(140058, 'itIT', '', '<Kiss sound>', 28153),
(140057, 'itIT', '<Kiss sound>', '', 28153),
(140056, 'itIT', 'Non temeremo l\'oscurità.', '', 28153),
(140055, 'itIT', 'Ti do il benvenuto fra noi.', '', 28153),
(140054, 'itIT', 'I miei saluti.', '', 28153),
(140053, 'itIT', 'Salve.', '', 28153),
(140052, 'itIT', 'Le mie ferite hanno bisogno di cure!', '', 28153),
(140051, 'itIT', 'Curami!', '', 28153),
(140050, 'itIT', 'Che la montagna ti dia sicurezza e conforto.', '', 28153),
(140049, 'itIT', 'Che i tuoi viaggi ti donino saggezza.', '', 28153),
(140048, 'itIT', 'Che la Madre Terra ti guidi sul tuo cammino.', '', 28153),
(140047, 'itIT', 'Arrivederci.', '', 28153),
(140046, 'itIT', 'Per l\'Orda!', '', 28153),
(140045, 'itIT', '', 'Per l\'Orda!', 28153),
(140044, 'itIT', 'Per l\'Alleanza!', '', 28153),
(140043, 'itIT', '', 'Per l\'Alleanza!', 28153),
(140042, 'itIT', 'Per l\'Orda!', '', 28153),
(140041, 'itIT', '', 'Segui i miei passi.', 28153),
(140040, 'itIT', 'Mi serve aiuto!', '', 28153),
(140039, 'itIT', 'Ho bisogno di aiuto!', '', 28153),
(140038, 'itIT', 'Si avvicina un pericolo!', '', 28153),
(140037, 'itIT', '<Kiss sound>', '', 28153),
(140036, 'itIT', '<Laughing sounds>', '', 28153),
(140035, 'itIT', '<Laughing>', '', 28153),
(140034, 'itIT', 'Inammissibile.', '', 28153),
(140033, 'itIT', 'Non credo proprio.', '', 28153),
(140032, 'itIT', 'No!', '', 28153),
(140031, 'itIT', 'D\'accordo... Jo\'chunga! Tengo bisogno che prepari nu rituale del sangue laggiù in chella capanna.', 'D\'accordo... Jo\'chunga! Tengo bisogno che prepari nu rituale del sangue laggiù in chella capanna.', 28153),
(140030, 'itIT', 'Presto. Nun teniamo tempo!', '', 28153),
(140029, 'itIT', 'Infatti.', '', 28153),
(140028, 'itIT', 'Proprio così.', '', 28153),
(140027, 'itIT', 'Shhh! Dobbiamo andarcene via. Tra i Troll del Sangue sono le donne a comandare.$B$BDammi l\'ordine di andare in chella tenda laggiù... tipo per preparare nu rituale del sangue.$B$BNessuno si farà domande se sarai tu a darmi ordini.', '', 28153),
(140026, 'itIT', 'Giusto.', '', 28153),
(140025, 'itIT', 'Fuoco!', '', 28153),
(140024, 'itIT', 'Bombardateli!', '', 28153),
(140023, 'itIT', 'Ho bisogno di mana.', '', 28153),
(140022, 'itIT', 'Mi serve del mana.', '', 28153),
(140021, 'itIT', '<Making a raspberry sound--Pfffthblth!>', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140020, 'itIT', '<Sighing sound>', '', 28153),
(140019, 'itIT', 'Ma certamente.', '', 28153),
(140018, 'itIT', 'È stato un piacere.', '', 28153),
(140017, 'itIT', 'Prego.', '', 28153),
(140016, 'itIT', 'Grazie mille.', '', 28153),
(140015, 'itIT', 'Non potrò mai ringraziarti abbastanza.', '', 28153),
(140014, 'itIT', 'Sono in debito con te.', '', 28153),
(140013, 'itIT', '<Train noises--chugga chugga choo choo!>', '', 28153),
(140012, 'itIT', 'Rimani in questo punto.', '', 28153),
(140011, 'itIT', 'Non allontanarti.', '', 28153),
(140010, 'itIT', 'Proprio così.', '', 28153),
(140009, 'itIT', 'Corretto.', '', 28153),
(140008, 'itIT', 'Sì.', '', 28153),
(140004, 'itIT', 'Ti invidio. Vedrai la nascita del nuovo Impero dei Troll di persona. Peccato che Rastakhan nun terrà chesto piacere.', '', 28153),
(140003, 'itIT', 'I Mogu hanno fatto la parte loro, allontanando le guardie del Re dal suo fianco.', '', 28153),
(140002, 'itIT', 'La profezia si avvererà. Chesta è solo na distrazione per lasciare che Zul agisca.', '', 28153),
(140001, 'itIT', 'Vilnak\'dor! Se Kao nun ha mentito, sarai tu il prossimo!', '', 28153),
(140000, 'itIT', '', 'Il Re?', 28153),
(139999, 'itIT', 'Non importa... La fine del vostro Re... arriverà...', '', 28153),
(139998, 'itIT', 'Sapevo che nun ci si poteva fidare di chel farabutto! La pagherà per chesto!', '', 28153),
(139997, 'itIT', 'Zul ci ha promesso un nuovo impero e noi ce lo prenderemo!', '', 28153),
(139996, 'itIT', 'Guardati intorno, Kao. Avete già perso! Gettate le armi e arrendetevi!', '', 28153),
(139995, 'itIT', 'Sono la potenza del tuono. Il terrore delle steppe. Non posso perdere!', '', 28153),
(139994, 'itIT', '', 'Siamo Zandalari! Nun ci arrenderemo mai!', 28153),
(139993, 'itIT', 'Zuldazar è nostra di diritto. Arrenditi e potrei garantirti una morte misericordiosa.', '', 28153),
(139992, 'itIT', 'Umpf. Speravo in una sfida migliore.', '', 28153),
(139991, 'itIT', 'Taz\'dingo! Per Re Rastakhan!', '', 28153),
(139990, 'itIT', '', 'Habutu, devi parlare a Re Rastakhan del tradimento di Zul. Di chesti bruti ci occupiamo io e $p.', 28153),
(139989, 'itIT', 'Arrival of the Zandalari Fleet', 'Arrival of the Zandalari Fleet', 28153),
(139988, 'itIT', 'Vediamo che cappelli hai.', 'Vediamo che cappelli hai.', 28153),
(139987, 'itIT', 'Sei $gtornato:tornata;?\n\nVoglio dire, sei $gtornato:tornata;!\n\nPrima che i passi tuoi mi spaventassero, stavo pulendo la locanda con Zulsan proprio come avevo detto... Si vede?', '', 28153),
(139986, 'itIT', 'Vediamo queste rocce!', 'Vediamo queste rocce!', 28153),
(139985, 'itIT', 'Io ha buona idea: tu compra due cappelli, tu indossa uno solo. Tu poi dà altro cappello ad amico, parente, conoscente. Io non giudica.', '', 28153),
(139984, 'itIT', 'Certo che io vende due cappelli assieme. Io ha due teste!$b$bVedo che tu solo ha una testa. Che sfortuna. Ma tu può tenere un cappello di scorta!', '', 28153),
(139983, 'itIT', 'Tu comprare cappelli? Io ha cappelli! Due al prezzo di due!', '', 28153),
(139982, 'itIT', 'Tu vuole essere grande e forte come Bol\'dar? Tu compra una di mie rocce, poi alza e spacca tutto con lei ogni giorno. Così forse tu diventa grande e forte.$b$bForse non grande e forte come me, però.', '', 28153),
(139981, 'itIT', 'Tu compra rocce di Bol\'dar! Io ha rocce migliori qui, vendo a buon prezzo!', '', 28153),
(139980, 'itIT', 'Ehi! Tu vuole roccia? Io ha belle rocce!', '', 28153),
(139979, 'itIT', 'Il Cuore di Sethraliss si illumina di rosso. Cosa significa?', 'Il Cuore di Sethraliss si illumina di rosso. Cosa significa?', 28153),
(139978, 'itIT', 'Dobbiamo rimanere forti.', 'Dobbiamo rimanere forti.', 28153),
(139977, 'itIT', 'Il Passo del Morto è facile da trovare. Ti basterà cercare alcune formazioni rocciose piuttosto sinistre a nord-ovest. Sarà divertente!', '', 28153),
(139976, 'itIT', 'Quando arriverai all\'accampamento, diventerai come loro. Però statt\' accuort\', chesto travestimento nun è perfetto. Eheheh...', '', 28153),
(139975, 'itIT', 'Le Troll del Sangue femmine stanno a capo delle squadre da battaglia, quindi dovrai sembrare una di loro. Fidati, funzionerà.', '', 28153),
(139974, 'itIT', 'Ti avviso, potrebbe farti nu poco male. Be\'... probabilmente assai male! Eheheh!', '', 28153),
(139727, 'itIT', 'Sono pronto a cominciare il rituale di trasformazione in Troll del Sangue.', 'Sono pronta a cominciare il rituale di trasformazione in Troll del Sangue.', 28153),
(139726, 'itIT', 'Ci sta qualche vudù davvero fetente accà.', '', 28153),
(139592, 'itIT', 'Se avete bisogno di me, mi troverete da qualche parte lontano da Izarn.', '', 28153),
(139567, 'itIT', 'Vedo che vi siete fatti nuovi amici durante l\'assenza mia.', '', 28153),
(139482, 'itIT', '', 'Difendi chesto incrocio! Dobbiamo impedire ai Mogu di avanzare ancora.', 28153),
(139443, 'itIT', 'Il tuo amico può andare, ma io lo terrei d\'occhio se fossi in te.', '', 28153),
(139410, 'itIT', 'Subito.', '', 28153),
(139408, 'itIT', 'La città è irrequieta. Dobbiamo tenerti al sicuro!', '', 28153),
(139406, 'itIT', 'Mio Re, nun possiamo lasciare il fianco tuo.', '', 28153),
(139401, 'itIT', 'Hai avuto la tua occasione. Finché regnerò, gli Zandalari nun terranno paura delle creature tue.', '', 28153),
(139397, 'itIT', 'I soldati miei perlustreranno la città alla ricerca di altri.', '', 28153),
(139391, 'itIT', 'Ti devo la mia vita. Troviamoci dentro il tempio, qui non siamo al sicuro.', '', 28153),
(139390, 'itIT', '', 'Ehi! O parli o ci aiuti. Andiamo a cacciare un po\' in acqua!', 28153),
(139389, 'itIT', 'Fratello Therold! Ser Sacraonda! Siete arrivati proprio al momento giusto! Ci serve il vostro aiuto.', '', 28153),
(139388, 'itIT', 'Raggiungimi insieme alli altri quando terrai le cose mie. Ci stanno preparativi da fare.', '', 28153),
(139387, 'itIT', 'Ehi tu! Vieni accà, prima che i bruti tornino per finirmi!', '', 28153),
(139386, 'itIT', 'Potranno pure pigliare chesta terra, ma non terranno mai l\'anima nostra.', '', 28153),
(139385, 'itIT', 'Grazie. Troverò un modo per uscire di qui.', 'Grazie. Troverò un modo per uscire di qui.', 28153),
(139384, 'itIT', 'Da chesta parte! Proteggeremo i bijou di Kaza\'jin con le vite nostre.', 'Da chesta parte! Proteggeremo i bijou di Kaza\'jin con le vite nostre.', 28153),
(139383, 'itIT', '', 'Preparatevi, Chigliatori! Queste creature sono diverse da qualsiasi altra cosa affrontata finora!', 28153),
(139375, 'itIT', 'Guarda dove metti i piedi. I ranishu mangiano tutto... letteralmente.', '', 28153),
(139374, 'itIT', '', 'Taji dovrebbe trovarsi in cima alla collina a sud, se lo stai cercando.', 28153),
(139372, 'itIT', 'Troviamoci alla carovana quando hai finito. Io inizierò le riparazioni.', '', 28153),
(139371, 'itIT', 'Congratulazioni, $p. Sei $gsopravvissuto:sopravvissuta; al tuo incontro con i ranishu. In pochi sono così fortunati.', '', 28153),
(139370, 'itIT', 'Dura e resistente... Questa legna sarà perfetta per riparare la carovana.', '', 28153),
(139369, 'itIT', 'Le riparazioni procedono bene, grazie alla legna di qualità che hai aiutato a recuperare.', '', 28153),
(139368, 'itIT', '', 'Va bene. Mmm... eccola! Pergamena dell\'Invisibilità, questa andrà bene.', 28153),
(139367, 'itIT', '', 'Concentratevi! Nun è il momento delle storielle!', 28153),
(139366, 'itIT', 'Non ti ho mai raccontato quella storia? Oh, è incredibile! Vediamo, da dove posso cominciare...', '', 28153),
(139365, 'itIT', '', 'Oh... pare che questa sia scritta nel linguaggio degli Dei Antichi. Dove hai trovato un oggetto del genere?', 28153),
(139364, 'itIT', 'No! L\'hai letta, almeno? Però tienila per dopo. Ci servirà quando avremo finito con tutto questo.', '', 28153),
(139363, 'itIT', '', 'Vediamo... Pergamena dell\'Eterno Ritorno... può essere utile?', 28153),
(139362, 'itIT', 'Ti prego, puoi aiutarmi a tornare da Alby? Sarà preoccupatissimo.', '', 28153),
(139361, 'itIT', 'Quando avrai salvato gli altri, raggiungimi sull\'altura a est per affrontare la Signora delle Maree!', '', 28153),
(139360, 'itIT', '', 'Ah, potrebbe volerci tutto il giorno! Principessa, non hai idea di quante pergamene ha.', 28153),
(139358, 'itIT', 'Dobbiamo unirci agli altri!', 'Dobbiamo unirci agli altri!', 28153),
(139357, 'itIT', 'Proteggete la flotta!', 'Proteggete la flotta!', 28153),
(139356, 'itIT', 'Il Porto da Guerra nun deve cadere!', 'Il Porto da Guerra non deve cadere!', 28153),
(139355, 'itIT', 'Nel nome di Re Rastakhan!', 'Nel nome di Re Rastakhan!', 28153),
(139354, 'itIT', 'Ah! Sapevo di averla da qualche parte. Questa ci permetterà di passare alle spalle dei Troll del Sangue. Restatemi vicini.', '', 28153),
(139353, 'itIT', 'Ai miei tempi, avrei potuto occuparmi da solo di un\'intera legione di quei vermi. Sono venuti di notte e mi hanno sopraffatto! I loro ordini, in poche parole, sembrano dire \"Presto! Azshara vuole il suo trofeo!\"', '', 28153),
(139351, 'itIT', 'Dicci tutto quello che puoi, mio signore. Ci servono tutte le informazioni possibili.', '', 28153),
(139350, 'itIT', 'I Naga stanno cercando qualcosa qui, sicuramente per conto di Azshara. Dobbiamo fermarli prima che riescano nel loro compito.', '', 28153),
(139348, 'itIT', 'Un... un culto ha preso possesso del villaggio a causa della mia... Incompetenza.', '', 28153),
(139347, 'itIT', 'La senti? È la chiamata di Bwonsamdi! L\'eternità è vicina!', 'La senti? È la chiamata di Bwonsamdi! L\'eternità è vicina!', 28153),
(139346, 'itIT', 'Mio signore! Sei al sicuro? Cos\'hai scoperto?', '', 28153),
(139345, 'itIT', 'Brannon!', '', 28153),
(139344, 'itIT', 'La voce... ci sta chiamando... dobbiamo obbedire!', 'La voce... ci sta chiamando... dobbiamo obbedire!', 28153),
(139343, 'itIT', 'Cos\'è accaduto? Stavo male nel letto mio... e mo\'... dove sto?', 'Cos\'è accaduto? Stavo male nel letto mio... e mo\'... dove sto?', 28153),
(139341, 'itIT', 'La mia vita... per l\'Imperatore...', '', 28153),
(139339, 'itIT', 'Ho deluso i miei sottoposti. Non sono riuscito a imporre la mia autorità e loro hanno scelto un\'altra direzione.', '', 28153),
(139338, 'itIT', 'Mio zio mi ha messo alla guida di questo villaggio per fare un po\' di esperienza. Ma... un culto? Come si fa ad affrontare un culto?!?', '', 28153),
(139336, 'itIT', 'Mille battaglie... mille vittorie...', '', 28153),
(139335, 'itIT', 'Il tuono... non può... essere zittito.', '', 28153),
(139334, 'itIT', 'Grazie per avermi salvato. Conway e i suoi uomini hanno colpito così velocemente, e... non me l\'aspettavo.', '', 28153),
(139333, 'itIT', 'La tempesta... si dissolve...', '', 28153),
(139329, 'itIT', 'La nostra è la volontà... degli dei...', '', 28153),
(139328, 'itIT', 'Anche la pietra... si spezza...', '', 28153),
(139327, 'itIT', 'La carne... è debole...', '', 28153),
(139326, 'itIT', 'L\'Impero... non cadrà... mai...', '', 28153),
(139317, 'itIT', 'Preparati a vivere in catene!', '', 28153),
(139316, 'itIT', 'Assaggia la furia della tempesta!', '', 28153),
(139315, 'itIT', 'Inchinati al mio cospetto!', '', 28153),
(139314, 'itIT', 'Sono il potere manifesto!', '', 28153),
(139312, 'itIT', 'Gli Zandalari onoreranno il loro patto... o moriranno!', '', 28153),
(139311, 'itIT', 'Ti schiaccerò il cranio con le mani!', '', 28153),
(139309, 'itIT', 'Riforgeremo il nostro impero con le tue ossa!', '', 28153),
(139308, 'itIT', 'Tu ci servirai!', '', 28153),
(139307, 'itIT', 'Brannon, non sei altro che uno stupido ragazzino. Ho fatto un patto e guiderò questo villaggio al successo senza di te!', 'Brannon, non sei altro che uno stupido ragazzino. Ho fatto un patto e guiderò questo villaggio al successo senza di te!', 28153),
(139306, 'itIT', 'Abbiamo bisogno di risorse per respingerli. Sparpagliatevi e portatemi ferro e legna!', '', 28153),
(139305, 'itIT', '', 'Che cosa sai dei segreti dell\'isola? Dimmelo!', 28153),
(139304, 'itIT', 'I mari saranno sempre sotto il nossstro controllo!', '', 28153),
(139303, 'itIT', 'Ti affogheremo sotto le onde!', '', 28153),
(139298, 'itIT', '', 'Va bene, io torno alla carovana. Ci vediamo, $p!', 28153),
(139295, 'itIT', 'Sì. Grazie per il vostro aiuto, Kona e $p. Sono in debito con voi.', '', 28153),
(139294, 'itIT', '', 'Avremmo combattuto con te fino alla fine, Sumber.', 28153),
(139293, 'itIT', 'Sono felice di sapere che Thun\'ka l\'Avvizzitore sia sfuggito al suo controllo. Un elementale così potente sarebbe stato... problematico.', '', 28153),
(139292, 'itIT', 'Quindi è stato uno Sciamano a causare tutto questo? Grazie per averlo ucciso.', '', 28153),
(139291, 'itIT', 'Ha-haaa! Prendete questo, feccia dell\'Orda!', '', 28153),
(139290, 'itIT', 'Il rituale mio sta quasi completo! Ascolta il volere mio, Thun\'ka l\'Avvizzitore!', '', 28153),
(139288, 'itIT', '', 'D\'accordo, fa\' pure! Tsk! Come se l\'avesse costruito lui questo posto.', 28153),
(139287, 'itIT', 'Ma cosa ne vuoi sapere tu! Resta qui se vuoi, noi andiamo avanti. Conosco ogni angolo di questa zona.', '', 28153),
(139286, 'itIT', 'Quelle cose saranno la tua fine! Sono più crudeli dei Troll del Sangue che abbiamo incontrato nell\'ultimo pellegrinaggio.', '', 28153),
(139285, 'itIT', 'Bah! Non sei il capo di nessuno. Daremo a quei macellai una bella lezione!', '', 28153),
(139284, 'itIT', '', 'Tu dovresti rimanere qui e aiutarci a elaborare un piano. Non sei in grado di affrontare i Troll del Sangue.', 28153),
(139283, 'itIT', 'Kisha, Lashk. Penseremo noi a questi insetti che stanno facendo a pezzi Torga.', '', 28153),
(139282, 'itIT', '', 'Era ora! Pensavo fossimo gli unici a cui importasse della morte di Torga.', 28153),
(139281, 'itIT', 'Ma guarda un po\'. Gli altri sono finalmente usciti dal loro guscio e stanno venendo qui.', '', 28153),
(139250, 'itIT', '|cffffff00+$1i Ferro|r', '|cffffff00+$1i Ferro|r', 28153),
(139241, 'itIT', 'Continuate a combattere!', '', 28153),
(139240, 'itIT', '', 'Siamo una grande squadra, non è vero?', 28153),
(139204, 'itIT', '', 'Ne ho ucciso un altro, Sumber! Sono già a ventisette!', 28153),
(139198, 'itIT', '|cffffff00+$1i Legna|r', '|cffffff00+$1i Legna|r', 28153),
(139168, 'itIT', 'Sì... combatti... resisti... G\'huun ha fame... della tua... sofferenza.', '', 28153),
(139167, 'itIT', 'Proverai... a fermare G\'huun. Fallirai... e soffrirai.', '', 28153),
(139165, 'itIT', 'Vieni.', '', 28153),
(139164, 'itIT', 'Fermati.', '', 28153),
(139163, 'itIT', 'Officina pronta all\'azione!', '', 28153),
(139162, 'itIT', 'L\'Officina è pronta. Costruite dei Demolitori e mostriamo all\'Alleanza quanto sono fragili le loro mura.', '', 28153),
(139097, 'itIT', '<$n cosparge i suoi artigli di veleno!>', '<$n cosparge i suoi artigli di veleno!>', 28153),
(139080, 'itIT', 'Tu non immagini... cosa si nasconde sotto...', '', 28153),
(139079, 'itIT', 'Il nostro potere vi spezzerà!', '', 28153),
(139078, 'itIT', 'Inchinatevi ai vostri nuovi padroni!', '', 28153),
(139077, 'itIT', 'Il nostro dominio... è l\'unica via...', '', 28153),
(139073, 'itIT', 'Le stesse tempeste rispondono alla mia chiamata!', '', 28153),
(139072, 'itIT', 'Te ne pentirai!', '', 28153),
(139071, 'itIT', 'Ho più potere di quanto tu possa mai sognare!', '', 28153),
(139070, 'itIT', 'Ti avevo avvertito!', '', 28153),
(139065, 'itIT', 'Le nostre parole sono piene di potere. Questa terra sarà nostra!', '', 28153),
(138870, 'itIT', '', 'La gente della Conca degli Impennatori è in debito con te, $C.\n\nTu pensa a Dama Crestabianca, noi elimineremo ciò che rimane della congrega.', 28153),
(138865, 'itIT', '', 'Sei $gtornato:tornata;! Dimmi che hai abbattuto la Matrona.', 28153),
(138864, 'itIT', '', 'Non siamo riusciti a metter piede nella miniera da quando quell\'energia è cominciata a fuoriuscire da lì.\n\nQuel costrutto di vimini sotto il tuo controllo potrebbe essere la nostra unica speranza.', 28153),
(138859, 'itIT', '', 'Apprezziamo il tuo aiuto, $C. La situazione sembrava alquanto grigia prima del tuo arrivo.', 28153),
(138853, 'itIT', 'Andrò a esplorare meglio la città. Speriamo che la gente sia al sicuro.', '', 28153),
(138852, 'itIT', 'Ce l\'hai fatta! Hai preso il controllo dello Schiavo Malovolto!', '', 28153),
(138849, 'itIT', 'Sparisci!', '', 28153),
(138848, 'itIT', '', 'Oh... sei felice ora? Mi muovo abbastanza per i tuoi gusti?', 28153),
(138847, 'itIT', '', 'Secondo te sono ferma? Ahahah, va bene così? Vale come pellegrinaggio?', 28153),
(138841, 'itIT', 'Avvicinati, $gpiccolo:piccola; $PR. Vorrei scambiare due parole con te.', '', 28153),
(138837, 'itIT', '', 'Andrò a chiedere in giro. Ci vediamo in città!', 28153),
(138836, 'itIT', '', 'Hai davvero delle grandi qualità, $p. Mi auguro di rivederti presto.', 28153),
(138833, 'itIT', 'Dobbiamo rimanere forti.', '', 28153),
(138832, 'itIT', 'Va\', $n! Proteggi la gente di Drustvar!', '', 28153),
(138831, 'itIT', 'State calmi, figli del mare. Dobbiamo porre la nostra fede nelle acque per scoprire una cura.', '', 28153),
(138830, 'itIT', '', 'Se ti capita di imbatterti in altre terribili streghe, da\' loro un pugno ben assestato da parte mia, $gcampione:campionessa;!', 28153),
(138829, 'itIT', '', 'Siamo felici di vedere che ci sono ancora dei campioni come te, $n.', 28153),
(138824, 'itIT', '', 'Taji e Kona dovrebbero essere già tornati. Deve essere successo qualcosa.', 28153),
(138823, 'itIT', 'La nostra priorità dovrebbe essere recuperare i rifornimenti. Dobbiamo mangiare.', '', 28153),
(138822, 'itIT', 'O grande mare, dona sollievo agli infermi del Pontile di Pescagrossa. Aiutaci a scoprire la fonte della malattia che ci affligge!', '', 28153),
(138821, 'itIT', 'Siete fortunati che $n vi abbia trovato e salvato.', '', 28153),
(138820, 'itIT', 'Continuate così e i mesi diventano tre!', '', 28153),
(138819, 'itIT', 'Ma siamo degli esploratori!', '', 28153),
(138818, 'itIT', '', 'Ohhh!', 28153),
(138817, 'itIT', 'Oh, e dai, nonno!', '', 28153),
(138816, 'itIT', 'Siete in punizione per due mesi!', '', 28153),
(138815, 'itIT', '', 'Sissignore!', 28153),
(138814, 'itIT', 'Sì, nonno.', '', 28153),
(138813, 'itIT', 'Sì, nonno.', '', 28153),
(138812, 'itIT', 'Lo sapete che voi bambini non dovete uscire di nascosto!', '', 28153),
(138811, 'itIT', 'Non voglio mai più sentire quel canto!', 'Non voglio mai più sentire quel canto!', 28153),
(138810, 'itIT', 'Finalmente! Libero!', 'Finalmente! Libera!', 28153),
(138809, 'itIT', 'Dannazione, quella canzone mi rimarrà in testa tutto il giorno.', 'Dannazione, quella canzone mi rimarrà in testa tutto il giorno.', 28153),
(138808, 'itIT', 'Grazie, $geroe:eroina;!', 'Grazie, $geroe:eroina;!', 28153),
(138807, 'itIT', 'Morte... finalmente... mo\' tocca a te... fermare G\'huun...', '', 28153),
(138804, 'itIT', 'Credi di tenere forza a sufficienza per fermare G\'huun? Lo scopriremo nell\'arena mia!', '', 28153),
(138803, 'itIT', 'Nazesh è stata piuttosto maleducata. La tua lezione di buone maniere dovrà essere dura... e permanente, temo. Usa la pergamena, ti aiuterà!', '', 28153),
(138802, 'itIT', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_EARTH.BLP:20|t Il sangue di $n è stato |cFFFF0000|Hspell:255582|h[corrotto]|h|r!', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_EARTH.BLP:20|t Il sangue di $n è stato |cFFFF0000|Hspell:255582|h[corrotto]|h|r!', 28153),
(138801, 'itIT', '', '|TInterface\\Icons\\SPELL_HOLY_PURIFY.BLP:20|t $n lancia |cFFFF0000|Hspell:255577|h[Trasfusione]|h|r!', 28153),
(138800, 'itIT', '', '$n si cosparge le mani di oro.', 28153),
(138799, 'itIT', 'Prima qui c\'erano solo piccoli Murloc, ma poi venne la tempesta e l\'invasione dei Naga. Mi hanno catturato per primo, il che è piuttosto imbarazzante.', '', 28153),
(138798, 'itIT', 'Libera lo spirito mio, ti prego!', '', 28153),
(138797, 'itIT', 'Basta! Nun voglio più soffrire!', '', 28153),
(138796, 'itIT', 'Lasciami andare con Bwonsamdi, ti prego!', '', 28153),
(138795, 'itIT', 'Fa male! Ti prego, poni fine chesta sofferenza!', '', 28153),
(138794, 'itIT', 'Ti prego, poni fine alle sofferenze mie!', '', 28153),
(138793, 'itIT', 'Nun riesco a controllarmi!!!', '', 28153),
(138792, 'itIT', 'Ti prego, poni fine alle sofferenze mie!', '', 28153),
(138791, 'itIT', '', 'Libera lo spirito mio, ti prego!', 28153),
(138790, 'itIT', '', 'Basta! Nun voglio più soffrire!', 28153),
(138789, 'itIT', '', 'Lasciami andare con Bwonsamdi, ti prego!', 28153),
(138788, 'itIT', '', 'Fa male! Ti prego, poni fine chesta sofferenza!', 28153),
(138787, 'itIT', '', 'Ti prego, poni fine alle sofferenze mie!', 28153),
(138786, 'itIT', '', 'Nun riesco a controllarmi!!!', 28153),
(138785, 'itIT', '', 'Ti prego, poni fine alle sofferenze mie!', 28153),
(138784, 'itIT', '', 'Sento il richiamo delli elementi e vado ovunque il vento mi porti.', 28153),
(138783, 'itIT', 'Come ci sono finiti quei cosi nel mio stomaco?', 'Come ci sono finiti quei cosi nel mio stomaco?', 28153),
(138782, 'itIT', 'Non... Non mi sento bene...', 'Non... Non mi sento bene...', 28153),
(138781, 'itIT', 'Il mio stomaco non stava così bene da giorni!', 'Il mio stomaco non stava così bene da giorni!', 28153),
(138779, 'itIT', 'Quei cosi erano dentro di me?', 'Quei cosi erano dentro di me?', 28153),
(138776, 'itIT', '', 'A meno che tu non voglia dare una mano, ti consiglio di andartene.', 28153),
(138775, 'itIT', '', 'Ti do il benvenuto alla Conca degli Impennatori. Perdona il caos, ma abbiamo un serio problema di streghe al momento.', 28153),
(138774, 'itIT', 'Pensavo che gli spiriti mi avrebbero ucciso! Grazie!', 'Pensavo che gli spiriti mi avrebbero uccisa! Grazie!', 28153),
(138773, 'itIT', 'Grazie. Appena avrò trovato il mio cucciolo, lascerò questo posto maledetto!', 'Grazie. Appena avrò trovato il mio cucciolo, lascerò questo posto maledetto!', 28153),
(138772, 'itIT', 'Grazie!', 'Grazie!', 28153),
(138771, 'itIT', 'Non ho mai visto degli spiriti del genere prima d\'ora. Basta, me ne vado!', 'Non ho mai visto degli spiriti del genere prima d\'ora. Basta, me ne vado!', 28153),
(138770, 'itIT', 'Grazie per avermi salvato.', 'Grazie per avermi salvata.', 28153),
(138769, 'itIT', 'Grazie, $gstraniero:straniera;. Credevo fosse giunta la mia ora.', 'Grazie, $gstraniero:straniera;. Credevo fosse giunta la mia ora.', 28153),
(138768, 'itIT', 'Perdona l\'intrusione. Tengo na richiesta urgente da fare.', '', 28153),
(138767, 'itIT', 'Chi sei? Nun sei nu Troll del Sangue... o li spiriti ti avrebbero fatto a pezzi.', '', 28153),
(138766, 'itIT', 'Aspetta... Qualcosa si sta avvicinando.', '', 28153),
(138765, 'itIT', 'Cheste rovine sono sacre per Bwonsamdi. I Troll del Sangue nun ci seguiranno accà.', '', 28153),
(138762, 'itIT', 'Non ne ho molte, ma sono tutte a tua disposizione.', '', 28153),
(138760, 'itIT', '', 'L\'Orda si ritira di nuovo? Quale sarebbe la sua tattica?', 28153),
(138759, 'itIT', 'Non possiamo lasciar fuggire la Capoguerra: catturarla è l\'unico modo per vincere questa guerra.', '', 28153),
(138758, 'itIT', 'Non sei nulla...', '', 28153),
(138757, 'itIT', 'Quesssta baia appartiene alla Signora delle Maree Nazesh! Scopriremo cosa si nasssconde a Zuldazar!', '', 28153),
(138756, 'itIT', 'Eheh. Carne fresca.', 'Eheh. Carne fresca.', 28153),
(138755, 'itIT', 'Non temere, quella parte la saltiamo. Conosco un posto dove nasconderci mentre recuperiamo informazioni.', '', 28153),
(138754, 'itIT', 'Tormento. Intendeva tormento.', '', 28153),
(138753, 'itIT', 'Va bene, entra e fai rapporto per... l\'\"orientamento\". Eheh.', '', 28153),
(138752, 'itIT', 'Mmm... be\', avete portato i cappelli, almeno...', '', 28153),
(138751, 'itIT', 'Vogliamo unirci agli Incursori Marferreo. Abbiamo portato i cappelli.', 'Vogliamo unirci agli Incursori Marferreo. Abbiamo portato i cappelli.', 28153),
(138749, 'itIT', 'Chesto luogo è sacro. Proteggerlo per l\'eternità è la missione mia.', '', 28153),
(138748, 'itIT', 'Molti pellegrini sostavano accà nel loro viaggio verso la Necropoli.\n\nPerò nun si vede più nessuno nelli ultimi tempi... Nun va bene. Nun va per niente bene.', '', 28153),
(138747, 'itIT', 'Ho sorvegliato chesto santuario da quando è stato costruito e continuerò a farlo fin quando nun crollerà.', '', 28153),
(138746, 'itIT', 'Tutti coloro diretti alla Necropoli sono i benvenuti accà.', '', 28153),
(138745, 'itIT', 'Per volere di Bwonsamdi, offro riposo ai viaggiatori che si avventurano nel tempio suo.', '', 28153),
(138744, 'itIT', 'Sembra tutto a posto. Avvisiamo il reclutatore che siamo venuti come volontari.', '', 28153),
(138743, 'itIT', 'Mettiti il cappello. Non puoi sembrare un lupo di mare senza cappello!', '', 28153),
(138742, 'itIT', 'Mi servono soltanto un paio di minuti, Rosaline. Con l\'aiuto degli arpioni potenziati, trionferai sulla cava!', '', 28153),
(138741, 'itIT', '', 'Okri, come stiamo coi rifornimenti? Voglio tornare in mare il prima possibile. Non c\'è tempo da perdere.', 28153),
(138740, 'itIT', 'Sì? Cosa vuoi?', 'Sì? Cosa vuoi?', 28153),
(138739, 'itIT', 'Mi tocca tornare a Boralus a mani vuote, per ora. Raggiungimi lì con la pergamena e penseremo al tuo compenso.', '', 28153),
(138738, 'itIT', 'Ricorda, è importante: la pergamena che ti serve è sigillata con cera verde. DEVE essere verde!', '', 28153),
(138737, 'itIT', 'La persona che cerchi si chiama Carentan. Il suo negozio è di sopra, al confine meridionale della città.', '', 28153),
(138734, 'itIT', 'Perché mi mordi? Nun ci sta carne sulle ossa mie.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(138733, 'itIT', 'Mangiati chesto, stupido serpente!', '', 28153),
(138732, 'itIT', 'Mi piace lo spirito combattivo tuo. Risparmialo per i Sethrak!', '', 28153),
(138731, 'itIT', 'Ah! Mi avevi quasi fregato.', '', 28153),
(138730, 'itIT', 'Rezan posa il suo sguardo su $n e lancia |TInterface\\Icons\\ABILITY_MOUNT_FOSSILIZEDRAPTOR.BLP:20|t|cFFFF0000|Hspell:255421|h[Voracità]|h|r!', '', 28153),
(138729, 'itIT', 'Il Capitano Gulnaku pagherà per chello che ha fatto.', '', 28153),
(138728, 'itIT', 'Grazie per avermi liberato... in cambio, risparmierò la vita tua.', '', 28153),
(138725, 'itIT', 'Guarda dove scavi! Stavo dormendo laggiù!', 'Guarda dove scavi! Stavo dormendo laggiù!', 28153),
(138724, 'itIT', 'Gli spiriti in quest\'area non resteranno indifferenti mentre distruggi la loro terra...', '', 28153),
(138723, 'itIT', 'Non credo sia una buona idea lanciare delle bombe su quelle ossa!', '', 28153),
(138722, 'itIT', 'Ho chiesto a molti Troll informazioni su Xibala, e ho sempre ricevuto una storia differente, indipendentemente dai miei metodi di interrogazione.\n\nAlcuni dicono che Xibala faccia imputridire i corpi della gente.\n\nAltri che chiunque lo guardi si trasforma in uno scheletro vivente.\n\nAltri ancora che si nasconde nelle ombre ed esce la notte per divorare le persone nel sonno.\n\nO anche che attenda presso le strade, facendo tossire sangue ai malcapitati viaggiatori fino alla morte.\n\nNon mi stupisce che i locali se ne stiano alla larga!', '', 28153),
(138721, 'itIT', 'È passato così tanto tempo da quando avevo messo gli occhi su questo luogo. Anche allora i locali lo temevano o evitavano...\n\nQui dimorano spiriti crudeli, $n, meglio non disturbarli.', '', 28153),
(138717, 'itIT', 'Nun dovresti vagare tra i vicoli di Zem\'lan. Kiffa, pensaci tu!', 'Nun dovresti vagare tra i vicoli di Zem\'lan. Kiffa, pensaci tu!', 28153),
(138716, 'itIT', 'L\'Orda... mi vendicherà...', '', 28153),
(138715, 'itIT', 'Questo sito appartiene al Reliquiario. L\'Alleanza non è bene accetta!', '', 28153),
(138709, 'itIT', '', 'Ci potrebbero essere danni collaterali, ma sono certa che poi riusciremo a rimettere i pezzi insieme. Forse dovremo chiamare qualche assistente ricercatore in più...', 28153),
(138707, 'itIT', 'Ehi, Zalnon\'mak, il capello tuo è davvero comodo. Credo che me lo terrò!', '', 28153),
(138706, 'itIT', 'Chi vuole farsi na bevuta con me?', '', 28153),
(138705, 'itIT', 'Perché lavorate tutti così tanto? Lo sapete che viviamo per sempre, vero?', '', 28153),
(138704, 'itIT', 'Ehi, Senjilak! Attento a voltare le spalle a Xunanji, ti ruberà tutto quanto!', '', 28153),
(138703, 'itIT', 'Ehi, Segazea, il servo tuo sta facendo puzzare tutto quanto. Portalo via!', '', 28153),
(138702, 'itIT', 'Xulai, sei la zavorra più pesante che mi sia mai trascinato dietro!', '', 28153),
(138701, 'itIT', 'Tieni sete? Peccato!', '', 28153),
(138700, 'itIT', 'Datevi na mossa, smidollati. Mi serve più grog!', '', 28153),
(138699, 'itIT', '$n ha conquistato la Miniera dei Baffosecco!', '$n ha conquistato la Miniera dei Baffosecco!', 28153),
(138698, 'itIT', '', 'Non provare più a scappare in quel modo. Hai capito? Ora, diamoci una mossa, abbiamo del lavoro da fare.', 28153),
(138691, 'itIT', 'Io... Calmatevi. Calmatevi tutti! Stiamo facendo il possibile. Troveremo la causa... e una cura!', '', 28153),
(138690, 'itIT', '', 'Devi aiutarci, Therold! Ci servono risposte! Ci serve una cura!', 28153),
(138689, 'itIT', 'Cosa sta causando questa malattia?', '', 28153),
(138688, 'itIT', '', 'I nostri bambini si stanno ammalando!', 28153),
(138687, 'itIT', 'Ti aspetterò per la rivincita...', 'Ti aspetterò per la rivincita...', 28153),
(138686, 'itIT', 'È tutto il giorno che bevo per chesto...', 'È tutto il giorno che bevo per chesto...', 28153),
(138679, 'itIT', 'Gulnaku nun sarà felice di tutto chesto.', 'Gulnaku nun sarà felice di tutto chesto.', 28153),
(138678, 'itIT', 'Sta\' alla larga dalla mappa mia!', 'Sta\' alla larga dalla mappa mia!', 28153),
(138676, 'itIT', 'Portate na capa di Vulpera e terrete no sconto sul primo acquisto vostro!', '', 28153),
(138675, 'itIT', 'Nu boccale di grog al giorno toglie lo smog di torno!', '', 28153),
(138674, 'itIT', 'Nun si tengono mai troppe bende per occhi!', '', 28153),
(138673, 'itIT', 'Pare Zem\'lan in persona con l\'ultimo copricapo di Spezzatino!', '', 28153),
(138672, 'itIT', 'Yoksa è il migliore con i mojo! Acquistate oggi le nuove pozioni sue!', '', 28153),
(138671, 'itIT', 'Nuove spade in vendita! Estremamente affilate!', '', 28153),
(138670, 'itIT', 'Oggi combatterai al fianco di na temibile tigre!', '', 28153),
(138669, 'itIT', 'Carne fresca di Vulpera, appena cucinata!', '', 28153),
(138668, 'itIT', 'Oggo a metà prezzo per il resto della giornata...', 'Oggo a metà prezzo per il resto della giornata...', 28153),
(138666, 'itIT', '', 'Posso farmi strada da sola. Fai attenzione.', 28153),
(138664, 'itIT', 'Metti a posto chesto casino prima di andartene.', 'Metti a posto chesto casino prima di andartene.', 28153),
(138663, 'itIT', 'Rendiamo chesta locanda la dimora tua... per sempre!', 'Rendiamo chesta locanda la dimora tua... per sempre!', 28153),
(138662, 'itIT', 'Salve, $C. Ci serve il tuo aiuto per un piccolissimo problema.', '', 28153),
(138661, 'itIT', 'Siamo vincolati al volere di Zem\'lan, per sempre.', 'Siamo vincolati al volere di Zem\'lan, per sempre.', 28153),
(138660, 'itIT', 'Ho dato tutto quanto per proteggere la ciurma mia. Nun andrai più avanti di così!', 'Ho dato tutto quanto per proteggere la ciurma mia. Nun andrai più avanti di così!', 28153),
(138659, 'itIT', 'Torniamo dalla tomba, pronti a combattere.', 'Torniamo dalla tomba, pronti a combattere.', 28153),
(138658, 'itIT', 'Nun ti ho già $gacciso:accisa;? O eri forse $gstato:stata; tu ad accidere me?', 'Nun ti ho già $gacciso:accisa;? O eri forse $gstato:stata; tu ad accidere me?', 28153),
(138655, 'itIT', 'Mi ciberò della tua carne e offrirò la tua anima al mio padrone!', '', 28153),
(138652, 'itIT', 'Ti strapperò la carne dalle ossa!', '', 28153),
(138651, 'itIT', 'Combatti bene per essere un patetico terrestre... ma non servirà!', '', 28153),
(138650, 'itIT', 'Corri pure quanto vuoi. Tengo tutta l\'eternità per darti la caccia.', 'Corri pure quanto vuoi. Tengo tutta l\'eternità per darti la caccia.', 28153),
(138649, 'itIT', 'Nessuno ruberà il tesoro mio! Né tu, né Zem\'lan, né nessun altro!', 'Nessuno ruberà il tesoro mio! Né tu, né Zem\'lan, né nessun altro!', 28153),
(138644, 'itIT', 'L\'alba del nostro impero sarà la vostra estinzione!', 'L\'alba del nostro impero sarà la vostra estinzione!', 28153),
(138641, 'itIT', 'La tua morte sarà di lezione per gli altri!', 'La tua morte sarà di lezione per gli altri!', 28153),
(138634, 'itIT', 'Nun temere, $PR, nun combatterò con te.\n\nÈ Zem\'lan che mi ha fatto chesto. L\'ha fatto a tutti noi, che lo volessimo o no.\n\nGuardami...\n\n<Guntha il Gentile sospira pesantemente.>\n\nVuoi qualcosa da bere?', '', 28153),
(138633, 'itIT', 'Se vuoi sopravvivere a Vol\'dun, devi guardare la morte nelli occhi ogni istante... e nun perderla mai di vista.', '', 28153),
(138631, 'itIT', 'Niente preda, niente paga.', 'Il tesoro tuo... mo\' è \'o mio!', 28153),
(138628, 'itIT', 'La maledizione ci rende forti!', 'Ho sacrificato tutto per Zem\'lan.', 28153),
(138627, 'itIT', 'Zem\'lan nun dovrà più patire la presenza dei vivi.', 'Se nun fai parte della ciurma, sei morto!', 28153),
(138625, 'itIT', 'Ho difeso chesto porto per tantissimi anni.', 'Chisto porto è nostro!', 28153),
(138624, 'itIT', 'Sta\' accuort\' là fuori! Nun sottovalutare mai i Sethrak...', '', 28153),
(138623, 'itIT', '', 'Eee... fatto! Grazie per l\'aiuto.', 28153),
(138622, 'itIT', '', 'Quasi finito...', 28153),
(138621, 'itIT', '', 'Ho finalmente raggiunto le vere reliquie, ora che l\'altra spazzatura è fuori dai piedi. Non dovrebbe volerci molto.', 28153),
(138620, 'itIT', '', 'E questa collezione d\'ossa deve essere opera di Birch, a giudicare dai segni dei denti.', 28153),
(138619, 'itIT', '', 'Un \"prototipo originale di Sfornamicce\". Che spreco di metallo, ma non c\'è posto per la spazzatura.', 28153),
(138618, 'itIT', '', 'Alcuni dei nostri ritrovamenti più preziosi sono stati lasciati in questa cassa. Guardami le spalle, $C, mentre cerco di salvare il più possibile.', 28153),
(138615, 'itIT', 'Non abbandoneremo questo tempio.', '', 28153),
(138589, 'itIT', 'Fintanto che il tempio rimarrà in piedi, potrai trovare rifugio tra le sue mura.', '', 28153),
(138568, 'itIT', '', 'Oooh! Appena riprendo il fiato ti prenderò a calci per quello che hai detto!', 28153),
(138567, 'itIT', 'Aspetta! Non sono un cane! Come fai a correre con quelle gambe tozze che ti ritrovi? Credevo fossi in grado solo di rotolare giù dai pendii.', '', 28153),
(138566, 'itIT', '', 'Un\'apertura! Ti farò uscire, Birch! Ma non riuscirai a prendermi, anche se sei in parte cane!', 28153),
(138556, 'itIT', 'L\'Alleanza ha preso il controllo del Cortile di Stromgarde!', 'L\'Alleanza ha preso il controllo del Cortile di Stromgarde!', 28153),
(138555, 'itIT', '$n ha conquistato il Cortile di Stromgarde!', '$n ha conquistato il Cortile di Stromgarde!', 28153),
(138553, 'itIT', '', 'Un\'imboscata! Difendete il villaggio!', 28153),
(138552, 'itIT', '', 'Vieni. Dirigiamoci al Passo Montano!', 28153),
(138551, 'itIT', 'Spero tu abbia ragione, mia signora. In formazione, soldati! Andiamo!', '', 28153),
(138550, 'itIT', '', 'Non intendo ragioni, Maresciallo. La mia scorta si assicurerà che io arrivi sana e salva.', 28153),
(138549, 'itIT', 'Ma, mia signora, sarebbe più sicuro se...', '', 28153),
(138548, 'itIT', '', 'Maresciallo, tu e i tuoi uomini andate al Presidio di Arom. Ci vedremo là. Io farò una piccola deviazione.', 28153),
(138547, 'itIT', 'L\'Alleanza ha preso il controllo del Passo di Granvalore!', 'L\'Alleanza ha preso il controllo del Passo di Granvalore!', 28153),
(138546, 'itIT', '$n ha conquistato il Passo di Granvalore!', '$n ha conquistato il Passo di Granvalore!', 28153),
(138545, 'itIT', 'Chi è il prossimo?', '', 28153),
(138544, 'itIT', 'Ti do il benvenuto nella ciurma dei dannati, Primo Ufficiale.', '', 28153),
(138543, 'itIT', 'Raaagh!', '', 28153),
(138542, 'itIT', 'Primo Ufficiale Jamboya, rinasci!', '', 28153),
(138540, 'itIT', 'Vieni avanti e accetta chesto dono. Unisciti alla ciurma mia per l\'eternità!', '', 28153),
(138539, 'itIT', 'Chesta è la casa nostra. Faremo di tutto per difendere chesto porto... per sempre!', '', 28153),
(138538, 'itIT', 'NO!', 'NO!', 28153),
(138537, 'itIT', 'I Sethrak pensano che ci nasconderemo aspettando di schiattare. Tu che ne dici?', '', 28153),
(138535, 'itIT', 'Nun rimarrò schiattato a lungo... Ci vediamo presto, Jamboya...', '', 28153),
(138534, 'itIT', 'N\'ammutinamento?!? Ti farò fare nu bel giro di chiglia!', '', 28153),
(138533, 'itIT', 'Oh! Chi è il farabutto che osa sfidarmi?', '', 28153),
(138532, 'itIT', '', 'La Madre... vi prenderà...', 28153),
(138531, 'itIT', '', 'Siete degli stolti a resistere. Le Frangicuore si impadroniranno di Kul Tiras!', 28153),
(138530, 'itIT', 'Noi proteggiamo Dama Crestabianca, continentale! Tu fa\' fuori il loro capo!', '', 28153),
(138529, 'itIT', '', 'La Madre ti prenderà, Lucille Crestabianca!', 28153),
(138528, 'itIT', 'Che cos\'è quell\'affare?', '', 28153),
(138527, 'itIT', 'Le trappole non li rallentano più. Ne arrivano altri!', '', 28153),
(138526, 'itIT', 'Calma, Kal\'dran. Possiamo ancora sconfiggere Zardrax.', 'Calma, Kal\'dran. Possiamo ancora sconfiggere Zardrax.', 28153),
(138521, 'itIT', '', 'Grazie, Conestabile. Vogliamo andare?', 28153),
(138520, 'itIT', 'Dama Crestabianca, sei libera. Le mie scuse...', '', 28153),
(138519, 'itIT', 'Attenzione! Si è scoperto che un\'altra strega è responsabile della maledizione alla Conca degli Impennatori.', '', 28153),
(138518, 'itIT', '', 'Va meglio. Ora andia...', 28153),
(138517, 'itIT', 'N\'altro Troll del Sangue. Essi sono infiniti e voi siete condannati!', '', 28153),
(138516, 'itIT', 'No! Nana\'kwug! Mo\' dovrò...', '', 28153),
(138515, 'itIT', 'Ahahah... Li sforzi tuoi nun servono a nulla. Nun fermerai mai il potere mio!', '', 28153),
(138514, 'itIT', 'Pensi che chesto faccia differenza? Il potere del Dio del Sangue scorre dentro di me! Nun puoi fermarlo!', '', 28153),
(138513, 'itIT', 'Il potere mio... svanisce! Ahah... dovete essere davvero disperati per pensare che chesto funzioni!', '', 28153),
(138509, 'itIT', 'Attenzione! Nemici dai boschi!', '', 28153),
(138502, 'itIT', 'Ecco! Chesto è il massimo che posso darti senza farmi troppo male. Va\' e brucia chei mucchi di scheletri.', '', 28153),
(138501, 'itIT', 'Concentrati. Ti trasmetterò parte del Mojo del Fuoco mio...', '', 28153),
(138500, 'itIT', 'Sono pronto a ricevere il Mojo del Fuoco per distruggere i tumuli sepolcrali.', 'Sono pronta a ricevere il Mojo del Fuoco per distruggere i tumuli sepolcrali.', 28153),
(138499, 'itIT', '', 'Ebbene, sembra che dovremo essere noi ad attaccare la congrega, allora. E penso anche di sapere come.', 28153),
(138498, 'itIT', 'L\'hanno... catturato, mia signora. Stavamo escogitando un modo per liberarlo, quando siamo venuti a sapere di questo... processo.', '', 28153),
(138497, 'itIT', '', 'E mio padre? Cosa sta facendo per contrastare questo attacco?', 28153),
(138496, 'itIT', 'Hanno invaso i territori oltre le montagne. Ci sono rimasti solo pochi soldati a difendere l\'accampamento di Arom.', '', 28153),
(138495, 'itIT', 'La situazione è assai grave, mia signora. Questa congrega si è diffusa in tutta Drustvar come una piaga.', '', 28153),
(138494, 'itIT', '', 'Maresciallo! Che cosa sai di questa congrega? Dimmi cosa accade alla nostra terra!', 28153),
(138449, 'itIT', '', 'Ohhh! Guarda che aspetto aveva il vecchio Zem\'lan!', 28153),
(138448, 'itIT', '', 'Zem\'lan era un po\' un infame, non trovi?', 28153),
(138439, 'itIT', 'Piglia li idoli e raduna la ciurma.', '', 28153),
(138438, 'itIT', 'I Sethrak nun si piglieranno la terra nostra. Né oggi, né mai.', '', 28153),
(138437, 'itIT', 'Io... Dev\'esserci n\'altro modo, Capitano. La ciurma...', '', 28153),
(138436, 'itIT', 'È-è un trucco? Lo è, vero?', 'Mi hai salvato la vita. Non ce l\'avrei mai fatta laggiù!', 28153),
(138435, 'itIT', 'Non c\'è tempo di presentarci. Non voglio passare altro tempo in questa miniera.', 'Non c\'è tempo di presentarci. Non voglio passare altro tempo in questa miniera.', 28153),
(138434, 'itIT', 'Nun fare domande! Raduna tutti all\'altare. Ora!', '', 28153),
(138433, 'itIT', 'Sono davvero felice di vederti.', 'Sono davvero felice di vederti.', 28153),
(138432, 'itIT', 'Non so chi tu sia o cosa tu voglia, ma grazie.', 'Non so chi tu sia o cosa tu voglia, ma grazie.', 28153),
(138431, 'itIT', 'Mi hai davvero salvato la vita. Non ce l\'avrei mai fatta laggiù!', 'Mi hai davvero salvato la vita. Non ce l\'avrei mai fatta laggiù!', 28153),
(138430, 'itIT', 'Le mie braccia sono stanche, ma le gambe non vedono l\'ora di correre via da qui!', 'Non so chi tu sia o cosa tu voglia, ma grazie.', 28153),
(138429, 'itIT', 'Al diavolo la sabbia! Al diavolo i serpenti! Il Porto di Zem\'lan è MIO!', '', 28153),
(138428, 'itIT', 'Te ne devo una.', 'Te ne devo una.', 28153),
(138427, 'itIT', 'Sono troppi, Capitano! Dobbiamo ritirarci o l\'intera ciurma rimarrà accisa!', '', 28153),
(138426, 'itIT', 'Fate a pezzi chei serpenti! Senza pietà!', '', 28153),
(138373, 'itIT', 'Speriamo di riuscire a seminare quei fuorilegge!', '', 28153),
(138316, 'itIT', 'Grazie, $C. Parleremo in un luogo più sicuro.', '', 28153),
(138288, 'itIT', 'Nessuna ritirata! Schiatteranno per mano dei Sethrak o per mano mia.', '', 28153),
(138282, 'itIT', 'Raduna la ciurma. Voglio ogni filibustiere ubriaco al cancello frontale.', '', 28153),
(138281, 'itIT', 'Nessuno me lo porterà via! Nessuno!', '', 28153),
(138280, 'itIT', 'Allora sono stupidi come tutti li altri. Chesto è il Porto di Zem\'lan! Il porto MIO!', '', 28153),
(138279, 'itIT', 'Capitano Zem\'lan, i Sethrak stanno arrivando! Sono tantissimi!', '', 28153),
(138264, 'itIT', 'Ingegnere di Volo Krazz al tuo servizio!', '', 28153),
(138247, 'itIT', 'Quindi andatevene dal porto mio! Andatevene e morite tra le dune come vi meritate.', '', 28153),
(138242, 'itIT', 'E dato che nun possedete altro che vestiti sporchi, siete già schiattati per me.', '', 28153),
(138240, 'itIT', 'Nessuno metterà piede sulle barche, eccetto chelli che pagheranno.', '', 28153),
(138238, 'itIT', 'E allora schiattate, stupidi vermi.', '', 28153),
(138235, 'itIT', 'Se nun ci lasciate salire, schiatteremo pure noi!', 'Se nun ci lasciate salire, schiatteremo pure noi!', 28153),
(138234, 'itIT', 'Fatevi da parte, rifugiati! I pirati tengono la precedenza per salire a bordo!', '', 28153),
(138233, 'itIT', 'Ti prego, Zem\'lan. Lasciaci salire sulle barche! I Sethrak ci accideranno!', 'Ti prego, Zem\'lan. Lasciaci salire sulle barche! I Sethrak ci accideranno!', 28153),
(138232, 'itIT', 'Con lo spazio che teniamo ancora, piglieremo più gente possibile.', '', 28153),
(138224, 'itIT', '', 'Sei $garrivato:arrivata; in un momento poco opportuno, continentale.\n\nCosa ti porta qui?', 28153),
(138214, 'itIT', 'Giusto. Solo io, allora.', '', 28153),
(138213, 'itIT', '', 'Assolutamente no.', 28153),
(138212, 'itIT', 'No.', '', 28153),
(138211, 'itIT', '', 'No.', 28153),
(138210, 'itIT', 'Non vi sembra che abbiamo esagerato annientando una moltitudine di Sethrak in questo modo?', '', 28153),
(138209, 'itIT', 'Be\', è un sollievo, anche se ritengo ugualmente che sia stato un po\' eccessivo.', '', 28153),
(138208, 'itIT', '', 'Ahah, è stato incredibile! E sei ancora in vita!', 28153),
(138203, 'itIT', 'Zeppelin in volo!', '', 28153),
(138202, 'itIT', 'Ce l\'hai fatta ancora una volta! Ben fatto!', '', 28153),
(138200, 'itIT', 'I Trogg mi hanno seguito fin qui. È tutta colpa mia! Ti prego, aiutami!', '', 28153),
(138123, 'itIT', 'Chi avrebbe detto che i Tortolliani potessero sentirsi così liberi?', '', 28153),
(138122, 'itIT', 'Riesco a sentire il vento soffiare tra le mie scaglie!', '', 28153),
(138121, 'itIT', 'Sono libero come un uccellino! Ah!', '', 28153),
(138120, 'itIT', 'Ottimo lavoro, papà!', '', 28153),
(138118, 'itIT', 'NON MOLLARE, NON MOLLARE, NON MOLLARE!', '', 28153),
(138075, 'itIT', 'Ti andrebbe di aiutarmi a ispezionare questi cavalli? Solo i migliori esemplari sono accetti!', '', 28153),
(138074, 'itIT', 'I lavoratori più pigri tentano sempre di rubarle. Se nun trovassi del grog, va\' da loro.', '', 28153),
(138073, 'itIT', 'Ho nascosto le scorte mie sott\'acqua. Aiuta a tenerle al fresco.', '', 28153),
(138072, 'itIT', 'Tutto a posto, $PR? Fammi sapere se vuoi qualcosa da bere.', '', 28153),
(138071, 'itIT', '', 'Hyah!', 28153),
(138070, 'itIT', '', 'Sei fortunato che non ho calciato più in alto! Non negarlo! Hai attivato tu la trappola!', 28153),
(138069, 'itIT', 'Ahi! Quello era il mio stinco!', '', 28153),
(138068, 'itIT', 'Casino? CASINO? Sei TU quella che l\'ha attivata, insopportabile sacco di...', '', 28153),
(138067, 'itIT', '', '...Per risolvere il casino che hai fatto!', 28153),
(138066, 'itIT', '', 'Allora andiamocene di qui e troviamo qualcuno con cui commerciare. Sto morendo di fame.', 28153),
(138065, 'itIT', '', 'E comunque, ho preso abbastanza gemme e monili da coprire i costi per un mese intero.', 28153),
(138064, 'itIT', '', 'Sì, sì. Vi voglio bene anch\'io.', 28153),
(138061, 'itIT', '', 'Non è rimasto nulla per noi qui. Prendiamo le nostre cose e muoviamoci.', 28153),
(138060, 'itIT', '', 'Non mi sorprende. Dissolvere la maledizione è stato un azzardo.', 28153),
(138059, 'itIT', 'Vuoi vedere come si fa una salsiccia?', '', 28153),
(138058, 'itIT', 'Chi ha la tua pancetta? Io! Ahahah!', '', 28153),
(138057, 'itIT', 'Andrai benissimo come pancetta!', '', 28153),
(138056, 'itIT', 'Ti... triterò...', '', 28153),
(138055, 'itIT', 'Non hai scampo...', '', 28153),
(138054, 'itIT', '', 'Possano i venti guidarti, $p... e non unirti a loro, va bene?', 28153),
(138053, 'itIT', '', 'Tornerò alla carovana. Saccheggeremo questo posto non appena avrai spezzato la maledizione.', 28153),
(138052, 'itIT', '', 'Ecco gli appunti che ho trovato. Ti serviranno solo un altro paio di cose per finire il rituale.', 28153),
(138051, 'itIT', 'Ti siamo davvero grati per averci salvato la pelle, $C. Tutti questi combattimenti devono averti messo fame, però.\n\nChe ne dici di qualche salsiccia?', '', 28153),
(138050, 'itIT', 'Ti prego, goditi la festa. Corri! Mangia! Bevi! In quanto ospite d\'onore, chiedi e avrai.', '', 28153),
(138049, 'itIT', 'Ohhh! Non solo hai salvato mio figlio, ma anche la festa! La gente parlerà per anni di tutto questo! Ahahah!', '', 28153),
(138048, 'itIT', '', 'Sei qui per il cibo, o qualcos\'altro?', 28153),
(138047, 'itIT', 'Rivitalizzazione', 'Rivitalizzazione', 28153),
(138046, 'itIT', '', 'Starò qui mentre vai a cercare gli altri idoli. Riportali da me quando li avrai trovati tutti.', 28153),
(138045, 'itIT', '', 'E anche uno degli idoli. Me lo prendi, per piacere?', 28153),
(138044, 'itIT', '', 'Credo che questa fosse la sala del trono di Zem\'lan. Ci sono tesori dappertutto!', 28153),
(138042, 'itIT', 'Tornate in posizione! Mantenete i ranghi!', '', 28153),
(138040, 'itIT', '', 'Meeki è probabilmente già morto. Vattene da Zem\'lan fintanto che puoi.', 28153),
(138039, 'itIT', '', 'Sei davvero un angelo!', 28153),
(138038, 'itIT', 'Hanno portato Ahna a sud, ma io me la svigno!', '', 28153),
(138037, 'itIT', 'Devo tornare al mio tempio mentre recupero le forze. Ti aspetterò lì.', '', 28153),
(138036, 'itIT', 'Finalmente sono libero.', '', 28153),
(138035, 'itIT', 'Torna presto, Norah.', '', 28153),
(138034, 'itIT', '', 'Se partissimo adesso, moriremmo di fame tra le dune.', 28153),
(138033, 'itIT', '', 'No, non possiamo. E lo sai anche tu.', 28153),
(138032, 'itIT', 'Non devi farlo per forza, Norah. Possiamo prendere tutto e lasciarci Zem\'lan alle spalle.', '', 28153),
(138031, 'itIT', '', 'Controlla la carovana mentre sono via, Viggy.', 28153),
(138029, 'itIT', 'È parecchio che non passo di qui. Speriamo di avere ancora qualche amico.', '', 28153),
(138028, 'itIT', 'Quando avrai le prove che la Compagnia dei Bracescura sta vendendo armi a questa feccia, raggiungimi al cancello principale in cima al colle.', '', 28153),
(138026, 'itIT', 'Bene, ho preso le tue... gambe. Cosa devo fare ora?', 'Bene, ho preso le tue... gambe. Cosa devo fare ora?', 28153),
(138025, 'itIT', 'Questa sarà la festa più eccitante degli ultimi anni! Salta in groppa a Cooper e fagliela vedere a quei Trogg. Ti sarà molto utile in combattimento!', '', 28153),
(138024, 'itIT', 'Senza dubbio Malautunno ti deve molto, $C.\n\nSpero solo che potremo ripagarti in qualche modo.', '', 28153),
(138023, 'itIT', 'Tu e Cooper formate una squadra magnifica! Divertiti pure a cavalcare con lui quanto ti pare.', '', 28153),
(138021, 'itIT', 'In molti nun sapranno mai ciò che hai fatto per loro, ma io nun lo dimenticherò mai.', '', 28153),
(138020, 'itIT', '', 'Folle! Osi sfidarmi qui, nel mio regno?!?', 28153),
(138019, 'itIT', '', 'Ahahah, nessuno udirà le tue urla!', 28153),
(138018, 'itIT', 'Un caldo benvenuto $gal nostro stimato:alla nostra stimata; ospite, $gSer:Dama; $n!', '', 28153),
(138017, 'itIT', 'Annuncio l\'arrivo di $gSer:Dama; $n!', '', 28153),
(138016, 'itIT', 'È un grande piacere dare il benvenuto a $gSer:Dama; $n alla Tenuta dei Norwington!', '', 28153),
(138015, 'itIT', '', 'Mi chiamo Jane. Ero una mercenaria su un vascello mercantile, quando le sirene ci hanno trascinati dentro.$B$BQuesta gente mi ha salvata, mi ha dato un soprannome e sono stati una famiglia per me sin da allora. Per alcuni di loro, finire qui è stato un gran cambiamento dalla vita precedente. Un\'occasione per ripartire da zero. Altri stanno semplicemente cercando di sopravvivere fino al momento in cui potranno tornare a casa.', 28153),
(138014, 'itIT', 'Xenxuju mi ha fatto bere dal Calice del Tuono. Grazie a Xenxuju, presto saremo tutt\'uno con Akunda!', '', 28153),
(138013, 'itIT', '', 'Kel\'vax... tiene molti modi... per acciderti...', 28153),
(138012, 'itIT', '', 'Diventerai parte delle offerte per Kel\'vax!', 28153),
(138009, 'itIT', 'N-non spaventarli, Norah. C-ci serve il loro aiuto.', 'N-non spaventarli, Norah. C-ci serve il loro aiuto.', 28153),
(138008, 'itIT', 'Dimmi, hai mai sentito parlare della leggenda di Zem\'lan?', 'Dimmi, hai mai sentito parlare della leggenda di Zem\'lan?', 28153),
(137999, 'itIT', 'Penso che aspetterò laggiù. Sembra che... ci sia una luce migliore per leggere lì. Buona fortuna!', '', 28153),
(137997, 'itIT', '<Guarda dentro lo zaino.>', '<Guarda dentro lo zaino.>', 28153),
(137993, 'itIT', '<Uno zaino da bambino. Su di esso c\'è attaccata una spilla con la scritta \"piccolo esploratore\".>', '', 28153),
(137988, 'itIT', 'Prenderò solo un altro po\' di tesori prima di andarmene...', 'Prenderò solo un altro po\' di tesori prima di andarmene...', 28153),
(137987, 'itIT', 'Grazie. Cercherò di guardare avanti.', 'Grazie. Cercherò di guardare avanti.', 28153),
(137986, 'itIT', 'Ho fatto un grosso errore.', 'Ho fatto un grosso errore.', 28153),
(137985, 'itIT', 'Hai visto i loro mostruosi famigli? Questo posto è un incubo.', 'Hai visto i loro mostruosi famigli? Questo posto è un incubo.', 28153),
(137984, 'itIT', 'Grazie, $PR. Non sarei durato ancora a lungo.', 'Grazie, $PR. Non sarei durata ancora a lungo.', 28153),
(137983, 'itIT', 'Sono in debito con te.', 'Sono in debito con te.', 28153),
(137982, 'itIT', 'Sono l\'ultimo della mia carovana...', 'Sono l\'ultima della mia carovana...', 28153),
(137981, 'itIT', 'Ho visto cose...', 'Ho visto cose...', 28153),
(137926, 'itIT', 'L\'amico tuo è schiattato. Chesto nun è nu posto per mortali.', '', 28153),
(137925, 'itIT', '', 'Quindi c\'è un Troll di nome Zem\'lan che dominava questo porto? Questa allora dev\'essere la sala del trono.', 28153),
(137924, 'itIT', 'Beh... Era un pellegrinaggio per soli Tortolliani, per sentire le storie di Torga... ma... suppongo possiate venire con noi.', '', 28153),
(137913, 'itIT', 'Tengo il rimedio perfetto per i ficcanaso come te!', '', 28153),
(137912, 'itIT', 'Mi è sempre piaciuto quel piccoletto. Il robot, intendo.', '', 28153),
(137911, 'itIT', 'Avevo un robot giocattolo. Un coso un po\' pazzo che ho comprato da uno Gnomo a Boralus.', '', 28153),
(137909, 'itIT', 'Recuperare i reagenti per la comunione tua è il primo passo verso la redenzione.', '', 28153),
(137908, 'itIT', 'Nun fare aspettare Xenxuju... ma sta\' accuort\'! Nun è il tipo con cui scherzare.', '', 28153),
(137907, 'itIT', '<%s continua a mugugnare sull\'accettare le proprie responsabilità per parecchi minuti.>', '', 28153),
(137906, 'itIT', 'Mmm... probabilmente la mia bussola. Mi ha sempre portato a destinazione! Be\', almeno fino a quando siamo finiti qui. Ma non è stata colpa sua. Voglio dire, è soltanto un oggetto.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137905, 'itIT', 'E va bene, puoi venire se vuoi... ma non fare troppo rumore! Questo è un pellegrinaggio, non una festa.', '', 28153),
(137903, 'itIT', '', 'Incredibile... ma teniamo altro lavoro da fare. Ci restano due Loa. Dobbiamo unirci ai Tortolliani nel loro pellegrinaggio per vedere Torga, il Loa Tartaruga.', 28153),
(137902, 'itIT', '', 'Mi stai dicendo che hai ottenuto l\'aiuto di Bwonsamdi... e ACCISO Hir\'eek?!?', 28153),
(137901, 'itIT', 'Oh, semplice! Il mio fidato cestino. Non ci ho mai tirato fuori un cattivo pasto da quel cestino. Mi manca davvero tanto.', '', 28153),
(137900, 'itIT', '', 'Libera finalmente!', 28153),
(137899, 'itIT', 'La padrona vincolerà la tua anima!', '', 28153),
(137898, 'itIT', '<Riferisci a Talanji dell\'aiuto di Bwonsamdi e dell\'uccisione di Hir\'eek.>', '<Riferisci a Talanji dell\'aiuto di Bwonsamdi e dell\'uccisione di Hir\'eek.>', 28153),
(137897, 'itIT', 'La padrona avrà la tua anima!', '', 28153),
(137896, 'itIT', 'Muori per la sua gloria!', '', 28153),
(137895, 'itIT', 'Ti ucciderò! Per la padrona!', '', 28153),
(137894, 'itIT', '', 'Ora devi andartene... Presto cambierò e nun voglio che tu veda ciò che diventerò...', 28153),
(137893, 'itIT', 'Mi chiamo Bill. Se devi riparare qualcosa, sono quello che fa per te.', '', 28153),
(137892, 'itIT', '', 'È troppo tardi per me... ma ci sta ancora speranza per li altri.', 28153),
(137891, 'itIT', 'Ehilà! Sei $gnaufragato:naufragata; qui come tutti noi?$B$BSo che non è molto, ma puoi rimanere qui nel nostro piccolo accampamento per quanto vuoi.', '', 28153),
(137890, 'itIT', 'Cerca nel deserto li iniziati mancanti. Starò accà ad attenderti.', '', 28153),
(137889, 'itIT', 'Qual è la cosa a cui tenevi di più che hai lasciato nel relitto?', 'Qual è la cosa a cui tenevi di più che hai lasciato nel relitto?', 28153),
(137888, 'itIT', 'Hai qualcosa da mangiare?', '', 28153),
(137887, 'itIT', '', 'Non va bene, non va bene per niente bene. Tutti fuori dalla carovana, presto!', 28153),
(137886, 'itIT', '', 'Chelle sono le truppe di Jakra\'zet!', 28153),
(137885, 'itIT', '', 'Non credo che quei Troll poco più avanti siano amici vostri.', 28153),
(137869, 'itIT', 'Folle! Avresti dovuto fuggire quando ne avevi l\'occasione! Il potere di Akunda sarà mio!', '', 28153),
(137860, 'itIT', '', 'Dolly! Dot! Non siete al sicuro laggiù!', 28153),
(137857, 'itIT', 'Ma guarda nu poco... Sei ancora in vita!', '', 28153),
(137851, 'itIT', 'Per la gloria dell\'impero dei Sethrak!', 'Per la gloria dell\'impero dei Sethrak!', 28153),
(137810, 'itIT', 'Ahhh! Credo di essermi spaccato na gamba.', '', 28153),
(137807, 'itIT', 'Andiamo.', 'Andiamo.', 28153),
(137806, 'itIT', 'Il rituale è entrato nel vivo. Sta\' accuort\', Hir\'eek arriverà da nu momento all\'altro.', '', 28153),
(137805, 'itIT', 'Incontriamoci al circolo del rituale.', '', 28153),
(137789, 'itIT', 'Fa\' attenzione, $C...', 'Fa\' attenzione, $C...', 28153),
(137788, 'itIT', '<Il corpo del Loa è intrappolato da dei vincoli magici.>', '', 28153),
(137787, 'itIT', 'Ti do il benvenuto nel mio tempio, $n. Ti ringrazio per le tue gesta, sarai sempre $gil benvenuto:la benvenuta; qui.', '', 28153),
(137785, 'itIT', '', 'Grazie a entrambi. La lealtà vostra significa assai per me... e per tutti li Zandalari.', 28153),
(137784, 'itIT', '', 'Scommetto di poter convincere gli altri Tortolliani di Nazmir ad aiutarvi. Forse verranno anche Shoak e Kajosh!', 28153),
(137783, 'itIT', 'Va bene, vi aiuteremo a combattere questo Dio del Sangue, Principessa. Ma smettila di assillarmi!', '', 28153),
(137782, 'itIT', '', 'Prenditi cura del Loa, Lashk. Noi dobbiamo andare a cercare altro aiuto.', 28153),
(137781, 'itIT', 'Ah! Quella scaltra tartaruga... non cercava la pace dello spirito. Voleva reincarnarsi!', '', 28153),
(137780, 'itIT', '', 'Ma che accidenti...', 28153),
(137779, 'itIT', '', 'Nun avrò pace finché G\'huun e i Troll del Sangue nun saranno altro che nu ricordo. Te lo giuro, Torga.', 28153),
(137778, 'itIT', '', 'E io mi assicurerò che i Tortolliani sappiano come ti sei opposto coraggiosamente a G\'huun.', 28153),
(137777, 'itIT', 'Addio, Torga. Ricorderò le storie che mi hai raccontato... e le condividerò con gli altri.', '', 28153),
(137776, 'itIT', '', 'Sei forte, ma nun sei niente di fronte al potere che tengo IO!', 28153),
(137764, 'itIT', '', 'Già. Torniamo al santuario.', 28153),
(137763, 'itIT', 'Fiuuu! È ora di prendersi una pausa.', '', 28153),
(137762, 'itIT', '', 'Oh... incredibile. Ce l\'abbiamo fatta!', 28153),
(137758, 'itIT', '', 'Io e il Campione dell\'Orda stiamo venendo a prenderti! E ti faremo a pezzi!', 28153),
(137757, 'itIT', '', 'Tutto chesto... finisce ora! La gente mia nun subirà più... l\'oppressione tua... e dei Troll del Sangue!', 28153),
(137755, 'itIT', 'Questo... non significa... NULLA! Otterrà... un nuovo... ricettacolo. I sigilli... saranno spezzati... G\'huun... sarà libero!', '', 28153),
(137754, 'itIT', 'Presto! Uccidilo prima che capisca che sono io la vera minaccia!', '', 28153),
(137753, 'itIT', 'Assaggia la mia fidata balestra, vile demonio!', '', 28153),
(137752, 'itIT', 'Tienilo fermo! Non riesco a mirare se continua a muoversi!', '', 28153),
(137751, 'itIT', '', 'Cosa stai facendo? Guardie, a me!', 28153),
(137750, 'itIT', 'ARGHHH! Non siete NULLA contro G\'huun! Soffrite e MORITE!', '', 28153),
(137749, 'itIT', '', 'PER TORGA!', 28153),
(137748, 'itIT', '', 'INSIEME! ORA!', 28153),
(137747, 'itIT', 'I vostri sforzi... sono inutili. Io sono... intocc... cosa? No. NO!', '', 28153),
(137746, 'itIT', '', 'La tracotanza sarà la fine tua! Il potere tuo nun può proteggerti!', 28153),
(137745, 'itIT', 'I vostri sforzi... sono inutili. Io sono... intoccabile.', '', 28153),
(137744, 'itIT', '', 'Pensa a quando gli altri sentiranno la storia di come abbiamo ucciso l\'Alfiere di G\'huun!', 28153),
(137743, 'itIT', 'Ah, erano anni che il mio cuore non bruciava così. Per Torga!', '', 28153),
(137742, 'itIT', '', 'Iniziamo. Per Zandalar... e per Torga!', 28153),
(137736, 'itIT', '', 'Grande Hir\'eek, ti offriamo nu sacrificio di carne e sangue!', 28153),
(137734, 'itIT', 'Sì, sì. Arriviamo!', '', 28153),
(137733, 'itIT', '', 'Venite! Dobbiamo essere pronti per distruggere l\'Alfiere del Dio del Sangue!', 28153),
(137732, 'itIT', 'Statt\' accuort\' ai ragni. Potrò pure essere il dio dei segreti, ma Yazma è la signora delle spie. Adora tenere i piccoli amici suoi presso il dominio mio, alla ricerca dei figli miei.', '', 28153),
(137731, 'itIT', 'Sono pronto.', 'Sono pronta.', 28153),
(137730, 'itIT', '', 'Non pensavo avrei mai messo piede in queste rovine. Incredibile, vero?', 28153),
(137728, 'itIT', 'Ti manca la forza tua mo\', eh? Vai, lacchè, e trova chello ratto di Nokano che ti ha detto di accidere la gente mia. Mordilo e ripigliati la forma da riccumpà tua.', '', 28153),
(137721, 'itIT', '', 'Vendicare un Loa e uccidere l\'avatar di qualche mostro. Questa potrebbe essere la miglior storia mai raccontata da un Tortolliano!', 28153),
(137720, 'itIT', 'Sai, credo che potremmo farcela a uccidere questo Alfiere di G\'huun.', '', 28153),
(137719, 'itIT', '', 'Sarà meglio muoverci e capire cos\'altro stanno facendo i Troll del Sangue più avanti.', 28153),
(137718, 'itIT', '', 'Il nostro lavoro qui è finito. Ci vediamo al Presidio di Arom.', 28153),
(137716, 'itIT', '', 'La strega era troppo forte per me. Sono stata intrappolata.', 28153),
(137715, 'itIT', '', 'Grazie per avermi liberato da quel terribile costrutto!', 28153),
(137710, 'itIT', '', 'Bene! È ora di muoverci. Ma ricordate, fate silenzio! L\'ultima cosa che vogliamo è che voi due finiate in gabbia.', 28153),
(137709, 'itIT', 'Certo. Ho delle pergamene più vecchie di voi! Kisha, guarda tra la mia roba.', '', 28153),
(137708, 'itIT', '', 'Lashk, Kisha, dobbiamo aggirare i Troll del Sangue e scoprire cos\'altro hanno in mente. Tenete qualcosa che possa aiutarci?', 28153),
(137707, 'itIT', '', 'Ma furono i nostri studiosi a mutarne le sorti...', 28153),
(137706, 'itIT', 'Sono troppo vecchio per queste cose.', '', 28153),
(137705, 'itIT', 'Magia del sangue! Ma chi userebbe mai una magia del genere?', '', 28153),
(137704, 'itIT', 'Racconterò agli altri tante storie di questo momento.', '', 28153),
(137703, 'itIT', 'Prima uccidono Torga e adesso vogliono uccidere noi! Ma cos\'è che non va in quei Troll?', '', 28153),
(137702, 'itIT', 'Mi hanno anche rubato tutte le pergamene! Riportamele, ti prego.', '', 28153),
(137701, 'itIT', 'Alla fine la fortuna mi ha sorriso!', '', 28153),
(137700, 'itIT', '', 'Non ci impedirai di mangiare i Tortolliani!', 28153),
(137699, 'itIT', '', 'Noi non mangiamo Loa... Noi mangiamo Tortolliani!', 28153),
(137697, 'itIT', '', 'Kachago!', 28153),
(137696, 'itIT', 'Non credere alle bugie di questo seccante spacciatore di schifezze.\n\nMi ha venduto numerosi manoscritti, ognuno dei quali si è rivelato solo un\'accozzaglia di bugie.\n\nSe pensa che me ne andrò prima di ottenere un rimborso, si sbaglia di grosso. Dopo tutto, i Troll non vivono poi così a lungo.', '', 28153),
(137695, 'itIT', 'Non me ne andrò fin quando non otterrò un rimborso.', '', 28153),
(137694, 'itIT', 'La vostra narrativa è confusa e mal formulata.', '', 28153),
(137693, 'itIT', 'I tuoi libri parlano di luoghi che semplicemente non esistono.', '', 28153),
(137692, 'itIT', 'Che la fortuna vi aiuti, mortali. E... grazie.', '', 28153),
(137691, 'itIT', 'Vendi solo bugie, Tella.', '', 28153),
(137690, 'itIT', 'Distruggete gli accampamenti attorno al mio cadavere per indebolire Jungo.', '', 28153),
(137689, 'itIT', 'Principessa Talanji. I Troll del Sangue stanno alimentando Jungo con i miei resti.', '', 28153),
(137678, 'itIT', '', 'Donaci la saggezza tua, grande Torga. Dicci come fermare chesti Troll del Sangue.', 28153),
(137677, 'itIT', 'Sono qui. Cosa desideri?', '', 28153),
(137676, 'itIT', 'Torga! Lo spirito tuo è richiesto! Tira fuori la testa dal guscio, cumpà!', '', 28153),
(137675, 'itIT', '', 'Guzincha!', 28153),
(137674, 'itIT', 'Rgggh...', '', 28153),
(137673, 'itIT', 'Aaaaaargh!', '', 28153),
(137672, 'itIT', '', 'Nun puoi nasconderti dal Dio del Sangue!', 28153),
(137671, 'itIT', '\"Stupida capra. Vieni, prima che i mostri ti mangino viva!\"', '\"Stupida capra. Vieni, prima che i mostri ti mangino viva!\"', 28153),
(137670, 'itIT', '', 'Il sangue tuo per G\'huun!', 28153),
(137669, 'itIT', '\"Ehi, Marzapane. Ti sei persa? Perché non vieni con me, così torniamo a casa?\"', '\"Ehi, Marzapane. Ti sei persa? Perché non vieni con me, così torniamo a casa?\"', 28153),
(137668, 'itIT', '', 'Le ossa tue ci serviranno a dovere.', 28153),
(137667, 'itIT', '', 'Voglio il sangue tuo!', 28153),
(137666, 'itIT', '', 'Carne fresca!', 28153),
(137665, 'itIT', '', 'Zuldazar cadrà!', 28153),
(137664, 'itIT', 'Nun sto accà per difendere te o i mercanti. No, il lavoro mio è combattere li incubi che possono arrivare da nord. Troll del Sangue, cumpà serpente, Alleanza, qualsiasi cosa sia.$b$bDevo anche combattere contro la noia, ma principalmente li altri pericoli. Per quale motivo stai accà?', 'Nun sto accà per difendere te o i mercanti. No, il lavoro mio è combattere li incubi che possono arrivare da nord. Troll del Sangue, cumpà serpente, Alleanza, qualsiasi cosa sia.$b$bDevo anche combattere contro la noia, ma principalmente li altri pericoli. Per quale motivo stai accà?', 28153),
(137663, 'itIT', '<Sembra che questa piccola capra smarrita appartenga a qualcuno.\n\nSul collare si legge il nome \"Marzapane\".>', '', 28153),
(137662, 'itIT', '', 'Sangue! Sangue! Sangue!', 28153),
(137661, 'itIT', 'Ho sentito che hai riportato indietro la Principessa Talanji. Tieni la riconoscenza mia per chesto.$b$bMa dicono che hai riportato anche Zul. Tieni l\'ira mia per chesto.\n\nCosa vuoi?', 'Ho sentito che hai riportato indietro la Principessa Talanji. Tieni la riconoscenza mia per chesto.$b$bMa dicono che hai riportato anche Zul. Tieni l\'ira mia per chesto.\n\nCosa vuoi?', 28153),
(137660, 'itIT', 'Mi hai scambiato per nu mercante? Io sono nu guerriero! D\'alta casta, cumpà.\n\nChe ti serve?', 'Mi hai scambiato per na mercante? Io sono na guerriera! D\'alta casta, cumpà.\n\nChe ti serve?', 28153),
(137659, 'itIT', 'Ti serve qualcosa? Altrimenti, aria.', 'Ti serve qualcosa? Altrimenti, aria.', 28153),
(137658, 'itIT', 'Nun tieni mica del vudù dei Troll del Sangue, vero? No? Bene.\n\nCosa ti porta accà?', 'Nun tieni mica del vudù dei Troll del Sangue, vero? No? Bene.\n\nCosa ti porta accà?', 28153),
(137657, 'itIT', 'Dicono che i Troll del Sangue stiano penetrando nella società nostra. Se nun riusciranno a invaderci, ci convertiranno.\n\nProbabilmente entrambe le cose, ma meglio nun pensarci. Di che tieni bisogno?', 'Dicono che i Troll del Sangue stiano penetrando nella società nostra. Se nun riusciranno a invaderci, ci convertiranno.\n\nProbabilmente entrambe le cose, ma meglio nun pensarci. Di che tieni bisogno?', 28153),
(137656, 'itIT', 'Il cugino mio sta combattendo gloriosamente presso le Porte del Sangue. E io?$b$bA me tocca badare ai sauridi. Bah.\n\nChe vuoi?', 'Il cugino mio sta combattendo gloriosamente presso le Porte del Sangue. E io?$b$bA me tocca badare ai sauridi. Bah.\n\nChe vuoi?', 28153),
(137655, 'itIT', 'Bwonsamdi, siamo pronti, evoca lo spirito di Torga.', 'Bwonsamdi, siamo pronti, evoca lo spirito di Torga.', 28153),
(137654, 'itIT', '\"Va\' a Nazmir\", dicevano. \"Ascolta le storie di Torga\", dicevano. \"Sarà divertente\", dicevano!', '', 28153),
(137652, 'itIT', 'Il guscio del Loa... mi nutre. Nutre... G\'huun.', '', 28153),
(137651, 'itIT', 'Io parlo... per G\'huun. Lui... guiderà. Tu... servirai... o morirai.', '', 28153),
(137643, 'itIT', 'Mi piacerebbe sentire le urla loro, ma faresti meglio a tenere nu basso profilo. Nun voglio che catturino pure te.', '', 28153),
(137642, 'itIT', 'Ah! Libertà!', '', 28153),
(137641, 'itIT', 'Oh, e se ti capitasse di incontrare nu Troll di nome Sur\'jan, dagli na pugnalata al core da parte mia! Se la merita!', '', 28153),
(137640, 'itIT', 'Grazie di tutto, cumpà.', '', 28153),
(137639, 'itIT', '', 'Con il potere del volo donatoci da Hir\'eek e la forza del Dio del Sangue, li Zandalari cadranno!', 28153),
(137638, 'itIT', 'Ti ringrazio per il lavoro che hai fatto, $p. Di\' a Kreepi di mandare altra acqua mentre te ne vai, grazie.', '', 28153),
(137637, 'itIT', 'Fai attenzione! I Treant sono infuriati e stanno uccidendo chiunque si avvicini troppo.', '', 28153),
(137620, 'itIT', 'Le tue dimensioni non sono importanti. Il tuo spirito è tra i più grandi che abbia mai visto.', '', 28153),
(137619, 'itIT', '', 'Grazie, Sumber! Voglio imparare da te tutto quello che una piccola Vulpera come me possa sapere.', 28153),
(137618, 'itIT', 'Ho infuso parte del mio potere in questo totem. Usalo con saggezza.', '', 28153),
(137616, 'itIT', '', 'Sei il benvenuto, Sumber. Io e $gil mio amico:la mia amica; saremo felici di aiutarti come possiamo.', 28153),
(137615, 'itIT', 'Sono impressionato. È stato saggio portarmi quest\'essenza.', '', 28153),
(137614, 'itIT', '', 'Argh! Quest\'acqua è troppo veloce. Non riesco a controllarla!', 28153),
(137610, 'itIT', '', 'Basta che cerchi delle grosse pozze d\'acqua. Non ce ne sono molte a Vol\'dun, dovrebbe essere facile.', 28153),
(137609, 'itIT', '', 'Cerca di dare spettacolo. Dobbiamo impressionare Sumber.', 28153),
(137608, 'itIT', '', 'Qualsiasi cosa stia succedendo laggiù, prendi l\'acqua e vattene. Non immischiarti.', 28153),
(137607, 'itIT', 'Ci sono potenti entità là sotto, $p. Lascia che la saggezza guidi i tuoi colpi e le tue scelte.', '', 28153),
(137606, 'itIT', 'Gloria e onore a te, $p.', '', 28153),
(137605, 'itIT', '', 'Un giorno di lavoro è un giorno di paga, non importa chi sei.', 28153),
(137604, 'itIT', 'Un potente flagello del male come $p non affronta mostri solo per soldi, Maiya. È la gloria ciò che conta!', '', 28153),
(137603, 'itIT', '', 'Tutto si può riparare, con l\'impegno giusto, Heiro.', 28153),
(137602, 'itIT', 'Sei sicura che possiamo ripararla? I ranishu ne hanno divorato gran parte.', '', 28153),
(137601, 'itIT', 'E mo\' viene la parte migliore: accidere gente e portarmi le anime loro!', '', 28153),
(137597, 'itIT', 'Tieni il fuoco nelle vene, Talanji. Eheheh! Ma l\'aiuto mio ti costerà comunque qualcosa.', '', 28153),
(137594, 'itIT', '', 'Nun staremo al gioco tuo, Bwonsamdi. Vuoi nu spirito Loa? L\'eroe ha già acciso Hir\'eek. Vatti a pigliare chello!', 28153),
(137590, 'itIT', 'Eheheh! Ah... che ne dite... di nu patto, eh? Portatemi l\'anima di n\'altro Loa, e vi farò avere... lo spirito di Torga, eh!', '', 28153),
(137588, 'itIT', 'Fatemi indovinare... mmm... Volete parlare con l\'anima del povero Torga.', '', 28153),
(137587, 'itIT', 'Sono pronto per provare a evocare Bwonsamdi.', 'Sono pronta per provare a evocare Bwonsamdi.', 28153),
(137586, 'itIT', 'Parlare non funziona. Dobbiamo trovare un altro modo per fermarli... o almeno per fuggire come hai fatto tu.', '', 28153),
(137585, 'itIT', 'Avviserò Kreepi e gli altri. I ranishu mangiano quelli della tua razza... e qualsiasi altra cosa.', '', 28153),
(137584, 'itIT', 'Ahah! Guarda come vanno quei piedi da $PR! Non inciampare!', '', 28153),
(137583, 'itIT', 'Gnam Gnam grosso! Mangia maschera! Tutti mangiano $PR!', '', 28153),
(137582, 'itIT', '', 'I Troll del Sangue desidereranno di nun averci mai traditi.', 28153),
(137581, 'itIT', '<Tira la torcia>', '<Tira la torcia>', 28153),
(137580, 'itIT', '<Dopo un\'attenta ispezione, capisci che la torcia sembra essere connessa a qualche sorta di meccanismo nel muro.>', '', 28153),
(137579, 'itIT', '<È solo un paio di vecchi stivali.>\n\n<Che cosa ti aspettavi?>', '', 28153),
(137578, 'itIT', '<Non c\'è alcuna entrata nascosta sotto il tappeto.>\n\n<Ma bisogna ammettere che sta proprio bene nella stanza.>', '', 28153),
(137577, 'itIT', '<Sorprendentemente, il libro che fuoriesce non è una leva segreta per l\'entrata nascosta.>', '', 28153),
(137576, 'itIT', '<L\'ancora è fissata saldamente al muro.>', '', 28153),
(137575, 'itIT', '', 'Te lo dico io chi. I Troll del Sangue. Seguitemi... gliela faremo pagare!', 28153),
(137574, 'itIT', '', 'Chi farebbe mai una cosa simile a Torga? Voleva solo raccontare storie!', 28153),
(137573, 'itIT', 'Torga! NO!', '', 28153),
(137572, 'itIT', 'Torga è stato ucciso come un animale qualsiasi!', '', 28153),
(137571, 'itIT', 'Tutte le storie di Torga... perdute per sempre!', '', 28153),
(137570, 'itIT', 'Un Loa... morto?', '', 28153),
(137569, 'itIT', 'Com\'è potuto succedere?', '', 28153),
(137568, 'itIT', '', 'Nascosero quelle informazioni qui, lontano da occhi indiscreti.', 28153),
(137563, 'itIT', 'Sto cercando lavoro.', 'Sto cercando lavoro.', 28153),
(137561, 'itIT', '', 'Bah! Ti sembro forse una guida turistica? Sono qui solo per sentire le storie di Torga.', 28153),
(137560, 'itIT', '', 'Farei meglio a muovermi, prima che qualcun altro cominci a chiedermi indicazioni.', 28153),
(137559, 'itIT', '', 'Continua a seguire la strada e troverai Torga. È una tartaruga gigante. È difficile non notarla.', 28153),
(137558, 'itIT', '', 'Ma che ti importa di quello che faccio? Non criticare il mio approccio al pellegrinaggio.', 28153),
(137557, 'itIT', '\"Pellegrinaggio?\" A me sembra che tu sia lì ferma nello stesso punto. Lashk ha detto che sapevi dove trovare Torga.', '\"Pellegrinaggio?\" A me sembra che tu sia lì ferma nello stesso punto. Lashk ha detto che sapevi dove trovare Torga.', 28153),
(137556, 'itIT', 'Lashk ha detto che sai dove posso trovare Torga.', 'Lashk ha detto che sai dove posso trovare Torga.', 28153),
(137555, 'itIT', 'Che vuoi? Non vedi che sono nel bel mezzo di un pellegrinaggio?', '', 28153),
(137554, 'itIT', 'Be\', credo che andremo d\'accordo, principessa.', '', 28153),
(137553, 'itIT', '', 'Chesta nun è la prima volta che ho avuto a che fare con voi Tortolliani... e le vostre storie infinite. Rimanete concentrati e camminate!', 28153),
(137552, 'itIT', 'Va bene, allora. Andiamo a vedere Torga. Però ricordatevi di fare silenzio, non voglio perdere una sola sua storia!', '', 28153),
(137551, 'itIT', 'Be\'... Sì, ecco. Non vogliamo unirci alla causa di nessuno, ma non vi fermeremo se vorrete camminare con noi.', '', 28153),
(137550, 'itIT', 'Cosa vuoi?', '', 28153),
(137549, 'itIT', 'Sarebbe saggio ripensare alla risposta tua.', '', 28153),
(137548, 'itIT', 'Io conosco solo Akunda.', '', 28153),
(137547, 'itIT', 'Ho chiesto il nome tuo, e tu mi racconti storie?', '', 28153),
(137546, 'itIT', 'Alamorte? Che genere di creatura si darebbe mai nu nome del genere?', '', 28153),
(137545, 'itIT', 'You will be granted access to this loa\'s buff. This system is a WIP.', 'You will be granted access to this loa\'s buff. This system is a WIP.', 28153),
(137544, 'itIT', 'Mi metto subito al lavoro.', 'Mi metto subito al lavoro.', 28153),
(137543, 'itIT', '', 'La flora di questa forra fa fatica a sopravvivere, proprio come noi.', 28153),
(137542, 'itIT', 'Non so come ringraziarti, continentale. Ora posso andarmene il più lontano possibile da questo posto.', 'Non so come ringraziarti, continentale. Ora posso andarmene il più lontano possibile da qui.', 28153),
(137541, 'itIT', '', 'Salve! Ti piacciono le fiamme? O i razzi? Che ne dici di razzi in fiamme? Ho così tante cose da mostrarti... Non vedo l\'ora!', 28153),
(137540, 'itIT', 'Per la miseria! Cos\'era quella... COSA?!?', 'Per la miseria! Cos\'era quella... quella COSA?!?', 28153),
(137537, 'itIT', '', 'Oh, no. Ma non conviene passare attraverso il canyon. Pullula di orribili incubi.', 28153),
(137536, 'itIT', '', 'Tieniti forte, se riesci. Ci saranno un po\' di scossoni!', 28153),
(137535, 'itIT', 'Non può essere l\'unica strada percorribile...', '', 28153),
(137534, 'itIT', '', 'E sud sia. È bene sapere però che le montagne sono maledette. Chi vi mette piede non fa ritorno.', 28153),
(137533, 'itIT', 'Chesto dev\'essere il posto giusto. Vedo n\'edificio più avanti.', '', 28153),
(137531, 'itIT', 'Dovremmo andare a sud. Il tempio sta da qualche parte tra chelle colline.', '', 28153),
(137530, 'itIT', 'I miei alloggi sono rustici ma confortevoli, te l\'assicuro.', '', 28153),
(137529, 'itIT', 'Akunda ci ha dato la possibilità di abbandonare il passato nostro e ripartire da capo.', '', 28153),
(137528, 'itIT', '', 'L\'Orda dev\'essere eliminata. Zuldazar si inchinerà di fronte all\'Alleanza!', 28153),
(137526, 'itIT', 'Bah. Questo posto non è niente male... comunque siamo in pellegrinaggio. E temo che tu stia per rendere questo viaggio più difficile...', '', 28153),
(137525, 'itIT', '', 'Tortolliani! Che ci fate in chesto luogo maledetto?', 28153),
(137523, 'itIT', 'Potrebbe nun piacerti la risposta mia, $n. Mi merito pienamente chesta condanna.', '', 28153),
(137517, 'itIT', 'Come hai fatto a finire qui?', 'Come hai fatto a finire qui?', 28153),
(137516, 'itIT', 'La possibilità di lasciare il passato alle spalle e ripartire da zero nun mi pare male. Chei Troll forse nun sono pazzi come sembrano.', '', 28153),
(137515, 'itIT', 'Devo la vita mia a Rakera. Nessuno di noi esuli sarebbe sopravvissuto nelle sabbie senza la guida sua.', '', 28153),
(137509, 'itIT', 'D\'accordo, prendilo! Basta che mi lasci andare!', '', 28153),
(137508, 'itIT', 'Rupert, balla!', '', 28153),
(137505, 'itIT', 'Ho visto chella che stai cercando. Ha superato le prove facilmente, ma nun sembrava interessata a rimanere accà.\n\nStava cercando qualcosa. Faceva domande, come te, ma è andata via dopo poco. Verso sud, proprio dove dovresti andare pure tu.\n\nChesto tempio nun è sicuro.', '', 28153),
(137504, 'itIT', '', 'Siamo tutti Akunda.', 28153),
(137502, 'itIT', 'Rupert, vieni qui!', '', 28153),
(137501, 'itIT', 'Hai visto la Guardia da Guerra Rakera?', 'Hai visto la Guardia da Guerra Rakera?', 28153),
(137500, 'itIT', 'Akunda ci dà forza.', 'Akunda ci dà forza.', 28153),
(137499, 'itIT', 'Senza Akunda, nun siamo nulla.', 'Senza Akunda, nun siamo nulla.', 28153),
(137498, 'itIT', 'Akunda ci dona il potere suo.', 'Akunda ci dona il potere suo.', 28153),
(137497, 'itIT', 'Siamo tutti Akunda.', 'Siamo tutti Akunda.', 28153),
(137496, 'itIT', 'Lei nun è Akunda.', '', 28153),
(137495, 'itIT', '', 'Se nun è Akunda, nun le è permesso entrare.', 28153),
(137494, 'itIT', 'Solo Akunda può camminare in chesto tempio.', '', 28153),
(137493, 'itIT', 'Nun conosco nessuno con quel nome qui.', '', 28153),
(137492, 'itIT', '', 'Vedo solo coloro abbastanza degni del potere di Akunda.', 28153),
(137491, 'itIT', 'Perché ti preoccupi di coloro che nun sono Akunda?', '', 28153),
(137490, 'itIT', '', 'Rakera? Che strano nome.', 28153),
(137489, 'itIT', 'Appiccicoso! Gnam gnam!', '', 28153),
(137488, 'itIT', 'Tieni la voce bassa... Nun vogliamo che chesti folli cultisti sappiano di che stiamo parlando.', '', 28153),
(137487, 'itIT', 'Vuoi diventare tutt\'uno con Akunda? Servimi bene e soddisferò la richiesta tua.', '', 28153),
(137486, 'itIT', 'Tu, laggiù! Nun bere da chel calice.', '', 28153),
(137485, 'itIT', 'Gnam, gnam, gnam!', '', 28153),
(137484, 'itIT', 'Nun mi hai sentito quando ho parlato? Nun bere da chel calice, te ne pentirai.', '', 28153),
(137483, 'itIT', 'Salja passa il tempo suo a dormire nella torre a ovest. Na goccia del veleno mio e nun camminerà mai più. Assicurati di pigliare la chiave!', '', 28153),
(137482, 'itIT', '', 'Ci siamo già visti da qualche parte? Hai una faccia familiare...', 28153),
(137480, 'itIT', 'Quando me ne andrò da accà, me la pagherai!', '', 28153),
(137479, 'itIT', 'Fammi uscire da accà o giuro che te ne pentirai!', '', 28153),
(137478, 'itIT', 'Tirami fuori da chesta prigione prima che ti mostri nu nuovo significato della parola incubo!', '', 28153),
(137477, 'itIT', 'Non ho mai visto nulla del genere... La carne ha solo reso i ranishu ancora più affamati. Il Vecchio Sottobosco non aveva possibilità!', '', 28153),
(137476, 'itIT', 'Ah! Che solleti... Ahia! Fa male! Basta!', '', 28153),
(137475, 'itIT', 'Non vi ho dato il permesso di divorarmi, creature infami!', '', 28153),
(137472, 'itIT', '<Gli occhi del Vecchio Sottobosco sembrano freddi e senza vita.>', '', 28153),
(137466, 'itIT', 'Cerca Ni-Ni il Mangiatore a nord. È un grosso insetto con una marea di cadaveri attorno. Schiaccialo e rubagli la maschera!', '', 28153),
(137465, 'itIT', '', 'Il sangue di Torga alimenterà il potere nostro!', 28153),
(137464, 'itIT', '', 'Il sangue di Torga è nostro mo\'!', 28153),
(137463, 'itIT', 'Ah, il prurito è finalmente passato. La solitudine è così deliziosa.', '', 28153),
(137462, 'itIT', 'Ignora quel guastafeste, Rupert. Sarai un ottimo cane da caccia.', '', 28153),
(137461, 'itIT', 'È un orso. Ascolta, preoccupati solo di sbarazzartene prima che uno degli Holton lo veda.', 'È un orso. Ascolta, preoccupati solo di sbarazzartene prima che uno degli Holton lo veda.', 28153),
(137460, 'itIT', 'Ho trovato questo povero cagnolino mentre ero a caccia. Ho deciso di insegnarli qualche trucchetto.', '', 28153),
(137459, 'itIT', 'Quello è... un orso?!?', 'Quello è... un orso?!?', 28153),
(137458, 'itIT', 'Rupert, $gquesto:questa; gentile $C ci ha portato un regalo. Mostra un po\' di apprezzamento! Balla!', '', 28153),
(137457, 'itIT', 'Ti do il benvenuto, Akunda l\'Audace.', '', 28153),
(137456, 'itIT', 'Ti do il benvenuto, Akunda l\'Imperturbabile.', '', 28153),
(137455, 'itIT', 'Ti do il benvenuto, Akunda l\'Agile.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137454, 'itIT', 'Ho ucciso Alamorte. Di certo avrai sentito parlare di me.', 'Ho ucciso Alamorte. Di certo avrai sentito parlare di me.', 28153),
(137453, 'itIT', 'I racconti del mio trionfo sul Re dei Lich non hanno raggiunto la tua terra?', 'I racconti del mio trionfo sul Re dei Lich non hanno raggiunto la tua terra?', 28153),
(137452, 'itIT', 'Ho sconfitto la Legione Infuocata. Davvero? Non sai chi sono?', 'Ho sconfitto la Legione Infuocata. Davvero? Non sai chi sono?', 28153),
(137451, 'itIT', 'Lasciatemi stare, dannati insetti! Andate a divorare la vostra amata carne e lasciate stare gli alberi!', '', 28153),
(137450, 'itIT', 'Il mio nome è Akunda l\'Agile', 'Il mio nome è Akunda l\'Agile', 28153),
(137449, 'itIT', 'Il mio nome è Akunda l\'Imperturbabile', 'Il mio nome è Akunda l\'Imperturbabile', 28153),
(137448, 'itIT', 'Il mio nome è Akunda l\'Audace', 'Il mio nome è Akunda l\'Audace', 28153),
(137447, 'itIT', 'Il mio nome non è cambiato.', 'Il mio nome non è cambiato.', 28153),
(137446, 'itIT', 'Finora hai vissuto na vita priva di significato.\n\nCiò che hai fatto e ciò che eri dev\'essere dimenticato.\n\nPronuncia il vero nome tuo, così che tutti lo sentano!', '', 28153),
(137444, 'itIT', 'In molti cercano riparo nel tempio nostro, ma solo ai più degni è permesso entrare.', '', 28153),
(137438, 'itIT', 'Ah! Insieme sconfiggeremo questa bestia!', '', 28153),
(137437, 'itIT', 'Zannalunga attacca con rinnovato vigore ora che ha degli alleati!', '', 28153),
(137436, 'itIT', 'Zannalunga ulula trionfante, ringraziandoti. Poi si accascia al suolo per riposare.', '', 28153),
(137435, 'itIT', 'Grazie. Ora posso riposare.', '', 28153),
(137434, 'itIT', '$gBenvenuto:Benvenuta; nel mio boschetto... o almeno ciò che ne resta.', '', 28153),
(137432, 'itIT', 'Nun ce la faccio, cumpà! Nun ce la faccio più!', '', 28153),
(137431, 'itIT', 'Nun ci pensare nemmeno, cumpà. Forse Hir\'eek darà a ME il potere se sacrificherò TE!', '', 28153),
(137430, 'itIT', 'Nun saremo più sacrificati! Levatevi, fratelli miei!', '', 28153),
(137429, 'itIT', 'Tu e la Gran Sacerdotessa potete anche marcire!', '', 28153),
(137428, 'itIT', 'Nun vivrò come nu animale!', '', 28153),
(137427, 'itIT', 'L\'Alta Sacerdotessa richiede un\'offerta come segno della tua sottomissione.\n', 'L\'Alta Sacerdotessa richiede un\'offerta come segno della tua sottomissione.\n', 28153),
(137426, 'itIT', 'Porta cibo o diventa cibo!', '', 28153),
(137425, 'itIT', 'Niente è mai facile come sembra a Vol\'dun.\n\nMi serve solo della legna per riparare la mia carovana.', '', 28153),
(137424, 'itIT', '', 'Ahahah... è troppo tardi... il Dio del Sangue... sta accà!', 28153),
(137423, 'itIT', '', 'L\'alfiere sarà completo presto! Nun riuscirai a fermarlo!', 28153),
(137422, 'itIT', 'Potrebbe sembrarti ridicolo, ma i ranishu sono un problema davvero serio.\n\nPerò fanno anche un po\' il solletico, in effetti.', '', 28153),
(137421, 'itIT', 'Nessuno potrà fermarci! Li uomini comanderanno!', '', 28153),
(137420, 'itIT', 'Faresti meglio a guardare le spalle tue, cumpà. Voi donne nun comanderete ancora per molto!', '', 28153),
(137419, 'itIT', 'Vedrai, cumpà. Io e i fratelli miei ce ne andremo da accà e regneremo su tutto quanto!', '', 28153),
(137418, 'itIT', 'Stai accà per punirmi ancora? Nun tremerò di fronte a te!', '', 28153),
(137417, 'itIT', 'Il sangue di Torga alimenterà il potere nostro!', '', 28153),
(137416, 'itIT', 'Il sangue di Torga è nostro mo\'!', '', 28153),
(137414, 'itIT', 'Porteremo la carne del Loa alli altri! Nun ci potrai fermare!', '', 28153),
(137413, 'itIT', 'La carne di Loa è nostra! Anche tu sei $gnostro:nostra;!', '', 28153),
(137412, 'itIT', '', 'Bene, ora abbiamo qualche strega di cui occuparci.', 28153),
(137411, 'itIT', '', 'Così rinasce l\'Ordine delle Braci.', 28153),
(137410, 'itIT', '', 'Il sapere al suo interno fornirà a te e alle nostre forze il potere per annientare la disgustosa congrega che affligge la nostra terra.', 28153),
(137409, 'itIT', '', 'Se vuoi seguire la strada dell\'Ordine, prendi il libro.', 28153),
(137408, 'itIT', '', 'Eccolo, l\'ultimo baluardo dell\'Ordine delle Braci. Qui rivivrai un\'antica storia.', 28153),
(137407, 'itIT', '', 'Vieni, il libro dovrebbe essere qui!', 28153),
(137406, 'itIT', '', 'Ma che dico, certo che stai bene. Serve ben altro che qualche pietra per toglierti di mezzo!', 28153),
(137405, 'itIT', '', 'Non avevo mai visto un costrutto di quelle dimensioni! Stai bene?', 28153),
(137404, 'itIT', '', 'Hir\'eek mi... vendicherà...', 28153),
(137403, 'itIT', '', 'L\'anima mia per G\'huun!', 28153),
(137402, 'itIT', '<Scegli di aiutare Henry Spezzafiumi e porre fine allo stallo.>', '<Scegli di aiutare Henry Spezzafiumi e porre fine allo stallo.>', 28153),
(137401, 'itIT', '', 'La carne del Loa è nostra!', 28153),
(137400, 'itIT', '', 'Alle tue spalle!', 28153),
(137399, 'itIT', '', 'Gloria... a Hir\'eek...', 28153),
(137398, 'itIT', '', 'Prendiamo la carne di Loa... e la MANGIAMO!', 28153),
(137397, 'itIT', '', 'Aspetta... c\'è qualcosa che non va.', 28153),
(137396, 'itIT', '', 'Mmm... Sembra che la strada sia bloccata dalle macerie. Potresti occupartene?', 28153),
(137395, 'itIT', '', 'Armati di questa conoscenza, i nostri iniziarono a respingere i Drust verso i loro rifugi montani.', 28153),
(137394, 'itIT', '', 'Con ciò che avevano appreso, scrissero un trattato sulle armi e le tattiche da utilizzare per sconfiggerli.', 28153),
(137393, 'itIT', '', 'Come dicevo, le sorti del conflitto cambiarono quando i nostri studiosi trovarono dei punti deboli nella magia dei Drust.', 28153),
(137392, 'itIT', '', 'Ti ringrazio. Per un attimo ho pensato che non ce l\'avrei fatta.', 28153),
(137391, 'itIT', '', 'Aspetta... attenzione!', 28153),
(137390, 'itIT', '', 'I Crestabianca sono sempre stati coraggiosi, ma la magia dei Drust era potente. Stavamo per perdere la guerra...', 28153),
(137389, 'itIT', '', 'I miei antenati affrontarono costrutti di pietra simili a questi nella guerra contro i Drust.', 28153),
(137388, 'itIT', '', 'Mi dispiace. La magia della congrega sta disturbando gli spiriti degli antichi Drust. Dovremo procedere con cautela.', 28153),
(137387, 'itIT', '', 'Attenzione!', 28153),
(137386, 'itIT', '', 'Aspetta... cos\'è stato?', 28153),
(137385, 'itIT', '', 'Continuarono per innumerevoli anni, fino a che gli antenati della Casata dei Crestabianca decisero di intervenire.', 28153),
(137384, 'itIT', '', 'Drustvar è sempre stata la loro dimora. Da qui partivano le infinite incursioni contro i nostri piccoli villaggi.', 28153),
(137383, 'itIT', '', 'Tanto tempo fa, quando si stabilì su Kul Tiras, la nostra gente entrò in contatto con un gruppo di selvaggi guerrafondai. Si facevano chiamare Drust.', 28153),
(137382, 'itIT', '', 'Sì! La via è libera!', 28153),
(137381, 'itIT', '', 'Ora non ci resta che trovare l\'entrata!', 28153),
(137380, 'itIT', '', 'Esso conserva un antico segreto della nostra casata, risalente a quando i Crestabianca si insediarono su questa terra.', 28153),
(137379, 'itIT', '', 'Non posso credere che siamo qui! Mio padre mi parlava spesso di questo luogo.', 28153),
(137378, 'itIT', '', 'Yah! Al Presidio di Arom, Bella!', 28153),
(137377, 'itIT', '', 'Bella, sii la sua ombra e porta le risorse che trova, d\'accordo?', 28153),
(137376, 'itIT', '<Scegli di aiutare Zannalunga e porre fine allo stallo.>', '<Scegli di aiutare Zannalunga e porre fine allo stallo.>', 28153),
(137375, 'itIT', '<Lo spirito del cacciatore Henry Spezzafiumi è troppo concentrato nell\'eterna battaglia per accorgersi di te.\n\nÈ bloccato in combattimento con lo spirito della lupa Zannalunga. Nessuno dei due è disposto a cedere il passo, nemmeno nella morte.>', '', 28153),
(137374, 'itIT', '<Lo spirito della potente lupa Zannalunga continua a combattere anche nella morte.\n\nÈ bloccata in un eterno combattimento con il cacciatore Henry Spezzafiumi.>', '', 28153),
(137296, 'itIT', '', 'Altro sangue per Hir\'eek!', 28153),
(137295, 'itIT', '', 'È ora di pigliare qualche capa!', 28153),
(137294, 'itIT', '', 'Ahahah, schiatterai accà!', 28153),
(137292, 'itIT', '', 'Hir\'eek berrà il sangue tuo!', 28153),
(137290, 'itIT', '', 'Sarai nu pasto delizioso per il pipistrello mio.', 28153),
(137289, 'itIT', '', 'Ti darò in pasto a Hir\'eek!', 28153),
(137287, 'itIT', '', 'Li Dei del Sangue mi avevano avvertito dell\'arrivo tuo!', 28153),
(137284, 'itIT', 'E così volete costruire un Bastione? Ah! Non fatemi ridere! Ahahah!', '', 28153),
(137282, 'itIT', 'Sotto con le armi pesanti! Della loro base non rimarranno che rovine.', '', 28153),
(137281, 'itIT', 'Bene, bene, bene... Sembra che gli scagnozzi dell\'Orda si siano finalmente decisi a mostrare i loro brutti musi!', '', 28153),
(137280, 'itIT', 'Mi indebolisco ogni momento di più. Devi... devi aiutarmi, prima che sia troppo tardi.', '', 28153),
(137279, 'itIT', 'Sei un talento naturale!', '', 28153),
(137278, 'itIT', 'E ovviamente la mia parte preferita: il salto! Dimostra la tua competenza equestre saltando gli ostacoli. Più riuscirai a saltare, più incredibili sembreranno le tue azioni!', '', 28153),
(137277, 'itIT', 'I Collorozzo ti hanno già fatto vedere il loro attrezzo preferito, le bolas! Fai pratica lanciandole contro gli zeppelin mentre sei a cavallo. Sono un po\' più rari, ma valgono molti più punti!', '', 28153),
(137276, 'itIT', 'L\'abilità in combattimento è un requisito importante per i cavalieri di Kul Tiras. Dimostra la tua prodezza con gli arpioni sui bersagli Gnoll!', '', 28153),
(137275, 'itIT', 'Potrebbe essere una combinazione dei due? Un orso fuorilegge... o un uomo-orso?', '', 28153),
(137274, 'itIT', 'Altre unghiate. Un fuorilegge e il suo famiglio orso, forse?', '', 28153),
(137271, 'itIT', 'O forse no. È come se stesse fuggendo da un fuorilegge o qualcosa del genere.', '', 28153),
(137270, 'itIT', 'Che strane ferite. Mi ricordano le unghiate lasciate dagli orsi. Anche a te?', '', 28153),
(137269, 'itIT', 'Tutto diventerà... deserto... anche Nazmir!', '', 28153),
(137268, 'itIT', 'Rivendico Nazmir nel nome dell\'Impero Sethrak!', '', 28153),
(137267, 'itIT', 'Sono sopravvissuto ai Troll del Sangue e mi tocca questo? Bah!', 'Sono sopravvissuta ai Troll del Sangue e mi tocca questo? Bah...', 28153),
(137266, 'itIT', 'Bah! Torga è morto e non sentirò alcuna storia.', 'Bah! Torga è morto e non sentirò alcuna storia.', 28153),
(137265, 'itIT', 'Cosa? Odio questo posto... non starò qui un secondo di più!', 'Cosa? Odio questo posto... non starò qui un secondo di più!', 28153),
(137264, 'itIT', 'Torga... è morto? Cos\'era tutto questo?', 'Torga... è morto? Cos\'era tutto questo?', 28153),
(137263, 'itIT', '', 'Che diavoleria è chesta? Mi piglierò la capa tua!', 28153),
(137262, 'itIT', '', 'Se n\'è andato. Mi toccherà raddoppiare la paga del custode per questa settimana.', 28153),
(137261, 'itIT', 'Eccellente! La caccia all\'elk è decisamente un\'attività più civile del catturare orsi!', '', 28153),
(137260, 'itIT', '', 'C\'è un piccolo accampamento a ovest che possiamo sfruttare...', 28153),
(137259, 'itIT', 'Ahah! Bello spettacolo! Continuate così!', '', 28153),
(137258, 'itIT', 'Via!', '', 28153),
(137257, 'itIT', 'Junji riesce sempre a mettersi nei guai. Sarebbe nu problema per lui se le lucertole lo trovassero prima di te!', '', 28153),
(137256, 'itIT', 'Pronti? Partenza...', '', 28153),
(137255, 'itIT', 'Nun sarà il cibo più delizioso al mondo, ma ci mantiene sazi.', '', 28153),
(137254, 'itIT', 'Ringhiadenti è schiattato e li alpaca dispersi sono stati recuperati. Mo\' dobbiamo solo preoccuparci che Mojambo nun ci accida tutti...', '', 28153),
(137253, 'itIT', 'Li alpaca nun sopravvivranno nel deserto da soli. Dobbiamo riportarli indietro!', '', 28153),
(137252, 'itIT', 'Il branco di alpaca nostri è scomparso. Dobbiamo trovarlo prima che sia troppo tardi!', '', 28153),
(137251, 'itIT', 'Il deserto è nu luogo desolato, ma si può trovare del cibo, se si sa dove cercare!', '', 28153),
(137250, 'itIT', 'Non sopravvivremo a lungo senza cibo e rifornimenti...', '', 28153),
(137249, 'itIT', 'Nun ci sarà mai pace fintanto che i Sethrak affliggeranno chesta terra.', '', 28153),
(137248, 'itIT', 'Procederemo quando sei $gpronto:pronta;.', '', 28153),
(137247, 'itIT', '$n ha conquistato la Nuova Fattoria!', '$n ha conquistato la Nuova Fattoria!', 28153),
(137246, 'itIT', 'L\'Alleanza ha preso il controllo della Nuova Fattoria!', 'L\'Alleanza ha preso il controllo della Nuova Fattoria!', 28153),
(137245, 'itIT', 'L\'Alleanza ha preso il controllo della Cresta della Scure!', 'L\'Alleanza ha preso il controllo della Cresta della Scure!', 28153),
(137244, 'itIT', '', 'Ti prego... Non mi rimane... molto tempo.', 28153),
(137243, 'itIT', '<Il Troll ha un taglio molto profondo, circondato da una strana schiuma verde.>', '', 28153),
(137242, 'itIT', '', 'Sono così preoccupata per mia nipote...', 28153),
(137241, 'itIT', '', 'Sono così felice che tu sia $gvivo:viva;, $p! Anche Dolly e Dot lo sono.', 28153),
(137240, 'itIT', '', 'Dolly e Dot sembrano piuttosto affamati. Trasportare un intero carico di Troll non è un compito semplice!', 28153),
(137239, 'itIT', '', 'Dolly e Dot sono forti e affidabili. Ci porteranno a destinazione.', 28153),
(137235, 'itIT', 'Siamo d\'accordo.', 'Siamo d\'accordo.', 28153),
(137234, 'itIT', '<Nickel mette il falco nella sua sacca.>', '', 28153),
(137233, 'itIT', 'Ma guarda, $gun impavido:un\'impavida; $C entra nel mio antro. Dimmi, $R, sei qui per stringere un patto con me?\n\nTempo fa decisi che ogni mio seguace avrebbe potuto seguire anche un altro Loa. Ma per ottenere un dono, be\'... per quello pretendo che tu diventi un simbolo del mio potere tra la gente di Zuldazar.\n\nSe desideri il mio dono, torna ai Gradini di Dazar ed erigi un santuario degno di un dio in mio nome.\n\nFallo, e ti considererò parte del mio branco. Siamo d\'accordo?', '', 28153),
(137226, 'itIT', 'Liberami.', 'Liberami.', 28153),
(137223, 'itIT', 'Salve, riccumpà. Cosa ti porta al Santuario delli Sciacalli oggi?', '', 28153),
(137212, 'itIT', 'Giorno uno: dovremmo raggiungere i Trogg delle Caverne Settentrionali per l\'ora di pranzo. Sento che troveremo qualcosa prima di cena! All\'avventura!', '', 28153),
(137175, 'itIT', '$n ha conquistato il Crocevia dei Norten!', '$n ha conquistato il Crocevia dei Norten!', 28153),
(137174, 'itIT', 'L\'Alleanza ha preso il controllo del Crocevia dei Norten!', 'L\'Alleanza ha preso il controllo del Crocevia dei Norten!', 28153),
(137162, 'itIT', 'Ah, n\'altra anima per G\'huun!', '', 28153),
(137161, 'itIT', 'Stupido sauride, sei schiattato ancora.', '', 28153),
(137157, 'itIT', 'Hek hek hek hek!', '', 28153),
(137156, 'itIT', '$n ha conquistato l\'Alto Osservatorio!', '$n ha conquistato l\'Alto Osservatorio!', 28153),
(137155, 'itIT', 'L\'Alleanza ha preso il controllo dell\'Alto Osservatorio!', 'L\'Alleanza ha preso il controllo dell\'Alto Osservatorio!', 28153),
(137154, 'itIT', 'Tutto questo... è piuttosto liberatorio!', '', 28153),
(137153, 'itIT', 'Aspetta... Joma! Joma, guardami!', '', 28153),
(137152, 'itIT', 'L\'Alleanza ha preso il controllo del Circolo degli Elementi!', 'L\'Alleanza ha preso il controllo del Circolo degli Elementi!', 28153),
(137151, 'itIT', '$n ha conquistato il Circolo degli Elementi!', '$n ha conquistato il Circolo degli Elementi!', 28153),
(137148, 'itIT', 'Forza papà!', '', 28153),
(137144, 'itIT', 'NO! NON RIESCO A CAVARMELA! VA TROPPO VELOCE!', '', 28153),
(137143, 'itIT', 'Bene, credo di riuscire a... cavarmela...', '', 28153),
(137142, 'itIT', 'Aaarrrgh!', '', 28153),
(137141, 'itIT', 'Aaargh! Squarciare! Uccidere!', '', 28153),
(137140, 'itIT', 'Uccidere! Uccidere! Uccidere!', '', 28153),
(137139, 'itIT', 'Grrr... schiacciare!', '', 28153),
(137138, 'itIT', 'Ti spezzo!', '', 28153),
(137137, 'itIT', 'Aaargh!', '', 28153),
(137135, 'itIT', 'Io... uccide... te...', '', 28153),
(137134, 'itIT', 'Si sbriciola...', '', 28153),
(137133, 'itIT', 'Sono... finito...', '', 28153),
(137132, 'itIT', 'Voi mio spuntino ora!', '', 28153),
(137131, 'itIT', 'Niente carne fresca!', '', 28153),
(137130, 'itIT', 'La terra vi distrugge!', '', 28153),
(137129, 'itIT', 'Vi mangio!', '', 28153),
(137128, 'itIT', 'Va bene, Joma. Portami alla zona d\'addestramento. Dovrebbe essere il posto ideale per... imparare a usare le redini. Eheh!', '', 28153),
(137127, 'itIT', 'D\'accordo, papà! Resisti!', '', 28153),
(137122, 'itIT', 'Questo... mio...', '', 28153),
(137121, 'itIT', 'Uccido... te...', '', 28153),
(137120, 'itIT', 'Ti... rompo...', '', 28153),
(137119, 'itIT', 'Ti rompo!', '', 28153),
(137118, 'itIT', 'Mangio!', '', 28153),
(137117, 'itIT', 'Uccido te!', '', 28153),
(137116, 'itIT', 'Questo mio tesoro!', '', 28153),
(137113, 'itIT', 'Harrison Jones è il mio eroe! Ma anche Brann Barbabronzea non è male.', '', 28153),
(137110, 'itIT', 'Ne hai preso uno!', '', 28153),
(137109, 'itIT', 'Ops! Hai acchiappato un granchio arrabbiato!', '', 28153),
(137108, 'itIT', 'La linea si è spezzata!', '', 28153),
(137107, 'itIT', 'Poz\'ga!', '', 28153),
(137106, 'itIT', 'Poz\'ga ti mangerà!', '', 28153),
(137105, 'itIT', 'Poz\'ga, vieni, scappiamo!', '', 28153),
(137104, 'itIT', '', 'Ti darò in pasto a Hir\'eek di persona!', 28153),
(137101, 'itIT', 'Pensi che ci sia roba dei Titani lassù? Io dico di sì. Per questo esistono i Trogg. Troverò le cose lasciate dai Titani.', '', 28153),
(137100, 'itIT', 'Quei bambini andranno in punizione per sempre!', '', 28153),
(137099, 'itIT', 'Mio nipote si mette sempre nei guai, ma in questo non c\'entra nulla!', '', 28153),
(137098, 'itIT', 'Squartamento', 'Squartamento', 28153),
(137097, 'itIT', 'Ehm... V-va bene. Direi che è il momento. Puoi aiutarmi?', '', 28153),
(137096, 'itIT', 'Avanti, usciamo da qui!', '', 28153),
(137095, 'itIT', 'Va bene, papà, abbiamo atteso anche troppo! Devi salire in groppa al cavallo!', '', 28153),
(137094, 'itIT', 'No, no, no, no, figlio mio, questo non è il cavallo per me. Eh, guarda la luce nei suoi occhi, mentre mi osserva. Non vede l\'ora di divorarmi!', '', 28153),
(137093, 'itIT', 'Questo mi piace. Credo sia il più bello! Papà?', '', 28153),
(137092, 'itIT', 'No, figlio mio. Non posso cavalcare questo. Sembra troppo... baldanzoso! Guarda quell\'andatura, eh! Le mie vecchie ossa non reggerebbero mai!', '', 28153),
(137091, 'itIT', 'Questo sembra carino!', '', 28153),
(137090, 'itIT', 'No, no, Joma. Questo non va bene. È troppo... mmm... irrequieto. Sì! Irrequieto! Credo si spaventerebbe al primo movimento brusco.', '', 28153),
(137089, 'itIT', 'E questo qui, papà?', '', 28153),
(137088, 'itIT', 'Bene, non perdiamo altro tempo. Bisogna trovare il cavallo perfetto!', '', 28153),
(137087, 'itIT', 'Prima di iniziare, lascia che mi prepari. Eheh! Solo un momento...', '', 28153),
(137086, 'itIT', 'Vi apriremo in due, pigliamo altro cibo!', '', 28153),
(137085, 'itIT', 'Sarai ottimo cibo per i padroni!', '', 28153),
(137084, 'itIT', 'Mio padre non fa che parlare di cavalli! Vorrebbe cavalcarne uno, ma credo abbia paura di loro.$b$bSo esattamente come aiutarlo!', '', 28153),
(137083, 'itIT', 'Dev\'essere chesto che i Sethrak stavano cercando!', '', 28153),
(137082, 'itIT', 'Dunque le storie incise sulle pietre runiche sono vere... la sfera esiste!', '', 28153),
(137080, 'itIT', '', 'La magia tua nun mi ingannerà!', 28153),
(137079, 'itIT', '', 'Le pozioni nun stanno ancora pronte! Va\' via!', 28153),
(137078, 'itIT', '', 'Parla. Perché disturbi la meditazione mia?', 28153),
(137077, 'itIT', 'Thun\'ka... l\'Avvizzitore...', '', 28153),
(137076, 'itIT', 'Thun\'ka... l\'Avvizzitore...', '', 28153),
(137075, 'itIT', '', 'Grazie per l\'aiuto, $gstraniero:straniera;. Ricorda di tenere il sale fuori dai pantaloni.', 28153),
(137074, 'itIT', 'Preparati. Questa festa sta per diventare molto più interessante.', '', 28153),
(137073, 'itIT', 'Furfante! La pagherai per questo!', 'Furfante! La pagherai per questo!', 28153),
(137071, 'itIT', 'Non potete nulla di fronte al nostro impero!', 'Non potete nulla contro il nostro impero!', 28153),
(137068, 'itIT', 'Il potere di queste rovine appartiene a noi!', 'Il potere di queste rovine appartiene a noi!', 28153),
(137067, 'itIT', 'Non potete avere il potere! Sarà nostro!', 'Non potete avere il potere! Sarà nostro!', 28153),
(137066, 'itIT', '', 'Non capita tutti i giorni di ottenere il favore di un Elementale dell\'Acqua.', 28153),
(137065, 'itIT', '', 'Ammiro la tua passione. Vai, innalza una statua nel mio nome davanti alle scalinate di Dazar\'alor, così che tutti i Troll di questa terra sappiano del tuo patto con me.', 28153),
(137063, 'itIT', '', 'Ahah! Non intendevo letteralmente.', 28153),
(137062, 'itIT', '<Attiva il Colosso>', '<Attiva il Colosso>', 28153),
(137061, 'itIT', '<L\'antico costrutto comincia a illuminarsi al tuo arrivo.>', '<L\'antico costrutto comincia a illuminarsi al tuo arrivo.>', 28153),
(137056, 'itIT', 'Non osare intrappolarmi ancora una volta, Sciamano. Ti disintegrerò!', '', 28153),
(137055, 'itIT', 'Oh! Non sembri proprio uno di quei nobili altezzosi. Vieni a farti una bevuta con noi! Abbiamo lasciato le montagne su invito di Ser Norwington per festeggiare ed è esattamente quello che faremo!', '', 28153),
(137054, 'itIT', 'Nun ti vogliamo qui... chesto è nu ponte dei Troll!', '', 28153),
(137053, 'itIT', 'Guarda questi magnifici cavalli. Abbiamo attraversato il continente per partecipare a questa festa e non vedo l\'ora di imparare di più su queste magnifiche bestie.$b$bNobili, potenti... instillano fascino e paura nel mio vecchio cuore.', '', 28153),
(137052, 'itIT', 'L\'Avvizzitore consumerà questa valle!', '', 28153),
(137051, 'itIT', 'L\'Orda ha riconquistato Ar\'gorok!', 'L\'Orda ha riconquistato Ar\'gorok!', 28153),
(137050, 'itIT', '', 'C\'è una nuova potenza nella mia dimora. Fatti avanti, $p dell\'Orda, così che io possa vederti per ciò che sei.$b$b$R e $C, e $gun vero campione:una vera campionessa;.$b$bIl Signore del Maleficio mi ha riferito che desideri il mio dono, ma prima voglio qualcosa in cambio, cosa che chiedo a tutti coloro con cui scendo a patti.$b$BRichiedo un atto di fede...', 28153),
(137049, 'itIT', 'Vieni, è ora di mettere fine a questo culto!', '', 28153),
(137048, 'itIT', 'D-Davvero? Credo che dovremmo accettare l\'offerta sua!', '', 28153),
(137047, 'itIT', 'Bah! Sono sopravvissuto a molte cose, so che nun vincerai.', '', 28153),
(137046, 'itIT', 'La gente vostra è condannata! Unitevi a me... e sarete salvati.', '', 28153),
(137045, 'itIT', 'Accetto.', 'Accetto.', 28153),
(137041, 'itIT', 'Ah, $gil nostro stimato eroe:la nostra stimata eroina;! $gBenvenuto, benvenuto:Benvenuta, benvenuta;. Serviti pure con cibo e bevande. Se hai bisogno di altro, fammi sapere e sarò felice di aiutarti.', '', 28153),
(137040, 'itIT', 'Qui è dove ci occupiamo dei nostri cavalli. Sia i proprietari che gli stallieri si impegnano al meglio per curarli come meritano.', '', 28153),
(137039, 'itIT', '', 'Cosa vuoi chiedere alla Loa dei Cieli?', 28153),
(137038, 'itIT', '', 'Andrò a nascondermi con Marcus!', 28153),
(137037, 'itIT', '', 'Grazie! Stavo finendo le rocce quassù!', 28153),
(137036, 'itIT', 'Muori, $gintruso:intrusa;!', '', 28153),
(137035, 'itIT', '', 'Il potere di Zardrax scorre dentro di me!', 28153),
(137034, 'itIT', '', 'Il potere di Zardrax ti distruggerà!', 28153),
(137033, 'itIT', 'Tornerò a Zul\'jan. Devo vedere se qualcun altro è uscito pazzo e vuole unirsi ai Troll del Sangue.', '', 28153),
(137032, 'itIT', 'Kal\'dran era troppo debole per capire che avremmo vinto. Peccato, eh?', '', 28153),
(137031, 'itIT', 'Buona fortuna. Uccidi Zardrax prima che corrompa tutti quanti al fianco suo.', '', 28153),
(137030, 'itIT', 'Lascia che se ne occupi $n. Ucciderà chella Malefica di cui parli.', '', 28153),
(137029, 'itIT', 'Nun so, Da\'jul... $n nun riuscirà a fermare tutto chesto! Schiatteremo tutti!', '', 28153),
(137028, 'itIT', '', 'Vado a trovare Marcus! Ci vediamo lì!', 28153),
(137027, 'itIT', '', 'Oh, grazie! Si stava un po\' scomodi qui dentro.', 28153),
(137026, 'itIT', '', 'Tutto questo è troppo per me. Basta, me ne vado!', 28153),
(137025, 'itIT', 'L\'Alleanza ha attaccato la Miniera!', '', 28153),
(137024, 'itIT', '$n ha attaccato la Miniera!', '', 28153),
(137023, 'itIT', 'Inizierò a riempire il lago immediatamente.', '', 28153),
(137022, 'itIT', 'Un\'essenza così forte... Dev\'essere opera di Sumber.', '', 28153),
(137021, 'itIT', 'Andrò da Marcus e attenderò assieme a lui. Ci vediamo là!', '', 28153),
(137020, 'itIT', 'Ehi, grazie! Chi pensava che i Trogg sapessero usare la magia?', '', 28153),
(137019, 'itIT', 'Ritorno... da Sumber.', '', 28153),
(137018, 'itIT', 'Sono rinato!', '', 28153),
(137017, 'itIT', 'Sono cresciuto sentendo storie dei selvaggi Troll del Sangue. Ma chesto è molto peggio.', '', 28153),
(137016, 'itIT', 'Kal\'dran! $n, devi seguirlo... e acciderlo, se dovesse essere necessario.', '', 28153),
(137015, 'itIT', 'Siamo tutti quanti CONDANNATI! Zardrax ci salverà e chiunque proverà a ostacolarmi verrà acciso!', '', 28153),
(137013, 'itIT', 'Non riesco... a resistere...', '', 28153),
(137012, 'itIT', 'Ti do il benvenuto al Festival Equestre dei Norwington! Siamo ancora occupati con i preparativi, ma non devi perderti assolutamente la festa. Io non lo farei per nessuna ragione!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137011, 'itIT', 'Andate! Non c\'è più niente per voi qui!', '', 28153),
(137010, 'itIT', 'Ora, $C!', '', 28153),
(137009, 'itIT', 'Non ascoltate le sue menzogne o vi condannerete da soli!', '', 28153),
(137008, 'itIT', 'Ser Vallecupa è morto! La sua sete di potere l\'ha condotto alla rovina!', '', 28153),
(137007, 'itIT', 'Ho visto... il volto di G\'huun... Nun ci sta speranza...', '', 28153),
(137006, 'itIT', 'Nun ci sta speranza! Perché nun ti unisci a Zardrax?', '', 28153),
(137005, 'itIT', 'Grazie ancora, $C. Sei $garrivato:arrivata; giusto in tempo!', '', 28153),
(137003, 'itIT', 'Hai condannato... questa terra...', '', 28153),
(137002, 'itIT', 'Non interferire, $gstraniero:straniera;, a meno che non voglia far parte anche tu del sacrificio!', '', 28153),
(137001, 'itIT', 'Questa gente è pazza! Aiutami, $C!', '', 28153),
(137000, 'itIT', 'L\'Uomo di Vimini dev\'essere soddisfatto, o le nostre sventure continueranno!', '', 28153),
(136999, 'itIT', 'Vuoi calmarti?!? La tua morte servirà per uno scopo più grande!', '', 28153),
(136998, 'itIT', 'Questo è omicidio e non vi servirà a niente!', '', 28153),
(136997, 'itIT', 'Sembra che tu ne abbia ridotto notevolmente il numero. Penso riuscirò a cavarmela da solo da qui in poi.', '', 28153),
(136996, 'itIT', 'Grazie, $gstraniero:straniera;! Pensavo che quelle api mi avrebbero ucciso!', '', 28153),
(136995, 'itIT', 'Mi sono entrate negli occhi! Negli occhi!!!', '', 28153),
(136994, 'itIT', 'Non le api! Nooo!', '', 28153),
(136993, 'itIT', '$C! È bello vedere un viso ami... aspetta, cosa sono quelle?', '', 28153),
(136992, 'itIT', 'Sia lode all\'Uomo di Vimini!', 'Sia lode all\'Uomo di Vimini!', 28153),
(136991, 'itIT', 'Guarda, $n! Questo è Magoo, il mio nuovo cavallo. Non è fantastico?$b$bMi manca Passolesto, era un bravo pony. A volte però si agitava troppo! Cercherò di creare un legame più forte con Magoo, così potrò capire quando è nervoso.$b$bVoglio diventare un bravo fantino e continuerò ad allenarmi con Melissa. Insieme possiamo diventare i migliori!', '', 28153),
(136990, 'itIT', 'Radunatevi di fronte all\'Uomo di Vimini, iniziati. La sua benevolenza ci proteggerà dalle maledizioni che hanno colpito questa terra.', '', 28153),
(136989, 'itIT', '', 'Non potrò mai ringraziarti abbastanza per aver salvato Eddie. È un bravo ragazzo e diventerà un bravo fantino.$b$bContinueremo a cavalcare nella villa ancora per un po\', però.', 28153),
(136988, 'itIT', 'Troppo... debole...', '', 28153),
(136987, 'itIT', 'Agli ordini, ma\'ma. Obbedisco!', '', 28153),
(136986, 'itIT', 'Mi manda Kejabu.', 'Mi manda Kejabu.', 28153),
(136985, 'itIT', 'Ma se ti unirai a me, potrai ricevere assai più potere di quanto tu abbia mai immaginato!', '', 28153),
(136984, 'itIT', 'Se cercherai di combattere, sarai $gschiacciato:schiacciata; dalle forze nostre.', '', 28153),
(136983, 'itIT', 'Nun tenete scelta. Zuldazar è condannata. G\'huun verrà liberato!', '', 28153),
(136982, 'itIT', 'La vita tua sarà risparmiata se mi servirai. G\'huun l\'ha promesso.', '', 28153),
(136981, 'itIT', 'G\'huun consumerà tutto quanto. Nun ci sta speranza!', '', 28153),
(136980, 'itIT', 'Ahah... sei forte! Ma tutti quanti cadranno dinnanzi a G\'huun. L\'offerta mia è sempre valida...', '', 28153),
(136979, 'itIT', 'Aspetta, forse possiamo lavorare con Zardrax! Come potremmo fermare tutto quanto chesto sennò?', '', 28153),
(136978, 'itIT', '$n nun si schiererà mai dalla parte tua! Mostra a chesto Lich cosa pensi dell\'offerta sua!', '', 28153),
(136977, 'itIT', 'Servimi e otterrai la salvezza... e ti darò parte del potere di G\'huun.', '', 28153),
(136976, 'itIT', 'Zuldazar cadrà di fronte ai Troll del Sangue e a G\'huun. Ma nun serve che tu condivida il destino suo.', '', 28153),
(136975, 'itIT', 'Bene, dimmi qual è la tua offerta.', 'Bene, dimmi qual è la tua offerta.', 28153),
(136974, 'itIT', 'Unisciti a me e ti salverai dalla distruzione di Zuldazar!', '', 28153),
(136973, 'itIT', 'Siamo condannati! Come possiamo sperare di fermare na cosa del genere?', '', 28153),
(136972, 'itIT', 'Quante fonti di potere tengono chesti Troll del Sangue?', '', 28153),
(136969, 'itIT', '', 'Eccellente! Hai scelto con saggezza. Vieni, vola con me e incontra il patrono tuo.', 28153),
(136968, 'itIT', 'Ah! Sapevo che avresti fatto la scelta giusta. Vieni accà e ti farò volare fino a vedere Pa\'ku faccia a faccia.', '', 28153),
(136967, 'itIT', 'Vorrei scegliere un Loa differente.', 'Vorrei scegliere un Loa differente.', 28153),
(136966, 'itIT', 'Nooo! Verme dell\'Orda! Strapperò la vita dal corpo tuo.', '', 28153),
(136965, 'itIT', 'Nun vi fermate! Tengo bisogno che nun vi fermiate!', '', 28153),
(136964, 'itIT', 'Datemene ancora! Datemelo tutto!', '', 28153),
(136963, 'itIT', 'Ancora! Ne voglio ancora!', '', 28153),
(136962, 'itIT', 'Sììì... Sììì... SÌÌÌ!!!', '', 28153),
(136961, 'itIT', '', 'Stai in ritardo! Se il pipistrello mio morirà per chesto, la capa tua decorerà la capanna mia!', 28153),
(136960, 'itIT', 'Siete alleati inaspettati in questa battaglia.', '', 28153),
(136959, 'itIT', 'Be\'... sì, è giusto.', '', 28153),
(136958, 'itIT', '', 'Va bene, Eddie. Le lezioni di equitazione continueranno alla tenuta, per ora.', 28153),
(136957, 'itIT', '', 'Non c\'è tempo per il sentimentalismo, Gran Supremo!', 28153),
(136956, 'itIT', 'Dev\'esserci un altro modo, Capoguerra!', '', 28153),
(136954, 'itIT', '', 'Raal, brutto idiota! Ci hai lasciati scoperti. Ci sta nu rituale dei cultisti del sangue sulla vetta nostra.', 28153),
(136953, 'itIT', 'L\'ultima barriera... cadrà... e G\'huun... sarà libero!', '', 28153),
(136952, 'itIT', 'No... il legame mio con G\'huun... sta svanendo?', '', 28153),
(136951, 'itIT', 'Diffonderò il potere di G\'huun! Nun mi fermerai!', '', 28153),
(136950, 'itIT', '$gSciocco:Sciocca;! Il potere di G\'huun sta dentro di me! Nun cadrò!', '', 28153),
(136949, 'itIT', '$gPiccolo presuntuoso:Piccola presuntuosa; $PR. Avvicinati, vorrei scambiare due parole con te.', '', 28153),
(136948, 'itIT', '', 'Ah... nessuno fermerà Zardrax... il potere suo... ci permetterà di distruggere... Zuldazar...', 28153),
(136947, 'itIT', '', 'Con il potere di Zardrax e G\'huun, saremo inarrestabili!', 28153),
(136945, 'itIT', 'Ben fatto, $C, hai ottenuto la mia fiducia. Ti aiuterò con la tua missione.', '', 28153),
(136944, 'itIT', '', 'Di sicuro sembra essere... più presente.', 28153),
(136943, 'itIT', 'Mi sembra che si sia mosso! No... aspetta... forse era solo il vento.', '', 28153),
(136942, 'itIT', 'Accetta le nostre offerte, Uomo di Vimini, e donaci la tua benedizione!', '', 28153),
(136941, 'itIT', 'Hai portato le ossa? Perfetto! A questa cosa piacciono le ossa, ovviamente.', '', 28153),
(136940, 'itIT', 'Ah, delle viscere! Sono sicuro che potremmo... farci qualcosa con quelle.', '', 28153),
(136939, 'itIT', 'Vedo che hai portato del vimini. Scelta ovvia, ma non meno corretta.', '', 28153),
(136938, 'itIT', '', 'No, no, no! Quelle sono erbe da cucina, non vanno bene per un rituale! Non capisci la differenza?!?', 28153),
(136937, 'itIT', '', 'Cosa stai facendo con quel grano? Non siamo qui per riempire degli spaventapasseri!', 28153),
(136936, 'itIT', 'Oh, hai portato le pergamene... Sebbene concordo siano vitali per risvegliare l\'Uomo di Vimini, be\'... nessuno di noi è in grado di leggerle.', '', 28153),
(136935, 'itIT', 'Un frutto? Sei $gserio:seria;?!? È davvero $gserio:seria;, vero?', '', 28153),
(136934, 'itIT', 'Ce l\'abbiamo fatta. Sylvanas finalmente risponderà dei suoi crimini. Campioni, al mio fianco...', '', 28153),
(136929, 'itIT', '<Heiro suona con noncuranza il suo tamburino e ti fa l\'occhiolino.>', '', 28153),
(136927, 'itIT', 'Dubito che ti rivedrò, $n. Grazie.', '', 28153),
(136925, 'itIT', '', 'Vol\'dun ci ha messi di fronte a ben peggio. Ce la caveremo.', 28153),
(136919, 'itIT', 'Credo di poter raggiungere Melissa se mi apri un passaggio. Grazie mille per avermi salvato!', '', 28153),
(136918, 'itIT', 'È... È sicuro là fuori? I Trogg mi fanno davvero paura!', '', 28153),
(136917, 'itIT', '$n ha conquistato la Cresta della Scure!', '$n ha conquistato la Cresta della Scure!', 28153),
(136916, 'itIT', 'Ti lascio da Loti. Falle sapere che la sorgente di tutto chesto potrebbe essere dentro Zanchul.', '', 28153),
(136915, 'itIT', 'Mmm, qualcosa nun va. Percepisco na fonte di potere dentro Zanchul.', '', 28153),
(136914, 'itIT', 'Nun passa settimana senza che qualche Zandalari si faccia corrompere dalla magia del sangue appresa dalli eretici di Nazmir.', '', 28153),
(136913, 'itIT', 'Le difese nostre sono sempre più deboli. La Principessa Talanji ha già richiesto altre truppe. Il padre suo nun ha agito velocemente, quindi lei si è rivolta all\'Orda.', '', 28153),
(136912, 'itIT', 'In chel momento abbiamo avuto il primo assaggio della vera magia del sangue. Nun la robetta delle tribù minori.', '', 28153),
(136911, 'itIT', 'Qualche anno fa, chesta terra tremò durante il Cataclisma. I cancelli settentrionali nostri sono caduti e sono arrivati i Troll del Sangue a sciami.', '', 28153),
(136910, 'itIT', 'Ti indicherò i punti migliori, ma tu puoi tenere l\'onore di lanciare nu Totem Avvistatore.', '', 28153),
(136909, 'itIT', '<Un piccolo sacchetto di mangime per cavalli si trova abbandonato per terra. Esaminando il sacchetto, trovi il nome di Eddie cucito sul tessuto.>$b$b<Deve essere passato di qui, anche se non sembra per sua scelta. Noti una scia di pezzi di cibo in direzione dell\'altura.>', '<Un piccolo sacchetto di mangime per cavalli si trova abbandonato per terra. Esaminando il sacchetto, trovi il nome di Eddie cucito sul tessuto.>$b$b<Deve essere passato di qui, anche se non sembra per sua scelta. Noti una scia di pezzi di cibo in direzione dell\'altura.>', 28153),
(136908, 'itIT', 'Non so quanto a lungo potremo sopravvivere contro i Sethrak...', '', 28153),
(136907, 'itIT', 'È evidente che nun provieni da Zuldazar, o sapresti esattamente chi sono. Ero lo chef personale del Generale Jakra\'zet!$b$bFui mandato in esilio dopo che il generale si ammalò mangiando uno dei piatti miei... ma nun fu colpa mia!$b$bLi altri cuochi mi invidiavano e uno di loro deve aver avvelenato il piatto mio mentre ero distratto!$b$bNu giorno troverò le prove dell\'innocenza mia, ma per ora mi tocca cucinare stercorari per sopravvivere.', '', 28153),
(136906, 'itIT', 'ALLEANZA, RESTARE IN POSIZIONE!', '', 28153),
(136905, 'itIT', 'Come sei finito a Vol\'dun?', 'Come sei finito a Vol\'dun?', 28153),
(136904, 'itIT', 'Fai domande pericolose, $C.\n\nNun intendo nascondere il passato mio, ma li altri nun la pensano allo stesso modo.\n\nQuando ero nu guaglione, fui esiliato con la famiglia mia. Mio padre teneva nu grande debito da saldare e in chei giorni i bambini venivano esiliati insieme ai genitori.\n\nEro solo e quasi schiattato di sete quando Razgaji mi trovò e mi prese con sé. Da chel giorno, nun ho più smesso di seguirli...', '', 28153),
(136903, 'itIT', 'Come sei finito a Vol\'dun?', 'Come sei finito a Vol\'dun?', 28153),
(136902, 'itIT', '', 'Tu, laggiù, nun ho mai visto la faccia tua prima d\'ora. Vieni, parla con me.', 28153),
(136901, 'itIT', '', 'Hir\'eek è compiaciuto... ma servirà altro sangue! Ci serve nu sacrificio!', 28153),
(136900, 'itIT', '', 'Grande Hir\'eek, Loa dei Pipistrelli e servitore di G\'huun. Ti offro chesto sacrificio!', 28153),
(136899, 'itIT', '', 'Puoi trovare il Signore del Maleficio Raal dall\'altra parte della Terrazza. Assicurati di porgergli li insulti miei.', 28153),
(136895, 'itIT', 'Il tuo tempo è scaduto, Re Anduin!', '', 28153),
(136894, 'itIT', 'Se fuggissimo adesso, diverremmo solo prede facili. No: combatteremo... e moriremo, se necessario, per ciò in cui crediamo!', '', 28153),
(136889, 'itIT', '', 'Parla o strapperemo la lingua tua e la useremo per il prossimo rituale.', 28153),
(136888, 'itIT', '', 'Hir\'eek ci fornisce la prole sua e il Dio del Sangue ci dona il potere. Insieme siamo inarrestabili!', 28153),
(136887, 'itIT', '', 'Che c\'è? Parla in fretta o sarai tu il prossimo sacrificio.', 28153),
(136882, 'itIT', 'Afferramento corda', 'Afferramento corda', 28153),
(136878, 'itIT', '', 'La guerra ci impone di adottare un approccio più diretto.', 28153),
(136876, 'itIT', '', 'Serpenti! Attenzione!', 28153),
(136874, 'itIT', 'Hai parlato con Gonk? È il Signore del Branco. Egli parlò con alcuni Lanciascura, insegnando loro le vie dei Druidi.$b$bPerò, per noi è molto più che na voce. Possiamo ascoltare le parole sue di persona. Nun è nu concetto, è na cosa reale.', 'Hai parlato con Gonk? È il Signore del Branco. Egli parlò con alcuni Lanciascura, insegnando loro le vie dei Druidi.$b$bPerò, per noi è molto più che na voce. Possiamo ascoltare le parole sue di persona. Nun è nu concetto, è na cosa reale.', 28153),
(136872, 'itIT', 'Gonk è il Loa che ha insegnato a tutti quanti i Troll come espandere la propria influenza alli altri Loa e diventare Druidi. Glie ne saremo sempre grati per sempre.', 'Gonk è il Loa che ha insegnato a tutti quanti i Troll come espandere la propria influenza alli altri Loa e diventare Druidi. Glie ne saremo sempre grati per sempre.', 28153),
(136871, 'itIT', 'I seguaci di Pa\'ku stanno furenti per come Raal sia stato abbandonato da Loti. Molto triste. Poco professionale.', 'I seguaci di Pa\'ku stanno furenti per come Raal sia stato abbandonato da Loti. Molto triste. Poco professionale.', 28153),
(136870, 'itIT', 'I seguaci di Gonk sono furenti per il modo in cui Raal ha abbandonato la Druida da Guerra Loti. Molto triste. Poco professionale.', 'I seguaci di Gonk sono furenti per il modo in cui Raal ha abbandonato la Druida da Guerra Loti. Molto triste. Poco professionale.', 28153),
(136869, 'itIT', 'Qualsiasi cosa farai, nun ascoltare le bugie dei seguaci di Gonk. Sono solo gelosi di quanto sia grande Pa\'ku, la Loa nostra.', 'Qualsiasi cosa farai, nun ascoltare le bugie dei seguaci di Gonk. Sono solo gelosi di quanto sia grande Pa\'ku, la Loa nostra.', 28153),
(136868, 'itIT', 'Io rispondo a Pa\'ku, Loa dei Venti e protettrice della flotta nostra. È na Loa come nessun altro. Ti consiglio di avere a che fare con lei invece che con li altri. Nun fidarti di loro.', 'Io rispondo a Pa\'ku, Loa dei Venti e protettrice della flotta nostra. È na Loa come nessun altro. Ti consiglio di avere a che fare con lei invece che con li altri. Nun fidarti di loro.', 28153),
(136867, 'itIT', 'Mmm, $p. I Loa hanno sussurrato il nome tuo. L\'arrivo tuo a Zuldazar sarà interessante assai.', 'Mmm, $p. I Loa hanno sussurrato il nome tuo. L\'arrivo tuo a Zuldazar sarà interessante assai.', 28153),
(136866, 'itIT', 'Pa\'ku è la Loa dei Venti e la signora delli esploratori e della flotta nostra. È na Loa impulsiva che adora la libertà. Parla con il campione suo, il Signore del Maleficio Raal, se desideri sapere altro.', 'Pa\'ku è la Loa dei Venti e la signora delli esploratori e della flotta nostra. È na Loa impulsiva che adora la libertà. Parla con il campione suo, il Signore del Maleficio Raal, se desideri sapere altro.', 28153),
(136865, 'itIT', 'Ah! $gL\'eroe:L\'eroina; dell\'Orda. Il Signore del Maleficio Raal resterà colpito da te. Stai in sintonia con lui, stai in sintonia con Pa\'ku e stai in sintonia con me.', 'Ah! $gL\'eroe:L\'eroina; dell\'Orda. Il Signore del Maleficio Raal resterà colpito da te. Stai in sintonia con lui, stai in sintonia con Pa\'ku e stai in sintonia con me.', 28153),
(136864, 'itIT', 'Qui la presenza tua nun è gradita.', 'Qui la presenza tua nun è gradita.', 28153),
(136863, 'itIT', 'Nun tengo nulla da dirti.', 'Nun tengo nulla da dirti.', 28153),
(136862, 'itIT', 'Devi esserti $gperso:persa;. Sappi che nun dovresti stare accà.', 'Devi esserti $gperso:persa;. Sappi che nun dovresti stare accà.', 28153),
(136861, 'itIT', 'Senza casta. Bah!', 'Senza casta. Bah!', 28153),
(136860, 'itIT', 'Nun osare rivolgermi la parola.', 'Nun osare rivolgermi la parola.', 28153),
(136859, 'itIT', '', 'Come previsto, il mio lavoro è perfetto. Qualcosa deve aver tappato le tubature. Ti andrebbe di dare uno sguardo?', 28153),
(136858, 'itIT', '', 'Darò uno sguardo ravvicinato a questa fontana.', 28153),
(136857, 'itIT', 'Userò il sangue tuo per il prossimo rituale.', 'Userò il sangue tuo per il prossimo rituale.', 28153),
(136856, 'itIT', 'Feccia dell\'Orda ficcanaso!', 'Feccia dell\'Orda ficcanaso!', 28153),
(136855, 'itIT', 'Nun potrai fermarci tutti!', 'Nun potrai fermarci tutti!', 28153),
(136854, 'itIT', 'Pensavi che solo io sapessi usare la magia del sangue? Preparati a na brutta sorpresa.', 'Pensavi che solo io sapessi usare la magia del sangue? Preparati a na brutta sorpresa.', 28153),
(136853, 'itIT', 'Bah! Nun mi farò sconfiggere da nu membro dell\'Orda $gimpiccione:impicciona;!', 'Bah! Nun mi farò sconfiggere da nu membro dell\'Orda $gimpiccione:impicciona;!', 28153),
(136852, 'itIT', 'Nun dovevate tenere d\'occhio voi stolti volanti chei Troll del Sangue? Perché dobbiamo fare noi il lavoro vostro?', 'Nun dovevate tenere d\'occhio voi stolti volanti chei Troll del Sangue? Perché dobbiamo fare noi il lavoro vostro?', 28153),
(136851, 'itIT', 'Nun interferirai con il rituale nostro. Se ne occuperà Loti.', 'Nun interferirai con il rituale nostro. Se ne occuperà Loti.', 28153),
(136850, 'itIT', 'Voi fanatici volanti sarete la fine di Zandalar.', 'Voi fanatici volanti sarete la fine di Zandalar.', 28153),
(136849, 'itIT', 'Raal vi darà in pasto tutti quanti al Loa del Re, se isso continua a darci problemi.', 'Raal vi darà in pasto tutti quanti al Loa del Re, se isso continua a darci problemi.', 28153),
(136848, 'itIT', '', 'Quell\'armata è enorme. Dammi l\'ordine e teletrasporterò tutti al sicuro.', 28153),
(136846, 'itIT', 'Segui ancora Loti? Ah! Sei più idiota di n\'escremento di brutosauro.', 'Segui ancora Loti? Ah! Sei più idiota di n\'escremento di brutosauro.', 28153),
(136845, 'itIT', 'Siete voi quelli in minoranza, adesso.', '', 28153),
(136844, 'itIT', 'Raal presto comanderà chesto posto e scaccerà tutti voi fanatici dei raptor nelle terre selvagge a cui appartenete.', 'Raal presto comanderà chesto posto e scaccerà tutti voi fanatici dei raptor nelle terre selvagge a cui appartenete.', 28153),
(136843, 'itIT', 'Il nome del Loa tuo è Gonk. Dovresti vergognarti di questo.', 'Il nome del Loa tuo è Gonk. Dovresti vergognarti di questo.', 28153),
(136842, 'itIT', 'Voi sporchi Druidi state sempre a raschiare il fondo. Nun siete migliori dei Gurubashi.', 'Voi sporchi Druidi state sempre a raschiare il fondo. Nun siete migliori dei Gurubashi.', 28153),
(136841, 'itIT', 'Nun sei meglio di me. O sangue mio... sta sulle mani tue.', '', 28153),
(136840, 'itIT', 'Si salvi chi Troll! Accidi o schiatta!', '', 28153),
(136838, 'itIT', '<Trovi il corpo freddo e immobile del pony di Eddie, Passolesto.>$b$b<Delle briciole conducono in cima all\'altura. Pare che Eddie abbia lasciato una traccia.>', '<Trovi il corpo freddo e immobile del pony di Eddie, Passolesto.>$b$b<Delle briciole conducono in cima all\'altura. Pare che Eddie abbia lasciato una traccia.>', 28153),
(136837, 'itIT', 'Piccino è boccone gustoso!', '', 28153),
(136836, 'itIT', 'Sono qui! Ha la chiave! Ti prego, aiutami!', '', 28153),
(136835, 'itIT', '', 'Andiamo, $n. Ser Norwington vorrà la mia testa se dovesse succedere qualcosa a suo figlio!', 28153),
(136832, 'itIT', 'Siamo na tribù di esiliati, cacciati da Zuldazar e abbandonati nel deserto a morire. Alcuni di noi sono stati accusati ingiustamente di crimini mai commessi... per li altri è stato nu destino meritato.$b$bL\'unica cosa che ora conta per noi è la sopravvivenza.$b$bObbedisci alle leggi nostre e il tuo posto tra di noi sarà assicurato.$b$bIgnorale e scoprirai che la giustizia nostra è ben più rapida di chella di Re Rastakhan.', '', 28153),
(136831, 'itIT', 'Che ti serve, ma\'ma?', '', 28153),
(136830, 'itIT', 'Che c\'è? Tu... nun sei tu il prossimo sacrificio, vero?', '', 28153),
(136829, 'itIT', 'Le Sacerdotesse! Ci accideranno tutti quanti!', '', 28153),
(136828, 'itIT', 'Chesto sarà assai più violento senza il travestimento tuo.', '', 28153),
(136827, 'itIT', 'Parlami della tua tribù.', 'Parlami della tua tribù.', 28153),
(136825, 'itIT', '', 'Chesto è lo scudo di Rakera... Dov\'è?!? Cosa le hai fatto!?!', 28153),
(136824, 'itIT', 'È colpa di Jakra\'zet, nun mia. Rakera è l\'unica ragione per cui ancora sono vivo.', '', 28153),
(136823, 'itIT', '', 'Meerah, ferma la carovana! Vedo qualcosa più avanti!', 28153),
(136822, 'itIT', '', 'Come ha fatto Rakera a sopravvivere accà?', 28153),
(136820, 'itIT', '', 'Riesci a credere che questa landa desolata era un tempo il gioiello dell\'impero dei Troll? Una giungla colma di vita... e ciò che ne rimane ora è sepolto sotto la sabbia.', 28153),
(136819, 'itIT', '', 'Kiro si preoccupa per nulla. Ho fatto un sacco di pratica! Magari, però, è meglio... se ti tieni.', 28153),
(136818, 'itIT', '', 'Lo faccio sempre!', 28153),
(136816, 'itIT', 'Ma solo con l\'aiuto di $gchesto prode:chesta prode; $C. Il mojo suo è incredibile. Ne sento l\'odore.', '', 28153),
(136815, 'itIT', 'Sei come tutti quanti li altri folli che vanno a Naz... cosa?', 'Sei come tutti quanti li altri folli che vanno a Naz... cosa?', 28153),
(136814, 'itIT', 'Bah! Senti, andrò laggiù e ti mostrerò che chesto è uscito pazzo.', 'Bah! Senti, andrò laggiù e ti mostrerò che chesto è uscito pazzo.', 28153),
(136813, 'itIT', 'Farò in modo che tutti sappiano che mi hai salvato!', '', 28153),
(136812, 'itIT', 'Sto libero! Nun posso crederci!', '', 28153),
(136811, 'itIT', 'Se riuscissi a ripigliare la forza mia, potrei batterlo...', '', 28153),
(136810, 'itIT', 'E chello è Urok, nu mostruoso non morto che vi acciderà tutti quanti.', '', 28153),
(136809, 'itIT', 'Idiota! Diventerai cibo per Urok!', '', 28153),
(136808, 'itIT', 'Shhh. Urok sta vicino... Riesco a sentire l\'ODORE dei DENTI suoi.', '', 28153),
(136807, 'itIT', 'Mostrami Urok, Terrore delle Paludi Grigie.', 'Mostrami Urok, Terrore delle Paludi Grigie.', 28153),
(136806, 'itIT', '', 'Eddie!!!', 28153),
(136805, 'itIT', 'Pa\'ku, Pa\'ku, Pa\'ku, lei è la Loa per te.', 'Pa\'ku, Pa\'ku, Pa\'ku, lei è la Loa per te.', 28153),
(136804, 'itIT', 'Ti piace il cielo? Pure a me. Unisciti a Pa\'ku, è la Loa per te.', 'Ti piace il cielo? Pure a me. Unisciti a Pa\'ku, è la Loa per te.', 28153),
(136803, 'itIT', 'Nun esitare, segui Pa\'ku oggi!', 'Nun esitare, segui Pa\'ku oggi!', 28153),
(136800, 'itIT', 'Sta bene, sta bene! Non c\'è bisogno di... AAAHHH!', '', 28153),
(136799, 'itIT', '', 'Va bene, Eddie, tieni calmo Passolesto.', 28153),
(136798, 'itIT', '', '$gPatetico piccirillo:Patetica piccirilla;! Hir\'eek nun ti accetterà manco come sacrificio!', 28153),
(136797, 'itIT', '', 'Seguimi. È il tuo turno mo\'.', 28153),
(136789, 'itIT', 'Addio, ci rivediamo presto.', '', 28153),
(136788, 'itIT', 'Devo tornare a Zo\'bal. Ci stanno altre anime da raccogliere per ripagare il debito mio.', '', 28153),
(136780, 'itIT', '<Il Cacciatore della Notte Vincolato farfuglia qualcosa.>', '', 28153),
(136779, 'itIT', '<Il Cacciatore della Notte Vincolato sente qualcosa nelle vicinanze!>', '', 28153),
(136778, 'itIT', '<Il Cacciatore della Notte Vincolato annusa l\'aria.>', '', 28153),
(136769, 'itIT', '', 'Meeki si meritava un destino migliore, ma so che non è colpa tua.\n\nGrazie per averlo riportato da noi, è meglio conoscere il dolore piuttosto che vivere col rimpianto.\n\nViaggiamo tra le dune come una famiglia, e tu ora ne fai parte. Sarai sempre $gil benvenuto:la benvenuta; tra noi.', 28153),
(136768, 'itIT', 'Devi tenere la mente più nitida, o i nemici percepiranno la debolezza nella capa tua.', '', 28153),
(136767, 'itIT', 'Smettila!', '', 28153),
(136766, 'itIT', 'N-n-non vedo l\'ora di ascoltare la canzone di Ahna sulla tua avventura.\n\nA-a-ahna fa dell\'ottima musica, ricordati di raccontarle la tua storia!\n\nF-f-faremo il possibile perché tutti sappiano della storia di $p.', '', 28153),
(136764, 'itIT', '', 'Tragedie, pirati non morti, tesori maledetti, ammutinamenti... quest\'avventura è materiale da epopea.\n\nHo già delle idee interessanti sul primo verso della mia canzone, la Ballata $gdel Coraggioso:della Coraggiosa; $p.\n\nDiventerai una leggenda per generazioni, almeno per questa carovana.\n\nTutto questo e molto altro, ma non prima di un sonnellino.', 28153),
(136763, 'itIT', 'Combatti con tutto il core! Sta in gioco tutto!', '', 28153),
(136762, 'itIT', 'Combattiamo nun solo per proteggere la gente, ma anche per il futuro delli Zandalari. Nun sottovalutate chesto aspetto.', '', 28153),
(136761, 'itIT', 'Attacca rapidamente, ma nun dimenticare mai i soldati al fianco tuo.', '', 28153),
(136760, 'itIT', 'Devi colpire il bersaglio con forza... ma anche con grazia.', '', 28153),
(136759, 'itIT', 'Ne ho cavalcati un sacco nel recinto, non sarà poi così diverso là fuori!', '', 28153),
(136758, 'itIT', '', 'Tieni salde le redini, Eddie.', 28153),
(136757, 'itIT', '', 'Ser Norwington mi ha incaricata di insegnare a suo figlio a cavalcare. Si è comportato bene nel recinto, ma ho paura a portarlo là fuori. Temo non sia ancora in grado di controllare il suo pony se si dovesse spaventare.$b$bSperiamo non capiti nulla di tutto questo!', 28153),
(136756, 'itIT', 'Passolesto non si spaventerebbe mai. È un bravo pony!', '', 28153),
(136755, 'itIT', 'Credo stia ascoltando, guarda le orecchie!', '', 28153),
(136754, 'itIT', 'Lo sto facendo!', '', 28153),
(136753, 'itIT', '', 'Vacci piano, potrebbe spaventarsi per qualsiasi cosa.', 28153),
(136752, 'itIT', '', 'Cerca di mantenere la sua attenzione su di te, sta accadendo un sacco di roba là fuori!', 28153),
(136751, 'itIT', '', 'Eddie, gira con la gamba, non con la mano.', 28153),
(136750, 'itIT', 'Mmm. Un deserto in una palude... che cosa stanno facendo i Sethrak?', '', 28153),
(136747, 'itIT', 'Grazie per avermi salvato da chei terribili saurolischi. Chesta è l\'ultima volta che vado al fiume da solo... almeno fin quando sarò più grande!', '', 28153),
(136746, 'itIT', 'Ehilà? C\'è qualcuno lì?', '', 28153),
(136745, 'itIT', 'L\'Alleanza non può nulla contro di noi. Per l\'Orda!', '', 28153),
(136744, 'itIT', 'Il Porto di Zem\'lan è mio!', '', 28153),
(136741, 'itIT', 'Sur\'jan, ragiona! Nun lasceremo Nazmir dopo chesto. Nun tornerò mai più a Zuldazar.', '', 28153),
(136740, 'itIT', 'Con l\'aiuto tuo, diventerò abbastanza forte da poter battere Urok di nuovo. Ti aspetterò accà e preparerò il prossimo rituale.', '', 28153),
(136738, 'itIT', 'Quei mostri volevano mangiarmi!', '', 28153),
(136732, 'itIT', 'Cos\'è chello, Sur\'jan? Mmm, d\'accordo, hai ragione.', '', 28153),
(136731, 'itIT', 'Sur\'jan, dovrei essere io a fare chesto. Nun mi piace starmene in disparte e vedere qualcun altro faticare al posto mio.', '', 28153),
(136730, 'itIT', 'Io vado avanti, tu prepara tutto quanto per il combattimento contro Urok.', '', 28153),
(136729, 'itIT', 'Papà dice che posso partecipare alle celebrazioni quest\'anno. Finalmente mi insegneranno a cavalcare!', '', 28153),
(136728, 'itIT', 'Io mi occuperò dell\'equilibrio della natura.\n\nCalma, Sur\'jan, è ovvio che ci tengo all\'equilibrio della natura... più o meno. Ma nun serve che lo sappia.', '', 28153),
(136727, 'itIT', 'La palude sta piena di orrori. Se vuoi sopravvivere là fuori, dovrai diventare come loro.', '', 28153),
(136726, 'itIT', 'La maledizione... è sparita? Sono finalmente... libero?', '', 28153),
(136725, 'itIT', 'Stai su na terra maledetta... nessuno se n\'è mai andato da accà!', '', 28153),
(136724, 'itIT', '', 'Ci sono mostri che si nascondono tra le ombre di Zem\'lan.\n\nFai attenzione a non diventare uno di questi.', 28153),
(136723, 'itIT', 'Le f-famiglie stanno insieme, in qualsiasi situazione.', '', 28153),
(136722, 'itIT', 'E nun scherzo, voglio veder schiattare chel Troll, proprio come Urok. Buona caccia.', '', 28153),
(136721, 'itIT', 'Nun fare lo stupido, Sur\'jan. Nun penserebbe mai che sto scherzando. D\'accordo, allora assicuriamoci che l\'abbia capito.', '', 28153),
(136720, 'itIT', 'È stato bello lavorare con te. Se vedi nu troll di nome Krugah, assicurati che schiatti. Ah!', '', 28153),
(136719, 'itIT', 'Nun perdiamo altro tempo. Urok dev\'essere abbattuto!', '', 28153),
(136718, 'itIT', 'Sì, è tempo. Accideremo Urok!', '', 28153),
(136717, 'itIT', 'La percepisco... L\'energia mia sta tornando!', '', 28153),
(136713, 'itIT', 'Ahah! Ci siamo quasi... Siamo quasi pronti per accidere Urok!', '', 28153),
(136712, 'itIT', 'Bene... Sento che il potere mio sta tornando!', '', 28153),
(136711, 'itIT', 'Ah... di più!!! Ci servirà altro potere se vogliamo accidere Urok!', '', 28153),
(136710, 'itIT', 'Chesto è tutto chello di cui tengo bisogno... Mo\' è tempo di ottenere più potere!', '', 28153),
(136698, 'itIT', 'Siamo stati fortunati. Tu no... non ancora.', '', 28153),
(136697, 'itIT', 'Va alla ricerca di ciò che si deve ottenere col sacrificio.', '', 28153),
(136696, 'itIT', '', 'Oltre al piccolo mare di stelle c\'è solo l\'infinita Oscurità.', 28153),
(136695, 'itIT', '', 'Di\' a mio padre che lo perdono.', 28153),
(136694, 'itIT', '', 'Ti ha già tradito? Lo farà...', 28153),
(136693, 'itIT', '', 'Morirai $gsolo:sola;.', 28153),
(136692, 'itIT', '', 'Il padrone ti sta aspettando...', 28153),
(136691, 'itIT', '', 'È sveglio ora. E ti ha notato.', 28153),
(136690, 'itIT', '', 'Tra poco ti unirai a noi.', 28153),
(136689, 'itIT', '', 'So cos\'hai fatto.', 28153),
(136688, 'itIT', '', 'Senti delle deboli risate.', 28153),
(136687, 'itIT', '', 'Ti senti degli occhi addosso.', 28153),
(136686, 'itIT', '', 'Qualcosa ti osserva.', 28153),
(136685, 'itIT', '', 'Il Seguace Fantasma ride e scappa via.', 28153),
(136684, 'itIT', 'Il nostro prossimo incontro sarà l\'ultimo...', '', 28153),
(136683, 'itIT', 'La tua anima sarà mia, ficcanaso!', '', 28153),
(136681, 'itIT', 'La presenza tua è dissacrante. Temi l\'ira di Xibala!', 'La presenza tua è dissacrante. Temi l\'ira di Xibala!', 28153),
(136680, 'itIT', '', 'Se vuoi i migliori monili e mojo provenienti dal sud, vieni da Wunja!', 28153),
(136679, 'itIT', 'Folle mortale. Xibala ti distruggerà!', 'Folle mortale. Xibala ti distruggerà!', 28153),
(136678, 'itIT', 'In chesto viaggio, dovremo cavalcare Ata, il Signore Alato. Salta su e tieni gli occhi aperti.', '', 28153),
(136677, 'itIT', 'È proprio come dice sempre il Loa mio: se nun vedi la sorgente della corruzione, vola più in alto.', '', 28153),
(136676, 'itIT', 'Il metodo di Loti è troppo terra terra per i gusti miei. Io preferisco guardare dal punto di vista di nu pterrordattilo.', '', 28153),
(136674, 'itIT', 'Sono pronto per il pattugliamento.', 'Sono pronta per il pattugliamento.', 28153),
(136673, 'itIT', '', 'Sono la Druida da Guerra Loti, Portavoce di Gonk, Loa Signore delle Forme e della Caccia.$b$bFaccio anche parte del Concilio delli Zanchuli, ma sono sicura che chesto tu lo sappia già.', 28153),
(136672, 'itIT', '<Il trasportatore fa un cenno alla Guardia Zandalari.>', '', 28153),
(136671, 'itIT', '<La guardia ti esamina con circospezione.>', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(136670, 'itIT', '<La guardia mostra di riconoscere la tua presenza.>', '', 28153),
(136669, 'itIT', 'Spero tu abbia imparato la lezione!', 'Spero tu abbia imparato la lezione!', 28153),
(136668, 'itIT', '<La guardia ti saluta mentre le passi accanto.>', '', 28153),
(136667, 'itIT', '<La guardia fa un cenno nella tua direzione.>', '', 28153),
(136662, 'itIT', 'Stai di fronte al Signore del Maleficio Raal, membro del Concilio delli Zanchuli e Alto Sacerdote della grande Loa Pa\'ku, Signora dei Venti e della flotta nostra.\n\nCosa vuoi?', '', 28153),
(136657, 'itIT', 'Lavoro, lavoro.', '', 28153),
(136655, 'itIT', '', 'Che la pace della Luce sia con te, $C.', 28153),
(136654, 'itIT', 'Stupido Sur\'jan! Perché parli così davanti a tutti quanti? Penseranno che sei uscito pazzo!', '', 28153),
(136653, 'itIT', 'Andrò fuori dalle rovine a recuperare li ingredienti per il rituale. Riusciremo ad accidere Urok nun appena riavrò il potere mio.', '', 28153),
(136652, 'itIT', 'Lo so. Vivo a Nazmir, quindi credi che io sia pazzo, ma devi ascoltarmi! Schiatterete tutti quanti se nun mi aiuterete!', '', 28153),
(136651, 'itIT', 'So che credi che io sia uscito pazzo, ma tieni bisogno di aiutarmi!', '', 28153),
(136650, 'itIT', 'Smettila di fuggire, mi serve l\'aiuto tuo!', '', 28153),
(136649, 'itIT', 'La protezione sua nun ci sta più! Finiamolo!', '', 28153),
(136648, 'itIT', '', 'Rinasco, nel nome di G\'huun!', 28153),
(136647, 'itIT', 'Ti lascio gestire le cose più complicate. Ti aspetterò fuori dall\'Antro di Urok.', '', 28153),
(136646, 'itIT', 'Ah! Ce l\'abbiamo fatta! Te l\'avevo detto, Sur\'jan, che l\'avremmo battuto!', '', 28153),
(136645, 'itIT', 'Presto, occupati di chella strega! Chelle quattro ossa che chiama \"servitori\" cadranno di fronte al vero Signore dei Morti!', '', 28153),
(136644, 'itIT', 'I totem proteggono Urok, usa la torcia mia per bruciarli!', '', 28153),
(136643, 'itIT', '<La sacca mezza sepolta è coperta di sabbia, ma gli oggetti al suo interno sembrano in buone condizioni.>', '', 28153),
(136642, 'itIT', '', 'Te l\'avevo detto di stare alla larga da quel posto! Siamo riusciti a tirarti fuori di lì per miracolo!', 28153),
(136641, 'itIT', 'La morte viene a prenderti!', 'La morte viene a prenderti!', 28153),
(136640, 'itIT', '$gUn estraneo:Un\'estranea;!', '$gUn estraneo:Un\'estranea;!', 28153),
(136639, 'itIT', 'Unisciti a noi!', 'Unisciti a noi!', 28153),
(136638, 'itIT', '', 'Il mio lavoro non verrà fermato! Annientate quest\'insetto!', 28153),
(136637, 'itIT', 'Vai, vai, vai!', 'Vai, vai, vai!', 28153),
(136632, 'itIT', 'Ahahah, ci penso io a dargli le mazzate!', '', 28153),
(136615, 'itIT', '', 'Sorgete, servitori! Sorgete e distruggete chisto folle Loa!', 28153),
(136614, 'itIT', 'Mi servirà l\'aiuto tuo... sta arrivando qualcosa di fetente e nun posso acciderlo da solo!', '', 28153),
(136613, 'itIT', '', 'Parole audaci, ma andrai incontro allo stesso destino di chi si oppone a G\'huun!', 28153),
(136611, 'itIT', 'Nessuno dice a Bwonsamdi cosa fare! Quindi, eheheh... pensi di potermi affrontare, piccirilla?', '', 28153),
(136610, 'itIT', 'Mmm, pari intelligente assai, femmina. Però stai accà, nella santità del tempio mio.', '', 28153),
(136609, 'itIT', '', 'Ti darò la possibilità di sottometterti al Dio del Sangue. Arrenditi... o muori.', 28153),
(136608, 'itIT', '', 'Bwonsamdi! Finalmente hai abbandonato chelle rovine.', 28153),
(136607, 'itIT', 'Nun startene lì a perdere tempo. Iniziamo!', '', 28153),
(136605, 'itIT', 'Cominciamo.', 'Cominciamo.', 28153),
(136604, 'itIT', 'Il Rito del Vincolo è nu mojo antico assai. Vecchio come il mondo stesso. Con chesto mojo, l\'anima di chiunque tu accida finisce nelle mani di Bwonsamdi. Se accetti, teniamo n\'accordo.$b$bSei $gpronto:pronta;?', '', 28153),
(136603, 'itIT', '', 'Che c\'è, continentale?', 28153),
(136602, 'itIT', '', 'I miei coscritti sono pronti ad aiutare a difendere il villaggio. Dobbiamo cominciare l\'evacuazione?', 28153),
(136601, 'itIT', 'Sono pronto.', 'Sono pronta.', 28153),
(136600, 'itIT', 'Che trucco crudele, Mignolo! Cattivo gigantosauro! Cattivo!', 'Che trucco crudele, Mignolo! Cattivo gigantosauro! Cattivo!', 28153),
(136599, 'itIT', 'Vieni alla Corte delli Spiriti, eheh. Là sigleremo il patto nostro.', '', 28153),
(136591, 'itIT', 'Chesta nun è na discussione. Siamo alli ordini della Principessa tua.', '', 28153),
(136590, 'itIT', '', 'E poi mi ha ordinato di assicurarmi che $n e, parole sue, \"chella bellezza\", raggiungano Nazmir il prima possibile.', 28153),
(136589, 'itIT', 'L\'errante si è rivoltato contro i suoi padroni!', '', 28153),
(136588, 'itIT', 'Lo schiavo sembra momentaneamente immobilizzato.', '', 28153),
(136587, 'itIT', 'Lo schiavo entra in uno stato di frenesia!', '', 28153),
(136581, 'itIT', 'Occupati di questo intruso, Guardiano del Mare. Che il mio volere sia fatto.', '', 28153),
(136578, 'itIT', 'Omaggio', '', 28153),
(136577, 'itIT', 'Scommetto che troveremo altre armi dei Bracescura al porto. Dobbiamo scoprire chi le sta comprando.', '', 28153),
(136576, 'itIT', '', 'Ho molte sorelle... Kul Tiras cadrà...', 28153),
(136575, 'itIT', '', 'Non puoi vincere! La congrega non si fermerà finché tutti non la serviranno!', 28153),
(136574, 'itIT', '', 'Affronta la mia ira!', 28153),
(136573, 'itIT', '', 'Notevole... ma ci vorrà ben altro per avere la meglio su una Matrona della Congrega Frangicuore!', 28153),
(136572, 'itIT', '', 'Non importa. Ammirate il destino di coloro che si oppongono alla congrega! Accoliti, togliete di mezzo quest\'intralcio!', 28153),
(136571, 'itIT', '', 'Quindi qualche stupido ficcanaso è riuscito ad aizzarci contro una delle nostre creazioni? Devono credersi davvero furbi.', 28153),
(136570, 'itIT', 'Non l\'ho mai vista così affollata prima d\'ora. C\'è qualcosa che bolle in pentola.', '', 28153),
(136569, 'itIT', 'Soldati, mercenari... persino i pirati sono i benvenuti. Ovviamente, è una città molto... vivace.', '', 28153),
(136568, 'itIT', 'Covo della Libertà è un \"porto libero\". A differenza di Boralus, nessuna legge impedisce l\'attracco di alcuni vascelli.', '', 28153),
(136567, 'itIT', '', 'Mi spiace, $C. Abbiamo finito completamente le alghe. Nessuno si sentiva in grado di andarle a raccogliere in acqua. Riferisci a Therold le mie scuse.', 28153),
(136566, 'itIT', '', 'Le mie sorelle mi vendicheranno...', 28153),
(136565, 'itIT', '', 'Non avresti dovuto interferire!', 28153),
(136564, 'itIT', 'Hai delle alghe? Therold ne ha bisogno per un antidoto.', 'Hai delle alghe? Therold ne ha bisogno per un antidoto.', 28153),
(136563, 'itIT', '', 'Cadrai... dinnanzi alla Matrona...', 28153),
(136562, 'itIT', '', 'Il villaggio appartiene alla congrega, ficcanaso!', 28153),
(136561, 'itIT', '', 'Così tanto da fare e così poco tempo!$b$bDevo benedire i pescatori e i loro attrezzi, scrutare le maree in cerca di presagi, pregare per il ritorno dei nostri marinai...', 28153),
(136560, 'itIT', '', 'La congrega vi prenderà...', 28153),
(136559, 'itIT', '', 'La congrega divorerà tutto!', 28153),
(136558, 'itIT', 'Le sirene sono scatenate oggi, ma non allontanarti dalla terraferma. Stai alla larga dalle isole e vivrai con prosperità.', 'Le sirene sono scatenate oggi, ma non allontanarti dalla terraferma. Stai alla larga dalle isole e vivrai con prosperità.', 28153),
(136557, 'itIT', 'Le maree si infrangono con forza a est, ma rimangono calme a ovest.', 'Le maree si infrangono con forza a est, ma rimangono calme a ovest.', 28153),
(136556, 'itIT', 'La mia benedizione ti proteggerà anche in acqua.', 'La mia benedizione ti proteggerà anche in acqua.', 28153),
(136555, 'itIT', 'Manda i pescatori al molo, vicino al mercato. Ci sono un sacco di pesci da prendere lì oggi.', 'Manda i pescatori al molo, vicino al mercato. Ci sono un sacco di pesci da prendere lì oggi.', 28153),
(136554, 'itIT', 'Saremo al sicuro grazie alla tua guida.', 'Saremo al sicuro grazie alla tua guida.', 28153),
(136553, 'itIT', 'Dobbiamo addentrarci in acque più profonde. Qual è la strada migliore da prendere?', 'Dobbiamo addentrarci in acque più profonde. Qual è la strada migliore da prendere?', 28153),
(136552, 'itIT', 'Allora non c\'è nulla di cui preoccuparsi. Grazie!', 'Allora non c\'è nulla di cui preoccuparsi. Grazie!', 28153),
(136551, 'itIT', 'Stiamo per intraprendere un\'incursione in acque profonde. Cosa dicono le maree?', 'Stiamo per intraprendere un\'escursione in acque profonde. Cosa dicono le maree?', 28153),
(136550, 'itIT', 'Sento la tua benedizione scorrere dentro di me. Ti ringrazio.', 'Sento la tua benedizione scorrere dentro di me. Ti ringrazio.', 28153),
(136549, 'itIT', 'Mi sto preparando a raggiungere le terre di quei mostri. Ti prego, concedimi la tua benedizione.', 'Mi sto preparando a raggiungere le terre di quei mostri. Ti prego, concedimi la tua benedizione.', 28153),
(136548, 'itIT', 'Informerò i pescatori.', 'Informerò i pescatori.', 28153),
(136547, 'itIT', 'Qual è il luogo con più abbondanza di pesci oggi?', 'Qual è il luogo con più abbondanza di pesci oggi?', 28153),
(136546, 'itIT', 'Ehi! Parleranno tutti di te al Kraal. Dicono che nun tieni paura di nulla!', '', 28153),
(136545, 'itIT', '', 'Tu sei tra coloro che camminano con i Loa. Fai attenzione, nun tutti i Loa vanno d\'accordo tra loro.', 28153),
(136538, 'itIT', 'Guerrieri dell\'Orda! Quest\'oggi sazieremo le nostre asce col sangue dei nemici.', '', 28153),
(136533, 'itIT', 'Meccatork, le tue macchine volanti possono portarci oltre la Piaga?', '', 28153),
(136532, 'itIT', '', 'Lascia che pareggiamo i conti, Re Wrynn!', 28153),
(136528, 'itIT', 'Jaina! Blocca le uscite! Non lasciare che chiamino rinforzi!', '', 28153),
(136527, 'itIT', 'Chesto tempio sta per cadere! La sacerdotessa l\'ha previsto!', '', 28153),
(136526, 'itIT', 'Proteggete la Sacerdotessa!', '', 28153),
(136525, 'itIT', 'La Sacerdotessa tiene bisogno di sangue per il rituale... Il tuo va bene.', '', 28153),
(136524, 'itIT', 'Per la Sacerdotessa! Per G\'huun!', '', 28153),
(136523, 'itIT', 'Bwonsamdi nun tiene potere su di noi! Per il Dio del Sangue!', '', 28153),
(136522, 'itIT', 'Per il volere del Signore della Guerra!', '', 28153),
(136521, 'itIT', '$gIntruso:Intrusa;! Ti schiaccio!', '', 28153),
(136520, 'itIT', 'Per la Signora della Guerra Malaka! Per il Dio del Sangue!', '', 28153),
(136519, 'itIT', 'Preparati a vivere al servizio del Signore della Guerra!', '', 28153),
(136518, 'itIT', '', 'Chi osa interrompere il rituale mio?', 28153),
(136517, 'itIT', '', 'Mo\' basta! Ti ho detto che ci penserò!', 28153),
(136516, 'itIT', 'Ma potresti raddoppiare, no, triplicare la produzione! I miei elisir sono completamente naturali e garantiti...', '', 28153),
(136515, 'itIT', '', 'Nun saprei... le tradizioni nostre funzionano altrettanto bene e...', 28153),
(136514, 'itIT', 'Fidati, stai perdendo una grandissima opportunità! Non ti conviene perdere questa occasione!', '', 28153),
(136513, 'itIT', '', 'Te ne pentirai!', 28153),
(136512, 'itIT', '', 'Iniziate il rituale! Mi libererò di chesta fragile forma!', 28153),
(136511, 'itIT', 'Non c\'è nulla da vedere, qui. Via.', '', 28153),
(136510, 'itIT', 'Non costringermi a farti del male.', '', 28153),
(136509, 'itIT', 'Oi! Che ci fai qui?', '', 28153),
(136508, 'itIT', '', 'Tutto cadrà... dinnanzi al volere del Dio del Sangue...', 28153),
(136507, 'itIT', '', 'Più sangue per il Dio del Sangue!', 28153),
(136498, 'itIT', 'Stanno impazzendo tutti! Io me la squaglio fintanto che posso!', '', 28153),
(136497, 'itIT', '', 'È finita\n\nEra necessario. La corruzione l\'aveva ormai pervasa.\n\n<Rebecca tira su col naso.>\n\nScusami. Ho bisogno di stare un po\' da sola.', 28153),
(136495, 'itIT', '', 'All\'inizio quello che stava facendo mia sorella mi sembrava divertente, ma questa è follia!\n\nNel suo grimorio parla di risvegliare un\'armata di costrutti antichi! Se non viene fermata, schiavizzerà tutta Drustvar!', 28153),
(136494, 'itIT', 'Sparisci!', 'Sparisci!', 28153),
(136493, 'itIT', '', 'Spero che io e ma\'ma ti rivedremo.', 28153),
(136492, 'itIT', '', 'È vero, ma\'ma ha sbagliato. Ma ho deciso di perdonarla. Mo\' potremo passare il resto dell\'eternità nostra nell\'Aldilà.', 28153),
(136491, 'itIT', '', 'Io e ma\'ma mo\' staremo insieme... per sempre!', 28153),
(136490, 'itIT', '', 'Nooo... Io dovevo vivere... per sempre...', 28153),
(136489, 'itIT', 'Guardati le spalle. Ci sono animali pericolosi là fuori.', '', 28153),
(136488, 'itIT', '', 'Che succede? No! Come osi portare chella COSA accà!', 28153),
(136487, 'itIT', '', 'Ti ho trovata, ma\'ma!', 28153),
(136486, 'itIT', '', 'Chi osa disturbare il riposo mio?', 28153),
(136485, 'itIT', '<Prova ad aprire il sarcofago.>', '<Prova ad aprire il sarcofago.>', 28153),
(136484, 'itIT', '<Il sarcofago è chiuso, ma con un po\' di sforzi dovresti essere in grado di aprirlo.>', '', 28153),
(136483, 'itIT', '', 'Credo che siamo vicini! Ma\'ma! Dove sei?', 28153),
(136482, 'itIT', '', 'È buio là dentro... tu va\' avanti, starò dietro di te.', 28153),
(136481, 'itIT', '', 'No, chella è la cripta della Grande Regina. Ma\'ma si metterebbe nei guai se andasse là dentro.', 28153),
(136480, 'itIT', '', 'Bleah, i Sacerdoti là dentro puzzano di verme putrefatto! No, ma\'ma nun ci entrerebbe mai.', 28153),
(136479, 'itIT', '', 'Ma\'ma e io abbiamo incontrato i Sacerdoti accà. M\'hanno dato chesto vestito. Erano così gentili!', 28153),
(136478, 'itIT', 'Sapevo che non eri all\'altezza mia!', 'Sapevo che non eri all\'altezza mia!', 28153),
(136477, 'itIT', '', 'Nun credo sia chesto. Il grande tempio nun lascia mai entrare nessuno.', 28153),
(136476, 'itIT', 'Devo allenarmi di più...', 'Devo allenarmi di più...', 28153),
(136475, 'itIT', 'Argh... sei più forte di quel che pensavo.', 'Argh... sei più forte di quel che pensavo.', 28153),
(136474, 'itIT', 'Basta! Mi arrendo!', 'Basta! Mi arrendo!', 28153),
(136473, 'itIT', 'Hai vinto. Per questa volta.', 'Hai vinto. Per questa volta.', 28153),
(136472, 'itIT', 'Basta! Mi arrendo!', 'Basta! Mi arrendo!', 28153),
(136471, 'itIT', 'Cerca di non sanguinarmi addosso!', 'Cerca di non sanguinarmi addosso!', 28153),
(136470, 'itIT', 'È stata una follia sfidarmi!', 'È stata una follia sfidarmi!', 28153),
(136469, 'itIT', 'Spero che la tua spada sia affilata come la tua lingua!', 'Spero che la tua spada sia affilata come la tua lingua!', 28153),
(136468, 'itIT', 'Osi sfidare me? Ti laverò con il tuo sangue!', 'Osi sfidare me? Ti laverò con il tuo sangue!', 28153),
(136467, 'itIT', 'Sfidarmi è stato il tuo ultimo errore!', 'Sfidarmi è stato il tuo ultimo errore!', 28153),
(136466, 'itIT', 'Se vuoi prenderle... posso accontentarti!', 'Se vuoi prenderle... posso accontentarti!', 28153),
(136465, 'itIT', '', 'Aveva detto che sarebbe andata in un posto buio e spaventoso. Chissà dov\'è... Oh, odio i posti bui!', 28153),
(136464, 'itIT', '', 'Sì! Allora, ma\'ma ha detto qualcosa di nu patto con Bwonsamdi. Forse sta ancora nel tempio.', 28153),
(136463, 'itIT', 'Razgaji mi ha chiesto di sfidarti a duello.', 'Razgaji mi ha chiesto di sfidarti a duello.', 28153),
(136462, 'itIT', 'Ti consiglio di fare attenzione... nun amo molto li stranieri.', 'Ti consiglio di fare attenzione... nun amo molto li stranieri.', 28153),
(136461, 'itIT', 'Chiedimi ancora come sono finito a Vol\'dun e ti darò una lista di tombe da visitare...', 'Chiedimi ancora come sono finita a Vol\'dun e ti darò una lista di tombe da visitare...', 28153),
(136460, 'itIT', 'Conterò fino a tre, dopodiché ti leverai dai piedi... Tre!', 'Conterò fino a tre, dopodiché ti leverai dai piedi... Tre!', 28153),
(136459, 'itIT', 'Non vedi che mi sto allenando? Vattene!', 'Non vedi che mi sto allenando? Vattene!', 28153),
(136458, 'itIT', 'Rokhan, sono qui per aiutare te e la Principessa Talanji a investigare a Nazmir.', 'Rokhan, sono qui per aiutare te e la Principessa Talanji a investigare a Nazmir.', 28153),
(136457, 'itIT', 'La Principessa Talanji ci vuole mandare a Nazmir. Ci serviranno li pterrordattili tuoi per arrivarci.', '', 28153),
(136453, 'itIT', '', 'Fate il possibile per prendere il controllo del villaggio. Io arriverò tra non molto a ispezionare le rovine personalmente.', 28153),
(136451, 'itIT', '', 'La tomba al suo interno potrebbe nascondere potenti reliquie utili per i nostri rituali.', 28153),
(136450, 'itIT', '', 'I minatori alla Conca degli Impennatori si sono imbattuti in alcune rovine nascoste nelle profondità della Miniera di Pietravecchia.', 28153),
(136449, 'itIT', '', 'Sorelle della congrega, ascoltate.', 28153),
(136448, 'itIT', '', 'Ho già perso due uomini là dentro. Fa\' in modo di non essere il terzo.', 28153),
(136447, 'itIT', '', 'Non so cosa stiano tramando, ma la magia che fuoriesce da quel luogo sembra risucchiare la vita.', 28153),
(136446, 'itIT', '', 'Giusto un avvertimento, evita la miniera a tutti i costi.', 28153),
(136445, 'itIT', '', 'Quello era l\'ultimo degli abitanti. Con un po\' di fortuna, arriveranno incolumi a Malautunno.', 28153),
(136444, 'itIT', '', 'Pare che stiano mandando i pezzi grossi! Resistete, ragazzi!', 28153),
(136443, 'itIT', '', 'Ne arrivano altri dal villaggio! Mantenete le posizioni!', 28153),
(136442, 'itIT', '', 'Sembra che stiano per attaccare. Proteggete i civili!', 28153),
(136441, 'itIT', '', 'Va\' con loro e respingi qualsiasi attacco proveniente dalla città!', 28153),
(136440, 'itIT', '', 'Forza ragazzi, liberiamo questa strada, così i civili saranno fuori pericolo.', 28153),
(136439, 'itIT', '', 'Spero che ci sia un esercito in quella tua borsa!', 28153),
(136438, 'itIT', '', 'Sentito, ragazzi? Ci aiuterà a riprendere il villaggio!', 28153),
(136437, 'itIT', '', 'Be\', diciamo che quelle inquietanti creature di vimini non sono qui per decorazione.\n\nÈ cominciato tutto qualche settimana fa, quando alcuni minatori sono scomparsi. Poi all\'improvviso sono apparse quelle creature, e ci hanno costretti ad andarcene dalla nostra città. Tutto ha avuto inizio quando la ragazza dei Crestabianca ha cominciato a curiosare in giro, ma dopo essersene andata, le cose sono soltanto peggiorate.\n\nOra quelle cose hanno preso la città e catturato gli abitanti. Io e qualche volontario siamo riusciti a mantenere il controllo di questo posto, ma non ho idea di come potremo riprendercela.\n\nQuindi, se non sei qui per aiutare, faresti meglio a muoverti.', 28153),
(136436, 'itIT', 'Sono qui per aiutare.', 'Sono qui per aiutare.', 28153),
(136435, 'itIT', 'Che succede qui?', 'Che succede qui?', 28153),
(136434, 'itIT', '', 'Da quando quelle creature terrificanti sono uscite dalle miniere, il nostro villaggio sta cadendo a pezzi.\n\nSpero avrai maggior fortuna rispetto a noi nel trovare la fonte di questo disastro.', 28153),
(136432, 'itIT', 'Ti aiuterò a trovare tua madre.', 'Ti aiuterò a trovare tua madre.', 28153),
(136431, 'itIT', 'Sei $gstato:stata; molto paziente.', 'Sei $gstato:stata; molto paziente.', 28153),
(136430, 'itIT', '', 'Mi sento così sola senza ma\'ma.$b$bPotresti aiutarmi a cercarla? Ti prego! Ti prometto che nun mi caccerò nei guai.', 28153),
(136429, 'itIT', '', 'Ma\'ma mi ha detto di aspettarla accà. Però è da tantissimo che aspetto e nun è ancora tornata!$b$bSono stanca di aspettare, voglio la ma\'ma mia!', 28153),
(136428, 'itIT', 'Che cosa ci fai qui?', 'Che cosa ci fai qui?', 28153),
(136427, 'itIT', '', 'Dov\'è ma\'ma? Voglio tornare a casa!', 28153),
(136426, 'itIT', '', 'Dov\'è andata ma\'ma? Nun è mai stata via per così tanto tempo.', 28153),
(136425, 'itIT', '', 'Fa così freddo... dov\'è ma\'ma?', 28153),
(136422, 'itIT', 'Qualcun altro sta andando a Nazmir? Non tornerete indietro, fidatevi di me.', '', 28153),
(136421, 'itIT', '', 'Mmm. Nun dire altro. Mi farò strada verso Nazmir. Speriamo di raggiungere in tempo la Principessa.', 28153),
(136420, 'itIT', 'Talanji sta già a Nazmir? Sarà il caso di muoversi, allora. Ci vediamo lì.', '', 28153),
(136419, 'itIT', '', 'Non c\'è tempo da perdere. Sono giorni che non riceviamo rapporti da Collefalco.', 28153),
(136418, 'itIT', '', 'Pe... penso di potermi intrufolare nella caverna dove si trova mia sorella. Vediamoci là.', 28153),
(136417, 'itIT', '', 'Mi farò strada verso Nazmir, ci vediamo lì.', 28153),
(136415, 'itIT', 'Li ingredienti di qualità nun sono facili da trovare a Vol\'dun, ma se mangi veloce e tieni li occhi chiusi, il sapore nun è poi così male!', '', 28153),
(136414, 'itIT', 'Se vuoi sapere di più sulli alpaca, stai nel posto giusto! So tutto chello che ci sta da sapere e molto di più.', '', 28153),
(136413, 'itIT', 'Vol\'dun sarà pure na landa desolata e pericolosa, ma è l\'unica casa che teniamo.', '', 28153),
(136407, 'itIT', 'Stiamo andando in nu luogo che nessuno a Zuldazar vorrebbe visitare. Preparati.', '', 28153),
(136406, 'itIT', 'SCHIACCIARE!', '', 28153),
(136405, 'itIT', 'Porto anche chest\'anima viva che desidera parlare con te, possente Loa.', '', 28153),
(136404, 'itIT', 'Vieni. Chesta è la via.', '', 28153),
(136403, 'itIT', 'Ahahah! Ah, conosco chesta voce! E chesti doni, molto bene. Vieni, vieni!', '', 28153),
(136402, 'itIT', 'La vena madre si sta spostando! Chiamate i rinforzi!', '', 28153),
(136398, 'itIT', 'La mia pelle! Brucia!', '', 28153),
(136397, 'itIT', 'Ahhh!', '', 28153),
(136396, 'itIT', 'Grande Bwonsamdi, il tamburo ha suonato in nome tuo! Le offerte ti attendono!', '', 28153),
(136395, 'itIT', 'Doba quzhu ta tawbo! Metah bo chu!', '', 28153),
(136394, 'itIT', 'Bene. Mo\' suona il tamburo!', '', 28153),
(136393, 'itIT', 'Che la visione ti guidi fino al circolo del rituale. Fai attenzione! Bwonsamdi nun sarà felice se il rituale verrà male.', '', 28153),
(136388, 'itIT', 'Avete finito di perdere tempo? Che ne dite di ...Hic!... portare un po\' di professionalità in questo posto?', '', 28153),
(136387, 'itIT', 'Pungiglioni velenosi? Sono sicuro che serviranno a qualcosa di importante.', '', 28153),
(136386, 'itIT', 'Ehi, è pericoloso qua fuori! Hic! Dovresti stare al mio fianco!', '', 28153),
(136385, 'itIT', 'Io, Uh... penso che aspetterò.', '', 28153),
(136384, 'itIT', 'Hic! Da questa parte!', '', 28153),
(136383, 'itIT', 'Ehi, cosa stai aspettando?', '', 28153),
(136382, 'itIT', 'Hic! Ehi, lucertola.', '', 28153),
(136380, 'itIT', 'Preparate le vostre lame! Lok\'tar ogar!', '', 28153),
(136379, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [300] Scava la galleria', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [300] Scava la galleria', 28153),
(136378, 'itIT', 'Ehi, lascia che ti illustri la nostra ultima invenzione per il Fronte di Guerra:\n\nGallerie.\n\nEsatto. Al solo prezzo di UNA gigantesca montagna d\'oro, io e il mio socio scaveremo una galleria verso le prime linee per te e i tuoi alleati. Che ne dici?', '', 28153),
(136377, 'itIT', 'Gli abitanti di questo posto sono molto rozzi. Lascia che... Hic!... sia io a parlare.', '', 28153),
(136376, 'itIT', 'Eccoci qui. Covo della Libertà.', '', 28153),
(136375, 'itIT', 'Mmm. L\'ultima volta siamo andati a destra... quindi DEVE essere a sinistra! Credo che la mia mente si stia schiarendo.', '', 28153),
(136374, 'itIT', '', 'Dobbiamo riportare la sfera all\'accampamento prima che i Sethrak si accorgano della sua scomparsa! Presto!', 28153),
(136373, 'itIT', 'Ahhh. Ci stiamo avvicinando! Riesco a sentirlo.', '', 28153),
(136372, 'itIT', 'Uff, che camminata. Mi serve un altro goccetto...', '', 28153),
(136371, 'itIT', 'Co... Cosa? Chi sei? Cos\'è quello?', 'Co... Cosa? Chi sei? Cos\'è quello?', 28153),
(136370, 'itIT', 'Quella cosa mi controllava il cervello?!?', 'Quella cosa mi controllava il cervello?!?', 28153),
(136369, 'itIT', 'Ah ah! Sembra familiare. Siamo sicuramente... Hic!... sulla strada giusta.', '', 28153),
(136368, 'itIT', 'Co... cos\'è successo?', 'Co... cos\'è successo?', 28153),
(136367, 'itIT', 'Uq naggwa... il nostro padrone... viene a prenderti.', 'Uq naggwa... il nostro padrone... sta venendo per te...', 28153),
(136366, 'itIT', 'Troppo tardi! Non puoi fermare la marea che avanza verso di te!', 'Troppo tardi! Non puoi fermare la marea che avanza verso di te!', 28153),
(136365, 'itIT', 'Ah, ci voleva proprio. Andiamo.', '', 28153),
(136364, 'itIT', 'Argh, sono ancora un po\' intontito. Devo bermi qualcosa per schiarire la mente.', '', 28153),
(136363, 'itIT', 'No, no. Era DECISAMENTE a destra.', '', 28153),
(136362, 'itIT', 'Hic! Allora, da che parte era... sinistra?', '', 28153),
(136361, 'itIT', 'I sussurri... Stanno travolgendo i miei pensieri...', 'I sussurri... Stanno travolgendo i miei pensieri...', 28153),
(136360, 'itIT', 'La mia anima per il mare...', 'La mia anima per il mare...', 28153),
(136359, 'itIT', 'Y\'za qam yyqzz...', 'Y\'za qam yyqzz...', 28153),
(136358, 'itIT', '$gIntruso:Intrusa;. Stai vagando in luoghi che non ti appartengono!', '$gIntruso:Intrusa;. Stai vagando in luoghi che non ti appartengono!', 28153),
(136357, 'itIT', 'Il tuo cuore sarà un\'ottima offerta sacrificale!', 'Il tuo cuore sarà un\'ottima offerta sacrificale!', 28153),
(136356, 'itIT', 'Dono la mia vita per questo potere!', 'Dono la mia vita per questo potere!', 28153),
(136350, 'itIT', '%s ti segue.', '', 28153),
(136349, 'itIT', '%s si è stancato di seguirti e corre via.', '', 28153),
(136348, 'itIT', '', 'Ora che abbiamo finito di occuparci del mare, è ora di concentrarci sulla caverna.', 28153),
(136347, 'itIT', 'Le candele sono accese e le offerte pronte. Mo\' dobbiamo preparare il circolo...', '', 28153),
(136346, 'itIT', 'La Gemma dell\'Invocatore Celeste si sta sovraccaricando! Cosa succederà se la usi ora?', 'La Gemma dell\'Invocatore Celeste si sta sovraccaricando! Cosa succederà se la usi ora?', 28153),
(136345, 'itIT', 'Per l\'Orda!', '', 28153),
(136341, 'itIT', 'Iniziamo.', 'Iniziamo.', 28153),
(136340, 'itIT', 'Queste pianure verranno bagnate col sangue dei nostri nemici.', '', 28153),
(136327, 'itIT', '', 'Attenzione!', 28153),
(136326, 'itIT', '', 'Attenzione!', 28153),
(136325, 'itIT', 'Va bene... sono pronto. Possiamo ancora sistemare le cose.', '', 28153),
(136324, 'itIT', 'Chiedi a Fozruk di attaccare l\'Alto Osservatorio.', 'Chiedi a Fozruk di attaccare l\'Alto Osservatorio.', 28153),
(136323, 'itIT', 'Chiedi a Fozruk di attaccare il Passo di Granvalore.', 'Chiedi a Fozruk di attaccare il Passo di Granvalore.', 28153),
(136322, 'itIT', 'Chiedi a Fozruk di attaccare Stromgarde.', 'Chiedi a Fozruk di attaccare Stromgarde.', 28153),
(136321, 'itIT', '<Fozruk abbassa lo sguardo verso di te.>', '', 28153),
(136320, 'itIT', 'Con piacere.', '', 28153),
(136319, 'itIT', 'Ti faccio a pezzi!', '', 28153),
(136318, 'itIT', 'Folle... Gli altri verranno... e si riprenderanno la gemma...', '', 28153),
(136317, 'itIT', 'Non ci fermerai mai! Scopriremo il vero potere della Gemma dell\'Invocatore Celeste!', '', 28153),
(136316, 'itIT', 'Il deserto si espanderà!', '', 28153),
(136315, 'itIT', 'Rivendichiamo Nazmir in nome dei Sethrak!', '', 28153),
(136314, 'itIT', 'Questa terra verrà trasformata in sabbia!', '', 28153),
(136313, 'itIT', 'Le vostre terre saranno le prossime!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(136312, 'itIT', 'Non puoi fermare il nostro dominio!', '', 28153),
(136311, 'itIT', 'Le paludi saranno trasformate!', '', 28153),
(136310, 'itIT', 'Domineremo su tutto!', '', 28153),
(136309, 'itIT', 'Il deserto ricoprirà questa terra!', '', 28153),
(136297, 'itIT', 'COME HAI POTUTO?', '', 28153),
(136296, 'itIT', 'Hai... Hai ucciso l\'amore della mia vita!', '', 28153),
(136295, 'itIT', 'Urgh... ma dai... tagliato in due dai Sethrak... così non va per niente bene.', '', 28153),
(136292, 'itIT', 'Ti concedo la benedizione del mare! Possa tu godere del suo gentile abbraccio.', '', 28153),
(136291, 'itIT', 'Xibala... ti farà soffrire...', '', 28153),
(136290, 'itIT', 'Chesto è il santuario di Xibala. Sarà felice di ricevere na nuova anima per la collezione sua!', '', 28153),
(136278, 'itIT', 'Il mondo... annegherà... ak yar qi\'lwhuk h\'iwn...', 'Il mondo... annegherà... ak yar qi\'lwhuk h\'iwn...', 28153),
(136277, 'itIT', 'È troppo tardi! Non puoi fermarci!', 'È troppo tardi! Non puoi fermarci!', 28153),
(136276, 'itIT', 'Ifis shuul qi\'nuq yyqzz...', '', 28153),
(136275, 'itIT', 'Brannon Sacraonda è un ragazzo debole. Il vero potere appartiene al mare!', '', 28153),
(136274, 'itIT', 'Alby? Cosa sta succedendo? Dov\'è Ser Sacraonda?', '', 28153),
(136273, 'itIT', 'Non ci crederesti se te lo dicessi, Therold! È un disastro.', '', 28153),
(136272, 'itIT', 'Abbassate la voce! Dama Sylvanas non sarà contenta se falliremo la missione.', '', 28153),
(136271, 'itIT', 'Tucker! Avrei dovuto immaginarlo. Se non altro ha pagato per la sua incompetenza.', '', 28153),
(136270, 'itIT', 'Doveva esserci Tucker. I Sethrak l\'hanno ucciso per primo.', '', 28153),
(136269, 'itIT', 'Avremmo dovuto prevedere l\'attacco. Chi doveva essere di guardia?', '', 28153),
(136268, 'itIT', '', 'Capo, non credo sia colpa nostra, considerando che siamo stati attaccati da un gruppo che non doveva essere lì.', 28153),
(136267, 'itIT', 'Lo sarà se svolgeremo al meglio il nostro lavoro, Ingrid.', '', 28153),
(136266, 'itIT', '', 'Capo, ma è mai contenta?', 28153),
(136265, 'itIT', 'Forza, andiamocene! Dobbiamo esplorare ancora gran parte di questo posto e non possiamo cadere in un\'altra imboscata.', '', 28153),
(136264, 'itIT', '<Il Feticcio Oscuro sembra muoversi ogni volta che distogli lo sguardo. Forse è un\'illusione creata dalla luce. O forse no.>', '', 28153),
(136263, 'itIT', '', 'Oh, ma dai!', 28153),
(136262, 'itIT', 'Quell\'informazione è riservata.', '', 28153),
(136261, 'itIT', '', 'Quand\'è che ti hanno tagliato in due per la prima volta?', 28153),
(136260, 'itIT', 'Non è la prima volta che mi tagliano in due. Ma spero sia l\'ultima.', '', 28153),
(136259, 'itIT', 'A volte.', '', 28153),
(136258, 'itIT', '', 'Oh, Clayton, siamo non morti, è ovvio che sopravviviamo se ci tagliano in due.', 28153),
(136257, 'itIT', 'Capo, come hai fatto a sopravvivere? Ti ho visto mentre ti tagliavano in due.', '', 28153),
(136256, 'itIT', '', 'Divertiti con la gemma! Credo che il rituale l\'abbia lasciata intatta... quasi.', 28153),
(136255, 'itIT', 'Vermi che mangiano facce? Io me la squaglio!', 'Vermi che mangiano facce? Io me la squaglio!', 28153),
(136254, 'itIT', 'Com\'è possibile che la gestione abbia lasciato che accadesse? Dobbiamo formare un sindacato.', 'Com\'è possibile che la gestione abbia lasciato che accadesse? Dobbiamo formare un sindacato.', 28153),
(136253, 'itIT', 'Era comunque ora di pausa. Io me ne vado.', 'Era comunque ora di pausa. Io me ne vado.', 28153),
(136252, 'itIT', 'Mi muovo in una postazione rialzata. Ordina alla squadra di ritrovarsi alla mia posizione.', '', 28153),
(136251, 'itIT', 'Sono abituato a vedere pezzi di mostri tra la merce, ma mostri vivi e vegeti? Non ci penso nemmeno.', 'Sono abituata a vedere pezzi di mostri tra la merce, ma mostri vivi e vegeti? Non ci penso nemmeno.', 28153),
(136250, 'itIT', 'Metti quella parte dentro...', '', 28153),
(136249, 'itIT', '', 'Ci vediamo dall\'altra parte dell\'area di imballaggio. Andrò a scoprire cosa sta succedendo in città.', 28153),
(136248, 'itIT', '', 'Che sta succedendo qui? Cosa... cos\'è quello?', 28153),
(136243, 'itIT', '', '\"Non sperimentare la magia oscura\", diceva.$B$B\"Condannerai tutta Azeroth se continui\", diceva.$B$B\"Ridammi il braccio, non puoi usarlo nei tuoi rituali!\" urlava dopo avergli strappato il braccio.$B$BOh, scusa, sono solo vecchi ricordi!', 28153),
(136242, 'itIT', 'Vince il sì. Sembra che rimarremo qui a goderci i fuochi d\'artificio.', '', 28153),
(136241, 'itIT', 'No.', '', 28153),
(136240, 'itIT', 'No.', '', 28153),
(136239, 'itIT', 'C\'è qualcuno contrario?', '', 28153),
(136238, 'itIT', 'Sì...', '', 28153),
(136237, 'itIT', 'Vengo pure io, per assicurarmi che tutto sia fatto come si deve.', '', 28153),
(136236, 'itIT', '', 'Sì...', 28153),
(136235, 'itIT', '', 'Sì...', 28153),
(136234, 'itIT', 'Mettiamola ai voti. Chi vuole rimanere in una pericolosa palude a guardare qualcuno usare una gemma per uccidere la gente serpente?', '', 28153),
(136233, 'itIT', '', 'Dai, Chadwick! Possiamo FRIGGERLI con la Gemma dell\'Invocatore Celeste che $n ci porterà!', 28153),
(136232, 'itIT', 'Io e i miei Maghi ti incontreremo lassù.', '', 28153),
(136231, 'itIT', 'Non pensavo di vedere un volto amico in questo posto. Grazie per l\'aiuto. Hai già sentito il piano di Ingrid?', '', 28153),
(136230, 'itIT', 'Nun saremmo mai dovuti venire in nu posto così pericoloso impreparati...', '', 28153),
(136229, 'itIT', '', 'Io me la squaglio mentre tu ti occupi della situazione... Poi vedremo cos\'è in grado di fare questa gemma!', 28153),
(136228, 'itIT', 'Grazie per avermi salvato. Quei Sethrak sono alla ricerca di qualche magia d\'ombra a Nazmir. Chissà a cosa gli serve...', '', 28153),
(136227, 'itIT', '', 'Che sollievo. I Sethrak sono alla ricerca di qualche tipo di magia per sbloccare il potere di uno dei loro manufatti.', 28153),
(136226, 'itIT', 'Hai ricevuto le spedizioni?', 'Hai ricevuto le spedizioni?', 28153),
(136225, 'itIT', 'AHHH! LEVAMI QUESTO COSO DI DOSSO!', '', 28153),
(136224, 'itIT', 'Brutto bastardo!', 'Brutto bastardo!', 28153),
(136223, 'itIT', 'Oh, mio dio! Hanno ammazzato Ken\'nai!', 'Oh, mio dio! Hanno ammazzato Ken\'nai!', 28153),
(136222, 'itIT', 'Questo potrebbe essere un problema. Fai attenzione!', '', 28153),
(136221, 'itIT', 'Ho ricevuto una spedizione giusto pochi minuti fa! Vuoi dare un\'occhiata?', '', 28153),
(136220, 'itIT', '', 'È da qualche giorno che non vedo quel ragazzino Sacraonda. Sarebbe bello avere qualcuno di competente alla guida di questo posto, ma chi sono io per giudicare?', 28153),
(136219, 'itIT', 'Hai notato niente di strano?', 'Hai notato niente di strano?', 28153),
(136218, 'itIT', 'Non ricevo ingredienti freschi da giorni! Come faccio a cucinare il mio famoso plesiosauro fritto senza pinne fresche di plesiosauro?', '', 28153),
(136215, 'itIT', 'Credo che sia ora di mostrare a questi Sethrak il significato della parola dolore.', '', 28153),
(136212, 'itIT', 'Così! Non sei così male, l\'avevi già fatto prima d\'ora?', '', 28153),
(136211, 'itIT', 'Ahia! No, continua, quel pezzo fa sempre male, giralo un po\'...', '', 28153),
(136210, 'itIT', 'Fai piano quando prendi le mie gambe, per favore. Tendono a muoversi un po\' quando vengono staccate.', '', 28153),
(136207, 'itIT', 'Ehi! Ridammelo!', '', 28153),
(136206, 'itIT', '', 'Cacciate chesti sauridi dalla locanda mia!', 28153),
(136205, 'itIT', '', 'Cosa? Che cosa vuoi?', 28153),
(136200, 'itIT', 'Concordo. Io coprirò le retrovie.', '', 28153),
(136199, 'itIT', 'Genn, dovrai coprirci le spalle. È troppo rischioso convogliare tutti lungo il lato della fortezza, ci saranno sicuramente delle trappole.', '', 28153),
(136198, 'itIT', '', 'Muoviamoci.', 28153),
(136197, 'itIT', 'Tutti quanti in posizione. Colpiremo al mio ordine!', '', 28153),
(136196, 'itIT', 'Ottimo consiglio. Sylvanas non ha avuto molto tempo per prepararsi a quest\'attacco, ma non possiamo permetterci di sottovalutarla.', '', 28153),
(136194, 'itIT', 'Non hai notato niente fuori dall\'ordinario?', 'Non hai notato niente fuori dall\'ordinario?', 28153),
(136193, 'itIT', 'Ti serve qualcosa?', '', 28153),
(136192, 'itIT', '', 'Sì? Posso aiutarti?', 28153),
(136191, 'itIT', 'Ti do il benvenuto! Vuoi qualcosa da mangiare?', '', 28153),
(136187, 'itIT', 'Ti va di darmi una mano? In realtà, le mie mani sono a posto, le mie gambe non tanto.', '', 28153),
(136179, 'itIT', 'È ora di mostrare alla feccia dell\'Alleanza il potere brandito dall\'Orda!', '', 28153),
(136178, 'itIT', 'I nostri lupi vengono addestrati e preparati alla battaglia da quando sono cuccioli.', '', 28153),
(136177, 'itIT', 'Non c\'è tempo per le chiacchiere. Abbiamo del lavoro da fare.', '', 28153),
(136176, 'itIT', '', 'Sì? Cosa posso fare per te?', 28153),
(136170, 'itIT', 'Jaina! Sia ringraziata la Luce, sei arrivata! Abbiamo davvero bisogno di te.', '', 28153),
(136169, 'itIT', '', 'Kel\'vax era figlio nostro, ma mo\' è soltanto nu mostro. Distruggilo, così potremo mandare l\'anima sua da Bwonsamdi.', 28153),
(136167, 'itIT', '', 'Kel\'vax profana tutto ciò che Bwonsamdi rappresenta. Trova quei filatteri, così porremo fine a chesto affronto!', 28153),
(136166, 'itIT', '', 'Aiutami a ripulire il vecchio luogo di culto di Bwonsamdi. E pensare che na volta era così glorioso...', 28153),
(136165, 'itIT', '', 'Aspetta... ci sta qualcuno laggiù... e nun sono Troll del Sangue! Ehi, venite accà!', 28153),
(136164, 'itIT', '', 'Le mie creazioni... non possono essere sconfitte...', 28153),
(136163, 'itIT', '', 'Queste anime sono mie!', 28153),
(136162, 'itIT', 'Di chesto passo, nun libereremo mai chesto posto per Bwonsamdi!', '', 28153),
(136161, 'itIT', '', 'Ah, eccoti! Stavo giusto dando n\'occhiata al rapporto di Mutumba. Sembra che voi due abbiate vissuto na bella avventura.', 28153),
(136160, 'itIT', '', 'Mi sono presa cura di questi boschi quando ero in vita. Non diventerò il burattino di queste streghe!', 28153),
(136159, 'itIT', 'Com\'è... bella...', '', 28153),
(136156, 'itIT', '', 'Piano, le ferite tue sono profonde.', 28153),
(136153, 'itIT', 'Possiamo partire.', 'Possiamo partire.', 28153),
(136152, 'itIT', '', 'Non è mai sicuro vagare per queste dune da soli.', 28153),
(136151, 'itIT', 'Durante la mia vita ho protetto queste terre.\n\nOra giuro di fare lo stesso nella morte.', '', 28153),
(136150, 'itIT', '', 'Ci vediamo nell\'Aldilà.', 28153),
(136149, 'itIT', 'Il volere di Bwonsamdi è compiuto. È giunta l\'ora di riposare nu poco.', '', 28153),
(136148, 'itIT', 'No! Nun riesco a vedere Bwonsamdi, nun voglio... ti prego, BASTA!', '', 28153),
(136147, 'itIT', '', 'Il destino tuo mo\' sta nelle mani di Bwonsamdi. Spera che tenga più pietà di chella che ha tenuto per noi.', 28153),
(136146, 'itIT', 'No! Madre, fa\' qualcosa!', '', 28153),
(136145, 'itIT', 'È tardi assai per chello, figlio mio. Hai scelto di tradire Bwonsamdi. Devi pagare per chesto.', '', 28153),
(136144, 'itIT', 'Padre... madre... mi dispiace. Vi prego, perdonatemi, parlate con Bwonsamdi per conto mio!', '', 28153),
(136141, 'itIT', 'Io mi prendo cura dei morti.$b$b<Allen alza le spalle.>$b$bSi tira avanti.', '', 28153),
(136140, 'itIT', '', 'Stupido Loa! Troverai solo la morte accà!', 28153),
(136116, 'itIT', 'Vieni, torniamo al Tugurio.', '', 28153),
(136115, 'itIT', 'Ohohoh! I nostri nemici scappano!', '', 28153),
(136114, 'itIT', 'Bwonsamdi! No... G\'huun mi aveva promesso che nun sarei mai stato sconfitto!', '', 28153),
(136113, 'itIT', 'Basta preoccuparsi tanto! Le creature della superstizione non sono mai così pericolose come le storie vorrebbero farci credere.', '', 28153),
(136112, 'itIT', 'Tengo nu brutto presentimento... Sta\' accuort\', $n!', '', 28153),
(136111, 'itIT', 'Bene! Ora che il loro capo è morto, i suoi servitori cadranno. Cibiamoci di loro!', '', 28153),
(136110, 'itIT', 'Che siate maledetti voi e Bwonsamdi! Nun terrà l\'anima mia!', '', 28153),
(136109, 'itIT', 'Li spiriti vostri alimenteranno il Dio del Sangue!', '', 28153),
(136108, 'itIT', 'Kel\'vax sta di nuovo vulnerabile... tocca a te!', '', 28153),
(136107, 'itIT', 'Che cosa... Impossibile! Nun sarò incatenato, né da te... né da Bwonsamdi!', '', 28153),
(136106, 'itIT', 'Mo\' devi affrontare il giudizio di Bwonsamdi! Noi teniamo i filatteri, mentre il campione tiene le ossa per contrastare il vudù tuo!', '', 28153),
(136105, 'itIT', 'Madre... padre...', '', 28153),
(136104, 'itIT', '', 'Kel\'vax, mo\' basta!', 28153),
(136103, 'itIT', 'Vi unirete ai servitori di Bwonsamdi in una sofferenza eterna!', '', 28153),
(136102, 'itIT', 'BASTA! Gli Dei del Sangue vogliono la tua distruzione... e io gliela darò, che sia dannato Bwonsamdi!', '', 28153),
(136101, 'itIT', 'Nun ci sta da preoccuparsi. Ho visto la nascita e la caduta di chesta civiltà... Nun mi fermerai!', '', 28153),
(136100, 'itIT', 'Cosa? Dove stanno li zombi miei? E li scheletri miei? Che sta succedendo?', '', 28153),
(136099, 'itIT', 'Folle mortale... le armate mie ti distruggeranno. Servitori, a me!', '', 28153),
(136096, 'itIT', 'Ehi, non ti conosco. Sei qui per aiutare o cosa?', '', 28153),
(136095, 'itIT', 'Basta con questa farsa!', 'Basta con questa farsa!', 28153),
(136094, 'itIT', '', 'Fa\' attenzione a ficcare il naso negli affari dei Bracescura. Sono loschi quanto il loro nome.', 28153),
(136093, 'itIT', 'Non male per un cane randagio pulcioso. Per tua fortuna non ti ho trovato quando ci siamo arenati, o le tue budella sarebbero ancora incrostate sui miei stivali.', 'Non male per un cane randagio. Per fortuna non t\'ho trovato appena arenati, o le tue budella sarebbero ancora sui miei stivali.', 28153),
(136092, 'itIT', 'Fatevi sotto, dannate megere! Userò le vostre pelli come stendardi!', 'Fatevi sotto, dannate megere! Userò le vostre pelli come stendardi!', 28153),
(136086, 'itIT', '', 'Il padre mio nu tempo governava col pugno di ferro e nessuno osava infrangere le leggi sue. Ma era anche giusto, pronto ad aiutare chi ne teneva bisogno e per chesto era molto amato dai sudditi suoi.$b$bMo\' il pugno di ferro nun ci sta più. Chelli di cui si fida avvelenano la mente sua, mentre complottano alle spalle sue.$b$bNun so cos\'abbiano in mente, ma so che la gente nostra nun tiene più tempo per aspettare e vedere.', 28153),
(136085, 'itIT', '', 'Figli miei, uccidete chesta creatura!', 28153),
(136072, 'itIT', 'La marea del sangue si abbatterà su di voi da nord! Vi inginocchierete tutti quanti!', 'La marea del sangue si abbatterà su di voi da nord! Vi inginocchierete tutti quanti!', 28153),
(136071, 'itIT', 'Presto verranno a Nazmir e allora vedrete ciò che abbiamo visto tutti quanti noi.', 'Presto verranno a Nazmir e allora vedrete ciò che abbiamo visto tutti quanti noi.', 28153),
(136070, 'itIT', 'No! Nun puoi fermarci. Ha promesso che nun puoi fermarci.', 'No! Nun puoi fermarci. Ha promesso che nun puoi fermarci.', 28153),
(136069, 'itIT', 'Il sangue tuo varrà n\'ottimo prezzo.', 'Il sangue tuo varrà n\'ottimo prezzo.', 28153),
(136068, 'itIT', 'Nun puoi avvertire le guardie della presenza mia, se schiatti.', 'Nun puoi avvertire le guardie della presenza mia, se schiatti.', 28153),
(136067, 'itIT', 'Chi sei tu per sfidarci?', 'Chi sei tu per sfidarci?', 28153),
(136039, 'itIT', 'Cosa succede? I nemici sono alle nostre spalle! Se non li affronterai con me, allora lo farò da solo.', '', 28153),
(136015, 'itIT', 'Le spedizioni sembrano contenere delle comuni parti di mostro.', '', 28153),
(136003, 'itIT', 'È ora di finirla. Incontriamoci sul limitare del fiume.', '', 28153),
(135928, 'itIT', '', 'Chesti non morti sono n\'affronto a Bwonsamdi. Dobbiamo occuparcene il prima possibile.', 28153),
(135927, 'itIT', 'Il volere di Bwonsamdi dev\'essere compiuto. Nun possiamo restarcene con le mani in mano.', '', 28153),
(135904, 'itIT', 'Vieni al mio eremo, c\'è ancora molto da fare.', '', 28153),
(135903, 'itIT', '', 'No! Perdonami, Krag\'wa.', 28153),
(135901, 'itIT', 'Sei così orgogliosa da mettere in dubbio la mia scelta su chi voglio donare quest\'onore?', '', 28153),
(135900, 'itIT', '', 'Krag\'wa! Sarebbe n\'onore, ma nun me lo merito... nun sono riuscita a fermare i Naga.', 28153),
(135898, 'itIT', 'Narez. Ti sei dimostrata degna di diventare mia seguace.', '', 28153),
(135875, 'itIT', '', 'Rimarrò accà a controllare i Naga e dimostrerò la devozione mia a Krag\'wa. Ci vediamo.', 28153),
(135874, 'itIT', 'Oh, no, per niente! Nun strapperai i guaglioni dalle mani mie!', '', 28153),
(135869, 'itIT', 'Fai strada.', 'Fai strada.', 28153),
(135868, 'itIT', 'Sei $gnuovo:nuova;? Chi sei?$b$bBuon Cumpà nun starà felice che nun sei $gandato:andata; a trovarlo subito. Vieni con me.', '', 28153),
(135865, 'itIT', '', 'E loro dicevano che ero una pazza a tenere una pergamena così \"specializzata\". Bah!', 28153),
(135861, 'itIT', '%s muore a causa delle sue ferite.', '%s muore a causa delle sue ferite.', 28153),
(135843, 'itIT', '', 'I Demoni delle Fauci... ne volevo... ancora... uno...', 28153),
(135842, 'itIT', '', 'Sarete n\'ottima fonte d\'energia per i totem miei!', 28153),
(135795, 'itIT', '<La rana gigante giace morta nel fango.>', '', 28153),
(135777, 'itIT', 'Disperdetevi!', '', 28153),
(135776, 'itIT', 'Ahhh!', '', 28153),
(135774, 'itIT', 'Jamme!', '', 28153),
(135772, 'itIT', 'Ih!', '', 28153),
(135771, 'itIT', 'Lo dirò a Buon Cumpà!', '', 28153),
(135770, 'itIT', 'Mi serviva!', '', 28153),
(135769, 'itIT', 'Ah! Allarme stranieri!', '', 28153),
(135768, 'itIT', 'Chesto nun piacerà a Buon Cumpà!', '', 28153),
(135741, 'itIT', 'Cosa?', 'Cosa?', 28153),
(135740, 'itIT', 'Cos\'ha detto $gil:la; prode $R al Taumaturgo?', '', 28153),
(135733, 'itIT', 'Aveva torto. Ci furono danni, ma Zul fuggì con la flotta nostra, dando inizio a na manciata di guerre. Chi di noi è rimasto, ha resistito. Abbiamo ricostruito tutto, perché è CHESTO che significa essere nu Zandalari.', '', 28153),
(135732, 'itIT', 'Le visioni di Zul, bah! Ti ha detto di chella volta che ha previsto che Zandalar sarebbe affondata sotto le onde?', '', 28153),
(135726, 'itIT', 'Ho visto centinaia di vascelli partire da chesti moli ogni mese verso chella terra e mi sono sempre assicurato che chelle navi arrivassero in orario.$b$bQuindi parla velocemente, il tempo mio è prezioso.', '', 28153),
(135719, 'itIT', '', 'Procedete.', 28153),
(135701, 'itIT', 'Ci stanno molte storie su Xibala, ma nun so quale sia chella vera. Li antichi lo temevano, chesto è certo.\n\nAlcuni dicono che Xibala faccia imputridire i corpi della gente.\n\nAltri che chiunque lo guardi, si trasforma in no scheletro vivente.\n\nSi dice che si nasconda nelle ombre ed esca la notte per divorare la gente nel sonno.\n\nO anche che attenda presso le strade, facendo tossire sangue ai malcapitati viaggiatori fino alla morte loro.\n\nAnche i combattenti più coraggiosi stanno alla larga da chesto posto.', '', 28153),
(135699, 'itIT', 'Chi era Xibala?', 'Chi era Xibala?', 28153),
(135694, 'itIT', '', 'Pe... penso di potermi intrufolare nella caverna dove si trova mia sorella. Vediamoci là.', 28153),
(135683, 'itIT', '$C, cosa ci fai qui?', '', 28153),
(135680, 'itIT', 'Siamo pronti a iniziare il processo.', 'Siamo pronte a iniziare il processo.', 28153),
(135679, 'itIT', 'Questo stallo non ti aiuterà. Presto scopriremo la verità che si cela dietro al nome di Dama Crestabianca!', '', 28153),
(135674, 'itIT', 'I nostri Cavalieri del Vento possono essere caduti, ma il nostro vero potere è nell\'ascia che impugniamo!', '', 28153),
(135673, 'itIT', 'Artiglieria o meno, la nostra forza è ineguagliabile!', '', 28153),
(135670, 'itIT', 'Le mie lame faranno a pezzi la tua carne!', '', 28153),
(135638, 'itIT', 'Quei mostri hanno abbattuto l\'ultimo mio seguace. Scatenerò su di loro una furia di diecimila anni!', '', 28153),
(135610, 'itIT', '', 'Chesto ascensore ti porterà alla camera sottostante, dove ti aspetta la Principessa Talanji. $gAttento:Attenta; ai gradini.', 28153),
(135604, 'itIT', '', 'Seguimi. Ti mostro la strada più veloce.', 28153),
(135586, 'itIT', '', 'Vieni a farmi visita quando ti capita. Non vedo l\'ora di mostrarti tutto ciò che ho scoperto su questi segni.', 28153),
(135579, 'itIT', '', 'Non preoccuparti per me... posso tornare all\'arena da sola.', 28153),
(135578, 'itIT', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Yazma inizia a lanciare |cFFFF0404|Hspell:249924|h[Laceranima]|h|r su |cFFFF0000$n|r!', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Yazma inizia a lanciare |cFFFF0404|Hspell:249924|h[Laceranima]|h|r su $n!', 28153),
(135577, 'itIT', 'Sento le mie forze tornare... Sembra che l\'antidoto stia funzionando.', '', 28153),
(135576, 'itIT', 'Nun so quanto tempo sia rimasto a Julwaba... l\'antidoto è l\'unica speranza sua.', '', 28153),
(135574, 'itIT', 'Julwaba e Taz\'jin sono spariti da giorni. Comincio a preoccuparmi per la sorte loro...', '', 28153),
(135565, 'itIT', 'Vai, veloce! I Naga devono essere accisi per salvare i seguaci di Krag\'wa!', '', 28153),
(135555, 'itIT', '', 'Che la benedizione di Krag\'wa stia con te. Mostra a Zaldraxia che si è messa contro il Loa sbagliato.', 28153),
(135539, 'itIT', 'I Naga devono essere fermati, non ti preoccupare per me.', '', 28153),
(135511, 'itIT', 'Portami da Re Rastakhan.', 'Portami da Re Rastakhan.', 28153),
(135496, 'itIT', 'La nostra Città è sotto attacco!', 'La nostra Città è sotto attacco!', 28153),
(135492, 'itIT', 'Sto mandando dei lavoratori a occuparsi di quella vena d\'Azerite.', '', 28153),
(135486, 'itIT', 'La Miniera è sotto attacco!', 'La Miniera è sotto attacco!', 28153),
(135469, 'itIT', '', 'Che c\'è, $C?', 28153),
(135466, 'itIT', 'Pergamena inutile... forza, TROVA SHOAK!', '', 28153),
(135465, 'itIT', 'Avanti, devi trovare Shoak, NON SALTELLARE SU QUEL TOTEM!', '', 28153),
(135464, 'itIT', 'Ma perché non FUNZIONI!?! Trova Shoak!', '', 28153),
(135457, 'itIT', '', 'Ci potrebbero essere danni collaterali, ma sono certa che poi riusciremo a rimettere i pezzi insieme. Forse dovremo chiamare qualche assistente ricercatore in più...', 28153),
(135456, 'itIT', 'Li spiriti nun staranno felici di tutto chesto. Nun dire che nun te lo avevo detto!', '', 28153),
(135455, 'itIT', 'Ehi! Ti conviene nun lanciare bombe su chelle ossa!', '', 28153),
(135446, 'itIT', '', 'Muori, $gintruso:intrusa;!', 28153),
(135445, 'itIT', '', 'Tu ci servirai!', 28153),
(135444, 'itIT', '', 'No! Non posso fallire!', 28153),
(135443, 'itIT', '', 'No... Mi era stato promesso... il potere...', 28153),
(135442, 'itIT', '', 'Invocherai la morte prima che io abbia finito!', 28153),
(135441, 'itIT', '', 'Anche tu mi servirai!', 28153),
(135440, 'itIT', '', 'Non puoi fermarmi!', 28153),
(135439, 'itIT', 'Porterò il tuo cuore alla padrona!', '', 28153),
(135432, 'itIT', 'L\'Alleanza ha conquistato una vena d\'Azerite!', '', 28153),
(135431, 'itIT', '$n ha difeso una vena d\'Azerite!', '', 28153),
(135430, 'itIT', 'L\'Orda ha conquistato una vena d\'Azerite!', '', 28153),
(135429, 'itIT', '$n ha attaccato una vena d\'Azerite!', '', 28153),
(135405, 'itIT', 'Molto bene. Ma sappi che richiederò na petizione al re per avere la testa di chesta bestia.', '', 28153),
(135400, 'itIT', 'Basta così. Generale, ti farai da parte. Chesto membro dell\'Orda ha superato le sfide di due tribù. Secondo la legge, devi lasciarlo passare.', '', 28153),
(135399, 'itIT', 'I\'m placeholder text. If you see this, Josh has made a mistake.', 'I\'m placeholder text. If you see this, Josh has made a mistake.', 28153),
(135388, 'itIT', 'Dicono che il re non ha lasciato il trono da quando è morta la moglie sua.', 'Dicono che il re non ha lasciato il trono da quando è morta la moglie sua.', 28153),
(135387, 'itIT', 'L\'Orda? Qui a Zuldazar? Male, molto male...', 'L\'Orda? Qui a Zuldazar? Male, molto male...', 28153),
(135386, 'itIT', 'Quando Zul se n\'è andato, ha portato molti di noi con sé. Ora dicono che i Troll del Sangue attaccano il confine settentrionale.', 'Quando Zul se n\'è andato, ha portato molti di noi con sé. Ora dicono che i Troll del Sangue attaccano il confine settentrionale.', 28153),
(135385, 'itIT', '', 'Oh... Mi dispiace, continentale, ma dovrò chiederti un altro favore.', 28153),
(135384, 'itIT', 'Allora, temo che dovremo attendere.', '', 28153),
(135383, 'itIT', '', 'Ma potrebbero volerci anni!', 28153),
(135382, 'itIT', 'Hai superato le prove, ma verrai assolta soltanto quando scopriremo cosa è veramente accaduto al nostro villaggio.', '', 28153),
(135381, 'itIT', '', 'Cosa?!? Dopo tutto quello a cui mi sono sottoposta?', 28153),
(135380, 'itIT', 'Non sono convinto. Questo non spiega ancora quanto accaduto alla Conca degli Impennatori.', '', 28153),
(135379, 'itIT', 'Silenzio! Sarò io a emettere la sentenza finale qui!', '', 28153),
(135378, 'itIT', 'Forse non è una strega, dopotutto! Ma... i-il villaggio, allora...?', 'Forse non è una strega, dopotutto! Ma allora cosa è stato a ridurre così il nostro villaggio?', 28153),
(135377, 'itIT', 'Sta male! Impossibile!', '', 28153),
(135376, 'itIT', '', 'Ohhh... Non mi sento tanto bene...', 28153),
(135375, 'itIT', '', 'Lo farò. Il veleno, continentale.', 28153),
(135374, 'itIT', 'Siete pronta a dimostrare il contrario, Dama Crestabianca?', '', 28153),
(135373, 'itIT', 'È noto che il potere di una strega non sia alimentato dal semplice cibo, ma dalle anime delle sue vittime. È per questo che non vi è nulla dentro di loro.', '', 28153),
(135372, 'itIT', 'Interessante, ma ancora insufficiente. Passiamo all\'ultima prova: la purificazione delle viscere.', '', 28153),
(135371, 'itIT', 'Non sembrano evitarla. Anzi, sembrano pungere ancora più del solito!', 'Non sembrano evitarla. Anzi, sembrano pungere ancora più del solito!', 28153),
(135370, 'itIT', '', 'Ah! Ahi! Ugh! Ah, Che male!', 28153),
(135369, 'itIT', '', 'Non preoccuparti. Posso sopravvivere a qualche puntura d\'insetto.', 28153),
(135368, 'itIT', 'Liberate gli insetti e osservateli fuggire dall\'imputata!', '', 28153),
(135367, 'itIT', 'La seconda prova è la puntura degli insetti. È risaputo, infatti, che perfino il più vorace degli Insetti del Sangue non assaggerebbe mai il sangue di una strega.', '', 28153),
(135366, 'itIT', 'Calma, calma. Potrebbe trattarsi di qualche altro tipo di inganno. Continuiamo con il processo.', '', 28153),
(135365, 'itIT', 'Sta piangendo! Le streghe non possono piangere, giusto?!?', 'Sta piangendo! Le streghe non possono piangere, giusto?!?', 28153),
(135364, 'itIT', '', 'Prego, continentale. Fagli vedere.', 28153),
(135363, 'itIT', 'L\'imputata è in grado di piangere? Ce lo dimostri, così potremo procedere col nostro giudizio.', '', 28153),
(135362, 'itIT', 'La prima prova riguarda il versamento delle lacrime. Sia messo agli atti che Dama Crestabianca non ha versato una sola lacrima durante l\'intero processo.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(135361, 'itIT', 'Ella ha richiesto che sia questa persona a sottoporle le prove. Con grande magnanimità, ho deciso di acconsentire.', '', 28153),
(135360, 'itIT', 'Come da tradizione, Dama Crestabianca ha scelto le prove a cui si sottoporrà per dimostrare la sua innocenza di fronte all\'accusa di stregoneria oscura.', '', 28153),
(135359, 'itIT', 'Finalmente! Il processo può cominciare!', '', 28153),
(135358, 'itIT', 'Avete finito? Sto diventando impaziente!', '', 28153),
(135357, 'itIT', 'Tempo fa ho sentito la storia di una strega che viveva nella palude. I cittadini riuscirono a scoprirla perché gli Insetti del Sangue non le si avvicinavano minimamente.\n\nMordevano chiunque altro, ma non lei!\n\nDicono che questo accade perché il suo sangue è così infetto e malvagio che nemmeno un Insetto del Sangue oserebbe assaggiarlo!', '', 28153),
(135356, 'itIT', 'Non ho mai visto una vera strega prima d\'ora. Non è emozionante?', '', 28153),
(135355, 'itIT', 'Ai miei tempi, si usava appesantirle e gettarle nel fiume! Se venivano a galla, era chiaro che avessero stretto un patto con qualche forza empia e a quel punto le impiccavamo!\n\nQuesto è l\'unico modo per assolvere una strega, a mio modo di vedere!', '', 28153),
(135354, 'itIT', 'La maledizione oscura della strega ha colpito mio figlio! Oggi sarà fatta giustizia!', '', 28153),
(135353, 'itIT', '', 'Non... non ne sono sicura...\n\nDicono che le streghe non possano sentirsi male, perché la loro pancia è costantemente divorata dagli spiriti oscuri che vivono al suo interno.\n\nNon ho idea di come si possa provare una cosa del genere però...', 28153),
(135352, 'itIT', '', 'Bisogna fare qualcosa per porre fine alla maledizione che affligge il nostro villaggio.\n\nDi certo se la strega venisse uccisa, la magia verrebbe dissolta, giusto?', 28153),
(135351, 'itIT', 'Ho sentito che il corpo di una strega resiste anche alle fiamme. È per questo che vengono impiccate quando sono scoperte!\n\nDatele fuoco, se volete convincermi!', '', 28153),
(135350, 'itIT', 'Quella donna ha portato la malvagità nel nostro villaggio. Deve pagare!', '', 28153),
(135349, 'itIT', '', 'Mia mamma mi diceva che le streghe non piangono mai, non importa quanto sono tristi o quanto dolore provano.\n\nIo ho visto tutto! Dama Crestabianca non ha pianto neanche un po\' dopo aver saputo del processo. È sicuramente una strega!', 28153),
(135348, 'itIT', 'Come si fa a dimostrare che qualcuno non è una strega?', 'Come si fa a dimostrare che qualcuno non è una strega?', 28153),
(135347, 'itIT', '', 'Il processo è una cosa orribile, ma giustizia dev\'essere fatta per la Conca degli Impennatori!', 28153),
(135346, 'itIT', 'Dama Crestabianca ha deciso come provare la sua innocenza?', '', 28153),
(135345, 'itIT', 'Finalmente! Diamoci da fare!', '', 28153),
(135344, 'itIT', 'Conestabile! Potete continuare questo... processo.', '', 28153),
(135343, 'itIT', 'Ci hai fatto guadagnare un po\' di tempo, continentale. Speriamo solo che questi villici non vogliano fare del male a Dama Crestabianca.', '', 28153),
(135342, 'itIT', '', 'Salvarmi? Hai forse intenzione di far fuori anche questi cittadini per farlo?\n\nNo, se davvero vuoi darmi una mano, dovrai aiutarmi con il Maresciallo.\n\nSebbene le loro accuse siano fuori luogo, questa resta comunque la mia gente, e non permetterò che gli venga fatto del male. Avranno il processo che vogliono e proverò la mia innocenza.\n\nA ogni modo, temo che il Maresciallo voglia occuparsi di questa faccenda personalmente e non posso fare molto nella mia situazione attuale. Vedi se riesci a convincerlo a lasciare che questo processo segua il suo corso.', 28153),
(135341, 'itIT', 'Sono qui per salvarti.', 'Sono qui per salvarti.', 28153),
(135340, 'itIT', '', 'Mi dispiace che tu sia $gstato messo:stata messa; in mezzo a tutto questo. Loro sono davvero brave persone, ma gli ultimi tempi le hanno messe a dura prova.', 28153),
(135339, 'itIT', '', 'Non farete nulla del genere, Maresciallo! Vi ordino di ritirarvi!', 28153),
(135338, 'itIT', 'Non c\'è tempo per le discussioni. Se non vi farete da parte, la prenderemo con la forza!', '', 28153),
(135337, 'itIT', 'Dama Crestabianca è accusata di stregoneria oscura! Non ve la consegneremo a meno che non sia assolta dai suoi crimini!', '', 28153),
(135336, 'itIT', 'Conestabile Framer! Ti ordino di liberare Dama Crestabianca e affidarla alla mia custodia!', '', 28153),
(135335, 'itIT', 'Altre interruzioni?!? Che c\'è questa volta?', '', 28153),
(135334, 'itIT', 'Guardate! Stanno arrivando dei cavalieri dal bosco!', 'Guardate! Arrivano dei cavalieri dal bosco!', 28153),
(135333, 'itIT', 'Oh, quanto detesto le interruzioni! Cosa ci fai qui, continentale?', '', 28153),
(135332, 'itIT', 'Conestabile! A-arriva qualcuno!', 'Conestabile! Arriva $guno straniero:una straniera;!', 28153),
(135331, 'itIT', 'Con il presente atto, sarai...', '', 28153),
(135330, 'itIT', 'Lucille Crestabianca! Sei accusata di praticare la stregoneria oscura e di aver gettato una maledizione sul villaggio della Conca degli Impennatori.', '', 28153),
(135301, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [70] Richiama una Treruote da Guerra', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [70] Richiama una Treruote da Guerra', 28153),
(135286, 'itIT', '', 'È stato stupido da parte mia andarmene in giro da sola in cerca di antiche reliquie...', 28153),
(135281, 'itIT', 'Cos... Hic! Cosha shtai guardando, cumpà?', '', 28153),
(135272, 'itIT', 'Parliamo di cosa possiamo fare per combattere i Troll del Sangue.', 'Parliamo di cosa possiamo fare per combattere i Troll del Sangue.', 28153),
(135265, 'itIT', '', 'Ce ne sta ancora uno... accà!', 28153),
(135263, 'itIT', '', 'Ecco! Torga, il Loa Tartaruga. È benevolo e saggio e so che ci aiuterà! Vediamo chi altro c\'è...', 28153),
(135261, 'itIT', '', 'Nazmir è nu posto maledetto... ma è anche il luogo di riposo dei Loa. Sta\' indietro, cercherò di scoprire quali di loro si trovano accà.', 28153),
(135226, 'itIT', 'Grazie! Stavo vivendo un vero incubo.', '', 28153),
(135225, 'itIT', 'Devi fermarla!', '', 28153),
(135224, 'itIT', 'Che succede?', '', 28153),
(135221, 'itIT', 'Ti ucciderò!', '', 28153),
(135220, 'itIT', 'Come osi interrompere il lavoro della padrona?', '', 28153),
(135209, 'itIT', '', 'Vediamo cos\'altro sta là fuori.', 28153),
(135190, 'itIT', 'Accà, Mignolo! Tengo nu buon bocconcino per te!', 'Accà, Mignolo! Tengo nu buon bocconcino per te!', 28153),
(135189, 'itIT', 'L\'Alleanza ha conquistato la Miniera.', 'L\'Alleanza ha conquistato la Miniera.', 28153),
(135188, 'itIT', 'Be\', le cose sono state nu poco strane. Ma tutto è bene chello che finisce bene, vero?', '', 28153),
(135187, 'itIT', 'Chiunque controlli quesssto pennone... comanda la mia ciurma...', '', 28153),
(135185, 'itIT', 'Alcuni attendono il ritorno della flotta. Ma io ricordo i Troll che sono salpati con Zul. Stavano arrabbiati assai.', 'Alcuni attendono il ritorno della flotta. Ma io ricordo i Troll che sono salpati con Zul. Stavano arrabbiati assai.', 28153),
(135184, 'itIT', 'È vero che Zul è stato trascinato nuovamente a Zandalar? Scommetto che nun sta felice di tutto chesto.', 'È vero che Zul è stato trascinato nuovamente a Zandalar? Scommetto che nun sta felice di tutto chesto.', 28153),
(135179, 'itIT', 'Nun amo l\'Orda, ma avete ucciso molta feccia dell\'Alleanza, per cui nun potete essere così male.', 'Nun amo l\'Orda, ma avete ucciso molta feccia dell\'Alleanza, per cui nun potete essere così male.', 28153),
(135178, 'itIT', 'Hai davvero combattuto al fianco della Principessa Talanji? Ha sciolto il viso di qualcuno? Ha strappato la mente ai nemici suoi? Com\'era il maleficio suo?', 'Hai davvero combattuto al fianco della Principessa Talanji? Ha sciolto il viso di qualcuno? Ha strappato la mente ai nemici suoi? Com\'era il maleficio suo?', 28153),
(135177, 'itIT', 'Ho sentito che la gente tua segue nu capo non morto. Al vecchio Bwonsamdi nun piacerà.', 'Ho sentito che la gente tua segue nu capo non morto. Al vecchio Bwonsamdi nun piacerà.', 28153),
(135176, 'itIT', 'Sei dell\'Orda? È vero che Vol\'jin è schiattato?', 'Sei dell\'Orda? È vero che Vol\'jin è schiattato?', 28153),
(135175, 'itIT', 'Ringrazia i Loa per il ritorno della Principessa Talanji. Nun è stata assente a lungo, ma a coloro che agivano contro di lei serviva poco tempo.', 'Ringrazia i Loa per il ritorno della Principessa Talanji. Nun è stata assente a lungo, ma a coloro che agivano contro di lei serviva poco tempo.', 28153),
(135174, 'itIT', 'Prima i nun Troll e mo\' l\'Orda? Chi altro farà entrare Talanji nella città?', 'Prima i nun Troll e mo\' l\'Orda? Chi altro farà entrare Talanji nella città?', 28153),
(135173, 'itIT', 'L\'Orda sta accà? Che tempi bui.', 'L\'Orda sta accà? Che tempi bui.', 28153),
(135147, 'itIT', 'Io... cos\'è successo? Me ne vado!', '', 28153),
(135140, 'itIT', 'Padre, aiutami. Ho bisogno della tua guida. Ho bisogno...', '', 28153),
(135138, 'itIT', 'Mio re, le torri d\'assedio sono distrutte! Le nostre truppe non riusciranno...', '', 28153),
(135002, 'itIT', 'Non posso lasciare qui questo coso. Prendilo o lo riporto indietro!', '', 28153),
(135001, 'itIT', 'Se nessuno apre la cassa, mi toccherà attivare il dispositivo di richiamo!', '', 28153),
(134991, 'itIT', 'Be\', non si può vincere tutto.', '', 28153),
(134989, 'itIT', 'Davvero? Nessuno? Fatti vostri!', '', 28153),
(134976, 'itIT', 'L\'ho visto io per primo!', 'L\'ho visto io per prima!', 28153),
(134975, 'itIT', 'Ti spiace se scelgo necessità?', 'Ti spiace se scelgo necessità?', 28153),
(134877, 'itIT', 'Va bene, diamoci da fare! Il primo che la apre, vince tutto!', '', 28153),
(134876, 'itIT', 'Ancora 15 secondi. Preparati a un bel casino!', '', 28153),
(134875, 'itIT', 'Sblocco in corso! Dammi solo 30 secondi.', '', 28153),
(134869, 'itIT', 'Il carico sta arrivando! Attenti alla testa!', '', 28153),
(134867, 'itIT', 'Ascoltate, abbiamo un sacco di rifornimenti diretti ai Bassopiani!', '', 28153),
(134811, 'itIT', 'Sblocco completato! Il vincitore prende tutto!', '', 28153),
(134810, 'itIT', '15 secondi allo sblocco!', '', 28153),
(134809, 'itIT', 'Sequenza di sblocco attivata! Meno 30 secondi.', '', 28153),
(134790, 'itIT', 'Carico consegnato! Attenzione là sotto!', '', 28153),
(134789, 'itIT', 'Rifornimenti in arrivo per i Bassopiani!', '', 28153),
(134699, 'itIT', '', 'Vai avanti. Devo scambiare altre parole con chesto serpente delle sabbie.', 28153),
(134678, 'itIT', 'Non uccideremo le rane, ma quesssto non vale per te!', '', 28153),
(134676, 'itIT', 'Cattureremo e prosciugheremo le tue piccole rane!', '', 28153),
(134675, 'itIT', 'Devo difendere la sua nuova fonte di mana!', '', 28153),
(134674, 'itIT', '$gLurido:Lurida; $R, non ci impedirai di sfruttare la nossstra fonte di mana!', '', 28153),
(134673, 'itIT', 'Quando sarai $gmorto:morta;, ci prenderemo altre rane!', '', 28153),
(134672, 'itIT', 'Abbiamo l\'ordine di non uccidere le rane, ma posssiamo uccidere te!', '', 28153),
(134671, 'itIT', 'Non ci fermerai. Le rane ci nutriranno per anni!', '', 28153),
(134670, 'itIT', '', 'Le rane appartengono ai Naga!', 28153),
(134669, 'itIT', '', 'Non ti lasceremo prendere le nossstre rane!', 28153),
(134668, 'itIT', '', 'Morte ai ladri di mana!', 28153),
(134667, 'itIT', '', 'Quessste rane ci appartengono!', 28153),
(134666, 'itIT', '', 'Le rane sono nossstre!', 28153),
(134665, 'itIT', '', 'Quessste rane ci sazieranno per anni!', 28153),
(134664, 'itIT', '', 'Useremo quessste rane per salvare la nossstra gente!', 28153),
(134663, 'itIT', '', 'Quessste rane ci nutriranno!', 28153),
(134661, 'itIT', 'Il vile attacco dell\'Orda a Teldrassil ci ha condotti alla guerra... e ha reso finalmente chiara la posta in gioco.', '', 28153),
(134656, 'itIT', 'Krag\'wa ricompenserà la tua fede. Vieni.', '', 28153),
(134652, 'itIT', '', 'I nonni miei mi raccontavano storie su Krag\'wa. Nessuno ci credeva... a parte me. Volevo che fosse vero.', 28153),
(134651, 'itIT', 'So cosa provi, Narez. Sei stata fedele a Krag\'wa per tutto questo tempo.', '', 28153),
(134650, 'itIT', '', 'Aspetta! Prima che tu vada...', 28153),
(134649, 'itIT', 'È ora di ritornare all\'eremo. Grazie ancora per tutto il tuo aiuto', '', 28153),
(134648, 'itIT', 'Dicono pure che il padre tuo si sia fatto prendere dalla debolezza e abbia inviato la figlia sua a pregare Zul di tornare con la flotta. Nun è forse così, maestà?', '', 28153),
(134647, 'itIT', '', 'Come osi parlarmi in chesto...', 28153),
(134646, 'itIT', 'Riusciremo a contrastare i Naga solo quando Zaldraxia sarà stata sconfitta. Buona fortuna.', '', 28153),
(134639, 'itIT', 'Un Demolitore nemico è comparso presso la Struttura Sud dell\'Orda!', 'Un Demolitore nemico è comparso presso la Struttura Sud dell\'Orda!', 28153),
(134638, 'itIT', '', 'In tutti gli anni passati su queste colline, non ho mai visto mostri come quelli!', 28153),
(134637, 'itIT', '<Mostrale la Parola di Zul.>', '<Mostrale la Parola di Zul.>', 28153),
(134630, 'itIT', '', 'Non... Non so cosa stiano tramando mia sorella e le sue amiche, ma non è nulla di buono. Le cose buone non richiedono sacrifici!', 28153),
(134629, 'itIT', '', 'Quante gambe! E quanti occhi! Mi stanno fissando!', 28153),
(134620, 'itIT', '', 'Teniamo bisogno di nu vero capo! Nun di nu re decrepito.', 28153),
(134618, 'itIT', '', 'I confini e il popolo nostri sono deboli. Teniamo bisogno della vera forza che solo Zul può offrire.', 28153),
(134617, 'itIT', '', 'Ricorda le ultime parole di Zul, il profeta nostro. Ricorda la rovina che previde per tutti noi.', 28153),
(134616, 'itIT', '', 'Re Rastakhan marcisce sul trono, troppo debole o codardo per visitare il popolo suo. Teniamo bisogno di nu capo forte assai!', 28153),
(134615, 'itIT', '', 'Zul predisse il Cataclisma e noi nun facemmo nulla. Abbiamo guardato mentre il Re lo esiliava. Abbiamo guardato mentre Zul portava i fratelli e le sorelle nostri con sé. E abbiamo guardato la distruzione causata dal Cataclisma!', 28153),
(134613, 'itIT', '', 'Zul tornerà e risolleverà l\'impero nostro dalle ceneri.', 28153),
(134610, 'itIT', '', 'È giunto il momento! Devo riferirlo agli altri. Chelli che gli sono ancora devoti devono sapere.', 28153),
(134599, 'itIT', '', 'Non ti deluderò, Regina Azshara! Le rane saranno nossstre. Me ne occuperò persssonalmente!', 28153),
(134598, 'itIT', '', 'Tutte le tue preziose rane verranno catturate e saranno al nossstro servizio!', 28153),
(134597, 'itIT', '', 'FECCIA IMPUDENTE! La nossstra gente sazierà finalmente la sua sete di magia. Niente più sete, niente più sofferenza!', 28153),
(134596, 'itIT', '', 'Eravamo... così vicini a non dover più... patire la fame...', 28153),
(134595, 'itIT', '', 'Tu! Hai rovinato tutto... le rane avrebbero dovuto saziare la nossstra sete di magia per anni!', 28153),
(134594, 'itIT', 'I Naga la pagheranno per ciò che hanno fatto.', '', 28153),
(134593, 'itIT', 'Fa\' pagare Zaldraxia per tutto ciò che ci ha fatto.', '', 28153),
(134592, 'itIT', 'Ah! Il mio potere scorre... grazie. Krag\'wa sarà informato del tuo aiuto.', '', 28153),
(134591, 'itIT', 'Ah... sento il potere scorrere di nuovo dentro di me! Hai agito bene. Krag\'wa verrà informato delle tue gesta.', '', 28153),
(134590, 'itIT', 'Mi sento... potente! Ti ringrazio, ma devo tornare da Krag\'wa.', '', 28153),
(134589, 'itIT', '', 'Anni fa, quando tornò con la flotta nostra dall\'esilio, descrisse na visione di chesto giorno, quando il mondo iniziò a sanguinare, e descrisse anche te con grande dettaglio.', 28153),
(134588, 'itIT', 'Quando hai parlato per l\'ultima volta con Zul?', 'Quando hai parlato per l\'ultima volta con Zul?', 28153),
(134587, 'itIT', '', 'Tu! Sei tu!$b$bZul mi ha raccontato di te na volta. In ogni dettaglio. Tieni pure chella... cosa... sulla faccia. Proprio come ti aveva descritto.$b$bQuindi è vero? Stai accà per riferirmi le parole sue?', 28153),
(134584, 'itIT', 'Alla fine l\'ora è giunta. È dai tempi del Re del Tuono che tengo in serbo chesta bestia, ma sembra che il giorno suo sia finalmente arrivato.', '', 28153),
(134583, 'itIT', 'La magia delle rane alimenterà la gente nostra. Nun conosceremo più la sete!', '', 28153),
(134581, 'itIT', '<Mostragli la Parola di Zul.>', '<Mostragli la Parola di Zul.>', 28153),
(134580, 'itIT', 'Che c\'è, viandante?', '', 28153),
(134492, 'itIT', '', 'Finalmente nu po\' d\'aiuto! I Naga mi hanno conciata per bene. Dobbiamo salvare le rane.', 28153),
(134471, 'itIT', '', 'Ahhh, cos\'abbiamo qui? Il Leone di Roccavento è finalmente uscito a giocare? Non hai idea di che cosa ti aspetta, ragazzino. Siamo solo all\'inizio!', 28153),
(134465, 'itIT', '', 'Mmm... sto accà a nascondermi e aspettare, le due cose che odio di più. Scopri perché chei Naga vogliono cheste rane!', 28153),
(134464, 'itIT', 'È tutto quello che sai fare, Ventolesto?!?', '', 28153),
(134463, 'itIT', 'Soldati, alle porte! Vittoria per l\'Alleanza!', '', 28153),
(134460, 'itIT', '', 'Chesti Naga nun se la caveranno per aver profanato cheste rane.', 28153),
(134453, 'itIT', 'Mo\' la Principessa nun sta accà a proteggerti.', 'Mo\' la Principessa nun sta accà a proteggerti.', 28153),
(134451, 'itIT', 'Ahah. Nessuno può salvarti a parte me.', 'Ahah. Nessuno può salvarti a parte me.', 28153),
(134450, 'itIT', 'Le guardie nun mi darebbero niente per la pellaccia tua.', 'Le guardie nun mi darebbero niente per la pellaccia tua.', 28153),
(134449, 'itIT', 'Il coltello mio dice che mi farai avere nu grosso sconto.', 'Il coltello mio dice che mi farai avere nu grosso sconto.', 28153),
(134448, 'itIT', 'Nun avete pagato in tempo per la protezione vostra.', 'Nun avete pagato in tempo per la protezione vostra.', 28153),
(134447, 'itIT', 'Altezza, nun senti l\'odore della paura che attanaglia la città?', '', 28153),
(134442, 'itIT', 'Eheh... I carichi sono già partiti...', '', 28153),
(134439, 'itIT', 'Ah! Altra carne per le salsicce!', '', 28153),
(134438, 'itIT', 'Ah! Hai ancora voglia di combattere. Permettimi di darti un assaggio di ciò che l\'Orda ha da offrirti.', '', 28153),
(134330, 'itIT', 'Si salvi chi può!', 'Si salvi chi può!', 28153),
(134329, 'itIT', 'Questo è puro caos! Devo mettermi in salvo.', 'Questo è puro caos! Devo mettermi in salvo.', 28153),
(134328, 'itIT', 'Quei Trogg sono sbucati dal nulla!', 'Quei Trogg sono sbucati dal nulla!', 28153),
(134310, 'itIT', 'Il tempio sta in rovina. È peggio di quanto pensassi.', '', 28153),
(134309, 'itIT', 'Prima che venissi acciso, ero il custode di chesto tempio. Nun oso pensare cosa ne sia rimasto dopo tutti chesti anni...', '', 28153),
(134300, 'itIT', 'Ahi! Cattivo dinosauro. Cattivo!', 'Ahi! Cattivo dinosauro. Cattivo!', 28153),
(134299, 'itIT', 'Sei $gbravo:brava;!', 'Sei $gbravo:brava;!', 28153),
(134298, 'itIT', 'Argh! Non le dita!', 'Argh! Non le dita!', 28153),
(134297, 'itIT', 'Ti farò a pezzi se farai l\'arrogante con me!', 'Ti farò a pezzi se farai l\'arrogante con me!', 28153),
(134296, 'itIT', 'Ahia! Niente morsi!', 'Ahia! Niente morsi!', 28153),
(134295, 'itIT', 'Piano... piano!', 'Piano... piano!', 28153),
(134292, 'itIT', '<%s rabbrividisce e piagnucola.>', '', 28153),
(134291, 'itIT', '<%s squittisce dalla preoccupazione.>', '', 28153),
(134290, 'itIT', '<%s strilla preso dalla paura.>', '', 28153),
(134289, 'itIT', 'Ti accompagnerò attraverso le rovine del tempio.', 'Ti accompagnerò attraverso le rovine del tempio.', 28153),
(134288, 'itIT', '<Nickel abbaia in direzione di un ermellino.>', '', 28153),
(134279, 'itIT', 'Si stanno cibando della mia magia!', '', 28153),
(134278, 'itIT', 'Stanno rubando la nostra magia!', '', 28153),
(134277, 'itIT', 'Urgh... la mia magia sta svanendo...', '', 28153),
(134276, 'itIT', 'Mi sento... prosciugata... Hanno rubato il mio potere!', '', 28153),
(134275, 'itIT', 'Quei maledetti hanno rapito i miei amici!', '', 28153),
(134274, 'itIT', 'Quei farabutti stavano assorbendo la mia magia!', '', 28153),
(134272, 'itIT', 'Non questa volta...', '', 28153),
(134271, 'itIT', 'L\'Alleanza non abbandona nessuno!', '', 28153),
(134270, 'itIT', 'Sta rianimando i loro corpi! Dobbiamo far evacuare i feriti!', '', 28153),
(134266, 'itIT', 'VITTORIA PER I REIETTI!', '', 28153),
(134263, 'itIT', 'La Piaga è troppo pericolosa, mio Re! Non possiamo permetterci di...', '', 28153),
(134252, 'itIT', 'Che la Luce vi benedica tutti. Portatemi i feriti.', '', 28153),
(134233, 'itIT', '', 'Grazie a tutti voi. Da qui posso cavarmela da sola.', 28153),
(134230, 'itIT', 'Dannati... selvaggi!', 'Dannati... selvaggi!', 28153),
(134229, 'itIT', 'Muoio... per il mio Re... per Lordaer... Ahhh!', 'Muoio... per il mio Re... per Lordaer...', 28153),
(134227, 'itIT', 'Non finiscono mai... continuano ad arrivare! Eroi, aiutatemi a respingerli!', 'Non finiscono mai... continuano ad arrivare! Eroi, aiutatemi a respingerli!', 28153),
(134226, 'itIT', '', 'Uhhh... Qualcuno può darmi una mano?', 28153),
(134224, 'itIT', '', 'Arcieri, incoccate le frecce! Avanzate!', 28153),
(134223, 'itIT', 'Eroi! Ci stanno travolgendo! Non posso tenerli in vita ancora a lungo...', '', 28153),
(134211, 'itIT', 'Stupeeenda...', '', 28153),
(134209, 'itIT', 'Aspetta... Hai sentito?', '', 28153),
(134208, 'itIT', 'Timoniere, allontanaci!', 'Timoniere, allontanaci!', 28153),
(134186, 'itIT', 'Tieni ragione! Era ora che accogliessimo $p ufficialmente nella banda. Preparate il rituale!', '', 28153),
(134164, 'itIT', '', 'Jamme, Drekal, continuiamo a cercare.', 28153),
(134163, 'itIT', '', 'Nun vedo nulla di interessante accà.', 28153),
(134162, 'itIT', '', 'Perché ci hai chiamati?', 28153),
(134161, 'itIT', '', 'Sai che è successo all\'$gultimo:ultima; $R che ha gridato \"Al lupo! Al lupo!\"?', 28153),
(134159, 'itIT', '', 'È forse nu gioco per te?', 28153),
(134158, 'itIT', 'Oh no... Il mio barile è pieno di piscio...', '', 28153),
(134157, 'itIT', 'I clienti esigono la merce immediatamente! Partiremo subito!', 'I clienti esigono la merce immediatamente! Partiremo subito!', 28153),
(134156, 'itIT', '', 'La tabella di marcia è cambiata, ragazzi! Tenetevi pronti!', 28153),
(134155, 'itIT', '', 'Perché ci stai facendo perdere tempo?', 28153),
(134151, 'itIT', '', 'Chel bengala nun è nu giocattolo.', 28153),
(134150, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Difendi la Struttura Sud dell\'Alleanza', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Difendi la Struttura Sud dell\'Alleanza', 28153),
(134149, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Difendi la Struttura Nord dell\'Alleanza', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Difendi la Struttura Nord dell\'Alleanza', 28153),
(134125, 'itIT', '', 'Nun importa, nun possiamo aspettarlo. Ho trovato qualcuno che dice di sapere dove si trova Rakera. Jamme, da chesta parte!', 28153),
(134123, 'itIT', '', 'Nun rimaniamo accà più del necessario. Lancia nu bengala, se dovessi trovare qualcosa di interessante.', 28153),
(134116, 'itIT', 'Queste terre sono nostre, cani! Pagherete con le vostre vite!', '', 28153),
(134115, 'itIT', 'Soldati! Riunitevi e serrate i ranghi!', '', 28153),
(134111, 'itIT', 'Non posso dire che questo posto mi mancherà.', '', 28153),
(134109, 'itIT', '', 'Stai facendo nu sacco di richieste per $guno:una; che si trova così vicino alla spada mia.', 28153),
(134101, 'itIT', 'Tu che ci fai qui?', 'Non appartieni a questo posto!', 28153),
(134100, 'itIT', 'Io mi prendo il barile vuoto! Tu puoi avere l\'altro.', '', 28153),
(134099, 'itIT', 'Presto, nasconditi!', '', 28153),
(134096, 'itIT', 'Lo sporco segreto dei Bracescura.', '', 28153),
(134095, 'itIT', 'Cos\'è stato?!?', '', 28153),
(134094, 'itIT', 'Vuoi davvero costruire una Torre d\'Osservazione per 50 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Oro del Fronte di Guerra?', 'Vuoi davvero costruire una Torre d\'Osservazione per 50 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Oro del Fronte di Guerra?', 28153),
(134093, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Costruisci la Torre d\'Osservazione', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Costruisci la Torre d\'Osservazione', 28153),
(134092, 'itIT', 'Sì, sì, Man\'zul. Avremmo dovuto ascoltarti. Nun ti meritavi chesto destino. Avremmo dovuto seguire il piano tuo. Sei intelligente, me lo ricordo. Ora sta\' zitto o ti piglio ancora il naso!', '', 28153),
(134091, 'itIT', 'Man\'zul! Chesta è na locanda per famiglie. Chei giorni sono solo nu ricordo.', '', 28153),
(134090, 'itIT', 'Ah! Mi piace lo stile tuo, $p, ma nun stai al livello mio. Nun gli resta che chella brutta benda per occhi e l\'inconfondibile sorriso suo.', '', 28153),
(134089, 'itIT', 'Volni, smettila di sfidare a duello li ospiti nostri! Li ultimi due che hai acciso nun avevano ancora pagato il conto.', '', 28153),
(134088, 'itIT', 'Parlate più forte! Nun riesco a origliare se continuate a mugugnare così!', '', 28153),
(134087, 'itIT', 'Nun freghi nessuno, Volni. So che adori il cappello che ti ho regalato e nun me ne vado finché nun lo ammetti!', '', 28153),
(134086, 'itIT', 'Aspetta, nun può sentirti con l\'incessante frastuono dei tamburi. Pigliati na pausa, Grenja! $p sta accà per salutarti. Grenja è la barda nostra, ma a volte si dimentica che la gente tiene bisogno di parlare.', '', 28153),
(134085, 'itIT', 'Tutto a posto, $p? Stai spaventando Grenja... Ti sta venendo n\'infarto?', '', 28153),
(134084, 'itIT', 'Tieni nu buon occhio, $p! A Zuldazar, Grenja ci ha salvati da nu sacco di situazioni pericolose. Ha aperto e sfondato nu sacco di porte per noi... e pure gente.', '', 28153),
(134079, 'itIT', 'D\'accordo, è ora di mettersi al lavoro!', '', 28153),
(134078, 'itIT', 'Comunque... hai reso un grande servigio alla nostra città, e di questo ti sono grato. Vedrò cosa posso fare...', '', 28153),
(134077, 'itIT', 'Credo che l\'ultima cosa che vogliano sia la visita di $gun:una; continentale.', '', 28153),
(134076, 'itIT', 'Una maledizione ha colpito questa terra e, quando è comparsa, i Crestabianca non hanno fatto nulla, se non fuggire. Si nascondono nel loro maniero, mentre i cittadini sono preda di un male mai visto prima.', '', 28153),
(134075, 'itIT', 'Vorresti incontrare i codardi Crestabianca? Non penso sia una buona idea.', '', 28153),
(134074, 'itIT', 'Desidero incontrare il capo della Casata dei Crestabianca.', 'Desidero incontrare il capo della Casata dei Crestabianca.', 28153),
(134073, 'itIT', 'Non potrò mai ringraziarti abbastanza per quello che hai fatto per la nostra città, continentale.\n\nMalautunno è in debito con te.', '', 28153),
(134072, 'itIT', 'Come posso aiutarti, $C?', '', 28153),
(134070, 'itIT', '', 'Ah, rieccoti! Ci hai messo più del previsto. Qualche problema?', 28153),
(134069, 'itIT', '', 'Puoi usare il mio razzo per tornare alla base. È un viaggio di sola andata, però, quindi non accenderlo fino al momento giusto.', 28153),
(134068, 'itIT', '', 'Ehi, uhm... È gentile da parte tua, ma ora possiamo cavarcela da soli.', 28153),
(134067, 'itIT', 'Andiamocene da qui.', 'Andiamocene da qui.', 28153),
(134066, 'itIT', 'Tripla G sostiene che questo razzo sia un veicolo sicuro, ma il modo in cui è costruito suggerisce il contrario.', '', 28153),
(134065, 'itIT', 'Dissstruggete chiunque opponga resissstenza! Per la gloria della regina!', '', 28153),
(134064, 'itIT', 'Dissstruggete qualsssiasi cosa venga fuori da quel tempio!', '', 28153),
(134063, 'itIT', 'Mettete al sicuro le reliquie per la regina!', '', 28153),
(134062, 'itIT', 'La regina ha richiesssto quessste reliquie! Mettetele al sicuro, presssto!', '', 28153),
(134061, 'itIT', 'È bello vedere che siete tutti interi, ed è tutto merito di... ehi, ecco l\'eroe del momento!', '', 28153),
(134060, 'itIT', 'I miei... tesori...', '', 28153),
(134059, 'itIT', 'Come osi toccare i tesori miei!', '', 28153),
(134018, 'itIT', '<Prova ad aprire il forziere.>', '<Prova ad aprire il forziere.>', 28153),
(134017, 'itIT', '<La cassa è chiusa, ma con un po\' di sforzi dovresti essere in grado di aprirla.>', '', 28153),
(134016, 'itIT', '', 'Pare che un\'altra nave dell\'Alleanza sia già attraccata. Speriamo abbiano ricevuto un\'accoglienza migliore di Jaina...', 28153),
(134015, 'itIT', 'Mi hai salvato la vita!', '', 28153),
(134014, 'itIT', 'Non lo dimenticherò. Grazie!', '', 28153),
(134013, 'itIT', 'Ti devo una birra!', '', 28153),
(134012, 'itIT', 'Grazie, non credo che avrei resistito ancora a lungo.', '', 28153),
(134011, 'itIT', 'I Naga hanno incatenato gli altri! Ti prego, salva anche loro!', '', 28153),
(134010, 'itIT', 'Sangue e onore! La prossima volta che ci vediamo offro io!', '', 28153),
(134009, 'itIT', '', 'Non ho idea di cosa ti sia successo, ma sembra abbia funzionato! Stai... stai bene?', 28153),
(134007, 'itIT', 'Per l\'Alleanza!', 'Per l\'Alleanza!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(134003, 'itIT', 'Rimanete uniti! PER L\'ALLEANZA!', '', 28153),
(134001, 'itIT', 'Per difendere il nostro futuro, la Regina Banshee deve rispondere dei suoi crimini. Il suo regno oscuro finirà oggi!', '', 28153),
(134000, 'itIT', 'L\'obiettivo della Capoguerra non era conquistare una sola città, ma distruggere la nostra civiltà... e cancellare la speranza per generazioni a venire.', '', 28153),
(133999, 'itIT', 'Insieme scacceremo questo male dalla terra... e innalzeremo i nostri stendardi su Lordaeron ancora una volta.', '', 28153),
(133998, 'itIT', 'Fratelli e sorelle dell\'Alleanza, ascoltatemi!', '', 28153),
(133996, 'itIT', 'Re Anduin sta guidando l\'assalto! Avanzate oltre le riserve e conquistate il campo di battaglia!', '', 28153),
(133990, 'itIT', 'Macchina d\'Assedio pronta all\'azione!', '', 28153),
(133989, 'itIT', 'Una Macchina d\'Assedio per $gil signore:la signora;!', '', 28153),
(133988, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [100] Costruisci Macchina d\'Assedio', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [100] Costruisci Macchina d\'Assedio', 28153),
(133986, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Addestra Guastatori - Attacco a nord', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Addestra Guastatori - Attacco a nord', 28153),
(133985, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Addestra Cavalieri - Attacco a nord', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Addestra Cavalieri - Attacco a nord', 28153),
(133984, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Addestra Archibugieri - Attacco a nord', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Addestra Archibugieri - Attacco a nord', 28153),
(133983, 'itIT', 'Dovrai darmi qualcosa in più perché io possa soddisfare i tuoi ordini.', '', 28153),
(133982, 'itIT', 'Ti do il benvenuto nel mio negozio!', '', 28153),
(133981, 'itIT', '', 'Stalliera Lucia Valfaron, al tuo servizio!', 28153),
(133980, 'itIT', '', 'L\'addestramento è piuttosto costoso, $n.', 28153),
(133979, 'itIT', '', 'Felice di rivederti, $n! Come posso aiutarti?', 28153),
(133974, 'itIT', '', 'Non addestro nessuno per niente!$B$BTrova un altro po\' d\'oro e poi torna a trovarmi!', 28153),
(133971, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Addestra Cavalieri - Attacco a sud', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Addestra Cavalieri - Attacco a sud', 28153),
(133970, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Addestra Guastatori - Attacco a sud', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Addestra Guastatori - Attacco a sud', 28153),
(133969, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Addestra Archibugieri - Attacco a sud ', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Addestra Archibugieri - Attacco a sud ', 28153),
(133968, 'itIT', '', 'Perché ci hai messo tanto? È ora di mettersi a lavorare!', 28153),
(133960, 'itIT', '<Presentati con gentilezza.>', '<Presentati con gentilezza.>', 28153),
(133959, 'itIT', '<Presentati con gentilezza.>', '<Presentati con gentilezza.>', 28153),
(133958, 'itIT', '', 'Sta al sicuro? Ho detto a Kaja di nun venire a cercarmi.', 28153),
(133953, 'itIT', 'Questa città sommersa era un tempio un maestoso tempio dedicato al Loa del Mare, Gral.$b$bQuando arrivarono i Naga, distrussero tutto quanto, uccidendo i suoi seguaci fino all\'ultimo.$B$BSe Gral è ancora vivo, sarà certamente debole.', '', 28153),
(133952, 'itIT', 'Che succede, cumpà? Stiamo sotto attacco?', '', 28153),
(133951, 'itIT', 'Qualcosa è caduto dal cielo! Venite accà!', '', 28153),
(133950, 'itIT', 'L\'odio dei miei fratelli sta annebbiando il loro giudizio. Non è la prima volta che la Signora Ssin e i suoi Naga Cupaspira arrivano a tanto.$b$bLoro sanno che noi sappiamo che loro non sanno, capisci?', '', 28153),
(133947, 'itIT', '', 'Implorerai pietà!', 28153),
(133946, 'itIT', 'Mi serve un passaggio per la Conca Nera.', 'Mi serve un passaggio per la Conca Nera.', 28153),
(133945, 'itIT', 'Morirai per mano mia!', 'Morirai per mano mia!', 28153),
(133944, 'itIT', 'Ti serve nu passaggio?', '', 28153),
(133943, 'itIT', 'Io non faccio prigionieri!', 'Io non faccio prigionieri!', 28153),
(133942, 'itIT', '', 'Pagherai con la vita quest\'intrusione!', 28153),
(133941, 'itIT', '', 'Perlussstrate quesssto accampamento. Portatemi quello a cui stavano lavorando Goji e la sua razza.', 28153),
(133939, 'itIT', 'La regina dei pirati... vendicherà... la mia morte...', '', 28153),
(133938, 'itIT', 'Chi ha fatto salire quest\'idiota sulla mia nave?', '', 28153),
(133936, 'itIT', 'Muori, verme!', 'Muori, verme!', 28153),
(133935, 'itIT', 'Hai del fegato, non è vero?', 'Hai del fegato, non è vero?', 28153),
(133934, 'itIT', 'Qualsiasi cosa tu possegga, ora appartiene a me!', 'Qualsiasi cosa tu possegga, ora appartiene a me!', 28153),
(133933, 'itIT', 'Questa terra appartiene alla Compagnia dei Bracescura!', 'Questa terra appartiene alla Compagnia dei Bracescura!', 28153),
(133929, 'itIT', 'Non ti vogliamo qui!', 'Qui non gradiamo la tua presenza!', 28153),
(133928, 'itIT', 'Non te ne andrai di qui ancora in vita!', 'Non te ne andrai di qui ancora in vita!', 28153),
(133926, 'itIT', 'Non dimenticherò la tua gentilezza...', 'Non dimenticherò la tua gentilezza...', 28153),
(133925, 'itIT', 'Il tormento è finalmente finito...', 'Il tormento è finalmente finito...', 28153),
(133924, 'itIT', 'Hai i miei più sentiti ringraziamenti...', 'Hai i miei più sentiti ringraziamenti...', 28153),
(133923, 'itIT', 'Sapevo che Eraka no Kimbul ci avrebbe mandato aiuto...', 'Sapevo che Eraka no Kimbul ci avrebbe mandato aiuto...', 28153),
(133919, 'itIT', 'Finalmente posso riposare in pace...', 'Finalmente posso riposare in pace...', 28153),
(133918, 'itIT', 'Sapevo che il Loa non ci avrebbe dimenticati...', 'Sapevo che il Loa non ci avrebbe dimenticati...', 28153),
(133917, 'itIT', 'Salta oltre l\'ostacolo designato. La giuria potrebbe non contarlo in caso non saltassi esattamente al centro!', 'Salta oltre l\'ostacolo designato. La giuria potrebbe non contarlo in caso non saltassi esattamente al centro!', 28153),
(133916, 'itIT', 'Saltando troppo presto o troppo tardi, il tuo cavallo potrebbe farti cadere a terra.', 'Saltando troppo presto o troppo tardi, il tuo cavallo potrebbe farti cadere a terra.', 28153),
(133915, 'itIT', 'Non preoccuparti, non mi perderò! E so che comunque verresti a cercarmi.', '', 28153),
(133913, 'itIT', 'Mentre sei al piccolo galoppo, usa Galoppo per andare ancora più veloce!', 'Mentre sei al piccolo galoppo, usa Galoppo per andare ancora più veloce!', 28153),
(133912, 'itIT', 'Usa Piccolo Galoppo per muoverti più velocemente. È la velocità più adatta per saltare!', 'Usa Piccolo Galoppo per muoverti più velocemente. È la velocità più adatta per saltare!', 28153),
(133911, 'itIT', 'Usa Cammina per camminare in avanti e Fermo per fermarti in qualsiasi momento.', 'Usa Cammina per camminare in avanti e Fermo per fermarti in qualsiasi momento.', 28153),
(133904, 'itIT', 'I Branclin sono creature terribili. Chei maledetti lacchè marini farebbero qualsiasi cosa per i padroni Naga loro, a prescindere da quanto sia spregevole.', '', 28153),
(133899, 'itIT', 'Mmm... forse Shoak capirà che questo non è un luogo da esplorare, ma da lasciar stare!', '', 28153),
(133893, 'itIT', 'Umpf... prego, idiota. Non scappare mai più!', '', 28153),
(133883, 'itIT', 'Un Demolitore nemico è comparso presso la Struttura Nord dell\'Orda!', 'Un Demolitore nemico è comparso presso la Struttura Nord dell\'Orda!', 28153),
(133835, 'itIT', 'Sfortunatamente, radunare un esercito è piuttosto costoso, $n. Dobbiamo addestrare i soldati, dar loro da mangiare e creare a mano gli equipaggiamenti.\n\nTorna con un po\' più di oro in tasca.', '', 28153),
(133834, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Addestra Fanti - Attacco a sud', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Addestra Fanti - Attacco a sud', 28153),
(133833, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Addestra Fanti - Attacco a nord', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Addestra Fanti - Attacco a nord', 28153),
(133832, 'itIT', '', 'Quanti corpi... hai mangiato... per ottenere chesto potere?', 28153),
(133831, 'itIT', '', 'I sussurri ci hanno parlato di te... mi piacerà mangiarti!', 28153),
(133830, 'itIT', '', 'Farai meglio... a nun mangiarmi... per pigliare... il potere mio...', 28153),
(133829, 'itIT', '', 'Mangerò le braccia tue prima di gettarti al totem!', 28153),
(133828, 'itIT', '', 'I sussurri dicono... che la carne... ci rende più forti...', 28153),
(133827, 'itIT', '', 'I sussurri mi stanno dicendo che la carne tua ci darà potere!', 28153),
(133820, 'itIT', 'Non hai abbastanza Oro del Fronte di Guerra per costruire un edificio.', 'Non hai abbastanza Oro del Fronte di Guerra per costruire un edificio.', 28153),
(133819, 'itIT', 'Non possiamo iniziare un nuovo edificio mentre siamo già impegnati a costruirne uno.', 'Non possiamo iniziare un nuovo edificio mentre siamo già impegnati a costruirne uno.', 28153),
(133806, 'itIT', 'Se tornerai in questo tempio, ti accoglieremo a braccia aperte.', '', 28153),
(133805, 'itIT', 'Per ricompensare il tuo coraggio, ti benedico donandoti nuovo potere. Possa esserti d\'aiuto nelle tue future battaglie.', '', 28153),
(133804, 'itIT', 'Inoltre, abbiamo salvato gli spiriti dei miei seguaci dalla distruzione e aiutato questo tempio.', '', 28153),
(133803, 'itIT', 'Kuppaka è stato finalmente ucciso, e i manufatti rubati sono stati strappati dalle mani dei Tortaka.', '', 28153),
(133801, 'itIT', 'Non c\'è alcuna speranza per i Tortaka. Kuppaka e la sua tribù devono sparire, così come la fonte del loro potere oscuro.', '', 28153),
(133799, 'itIT', 'Nun avrei mai immaginato che la sete di potere loro li avrebbe condotti a na tale perfidia... cosa possiamo fare?', '', 28153),
(133798, 'itIT', 'I Tortaka non si fermeranno fino a quando non avranno assorbito l\'energia di ogni spirito nel tempio.', '', 28153),
(133794, 'itIT', 'Vuoi davvero costruire una Fucina per 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Oro del Fronte di Guerra?', 'Vuoi davvero costruire una Fucina per 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Oro del Fronte di Guerra?', 28153),
(133793, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Costruisci la Fucina', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Costruisci la Fucina', 28153),
(133790, 'itIT', 'Vuoi davvero costruire un\'Officina per 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Oro del Fronte di Guerra?', 'Vuoi davvero costruire un\'Officina per 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Oro del Fronte di Guerra?', 28153),
(133788, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Costruisci l\'Officina', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Costruisci l\'Officina', 28153),
(133786, 'itIT', 'Vuoi davvero costruire una Scuderia per 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Oro del Fronte di Guerra?', 'Vuoi davvero costruire una Scuderia per 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Oro del Fronte di Guerra?', 28153),
(133785, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Costruisci la Scuderia', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Costruisci la Scuderia', 28153),
(133784, 'itIT', 'Scegli quale edificio costruire in questo punto:', 'Scegli quale edificio costruire in questo punto:', 28153),
(133775, 'itIT', 'Shoak si è cacciato nei guai... di nuovo! Non posso credere che quell\'idiota si sia fatto catturare dai Troll del Sangue.', '', 28153),
(133769, 'itIT', 'SHOAK! Dove sei? SHOAK!', '', 28153),
(133768, 'itIT', 'Conosco un posto dove radunare tutti quanti. Seguimi!', '', 28153),
(133765, 'itIT', 'La tua anima è condannata!', '', 28153),
(133764, 'itIT', 'I tuoi Loa non hanno alcun potere qui!', '', 28153),
(133763, 'itIT', 'La tua anima sarà nostra!', '', 28153),
(133760, 'itIT', 'I Tortaka non tollerano gli stranieri!', '', 28153),
(133759, 'itIT', 'Non puoi stare qui.', '', 28153),
(133758, 'itIT', 'Eraka no Kimbul non ha alcun potere qui!', '', 28153),
(133757, 'itIT', 'Il potere di questo regno è nostro!', '', 28153),
(133756, 'itIT', 'Persino i Loa non possono fermarci!', '', 28153),
(133755, 'itIT', 'Ti mostrerò il mio vero potere!', '', 28153),
(133754, 'itIT', 'Il potere sarà nostro!', '', 28153),
(133752, 'itIT', 'Ci ciberemo della tua anima!', '', 28153),
(133745, 'itIT', '', 'Che cosa sai dei nossstri piani? Parla!', 28153),
(133742, 'itIT', '', 'Parla! Quali segreti nasssconde il tempio?', 28153),
(133741, 'itIT', '', 'Parlerai o affogherai!', 28153),
(133732, 'itIT', 'Tu salva Shoak, io mi metterò al sicuro. Non vorrei che ti toccasse salvare entrambi.', '', 28153),
(133731, 'itIT', '<Dopo un piccolo tragitto in traghetto...>', '<Dopo un piccolo tragitto in traghetto...>', 28153),
(133730, 'itIT', 'Grazie per il passaggio, Tae. Farò rapporto al vecchio.', '', 28153),
(133729, 'itIT', 'Quell\'idiota... perché doveva proprio farsi catturare dai Troll del Sangue?', '', 28153),
(133728, 'itIT', 'I Troll Natha\'vor hanno catturato Shoak.', '', 28153),
(133727, 'itIT', 'No... no... no!', '', 28153),
(133726, 'itIT', 'Oh, no...', '', 28153),
(133725, 'itIT', 'Basta girarmi attorno... trova Shoak!', '', 28153),
(133724, 'itIT', 'Che è stato \'sto rumore? Io proteggerò la principessa, tu va\' a dare n\'occhiata.', '', 28153),
(133723, 'itIT', 'Malautunno è in debito con te. Ti prego, dicci come possiamo ripagarti.', '', 28153),
(133722, 'itIT', 'Devo ringraziarti... Non pensavo mi sarei mai risvegliato da quella maledizione...', '', 28153),
(133721, 'itIT', 'Eh? Cosa... cosa sta succedendo?', '', 28153),
(133720, 'itIT', '', 'Sei di ritorno! E anche i cittadini!', 28153),
(133719, 'itIT', '', 'Non puoi fermare... la maledizione...', 28153),
(133718, 'itIT', '', 'Il nostro è un potere antico! Non sopravvivrai!', 28153),
(133717, 'itIT', '', 'Ti mostrerò il potere della congrega!', 28153),
(133716, 'itIT', '', 'Farai meglio ad andartene, se non vuoi condividere il loro destino.', 28153),
(133715, 'itIT', '', 'Essere insignificante, il villaggio è mio. Così vuole la Madre!', 28153),
(133714, 'itIT', 'È pericolosa... ma non quanto me se scoprirò che non stai escogitando nulla di buono!', 'È pericolosa... ma non quanto me se scoprirò che hai una tresca con lei!', 28153),
(133713, 'itIT', 'Qualunque cosa tu stia facendo, sarà meglio che non riguardi quella pazza nei boschi.', 'Qualunque cosa tu stia facendo, sarà meglio che non riguardi quella pazza nei boschi.', 28153),
(133712, 'itIT', 'Caro marito, non so chi pensi di prendere in giro, ma sappi che ti ho visto mentre sgattaiolavi verso le alture pensando che stessi dormendo.', 'Caro marito, non so chi pensi di prendere in giro, ma sappi che ti ho visto mentre sgattaiolavi verso le alture pensando che stessi dormendo.', 28153),
(133711, 'itIT', 'Cercherò di inviare un\'altra spedizione per la fine della settimana.', 'Cercherò di inviare un\'altra spedizione per la fine della settimana.', 28153),
(133710, 'itIT', 'Per questo motivo sono stati colpiti da una malattia che li ha resi stranamente aggressivi. È stato... difficile radunarli per il trasporto.', 'I miei maiali sono stati colpiti da una malattia che li ha resi stranamente aggressivi. Ha reso molto difficile radunarli per il trasporto.', 28153),
(133709, 'itIT', 'Una vecchia signora mi aveva donato alcune piante per sfamare i maiali, ma temo che fossero contaminate.', 'Una vecchia signora mi aveva donato alcune piante per sfamare i maiali, ma ho paura che fossero contaminate.', 28153),
(133708, 'itIT', 'Caro Caposquadra Staughton, mi scuso per il ritardo nell\'ultima consegna di carne.', 'Caro Caposquadra Staughton, mi scuso per il ritardo nell\'ultima consegna di carne.', 28153),
(133707, 'itIT', 'Siete pregati di segnalare qualsiasi persona o attività sospetta al Sindaco White.', '', 28153),
(133706, 'itIT', 'Inoltre, ci è giunta voce della presenza di creature pericolose sulle alture. Coloro che svolgono un lavoro fuori città, sono pregati di prestare massima cautela.', '', 28153),
(133705, 'itIT', 'Per la vostra protezione, tutti i cittadini sono pregati di ritirarsi nelle loro abitazioni prima del tramonto.', '', 28153),
(133704, 'itIT', 'A causa delle recenti e numerose scomparse, è stato introdotto un nuovo coprifuoco a Malautunno.', '', 28153),
(133703, 'itIT', 'Scommetto la mia ultima torcia che tutto questo ha qualcosa a che fare con quella vecchia strega!', 'Scommetto la mia ultima torcia che tutto questo ha qualcosa a che fare con quella vecchia strega!', 28153),
(133702, 'itIT', 'Se andiamo avanti così, finiremo il cibo per i maiali nel giro di un mese. Da che maledizione è stato colpito questo posto?', 'Se andiamo avanti così, finiremo il cibo per i maiali nel giro di un mese. Da che maledizione è stato colpito questo posto?', 28153),
(133701, 'itIT', 'Non so da dove arrivino queste dannate mosche, ma... ormai è un paio di settimane che continuano a tornare ogni mattina.', 'Non so da dove arrivino queste dannate mosche, ma ormai è da un paio di settimane che continuano a tornare ogni mattina.', 28153),
(133700, 'itIT', '', 'Cerca qualche appunto dei cittadini. Potrebbero aiutarci a capire cosa ha causato tutto questo.', 28153),
(133699, 'itIT', '', 'Vedrò se riesco a trovare qualcosa nei registri della città. Se i cittadini hanno visto qualcosa di sospetto, potrebbero averlo annotato da qualche parte.', 28153),
(133698, 'itIT', '', 'Oh no... anche qui no!', 28153),
(133693, 'itIT', '', 'Nun capisci. Nessun luogo starà al sicuro se Jakra\'zet avrà successo.', 28153),
(133692, 'itIT', '', 'Nun potevo lasciarti morire! Possiamo sfuggire a tutto chesto. Ripartire da capo da n\'altra parte, al sicuro.', 28153),
(133691, 'itIT', '', 'Nun saresti dovuta venire a cercarmi, Kaja.', 28153),
(133690, 'itIT', '', 'Credevo che nun ti avrei più rivista...', 28153),
(133689, 'itIT', 'Be\', meglio distruggere qualche totem che nessuno. Vediamo se riusciamo a trovare quell\'imbranato.', '', 28153),
(133688, 'itIT', 'SHOAK! Tutto questo non è divertente. Sono troppo vicino all\'accampamento dei Troll del Sangue!', '', 28153),
(133686, 'itIT', '', 'Rakera! Stai ancora in vita!', 28153),
(133685, 'itIT', 'Zolani, lama mia, dobbiamo difendere il tempio. Vai!', '', 28153),
(133672, 'itIT', 'Io fa come vuole signora mia!', '', 28153),
(133670, 'itIT', 'Eheh! Ora di mazziare!', '', 28153),
(133669, 'itIT', 'Vieni, piccolo Re. Annientiamo questi eretici!', '', 28153),
(133668, 'itIT', 'Ma giuro a te e a chesto campione dell\'Orda che nun riposerò finché nun terrò la capa di Zul.', '', 28153),
(133667, 'itIT', 'Mi sono rammollito. Molti hanno cercato di avvisarmi... tra cui la stessa figlia mia, ma nun ho ascoltato.', '', 28153),
(133666, 'itIT', 'È ora che tu ti chieda... sei un re o sei una preda?', '', 28153),
(133665, 'itIT', 'C\'è sangue nelle acque, ora.', '', 28153),
(133664, 'itIT', 'Il tuo Concilio sfida la tua autorità. I tuoi amici cercano di ucciderti.', '', 28153),
(133663, 'itIT', 'Rastakhan, i tuoi nemici mettono alla prova i confini.', '', 28153),
(133648, 'itIT', 'Grande Loa, respiri ancora? Lascia che ti liberi da chesto peso.', '', 28153),
(133646, 'itIT', 'Zul aveva previsto il vostro arrivo. Tutto procede come predetto.', '', 28153),
(133645, 'itIT', '', 'Folle! Se ne avessi il tempo, potrei schiacciarti per ciò che hai fatto a Vol\'kaal.', 28153),
(133644, 'itIT', '', 'Schiatta per sempre, Shadra! Come da tradizione, io reclamo il potere tuo!', 28153),
(133643, 'itIT', 'Io proseguo, tu occupati di quei totem. Forse riusciremo a trovare quell\'imbranato una volta che saranno stati distrutti.', '', 28153),
(133638, 'itIT', '', 'Vol\'kaal! Sbarazzati di chisti invasori mentre io mi occupo di Shadra.', 28153),
(133633, 'itIT', '', 'Shadra! Per anni hai guidato la mano mia. Ma da oggi, seguirò nu nuovo padrone!', 28153),
(133632, 'itIT', '', 'È troppo tardi. Il sangue dei Loa è stato versato!', 28153),
(133610, 'itIT', 'Gonk pazzo! Gonk schiaccia Yazma!', '', 28153),
(133606, 'itIT', 'Le tue azioni non sono passate inosservate. Hai la mia benedizione.', '', 28153),
(133605, 'itIT', 'Grazie, $n. Hai ottenuto la mia benedizione.', '', 28153),
(133591, 'itIT', '<C\'è un piccolo messaggio scarabocchiato sul lato del razzo.>$B$BAttenzione: messaggio ufficiale.$b$bSe non ricopri una posizione di comando nell\'Orda, SMETTI DI LEGGERE IMMEDIATAMENTE!$b$bDa: Asdrubal, Squadra Gob.$b$bLa mia squadra è stata inviata per fornirvi un po\' di potenza di fuoco in modo che il nostro piano a Nazmir possa procedere. Abbiamo con noi un cannone che dovrebbe mettere fuori gioco qualsiasi cosa si metta sul nostro cammino.$B$BSiamo sulla \"Grande Libagione\" e stiamo cercando un punto d\'approdo presso le coste orientali. Inviateci qualcuno che ci guidi al punto di sbarco.', '', 28153),
(133582, 'itIT', '<Ringhia> Rimarrò, per ora, se non altro per aiutare gli spiriti dei miei seguaci competenti, morti per la tua stupidità.', '', 28153),
(133581, 'itIT', 'È stato solo nu piccolo errore... ma guardati attorno! Chesto posto nun ti porta ricordi meravigliosi? Rimani e dacci la possibilità di ricostruire il tempio in tuo onore!', '', 28153),
(133580, 'itIT', 'I Tortolliani hanno usanze strane assai, mio signore. Come potevo sapere che rifiutare na proposta di matrimonio fosse considerato n\'atto di guerra?', '', 28153),
(133579, 'itIT', 'Il tuo compito era semplice: fare pace con i Tortaka e custodire il mio tempio fino al mio ritorno. Guarda cos\'hai combinato!', '', 28153),
(133578, 'itIT', 'Ehm, ehm... Sono io, grande Loa, il fedele servitore tuo, Vunanju.', '', 28153),
(133576, 'itIT', '', 'C\'è un vecchio detto qui a Kul Tiras.$B$BQuando qualcosa va storto, i vecchi marinai non se ne curano, dicendo: \"Non si possono cambiare i venti.\"$B$BOdio quel detto.', 28153),
(133575, 'itIT', '', 'Cyrus mi ha cresciuta da quando ero bambina. Mi ha insegnato a combattere, a cavalcare e a navigare.$B$BQuando entrai nella guardia, ero già più abile di alcuni degli istruttori.$B$BInutile dire che non apprezzarono per nulla la cosa.', 28153),
(133574, 'itIT', '', 'Tutto è cambiato da quando Daelin Marefiero è stato sconfitto.$B$BJaina Marefiero aveva le sue ragioni... vero?', 28153),
(133573, 'itIT', '', 'Sono cresciuta sentendo storie sul grande regno di Lordaeron e sulla sua caduta.$B$BIl Flagello si prese mia madre, mio padre e la mia terra prima che fossi abbastanza adulta da comprendere.', 28153),
(133572, 'itIT', 'Sono pronto a fare la mia scelta.', 'Sono pronta a fare la mia scelta.', 28153),
(133571, 'itIT', 'QUESTA BESTIA È FUORI CONTROLLO!', '', 28153),
(133570, 'itIT', '', 'Hai deciso cosa farai?', 28153),
(133569, 'itIT', '', 'Tieni la gratitudine mia, $n.', 28153),
(133568, 'itIT', 'Se ti perdi mentre torniamo indietro, sappi che NON tornerò a cercarti!', '', 28153),
(133567, 'itIT', 'Torniamo dagli altri. Ho così tante storie da raccontare!', '', 28153),
(133566, 'itIT', 'Fa\' attenzione, questi Troll non sono tutti a posto. Perché mai dovrebbero mangiare la loro stessa gente?', '', 28153),
(133565, 'itIT', 'Mmm... ottima! Credo abbia bisogno di qualche aggiunta, però. Magari la prossima volta.', '', 28153),
(133564, 'itIT', 'Sono così affamato... che potrei provare un po\' di carne di Raptor.', '', 28153),
(133563, 'itIT', 'Preparati, mortale! Il Signore delle Bestie è tornato finalmente tra noi!', '', 28153),
(133562, 'itIT', 'Mi ha mandato la Guardia di Spade Kaja.', 'Mi ha mandata la Guardia di Spade Kaja.', 28153),
(133561, 'itIT', '', 'È bello vedere che Julwaba sta ancora in vita.', 28153),
(133560, 'itIT', '', 'Ti devo la vita mia, $n!', 28153),
(133559, 'itIT', '', 'Credo sia meglio indossare la divisa e raggiungere l\'accampamento. Nun prometto di riuscire a impedire che la lama mia colpisca chiunque abbia sfiorato Rakera.', 28153),
(133558, 'itIT', 'I nossstri... tesori...', '', 28153),
(133557, 'itIT', 'Quesssti tesori appartengono agli Scagliavile!', '', 28153),
(133556, 'itIT', 'Siamo solo degli umili salumieri! Perché qualcuno vorrebbe farci del male?', '', 28153),
(133555, 'itIT', '', 'Terrò sotto controllo l\'Umano. Se cerca di scappare, la spada mia lo fermerà.', 28153),
(133554, 'itIT', 'Mi farò strada verso la spiaggia. Troviamoci lì quando avrai recuperato ciò che ti ho chiesto.', '', 28153),
(133553, 'itIT', 'Ora che le offerte stanno pronte, teniamo tutto ciò che ci serve per evocare il Loa.', '', 28153),
(133551, 'itIT', 'Li Zandalari terranno bisogno di tutto l\'aiuto possibile contro chesto male. Fortunatamente, l\'Orda è giunta al salvataggio.', '', 28153),
(133548, 'itIT', '', 'Lo terrò d\'occhio e mi assicurerò che nun vada da nessuna parte.', 28153),
(133547, 'itIT', '', 'Sta per arrivare uno tsunami di sangue. Siamo condannati, $n?', 28153),
(133540, 'itIT', 'Vai, dispensa l\'ira mia. Io devo raggiungere il mio Loa prima che sia troppo tardi.', '', 28153),
(133539, 'itIT', '', 'Ma come... La carne... doveva darmi... potere...', 28153),
(133538, 'itIT', '', 'Nun è possibile... Nun mi mangerai! Nun piglierai il potere mio!', 28153),
(133537, 'itIT', '', 'Uh? Ha detto che avrei ottenuto potere mangiando carne, perché nun muori?', 28153),
(133536, 'itIT', '', 'Tieni n\'odore potente. Diventerò più forte dopo averti mangiato!', 28153),
(133534, 'itIT', '', 'Nun piglierai chesto manufatto!', 28153),
(133532, 'itIT', 'Ahhh sì, che stupido... Mi sono dimenticato le offerte! Nun possiamo evocare nulla a mani vuote!', '', 28153),
(133527, 'itIT', 'Mmm... ci sta qualcosa di sbagliato. L\'idolo sta in posizione sull\'altare, perché il Loa nun torna?', '', 28153),
(133526, 'itIT', '', 'Chesto è il medaglione di Rakera. Viene dato a tutte le Guardie da Guerra in riconoscenza dei servigi al Re. Almeno nun ha ceduto senza combattere.', 28153),
(133516, 'itIT', 'Zul e tutti coloro che lo seguono presto scopriranno che ci sta sempre nu prezzo da pagare per aver sfidato nu Loa.\n\nOgni momento che passa, il debito cresce.', '', 28153),
(133515, 'itIT', '', 'Stiamo accà! Che cosa hai trovato?', 28153),
(133514, 'itIT', '', 'Diamoci na mossa. Sento che stiamo vicini!', 28153),
(133505, 'itIT', '', 'Sono al tuo fianco, mio Re. L\'Orda pagherà per i suoi crimini. Bloccherò l\'entrata, così le nostre forze potranno radunarsi.', 28153),
(133503, 'itIT', 'Almeno due ed erano davvero grandi! Oh, e grazie per avermi curato.', '', 28153),
(133502, 'itIT', 'Ti stavano per mangiare e... quante lance avevi nello stomaco tu?', '', 28153),
(133501, 'itIT', 'Avresti dovuto vedere, Kajosh! Magia oscura dappertutto, Troll che facevano cose assurde, avevo addirittura delle lance nello stomaco!', '', 28153),
(133500, 'itIT', 'Idiota! Hai idea di quanto fossi preoccupato?', '', 28153),
(133499, 'itIT', 'C\'è mancato poco! Mi riprenderò... questo vecchio guscio non è così facile da distruggere.', '', 28153),
(133498, 'itIT', 'Sono sveglio! Era proprio necessario?', '', 28153),
(133497, 'itIT', '', 'Bene, hai visto il bengala mio! Dove sta Drekal?', 28153),
(133496, 'itIT', 'Argh... sto bene, riesco a muovermi. Incontrerò Kajosh... sono sicuro... che sarà molto arrabbiato!', '', 28153),
(133495, 'itIT', '', 'Ah... Jal\'aya... tiene ancora... il manufatto... tuo...', 28153),
(133494, 'itIT', '', 'Credo che mangeremo te... dopo il Tortolliano!', 28153),
(133492, 'itIT', '', 'Il mercato ospita viaggiatori da tutta Azeroth. Ci sono molte locande, ma questa è la mia preferita!', 28153),
(133490, 'itIT', '', 'La visione che ho avuto... Zul e Yazma devono essere fermati, $n!', 28153),
(133489, 'itIT', 'Mi manda Kajosh. Mi occuperò io dei Demoni delle Fauci.', 'Mi manda Kajosh. Mi occuperò io dei Demoni delle Fauci.', 28153),
(133488, 'itIT', 'Argh... Se non sei qui per mangiarmi... vattene, salvati!\n\nI Demoni delle Fauci arriveranno... da un momento all\'altro... a prendere il loro \"cibo\".', '', 28153),
(133487, 'itIT', 'Argh... Attenzione, arrivano!', '', 28153),
(133481, 'itIT', 'Chesta nun è la via di Shadra. Cosa le è successo?', 'Chesta nun è la via di Shadra. Cosa le è successo?', 28153),
(133480, 'itIT', 'Zul e Yazma sono i responsabili di chesto tradimento. Devono essere fermati!', 'Zul e Yazma sono i responsabili di chesto tradimento. Devono essere fermati!', 28153),
(133479, 'itIT', 'Nun è modo di morire, chesto. Grazie per avermi salvato!', 'Nun è modo di morire, chesto. Grazie per avermi salvata!', 28153),
(133478, 'itIT', 'Discuterò coi Loa a chesto proposito!', 'Discuterò coi Loa a chesto proposito!', 28153),
(133477, 'itIT', 'Oggi è un buon giorno per una battaglia, come sempre.', '', 28153),
(133476, 'itIT', 'La magia del sangue è vietata! I traditori devono essere fermati!', '', 28153),
(133475, 'itIT', 'Il mio potere... è tornato! È l\'ora della vendetta!', '', 28153),
(133474, 'itIT', 'Shadra e i servitori suoi hanno davvero esagerato!', '', 28153),
(133473, 'itIT', 'Bene! La mia forza cresce! Ora, attiva l\'ultimo totem.', '', 28153),
(133472, 'itIT', 'Va\' a cercare Shoak, io aspetterò qui.', '', 28153),
(133471, 'itIT', 'È nel tempio dietro di noi. Be\', è stato facile.', '', 28153),
(133470, 'itIT', 'Ah! È...', '', 28153),
(133469, 'itIT', 'Zul pagherà per chesto!', '', 28153),
(133468, 'itIT', 'Ah, la mia forza sta tornando! Presto, attiva un altro totem!', '', 28153),
(133467, 'itIT', 'Che i Loa ti benedicano, cumpà!', '', 28153),
(133466, 'itIT', 'D\'accordo. Shoak potrebbe essere ovunque a Nazmir...', '', 28153),
(133465, 'itIT', 'Sono pronto: lancia la magia, così potremo trovare Shoak.', 'Sono pronta: lancia la magia, così potremo trovare Shoak.', 28153),
(133463, 'itIT', '', 'Credimi, so come ci si sente. Presto ci faremo un bel volo, d\'accordo?', 28153),
(133461, 'itIT', '(Indietro)', '(Indietro)', 28153),
(133460, 'itIT', 'Credo che potrei continuare a mangiare il solito cibo, ma non ho mai provato la carne di Raptor. Perché non cogliere quest\'opportunità?', '', 28153),
(133459, 'itIT', 'Alcuni totem sono stati distrutti. La tua magia funzionerà ora?', 'Alcuni totem sono stati distrutti. La tua magia funzionerà ora?', 28153),
(133455, 'itIT', '', 'Ah, ecco la mia piccola. Sarai agitata, legata qui tutto il giorno.', 28153),
(133450, 'itIT', 'Mo\' schiatti.', 'Mo\' schiatti.', 28153),
(133449, 'itIT', 'Zul ha promesso potere a chiunque gli porti la capa tua.', 'Zul ha promesso potere a chiunque gli porti la capa tua.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(133448, 'itIT', 'Donerò la capa tua a Zul.', 'Donerò la capa tua a Zul.', 28153),
(133447, 'itIT', 'Farò a pezzi la mente tua.', 'Farò a pezzi la mente tua.', 28153),
(133446, 'itIT', 'Ti faremo sanguinare.', 'Ti faremo sanguinare.', 28153),
(133445, 'itIT', 'Dove sta il Re?', 'Dove sta il Re?', 28153),
(133444, 'itIT', 'Metteremo la testa tua in cima a na picca.', 'Metteremo la testa tua in cima a na picca.', 28153),
(133443, 'itIT', 'La mia vita per Zul!', 'La mia vita per Zul!', 28153),
(133438, 'itIT', '<La superficie dell\'altare è leggermente concava, con dei solchi visibili vicino a ogni angolo.$b$bSembra come se ci fosse stato un oggetto grosso e pesante sopra l\'altare.$b$bQualsiasi cosa fosse, sembra essere sparito.>', '', 28153),
(133432, 'itIT', 'Esamina l\'altare.', 'Esamina l\'altare.', 28153),
(133430, 'itIT', '<La stanza sembra essere vuota.$b$bL\'altare di fronte a te è inciso con antichi glifi Zandalari e immagini del Loa Eraka no Kimbul.$b$bSembra ci fosse qualcosa sopra l\'altare... forse una statua?>', '', 28153),
(133428, 'itIT', '', 'L\'Ufficio Contabile è sorvegliato giorno e notte. I tuoi averi saranno al sicuro qui.', 28153),
(133412, 'itIT', 'Li Zanchuli vedono tutto!', 'Li Zanchuli vedono tutto!', 28153),
(133411, 'itIT', 'Nun puoi nasconderti da me!', 'Nun puoi nasconderti da me!', 28153),
(133410, 'itIT', 'Zul verrà a sapere dei segreti tuoi!', 'Zul verrà a sapere dei segreti tuoi!', 28153),
(133409, 'itIT', 'La tua vita è giunta alla fine!', 'La tua vita è giunta alla fine!', 28153),
(133407, 'itIT', 'Nun ti metterai sulla strada mia!', 'Nun ti metterai sulla strada mia!', 28153),
(133406, 'itIT', 'Zandalar mo\' appartiene alli Zanchuli!', 'Zandalar mo\' appartiene alli Zanchuli!', 28153),
(133405, 'itIT', 'Per Zul! Per li Zanchuli!', 'Per Zul! Per li Zanchuli!', 28153),
(133404, 'itIT', 'Noi Zanchuli piglieremo ciò che vogliamo!', 'Noi Zanchuli piglieremo ciò che vogliamo!', 28153),
(133403, 'itIT', 'Il potere tuo sarà mio!', 'Il potere tuo sarà mio!', 28153),
(133402, 'itIT', 'La tua morte mi renderà più forte.', 'La tua morte mi renderà più forte.', 28153),
(133401, 'itIT', 'Più sangue per Zul!', 'Più sangue per Zul!', 28153),
(133392, 'itIT', '', 'Questo traghetto collega tutte le stazioni lungo la costa interna.', 28153),
(133389, 'itIT', '', 'Ti servirà l\'autorizzazione dal Maestro del Porto, ma non sarà un problema.', 28153),
(133387, 'itIT', '', 'Non preoccuparti dell\'evasione. Qui al mercato ti tratteranno da viandante come tutti gli altri. Ora vediamo di farti sistemare!', 28153),
(133380, 'itIT', '', 'Terrò la capa tua da parte per dopo!', 28153),
(133379, 'itIT', '', 'Mi alimenterai per tanto tempo!', 28153),
(133374, 'itIT', '', 'Masticherò le tue ossa!', 28153),
(133372, 'itIT', '', 'Pigliate le lance, sta arrivando del cibo!', 28153),
(133371, 'itIT', '', 'Ahhh, altro cibo da mangiare!', 28153),
(133370, 'itIT', '', 'Le gambe tue saranno n\'ottimo pasto!', 28153),
(133369, 'itIT', '', 'È arrivato del cibo!', 28153),
(133368, 'itIT', '', 'Sembri davvero $gappetitoso:appetitosa;!', 28153),
(133359, 'itIT', 'Non è la prima volta che Shoak si perde. Con tutto quello che stiamo facendo, sarà meglio che si sia cacciato in un guaio bello grosso.', '', 28153),
(133357, 'itIT', 'In piedi! Quest\'Azerite non si estrarrà da sola.', 'In piedi! Quest\'Azerite non si estrarrà da sola.', 28153),
(133356, 'itIT', 'Sono pronto ad accompagnarti al tempio.', 'Sono pronta ad accompagnarti al tempio.', 28153),
(133355, 'itIT', 'Nun mi sarei mai dovuto fidare di quei traditori dei Tortaka! Nun riesco a credere che mi abbiano acciso e intrappolato dentro na giara per cento anni... o sono stati duecento? Nun riesco nemmeno a ricordare!', '', 28153),
(133354, 'itIT', '<Un terribile ruggito agonizzante echeggia su Zeb\'ahari.>', '<Un terribile ruggito agonizzante echeggia su Zeb\'ahari.>', 28153),
(133351, 'itIT', 'Andrò a cercare il Loa. Troviamoci all\'interno del tempio quando hai finito.', '', 28153),
(133350, 'itIT', 'Finalmente libero... Ti ringrazio per avermi liberato da chella giara maledetta! Ci si stava stretti, anche per nu spirito!', '', 28153),
(133349, 'itIT', '', 'Queste mura non reggeranno a lungo. Non dobbiamo indugiare.', 28153),
(133348, 'itIT', '', 'Ottimo lavoro, cumpà! Parla con me quando vuoi, teniamo na guerra da combattere.', 28153),
(133346, 'itIT', '', 'Dio del Sangue... pigliami! Chesta... nun è... la fine...', 28153),
(133345, 'itIT', '', 'Il Dio del Sangue terrà ciò che vuole, prima o poi. Nun ci fermerai!', 28153),
(133344, 'itIT', '', 'La principessa vorrà ricevere i rapporti il prima possibile. Nun farla aspettare.', 28153),
(133343, 'itIT', 'Cammina.', '', 28153),
(133342, 'itIT', 'Nun è ancora l\'ora di schiattare. Teniamo ancora molto da fare.', '', 28153),
(133341, 'itIT', 'Alzati. Il lavoro nostro nun sta ancora finito.', '', 28153),
(133340, 'itIT', 'Rialzati! Teniamo bisogno di te.', '', 28153),
(133339, 'itIT', 'Rialzati!', '', 28153),
(133338, 'itIT', 'Rialzati! Il re tuo tiene bisogno di te.', '', 28153),
(133337, 'itIT', 'Sono pronto a combattere i Troll del Sangue!', 'Sono pronta a combattere i Troll del Sangue!', 28153),
(133336, 'itIT', 'I Troll del Sangue stanno radunando le forze per un altro attacco contro me e la mia prole.$b$bQuesta volta, sarò io ad ucciderli!$b$bSei $gpronto:pronta;?', '', 28153),
(133325, 'itIT', 'Gli attaccanti dell\'Orda si stanno dirigendo verso la Caserma!', 'Gli attaccanti dell\'Orda si stanno dirigendo verso la Caserma!', 28153),
(133305, 'itIT', '', 'Ti sentirai a casa in men che non si dica! Ora andiamo da Cyrus!', 28153),
(133304, 'itIT', '', 'È bellissima, non è vero? Cyrus me l\'ha affidata quando era solo un cucciolo.', 28153),
(133303, 'itIT', 'Mi unirò alla tua crociata contro gli invasori Troll del Sangue, ma prima ho bisogno di recuperare le forze. Mi aiuterai?', '', 28153),
(133302, 'itIT', 'Zentimo mi ha servito bene. Il suo spirito continuerà a vivere tra quelli dei miei figli.', '', 28153),
(133300, 'itIT', '<Randall Redmond sputa sulla sabbia.>', '', 28153),
(133298, 'itIT', 'Aiuto! Toglietemeli di dosso!', '', 28153),
(133297, 'itIT', '', 'Le ferite sue erano troppo gravi... mi dispiace.', 28153),
(133295, 'itIT', 'Vunanju? <Ringhia> Avrei dovuto immaginarlo...', '', 28153),
(133294, 'itIT', 'Chi osa evocarmi in questo tempio decrepito?', '', 28153),
(133274, 'itIT', 'Andrò in avanscoperta per preparare il rituale. Raggiungimi quando puoi.', '', 28153),
(133265, 'itIT', 'Preparati ad ammirare la gloria di Eraka no Kimbul, il Loa delle Tigri, Signore delle Bestie, Re dei Felini e Flagello delle Prede!', '', 28153),
(133264, 'itIT', 'Hai trovato l\'idolo! Ora che sta in posizione, possiamo evocare il Loa...', '', 28153),
(133263, 'itIT', '', 'Porterò chesto tizio dal Loa suo e acciderò chiunque passi per accà.', 28153),
(133261, 'itIT', 'La Caserma è stata distrutta! Ricostruiscila!', 'La Caserma è stata distrutta! Ricostruiscila!', 28153),
(133260, 'itIT', 'La Fucina è stata distrutta! Ricostruiscila!', 'La Fucina è stata distrutta! Ricostruiscila!', 28153),
(133259, 'itIT', 'La Scuderia è stata distrutta! Ricostruiscila!', 'La Scuderia è stata distrutta! Ricostruiscila!', 28153),
(133258, 'itIT', 'L\'Officina è stata distrutta! Ricostruiscila!', 'L\'Officina è stata distrutta! Ricostruiscila!', 28153),
(133254, 'itIT', 'Non ho nemmeno un\'arma!', '', 28153),
(133253, 'itIT', 'Non voglio morire!', '', 28153),
(133252, 'itIT', 'Non posso lavorare in queste condizioni!', '', 28153),
(133251, 'itIT', 'Sta funzionando! Preparati!', '', 28153),
(133250, 'itIT', 'Proveremo una magia di fossilizzazione inversa. Sta\' indietro!', '', 28153),
(133249, 'itIT', 'Sono pronta.', 'Sono pronta.', 28153),
(133248, 'itIT', 'Se funzionerà, aspettati una dura reazione da parte di Xibala.\n\nSei $gpronto:pronta; a fare tutto ciò che serve per sottometterlo?', '', 28153),
(133247, 'itIT', '', 'Di qua! Chesto è ferito!', 28153),
(133240, 'itIT', '', 'Offro il rifugio di cui dispongo in queste terre ostili.', 28153),
(133239, 'itIT', 'Questa era la mia dimora prima che gli Zandalari decidessero di costruire una casa attorno a me.', '', 28153),
(133224, 'itIT', 'L\'idolo dev\'essere riportato al Tempio di Kimbul. Tieni tra le mani la chiave per il ritorno del Loa!', '', 28153),
(133223, 'itIT', 'Lo spirito mio sta debole e nun tengo molto tempo. Ascolta attentamente le parole mie...', '', 28153),
(133214, 'itIT', 'Meglio andarcene da accà. Più avanti ci sta nu santuario che si chiama Zo\'bal. Incontriamoci là.', '', 28153),
(133213, 'itIT', 'Il Comandante dell\'Orda è stato sconfitto. Vittoria!', 'Il Comandante dell\'Orda è stato sconfitto. Vittoria!', 28153),
(133212, 'itIT', 'Dannatamente fenomenale! Pare che quella feccia degli Orchi si sia lasciata alle spalle un po\' di deliziosi esplosivi. Mi chiedo cosa accadrebbe se li piazzassimo vicino a quelle loro orribili strutture...', '', 28153),
(133207, 'itIT', 'Chest\'area è stata abbandonata da tempo alli spiriti del passato, e per nu motivo buono assai.\n\nL\'Orda è benvenuta se vuole scoprire di più... e se tiene il coraggio.', '', 28153),
(133204, 'itIT', 'Persino nella morte, li spiriti della gente mia sono rimasti leali al grande Loa, Eraka no Kimbul. I legami della fede nostri sono indissolubili e più forti della morte stessa.', '', 28153),
(133201, 'itIT', 'Abbiamo bisogno di quella Miniera, ma ci sono quei dannati Orchi sul nostro cammino. Andiamo laggiù ed eliminiamoli, così potremo usare quei Braccianti per costruire una Caserma.', '', 28153),
(133200, 'itIT', 'È la fine per quel brutto muso. Ora sbarazzati di quello stendardo e mettiamoci al lavoro.', '', 28153),
(133199, 'itIT', 'Bene ragazzi, dobbiamo costruire e far funzionare una base qui, se vogliamo far fuori quel Comandante Orco e distruggere la sua base una volta per tutte.', '', 28153),
(133198, 'itIT', '', 'Nun cambia niente! Presto... schiatterete... tutti quanti...', 28153),
(133197, 'itIT', 'Tu sei $gil primo:la prima; mortale ad aver messo piede nel mio tempio da molti anni. È bello scoprire di avere ancora dei seguaci tra i vivi.', '', 28153),
(133158, 'itIT', '', 'Ce l\'abbiamo fatta. Pensa a cosa succederebbe se quel costrutto distruggesse le mura di Zuldazar e li facesse entrare tutti quanti. Ci farebbero comodo altri Loa al fianco nostro.', 28153),
(133157, 'itIT', '', 'Guardate! Tutti chelli diretti a Zuldazar... state accuort\'! Tenete giù la capa!', 28153),
(133156, 'itIT', '', 'L\'isola sta a sud rispetto accà. Ti aspetterò lì.', 28153),
(133155, 'itIT', '', 'Da chesta parte. La nave sta pronta quando vuoi partire. Speriamo nun ci stiano mostri marini, eh?', 28153),
(133154, 'itIT', 'CI SIAMO!', '', 28153),
(133153, 'itIT', 'BASTA CHE NON LA FAI ESPLODERE!', '', 28153),
(133152, 'itIT', 'CONTINUA A COLPIRLA!', '', 28153),
(133151, 'itIT', 'Cosa posso fare per te, $gamico:amica;?', '', 28153),
(133150, 'itIT', 'Sai che ti dico? Prendi qualunque cosa tu trovi là dentro. È il mio modo di dirti grazie.', '', 28153),
(133149, 'itIT', 'Ahhh... AHHH...', '', 28153),
(133143, 'itIT', 'La presenza tua è dissacrante! Guardati da Xibala!', '', 28153),
(133141, 'itIT', 'I Granatieri Nani possono ora essere reclutati all\'Officina.', 'I Granatieri Nani possono ora essere reclutati all\'Officina.', 28153),
(133140, 'itIT', 'I Fucilieri possono ora essere reclutati alla Fucina.', 'I Fucilieri possono ora essere reclutati alla Fucina.', 28153),
(133139, 'itIT', 'I Cavalieri possono ora essere reclutati alla Scuderia.', 'I Cavalieri possono ora essere reclutati alla Scuderia.', 28153),
(133138, 'itIT', 'I Coscritti possono ora essere reclutati alla Caserma.', 'I Coscritti possono ora essere reclutati alla Caserma.', 28153),
(133136, 'itIT', '', 'La prima presenza che ho percepito stava vicino a nu fiume. Ci sta nu sentiero che conduce proprio a nord-est.', 28153),
(133133, 'itIT', '', 'Mmm... chell\'offerta sembra fresca. Pare che Bwonsamdi tenga nu fedele accà nella palude.', 28153),
(133131, 'itIT', 'Troppi Troll del Sangue. Nun combatto più.', '', 28153),
(133126, 'itIT', 'L\'Orda ha perso un edificio. La Fucina è ora pronta per essere costruita.', 'L\'Orda ha perso un edificio. La Fucina è ora pronta per essere costruita.', 28153),
(133125, 'itIT', 'L\'Orda ha perso un edificio. L\'Officina è ora pronta per essere costruita.', 'L\'Orda ha perso un edificio. L\'Officina è ora pronta per essere costruita.', 28153),
(133124, 'itIT', 'L\'Orda ha perso un edificio. La Scuderia è ora pronta per essere costruita.', 'L\'Orda ha perso un edificio. La Scuderia è ora pronta per essere costruita.', 28153),
(133123, 'itIT', '', 'Là, segui il fantasma e vediamo dov\'è andato chesto seguace di Bwonsamdi.', 28153),
(133122, 'itIT', '', 'Na Troll del Sangue. Sembra sia stata sacrificata. Ah, l\'assassino s\'è scordato nu pugnale! Na magia piccirilla e...', 28153),
(133114, 'itIT', 'FAMMI USCIRE DI QUI!', '', 28153),
(133113, 'itIT', 'La bomba è stata rilasciata!', 'La bomba è stata rilasciata!', 28153),
(133112, 'itIT', 'La bomba è stata presa!', 'La bomba è stata presa!', 28153),
(133111, 'itIT', 'La bomba sta per esplodere! Scappa!', 'La bomba sta per esplodere! Scappa!', 28153),
(133108, 'itIT', 'Fante [25 Oro del Fronte di Guerra] |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t', 'Fante [25 Oro del Fronte di Guerra] |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t', 28153),
(133104, 'itIT', 'Iniziamo.', 'Iniziamo.', 28153),
(133103, 'itIT', 'REUSEME', 'REUSEME', 28153),
(133102, 'itIT', 'Il nostro lavoro procede lentamente a causa dell\'interferenza dell\'Alleanza!', 'Il nostro lavoro procede lentamente a causa dell\'interferenza dell\'Alleanza!', 28153),
(133101, 'itIT', 'Potrei fare molto di più se non dovessi costantemente guardarmi le spalle dai sabotatori dell\'Alleanza...', 'Potrei fare molto di più se non dovessi costantemente guardarmi le spalle dai sabotatori dell\'Alleanza...', 28153),
(133100, 'itIT', 'L\'Alleanza non ha alcun diritto su questa terra: Zuldazar è territorio dell\'Orda!', 'L\'Alleanza non ha alcun diritto su questa terra: Zuldazar è territorio dell\'Orda!', 28153),
(133099, 'itIT', 'Non potremo fare progressi fin quando quei maledetti Nani non verranno cacciati dalle nostre terre!', '', 28153),
(133085, 'itIT', '', 'L\'Alleanza... avrà la meglio...', 28153),
(133084, 'itIT', '', 'Questo è un sito di scavo ufficiale della Lega degli Esploratori. L\'ingresso è vietato!', 28153),
(133069, 'itIT', 'Per l\'Alleanza!', 'Per l\'Alleanza!', 28153),
(133066, 'itIT', 'Vattene, ficcanaso!', 'Vattene, ficcanaso!', 28153),
(133065, 'itIT', 'Questi manufatti saranno nostri!', 'Questi manufatti saranno nostri!', 28153),
(133064, 'itIT', 'Morte al Reliquiario!', 'Morte al Reliquiario!', 28153),
(133055, 'itIT', '', 'Salve! Hai mai acceso un razzo sulla tua schiena mentre eri $gbendato:bendata;? Io sì!', 28153),
(133054, 'itIT', 'L\'Alleanza deve essere eliminata. Zuldazar appartiene all\'Orda!', '', 28153),
(133053, 'itIT', 'Davvero incredibile. Che ritrovamento!', '', 28153),
(133048, 'itIT', '', 'Passo un sacco di tempo qui a infastidire i viaggiatori chiedendo loro di raccontarmi le loro storie. Soprattutto quelli dei Regni Orientali!', 28153),
(133047, 'itIT', '', 'Eccoci qui, il Porto di Boralus. A parte il Forte dei Marefiero, è la zona più difesa di tutta la città ed è l\'unico luogo che gran parte degli ospiti riesce a vedere.', 28153),
(133045, 'itIT', '', 'Ritieniti fortunato se ti pagherà qualcosa. Ora rema!', 28153),
(133044, 'itIT', 'Un emissario dell\'Alleanza?!? Cyrus non me l\'aveva detto... gli avrei fatto pagare il doppio!', '', 28153),
(133043, 'itIT', '', 'Sei qui con Jaina Marefiero! Sei l\'emissario dell\'Alleanza!', 28153),
(133042, 'itIT', '', 'Aspetta... io ti conosco...', 28153),
(133041, 'itIT', 'Ah, e naturalmente ho salvato l\'obiettivo. Ti presento Taelia.', '', 28153),
(133040, 'itIT', '', 'Che succede là dentro? Pare che tu abbia scatenato una rivolta!', 28153),
(133039, 'itIT', 'Non ho idea di cosa tu stia parlando... ma credo che abbiamo finalmente qualcosa di GROSSO su Bracescura.', '', 28153),
(133038, 'itIT', 'Eccola lì! Saltiamo su.', '', 28153),
(133037, 'itIT', 'Raggiungiamo i livelli inferiori e troviamo una via d\'uscita.', '', 28153),
(133036, 'itIT', 'Ah, ora va meglio. Mi sentivo nudo senza di loro! Muoviamoci.', '', 28153),
(133013, 'itIT', '', 'Che ti serva un nuovo tappeto o cappotto, abbiamo esattamente quello che ti serve!', 28153),
(133012, 'itIT', '', 'Pellicce calde, pellicce pratiche, pellicce comode!', 28153),
(133011, 'itIT', '', 'Pellicce di qualità da tutta Kul Tiras!', 28153),
(133009, 'itIT', '', 'Le invenzioni più affidabili di tutta Tiragarde, parola mia!', 28153),
(133008, 'itIT', '', 'Non fidarti delle invenzioni degli altri Gnomi! I miei concorrenti sono degli imbroglioni!', 28153),
(133007, 'itIT', '', 'Non troverai attrezzi di pari qualità da nessun\'altra parte!', 28153),
(133001, 'itIT', 'Accidenti! Sta... sta crescendo?', 'Accidenti! Sta... sta crescendo?', 28153),
(132999, 'itIT', 'Innalzamento', 'Innalzamento', 28153),
(132994, 'itIT', 'Maghi, torniamo all\'accampamento. Abbiamo molto da studiare!', '', 28153),
(132993, 'itIT', 'Dannazione! Le chiavi sono rovinate. Un gran bel botto, devo dire!', '', 28153),
(132992, 'itIT', 'Prendi la tua roba e facciamo visita al direttore. Ci servono le sue chiavi.', '', 28153),
(132991, 'itIT', 'Direi che di qui non si passa. Proviamo dall\'altra parte.', '', 28153),
(132990, 'itIT', 'Caserma disponibile', 'Caserma disponibile', 28153),
(132989, 'itIT', 'Ribellatevi, ragazzi! Scatenate l\'inferno!', '', 28153),
(132988, 'itIT', '<Le porte delle celle si aprono. I detenuti si riversano fuori verso il corridoio.>', '<Le porte delle celle si aprono. I detenuti si riversano fuori verso il corridoio.>', 28153),
(132987, 'itIT', 'Gli attaccanti dell\'Orda si stanno dirigendo verso l\'Officina!', 'Gli attaccanti dell\'Orda si stanno dirigendo verso l\'Officina!', 28153),
(132986, 'itIT', 'Addestramento Coscritti', 'Addestramento Coscritti', 28153),
(132985, 'itIT', 'La Caserma è stata conquistata ed è in ricostruzione.', 'La Caserma è stata conquistata ed è in ricostruzione.', 28153),
(132981, 'itIT', 'Gli attaccanti dell\'Orda si stanno dirigendo verso la Scuderia!', 'Gli attaccanti dell\'Orda si stanno dirigendo verso la Scuderia!', 28153),
(132980, 'itIT', 'Gli attaccanti dell\'Orda si stanno dirigendo verso la Fucina!', 'Gli attaccanti dell\'Orda si stanno dirigendo verso la Fucina!', 28153),
(132969, 'itIT', '', 'Mamma, i miei amici stanno giocando senza di me! Ti prego, posso andare?', 28153),
(132968, 'itIT', '', 'Che noia! Posso andare a giocare?', 28153),
(132967, 'itIT', '', 'Abbiamo finito con quei vagabondi?', 28153),
(132966, 'itIT', 'Chesto dovrebbe permettergli quantomeno di rialzarsi.', '', 28153),
(132957, 'itIT', '', 'Questo vecchio arnese?$B$B<Scoppia in una risata amichevole.>$B$BGuardati intorno. Dove pensi che l\'abbia trovato?', 28153),
(132955, 'itIT', 'Che scudo interessante. Dove l\'hai trovato?', 'Che scudo interessante. Dove l\'hai trovato?', 28153),
(132954, 'itIT', '', 'Sarò anche una ragazzina, ma picchio il mio martello più forte della maggior parte di quegli zozzoni dell\'Orda che vedrai là fuori.', 28153),
(132945, 'itIT', 'Che ci fai qui fuori?', 'Che ci fai qui fuori?', 28153),
(132944, 'itIT', 'Ho quello che ci serve per occuparci di quel cannone. Lasciateglielo!', '', 28153),
(132943, 'itIT', 'Gigante in arrivo! Ehi, è quello che ha distrutto la nostra nave! È tempo di vendetta!', '', 28153),
(132941, 'itIT', 'Ascolta, $gamico:amica;... Io, ehm... mi sono dimenticato quello che stavo per dire, ma meglio se tieni le mani a posto qui.$B$BNon vorrei che mi sanguinassi sull\'equipaggiamento.', '', 28153),
(132940, 'itIT', 'Essere alti significa che ci vuole più tempo perché le emozioni raggiungano il loro massimo potenziale.$B$BPorta pazienza.', '', 28153),
(132939, 'itIT', 'Dobbiamo verificare la precisione dell\'arma prima di fare qualunque altra cosa, quindi perché non farlo eliminando un po\' di quei Naga?', '', 28153),
(132938, 'itIT', 'Attenzione! Stanno sparando con dei cannoni sulla nostra posizione! Eliminateli con delle munizioni a grappolo!', '', 28153),
(132935, 'itIT', 'Sotto di noi! State accuort\'!', '', 28153),
(132932, 'itIT', '', 'Allora sta così... Andiamo a ovest ed evitiamo scontri nun necessari.', 28153),
(132931, 'itIT', 'Pare che la presenza loro sia cresciuta assai.', '', 28153),
(132928, 'itIT', 'Sei qui per rifugiarti o commerciare?', 'Sei qui per rifugiarti o commerciare?', 28153),
(132926, 'itIT', 'Siamo pronti a partire. Salta su.', '', 28153),
(132924, 'itIT', 'Presto! Tira quella leva!', '', 28153),
(132923, 'itIT', 'Andiamo. Il nostro trasporto ci sta aspettando alla spiaggia.', '', 28153),
(132922, 'itIT', '', 'Fuori dai piedi! C\'è il mio nome scritto su quell\'oro!', 28153),
(132920, 'itIT', 'Cinquantamila monete d\'oro al primo che arriva al punto di sbarco!', '', 28153),
(132918, 'itIT', 'Ma ho appena costruito delle mine per mettere al sicuro questo posto.', '', 28153),
(132917, 'itIT', 'Ecco, ho ufficialmente finito con questo posto.', '', 28153),
(132916, 'itIT', 'Uh... puzza come la branda di un filibustiere.', '', 28153),
(132915, 'itIT', 'Forza, squadra, muoviamoci!', '', 28153),
(132912, 'itIT', 'I rischi rendono tutto più eccitante! Bah! Dovresti giocare un po\' più d\'azzardo.', '', 28153),
(132911, 'itIT', '', 'Andiamo, l\'80% basta. Perché rischiare di far saltare l\'accordo?', 28153),
(132910, 'itIT', 'Solo l\'80%? Avresti potuto chiedere MOLTO di più! Dov\'è finita la tua avidità?', '', 28153),
(132909, 'itIT', 'Bentornata alla Locanda Zannadoro, cumpà. Accà starai sempre tra amici.\n\nRilassati, riposati e fatti na bevuta!', '', 28153),
(132908, 'itIT', 'Bentornato alla Locanda Zannadoro, cumpà. Accà starai sempre tra amici.\n\nRilassati, riposati e fatti na bevuta!', '', 28153),
(132907, 'itIT', 'Che stai facendo? Quello è il mio equipaggiamento!', 'Che stai facendo? Quello è il mio equipaggiamento!', 28153),
(132906, 'itIT', 'Aiuto! C\'è un sabotatore!', 'Aiuto! C\'è un sabotatore!', 28153),
(132905, 'itIT', 'Quell\'equipaggiamento è delicato!', 'Quell\'equipaggiamento è delicato!', 28153),
(132904, 'itIT', 'Ehi! Allontanati dalla mia attrezzatura!', 'Ehi! Allontanati dalla mia attrezzatura!', 28153),
(132897, 'itIT', 'Fammi uscire da chesta gabbia! Sono innocente, lo giuro!', 'Fammi uscire da chesta gabbia! Sono innocente, lo giuro!', 28153),
(132893, 'itIT', 'Concordo, Grenja. $p sarebbe n\'ottima scelta, se Zulsan nun dovesse tornare.', '', 28153),
(132891, 'itIT', 'Di chi è stata l\'idea di navigare vicino a questa maledetta grotta?', 'Di chi è stata l\'idea di navigare vicino a questa maledetta grotta?', 28153),
(132890, 'itIT', 'Il canto si è finalmente fermato!', 'Il canto si è finalmente fermato!', 28153),
(132889, 'itIT', 'Quella è... birra?', 'Quella è... birra?', 28153),
(132880, 'itIT', 'Eheh, chesta parte è sempre la mia preferita.', '', 28153),
(132879, 'itIT', 'Ho bollito il sangue e i pungiglioni che hai recuperato e li ho versati nel calice cerimoniale della Zannadoro... Sì, è n\'ananas. Nun mangiarlo. Ne teniamo solo uno.', '', 28153),
(132877, 'itIT', 'Mi hai salvato la pelle, grazie!', '', 28153),
(132876, 'itIT', 'Grazie! Ci vediamo al luogo dell\'incontro!', '', 28153),
(132849, 'itIT', 'Mi accorgo ora di essere quasi finito in una terribile trappola... grazie!', 'Mi accorgo ora di essere quasi finita in una terribile trappola... grazie!', 28153),
(132848, 'itIT', 'Non so cosa mi sia successo...', 'Non so cosa mi sia successo...', 28153),
(132847, 'itIT', 'Ti prego, salva anche gli altri... Io tornerò subito da Kimbul.', 'Ti prego, salva anche gli altri... Io tornerò subito da Kimbul.', 28153),
(132846, 'itIT', 'Per poco non morivo... Hai i miei ringraziamenti!', 'Per poco non morivo... Hai i miei ringraziamenti!', 28153),
(132845, 'itIT', 'Quest\'inganno mi è quasi costato l\'anima...', 'Quest\'inganno mi è quasi costato l\'anima...', 28153),
(132844, 'itIT', 'Ora capisco che si trattava solo di un incantamento. Andrò da Kimbul...', 'Ora capisco che si trattava solo di un incantamento. Andrò da Kimbul...', 28153),
(132843, 'itIT', 'Sono stato sedotto dalla luce divorante. Grazie per avermi salvato...', 'Sono stata sedotta dalla luce divorante. Grazie per avermi salvata...', 28153),
(132841, 'itIT', '', 'Nun sopravvivrò ancora a lungo senza cibo o acqua. Dopo aver viaggiato in tondo per quasi nu giorno, ho deciso che l\'unica possibilità mia era di seguire il consiglio del folle e dirigermi a sud, cercando chesto rifugio.', 28153),
(132840, 'itIT', '', 'Degli assassini, mandati da Jakra\'zet, hanno attaccato l\'accampamento nostro nel bel mezzo della notte. Disarmati e intontiti dal sonno, nun siamo riusciti a difenderci. Ho affrontato i traditori, ma era troppo tardi... I sopravvissuti si sono dispersi, costretti a vagare pe\' chesta terra inclemente... da soli.', 28153),
(132839, 'itIT', '', 'Il sole è tramontato oltre le dune, dando nu poco di sollievo dal calore che ha portato molti al delirio. Uno tra noi ha iniziato a blaterare a proposito di nu tempio a sud, che offre riparo agli esiliati. Dubito che supererà la notte.', 28153),
(132838, 'itIT', '', 'Mentre scrivo, mi trovo rinchiusa insieme ad altri esiliati, in viaggio verso le sabbie dove finiremo i pochi giorni che ci rimangono. L\'aria, così pesante e calda, mi dice che stiamo vicini.', 28153),
(132830, 'itIT', '', 'Sei $garrivato:arrivata; tardi... Il Loa... Tutti quanti diventeranno cibo... per il Dio del Sangue.', 28153),
(132827, 'itIT', 'Questi Naga la pagheranno!', '', 28153),
(132826, 'itIT', 'Non so come ringraziarti!', '', 28153),
(132825, 'itIT', 'Te ne devo una!', '', 28153),
(132824, 'itIT', 'Libertà!', '', 28153),
(132823, 'itIT', 'Ti devo la mia vita. Questi uomini serpente la pagheranno per ciò che hanno fatto alla nostra casa...', 'Ti devo la mia vita. Questi uomini serpente la pagheranno per ciò che hanno fatto alla nostra casa...', 28153),
(132821, 'itIT', '<Prendi la lettera.>', '<Prendi la lettera.>', 28153),
(132752, 'itIT', 'Nisha, sia lode alle sabbie, sei viva!', '', 28153),
(132737, 'itIT', '', 'È davvero la persona più gentile che abbia mai conosciuto.', 28153),
(132736, 'itIT', '<%s si muove verso di te come per fermarti, poi torna indietro, per poi continuare a fissare un punto in lontananza.>', '', 28153),
(132735, 'itIT', 'Eheh, il primo sorso di Sangue di Scorpide Rituale è sempre difficile da mandar giù. La prossima volta sarà più facile.', '', 28153),
(132734, 'itIT', 'Zuldazar ci ha traditi, esiliati come stranieri. Ma noi nun lo faremmo mai. Li Zannadoro sono fedeli.', '', 28153),
(132733, 'itIT', 'Ah, il sangue è delizioso... Bevilo e vedrai ciò che vedo io, $p.', '', 28153),
(132714, 'itIT', 'Armi professionali per Cacciatori di ogni livello!', '', 28153),
(132713, 'itIT', 'Sei in partenza per una caccia? Non c\'è posto migliore di questo per acquistare i giusti rifornimenti!', '', 28153),
(132712, 'itIT', 'Armi, munizioni ed esplosivi per Cacciatori novelli o veterani!', '', 28153),
(132711, 'itIT', '<Il Cornofurente Giovane sbadiglia assonnato.>', '', 28153),
(132710, 'itIT', 'Oh, quello? Era solo un premio che do alle mie guardie personali. Ne ho molti altri. Vuoi fare un\'offerta?', '', 28153),
(132696, 'itIT', 'È sicuro uscire, mo\'?', '', 28153),
(132692, 'itIT', 'Ah! Sì, lo so che $p nun può vederti. Probabilmente crede che io sia pazzo. Ah!', '', 28153),
(132691, 'itIT', 'Nun essere triste. $p nun può nemmeno vederti. Probabilmente crede che io sia pazzo. Ah!', '', 28153),
(132690, 'itIT', '$p ti ha salvato, Zulsan! Sono così felice!', '', 28153),
(132688, 'itIT', 'Ehilà, $n! Il Principe del Commercio pretende che iniziamo a ottenere un profitto. Fammi sapere se senti di qualche buon affare, va bene?', '', 28153),
(132684, 'itIT', '', 'Arriva la sposa, arriva la sposa!', 28153),
(132683, 'itIT', 'Accà!', 'Accà!', 28153),
(132682, 'itIT', 'Carica! Ce la puoi fare!', 'Carica! Ce la puoi fare!', 28153),
(132681, 'itIT', '<Sussurra che pensi che la sua benda per occhi sia stupida.>', '<Sussurra che pensi che la sua benda per occhi sia stupida.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(132680, 'itIT', 'Posso avere la tua roba?', 'Posso avere la tua roba?', 28153),
(132679, 'itIT', 'La tua benda per occhi è davvero spaventosa.', 'La tua benda per occhi è davvero spaventosa.', 28153),
(132678, 'itIT', '<La benda per occhi di Man\'zul vibra di magia.>', '', 28153),
(132677, 'itIT', '<Cerca di battere Grenja in una sfida di sguardi.>', '<Cerca di battere Grenja in una sfida di sguardi.>', 28153),
(132676, 'itIT', 'Scommetto che saresti un ottimo fermaporte.', 'Scommetto che saresti un ottimo fermaporte.', 28153),
(132675, 'itIT', 'Salve!', 'Salve!', 28153),
(132674, 'itIT', '<Grenja sembra sorprendentemente felice per essere un teschio.>', '', 28153),
(132673, 'itIT', 'State tutti zitti! Teniamo n\'ospite.', '', 28153),
(132672, 'itIT', '<Presentati con gentilezza.>', '<Presentati con gentilezza.>', 28153),
(132671, 'itIT', '<Borbotta qualcosa a proposito di quanto sia folle tutto questo.>', '<Borbotta qualcosa a proposito di quanto sia folle tutto questo.>', 28153),
(132670, 'itIT', 'Mi piace il tuo cappello.', 'Mi piace il tuo cappello.', 28153),
(132669, 'itIT', 'Ehm... salve?', 'Ehm... salve?', 28153),
(132668, 'itIT', 'Accidenti, cos\'è stato? Mi sento benissimo.', '', 28153),
(132667, 'itIT', '', '<Volni sembra sia bloccata in uno stato di terrore perpetuo.>', 28153),
(132663, 'itIT', '', 'Adorerete i colori e i sapori che le nostre spezie doneranno a ogni piatto!', 28153),
(132662, 'itIT', '', 'Spezie di qualità da tutta Azeroth!', 28153),
(132661, 'itIT', '', 'Dite addio ai pasti poco saporiti! Date un\'occhiata alle nostre spezie!', 28153),
(132657, 'itIT', 'Ahhh! Cerca di distrarlo con nu giocattolo!', 'Ahhh! Cerca di distrarlo con nu giocattolo!', 28153),
(132656, 'itIT', 'Il miglior pesce sul mercato!', 'Il miglior pesce sul mercato!', 28153),
(132655, 'itIT', 'Non c\'è niente di meglio di un pesce appena pescato per cena!', 'Non c\'è niente di meglio di un pesce appena pescato per cena!', 28153),
(132654, 'itIT', 'Pesce fresco direttamente dalle navi Tuskarr!', 'Pesce fresco direttamente dalle navi Tuskarr!', 28153),
(132653, 'itIT', 'Signore! Sembra che forze dell\'Orda si stiano ammassando negli accampamenti a sud-ovest. Pare si stiano preparando a muoversi.', '', 28153),
(132651, 'itIT', 'Non perdeteli di vista! A qualsiasi segno di movimento, sapete cosa fare.', '', 28153),
(132650, 'itIT', 'Selcialegno! Aggiornamenti?', '', 28153),
(132648, 'itIT', 'Salvataggio', 'Salvataggio', 28153),
(132646, 'itIT', 'Fuoco!', 'Fuoco!', 28153),
(132645, 'itIT', 'Devi essere nu membro di chest\'Orda di cui si sente tanto parlare. E tieni nu cucciolo di cornofurente? Il Signore delle Bestie vorrà vederlo. Va\'.', 'Devi essere un membro di chest\'Orda di cui si sente tanto parlare. Tieni nu Cucciolo di Cornofurente? La Signora delle Bestie vorrà vederlo. Va\'.', 28153),
(132636, 'itIT', '', 'Davvero interessante...', 28153),
(132635, 'itIT', '', 'Vediamo cos\'abbiamo qui.', 28153),
(132634, 'itIT', '', 'Fai attenzione là fuori.', 28153),
(132629, 'itIT', 'Usa Scatto per correre più veloce!', 'Usa Scatto per correre più veloce!', 28153),
(132628, 'itIT', '', 'Accideremo i cacciatori e rivendicheremo i totem perduti tuoi.', 28153),
(132626, 'itIT', '', 'Quando li Zandalari ti vedranno combattere con loro, terrai di nuovo dei seguaci.', 28153),
(132624, 'itIT', '', 'Sei nu Loa potente assai! Con nu potere simile al fianco nostro, annienteremo il nemico!', 28153),
(132622, 'itIT', '', 'Grande Krag\'wa! Stiamo accà per chiedere aiuto contro i Troll del Sangue!', 28153),
(132620, 'itIT', 'Preso! Ora tocca a te!', '', 28153),
(132619, 'itIT', 'Tana! Tocca a te!', '', 28153),
(132613, 'itIT', 'Ti benedirò con una piccola parte del mio potere. Usalo per aiutare Zentimo a unirsi ai miei figli.', '', 28153),
(132611, 'itIT', 'Debug Testing', 'Debug Testing', 28153),
(132609, 'itIT', 'L\'attacco è avvenuto così improvvisamente che... non siamo riusciti a fermarli.', 'L\'attacco è avvenuto così improvvisamente che... non siamo riusciti a fermarli.', 28153),
(132608, 'itIT', 'Il Gigante... ci ha distrutto...', 'Il Gigante... ci ha distrutto...', 28153),
(132607, 'itIT', 'L\'arma... distrutta...', 'L\'arma... distrutta...', 28153),
(132606, 'itIT', 'N... Naga... dappertutto!', 'N... Naga... dappertutto!', 28153),
(132605, 'itIT', 'Gra... grazie!', 'Gra... grazie!', 28153),
(132604, 'itIT', 'Quindi siamo giunti a questo.', 'Quindi siamo giunti a questo.', 28153),
(132603, 'itIT', '$gCodardo:Codarda;!', '$gCodardo:Codarda;!', 28153),
(132602, 'itIT', 'Non mi avrete mai vivo!', 'Non mi avrete mai viva!', 28153),
(132601, 'itIT', 'Miserabile senza onore!', 'Miserabile senza onore!', 28153),
(132600, 'itIT', 'Razza di miserabile!', 'Razza di miserabile!', 28153),
(132599, 'itIT', 'Il coraggio nun ti manca se stai qui durante la Grande Caccia. Sarà na giornata interessante assai, nun credi?', '', 28153),
(132581, 'itIT', 'Basta con questi insetti! Andiamo dal loro capo!', '', 28153),
(132580, 'itIT', 'Non tollererò ulteriormente questi attacchi! Schiacciateli! Io sono Krag\'wa, non sono il banchetto di nessuno!', '', 28153),
(132579, 'itIT', 'Ben fatto. Hai dimostrato di avere forza e coraggio. Torna al tempio e accetta la tua ricompensa.', '', 28153),
(132573, 'itIT', 'Nell\'ultimo assalto dei ranishu erano state divorate quattro carovane. Grazie per aver impedito che accadesse di nuovo.', '', 28153),
(132572, 'itIT', 'Un branco di brutosauri ha messo piede a Vol\'dun, facendo impazzire quei voraci ranishu! Eliminane un po\', prima che diventino una piaga incontenibile.', '', 28153),
(132571, 'itIT', 'Dimostra il tuo valore tornando con le offerte e il Loa ti concederà un\'udienza.', '', 28153),
(132566, 'itIT', 'Hai servito questo tempio e dimostrato il tuo valore. In cambio, ti donerò la mia benedizione, se la desideri.', '', 28153),
(132565, 'itIT', 'Devi trovare la tana dell\'Invocatore delle Zanne e uccidere la creatura il prima possibile. La salvezza del tempio dipende da questo.', '', 28153),
(132564, 'itIT', 'Se i Sethrak non verranno cacciati da questo canyon, la sicurezza di questo tempio sarà in pericolo.', '', 28153),
(132563, 'itIT', 'Accetto le offerte tue, $gstraniero:straniera;. Avvicinati, chesti vecchi occhi nun sono più chelli di na volta.', '', 28153),
(132562, 'itIT', 'Pare che teniamo n\'ospite, Jal\'nanji. Occupati tu di $gdargli:darle; il benvenuto.', '', 28153),
(132560, 'itIT', 'La vera caccia ti attende.', '', 28153),
(132550, 'itIT', 'Il grande sauro del tuono ci ha permesso di rifugiarci nel tempio. Potrai stare accà fintanto che il Loa lo permetterà.', '', 28153),
(132549, 'itIT', 'NOOO! Sta scappando con il nostro M.IM.MO.! Passeremo il resto della vita senza stipendio se non lo riportiamo indietro!', '', 28153),
(132547, 'itIT', 'Hai recuperato quello che ci serviva?', '', 28153),
(132545, 'itIT', '<Noti centinaia di micce che fuoriescono da piccole fiale contenenti una polvere luccicante.>', '', 28153),
(132544, 'itIT', '<Le sciabole all\'interno della cassa presentano delle lame dall\'aspetto familiare.>', '', 28153),
(132541, 'itIT', '<Migliaia di pallini per moschetto sono incartati con cura all\'interno della cassa.>', '', 28153),
(132537, 'itIT', '<L\'inconfondibile odore di polvere da sparo emana dalla cassa.>', '', 28153),
(132536, 'itIT', '<Scartando l\'involucro, noti il luccichio del metallo all\'interno della cassa.>', '', 28153),
(132534, 'itIT', 'Non avrei mai pensato di dover rischiare di nuovo la vita per Cyrus.$B$BOvviamente non avrei mai pensato nemmeno che saremmo sopravvissuti entrambi così a lungo!', '', 28153),
(132533, 'itIT', 'Raggiungimi lì quando avrai qualche informazione sulle spedizioni.', '', 28153),
(132532, 'itIT', 'Manda quei giovani al lato occidentale della fonderia. Io aspetterò lì per assicurarmi che nessuno cerchi di rapirli.', '', 28153),
(132531, 'itIT', 'Cagney ha ripescato questa ragazza dall\'acqua con il suo traghetto. Ha detto che stava cercando di fuggire dalla fonderia.$B$BNon mi sorprende neanche un po\' che la Compagnia dei Bracescura stia facendo lavorare dei bambini. Ero poco più grande di lei quando le bande di Boralus mi costrinsero a borseggiare e distrarre le guardie per conto loro.$B$BIn questo mondo, più sei debole, più la gente se ne approfitta.', '', 28153),
(132495, 'itIT', '', 'G\'huun... chesto nun è... ciò che avevi promesso...', 28153),
(132494, 'itIT', '', 'Folle! L\'anima tua appartiene a G\'huun.', 28153),
(132493, 'itIT', '', 'No! Nun sono pronta... per... chesto...', 28153),
(132492, 'itIT', '', 'Osi interrompere il cordoglio mio? Te ne pentirai!', 28153),
(132453, 'itIT', '', 'Credevo che sarei morta soffocata là dentro! Grazie!', 28153),
(132450, 'itIT', '', '<Tripla G annaspa.>', 28153),
(132444, 'itIT', 'Accà!', 'Accà!', 28153),
(132416, 'itIT', 'Stammi vicino!', '', 28153),
(132415, 'itIT', 'Dobbiamo raggiungere il Giardino dei Loa prima che sia troppo tardi. Fa\' in fretta!', '', 28153),
(132408, 'itIT', '', 'Grazie per aver risolto quel pasticcio. Zem\'lan è più pericoloso di quanto affermino le leggende.', 28153),
(132406, 'itIT', 'Chesta situazione era scomoda assai. Grazie, $n!', '', 28153),
(132404, 'itIT', '', 'Quando affonderò gli artigli miei su Yazma e sul culto dei ragni suo... Oh, scorrerà del sangue.', 28153),
(132403, 'itIT', 'Grazie, $CT. Per l\'Orda!', 'Grazie, $CT. Per l\'Orda!', 28153),
(132398, 'itIT', 'Nun tengo tempo da perdere in chiacchiere.', '', 28153),
(132396, 'itIT', 'Perché fai cheste domande? Stai cercando di farti gettare tra le sabbie?', '', 28153),
(132376, 'itIT', '', 'Te la farò pagare per quest...', 28153),
(132374, 'itIT', 'Aaagh!', 'Aaagh!', 28153),
(132365, 'itIT', 'Il Loa è tornato nel tempio.', 'Il Loa è tornato nel tempio.', 28153),
(132364, 'itIT', 'Non è sicuro per te qui, dovresti andartene prima che sia troppo tardi.', 'Non è sicuro per te qui, dovresti andartene prima che sia troppo tardi.', 28153),
(132343, 'itIT', 'C\'è un luogo nascosto, dall\'altra parte di queste rovine, che sarebbe perfetto come base delle nostre operazioni. Dì alla squadra che ci troveremo là.', '', 28153),
(132342, 'itIT', '<Krag\'wa fissa per qualche istante le lucciole, affascinato dalla loro luminosità.>', '', 28153),
(132340, 'itIT', '<Krag\'wa divora la carne in un solo boccone!>', '', 28153),
(132325, 'itIT', 'Osi insultarmi?!? Vattene!', '', 28153),
(132324, 'itIT', '<Krag\'wa si sta infuriando! Hai agito troppo lentamente!>', '', 28153),
(132323, 'itIT', 'Accetto le tue offerte. Ora mostrami ciò che sai fare.', '', 28153),
(132322, 'itIT', '<Krag\'wa si guarda attorno, irritato. Sembra si stia annoiando. Distrailo!>', '', 28153),
(132321, 'itIT', '<Krag\'wa si lecca le labbra e ti guarda affamato. Dagli da mangiare!>', '', 28153),
(132320, 'itIT', 'Hai portato dei doni! Questo mi rallegra! Potrai vivere qualche attimo in più.', '', 28153),
(132310, 'itIT', 'Attivazione Maschera Spiritica', 'Attivazione Maschera Spiritica', 28153),
(132308, 'itIT', 'Potente Krag\'wa, ti offro un dono di carne e mosche.', 'Potente Krag\'wa, ti offro un dono di carne e mosche.', 28153),
(132307, 'itIT', 'Sei $gun amico:un\'amica; delle rane... Non ti mangerò.', '', 28153),
(132306, 'itIT', 'Sacrilegio! Sei qui per rubare la mia prole? Ti mangerò!', '', 28153),
(132297, 'itIT', 'Sembra ci sia un sentiero che conduce da questa parte...', '', 28153),
(132296, 'itIT', 'Che c\'è, Notley?', '', 28153),
(132294, 'itIT', 'Prendi queste pietre che ho raccolto, le mie vecchie ossa non possono più trasportare tesori come un tempo. Ohohoh!', '', 28153),
(132293, 'itIT', 'Oh, salve. Credete di poter dare una mano a un anziano? Mi sa che mi sono cacciato in un bel pasticcio.', '', 28153),
(132289, 'itIT', 'Sto lavorando a un piano per risolvere tutto, non temere.', '', 28153),
(132288, 'itIT', 'Barbagruggo ringrazia! Prendete sbrilli, portano sfortuna.', '', 28153),
(132287, 'itIT', '', 'Ehi, voi! Mi farebbe comodo il vostro aiuto!', 28153),
(132279, 'itIT', '', 'Dobbiamo rafforzare la posizione nostra. Siamo tutto ciò che rimane tra la terra mia e la distruzione totale.', 28153),
(132275, 'itIT', '', 'Come osi profanare il nostro luogo di riposo!', 28153),
(132274, 'itIT', '', 'Vattene! Lasciaci al nostro dolore!', 28153),
(132267, 'itIT', 'Che imbarazzo... Almeno hai trovato il mio archibugio.', '', 28153),
(132266, 'itIT', 'Sarai na piacevole variazione dai Troll del Sangue che caccio di solito.', '', 28153),
(132265, 'itIT', 'Nun muoverti, devo staccarti la capa come si deve.', '', 28153),
(132264, 'itIT', 'Saluta Bwonsamdi da parte mia.', '', 28153),
(132263, 'itIT', 'Vieni avanti, nun essere timido.', '', 28153),
(132262, 'itIT', 'Attenzione a dove metti i piedi...', '', 28153),
(132261, 'itIT', 'Raccoglierò la capa tua.', '', 28153),
(132260, 'itIT', 'Vieni a giocare, $gpiccolo:piccola; $R!', '', 28153),
(132254, 'itIT', '', 'Imboscata!', 28153),
(132243, 'itIT', '', 'Ho deciso di trasferirmi a Dimor Est. Spero solo non abbia subito lo stesso destino di Acqualunga.', 28153),
(132240, 'itIT', '', 'Percepisco rabbia e dolore in chesto posto. Qualunque cosa sia successa accà, nun è stata piacevole.', 28153),
(132237, 'itIT', '<Vedi i segni dei denti di una trappola che ha attanagliato la gamba del cacciatore caduto.>$B$B<Ci sono buchi di dardi che gli hanno trapassato l\'armatura.>$B$B<Gli occhi sono spalancati e scioccati. Non ha nemmeno capito cosa lo ha ucciso.>', '', 28153),
(132236, 'itIT', '', 'Comportati bene con il nostro ospite! Non vogliamo che se ne vada affamato... o che se ne vada e basta!', 28153),
(132221, 'itIT', 'INSERT SHOOTING GALLERY HERE', '', 28153),
(132205, 'itIT', 'I carcerieri di Jaina sono arrivati solo un paio di giorni fa per occuparsi del suo esilio. Se ci sbrighiamo, dovremmo riuscire a raggiungerla prima che sia troppo tardi.', '', 28153),
(132201, 'itIT', '', 'Pagherai per la morte delle sorelle mie!', 28153),
(132190, 'itIT', 'Il Signore delle Bestie dice che tu sei uno di noi mo\', per cui puoi restare accà. Nun pensare però che nun ti terrò d\'occhio.', '', 28153),
(132189, 'itIT', '', 'Cavalcare nu pterrordattilo è emozionante assai! Fai però attenzione a tenerti forte!', 28153),
(132188, 'itIT', 'Molto bene, cominceremo da là.', '', 28153),
(132187, 'itIT', 'È probabile che abbia seguito la strada in cerca di un rifugio.', '', 28153),
(132186, 'itIT', 'Troveremo un modo, Mace, non appena troveremo Jaina. Idee, Yorrick?', '', 28153),
(132185, 'itIT', '', 'Ho la sensazione che non apriranno quel cancello al nostro ritorno...', 28153),
(132180, 'itIT', '', 'Da chesta parte, seguiamo la strada!', 28153),
(132179, 'itIT', 'Cosa vuoi chiedere al vecchio Bwonsamdi?', '', 28153),
(132178, 'itIT', 'Nun male. Nun male davvero! Tieni talento come $gmietitore:mietitrice; d\'anime!', '', 28153),
(132177, 'itIT', 'Come osi profanare il corpo mio!', '', 28153),
(132169, 'itIT', 'L\'Alleanza è pronta a offrire una lauta ricompensa a chi farà tornare Jaina.', 'L\'Alleanza è pronta a offrire una lauta ricompensa a chi farà tornare Jaina.', 28153),
(132168, 'itIT', 'Intendi a Drustvar?!? Stai scherzando, vero?\n\nIl mio posto è qui alle mura a rifornire questi soldati! Solo un folle metterebbe piede oltre quei cancelli di sua spontanea volontà!', '', 28153),
(132152, 'itIT', '', 'Devo ammetterlo, sei $gun:una; gran combattente. La mia lama è al servizio del Maresciallo.', 28153),
(132149, 'itIT', '', 'È tardi per tornare indietro ora, Yorrick. Tanaleccio non perdonerà mai una guardia che attacca qualcuno dei suoi, nemmeno per obbedire a degli ordini.', 28153),
(132148, 'itIT', 'Jaina?!? È lei l\'obiettivo di questa spedizione? Ma questo è tradimento!', '', 28153),
(132146, 'itIT', 'È un rischio che devo correre, Capitano. Soldati, a me.', '', 28153),
(132145, 'itIT', 'Puoi passare, Reade, ma la regina verrà informata! Non mettere mai più piede a Boralus!', '', 28153),
(132144, 'itIT', 'Basta, mi arrendo!', '', 28153),
(132143, 'itIT', 'Non abbiamo tempo per questo! Soldati, combattete al mio fianco!', '', 28153),
(132142, 'itIT', 'Per ordine della regina, nessuno può passare da questo cancello. Nemmeno tu.', '', 28153),
(132141, 'itIT', 'Capitano Tanaleccio, ho arruolato questi uomini per una missione speciale. Ti ordino di farti di parte e lasciarci passare!', '', 28153),
(132140, 'itIT', 'Altolà! Dove pensi di andare esattamente con i miei uomini, Maresciallo?', '', 28153),
(132139, 'itIT', 'Dovrebbe andare! Di\' al Maresciallo Reade che il Quartiermastro Notley è a rapporto!', '', 28153),
(132138, 'itIT', 'Prenderò in prestito alcune cose che ci servono...', '', 28153),
(132137, 'itIT', 'Hai detto ricompensa? Be\', questo cambia le cose...', '', 28153),
(132136, 'itIT', 'Cessate il fuoco, sembra che li abbiamo messi in fuga.', '', 28153),
(132135, 'itIT', 'Prendi una balestra e seguimi, continentale.', '', 28153),
(132134, 'itIT', 'Se ha bisogno di me, seguirò i suoi ordini, ma sarebbe un peccato andarsene senza recare il minimo danno a queste bestie.', '', 28153),
(132133, 'itIT', 'Sospettavo che il Maresciallo potesse essere qui per quella ragione, ma se devi fare quel nome, almeno tieni la voce bassa...', '', 28153),
(132132, 'itIT', '', 'Sai che ti dico? Dimostrami il tuo valore e mi unirò alla piccola avventura di Reade. En garde!', 28153),
(132131, 'itIT', '', 'Sono pronta ad affrontare i pericoli di Boscomorto, ma non ho alcuna intenzione di badare a qualcuno che non sa stare al nostro passo.', 28153),
(132130, 'itIT', '', '$gBenvenuto:Benvenuta; alla Grande Caccia, $R. In chesto luogo, tutto ciò che si muove è na preda.$b$bAccà onoriamo solo coloro che portano i trofei più rari.', 28153),
(132129, 'itIT', 'Statt\' accuort\'! Chella strega tiene nu vudù potente assai!', '', 28153),
(132128, 'itIT', '<La tavoletta è antica e consunta. È in netto contrasto con le offerte fresche piazzate vicino a essa.>', '<La tavoletta è antica e consunta. È in netto contrasto con le offerte fresche piazzate vicino a essa.>', 28153),
(132117, 'itIT', '', 'Le ossa tue serviranno la padrona!', 28153),
(132114, 'itIT', 'Quest\'Orda è solo feccia miserabile.', '', 28153),
(132113, 'itIT', 'Questa guerra avrà mai fine?', '', 28153),
(132112, 'itIT', 'Ritorno alle ombre.', '', 28153),
(132111, 'itIT', 'Fai attenzione, $gsoldato:soldatessa;.', '', 28153),
(132107, 'itIT', 'Sta a nord. Segui il fiume e attraversalo quando l\'acqua sta più bassa.', '', 28153),
(132106, 'itIT', '', 'Andrò con loro. Assicurati che sia davvero sicuro.', 28153),
(132105, 'itIT', 'Mi scuso per il disordine, ma non riceviamo visitatori vivi molto spesso.', '', 28153),
(132096, 'itIT', 'Mmm... Crederò alla storia tua, per ora. Parliamo.', '', 28153),
(132095, 'itIT', '', 'Lo giuro!', 28153),
(132094, 'itIT', 'Aspetta, Jhasan! Nun tiene tutti i torti. Forse chesta guaglioncella sta dicendo la verità.', '', 28153),
(132093, 'itIT', 'State cercando di tenerci occupati fino all\'arrivo delli amici vostri?', '', 28153),
(132092, 'itIT', '', 'Aspetta, sono amici... $n, sta\' accuort\'!', 28153),
(132081, 'itIT', 'Mi spiace che Zulsan nun stia qui. Gli sarebbero piaciuti i capelli tuoi.', '', 28153),
(132068, 'itIT', 'Sì, ho sentito cos\'ha detto $p, Man\'zul. Pure io credo che la benda per occhi tua sia più brutta del fondoschiena di nu saurolisco.', '', 28153),
(132067, 'itIT', 'Ah! Volni, sii gentile. Forse si sono vestiti al buio... nun tieni tutti i torti, però!', '', 28153),
(132066, 'itIT', 'Grenja è la barda nostra. Suonerà qualsiasi canzone tu voglia... fintanto che preveda tamburi. Adora pestare ogni cosa. Speriamo nun la faccia tua, ahahah! Nun lo farà, nun temere... o forse sì.', '', 28153),
(132057, 'itIT', 'No, Grenja, nun ti comprerò nu tamburo dorato! Smettila di chiedere o ti porto via anche quel nuovo cappello tuo!', '', 28153),
(132055, 'itIT', 'Dobbiamo rimanere vigili qui. Chesta palude è la fonte di nu potente vudù.', '', 28153),
(132054, 'itIT', 'Mmm, odori di fresco. Il puzzo della palude non ti è penetrato nella carne. Meglio cominciare a parlare.', '', 28153),
(132053, 'itIT', '', 'Gli oscuri chiamavano Annie per nome, ma lei non si è mai allontanata dal bene. È come se fosse finita in prigione, con l\'anima avvolta da oscure catene!', 28153),
(132049, 'itIT', '', 'Sam si occupava della fattoria. Era gentile con gli animali. Ora però se ne è andato via. Chi penserà ai suoi maiali?', 28153),
(132048, 'itIT', '', 'Il signor Hayes era un uomo assai buono, da sempre gentile e dall\'animo retto. Aveva un gran cuore ed era incline al perdono, forse è per questo che non l\'ha più nel petto!', 28153),
(132047, 'itIT', '', 'La signora Mary voleva un vantaggio. È andata a cercare un potere cattivo. Ha portato la morte nel nostro villaggio, mutando il bosco in un luogo nocivo.', 28153),
(132046, 'itIT', 'Da chesta parte. Oltrepassa la porta e sali con l\'ascensore per raggiungere il re.', '', 28153),
(132045, 'itIT', '', 'Ti avverto, viandante, ti controlliamo a vista. Sarai al cospetto di uno dei più anziani Troll ancora in vita. E sta in vita perché io e il cumpà mio lo difendiamo. Quindi nun farti venire in mente strane idee.', 28153),
(132044, 'itIT', 'Vendetta per Zul\'jin!', '', 28153),
(132043, 'itIT', 'Spero che abbiano del cibo sulla barca!', 'Spero abbiano del cibo sulla barca!', 28153),
(132042, 'itIT', 'Ora troviamo un bel fuoco caldo!', 'Ora troviamo un bel fuoco caldo!', 28153),
(132041, 'itIT', 'Ti prego, aiuta anche i grandi!', 'Ti prego, aiuta anche i grandi!', 28153),
(132040, 'itIT', 'Grazie!', 'Grazie!', 28153),
(132039, 'itIT', 'Me ne tornerò a scuola...', 'Me ne tornerò a scuola...', 28153),
(132038, 'itIT', 'Non mi prenderanno! Sono troppo veloce!', 'Non mi prenderanno! Sono troppo veloce!', 28153),
(132037, 'itIT', 'Io me la svigno!', 'Io me la svigno!', 28153),
(132020, 'itIT', '', 'Calmati, Drekal. Cheste creature ci hanno fornito nu riparo. Dobbiamo guadagnare la fiducia loro.', 28153),
(132019, 'itIT', 'Oh, che anima possente! Ahah! Il vecchio Bwonsamdi si sente pieno di energie... Ahahah, sì! I poteri miei crescono!', '', 28153),
(132017, 'itIT', '', 'Stai rinunciando a un grande potere...', 28153),
(132016, 'itIT', 'Ben fatto. Questo li tratterrà per un po\'.', '', 28153),
(132015, 'itIT', 'I Sethrak stanno espandendo il loro impero, conquistando le pianure dove un tempo viveva la nostra gente. Dobbiamo fermarli!', '', 28153),
(132010, 'itIT', 'Raggiungi la costa. C\'è una barca pronta a condurti in salvo.', 'Raggiungi la costa. C\'è una barca pronta a condurti in salvo.', 28153),
(132009, 'itIT', '', 'Stolto... non hai idea di quello in cui ti stai immischiando...', 28153),
(132004, 'itIT', 'Ho visto uomini cattivi. Urlavano a tutti... anche a quelli grandi!', 'Ho visto uomini cattivi. Urlavano a tutti... anche a quelli grandi!', 28153),
(132003, 'itIT', 'Sei $gcattivo:cattiva;?$B$BNon sembri $gcattivo:cattiva;.', 'Sei $gcattivo:cattiva;?$B$BNon sembri $gcattivo:cattiva;.', 28153),
(132002, 'itIT', 'Il mio naso è congelato, e anche le orecchie. E anche i piedi...', 'Il mio naso è congelato, e anche le orecchie. E anche i piedi...', 28153),
(131999, 'itIT', 'Dicevano che ci avrebbero dato da mangiare, ma da quando sono qui non ho ancora visto una crosta di pane!', 'Dicevano che ci avrebbero dato da mangiare, ma da quando sono qui non ho ancora visto una crosta di pane!', 28153),
(131998, 'itIT', '', 'Drekal e io ti raggiungeremo lì dopo che avremo dato n\'occhiata.', 28153),
(131997, 'itIT', '', 'Dovresti raggiungere il tempio davanti a noi. Se chesto Loa possiede il potere di cui parlano, potrebbe aiutarci a trovare Rakera.', 28153),
(131996, 'itIT', '<Tossisce>$B$BVoglio andare a casa.', '<Tossisce>$B$BVoglio andare a casa.', 28153),
(131995, 'itIT', 'Ti prego, non gridare!', 'Ti prego, non gridare!', 28153),
(131994, 'itIT', 'Sono stanco.', 'Sono stanca.', 28153),
(131939, 'itIT', '', 'Ti do il benvenuto, $gsoldato:soldatessa;, sei $gpronto:pronta; a combattere per l\'Alleanza?', 28153),
(131931, 'itIT', 'Credi di passartela male? Non hai la minima idea di quanto sia difficile tenere traccia di quali e quante guerre sono attualmente in corso.', '', 28153),
(131897, 'itIT', '', 'Continuiamo a volare e speriamo di nun scoprirlo.', 28153),
(131894, 'itIT', '', 'Dovremo attraversare la palude. Fintanto che resteremo in volo e fuori portata, nun dovrebbero esserci troppi problemi.', 28153),
(131893, 'itIT', '', 'Kaja, sotto di noi! Cosa sono?', 28153),
(131888, 'itIT', 'Ma\'ma chiede, ma\'ma avrà.', '', 28153),
(131887, 'itIT', 'La vita mia per la Madre Anziana!', '', 28153),
(131886, 'itIT', 'Carne per le Madri della Guerra!', '', 28153),
(131885, 'itIT', 'Altro sangue!', '', 28153),
(131884, 'itIT', 'Ma\'ma ha detto di accidere... no... catturare. Sì! Catturare.', '', 28153),
(131883, 'itIT', 'I tendini! Tagliateglieli. Ma\'ma ha detto di tagliarli.', '', 28153),
(131882, 'itIT', 'Muori! Muori! Muori!', '', 28153),
(131881, 'itIT', '<Cercando nelle sue tasche, trovi una lettera.>\n\nMia cara Mary,\n\nti prego, torna a casa. Russell continua a chiedere dove sei. Cosa posso dirgli? Che sua madre è fuggita nelle foreste per fare chissà cosa? Ci manchi, mia adorata. La nostra casa non è più la stessa. Ti prego, torna da noi.\n\nCon amore,\nJonathan.', '', 28153),
(131880, 'itIT', 'Hic! Guarda dove metti i piedi...', 'Hic! Guarda dove metti i piedi...', 28153),
(131878, 'itIT', '<Esamina il corpo per identificarlo.>', '<Esamina il corpo per identificarlo.>', 28153),
(131875, 'itIT', 'Oggi cosa dobbiamo spedire?', 'Oggi cosa dobbiamo spedire?', 28153),
(131874, 'itIT', 'Sì?', 'Sì?', 28153),
(131869, 'itIT', 'Grog della vedova! Tre barili.', 'Grog della vedova! Tre barili.', 28153),
(131868, 'itIT', 'Vino speziato! Cinque barili! Birra abissale! Sette barili! Eee...', 'Vino speziato! Cinque barili! Birra abissale! Sette barili! Eee...', 28153),
(131867, 'itIT', 'Ascoltate! Questo è l\'ordine del giorno!', 'Ascoltate! Questo è l\'ordine del giorno!', 28153),
(131855, 'itIT', 'Grazie ancora per il tuo aiuto. Porterò queste offerte direttamente al tempio.', 'Grazie ancora per il tuo aiuto. Porterò queste offerte direttamente al tempio.', 28153),
(131851, 'itIT', 'Calmatevi, tutti quanti! $p sta per passare a salutarvi uno a uno.', '', 28153),
(131845, 'itIT', 'Basta così per ora. Va\' a trovare la principessa alla grande scalinata. Io starò accà di pattuglia nel caso arrivasse qualcuno dell\'Alleanza.', '', 28153),
(131844, 'itIT', 'Dividiamoci e troviamo chesti membri dell\'Alleanza. Farò il possibile per aiutarti a trovarli.', '', 28153),
(131843, 'itIT', 'Che audacia! N\'attacco direttamente al tempio mio! Eheh, incredibile! Se ne pentiranno... ahah... se ne pentiranno assai.', '', 28153),
(131842, 'itIT', '', 'Ho camminato su chesto mondo fin troppo a lungo. Alla fine è giunta la pace!', 28153),
(131841, 'itIT', 'Mmm. Vai pure, cumpà. Bwonsamdi ti osserva.', '', 28153),
(131840, 'itIT', 'Bene, bene. Sylvanas sarà compiaciuta. Vieni, \"Oratore\", parliamo della nostra prossima mossa.', '', 28153),
(131839, 'itIT', 'Aspetta, dobbiamo TUTTI combattere quella cosa? Pensavo potessimo... cioè, sai... inviare un rappresentante o qualcosa del genere.', '', 28153),
(131838, 'itIT', 'Per suonare il tamburo avrai bisogno del Martello di Mambu e del Martello di Gee\'dae. Li troverai entrambi nel tempio mio.', '', 28153),
(131832, 'itIT', 'Grazie, $gamico:amica;.', '', 28153),
(131831, 'itIT', 'Mi serve un passaggio per Zul\'jan.', 'Mi serve un passaggio per Zul\'jan.', 28153),
(131830, 'itIT', '', 'Anche se sono schiattato, le creature rispondono ancora alla chiamata mia.\n\nVuoi nu passaggio?', 28153),
(131829, 'itIT', 'Devo parlarti n\'attimo. Ci sta nu problema che richiede l\'attenzione tua.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(131828, 'itIT', 'Ciao, $gamico mio:amica mia;! Ti ho cercato ovunque!', '', 28153),
(131818, 'itIT', 'Nun dimenticare il patto nostro. Continua a mandarmi anime... se vuoi ancora il favore mio.', '', 28153),
(131816, 'itIT', 'Calma, principessa! Sarà meglio procedere con cautela. Dobbiamo esplorare la zona e pensare a nu piano.', '', 28153),
(131803, 'itIT', '', 'Tu devi essere $gl\'eroe:l\'eroina; di cui parla, immagino. Se riuscirai ad aiutare la principessa nostra, ti dirò ogni cosa. È ormai da tanto tempo che mi piglio cura dei feriti, e le cose nun fanno che peggiorare.\n\nÈ diretta a Nazmir e si porterà appresso na sola guardia piccirilla, oltre a Rokhan. Gli abbiamo dato tutte le provviste in eccesso.\n\nPasseranno dal cancello a nord-ovest. Nessun Troll del Sangue è stato avvistato in chel luogo da diverso tempo, da quando hanno cominciato l\'assalto al cancello principale.\n\nGli occhi del Loa mio vegliano su chel luogo. Sta\' accuort\'.', 28153),
(131777, 'itIT', 'Ripagherò questo debito, hai la mia parola.', 'Ripagherò questo debito, hai la mia parola.', 28153),
(131776, 'itIT', 'Posso... andare? Senza niente in cambio? Non sei come gli altri.', '', 28153),
(131774, 'itIT', '', 'Che caos laggiù. Vorrei che la principessa nun se ne fosse mai andata. I Troll del Sangue stanno alle porte nostre e il re nun fa niente!', 28153),
(131771, 'itIT', 'Sta accà a malapena da nu giorno e già se ne va!\n\nTalanji se n\'è andata da qualche parte e trama alle spalle del padre suo. Ha pigliato qualche guardia del corpo per mantenere le apparenze.\n\nCredo sia diretta a Nazmir, anche se nun lo dice. Chello è nu posto fetente, cumpà. Se io nun posso andare, starei meglio se ci fossi tu con essa.\n\nTiene bisogno d\'aiuto. La principessa terrà nu conto in sospeso con i Sacerdoti della vecchia dimora sua. Fammi vedere la mappa tua.', '', 28153),
(131766, 'itIT', 'Dov\'è Talanji?', 'Dov\'è Talanji?', 28153),
(131765, 'itIT', 'Tieni la mia gratitudine per aver salvato la principessa. So che a volte è difficile proteggerla. Crede di dover salvare li Zandalari da sola.', '', 28153),
(131764, 'itIT', 'La tua gentilezza è inaspettata.', 'La tua gentilezza è inaspettata.', 28153),
(131763, 'itIT', 'Non perdiamo altro tempo, questo è il Comando Avanzato. Ci troviamo nel bel mezzo di esso, con l\'Accampamento Taurajo impegnato a inviare continuamente ondate e ondate di dannati Tauren contro di noi.\n\nSe dovessimo perdere la posizione, non riusciremmo mai a conquistare i cancelli.', '', 28153),
(131761, 'itIT', 'Nun puoi nasconderti dal mojo!', '', 28153),
(131752, 'itIT', 'Valjabu, nun ci sta motivo per andare nell\'Aldilà. Sottomettiti a G\'huun e potrai ottenere la vita eterna!', '', 28153),
(131750, 'itIT', '$gUn altro patetico esiliato venuto:Un\'altra patetica esiliata venuta; a morire tra le sabbie?', '', 28153),
(131745, 'itIT', '', 'Fatti strada verso Nazmir con Rokhan. Io vi raggiungerò lì. Dobbiamo porre fine alla minaccia di chesti Troll del Sangue.', 28153),
(131742, 'itIT', '', 'Che Odyn vi benedica. Eccovi anche una giusta ricompensa.', 28153),
(131741, 'itIT', 'Va bene ragazzi, entriamo e mettiamoci in azione. Voglio delle guardie alle porte in caso tentino di cacciarci fuori e voglio immediatamente un servizio ristorazione. Inoltre, trovatemi un\'altra pietra del teletrasporto per le emergenze.', '', 28153),
(131709, 'itIT', 'Che cosa sta succedendo accà? Perché siamo rinchiusi come animali?', '', 28153),
(131706, 'itIT', '', 'Yorrick, porta qui il kit da campo, c\'è un sopravvissuto!', 28153),
(131705, 'itIT', 'Uh... oh! Sì, signore!', '', 28153),
(131703, 'itIT', '', 'In piedi, Guardiamarina! Dobbiamo trovare un modo di uscire da qui!', 28153),
(131690, 'itIT', '<La Guardia di Spade Hozzul non risponde.>', '', 28153),
(131689, 'itIT', '', '<La Guardia di Spade Jorana non risponde.>', 28153),
(131674, 'itIT', 'Ti do il benvenuto alla Locanda Zannadoro!', '', 28153),
(131672, 'itIT', '<Questo esiliato sembra essere ancora vivo, anche se respira a malapena.\n\nNon sembra passarsela molto bene, ma il suo stato suggerisce un qualcosa di più grave delle semplici ferite visibili a occhio nudo.>', '', 28153),
(131671, 'itIT', '<Sembra ci sia una luce proveniente dall\'altro lato di questi detriti che bloccano il corridoio.\n\nSe si riuscisse ad aprire un passaggio fra le macerie, quella luce potrebbe condurre fuori dalle rovine.>', '', 28153),
(131670, 'itIT', '<Queste creature sono state uccise dalla magia del gelo, un chiaro segno del passaggio di Jaina.\n\nDove si sia diretta, tuttavia, rimane un mistero.>', '', 28153),
(131668, 'itIT', '<Probabilmente si tratta delle tracce di una delle bestie che ha attaccato il tuo gruppo nella foresta. Sembra che stesse trascinando qualcosa dietro di sé.\n\nStranamente, le tracce scompaiono completamente a un certo punto, come se la bestia fosse scomparsa.>', '', 28153),
(131667, 'itIT', 'Fai attenzione. Inizio ad avere FAME!', '', 28153),
(131666, 'itIT', '', 'Cos\'era chello?!?', 28153),
(131665, 'itIT', '<Il Cucciolo di Cornofurente grida per la sorpresa.>', '', 28153),
(131664, 'itIT', '<Il Cornofurente Giovane ti salta addosso affettuosamente.>', '', 28153),
(131663, 'itIT', '<Il Cornofurente Giovane ti dà un accidentale morso d\'affetto.>', '', 28153),
(131662, 'itIT', '<Il Cornofurente Giovane ti urta tutto felice.>', '', 28153),
(131661, 'itIT', 'Ho così fame che mangerei un brutosauro.', '', 28153),
(131659, 'itIT', 'Mamma, posso avere altra carne, per favore?', '', 28153),
(131658, 'itIT', 'I guinzagli sono buoni, ma io voglio la CARNE!', '', 28153),
(131657, 'itIT', '<%s ruggisce giocosamente.>', '', 28153),
(131656, 'itIT', '<%s ti saluta giocosamente.>', '', 28153),
(131655, 'itIT', '<%s saltella felicemente.>', '', 28153),
(131654, 'itIT', '<%s piagnucola con foga.>', '', 28153),
(131653, 'itIT', 'Senti, avrai anche coraggio, ma non sei $gun negoziatore:una negoziatrice;. Non al mio livello.$b$bFammi avere un\'udienza con il loro re e lo convincerò a darci la sua flotta, il trono, tutto l\'oro che hanno usato per decorare questo posto e, mentre lo saluto, anche qualche Maschera Tiki.', '', 28153),
(131652, 'itIT', 'Eheheh, guarda nu poco! Forse con te nun spreco il tempo mio, dopotutto, eheh! Vieni a parlare con me al tempio. Il vecchio Bwonsamdi tiene n\'offerta per te.', '', 28153),
(131651, 'itIT', 'Ah, Salazae... ha bighellonato con i vivi troppo a lungo. Fai ciò che devi per portare l\'anima sua a chesto Loa fin troppo paziente, eheh... capito?', '', 28153),
(131650, 'itIT', '', 'Vattene, a meno che tu nun possa farmi tornare con l\'amato mio.', 28153),
(131649, 'itIT', 'Siamo pronti a ricevere la tua benedizione.', 'Siamo pronti a ricevere la tua benedizione, grande Loa.', 28153),
(131648, 'itIT', 'Sono passati molti anni dalla costruzione di questo tempio. Anche se le mura sono le stesse, i volti dei miei seguaci sono cambiati.', '', 28153),
(131637, 'itIT', 'Salve, piccole creature, sono tornato. Avvicinatevi e ricevete la mia benedizione.', '', 28153),
(131633, 'itIT', 'Solo gli Zandalari possono mettere piede in cheste sacre sale! La legge stabili...', '', 28153),
(131632, 'itIT', 'Che sia noto... da chesto giorno, ti nomino Voce dell\'Orda.', '', 28153),
(131631, 'itIT', 'La legge è ciò che dico io, fintanto che sarò Re.', '', 28153),
(131630, 'itIT', 'Li occhi dell\'Impero sono puntati su di te. Chest\'oggi ti nomino Voce dell\'Orda.', '', 28153),
(131629, 'itIT', 'Vediamo se l\'Orda sarà in grado di provare il valore suo. Che stiano accà al Gran Sigillo, come ospiti miei... per ora.', '', 28153),
(131628, 'itIT', 'Talanji teme che nun capisca chi sono i nemici nostri, ma sappi che nun sono cieco come crede.', '', 28153),
(131627, 'itIT', 'Ma pure la figlia mia tiene ragione. Il fatto che tu l\'abbia salvata dimostra coraggio... qualità che ammiro.', '', 28153),
(131626, 'itIT', 'Jakra\'zet dice il vero... vuoi usare il potere della flotta nostra contro l\'Alleanza.', '', 28153),
(131625, 'itIT', '', 'Grandioso! Siediti e diamo inizio alla festa. Con il tuo aiuto e quello di Pomicio, posso chiamare l\'ultimo ospite!', 28153),
(131624, 'itIT', '', 'Quassù! Sarà l\'ora del tè più bella di sempre!', 28153),
(131623, 'itIT', '', 'Andiamo! Andiamo! È l\'ora del tè!', 28153),
(131620, 'itIT', '', 'Con il tuo sacrificio, insieme a quello di mio marito, il rituale è completato!', 28153),
(131619, 'itIT', '', 'Unisciti a noi, sorella, e insieme otterremo un grande potere!', 28153),
(131618, 'itIT', '<C\'è una grossa ferita aperta al centro del torso dell\'uomo. Guardando all\'interno, noti che il suo cuore è stato strappato.>', '', 28153),
(131617, 'itIT', '<Sul legno è stato inciso \"S. Biancospino\".>', '', 28153),
(131616, 'itIT', '', 'Il Signor Biancospino teneva sempre i cagnolini lontani dai suoi animali. Ora i cagnolini possono finalmente mangiare!', 28153),
(131615, 'itIT', '', 'Il nostro villaggio è deserto.', 28153),
(131609, 'itIT', '', 'Dobbiamo essere cauti. Nessuno ha mai fatto ritorno da Nazmir.', 28153),
(131608, 'itIT', '', 'I Troll del Sangue sono dei patetici selvaggi. Nun sono stati nu pericolo per secoli.', 28153),
(131607, 'itIT', 'Basta! Deciderò io cosa fare con chesto \"campione\"!', '', 28153),
(131606, 'itIT', '', 'Per sconfiggere i Troll del Sangue, ci servono alleati. Ho fatto ciò che dovevo.', 28153),
(131605, 'itIT', 'Talanji ha portato la feccia dell\'Orda con sé. Chesto è tradimento, Maestà.', '', 28153),
(131604, 'itIT', '', 'L\'anima tua per il mio padrone! L\'anima tua per G\'huun!', 28153),
(131603, 'itIT', 'Chesta nun sarà... la fine...', 'Chesta nun sarà... la fine...', 28153),
(131602, 'itIT', '', 'G\'huun è il padrone di chesta terra! Presto anche chillo stupido di Bwonsamdi lo servirà!', 28153),
(131544, 'itIT', 'Sono pronto.', 'Sono pronta.', 28153),
(131543, 'itIT', '', '<Annie ti guarda con occhi vuoti. I suoi vestiti sono macchiati di sangue, anche se non sembra ferita. Balbetta, ma le sue parole sono incomprensibili.>', 28153),
(131542, 'itIT', 'Mace, Notley e Yorrick hanno fatto rapporto e sono pronti a partire.', 'Mace, Notley e Yorrick hanno fatto rapporto e sono pronti a partire.', 28153),
(131541, 'itIT', 'Vieni da Acqualunga?', 'Vieni da Acqualunga?', 28153),
(131540, 'itIT', '', '<Annie trema visibilmente. I suoi occhi fissano il vuoto.>', 28153),
(131539, 'itIT', 'È giunta l\'ora. Raggiungimi al cancello e insieme attaccheremo Drustvar!', '', 28153),
(131505, 'itIT', 'Non lo lascerò così. Fai sapere agli altri cosa gli hanno fatto, ci rivedremo al tempio.', '', 28153),
(131504, 'itIT', '<Sospira> Ti prego, svegliati...', '', 28153),
(131503, 'itIT', 'Hakasi, ora sei al sicuro... Hakasi? Ehi, svegliati...', '', 28153),
(131497, 'itIT', 'Cattivo gigantosauro! Cattivo!', 'Cattivo gigantosauro! Cattivo!', 28153),
(131496, 'itIT', 'Grazie per l\'aiuto e per aver inoltrato i miei ordini. Farò rapporto al Maresciallo Reade.', '', 28153),
(131494, 'itIT', 'Spesso il tempo è nemico della saggezza.', '', 28153),
(131493, 'itIT', 'La saggezza suggerirebbe di aspettare che passi la tempesta prima di avventurarsi in un territorio così ostile.', '', 28153),
(131492, 'itIT', 'Molto bene, preparerò i rifornimenti immediatamente.', '', 28153),
(131491, 'itIT', 'Di\' al Maresciallo Reade che il Quartiermastro Notley è a rapporto!', '', 28153),
(131490, 'itIT', '', 'Incontriamoci al cancello, continentale. Spero tu sia $gpronto:pronta; per ciò che ci aspetta.', 28153),
(131489, 'itIT', '', 'Ah! Quindi Reade vorrebbe avventurarsi nei boschi di Drustvar? Era ora che succedesse qualcosa di interessante qui.', 28153),
(131487, 'itIT', '', 'C\'è un motivo particolare per cui mi stai importunando, continentale?\n\nO forse non è chiaro che ho da fare?', 28153),
(131486, 'itIT', 'Una tempesta sta per abbattersi su Boscomorto. Sarà ancora più difficile scoprire un qualsiasi attacco prima che si presenti alle nostre porte.\n\nCome se Drustvar non fosse già abbastanza pericolosa anche senza questo tempo maledetto...', '', 28153),
(131485, 'itIT', 'Il Maresciallo Reade ti ordina di unirti alla sua spedizione per trovare Jaina.', 'Il Maresciallo Reade ti ordina di unirti alla sua spedizione per trovare Jaina.', 28153),
(131484, 'itIT', 'Oh, non arrivano molti continentali qui alle mura di solito.\n\nStai cercando delle risorse?', '', 28153),
(131479, 'itIT', 'Lo ammetto, il tuo coraggio mi ha davvero sorpreso, continentale.\n\nAnche se non sei di queste parti, hai scelto di affrontare il pericolo per salvare uno di noi. Spero solo che la tua lama sia ferma come il tuo cuore.\n\nPartiremo quando sarai $gpronto:pronta;.', '', 28153),
(131478, 'itIT', 'Tieni duro, Hakasi... ti salveremo, te lo prometto!', '', 28153),
(131477, 'itIT', 'Non... la passerai liscia... mostro!', '', 28153),
(131476, 'itIT', '$gUn:Una; continentale qui alle mura? Sicuramente sei $gvenuto:venuta; fin qui a vedere coi tuoi occhi la maledizione che affligge Drustvar senza essere a conoscenza del grave pericolo che porta con sé.\n\nVa\' a casa, $gragazzo:ragazza;. Questo posto non fa per te.', '', 28153),
(131475, 'itIT', 'Cosa?\n\nLe mie scuse, ho parlato a sproposito.\n\nQuindi sei $gun alleato:un\'alleata; della Casata dei Marefiero? Immagino tu sia qui in cerca di notizie riguardanti Jaina, allora. Altrimenti non ci sarebbe una ragione per avventurarsi così tanto a nord.\n\nBe\', potresti essere $garrivato:arrivata; appena in tempo.', '', 28153),
(131472, 'itIT', '<Dai a Reade la lettera di Taelia.>', '<Dai a Reade la lettera di Taelia.>', 28153),
(131471, 'itIT', 'Ah, salve, Hanzabu. Stai accà per saldare i debiti tuoi?', '', 28153),
(131470, 'itIT', 'Che notizie porti, viandante?', '', 28153),
(131469, 'itIT', 'Dobbiamo salvarlo!', '', 28153),
(131468, 'itIT', 'Ho appena sentito la voce di Hakasi da dentro la caverna! Sembrava fosse in pericolo...', '', 28153),
(131467, 'itIT', '$n! Vieni accà!', '', 28153),
(131466, 'itIT', 'Guardie! Alleati! Forze dell\'Orda in avvicinamento da sud-ovest! State pronti a difendere i cancelli!', '', 28153),
(131465, 'itIT', 'Tu preoccupati degli uomini serpente, io andrò avanti a cercare Hakasi...', '', 28153),
(131461, 'itIT', 'Buahahah! Hanzabu, per chi mi hai preso? Nun è stata la mano tua ad accidere chei due.', '', 28153),
(131460, 'itIT', 'Due di loro stanno feriti in modo grave. Dovrebbero andare bene per il patto nostro, vero?', '', 28153),
(131459, 'itIT', 'Grande Bwonsamdi, ti ho portato altre anime... come pattuito.', '', 28153),
(131458, 'itIT', '', 'Aspetta... ascolta, mi è parso di sentire qualcosa.', 28153),
(131457, 'itIT', '', 'La barriera ha ceduto! Andiamocene da accà!', 28153),
(131456, 'itIT', 'Era inutile. I Troll del Sangue invadono le terre nostre da nord, l\'Alleanza si infiltra da sud e mo\' permettiamo l\'accesso alla città a cheste bestie dell\'Orda.', '', 28153),
(131455, 'itIT', '', 'Nun so cos\'hai fatto, ma ha fermato il flusso di mojo della barriera. Cerchiamo altre di chelle cose.', 28153),
(131454, 'itIT', '', 'Rakera era la guida migliore che chesto regno...', 28153),
(131453, 'itIT', 'Ho notizie su Hakasi.', 'Ho notizie su Hakasi.', 28153),
(131452, 'itIT', '', 'Stanno arrivando!', 28153),
(131451, 'itIT', '', 'Il passaggio sta bloccato! Diamo n\'occhiata. Ci deve stare nu modo per abbattere chella barriera.', 28153),
(131450, 'itIT', '', 'Nessuna pietà!', 28153),
(131449, 'itIT', '', 'Nessuno può fermarci!', 28153),
(131448, 'itIT', '', 'Frantumato!', 28153),
(131447, 'itIT', '', 'Tayhuwaniwanga!', 28153),
(131446, 'itIT', '<Un mostro ruggisce da lontano.>', '', 28153),
(131445, 'itIT', 'Dobbiamo andare a cercarlo prima che sia troppo tardi! Troviamoci vicino al canyon non appena sei $gpronto:pronta;!', '', 28153),
(131444, 'itIT', 'Dunque Hakasi è andato a indagare nel canyon e non è più tornato... è una pessima notizia.', '', 28153),
(131443, 'itIT', '', 'Sta\' accuort\', li spiriti stanno arrabbiati. Stanno intrappolati accà da molto tempo.', 28153),
(131442, 'itIT', '', '$gIl nostro ospite:La nostra ospite; è $gsveglio:sveglia;.', 28153),
(131440, 'itIT', '', 'Pomicio adora le foreste. Mi assicurerò che i cani non lo prendano!', 28153),
(131439, 'itIT', 'Nun mi prenderai, strega!', '', 28153),
(131435, 'itIT', 'Aiuta gli addestratori a soggiogare il gigantosauro!', 'Aiuta gli addestratori a soggiogare il gigantosauro!', 28153),
(131434, 'itIT', 'Attacca Morte Rossa!', 'Attacca Morte Rossa!', 28153),
(131431, 'itIT', 'Lancia un giocattolo per distrarre il gigantosauro!', 'Lancia un giocattolo per distrarre il gigantosauro!', 28153),
(131430, 'itIT', 'Carica la barriera per sfondarla!', 'Carica la barriera per sfondarla!', 28153),
(131429, 'itIT', 'Fuggi dalla Porta Settentrionale! Non farti prendere dal gigantosauro!', 'Fuggi dalla Porta Settentrionale! Non farti prendere dal gigantosauro!', 28153),
(131428, 'itIT', 'Buona fortuna, apprendista!', '', 28153),
(131427, 'itIT', 'È nu piacere averti alla zona d\'addestramento! Affronterai Mignolo, l\'irritabile giovane gigantosauro nostro.', '', 28153),
(131426, 'itIT', 'Quella spedizione è nostra, feccia dell\'Alleanza!', 'Quella spedizione è nostra, feccia dell\'Alleanza!', 28153),
(131425, 'itIT', 'Esamina il cadavere più attentamente.', 'Esamina il cadavere più attentamente.', 28153),
(131424, 'itIT', '<Le ferite sono profonde. Questi tagli sono stati fatti con estrema precisione.$B$BI resti di una sostanza liquida riflettono la luce insieme alle aree lesionate.>', '', 28153),
(131419, 'itIT', '', 'Partiremo nun appena vorrai, ma vediamo di nun perdere troppo tempo. Rakera non durerà assai in chelle sabbie.', 28153),
(131418, 'itIT', '', 'Nun riposerò finché nun troveremo Rakera.', 28153),
(131416, 'itIT', 'Hai mai combattuto contro nu gigantosauro? Nun morde forte... generalmente!', 'Hai mai combattuto contro nu gigantosauro? Nun morde forte... generalmente!', 28153),
(131415, 'itIT', '', 'Tieni ragione! Muoviamoci!', 28153),
(131414, 'itIT', '', 'Le parole tue sono sagge. Vieni, troviamo nu modo per uscire da chesta cripta.', 28153),
(131413, 'itIT', '', 'Tieni ragione, cumpà. Diamo n\'occhiata, ci deve stare nu modo per uscire da accà.', 28153),
(131408, 'itIT', 'I soldati non si arrendono mai, Bwu\'ja. Ora riprenditi e troviamo un modo per uscire da qui. Per l\'Orda!', 'I soldati non si arrendono mai, Bwu\'ja. Ora riprenditi e troviamo un modo per uscire da qui. Per l\'Orda!', 28153),
(131407, 'itIT', 'Abbiamo una missione, Bwu\'ja, dobbiamo portarla a termine, costi quel che costi!', 'Abbiamo una missione, Bwu\'ja, dobbiamo portarla a termine, costi quel che costi!', 28153),
(131406, 'itIT', 'È questo l\'atteggiamento che intendi mostrare alla Capoguerra? Dipende tutto da noi!', 'È questo l\'atteggiamento che intendi mostrare alla Capoguerra? Dipende tutto da noi!', 28153),
(131405, 'itIT', '', 'Nun tiene più senso combattere, siamo finiti ormai!', 28153),
(131404, 'itIT', 'Sei una Cacciatrice dell\'Ombra, Bwu\'ja. Mostragli che non è soltanto un titolo.', 'Sei una Cacciatrice dell\'Ombra, Bwu\'ja. Mostragli che non è soltanto un titolo.', 28153),
(131403, 'itIT', 'Vuoi che le speranze e i sogni dei tuoi antenati vadano in frantumi senza combattere?', 'Vuoi che le speranze e i sogni dei tuoi antenati vadano in frantumi senza combattere?', 28153),
(131399, 'itIT', 'E allora continua a combattere! Credi in te e rendili fieri!', 'E allora continua a combattere! Credi in te e rendili fieri!', 28153),
(131396, 'itIT', '', 'Cosa? Certo che no!', 28153),
(131392, 'itIT', 'Forza, riprenditi. Sei una Cacciatrice dell\'Ombra, sei meglio di così!', 'Forza, riprenditi. Sei una Cacciatrice dell\'Ombra, sei meglio di così!', 28153),
(131391, 'itIT', 'Nun sembra che la Principessa Talanji voglia attendere. Ha già lasciato il molo insieme a Zul. Ti conviene muoverti se desideri raggiungerli.', '', 28153),
(131389, 'itIT', '', '[PH] Intro', 28153),
(131388, 'itIT', 'Se sei disperata, significa che il tuo spirito è ancora vivo e puoi ancora fare qualcosa per cambiare la situazione!', 'Se sei disperata, significa che il tuo spirito è ancora vivo e puoi ancora fare qualcosa per cambiare la situazione!', 28153),
(131387, 'itIT', 'Si sta liberando! Correte!', 'Si sta liberando! Correte!', 28153),
(131386, 'itIT', 'C\'è ancora speranza! Se lottiamo insieme, troveremo un modo per sconfiggere questa maledizione.', 'C\'è ancora speranza! Se lottiamo insieme, troveremo un modo per sconfiggere questa maledizione.', 28153),
(131385, 'itIT', 'Per adesso, lascerò che tu e Rokhan decidiate come procedere, in quanto conosce questa gente meglio di me.$b$bInoltre, i Troll sono pieni di pregiudizi nei confronti di coloro, come me, che si rifiutano di restate morti. Non voglio che la loro scarsa lungimiranza sulla vita possa impedirci di ottenere la loro flotta.$b$bNon dobbiamo fallire. Sylvanas deve averla.', '', 28153),
(131384, 'itIT', '', 'Oh? E perché lo pensi?', 28153),
(131383, 'itIT', 'Torna in te, dobbiamo continuare a combattere!', 'Torna in te, dobbiamo continuare a combattere!', 28153),
(131382, 'itIT', 'Cosa dirai agli spiriti dei tuoi antenati quando li incontrerai? Che ti sei arresa?', 'Cosa dirai agli spiriti dei tuoi antenati quando li incontrerai? Che ti sei arresa?', 28153),
(131377, 'itIT', 'Non cedere alla disperazione! Troveremo un modo per uscire!', 'Non cedere alla disperazione! Troveremo un modo per uscire!', 28153),
(131372, 'itIT', 'Muoviamoci.', 'Muoviamoci.', 28153),
(131371, 'itIT', 'Non riesco a credere che Hakasi abbia lasciato tutto il lavoro a noi. La pagherà quando tornerà!', '', 28153),
(131370, 'itIT', '', 'Ahah! Colpito!', 28153),
(131369, 'itIT', '', 'Nun ci sta speranza. Come usciremo da accà?', 28153),
(131333, 'itIT', 'Mi ha detto qualcosa riguardo un certo disturbo nel canyon. Gli ho detto che non era probabilmente nulla di cui preoccuparsi.', '', 28153),
(131332, 'itIT', 'Mmm... fammi pensare. Oh, sì! L\'ho visto dirigersi nel canyon non troppo tempo fa. Mi chiedo cosa stesse facendo...', '', 28153),
(131331, 'itIT', 'Hakasi? Sì, l\'ho visto l\'altro giorno non lontano da qui. Stava radunando le offerte per il rituale.', '', 28153),
(131329, 'itIT', '', 'Rompete i ranghi! Mettetevi al sicuro! Allontanatevi il più possibile da chei serpenti!', 28153),
(131327, 'itIT', 'Kaja, dovremmo cambiare rotta. Ci stiamo avvicinando all\'impero dei Sethrak.', '', 28153),
(131325, 'itIT', '', 'Gli uomini serpente? Credevo si nascondessero sotto le dune...', 28153),
(131322, 'itIT', '', 'Avanti! Vedo il passo! Vola basso e tieni gli occhi aperti per qualche segno di Rakera.', 28153),
(131306, 'itIT', 'Non hai mai visto il grande Akunda prima d\'ora? Non potevi arrivare in un momento migliore!', '', 28153),
(131305, 'itIT', 'Ho un sacco di lavoro da fare prima che arrivi Akunda! Non c\'è tempo... non c\'è assolutamente tempo!', '', 28153),
(131304, 'itIT', 'Hai visto Hakasi?', 'Hai visto Hakasi?', 28153),
(131303, 'itIT', 'Sono passati molti anni da quando la nostra gente ha evocato Akunda. Non vedo l\'ora di trovarmi di nuovo in sua presenza!', '', 28153),
(131302, 'itIT', '<%s divora avidamente ogni boccone, poi rutta fiamme!>', '', 28153),
(131300, 'itIT', '%s divora rumorosamente la pianta.', '', 28153),
(131299, 'itIT', 'Finalmente una vera battaglia!\n\nQuesti stolti dell\'Orda credono di poter far breccia nella gola e raggiungere il Comando Avanzato. Cosa ne penso?\n\nFOLLIA!\n\nVieni, andiamo a uccidere un po\' di feccia insieme.', '', 28153),
(131298, 'itIT', '', 'Sono felice che tu sia qui, stiamo reggendo a malapena!\n\nLa Roccaforte del Trionfo è un punto strategico cruciale per il nostro assalto ai cancelli. Con la gola a nord sotto costante attacco dai rinforzi di Orgrimmar, se non riuscissimo a mantenere il controllo di questa posizione, tutti i nostri convogli provenienti da Theramore sarebbero in pericolo.', 28153),
(131297, 'itIT', 'Come desideri, Maestro Higashi...', '', 28153),
(131296, 'itIT', 'Assaggiare il cibo non significa \"preparare il banchetto\". Non farmelo ripetere, Rifu.', '', 28153),
(131295, 'itIT', 'Ma sono già occupato a preparare il banchetto!', '', 28153),
(131294, 'itIT', 'Hakasi deve ancora arrivare con le ultime offerte. Fatti accompagnare $gdal nostro nuovo amico:dalla nostra nuova amica; e recuperale.', '', 28153),
(131293, 'itIT', 'Sì, Maestro Higashi!', '', 28153),
(131292, 'itIT', 'Rifu! C\'è qui qualcuno che vorrei che tu incontrassi.', '', 28153),
(131291, 'itIT', 'Senza di esse, non potremmo evocare il Loa. Forse potresti aiutarci...', '', 28153),
(131290, 'itIT', 'Il momento del rituale è quasi giunto, ma molte delle offerte necessarie devono ancora arrivare.', '', 28153),
(131289, 'itIT', 'Cerca le tavolette antiche all\'interno delle sale del tempio. La leggenda di Akunda ti attende.', '', 28153),
(131255, 'itIT', 'Che la gloria sua sia sempre lodata. Che egli protegga per sempre chesta giungla.', '', 28153),
(131254, 'itIT', '', 'Vabbuo\', è l\'ora di scegliere n\'uovo. Saprai se nu cucciolo ti avrà accettato se sentirai la voce sua nella capa.', 28153),
(131250, 'itIT', '', '<La Matriarca Jaz\'lith ti osserva con attenzione.>', 28153),
(131249, 'itIT', '', 'Eccola. Nun è la perfetta combinazione di ferocia e grazia? Sfidala se tieni il coraggio.', 28153),
(131248, 'itIT', '', 'Chesto monumento è antico, ma è assai simile ai santuari di Bwonsamdi a Zandalar.', 28153),
(131247, 'itIT', 'Io e il cornofurente mio stiamo assieme sin da quando è uscito dall\'uovo. Combattiamo all\'unisono.', 'Io e il cornofurente mio stiamo assieme sin da quando è uscito dall\'uovo. Combattiamo all\'unisono.', 28153),
(131246, 'itIT', 'Sì, diventare n\'Invocatrice delle Bestie richiede grandi capacità, ma anche infinita pazienza. Nu giovane cornofurente può causare molti problemi!', 'Sì, diventare n\'Invocatrice delle Bestie richiede grandi capacità, ma anche infinita pazienza. Nu giovane cornofurente può causare molti problemi!', 28153),
(131245, 'itIT', 'E quindi fu in chel preciso punto che costruimmo chesto tempio in onore di Akunda. Che nessuno di noi dimentichi più il potente Loa.', '', 28153),
(131244, 'itIT', 'Quando tutto si calmò, ci arrampicammo sulla vetta della montagna. Il corpo esanime di Zul\'khan stava di fronte a noi, ma di Akunda nun rimase traccia.', '', 28153),
(131243, 'itIT', 'Proprio quando sembrava che la battaglia nun dovesse finire mai, la polvere si diradò e la terra cessò di tremare...', '', 28153),
(131242, 'itIT', 'Akunda era tornato e in pochi istanti le due bestie si scagliarono l\'una contro l\'altra. La terra tremava a ogni colpo!', '', 28153),
(131241, 'itIT', 'Proprio quando ogni speranza era ormai persa, nu potente ruggito tuonò tra le mura del canyon. Na figura apparve sulle alture, stagliandosi nella luce della Luna.', '', 28153),
(131240, 'itIT', 'Attaccammo Zul\'khan con tutte le nostre forze, ma il suo potere era troppo grande! Si liberò... senza lasciarci alcuna possibilità.', '', 28153),
(131239, 'itIT', 'Attirammo Zul\'khan nel profondo del canyon per tendergli n\'imboscata. Lanciammo na grossa rete dall\'alto...', '', 28153),
(131238, 'itIT', 'Li anziani delle tribù si incontrarono nel cuore di Vol\'aman. Cosa dovevamo fare? Rimanere uniti e combattere insieme o prendere il possibile e fuggire nella giungla? Noi scegliemmo di combattere!', '', 28153),
(131237, 'itIT', 'Zul\'khan era quindi libero di terrorizzare cheste terre. Cacciò e accise la gente mia indiscriminatamente. Erano tempi bui...', '', 28153),
(131236, 'itIT', 'Smettemmo di onorare il grande sauro del tuono. Alla fine, Akunda scomparve dalla giungla...', '', 28153),
(131235, 'itIT', 'Akunda ci difese dal terrore di Zul\'khan, ma con il passare delli anni la gente mia cominciò a ignorarlo.', '', 28153),
(131234, 'itIT', 'Il gigantosauro Zul\'khan era geloso del potere del Loa. Vagava nella giungla oscura, cacciando per gola e accidendo per divertimento.', '', 28153),
(131233, 'itIT', 'Tutte le creature si inchinavano alla magnificenza e al potere suo. Tutte eccetto una, il tiranno Zul\'khan...', '', 28153),
(131232, 'itIT', 'Molto tempo fa, la gente mia guardava con ammirazione il grande sauro del tuono vagare per la giungla.', '', 28153),
(131231, 'itIT', 'Io, Zan\'gaji, capo della tribù mia e architetto di chesto tempio, lo consacro in onore del potente Akunda.', '', 28153),
(131230, 'itIT', 'È tutta la vita che mi addestro per diventare n\'Invocatore delle Bestie. Cosa hai fatto tu?', 'È tutta la vita che mi addestro per diventare n\'Invocatore delle Bestie. Cosa hai fatto tu?', 28153),
(131229, 'itIT', 'Combattiamo!', 'Combattiamo!', 28153),
(131228, 'itIT', '', 'Zandalar per sempre!', 28153),
(131227, 'itIT', '', 'I Loa stanno con me!', 28153),
(131226, 'itIT', '', 'Per Zuldazar!', 28153),
(131224, 'itIT', '', 'La Guardia da Guerra Rakera era il comandante mio. Il migliore che chesta città abbia mai avuto.', 28153),
(131223, 'itIT', 'Io nun faccio domande, eseguo solo li ordini. Faresti meglio a fare lo stesso.', '', 28153),
(131222, 'itIT', 'Sputa il rospo, nun mi pagano per parlare.', '', 28153),
(131221, 'itIT', '', 'Vuoi schiattare? Il generale tiene occhi e orecchie dappertutto.', 28153),
(131220, 'itIT', '', 'Qualunque cosa ti serva, fa\' presto.', 28153),
(131218, 'itIT', '', 'Come puoi vedere, ci stanno ancora persone tra di noi che lo credono.', 28153),
(131215, 'itIT', '', 'Ehi, tu! Sì, tu. Sei tu che vai chiedendo in giro del Generale?', 28153),
(131214, 'itIT', '', 'Le dune sono na sentenza di morte. Nun me ne starò accà a lasciare che Rakera venga ingoiata dalle sabbie!', 28153),
(131213, 'itIT', '', 'Qualsiasi cosa abbia scoperto, le ha fatto ottenere nu viaggio verso il deserto.', 28153),
(131212, 'itIT', '', 'Mi ha detto che stava per dimostrare che il Generale Jakra\'zet è nu traditore, ma nun mi ha più fatto sapere nulla.', 28153),
(131211, 'itIT', '', 'Cammina con me, ma cerchiamo di nun attirare l\'attenzione.', 28153),
(131210, 'itIT', 'Cosa puoi dirmi del Generale Jakra\'zet?', 'Cosa puoi dirmi del Generale Jakra\'zet?', 28153),
(131209, 'itIT', '', 'Cosa posso fare per te?', 28153),
(131208, 'itIT', 'Mi dispiace che siate stati trascinati in tutto chesto, ma se nun altro potrete incontrare Bwonsamdi, proprio chello che volevate! Eheheh!', '', 28153),
(131207, 'itIT', 'Eheheh, hai agito bene. L\'anima sua sarà n\'offerta degna per Bwonsamdi!', '', 28153),
(131206, 'itIT', 'Maledizione, mi hanno trovato! Ehi, aiutami e forse potrei restituire il favore tuo.', '', 28153),
(131205, 'itIT', 'Alle armi!', '', 28153),
(131204, 'itIT', '', 'Maresciallo, no!', 28153),
(131203, 'itIT', '$gLiberatelo:Liberatela;. Tu...', '', 28153),
(131202, 'itIT', '', 'Attenzione, continentale!', 28153),
(131201, 'itIT', 'Mace, Yorrick: dividetevi lungo il perimetro e cercate...', '', 28153),
(131200, 'itIT', '', 'Pensi che sia andata... laggiù?', 28153),
(131199, 'itIT', 'Non capisco! Il sentiero conduce da questa parte...', '', 28153),
(131198, 'itIT', 'Non c\'è via di uscita...', '', 28153),
(131197, 'itIT', '', 'Cosa... cos\'è questo posto?', 28153),
(131196, 'itIT', '<Sembra ci sia una struttura in lontananza. Dev\'essere il luogo dove era diretta Jaina!>', '', 28153),
(131195, 'itIT', 'Le bestie stanno impedendo il passaggio. Eliminale!', '', 28153),
(131194, 'itIT', 'Dobbiamo addentrarci ancora di più nella foresta! In formazione!', '', 28153),
(131193, 'itIT', 'Sembra magia del gelo... Jaina dev\'essere andata da questa parte.', '', 28153),
(131192, 'itIT', 'Maledizione! Dovremo continuare senza di lui... aspetta, cos\'è questo?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(131191, 'itIT', 'Signore! Non riusciamo a trovare Notley, ed è impossibile seguirne le tracce con questa tempesta!', '', 28153),
(131190, 'itIT', 'Questo... non promette nulla di buono.', '', 28153),
(131189, 'itIT', '', 'Ma cosa...', 28153),
(131188, 'itIT', 'Presto, sono andati in questa direzione!', '', 28153),
(131187, 'itIT', '', 'È un\'imboscata!', 28153),
(131186, 'itIT', 'Aaahhh!', '', 28153),
(131185, 'itIT', 'Notley, no!', '', 28153),
(131184, 'itIT', 'Aspetta... Credo di vedere qualcosa...', '', 28153),
(131183, 'itIT', 'Vieni, dobbiamo avanzare.', '', 28153),
(131182, 'itIT', 'Mi piacerebbe pensare che l\'abbiano fatto. No... c\'è sotto qualcosa di molto più oscuro.', '', 28153),
(131181, 'itIT', '', 'Sembra che questo bosco non sia infestato solamente dalle bestie. Pensi sia stato un esiliato a fare ciò?', 28153),
(131180, 'itIT', 'Altolà! Cosa succede?', '', 28153),
(131179, 'itIT', 'La cosa non promette bene...', '', 28153),
(131178, 'itIT', 'Le bestie stanno diventando sempre più aggressive e attaccano chiunque in campo aperto.', '', 28153),
(131177, 'itIT', 'Cos\'è stato? In guardia, uomini!', '', 28153),
(131176, 'itIT', 'A me!', '', 28153),
(131175, 'itIT', 'Armi pronte e nervi saldi, questa notte cavalcheremo nell\'oscurità.', '', 28153),
(131174, 'itIT', 'Le bestie di questi boschi non reagiscono bene a... be\', a tutto, in realtà.', '', 28153),
(131173, 'itIT', 'Questa tempesta limiterà il nostro raggio visivo, quindi state vicini e rimanete in gruppo.', '', 28153),
(131172, 'itIT', 'Sono pronto per l\'addestramento.', 'Sono pronta per l\'addestramento.', 28153),
(131171, 'itIT', 'Noi addestriamo bestie di tutte le forme e dimensioni. Anche chelle destinate a spostare pesi devono essere addestrate alla battaglia!', '', 28153),
(131170, 'itIT', 'Seguiremo la strada per Fine del Destino. È lì che si sarebbe diretta la carovana degli esiliati.', '', 28153),
(131169, 'itIT', '', 'Li spiriti... mi... abbandonano...', 28153),
(131168, 'itIT', '', 'Arghhh!!', 28153),
(131167, 'itIT', '', 'Nun posso... più...', 28153),
(131166, 'itIT', '', 'Nun ci sconfiggerete mai! Con l\'ultimo respiro mio, vi maledirò tutti quanti! Unitevi a me nell\'Aldilà!', 28153),
(131165, 'itIT', '', 'La connessione tra na bestia e il cavaliere suo è resa possibile da nu feticcio. Tocca la Pietra del Sauro nostra quando vuoi cominciare.', 28153),
(131158, 'itIT', 'Nel nome di Akunda, il grande Loa, ti do il benvenuto in questo tempio.', '', 28153),
(131148, 'itIT', '', 'Combatti bene. I cuccioli miei staranno al sicuro con te.', 28153),
(131142, 'itIT', '', 'I cuccioli miei meritano solo il meglio!', 28153),
(131115, 'itIT', 'Prendiamoli, ragazzi!', '', 28153),
(131114, 'itIT', 'Codardi! Manda il tuo campione migliore e vediamo di che pasta è fatto!', '', 28153),
(131113, 'itIT', 'Vediamo cos\'ha in serbo per noi quest\'Orda, che ne dici?', '', 28153),
(131112, 'itIT', '', 'Il sangue tuo scorrerà!', 28153),
(131111, 'itIT', '', 'Ti ho pigliato chesta volta, Hanzabu! Pagherai per la morte delle sorelle mie!', 28153),
(131109, 'itIT', 'Siamo alla ricerca del Loa, Bwonsamdi.', 'Siamo alla ricerca del Loa, Bwonsamdi.', 28153),
(131108, 'itIT', 'A quanto pare abbiamo superato il peggio, prendiamoci una pausa prima di continuare.', '', 28153),
(131107, 'itIT', 'Ben fatto, queste truppe saranno indispensabili per la nostra campagna.', '', 28153),
(131106, 'itIT', 'Prendetevi una pausa, soldati, presto riprenderemo la marcia.', '', 28153),
(131105, 'itIT', 'Soldati dell\'Alleanza! Difendete questo coraggioso convoglio mentre ci facciamo strada verso il Comando Avanzato!', '', 28153),
(131098, 'itIT', 'Chelli artigli... e le zanne... Terrò incubi per molto tempo a causa di tutto chesto.', 'Chelli artigli... e le zanne... Terrò incubi per molto tempo a causa di tutto chesto.', 28153),
(131097, 'itIT', 'Appena in tempo!', 'Appena in tempo!', 28153),
(131096, 'itIT', 'Nun credevo che ce l\'avrei fatta. Grazie!', 'Nun credevo che ce l\'avrei fatta. Grazie!', 28153),
(131094, 'itIT', 'I vestiti tuoi nun sono coperti di sporcizia e nun puzzi nemmeno per uno che gira per na palude.$b$bChi sei tu?', '', 28153),
(131093, 'itIT', 'Chi sei, viandante? Nun tieni l\'odore di nu Troll del Sangue.', '', 28153),
(131088, 'itIT', '', 'Sì! Sarà l\'ora del tè più bella di sempre! Andiamo a cercare gli altri ospiti.', 28153),
(131087, 'itIT', 'Cosa vuoi da Hanzabu?', '', 28153),
(131086, 'itIT', '', 'Nasone! Lo sai che la signora Mary non vuole che entri in casa! Lasci fango dappertutto!', 28153),
(131085, 'itIT', '', 'Oh, Signor Dino! Avevi fame, vero? Unisciti pure a noi, è l\'ora del tè.', 28153),
(131081, 'itIT', '', 'Cattivo Sindaco Striggs! Sempre a scappare dalle tue responsabilità verso la gente. Be\', ora non puoi più fuggire!', 28153),
(131080, 'itIT', '', 'Nun mi fido. Dovrem...', 28153),
(131079, 'itIT', 'Silenzio! Basta piagnucolare!', '', 28153),
(131078, 'itIT', '', 'Arghhh!', 28153),
(131077, 'itIT', 'Oh sì, chesto sarà nu premio prezioso assai!', '', 28153),
(131057, 'itIT', '$n ha difeso la Segheria!', '', 28153),
(131056, 'itIT', 'L\'Alleanza ha conquistato il Relitto!', '', 28153),
(131055, 'itIT', 'L\'Orda ha conquistato il Relitto!', '', 28153),
(131054, 'itIT', '$n ha attaccato il Relitto!', '', 28153),
(131049, 'itIT', 'L\'Orda ha posizionato un carro armato sulla strada per la Fortezza dei Custodi del Nord! Deve essere distrutto!', 'L\'Orda ha posizionato un carro armato sulla strada per la Fortezza dei Custodi del Nord! Deve essere distrutto!', 28153),
(131048, 'itIT', 'Scenario completato.', 'Scenario completato.', 28153),
(131033, 'itIT', '', 'Aprite una via per la VII Flotta! Noi procederemo quando arriveranno i rinforzi.', 28153),
(131032, 'itIT', 'Prova', '', 28153),
(131030, 'itIT', '', 'Guarda, cumpà! La traccia del mojo va verso nord, seguiamola.', 28153),
(131025, 'itIT', '', 'Che notizie porti dal nord?', 28153),
(131010, 'itIT', '', 'Mmm... sacrifici... e pure freschi. Il mojo residuo di chesto rituale ha lasciato na traccia. Vediamo dove conduce.', 28153),
(131009, 'itIT', '<Il corpo ha un piccolo pugnale conficcato nella schiena.>', '<Il corpo ha un piccolo pugnale conficcato nella schiena.>', 28153),
(131008, 'itIT', '', 'Sento na presenza potente a nord. Jamme a vedere di che si tratta.', 28153),
(131007, 'itIT', '', 'Chesta offerta nun stava accà quando sono arrivata in chesto posto. Sembra che Bwonsamdi tenga ancora nu seguace accà.', 28153),
(131000, 'itIT', '<Il duro clima di Nazmir ha intaccato parte delle scritte sulla tavoletta. Si riescono a leggere soltanto le parole \"pregare\", \"spirito\" e \"tomba\".>', '<Il duro clima di Nazmir ha intaccato parte delle scritte sulla tavoletta. Si riescono a leggere soltanto le parole \"pregare\", \"spirito\" e \"tomba\".>', 28153),
(130979, 'itIT', 'I nostri esploratori dicono che le forze dell\'Orda stanno avanzando verso i Custodi del Nord sfruttando la copertura della notte. Abbiamo immediatamente bisogno del tuo aiuto!', '', 28153),
(130978, 'itIT', '', 'Soldati dell\'Alleanza! È il vostro momento! Il nostro assalto alla Grande Palizzata di Mulgore inizia ora. Rimanete vicini e combattete con onore.', 28153),
(130977, 'itIT', '', 'Tutti al porto!', 28153),
(130969, 'itIT', '', 'Ah, stai accà. Proprio come aveva previsto G\'huun. Ci sarà da divertirsi!', 28153),
(130967, 'itIT', '', 'Soldati della VII Flotta, il momento del nostro assalto è quasi arrivato. Recuperate le vostre cose e preparatevi a muovervi.', 28153),
(130947, 'itIT', 'Non vedi che sto morendo di fame?', '', 28153),
(130946, 'itIT', 'Mamma, ho fameee!!!', '', 28153),
(130945, 'itIT', '<%s ti tira una testata amichevole>', '', 28153),
(130944, 'itIT', '', 'La morte mia nun sarà la fine.', 28153),
(130943, 'itIT', 'Facciamo un gioco? Tu corri e io cerco di prenderti e mangiarti!', '', 28153),
(130940, 'itIT', '<%s ti guarda lamentosamente.>', '', 28153),
(130939, 'itIT', '<%s si lamenta affamato.>', '', 28153),
(130938, 'itIT', '<%s si lamenta e ti fiuta insistentemente.>', '', 28153),
(130937, 'itIT', '<Lo stomaco di %s brontola rumorosamente.>', '', 28153),
(130936, 'itIT', '<%s ti si strofina addosso calorosamente.>', '', 28153),
(130935, 'itIT', '', 'Nun potete sconfiggerci tutti! Dazar\'alor cadrà!', 28153),
(130934, 'itIT', 'Io porterò via i feriti. Incontriamoci a Raz\'lotec quando avrai finito e metteremo fine a chesto assedio.', '', 28153),
(130932, 'itIT', 'Schiusura', 'Schiusura', 28153),
(130931, 'itIT', '', 'Ti sventro!', 28153),
(130930, 'itIT', '', 'Ti spellerò!', 28153),
(130929, 'itIT', '', 'Altro sangue! Altro sangue!', 28153),
(130928, 'itIT', '', 'Ma\'ma ha bisogno del sangue tuo.', 28153),
(130927, 'itIT', '', 'Belle ossa.', 28153),
(130926, 'itIT', '', 'Carne fresca, sangue a fiotti.', 28153),
(130925, 'itIT', 'Urgh, ci vorrà na settimana perché chesti tagli si rimarginino.', 'Urgh, ci vorrà na settimana perché chesti tagli si rimarginino.', 28153),
(130924, 'itIT', 'Maledetti Troll del Sangue!', 'Maledetti Troll del Sangue!', 28153),
(130923, 'itIT', 'Ah! Nun piglierete il sangue mio oggi.', 'Ah! Nun piglierete il sangue mio oggi.', 28153),
(130922, 'itIT', 'Dicevano di voler usare il sangue mio in qualche modo.', 'Dicevano di voler usare il sangue mio in qualche modo.', 28153),
(130921, 'itIT', 'Ah! Nun mi avrete oggi, branco di selvaggi!', 'Ah! Nun mi avrete oggi, branco di selvaggi!', 28153),
(130920, 'itIT', 'Stavano per cominciare nu rituale. Sentivo le ossa mie muoversi sottopelle.', 'Stavano per cominciare nu rituale. Sentivo le ossa mie muoversi sottopelle.', 28153),
(130919, 'itIT', 'Stavano incidendo dei simboli nel braccio mio. Selvaggi.', 'Stavano incidendo dei simboli nel braccio mio. Selvaggi.', 28153),
(130918, 'itIT', 'Sì! Nun piglierete la vita di chesto Troll oggi.', 'Sì! Nun piglierete la vita di chesta Troll oggi.', 28153),
(130917, 'itIT', 'Grazie! Grazie mille.', 'Grazie! Grazie mille.', 28153),
(130915, 'itIT', 'Cessate il fuoco. Ecco i rinforzi nostri!', '', 28153),
(130914, 'itIT', '', 'Andiamo, cumpà, è il momento di cacciare!', 28153),
(130913, 'itIT', '', 'Vieni! La schiusa avverrà a breve.', 28153),
(130907, 'itIT', 'Sono pronta.', 'Sono pronta.', 28153),
(130906, 'itIT', '', '$GBenvenuto:Benvenuta; al Kraal delle Bestie da Guerra, $n.\n\nHo sentito parlare dell\'Orda e so che state accà per fare nu patto con il vecchio Rastakhan.\n\nVedremo se ci sarete utili. Nel caso, lo faremo sapere ai piani alti di Dazar, eh?', 28153),
(130905, 'itIT', 'Se trovo chi ti ha fatto chesto, vecchio mio...', '', 28153),
(130904, 'itIT', 'I Troll del Sangue giocano sporco.', '', 28153),
(130903, 'itIT', 'Magia oscura. Chesto nun è naturale.', '', 28153),
(130902, 'itIT', 'Con che maledizione ti hanno afflitto, vecchio mio?', '', 28153),
(130901, 'itIT', 'Forza, vecchio mio. Ce la puoi fare.', '', 28153),
(130900, 'itIT', 'Restate in formazione! Riportate indietro feriti e schiattati, ma restate in formazione.', '', 28153),
(130899, 'itIT', 'State accuort\'! Altri Volatili Ventrerosso arrivano dal cielo!', '', 28153),
(130898, 'itIT', 'Siete Zandalari, combattete come tali!', '', 28153),
(130897, 'itIT', 'Aiutate chel ferito a rialzarsi! Nun lasciate nessuno a chesti selvaggi.', '', 28153),
(130896, 'itIT', 'Resistete, cumpà! Nun cadremo contro chesti selvaggi chest\'oggi!', '', 28153),
(130842, 'itIT', 'Dai a tutti un beneficio.', 'Dai a tutti un beneficio.', 28153),
(130841, 'itIT', '', 'Forse sei più forte di quanto sembri. Il campione mio nun ci andrà leggero con te. Sfidalo quando vuoi.', 28153),
(130840, 'itIT', '', 'Nun mi aspettavo che nu novizio sarebbe stato na sfida. Vediamo come te la cavi contro nu rivale più potente.', 28153),
(130839, 'itIT', 'Posso aiutarti fornendoti il supporto di molti benefici sul Fronte di Guerra.', '', 28153),
(130838, 'itIT', '', 'Tieni la certezza di voler affrontare chesto impegno? Nun è ancora troppo tardi per rinunciare.', 28153),
(130822, 'itIT', 'Nuovi Generali stanno per essere promossi!', 'Nuovi Generali stanno per essere promossi!', 28153),
(130797, 'itIT', '', 'Apprezzo la determinazione tua. È giunta l\'ora di incontrare la Matriarca Jaz\'lith. Vieni.', 28153),
(130796, 'itIT', '', 'Lo sai che dovrai mettere le necessità del cucciolo tuo prima delle tue? Tieni n\'idea di quanto mangino?', 28153),
(130795, 'itIT', 'Il legame con le bestie nostre comincia alla schiusa delle uova e dura tutta la vita. Sono la famiglia nostra.', 'Il legame con le bestie nostre comincia alla schiusa delle uova e dura tutta la vita. Sono la famiglia nostra.', 28153),
(130794, 'itIT', '', 'I cornofurente sono erbivori, per cui nun provare a dar loro della carne!', 28153),
(130793, 'itIT', 'I cuccioli sono molto scrupolosi nello scegliere con chi legarsi. È nu mistero che sia $gstato scelto nu straniero:stata scelta na straniera;!', 'I cuccioli sono molto scrupolosi nello scegliere con chi legarsi. È nu mistero che sia $gstato scelto nu straniero:stata scelta na straniera;!', 28153),
(130732, 'itIT', '', 'Ah, Hir\'eek, il Loa Pipistrello... sta da qualche parte a Nazmir. È astuto... Potrebbe sapere come fermare tutto chesto.', 28153),
(130731, 'itIT', '', 'Sento il potere suo... è vicino. Più vicino delli altri Loa.', 28153),
(130730, 'itIT', '', 'Bwonsamdi... il Loa della Morte. Anche lui è nu Loa potente, ma scaltro e pericoloso... sempre pronto a stringere patti.', 28153),
(130710, 'itIT', '', 'Il Loa Rana, Krag\'wa... è a Nazmir! È nu potente Loa che nun tollererà la malvagità dei Troll del Sangue.', 28153),
(130707, 'itIT', 'Quindi stringeremo nu patto col Loa della Morte, il Loa Tartaruga, il Loa Pipistrello e il Loa Rana... tutto per fermare i Troll del Sangue.', '', 28153),
(130705, 'itIT', '', 'Ci serve più potere per fermare i Troll del Sangue. Nun teniamo altra scelta: i Loa di Nazmir.', 28153),
(130692, 'itIT', '', '<Ti squadra... in modo suggestivo.>', 28153),
(130625, 'itIT', '', 'Talanji talks about wrangling limited support from contacts in Zuldazar while the player seeks the aid of forgotten loa.', 28153),
(130566, 'itIT', '', 'COOL CUTSCENE/FLYOVER. You see the corrupt titan superconstruct! The Blood Matriarch notices you and casts a capturing spell on Talanji!', 28153),
(130494, 'itIT', '', 'Finalmente libera! Dobbiamo muoverci, jamme!', 28153),
(130490, 'itIT', '', 'Altri corpi dei soldati miei. Dovremo seguire la scia di morte.', 28153),
(130485, 'itIT', '', 'La gente mia... massacrata! Mo\' hai visto il male contro cui combattiamo... I Troll del Sangue sono dei mostri.', 28153),
(130383, 'itIT', '', 'I consigli tuoi sono saggi, Rokhan, ma bisogna agire in fretta. Chesti Troll del Sangue devono essere fermati.', 28153),
(130372, 'itIT', '', 'Sii veloce e letale. Zul e io ti aspetteremo alle scale della piramide. Nun puoi sbagliare.', 28153),
(130361, 'itIT', '', 'Se sopravvivi, raggiungici all\'entrata della Via del Barile. Potrei tenere nu lavoro per te.', 28153),
(130353, 'itIT', 'Nun avevo mai messo piede a Zandalar prima d\'ora. Zuldazar è ancora più grandiosa di quanto credessi.$b$bGuardati le spalle, cumpà: li Zandalari potranno anche sembrare gentili, ma sono sempre Troll. La società nostra è implacabile con coloro che paiono deboli.', '', 28153),
(130352, 'itIT', 'La Principessa Talanji ti attende alla fine di chesti moli. Nun perdere tempo e nun entrare nella città prima che i rituali sul dolore della morte nun saranno stati eseguiti.\n\nI cadaveri parlanti resteranno accà fin quando il Re nun dirà il contrario.', '', 28153),
(130121, 'itIT', '', 'Come desideri.', 28153),
(130120, 'itIT', 'Risponderai direttamente a lei dei tuoi crimini contro Kul Tiras.', '', 28153),
(130119, 'itIT', 'Ti porteremo immediatamente da Katherine.', '', 28153),
(130099, 'itIT', '<Short talky moment where I laugh at Zul and demean him, tell my daughter she abandoned her post>', '', 28153),
(130096, 'itIT', 'Devi sapere che il Re nostro è sopravvissuto a centoventitré tentativi di assassinio.$b$bLe cape di coloro che hanno provato ad acciderlo mo\' decorano la sala del trono sua.', '', 28153),
(130081, 'itIT', '', 'Desideri vedere il Re? Bene, suona il gong e ti presenteremo na degna sfida.', 28153),
(130079, 'itIT', '', 'Prendi la benedizione tua e vattene. Se tornerai, la tua vita avrà fine.', 28153),
(130075, 'itIT', '', 'Come sta il vecchio Vol\'jin? Schiattato, ho sentito. Ah, peccato. Alcuni di noi sognavano di acciderlo con le mani loro.', 28153),
(130032, 'itIT', 'Parla velocemente e vattene, $R. Li Amani nun dimenticheranno mai che è stata l\'Orda tua a uccidere il nostro amato Zul\'jin.\n\nCome cortesia verso li Zandalari, ti darò chesto avvertimento: stai nel territorio Amani. Resta accà e verrai seppellito in chesto luogo.', '', 28153),
(130031, 'itIT', 'Piglia la benedizione tua e vattene. Nun ci sta posto per la feccia dell\'Orda come te tra li Amani.', '', 28153),
(130030, 'itIT', 'Audace, cumpà. Ma nun penso tu abbia capito in cosa ti sei $gcacciato:cacciata;. Sconfiggi tutti quanti i discepoli e potrai andartene con la benedizione nostra.', '', 28153),
(130003, 'itIT', '', '.', 28153),
(129998, 'itIT', '', 'Sono Jaina Marefiero. Sono qui per un\'udienza con l\'Ammiraglio Supremo Katherine Marefiero... mia madre.', 28153),
(129993, 'itIT', '', 'Spero che funzioni.', 28153),
(129983, 'itIT', 'Ah! No! Gahz\'ragon! Insensibile feccia dell\'Orda! Piglia la benedizione tua e vattene.', '', 28153),
(129980, 'itIT', 'Molto è cambiato in tua assenza, maestà. Rakera si è dimostrata debole assai per la posizione sua, così mi sono assicurato che venisse esiliata a Vol\'dun.', '', 28153),
(129979, 'itIT', '', 'Jakra\'zet. Dove sta la Guardia da Guerra Rakera?', 28153),
(129978, 'itIT', 'Basta così, feccia dell\'Orda.', '', 28153),
(129969, 'itIT', '[Loading screen -> IGC - Ship on open water, Jaina\'s nightmare, arrival at Boralus gates.]', '[Loading screen -> IGC - Ship on open water, Jaina\'s nightmare, arrival at Boralus gates.]', 28153),
(129968, 'itIT', 'Vuoi affrontare la sfida nostra? Te la sei meritata. Suona il gong laggiù e pigliati tutta quanta la sfida nostra.', '', 28153),
(129967, 'itIT', '<Lancia la sfida>', '<Lancia la sfida>', 28153),
(129966, 'itIT', 'Ehi, salve $R. La gente tua ha causato tanti guai alla mia in passato. Che cosa vuoi?', '', 28153),
(129965, 'itIT', 'L\'Alleanza nun tollererà tutto chesto!', 'L\'Alleanza nun tollererà tutto chesto!', 28153),
(129964, 'itIT', 'Il re nostro ne sarà informato!', 'Il re nostro ne sarà informato!', 28153),
(129963, 'itIT', 'Hai vinto chesta volta.', 'Hai vinto chesta volta.', 28153),
(129962, 'itIT', 'Nun terrete chesta terra per sempre.', 'Nun terrete chesta terra per sempre.', 28153),
(129961, 'itIT', 'Torneremo!', 'Torneremo!', 28153),
(129960, 'itIT', 'Nun sarà l\'ultima volta che senti parlare di noi, $p!', 'Nun sarà l\'ultima volta che senti parlare di noi, $p!', 28153),
(129959, 'itIT', '$C fetente!', '$C fetente!', 28153),
(129958, 'itIT', 'Muori!', 'Muori!', 28153),
(129957, 'itIT', 'Ho sentito parlare di te, $p! La morte tua mi renderà n\'eroe!', 'Ho sentito parlare di te, $p! La morte tua mi renderà n\'eroina!', 28153),
(129956, 'itIT', 'Nun me ne vado finché ancora respiri.', 'Nun me ne vado finché ancora respiri.', 28153),
(129955, 'itIT', 'Li Zandalari nun possono allearsi con te, se sei $gschiattato:schiattata;.', 'Li Zandalari nun possono allearsi con te, se sei $gschiattato:schiattata;.', 28153),
(129954, 'itIT', 'Nun ti libererai di me così facilmente!', 'Nun ti libererai di me così facilmente!', 28153),
(129953, 'itIT', 'Feccia dell\'Orda!', 'Feccia dell\'Orda!', 28153),
(129952, 'itIT', 'Nessuna feccia dell\'Orda si unirà alli Zandalari.', 'Nessuna feccia dell\'Orda si unirà alli Zandalari.', 28153),
(129951, 'itIT', 'Per ordine della principessa, andrai in esilio. Vattene o muori.', 'Per ordine della principessa, andrai in esilio. Vattene o muori.', 28153),
(129950, 'itIT', 'Nun toccarmi, feccia dell\'Orda.', 'Nun toccarmi, feccia dell\'Orda.', 28153),
(129949, 'itIT', 'Bene bene bene, nu membro dell\'Orda accà a Zuldazar, molto interessante.', 'Bene bene bene, nu membro dell\'Orda accà a Zuldazar, molto interessante.', 28153),
(129948, 'itIT', 'Anche tu vuoi chesta cosa? L\'ho vista prima io e voglio pigliarla, quindi fatti da parte.', 'Anche tu vuoi chesta cosa? L\'ho vista prima io e voglio pigliarla, quindi fatti da parte.', 28153),
(129947, 'itIT', 'Cosa vuoi? Tengo da fare.', 'Cosa vuoi? Tengo da fare.', 28153),
(129946, 'itIT', 'Che c\'è, feccia dell\'Orda?', 'Che c\'è, feccia dell\'Orda?', 28153),
(129944, 'itIT', '', 'Devo preparare la mia nave. Incontriamoci al porto quando sarà ora di partire.', 28153),
(129940, 'itIT', 'Guarda, io tengo na regola sola: se vuoi combattere, fallo all\'esterno.\n\nSeguila e potrai dormire accà.\n\nOh, e nun lamentarti con me se vedi qualcosa di strano.', '', 28153),
(129883, 'itIT', 'Ai viandanti non è permesso entrare a Zuldazar senza che io abbia assaggiato la loro carne!', '', 28153),
(129881, 'itIT', 'Va\', mortale. Di\' alla figlia di Rastakhan che ti concedo il permesso di entrare nella città.', '', 28153),
(129880, 'itIT', 'Vorrei entrare nella città.', 'Vorrei entrare nella città.', 28153),
(129879, 'itIT', 'Odori di qualcosa di nuovo e provato dalla guerra. Una preda stuzzicante. Perché sei qui di fronte a me?', '', 28153),
(129660, 'itIT', 'È in corso un urgente concilio di guerra. La tua presenza è richiesta al Forte di Roccavento.', '', 28153),
(128197, 'itIT', 'Ritorno dalle profondità!', '', 28153),
(128196, 'itIT', 'A quanto pare siamo arrivati! Noi penseremo ad attivare il rilevatore, mentre voi vi ambientate sull\'isola.', '', 28153),
(128195, 'itIT', 'Qui, peoni. Aspettate, sento il tipico fetore degli UMANI. Umani, mi sentite? Quest\'isola appartiene a Burgthok!', '', 28153),
(127581, 'itIT', 'Uooo, questo clima non è normale. L\'Azerite deve aver attirato le attenzioni di un Signore Elementale. Fate attenzione. O uccidetelo. O entrambe le cose!', '', 28153),
(127580, 'itIT', '', 'Mando subito dei lavoratori a estrarre quell\'Azerite.', 28153),
(127579, 'itIT', '$n, i nostri esploratori hanno scovato diverse isole colme d\'Azerite. Ci serve la tua nave immediatamente.', '', 28153),
(127578, 'itIT', 'Alleanza! La Luce ci ha donato quest\'isola. Andatevene, prima che scorra del sangue. Questo è l\'ultimo avvertimento.', '', 28153),
(127577, 'itIT', '', 'Bottini e razzie, ahah! Dorp, colpisci qualunque cosa si muova. Pete, trova quella feccia dell\'Alleanza e mostragli cosa succede a quelli come loro. E prendete quell\'Azerite!', 28153),
(127576, 'itIT', 'Ehi $gamico:amica;, abbiamo della bella roba.', '', 28153),
(127575, 'itIT', '', 'I tuoi alleati Forgialuce sono qui per aiutare!', 28153),
(127574, 'itIT', 'Ci sono delle navi dell\'Orda in arrivo. Forse vi conviene sveltire un po\' le operazioni.', '', 28153),
(127573, 'itIT', 'Sì? Abbiamo i nostri ordini e l\'Azerite sta aspettando, dai un\'occhiata al tavolo e fammi sapere quando sei $gpronto:pronta; a partire.\n\nLo so, è difficile non ammirare il mio fascino, me lo dicono tutti, ma cerca di concentrarti.', '', 28153),
(127569, 'itIT', 'Reimposta l\'isola attuale.', 'Reimposta l\'isola attuale.', 28153),
(127568, 'itIT', 'Squadra, siamo a metà dell\'opera. Non deludetemi.', '', 28153),
(127501, 'itIT', 'Voi salva Barbagruggo! Ho molti sbrilli da dare a voi!', '', 28153),
(126508, 'itIT', '|cFF0EA6DC+$1i|r |cFFFFFF00Azerite|r', '|cFF0EA6DC+$1i|r |cFFFFFF00Azerite|r', 28153),
(124726, 'itIT', 'Decifra le regole', 'Decifra le regole', 28153),
(124724, 'itIT', 'Reimposta il gioco', 'Reimposta il gioco', 28153),
(124723, 'itIT', 'Inizia il gioco', 'Inizia il gioco', 28153),
(124717, 'itIT', '------------------------------$bDIFFICOLTÀ MASSIMA$b------------------------------$b\nLa console emette strani rumori mentre posizioni la tua mano sopra di essa. Lo schermo centrale si illumina con un\'infinita cascata di glifi, teschi e volti con delle X sopra gli occhi. Il tempo aggiuntivo è disponibile a questa difficoltà, ma uno dei temporizzatori nasconde una trappola.$b$bDella musica allegra emana dagli altoparlanti. La console ti sta forse augurando buona fortuna... o ti sta dicendo addio?', '', 28153),
(124716, 'itIT', '---------------$b   LIVELLO 4$b---------------$b\nLa console risponde al tuo tocco familiare, illuminandosi in una serie di forme esagonali ed eseguendo una musica allegra.$b$bÈ difficile interpretare gli antichi simboli che scorrono sullo schermo, ma a quanto pare la maggior parte di chi tenta di superare questo livello di difficoltà rimane brutalmente ucciso.$b$bLa buona notizia è che è disponibile del tempo aggiuntivo.', '', 28153),
(124715, 'itIT', '---------------$b   LIVELLO 3$b---------------$b\nLa console ti accoglie caldamente, nonostante i suoi continui tentativi di assassinarti.$b$bI simboli relativi al prossimo livello della sfida sembrano indicare che dovresti aspettarti meno indizi, meno tempo e più trappole.', '', 28153),
(124714, 'itIT', '---------------$b   LIVELLO 2$b---------------$b\nLa console emette dei suoni, riconoscendoti al tocco della tua mano. Le regole sembrano essere cambiate e i disegni ora indicano la presenza di un temporizzatore.$b$bLa penalità per non riuscire a completare il rompicapo in tempo sembrerebbe essere solo dolore anziché morte.', '', 28153),
(124713, 'itIT', 'Fai del tuo meglio per interpretare i pittogrammi e ignorare gli avvertimenti su una possibile morte istantanea.$b$bLa console di Mago Minato genererà una griglia esagonale, sensibile ai passi. Molti esagoni sono \"minati\" e distruggeranno il giocatore. Al contrario, camminare su una piattaforma \"sicura\" rivelerà il numero delle mine adiacenti.$b$bL\'obiettivo è \"ripulire\" il campo rivelando tutte le piattaforme sicure ed evidenziando quelle pericolose con le piccole bandiere fornite.$b$bNon è chiaro per quale motivo il gioco abbia necessità di uccidere chiunque sbagli.', '', 28153),
(124711, 'itIT', '---------------$b   LIVELLO 1$b---------------$b\nQuesta misteriosa console arcana si illumina al tocco della tua mano. Pagine e pagine di istruzioni appaiono sul pannello centrale. Il linguaggio non è chiaro, ma i disegni sono inequivocabili:$bun sacco di teschi.$b$bQuesto è Mago Minato, un pericolosissimo gioco in cui bisogna attraversare un campo minato arcano e identificare tutte le trappole nascoste. Il più piccolo errore porterebbe a morte certa.$b$bTi domandi come qualcuno potrebbe mai trovarlo divertente.', '', 28153),
(124677, 'itIT', 'LIVELLO 5', '', 28153),
(124676, 'itIT', 'LIVELLO 4', '', 28153),
(124675, 'itIT', 'LIVELLO 3', '', 28153),
(124674, 'itIT', 'LIVELLO 2', '', 28153),
(124673, 'itIT', 'LIVELLO 1', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(167308, 'koKR', 'I want to teleport to Waycrest Manor (Dungeon).', 'I want to teleport to Waycrest Manor (Dungeon).', 28153),
(167307, 'koKR', 'I want to teleport to Tol Dagor (Dungeon).', 'I want to teleport to Tol Dagor (Dungeon).', 28153),
(167306, 'koKR', 'I want to teleport to The Underrot (Dungeon).', 'I want to teleport to The Underrot (Dungeon).', 28153),
(167305, 'koKR', 'I want to teleport to  The MOTHERLODE!! (Dungeon).', 'I want to teleport to  The MOTHERLODE!! (Dungeon).', 28153),
(167304, 'koKR', 'I want to teleport to Temple of Sethraliss (Dungeon).', 'I want to teleport to Temple of Sethraliss (Dungeon).', 28153),
(167302, 'koKR', 'I want to teleport to Siege of Boralus (Dungeon).', 'I want to teleport to Siege of Boralus (Dungeon).', 28153),
(167301, 'koKR', 'I want to teleport to Shrine of the Storm (Dungeon).', 'I want to teleport to Shrine of the Storm (Dungeon).', 28153),
(167300, 'koKR', 'I want to teleport to Kings\' Rest (Dungeon).', 'I want to teleport to Kings\' Rest (Dungeon).', 28153),
(167299, 'koKR', 'I want to teleport to Freehold (Dungeon).', 'I want to teleport to Freehold (Dungeon).', 28153),
(167298, 'koKR', 'I want to teleport to Atal\'dazar (Dungeon).', 'I want to teleport to Atal\'dazar (Dungeon).', 28153),
(167297, 'koKR', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 28153),
(167296, 'koKR', '', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 28153),
(162171, 'koKR', '어둠괴철로 도시', '어둠괴철로 도시', 28153),
(162170, 'koKR', '의무를 저버려선 안 됩니다, 다르나서스로 돌아가야 합니다!', '의무를 저버려선 안 됩니다, 다르나서스로 돌아가야 합니다!', 28153),
(162169, 'koKR', '', '이제 모든 일을 마칠 각오는 되었나, $n?', 28153),
(162168, 'koKR', '<달라란으로 비행합니다.>', '<달라란으로 비행합니다.>', 28153),
(162167, 'koKR', '로가 모든 상점에 들른 다음 여관에 가도록 인도해 주십시오. 단, 로가 갔던 길이 서로 겹치면 안 됩니다.', '', 28153),
(162166, 'koKR', '', '아기 거북이들이 바다에 무사히 들어갈 수 있도록 호위할 준비가 되셨습니까?', 28153),
(162165, 'koKR', '준비됐습니다.', '준비됐습니다.', 28153),
(162164, 'koKR', '환영합니다, $n|1이여;여;. 자신의 예리함을 시험할 수 있는 껍질 놀이에 참여해 보겠습니까?', '', 28153),
(162161, 'koKR', '어둠해안 도입부를 건너뛰시겠습니까?', '어둠해안 도입부를 건너뛰시겠습니까?', 28153),
(162160, 'koKR', '무슨 일입니까, $n 님? 신경 쓰이는 것이라도 있으신지...', '', 28153),
(162159, 'koKR', '<표류하는 선원이 당신을 무섭게 쳐다봅니다. 여기 있으면 안 될 것 같습니다.>', '<표류하는 선원이 당신을 무섭게 쳐다봅니다. 여기 있으면 안 될 것 같습니다.>', 28153),
(162158, 'koKR', '이 이야기는 전에 들어 본 적이 있어요... <도입부를 건너뛰고 어둠해안에서 모험을 시작합니다.>', '이 이야기는 전에 들었습니다... <시나리오를 건너뛰고 다음 임무를 시작합니다.>', 28153),
(162157, 'koKR', '안전한 장소로 돌려보내 주마, $n. 꽉 잡아라!', '', 28153),
(162156, 'koKR', '자연의 격노가 벌할지니!', '', 28153),
(162155, 'koKR', '가지에 꽉 매달려라, $c.', '', 28153),
(162152, 'koKR', '아제라이트가 얼라이언스의 손에 넘어가서는 안 됩니다!', '아제라이트가 얼라이언스의 손에 넘어가서는 안 됩니다!', 28153),
(162151, 'koKR', '|TInterface\\Icons\\Ability_Earthen_Pillar.blp:20|t$n|1이;가; |cFFF00000|Hspell:260551|h[영혼 가시]|h|r에 갇혔습니다!', '', 28153),
(162150, 'koKR', '쿨 티라스 해군을 돕고 싶습니다. <프라우드무어 해군과의 평판을 약간 우호적으로 설정합니다.>', '쿨 티라스 해군을 돕고 싶습니다. <프라우드무어 해군과의 평판을 약간 우호적으로 설정합니다.>', 28153),
(162149, 'koKR', '당신이 최고야, $n!', '당신이 최고야, $n!', 28153),
(162148, 'koKR', '$n 세상에서 제일 멋지다!', '$n 세상에서 제일 멋지다!', 28153),
(162147, 'koKR', '멋지다!', '멋지다!', 28153),
(162146, 'koKR', '워후!', '워후!', 28153),
(162145, 'koKR', '$n! $n! $n!', '$n! $n! $n!', 28153),
(162144, 'koKR', '$n|1이다;다;! $n|1이가;가; 무대에 올랐어!', '$n|1이다;다;! $n|1이가;가; 무대에 올랐어!', 28153),
(162143, 'koKR', '$n 최고! 워후!', '$n 최고! 워후!', 28153),
(162142, 'koKR', '$n 최고!', '$n 최고!', 28153),
(162141, 'koKR', '내 가열로는 언제나 준비되어 있네, $n.', '내 가열로는 언제나 준비되어 있네, $n.', 28153),
(162140, 'koKR', '수중에 있는 식량을 모으고 잠자리를 마련해 두겠습니다. 록타르 오가르!', '여기는 비록 작은 전초기지이지만, 가진 걸 최대한 모아보겠습니다. 대족장님과 병사들에게 모자란 것이 없도록 단단히 준비하겠습니다! 록타르 오가르!', 28153),
(162139, 'koKR', '여기 조람가르에 만반의 준비를 해두겠네. 호드를 위하여!', '여기 조람가르에 만반의 준비를 해두겠네. 호드를 위하여!', 28153),
(162138, 'koKR', '대족장 실바나스 윈드러너 님이 병사들의 무기를 수리하는 데 당신의 도움이 필요합니다.', '대족장 실바나스 윈드러너 님이 병사들의 무기를 수리하는 데 당신의 도움이 필요합니다.', 28153),
(162137, 'koKR', '', '근처의 비밀 통로를 이용하면 저택의 응접실로 돌아갈 수 있을 거예요.', 28153),
(162135, 'koKR', '황혼의 계곡으로 돌아갑니다!', '', 28153),
(162134, 'koKR', '', '다 벼려버려! 검은무쇠 부족이여 실력을 보여 주세요!', 28153),
(162133, 'koKR', '', '와서 내 마음의 불도 지펴 줘요! 검은무쇠 드워프를 환호와 함께 맞아 줍시다!', 28153),
(162132, 'koKR', '', '이 세상 안무가 아니다! 마그하르 오크를 박수로 맞아 주세요!', 28153),
(162131, 'koKR', '', '마그하르 오크를 무대 위로 모셔보겠습니다!', 28153),
(162130, 'koKR', '선택할 수 있는 연구를 보여 주십시오.', '선택할 수 있는 연구를 보여 주십시오.', 28153),
(162129, 'koKR', '성난굽이 강으로 돌아갑니다!', '', 28153),
(162128, 'koKR', '지배자의 고대검으로 돌아갑니다!', '', 28153),
(162127, 'koKR', '', '일을 제대로 수행하려면... 큰 폭탄을 써야하는 법!', 28153),
(162123, 'koKR', '$n|1이;가; 푸짐한 선장의 잔칫상을 준비합니다!', '$n|1이;가; 푸짐한 선장의 잔칫상을 준비합니다!', 28153),
(162122, 'koKR', '$n|1이;가; 선박의 연회를 준비합니다!', '$n|1이;가; 선박의 연회를 준비합니다!', 28153),
(162121, 'koKR', '정말 로데론 전투를 건너뛰시겠습니까?', '정말 로데론 전투를 건너뛰시겠습니까?', 28153),
(162120, 'koKR', '이 이야기는 전에 들었습니다... <시나리오를 건너뛰고 다음 임무를 시작합니다.>', '이 이야기는 전에 들었습니다... <시나리오를 건너뛰고 다음 임무를 시작합니다.>', 28153),
(162119, 'koKR', '', '자매들이여, 저와 함께 갑시다! 호드로부터 우리의 땅을 지켜야 합니다!', 28153),
(162118, 'koKR', '', '어둠해안이 공격받고 있습니다! 대여사제님께 즉시 이 사실을 알리십시오!', 28153),
(162117, 'koKR', '우리의 숲 동맹들을 결집하십시오! 세계수를 반드시 지켜야 합니다!', '', 28153),
(162116, 'koKR', '어둠해안이 공격받고 있습니다! 어서 가서 우리의 숲을 보호해야 합니다!', '', 28153),
(162110, 'koKR', '장군 그레보를 처리해야 합니다.', '장군 그레보를 처리해야 합니다.', 28153),
(162109, 'koKR', '반갑네.', '', 28153),
(162108, 'koKR', '호드의 진군이 성난굽이 강에서 멈췄습니다! 즉시 놈들을 몰아내야 합니다!', '호드의 진군이 성난굽이 강에서 멈췄습니다! 즉시 놈들을 몰아내야 합니다!', 28153),
(162107, 'koKR', '전쟁의 북이 온 숲에 메아리치는 소리가 들립니다. 발톱의 드루이드는 이 땅을 파괴하려는 자들을 막을 준비가 되었습니다!', '', 28153),
(162106, 'koKR', '이런 힘이라니!', '', 28153),
(162105, 'koKR', '좋아, 완벽하네. 딱 필요한 걸세. 오래 기다릴 필요 없네.', '', 28153),
(162104, 'koKR', '느껴지네. 파편이 힘으로 진동하는군! 정말이지... 아름다워, 무섭기도 하지만.', '', 28153),
(162103, 'koKR', '', '정말 오랜 시간이 걸렸다. 드디어 검은무쇠 부족이 산 밖으로 나와 당당히 얼라이언스에 자리를 잡게 됐군.', 28153),
(162102, 'koKR', '이보게, 이들이 스톰윈드 거리에서 전차를 몰고 다니게 허락할 것 같나?', '', 28153),
(162101, 'koKR', '다른 얼라이언스도 새롭게 생긴 불타는 골목에 익숙해져야 할 걸세!', '', 28153),
(162100, 'koKR', '스톰윈드에서 다른 드워프들이 날 바라보는 눈길이 영 마음에 안 들어.', '스톰윈드에서 다른 드워프들이 날 바라보는 눈길이 영 마음에 안 들어.', 28153),
(162099, 'koKR', '지상은 쓸 데 없이 눈부시다고.', '지상은 쓸 데 없이 눈부시다고.', 28153),
(162098, 'koKR', '검댕 안 묻은 집을 어떻게 집이라고 부를 수 있겠나.', '검댕 안 묻은 집을 어떻게 집이라고 부를 수 있겠나.', 28153),
(162097, 'koKR', '검은바위의 불길은 얼라이언스를 위해 타오른다네!', '검은바위의 불길은 얼라이언스를 위해 타오른다네!', 28153),
(162096, 'koKR', '스패너 하나에 팔힘만 있으면 못 고칠 게 없지.', '스패너 하나에 팔힘만 있으면 못 고칠 게 없지.', 28153),
(162095, 'koKR', '검은무쇠 부족만이 진정한 드워프지. 나머지 부족은 너무 물러 터졌다고!', '검은무쇠 부족만이 진정한 드워프지. 나머지 부족은 너무 물러 터졌다고!', 28153),
(162094, 'koKR', '우린 산의 진정한 힘이라네.', '우린 산의 진정한 힘이라네.', 28153),
(162093, 'koKR', '왜 이쪽으로 오는 건가? 조심하라고... 난 인내심이 부족하거든!', '왜 이쪽으로 오는 건가? 조심하라고... 난 인내심이 부족하거든!', 28153),
(162089, 'koKR', '이곳을 떠나라!', '', 28153),
(162088, 'koKR', '꺼져라! 너희를 이곳으로 부른 적 없다!', '', 28153),
(162087, 'koKR', '우리 보금자리 못 가져간다!', '', 28153),
(162086, 'koKR', '이제 그만! 자비를! 너희가 이겼다...', '', 28153),
(162085, 'koKR', '알았다, 알았다... 우리 일족을 모아 여길 떠나겠다.', '', 28153),
(162084, 'koKR', '그만! 제발! 항복한다...', '', 28153),
(162082, 'koKR', '', '얼라이언스는 드레나이와 빛벼림을 받아들였다.\n\n그것 하나로도 놈들의 도시를 먼지로 만들 이유는 충분하지.', 28153),
(162081, 'koKR', '', '드레나이가 이 세상에 있다고?\n\n<눈을 가늘게 뜨는 게야라>\n\n곧 아니게 될 것이다.', 28153),
(162080, 'koKR', '', '우린 호드를 위해 검을 든다!', 28153),
(162079, 'koKR', '', '마그하르는 아제로스에서 새로운 삶의 터전을 꾸릴 것이다.', 28153),
(162078, 'koKR', '', '드레노어를 잃었을지도 모르지만, 내 심장은 언젠가 그 하늘을 다시 보게 되리라고 말한다.\n\n선조들이여, 이 꿈을 이루어 주시길!', 28153),
(162077, 'koKR', '뼈와 살을 분리하는 거요? 오래 전부터 지속된 야만적인 전통이죠. 아니, 그런 의식은 도대체 어떻게 시작해야 할지도 모르겠다니까요.\n\n<몸을 가까이 기울이며 속삭이는 오크>\n\n정확히 알고 있습니다. 직접 보여드릴까요?', '뼈와 살을 분리하는 거요? 오래 전부터 지속된 야만적인 전통이죠. 아니, 그런 의식은 도대체 어떻게 시작해야 할지도 모르겠다니까요.\n\n<몸을 가까이 기울이며 속삭이는 오크>\n\n정확히 알고 있습니다. 직접 보여드릴까요?', 28153),
(162076, 'koKR', '드레나이를 보면 그 얼굴에 달린 통통한 촉수 안에 뼈가 있는지 궁금합니다 만약에 뼈가 있으면 그 촉수 수백 개를 가져다가 실로 이어서 장식용 장식으로 만들면 그걸 또 우리 성벽에 장식하고 지나가던 행인들이 그걸 보고 우와 하면서 와 저 얼굴 촉수 뼈 걸어 놓은 것 좀 봐 정말 정말 지혜롭고 재능 넘치는 오크가 구해다가 장식해 놨나 봐하면 제가 이렇게 대답하는 거죠 맞습니다 저희 어머니도 언제나 제게 그렇게 말씀하셨죠,라고요.\n\n죄송합니다. 질문이라도 있으십니까?', '드레나이를 보면 그 얼굴에 달린 통통한 촉수 안에 뼈가 있는지 궁금합니다 만약에 뼈가 있으면 그 촉수 수백 개를 가져다가 실로 이어서 장식용 장식으로 만들면 그걸 또 우리 성벽에 장식하고 지나가던 행인들이 그걸 보고 우와 하면서 와 저 얼굴 촉수 뼈 걸어 놓은 것 좀 봐 정말 정말 지혜롭고 재능 넘치는 오크가 구해다가 장식해 놨나 봐하면 제가 이렇게 대답하는 거죠 맞습니다 저희 어머니도 언제나 제게 그렇게 말씀하셨죠,라고요.\n\n죄송합니다. 질문이라도 있으십니까?', 28153),
(162075, 'koKR', '식사 시간인가요? 식사 시간이면 좋겠는데!\n\n이건 다른 얘기지만... 사지 중에 없어도 되는 게 있다면, 어느 쪽인가요?', '식사 시간인가요? 식사 시간이면 좋겠는데!\n\n이건 다른 얘기지만... 사지 중에 없어도 되는 게 있다면, 어느 쪽인가요?', 28153),
(162074, 'koKR', '', '<당신의 머리를 바라보는 라샤>\n\n두개골 상태는 어떤가? 잘 맞나?\n\n생각이 자유롭던가... 없던가... 쪼개졌나?', 28153),
(162073, 'koKR', '', '신록지기가 그립군.\n\n제대로 구우면, 정말 맛있었거든.\n\n<입에서 흐르는 침을 닦는 라샤>', 28153),
(162072, 'koKR', '', '빛의 결속을 불태워 버릴 때인가?', 28153),
(162071, 'koKR', '여행에 지친 $c님, 여관에 오신 걸 환영합니다. 뭘 도와드릴까요?', '여행에 지친 $c님, 여관에 오신 걸 환영합니다. 뭘 도와드릴까요?', 28153),
(162070, 'koKR', '이 여관을 귀환 장소로 사용합니다.', '이 여관을 귀환 장소로 사용합니다.', 28153),
(162069, 'koKR', '헬스크림 대족장님께 도전하는 자는 목숨을 대가로 치를 겁니다!', '헬스크림 대족장님께 도전하는 자는 목숨을 대가로 치를 겁니다!', 28153),
(162068, 'koKR', '당신은 저희 세상에 온 이방인입니다.\n\n만약 이곳에 타락을 가져온다면, 당신의 삶은 거기서 끝입니다.', '당신은 저희 세상에 온 이방인입니다.\n\n만약 이곳에 타락을 가져온다면, 당신의 삶은 거기서 끝입니다.', 28153),
(162067, 'koKR', '빛의 결속 배신자놈들, 잡히기만 하면 목을 그어버릴 겁니다.', '빛의 결속 배신자놈들, 잡히기만 하면 목을 그어버릴 겁니다.', 28153),
(162066, 'koKR', '원시의 존재들도 이겨냈는데, 우린 못 쓰러뜨릴 적이 없습니다.', '원시의 존재들도 이겨냈는데, 우린 못 쓰러뜨릴 적이 없습니다.', 28153),
(162065, 'koKR', '드레노어는 자유를 얻게 되리라!', '드레노어는 자유를 얻게 되리라!', 28153),
(162064, 'koKR', '대군주님의 신뢰를 얻으려면, 일단 제 신뢰부터 얻으십시오.', '대군주님의 신뢰를 얻으려면, 일단 제 신뢰부터 얻으십시오.', 28153),
(162063, 'koKR', '대군주 게야라 님은 대족장의 오른팔입니다. 드레노어에서는 그분만큼 용맹한 오크가 없습니다.\n\n그건 당신 세계에서도 마찬가지일 겁니다, 이방인!', '대군주 게야라 님은 대족장의 오른팔입니다. 드레노어에서는 그분만큼 용맹한 오크가 없습니다.\n\n그건 당신 세계에서도 마찬가지일 겁니다, 이방인!', 28153),
(162062, 'koKR', '', '어렸을 때, 드레나이 학자들이 읽고 쓰는 법을 알려 줬다. 난 그들이 좋았고, 그들을 존경했지.\n\n하지만 나루가 온 이래로, 그들은 광신적으로 변해갔다.\n\n드레나이는 저들의 고귀한 빛으로 새로 태어났다. 아니, 녀석들은 그걸 다시 벼려졌다고 표현하더군.\n\n그자들은 믿음에 눈이 멀어, 군단이 그랬던 것처럼 이 우주를 지배하려 하는 주인들에게 헌신하고 있지.\n\n드레나이... 에레다르... 다른 이들을 굴복시키려고 애가 탄 놈들이지. 녀석들은 오염됐어.', 28153),
(162061, 'koKR', '', '그롬마쉬 헬스크림 님께서는 우리를 훌륭하게 이끄셨다. 난 아버지 못지않게 헬스크림 님 역시 존경하지.\n\n하지만 배신자인 그분의 아들을 본다면...\n\n<땅에 침을 뱉는 게야라>\n\n...놈을 끝장낼 것이다.', 28153),
(162060, 'koKR', '', '드레노어는 광신도와 독재자로부터 벗어나야 한다.', 28153),
(162059, 'koKR', '너희 세계에서 온 영웅들 덕분에 지옥불 성채에서 악마의 지배로부터 자유로워질 수 있었지. 너도 그들과 함께 있었느냐?\n\n<당신을 쳐다보는 그롬마쉬>\n\n맞다면, 네게 큰 빚을 졌다. 어쩌면, 영혼들이 그 빚을 갚을 방법을 알려 주실지도 모르겠군.', '', 28153),
(162058, 'koKR', '마그하르는 누구에게도 굽히지 않는다. 설령 그것이 한때의 친구일 지라도.', '', 28153),
(162057, 'koKR', '먼 길을 왔구나, $c. 이곳이 너희들이 마지막으로 왔을 때보다도 야만적으로 변했다고 생각할지도 모르겠군.', '', 28153),
(162047, 'koKR', '', '오늘은 어떤 기억을 불러올까요?', 28153),
(162046, 'koKR', '이 늙은 톰쿠스가 뭘 도와드리면 되겠습니까?', '', 28153),
(162045, 'koKR', '로데론 전투에 대해 얘기해 주십시오.', '로데론 전투에 대해 얘기해 주십시오.', 28153),
(162044, 'koKR', '왕좌에서 일어난 일을 알려 주십시오.', '왕좌에서 일어난 일을 알려 주십시오.', 28153),
(162043, 'koKR', '프라우드무어의 배신에 대해 얘기해 주십시오.', '프라우드무어의 배신에 대해 얘기해 주십시오.', 28153),
(162042, 'koKR', '제이나의 시련에 대해 얘기해 주십시오.', '제이나의 시련에 대해 얘기해 주십시오.', 28153),
(162041, 'koKR', '제이나의 악몽에 대해 얘기해 주십시오.', '제이나의 악몽에 대해 얘기해 주십시오.', 28153),
(162040, 'koKR', '제이나가 테라모어로 간 일에 대해 말해 주십시오.', '제이나가 테라모어로 간 일에 대해 말해 주십시오.', 28153),
(162039, 'koKR', '피라미드에서의 전투에 대해 말해 주십시오.', '피라미드에서의 전투에 대해 말해 주십시오.', 28153),
(162038, 'koKR', '라스타칸의 선택에 대해 말해 주십시오.', '라스타칸의 선택에 대해 말해 주십시오.', 28153),
(162037, 'koKR', '탈란지가 줄다자르로 돌아가는 것에 대해 말해 주십시오.', '탈란지가 줄다자르로 돌아가는 것에 대해 말해 주십시오.', 28153),
(162035, 'koKR', '이렇게 죽을 순 없습니다.', '이렇게 죽을 순 없습니다.', 28153),
(162034, 'koKR', '저를 사로잡는 한기가 느껴졌습니다...', '저를 사로잡는 한기가 느껴졌습니다...', 28153),
(162033, 'koKR', '고맙습니다.', '고맙습니다.', 28153),
(162032, 'koKR', '설마 함정은 아니겠지. 우리에겐 아직 $n의 도움이 필요하네.', '', 28153),
(162031, 'koKR', '운명의 끝을 떠날 준비가 되었습니다.', '운명의 끝을 떠날 준비가 되었습니다.', 28153),
(162030, 'koKR', '운명의 끝으로 갈 준비가 됐습니다.', '운명의 끝으로 갈 준비가 됐습니다.', 28153),
(162029, 'koKR', '뭐라고? 마그니 브론즈비어드 님에게 무슨 일이오?', '', 28153),
(162025, 'koKR', '얘기 못 들었어? 데렉 프라우드무어 님의 시신이 약탈의 항구에 있대. 호드의 손에 말이야. 프라우드무어 여군주님이 시신을 되찾기 위해 사실상 전 함대를 보내셨대.', '얘기 못 들었어? 데렉 프라우드무어 님의 시신이 약탈의 항구에 있대. 호드의 손에 말이야. 프라우드무어 여군주님이 시신을 되찾기 위해 사실상 전 함대를 보내셨대.', 28153),
(162024, 'koKR', '오늘은 정말 조용하네. 다들 어디 간 거야?', '오늘은 정말 조용하네. 다들 어디 간 거야?', 28153),
(162023, 'koKR', '', '스톤이 꽤 잘 추스리고 있는 것 같네.\n\n언젠가 우리의 충직한 동료가 될 것이라 믿네.', 28153),
(162021, 'koKR', '', '그자들이 마땅히 받아야 할 죗값을 받는 걸 보니... 힘이 나네요.\n\n이게 바로 자유라는 걸까요? 자기의 규칙을 자기가 정하는?\n\n어쩌면 저도 적응이 될 것 같기도 하네요.', 28153),
(162020, 'koKR', '', '아말리아는 상대적으로 잘 적응하고 있는 것 같네.\n\n지금 겪고 있는 일들이 쉽지는 않겠지만, 아말리아는 강하네. 예전에 내가 변했을 때와 비교하면 말이지. 당시에 난 날 화나게 만드는 자들을 거의 다 죽였다네. 아말리아는 잠시 혼자이고 싶은 게야.\n\n시간이 지나면 괜찮아질 걸세. 날 믿게.', 28153),
(162019, 'koKR', '놈들이 온다! 아주 뭉개버려!', '', 28153),
(162018, 'koKR', '좋아, 얘들아! 고통스럽게 해 주자!', '', 28153),
(162017, 'koKR', '너는 무너지리라... 그분께서 일어나신다... 일어나신다...', '', 28153),
(162016, 'koKR', '', '절 그냥 두세요. 이야기할 기분이 아니에요.', 28153),
(162015, 'koKR', '주인님께서 굶주리셨다... 심장이 그의 백일몽을 채우리라...', '', 28153),
(162014, 'koKR', '잔달라 부족은 오랜 시간 브원삼디 님을 섬겨 왔네. 검은창 부족처럼 말이지.\n\n내가 항구에서 구입한 이 브원삼디 님의 우상을 보게. 정말 멋지지 않나? 고향에서 보던 웬만한 우상보다 낫네.\n\n검은창과 잔달라가 다른 점이 많은 건 사실이네만, 공통점은 더 많네.\n\n잔달라 부족이 그 고지식함만 좀 버린다면, 우리와 좋은 친구가 될 수 있을 걸세!', '우리의 다음 사냥은 언젠가, $p?\n\n내 평생 아제로스에 살면서, 제거해야 할 괴물이 부족한 적은 없었네.', 28153),
(162013, 'koKR', '', '안 돼! 우리 고향이...', 28153),
(162012, 'koKR', '', '우리 고향 쪽으로는 한 발자국도 더 움직일 수 없다, $r! 토르 일리사르데라날!', 28153),
(162011, 'koKR', '어리석은 것... 이미 늦었다...', '', 28153),
(162010, 'koKR', '이 작은 마을에 남은 것들은 모두 쓸어버리고, 네놈을 단번에 처리해주마!', '', 28153),
(162009, 'koKR', '잔달라 부족은 테러닥스 로아를 숭배한다고 들었소.\n\n날개 달린... 파충류 신이라!\n\n<라산의 눈이 반짝거리는 것 같습니다.>\n\n아비아쉬는 그쪽 최고의 기수와 경주를 벌일 준비가 됐소. 싸움이면 더 좋고!\n\n어느 쪽이든 상관없소. 어차피 우리가 다 이길 테니!\n\n하하하하하하하하하하!', '우리의 다음 사냥은 언제요, $p?\n\n내 평생 아제로스에 살면서, 제거해야 할 괴물이 부족한 적은 없었소.', 28153),
(162008, 'koKR', '계획을 말씀해 주십시오, 나타노스.', '계획을 말씀해 주십시오, 나타노스.', 28153),
(162007, 'koKR', '아주 좋아. $n, 태터세일에게 우리가 출발할 준비가 되었다고 전해 주게.', '', 28153),
(162006, 'koKR', '호드가 그것을 훔칠 것입니다.', '', 28153),
(162005, 'koKR', '이 유물은 쿨 티라스의 수도 보랄러스의 심장부에 보관되어 있습니다.', '', 28153),
(162004, 'koKR', '심연의 홀을 휘두른다는 건, 곧 바다와 폭풍의 힘을 휘두른다는 뜻이죠.', '', 28153),
(162003, 'koKR', '바로 심연의 홀입니다.', '', 28153),
(162002, 'koKR', '스톰송 가문에 속한 저의 옛 파도현자 형제들에겐 강력한 유물이 있습니다.', '', 28153),
(162001, 'koKR', '알겠습니다, 블라이트콜러 님.', '', 28153),
(162000, 'koKR', '젤링, 자네가 설명해 주겠나?', '', 28153),
(161999, 'koKR', '저 공룡들 크기 좀 봐!\n\n<기대에 찬 한숨을 쉬는 지>\n\n빨리 한 방 먹여 주고 싶어.', '우리의 다음 사냥은 언제야, $p?\n\n내 평생 아제로스에 살면서, 제거해야 할 괴물이 부족한 적은 없었어.', 28153),
(161998, 'koKR', '부서진 해변', '부서진 해변', 28153),
(161997, 'koKR', '넬타리온의 석실', '넬타리온의 석실', 28153),
(161996, 'koKR', '정령의 고원', '정령의 고원', 28153),
(161995, 'koKR', '검은바위 용광로 전망대', '검은바위 용광로 전망대', 28153),
(161994, 'koKR', '스톰스타우트 양조장', '스톰스타우트 양조장', 28153),
(161993, 'koKR', '맥주통 휴게소', '맥주통 휴게소', 28153),
(161992, 'koKR', '난 오랜 세월을 싸워왔네. 영웅과 겁쟁이가 전장에서 피 흘리는 걸 목격했지.\n\n그런데 이 전쟁은... 뭔가 좀 다르네.\n\n단순히 우리의 패기와 능력만을 시험하는 전쟁이 아니야. 이 전쟁은 우리의 진심을 시험하고 있네. 서로에 대한 우리의 신뢰를.\n\n그 어떤 일이 있어도, 호드는 이겨낼 걸세.\n\n그래야만 하네.', '우리의 다음 사냥은 언제인가, $p?\n\n내 평생 아제로스에 살면서, 제거해야 할 괴물이 부족한 적은 없었다네.', 28153),
(161991, 'koKR', '루비 용제단', '루비 용제단', 28153),
(161990, 'koKR', '은빛십자군 마상시합 광장', '은빛십자군 마상시합 광장', 28153),
(161989, 'koKR', '불타버린 언덕', '불타버린 언덕', 28153),
(161988, 'koKR', '지옥의 구덩이', '지옥의 구덩이', 28153),
(161987, 'koKR', '명예의 요새', '명예의 요새', 28153),
