(161984, 'koKR', '불꽃깃털 마루', '불꽃깃털 마루', 28153),
(161983, 'koKR', '석공 작업장', '석공 작업장', 28153),
(161982, 'koKR', '맹금의 봉우리', '맹금의 봉우리', 28153),
(161981, 'koKR', '네더가드 요새', '네더가드 요새', 28153),
(161980, 'koKR', '스톰윈드', '스톰윈드', 28153),
(161979, 'koKR', '아이언포지', '아이언포지', 28153),
(161978, 'koKR', '잔달라', '잔달라', 28153),
(161977, 'koKR', '쿨 티라스', '쿨 티라스', 28153),
(161976, 'koKR', '부서진 섬', '부서진 섬', 28153),
(161975, 'koKR', '노스렌드', '노스렌드', 28153),
(161974, 'koKR', '판다리아', '판다리아', 28153),
(161973, 'koKR', '드레노어', '드레노어', 28153),
(161972, 'koKR', '아웃랜드', '아웃랜드', 28153),
(161971, 'koKR', '칼림도어', '칼림도어', 28153),
(161970, 'koKR', '동부 왕국', '동부 왕국', 28153),
(161969, 'koKR', '중요한 것들은 말이야 상자 안에 넣을 가치가 있지.\n\n물론, 사람은 빼고! $p, 자네를 상자 안에 넣을 순 없잖아, 안 그래?\n\n<잠시 생각에 잠기는 호바트>\n\n아무튼, 난 지금 이 녀석을 좀 손보는 중이야. 빠르게 다시 작동시킬 거라고... 폭탄을 좀 개량해서 말이지!', '다음 사냥은 또 언제 가는 거야, $p?\n\n내 평생 아제로스에 살면서, 제거해야 할 괴물들이 부족한 적은 없었거든.', 28153),
(161968, 'koKR', '조지, 내가 이런 언덕에서 죽을 순 없지.', '', 28153),
(161967, 'koKR', '제프와 겨뤄보겠다고, 각오 단단히 하시오!', '', 28153),
(161966, 'koKR', '따님은 운명의 끝으로 끌려갔습니다.', '따님은 운명의 끝으로 끌려갔습니다.', 28153),
(161965, 'koKR', '좋습니다! 본때를 보여줬군요!', '', 28153),
(161964, 'koKR', '사막이라니? 정말... 진기하군요.', '', 28153),
(161963, 'koKR', '부름 받고 왔습니다, 웜베인 님.', '', 28153),
(161962, 'koKR', '간다...', '', 28153),
(161961, 'koKR', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t|cFFFF0000|Hspell:267334|h[타락의 보주]|h|r안으로 들어가 보주를 공중으로 돌려보내십시오!', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t|cFFFF0000|Hspell:267334|h[타락의 보주]|h|r안으로 들어가 보주를 공중으로 돌려보내십시오!', 28153),
