(161959, 'koKR', '좋습니다! 전 준비됐습니다!', '', 28153),
(161958, 'koKR', '대포 발사를 준비하는 동안 저 망할 것 좀 처리해 주십시오!', '', 28153),
(161957, 'koKR', '|cFF0000FF(퀘스트)|r 드레노어로 갈 준비가 되었습니다.', '|cFF0000FF(퀘스트)|r 드레노어로 갈 준비가 되었습니다.', 28153),
(161956, 'koKR', '|TInterface\\Icons\\ABILITY_EARTHEN_PILLAR.BLP:20|t %s|1이;가; 당신을 |cFFFF0000|Hspell:259720|h[지각 변동]|h|r의 대상으로 지정합니다!', '|TInterface\\Icons\\ABILITY_EARTHEN_PILLAR.BLP:20|t %s|1이;가; 당신을 |cFFFF0000|Hspell:259720|h[지각 변동]|h|r의 대상으로 지정합니다!', 28153),
(161955, 'koKR', '여기, 마지막 열쇠에요!', '여기, 마지막 열쇠에요!', 28153),
(161954, 'koKR', '가로쉬 헬스크림의 메아리를 찾을 준비가 되었습니다.', '가로쉬 헬스크림의 메아리를 찾을 준비가 되었습니다.', 28153),
(161953, 'koKR', '중요하다고 생각하지 않았다면, 애초에 널 도와 이 일에 함께하지도 않았겠지.', '', 28153),
(161952, 'koKR', '그만 떠들어요! 소문낼 필요는 없다고요.', '어제 떠났어야 하는 건데.', 28153),
(161950, 'koKR', '오늘 이런 일이 벌어질 줄은 몰랐습니다!', '', 28153),
(161949, 'koKR', '|TINTERFACE\\ICONS\\INV_MISC_SOCCERBALL.BLP:20|t동전 투입식 군중 난타기가 |cFFFF0000|Hspell:256214|h[축구탄 발사기]|h|r를 시전합니다!', '|TINTERFACE\\ICONS\\INV_MISC_SOCCERBALL.BLP:20|t동전 투입식 군중 난타기가 |cFFFF0000|Hspell:256214|h[축구탄 발사기]|h|r를 시전합니다!', 28153),
(161948, 'koKR', '파편이 힘을 얻는다, $p.', '', 28153),
(161947, 'koKR', '용족의 악취가 머무는구나. 빠르게 처리해라.', '', 28153),
(161946, 'koKR', '할 일은 끝났다, $p. 수석 이동술사 오큘레스가 줄다자르에서 널 기다린다.', '', 28153),
(161945, 'koKR', '', '약속을 지킬 때까진 안 풀릴 것 같군, 얌생이 같으니.', 28153),
(161944, 'koKR', '알았네, 50으로 하자고! 그 정도면 괜찮네! 이제 마음 풀렸나?', '', 28153),
(161943, 'koKR', '', '50으로 하게. 네 이빨의 반을 가져가길 원하지 않는다면 말이지.', 28153),
(161942, 'koKR', '제안 하나 하지. 은으로 남긴 수익을 나눠 줄 테니까 그 곡괭이 좀 내려놔. 20퍼센트 정도면 어때?', '', 28153),
(161941, 'koKR', '정말인가? 기억이 나는 것 같기도 하고...', '', 28153),
(161940, 'koKR', '', '네가 남은 경비병과 내뺄 때 우리가 비명 지른 거 기억 안 나냐!', 28153),
(161939, 'koKR', '이봐, 진정하라고! 생존자가 있다는 걸 내가 어떻게 알았겠어?', '', 28153),
(161938, 'koKR', '', '이 비겁한 자식! 죽을 게 뻔한데 우릴 버리고 가다니!', 28153),
(161937, 'koKR', '다음 건 점수를 매겨 주십시오!', '다음 건 점수를 매겨 주십시오!', 28153),
(161936, 'koKR', '말 탈 준비 되었길 바라오!', '', 28153),
(161935, 'koKR', '', '괜찮다면, 난 내 곡괭이 날을 가지고 그림록과 담소를 좀 나누러 가 보겠네...', 28153),
(161934, 'koKR', '', '다시 한번 도와줘서 고맙네, 이방인 친구.', 28153),
(161933, 'koKR', '전역 퀘스트 플레이 가능', '', 28153),
(161932, 'koKR', '녀석들은 이걸 음식이라고 팔려고 했어요!', '상자들 좀 닫아주세요, 이 난장판을 해결해야 합니다!', 28153),
(161931, 'koKR', '격전의 스트롬가드 플레이 가능', '', 28153),
(161930, 'koKR', '정말 짜증나는 꼬마들이군!', '이것들 좀 치워주세요!', 28153),
(161929, 'koKR', '저 망할 꼬맹이들이 저것들을 마을에 들여왔다고요!', '꼬마 녀석 하나가 또 정신 나간 짓을 벌였어요!', 28153),
(161928, 'koKR', '|TInterface\\ICONS\\INV_Misc_Bell_Green:20|t 식탐귀 라알이 |cFFFF0404|Hspell:264931|h[시종 부르기]|h|r를 시전합니다!', '', 28153),
(161927, 'koKR', '|TInterface\\ICONS\\INV_MISC_VOLATILESHADOW:20|t 부인 웨이크레스트가 |cFFFF0404|Hspell:268306|h[불협의 카덴차]|h|r를 시전합니다!', '|TInterface\\ICONS\\INV_MISC_VOLATILESHADOW:20|t 부인 웨이크레스트가 |cFFFF0404|Hspell:268306|h[불협의 카덴차]|h|r를 시전합니다!', 28153),
(161926, 'koKR', '해냈군! 아제로스가 더욱 강력해졌군... 자네도 마찬가지일세!', '', 28153),
(161925, 'koKR', '고대 신의 하수인일세! 아제로스의 심장이 가진 힘이라면 놈을 몰아낼 수 있어! 심장을 사용하게, $n|1이여;여;!', '', 28153),
(161924, 'koKR', '군도 플레이 가능', '', 28153),
(161923, 'koKR', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_CANNIBALIZE.BLP:20|t |cFFFF0404|Hspell:263235|h[피의 잔치]|h|r를 사용하여 |cFFFF0404|Hspell:263227|h[부패한 피]|h|r 중첩을 제거하십시오.', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_CANNIBALIZE.BLP:20|t |cFFFF0404|Hspell:263235|h[피의 잔치]|h|r를 사용하여 |cFFFF0404|Hspell:263227|h[부패한 피]|h|r 중첩을 제거하십시오.', 28153),
(161922, 'koKR', '폭풍 위로 높이 솟아라. 다른 자들은 젖게 두어라.', '', 28153),
(161921, 'koKR', '', '됐군! 이제 스톰윈드로 돌아가 왕에게 보고하도록 하지.', 28153),
(161920, 'koKR', '', '검은 모루를 수리하면서 그 성능도 몇 가지 강화하기로 했다.', 28153),
(161919, 'koKR', '', '전 전쟁에서 승리를 쟁취할 때까지 사냥을 멈추지 않을 겁니다, $n.\n\n텔드랏실에서 잃어버린 모든 이에게 그렇게 맹세했으니까요.\n\n<고개를 숙이며 기도하는 샨드리스>', 28153),
(161918, 'koKR', '', '파도에 타세요. 폭풍을 안고!', 28153),
(161917, 'koKR', '피의 관문으로 돌아갑시다.', '피의 관문으로 돌아갑시다.', 28153),
(161916, 'koKR', '솔직히 말해, 배 타는 걸 좋아하진 않아요. 하지만 그 아래 숨겨진 것들에는 감탄하지 않을 수 없죠.\n\n가서 볼 만한 고대 유물을 발견하게 된다면, 언제든지 제게 보여 주세요.\n\n그리고 문도요. 수수께끼의 문. 수수께끼 티탄 문이 제 전문이니까요!', '', 28153),
(161915, 'koKR', '', '할포드 님이 여기 재밌어 보이는 것들을 두셨네요. 전쟁 보고서, 부대 이동 관련 서류...\n\n<문가를 힐끗 보고는 당신에게 가까이 와 속삭이는 켈시>\n\n그리고 개인 일기장까지 발견했답니다!\n\n<의미심장하게 윙크하는 켈시>', 28153),
(161914, 'koKR', '', '친구들 없이는 떠나기 싫으신 거죠, 아닌가요?', 28153),
(161913, 'koKR', '강직하고 정직한 얼라이언스 병사들과 함께 싸우게 되어 기쁩니다. 불곰 중대 소속이던 시절이 생각나는군요.\n\n<먼 산을 바라보는 듯한 키샨>\n\n$n 님, 언제나 무기는 준비해야 합니다. 그리고 붙잡혔을 때를 대비해 하나 더 숨겨 두십시오. 아무도 못 찾을 곳에 말입니다.', '', 28153),
(161912, 'koKR', '|TINTERFACE\\ICONS\\SPELL_FROST_ARCTICWINDS.BLP:20|t릭사 플럭스플레임이 |cFFFF0000|Hspell:259940|h[압축가스 작렬]|h|r을 시전합니다!', '|TINTERFACE\\ICONS\\SPELL_FROST_ARCTICWINDS.BLP:20|t릭사 플럭스플레임이 |cFFFF0000|Hspell:259940|h[압축가스 작렬]|h|r을 시전합니다!', 28153),
(161911, 'koKR', '우리 종족은 훈련 중입니다. 능력을 갈고닦고 있죠.\n\n<눈을 가늘게 뜨는 엄브릭>\n\n속삭임은 다양한 가능성을 말해 줍니다. 어떤 미래가 오든, 저희는 준비됐습니다.', '', 28153),
(161910, 'koKR', '솔직히 처음에는 이 모든 게 좀 의심스러웠지만, 결국 다 잘 풀렸군요.', '', 28153),
(161909, 'koKR', '검은무쇠에게 너무나도 기쁜 날입니다!', '', 28153),
(161908, 'koKR', '', '마무리는 네게 맡기지, $p.', 28153),
(161907, 'koKR', '', '$n, 다시 전쟁터에 나오니 기분이 좋습니다. 하지만... 상처입은 자들을 치유하는 것도 힘에 부치는군요. 더 좋은 곳에 제 힘을 사용할 수 있을 텐데.\n\n우리 빛벼림이 군단을 상대로 사용한 여러 기술은 호드와의 전쟁에서도 도움이 될 겁니다.\n\n괜찮다면 총사령관님께 잡아들인 포로들이 전부 제대로... \"정화\"되었다는 걸 전해 주시겠습니까.', 28153),
(161906, 'koKR', '', '제이나 프라우드무어 님이 고향으로 돌아가기로 하신 게 놀랄 일은 아니죠.\n\n상처는 치료하지 않으면 낫지 않습니다. 제이나 님처럼 깊은 상처를 입은 경우에는 더더욱.', 28153),
(161905, 'koKR', '심장부 수호자가 당신을 공격하러 옵니다!', '심장부 수호자가 당신을 공격하러 옵니다!', 28153),
(161904, 'koKR', '|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:20|t메레크타가 |cFFFF0000|Hspell:263914|h[실명의 모래]|h|r로 공격하려 합니다. 시선을 돌리십시오!', '|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:20|t메레크타가 |cFFFF0000|Hspell:263914|h[실명의 모래]|h|r로 공격하려 합니다. 시선을 돌리십시오!', 28153),
(161903, 'koKR', '', '준비되면 말해라, $n. 검은바위 나락으로 가고 싶으면 말만 해라.', 28153),
(161902, 'koKR', '', '할 일은 알고 계시겠죠, $n|1이여;여;. 움직이죠.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161901, 'koKR', '|cFF0000FF(퀘스트)|r 불의 땅으로 갈 준비가 되었습니다.', '|cFF0000FF(퀘스트)|r 불의 땅으로 갈 준비가 되었습니다.', 28153),
(161900, 'koKR', '', '갑시다, $n|1이여;여;. 쓰러뜨릴 적이 있습니다.', 28153),
(161899, 'koKR', '볼둔에 우리가 왔다고 예상도 못 했겠지만, 놈들의 요원들을 죽이면 우리 존재를 알아차리는 건 시간문제요.', '', 28153),
(161898, 'koKR', '빨리 움직여야 하오, $n. 호드는 아직 우리가 왔단 사실을 모르니까.', '', 28153),
(161897, 'koKR', '순식간에 폭발물을 설치하고 우리에게 돌아올 것이오.', '', 28153),
(161896, 'koKR', '그렇게 안 보일지도 모르지만, 싸움도 거뜬히 해 내고, 폭발물 다뤄 본 경험은 누구와 비교해도 최고니까.', '', 28153),
(161895, 'koKR', '걱정 마시오. 거즈버트와는 예전에도 일해 본 적 있으니. 그는 전문가요.', '', 28153),
(161894, 'koKR', '빛의 뜻대로, 놈들을 막아야 하오.', '', 28153),
(161893, 'koKR', '쓸 수 없는 건, 팔아 버리고는 호드의 전쟁 대장정에 보태지.', '', 28153),
(161892, 'koKR', '하지만 그래서는 안 되지. 그 망할 놈들은 강력한 유물을 파 내서 자신들의 적에게 써 버리니 말이오.', '', 28153),
(161891, 'koKR', '솔직히 선워처와 그 성물회 무리는 무시하고 지나가고 싶소. 솔직히... 결국 놈들은 고고학자잖소.', '', 28153),
(161890, 'koKR', '|cFF0000FF(퀘스트)|r 검은바위 나락으로 갈 준비가 되었습니다.', '|cFF0000FF(퀘스트)|r 검은바위 나락으로 갈 준비가 되었습니다.', 28153),
(161889, 'koKR', '', '지금 아라시는 여행을 하기엔 너무 위험한 곳이에요.$B$B스트롬가드를 되찾으면 차원문을 다시 쓸 수 있을 거예요.', 28153),
(161888, 'koKR', '마그하르 오크에 대해 어떤 걸 아십니까?', '마그하르 오크에 대해 어떤 걸 아십니까?', 28153),
(161887, 'koKR', '검은무쇠 드워프에 관해 이야기해 주시겠습니까?', '검은무쇠 드워프에 관해 이야기해 주시겠습니까?', 28153),
(161886, 'koKR', '저는 커서 니샤처럼 될 거예요! 니샤가 최고니까요!\n\n아니면 키로처럼 될 거예요! 키로는 엄청 똑똑하거든요....\n\n아니면 미라처럼 될 거예요! 미라는 정말 상냥하거든요....\n\n아니면 제나처럼 될 거예요! 제나는 가진 게 많거든요....\n\n아니면...\n\n<계속해서 야영지에 있는 다른 불페라의 이름을 나열하는 루도>', '', 28153),
(161885, 'koKR', '', '지금 아라시는 여행을 하기엔 너무 위험한 곳이라네.$B$B아르고로크를 되찾으면 차원문을 다시 쓸 수 있을 거야.', 28153),
(161884, 'koKR', '', '시원한 맥주 한 잔 하시겠어요?', 28153),
(161883, 'koKR', '너 운이 좋구나! 이거 없인 이길 수 없다고!', '', 28153),
(161882, 'koKR', '안녕하세요, 좋은 물건을 조금 가져왔답니다.', '오, 제 발명품이 마음에 드셨으면 좋겠군요!', 28153),
(161881, 'koKR', '이제 막 벼려낸 무기와 갑옷도 있다네!', '', 28153),
(161880, 'koKR', '', '스톰윈드에서 가져온 보급품이 있어요!', 28153),
(161879, 'koKR', '어둠의 도구들을 가져왔습니다.', '', 28153),
(161878, 'koKR', '관심이 있으실지도 모를 마법 유물들을 가져왔습니다.', '여기서 좋은 물건을 좀 얻었습니다. 어디서 났냐고는 묻지 마십시오.', 28153),
(161877, 'koKR', '술 사시게!', '여기서 좋은 물건을 좀 얻었네. 어디서 났냐고는 묻지 말게.', 28153),
(161876, 'koKR', '마그하르는 당신 편입니다, 피와 번개의 축복을!', '여기서 좋은 물건을 좀 얻었습니다. 어디서 났냐고는 묻지 마십시오.', 28153),
(161875, 'koKR', '이봐요, 폭탄이 필요하신가요? 그 필요하신 물건이 제게 있답니다.', '여기서 좋은 물건을 좀 얻었어요. 어디서 났냐고는 묻지 마시고요.', 28153),
(161874, 'koKR', '록타르! 오그리마에서 가져온 물건이 있다오.', '여기서 좋은 물건을 좀 얻었소. 어디서 났냐고는 묻지 마시오.', 28153),
(161873, 'koKR', '좋은 물건이 있어! 네게 행운을 가져다줄 거야!', '좋은 물건이 있어! 네게 행운을 가져다줄 거야!', 28153),
(161872, 'koKR', '엘리산드는 청동용에게만 알려졌던 주문에 통달했다고 하더군. 어쩌면 그들에게 도움을 받을 수 있을지도 모르네.', '', 28153),
(161871, 'koKR', '시간 마법은 우리의 전 지도자였던 대마법학자 엘리산드의 전문이었네. 그녀의 죽음과 함께 관련 지식 대부분이 사장되었지.', '', 28153),
(161870, 'koKR', '프라우드무어 훈련소에 잠입해야 합니다.', '프라우드무어 훈련소에 잠입해야 합니다.', 28153),
(161869, 'koKR', '프라우드무어 병영에 잠입해야 합니다.', '프라우드무어 병영에 잠입해야 합니다.', 28153),
(161868, 'koKR', '', '얼라이언스를 위하여!', 28153),
(161867, 'koKR', '우린 방어선을 지키겠소. 당신은 가시오. 얼라이언스를 위하여!', '', 28153),
(161866, 'koKR', '우린 지금 뒤가 막혀 있고, 바다에는 수많은 적 함선이 우릴 겨냥하고 있는 상황이오.', '', 28153),
(161865, 'koKR', '안타깝지만 노움의 말이 맞소, $p.', '', 28153),
(161864, 'koKR', '', '저기요!', 28153),
(161863, 'koKR', '%s|1이;가; 황급히 개구리습지로 돌아갑니다.', '%s|1이;가; 황급히 개구리습지로 돌아갑니다.', 28153),
(161862, 'koKR', '이놈은 입을 열 거요. 냄새 고약한 포세이큰과는 달리 적어도 혀는 아직 있으니 말이오.', '', 28153),
(161861, 'koKR', '', '이동하죠, $p 님! 함선의 선장님과 이야기하고 출발해요!', 28153),
(161860, 'koKR', '', '가끔은 제가 그냥 기계였으면 할 때도 있어요...', 28153),
(161859, 'koKR', '', '기계.... <한숨>', 28153),
(161858, 'koKR', '이상. 해산!', '', 28153),
(161857, 'koKR', '이 야영지 상황을 파악한 후, 그 결과를 내게 보고하시오. ', '', 28153),
(161856, 'koKR', '', '오오! 검은무쇠 드워프! 전 검은무쇠 드워프를 사랑해요! 검은무쇠 드워프는 기계를 쓰거든요.', 28153),
(161855, 'koKR', '가서 줄다자르 남동쪽 해안에 있는 엔빌테인 터르가덴과 만나도록.', '', 28153),
(161854, 'koKR', '', '옛!', 28153),
(161853, 'koKR', '켈시!', '', 28153),
(161852, 'koKR', '그의 병력은 바다에서 큰 타격을 받았지만, 그래도 동쪽 해안에 야영지를 꾸리고 활동을 근근이 이어가고 있소.', '', 28153),
(161851, 'koKR', '우리 7군단 장교 중 한 명인 톰 준장과 만나시오. ', '', 28153),
(161850, 'koKR', '$p!', '', 28153),
(161849, 'koKR', '', '안에 신선한 음식이 많아요.', 28153),
(161848, 'koKR', '줄다자르에는 이미 우리 지상군이 진출해 있소. 한 군데도 아니라 두 군데에.', '', 28153),
(161847, 'koKR', '다들 모이시오. 계획을 설명하겠소.', '', 28153),
(161846, 'koKR', '네가 갈 곳은... 프라우드무어 님의 감옥이다...', '', 28153),
(161845, 'koKR', '', '더러운... 호드 놈...', 28153),
(161844, 'koKR', '데렉 님의 시신을 되찾겠다... 어떤 식으로든...', '', 28153),
(161843, 'koKR', '', '너희는 우리 가르침의 힘을 절대 사용하지 못 한다...', 28153),
(161842, 'koKR', '네놈들은 모두 휩쓸려버릴 것이다...', '', 28153),
(161841, 'koKR', '자, 오큘레스에게 가라. 파편이 온전해졌으니, 네가 원하는 곳으로 보내 줄 수 있을 거다.', '', 28153),
(161840, 'koKR', '조금이라도 의심이 됐다면 잘못된 이의 손에 파편이 들어가는 걸 막았을 거다. 두 번은 안 되지.', '', 28153),
(161839, 'koKR', '운명의 끈이 너를 감싸는구나. 네게 앞으로 올 미래를 맞이할 자격이 있다는 거겠지.', '', 28153),
(161838, 'koKR', '과거를 되살린 것뿐인데도, 가로쉬는 강력한 상대였다.', '', 28153),
(161837, 'koKR', '여기서 본 메아리는 가장 최악의 모습이었다. 존재 가치도 없었지.', '', 28153),
(161836, 'koKR', '수많은 시간의 길에서, 그는 동족에게 위대한 영웅이었다. 호드의 가장 위대한 대족장이라는 이야기도 더러 했지.', '', 28153),
(161835, 'koKR', '가로쉬 헬스크림... 참 유감스럽게 됐지.', '', 28153),
(161834, 'koKR', '내가 널 무서워할 거라 생각하나?', '', 28153),
(161833, 'koKR', '전부 말해라, 잔달라여.', '전부 말해라, 잔달라여.', 28153),
(161832, 'koKR', '내 이야기 들려 줄까?\n\n난 기함에 있었어. 다 봤다고.\n\n좋아. 무슨 일이 벌어졌는지 말해 주지. 아는 편이 좋을 거야. 공포를 맛보는 편이 좋지.', '', 28153),
(161831, 'koKR', '이제 백호사로 가야한다.', '', 28153),
(161830, 'koKR', '굴단이 사라졌다고 아쉬워하는 이는 아무도 없다... 이곳에서도, 다른 어떤 시간 속에서도.', '', 28153),
(161829, 'koKR', '이건 아제로스의 적이었던 자의 메아리에 지나지 않지만, 그렇다고 해서 놈에게 죽는 게 진짜가 아닐 거란 생각은 마라.', '', 28153),
(161828, 'koKR', '굴단은 시간의 환영의 도움을 받아 이곳을 통해 다른 세계를 오갔지.', '', 28153),
(161827, 'koKR', '시간의 길을 따라 마법의 메아리가 진동하는군.', '', 28153),
(161826, 'koKR', '지금 이 순간에도... 잠깐, 저게 뭐지?', '', 28153),
(161825, 'koKR', '이 방에서라면, 그대가 지닌 아제로스의 심장은 더욱 강해질 수 있네!', '', 28153),
(161824, 'koKR', '확실히 저번에 왔을 때보다 심장의 방 상태가 나아지지 않았나, 안 그런가?', '', 28153),
(161823, 'koKR', '하지만 절망에 굴복해서는 안 되네. 그대가 이 어둠의 물결을 몰아낼 걸세!', '', 28153),
(161822, 'koKR', '아직 갈 길이 머네, $n. 바깥 상황은 점점 최악으로 치닫고 있는 것도 같고.', '', 28153),
(161821, 'koKR', '느껴지나? 심장의 힘이 계속해서 깨어나고 있네!', '', 28153),
(161820, 'koKR', '이런 제길! 내 말을 똑똑히 기억하게... 불의 군주는 반드시 돌아올 걸세. 그때 보자고... 오랜 친구여.', '', 28153),
(161819, 'koKR', '아아, 바로 이거지... 불 냄새가 이렇게 아침에도... 점심에도, 저녁에도 나는 곳. 화산 심장부를 충전하려면 불의 군주의 소굴 깊숙이 가야하네.', '', 28153),
(161818, 'koKR', '나는 최정예 정찰대를 보내 그림스톤을 찾겠네. 그 미친 녀석이 추종자들을 더 세뇌시키기 전에 막아야 해!', '', 28153),
(161817, 'koKR', '정말 쿨 티라스 도입부를 건너뛰시겠습니까?', '정말 쿨 티라스 도입부를 건너뛰시겠습니까?', 28153),
(161816, 'koKR', '이 이야기는 전에 들어 본 적이 있어요... <쿨 티라스 도입부를 건너뛰고 보랄러스에서 모험을 시작합니다.>', '이 이야기는 전에 들어 본 적이 있어요... <쿨 티라스 도입부를 건너뛰고 보랄러스에서 모험을 시작합니다.>', 28153),
(161815, 'koKR', '$n|1이여;여;, 힘을 지혜롭게 쓰게. 그리고 늘 경계하게... 자네가 세상을 구하는 걸 막으려는 세력도 존재하니까!', '', 28153),
(161814, 'koKR', '아제로스가 강력해질수록, 그대 목에 건 아제로스의 심장도 강해지지!', '', 28153),
(161813, 'koKR', '아제로스는 여전히 고통스러워하지만, 그대가 애써 준 덕분에 버티고 있네.', '', 28153),
(161812, 'koKR', '좋아. 그럼 다리를 세워 볼까. 딱 알맞은 주문이...', '', 28153),
(161811, 'koKR', '그 정도면 됐네! 이제 여길 빠져나가세.', '', 28153),
(161810, 'koKR', '급한 불부터 꺼야겠지. 화산 심장부를 충전시켜 검은모루를 고쳐야 하네.', '', 28153),
(161809, 'koKR', '심각한 일일세, $p. 그림스톤과 놈의 광신도들이 라그나로스를 다시 데려오려 하네... 얼마나 무모한 짓인지 잘 알고 있으리라 생각했는데.', '', 28153),
(161808, 'koKR', '얼라이언스가 실리더스로 향하게 된 경위를 보여 주십시오.', '얼라이언스가 실리더스로 향하게 된 경위를 보여 주십시오.', 28153),
(161807, 'koKR', '호드가 실리더스로 향하게 된 경위를 보여 주십시오.', '호드가 실리더스로 향하게 된 경위를 보여 주십시오.', 28153),
(161806, 'koKR', '술이 끊기면 못 쓰죠.', '', 28153),
(161805, 'koKR', '아직 술이 고프다고!', '', 28153),
(161804, 'koKR', '하나 더!', '', 28153),
(161803, 'koKR', '더!', '', 28153),
(161802, 'koKR', '|TInterface\\ICONS\\Spell_Shaman_TidalWaves.blp:20|t 하달이 |cFFFF0000|Hspell:276068|h[굽이치는 파도]|h|r를 만듭니다!', '|TInterface\\ICONS\\Spell_Shaman_TidalWaves.blp:20|t 하달이 |cFFFF0000|Hspell:276068|h[굽이치는 파도]|h|r를 만듭니다!', 28153),
(161801, 'koKR', '그래, 잡담을 더 해도 의미가 없겠군.', '', 28153),
(161800, 'koKR', '그렇고 말고, 이녀석아!', '', 28153),
(161799, 'koKR', '진정한 불의 군주께서 다시 일어나시면 충직한 검은무쇠 부족 모두가 부름에 응할 걸세. 자네는 우리에게 반기를 들겠단 말인가?', '', 28153),
(161798, 'koKR', '그 누더기같은 불꽃 고리를 보면 그자가 감격이라도 할 줄 아나? 여기까지 오는 길에 네 이도교 끄나풀은 거의 다 쓸어버렸다고 생각했네만.', '', 28153),
(161797, 'koKR', '타우릿산의 뜻은 옳았으나, 불의 군주를 통제하려던 것이 실수였지. 우린 그분을 열과 성을 다해 섬겨야 하네.', '', 28153),
(161796, 'koKR', '라그나로스 말인가?! 그 폭군을 다시 데려오겠다고? 마술사 영주가 그러려고 한 적이 있었네만, 그 자는...', '', 28153),
(161795, 'koKR', '정당한 지도자? 그녀의 핏줄에선 불꽃 따위는 찾아볼 수 없네, 엔빌테인. 우리의 정당한 지도자는 화염의 군주일세. 브론즈비어드인가 뭔가 하는 똥강아지와, 놈의 거짓 추종자들이 아니라.', '', 28153),
(161794, 'koKR', '알았네, 전령. 우리의 정당한 지도자에게 무슨 불경한 소리인가.', '', 28153),
(161793, 'koKR', '예의는 어디에 팔아먹었나! 호칭은 제대로 하시게.', '', 28153),
(161792, 'koKR', '입 조심하시지, 배달부 양반. 그런 소릴 함부로 내뱉다간 불구덩이를 구경하는 수가 있어.', '', 28153),
(161791, 'koKR', '잘 왔네, 엔빌테인. 자네도 알다시피 섭정 여왕은 나약해 빠지지 않았나.', '', 28153),
(161790, 'koKR', '그림스톤... 대체 여기서 무슨 일이 벌어지는 겐가? 스몰데론은 어디 있나?', '', 28153),
(161789, 'koKR', '두... 두목!', '', 28153),
(161788, 'koKR', '엔빌테인 터르가덴이 여기에 있다! 그림스톤 대법관님께 알려라!', '엔빌테인 터르가덴이 여기에 있다! 그림스톤 대법관님께 알려라!', 28153),
(161786, 'koKR', '어버버하지 말고 똑바로 대답해!', '', 28153),
(161785, 'koKR', '아아... 글쎄 그것이...', '아아... 글쎄 그것이...', 28153),
(161784, 'koKR', '다리는 왜 막혀있느냐? 여기 담당이 누구야?', '', 28153),
(161783, 'koKR', '엔빌테인 님?!', '엔빌테인 님?!', 28153),
(161782, 'koKR', '이게 대체 무슨 일이냐?', '', 28153),
(161781, 'koKR', '내 작은 친구에게 인사해라!', '', 28153),
(161780, 'koKR', 'This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN\'T a--dreadlord, really?', 'This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN\'T a--dreadlord, really?', 28153),
(161779, 'koKR', '<상인이 어쩌다 이 꼴이 됐는지는 알 수 없지만, 꽤 오랫동안 까마귀들의 밥이었던 것 같습니다.>', '', 28153),
(161774, 'koKR', '|TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SHARK JAWS.BLP:20|t 크라켄이 |cFFFF0000|Hspell:279897|h[심해에서 솟아오르는 공포]|h|r를 불러일으킵니다!', '|TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SHARK JAWS.BLP:20|t 크라켄이 |cFFFF0000|Hspell:279897|h[심해에서 솟아오르는 공포]|h|r를 불러일으킵니다!', 28153),
(161773, 'koKR', '|TInterface\\ICONS\\INV_Pet_BabyShark.blp:20|t 상어들이 |cFFFF0000|Hspell:279893|h[피에 물든 바다]|h|r의 냄새를 맡습니다!', '|TInterface\\ICONS\\INV_Pet_BabyShark.blp:20|t 상어들이 |cFFFF0000|Hspell:279893|h[피에 물든 바다]|h|r의 냄새를 맡습니다!', 28153),
(161772, 'koKR', '아버진 경의를 표하셨고, 나도 같은 마음이다.', '', 28153),
(161771, 'koKR', '제이나가 용서받을 거란 생각은 섣부른 것이었군. 그녀의 미래가 워낙 불확실한 터라 불안하네만, 일단은 임무에 집중해야 하네.\n\n쿨 티라스를 얼라이언스에 영입해야 해. 캐서린 프라우드무어가 우리 제안을 무시한다면, 우리에게 힘을 실어 줄 자들에게 희망을 걸어야 하네.', '', 28153),
(161770, 'koKR', '허윽...', '', 28153),
(161769, 'koKR', '얼라이언스가 여기에?', '', 28153),
(161768, 'koKR', '', '내 인생을 고고학에...', 28153),
(161767, 'koKR', '', '발굴현장에 못 오게 해라!', 28153),
(161766, 'koKR', '성물회가 내 복수를 해주리...', '', 28153),
(161765, 'koKR', '', '선워처 님에게... 알려야...', 28153),
(161764, 'koKR', '', '이봐! 여긴 호드 영토라고! 여기 넘어오면 안 되지!', 28153),
(161763, 'koKR', '계속 싸우라고, 대장! 나는... 여기서 기다릴게.', '', 28153),
(161762, 'koKR', '우리가 호드를 승리로 이끌 것이다!', '우리가 호드를 승리로 이끌 것이다!', 28153),
(161761, 'koKR', '최전방에서 보세.', '최전방에서 보세.', 28153),
(161760, 'koKR', '출항할 준비 됐나?', '출항할 준비 됐나?', 28153),
(161759, 'koKR', '적들이 우리 앞에서 벌벌 떨 거야.', '적들이 우리 앞에서 벌벌 떨 거야.', 28153),
(161758, 'koKR', '전장이 기다린다!', '전장이 기다린다!', 28153),
(161757, 'koKR', '전쟁이라면 가지가지 다 겪어 봤습니다!', '전쟁이라면 가지가지 다 겪어 봤습니다!', 28153),
(161756, 'koKR', '당신의 가지로 저를 들어올려 주시겠습니까, 고대의 존재여?', '당신의 가지로 저를 들어올려 주시겠습니까, 고대의 존재여?', 28153),
(161755, 'koKR', '호드는 왜 우릴 가만두지 않는 건지, 정말 나무랄 수밖에 없군요.', '호드는 왜 우릴 가만두지 않는 건지, 정말 나무랄 수밖에 없군요.', 28153),
(161754, 'koKR', '보랄러스의 시민이여! 두 눈을 돌려 파도를 바라보라!', '', 28153),
(161753, 'koKR', '와일드해머가 호드의 주의를 저 배로 돌려 놓도록 하겠네. 그동안 우리는 다른 배에 있는 드레븐을 노리세.', '', 28153),
(161752, 'koKR', '보랄러스로 돌아갈 준비가 됐습니다.', '보랄러스로 돌아갈 준비가 됐습니다.', 28153),
(161751, 'koKR', '', '사냥이 끝났습니다. 세계는 더 안전해졌습니다.\n\n오늘은 좋은 날이군요.', 28153),
(161750, 'koKR', '전장을 향하여!', '전장을 향하여!', 28153),
(161749, 'koKR', '앞장서시게.', '앞장서시게.', 28153),
(161748, 'koKR', '바로 그걸세! 이제 슬슬 일을 시작해보자고.', '바로 그걸세! 이제 슬슬 일을 시작해보자고.', 28153),
(161747, 'koKR', '함께 싸우겠네.', '함께 싸우겠네.', 28153),
(161746, 'koKR', '신세를 졌군, $n|1이여;여;.', '신세를 졌군, $n|1이여;여;.', 28153),
(161745, 'koKR', '우와아아! 정말 고마워요, $p 님!', '', 28153),
(161744, 'koKR', '앙켈 마일든홀에게 로잘린의 편지를 줄까요?', '앙켈 마일든홀에게 로잘린의 편지를 줄까요?', 28153),
(161743, 'koKR', '트로그 놈들이 공격하고 있소! 쿠퍼를 타고 트로그들과 한판 해 보시오.', '', 28153),
(161742, 'koKR', '안녕히!', '안녕히!', 28153),
(161741, 'koKR', '', '물론이죠. 정말 다들 너무 보고 싶어서 얼른 집에 돌아가고 싶어요. 레이몬드는 최선을 다하고 있겠지만, 손대는 일마다 혼란에 빠뜨려버리는 경향이 있으니까요!', 28153),
(161740, 'koKR', '입으면 따뜻할 겁니다.', '', 28153),
(161739, 'koKR', '그거면 될 것 같습니다.', '', 28153),
(161738, 'koKR', '그 옷이 채집에 도움이 될지도 모릅니다.', '', 28153),
(161737, 'koKR', '멋지군요, $n 님.', '', 28153),
(161736, 'koKR', '전 어둠에 얼음 화살을 날립니다!', '전 어둠에 얼음 화살을 날립니다!', 28153),
(161735, 'koKR', '감사합니다. 이번에는 꼭 잘 전달하겠습니다.', '감사합니다. 이번에는 꼭 잘 전달하겠습니다.', 28153),
(161734, 'koKR', '제 신상 정보를 보면서 맥주 흘리지 마십시오!', '제 신상 정보를 보면서 맥주 흘리지 마십시오!', 28153),
(161733, 'koKR', '전 양초를 가져갑니다.', '전 양초를 가져갑니다.', 28153),
(161732, 'koKR', '음?', '', 28153),
(161731, 'koKR', '당신이 불 속에 서 있지만 않으면 훨씬 편하게 치유할 수 있겠죠.', '당신이 불 속에 서 있지만 않으면 훨씬 편하게 치유할 수 있겠죠.', 28153),
(161730, 'koKR', '아... 그게... 편지를 제대로 전달 못 했습니다. 한 통 더 받을 수 있을까요?', '아... 그게... 편지를 제대로 전달 못 했습니다. 한 통 더 받을 수 있을까요?', 28153),
(161729, 'koKR', '이거 슬쩍해도 경비병한테 안 걸리지 않을까...', '이거 슬쩍해도 경비병한테 안 걸리지 않을까...', 28153),
(161728, 'koKR', '임무 주는 사람 괴롭히지 좀 마십시오!', '임무 주는 사람 괴롭히지 좀 마십시오!', 28153),
(161727, 'koKR', '이 나무는 불로 공격해도 멀쩡할걸요.', '이 나무는 불로 공격해도 멀쩡할걸요.', 28153),
(161726, 'koKR', '아니 음유시인이 직업이 아니라고 몇 번을 말해야 알아먹겠습니까?!', '아니 음유시인이 직업이 아니라고 몇 번을 말해야 알아먹겠습니까?!', 28153),
(161725, 'koKR', '', '반가워요, $p 님. 이렇게 빨리 다시 만날 줄은 몰랐네요. 앙켈이 제 편지를 보고 뭐라고 하던가요?', 28153),
(161724, 'koKR', '', '세상에... $p 님, 물건 잊어버리기가 습관은 아니기를 진심으로 바라요. 잠시만요... 하나 더 만들어 드릴게요.', 28153),
(161723, 'koKR', '로잘린에게 열처리한 꿀 아뮬렛을 줄까요?', '로잘린에게 열처리한 꿀 아뮬렛을 줄까요?', 28153),
(161722, 'koKR', '', '아... 오늘도 또, 피를 봤군.', 28153),
(161721, 'koKR', '', '지금 뭐라고... 앙켈이랑 레이몬드를 만나셨다고요!?', 28153),
(161720, 'koKR', '그게... 이야기가 좀 길긴 한데, 아뮬렛은 꿀로 된 일종의 살아 있는 괴물에 박혀 있었습니다. 앙켈과 레이몬드를 도와 농장을 정리하다가 발견한 겁니다.', '그게... 이야기가 좀 길긴 한데, 아뮬렛은 꿀로 된 일종의 살아 있는 괴물에 박혀 있었습니다. 앙켈과 레이몬드를 도와 농장을 정리하다가 발견한 겁니다.', 28153),
(161719, 'koKR', '이 아뮬렛을 발견했는데, 당신 것인가요?', '이 아뮬렛을 발견했는데, 당신 것인가요?', 28153),
(161718, 'koKR', '', '뭘 도와드릴까요, 친구여? 감정이 필요한 비전 도구라도 가져오셨나요?', 28153),
(161717, 'koKR', '검은 모루를 고칠 준비가 거의 다 됐네. 이제 라그나로스의 정수로 심장부 조각에 힘을 불어넣기만 하면 될걸세.', '', 28153),
(161716, 'koKR', '|cFF0000FF(퀘스트)|r 화산 심장부로 갈 준비가 되었습니다.', '|cFF0000FF(퀘스트)|r 화산 심장부로 갈 준비가 되었습니다.', 28153),
(161715, 'koKR', '아름답지 않나? 이제 여길 빠져나가세. 굴착기 덕에 무사히 스톰윈드로 돌아갈 수 있을 걸세.', '', 28153),
(161714, 'koKR', '그 말 그대로 돌려주지, 포자형.', '', 28153),
(161713, 'koKR', '널 동급으로 생각한 적 없다!', '', 28153),
(161712, 'koKR', '누구에게 더 실망하실지 가늠하기 어렵군.', '', 28153),
(161711, 'koKR', '포자아버지가 우리 모습을 보면 어떻게 생각할까?', '', 28153),
(161710, 'koKR', '두고 보지, 포자형.', '', 28153),
(161709, 'koKR', '넌 한참 멀었어.', '', 28153),
(161708, 'koKR', '나머지는 걸어서 가야겠구먼.', '', 28153),
(161707, 'koKR', '그래, 그런 일도 있지. 예비품이 있어서 다행일세.', '', 28153),
(161706, 'koKR', '왼쪽! 오른쪽! 외... 용암!', '', 28153),
(161705, 'koKR', '윽! 옷에 묻은 모래를 다 털어내려면 평생 걸리겠군.', '', 28153),
(161704, 'koKR', '아악! 조심해!', '', 28153),
(161703, 'koKR', '화물칸을 조금만 더 채우고 나면, 이 저주받은 해안에서도... 이 냄새에서도... 다 벗어날 수 있겠지.', '', 28153),
(161702, 'koKR', '아무튼, 내 전차를 몰고 가면 일이 조금은 쉬워질 걸세. 내가 준비하는 동안 어디 긁히지 않게 조심해주게.', '', 28153),
(161701, 'koKR', '말할 것도 없네만, 심장부 조각을 얻으려면 먼저 늙다리 게즈로크와 볼일도 봐야 하겠고 말일세.', '', 28153),
(161700, 'koKR', '선원들이 일정한 속도로 일하지 않는 건가?', '', 28153),
(161699, 'koKR', '문제는 라그나로스의 옛날 둥지로 가는 길목을 불타는 괴물들이 지키고 있다는 거지.', '', 28153),
(161698, 'koKR', '그래, $n. 잽싸게 물건을 슬쩍해오는 일이라 생각할 수도 있겠네만, 뭐, 그정도면 거의 정답일세.', '', 28153),
(161697, 'koKR', '너희 선원들이 한심한 정도에서 조금 더 나은 수준만 된다면, 그것만으로도 충분히 놀랍겠다만.', '', 28153),
(161696, 'koKR', '당장 해야 할 일에 집중하길 권해주고 싶군.', '', 28153),
(161695, 'koKR', '솔직히, 너희 지도자의... 정치적 위치가... 나나 내가 대표하는 이들이나, 그중 아무와도 상관이 없어서 말이지.', '', 28153),
(161694, 'koKR', '그래, 그래... 말해봐.', '', 28153),
(161693, 'koKR', '아무도 그렇게 되길 바라지 않는다고!', '', 28153),
(161692, 'koKR', '이봐, 돈주머니, 이렇게 계속 선원도 잃고 장비도 계속 고장이 난다면, 그 앙상하고 작은 엘프 다리로 아제라이트를 짊어져야 할 거야.', '', 28153),
(161691, 'koKR', '그래, 넌 상관 없겠지.', '', 28153),
(161690, 'koKR', '그렇습죠, 모이라 님. 미안하네, $n.', '', 28153),
(161689, 'koKR', '', '검은 금고에 광석을 끝도 없이 쌓아 둔 걸 나도 알고 너도 알지.', 28153),
(161688, 'koKR', '', '욕심 부리지 마라, 테일린. $n|1은;는; 아주 중요한 임무를 앞두고 있다고.', 28153),
(161687, 'koKR', '검은 모루는 가장 순도 높은 무쇠로 만들어지지. 그걸 어떻게 제련하고 정제하는지는 신뢰할 수 있는 광부들과 대장장이들에게만 알려 줄 수 있네.', '', 28153),
(161686, 'koKR', '이걸 고치려면 검은무쇠를 아주 산더미처럼 모아야 하네!', '', 28153),
(161685, 'koKR', '', '예상하시겠지만, 쿨 티라스에서 난리를 피우고 있는 이 호드 놈들의 배후에는 볼라스가 있습니다.\n\n처음엔 아쉬란, 그 다음엔 페랄라스 연안의 그 섬, 그리고 이제 여기까지... 정말 떨어지지 않는 독감 같은 작자죠.', 28153),
(161684, 'koKR', '전투 기술을 닦기에는 결투가 좋은 방법인 것 같습니다...\n\n저요? 저에게는 얼라이언스만한 훈련용 허수아비가 없지요.', '전투 기술을 닦기에는 결투가 좋은 방법인 것 같습니다...\n\n저요? 저에게는 얼라이언스만한 훈련용 허수아비가 없지요.', 28153),
(161683, 'koKR', '잔달라 항구에 있는 밴시의 비명호에서 만나세.', '', 28153),
(161682, 'koKR', '병사들이여, 대형을 다시 갖춰라!', '병사들이여, 대형을 다시 갖춰라!', 28153),
(161681, 'koKR', '다음 증원 분대가 출항을 준비하고 있습니다.', '다음 증원 분대가 출항을 준비하고 있습니다.', 28153),
(161680, 'koKR', '전장의 부름에 답해주십시오.', '전장의 부름에 답해주십시오.', 28153),
(161679, 'koKR', '이날을 위해 훈련했습니다.', '이날을 위해 훈련했습니다.', 28153),
(161678, 'koKR', '전장이 기다립니다.', '전장이 기다립니다.', 28153),
(161677, 'koKR', '좋아, $n. 그 심장부를 한 덩이 챙겨서 위의 동굴로 돌아가세. 나는 굴착기를 준비해 놓겠네.', '', 28153),
(161676, 'koKR', '당신 같은 $c|1이라면;라면; 우리 사이에서 잘 해낼 수 있을 거요.', '당신 같은 $c|1이라면;라면; 우리 사이에서 잘 해낼 수 있을 거요.', 28153),
(161675, 'koKR', '전투를 준비합시다.', '전투를 준비합시다.', 28153),
(161674, 'koKR', '좋지!', '', 28153),
(161673, 'koKR', '그래, 그렇겠지. 날 쓰러뜨리면 심장부의 조각을 가지고 돌아갈 수 있을 것이다.', '', 28153),
(161672, 'koKR', '검은 모루를 고칠 때 쓸 화산 심장부의 조각이 필요하다.', '', 28153),
(161671, 'koKR', '무엇을 구하느냐, 불의 자손아?', '', 28153),
(161670, 'koKR', '검은무쇠 부족의 테일린 다크앤빌이다.', '', 28153),
(161669, 'koKR', '누가 다가오는가?', '', 28153),
(161668, 'koKR', '잘했다. 화산 심장부의 조각을 손에 넣었구나. 현명하게 사용하거라.', '', 28153),
(161667, 'koKR', '트렘블레이드는 자기 오합지졸 얼라이언스 부하들을 데리고 우릴 이길 수 있다고 생각하네.\n\n그 오만함은 곧 파멸로 이어질 걸세.', '', 28153),
(161666, 'koKR', '', '당신에게만 말씀드리는 거지만, 매의 수가 줄어 조금 기쁩니다.\n\n새가 싫다거나 그런 건 아니지만, 저는 이곳의 북슬북슬한 녀석들에게 정들었거든요.\n\n매가 없으니, 토끼들도 조금 더... 살아 있을 수 있답니다.', 28153),
(161665, 'koKR', '얼라이언스를 위하여!', '그리고 쓰러진 자들을 위하여... 엘룬 아도레.', 28153),
(161664, 'koKR', '아, 폴스타트! 도착 했군.', '', 28153),
(161663, 'koKR', '이곳을 떠나라!', '이곳을 떠나라!', 28153),
(161662, 'koKR', '이 땅을 더럽힐 순 없다!', '이 땅을 더럽힐 순 없다!', 28153),
(161661, 'koKR', '영혼들이... 날 맞이한다...', '영혼들이... 날 맞이한다...', 28153),
(161660, 'koKR', '우리 모두를 죽일 순 없다...', '우리 모두를 죽일 순 없다...', 28153),
(161659, 'koKR', '영혼들에게 간다...', '영혼들에게 간다...', 28153),
(161658, 'koKR', '이럴 리가... 없는데...', '이럴 리가... 없는데...', 28153),
(161657, 'koKR', '호드는... 건재하다...', '호드는... 건재하다...', 28153),
(161656, 'koKR', '호드를 위하여!', '호드를 위하여!', 28153),
(161655, 'koKR', '꼼짝 마라!', '꼼짝 마라!', 28153),
(161654, 'koKR', '부정한 주술이 너를 덮칠 것이다!', '부정한 주술이 너를 덮칠 것이다!', 28153),
(161653, 'koKR', '우릴 막을 순 없다...', '우릴 막을 순 없다...', 28153),
(161652, 'koKR', '', '언더시티에 있는 내 방으로 오거라. 앞으로의 행보를 의논하자... 은밀하게.', 28153),
(161651, 'koKR', '위스키요? 그런 건 손에 대지도 마십시오.\n\n아니요. 전 그냥 프렛첼이나 먹으려고 온 겁니다.', '', 28153),
(161650, 'koKR', '고맙소, 마법학자. 당신의 통찰력이 큰 도움이 될 거요.', '', 28153),
(161649, 'koKR', '도움이 될 만한 것이 기억나면 뭐든지 말씀해 드리겠습니다.', '', 28153),
(161648, 'koKR', '진짜 갤리윅스는 하나뿐이니 우리가 그를 찾아낼 겁니다. 쇼에게 미끼에 관해 알리겠습니다.', '', 28153),
(161647, 'koKR', '', '갤리윅스가 한 명만 있어도 아제로스는 이미 벅찬데, 이제는... 어떻게 생각해요, 할포드? 수십 명쯤 될까요?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161645, 'koKR', '누가 저 $pr놈 좀 처리해! 그리고 다른 놈은 발코니로 코코아 버터 가져와!', '', 28153),
(161644, 'koKR', '갈 준비가 됐어요!', '갈 준비가 됐어요!', 28153),
(161643, 'koKR', '$n 님, 무사히 도착하셨군요! 당신을 울파르 님께 데려다줄 테니 준비가 되면 알려주십시오.', '', 28153),
(161642, 'koKR', '고블린 잔치는 도통 이해를 못 하겠습니다.', '', 28153),
(161641, 'koKR', '다시는 이곳에 관해 언급하지 말죠.', '', 28153),
(161640, 'koKR', '다른 고블린들은 굶고 있는데, 여기서는 이렇게 실컷 먹어대면서 자원을 낭비하고 있다니.', '', 28153),
(161639, 'koKR', '으, 이 지독한 냄새는 또 뭡니까?', '', 28153),
(161638, 'koKR', '살면서 지금처럼 씻고 싶었던 적이 없었습니다.', '', 28153),
(161637, 'koKR', '저 더러운 수영장에는 발가락 하나조차 담그고 싶지 않습니다. 저 안에서 도대체 무슨 일을 하고 있었는지 누가 알겠습니까.', '', 28153),
(161636, 'koKR', '물론 놈들은 쓰레기를 그냥 물에 던져 버립니다. 이렇게 천박할 데가.', '', 28153),
(161635, 'koKR', '이 아름다운 자연 풍경을... 조잡한 인공 잔디밭이 망치고 있군요.', '', 28153),
(161634, 'koKR', '폐에 연기가 들어차며 몸이 무거워집니다...', '폐에 연기가 들어차며 몸이 무거워집니다...', 28153),
(161633, 'koKR', '', '당신을... 찾아서... 정말 다행이에요...', 28153),
(161632, 'koKR', '', '영웅이여? 제 목소리 들리나요?', 28153),
(161631, 'koKR', '불길이 걷혔습니다! 달의 신전으로 가세요!', '불길이 걷혔습니다! 달의 신전으로 가세요!', 28153),
(161630, 'koKR', '이샬라! 이샬라! 어디에 있는 거니?!? 이샬라, 제발 대답 좀 해 주렴!', '이샬라! 이샬라! 어디에 있는 거니?!? 이샬라, 제발 대답 좀 해 주렴!', 28153),
(161629, 'koKR', '아이 없이는 떠날 수 없어요. 제발 누가 좀 도와주세요!', '아이 없이는 떠날 수 없어요. 제발 누가 좀 도와주세요!', 28153),
(161628, 'koKR', '제발, 내 가족을 찾아 주십시오!', '제발, 내 가족을 찾아 주십시오!', 28153),
(161627, 'koKR', '제발 도와주세요! 딸아이가 없어졌어요!', '제발 도와주세요! 딸아이가 없어졌어요!', 28153),
(161626, 'koKR', '어서. 제이나가 기다리네.', '', 28153),
(161625, 'koKR', '자네에겐 기회가 한 번 더 있네.', '', 28153),
(161624, 'koKR', '내 아들을 볼 수 있다면 난 뭐든 했을 거야.', '', 28153),
(161623, 'koKR', '살아 있다면, 늦은 건 없네.', '', 28153),
(161622, 'koKR', '', '그러기엔 너무 늦었소.', 28153),
(161621, 'koKR', '캐서린, 제이나가 자넬 부르고 있어... 손을 내밀어야 하네.', '', 28153),
(161620, 'koKR', '', '겐... 딸이 불타고 있었소.', 28153),
(161619, 'koKR', '', '... 꿈에서... 딸을 보오.', 28153),
(161618, 'koKR', '... 지금도 혹독히 치르고 있지. 아닌가?', '', 28153),
(161617, 'koKR', '제이나는 그저 자신의 마음을 따랐지. 그 대가는 톡톡히 치렀고.', '', 28153),
(161616, 'koKR', '', '제이나는 왕국을 배신했소.', 28153),
(161615, 'koKR', '제이나가 있네.', '', 28153),
(161614, 'koKR', '', '이제 그 무엇도... 남지... 않았어...', 28153),
(161613, 'koKR', '', '프리실라, 한때 나의 소중했던 벗이... 내 마음에 대못을 박았지.', 28153),
(161612, 'koKR', '', '어떻게 해야 할지 모르겠어, 댈린. 뭘 믿어야 할지도... 누굴 믿어야 할지도.', 28153),
(161611, 'koKR', '제이나든, 쿨 티란이든, 모든 얼라이언스든, 필요하다면 누구하고라도 싸우겠네.\n\n난 호드를 아끼네. 스랄에게 호드를 지키겠다고 약속까지 했지.\n\n누가 전쟁을 일으켰는지는 중요하지 않아. 마지막까지 싸울 걸세, 전쟁이 끝날 때까지... 아니면 내 목숨이 끝장날 때까지.', '', 28153),
(161610, 'koKR', '다르나서스를 잃을 순 없어... 이렇게 잃을 순 없어요!', '다르나서스를 잃을 순 없어... 이렇게 잃을 순 없어요!', 28153),
(161609, 'koKR', '망할 놈의 호드! 전부 지옥에나 떨어져라!', '망할 놈의 호드! 전부 지옥에나 떨어져라!', 28153),
(161608, 'koKR', '...어찌 된 건지... 모르겠어요...', '...어찌 된 건지... 모르겠어요...', 28153),
(161607, 'koKR', '고마워요! 다른 사람들도 살아남았어야 할 텐데...', '고마워요! 다른 사람들도 살아남았어야 할 텐데...', 28153),
(161606, 'koKR', '제이나 프라우드무어와 싸우겠다고요?', '제이나 프라우드무어와 싸우겠다고요?', 28153),
(161605, 'koKR', '제이나 프라우드무어 말일세.\n\n한때는 자신의 아버지가 저지른 횡포로부터 우리를 구해 주기도 했었지. 그 용단은 높이 사네. 어려운 결정이었을 테니까.\n\n하지만 헬스크림이 테라모어에 저지른 짓은 결코 용납하지 못하더군. 그 원망의 화살은 결국 호드 전체에게로 향하게 됐네.\n\n이미 선을 넘었어. 너무 많은 살상을 저질렀지. 복수를 향한 그녀의 집착에 종지부를 찍을 때가 됐네.', '', 28153),
(161604, 'koKR', '고맙습니다... 살아남지 못할 줄 알았어요.', '고맙습니다... 살아남지 못할 줄 알았어요.', 28153),
(161603, 'koKR', '전부... 불타고 있어요...', '전부... 불타고 있어요...', 28153),
(161602, 'koKR', '엘룬이 당신을 축복하기를...', '엘룬이 당신을 축복하기를...', 28153),
(161601, 'koKR', '$n 님, 엘룬의 찬양을 당신께.', '$n 님, 엘룬의 찬양을 당신께.', 28153),
(161600, 'koKR', '보랄러스로 보내 주세요!', '보랄러스로 보내 주세요!', 28153),
(161599, 'koKR', '', '반갑습니다, $c님. 보랄러스로 돌아가시겠어요?', 28153),
(161598, 'koKR', '', '반가워요, $c님. 전선으로 향하는 길이신가요?', 28153),
(161597, 'koKR', '\"그 여자\"라니, 누구 말입니까?', '\"그 여자\"라니, 누구 말입니까?', 28153),
(161596, 'koKR', '숨을... 쉴 수가 없어...', '숨을... 쉴 수가 없어...', 28153),
(161595, 'koKR', '드러나지 않은 길에 있던 사냥꾼들과는 동질감을 느꼈네. 우리 모두 부서진 섬을 지키기 위해 싸웠지.\n\n허나 전쟁의 뿔피리 소리가 다시 한 번 들려왔네.\n\n그 여자가 돌아왔다는 소식을 들었고... 부름에 응해야만 했네.', '', 28153),
(161594, 'koKR', '렉사르, 어쩌다 이 문제에 엮인 거죠?', '렉사르, 어쩌다 이 문제에 엮인 거죠?', 28153),
(161593, 'koKR', '제발 도와주세요!', '제발 도와주세요!', 28153),
(161592, 'koKR', '불 좀 꺼 주세요! 아무도 없나요?!', '불 좀 꺼 주세요! 아무도 없나요?!', 28153),
(161591, 'koKR', '또 다른 전쟁이 우릴 기다리는 것 같군.\n\n잡담이나 할 시간이 없네.', '', 28153),
(161590, 'koKR', '너무... 뜨거워...', '너무... 뜨거워...', 28153),
(161589, 'koKR', '왜 이런 일이 벌어지는 거죠?!', '왜 이런 일이 벌어지는 거죠?!', 28153),
(161588, 'koKR', '아아아아악!!', '아아아아악!!', 28153),
(161587, 'koKR', '물이 필요해요! 제발! 도와주세요!', '물이 필요해요! 제발! 도와주세요!', 28153),
(161586, 'koKR', '엘룬이시여, 우리를 구하소서!', '엘룬이시여, 우리를 구하소서!', 28153),
(161585, 'koKR', '그래, 집중해야지. 당장 닥친 일에. 나타노스 님을 기쁘게 하고, 가족들을 지켜야지.\n\n이제 내 할 일을 해야겠네, $n|1이여;여;.', '', 28153),
(161584, 'koKR', '집중하십시오, 젤링 수사님!', '집중하십시오, 젤링 수사님!', 28153),
(161583, 'koKR', '아내와 아이들은 내 전부라네!\n\n이... 이제 가족들이 더는 날 보고 싶어 하지 않는다는 건 아네. 하지만 상황은 바뀔 수도 있지!\n\n난 아네. 가족들이 나를 알아보고, 또 내가 아직도 자기들을 사랑한다는 사실을 알게 되면, 날 다시... 받아줄 거라는 걸...\n\n나는... 난...', '', 28153),
(161582, 'koKR', '아직도 가족을 생각하고 계시는군요.', '아직도 가족을 생각하고 계시는군요.', 28153),
(161581, 'koKR', '잘 모르겠군... 난 아직...\n\n쉽지 않은 과정일세, $n|1이여;여;.\n\n보스 님께선 당장 눈앞의 일에 집중하라고 하셨네. 나타노스 님께 내 가치를 증명하는 것이 가족을 지키는 가장 좋은 방법이라고 말이네.\n\n나의 가족...', '', 28153),
(161580, 'koKR', '변화는 어떻게 되어 갑니까, 젤링?', '변화는 어떻게 되어 갑니까, 젤링?', 28153),
(161579, 'koKR', '포세이큰의 대의를 돕는 일이라면 난 뭐든지 하겠네.', '', 28153),
(161578, 'koKR', '줄다자르로 보내 주세요!', '줄다자르로 보내 주세요!', 28153),
(161577, 'koKR', '', '트롬카, $c|1이여;여;. 줄다자르로 돌아갈 텐가?', 28153),
(161576, 'koKR', '', '나는 언데드를 증오하도록 교육받았네. 언데드를 파괴하도록 말이지.\n\n덕분에 내가 포세이큰이 되었을 때 가장 증오했던 게 바로 나 자신이었다네.\n\n하지만 이젠 아네. 그런 악의를 조장하는 게 바로 얼라이언스라는 걸. 인간 왕국이 왜 한때 형제자매였던 우릴 피하는지 아나? 우리를 보면 육체의 가면 속에 감춰진 자기 자신이 떠오르거든.\n\n이제 놈들의 뿌리 깊은 증오의 굴레를 끊을 때가 왔네. 얼라이언스는 무너져야 하네.', 28153),
(161575, 'koKR', '', '어둠은 빛 앞에 머무를 수 없어!', 28153),
(161574, 'koKR', '역겨운 부두술이군.', '', 28153),
(161573, 'koKR', '괜찮습니다.', '괜찮습니다.', 28153),
(161572, 'koKR', '그 무엇이 호드를 막겠는가!', '', 28153),
(161571, 'koKR', '얼라이언스에 대해선 어떠신가요?', '얼라이언스에 대해선 어떠신가요?', 28153),
(161570, 'koKR', '', '실바나스 님께서 이 전쟁을 이용해 더 많은 포세이큰을 세상으로 내보내실 거라는 사실은 누구라도 알 수 있다네.\n\n내가 포세이큰으로 변했던 과정은... 순탄치 않았지. 처리해야 할 일도 많았고, 풀어야 할 원한도 많았다네.\n\n아직도 완전히 털어 버린 건 아니야. 하지만 새로이 되살아난 이들이 적응하는 것을 도와주는 것이 내 의무라는 생각도 든다네. 어쩌면 내가 견뎌야 했던 고통을 겪지 않도록 도와줄 수 있을지도 모르지.', 28153),
(161569, 'koKR', '그렇게 말한다면야, 알겠네.', '그렇게 말한다면야, 알겠네.', 28153),
(161568, 'koKR', '모든 일이 순조롭게 진행되고 있습니다. 편히 맥주를 즐기십시오.', '모든 일이 순조롭게 진행되고 있습니다. 편히 맥주를 즐기십시오.', 28153),
(161567, 'koKR', '감사합니다, 먼지투성이 친구여. 하지만 저희끼리 움직이는 편이 더 빠릅니다.', '감사합니다, 먼지투성이 친구여. 하지만 저희끼리 움직이는 편이 더 빠릅니다.', 28153),
(161566, 'koKR', '도움이 필요한가, 엘프 친구들? 우리 검은무쇠가 해결해 줄 수 있다고!', '도움이 필요한가, 엘프 친구들? 우리 검은무쇠가 해결해 줄 수 있다고!', 28153),
(161565, 'koKR', '무슨 기회 말입니까?', '무슨 기회 말입니까?', 28153),
(161564, 'koKR', '', '권력자들이 내 기술에 흥미를 느낀 것 같네. 그들은 나의 도움을... \"요청\"했지.\n\n내 말의 숨은 의미를 간파했나? 미안하군. 내 직업에 어울리지 않게, 은밀하게 돌려 얘기하는 건 내 전문이 아니라서 말이야.\n\n어쨌든 중요한 건, 나는 기회가 오면 절대 놓치지 않는다는 거지.', 28153),
(161563, 'koKR', '호드를 받아들이신 모양이군요.', '호드를 받아들이신 모양이군요.', 28153),
(161562, 'koKR', '할포드, 이제 배를 날려버립시다.', '할포드, 이제 배를 날려버립시다.', 28153),
(161561, 'koKR', '탈것이 필요하신가요?', '', 28153),
(161560, 'koKR', '탈것이 필요하십니까?', '', 28153),
(161559, 'koKR', '브루스턴 대장이 그러는데, 당신이 이 근처를 구경시켜 줄 수 있다더군요.', '브루스턴 대장이 그러는데, 당신이 이 근처를 구경시켜 줄 수 있다더군요.', 28153),
(161558, 'koKR', '감사합니다.', '감사합니다.', 28153),
(161557, 'koKR', '위스텔이 그러는데, 당신이 이 근처를 구경시켜 줄 수 있다더군요.', '위스텔이 그러는데, 당신이 이 근처를 구경시켜 줄 수 있다더군요.', 28153),
(161556, 'koKR', '감사합니다.', '감사합니다.', 28153),
(161555, 'koKR', '이만하면 됐습니다. 내려가시지요.', '', 28153),
(161554, 'koKR', '저 앞을 보시면 높은 감시대가 보일 겁니다. 그 뒤에 있는 곳이요? 그곳이 바로 아르고로크입니다. 적진입니다. 우리가 정복해야 할 곳이지요.', '', 28153),
(161553, 'koKR', '저쪽이요? 저기는 뉴스테드입니다. 농장과 초원이 가득하지요. 음식도 괜찮습니다.', '', 28153),
(161552, 'koKR', '동쪽에는 정령의 마법진이 있습니다. 커다란 돌 토템이며 엄청나게 거대한 화염 정령이 있고 땅에는 커다란 마법진이 그려져 있지요. 주술사들이 아주 좋아하는 곳입니다.', '', 28153),
(161551, 'koKR', '걱정하지 마십시오. 멀리 가지 않을 테니까요. 호드와 전투를 벌이고 있는 곳이 어디인지 알려드리고 싶었을 뿐입니다. 혹시나 해서 말입니다만 놈들을 처치할 상황이 될 수도 있으니까요.', '', 28153),
(161550, 'koKR', '스트롬가드 목재의 고향, 고원 제재소에 온 것을 환영합니다. 뭐, 평소 같았다면 이곳에서 목재를 가져왔을 겁니다. 지난번에 호드가 우릴 몰아낸 이후 제재소가 다시 자연의 일부가 되긴 했지만 말입니다.\n\n걱정할 필요는 없습니다. 보병 몇을 이곳에 주둔시키면 제재소를 다시 가동할 수 있을 겁니다.', '', 28153),
(161549, 'koKR', '스트롬가드 목재의 고향, 고원 제재소에 온 것을 환영합니다.\n\n오늘따라 숲이 조용하군요. 농부 하나가 곰이랑 싸움이 붙은 거 말고는, 별일 없습니다. 농부들과 있는 게 어떤지 잘 알지 않으십니까.', '', 28153),
(161548, 'koKR', '', '$n 님, 맞죠? 저는 툴리라고 해요.\n\n<굳은살이 박인 손을 내미는 현장감독 툴리>\n\n여기는 갤슨의 광맥입니다. 평소 같으면 저희 광부들이 전쟁 지원을 위해 광석을 캐고 있었겠지만 지난번 호드 공격 이후 쫓겨나고 말았어요.\n\n브루스턴 님께 지원병이 필요하다고 전해 주세요. 저희는 일할 준비가 되었지만 싸우지 않고서는 광산 안으로 들어갈 수 없을 테니까요.', 28153),
(161547, 'koKR', '', '$n 님, 맞죠? 저는 툴리라고 해요.\n\n<굳은살이 박인 손을 내미는 현장감독 툴리>\n\n딱히 보고할 사항은 없어요. 호드는 여전히 골칫거리이고 코볼트는 계속... 귀찮게 굴지만, 저희가 해결할 수 있어요.', 28153),
(161546, 'koKR', '이만하면 됐어요. 내려가시죠.', '', 28153),
(161545, 'koKR', '저 앞을 보시면 높은 감시대가 보일 거예요. 그 뒤에 있는 곳이요? 그곳이 바로 스트롬가드 요새입니다. 적진이지요. 우리가 정복해야 할 곳이랍니다.', '', 28153),
(161544, 'koKR', '저쪽이요? 저기는 뉴스테드예요. 농장과 초원이 가득하지요. 평범한 동네랍니다.', '', 28153),
(161543, 'koKR', '동쪽에는 정령의 마법진이 있어요. 커다란 돌 토템이며 엄청나게 거대한 화염 정령이 있고 땅에는 커다란 동그라미들이 그려져 있지요. 주술사들이 아주 좋아하는 곳이에요.', '', 28153),
(161542, 'koKR', '걱정하지 마세요. 멀리 가지 않을 테니까요. 얼라이언스와 전투를 벌이고 있는 곳이 어디인지 알려드리고 싶었을 뿐이에요. 혹시나 말이지만 놈들을 처치해야 할 상황이 될 수도 있으니까요.', '', 28153),
(161541, 'koKR', '아르고로크 목재의 고향, 손도끼 마루에 온 것을 환영하오. 뭐, 평소 같았다면 이곳에서 목재를 가져왔을 거요. 지난번에 얼라이언스가 우릴 몰아낸 이후 제재소가 다시 자연의 일부가 되긴 했지만 말이오.\n\n걱정할 필요는 없소. 그런트 몇을 이곳에 주둔시키면 제재소를 다시 가동할 수 있을 거요.', '', 28153),
(161540, 'koKR', '아르고로크 목재의 고향, 손도끼 마루에 온 것을 환영하오.\n\n오늘따라 숲이 조용하군. 일꾼 하나가 곰이랑 싸움이 붙은 거 말고는, 별일 없소. 일꾼들과 있는 게 어떤지 잘 알지 않소.', '', 28153),
(161539, 'koKR', '$n 님, 맞소? 난 드로그라고 하오.\n\n<굳은살이 박인 손을 내미는 현장감독 드로그>\n\n여기는 마른수염 광산이오. 평소 같으면 우리 광부들이 전쟁 지원을 위해 광석을 캐고 있었을 테지만, 지난번 얼라이언스의 공격 이후 쫓겨나고 말았다오.\n\n위스텔에게 지원병이 필요하다고 전해주시오. 우리는 일할 준비가 되었지만 놈들이 순순히 광산 안으로 들여보내 주지 않을 거요.', '', 28153),
(161538, 'koKR', '', '$n 님, 맞소? 난 드로그라고 하오.\n\n<굳은살이 박인 손을 내미는 현장감독 드로그>\n\n딱히 보고할 사항은 없소. 얼라이언스는 여전히 골칫거리이고 코볼트는 계속... 귀찮게 굴지만, 우리가 해결할 수 있소.', 28153),
(161537, 'koKR', '실버문이 호드의 편에 서 있는 이상, 우리를 불신하는 자들은 언제나 존재할 것입니다.\n\n하지만 우리가 있을 곳은 얼라이언스입니다. 그 어느 때보다 확신이 듭니다.\n\n계속해서 버티십시오, $n 님. 얼라이언스의 동지들에게 우리가 같은 대의를 위해 싸운다는 사실을 보여주십시오.\n\n언젠가 우리의 땅이 호드의 손아귀에서 벗어나고, 쿠엘탈라스의 아이들이 다시 하나가 될 날이 올 것입니다.\n\n저는 알고 있습니다.', '', 28153),
(161536, 'koKR', '우리가 얼라이언스의 신뢰를 얻었다고 생각하십니까?', '우리가 얼라이언스의 신뢰를 얻었다고 생각하십니까?', 28153),
(161535, 'koKR', '당신과 마찬가지로 저도 속삭임을 막는 데 힘쓰며 지냅니다. 감사하게도 알레리아 윈드러너 님께서 계속해서 인도해 주십니다.\n\n그분께서 도와주시지 않았더라면... 저희 모두가 길을 잃었겠지요.\n\n처음에는 대하기 껄끄러웠지만 공간 방랑자에게도 많은 것을 배웠습니다. 그가 제안하는 모든 것은 결국 그 자신의 목적을 성취하기 위해서라는 사실만 기억하고 계시면 됩니다.', '', 28153),
(161534, 'koKR', '잘 지내셨나요, 마법학자 엄브릭?', '잘 지내셨나요, 마법학자 엄브릭?', 28153),
(161533, 'koKR', '우리는 편의를 위해 얼라이언스의 편에 선 것이 아닙니다. 알레리아 님께 단순히 감사를 표하기 위해서도 아니지요.\n\n우리는 시련을 통해, 강력한 힘은 올바른 자의 손에 있어야 한다는 것을 배웠습니다. 호드가 우리의 지식을 손에 넣거나 우리를 무기처럼 사용하는 것을 두고 볼 수는 없습니다.\n\n우리는 얼라이언스의 가치관에 동의하기에 그편에 섭니다. 그리고 언젠가 모든 실버문 시민이 돌아와 다시 모일 것을 염원합니다.', '', 28153),
(161532, 'koKR', '이제 당신은 얼라이언스를 위해 싸우죠.', '이제 당신은 얼라이언스를 위해 싸우죠.', 28153),
(161531, 'koKR', '저는 추종자들을 에테리얼의 덫으로 이끌고 말았습니다. 알레리아 윈드러너 님께서 도와주시지 않았더라면 모두 길을 잃고 말았을 겁니다.\n\n암흑 마력이 우리를 변화시켰고... 공허의 속삭임에 마음을 열게 했습니다. 알레리아 님의 인도가 없었더라면 모두 광기에 빠져 버렸을 것입니다.\n\n알레리아 님께서 우리의 마음을 진정시키고, 속삭임을 잠재우는 것을 도와주고 계십니다. 지금도 저희는 광기에 저항하고 있습니다.', '', 28153),
(161530, 'koKR', '공허가 당신을 거의 집어삼킬 뻔했다고요?', '공허가 당신을 거의 집어삼킬 뻔했다고요?', 28153),
(161529, 'koKR', '저와 추종자들은 호드에 충성심을 느끼지 않았습니다. 대마법학자 롬매스께서 공허 연구를 금지하셨을 때, 우리는 망설이지 않고 달아나 우리만의 길을 갔죠.\n\n하지만 저는 자만심에 덜미를 잡혔습니다. 제가 마주하는 모든 힘에 숙달할 수 있다고 생각했던 겁니다.\n\n정말이지 어리석었습니다...', '', 28153),
(161528, 'koKR', '어둠의 힘을 추구하셨다는 말씀입니까?', '어둠의 힘을 추구하셨다는 말씀입니까?', 28153),
(161527, 'koKR', '마법학자로서 저의 임무는 언제나 실버문과 그 시민들을 향해 있었습니다. 광기의 아서스가 우리의 땅을 파괴했을 때, 저는 실버문이 살아남기 위해서는 우리의 모든 힘을 억눌러야 한다는 사실을 알았습니다.\n\n캘타스 왕자가 한 가지 방법을 내놓았지만 저는 그와 다른 방법을 찾았습니다.', '', 28153),
(161526, 'koKR', '이 대장정에서 당신의 역할은 무엇입니까?', '이 대장정에서 당신의 역할은 무엇입니까?', 28153),
(161525, 'koKR', '', '가실까요, 용사여?', 28153),
(161524, 'koKR', '벌써 온 겁니까?', '', 28153),
(161523, 'koKR', '플루트를 어디에다 뒀는지 모르겠어요.', '플루트를 어디에다 뒀는지 모르겠어요.', 28153),
(161521, 'koKR', '대단하군. 고맙소, 마법학자여.', '', 28153),
(161520, 'koKR', '이 배를 타고 당신과 함께 가겠습니다. 그동안 전략을 짤 수 있을 겁니다.', '', 28153),
(161519, 'koKR', '도착하는 시간에 맞춰 해안에서 기다리고 있을 겁니다. 상세한 정찰 보고도 받을 수 있을 테죠.', '', 28153),
(161518, 'koKR', '고맙소, 마법학자 엄브릭. 그들과 접선하려면 시간이 얼마나 걸릴 것 같소?', '', 28153),
(161517, 'koKR', '총사령관님, 자이발라에서 최고의 정찰병과 암살자들로 이루어진 부대와 접선하기로 했습니다.', '', 28153),
(161516, 'koKR', '', '구경꾼이 왔나, 잘 됐군! 꼼짝 말거라, 얼라이언스의 개야. 너희 위대한 영웅이 내 손에 사라지는 모습을 보거라!', 28153),
(161515, 'koKR', '아라시 고원으로 보내 주세요!', '아라시 고원으로 보내 주세요!', 28153),
(161514, 'koKR', '', '트롬카, $c|1이여;여;. 전선으로 향하는 길인가?', 28153),
(161513, 'koKR', '', '안녕하세요! 여기 정말 멋지죠? 제일 좋아하는 술집을 하나만 꼽긴 어렵지만 장담하는데, 여긴 10위 안에는 가뿐히 드는 곳이죠.', 28153),
(161512, 'koKR', '우리 함선에 비할 수 있는 함선은 없습니다. 절대로요.', '우리 함선에 비할 수 있는 함선은 없습니다. 절대로요.', 28153),
(161511, 'koKR', '파도어머니께 영광을.', '파도어머니께 영광을.', 28153),
(161510, 'koKR', '바다의 목소리를 들으십시오. 바다만이 진실을 보여줍니다.', '바다의 목소리를 들으십시오. 바다만이 진실을 보여줍니다.', 28153),
(161509, 'koKR', '', '아, 이봐요, 드러스트 유물이 하나 더 생겼네요. 제인에게 가져가는 게 좋겠습니다.', 28153),
(161508, 'koKR', '파도가 당신을 인도하길.', '파도가 당신을 인도하길.', 28153),
(161507, 'koKR', '', '흐음. 채광용 곡괭이가 점점 헐거워지네요. 그릭스에게 봐 달라고 해야겠습니다.', 28153),
(161506, 'koKR', '', '배가 고프군요. 알란을 데려다주고 바이론 형제네 가게에 가야겠습니다.', 28153),
(161505, 'koKR', '', '인정하고 싶지는 않지만 프랭클린이 여기 있을 때 물건을 옮기기가 훨씬 수월했습니다.', 28153),
(161504, 'koKR', '', '누추한 여관이지만 어서오세요. 무엇을 도와드릴까요?', 28153),
(161503, 'koKR', '', '보랄러스로 돌아가는 걸 도와드릴까요?', 28153),
(161502, 'koKR', '$p 님, 우리의 진정한 동맹임을 몸소 증명해 주었군요.\n\n저희 마차는 언제나 당신을 환영합니다. 이곳에서든, 모래가 우릴 데려다주는 어느 곳에서든 말입니다.', '', 28153),
(161501, 'koKR', '', '볼둔에서의 생활은 쉽지 않겠지만, 부정한 자들을 물리치고 난 후에는 분명 더 쉬워지겠죠.\n\n감사합니다, $p 님.\n\n편히 쉬시고 제 동족들의 환대를 즐겨주세요. 저희를 도와 함께 구출해주신 아이들과 얘기도 나누시고요. 한잔하시죠.\n\n우리가 싸우는 건 바로 이런 평화로운 순간을 위해서이니, 잊지 않고 꼭 즐겨야 해요.', 28153),
(161500, 'koKR', '', '$p 님, 정말 대단한 모험이었어요. 한동안 잊지 못할 거예요.\n\n아, 돌리에게 안부 전하는 거 잊지 마세요. 당신을 보고 싶어 하니까요!', 28153),
(161499, 'koKR', '알거슨 벌목장의 상황이 해결되었습니다. 목재를 기다리는 분은 조만간 주문이 처리될 테니 기다려 주십시오.', '', 28153),
(161498, 'koKR', '', '으으. 멧돼지 가죽 털 때문에 칼날이 자꾸 무뎌져요. 그릭스한테 더 좋은 도구를 만들어 달라고 해야겠어요.', 28153),
(161497, 'koKR', '웨이크레스트 경비대가 드러스트바로의 여행길이 다시 안전해졌다고 알려 왔습니다. 단, 어떤 상황에도 도로를 벗어나지 말 것을 권고하더군요.', '', 28153),
(161496, 'koKR', '탈란지 공주님과 함께 있는 저분은 누구지? 설마... 호드?', '', 28153),
(161495, 'koKR', '새로운 해골은 없나요? 어디 좀 봐요!', '', 28153),
(161494, 'koKR', '공주님께서 돌아오셨어요!', '', 28153),
(161493, 'koKR', '공주님! 탈란지 공주님!', '공주님! 탈란지 공주님!', 28153),
(161492, 'koKR', '줄다자르로 데려다주십시오.', '줄다자르로 데려다주십시오.', 28153),
(161491, 'koKR', '놀윙턴 군주님이 실력이 뛰어난 기수와 사냥꾼들을 초청해 자신의 영지에서 제15회 놀윙턴 승마와 사냥 축제를 열고자 하십니다.', '', 28153),
(161490, 'koKR', '', '문명은 너무 지루해요... 나가서 사냥이나 하면 좋을 텐데...', 28153),
(161489, 'koKR', '이번이 마지막이야... 더는 못 해...', '이번이 마지막이야... 더는 못 해...', 28153),
(161488, 'koKR', '납작하게 뭉개 주지!', '납작하게 뭉개 주지!', 28153),
(161487, 'koKR', '프라우드무어 경비대가 추후 공지가 있을 때까지 드러스트바로의 여행을 자제해 달라고 전해 왔습니다. 웨이크레스트 경비대의 답을 기다리는 중입니다. 지금 당장 확인된 정보는 이렇습니다.', '', 28153),
(161486, 'koKR', '걱정 말렴. 별일 없으실 거야. 자, 엄마가 너에게 주라고 했던 편지란다!', '걱정 말렴. 별일 없으실 거야. 자, 엄마가 너에게 주라고 했던 편지란다!', 28153),
(161485, 'koKR', '', '저기, 카산드라. 내가 아끼는 무두질용 손칼이 보이질 않네. 혹시... 앗, 아니다. 찾았어.', 28153),
(161484, 'koKR', '알거슨 벌목장을 둘러싼 이상한 소문 때문에 걱정하고 계신 분께 알립니다. 주민을 자극하기 위해 모든 이야기가 과장되었고 벌목장에서는 단순히 일상적인 사업 문제를 처리 중일 뿐이라고 메이나드가 전해 달랍니다.', '', 28153),
(161483, 'koKR', '프리실라... 언젠가 네 목을 베어 버리겠다...', '프리실라... 언젠가 네 목을 베어 버리겠다...', 28153),
(161482, 'koKR', '기웃거리는 건 건강에 좋을 게 하나 없어!', '기웃거리는 건 건강에 좋을 게 하나 없어!', 28153),
(161481, 'koKR', '대제독님의 명에 따라 스톰송을 방문하는 모든 시민에게 다시 한번 알립니다. 스톰송 군주님의 경비대가 검열을 진행하니 계곡 통과 지점에서 신원 증명에 협조해 주십시오.', '', 28153),
(161480, 'koKR', '아아아아, 엄마! 정말 보고 싶어요. 빨리 집으로 돌아왔으면 좋겠어요.', '', 28153),
(161479, 'koKR', '바람은 언제나 변하지. 때로는 좋게, 때로는 나쁘게 말일세. 파쿠 님은 바람이 인도하는 곳으로 가라고 가르치셨네. 바람은 우리를 긴히 쓰일 곳으로 데려간다고 하셨지.\n\n자네와 호드는 나의 왕께, 또 백성에게 많은 도움을 주었네. 이 은혜는 절대 잊지 않겠네.\n\n로티가 허락하지도 않을 터이지만. 아마 로티를 용서해야 할지도 모르겠네. 아니면 사과해야 하던가? 기억이 안 나는군. 어쨌든 이것으로 끝일 테지.', '', 28153),
(161478, 'koKR', '', '안녕하세요!$b$b기계공학이 궁금하신가요?', 28153),
(161477, 'koKR', '아빠는 농장을 고쳐놓으려고 꿀벌처럼 바쁘게 일하고 있어요!', '', 28153),
(161476, 'koKR', '엄마가 보고싶어요... 정말 오랫동안 집에 돌아오지 않으셨거든요.', '', 28153),
(161475, 'koKR', '있잖아요... 저도 언젠가 모험가가 되고 싶어요.', '', 28153),
(161474, 'koKR', '웬디고랑 싸워서 이겼다니, 믿을 수가 없어요!!', '', 28153),
(161473, 'koKR', '우와아, 제가 못 들어본 멋진 이야기 좀 해주세요!', '', 28153),
(161472, 'koKR', '안녕하세요, $p 님!', '', 28153),
(161471, 'koKR', '당신이 아니었다면 전 이미 죽었을 겁니다. 감사합니다.', '당신이 아니었다면 전 이미 죽었을 겁니다. 감사합니다.', 28153),
(161470, 'koKR', '로아시여, 이러다 들이받겠어요!', '로아시여, 이러다 들이받겠어요!', 28153),
(161469, 'koKR', '빌어먹을 호드 녀석들! 로르다넬이 뭘 어쨌다고 이런 짓을!', '빌어먹을 호드 녀석들! 로르다넬이 뭘 어쨌다고 이런 짓을!', 28153),
(161468, 'koKR', '아, 안녕하십니까! 근데 꼴이... 엉망이군요.$b$b걱정 붙들어 매십시오. 이 대니가 필요한 건 뭐든 구해 드릴 테니!', '', 28153),
(161467, 'koKR', '로아께서 두 분과 함께하시길.', '', 28153),
(161466, 'koKR', '잔달라에 암흑의 시기가 찾아왔네. 혈트롤에, 로아께서는 돌아가시고, 배신자까지 나오다니. 하늘에는 어둠이 가득하고 바람은 앞으로 찾아올 역경들을 속삭이는군.\n\n심지어 로티까지 나에게 다정하다니, 이건 정상일 리 없네. 예감이 좋지 않아.\n\n자네와 호드가 여기에 있어 기쁘군, $n|1이여;여;.', '', 28153),
(161465, 'koKR', '엘룬이시여, 힘을 주소서!', '엘룬이시여, 힘을 주소서!', 28153),
(161464, 'koKR', '잠깐만요. 뭘 하고 싶다고요?', '잠깐만요. 뭘 하고 싶다고요?', 28153),
(161463, 'koKR', '이게 좋은 생각이라고 누가 그랬나요?', '이게 좋은 생각이라고 누가 그랬나요?', 28153),
(161462, 'koKR', '농장이 엉망이에요, 무슨 일인지 모르겠어요!', '', 28153),
(161461, 'koKR', '너무 순식간에 벌어진 일이었습니다...', '너무 순식간에 벌어진 일이었습니다...', 28153),
(161460, 'koKR', '엘룬께 찬양을!', '엘룬께 찬양을!', 28153),
(161459, 'koKR', '가고 싶은 곳이라도?', '가고 싶은 곳이라도?', 28153),
(161458, 'koKR', '이제 끝장이라고 생각했어요, 고맙습니다!', '이제 끝장이라고 생각했어요, 고맙습니다!', 28153),
(161457, 'koKR', '여기에서 그러시면 안 됩니다.', '여기에서 그러시면 안 됩니다.', 28153),
(161456, 'koKR', '여긴 너무 복잡하군요.', '여긴 너무 복잡하군요.', 28153),
(161455, 'koKR', '저희가 뭘 어떻게 해볼 틈도 없었습니다...', '저희가 뭘 어떻게 해볼 틈도 없었습니다...', 28153),
(161454, 'koKR', '피해가 간단 말입니다.', '피해가 간단 말입니다.', 28153),
(161453, 'koKR', '네 엄마를 만났단다. 안부 전해달라 하시더구나!', '네 엄마를 만났단다. 안부 전해달라 하시더구나!', 28153),
(161452, 'koKR', '당장은 공포뿔들의 실력이 영 미덥지 않군요.', '당장은 공포뿔들의 실력이 영 미덥지 않군요.', 28153),
(161451, 'koKR', '아야! 전 고통 알레르기가 있다고요!', '아야! 전 고통 알레르기가 있다고요!', 28153),
(161450, 'koKR', '그냥 포기하고 여기에 서 있으면 안 되나요?', '그냥 포기하고 여기에 서 있으면 안 되나요?', 28153),
(161449, 'koKR', '공크 님, 절 버리지 마십시오!', '공크 님, 절 버리지 마십시오!', 28153),
(161448, 'koKR', '달아나요!', '달아나요!', 28153),
(161447, 'koKR', '왜 우릴 공격하는 걸까요?!', '왜 우릴 공격하는 걸까요?!', 28153),
(161446, 'koKR', '안 돼! 절대! 안 돼요!', '안 돼! 절대! 안 돼요!', 28153),
(161445, 'koKR', '당신이 아무리 빨라도 절 잡을 순 없을 거예요!', '당신이 아무리 빨라도 절 잡을 순 없을 거예요!', 28153),
(161444, 'koKR', '도망쳐!', '도망쳐!', 28153),
(161443, 'koKR', '<일기는 브렌나담 광장의 호드 공습이 자세히 묘사된 페이지가 펼쳐진 채 놓여있습니다.>', '<일기는 브렌나담 광장의 호드 공습이 자세히 묘사된 페이지가 펼쳐진 채 놓여있습니다.>', 28153),
(161442, 'koKR', '', '저는 그 봉인이 무슨 역할을 하고 있는지도 몰랐습니다!\n\n우리는 지금, 그 어느 때보다도 하나가 되어 잔달라를 위협하는 적에 대항해야 합니다. 무리의 동료들을 찾아 그들의 짐을 나눠서 지십시오. \n\n배신자 줄은 죽었습니다. 라알에게 제가 옳았다는 사실을 말해주고 싶지만, 어차피 남은 이들이 많지 않으니 그냥 평화를 유지해야 할까요? 흥.', 28153),
(161441, 'koKR', '', '쿨 티란 모피와 가죽 가게에 잘 오셨어요!$b$b흠... 가게 이름이 멋이 없긴 해요, 그렇죠?$b$b저는 카산드라라고 해요. 가죽세공을 가르치고 있죠. 제 동업자인 카미는 좀 무뚝뚝하긴 해도 무두질 실력만큼은 누구에게도 뒤지지 않아요.$b$b소개는 충분히 했고, 뭘 찾으시죠?', 28153),
(161440, 'koKR', '', '너무나 많은 로아를 잃었습니다... 떠돌아다니는 이들은 공크 님께서 보호하고 계십니다. 폐하와 공주님을 생각하면 마음이 아픕니다. 레잔 님의 죽음은 그분들께도 엄청난 고통이 되었겠지요.\n\n흥, 저도 라알에게 친절하게 굴어야 할지도 모르겠습니다. 단 며칠만이라도 말이지요.\n\n감사합니다, $n 님. 당신과 호드는 강합니다. 그 힘을 입어 우리 부족은 더 강력해졌습니다. 당신은 우리에게 꼭 필요한 존재입니다.', 28153),
(161439, 'koKR', '', '다시 한번 잔달라 제국에게 자신의 가치를 증명하셨군요. 혈트롤, 세스락의 위협, 그리고 이제는 배신한 예언자까지 처치하시다니!\n\n당신과 나란히 싸우는 것이 자랑스럽습니다, $n 님.', 28153),
(161438, 'koKR', '새로운 야수를 찾고 있느냐?\n\n<비웃는 울파르>\n\n이곳의 마법은 깊고 심오하다. 지역의 몇몇 동물들이 이곳에 터전을 마련했지. 그들은 우리가 경의를 표해야 할 자연의 강한 면모를 보여주는 형체라 할 수 있다.', '', 28153),
(161437, 'koKR', '관찰력이 아주 뛰어나구나.\n\n<낄낄대는 울파르>\n\n그래, 바로 나다. 하지만 우리 종족 중에는 분쟁에 동의하지 않는 자들도 있었다. 너희 종족 사이에서는 의견이 나뉘는 것을 본 적이 없느냐? 우리 가시예언자들은 쿨 티란 협회에 가입했다. 너희 후손이 야생의 부름을 듣고 고대의 방식을 배우고자 하기에 우리는 그들을 가르쳤다. 혹시 너도 부름의 소리를 들은 것이냐?', '', 28153),
(161436, 'koKR', '줄은 죽었지만 결과는 참혹하구나.\n\n거대한 봉인은 파괴되었고 종결자 미스락스가 다시 세상에 풀려났다. 거기에 잔달라가 마주했던 그 어떤 존재들보다 더욱 사악한 존재인 그훈이란 존재도 다가오고 있다.\n\n$n|1이여;여;, 모두 나의 책임이다. 내가 탈란지의 말을 들었더라면, 줄의 행동이 문제가 될 때마다 한 번이라도 직접 해결하려 했다면, 이런 사태까지는 오지 않았을 것을. 나의 로아께서는 아직 살아 계실지도 모르는 상태에서 죽음의 로아께 내 운명을 걸어서는 안 되었는데.\n\n부끄럽구나.\n\n하지만 $n|1이여;여;, 너는 나의 곁에 있어 주었다. 호드는 우리의 오랜 적에 맞서 함께 싸워줬다. 잔달라는 그 사실을 절대 잊지 않을 것이다.\n\n약속한다.', '', 28153),
(161435, 'koKR', '그래 맞다. 우리 종족 중에는 분쟁에 동의하지 않는 자들도 있었다. 너희 종족 사이에서는 의견이 나뉘는 것을 본 적이 없느냐? \n\n우리 가시예언자들은 쿨 티란 협회에 가입했다. 너희 후손이 야생의 부름을 듣고 고대의 방식을 배우고자 하기에 우리는 그들을 가르쳤다.', '', 28153),
(161434, 'koKR', '나는 최후의 드러스트 가시예언자이자 이 제자들의 스승인 울파르다. 언젠가 나의 임무가 끝나면 난 순리대로 흙으로 돌아갈 테고, 새로운 고위 가시예언자가 나타나 이끌어 갈 것이다.\n\n하지만 그 날은 아직 오지 않았다.', '', 28153),
(161433, 'koKR', '어이쿠, 깜짝이야!$b$b그러니까... 낚시를 배우러 온 거 맞죠? 그거 말고는 제가 할 줄 아는 게 없거든요.', '', 28153),
(161432, 'koKR', '반은 식물, 반은 동물처럼 보이는 생명체를 본 적이 있습니다. 그들에 관해 이야기해 주시겠어요?', '반은 식물, 반은 동물처럼 보이는 생명체를 본 적이 있습니다. 그들에 관해 이야기해 주시겠어요?', 28153),
(161431, 'koKR', '당신, 드러스트군요! 전쟁에서 적으로 싸운 적이 있지요!', '당신, 드러스트군요! 전쟁에서 적으로 싸운 적이 있지요!', 28153),
(161430, 'koKR', '드러스트라고요? 우리 전쟁에서 싸운 적 있지 않은가요?', '드러스트라고요? 우리 전쟁에서 싸운 적 있지 않은가요?', 28153),
(161429, 'koKR', '이야기를 또 해주시겠어요?', '이야기를 또 해주시겠어요?', 28153),
(161428, 'koKR', '당신은 누굽니까?', '당신은 누굽니까?', 28153),
(161427, 'koKR', '', '우리 자신을 돌보는 일도 잊어선 안 돼요, $p 님. 자기 앞가림이 급급하면 사랑하는 사람들을 챙겨줄 수 없는 법이니까요.', 28153),
(161426, 'koKR', '당신도 드루이드입니까?', '당신도 드루이드입니까?', 28153),
(161425, 'koKR', '당신들은 드루이드인가요?', '당신들은 드루이드인가요?', 28153),
(161424, 'koKR', '', '모험은 잘 하고 계셨길 바라요, $p 님!', 28153),
(161423, 'koKR', '그렇다, $n. 우리는 자연의 균형을 수호하고 순환을 유지한다. 삶은 죽음과 마찬가지로 자연의 일부다.', '', 28153),
(161422, 'koKR', '$n, 우리는 너희와 크게 다르지 않다. 자연의 균형을 수호하고 순환을 유지하지. 삶은 죽음과 마찬가지로 자연의 일부다. 하지만 드루이드인 네가 그걸 모를 리 없겠지.\n\n우리 숲에 온 걸 환영한다.', '', 28153),
(161421, 'koKR', '', '앙켈과 아이 아빠가 너무 보고 싶어요. 곧 집에 돌아갈 수 있게 되기를 바라요.', 28153),
(161420, 'koKR', '', '다시 만나서 반가워요, $p 님. 잘 있었길 바라요.', 28153),
(161419, 'koKR', '<일기를 읽습니다.>', '<일기를 읽습니다.>', 28153),
(161418, 'koKR', '알겠어요!', '알겠어요!', 28153),
(161417, 'koKR', '당신과 탈란지가 어둠의 심장부를 처음 봤을 때의 이야기를 읽습니다.', '당신과 탈란지가 어둠의 심장부를 처음 봤을 때의 이야기를 읽습니다.', 28153),
(161416, 'koKR', '', '물론이죠. 정말 다들 너무 보고 싶어서 얼른 집에 돌아가고 싶어요. 레이몬드는 최선을 다하고 있겠지만, 손대는 일마다 혼란에 빠뜨려버리는 경향이 있으니까요!\n\n제 가족들을 다시 만나면, 제 사랑하는 앙켈에게 이 편지를 전해주세요.', 28153),
(161414, 'koKR', '미치광이 바자가 나즈미르에서 벌어진 모든 일에 관해 기록해 뒀었습니다. 미치광이라는 별명에 어울리지 않게 글이 맛깔나게 잘 정리되어 있습니다.', '', 28153),
(161413, 'koKR', '', '줄로 인해 벌어진 참상이 이루 말할 수가 없군요...\n\n당신과 호드가 아직 이곳에 함께해 주어 정말 다행입니다, $n 님. 제 믿음이 틀리지 않은 것 같아 기쁘군요. 잔달라 부족 혼자서 그런 일을 맞이했다면... 말로 표현할 수 없을 정도로 끔찍하군요.\n\n이 모든 게 끝나고도 우리가 아직 살아 있다면, 당신에게 보답하고 싶습니다. 잔달라가 당신에게 진 빚을, 영원히 잊지 않겠습니다.', 28153),
(161412, 'koKR', '\"동생아, 넌 선원으로서는 실력이 썩어 문드러졌지만, 훌륭한 파도현자는 될 것 같구나.\" 코랄린이 말했어요.', '\"동생아, 넌 선원으로서는 실력이 썩어 문드러졌지만, 훌륭한 파도현자는 될 것 같구나.\" 코랄린이 말했어요.', 28153),
(161411, 'koKR', '', '아이트리그, 당신과 함께하겠습니다. 대족장과도 이야기해 보겠습니다. 대족장은 아직 제 어머니께서 말씀하시던 트롤입니까?', 28153),
(161410, 'koKR', '', '레잔... 나의 로아께서... 쓰러지셨습니다.\n\n마음이 너무 아픕니다. 아버님의 어깨가 그렇게 무겁게 처진 모습은 처음 보았습니다. 줄의 배신은 아버님께는 우리가 예상했던 것보다... 처음부터 줄을 의심하고 있던 이들의 예상보다도 더 깊은 상처로 남았습니다.\n\n그러한 이단 행위를 그대로 두고 볼 수는 없습니다, $n 님. 우리 백성과 로아, 아군이 모두 단결해야 합니다! 하나가 되어야만 줄의 사악한 계획을 막을 수 있을 것입니다.', 28153),
(161409, 'koKR', '', '알았어요, 그럼. 다음에 봐요.', 28153),
(161408, 'koKR', '안녕하십니까!$b$b바이론 형제의 보랄러스 바베큐에 오신 걸 환영합니다! 이 동네의 아이언포지라고도 할 수 있는, 최고로 맛있는 훈제 고기를 맛볼 수 있는 곳이지요!$b$b뭘 드리면 좋을까요?', '', 28153),
(161407, 'koKR', '라스타칸 왕이 브원삼디와 맺은 계약에 관해 말해주세요.', '라스타칸 왕이 브원삼디와 맺은 계약에 관해 말해주세요.', 28153),
(161406, 'koKR', '앞에 보이는 게 바로 호드의 수도, 오그리마의 성벽이네.', '', 28153),
(161405, 'koKR', '오래전에는 나도 그랬지. 꽤나... 어지러운 일일세. 내가 어떻게든 자네와 자네 부족을 돕겠네.', '', 28153),
(161404, 'koKR', '와... 그것참 흥미로운 이야기네요.', '와... 그것참 흥미로운 이야기네요.', 28153),
(161403, 'koKR', '', '종결자 미스락스가 다시 세상에 풀려났다니! 우리는 미스락스가 일종의 신화, 그러니까 쇠퇴한 시대와 안일함에 굴복하지 말도록 경고하기 위해 지어낸 이야기인 줄 알았습니다. 이제 음흉한 자크라제트와 그의 부정한 자들의 덕에 공포가 다시 살아나 땅 위를 걷게 되겠군요.\n\n희망이 없는 건 아닙니다. 자크라제트는 최후를 맞이했고 우리는 불페라 부족과 세스랄리스 님을 모시는 자들과 새 동맹을 맺었으니까요. 하지만... 아무리 그들의 힘을 빌린다고 해도 승산이 있을지 몰라 두렵습니다.\n\n다가오는 어둠의 나날들이... 부디 잔달라의 최후의 날이 아니기를 빕니다.', 28153),
(161402, 'koKR', '', '방금 전까지만 해도 드레노어에서 목숨을 걸고 싸우고 있었는데, 또 다른 세계를 보게 될 거라곤 상상도 못했습니다.', 28153),
(161401, 'koKR', '탈란지의 징벌에 관해 말해주세요.', '탈란지의 징벌에 관해 말해주세요.', 28153),
(161400, 'koKR', '미스락스의 공격에 관해 말해주세요.', '미스락스의 공격에 관해 말해주세요.', 28153),
(161399, 'koKR', '끝났네, 대군주. 여기가... 아제로스라네.', '', 28153),
(161398, 'koKR', '줄의 배신에 관해 말해주세요.', '줄의 배신에 관해 말해주세요.', 28153),
(161397, 'koKR', '', '수 세대 동안 잔달라 부족은 나즈마니와 전쟁을 벌여 왔습니다. 우리의 국경은 제가 태어나기 훨씬 전부터 공격을 받아 왔고, 제 아버지는 혈트롤과 끊임없이 전쟁을 벌이셨죠. 아버지는 혈트롤을 그냥 해로운 존재 정도로 생각하셨고, 우리는 그들이 힘을 모으게 방치했습니다. 그 힘의 원천을, 우린 이제 압니다.\n\n혈트롤은 혈신 그훈을 섬깁니다.\n\n우리는 실패해선 안 됩니다. 줄다자르가 무너지면, 다음은 나머지 세계들입니다. 놈들은 혈신이 모든 걸 지배할 때까지 멈추지 않을 겁니다.', 28153),
(161396, 'koKR', '', '제 가게에 잘 오셨어요.$b$b편하게 둘러보세요. 궁금한 게 있으시면 도와 드릴 테니 말씀만 하세요.', 28153),
(161395, 'koKR', '', '삐뽀! 삐뽀!', 28153),
(161394, 'koKR', '이 잔달라 표본을 연구하려면 기존과는 완전히 다른 분류법이 필요합니다!', '이 잔달라 표본을 연구하려면 기존과는 완전히 다른 분류법이 필요합니다!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161393, 'koKR', '', '페어웨더의 고급 마법부여소에 오신 걸 환영해요!\n\n신비한 것들에 대해 궁금한 게 있으면 무엇이든 물어보세요!', 28153),
(161391, 'koKR', '', '으으, 가시를 또 부러뜨렸어요...', 28153),
(161390, 'koKR', '열쇠가... 다시 한 번 돌아간다.', '', 28153),
(161389, 'koKR', '부정한 존재! 그것이 각성하는 순간 너는 영원을 알게 되리라, 그리고 무너지게 되리라!', '', 28153),
(161388, 'koKR', '', '아아! 손에 쥐가 났어요!', 28153),
(161387, 'koKR', '태초에 위대하고 끔찍한 진실이 있었나니, 나는 그 전령이다. 내 설교를 듣고 네 끝없는 부조리를 깨닫거라.', '', 28153),
(161386, 'koKR', '전 당황하지 않고 주변을 헤엄치며 계속 마셔댔습니다!', '', 28153),
(161385, 'koKR', '제가 말입니다, 커다란 스톰스타우트 맥주통 안에 갇힌 적이 있었죠!', '', 28153),
(161384, 'koKR', '너는 저 세계를 들여다보았다. 이제 만물을 진실된 모습으로 보게 되리라.', '', 28153),
(161383, 'koKR', '', '잠깐. 얼룩이었어요? 아니면 문양?', 28153),
(161382, 'koKR', '실바나스의 소원이 나와 싸우는 거라면 그렇게 해줘야지.', '', 28153),
(161381, 'koKR', '달숲에 드워프 양조장이 한두 곳만 있어도 그나마 살 만한 곳이 될 겁니다.', '', 28153),
(161380, 'koKR', '', '가요! 잠수함은 이미 출발할 준비가 됐을 거예요.', 28153),
(161379, 'koKR', '제 친구들을 위해 한 잔 더 하지요!', '', 28153),
(161378, 'koKR', '특급 배송입니다, 스승님!', '', 28153),
(161377, 'koKR', '뭐, 안타까운 상황이었죠. 어쨌든 다 왔습니다!', '', 28153),
(161376, 'koKR', '전 뿌리 깊은 가시예언자인걸요! 아시겠습니까?', '', 28153),
(161375, 'koKR', '부모님께서는 제가 해군에 들어가길 바라셨습니다. 제가 해군이라니, 상상이 가세요? 말도 안 됩니다.', '', 28153),
(161374, 'koKR', '제가 어릴 적 부름의 소리를 들은 뒤로, 그와 다른 이들이 절 인도해 주고 있죠.', '', 28153),
(161373, 'koKR', '울파르는 꽤 까다로운 스승이지만 공정하긴 합니다.', '', 28153),
(161372, 'koKR', '꽉 잡으세요!', '', 28153),
(161371, 'koKR', '이봐요! $n 님! 이쪽이에요!', '', 28153),
(161370, 'koKR', '울파르의 숲까지 가는 길은 위험천만합니다. 길이 시작되는 지점에서 제 동료인 아서와 합류하십시오.', '', 28153),
(161369, 'koKR', '좋아요! $n 님, 거기서 만나요!', '', 28153),
(161368, 'koKR', '$p 님, 텔로그러스 균열에서 당신이 이룬 위대한 업적에 관해 들었습니다.\n\n당신 같은 분과 나란히 임무를 수행하게 되어 정말 기쁩니다. 우리 둘이 힘을 합치면 못할 일이 없을 겁니다.', '', 28153),
(161367, 'koKR', '근처에 혹시라도 남아 있을 위험 장치들을 제거하느라 동분서주하고 있어요.', '근처에 혹시라도 남아 있을 위험 장치들을 제거하느라 동분서주하고 있어요.', 28153),
(161366, 'koKR', '장치를 전부 해제했으니 당분간... 여긴 안전할 거예요.', '장치를 전부 해제했으니 당분간... 여긴 안전할 거예요.', 28153),
(161365, 'koKR', '발밑 조심하세요.', '발밑 조심하세요.', 28153),
(161364, 'koKR', '장치를 다 해제하긴 했지만 혹시 모르니 조심해야 해요!', '장치를 다 해제하긴 했지만 혹시 모르니 조심해야 해요!', 28153),
(161363, 'koKR', '', '네, 확실히 고쳐졌어요! 참! $n 님이 찾아오신 기록을 확인해 보는 게 어때요?', 28153),
(161362, 'koKR', '그렇군요, 고쳤다니 잘 됐습니다.', '', 28153),
(161361, 'koKR', '너무나 어여쁘게 피었군요.', '', 28153),
(161360, 'koKR', '', '아! 아하하... 그게, 십 분 전에는 소형 억제장이 제대로 작동하지 않았거든요.', 28153),
(161359, 'koKR', '켈시, 송곳니의 섬으로 갈 때도 이 잠수함을 사용할 수 있지 않았나요?', '', 28153),
(161358, 'koKR', '', '맘 놓고 편히 계세요. 순식간에 전쟁항구로 모셔다드릴 테니까요!', 28153),
(161357, 'koKR', '파도돌고래가 겁을 먹고 있습니다. 당장 돌아가야 합니다!', '파도돌고래가 겁을 먹고 있습니다. 당장 돌아가야 합니다!', 28153),
(161356, 'koKR', '흠... 진딧물이라... 당신과의 일은 조금 뒤로 미루지요.', '', 28153),
(161355, 'koKR', '자, 어서 힘을 내 싹을 틔워야지.', '', 28153),
(161354, 'koKR', '아아, 에이트릴의 향기를 맡을 때 이 일에 가장 큰 보람을 느낀답니다.', '', 28153),
(161353, 'koKR', '요잠바 섬은 오래전 가시덤불 골짜기의 원정 거점이었습니다. 저는 학카르가 이 세계로 돌아오는 것을 막는 임무를 맡은 자 중 하나였지요. 우리는 사악한 로아에 맞서 싸우는 영웅들에게 영광스러운 무기를 전달했습니다.\n\n승리의 영예를 안고 잔달라로 돌아온 저는 예언가 줄에게 저의 승리를 과장해서 자랑하는 실수를 저지르고 말았습니다. 공개적인 자리에서 했던 말이 뭔가 문제가 됐을지도요.\n\n지금은 간식이나 파는 처지랍니다.', '', 28153),
(161352, 'koKR', '이야기가 다른 곳으로 새고 있어요. 본론으로 돌아가죠!', '이야기가 다른 곳으로 새고 있어요. 본론으로 돌아가죠!', 28153),
(161351, 'koKR', '', '다시 만나서 반가워요, $p 님. 얼라이언스 연합에서 그렇게 빨리 진급을 하다니, 정말 대단합니다. \n\n무엇보다 속삭임의 유혹에 꿋꿋이 저항하고 계셔서 더 기쁘군요.\n\n전쟁은 혼돈과 야만으로 세상을 얼룩지게 해요. 지금까지 무얼 보고 경험했든, 자제력을 잃지 마세요. 어둠의 그림자에 의지를 꺾여서는 안 돼요.\n\n얼라이언스는 당신을 믿어요.\n\n그리고 저도 당신을 믿어요.', 28153),
(161350, 'koKR', '요잠바가 대체 무엇입니까?', '요잠바가 대체 무엇입니까?', 28153),
(161349, 'koKR', '얼라이언스 놈들이 쳐들어온다! 왕께 보고해라!', '얼라이언스 놈들이 쳐들어온다! 왕께 보고해라!', 28153),
(161348, 'koKR', '얼라이언스가 여기 있다! 본토에 알려라!', '얼라이언스가 여기 있다! 본토에 알려라!', 28153),
(161347, 'koKR', '얼라이언스에게 공격받고 있다! 본토에 알려야 한다!', '얼라이언스에게 공격받고 있다! 본토에 알려야 한다!', 28153),
(161346, 'koKR', '얼라이언스 놈들이 쳐들어온다! 아군에게 알려라!', '얼라이언스 놈들이 쳐들어온다! 아군에게 알려라!', 28153),
(161345, 'koKR', '', '방심하지 마십시오, 엄브릭. 이건 만만한 계획이 아닙니다. 일이 조금이라도 틀어졌다가는 수많은 이들이 목숨을 잃게 됩니다.', 28153),
(161344, 'koKR', '제가 생각했던 것만큼 무모한 계획은 아니었던 것 같군요.', '', 28153),
(161343, 'koKR', '할포드 님, 주제 넘은 소리일지도 모르지만, 그건 자살 행위나 다름없습니다. 지난번 잔달라 해안에 접근했던 함대도 전멸했습니다.', '', 28153),
(161342, 'koKR', '그 말이 맞소. 만일 이대로 대규모 함대를 상륙시킨다면 손실이 엄청날 거요.', '', 28153),
(161341, 'koKR', '잔달라 섬에 접근했던 우리 함대가 놈들의 해군 공격에 초토화되었습니다. 배에 탄 어떤 공주를 추적하다 난데없이 말이죠.', '', 28153),
(161340, 'koKR', '묻혀 있는 물건이라고요?', '묻혀 있는 물건이라고요?', 28153),
(161339, 'koKR', '고맙다고... 해야겠죠?', '고맙다고... 해야겠죠?', 28153),
(161338, 'koKR', '무슨 하고 싶은 이야기가 있는 거예요?', '무슨 하고 싶은 이야기가 있는 거예요?', 28153),
(161337, 'koKR', '이 안은 덥네요.', '이 안은 덥네요.', 28153),
(161336, 'koKR', '<주위를 가리키는 당신>', '<주위를 가리키는 당신>', 28153),
(161335, 'koKR', '무슨 말을 하고 있었죠?', '무슨 말을 하고 있었죠?', 28153),
(161334, 'koKR', '그렇게 생각하고 있던 거예요?', '그렇게 생각하고 있던 거예요?', 28153),
(161333, 'koKR', '안녕하세요. 겁먹지 마십시오.', '', 28153),
(161332, 'koKR', '그 정도면 사례로 충분하겠죠!', '', 28153),
(161331, 'koKR', '그래요, 녀석들에게 붙잡히기 전에 숨겨 둔 것이지요. 나즈미르의 강가에 있는 뿌릿길 바로 옆에 탑을 찾아가십시오. 발치에 있을 겁니다.', '', 28153),
(161330, 'koKR', '오래 전에 당신한테 빚을 진 것 같으니 땅에 묻혀 있는 물건들을 가져가도 좋습니다.', '', 28153),
(161329, 'koKR', '해골이 된 입장에서 안내를 부탁하기에 당신만큼 든든한 존재가 있을까 싶군요.', '', 28153),
(161328, 'koKR', '괜찮아요. 여긴 꽤 아늑한 것 같습니다.', '', 28153),
(161327, 'koKR', '제가 말했나요? 그 별것도 아닌 잿빛 놈들 중 하나가 자기가 화산에 살았다고 말하는 걸 우연히 들은 적이 있습니다.', '', 28153),
(161326, 'koKR', '그래요. 그럴 수도 있겠군요... 당신 안색이 점점 파래지는군요... 절대 절 여기 두고 가지 마십시오.', '', 28153),
(161325, 'koKR', '실은 볼둔에 경주장을 하나 차릴 뻔했는데, 동업자들이 대재앙이 또 찾아와 모든 게 물속으로 가라앉을 거라며 걱정하곤 모두 달아나는 바람에... 게다가 돈도 한 푼 없었어요. 망명할 때 다 빼앗겼거든요.', '', 28153),
(161324, 'koKR', '이건 진짜 파충류가 아니에요... 제가 그랬다고는 이르지 마십시오.', '', 28153),
(161323, 'koKR', '잔달라에는 커다란 파충류가 많습니다. 그렇게 큰 종은 역사상 없을 거예요.', '', 28153),
(161322, 'koKR', '보통 때보다 추운 느낌이 드는데, 이게 가능한 일인가요?', '', 28153),
(161321, 'koKR', '눈 속에서 호랑이를 볼 일이 있을까요? 눈과 호랑이라니, 말도 안 되는 일이죠.', '', 28153),
(161320, 'koKR', '이곳이 마음에 듭니다. 여기서 떠돌면 될 것 같군요.', '', 28153),
(161319, 'koKR', '언제쯤 좋은 곳에 갈 건가요?', '', 28153),
(161318, 'koKR', '', '그러니까, 삶에 변화를 좀 주고 싶어서 그 농장으로 거처를 옮겼어요. 도시에서는 일도 잘 안 풀리고, 앙켈은 학교에도 잘 적응하지 못하고 있었거든요. 아이 아빠랑 저는 정신 없는 생활을 접고 시골에서 한적하게 사는 게 제일 낫겠다고 생각했지요.\n\n저는 비전 연구를 그만두고 농장에서 작물을 거두는 데 집중해야 했어요. 쉽지는 않았답니다. 일은 고되었고, 오랫동안 입에 풀칠이나 겨우 했지요. 레이몬드가 돌파구를 찾았다고 생각했을 때에는 늘 무언가가 잘못되곤 했죠.\n\n그때 우리는 제가 비전 연구를 다시 시작하면 좋겠다는 결론을 내렸지요. 저는 그 뒤로 여행을 하며 실력을 닦고, 돈 있는 사람들에게 제 기술을 보여주며 제 가족을 부양하고 있어요.', 28153),
(161317, 'koKR', '여긴 좀 쌀쌀한 것 같은데, 저만 그런 건가요?', '', 28153),
(161316, 'koKR', '꽤 흥미로운 장소군요.', '', 28153),
(161315, 'koKR', '오오, 오늘은 어디로 가죠?', '', 28153),
(161314, 'koKR', '고맙... 습니다...?', '고맙... 습니다...?', 28153),
(161313, 'koKR', '아무래도 다음으로 미뤄야 할 것 같아요.', '아무래도 다음으로 미뤄야 할 것 같아요.', 28153),
(161312, 'koKR', '그럴지도 모르죠. 하지만 전 드루이드가 아니라서요.', '그럴지도 모르죠. 하지만 전 드루이드가 아니라서요.', 28153),
(161311, 'koKR', '그러죠.', '그러죠.', 28153),
(161310, 'koKR', '속상했겠군요.', '속상했겠군요.', 28153),
(161309, 'koKR', '당신이라면 할 수 있겠죠.', '당신이라면 할 수 있겠죠.', 28153),
(161308, 'koKR', '하지만 그런 멋진 모습이라면 더 빨리 날 수 있지 않나요?', '하지만 그런 멋진 모습이라면 더 빨리 날 수 있지 않나요?', 28153),
(161307, 'koKR', '실은 생각이 바뀌었습니다. 알고 싶지 않아요.', '실은 생각이 바뀌었습니다. 알고 싶지 않아요.', 28153),
(161306, 'koKR', '왜 기분이 안 좋은 거죠?', '왜 기분이 안 좋은 거죠?', 28153),
(161305, 'koKR', '왠지 흥미로운 이야깃거리가 있을 것 같군요.', '왠지 흥미로운 이야깃거리가 있을 것 같군요.', 28153),
(161304, 'koKR', '', '음... 말하자면 긴 이야기인데요. 들어주신다면 얼마든지 얘기해 드릴게요. 잠깐 시간 되시나요?', 28153),
(161303, 'koKR', '그대를 탓하진 않을 겁니다. 아니, 제가 직접 적어 드리겠습니다, 읽기 쉽게 큰 글자로 말이지요.', '', 28153),
(161302, 'koKR', '이러면 어떻겠습니까? 제가 당신에게 점잖게 보이면서도 그토록 갈망하는 \'더 빠른 비행\'을 유지하는 방법을 그대에게 가르쳐준다면, 젊은이들도 제 말을 들으려 하겠지요.', '', 28153),
(161301, 'koKR', '그대도 알겠지만 아무도 제 말을 들으려 하지 않습니다. 다들 텁수룩한 갈기와 털, 아니면 장식이나 목을 연신 흔들어댈 뿐이지요.', '', 28153),
(161300, 'koKR', '그렇긴 한데... 왜 그들과 함께이지 않은지 물어봐도 되나요? 그들이 농장을 아주 엉망으로 만들어 놨던데.', '그렇긴 한데... 왜 그들과 함께이지 않은지 물어봐도 되나요? 그들이 농장을 아주 엉망으로 만들어 놨던데.', 28153),
(161299, 'koKR', '다들 뭘 몰라서 그렇습니다. 나이가 좀 들었다고 겉만 번지르르한 요즘 변신 형태를 따라잡지 못한다는 법이 어디 있습니까? 겸손한 태고의 모습도 수천 년간 제 몫을 톡톡히 해 왔는데 말이지요.', '', 28153),
(161298, 'koKR', '아시다시피, 요즘 드루이드 젊은이들은 우리 전통주의자를 존중하지 않습니다. 제가 화려한 술이나 번쩍거리는 방어구를 달고 날아다닐 것 같습니까?', '', 28153),
(161297, 'koKR', '', '이걸 어디서 찾으셨어요? 영영 없어진 건 줄 알았는데!', 28153),
(161296, 'koKR', '혹시 주문각인사입니까? 그럼 주문 하나 알려 드릴 테니 들어 보시겠습니까?', '', 28153),
(161295, 'koKR', '모두 겉멋만 들었다 이겁니다.', '', 28153),
(161294, 'koKR', '우리 때만 해도 연장자들의 방식을 존중했는데 말이지요.', '', 28153),
(161293, 'koKR', '전쟁을 피해 쿨 티라스로 왔습니다. 제 삶이 그렇지요, 뭐.', '', 28153),
(161292, 'koKR', '요즘 젊은 드루이드들은 이해가 안 갑니다.', '', 28153),
(161291, 'koKR', '제가 볕을 쬐고 있는 모습이 안 보이십니까?', '', 28153),
(161290, 'koKR', '저리 가십시오.', '', 28153),
(161289, 'koKR', '제가 길을 열었습니다. 당장 탈출하십시오!', '제가 길을 열었습니다. 당장 탈출하십시오!', 28153),
(161288, 'koKR', '절 내버려 두십시오.', '', 28153),
(161287, 'koKR', '', '어떤 대모험을 하시길래 여기까지 오셨죠?', 28153),
(161286, 'koKR', '', '희생은 항상 어려운 일이에요. 더 큰 선을 위해서라도 말이지요...', 28153),
(161285, 'koKR', '', '언젠가는 우리 불행을 해결할 힘을 찾아 집에 돌아갔으면 좋겠어요.', 28153),
(161284, 'koKR', '', '비전 지식을 탐구하는 일에는 전력이 필요해요. 때로는 여행에 지쳐버리기도 해요...', 28153),
(161283, 'koKR', '', '혹시 집에 아이 있으세요? 우리 앙켈은 어쩌고 있을지... 편지라도 보내야겠어요.', 28153),
(161282, 'koKR', '', '귀한 마법 도구 같은 걸 파시는 건 아닌 것 같은데요?', 28153),
(161281, 'koKR', '', '안녕하세요, 만나서 반갑네요.', 28153),
(161280, 'koKR', '웩! 잠깐 하품 좀 했더니!', '웩! 잠깐 하품 좀 했더니!', 28153),
(161279, 'koKR', '안대가 있으면 뭘 해!', '안대가 있으면 뭘 해!', 28153),
(161278, 'koKR', '끄응! 네놈 깃털을 죄다 뽑아 버리겠어!', '끄응! 네놈 깃털을 죄다 뽑아 버리겠어!', 28153),
(161277, 'koKR', '으윽!! 이번엔 멀쩡한 내 눈에다!', '으윽!! 이번엔 멀쩡한 내 눈에다!', 28153),
(161276, 'koKR', '망할 날개 달린 악마 같으니!', '망할 날개 달린 악마 같으니!', 28153),
(161275, 'koKR', '으윽...', '으윽...', 28153),
(161274, 'koKR', '아, 또야!', '아, 또야!', 28153),
(161273, 'koKR', '에잇! 더러워!', '에잇! 더러워!', 28153),
(161272, 'koKR', '당신들이 지지는 않겠죠, 그쵸? 제 돈을 당신들에게 걸었단 말이에요... 돈을 잃으면 아빠가 절 싫어할 거예요.', '', 28153),
(161271, 'koKR', '내 소중한 황금들아. 곧 가지러 갈 테니 걱정하지 말고 기다려라!', '내 소중한 황금들아. 곧 가지러 갈 테니 걱정하지 말고 기다려라!', 28153),
(161270, 'koKR', '전방 주시해, 제임스! 우린 지금 교전 지역에 와 있다!', '', 28153),
(161269, 'koKR', '하사관님, 우릴 둘러싸고 있는 이 모든 금 좀 보십시오.... 눈이 부실 지경입니다!', '', 28153),
(161268, 'koKR', '안녕하세요! 아이들을 계속 즐겁게 해 주고 싶습니다. 어떤 이야기가 좋을까요?', '안녕하세요! 아이들을 계속 즐겁게 해 주고 싶습니다. 어떤 이야기가 좋을까요?', 28153),
(161267, 'koKR', '', '거기 잠깐만요! 수수께끼 푸는 거 좋아하시나요? 못 맞추면 목숨을 잃거나 닭으로 변할 수도 있는데. 그렇다면 기계공학을 배워 보는 걸 추천해요!', 28153),
(161266, 'koKR', '', '그게 말이죠... 하늘 골렘이 아직 완성되지 않아서 마무리해야 해요.', 28153),
(161265, 'koKR', '진지한 노래 한 가닥 듣고 싶네요.', '진지한 노래 한 가닥 듣고 싶네요.', 28153),
(161264, 'koKR', '파도현자에 관한 이야기를 듣고 싶어요.', '파도현자에 관한 이야기를 듣고 싶어요.', 28153),
(161263, 'koKR', '재미난 노래 한 가락 듣고 싶네요.', '재미난 노래 한 가락 듣고 싶네요.', 28153),
(161262, 'koKR', '아테어에 관해 알려 주세요.', '아테어에 관해 알려 주세요.', 28153),
(161261, 'koKR', '은식기류, 찻주전자, 고급 식기류, 전부 다 애쉬베인급입니다!', '은식기류, 찻주전자, 고급 식기류, 전부 다 애쉬베인급입니다!', 28153),
(161260, 'koKR', '', '초기 장전에 힘을 좀 더 부여하면 폭발력이 향상할 수도 있을 것 같은데... 역화가 발생할 가능성은 얼마나 되는 걸까요?', 28153),
(161259, 'koKR', '물건은 다양하게 준비되어 있으니 와서 마음 편히 구경하십시오!', '물건은 다양하게 준비되어 있으니 와서 마음 편히 구경하십시오!', 28153),
(161258, 'koKR', '선원의 회중시계도 있습니다! 이제 더 만들지도 않아서 구하기 어려운 물건입니다!', '선원의 회중시계도 있습니다! 이제 더 만들지도 않아서 구하기 어려운 물건입니다!', 28153),
(161257, 'koKR', '... 무역풍 시장보다 무조건 12실버 더 싸게 팝니다!', '... 무역풍 시장보다 무조건 12실버 더 싸게 팝니다!', 28153),
(161256, 'koKR', '도금한 나침반 팝니다! 해군에 납품하는 공급업자에게 직접 공수해 온 물건입니다!', '도금한 나침반 팝니다! 해군에 납품하는 공급업자에게 직접 공수해 온 물건입니다!', 28153),
(161255, 'koKR', '', '스패너를 어디다 뒀더라?', 28153),
(161254, 'koKR', '쥐새끼처럼 달아나는 꼴 좀 보십시오! $p|1이여;여;, 수중 폭탄을 투하해 주십시오!', '쥐새끼처럼 달아나는 꼴 좀 보십시오! $p|1이여;여;, 수중 폭탄을 투하해 주십시오!', 28153),
(161253, 'koKR', '$p 님, 아래를 보십시오! 물속에 놈들의 창고가 있습니다. 수중 폭탄을 투하하십시오!', '', 28153),
(161252, 'koKR', '', '마법부여! 얼마나 돈을 많이 버는 일인데요!', 28153),
(161251, 'koKR', '', '반지가 어디로 갔지? 아까 분명히 끼고 있었는데... 맙소사... 또 이러지 마.', 28153),
(161250, 'koKR', '', '제아무리 강력한 전사라도 마법 방어구와 무기 없이는 아무것도 할 수 없어요. 마법부여를 배우세요!', 28153),
(161249, 'koKR', '', '비전술에 관심 있으세요? 마법 특성으로 아이템에 마법을 부여하는 방법을 배워보세요!', 28153),
(161248, 'koKR', '성벽 위에 대포가 있습니다!', '', 28153),
(161247, 'koKR', '붉은 깃발이 달린 통나무배에 불을 붙이십시오!', '', 28153),
(161246, 'koKR', '성벽 위에 대포가 있습니다! 물에 빠져 죽고 싶지 않으면 조심하십시오!', '', 28153),
(161245, 'koKR', '붉은 깃발을 휘날리는 통나무배에 불을 붙이십시오!', '', 28153),
(161244, 'koKR', '향료와 불을 완벽하게 다루는 법을 배우십시오!', '', 28153),
(161243, 'koKR', '배가 고픈 겁니까? 그럼 직접 만들어 드십시오!', '', 28153),
(161242, 'koKR', '입안에 침을 고이게 만드는 훈제 고기입니다! 판매는 안 하지만 직접 만드는 법을 배울 순 있답니다!', '', 28153),
(161241, 'koKR', '', '운송 중인 유물을 계속 없애는 놈이 누구인지 알아내면 그놈의 뼈를 하나도 남김없이 부러뜨려 버릴 거예요.', 28153),
(161240, 'koKR', '', '당신은 굉장한 용기와 명예를 보여주셨습니다. 더욱 중요한 사안을 믿고 맡길 수 있는 분으로 보인다고 제가 라스타칸 폐하께 말씀드렸습니다.\n\n지금부턴 등 뒤를 조심하십시오. 악의를 가진 놈들이 당신을 호시탐탐 노리고 있을 테니까 말입니다.', 28153),
(161239, 'koKR', '', '이 정도면 수집가에게 꽤 가치가 있겠는걸요.', 28153),
(161238, 'koKR', '그래서 우리 배는 최고 중의 최고라는 명성을 얻게 됐답니다!', '그래서 우리 배는 최고 중의 최고라는 명성을 얻게 됐답니다!', 28153),
(161237, 'koKR', '도메닉은 손을 벌벌 떨며 눈을 동그랗게 떴어요. 바다가 자신의 부름에 응했던 거죠.', '도메닉은 손을 벌벌 떨며 눈을 동그랗게 떴어요. 바다가 자신의 부름에 응했던 거죠.', 28153),
(161236, 'koKR', '그때 파도가 잔잔해졌어요. 괴물은 바위 때문에 꼼짝달싹하지 못하게 됐죠!', '그때 파도가 잔잔해졌어요. 괴물은 바위 때문에 꼼짝달싹하지 못하게 됐죠!', 28153),
(161234, 'koKR', '덕분에 도망치던 배는 바위 위로 떠 올랐답니다! 뒤를 쫓던 크라켄은 도망가는 먹잇감을 따라 헤엄쳐 왔고요!', '덕분에 도망치던 배는 바위 위로 떠 올랐답니다! 뒤를 쫓던 크라켄은 도망가는 먹잇감을 따라 헤엄쳐 왔고요!', 28153),
(161233, 'koKR', '', '다음 출장 전에 꼭 계측 장비를 보정해야겠어요.', 28153),
(161231, 'koKR', '그러더니 갑자기 배를 쫓던 녀석보다 세 배는 덩치가 더 큰 크라켄이 물 밖으로 나오지 뭐예요!', '그러더니 갑자기 배를 쫓던 녀석보다 세 배는 덩치가 더 큰 크라켄이 물 밖으로 나오지 뭐예요!', 28153),
(161229, 'koKR', '\"우린 다 죽었어!\" 선원들이 소리쳤어요.', '\"우린 다 죽었어!\" 선원들이 소리쳤어요.', 28153),
(161228, 'koKR', '갑자기 물속에서 거대한 바위들이 솟아올랐어요.', '갑자기 물속에서 거대한 바위들이 솟아올랐어요.', 28153),
(161227, 'koKR', '도메닉이 일러준 방향대로 바위 사이를 헤치며 도망쳤지만, 크라켄이 거리를 좁혀 왔어요!', '도메닉이 일러준 방향대로 바위 사이를 헤치며 도망쳤지만, 크라켄이 거리를 좁혀 왔어요!', 28153),
(161226, 'koKR', '\"항구로 전진!\" 당황한 도메닉이 외치자 물결인지 모를 무언가가 도메닉을 그 방향으로 잡아당겼고, 배가 방향을 틀었어요. \"우현으로!\" 그 말에 누이가 지시대로 키를 돌렸어요.', '\"항구로 전진!\" 당황한 도메닉이 외치자 물결인지 모를 무언가가 도메닉을 그 방향으로 잡아당겼고, 배가 방향을 틀었어요. \"우현으로!\" 그 말에 누이가 지시대로 키를 돌렸어요.', 28153),
(161225, 'koKR', '큰 배보다도 더 커다란 거대 크라켄이 바다 깊은 곳에서 용솟음쳤던 거예요!', '큰 배보다도 더 커다란 거대 크라켄이 바다 깊은 곳에서 용솟음쳤던 거예요!', 28153),
(161224, 'koKR', '하지만 그곳에 도달했을 때, 사냥당하는 건 자신들이란 걸 깨달았어요.', '하지만 그곳에 도달했을 때, 사냥당하는 건 자신들이란 걸 깨달았어요.', 28153),
(161223, 'koKR', '\"바다가 평온해지고 바람도 잔잔해질 거야.\" 도메닉이 말했어요. 작은 낚싯배가 속도를 낼수록 도메닉의 예언이 맞아떨어졌다는 게 드러나 모두들 놀랐죠.', '\"바다가 평온해지고 바람도 잔잔해질 거야.\" 도메닉이 말했어요. 작은 낚싯배가 속도를 낼수록 도메닉의 예언이 맞아떨어졌다는 게 드러나 모두들 놀랐죠.', 28153),
(161222, 'koKR', '\"위험해!\" 선원들이 소리쳤어요. \"배가 산산조각이 날 거야!\"', '\"위험해!\" 선원들이 소리쳤어요. \"배가 산산조각이 날 거야!\"', 28153),
(161221, 'koKR', '동생은 오랫동안 아무도 듣지 못하는 노래에 홀로 심취한 듯 질문을 곱씹더니 답했습니다. \"왠지 칼림도어 부근에서 많이 찾을 수 있을 것 같은데.\"', '동생은 오랫동안 아무도 듣지 못하는 노래에 홀로 심취한 듯 질문을 곱씹더니 답했습니다. \"왠지 칼림도어 부근에서 많이 찾을 수 있을 것 같은데.\"', 28153),
(161220, 'koKR', '\"동생아, 어디에서 사냥해야 할까?\" 코랄린은 여태껏 직감이 틀린 적 없는 동생에게 물었어요.', '\"동생아, 어디에서 사냥해야 할까?\" 코랄린은 여태껏 직감이 틀린 적 없는 동생에게 물었어요.', 28153),
(161219, 'koKR', '코랄린은 다른 곳에서 사냥해야 할 것 같다는 생각이 들었어요.', '코랄린은 다른 곳에서 사냥해야 할 것 같다는 생각이 들었어요.', 28153),
(161218, 'koKR', '먹을 것을 찾지 못한 지 몇 주가 지난 터라 상황은 점점 더 악화됐어요!', '먹을 것을 찾지 못한 지 몇 주가 지난 터라 상황은 점점 더 악화됐어요!', 28153),
(161217, 'koKR', '하루는 함께 배의 식량으로 쓸 크라켄을 사냥하기 위해 바다로 나갔어요. 크라켄이 자주 출몰하는 곳에 갔지만 그날따라 아무것도 찾을 수 없었죠!', '하루는 함께 배의 식량으로 쓸 크라켄을 사냥하기 위해 바다로 나갔어요. 크라켄이 자주 출몰하는 곳에 갔지만 그날따라 아무것도 찾을 수 없었죠!', 28153),
(161215, 'koKR', '도메닉은 바다에 관해 다른 이는 절대 알 수 없는 걸 아는 것 같았어요. 동생은 폭풍이 언제 밀려올지, 파도가 언제 바뀔지, 낚시할 만한 곳은 어딘지 알았거든요.', '도메닉은 바다에 관해 다른 이는 절대 알 수 없는 걸 아는 것 같았어요. 동생은 폭풍이 언제 밀려올지, 파도가 언제 바뀔지, 낚시할 만한 곳은 어딘지 알았거든요.', 28153),
(161214, 'koKR', '하지만 코랄린은 일을 보고 배우는 동안, 남동생도 지켜봤었답니다.', '하지만 코랄린은 일을 보고 배우는 동안, 남동생도 지켜봤었답니다.', 28153),
(161213, 'koKR', '이상하군요! 전에는 그런 이런 걸 본 적이 없는데...', '', 28153),
(161212, 'koKR', '적어놔야겠어요. 별이끼 추출물이 얼마 안 남았으니 가능할 때 구해 둘 것', '', 28153),
(161211, 'koKR', '그래서 코랄린이 선장이 되고서 선원으로 도메닉을 영입했을 땐 다들 얼마나 놀랐는지 몰라요. 도메닉 자신마저 놀랐어요!', '그래서 코랄린이 선장이 되고서 선원으로 도메닉을 영입했을 땐 다들 얼마나 놀랐는지 몰라요. 도메닉 자신마저 놀랐어요!', 28153),
(161210, 'koKR', '도메닉이 배를 더 잘 몰기 위해 어떤 시도를 했는지 말하지 않는 게 나을 정도였죠!', '도메닉이 배를 더 잘 몰기 위해 어떤 시도를 했는지 말하지 않는 게 나을 정도였죠!', 28153),
(161209, 'koKR', '아하, 단단히 잘 굳었군요.', '', 28153),
(161208, 'koKR', '도메닉은 삭구에서 균형을 잡지도 못하고, 아무리 알려 줘도 매듭을 묶거나 돛을 조절하는 법을 몰랐어요.', '도메닉은 삭구에서 균형을 잡지도 못하고, 아무리 알려 줘도 매듭을 묶거나 돛을 조절하는 법을 몰랐어요.', 28153),
(161207, 'koKR', '도메닉은 유별났어요. 자면서 마치 꿈을 꾸는 것처럼 갑판을 뛰어다니며 가끔 노래도 흥얼거렸죠.', '도메닉은 유별났어요. 자면서 마치 꿈을 꾸는 것처럼 갑판을 뛰어다니며 가끔 노래도 흥얼거렸죠.', 28153),
(161206, 'koKR', '이제 다시 열을 좀 더 가하면...', '', 28153),
(161205, 'koKR', '코랄린은 쿨 티란이 갖춰야 할 모든 덕목을 갖춘 아이였지만, 동생은 그렇지 못했어요.', '코랄린은 쿨 티란이 갖춰야 할 모든 덕목을 갖춘 아이였지만, 동생은 그렇지 못했어요.', 28153),
(161203, 'koKR', '코랄린은 별자리표와 해류, 사냥터에 관해 공부했어요. 선원들을 관찰하며 여러 가지를 배웠죠.', '코랄린은 별자리표와 해류, 사냥터에 관해 공부했어요. 선원들을 관찰하며 여러 가지를 배웠죠.', 28153),
(161202, 'koKR', '흐음... 엔게스에게 피아른스카글을 좀 더 주문해야 할지도 모르겠습니다.', '', 28153),
(161201, 'koKR', '코랄린은 힘이 세고 영리했죠.', '코랄린은 힘이 세고 영리했죠.', 28153),
(161200, 'koKR', '아주 오래전에 코랄린과 도메닉이라는 두 아이가 살고 있었어요.', '아주 오래전에 코랄린과 도메닉이라는 두 아이가 살고 있었어요.', 28153),
(161199, 'koKR', '', '사령관님, 고맙습니다. 구해 주시지 않았으면 우린 지금쯤 이 세상에 없었을 겁니다. 즉시 초소로 복귀하겠습니다.', 28153),
(161198, 'koKR', '미이미이가 당신을 따라다니기 시작합니다.', '미이미이가 당신을 따라다니기 시작합니다.', 28153),
(161197, 'koKR', '근처 석관에서 소리가 들립니다...', '근처 석관에서 소리가 들립니다...', 28153),
(161196, 'koKR', '미라 미이미이가 기다렸다는 듯이 당신을 바라봅니다.', '미라 미이미이가 기다렸다는 듯이 당신을 바라봅니다.', 28153),
(161195, 'koKR', '물고기가 없다고요? 이러다 굶어 죽겠네요.', '', 28153),
(161194, 'koKR', '마지막으로 먹은 지가 언제인지 모르겠습니다.', '', 28153),
(161193, 'koKR', '입질이 없다고요? 아직도요?!', '', 28153),
(161192, 'koKR', '지금껏 나는 수많은 기념비적인 순간을 보았다네. 역사가 펼쳐지는 것, 갈등이 해결되고 다시 얽히는 것, 배신, 위대한 승리를 보았지.\n\n그리고 이건 분명히 패배의 순간일세. 줄은 모든 수에서 우리를 앞질렀고 결국 목적을 이루었네. 이대로 끝을 맞이할 수는 없어.\n\n잔달라 백성이 처음 빚어졌을 때부터 함께 존재했던 이 고대의 적과의 전쟁은 호드와 잔달라의 운명을 한 배에 태울 걸세. 우리는 그들의 부름에 답할 거라네. 줄이 어지럽혀 놓은 것들을 다시 바로잡을 걸세.\n\n항상 대비하게. 늘 깨어 있게. 절대 흔들려서는 안 된다네, $n|1이여;여;.', '', 28153),
(161191, 'koKR', '', '당신 부대에 보급품을 전하지 못하게 될까봐 걱정했습니다. 고맙습니다. 제 선물이니 이 자원을 받아 주십시오.', 28153),
(161190, 'koKR', '잔달라의 왕이 무슨 생각을 하고 있는지 모르겠지만, 이런 사건들 때문에 우리의 목표가 흔들려서는 안 되네. 잔달라는 이 분쟁을 견뎌내야 할 걸세. 호드는 잔달라의 백성을 지킬 것을 맹세했지만 만약 그들의 신이 자신의 백성을 지키지 않기로 했다면 우린 홀로서야 할 수도 있다네.\n\n지금 그들은 그 어느 때보다도 자네에게 의존하고 있네. 소신 있게 행동하게, 호드의 대변자여.', '', 28153),
(161189, 'koKR', '', '와, 이제 죽었구나 싶던 찰나에 당신이 나타났어요! 감사의 표시로 부대의 방어구를 강화해 드릴게요. 고맙습니다!', 28153),
(161188, 'koKR', '마법과 까마득히 먼 세상을 갈망하십니까? 아니면 전쟁 때문에 당분간 멀리 떠나려는 겁니까?\n\n스톰윈드, 아이언포지, 엑소다르로 가는 차원문을 찾고 있다면 남쪽 무역풍 시장 하층으로 가면 됩니다. 별난 에테리얼 형상변환사 바로 옆에 있는 방을 찾아보십시오.', '마법과 까마득히 먼 세상을 갈망하십니까? 아니면 전쟁 때문에 당분간 멀리 떠나려는 겁니까?\n\n스톰윈드, 아이언포지, 엑소다르로 가는 차원문을 찾고 있다면 남쪽 무역풍 시장 하층으로 가면 됩니다. 별난 에테리얼 형상변환사 바로 옆에 있는 방을 찾아보십시오.', 28153),
(161187, 'koKR', '', '희망을 놓아선 안 되오. 제이나는 아직 살아 있을지도 모르오.', 28153),
(161186, 'koKR', '당신의 눈동자에 드리운 어둠이 보입니다. 당신은 다음 행동으로 정신이 파괴되고, 또다른 환영이 되어 나를 괴롭하겠지요.$b$b당신은 아직 준비가 안 되었습니다. 준비가 되면 돌아오십시오. 다음 할 일이 기다리고 있을 겁니다. 부패는 영겁의 시간 동안 곪아가며 자라납니다. 결국 며칠 정도는 대수롭지 않을 겁니다.', '', 28153),
(161185, 'koKR', '애쉬베인의 사무실에서 이 단서를 찾았습니다.', '애쉬베인의 사무실에서 이 단서를 찾았습니다.', 28153),
(161184, 'koKR', '드디어 절 구하러 오셨군요? 흠, 제가 빚을 진 셈이네요. 보답으로 당신 부대의 무기를 강화드리는 건 어떻겠습니까?', '', 28153),
(161183, 'koKR', '', '난 제이나가 죽었다고 믿지 않겠소.', 28153),
(161181, 'koKR', '무역풍 콜쉬 맥주 정말 마음에 듭니다. 통도 찌그러뜨릴 수 있고 말이죠!\n\n이건 도로 던져 놓고 다른 걸 가져와야겠습니다!', '', 28153),
(161180, 'koKR', '전 여기 맥주가 너무 맛있어요. 제가 제일 좋아하는 맥주 중 하나지요!\n\n건배!', '', 28153),
(161179, 'koKR', '저희 양조장에 오신 걸 환영합니다!\n\n저희가 제공하는 맥주를 즐겁게 음미하시길 바랍니다. 행사용 맥주를 통으로 구입하시려면 큰소리로 절 불러 주십시오.\n\n막간을 이용해 한잔하시지 그래요?', '', 28153),
(161178, 'koKR', '여기 있었군! 줄의 세력이 우리를 몰아내려 했지만 호드가 힘을 발휘했다네. 당장은 전투가 끝났어.\n\n우리에게는 줄이 음모를 꾸미고 있다고 의심할 만한 근거가 있었다네. 하지만 이렇게 빨리, 과감하게 행동할 줄은 미처 예상치 못했지. 줄의 예언자로서의 능력은 과찬이 아니었던 모양이군.\n\n우리의 새로운 아군을 보호해야 하네. 가서 라스타칸 왕이 다시 권력을 잡을 수 있도록 돕게. 호드는 여기서 질서를 유지하겠네.', '', 28153),
(161177, 'koKR', '이 왕좌에 처음 앉았던 분은 온 세상의 문명인을 지배했습니다.\n\n지금 우리의 꼴을 보십시오. 세력은 달랑 섬 하나로 줄어들었고, 열등한 트롤마저 우리의 힘에 반항합니다.\n\n이대로 내버려 두지는 않겠습니다.', '', 28153),
(161176, 'koKR', '저 새 배를 타고 오신 겁니까? 맥주 한 잔 마시면서 배의 구조나 조선술 관해 이야기해 주십시오.', '', 28153),
(161175, 'koKR', '새로운 하루를 새로운 맥주와 함께!\n\n당신은 어떤 맥주를 가장 좋아합니까?', '', 28153),
(161174, 'koKR', '뭐 고칠 거라도 있습니까?', '', 28153),
(161173, 'koKR', '들이킵시다!', '', 28153),
(161172, 'koKR', '내 딸 아이는 나즈미르에 닥친 위기가 너무도 커서 병력을 모두 북쪽 국경으로 보내야 한다는군.\n\n그 아이는 어리고 참을성이 없다. 혈트롤들이 우리 백성을 수 세대에 걸쳐 괴롭혀왔는지 모르는 게 분명하다.\n\n호드가 우리를 도울 수 있다고 딸아이가 믿고 있으니, 나는 자네들이 무슨 일을 해내는지 지켜보겠다. 이를 계기로 외부 세력을 어떻게 상대해야 하는지 그 아이에게도 도움이 될지도.\n\n만약 그 아이가 위험에 처한다면, 너희 호드 놈들을 깡그리 불태우고 네놈들이 함대라 칭하는 조악한 나룻배들을 산산조각낼 것이다.\n\n행운을 빈다.', '', 28153),
(161171, 'koKR', '다들 건배하시지요!', '', 28153),
(161170, 'koKR', '우선 이것만 마저 마시고 가서 도울 예정입니다.', '', 28153),
(161169, 'koKR', '말퓨리온 님이 보내신 전언에 따르면 불타는 군단이 부서진 해변을 공격하고 있다는군요!', '', 28153),
(161168, 'koKR', '여기서 밀드레드를 만나기 전까진 티란데랑 저는 단짝이었습니다.', '', 28153),
(161167, 'koKR', '바로 팔 걷어붙이고 한 통도 빠짐없이 모든 럼주 통을 건져 냈지요!', '', 28153),
(161166, 'koKR', '배가 침몰해 곳곳에서 탑승자들이 익사하는 중에 티라가드 럼주 서른 통이 바다에 가라앉고 있지 몹니까.', '', 28153),
(161165, 'koKR', '꿈숲에는 괜찮은 스타우트 맥주가 하나도 없습니다. 그래서 전 그쪽은 절대 안 가지요.', '', 28153),
(161164, 'koKR', '줄다자르로 가실 분은 어서 타십시오!', '', 28153),
(161163, 'koKR', '메아리 섬으로 가실 분은 어서 타십시오!', '', 28153),
(161162, 'koKR', '밀려오는 전쟁의 물결을 두려워하지 마십시오, $p 님. 진정 시험에 들 때에만 우리의 가장 강인한 모습이 드러납니다.', '', 28153),
(161161, 'koKR', '왕한테 가서 날 좀 다른 곳에서 일하게 해 달라고 잘 좀 말해주시오!', '', 28153),
(161160, 'koKR', '싸움은 이제 시작되었을 뿐입니다, $p 님. 전쟁의 시련을 이겨낼 준비가 되셨길 바랍니다.', '', 28153),
(161159, 'koKR', '이런 곳에서 일하려면 돈을 더 받아야 하는데. 위험수당 말이오, $r 양반! 위험수당!', '', 28153),
(161158, 'koKR', '벌레가 아랫도리를 물어댈 때마다 마음 같아선 내 몸을 다 불태워 버리고 싶다오. 여긴 정말 나랑 안 맞는군!', '', 28153),
(161157, 'koKR', '호드가 가장 강력한 병사들을 보내준다면야 환영이지요. 호적수에게 칼날을 시험하는 것만큼 좋은 일은 없으니 말입니다.', '', 28153),
(161156, 'koKR', '아, 더워 죽겠군! 내 수염을 타고 흘러내리는 땀방울이 보이시오?', '', 28153),
(161155, 'koKR', '도움을 주실 기회가 생긴다면 주저하지 마십시오. 이렇게 위태로운 시기에 허락을 기다릴 필요는 없습니다.', '', 28153),
(161154, 'koKR', '걱정 마십시오. 이 배는 잔달라에서 가장 빠른 배 중 하나랍니다. 목적지까지 안전하게 모셔다드리겠습니다.', '', 28153),
(161153, 'koKR', '호드를 물리치려면 영리하고 꼼꼼해져야 합니다. 실수는 용납되지 않지요.', '', 28153),
(161152, 'koKR', '메아리 섬에 도착했습니다!', '', 28153),
(161151, 'koKR', '줄다자르에 도착했습니다!', '', 28153),
(161150, 'koKR', '색깔 순서대로 맥주를 다시 정렬해 두었어요.\n\n잠깐. 철자 순으로 놔야 할까요? 아니면 날짜? 종류?', '', 28153),
(161149, 'koKR', '', '안녕하세요. 믿음직한 동료를 찾고 계신가요? 비바람 부는 날에 꼭 끌어안을 동물을 찾으시나요? 인생의 기쁨과 슬픔을 나눌 친구가 필요하신가요?', 28153),
(161148, 'koKR', '으음... 내가 기술을 배웠던 때가... 생각나는군요... 세콧이 입에 달고 사는 말이... 곡괭이를 특정한 각도로 휘두르는 것이... 광석을 보존하는... 요령이라고 했는데...', '으웩! 해과일이 너무 많이 들어갔는데요...', 28153),
(161147, 'koKR', '사령관님, 고맙습니다. 구해 주시지 않았으면 우린 지금쯤 이 세상에 없었을 겁니다. 즉시 초소로 복귀하겠습니다.', '', 28153),
(161146, 'koKR', '뭐라고 할까, \"노새\" 맛이었습니다.', '뭐라고 할까, \"노새\" 맛이었습니다.', 28153),
(161145, 'koKR', '우리의 승리가 보인다.', '우리의 승리가 보인다.', 28153),
(161144, 'koKR', '이 숲은 늘 마음에 들지 않았어.', '이 숲은 늘 마음에 들지 않았어.', 28153),
(161143, 'koKR', '방금 그건... 걸레 빤 물이었습니까?', '방금 그건... 걸레 빤 물이었습니까?', 28153),
(161142, 'koKR', '나무는 우리 것이다.', '나무는 우리 것이다.', 28153),
(161141, 'koKR', '우웩! 전 진을 싫어합니다!', '우웩! 전 진을 싫어합니다!', 28153),
(161140, 'koKR', '', '배가 이미 잔달라를 떠나 지금쯤 이곳으로 오고 있을 겁니다.', 28153),
(161139, 'koKR', '그래도 전장이 내 무덤이군.', '그래도 전장이 내 무덤이군.', 28153),
(161138, 'koKR', '', '바다 건너 잔달라에 있는데, 곧 돌아올 테니 걱정 붙들어 매십시오.', 28153),
(161137, 'koKR', '성가신 녀석이로구나.', '성가신 녀석이로구나.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161136, 'koKR', '끔찍한 맛이었습니다, 친구.', '끔찍한 맛이었습니다, 친구.', 28153),
(161135, 'koKR', '', '배가 방금 잔달라로 출항했습니다만, 금세 돌아올 겁니다.', 28153),
(161134, 'koKR', '', '바로 앞에 있습니다. 타십시오!', 28153),
(161133, 'koKR', '윽, 이건 뭡니까? 토르톨란 포도주인가요?', '윽, 이건 뭡니까? 토르톨란 포도주인가요?', 28153),
(161132, 'koKR', '갈고리 시장 에일 맥주는 구운 덩굴손 씨앗과 함께 드셔 보시길 권합니다.\n\n씨앗 때문에 거부감을 가질 필요 없습니다. 바짝 구웠기 때문에 맥아 향과 어우러져 맥주의 향을 훨씬 더 풍부하게 해 준답니다. 좀 희한한 조합처럼 들릴지 몰라도 개인적으로 제가 제일 좋아하는 맛이랍니다.', '', 28153),
(161131, 'koKR', '으웩! 해과일이 너무 많이 들어갔는데요...', '으웩! 태양과가 너무 많이 들어갔는데요...', 28153),
(161130, 'koKR', '녹청빛 에일 맥주는 제가 개인적으로 좋아하는 콜 텐더스 양념 닭튀김과 함께하면 끝내줍니다.\n\n맥주에 감도는 옅은 꿀의 달콤함과 닭고기 양념이 잘 어울리죠. 양념이 너무 세다고 느껴질 땐 맥주의 밀 향이 강도를 잡아 줄 겁니다.', '', 28153),
(161129, 'koKR', '제 물건 구경하러 오신 거예요?', '', 28153),
(161128, 'koKR', '그분을 본받으십시오. 꺾이지 말고 휘어지십시오. 그리고 적에게 본때를 보여준 다음 바위 위로 떨어뜨리십시오!', '그분을 본받으십시오. 꺾이지 말고 휘어지십시오. 그리고 적에게 본때를 보여준 다음 바위 위로 떨어뜨리십시오!', 28153),
(161127, 'koKR', '', '확실하지 않아요, 하지만 수평선 너머에서 폭풍우가 몰아칠 것 같습니다.', 28153),
(161126, 'koKR', '바람이 가져오는 것은 폭풍과 무역뿐만이 아닙니다. 바람은 변화를 가져옵니다. 파쿠 님께서 저희에게 부러지지 말고 견뎌내라고 가르치셨던 변화 말입니다.', '바람이 가져오는 것은 폭풍과 무역뿐만이 아닙니다. 바람은 변화를 가져옵니다. 파쿠 님께서 저희에게 부러지지 말고 견뎌내라고 가르치셨던 변화 말입니다.', 28153),
(161125, 'koKR', '저는 그냥 *딸꾹* 술이나 한잔 하려고 했는데...', '저는 그냥 *딸꾹* 술이나 한잔 하려고 했는데...', 28153),
(161124, 'koKR', '너희는 이미 패배했다!', '너희는 이미 패배했다!', 28153),
(161123, 'koKR', '우리의 것을 받아가마!', '우리의 것을 받아가마!', 28153),
(161122, 'koKR', '폭풍에 꺾인 이들의 악의적인 말에 귀를 기울이지 마십시오. 대신 휘어졌던 이들에게 귀를 기울이십시오.', '폭풍에 꺾인 이들의 악의적인 말에 귀를 기울이지 마십시오. 대신 휘어졌던 이들에게 귀를 기울이십시오.', 28153),
(161121, 'koKR', '뭐가 있습니까?', '뭐가 있습니까?', 28153),
(161120, 'koKR', '그분께서는 무자비하고, 성미가 급하시며, 변덕스럽다고 알려져 있습니다. 하지만 감히 말씀드리건대 더 자세히 알아보십시오.', '그분께서는 무자비하고, 성미가 급하시며, 변덕스럽다고 알려져 있습니다. 하지만 감히 말씀드리건대 더 자세히 알아보십시오.', 28153),
(161119, 'koKR', '내가 죽여주는 걸 영광으로 알아라.', '내가 죽여주는 걸 영광으로 알아라.', 28153),
(161118, 'koKR', '공짜 술이요?', '공짜 술이요?', 28153),
(161117, 'koKR', '이번엔 맛이 좋아야 할 겁니다...', '이번엔 맛이 좋아야 할 겁니다...', 28153),
(161116, 'koKR', '그분의 바람은 비를 내리시고, 항해를 도우시며, 배를 바다 너머로 보내십니다. 그분의 권능으로 우리가 있습니다!', '그분의 바람은 비를 내리시고, 항해를 도우시며, 배를 바다 너머로 보내십니다. 그분의 권능으로 우리가 있습니다!', 28153),
(161115, 'koKR', '풍미 가득한 염장한 갯고랑 대구를 부교 필슨 맥주와 함께 드십시오.\n\n맥주의 청량함과 대구의 달짝지근함이 안 어울릴 듯 잘 어울리는 데다 홉이 생선의 염도를 알맞게 조절해 준답니다.', '', 28153),
(161114, 'koKR', '', '잔달라로 가는 길이십니까? 마침 여기 부두의 배가 그쪽으로 갑니다, 친구.', 28153),
(161113, 'koKR', '지금 가요, 내 사랑...', '지금 가요, 내 사랑...', 28153),
(161112, 'koKR', '아마니 뮬 제공', '아마니 뮬 제공', 28153),
(161111, 'koKR', '자니 즙 제공', '자니 즙 제공', 28153),
(161110, 'koKR', '모조히토 제공', '모조히토 제공', 28153),
(161109, 'koKR', '줄의 진 제공', '줄의 진 제공', 28153),
(161108, 'koKR', '브원좀비 제공', '브원좀비 제공', 28153),
(161107, 'koKR', '동굴 맥주 제공', '동굴 맥주 제공', 28153),
(161106, 'koKR', '닻내림 둔켈 맥주에 헤더포드산 갈색치즈를 곁들여 드셔 보길 권합니다.\n\n좋은 맥주에 치즈, 그만한 천생연분도 없죠. 각각 살짝 단맛을 품고 있어서 함께 즐기면 입안에 퍼지는 맛이 최고랍니다.', '', 28153),
(161105, 'koKR', '트롤섞었주 제공', '트롤섞었주 제공', 28153),
(161104, 'koKR', '죽음이 널 데려가리...', '죽음이 널 데려가리...', 28153),
(161103, 'koKR', '', '제 애완동물은 아군이 전투에서 패할 때마다 점점 더 강해집니다.', 28153),
(161102, 'koKR', '새들의 노랫소리가 왜 멈춘 거지...?', '새들의 노랫소리가 왜 멈춘 거지...?', 28153),
(161101, 'koKR', '티란데 여군주께서 널 막을 것이다.', '티란데 여군주께서 널 막을 것이다.', 28153),
(161100, 'koKR', '', '잔달라의 종은 다른 어느 곳의 종과는 비교할 수 없을 만큼 강해요. 당신이 데리고 있는 다른 애완동물은 승산이 없을 겁니다.', 28153),
(161099, 'koKR', '밤호랑이를 궁지에 몰면 어떻게 되는지 보여주마.', '밤호랑이를 궁지에 몰면 어떻게 되는지 보여주마.', 28153),
(161098, 'koKR', '이 땅은 우리 것이다!', '이 땅은 우리 것이다!', 28153),
(161097, 'koKR', '', '이건 예상치 못한 결말인걸요? 다음엔 제가 꼭 이길 겁니다, 이방인님.', 28153),
(161096, 'koKR', '', '제게 익숙한 곳이니 아무래도 제가 유리했던 것 같군요.', 28153),
(161095, 'koKR', '너에게 명예는 없다.', '너에게 명예는 없다.', 28153),
(161094, 'koKR', '', '제 구역에서 저와 붙어보시겠다? 행운을 빕니다.', 28153),
(161093, 'koKR', '죽이고 싶진 않지만, 어쩔 수 없군.', '죽이고 싶진 않지만, 어쩔 수 없군.', 28153),
(161092, 'koKR', '', '이곳에서 가장 강한 종은 따로 있는 것 같군요. 계속 돌아다니며 다른 종들을 포획해야겠습니다.', 28153),
(161091, 'koKR', '우리 눈꽃딸기 맥주에 곁들일 안주로 눈꽃딸기 커스터드를 감히 추천합니다!\n\n이 조합이면 눈꽃딸기의 두 가지 매력을 모두 경험할 수 있어요. 맥주에서는 시큼함을, 커스터드에서는 과하지 않은 달콤함을 맛볼 수 있죠. 커스터드의 풍부한 크림이 맥주의 쓴맛과 어우러져 기가 막힌 맛을 냅니다.', '', 28153),
(161090, 'koKR', '', '저거 아무래도 흉이 지겠는데요.', 28153),
(161089, 'koKR', '', '새로운 종을 훈련시킬 시간이 더 필요하겠군요. 다음 번에는 더 강해져 있을 겁니다.', 28153),
(161088, 'koKR', '', '말씀 드렸지요, 이 땅의 생물들은 흉포하다고요. 아무튼 멋진 대전이었습니다.', 28153),
(161087, 'koKR', '', '이 땅의 생물들은 흉포합니다. 준비 되셨길 바랄게요.', 28153),
(161086, 'koKR', '', '작은 친구, 제가 보살펴 드릴 테니 걱정 마십시오.', 28153),
(161085, 'koKR', '만물은 죽음을 맞이한다.', '만물은 죽음을 맞이한다.', 28153),
(161084, 'koKR', '', '이번에 졌다고 슬퍼하지 마십시오. 당신의 다른 애완동물도 충분히 강해 보이니까요.', 28153),
(161083, 'koKR', '고향을 지켰을 따름이다.', '고향을 지켰을 따름이다.', 28153),
(161082, 'koKR', '', '아무래도 제 연습이 부족한 모양입니다.', 28153),
(161081, 'koKR', '꿈을 꾸기를...', '꿈을 꾸기를...', 28153),
(161080, 'koKR', '', '맙소사. 우리 팀이 이렇게 강한 줄은 저도 몰랐군요.', 28153),
(161079, 'koKR', '낙엽이 지는구나...', '낙엽이 지는구나...', 28153),
(161078, 'koKR', '네놈을 느긋하게 처리할 시간만 있었더라도.', '네놈을 느긋하게 처리할 시간만 있었더라도.', 28153),
(161077, 'koKR', '', '대전은 아주 오랜만입니다만, 당신을 상대할 정도의 실력은 남아있으면 좋겠군요.', 28153),
(161076, 'koKR', '발톱을 맛봐라!', '발톱을 맛봐라!', 28153),
(161075, 'koKR', '가시가 널 뚫는다!', '가시가 널 뚫는다!', 28153),
(161074, 'koKR', '', '아, 아직 준비 안 됐는데! 이번 건 무효예요!', 28153),
(161073, 'koKR', '숲의 복수를 내려주마!', '숲의 복수를 내려주마!', 28153),
(161072, 'koKR', '', '이거, 제 연승이 계속될 것 같네요.', 28153),
(161071, 'koKR', '무역풍 콜쉬 맥주는 수제로 만든 회향호밀 빵덩이와 함께 즐기면 좋습니다.\n\n맥주와 향의 구수한 맛과 향이 어우러져 제법이거든요. 게다가 탄산이 주는 청량감도 그만이죠.', '', 28153),
(161070, 'koKR', '', '이건 졌다고 볼 수 없으니까, 제 연승은 계속되는 거예요.', 28153),
(161069, 'koKR', '', '만세, 제 연승 가도가 계속되네요!', 28153),
(161068, 'koKR', '', '전 지금 불붙었다고요. 당신이 우리 팀의 적수가 되긴 어려울 것 같은데요.', 28153),
(161067, 'koKR', '|TInterface\\Icons\\ABILITY_WARLOCK_HAUNT.BLP:20|t화신이 더는 |cFFFF0000|Hspell:274148|h[오염]|h|r되어 있지 않습니다. 이제 화신이 받는 모든 치유가 완전해집니다!', '|TInterface\\Icons\\ABILITY_WARLOCK_HAUNT.BLP:20|t화신이 더는 |cFFFF0000|Hspell:274148|h[오염]|h|r되어 있지 않습니다. 이제 화신이 받는 모든 치유가 완전해집니다!', 28153),
(161066, 'koKR', '패잔병같이 겁먹은 모습은 보이지 마십시오. 다시 도전하는 겁니다.', '', 28153),
(161065, 'koKR', '먹을 것을 좀 사고 싶은데요.', '먹을 것을 좀 사고 싶은데요.', 28153),
(161064, 'koKR', '승리가 코앞까지 왔습니다. 느낄 수 있어요.', '', 28153),
(161063, 'koKR', '공크 님께 감사를 표하고, 그의 무리와 함께하십시오. 그리고 동시에 여러분에게 다른 길이 열려 있다는 사실을 기억하십시오. 이것이 그분께서 잔달라 트롤에게 주신 선물입니다.', '공크 님께 감사를 표하고, 그의 무리와 함께하십시오. 그리고 동시에 여러분에게 다른 길이 열려 있다는 사실을 기억하십시오. 이것이 그분께서 잔달라 트롤에게 주신 선물입니다.', 28153),
(161062, 'koKR', '공크 님께서는 현명하시어 우리가 뭉쳐 있을 때 더 강하다는 사실을 아십니다. 그분은 여러분의 제단에 그분의 우상을 세우라고 강요하지 않으십니다.', '공크 님께서는 현명하시어 우리가 뭉쳐 있을 때 더 강하다는 사실을 아십니다. 그분은 여러분의 제단에 그분의 우상을 세우라고 강요하지 않으십니다.', 28153),
(161061, 'koKR', '갈고리 시장 에일 맥주에 어떤 안주를 곁들이면 좋을까요?', '갈고리 시장 에일 맥주에 어떤 안주를 곁들이면 좋을까요?', 28153),
(161060, 'koKR', '놀랍군요. 몇 년 동안 한 번도 진 적이 없었는데. 멋진 승부였습니다!', '', 28153),
(161059, 'koKR', '조금만 더 연습하면 제게 도전할 실력을 갖추실 겁니다, 힘내십시오.', '', 28153),
(161058, 'koKR', '녹청빛 에일 맥주에 어떤 안주를 곁들이면 좋을까요?', '녹청빛 에일 맥주에 어떤 안주를 곁들이면 좋을까요?', 28153),
(161057, 'koKR', '부교 필슨 맥주에 어떤 안주를 곁들이면 좋을까요?', '부교 필슨 맥주에 어떤 안주를 곁들이면 좋을까요?', 28153),
(161056, 'koKR', '닻내림 둔켈 맥주에 어떤 안주를 곁들이면 좋을까요?', '닻내림 둔켈 맥주에 어떤 안주를 곁들이면 좋을까요?', 28153),
(161055, 'koKR', '눈꽃딸기 맥주에 어떤 안주를 곁들이면 좋을까요?', '눈꽃딸기 맥주에 어떤 안주를 곁들이면 좋을까요?', 28153),
(161054, 'koKR', '무역풍 콜쉬 맥주에 어떤 안주를 곁들이면 좋을까요?', '무역풍 콜쉬 맥주에 어떤 안주를 곁들이면 좋을까요?', 28153),
(161053, 'koKR', '다른 로아들께서는 화를 내셨습니다. 그분에게 침을 뱉으셨으며, 그분이 변덕스럽고 나약하며 마땅히 받아야 할 것을 받지 않고 있다고 하셨습니다.', '다른 로아들께서는 화를 내셨습니다. 그분에게 침을 뱉으셨으며, 그분이 변덕스럽고 나약하며 마땅히 받아야 할 것을 받지 않고 있다고 하셨습니다.', 28153),
(161052, 'koKR', '그분은 추종자들에게 말씀하셨습니다. \"네게 알맞은 길을 선택하거라. 내 안에서는 모두가 하나의 무리이니.\"', '그분은 추종자들에게 말씀하셨습니다. \"네게 알맞은 길을 선택하거라. 내 안에서는 모두가 하나의 무리이니.\"', 28153),
(161051, 'koKR', '맥주에 어울릴 만한 맛있는 음식을 찾고 계십니까?\n\n저한테 마침 딱 맞는 안주가 있습니다.', '', 28153),
(161050, 'koKR', '변신의 로아께서는 자신의 백성을 살피시고는 백성이 요구하는 것이 아주 많다는 사실을 깨달으셨습니다. 그분이 채우실 수 없는 요구들이었지요.', '변신의 로아께서는 자신의 백성을 살피시고는 백성이 요구하는 것이 아주 많다는 사실을 깨달으셨습니다. 그분이 채우실 수 없는 요구들이었지요.', 28153),
(161049, 'koKR', '잘 생각해 보십시오, 형제자매여. 현명하게 선택하십시오.', '잘 생각해 보십시오, 형제자매여. 현명하게 선택하십시오.', 28153),
(161048, 'koKR', '아니면 해가 지고 하늘이 어두컴컴해질 때까지 고문받고 싶으신가요?', '아니면 해가 지고 하늘이 어두컴컴해질 때까지 고문받고 싶으신가요?', 28153),
(161047, 'koKR', '여러분은 그분과 함께 웃을 것입니까? 다른 고마워하는 영혼들과 춤을 추시겠습니까?', '여러분은 그분과 함께 웃을 것입니까? 다른 고마워하는 영혼들과 춤을 추시겠습니까?', 28153),
(161046, 'koKR', '여러분의 숨이 멎고 영혼이 반대편으로 건너갈 때, 브원삼디 님은 여러분을 친구로 삼으실까요?', '여러분의 숨이 멎고 영혼이 반대편으로 건너갈 때, 브원삼디 님은 여러분을 친구로 삼으실까요?', 28153),
(161045, 'koKR', '여러분께 다시 알려드리겠습니다. 브원삼디 님께서는 산 자의 세계도 지켜보고 계십니다. 평가 차원에서 말입니다.', '여러분께 다시 알려드리겠습니다. 브원삼디 님께서는 산 자의 세계도 지켜보고 계십니다. 평가 차원에서 말입니다.', 28153),
(161044, 'koKR', '여러분은 생각하시겠지요. 나는 아직 살아 있으니, 아직은 그런 로아께 제단을 내줄 필요가 없다고요.', '여러분은 생각하시겠지요. 나는 아직 살아 있으니, 아직은 그런 로아께 제단을 내줄 필요가 없다고요.', 28153),
(161043, 'koKR', '크라그와 님께서 돌아오셨습니다. 그분께서 잔달라 백성들에게 가르치는 말씀을 들어보십시오.', '크라그와 님께서 돌아오셨습니다. 그분께서 잔달라 백성들에게 가르치는 말씀을 들어보십시오.', 28153),
(161042, 'koKR', '용기를 찾아 헤매는 자, 다른 이를 보호할 힘을 찾는 자, 삶을 계속할 의지를 찾는 자여, 더는 방황하지 마십시오.', '용기를 찾아 헤매는 자, 다른 이를 보호할 힘을 찾는 자, 삶을 계속할 의지를 찾는 자여, 더는 방황하지 마십시오.', 28153),
(161041, 'koKR', '형제자매여, 그분의 이야기를 마음속 깊이 새기십시오. 여러분의 것을 보호하시겠다는 신념은 강력한 축복입니다.', '형제자매여, 그분의 이야기를 마음속 깊이 새기십시오. 여러분의 것을 보호하시겠다는 신념은 강력한 축복입니다.', 28153),
(161040, 'koKR', '크라그와 님은 설령 공허가 그분을 위협할지라도, 그분의 추종자를 지킬 수 있다는 사실을 증명하셨습니다.', '크라그와 님은 설령 공허가 그분을 위협할지라도, 그분의 추종자를 지킬 수 있다는 사실을 증명하셨습니다.', 28153),
(161039, 'koKR', '이 말씀을 드리기 위해 이 자리에 섰습니다. 위대하신 수호자께서 돌아오셨으며, 그분의 힘은 여전히 강대하십니다.', '이 말씀을 드리기 위해 이 자리에 섰습니다. 위대하신 수호자께서 돌아오셨으며, 그분의 힘은 여전히 강대하십니다.', 28153),
(161038, 'koKR', '새로운 도전자는 언제든 환영이지요.', '', 28153),
(161037, 'koKR', '애완동물용 붕대를 좀 더 만들어야겠는데요.', '', 28153),
(161036, 'koKR', '잘 싸웠어요, 꼬마 친구. 점점 더 나아질 거예요!', '', 28153),
(161035, 'koKR', '에잇, 지는 건 싫은데. 그래도 좋은 승부였어요.', '', 28153),
(161034, 'koKR', '새로운 폭풍이 다가오는 것은 다시 시작할 기회를 의미합니다. 지평선을 덮은 구름을 두려워하지 마십시오.', '새로운 폭풍이 다가오는 것은 다시 시작할 기회를 의미합니다. 지평선을 덮은 구름을 두려워하지 마십시오.', 28153),
(161033, 'koKR', '제가 이겼다고요? 맙소사, 친구들한테 자랑해야지!', '', 28153),
(161032, 'koKR', '위대한 도전의 시간입니다!', '', 28153),
(161031, 'koKR', '쏟아지는 시련을 통해 우리의 힘과 결의를 시험하는 것인지도 모릅니다. 진정 강한 자들은 구름이 걷힌 후에도 여전히 서 있겠지요.', '쏟아지는 시련을 통해 우리의 힘과 결의를 시험하는 것인지도 모릅니다. 진정 강한 자들은 구름이 걷힌 후에도 여전히 서 있겠지요.', 28153),
(161030, 'koKR', '그녀석은 좀 소름 끼치는 편이었거든. 차라리 잘 됐네.', '', 28153),
(161029, 'koKR', '그분의 번개에는 분노가, 천둥에는 노여움이 담겨 있습니다. 하지만 변화의 고통은 원래 쉽지 않은 법이지요.', '그분의 번개에는 분노가, 천둥에는 노여움이 담겨 있습니다. 하지만 변화의 고통은 원래 쉽지 않은 법이지요.', 28153),
(161028, 'koKR', '바람이 지상을 깨끗이 청소하고 새로운 생명이 자랄 곳을 마련해 주실 겁니다.', '바람이 지상을 깨끗이 청소하고 새로운 생명이 자랄 곳을 마련해 주실 겁니다.', 28153),
(161027, 'koKR', '그 아이가 피의 제물로 바쳐지기 전에 치료해 주든가 어떻게 좀 해 주게나.', '', 28153),
(161026, 'koKR', '그분께서는 지평선을 덮은 폭풍을 두려워하지 말라 가르치셨습니다. 폭풍우가 과거의 아픔을 씻어내릴 것이라고 말이지요.', '그분께서는 지평선을 덮은 폭풍을 두려워하지 말라 가르치셨습니다. 폭풍우가 과거의 아픔을 씻어내릴 것이라고 말이지요.', 28153),
(161025, 'koKR', '여긴 터가 안 좋은가 보군. 이렇게 참담하게 진 적이 없는데 말이야.', '', 28153),
(161024, 'koKR', '제법 잘 싸웠지만 자넨 내 상대가 못 되네.', '', 28153),
(161023, 'koKR', '여긴 어째 좀 으스스하군. 빨리 싸우고 끝내세.', '', 28153),
(161022, 'koKR', '인정머리 없는 이 같으니! 저 아이는 제가 가장 아끼는 아이였단 말입니다.', '', 28153),
(161021, 'koKR', '또 한 놈이 쓰러졌군요.', '', 28153),
(161020, 'koKR', '소리 한 번 지르면 제가 한 잔 대접하겠습니다!\n\n하지만 원하는 게 비행이라면 다른 이한테 물어보십시오. 제 온전한 정신을 위해.', '', 28153),
(161019, 'koKR', '', '그럼요! 여기요.', 28153),
(161018, 'koKR', '전 지는 게 정말 싫습니다! 다음엔 반드시 더 강해진 모습을 보여 드리겠습니다.', '', 28153),
(161017, 'koKR', '여분의 우유 통이 있으십니까?', '여분의 우유 통이 있으십니까?', 28153),
(161016, 'koKR', '최고의 팀, 바로 제가 또 한 번 승리하는군요!', '', 28153),
(161015, 'koKR', '전투에 나설 시간이 됐습니다! 자, 해봅시다!', '', 28153),
(161014, 'koKR', '|TInterface\\Icons\\INV_PET_TOAD_BROWN.BLP:20|t두꺼비 떼가|cFFFF0000|Hspell:269688|h [비처럼]|h|r 쏟아져 내립니다!', '|TInterface\\Icons\\INV_PET_TOAD_BROWN.BLP:20|t두꺼비 떼가|cFFFF0000|Hspell:269688|h [비처럼]|h|r 쏟아져 내립니다!', 28153),
(161013, 'koKR', '', '있잖아요, 볼수록 귀엽게 생기신 것 같은데...', 28153),
(161012, 'koKR', '', '제게 필요한 게 있으시면 말씀만 하세요!', 28153),
(161011, 'koKR', '', '전투에서 누군가 쓰러지면, 남은 자들은 힘을 얻어 더 맹렬히 싸우는 법이지요.', 28153),
(161010, 'koKR', '', '밀리를 구해주셔서 어떻게 감사드려야 할지 모르겠네요.', 28153),
(161009, 'koKR', '', '안녕하세요, $p 님. 볼 때마다 반가워요.', 28153),
(161008, 'koKR', '', '하핫! 잡았다!', 28153),
(161007, 'koKR', '', '우리가 다시 만날 날을 위해 훈련하고 준비하겠습니다.', 28153),
(161006, 'koKR', '', '졌다고 너무 낙심하지 마십시오. 실수를 교훈으로 삼아 또다시 도전하면 됩니다.', 28153),
(161005, 'koKR', '', '힘 좀 쓰는 사람이 나타나 도와줄 때가 되었는데 말이죠!', 28153),
(161004, 'koKR', '', '이방인님, 명예롭게 싸웁시다.', 28153),
(161003, 'koKR', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|t근처에 마력 조각이 형성됩니다. 마력 조각을 사용하여 화신에게 |cFFFF0000|Hspell:274149|h[생명의 힘]|h|r을 부여하세요!', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|t근처에 마력 조각이 형성됩니다. 마력 조각을 사용하여 화신에게 |cFFFF0000|Hspell:274149|h[생명의 힘]|h|r을 부여하세요!', 28153),
(161002, 'koKR', '<겐이 캐서린과 이야기할 수 있는 시간을 줍니다.>', '<겐이 캐서린과 이야기할 수 있는 시간을 줍니다.>', 28153),
(161001, 'koKR', '지금이 기회입니다!', '지금이 기회입니다!', 28153),
(161000, 'koKR', '짐들 챙기세요, 서둘러요!', '짐들 챙기세요, 서둘러요!', 28153),
(160999, 'koKR', '갑시다!', '갑시다!', 28153),
(160998, 'koKR', '어서요! 이곳에서 벗어나요!', '어서요! 이곳에서 벗어나요!', 28153),
(160997, 'koKR', '세스랄리스의 심장을 보호하기 위해 근처에 수호자가 생성됩니다.', '세스랄리스의 심장을 보호하기 위해 근처에 수호자가 생성됩니다.', 28153),
(160996, 'koKR', '자크라제트의 추종자들이 세스랄리스의 심장으로 달려듭니다.', '자크라제트의 추종자들이 세스랄리스의 심장으로 달려듭니다.', 28153),
(160995, 'koKR', '야생에는 곰, 늑대뿐 아니라 무는 게 특기인 염소도 삽니다!', '', 28153),
(160994, 'koKR', '좋은 분 같지만 거리를 유지해 주시길 부탁드립니다.', '', 28153),
(160993, 'koKR', '동물을 다치게 하고 싶진 않습니다만, 경고는 해야겠는걸요.', '', 28153),
(160992, 'koKR', '조심하시는 게 좋을 겁니다. 전 그래서 항상 불을 준비하죠.', '', 28153),
(160991, 'koKR', '밖으로 나와 자연과 함께하는 게 얼마나 기분 좋은 일인지 아십니까?', '', 28153),
(160990, 'koKR', '여기에 서 있는 건 소나무입니다. 겉모습만 보고도 소나무인지 아닌지 알 수 있죠.', '', 28153),
(160989, 'koKR', '폭포를 왜 폭포라고 하는지 아십니까? 물이 떨어져서 그렇다고 하더군요!', '', 28153),
(160988, 'koKR', '폭포는 장관 그 자체죠...', '', 28153),
(160987, 'koKR', '여기 보이는 게 폭포라는 겁니다.', '', 28153),
(160986, 'koKR', '얼마나 좋습니까?', '', 28153),
(160985, 'koKR', '이야, 정말 멋지군요!', '', 28153),
(160984, 'koKR', '이렇듯 야수의 제왕께서는 추종자들에게 용기와 신념의 미덕을 심어 주셨습니다.', '이렇듯 야수의 제왕께서는 추종자들에게 용기와 신념의 미덕을 심어 주셨습니다.', 28153),
(160983, 'koKR', '능력의 근원은 물리적인 힘이 아니라 세월에도 스러지지 않는 불굴의 의지 이니라.', '능력의 근원은 물리적인 힘이 아니라 세월에도 스러지지 않는 불굴의 의지 이니라.', 28153),
(160982, 'koKR', '밀림의 꽃송이가 썩어 문드러지듯 세월은 젊음의 힘을 노쇠하게 하지.', '밀림의 꽃송이가 썩어 문드러지듯 세월은 젊음의 힘을 노쇠하게 하지.', 28153),
(160981, 'koKR', '어떤 일에든 용기를 가지고 행동하면 사냥감을 놓치지 않을 것이다.', '어떤 일에든 용기를 가지고 행동하면 사냥감을 놓치지 않을 것이다.', 28153),
(160980, 'koKR', '사냥하는 호랑이가 바위와 협곡을 건너뛰듯, 용감한 이는 공포 앞에서 떠느라 시간을 지체하지 않는다.', '사냥하는 호랑이가 바위와 협곡을 건너뛰듯, 용감한 이는 공포 앞에서 떠느라 시간을 지체하지 않는다.', 28153),
(160979, 'koKR', '저의 로아께서 하신 말씀을 전해 드리겠습니다. 그분은 추종자들에게 이렇게 말씀하셨습니다.', '저의 로아께서 하신 말씀을 전해 드리겠습니다. 그분은 추종자들에게 이렇게 말씀하셨습니다.', 28153),
(160978, 'koKR', '이렇듯 고양이의 왕께서는 추종자들에게 헌신의 미덕을 심어 주셨습니다.', '이렇듯 고양이의 왕께서는 추종자들에게 헌신의 미덕을 심어 주셨습니다.', 28153),
(160977, 'koKR', '불굴의 의지를 지니고 살아간다면 실패에도 쓰러지지 않을 것이다.', '불굴의 의지를 지니고 살아간다면 실패에도 쓰러지지 않을 것이다.', 28153),
(160976, 'koKR', '협곡이 오랜 시간 물줄기에 깎이듯 모든 위대한 업적 또한 끈기에서 비롯된다.', '협곡이 오랜 시간 물줄기에 깎이듯 모든 위대한 업적 또한 끈기에서 비롯된다.', 28153),
(160975, 'koKR', '영예로운 삶을 살아라. 그것이 훌륭한 삶으로 이어진다.', '영예로운 삶을 살아라. 그것이 훌륭한 삶으로 이어진다.', 28153),
(160974, 'koKR', '왕이 그에게 가장 귀중한 보물을 티끌만큼이라도 내주기 싫어하듯 존경받는 자는 자신의 진실함을 부나 명예와 바꾸지 않는다.', '왕이 그에게 가장 귀중한 보물을 티끌만큼이라도 내주기 싫어하듯 존경받는 자는 자신의 진실함을 부나 명예와 바꾸지 않는다.', 28153),
(160973, 'koKR', '저의 로아께서 하신 말씀을 전해 드리겠습니다. 그분은 추종자들에게 이렇게 말씀하셨습니다.', '저의 로아께서 하신 말씀을 전해 드리겠습니다. 그분은 추종자들에게 이렇게 말씀하셨습니다.', 28153),
(160972, 'koKR', '이렇듯 사냥감을 파멸로 이끄시는 분께서는 추종자들에게 인내와 존중이라는 미덕을 심어 주셨습니다.', '이렇듯 사냥감을 파멸로 이끄시는 분께서는 추종자들에게 인내와 존중이라는 미덕을 심어 주셨습니다.', 28153),
(160971, 'koKR', '그들은 자연의 섭리를 존중하며 꼭 필요한 만큼만 가져간다.', '그들은 자연의 섭리를 존중하며 꼭 필요한 만큼만 가져간다.', 28153),
(160970, 'koKR', '통찰력을 가진 자들은 자연이 그들의 것이 아니라, 그들이 자연의 것이라는 사실을 안다.', '통찰력을 가진 자들은 자연이 그들의 것이 아니라, 그들이 자연의 것이라는 사실을 안다.', 28153),
(160969, 'koKR', '밀림은 삶이라는 축복을 내리지만, 죽음의 손길 또한 뻗는다.', '밀림은 삶이라는 축복을 내리지만, 죽음의 손길 또한 뻗는다.', 28153),
(160968, 'koKR', '어리석은 자들은 욕망과 감정에 이끌려 삶을 살아가고 밀림에서 오래 살아남지 못한다.', '어리석은 자들은 욕망과 감정에 이끌려 삶을 살아가고 밀림에서 오래 살아남지 못한다.', 28153),
(160967, 'koKR', '때때로 며칠 동안이나 한 사냥감을 쫓는 재규어처럼, 지혜로운 자들은 어떤 상황에서든 인내한다.', '때때로 며칠 동안이나 한 사냥감을 쫓는 재규어처럼, 지혜로운 자들은 어떤 상황에서든 인내한다.', 28153),
(160966, 'koKR', '살아남는 것뿐만 아니라, 번창하십시오! 감히 말씀드리건대, 하십시오! 시궁창에서 살지라도 고개를 높이 드십시오. 그곳이 바로 자니 님의 영역이니까요.', '살아남는 것뿐만 아니라, 번창하십시오! 감히 말씀드리건대, 하십시오! 시궁창에서 살지라도 고개를 높이 드십시오. 그곳이 바로 자니 님의 영역이니까요.', 28153),
(160965, 'koKR', '자니 님께서는 화려한 말이나 거창한 희생을 요구하지 않으십니다. 자니 님을 찬양하는 것은 억압하는 이들의 코앞에서 살아남기 위함입니다.', '자니 님께서는 화려한 말이나 거창한 희생을 요구하지 않으십니다. 자니 님을 찬양하는 것은 억압하는 이들의 코앞에서 살아남기 위함입니다.', 28153),
(160964, 'koKR', '다른 로아께서는 가져가시지만, 자니 님께서는 베푸십니다! 그분께서는 스스로 살아가는 모든 자에게 베푸십니다. 위대한 자, 부유한 자는 버리십니다.', '다른 로아께서는 가져가시지만, 자니 님께서는 베푸십니다! 그분께서는 스스로 살아가는 모든 자에게 베푸십니다. 위대한 자, 부유한 자는 버리십니다.', 28153),
(160963, 'koKR', '자니 님께서는 다른 로아보다 위대하십니다. 그 이유를 알려드리지요!', '자니 님께서는 다른 로아보다 위대하십니다. 그 이유를 알려드리지요!', 28153),
(160962, 'koKR', '그들은 백성의 찬양에 목말라 손을 뻗습니다.', '그들은 백성의 찬양에 목말라 손을 뻗습니다.', 28153),
(160961, 'koKR', '트로스가... 집어삼킨다...', '', 28153),
(160960, 'koKR', '못 도망간다...', '', 28153),
(160959, 'koKR', '희망은 없다...', '', 28153),
(160958, 'koKR', '가죽을 벗겨 주마!', '', 28153),
(160957, 'koKR', '고통에 몸부림쳐라!', '', 28153),
(160956, 'koKR', '당신네 부유한 로아의 얼굴에 침을 뱉어 주마!', '당신네 부유한 로아의 얼굴에 침을 뱉어 주마!', 28153),
(160955, 'koKR', '고통을 느껴라!', '', 28153),
(160954, 'koKR', '흩어져!', '흩어져!', 28153),
(160953, 'koKR', '자니 님은 나의 로아! 아하하!', '자니 님은 나의 로아! 아하하!', 28153),
(160952, 'koKR', '자니 님이 우릴 부자로 만들어 주신다!', '자니 님이 우릴 부자로 만들어 주신다!', 28153),
(160951, 'koKR', '이 흥청망청 멍청한 짓을 멈춰라! 꺼져!', '이 흥청망청 멍청한 짓을 멈춰라! 꺼져!', 28153),
(160950, 'koKR', '이건 지금 우릴 모욕하는 처사다! 사라져라!', '이건 지금 우릴 모욕하는 처사다! 사라져라!', 28153),
(160949, 'koKR', '진짜 로아를 욕되게 하지 마라! 이 쓰레기를 당장 치우지 못해!', '진짜 로아를 욕되게 하지 마라! 이 쓰레기를 당장 치우지 못해!', 28153),
(160948, 'koKR', '쓸모없는 자니가 또 난장판을 만드는군! 훠이! 훠이!', '쓸모없는 자니가 또 난장판을 만드는군! 훠이! 훠이!', 28153),
(160947, 'koKR', '그럴 리가 없습니다. 제 로아의 축복을 받으십시오!', '그럴 리가 없습니다. 제 로아의 축복을 받으십시오!', 28153),
(160946, 'koKR', '제가 조금 늦었나 보군요...', '제가 조금 늦었나 보군요...', 28153),
(160945, 'koKR', '그 헌신적인 모습을 보니 눈물이 나는군요. 로아의 자비로움을 느끼셨습니까?', '그 헌신적인 모습을 보니 눈물이 나는군요. 로아의 자비로움을 느끼셨습니까?', 28153),
(160944, 'koKR', '의식이 곧 시작됩니다, $n 님.\n\n각양각색의 삶을 사는 백성이 잔달라 곳곳에서 로아의 지혜로운 말씀을 듣기 위해 모였습니다. 많은 이가 로아께서 축복을 내려주실 것이라고 기대하고 있습니다. 어쩌면 당신에게도 축복을 내려주실지 모르죠!\n\n이곳에서 잔달라의 백성과 함께 로아를 찬양하십시오.', '의식이 곧 시작됩니다, $n 님.\n\n각양각색의 삶을 사는 백성이 잔달라 곳곳에서 로아의 지혜로운 말씀을 듣기 위해 모였습니다. 많은 이가 로아께서 축복을 내려주실 것이라고 기대하고 있습니다. 어쩌면 당신에게도 축복을 내려주실지 모르죠!\n\n이곳에서 잔달라의 백성과 함께 로아를 찬양하십시오.', 28153),
(160943, 'koKR', '넌 죽기를... 바라게 될 것이다...', '', 28153),
(160942, 'koKR', '네 고통은 끝나지 않는다!', '', 28153),
(160941, 'koKR', '복수는... 반드시... 이루어질 것이다...', '', 28153),
(160940, 'koKR', '이 아이는 고라크 툴 님의 것이다!', '', 28153),
(160939, 'koKR', '이 아인 절대 못 데려간다!', '', 28153),
(160938, 'koKR', '넌 그날 언더시티에 있었지. 놈들은 밀리고 있었다! 정의가 내 손 안에 있었지!', '', 28153),
(160937, 'koKR', '이봐요, $G형제:자매; 님, 목이 말라 보이는데, 맥주 한 잔 드려요?', '', 28153),
(160936, 'koKR', '최상품 스톰송 꿀을 가지고 새로운 술을 만들기 시작했습니다.\n\n재료 사는 데 큰돈을 쓰긴 했지만 가치 있는 투자였다고 확신합니다!', '', 28153),
(160935, 'koKR', '', '한 잔 드릴까요? 정신 차리게 해줄 음료가 필요하다면 커피도 준비되어있으니 말씀만 하세요.', 28153),
(160934, 'koKR', '난 부자가 될 거야! 우후!', '난 부자가 될 거야! 우후!', 28153),
(160933, 'koKR', '너희 로아는 여기선 사절이다! 꺼져라!', '너희 로아는 여기선 사절이다! 꺼져라!', 28153),
(160932, 'koKR', '쓰레기의 신께서 은총을 내리시길! 하하하!', '쓰레기의 신께서 은총을 내리시길! 하하하!', 28153),
(160931, 'koKR', '다른 이는 그들의 로아께서 가장 자비롭거나, 강력하거나, 성미가 급하시다고 말할 겁니다.', '다른 이는 그들의 로아께서 가장 자비롭거나, 강력하거나, 성미가 급하시다고 말할 겁니다.', 28153),
(160930, 'koKR', '하하하! 모든 이의 로아께 찬양을 올립시다! 다자알로의 계단에 모여 자니 님을 찬양합시다!', '하하하! 모든 이의 로아께 찬양을 올립시다! 다자알로의 계단에 모여 자니 님을 찬양합시다!', 28153),
(160929, 'koKR', '일정대로라면 배는 메아리 섬을 떠나 곧 여기에 도착할 겁니다.', '', 28153),
(160928, 'koKR', '잔달라의 백성이여! 바람의 군주, 하늘의 여왕, 바다의 수호자를 찬양할 때가 왔습니다! 계단에 모여 파쿠 님을 찬미합시다!', '잔달라의 백성이여! 바람의 군주, 하늘의 여왕, 바다의 수호자를 찬양할 때가 왔습니다! 계단에 모여 파쿠 님을 찬미합시다!', 28153),
(160927, 'koKR', '제 앞에 계신 모든 분께서 저의 로아이신 파쿠 님의 축복을 느끼셨을 겁니다.', '제 앞에 계신 모든 분께서 저의 로아이신 파쿠 님의 축복을 느끼셨을 겁니다.', 28153),
(160926, 'koKR', '파쿠 님을 찬양하십시오! 그분의 바람이 당신의 항해에 가득하기를!', '파쿠 님을 찬양하십시오! 그분의 바람이 당신의 항해에 가득하기를!', 28153),
(160925, 'koKR', '공크 님께서 은총을 내리십니다! 무리가 영원히 당신과 함께하길!', '공크 님께서 은총을 내리십니다! 무리가 영원히 당신과 함께하길!', 28153),
(160924, 'koKR', '환영합니다, 형제자매여. 공크 님께서 함께하신다는 사실을 기억하십시오.', '환영합니다, 형제자매여. 공크 님께서 함께하신다는 사실을 기억하십시오.', 28153),
(160923, 'koKR', '잔달라의 백성이여! 변신의 로아께서 백성의 찬양을 바라십니다. 오셔서 무리의 왕, 가장 자비로운 로아를 소리 높여 찬미하십시오! 공크 님을 찬양하십시오!', '잔달라의 백성이여! 변신의 로아께서 백성의 찬양을 바라십니다. 오셔서 무리의 왕, 가장 자비로운 로아를 소리 높여 찬미하십시오! 공크 님을 찬양하십시오!', 28153),
(160922, 'koKR', '잔달라의 백성이여! 위대한 크라그와 님께서 돌아오셨습니다! 다자알로의 계단에 모여 위대한 수호자께 찬양을 올립시다!', '잔달라의 백성이여! 위대한 크라그와 님께서 돌아오셨습니다! 다자알로의 계단에 모여 위대한 수호자께 찬양을 올립시다!', 28153),
(160921, 'koKR', '많은 분이 말씀하셨지요. 크라그와? 위대하신 두꺼비? 그런 로아는 없어! 꾸며낸 이야기라고!', '많은 분이 말씀하셨지요. 크라그와? 위대하신 두꺼비? 그런 로아는 없어! 꾸며낸 이야기라고!', 28153),
(160920, 'koKR', '위대하신 수호자께서 여러분을 보호하십니다! 크라그와 님을 찬양하십시오!', '위대하신 수호자께서 여러분을 보호하십니다! 크라그와 님을 찬양하십시오!', 28153),
(160919, 'koKR', '브원삼디 님께서는 우리를 지켜보십니다. 형제자매여, 그분의 은혜에 부합하십시오!', '브원삼디 님께서는 우리를 지켜보십니다. 형제자매여, 그분의 은혜에 부합하십시오!', 28153),
(160918, 'koKR', '브원삼디 님에 관해 다들 잘 아시겠지요. 아, 죽음의 로아?라고 생각하실 겁니다.', '브원삼디 님에 관해 다들 잘 아시겠지요. 아, 죽음의 로아?라고 생각하실 겁니다.', 28153),
(160917, 'koKR', '영혼은 우리와 함께합니다! 모두 다자알로의 계단에 모여 죽은 자를 지키시는 그분을 찬양합시다. 브원삼디 님께 감사함을 전하십시오!', '영혼은 우리와 함께합니다! 모두 다자알로의 계단에 모여 죽은 자를 지키시는 그분을 찬양합시다. 브원삼디 님께 감사함을 전하십시오!', 28153),
(160916, 'koKR', '배는 메아리 섬에 있습니다. 곧 출항해서 여기로 돌아올 겁니다.', '', 28153),
(160915, 'koKR', '', '칠판에 써 있는 건 신경 쓰지 마세요. 확실히 정해진 건 없답니다.', 28153),
(160914, 'koKR', '배는 막 떠났습니다. 지금 메아리 섬으로 가고 있지만 곧 여기로 돌아올 겁니다.', '', 28153),
(160913, 'koKR', '잔달라의 백성이여! 함께 다자알로의 계단에 모여 고양이의 왕, 야수의 제왕, 사냥감을 파멸로 이끄시는 분의 지혜로운 말씀을 들읍시다. 킴불 님을 찬양합시다!', '잔달라의 백성이여! 함께 다자알로의 계단에 모여 고양이의 왕, 야수의 제왕, 사냥감을 파멸로 이끄시는 분의 지혜로운 말씀을 들읍시다. 킴불 님을 찬양합시다!', 28153),
(160912, 'koKR', '저의 로아께서 하신 말씀을 전해 드리겠습니다. 그분은 추종자들에게 이렇게 말씀하셨습니다.', '저의 로아께서 하신 말씀을 전해 드리겠습니다. 그분은 추종자들에게 이렇게 말씀하셨습니다.', 28153),
(160911, 'koKR', '사냥감을 파멸로 이끄시는 분께서 당신의 사냥을 축복합니다! 앞으로 나아가십시오!', '사냥감을 파멸로 이끄시는 분께서 당신의 사냥을 축복합니다! 앞으로 나아가십시오!', 28153),
(160910, 'koKR', '아쿤다 님의 축복을 느끼십시오!', '아쿤다 님의 축복을 느끼십시오!', 28153),
(160909, 'koKR', '아쿤다 님의 지혜를 나누어 드리겠습니다. 아쿤다 님께서는 폭풍과 새로운 시작의 로아이십니다.', '아쿤다 님의 지혜를 나누어 드리겠습니다. 아쿤다 님께서는 폭풍과 새로운 시작의 로아이십니다.', 28153),
(160908, 'koKR', '폭풍이 다가오고 있습니다! 형제자매여, 여러분의 걱정을 비로 씻어내십시오. 다자알로의 계단으로 모여 아쿤다 님을 찬양합시다!', '폭풍이 다가오고 있습니다! 형제자매여, 여러분의 걱정을 비로 씻어내십시오. 다자알로의 계단으로 모여 아쿤다 님을 찬양합시다!', 28153),
(160907, 'koKR', '배는 여기 있습니다, 친구여. 떠나기 전에 어서 타십시오.', '', 28153),
(160906, 'koKR', '진짜 팬이라니, 정말 반갑군요! 절 만나서 지금 제정신이 아니겠지만 걱정하지 말아요. 저도 당신 같은 평범한 모험가일 뿐이니까요. 상을 받은 책의 저자라 돈이 아주 많고 팬들이 제 얼굴 한번 볼 수 있을까 하는 희망으로 바다 건너 찾아온다는 점만 빼면 말이죠.\n\n자, 당신 책을 돌려드리지요. 당신에게는 당연히 가보로 삼을 만한 소중한 선물이겠죠.', '', 28153),
(160905, 'koKR', '새로운 하루의 시작은 새로운 맥주와 함께! 정말 기가 막힌 맥주를 맛본 적이 있습니까?', '', 28153),
(160904, 'koKR', '혹시 죽음의 기사이신가요? 한번 꼭 만나 뵙고 싶었습니다!\n\n언데드로 살아가는 건 어떤가요? 죽음의 기사가 되고 싶어서 되신 건가요? 전 되고 싶은데, 어떻게 하면 되죠?', '', 28153),
(160903, 'koKR', '제 책에 사인 좀 해주실래요?', '제 책에 사인 좀 해주실래요?', 28153),
(160902, 'koKR', '최근 완성한 작품은 말 그대로 걸작입니다. 독자를 현혹하고 황홀하게 할 문학의 보석이자 심연에서 끌어낸 명약이라 할 수 있죠. 절 찬양하러 오신 겁니까?', '', 28153),
(160901, 'koKR', '솔직히 말하자면 당장은 확신이 서지 않습니다. 얼라이언스 놈들에게 당하지 않았기를 바라는 수밖에요.', '', 28153),
(160900, 'koKR', '미스락스를 오래 잡아두고 있지는 못할 거다. 시간이 있을 때 줄을 처치해라.', '', 28153),
(160899, 'koKR', '절 구해 주셨군요! 정말 고맙습니다! 이 가방 속 어딘가에 보답으로 드릴 물건이 있어요.', '', 28153),
(160898, 'koKR', '도시를 맡거라, 영웅이여. 나는 사악한 세스락 놈들에게서 북쪽 길을 지키겠다.', '', 28153),
(160897, 'koKR', '', '줄다자르의 거리가 적으로 들끓는 모습을 보게 되는 날이 올 줄은 꿈에도 몰랐습니다...', 28153),
(160896, 'koKR', '', '방어병들은 도대체 어디에 있습니까? 줄이 배신했다고 줄다자르가 스스로를 방어하지 못할 정도로 약해진 겁니까?\n\n미라가 어서 이곳으로 달려와 왕실근위병들에게 알리라고 했건만, 몇 명 남아 있지도 않군요. 우리끼리 이곳을 지킬 수밖에 없겠습니다.', 28153),
(160895, 'koKR', '', '세스락 놈들보다 먼저 이곳에 도착하기 위해 우리가 어떤 길을 택했는지 알면 놀랄 거예요. 제 도움이 없었다면 당신 친구들은 제시간에 산을 넘지 못했을걸요.\n\n참, 아쿤다 님과 킴불 님을 모셔왔어요. 아쿤다 님은 저희 뒤를 봐주고 계시고, 킴불 님은 지금 어디 계시는지 모르겠지만 \"적을 찢어발긴다\" 어쩌고 하시던데요.\n\n제가 아는 거라곤 이곳으로 오는 세스락들이 엄청나게 많다는 거예요. 정말 엄청나게요!', 28153),
(160894, 'koKR', '이 지역의 호드 움직임에 대해 말해 주시겠습니까?', '이 지역의 호드 움직임에 대해 말해 주시겠습니까?', 28153),
(160893, 'koKR', '그냥 그렇게 죽는 줄 알았습니다. 감사합니다, $r 친구여. 사람들이 당신네 종족을 아직 $r|1이라고;라고; 부르는 거 맞죠?', '그냥 그렇게 죽는 줄 알았습니다. 감사합니다, $r 친구여. 사람들이 당신네 종족을 아직 $r|1이라고;라고; 부르는 거 맞죠?', 28153),
(160892, 'koKR', '', '당신 마치 커다란 물통 같아요! 아니, 맥주통인가?', 28153),
(160891, 'koKR', '어떤 맥주가 있는지 보여 주세요.', '어떤 맥주가 있는지 보여 주세요.', 28153),
(160890, 'koKR', '', '맥주 좀 소개해 드려도 될까요? 종류가 워낙 많아 어떤 입맛이든 만족시켜 드릴 수 있을 거예요.', 28153),
(160889, 'koKR', '와, 눈 깜짝할 사이에 끝내셨군요. 원하신다면 당신 부대에 새로운 방어구를 지원해 드릴게요. 당연히 공짜로 말이죠!', '', 28153),
(160888, 'koKR', '', '날카로운 사격을 사용하면 야수의 격노를 다시 발동할 수 있는 시간이 단축됩니다.', 28153),
(160887, 'koKR', '최대한 빨리 썰고 있어!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160886, 'koKR', '', '콜튼, 빨리 썰어! 손님들이 기다린단 말이야!', 28153),
(160885, 'koKR', '날카로운 사격을 사용하면 야수의 격노를 다시 발동할 수 있는 시간이 단축됩니다.', '', 28153),
(160884, 'koKR', '어서 가자, 얘야!', '', 28153),
(160883, 'koKR', '준비되셨습니까?', '', 28153),
(160882, 'koKR', '노는 시간이니, 루나?', '', 28153),
(160881, 'koKR', '이렇게 훌륭한 아내를 두었다니 저는 정말 운 좋은 놈입니다.', '', 28153),
(160880, 'koKR', '', '깜짝 선물이 있습니다!', 28153),
(160879, 'koKR', '', '정말 멋져요. 보셨나요?', 28153),
(160878, 'koKR', '글쎄. 모르겠습니다. 좋은 여자를 만나게 되면 어딘가 작은 농장에서 터전이라도 마련하려나...\n\n제가 정말 그럴 거로 생각하십니까?\n\n사이러스 님에게 돈을 받으면 아늑한 항구 여관의 모든 이에게 한잔 돌린 후 또 다른 모험을 찾아봐야지요.\n\n그게 제 유일한 삶의 방식입니다.', '', 28153),
(160877, 'koKR', '당신은 어떻게 할 겁니까?', '당신은 어떻게 할 겁니까?', 28153),
(160876, 'koKR', '침략에, 반란, 고대 신의 부활이라니, 이런! 저는 늙은 텔라가 빚을 갚기 전까지는 조칼로를 떠나지 않을 겁니다.', '', 28153),
(160875, 'koKR', '이 정도는 아무것도 아닙니다. 3차 대전쟁 당시 저는 뿌릿길에서 엄청난 뼈들이 춤추는 것도 보았지요. 생전 그렇게 무서우면서도 흥분되는 광경은 처음 봤어요.', '', 28153),
(160874, 'koKR', '맹세하건대, 여기서 살아남게 된다면 한 2주... 아니 3주는 고객에게 사기를 치지 않겠습니다.', '', 28153),
(160873, 'koKR', '배는 지금 어디 있죠?', '배는 지금 어디 있죠?', 28153),
(160872, 'koKR', '', '무슨 수를 써서든 그대를 최대한 도울게요, $n 님.', 28153),
(160871, 'koKR', '', '전 스컬지가 줄드락을 덮쳤을 당시, 맞서 일어났습니다... 그런데 이번엔 친구라고 생각했던 자들이 제 고향 땅을 공격하고 있군요...\n\n저는 폭력적인 트롤은 아니지만, 이런 상황에서는 손에 피를 묻히는 것도 마다하지 않겠습니다.', 28153),
(160870, 'koKR', '말퓨리온 님이 어둠해안에서 지원을 요청합니다, 대드루이드님!', '말퓨리온 님이 어둠해안에서 지원을 요청합니다, 대드루이드님!', 28153),
(160869, 'koKR', '여사제님, 성난굽이 강에서 호드를 막아야 합니다. 도와주십시오.', '여사제님, 성난굽이 강에서 호드를 막아야 합니다. 도와주십시오.', 28153),
(160868, 'koKR', '공주님을 도우시는군요. 좋은 일입니다. 계속 도와 주십시오. 혈트롤이 우리 모두를 집어삼키기 전에 놈들의 위협을 격파해야 합니다.\n\n당신이 찾는 자는 줄잔 폐허에 있습니다. 그녀의 이름은 배급원 리자. 그녀가 당신을 도와줄 겁니다.', '공주님을 도우시는군요. 좋은 일입니다. 계속 도와 주십시오. 혈트롤이 우리 모두를 집어삼키기 전에 놈들의 위협을 격파해야 합니다.\n\n당신이 찾는 자는 줄잔 폐허에 있습니다. 그녀의 이름은 배급원 리자. 그녀가 당신을 도와줄 겁니다.', 28153),
(160867, 'koKR', '자네가 무슨 일을 해서든 잔달라와 그 함대가 호드에 합류하도록 하는 것이 대족장님을 위한 길일세. 그러려면 탈란지 공주를 계속해서 지원해야 하네. 그 지원이라는 것이 혈트롤을 남김없이 없애야 하는 일이라면 그렇게 하게나.\n\n나즈미르에 있는 줄잔 폐허에 가면 호드 사절을 찾을 수 있을 걸세. 리자라는 배급원을 찾게. 어둠의 여왕이 자네를 보살피시길.', '자네가 무슨 일을 해서든 잔달라와 그 함대가 호드에 합류하도록 하는 것이 대족장님을 위한 길일세. 그러려면 탈란지 공주를 계속해서 지원해야 하네. 그 지원이라는 것이 혈트롤을 남김없이 없애야 하는 일이라면 그렇게 하게나.\n\n나즈미르에 있는 줄잔 폐허에 가면 호드 사절을 찾을 수 있을 걸세. 리자라는 배급원을 찾게. 어둠의 여왕이 자네를 보살피시길.', 28153),
(160866, 'koKR', '탈란지의 원정대 사절', '탈란지의 원정대 사절', 28153),
(160865, 'koKR', '쿨 티란 주민들이 마시는 맥주는 참 신기해요!\n\n본토에서 파는 것보다 훨씬 풍미가 깊어요. 자기들의 기술을 제대로 활용할 줄 아는 것 같아요!', '', 28153),
(160864, 'koKR', '탈란지 공주와 전쟁경비병 라케라에게 가세요.', '탈란지 공주와 전쟁경비병 라케라에게 가세요.', 28153),
(160863, 'koKR', '', '피의 이교도, 세스락, 모구, 이제 줄까지? 세계 정복을 꿈꾸던 평온한 날들이 그립군요.', 28153),
(160862, 'koKR', '', '군단과의 기나긴 전쟁은 끝났지만, 호드에게는 단 한 순간도 쉴 틈은 없다.', 28153),
(160861, 'koKR', '군단은 쓰러졌지만, 새로운 위협이 나타났습니다. 오그리마에 있는 요원들이 불길한 소식을 전했습니다. 스톰윈드 왕궁에서 저와 자세히 논의하시죠.', '', 28153),
(160860, 'koKR', '거친 물살에 오신 걸 환영합니다! 귀여운 아드님이나 따님에게 줄 물건을 찾고 계신가요?', '', 28153),
(160859, 'koKR', '', '처음엔 고양이 세 마리였어요. 세 마리요! 그 정도면 많은 것도, 적은 것도 아니잖아요!\n\n어느 날 친구 하나가 멀리 이사하면서 자기가 기르던 고양이를 맡아 달라고 했어요. 또 하루는 길거리에서 슬픈 눈으로 저를 쳐다보는 길고양이를 한 마리 발견했고요. 이웃이 세상을 떠났고, 고양이 한 마리가 새끼를 낳았고, 또 한두 마리가... 어디선가 나타났죠!\n\n저에겐 한 마리 한 마리가 다 소중해요. 세상을 다 준다 해도 제 고양이들과는 안 바꿀 거예요.', 28153),
(160858, 'koKR', '우와! 또야!', '', 28153),
(160857, 'koKR', '이 중에 제 강아지는 없습니다. 아끼던 강아지 윌로비를 수년 전에 잃어버렸죠. 그래서 전 매일 여기 와서 가장 외로워 보이는 녀석을 쓰다듬고 칭찬해 줍니다.', '', 28153),
(160856, 'koKR', '제 개를 위해서라면 전 무엇이든 할 수 있습니다.', '', 28153),
(160855, 'koKR', '얘는 제가 키우는 버켓이라는 개예요. 땅을 기가 막히게 잘 파죠!\n\n버켓에게 좋은 애완동물을 만들어 주려고 신청했어요. 버켓은 그냥 여기 와 있는 것만으로 신난 것 같아요.', '', 28153),
(160854, 'koKR', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t |cFFFF0000|Hspell:266948|h[역병 폭탄]|h|r의 대상 지역에 플레이어가 한 명 이상 서 있어야 합니다!', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t |cFFFF0000|Hspell:266948|h[역병 폭탄]|h|r의 대상 지역에 플레이어가 한 명 이상 서 있어야 합니다!', 28153),
(160853, 'koKR', '|TInterface\\ICONS\\Spell_Priest_Void Blast.blp:20|t |cFFFF0000|Hspell:272146|h[파멸]|h|r이 50번 중첩되었습니다! 정수 파편을 구해 최대 생명력을 되찾으십시오!', '|TInterface\\ICONS\\Spell_Priest_Void Blast.blp:20|t |cFFFF0000|Hspell:272146|h[파멸]|h|r이 50번 중첩되었습니다! 정수 파편을 구해 최대 생명력을 되찾으십시오!', 28153),
(160852, 'koKR', '거인 때문에 도움이 필요하시다고 들었는데요.', '거인 때문에 도움이 필요하시다고 들었는데요.', 28153),
(160851, 'koKR', '얼라이언스를 위하여!', '', 28153),
(160850, 'koKR', '오늘 여러분이 이루어 낸 위대한 업적을 안두인 폐하께 직접 말씀드리겠소. 다들 정말 수고 많았소.', '', 28153),
(160849, 'koKR', '고위 영주 폴스타트와 와일드해머 드워프 모두에게 특별히 공로를 돌리겠소.', '', 28153),
