(158821, 'koKR', '크아! 먹어주마!', '', 28153),
(158820, 'koKR', '물어뜯는다, 네 살덩이 먹는다!', '', 28153),
(158819, 'koKR', '죽어! 크아아!', '', 28153),
(158818, 'koKR', '크르르... 너... 내가 죽인다!', '', 28153),
(158817, 'koKR', '크아아아!', '', 28153),
(158816, 'koKR', '으으으!', '', 28153),
(158815, 'koKR', '야생은 너희보다 훨씬 오래 살았고 앞으로도 너희보다 오래 살아남으리라.', '야생은 너희보다 훨씬 오래 살았고 앞으로도 너희보다 오래 살아남으리라.', 28153),
(158814, 'koKR', '반짝이는 보석은 자연이 우리에게 준 선물이다. 너희 종족에게서 그 선물을 지킬 것이다!', '반짝이는 보석은 자연이 우리에게 준 선물이다. 너희 종족에게서 그 선물을 지킬 것이다!', 28153),
(158813, 'koKR', '오늘 자연의 순환이 너에게 닿았다, 침입자여. 너희 시체로 우리는 성장하리라.', '오늘 자연의 순환이 너에게 닿았다, 침입자여. 너희 시체로 우리는 성장하리라.', 28153),
(158812, 'koKR', '우리의 땅이 더 오염되기 전에 네놈을 제거해주마.', '우리의 땅이 더 오염되기 전에 네놈을 제거해주마.', 28153),
(158811, 'koKR', '너희는 너희가 짓밟은 이 땅의 거름이 되리라.', '너희는 너희가 짓밟은 이 땅의 거름이 되리라.', 28153),
(158810, 'koKR', '너희 종족은 균형을 잃었다. 너희는 버티지 못한다. 내가 개입하겠다.', '너희 종족은 균형을 잃었다. 너희는 버티지 못한다. 내가 개입하겠다.', 28153),
(158809, 'koKR', '네놈을 처치하여 네놈이 무너뜨린 균형을 보전하리라.', '네놈을 처치하여 네놈이 무너뜨린 균형을 보전하리라.', 28153),
(158808, 'koKR', '우리는 이 땅과 야수의 수호자다. 여긴 너희가 있을 곳이 아니다!', '우리는 이 땅과 야수의 수호자다. 여긴 너희가 있을 곳이 아니다!', 28153),
(158807, 'koKR', '너희 종족은... 역병이다...', '너희 종족은... 역병이다...', 28153),
(158806, 'koKR', '너희는 우리 땅을... 더럽혔다...', '너희는 우리 땅을... 더럽혔다...', 28153),
(158805, 'koKR', '자연을... 죽일 수는 없다...', '자연을... 죽일 수는 없다...', 28153),
(158804, 'koKR', '우리는... 다시 자라리...', '우리는... 다시 자라리...', 28153),
(158803, 'koKR', '너희 종족은... 오래가지 못하리라...', '너희 종족은... 오래가지 못하리라...', 28153),
(158802, 'koKR', '내가 이 땅을... 윤택하게 하리라...', '내가 이 땅을... 윤택하게 하리라...', 28153),
(158801, 'koKR', '너희는... 균형을 깨뜨렸다...', '너희는... 균형을 깨뜨렸다...', 28153),
(158800, 'koKR', '자연으로... 돌아간다...', '자연으로... 돌아간다...', 28153),
(158799, 'koKR', '이곳을 수호하는 것이 우리 임무다!', '이곳을 수호하는 것이 우리 임무다!', 28153),
(158798, 'koKR', '반짝이는 보석은 야생에 주어야 할 선물이다!', '반짝이는 보석은 야생에 주어야 할 선물이다!', 28153),
(158797, 'koKR', '균형을 보전하리라!', '균형을 보전하리라!', 28153),
(158796, 'koKR', '네놈은 우리의 터를 오염시키지 못한다!', '네놈은 우리의 터를 오염시키지 못한다!', 28153),
(158795, 'koKR', '자연의 부름에 응답하노라!', '자연의 부름에 응답하노라!', 28153),
(158794, 'koKR', '침입자여, 네놈은 이 땅을 망칠 수 없다!', '침입자여, 네놈은 이 땅을 망칠 수 없다!', 28153),
(158793, 'koKR', '자연은 나의 분노를 인도한다!', '자연은 나의 분노를 인도한다!', 28153),
(158792, 'koKR', '야생을 지킬 것이다!', '야생을 지킬 것이다!', 28153),
(158791, 'koKR', '저는 매일 이곳에 와서 할아버지와 할머니에게 이야기해요. 그분들이 제 말을 들으시는 것 같아요!', '', 28153),
(158790, 'koKR', '크헉...', '크헉...', 28153),
(158789, 'koKR', '여긴... 어디지...?', '여긴... 어디지...?', 28153),
(158788, 'koKR', '으윽... 피가...', '으윽... 피가...', 28153),
(158787, 'koKR', '', '전투에 승리하면, 진짜 할 일이 시작되지요.', 28153),
(158786, 'koKR', '나의 분노가... 빠져나간다...', '나의 분노가... 빠져나간다...', 28153),
(158785, 'koKR', '너... 왜...', '너... 왜...', 28153),
(158784, 'koKR', '도망쳐야...', '도망쳐야...', 28153),
(158783, 'koKR', '이제 더... 분명히 보인다...', '이제 더... 분명히 보인다...', 28153),
(158782, 'koKR', '으윽... 고통스럽다...', '으윽... 고통스럽다...', 28153),
(158781, 'koKR', '크아아!', '크아아!', 28153),
(158780, 'koKR', '분노한다!', '분노한다!', 28153),
(158779, 'koKR', '모르는 낯짝이군...', '모르는 낯짝이군...', 28153),
(158778, 'koKR', '겁에 질렸군...', '겁에 질렸군...', 28153),
(158777, 'koKR', '떠나라... 크르르...', '떠나라... 크르르...', 28153),
(158776, 'koKR', '죽어라...', '죽어라...', 28153),
(158775, 'koKR', '크르르...', '크르르...', 28153),
(158774, 'koKR', '크아아!', '크아아!', 28153),
(158773, 'koKR', '얼마나 컸는지 보세요! 쟤 아빠만큼 커요.', '', 28153),
(158772, 'koKR', '널 저주한다...', '널 저주한다...', 28153),
(158771, 'koKR', '조상님들을... 볼 수 있어...', '조상님들을... 볼 수 있어...', 28153),
(158770, 'koKR', '영혼들이... 날 맞아주리...', '영혼들이... 날 맞아주리...', 28153),
(158769, 'koKR', '명예도 모르는...', '명예도 모르는...', 28153),
(158768, 'koKR', '으윽... 내가 졌군...', '으윽... 내가 졌군...', 28153),
(158767, 'koKR', '우리 모두를... 죽이지는 못해...', '우리 모두를... 죽이지는 못해...', 28153),
(158766, 'koKR', '저편에서... 네게 복수하겠다..', '저편에서... 네게 복수하겠다..', 28153),
(158765, 'koKR', '영혼과 함께하리...', '영혼과 함께하리...', 28153),
(158764, 'koKR', '네 뼈로 주술을 만들어 네 가족에게 저주를 걸어주마!', '네 뼈로 주술을 만들어 네 가족에게 저주를 걸어주마!', 28153),
(158763, 'koKR', '넌 더러운 외부인일 뿐이다. 여긴 네가 있을 곳이 아니야!', '넌 더러운 외부인일 뿐이다. 여긴 네가 있을 곳이 아니야!', 28153),
(158762, 'koKR', '', '우리 아이도 이 아이 만할 때가 있었지요. 그때가 엊그제 같은데 이렇게 컸답니다!', 28153),
(158761, 'koKR', '넌 누구지? 넌 여기 있으면 안 돼, 알겠나?', '넌 누구지? 넌 여기 있으면 안 돼, 알겠나?', 28153),
(158760, 'koKR', '어디 실력 좀 볼까...', '어디 실력 좀 볼까...', 28153),
(158759, 'koKR', '이제 보석은 우리 것이다. 우리 부족은 최강이다!', '이제 보석은 우리 것이다. 우리 부족은 최강이다!', 28153),
(158758, 'koKR', '날 쉽게 찾을 수는 없을 거다, 헤.', '날 쉽게 찾을 수는 없을 거다, 헤.', 28153),
(158757, 'koKR', '내 섬이고 내 보석이다. 네놈이 찾을 것은 죽음밖에 없다.', '내 섬이고 내 보석이다. 네놈이 찾을 것은 죽음밖에 없다.', 28153),
(158756, 'koKR', '이곳은 우리가 찾은 곳이다, 침입자. 네가 빼앗을 수 없다.', '이곳은 우리가 찾은 곳이다, 침입자. 네가 빼앗을 수 없다.', 28153),
(158755, 'koKR', '이 섬은 우리 것이다!', '이 섬은 우리 것이다!', 28153),
(158754, 'koKR', '이 섬에서 무얼 하는 거냐?', '이 섬에서 무얼 하는 거냐?', 28153),
(158753, 'koKR', '공격받고 있다! 이쪽이야!', '공격받고 있다! 이쪽이야!', 28153),
(158752, 'koKR', '서둘러 놈들을 처치해라!', '서둘러 놈들을 처치해라!', 28153),
(158751, 'koKR', '널 먹어치우는 내 모습을 보게 될 것이다!', '널 먹어치우는 내 모습을 보게 될 것이다!', 28153),
(158750, 'koKR', '산채로 가죽을 벗겨주마!', '산채로 가죽을 벗겨주마!', 28153),
(158749, 'koKR', '네 뼈로 목걸이를 만들겠다!', '네 뼈로 목걸이를 만들겠다!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158748, 'koKR', '네 피를 마셔주마!', '네 피를 마셔주마!', 28153),
(158747, 'koKR', '크아악! 명예롭게 죽는다!', '', 28153),
(158746, 'koKR', '너는... 이곳의 침입자다... 우린 아무 짓도 하지 않았어...', '', 28153),
(158745, 'koKR', '보석은... 우릴 구할 수 없어...', '', 28153),
(158744, 'koKR', '더 많은 병력으로... 돌아올 것이다...', '', 28153),
(158743, 'koKR', '별들이... 펼쳐져 있다...', '', 28153),
(158742, 'koKR', '조상님의 부름이... 들린다...', '', 28153),
(158741, 'koKR', '영혼들이 나를 환영한다...', '', 28153),
(158740, 'koKR', '조상님께... 간다...', '', 28153),
(158739, 'koKR', '별들이 내 주먹을 인도한다. 미래는 네놈의 피로 쓰일 것이다!', '', 28153),
(158738, 'koKR', '바람이 말해줬다. 오늘 네가 쓰러진다고.', '', 28153),
(158737, 'koKR', '정령들이여, 저 꺼지지 않는 화염의 힘을 주소서!', '', 28153),
(158736, 'koKR', '이길 수 없는 싸움을 시작했구나, 나약한 놈!', '', 28153),
(158735, 'koKR', '이 섬의 부는 우리 것이다, 얼간이들.', '', 28153),
(158734, 'koKR', '선조들께서 내게 힘과 지혜를 주신다!', '', 28153),
(158733, 'koKR', '어리석은 놈, 네 피로 내 뿔을 적시리라!', '', 28153),
(158732, 'koKR', '내 부족을 지킬 것이다!', '', 28153),
(158731, 'koKR', '전사들이여, 나를 도와라!', '', 28153),
(158730, 'koKR', '집결하라! 공격받고 있다!', '', 28153),
(158729, 'koKR', '이 섬은 우리 것이다. 네놈은 권리가 없다!', '', 28153),
(158728, 'koKR', '반짝이는 보석은 우리 것이다. 네놈에게는 승산이 없다!', '', 28153),
(158727, 'koKR', '침입자다. 이곳은 절대 빼앗기지 않는다!', '', 28153),
(158726, 'koKR', '침입자다! 놈들을 처치하라!', '', 28153),
(158725, 'koKR', '영혼들이 내 무기를 인도한다!', '', 28153),
(158724, 'koKR', '선조들을 위하여!', '', 28153),
(158723, 'koKR', '그거... 아프다...', '', 28153),
(158722, 'koKR', '너 여기... 왜 왔어...?', '', 28153),
(158721, 'koKR', '아악! 배에 바로...', '', 28153),
(158720, 'koKR', '너... 도둑...', '', 28153),
(158719, 'koKR', '안 돼! 내 보석...', '', 28153),
(158718, 'koKR', '무슨... 짓을?', '', 28153),
(158717, 'koKR', '우욱... 마음에 안 들어...', '', 28153),
(158716, 'koKR', '벌써 왜 어둡지?', '', 28153),
(158715, 'koKR', '', '거래는 거래일 뿐이라고 하는 사람들이 있습니다. 공허한 거래와 가식이라고. 오늘의 보상은 알 수 없는 미래와 교환했습니다.\n\n하지만 명심하십시오. 브원삼디 님께서는 결국 모든 빚을 받아낸다는 사실을요.', 28153),
(158714, 'koKR', '오우거들아, 박살 내라!', '', 28153),
(158713, 'koKR', '안 돼! 내 보석! 네 거 아냐! 나 보석 필요해!', '', 28153),
(158712, 'koKR', '보석 우리에게 힘 준다, 침입자. 너보다 강한 힘!', '', 28153),
(158711, 'koKR', '나 너 해치우고 네 머리 가져간다!', '', 28153),
(158710, 'koKR', '보석 지켜! 놈들 뼈 부숴!', '', 28153),
(158709, 'koKR', '콩알만 한 놈. 여긴 내 섬이다, 내 거야!', '', 28153),
(158708, 'koKR', '나 너 박살 내고 피 마신다!', '', 28153),
(158707, 'koKR', '나 너 부순다! 크라아악!', '', 28153),
(158706, 'koKR', '이건 내 보석이다! 크라악!', '', 28153),
(158705, 'koKR', '우리 물건 못 가져간다!', '', 28153),
(158704, 'koKR', '저들을 잡아라!', '', 28153),
(158703, 'koKR', '너 보석 못 가져간다!', '', 28153),
(158702, 'koKR', '여기는 내 섬이다! 너 당장 나가라!', '', 28153),
(158701, 'koKR', '침입자를 처치해!', '', 28153),
(158700, 'koKR', '박살 낸다, 뭉갠다, 해치운다!', '', 28153),
(158699, 'koKR', '너 부숴뜨린다!', '', 28153),
(158698, 'koKR', '지난번과 달리... 이번엔 더 나은 삶을 살겠다고만 약속하면 혹시!', '지난번과 달리... 이번엔 더 나은 삶을 살겠다고만 약속하면 혹시!', 28153),
(158697, 'koKR', '브원삼디 님께서 제게 무엇을 원하는지 아십니까?', '브원삼디 님께서 제게 무엇을 원하는지 아십니까?', 28153),
(158696, 'koKR', '전 어떻게 해야 합니까... 어떻게... 분명히 여기서 나갈 방법이 있을 겁니다!', '전 어떻게 해야 합니까... 어떻게... 분명히 여기서 나갈 방법이 있을 겁니다!', 28153),
(158695, 'koKR', '브원삼디 님과 거래하면 모든 것이 평소대로 돌아간다 이겁니까?', '브원삼디 님과 거래하면 모든 것이 평소대로 돌아간다 이겁니까?', 28153),
(158694, 'koKR', '난 이게 싫다! 모든 걸 증오한다!', '난 이게 싫다! 모든 걸 증오한다!', 28153),
(158693, 'koKR', '참을 수 없는 일이군! 저들은 내가 누군지 모른다는 말인가?', '참을 수 없는 일이군! 저들은 내가 누군지 모른다는 말인가?', 28153),
(158692, 'koKR', '내게 이런 짓을 한 놈을 잡고야 말겠다! 그게 내 마지막 일이 되더라도!', '내게 이런 짓을 한 놈을 잡고야 말겠다! 그게 내 마지막 일이 되더라도!', 28153),
(158691, 'koKR', '어떻게 이런 일이? 공정하지 않아!', '어떻게 이런 일이? 공정하지 않아!', 28153),
(158690, 'koKR', '더 좋아지지 않을 겁니다. 당신도 절 설득할 수 없습니다.', '더 좋아지지 않을 겁니다. 당신도 절 설득할 수 없습니다.', 28153),
(158689, 'koKR', '정말 굉장할 것이라 생각했는데, 보십시오... 전 아무것도 아닙니다.', '정말 굉장할 것이라 생각했는데, 보십시오... 전 아무것도 아닙니다.', 28153),
(158688, 'koKR', '전 다시는 태양을 느끼지 못할 겁니다.', '전 다시는 태양을 느끼지 못할 겁니다.', 28153),
(158687, 'koKR', '제게 며칠만 더 있었어도... 정말 많은 일을 했을 겁니다.', '제게 며칠만 더 있었어도... 정말 많은 일을 했을 겁니다.', 28153),
(158686, 'koKR', '죽었냐고요? 아니, 전 그저 잠시 쉬고 있을 뿐입니다.', '죽었냐고요? 아니, 전 그저 잠시 쉬고 있을 뿐입니다.', 28153),
(158685, 'koKR', '당신은 누구시죠? 상관없습니다. 별로 중요하지 않습니다...', '당신은 누구시죠? 상관없습니다. 별로 중요하지 않습니다...', 28153),
(158684, 'koKR', '보지 않으면 일어난 게 아닙니다. 간단해요.', '보지 않으면 일어난 게 아닙니다. 간단해요.', 28153),
(158683, 'koKR', '계속 가야 합니다... 계속 가야... 결국에는 바뀔 겁니다.', '계속 가야 합니다... 계속 가야... 결국에는 바뀔 겁니다.', 28153),
(158682, 'koKR', '감히 내 주둔지에서 설치고 다녀? 여기까지다!', '', 28153),
(158681, 'koKR', '약한 녀석. 진짜 전투에서 나와 싸워라!', '', 28153),
(158680, 'koKR', '그 초라한 기계로 내게 이겨보겠다는 것이냐!?', '', 28153),
(158679, 'koKR', '으쌰, 도전자 등장이오! 받아라!', '', 28153),
(158678, 'koKR', '하지만... 난 죽기에는 너무 잘생겼다고...', '', 28153),
(158677, 'koKR', '', '내장을... 손질해주마...', 28153),
(158676, 'koKR', '', '포를 떠 주마!', 28153),
(158675, 'koKR', '날 바다에 묻어라...', '', 28153),
(158674, 'koKR', '꽁꽁 묶어 바닷속에 처박아주마!', '', 28153),
(158673, 'koKR', '윽, 이 녀석 비호감이죠. 머리에 발라 대는 약품도, 직접 쓴 허접한 시도 끔찍하죠. 그렇다 해도, 리드는 사랑꾼에 싸움꾼입니다.', '', 28153),
(158672, 'koKR', '베케트는 자기가 대단한 줄 알고요.', '', 28153),
(158671, 'koKR', '루나는, 좀... 날카롭죠.', '', 28153),
(158670, 'koKR', '하... 인생에서 확실한 건 세금과 죽음뿐...', '', 28153),
(158669, 'koKR', '이것 보게? 처리할 장부가 아직 하나 남았었군!', '', 28153),
(158668, 'koKR', '', '너무 늦지 않았기만을 바라오. 서두르시오. 가서 내 딸을 찾아주시오.', 28153),
(158666, 'koKR', '', '운명의 끝은 스톰송 해안 부근의 섬이오. 최악의 범죄자와 반역자가... 평생 유배되는 곳이지.', 28153),
(158665, 'koKR', '', '용사여! 뭔가 알아낸 거요?', 28153),
(158661, 'koKR', '전 여길 빠져나가겠습니다! 도와줘서 고맙습니다, $p 님!', '', 28153),
(158660, 'koKR', '쿠아폰이 날카로운 비명을 지르며 신나게 꼬리를 휘두릅니다.', '', 28153),
(158659, 'koKR', '쿠아폰이 해골을 당신 손에 놓습니다.', '', 28153),
(158658, 'koKR', '쿠아폰이 해골을 발밑에 떨어뜨리고 장난스럽게 당신을 향해 울어댑니다.', '', 28153),
(158657, 'koKR', '', '우리가 졌습니다. 텔드랏실은 곧 쓰러질 겁니다.', 28153),
(158656, 'koKR', '파도가 너희를 모조리 삼키리라!', '', 28153),
(158655, 'koKR', '가세, 용사여. 대족장을 따라... 승리해야 하네.', '', 28153),
(158654, 'koKR', '', '효과가 있네요. 모두 타세요!', 28153),
(158653, 'koKR', '나도 선택지를 주지. 함께 다르나서스로 돌아가 우리가 그곳을 함락시킬 때 같이 죽든지... 아니면 어딘가 멀리 도망쳐 같이 살아남든지.', '', 28153),
(158652, 'koKR', '', '말퓨리온을 살려줬으니, 그대에게도 선택지를 주지.', 28153),
(158651, 'koKR', '', '굳건히 버티세요.', 28153),
(158650, 'koKR', '의미 없는 것이 아니다. 호드가 건재하기 위해 흘리는 피다.', '', 28153),
(158649, 'koKR', '', '이 전쟁 자체에 명예 따윈 없다. 무고한 피를 이렇게나 많이 흘리게 하다니... 아무 의미도 없이!', 28153),
(158648, 'koKR', '명예롭지 못한 습격이었으니, 내겐 그럴 자격이 없다.', '', 28153),
(158647, 'koKR', '', '죽이지 않았군. 왜지, 오크여?', 28153),
(158646, 'koKR', '', '말퓨리온! 안 돼!', 28153),
(158645, 'koKR', '그대는... 호드를 죽음의 길로 이끌었다. 오늘을... 후회하게 될 것이다...', '', 28153),
(158642, 'koKR', '', '상처를 치유하고 몸을 눕히십시오. 여기는 안전합니다.', 28153),
(158641, 'koKR', '저는 야수와 싸우다 죽었습니다. 상대를 잘 못 고른 거죠. 당신도 아는 놈입니다.', '저는 야수와 싸우다 죽었습니다. 상대를 잘 못 고른 거죠. 당신도 아는 놈입니다.', 28153),
(158640, 'koKR', '저도 당신처럼 혼란스럽습니다, 친구.', '저도 당신처럼 혼란스럽습니다, 친구.', 28153),
(158639, 'koKR', '하우리의 칠리의 열기를 견디지 못했습니다.', '하우리의 칠리의 열기를 견디지 못했습니다.', 28153),
(158638, 'koKR', '토르카나타에서 달리던 중에 죽었습니다. 할 수 있다면 다시 할 겁니다!', '토르카나타에서 달리던 중에 죽었습니다. 할 수 있다면 다시 할 겁니다!', 28153),
(158637, 'koKR', '문 앞에 당신 몸을 남겨주세요, 네?', '문 앞에 당신 몸을 남겨주세요, 네?', 28153),
(158636, 'koKR', '전 조칼로의 거리를 걷다가 벼락에 맞았습니다.', '전 조칼로의 거리를 걷다가 벼락에 맞았습니다.', 28153),
(158635, 'koKR', '피라미드에서 떨어져 죽었습니다. 지금은 왜 거기 올라갔는지도 기억나지 않아요.', '피라미드에서 떨어져 죽었습니다. 지금은 왜 거기 올라갔는지도 기억나지 않아요.', 28153),
(158634, 'koKR', '옷은 차려입었는데 갈 곳이 없군요.', '옷은 차려입었는데 갈 곳이 없군요.', 28153),
(158633, 'koKR', '보랄러스에 이 차원문을 배치할 정확한 위치를 계산하는 일이 쉽지는 않았네만, 즐거운 도전이었네! 상황이 어떤지 얘기해 주겠나?', '', 28153),
(158632, 'koKR', '알겠습니다, 나타노스 님.', '', 28153),
(158631, 'koKR', '젤링, $n|1과;와; 보랄러스로 가게. 오큘레스가 차원문을 열고 기다리고 있네.', '', 28153),
(158630, 'koKR', '어이 거기, 얘기 좀 하지.', '', 28153),
(158629, 'koKR', '여긴 이 집에서 가장 좋은 자리일세... 내가 일어나면 여기 앉게나.', '', 28153),
(158628, 'koKR', '', '$p 님이라고요? 흠, 처음 들어보는군요.', 28153),
(158627, 'koKR', '함선으로 갈 준비가 되면 호바트를 만나게. 자네를 지원하려 기다리고 있네.', '', 28153),
(158626, 'koKR', '분명히 경고했습니다.', '분명히 경고했습니다.', 28153),
(158625, 'koKR', '물러서십시오! 당신을 위해서입니다.', '물러서십시오! 당신을 위해서입니다.', 28153),
(158624, 'koKR', '쿠아폰이 공포에 떨고 있습니다.', '', 28153),
(158623, 'koKR', '흐름이 확실히 우리에게 유리하게 바뀌었군요. 그렇지 않습니까, $n|1이여;여;?', '', 28153),
(158622, 'koKR', '수평선에서 굉장한 것을 봤습니다. 당신도 관심이 갈 겁니다.', '', 28153),
(158621, 'koKR', '저를 두고 가지 마십시오. 전 광산에서 일하기에는 너무 늙었습니다.', '저를 두고 가지 마십시오. 전 광산에서 일하기에는 너무 늙었습니다.', 28153),
(158620, 'koKR', '발효 과정에서 우리가 뭘 잘못했는지 살펴볼 수 있겠어.', '', 28153),
(158619, 'koKR', '그래, 보이지 않는 오염물 유입이 초기 환원 과정에 영향을 미치고 있는 것일 수 있겠군.', '', 28153),
(158618, 'koKR', '분부대로.', '', 28153),
(158617, 'koKR', '무엇이든 도와드리죠.', '', 28153),
(158616, 'koKR', '일하러 가겠습니다.', '', 28153),
(158615, 'koKR', '물론이죠, 도와드리겠습니다.', '', 28153),
(158614, 'koKR', '제가 도와드릴 수 있을 것 같군요.', '', 28153),
(158612, 'koKR', '', '주위를 둘러보거라. 나무에 눈이 달렸구나, 용사여. 저 눈을 멀게 만들어라.', 28153),
(158611, 'koKR', '주요 혼합물을 안정화하는 데 먼저 집중해야겠어.', '', 28153),
(158610, 'koKR', '오오! 이제 말이 되는군! \"연금술의 첫 번째 법칙, 무언가 가치 있는 것을 얻기 위해서는 동등한 치환물을 희생해야 한다.\"', '', 28153),
(158609, 'koKR', '시작해 봅시다!', '시작해 봅시다!', 28153),
(158608, 'koKR', '흥미롭군... 정밀한 가열이 무척 중요하구나.', '', 28153),
(158607, 'koKR', '아아! 촉매가 어디서 잘못됐는지 알겠다.', '', 28153),
(158606, 'koKR', '이상해... 이런 걸 예측할 수 있었을 리가 없지.', '', 28153),
(158605, 'koKR', '흐음... 재미있는데.', '', 28153),
(158604, 'koKR', '친구들 몇 명이 저기 잡혀버렸네. 좀 도와주지 그래?', '', 28153),
(158603, 'koKR', '이봐! 누가 우리 물건을 잔뜩 훔쳐갔잖아! 당장 되찾아야겠군. 이자까지 톡톡히 쳐서 말이야.', '', 28153),
(158602, 'koKR', '이런, 사방이 부상병이잖아. 도와줘야 한다고!', '', 28153),
(158601, 'koKR', '잠입 잘 하는 도둑 어디 없나? 맡길 일이 있는데!', '', 28153),
(158600, 'koKR', '이거 봐, 저기서 전쟁 세발차 예비 부품이 보이거든 알려 달라고. 다 고치면 한바퀴 타고 오게 해줄 테니까 말이야.', '', 28153),
(158599, 'koKR', '저 녀석, 내 눈에 띄었겠다? 전통 케잔 식으로 흠씬 두들겨 줘야겠는데!', '', 28153),
(158598, 'koKR', '우와, 엄청난 크기잖아. 저거 해치울 사람?', '', 28153),
(158597, 'koKR', '얼라이언스 병사들 몇 명이 붙잡혔습니다. 구조 작전을 개시하는 게 어떻겠습니까?', '', 28153),
(158596, 'koKR', '적 병력이 중요한 보급품을 탈취해 갔습니다. 이 도둑놈들에게 얼라이언스의 정의를 보급해줘야 할 것 같은데요?', '', 28153),
(158595, 'koKR', '전장에 부상병이 있습니다. 치료를 도와주시겠습니까?', '', 28153),
(158594, 'koKR', '그렇다, 아이야. 엘룬의 축복으로 드루이드들이 커다란 바람을 다룰 힘을 얻어 항해를 마쳤다.', '', 28153),
(158593, 'koKR', '', '장막의 바다는 잔잔했습니까?', 28153),
(158592, 'koKR', '항구로 보내주십시오.', '항구로 보내주십시오.', 28153),
(158591, 'koKR', '작은 함선으로 보내주십시오.', '작은 함선으로 보내주십시오.', 28153),
(158590, 'koKR', '비밀 작전에 투입할 용감한 지원자를 찾고 있습니다. 은신과 속임수에 능한 사람이 필요한데요.', '', 28153),
(158589, 'koKR', '적의 전쟁 기계를 회수하려는 중입니다. 예비 부품이 보이면 가져다주십시오.', '', 28153),
(158588, 'koKR', '아, 표적이 제 발로 걸어들어왔습니다.', '', 28153),
(158587, 'koKR', '사납고 덩치 큰 야생 동물이 전장을 배회하는군요. 사냥 시작입니다!', '', 28153),
(158586, 'koKR', '내 작은 친구 맛 좀 볼래?', '', 28153),
(158585, 'koKR', '지금 잠자는 사자의 코털을 건드리는 거라고.', '', 28153),
(158584, 'koKR', '이봐, 진정하라고.', '', 28153),
(158583, 'koKR', '고장내지 말고 가져오라고, 알았지?', '', 28153),
(158582, 'koKR', '긴장을 늦추지 말라고.', '', 28153),
(158581, 'koKR', '몸조심하라고.', '', 28153),
(158580, 'koKR', '좋은 소식이라도?', '', 28153),
(158579, 'koKR', '잘 지내고 있어?', '', 28153),
(158578, 'koKR', '좋아 보이는데.', '', 28153),
(158577, 'koKR', '빛이여, 술 한 잔이 간절합니다.', '', 28153),
(158576, 'koKR', '아무리 돈을 많이 줘도 이건 못 참겠습니다.', '', 28153),
(158575, 'koKR', '아 예, 예...', '', 28153),
(158574, 'koKR', '하던 일 마저 하십시오.', '', 28153),
(158573, 'koKR', '이만 가보십시오.', '', 28153),
(158572, 'koKR', '경계를 늦추지 마십시오.', '', 28153),
(158571, 'koKR', '무슨 일이십니까?', '', 28153),
(158570, 'koKR', '집중해서 듣고 있습니다.', '', 28153),
(158569, 'koKR', '얼라이언스에 영광을.', '', 28153),
(158568, 'koKR', '', '안 돼... 이럴 순 없어.', 28153),
(158565, 'koKR', '', '네 힘의 한계를 시험해보자, 네가 도와다오!', 28153),
(158564, 'koKR', '', '내 마법이 잔혹하다고들 하지만, 난 무슨 일까지 가능할지 탐구할 뿐이야.', 28153),
(158563, 'koKR', '이동 불가', '이동 불가', 28153),
(158562, 'koKR', '미아... 미아! 나의 왕비... 눈을 뜨시오, 내 사랑!', '', 28153),
(158561, 'koKR', '여신의 가호가 함께하길.', '', 28153),
(158560, 'koKR', '저 밴시가 내 아들을 죽이고, 내 왕국을 빼앗았지만, 내 사랑마저 앗아갈 순 없다!', '', 28153),
(158559, 'koKR', '', '그들은... 가지 않을 거예요...', 28153),
(158558, 'koKR', '아스타리, 자네는 할 만큼 했네! 사제들을 지휘해 함께 오라 하게!', '', 28153),
(158557, 'koKR', '안 돼! 모두 데려갈 것이오!', '', 28153),
(158555, 'koKR', '', '나무가... 나무가 불타고 있어요! 아이를... 구하세요. 저는... 괜찮아요.', 28153),
(158554, 'koKR', '여기에 더 머물러선 안 되오! 차원문으로 탈출해야만 하오!', '', 28153),
(158553, 'koKR', '', '아스타리, 시간이 없어요. 잿더미만 남기 전에 도시를 빠져나가야 해요!', 28153),
(158551, 'koKR', '', '여길 마무리하시오. 원한다면 잠시 시간을 갖고... 그 목을 가져오시오. 세계수에서 보겠소.', 28153),
(158550, 'koKR', '', '내 승리는 정해진 수순이었소. 이자는 겨우 시간을 끌었을 뿐.', 28153),
(158549, 'koKR', '내가 끼어들어서는 안 되었소.', '', 28153),
(158548, 'koKR', '', '후회할 것 없소. 아주 좋았으니.', 28153),
(158547, 'koKR', '내가 이렇게 불명예스러운 짓을...', '', 28153),
(158546, 'koKR', '으윽! 사울팽...?!', '', 28153),
(158545, 'koKR', '대족장 혼자서 스톰레이지를!? 내가...', '', 28153),
(158544, 'koKR', '북쪽이라고? 대체 어떻게... 아, 악령숲의 산맥을 오른 게로구나. 분명!', '', 28153),
(158543, 'koKR', '용사여, 델라린, 아우버다인에서 저들을 막아라. 나는 북쪽을 살펴보겠다.', '', 28153),
(158542, 'koKR', '호드가 뚫고 들어오는 것도 시간 문제다. 양쪽에서 쳐들어오겠구나.', '', 28153),
(158541, 'koKR', '위습들이... 점점 당황하고 있다! 벽이 무너진다!', '', 28153),
(158540, 'koKR', '', '저 소리는... 설마...? 샨도! 호드가 북쪽에서 다가옵니다!', 28153),
(158539, 'koKR', '', '때가 왔다. 세계수는 우리 것이나 다름없다! 사울팽을 찾아라. 이제 모든 일의 결착을 내야만 한다.', 28153),
(158537, 'koKR', '', '보아라, 영웅이여! 이 얼마나 아름다운 광경인가. 위습들이 흩어지는구나. 한 마리 한 마리씩... 벽이 무너져 내리는군.', 28153),
(158536, 'koKR', '', '사울팽인가! 때가 되었군.', 28153),
(158535, 'koKR', '호드를 위하여!', '', 28153),
(158534, 'koKR', '', '약삭빠른 것, 어디로 도망쳤느냐?', 28153),
(158533, 'koKR', '', '아악! 내 눈이! 타들어간다!', 28153),
(158532, 'koKR', '사라져라, 마녀야!', '', 28153),
(158531, 'koKR', '', '놀라워라, 귀하디 귀한 나무를 지키러 직접 행차하시다니.', 28153),
(158530, 'koKR', '', '말퓨리온, 이렇게 반가울 데가 있나...', 28153),
(158529, 'koKR', '실바나스! 네 어리석은 짓이 이 신성한 장소를 모독하는구나! 안두 팔라 도르!', '', 28153),
(158528, 'koKR', '', '녀석들이 평온하게 밤의 휴식을 맛보게 둘 수는 없지. 이건 전쟁이다.', 28153),
(158527, 'koKR', '', '동시에, 할 수 있는 모든 수를 써서 칼도레이를 계속 압박할 것이다.', 28153),
(158526, 'koKR', '', '사울팽의 소식을 기다릴 동안, 난 병사를 벽 너머로 이끌겠다.', 28153),
(158525, 'koKR', '', '당장은 이대로 진행해야 한다.', 28153),
(158524, 'koKR', '', '성난굽이 강은 교착 상태고, 말퓨리온도 그걸 알고 있지.', 28153),
(158523, 'koKR', '', '호드의 용사들이여, 성난굽이 강에 너희의 도움이 필요하다! 우리가 승리를 차지할 기회다!', 28153),
(158522, 'koKR', '', '...까마귀 하나를 잡아야겠군.', 28153),
(158521, 'koKR', '', '서둘러 할 일을 해라. 아제라이트를 최대한 모아 기술자들에게 전달해야 한다.', 28153),
(158520, 'koKR', '', '저 함선은 다르나서스에서 왔을 터... 그렇다면...', 28153),
(158519, 'koKR', '', '조심해서 전진해라, 용사여. 얼라이언스가 선수를 친 것 같으니.', 28153),
(158518, 'koKR', '', '아제라이트... 손에 넣기만 하면, 호드에 맞서는 이들은 모두 멸망하리라.', 28153),
(158517, 'koKR', '', '공병들은 장비를 들고 날 따라와라! 벌목기를 모두 동원해라!', 28153),
(158516, 'koKR', '', '그들을 없애라. 그렇지 않으면 이 숲이 우리 동료들의 피로 물들 것이다.', 28153),
(158515, 'koKR', '', '흠... 심기가 불편한가 보구나, 드루이드여. 이 고대정령들은 너에게서 등을 돌리고, 신성한 의무를 외면했다.', 28153),
(158514, 'koKR', '탤리아! 우리 좀 태워 줘!', '', 28153),
(158513, 'koKR', '\"절벽에서 뛰어내리라\"는 말입니다! 어서요!', '', 28153),
(158512, 'koKR', '극적으로 탈출하죠!', '', 28153),
(158511, 'koKR', '상자를 낚아채고...', '', 28153),
(158510, 'koKR', '태양이 내 남은 피부에 이토록 가혹할 줄은 몰랐소.', '태양이 내 남은 피부에 이토록 가혹할 줄은 몰랐소.', 28153),
(158509, 'koKR', '다 생각이 있습니다.', '', 28153),
(158508, 'koKR', '저걸 들고 여기서 탈출하는 계획은 세우셨겠죠?', '저걸 들고 여기서 탈출하는 계획은 세우셨겠죠?', 28153),
(158507, 'koKR', '할란이 금고에 열쇠를 추가하여 보안을 강화했습니다.\n\n<턱을 문지르는 플린>\n\n네, 지금은 상자를 훔치는 것 말고는 다른 방법이 없겠습니다.', '', 28153),
(158506, 'koKR', '제법이군, 할란. 제법이야.', '', 28153),
(158505, 'koKR', '찾아낸 생도 모두에게 대학을 백 바퀴쯤 돌게 할 생각입니다.', '', 28153),
(158504, 'koKR', '그들은 분명 여기 어디쯤 있을 겁니다.', '', 28153),
(158503, 'koKR', '우리도 여기 오고 싶어 온 게 아니라오... 누가 이런 일을 겪고 싶어 하겠소.', '우리도 여기 오고 싶어 온 게 아니라오... 누가 이런 일을 겪고 싶어 하겠소.', 28153),
(158502, 'koKR', '자물쇠가 네 개네?!', '', 28153),
(158501, 'koKR', '얼라이언스가 감히 우리를 괴물로 생각한다고?', '얼라이언스가 감히 우리를 괴물로 생각한다고?', 28153),
(158500, 'koKR', '생도들이 어디로 갔을까요...', '', 28153),
(158499, 'koKR', '아, 찾았군요. 할란 스위트의 금고입니다.', '', 28153),
(158498, 'koKR', '그분이 남부럽지 않은 삶을 보내시지 못한 건 이해하오. 하지만, 이제 쿨 티라스를 더 잘 이끌어갈 사람에게 넘겨주실 때가 된 것 같소.', '그분이 남부럽지 않은 삶을 보내시지 못한 건 이해하오. 하지만, 이제 쿨 티라스를 더 잘 이끌어갈 사람에게 넘겨주실 때가 된 것 같소.', 28153),
(158497, 'koKR', '캐서린 님의 정신이 세상을 뜬 남편의 뒤를 따르고 있다는 사실이 날이 갈수록 점점 명확해지는 것 같소.', '캐서린 님의 정신이 세상을 뜬 남편의 뒤를 따르고 있다는 사실이 날이 갈수록 점점 명확해지는 것 같소.', 28153),
(158496, 'koKR', '이번 주에도 가문들이 회합을 가지지 않았소.', '이번 주에도 가문들이 회합을 가지지 않았소.', 28153),
(158495, 'koKR', '그러게 말이오. 정신이 제대로 박힌 티라가드 귀족이라면 희생자가 떠들고 다닐 만한 눈물겨운 이야기를 만들 여지조차 없애버렸을 텐데.', '그러게 말이오. 정신이 제대로 박힌 티라가드 귀족이라면 희생자가 떠들고 다닐 만한 눈물겨운 이야기를 만들 여지조차 없애버렸을 텐데.', 28153),
(158494, 'koKR', '대낮에, 그것도 결혼식 당일에 살인이라니, 정말 어설픈 계획이었소.', '대낮에, 그것도 결혼식 당일에 살인이라니, 정말 어설픈 계획이었소.', 28153),
(158493, 'koKR', '그녀의 약혼자? 물론이지, 정말 유감이오.', '그녀의 약혼자? 물론이지, 정말 유감이오.', 28153),
(158492, 'koKR', '웨이크레스트 가문의 딸이 무슨 일을 당했는지 들었소?', '웨이크레스트 가문의 딸이 무슨 일을 당했는지 들었소?', 28153),
(158491, 'koKR', '오호 통재라. 바다의 힘을 부릴 줄도 모르는 스톰송 가문 사람이 어디 있어? 내가 그 가문 사람이었다면 진작에 의절했을 텐데.', '오호 통재라. 바다의 힘을 부릴 줄도 모르는 스톰송 가문 사람이 어디 있어? 내가 그 가문 사람이었다면 진작에 의절했을 텐데.', 28153),
(158490, 'koKR', '그 양반 삼촌이라는 사람이 우릴 더 괴롭히려나 보군?', '그 양반 삼촌이라는 사람이 우릴 더 괴롭히려나 보군?', 28153),
(158489, 'koKR', '브래넌이 해협을 관리하러 돌아왔다던데.', '브래넌이 해협을 관리하러 돌아왔다던데.', 28153),
(158488, 'koKR', '모친을 닮은 제이나 님을 보니 적잖게 안심이 되오. 솔직히 댈린 님이 잘생긴 편은 아니었잖소.', '모친을 닮은 제이나 님을 보니 적잖게 안심이 되오. 솔직히 댈린 님이 잘생긴 편은 아니었잖소.', 28153),
(158487, 'koKR', '', '<단검이 등에 꽂힌 상태지만, 소지품은 모두 사라졌습니다.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158486, 'koKR', '', '<이 잔달라 시체는 죽은 지 얼마 되지 않은 것 같습니다.>', 28153),
(158485, 'koKR', '<시신을 살펴봅니다.>', '<시신을 살펴봅니다.>', 28153),
(158484, 'koKR', '웨이크레스트는 한동안 보랄러스에 오지 않았소. 메레디스가 자신이 여기 얼마나 어울리지 않는지 결국 깨달은 모양이오.', '웨이크레스트는 한동안 보랄러스에 오지 않았소. 메레디스가 자신이 여기 얼마나 어울리지 않는지 결국 깨달은 모양이오.', 28153),
(158483, 'koKR', '스톰송 군주가 저번에 왔을 때 입었던 옷을 보았는가? 촉수 달린 모자는 좀 촌스럽지 않나.', '스톰송 군주가 저번에 왔을 때 입었던 옷을 보았는가? 촉수 달린 모자는 좀 촌스럽지 않나.', 28153),
(158482, 'koKR', '<쿤가를 힐끗 보는 사이먼>\n\n음, 그래... 하! 하! 농담도 잘하는군, 친구!\n\n하! 하! 정말 재미있어!\n\n당장 떠나게. 다른 시체를 찾기 전에. 하! 하!\n\n가서 싸움이나 지켜보게. 내가... 상품을 보충하는 동안 말일세.', '', 28153),
(158481, 'koKR', '천막 뒤에서 시체를 발견했습니다.', '천막 뒤에서 시체를 발견했습니다.', 28153),
(158480, 'koKR', '안녕하신가, 음, 그래.\n\n내 상점에 온 것을 환영하네. 사이먼의... 머시기... 판매... 상점.\n\n내가 파는 건...\n\n<재빨리 뒤를 쳐다보는 사이먼>\n\n무기일세. 없는 무기가 없지. 하지만, 지금은 바쁘군.\n\n나중에 다시 오면 어떻겠나. 그러니까... 상품이 입고되면 말일세.', '', 28153),
(158479, 'koKR', '더러운 호드 놈아, 내가 죽여주마!', '', 28153),
(158478, 'koKR', '얼라이언스에겐 우리 땅을 차지할 권리가 없소!', '얼라이언스에겐 우리 땅을 차지할 권리가 없소!', 28153),
(158477, 'koKR', '뭐든 길에서 먹는 빵보다는 낫겠군.', '', 28153),
(158476, 'koKR', '우리 병력은 사람들이 대피할 시간을 벌어주고, 호드를 궁지로 모는 데 집중하고 있다. 우리 파수병들이 먹을 것을 구해 와라.', '', 28153),
(158475, 'koKR', '', '바다 깊은 곳으로 가라앉혀 주마!', 28153),
(158474, 'koKR', '주머니에 든 게 모조는 아닐세.', '', 28153),
(158473, 'koKR', '아, 똑같이 갚아줘야겠군!', '', 28153),
(158472, 'koKR', '내가 자넬 두꺼비로 만들어야 그만둘 텐가!', '', 28153),
(158471, 'koKR', '관두는 게 좋을 걸세. 나는 늙었지만, 그만큼 사술에는 능하니까.', '', 28153),
(158470, 'koKR', '진정하게, 친구. 그렇게 더듬거릴 필요는 없지 않나.', '', 28153),
(158469, 'koKR', '나는 몇 세대에 걸쳐 검은창 트롤을 훈련시켜 왔네.', '', 28153),
(158468, 'koKR', '행운을 비네, 늘 선한 모조를 가까이 하길.', '', 28153),
(158467, 'koKR', '', '뭐든 길에서 먹는 식량보다는 낫겠지.', 28153),
(158466, 'koKR', '', '부대 하나가 먹을 걸 찾아 움직였다고 들었다. 이 숲에 배를 채울 만한 것이 있는 게 분명하다.', 28153),
(158465, 'koKR', '기억하게, 세상엔 재생되지 않는 것들도 있다는 사실을.', '', 28153),
(158464, 'koKR', '조심해요!', '', 28153),
(158463, 'koKR', '필요한 표본을 거의 다 얻었습니다! 조금만 더...', '', 28153),
(158462, 'koKR', '흠, 잎이 생각처럼은 잘 안 떨어지는군요... 그래도 진전은 있습니다.', '', 28153),
(158461, 'koKR', '시간이 좀 걸릴 겁니다. 잎을 따는 게 좀 섬세한 작업이거든요.', '', 28153),
(158460, 'koKR', '이러기엔 너무 늙었어.', '', 28153),
(158459, 'koKR', '정령의 가호가 따르길.', '', 28153),
(158458, 'koKR', '에쿰 보쿰.', '', 28153),
(158457, 'koKR', '누가 의술사를 찾았는가?', '', 28153),
(158456, 'koKR', '도움을 바라는가?', '', 28153),
(158455, 'koKR', '어서 오게, 친구.', '', 28153),
(158454, 'koKR', '영혼의 안내를 받고 싶습니다.', '영혼의 안내를 받고 싶습니다.', 28153),
(158453, 'koKR', '영혼이 당신을 안내할 수 있습니다.', '', 28153),
(158452, 'koKR', '우나페입니다, $n 님. 이 전초기지는 당신의 명령을 따릅니다.', '', 28153),
(158451, 'koKR', '', '당분간은 놈들도 손을 못 쓰겠죠. 하지만 보급선을 완전히 끊기 전까진 경계를 늦출 수 없어요.', 28153),
(158450, 'koKR', '', '양껏 드시고 푹 쉬십시오!', 28153),
(158449, 'koKR', '이 방의 봉인이 세계혼을 보호하는 걸세. 하지만 아제라이트가 이렇게 터져나오는 바람에 봉인이 파괴되기 직전이네!', '', 28153),
(158448, 'koKR', '아뮬렛을 사용해 아제라이트를 흡수하면 그 힘으로 방의 봉인을 복구할 수 있을 걸세!', '', 28153),
(158447, 'koKR', '', '폭력조직원들이 위험한 아제라이트 폭탄을 입수했다는 소문이 있어요. 그 폭탄을 회수하기 전까진 보랄러스의 그 누구도 안전하지 않아요.', 28153),
(158446, 'koKR', '제 배는 가라앉았고 수백 명이 물에 빠졌습니다. 곧이어 상어가 나타났죠. 큰 상어, 작은 상어, 화난 상어요. 온 힘을 다해 놈들과 싸웠습니다만... 상어 코앞에서 생기 없는 검은 눈을 마주 보게 되면 놈들은 살아 있는 것처럼 보이지도 않다가 튀어 올라 물어뜯습니다. 그렇게 바다는 붉게, 거의 검어질 정도로 붉게 물들었고 사람들은 순식간에 찢겨나갔습니다. 첫날 밤에만 절반은 죽었을 겁니다. 우리가 10명이라면 상어는 수천 마리였죠. 5일 정도 지나 결국 구조선이 왔지만, 구조받지 못한 게 대부분이었습니다. 316명 가운데 7명만 살아 돌아오고 나머지는 상어 밥이 됐죠.\n\n이야기는 그만하겠습니다. 상어와 한 판 붙어 보고 싶으십니까?', '', 28153),
(158445, 'koKR', '감사합니다. 운을 시험해 보죠. 장화를 빌려주십시오.', '감사합니다. 운을 시험해 보죠. 장화를 빌려주십시오.', 28153),
(158444, 'koKR', '', '아야! 마차에서 상자를 좀 내리려다... 으... 위에서 떨어졌어요.\n\n적어도 코다는 괜찮군요. 우리 코다를 다치게 할 수 있는 건 아무것도 없다고요!\n\n북쪽으로 도약해서 돌아가셔야 한다면, 남는 장화를 빌려드릴 수 있어요. 솔직히 말씀드리면... 아직 시험해보지는 않았어요.', 28153),
(158443, 'koKR', '', '늦었군요.', 28153),
(158442, 'koKR', '', '사람들을 도와주세요. 저는 계속 갈게요!', 28153),
(158441, 'koKR', '', '우선 관문부터 지켜야 돼!', 28153),
(158440, 'koKR', '', '오, 안 돼...', 28153),
(158439, 'koKR', '', '아니까, 일단 좀 쉬어. 그놈을 혼쭐내 줄 테니.', 28153),
(158438, 'koKR', '할란... 그놈이 애쉬베인에게 붙었어... 놈은... 윽!', '', 28153),
(158437, 'koKR', '안 다친 데가... 없는데...<쿨럭>', '', 28153),
(158436, 'koKR', '', '플린! 괜찮아, 내가 잡았어! 몸은 어때? 다친 덴 없고?', 28153),
(158435, 'koKR', '어... 아... 우아아아아!', '', 28153),
(158434, 'koKR', '', '좋습니다. 어머니, 집으로 돌아가요.', 28153),
(158433, 'koKR', '', '꽉 잡으세요!', 28153),
(158432, 'koKR', '떠날 준비 됐습니다.', '떠날 준비 됐습니다.', 28153),
(158431, 'koKR', '', '그대가 준비되면 순간이동으로 이곳을 빠져나가도록 하죠.\n\n서두르세요. 어서 이곳에서 벗어나고 싶으니.', 28153),
(158430, 'koKR', '컷신!', '컷신!', 28153),
(158429, 'koKR', '나이트 엘프와는 잘 지낼 수 있겠지만... 음, 위습은 적응하려면 시간이 좀 걸릴 것 같군요.', '', 28153),
(158428, 'koKR', '땅을 이용하고 땅을 경작한다. 그렇게 하기로 되어 있었습니다.', '', 28153),
(158427, 'koKR', '저들의 나무에 일어난 일은 정말 유감입니다.', '', 28153),
(158426, 'koKR', '우린 데렉 님의 시신을 가져갈 것이다. 그걸 막을 수 있을 것 같으냐? 착각 마라!', '', 28153),
(158425, 'koKR', '이번에는 로가 목표 지점으로만 가면 됩니다만, 미로에 도사리는 위험을 조심하십시오.', '', 28153),
(158424, 'koKR', '이제 로가 보물에 닿은 후 목표 지점에 가도록 인도해 주십시오. 단, 로가 갔던 길이 서로 겹치면 안 됩니다.', '', 28153),
(158423, 'koKR', '참 쉽죠?', '', 28153),
(158422, 'koKR', '먼저 간단한 도전부터. 로를 목표 지점으로 인도하십시오.', '', 28153),
(158421, 'koKR', '어린 토르톨란에게 이 이야기를 들려줄 때면, 작은 미로에 있는 로를 인도해 여러 도전을 완수하도록 하지요.', '', 28153),
(158420, 'koKR', '전투 훈련 준비가 되었습니까?', '전투 훈련 준비가 되었습니까?', 28153),
(158419, 'koKR', '어디, 벌 볼 일 있나 봅시다, $p 님!', '어디, 벌 볼 일 있나 봅시다, $p 님!', 28153),
(158418, 'koKR', '로는 첫 성공을 거둔 이후 자신감이 커졌고, 더 많은 멋진 지역들을 탐험했지요.', '', 28153),
(158416, 'koKR', '로가 모든 보물에 닿은 후 출구로 나가게 인도해 주십시오. 단, 로가 갔던 길이 서로 겹치면 안 됩니다.', '', 28153),
(158415, 'koKR', '로는 마주치는 고대 폐허들을 탐험하기 시작했고, 종종 귀중한 보물을 발견하기도 했습니다.', '', 28153),
(158414, 'koKR', '\"탐험가 로.\" 로는 자라면서 점점 세상에 호기심이 생겼습니다.', '', 28153),
(158413, 'koKR', '로의 성실함은 결실을 맺었고, 대지는 그에게 많은 영양분을 공급했습니다.', '', 28153),
(158412, 'koKR', '로가 정원에 있는 모든 식물을 한 번에 둘러보도록 도와주세요.', '', 28153),
(158411, 'koKR', '매일 아침 정원에 있는 모든 식물을 찾아가 보살펴주었죠.', '', 28153),
(158410, 'koKR', '', '드러스트는 포로를 살려둘 생각이 없는 게 분명하오. 이 운명이 제이나를 덮치게 둘 순 없소.', 28153),
(158409, 'koKR', '\"로의 수확물\". 로는 성장을 지켜보는 걸 좋아했습니다.', '', 28153),
(158408, 'koKR', '로는 간신히 함정에서 빠져나왔고, 그 후로는 좀 덜 신나게 살기로 했답니다.', '', 28153),
(158407, 'koKR', '로가 빛나는 바닥을 모두 끄고 함정을 해제할 수 있게 도와 주시겠습니까?', '', 28153),
(158406, 'koKR', '\"호기심과 토르톨란.\" 한번은 호기심을 참지 못하고 로가 고대 잔달라의 함정을 발동시킨 적이 있답니다!', '', 28153),
(158405, 'koKR', '', '자비를 구걸하게 해주마!', 28153),
(158404, 'koKR', '로에게 대도시의 삶은 맞지 않았습니다. 결국 다시 소박한 삶을 살기로 했지요.', '', 28153),
(158403, 'koKR', '하지만 매번 길을 잃었죠. 로가 모든 상점에 들른 다음 여관에 가도록 인도해 주십시오. 단, 로가 갔던 길이 서로 겹치면 안 됩니다.', '', 28153),
(158402, 'koKR', '\"대도시의 삶.\" 로는 대도시에 간 적이 있습니다. 저기 보랄러스와 아주 비슷하답니다.', '', 28153),
(158401, 'koKR', '로는 조용하고 평화로운 삶을 누렸습니다... 물론 배도 잔뜩 채웠고요.', '', 28153),
(158399, 'koKR', '', '이 제단 주변에서 하급 정령을 조금 잡았죠. 아주 놀라운 존재들이에요. 어떤 재주가 있는지 한 번 보시겠어요?', 28153),
