(153673, 'koKR', '호드가 높은 감시대를 점령했습니다!', '호드가 높은 감시대를 점령했습니다!', 28153),
(153672, 'koKR', '$n|1이;가; 높은 감시대를 점령했습니다!', '$n|1이;가; 높은 감시대를 점령했습니다!', 28153),
(153671, 'koKR', '호드가 뉴스테드를 점령했습니다!', '호드가 뉴스테드를 점령했습니다!', 28153),
(153670, 'koKR', '$n|1이;가; 뉴스테드를 점령했습니다!', '$n|1이;가; 뉴스테드를 점령했습니다!', 28153),
(153669, 'koKR', '호드가 고원 제재소를 점령했습니다!', '호드가 고원 제재소를 점령했습니다!', 28153),
(153668, 'koKR', '$n|1이;가; 고원 제재소를 점령했습니다!', '$n|1이;가; 고원 제재소를 점령했습니다!', 28153),
(153667, 'koKR', '호드가 밸러콜의 길을 점령했습니다!', '호드가 밸러콜의 길을 점령했습니다!', 28153),
(153666, 'koKR', '$n|1이;가; 밸러콜의 길을 점령했습니다!', '$n|1이;가; 밸러콜의 길을 점령했습니다!', 28153),
(153665, 'koKR', '우리의 영웅담은 군사 연대기에 길이 남겨질 것입니다.', '', 28153),
(153664, 'koKR', '위대한 전략과 물 흐르는 듯한 수행력. 녀석들 혼을 쏙 빼놨을 겁니다.', '', 28153),
(153663, 'koKR', '녀석들의 무방비 상태를 잘 노렸습니다.', '', 28153),
(153662, 'koKR', '', '빅토리아! 구하지... 못했어요...', 28153),
(153661, 'koKR', '', '모두, 나타노스를 따라 안마당으로 가라! 나는 후방에서 얼라이언스를 막겠다!', 28153),
(153660, 'koKR', '병사들이여, 대열을 정비해라! 얼라이언스가 다가온다!', '', 28153),
(153659, 'koKR', '', '잔달라는 어떤 공포가 기다리는지 모르고 있습니다. 경고해줘야 합니다.', 28153),
(153658, 'koKR', '', '아즈샤라 여왕이 뭔가 일을 꾸미고 있어요. 그것도 누군가와 함께 말입니다.', 28153),
(153657, 'koKR', '', '세상에! 끔찍하군요. 이건 그랄 님께 충성하는 자들을 죽이라는 살인 지령입니다.', 28153),
(153656, 'koKR', '트인 곳으로 나오면 우리 수가 열 배는 많을 것입니다!', '', 28153),
(153655, 'koKR', '골렘에게 돌려보내지 말아 줘...', '내 영혼을 풀어줘. 제발...', 28153),
(153654, 'koKR', '우리가 간다, 자크라잔...', '다음은 네놈이다, 자크라잔...', 28153),
(153653, 'koKR', '마침내... 끝났구나.', '마침내... 안식을...', 28153),
(153652, 'koKR', '브원삼디 님이... 죽음을 허락치 않으실 거야...', '저편은... 어디인가?', 28153),
(153651, 'koKR', '묘묙이 야생 동물에게 먹혔습니다!', '묘묙이 야생 동물에게 먹혔습니다!', 28153),
(153650, 'koKR', '우아아아아아악!', '', 28153),
(153649, 'koKR', '호드가 도망치게 해서는 안 된다!', '', 28153),
(153648, 'koKR', '경비대! 공격받고 있다! 위치를 사수하라! 관문을 내리고 출구를 막아라!', '', 28153),
(153647, 'koKR', '그럼, 출발!', '', 28153),
(153646, 'koKR', '물론이죠.', '물론이죠.', 28153),
(153645, 'koKR', '당신 친구들은 모두 마녀에게 고문당하고 살해당했습니다.', '당신 친구들은 모두 마녀에게 고문당하고 살해당했습니다.', 28153),
(153644, 'koKR', '어우, 맙소사! 좋지 않군.\n\n나한테 좋은 소식이 있어. 여기 언덕 위에 거점을 거의 다 만들었다고. 가서 확인해 보겠어?', '', 28153),
(153643, 'koKR', '보아하니 숲에서 왔군. 그 아래 친구들은 어떻게 지내지?', '', 28153),
(153642, 'koKR', '그것도 제가 이 늑토바이를 발명한 직후에!', '', 28153),
(153641, 'koKR', '대장님, 오셨군요! 세발차까지 가져오셨네요!', '', 28153),
(153640, 'koKR', '격전의 스트롬가드 전투 시작 1분 전입니다.', '', 28153),
(153639, 'koKR', '힘을 합하면 더욱 강해집니다.', '', 28153),
(153638, 'koKR', '절대 지지 마세요. 그리고 죽지 마십시오.', '', 28153),
(153637, 'koKR', '조심하십시오.', '', 28153),
(153636, 'koKR', '내가 어리석은 짓 하지 말라고 했잖나?', '', 28153),
(153635, 'koKR', '추방자들은 당신을 환영합니다, 여행자여.', '', 28153),
(153634, 'koKR', '도움이 필요하신가요?', '', 28153),
(153633, 'koKR', '무슨 일로 오셨습니까?', '', 28153),
(153632, 'koKR', '바람이 그대의 등을 받쳐 주길.', '', 28153),
(153631, 'koKR', '힘과 고결함이 따르길.', '', 28153),
(153630, 'koKR', '명예롭게 가라.', '', 28153),
(153629, 'koKR', '이 땅이 일어나... 너를 적대하리라...', '이 땅이 일어나... 너를 적대하리라...', 28153),
(153628, 'koKR', '안 돼! 네 머리를 가져가려 했는데...', '안 돼! 네 머리를 가져가려 했는데...', 28153),
(153627, 'koKR', '하찮은... 얼라이언스...', '하찮은... 얼라이언스...', 28153),
(153626, 'koKR', '오래 버티지 못할 것이다...', '오래 버티지 못할 것이다...', 28153),
(153625, 'koKR', '제국은... 살아남으리라...', '제국은... 살아남으리라...', 28153),
(153624, 'koKR', '우리는 계속 몰려올 것이다...', '우리는 계속 몰려올 것이다...', 28153),
(153623, 'koKR', '듣고 있다.', '', 28153),
(153622, 'koKR', '이걸로 끝이 아니다...', '이걸로 끝이 아니다...', 28153),
(153621, 'koKR', '너라면 언제나 환영이다.', '', 28153),
(153620, 'koKR', '호드를... 위하여.', '호드를... 위하여.', 28153),
(153619, 'koKR', '네 머리카락을 베어 상을 받을 것이다.', '네 머리카락을 베어 상을 받을 것이다.', 28153),
(153618, 'koKR', '우리보다 한 수 앞선다고 생각하나? 하!', '우리보다 한 수 앞선다고 생각하나? 하!', 28153),
(153617, 'koKR', '네 머리카락을 전리품으로 가져가겠다!', '네 머리카락을 전리품으로 가져가겠다!', 28153),
(153616, 'koKR', '우리를 모두 찾을 수는 없다!', '우리를 모두 찾을 수는 없다!', 28153),
(153615, 'koKR', '나와서 놀아보자고, 얼라이언스 애송이?', '나와서 놀아보자고, 얼라이언스 애송이?', 28153),
(153614, 'koKR', '이곳은 잔달라의 땅이다!', '이곳은 잔달라의 땅이다!', 28153),
(153613, 'koKR', '여기 온 것을 후회할 것이다!', '여기 온 것을 후회할 것이다!', 28153),
(153612, 'koKR', '이 땅은 네가 있을 곳이 아니다!', '이 땅은 네가 있을 곳이 아니다!', 28153),
(153611, 'koKR', '그럴 순 없죠. 우린 이 미개한 족속들과는 다르잖아요.', '그럴 순 없죠. 우린 이 미개한 족속들과는 다르잖아요.', 28153),
(153610, 'koKR', '당신 없이는 못 가요!', '당신 없이는 못 가요!', 28153),
(153609, 'koKR', '같이 가야 해요. 젠장!', '같이 가야 해요. 젠장!', 28153),
(153608, 'koKR', '혼자 두곤 못 가요!', '혼자 두곤 못 가요!', 28153),
(153607, 'koKR', '뭐 하는 거예요? 그러다 죽는다고요!', '뭐 하는 거예요? 그러다 죽는다고요!', 28153),
(153606, 'koKR', '가서 도움을 청해요! 저는 괜찮을 거예요.', '가서 도움을 청해요! 저는 괜찮을 거예요.', 28153),
(153605, 'koKR', '피하세요, 너무 늦었어요...', '피하세요, 너무 늦었어요...', 28153),
(153604, 'koKR', '도망쳐요...', '도망쳐요...', 28153),
(153603, 'koKR', '너를 지켜보고 있다.', '', 28153),
(153602, 'koKR', '다음에는 그 친구들도 포로로 잡히지 않도록 조심할 걸세. 뒷배를 봐 줄 자네 같은 우수한 영웅이 호드에 있어 천만다행이었네.', '', 28153),
(153601, 'koKR', '동맹에게 우리 도움이 필요하네. 포로로 잡힌 모양이더군. 가서 풀어 주게나.', '', 28153),
(153600, 'koKR', '흠, 이 정보 덕분에 확실히 얼라이언스보다 우위를 차지하게 됐네. 자네 수고는 보상받을 걸세.', '', 28153),
(153599, 'koKR', '첩자에 의하면 이 지역에 중요한 정보를 지닌 전령이 지나간다고 알려 왔네. 수단과 방법을 가리지 말고 정보를 가로채게.', '', 28153),
(153598, 'koKR', '로아께서 자네를 좋아하시는군. 좋은 일이야! 너무 자만하지만 말게나.', '', 28153),
(153597, 'koKR', '적이 다시 로아의 정원을 더럽히고 있네. 놈들에게 따끔한 교훈을 줘야 하네. 로아의 힘이 자네와 함께하기를!', '', 28153),
(153596, 'koKR', '전초기지에서 뵙죠. 반드시 답을 찾아야 합니다. 커다란 격변의 기운이 느껴지는군요.', '', 28153),
(153595, 'koKR', '정교한 작전은 아니었지만, 필요한 일이었네. 적의 눈을 계속 가려야 하니까. 잘했네.', '', 28153),
(153594, 'koKR', '얼라이언스가 보낸 첩자들이 어둠 속에서 우리 비밀을 빼내려 드는군. 놈들이 우리 계획을 알아내게 둘 순 없지. 처리하게.', '', 28153),
(153593, 'koKR', '잔달라 함대를 얻지 못하면 얼라이언스는 우릴 쓸어버릴 걸세.', '', 28153),
(153592, 'koKR', '얼라이언스가 우리 함대가 만들어질 때까지 기다려 줄 것 같나. 우리에겐 잔달라가 필요하네.', '', 28153),
(153591, 'koKR', '잔달라를 호드에 영입시키게, 영웅이여.', '', 28153),
(153590, 'koKR', '우리에겐 잔달라 함대가 필요하네.', '', 28153),
(153589, 'koKR', '대족장님의 뜻은 이루어지리라.', '', 28153),
(153588, 'koKR', '당신과 아이트웬이 있으니 계획이 실패할 리 없겠군요.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153587, 'koKR', '잔달라는 나를 별로 좋아하지 않는 것 같네.', '', 28153),
(153586, 'koKR', '호드의 대변자가 납시었군.', '', 28153),
(153585, 'koKR', '잔달라 함대는 호드에 합류해야만 하네. 반드시 성공하게.', '', 28153),
(153584, 'koKR', '', '이 용사는 줄과 저를 구하려고 스톰윈드에 맞섰어요. 이런 용맹한 자의 말은 들어 보셔야 하지 않을까요, 아버지.', 28153),
(153583, 'koKR', '폐하, 호드는 자기네 언데드 대족장을 위해 우리 해군을 훔치려는 것뿐입니다.', '', 28153),
(153582, 'koKR', '여기서 좋은 물건을 좀 얻었습니다. 어디서 났냐고는 묻지 마세요.', '여기서 좋은 물건을 좀 얻었습니다. 어디서 났냐고는 묻지 마세요.', 28153),
(153581, 'koKR', '나는 높은산에서 보급품을 가져오지.', '나는 높은산에서 보급품을 가져오지.', 28153),
(153580, 'koKR', '(아제로스의 상처로 이어지는 이벤트 보기)', '(아제로스의 상처로 이어지는 이벤트 보기)', 28153),
(153579, 'koKR', '<티탄 제어장치에 데이터 항목이 연달아 표시되어 있습니다. 그중 하나를 선택해 확인할 수 있습니다.>', '', 28153),
(153578, 'koKR', '불에 안 타는 속옷 입었겠지? 하하하!', '불에 안 타는 속옷 입었겠지? 하하하!', 28153),
(153577, 'koKR', '어이, 좀 화끈할 거야! 하하!', '어이, 좀 화끈할 거야! 하하!', 28153),
(153576, 'koKR', '하, 화끈하게 불태워 볼까!', '하, 화끈하게 불태워 볼까!', 28153),
(153575, 'koKR', '저 \"다이아몬드 드워프\"는 이 세계혼의 대변인일세. 상황이 보통 심각하지 않은 한 이렇게 끼어들 이가 아니라네.', '', 28153),
(153574, 'koKR', '', '오, 생각해 보세요. 다이아몬드 드워프가 우릴 아제로스 어디로든 보내 줄 거예요!', 28153),
(153573, 'koKR', '순간이동 다이아몬드 드워프가 강력한 선물까지 주고... 데려가도 됩니까?', '', 28153),
(153572, 'koKR', '마그니, 중요한 일이라는 건 짐작하지만, 쿨 티라스를 위해... 부디 서둘러주시오.', '', 28153),
(153571, 'koKR', '오게, 용사여. 아제로스가 손짓하네!', '', 28153),
(153570, 'koKR', '아, 귀환 장소를 여기로 해 뒀었지.', '아, 귀환 장소를 여기로 해 뒀었지. 제기랄.', 28153),
(153569, 'koKR', '나이를 먹으니 이 짓거리도 못 해 먹겠군. 난 여기서 나가겠어!', '나이를 먹으니 이 짓거리도 못 해 먹겠군. 난 여기서 나가겠어!', 28153),
(153568, 'koKR', '정신 똑바로 차리는 게 좋을 거다.', '정신 똑바로 차리는 게 좋을 거다.', 28153),
(153567, 'koKR', '하사관님, 제가... 앞으로 더 잘 하겠습니다.', '하사관님, 제가... 앞으로 더 잘 하겠습니다.', 28153),
(153566, 'koKR', '제임스 병사, 어렸을 때 부모님이 관심을 충분히 주지 않으시던가? 왜 이 알지도 못하는 땅에서 자네 꽁무니나 쫓게 만든 거지?', '제임스 병사, 어렸을 때 부모님이 관심을 충분히 주지 않으시던가? 왜 이 알지도 못하는 땅에서 자네 꽁무니나 쫓게 만든 거지?', 28153),
(153565, 'koKR', '하사관님... 저를 찾아 주셔서 감사합니다...', '하사관님... 저를 찾아 주셔서 감사합니다...', 28153),
(153564, 'koKR', '어서 움직입시다!', '어서 움직입시다!', 28153),
(153563, 'koKR', '이제 돌아가시죠. 웜베인 사령관님이 자세한 보고를 기다릴 겁니다.', '이제 돌아가시죠. 웜베인 사령관님이 자세한 보고를 기다릴 겁니다.', 28153),
(153562, 'koKR', '', '뾰족털 녀석들이 저를 죽이지는 못했죠. 이제 후회할 거예요.', 28153),
(153561, 'koKR', '', '돌아가면 다시 꾸며봐야겠어요. 엄니를 소재로 해볼까 하는데... 그걸 어디서 또 구하겠어요?$b$b<장난스레 웃는 딜>', 28153),
(153560, 'koKR', '', '일단 한 잔 걸치고, 집을 되찾아 고쳐야겠어요. 녀석들을 쫓아내 줘서 고마워요!', 28153),
(153559, 'koKR', '농장에 돌아가야 하니 오래 있을 수는 없겠네. 자네 덕에 뾰족털 녀석들과의 싸움에서 이겼으니, 시장이 여기 와서 같이 축하해달라 하더군.$b$b아주 잘 했네, 젊은이.', '', 28153),
(153558, 'koKR', '훌륭한 가시멧돼지 처리였습니다. 친구여!', '', 28153),
(153557, 'koKR', '그리 오래 있을 수는 없습니다. 저 농장 일꾼들을 수리하고 훼손된 밭을 복구해야 할 겁니다.$b$b하지만 중간중간 쉬는 것도 물론 중요하지요.', '', 28153),
(153556, 'koKR', '농장 일꾼을 자기방어 모드로 놔뒀습니다. 문제없을 겁니다.', '', 28153),
(153555, 'koKR', '가시멧돼지의 가시가 보이면 잘 챙기십시오. 의외로 유용하거든요. 얼마나 좋으면, 가시멧돼지들이 자기네들 가시를 가마솥에 넣어 삶기까지 하겠습니까?', '', 28153),
(153554, 'koKR', '북쪽에선 호드가, 서쪽에선 가시멧돼지가... 민병대를 더 믿을 수 있겠습니까?', '', 28153),
(153553, 'koKR', '롤프, 모르트, 스피프가 무사히 나왔어야 할 텐데...', '', 28153),
(153552, 'koKR', '', '정보원의 말에 따르면 우리 함대 없이는 당신네가 얼라이언스와의 전쟁에서 이길 수 없다는군요.\n\n그 말은... 제가 오늘 해야 할 더러운 일을 당신이 대신 처리해 줄 수 있다는 뜻으로 받아들여도 되겠습니까? 싫으면 마시고요!', 28153),
(153551, 'koKR', '', '저는 계속해서 졸라니와 탈란지 공주님께 항구는 문제없다고 말씀드렸습니다. 제 말을 들으셨냐고요? 아닙니다.$b$b다툼? 난투? 건달패? 당연히 있습니다. 하지만, 왕께서 신경 쓸 정도로 큰일은 없습니다.', 28153),
(153550, 'koKR', '원한다면 따라오게.', '원한다면 따라오게.', 28153),
(153549, 'koKR', '용사에게 보여줄 것이 있네. 이 땅을 도울 선물이기도 하지.', '', 28153),
(153548, 'koKR', '모두 침착하시오. 이쪽은 전 아이언포지 국왕 마그니 브론즈비어드요. 지금은 아제로스의 대변자이지.', '', 28153),
(153547, 'koKR', '이런 건... 처음 봅니다.', '', 28153),
(153546, 'koKR', '마법인가!', '', 28153),
(153545, 'koKR', '', '다이아몬드 드워프?!', 28153),
(153544, 'koKR', '이제 심장의 힘을 방출하게!', '', 28153),
(153543, 'koKR', '무서운 소식이군요. 총사령관님께 보고하는 것이 좋겠습니다.', '무서운 소식이군요. 총사령관님께 보고하는 것이 좋겠습니다.', 28153),
(153542, 'koKR', '코르테크는 미쳤어! 반드시 막아야만 해!', '코르테크는 미쳤어! 반드시 막아야만 해!', 28153),
(153541, 'koKR', '코르테크는 평화로운 상황에 점점 싫증을 냈네. 세스랄리스 님의 희생을 배신하고, 어리석게도 열쇠를 하나로 모아 크트락시를 풀어 자기 적들을 치려 하네.', '코르테크는 평화로운 상황에 점점 싫증을 냈네. 세스랄리스 님의 희생을 배신하고, 어리석게도 열쇠를 하나로 모아 크트락시를 풀어 자기 적들을 치려 하네.', 28153),
(153540, 'koKR', '위대한 현자 술디스가 코르테크와 내 힘을 빌어 쓰러진 크트락시를 봉인할 마법 보호막을 세웠네. 우리는 맹세했지. 다시는 크트락시 같은 끔찍한 힘이 세상에 나오지 않게 하겠다고.', '위대한 현자 술디스가 코르테크와 내 힘을 빌어 쓰러진 크트락시를 봉인할 마법 보호막을 세웠네. 우리는 맹세했지. 다시는 크트락시 같은 끔찍한 힘이 세상에 나오지 않게 하겠다고.', 28153),
(153539, 'koKR', '파괴에서 분출된 엄청난 힘이 우리 땅을 영원히 바꿔놓았네.', '파괴에서 분출된 엄청난 힘이 우리 땅을 영원히 바꿔놓았네.', 28153),
(153538, 'koKR', '우리의 로아께서 나서지 않았다면 모두 죽었을 걸세. 세스랄리스 님은 자신을 희생해 크트락시를 제압했어. 하지만 이미 크트락시가 이 땅 중앙의 고대 피라미드를 파괴하고 난 뒤였네.', '우리의 로아께서 나서지 않았다면 모두 죽었을 걸세. 세스랄리스 님은 자신을 희생해 크트락시를 제압했어. 하지만 이미 크트락시가 이 땅 중앙의 고대 피라미드를 파괴하고 난 뒤였네.', 28153),
(153537, 'koKR', '아주 먼 옛날, 사막화가 진행되기 전에 끔찍한 크트락시 전쟁인도자가 우리 땅에 내려왔네. 그리고는 트롤이든 세스락이든 자신의 앞을 막는 자는 모두 살해하기 시작했지.', '아주 먼 옛날, 사막화가 진행되기 전에 끔찍한 크트락시 전쟁인도자가 우리 땅에 내려왔네. 그리고는 트롤이든 세스락이든 자신의 앞을 막는 자는 모두 살해하기 시작했지.', 28153),
(153536, 'koKR', '', '호드를 바짝 경계해야겠어요. 계속 광장을 공격해 대니까요.', 28153),
(153535, 'koKR', '', '나중에라도 우리 마을을 습격하려는 것이 보이면, 알려주시면 고맙겠어요.', 28153),
(153534, 'koKR', '', '모두 제가 잘 이끌어줄 것을 믿고 있어요. 실망시키지 않을 거예요!', 28153),
(153533, 'koKR', '', '다들 안전해 보이네요... 일단은.', 28153),
(153532, 'koKR', '그건 그냥 돌이 아니라 열쇠일세. 거대하고 무시무시한 힘을 가두기 위해 사용한 열쇠 중 하나지.', '그건 그냥 돌이 아니라 열쇠일세. 거대하고 무시무시한 힘을 가두기 위해 사용한 열쇠 중 하나지.', 28153),
(153531, 'koKR', '오! 무슨 돌 같은 게 안에 있어요.', '오! 무슨 돌 같은 게 안에 있어요.', 28153),
(153530, 'koKR', '\"조심하오, 바다의 딸!\"', '\"조심하오, 바다의 딸!\"', 28153),
