(153505, 'koKR', '\"조심하오, 바다의 딸을.\"', '\"조심하오, 바다의 딸을.\"', 28153),
(153504, 'koKR', '좋은 하루 보내십시오, $r님.', '', 28153),
(153502, 'koKR', '당신 주머니에 아무것도 없습니까?', '당신 주머니에 아무것도 없습니까?', 28153),
(153501, 'koKR', '나는 여기 머물면서 방어하겠네. 다시 한 번 고맙네.', '나는 여기 머물면서 방어하겠네. 다시 한 번 고맙네.', 28153),
(153500, 'koKR', '', '', 28153),
(153499, 'koKR', '', '하수인들이여! 놈들을 죽여라!', 28153),
(153498, 'koKR', '당신과 하사관님이 아니었다면 저는 무사하지 못했을 겁니다. 다시 한번 감사드립니다.', '당신과 하사관님이 아니었다면 저는 무사하지 못했을 겁니다. 다시 한번 감사드립니다.', 28153),
(153497, 'koKR', '', '줄 님께 말씀드리죠. 라스타칸 님께 알려야 할지 그분이 결정하실 겁니다.', 28153),
(153496, 'koKR', '놈들을 빠르게 해치우게!', '', 28153),
(153495, 'koKR', '부두에 도착할 때까지는 다신 멈추지 않을 걸세. 준비되면 말하게.', '', 28153),
(153494, 'koKR', '죽고 싶은 겐가?', '', 28153),
(153493, 'koKR', '우리까지 잡히게 할 셈인가?', '', 28153),
(153492, 'koKR', '우릴 죽일 작정인가?', '', 28153),
(153491, 'koKR', '어이, 어이! 어디 가나?!', '', 28153),
(153490, 'koKR', '이리로 오게!', '', 28153),
(153489, 'koKR', '빛이시여, $n 님이시군요! 저는 사원으로 가겠습니다. 여긴 위험합니다.', '', 28153),
(153488, 'koKR', '그리고 한쪽을 선택하는 일이 없길 기도하게.', '', 28153),
(153487, 'koKR', '충성심과 명예의 차이를 분명히 알아두게.', '', 28153),
(153486, 'koKR', '그게 무슨 뜻이죠?', '그게 무슨 뜻이죠?', 28153),
(153485, 'koKR', '실바나스가 한 일이 있으니, 나는 그녀의 호드로 다시는 돌아가지 않을 걸세.', '', 28153),
(153484, 'koKR', '나를 오그리마로, 대족장에게로 데려갈 수 있다고 생각했다면, 그건 착각일세.', '', 28153),
(153483, 'koKR', '투자개발회사에 전략적으로 한 방 먹여줄 때가 왔습니다!', '', 28153),
(153482, 'koKR', '말만 하게.', '', 28153),
(153477, 'koKR', '', '아직 죽을 때가 아닙니다. 할 일이 남았습니다.', 28153),
(153476, 'koKR', '', '브원삼디 님이 그렇게 보고 싶으십니까?', 28153),
(153475, 'koKR', '', '엄살 피우지 마십시오.', 28153),
(153474, 'koKR', '', '일어나십시오. 아직 끝이 아닙니다.', 28153),
(153473, 'koKR', '', '제 로아께서 당신을 쓰러지게 두진 않으실 겁니다.', 28153),
(153472, 'koKR', '정보가 잘못된 것 같습니다. 모든 세스락이 나쁜 건 아닌 것 같군요.', '정보가 잘못된 것 같습니다. 모든 세스락이 나쁜 건 아닌 것 같군요.', 28153),
(153471, 'koKR', '받은 만큼 되돌려 주지!', '받은 만큼 되돌려 주지!', 28153),
(153470, 'koKR', '', '새로운 트롤 제국의 시대가 열릴 것이다. 기나긴 정체기는 이제 끝났다!', 28153),
(153469, 'koKR', '', '줄 님은 이날을 예견하셨다. 일어나라... 일어나라, 피의 사제들이여. 이 세계에 도래할 다음 시대를 준비해라!', 28153),
(153468, 'koKR', '안 돼! 안 돼...', '안 돼! 안 돼...', 28153),
(153467, 'koKR', '감히 내 몫을 가져가다니...', '감히 내 몫을 가져가다니...', 28153),
(153466, 'koKR', '네 차례가 올 거다...', '네 차례가 올 거다...', 28153),
(153465, 'koKR', '영웅들이여, 날 따르게!', '', 28153),
(153464, 'koKR', '언젠가... 널...', '언젠가... 널...', 28153),
(153463, 'koKR', '너는 죽은 목숨이다! 너희 모두!', '너는 죽은 목숨이다! 너희 모두!', 28153),
(153462, 'koKR', '내 몫을 가져갈 수 있을 것 같은가?', '내 몫을 가져갈 수 있을 것 같은가?', 28153),
(153461, 'koKR', '반역자! 목을 베어주마!', '반역자! 목을 베어주마!', 28153),
(153460, 'koKR', '너희 모두 배신자다!', '너희 모두 배신자다!', 28153),
(153459, 'koKR', '유도라 선장님... 저희를 승리로...', '', 28153),
(153458, 'koKR', '신선한 고기? 시궁쥐단! 식사 시간이다!', '', 28153),
(153457, 'koKR', '오늘, 우렁찬 전투의 함성과 무기 부딪치는 소리를 위대한 로아께서 들으실 것이다! 쓰러진 자들도... 내세에서 함께하리라.', '', 28153),
(153456, 'koKR', '그녀에게 명예로운 죽음을...', '', 28153),
(153455, 'koKR', '저자에게 명예로운 죽음을...', '', 28153),
(153454, 'koKR', '아아아아?!', '', 28153),
(153453, 'koKR', '내세로 가거라...', '', 28153),
(153452, 'koKR', '오늘은 로아의 축복을 받지 못하였구나.', '', 28153),
(153451, 'koKR', '잔달라를 위하여!', '', 28153),
(153450, 'koKR', '낙찰! 무지개비늘 검이 281골드에 낙찰되었습니다! 이 칼이라면 용감하게 적에 맞설 수 있답니다.', '', 28153),
(153449, 'koKR', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t 당신은 |cFFFF0000|Hspell:260838|h[추적 미사일]|h|r의 대상이 되었습니다!', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t 당신은 |cFFFF0000|Hspell:260838|h[추적 미사일]|h|r의 대상이 되었습니다!', 28153),
(153448, 'koKR', '쿨 티라스를 위한 날입니다!', '', 28153),
(153447, 'koKR', '오늘 바닥에 귀와 코가 잔뜩 쌓이겠군요.', '', 28153),
(153446, 'koKR', '끝날 때까지 끝난 게 아니랍니다.', '', 28153),
(153445, 'koKR', '자, 조용! 아직 싸움이 한창입니다!', '', 28153),
(153444, 'koKR', '자자, 이제 피를 보게 될 겁니다! 조금만 참으십시오. 하하.', '', 28153),
(153443, 'koKR', '낙찰! 유령 기념품이 18골드에 낙찰되었습니다! 솔직히, 저라면 땡전 한 닢도 아깝겠지만, 제 돈 아니면 괜찮습니다!', '', 28153),
(153442, 'koKR', '자, 자, 좋아요. 아주 좋습니다.', '', 28153),
(153441, 'koKR', '그런 최후는... 진정한 쿨 티란과는 거리가 멀군요.', '', 28153),
(153440, 'koKR', '아이고, 저런!', '', 28153),
(153439, 'koKR', '쿨 티라스를 위한 밤입니다!', '', 28153),
(153438, 'koKR', '정정당당한 싸움과는 거리가 멀 겁니다. 알아서 조심하시길! 자, 준비됐습니까?', '', 28153),
(153437, 'koKR', '마지막까지 남는 자만이 그 영예를 안게 됩니다.', '', 28153),
(153436, 'koKR', '여러분! 오늘 우리는 이 좀도둑과 불한당과 버러지들 중에 누가 진정한 쿨 티란으로 불릴 자격을 얻는지 보기 위해 모였습니다!', '', 28153),
(153435, 'koKR', '낙찰! 커다란 사랑의 로켓이 1,412골드에 낙찰되었습니다! 분명 마을에서 화제가 될 겁니다!', '', 28153),
(153434, 'koKR', '낙찰! 무쌍의 견갑이 앞에 있는 청년에게 756골드에 낙찰되었습니다! 당신이 착용하기엔 힘들어보이지만, 뭐 어떻습니까!', '', 28153),
(153433, 'koKR', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t 아제로크가 |cFFFF0000|Hspell:257597|h[아제라이트 주입]|h|r을 시전합니다!', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t 아제로크가 |cFFFF0000|Hspell:257597|h[아제라이트 주입]|h|r을 시전합니다!', 28153),
(153432, 'koKR', '반역자다! 잡아라!', '', 28153),
(153431, 'koKR', '절대 코르테크가 열쇠를 손에 넣어서는 안 되네. 가세, 앞쪽에 우리 사원이 있네.', '', 28153),
(153430, 'koKR', '난 당시 막 잡혀서 들어온 어떤 포로의 주머니에 열쇠를 몰래 집어넣었지. 이름이\"제임스\"였던 것 같네.', '', 28153),
(153429, 'koKR', '그 멍청이들! 놈들은 날 잡아 수색했지만, 그건 이미 내가 아무도 예상치 못한 곳에 열쇠를 숨긴 뒤였지.', '', 28153),
(153428, 'koKR', '하지만 코르테크가 우릴 배신했고, 술디스는 살해당했네. 이제 코르테크와 그를 추종하는 부정한 자들이 나와 내 열쇠를 노리네.', '', 28153),
(153427, 'koKR', '오래전, 우리 셋, 코르테크, 술디스, 그리고 나는 삼위일체로 백성을 이끌었지. 로아께서는 우리를 믿고 모래 아래 잠든 고대의 사악한 힘을 봉인한 열쇠 세 개를 맡기셨네.', '', 28153),
(153426, 'koKR', '우리 사원은 부정한 자들에 맞서는 최후의 보루일세.', '', 28153),
(153425, 'koKR', '', '네, 그렇습니다. 사소한 문제가 생긴 것은 사실입니다만, 폐하께서 걱정할 만한 일은 전혀 아닙니다.', 28153),
(153424, 'koKR', '', '로아와 거래하던 시절은 이제 지나갔다. 피를 흘릴 시간이 왔노라!', 28153),
(153423, 'koKR', '', '사소한 범죄 같은 것으로 걱정하지 마십시오. 해결해야 할 훨씬 중요한 문제가 있지 않습니까.', 28153),
(153421, 'koKR', '', '입맛에 맞았으면 좋겠구려!', 28153),
(153419, 'koKR', '', '드시구려. 사람을 굶겨서 내보낼 순 없지 않겠수, 안 그러우?', 28153),
(153418, 'koKR', '', '아, 정말 완벽해!', 28153),
(153417, 'koKR', '', '잠시만 기다려 보시우. 당신에게 줄 게 있으니.', 28153),
(153416, 'koKR', '잘했네! 자네의 활약에 잔달라 제국이 흔들릴 걸세.', '', 28153),
(153415, 'koKR', '저는 바람의 지배자 파쿠를 선택하겠습니다.', '저는 바람의 지배자 파쿠를 선택하겠습니다.', 28153),
(153414, 'koKR', '저는 무리의 지도자 공크를 선택하겠습니다.', '저는 무리의 지도자 공크를 선택하겠습니다.', 28153),
(153413, 'koKR', '잔달라가 계속 야수를 훈련하고 있네. 자신들을 지켜줄 거라 믿는 모양인데, 놈들의 착각임을 보여주게나!', '', 28153),
(153412, 'koKR', '마침내 우리가 스트롬가드를 되찾았다.', '', 28153),
(153411, 'koKR', '죽어라, 잡것!', '', 28153),
(153410, 'koKR', '이제 네 주제를 알겠지.', '', 28153),
(153409, 'koKR', '아무도 네놈을 찾지 않을 것이다.', '', 28153),
(153408, 'koKR', '언젠가는... 스트롬가드가 다시 얼라이언스의 차지가 될 것이다.', '', 28153),
(153407, 'koKR', '호드에 죽음의 비를 내려라!', '', 28153),
(153406, 'koKR', '3사단, 발사!', '', 28153),
(153405, 'koKR', '줄다자르에서 이곳의 대표 로아를 바꾸고 싶습니다.', '줄다자르에서 이곳의 대표 로아를 바꾸고 싶습니다.', 28153),
(153404, 'koKR', '성루 병사여, 화살을 쏴라!', '', 28153),
(153403, 'koKR', '과거의 메아리여, 일어나소서!', '', 28153),
(153402, 'koKR', '아라소르의 영혼이 널 파괴하리라!', '', 28153),
(153401, 'koKR', '악이 숨을 수 있는 곳은 없네. 이런 땅에서조차 말일세. 수고했네.', '', 28153),
(153400, 'koKR', '선조들이여, 일어나 당신들의 안식처를 보호하소서.', '', 28153),
(153399, 'koKR', '네 족속을 수없이 죽였다. 너라고 다를 것 같으냐.', '', 28153),
(153398, 'koKR', '잔달라 제국이 다시 승리했다! 잘했다, 호드의 용사여.', '', 28153),
(153397, 'koKR', '이 야만의 땅에 악이 창궐했네. 찾아서 몰아내게!', '', 28153),
(153396, 'koKR', '밀림에서 가장 강력한 생물 중 하나가 이 지역을 위협하고 있다. 찾아 해치워라!', '', 28153),
(153395, 'koKR', '정의는 언제나 승리한다.', '', 28153),
(153394, 'koKR', '정화했노라!', '', 28153),
(153393, 'koKR', '네 운명이 결정되었다.', '', 28153),
(153392, 'koKR', '심판을 내렸노라.', '', 28153),
(153391, 'koKR', '스트롬가드는 함락되었지만, 얼라이언스는 절대 굴하지 않는다.', '', 28153),
(153390, 'koKR', '빛의 힘으로!', '', 28153),
(153389, 'koKR', '빛에게서 도망치려느냐, 겁쟁이들!', '', 28153),
(153388, 'koKR', '빛이 징벌하리라!', '', 28153),
(153387, 'koKR', '위협이 하나 더 사라졌고, 얼라이언스의 승리가 하나 더 추가됐네!', '', 28153),
(153386, 'koKR', '빛은 승리하리라!', '', 28153),
(153385, 'koKR', '', '제가 최초의 기록가예요. 폐하께서 저를 선택하신 다음 우리 역사를 돌에 새기도록 하셨죠. 영원히 남을 수 있도록요.', 28153),
(153384, 'koKR', '빛이 너희를 정화하리라!', '', 28153),
(153383, 'koKR', '백성들이 너를 잔달라의 용사로 알게 되리라. 잘했다!', '', 28153),
(153382, 'koKR', '빛의 세례를 받아라!', '', 28153),
(153381, 'koKR', '빛을 위하여!', '', 28153),
(153380, 'koKR', '사악한 존재가 죄어오는 덩굴처럼 자연스럽게 이 땅에 나타났네. 악을 잘라버리고 우리 병사들을 보호해 주게.', '', 28153),
(153379, 'koKR', '적의 손에 백성이 다치게 둘 수는 없다. 놈들을 박살 내라!', '', 28153),
(153378, 'koKR', '길을 확보한 덕분에 이 땅에서 잔달라를 대적하는 일에 더 집중할 수 있게 됐네. 고맙네, 용사여.', '', 28153),
(153377, 'koKR', '잔달라 제국의 이름 아래 또 다른 적이 쓰러지는구나.', '', 28153),
(153376, 'koKR', '저 고약한 생명체가 우리 군대를 위협하고 있네. 놈을 해치우게나. 얼라이언스를 위하여!', '', 28153),
(153375, 'koKR', '영토 내의 위협을 용납하지 않겠다. 놈들을 정복해라!', '', 28153),
(153374, 'koKR', '준비되면 세발차에 올라타라고.', '', 28153),
(153372, 'koKR', '', '이 나가들은 뭔가를 두려워하고 있습니다. 놈들을 몰아붙이는 무언가가 있어요. 단순히 아즈샤라 여왕에 대한 충성심이 아닙니다.', 28153),
(153371, 'koKR', '', '반가워요.', 28153),
(153370, 'koKR', '겨우 이 정도냐? 몸풀기도 안 되겠군!', '', 28153),
(153369, 'koKR', '참 재밌군!', '', 28153),
(153368, 'koKR', '다시는 그러지 말게', '', 28153),
(153367, 'koKR', '저승의 조상님들께 안부나 전해주라고!', '', 28153),
(153366, 'koKR', '어디 두고 보자!', '', 28153),
(153365, 'koKR', '이런 게 마무리 일격이지.', '', 28153),
(153364, 'koKR', '하하! 이게 우리 방식이지!', '', 28153),
(153363, 'koKR', '꺼져라!', '', 28153),
(153362, 'koKR', '카즈 모단을 위하여!', '', 28153),
(153361, 'koKR', '선물이다!', '', 28153),
(153360, 'koKR', '네놈도 한 대.', '', 28153),
(153359, 'koKR', '어이, 잘 받아라!', '', 28153),
(153357, 'koKR', '네놈들 싸움도 여기서 끝이다!', '', 28153),
(153351, 'koKR', '마그니, 아제로스가 제게 뭘 주려는 거죠?', '마그니, 아제로스가 제게 뭘 주려는 거죠?', 28153),
(153350, 'koKR', '저 고릴라를 물리친 덕분에 호드에 전력을 집중할 수 있겠군. 잘하셨소.', '', 28153),
(153349, 'koKR', '저 고릴라들은 카자마이트의 정수를 흡수하여 놀라운 지능을 얻었소. 놈들이 이 협곡을 벗어나게 해서는 안 되오.', '', 28153),
(153348, 'koKR', 'A.T.O.M.I.K. 발사 감지', 'A.T.O.M.I.K. 발사 감지', 28153),
(153347, 'koKR', '호드가 우리를 포로로 만들 수 있다고 생각하다니 정말 갈 데까지 갔구먼. 어쨌든 자네 덕에 주민들이 자유로워졌네. 잘했네!', '', 28153),
(153346, 'koKR', '동료가 저 밖에 있는 걸 알고도 가만히 있을 수는 없습니다.', '동료가 저 밖에 있는 걸 알고도 가만히 있을 수는 없습니다.', 28153),
(153345, 'koKR', '저들은 우리가 다가오는 걸 절대 눈치채지 못할 걸세. 하! 고맙네, 용사여.', '', 28153),
(153344, 'koKR', '호드가 줄다자르에 있는 우리 위치를 알아낼 수 있다고 생각하는 모양이지만, 잘못 짚은 걸세! 놈들의 귀를 먹게 하고, 얼라이언스가 굳건하다는 메시지를 보내게.', '', 28153),
(153343, 'koKR', '다시는 열쇠 없이 저 망할 것에 타지 않을 겁니다!', '다시는 열쇠 없이 저 망할 것에 타지 않을 겁니다!', 28153),
(153342, 'koKR', '일 분만 더 있었으면 내 가만 안 있었을 겁니다!', '일 분만 더 있었으면 내 가만 안 있었을 겁니다!', 28153),
(153341, 'koKR', '터르가덴 님께서 이 깡통 속에 우릴 이렇게 오래 버려둔 이유가 뭐랍니까? 젠장!', '터르가덴 님께서 이 깡통 속에 우릴 이렇게 오래 버려둔 이유가 뭐랍니까? 젠장!', 28153),
(153340, 'koKR', '라그나로스의 불바닥보다 저기가 더 뜨겁단 말입니다!', '라그나로스의 불바닥보다 저기가 더 뜨겁단 말입니다!', 28153),
(153339, 'koKR', '웜베인 사령관에게 전령을 보내 이 지역을 확보했다고 알려야겠군. 도와줘서 고맙네, $n.', '', 28153),
(153338, 'koKR', '당연한 소릴!', '', 28153),
(153337, 'koKR', '녀석들, 잔뜩 겁먹었겠군!', '', 28153),
(153336, 'koKR', '불의 땅의 힘을 끌어와서 소환하고 있지만, 위험할 일은 전혀 없네.', '', 28153),
(153335, 'koKR', '걱정 꽉 붙들어 매시게, 테일린. 내가 마술사 영주 타우릿산처럼 바보인 줄 아나.', '', 28153),
(153334, 'koKR', '엔빌테인, 신중히 소환하게나.', '', 28153),
(153333, 'koKR', '훌륭하게 소환했군, 친구. $n, 자네가 조종할 수 있을 걸세. 호드 놈들에게 검은무쇠 드워프를 건드리면 어떻게 되는지 보여주게!', '', 28153),
(153332, 'koKR', '$C|1이여;여;, 그 바위를 불안정한 용암에 넣게. 그리고 준비하게나.', '', 28153),
(153331, 'koKR', '격전의 스트롬가드 전투가 시작되었습니다!', '', 28153),
(153330, 'koKR', '격전의 스트롬가드 전투 시작 30초 전입니다.', '', 28153),
(153329, 'koKR', '그럼, 문제될 것 없지 않나.', '', 28153),
(153328, 'koKR', '잠깐, 열쇠를 자네가 갖고 있었나?', '', 28153),
(153327, 'koKR', '우리 주술사들이 아직 굴착기에서 나오지 못했네. 어쩐지 뭔가 빠뜨린 것 같더라니.', '', 28153),
(153326, 'koKR', '이미 여기서 잘 진행중일세. 뭐, 빠뜨린 게 있나?', '', 28153),
(153325, 'koKR', '우리의 막강한 힘은 상상도 못할 것이다, 애송아.', '', 28153),
(153324, 'koKR', '<안으로 손을 뻗어 건물같이 느껴지는 뭔가를 꺼냅니다.>', '<안으로 손을 뻗어 건물같이 느껴지는 뭔가를 꺼냅니다.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153323, 'koKR', '<안으로 손을 뻗어 뭔가를 꺼냅니다.>', '<안으로 손을 뻗어 뭔가를 꺼냅니다.>', 28153),
(153322, 'koKR', '<눈 앞에 웜홀이 펼쳐져 있습니다. 이걸 건물 생성에 이용할 방법이 있을 것 같습니다.>', '', 28153),
(153321, 'koKR', '내 인내심을 시험하지 마라, 벌레야. 죽어라.', '', 28153),
(153320, 'koKR', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_CTHUN.BLP:20|t%s|1이;가; |cFFFF0000|Hspell:264382|h[안광]|h|r을 시전합니다!', '저 멀리 투영체가 나타납니다...', 28153),
(153319, 'koKR', '바다는 저희 고향입니다. 무언가가 바다에서 우릴 밀어내고 있습니다. 좀 도와주십시오!', '', 28153),
(153318, 'koKR', '탐구자를 만나시겠죠? 믿을 만한 친구들이니, 거기는 안전할 겁니다.', '', 28153),
(153317, 'koKR', '배들이 사라졌습니다. 갑자기 폭풍이 불어왔죠. 다른 이들은 무서워서 바다로 못 나가고 있습니다.', '', 28153),
(153316, 'koKR', '해안에 이상한 일이 일어난다는 소문이 떠돌고 있습니다.', '', 28153),
(153315, 'koKR', '맡겨 두게.', '', 28153),
(153314, 'koKR', '그리고, 제이나 님을 부탁드려요.', '', 28153),
(153313, 'koKR', '쿨 티라스에 작전 기지를 세우세요. 계획이 실패해서는 안 됩니다.', '', 28153),
(153312, 'koKR', '7군단 함선을 호위로 데려가시죠.', '', 28153),
(153311, 'koKR', '하. 끄떡없다네.', '', 28153),
(153310, 'koKR', '바다가 너를 거부하리라. 네가 동포들에게 그랬듯.', '', 28153),
(153309, 'koKR', '네놈은 증오와 고통 그 자체로구나.', '', 28153),
(153308, 'koKR', '폭풍이 깨어나는 소리를 들어라. 이것이 너의 최후다.', '', 28153),
(153307, 'koKR', '두려워 말아라. 네 심판의 때가 왔노라.', '', 28153),
(153306, 'koKR', '겐 님... 배멀미는 안 하시죠?', '', 28153),
(153305, 'koKR', '우리 동포가 울부짖는 소리가 들리느냐? 이제 네 차례다.', '', 28153),
(153304, 'koKR', '너에게 구원은 없다.', '', 28153),
(153303, 'koKR', '네가 자초한 일이다.', '', 28153),
(153302, 'koKR', '네 영혼이 영원히 방황하기를.', '', 28153),
(153301, 'koKR', '', '내 손에 무기만 쥐어지는 날에는...', 28153),
(153300, 'koKR', '', '녀석들이 저를 죽이진 못했죠. 그게 첫 번째 실수였어요.', 28153),
(153299, 'koKR', '', '녀석들, 제 농장을 망쳐놓고 겁도 없이 저를 납치하기까지 했어요. 가만히 놔둘 수 없습니다!', 28153),
(153298, 'koKR', '이 위기를 해결하기 전까진 떠나지 않을 겁니다!', '이 위기를 해결하기 전까진 떠나지 않을 겁니다!', 28153),
(153297, 'koKR', '녀석들은 이제 대가를 치를 겁니다!', '녀석들은 이제 대가를 치를 겁니다!', 28153),
(153296, 'koKR', '이 가시멧돼지들에겐 빚진 게 많지!', '이 가시멧돼지들에겐 빚진 게 많지!', 28153),
(153295, 'koKR', '', '가끔 들려서 거래해 주세요.', 28153),
(153294, 'koKR', '', '겨우 풀려났군요! 이 역겨운 돼지들, 내 농장을 망쳐놓으면 어떻게 되는지 똑똑히 알려주죠!', 28153),
(153293, 'koKR', '이야, 겨우 깨어나셨군요.', '', 28153),
(153292, 'koKR', '조심... 하오... 바다의 딸을... 흠흠...', '', 28153),
(153291, 'koKR', '그... 그거 치우십시오. 저는 그저... 술통에서 익사하고 싶을 뿐이라고요! *딸꾹*', '그... 그거 치우십시오. 저는 그저... 술통에서 익사하고 싶을 뿐이라고요! *딸꾹*', 28153),
(153290, 'koKR', '여동생 남편이 넉 달 동안 항해를 떠나기 전에 여동생에게 바다 줄기를 주었습니다. 하지만 그 줄기가 사흘 만에 시들었지요. 여동생은 슬픔에 잠겼지만, 비극을 미리 알았던 덕분에 아이들을 위해 돈을 저축할 수 있었습니다.', '여동생 남편이 넉 달 동안 항해를 떠나기 전에 여동생에게 바다 줄기를 주었습니다. 하지만 그 줄기가 사흘 만에 시들었지요. 여동생은 슬픔에 잠겼지만, 비극을 미리 알았던 덕분에 아이들을 위해 돈을 저축할 수 있었습니다.', 28153),
(153289, 'koKR', '위층에 간이침대가 있고, 지하실에는 장비를 둘 공간이 있습니다.\n\n누추하지만 마녀들이 득실대는 밖에서 자는 것보다는 나을 겁니다.', '위층에 간이침대가 있고, 지하실에는 장비를 둘 공간이 있습니다. 누추하지만 마녀들이 득실대는 밖에서 자는 것보다는 나을 겁니다.', 28153),
(153288, 'koKR', '어떤 선원은 저것들이 불운을 의미한다고 생각합니다. 운명을 점쳐 본다고나 할까요? 또 어떤 선원은 자기가 사랑하는 사람이 나쁜 소식을 기다리지 않아도 되기를 바라고요. 저는 어느 쪽도 상관없습니다.', '어떤 선원은 저것들이 불운을 의미한다고 생각합니다. 운명을 점쳐 본다고나 할까요? 또 어떤 선원은 자기가 사랑하는 사람이 나쁜 소식을 기다리지 않아도 되기를 바라고요. 저는 어느 쪽도 상관없습니다.', 28153),
(153287, 'koKR', '잊지 마라. 나무가 버티는 한 우리도 버텨야 한다. 여기서 목숨을 버려서는 안 된다.', '', 28153),
(153286, 'koKR', '동족을 찾으러 가자꾸나. 힘을 합치면 드러스트바를 괴롭히는 문제를 조금이나마 해결할 수 있을지 모르잖니.', '', 28153),
(153285, 'koKR', '', '하지만!', 28153),
(153284, 'koKR', '저 숲에서 중요한 것은 모두 구했단다. 버섯전사의 공격이 없었다면 남쪽의 타락이 우리에게까지 덮쳤을 거다.', '', 28153),
(153283, 'koKR', '', '간다고요? 어디로요? 잿빛나무 숲은 우리 집이에요, 모르윈 님. 숲이 포자로 뒤덮였다고요. 그냥 떠날 수는 없어요!', 28153),
(153282, 'koKR', '잘했다, 아말리. 이제 가야한다.', '', 28153),
(153278, 'koKR', '바다 줄기에 관해 얘기해주실 수 있습니까?', '바다 줄기에 관해 얘기해주실 수 있습니까?', 28153),
(153277, 'koKR', '북치기', '북치기', 28153),
(153276, 'koKR', '|cFF0000FF(퀘스트)|r 줄다자르로 갑시다.', '|cFF0000FF(퀘스트)|r 줄다자르로 갑시다.', 28153),
(153275, 'koKR', '아, 힘이 돌아오는군!', '', 28153),
(153274, 'koKR', '여기는 조용했습니다. 그러다 폭풍이 덮쳤고, 다른 탐구자는 돌아오지 않았지요. 저 밖에서는 무슨 일이 벌어지고 있습니까?', '', 28153),
(153273, 'koKR', '진심으로 감사드립니다. 여기, 약소하나마 도움이 될 겁니다. 저는 이제 여길 떠나야 합니다, 그럼 안녕히!', '', 28153),
(153272, 'koKR', '세상에, 제게 문제가 생긴 것 같습니다. 부디 은혜를 베풀어 도움의 손길을 주십시오.', '', 28153),
(153271, 'koKR', '아아, 고마워요. 참 친절하시네요. 여기 약소하지만 보답이에요. 그럼 안녕!', '아아, 고마워요. 참 친절하시네요. 여기 약소하지만 보답이에요. 그럼 안녕!', 28153),
(153270, 'koKR', '', '저기요! 저 좀 꺼내주세요! 홀로 갇혀 있어요. 이 절망적인 기분 알아요?', 28153),
(153269, 'koKR', '자네도 알겠지만 내 아제라이트를 전부 줄 수는 없는 일이지. 구해준 보답으로는 이거면 충분할 게야. 이제 가던 길 마저 가도록!', '', 28153),
(153268, 'koKR', '어이, 거기. 나를 이 망할 것에서 좀 꺼내주겠나?', '', 28153),
(153267, 'koKR', '봐요, 이건 그냥 의상이라고요! 보여요? 만져 보라니까요!$b$b이제 저 좀 내보내달라고 얘기해 주시겠어요? 이건 그냥 장난이었어요! 들창코가 진짜로 스톰윈드를 위협하는 게 아니라니까요!', '봐요, 이건 그냥 의상이라고요! 보여요? 만져 보라니까요!$b$b이제 저 좀 내보내달라고 얘기해 주시겠어요? 이건 그냥 장난이었어요! 들창코가 진짜로 스톰윈드를 위협하는 게 아니라니까요!', 28153),
(153266, 'koKR', '', '감사해요! 제 아제라이트를 기대하셨겠죠? 당연히 드려 마땅하죠.', 28153),
(153265, 'koKR', '', '어이, 거기요! 여기서 저 좀 꺼내주시겠어요?', 28153),
(153264, 'koKR', '', '제가 자초한 일이겠죠.', 28153),
(153263, 'koKR', '', '피할 생각은 없습니다...', 28153),
(153262, 'koKR', '우... 우리를 끝장내러 온 건가!', '', 28153),
(153261, 'koKR', '이 살인자!', '이 살인자!', 28153),
(153260, 'koKR', '배신자!', '배신자!', 28153),
(153259, 'koKR', '봐요, 바다의 딸이에요!', '', 28153),
(153258, 'koKR', '', '여군주 제이나 님... 정말... 그분인가요?', 28153),
(153257, 'koKR', '', '이리 오렴, 집으로 들어가자. 어서!', 28153),
(153256, 'koKR', '엄마, 저 언니는 누구예요?', '엄마, 저 언니는 누구예요?', 28153),
(153255, 'koKR', '햄릿... 고통은 이제 끝이야...', '', 28153),
(153254, 'koKR', '아이고, 머리야... 제 돼지에게 무슨 일이 생긴 거죠!?', '', 28153),
(153253, 'koKR', '오늘의 위대한 승리를 후세에 전하겠습니다. 그러니... 반드시 승리하십시오!', '', 28153),
(153252, 'koKR', '진홍빛 숲으로 돌아가십시오!', '진홍빛 숲으로 돌아가십시오!', 28153),
(153250, 'koKR', '시민들을 경계선 밖으로 물려라!', '', 28153),
(153249, 'koKR', '%s|1이;가; 도망칩니다.', '%s|1이;가; 도망칩니다.', 28153),
(153248, 'koKR', '', '이제 저는 저들의 범죄자고요.', 28153),
(153247, 'koKR', '', '도시 경비는 여전히 잘 통솔되네요. 아버지의 큰 자랑이었죠.', 28153),
(153246, 'koKR', '재촉 말거라! 네 주인을 구하려는 중이다!', '', 28153),
(153245, 'koKR', '이보시오, $n! 이쪽이오!', '이보시오, $n! 이쪽이오!', 28153),
(153244, 'koKR', '재수가 없었습니다! 돌와타에 가는 길이었는데 제 야수가 병에 걸렸지 뭡니까? 재수가 없으면 뒤로 자빠져도 코가 깨진다더니, 딱 그 꼴입니다.', '', 28153),
(153243, 'koKR', '저는 랠리예요!', '저는 랠리예요!', 28153),
(153242, 'koKR', '저곳에 수많은 호드의 피가 뿌려졌습니다. 저에게 조금만 가져다주시겠습니까?', '저기에 수많은 호드의 피가 뿌려졌습니다. 저에게 조금만 가져다주시겠습니까?', 28153),
(153241, 'koKR', '고통스럽게 해주마.', '고통스럽게 해주마.', 28153),
(153240, 'koKR', '이 자를 죽이라는 명령을 받았다.', '이 자를 죽이라는 명령을 받았다.', 28153),
(153239, 'koKR', '', '가까이 오세요. 들킬 위험은 감수하고 싶지 않아요.', 28153),
(153238, 'koKR', '', '집중하세요.', 28153),
(153237, 'koKR', '', '외부의 눈길을 끌 셈인가요?', 28153),
(153236, 'koKR', '어이, 보리스... 우리 날치기도 날 샌 것 같아...', '', 28153),
(153235, 'koKR', '내 야수에게서 떨어지지 못해!', '', 28153),
(153234, 'koKR', '바로 이거야. 이 아제라이트를 봐!', '', 28153),
(153233, 'koKR', '대장! 오셨군요!', '', 28153),
(153231, 'koKR', '비키십시오! 여기 위험한 범죄자가 지나갑니다!', '', 28153),
(153230, 'koKR', '멈추시오! 용건을 밝히시오!', '', 28153),
(153229, 'koKR', '', '돌아다닐 시간 없어요.', 28153),
(153228, 'koKR', '시... 시끄럽네.', '', 28153),
(153227, 'koKR', '오오... 마녀의 짓인가 보군!', '', 28153),
(153226, 'koKR', '갤리윅스, 자네 정찰병이군... 이번엔 목숨을 잃었네.', '', 28153),
(153225, 'koKR', '도시 심장부로 들어가 나머지 시민들을 대피시켜야 한다!', '', 28153),
(153224, 'koKR', '조... 조심...', '', 28153),
(153223, 'koKR', '', '거의 다 됐다! 서둘러라, 영웅들이여!', 28153),
(153222, 'koKR', '', '계속 이동해라!', 28153),
(153220, 'koKR', '용사들이여, 나와 함께 성채로 집결하게! 대족장님의 명령일세!', '', 28153),
(153217, 'koKR', '', '사울팽! 어딜 간 거지?', 28153),
(153216, 'koKR', '붕괴된 밭은 아직 위험하니 조심하십시오! 오른쪽 길로 가면 조금 더 안전하게 풍차까지 갈 수 있을 겁니다. 거기를 지나면 금방 딜의 농장입니다.', '', 28153),
(153215, 'koKR', '', '싸울 생각이 있다면, 저를 좀 도와주시죠.', 28153),
(153214, 'koKR', '', '물약은 다 떨어졌고 마차로 가는 길에는 세스락이 잔뜩 깔렸어요.', 28153),
(153213, 'koKR', '', '숨 붙어 있는 거 맞죠? 무기도 아직 쓸 만한가요?', 28153),
(153212, 'koKR', '', '꿈 깨시지, 뱀 대가리들!', 28153),
(153211, 'koKR', '저를 입구로 보내주십시오.', '저를 입구로 보내주십시오.', 28153),
(153210, 'koKR', '당신과 당신의 아군 덕분에 세스랄리스의 화신이 생명력을 회복했습니다.', '당신과 당신의 아군 덕분에 세스랄리스의 화신이 생명력을 회복했습니다.', 28153),
(153209, 'koKR', '마그니, 저를 잔달라로 보내주십시오.', '마그니, 저를 잔달라로 보내주십시오.', 28153),
(153207, 'koKR', '이거면 어디든 갈 수 있다네! 같이 가세나.', '', 28153),
(153206, 'koKR', '남은 침입자를 모두 물리쳐야 합니다.', '남은 침입자를 모두 물리쳐야 합니다.', 28153),
(153205, 'koKR', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|t화신이 합류하여, 전투를 마무리 하도록 당신에게 |cFFFF0000|Hspell:269670|h[권능]|h|r을 부여합니다!', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|t화신이 합류하여, 전투를 마무리 하도록 당신에게 |cFFFF0000|Hspell:269670|h[권능]|h|r을 부여합니다!', 28153),
(153204, 'koKR', '<당신 앞에 세스랄리스의 화신이 보입니다. 아직 살아 있지만, 트롤들의 손에 너무 약해졌습니다. 주변의 고대 방어 수호물에 생명의 빛이 깜박입니다...>', '<당신 앞에 세스랄리스의 화신이 보입니다. 아직 살아 있지만, 트롤들의 손에 너무 약해졌습니다. 주변의 고대 방어 수호물에 생명의 빛이 깜박입니다...>', 28153),
(153203, 'koKR', '|cffffff00나무 +$1i|r', '|cffffff00나무 +$1i|r', 28153),
(153202, 'koKR', '공주님 말씀 들었지! 박살 내자!', '', 28153),
(153201, 'koKR', '', '보호막이! 사라지고 있습니다!', 28153),
(153199, 'koKR', '내 등장이 조금 갑작스럽긴 했지만 놀라지 말게! 나는 마그니 브론즈비어드, 아제로스의 대변자일세.', '', 28153),
(153198, 'koKR', '', '아, 오셨군요, 용사님. 논의할 계획이 있습니다.', 28153),
(153197, 'koKR', '아, 여기 있었군, 용사여. 할 말이 있네!', '', 28153),
(153196, 'koKR', '[IGC - 캐서린 접견 - 제이나는 자신의 운명을 캐서린의 손에 맡깁니다. 제이나를 반역자로 취급하라는 여군주 애쉬베인의 말을 받아들인 캐서린은 제이나를 심판대로 올립니다. \"내게 그 아이는 이미 죽은 사람이다.\" 플레이어는 체포됩니다.]', '[IGC - 캐서린 접견 - 제이나는 자신의 운명을 캐서린의 손에 맡깁니다. 제이나를 반역자로 취급하라는 여군주 애쉬베인의 말을 받아들인 캐서린은 제이나를 심판대로 올립니다. \"내게 그 아이는 이미 죽은 사람이다.\" 플레이어는 체포됩니다.]', 28153),
(153195, 'koKR', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t 당신은 |cFFFF0000|Hspell:265212|h[잉태]|h|r의 대상으로 지정되었습니다!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t 당신은 |cFFFF0000|Hspell:265212|h[잉태]|h|r의 대상으로 지정되었습니다!', 28153),
(153194, 'koKR', '우리가 당신을 회복시키겠습니다!', '우리가 당신을 회복시키겠습니다!', 28153),
(153193, 'koKR', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t 벡티스가 |cFFFF0000|Hspell:265217|h[액화]|h|r를 시작합니다!', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t 벡티스가 |cFFFF0000|Hspell:265217|h[액화]|h|r를 시작합니다!', 28153),
(153192, 'koKR', '갤리윅스는 신경 쓰지 말게. 우리는 적의 위치를 확인하러 드러스트바로 가는 걸세. 돈은 주 관심사가 아니야.', '', 28153),
(153191, 'koKR', '이제는... 고요하구나.', '', 28153),
(153190, 'koKR', '아, 나는 죽으리...', '', 28153),
(153189, 'koKR', '아이트리그와 선장이 준비됐는지 확인해 봐. 돈을 벌어야 한다고!', '', 28153),
(153188, 'koKR', '나를... 쓰러뜨리다니...', '', 28153),
(153187, 'koKR', '이제부터는... 한 마디도 할 수 없다.', '', 28153),
(153186, 'koKR', '이제, 그만!', '', 28153),
(153185, 'koKR', '악당이여, 나를 죽이다니!', '', 28153),
(153184, 'koKR', '오, 내가 졌도다!', '', 28153),
(153183, 'koKR', '이제 내 영혼은 떠난다. 더는... 할 수 있는 것이 없다.', '', 28153),
(153182, 'koKR', '', '아니. 내 백성을 더 건드리게 두지 않겠다. 너의 광기도 여기서 끝이다!', 28153),
(153180, 'koKR', '', '바로 그거다, 공주!', 28153),
(153177, 'koKR', '타락 봉인을 위한 세 가지 장치가 있습니다.', '', 28153),
(153174, 'koKR', '[멋진 컷신]', '[멋진 컷신]', 28153),
(153173, 'koKR', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t 벡티스가 |cFFFF0000|Hspell:266948|h[역병 폭탄]|h|r을 시전합니다!', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t 벡티스가 |cFFFF0000|Hspell:266948|h[역병 폭탄]|h|r을 시전합니다!', 28153),
(153172, 'koKR', '', '고대 신?! 그래서 혈트롤들이 내 도시를 공격했군...', 28153),
(153171, 'koKR', '데이터 복구 완료. 타락의 근원은 나즈미르에 격리된 고대 신입니다.', '', 28153),
(153169, 'koKR', '...데킬라 한 통에 1점!', '...데킬라 한 통에 1점!', 28153),
(153168, 'koKR', '|cFF0000FF(퀘스트)|r 드러스트바로 갑시다.', '|cFF0000FF(퀘스트)|r 드러스트바로 갑시다.', 28153),
(153167, 'koKR', '', '밴시의 비명호는 어둠의 여왕께서 보유한 최고의 함선 중 하나일세. 겉만 봐서는 모르겠지만, 어둠의 여왕님은 강하고 무서운 분이시지.\n\n나는 그 발치에도 못 미친다네.', 28153),
(153166, 'koKR', '네, 드러스트바로 떠날 준비가 됐습니다.', '네, 드러스트바로 떠날 준비가 됐습니다.', 28153),
(153165, 'koKR', '고블린은 신경 쓰지 말게, $n|1이여;여;. 단순히 아제라이트를 최대한 확보하는 것이 아니라 얼라이언스에 대한 정보를 모으는 것이 우리 임무일세.\n\n떠날 준비는 되었나?', '', 28153),
(153164, 'koKR', '무역왕에게 끌려다니지 말게. 우리 주 임무는 정찰이야... 돈이 목적이 아닐세.', '', 28153),
(153163, 'koKR', '저기 어마어마한 아제라이트가 우리를 기다리고 있다는 소식을 들었습니다. 가서 차지하기만 하면 됩니다. 당신이 말입니다.\n\n당신이 죽으면 그 모자는 제가 갖겠습니다! 하하!', '', 28153),
(153162, 'koKR', '몰려오는 침입자를 해치우면서 세스랄리스의 화신을 회복시켜야 합니다.', '몰려오는 침입자를 해치우면서 세스랄리스의 화신을 회복시켜야 합니다.', 28153),
(153161, 'koKR', '잘했다, 영웅이여. 밀림그물 거미가 들어오지 못하도록 사원 앞마당을 잘 지켜야 한다.', '', 28153),
(153160, 'koKR', '사원 폐허에 밀림그물 거미가 우글거린다. 저 해충들을 처리하고 거미줄에 갇힌 내 추종자들을 구하거라.', '', 28153),
(153159, 'koKR', '화신의 생명력을 완전히 회복시켜야 합니다.', '화신의 생명력을 완전히 회복시켜야 합니다.', 28153),
(153158, 'koKR', '교활한 거미들!', '', 28153),
(153157, 'koKR', '감사합니다, $n 님! 제 생명의 은인이십니다.', '', 28153),
(153156, 'koKR', '다시 숨 쉴 수 있다니! 감사합니다!', '', 28153),
(153155, 'koKR', '이 거미들은 뭐든 먹어치울 것입니다!', '', 28153),
(153154, 'koKR', '감사합니다! 정말 아슬아슬했습니다...', '', 28153),
(153153, 'koKR', '이렇게 끝나는 줄 알았습니다!', '', 28153),
(153152, 'koKR', '바라는 게 뭐냐?', '바라는 게 뭐냐?', 28153),
(153151, 'koKR', '안 돼, 제발...', '안 돼, 제발...', 28153),
(153150, 'koKR', '', '그럼 타세요! 용사님, 저희는 먼저 가서 애쉬턴 대가님을 찾아볼게요. 진홍빛 숲에서 만나요!', 28153),
(153149, 'koKR', '으악! 내 뼈!', '으악! 내 뼈!', 28153),
(153148, 'koKR', '아, 이게 얼마나 그립던지.', '아, 이게 얼마나 그립던지.', 28153),
(153147, 'koKR', '재미없구나. 조금 재미있게... 만들어주지.', '재미없구나. 조금 재미있게... 만들어주지.', 28153),
(153146, 'koKR', '어때, 고통스럽나?', '어때, 고통스럽나?', 28153),
(153145, 'koKR', '그런 것 같습니다.', '', 28153),
(153144, 'koKR', '', '마르텐, 움직일 수 있겠어요?', 28153),
(153143, 'koKR', '마을은 안심해도 되니, 무슨 일인지 설명 좀 해 줄 수 있겠나?', '', 28153),
(153142, 'koKR', '물론이네! 무슨 일로 내 도움이 필요한진 몰라도 내 고향을 구해줬으니 마땅히 돕겠네!\n\n그런데 조금 기다려야 할 것 같네. 마을이 지금 난장판이어서 말이지.', '', 28153),
(153141, 'koKR', '여기서 빠져나가야 해요!', '여기서 빠져나가야 해요!', 28153),
(153140, 'koKR', '안 돼, 저 녀석들이 또!', '안 돼, 저 녀석들이 또!', 28153),
(153139, 'koKR', '당신이 절 살려주셨군요...', '당신 덕분에 살았습니다...', 28153),
(153138, 'koKR', '호드라니! 여기서 뭘 하는 거죠?', '호드라니! 여기서 뭘 하는 거죠?', 28153),
(153137, 'koKR', '닻을 올리십시오, 사령관님!', '닻을 올리십시오, 사령관님!', 28153),
(153136, 'koKR', '전 당신을 갈매기보다 빠르게 저 너머로 데려가 줄 수 있습니다. 준비되면 알려 주십시오.', '', 28153),
(153135, 'koKR', '애쉬턴 님을 찾으십니까? 함께 가시죠. 대가님은 못 봤지만, 그의 수습생은 봤거든요.', '', 28153),
(153134, 'koKR', '후우. 이건 심장이나 비위가 약한 분에겐 좀 힘들겠네요.', '', 28153),
(153133, 'koKR', '바다 건너 사막에서 온 맛있는 간식에 관해 들은 적이 있습니다. 대머리수리 날개와 전갈 독침을 좀 구해 주십시오. 저만의 비법으로 새로운 요리를 만들 생각입니다.', '', 28153),
(153132, 'koKR', '조타수, 항로를 유지하라.', '조타수, 항로를 유지하라.', 28153),
(153131, 'koKR', '아니야, 이 멍청아. 다른 쪽이라고!', '아니야, 이 멍청아. 다른 쪽이라고!', 28153),
(153130, 'koKR', '불순한 자들은 죽음의 전당을 지나지 못한다.', '', 28153),
(153129, 'koKR', '더는 못 간다.', '', 28153),
(153128, 'koKR', '아무도 들어가지 못한다.', '', 28153),
(153127, 'koKR', '또 보자고.', '', 28153),
(153126, 'koKR', '안녕하신가.', '', 28153),
(153125, 'koKR', '', '선생으로서 실격이군요.', 28153),
(153124, 'koKR', '', '쉴 시간이에요.', 28153),
(153123, 'koKR', '', '수업은... 끝났어요.', 28153),
(153122, 'koKR', '', '수업을 시작하죠!', 28153),
(153121, 'koKR', '', '세 가지를 가르쳐드리죠. 룬, 의식 그리고 유물이에요!', 28153),
(153120, 'koKR', '', '좀 배우셔야겠군요!', 28153),
(153119, 'koKR', '이제 숙성 과정은 누가 지켜보지?', '', 28153),
(153118, 'koKR', '이번 술은... 망쳤어.', '', 28153),
(153117, 'koKR', '물건에 손대지 마!', '', 28153),
(153116, 'koKR', '이 수집품은 손님 전용이야!', '', 28153),
(153115, 'koKR', '좋습니다! 이 정도면 오래 먹을 수 있을 겁니다. 한 번에 먹어치우지만 않으면 말이죠.', '', 28153),
(153114, 'koKR', '이곳에 적응해서 살아남는 생물을 보면 놀라실 겁니다. 덩굴손 씨앗은 톡 튀는 맛이 일품이랍니다! 씨앗을 좀 가져다주십시오. 가시 조심하시고요!', '', 28153),
(153113, 'koKR', '... 왈트, 네 사고방식은 참 맘에 든다니까.', '', 28153),
(153112, 'koKR', '아니면... 이미 값은 지불했으니 해더포드에는 우리가 당했다고 전하고... 벌꿀술은 우리가 마시면 어떨까요?', '', 28153),
(153111, 'koKR', '좋아... 이제 안전한 것 같습니다. 술통을 해더포드로 가져가죠.', '', 28153),
(153110, 'koKR', '당신이 배에 연락하는 동안 저는 제임스의 흔적을 추적하겠습니다. 저 비늘 달린 놈들의 손아귀에 제임스를 버려둘 수 없습니다.', '당신이 배에 연락하는 동안 저는 제임스의 흔적을 추적하겠습니다. 저 비늘 달린 놈들의 손아귀에 제임스를 버려둘 수 없습니다.', 28153),
(153109, 'koKR', '확실해! 저건 꿀이 줄줄 흐를 거야!', '', 28153),
(153108, 'koKR', '이리 와, 이 멍청이야!', '', 28153),
(153107, 'koKR', '음... 난 완벽하게 준비됐다. 할 테면 해 봐라, 자연아!', '', 28153),
(153106, 'koKR', '시작합시다!', '시작합시다!', 28153),
(153105, 'koKR', '더 흉포한 짐승이 곧 나타날 겁니다, $c님. 벌꿀술을 당신 목숨처럼 지켜주세요!', '', 28153),
(153103, 'koKR', '기운 내, 브래드포드! 놈들에게 지면 안 돼!', '', 28153),
(153102, 'koKR', '이봐, 왈트. 이제 끝인 것 같아. 저 야수들과 얼마나 더 싸울 수 있을지 모르겠어!', '', 28153),
(153101, 'koKR', '%s|1이;가; 완전히 충전된 아제라이트 대포로 공성 탑을 조준합니다.', '', 28153),
(153100, 'koKR', '$n 님! 당신이 필요합니다, 급합니다!', '$n 님! 당신이 필요합니다, 급합니다!', 28153),
(153099, 'koKR', '빌어먹을, 레오나드! 조사하겠다는 허락도 안 받고 가더니만!', '빌어먹을, 레오나드! 조사하겠다는 허락도 안 받고 가더니만!', 28153),
(153098, 'koKR', '나머지는 나를 따라 와라. 우리는 적의 측면으로 움직인다.', '나머지는 나를 따라 와라. 우리는 적의 측면으로 움직인다.', 28153),
(153097, 'koKR', '멋지군요. 이 작은 녀석들은 놀라운 여행가입니다. 이들이 어떤 이야기를 들려줄지 궁금하군요.', '', 28153),
(153096, 'koKR', '펄럭이는 보통 몇 달밖에 살지 못하는데, 여기 녀석들은 다르더군요. 몇 마리만 잡아다 주십시오. 예민하니까 살살 다루셔야 합니다.', '', 28153),
(153093, 'koKR', '', '이제... 정원은 누가 관리하지?', 28153),
(153092, 'koKR', '', '흙으로 돌아가리...', 28153),
(153091, 'koKR', '', '네놈은 좋은 비료가 되겠군.', 28153),
(153090, 'koKR', '', '뿌린 대로 거두는 법!', 28153),
(153089, 'koKR', '', '내 정원에 침입하다니!', 28153),
(153088, 'koKR', '', '갈가리 찢어주마.', 28153),
(153087, 'koKR', '', '내 계획이... 흐트러졌어...', 28153),
(153086, 'koKR', '', '내 직물에 네 파멸이 예고되어 있다!', 28153),
(153085, 'koKR', '', '네 최후가 다가온다!', 28153),
(153084, 'koKR', '', '네 영혼을 꼬아 양탄자로 만들어 주마!', 28153),
(153083, 'koKR', '끝내기엔 아쉬운 사냥이건만...', '', 28153),
(153082, 'koKR', '사나운 상대로구나...', '', 28153),
(153081, 'koKR', '내가 전리품이 될 줄은... 생각지도 못했군...', '', 28153),
(153080, 'koKR', '공격 시간이다!', '', 28153),
(153079, 'koKR', '네놈을 벽에 걸면 멋진 장식품이 되겠군!', '', 28153),
(153078, 'koKR', '사냥 시작!', '', 28153),
(153077, 'koKR', '신선한 고기는 석쇠로!', '', 28153),
(153076, 'koKR', '저녁 준비됐다!', '', 28153),
(153075, 'koKR', '사원은 다시 한 번 열릴 것이오. 구원의 때가 왔소!', '', 28153),
(153074, 'koKR', '이 어둠은 우리 앞길을 막을 수 없소.', '', 28153),
(153073, 'koKR', '잘하셨습니다. 영웅처럼 목숨을 희생해 라카타카 왕의 횡포를 막아 준 용감한 협곡 딱정벌레가 길이 기억되기를.', '', 28153),
(153072, 'koKR', '저희 종족은 별거 아닌 일로도 칼을 뽑죠.', '', 28153),
(153071, 'koKR', '당신은 눈치도 없고 수양도 부족한 분인 것 같군요.', '', 28153),
(153070, 'koKR', '모든 것에는 가치가 있답니다. 심지어 당신도요.', '', 28153),
(153069, 'koKR', '사막은 파괴하는 자를 집어삼킵니다.', '', 28153),
(153068, 'koKR', '사막이 우리에게 길을 보여줄 겁니다.', '', 28153),
(153067, 'koKR', '우리는 사막이 인도하는 곳으로 갑니다.', '', 28153),
(153066, 'koKR', '사막에는 우리에게 필요한 모든 것이 있습니다.', '', 28153),
(153065, 'koKR', '사막에서 생존하기 위해 가장 중요한 것은 잊어버린 가치를 찾는 것입니다.', '', 28153),
(153064, 'koKR', '잊지 마세요. 모든 것은 쓸모가 있습니다.', '', 28153),
(153063, 'koKR', '편하게 말씀하시죠.', '', 28153),
(153062, 'koKR', '안녕하십니까.', '', 28153),
(153061, 'koKR', '뭘 가져오셨나요?', '', 28153),
(153060, 'koKR', '거래를 하러 오셨습니까?', '', 28153),
(153059, 'koKR', '도와드릴까요?', '', 28153),
(153058, 'koKR', '', '잔달라는 견뎌낼 겁니다.', 28153),
(153057, 'koKR', '', '조심히 가십시오.', 28153),
(153056, 'koKR', '', '사막은 누구에게나 너무 가혹한 운명입니다.', 28153),
(153055, 'koKR', '', '뭘 도와드릴까요?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153054, 'koKR', '', '용건만 말하십시오.', 28153),
(153053, 'koKR', '', '듣고 있습니다.', 28153),
(153052, 'koKR', '', '무슨 일이십니까?', 28153),
(153051, 'koKR', '우린 절대 포기하지 않습니다.', '우린 절대 포기하지 않습니다.', 28153),
(153050, 'koKR', '부정한 자들의 제국은 멸망할 것입니다.', '부정한 자들의 제국은 멸망할 것입니다.', 28153),
(153049, 'koKR', '세스랄리스 님이 우리 모두를 구원하실 겁니다.', '세스랄리스 님이 우리 모두를 구원하실 겁니다.', 28153),
(153048, 'koKR', '코르테크가 이 전쟁을 시작했습니다.', '코르테크가 이 전쟁을 시작했습니다.', 28153),
(153047, 'koKR', '굳건해야 합니다.', '굳건해야 합니다.', 28153),
(153046, 'koKR', '도와주러 오신 건지요?', '도와주러 오신 건지요?', 28153),
(153045, 'koKR', '라카타카 왕이 뼛길 협곡에서 횡포를 부리고 있어요! 직접 공격하기엔 너무 강하지만, 놈의 먹성은 끝이 없으니 먹을 걸 계속 먹이면 배가 불러 죽을 겁니다!', '', 28153),
(153044, 'koKR', '저희 종족은 별거 아닌 일로도 칼을 뽑죠.', '저희 종족은 별거 아닌 일로도 칼을 뽑죠.', 28153),
