(151990, 'koKR', '그럼 이제... 전리품을 받아 볼까.', '', 28153),
(151989, 'koKR', '진주를 손에 넣었네! 이거면 우리 함대가 바다의 지배자가 될 수 있어.', '', 28153),
(151987, 'koKR', '', '지금의 승리를 즐겨라. 그것이 마지막일 테니.', 28153),
(151986, 'koKR', '약육강식, 그게 바로 야생의 만고불변한 법칙이지.', '', 28153),
(151985, 'koKR', '긴장 늦추지 말게. 보이지 않는 힘이 우리를 지켜보네.', '', 28153),
(151983, 'koKR', '얼라이언스가 차지하게 두어서는 안 되네. 우리에게 맞서는 자는 파멸시키게!', '', 28153),
(151982, 'koKR', '', '제 사업을 되찾아주셨으니 그래야겠죠. 세시를 상관으로 모시게 되면 저희가 이곳에서 벌어들이는 돈이 다시 많이 늘어날 테니까요.', 28153),
(151981, 'koKR', '세시 루스캐넌을 지지해 줄 겁니까?', '세시 루스캐넌을 지지해 줄 겁니까?', 28153),
(151980, 'koKR', '', '이곳의 수익성은 예전이 훨씬 좋았죠.', 28153),
(151979, 'koKR', '', '더 위험해지기 전에 빠져나가죠. 어서요!', 28153),
(151978, 'koKR', '파도어머니의 분노는 막을 수 없나니, 스톰송 가문이 이 물에 잠긴 왕국을 통치하리라.', '', 28153),
(151977, 'koKR', '함대를... 여왕님 손에...', '', 28153),
(151976, 'koKR', '잠시 놀아줬을 뿐입니다, 주군. 이제 분부대로!', '', 28153),
(151975, 'koKR', '운명의 때가 당도했다. 절대로 녀석들을 폭풍의 사원에 들이지 말거라.', '', 28153),
(151974, 'koKR', '', '네 모습을 똑바로 봐. 네가 피로 물들인 사람들을 보라고!', 28153),
(151973, 'koKR', '두루마리가 떠올라 웅웅거립니다. 다른 장소의 환영은 마법에 의해 가려져 있습니다.', '', 28153),
(151972, 'koKR', '세계영혼 생존 가능성: 없음...', '', 28153),
(151971, 'koKR', '행성 감염 임박.', '', 28153),
(151970, 'koKR', '무쇠파도 녀석들이 보물을 가져가게 하는 게 낫겠어요.', '무쇠파도 녀석들이 보물을 가져가게 하는 게 낫겠어요.', 28153),
(151969, 'koKR', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s|1이;가; |cFFFF0000|Hspell:267891|h[신속 수호물]|h|r을 생성합니다!', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s|1이;가; |cFFFF0000|Hspell:267891|h[신속 수호물]|h|r을 생성합니다!', 28153),
(151968, 'koKR', '<그냥 찌른다>', '<그냥 찌른다>', 28153),
(151967, 'koKR', '...정말입니까?', '...정말입니까?', 28153),
(151966, 'koKR', '터무니없군요! 그 가격은 낼 수 없습니다!', '터무니없군요! 그 가격은 낼 수 없습니다!', 28153),
(151965, 'koKR', '바닥에서 1박은 50골드입니다. 불 근처 자리면 60골드 받습니다. 담요는 개별 지참입니다. \n\n침대 숙박은 100골드입니다. \n\n이곳을 귀환 장소로 선택하고 싶으시다면, 일주일에 75골드입니다.\n\n마음에 들지 않으십니까? \n\n<실실 비웃으며 팔짱을 끼는 게리 빌지워터>\n\n안타깝군요. 요즘 시세가 이런데 어쩌겠습니까.', '', 28153),
(151964, 'koKR', '바다에게 들었다. 너희가 올 거라고, 그리고 죽을 거라고!', '', 28153),
(151963, 'koKR', '대규모 침투 감지.', '', 28153),
(151962, 'koKR', '', '병력을 모아 부패의 근원을 없애야 합니다.', 28153),
(151961, 'koKR', '', '티탄이 시간을 벌어줬지만, 그훈을 오래 막지는 못할 겁니다.', 28153),
(151960, 'koKR', '악성 표본 감지. 우선 봉쇄 대상으로 지정.', '', 28153),
(151959, 'koKR', '집어삼켜라! 먹어치워라! 퍼져라!', '', 28153),
(151958, 'koKR', '', '이게 마마를 찾는 겁니까? 일단, 저게 역병 전염을 막을 무언가를 찾아주길 기대해 보죠.', 28153),
(151957, 'koKR', '그훈 봉쇄 실패. 마.더. 응답 없음.', '', 28153),
(151954, 'koKR', '', '이게 지상에 퍼지면, 우리 힘으로 막을 수 없을 겁니다.', 28153),
(151953, 'koKR', '', '이런 형태의 부패는 처음 봅니다.', 28153),
(151952, 'koKR', '', '저게 지상에 도달하면 안 됩니다. 당장 파괴하십시오!', 28153),
(151951, 'koKR', '', '윽! 이건 대체 무슨 생명체입니까?', 28153),
(151950, 'koKR', '', '조심하십시오. 이 동굴에 뭐가 숨어 있을지 아무도 모릅니다.', 28153),
(151949, 'koKR', '', '혈트롤이 흩어졌지만, 우린 부패의 근원을 찾아 파괴해야 합니다.', 28153),
(151948, 'koKR', '선물을 가져왔습니다, 위대한 죽음의 로아여!', '', 28153),
(151947, 'koKR', '새로운 얼굴들로 교체된다면야, 알겠어. 그렇게 하도록 하지.', '', 28153),
(151946, 'koKR', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t $s|1이;가; |cFFFF0404|Hspell:260773|h[광포한 의식]|h|r을 시전합니다!', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t %s|1이;가; |cFFFF0404|Hspell:260773|h[광포한 의식]|h|r을 시전합니다!', 28153),
(151945, 'koKR', '세시 루스캐넌을 지지해 줄 겁니까?', '세시 루스캐넌을 지지해 줄 겁니까?', 28153),
(151944, 'koKR', '거래를 하러 왔나?', '', 28153),
(151943, 'koKR', '', '상황이 좋지 않네요...', 28153),
(151942, 'koKR', '기꺼이. 저들에게 고통을!', '', 28153),
(151941, 'koKR', '전염 감지. 정화.', '', 28153),
(151940, 'koKR', '역병 폭발!', '', 28153),
(151939, 'koKR', '최후 안전 조치 실행. 악성 근원 파괴.', '', 28153),
(151938, 'koKR', '알겠습니다, 군주님. 해충 몇 마리만 처리하면 됩니다.', '알겠습니다. 해충 몇 마리만 처리하면 됩니다.', 28153),
(151937, 'koKR', '해당 구역 정화.', '', 28153),
(151936, 'koKR', '정화 프로토콜 가동.', '', 28153),
(151935, 'koKR', '썩은 파열!', '', 28153),
(151934, 'koKR', '뼈가 몇 개 부러졌을 뿐입니다... 대수로울 것도 없어요.', '', 28153),
(151933, 'koKR', '불페라 야영지로 안내해 주십시오, $p|1이여;여;. 보물을 옮겨야 합니다.', '', 28153),
(151932, 'koKR', '피의 방출!', '', 28153),
(151931, 'koKR', '', '무기를 버려! 너와 싸우고 싶지 않아!', 28153),
(151930, 'koKR', '퍼뜨려야... 하는데...', '', 28153),
(151929, 'koKR', '역병의 손아귀로!', '', 28153),
(151928, 'koKR', '잘 옮았구나!', '', 28153),
(151927, 'koKR', '육체를 감염시키자.', '', 28153),
(151926, 'koKR', '먹어치우자!', '', 28153),
(151925, 'koKR', '퍼뜨려야 해!', '', 28153),
(151924, 'koKR', '이제 네가 지킬 약속을 잊지만 말거라...', '', 28153),
(151923, 'koKR', '하하하하! 보았느냐, 왕이여? 브원삼디는 항상 약속을 지킨다!', '', 28153),
(151922, 'koKR', '일어나라... 일어나! 게으름 피우지 말고! 다시 창을 들고, 싸워라!', '', 28153),
(151921, 'koKR', '워워, 진정하라고. 브원삼디는 항상 친구를 도우니까...', '', 28153),
(151920, 'koKR', '', '거기서 제가 일하는 모습을 지켜보고 있을 필요는 없습니다. 우리 둘 다 할 일이 있잖습니까.', 28153),
(151919, 'koKR', '언제든 배를 띄울 준비가 됐습니다.', '', 28153),
(151918, 'koKR', '이 배신자들이 저와 제 왕국을 가로막고 있는데 로아께서 약속하신 지원은 어디에 있습니까? 언제 약속을 지키실 겁니까?', '', 28153),
(151916, 'koKR', '잘해주었네, 용사여. 아제로스가 힘을 회복하는 게 느껴지는군. 그대 덕분일세.', '', 28153),
(151915, 'koKR', '근처에 아제라이트 흉터가 여러 곳 드러나 있네. 그대가 가진 아제로스의 심장을 이용해 치유해주게나.', '', 28153),
(151913, 'koKR', '도망칠 수 있을 때 도망치십시오!', '', 28153),
(151912, 'koKR', '쯧쯧! 자신이 모시는 로아에게 존경을 보이는 말투는 아니로구나. 하지만 내가 오늘 모을 영혼을 보아 이 정도는 넘어가도록 하지!', '', 28153),
(151911, 'koKR', '우린 이제 같은 배를 탄 겁니다, $p|1이여;여;.\n\n반란이 아니면 활대 형벌을!', '', 28153),
(151910, 'koKR', '브원삼디 님, 나타나 주십시오!', '', 28153),
(151909, 'koKR', '줄과 함께하는 이가 너무 많군. 길은 하나뿐이다...', '', 28153),
(151908, 'koKR', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s|1이;가; |cFFFF0000$n|r|1을;를; 바라보며 |cFFFF0000|Hspell:266951|h[질주 돌파]|h|r를 준비합니다!', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s|1이;가; |cFFFF0000$n|r|1을;를; 바라보며 |cFFFF0000|Hspell:266951|h[질주 돌파]|h|r를 준비합니다!', 28153),
(151907, 'koKR', '잔달라 무리가 세스랄리스의 심장을 보호하던 고대의 수호물을 해제했습니다...', '잔달라 무리가 세스랄리스의 심장을 보호하던 고대의 수호물을 해제했습니다...', 28153),
(151906, 'koKR', '예. 확실하게 세시를 지지하도록 하죠.', '', 28153),
(151905, 'koKR', '빨리 움직여라 이 게으른 고블린들아! 그 상자 안에 든 물건들로 당장 기지를 세워야 한단 말이다!', '빨리 움직여라 이 게으른 고블린들아! 그 상자 안에 든 물건들로 당장 기지를 세워야 한단 말이다!', 28153),
(151904, 'koKR', '세시 루스캐넌을 지지하겠습니까?', '세시 루스캐넌을 지지하겠습니까?', 28153),
(151902, 'koKR', '흐음. 그래요, 살펴보겠습니다.\n\n<한동안 뒤적거리더니 짐 깊숙이에서 단지 하나를 꺼내는 쿠다.>\n\n수백 년 전에 이것을 샀었습니다. 잊어버리고 있었군요. 팔아도 될 것 같습니다.', '', 28153),
(151901, 'koKR', '\'세기의 양념\'이라는 것을 들어보셨습니까? 혹시 가지고 계십니까?', '\'세기의 양념\'이라는 것을 들어보셨습니까? 혹시 가지고 계십니까?', 28153),
(151900, 'koKR', '안녕하세요, $r님. 판매할 흥미로운 물건이 있나요?', '', 28153),
(151899, 'koKR', '파도의 이름으로, 나와라!', '파도의 이름으로, 나와라!', 28153),
(151898, 'koKR', '굶주림은 끝이 없고, 왕께서는 포식하신다.', '', 28153),
(151897, 'koKR', '상처는 곪으며, 세계는 부패한다.', '', 28153),
(151896, 'koKR', '우리는 언제나 네 머릿속에 있었다.', '', 28153),
(151895, 'koKR', '부패한 절규가 그분의 도착을 알린다.', '', 28153),
(151894, 'koKR', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|t현자 자나잘이 |cFFFF0000|Hspell:267273|h[독 회오리]|h|r를 시전합니다!', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|t현자 자나잘이 |cFFFF0000|Hspell:267273|h[독 회오리]|h|r를 시전합니다!', 28153),
(151893, 'koKR', '', '심연의 무리가 깨어났다!', 28153),
(151892, 'koKR', '', '크릴 락스 쿠토릴!', 28153),
(151890, 'koKR', '넌 내 화신이 되어 나가를 상대했고, 내 사원을 향한 공격도 멈추게 해 주었다.', '', 28153),
(151889, 'koKR', '', '오! 정말 오랫동안 세기의 양념을 써보고 싶었어요! 몇 가지 재료를 모두 섞은 다음 수 세기 동안 발효시킨 요리 양념이랍니다. 오래 발효할수록 더욱 복잡한 풍미가 느껴져요. 모든 요리에 독특한 향과 맛을 더해준다고 해요.\n\n일부 토르톨란 무역상이 가지고 다닌다는 소문이 있지만, 희귀하고 매우 비싼 물건이에요.\n\n<애석한 듯 한숨 쉬는 슌슌>\n\n요리사에게는 꿈의 재료라고 할 수 있죠!', 28153),
(151888, 'koKR', '식료품 종류가 어마어마하군요. 혹시 양념 선반에 더 필요한 물건은 없습니까?', '식료품 종류가 어마어마하군요. 혹시 양념 선반에 더 필요한 물건은 없습니까?', 28153),
(151887, 'koKR', '', '처음 보는 얼굴이군요! 하지만 낯설지는 않군요. 특별한 물건을 찾으시나요? 아니면 희귀한 향료나 조제법을 찾고 있나요?', 28153),
(151886, 'koKR', '아제로스의 심장이 그대 덕에 강력해졌네. 아제로스의 상처를 치유하는 데 한걸음 더 가까워졌군.', '', 28153),
(151885, 'koKR', '근처에서 아제라이트가 느껴지네... 그걸 자기 마음대로 이용하려는 놈들도 함께 있군. 그대가 저들을 막아야 하네!', '', 28153),
(151884, 'koKR', '제자여, 이리오거라. 마음을 가라앉히고 나와 함께 이 자를 치유하자꾸나.', '', 28153),
(151883, 'koKR', '', '심연에서 피가 쏟아져 나온다.', 28153),
(151882, 'koKR', '', '파도 아래, 네 진실이 기다린다.', 28153),
(151881, 'koKR', '', '물에 빠진 자들의 노래를 들어 봐라.', 28153),
(151880, 'koKR', '', '어둠이 뿌리를 내린다. 전염병이 퍼진다. 문이 열린다.', 28153),
(151879, 'koKR', '', '심연이 네 비명을 집어삼키리라!', 28153),
(151878, 'koKR', '', '나는 네놈 폐 속에 있다!', 28153),
(151877, 'koKR', '', '어둠 속에서... 널 기다리겠다...', 28153),
(151876, 'koKR', '', '넌 내 거다!', 28153),
(151875, 'koKR', '', '네 동료가 네 죽음을 즐거이 지켜보더구나.', 28153),
(151874, 'koKR', '', '우리는 심연의 광대함에 영원히 묶여 있다.', 28153),
(151873, 'koKR', '너에게선 어떤 쓸모도 찾을 수 없군.', '', 28153),
(151872, 'koKR', '약해 빠졌어! 쓸모 없어!', '', 28153),
(151871, 'koKR', '열등하기 짝이 없구나!', '', 28153),
(151870, 'koKR', '어떻게... 이런 일이...', '', 28153),
(151869, 'koKR', '울 바샤 크릭스.', '', 28153),
(151868, 'koKR', '', '포화로 하늘을 뒤덮어라! 놈들을 파멸시켜라.', 28153),
(151867, 'koKR', '열등한 생명체여, 복종하라... 아니면 죽어라!', '', 28153),
(151866, 'koKR', '', '호드를 위하여!', 28153),
(151865, 'koKR', '', '절대 봐주지 마라!', 28153),
(151864, 'koKR', '우그 크리쉬 줄 스락사스!', '', 28153),
(151863, 'koKR', '', '계속 발사해라! 지상 병력은 제군들을 믿고 있다.', 28153),
(151862, 'koKR', '', '계속 발사하라!', 28153),
(151861, 'koKR', '이 무덤이 너희들의 마지막 안식처가 되리라!', '', 28153),
(151860, 'koKR', '네놈은 잔달라에 대항할 수 없다!', '', 28153),
(151859, 'koKR', '이 사원은 그훈 님의 지배하에 있다!', '', 28153),
(151858, 'koKR', '잔달라가 지배하리라!', '', 28153),
(151857, 'koKR', '', '이쪽이에요! 영광스러운 전투가 기다려요!', 28153),
(151856, 'koKR', '그훈 님을 막을 수는 없다!', '', 28153),
(151855, 'koKR', '혈신을 위해 피를 흘려라!', '', 28153),
(151854, 'koKR', '저도 제 나름대로 조사해 볼게요. 뭔가 알아내면 가장 먼저 알려드리겠습니다.', '', 28153),
(151853, 'koKR', '들으셨죠! 이 고대 신 타락의 원천을 알아내야 해요... 그래야 이 일에 종지부를 찍을 수 있어요!', '', 28153),
(151852, 'koKR', '하, 줄! 네놈이 고작 이 정도라면 트롤 제국이 멸망한 것도 이해가 된다!', '', 28153),
(151850, 'koKR', '너의 그 감염된 시체를 이 석관에 넣을 수도 있었겠군.', '', 28153),
(151849, 'koKR', '명예와 영광을, 깨어난 폭풍을 위해 싸우겠습니다!', '명예와 영광을, 깨어난 폭풍을 위해 싸우겠습니다!', 28153),
(151848, 'koKR', '제 칼은 당신 것입니다.', '제 칼은 당신 것입니다.', 28153),
(151847, 'koKR', '제 목숨은 아직 다하지 않았습니다!', '제 목숨은 아직 다하지 않았습니다!', 28153),
(151846, 'koKR', '힘을 합쳐 이 악마들을 막을 겁니다!', '힘을 합쳐 이 악마들을 막을 겁니다!', 28153),
(151845, 'koKR', '제가 있는 한 계곡의 자유는 영원할 것입니다!', '제가 있는 한 계곡의 자유는 영원할 것입니다!', 28153),
(151844, 'koKR', '깨어난 폭풍이 부른다면, 반드시 응할 것입니다.', '깨어난 폭풍이 부른다면, 반드시 응할 것입니다.', 28153),
(151843, 'koKR', '죽느냐 사느냐, 결정의 때가 왔군요.', '죽느냐 사느냐, 결정의 때가 왔군요.', 28153),
(151842, 'koKR', '당신과 함께하겠습니다!', '당신과 함께하겠습니다!', 28153),
(151841, 'koKR', '여기 없어서 아쉽구나, 줄. 네 작품이 부서지는 걸 봐야 하는데.', '', 28153),
(151840, 'koKR', '으윽! 어디 두고 보자고, 이 겁쟁이 트롤!', '', 28153),
(151839, 'koKR', '그들은 곧 일어나고, 그훈 님을 대적하는 자는 쓰러지리라!', '', 28153),
(151838, 'koKR', '우리에게도 승산이 있습니다! 깨어난 폭풍을 위하여!', '우리에게도 승산이 있습니다! 깨어난 폭풍을 위하여!', 28153),
(151837, 'koKR', '멍청이들! 이미 나의 힘으로 고대 영혼은 우리 주인님의 뜻에 속박됐다.', '', 28153),
(151836, 'koKR', '폭풍의 노래가 들리는군요. 희망이 있습니다!', '폭풍의 노래가 들리는군요. 희망이 있습니다!', 28153),
(151835, 'koKR', '저기 다른 사람들도 있습니다. 아직 희망이 있습니다!', '저기 다른 사람들도 있습니다. 아직 희망이 있습니다!', 28153),
(151834, 'koKR', '무슨 암흑 마법이 뿌리내린지는 모르지만, 그걸 해제하는 법을 알아내야 해요.', '', 28153),
(151833, 'koKR', '우리답지 않았군요. 아직 스톰송 군주를 막을 수 있습니다!', '우리답지 않았군요. 아직 스톰송 군주를 막을 수 있습니다!', 28153),
(151832, 'koKR', '조사한 바에 따르면 여기가 잔달라의 초대 왕이 잠든 바로 그곳이에요.', '', 28153),
(151831, 'koKR', '관문이 부서졌다. 진군하라! 얼라이언스를 위해 아라시를 탈환하라!', '', 28153),
(151830, 'koKR', '파이크 님이 살아계시다고요? 당장 만나러 가야겠습니다!', '파이크 님이 살아계시다고요? 당장 만나러 가야겠습니다!', 28153),
(151829, 'koKR', '관문은 함락되었습니다. 지금입니다! 호드 녀석들에게서 아라시를 탈환하십시오!', '', 28153),
(151828, 'koKR', '됐다, 문이 파괴됐군! 쳐들어가자!', '', 28153),
(151827, 'koKR', '', '성문이 무너졌다! 진격해라!', 28153),
(151826, 'koKR', '성문이 부서졌다! 요새를 휩쓸어버려라!', '', 28153),
(151825, 'koKR', '잔달라를 위해... 그리고 너희 왕국을 위해... 놈을 막아야 한다.', '', 28153),
(151824, 'koKR', '성문이 함락되었다! 녀석들의 진영을 차지해라!', '', 28153),
(151823, 'koKR', '당장 폭풍의 사원을 열어야 합니다!', '당장 폭풍의 사원을 열어야 합니다!', 28153),
(151822, 'koKR', '지금도 놈의 주인은 힘을 모으고 있다. 혈신이 세상을 장악할 때까지 줄은 쉬지 않을 것이다.', '', 28153),
(151821, 'koKR', '다 끝났다. 아라시는 다시 우리 차지가 되었다. 얼라이언스를 위하여!', '', 28153),
(151820, 'koKR', '제 안의 폭풍이 깨어납니다. 어둠에 맞설 겁니다!', '제 안의 폭풍이 깨어납니다. 어둠에 맞설 겁니다!', 28153),
(151819, 'koKR', '', '우린 승리할 수밖에 없었다. 호드를 위하여!', 28153),
(151818, 'koKR', '잔인한 운명에서 나를 풀어주었지만, 줄은 거대한 음모의 꼭두각시일 뿐이다.', '', 28153),
(151817, 'koKR', '네 주인에게 기어가라. 가서 실패의 값을 치러라!', '', 28153),
(151816, 'koKR', '이 날이 올 줄 알았습니다. 다른 이들과 합류하겠습니다.', '이 날이 올 줄 알았습니다. 다른 이들과 합류하겠습니다.', 28153),
(151815, 'koKR', '말도 안 돼! 그훈 님을 거부할 순 없다!', '', 28153),
(151814, 'koKR', '줄의 속박이 풀렸다! 더는 그놈을 섬기지 않아도 된다!', '', 28153),
(151813, 'koKR', '얼마든지 푸념하라, 왕이여... 하지만 그훈 님을 벗어날 수 없다는 걸 알았어야지.', '', 28153),
(151812, 'koKR', '침입자들은 죽으리라... 거기에 네놈의 수다를 들을 필요 없다.', '', 28153),
(151811, 'koKR', '나는 생전에 네 주인에게 맞섰다. 그런데 넌 죽은 나를 그에게 속박시켰지.', '', 28153),
(151810, 'koKR', '닥쳐라, 거짓 예언자!', '', 28153),
(151809, 'koKR', '이곳은 잔달라 최초의 왕이 잠든 곳이다. 다자르는 완고했지만... 이제 그도 종복이 되었지!', '', 28153),
(151808, 'koKR', '제 정신이십니까?', '제 정신이십니까?', 28153),
(151807, 'koKR', '말씀하십시오.', '말씀하십시오.', 28153),
(151806, 'koKR', '하지만 사후에는 내가 하나의 목적에 묶어 놨지. 널 죽이도록 말이야.', '', 28153),
(151805, 'koKR', '대지가 날 받아들인다.', '대지가 날 받아들인다.', 28153),
(151804, 'koKR', '저들은 평생 서로를 증오하다, 결국 서로를 파멸시켰지.', '', 28153),
(151803, 'koKR', '너흰 곧 홀로 왕좌를 차지할 수 없던 시절, 제국을 다스렸던 세 명의 지배자들을 만나게 된다.', '', 28153),
(151802, 'koKR', '외부인은 여기 들어올 수 없습니다.', '외부인은 여기 들어올 수 없습니다.', 28153),
(151801, 'koKR', '바다가 물러나면 대지가 일어나리라!', '바다가 물러나면 대지가 일어나리라!', 28153),
(151800, 'koKR', '물론, 네놈을 처리하는 데에도 문제없을 거다.', '', 28153),
(151799, 'koKR', '사원에는 시체가 쌓여갔고, 우리는 골렘을 만들어 감염된 시체들을 처리하도록 했다.', '', 28153),
(151798, 'koKR', '수천 년 전, 피의 전염병이 잔달라를 전멸시킬 뻔했다.', '', 28153),
(151797, 'koKR', '그들은 곧 일어나고, 그훈 님을 대적하는 자는 쓰러지리라!', '', 28153),
(151796, 'koKR', '내 힘은 이미 뿌리를 내렸다. 고대 영혼이 주인님의 뜻을 따르도록 속박시켰지.', '', 28153),
(151795, 'koKR', '초대 트롤 왕의 무덤에 온 것을 환영한다. 직접 환대할 수 있다면 좋으련만.', '', 28153),
(151794, 'koKR', '이런 정신 나간 짓에 동참할 순 없다고, 내가 말하지 않았습니까!', '이런 정신 나간 짓에 동참할 순 없다고, 내가 말하지 않았습니까!', 28153),
(151793, 'koKR', '이번에는 속아 넘어가지 않을 겁니다.', '이번에는 속아 넘어가지 않을 겁니다.', 28153),
(151792, 'koKR', '정말... 안전합니까?', '정말... 안전합니까?', 28153),
(151791, 'koKR', '저희는 투자 자문이자 이주 전문가입니다. 붉은색을 뒤집어쓴 저 빌어먹을 용병과는 다릅니다. 저희는 해적이 아니니까요.', '', 28153),
(151790, 'koKR', '', '우리는 캐서린 님께 돌아가요.', 28153),
(151789, 'koKR', '', '거기 세 분! 수색대를 꾸려 추적해 주세요!', 28153),
(151788, 'koKR', '', '잠깐, 안 돼!', 28153),
(151787, 'koKR', '', '건방진 계집 같으니. 끝은 아직 멀었다!', 28153),
(151786, 'koKR', '', '끝이다. 이제 도망칠 곳은 없어.', 28153),
(151785, 'koKR', '', '비켜라, 멍청한 놈들아!', 28153),
(151784, 'koKR', '', '받아라!', 28153),
(151783, 'koKR', '', '그런 짓 해봐야 아무 의미 없다! 이 도시는 내 것이다!', 28153),
(151782, 'koKR', '돌아가는 길을 찾는 이들이 있을지 모르니 전 이곳에서 기다리겠습니다!', '', 28153),
(151781, 'koKR', '', '제가 우두머리가 되면 상황이 훨씬 좋아질 거예요.\n\n무쇠파도단 해적 놈들이 사라지면 모두들 이곳에서 물건을 사고팔 수 있을 테죠. 정말 멋질 거예요!', 28153),
(151780, 'koKR', '', '어휴! 저 붉은색으로 뒤덮인 머저리들이 나타나기 전이 더 좋았지요.', 28153),
(151779, 'koKR', '잠깐만요, 전 그저 생활비를 벌려는 것뿐입니다.', '', 28153),
(151778, 'koKR', '톤세일과 그의 무리가 사업에 악영향을 미치고 있습니다. 전 더 나빠지면 제 새들을 데리고 그냥 떠나버릴 생각도 하고 있지요.', '', 28153),
(151777, 'koKR', '부자가 될 수 있었는데...', '', 28153),
(151776, 'koKR', '우릴 방해하겠다고? 더 사소한 일로도 손에 피를 묻힌 나다!', '', 28153),
(151775, 'koKR', '', '넌 이 숲을 빼앗을 수 없다!', 28153),
(151774, 'koKR', '', '감사해요. 저 혼자서도 녀석들을 상대할 수 있으리라 생각했는데. 이제 모르윈 님에게 돌아갈게요.', 28153),
(151773, 'koKR', '당신 아주 멋있었어요.', '', 28153),
(151772, 'koKR', '우리 토르톨란은 매우 오래전부터 이곳에서 교역을 해왔습니다. 결과적으로 저희 주변에 잔달라 부족이 많아졌지만, 그들에게 어려운 시기가 찾아왔죠. 물론 저희는 인내할 것입니다.', '', 28153),
(151771, 'koKR', '전 여기서 일할게요. 위험한 길로 갈 필요 없어요.', '', 28153),
(151770, 'koKR', '록타르 오가르!', '록타르 오가르!', 28153),
(151769, 'koKR', '로크 나라쉬!', '로크 나라쉬!', 28153),
(151768, 'koKR', '가카라 마!', '가카라 마!', 28153),
(151767, 'koKR', '호드 앞에 무릎 꿇어라!', '호드 앞에 무릎 꿇어라!', 28153),
(151766, 'koKR', '호드를 위하여!', '호드를 위하여!', 28153),
(151765, 'koKR', '적들에게 죽음을!', '적들에게 죽음을!', 28153),
(151764, 'koKR', '오늘이 네 제삿날이다!', '오늘이 네 제삿날이다!', 28153),
(151763, 'koKR', '명예로운... 죽음이다...', '명예로운... 죽음이다...', 28153),
(151762, 'koKR', '하! 보고하러 온 게로군. 알겠네. 그것은 상자에 던져넣고 작업을 재개하게!', '', 28153),
(151761, 'koKR', '선조들이여... 제가 갑니다...', '선조들이여... 제가 갑니다...', 28153),
(151760, 'koKR', '너희는 이 전쟁에서... 패배할 것이다...', '너희는 이 전쟁에서... 패배할 것이다...', 28153),
(151759, 'koKR', '너도... 종말을 맞게 될 것이다...', '너도... 종말을 맞게 될 것이다...', 28153),
(151758, 'koKR', '전사로 태어나... 전사로 죽는다...', '전사로 태어나... 전사로 죽는다...', 28153),
(151757, 'koKR', '내 전투는... 끝났다...', '내 전투는... 끝났다...', 28153),
(151756, 'koKR', '내 영혼은... 드레노어로 돌아간다...', '내 영혼은... 드레노어로 돌아간다...', 28153),
(151755, 'koKR', '명예롭게 죽으십시오.', '명예롭게 죽으십시오.', 28153),
(151754, 'koKR', '더 할 얘기는 없습니다.', '더 할 얘기는 없습니다.', 28153),
(151753, 'koKR', '가십시오.', '가십시오.', 28153),
(151752, 'koKR', '명예롭게 가십시오.', '명예롭게 가십시오.', 28153),
(151751, 'koKR', '칼끝이 무뎌지지 않기를.', '칼끝이 무뎌지지 않기를.', 28153),
(151750, 'koKR', '나아가 승리를 차지하십시오.', '나아가 승리를 차지하십시오.', 28153),
(151749, 'koKR', '그럼 이만.', '그럼 이만.', 28153),
(151748, 'koKR', '말하십시오.', '말하십시오.', 28153),
(151747, 'koKR', '반갑습니다.', '반갑습니다.', 28153),
(151746, 'koKR', '록타르!', '록타르!', 28153),
(151745, 'koKR', '트롬카!', '트롬카!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151744, 'koKR', '무슨 일입니까?', '무슨 일입니까?', 28153),
(151743, 'koKR', '저그저그.', '저그저그.', 28153),
(151742, 'koKR', '힘과 명예를.', '힘과 명예를.', 28153),
(151741, 'koKR', '다음엔 더 많이 사십시오.', '다음엔 더 많이 사십시오.', 28153),
(151740, 'koKR', '잘 쓰시길 바랍니다.', '잘 쓰시길 바랍니다.', 28153),
(151739, 'koKR', '환불은 안 됩니다!', '환불은 안 됩니다!', 28153),
(151738, 'koKR', '뭘 찾고 있습니까?', '뭘 찾고 있습니까?', 28153),
(151737, 'koKR', '무엇이 필요합니까?', '무엇이 필요합니까?', 28153),
(151736, 'koKR', '둘러보십시오.', '둘러보십시오.', 28153),
(151735, 'koKR', '아제로스 사람들은 원래 이렇게 성가십니까?', '아제로스 사람들은 원래 이렇게 성가십니까?', 28153),
(151734, 'koKR', '전 저를 방해하는 것들의 목을 베는 게 취미인데, 그래도 계속 쿡쿡 찌를 겁니까?', '전 저를 방해하는 것들의 목을 베는 게 취미인데, 그래도 계속 쿡쿡 찌를 겁니까?', 28153),
(151733, 'koKR', '친구, 절 화나게 하지 마십시오. 감당하기 힘들어질 겁니다.', '친구, 절 화나게 하지 마십시오. 감당하기 힘들어질 겁니다.', 28153),
(151732, 'koKR', '오크... 주먹!!!!!', '오크... 주먹!!!!!', 28153),
