(151555, 'koKR', '거래할 수 없는 물건입니다.', '', 28153),
(151554, 'koKR', '사용할 수 없습니다.', '', 28153),
(151553, 'koKR', '착용해야 사용할 수 있습니다.', '', 28153),
(151552, 'koKR', '아니, 아라시는 내 것이다. 너와 호드 놈들은 침입한 대가를 치를 것이다, 아이트리그.', '', 28153),
(151551, 'koKR', '우선 착용해야 합니다.', '', 28153),
(151550, 'koKR', '트롤베인! 왔던 길로 돌아가라. 아라시는 이제 호드의 것이다.', '', 28153),
(151549, 'koKR', '하지만 먼저 이 진지를 보강해야 합니다. 목재와 철을 구해주십시오.', '', 28153),
(151548, 'koKR', '적을 쓸어버리십시오!', '', 28153),
(151547, 'koKR', '물론이지, 여군주 리아드린. 길을 벗어난 호드 성기사들에게 어서 정의를 구현해주고 싶구나.', '', 28153),
(151546, 'koKR', '대상을 공격하십시오!', '', 28153),
(151545, 'koKR', '놈들을 쓰러뜨리십시오!', '', 28153),
(151544, 'koKR', '이쪽입니다.', '', 28153),
(151543, 'koKR', '오크가 앞장서죠.', '', 28153),
(151542, 'koKR', '', '투랄리온이라? 이것 참... 재미있겠군...', 28153),
(151541, 'koKR', '따라오십시오.', '', 28153),
(151540, 'koKR', '호드를 위하여!', '', 28153),
(151539, 'koKR', '상처를 입었습니다!', '', 28153),
(151538, 'koKR', '절 고쳐주십시오, 치유사여!', '', 28153),
(151537, 'koKR', '멀뚱히 서 있지만 말고 도와주십시오!', '', 28153),
(151536, 'koKR', '도와주십시오!', '', 28153),
(151535, 'koKR', '여기 계십시오.', '', 28153),
(151534, 'koKR', '잠시 기다리십시오.', '', 28153),
(151533, 'koKR', '빛이 우리 편이다, 로칸. 어둠 따위는 두렵지 않다.', '', 28153),
(151532, 'koKR', '어둠을 조심해라, 투랄리온. 나와 호드가 지금 가고 있다...', '', 28153),
(151531, 'koKR', '명예로운 죽음을!', '', 28153),
(151530, 'koKR', '공격!', '', 28153),
(151529, 'koKR', '모크 토라 카!', '', 28153),
(151528, 'koKR', '모조리 쓸어버립시다!', '', 28153),
(151527, 'koKR', '네놈과 호드 군대를 아라시의 언덕에서 몰아낼 시간이지, 아이트리그.', '', 28153),
(151526, 'koKR', '놈들의 대열을 부수십시오!', '', 28153),
(151525, 'koKR', '후퇴 아니면 죽음 뿐입니다!', '', 28153),
(151524, 'koKR', '다음 전투를 기약합시다!', '', 28153),
(151523, 'koKR', '가세요! 달아나십시오!', '', 28153),
(151522, 'koKR', '전장 어딘가에서 얼라이언스 버러지 놈들 냄새가 나지 않나? 싸울 시간인가 보군.', '', 28153),
(151521, 'koKR', '준비하십시오!', '', 28153),
(151520, 'koKR', '종종 들리게. 저 상자에 든 철이 낭비되는 꼴은 보기 싫네.', '', 28153),
(151519, 'koKR', '모두 불태웁시다!', '', 28153),
(151518, 'koKR', '공격 개시!', '', 28153),
(151517, 'koKR', '곧 놈들이 올 테니 이 기지를 보강해야 하네. 그러려면 목재와 철을 확보해야겠지.', '', 28153),
(151516, 'koKR', '부어오른 궁둥이를 붙잡고 엉엉 울게 해주마. 호드 놈들! 하!', '', 28153),
(151515, 'koKR', '', '물러나라, 무라딘. 이곳은 호드의 영토다.', 28153),
(151514, 'koKR', '아니, 내 새 도끼날에 더러운 호드 무리의 목을 걸러 왔다!', '', 28153),
(151513, 'koKR', '여기서 뭘 하는 거냐, 무라딘? 시비라도 걸 셈인가?', '', 28153),
(151512, 'koKR', '네놈들이나 척박한 황무지로 돌아가지그래, 벼룩투성이 오크야!', '', 28153),
(151511, 'koKR', '무라딘! 네 드워프들이 국경을 침범했다. 너희들이 있던 산으로 돌아가라.', '', 28153),
(151510, 'koKR', '', '얼라이언스가 곧 옵니다. 신속하게 움직여야 합니다. 진지를 세울 수 있게 목재와 철을 확보하십시오.', 28153),
(151509, 'koKR', '', '착각하지 마라, 늙은이. 우린 스트롬가드를 탈환하러 왔다.', 28153),
(151508, 'koKR', '여군주 리아드린! 아라시에 온 것을 환영한다. 항복하러 왔나?', '', 28153),
(151507, 'koKR', '', '너무 오랫동안 자리를 비웠군, 투랄리온. 그사이 세상은 변했다.', 28153),
(151506, 'koKR', '이건 뭐야? 호드 침략병을, 성기사가 지휘해? 어떻게 된 세상이야?', '', 28153),
(151505, 'koKR', '', '해 볼 테면 해 봐라, 무라딘. 이제 이곳은 호드의 영토다.', 28153),
(151504, 'koKR', '거기 딱 멈추는 게 좋을 거다. 얼라이언스의 박격포탄을 제대로 맛보기 전에 말이지.', '', 28153),
(151503, 'koKR', '다나스 트롤베인... 네놈과는 끝내야 할 일이 있지! 이따가 전장에서 보자...', '', 28153),
(151502, 'koKR', '트롤 따위를 사령관으로 세우고 감히 아라시를 침공한다고? 큰 실수를 했군.', '', 28153),
(151501, 'koKR', '\"녹색 피부\"? 어허... 날 화나게 만드는군.', '', 28153),
(151500, 'koKR', '되찾는 중', '되찾는 중', 28153),
(151499, 'koKR', '<코웃음을 웃는 클라우스>\n\n네, 그러셨을 수도 있습니다. 이곳저곳에 상당한 수의 친척들이 살고 있으니까요.', '', 28153),
(151498, 'koKR', '감히 트롤베인 가의 고향인 스트롬가드를 침공하다니! 내 눈 앞에서 썩 꺼져라, 녹색 피부.', '', 28153),
(151497, 'koKR', '오늘 우리는 정당한 우리의 것을 되찾는다. 얼라이언스를 위하여!', '', 28153),
(151496, 'koKR', '스트롬가드는 오랜 시간 침략자의 손에 훼손되었다.', '', 28153),
(151495, 'koKR', '얼라이언스를 위하여!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151494, 'koKR', '얼라이언스의 병사들이여! 오늘, 잔학무도한 호드로부터 우리의 숭고한 도시 스트롬가드를 되찾는다.', '', 28153),
(151493, 'koKR', '오늘 아라시의 언덕을 탈환한다... 얼라이언스를 위하여!', '', 28153),
(151492, 'koKR', '소총을 장전하고 무기를 뽑아라.', '', 28153),
(151491, 'koKR', '', '아라시는 우리가 차지할 것이다! 호드를 위하여!', 28153),
(151490, 'koKR', '', '우선순위를 지키도록. 아르고로크부터 점령하고 스트롬가드로 진격해라!', 28153),
(151489, 'koKR', '페어윈드? 그 이름을 사용하는 사람을 만나본 적이 있습니다.', '페어윈드? 그 이름을 사용하는 사람을 만나본 적이 있습니다.', 28153),
(151488, 'koKR', '짐 챙겨라, 얘들아! 무기를 다른 곳으로 옮기자!', '', 28153),
(151487, 'koKR', '스트롬가드 요새가 성으로 강화되었습니다.', '', 28153),
(151486, 'koKR', '무기고 건설을 마쳤습니다.', '', 28153),
(151485, 'koKR', '이제 작업장이 준비됐습니다.', '', 28153),
(151484, 'koKR', '우리 마을회관이 성채로 강화되었습니다.', '', 28153),
(151483, 'koKR', '왕의 제단이 완성되었습니다.', '', 28153),
(151482, 'koKR', '아군의 성채가 성이 되었습니다!', '', 28153),
(151481, 'koKR', '무기고가 건설되었습니다.', '', 28153),
(151480, 'koKR', '이제 작업장에서 전차를 생산할 수 있습니다.', '', 28153),
(151479, 'koKR', '우리 마을회관이 성채로 강화되었습니다.', '', 28153),
(151478, 'koKR', '왕의 제단이 완성되었습니다.', '', 28153),
(151477, 'koKR', '좋아! 성채가 강화되어 성이 됐네!', '', 28153),
(151476, 'koKR', '이제 무기고에서 무기를 공급받을 수 있네!', '', 28153),
(151475, 'koKR', '작업장이 준비되었네. 전차를 생산할 시간이군!', '', 28153),
(151474, 'koKR', '마을회관이 강화되어 성채가 됐네!', '', 28153),
(151473, 'koKR', '왕의 제단이 준비되었네!', '', 28153),
(151472, 'koKR', '', '이제 보루는 요새가 되었습니다! 호드를 위하여!', 28153),
(151471, 'koKR', '', '새 무기고 덕분에 더 좋은 장비를 갖출 수 있겠군요.', 28153),
(151470, 'koKR', '', '작업장이 완공됐습니다.', 28153),
(151469, 'koKR', '', '기지가 강화되었습니다. 아군의 전당이 보루가 되었습니다.', 28153),
(151468, 'koKR', '', '폭풍의 제단이 준비되었습니다.', 28153),
(151467, 'koKR', '이제 병영에서 부대를 훈련할 수 있습니다.', '', 28153),
(151466, 'koKR', '아군 병영이 완공됐습니다. 부대를 훈련할 차례입니다.', '', 28153),
(151465, 'koKR', '병영이 생겼네! 병사를 훈련하세!', '', 28153),
(151464, 'koKR', '', '이제 병영에서 부대를 훈련할 수 있습니다.', 28153),
(151463, 'koKR', '보루가 이제 요새가 되었네!', '', 28153),
(151462, 'koKR', '전당을 보루로 강화시켰네.', '', 28153),
(151461, 'koKR', '폭풍의 제단이 준비되었네.', '', 28153),
(151460, 'koKR', '병영이 준비되었네. 이 전쟁의 승리는 그런트에게 달렸다네.', '', 28153),
(151459, 'koKR', '보루가 이제 요새가 되었네!', '', 28153),
(151458, 'koKR', '전당이 보루가 되었네!', '', 28153),
(151457, 'koKR', '폭풍의 제단이 완성되었네.', '', 28153),
(151456, 'koKR', '병영을 마련했으니 이제 그런트를 훈련시키게!', '', 28153),
(151455, 'koKR', '', '어림도 없다. 혈기사들이여, 저들을 물리쳐라!', 28153),
(151454, 'koKR', '나 역시 괜히 어둠사냥꾼이라 불리는 게 아니다. 지금이다, 암살단이여, 모습을 드러내라!', '', 28153),
(151453, 'koKR', '\"얼라이언스의 정의\"라면 잘 알고 있지. 와이번 기수들아, 호드의 분노가 무엇인지 보여주어라!', '', 28153),
(151452, 'koKR', '', '닥쳐라!', 28153),
(151451, 'koKR', '이 땅에 네 것은 없다, 트롤베인. 트롤이 너보다 훨씬 오래 전부터 이곳에 있었다.', '', 28153),
(151450, 'koKR', '하! 그건 네놈 생각이지.', '', 28153),
(151449, 'koKR', '', '네 가식도 이제 지긋지긋하군. 혈기사들이여, 빛의 분노로 저들을 물리쳐라!', 28153),
(151448, 'koKR', '빛은 이제 널 구해줄 수 없다. 어둠사냥꾼이여, 모습을 드러내라!', '', 28153),
(151447, 'koKR', '와이번 기수들이여, 공습을 가하라!', '', 28153),
(151446, 'koKR', '', '그건 모를 일이지, 투랄리온. 아직 내가 남아 있거든.', 28153),
(151445, 'koKR', '얼마든지 기다려 주지.', '', 28153),
(151444, 'koKR', '내가 그렇게 둘까 보냐, 투랄리온.', '', 28153),
(151443, 'koKR', '', '소용 없다, 드워프. 혈기사들이여, 위치로!', 28153),
(151442, 'koKR', '덫에 걸려들었구나, 무라딘. 어둠사냥꾼이여, 모습을 드러내라!', '', 28153),
(151441, 'koKR', '지금이다, 와이번 기수들이여! 공격!', '', 28153),
(151440, 'koKR', '', '헛소리.', 28153),
(151439, 'koKR', '각오하는 게 좋을 거다, 무라딘!', '', 28153),
(151438, 'koKR', '오래가진 못할 것이다, 드워프. 호드를 위하여!', '', 28153),
(151437, 'koKR', '한 번 잃었던 이 도시를 다신 잃지 않겠다. 특히 너희 같은 족속에겐 말이지. 수비대, 놈들에게 스트롬가드의 힘을 보여줘라!', '', 28153),
(151436, 'koKR', '이제 전 안전해요. 일하러 갈게요.', '', 28153),
(151435, 'koKR', '빛이 함께한다. 수비대, 전진!', '', 28153),
(151434, 'koKR', '난 최후까지 스트롬가드 요새를 지킬 것이오, 리아드린. 버텨라!', '', 28153),
(151433, 'koKR', '축하는 미뤄둬라, 블러드 엘프. 아직 내가 남아 있다.', '', 28153),
(151432, 'koKR', '그래... 기대하고 있겠다.', '', 28153),
(151431, 'koKR', '하! 고지를 얻은 게 다는 아니다!', '', 28153),
(151430, 'koKR', '멍청한 늙은이 주제에 잔재주는 잘도 남아 있구나, 트롤. 수비대, 스트롬가드의 힘을 보여줘라!', '', 28153),
(151429, 'koKR', '빛은 언제나 어둠을 이긴다, 로칸. 수비대, 앞으로!', '', 28153),
(151428, 'koKR', '덤벼라, 로칸! 기다리고 있었다! 우리가 누군지 놈들에게 똑똑히 보여줘라!', '', 28153),
(151427, 'koKR', '그 입 다물어라, 트롤. 얼라이언스는 네 더러운 괴물 군대에게 승리할 것이다.', '', 28153),
(151426, 'koKR', '하지만, 스트롬가드에는 아직 빛이 드리운다.', '', 28153),
(151425, 'koKR', '곧 상대해주마. 그전에 우리 소총병이 너희를 손봐줄 것이다.', '', 28153),
(151424, 'koKR', '스트롬가드는 건재하다, 오크. 네 시체가 못에 떠다니면 참 볼만하겠군. 수비대, 놈들에게 우리 도시의 힘을 보여줘라!', '', 28153),
(151423, 'koKR', '난 너보다 수천 번은 더 많은 전투에서 승패를 맛보았다, 아이트리그. 이번 전투는 패배와는 거리가 멀지. 수비대, 앞으로!', '', 28153),
(151422, 'koKR', '여기까지 오는 게 먼저 아니겠나, 애송이! 놈들을 밀어내라!', '', 28153),
(151421, 'koKR', '흥, 너나 네 족속 모두 똑같구나. 나머지 놈들처럼 무릎 꿇은 채 죽게 될 것이다.', '', 28153),
(151420, 'koKR', '보채지 마라, 오크여. 조만간 보게 될 것이니.', '', 28153),
(151419, 'koKR', '네 입냄새는 이 밑에까지 나는구나! 덤벼라, 오크 녀석아!', '', 28153),
(151418, 'koKR', '이제 공성 전차로 저 성문을 날려 버려라. 저 블러드 엘프의 머리를 창에 꿰어 두겠다!', '', 28153),
(151417, 'koKR', '이제 공성 전차로 저 성문을 날려 버리고 로칸을 잡아 와라! 괜히 이 몸을 트롤베인이라고 부르는 것이 아니지...', '', 28153),
(151416, 'koKR', '자, 공성 전차로 관문을 날려 버려라. 이 건방진 오크들은 얼라이언스의 정의가 무엇인지 알게 되리라!', '', 28153),
(151415, 'koKR', '높은 감시대는 우리 차지다. 마지막 기회다, 블러드 엘프. 항복하면 목숨만은 살려줄 수도 있다.', '', 28153),
(151414, 'koKR', '높은 감시대를 확보했다. 곧 아르고로크를 점령하고 정당한 우리 것을 탈환할 것이다!', '', 28153),
(151413, 'koKR', '높은 감시대는 우리 것이다. 침입자들을 상대하는 건 일도 아니지.', '', 28153),
(151412, 'koKR', '갤슨의 광맥을 차지하면 철 보급이 끊임없이 이루어집니다. 분명 유용할 것입니다.', '', 28153),
(151411, 'koKR', '좋습니다. 고원 제재소가 스트롬가드 재건에 필요한 목재를 제공할 겁니다.', '', 28153),
(151410, 'koKR', '기회가 왔습니다. 문을 포위하십시오! 호드 침략자들을 응징할 때입니다!', '', 28153),
(151409, 'koKR', '기회가 왔습니다. 성문을 포위하십시오! 빛이 너를 벌하러 왔다, 로칸!', '', 28153),
(151408, 'koKR', '기회가 왔습니다. 성문을 포위하십시오! 넌 끝장이다, 아이트리그!', '', 28153),
(151407, 'koKR', '높은 감시대를 점령했습니다. 빛이 얼라이언스와 함께합니다.', '', 28153),
(151406, 'koKR', '높은 감시대는 우리 것입니다. 다음은 아르고로크입니다. 각오하고 기다리거라, 로칸.', '', 28153),
(151405, 'koKR', '높은 감시대를 확보했습니다. 머지않아 호드 병력을 완전히 없애버릴 겁니다.', '', 28153),
(151404, 'koKR', '잘 하셨습니다. 갤슨의 광맥이라면 필요한 철을 모두 충당할 수 있을 것입니다.', '', 28153),
(151403, 'koKR', '제재소의 목재는 기지 건설에 요긴하게 쓰일 겁니다.', '', 28153),
(151402, 'koKR', '어서 공성 전차를 가져와라! 관문을 파괴해! 블러드엘프 녀석들에게 드워프 박격포 맛을 보여줘라!', '', 28153),
(151401, 'koKR', '어서 공성 전차를 가져와라! 관문을 파괴해! 트롤 놈들의 오두막을 잿더미로 만들어버려라!', '', 28153),
(151400, 'koKR', '어서 공성 전차를 가져와라! 관문을 파괴해! 저 오크들을 가루로 만들어버려라!', '', 28153),
(151399, 'koKR', '높은 감시대는 얼라이언스 것이다! 백기를 흔들 준비가 되었느냐, 애송아?', '', 28153),
(151398, 'koKR', '높은 감시대를 점령했다! 이제 네놈 차례로구나, 로칸.', '', 28153),
(151397, 'koKR', '허... 술집 외상도 못 갚고 죽네...', '허... 술집 외상도 못 갚고 죽네...', 28153),
(151396, 'koKR', '높은 감시대는 우리 것이다!', '', 28153),
(151395, 'koKR', '혹시... 거래할 생각은 없나...', '혹시... 거래할 생각은 없나...', 28153),
(151394, 'koKR', '갤슨의 광맥을 손에 넣었으니, 철은 넉넉할 걸세.', '', 28153),
(151393, 'koKR', '훌륭하군. 고원 제재소를 확보했네. 저 목재로 기지를 지을 수 있을 걸세.', '', 28153),
(151392, 'koKR', '', '이 싸움에는 기술이 필요하다. 네놈은 그게 부족하구나!', 28153),
(151391, 'koKR', '', '파괴전차를 가져와! 저 문을 파괴하자! 스트롬가드를 산산조각 내라!', 28153),
(151390, 'koKR', '상관 말라고, 친구!', '상관 말라고, 친구!', 28153),
(151389, 'koKR', '', '파괴전차를 가져와라! 저 문을 파괴해야 한다! 네 최후의 시간이다, 투랄리온!', 28153),
(151388, 'koKR', '원하는 게 뭔데 깔작대는 거야?', '원하는 게 뭔데 깔작대는 거야?', 28153),
(151387, 'koKR', '', '파괴전차를 가져와 저 문을 파괴해라! 드워프가 직접 행차하게 만들어라!', 28153),
(151386, 'koKR', '', '높은 감시대는 우리 것이다! 머지않아 호드가 아라시를 정복할 것이다!', 28153),
(151385, 'koKR', '', '높은 감시대는 우리가 차지했다! 호드 군대가 곧 들이닥칠 것이다, 투랄리온.', 28153),
(151384, 'koKR', '', '높은 감시대를 점령했으니, 고지를 확보한 셈이지. 전세가 우리 쪽으로 기울고 있다.', 28153),
(151383, 'koKR', '', '수고하셨습니다. 저 광산의 철 없인 전진하기 어렵죠.', 28153),
(151382, 'koKR', '죽어서도 형편없구나! 비켜라, 위대함을 직접 목격하라!', '', 28153),
(151381, 'koKR', '', '손도끼 마루에서 구한 목재로 아군 기지의 토대를 세울 것입니다. 잘하셨습니다.', 28153),
(151380, 'koKR', '파괴전차를 보내 저 문을 파괴해라! 저 멍청한 트롤베인의 머리를 내게 가져라와!', '', 28153),
(151379, 'koKR', '파괴전차를 보내라! 그 어떤 빛도 호드의 힘으로부터 저 성기사를 보호하지 못하리라!', '', 28153),
(151378, 'koKR', '파괴전차를 보내라! 저 드워프 놈이 언제까지 저렇게 숨어 있나 보자!', '', 28153),
(151377, 'koKR', '높은 감시대는 호드에 함락되었다, 트롤베인.', '', 28153),
(151376, 'koKR', '높은 감시대는 우리 것이다, 투랄리온. 어둠이 점점 다가온다...', '', 28153),
(151375, 'koKR', '무라딘... 우리가 높은 감시대를 점령했다. 싸울 준비가 더 필요하느냐?', '', 28153),
(151374, 'koKR', '호드가 마른수염 광산을 차지했네.', '', 28153),
(151373, 'koKR', '', '흥. 살아서도 죽어서도 쓸모없는 놈들 같으니. 내가 직접 처리하겠다!', 28153),
(151372, 'koKR', '좋아. 손도끼 마루에서 구한 목재로 아군 보루를 세울 걸세.', '', 28153),
(151371, 'koKR', '파괴전차를 가져와 저 문을 부숴버려라! 멍청한 트롤베인에게 녹색 피부가 무얼 할 수 있는지 똑똑히 보여주자!', '', 28153),
(151370, 'koKR', '', '용맹한 이로 자랐구나, 탤리아. 네 아버지가 자랑스러워 하실 게다.', 28153),
(151369, 'koKR', '파괴전차를 가져와 저 문을 부숴버려라! 이 전투는 끝난 것이나 다름없다!', '', 28153),
(151368, 'koKR', '파괴전차를 가져와 저 문을 부숴버려라! 저 드워프의 썩은 머리통을 창끝에 걸어둘 것이다!', '', 28153),
(151367, 'koKR', '대장이 좋아하지 않겠군...', '대장이 좋아하지 않겠군...', 28153),
(151366, 'koKR', '높은 감시대는 호드의 것이다. 아, 차라리 \"녹색 피부\"의 것이라 할까?', '', 28153),
(151365, 'koKR', '높은 감시대는 우리 것이다. 응징은 아직이냐, 투랄리온? 기다리게 하는군...', '', 28153),
(151364, 'koKR', '으억...', '으억...', 28153),
(151363, 'koKR', '개인적인 감정은... 없었...', '개인적인 감정은... 없었...', 28153),
(151362, 'koKR', '높은 감시대를 점령했다. 무라딘! 네놈의 주먹코는 위에서도 잘 보이는군!', '', 28153),
(151361, 'koKR', '해야 할 일을... 했을 뿐...', '해야 할 일을... 했을 뿐...', 28153),
(151360, 'koKR', '', '아아, 탤리아... 바다 건너 왔던 그 아이구나. 벌써 세월이 그리 흘렀단 말인가?', 28153),
(151359, 'koKR', '잘했네. 마른수염 광산이 수중에 들어왔으니 철이 부족할 일은 없을 걸세.', '', 28153),
(151358, 'koKR', '손도끼 마루는 우리 것이네. 그곳의 제재소를 이용해 기지를 지을 수 있을 걸세.', '', 28153),
(151357, 'koKR', '개인적인 감정은 없지만, 우리도 규칙이란 게 있어서 말이지!', '개인적인 감정은 없지만, 우리도 규칙이란 게 있어서 말이지!', 28153),
(151356, 'koKR', '밸러콜의 길은 이제 우리 것입니다. 계속 공격하십시오!', '', 28153),
(151355, 'koKR', '', '탤리아입니다.', 28153),
(151354, 'koKR', '잘하셨습니다. 정령의 마법진을 탈환했습니다.', '', 28153),
(151353, 'koKR', '뉴스테드에 다시금 얼라이언스 깃발이 휘날리는군요.', '', 28153),
(151352, 'koKR', '', '좋소. 그대의 이름은?', 28153),
(151351, 'koKR', '밸러콜의 길을 확보했습니다.', '', 28153),
(151350, 'koKR', '정령의 마법진은 이제 얼라이언스의 것입니다.', '', 28153),
(151349, 'koKR', '잘하셨습니다. 뉴스테드는 우리 것입니다.', '', 28153),
(151348, 'koKR', '그만 하라고!', '그만 하라고!', 28153),
(151347, 'koKR', '', '제독님, 요새로 모셔다 드리겠습니다. 거기서 애쉬베인 가문에 대한 증거를 정리해 드리겠습니다.', 28153),
(151346, 'koKR', '좋아, 놈들을 밸러콜의 길까지 밀어붙였군. 계속 움직이세나!', '', 28153),
(151345, 'koKR', '정령의 마법진을 확보했네!', '', 28153),
(151344, 'koKR', '선을 넘었군!', '선을 넘었군!', 28153),
(151343, 'koKR', '뉴스테드를 확보했네!', '', 28153),
(151342, 'koKR', '', '정령의 마법진은 우리 것입니다.', 28153),
(151341, 'koKR', '', '뉴스테드를 점령했습니다.', 28153),
(151340, 'koKR', '문제를 일으키는 놈들을 상대하는 우리만의 방법이 있지!', '문제를 일으키는 놈들을 상대하는 우리만의 방법이 있지!', 28153),
(151338, 'koKR', '', '아, 이제 좀 숨통이 트이는군요.', 28153),
(151337, 'koKR', '이봐!', '이봐!', 28153),
(151336, 'koKR', '어둠을 조심해라, 얼라이언스 쓰레기 놈들아. 호드가 간다...', '', 28153),
(151335, 'koKR', '수고했네. 북부습곡 십자로를 점령했으니 더 중요한 표적에 집중할 수 있을 걸세.', '', 28153),
(151333, 'koKR', '', '그대여! 한마디 해도 되겠소?', 28153),
(151332, 'koKR', '셀 수 없을 만큼 기나긴 세월 동안 복수의 날을 기다렸다. 네 어미가 그 기회를 제공했지.', '', 28153),
(151331, 'koKR', '네 선조들이 우리 부족을 쓸어버렸으나, 나를 파괴하지는 못했다.', '', 28153),
(151330, 'koKR', '', '고라크 툴? 어떻게 이런 일이? 넌 오래전에 조상님들의 손에 사라졌는데!', 28153),
(151329, 'koKR', '공성 전차, 저 기지를 파괴하라!', '', 28153),
(151328, 'koKR', '경고하지 않았나, 한심한 호드여. 이제 말살될 각오를 해라.', '', 28153),
(151327, 'koKR', '이곳의 얼라이언스의 땅이다! 빛의 축복이 담긴 스트롬가드 성벽이 너희에게 무너질 일은 없다.', '', 28153),
(151326, 'koKR', '저기 전장에 보이는 게 호드가 맞나? 한 판 붙어보고 싶었던 참이거든!', '', 28153),
(151324, 'koKR', '그대가 놈들을 막고... 저 아제라이트를 흡수하여 심장을 강화해야 하네!', '', 28153),
(151323, 'koKR', '아제로스의 땅에 계속해서 상처가 벌어지고... 야욕을 위해 아제라이트를 손에 넣으려는 세력도 늘어나고 있네.', '', 28153),
(151322, 'koKR', '아제로스의 심장이 우리 세계를 치유할 열쇠일세... 하지만 그럴 기회라도 얻으려면 힘을 더 많이 모아야 하지.', '', 28153),
(151321, 'koKR', '마그니, 아제로스의 심장을 강화할 준비가 됐습니다.', '마그니, 아제로스의 심장을 강화할 준비가 됐습니다.', 28153),
(151320, 'koKR', '용사여, 실리더스에서 할 얘기가 있네. 우리 세계를 치유하기 위해 해야 할 일이 더 있네!', '', 28153),
(151319, 'koKR', '', '지금 빗자루 들었어! 진짜 휘두른다!', 28153),
(151318, 'koKR', '', '저리 가, 하늘의 쥐새끼 같은 놈들!', 28153),
(151317, 'koKR', '', '내 집에서 나가!', 28153),
(151316, 'koKR', '', '여기서 썩 꺼져, 더러운 놈들아!', 28153),
(151315, 'koKR', '목숨을 내놔라!', '', 28153),
(151314, 'koKR', '악몽의 괴수여, 나오거라!', '', 28153),
(151313, 'koKR', '느낌이 왔어. 오늘은 찾을 수 있을 거야.', '느낌이 왔어. 오늘은 찾을 수 있을 거야.', 28153),
(151312, 'koKR', '그 장화 마음에 드는걸?', '그 장화 마음에 드는걸?', 28153),
(151311, 'koKR', '두 동강을 내주마!', '두 동강을 내주마!', 28153),
(151310, 'koKR', '여기서는 누구도 널 구해줄 수 없다.', '여기서는 누구도 널 구해줄 수 없다.', 28153),
(151309, 'koKR', '발 조심해라.', '발 조심해라.', 28153),
(151308, 'koKR', '산산조각 내 주마...', '산산조각 내 주마...', 28153),
(151307, 'koKR', '두고 봐라...', '두고 봐라...', 28153),
(151306, 'koKR', '그 자원은 네놈들 것이 아니다!', '그 자원은 네놈들 것이 아니다!', 28153),
(151305, 'koKR', '새로운 돈벌이로군!', '새로운 돈벌이로군!', 28153),
(151304, 'koKR', '대양이 솟구친다! 하수인이여, 일어나라!', '', 28153),
(151303, 'koKR', '엄습하는 공포여, 와서 배를 채우거라!', '', 28153),
(151302, 'koKR', '심연의 생명체여, 내 부름에 응하라!', '', 28153),
(151301, 'koKR', '여긴 공기가 좋네요. 오크가 득실대는 광산과는 달라요.', '', 28153),
(151300, 'koKR', '어둠이 널 거두리라!', '', 28153),
(151299, 'koKR', '슬슬 싫증이 나는군. 그만 최후를 맞이해라!', '', 28153),
(151298, 'koKR', '아즈샤라 님의 하수인은 무한하다. 왜 저항하느냐?', '', 28153),
(151297, 'koKR', '이제 안 무서워요. 그런데 바위 때문에 팔이 아파요.', '', 28153),
(151295, 'koKR', '이제 속삭임이 들리나보군. 시간이 얼마 없소.', '', 28153),
(151294, 'koKR', '', '금방 따라갈게요. 기다리지 마세요!', 28153),
(151293, 'koKR', '파도 저 아래... 기다리는... 부름이...', '', 28153),
(151292, 'koKR', '여기에요. 여기서 철을 구해요.', '', 28153),
(151291, 'koKR', '주변에서 무기 선반을 찾아보십시오. 부정한 자들이 곳곳에 배치해 두었으니까요.\n\n전 당신이 오실 때까지 몸을 숨기고 있겠습니다.', '주변에서 무기 선반을 찾아보십시오. 부정한 자들이 곳곳에 배치해 두었으니까요.\n\n전 당신이 오실 때까지 몸을 숨기고 있겠습니다.', 28153),
(151290, 'koKR', '', '바람이여, 나를 보호하라!', 28153),
(151289, 'koKR', '사용할 만한 무기를 찾으면 돌아오겠습니다.', '사용할 만한 무기를 찾으면 돌아오겠습니다.', 28153),
(151288, 'koKR', '', '순풍이 언제나 우리와 함께한다!', 28153),
(151287, 'koKR', '아주 산산조각을 내주마!', '', 28153),
(151286, 'koKR', '내 배는 무적이다!', '', 28153),
(151285, 'koKR', '정령의 분노가 끓어오른다!', '정령의 분노가 끓어오른다!', 28153),
(151284, 'koKR', '필멸자 도둑놈들의 목숨을 거두어주마.', '필멸자 도둑놈들의 목숨을 거두어주마.', 28153),
(151283, 'koKR', '너희가 훔쳐간 모든 것을 되찾겠다!', '너희가 훔쳐간 모든 것을 되찾겠다!', 28153),
(151282, 'koKR', '정령이 지배하리라!', '정령이 지배하리라!', 28153),
(151281, 'koKR', '너희는 절대 가질 수 없을 것이다!', '너희는 절대 가질 수 없을 것이다!', 28153),
(151280, 'koKR', '이 보석은 정령 군주님의 것이다!', '이 보석은 정령 군주님의 것이다!', 28153),
(151279, 'koKR', '<노예를 풀어주고 전투에 사용할 무기를 줍니다.>', '<노예를 풀어주고 전투에 사용할 무기를 줍니다.>', 28153),
(151278, 'koKR', '이 힘으로 세상을 다시 차지하겠다!', '이 힘으로 세상을 다시 차지하겠다!', 28153),
(151277, 'koKR', '<노예를 풀어주고 전투에 사용할 무기를 줍니다.>', '<노예를 풀어주고 전투에 사용할 무기를 줍니다.>', 28153),
(151276, 'koKR', '너를 파괴하면 나의 군주께서 상을 내리실 것이다.', '너를 파괴하면 나의 군주께서 상을 내리실 것이다.', 28153),
(151275, 'koKR', '무기를 주시면 부정한 자들 열 놈을 죽여 드리겠습니다.', '무기를 주시면 부정한 자들 열 놈을 죽여 드리겠습니다.', 28153),
(151274, 'koKR', '물건을 챙기십시오. 저와 함께 가셔야 합니다.', '물건을 챙기십시오. 저와 함께 가셔야 합니다.', 28153),
(151273, 'koKR', '이 족쇄를 부숴주십시오, 친구여. 불페라는 본디 자유로운 존재입니다.', '이 족쇄를 부숴주십시오, 친구여. 불페라는 본디 자유로운 존재입니다.', 28153),
(151272, 'koKR', '일하고 싶은데 너무 위험해요.', '', 28153),
(151271, 'koKR', '절 풀어주십시오, $pr님. 그러면 부정한 자들을 처치하는 걸 돕겠습니다.', '절 풀어주십시오, $pr님. 그러면 부정한 자들을 처치하는 걸 돕겠습니다.', 28153),
(151270, 'koKR', '부정한 자들에게 자비란 없습니다. 그들이 한 짓을 보십시오.', '부정한 자들에게 자비란 없습니다. 그들이 한 짓을 보십시오.', 28153),
(151269, 'koKR', '부정한 자들이 내게 한 짓의 대가를 치르게 하겠습니다.', '부정한 자들이 내게 한 짓의 대가를 치르게 하겠습니다.', 28153),
(151268, 'koKR', '니샤가 보낸 분인가요? 어떤 계획이든 동참하겠습니다.', '니샤가 보낸 분인가요? 어떤 계획이든 동참하겠습니다.', 28153),
(151267, 'koKR', '무기만 마련해 주십시오, 친구여. 그러면 제가 나머지를 처리하겠습니다.', '무기만 마련해 주십시오, 친구여. 그러면 제가 나머지를 처리하겠습니다.', 28153),
(151266, 'koKR', '무기만 있으면 됩니다.', '무기만 있으면 됩니다.', 28153),
(151265, 'koKR', '안 돼... 보석은 내 것이다... 어디 손을... 대느냐...', '', 28153),
(151264, 'koKR', '안 돼! 어리석은 놈!', '', 28153),
(151263, 'koKR', '네가... 이긴 것이... 아니다...', '', 28153),
(151262, 'koKR', '다시 돌아오리라!', '', 28153),
(151261, 'koKR', '우리의 때가 도래한다...', '', 28153),
(151260, 'koKR', '잠시 미뤄질 뿐... 피할 수 없다...', '', 28153),
(151259, 'koKR', '혼돈을... 가둘 수는 없다...', '', 28153),
(151258, 'koKR', '정령은... 막을 수 없다...', '', 28153),
(151257, 'koKR', '너희 봉인은 무너지고 하늘은 갈라지며 산은 솟아오를 것이다. 그리고 우리가 돌아올 것이다!', '', 28153),
(151256, 'koKR', '정령의 새벽이 도래할 것이다!', '', 28153),
(151255, 'koKR', '너희는 이제 끝이다, 필멸자여.', '', 28153),
(151254, 'koKR', '이 보석으로 기어코 너희를 파멸시키고 말겠다.', '', 28153),
(151253, 'koKR', '정령이 다시 지배할 것이다!', '', 28153),
(151252, 'koKR', '황금 광물이 우리에게 힘을 준다!', '', 28153),
(151251, 'koKR', '너희 세계는 다시 우리 차지가 될 거다!', '', 28153),
(151250, 'koKR', '내 세계에서 감히 내게 대적하는 것이냐!', '', 28153),
(151249, 'koKR', '여기 보세요. 짐이 너무 많아요!', '', 28153),
(151248, 'koKR', '절 오그리마로 보내주십시오.', '절 오그리마로 보내주십시오.', 28153),
(151247, 'koKR', '', '$n 님, 만나서 반가워요. 지금 제가 여기에 있는 이유는 크라그와 님과 가까이 있기 위해서예요.\n\n전 제 부모님께 그 개구리 로아에 관한 여러 이야기를 듣고 있답니다. 혈트롤에게서 그분을 지켜드릴 수 있어서 영광이에요.', 28153),
(151246, 'koKR', '이걸로 충분합니다. 감사합니다!', '이걸로 충분합니다. 감사합니다!', 28153),
(151245, 'koKR', '용사여, 포화를 이어갈 수 있도록, 제게 포탄을 가져다 주십시오.', '용사여, 포화를 이어갈 수 있도록, 제게 포탄을 가져다 주십시오.', 28153),
(151244, 'koKR', '', '드레나... 아니, 드레노이... 아니, 드레노어, 드레노어요! <한숨> 앞으로 그냥 제 고향은 아웃랜드라고 말할래요.', 28153),
(151243, 'koKR', '', '저는 타락하지 않은 오크 맞아요. 하지만 저는 스스로를 유기농 오크라 여기는 편이죠.', 28153),
(151242, 'koKR', '', '한번은 머리를 녹색으로 염색했었죠. 헬스크림 대족장님께서 전혀 기뻐하지 않으시더군요.', 28153),
(151241, 'koKR', '', '이런 고만고만하고 들으나 마나 한 잡담은 이제 그만! 그냥 뭐든 두들겨 패게 좀 내버려 둬요!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151240, 'koKR', '', '으스러진 손은 전설적인 전사 부족이죠. 그런데 절대 그 친구들한테 등을 긁어 달라고 하진 마세요. 이건 정말 제 말 믿으셔도 돼요... <고통스러운 신음>', 28153),
(151239, 'koKR', '', '아제로스에는 법이 너무 많습니다. 누구는 찔러도 된다, 누구는 찌르면 안 된다... 누구는 때려도 된다, 누구는 때리면 안 된다... 너무 빡빡하게들 사는 것 아닙니까?', 28153),
(151238, 'koKR', '', '잠깐... 당신, 서리불꽃 마루를 온통 난장판으로 만들고 떠났던 그놈... 아니, 그분 아니에요?', 28153),
(151237, 'koKR', '', '원하는 만큼 계속 머무르세요. 단, 물건을 파손하면 변상해 주셔야 해요!', 28153),
(151236, 'koKR', '', '더 가까워지기 전에 물어볼 게 있어요... 당신은 고통을 얼마나 참을 수 있나요?', 28153),
(151235, 'koKR', '', '당신에게 호응해 준다고 해서, 당신 얼굴에 주먹을 날리지 않겠다는 뜻은 아니에요.', 28153),
(151234, 'koKR', '', '피눈물 부족 주술사가 제게 알랑거리더군요. 제 생각엔 그래요. 도발적으로 윙크한 거든지 한쪽 눈을 막 제물로 바친 거든지, 둘 중 하나예요.', 28153),
(151233, 'koKR', '', '제게 마지막으로 추파를 던졌던 자는, 진짜 \"던진다\"는 게 뭔지 제대로 알아갔죠.', 28153),
(151232, 'koKR', '', '녹색 오크 하나가 \"당신 없는 세상은 지옥이에요\"라고 쓴 쪽지를 건네더군요. 그래서 말했죠. 악마의 피가 흐르니 그런 거라고. 그러고 둔기로 흠씬 두들겨 줬어요.', 28153),
(151231, 'koKR', '', '사울팽 님은 혹시 짝이 있으신가요? 점점 미중년이 되어 가고 계시네요...', 28153),
(151230, 'koKR', '', '당신에게 어둠의 문은 필요 없겠네요... 이미 제 마음을 침공했으니.', 28153),
(151229, 'koKR', '', '그건... 미안합니다.', 28153),
(151228, 'koKR', '', '가엾기도 하지! 넌 마그하르 앞에 무릎 꿇게 될 거다!', 28153),
(151227, 'koKR', '제대로 상대해 주마...', '제대로 상대해 주마...', 28153),
(151226, 'koKR', '그 제안... 받아들였어야 하는 건데...', '내가 먼저... 불타버린 것 같군...', 28153),
(151225, 'koKR', '내 돈을... 같이 묻어줘...', '죽음도... 피할 수 없구나... 세금처럼...', 28153),
(151224, 'koKR', '제법... 하는군...', '으으윽... 두고 보자...', 28153),
(151223, 'koKR', '괜히... 나서는 바람에...', '괜히... 나서는 바람에...', 28153),
(151222, 'koKR', '위험 수당... 내놔...', '괜히... 나서는 바람에...', 28153),
(151221, 'koKR', '', '감사합니다.', 28153),
(151220, 'koKR', '', '고맙습니다.', 28153),
(151219, 'koKR', '대족장께서 마음껏 날뛰라고 허락하셨다. 불타라, 불타!', '대족장께서 마음껏 날뛰라고 허락하셨다. 불타라, 불타!', 28153),
(151218, 'koKR', '마음껏 날뛰어도 좋다고 했다. 불타라, 불타!', '네 목에 걸린 현상금... 그거 내가 다 가질 거야!', 28153),
(151217, 'koKR', '', '신세를 졌군요.', 28153),
(151216, 'koKR', '', '내 앞에 무릎 꿇게 될 것이다!', 28153),
(151215, 'koKR', '여왕님을 막을 순 없다...', '여왕님을 막을 순 없다...', 28153),
(151214, 'koKR', '이봐, 번지수 잘못 찾았어!', '오늘 크게 실수한 줄 알아라!', 28153),
(151213, 'koKR', '', '드레노어의 달이시여!', 28153),
(151212, 'koKR', '아주 재미있겠군!', '음흠, 타는 냄새 죽이는데!', 28153),
(151211, 'koKR', '호드를 위하여! 내 돈을 위하여!', '호드를 위하여!', 28153),
(151210, 'koKR', '', '별로 한 것도 없습니다.', 28153),
(151209, 'koKR', '', '다시는 이런 일을 부탁하지 마십시오.', 28153),
(151208, 'koKR', '', '천만에요.', 28153),
(151207, 'koKR', '', '아닙니다.', 28153),
(151206, 'koKR', '', '안 된다고요!', 28153),
(151205, 'koKR', '', '안 됩니다!', 28153),
(151204, 'koKR', '', '맞는 말씀입니다.', 28153),
(151203, 'koKR', '', '맞습니다.', 28153),
(151202, 'koKR', '', '그렇고 말고요.', 28153),
(151201, 'koKR', '', '제가 우리 부족의 이름에 먹칠을 했군요!', 28153),
(151200, 'koKR', '', '마나를 채워야겠습니다.', 28153),
(151199, 'koKR', '', '마나가 필요해요!', 28153),
(151198, 'koKR', '', '명예롭게 죽으십시오.', 28153),
(151197, 'koKR', '', '더 할 얘기가 없군요.', 28153),
(151196, 'koKR', '', '이제 가셔도 좋습니다.', 28153),
(151195, 'koKR', '', '명예롭게 가십시오.', 28153),
(151194, 'koKR', '', '말씀하십시오.', 28153),
(151193, 'koKR', '', '반갑습니다.', 28153),
(151192, 'koKR', '', '록타르!', 28153),
(151191, 'koKR', '', '트롬카!', 28153),
(151190, 'koKR', '', '제발! 부탁합니다!', 28153),
(151189, 'koKR', '', '이 불쌍한 오크를 가엾게 여겨 주세요!', 28153),
(151188, 'koKR', '', '이 일꾼에게 사랑을 베푸십시오!', 28153),
(151187, 'koKR', '', '잘하셨습니다.', 28153),
(151186, 'koKR', '', '뭐, 인상적이군요.', 28153),
(151185, 'koKR', '', '<흥.> 축하합니다.', 28153),
(151184, 'koKR', '어서 하자고, 구두쇠들. 경호는 공짜가 아니라고!', '', 28153),
(151183, 'koKR', '', '적을 쓸어버리십시오!', 28153),
(151182, 'koKR', '', '대상을 공격하십시오!', 28153),
(151181, 'koKR', '', '놈들을 쓰러뜨리십시오!', 28153),
(151180, 'koKR', '', '명예로운 죽음을!', 28153),
(151179, 'koKR', '', '공격!', 28153),
(151178, 'koKR', '', '모크 토라 카!', 28153),
(151177, 'koKR', '왜 싸우는가...?', '왜 싸우는가...?', 28153),
(151176, 'koKR', '호드는 승리할 것이다.', '호드는 승리할 것이다.', 28153),
(151175, 'koKR', '', '적의 공격이다!', 28153),
(151174, 'koKR', '', '모조리 쓸어버립시다!', 28153),
(151173, 'koKR', '', '놈들의 대열을 부수십시오!', 28153),
(151172, 'koKR', '', '후퇴 아니면 죽음 뿐입니다!', 28153),
(151171, 'koKR', '', '다음 전투를 기약합시다!', 28153),
(151170, 'koKR', '', '가십시오! 달아나요!', 28153),
(151169, 'koKR', '', '이쪽입니다.', 28153),
(151168, 'koKR', '', '오크가 앞장서죠.', 28153),
(151167, 'koKR', '계속 싸워라... 전우들이여...', '계속 싸워라... 전우들이여...', 28153),
(151166, 'koKR', '이제... 안식을...', '이제... 안식을...', 28153),
(151165, 'koKR', '', '따라오십시오.', 28153),
