(151045, 'koKR', '', '아직 준비되지 않았습니다.', 28153),
(151044, 'koKR', '너무하잖아, 나도 좀 하자구!', '', 28153),
(151043, 'koKR', '이럴 리가... 없는데...', '제법... 날카롭구나...', 28153),
(151042, 'koKR', '이봐들, 저 빚쟁이는 게임에 끼워주지 마!', '', 28153),
(151041, 'koKR', '왜 이래, 나 잘 딴다고!', '', 28153),
(151040, 'koKR', '들어가기 전에 조사를 조금 더 해야겠어요. 이 트롤들의 꿍꿍이와 그걸 막을 방법을 알아내려면요.', '', 28153),
(151039, 'koKR', '당연한 말이지만, 사원 깊은 곳에 문제가 더 있을 거란 직감이 들어요.', '', 28153),
(151038, 'koKR', '놈을 깔끔하게 처리하셨군요.', '', 28153),
(151037, 'koKR', '물론, 우리만 저 힘에 끌려온 게 아니겠지요.', '', 28153),
(151036, 'koKR', '아아, 이곳이군요. 이 유물들의 힘이 제 뼛속까지 느껴집니다.', '', 28153),
(151034, 'koKR', '', '거기 당신! 동료들이 저를 사지에 두고 갔습니다. 도와주시겠습니까?', 28153),
(151031, 'koKR', '', '음... 흥미롭군요...', 28153),
(151030, 'koKR', '자신의 음식은 스스로 만들어 먹는 법을 배우십시오! 말라깽이 요리사는 절대 믿지 마시고요!', '', 28153),
(151029, 'koKR', '로아께서... 부르신다...', '운이... 좋았구나...', 28153),
(151028, 'koKR', '호드는... 건재하다...', '호드가... 승리할 것이다...', 28153),
(151027, 'koKR', '브원삼디 님, 지금 봬러 갑니다...', '브원삼디 님, 지금 봬러 갑니다...', 28153),
(151026, 'koKR', '멍청이들! 어떻게 추종자도 없는 버려진 사원의 로아에게 당할 수 있단 말이냐?! 녀석을 죽여라!', '', 28153),
(151025, 'koKR', '브원삼디 님... 지금 봬러 갑니다...', '저편이... 손짓하는구나...', 28153),
(151024, 'koKR', '부정한 주술이 너를 덮칠 것이다!', '부정한 주술을 받아라!', 28153),
(151023, 'koKR', '어쩌나? 모조리 죽이라는, 대족장님의 명령이다.', '어쩌나? 모조리 죽이라는, 대족장님의 명령이다.', 28153),
(151022, 'koKR', '꼼짝 마라!', '어디 피해보시지, 애송이!', 28153),
(151021, 'koKR', '어디 보자. 나약한 인간 놈들이 나 좀 죽여달라고 기다리고 있군?', '어디 보자. 나약한 인간 놈들이 나 좀 죽여달라고 기다리고 있군?', 28153),
(151020, 'koKR', '라즈덩크 님이 여기서 사라지라고 전하랍신다.', '', 28153),
(151019, 'koKR', '라즈덩크 님이 안부 전하랍신다.', '', 28153),
(151018, 'koKR', '제기랄! 좀 잡혀라, 배고파 죽겠다고!', '', 28153),
(151017, 'koKR', '저의 형제자매는 한때 나무의 동족으로서 이 대지를 돌봤습니다. 이미 지나간 지 오래된 시대의 얘기입니다.\n\n저희 중 몇몇은 그 길을 잊지 않았습니다.\n\n잿빛나무 숲은 서서히 진홍빛 숲을 잠식하는 타락을 잠시 멈춰준 저희의 성소였습니다.\n\n어둠 속에서 자라는 저 역병을 보니 그 시대 또한 지나간 것 같습니다. 이제 전 그곳이 사라져가는 모습을 바라보고 있습니다. 이제 그곳은 한때 그곳에서 자란 이들의 기억 속에만 남겠지요.', '', 28153),
(151016, 'koKR', '로아께서 내 칼날을 인도하신다!', '너를 브원삼디 님께 보내주마!', 28153),
(151015, 'koKR', '호드를 위하여!', '호드를 위하여!', 28153),
(151014, 'koKR', '숲에 무슨 일이 있습니까?', '숲에 무슨 일이 있습니까?', 28153),
(151013, 'koKR', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t 그훈이 |cFFFF0404|Hspell:267509|h[천 마리 식인아귀]|h|r를 불러내 전투를 돕게 합니다!', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t 그훈이 |cFFFF0404|Hspell:267509|h[천 마리 식인아귀]|h|r를 불러내 전투를 돕게 합니다!', 28153),
(151011, 'koKR', '', '힘을 완전히 회복하려면 시간이 좀 더 필요하겠지만, 나의 부활을 막고 있던 저주는 사라졌다.', 28153),
(151010, 'koKR', '', '정말 고맙구나, 용사들이여.', 28153),
(151009, 'koKR', '저 침입자들은 누구지?! 세스랄리스 님을 타락시키고 있어!', '', 28153),
(151008, 'koKR', '전장으로 보내 주세요.', '전장으로 보내 주세요.', 28153),
(151007, 'koKR', '아아, 그분의 성소가 곧 나오겠군.', '', 28153),
(151006, 'koKR', '세스랄리스 님이 아니었다면 세상은 혼돈에 빠졌을 걸세.', '', 28153),
(151005, 'koKR', '세스랄리스 님이 자신을 희생해 미스락스를 저지할 때 나도 거기 있었네.', '', 28153),
(151003, 'koKR', '진홍빛 숲의 뿌리가 피를 갈구하는 소리가 여기까지 들리는군요. 놈들의 타락이 이 정도로 멀리 퍼질 거라고는 생각하지 못했습니다.', '', 28153),
(151002, 'koKR', '보물 찾겠다고 시체를 전부 뒤질 셈인가? 세스랄리스 님을 찾는 게 먼저일세!', '', 28153),
(151001, 'koKR', '이것 참, 부수는 솜씨 하나는 확실하군.', '', 28153),
(151000, 'koKR', '부디 서둘러 주게나. 어둠이 사원을 장악하는 게 느껴지니 말일세.', '', 28153),
(150999, 'koKR', '감염을 제거해 준 데 진심 어린 감사를 표하네.', '', 28153),
(150998, 'koKR', '그분은 자신을 희생해 미스락스를 저지했지만... 그분의 죽음으로 볼둔의 밀림이 메말라 사막이 되고 말았네.', '', 28153),
(150997, 'koKR', '이 사원으로 말할 것 같으면, 아주 오래전 파멸로부터 백성을 보호해 주신 강력한 로아, 세스랄리스께서 안식하고 계신 곳이라네.', '', 28153),
(150996, 'koKR', '', '그래! 잘 싸운다!', 28153),
(150995, 'koKR', '', '큰 놈한테 금화 10개!', 28153),
(150993, 'koKR', '지금쯤이면 벌써 환생하셨어야 했지만, 아무래도 그분이 돌아오지 못하게 막는 무언가가 있는 것 같네.', '', 28153),
(150990, 'koKR', '지정된 지역에서 벗어나면 탈것에서 떨어지게 됩니다.', '지정된 지역에서 벗어나면 탈것에서 떨어지게 됩니다.', 28153),
(150989, 'koKR', '잠시 숨 좀 돌리겠군. 이 틈을 타 부대를 정비하고 피해를 복구할 수 있으면 좋겠네.', '', 28153),
(150988, 'koKR', '서두르게! 내 선원들에게 도움이 필요하네! 가뜩이나 부상을 입어 힘든 상황인데 호드까지 압박하고 있다네!', '', 28153),
(150987, 'koKR', '파도가 당신에게 친절하기를.', '', 28153),
(150986, 'koKR', '신선한 배추 사세요!', '', 28153),
(150985, 'koKR', '진실된 마음으로 항해하십시오.', '', 28153),
(150984, 'koKR', '순풍이 불기를.', '', 28153),
(150983, 'koKR', '아, 안녕하십니까?', '', 28153),
(150982, 'koKR', '뭐가 필요하십니까?', '', 28153),
(150981, 'koKR', '반갑습니다.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150980, 'koKR', '한 대 때릴 시간이다!', '', 28153),
(150979, 'koKR', '호드를 위하여!', '호드를 위하여!', 28153),
(150978, 'koKR', '호드를 저지할 수는 없다!', '호드를 저지할 수는 없다!', 28153),
(150977, 'koKR', '우리는 선봉 돌격대...', '우리는 선봉 돌격대...', 28153),
(150976, 'koKR', '', '우갈라줄 부락실 쿠 락스.', 28153),
(150975, 'koKR', '너희 종족에게... 패배할 줄이야.', '너희 종족에게... 패배할 줄이야.', 28153),
(150974, 'koKR', '호드는... 승리할 것이다...', '이 땅은... 우리 것이 되리라...', 28153),
(150973, 'koKR', '우리는... 선봉 돌격대다...', '나는... 명예롭게 죽는다...', 28153),
(150972, 'koKR', '우릴... 막을 수는 없다...', '하찮은... 쓰레기가...', 28153),
(150971, 'koKR', '', '심연이... 이 땅을 삼키리라!', 28153),
(150970, 'koKR', '', '안 돼... 그분을 실망시키다니!', 28153),
(150969, 'koKR', '', '네 족속을 저주한다!', 28153),
(150968, 'koKR', '', '물이여... 날 삼켜라!', 28153),
(150967, 'koKR', '', '이 목숨을... 여왕님께 바치리라!', 28153),
(150966, 'koKR', '', '심연에서... 솟아난다...', 28153),
(150965, 'koKR', '', '여왕님이 승리하실 것이다...', 28153),
(150964, 'koKR', '아! 지금 바로 복귀하겠습니다. 보고는 하지 말아 주십시오!', '아! 지금 바로 복귀하겠습니다. 보고는 하지 말아 주십시오!', 28153),
(150963, 'koKR', '괜찮은 상대를 만났군.', '괜찮은 상대를 만났군.', 28153),
(150962, 'koKR', '쓸 데 없이 기웃거리지 말라고!', '쓸 데 없이 기웃거리지 말라고!', 28153),
(150961, 'koKR', '심연이... 이 땅을 삼키리라!', '', 28153),
(150960, 'koKR', '안 돼... 그분을 실망시키다니!', '', 28153),
(150959, 'koKR', '네 족속을 저주한다!', '', 28153),
(150958, 'koKR', '물이여... 날 삼켜라!', '', 28153),
(150957, 'koKR', '이 목숨을... 여왕님께 바치리라!', '', 28153),
(150956, 'koKR', '여왕님을... 막을 순 없다...', '', 28153),
(150955, 'koKR', '심연에서... 솟아난다...', '', 28153),
(150954, 'koKR', '여왕님이 승리하실 것이다...', '', 28153),
(150953, 'koKR', '', '놈들에게 거점을 허용하지 않으면 우리 땅을 안전하게 지킬 수 있습니다. 공크 님의 복수를 한 자에게 보상이 있으리!', 28153),
(150952, 'koKR', '', '얼라이언스가 잔달라에 거점을 마련한다는 건 재앙 그 자체입니다. 최대한 보급품을 많이 회수하되 놈들에겐 자비를 베풀지 마십시오.', 28153),
(150951, 'koKR', '제대로 상대해 주마...', '', 28153),
(150950, 'koKR', '널 명예롭게 처치하겠다!', '최후를 맞이해라!', 28153),
(150949, 'koKR', '모두 없애버려라!', '록타르!', 28153),
(150948, 'koKR', '괜찮은 상대를 만났군!', '한 놈도 살려두지 마라!', 28153),
(150947, 'koKR', '호드를... 위하여...', '호드를... 위하여...', 28153),
(150946, 'koKR', '아, 정말 아름다운 녀석이야! 오늘 네 몫은 해냈구나.', '', 28153),
(150945, 'koKR', '', '감히 내 앞을 가로막으려 들어? 정녕 내 의지를 거스를 수 있다고 생각하는 것이냐!', 28153),
(150944, 'koKR', '단단히 준비하게. 사냥할 맛이 나는 괴수로군!', '', 28153),
(150943, 'koKR', '놈의 소굴로 이어지는 거였군!', '', 28153),
(150942, 'koKR', '흠... 이 악취 나는 통로 깊숙한 곳으로 흔적이 이어지는군.', '', 28153),
(150941, 'koKR', '진주는 여기 없군. 아즈샤라의 졸개가 보기보다 똑똑했던 모양이야.', '', 28153),
(150940, 'koKR', '머지않아 네 머리를 집에 장식할 수 있겠군!', '', 28153),
(150939, 'koKR', '네놈의 여왕과 함께 잠들어라. 네 삶은 여기까지니까.', '', 28153),
(150938, 'koKR', '침입자?! 네 몸뚱이를 어두운 심연으로 내던져 영원히 고통받게 하리라.', '', 28153),
(150937, 'koKR', '로아가 너무 강력하다! 바닷속 안전한 곳으로 후퇴하라! 이 전투는 패배했다!', '', 28153),
(150936, 'koKR', '사원을 파괴해라! 바위를 깨뜨리고 조각상도 다 부숴라! 모두가 여왕님 앞에 무릎을 꿇으리라!', '', 28153),
(150935, 'koKR', '어둠의 힘이건 아니건, 다음은 널 사냥해 주마!', '', 28153),
(150934, 'koKR', '어서 와라, 침입자여. 딱 맞춰 왔군. 우리의 진정한 힘을 보아라!', '', 28153),
(150933, 'koKR', '잘 처리했네만... 진정한 사냥감은 제단 안으로 들어갔네.', '', 28153),
(150932, 'koKR', '', '여왕님께서 네 죽음을 명하셨다!', 28153),
(150931, 'koKR', '', '아즈샤라 님에게 영광을!', 28153),
(150930, 'koKR', '', '우리의 운명이 도래했다!', 28153),
(150929, 'koKR', '', '널 죽음으로 이끄는 영광은 내 것이다!', 28153),
(150928, 'koKR', '', '누구도 아즈샤라 여왕님을 거역하지 못하리라!', 28153),
(150927, 'koKR', '', '파도의 반지는 우리 것이다!', 28153),
(150926, 'koKR', '', '넌 우리의 힘을 이해할 수 없다!', 28153),
(150925, 'koKR', '저기, 당신 신발 안 신었어요.', '', 28153),
(150924, 'koKR', '', '아니면 딱 한 놈만? 새 신발을 구하면 좋겠습니다.', 28153),
(150923, 'koKR', '인내심을 가지세요, 어린 자매여!', '', 28153),
(150922, 'koKR', '', '저들은 절대 알아차리지 못할 겁니다. 누구도 야영지로 돌격하라고 말하지는 않았지만, 몇 놈을 제거한다고 큰일 나진 않겠죠!', 28153),
(150921, 'koKR', '여왕님께서 네 죽음을 명하셨다!', '', 28153),
(150920, 'koKR', '아즈샤라에게 영광을!', '', 28153),
(150919, 'koKR', '우리의 운명이 도래했다!', '', 28153),
(150918, 'koKR', '널 죽음으로 이끄는 영광은 내 것이다!', '', 28153),
(150917, 'koKR', '누구도 아즈샤라 여왕님을 거역하지 못하리라!', '', 28153),
(150916, 'koKR', '파도의 반지는 우리 것이다!', '', 28153),
(150914, 'koKR', '저희는 이곳에 있어야 합니다. 만약 당신이 떠나고 우리가 죽는다면 보고할 사람이 아무도 없을 테니까요.', '', 28153),
(150913, 'koKR', '넌 우리의 힘을 이해할 수 없다!', '', 28153),
(150912, 'koKR', '내 배추!!!', '', 28153),
(150911, 'koKR', '그리핀 하나 더 잡을 시간이다. 어서 타!', '', 28153),
(150908, 'koKR', '거친목이 하는 일이 늘 매력적인 건 아니지만, 쏠쏠하긴 하지.', '', 28153),
(150907, 'koKR', '그리핀 안장 주문이 잔뜩 들어왔다. 털이 모자라니 어서 구해 와라!', '', 28153),
(150906, 'koKR', '산 속에 있는 놈들이 적어지면 내려올 놈들도 적어지지. 아주 잘했다!', '', 28153),
(150905, 'koKR', '빙하에 사는 웬디고가 점점 늘고 있다. 가서 어떻게 좀 해 봐라!', '', 28153),
(150904, 'koKR', '파도 진주의 힘만 있으면, 우리 함대는 무적이 될 걸세.', '', 28153),
(150903, 'koKR', '', '내가 금덩이로 만들어져 있는 줄 아는 거 아냐?!', 28153),
(150902, 'koKR', '미안해, 대장...', '', 28153),
(150901, 'koKR', '', '멍청한 자식! 왕창 잃었잖아!', 28153),
(150900, 'koKR', '고맙소. 그대들은 쿨 티란 백성에게 희망을 되찾아주었소.', '', 28153),
(150899, 'koKR', '어둠이 물러나는 것이 느껴지는군. 제단이 원래대로 돌아올 것이오.', '', 28153),
(150898, 'koKR', '놈의 속삭임을 듣지 마시오! 공포로 영혼을 뒤틀려는 수작이오!', '', 28153),
(150897, 'koKR', '파도어머니시여!', '', 28153),
(150896, 'koKR', '조심하시오. 보이지 않는 악이 아직 어둠 속에 도사리고 있소. 제단으로부터 그 악을 몰아내야 하오.', '', 28153),
(150895, 'koKR', '뭔가 잘못됐소. 어둠이 아직 이곳을 물들이고 있소.', '', 28153),
(150894, 'koKR', '주군이여, 파도를 거스르더니 이제 그 아래 잠드셨군요.', '', 28153),
(150893, 'koKR', '그렇다면 네 몸뚱이를 어두운 심연으로 내던져 영원히 고통받게 하리라.', '', 28153),
(150892, 'koKR', '못합니다.', '', 28153),
(150891, 'koKR', '마지막 기회다. 복종하거나... 죽어라.', '', 28153),
(150890, 'koKR', '어리석구나! 우리는 바다로 돌아가야 한다. 아즈샤라 여왕님께서 돌아갈 힘을 주시리라!', '', 28153),
(150889, 'koKR', '주군이여! 이 광기를 멈추십시오! 쿨 티란 함대가 어둠에 빠져서는 안 됩니다!', '', 28153),
(150888, 'koKR', '', '손님이 있는 것 같군, 스톰송 군주.', 28153),
(150887, 'koKR', '', '예의를 지키며 말씀을 듣기만 하십시오... 그럼 피라미드 밖으로 내던져지진 않을 겁니다.', 28153),
(150886, 'koKR', '여왕님, 쿨 티란 함대가 거의 손안에 들어왔습니다.', '', 28153),
(150885, 'koKR', '바다는 바다로, 재는 재로, 물결은 물결로. 영혼이 평안한 해류에 안기기를.', '', 28153),
(150884, 'koKR', '서두르시오! 함대를 잃기 전에 놈들을 막아야 하오!', '', 28153),
(150883, 'koKR', '티탄 원반 활성화: 타락 프로토콜 개시', '티탄 원반 활성화: 타락 프로토콜 개시', 28153),
(150882, 'koKR', '티탄 원반 활성화: 기만 프로토콜 개시', '티탄 원반 활성화: 기만 프로토콜 개시', 28153),
(150881, 'koKR', '', '의식이 완료되면 쿨 티란 함대는 아즈샤라 여왕님의 것이 되리라!', 28153),
(150880, 'koKR', '어서 오게, 파이크 수사. 딱 맞춰 왔군. 우리의 승리를 지켜보게.', '', 28153),
(150879, 'koKR', '스톰송이 이 성스러운 곳을 뒤틀어 놓았소. 놈을 몰아내고 이곳을 바로잡아야 하오.', '', 28153),
(150878, 'koKR', '목소리라고요?', '목소리라고요?', 28153),
(150877, 'koKR', '조심히 가시오. 지금도 어둠의 존재가 지켜보고 있소.', '', 28153),
(150876, 'koKR', '스톰송 군주의 악으로부터 제단을 정화해야 하오.', '', 28153),
(150875, 'koKR', '', '주인님! 절 버리지 마십시오! 안 돼!', 28153),
(150874, 'koKR', '', '정말 그훈 님의 힘에 대적할 생각이었나? 오만의 대가를 치러라!', 28153),
(150873, 'koKR', '진흙 속에서 목소리가 들린다!', '진흙 속에서 목소리가 들린다!', 28153),
(150872, 'koKR', '', '우린 끝났습니다.\n\n레잔 님의 빛이 우리를 떠났습니다. 위대한 로아의 왕을 따르던 극소수의 인원이 그나마 힘을 조금 유지하고 있지만, 그들마저 의심스러운 상황입니다.\n\n우리의 삶은 헌신 그 자체였습니다. 이제 우리는 어떤 존재가 되어야 합니까?', 28153),
(150871, 'koKR', '업그레이드할 시간이로군!', '', 28153),
(150870, 'koKR', '됐어, 난 공정하게 싸울 만큼 싸웠어.', '', 28153),
(150869, 'koKR', '훌륭하오! 우리 병사들이 그 보급품을 유용하게 사용할 거요. 수고했소!', '', 28153),
(150868, 'koKR', '이 근처에서 혈트롤 약탈조가 잔달라 부족의 화물선을 강탈했다는 정찰병의 보고요. 놈들을 처치하고 보급품을 회수하시오.', '', 28153),
(150867, 'koKR', '조심해, 친구들. 잡상인이 온 것 같아!', '', 28153),
(150866, 'koKR', '그래! \"패션 왕을 찾아가서 한 수 배워야 합니다\"!', '', 28153),
(150865, 'koKR', '', '$n! 어이, $n! 퀘스트 줄게 이리 와 봐!', 28153),
(150864, 'koKR', '뛰기!', '뛰기!', 28153),
(150863, 'koKR', '이 브원삼디 님에게서 숨을 순 없지, 작은 존재여.', '', 28153),
(150862, 'koKR', '넌 뭔가 느낌이 좀 이상한데... <킁> 아, 이 고약한 악마사냥꾼의 냄새.', '', 28153),
(150861, 'koKR', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a사령관이 공격받고 있습니다!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a사령관이 공격받고 있습니다!', 28153),
(150860, 'koKR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a밸러콜의 길이 공격받고 있습니다!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a밸러콜의 길이 공격받고 있습니다!', 28153),
(150859, 'koKR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a뉴스테드가 공격받고 있습니다!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a뉴스테드가 공격받고 있습니다!', 28153),
(150858, 'koKR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a정령의 마법진이 공격받고 있습니다!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a정령의 마법진이 공격받고 있습니다!', 28153),
(150857, 'koKR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a높은 감시대가 공격받고 있습니다!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a높은 감시대가 공격받고 있습니다!', 28153),
(150856, 'koKR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a북부습곡 십자로가 공격받고 있습니다!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a북부습곡 십자로가 공격받고 있습니다!', 28153),
(150855, 'koKR', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a마른수염 광산이 공격받고 있습니다!', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a마른수염 광산이 공격받고 있습니다!', 28153),
(150854, 'koKR', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a손도끼 마루가 공격받고 있습니다!', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a손도끼 마루가 공격받고 있습니다!', 28153),
(150853, 'koKR', '전위 정찰병에게 연락을 취해야 합니다. 이 날아다니는 해충을 신속히 제거하십시오!', '전위 정찰병에게 연락을 취해야 합니다. 이 날아다니는 해충을 신속히 제거하십시오!', 28153),
(150852, 'koKR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a밸러콜의 길을 잃었습니다!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a밸러콜의 길을 잃었습니다!', 28153),
(150851, 'koKR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a뉴스테드를 잃었습니다!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a뉴스테드를 잃었습니다!', 28153),
(150850, 'koKR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a정령의 마법진을 잃었습니다!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a정령의 마법진을 잃었습니다!', 28153),
(150849, 'koKR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a높은 감시대를 잃었습니다!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a높은 감시대를 잃었습니다!', 28153),
(150848, 'koKR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a북부습곡 십자로를 잃었습니다!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a북부습곡 십자로를 잃었습니다!', 28153),
(150847, 'koKR', '이건 꿈이 아니야, 친구.', '', 28153),
(150846, 'koKR', '오, 영혼이 이제 너와 진짜 함께한다.', '', 28153),
(150845, 'koKR', '아, 죽음의 기사. 내 죽음의 관문을 한번 보여주고 싶은데!', '', 28153),
(150844, 'koKR', '다음은 너희 땅이 파멸하리라!', '다음은 너희 땅이 파멸하리라!', 28153),
(150843, 'koKR', '모래가 퍼지는 걸 막을 순 없다!', '모래가 퍼지는 걸 막을 순 없다!', 28153),
(150842, 'koKR', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a마른수염 광산을 잃었습니다!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a마른수염 광산을 잃었습니다!', 28153),
(150841, 'koKR', '하하! 구르기로도 못 피할 정도였나보구먼.', '', 28153),
(150840, 'koKR', '우리가 모두를 지배하리라!', '우리가 모두를 지배하리라!', 28153),
(150839, 'koKR', '벌레 같은 놈들, 박멸시켜 주마!', '벌레 같은 놈들, 박멸시켜 주마!', 28153),
(150838, 'koKR', '죽은 척하기 하는 거야, 친구? 딱하기도 하지...', '', 28153),
(150837, 'koKR', '제왕님을 위하여!', '제왕님을 위하여!', 28153),
(150836, 'koKR', '엉뚱한 빛을 따른 모양이로군, 친구.', '', 28153),
(150835, 'koKR', '점멸로 피하는 것도 한계가 있지, 안 그래?', '', 28153),
(150834, 'koKR', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a손도끼 마루를 잃었습니다!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a손도끼 마루를 잃었습니다!', 28153),
(150833, 'koKR', '맞아! 아, 그러니까 이놈들도 끔찍해 보이긴 하는데, 그 중에서도 달라 보여!', '', 28153),
(150832, 'koKR', '', '와, 저 모험가는 확실히 달라 보이네.', 28153),
(150831, 'koKR', '그 \"영웅들\" 중 하나한테서 나는 것 같은데. 불에 타는 살 냄새가 나!', '', 28153),
(150830, 'koKR', '', '대체 이게 무슨 냄새야?!', 28153),
(150829, 'koKR', '', '월도프, 저건 가시멧돼지가 아니야. 그 \"영웅\"이라는 자들 중 하나잖아.', 28153),
(150828, 'koKR', '하, 그 으리으리한 방어구도 별 소용이 없었나 보지?', '', 28153),
(150827, 'koKR', '어이, 스타틀러, 검 좀 줘봐! 저기 가시멧돼지가 오고 있어!', '', 28153),
(150826, 'koKR', '어이구, 그 귀한 영혼석을 잃어버리신 모양이지, 응?', '', 28153),
(150825, 'koKR', '', '맞아! 후줄근한 태 나기 딱 좋아 보이네!', 28153),
(150824, 'koKR', '$n|1이;가;입은 옷 보여? 좋아 보이는데?', '', 28153),
(150823, 'koKR', '아, 브원삼디와 좋은 시간을 보내러 왔나?', '', 28153),
(150822, 'koKR', '하하! 아주 인상 깊은 죽음이었다!', '', 28153),
(150821, 'koKR', '놈들이 조금 피곤해 보이는데... 항상 저렇게 안 좋은 상태인 것 같긴 해!', '', 28153),
(150820, 'koKR', '', '동네 사람들! 사우로리스크가 누굴 끌고 왔는지 봐요! $n|1이에요;예요;!', 28153),
(150819, 'koKR', '', '와, 저 세트는 어디서 났을까? 트로그가 줬나?!', 28153),
(150818, 'koKR', '어이, 스타틀러! $n|1이;가; 착용한 장비 좀 봐봐!', '', 28153),
(150817, 'koKR', '맞는 것 같은데! 와, 상상했던 것보다 더 구린 냄새가 나는걸? 하!', '', 28153),
(150816, 'koKR', '', '어이, 월도프! 이 사람이 제이나와 함께 나타났다던 그 \"유명한\" $r 아니야?', 28153),
(150815, 'koKR', '', '그런가 봐! 냄새도 난다! 하하하!', 28153),
(150814, 'koKR', '어이, 어이! 그래, $r 너 말야! 네 이름이 \"어이\"냐?', '', 28153),
(150813, 'koKR', '난 너보다 형상변환 잘한 말도 봤다고!', '', 28153),
(150812, 'koKR', '', '어이! $n! 그 투구가 네 신발이랑 잘 어울린다고 생각하냐?', 28153),
(150811, 'koKR', '제가 알고 싶었던 건 다른 겁니다.', '제가 알고 싶었던 건 다른 겁니다.', 28153),
(150810, 'koKR', '', '고대의 드러스트. 쿨 티란을 향한 저들의 증오가 필멸자의 삶을 초월하도록 만들었어요. 저 너머에서 울리는 메아리조차 우리의 존재, 그 자체를 혐오하지요. \n\n누군진 몰라도 그들을 만들어낸 어리석은 이가 가엾을 뿐이랍니다.', 28153),
(150809, 'koKR', '복수심에 불타는 망자요?', '복수심에 불타는 망자요?', 28153),
(150808, 'koKR', '모두 박멸시켜 주마!', '', 28153),
(150807, 'koKR', '', '이 마녀들이 사용하는 마법은 고대의 것으로 깊이 타락해 있어요. 야생 동물을 뒤틀린 존재로 만들고 이들을 부려 균형을 깨뜨리지요. 저들의 추악한 피조물에는 복수심에 불타는 망자의 영혼이 담겨 있어요.', 28153),
(150806, 'koKR', '', '사냥에는 즐거움이, 그리고 복수에는 만족감이 따르지요!', 28153),
(150805, 'koKR', '', '로아를 살해한 반역자들이 아직도 레잔 님의 사원을 더럽히고 있습니다. 왕들의 로아를 모욕하면 어떻게 되는지 고대의 크즐로텍이 가르쳐줄 겁니다.', 28153),
(150804, 'koKR', '나자 불 렉실 칼릭 울, 라 무아.', '', 28153),
(150803, 'koKR', '숲에 무슨 일이 일어난 거죠?', '숲에 무슨 일이 일어난 거죠?', 28153),
(150802, 'koKR', '카 리쉬! 카, 아니, 타!', '', 28153),
(150801, 'koKR', '', '주변에 있는 동굴에서 찾을 수 있을거에요. 행운을 빌게요, $n 님.', 28153),
(150800, 'koKR', '', '초원추적자가 약해진 건 사실이지만, 머지않아 다시 사냥에 나설 수 있을 거예요.', 28153),
(150799, 'koKR', '우그 브아파 킬릭스 자!', '', 28153),
(150798, 'koKR', '너는 이 사원에서 영원히 환영받을 것이다.', '', 28153),
(150797, 'koKR', '오, 가여운 존재여, 이 브원삼디 님의 도움이 필요한가?', '', 28153),
(150796, 'koKR', '라니슈가 내 아이들을 중독시켰다. 그 아이들은 약해져 죽어가고 있지. 네가 날 구했듯이 내 힘으로 그들을 구하거라.', '', 28153),
(150795, 'koKR', '훌 발라 미즈 릴라키츠...', '', 28153),
(150794, 'koKR', '어허, 이런, 이런. 여기서 이렇게 빨리 보게 될 줄이야.', '', 28153),
(150793, 'koKR', '록타르 오가르!', '록타르 오가르!', 28153),
(150792, 'koKR', '호드를 위하여!', '호드를 위하여!', 28153),
(150791, 'koKR', '나는 우월하다!', '', 28153),
(150790, 'koKR', '호드의 병사들이여, 검을 들어라! 오늘 우리는 칼도레이로 진군할 것이다!', '', 28153),
(150789, 'koKR', '내가 맞춰보지... 좀 자만했지?', '', 28153),
(150788, 'koKR', '일 쿨 제라키쉬! 두아 타움...', '', 28153),
(150787, 'koKR', '이제 수리되었을 겁니다. 오그리마에 있는 실바나스에게 가서 장대한 속임수의 서막을 올려 보시지요.', '', 28153),
(150786, 'koKR', '나즈미르를 시작했는데 줄다자르를 시작할 수 없습니다. 고쳐주십시오.', '나즈미르를 시작했는데 줄다자르를 시작할 수 없습니다. 고쳐주십시오.', 28153),
(150785, 'koKR', '뭐가 필요하십니까?', '', 28153),
(150784, 'koKR', '그 상태가 유지되는 게 우리에겐 더 이득이겠지.', '', 28153),
(150783, 'koKR', '웨이크레스트 가문을 계속 압박하면 충분한 보상이 주어질 거다.', '', 28153),
(150781, 'koKR', '가장 쓸 만한 놈들을 모아 선구품 부두로 가라. 거길 시작으로 온 땅을 약탈하고, 전리품을 챙겨 놈들의 물자를 바닥내고, 동시에 우리 주머니도 채워라.', '', 28153),
(150779, 'koKR', '리드피스트 선장, 우리의 후원자가 웨이크레스트 가문이 회생 불가능한 큰 위기에 처했다는 소식을 전해왔다.', '', 28153),
(150778, 'koKR', '왜 자리를 지키지 않고 있습니까?', '왜 자리를 지키지 않고 있습니까?', 28153),
(150777, 'koKR', '킴불 님을 제 로아로 선택하고 싶습니다.', '킴불 님을 제 로아로 선택하고 싶습니다.', 28153),
(150776, 'koKR', '아제로스의 심장 그 자체일세!', '', 28153),
(150775, 'koKR', '<야수의 제왕인 킴불에게 바치기 위해 지어진 제단>', '<야수의 제왕인 킴불에게 바치기 위해 지어진 제단>', 28153),
(150773, 'koKR', '뭡니까?', '뭡니까?', 28153),
(150772, 'koKR', '난 아제로스의 대변자이지만, 그대는 아제로스의 영웅일세. 그대가 아제로스를 지켜야 해.', '', 28153),
(150771, 'koKR', '아제로스가 자네를 부르네. 자네에게 주는 선물이군... 아제로스의 정수로부터 나온 것일세.', '', 28153),
(150770, 'koKR', '자유다! 사원 안쪽의 안전한 곳으로 가야 합니다!', '자유다! 사원 안쪽의 안전한 곳으로 가야 합니다!', 28153),
(150769, 'koKR', '뭐야... 내게 무슨 일이 일어난 거지?', '뭐야... 내게 무슨 일이 일어난 거지?', 28153),
(150768, 'koKR', '', '그훈 님! 당신의 힘을 내려 주소서!', 28153),
(150767, 'koKR', '저편에서 이 빚을 꼭 갚겠습니다, 친구여.', '저편에서 이 빚을 꼭 갚겠습니다, 친구여.', 28153),
(150766, 'koKR', '', '종말이 다가온다!', 28153),
(150765, 'koKR', '', '비명 지르며 빌어 봐라!', 28153),
(150764, 'koKR', '', '모두 주인님을 섬기리라!', 28153),
(150763, 'koKR', '드디어 저 저주받은 뼈에서 해방되었습니다!', '드디어 저 저주받은 뼈에서 해방되었습니다!', 28153),
(150762, 'koKR', '이제 할란 스위트의 재산을 덜어줄 때입니다.', '', 28153),
(150761, 'koKR', '티탄 원반 활성화: 혼돈 프로토콜 개시', '티탄 원반 활성화: 혼돈 프로토콜 개시', 28153),
(150760, 'koKR', '잘 쓰고 돌려줄게! 정말로!', '잘 쓰고 돌려줄게! 정말로!', 28153),
(150759, 'koKR', '할란 스위트를 해치웠으니 이제 바다는 우리 차지입니다.', '', 28153),
(150758, 'koKR', '으아악!', '으아악!', 28153),
(150757, 'koKR', '정정당당하게 훔친 거야!', '정정당당하게 훔친 거야!', 28153),
(150756, 'koKR', '하! 역시 당신한테 걸길 잘했군요!', '', 28153),
(150755, 'koKR', '흩어져!', '흩어져!', 28153),
(150754, 'koKR', '으아! 절 잡아가려고 해요!', '으아! 절 잡아가려고 해요!', 28153),
(150753, 'koKR', '해골 몇 개 깨부수고 돈을 좀 벌어보시지 않겠습니까?', '', 28153),
(150752, 'koKR', '이 섬은 난투장의 싸움 대회가 끝날 때까지 봉쇄될 겁니다.', '', 28153),
(150750, 'koKR', '잘하셨습니다. 다만 할란에게 따끔한 맛을 보여주기는 훨씬 어려울 겁니다.', '', 28153),
(150749, 'koKR', '초대를 받으면 일이 쉬워질 겁니다. 반면 무작정 들이닥쳐 무시무시한 해적 선장 셋을 동시에 상대하려면... 꽤나 고달플 겁니다. 선택은 맡기겠습니다.', '', 28153),
(150748, 'koKR', '항만의 시궁쥐단은 술고래로 유명합니다. 술로 이들과 대적할 수 있다면 유도라 선장이 당신을 초대할 겁니다.', '', 28153),
(150747, 'koKR', '검은이빨 난투꾼은 치고받고 싸우는 걸 좋아합니다. 놈들 이빨을 하나 날려주면 라울 선장이 분명히 당신을 초대할 겁니다.', '', 28153),
(150746, 'koKR', '선장들이 모인다더군요. 그 모임에 잠입해서 녀석들 목을 한꺼번에 쳐버리는 겁니다.', '', 28153),
(150745, 'koKR', '이 전쟁이 알아서 승리로 향하지는 않을 거라고. 우리에겐 해야 할 일이 있어!', '', 28153),
(150744, 'koKR', '그런 다음 할란 스위트를 영원히 잠재울 겁니다.', '', 28153),
(150743, 'koKR', '바다가름은 갈라버리고, 항만의 시궁쥐는 시궁창에 던져넣고, 검은이빨은 뽑고, 무쇠파도는 녹여버리는 겁니다.', '', 28153),
(150742, 'koKR', '놈이 성공하면 함대를 지휘해 우리 영역을 위협할 것입니다.', '', 28153),
(150741, 'koKR', '할란은 무쇠파도를 이용해 다른 해적들을 끌어모으고 있습니다.', '', 28153),
(150740, 'koKR', '풀어줘서 고맙습니다. 사원에서 브원삼디 님의 부름이 느껴집니다. 그리로 가시죠.', '풀어줘서 고맙습니다. 사원에서 브원삼디 님의 부름이 느껴집니다. 그리로 가시죠.', 28153),
(150739, 'koKR', '영원히 흉측한 해골 신세가 되는 줄 알았습니다. 어서 사원으로 돌아가야겠습니다!', '영원히 흉측한 해골 신세가 되는 줄 알았습니다. 어서 사원으로 돌아가야겠습니다!', 28153),
(150738, 'koKR', '빨리 브원삼디 님의... 사원으로... 돌아가야 합니다...', '빨리 브원삼디 님의... 사원으로... 돌아가야 합니다...', 28153),
(150737, 'koKR', '놈들의 역겨운 의식 때문에 남은 감각이 무뎌졌습니다... 사원 계단으로 안내해 주십시오.', '놈들의 역겨운 의식 때문에 남은 감각이 무뎌졌습니다... 사원 계단으로 안내해 주십시오.', 28153),
(150736, 'koKR', '고맙습니다, 친구여! 전 빠르게 사라지고 있습니다. 제가 브원삼디 님의 사원으로 갈 수 있게 도와 주십시오.', '고맙습니다, 친구여! 전 빠르게 사라지고 있습니다. 제가 브원삼디 님의 사원으로 갈 수 있게 도와 주십시오.', 28153),
(150735, 'koKR', '뭘 가지고 왔나, 부유한 이여? 자니에게 줄 반짝이는 장신구인가? 가까이 가지고 오게...', '', 28153),
(150734, 'koKR', '여기서 산수가 좀 되는 사람은 저뿐입니다. 그래서 제가 지출을 관리하고, 다들 허튼수작을 부리지 못하게 하고 있지요.', '', 28153),
(150733, 'koKR', '일꾼은 이 전쟁의 근간이라네.', '', 28153),
(150732, 'koKR', '무사히 돌아오십시오.', '', 28153),
(150731, 'koKR', '혈트롤을 조심하십시오.', '', 28153),
(150730, 'koKR', '몸 조심하십시오. 당신은 살아주셔야 합니다!', '', 28153),
(150729, 'koKR', '잔달라의 암흑기입니다.', '', 28153),
(150728, 'koKR', '아, 혈트롤은 정말 혐오스럽지요.', '', 28153),
(150727, 'koKR', '이 상황을 어떻게 해결할까요?', '', 28153),
(150726, 'koKR', '흠! 호드는 응당한 대가를 받았습니다. 이 장치를 아롬의 격전지에 가져가서 쓸 만한 사람이 있는지 알아보겠습니다. 잘하셨습니다.', '', 28153),
(150719, 'koKR', '잔달라를 지킬 준비가 됐습니다.', '잔달라를 지킬 준비가 됐습니다.', 28153),
(150718, 'koKR', '이쪽이야! 우리 지상 병력이 아래서 기다리고 있어.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150717, 'koKR', '', '숲이 고통스러워하며 울어요. 들리시나요?', 28153),
(150716, 'koKR', '고향으로 간다!', '고향으로 간다!', 28153),
(150715, 'koKR', '제 도움까진 필요 없었나 보군요! 최대한 빨리 온다고 왔는데 말이죠!', '', 28153),
(150714, 'koKR', '저와 다릴은 평생 동안 이 언덕과 함께 살아왔습니다. 우린 여기서 그 어떤 호드보다도 오래 살아남을 겁니다.', '', 28153),
(150713, 'koKR', '좋아, 택일해라. 줄다자르에 돌아가 잡혀 죽던가, 여기 남아서 랩터한테 찢겨 죽던가.', '좋아, 택일해라. 줄다자르에 돌아가 잡혀 죽던가, 여기 남아서 랩터한테 찢겨 죽던가.', 28153),
(150712, 'koKR', '볼둔으로는 안 간다! 내 말 들었나? 나는 도시로 돌아가서 살 거라고!', '', 28153),
(150711, 'koKR', '', '엠마, 신선한 거북이에요! 제 몫을 주세요!', 28153),
(150710, 'koKR', '뭘 가지고 왔나, 부유한 이여? 이 자니에게 줄 반짝이는 장신구인가? 가까이 가지고 오게...', '', 28153),
(150709, 'koKR', '', '쑬 크라스 키 운 스쿠쉬!', 28153),
(150708, 'koKR', '', '스키티쉬 키우티크 일리쓰!', 28153),
(150707, 'koKR', '', '바닥이 온통 피로 물들고 있어.', 28153),
(150706, 'koKR', '', '지하실로 와서 나와 함께 죽음의 아름다움을 느껴보는 건 어떤가?', 28153),
(150705, 'koKR', '', '오, 이런. 우리 가정부들을 모두 죽였구나.', 28153),
(150704, 'koKR', '<어린 트롤이 장례 행렬 같은 모습을 바라보는 환영이 보입니다. 눈을 크게 뜬 모습이 천진난만해 보입니다.>', '<어린 트롤이 장례 행렬 같은 모습을 바라보는 환영이 보입니다. 눈을 크게 뜬 모습이 천진난만해 보입니다.>', 28153),
(150703, 'koKR', '관문에서 떨어지게! 여긴 안전하지 않네.', '관문에서 떨어지게! 여긴 안전하지 않네.', 28153),
(150702, 'koKR', '쿠아폰이 당신에게 포효합니다. 라알에게 돌아가지 않으면 탈것에서 내리게 됩니다!', '쿠아폰이 당신에게 포효합니다. 라알에게 돌아가지 않으면 탈것에서 내리게 됩니다!', 28153),
(150701, 'koKR', '', '고통에 몸부림쳐라!', 28153),
(150700, 'koKR', '', '네 영혼을 갈기갈기 찢어 주마!', 28153),
(150699, 'koKR', '', '그걸 썼더니 머리가 초록색이 됐어요!', 28153),
(150698, 'koKR', '', '너희 비명이 영원히 울리리라!', 28153),
(150697, 'koKR', '', '내가 모두를 지배하리라!', 28153),
(150696, 'koKR', '', '키로, 저들이 살아있어요! 이곳에 그냥 두고 갈 수는 없어요...', 28153),
(150695, 'koKR', '서둘러서 최대한 많이 챙기세요. 시체는 독수리 밥으로 남겨두세요.', '', 28153),
(150694, 'koKR', '이 사막이 네 무덤이다...', '', 28153),
(150693, 'koKR', '침입자다!', '', 28153),
(150692, 'koKR', '네가 맡은 일을 해라, 장군. 난 내 일을 할 터이니.', '', 28153),
(150691, 'koKR', '일을 서둘러야하오. 왕을 찾아온 시끄러운 방문자들이... 문제가 될 수 있소.', '', 28153),
(150690, 'koKR', '', '톨 다고르에 경비병이 하나 있었는데, 당신이랑 똑같이 생겼지 뭐예요!', 28153),
(150689, 'koKR', '', '저를 보랄러스 은행에 잠입시킬 수 있겠어요?', 28153),
(150688, 'koKR', '', '방사능이 뭔지는 아시는 거죠?', 28153),
(150687, 'koKR', '', '쓸 만한 기술 없어요? 위조나 금고따기 같은 거요.', 28153),
(150686, 'koKR', '', '폭풍이 깨지고, 다시 내 자아를 찾았다. 고맙구나.', 28153),
(150685, 'koKR', '', '너희 생은 무의미했다. 이제 죽음으로 잊혀지리라.', 28153),
(150684, 'koKR', '', '더러운 것들!', 28153),
(150683, 'koKR', '', '나를 회복시켜주면 놈들을 무력화시키겠다!', 28153),
(150682, 'koKR', '', '사술은 깨졌지만, 사원의 방어 체계가 발동되었구나!', 28153),
(150681, 'koKR', '', '너희의 고통은 끝이 없으리라!', 28153),
(150680, 'koKR', '네놈들 구워지는 모습이 기대되는구나!', '', 28153),
(150679, 'koKR', '죽어라, 벌레야!', '', 28153),
(150678, 'koKR', '곡선베기!', '', 28153),
(150677, 'koKR', '썰어주마!', '', 28153),
(150676, 'koKR', '한심하기는!', '', 28153),
(150675, 'koKR', '박살났군, 깨진 유리처럼!', '', 28153),
(150674, 'koKR', '겁먹거나 그런 게 아니라, 그냥 그럴 기분이 아니라서 그래!', '', 28153),
(150673, 'koKR', '누구도 우리 제국에 맞설 수 없다!', '', 28153),
(150672, 'koKR', '그 정도는 올라갈 수 있어. 나 겁쟁이 아니거든!', '', 28153),
(150671, 'koKR', '너 같은 놈한테 굳이 내 능력을 증명할 필요 없지!', '', 28153),
(150670, 'koKR', '와 봐, 아브라함. 어린애들도 올라오던걸.', '', 28153),
(150669, 'koKR', '올라와 봐, 그렇게 안 높아.', '', 28153),
(150668, 'koKR', '이건 절대 못 오를 걸.', '', 28153),
(150667, 'koKR', '재미 하나도 없거든! 어서 여기서 내려 줘!', '', 28153),
(150666, 'koKR', '그만 놀리고 날 좀 내려줘!', '', 28153),
(150665, 'koKR', '내려가게 해 줘!', '', 28153),
(150664, 'koKR', '더 늦기 전에 빠져나가십시오!', '더 늦기 전에 빠져나가십시오!', 28153),
(150663, 'koKR', '날 잡아갈 수는 없지!', '날 잡아갈 수는 없지!', 28153),
(150662, 'koKR', '내 몫은 필요 없어!', '내 몫은 필요 없어!', 28153),
(150661, 'koKR', '무쇠파도를 해치워버리자!', '무쇠파도를 해치워버리자!', 28153),
(150660, 'koKR', '저를 데려가지 못하게 해 주세요!', '저를 데려가지 못하게 해 주세요!', 28153),
(150659, 'koKR', '해적 밑에서 일할 순 없죠!', '해적 밑에서 일할 순 없죠!', 28153),
(150658, 'koKR', '', '머리를 납작하게 만들어 주지!', 28153),
(150657, 'koKR', '위에서 좋은 시간 보내고 있다고? 하!', '', 28153),
(150656, 'koKR', '거기 무슨 문제 있니, 아브라함?', '', 28153),
(150655, 'koKR', '바보래요! 위에 갇혔대요!', '', 28153),
(150654, 'koKR', '세스랄리스 님은 목숨을 바쳐 우리 세상을 구하셨네. 미스락스가 돌아온다면 그녀의 용맹한 희생이 물거품이 될지도...', '', 28153),
(150653, 'koKR', '죽은 뒤에도 미스락스의 정수는 아직도 강력하네. 그가 되살아나기라도 한다면, 세상에 어떤 일이 벌어질지 걱정되는군...', '', 28153),
(150652, 'koKR', '이곳엔 어두운 무언가가 있네. 경계를 늦추지 말게...', '', 28153),
(150651, 'koKR', '', '아이들의 위대한 여정이 시작됩니다.', 28153),
(150650, 'koKR', '', '이 미약한 존재들은 시험을 받아야 운명을 향해 나아갈 수 있습니다. 아이들이 계급의 전당으로 돌아갈 수 있도록 격려해 주십시오.', 28153),
(150649, 'koKR', '좋소! 이 생명체들은 사냥꾼이 사용할 화살과 방어구에 쓸 안감을 제공할 거요.', '', 28153),
(150648, 'koKR', '늪지로 물자를 운송하는 것은 어려우니 전쟁 지원을 계속하려면 사냥으로 물자를 확보해야 하오.', '', 28153),
(150647, 'koKR', '아, 그 정도면 충분할 것 같군요. 그 미끈미끈한 생물들이 당신 같은 분을 곤란하게 하진 않았겠지요?', '', 28153),
(150646, 'koKR', '가시돌풍 떼라고요? 막 먹물이 떨어진 참인데 이렇게 나타나 주다니 얼마나 착한 녀석들입니까! 이 두루마리를 받으십시오. 이걸로 녀석들에게서 귀한 먹물을 흡수할 수 있습니다.', '', 28153),
(150645, 'koKR', '', '우리 병력에 큰 도움이 될 기술 같군요. 잘하셨어요!', 28153),
(150644, 'koKR', '', '멕카토크가 무인 정찰기 기술을 개선했는데 실전 테스트가 필요하다는군요. 근처에 대규모 혈트롤이 숨어 있다는 소식이 있어요. 정찰기로 놈들을 찾아 처치하세요!', 28153),
(150643, 'koKR', '<올라탑니다!>', '<올라탑니다!>', 28153),
(150642, 'koKR', '<쿠아폰이 머리를 돌려 당신을 살펴봅니다. 반갑다는 표시로 날카로운 울음소리를 냅니다.>\n\n끽!', '', 28153),
(150641, 'koKR', '', '더러운 괴물 자식들.', 28153),
(150640, 'koKR', '', '라니슈는 위가 여러 개 있어요. 그러니까 하나를 찾았더라도 멈추지 말고 계속 찾아보세요.', 28153),
(150639, 'koKR', '날 수 없는 녀석도 있어서 횃대로 돌아가는 데 시간이 걸리겠군요. 분명 괜찮을 겁니다.$b$b나중에 보면 돌아와 있을 겁니다.', '', 28153),
(150638, 'koKR', '자, 고쳤습니다. 감사의 인사는 됐습니다.$b$b녀석이 약간 쓸쓸해 보이더군요. 다음 전투에 데려가 보십시오! 운동을 좀 하게 말입니다.', '', 28153),
(150637, 'koKR', '그 연은 뭐죠?', '그 연은 뭐죠?', 28153),
(150636, 'koKR', '', '카자를 따라잡아야 합니다. 가시죠!', 28153),
(150635, 'koKR', '', '서둘러 라케라 님을 찾아야 합니다!', 28153),
(150634, 'koKR', '진작에 했어요, 켄조우.', '', 28153),
(150633, 'koKR', '감사해요, $p 님. 당신 없이는 해내지 못했을 거예요. 당신 몫을 가져가세요.', '', 28153),
(150632, 'koKR', '그럼, 타차, 오미... 여기서 가져갈 만한 건 다 챙겨 갑시다.', '', 28153),
(150631, 'koKR', '그만! 내 손에 죽는 영광을 주마!', '', 28153),
(150630, 'koKR', '내 야수들아, 죽음도 우릴 가를 순 없다. 트잘라, 네 먹이다... 마음껏 먹어라!', '', 28153),
(150629, 'koKR', '누구도 내 검에 맞설 수 없다!', '', 28153),
(150628, 'koKR', '피를 볼 시간이군!', '', 28153),
(150627, 'koKR', '살을 발라주마!', '', 28153),
(150626, 'koKR', '이럴 수가? 좋아... 드디어!', '', 28153),
(150625, 'koKR', '너희는 잊혀지고, 내 전설은 영원하리라!', '', 28153),
(150624, 'koKR', '내 왕관은 절대 가져갈 수 없다!', '', 28153),
