(150486, 'koKR', '사우리드? 여기서 뭘 하는 거지?', '', 28153),
(150485, 'koKR', '', '그들이 누군지는 상관없어요. 그들의 도움이 필요해요. 고라크 툴이 세계로 나오게 해서는 안 돼요!', 28153),
(150484, 'koKR', '', '진정하세요, 애쉬턴 대가님! 아군입니다!', 28153),
(150483, 'koKR', '늦었습니다! 잠깐, 당신들은 누구죠?!', '', 28153),
(150482, 'koKR', '흠, 위험해 보이지는 않는구먼. 하, 그럼 공격은 끝난 거요?', '', 28153),
(150480, 'koKR', '물러서! 나는 연금술을 사용할 줄 안다고!', '', 28153),
(150479, 'koKR', '웨이크레스트 부인을 없애준 덕분에 너희 세계로 통하는 문이 열렸다.', '', 28153),
(150478, 'koKR', '한 치 앞도 못 보는 필멸자들. 죽음을 막을 수는 없다.', '', 28153),
(150477, 'koKR', '', '환영받지도 못하는 놈들이 오래도 머물렀군. 이제 네놈들은 절대 이 땅을 떠나지 못할 것이다!', 28153),
(150476, 'koKR', '', '내 일을 계속 방해하면 길고 고통스러운 죽음을 맞게 될 거다.', 28153),
(150475, 'koKR', '', '덜떨어진 표정을 보니 출신을 알 만하구나. 돼지우리 같은 집만 보다가 이런 곳에 오니 마냥 새롭고 신기한 모양이지.', 28153),
(150474, 'koKR', '', '다시 생각해 보니, 대답은 필요 없겠군.', 28153),
(150473, 'koKR', '', '네놈이 살던 곳에서는 안주인의 종을 함부로 죽이는 게 인사인 모양이지?', 28153),
(150472, 'koKR', '준비됐습니다. 다른 이들을 찾으러 갑시다.', '준비됐습니다. 다른 이들을 찾으러 갑시다.', 28153),
(150471, 'koKR', '낭비할 시간이 없네. 자네 친구들이 이미 아툴아만 안에 들어섰네...', '', 28153),
(150470, 'koKR', '쿠아폰이 분노로 울부짖으며 달아납니다.', '', 28153),
(150469, 'koKR', '', '꼬마야! 둥지로 돌아가고 싶으면 달리는 게 좋을 거다.', 28153),
(150468, 'koKR', '', '이제, 실전 훈련으로 들어가보자꾸나.', 28153),
(150467, 'koKR', '', '이 작은 녀석은 아직 자신의 날개를 믿지 못하는 것 같군. 계속 알려주어야 한다. 하늘의 즐거움을!', 28153),
(150466, 'koKR', '', '왜? 아직도 다리를 사용하는 게냐?!', 28153),
(150465, 'koKR', '', '둘 다 살아있군. 좋아. 그럴 줄 알았어...', 28153),
(150464, 'koKR', '', '감사해요. 서약단을 무너뜨리고 고라크 툴의 힘로부터 우리를 해방시켜 주셨군요. 큰 빚을 졌네요.', 28153),
(150463, 'koKR', '', '아셨죠, 강력한 육체와 무기로 해결할 수 없는 문제는 없어요.', 28153),
(150462, 'koKR', '하, 해냈군요. 고라크 툴을 물리쳤습니다.', '', 28153),
(150461, 'koKR', '충돌이 임박하자 쿠아폰이 울부짖으며 도움을 구합니다!', '충돌이 임박하자 쿠아폰이 울부짖으며 도움을 구합니다!', 28153),
(150460, 'koKR', '오너라, 필멸자여. 죽음을 맞이하라.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150459, 'koKR', '', '스턴타이드와 제가 여기서 막을게요. 끝을 내주세요!', 28153),
(150458, 'koKR', '', '저택에 있는 공포가 모두 우리 쪽으로 몰려와요!', 28153),
(150457, 'koKR', '', '고라크 툴이 우리 세계로 건너오게 해서는 안 돼요!', 28153),
(150456, 'koKR', '연이 격렬하게 흔들리기 시작합니다. 바람이 잔잔한 곳으로 돌아가십시오!', '연이 격렬하게 흔들리기 시작합니다. 바람이 잔잔한 곳으로 돌아가십시오!', 28153),
(150455, 'koKR', '|TInterface\\ICONS\\INV_POTION_24:20|t |cFFFF0404|Hspell:266198|h[연금술 불]|h|r을 사용하여 죽음에 물든 노예사냥꾼 시체를 파괴하십시오!', '', 28153),
(150454, 'koKR', '너희의 악몽은 이제 시작일 뿐이다.', '', 28153),
(150453, 'koKR', '웨이크레스트 부인은 내 힘을 담은 그릇일 뿐이었다. 너희가 그것을 파괴해준 덕에 너희 세계로 통하는 문이 열렸지.', '', 28153),
(150452, 'koKR', '흡수 중', '흡수 중', 28153),
(150451, 'koKR', '한 치 앞도 못 보는 어리석은 놈. 피할 수 없는 죽음이 매 순간 너를 쫓을 것이다.', '', 28153),
(150450, 'koKR', '', '마침내 악몽이 끝났어요.', 28153),
(150448, 'koKR', '가게, 수하여. 놈의 모자를 빼앗아 이 자니의 기쁨을 더해 주게나. 단, 그 굶주린 포식자들에게 들키지 않게 조심하게...', '', 28153),
(150446, 'koKR', '', '맞아요. 하지만 사람들이 제 가족이 저지른 끔찍한 짓을 알고도 어떻게 저를 다시 믿어주겠어요?', 28153),
(150445, 'koKR', '', '지금 중요한 건 그 악행을 멈추는 일이에요.', 28153),
(150444, 'koKR', '', '어머니가 잔인한 면이 있긴 했지만 이 정도일 줄은 정말 몰랐어요.', 28153),
(150443, 'koKR', '계속하시오. 웨이크레스트 부인을 찾아 복수해 주시오.', '', 28153),
(150442, 'koKR', '헤! 고깃덩이가 됐군.', '', 28153),
(150441, 'koKR', '웨이크레스트 부인은 이 사악한 마술을 부린 대가를 치러야 합니다.', '', 28153),
(150440, 'koKR', '영혼들에게 자유를 주셨으니, 좋은 일을 한 겁니다.', '', 28153),
(150439, 'koKR', '웨이크레스트 부인을 계속 쫓으십시오. 저는 이 방들을 살펴보겠습니다.', '', 28153),
(150438, 'koKR', '이 더러운 놈들이 밤에 쏘다니지 않는다니, 편히 쉴 수 있겠군요.', '', 28153),
(150437, 'koKR', '하수인을 처리하는 동안 우린 주변을 조사하겠습니다. 행운을 빌죠.', '', 28153),
(150436, 'koKR', '', '영웅들이여, 여러분의 힘이 필요해요. 우리가 이 악을 처단해야 해요.', 28153),
(150435, 'koKR', '무작정 달려드는 건 별로인 것 같습니다. 더 좋은 계획이 있는 거죠... 그렇죠?', '', 28153),
(150434, 'koKR', '메이스!', '', 28153),
(150433, 'koKR', '', '돌아와서 내 검을 받아라!', 28153),
(150432, 'koKR', '', '알겠습니다, 주인님.', 28153),
(150431, 'koKR', '', '얘들아, 손님을 친절히 맞이해 줘라.', 28153),
(150430, 'koKR', '', '초대받지 않은 손님이 있는 모양이군. 상관없다. 손님들이 머물 공간이야 많으니.', 28153),
(150429, 'koKR', '당신은 정말 놀라운 사람이군요.', '당신은 정말 놀라운 사람이군요.', 28153),
(150428, 'koKR', '고마워요, $r님!', '고마워요, $p 님!', 28153),
(150427, 'koKR', '자유다!', '자유다!', 28153),
(150426, 'koKR', '신세를 졌어요!', '신세를 졌어요!', 28153),
(150425, 'koKR', '정말 감사합니다!', '정말 감사합니다!', 28153),
(150421, 'koKR', '자네에게 내 힘을 나누어 주겠네. 이 보호물이 자네를 공격하는 부정한 자들을 없애 줄 걸세.', '', 28153),
(150420, 'koKR', '백성이 이렇게나 고통받고 있는데, 무서워서 숨어 버린 건가, 오랜 벗이여? 나와서 끝장을 보자, 코르테크!', '', 28153),
(150419, 'koKR', '내가 보물을 찾을 거야. 나랑 같이 작업하자고.', '내가 보물을 찾을 거야. 나랑 같이 작업하자고.', 28153),
(150418, 'koKR', '', '성가신 것들! 내 군대가 정비되면 이런 누추한 마을 따위 금방 우리 것이다!', 28153),
(150417, 'koKR', '줄의 배신이 내 생각보다 훨씬 뼈저리군. 그가 일으킨 반란으로 내 군대가 거의 파괴되었다.\n\n아직 내게 충성하는 자들은 끊임없이 침략하는 혈트롤 무리에 맞서 싸우며 전장에서 죽어가고 있지.\n\n탈란지의 말을 들었어야 했다...', '', 28153),
(150416, 'koKR', '그게 어디 있는지 아는 사람을 내가 아는데.', '그게 어디 있는지 아는 사람을 내가 아는데.', 28153),
(150415, 'koKR', '금화가 어디 있는지 아는가?', '금화가 어디 있는지 아는가?', 28153),
(150414, 'koKR', '보물을 찾으면 나랑 나눠 갖자고.', '보물을 찾으면 나랑 나눠 갖자고.', 28153),
(150413, 'koKR', '무쇠파도 녀석들이 벌써 찾았다던데?', '무쇠파도 녀석들이 벌써 찾았다던데?', 28153),
(150412, 'koKR', '어이, 보물찾기 좀 도와 달라고!', '어이, 보물찾기 좀 도와 달라고!', 28153),
(150411, 'koKR', '그 친구의 친구 말로는, 무쇠파도 녀석들 중 하나가 보물이 어디에 있는지 안다고 하는 걸 들었다던데...', '그 친구의 친구 말로는, 무쇠파도 녀석들 중 하나가 보물이 어디에 있는지 안다고 하는 걸 들었다던데...', 28153),
(150410, 'koKR', '금화 이야기가 전부 거짓말일 수도 있겠어.', '금화 이야기가 전부 거짓말일 수도 있겠어.', 28153),
(150409, 'koKR', '무쇠파도가 여기 들이닥치기 전에 이 보물을 찾아낼 거야.', '무쇠파도가 여기 들이닥치기 전에 이 보물을 찾아낼 거야.', 28153),
(150408, 'koKR', '', '누가 고양이를 잡아먹었나 봐.', 28153),
(150407, 'koKR', '[DNT] 집으로 날아가거라, 자랑스러운 라크자니야. 네 아빠에게 누가 널 풀어줬는지 말해주렴.', '', 28153),
(150406, 'koKR', '', '저는 선원들을 모으고 다른 이들에게 주위의 소형선을 모으게 하겠습니다. 즐거운 시간 되십시오, $n 님!', 28153),
(150405, 'koKR', '드러스트 왕이 놈들을 되살리기 전에 불태우십시오!', '', 28153),
(150404, 'koKR', '빨리 태워버리십시오!', '', 28153),
(150403, 'koKR', '여기 좀 도와주시겠습니까!', '', 28153),
(150402, 'koKR', '적에게 밀리고 있습니다!', '', 28153),
(150401, 'koKR', '어둠에 굴복하라!', '', 28153),
(150400, 'koKR', '일어나라!', '', 28153),
(150399, 'koKR', '누구도 내게 맞설 수 없다!', '', 28153),
(150398, 'koKR', '별 것도 아니구나!', '', 28153),
(150397, 'koKR', '모든 생명엔 끝이 있지.', '', 28153),
(150396, 'koKR', '죽음도... 나를 가두지 못한다...', '', 28153),
(150395, 'koKR', '죽음이 모두 먹어치운다!', '', 28153),
(150394, 'koKR', '아무도 내 복수에서 벗어날 수 없다!', '', 28153),
(150393, 'koKR', '모두 부엌으로 집합!', '', 28153),
(150392, 'koKR', '고기는 두들겨야 제맛이지!', '', 28153),
(150391, 'koKR', '오늘 저녁 요리는 특히나 맛있겠군...', '', 28153),
(150390, 'koKR', '맛있는... 고통이로구나...', '', 28153),
(150388, 'koKR', '', '불페라가 당신 뒤에 있어요, $p 님.\n\n거칠게 다뤄야 할 부정한 자들을 제게 보내 주시면 제가 반갑게 맞아줄게요.', 28153),
(150387, 'koKR', '오, 육즙이!', '', 28153),
(150386, 'koKR', '아, 신선한 고기!', '', 28153),
(150385, 'koKR', '군침이 도는군!', '', 28153),
(150384, 'koKR', '저녁 거리로구나!', '', 28153),
(150383, 'koKR', '보물을 찾은 사람은 지분을 세 배로 준다!', '', 28153),
(150382, 'koKR', '한몫 잡고 싶나? 보물을 찾아 와라!', '', 28153),
(150381, 'koKR', '목시, 저 근무태만자를 원 위치로!', '', 28153),
(150380, 'koKR', '끈질긴 무쇠파도 녀석들, 보물은 절대 못 준다!', '', 28153),
(150379, 'koKR', '해적 모자 쓴 녀석을 노려라! 그래, 그놈이다!', '', 28153),
(150378, 'koKR', '바위 밑도 찾아! 샅샅이 뒤져보라고!', '', 28153),
(150377, 'koKR', '이 무쇠파도 녀석들을 쓸어버려라!', '', 28153),
(150376, 'koKR', '<소 울음소리>', '', 28153),
(150375, 'koKR', '', '<소 울음소리>', 28153),
(150374, 'koKR', '', '미안합니다...', 28153),
(150373, 'koKR', '', '저는 의지의 여제, 무한한 연구의 전령입니다. 모델명: 의여무연령', 28153),
(150372, 'koKR', '', '지금까지 뭘 했든, 오늘부턴 좀 새로울 거다!', 28153),
(150371, 'koKR', '', '돈은 어디 있지?', 28153),
(150370, 'koKR', '', '여기 무언가 숨겨놓았다는 건 이미 알고 있다!', 28153),
(150369, 'koKR', '', '선착장에서 열심히 일해야지. 너희들 모두!', 28153),
(150368, 'koKR', '', '기대했던 것만큼 튼튼하지도 않구나.', 28153),
(150367, 'koKR', '', '선착장까지 이 족쇄를 차고 이동한다!', 28153),
(150366, 'koKR', '반갑군. 청소부의 제단에 견고하면서 단단한 것을 가져왔나?', '', 28153),
(150365, 'koKR', '포기하라고! 무덤에서 보물 찾아서 뭐 해?', '포기하라고! 무덤에서 보물 찾아서 뭐 해?', 28153),
(150364, 'koKR', '보물을 두고 갈 순 없어. 바로 여기 있단 말야!', '보물을 두고 갈 순 없어. 바로 여기 있단 말야!', 28153),
(150363, 'koKR', '무쇠파도가 온다! 어서 여기서 피해야 해!', '무쇠파도가 온다! 어서 여기서 피해야 해!', 28153),
(150362, 'koKR', '반갑군. 청소부의 제단에 반짝이고 매끄러운 것을 가져왔나?', '', 28153),
(150361, 'koKR', '도착했습니다. 하늘도 맑아 탐험하기 딱 좋은 날이군요.', '', 28153),
(150360, 'koKR', '보통 지진이 아닙니다... 근처 어디선가 아제라이트가 흘러나오는 겁니다.', '', 28153),
(150359, 'koKR', '장치를 활성화했습니다. 이제 모든 아제라이트를 볼 수 있을 겁니다.', '', 28153),
(150358, 'koKR', '조심하십시오. 상륙 중인 쿨 티란 함선입니다.', '', 28153),
(150357, 'koKR', '불공평해, 지난번에도 네가 가졌잖아!', '불공평해, 지난번에도 네가 가졌잖아!', 28153),
(150356, 'koKR', '이봐, 그건 내 거야!', '이봐, 그건 내 거야!', 28153),
(150355, 'koKR', '놈의 주머니를 뒤져!', '놈의 주머니를 뒤져!', 28153),
(150354, 'koKR', '열쇠를 가져 와!', '열쇠를 가져 와!', 28153),
(150353, 'koKR', '멍청한 것! 라즈가지가 널 죽음으로 내몰았구나!', '', 28153),
(150352, 'koKR', '', '나와 같은 생각을 했군. 용사여, 네가 우리 가설을 시험해 보겠느냐?', 28153),
(150351, 'koKR', '흥미롭군. 위습이 말퓨리온의 부름에 응답하네. 숲의 다른 존재들도 도움을 요청하면 어떻게 될까?', '', 28153),
(150350, 'koKR', '', '전세를 뒤바꿀 정도로... 위습을 파괴할 순 없다. 하나, 놈들을 분산시킬 순 있지.', 28153),
(150349, 'koKR', '그 누구도 통고의 물건을 훔쳐갈 순 없다!', '', 28153),
(150348, 'koKR', '', '내가 말퓨리온에게 보낸 정찰대도 위습을 우습게 봤지. 그들은 그 대가를 치러야만 했다.', 28153),
(150347, 'koKR', '위습의 벽이라고요? 어둠 순찰자들과 파괴전차가 넘어서지 못할 건 없습니다, 여왕님.', '', 28153),
(150346, 'koKR', '난 무너지지... 않을 것이다...', '', 28153),
(150345, 'koKR', '부정한 자들이 쓰기에는 너무 약한 테러닥스군!', '', 28153),
(150344, 'koKR', '', '반가워요! 지쳤을 텐데 여기서 좀 쉬고 가세요.', 28153),
(150343, 'koKR', '', '필요한 게 있으면 말씀하세요!', 28153),
(150342, 'koKR', '', '제 선술집에 오신 걸 환영해요! 와서 목이라도 축이세요.', 28153),
(150341, 'koKR', '', '친구여, 하루 잘 보내고 있나요? 여기가 집이라 생각하고 편히 있다 가세요.', 28153),
(150340, 'koKR', '', '휴식이 필요해 보이시네요. 좀 앉으세요. 식사도 하시고요!', 28153),
(150339, 'koKR', '반갑군. 청소부의 제단에 정전기가 생기는 날카로운 물건을 가져왔나?', '', 28153),
(150338, 'koKR', '이 아제라이트는 모두 내 거야!', '이 아제라이트는 모두 내 거야!', 28153),
(150337, 'koKR', '', '아프면 얘기해...', 28153),
(150336, 'koKR', '', '와, 정말 피 많이 흘리네!', 28153),
(150335, 'koKR', '', '선장님, 제 장치가 근처에 있는 적을 감지했어요. 드디어 제 칼을 쓸 시간이 왔군요!', 28153),
(150334, 'koKR', '', '불나도 내가 고치고, 폭발해도 내가 고치고... 으! 내 신세야!', 28153),
(150333, 'koKR', '', '으, 폭발한다고 다 실패는 아니에요. 폭발과 실패가 양립 불가한 게 아니라고요!', 28153),
(150332, 'koKR', '', '선장님이... 싫어하실 텐데...', 28153),
(150331, 'koKR', '', '찔릴 준비나 하시지!', 28153),
(150330, 'koKR', '', '깜짝 놀랐지!', 28153),
(150329, 'koKR', '', '찔러 버리겠어!', 28153),
(150328, 'koKR', '이거 살짝 아파지는데?', '', 28153),
(150327, 'koKR', '하하하, 화끈하구먼!', '', 28153),
(150326, 'koKR', '이제 넌 물고기 밥이다!', '', 28153),
(150325, 'koKR', '뭘 보고 있나?', '', 28153),
(150324, 'koKR', '이제 내가... 물고기 밥이 되었군...', '', 28153),
(150323, 'koKR', '이 섬에 있는 녀석들, 그냥 조무래기는 아니군. 멀리 돌아온 보람이 있겠어.', '', 28153),
(150322, 'koKR', '벌레 놈들, 내 낚싯바늘에 걸어 주마!', '', 28153),
(150321, 'koKR', '물고기 미끼로 써 주마!', '', 28153),
(150320, 'koKR', '이제 폭풍우를 맞이하십시오!', '', 28153),
(150319, 'koKR', '', '어서 양동이 좀 가져와! 한 방울도 흘리면 안 된다!', 28153),
(150318, 'koKR', '', '이 섬은 발 디딜 틈이 없구나. 별의별 종족과 동물과 벌레에... 호드까지! 가서 피를 가져오너라!', 28153),
(150317, 'koKR', '', '좋아, 얘들아! 피를 가져와라... 달콤한 피를...! 너희들이 챙길 보물도 있을지 모르지.', 28153),
(150316, 'koKR', '', '호드의 피는 최고지! 얘들아, 해야할 일은 알고 있겠지?', 28153),
(150315, 'koKR', '', '안녕하신가! 혹시 몸에 남는 피 좀 없나? 좀 나눠주고 가지 그래?', 28153),
(150314, 'koKR', '', '내 아까운... 피...', 28153),
(150313, 'koKR', '', '더 빨리 죽여라! 피가 필요하다!', 28153),
(150312, 'koKR', '', '피를 볼 시간이다!', 28153),
(150311, 'koKR', '', '모두 없애주마!', 28153),
(150310, 'koKR', '아! 하하하!', '', 28153),
(150309, 'koKR', '히히히히!', '', 28153),
(150308, 'koKR', '얼...라이...언스! 노올자!', '', 28153),
(150307, 'koKR', '안녕하신가!', '', 28153),
(150306, 'koKR', '에... 헤... 헤...', '', 28153),
(150305, 'koKR', '멈춰라!', '', 28153),
(150304, 'koKR', '교활한 피트 나가신다!', '', 28153),
(150303, 'koKR', '교활한 피트 나가신다!', '', 28153),
(150302, 'koKR', '교활한 피트 나가신다!', '', 28153),
(150301, 'koKR', '그만 좀 찔러!', '', 28153),
(150300, 'koKR', '야, 간지럽잖아!', '', 28153),
(150299, 'koKR', '날려버려 주마!', '', 28153),
(150298, 'koKR', '하! 잡았다!', '', 28153),
(150297, 'koKR', '룬 문자를 크게 읽습니다.', '룬 문자를 크게 읽습니다.', 28153),
(150295, 'koKR', '황금 왕좌로 가고 싶습니다.', '황금 왕좌로 가고 싶습니다.', 28153),
(150294, 'koKR', '', '용사여, 내가 위습을 어떻게 처리할지 생각할 동안, 칼도레이의 주의를 끌어 주어야겠구나.', 28153),
(150293, 'koKR', '', '흠, 위습들이 흩어지고 있었다고? 좋아. 계획이 잘 풀릴 것 같군...', 28153),
(150292, 'koKR', '', '내 파괴자가 널 갈기갈기 찢어줄 거다! 피할 수 있다면 피해 봐라!', 28153),
(150291, 'koKR', '', '수행사제들아, 방벽을 무너뜨려라!', 28153),
(150290, 'koKR', '', '가라, 얘들아! 갈기갈기 찢어버려!', 28153),
(150289, 'koKR', '', '용사들이여, 나와 함께해라. 대단원의 막을 지켜볼 영광을 너희에게 주겠다.', 28153),
(150288, 'koKR', '', '아니면, 그대의 아들과 인사라도 나눌 수 있겠지.', 28153),
(150287, 'koKR', '', '그놈의 전사다운 죽음이나 맞으시오, 사울팽. 나와는 상관없으니. 어쩌면 그대의 부서진 몸뚱이를 병사로서 써먹을 수 있을지도.', 28153),
(150286, 'koKR', '', '명예롭기만 하다면 부하들이 죽어도 상관없다고 생각하는군. 하지만, 내게 호드는 지킬 가치가 있소. 이에 반대한다면 호드의 편에 설 자격이 없지.', 28153),
(150285, 'koKR', '', '시체에게 명예가 무슨 소용이겠소, 사울팽. 그대는 죽음이 아무 것도 아니라고 생각하는군. 그쪽과 달리 나는 죽음을 아주 잘 알고 있소.', 28153),
(150284, 'koKR', '대족장님의 전략을 믿으시오, 테론!', '', 28153),
(150283, 'koKR', '공허 엘프... 저 배신자들을 처리해야 하오!', '', 28153),
(150282, 'koKR', '로데론의 주인은 우리 포세이큰이다! 물러설 생각 마라!', '', 28153),
(150281, 'koKR', '공격이 곧 주춤해질 것이오. 굳건히 버티시오!', '', 28153),
(150280, 'koKR', '얼라이언스는 붕괴 직전이오, 용사들이여! 벌써 놈들의 반 이상이 쓰러졌소.', '', 28153),
(150279, 'koKR', '하하하! 이게 누구신가. 안 그래도 네가 이 전투를 흥미롭게 해 주기를 기다리고 있었다!', '', 28153),
(150278, 'koKR', '그건 그분께 직접 들으시죠. 어서 가십시오!', '', 28153),
(150277, 'koKR', '놈들을 얼마나 잡아둘 수 있을 것 같소? 대족장의 작전이 뭐요?', '', 28153),
(150276, 'koKR', '아뇨, 로르테마르와 제가 침입자를 처리할 겁니다. 대족장님을 무방비하게 두는 건 너무 위험합니다. 그분 곁을 떠나지 마십시오.', '', 28153),
(150275, 'koKR', '알겠소. 가능한 한 빨리 합류하겠소.', '', 28153),
(150274, 'koKR', '성채 측면으로 들어오는 녀석들은 좁은 관문 탓에 대형을 좁힐 테죠.', '', 28153),
(150273, 'koKR', '시간이 없습니다! 지리적 우위를 잃기 전에 최대한 그걸 활용해야 합니다!', '', 28153),
(150272, 'koKR', '알겠소. 헌데... 사울팽은 어디 있는 거요?', '', 28153),
(150271, 'koKR', '바인이여! 투척기를 모으고 최대한 많은 연금술사를 바로 성으로 보내 주십시오!', '', 28153),
(150270, 'koKR', '분부대로, 블라이트콜러.', '', 28153),
(150269, 'koKR', '로르테마르, 궁수들을 측면의 성벽 꼭대기에 배치해 주시오!', '', 28153),
(150268, 'koKR', '역병투척자들이여, 너희들은 최전방을 맡아 줘야겠다! 역병을 만들어 아군과 적군 사이를 갈라 놓아라!', '', 28153),
(150267, 'koKR', '분부대로 하죠, 여왕이여.', '', 28153),
(150266, 'koKR', '', '로르테마르에게 가라. 어서! 날 실망시키지 마라, 나타노스!', 28153),
(150265, 'koKR', '방독면! 방독면 챙기라고! 기운이 펄펄 넘친다면 이 가방 하나 챙겨서 작업을 시작해도 되고!', '', 28153),
(150264, 'koKR', '명예를 지켜라, 영웅들이여. 로크 나라쉬!', '', 28153),
(150263, 'koKR', '', '모두 쓸어버려라, 용사들이여! 명심해라. 안두인 국왕과 군대는 놀러 온 게 아니다. 우리를 끝낼 작정으로 왔다! 자비를 보이지 마라. 놈들도 자비를 보이지 않을 테니까!', 28153),
(150262, 'koKR', '호드의 병사들이여! 너희 형제자매가 전장에 상처 입고 쓰러져 있다! 동족을 버린다면 이 승리에 명예는 없을 것이다!', '', 28153),
(150261, 'koKR', '록타르 오가르!', '', 28153),
(150260, 'koKR', '놈들은 수가 많다. 하지만 우리는 더 강력하다. 우리는 호드다! 우릴 해하려는 자들은 모두 짓밟는다!', '', 28153),
(150259, 'koKR', '용사들이여! 대족장의 명령이다! 무기를 들고 얼라이언스와 싸울 때가 되었다!', '', 28153),
(150258, 'koKR', '', '그렇다면 이제 모든 걸 끝낼 때가 왔군. 사울팽, 병력을 모으시오. 나는 아제라이트 기계를 준비시키겠소.', 28153),
(150257, 'koKR', '그렇소.', '', 28153),
(150256, 'koKR', '서둘러라! 대족장이 기다린다!', '', 28153),
(150255, 'koKR', '어서 제 쪽으로 오십시오! 호드가 반격하기 전에 밀어붙여야 합니다!', '', 28153),
(150254, 'koKR', '놈의 바람은 세차지만, 우리가 힘을 합하면 더 강합니다! 버티세요, 용사들이여!', '', 28153),
(150253, 'koKR', '느려 빠졌어!', '', 28153),
(150252, 'koKR', '', '서두르세요! 얼음 방벽도 오래 버티지 못할 겁니다!', 28153),
(150251, 'koKR', '영웅들이여! 추가 병력에 집중하세요. 그 뒤에 주술사를 처리합시다!', '', 28153),
(150250, 'koKR', '대족장께서... 너희를... 막을 것이다.', '', 28153),
(150249, 'koKR', '독수리 영혼의 바람이 네놈들의 뼈를 발라버릴 것이다!', '', 28153),
(150248, 'koKR', '', '', 28153),
(150246, 'koKR', '끼이익.', '', 28153),
(150245, 'koKR', '끼이이이익!', '', 28153),
(150244, 'koKR', '끼이익!', '', 28153),
(150242, 'koKR', '책 곳곳에 마법이 부여된 룬 문자가 가득 쓰여 있습니다.', '책 곳곳에 마법이 부여된 룬 문자가 가득 쓰여 있습니다.', 28153),
(150241, 'koKR', '죽여도 됩니까? 죽여도 된다고 했잖습니까.', '', 28153),
(150240, 'koKR', '뭐라고요?', '', 28153),
(150239, 'koKR', '이 상자는 제 겁니다, 욕심 많은 $r같으니!', '안 됩니다! 이 상자는 제 겁니다!\n\n저는 수프에 쓸 벌레를 잡으러 여기에 왔습니다. 게살로 만드는 수프가 환상적이라는 토르톨란도 더러 있지만 저는 그런 친구들과는 어울리지 않습니다. 고작 게살 수프를 먹겠다고 애써 낯선 사람이랑 친구가 될 필요는 없습니다.\n\n진흙 벌레 수프는 평생을 가는 우정을 만든다고 하지요. 참고로, 우리 토르톨란은 굉장히 장수하는 편입니다.\n\n진흙 벌레 고기를 좀 찾아다 주시면 이 상자를 넘기는 것도 생각해보도록 하겠습니다.', 28153),
(150238, 'koKR', '윽... 아파...', '', 28153),
(150237, 'koKR', '으아아아!', '', 28153),
(150236, 'koKR', '무기를 꺼내기 전에 제 말 좀 들어 보십시오...', '', 28153),
(150235, 'koKR', '', '시체에서 건질 게 있는지 확인해라.', 28153),
(150234, 'koKR', '', '아직도 섬의 보물을 배에 싣지 못했나? 빨리 움직여, 이 게으름뱅이들아! 얼라이언스의 전리품도 뺏어와라!', 28153),
(150233, 'koKR', '', '얼라이언스도 있군. 산 채로 말이야. 손을 봐줘야겠어.', 28153),
(150232, 'koKR', '', '이 섬을 털어야겠다, 얘들아. 가라! 날 기다리게 하지 마라.', 28153),
(150231, 'koKR', '', '무슨 일이지?', 28153),
(150230, 'koKR', '', '아무것도... 돌려주지 마라...', 28153),
(150229, 'koKR', '', '그만 됐다! 모두 죽여, 당장!', 28153),
(150228, 'koKR', '', '네놈을 죽이고 나면 벗겨먹기 더 쉽겠군!', 28153),
(150227, 'koKR', '', '얼라이언스에 대한 안 좋은 얘기를 들었습니다. 가까이하지 맙시다.', 28153),
(150226, 'koKR', '', '이게 도움이 될 겁니다.', 28153),
(150225, 'koKR', '', '제가 도와드리죠.', 28153),
(150224, 'koKR', '', '안녕하십니까.', 28153),
(150223, 'koKR', '', '내가... 옳았어...', 28153),
(150222, 'koKR', '', '이런, 그들이 왔습니다.', 28153),
(150221, 'koKR', '조금 후퇴해야겠습니다.', '', 28153),
(150220, 'koKR', '그만하면 됐다.', '', 28153),
(150219, 'koKR', '가까이 오지 마라, 얼라이언스. 그렇지 않으면 짓밟아 주겠다.', '', 28153),
(150218, 'koKR', '안녕하십니까.', '', 28153),
(150217, 'koKR', '쿠아폰이 음식을 집어삼킵니다. 고기 살점이 곳곳에 흩날립니다.', '', 28153),
(150216, 'koKR', '빛이여... 난 다시 돌아올... 것이다...', '', 28153),
(150215, 'koKR', '분노를 폭발시키십시오!', '', 28153),
(150214, 'koKR', '장난 칠 시간은 없다!', '', 28153),
(150213, 'koKR', '', '자, 진정하시고.', 28153),
(150212, 'koKR', '', '속도를 좀 늦춰볼까.', 28153),
(150211, 'koKR', '', '최후를 맞을 시간이다.', 28153),
(150210, 'koKR', '', '재에서 재로.', 28153),
(150209, 'koKR', '', '바람이 우리를 여기로 이끌었어요... 얼라이언스도 같이 말이죠. 정령들이 하는 일에는 아직도 가끔 놀란답니다.', 28153),
(150208, 'koKR', '', '잘 들어라, 얼라이언스. 우리를 방해하지 않으면 우리도 방해하지 않겠다.', 28153),
(150207, 'koKR', '', '이곳의 정령들이 균형을 잃었어요. 우리가 도울 수 있는지 알아보죠. 단, 얼라이언스가 끼어들어선 안 돼요.', 28153),
(150206, 'koKR', '', '여긴 무슨 일이신가요?', 28153),
(150205, 'koKR', '', '내 영혼은... 돌아올... 것이다...', 28153),
(150204, 'koKR', '', '내 참을성을 시험하는군.', 28153),
(150203, 'koKR', '', '정령이여, 도와주세요.', 28153),
(150202, 'koKR', '', '제가 도와드릴게요.', 28153),
(150201, 'koKR', '', '빛이 당신을 밝힐 거예요!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150200, 'koKR', '', '난 살생을 즐기지 않는다.', 28153),
(150199, 'koKR', '', '적이 도착했으니 조심하죠. 가급적이면 상대하지 않도록 해요.', 28153),
(150198, 'koKR', '<|TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[대형 공룡 사료]|h|r를 줍니다.>', '<|TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[대형 공룡 사료]|h|r를 줍니다.>', 28153),
(150197, 'koKR', '', '빛이 당신을 반겨 주기를!', 28153),
(150196, 'koKR', '', '저도... 눈부신 빛속으로...', 28153),
(150195, 'koKR', '<조바심내며 턱을 딱딱 부딪치는 쿠아폰>\n\n끼이익.', '', 28153),
(150194, 'koKR', '', '항복해라! 무의미한 죽음은 피해라!', 28153),
(150193, 'koKR', '<당신의 냄새를 맡는 쿠아폰>\n\n끽.', '', 28153),
(150192, 'koKR', '정말 이렇게 하고 싶은 겁니까? 전리품은 고사하고 아무런 영향도 주지 못할 겁니다.', '정말 이렇게 하고 싶은 겁니까? 전리품은 고사하고 아무런 영향도 주지 못할 겁니다.', 28153),
(150191, 'koKR', '강력한 적입니다!', '', 28153),
(150190, 'koKR', '빛의 심판이다!', '', 28153),
(150189, 'koKR', '대족장님께서 위습들을 쫓아버리길 원한다고? 딱 좋은 게 있지.\n\n이걸 타고 날아볼래? 아니면 폭격을 좀 해보고 싶어?', '', 28153),
(150188, 'koKR', '이곳엔 빛이 밝게 빛납니다. 아제라이트도 많이 묻혀 있지요.', '', 28153),
(150187, 'koKR', '아직 처리 방법에 관해 생각 중입니다. 나무를 좀 베든가, 나무에서 빛이라도 나게 만들어야겠군요.\n\n마치 대단한 장관이었던 것처럼 연기하십시오. 위습들이 벽에서 나와, 당신이 폭탄을 던진 자리에 균열이 드러난 것처럼요.', '아직 처리 방법에 관해 생각 중입니다. 나무를 좀 베든가, 나무에서 빛이라도 나게 만들어야겠군요.\n\n마치 대단한 장관이었던 것처럼 연기하십시오. 위습들이 벽에서 나와, 당신이 폭탄을 던진 자리에 균열이 드러난 것처럼요.', 28153),
(150186, 'koKR', '날기로 하죠.', '날기로 하죠.', 28153),
(150185, 'koKR', '나는 방법은 어떻습니까. 숲을 불태우는 건 제 방식이 아닙니다.', '나는 방법은 어떻습니까. 숲을 불태우는 건 제 방식이 아닙니다.', 28153),
(150184, 'koKR', '빛이 함께하길.', '', 28153),
(150183, 'koKR', '꽤... 잘 싸우는군...', '', 28153),
(150181, 'koKR', '빛이여, 적을 무찔러 주소서!', '', 28153),
(150180, 'koKR', '빛을 위하여!', '', 28153),
(150179, 'koKR', '', '어딜 도망가려고.', 28153),
(150178, 'koKR', '', '물러나라.', 28153),
(150177, 'koKR', '', '이놈을 끝장내 버리죠!', 28153),
(150176, 'koKR', '', '우리가 승리한다!', 28153),
(150175, 'koKR', '', '이런 게 진정한 모험이죠! 온갖 위험과 보물이 숨어 있는 미지의 섬이라니! 잠깐, 여기 호드도 있습니까?', 28153),
(150174, 'koKR', '', '어떤 모험이 우릴 기다릴지 살펴봅시다. 호드를 몰아내기만 하면 돼요.', 28153),
(150173, 'koKR', '', '어둠의 존재는 승리하지 못하리라! 빛의 복수가 너희를 정복할 것이다!', 28153),
(150172, 'koKR', '', '만나서 반가워요.', 28153),
(150171, 'koKR', '', '빛이... 나를 구원하리라...', 28153),
(150170, 'koKR', '', '넌 우리 상대가 안 된다!', 28153),
(150169, 'koKR', '<끽끽 울며 반기는 쿠아폰>\n\n끽!', '', 28153),
(150168, 'koKR', '<당신을 향해 힘차게 고개를 까닥거리는 쿠아폰>', '', 28153),
(150166, 'koKR', '<당신을 향해 장난치듯 꾸르륵 소리를 내는 쿠아폰>', '', 28153),
(150165, 'koKR', '', '공허에 이 영혼을 바치리!', 28153),
(150164, 'koKR', '<당신이 다가가자 머리를 그쪽으로 기울이는 쿠아폰>\n\n끽?', '', 28153),
(150163, 'koKR', '', '공허를 위하여!', 28153),
(150162, 'koKR', '', '여기에요! 여기 도착했어요. 속삭임이 말한 그대로요! 그래요! 하하하. 그럼요, 그렇고 말고요.', 28153),
(150161, 'koKR', '', '네? 방금 누가 말한 거죠?', 28153),
(150160, 'koKR', '', '하하하하... 공허로 사라진다...', 28153),
(150159, 'koKR', '', '얘들아, 먹어라!', 28153),
(150158, 'koKR', '', '훌륭한 영혼이로구나!', 28153),
(150157, 'koKR', '혼돈을 느껴 봐라!', '', 28153),
(150156, 'koKR', '한심하군.', '', 28153),
(150155, 'koKR', '호드 야만인들이 먼저 와있군요. 하, 마치 공허를 상대할 수 있을 것처럼 구는군요.', '', 28153),
(150154, 'koKR', '코볼트와 지하 미궁!', '코볼트와 지하 미궁!', 28153),
(150153, 'koKR', '코볼트와 지하 미궁!', '코볼트와 지하 미궁!', 28153),
(150152, 'koKR', '재물을 얻을지, 목숨을 잃을지이이이...', '재물을 얻을지, 목숨을 잃을지이이이...', 28153),
(150151, 'koKR', '살아남을 수는 있을까아아아!', '살아남을 수는 있을까아아아!', 28153),
(150150, 'koKR', '공허여, 나를 지탱하라!', '', 28153),
(150149, 'koKR', '달아나도, 곧 다가오고,', '달아나도, 곧 다가오고,', 28153),
(150148, 'koKR', '황급히 달리고, 괴물들은 뒤쫓고, 출구를 찾으려 안간힘을 쓰지!', '황급히 달리고, 괴물들은 뒤쫓고, 출구를 찾으려 안간힘을 쓰지!', 28153),
(150147, 'koKR', '공허를 받아들이십시오!', '', 28153),
(150146, 'koKR', '그 빛을 훔치면, 곧 도망쳐야 해. 온갖 함정들을 피하며!', '그 빛을 훔치면, 곧 도망쳐야 해. 온갖 함정들을 피하며!', 28153),
(150145, 'koKR', '너 양초 못 가져간다!', '너 양초 못 가져간다!', 28153),
(150144, 'koKR', '너 양초 못 가져간다!', '너 양초 못 가져간다!', 28153),
(150143, 'koKR', '하지만 단 하나 탐내지 말 거어어어언...', '하지만 단 하나 탐내지 말 거어어어언...', 28153),
(150142, 'koKR', '조심스레 앞으로 나아가고, 두 손 가득 전리품을 들며!', '조심스레 앞으로 나아가고, 두 손 가득 전리품을 들며!', 28153),
(150141, 'koKR', '보물이 가득, 하나 위험도 문득, 규칙도 상식도 없는 곳.', '보물이 가득, 하나 위험도 문득, 규칙도 상식도 없는 곳.', 28153),
(150140, 'koKR', '안녕하세요.', '', 28153),
(150139, 'koKR', '알확천금을 꿈꾸며.', '알확천금을 꿈꾸며.', 28153),
(150138, 'koKR', '아... 어둠이... 날 감싸는군...', '', 28153),
(150137, 'koKR', '불쌍한 녀석들. 먹힐 준비나 해라.', '', 28153),
(150136, 'koKR', '제대로 좀 해 봐.', '', 28153),
(150135, 'koKR', '최고의 동료들, 장대한 모험,', '최고의 동료들, 장대한 모험,', 28153),
(150134, 'koKR', '뛰어난 모험가들을 기다리는 엄청난 보물이 있다고 하지...', '뛰어난 모험가들을 기다리는 엄청난 보물이 있다고 하지...', 28153),
(150133, 'koKR', '이제 승리의 자세를 취해도 되겠습니까? 아, 호드 먼저 죽이라고요? 그러죠, 뭐.', '', 28153),
(150132, 'koKR', '전설에 따르면 드넓은 지하 세계에...', '전설에 따르면 드넓은 지하 세계에...', 28153),
(150131, 'koKR', '오예!', '오예!', 28153),
(150130, 'koKR', '오, 나를 보니 기분이 끝내주지? 죽어서도 계속 같은 기분일까 모르겠네!', '', 28153),
(150129, 'koKR', '호드 함선입니다! 놈들이 우리를 발견하면 어떤 표정을 지을지 정말 기대되는군요.', '', 28153),
(150128, 'koKR', '얘들아 노래 부르는 거 좋아하니?', '얘들아 노래 부르는 거 좋아하니?', 28153),
(150127, 'koKR', '히힛!', '히힛!', 28153),
(150126, 'koKR', '아, 어서 오십시오!', '', 28153),
(150125, 'koKR', '하하!', '하하!', 28153),
(150124, 'koKR', '여기야!', '', 28153),
(150123, 'koKR', '왜 그래? 따라오기 힘들어?', '', 28153),
(150122, 'koKR', '만세!', '만세!', 28153),
(150121, 'koKR', '잡아라!', '잡아라!', 28153),
(150120, 'koKR', '윽, 운 좋게 맞혔군...', '', 28153),
(150119, 'koKR', '세상에!', '세상에!', 28153),
(150118, 'koKR', '나야, 나! 걱정 마. 살살 해줄 테니.', '', 28153),
(150117, 'koKR', '안녕, 호드. 난 켈레인이야. 여기서 보니 반갑네.', '', 28153),
(150116, 'koKR', '', '물러나라, 미물아!', 28153),
(150115, 'koKR', '그로즈토크와 마주치신다면 주저하지 말고 그의 검은 심장에 칼을 꽂아주십시오.', '', 28153),
(150114, 'koKR', '', '천한 것!', 28153),
(150113, 'koKR', '', '감히 내게 피를 묻히다니! 앞으로 조심하거라.', 28153),
(150112, 'koKR', '', '이런, 운이 참 없구나, 얼라이언스여. 곧 무덤 자리를 알려주마.', 28153),
(150111, 'koKR', '그로즈토크에게 걸맞은 최후였습니다. 고통스럽게 죽었기를 바랍니다.', '', 28153),
(150110, 'koKR', '', '맙소사, 내가 숙녀답지 못한 짓을.', 28153),
(150109, 'koKR', '저는 이 모래 언덕에서 죽을 겁니다. 저는 죽어 마땅해요.', '', 28153),
(150108, 'koKR', '', '저런 저런, 치료할까요.', 28153),
(150107, 'koKR', '', '아, 당신인가요. 안녕하신지.', 28153),
(150106, 'koKR', '', '이건 정말... 내 수준에 안 맞아...', 28153),
(150105, 'koKR', '', '장갑을 껴라! 손이 더러워질 테니.', 28153),
(150104, 'koKR', '', '여기, 이 약한 놈을 노리죠!', 28153),
(150103, 'koKR', '', '좋았어! 방금 보셨나요?', 28153),
(150102, 'koKR', '', '어서! 어서 배에서 내리시죠. 시간이 없습니다! 자, 어서 서두르십시오!', 28153),
(150101, 'koKR', '', '저도 나가서 싸울 수 있는데 왜 여기 처박혀 있어야 할까요?', 28153),
(150100, 'koKR', '감독관의 열쇠를 손에 넣었으니, 이제 우리 요원들을 풀어주고 이들을 활용해 전선을 보강할 수 있겠네.', '', 28153),
(150099, 'koKR', '', '하하! 시도는 좋았다!', 28153),
(150098, 'koKR', '', '느려 빠졌어!', 28153),
(150097, 'koKR', '어둠의 여왕께서 기뻐하시겠군.', '', 28153),
(150096, 'koKR', '', '윽, 말도... 안 돼! 끔찍한... 놈들 같으니...', 28153),
(150095, 'koKR', '', '모두 공격!', 28153),
(150094, 'koKR', '', '내게서 도망칠 수 없다!', 28153),
(150093, 'koKR', '지금입니다! 이 녀석을 쓰러뜨리죠!', '', 28153),
(150092, 'koKR', '피할 수 없는 운명이다.', '', 28153),
(150091, 'koKR', '놈에게서 열쇠를 빼앗아, 우리 요원들을 풀어 주게. 걸리적거리는 놈들은 모조리 없애도 좋네.', '', 28153),
(150090, 'koKR', '때가 왔습니다. 훈련한 대로 얼라이언스에게 명가란 무엇인지 알려주십시오.', '', 28153),
(150089, 'koKR', '꼭대기 층으로 이동하게. 거기에 감독관이 있을 걸세.', '', 28153),
(150088, 'koKR', '집중하십시오. 상대할 만한 적이 근처에 있습니다. 얼라이언스도 있군요.', '', 28153),
(150087, 'koKR', '최근 탈옥 사건으로 감옥 하층부가 혼란스러운 상황이네. 우린 이걸 유리하게 활용할 수 있겠지.', '', 28153),
(150086, 'koKR', '얼라이언스가 있습니다. 마력을 집중하세요. 실수하면 안 됩니다.', '', 28153),
(150085, 'koKR', '우리의 목표가 톨 다고르에 갇혀 있네.', '', 28153),
(150084, 'koKR', '안녕하십니까.', '', 28153),
(150083, 'koKR', '어서... 후퇴하십시오...', '', 28153),
(150082, 'koKR', '계획대로 갑니다! 교전하십시오!', '', 28153),
(150081, 'koKR', '공격하십시오! 저를 따르세요!', '', 28153),
(150080, 'koKR', '오, 오, 최우선 목표예요!', '', 28153),
(150079, 'koKR', '잡았다! 잡았어!', '', 28153),
(150078, 'koKR', '호드가 있다고요? 화, 확실해요? 아니, 제게 섬세한 장비가 있는데 무, 무척 비싼 거라서요.', '', 28153),
(150077, 'koKR', '안녕하세요!', '', 28153),
(150076, 'koKR', '여러분... 제가... 뭐랬나요...', '', 28153),
(150075, 'koKR', '$n|1이;가; 완전히 충전되었습니다!', '$n|1이;가; 완전히 충전되었습니다!', 28153),
(150074, 'koKR', '$n에게 힘이 모여들고 있습니다!', '$n에게 힘이 모여들고 있습니다!', 28153),
(150073, 'koKR', '꺼져!', '', 28153),
(150072, 'koKR', '$n의 동력 수준이 다시 증가합니다...', '$n의 동력 수준이 다시 증가합니다...', 28153),
(150071, 'koKR', '어... 이, 이래도 되, 되는지 모르겠네!', '', 28153),
(150070, 'koKR', '$n의 동력 수준이 증가합니다...', '$n의 동력 수준이 증가합니다...', 28153),
(150069, 'koKR', '', '의무병!', 28153),
(150068, 'koKR', '혼돈의 불꽃이 전장으로 돌진합니다!', '혼돈의 불꽃이 전장으로 돌진합니다!', 28153),
(150067, 'koKR', '', '목표물 제거.', 28153),
(150066, 'koKR', '근처에 마력 핵이 형성됩니다.', '근처에 마력 핵이 형성됩니다.', 28153),
(150065, 'koKR', '', '준비하세요, 호드가 왔습니다! 전리품은 쓰러뜨린 다음 챙겨도 늦지 않아요!', 28153),
(150064, 'koKR', '', '좋은 건 남 주면 안 되죠.', 28153),
(150063, 'koKR', '', '물러날게요.', 28153),
(150062, 'koKR', '눈앞에서 순수한 에너지의 존재가 형성됩니다.', '눈앞에서 순수한 에너지의 존재가 형성됩니다.', 28153),
(150061, 'koKR', '', '아우... 따가워라...', 28153),
(150060, 'koKR', '', '이동 중인 적 포착!', 28153),
(150059, 'koKR', '', '머리를 노려요. 거기가 약점이에요!', 28153),
(150058, 'koKR', '놈들을 쓰러뜨릴 시간이다!', '', 28153),
(150057, 'koKR', '로봇 싸움에 칼을 들고 오면 쓰나.', '', 28153),
(150056, 'koKR', '놈들이 내 기계타조를 파괴했다! 후퇴!', '', 28153),
(150055, 'koKR', '기계타조 파괴! 지원이 필요하다, 어서!', '', 28153),
(150054, 'koKR', '짜부라졌군.', '', 28153),
(150053, 'koKR', '착한 벌레는 죽은 벌레뿐. 그리고 호드는 벌레와 꼭 닮았지.', '', 28153),
(150052, 'koKR', '역사적으로도 갈등 해결엔 폭력만한 게 없었지. 이참에 한 번 더 증명해 보자고.', '', 28153),
(150051, 'koKR', '호드가 왔으니 집중하라고. 제대로 싸우지 않으면 내 총에 맞을 줄 알아! 위치로!', '', 28153),
(150050, 'koKR', '치열한 전장으로!', '', 28153),
(150049, 'koKR', '불꽃 받아라!', '', 28153),
(150048, 'koKR', '내 몫까지... 싸워 줘...', '', 28153),
(150047, 'koKR', '정신 바짝 차려! 손님 맞이하자고.', '', 28153),
(150046, 'koKR', '간다!', '', 28153),
(150044, 'koKR', '치료 시간.', '', 28153),
(150043, 'koKR', '더 빨리 파라고, 보물은 여기 어딘가에 있을 거야!', '더 빨리 파라고, 보물은 여기 어딘가에 있을 거야!', 28153),
(150041, 'koKR', '으하하! 어떠냐!', '', 28153),
(150040, 'koKR', '칼을 갈아두라고. 처리해야 할 놈들이 있으니까. 가자. 천천히, 은밀하게.', '', 28153),
(150039, 'koKR', '원하는 거라도?', '', 28153),
(150038, 'koKR', '너무 느려!', '', 28153),
(150037, 'koKR', '하... 별것도... 아닌 게...', '', 28153),
(150036, 'koKR', '눈만 깜박해 봐라, 얼라이언스.', '', 28153),
(150035, 'koKR', '', '우리 백성들은 탈란지 공주님이 제안하는 변화를 두려워합니다. 두려움에 빠지면 누구나 어리석은 행동을 하는 법이죠.', 28153),
(150034, 'koKR', '', '전 함포, 발사 준비!', 28153),
(150033, 'koKR', '', '지긋지긋하군. 네놈들이 승리하기 전에 보랄러스를 잿더미로 만들겠다!', 28153),
(150032, 'koKR', '', '감히 내 애완동물을 건드려!?', 28153),
(150031, 'koKR', '', '이놈부터 처리하자.', 28153),
(150030, 'koKR', '', '전부 계획대로야.', 28153),
(150029, 'koKR', '', '내가 모든 경로를 생각해 뒀어. 대담하고, 효율적이고, 계획다운 요소는 다 갖췄지. 이제 집중하라고.', 28153),
(150028, 'koKR', '', '갑옷 괜찮네. 가시만 좀 더 달면 좋을텐데.', 28153),
(150027, 'koKR', '', '이 정도로... 우릴 막을 수 없다...', 28153),
(150026, 'koKR', '', '찌릿!', 28153),
(150025, 'koKR', '', '쿨 티라스를 위하여!', 28153),
(150024, 'koKR', '', '이번 계획은 제대로 짜오지 않은 것 같네?', 28153),
(150023, 'koKR', '다시 일하러 가 볼까?', '', 28153),
(150022, 'koKR', '다 갈아버리겠어!', '', 28153),
(150021, 'koKR', '이봐! 수리는 거저 되는 줄 알아!', '', 28153),
(150020, 'koKR', '', '놈들의 문이 무너졌다! 도시로 들어가 저항하는 자는 모조리 죽여 버려라!', 28153),
(150019, 'koKR', '멍청한 고물 같으니.', '', 28153),
(150018, 'koKR', '하하하! 쨍그랑!', '', 28153),
(150017, 'koKR', '장사 될 만한 게 잔뜩 보이는구나! 경치도 좋고, 보물도 많고... 아, 얼라이언스...? 젠장, 다 틀렸군!', '', 28153),
(150016, 'koKR', '신나는 장사 시간이 돌아왔군! 고물 대신 얼라이언스 놈들을 팔아도 되겠어!', '', 28153),
(150015, 'koKR', '', '내가 직접 보여주지.', 28153),
(150014, 'koKR', '', '하! 마음껏 즐겨라, 어리석은 것들아. 쿨 티란 함대 없이 나를 쓰러뜨릴 수 있을 것 같으냐?', 28153),
(150013, 'koKR', '냄새가 난다, 약탈의 냄새가 나! 어서 가방 챙기자고!', '', 28153),
(150012, 'koKR', '무슨 일이지?', '', 28153),
(150011, 'koKR', '나 아직... 안 끝났다...', '', 28153),
(150010, 'koKR', '', '해내셨군요! 거인이 사라졌으니, 애쉬베인의 병력을 몰아낼 수 있어요.', 28153),
(150009, 'koKR', '얘는 이렇게 쓰라고 만든 거야!', '', 28153),
(150008, 'koKR', '처치 작업 개시!', '', 28153),
(150007, 'koKR', '전장으로!', '', 28153),
(150006, 'koKR', '이런, 내가 좀 심했나.', '', 28153),
(150005, 'koKR', '*하품* 벌써 도착인가? 아, 낮잠 자기 딱 좋은 시간이건만...', '', 28153),
(150004, 'koKR', '싸움을 멈춘다면 이럴 필요도 없을 텐데.', '', 28153),
(150003, 'koKR', '상처를 아물게 해줘야겠군.', '', 28153),
(150002, 'koKR', '안녕하신가!', '', 28153),
(150001, 'koKR', '드디어... 한숨 잘 수 있겠군...', '', 28153),
(150000, 'koKR', '낮잠 시간이다!', '', 28153),
(149999, 'koKR', '*하하* 도망쳐 보라고, 호드 친구들! 안 쫓아갈게!', '', 28153),
(149998, 'koKR', '', '주마등이 스쳐가게 해주마!', 28153),
(149997, 'koKR', '', '새로운 사냥감이 필요하겠군!', 28153),
(149996, 'koKR', '', '아아아... 먹이 냄새가 나는군. 사냥은 해치우기 직전의 추격전이 최고지!', 28153),
(149995, 'koKR', '', '이상한 냄새를 풍기는 자로군.', 28153),
(149994, 'koKR', '', '아... 달콤한... 피 냄새...', 28153),
(149993, 'koKR', '', '기다려라... 다음은 너다!', 28153),
(149992, 'koKR', '', '숨통을 노려라!', 28153),
(149991, 'koKR', '잘했네, 용사여! 자네의 노력으로 이 땅이 더 안전해졌네.', '', 28153),
(149990, 'koKR', '죽어라!', '', 28153),
(149989, 'koKR', '그거면 잔달라의 힘을 보여줄 수 있을 것이다!', '', 28153),
(149988, 'koKR', '겁먹은 것 같구나.', '', 28153),
(149987, 'koKR', '끝났군, 재미있었다!', '', 28153),
(149986, 'koKR', '호드다! 놈들을 해치워라. 사냥을 시작하자! *아우우*', '', 28153),
(149985, 'koKR', '우리 첩자가 이 지역의 위협을 찾아냈네. 찾아서 없애버리게!', '', 28153),
(149984, 'koKR', '*킁킁* *킁킁* 호드 냄새다! 역풍이 불었으면 좋았을 것을...', '', 28153),
(149983, 'koKR', '', '상관없다. 어차피 내 대포가 놈들을 먼지로 만들어 버릴 테니!', 28153),
(149982, 'koKR', '따로 떨어지지 말고 뭉쳐 있어라. 뭔가 불길한 냄새가 나는군.', '', 28153),
(149981, 'koKR', '*으르렁*', '', 28153),
(149980, 'koKR', '늑대를... 길들일 수는... 없지...', '', 28153),
(149979, 'koKR', '놈은 이 일을 후회할 것이다! 디 츄카 레잔!', '', 28153),
(149978, 'koKR', '갈기갈기 찢어버려라!', '', 28153),
(149977, 'koKR', '*아우우* 늑대들이여, 공격하라!', '', 28153),
(149976, 'koKR', '', '좋아! 머리는 내 거다, 하하!', 28153),
(149975, 'koKR', '', '오호, 가능성이 풍부한 섬이로군. 비키게, 부두 주술을 좀 해야겠네.', 28153),
(149974, 'koKR', '', '치료해 주겠네.', 28153),
(149973, 'koKR', '', '오, 머리가 멋지구먼! 자네가 죽으면 내가 가져도 되겠나?', 28153),
(149972, 'koKR', '', '하하, 그래도 검은창은... 죽지 않아...', 28153),
(149971, 'koKR', '', '사술을 받아라!', 28153),
(149970, 'koKR', '', '파멸하라!', 28153),
(149969, 'koKR', '', '거기 너, 머리를 뭉개주마!', 28153),
(149968, 'koKR', '저놈을 처리하죠.', '', 28153),
(149967, 'koKR', '잡았다, 이놈.', '', 28153),
(149966, 'koKR', '멋진 섬입니다. 여기서 오늘 뭘 찾을지 궁금하군요.', '', 28153),
(149965, 'koKR', '무슨 일로?', '', 28153),
(149964, 'koKR', '잠깐만... 누워 있어야지...', '', 28153),
(149963, 'koKR', '낮잠이나 자라!', '', 28153),
(149962, 'koKR', '어디에서 온 놈들이냐? 여기서 뭘 하는 거지?', '', 28153),
(149961, 'koKR', '', '으아아!', 28153),
(149960, 'koKR', '', '피를 내놔!', 28153),
(149959, 'koKR', '', '더! 더 덤벼봐라!', 28153),
(149958, 'koKR', '', '팀... 전술... 하, 그냥 전부 죽여라! 으아아아!', 28153),
(149957, 'koKR', '', '얼라이언스 놈들! 모두 죽여서 심장을 가져와라...', 28153),
(149956, 'koKR', '', '달려들어서 갈기갈기 찢어버려라! 피범벅이 되겠구나! 하하하!', 28153),
(149955, 'koKR', '', '뭡니까?', 28153),
(149954, 'koKR', '', '나는... 전사답게 죽겠다! *퉤*', 28153),
(149953, 'koKR', '', '사지를 찢어라!', 28153),
(149952, 'koKR', '나 보고 싶었어?', '', 28153),
(149951, 'koKR', '얼어붙어라!', '', 28153),
(149950, 'koKR', '음, 음... 안녕하십니까.', '', 28153),
(149949, 'koKR', '훌륭... 했다...', '', 28153),
(149948, 'koKR', '한 놈 더 잡았고! 분명 제가 일등이겠군요.', '', 28153),
(149947, 'koKR', '한번 해 보자고!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149946, 'koKR', '새 얼굴이나 먼저 사야할 것 같은데?', '새 얼굴이나 먼저 사야할 것 같은데?', 28153),
(149945, 'koKR', '', '확신이 부족해 보이는구나, $n.\n\n원한다면 내 계획에 관해 물어 봐도 좋다.', 28153),
(149944, 'koKR', '대족장님, 텔드랏실을 점령해야 하는 이유를 여쭤 봐도 됩니까?', '대족장님, 텔드랏실을 점령해야 하는 이유를 여쭤 봐도 됩니까?', 28153),
(149943, 'koKR', '기회라고요?', '기회라고요?', 28153),
(149942, 'koKR', '확실하지 않습니다, 대족장님.', '확실하지 않습니다, 대족장님.', 28153),
(149940, 'koKR', '', '확실한 건 얼라이언스가 다르나서스를 통해 동부 왕국으로 아제라이트를 유입시킬 거란 사실이다. 안두인 린은 강력한 무기를 새로 만들 테고, 곧 그걸 우리 영토를 공격하는 데 쓸 테지. 놈은 언더시티와 실버문부터 치고, 그다음 칼림도어를 노릴 것이다.\n\n호드의 미래를 위해 우리가 선수를 쳐야 한다.\n\n다르나서스를 점령하면, 아제라이트의 흐름을 통제해 우리에게 불리하게 사용되는 걸 막을 수 있다. 얼라이언스는 민간인을 해칠 수 없단 이유로 제 도시는 감히 건드리지도 못하겠지.\n\n일격만으로도, 수 세대가 평화를 누릴 수 있다.', 28153),
(149939, 'koKR', '', '시간이 촉박하나, 더 알고자 하는 네 마음도 이해한다.\n\n<지도에서 실리더스를 가리키는 실바나스>\n\n이곳으로 인해 아제로스 내 힘의 균형이 영원히 바뀌었다.\n\n아제라이트는 전 세계에서 그 광맥이 발견되고 있다, $n. 아제라이트의 잠재력을 완전히 파악하지는 못했으나, 이 물질이 엄청난 파괴력을 지녔다는 건 확실하다.\n\n20년, 100년 후엔 어떻게 전쟁을 벌일 것 같으냐?\n\n얼라이언스가 아제라이트를 통제하게 되면 호드가 영토를 지킬 수 있을 것 같으냐?', 28153),
(149938, 'koKR', '', '내게 물어볼 게 있나, $n?', 28153),
(149937, 'koKR', '부정한 자들이 근처에 야생 동물들을 가두어 두고 있습니다. 아주 좋은 기회로 보이네요.', '', 28153),
(149936, 'koKR', '호드가 도착한 것 같습니다. 재밌는 일이... 벌어지겠군요.', '', 28153),
(149935, 'koKR', '이런, 날 너무 좋아하는 거 아니야?', '', 28153),
(149934, 'koKR', '자, 마무리 짓자고!', '', 28153),
(149933, 'koKR', '안녕하십니까, 매력적인 친구여.', '', 28153),
(149932, 'koKR', '으윽, 좋은 공격이군... 언젠가... 또 만나자...', '', 28153),
(149931, 'koKR', '하! 또 한 놈 보내고!', '', 28153),
(149930, 'koKR', '이 몸은 준비되셨다!', '', 28153),
(149929, 'koKR', '그래도 이 무기로 우리가 훨씬 유리한 고지를 점할 수 있을 걸세.', '', 28153),
(149928, 'koKR', '내 새로운 날개가 마음에 드나? 빠른 날개가 있으니 그 어떤 미끈고기도 나를 피할 순 없지!$b$b우낏도 마찬가지고.$b$b$b$b더러운 우낏.', '', 28153),
(149927, 'koKR', '잔달라 부족의 미끈고기는 이상하다. 엄청 우끼끼하게 짭짤하고 가끔 말대답도 한다.', '', 28153),
(149926, 'koKR', '호드다! 이제야 힘 좀 쓰겠군. 우선 셔츠부터 좀 벗어야겠어!', '', 28153),
(149925, 'koKR', '쿠아폰이 기쁘게 울면서 음식을 먹어치웁니다.', '', 28153),
(149924, 'koKR', '쿠아폰이 음식 냄새를 맡더니 열심히 집어삼킵니다.', '', 28153),
(149923, 'koKR', '쿠아폰이 공중에서 음식을 가로챕니다.', '', 28153),
(149922, 'koKR', '쿠아폰이 음식을 향해 달려들더니 한 번에 꿀꺽 삼킵니다.', '', 28153),
(149921, 'koKR', '신비로우면서도 신성한 비밀은 많이 있다. 너에게도. 그리고 나에게도.', '', 28153),
(149920, 'koKR', '끼익?', '', 28153),
(149919, 'koKR', '끼이이익!', '', 28153),
(149918, 'koKR', '끽!', '', 28153),
(149917, 'koKR', '끼이익.', '', 28153),
(149916, 'koKR', '날개 달린 호젠이라니, 어떻게 된 거죠?', '날개 달린 호젠이라니, 어떻게 된 거죠?', 28153),
(149915, 'koKR', '작전상 후퇴다!', '', 28153),
(149914, 'koKR', '제가 치료해드리겠습니다!', '', 28153),
(149913, 'koKR', '안녕하십니까. 최고를 보러 오셨습니까?', '', 28153),
(149912, 'koKR', '보급품이라고 할 만한 것이 거의 없지만 몇 가지 챙겨드릴 수 있습니다. 저희를 도와주시면 괜찮은 물건을 조금 드리겠습니다.', '보급품이라고 할 만한 것이 거의 없지만 몇 가지 챙겨드릴 수 있습니다. 저희를 도와주시면 괜찮은 물건을 조금 드리겠습니다.', 28153),
(149911, 'koKR', '<|TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[일반 공룡 먹거리]|h|r를 줍니다>', '<|TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[일반 공룡 먹거리]|h|r를 줍니다>', 28153),
(149910, 'koKR', '여기가 명당이야, 보물은 여기 있을 거야!', '여기가 명당이야, 보물은 여기 있을 거야!', 28153),
(149909, 'koKR', '난... 아직... 끝나지 않았다...', '', 28153),
(149908, 'koKR', '<당신의 손에 먹이가 있는지 살피는 쿠아폰>\n\n끼익? 끼이익.', '', 28153),
(149907, 'koKR', '네 주제를 알아라.', '', 28153),
(149906, 'koKR', '훠이! 더러운 호드 놈!', '', 28153),
(149905, 'koKR', '허를 찔러주지!', '', 28153),
(149904, 'koKR', '더럽고 멍청하고 지성이라고는 찾아볼 수 없는 호드놈들아. 대체 네놈들이 어떻게 이 섬을 찾은 거지? 뭐, 자빠졌는데 꽃밭이었던 거지. 분명해.', '', 28153),
(149903, 'koKR', '돌대가리 호드놈들아, 천천히 말해주마. 섬은... 우리 거다. 너희는... 떠난다. 자, 이제 이해됐지?', '', 28153),
(149902, 'koKR', '미개한 호드놈들! 아제라이트를 얌전히 넘겨주면 항복한 걸로 받아주마. 그 돌대가리로 내 넓은 아량을 이해할지는 모르겠다만.', '', 28153),
(149901, 'koKR', '', '네. 그런데 누구셨죠?', 28153),
(149900, 'koKR', '', '윽! 너희 얼라이언스는 원래 옷차림이 그런 거냐? 수치스러워서 죽기 전에... 떠나는 게 좋을 거다!', 28153),
(149899, 'koKR', '', '얼라이언스. 너희 함선인가? 바다 거인이 공격한 건가, 아니면 원래 저 꼴인 건가?', 28153),
(149898, 'koKR', '여기, 나만 더운 거요? 뭐, 당연하겠지. 나는 뜨거운 남자니까!', '', 28153),
(149897, 'koKR', '통구이가 됐군!', '', 28153),
(149896, 'koKR', '더 불태우자, 더!', '', 28153),
(149895, 'koKR', '불 좀 붙여 볼까!', '', 28153),
(149894, 'koKR', '당신이 협곡을 불태우는 동안 전 위쪽의 대포를 처리하죠. 끝나면 야수 우리에서 만납시다.', '', 28153),
(149893, 'koKR', '', '어휴! 이 못생긴 걸 쳐다보지 않고 죽일 수만 있었더라면!', 28153),
(149892, 'koKR', '그 악취를 갖고 바다로 들어갈지, 내 화염을 뒤집어쓸지 선택해라, 얼라이언스!', '', 28153),
(149891, 'koKR', '어후, 이 냄새는 뭐지? 오, 얼라이언스가 \"최정예\" 병력을 보냈군. 놈들한테 왜 저런 냄새가 나는지 아시오? 치즈를 엄청 먹기 때문이라오.', '', 28153),
(149890, 'koKR', '빛이 당신을 축복하길.', '', 28153),
(149889, 'koKR', '넌 잘 싸웠다. 내가 더 강했을 뿐이지.', '', 28153),
(149888, 'koKR', '물러나야겠군.', '', 28153),
(149887, 'koKR', '빛으로 치유되리라!', '', 28153),
(149886, 'koKR', '아아, 얼라이언스로군! 내가 기분이 좀 좋은데, 당장 떠나주면 더 좋을 것 같군.', '', 28153),
(149885, 'koKR', '이 섬은 우리 것이다, 얼라이언스. 지금 떠난다면 유혈 사태는 일어나지 않을 거다.', '', 28153),
(149884, 'koKR', '적이 온다!', '', 28153),
(149883, 'koKR', '$n|1이;가; 상급 치유를 시전합니다!', '$n|1이;가; 상급 치유를 시전합니다!', 28153),
(149882, 'koKR', '', '찾아내던지, 만들든지 하시오. 시간은 붙잡을 수 없는 귀한 것이니.', 28153),
(149881, 'koKR', '', '그럼 정해졌군. 사울팽, 나타노스. 당장 출발하시오.', 28153),
(149880, 'koKR', '대군주의 눈에 띄고 싶은 밀수업자가 어디 있겠나 싶습니다만은... 한 명쯤은 우릴 돕게 설득해낼 수 있을 겁니다.', '', 28153),
(149879, 'koKR', '내가 그리 순진해 보였나. 눈망루 마을로 오는 모든 화물이 정당한 수단으로 올 가능성은 희박하지. 누군간 악령숲을 통과하는 숨겨진 경로를 이용하고 있겠군.', '', 28153),
(149878, 'koKR', '무슨 말씀이신지?', '', 28153),
(149877, 'koKR', '흐음... 알고 있는 밀수업자가 얼마나 되나, 블라이트콜러?', '', 28153),
(149876, 'koKR', '', '말퓨리온을 양쪽에서 밀어붙일 것이오.', 28153),
(149875, 'koKR', '', '사울팽, 분대와 악령숲으로 가서, 산 너머 어둠해안으로 통하는 길을 찾으시오. 다만, 공성 무기는 내 지휘하에 두시오.', 28153),
(149874, 'koKR', '', '위습은 쉽게 주의가 분산되는 것 같군. 이 약점을 노려서 녀석들을 뚫겠소.', 28153),
(149873, 'koKR', '대족장, 악령숲을 통과하는 안전한 길은 없소.', '', 28153),
(149872, 'koKR', '', '줄다자르는 세계의 분리에서 살아남고 여전히 번성하고 있는 도시 중 하나예요. 전성기에는 잔달라 제국이 이 세계의 반을 지배했었죠. 수라마르에서는 아직도 트롤과 트롤의 어두운 면에 대해 아이들에게 주의를 줘요.\n\n저희는 그들이 피에 굶주린 야만인들이라 생각했거든요. 하지만 이걸 보니... 잔달라 부족과 호드 중 누가 상대를 필요로 하는지 의심스러워지네요.', 28153),
(149871, 'koKR', '', '불페라의 분노가 모래에서 솟아올라 복수를 갈망하고 있어요. 반드시 응징할 겁니다!', 28153),
(149870, 'koKR', '', '사신이 찾아왔다, 부정한 자들아!', 28153),
(149869, 'koKR', '', '조람가르로, 어서!', 28153),
(149868, 'koKR', '예식이 곧 시작됩니다.', '예식이 곧 시작됩니다.', 28153),
(149867, 'koKR', '이런, 당황스럽군.\n\n주례사를 공책에 적어두었는데... 잃어버린 것 같소.\n\n분명 이 방 어딘가에 있을 거요. 찾는 걸 도와준다면 평생 감사함을 잊지 않겠소!', '', 28153),
(149866, 'koKR', '반갑소. 우리가 만난 적은 없는 것 같소만, 내 사랑하는 루실을 위해 와 줘서 고맙소.\n\n도움이 필요하시오?', '', 28153),
(149865, 'koKR', '걱정 마십시오, 바자가 나즈미르에서 당신을 돌봐드리겠습니다!', '', 28153),
(149864, 'koKR', '루실은 잘 모르겠지만 그녀가 하얀숲 예배당을 찾을 때마다 나도 왔었습니다.\n\n이곳에서 벌어진 일로 인한 그녀의 절망으로 내 영혼을 볼 수 없게 되었지만, 그녀도 내가 이곳에 있다는 걸 어느 정도 알아줬으면 좋겠군요.', '', 28153),
(149858, 'koKR', '이제 너도 그들과 함께할 테지. 세스랄리스 님께서 용서하시길.', '', 28153),
(149857, 'koKR', '싸움은 우리 거다!', '싸움은 우리 거다!', 28153),
(149856, 'koKR', '쿠아폰이 물고기를 게걸스럽게 먹습니다.', '', 28153),
(149855, 'koKR', '쿠아폰이 경계하며 먹이로 준 물고기의 냄새를 맡습니다.', '', 28153),
(149854, 'koKR', '<흐린빛지느러미 고기를 줍니다.>', '<흐린빛지느러미 고기를 줍니다.>', 28153),
(149853, 'koKR', '<당신이 다가가자 겁에 질려 멀리 피하는 쿠아폰>$b$b새끼 테러닥스를 달랠 만한 것이 필요합니다. 간식은 어떨까요?', '', 28153),
(149852, 'koKR', '언제나...', '', 28153),
(149851, 'koKR', '나는 항상 여기 있을 거야, 사랑하는 루실...', '', 28153),
(149850, 'koKR', '', '오, 알렉산더... 당신도 지금 함께라면 좋을 텐데...', 28153),
(149849, 'koKR', '친구여, 감사드립니다.', '', 28153),
(149848, 'koKR', '드디어... 이곳에 대한 기억을 두고 떠날 수 있겠습니다.', '', 28153),
(149847, 'koKR', '말은 똑바로 해야지. 우리 백성은 네놈 때문에 죽은 거야.', '', 28153),
(149846, 'koKR', '나는 누구에게도 날 따르라 강요하지 않았다, 보리크... 우리는 정복의 민족이다...', '', 28153),
(149845, 'koKR', '이 순간을... 후회하게 될 거다...', '이 순간을... 후회하게 될 거다...', 28153),
(149844, 'koKR', '웨이크레스트 부인은 강력한 적이다...', '웨이크레스트 부인은 강력한 적이다...', 28153),
(149843, 'koKR', '', '당연히 그래야지!', 28153),
(149842, 'koKR', '걱정 마십시오. 제가 처리하겠습니다.', '걱정 마십시오. 제가 처리하겠습니다.', 28153),
(149841, 'koKR', '', '멍청하긴! 목격자가 있으면 안 돼!', 28153),
(149840, 'koKR', '누군가 찾아온 모양이군요...', '누군가 찾아온 모양이군요...', 28153),
(149839, 'koKR', '언제나처럼 거래하게 되어 기쁩니다, 부인.', '언제나처럼 거래하게 되어 기쁩니다, 부인.', 28153),
(149838, 'koKR', '', '돈은 여기 있다, 무법자여. 누가 보기 전에 어서 가져가라!', 28153),
(149837, 'koKR', '매복이다! 루실, 내 뒤에 숨거라! 경비병, 전투 준비!', '', 28153),
(149836, 'koKR', '', '알렉산더, 안 돼!', 28153),
(149835, 'koKR', '개인적 원한은 없다.', '개인적 원한은 없다.', 28153),
(149834, 'koKR', '알렉산더, 준비는 되었나... 잠깐, 방금 뭐였지!?', '', 28153),
(149833, 'koKR', '드러스트바의 군주로서, 그리고 루실의 자랑스러운 아버지로서, 나는 이 하늘과 땅, 바다가 있는 곳에서 두 사람이 결혼하게 되어 매우 영광이오.', '', 28153),
(149832, 'koKR', '친구와 친지, 귀빈 여러분. 우리는 이 화창한 가을날 루실과 알렉산더가 하나가 되는 것을 축하하기 위해 이 자리에 모였소.', '', 28153),
(149831, 'koKR', '알았다.', '', 28153),
(149830, 'koKR', '', '네, 그렇게 해주세요. 아버지.', 28153),
(149829, 'koKR', '시작할까?', '', 28153),
(149828, 'koKR', '곧 올 게다. 내게 대신 시작하라고 부탁했단다.', '', 28153),
(149827, 'koKR', '', '괜찮아요, 아버지. 어머니는요?', 28153),
(149826, 'koKR', '늦어서 미안하구나.', '', 28153),
(149825, 'koKR', '웨이크레스트 부인은?', '', 28153),
(149824, 'koKR', '', '저기 오신다!', 28153),
(149823, 'koKR', '늦어져서 미안하다는 말도 부탁하오.', '', 28153),
(149822, 'koKR', '행복한 한 쌍에게 곧 간다고 전해주시오.', '', 28153),
(149821, 'koKR', '오, 바로 그거요! 정말 고맙소!', '', 28153),
(149820, 'koKR', '', '시간을 날릴 셈인가요?', 28153),
(149819, 'koKR', '', '지금 책을 찾고 있는데, 책장을 가장 먼저 확인해 봤을 거란 생각은 안 드나요?', 28153),
(149818, 'koKR', '', '왜 남편이 루실의 가방에 공책을 넣어 놓겠어요? 바본가요!?', 28153),
(149817, 'koKR', '주례사를 편지 더미에 둔 기억은 없지만, 확인해 보는 건 나쁘지 않겠지.', '', 28153),
(149816, 'koKR', '도와줘서 고맙긴 하지만, 딸아이의 개인적인 물건까진 뒤적이지 않길 바라오...', '', 28153),
(149815, 'koKR', '', '루실의 사랑은 가문에 아무 도움도 안 돼요...', 28153),
(149814, 'koKR', '루실은 그저 사랑을 따를 뿐이에요, 메레디스. 내가 당신과 결혼했던 것처럼.', '', 28153),
(149813, 'koKR', '', '내 말 들어요, 아서. 허락하면 안 돼요. 우리 딸이 평범한 상인과 결혼하다니요?!', 28153),
(149812, 'koKR', '', '정말 고마워요. 이렇게 와주셔서 영광이에요.', 28153),
(149811, 'koKR', '이곳엔 왜 오셨습니까?', '', 28153),
(149810, 'koKR', '루실? 왔구나... 잠깐, 당신은 루실이 아니군요.', '', 28153),
(149809, 'koKR', '그건 공주도 마찬가지요. 전하께선 이 존재들이 여기 온 걸 불쾌해 하시오. 내게 데려오라고 명령하셨소.', '', 28153),
(149807, 'koKR', '여기서 무슨 일이 일어나든 나의 승리는 확실하다. 자크라제트 장군이 이미 내 열쇠를 가져갔고, 지금쯤이면 네 열쇠도 손에 넣었겠지.', '', 28153),
(149806, 'koKR', '무슨 짓을 한 거냐, 코르테크?', '', 28153),
(149805, 'koKR', '그나저나 보리크... 네가 여기에 있으면 사원 열쇠는 누가 지키고 있는 거지?', '', 28153),
(149804, 'koKR', '', '내가 우리 부족을 지킬 것이다. 네놈은 이 비천한 손에 죽음을 맞게 되리라!', 28153),
(149803, 'koKR', '비천한 불페라는 나의 제국을 섬기도록 해라!', '', 28153),
(149802, 'koKR', '', '', 28153),
(149801, 'koKR', '빠진 이를 금으로 때워야겠군!', '빠진 이를 금으로 때워야겠군!', 28153),
(149800, 'koKR', '미스락스는 영원히 봉인되어 있을 걸세. 그리고 난 백성을 단합시킬 거네.', '', 28153),
(149799, 'koKR', '일은 우리가 다 하니, 골드도 우리가 다 가져야지.', '일은 우리가 다 하니, 골드도 우리가 다 가져야지.', 28153),
(149798, 'koKR', '아니, 넌 실패작이다. 세스랄리스 님은 우리가 평화롭게 살 수 있도록 자신을 희생하셨다.', '', 28153),
(149797, 'koKR', '나는 진정한 세스락의 힘이다!', '', 28153),
(149796, 'koKR', '내 몫을 가지고 장난칠 생각은 하지 않는 게 좋을 걸.', '내 몫을 가지고 장난칠 생각은 하지 않는 게 좋을 걸.', 28153),
(149795, 'koKR', '내가 갑자기 사라지면, 보물을 들고 튄 것으로 알라고!', '내가 갑자기 사라지면, 보물을 들고 튄 것으로 알라고!', 28153),
(149794, 'koKR', '보물을 찾는 사람에게는 지분을 더 얹어주기로 했다고!', '보물을 찾는 사람에게는 지분을 더 얹어주기로 했다고!', 28153),
(149793, 'koKR', '300만 골드 상당의 보물, 우린 부자가 될 거야!', '300만 골드 상당의 보물, 우린 부자가 될 거야!', 28153),
(149792, 'koKR', '파낼 장소를 잘못 골랐나?', '파낼 장소를 잘못 골랐나?', 28153),
(149791, 'koKR', '성을 하나 사고, 고급 욕탕에 하인도 들여야지.', '성을 하나 사고, 고급 욕탕에 하인도 들여야지.', 28153),
(149790, 'koKR', '네들리 말로는 점점 가까워지고 있다더군. 이제 얼마 안 남았대.', '네들리 말로는 점점 가까워지고 있다더군. 이제 얼마 안 남았대.', 28153),
(149789, 'koKR', '그 어떤 함선보다 큰 배를 살 거야!', '그 어떤 함선보다 큰 배를 살 거야!', 28153),
(149788, 'koKR', '300만의 267분의 1이면 얼마야?', '300만의 267분의 1이면 얼마야?', 28153),
(149787, 'koKR', '이 정도면 제이나 프라우드무어가 나랑 결혼하자 하겠군!', '이 정도면 제이나 프라우드무어가 나랑 결혼하자 하겠군!', 28153),
(149786, 'koKR', '', '...가끔은 저런 일도 있지.', 28153),
(149785, 'koKR', '', '난생처음, 날개 아래로 지나는 바람을 느끼게 될 터, 그것이 비행의 즐거움! 그것이...', 28153),
(149784, 'koKR', '', '아, 또 한 아이가 하늘의 부름에 응하는구나!', 28153),
(149783, 'koKR', '금방 돌아오게. 곧바로 코르테크 제왕을 치러 가야 하니 말일세.', '', 28153),
(149782, 'koKR', '자네가 부정한 자들 사이를 교란시키는 동안 나는 여기에 남아 공격을 준비하겠네.', '', 28153),
(149781, 'koKR', '<새끼를 둥지 밖으로 밀어냅니다.>', '<새끼를 둥지 밖으로 밀어냅니다.>', 28153),
(149779, 'koKR', '[클라이언트 장면 - 탤리아가 앞으로 나와 여군주 애쉬베인이 공격의 배후에 있다고 말합니다. 모르시겠습니까, 캐서린 님? 제독님의 자리를 꿰차려는 게 저자의 계획입니다. 캐서린이 프리실라를 돌아봅니다. 사실인가? 프리실라가 부드럽고 호의적인 행동을 거두고 캐서린에게 거칠게 말합니다. 나약한 것! 지도자의 그릇이 아니야! 이 도시를 세운 건 애쉬베인이다! 애쉬베인이 캐서린에게 권총을 쏩니다. 경비병들이 뛰어듭니다. 프리실라가 군중 근처에 있는 수레 위의 통을 쏘자 광장이 순식간에 연막으로 뒤덮힙니다. 광장이 혼란스러워집니다.]', '[클라이언트 장면 - 탤리아가 앞으로 나와 여군주 애쉬베인이 공격의 배후에 있다고 말합니다. 모르시겠습니까, 캐서린 님? 제독님의 자리를 꿰차려는 게 저자의 계획입니다. 캐서린이 프리실라를 돌아봅니다. 사실인가? 프리실라가 부드럽고 호의적인 행동을 거두고 캐서린에게 거칠게 말합니다. 나약한 것! 지도자의 그릇이 아니야! 이 도시를 세운 건 애쉬베인이다! 애쉬베인이 캐서린에게 권총을 쏩니다. 경비병들이 뛰어듭니다. 프리실라가 군중 근처에 있는 수레 위의 통을 쏘자 광장이 순식간에 연막으로 뒤덮힙니다. 광장이 혼란스러워집니다.]', 28153),
(149778, 'koKR', '보리크, 저는 코르테크 제왕에게 맞설 준비가 되었습니다.', '보리크, 저는 코르테크 제왕에게 맞설 준비가 되었습니다.', 28153),
(149777, 'koKR', '', '내 전리품... 안 돼...', 28153),
(149776, 'koKR', '이 배를 벌하고 우리 동족을 해방하라!', '', 28153),
(149775, 'koKR', '', '빛나는 무기가 많구나. 전리품을 더 많이 가져와라!', 28153),
(149774, 'koKR', '위대한 바다의 폭풍이여, 부름에 응하라!', '', 28153),
(149772, 'koKR', '꽤 놀랍군, \"오랜 친구\"여. 하지만 나를 막기엔 부족하다!', '', 28153),
(149771, 'koKR', '열쇠는 내 요새 깊숙한 곳에 있다, 보리크. 설마 열쇠를 직접 들고 다닐 정도로 내가 어리석다고 생각했나?', '', 28153),
(149770, 'koKR', '딱 하나 맞는 말을 했군. 이야기는 이제 끝이다!', '', 28153),
(149769, 'koKR', '이야기는 됐다, 오랜 친구여. 미스락스의 감옥 열쇠를 넘겨라. 우리 모두를 파멸시킬 셈이냐!', '', 28153),
(149768, 'koKR', '영원한 제왕, 코르테크의 힘을 보여주마!', '', 28153),
(149767, 'koKR', '다 됐네. 내가 첨탑의 힘을 이용할 수 있네. 어서 관문으로 가게!', '', 28153),
(149766, 'koKR', '', '와 대박, 정말 반가워요! 도움이 필요하던 참인데요...', 28153),
(149765, 'koKR', '', '키로의 행적을 계속 파악하기란 쉽지 않은 일이에요. 항상 분주하게 돌아다니며 큰 계획을 꾸미고 있죠.\n\n그는 니샤와 함께 떠났는데, 최근에 듣기로는 보급품을 훔친다나 대포를 파괴한다나 하면서 협곡으로 내려간다고 했어요.', 28153),
(149764, 'koKR', '', '니샤가 노예 수용소 주변에서 소동을 일으키고 있어요. 동굴 서쪽으로 나가서 오른쪽에 있는 첫 번째 경사로를 따라가세요.\n\n잘 모르겠다면 세스락이 죽어가는 소리가 나는 곳으로 가시면 돼요. 그 근처에 니샤가 있을 거예요.', 28153),
(149763, 'koKR', '', '오, 좋은 질문이에요! 오는 길에 불페라들이 있는지 눈치도 못 채셨죠?\n\n탈출로 곳곳에 불페라들이 잠입해서 부정한 자들을 지켜보고 있어요!\n\n길이 안전하다고 판단되면 제가 몇몇 불페라를 이끌고 안전한 곳으로 데려다줄 마차로 안내해요.\n\n그런 다음 다시 잠입해서 다른 불페라 무리를 데리고 나올 준비를 하죠. 정말 흥미진진해요. 지금까지 겁에 질려 울었던 건 고작 세 번밖에 없고요!\n\n떠날 일이 있다면 동굴을 나가서 서쪽으로 가세요. 다리를 건너 폐허에 들어가면 당신도 성공할 수 있어요.', 28153),
(149762, 'koKR', '', '당신이랑 똑같은 일인 것 같네요. 여기 이 불페라들을 보세요... 상처를 입고 도움을 필요로 하고 있어요.\n\n부정한 자들이 수많은 우리 동족을 노예로 만들고 자신들을 위해 일하고 싸우도록 했어요.\n\n지금까지는 그걸 막을 수가 없었지만 니샤와 키로가 우리도 저항할 수 있다는 걸 보여줬어요.\n\n밤이 되면 키로와 다른 불페라들이 노예 수용소에 잠입해 가장 약한 불페라부터 구해서 돌아와요.\n\n일단 여기로 데려오면 저는 모래 언덕까지 가는 안전한 길을 확보해요. 그들을 데리고 안전하게 사막을 건널 짐마차가 있는 곳까지요.\n\n위험한 일이에요. 저도 따뜻한 모닥불을 쬐며 아흐나의 노래를 듣는 게 더 좋지만, 친구가 도움이 필요한데 어떻게 외면하겠어요?', 28153),
(149761, 'koKR', '묻고 싶은 것이 있습니다.', '묻고 싶은 것이 있습니다.', 28153),
(149760, 'koKR', '니샤는 어디에 있습니까?', '니샤는 어디에 있습니까?', 28153),
(149759, 'koKR', '키로는 어디에 있습니까?', '키로는 어디에 있습니까?', 28153),
(149758, 'koKR', '어떻게 노예들을 몰래 내보내실 겁니까?', '어떻게 노예들을 몰래 내보내실 겁니까?', 28153),
(149757, 'koKR', '여기서 뭐 하고 계십니까?', '여기서 뭐 하고 계십니까?', 28153),
(149756, 'koKR', '', '$p 님! 오실 줄 알았어요! 친구들에게도 이렇게 이야기했죠. \"$p 님은 불페라를 도와줄 거야. 절대 우릴 버리지 않을 거라고.\"\n\n저도 도우러 왔어요! 키로와 니샤는 불페라 노예들을 구출하는 중이에요. 저는 구출된 노예를 데리고 나갈 마차를 꾸리고 있죠.\n\n세스락 놈들에게 이렇게 가까이 오다니 무섭기는 하지만, 이건 옳은 일이에요. 니샤도 그렇게 말했고요.\n\n그나저나, 저희 소박한 은신처에 오신 것을 환영해요.', 28153),
(149755, 'koKR', '앞장서십시오.', '앞장서십시오.', 28153),
(149754, 'koKR', '만약 거짓이라면 당신의 목을 매달 겁니다.', '만약 거짓이라면 당신의 목을 매달 겁니다.', 28153),
(149753, 'koKR', '함께하겠습니다.', '함께하겠습니다.', 28153),
(149752, 'koKR', '', '우리 병사들이 보급품을 유용하게 사용할 겁니다. 잘하셨습니다!', 28153),
(149751, 'koKR', '', '어떤 거룻배의 잔해를 발견했습니다. 혈트롤 짓이더군요! 혈트롤보다 먼저 그 배의 화물을 확보해야 합니다!', 28153),
(149750, 'koKR', '괜찮은 작전이어야 할 겁니다.', '괜찮은 작전이어야 할 겁니다.', 28153),
(149749, 'koKR', '흐음. 좋습니다. 가시죠.', '흐음. 좋습니다. 가시죠.', 28153),
(149748, 'koKR', '뭐라고요?! 잘못된 정보가 아니기를 바랍니다...', '뭐라고요?! 잘못된 정보가 아니기를 바랍니다...', 28153),
(149747, 'koKR', '그래, 나의 듬직한 종자야. 여기서 할 일은 마친 것 같구나. 그럼 난 이만. 거인을 하나 처치해야 해서 말이다.', '', 28153),
(149746, 'koKR', '좀도둑인가! 두려워 마시오, 여인이여. 이 맥시밀리언이 그대를 보호하리다!', '', 28153),
(149745, 'koKR', '별가루 악마? 제2대 반짝별에게 이런 무례한 언사라니, 더는 못 들어주겠군! 조니의 힘을 느껴볼 준비는 되었는... 혹시 저거 거인?', '', 28153),
(149744, 'koKR', '보아하니 이 별가루 악마와 맞닥뜨렸구나! 혼자서 녀석을 처치하다니 대단하구나! 혹시 그놈에게 부상을 입었느냐?', '', 28153),
(149743, 'koKR', '', '사람들이 캐서린 님에 대한 믿음을 잃고 있어요...', 28153),
(149742, 'koKR', '', '좋아요... 이제 소란을 피워 보죠.', 28153),
(149741, 'koKR', '', '첫 번째, 폭동을 일으켜요.', 28153),
(149740, 'koKR', '됐습니다. 미스락스가 깨어나면 배신자인 당신들은 멸망할 것입니다!', '', 28153),
(149739, 'koKR', '열쇠를 손에 넣고... 미스락스는 깨어날 것이다!', '', 28153),
(149738, 'koKR', '제2대 반짝별아... 왜 날지 않았니...?', '', 28153),
(149737, 'koKR', '시작해야겠군... 여유가 없네. 코르테크의 군대가 이리 오고 있네!', '', 28153),
(149736, 'koKR', '세스락에게서 당신을 보호할 준비가 됐습니다. 조율을 시작하십시오.', '세스락에게서 당신을 보호할 준비가 됐습니다. 조율을 시작하십시오.', 28153),
(149735, 'koKR', '준비됐나? 서둘러야 하네. 코르테크의 군대는 내가 이 첨탑에서 힘을 얻는 걸 막으려 할 걸세. 내가 주문을 시전할 동안 자네가 날 지켜 주게.', '', 28153),
(149730, 'koKR', '이 위습들은 대체 어디서 온 건가?', '', 28153),
(149729, 'koKR', '으윽! 이 망할 위습이 찔러대는군!', '', 28153),
(149726, 'koKR', '덕분에 보랄러스를 위협하는 존재를 제거했습니다만, 장담컨대, 이 도시는 아직 안전하지 않습니다.', '', 28153),
(149725, 'koKR', '저 뒤통수나 치는 겁쟁이와 그 선장들이 사라졌으니, 이 해적 군대는 오합지졸이나 마찬가지입니다.', '', 28153),
(149724, 'koKR', '절 배신하고 이렇게 끝날 줄은 몰랐겠지요.', '', 28153),
(149723, 'koKR', '그래도 녀석들쯤은 문제 없으시죠?', '', 28153),
(149722, 'koKR', '물론 할란을 지키는 무시무시한 살인자 일당은 빼고요.', '', 28153),
(149720, 'koKR', '나는 첨탑으로 가겠네. 거기서 만나지. 코르테크의 군대는 분명 우리가 그들의 힘을 사용하려는 걸 막으려 할 걸세.', '', 28153),
(149719, 'koKR', '아리따운 여인이여, 그대를 괴롭게 하는 것이 무엇이오? 이 북녘골의 맥시밀리언이 도우러 왔소!', '', 28153),
(149717, 'koKR', '', '당신이 아니었다면 라케라 님을 찾지 못했을 겁니다.', 28153),
(149716, 'koKR', '이것은 도움을 구하는 여인의 목소리가 아닌가. 종자여, 서둘러라!', '', 28153),
(149715, 'koKR', '알겠는가, 종자여. 이 거인을 쓰러뜨리기 위한 나의 지난 시도는 수포로 돌아갔으나, 나의 창은 그 옆구리에 단단히 꽂혀 있노라. 그럼, 너에게 첫 번째 명령을 하달하겠...', '', 28153),
(149714, 'koKR', '', '우리, 친구 맞죠?', 28153),
(149713, 'koKR', '', '폐허는 젬란으로 가는 길에 있어요. 데려다 드리게 되어 기뻐요! 돌리와 도트도 좋지만, 대화가 통하는 친구가 있으니 참 좋네요.', 28153),
(149712, 'koKR', '저 거품은... 앗! 바닷물은 안 된다고요? 이상하신 분이네요.', '', 28153),
(149711, 'koKR', '아아, 안 돼! 이럴 순 없어!!!', '', 28153),
(149710, 'koKR', '잠깐... 불페라가 여기서 뭘 하는 거지?', '', 28153),
(149709, 'koKR', '오랫동안 방치되긴 했네만, 거기라면 공격하기에 이상적인--', '', 28153),
(149708, 'koKR', '내 성소는 언덕 위에 숨겨져 있었지. 세스랄리스 님을 위한 작은 제단이자 내가 명상을 하던 곳이었네.', '', 28153),
(149707, 'koKR', '그 당시에 코르테크와 나는 세스락을 이끌고 세스랄리스 님을 모셨네.', '', 28153),
(149706, 'koKR', '가라앉은 욕망과 하나가 되리라!', '가라앉은 욕망과 하나가 되리라!', 28153),
(149705, 'koKR', '나도 한때 여기 살았었네. 아주 오래 전에. 코르테크가 힘과 광기 때문에 우리를 배신하기 전에 말이지.', '', 28153),
(149704, 'koKR', '바위와 먼지로 이루어진 이 사악한 둥지에는 우리의 로아를 저버린 세스락 놈들이 들끓지.', '', 28153),
(149703, 'koKR', '나는 무한의 공허를 삼킨다.', '나는 무한의 공허를 삼킨다.', 28153),
(149702, 'koKR', '이제 모든 것이 보인다.', '이제 모든 것이 보인다.', 28153),
(149701, 'koKR', '우리는 부정한 자들의 제국 한가운데로 가는 걸세, 용사여.', '', 28153),
(149700, 'koKR', '순환의 고리가... 보이는구나!', '그래... 순환의 고리가... 보이는구나!', 28153),
(149699, 'koKR', '오라, 꿈틀대는 어둠이여!', '오... 오라, 꿈틀대는 어둠이여!', 28153),
(149698, 'koKR', '목소리가 들린다, 천 개의 진실이!', '아... 목소리가 들린다, 천 개의 진실이!', 28153),
(149697, 'koKR', '나 심연 속에서 영생하리라.', '나 심연 속에서 영생하리라.', 28153),
(149696, 'koKR', '이제 할란 스위트에게로 가는 길이 열렸으니, 무엇도 우릴 막을 수 없습니다.', '', 28153),
(149695, 'koKR', '내 영혼을 고대의 존재에게!', '내 영혼을 고대의 존재에게!', 28153),
(149694, 'koKR', '', '당신 부족을 우리 부족처럼 지키죠.', 28153),
(149693, 'koKR', '그러니, 당신의 주먹을 활용해 보면 어떨까요?', '', 28153),
(149692, 'koKR', '그 망할 녀석이 난투장의 싸움 대회가 끝날 때까지 섬에 봉쇄령을 내려 놓은 상황입니다.', '', 28153),
(149691, 'koKR', '내 옷깃엔 평온초가 없다, 이 얼라이언스 쓰레기야!', '내 옷깃엔 평온초가 없다, 이 얼라이언스 쓰레기야!', 28153),
(149690, 'koKR', '난 깊은굴 지하철에 대해 아무것도 몰라!', '난 깊은굴 지하철에 대해 아무것도 몰라!', 28153),
(149689, 'koKR', '이제 남은 일은 할란에게 차가운 칼날 맛을 보여주는 겁니다. 물론 쉽지는 않겠지요.', '', 28153),
(149688, 'koKR', '달빛야수는 날지 않아! 꺼져!', '달빛야수는 날지 않아! 꺼져!', 28153),
(149687, 'koKR', '난 첩자가 아니야!', '난 첩자가 아니야!', 28153),
(149686, 'koKR', '\"멀록이 뭘 어쨌다고?\" 제정신이 아니군!', '\"멀록이 뭘 어쨌다고?\" 제정신이 아니군!', 28153),
(149685, 'koKR', '\"트롤의 땀방울 한 병?\" 그런 건 취급 안 해!', '\"트롤의 땀방울 한 병?\" 그런 건 취급 안 해!', 28153),
(149684, 'koKR', '당연히 나무는 아름답고 불은 나쁘지. 뭔 수작이야?', '당연히 나무는 아름답고 불은 나쁘지. 뭔 수작이야?', 28153),
(149683, 'koKR', '잔달라는 영원하리!', '잔달라는 영원하리!', 28153),
(149682, 'koKR', '', '이 사원은 뭔가 이상합니다. 안으로 들어갈 방법을 찾아야 합니다.', 28153),
(149681, 'koKR', '영웅 아니었다면 대단한 해적이 되셨겠군요.', '', 28153),
(149680, 'koKR', '나는... 다시 일어날 것이다...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149679, 'koKR', '정말... 대단하네요, 맥시밀리언. 전 슬슬 가볼게요.', '정말... 대단하네요, 맥시밀리언. 전 슬슬 가볼게요.', 28153),
(149678, 'koKR', '영원한 어둠이... 나를 감싸는구나...', '', 28153),
(149677, 'koKR', '끝이다... 네 희망도... ', '', 28153),
(149676, 'koKR', '어... 뭐라고요?', '어... 뭐라고요?', 28153),
(149675, 'koKR', '씨앗이... 뿌리를 내린다...', '', 28153),
(149674, 'koKR', '소용없다... 나 하나... 사라진들...', '', 28153),
(149673, 'koKR', '순환은... 계속된다...', '', 28153),
(149672, 'koKR', '죽음도... 죽음을... 피하진 못하는구나...', '', 28153),
(149671, 'koKR', '결국에는... 너도 진실을 알게 될 것이다...', '', 28153),
(149670, 'koKR', '들었어요? 댈린의 관문이 무너졌대요!', '들었어요? 댈린의 관문이 무너졌대요!', 28153),
(149669, 'koKR', '이 모든 일을 어떻게 생각하시나요?', '이 모든 일을 어떻게 생각하시나요?', 28153),
(149668, 'koKR', '파도가 너를 심연으로 휩쓸어 가리라.', '', 28153),
(149667, 'koKR', '저는 불편해지는 것 같은데요...', '', 28153),
(149666, 'koKR', '검은이빨 난투꾼은 치고받고 싸우는 걸 좋아합니다. 놈들에게 진짜 주먹 맛을 보여주면 라울 선장이 분명히 당신을 초대할 겁니다.', '', 28153),
(149665, 'koKR', '왜 갑자기 돼지 잡는 소릴 냅니까?', '', 28153),
(149664, 'koKR', '시궁쥐단은 잘 마시는 걸로 유명합니다. 술로 이들과 대적할 수 있다면 유도라 선장이 당신을 초대하지 않곤 못 배길 겁니다.', '', 28153),
(149663, 'koKR', '공격에 대해 들은 이야기가 있습니까?', '공격에 대해 들은 이야기가 있습니까?', 28153),
(149662, 'koKR', '그 누구도 제가 전쟁에 공헌한 바가 없다고 말 못 할 겁니다. 여기 보고서입니다.', '그 누구도 제가 전쟁에 공헌한 바가 없다고 말 못 할 겁니다. 여기 보고서입니다.', 28153),
(149661, 'koKR', '', '알았어요 그럼. 돌리랑 도트가 제일 좋아. 마차를 끌고 모래 언덕을 지나네!', 28153),
(149660, 'koKR', '글쎄요... 날이 갈수록 상황이 안 좋아지기만 하니. 캐서린 님도 내려오실 때가 된 걸지도 모르죠.', '글쎄요... 날이 갈수록 상황이 안 좋아지기만 하니. 캐서린 님도 내려오실 때가 된 걸지도 모르죠.', 28153),
(149659, 'koKR', '얼라이언스를 실망시키지 않겠습니다. 이걸 얻기 위해 진흙 위에 3일 동안 앉아 있어야 하긴 했지만 말입니다. 보고서를 받아주십시오.', '얼라이언스를 실망시키지 않겠습니다. 이걸 얻기 위해 진흙 위에 3일 동안 앉아 있어야 하긴 했지만 말입니다. 보고서를 받아주십시오.', 28153),
(149658, 'koKR', '', '도트와 돌리는 제 노래를 좋아해요. 편안해지나 봐요.', 28153),
(149657, 'koKR', '나이트 엘프와 트롤이 한 핏줄이라고 하는 이들이 있다니, 믿을 수 없습니다. 끔찍한 경험이었습니다. 여기, 보고서입니다.', '나이트 엘프와 트롤이 한 핏줄이라고 하는 이들이 있다니, 믿을 수 없습니다. 끔찍한 경험이었습니다. 여기, 보고서입니다.', 28153),
(149656, 'koKR', '놈들에게 초대를 받는다면 일이 수월해질 겁니다. 아님 그냥 돌진해 들어가 무시무시한 해적 선장 셋을 처치할 수도 있고요. 선택하시죠.', '', 28153),
(149655, 'koKR', '', '돌리랑 도트가 제일 좋아. 마차를 끌고 모래 언덕을 지나네! 이빨은 작아도 먹는 걸 좋아해...', 28153),
(149654, 'koKR', '텔드랏실의 복수를 위해서라면 그 어떤 끔찍한 일이라도 하겠다고 했습니다만, 트롤로 위장하는 게 진짜 끔찍한 일이긴 하더군요. 여기, 보고서입니다.', '텔드랏실의 복수를 위해서라면 그 어떤 끔찍한 일이라도 하겠다고 했습니다만, 트롤로 위장하는 게 진짜 끔찍한 일이긴 하더군요. 여기, 보고서입니다.', 28153),
(149653, 'koKR', '선장들이 모임을 한다는 정보를 입수했습니다. 거기에 참가할 수만 있다면 녀석들의 목을 단번에 칠 수 있겠죠.', '', 28153),
(149652, 'koKR', '제 테러닥스는 어디에 있습니까?', '제 테러닥스는 어디에 있습니까?', 28153),
(149651, 'koKR', '제 새끼에게 무슨 일이 생긴 겁니까?', '제 새끼에게 무슨 일이 생긴 겁니까?', 28153),
(149650, 'koKR', '잠깐 밀림으로 여행 가는 거라고, 쉬울 거라고 해서 온 건데... 퍽이나요. 여기, 보고서입니다.', '잠깐 밀림으로 여행 가는 거라고, 쉬울 거라고 해서 온 건데... 퍽이나요. 여기, 보고서입니다.', 28153),
(149649, 'koKR', '왜 저런 소리를 내는 건가요?', '왜 저런 소리를 내는 건가요?', 28153),
(149648, 'koKR', '야만인들. 완전히 야만인들입니다. 보고서를 받아주십시오.', '야만인들. 완전히 야만인들입니다. 보고서를 받아주십시오.', 28153),
(149647, 'koKR', '어젯밤엔 어디서 잤는지 아십니까? 말도 마십시오. 여기, 보고서입니다.', '어젯밤엔 어디서 잤는지 아십니까? 말도 마십시오. 여기, 보고서입니다.', 28153),
(149646, 'koKR', '고맙습니다.', '고맙습니다.', 28153),
(149645, 'koKR', '큰 그림은 제가 그렸으니, 세세한 실행은 여러분께 맡기겠습니다.', '', 28153),
(149644, 'koKR', '그런 다음, 할란에게 죄값을 받고요.', '', 28153),
(149643, 'koKR', '무한의 피바다를 헤매이거라.', '', 28153),
(149642, 'koKR', '일단, 바다가름은 갈라버리고, 항만의 시궁쥐는 시궁창에 던져넣고, 검은이빨은 뽑고, 무쇠파도는 녹여버리시죠.', '', 28153),
(149641, 'koKR', '그대로 뒀다간, 지역 전체를 위협할 함대를 보유하게 될 겁니다.', '', 28153),
(149640, 'koKR', '울음소리를 들은 것 같은데, 살펴보러 둥지를 떠날 수가 없습니다.$b$b서두르십시오. 그렇지 않으면 돌볼 테러닥스가 남아 있지 않을 겁니다. 모두가 무사히 성체로 자라는 건 아니니까요.', '', 28153),
(149639, 'koKR', '할란 스위트는 무쇠파도 약탈단을 이용해 다른 해적들을 끌어모으고 있습니다.', '', 28153),
(149638, 'koKR', '음, 도망가 버렸군요. 아마 지루했나 봅니다.$b$b다치기 전에 찾아야 할 겁니다. 아직 자립할 준비가 된 녀석은 아니니까요.', '', 28153),
(149637, 'koKR', '그 녀석, 우울해 보이는군요.$b$b분명히 어미가 그리운 걸 겁니다. 아, 그러고 보니 당신이 그 어미군요?', '', 28153),
(149636, 'koKR', '네 영혼은 굶주림에 허덕일 것이다.', '', 28153),
(149635, 'koKR', '별들도 우리의 승천을 두려워하는구나.', '', 28153),
(149634, 'koKR', '저 소리는 분명 배고프다는 신호입니다.$b$b배고파서 손가락이라도 물어대면 문제이니 그 전에 먹이를 주어야 합니다.$b$b먹이가 없다면 전쟁야수 우리에서 얻을 수 있습니다.', '', 28153),
(149633, 'koKR', '궁극의 허무가 너를 감싸리라.', '', 28153),
(149632, 'koKR', '나이알로사에서 영원한 잠에 빠지거라.', '', 28153),
(149631, 'koKR', '끝없는 심연 속에서 빛조차도 죽으리니.', '', 28153),
(149630, 'koKR', '전 날개관리자 고즈아라고 합니다. 파쿠 님이 제 로아시죠. 전 바람의 군주의 후손을 돌보며 그분을 섬깁니다.$b$b파쿠 님께서 당신에게 도움이 필요할 거라고 말씀하시더군요.$b$b<큭큭 웃는 날개관리자 고즈아>$b$b뭘 도와드리면 되겠습니까?', '', 28153),
(149629, 'koKR', '네 종말을 고하는 그림자가 드리운다.', '', 28153),
(149628, 'koKR', '해적들 짓이래요. 믿겨지나요? 못돼먹고 추잡한 해적들 말이에요! 프라우드무어 가문이 우릴 지켜줄 수나 있을까요?', '해적들 짓이래요. 믿겨지나요? 못돼먹고 추잡한 해적들 말이에요! 프라우드무어 가문이 우릴 지켜줄 수나 있을까요?', 28153),
(149627, 'koKR', '오! 나의 듬직한 종자여! 늘 필요할 때 나타나 주는구나.\n\n나는 도움이 필요한 백성들을 구하겠다는 희망을 안고 쿨 티라스에 당도하였다. 지금 할 일은 이 고풍스런 마을의 낚시꾼들을 돕는 것이다. 거인들이 이들을 공포에 몰아넣으려 하고 있다.\n\n거인의 가죽은 비정상적으로 두껍지.', '', 28153),
(149626, 'koKR', '네, 당신 포함 모두 말입니다. 질서를 잘 지켜 소란이 일어나지 않게 하십시오. 그러지 않아도 사람들 모두 짜증이 잔뜩 나 있으니까요.', '네, 당신 포함 모두 말입니다. 질서를 잘 지켜 소란이 일어나지 않게 하십시오. 그러지 않아도 사람들 모두 짜증이 잔뜩 나 있으니까요.', 28153),
(149625, 'koKR', '지금 당장 캐서린 프라우드무어 님과 대화해야 합니다.', '지금 당장 캐서린 프라우드무어 님과 대화해야 합니다.', 28153),
(149624, 'koKR', '프라우드무어 제독님께서 연설을 준비 중이십니다. 침착하게 기다려 주십시오.', '프라우드무어 제독님께서 연설을 준비 중이십니다. 침착하게 기다려 주십시오.', 28153),
(149623, 'koKR', '제독님이 위험합니다. 저희와 함께해주세요!', '제독님이 위험합니다. 저희와 함께해주세요!', 28153),
(149622, 'koKR', '진정하십시오. 모든 상황을 통제하고 있습니다.', '진정하십시오. 모든 상황을 통제하고 있습니다.', 28153),
(149621, 'koKR', '네들리 그리너는 이용당하는 것을 싫어합니다. 그 누구도 저보다 앞서 보물을 찾을 순 없습니다!', '', 28153),
(149620, 'koKR', '제가 조는 모습을 볼 수는 없으실 겁니다.\n\n저를 속이려 들면 그 누구라도 충성주의자에게 팔아넘길 겁니다.', '', 28153),
(149619, 'koKR', '이 파도피는 최근에 오염됐소. 내가 정화할 수 있을 것이오.', '', 28153),
(149618, 'koKR', '으읏! 생각보다 난폭하구려.', '', 28153),
(149617, 'koKR', '허이, 나그네여!\n\n이 북녘골의 맥시밀리언의 종자가 되겠다는 꿈에 부풀어 이 몸의 영웅담을 뒤쫓아 왔는가?\n\n운이 좋은 줄 알아라. 이제 그 꿈을 이룰 수 있으니! 내가 마침 위험한 적들에 맞서 나를 보좌할 종자를 구하고 있던 참이다.', '', 28153),
(149616, 'koKR', '', '죽는 한이 있어도 그분을 찾을 겁니다.', 28153),
(149615, 'koKR', '', '젬란의 항구는 남쪽에 있어요. 수년 동안 배가 드나들지는 않았지만, 키로와 니샤가 세스락 공격을 준비할 때 필요한 걸 얻으려면, 거기가 제일 나을 거예요.', 28153),
(149614, 'koKR', '', '친구를 잘 찾아보세요. 전 운전에 집중할게요.', 28153),
(149613, 'koKR', '', '전투가 끝난 뒤인데... 툴은 죽은 것 같지 않아요. 상처는 심했지만 죽지는 않았어요!', 28153),
(149612, 'koKR', '', '이 사건의 역사를 살펴보면, 후에 군주 아롬이 고라크 툴과 그의 군대를 물리쳤다고 해요. 하지만 여기 보이듯이 고라크 툴이 다치고 힘이 꺾였을 때 모든 피조물이 파괴되었어요. 분명 연관이 있었던 거예요.', 28153),
(149611, 'koKR', '', '저건 아직 대령일 때 최후의 공격을 지휘했던 군주 아롬 웨이크레스트예요. 그리고 저건... 웨이크레스트에게 찔리는 고라크 툴이고요.', 28153),
(149610, 'koKR', '', '이건 드러스트가 아니에요. 쿨 티란이 드러스트 비석에 글을 새기고 있어요.', 28153),
(149609, 'koKR', '', '흥미롭네요. 이 피조물들이 승리를 향한 그의 절박함에서 나온 줄은 몰랐어요.', 28153),
(149608, 'koKR', '주크 요흐 가흘 마 오우 샨다이 누크 일리스 사이즈', '', 28153),
(149607, 'koKR', '프쉬 조프 오그 파알 악쉬', '', 28153),
(149606, 'koKR', '', '잘하셨습니다! 이제 크라그와 님의 자손도 한숨 돌릴 겁니다. 감사합니다.', 28153),
(149605, 'koKR', '쿠아폰이 기쁘게 울면서 음식을 먹어치웁니다.', '', 28153),
(149604, 'koKR', '쿠아폰이 음식 냄새를 맡더니 열심히 집어삼킵니다.', '', 28153),
(149603, 'koKR', '쿠아폰이 음식을 낚아채 날아갑니다.', '', 28153),
(149602, 'koKR', '쿠아폰이 음식을 향해 달려들더니 한입에 꿀꺽 삼킵니다.', '', 28153),
(149601, 'koKR', '', '혈트롤이 크라그와 님의 자손 사냥을 재개했습니다. 개구리 로아의 심장이 분노로 불타오릅니다. 그분의 복수를 도와주십시오!', 28153),
(149600, 'koKR', '스톰송의 이름으로!', '스톰송의 이름으로!', 28153),
(149599, 'koKR', '계곡은 우리 거다, 이 쥐새끼야!', '계곡은 우리 거다, 이 쥐새끼야!', 28153),
(149598, 'koKR', '우리가 없는 쿨 티라스는 아무것도 아니다!', '우리가 없는 쿨 티라스는 아무것도 아니다!', 28153),
(149597, 'koKR', '우리 함대가 널 박살 낼 것이다!', '우리 함대가 널 박살 낼 것이다!', 28153),
(149596, 'koKR', '우리에게 맞서는 자는 파멸하리라!', '우리에게 맞서는 자는 파멸하리라!', 28153),
(149595, 'koKR', '우리는 거친 바다 그 자체다!', '우리는 거친 바다 그 자체다!', 28153),
(149594, 'koKR', '감히 스톰송 가문에 맞서려 하다니!?', '감히 스톰송 가문에 맞서려 하다니!?', 28153),
(149593, 'koKR', '쿨 티라스는 바다의 것이다!', '쿨 티라스는 바다의 것이다!', 28153),
(149592, 'koKR', '내 목숨을... 바다에...', '내 목숨을... 바다에...', 28153),
(149591, 'koKR', '파도현자여... 날 보호하소서...', '파도현자여... 날 보호하소서...', 28153),
(149590, 'koKR', '난 그저... 명령을 따랐을 뿐...', '난 그저... 명령을 따랐을 뿐...', 28153),
(149589, 'koKR', '우린 이미... 승리했다...', '우린 이미... 승리했다...', 28153),
(149588, 'koKR', '내가 죽는다고... 달라질 건 없다...', '내가 죽는다고... 달라질 건 없다...', 28153),
(149587, 'koKR', '우린 결코... 멈추지 않는다...', '우린 결코... 멈추지 않는다...', 28153),
(149586, 'koKR', '이 피는... 파도의 피다...', '이 피는... 파도의 피다...', 28153),
(149585, 'koKR', '난 물속에서... 진실을 봤노라...', '난 물속에서... 진실을 봤노라...', 28153),
(149584, 'koKR', '당신은 이러고 있는 게 얼마나 모욕적인지 모를 겁니다. 여기, 보고서입니다.', '당신은 이러고 있는 게 얼마나 모욕적인지 모를 겁니다. 여기, 보고서입니다.', 28153),
(149583, 'koKR', '', '으, 멍청이들... 적어도 위습이 위험할 수 있단 건 깨달았겠지.', 28153),
(149582, 'koKR', '', '다음에 만나면 도망칠 수 없을 것이다, 말퓨리온!', 28153),
(149581, 'koKR', '더는 가까이 올 수 없다, 밴시 여왕!', '', 28153),
(149580, 'koKR', '<아련한 울음소리를 내며 날개 아래에 머리를 파묻고 쉬는 쿠아폰>', '', 28153),
(149579, 'koKR', '', '찔러 버리겠어!', 28153),
(149577, 'koKR', '놈들이 대가를 치르게 해 주세요, $p님.', '', 28153),
(149575, 'koKR', '', '무엇을 기대했나? 한낱 새끼이거늘! 전쟁야수 우리에 가서 고기를 좀 먹이거라.', 28153),
(149574, 'koKR', '벼락 맞아본 적 있으신 분!', '', 28153),
(149573, 'koKR', '', '들린다. 어린 것들이 엄청난 폐를 가지고 있어.\n\n너는 왜 이렇게 겁먹은 거지?', 28153),
(149571, 'koKR', '<당신을 멍하니 바라봅니다.>', '<당신을 멍하니 바라봅니다.>', 28153),
(149570, 'koKR', '전 할 말 없습니다.', '전 할 말 없습니다.', 28153),
(149569, 'koKR', '금화 좀 주시겠습니까?', '금화 좀 주시겠습니까?', 28153),
(149568, 'koKR', '당신은 웃기게 생긴 트롤이군요.', '당신은 웃기게 생긴 트롤이군요.', 28153),
(149567, 'koKR', '...뭐라고요?', '...뭐라고요?', 28153),
(149566, 'koKR', '당신이 제 시야를 가리고 있군요.', '당신이 제 시야를 가리고 있군요.', 28153),
(149565, 'koKR', '<트림>', '<트림>', 28153),
(149564, 'koKR', '<암호문을 말합니다.>', '<암호문을 말합니다.>', 28153),
(149563, 'koKR', '뭘 원하십니까?', '뭘 원하십니까?', 28153),
(149562, 'koKR', '$r 수프에 비하면, 거북 수프는 요리 축에도 못 낍니다.\n\n작은 거북이들은 놔두시고, 진흙 벌레 고기나 가져다주시지요.\n\n나중에 저를 만나러 오십시오. 그때 다른 수프를 좀 더 연구해보도록 합시다.', '', 28153),
(149561, 'koKR', '거북 수프는 어떨까요?', '거북 수프는 어떨까요?', 28153),
(149560, 'koKR', '세스랄리스 님을 위하여!', '', 28153),
(149559, 'koKR', '부정한 자들이 코르테크 제왕에게 가는 길을 막고 있네. 방어를 뚫어야 하네!', '', 28153),
(149558, 'koKR', '자, 들어봐! 마지가 작업장에서 도와줄 사람을 찾고 있더라고. 부품이 어쩌고 그랬는데... 내 분야가 아니라서 말이야. 무슨 얘긴지 알겠지?', '', 28153),
(149557, 'koKR', '훌륭하오. 이 정보는 우리 전쟁에 큰 도움이 될 거요. 그나저나 이번 암호문을 만든 이가 누군지는 나도 모른다오.', '', 28153),
(149556, 'koKR', '우리 첩자들이 잔달라 수도에 잠입했소. 당신이 그들의 보고서를 가져와 주었으면 하오. 부랑자들과 얘기해 보시오. 우리 첩자라면 비밀 암호문에 답할 거요.', '', 28153),
(149555, 'koKR', '저기, 어, 기지 근처에 인상 더러운 오우거 몇 마리가 나타났잖아. 신사 숙녀 여러분, 무기를 들자고!', '', 28153),
(149554, 'koKR', '여기엔 아쿤다 님만 계십니다. 그분의 사원에는 그분과 이름을 공유하는 사람만을 들일 수 있습니다.', '', 28153),
(149553, 'koKR', '구원을 찾으십니까? 아쿤다 님은 모두를 환영합니다.', '', 28153),
(149552, 'koKR', '', '우린 라케라라는 추방자를 찾고 있습니다. 이 사원에 계실 것 같아서요.', 28153),
(149551, 'koKR', '', '제가 앞장설게요. 금화가 있을지도 모르니까.', 28153),
(149550, 'koKR', '', '처음 상륙했을 때 우리는 평화를 원했지만, 드러스트는 무력을 행사했어요. 극소수만이 새 이웃을 받아들였죠.', 28153),
(149549, 'koKR', '', '잠깐, 이건 초기 쿨 티란 정착지를 묘사하고 있어요. 사라진 마을 중 하나요.', 28153),
(149548, 'koKR', '마오카랑 이야기해보겠습니다.', '마오카랑 이야기해보겠습니다.', 28153),
(149547, 'koKR', '좋아, 다 모였군.', '', 28153),
(149545, 'koKR', '어서 오게나.', '', 28153),
(149544, 'koKR', '', '다시 만났군요, 친구여.', 28153),
(149543, 'koKR', '', '이 세계는 미스락스가 가져올 파괴의 힘을 견딜 수 없다.', 28153),
(149542, 'koKR', '그냥 가게 두시오!', '', 28153),
(149541, 'koKR', '', '사무엘! 안 돼요!', 28153),
(149540, 'koKR', '에딩턴 님을 위하여! 스톰송 계곡을 위하여!', '', 28153),
(149539, 'koKR', '저놈들은 대가를 치르게 될 겁니다.', '', 28153),
(149538, 'koKR', '', '자크라제트에게 걸맞은 최후였습니다.', 28153),
(149537, 'koKR', '우리가 왔소, 깨어난 폭풍을 위하여!', '', 28153),
(149535, 'koKR', '', '함께할 만한 동료들을 불러 모았으니, 가서 내 것을 쟁취해 오도록.', 28153),
(149533, 'koKR', '수도회 탈주자들이 더 있소. 아직 희망이 있는 것 같군.', '', 28153),
(149532, 'koKR', '저들이 있는 걸 보니, 함대가 큰 위험에 빠진 것 같소.', '', 28153),
(149531, 'koKR', '대부분은 우리 마법에 지나치게 빠져들지 않도록 경고하기 위한 전설인 줄로만 알 터인데...', '', 28153),
(149530, 'koKR', '저것들은... 크시르요. 저 파도 아래 가장 깊은 어둠 속에서 온다고 알려졌소.', '', 28153),
(149529, 'koKR', '', '', 28153),
(149528, 'koKR', '대족장님, 제게 부탁할 일이 있으십니까?', '대족장님, 제게 부탁할 일이 있으십니까?', 28153),
(149527, 'koKR', '', '바인, 후퇴하시오!', 28153),
(149526, 'koKR', '', '무선 조종기로 얼-E를 움직일 수 있어요. 땅 속 균열이 보이는 곳으로 얼-E를 보내면 벌레를 낚을 거예요!', 28153),
(149525, 'koKR', '그 속삭임에 저항한다고 해 봤지만, 소용없는 시도가 아니었는지 걱정이 되는구려.', '', 28153),
(149523, 'koKR', '시간이 흐르며 그 속삭임은... 변해버렸소. 때론 갈구하듯, 때론 난폭하게.', '', 28153),
(149522, 'koKR', '우리 수도회는 오랫동안 다른 이에겐 들리지 않는 바다의 속삭임을 들으며 배와 사람들을 인도했소.', '', 28153),
(149521, 'koKR', '이 근처에 폭풍의 사원이 잘 보이는 다리가 있소. 예언은 사원에서 오고 있소.', '', 28153),
(149520, 'koKR', '네놈을 기꺼이 박살 내주마.', '', 28153),
(149519, 'koKR', '', '조심히 다루세요. 그곳에 있는 아무짝에도 쓸모없는 것들과 싸울 생각이 아니라면 말이죠. 만약 그렇게 되면 모조리 불태워 버리세요!', 28153),
(149518, 'koKR', '어리석구나, 죽어라.', '', 28153),
(149517, 'koKR', '이 포로들은 잔달라 소유다!', '', 28153),
(149516, 'koKR', '하하하!', '', 28153),
(149515, 'koKR', '이제 죽어라!', '', 28153),
(149514, 'koKR', '하찮은 얼라이언스.', '', 28153),
(149513, 'koKR', '널 으깨 주마!', '', 28153),
(149512, 'koKR', '심문관을 만나고 싶다고?', '', 28153),
(149511, 'koKR', '신선한 고기다!', '', 28153),
(149510, 'koKR', '안전한... 가요? 제가 위험을 감수하죠!', '안전한... 가요? 제가 위험을 감수하죠!', 28153),
(149509, 'koKR', '여기서 빠져나가게 도와주십시오!', '여기서 빠져나가게 도와주십시오!', 28153),
(149508, 'koKR', '파도어머니시여... 우릴 용서하소서.', '', 28153),
(149507, 'koKR', '딱 맞춰 오셨군요!', '딱 맞춰 오셨군요!', 28153),
(149506, 'koKR', '저건... 굴착기인가요?', '저건... 굴착기인가요?', 28153),
(149505, 'koKR', '지하로 내려가는 것도 무섭지만... 이 트롤들은 더 무섭습니다!', '지하로 내려가는 것도 무섭지만... 이 트롤들은 더 무섭습니다!', 28153),
(149504, 'koKR', '정말 고맙습니다!', '정말 고맙습니다!', 28153),
(149503, 'koKR', '때맞춰 오셨군요!', '때맞춰 오셨군요!', 28153),
(149502, 'koKR', '놈들에게 먹히는 줄 알았습니다!', '놈들에게 먹히는 줄 알았습니다!', 28153),
(149501, 'koKR', '사령관님, 대족장님께서 곧 도착할 병사를 수용할 수 있는 전초기지를 준비하라고 하셨습니다.', '사령관님, 대족장님께서 곧 도착할 병사를 수용할 수 있는 전초기지를 준비하라고 하셨습니다.', 28153),
(149500, 'koKR', '대족장님의 함대가 들어올 공간을 만들어야 합니다. 항구를 정리해 주시겠습니까?', '대족장님의 함대가 들어올 공간을 만들어야 합니다. 항구를 정리해 주시겠습니까?', 28153),
(149499, 'koKR', '대족장님께서 곧 도착할 군대를 위한 식량과 숙소를 필요로 하십니다.', '대족장님께서 곧 도착할 군대를 위한 식량과 숙소를 필요로 하십니다.', 28153),
(149498, 'koKR', '대족장님과 200명의 병사라고 했나? 그분이 도착하실 때를 대비해 전초기지를 준비해 두겠네.', '', 28153),
(149497, 'koKR', '대족장님을 위해서라면 뭐든 해야지. 즉시 항구를 정리할 경비병들을 모으도록 하겠네. 록타르, 친구여.', '', 28153),
(149496, 'koKR', '', '대족장님께서 군대의 숙소와 식량을 필요로 하신다고요? 저희가 가진 걸로 충분할 거예요. 지난봄의 수확도 좋았고 겨울도 따뜻했으니까요.', 28153),
(149495, 'koKR', '자기 병력을 죽이고 있어요...', '', 28153),
(149494, 'koKR', '도와드리죠. 제가 치료법을 압니다.', '', 28153),
(149493, 'koKR', '스톰윈드로 보내 주십시오. (시나리오 돌아가기/다시 시작)', '스톰윈드로 보내 주십시오. (시나리오 돌아가기/다시 시작)', 28153),
(149492, 'koKR', '줄다자르로 가고 싶습니다. (도입부 시나리오를 건너뜁니다.)', '줄다자르로 가고 싶습니다. (도입부 시나리오를 건너뜁니다.)', 28153),
(149491, 'koKR', '', '군단과 얼라이언스 때문에 우리 해군의 배가 너무 많이 파괴되었다. 부두주임이 밤새 작업하고 있지만, 더 많은 배가 필요하다.', 28153),
(149490, 'koKR', '그만.', '', 28153),
(149489, 'koKR', '난 그훈 님의... 대변자다. 그분의 인도를... 받아들여라... 아니면 죽어라.', '', 28153),
(149488, 'koKR', '오너라.', '', 28153),
(149487, 'koKR', '이 로아의 육신은 나와... 그훈 님의 먹잇감이다.', '', 28153),
(149486, 'koKR', '넌... 그훈 님을 막으려... 하겠지만... 실패하고... 고통받을 것이다.', '', 28153),
(149485, 'koKR', '그래... 저항해라... 그훈 님은... 네 고통을... 바라신다.', '', 28153),
(149484, 'koKR', '네 노력은... 부질없다. 날... 막을 순 없다.', '', 28153),
(149483, 'koKR', '소용없다... 날... 이길 수는... 뭐지? 안, 안 돼!', '', 28153),
(149482, 'koKR', '아무... 소용... 없다! 그분은 다른... 육체를... 차지하리라. 봉인이... 깨지면... 그훈 님이... 풀려나신다!', '', 28153),
(149481, 'koKR', '잠시만요... 이게 지하실에서 나온 건가요?', '', 28153),
(149480, 'koKR', '', '행운을 빕니다.', 28153),
(149479, 'koKR', '', '놈들 정찰대가 막 지나갔으니 지금 건너가는 게 좋을 겁니다.', 28153),
(149478, 'koKR', '', '', 28153),
(149477, 'koKR', '', '[PH] 부정한 자들은 어떻게 당한 지도 모를 거예요.', 28153),
(149476, 'koKR', '', '', 28153),
(149475, 'koKR', '당신이 따라가자 어린아이가 웃으며 도망칩니다.', '당신이 따라가자 어린아이가 웃으며 도망칩니다.', 28153),
(149474, 'koKR', '|TInterface\\Icons\\SPELL_NATURE_EARTHQUAKE:20|t%s|1이;가; |cFFFF0000$n|r|1을;를; |cFFFF0000|Hspell:257617|h[지각 변동]|h|r의 대상으로 지정합니다! 흩어지십시오!', '', 28153),
(149473, 'koKR', '테러닥스를 몰아내고 언덕 위를 거점으로 삼으면 유리한 위치를 선점할 거라 생각했는데, 맥도 못 추고 한 명씩 잡혀버리고 있습니다.', '테러닥스를 몰아내고 언덕 위를 거점으로 삼으면 유리한 위치를 선점할 거라 생각했는데, 맥도 못 추고 한 명씩 잡혀버리고 있습니다.', 28153),
(149472, 'koKR', '별 말씀을요.', '', 28153),
(149471, 'koKR', '', '연설을 좋아하는 편은 아니니, 짧게 마치겠습니다. 정말 고마워요. 스톰송 계곡은 언제나 당신의 편에 서겠습니다.', 28153),
(149470, 'koKR', '', '섭섭해 마요, 캘빈.', 28153),
(149469, 'koKR', '', '당신은 우리 농장에서 가시멧돼지를 몰아내고 그들의 소굴까지 소탕하고, 사람들과 농부들을 구출하기까지... 우리 민병대는 절대 하지 못했을, 하지 않았을 일을 해 주셨습니다.', 28153),
(149468, 'koKR', '', '화려한 수사는 생략하겠어요. 자신 있는 종목도 아니어서요.', 28153),
(149466, 'koKR', '잔달라는 전쟁 포로들을 배로 운반하네. 그 꼴을 그냥 둘 수 없지! 검은무쇠의 굴착기를 써서 죽음과 심문에 직면한 포로들을 구하게.', '', 28153),
(149465, 'koKR', '', '이 공격 계획서를 키로에게 전해야 해요. 시간이 없어요. 빨리 가죠!', 28153),
(149464, 'koKR', '', '맞아요. 그들은 아롬 웨이크레스트가 승리하자 그를 군주로 추앙했어요.', 28153),
(149463, 'koKR', '', '흠, 우리가 명령을 따르면 이 괴물들은 아롬의 격전지로 가지 못할 거예요. 도웁시다.', 28153),
(149462, 'koKR', '', '우리가 자기 병사인 줄 아는군요...', 28153),
(149461, 'koKR', '', '피의 제물 의식을 막아야 합니다! 그것이 혈신을 저지하는 첫 걸음입니다.', 28153),
(149460, 'koKR', '', '줄나즈만의 불경한 의식이 이 땅에 타락을 퍼뜨려 죽은 자들의 영혼을 불러내고 있습니다! 그들의 유해를 정화하고 영혼들에게 안식을 선사해야 합니다!', 28153),
(149459, 'koKR', '혈신... 이시여...!', '혈신... 이시여...!', 28153),
(149458, 'koKR', '아툴아만에서 만나세. 그곳에서 다른 이들이 우릴 기다리고 있네!', '', 28153),
(149457, 'koKR', '그분께서 부르신다...', '그분께서 부르신다...', 28153),
(149456, 'koKR', '와이번 기수 몇 명이 곤경에 처한 것 같아. 전장에서 생존자를 찾아달라고!', '', 28153),
(149455, 'koKR', '저리 가!', '저리 가!', 28153),
(149454, 'koKR', '안 돼, 안 돼, 안 돼!', '안 돼, 안 돼, 안 돼!', 28153),
(149453, 'koKR', '내 머리에서 꺼져!', '내 머리에서 꺼져!', 28153),
(149452, 'koKR', '으악!', '으악!', 28153),
(149451, 'koKR', '그만!', '그만!', 28153),
(149450, 'koKR', '부정한 자들이 평화에 만족할 수 있다면 좋으련만. 저희는 항상 그랬는데 말이죠.\n\n하지만 놈들의 끊임없는 공격에 결국 저희도 대항할 수밖에 없었습니다.\n\n제왕 코르테크를 쓰러뜨릴 겁니다... 그리고 그 과정에서 쓸 만한 건 모두 챙길 작정입니다.', '', 28153),
(149449, 'koKR', '', '|TInterface\\Icons\\SPELL_MAGE_FLAMEORB:20|t탄약통에 불이 붙지 않게 빨리 치우십시오! %s|1이;가; 탄약통을 터트리는 것을 막아야 합니다.', 28153),
(149448, 'koKR', '선봉대여! 웨이크레스트 대령님을 지원할 준비를 해라!', '선봉대여! 아롬 대령님을 지원할 준비를 해라!', 28153),
(149447, 'koKR', '드러스트바와 쿨 티라스를 위하여!', '드러스트바와 쿨 티라스를 위하여!', 28153),
(149446, 'koKR', '놈들이 우리 아이들을 데려갔다! 대가를 치르게 하자!', '놈들이 우리 아이들을 데려갔다! 대가를 치르게 하자!', 28153),
(149445, 'koKR', '선조들을 드높일 때다!', '선조들을 드높일 때다!', 28153),
(149444, 'koKR', '놈들을 밀어붙였다! 이대로 계속 가라!', '놈들을 밀어붙였다! 이대로 계속 가라!', 28153),
(149443, 'koKR', '굳건히 버텨라!', '굳건히 버텨라!', 28153),
(149442, 'koKR', '적을 몰아냈다!\n\n멍하니 있지 말고 들어가 싸워라!', '적을 몰아냈다!\n\n멍하니 있지 말고 들어가 싸워라!', 28153),
(149441, 'koKR', '%s|1이;가; 불길한 구름에 다가가자 구름이 타오르기 시작합니다!', '%s|1이;가; 불길한 구름에 다가가자 구름이 타오르기 시작합니다!', 28153),
(149440, 'koKR', '고맙네...', '고맙네...', 28153),
(149439, 'koKR', '드디어... 안식을 취할 수 있겠군...', '드디어... 안식을 취할 수 있겠군...', 28153),
(149438, 'koKR', '내 감시는 끝났네...', '내 감시는 끝났네...', 28153),
(149437, 'koKR', '다시... 잠들 수 있겠군...', '다시... 잠들 수 있겠군...', 28153),
(149436, 'koKR', '내 임무는 끝났네...', '내 임무는 끝났네...', 28153),
(149435, 'koKR', '고기를 구해 오겠습니다.', '고기를 구해 오겠습니다.', 28153),
(149434, 'koKR', '이 상자는 제 겁니다. $r들은 제법 간섭하기를 좋아하는군요.\n\n진흙 벌레 수프를 만들 진흙 벌레가 좀 필요합니다만, 그 벌레들은 숨어있습니다! 저는 인내심이 강하므로 여기서 며칠 더 기다릴 수 있습니다. 상자를 더 찾을지도 모르지요.\n\n당신이 진흙 벌레 고기를 좀 가져다주시면 이 상자와 거래하도록 하겠습니다.', '안 됩니다! 이 상자는 제 겁니다!\n\n저는 수프에 쓸 벌레를 잡으러 여기에 왔습니다. 게살로 만드는 수프가 환상적이라는 토르톨란도 더러 있지만 저는 그런 친구들과는 어울리지 않습니다. 고작 게살 수프를 먹겠다고 애써 낯선 사람이랑 친구가 될 필요는 없습니다.\n\n진흙 벌레 수프는 평생을 가는 우정을 만든다고 하지요. 참고로, 우리 토르톨란은 굉장히 장수하는 편입니다.\n\n진흙 벌레 고기를 좀 찾아다 주시면 이 상자를 넘기는 것도 생각해보도록 하겠습니다.', 28153),
(149433, 'koKR', '저 상자인가요?', '저 상자인가요?', 28153),
(149432, 'koKR', '전 이곳에 제법 오래 서 있었습니다. 그러다가 진흙 속에서 이 재미나 보이는 상자를 찾았지요.', '전 이곳에 제법 오래 서 있었습니다. 그러다가 진흙 속에서 이 재미나 보이는 상자를 찾았지요.', 28153),
(149431, 'koKR', '잘했네. 나는... 토르톨란 짐마차 마냥 천천히 미쳐갔고 영혼은 천천히 시들어가고 있었네.', '잘했네. 나는... 미쳐갔고, 내 영혼은 토르톨란 짐마차처럼 천천히 시들어가고 있었네.', 28153),
(149430, 'koKR', '고맙네, 이방인이여.', '고맙네, 이방인이여.', 28153),
(149429, 'koKR', '마침내 끝이로군. 고맙네.', '마침내 끝이로군. 고맙네.', 28153),
(149428, 'koKR', '편히 잠들겠군. 고맙네, 나그네여.', '편히 잠들겠군. 고맙네, 나그네여.', 28153),
(149427, 'koKR', '이제 끝이구나...', '이제 끝이구나...', 28153),
(149426, 'koKR', '계획이 있습니까?', '계획이 있습니까?', 28153),
(149425, 'koKR', '', '전기 충격이나 불을 쓸까 생각했는데, 그냥 날려버리는 것도 괜찮을 것 같네요!\n\n그런데 토르톨란을 해치면 불행이 따른다고 하잖아요. 이제 불행이라면 좀 사양하고 싶은데.\n\n그러니까 당신이 저 토르톨란을 어떻게 처리하면 좋을지 좀 보여주실래요?', 28153),
(149424, 'koKR', '', '$p 님, 문제가 생겼어요. 토르톨란이 상자를 하나 찾았는데 그걸 손에 넣어야 해요!', 28153),
(149423, 'koKR', '망할 늪지! 이 습도 때문에 모든 게 허물어지고 있습니다.\n\n자, 필요한 게 있다면 어서 말씀하십시오. 그래야 저도 보수 작업을 진행하니까요.', '망할 늪지! 이 습도 때문에 모든 게 허물어지고 있습니다.\n\n자, 필요한 게 있다면 어서 말씀하십시오. 그래야 저도 보수 작업을 진행하니까요.', 28153),
(149422, 'koKR', '', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149421, 'koKR', '아마니를 자신의 영역에 들이는 게 현명하다고 생각하는 건 자만에 빠진 자들뿐이지. 오늘 잘해주었네, 용사여.', '', 28153),
(149420, 'koKR', '아마니는 죽어 있을 때만 선한 족속일 뿐이지. 하지만 잔달라가 아마니에게 도시에 거처를 마련해 주었네. 그들의 추종자들을 물리치게! 얼라이언스를 위하여!', '', 28153),
(149419, 'koKR', '괴물이 죽었습니다! 애쉬베인 님, 상층부를 확보하십시오! 이 도둑은 제가 처리하겠습니다...', '괴물이 죽었습니다! 애쉬베인 님, 상층부를 확보하십시오! 이 도둑은 제가 처리하겠습니다...', 28153),
(149418, 'koKR', '내가 여길 지키는 한, 요새가 함락되게 두진 않을 것이오!', '', 28153),
(149417, 'koKR', '놈들의 분수를 일깨워 줬군.', '', 28153),
(149416, 'koKR', '<사령관 켈람에게 노랫돌을 보여줍니다.>', '<사령관 켈람에게 노랫돌을 보여줍니다.>', 28153),
(149415, 'koKR', '아마니 부족은 줄다자르에서 호드의 영향력이 꽤 된다는 걸 명심해야 해. 기억을 되살려주는 게 어떻겠나? 놈들에게 따끔한 맛을 보여 주게.', '', 28153),
(149414, 'koKR', '먼저 가서 농부들을 찾아보겠습니다. 절대 붙잡히시면 안 됩니다!', '', 28153),
(149413, 'koKR', '', '타즈딩고!', 28153),
(149411, 'koKR', '진흙 속에 엄청난 양의 보물이 묻혀 있습니다. 당신과 목시가 힘을 합쳐 찾아내십시오!', '', 28153),
(149410, 'koKR', '안 돼! 크로그에게... 해방은 없다...', '', 28153),
(149409, 'koKR', '전장을 향하여!', '전장을 향하여!', 28153),
(149408, 'koKR', '호드를 위하여!', '호드를 위하여!', 28153),
(149407, 'koKR', '우리는 함께 싸울 걸세.', '우리는 함께 싸울 걸세.', 28153),
(149406, 'koKR', '자네와 함께 싸우겠네.', '자네와 함께 싸우겠네.', 28153),
(149405, 'koKR', '신세를 졌군, $n|1이여;여;.', '신세를 졌군, $n|1이여;여;.', 28153),
(149404, 'koKR', '의식은 아직 끝나지 않았다. 반드시 크로그를 제압해야 해!', '', 28153),
(149403, 'koKR', '집중 공격을 부탁드립니다. 전 제가 알아서 하겠습니다.', '', 28153),
(149402, 'koKR', '', '내 힘이... 이건 대체...?', 28153),
(149401, 'koKR', '', '내 몸이... 움직이지... 으으윽!', 28153),
(149400, 'koKR', '알겠습니다.', '알겠습니다.', 28153),
(149399, 'koKR', '', '진흙 속에서 목소리가 들린다는 일꾼들이 있어요. 그것 때문에 결국 정신이 나가버린 사람들도 있고요!\n\n저는 그냥 안 들어요!', 28153),
(149398, 'koKR', '', '어떤 쿨 티란 사람들은 저를 어떤 도굴꾼이랑 엮으려고 하는데, 저는 전혀 모르는 일이에요!', 28153),
(149397, 'koKR', '', '나... 미지의 바다로... 가리...', 28153),
(149396, 'koKR', '', '아니, 무슨 노움 처음 보는 것처럼 하잖아요!', 28153),
(149395, 'koKR', '', '지긋지긋하구나!', 28153),
(149394, 'koKR', '', '학살의 시간이다... 발사!', 28153),
(149393, 'koKR', '', '탄환을 먹여 주마!', 28153),
(149392, 'koKR', '', '널 산산조각 내 주마!', 28153),
(149391, 'koKR', '', '모두 피해!', 28153),
(149390, 'koKR', '잔달라는... 헛된 약속뿐이군.', '잔달라는... 헛된 약속뿐이군.', 28153),
(149389, 'koKR', '넌 내 로아께서 이에 관해 뭐라고 하실지 듣게 될 거다.', '넌 내 로아께서 이에 관해 뭐라고 하실지 듣게 될 거다.', 28153),
(149388, 'koKR', '이제 우리에게 안전한 곳은 없다.', '이제 우리에게 안전한 곳은 없다.', 28153),
(149387, 'koKR', '그들의 도시에서... 우리가 죽게 두는구나.', '그들의 도시에서... 우리가 죽게 두는구나.', 28153),
(149386, 'koKR', '이제 우리는 어떻게 되는가?', '이제 우리는 어떻게 되는가?', 28153),
(149385, 'koKR', '제국은... 진정으로 무너졌다.', '제국은... 진정으로 무너졌다.', 28153),
(149384, 'koKR', '어떻게 이런... 일이 일어나게 두다니?', '어떻게 이런... 일이 일어나게 두다니?', 28153),
(149383, 'koKR', '잔달라가... 우리 안전을 약속했는데...', '잔달라가... 우리 안전을 약속했는데...', 28153),
(149382, 'koKR', '마침내! 브원삼디 님께 바칠 제 공물을 누군가 찾았군요. 잘 쓰십시오!', '마침내! 브원삼디 님께 바칠 제 공물을 누군가 찾았군요. 잘 쓰십시오!', 28153),
(149381, 'koKR', '', '놈들의 엄지를 가져와라! 나머지는 너희들 마음대로 하고.', 28153),
(149380, 'koKR', '', '당신이 죽으면 당신 몫은 제가 가질게요!', 28153),
(149379, 'koKR', '', '네 머리는 내 수집품에 잘 어울리겠군.', 28153),
(149378, 'koKR', '', '이제 우리 사이를 친한 친구라고 할 수 있겠네요. 저 돈 좀 빌려주실래요?', 28153),
(149377, 'koKR', '', '톨 다고르에서 당신을 꼭 닮은 사람을 봤어요.', 28153),
(149376, 'koKR', '큰 실수하는 거다!', '큰 실수하는 거다!', 28153),
(149375, 'koKR', '도와줘! 놈들이 뜰을 공격한다!', '도와줘! 놈들이 뜰을 공격한다!', 28153),
(149374, 'koKR', '저들을 잡아라!', '저들을 잡아라!', 28153),
(149373, 'koKR', '여긴 네가 있을 곳이 아니다!', '여긴 네가 있을 곳이 아니다!', 28153),
(149372, 'koKR', '사라져라! 잔달라는 트롤의 것이다!', '사라져라! 잔달라는 트롤의 것이다!', 28153),
(149371, 'koKR', '부정한 냄새가 나는 걸 알고 있었지...', '부정한 냄새가 나는 걸 알고 있었지...', 28153),
(149370, 'koKR', '도와주십시오! 공격당하고 있습니다!', '도와주십시오! 공격당하고 있습니다!', 28153),
(149369, 'koKR', '더러운 잡종!', '더러운 잡종!', 28153),
(149368, 'koKR', '코다가 끽끽거리며 골짜기를 바라봅니다.', '', 28153),
(149367, 'koKR', '', '나도 걱정이야, 코다.', 28153),
(149366, 'koKR', '동부경비 초소로 가는 탈것이 필요합니다.', '동부경비 초소로 가는 탈것이 필요합니다.', 28153),
(149365, 'koKR', '', '어디로 가시겠어요?', 28153),
(149364, 'koKR', '', '감사해요! 포다를 많이 많이 안아주세요!', 28153),
(149363, 'koKR', '', '전 대포... 발사!', 28153),
(149362, 'koKR', '선착장이 너희의 새로운 보금자리다.', '', 28153),
(149361, 'koKR', '선착장에서 스톰송 군주님을 섬기게 될 것이다.', '', 28153),
(149360, 'koKR', '다들 마차에 올라타라.', '', 28153),
(149359, 'koKR', '혈트롤들이 또 내 후손들을 위협하는구나!$B$B이리 오거라, 크라그와의 화를 불러오는 자들에게 어떤 일이 벌어지는지 우리 함께 보여주자!', '', 28153),
(149358, 'koKR', '', '이 도시는 우리 것이다!', 28153),
(149357, 'koKR', '', '네놈을 돛 위에 걸어 두마!', 28153),
(149356, 'koKR', '', '내 손에 죽은 놈이 하나 더 늘었군.', 28153),
(149355, 'koKR', '', '전원... 공격!', 28153),
(149354, 'koKR', '', '모조리 없애라!', 28153),
(149353, 'koKR', '기다림의 시간도 얼마 남지 않았다.', '', 28153),
(149352, 'koKR', '얼마나 급하죠?', '얼마나 급하죠?', 28153),
(149351, 'koKR', '무쇠파도는 우릴 매일 습격하는 데다, 이쪽으로 진군 중인 호드 병력도 있습니다. 이대론 곧 마을을 통째로 들고 달아나야 할 판입니다.', '', 28153),
(149348, 'koKR', '너희의 피로... 의식을 완성할 것이다!', '', 28153),
(149347, 'koKR', '잘 알겠습니다.', '잘 알겠습니다.', 28153),
(149346, 'koKR', '실패라고? 틀렸다...', '', 28153),
(149345, 'koKR', '저 진창 바닥에 어떤 왕국의 재산이 골드로 묻혀 있습니다. 2차 대전쟁에서 가라앉은 보물선이죠!\n\n마을 사람들 모두가 보물을 먼저 찾아내려고 힘을 모으고 있습니다만, 시간이 많지는 않습니다. 서둘러야 합니다!', '', 28153),
(149344, 'koKR', '리스 쿨 쇼스 우쉬... 이즈시 워브쉬 크바스크.', '', 28153),
(149343, 'koKR', '', '끝났다, 자크라제트. 네 계획은 실패했다!', 28153),
(149341, 'koKR', '너는 수면에서 허우적대지만... 그분께서는 저 아래에서 기다리신다.', '', 28153),
(149340, 'koKR', '', '네놈의 짓거리도 여기까지다!', 28153),
(149339, 'koKR', '때맞춰 잘 왔군...', '', 28153),
(149338, 'koKR', '', '와! 다들 집으로 도망쳤어요!', 28153),
(149337, 'koKR', '피의 의식이 거의 끝났다!', '', 28153),
(149336, 'koKR', '', '빨리 찾아주세요! 가족을 잃으면 코다가 정말 슬퍼할 거예요.', 28153),
(149335, 'koKR', '무슨 보물이요?', '무슨 보물이요?', 28153),
(149334, 'koKR', '이 무쇠파도 녀석들이 우릴 전부 노예로 끌고 가려고 합니다. 우리가 먼저 보물을 찾지 못하게 하려는 겁니다!', '', 28153),
(149333, 'koKR', '', '이리 와, 얘들아! 우리가 도와줄게!', 28153),
(149332, 'koKR', '', '저기 들어가면 우리도 벌에게 마구 쏘일 거야!', 28153),
(149331, 'koKR', '', '친구들이 안 보여, 코다!', 28153),
(149330, 'koKR', '자익스 랄 스크오스 글 자익스 랄 울위', '', 28153),
(149329, 'koKR', '이 무쇠파도 녀석들이 사람들을 노예로 잡아가려고 합니다. 도와주십시오!', '', 28153),
(149328, 'koKR', '저들은 구원이요, 진실이다.', '', 28153),
(149327, 'koKR', '즈쿠 우가 누크 일리스 자 오우 가할라하스 아나그', '', 28153),
(149326, 'koKR', '어둠의 심연에 빠지게 될 것이다.', '', 28153),
(149325, 'koKR', '', '폭발하지 않으면 다시 시도해봐요.', 28153),
(149323, 'koKR', '그건 어렵겠군요. 당신을 대족장님께 돌려보내라는 지시를 받았습니다.', '', 28153),
(149322, 'koKR', '', '이건 내 배이니, 그 계획을 수정하셔야 할 것 같습니다만.', 28153),
(149321, 'koKR', '가면서 이야기하죠, 공주님.', '', 28153),
(149320, 'koKR', '', '서두르십시오. 줄다자르로 갈 겁니다.', 28153),
(149319, 'koKR', '\"고맙다\"는 말을 하고 싶으신 거라고 믿겠습니다.', '', 28153),
(149318, 'koKR', '지금이야말로 너의 그 마법... 기술을 쓰면... 딱일 것 같은데, 안 그런가?', '', 28153),
(149317, 'koKR', '', '이건... 말도 안 돼.', 28153),
(149315, 'koKR', '넌 높은 확률로 우리를 진압하겠지.', '', 28153),
(149314, 'koKR', '도시가 불타는 게 보이지 않나.', '', 28153),
(149313, 'koKR', '성급하게 굴지 말자고.', '', 28153),
(149312, 'koKR', '', '그렇다면 죽어라.', 28153),
(149311, 'koKR', '실례지만, 우리가 탈 배가 있어서 말이지.', '', 28153),
(149310, 'koKR', '', '항복해라. 그러면 너희가 있어야 할 지하감옥으로 보내 주겠다. 거기서 왕의 심판을 기다리도록.', 28153),
(149309, 'koKR', '잠깐.', '', 28153),
(149307, 'koKR', '이미 방법을 써 놨네. 보기나 하게.', '', 28153),
(149306, 'koKR', '멍청한 표정 그만 짓고, 얼음을 부수게!', '', 28153),
(149305, 'koKR', '레잔을 잘 모르네만, 그에게 빚을 진 것 같구먼.', '', 28153),
(149303, 'koKR', '', '죽어라, 호드 쓰레기들!', 28153),
(149302, 'koKR', '', '탈출로가 막혔어요!', 28153),
(149300, 'koKR', '', '저런 새 스무 마리만 있었으면 좋겠군요.', 28153),
(149299, 'koKR', '아하! 라산, 이 영리한 친구!', '', 28153),
(149298, 'koKR', '그렇군... 하지만 이유는 알 것 같네. 보게나.', '', 28153),
(149297, 'koKR', '아, 로아께서 자넬 도우셨군, 줄.', '', 28153),
(149296, 'koKR', '', '지금까지 죄 없는 이들을 많이도 죽였더군. 네놈들 탈옥 소동은 이제 끝이다.', 28153),
(149295, 'koKR', '', '우릴 쫓아오지 않네요.', 28153),
(149294, 'koKR', '하하하하!', '', 28153),
(149292, 'koKR', '', '놈들 군대가 로데론에서 돌아온 게 분명해요. 어떻게 돌파하죠?', 28153),
(149291, 'koKR', '이동해라!', '', 28153),
(149290, 'koKR', '', '로아께서 듣고 계십니다. 위대한 레잔이시여, 힘을 빌려주십시오!', 28153),
(149289, 'koKR', '', '더는 이 도시의 영혼을 해칠 수 없을 거다!', 28153),
(149288, 'koKR', '', '거기까지다!', 28153),
(149287, 'koKR', '조심하도록 하게. 저 유능한 얼라이언스 외교관이 이번에는 포로를 남겨두지 않을 모양일세.', '', 28153),
(149286, 'koKR', '으웩!', '', 28153),
(149285, 'koKR', '', '우리 엄마를 찾아 주셨네요! 무서운 괴물들에게서 엄마를 구해 주셔서 정말 감사해요!', 28153),
(149284, 'koKR', '', '제 장난감을 갖다 주셔서 감사해요. 우리 엄마를 보시면 집으로 돌아오시라고 전해 주실래요?\n\n엄마를 못 본지 좀 오래됐어요.', 28153),
(149283, 'koKR', '지금이다. 마지막 봉인을 조각내라.', '', 28153),
(149282, 'koKR', '', '탈란지, 넌 용사님과 함께 줄을 쫓아. 난 최대한 많은 병력을 집결시켜서 그 종결자를 저지해볼게. 그놈을 거꾸러뜨리려면 군대라도 동원해야겠어.', 28153),
(149281, 'koKR', '그가 미스락스에게 명령을 내린다. 검은 제국의 하수인을 반드시 막아야 한다.', '', 28153),
(149280, 'koKR', '', '용사님, 미스락스는 로아와 제가 최대한 막아 보겠습니다. 당신은 제 아버지를 찾아 줄을 끝장내 주십시오!', 28153),
(149279, 'koKR', '오너라, 미스락스. 오너라, 나의 종결자여. 마지막 봉인을 풀어야 하느니.', '', 28153),
(149278, 'koKR', '이제 안전하다, 아이들아. 어서 가라. 미스락스가 오고 있다.', '', 28153),
(149277, 'koKR', '', '잔달라의 형제자매들이여, 우리의 도시를 되찾자! 모두, 전진하라!', 28153),
(149276, 'koKR', '', '용사님, 조칼로에 아직 남은 주민들을 찾아 저희에게 보내주십시오. 저희도 곧 따라가겠습니다.', 28153),
(149275, 'koKR', '', '심각해. 로아들께서 도와주고 계시지만 우리도 싸울 여력이 있는 트롤들을 최대한 집결시켜야 해.', 28153),
(149274, 'koKR', '', '엄중한 시기엔 위대한 활약이 필요한 법. 상황은?', 28153),
(149273, 'koKR', '', '아, 탈란지, 전투에 로아를 모셔 왔구나.', 28153),
(149272, 'koKR', '', '라케라, 내 병사들을 지휘하고 있구나.', 28153),
(149271, 'koKR', '', '대형을 갖춰라! 전쟁활 준비!', 28153),
(149270, 'koKR', '', '이런... 이거... 귀찮게 됐군.', 28153),
(149269, 'koKR', '', '이 용사분에 따르면 종결자 미스락스가 깨어났다고 합니다.', 28153),
(149268, 'koKR', '', '세스락 공격의 배후에는 무언가가 있다. 놈들이 이렇게 몰려드는 건 처음이야.', 28153),
(149267, 'koKR', '', '조심하세요, 아버지. 이건 우리가 알지 못하는 적이 오랫동안 세운 계획이에요.', 28153),
(149266, 'koKR', '탈란지, 호드 용사와 함께 병력을 집결시키거라. 나는 크라그와 님과 함께 조각의 길을 지키겠다.', '', 28153),
(149265, 'koKR', '', '라스타칸! 볼둔의 뱀들이 네 도시의 서쪽을 포위하고 있다. 무슨 수를 써보아라.', 28153),
(149264, 'koKR', '놈들이 너무 많이 통과했다. 다자알로로 가는 다리로 가라. 거기에 놈들을 몰아넣자.', '', 28153),
(149263, 'koKR', '브원삼디 님을 위한 선물이다.', '', 28153),
(149262, 'koKR', '죽어라, 침입자들아!', '', 28153),
(149261, 'koKR', '적이 너무 많군.', '', 28153),
(149260, 'koKR', '놈들이 피의 관문에 몰려들고 있다. 서둘러라. 적들이 도시에 도착하기 전에 최대한 없애야 한다.', '', 28153),
(149259, 'koKR', '', '폭풍을... 막을 순... 없다...', 28153),
(149258, 'koKR', '', '넌 부정한 제국을 막을 수 없다!', 28153),
(149257, 'koKR', '나가는 길을 찾아보겠습니다. 조심하십시오!', '', 28153),
(149256, 'koKR', '고맙습니다... 이젠 끝장인 줄 알았습니다.', '', 28153),
(149255, 'koKR', '그거면 될 겁니다. 도시 전체를 혼자서 약탈한 기분이 어떻습니까?', '', 28153),
(149254, 'koKR', '도망치십시오... 어서!!!', '', 28153),
(149253, 'koKR', '너무 빨리 왔군. 이자가 주인님의 영예를 얻으려면 시간이 더 필요하거늘!', '', 28153),
(149252, 'koKR', '오, 안 돼! 도시가 소란스럽습니다! 여기를 벗어나야겠습니다.', '', 28153),
(149250, 'koKR', '제가 당신 주머니에 넣어 둔 단검을 써보십시오. 마음에 드실 걸요.', '', 28153),
(149249, 'koKR', '먼저 가십시오. 안전한 목표를 표시하면 제가 쓰러뜨리죠.', '', 28153),
(149248, 'koKR', '신뢰란 한 번 깨지면 회복할 수 없는 법. 이번 공격은 잔달라 부족에게 큰 피해를 줄 거요. 잘했소, 용사여.', '', 28153),
(149247, 'koKR', '하급 트롤 부족의 대표들이 잔달라 부족의 보호 아래 회동을 갖소만, 그 방어는 취약한 상황이오. 전령들을 없애고 적들 사이에 불화의 씨앗을 심으시오.', '', 28153),
(149246, 'koKR', '마차를 불태우고 뼈를 부러뜨려라!', '마차를 불태우고 뼈를 부러뜨려라!', 28153),
(149245, 'koKR', '이 벌레들이 열쇠를 숨겨도 우리는 찾아낼 것이다!', '이 벌레들이 열쇠를 숨겨도 우리는 찾아낼 것이다!', 28153),
(149244, 'koKR', '강한 녀석들은 죽이지 마라. 시장에서 잘 팔릴 거다.', '강한 녀석들은 죽이지 마라. 시장에서 잘 팔릴 거다.', 28153),
(149243, 'koKR', '끝난 겁니까? 제발 끝났다고 해주십시오!', '', 28153),
(149242, 'koKR', '돌아오지 못해!', '돌아오지 못해!', 28153),
(149241, 'koKR', '', '북서쪽의 마루로 가야 해요. 아롬의 격전지라면 우리의 신호가 잘 보일 거예요.', 28153),
(149240, 'koKR', '', '하지만 그 전에, 이 상황을 기회 삼아 저들의 군대를 쓸어버리시죠.', 28153),
(149239, 'koKR', '', '북서쪽 고지에서 탈출 신호를 보낼 수 있어요.', 28153),
(149238, 'koKR', '미친 짓입니다! 속도 좀 줄여요!', '', 28153),
(149237, 'koKR', '하하하! 지축을 울리는 발구르기라, 재밌구먼!', '', 28153),
(149236, 'koKR', '', '서약단의 무기로 도리어 놈들을 짓밟으니 만족감이 남다르네요.', 28153),
(149235, 'koKR', '이 불은 보라색 연기를 냅니다. 곧 나무 위로 연기가 보일 겁니다.', '', 28153),
(149234, 'koKR', '우선, 동료들에게 공격 신호를 보내겠습니다.', '', 28153),
(149233, 'koKR', '아니. 때가 되면, 제 발로 걸어 들어올 거다.', '', 28153),
(149232, 'koKR', '', '놈들을 쫓아갈까요?', 28153),
(149231, 'koKR', '외부인과의 조약도... 로아와의 거래도 끝이다. 이제 피의 시대가 도래했다... 그훈 님의 시대가 열렸다!', '', 28153),
(149230, 'koKR', '지금은 그리 배가 고프지 않군. 나중에 와라...', '', 28153),
(149229, 'koKR', '모두 계획대로 진행되고 있다고 하면 믿으시겠습니까? 그럼 그렇죠...', '', 28153),
(149228, 'koKR', '좋은 소식입니다! 적들의 위치를 알아냈습니다. 사방에 있다고 보시면 됩니다.', '', 28153),
(149227, 'koKR', '부디 시장님께는 비밀로... 해주시겠습니까?', '', 28153),
(149226, 'koKR', '그다지 자랑스러운 순간은 아니군요.', '', 28153),
(149225, 'koKR', '예언 하나 해 주마. 처음에 그랬듯, 마지막에는 트롤 제국이 세계를 지배할 것이다. 그리고 그 왕좌에 왕이 앉겠지만, 너와 나는 그 모습을 살아서 보지 못 하리라. 이것은 나의 신이 내게 보여 주신 것이다...', '', 28153),
(149224, 'koKR', '너는 고인 물이 되고 말았어. 우리 제국이 썩어가는 데도 그저 지켜만 봤지. 하지만 나는, 트롤 제국의 재건을 예견했다.', '', 28153),
(149223, 'koKR', '탈란지의 말을 들었어야지.', '', 28153),
(149221, 'koKR', '안 돼! 하부투!', '', 28153),
(149220, 'koKR', '하하하! 멋지구먼!', '', 28153),
(149219, 'koKR', '피의 시간이 다가온다.', '', 28153),
(149218, 'koKR', '로아의 시대는... 끝났다.', '', 28153),
(149217, 'koKR', '나는 네 신하가 아니다.', '', 28153),
(149216, 'koKR', '레잔, 레잔...', '', 28153),
(149215, 'koKR', '입 조심해라, 배신자.', '', 28153),
(149214, 'koKR', '아, 도착했군. 이제는 호칭이... 흠...', '', 28153),
(149212, 'koKR', '', '당신의 예견이 맞길 바라도록 하죠.', 28153),
(149211, 'koKR', '이 이단자!', '', 28153),
(149210, 'koKR', '', '상대의 다음 움직임을 예측해라!', 28153),
(149209, 'koKR', '', '바람처럼 때리고! 피해라!', 28153),
(149208, 'koKR', '', '훈련을 완료하기 전까진 쉴 수 없다!', 28153),
(149207, 'koKR', '', '상대에 집중해! 목표한 곳을 공격해라!', 28153),
(149206, 'koKR', '사령관님! 이분께서 갑자기... 쓰러... 졌어?!', '사령관님! 이분께서 갑자기... 쓰러... 졌어?!', 28153),
(149205, 'koKR', '자매여, 괜찮으십니까? 그렇게 세게 공격할 생각은 없었습니다!', '자매여, 괜찮으십니까? 그렇게 세게 공격할 생각은 없었습니다!', 28153),
(149204, 'koKR', '이럴 수가, 이게 무슨... 괜찮으십니까?!', '이럴 수가, 이게 무슨... 괜찮으십니까?!', 28153),
(149200, 'koKR', '얼라이언스 사령관을 없애는 것만큼 기분 좋은 일은 없습니다. 게다가 이렇게 쉽게...', '', 28153),
(149199, 'koKR', '', '당신에게 순풍이 불기를.', 28153),
(149198, 'koKR', '', '잿불단이 다시 한 번 고라크 툴에 맞섰습니다. 동료들과 함께라면, 우리는 무너지지 않을 테죠.', 28153),
(149197, 'koKR', '', '도와주셔서 감사해요. 루실 영애께 모든 임무에 성공했다고 보고할게요.', 28153),
(149196, 'koKR', '자네와 심문관이 나서지 않았으면 어찌 되었을지, 생각만 해도 떨린다네.', '', 28153),
(149195, 'koKR', '살아남아 다행입니다.', '', 28153),
(149194, 'koKR', '', '이제 안전하게 숲을 날 수 있어요. 그리핀 기수들이 빨리 오기를.', 28153),
(149193, 'koKR', '', '그리핀 기수들이 신호를 기다리고 있어요.', 28153),
(149192, 'koKR', '너무 허술해요! 다음엔 더 조용히 하십시오!', '', 28153),
(149191, 'koKR', '이런! 조용하고 신속하게 공격해야 합니다. 집중 좀 하십시오!', '', 28153),
(149190, 'koKR', '다른 이들이 눈치채기 전에 이 자를 빨리 처치하십시오!', '', 28153),
(149189, 'koKR', '발각되지 않게 조심하십시오! 눈에 띄면 안 됩니다...', '', 28153),
(149187, 'koKR', '아아, 아닙니다. 제가 상대하겠습니다.', '', 28153),
(149186, 'koKR', '못 본 걸로 하겠습니다. 자고 있는 녀석을 해치운 적이 없는 것도 아니고요.', '', 28153),
(149185, 'koKR', '잠깐, 민간인을 죽이면 경비병의 시선을 끌 수도 있으니 조심하십시오.', '', 28153),
(149184, 'koKR', '경비병은 아니었지만, 당신이 얼라이언스를 죽이는 걸 막을 마음은 없습니다.', '', 28153),
(149183, 'koKR', '원칙적으로 민간인을 죽일 필요는 없지만, 그 방식은 마음에 듭니다.', '', 28153),
(149182, 'koKR', '아주 냉정하신 분이군요... 좋습니다.', '', 28153),
(149181, 'koKR', '우리 기술자 하나가 예비 부품을 찾다가 광산 근처에서 얼라이언스 얼간이들을 봤다고 하잖아? 작업장에 마지가 있으니까 직접 물어보고... 나갈 준비를 해야지?', '', 28153),
(149180, 'koKR', '가슴이... 숨을 못 쉬겠어!', '가슴이... 숨을 못 쉬겠어!', 28153),
(149179, 'koKR', '목이... 막혀!', '목이... 막혀!', 28153),
(149178, 'koKR', '몸이 좋지 않은걸...', '몸이 좋지 않은걸...', 28153),
(149177, 'koKR', '좀... 쉬어야겠어...', '좀... 쉬어야겠어...', 28153),
(149176, 'koKR', '모든 게 너무... 어두워...', '모든 게 너무... 어두워...', 28153),
(149175, 'koKR', '기분이... 이상해.', '기분이... 이상해.', 28153),
(149174, 'koKR', '안 돼! 안 돼에에에!', '', 28153),
(149173, 'koKR', '뭐, 뭐야?!', '', 28153),
(149172, 'koKR', '너흰 뭐냐! 꼼짝 마라!', '', 28153),
(149171, 'koKR', '', '저들은 죽음을 원하는 것 같군요... 저들의 피가 그훈에게 힘을 보태지 않길 바랄 뿐입니다.', 28153),
(149170, 'koKR', '', '저들은 계속 브원삼디 님께 저항하지만 끝이 좋지는 않을 겁니다. 용사님, 브원삼디 님과 우리의 맹약은 유효합니다. 이 어긋난 영혼들을 그분께 보내주십시오!', 28153),
(149169, 'koKR', '자, 잠깐. 제 반대쪽 다리였군요. 미안합니다.', '', 28153),
(149168, 'koKR', '다리에 뭔가 닿았어요!', '', 28153),
(149167, 'koKR', '왕노다지차는 멀쩡하구나. 와서 자기 몫을 챙기라고!', '', 28153),
(149166, 'koKR', '우리 광부들이 대박을 터뜨린 모양이군! 수레를 무사히 기지로 가져다 줘. 큰 도움이 될 거라고.', '', 28153),
(149165, 'koKR', '', '가시죠. 제가 지켜봐 드릴게요!', 28153),
(149164, 'koKR', '', '폭탄을 쓸 때 적당히라는 건 없어요!', 28153),
(149163, 'koKR', '', '혹시, 아는 사람 중에 돈은 엄청 많으면서 경비는 느슨하게 세워두는 쿨 티라스 귀족 없나요?', 28153),
(149162, 'koKR', '', '당신처럼 똑똑한 사람을 찾고 있었어요, $p 님. 제가 새로운 사업을 시작하려는데 골드를 시원하게 투자해주실 분이 필요하거든요.', 28153),
(149161, 'koKR', '', '이런 쿨 티란들 주위에서, 노움은 뒤통수를 조심해야 하죠.', 28153),
(149160, 'koKR', '', '의심이 간다 싶으면, 일단 날리고 보세요.', 28153),
(149159, 'koKR', '', '톨 바라드, 톨 다고르, 스톰윈드 지하감옥까지, 모두 이 눈으로 봤다고요!', 28153),
(149158, 'koKR', '신호를 보내십시오. 여기서 나갑시다!', '신호를 보내십시오. 여기서 나갑시다!', 28153),
(149157, 'koKR', '', '라케라 님, 제발 이러지 마세요! 그러다 죽으실지도 몰라요!', 28153),
(149156, 'koKR', '', '무사하셨군요, 사막이여 감사합니다!', 28153),
(149155, 'koKR', '', '여기까지다! 누구도 아티나 님을 방해할 수 없다!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149154, 'koKR', '이 조그만 놈들은 위험하지 않을 것 같군, $r.', '', 28153),
(149151, 'koKR', '', '$p 님, 살아계셨네요! 저처럼 운이 좋으시군요.', 28153),
(149150, 'koKR', '우리 또 보세.', '', 28153),
(149149, 'koKR', '가는 건가?', '', 28153),
(149148, 'koKR', '조심히 가게.', '', 28153),
(149147, 'koKR', '걱정 말게, 친구여.', '', 28153),
(149146, 'koKR', '부두술이 필요한가?', '', 28153),
(149145, 'koKR', '뭐가 필요한가?', '', 28153),
(149144, 'koKR', '', '제가 살아있는 한 혈트롤이 다시는 계략을 꾸미지 못할 겁니다.', 28153),
(149143, 'koKR', '', '혈트롤이 우리 쪽에 잠입하려 합니다. 놈들을 감지하고 볼 수 있는 물건이 제게 있습니다. 그걸 이용해 처치하십시오!', 28153),
(149142, 'koKR', '숨을 고르게. 배에 도착하기 전까지는 멈추지 않을 테니.', '', 28153),
(149141, 'koKR', '전 도망갑니다! 도망간다고요!', '전 도망갑니다! 도망간다고요!', 28153),
(149140, 'koKR', '줄이 우리 모두를 죽일 겁니다.', '줄이 우리 모두를 죽일 겁니다.', 28153),
(149139, 'koKR', '이제 끝이군요!', '이제 끝이군요!', 28153),
(149138, 'koKR', '사업에 지장이 큽니다.', '사업에 지장이 큽니다.', 28153),
(149137, 'koKR', '전 여길 벗어날 겁니다.', '전 여길 벗어날 겁니다.', 28153),
(149136, 'koKR', '뭐야! 무슨 소란이냐?!', '', 28153),
(149135, 'koKR', '경비병! 경비병, 도와줘요! 으아악!!', '', 28153),
(149134, 'koKR', '아야! 이런, 깡패 같은!', '', 28153),
(149133, 'koKR', '걱정 말고 한 방 날려보세요!', '', 28153),
(149132, 'koKR', '어서, 날 때려요!', '', 28153),
(149131, 'koKR', '때려주세요.', '', 28153),
(149130, 'koKR', '잘 들어요.', '', 28153),
(149129, 'koKR', '세 번째 기록: 거의 다 됐다! 벌들이 성장하고 있고, 생산성도 기하급수적으로 증가하고 있다. 다만 한 가지, 여왕에게서는 눈을 떼지 말아야겠다.', '', 28153),
(149128, 'koKR', '두 번째 기록: 살아 움직이는 벌꿀술이 공격성을 띠기 시작했다. 아무래도 살짝 계산 착오가 있었던 것 같다.', '', 28153),
(149127, 'koKR', '첫 번째 기록: 벌꿀이 살아나긴 했는데, 복제 속도가 생각했던 것과는 비교도 할 수 없을 정도로 빠르다. 시험을 더 진행해야겠다!', '', 28153),
(149126, 'koKR', '불을 꺼! 불길을 잡아라!', '', 28153),
(149125, 'koKR', '다리 사이로 꼬리를 말고 도망치는 꼴 좀 보게!', '', 28153),
(149124, 'koKR', '쥐새끼처럼 도망쳐봐라!', '', 28153),
(149123, 'koKR', '', '어리석은 행동이다. 너흰 여기서 죽는다. 남는 건 이름 없는 무덤뿐일 거다.', 28153),
(149122, 'koKR', '', '내가 아는 호드는 잔인하고 무자비한 자들이다. 인정사정 없이 승리를 쟁취하고자 하지. 하지만 이건...', 28153),
(149121, 'koKR', '국왕, 놈들을 찾았네! 놈들의 가죽을 전리품으로 가져가지!', '', 28153),
(149120, 'koKR', '하아, 우릴 만나서 별로란 듯이 굴지 말게.', '', 28153),
(149119, 'koKR', '정말 기쁘군. 진심이야. 이제 움직이세. 준비하게.', '', 28153),
(149118, 'koKR', '', '참 잔인하시오, 줄.', 28153),
(149117, 'koKR', '', '맞설 때가 아니에요. 가요!', 28153),
(149116, 'koKR', '', '이번엔 또 뭐요?', 28153),
(149115, 'koKR', '음, 여기는 아주 난장판이로군.', '', 28153),
(149114, 'koKR', '', '항구예요! 앞으로 계속 가야 해요!', 28153),
(149113, 'koKR', '돌로 된 도시는 불에 잘 타지 않을 거란 편견이 있죠.', '', 28153),
(149112, 'koKR', '우릴 포위하려 하는군. 그렇게 당할 순 없네!', '', 28153),
(149111, 'koKR', '여기서 기다려야합니다.', '', 28153),
(149110, 'koKR', '용수로로 돌아가야 하네. 서두르게!', '', 28153),
(149109, 'koKR', '아아, 이것 참 쓸만하겠군.', '', 28153),
(149108, 'koKR', '', '숨을 곳을 찾아야 해요!', 28153),
(149107, 'koKR', '', '조심하십시오!', 28153),
(149106, 'koKR', '으, 늙은 늑대가 냄새를 맡았네. 여길 벗어나야 해!', '', 28153),
(149105, 'koKR', '', '너무 많아요... 방벽이 버티지 못할 거예요!', 28153),
(149104, 'koKR', '저기 있다! 놈들이 문에 도달하기 전에 막아야 한다!', '저기 있다! 놈들이 문에 도달하기 전에 막아야 한다!', 28153),
(149103, 'koKR', '따돌린 줄 알았나? 어림없는 소리!', '따돌린 줄 알았나? 어림없는 소리!', 28153),
(149102, 'koKR', '저 아래다! 자원을 차지하자!', '저 아래다! 자원을 차지하자!', 28153),
(149101, 'koKR', '', '혈트롤은 역겹고 뒤틀린 생물입니다. 그들이 변할 일은 절대 없습니다.', 28153),
(149100, 'koKR', '', '혈트롤이 제 백성을 학살하고 있습니다! 놈들을 막으십시오!', 28153),
(149099, 'koKR', '살해부리가 소동에 관심을 보입니다!', '살해부리가 소동에 관심을 보입니다!', 28153),
(149098, 'koKR', '칼부리가 물속의 미끼 냄새에 홀렸습니다!', '칼부리가 물속의 미끼 냄새에 홀렸습니다!', 28153),
(149097, 'koKR', '감사합니다, 친구여! 문이 이렇게 닫혀 있을 줄은 몰랐군요.', '', 28153),
(149096, 'koKR', '오셨군요! 저 좀 도와주시겠습니까?', '', 28153),
(149095, 'koKR', '빨리 움직여 줘서 고맙습니다. 영애님과 합류하도록 하죠.', '', 28153),
(149094, 'koKR', '', '좀 도와주겠어요?', 28153),
(149093, 'koKR', '도와줘서 고맙소.', '', 28153),
(149092, 'koKR', '망할 마녀들과 보호막 같으니!', '', 28153),
(149091, 'koKR', '', '어린 야수들은 잘 자라고 있습니다. 언젠가 훌륭한 전쟁야수가 되겠죠.', 28153),
(149090, 'koKR', '', '어린 전쟁야수들은 꾸준한 관심과 애정이 필요합니다. 그들이 우리와 교감하는 법을 배워야 하는 것처럼, 우리도 그들과 교감하는 법을 배워야 합니다.', 28153),
(149089, 'koKR', '소환되는 소리가 들린다!', '', 28153),
(149088, 'koKR', '무기는 모두 잃었지만 목숨은 구했습니다.', '', 28153),
(149087, 'koKR', '정찰 중 방심한 틈에 잡혀 버렸습니다. 다신 방심하지 않겠습니다.', '', 28153),
(149086, 'koKR', '돌아가서 혈트롤에게 복수할 겁니다!', '', 28153),
(149085, 'koKR', '감사합니다. 저는 줄잔으로 돌아가겠습니다.', '', 28153),
(149084, 'koKR', '', '감사합니다. 저 고블린들, 돈 벌 궁리 그만하고 제 도시를 구하는 데 집중하는 게 좋을 겁니다!', 28153),
(149083, 'koKR', '', '고블린 발굴조사단원 한 무리가 언데드에게 잡혔습니다. 풀어줘야 합니다!', 28153),
(149082, 'koKR', '이 타르의 용도를 알아? 나도 몰라. 하지만 엄청 비싸게 팔리는 거래!', '', 28153),
(149081, 'koKR', '여긴 구덩이네, 진짜로! 여기서 나가야겠어.', '', 28153),
(149080, 'koKR', '좋아, 막 나가려고 했어. 이 타르는 엄청 인기 좋을 거야!', '', 28153),
(149079, 'koKR', '아슬아슬했어! 그건 그렇고, 타르 좀 가져올래? 고향에 가져가서 팔면 엄청 비싸게 팔 수 있다고.', '', 28153),
(149078, 'koKR', '고마워, 금지된 늪지에서 타르 좀 가져오는 게 위험할 줄 누가 알았겠어?', '', 28153),
(149076, 'koKR', '코르테크가 도를 넘었네. 이 일은 개인적으로 처리해야겠네. 내가 없는 동안 자네가 열쇠를 지켜주게.', '', 28153),
(149075, 'koKR', '', '이걸로 혈트롤들도 자기들의 시간이 끝나간다는 걸 알 겁니다.', 28153),
(149074, 'koKR', '', '고블린 분대에겐 혈트롤을 상대할 계획이 있습니다. 저들이 살아서 나올 수 있게 당신이 도와주십시오.', 28153),
(149073, 'koKR', '완멋날죽포에 올라타서 혈트롤 군대를 막읍시다!', '완멋날죽포에 올라타서 혈트롤 군대를 막읍시다!', 28153),
(149072, 'koKR', '그래요! 끔찍한 혈트롤들이 줄다자르로 가고 있어요. 다행히 완멋죽포를 좀 업그레이드했지요!\n\n완멋날죽포 좀 보실래요? 날아다닐 수 있어요! 죽음이 날아드는 거죠!\n\n물론, 방어막은 포기해야 해요. 그걸 장착하곤 날 순 없거든요.\n\n한 번 시험해보실래요? 적들을 가루로 만들어버릴 거예요!', '', 28153),
(149071, 'koKR', '네놈도 쓸모없기는... 다른 놈들과 마찬가지다...', '', 28153),
(149070, 'koKR', '이 추방자도 죽이면 되는 건가? 운수가 아주 좋은 날이군.', '', 28153),
(149066, 'koKR', '가거라, 작은 왕아. 너를 추적하려는 자는 내가 모두 집어삼킬 것이다.', '', 28153),
(149065, 'koKR', '아무것도 아닌 건 아니죠.', '', 28153),
(149064, 'koKR', '', '줄이 괜찮지 않습니까. 아무것도 아니겠죠.', 28153),
(149063, 'koKR', '멀리 가지 못했을 것이다. 경계를 늦추면 안 된다.', '', 28153),
(149062, 'koKR', '호드 침입자들이 지하감옥에 침투했습니다. 침입자들을 처리할 때까지 집 안에서 대기해 주시기 바랍니다!', '', 28153),
(149061, 'koKR', '왕의 명령입니다!', '', 28153),
(149060, 'koKR', '누군가 멍청한 짓만 하지 않으면 들키지 않을 걸세.', '', 28153),
(149059, 'koKR', '하하! 걱정 말거라, 앙켈. 일보 후퇴일 뿐이야! 금방 다시 예전으로 돌아갈 거란다.', '하하! 걱정 말거라, 앙켈. 일보 후퇴일 뿐이야! 금방 다시 예전으로 돌아갈 거란다.', 28153),
(149058, 'koKR', '도, 도대체 무슨 말 하시는 거예요!? 목숨도 겨우 건지고, 농장도 완전히 망쳐 버리시고는!', '', 28153),
(149057, 'koKR', '어떤 희생이 있더라도, 벌꿀 생산 기술을 발전시키는 건 우리의 몫이란다!', '어떤 희생이 있더라도, 벌꿀 생산 기술을 발전시키는 건 우리의 몫이란다!', 28153),
(149056, 'koKR', '없어도 잘 되지 않았습니까.', '', 28153),
(149055, 'koKR', '당장.', '', 28153),
(149054, 'koKR', '엇?', '', 28153),
(149053, 'koKR', '', '걱정 마십시오. 위험한 일은 피할 작자이니.', 28153),
(149052, 'koKR', '가시죠.', '', 28153),
(149051, 'koKR', '', '잠깐... 경비병이 왜 없죠?', 28153),
(149050, 'koKR', '가세. 서로 떨어지지 말고.', '', 28153),
(149049, 'koKR', '하, 미리 경고 좀 해주면 어디 덧나나.', '', 28153),
(149048, 'koKR', '늘 경계해라. SI:7에 의하면 적이 왕궁 근처까지 왔다 한다.', '', 28153),
(149047, 'koKR', '다리에서 당장 뛰어내리십시오.', '', 28153),
(149046, 'koKR', '다리를 건너세. 자네 예언자가 괜찮다고 하면 말일세.', '', 28153),
(149045, 'koKR', '어이, 빨리! 피하게.', '', 28153),
(149044, 'koKR', '대기하십시오.', '', 28153),
(149043, 'koKR', '스톰윈드 시민 여러분!', '', 28153),
(149042, 'koKR', '좋아, 다들 가까이 붙게, 친구들.', '', 28153),
(149041, 'koKR', '', '도시가 시끄럽군요. 오래 머물 순 없겠어요.', 28153),
(149040, 'koKR', '항해할 준비가 되었습니다!', '항해할 준비가 되었습니다!', 28153),
(149039, 'koKR', '', '쿨 티라스로 떠날 준비 되셨습니까?', 28153),
(149038, 'koKR', '', '덕분에 작전을 세울 시간을 조금 벌었습니다. 이제 크라그와께서 방어를 강화할 수 있겠군요. 감사합니다.', 28153),
(149037, 'koKR', '내 것을 되찾는 걸 막을 순 없다!', '', 28153),
(149036, 'koKR', '', '혈트롤이 계속 크라그와 님을 공격합니다! 놈들의 보급품을 차단하고 놈들에게 쓴맛을 보여 주십시오!', 28153),
(149035, 'koKR', '세스랄리스 님... 당신의 목소리를 잊고 말았습니다...', '', 28153),
(149034, 'koKR', '우린 로아의 힘을 빌리지 않는다. 이 힘은 우리의 것이다!', '', 28153),
(149033, 'koKR', '침입자들! 알지도 못 하는 일에 껴드는군.', '', 28153),
(149031, 'koKR', 'PLACEHOLDER SCENE - 탈란지가 모든 게 끝났는지 물어봅니다. 로칸은 악은 살아남을 방법을 찾을 테니 이곳을 보는 것이 마지막이 아닐 거라 생각합니다.\nShot: 탈란지와 로칸을 클로즈업한 다음 새롭게 드러난 구덩이를 불길하게 보여줍니다.', 'PLACEHOLDER SCENE - 탈란지가 모든 게 끝났는지 물어봅니다. 로칸은 악은 살아남을 방법을 찾을 테니 이곳을 보는 것이 마지막이 아닐 거라 생각합니다.\nShot: 탈란지와 로칸을 클로즈업한 다음 새롭게 드러난 구덩이를 불길하게 보여줍니다.', 28153),
(149030, 'koKR', '', '주인님... 실패했습니다...', 28153),
(149029, 'koKR', '', '고라크 툴 님이... 오신다...', 28153),
(149028, 'koKR', '', '고라크 툴 님이... 힘을 약속하셨건만...', 28153),
(149027, 'koKR', '', '전투엔 별 도움이 안 되겠지만, 어머니는 죄값을 치러야 해요... 그걸 제 눈으로 직접 봐야겠어요.', 28153),
(149026, 'koKR', '', '아버지를 위하여, 드러스트바를 위하여!', 28153),
(149025, 'koKR', '', '저는 안에서 합류할게요.', 28153),
(149024, 'koKR', '', '심문관들이여, 나를 따르라! 웨이크레스트 가문에 영광을!', 28153),
(149023, 'koKR', '', '네, 루실 님. 서약단을 무너뜨리겠어요.', 28153),
(149022, 'koKR', '', '심문관들이여, 마지막 전투예요. 모두에게 행운이 함께하기를.', 28153),
(149021, 'koKR', '', '어머니... 대체 무슨 짓을?', 28153),
(149020, 'koKR', '', '안 돼요, 치안대장님. 안 돼요...', 28153),
(149019, 'koKR', '송구... 합니다...', '', 28153),
(149018, 'koKR', '루실 님... 제가... 부족했습니다...', '', 28153),
(149017, 'koKR', '', '버티셔야 해요!', 28153),
(149016, 'koKR', '아냐... 이건... 아니야!', '', 28153),
(149015, 'koKR', '복종... 합니다...', '', 28153),
(149014, 'koKR', '당신은 루실 님, 치안대장님과 함께 가십시오!', '', 28153),
(149013, 'koKR', '', '넌 상대를 잘못 골랐다, 이 마녀야!', 28153),
(149012, 'koKR', '계속 이동하십시오. 저흰 괜찮습니다! 눈을 노려, 윈스톤!', '', 28153),
(149011, 'koKR', '바로 뒤따르겠습니다.', '바로 뒤따르겠습니다.', 28153),
(149010, 'koKR', '웨이크레스트 가문을 위하여!', '', 28153),
(149009, 'koKR', '뭉쳐라. 저택의 문을 뚫을 때까지 전진을 멈추지 마라!', '', 28153),
(149008, 'koKR', '이대로는 오래 버틸 수 없네. 부두로 달려가야 하네.\n\n말만 하면 바로 가겠네.', '', 28153),
(149007, 'koKR', '심문관들이여! 이건 웨이크레스트 군주와 부인을 구하고... 저 끔찍한 서약단을 없앨 절호의 기회다!', '', 28153),
(149005, 'koKR', '', '벌벌 떨고 있구나. 겁에 질렸는가, 얼라이언스여?', 28153),
(149004, 'koKR', '', '어지럽나?', 28153),
(149003, 'koKR', '', '가망이 있다고 생각했나, 정말?', 28153),
(149002, 'koKR', '', '미천한 쓰레기에게... 지다니...', 28153),
(149001, 'koKR', '네가 승리할 가능성은 전혀 없다!', '', 28153),
(149000, 'koKR', '내 그림자만 쫓는구나!', '', 28153),
(148999, 'koKR', '이 놈을 불사르자!', '', 28153),
(148998, 'koKR', '속임수를... 쓰다니...', '', 28153),
(148997, 'koKR', '내가 지켜주겠소!', '', 28153),
(148996, 'koKR', '방어 태세!', '', 28153),
(148995, 'koKR', '빛은... 날 돌려보내 주시리라.', '', 28153),
(148994, 'koKR', '', '심장을 꺼내라!', 28153),
(148993, 'koKR', '', '네 영혼을 고라크 툴 님께 보내겠다!', 28153),
(148991, 'koKR', '적의 습격이다, 전투 준비!', '적의 습격이다, 전투 준비!', 28153),
(148990, 'koKR', '자원을 지켜라!', '자원을 지켜라!', 28153),
(148989, 'koKR', '이 나무는 우리 것이다!', '이 나무는 우리 것이다!', 28153),
