(148894, 'koKR', '', '내 저주는 절대 깰 수 없다!', 28153),
(148893, 'koKR', '언젠가 이 야수들은 모두 호드를 섬길 겁니다. 그런 일은 용납할 수 없습니다.', '', 28153),
(148892, 'koKR', '야수의 수는 다시 늘어나겠지만 호드가 야수지기를 교체할 때까진 시간이 아주 오래 걸릴 거요. 수고했소!', '', 28153),
(148891, 'koKR', '잔달라의 생태 보존지는 전쟁용 야수들로 가득하지만, 그것도 훈련을 잘 받았을 때 얘기요. 놈들을 중독시켜 야수지기들을 끌어내시오. 그들이 진짜 목표요.', '', 28153),
(148890, 'koKR', '', '틀림없겠지요, 줄.', 28153),
(148889, 'koKR', '그쪽이 아닙니다. 다른 길이 맞습니다.', '', 28153),
(148888, 'koKR', '이쪽이네!', '', 28153),
(148887, 'koKR', '', '어떻게 나가죠?', 28153),
(148886, 'koKR', '', '당신 덕분에 혈트롤의 위협을 영원히 종식시키는 데 한 걸음 다가갔습니다.', 28153),
(148885, 'koKR', '', '근처에서 어둠의 모조가 느껴집니다. 분명 혈트롤입니다! 무슨 짓인진 몰라도, 놈들을 찾아 저지하십시오!', 28153),
(148884, 'koKR', '', '움직여야 해요!', 28153),
(148883, 'koKR', '', '포위하라!', 28153),
(148879, 'koKR', '구름이 물러나고... 폭풍이 가라앉는다...', '', 28153),
(148878, 'koKR', '나는 폭풍의 전령이다!', '', 28153),
(148877, 'koKR', '인사는 나중에 하죠.', '', 28153),
(148876, 'koKR', '', '저희는 호드를 대표해 왔어요. 저는 탈리스라, 이쪽은 로칸 님이에요.', 28153),
(148875, 'koKR', '', '흠... 고맙습니다. 제 예언자 말로는, 저희 동맹이시라고요?', 28153),
(148874, 'koKR', '아하하, 그래, 그래, 자네 기억나네. 그 교활하던-', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148872, 'koKR', '아, 호위병이 도착했군요. 제 말 대로 말입니다, 공주님.', '', 28153),
(148871, 'koKR', '흠, 가지. 이쪽일세.', '', 28153),
(148870, 'koKR', '잠시 쉴 시간이 필요합니다.', '', 28153),
(148868, 'koKR', '코르테크는 벽 뒤에 숨어 우리를 피할 수 있다고 생각하나 보군? 멍청하긴.', '', 28153),
(148867, 'koKR', '계획대로 하십시오. 저도 따라가겠습니다.', '', 28153),
(148858, 'koKR', '', '알겠어요... 대군주님의 뜻이 확실하다면요.', 28153),
(148857, 'koKR', '확실하오. 록타르.', '', 28153),
(148856, 'koKR', '여기 남을 생각이군.', '', 28153),
(148855, 'koKR', '날 구하러 온 게 아니지 않나. 자네가 찾는 이들은 저 밑에 있네.', '', 28153),
(148854, 'koKR', '보고에 따르면 제왕이 가장 취약할 때는 시장을 갈 때입니다. 시장은 근처에 있습니다.', '', 28153),
(148853, 'koKR', '자네가 이걸 가져가는 게 좋겠네.', '', 28153),
(148852, 'koKR', '', '우리가 주의를 끌게요. 조심하세요.', 28153),
(148851, 'koKR', '난 먼저 가 수감자들을 찾겠네. 엄호를 부탁하네.', '', 28153),
(148850, 'koKR', '여기에 7군단이 있네. 우리가 누굴 구출하든 저 인간들은 호락호락하지 않을 걸세.', '', 28153),
(148849, 'koKR', '내가 자네를 찾지. 행운을 비네.', '', 28153),
(148848, 'koKR', '탈출로는 저쪽일세. 수감자를 구하고 나면 저 배로 가게.', '', 28153),
(148847, 'koKR', '자네들 가방에 빠른 죽음을 선사하는 물건을 넣어 두었네. 선택의 여지가 없어지면 사용하도록.', '', 28153),
(148846, 'koKR', '자네가 붙잡힌다면... 대족장과 호드는 이 임무에 관해서 일체 부인할 걸세.', '', 28153),
(148845, 'koKR', '우리 정찰병이 숨겨진 입구를 찾았네. 타우렌과 내가 자네 탈출을 돕지.', '', 28153),
(148844, 'koKR', '자네는 탈리스라와 로칸과 감옥으로 잠입해 수감자들을 풀어주게.', '', 28153),
(148843, 'koKR', '잘 듣게. 일단 스톰윈드에 들어가면 연락이 끊길 걸세.', '', 28153),
(148842, 'koKR', '', '가시멧돼지 녀석들이 다시는 이런 규모의 전쟁을 벌이지 못하게 해야 해요.', 28153),
(148841, 'koKR', '너의 파멸이... 머지 않았다...', '너의 파멸이... 머지 않았다...', 28153),
(148840, 'koKR', '어떻게... 이럴 수가...', '어떻게... 이럴 수가...', 28153),
