(148611, 'koKR', '내 아내는 라바사우루스가 못 먹는 게 없다고 하지! 그건 위장이 강철 같다는 말일 게야! 그놈들 위벽을 좀 구해주게... 아내에게 들키기 전에.', '', 28153),
(148610, 'koKR', '자, 이것저것 구경 좀 하시겠습니까?', '자, 이것저것 구경 좀 하시겠습니까?', 28153),
(148609, 'koKR', '보고할 일이라도?', '보고할 일이라도?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148608, 'koKR', '쿨 티라스에서 제일가는 물건들입니다.', '쿨 티라스에서 제일가는 물건들입니다.', 28153),
(148607, 'koKR', '대충 만든 물건이란 없답니다.', '대충 만든 물건이란 없답니다.', 28153),
(148606, 'koKR', '뭘 도와드릴까요?', '뭘 도와드릴까요?', 28153),
(148605, 'koKR', '제독님의 은혜가 있기를!', '제독님의 은혜가 있기를!', 28153),
(148604, 'koKR', '몸을 따스히 하세요.', '몸을 따스히 하세요.', 28153),
(148603, 'koKR', '안녕하십니까?', '안녕하십니까?', 28153),
(148602, 'koKR', '한 잔 드릴까요?', '한 잔 드릴까요?', 28153),
(148601, 'koKR', '후미진 골목은 피해 다니십시오.', '후미진 골목은 피해 다니십시오.', 28153),
(148600, 'koKR', '굳건히 나아가세요.', '굳건히 나아가세요.', 28153),
(148599, 'koKR', '요즈음 도시가 흉흉합니다.', '요즈음 도시가 흉흉합니다.', 28153),
(148598, 'koKR', '무언가 찾으면 부르십시오! 이름을 기억해두겠습니다.', '', 28153),
(148597, 'koKR', '우리가 이걸 찾으면 제왕께서 세상을 지배하고 세스락의 영광을 되찾을 수 있을 겁니다! 전 언제나 여행을 원해왔습니다.', '', 28153),
(148596, 'koKR', '잠자는 자가 깨어날 것입니다.', '', 28153),
(148595, 'koKR', '그가 정말 깨어나면, 무사할 자가 있을까요?', '', 28153),
(148594, 'koKR', '열쇠가 있다고 생각합니까?', '', 28153),
(148593, 'koKR', '코르테크 제왕께서는 우리가 열쇠를 찾으면 세스락을 다시 합칠 수 있다고 생각하십니다.', '', 28153),
(148592, 'koKR', '무슨 소리 들리지 않았습니까?', '', 28153),
(148591, 'koKR', '제국의 일로 바쁩니다.', '', 28153),
(148590, 'koKR', '저 히죽거리는 \'추종자\'들도 곧 고개를 숙일 것입니다.', '', 28153),
(148589, 'koKR', '오늘은 바람이 세군요.', '오늘은 바람이 세군요.', 28153),
(148588, 'koKR', '몸을 따스하게 하십시오.', '몸을 따스하게 하십시오.', 28153),
(148587, 'koKR', '감독관의 말에 따르면 열쇠가 이곳에 있습니다. 빨리 찾을수록 빨리 나갈 수 있습니다. 여긴 좀 무섭군요.', '', 28153),
(148586, 'koKR', '몸을 따스히 하십시오.', '몸을 따스히 하십시오.', 28153),
(148585, 'koKR', '프라우드무어 가문이 우릴 지켜줄 겁니다. 늘 그랬듯이.', '프라우드무어 가문이 우릴 지켜줄 겁니다. 늘 그랬듯이.', 28153),
(148584, 'koKR', '바람과 파도가 도와주기를.', '바람과 파도가 도와주기를.', 28153),
(148583, 'koKR', '평화라는 걸 평생 모르게 될까 봐 걱정입니다.', '평화라는 걸 평생 모르게 될까 봐 걱정입니다.', 28153),
(148582, 'koKR', '본토 소식을 전하러 왔습니까?', '본토 소식을 전하러 왔습니까?', 28153),
(148581, 'koKR', '가혹한 상황이죠, 안 그런가요?', '가혹한 상황이죠, 안 그런가요?', 28153),
(148580, 'koKR', '새 상품이 오면 또 들러 주십시오.', '새 상품이 오면 또 들러 주십시오.', 28153),
(148579, 'koKR', '특이한 물품이 매일 들어옵니다.', '특이한 물품이 매일 들어옵니다.', 28153),
(148578, 'koKR', '언제든 다시 오십시오.', '언제든 다시 오십시오.', 28153),
(148577, 'koKR', '마음껏 둘러보십시오.', '마음껏 둘러보십시오.', 28153),
(148576, 'koKR', '자, 협상을 시작하시죠.', '자, 협상을 시작하시죠.', 28153),
(148575, 'koKR', '이것이... 끝은... 아니다...', '', 28153),
(148574, 'koKR', '이미 늦었다...', '', 28153),
(148573, 'koKR', '우린 절대 멈추지 않는다...', '', 28153),
(148572, 'koKR', '이 땅은... 우리 것이다...', '', 28153),
(148571, 'koKR', '트로스로... 돌아가리...', '', 28153),
(148570, 'koKR', '진지하게 얘기 좀 해볼까요?', '진지하게 얘기 좀 해볼까요?', 28153),
(148569, 'koKR', '복수는 우리 것이다!', '', 28153),
(148568, 'koKR', '자비란 없다!', '', 28153),
(148567, 'koKR', '드러스트가 이 땅을 되찾을 것이다!', '', 28153),
(148566, 'koKR', '고라크 툴님께 고개를 숙여라!', '', 28153),
(148565, 'koKR', '내가 깨어났다!', '', 28153),
(148564, 'koKR', '혹시 이것보다 더 중요한 일이 뭐라도 있지 않습니까?', '혹시 이것보다 더 중요한 일이 뭐라도 있지 않습니까?', 28153),
(148563, 'koKR', '들려요? 누군가 당신을 부르는 것 같아요. 바로 저쪽에서요. 아주 급한가 봐요!', '들려요? 누군가 당신을 부르는 것 같아요. 바로 저쪽에서요. 아주 급한가 봐요!', 28153),
(148562, 'koKR', '세상에... 시계 좀 봐요. 방금 떠났다가 또 온 건가요?', '세상에... 시계 좀 봐요. 방금 떠났다가 또 온 건가요?', 28153),
(148561, 'koKR', '앞길을 잘 살피십시오.', '앞길을 잘 살피십시오.', 28153),
(148560, 'koKR', '앞길이 평온하기를.', '앞길이 평온하기를.', 28153),
(148559, 'koKR', '차분하게 나아가십시오.', '차분하게 나아가십시오.', 28153),
(148553, 'koKR', '이곳을 완전히 태워버립시다!', '니샤 님처럼 놈들을 해치우십시오!', 28153),
(148552, 'koKR', '행운을 빕니다.', '행운을 빕니다.', 28153),
(148551, 'koKR', '다음 부정한자는 제 차지입니다!', '이 검을 유용하게 쓰겠습니다!', 28153),
(148550, 'koKR', '다시 무기를 드니 기분이 좋군요.', '놈들은 불페라를 두려워하게 될 겁니다.', 28153),
(148549, 'koKR', '제 기품에 매혹됐군요.', '제 기품에 매혹됐군요.', 28153),
(148548, 'koKR', '무슨 일로 찾아오셨습니까?', '무슨 일로 찾아오셨습니까?', 28153),
(148547, 'koKR', '', '오, 이거면 완벽합니다! 라알의 감정이 상한 건 신경 쓰지 마십시오. 금방 잊어버릴 겁니다.', 28153),
(148546, 'koKR', '', '저희 쪽에서 물약을 만들려면 테러닥스 타액이 필요한데 남편이 모으려 하지 않습니다. 물러 터져서 말이죠. 당신이 가서 최대한 침샘을 많이 모아주십시오!', 28153),
(148545, 'koKR', '잘했네. 우리 현자들이 이걸 연구하느라 바빠지겠군.', '', 28153),
(148544, 'koKR', '바람에 실려온 소문 없습니까?', '바람에 실려온 소문 없습니까?', 28153),
(148543, 'koKR', '만나서 반갑습니다.', '만나서 반갑습니다.', 28153),
(148542, 'koKR', '많은 토르톨란이 저 혈트롤 도살자들에게 목숨을 잃었지만, 그들의 지식은 아직 지킬 수 있네. 최대한 많은 두루마리를 회수하게!', '', 28153),
(148541, 'koKR', '어... 뭐야? 아이!!! 순간적인 상황 변화를 받아들이지 못하고 난폭하게 변해 버렸네!', '어... 뭐야? 순간적인 상황 변화를 받아들이지 못하고 난폭하게 변해 버렸네!', 28153),
(148540, 'koKR', '', '이럴 리가... 없어...', 28153),
(148539, 'koKR', '아, 게임 캐릭터의 폭력성을 확인해 보시겠다 이거군요!', '아, 게임 캐릭터의 폭력성을 확인해 보시겠다 이거군요!', 28153),
(148538, 'koKR', '', '내 마법이... 실패했다고?', 28153),
(148537, 'koKR', '', '난 힘을... 약속 받았는데...', 28153),
(148536, 'koKR', '그들의 영혼이 자유로워질 때까지 새 추종자를 받아들일 수 없다. 신의를 저버리는 일일 테니.', '', 28153),
(148535, 'koKR', '지금 시비 거시는 겁니까?', '지금 시비 거시는 겁니까?', 28153),
(148534, 'koKR', '', '힘이... 빠져나간다...', 28153),
(148533, 'koKR', '', '내 자매들이 널 파멸시키리라...', 28153),
(148532, 'koKR', '', '네 피를 의식에 사용하겠다!', 28153),
(148531, 'koKR', '', '넌 훌륭한 제물이 되겠구나!', 28153),
(148530, 'koKR', '', '모두 심장파멸을 섬기리라!', 28153),
(148529, 'koKR', '', '어머니시여, 힘을 주소서!', 28153),
(148528, 'koKR', '하나, 우두머리의 심장에 송곳니를 박아 넣은 순간, 놈은 내 추종자들의 영혼에 끝없는 저주를 걸었다.', '', 28153),
(148527, 'koKR', '', '내 목숨을 서약단에!', 28153),
(148526, 'koKR', '아내가 죽은 건 별 상관 없습니다. 제 길을 막는 이가 하나 줄었을 뿐인 것을.', '', 28153),
(148525, 'koKR', '페툴라가 제게 복수하려고 마녀의 길로 들어서다니...', '', 28153),
(148524, 'koKR', '나는 남아 있던 나가를 모조리 없앴다. 내 분노를 피할 수는 없었지...', '', 28153),
(148523, 'koKR', '일은 제 삶이나 다름없습니다! 페툴라도 됐고, 벤자민도 됐습니다. 이건 제 재산입니다.', '', 28153),
(148522, 'koKR', '바닥부터 시작했다고요! 저는 아내와 가족을 돕기 위해 이 사업을 시작했습니다.', '', 28153),
(148521, 'koKR', '웨이크레스트 가문에 영광을.', '웨이크레스트 가문에 영광을.', 28153),
(148520, 'koKR', '제가 처음부터 성공적인 벌목 회사를 이끌었던 것은 아니었습니다.', '', 28153),
(148519, 'koKR', '마녀들의 일에는 관여하지 마십시오.', '마녀들의 일에는 관여하지 마십시오.', 28153),
(148518, 'koKR', '낯선 사람을 주의하십시오.', '낯선 사람을 주의하십시오.', 28153),
(148517, 'koKR', '가까이 오지 마십시오, 본토인이여.', '가까이 오지 마십시오, 본토인이여.', 28153),
(148516, 'koKR', '아군이오, 적이오?', '아군이오, 적이오?', 28153),
(148515, 'koKR', '용건을 말하십시오.', '용건을 말하십시오.', 28153),
(148514, 'koKR', '몇백 년 전, 이 사원은 나가의 공격을 받았다. 내가 왔을 땐 추종자들을 구하기엔 너무 늦었었어.', '', 28153),
(148513, 'koKR', '토르타카가 나가 때문에 곤란한 것은 안타깝지만, 난 그들을 지켜줄 수 없다.', '', 28153),
(148512, 'koKR', '바다가 은혜를 베풀기를.', '바다가 은혜를 베풀기를.', 28153),
(148511, 'koKR', '어떤 길에도 시련은 있기 마련이에요.', '어떤 길에도 시련은 있기 마련이에요.', 28153),
(148510, 'koKR', '우리의 것을 되찾을 겁니다.', '우리의 것을 되찾을 겁니다.', 28153),
(148509, 'koKR', '참 평온하던 시절도 있었죠.', '참 평온하던 시절도 있었죠.', 28153),
(148508, 'koKR', '일손은 많을수록 좋죠.', '일손은 많을수록 좋죠.', 28153),
(148507, 'koKR', '근처에서 못 보던 분인데, 맞죠?', '근처에서 못 보던 분인데, 맞죠?', 28153),
(148506, 'koKR', '스톰송은 다시 한 번 정화될 겁니다.', '스톰송은 다시 한 번 정화될 겁니다.', 28153),
(148505, 'koKR', '심연에 도사리는 것을 조심하십시오.', '심연에 도사리는 것을 조심하십시오.', 28153),
(148504, 'koKR', '바다가 당신을 빠르게 실어다 주기를.', '바다가 당신을 빠르게 실어다 주기를.', 28153),
(148503, 'koKR', '우린 이 위기를 극복할 겁니다.', '우린 이 위기를 극복할 겁니다.', 28153),
(148502, 'koKR', '저는 바다를 섬기는 자들을 환영합니다.', '저는 바다를 섬기는 자들을 환영합니다.', 28153),
(148501, 'koKR', '파도가 당신을 반깁니다.', '파도가 당신을 반깁니다.', 28153),
(148500, 'koKR', '이 계곡을 다시 온전하게 만들 겁니다.', '이 계곡을 다시 온전하게 만들 겁니다.', 28153),
(148499, 'koKR', '늘 긴장을 놓지 마십시오.', '늘 긴장을 놓지 마십시오.', 28153),
(148498, 'koKR', '폭풍의 노래를 기억하십시오.', '폭풍의 노래를 기억하십시오.', 28153),
(148497, 'koKR', '우리는 흔들리지 않습니다.', '우리는 흔들리지 않습니다.', 28153),
(148496, 'koKR', '스톰송은 이겨낼 겁니다.', '스톰송은 이겨낼 겁니다.', 28153),
(148495, 'koKR', '먼 길을 오셨군요.', '먼 길을 오셨군요.', 28153),
(148493, 'koKR', '.....무사하라고, 친구. 그리고 $n, 모조깨나 쓸 줄 알던데. 볼둔에 오면 한번 보자고.', '', 28153),
(148492, 'koKR', '진티키, 잘 가게... 부디 살아남길.', '', 28153),
(148491, 'koKR', '제가 처리하겠습니다.', '', 28153),
(148490, 'koKR', '계획이 준비됐습니다. 가시지요.', '', 28153),
(148489, 'koKR', '하! 이런 미친 노름은 생전 처음이야!', '', 28153),
(148488, 'koKR', '줄라진이 죽었습니다! 빠져나갑시다.', '', 28153),
(148487, 'koKR', '좋습니다! 이대로만 하십시오!', '', 28153),
(148486, 'koKR', '이크!', '이크!', 28153),
(148485, 'koKR', '절 잡아먹지 마세요!', '절 잡아먹지 마세요!', 28153),
(148484, 'koKR', '아악!', '아악!', 28153),
(148483, 'koKR', '아빠가 무슨 작업을 하셨길래 이런 일이...?', '', 28153),
(148482, 'koKR', '벌꿀이 어떻게 혼자서 움직이는 거죠?', '', 28153),
(148481, 'koKR', '헛! 어어어.... $p 님... 벌... 벌꿀이... 살... 살아 있는 건가요!?', '', 28153),
(148480, 'koKR', '감사합니다, 이방인.', '감사합니다, 이방인.', 28153),
(148479, 'koKR', '세스락이 이곳을 떠날 때 전리품 하나도 못 챙기게 할 겁니다.', '세스락이 이곳을 떠날 때 전리품을 챙기지 못하도록 할 겁니다.', 28153),
(148478, 'koKR', '\"여우야, 여우야, 뭐 하니\" 놀이를 시작해 볼까요...', '\"여우야, 여우야, 뭐 하니\" 놀이를 시작해 볼까요...', 28153),
(148477, 'koKR', '와! 자유다! 절 잡아먹지 않으셨군요!', '와! 자유다! 절 잡아먹지 않으셨군요!', 28153),
(148476, 'koKR', '됐어요, 이제 두 배로 돌려받을 겁니다.', '됐어요, 이제 두 배로 돌려받을 겁니다.', 28153),
(148475, 'koKR', '', '모래에 묻히지 않아서 다행이네요, $n 님!', 28153),
(148473, 'koKR', '위대하신 로아여, 토르타카 부족이 바치는 공물입니다.', '위대하신 로아여, 토르타카 부족이 바치는 공물입니다.', 28153),
