(146119, 'koKR', '너희 필멸자들은 다 똑같아. 싸우긴 엄청 싸우는데, 목적이 뭔지도 모르고 싸워.', '', 28153),
(146118, 'koKR', '우리가 여기 있는 건 어떻게 알아낸 거지?', '', 28153),
(146117, 'koKR', '이런, 이런. 이건 또 뭔가?', '', 28153),
(146116, 'koKR', '', '너는 공허 앞에선 한낱 미물에 불과해!', 28153),
(146115, 'koKR', '', '영지 저택에 어서 오십시오. 부디 마음껏 돌아보시고, 도움이 필요한 일이 있다면 말씀해 주십시오.', 28153),
(146114, 'koKR', '너는 공허 앞에선 한낱 미물에 불과해!', '', 28153),
(146113, 'koKR', '직접 사냥을 나가는 것도 꽤나 기대가 되네. 가장 커다란 곰을 잡을 거라고!', '', 28153),
(146110, 'koKR', '너무 늦었을지도 모릅니다.', '', 28153),
(146109, 'koKR', '귀족들의 거만한 태도는 내 취향이 살짝 아니지만, 놀윙턴 님은 좋아할 수밖에 없지!', '', 28153),
(146108, 'koKR', '', '어이! 한 판 더!', 28153),
(146107, 'koKR', '', '엄청난 판이었군! 지금까지 본 중 최고가 아니었나 싶네.', 28153),
(146106, 'koKR', '<테러닥스에게 간식을 주고 안장에 올라탑니다.>', '<테러닥스에게 간식을 주고 안장에 올라탑니다.>', 28153),
(146105, 'koKR', '', '짜잔!', 28153),
(146104, 'koKR', '<킁킁대며 냄새를 맡고 당신의 다음 행동을 기다리는 테러닥스>', '', 28153),
(146103, 'koKR', '', '깔려 죽을 준비나 하시지!', 28153),
(146102, 'koKR', '깔려 죽을 준비나 하시지!', '', 28153),
(146101, 'koKR', '', '황천으로 비명 지르며 도망치게 해 주마!', 28153),
(146100, 'koKR', '네가 빛에게 상대가 될 거라 생각하나?', '', 28153),
(146099, 'koKR', '통제되지 않은 공허 마력이 다른 섬들마저 황폐하게 만들고 있습니다. 지금으로서는 너무 위험해서 위치를 추적하기가 어렵습니다.', '통제되지 않은 공허 마력이 다른 섬들마저 황폐하게 만들고 있습니다. 지금으로서는 너무 위험해서 위치를 추적하기가 어렵습니다.', 28153),
(146098, 'koKR', '공허의 폭풍이 위세를 더해갑니다. 이 커다란 섬 전체를 삼킬 수도 있습니다.', '공허의 폭풍이 위세를 더해갑니다. 이 커다란 섬 전체를 삼킬 수도 있습니다.', 28153),
(146097, 'koKR', '', '네 열등함은 자명하다!', 28153),
(146096, 'koKR', '네 열등함은 자명하다!', '', 28153),
(146094, 'koKR', '거, 거기! 좋아, 정지!', '', 28153),
(146092, 'koKR', '천천히... 조심조심...', '', 28153),
(146091, 'koKR', '좋아, 여기에 자리를 잡자고!', '', 28153),
(146090, 'koKR', '온전한 공허 마력이 이 공간에 녹아 있습니다... 놀랍군요.', '온전한 공허 마력이 이 공간에 녹아 있습니다... 놀랍군요.', 28153),
(146089, 'koKR', '로아여, 감사합니다. 목숨을 건졌습니다!', '', 28153),
(146088, 'koKR', '로아를 찬양하라! 당신은 저의 영웅입니다!', '', 28153),
(146087, 'koKR', '신세를 졌습니다, 이방인님. 이제 절대 이 저주받은 늪에 오지 않을 겁니다!', '', 28153),
(146086, 'koKR', '당신에게 엄청난 축복이 내리길, 이방인이여!', '', 28153),
(146085, 'koKR', '이번 일은 절대 잊지 않겠다!', '', 28153),
(146084, 'koKR', '감사합니다. 브원삼디 님을 뵙게 되는 줄 알았습니다!', '', 28153),
(146083, 'koKR', '으억! 바지를 깜빡했잖아!', '', 28153),
(146082, 'koKR', '별세계도 이만큼 놀랍진 않을 겁니다!', '', 28153),
(146081, 'koKR', '', '별세계도 이만큼 놀랍진 않을 겁니다!', 28153),
(146080, 'koKR', '감사합니다, $n 님. 다음에 뵙죠! 저는 바지를 찾으러 이만...', '', 28153),
(146079, 'koKR', '난생 처음 보는 광경입니다!', '', 28153),
(146078, 'koKR', '', '난생 처음 보는 광경입니다!', 28153),
(146077, 'koKR', '대지모신이여, 맙소사!', '', 28153),
(146076, 'koKR', '', '대지모신이여, 맙소사!', 28153),
(146075, 'koKR', '흥미롭군요.', '', 28153),
(146074, 'koKR', '', '흥미롭군요.', 28153),
(146073, 'koKR', '', '우편은 계속 배달되어야 해요!', 28153),
(146072, 'koKR', '', '우편이 가는 곳에는 저도 가죠!', 28153),
(146071, 'koKR', '', '케이티 스탬프휘슬입니다. 뭘 도와드릴까요?', 28153),
(146070, 'koKR', '', '절 부르셨나요?', 28153),
(146069, 'koKR', '', '아쉽지만 제 시간은 여기까지예요. 다음에 만나요!', 28153),
(146068, 'koKR', '', '어머나, 늦었잖아! 우편들이 알아서 분류되면 좋을 텐데!', 28153),
(146067, 'koKR', '', '우편 업무 보러 가야겠어요! 다음에 봐요!', 28153),
(146066, 'koKR', '다시 해 봐야겠습니다.', '', 28153),
(146065, 'koKR', '선조시여, 용서하소서.', '', 28153),
(146064, 'koKR', '', '우체국장님께서 제가 당장 필요하신가 봐요. 그럼 안녕히!', 28153),
(146061, 'koKR', '', '선조시여, 용서하소서.', 28153),
(146060, 'koKR', '크큭, 늦었다... 그분은... 왕이 여기 있는 걸... 아신다...', '크큭, 늦었다... 그분은... 왕이 여기 있는 걸... 아신다...', 28153),
(146059, 'koKR', '줄 님이 미친 왕으로부터 우리를 구하실 거다! 넌 방해가 될 뿐이야!', '줄 님이 미친 왕으로부터 우리를 구하실 거다! 넌 방해가 될 뿐이야!', 28153),
(146058, 'koKR', '', '다시 해 보겠습니다.', 28153),
(146057, 'koKR', '그래서 내가 다시 가게로 들어가 내게 준 사파이어를 온전한 사파이어로 바꾸어 달라고 요구했네. 대체 날 뭘로 보고!', '', 28153),
(146056, 'koKR', '윽! 이런 실수를!', '', 28153),
(146055, 'koKR', '때려 주겠어!', '', 28153),
(146054, 'koKR', '고작 그 정도냐?', '', 28153),
(146053, 'koKR', '맙소사, 검은 모루여!', '', 28153),
(146052, 'koKR', '', '잘했다고는 하기 힘들군요.', 28153),
(146051, 'koKR', '으억! 우아한 탈출 방법은 아니지만, 정말 감사합니다!', '', 28153),
(146050, 'koKR', '공허의 습격이다! 놈들을 쓰러뜨려라!', '공허의 습격이다! 놈들을 쓰러뜨려라!', 28153),
(146049, 'koKR', '온다!', '온다!', 28153),
(146048, 'koKR', '', '윽! 이런 실수를!', 28153),
(146047, 'koKR', '', '다넬이 탔던 암당나귀 봤나? 하! 순위에 들어갈 생각을 하긴 한 건지.', 28153),
(146046, 'koKR', '', '안녕하세요!', 28153),
(146045, 'koKR', '우편을 확인하고 싶습니다.', '우편을 확인하고 싶습니다.', 28153),
(146044, 'koKR', '', '안녕하십니까! 어떻게 도와드릴까요?', 28153),
(146043, 'koKR', '재가 되리라...', '', 28153),
(146042, 'koKR', '다시 태어난다!', '', 28153),
(146040, 'koKR', '', '와, 예쁘다!', 28153),
(146039, 'koKR', '가족끼리는 사이좋게 지내야지, 얘들아. 우리에게는 가족이 가장 소중하단다.', '', 28153),
(146038, 'koKR', '그만하렴, 주난지! 주디나에게 사과해.', '', 28153),
(146037, 'koKR', '주디나에게 상냥하게 대해주렴, 주난지.', '', 28153),
(146036, 'koKR', '', '둘 다 혼난다. 적당히 하렴!', 28153),
(146035, 'koKR', '', '주난지에게 뭐 잊은 거 없니, 주디나?', 28153),
(146034, 'koKR', '', '주디나야, 쉿...', 28153),
(146033, 'koKR', '이익...', '', 28153),
(146032, 'koKR', '아야!', '', 28153),
(146031, 'koKR', '오우...', '', 28153),
(146030, 'koKR', '바지 볼 시간은 없겠군요! 어디 화상 전문 병원이 있는지 찾아 봐야겠는걸요...', '', 28153),
(146029, 'koKR', '큰일이 날 뻔했군요! 확인 좀 해 봐야겠습니다. 눈썹... 있고. 수염... 있고. 바지...', '', 28153),
(146028, 'koKR', '', '이 길이 맞는 거야?', 28153),
(146027, 'koKR', '으아아아아아아아아!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(146026, 'koKR', '발사!', '', 28153),
(146025, 'koKR', '그럼, 간단하게 불 좀 붙여서 냄새를 처리하도록 하죠...', '', 28153),
(146024, 'koKR', '새로운 동맹을 영입할 준비가 됐습니다.', '새로운 동맹을 영입할 준비가 됐습니다.', 28153),
(146023, 'koKR', '아아... 이 비단의 촉감은 어느 여름 아침 내리는 비보다 더 좋군요...', '', 28153),
(146022, 'koKR', '$n 님, 아제로스에 곧 전쟁이 일어날 거예요. 이제 얼라이언스에 새 동맹을 편입시킬 때입니다.', '', 28153),
(146021, 'koKR', '우리는 공허 엘프에 관해 어떤 정보를 가지고 있습니까?', '우리는 공허 엘프에 관해 어떤 정보를 가지고 있습니까?', 28153),
(146020, 'koKR', '빛벼림 드레나이에 관해 알려 주실 수 있습니까?', '빛벼림 드레나이에 관해 알려 주실 수 있습니까?', 28153),
(146019, 'koKR', '이 주인 없는 섬에서 강력한 지열 에너지 반응을 관찰했습니다.\n\n분명, 아제라이트입니다!', '', 28153),
(146018, 'koKR', '천연 가스와 섞인 액체 아제라이트는 빠르게 굳어 획득하기 쉬운 형태로 변합니다. 시선을 아래로 내리고 표면에 불안정한 움직임을 찾아보십시오. 최근 일어나는 지진으로 미루어 볼 때... 분명 균열이나 틈 사이로 뿜어져 나올 겁니다.', '', 28153),
(146017, 'koKR', '안타깝지만, 그건 허락할 수 없다.', '', 28153),
(146016, 'koKR', '좋다.', '', 28153),
(146015, 'koKR', '어쩌면.', '', 28153),
(146014, 'koKR', '당분간은.', '', 28153),
(146013, 'koKR', '힘은 의외의 곳에서도 발견된다고 교육받았다.', '', 28153),
(146012, 'koKR', '꽤 아플 것으로 예상된다.', '', 28153),
(146011, 'koKR', '널 죽이기 위해 만들어졌지.', '', 28153),
(146010, 'koKR', '축하한다.', '', 28153),
(146009, 'koKR', '왜 돌아왔나?', '', 28153),
(146008, 'koKR', '나는 규정상 인사를 해야 한다. 안녕하신가.', '', 28153),
(146007, 'koKR', '목적을 말해라.', '', 28153),
(146006, 'koKR', '불안정한 공허의 균열과 균열의 존재들을 조심하십시오. 여긴 완벽하게 안전한 곳이 아닙니다.', '불안정한 공허의 균열과 균열의 존재들을 조심하십시오. 여긴 완벽하게 안전한 곳이 아닙니다.', 28153),
(146005, 'koKR', '이야기를 들려주세요!', '이야기를 들려주세요!', 28153),
(146004, 'koKR', '', '안 돼! 내 노예들! 돌아와!', 28153),
(146003, 'koKR', '여기서 나가야겠어요!', '여기서 나가야겠어요!', 28153),
(146002, 'koKR', '제브아하리가 무슨 짓을 했기에 이런 일을 당해야 합니까?', '제브아하리가 무슨 짓을 했기에 이런 일을 당해야 합니까?', 28153),
(146001, 'koKR', '저는 왕에게 가겠어요!', '저는 왕에게 가겠어요!', 28153),
(146000, 'koKR', '왜 저들이 우릴 공격하죠?!', '왜 저들이 우릴 공격하죠?!', 28153),
(145999, 'koKR', '제브아하리가 장악당했어요!', '제브아하리가 장악당했어요!', 28153),
(145998, 'koKR', '예감이 좋지 않아요...', '예감이 좋지 않아요...', 28153),
(145997, 'koKR', '이건 좋지 않은데!', '이건 좋지 않은데!', 28153),
(145996, 'koKR', '저들은 왕을 죽이러 여기 왔습니다!', '저들은 왕을 죽이러 여기 왔습니다!', 28153),
(145986, 'koKR', '', '수레에서 내려와, 한 판 붙자!', 28153),
(145985, 'koKR', '', '주난지, 네 발가락을 또 잘라주겠어!', 28153),
(145984, 'koKR', '', '으으, 끈적거리잖아!', 28153),
(145983, 'koKR', '', '으악! 세계 신기록 세울 수 있었는데!', 28153),
(145982, 'koKR', '', '이 더러운 혈트롤!', 28153),
(145981, 'koKR', '', '넌 최악이야, 주난지!', 28153),
(145980, 'koKR', '', '으웩!', 28153),
(145979, 'koKR', '', '징그러!', 28153),
(145978, 'koKR', '얼라이언스가 마른수염 광산을 점령했습니다!', '얼라이언스가 마른수염 광산을 점령했습니다!', 28153),
(145977, 'koKR', '천만 좀 구해 주시면 저는 준비 끝입니다요!', '', 28153),
(145976, 'koKR', '어서 가보는 게 좋겠군요. 늦으면 재미있는 부분을 놓치게 될 겁니다!', '', 28153),
(145975, 'koKR', '꽤 흥미로울 겁니다. 전 이제 동굴로 가보겠습니다.', '', 28153),
(145974, 'koKR', '자, 이제 마지막입니다!', '', 28153),
(145973, 'koKR', '좋습니다. 변환술이 효과가 있는 게 느껴집니다!', '', 28153),
(145972, 'koKR', '제시간에 오셨군요! 이제 진행 중인 역사를 목격하시지요!', '', 28153),
(145971, 'koKR', '<...>', '<...>', 28153),
(145970, 'koKR', '아이... 귀는... 괜찮은... 것 같은데요?', '아이... 귀는... 괜찮은... 것 같은데요?', 28153),
(145969, 'koKR', '괜찮으세요?', '괜찮으세요?', 28153),
(145968, 'koKR', '', '<생각에 잠긴 듯 잠시 먼 곳을 바라보는 샤통 부인>\n\n...죄송해요... 저는 고양이가 너무 좋아요. 전부 기르고 싶지만 그럴 수 없답니다. 이곳에 없으니까요. 모든 고양이를 애완동물로 삼을 수 없어요. 제 고양이만을 기를 수 있고 지금은 그걸로 만족할 수 밖에요.\n\n<그녀가 눈에 고인 눈물을 닦아내는 지금이 대화를 끝낼 기회라는 생각이 듭니다.>', 28153),
(145967, 'koKR', '', '지금은 티가 나지 않아요. 수라마르 최고의 의사를 불러왔으니까요. 아, 이쪽은 잿불이에요. 아주 교활한 아이죠! 발톱을 꽂을 수 있는 곳이라면 어디든 올라가는 걸 좋아하고 다른 고양이의 장난감을 훔치는 걸 좋아한답니다. 그래서 이 아이가 왔을 때 다른 세 고양이들이 귀찮아했죠. 벨라는 어렸을 때여서 그런지 별로 신경 쓰지 않았어요. 그리고 그 아이는 이 녀석을 떠받드는 것 같아요. 잿불이는 특히나 그늘이의 장난감 공을 훔치는 걸 좋아하는데, 그늘이는 가장 좋아하는 물건을 뺏기니까 화를 내죠. 보통은 제가 더러운 걸 집안에 들이지 못하게 하는데, 녀석은 집안에 두는 걸 좋아한답니다.', 28153),
(145966, 'koKR', '', '<잠시 울음을 멈추고 스스로를 진정시키는 샤통 부인>\n\n아, 아직 나머지 아이를 소개하지 않았네요! \n\n여기는 벨라예요. 어렸을 때부터 나풀나비 부인과 사이가 좋지 않았어요. 벨라가 어렸을 때 말이에요. 나풀나비 부인은 어리지 않았고요. 바보 같죠. 어른 고양이인데 말이죠... 아, 그리고 실랑이를 벌이다가 저 불쌍한 아이 귀가 찢어졌죠!', 28153),
(145965, 'koKR', '기계를 쓰러뜨려라!', '기계를 쓰러뜨려라!', 28153),
(145964, 'koKR', '부드럽게 짜내는 중', '부드럽게 짜내는 중', 28153),
(145963, 'koKR', '부서져 버렸군.', '', 28153),
(145962, 'koKR', '', '전 한때 쿨 티라스 군대의 대장이었어요. 은퇴하긴 했지만, 전 제 경력에 큰 자부심을 느끼고 있죠.$b$b솔직히 말하자면, 저는 오락을 그다지 좋아하지 않아요. 하지만, 제대로 된 사냥은 즐기는 편이고, 제 남편도 자신이 여는 축제를 매우 좋아하죠.$b$b도울 수 있는 건 돕고 있어요. 가끔은 겉치레가 필요한 법이니까요, 안 그런가요?', 28153),
(145961, 'koKR', '예비 부품이 생겼군.', '', 28153),
(145960, 'koKR', '썩어라!', '', 28153),
(145959, 'koKR', '곪아 터져라!', '', 28153),
(145958, 'koKR', '', '내 명에 따라 현실은 산산이 조각난다!', 28153),
(145957, 'koKR', '', '모조리 삼켜 버리겠다!', 28153),
(145956, 'koKR', '', '우리 사랑을 방해하더니 꼴 좋구나.', 28153),
(145955, 'koKR', '', '이 난장판은 우리 사랑스러운 남편이 치워 주겠지?', 28153),
(145954, 'koKR', '', '우릴 갈라놓지 못 하리라...', 28153),
(145953, 'koKR', '', '꼴 좋군.', 28153),
(145952, 'koKR', '', '이래서 수준 낮은 것들은.', 28153),
(145951, 'koKR', '', '세상은 불타오를 것이다!', 28153),
(145950, 'koKR', '', '넌 상상도 못 할 힘이 우리 손에 있다!', 28153),
(145949, 'koKR', '', '침입자 놈들! 죽어라!', 28153),
(145948, 'koKR', '', '이 땅은 우리 주인님의 것이다!', 28153),
(145947, 'koKR', '', '넌 비명을 지르며 죽을 것이다!', 28153),
(145946, 'koKR', '', '그분이 오신다... 그분이...', 28153),
(145945, 'koKR', '', '우리는... 복수할 것이다...', 28153),
(145944, 'koKR', '', '우리가... 이길 것이다...', 28153),
(145943, 'koKR', '', '난 힘을... 약속받았는데...', 28153),
(145942, 'koKR', '녀석들을 남서쪽 호수에 있는 아빠한테 데려다 주라고. 보상 받는 거 잊지 말고!', '', 28153),
(145941, 'koKR', '노다지 맙소사! 어린 멀록이 사방에 깔려있잖아!', '', 28153),
(145940, 'koKR', '이런... 포즈루크가 남동쪽의 길을 순찰하고 있어. 그쪽으로 갈 땐 늙고 괴팍한 바위 거인을 조심하라고.', '', 28153),
(145939, 'koKR', '저 녀석들을... 두들겨서 우리 편으로 끌어들일 수 있을지 보자고!', '', 28153),
(145938, 'koKR', '주술사들이 그러는데, 길 잃은 대지의 정령이 동쪽에 있는 언덕 꼭대기에 들어앉았대.', '', 28153),
(145937, 'koKR', '그래, 그래. 포즈루크 약골들 때려 주러 간다.', '', 28153),
(145936, 'koKR', '알겠다, 알겠어. 포즈루크 그만한다. 포즈루크가 뭐 하면 되나?', '', 28153),
(145935, 'koKR', '포즈루크에게 정령의 마법진을 공격해 달라고 합니다.', '포즈루크에게 정령의 마법진을 공격해 달라고 합니다.', 28153),
(145934, 'koKR', '포즈루크에게 뉴스테드를 공격해 달라고 합니다.', '포즈루크에게 뉴스테드를 공격해 달라고 합니다.', 28153),
(145933, 'koKR', '포즈루크에게 북부습곡 십자로를 공격해 달라고 합니다.', '포즈루크에게 북부습곡 십자로를 공격해 달라고 합니다.', 28153),
(145932, 'koKR', '...돈?', '', 28153),
(145931, 'koKR', '하지만... 하지만... 엄청난 돈을 생각해보라고!', '', 28153),
(145930, 'koKR', '친구여, 제 동료들은 전쟁을 좋아하지 않습니다. 당신의 어리석은 일에 동참하지 않겠습니다.', '', 28153),
(145929, 'koKR', '우리에게 아주 중요한 것일 수도 있어. 아주 많이! 이제 카자마이트를 찾게 도와줄 친절한 고릴라만 있으면 되겠군...', '', 28153),
(145928, 'koKR', '고작 야생 고릴라 몇 마리 때문에? 내 친구가 처리하지 못 하는 일은 없다고! 그렇지, 호구? 아니 내 말은, 친구?', '', 28153),
(145927, 'koKR', '', '전 저 작은 고블린들에게 경고했어요. 저 협곡이 버려진 데에는 이유가 있다고요.', 28153),
(145926, 'koKR', '', '우리의 유대는 깨지지 않는다!', 28153),
(145925, 'koKR', '', '그를 포기할 것 같으냐!', 28153),
(145924, 'koKR', '', '안 돼! 내 짝을 빼앗길 순 없어!', 28153),
(145923, 'koKR', '', '여보, 손님을 맞이해 줘요.', 28153),
(145922, 'koKR', '', '카자마이트란 무엇일까요? 우리에게 지성을 주는 강력한 자원이죠!\n\n수천 년 전 케잔에서 처음 발견됐는데, 우리 고블린들이 채굴하고 정제했어요. 일부 전문가들은 카자마이트가 고블린에게 엄청난 지성을 주었다고 하더군요.\n\n잔달라 트롤들도 카자마이트를 사용합니다. 여러 가지 용도로 쓰지만 주로 의식에 사용하죠. 하지만 고블린 법에 따르면, 모든 카자마이트는 고블린 소유라고요!', 28153),
(145921, 'koKR', '카자마이트가 무엇입니까?', '카자마이트가 무엇입니까?', 28153),
(145920, 'koKR', '', '정말 흥미롭군요! 어쩌면 잃어버린 섬 이후 처음으로 발견한 진정한 카자마이트일 수도 있어요. 흥분을 가라앉히기 힘들군요!', 28153),
(145919, 'koKR', '', '어머나, 봐요. 당신 저녁 식사가 왔네.', 28153),
(145918, 'koKR', '음... 꽤나 형편없는 결과로군. 자네가 협곡 깊은 곳으로 가서 탐색할 만한 분출구가 있는지 알아봐 주게.', '', 28153),
(145917, 'koKR', '이제 마지막입니다!', '', 28153),
(145916, 'koKR', '좋습니다. 변신이 효과가 있는 게 느껴집니다!', '', 28153),
(145915, 'koKR', '때마침 오셨습니다, 수습생님! 이제 역사가 만들어지는 것을 지켜보십시오!', '', 28153),
(145914, 'koKR', '흠... 어떤 로아와 거래하러 오셨습니까?', '흠... 어떤 로아와 거래하러 오셨습니까?', 28153),
(145913, 'koKR', '제가 누군지 아십니까?', '제가 누군지 아십니까?', 28153),
(145912, 'koKR', '원하는 게 있으십니까?', '원하는 게 있으십니까?', 28153),
(145911, 'koKR', '잔달라는 영원하리.', '잔달라는 영원하리.', 28153),
(145910, 'koKR', '당신이 새끼 크로그에게서 신뢰를 얻을 수 있다면 새끼 크로그는 언젠가 강력한 아군이 될 것입니다.', '', 28153),
(145909, 'koKR', '얼라이언스가 밸러콜의 길에서 우리 야영지를 공격하고 있다고!', '', 28153),
(145908, 'koKR', '정령의 마법진에서 얼라이언스 부대를 발견했어!', '', 28153),
(145907, 'koKR', '이봐! 얼라이언스가 뉴스테드를 공격하고 있다고!', '', 28153),
(145906, 'koKR', '높은 감시대에 얼라이언스 병력이 잔뜩 있잖아! 놈들이 유리한 위치를 잡기 전에 막아야 한다고!', '', 28153),
(145905, 'koKR', '얼라이언스가 북부습곡 십자로를 공격하잖아! 막아야 해, 우리 본진 코앞이라고!', '', 28153),
(145904, 'koKR', '놈들이 광산을 공격하고 있다고! 우리 광산을!', '', 28153),
(145903, 'koKR', '이봐, 놈들이 손도끼 마루에서 제재소를 공격하고 있잖아! 저 목재 필요한 거라고!', '', 28153),
(145902, 'koKR', '얼라이언스 병사들이 우리 본진으로 오고 있잖아! 어서 돌아오지 않으면 우리가 질 거라고!', '', 28153),
(145901, 'koKR', '대체 무슨 소란인지 모르겠습니다.', '', 28153),
(145900, 'koKR', '좋은 기회를 놓치고 싶지 않다면 서둘러서 오십시오.', '', 28153),
(145899, 'koKR', '마침 잘 오셨습니다, 수습생님. 저는 이제 동굴로 떠납니다.', '', 28153),
(145898, 'koKR', '오랫동안 우리를 받아들이지 않던 길이 드디어 열렸습니다.', '오랫동안 우리를 받아들이지 않던 길이 드디어 열렸습니다.', 28153),
(145897, 'koKR', '이제 지식을 탐구할 때 추방당할까 봐 걱정하지 않아도 됩니다.', '이제 지식을 탐구할 때 추방당할까 봐 걱정하지 않아도 됩니다.', 28153),
(145896, 'koKR', '흥미롭군.\n\n알레리아 윈드러너의 변화는 필연적이라 여겼다. 하지만 그녀의 종족까지 유사한 변신을 할 거란 기대는 못 했지.\n\n다양한 가설이 있다. 이 일로 생각할 게 많아졌군.', '', 28153),
(145895, 'koKR', '', '목소리는 멈추는 법이 없어요. 충동질하기도, 괴롭히기도, 애원하기도 하죠. 한순간도 만족하는 법이 없어요.\n\n하지만 당신은 그 목소리들보다 강해요. 놈들의 비밀을 알아내고 그들의 힘을 이용할 수 있어요.', 28153),
(145894, 'koKR', '이건 그저 살과 뼈가 다친 상처가 아닙니다. 배신이 영혼에 상처를 남겼습니다.', '', 28153),
(145893, 'koKR', '알레리아 님이 가르침이 있기에 우리는 마크아리에서 고통받던 이들의 운명을 피할 수 있게 되었습니다.', '', 28153),
(145892, 'koKR', '<순간 집중력이 떨어진 엘프들이 당신에게 싸늘한 눈길을 보냅니다.>', '<순간 집중력이 떨어진 엘프들이 당신에게 싸늘한 눈길을 보냅니다.>', 28153),
(145891, 'koKR', '공격 개시!', '공격 개시!', 28153),
(145890, 'koKR', '보시다시피, 저희가 지금 좀 바쁩니다.', '보시다시피, 저희가 지금 좀 바쁩니다.', 28153),
(145889, 'koKR', '안녕하신가?', '', 28153),
(145888, 'koKR', '전하께서 아직 삶을 포기하시진 않았지만, 시간이 없네. 상처가 아물지를 않습니다.', '', 28153),
(145887, 'koKR', '어리석은 것...', '어리석은 것...', 28153),
(145886, 'koKR', '모두가 무자비한 심해를 섬기리라!', '', 28153),
(145885, 'koKR', '', '잠깐... 효과가 없군. 뭣 때문인지 그녀는 매우 화가 났어... 조심하게.', 28153),
