(145340, 'koKR', '자금이 부족합니다.', '', 28153),
(145339, 'koKR', '형편이 안 됩니다.', '', 28153),
(145338, 'koKR', '돈이 모자랍니다.', '', 28153),
(145337, 'koKR', '파티에 들어올 수 없습니다.', '', 28153),
