(145332, 'koKR', '마나가 별로 없습니다.', '', 28153),
(145331, 'koKR', '마나가 있어야 합니다.', '', 28153),
(145330, 'koKR', '분노가 부족합니다.', '', 28153),
(145329, 'koKR', '분노가 더 필요합니다.', '', 28153),
(145328, 'koKR', '너무 멀리 있습니다.', '', 28153),
(145327, 'koKR', '사정거리에서 벗어났습니다.', '', 28153),
(145326, 'koKR', '좀 더 가까이 가야 합니다.', '', 28153),
(145325, 'koKR', '더는 초대할 수 없습니다.', '', 28153),
(145324, 'koKR', '지금은 마실 수 없습니다.', '', 28153),
(145323, 'koKR', '아직 배우지 못했습니다.', '', 28153),
(145322, 'koKR', '아직 사용할 수 없습니다.', '', 28153),
(145321, 'koKR', '아직 주문을 외울 수 없습니다.', '', 28153),
(145320, 'koKR', '조금 더 기다려야 합니다.', '', 28153),
(145319, 'koKR', '아직 준비되지 않았습니다.', '', 28153),
(145318, 'koKR', '맞춰보십시오.\n\n내가 갖고 있으면 함께 나눌 수 없는 것. 함께 나누면 내가 갖지 못하는 것. 그것은 무엇입니까?', '', 28153),
(145317, 'koKR', '이놈을 쓰러뜨려야 합니다!', '', 28153),
(145316, 'koKR', '대상을 처치해야 합니다!', '', 28153),
(145315, 'koKR', '이 적을 집중 공격하십시오!', '', 28153),
(145314, 'koKR', '전투 준비!', '', 28153),
(145313, 'koKR', '여왕님을 위하여!', '', 28153),
(145312, 'koKR', '산의 힘으로!', '', 28153),
(145311, 'koKR', '놈들을 쓰러뜨립시다!', '', 28153),
(145310, 'koKR', '놈들을 물리칩시다!', '', 28153),
(145309, 'koKR', '물러나야 합니다!', '', 28153),
(145308, 'koKR', '당신을 향한 낯선 시선이 느껴집니다. 아주... 의기양양한 시선입니다.', '당신을 향한 낯선 시선이 느껴집니다. 아주... 의기양양한 시선입니다.', 28153),
(145307, 'koKR', '전원, 퇴각!', '', 28153),
(145306, 'koKR', '여기서 나가십시오!', '', 28153),
(145305, 'koKR', '이쪽입니다.', '', 28153),
(145304, 'koKR', '제가 앞장서지요.', '', 28153),
(145303, 'koKR', '따라오십시오.', '', 28153),
(145302, 'koKR', '정말 또 있는 겁니까?', '정말 또 있는 겁니까?', 28153),
(145301, 'koKR', '준비됐습니다!', '준비됐습니다!', 28153),
(145300, 'koKR', '쉽지 않은 놈들이야말로 큰 즐거움을 주는 사냥감이지. 간다!', '', 28153),
(145299, 'koKR', '정답입니다!\n\n다음 문제 준비되셨습니까?', '', 28153),
(145298, 'koKR', '얼라이언스를 위하여!', '', 28153),
(145297, 'koKR', '상처가 깊습니다!', '', 28153),
(145296, 'koKR', '치유가 필요합니다!', '', 28153),
(145295, 'koKR', '도움이 필요합니다!', '', 28153),
(145294, 'koKR', '도와주십시오!', '', 28153),
(145293, 'koKR', '위험이 다가옵니다!', '', 28153),
(145292, 'koKR', '봐주지 마십시오!', '', 28153),
(145291, 'koKR', '공격 개시!', '', 28153),
(145290, 'koKR', '여기 계십시오.', '', 28153),
(145289, 'koKR', '꼼짝 말고 계십시오.', '', 28153),
(145288, 'koKR', '식충식물입니다.', '식충식물입니다.', 28153),
(145287, 'koKR', '', '마나를 채워야겠습니다!', 28153),
(145286, 'koKR', '', '마나를 회복해야 합니다.', 28153),
(145285, 'koKR', '물고기입니다.', '물고기입니다.', 28153),
(145283, 'koKR', '한 번 더 해보겠습니다.', '한 번 더 해보겠습니다.', 28153),
(145282, 'koKR', '아닙니다!\n\n다시 하시겠습니까?', '', 28153),
(145281, 'koKR', '판다렌입니다.', '판다렌입니다.', 28153),
(145280, 'koKR', '불입니다.', '불입니다.', 28153),
(145279, 'koKR', '맞춰보십시오.\n\n나는 마시면 죽고, 먹으면 삽니다. 나는 무엇일까요?', '', 28153),
(145278, 'koKR', '준비됐습니다!', '준비됐습니다!', 28153),
(145277, 'koKR', '정확합니다!\n\n다음 문제 준비되셨습니까?', '', 28153),
(145276, 'koKR', '어둠이 우우나를 삼켜 버립니다.', '어둠이 우우나를 삼켜 버립니다.', 28153),
(145275, 'koKR', '', '으아아악! 안 돼! 도와줘!', 28153),
(145273, 'koKR', '', '우렁찬 음성이 울리며 당신을 불안하게 합니다.', 28153),
(145272, 'koKR', '', '이렇게 간청합니다!', 28153),
(145271, 'koKR', '', '친절을 베풀어 주십시오.', 28153),
(145270, 'koKR', '', '부디 온정을!', 28153),
(145269, 'koKR', '', '아주 좋군요.', 28153),
(145268, 'koKR', '', '감탄했습니다.', 28153),
(145267, 'koKR', '', '훌륭하군요.', 28153),
(145266, 'koKR', '', '하지만... 아직은 아냐.', 28153),
(145265, 'koKR', '', '언젠가는 나도 엄마랑 아빠 곁으로 가야겠지.', 28153),
(145264, 'koKR', '', '가열로가 당신의 앞길을 비추기를.', 28153),
(145263, 'koKR', '', '덕분에 멋진 걸 많이 봤어. 넌 정말 최고의 친구야!', 28153),
(145262, 'koKR', '', '볼 일은 끝났습니다.', 28153),
(145261, 'koKR', '', '네가 한 짓에 대해 대가를 치를 것이다!', 28153),
(145260, 'koKR', '', '가십시오!', 28153),
(145259, 'koKR', '', '안녕히.', 28153),
(145258, 'koKR', '', '이걸 다 보여 줘서 너무너무 고마워, 친구야!', 28153),
(145257, 'koKR', '', '모두 아르거스에서 죽은 게 아니었어?', 28153),
(145256, 'koKR', '', '우리 종족이다! 살아남은 거구나!', 28153),
(145255, 'koKR', '', '너무... 아름다워...', 28153),
(145254, 'koKR', '', '좀 우스꽝스러운 것 같아, 친구야.', 28153),
(145253, 'koKR', '', '근데 물 같이 흐르고 있어... 반짝이는 호수인걸까?', 28153),
(145252, 'koKR', '', '용건을 말하십시오.', 28153),
(145251, 'koKR', '다시 하겠습니다.', '다시 하겠습니다.', 28153),
(145250, 'koKR', '틀렸습니다!\n\n다시 하시겠습니까?', '', 28153),
(145249, 'koKR', '로아입니다.', '로아입니다.', 28153),
(145248, 'koKR', '양초입니다.', '양초입니다.', 28153),
(145247, 'koKR', '', '아래를 좀 봐. 다 반짝이고 있어!', 28153),
(145246, 'koKR', '', '여긴 어디지? 왜 이렇게 연기가 가득해?', 28153),
(145245, 'koKR', '', '그러니까 조심해, 알겠지?', 28153),
(145244, 'koKR', '나무입니다.', '나무입니다.', 28153),
(145243, 'koKR', '', '떨어지지 않게 조심해! 나야 떨어져도 괜찮지만, 넌 납작해질 거야!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145242, 'koKR', '', '안녕하십니까.', 28153),
(145241, 'koKR', '', '산이 이렇게 높을 수 있는지 몰랐어!', 28153),
(145240, 'koKR', '', '여기서는 모든 게 다 보이네!', 28153),
(145239, 'koKR', '', '만나서 반갑습니다.', 28153),
(145238, 'koKR', '', '반갑습니다.', 28153),
(145237, 'koKR', '', '깍 깍 깍 깍 깍!', 28153),
(145236, 'koKR', '', '아닙니다.', 28153),
(145235, 'koKR', '', '아니요.', 28153),
(145234, 'koKR', '', '절대 안 됩니다.', 28153),
(145233, 'koKR', '', '그렇습니다.', 28153),
(145232, 'koKR', '', '네에.', 28153),
(145231, 'koKR', '', '넵.', 28153),
(145230, 'koKR', '', '정말 고맙습니다.', 28153),
(145229, 'koKR', '', '감사를 받아 주십시오.', 28153),
(145228, 'koKR', '노움입니다.', '노움입니다.', 28153),
(145227, 'koKR', '', '제가 빚을 졌군요.', 28153),
(145226, 'koKR', '', '맙소사, 검은 모루여!', 28153),
(145225, 'koKR', '', '한... 열 마리!', 28153),
(145224, 'koKR', '', '고작 그 정도냐?', 28153),
(145222, 'koKR', '', '때려 주겠어!', 28153),
(145221, 'koKR', '', '얼마나 많은 새가 저 나무에 살고 있을까. 엄청 많이 살겠지!', 28153),
(145220, 'koKR', '맞춰보십시오.\n\n나는 젊을 때 크고, 나이가 들면 작아집니다. 나는 무엇일까요?', '', 28153),
(145219, 'koKR', '', '좋아서 한 일입니다.', 28153),
(145218, 'koKR', '', '친구야, 봐! 우린 지금 거대한 나무 아래에 있어!', 28153),
(145217, 'koKR', '', '도움이 되어 기쁩니다.', 28153),
(145216, 'koKR', '', '별말씀을요.', 28153),
(145215, 'koKR', '해 봅시다.', '해 봅시다.', 28153),
(145214, 'koKR', '당신의 추리 능력을 시험해볼 준비가 됐습니까?', '', 28153),
(145213, 'koKR', '', '하나 애완동물로 길러도 돼?', 28153),
(145212, 'koKR', '', '도마뱀 같은 새긴 하지만.', 28153),
(145211, 'koKR', '', '정말 커다란 탑이야. 마치... 거대한 새집 같아!', 28153),
(145210, 'koKR', '', '와, 저 날아다니는 건 뭐지? 너무 예쁘다!', 28153),
(145209, 'koKR', '', '생각해 보니... 네가 어디 살기는 해?', 28153),
(145208, 'koKR', '', '넌 여기 살아?', 28153),
(145207, 'koKR', '', '그게 어떻게 가능해?', 28153),
(145206, 'koKR', '', '와... 날아다니는 도시라니! 그게 정말이야?!', 28153),
(145205, 'koKR', '', '나랑 공주님 놀이 할래?', 28153),
(145204, 'koKR', '', '누가 여기 사는지 알아? 공주님이 살 것 같아.', 28153),
(145203, 'koKR', '', '우와! 세상에서 가장 아름다운 집이야!', 28153),
(145202, 'koKR', '', '으으으으으!!', 28153),
(145201, 'koKR', '', '저거 벌레야? 벌레 같아. 으웩! 난 벌레가 너무 싫어!', 28153),
(145200, 'koKR', '', '이걸 만든 사람들은 뭘 막아 내려고 했던 걸까?', 28153),
(145199, 'koKR', '', '우와! 태어나서 이렇게 커다란 장벽은 처음 봐!', 28153),
(145197, 'koKR', '', '우우나가 당신을 껴안습니다.', 28153),
(145196, 'koKR', '너 장화 못 가져간다!', '', 28153),
(145195, 'koKR', '', '좋아, 친구야. 이곳을 빠져나가자! 우린 갈 곳이 너무나도 많아!', 28153),
(145194, 'koKR', '', '엄마 아빠한테 내가 그리워한다고 전해 줘... 그리고 곧 보러 갈 거라고도!', 28153),
(145193, 'koKR', '', '친구야! 빛이 나한테 더 있어도 된대! 우와!', 28153),
(145192, 'koKR', '', '친구랑 조금 더 있어도 될까요? 아주 조금만 더 같이 있으면 안 돼요?', 28153),
(145191, 'koKR', '', '저는 아직 못 해 본 일이 많아요. 아직 한 번도 안 가 본 곳도 많고요...', 28153),
(145190, 'koKR', '', '잠깐 기다려요...', 28153),
(145189, 'koKR', '', '엄마! 아빠! 부모님이 날 기다리고 있어!', 28153),
(145188, 'koKR', '', '빛이... 나한테 따라오라고 하고 있어...', 28153),
(145187, 'koKR', '', '무슨... 무슨 일이지?', 28153),
(145186, 'koKR', '', '아, 친구야! 우리가 해냈어! 우리가 이겼어!', 28153),
(145185, 'koKR', '', '어둠이 사라졌어! 이제 보인다!', 28153),
(145184, 'koKR', '', '네가 한 짓의 대가를 치를 것이다!', 28153),
(145183, 'koKR', '망할 것. 망할 것! 난 아직 안 끝났는데...', '', 28153),
(145182, 'koKR', '밴시 여왕님께서 네 죽음을 기뻐하시리라!', '', 28153),
(145181, 'koKR', '더러운 얼라이언스 놈! 어둠의 여왕께 네 머리를 바치겠다!', '', 28153),
(145180, 'koKR', '', '네 목을 그어주마, $n!', 28153),
(145179, 'koKR', '격렬한 말발굽 소리가 멀리서 들립니다. 무언가 오고 있습니다.', '격렬한 말발굽 소리가 멀리서 들립니다. 무언가 오고 있습니다.', 28153),
(145178, 'koKR', '', '감히 날 방해하다니. 대가는 목숨으로 치뤄라, $n!', 28153),
(145177, 'koKR', '', '널 지켜보고 있었다, $n.', 28153),
(145176, 'koKR', '노릇노릇하게 튀겨 주마! 호드를 위하여!', '', 28153),
(145175, 'koKR', '공기가 타기 시작하면 오존 냄새가 날 걸세.', '공기가 타기 시작하면 오존 냄새가 날 걸세.', 28153),
(145173, 'koKR', '', '건방지군. 하지만 내게는 마법만 있는 게 아니다.', 28153),
(145172, 'koKR', '준비됐습니다. 의식을 시작하죠.', '준비됐습니다. 의식을 시작하죠.', 28153),
(145171, 'koKR', '내 발을 디딘 이 세상의 울음소리가 들리네. 아제로스가 고통에 몸부림치고 있어! 이 고통을 잠재울 방법을 찾아야 해...', '', 28153),
(145170, 'koKR', '', '난 그렇게 쉽게 죽지 않는다, $n. 내 분노로 고통받으리라!', 28153),
(145169, 'koKR', '', '마침내 찾았다, $n.', 28153),
(145168, 'koKR', '머리통을 박살 내 주마!', '', 28153),
(145167, 'koKR', '뼈에서 살점을 분리해주마!', '', 28153),
(145166, 'koKR', '내가 영원히 네놈 무덤을 지켜봐 주마.', '', 28153),
(145165, 'koKR', '내 모든 희망이 사라졌구나.', '', 28153),
(145164, 'koKR', '망할. 또 죽는 건가.', '', 28153),
(145163, 'koKR', '네놈이 한 짓을 후회하게 해주마.', '', 28153),
(145162, 'koKR', '네 생명력을 흡수해 주마.', '', 28153),
(145161, 'koKR', '나는 금속이 맞부딪치는 소리와 공포의 냄새를 즐기지.', '', 28153),
(145160, 'koKR', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t |cFFF00000|Hspell:260953|h[강철의 시선]|h|r이 당신을 응시합니다!', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t |cFFF00000|Hspell:257459|h[갈고리 걸기]|h|r의 대상이 되었습니다!', 28153),
(145159, 'koKR', '', '이제 무섭지 않아!', 28153),
(145158, 'koKR', '', '내 빛은 엄청 강해!', 28153),
(145157, 'koKR', '집에 가고 싶군.', '', 28153),
(145156, 'koKR', '', '그리고 빛이 나랑 함께라면, 어둠은 절대 이기지 못해!', 28153),
(145155, 'koKR', '', '엄마가 그랬어! 빛은 언제나 날 찾을 수 있다고! 그게 너야, 친구야. 넌 내 빛이야!', 28153),
(145154, 'koKR', '', '친구야, 여기 있구나! 날 버리지 않았어!', 28153),
(145153, 'koKR', '안 돼... 안 돼...', '안 돼... 안 돼...', 28153),
(145152, 'koKR', '어둠의 여왕이시여... 실패했습니다...', '어둠의 여왕이시여... 실패했습니다...', 28153),
(145151, 'koKR', '나는 저 토템 기둥 제일 밑바닥이 되겠지.', '', 28153),
(145150, 'koKR', '마침내...', '마침내...', 28153),
(145149, 'koKR', '아니... 또 죽다니...', '아니... 또 죽다니...', 28153),
(145148, 'koKR', '어둠의 여왕을 위하여!', '어둠의 여왕을 위하여!', 28153),
(145147, 'koKR', '희망 따윈 버려라!', '희망 따윈 버려라!', 28153),
(145146, 'koKR', '죽음이 무엇인지 너도 느끼게 해주마!', '죽음이 무엇인지 너도 느끼게 해주마!', 28153),
(145145, 'koKR', '네 뼈로 잔치를 벌이겠다!', '네 뼈로 잔치를 벌이겠다!', 28153),
(145144, 'koKR', '산 자에게 죽음을!', '산 자에게 죽음을!', 28153),
(145143, 'koKR', '실바나스 님을 위하여!', '실바나스 님을 위하여!', 28153),
(145142, 'koKR', '', '우우나가 팔로 자신을 감싸며 울기 시작합니다.', 28153),
