(144078, 'koKR', '프라우드무어는 무너지리라!', '프라우드무어는 무너지리라!', 28153),
(144077, 'koKR', '내 죽음이 파도의 방향을 바꾸진 못한다.', '내 죽음이 파도의 방향을 바꾸진 못한다.', 28153),
(144076, 'koKR', '후회하게 해 주마!', '후회하게 해 주마!', 28153),
