(140268, 'koKR', '', '도움이 되어 기쁩니다.', 28153),
(140267, 'koKR', '', '틀림없습니다.', 28153),
(140266, 'koKR', '틀림없습니다.', '', 28153),
(140265, 'koKR', '그렇습니다.', '', 28153),
(140264, 'koKR', '볼둔에서 처음으로 목을 축이는군요. 공격을 받은 뒤 모래 언덕에서 길을 잃었거든요.', '', 28153),
(140263, 'koKR', '', '그렇습니다.', 28153),
(140262, 'koKR', '여기서 뭐 하십니까, $p 님? 죽은 줄 알았습니다!', '', 28153),
(140261, 'koKR', '알겠습니다.', '', 28153),
(140260, 'koKR', '', '알겠습니다.', 28153),
