(140258, 'koKR', '두말할 것도 없지요.', '', 28153),
(140257, 'koKR', '여기서 기다리십시오.', '', 28153),
(140256, 'koKR', '', '여기서 기다리십시오.', 28153),
(140255, 'koKR', '', '자리를 지키십시오.', 28153),
(140254, 'koKR', '자리를 지키십시오.', '', 28153),
(140253, 'koKR', '여기서 기다리십시오.', '', 28153),
(140252, 'koKR', '', '여기서 기다리십시오.', 28153),
(140251, 'koKR', '', '여기서 대기하십시오.', 28153),
(140250, 'koKR', '여기서 대기하십시오.', '', 28153),
(140249, 'koKR', '정말 자상하시군요.', '', 28153),
(140248, 'koKR', '', '정말 자상하시군요.', 28153),
(140247, 'koKR', '', '제 주먹이 아주 날쌔다고 생각하신다면 제 자매 녹시를 아직 못 보셔서 그래요. 그 주먹에 한 대 맞으면 별을 보게 되실 거예요.', 28153),
(140246, 'koKR', '', '신세를 졌습니다.', 28153),
