(159157, 'ptBR', 'As brumas levarão você!', 'As brumas levarão você!', 28153),
(159156, 'ptBR', 'Você jamais dominará os mares...', 'Você jamais dominará os mares...', 28153),
(159155, 'ptBR', 'Um morre, restam milhares...', 'Um morre, restam milhares...', 28153),
(159154, 'ptBR', 'Não pense que venceu...', 'Não pense que venceu...', 28153),
