(159149, 'ptBR', 'Minha rainha...', 'Minha rainha...', 28153),
(159148, 'ptBR', 'O deus abissal espera por você, retorcendo-se de ansiedade!', 'O deus abissal espera por você, retorcendo-se de ansiedade!', 28153),
(159147, 'ptBR', 'Os olhos das profundezas levarão você à insanidade!', 'Os olhos das profundezas levarão você à insanidade!', 28153),
