(159109, 'ptBR', 'O sangue do planeta está sob nossa guarda.', 'O sangue do planeta está sob nossa guarda.', 28153),
(159108, 'ptBR', 'Pelo menos eu morri rico...', 'Pelo menos eu morri rica...', 28153),
(159107, 'ptBR', 'Diga aos meus filhos... que não vão ficar com meu dinheiro...', 'Diga aos meus filhos... que não vão ficar com meu dinheiro...', 28153),
(159106, 'ptBR', 'Lembrem-se de mim... e dos meus lucros trimestrais...', 'Lembrem-se de mim... e dos meus lucros trimestrais...', 28153),
(159105, 'ptBR', 'Espera! Eu pago pra você me reviver! Qual é!', 'Espera! Eu pago pra você me reviver! Qual é!', 28153),
(159104, 'ptBR', 'Uff! Auditoria...', 'Uff! Auditoria...', 28153),
(159103, 'ptBR', 'Espero... que isso não afete... minha aposentadoria...', 'Espero... que isso não afete... minha aposentadoria...', 28153),
(159102, 'ptBR', 'Já estamos no vermelho!', 'Já estamos no vermelho!', 28153),
(159101, 'ptBR', 'Crash na bolsa... de valores...', 'Crash na bolsa... de valores...', 28153),
(159100, 'ptBR', 'Preparem-se para descontar o cheque!', 'Preparem-se para descontar o cheque!', 28153),
(159099, 'ptBR', 'Se não matarmos eles, o prejuízo vai ser descontado da verba do café!', 'Se não matarmos eles, o prejuízo vai ser descontado da verba do café!', 28153),
(159098, 'ptBR', 'Eu vou ganhar um bônus incrível por entregar a sua cabeça!', 'Eu vou ganhar um bônus incrível por entregar a sua cabeça!', 28153),
