(159085, 'ptBR', 'Argh! Intrusos! Alguém me acuda!', 'Argh! Intrusos! Alguém me acuda!', 28153),
(159084, 'ptBR', 'Peguem eles! Mas usem o material barato!', 'Peguem eles! Mas usem o material barato!', 28153),
