(159082, 'ptBR', 'Dar 20 bolas de Sorvete de Morango de Tigule e Foror para Maria Dalmora?', 'Dar 20 bolas de Sorvete de Morango de Tigule e Foror para Maria Dalmora?', 28153),
(159081, 'ptBR', '', 'Umbric e eu vamos na frente para fazer os preparativos do ataque surpresa ao Porto de Guerra.', 28153),
