(159045, 'ptBR', 'Criaturas insignificantes de carne! Proteger o sangue dourado do mundo é nossa missão!', 'Criaturas insignificantes de carne! Proteger o sangue dourado do mundo é nossa missão!', 28153),
(159044, 'ptBR', 'O mundo foi dado aos dragões. Sua espécie é uma doença!', 'O mundo foi dado aos dragões. Sua espécie é uma doença!', 28153),
(159043, 'ptBR', 'Como se atreve a tomar o que é nosso por direito?', 'Como se atreve a tomar o que é nosso por direito?', 28153),
(159042, 'ptBR', 'O sangue do mundo é nossa responsabilidade! Somos os guardiões!', 'O sangue do mundo é nossa responsabilidade! Somos os guardiões!', 28153),
(159041, 'ptBR', 'Você rouba... o que é nosso por direito...', 'Você rouba... o que é nosso por direito...', 28153),
(159040, 'ptBR', 'Não seremos perdidos para a história...', 'Não seremos perdidos para a história...', 28153),
(159039, 'ptBR', 'A revoada negra está no seu encalço...', 'A revoada negra está no seu encalço...', 28153),
(159038, 'ptBR', 'Você não vencerá esta guerra...', 'Você não vencerá esta guerra...', 28153),
(159037, 'ptBR', 'Esse mundo pertence... aos dragões...', 'Esse mundo pertence... aos dragões...', 28153),
(159036, 'ptBR', 'Sua espécie... não é bem-vinda...', 'Sua espécie... não é bem-vinda...', 28153),
(159035, 'ptBR', 'Não há como derrotar a revoada negra...', 'Não há como derrotar a revoada negra...', 28153),
(159034, 'ptBR', 'Nós... voltaremos...', 'Nós... voltaremos...', 28153),
(159033, 'ptBR', 'A revoada negra renascerá!', 'A revoada negra renascerá!', 28153),
(159032, 'ptBR', 'Sua espécie será expurgada!', 'Sua espécie será expurgada!', 28153),
(159031, 'ptBR', 'Fogo e morte são nossa dádiva!', 'Fogo e morte são nossa dádiva!', 28153),
(159030, 'ptBR', 'Você ousa desafiar uma revoada dragônica?', 'Você ousa desafiar uma revoada dragônica?', 28153),
(159029, 'ptBR', 'A revoada negra se reerguerá!', 'A revoada negra se reerguerá!', 28153),
(159028, 'ptBR', 'Glória à revoada negra!', 'Glória à revoada negra!', 28153),
(159027, 'ptBR', 'Pelos guardiões da terra!', 'Pelos guardiões da terra!', 28153),
(159026, 'ptBR', 'Eu defenderei a revoada!', 'Eu defenderei a revoada!', 28153),
(159025, 'ptBR', 'Por você... imperatriz...', 'Por você... imperatriz...', 28153),
(159024, 'ptBR', 'Você esmaga um... muitos mais surgem no lugar...', 'Você esmaga um... muitos mais surgem no lugar...', 28153),
(159023, 'ptBR', 'Levem o ouro... para a imperatriz...', 'Levem o ouro... para a imperatriz...', 28153),
(159022, 'ptBR', 'O chamado dela... é música...', 'O chamado dela... é música...', 28153),
(159021, 'ptBR', 'Eu a ouço... mesmo morrendo...', 'Eu a ouço... mesmo morrendo...', 28153),
(159020, 'ptBR', 'A canção da imperatriz... desvanece...', 'A canção da imperatriz... desvanece...', 28153),
(159019, 'ptBR', 'Somos... milhares... você não nos deterá...', 'Somos... milhares... você não nos deterá...', 28153),
(159018, 'ptBR', 'Kshh... Eu morro...', 'Kshh... Eu morro...', 28153),
(159017, 'ptBR', 'Eu matarei você e darei seu cadáver para alimentar o enxame!', 'Eu matarei você e darei seu cadáver para alimentar o enxame!', 28153),
(159016, 'ptBR', 'Você busca tanto assim a sua destruição?', 'Você busca tanto assim a sua destruição?', 28153),
(159015, 'ptBR', 'O minério de ouro é nosso! Presente para a imperatriz!', 'O minério de ouro é nosso! Presente para a imperatriz!', 28153),
(159014, 'ptBR', 'O enxame serve à imperatriz!', 'O enxame serve à imperatriz!', 28153),
(159013, 'ptBR', 'O enxame não pode ser detido!', 'O enxame não pode ser detido!', 28153),
(159012, 'ptBR', 'A doce canção da nossa imperatriz exige a sua morte!', 'A doce canção da nossa imperatriz exige a sua morte!', 28153),
(159011, 'ptBR', 'Sigo a ordem da imperatriz!', 'Sigo a ordem da imperatriz!', 28153),
(159010, 'ptBR', 'Pela imperatriz!', 'Pela imperatriz!', 28153),
(159009, 'ptBR', 'A Aliança resistirá... e o reinado perverso da Rainha Banshee terá um fim.', '', 28153),
(159008, 'ptBR', 'Ela acha que essa atrocidade vai nos desiludir. Que vai romper nossa união. Mas isto eu juro...', '', 28153),
(159007, 'ptBR', 'Rargh! Um golpe justo...', 'Rargh! Um golpe justo...', 28153),
(159006, 'ptBR', 'Argh! Esta é a morte que eu queria!', 'Argh! Esta é a morte que eu queria!', 28153),
(159005, 'ptBR', 'Mas esse sonho jamais se realizará enquanto Sylvana Correventos liderar a Horda.', '', 28153),
(159004, 'ptBR', 'Estou zarpando... para o crepúsculo...', 'Estou zarpando... para o crepúsculo...', 28153),
(159003, 'ptBR', 'Minha vida inteira, eu rezei pedindo paz no mundo.', '', 28153),
(159002, 'ptBR', 'Eu tomarei meu assento entre os guerreiros da antiguidade...', 'Eu tomarei meu assento entre os guerreiros da antiguidade...', 28153),
(159001, 'ptBR', 'Você mostrou que tem coragem, camarada. Justo agora, nestes tempos tão difíceis para a Aliança.', '', 28153),
(159000, 'ptBR', 'Os espíritos abençoam minha passagem para o além-vida...', 'Os espíritos abençoam minha passagem para o além-vida...', 28153),
(158999, 'ptBR', '', 'Descanse enquanto pode. Prepare-se para as batalhas adiante. Eu precisarei de você.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158998, 'ptBR', 'Eu morro numa batalha gloriosa!', 'Eu morro numa batalha gloriosa!', 28153),
(158997, 'ptBR', 'O clã me vingará...', 'O clã me vingará...', 28153),
(158996, 'ptBR', '', 'Mas eles estão sangrando. A raiva será o ponto fraco, e não a força deles, na guerra por vir.', 28153),
(158995, 'ptBR', 'A morte chegou para você...', 'A morte chegou para você...', 28153),
(158994, 'ptBR', 'Mais um fracote para derrotar!', 'Mais um fracote para derrotar!', 28153),
(158993, 'ptBR', 'Mais uma gloriosa batalha!', 'Mais uma gloriosa batalha!', 28153),
(158992, 'ptBR', 'Eu arrancarei seus olhos!', 'Eu arrancarei seus olhos!', 28153),
(158991, 'ptBR', '', 'Nós alcançamos o objetivo em partes. A Aliança vai dar o troco. Eles virão atrás de nós. De mim. De você.', 28153),
(158990, 'ptBR', '', 'A intenção do ataque era pôr fim na guerra antes que ela começasse... destruir a casa e os líderes do inimigo num golpe só. Abrir uma ferida que sangrasse a Aliança até secar.', 28153),
(158989, 'ptBR', '', 'Quando lhe dei a missão, não imaginava este resultado.', 28153),
(158988, 'ptBR', 'As mil naus velejam à sua ruína!', 'As mil naus velejam à sua ruína!', 28153),
(158987, 'ptBR', 'Minha vida por Jorun!', 'Minha vida por Jorun!', 28153),
(158986, 'ptBR', 'Pelos Trilhassangue!', 'Pelos Trilhassangue!', 28153),
(158985, 'ptBR', 'Morra com honra!', 'Morra com honra!', 28153),
(158984, 'ptBR', 'Vou devorar seu coração!', 'Vou devorar seu coração!', 28153),
(158983, 'ptBR', 'Mrglrggg...', 'Mrglrggg...', 28153),
(158982, 'ptBR', 'Mrrg mrgl?', 'Mrrg mrgl?', 28153),
(158981, 'ptBR', 'Rgll mgrgl... rgl...', 'Rgll mgrgl... rgl...', 28153),
(158980, 'ptBR', 'Grgl...', 'Grgl...', 28153),
(158979, 'ptBR', 'Mrg!', 'Mrg!', 28153),
(158978, 'ptBR', 'Rgl... mrg...', 'Rgl... mrg...', 28153),
(158977, 'ptBR', 'Mrrrmgrl!', 'Mrrrmgrl!', 28153),
(158976, 'ptBR', 'Mrglrgl? Mrg! Rgl!', 'Mrglrgl? Mrg! Rgl!', 28153),
(158975, 'ptBR', 'Rgrml grml grml!', 'Rgrml grml grml!', 28153),
(158974, 'ptBR', '', 'Minha nossa! Perfeito! Eu agradeço muito, $p. Você é um amor. Tome, leve uns biscoitos.', 28153),
(158973, 'ptBR', 'Mrg? Grml?!', 'Mrg? Grml?!', 28153),
(158972, 'ptBR', 'Mrgl? Rgl!', 'Mrgl? Rgl!', 28153),
(158971, 'ptBR', 'Mrglrglrgl!', 'Mrglrglrgl!', 28153),
(158970, 'ptBR', 'A morte não significa nada para o caos infinito...', 'A morte não significa nada para o caos infinito...', 28153),
(158969, 'ptBR', 'Contemple o ressurgimento dele...', 'Contemple o ressurgimento dele...', 28153),
(158968, 'ptBR', 'Sua ruína virá das profundezas...', 'Sua ruína virá das profundezas...', 28153),
(158967, 'ptBR', 'É impossível nos destruir... somos infindáveis...', 'É impossível nos destruir... somos infindáveis...', 28153),
(158966, 'ptBR', 'Você sucumbirá... Seus aliados abandonarão você...', 'Você sucumbirá... Seus aliados abandonarão você...', 28153),
(158965, 'ptBR', 'Está ouvindo o chamado da escuridão profunda?', 'Está ouvindo o chamado da escuridão profunda?', 28153),
(158964, 'ptBR', 'Não há como conter as profundezas da insanidade!', 'Não há como conter as profundezas da insanidade!', 28153),
(158963, 'ptBR', 'Do meu cadáver nascerão outros milhares.', 'Do meu cadáver nascerão outros milhares.', 28153),
(158962, 'ptBR', 'As trevas contorcidas toam o sino final.', 'As trevas contorcidas toam o sino final.', 28153),
(158961, 'ptBR', 'O devorador das profundezas anseia por devorar seu mundo!', 'O devorador das profundezas anseia por devorar seu mundo!', 28153),
(158960, 'ptBR', 'Você não tem como vencer aquilo que teme!', 'Você não tem como vencer aquilo que teme!', 28153),
(158959, 'ptBR', 'Nós nos espalharemos pelo seu mundo até restar apenas medo e olhos.', 'Nós nos espalharemos pelo seu mundo até restar apenas medo e olhos.', 28153),
(158958, 'ptBR', 'As fossas abissais chamam você.', 'As fossas abissais chamam você.', 28153),
(158957, 'ptBR', 'Corra para as profundezas aos gritos!', 'Corra para as profundezas aos gritos!', 28153),
(158956, 'ptBR', 'Vamos consumir todos vocês!', 'Vamos consumir todos vocês!', 28153),
(158955, 'ptBR', 'Seu corpo alimentará a escuridão!', 'Seu corpo alimentará a escuridão!', 28153),
(158954, 'ptBR', 'Naufraguei...', 'Naufraguei...', 28153),
(158953, 'ptBR', 'É doce... morrer no mar...', 'É doce... morrer no mar...', 28153),
(158952, 'ptBR', 'Não vou... morrer assim...', 'Não vou... morrer assim...', 28153),
(158951, 'ptBR', 'Foi culpa... do navegador...', 'Foi culpa... do navegador...', 28153),
(158950, 'ptBR', 'Me salvem... seus cães...', 'Me salvem... seus cães...', 28153),
(158949, 'ptBR', 'Melhor morrer... do que perder a vida...', 'Melhor morrer... do que perder a vida...', 28153),
(158948, 'ptBR', 'A gente não devia... ter pisado aqui...', 'A gente não devia... ter pisado aqui...', 28153),
(158947, 'ptBR', 'Pior... tripulação... que já vi...', 'Pior... tripulação... que já vi...', 28153),
(158946, 'ptBR', 'Esse navio agora é nosso, cães sarnentos!', 'Esse navio agora é nosso, cães sarnentos!', 28153),
(158945, 'ptBR', 'Olhem só, rapazes! Trouxeram um tesouro pra gente. E um jeito de cair fora daqui!', 'Olhem só, rapazes! Trouxeram um tesouro pra gente. E um jeito de cair fora daqui!', 28153),
(158944, 'ptBR', 'Eles têm um navio! Peguem eles!', 'Eles têm um navio! Peguem eles!', 28153),
(158943, 'ptBR', 'Tu vai se arrepender de ter vindo aqui!', 'Tu vai se arrepender de ter vindo aqui!', 28153),
(158942, 'ptBR', 'Arr, acho que tomei rum demais...', 'Arr, acho que tomei rum demais...', 28153),
(158941, 'ptBR', 'Estamos sendo atacados, seus cães! Todo mundo de pé!', 'Estamos sendo atacados, seus cães! Todo mundo de pé!', 28153),
(158940, 'ptBR', 'Não vieram pra salvar a gente. Peguem eles!', 'Não vieram pra salvar a gente. Peguem eles!', 28153),
(158939, 'ptBR', 'Iarr, a gente vai sair daqui agora mesmo, rapazes! Peguem eles!', 'Iarr, a gente vai sair daqui agora mesmo, rapazes! Peguem eles!', 28153),
(158938, 'ptBR', ' Volto às profundezas... uma morte de marinheiro...', ' Volto às profundezas... uma morte de marinheiro...', 28153),
(158937, 'ptBR', 'Gulp... me dá uma dose de rum antes de eu morrer...', 'Gulp... me dá uma dose de rum antes de eu morrer...', 28153),
(158936, 'ptBR', 'Tá ficando tudo escuro... aqui...', 'Tá ficando tudo escuro... aqui...', 28153),
(158935, 'ptBR', 'Urgh... Que golpe baixo...', 'Urgh... Que golpe baixo...', 28153),
(158934, 'ptBR', 'Para... o navio...', 'Para... o navio...', 28153),
(158933, 'ptBR', 'Argh! Bem nas tripas...', 'Argh! Bem nas tripas...', 28153),
(158932, 'ptBR', 'Tu nunca vai achar... meu butim...', 'Tu nunca vai achar... meu butim...', 28153),
(158931, 'ptBR', 'Arr... meu tesouro...', 'Arr... meu tesouro...', 28153),
(158930, 'ptBR', 'Me defendam, seus broncos inúteis!', 'Me defendam, seus broncos inúteis!', 28153),
(158929, 'ptBR', 'A mim, cães sarnentos! Tem invasores aqui!', 'A mim, cães sarnentos! Tem invasores aqui!', 28153),
(158928, 'ptBR', 'Tu não devia ter vindo pra essas bandas. Aqui é terra de pirata!', 'Tu não devia ter vindo pra essas bandas. Aqui é terra de pirata!', 28153),
(158927, 'ptBR', 'Arr, há invasores entre nós, meus marujos!', 'Arr, há invasores entre nós, meus marujos!', 28153),
(158926, 'ptBR', 'Saque e pilhagem, iarr!', 'Saque e pilhagem, iarr!', 28153),
(158925, 'ptBR', 'Você está pedindo um alfanje nas tripas!', 'Você está pedindo um alfanje nas tripas!', 28153),
(158924, 'ptBR', 'Você vai andar na prancha!', 'Você vai andar na prancha!', 28153),
(158923, 'ptBR', 'Basta, seus inúteis! Expulsem os invasores!', 'Basta, seus inúteis! Expulsem os invasores!', 28153),
(158922, 'ptBR', 'Nada ficará no caminho da caçada por Onoho!', '', 28153),
(158921, 'ptBR', 'O mar trouxe você para nosso usufruto. Você não pode partir...', '', 28153),
(158920, 'ptBR', 'Vamos aprimorar nossas habilidades enquanto aguardamos a orientação do mar!', '', 28153),
(158919, 'ptBR', 'As marés previram este encontro.', '', 28153),
(158918, 'ptBR', 'Você veio enfrentar o clã da Grande Caçada e ainda espera sair com vida?', '', 28153),
(158917, 'ptBR', 'O mar nos traz carne fresca e novas armas. Benditas sejam as ondas por mais esta graça!', '', 28153),
(158916, 'ptBR', 'Sua carne e seus suprimentos servirão de combustível à Grande Caçada. Agradecemos!', '', 28153),
(158915, 'ptBR', 'Nosso clã já caça o grandioso há muitos anos. Não é você que vai nos impedir!', '', 28153),
(158914, 'ptBR', 'Os baixios... me revelaram... esta sina...', '', 28153),
(158913, 'ptBR', 'As ondas... me levam...', '', 28153),
(158912, 'ptBR', 'A caçada... abate mais um...', '', 28153),
(158911, 'ptBR', 'Você também... sabe... caçar...', '', 28153),
(158910, 'ptBR', 'Ugh... golpe certeiro...', '', 28153),
(158909, 'ptBR', 'No fim, o mar engole a todos...', '', 28153),
(158908, 'ptBR', 'A caçada vai continuar... sem mim...', '', 28153),
(158907, 'ptBR', 'Não me arrependo... de nada...', '', 28153),
(158906, 'ptBR', 'Parece que forasteiros desaguaram na praia.', '', 28153),
(158905, 'ptBR', 'Agradecemos o seu sacrifício.', '', 28153),
(158904, 'ptBR', 'Tomem os suprimentos deles. Hoje teremos banquete!', '', 28153),
(158903, 'ptBR', 'Você ousa enfrentar nosso clã?', '', 28153),
(158902, 'ptBR', 'Seu sangue alimenta a caçada.', '', 28153),
(158901, 'ptBR', 'Seu cadáver nos alimentará. Agradecemos.', '', 28153),
(158900, 'ptBR', 'O mar nos deu novos suprimentos...', '', 28153),
(158899, 'ptBR', 'As ondas previram sua chegada.', '', 28153),
(158898, 'ptBR', '', 'Eu adoro essas criaturinhas que vivem por aqui. Coelhinhos, passarinhos, caranguejos... tudo que você puder imaginar. Eu tenho uns mascotes que foram treinados para serem campeões. Está vendo esta carcaça aqui? Meus mascotes fizeram isso em 4 minutos, batido. Gostam de comer. Quer ver eles em ação?', 28153),
(158897, 'ptBR', '', 'Fique de olho em Meerah, está bem? \n\nEla não enxerga os verdadeiros perigos do deserto. Não quero que ela acabe engolida pelas areias...', 28153),
(158896, 'ptBR', '', 'Seu amigo parece bem melhor. Fico feliz por Kiro e Meerah terem ajudado.', 28153),
(158895, 'ptBR', '', 'Bem-$Uvindo:vinda; ao nosso lar, $n... ao menos por enquanto. \n\nAs caravanas estão prontas para partir num instante, caso os sethraks encontrem nosso esconderijo.', 28153),
(158894, 'ptBR', 'Veja se consegue levar Loh até um lugar seguro, atravessando as algas no meio do caminho.', '', 28153),
(158893, 'ptBR', '', 'Certamente! Tome, leve umas bombas de farinha com você. Mas tenha cuidado com elas.', 28153),
(158892, 'ptBR', 'Quer trocar por carne de urso?', '', 28153),
(158891, 'ptBR', 'Kua\'fon sai em disparada!', '', 28153),
(158890, 'ptBR', 'Kua\'fon segura o crânio logo fora do alcance, balançando a cauda brincalhão.', '', 28153),
(158889, 'ptBR', 'Você não é lá... essas coisas.', '', 28153),
(158888, 'ptBR', 'Eu vou pegar o que eu quiser, então!', '', 28153),
(158887, 'ptBR', 'Gostei do seu equipamento... quer trocar?', '', 28153),
(158886, 'ptBR', 'Recuar... para a água...', '', 28153),
(158885, 'ptBR', 'O clã não morrerá... hoje...', '', 28153),
(158884, 'ptBR', 'Gurrr... como...?', '', 28153),
(158883, 'ptBR', 'Eu retorno... às ondas...', '', 28153),
(158882, 'ptBR', 'O tesouro... era meu...', '', 28153),
(158881, 'ptBR', 'Ssss... vocêsss vão pagar...', '', 28153),
(158880, 'ptBR', 'Hsss... ladrõessss....', '', 28153),
(158879, 'ptBR', 'Gahh... meu sangue...', '', 28153),
(158878, 'ptBR', 'Hssss! Matem elesss! Guardem o tesouro!', '', 28153),
(158877, 'ptBR', 'As gemas dão poderesss ao nosssso clã. Não nosss curvaremos a vocêss!', '', 28153),
(158876, 'ptBR', 'Vou me banquetear com sua carne e roer seus ossos!', '', 28153),
(158875, 'ptBR', 'Você ousssa desafiar um grande guerreiro?', '', 28153),
(158874, 'ptBR', 'Eu defendo o clã! Você vai morrer!', '', 28153),
(158873, 'ptBR', 'Intrusos! Matem elesss, meus lacaiosss!', '', 28153),
(158872, 'ptBR', 'Este tesouro pertence ao meu clã. Vocês são ladrõesss!', '', 28153),
(158871, 'ptBR', 'Meu clã é poderoso. Você não é capaz de nos deter!', '', 28153),
(158870, 'ptBR', 'Vou tentar encontrar para você.', 'Vou tentar encontrar para você.', 28153),
(158869, 'ptBR', 'Seu tesouro será nosso!', '', 28153),
(158868, 'ptBR', 'Eu trouxe sorvete para você!', 'Eu trouxe sorvete para você!', 28153),
(158867, 'ptBR', 'Vou estripar você feito um peixe!', '', 28153),
(158866, 'ptBR', 'Defendam o clã!', '', 28153),
(158865, 'ptBR', 'Ssssangrem! Tragam os tesouros deles!', '', 28153),
(158864, 'ptBR', 'Sss! Estão nos atacando!', '', 28153),
(158863, 'ptBR', 'Sangue quente!', '', 28153),
(158862, 'ptBR', 'Matem eles! Peguem os pertencesss!', '', 28153),
(158861, 'ptBR', 'Hssss! Asssasssinar você!', '', 28153),
(158860, 'ptBR', 'Mais alimento para minhas crianças!', 'Mais alimento para minhas crianças!', 28153),
(158859, 'ptBR', 'Claro. Em que posso ajudar?', 'Claro. Em que posso ajudar?', 28153),
(158858, 'ptBR', 'Hikkk-k-k! Mais um que cai em nossa toca. Sua jornada termina aqui...', 'Hikkk-k-k! Mais um que cai em nossa toca. Sua jornada termina aqui...', 28153),
(158857, 'ptBR', 'Carne deliciosa, vindo direto para nosso covil! Que maravilha.', 'Carne deliciosa, vindo direto para nosso covil! Que maravilha.', 28153),
(158856, 'ptBR', 'Seu sangue saciará os filhotes. Sua carne nutrirá as rainhas. E eu devorarei seu cérebro!', 'Seu sangue saciará os filhotes. Sua carne nutrirá as rainhas. E eu devorarei seu cérebro!', 28153),
(158855, 'ptBR', 'Você nunca encontrará os ovos. Nossa ninhada é eterna!', 'Você nunca encontrará os ovos. Nossa ninhada é eterna!', 28153),
(158854, 'ptBR', 'Não se debata, presa! Isso só prolonga sua dor!', 'Não se debata, presa! Isso só prolonga sua dor!', 28153),
(158853, 'ptBR', 'Ah, outra vítima cai em nossa teia... kshhh!', 'Ah, outra vítima cai em nossa teia... kshhh!', 28153),
(158852, 'ptBR', 'Defenderemos a ninhada até o fim!', 'Defenderemos a ninhada até o fim!', 28153),
(158851, 'ptBR', 'Cuidado... com os invasores...', 'Cuidado... com os invasores...', 28153),
(158850, 'ptBR', 'Os ovos... estão a salvo... de você...', 'Os ovos... estão a salvo... de você...', 28153),
(158849, 'ptBR', 'Você não vai achar... todos nós...', 'Você não vai achar... todos nós...', 28153),
(158848, 'ptBR', 'Eu não cheguei tão longe... para morrer pelas suas mãos...', 'Eu não cheguei tão longe... para morrer pelas suas mãos...', 28153),
(158847, 'ptBR', 'Meu corpo servirá de alimento para os filhotes...', 'Meu corpo servirá de alimento para os filhotes...', 28153),
(158846, 'ptBR', 'Ashhh... dor...', 'Ashhh... dor...', 28153),
(158845, 'ptBR', 'Defender... a ninhada...', 'Defender... a ninhada...', 28153),
(158844, 'ptBR', 'Kashhh...', 'Kashhh...', 28153),
(158843, 'ptBR', 'Os filhotes vão devorar sua carne!', 'Os filhotes vão devorar sua carne!', 28153),
(158842, 'ptBR', 'Hikkk-k-k... venha para minha teia!', 'Hikkk-k-k... venha para minha teia!', 28153),
(158841, 'ptBR', 'Invasores!', 'Invasores!', 28153),
(158840, 'ptBR', 'Vamos proteger a ninhada!', 'Vamos proteger a ninhada!', 28153),
(158839, 'ptBR', 'Hshhh... sangue fresco...', 'Hshhh... sangue fresco...', 28153),
(158838, 'ptBR', 'Apareceu uma presa...', 'Apareceu uma presa...', 28153),
(158837, 'ptBR', 'Você mexeu nas nossas teiasss!', 'Você mexeu nas nossas teiasss!', 28153),
(158836, 'ptBR', 'Kshhh... invasoresss...', 'Kshhh... invasoresss...', 28153),
(158835, 'ptBR', '', 'Bem, ultimamente eu ando querendo doces. Eu bem que queria um delicioso sorvete de morango! \n\nSe você conseguisse para mim, eu não sei nem como poderia agradecer. Se não for dar muito trabalho, traga um pouco mais para eu guardar. Espero que não seja muito incômodo!', 28153),
(158834, 'ptBR', '', 'Você está meio magricela! Tem se alimentado bem?', 28153),
(158833, 'ptBR', '', 'Ooooh. Você andou tudo isso só para me ver?', 28153),
(158832, 'ptBR', '', 'Olá, docinho. Que bom ver você.', 28153),
(158831, 'ptBR', 'Rar! Rargh!', '', 28153),
(158830, 'ptBR', 'Você... não...', '', 28153),
(158829, 'ptBR', 'Argrrr...', '', 28153),
(158828, 'ptBR', 'Grrrr...', '', 28153),
(158827, 'ptBR', 'Você... cheiro ruim...', '', 28153),
(158826, 'ptBR', 'Preciso... fugir...', '', 28153),
(158825, 'ptBR', 'Urgh...', '', 28153),
(158824, 'ptBR', 'Urgh... grah...', '', 28153),
(158823, 'ptBR', 'Cheiro novo, cheiro ruim! Rarr!', '', 28153),
(158822, 'ptBR', 'Arrr! Cheiro de carne!', '', 28153),
(158821, 'ptBR', 'Grar! Alimento!', '', 28153),
(158820, 'ptBR', 'Morde e come a carne!', '', 28153),
(158819, 'ptBR', 'Morre! Rargh!', '', 28153),
(158818, 'ptBR', 'Rrrr... você... eu mata!', '', 28153),
(158817, 'ptBR', 'Grrrargh!', '', 28153),
(158816, 'ptBR', 'Mmrrr!', '', 28153),
(158815, 'ptBR', 'Estas matas viveram bem mais do que você e ainda estarão aqui quando você se for.', 'Estas matas viveram bem mais do que você e ainda estarão aqui quando você se for.', 28153),
(158814, 'ptBR', 'As gemas brilhantes são uma dádiva da natureza para nós. E vamos protegê-las da sua laia!', 'As gemas brilhantes são uma dádiva da natureza para nós. E vamos protegê-las da sua laia!', 28153),
(158813, 'ptBR', 'O ciclo consumirá você, e nós nos nutriremos de seus restos mortais.', 'O ciclo consumirá você, e nós nos nutriremos de seus restos mortais.', 28153),
(158812, 'ptBR', 'Eu porei fim à sua presença antes que corrompa ainda mais nossas terras.', 'Eu porei fim à sua presença antes que corrompa ainda mais nossas terras.', 28153),
(158811, 'ptBR', 'Você servirá de nutriente para o solo que destroçou ao pisar aqui.', 'Você servirá de nutriente para o solo que destroçou ao pisar aqui.', 28153),
(158810, 'ptBR', 'Sua espécie é desequilibrada. Não é sustentável. Eu tenho que agir.', 'Sua espécie é desequilibrada. Não é sustentável. Eu tenho que agir.', 28153),
(158809, 'ptBR', 'Tenho que destruir você para restaurar o equilíbrio que você rompeu.', 'Tenho que destruir você para restaurar o equilíbrio que você rompeu.', 28153),
(158808, 'ptBR', 'Temos a incumbência de conservar esta terra e a fauna. Este lugar não é para você!', 'Temos a incumbência de conservar esta terra e a fauna. Este lugar não é para você!', 28153),
(158807, 'ptBR', 'Sua raça... é uma praga...', 'Sua raça... é uma praga...', 28153),
(158806, 'ptBR', 'Você maculou... nossas terras..', 'Você maculou... nossas terras..', 28153),
(158805, 'ptBR', 'Não há como matar... a natureza...', 'Não há como matar... a natureza...', 28153),
(158804, 'ptBR', 'Nós cresceremos... outra vez...', 'Nós cresceremos... outra vez...', 28153),
(158803, 'ptBR', 'Sua espécie... não sobreviverá...', 'Sua espécie... não sobreviverá...', 28153),
(158802, 'ptBR', 'Eu sinto... a terra...', 'Eu sinto... a terra...', 28153),
(158801, 'ptBR', 'Você rompeu... o equilíbrio...', 'Você rompeu... o equilíbrio...', 28153),
(158800, 'ptBR', 'Eu volto... à natureza...', 'Eu volto... à natureza...', 28153),
(158799, 'ptBR', 'Nós temos a missão de proteger este lugar!', 'Nós temos a missão de proteger este lugar!', 28153),
(158798, 'ptBR', 'As gemas brilhantes são uma dádiva para a natureza!', 'As gemas brilhantes são uma dádiva para a natureza!', 28153),
(158797, 'ptBR', 'Temos que preservar o equilíbrio!', 'Temos que preservar o equilíbrio!', 28153),
(158796, 'ptBR', 'Você não vai corromper nossa clareira!', 'Você não vai corromper nossa clareira!', 28153),
(158795, 'ptBR', 'Eu vim pelo chamado da natureza!', 'Eu vim pelo chamado da natureza!', 28153),
(158794, 'ptBR', 'Esta terra não será conspurcada por você!', 'Esta terra não será conspurcada por você!', 28153),
(158793, 'ptBR', 'Natureza, guie minha fúria!', 'Natureza, guie minha fúria!', 28153),
(158792, 'ptBR', 'Tenho que proteger a natureza!', 'Tenho que proteger a natureza!', 28153),
(158791, 'ptBR', 'Eu venho aqui todo dia pra falar com meus avós. Acho que eles me escutam!', '', 28153),
(158790, 'ptBR', 'Gruu...', 'Gruu...', 28153),
(158789, 'ptBR', 'Onde... estou...?', 'Onde... estou...?', 28153),
(158788, 'ptBR', 'Graaa... sangue...', 'Graaa... sangue...', 28153),
(158787, 'ptBR', '', 'Após a vitória é que começa o verdadeiro trabalho.', 28153),
(158786, 'ptBR', 'A fúria... se abranda...', 'A fúria... se abranda...', 28153),
(158785, 'ptBR', 'Você... por quê...', 'Você... por quê...', 28153),
(158784, 'ptBR', 'Preciso... fugir...', 'Preciso... fugir...', 28153),
(158783, 'ptBR', 'Agora... vejo melhor...', 'Agora... vejo melhor...', 28153),
(158782, 'ptBR', 'Argh... dor...', 'Argh... dor...', 28153),
(158781, 'ptBR', 'Grarh!', 'Grarh!', 28153),
(158780, 'ptBR', 'Minha fúria!', 'Minha fúria!', 28153),
(158779, 'ptBR', 'Estranho...', 'Estranho...', 28153),
(158778, 'ptBR', 'Cheiro de medo...', 'Cheiro de medo...', 28153),
(158777, 'ptBR', 'Sai... rrr...', 'Sai... rrr...', 28153),
(158776, 'ptBR', 'Matar... você...', 'Matar... você...', 28153),
(158775, 'ptBR', 'Grrr...', 'Grrr...', 28153),
(158774, 'ptBR', 'Rargh!', 'Rargh!', 28153),
(158773, 'ptBR', 'Olha como ele tá esticando! Vai ficar igualzinho ao pai.', '', 28153),
(158772, 'ptBR', 'Maldição... em você...', 'Maldição... em você...', 28153),
(158771, 'ptBR', 'Já tô vendo... os ancestrais...', 'Já tô vendo... os ancestrais...', 28153),
(158770, 'ptBR', 'Os espíritos vão... me receber...', 'Os espíritos vão... me receber...', 28153),
(158769, 'ptBR', 'Tu não tem... honra...', 'Tu não tem... honra...', 28153),
(158768, 'ptBR', 'Ugh... tu me pegou...', 'Ugh... tu me pegou...', 28153),
(158767, 'ptBR', 'Vocês não vão... matar a gente tudo...', 'Vocês não vão... matar a gente tudo...', 28153),
(158766, 'ptBR', 'Vou me vingar de tu... lá do além...', 'Vou me vingar de tu... lá do além...', 28153),
(158765, 'ptBR', 'Indo pros espíritos...', 'Indo pros espíritos...', 28153),
(158764, 'ptBR', 'Vou fazer uma bagata com teus ossos e botar uma maldição na tua família!', 'Vou fazer uma bagata com teus ossos e botar uma maldição na tua família!', 28153),
(158763, 'ptBR', 'Tu não passa de $Uum:uma; forastei$Uro:ra; $Uimundo:imunda;. Não tem nada pra tu aqui!', 'Tu não passa de $Uum:uma; forastei$Uro:ra; $Uimundo:imunda;. Não tem nada pra tu aqui!', 28153),
(158762, 'ptBR', '', 'Parece que foi ontem que nosso filhote teve essa criança. Olha pra ele agora!', 28153),
(158761, 'ptBR', 'Ei, quem é tu? Aqui não é lugar pra tu, tá sabendo?', 'Ei, quem é tu? Aqui não é lugar pra tu, tá sabendo?', 28153),
(158760, 'ptBR', 'Mostra aí do que tu é capaz, então...', 'Mostra aí do que tu é capaz, então...', 28153),
(158759, 'ptBR', 'Agora que a gente pegou as gemas, meu clã vai ser o mais forte!', 'Agora que a gente pegou as gemas, meu clã vai ser o mais forte!', 28153),
(158758, 'ptBR', 'Tu não vai me achar tão fácil assim, hehe.', 'Tu não vai me achar tão fácil assim, hehe.', 28153),
(158757, 'ptBR', 'A ilha e as gemas são minhas. Você veio aqui encontrar a morte.', 'A ilha e as gemas são minhas. Você veio aqui encontrar a morte.', 28153),
(158756, 'ptBR', 'A gente que encontrou este lugar. Tu não vai tomar da gente!', 'A gente que encontrou este lugar. Tu não vai tomar da gente!', 28153),
(158755, 'ptBR', 'Essa ilha é nossa!', 'Essa ilha é nossa!', 28153),
(158754, 'ptBR', 'Ei, o que tu tá fazendo nessa ilha?', 'Ei, o que tu tá fazendo nessa ilha?', 28153),
(158753, 'ptBR', 'A gente tá sendo atacado, cara! Vem logo pra cá!', 'A gente tá sendo atacado, cara! Vem logo pra cá!', 28153),
(158752, 'ptBR', 'Corta eles rápido!', 'Corta eles rápido!', 28153),
(158751, 'ptBR', 'Tu vai ver quando te devorar!', 'Tu vai ver quando te devorar!', 28153),
(158750, 'ptBR', 'A gente vai te esfolar viv$Uo:a;!', 'A gente vai te esfolar viv$Uo:a;!', 28153),
(158749, 'ptBR', 'Vou fazer um colar com teus ossos!', 'Vou fazer um colar com teus ossos!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158748, 'ptBR', 'Vou te furar e beber teu sangue, cara!', 'Vou te furar e beber teu sangue, cara!', 28153),
(158747, 'ptBR', 'Raurgh! Eu tombo com dignidade!', '', 28153),
(158746, 'ptBR', 'Você... é que invadiu... nós não fizemos... nada...', '', 28153),
(158745, 'ptBR', 'A gemas... não nos salvaram...', '', 28153),
(158744, 'ptBR', 'Voltaremos... em maior número...', '', 28153),
(158743, 'ptBR', 'As estrelas... mentiram...', '', 28153),
(158742, 'ptBR', 'Eu ouço o chamado... dos ancestrais...', '', 28153),
(158741, 'ptBR', 'Os espíritos me dão as boas-vindas...', '', 28153),
(158740, 'ptBR', 'Vou me unir... aos meus ancestrais...', '', 28153),
(158739, 'ptBR', 'As estrelas guiam meus punhos. O futuro está escrito com seu sangue!', '', 28153),
(158738, 'ptBR', 'Os ventos me contaram que você perecerá hoje.', '', 28153),
(158737, 'ptBR', 'Espíritos, concedam-me a força de uma chama inextinguível!', '', 28153),
(158736, 'ptBR', 'Você arranjou uma luta que não pode vencer, fracote!', '', 28153),
(158735, 'ptBR', 'As riquezas da ilha são nossas, tolos.', '', 28153),
(158734, 'ptBR', 'Os ancestrais me dão força e sabedoria!', '', 28153),
(158733, 'ptBR', 'Eu vou untar meus chifres com seu sangue!', '', 28153),
(158732, 'ptBR', 'Eu vou defender meu clã!', '', 28153),
(158731, 'ptBR', 'Guerreiros, me ajudem!', '', 28153),
(158730, 'ptBR', 'Todos juntos! Estão nos atacando!', '', 28153),
(158729, 'ptBR', 'Esta ilha é nossa. Nada aqui lhe pertence!', '', 28153),
(158728, 'ptBR', 'As gemas brilhantes são nossas. Você não tem a menor chance!', '', 28153),
(158727, 'ptBR', 'Você não vai tomar esta terra de nós!', '', 28153),
(158726, 'ptBR', 'Invasores! Expulsem eles!', '', 28153),
(158725, 'ptBR', 'Espíritos, guiem minha arma!', '', 28153),
(158724, 'ptBR', 'Pelos antepassados!', '', 28153),
(158723, 'ptBR', 'Isso... dói...', '', 28153),
(158722, 'ptBR', 'Por que... cê veio aqui?', '', 28153),
(158721, 'ptBR', 'Argh! Bem na barriga...', '', 28153),
(158720, 'ptBR', 'Isso... é roubo...', '', 28153),
(158719, 'ptBR', 'Não! As gemas...', '', 28153),
(158718, 'ptBR', 'Pra que... que tu fez isso?', '', 28153),
(158717, 'ptBR', 'Uff... não caiu bem...', '', 28153),
(158716, 'ptBR', 'Por que tá escuro?', '', 28153),
(158715, 'ptBR', '', 'Tem gente que acha que um acordo é só de boca. Promessa vazia e caô. A recompensa de hoje em troca da incerteza do futuro.\n\nMas não esqueça uma coisa: o Bwonsamdi não deixa de cobrar nenhuma dívida. Nunca.', 28153),
(158714, 'ptBR', 'Ogros tudo, hora de esmagar!', '', 28153),
(158713, 'ptBR', 'Não! Minha gema! Não sua! Mim precisa!', '', 28153),
(158712, 'ptBR', 'As gemas deixa a gente mais forte. Mais forte que tu!', '', 28153),
(158711, 'ptBR', 'Mim pega tua cabeça de troféu quando terminar tudo!', '', 28153),
(158710, 'ptBR', 'Pega eles! Arrebenta espinha deles!', '', 28153),
(158709, 'ptBR', 'A ilha é minha, fracote. Minha!', '', 28153),
(158708, 'ptBR', 'Mim esmaga tu. Mim bebe teu sangue!', '', 28153),
(158707, 'ptBR', 'Mim quebra tu em pedaço! Raaurgh!', '', 28153),
(158706, 'ptBR', 'Gema tudo minha! Raaurgh!', '', 28153),
(158705, 'ptBR', 'Não pega coisa da gente!', '', 28153),
(158704, 'ptBR', 'Pega eles!', '', 28153),
(158703, 'ptBR', 'Cê não pega gema!', '', 28153),
(158702, 'ptBR', 'A ilha é minha! Sai agora!', '', 28153),
(158701, 'ptBR', 'Mata $Go intruso:a intrusa;!', '', 28153),
(158700, 'ptBR', 'Esmaga, arrebenta, mata!', '', 28153),
(158699, 'ptBR', 'Mim esmaga tu!', '', 28153),
(158698, 'ptBR', 'Quem sabe se eu prometer ser uma pessoa melhor desta vez... diferente da outra vez!', 'Quem sabe se eu prometer ser uma pessoa melhor desta vez... diferente da outra vez!', 28153),
(158697, 'ptBR', 'O que tu acha que o Bwonsamdi quer de mim?', 'O que tu acha que o Bwonsamdi quer de mim?', 28153),
(158696, 'ptBR', 'Que é que eu faço... que é que eu faço... tem que ter um jeito!', 'Que é que eu faço... que é que eu faço... tem que ter um jeito!', 28153),
(158695, 'ptBR', 'Se eu fizer um acordo com Bwonsamdi, aí tudo volta ao normal, né?', 'Se eu fizer um acordo com Bwonsamdi, aí tudo volta ao normal, né?', 28153),
(158694, 'ptBR', 'Eu odeio isso aqui! Eu odeio tudo!', 'Eu odeio isso aqui! Eu odeio tudo!', 28153),
(158693, 'ptBR', 'Isso é inaceitável! Será que não sabem quem eu sou?', 'Isso é inaceitável! Será que não sabem quem eu sou?', 28153),
(158692, 'ptBR', 'Eu vou pegar quem armou essa pra mim! Nem que seja a última coisa que eu faça!', 'Eu vou pegar quem armou essa pra mim! Nem que seja a última coisa que eu faça!', 28153),
(158691, 'ptBR', 'Como é que rolou uma coisa dessas? Que sacanage!', 'Como é que rolou uma coisa dessas? Que sacanage!', 28153),
(158690, 'ptBR', 'Nada vai melhorar. Não tem como tu me convencer disso.', 'Nada vai melhorar. Não tem como tu me convencer disso.', 28153),
(158689, 'ptBR', 'Tava tudo beleza pra mim, e agora olha... eu perdi tudo.', 'Tava tudo beleza pra mim, e agora olha... eu perdi tudo.', 28153),
(158688, 'ptBR', 'Nunca mais vou sentir a luz do sol.', 'Nunca mais vou sentir a luz do sol.', 28153),
(158687, 'ptBR', 'Se tivesse só mais uns dias... Eu podia fazer tanta coisa.', 'Se tivesse só mais uns dias... Eu podia fazer tanta coisa.', 28153),
(158686, 'ptBR', 'Morto? Não, eu tô só dando uma descansada.', 'Morta? Não, eu tô só dando uma descansada.', 28153),
(158685, 'ptBR', 'Quem é você? Deixa pra lá, não deve ser importante...', 'Quem é você? Deixa pra lá, não deve ser importante...', 28153),
(158684, 'ptBR', 'Se eu não estiver olhando, não tá acontecendo. Simples assim.', 'Se eu não estiver olhando, não tá acontecendo. Simples assim.', 28153),
(158683, 'ptBR', 'Continua indo... continua indo... vai dar tudo certo...', 'Continua indo... continua indo... vai dar tudo certo...', 28153),
(158682, 'ptBR', 'Como ousa pisar na MINHA fortaleza? Basta!', '', 28153),
(158681, 'ptBR', 'Criatura fraca. Venha me enfrentar em combate!', '', 28153),
(158680, 'ptBR', 'Você acha que sua máquina deplorável pode dar conta de mim!?', '', 28153),
(158679, 'ptBR', 'Salve! Um desafiante! Ao ataque!', '', 28153),
(158678, 'ptBR', 'Como esse rostinho bonito pode morrer assim...', '', 28153),
(158677, 'ptBR', '', 'Eu... vou te estripar...', 28153),
(158676, 'ptBR', '', 'Eu vou te fazer em retalhos!', 28153),
(158675, 'ptBR', 'Me atirem no mar...', '', 28153),
(158674, 'ptBR', 'Eu vou arrastar você na quilha!', '', 28153),
(158673, 'ptBR', 'Urgh. Esse cara... Eu não sei o que é pior: a quantidade de creme no cabelo ou os poemas dele. Mas não se deixe enganar, o Ridão é um guerreiro e um romântico.', '', 28153),
(158672, 'ptBR', 'O Beckett acha que é uma lenda no mundinho dele.', '', 28153),
(158671, 'ptBR', 'A Luna tem a língua... Afiada, né? Digamos assim.', '', 28153),
(158670, 'ptBR', 'Heh... As únicas certezas. Impostos e...', '', 28153),
(158669, 'ptBR', 'O que temos aqui? Parece uma conta que precisa ser encerrada!', '', 28153),
(158668, 'ptBR', '', 'Tomara que não seja tarde, $n. Voe como o vento. Encontre a minha filha.', 28153),
(158666, 'ptBR', '', 'Fim do Destino é uma ilha no litoral de Trovamare. Os criminosos e traidores da pior estirpe são mandados para lá e nunca voltam.', 28153),
(158665, 'ptBR', '', '$n, o que você descobriu?', 28153),
(158661, 'ptBR', 'Eu vou cair fora daqui! Obrigado pela ajuda, $p!', '', 28153),
(158660, 'ptBR', 'Kua\'fon solta um guinchado de estourar os tímpanos e sacode a cauda alegremente.', '', 28153),
(158659, 'ptBR', 'Kua\'fon põe a caveira de volta na sua mão.', '', 28153),
(158658, 'ptBR', 'Kua\'fon solta a caveira junto aos pés e trina alegremente para você.', '', 28153),
(158657, 'ptBR', '', 'A guerra está perdida. Logo Teldrassil cairá.', 28153),
(158656, 'ptBR', 'As ondas engolirão você!', '', 28153),
(158655, 'ptBR', 'Vamos, camarada. Vamos atrás da Chefe Guerreira... rumo à vitória.', '', 28153),
(158654, 'ptBR', '', 'Vai servir. Sobe aí, pessoal!', 28153),
(158653, 'ptBR', 'Você também tem uma escolha. Levá-lo a Darnassus, onde vocês dois vão cair quando a invasão acontecer... ou fugir para bem longe daqui, onde os dois vão sobreviver.', '', 28153),
(158652, 'ptBR', '', 'Como você poupou Malfurion, vou lhe dar uma escolha.', 28153),
(158651, 'ptBR', '', 'Aguentem firme.', 28153),
(158650, 'ptBR', 'Não foi a troco de nada. Nós derramamos sangue pelo futuro da Horda.', '', 28153),
(158649, 'ptBR', '', 'Essa guerra inteira não tem honra. Como você ousa derramar tanto sangue a troco de nada!', 28153),
(158648, 'ptBR', 'Eu ataquei sem honra. Eu não tinha direito de acabar com ele.', '', 28153),
(158647, 'ptBR', '', 'Você não o matou, orc. Por quê?', 28153),
(158646, 'ptBR', '', 'Malfurion! Não!', 28153),
(158645, 'ptBR', 'Você liderou... a Horda... a serviço... da morte. Vai se arrepender... do que fez hoje...', '', 28153),
(158642, 'ptBR', '', 'Cure suas feridas e descanse. Você está em segurança aqui.', 28153),
(158641, 'ptBR', 'Morri caçando briga com o bicho errado. Você sabe que bicho.', 'Morri caçando briga com o bicho errado. Você sabe que bicho.', 28153),
(158640, 'ptBR', 'Tô confuso que nem você, cara.', 'Tô confusa que nem você, cara.', 28153),
(158639, 'ptBR', 'Não aguentei a pimenta no chili do Haw\'li.', 'Não aguentei a pimenta no chili do Haw\'li.', 28153),
(158638, 'ptBR', 'Eu morri correndo na Torcanata. E faria a mesma coisa de novo, se pudesse!', 'Eu morri correndo na Torcanata. E faria a mesma coisa de novo, se pudesse!', 28153),
(158637, 'ptBR', 'Tu vai deixar o corpo na porta, né?', 'Tu vai deixar o corpo na porta, né?', 28153),
(158636, 'ptBR', 'Eu fui atingido por um raio enquanto andava pelo Zocalo.', 'Eu fui atingida por um raio enquanto andava pelo Zocalo.', 28153),
(158635, 'ptBR', 'Eu morri caindo da pirâmide, agora não consigo lembrar como cheguei aqui.', 'Eu morri caindo da pirâmide, agora não consigo lembrar como cheguei aqui.', 28153),
(158634, 'ptBR', 'Todo arrumadinho, mas sem nenhum lugar para ir.', 'Toda arrumadinha, mas sem nenhum lugar para ir.', 28153),
(158633, 'ptBR', 'Calcular a localização correta para este portal em Boralus não foi fácil, mas foi um desafio muito bem-vindo! Diga-me se deu certo, tudo bem?', '', 28153),
(158632, 'ptBR', 'Como quiser, Nathanos.', '', 28153),
(158631, 'ptBR', 'Zelão, vá com $n para Boralus. Oculeth aguarda com um portal.', '', 28153),
(158630, 'ptBR', 'Chega mais, camarada. A gente precisa trocar uma ideia.', '', 28153),
(158629, 'ptBR', 'Este é o melhor assento da casa... Pode ficar aqui quando eu me levantar.', '', 28153),
(158628, 'ptBR', '', '$p? Pfff. Nunca nem ouvi falar.', 28153),
(158627, 'ptBR', 'Quando estiver preparad$Uo:a; para ir até os navios, fale com o Roberto aí fora.', '', 28153),
(158626, 'ptBR', 'Depois não diga que não avisei.', 'Depois não diga que não avisei.', 28153),
(158625, 'ptBR', 'Para trás! É para o seu próprio bem.', 'Para trás! É para o seu próprio bem.', 28153),
(158624, 'ptBR', 'Kua\'fon treme de medo.', '', 28153),
(158623, 'ptBR', 'A maré virou para o nosso lado, não acha, $n?', '', 28153),
(158622, 'ptBR', 'Vejo grandes eventos no horizonte... tanto para mim quanto para você.', '', 28153),
(158621, 'ptBR', 'Tu não pode me deixar aqui. Meus ossos tão velhos demais pra trabalhar nas minas.', 'Tu não pode me deixar aqui. Meus ossos tão velhos demais pra trabalhar nas minas.', 28153),
(158620, 'ptBR', 'Acho que eu sei o que fizemos de errado no estágio de fermentação.', '', 28153),
(158619, 'ptBR', 'Então, a introdução de contaminantes invisíveis pode estar causando impacto no processo de redução inicial.', '', 28153),
(158618, 'ptBR', 'Pode deixar.', '', 28153),
(158617, 'ptBR', 'Qualquer coisa pra ajudar.', '', 28153),
(158616, 'ptBR', 'Vou trabalhar.', '', 28153),
(158615, 'ptBR', 'Claro, eu dou uma mão.', '', 28153),
(158614, 'ptBR', 'Acho que eu posso dar uma mão.', '', 28153),
(158612, 'ptBR', '', 'Olhe para cima. As árvores têm olhos, camarada. Trate de cegá-las.', 28153),
(158611, 'ptBR', 'Primeiro, temos que nos concentrar em estabilizar os componentes principais.', '', 28153),
(158610, 'ptBR', 'Ahhhh! Isso explica muito! \"Primeira Lei da Alquimia: Para obter um benefício, é preciso fornecer um substituto à altura\".', '', 28153),
(158609, 'ptBR', 'Vamos lá!', 'Vamos lá!', 28153),
(158608, 'ptBR', 'Intrigante... É fundamental aplicar a dose certa de calor.', '', 28153),
(158607, 'ptBR', 'Ahhh! Acho que entendi onde foi que o catalisador falhou.', '', 28153),
(158606, 'ptBR', 'Estranho... não havia como prever.', '', 28153),
(158605, 'ptBR', 'Hmmm... Que interessante.', '', 28153),
(158604, 'ptBR', 'Uns parceiros nossos foram pegos. Você daria uma mãozinha?', '', 28153),
(158603, 'ptBR', 'Ei, alguém malocou um bocado de coisa nossa! A gente tem que recuperar PRA ONTEM. De preferência com juros.', '', 28153),
(158602, 'ptBR', 'Aah, tudo ARREBENTADO. A gente tem que ajudar esses caras!', '', 28153),
(158601, 'ptBR', 'Tem mão leve na área? Eu tenho um servicinho!', '', 28153),
(158600, 'ptBR', 'Escuta, se achar umas peças de triciclo de guerra por aí, me dá um toque. Depois que ele estiver nos trinques, eu te empresto.', '', 28153),
(158599, 'ptBR', 'Eu espiei um bicho que tá precisando da boa e velha surra de Kezan.', '', 28153),
(158598, 'ptBR', 'Aah, olha o TAMANHO desse bicho. Ei, ninguém vai matar esse troço, não?', '', 28153),
(158597, 'ptBR', 'Forças aliadas foram capturadas. Que tal uma operaçãozinha de resgate?', '', 28153),
(158596, 'ptBR', 'Forças inimigas fugiram com suprimentos vitais. Que tal abastecermos as despensas dos ladrõezinhos com a justiça da Aliança?', '', 28153),
(158595, 'ptBR', 'Tem soldados feridos no campo de batalha. Algum socorrista disponível?', '', 28153),
(158594, 'ptBR', 'Sim, criança. Eluna estava com eles. Ela abençoou os druidas para que conjurassem ventos fortes para inflar as velas.', '', 28153),
(158593, 'ptBR', '', 'O Mar Velado foi gentil com eles, Shan\'do?', 28153),
(158592, 'ptBR', 'Leve-me de volta ao porto.', 'Leve-me de volta ao porto.', 28153),
(158591, 'ptBR', 'Leve-me para o barco menor.', 'Leve-me para o barco menor.', 28153),
(158590, 'ptBR', 'Procuram-se voluntários para uma operação secreta, com experiência em furtividade, truques e engodos.', '', 28153),
(158589, 'ptBR', 'Nós estamos tentando reaproveitar uma máquina de guerra inimiga. Traga todas as peças sobressalentes que encontrar.', '', 28153),
(158588, 'ptBR', 'Ah! Apareceu um alvo de oportunidade.', '', 28153),
(158587, 'ptBR', 'Uma criatura grande e agressiva apareceu no campo de batalha. A temporada de caça está aberta!', '', 28153),
(158586, 'ptBR', 'Já deu oi pro meu camaradinha?', '', 28153),
(158585, 'ptBR', 'Você tirou o dia pra me alugar, camarada?', '', 28153),
(158584, 'ptBR', 'Sossega o facho.', '', 28153),
(158583, 'ptBR', 'Não vai me morrer à toa, hein?', '', 28153),
(158582, 'ptBR', 'Mantenha seus olhos abertos.', '', 28153),
(158581, 'ptBR', 'Toma cuidado lá fora.', '', 28153),
(158580, 'ptBR', 'Quais são as novidades?', '', 28153),
(158579, 'ptBR', 'Que tal o dia?', '', 28153),
(158578, 'ptBR', 'Oi, belezinha.', '', 28153),
(158577, 'ptBR', 'Luz do céu, é por isso que eu bebo.', '', 28153),
(158576, 'ptBR', 'Meu soldo de oficial não vale essa palhaçada.', '', 28153),
(158575, 'ptBR', 'Sim, sim...', '', 28153),
(158574, 'ptBR', 'Siga em frente.', '', 28153),
(158573, 'ptBR', 'Dispensados.', '', 28153),
(158572, 'ptBR', 'Não perca os inimigos de vista.', '', 28153),
(158571, 'ptBR', 'Pois não?', '', 28153),
(158570, 'ptBR', 'Você tem toda a minha atenção.', '', 28153),
(158569, 'ptBR', 'Glória à Aliança.', '', 28153),
(158568, 'ptBR', '', 'Não... não é possível.', 28153),
(158565, 'ptBR', '', 'Você me ajudará a testar os limites do meu poder!', 28153),
(158564, 'ptBR', '', 'Dizem que minha magia é cruel, mas eu só tento explorar os limites do possível.', 28153),
(158563, 'ptBR', 'Desarraigando', 'Desarraigando', 28153),
(158562, 'ptBR', 'Mia... MIA! Abra os olhos, minha rainha... meu amor!', '', 28153),
(158561, 'ptBR', 'Que a sua deusa zele por você.', '', 28153),
(158560, 'ptBR', 'A Banshee matou o meu filho. Roubou o meu reino. Ela não vai me tirar a minha amada!', '', 28153),
(158559, 'ptBR', '', 'Eles... não vão...', 28153),
(158558, 'ptBR', 'Astarii, você já fez tudo que podia! Mande os sacerdotes virem conosco!', '', 28153),
(158557, 'ptBR', 'Jamais! Vou levar as duas!', '', 28153),
(158555, 'ptBR', '', 'A árvore... Botaram fogo na árvore! A criança... salve-a. Eu fico...', 28153),
(158554, 'ptBR', 'Você não pode continuar aqui! Nós temos que fugir pelo portal!', '', 28153),
(158553, 'ptBR', '', 'Astarii, não há tempo a perder. Temos que evacuar a cidade antes que ela vire pó!', 28153),
(158551, 'ptBR', '', 'Mate-o e acabe logo com isso. Tome um ar, se quiser... depois corte-lhe a cabeça. Encontro você na Árvore do Mundo.', 28153),
(158550, 'ptBR', '', 'Minha vitória era inevitável. Ele só estava me fazendo perder tempo.', 28153),
(158549, 'ptBR', 'Eu não tinha nada que interferir.', '', 28153),
(158548, 'ptBR', '', 'Não sinta culpa. Foi um bom trabalho.', 28153),
(158547, 'ptBR', 'Um golpe sem honra. Eu... me arrependo.', '', 28153),
(158546, 'ptBR', 'ARGH! Saur... fang?!', '', 28153),
(158545, 'ptBR', 'A Chefe Guerreira enfrenta Tempesfúria sozinha! Eu preciso...', '', 28153),
(158544, 'ptBR', 'Pelo norte? Como foi que...  Eles escalaram as montanhas da Selva Maleva. É lógico!', '', 28153),
(158543, 'ptBR', 'Camarada, Delaryn: interceptem o inimigo em Auberdine. Eu cuidarei do norte.', '', 28153),
(158542, 'ptBR', 'É só questão de tempo para que a Horda atravesse. Eles nos atacarão pelos dois lados.', '', 28153),
(158541, 'ptBR', 'Os fogos-fátuos... estão ficando desnorteados! A muralha está cedendo!', '', 28153),
(158540, 'ptBR', '', 'Esse barulho... será possível? Shan\'do! A Horda se aproxima pelo norte!', 28153),
(158539, 'ptBR', '', 'Chegou a hora. A Árvore do Mundo está quase em nossas mãos! Encontre Saurfang. Vamos acabar com isso de uma vez por todas.', 28153),
(158537, 'ptBR', '', 'Olhe ao redor, camarada! Que vista linda. Os fogos-fátuos estão se dispersando. As muralhas desmoronam uma a uma.', 28153),
(158536, 'ptBR', '', 'Saurfang! Já era hora.', 28153),
(158535, 'ptBR', 'PELA HORDA!', '', 28153),
(158534, 'ptBR', '', 'Para onde você voou, passarinho?', 28153),
(158533, 'ptBR', '', 'Argh! Meus olhos estão ardendo!', 28153),
(158532, 'ptBR', 'Suma daqui, bruxa!', '', 28153),
(158531, 'ptBR', '', 'Quem poderia imaginar que você viria proteger suas preciosas árvores?', 28153),
(158530, 'ptBR', '', 'Malfurion. Que bom que você veio dar o ar da sua graça...', 28153),
(158529, 'ptBR', 'Sylvana! Sua perversidade profana este solo sagrado! Andu-falah-dor!', '', 28153),
(158528, 'ptBR', '', 'Não podemos lhes dar o luxo de uma noite bem dormida. Isto aqui é guerra.', 28153),
(158527, 'ptBR', '', 'Neste meio tempo, faremos de tudo para continuar pressionando os kaldorei.', 28153),
(158526, 'ptBR', '', 'Eu vou continuar avançando com os soldados pela muralha enquanto esperamos notícias de Saurfang.', 28153),
(158525, 'ptBR', '', 'Temos que seguir o plano por ora.', 28153),
(158524, 'ptBR', '', 'Armou-se um impasse no Rio Crenado, e Malfurion está ciente disso.', 28153),
(158523, 'ptBR', '', 'Campeões da Horda, precisamos de vocês no Rio Crenado! Esta é a nossa chance de vencer!', 28153),
(158522, 'ptBR', '', '... Eu tenho um corvo a caçar.', 28153),
(158521, 'ptBR', '', 'Vamos agir rápido aqui. Recolham toda a azerita que der para carregar e entreguem para os engenheiros.', 28153),
(158520, 'ptBR', '', 'O navio deve ter vindo de Darnassus... Isso quer dizer que...', 28153),
(158519, 'ptBR', '', 'Prossiga com cautela, camarada. Pelo visto, a Aliança chegou primeiro.', 28153),
(158518, 'ptBR', '', 'Azerita... Com isso em mãos, todos que se opuserem a Horda virão abaixo.', 28153),
(158517, 'ptBR', '', 'Sapadores, recolham o equipamento e venham! Tragam todos os retalhadores que tivermos.', 28153),
(158516, 'ptBR', '', 'Acabe com a existência deles, antes que cubram a floresta com o sangue do seu povo.', 28153),
(158515, 'ptBR', '', 'Estou vendo a preocupação em seus olhos. Os ancientes se voltaram contra você, druida... contra o dever sagrado deles.', 28153),
(158514, 'ptBR', 'Taelia! Precisamos de uma carona aqui, rápido!', '', 28153),
(158513, 'ptBR', 'E com isso eu quero dizer \"saltar do precipício para se salvar\". Vamos!', '', 28153),
(158512, 'ptBR', 'E fazer uma fuga emocionante!', '', 28153),
(158511, 'ptBR', 'É só pegar o baú...', '', 28153),
(158510, 'ptBR', 'Nunca imaginei que o sol pudesse castigar tanto a pele restante de alguém.', 'Nunca imaginei que o sol pudesse castigar tanto a pele restante de alguém.', 28153),
(158509, 'ptBR', 'Eu garanto que meu plano é brilhante.', '', 28153),
(158508, 'ptBR', 'Imagino que você tenha um plano para sair daqui com isso.', 'Imagino que você tenha um plano para sair daqui com isso.', 28153),
(158507, 'ptBR', 'Arlão colocou outra fechadura na caixa-forte dele para aumentar a segurança.\n\n<Filinto coça o queixo.>\n\nÉ... a única coisa a fazer agora... é roubar o baú.', '', 28153),
(158506, 'ptBR', 'Essa foi boa, Arlão. Muito boa mesmo.', '', 28153),
(158505, 'ptBR', 'Estou pensando em cem voltas em torno da Academia para cada cadete que eu encontrar.', '', 28153),
(158504, 'ptBR', 'Devem estar em algum lugar por aqui.', '', 28153),
(158503, 'ptBR', 'Nunca pedimos para vir para cá... ou para enfrentar isso.', 'Nunca pedimos para vir para cá... ou para enfrentar isso.', 28153),
(158502, 'ptBR', 'Quatro!? Quatro cadeados!?', '', 28153),
(158501, 'ptBR', 'A Aliança ousa dizer que NÓS somos monstros?', 'A Aliança ousa dizer que NÓS somos monstros?', 28153),
(158500, 'ptBR', 'Onde estão os cadetes...', '', 28153),
(158499, 'ptBR', 'Vamos lá... Caixa-forte de Arlão Mel.', '', 28153),
(158498, 'ptBR', 'Com tudo que aconteceu, não posso dizer que tenho inveja dela. Mas talvez seja hora de ela passar o comando de Kul Tiraz a alguém mais qualificado.', 'Com tudo que aconteceu, não posso dizer que tenho inveja dela. Mas talvez seja hora de ela passar o comando de Kul Tiraz a alguém mais qualificado.', 28153),
(158497, 'ptBR', 'A cada dia fica mais óbvio que Katherine está aproveitando o vácuo deixado pelo marido.', 'A cada dia fica mais óbvio que Katherine está aproveitando o vácuo deixado pelo marido.', 28153),
(158496, 'ptBR', 'Mais uma semana se passou sem que o encontro das Casas se concretizasse.', 'Mais uma semana se passou sem que o encontro das Casas se concretizasse.', 28153),
(158495, 'ptBR', 'Muito. Qualquer nobre de Tiragarde que se preze teria o bom senso de não entregar de bandeja uma história triste de que a vítima possa se aproveitar.', 'Muito. Qualquer nobre de Tiragarde que se preze teria o bom senso de não entregar de bandeja uma história triste de que a vítima possa se aproveitar.', 28153),
(158494, 'ptBR', 'Assassinado à luz do dia, na data do casamento. Que planejamento amador.', 'Assassinado à luz do dia, na data do casamento. Que planejamento amador.', 28153),
(158493, 'ptBR', 'A história do noivo? Claro, uma lástima.', 'A história do noivo? Claro, uma lástima.', 28153),
(158492, 'ptBR', 'Você ouviu falar do que aconteceu com a filha dos Capelo?', 'Você ouviu falar do que aconteceu com a filha dos Capelo?', 28153),
(158491, 'ptBR', 'Que desgraça. Um Trovamare que não consegue evocar o mar? Se fosse na minha família, eu já teria deserdado esse menino há anos.', 'Que desgraça. Um Trovamare que não consegue evocar o mar? Se fosse na minha família, eu já teria deserdado esse menino há anos.', 28153),
(158490, 'ptBR', 'Então o tio daquele estorvo despachou ele e o jogou nas nossas costas?', 'Então o tio daquele estorvo despachou ele e o jogou nas nossas costas?', 28153),
(158489, 'ptBR', 'Ouvi dizer que Brício voltou a trabalhar aqui no Estreito.', 'Ouvi dizer que Brício voltou a trabalhar aqui no Estreito.', 28153),
(158488, 'ptBR', 'Ainda bem que Jaina puxou à mãe. Não se pode dizer que Daelin era dos mais bem-apessoados.', 'Ainda bem que Jaina puxou à mãe. Não se pode dizer que Daelin era dos mais bem-apessoados.', 28153),
(158487, 'ptBR', '', '<Ainda há uma adaga nas costas dela, mas todos seus pertences foram roubados.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158486, 'ptBR', '', '<Este cadáver de Zandalari parece ser coisa recente.>', 28153),
(158485, 'ptBR', '<Examinar o corpo.>', '<Examinar o corpo.>', 28153),
(158484, 'ptBR', 'Faz tempo que os Capelo não aparecem em Boralus. Acho que Meredite finalmente se deu conta de que ela não é bem-vinda aqui.', 'Faz tempo que os Capelo não aparecem em Boralus. Acho que Meredite finalmente se deu conta de que ela não é bem-vinda aqui.', 28153),
(158483, 'ptBR', 'Você viu os trajes do Lorde Trovamare da última vez? Chapéu com tentáculos é meio cafona, na minha opinião.', 'Você viu os trajes do Lorde Trovamare da última vez? Chapéu com tentáculos é meio cafona, na minha opinião.', 28153),
(158482, 'ptBR', '<Simão olha para Kunga.>\n\nHã... sim! Haha! Muito engraçado!\n\nHahaha! Hilário mesmo!\n\nMelhor você ir embora para não achar outro. Haha!\n\nVá assistir uma luta enquanto eu... reponho o estoque.', '', 28153),
(158481, 'ptBR', 'Achei um corpo atrás da barraca.', 'Achei um corpo atrás da barraca.', 28153),
(158480, 'ptBR', 'Oi, hã, sim.\n\nBem-$Uvindo:vinda; à minha loja. A Loja... de Vender... Coisas... do Simão.\n\nEu vendo...\n\n<Simão olha para trás de soslaio.>\n\nArmas. De todo tipo. Mas estamos ocupados.\n\nVolte depois que eu... terminar de fazer as contas.', '', 28153),
(158479, 'ptBR', 'Vou acabar com você, escória da Horda!', '', 28153),
(158478, 'ptBR', 'A Aliança não tem direito nenhum sobre as nossas terras!', 'A Aliança não tem direito nenhum sobre as nossas terras!', 28153),
(158477, 'ptBR', 'Qualquer coisa é melhor do que comida de viagem.', '', 28153),
(158476, 'ptBR', 'Todos os nossos recursos estão concentrados em ganhar tempo para o nosso povo fugir e conter o avanço da Horda. Procure algo para as nossas sentinelas comerem.', '', 28153),
(158475, 'ptBR', '', 'Vou mandar você para a escuridão!', 28153),
(158474, 'ptBR', 'O volume no meu bolso não é mojo, não.', '', 28153),
(158473, 'ptBR', 'Tu vai provar do teu próprio veneno.', '', 28153),
(158472, 'ptBR', 'Não me obriga a te transformar em sapo!', '', 28153),
(158471, 'ptBR', 'Acho bom parar com a palhaçada. Troll velho é que faz bagata boa.', '', 28153),
(158470, 'ptBR', 'Calma lá, camarada. Não precisa ficar encostando.', '', 28153),
(158469, 'ptBR', 'Eu já treinei gerações e gerações de trolls Lançanegra.', '', 28153),
(158468, 'ptBR', 'Boa sorte, leva um mojo sempre contigo.', '', 28153),
(158467, 'ptBR', '', 'Qualquer coisa é melhor do que rações de viagem.', 28153),
(158466, 'ptBR', '', 'Pelo que sei, um exército precisa de comida para se mover. Deve ter algo que sirva de alimento nesta floresta.', 28153),
(158465, 'ptBR', 'Lembra que nem tudo regenera.', '', 28153),
(158464, 'ptBR', 'Cuidado!', '', 28153),
(158463, 'ptBR', 'Eu praticamente já consegui o que queria! Só mais um instantinho...', '', 28153),
(158462, 'ptBR', 'Hum, as folhas são um pouquinho mais teimosas do que eu previa... mas acho que está dando certo.', '', 28153),
(158461, 'ptBR', 'Isso vai levar um tempo. A remoção das folhas é um processo delicado.', '', 28153),
(158460, 'ptBR', 'Eu tô velho demais pra isso.', '', 28153),
(158459, 'ptBR', 'Que os espíritos te abençoem.', '', 28153),
(158458, 'ptBR', 'Ikum bokum.', '', 28153),
(158457, 'ptBR', 'Quem chamou o mandingueiro?', '', 28153),
(158456, 'ptBR', 'Tu quer uma moral?', '', 28153),
(158455, 'ptBR', 'Fala, cara.', '', 28153),
(158454, 'ptBR', 'Eu gostaria que os espíritos me guiassem.', 'Eu gostaria que os espíritos me guiassem.', 28153),
(158453, 'ptBR', 'Os espíritos podem guiar você.', '', 28153),
(158452, 'ptBR', 'Una\'fe, $n. O posto avançado está às suas ordens.', '', 28153),
(158451, 'ptBR', '', 'Você desarmou a gangue... por ora. Enquanto não pegarmos os fornecedores, vamos ter que ficar atentos.', 28153),
(158450, 'ptBR', '', 'Encha a barriga e descanse um pouco!', 28153),
(158449, 'ptBR', 'Essa câmara selada guarda a alma do mundo. Mas com todas essas explosões de azerita, o selo está prestes a romper!', '', 28153),
(158448, 'ptBR', 'Se usar o amuleto para absorver a azerita, o poder dela vai restaurar o selo da câmara!', '', 28153),
(158447, 'ptBR', '', 'Corre à boca miúda que as gangues arranjaram uns explosivos assombrosos. Enquanto não tomarmos os armamentos, ninguém em Boralus estará a salvo!', 28153),
(158446, 'ptBR', 'Meu barco afundou com centenas de homens. Logo apareceram tubarões. Grandes, pequenos, raivosos... Lutamos contra eles do jeito que dava, mas, quando você fica cara a cara com um tubarão e vê aqueles olhos mortos e completamente pretos, parece até que eles tão mortos e ganham vida quando vêm te morder. Aí o mar ficou vermelho, a situação ficou feia... em instantes, um homem é feito em pedacinho. Acho que perdi metade dos homens na primeira noite. Parecia que tinha milhares de tubarões. O resgate finalmente apareceu uns cinco dias depois. Tarde demais. Trezentos e dezesseis homens se afogaram, sete escaparam, e os tubarões pegaram o resto. \n\nChega de conversa. Quer lutar contra tubarões?', '', 28153),
(158445, 'ptBR', 'Obrigado. Eu vou arriscar. Vou pegar as botas emprestadas.', 'Obrigada. Eu vou arriscar. Vou pegar as botas emprestadas.', 28153),
(158444, 'ptBR', '', 'Eu só queria levar umas caixas que... hã... caíram da carroça.\n\nPelo menos Cido está bem. Nada machuca meu queridinho!\n\nEu tenho um par de botas extras caso você queira retomar o caminho para o norte. Mas aviso logo: eu ainda não testei.', 28153),
(158443, 'ptBR', '', 'Chegamos tarde.', 28153),
(158442, 'ptBR', '', 'Veja se precisam de ajuda. Eu vou na frente!', 28153),
(158441, 'ptBR', '', 'Primeiro temos que defender o portão!', 28153),
(158440, 'ptBR', '', 'Ah, não...', 28153),
(158439, 'ptBR', '', 'Nós sabemos. Descanse. Cuidaremos dele depois.', 28153),
(158438, 'ptBR', 'Arlão... Aquele vendido passou para o lado dos Grimpagris... Ele... AI!', '', 28153),
(158437, 'ptBR', 'Uhh... o corpo inteiro... <cof>', '', 28153),
(158436, 'ptBR', '', 'Filinto! Calma, sou eu! Você está bem? Onde é que dói?', 28153),
(158435, 'ptBR', 'Ughh.. ah.. uo-uoooPAA!!', '', 28153),
(158434, 'ptBR', '', 'Muito bem. Venha, mãe, vamos para casa.', 28153),
(158433, 'ptBR', '', 'Segura firme!', 28153),
(158432, 'ptBR', 'Estou pronto para partir.', 'Estou pronta para partir.', 28153),
(158431, 'ptBR', '', 'Eu posso nos teleportar para fora daqui. É só falar, $c. \n\nNão demore. Quero sair logo daqui.', 28153),
(158430, 'ptBR', 'CENA!', 'CENA!', 28153),
(158429, 'ptBR', 'Os elfos noturnos são vizinhos bacanas. Mas, hm... demora um pouco para se acostumar com os fogos-fátuos.', '', 28153),
(158428, 'ptBR', 'Usar a terra, trabalhar a terra. Esse era o nosso acordo.', '', 28153),
(158427, 'ptBR', 'Que pena, o que aconteceu com a árvore deles.', '', 28153),
(158426, 'ptBR', 'Se tu acha que vai impedir a gente de resgatar o corpo do Derek, pode te preparar pra uma surpresa!', '', 28153),
(158425, 'ptBR', 'Desta vez Loh só tem que chegar ao objetivo. Mas cuidado com os perigos à espreita no labirinto.', '', 28153),
(158424, 'ptBR', 'Agora, será que você consegue levar Loh até o tesouro, depois até o objetivo, sem cruzar o caminho dele?', '', 28153),
(158423, 'ptBR', 'Molezinha, não é, $n?', '', 28153),
(158422, 'ptBR', 'Primeiro, um desafio fácil: levar Loh até o objetivo.', '', 28153),
(158421, 'ptBR', 'Quando contamos as histórias, pedimos aos tortollaninhos que guiem Loh por um labirinto, enquanto enfrentam alguns desafios.', '', 28153),
(158420, 'ptBR', 'Já podemos começar o treinamento de combate?', 'Já podemos começar o treinamento de combate?', 28153),
(158419, 'ptBR', 'Abelheza da vida deixa tudo mel-lhor, $p!', 'Abelheza da vida deixa tudo mel-lhor, $p!', 28153),
(158418, 'ptBR', 'O sucesso inicial deixou Loh mais confiante, fazendo com que fosse atrás de mais lugares fantásticos para explorar.', '', 28153),
(158416, 'ptBR', 'Você consegue levar Loh até todos os tesouros, depois até a saída, sem cruzar o caminho dele?', '', 28153),
(158415, 'ptBR', 'Loh começou a explorar ruínas antigas, onde descobria tesouros maravilhosos.', '', 28153),
(158414, 'ptBR', '\"Loh, o explorador.\" Quanto mais crescia, mais curioso Loh ficava a respeito do mundo.', '', 28153),
(158413, 'ptBR', 'O cuidado de Loh compensou. A terra ofereceu a ele várias coisas nutritivas para se alimentar.', '', 28153),
(158412, 'ptBR', 'Você pode ajudar o Loh a visitar todas as plantas do jardim uma só vez?', '', 28153),
(158411, 'ptBR', 'Todas as manhãs ele fazia uma visita para conferir as plantas do seu jardim.', '', 28153),
(158410, 'ptBR', '', 'Parece que os drustos não têm interesse em manter os prisioneiros vivos. Temos que encontrar Jaina antes que seja tarde!', 28153),
(158409, 'ptBR', '\"A colheita de Loh.\" Loh adorava ver coisas crescendo.', '', 28153),
(158408, 'ptBR', 'Loh quase não conseguiu escapar. Por isso, ele decidiu buscar uma vida menos emocionante.', '', 28153),
(158407, 'ptBR', 'Você pode ajudar Loh a desativar os ladrilhos brilhantes para desativar a armadilha?', '', 28153),
(158406, 'ptBR', '\"A curiosidade e o tortollano.\" A curiosidade de Loh quase acabou com ele uma vez. Ele ativou uma armadilha Zandalari!', '', 28153),
(158405, 'ptBR', '', 'Implore por misericórdia!', 28153),
(158404, 'ptBR', 'A cidade grande não era para Loh. Ele decidiu voltar para a sua vidinha simples.', '', 28153),
(158403, 'ptBR', 'Mas toda hora ele se perdia. Você consegue levar Loh em todas as lojas, depois para a estalagem, sem cruzar o caminho dele?', '', 28153),
(158402, 'ptBR', '\"A vida na cidade grande.\" Uma vez Loh foi visitar a cidade grande, igualzinha à cidade de Boralus.', '', 28153),
(158401, 'ptBR', 'Loh foi levar uma vidinha tranquila... e de barriga cheia.', '', 28153),
(158399, 'ptBR', '', 'Eu consegui capturar uns elementais menores fascinantes em torno desses santuários. Quer ver o que eles sabem fazer?', 28153),
(158398, 'ptBR', 'Clientes fogem... $pr forte....', '', 28153),
(158397, 'ptBR', 'Ainda com fome...', '', 28153),
(158396, 'ptBR', 'Cadê luz?', '', 28153),
(158395, 'ptBR', 'Adeus, Gallywix...', '', 28153),
(158394, 'ptBR', 'Nada de briga!', '', 28153),
(158393, 'ptBR', 'Primeiro de dia de trabalho! Boa sorte!', '', 28153),
(158392, 'ptBR', 'Proibido $pr aqui!', '', 28153),
(158391, 'ptBR', 'Fexta prevada!', '', 28153),
(158390, 'ptBR', 'E nem assim você foi o pior cliente... que eu atendi hoje...', 'E nem assim você foi o pior cliente... que eu atendi hoje...', 28153),
(158389, 'ptBR', 'Um goblin.... com gelo e limão...', 'Um goblin.... com gelo e limão...', 28153),
(158388, 'ptBR', 'Quero uma última... Jaka\'Cola...', 'Quero uma última... Jaka\'Cola...', 28153),
(158387, 'ptBR', 'É bom você deixar... uma gorjeta gorda...', 'É bom você deixar... uma gorjeta gorda...', 28153),
(158386, 'ptBR', 'Eu nunca aprendi... a jogar... golfe...', 'Eu nunca aprendi... a jogar... golfe...', 28153),
(158385, 'ptBR', 'Você não tem completa o curso... nem em mil tacadas...', 'Você não tem completa o curso... nem em mil tacadas...', 28153),
(158384, 'ptBR', 'Não me enterrem nesse uniforme... É ridículo...', 'Não me enterrem nesse uniforme... É ridículo...', 28153),
(158383, 'ptBR', 'Eu não vou mais carregar porcaria de taco nenhuma...', 'Eu não vou mais carregar porcaria de taco nenhuma...', 28153),
(158382, 'ptBR', 'O Gezão... vai te fazer pagar por isso...', 'O Gezão... vai te fazer pagar por isso...', 28153),
(158381, 'ptBR', 'Ei, eu nem cheguei... na parte do \"prazer\"...', 'Ei, eu nem cheguei... na parte do \"prazer\"...', 28153),
(158380, 'ptBR', 'Peraí... meu expediente ainda não acabou...', 'Peraí... meu expediente ainda não acabou...', 28153),
(158379, 'ptBR', 'Diz pro Gallywix continuar... me pagando.', 'Diz pro Gallywix continuar... me pagando.', 28153),
(158378, 'ptBR', 'Aposto que você não dá gorjeta, muquirana...', 'Aposto que você não dá gorjeta, muquirana...', 28153),
(158377, 'ptBR', 'Você não vai pegar minha Jaka\'Cola!', 'Você não vai pegar minha Jaka\'Cola!', 28153),
(158376, 'ptBR', 'Vou usar teu rim pra fazer um drink... vai se chamar \"daiqui-rim\"!', 'Vou usar teu rim pra fazer um drink... vai se chamar \"daiqui-rim\"!', 28153),
(158375, 'ptBR', 'Estou escutando alguma coisa...', 'Estou escutando alguma coisa...', 28153),
(158374, 'ptBR', 'É você quem vai pagar essas bebidas, xará!', 'É você quem vai pagar essas bebidas, xará!', 28153),
(158373, 'ptBR', 'Que tal tentar uma tacada... no seu joelho!', 'Que tal tentar uma tacada... no seu joelho!', 28153),
(158372, 'ptBR', '<O médico se vira para você e sussurra.>$b$bEles estão muito feridos. Não dá para remover daqui... não nessas condições. O melhor a fazer é tratar eles aqui e depois tentar escapar.$b$bEste lugar está uma loucura...', 'N/D', 28153),
(158371, 'ptBR', 'Qualquer coisa é melhor do que ficar vendo esses idiotas errando tacadas o dia todo.', 'Qualquer coisa é melhor do que ficar vendo esses idiotas errando tacadas o dia todo.', 28153),
(158370, 'ptBR', 'Neste caso, recomendo um taco de ferro número nove bem no meio da cara!', 'Neste caso, recomendo um taco de ferro número nove bem no meio da cara!', 28153),
(158369, 'ptBR', 'Finalmente, é a minha vez de bater em alguma coisa!', 'Finalmente, é a minha vez de bater em alguma coisa!', 28153),
(158368, 'ptBR', 'Rá! Enganei você! Eu sou agente secreto da segurança!', 'Rá! Enganei você! Eu sou agente secreta da segurança!', 28153),
(158367, 'ptBR', 'Não se preocupe. Deixa comigo.', 'Não se preocupe. Deixa comigo.', 28153),
(158366, 'ptBR', 'Fiquem longe dos convidados!', 'Fiquem longe dos convidados!', 28153),
(158365, 'ptBR', 'O que eu ganho não vale isso.', 'O que eu ganho não vale isso.', 28153),
(158364, 'ptBR', 'Tenho que me queimar... uma última... vez...', 'Tenho que me queimar... uma última... vez...', 28153),
(158363, 'ptBR', 'Deixe-me no sol... e me vire para eu não queimar...', 'Deixe-me no sol... e me vire para eu não queimar...', 28153),
(158362, 'ptBR', 'Rá! E disseram... que o sol me mataria...', 'Rá! E disseram... que o sol me mataria...', 28153),
(158361, 'ptBR', 'Não... meu lindo corpo bronzeado...', 'Não... meu lindo corpo bronzeado...', 28153),
(158360, 'ptBR', 'Eu vou ter uma conversinha... com Gallywix sobre isso...', 'Eu vou ter uma conversinha... com Gallywix sobre isso...', 28153),
(158359, 'ptBR', 'Eu só queria uma festa...', 'Eu só queria uma festa...', 28153),
(158358, 'ptBR', 'Isso aqui não tem prazer... nem é palácio...', 'Isso aqui não tem prazer... nem é palácio...', 28153),
(158357, 'ptBR', 'Mas eu sou... muito importante...', 'Mas eu sou... muito importante...', 28153),
(158356, 'ptBR', 'Moleque, me leva... para o buraco.', 'Moleque, me leva... para o buraco.', 28153),
(158355, 'ptBR', 'Pelo menos eu morri... com uma boa pontuação...', 'Pelo menos eu morri... com uma boa pontuação...', 28153),
(158354, 'ptBR', 'Me enterre... no fosso de areia.', 'Me enterre... no fosso de areia.', 28153),
(158353, 'ptBR', 'Fala que... eu fiz uma boa pontuação.', 'Fala que... eu fiz uma boa pontuação.', 28153),
(158352, 'ptBR', 'Melhor festa... da minha vida.', 'Melhor festa... da minha vida.', 28153),
(158351, 'ptBR', 'Pior festa... da minha vida.', 'Pior festa... da minha vida.', 28153),
(158350, 'ptBR', 'Quero... meu dinheiro de volta.', 'Quero... meu dinheiro de volta.', 28153),
(158349, 'ptBR', 'Só... mais uma... bebida...', 'Só... mais uma... bebida...', 28153),
(158348, 'ptBR', 'Estamos lotados. Vai nadar em outro lugar!', 'Estamos lotados. Vai nadar em outro lugar!', 28153),
(158347, 'ptBR', 'Isso aqui não é piscina de $pr!', 'Isso aqui não é piscina de $pr!', 28153),
(158346, 'ptBR', 'Você viu meu mergulho? 10 estrelas de 10, cara!', 'Você viu meu mergulho? 10 estrelas de 10, cara!', 28153),
(158345, 'ptBR', 'Ei, $pr. Essa sua cara feia está na frente do sol!', 'Ei, $pr. Essa sua cara feia está na frente do sol!', 28153),
(158344, 'ptBR', 'Essa segurança de Gallywix fica pior a cada fim de semana.', 'Essa segurança de Gallywix fica pior a cada fim de semana.', 28153),
(158343, 'ptBR', 'Eu não paguei mais caro para ser atacado por u$Um:ma; $pr!', 'Eu não paguei mais caro para ser atacada por u$Um:ma; $pr!', 28153),
(158342, 'ptBR', 'Desapareça, $p. Vai ficar com a ralé na piscina.', 'Desapareça, $p. Vai ficar com a ralé na piscina.', 28153),
(158341, 'ptBR', 'Segura minha Jaka\'Cola. Deixa comigo.', 'Segura minha Jaka\'Cola. Deixa comigo.', 28153),
(158340, 'ptBR', 'Não pise na grama! Seus sapatos vão estragar.', 'Não pise na grama! Seus sapatos vão estragar.', 28153),
(158339, 'ptBR', 'Moleque, chama meu motorista! Essa vai ser longa.', 'Moleque, chama meu motorista! Essa vai ser longa.', 28153),
(158338, 'ptBR', 'Minha próxima tacada certeira vai ser no seu olho!', 'Minha próxima tacada certeira vai ser no seu olho!', 28153),
(158337, 'ptBR', 'Perturbação no campo! Quero outra chance!', 'Perturbação no campo! Quero outra chance!', 28153),
(158336, 'ptBR', 'Cai fora, $pr. Estamos ocupados bebendo e comendo e bebendo de novo!', 'Cai fora, $pr. Estamos ocupados bebendo e comendo e bebendo de novo!', 28153),
(158335, 'ptBR', 'Um pouco mais de animação não me incomodaria.', 'Um pouco mais de animação não me incomodaria.', 28153),
(158334, 'ptBR', 'Segurança! Leva $Uo:a; $pr daqui!', 'Segurança! Leva $Uo:a; $pr daqui!', 28153),
(158333, 'ptBR', 'Eu não comprei o pacote Molenga da Aliança!', 'Eu não comprei o pacote Molenga da Aliança!', 28153),
(158332, 'ptBR', 'Aiê...', '', 28153),
(158331, 'ptBR', 'Goblins... corre!', '', 28153),
(158330, 'ptBR', 'Só queria... brilhante...', '', 28153),
(158329, 'ptBR', 'Eu fiz o que deu...', '', 28153),
(158328, 'ptBR', 'Diz pro Gezão... desculpa...', '', 28153),
(158327, 'ptBR', 'Trabalha...', '', 28153),
(158326, 'ptBR', 'Tô com sono...', '', 28153),
(158325, 'ptBR', 'Não para... o ouro.', '', 28153),
(158324, 'ptBR', 'Não pode tocar!', '', 28153),
(158323, 'ptBR', 'Nosso ouro brilhante!', '', 28153),
(158322, 'ptBR', 'Gezão quer esmagar $pr.', '', 28153),
(158321, 'ptBR', 'Fica longe dos goblins!', '', 28153),
(158320, 'ptBR', 'Dá ouro!', '', 28153),
(158319, 'ptBR', 'Gallawick é batuta!', '', 28153),
(158318, 'ptBR', 'Não pare o trabalho!', '', 28153),
(158317, 'ptBR', 'Nada de atraso!', '', 28153),
(158316, 'ptBR', 'Eles se curvarão ao Caos.', 'Eles se curvarão ao Caos.', 28153),
(158315, 'ptBR', 'Eu os vi pelo véu. Siga-me.', 'Eu os vi pelo véu. Siga-me.', 28153),
(158314, 'ptBR', 'Venham cá, goblinzinhos...', 'Venham cá, goblinzinhos...', 28153),
(158313, 'ptBR', '', 'Nossas forças já se reuniram em Ar\'gorok. Junte os seus aliados e tome Stromgarde para a Horda!', 28153),
(158312, 'ptBR', '<Sair e juntar-se ao ataque a Lordaeron.>', '<Sair e juntar-se ao ataque a Lordaeron.>', 28153),
(158311, 'ptBR', 'As surpresas continuarão até o moral estar elevado.', '', 28153),
(158310, 'ptBR', 'Será divertido contar esta história aos seus amigos.', '', 28153),
(158309, 'ptBR', 'Preparar câmeras. Em 3... 2... 1...', '', 28153),
(158308, 'ptBR', 'Iniciando bons momentos.', '', 28153),
(158307, 'ptBR', 'Pedido de surpresa recebido. Inicializando processo com empenho.', '', 28153),
(158306, 'ptBR', 'Níveis máximos de diversão serão ultrapassados.', '', 28153),
(158305, 'ptBR', 'Convidados tediosos não serão tolerados.', '', 28153),
(158304, 'ptBR', 'Falta de diversão detectada. Corrigindo.', '', 28153),
(158303, 'ptBR', '', '... Eu conto quando a guerra acabar.', 28153),
(158302, 'ptBR', 'Esquece.', 'Esquece.', 28153),
(158301, 'ptBR', 'Sim.', 'Sim.', 28153),
(158300, 'ptBR', '', 'Estamos a poucos metros de um local cheio de membros da Horda e você ainda pergunta por que eu tenho uma poção que deixa a pessoa invisível?', 28153),
(158299, 'ptBR', 'Por que você tem um frasco de invisibilidade?', 'Por que você tem um frasco de invisibilidade?', 28153),
(158298, 'ptBR', 'Shh! Sai daqui. Você vai me entregar.', '', 28153),
(158297, 'ptBR', 'Leve-me até a nau capitânia.', 'Leve-me até a nau capitânia.', 28153),
(158296, 'ptBR', 'Precisa de carona para o navio? É comigo mesmo!', '', 28153),
(158295, 'ptBR', 'Essa arvorezona ambulante é bem impressionante!', '', 28153),
(158294, 'ptBR', 'Vai pagar por deixar Vog\'rish nervoso!', '', 28153),
(158293, 'ptBR', 'Nunca acontece com Vog\'rish antes!', '', 28153),
(158292, 'ptBR', 'Raaaagh! Vog\'rish com vergonha!', '', 28153),
(158291, 'ptBR', 'Esses elfos sabem mesmo cultivar as paradas.', '', 28153),
(158290, 'ptBR', 'Eu te mostra poder verdadeiro de Vog\'rish!', '', 28153),
(158289, 'ptBR', 'Se prepara pro inferno, fracotes!', '', 28153),
(158288, 'ptBR', 'Acabô ogro legal!', '', 28153),
(158287, 'ptBR', 'É bom ter uma ajuda extra.', '', 28153),
(158286, 'ptBR', '', 'Shandris... você tem... que sobreviver...', 28153),
(158285, 'ptBR', '', 'Pelo... meu... povo...', 28153),
(158284, 'ptBR', 'Vog\'rish queima teu pé!', '', 28153),
(158283, 'ptBR', 'Magia de Vog\'rish fora de controle!', '', 28153),
(158282, 'ptBR', '', 'Juntem-se a mim na morte!', 28153),
(158281, 'ptBR', 'Contempla poder incrível!', '', 28153),
(158280, 'ptBR', 'Ah, bem na hora.', '', 28153),
(158279, 'ptBR', '', 'Parece que você não vai ter que esperar muito mais, Nathanos.', 28153),
(158278, 'ptBR', '', 'Como são cintilantes! Vou dizer que a concha grande foi abençoada pelos Sábios das Marés e que a espiralada veio de um baú de tesouro de pirata!', 28153),
(158277, 'ptBR', '', 'Menos fogos-fátuos na muralha incomodando nossos soldados. Bom trabalho.', 28153),
(158276, 'ptBR', '', 'Para nossas tropas passarem em segurança, esta área precisa de uma limpeza. Não subestime os fogos-fátuos. Em grande número, eles são mortíferos.', 28153),
(158275, 'ptBR', '', 'Você não acreditaria nas coisas estranhas que aparecem quando se pesca aqui. Peguei uns bichos exóticos nos últimos dias. Vai encarar?', 28153),
(158274, 'ptBR', 'Lilian sempre fala que a Horda é uma família.\n\nAgora que minha família me rejeitou... sinceramente, eu preciso dessa ajuda.\n\nMas, por outro lado, Lilian prometeu que minha família ficaria segura. Se prestar auxílio à Horda for me dar essa garantia...\n\nEntão é isso que farei.', '', 28153),
(158273, 'ptBR', '', 'Nós vamos sair daqui agora mesmo!', 28153),
(158272, 'ptBR', '', 'Vendo conchas! As mais lindas de toda Kul Tiraz. Quer dizer, de Azeroth! As mais lindas de toda Azeroth!', 28153),
(158271, 'ptBR', '', 'Acho que estou recobrando o juízo, $n.\n\nCom a ajuda de Lilian, talvez eu consiga aceitar este novo destino.\n\nMas tenho que admitir... quanto mais longe de Kul Tiraz, melhor.', 28153),
(158270, 'ptBR', 'Fico grato pela oportunidade de mostrar o valor da causa ren\'dorei.\n\nFaremos de tudo para conquistar a vitória da Aliança.', '', 28153),
(158269, 'ptBR', '', 'Até agora, estou bastante impressionada com o Alto-comandante Serpecida.\n\nEle é um grande estrategista e se adapta depressa com táticas eficientes e adequadas às circunstâncias.\n\nO esforço de guerra da Aliança está em boas mãos. Assim como você, eu me orgulho de poder fazer a minha parte.', 28153),
(158268, 'ptBR', '', 'Os San\'layn têm que ser eliminados. A imprudência da Horda é um perigo para todos nós.', 28153),
(158267, 'ptBR', 'Você vê daqui a pouco. Fogo! Sim, fogo grande!', '', 28153),
(158266, 'ptBR', 'Eu chamarei você novamente quando for preciso. Pela Aliança.', '', 28153),
(158265, 'ptBR', 'O Rei Anduin precisa ficar sabendo disso agora mesmo. Nossa tarefa aqui está terminada, mas a missão apenas começou.', '', 28153),
(158264, 'ptBR', 'A Horda está mesmo usando esses elfos vampíricos? A que nível chegou...', '', 28153),
(158263, 'ptBR', 'Fumaça, sim, mas esquece o espelho!', '', 28153),
(158262, 'ptBR', 'Pela sua descrição, parece um dos san\'layn... um príncipe de sangue.', '', 28153),
(158261, 'ptBR', '', 'O Gusba m-morreu?', 28153),
(158260, 'ptBR', 'Onde tem fumaça, tem fogo... pode crer!', '', 28153),
(158259, 'ptBR', 'Chegou a hora da próxima fase do nosso plano.', '', 28153),
(158258, 'ptBR', 'Estamos com o cadáver de Derek Proudmore. Não precisamos reviver mais nenhum cadáver kultireno. Por ora.', '', 28153),
(158257, 'ptBR', 'Vamos torcer para os seus esforços não serem inúteis.', '', 28153),
(158256, 'ptBR', 'A guerra chegou à Costa Negra, e nós temos que proteger o nosso povo da melhor forma que pudermos. Mande os fogos-fátuos que encontrar para as linhas de frente e elimine as ameaças.', '', 28153),
(158255, 'ptBR', '', 'Rá! Eu ouvi um grito de traidor!', 28153),
(158254, 'ptBR', '', 'Descanso pros fatigados, comida pros famintos.', 28153),
(158253, 'ptBR', '', 'Eu não concordei com a ideia de trazer a frota kultirena para o meu porto.\n\nÉ bom você bolar outro plano. Eu me recuso a perder minha liberdade.', 28153),
(158252, 'ptBR', 'Comece o ritual.', 'Comece o ritual.', 28153),
(158251, 'ptBR', 'De onde você vem?', 'De onde você vem?', 28153),
(158250, 'ptBR', 'Há quanto tempo você está aqui?', 'Há quanto tempo você está aqui?', 28153),
(158249, 'ptBR', 'Esta terra é o único lar que tivemos até hoje. \n\nNós vamos aonde as areias nos levam.', 'Esta terra é o único lar que tivemos até hoje. \n\nNós vamos aonde as areias nos levam.', 28153),
(158248, 'ptBR', 'Minha caravana vive nestas areias desde antes de eu nascer. \n\nHá outras nas terras além-mar, embora eu nunca tenha visto pessoalmente.', 'Minha caravana vive nestas areias desde antes de eu nascer. \n\nHá outras nas terras além-mar, embora eu nunca tenha visto pessoalmente.', 28153),
(158247, 'ptBR', 'Tolice. Você e seu povo se portaram de forma admirável, Magíster. Você é um aliado valioso para a Aliança.', '', 28153),
(158246, 'ptBR', 'Em nome de todos os elfos caóticos, eu peço desculpas pelo nosso fracasso.', '', 28153),
(158245, 'ptBR', '', 'Nós temos que ir para a Colina da Vigília. Sobe aí!', 28153),
(158244, 'ptBR', 'Kua\'fon solta um trinado alegre e se enrosca para tirar um cochilo.', '', 28153),
(158243, 'ptBR', 'O aldeão geme de dor.', 'A aldeã geme de dor.', 28153),
(158242, 'ptBR', 'Mok\'rah, $n! O posto avançado está às suas ordens.', '', 28153),
(158241, 'ptBR', '', 'Hunf.', 28153),
(158240, 'ptBR', 'Seus esforços serão vastamente recompensados.', '', 28153),
(158239, 'ptBR', '', 'Nathanos, eu falei que a sua Horda podia usar meu porto como base. Mas não dei permissão para trazerem a frota de Proudmore até aqui!', 28153),
(158238, 'ptBR', 'O Cetro é um artefato de imenso poder sobre o mar. Com ele, teremos uma grande vantagem sobre a frota de Kul Tiraz.', '', 28153),
(158237, 'ptBR', '', 'Como você vai entrar? Não dá para simplesmente entrar em Boralus...', 28153),
(158236, 'ptBR', 'Mandei Valentim para Boralus com uma mensagem para a Grã-senhora Proudmore que deve ser entregue a qualquer custo: Estamos com seu filho.', '', 28153),
(158235, 'ptBR', 'Calma, meus amigos. Este pirata há de pagar por seus crimes. No entanto, é preciso esperar a sentença final emitida pela corte.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158234, 'ptBR', 'Nossa missão aqui é recuperar o Cetro Abissal, localizado nas profundezas do Monastério de Trovamare, em Boralus.', '', 28153),
(158233, 'ptBR', '', 'Entre, $n. Nathanos vai lhe passar todas as informações.', 28153),
(158232, 'ptBR', 'A corte considera você culpado do crime de usura. Seus empréstimos predatórios dizimaram as economias do povo da Ponta do Gancho. Muitos agora vivem pelas ruas, devido aos seus malfeitos.', '', 28153),
(158231, 'ptBR', 'A corte julga você culpado dos crimes de pirataria, roubo e assassinato. A pirataria é um dos crimes mais abjetos sob a lei kultirena, portanto você será submetido à justiça.', '', 28153),
(158230, 'ptBR', 'Extorsão e prevaricação! Muitas das famílias aqui hoje foram vítimas dos seus esquemas. Você se beneficiou cobrando preços altíssimos do bondoso povo de Kul Tiraz, agora terá de enfrentar as consequências do que fez.', '', 28153),
(158229, 'ptBR', 'Venham comigo. Vamos até onde estão Alleria e o Alto-comandante.', '', 28153),
(158228, 'ptBR', 'Não é a vitória absoluta que eu esperava obter para a Aliança, mas não acrescentarei a impontualidade à minha lista de defeitos.', '', 28153),
(158227, 'ptBR', 'Passamos todo esse tempo atrás de uma sombra de Gallywix? Goblins são mesmo terríveis.', '', 28153),
(158226, 'ptBR', 'Até mais, otários!', '', 28153),
(158225, 'ptBR', 'Mas esses trajes mecanoides não são baratos, $p. A conta desse prejuízo vai chegar na tua casa!', '', 28153),
(158224, 'ptBR', 'Você caiu num velho truque de Borraquilha: qualidade alta, salários baixos!', '', 28153),
(158223, 'ptBR', 'Rá! Só queria que vocês vissem cara de vocês...', '', 28153),
(158222, 'ptBR', '', 'Só a ideia de um espírito poder escapar do Bwonsamdi já é impressionante. Espero que os laços com os amigos dele sejam suficientes pra conseguir contatar ele do Outro Lado.', 28153),
(158221, 'ptBR', '$n, há um telescópio no lado oeste do acampamento. Por que você não vai procurar ele?', '', 28153),
(158220, 'ptBR', 'Hmm... é, onde está Gusberto? Ele deveria despontar na esquina mais ou menos agora.', '', 28153),
(158219, 'ptBR', '', 'Eu voltei antes de todo mundo? Cadê o Gusba?', 28153),
(158218, 'ptBR', 'Bem-vinda de volta, srta. Fagulhaço.', '', 28153),
(158217, 'ptBR', '', 'Ei, chefe! Ouviu um \"cabum\"? Acho que eu coloquei um goblin em órbita.', 28153),
(158216, 'ptBR', 'Gusberto e Kelsey devem chegar daqui a pouco.', '', 28153),
(158215, 'ptBR', 'Rá! O que foi que o mundo fez por mim?', '', 28153),
(158214, 'ptBR', 'Seu ego é tão inchado quanto seu corpo. Imagine todo o bem que você poderia ter feito a este mundo!', '', 28153),
(158213, 'ptBR', 'Você amealhou essa riqueza toda para construir isso, Gallywix? Um covil de depravação?!', '', 28153),
(158212, 'ptBR', '', 'Use Vivificar para recuperar completamente seus pontos de vida.', 28153),
(158211, 'ptBR', 'Use Vivificar para recuperar completamente seus pontos de vida.', '', 28153),
(158210, 'ptBR', '', 'Receber dano faz parte da batalha, mas você pode usar as brumas espirituais para curar a si $Upróprio:própria; e a seus aliados. Use Vivificar para fechar suas feridas.', 28153),
(158209, 'ptBR', 'Receber dano faz parte da batalha, mas você pode usar as brumas espirituais para curar a si $Upróprio:própria; e a seus aliados. Use Vivificar para fechar suas feridas.', '', 28153),
(158208, 'ptBR', 'A Aliança foi derrotada!', '', 28153),
(158207, 'ptBR', '|A:Warfront-HordeWave3:25:23:0:0|aA Uma força de ataque da Horda foi lançada!', '|A:Warfront-HordeWave3:25:23:0:0|aA Uma força de ataque da Horda foi lançada!', 28153),
(158206, 'ptBR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aPerdemos a Passagem Clamabravo!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aPerdemos a Passagem Clamabravo!', 28153),
(158205, 'ptBR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aPerdemos Novaterra!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aPerdemos Novaterra!', 28153),
(158204, 'ptBR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aPerdemos o Círculo dos Elementos!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aPerdemos o Círculo dos Elementos!', 28153),
(158203, 'ptBR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aPerdemos a Alcândora!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aPerdemos a Alcândora!', 28153),
(158202, 'ptBR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aPerdemos a Encruzilhada do Aprisco Norte!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aPerdemos a Encruzilhada do Aprisco Norte!', 28153),
(158201, 'ptBR', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|aPerdemos o Veio do Galson!', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|aPerdemos o Veio do Galson!', 28153),
(158200, 'ptBR', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|aPerdemos a Serraria do Planalto!', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|aPerdemos a Serraria do Planalto!', 28153),
(158199, 'ptBR', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aO Veio do Galson está sendo atacado!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aO Veio do Galson está sendo atacado!', 28153),
(158198, 'ptBR', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aA Serraria do Planalto está sendo atacada!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aA Serraria do Planalto está sendo atacada!', 28153),
(158197, 'ptBR', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|aSeu comandante está sendo atacado!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aSeu Comandante está sob ataque!', 28153),
(158196, 'ptBR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aA Passagem Clamabravo está sendo atacada!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aA Passagem Clamabravo está sendo atacada!', 28153),
(158195, 'ptBR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aNovaterra está sendo atacada!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aNovaterra está sendo atacada!', 28153),
(158194, 'ptBR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aO Círculo dos Elementos está sendo atacado!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aO Círculo dos Elementos está sendo atacado!', 28153),
(158193, 'ptBR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aA Encruzilhada do Aprisco Norte está sendo atacada!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aA Encruzilhada do Aprisco Norte está sendo atacada!', 28153),
(158192, 'ptBR', 'Apertar o grande botão vermelho quando você mandar. Entendido.', 'Apertar o grande botão vermelho quando você mandar. Entendido.', 28153),
(158191, 'ptBR', 'Mostre-me para onde posso voar.', 'Mostre-me para onde posso voar.', 28153),
(158190, 'ptBR', 'Quer voar pra algum canto?', '', 28153),
(158189, 'ptBR', 'Um lance mais alto de novo! Há quem não se importe mesmo em lucrar com a desgraça alheia, não é?', 'Um lance mais alto de novo! Há quem não se importe mesmo em lucrar com a desgraça alheia, não é?', 28153),
(158188, 'ptBR', 'Não temos nada de valor para vender.', 'Não temos nada de valor para vender.', 28153),
(158187, 'ptBR', 'Espero que tenhamos o suficiente para comprar os suprimentos de que precisamos.', 'Espero que tenhamos o suficiente para comprar os suprimentos de que precisamos.', 28153),
(158186, 'ptBR', 'Quanto ouro nós ainda temos?', 'Quanto ouro nós ainda temos?', 28153),
(158185, 'ptBR', 'Não há provisões suficientes...', 'Não há provisões suficientes...', 28153),
(158183, 'ptBR', 'Cuidado na estrada, viajante. Há coisas estranhas nas sombras de Drustvar.', 'Cuidado na estrada, viajante. Há coisas estranhas nas sombras de Drustvar.', 28153),
(158182, 'ptBR', 'Opa... Opa... O traje deu defeito!', '', 28153),
(158181, 'ptBR', 'Os corvos estão observando! A gargalhada não para! Eles vêm atrás de mim!', '', 28153),
(158180, 'ptBR', '', 'Você me fez... derrubar... minha bebida...', 28153),
(158179, 'ptBR', '', 'Tá achando que consegue me tapear, NÉ?! Eu <hic> vou te mostrar o que é bom pra tosse!', 28153),
(158178, 'ptBR', '', 'Bom trabalho. Nos vemos do outro lado do acampamento.', 28153),
(158177, 'ptBR', 'Olha isso, Gallywix!', 'Olha isso, Gallywix!', 28153),
(158176, 'ptBR', 'Aliança? Aqui em Zandalar?', '', 28153),
(158175, 'ptBR', 'Nós nos movemos com as areias.', 'Nós nos movemos com as areias.', 28153),
(158174, 'ptBR', 'As dunas estão repletas de tesouros esperando para ser encontrados.', 'As dunas estão repletas de tesouros esperando para ser encontrados.', 28153),
(158173, 'ptBR', 'Lar é onde a carroça está.', 'Lar é onde a carroça está.', 28153),
(158171, 'ptBR', '|TInterface\\Icons\\INV_Mace_2H_CapturedTitanConstruct_D_01:20|t%s está alvejando você com |cFFFF0000|Hspell:271296|h[Clava do Escorno]|h|r!', '', 28153),
(158170, 'ptBR', '', 'Pobres almas… ninguém merece sofrer isso. Depois que terminarmos, temos que voltar para ajudar.', 28153),
(158169, 'ptBR', 'Uma coisa é certa, Drustvar enlouqueceu.', 'Uma coisa é certa, Drustvar enlouqueceu.', 28153),
(158168, 'ptBR', 'Eu ouvi um falar sobre cervos devoradores de carne humana.', 'Eu ouvi um falar sobre cervos devoradores de carne humana.', 28153),
(158167, 'ptBR', 'As histórias de homens-fera e demônios de madeira? Aham, eu ouvi eles falando disso.', 'As histórias de homens-fera e demônios de madeira? Aham, eu ouvi eles falando disso.', 28153),
(158166, 'ptBR', 'Você ouviu o que eles estavam dizendo? Por que esses refugiados vieram para cá?', 'Você ouviu o que eles estavam dizendo? Por que esses refugiados vieram para cá?', 28153),
(158165, 'ptBR', 'Tem dias que, zumbindo com a boca, eu acho que consigo me comunicar com as minhas abelhas, mas provavelmente não vai funcionar enquanto eu não terminar minha fantasia de abelha. Mas isso não importa, minhas abelhas são as melhores das redondezas. Vai encarar ou sair tinindo?', '', 28153),
(158164, 'ptBR', '', 'Que nosso ânimo seja mais forte do que as máquinas de guerra.', 28153),
(158163, 'ptBR', 'Seus feitos jamais serão esquecidos pelos kaldorei, $n. Sua ajuda fará toda a diferença nesses tempos difíceis.', '', 28153),
(158162, 'ptBR', 'A provação que enfrentamos é grande, mas não se desesperem. A deusa nos dará força, temos que ter fé.', '', 28153),
(158161, 'ptBR', 'Uma guerra não se vence nem se perde numa única batalha. Nosso dia chegará.', '', 28153),
(158160, 'ptBR', 'O Rei Anduin mandará seus soldados para nos ajudar. Temos que resistir até eles chegarem.', '', 28153),
(158159, 'ptBR', 'Nossa frota regressou de Silithus. Graças a Eluna! Precisamos dela desesperadamente.', '', 28153),
(158158, 'ptBR', 'Embora a muralha continue de pé, as forças da Horda já invadem a Costa Negra.', '', 28153),
(158157, 'ptBR', 'Isso abalou o moral inimigo. Nunca subestime o valor da guerra psicológica.', '', 28153),
(158156, 'ptBR', 'Você disse palavras duras para Nathanos.', 'Você disse palavras duras para Nathanos.', 28153),
(158155, 'ptBR', 'Os piratas da Angra do Facão estão cada vez mais atrevidos. Temos que semear o caos entre os inimigos. Pegue uma das montarias deles e vá bombardeá-los!', '', 28153),
(158154, 'ptBR', '', 'Todo marinheiro teme o canto das sirenas. Uns mais do que os outros.', 28153),
(158153, 'ptBR', '', 'As sirenas capturaram outro navio de carga kultireno. Vasculhe o naufrágio, busque o que for aproveitável. Cuidado, não acabe como a tripulação!', 28153),
(158152, 'ptBR', 'Uma sina pior que a morte espera por você...', '', 28153),
(158151, 'ptBR', 'Você acha que venceu!? Minha queda é só o início da sua ruína!', '', 28153),
(158150, 'ptBR', 'Bom trabalho. O adversário não terá com o que nos desafiar.', '', 28153),
(158149, 'ptBR', 'Não podemos deixar os kultirenos produzirem mais munição de azerita. Acabe com a linha de montagem na fundição!', '', 28153),
(158148, 'ptBR', '', 'Quando fanáticos duvidam da sua lealdade, seus dias estão contados.\n\nEu fui convocada para esta campanha. Talvez você também tenha sido. Temos que fazer o que for preciso para sobreviver.\n\nMas uma coisa você tem que saber: somente uma guerra importa. E não é esta.', 28153),
(158147, 'ptBR', 'Vocês sofrerão a mesma sina que ela…', '', 28153),
(158146, 'ptBR', 'É tarde demais para salvá-la...', '', 28153),
(158145, 'ptBR', 'O tormento espera todos vocês...', '', 28153),
(158144, 'ptBR', 'Ela já está condenada...', '', 28153),
(158143, 'ptBR', 'A vingança se aproxima!', '', 28153),
(158142, 'ptBR', 'A menina é nossa!', '', 28153),
(158141, 'ptBR', 'Também consumiremos vocês!', '', 28153),
(158140, 'ptBR', 'Você compartilhará do sofrimento dela!', '', 28153),
(158139, 'ptBR', '', 'Eu trabalho nesta área já faz tempo suficiente pra ter visto manifestações bem interessantes dessa tal de azerita. Quer ver como você se sai contra uns elementais de azerita descontrolados que eu andei juntando na surdina?', 28153),
(158138, 'ptBR', 'TOLOS! Vocês brincam com poderes além da sua compreensão!', '', 28153),
(158137, 'ptBR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aA Alcândora está sendo atacada!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aA Alcândora está sendo atacada!', 28153),
(158136, 'ptBR', '', 'Não exatamente. Quando a oportunidade bate à porta, você tem que aproveitar.\n\nEu sempre tive planos para o futuro. Chegou a hora de trabalhar para torná-los realidade.', 28153),
(158135, 'ptBR', 'Achei que você servisse aos Destronados. Você mudou de aliados?', 'Achei que você servisse aos Destronados. Você mudou de aliados?', 28153),
(158134, 'ptBR', 'Estou LIVRE! Eu agradeço... e agora vou saciar minha fome incomensurável com suas almas!', '', 28153),
(158133, 'ptBR', 'A região de que cuidaremos primeiro fica por sua conta. Faça sua escolha, e zarparemos imediatamente.', '', 28153),
(158132, 'ptBR', '', 'Bom trabalho. Deixe que os guardas cuidem dos retardatários. Vamos ter que ficar de olho na mansão.', 28153),
(158131, 'ptBR', '', 'Começou a sair aberração atrás de aberração na Mansão Capelo! Nós temos que detê-las antes que cheguem ao Brado de Arom!', 28153),
(158129, 'ptBR', 'Nós venceremos esta guerra, $n. Pela Aliança!', '', 28153),
(158128, 'ptBR', 'Elimine alvos descuidados nas terras trólicas. Sabote os planos da Chefe Guerreira em toda e qualquer oportunidade.', '', 28153),
(158127, 'ptBR', 'O território que você conquistou em Zandalar foi o primeiro passo ousado. Agora vamos usá-lo para bater de frente com a Horda!', '', 28153),
(158126, 'ptBR', 'Mas os ventos da guerra estão sempre mudando. É hora de mudar o foco da nossa campanha também.', '', 28153),
(158125, 'ptBR', 'Nunca senti tanta fome...', 'Nunca senti tanta fome...', 28153),
(158124, 'ptBR', 'Seu trabalho em Kul Tiraz foi crucial para a nossa causa. Só através da união é que a Aliança vai se fortalecer.', '', 28153),
(158123, 'ptBR', 'Pela Aliança!', '', 28153),
(158122, 'ptBR', 'Mas saiba que, pelo menos por enquanto, você serve de inspiração para todos ao seu redor. E por isso eu lhe sou grato.', '', 28153),
(158121, 'ptBR', 'A Aliança ainda precisa de você, $n. Já ficou claro que jamais acabaremos com o reinado da Chefe Guerreira enquanto não rompermos seus laços com os Zandalari. Esse dia há de chegar... muito em breve.', '', 28153),
(158120, 'ptBR', 'Quem me dera dar o trabalho por terminado, mas resta muito a ser feito. Nuvens ainda cobrem o nosso horizonte... mas o sol há de brilhar mais uma vez.', '', 28153),
(158119, 'ptBR', 'Você liderou uma longa campanha contra um inimigo implacável. E não é só isso, você enfrentou a Horda com coragem... e honra.', '', 28153),
(158118, 'ptBR', '', 'Pela Horda!', 28153),
(158117, 'ptBR', '', 'Você personifica tudo que há de melhor na Horda, $n. A faísca que incendiará Boralus vai ser você.', 28153),
(158116, 'ptBR', '', 'Kul Tiraz se tornou uma base importante para a Aliança. Ficaram atrevidos com o regresso daquela marinhazina deles. Mas já, já, aqueles cachorros dos mares vão pagar caro por ter nos desafiado.', 28153),
(158115, 'ptBR', '', 'A vitória ainda nos escapa, mas fica cada dia mais próxima. Não podemos descansar enquanto não apagarmos a última centelha de esperança no coração do reizinho.', 28153),
(158114, 'ptBR', '', 'O mundo está cheio de soldados, camarada. Mas poucos têm estômago para a guerra. Já você parece ter até gosto por ela.', 28153),
(158113, 'ptBR', '', 'Tire a esperança deles e a vitória será sua, $n. Pela Horda!', 28153),
(158112, 'ptBR', '', 'Use o território conquistado em Kul Tiraz para desfalcar as forças do reizinho. Vá testar a fé deles naquela causa vã.', 28153),
(158111, 'ptBR', '', 'Mas vencer não é só aumentar as próprias forças. Para vencer, temos que bater no inimigo até deixá-lo prostrado no chão.', 28153),
(158110, 'ptBR', '', 'Não há ninguém melhor para trazer os Zandalari para o nosso lado do que você.', 28153),
(158109, 'ptBR', '', 'Quando a Princesa Talanji veio pedir nossa ajuda, eu vi uma oportunidade de unir a força do reino dela à Horda.', 28153),
(158108, 'ptBR', 'A terra aqui tá morta. Isso é mau, cara. Mau à beça.', '', 28153),
(158107, 'ptBR', '', 'Aqueça as mãos e descanse os ossos, $c.', 28153),
(158106, 'ptBR', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t %s começa a lançar |cFFFF0000|Hspell:273361|h[Fonte das Trevas]|h|r!', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t %s começa a lançar |cFFFF0000|Hspell:273361|h[Fonte das Trevas]|h|r!', 28153),
(158105, 'ptBR', 'Boas-vindas ao Posto de Velozvento, $n. O posto avançado está sob o seu comando.', '', 28153),
(158104, 'ptBR', 'Eu devia... ter pagado... com a garantia estendida...', '', 28153),
(158103, 'ptBR', 'Diz oi pra Palácio da DOR do Gallywix, vigarista de uma figa!', '', 28153),
(158102, 'ptBR', 'Peça que Fozruk ataque Ar\'gorok.', 'Peça que Fozruk ataque Ar\'gorok.', 28153),
(158101, 'ptBR', 'A corrupção está se espalhando mais rápido do que eu imaginava...', '', 28153),
(158100, 'ptBR', 'Esses esporos não são normais. Precisamos descobrir a causa disso.', '', 28153),
(158099, 'ptBR', 'Nós fizemos o que foi possível. Que eles encontrem paz na vida eterna.', '', 28153),
(158098, 'ptBR', 'Os espíritos estão inquietos. Nós temos que botar fim nesse tormento.', '', 28153),
(158097, 'ptBR', '', 'Bom trabalho. Que eles descansem em paz.', 28153),
(158096, 'ptBR', '', 'Os espíritos estão inquietos. Devolva-lhes a paz.', 28153),
(158095, 'ptBR', '', 'Com os esporos, podemos encontrar a fonte da podridão e destruí-la.', 28153),
(158094, 'ptBR', '', 'A praga vem se espalhando depressa. Precisamos acabar com ela. Recolha os esporos para que possamos estudá-los.', 28153),
(158093, 'ptBR', 'Irmãos e irmãs! A Horda está avançando cada vez mais pela Costa Negra! Vamos nos reunir no Rio Crenado.', '', 28153),
(158092, 'ptBR', 'Você recebeu o poder do vento!', 'Você recebeu o poder do vento!', 28153),
(158091, 'ptBR', 'Eu quero esse ouro todo no palácio pra ontem, aí...', '', 28153),
(158090, 'ptBR', 'Nada de atraso! Nada de desculpa! Nada de promoção!', '', 28153),
(158089, 'ptBR', 'Sai da frente! A Aliança tá aqui!', '', 28153),
(158088, 'ptBR', 'Eu não vou morrer... pelas mãos de um goblin.', '', 28153),
(158087, 'ptBR', 'A Aliança está contando com os elfos caóticos. Não decepcionaremos.', '', 28153),
(158086, 'ptBR', 'Gallywiiiiix!', 'Gallywiiiiix!', 28153),
(158085, 'ptBR', 'Carambola! É a Aliança!', 'Carambola! É a Aliança!', 28153),
(158084, 'ptBR', '', 'A Horda deve ter expulsado os pelursos de suas terras.', 28153),
(158083, 'ptBR', '', 'A Horda... É gente demais...', 28153),
(158082, 'ptBR', 'Santo ouro! Estourou o cano de elfo!', 'Santo ouro! Estourou o cano de elfo!', 28153),
(158081, 'ptBR', '', 'A tribo dos pelursos geralmente é pacífica. Devem ter enlouquecido depois que foram expulsos de suas terras.', 28153),
(158078, 'ptBR', '', 'Eu caminho nas sombras.', 28153),
(158077, 'ptBR', '', 'Imediatamente!', 28153),
(158076, 'ptBR', '', 'Cuidado, camarada! Não podemos fazer barulho!', 28153),
(158075, 'ptBR', '', 'Mate o bicho logo, antes que avise os outros!', 28153),
(158074, 'ptBR', '', 'Muito cuidado! Não podemos chamar atenção...', 28153),
(158073, 'ptBR', 'Eu já desço, Lanfa!', '', 28153),
(158072, 'ptBR', '', 'Vá na frente, $n. Se quiser que eu derrube alguém, é só dizer... mas sem alarde.', 28153),
(158071, 'ptBR', 'Harli te leva lá e volta pra cá. Eu tenho que ver como tá a minha companheira!', '', 28153),
(158070, 'ptBR', 'Você deu uma lição neles. Vamos ver se agora eles aprendem.', '', 28153),
(158069, 'ptBR', 'Esses anões não estão sacando. Ninguém quer eles aqui. Mostra pra eles o que os Zandalari fazem com intrusos.', '', 28153),
(158068, 'ptBR', 'Se alguém tentar subir esta colina... matem!', '', 28153),
(158067, 'ptBR', 'Quando acabarmos com a frota, Zandalar será nossa!', '', 28153),
(158066, 'ptBR', 'Ergam esses pilares!', '', 28153),
(158065, 'ptBR', '<Aguarde um instante enquanto Genn convence Katherine numa animação incrível>', '<Aguarde um instante enquanto Genn convence Katherine numa animação incrível>', 28153),
(158064, 'ptBR', 'O povo de Kul Tiraz está unido, mas a casa que o lidera não, e a Aliança está sem uma de suas líderes mais poderosas.\n\nMinha esperança é também conseguir desfazer esta cisão.', '', 28153),
(158063, 'ptBR', 'Venha me encontrar no memorial da família perto da Fortaleza Proudmore. Com sorte, conseguiremos convencer a Lorde-almirante Proudmore a suspender a pena da filha.', '', 28153),
(158062, 'ptBR', 'Camarada, você ajudou a unir os kultirenos e arrebanhar o apoio deles em prol da Aliança. Talvez você consiga reatar os laços entre mãe e filha.', '', 28153),
(158061, 'ptBR', 'Barrar os suprimentos da Horda vai atrapalhar a investida deles. Você ganhou tempo.', '', 28153),
(158060, 'ptBR', 'Os goblins estão escavando atrás de combustível para as máquinas de guerra! Acabe com esses monstros!', '', 28153),
(158059, 'ptBR', '', 'Quanto mais o fogo queima, mais nós avançamos.', 28153),
(158058, 'ptBR', '', 'Os elementais servirão de combustível para os demolidores. Mate todos, e também os kaldorei que entrarem no caminho.', 28153),
(158057, 'ptBR', 'Podemos viajar através do Caos para economizar tempo. Venha comigo.', '', 28153),
(158056, 'ptBR', 'O Gallywix é escorregadio. Ele não vai ficar à vista por muito tempo.', '', 28153),
(158055, 'ptBR', 'Eu devia saber que um goblin feito o Gallywix não conseguiria resistir a saquear uma cidade literalmente feita de ouro.', '', 28153),
(158054, 'ptBR', '', 'Nós fomos vistos! Recolha o máximo de azerita que puder. Não podemos demorar muito!', 28153),
(158053, 'ptBR', '', 'Pela deusa... Tem azerita por toda parte!', 28153),
(158052, 'ptBR', 'Nodos de azerita estão surgindo por toda parte', 'Nodos de azerita estão surgindo por toda parte', 28153),
(158051, 'ptBR', '<Ponha a mão no nodo de azerita>.', '<Ponha a mão no nodo de azerita>.', 28153),
(158050, 'ptBR', '<O poder faz o nodo de azerita zumbir>.', '', 28153),
(158049, 'ptBR', '', 'Você fica com o retalhador! Eu vou expulsar os invasores do bosque!', 28153),
(158048, 'ptBR', 'O Bosque dos Ancientes! Minha nossa...', 'O Bosque dos Ancientes! Minha nossa...', 28153),
(158047, 'ptBR', 'Conte comigo!', 'Conte comigo!', 28153),
(158046, 'ptBR', 'Cuidado com os pelursos. Eles têm aparecido subitamente aos montes.', 'Cuidado com os pelursos. Eles têm aparecido subitamente aos montes.', 28153),
(158045, 'ptBR', 'Estou a caminho!', 'Estou a caminho!', 28153),
(158044, 'ptBR', 'Os pelursos parecem atipicamente agressivos...', 'Os pelursos parecem atipicamente agressivos...', 28153),
(158043, 'ptBR', '|TInterface\\Icons\\INV_misc_boilingblood:20|t%s está alvejando você com |cFFFF0000|Hspell:271224|h[Descarga de Plasma]|h|r!', '', 28153),
(158042, 'ptBR', 'Não subestime o valor do que você fez. Enquanto eles se recuperam da derrota, nós podemos firmar nossa posição na região.', '', 28153),
(158041, 'ptBR', 'A Horda quer expandir seu território na região. Não deixe isso acontecer, camarada!', '', 28153),
(158040, 'ptBR', '', 'O bando sobreviveu. Você se saiu bem.', 28153),
(158039, 'ptBR', '', 'Uma ninhada um tanto incomum precisa de ajuda. Ajude-os e você cairá nas graças de Gonk.', 28153),
(158038, 'ptBR', 'É uma incursão militar a menos para enfrentarmos. Excelente trabalho.', '', 28153),
(158037, 'ptBR', '', 'Zandalar para sempre!', 28153),
(158036, 'ptBR', '', 'Não fosse esse membro da Horda, nossas perdas teriam sido muito maiores.$bIsso mostra, mais do que nunca, que precisamos nos adaptar para voltar a fazer parte deste mundo.', 28153),
(158035, 'ptBR', '', 'Que a glaive dele sirva para nos lembrar de que, mesmo perdendo tudo, nós continuamos sendo Zandalari!$bNós nos adaptamos para sobreviver!', 28153),
(158034, 'ptBR', '', 'Por vontade dele, morreram tantos de nossos irmãos e irmãs.', 28153),
(158033, 'ptBR', '', 'Contemple o sangue de G\'huun. Por vontade dele, morreram Shadra, Hi\'reek, Torga e... e Rezan.', 28153),
(158032, 'ptBR', 'Os batedores avistaram um navio de guerra da Horda perto do litoral. Não deixe os reforços desembarcarem.', '', 28153),
(158031, 'ptBR', '', 'Isto não foi obra minha.', 28153),
(158030, 'ptBR', 'Todo cuidado é pouco neste lugar, camarada. Graças a você, nossos batedores não vão aposentar os disfarces.', '', 28153),
(158029, 'ptBR', 'Mostra a lâmina pra eles. Tu vai virar um símbolo.', '', 28153),
(158028, 'ptBR', 'Tu fez o que precisava fazer pra salvar tua gente. Agora mais do que nunca, eles precisam de um líder de confiança.', '', 28153),
(158027, 'ptBR', 'Tu trouxe uma pessoa que vive de aventuras contra a vontade do teu pai. Descobriu os segredos de G\'huun quando ninguém quis dar ouvidos.', '', 28153),
(158026, 'ptBR', 'Vários agentes da AVIN foram mandados para a nossa região, mas nenhum se apresentou ainda. Descubra o motivo do atraso e resolva a situação.', '', 28153),
(158025, 'ptBR', 'Mostra pra eles, líder dos Zandalar. Mostra a lâmina pra quem mais precisa ver. Dá paz pra esse povo.', '', 28153),
(158024, 'ptBR', '', 'Vol\'jin, você está ouvindo? Apareça, espírito.', 28153),
(158023, 'ptBR', 'A Horda pagará com sangue por cada palmo de terra que tentou conquistar. De vitória em vitória, a balança aos poucos pesará para o nosso lado. Bom trabalho.', '', 28153),
(158022, 'ptBR', 'Perdas... perdas. Quantas perdas. Tanta gente sem direção. Tanta gente injustiçada. A esperança roubada por G\'huun.', '', 28153),
(158021, 'ptBR', 'A Horda acha que pode fazer o que bem entender na região. Mostre a eles que estão equivocados, camarada.', '', 28153),
(158020, 'ptBR', '', 'Silêncio.', 28153),
(158019, 'ptBR', 'Eu ouvi a voz dele!', '', 28153),
(158018, 'ptBR', 'Perdas...', '', 28153),
(158017, 'ptBR', '', 'Vol\'jin, filho de Sen\'jin, ouça as vozes de seus amigos e familiares. Eles querem saber onde você está.', 28153),
(158016, 'ptBR', 'Colocando azerita', 'Colocando azerita', 28153),
(158015, 'ptBR', 'Você tem que defender o Bosque dos Ancientes!', 'Você tem que defender o Bosque dos Ancientes!', 28153),
(158014, 'ptBR', 'Eu sigo vigilante.', 'Eu sigo vigilante.', 28153),
(158013, 'ptBR', '<Ajudá-lo.>', '<Ajudá-lo.>', 28153),
(158012, 'ptBR', 'Eu vou ser sincero com você: nem é a pior situação em que eu já me meti.\n\nMas chega perto.', '', 28153),
(158011, 'ptBR', '', 'Camarada, os ancientes nos chamam! Vá falar com os Druidas da Garra na floresta e me encontre no Bosque dos Ancientes!', 28153),
(158009, 'ptBR', '', 'Isso nos dará um fôlego. Sentinelas, mantenham suas posições!', 28153),
(158008, 'ptBR', '', 'Não vi ninguém assim. Talvez seu amigo tenha se perdido com o chamado de uma sirena.', 28153),
(158007, 'ptBR', '<Perguntar se ela viu Filinto.>', '<Perguntar se ela viu Filinto.>', 28153),
(158006, 'ptBR', 'Se foi? Como assim, se foi? Eu exijo um reembolso!', 'Se foi? Como assim, se foi? Eu exijo um reembolso!', 28153),
(158005, 'ptBR', '', 'Você não é o único que solicita fichas à AVIN.', 28153),
(158004, 'ptBR', 'Como uma general élfica condecorada sabe alguma coisa sobre mim?', '', 28153),
(158003, 'ptBR', '', 'Você é um herói à sua maneira, Keeshan, desde seu serviço nas três primeiras guerras até os seus atos de heroísmo em Cristarrubra.', 28153),
(158002, 'ptBR', 'Para dizer a verdade, eu nem me sinto digno de servir ao seu lado. O mínimo que eu posso fazer é me calar e mostrar respeito.', '', 28153),
(158001, 'ptBR', 'Dona, eu li sua ficha da AVIN. Você nasceu a mais de dez mil anos atrás, lutou em mais guerras do que eu consigo imaginar.', '', 28153),
(158000, 'ptBR', '', 'Keeshan, pode ficar à vontade na minha presença.', 28153),
(157999, 'ptBR', 'Ela disse que deveria estar combatendo a Aliança, em vez de lidando com bobagens. Depois disso, eu percebi que ir embora era melhor do que fazer mais tratos por histórias.', '', 28153),
(157998, 'ptBR', 'A Areiel que vocês procuram está na Necrópole, na companhia de uma verdadeira hoste da Horda! Ela parecia um tanto incomodada com uma mensagem que recebeu.', '', 28153),
(157997, 'ptBR', 'Isso vai ser divertido! Eu digo o que vocês precisam saber, aí vocês podem me contar tudo sobre a vida na guerra.', '', 28153),
(157996, 'ptBR', '', 'Eu nasci a 10 mil anos atrás e lutei em todas as guerras. Eu vi a Nascente da Eternidade original com meus próprios olhos.', 28153),
(157995, 'ptBR', 'E eu servi nas três primeiras guerras, sobrevivi como prisioneiro de uma turba de orcs bárbaros e ajudei a matar um dragão negro.', '', 28153),
(157994, 'ptBR', 'Uma boa história! Era para eu ouvir histórias excelentes de Torga, mas ele está morto. Vocês têm alguma das boas?', '', 28153),
(157993, 'ptBR', 'Nós acabamos de salvar sua vida. Do que mais você precisa?', '', 28153),
(157992, 'ptBR', 'Eu posso lhe contar tudo sobre a Horda. Mas preciso de algo em troca.', '', 28153),
(157991, 'ptBR', 'Obrigado, dona.', '', 28153),
(157990, 'ptBR', '', 'Obrigada por toda a ajuda, $n e Keeshan. Eu agora tenho que prosseguir à caça de Dreven. Que Eluna ilumine seus caminhos.', 28153),
(157989, 'ptBR', 'Vai! Eu fico vigiando a lateral!', '', 28153),
(157988, 'ptBR', '', '$n, Keeshan, venham. Vamos retornar para o Forte da Vitória... e providenciar um enterro para os meus amigos.', 28153),
(157987, 'ptBR', '', 'Elfos ou humanos, somos todos iguais, Keeshan. Ninguém vale mais que ninguém.', 28153),
(157986, 'ptBR', 'Rapidinho... eu fico zero-bala... mas não devia ter sido eu. Seus amigos é que deviam ter sobrevivido.', '', 28153),
(157985, 'ptBR', '', 'Keeshan! Graças a Eluna, pelo menos alguém sobreviveu ao massacre.', 28153),
(157984, 'ptBR', '<cof> Dona... eu ainda... não morri. Parece que o poder dele... não é grandes coisas... sem aqueles lacaios.', '', 28153),
(157983, 'ptBR', '', 'Falia... Lyrias... Aeolyn... Keeshan... Eu juro, $n, Dreven vai pagar!', 28153),
(157982, 'ptBR', 'Augh!', '', 28153),
(157981, 'ptBR', 'Eu jamais cederei, Shandris Plumaluna. Veja como seus aliados são débeis!', '', 28153),
(157980, 'ptBR', 'É melhor a gente meter o pé. Deixa que os espíritos encontram o Bwonsamdi sozinhos.', '', 28153),
(157979, 'ptBR', 'Os trolls sangrentos vão voltar, disso eu não tenho dúvida. Mas agora eles sabem que nem em casa estão seguros. Vão pensar duas vezes antes de atacar a gente.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157978, 'ptBR', '', 'Shandris... prossiga... sem mim...', 28153),
(157977, 'ptBR', 'Andei dando uma olhada mais pra frente, pra ajeitar um ponto de encontro. Te espero na frente do vilarejo.', '', 28153),
(157976, 'ptBR', 'Abrace a morte comigo, elfa noturna!', '', 28153),
(157975, 'ptBR', 'Hora de mostrar do que este humano deplorável é capaz!', '', 28153),
(157974, 'ptBR', '', 'Derrubem o escudo! Aproveitem a oportunidade! Nós tomaremos Stromgarde!', 28153),
(157973, 'ptBR', '', 'Todos os canhões... FOGO!', 28153),
(157972, 'ptBR', '', 'Sim?', 28153),
(157971, 'ptBR', 'Eles certamente vão permitir que busquemos nossos pertences. Quando a fumaça clarear, digo.', 'Eles certamente vão permitir que busquemos nossos pertences. Quando a fumaça clarear, digo.', 28153),
(157970, 'ptBR', 'Tudo o que tínhamos estava guardado no Ramo dos Eternos!', 'Tudo o que tínhamos estava guardado no Ramo dos Eternos!', 28153),
(157969, 'ptBR', 'Você vai desejar ter queimado com Darnassus!', '', 28153),
(157968, 'ptBR', 'Shandris Plumaluna tentando uma emboscada? Ousado.', '', 28153),
(157967, 'ptBR', 'Talvez um humano tão deplorável sirva para dar o exemplo.', '', 28153),
(157966, 'ptBR', '', 'A matança termina hoje, Dreven.', 28153),
(157965, 'ptBR', 'Quantos mais da sua gente eu terei de matar para que vocês aprendam a ficar fora do nosso caminho?', '', 28153),
(157964, 'ptBR', 'A Aliança. Eu sabia que vocês seriam idiotas demais para aprender a lição no nosso último encontro.', '', 28153),
(157963, 'ptBR', 'Parece que tá na hora de tirar as aranhas de batalha ruins e botar umas aranhas de batalha boas.', '', 28153),
(157962, 'ptBR', 'Um cara, três aranhas, 26 pernas no total. Você não tinha chance.', '', 28153),
(157961, 'ptBR', 'Quando uma cai, aparece outra no lugar!', '', 28153),
(157960, 'ptBR', 'Calma, pequena. Você vai nos ajudar?', 'Calma, pequena. Você vai nos ajudar?', 28153),
(157959, 'ptBR', '<Flicka olha para você com desconfiança.>\n\nFlicka?', '', 28153),
(157958, 'ptBR', 'É, é isso aí. A gente é mau, pior que pica-pau, terror da capital!', '', 28153),
(157957, 'ptBR', 'Estou pronto para matar Dreven e seus seguidores.', 'Estou pronta para matar Dreven e seus seguidores.', 28153),
(157956, 'ptBR', 'Oi, meu nome é Dagoberto Mascarenhas, Gerenciamento de Infestações. Uma batalha com outro entusiasta de aracnoides é sempre muito bem-vinda.', '', 28153),
(157955, 'ptBR', 'Parece que nós somos a isca para um grupo de elfos sanguessugas famintos. Pront$Uo:a; para o que der e vier?', '', 28153),
(157954, 'ptBR', '', 'Eu vou alertar os outros, Keeshan vai encontrar você nos túneis.', 28153),
(157953, 'ptBR', '', 'É assim que se faz. Deixe o resto conosco.', 28153),
(157952, 'ptBR', '', 'Forças da Horda passaram pelas defesas! Eles estão tentando montar uma base! Bote-os para correr com o dragão feérico!', 28153),
(157951, 'ptBR', 'Se andar pelo matagal aqui perto, você pode achar que aranhas não gostam da brisa e do ar fresco, mas no que diz respeito a isso, aranhas são iguaizinhas a mim e a você. Além do mais, as teias de aranha dão uma bela dica da presença de aracnoides.', '', 28153),
(157950, 'ptBR', '', 'Nos encontramos nas Ruínas de Zo\'bal. Tome cuidado.', 28153),
(157949, 'ptBR', 'Ah, o calor da caçada. Não tem coisa melhor, aproveite.', '', 28153),
(157948, 'ptBR', '', 'Descanso para os exaustos, comida para os famintos.', 28153),
(157947, 'ptBR', 'Sempre, Princesa.', '', 28153),
(157946, 'ptBR', '', 'Entendo. Eu vou voltar para Zuldazar. Me mantenham informada das operações da Horda em Nazmir. E tenha cuidado, Rokhan.', 28153),
(157945, 'ptBR', 'Sylvana quer dar uma chance a eles. Eles não têm mais casa. Se puderem dar uma força pra gente, a Horda aceita eles. Se não, eles já eram.', '', 28153),
(157944, 'ptBR', 'Um predador alado aterroriza os mares, atacando todos os navios que despachamos para Kul Tiraz. Acabe com ele.', '', 28153),
(157943, 'ptBR', '', 'Eu não confio nesse Dreven, Rokhan. Não é lá muito sábio envolver os San\'layn neste conflito.', 28153),
(157942, 'ptBR', 'Farei o que me pede, por ora. Limparemos o túnel e mandaremos avisar quando sua tropas puderem se mover.', '', 28153),
(157941, 'ptBR', 'Por que fazia parte do teu acordo com a Sylvana respeitar a hierarquia e a autoridade da Horda. E mermão, meu ranque é mais alto que o teu.', '', 28153),
(157940, 'ptBR', 'Você quer que usemos nossas habilidades... para tirar pedras do caminho. E por que eu deveria lhe seguir, troll?', '', 28153),
(157939, 'ptBR', 'Tem um túnel desabado que liga Nazmir e Vol\'dun. Leva os seus seguidores, usa seus poderes pra limpar os escombros que a gente atacar as forças principais da Aliança.', '', 28153),
(157938, 'ptBR', '', 'Ao sul daqui tem um túnel desabado que liga Nazmir e Vol\'dun. Libera ele que a Horda vai poder atacar a base principal da Aliança em Vol\'dun sem dificuldade.', 28153),
(157937, 'ptBR', 'A Sylvana não vai gostar de saber. A gente tem que acelerar o plano de barrar a Aliança, Príncipe Dreven.', '', 28153),
(157936, 'ptBR', 'Digamos que é uma das minhas habilidades especiais. A Aliança deteve as forças da Horda na Necrópole e, no processo, matou Areiel.', '', 28153),
(157935, 'ptBR', '', 'Me chame de Princesa Talanji, Príncipe Dreven. E como você sabe?', 28153),
(157934, 'ptBR', 'A Capitã Areiel não vem porque está morta, Talanji.', '', 28153),
(157933, 'ptBR', '', 'Mas ela não está aqui. Ela está ocupada demais para transmitir um simples relatório?', 28153),
(157932, 'ptBR', 'A Areiel tá matando as forças da Aliança e dos trolls sangrentos. Ela ajudou a gente a estabelecer uma base na Necrópole.', '', 28153),
(157931, 'ptBR', '', 'Desculpa a demora, Rokhan. Como estão as coisas aqui? A Capitão Areiel tá sendo útil?', 28153),
(157930, 'ptBR', 'Princesa, valeu por ter vindo lá de Zandalar. A gente tá suando aqui pra repelir os trolls sangrentos e os invasores da Aliança.', '', 28153),
(157929, 'ptBR', '', 'Bem-vind$Uo:a;, $n. O posto avançado está sob o seu comando.', 28153),
(157927, 'ptBR', 'Eu estou ao seu serviço.', '', 28153),
(157926, 'ptBR', '(Pegar o frasco de invisibilidade.)', '(Pegar o frasco de invisibilidade.)', 28153),
(157925, 'ptBR', '', 'Fique escondid$Uo:a;. Só um de nós deve entrar. Eu vou ficar aqui para não deixar que ninguém descubra o que estamos fazendo.\n\nTenho um frasco da invisibilidade que você pode usar para entrar sorrateiramente. Ele deve te deixar totalmente invisível... por pouco tempo.\n\nBeba o frasco e entre nas ruínas. Descubra o que a Horda está planejando e saia de lá.', 28153),
(157924, 'ptBR', 'Temo que mesmo as pequenas vitórias estejam apenas postergando o inevitável.', '', 28153),
(157923, 'ptBR', 'Estamos conseguindo conter a Horda, mas a atenção deles se voltou para uma erupção de azerita na costa. Temos que detê-los.', '', 28153),
(157920, 'ptBR', 'Mais perto, amoreco. Wunja é cega, mas não surda! Hihihi! Veio até Wunja atrás de uma poção?', 'Mais perto, amoreco. Wunja é cega, mas não surda! Hihihi! Veio até Wunja atrás de uma poção?', 28153),
(157919, 'ptBR', '', 'O Gezão não vai gostar disso...', 28153),
(157918, 'ptBR', '', 'Eu vou te explodir, e vai ser pela boca!', 28153),
(157917, 'ptBR', 'Meu povo está pronto, $p. Pela Aliança.', '', 28153),
(157916, 'ptBR', '', 'Então você vem comigo, $p. Nos vemos no acampamento do Relicário.', 28153),
(157915, 'ptBR', 'Vamos indo, Fusivoide.', '', 28153),
(157914, 'ptBR', 'Eu lutei nas três guerras. Achei que tinha visto o pior que Azeroth tem a oferecer.\n\nLedo engano.', '', 28153),
(157913, 'ptBR', '', 'Eu tenho uma coisa que pode ajudar.', 28153),
(157912, 'ptBR', '', 'Só falta você, her$Uói:oína;. Vá se apresentar à Capitã Lunestio e reforce a fronteira!', 28153),
(157911, 'ptBR', '', 'Arqueiros de Hipogrifo, venham comigo. Vamos nos reagrupar em Lor\'danel, onde permaneceremos de prontidão como unidade de resposta móvel!', 28153),
(157910, 'ptBR', '', 'Sentinelas, criem uma linha de batalha no Rio Crenado! Ajudem nossos aliados no Bosque dos Ancientes!', 28153),
(157909, 'ptBR', '', 'Caçadoras, vocês precisam reforçar a fronteira meridional da Costa Negra! Tragam os lançadores de glaives!', 28153),
(157908, 'ptBR', '', 'Temos que agir! Sentinelas, avançar!', 28153),
(157907, 'ptBR', 'Capitã, a Horda já chegou ao Rio Crenado! Não conseguiremos segurá-los por muito tempo!', 'Capitã, a Horda já chegou ao Rio Crenado! Não conseguiremos segurá-los por muito tempo!', 28153),
(157906, 'ptBR', 'Uma alpaca! Oba!', '', 28153),
(157905, 'ptBR', 'Tem certeza?', 'Tem certeza?', 28153),
(157904, 'ptBR', '', 'Sim, senhor!', 28153),
(157903, 'ptBR', '<Apenas atacar.>', '<Apenas atacar.>', 28153),
(157902, 'ptBR', 'Que tal um pouco de ouro?', 'Que tal um pouco de ouro?', 28153),
(157900, 'ptBR', 'Se Sylvana quer me enfrentar, é isso que ela vai ter. Já mandei uma mensagem para os nossos navios. Se Eluna quiser, eles estarão de volta logo.', '', 28153),
(157899, 'ptBR', '$n, vou pedir a você que cuide da defesa de Darnassus.', '', 28153),
(157898, 'ptBR', 'Delaryn, passe pelos postos avançados. Reúna todos os soldados que encontrar e traga-os para cá.', '', 28153),
(157897, 'ptBR', '', 'E você, Shan\'do?', 28153),
(157896, 'ptBR', 'A Rainha Banshee quer capturar a Árvore do Mundo.', '', 28153),
(157895, 'ptBR', '', 'Malfurion! Forças da Horda se reuniram no Assentamento Zoram\'gar.', 28153),
(157894, 'ptBR', 'Você pode passar pela muralha, $n. Os fogos-fátuos não lhe farão nada.', '', 28153),
(157893, 'ptBR', '', 'Mesmo tão perto do fim, você é incapaz de enxergar o verdadeiro potencial dos humanos.', 28153),
(157892, 'ptBR', '', 'E você, ainda presa à sua visão ultrapassada dos humanos. Eu devia ter te matado há muito tempo.', 28153),
(157891, 'ptBR', '', 'Meu destino é viver por toda eternidade. Eu não morrerei aqui!', 28153),
(157890, 'ptBR', '', 'É uma pena que esteja lutando ao lado desse ser humano imundo, Shandris! Vidas tão curtas, tão insignificantes.', 28153),
(157889, 'ptBR', '', 'Shandris, já faz, o quê... dois, três mil anos? Que jeito de nos reencontrarmos. E com você ajudando um ser humano, ainda por cima.', 28153),
(157888, 'ptBR', '', 'Escuridão... Sylvana... foi isso que você viu... aquilo de que você queria nos salvar?', 28153),
(157887, 'ptBR', '', 'E eu que achava que seria uma simples missão de reconhecimento. Vou gostar disso!', 28153),
(157886, 'ptBR', '', 'Acabou. Encontre os planos dela e volte para a Guarda de Camporrubro quando tiver terminado.', 28153),
(157885, 'ptBR', '|cFF0000FF(Missão)|r Zarpar para Xibala, em Zuldazar.', '|cFF0000FF(Missão)|r Zarpar para Xibala, em Zuldazar.', 28153),
(157884, 'ptBR', 'Bom trabalho! Com a criatura morta, nossas tropas poderão passar pela região desimpedidas.', '', 28153),
(157883, 'ptBR', 'O rum é pros Maré-férrea de verdade. Tira a mão!', 'O rum é pros Maré-férrea de verdade. Tira a mão!', 28153),
(157882, 'ptBR', 'Já é difícil estabelecer uma rota de abastecimento no meio do pântano sem monstros mágicos no caminho. Dê cabo do bicho para liberar a passagem.', '', 28153),
(157881, 'ptBR', '', 'Bom trabalho! Essa daí não incomoda mais.', 28153),
(157880, 'ptBR', '', 'A criatura se alimenta de mojos perversos! Devolva as almas para o Bwonsamdi.', 28153),
(157879, 'ptBR', '', 'Outra vitória.', 28153),
(157878, 'ptBR', 'Tu tem que aprender que quem interrompe o Bwonsamdi paga um preço! Que tal fazer uma viagenzinha?', '', 28153),
(157877, 'ptBR', '', 'Meus batedores relataram uma erupção súbita de azerita aqui na Costa Negra. Ajude nossos aliados goblins a tomar o controle da azerita.', 28153),
(157876, 'ptBR', 'Não chega perto demais do Bwonsamdi!', 'Não chega perto demais do Bwonsamdi!', 28153),
(157875, 'ptBR', 'As orelhas?$B$BHm, o nome disso é estilo, OBVIAMENTE.', '', 28153),
(157874, 'ptBR', 'Hozens ladrões. Acho bom não estar faltando nenhum rum.', 'Hozens ladrões. Acho bom não estar faltando nenhum rum.', 28153),
(157873, 'ptBR', 'Ratos de porão inúteis, parem de beber o rum!', 'Ratos de porão inúteis, parem de beber o rum!', 28153),
(157872, 'ptBR', 'Romper a aliança entre a Horda e os Zandalari é nossa maior prioridade. Para tal, vamos precisar de bases no território inimigo.', '', 28153),
(157871, 'ptBR', 'Hora de mostrar à Horda que a 7ª Legião não brinca em serviço, $n.', '', 28153),
(157870, 'ptBR', '', 'Soldados... Não! Não apressem...', 28153),
(157869, 'ptBR', 'Hum, esse negócio está ligado? Alô? Certo...', '', 28153),
(157868, 'ptBR', 'Ha, você botou eles para correr! Vai demorar um tempo para mobilizarem suas forças agora. Bom trabalho.', '', 28153),
(157867, 'ptBR', 'Nós capturamos outra máquina de guerra da Horda. É hora de virar o jogo contra eles!', '', 28153),
(157866, 'ptBR', 'Não! Não! Impossível! O chefe vai ficar fulo da vida. O velho Bwonsamdi não pode perder um espírito assim... ah, miséria.', '', 28153),
(157865, 'ptBR', 'E aí, Vol\'jin? Sai dessa urna. Espera... peraí, peraí... não! Cadê aquele espírito?! Cadê o Vol\'jin?', '', 28153),
(157864, 'ptBR', 'Te pica, camarada. Não tem nada pra tu aqui.', '', 28153),
(157863, 'ptBR', 'Felizmente, os trabalhadores não parecem se importar conosco bisbilhotando por aí... só os capangas da companhia.\n\nEntendeu o que a gente precisa fazer?', '', 28153),
(157862, 'ptBR', 'Muito foi alcançado aqui hoje. Podemos nos reagrupar do lado de fora.', 'Muito foi alcançado aqui hoje. Podemos nos reagrupar do lado de fora.', 28153),
(157861, 'ptBR', '', 'Temos que deter Jakra\'zet.', 28153),
(157860, 'ptBR', 'O que o rei está fazendo quanto à nossa terra natal?', 'O que o rei está fazendo quanto à nossa terra natal?', 28153),
(157859, 'ptBR', 'Os recursos de Ventobravo ficam cada vez mais escassos. Não vai haver o suficiente para manter todos nós vivos.', 'Os recursos de Ventobravo ficam cada vez mais escassos. Não vai haver o suficiente para manter todos nós vivos.', 28153),
(157858, 'ptBR', 'Na-na-ni-na-não, camaradinha. Aqui, isso não fica.', '', 28153),
(157857, 'ptBR', 'Bom trabalho! Um monstro a menos para nos devorar.', '', 28153),
(157856, 'ptBR', 'Em vez de lutar pelas ruínas, a Aliança devia retomar nossa terra natal!', 'Em vez de lutar pelas ruínas, a Aliança devia retomar nossa terra natal!', 28153),
(157855, 'ptBR', 'É o segundo lar que perdemos.', 'É o segundo lar que perdemos.', 28153),
(157854, 'ptBR', 'Para onde vamos agora?', 'Para onde vamos agora?', 28153),
(157853, 'ptBR', 'Bom trabalho. Sem ela por aqui, as gerações futuras poderão crescer em paz.', '', 28153),
(157852, 'ptBR', 'Há coisas maiores em jogo, General. Temos que nos adaptar às novas informações.', '', 28153),
(157851, 'ptBR', '', 'Não podemos deixar aquele monstro fugir, Serpecida.', 28153),
(157850, 'ptBR', 'Lançanegra, não! Nada de troll burro em lugar de troll grã-fino!', '', 28153),
(157849, 'ptBR', 'Nenhuma imundície da Horda vai ser digna desse lugar. Nós, dos Zangareia, te desafiamos!', 'Nenhuma imundície da Horda vai ser digna desse lugar. Nós, dos Zangareia, te desafiamos!', 28153),
(157848, 'ptBR', '', 'Obrigada, Alleria. Sua ajuda é mais que bem-vinda.', 28153),
(157847, 'ptBR', 'Uma estratégia sábia. Tem minha aprovação.', '', 28153),
(157846, 'ptBR', '', 'Nós o caçaremos e lhe traremos a cabeça dele. Shandris cuida apenas do rastreamento do Príncipe de Sangue.', 28153),
(157845, 'ptBR', '', 'Meus elfos caóticos podem liderar os esforços para eliminar Gallywix.', 28153),
(157844, 'ptBR', '', 'Alleria abre um portal do caos atrás de si mesma.', 28153),
(157843, 'ptBR', '', 'Não podemos permitir que nenhum dos alvos nos escapem... E nem precisamos.', 28153),
(157842, 'ptBR', '', 'Perdoem a interrupção, mas creio que ambos têm razão.', 28153),
(157841, 'ptBR', '', 'Eu vi do que Dreven foi capaz, Serpecida. E se houver mais iguais a ele?', 28153),
(157840, 'ptBR', 'Ele é o ponto fraco deles. É uma oportunidade estratégica rara. Temos que atacar agora.', '', 28153),
(157839, 'ptBR', 'Gallywix patrocina a campanha bélica da Horda e entende de azerita melhor do que qualquer outro líder deles.', '', 28153),
(157838, 'ptBR', '', 'Podemos matar aquele goblin glutão a qualquer hora! Se Dreven fugir, talvez nunca o encontremos novamente.', 28153),
(157837, 'ptBR', 'Lidaremos com o Príncipe de Sangue Dreven em breve, general. Mas esta é uma rara oportunidade para estorvar as forças militares da Horda. Todo o resto terá que esperar.', '', 28153),
(157836, 'ptBR', 'Um monstro alado vem dando meus homens de comer aos filhotes! Abra o bucho desse bicho no aço.', '', 28153),
(157835, 'ptBR', 'Tu não vai trazer traidor amante da Horda nenhum pra esse lugar sagrado!', '', 28153),
(157834, 'ptBR', '', 'Nossos aliados esperam suas ordens.', 28153),
(157833, 'ptBR', 'A grande Pa\'kul decidiu que já passou da hora de Ji\'arak partir pro além. Junta tuas forças e vai dar um jeito na criatura.', '', 28153),
(157832, 'ptBR', 'Boas-vindas, $n. Nós temos trabalho a fazer.', '', 28153),
(157831, 'ptBR', 'Isso é... sangue? Sério? Você tá me dizendo que tem um escudo literalmente de sangue protegendo aquela coisa?\n\nTá... Agora, sim, eu vi de tudo.', '', 28153),
(157830, 'ptBR', '', 'O Círculo é nosso! Todos para os seus postos!', 28153),
(157829, 'ptBR', 'A próxima guerra. E a que vier depois dela.', '', 28153),
(157828, 'ptBR', 'A Luz vai continuar existindo depois que nós tivermos partido. Mas quando esta guerra terminar, o que vai lhe restar, Shaw?', '', 28153),
(157827, 'ptBR', 'Sua fé na Luz? Ou em Turalyon?', '', 28153),
(157826, 'ptBR', 'Muito pelo contrário. Testemunhar o retorno de Turalyon e ver como a Luz o havia mantido de pé e o transformado só fortaleceu minha determinação. Eu vi que havia depositado minha fé no lugar certo.', '', 28153),
(157825, 'ptBR', 'Quando soube que Turalyon estava vivo, você questionou sua devoção? As suas escolhas?', '', 28153),
(157824, 'ptBR', 'Quando ele partiu na Expedição da Aliança rumo a Terralém e foi dado como desaparecido, a Luz abriu meus olhos. Eu percebi que podia ser soldado e paladino. E jurei fazer jus ao sacrifício de Turalyon.', '', 28153),
(157823, 'ptBR', 'E quanto mais observava aqueles primeiros paladinos, mais admirava um em particular... Turalyon. Sua firmeza e dedicação vinham da fé e era isso o que fazia dele um grande líder.', '', 28153),
(157822, 'ptBR', 'O Drukan tá fazendo uma pausa.', '', 28153),
(157821, 'ptBR', 'Eu fui cavaleiro do Punho de Prata quando ele foi fundado. Como tinha dúvidas se era possível misturar sacerdócio e guerra, decidi focar só no treinamento de combate.', '', 28153),
(157820, 'ptBR', 'Diga, Serpecida, o que faz um paladino liderando uma tropa de elite? Você não deveria estar consagrando templos por aí?', '', 28153),
(157819, 'ptBR', 'Ah, sem dúvida.', '', 28153),
(157818, 'ptBR', 'É muita gentileza da sua parte, mas se eu tiver que escolher entre a honra e um serviço bem feito, sempre fico com o serviço. Pela Aliança, é lógico.', '', 28153),
(157817, 'ptBR', 'Eu confesso que... como paladino, já questionei qual é a necessidade de espiões e assassinos entre as fileiras da Aliança. Mas a sua honra e lealdade perante o rei são inquestionáveis.', '', 28153),
(157816, 'ptBR', 'A AVIN foi feita para trabalhar nos bastidores. Eu prefiro ficar nas sombras, não gosto muito de... exposição.', '', 28153),
(157815, 'ptBR', 'Já perdi a conta. Vou aonde a Aliança manda... e aonde a Luz me chama. Mas, que eu saiba, você também já é velho de guerra.', '', 28153),
(157814, 'ptBR', 'De quantas campanhas contra a Horda você participou com essa, Serpecida?', '', 28153),
(157813, 'ptBR', 'Cuidado com essa coisa aí, $n.', '', 28153),
(157812, 'ptBR', 'Achei que era uma boa te contar.', '', 28153),
(157811, 'ptBR', 'Oficina aberta pra negócios! Se tu precisar de alguma coisa, a gente mete a mão na graxa pra dar um jeito!', '', 28153),
(157810, 'ptBR', 'O dano causado à Presa de Guerra será devolvido com dez vezes mais intensidade!', '', 28153),
(157809, 'ptBR', 'Eu não temo mais a morte, é a morte que teme a mim...', '', 28153),
(157808, 'ptBR', 'A Chefe Guerreira vai garantir que haja punição.', '', 28153),
(157807, 'ptBR', 'A morte é boa demais para você!', '', 28153),
(157806, 'ptBR', 'Eu vou me refestelar no seu cadáver!', '', 28153),
(157805, 'ptBR', 'Eu vou rasgar você ao meio!', '', 28153),
(157804, 'ptBR', '', 'Bom trabalho, mas algo me diz que eles não vão largar o osso.', 28153),
(157803, 'ptBR', '', 'Piratas na Colina da Vigília outra vez! Eles não aprendem nunca?! Ajude os fuzileiros a expulsar os facínoras!', 28153),
(157802, 'ptBR', 'Obrigado! Eu tenho que voltar para a minha família.', 'Obrigada! Eu tenho que voltar para a minha família.', 28153),
(157801, 'ptBR', 'Você viu a cara deles?! Ah, a cena foi impagável! Vão demorar dias para arrumar essa lambança!', '', 28153),
(157800, 'ptBR', 'A Horda é um bando de bárbaros!', 'A Horda é um bando de bárbaros!', 28153),
(157799, 'ptBR', 'É melhor expurgar essa corrupção insidiosa... antes que ela infecte a Horda.', '', 28153),
(157798, 'ptBR', 'Bom trabalho. Não podemos ficar parados enquanto o abismo corrompe nossas terras!', '', 28153),
(157797, 'ptBR', 'Eu e o Venrik enchíamos a cara e saíamos voando em papagaios só de brincadeira. Por que você não experimenta? Aí, a justiça vem de cima pra esses salteadores!', '', 28153),
(157796, 'ptBR', 'Desengrenado...', '', 28153),
(157795, 'ptBR', 'Eu calculei... mal.', '', 28153),
(157794, 'ptBR', 'Essa abominação é a encarnação da loucura e da corrupção. Destrua o monstro imediatamente!', '', 28153),
(157793, 'ptBR', 'Só espero que minha família tenha conseguido fugir a tempo.', 'Só espero que minha família tenha conseguido fugir a tempo.', 28153),
(157792, 'ptBR', 'A fumaça tomou conta de tudo. Nós teríamos nos perdido nela se não fosse a Rainha Greymane.', 'A fumaça tomou conta de tudo. Nós teríamos nos perdido nela se não fosse a Rainha Greymane.', 28153),
(157791, 'ptBR', 'Temos que mandar essa criatura de volta para o abismo. Destrua o monstro!', '', 28153),
(157790, 'ptBR', 'Mal saímos com vida.', 'Mal saímos com vida.', 28153),
(157789, 'ptBR', 'Por que eles fariam isso?', 'Por que eles fariam isso?', 28153),
(157788, 'ptBR', 'Você está me tirando dos eixos de verdade!', '', 28153),
(157787, 'ptBR', 'Isso tudo é meeeeu!', '', 28153),
(157786, 'ptBR', 'Eu vou te fazer em pedacinhos!', '', 28153),
(157785, 'ptBR', '', 'Por pouco a Guarda Proudmore não sofreu uma grande perda. Graças a você, não passou de um contratempo.', 28153),
(157784, 'ptBR', '', 'Um dos navios de carga encalhou lá para baixo, no sul. A maior parte da tripulação escapou, mas eles tiveram que deixar tudo de valioso para trás.', 28153),
(157783, 'ptBR', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t O Armipotente Yenajz começa a lançar |cFFF00000|Hspell:274932|h[Abismo Interminável]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t O Armipotente Yenajz começa a lançar |cFFF00000|Hspell:274932|h[Abismo Interminável]|h|r!', 28153),
(157782, 'ptBR', 'Era cachaça?! Ahh, eu torcendo pra que fosse ouro... pra TORRAR em cachaça!', '', 28153),
(157781, 'ptBR', 'Andam dizendo pela Angra do Facão que um dos piratas tem um tesouro de dar água na boca, escondido no mar, nas redondezas das docas. Tente achar esse butim!', '', 28153),
(157780, 'ptBR', 'Bom trabalho. Isso vai reduzir os armamentos de azerita em Boralus enquanto não damos um jeito no motim dos Grimpagris.', '', 28153),
(157779, 'ptBR', 'A Companhia Comercial Grimpagris não interrompeu a produção de armas. Mande a fundição pelos ares, mas cuidado para não ferir nenhum inocente.', '', 28153),
(157778, 'ptBR', 'Aí, não esquenta. Vamos arranjar novos lares pra eles. O mais importante é que não estão mais na rua, nem correndo perigo.', '', 28153),
(157777, 'ptBR', 'A Companhia Comercial Grimpagris alicia órfãos com promessas de banquetes e os põe para trabalhar noite e dia. Tire as crianças de lá!', '', 28153),
(157776, 'ptBR', 'Dizem que o Lazureto arrancava kraken do mar na base da unhada. Era um bicho perigoso, camarada. Sua façanha vai virar lenda.', '', 28153),
(157775, 'ptBR', 'Os marinheiros entoam canções sobre Lazureto, a notória criatura capaz de emborcar um galeão com um mísero sopro. Pelo visto, é verdade. Se matar o bicho, eles vão cantar é a sua história.', '', 28153),
(157774, 'ptBR', '', 'Apresentem-se ao Lorde Supremo Saurfang. Façam com que paguem o preço por tamanha tolice. Pela Horda!', 28153),
(157773, 'ptBR', 'Quando fecho os olhos... vejo as chamas.', 'Quando fecho os olhos... vejo as chamas.', 28153),
(157772, 'ptBR', 'Espero que nossos amigos estejam em segurança.', 'Espero que nossos amigos estejam em segurança.', 28153),
(157771, 'ptBR', 'Não podemos perder Kalimdor.', 'Não podemos perder Kalimdor.', 28153),
(157770, 'ptBR', 'Não acredito que a Árvore do Mundo... se foi...', 'Não acredito que a Árvore do Mundo... se foi...', 28153),
(157769, 'ptBR', 'Os vira-latas da Horda destruíram nosso lar!', 'Os vira-latas da Horda destruíram nosso lar!', 28153),
(157768, 'ptBR', 'O que você quer? Ah, vejam só, u$Um:ma; colega engenheir$Uo:a;...', '', 28153),
(157767, 'ptBR', 'Quero perguntar outra coisa.', 'Quero perguntar outra coisa.', 28153),
(157766, 'ptBR', 'O cozinheiro maluco? Primo de segundo grau, se não me engano. É triste, ele só consegue pensar em bombas e bombonas. O gênio de verdade está inventando uma fonte de energia insuperável. Para alimentar máquinas que rasgam, retalham, perfuram e explodem um monte de coisas, pelo máximo de tempo possível.', '', 28153),
(157765, 'ptBR', 'Bom dia, doutor, eu gostaria de fazer uma oferta por um dos seus reatores. Eu posso pagar uma quantia à altura do seu trabalho.', 'Bom dia, doutor, eu gostaria de fazer uma oferta por um dos seus reatores. Eu posso pagar uma quantia à altura do seu trabalho.', 28153),
(157764, 'ptBR', 'Você é o Dr. Cabum? O Dr. Cabum em pessoa?', 'Você é o Dr. Cabum? O Dr. Cabum em pessoa?', 28153),
(157763, 'ptBR', 'Ah, você acha? Tô vendo que você É, SIM, u$Um:ma; engenheir$Uo:a; da maior qualidade! Não chega aos meus pés, mas são raros os que chegam.', '', 28153),
(157762, 'ptBR', '', 'Não faço ideia de quem seja essa fulana, mas sou a favor de matar logo!', 28153),
(157761, 'ptBR', 'Dr., a engenharia dessa peça é extraordinária!', 'Dr., a engenharia dessa peça é extraordinária!', 28153),
(157760, 'ptBR', '', 'Nos reencontramos na Bigorna Negra! Vamos precisar de um relatório de danos!', 28153),
(157759, 'ptBR', 'Ei, eu tô trabalhando! Volte quando tiver alguma habilidade útil pra oferecer na área de engenharia.', '', 28153),
(157758, 'ptBR', '', 'Isso aí, tu acabou com a raça deles! Nós vamos abrir a porta. Já dá pra ouvir inimigo de monte do outro lado. Abre teu olho!', 28153),
(157757, 'ptBR', 'Eu passei os últimos cincos anos consertando, aprimorando e ajustando a equipe de robôs mais avançada e mais mortífera já imaginada. Você quer ver como suas mascotes normais e enfadonhas se saem contra os técnicos de reparos de baixo nível mais brilhantes do universo?', '', 28153),
(157756, 'ptBR', 'Defeito?! Não era pra isso acontecer!', '', 28153),
(157755, 'ptBR', 'Minha mente brilhante concebendo máquinas ainda mais brilhantes é uma combinação insuperável.', '', 28153),
(157754, 'ptBR', '', 'Bom trabalho! O constructo virou pó, e Drustvar continua sã e salva.', 28153),
(157753, 'ptBR', '', 'Um constructo de pedra colossal despertou nas montanhas aqui perto! Nós temos que derrubar esse monstro antes que ele ataque o povo de Drustvar!', 28153),
(157752, 'ptBR', 'Impossível! Da próxima vez, vou construir robôs maiores.', '', 28153),
(157751, 'ptBR', 'Ajudante nenhum pode competir com a minha equipe. Eu sou invencível!', '', 28153),
(157750, 'ptBR', 'Se prepara pra encarar minha equipe invencível de robôs altamente modificados e customizados!', '', 28153),
(157749, 'ptBR', 'Estou pronto, Krag\'wa.', 'Estou pronta, Krag\'wa.', 28153),
(157748, 'ptBR', 'Neste momento, os trolls sangrentos continuam a massacrar meus filhos. $b$bEu ajudarei você a chegar ao líder deles, mas tenho que voltar para o pântano para proteger meus filhos.', '', 28153),
(157747, 'ptBR', 'Krag\'wa, o líder dos trolls sangrentos fugiu para a grande estrutura ao longe. Por favor, ajude-nos.', 'Krag\'wa, o líder dos trolls sangrentos fugiu para a grande estrutura ao longe. Por favor, ajude-nos.', 28153),
(157746, 'ptBR', 'Hum... rã-rã. Agora não, Venrik. Estamos tratando de coisas sérias aqui...', '', 28153),
(157745, 'ptBR', '', 'Estou aqui para ajudar, para lutar!', 28153),
(157744, 'ptBR', '', 'Eu luto pelo meu povo.', 28153),
(157743, 'ptBR', '', 'Um inimigo fraco. Dê cabo dele rapidamente!', 28153),
(157742, 'ptBR', 'Sabe, aquela de madeixas feito penas de corvo. Haha!', '', 28153),
(157741, 'ptBR', '', 'Pela memória de Darnassus!', 28153),
(157740, 'ptBR', '', 'Vai ser um alívio deixar este lugar para trás.', 28153),
(157739, 'ptBR', '', 'Temos que partir antes que cheguem mais desses... bichos.', 28153),
(157738, 'ptBR', '', 'Estou... vou ficar bem.', 28153),
(157737, 'ptBR', 'Diga, Filinto, o que aconteceu com aquela mulher de quem você não parava de falar?', '', 28153),
(157736, 'ptBR', '', 'Mãe! Você está bem?', 28153),
(157735, 'ptBR', '', 'Tu vai recuperar o martelo? Ele tem um baita poder. Se os goblins descobrirem como usar, pode ser o nosso fim.', 28153),
(157734, 'ptBR', '', '$n, eu tenho mais uma coisa pra te pedir. Esses selvagens eram da Empreendimentos S.A. Isso quer dizer que vão para Kezan. Provavelmente tão entregando o Inimigo de Ferro nas patas sebosas do Barão dos Negócios Frustrus agora mesmo.', 28153),
(157733, 'ptBR', '', 'Thane de Bigorna, Forjanegra, vocês descobrem como consertar a Bigorna Negra.', 28153),
(157732, 'ptBR', '', 'Tchê, o Inimigo de Ferro foi roubado e eles partiram a Bigorna Negra em duas!', 28153),
(157731, 'ptBR', '', 'E Kul Tiraz jamais se renderá.', 28153),
(157730, 'ptBR', 'Os drustos... jamais... se curvarão...', '', 28153),
(157729, 'ptBR', 'Que diacho!', '', 28153),
(157728, 'ptBR', 'Vocês dois, olho aberto! De olho na Bigorna Negra!', '', 28153),
(157727, 'ptBR', '', 'Filho do núcleo! Deve ter sido o mecanoide grandalhão que me atropelou!', 28153),
(157726, 'ptBR', 'Um esbordoador ou coisa que o valha me pegou desprevenido e roubou o Inimigo de Ferro!', '', 28153),
(157725, 'ptBR', '', 'Tudo bem comigo. Tu que não tá com uma cara boa.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157724, 'ptBR', 'Rainha Regente! Tudo bem contigo, guria?!', '', 28153),
(157723, 'ptBR', '', 'Beleza, garotada, vamos fechar o boteco!', 28153),
(157722, 'ptBR', '', 'Meu povo já derrotou vocês antes, monstro. Nós faremos isso de novo!', 28153),
(157721, 'ptBR', 'Thros há de consumir vocês! Finalmente eu terei minha vingança!', '', 28153),
(157720, 'ptBR', '', 'Justo quando a coisa começou a ficar boa pra gente.', 28153),
(157719, 'ptBR', '', '<Moira balbucia sozinha.>', 28153),
(157718, 'ptBR', '', 'Thaelin, vai pro Salão da Criação! Eles devem estar a caminho do Cofre Negro.', 28153),
(157717, 'ptBR', '', 'Campe$Uão:ã;, toma a Estrada do Ferro Negro e mantém ela segura!', 28153),
(157716, 'ptBR', '', 'Thane de Bigorna, vai reunir teus feiticeiros pro contra-ataque!', 28153),
(157715, 'ptBR', '', 'Essas titicas maulas verdes acham que podem atacar a gente em casa?!', 28153),
(157714, 'ptBR', 'Goblins! Nos túneis!', '', 28153),
(157713, 'ptBR', '', 'Às armas, $n!', 28153),
(157712, 'ptBR', '', 'Você se meteu com a família errada, demônio!', 28153),
(157711, 'ptBR', '', 'Mãe!', 28153),
(157710, 'ptBR', '', 'Mãe, cuidado!', 28153),
(157709, 'ptBR', '', 'Eita, que baita arma!', 28153),
(157708, 'ptBR', 'Ninguém escapará!', '', 28153),
(157707, 'ptBR', '', 'Venha, filha. Vamos dar um jeito de sair daqui.', 28153),
(157706, 'ptBR', '', 'Lá vêm mais deles!', 28153),
(157705, 'ptBR', '', 'Elementais vindo aí!', 28153),
(157704, 'ptBR', '', 'A gente descobriu que aplicar magia grandiosa na azerita pode ter resultados inesperados.', 28153),
(157703, 'ptBR', '', 'Jaina... é você mesmo?', 28153),
(157702, 'ptBR', 'O que a traça de livro rabugenta quer dizer é: cobre a gente quando os elementos atacarem.', '', 28153),
(157701, 'ptBR', 'Vocês chegaram... tarde demais...', '', 28153),
(157700, 'ptBR', '$C, com certeza vamos nos deparar com mais incidentes de azerigênese espontânea quando estivermos moldando a azerita. Tu acha que dá conta?', '', 28153),
(157699, 'ptBR', 'Pode ajeitar um pouco mais de azerita na bigorna pra mim, $n?', '', 28153),
(157698, 'ptBR', 'Vocês são os próximos!', '', 28153),
(157697, 'ptBR', 'Tolos insolentes! Vocês não podem mais salvar a menina!', '', 28153),
(157696, 'ptBR', 'Sim, Rainha Regente.', '', 28153),
(157695, 'ptBR', '', 'Thaelin e Thurgaden, eu quero ver empenho.', 28153),
(157694, 'ptBR', '', 'Basta! Revele sua verdadeira forma, monstro!', 28153),
(157693, 'ptBR', '', 'O trabalho está progredindo. Anduin pede atualizações quase todo dia, então achei que seria uma boa te mostrar o que a gente descobriu.', 28153),
(157692, 'ptBR', '', 'Botei os melhores pra trabalhar no refinamento de azerita desde que ela apareceu nas profundezas.', 28153),
(157691, 'ptBR', '', 'Obrigada por ter vindo, $n.', 28153),
(157690, 'ptBR', '', 'Pai... por favor...', 28153),
(157689, 'ptBR', '', 'Encontro você perto da estátua, na ladeira.', 28153),
(157688, 'ptBR', '', 'Grande Krag\'wa, nós precisamos da sua ajuda!', 28153),
(157687, 'ptBR', 'Igualzinho à Terceira Guerra.', '', 28153),
(157686, 'ptBR', 'Pela Companhia Bravo!', '', 28153),
(157685, 'ptBR', 'Igualzinho a Draenor!', '', 28153),
(157684, 'ptBR', 'Me faz lembrar da Segunda Guerra.', '', 28153),
(157683, 'ptBR', 'Hunf, hunf, hunf, hunf.', 'Hunf, hunf, hunf, hunf.', 28153),
(157682, 'ptBR', 'Vamos repassar o plano para matar a Capitã Areiel.', 'Vamos repassar o plano para matar a Capitã Areiel.', 28153),
(157681, 'ptBR', 'General.', '', 28153),
(157680, 'ptBR', '', 'Vamos agora. $n vai na frente. O resto de nós dá apoio e cuida do reconhecimento. Keeshan, isso inclui você.', 28153),
(157679, 'ptBR', '', 'Salvando os tortollanos, teremos acesso a informações sobre a movimentação da Horda, o que deve nos levar à Capitã Areiel.', 28153),
(157678, 'ptBR', 'Senhora. Há tortollanos em Nazmir, e as informações indicam que eles sabem da movimentação da Horda. Vários deles foram capturados pelos trolls sangrentos.', '', 28153),
(157677, 'ptBR', 'É como acertar peixes num barril!', 'É como acertar peixes num barril!', 28153),
(157676, 'ptBR', 'Na mosca! Digo, no peixe!', 'Na mosca! Digo, no peixe!', 28153),
(157675, 'ptBR', '', 'Precisamos de informações e aliados em Nazmir para conseguir. Para nossa sorte, temos uma oportunidade. Keeshan?', 28153),
(157674, 'ptBR', '', 'A morte da Capitã Areiel vai atravancar as operações da Horda em Nazmir e enfraquecer as patrulheiras sombrias de Sylvana.', 28153),
(157673, 'ptBR', 'Esses trolls estão fazendo mal aos meus filhos há muito tempo! Agora eu vou à caça.', '', 28153),
(157672, 'ptBR', 'Eu sempre achei que a Água Morta ficasse pro outro lado.', '', 28153),
(157671, 'ptBR', '', 'Tudo anda calmo e agradável desde que o Netinho sumiu.', 28153),
(157670, 'ptBR', 'Não podemos permitir que isso aconteça. Reúna os seus aliados. Stromgarde é território da Aliança!', '', 28153),
(157669, 'ptBR', 'Mas a Horda vem reunindo forças para tirar a bastilha do nosso controle. Se conseguirem, vão ganhar uma posição estratégica de suma importância nos Reinos do Leste.', '', 28153),
(157668, 'ptBR', 'Stromgarde era um centro de poder importante na época que Lordaeron pertencia à Aliança. A intenção é que volte a ser.', '', 28153),
(157667, 'ptBR', 'Monte uma expedição para extrair a azerita... antes que a Horda faça o mesmo.', '', 28153),
(157666, 'ptBR', 'Os batedores de Shaw descobriram depósitos de azerita espalhados pelas ilhas mar afora. A Aliança precisa desse material.', '', 28153),
(157665, 'ptBR', 'Os agentes recrutados vão ficar encarregados de sabotar as operações da Horda... garantindo assim a nossa vitória.', '', 28153),
(157664, 'ptBR', 'Monte, junto com Mathias Shaw, uma equipe de agentes secretos. Não há ninguém mais apto para a tarefa do que o melhor espião de Ventobravo.', '', 28153),
(157663, 'ptBR', 'Campeão, para vencer na guerra é preciso estar bem armado. Mas, às vezes, a vitória pede uma abordagem mais... sutil, digamos assim.', '', 28153),
(157662, 'ptBR', 'Eu estou pronto para evocar Krag\'wa.', 'Eu estou pronto para evocar Krag\'wa.', 28153),
(157661, 'ptBR', '', 'Zelão está conversando com a família. Fique longe, vamos ver se eu terei que interferir.', 28153),
(157660, 'ptBR', '', 'A ideia é valer-se de sua astúcia e furtividade para revelar as fraquezas do inimigo... e tirar partido disso.', 28153),
(157659, 'ptBR', '', 'Reúna, junto com Garona Meiorken, os agentes mais astutos e engenhosos da Horda. Vocês vão mandá-los em missões secretas por toda Kul Tiraz e Zandalar.', 28153),
(157658, 'ptBR', '', 'Para não dar margem para erro, vou mandar com você uma agente cheia de... truques na manga. Tenho certeza de que cairão como uma luva para a missão.', 28153),
(157657, 'ptBR', '', 'Você tem que andar logo. Esconda-se na escuridão da noite para realizar a busca. Aquelas águas estão apinhadas de patrulhas da Aliança.', 28153),
(157656, 'ptBR', '', 'Nathanos, a conversão do Irmão Zelão já vem rendendo frutos. Ele revelou o paradeiro do navio naufragado que nós procurávamos.', 28153),
(157655, 'ptBR', '', 'Agora o reizinho mandou seus súditos para tomá-la de volta. Não podemos deixar que isso aconteça.', 28153),
(157654, 'ptBR', '', 'Stromgarde era um centro de poder da Aliança nos Reinos do Leste antes da bastilha cair em ruínas.', 28153),
(157653, 'ptBR', '', 'Nós temos que sair na frente. Vá explorar as ilhas e dominar o território... antes que a Aliança o domine.', 28153),
(157652, 'ptBR', '', 'Os goblins continuam mostrando a que vieram. Eles localizaram vários depósitos de azerita em ilhas espalhadas pela vastidão dos mares.', 28153),
(157651, 'ptBR', '', 'Na guerra, às vezes uma punhalada bem dada nas costas faz mais estrago do que mil espadas no campo de batalha.', 28153),
(157650, 'ptBR', '', 'Aquele maldito Mildião está louco! Parece que a hidromelaria foi tomada pelos experimentos dele. Vá investigar antes que as coisas piorem.', 28153),
(157649, 'ptBR', '', 'Agradeço a você e à sua Horda por ajudar a libertar minha tripulação.\n\nEnquanto eu estiver no comando, os Neblineiros serão livres para cruzar os mares!', 28153),
(157648, 'ptBR', '', 'Ele era o último sacrifício... Nós fracassamos.', 28153),
(157647, 'ptBR', 'Não... não pode ser!', '', 28153),
(157646, 'ptBR', 'Mas vai saber!', '', 28153),
(157645, 'ptBR', 'Sofrimento? Você não sabe o que é sofrer de verdade. Ainda não...', '', 28153),
(157644, 'ptBR', 'Taelia, quando as circunstâncias permitirem, você voltará a Ventobravo como minha convidada. Eu tenho muitas histórias do seu pai para contar.', '', 28153),
(157643, 'ptBR', '', 'As cartas pararam de chegar. Eu... tenho tantas perguntas.', 28153),
(157642, 'ptBR', '', 'Dê a ele uma morte breve. Nós já vimos sofrimento demais por hoje.', 28153),
(157641, 'ptBR', '', '\"Minha estrela brilhante.\"', 28153),
(157640, 'ptBR', 'Eu me lembro agora... ele lhe escrevia cartas. Chamava você de...', '', 28153),
(157639, 'ptBR', 'O Grão-lorde Bolvar foi um grande homem. Um herói para a Aliança... e para mim.', '', 28153),
(157638, 'ptBR', '', 'Você conheceu o meu pai?', 28153),
(157637, 'ptBR', '<Jakra\'zet solta um grunhido.>', '', 28153),
(157636, 'ptBR', 'Taelia... levante-se, por favor. A honra é minha.', '', 28153),
(157635, 'ptBR', '', 'Filha de Bolvar. Criada sob a nossa proteção desde a Terceira Guerra.', 28153),
(157634, 'ptBR', 'Fordragon?!', '', 28153),
(157633, 'ptBR', '', 'Taelia Fordragon.', 28153),
(157632, 'ptBR', '', 'É uma honra conhecê-lo, Rei Wrynn. Meu nome é Taelia.', 28153),
(157631, 'ptBR', '', 'Ela também foi crucial para a salvação do reino... e da minha vida.', 28153),
(157630, 'ptBR', '', 'Rei Wrynn, tem uma pessoa que você precisa conhecer.', 28153),
(157629, 'ptBR', 'É um prazer e uma honra receber Kul Tiraz de volta a Aliança. Que a Luz nos leve à vitória.', '', 28153),
(157628, 'ptBR', '', 'Muito obrigada... a todo mundo. Eu farei tudo ao meu alcance para honrar a confiança de vocês.', 28153),
(157627, 'ptBR', '', 'O que você me diz?', 28153),
(157626, 'ptBR', '', 'Acabou a festa, General. As tramoias. As mentiras. Os assassinatos.', 28153),
(157625, 'ptBR', '', 'Sam, não!', 28153),
(157624, 'ptBR', 'TROVAMAREEE!', '', 28153),
(157623, 'ptBR', 'Você trouxe o seu próprio fim, Pique. Eu levarei a frota à nossa gloriosa salvadora... Azshara.', '', 28153),
(157622, 'ptBR', 'Tudo o que vejo são almas perdidas, implorando para serem libertadas.', '', 28153),
(157621, 'ptBR', 'Acabou, Trovamare! Olhe em volta... você está cercado!', '', 28153),
(157620, 'ptBR', 'Você claramente sabe o que estava fazendo. Sempre posso contar contigo na hora de espalhar o caos!', '', 28153),
(157619, 'ptBR', 'Não temos lá muito armamento, então temos que ser engenhosos. Encontre um jeito de fazer um belo estrago e caia fora antes que eles entendam o que aconteceu.', '', 28153),
(157618, 'ptBR', '', 'Quem sabe quanto estrago aquela coisa poderia ter causado à frota? Graças a você, nunca descobriremos.', 28153),
(157617, 'ptBR', '', 'Você é fraca demais para governar, Katherine.', 28153),
(157616, 'ptBR', '', 'E eu quase... Priscilla... como você pôde trair o reino? Como você pôde trair a mim?', 28153),
(157615, 'ptBR', '', 'Aquele golem pode partir um navio ao meio! Não podemos deixar uma arma de tamanha magnitude nas mãos do Lorde Trovamare.', 28153),
(157614, 'ptBR', '', 'Você contratou a frota pirata, encheu os facínoras de armas e os lançou contra seu próprio povo.', 28153),
(157613, 'ptBR', '', 'Ele se chama azerita... E a Aliança e a Horda já estão guerreando por isso.', 28153),
(157612, 'ptBR', '', 'A sua companhia FABRICOU as armas que destruíram o Portão de Daelin com este material!', 28153),
(157611, 'ptBR', '', 'Lady Priscilla Grimpagris, você está presa por tráfico, por conspirar com piratas e por trair o Almirantado de Kul Tiraz.', 28153),
(157610, 'ptBR', 'O mar nos dá muita coisa, mas debaixo d\'água só existe desespero.', '', 28153),
(157609, 'ptBR', '', 'O que significa isso, garota?!', 28153),
(157608, 'ptBR', '', 'Então esse era o seu plano o tempo todo. Que desprezível.', 28153),
(157607, 'ptBR', '', 'Uma mentirosa!', 28153),
(157606, 'ptBR', 'Um horror ancestral das profundezas se manifestou. Mande-o de volta para debaixo do mar.', '', 28153),
(157605, 'ptBR', '', 'A Lady Grimpagris foi o meu rochedo naqueles dias difíceis, quando nós duas perdemos nossos maridos. Agora, ela será o rochedo do reino. Agora... ela é...', 28153),
(157603, 'ptBR', '', 'Mas ainda não foi o bastante.', 28153),
(157602, 'ptBR', '', 'Bela jogada! Nossas forças terrestres continuam firmes e fortes.', 28153),
(157601, 'ptBR', 'A última vez que vi tanta fumaça assim foi quando a dona Dalmora tentou ensinar aquele neto abestalhado dela a assar um bolo. Excelente trabalho!', '', 28153),
(157600, 'ptBR', '', 'Que vergonha!', 28153),
(157599, 'ptBR', '', 'As nagas trouxeram uma arma de cerco viva para destruir o dique! Às armas!', 28153),
(157598, 'ptBR', 'Piratas?! Os Proudmore não conseguem nos proteger nem dos piratas mais!', '', 28153),
(157597, 'ptBR', '', 'Uma frota pirata atacou o portão com força descomunal...', 28153),
(157596, 'ptBR', 'A fúria da tempestade é perigosa e imprevisível, mas não é páreo para o seu talento.', '', 28153),
(157595, 'ptBR', 'Isso tem cheiro de magia dos Sábios das Marés. Faça o que for necessário para contê-la!', '', 28153),
(157594, 'ptBR', 'Sempre que eu acho que estamos fazendo um estrago nos inimigos, eles reconstroem mais rápido do que conseguimos destruir. Temos que cortar o suprimento de madeira deles! Queima tudo!', '', 28153),
(157593, 'ptBR', '', 'Os rumores eram verdade. O Portão de Daelin... caiu por terra.', 28153),
(157592, 'ptBR', 'Que explosões mais barulhentas. Sobrou alguma coisa além dos destroços?', '', 28153),
(157591, 'ptBR', '', 'A colheita está segura, graças a você! Vamos ver se conseguimos arranjar um lugar para esses carinhas, longe das fazendas.', 28153),
(157590, 'ptBR', '', 'Eu sabia que ia valer a pena. Sorte nossa que podemos contar com ela!', 28153),
(157589, 'ptBR', '', 'Tem alguma coisa comendo as sementes dos fazendeiros da região. Eles precisam plantá-las. Veja se você consegue revelar os culpados!', 28153),
(157588, 'ptBR', '', 'A dona Dalmora solicitou alguns itens para ajudar no esforço de guerra. A velhinha é dura de roer. Seríamos loucos em recusar a ajuda dela!', 28153),
(157587, 'ptBR', 'Nós vamos eliminar a corrupção demoníaca uma vez após a outra, até purificar o Santuário da Tempestade.', '', 28153),
(157586, 'ptBR', 'Os demônios querem profanar nosso solo sagrado. Não podemos tolerar isso!', '', 28153),
(157585, 'ptBR', '', 'Eu sei que controle de pragas não é a atividade mais glamourosa do mundo, mas os moradores da Pedra do Moinho ficarão gratos.', 28153),
(157584, 'ptBR', '', 'Os moradores de Pedra do Moinho anda penando com todo tipo de infortúnio. Os armazéns deles estão infestados de pragas. Vamos ajudar a exterminar a infestação.', 28153),
(157583, 'ptBR', 'Um dia, o som alegre dos Sábios das Marés lançando seus primeiros feitiços voltará a ecoar por estas bandas... mas não será hoje.', '', 28153),
(157582, 'ptBR', '', 'Tomara que isso mande o resto desses gigantes horrendos de volta para as montanhas, onde é o lugar deles!', 28153),
(157581, 'ptBR', 'As raízes do meu antigo mestre são profundas. Elimine cada traço delas.', '', 28153),
(157580, 'ptBR', 'Obrigado. O povo do vale jamais se esquecerá do que você fez por nós.', '', 28153),
(157579, 'ptBR', '', 'Os gorjalas estão aterrorizando a Vila Pedra do Moinho, e os civis não têm como enfrentá-los. Nós somos a única esperança deles!', 28153),
(157578, 'ptBR', 'Precisamos de você em Brennadam, camarada. Ainda não temos tropas suficientes para montar um contra-ataque sozinhos.', '', 28153),
(157577, 'ptBR', 'Fale com a Capitã Angélica quando estiver tudo pronto para embarcar.', '', 28153),
(157576, 'ptBR', '', 'Desculpa. Eu deveria ter perguntado se você tinha alergia a abelhas antes de te mandar para lá. Mas você parece estar bem, então sei quem chamar da próxima vez!', 28153),
(157575, 'ptBR', 'Eu agradeço a prontidão com que atendeu ao chamado, $n. Você zarpará com a Terceira Frota.', '', 28153),
(157574, 'ptBR', 'Não podemos permitir que tamanha maldade floresça no mundo.', '', 28153),
(157573, 'ptBR', '', 'As abelhas da hidromelaria estão aterrorizando os moradores de novo e — olha só essa — os fazendeiros perderam o controle delas. Que surpresa!', 28153),
(157572, 'ptBR', 'O Rei Anduin me mandou, Mestre Espião.', 'O Rei Anduin me mandou, Mestre Espião.', 28153),
(157571, 'ptBR', '', 'Tem alguma coisa acontecendo na fazenda que deixou os wendigos frenéticos. Eles ficavam na deles antes daqueles Mildiões malucos se mudarem para lá.', 28153),
(157570, 'ptBR', '', 'Ficamos sabendo que a Hidromelaria Mildião está com problemas com wendigos. Acha que dá para chegar lá e dar uma força para eles?', 28153),
(157569, 'ptBR', 'K\'thir pratica a magia sombria completamente desimpedido, a bordo do Melodia Abissal. Lave esta sujeira dos convés.', '', 28153),
(157568, 'ptBR', 'Nós podemos estar em minoria, mas continuamos inabalados graças a você.', '', 28153),
(157567, 'ptBR', 'Sábio das Marés decaídos enfeitiçaram marinheiros perdidos e ameaçam tomar Cruzamaré. Dê um jeito neles!', '', 28153),
(157566, 'ptBR', '', 'A criatura devia ser um fungoriano honrado. Que sina trágica para um guerreiro tão nobre.', 28153),
(157565, 'ptBR', '', 'Recebemos relatos sobre uma presença poderosa em uma caverna ao sul. Tome cuidado. Só de ouvir falar na criatura já me dá calafrios...', 28153),
(157564, 'ptBR', '', 'Bom trabalho, só não garanto que esta vai ser a última vez que teremos que salvar a pele dele...', 28153),
(157563, 'ptBR', 'Ainda não conseguimos expulsar a Horda da passagem. Acabe com a produção deles, a qualquer custo. Exploda o lugar até a Espiral Etérea, se for necessário!', '', 28153),
(157562, 'ptBR', '', 'As armas produzidas pelas fundições do Trovamare deveriam proteger seu povo, não oprimi-lo.', 28153),
(157561, 'ptBR', 'Pode até ser uma tarefa boba, considerando o seu histórico, mas alguém precisa fazê-la.', '', 28153),
(157560, 'ptBR', 'A Cabana de Kennings não vem dando conta dos pedidos do Almirantado devido a algumas... complicações. Para você, vai ser moleza resolver o problema.\nNOTE: Make sure to keep consistency with other Kennings Lodge strings.', '', 28153),
(157559, 'ptBR', '', 'Seria uma pena desperdiçar tanta munição assim. Você sabe o que fazer.', 28153),
(157558, 'ptBR', 'Cabe a nós mantê-los na linha, agora que a milícia já era.', '', 28153),
(157557, 'ptBR', 'Os javatuscos estão aprontando alguma no urzal. Dê um basta nos planos deles antes que recuperem as forças!', '', 28153),
(157556, 'ptBR', 'Nura, eu estou aqui para ajudar.', 'Nura, eu estou aqui para ajudar.', 28153),
(157555, 'ptBR', '', 'O que $Uo:a; traz aqui?', 28153),
(157554, 'ptBR', 'Nos encontramos mais tarde na cidade para dividir!', '', 28153),
(157553, 'ptBR', 'Você pode me levar até a Estrada Alta, nos Sertões Meridionais?', 'Você pode me levar até a Estrada Alta, nos Sertões Meridionais?', 28153),
(157552, 'ptBR', 'Um navio sem velas é igualzinho a uma cavalaria sem cavalos. Não presta para nada...', '', 28153),
(157551, 'ptBR', 'A tempestade periga arrasar com os nossos depósitos. Acalme-a enquanto é tempo!', '', 28153),
(157550, 'ptBR', 'Você fez jus ao legado de Amarante hoje. Muito obrigado.', '', 28153),
(157549, 'ptBR', 'O Irmão Amarante jamais teria tolerado tamanha perversão. Recupere os estaleiros em nome dele!', '', 28153),
(157548, 'ptBR', '', 'Tudo começa na matéria-prima. O resto é trabalho duro e boa fé.', 28153),
(157547, 'ptBR', '', 'Os construtores navais de Trovamare são lendários, mas precisam de madeira para trabalhar. Restaure a ordem imediatamente!', 28153),
(157546, 'ptBR', '', 'Agora eles vão aprender. O Vale Trovamare sempre estará aberto a todos!', 28153),
(157545, 'ptBR', '', 'As forças do Lorde Trovamare levantaram outra barricada! Libere a passagem para os comerciantes!', 28153),
(157544, 'ptBR', 'Rápido, ande logo!', '', 28153),
(157543, 'ptBR', 'Fale com Isabella. Ela fará com que você chegue em segurança ao ponto de encontro, na Cidade Baixa.', '', 28153),
(157542, 'ptBR', 'Assim que tivermos reunido os reforços, eu lhe explicarei a missão.', '', 28153),
(157541, 'ptBR', 'Obrigado por vir tão rápido, $n. Não há tempo a perder.', '', 28153),
(157540, 'ptBR', 'Proteger, alimentar e guiar. Este é o caminho dos Sábios das Marés.', '', 28153),
(157539, 'ptBR', 'Todos os Sábios das Marés fazem o juramento de proteger o povo. Cumpra nosso juramento, salve essas pobres almas!', '', 28153),
(157538, 'ptBR', 'Nossos inimigos são implacáveis. Mas, graças a você, nós continuamos firmes e fortes.', '', 28153),
(157537, 'ptBR', 'Parece que o ritual fracassou. Não podemos permitir que a magia nefasta das nagas continue corrompendo os mares.', '', 28153),
(157536, 'ptBR', 'Os seguidores de Azshara decidiram arriscar um ritual diferente depois da última derrota que sofreram. Mande-os para as profundezas que eles tanto adoram.', '', 28153),
(157535, 'ptBR', '', 'As nagas ficam mais agressivas a cada dia que se passa. Tenho medo do que pode acontecer conosco.', 28153),
(157534, 'ptBR', '', 'O Rastro da Tempestade ainda está se recuperando do ataque das nagas. Ajude-os a se defender enquanto recuperam o controle da situação!', 28153),
(157533, 'ptBR', 'Esses recursos vão servir muito bem às nossas forças. Tome-os para a nossa causa!', '', 28153),
(157532, 'ptBR', 'O mar te abençoe. Eles só tomarão o vale por cima dos nossos cadáveres!', '', 28153),
(157531, 'ptBR', 'Para tudo na vida tem uma primeira vez, e... vamos torcer para que não haja uma segunda, nesse caso.', '', 28153),
(157530, 'ptBR', 'Hã, eu não sei bem o que pensar a respeito disso, mas tem alguma coisa muito estranha acontecendo na cidade. Veja se consegue dar um jeito.', '', 28153),
(157529, 'ptBR', '', 'Se abandonar os sentimentos, só restam o vazio e a escuridão.', 28153),
(157528, 'ptBR', '', 'Jaina, querida... nem todas as decisões são tomadas com base só na razão.', 28153),
(157527, 'ptBR', '', 'Ele não é real, Jaina! Nada disso é!', 28153),
(157526, 'ptBR', '', 'Mas... eles mentiram para mim...', 28153),
(157525, 'ptBR', 'Foi tolice minha imaginar que você seria capaz de liderar!', '', 28153),
(157524, 'ptBR', 'Você deixou os seus julgamentos pessoais macularem o Kirin Tor!', '', 28153),
(157523, 'ptBR', '', 'Eu queria que seu pai tivesse aprendido essa lição...', 28153),
(157522, 'ptBR', '', 'Buscar uma maneira de encerrar o massacre é uma causa nobre, Jaina...', 28153),
(157521, 'ptBR', 'Os exércitos do Lorde Trovamare perigam tomar a região. Não deixe que ela caia nas mãos deles!', '', 28153),
(157520, 'ptBR', '', 'Saia de perto dela!', 28153),
(157519, 'ptBR', 'Hir\'eek é o loa da noite. Você não precisa saber mais nada.', 'Hir\'eek é o loa da noite. Você não precisa saber mais nada.', 28153),
(157518, 'ptBR', '', 'Foi tudo culpa minha...', 28153),
(157517, 'ptBR', 'Mas você... você deteve a minha lâmina. Quantos soldados da Aliança morreram naquele dia? Em todas as batalhas que se seguiram?', '', 28153),
(157516, 'ptBR', 'Eu podia ter acabado com todos eles! Sylvana... Thrall... Imagine como seria nosso mundo sem eles e aquela Horda desgraçada!', '', 28153),
(157515, 'ptBR', '', 'Não! Deve ser outra daquelas criaturas atormentando a Jaina. Temos que nos apressar!', 28153),
(157514, 'ptBR', '', 'Essa voz... Daelin?!', 28153),
(157513, 'ptBR', '', 'Outra ilusão? Jaina ainda deve estar presa em algum lugar por aqui.', 28153),
(157512, 'ptBR', '', 'Vamos encontrá-la… e libertá-la deste lugar amaldiçoado.', 28153),
(157511, 'ptBR', '', 'Minha filha está aqui em algum lugar, escondida, sofrendo.', 28153),
(157510, 'ptBR', 'Que bela luta! Os mares carregarão a história dos seus feitos por muitos anos.', '', 28153),
(157509, 'ptBR', '', 'É melhor continuarmos nossa busca.', 28153),
(157508, 'ptBR', '', 'Ela se foi. A criança era apenas um reflexo… um eco do sofrimento de Jaina.', 28153),
(157507, 'ptBR', '', '... mas nem o mais poderoso de nós pode salvar a todos.', 28153),
(157506, 'ptBR', '', 'Jaina... você era... ainda é... o orgulho de Kul Tiraz. O poder e a fúria...', 28153),
(157505, 'ptBR', '', 'Não! Não dê ouvidos a eles, Jaina!', 28153),
(157504, 'ptBR', '', 'Eu os decepcionei... todos eles…', 28153),
(157503, 'ptBR', '', 'Você podia ter detido ele! Podia ter nos salvado!', 28153),
(157502, 'ptBR', 'Vim me apresentar para o serviço, Lorde Supremo.', 'Vim me apresentar para o serviço, Lorde Supremo.', 28153),
(157501, 'ptBR', 'O Rastro da Tempestade precisa da sua ajuda mais uma vez. Que o mar leve você à vitória.', '', 28153),
(157500, 'ptBR', 'Você nos deixou nas garras da morte!', '', 28153),
(157499, 'ptBR', '', 'Mostre o caminho, $p.', 28153),
(157498, 'ptBR', '', 'Eu sempre a encontrava então, e não deixarei de encontrá-la agora.', 28153),
(157497, 'ptBR', '', 'Quando era criança, Jaina sempre se escondia quando estava assustada ou chateada.', 28153),
(157496, 'ptBR', '', 'Espere!', 28153),
(157495, 'ptBR', '', 'Não! Você não pode me ajudar! Ninguém pode me ajudar!', 28153),
(157494, 'ptBR', '', 'Está tudo bem, querida...', 28153),
(157493, 'ptBR', '', 'Jaina está logo à frente. Vamos logo!', 28153),
(157492, 'ptBR', 'Thros... há de consumir vocês...', '', 28153),
(157491, 'ptBR', '', 'Não se eu puder impedir!', 28153),
(157490, 'ptBR', 'A menina Proudmore é nossa, intrusos!\n', '', 28153),
(157489, 'ptBR', '', 'Temos que ir atrás dela!', 28153),
(157488, 'ptBR', '', 'Jaina, espere!', 28153),
(157487, 'ptBR', '', 'Não! Fique longe!', 28153),
(157486, 'ptBR', '', 'Jaina?!', 28153),
(157485, 'ptBR', '', 'A culpa... é minha...', 28153),
(157484, 'ptBR', '', 'Terra Morta... este lugar faz jus ao nome que tem...', 28153),
(157483, 'ptBR', 'O mar te abençoe. Nosso vale voltou a ter paz.', '', 28153),
(157482, 'ptBR', 'Pelas profundezas abissais... não podemos permitir que essa aberração continue ameaçando o nosso povo!', '', 28153),
(157481, 'ptBR', 'Que isso sirva de lição a todos que receberem a bênção da Mãe das Marés.', '', 28153),
(157480, 'ptBR', 'Tamanho desrespeito pelo poder do mar tem mais é que ser destruído.', '', 28153),
(157479, 'ptBR', 'Torga é um ser poderoso que acabou enfraquecido, mas nós tortollanos mantemos sua memória viva.', '', 28153),
(157478, 'ptBR', 'Vamos parar aqui por um instante, $p.', '', 28153),
(157477, 'ptBR', 'Gral é um loa sábio, ele vê as coisas no longo prazo. O mar profundo é o reino dele, e a escuridão do oceano é seu domínio.', 'Gral é um loa sábio, ele vê as coisas no longo prazo. O mar profundo é o reino dele, e a escuridão do oceano é seu domínio.', 28153),
(157476, 'ptBR', 'Que o mar os rejeite, assim como o povo os rejeitou.', '', 28153),
(157475, 'ptBR', 'Nada como uma rosa sem espinhos! Bom trabalho.', '', 28153),
(157474, 'ptBR', 'Os javatuscos estão armando alguma coisa na fazenda ao lado do urzal deles. Que tal você dar um pulo lá e acabar com as maquinações deles?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157473, 'ptBR', 'Outra alma perversa veio atender ao chamado do Lorde Trovamare. Não deixem que desfaçam nosso trabalho!', '', 28153),
(157472, 'ptBR', 'Descanse em paz, alma atormentada. O sofrimento acabou.', '', 28153),
(157471, 'ptBR', 'Que horror, que os nossos irmãos fizeram... Acabe com o sofrimento dessa criatura.', '', 28153),
(157470, 'ptBR', 'Tô fora...', 'Tô fora...', 28153),
(157469, 'ptBR', 'Sim... milorde.', 'Sim... milorde.', 28153),
(157468, 'ptBR', 'Quequié?', 'Quequié?', 28153),
(157467, 'ptBR', 'Lá vou eu!', 'Lá vou eu!', 28153),
(157466, 'ptBR', 'Mais trabalho?', 'Mais trabalho?', 28153),
(157465, 'ptBR', '', 'Deixa comigo, chefe!', 28153),
(157464, 'ptBR', 'Eu estou vendo, sim, outra pequena escavação a oeste daqui. Kelsey?', '', 28153),
(157463, 'ptBR', 'Fiquem juntos. Nós não viemos até aqui para perder!', '', 28153),
(157462, 'ptBR', 'As maiores escavações do Relicário ficam mais ao sul. Como eu suspeitava.', '', 28153),
(157461, 'ptBR', 'A Horda incendiou as construções! Apague tudo antes que o vale inteiro vire cinzas!', '', 28153),
(157460, 'ptBR', 'Bom trabalho! O fogo retrocedeu e nossas casas ainda estão de pé. Obrigado.', '', 28153),
(157459, 'ptBR', 'Não vou deixar os sethraks levarem nem o próprio saque quando saírem daqui.', 'Não vou deixar os sethraks levarem nem o próprio saque quando saírem daqui.', 28153),
(157458, 'ptBR', 'Por mais que eu não possa convocar nossos fuzileiros de volta... pelo menos nós sabemos que eles estão em algum lugar por aí. O destino da frota está nas mãos dos Proudmore.', '', 28153),
(157457, 'ptBR', 'Jani é o loa das coisas jogadas fora e do povo que os outros às vezes tratam como refugo ou ignoram. Ele cuida de órfãos que nem eu e de qualquer um que tenha ido parar numa situação ruim.', '', 28153),
(157456, 'ptBR', 'Minha magia fica mais forte aqui. Se existe alguma chance de eu localizar a nossa frota, a hora de tentar é agora.', '', 28153),
(157455, 'ptBR', 'Hunf... Cai fora... <hic!> Eu tô ocupado.', '', 28153),
(157454, 'ptBR', 'A gente é seguidor do Torcali, a Montanha Movente, o Baluarte Errante. Se nosso loa quiser, nada vai passar pelos nossos escudos.', '', 28153),
(157453, 'ptBR', '', 'Já é um perigo a menos no vale! Bom trabalho!', 28153),
(157452, 'ptBR', '', 'Eita... estou sem palavras. Foi uma luta incrível!', 28153),
(157451, 'ptBR', 'Espere aqui. Acho que estou vendo alguma coisa.', '', 28153),
(157450, 'ptBR', 'Eu nunca achei que isso fosse dar certo, mas o ouro vai ajudar muita gente a sacudir a poeira e se reerguer na vida!', '', 28153),
(157449, 'ptBR', 'Sim... eu sinto os navios... nossa frota! O nevoeiro cerrado que os envolve está se dissipando!', '', 28153),
(157448, 'ptBR', 'Eu estou aqui para resolver seus problemas, Krog.', 'Eu estou aqui para resolver seus problemas, Krog.', 28153),
(157447, 'ptBR', '', 'Alguns membros do Rastro da Tempestade avistaram uma fera arisca nas redondezas. Mas você deve dar conta do recado!', 28153),
(157446, 'ptBR', '', 'Um monstro vem rondando a serra. Encontre-o antes que alguém acabe machucado!', 28153),
(157445, 'ptBR', 'Os caçadores de tesouro da Água Morta vão doar uma quantia em ouro para ajudar na reconstrução de Brennadam. Só tem uma pegadinha: quem vai recolher o ouro somos nós!', '', 28153),
(157444, 'ptBR', 'Artur...', '', 28153),
(157443, 'ptBR', 'Doraso, eu preciso de uma mantícora para a Aldeia Muralha Verde.', 'Doraso, eu preciso de uma mantícora para a Aldeia Muralha Verde.', 28153),
(157442, 'ptBR', '', 'Bom trabalho. Ao salvar Ai\'twen, você fez um favor aos tortollanos... e deve ter agradado os loas também, imagino.', 28153),
(157441, 'ptBR', 'Ei, eu derrubei pedras! Umas pedras bem nervosas.', '', 28153),
(157440, 'ptBR', 'Você tinha ordens de derrubar marcos.', '', 28153),
(157439, 'ptBR', 'Ah, como assim? No fim das contas, tudo terminou bem. Eu e $Uo:a; continental acabamos com aquele monstrão de pedra e saímos com vida! Foi uma vitória.', '', 28153),
(157438, 'ptBR', 'Artur! O que foi que eu disse sobre pular de cabeça nas coisas?', '', 28153),
(157437, 'ptBR', '', 'Tortollanos reverenciam a grande tartaruga Ai\'twen, aliada poderosa de tempos idos. A proteja e alimente para que continue nos ajudando.', 28153),
(157436, 'ptBR', 'Saia daqui!', '', 28153),
(157435, 'ptBR', 'Boas ondas te levem, camarada! Seus feitos servirão de exemplo para todos nós.', '', 28153),
(157434, 'ptBR', 'Então seguiremos para o sul. Manteremos contato, Gusberto.', '', 28153),
(157433, 'ptBR', 'Mostra o que sabe, Gusba!', '', 28153),
(157432, 'ptBR', '', 'Vai com tudo, Gusberto!', 28153),
(157431, 'ptBR', 'COM BOMBA ATÉ A TAMPA!', '', 28153),
(157430, 'ptBR', 'Pequena escavação, é? Parece trabalho pra um gnomo...', '', 28153),
(157429, 'ptBR', 'Há uma pequena escavação do Relicário cerca de meio quilômetro a leste daqui.', '', 28153),
(157428, 'ptBR', '$n, atrás de você! Ajude-me a tirar esses estorvos do caminho.', '', 28153),
(157427, 'ptBR', 'Ai\'twen, a tartaruga ancestral, é um mistério do mar e tem que ser protegida. Ajude os tortollanos a mantê-lo seguro e bem alimentado.', '', 28153),
(157426, 'ptBR', 'Nós faremos o Lorde Trovamare pagar por suas transgressões... ou morreremos tentando.', '', 28153),
(157425, 'ptBR', 'O povo de Trovamare merece uma sensação de segurança. Não tenha misericórdia de ninguém que ameace esse sentimento.', '', 28153),
(157424, 'ptBR', 'Se quisermos salvar a frota das garras de Azshara, temos que tomar uma atitude.', '', 28153),
(157423, 'ptBR', 'É perigoso aqui. Venha, tem uma guarita aqui perto que dá para o Santuário.', '', 28153),
(157422, 'ptBR', 'Mas ele jamais será esquecido... enquanto nós estivermos vivos.', '', 28153),
(157421, 'ptBR', 'A voz agora faz eco à sua. Você a sente buscar uma resposta, pois você também a busca.\n\n\"Com que fim?\"', '', 28153),
(157420, 'ptBR', 'Você estremece de dor quando a voz grita dentro de você.\n\n\"Onde foi que começou?\"', '', 28153),
(157419, 'ptBR', 'Você tem a minha gratidão. Agora os fazendeiros poderão voltar aos seus roçados.', '', 28153),
(157418, 'ptBR', 'Eu recebi notícias sobre um perigo que vem rondando as fazendas. Ajude a restaurar a ordem no vale!', '', 28153),
(157417, 'ptBR', 'A voz fica mais forte e mais ávida.\n\n\"Mais! Mais! Mais!\"', '', 28153),
(157416, 'ptBR', 'A voz ancestral agora é só um eco, chamando das profundezas da sua mente.\n\n\"O que procura?\"', '', 28153),
(157415, 'ptBR', 'Você é mesmo uma caixinha de surpresas! Bem que poderia me ensinar uns truques.', '', 28153),
(157414, 'ptBR', 'Bom trabalho. Se precisar tirar alguma coisa de Boralus, nós temos agentes disponíveis nas redondezas.', '', 28153),
(157413, 'ptBR', 'Eu vou me esgueirar de volta para contar a Betulosque. Nos vemos lá!', '', 28153),
(157412, 'ptBR', 'HA! Sucumbiu à nossa força!', '', 28153),
(157411, 'ptBR', '', 'Sam... ele... se foi...', 28153),
(157410, 'ptBR', 'Quando o último súdito humano for morto e transformado em Renegado, o reizinho se ajoelhará perante a Dama Sombria. E eis que, finalmente, só haverá uma rainha para governar a todos.', '', 28153),
(157409, 'ptBR', 'Vingança. Desprezo. Chame do que quiser.', '', 28153),
(157408, 'ptBR', '', 'Você é motivado pela vingança. Algo que eu admiro.', 28153),
(157407, 'ptBR', 'Quando nós nos libertamos do Lich Rei, Sylvana buscou aliados. Em vez de acolher seus irmãos decaídos de Lordaeron, os humanos nos escorraçaram. Nos caçaram. Então eu jurei caçá-los também.', '', 28153),
(157406, 'ptBR', '', 'Desde que eles deram as costas?', 28153),
(157405, 'ptBR', 'Eu já lutei pela causa deles. A soberba insuportável da Aliança aumentou dez vezes desde que eles nos deram as costas.', '', 28153),
(157404, 'ptBR', '', 'Eu diria que o afinco com que você ataca a Aliança não vem só da sua reverência pela rainha, Arauto da Praga.', 28153),
(157403, 'ptBR', '', 'Eu provoquei a queda de um rei. Já está na hora de acabar com o reinado de outro.', 28153),
(157402, 'ptBR', 'Que bom. A Aliança não merece simpatia... nem misericórdia. Faça com que sofram e será recompensada pela Dama Sombria.', '', 28153),
(157401, 'ptBR', '', 'Não foi. E, na certa, você sabe que eu trabalhei com a Aliança quando isso serviu aos meus interesses. Mas não devo nada a eles. Minha casa é a Horda.', 28153),
(157400, 'ptBR', 'Seus tolos...', '', 28153),
(157399, 'ptBR', 'Em nome de Kul Tiraz, você há de sumir deste lugar!', '', 28153),
(157398, 'ptBR', 'Eu conheço a história. E também estou ciente de que matar Llane Wrynn não foi uma escolha sua.', '', 28153),
(157397, 'ptBR', '', 'Só porque eu já fui amiga do avô do jovem rei? Fui eu quem o assassinou, caso você não esteja lembrado.', 28153),
(157396, 'ptBR', 'Os ataques aos alvos da Aliança foram bastante impressionantes, Garona. Eu confesso que tinha dúvidas quanto à sua lealdade.', '', 28153),
(157395, 'ptBR', 'Hehehe... carne fresca!', '', 28153),
(157394, 'ptBR', 'Sinta a fúria da natureza!', '', 28153),
(157393, 'ptBR', 'Eu vou reduzir você a pó!', '', 28153),
(157392, 'ptBR', 'Tem certeza de que quer continuar?', 'Tem certeza de que quer continuar?', 28153),
(157391, 'ptBR', 'Bom trabalho, $p. O Vale Trovamare lhe deve mais do que poderíamos recompensar.', '', 28153),
(157390, 'ptBR', 'Sonhe, sonhe com a Cidade Submersa.', 'Sonhe, sonhe com a Cidade Submersa.', 28153),
(157389, 'ptBR', 'Encontrado à sombra do olhar Dele...', 'Encontrado à sombra do olhar Dele...', 28153),
(157388, 'ptBR', 'Perdido nos braços implacáveis Dela...', 'Perdido nos braços implacáveis Dela...', 28153),
(157387, 'ptBR', 'Inspirar a sabedoria dos afogados...', 'Inspirar a sabedoria dos afogados...', 28153),
(157386, 'ptBR', 'Os sobreviventes na Cabana das Colinas Atrozes já estão lutando há dias. Tente ajudá-los, e dê a eles uma chance de descansar.', '', 28153),
(157383, 'ptBR', 'Que quantidade impressionante de explosões! Ainda bem que nenhuma pegou você nem o Toki.', '', 28153),
(157382, 'ptBR', 'Beba fundo da maré iridescente...', 'Beba fundo da maré iridescente...', 28153),
(157381, 'ptBR', 'A Empreendimentos S.A. continua destruindo o litoral. Encontre o Toki e veja se consegue ajudar.', '', 28153),
(157380, 'ptBR', 'Hm...', 'Hm...', 28153),
(157379, 'ptBR', 'Você encontra um altar tenebroso. Ao colocar a mão nele, palavras começam a inundar sua mente.\n\n\"Como você começará?\"', '', 28153),
(157378, 'ptBR', 'Bom trabalho. Eu lhe devo um drinque depois dessa.', '', 28153),
(157377, 'ptBR', 'Espere até eu pôr as garras em você!', '', 28153),
(157376, 'ptBR', 'Vou rasgar você no meio!', '', 28153),
(157375, 'ptBR', 'Quero os Maré-férrea longe daqui. Vamos ver se eles ainda vão querer ficar na região depois que deixarmos a vida deles ainda mais infeliz.', '', 28153),
(157374, 'ptBR', 'Por Drustvar!', '', 28153),
(157373, 'ptBR', 'Venha! Vamos transformar aquele monstro em pó!', '', 28153),
(157372, 'ptBR', '', 'Os tortollanos agradecem pela ajuda, e eu também.', 28153),
(157371, 'ptBR', '', 'Aqueles brutamontes da Empreendimentos S.A continuam antagonizando os tortollanos! Vá ao encontro de Toki para ajudá-lo.', 28153),
(157370, 'ptBR', '', 'Nossos inimigos vão saber que um membro da Horda pôs fim nas suas tramoias. Bom trabalho.', 28153),
(157369, 'ptBR', '', 'O inimigo está cada vez mais atrevido! Tome os recursos deles... e as vidas, se preciso.', 28153),
(157368, 'ptBR', '', 'Enquanto nós nos fortalecemos, o inimigo enfraquece. Pequenas vitórias levam a grandes triunfos.', 28153),
(157367, 'ptBR', '', 'Os soldados não vão vencer a guerra de barriga vazia. A carne de urso vai alimentar nossas tropas. Não deixe o inimigo interferir.', 28153),
(157362, 'ptBR', 'Coisas ancestrais que não deveriam existir estão se revolvendo. Fique de prontidão.', 'Coisas ancestrais que não deveriam existir estão se revolvendo. Fique de prontidão.', 28153),
(157361, 'ptBR', 'Não esperávamos que os mortos começassem a andar!', 'Não esperávamos que os mortos se erguessem e começassem a andar!', 28153),
(157360, 'ptBR', 'Não esperávamos tanto poder! Tenha cuidado, continental.', 'Não esperávamos tanto poder! Tenha cuidado, continental.', 28153),
(157359, 'ptBR', 'Os constructos têm que ser destruídos. Por favor, ajude!', 'Os constructos têm que ser destruídos. Por favor, ajude!', 28153),
(157358, 'ptBR', 'A hora certa de ajudar, continental.', 'A hora certa de ajudar, continental.', 28153),
(157357, 'ptBR', '$p, pare. Viu aquilo?', '', 28153),
(157356, 'ptBR', 'Eles recuaram por enquanto, e a cidade ainda está de pé. Nós devemos nossas vidas a você.', '', 28153),
(157355, 'ptBR', 'A Horda voltou em peso para tentar terminar o serviço. Detenha esses malditos de qualquer jeito!', '', 28153),
(157354, 'ptBR', 'Ele fica na dele a maior parte do tempo, mas sabe bem quando está numa encrenca. Obrigado pela ajuda!', '', 28153),
(157353, 'ptBR', 'Campodouro diz que precisa da sua ajuda. Os ataques à fazenda dele não cessaram, e ele está ficando sem suprimentos. Ajude-o como puder.', '', 28153),
(157352, 'ptBR', 'Eles vão pensar duas vezes antes de tentar essa de novo! Dá uma coçadinha extra naquele cachorro para mim.', '', 28153),
(157351, 'ptBR', 'Os javatuscos estão tentando expandir a rede de túneis, colocando o vale em risco. Nossos cães podem farejá-los, se souberem onde começar.', '', 28153),
(157350, 'ptBR', 'Vamos indo, $p.', '', 28153),
(157349, 'ptBR', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t Você está sob efeito de |cFFFF0000|Hspell:272536|h[Ruína Iminente]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t Você está sob efeito de |cFFFF0000|Hspell:272536|h[Ruína Iminente]|h|r!', 28153),
(157348, 'ptBR', 'Sabe de uma coisa, essa câmara é ideal para exibir a coleção real de antiguidades. A gente devia...', '', 28153),
(157347, 'ptBR', '', 'Estarei por perto.', 28153),
(157346, 'ptBR', 'Shandris, mantenha a discrição. Permaneça nas sombras... se encontrar alguma.', '', 28153),
(157345, 'ptBR', '', 'QSL, Alto-comandante! Vamos voar!', 28153),
(157344, 'ptBR', 'Kelsey, você é nossos olhos no céu. Avise se avistar alguma coisa.', '', 28153),
(157343, 'ptBR', 'Você pode repetir o plano?', 'Você pode repetir o plano?', 28153),
(157342, 'ptBR', 'Meus pais sempre diziam que eu tinha a imaginação fértil.', '', 28153),
(157341, 'ptBR', 'Às vezes, a gente descia as ribanceiras do vale de carrinho! A gente fingia que o Hobert era um tigre!', '', 28153),
(157340, 'ptBR', 'Eu e Hobert vivíamos aventuras de monte na época de criança.', '', 28153),
(157339, 'ptBR', 'Mostre-me.', 'Mostre-me.', 28153),
(157338, 'ptBR', 'As visões podem nos ajudar a observar a carnificina, $r.', 'As visões podem nos ajudar a observar a carnificina, $r.', 28153),
(157337, 'ptBR', 'Falta pouco para ela iluminar a nossa frota, e então toda Kul Tiraz se curvará à luz sob a maré.', '', 28153),
(157336, 'ptBR', 'Vocês estão cegos. A bênção da Mãe das Marés nos devolveu nossa força.', '', 28153),
(157335, 'ptBR', 'Almas dos corrompidos, vocês ainda cumprirão seu juramento. Arrebentem o portão!', '', 28153),
(157334, 'ptBR', '', '|TINTERFACE\\ICONS\\INV_TikiMan2_Bloodtroll.blp:20|t A Anciã Leaxa começa a lançar |cFFF00000|Hspell:264603|h[Espelho de Sangue]|h|r!', 28153),
(157333, 'ptBR', '', 'Tô otimista com essa caverna. Já vejo a montanha de ouro dentro dela.', 28153),
(157332, 'ptBR', 'Mas eu tava chegando bem na parte que eu mergulho goela abaixo do bichão e rasgo ele de dentro pra fora!', 'Mas eu tava chegando bem na parte que eu mergulho goela abaixo do bichão e rasgo ele de dentro pra fora!', 28153),
(157331, 'ptBR', 'Tá, tá, Linha e Chumbada ajudaram. Mas todo o resto é verdade... cada sílaba!', 'Tá, tá, Linha e Chumbada ajudaram. Mas todo o resto é verdade... cada sílaba!', 28153),
(157330, 'ptBR', 'Hunf hunf hunf hunf, hunf hunf!', 'Hunf, hunf, hunf, hunf, hunf!', 28153),
(157329, 'ptBR', 'Cala a boca, Linha. Espera a sua vez!', 'Fecha a matraca, Linha. Espera a sua vez!', 28153),
(157328, 'ptBR', '', 'Nada de ouro, mas tem um monte de rum!', 28153),
(157327, 'ptBR', 'É, com a minha mira perfeita!', 'É, com a minha mira perfeita!', 28153),
(157326, 'ptBR', 'Graças à minha sagacidade afiadíssima, eu sabia exatamente como abater o bicho.', 'Graças à minha sagacidade afiadíssima, eu soube exatamente como abater a fera.', 28153),
(157325, 'ptBR', 'Foi então que eu o vi no horizonte. Um monstro como nunca tinha visto!', 'Foi então que eu vi no horizonte... Um monstro como eu nunca tinha visto igual!', 28153),
(157324, 'ptBR', 'Eu estava com a primeira guarda, de olho para ver se apareciam mais daquelas nagas malditas.', 'Eu estava com a primeira guarda, de olho para ver se apareciam mais daquelas nagas malditas.', 28153),
(157323, 'ptBR', 'Agora deixa eu lhe contar como conheci esses dois pobres coitados.', 'Agora deixa eu lhe contar como conheci esses dois pobres coitados.', 28153),
(157322, 'ptBR', 'Sim, até eu concordo... Ei, espera aí!', 'Sim, até eu concordo... Ei, espera um minuto!', 28153),
(157321, 'ptBR', 'Esse capacete lhe subiu à cabeça. Acho mais fácil acreditar que Linha conseguiu pegar um peixe!', 'Esse capacete lhe subiu à cabeça. Acho mais fácil acreditar que Linha conseguiu pegar um peixe!', 28153),
(157320, 'ptBR', 'Hunf, hunf, hunf, hunf, hunf. Hunf.', 'Hunf, hunf, hunf, hunf, hunf. Hunf.', 28153),
(157319, 'ptBR', 'HUNF!!!', 'HUNF!!!', 28153),
(157318, 'ptBR', 'Hunf hunf... hunf!', 'Hunf, hunf... hunf.', 28153),
(157317, 'ptBR', 'Por sorte, trago sempre a minha bala especial pendurada no pescoço para essas ocasiões.', 'Ainda bem que eu trago a minha bala especial pendurada no pescoço o tempo todo para essas ocasiões.', 28153),
(157316, 'ptBR', 'Eu guardo o rum até o capitão voltar.', '', 28153),
(157315, 'ptBR', 'Capitão... não bebi nadica.', '', 28153),
(157314, 'ptBR', '', 'Onde tem pirata, geralmente tem ouro!', 28153),
(157313, 'ptBR', '', 'Alguns dos trabalhadores disseram ter visto um fantasma de pirata nessa caverna.', 28153),
(157312, 'ptBR', '', 'Brennadam fica logo adiante. Vamos logo!', 28153),
(157311, 'ptBR', '', 'Kul Tiraz ficará exposta. É só questão de tempo para nos atacarem.', 28153),
(157310, 'ptBR', '', 'Temos que encontrar o Irmão Pique Ele nos ajudará a trazer a frota para casa.', 28153),
(157309, 'ptBR', '', 'O vale não é magnífico? É por isso que quem chega não quer mais sair.', 28153),
(157308, 'ptBR', '', 'Esta passagem é a única forma de chegar ao vale por terra. A Casa Trovamare está armando alguma coisa.', 28153),
(157307, 'ptBR', '', 'Brennadam é o maior polo comercial de Kul Tiraz, depois de Boralus.', 28153),
(157306, 'ptBR', 'Quero ver esforço, seus sacos de batatas inúteis!', 'Quero ver esforço, seus sacos de batatas inúteis!', 28153),
(157305, 'ptBR', 'Ele tá bem ali. Duas cabeças e gigantão!', 'Ele tá bem ali, se preparando pra atacar!', 28153),
(157304, 'ptBR', 'Vai cuidar dos seus pontos de vida. Eu tô aqui resolvendo assuntos oficias!', 'Vai cuidar dos seus pontos de vida. Eu tô aqui resolvendo assuntos oficias!', 28153),
(157303, 'ptBR', 'O que você está fazendo? Você tem que sair com o resto de nós!', 'O que você está fazendo? Você tem que sair com o resto de nós!', 28153),
(157302, 'ptBR', 'Cuidado com a clava!', 'É bom fugir, Tom. Nós somos mais!', 28153),
(157301, 'ptBR', 'A culpa disso... é de vocês. A gente sabe.', 'A culpa disso... é de vocês. A gente sabe.', 28153),
(157300, 'ptBR', 'Vem lutar comigo... com a gente!', 'Vem lutar comigo... com a gente!', 28153),
(157299, 'ptBR', 'Eu cuido da cabeça da direita.', 'Ele é maior do que eu achei que fosse.', 28153),
(157298, 'ptBR', 'Inspecionando', 'Inspecionando', 28153),
(157296, 'ptBR', 'Bem-vindos de volta, meus amiguinhos. Ouçam só a música nova que aprendi!', '', 28153),
(157294, 'ptBR', 'Depois que tu morrer, eu vou lá esmigalhar todo mundo na cidade!', 'Depois que tu morrer, eu vou lá esmigalhar todo mundo na cidade!', 28153),
(157293, 'ptBR', 'O Rastro da Tempestade vai guiar a frota até a vitória para a Aliança, como já fizemos.', '', 28153),
(157292, 'ptBR', '', 'A Casa Capelo está com a senhora, Lorde-almirante. E com a Aliança.', 28153),
(157291, 'ptBR', '', 'E reatar os laços com a Aliança, cujos heróis nos salvaram de nossa própria derrocada.', 28153),
(157290, 'ptBR', '', 'Peço agora que depositem sua fé na minha filha Jaina, a verdadeira Lorde-almirante de Kul Tiraz.', 28153),
(157289, 'ptBR', '', 'A Horda também deixou suas intenções bem claras: aqueles selvagens querem ver nossas cinzas.', 28153),
(157288, 'ptBR', '', 'A divisão nos tornou vulneráveis. Somos atacados por inimigos internos.', 28153),
(157287, 'ptBR', '', 'Agradeço a presença de todos. Eu serei rápida.', 28153),
(157286, 'ptBR', 'Aposto que nós dois podemos dar cabo desses monstros!', '', 28153),
(157285, 'ptBR', 'Quando Daelin me pediu para deixar a guarda e criar essa filha dos Reinos do Leste, eu me esforcei para entender o porquê. \n\nPor que confiar este fardo a mim? Por que me negar a honra de lutar ao lado dele? Eu me perguntava se, por alguma razão, tinha perdido sua confiança. \n\nAo longo dos anos, compreendi que se tratava do contrário. Seu desejo era que Taelia se tornasse forte e crescesse com um coração nobre. Ele acreditava que eu poderia fazer com que isso acontecesse.', '', 28153),
(157284, 'ptBR', '', 'É verdade que é possível viajar de Ventobravo para Altaforja por um túnel subterrâneo?$B$BQue incrível! Eu bem que gostaria de ver isso um dia.', 28153),
(157283, 'ptBR', 'E isso foi só um tiquinho! Imagine o estrago que não dá para fazer com uma quantidade boa.', '', 28153),
(157282, 'ptBR', '', 'Obrigada. Agora os moradores podem voltar a trabalhar a terra em paz.', 28153),
(157281, 'ptBR', '', 'Tem uma criatura pondo os fazendeiros da região em risco. Nós temos que ajudá-los!', 28153),
(157280, 'ptBR', '', 'Excelente! Eles vão saber como aproveitar os suprimentos.', 28153),
(157279, 'ptBR', '', 'Tomara que um dia os moradores de Kul Tiraz possam voltar a confiar na liderança dos Sábios das Marés. Até lá, teremos que trilhar nosso próprio caminho.', 28153),
(157278, 'ptBR', '', 'Isso vai nos dar um tempinho para arejar as ideias. Muito obrigada.', 28153),
(157277, 'ptBR', '', 'O povo de Trovamare não se esquecerá do que você fez. Bom trabalho!', 28153),
(157276, 'ptBR', '', 'Esta serra está cheia de recursos importantes para o Rastro da Tempestade. Por que você não vai ajudá-los?', 28153),
(157275, 'ptBR', '', 'As forças do Lorde Trovamare estão dando trabalho outra vez. Não podemos deixar que esses rituais macabros continuem!', 28153),
(157274, 'ptBR', '', 'Nós perdemos o controle da área! Trate de expulsar o inimigo daqui!', 28153),
(157273, 'ptBR', '', 'O Rastro da Tempestade precisa de ajuda. Faça o que for preciso para restaurar a paz no vale!', 28153),
(157272, 'ptBR', '', 'Canhoneiros! Preparem a salva final!', 28153),
(157271, 'ptBR', '', 'Mantenham o escudo! Já está difícil com ele!', 28153),
(157270, 'ptBR', 'Mais uma Renegada. Não achei que... <cof>. Diga-me, senhorita...?', '', 28153),
(157269, 'ptBR', '<cof> A Horda. E eu aqui pensando que ia morrer em paz.\n\nE você é Renegado? Interessante, mas tarde demais.\n\nBem, o que você está esperando?', '', 28153),
(157268, 'ptBR', 'Nos vemos de novo na carroça, $p!', '', 28153),
(157267, 'ptBR', '', 'Issa! Tá na hora do saque!', 28153),
(157266, 'ptBR', 'Por favor, leve-me de volta.', 'Por favor, leve-me de volta.', 28153),
(157265, 'ptBR', 'Agradeço pela sua ajuda hoje. É melhor voltarmos.', 'Agradeço pela sua ajuda hoje. É melhor voltarmos.', 28153),
(157264, 'ptBR', 'Assistir ao encontro de Zelão com a família.', 'Assistir ao encontro de Zelão com a família.', 28153),
(157263, 'ptBR', 'Excelente trabalho como sempre, camarada. Se todos na Aliança cavalgarem bem assim, então serão bem-vindos na minha herdade!', '', 28153),
(157262, 'ptBR', 'Ah, que belo dia para uma briga! Suba na sua montaria, camarada, e mostre do que você é capaz no ringue!', '', 28153),
(157261, 'ptBR', '', 'Faça como preferir. Venha, $n.', 28153),
(157260, 'ptBR', 'Estou voltando à base. Sei como isso acaba, não preciso assistir.', '', 28153),
(157259, 'ptBR', 'Tu fica sabendo que tu tá no meio de gente superior a ti. Não fica te metendo no meu tempo com o Senhor da Bagata.', '', 28153),
(157258, 'ptBR', '', 'Fantástico! Isso vai dar um jeito nas nagas.', 28153),
(157257, 'ptBR', '', 'Você tem a minha palavra. Venha. $n, volte a Nathanos e diga a ele que temos o que precisamos.', 28153),
(157256, 'ptBR', 'Vou me juntar a vocês... e ajudar a achar o Marechal Valentim. Desde que vocês prometam que minha família continuará ilesa.', '', 28153),
(157255, 'ptBR', '', 'As nagas lançaram outra investida contra o forte! Cuide delas no estilo tortollano!', 28153),
(157254, 'ptBR', '', 'Junte-se aos Renegados e crie seu próprio destino. Você estará entre aqueles que aceitam o que você se tornou.', 28153),
(157253, 'ptBR', 'E o que vai ser de mim? Vou ser um escravo da Rainha Banshee?', '', 28153),
(157252, 'ptBR', '', 'É raríssimo alguém de fora de Zandalar receber essa honraria. Queira me acompanhar, e me conte dos grandes feitos de Vol\'jin.', 28153),
(157250, 'ptBR', '', 'Eu tentei avisar você, Zelão. O processo é transformativo. Os vivos não aceitarão mais você.', 28153),
(157249, 'ptBR', 'Não... Júlia... Mateus... Anna... o que foi que eu fiz? O quê... sou eu?', '', 28153),
(157248, 'ptBR', '', 'Faz o monstro ir embora!', 28153),
(157247, 'ptBR', '', 'Nos deixe em paz!', 28153),
(157246, 'ptBR', 'Tira isso daqui!', '', 28153),
(157245, 'ptBR', 'Silêncio!', '', 28153),
(157244, 'ptBR', '', 'Não sei quem você é, mas meu marido NUNCA tentou machucar a mim ou aos nossos filhos. Vamos embora... não nos siga!', 28153),
(157243, 'ptBR', 'Eu... eu...', '', 28153),
(157242, 'ptBR', 'JÁ CHEGA!', '', 28153),
(157241, 'ptBR', 'Mamãe, socorro!', '', 28153),
(157240, 'ptBR', '', 'Fique longe!', 28153),
(157239, 'ptBR', 'O papai está aqui. Escutem a minha voz! Por que vocês não entendem?!', '', 28153),
(157238, 'ptBR', '', 'Afaste-se!', 28153),
(157237, 'ptBR', 'Mamãe, tô com medo do monstro!', '', 28153),
(157236, 'ptBR', 'Por que vocês não entendem?! Sou eu, seu marido... Crianças, é o papai!', '', 28153),
(157235, 'ptBR', '', 'Pela última vez, AFASTE-SE! Você NÃO é meu marido!', 28153),
(157234, 'ptBR', 'Continuo forte... mesmo na morte.', '', 28153),
(157233, 'ptBR', 'Você não está em condições de me enfrentar em combate!', '', 28153),
(157232, 'ptBR', 'Zelão, precisamos que você encontre o cadáver do Marechal Valentim.', 'Zelão, precisamos que você encontre o cadáver do Marechal Valentim.', 28153),
(157231, 'ptBR', 'Minha família vai... me vingar.', '', 28153),
(157230, 'ptBR', 'Você será o foco da minha fúria!', '', 28153),
(157229, 'ptBR', '', 'Vamos ver o que acontece agora.', 28153),
(157228, 'ptBR', 'Eu... estou vivo! Hahaha! Tenho que ir ver Júlia e as crianças, elas vão ficar felicíssimas!', '', 28153),
(157227, 'ptBR', '', 'Poucos foram os espíritos que demonstraram tamanho poder... Mestre Gadrin, eu lhe peço que leve as cinzas do chefe para Atal\'Dazar. Se o espírito dele for digno, ele terá um lugar de honra entre os reis.', 28153),
(157226, 'ptBR', 'Zalazane não vai voltar depois dessa. O Vol\'jin cuida da gente mesmo depois de morto.', '', 28153),
(157225, 'ptBR', 'Os mortos tão caindo...', '', 28153),
(157224, 'ptBR', 'Nossos reforços aguardam suas ordens.', '', 28153),
(157223, 'ptBR', 'Se a Horda quer guerra, nós vamos lhes dar tudo que temos!', '', 28153),
(157222, 'ptBR', 'Espero que você tenha boas notícias.', '', 28153),
(157221, 'ptBR', 'Trovamare há de perdurar.', '', 28153),
(157220, 'ptBR', 'Boa viagem.', '', 28153),
(157219, 'ptBR', 'Que as marés guiem você.', '', 28153),
(157218, 'ptBR', 'Excelente! Os suprimentos vão cair muito bem, e vamos arranjar alguma utilidade para os porquinhos.', '', 28153),
(157217, 'ptBR', 'Os javatuscos andam saqueando nossos estoques de novo. É olho por olho! Recupera os nossos suprimentos, e tudo mais que parecer útil!', '', 28153),
(157216, 'ptBR', 'Pode deixar.', '', 28153),
(157215, 'ptBR', '', 'Sim, senhor!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157214, 'ptBR', '', 'Eluna toda misericordiosa, eu lhe rogo que abençoe os mortos.', 28153),
(157213, 'ptBR', 'Taelia, prepare-se para a sua ronda novamente. Diga à guarda da cidade para ficar de olho em armas estranhas sendo traficadas para Boralus.', '', 28153),
(157212, 'ptBR', '', 'Que todos saibam que eu considero Vol\'jin, filho de Sen\'jin, digno destas tumbas sagradas. Porém, para entrar em Atal\'Dazar, talvez você tenha que lutar. Recomendo que seja o campeão a levar essas cinzas para o local de descanso final delas.', 28153),
(157211, 'ptBR', '', 'É difícil ter que fazer aquilo que nossos líderes se recusam a fazer.', 28153),
(157210, 'ptBR', 'Quando ficou explanado que o Garrosh, nosso Chefe Guerreiro, era um líder sem honra, o Vol\'jin mandou uma rebelião para tirar aquele maníaco.', '', 28153),
(157209, 'ptBR', '', 'Na época, a visão que Zul tinha de um império trólico grandioso foi tentadora demais para o meu pai. Tenho que agradecer ao seu chefe por ter enxergado tudo com clareza.', 28153),
(157208, 'ptBR', 'Quando Zandalar tentou juntar as tribos, o Vol\'jin escolheu a segurança do povo, em vez dos poderes sinistros do profeta.', '', 28153),
(157207, 'ptBR', 'O Vol\'jin arranjou um esquema com o Bwonsamdi pra derrotar o Zalazane.', '', 28153),
(157206, 'ptBR', '', 'Tem fogo-fátuo a perder de vista. Quantas vidas perdidas...', 28153),
(157205, 'ptBR', 'A gente trouxe as cinzas de Vol\'jin, filho de Sen\'jin, para serem honradas neste lugar sagrado.', '', 28153),
(157204, 'ptBR', 'Filinto, eu tenho outro serviço para você: ajude a descobrir a origem dessa pólvora.', '', 28153),
(157203, 'ptBR', 'Antigas ameaças despertam nestas terras. Cuidado.', '', 28153),
(157202, 'ptBR', 'Arauto do Vento, vim sob as ordens da Chefe Guerreira.', 'Arauto do Vento, vim sob as ordens da Chefe Guerreira.', 28153),
(157201, 'ptBR', 'Sim, preciso ir a Silithus.', 'Sim, preciso ir a Silithus.', 28153),
(157200, 'ptBR', 'Por que estou aqui, humano?', 'Por que estou aqui, humano?', 28153),
(157199, 'ptBR', 'Você se importa em fazer uma demonstração para os nossos coleguinhas céticos?', '', 28153),
(157198, 'ptBR', 'Inventam, mas não que nem essa.', '', 28153),
(157197, 'ptBR', 'Que raio de descoberta é essa? Eles inventam armas novas o tempo todo.', '', 28153),
(157196, 'ptBR', '', 'Certo, Filinto. Qual foi a grande descoberta? A Grimpagris arranjou um tipo novo de pólvora por acaso?', 28153),
(157195, 'ptBR', 'Preciso de uma mantícora para o Refúgio do Marshal na Cratera Un\'Goro.', 'Preciso de uma mantícora para o Refúgio do Marshal na Cratera Un\'Goro.', 28153),
(157194, 'ptBR', 'Tu voltou... que bom! Já tava quase falando pra princesa que o anão de diamante tinha vindo pra te sequestrar!', '', 28153),
(157193, 'ptBR', 'Eita! A gente fez um excelente trabalho!', '', 28153),
(157192, 'ptBR', 'A gente precisa recuperar parte da carga perdida. \"A gente\", no caso, é você.', '', 28153),
(157191, 'ptBR', 'Não sei pra onde tu vai, mas tomara que a viagem seja breve. A princesa precisa da tua ajuda.', 'Não sei pra onde tu vai, mas tomara que a viagem seja breve. A princesa precisa da tua ajuda.', 28153),
(157190, 'ptBR', 'Que coisa extraordinária! É melhor eu anotar tudo.', 'Que coisa extraordinária! É melhor eu anotar tudo.', 28153),
(157189, 'ptBR', 'Proteger as rotas de abastecimento é fundamental na guerra... assim como barrar as rotas do inimigo.', '', 28153),
(157188, 'ptBR', 'Naufrágios da Aliança... uma cena que faz valer o dia! Vasculhem a área em busca de suprimentos para a Horda.', '', 28153),
(157187, 'ptBR', 'São os ossos do ofício.', '', 28153),
(157186, 'ptBR', 'Estão atacando o extrator! Proteja-o!', '', 28153),
(157185, 'ptBR', 'É graças a esses recursos que a Horda pode prosseguir com suas operações. Bom trabalho.', '', 28153),
(157184, 'ptBR', 'Proteja o extrator! Nós precisamos da azerita!', '', 28153),
(157183, 'ptBR', 'Qual é a sua estratégia, Shandris?', 'Qual é a sua estratégia, Shandris?', 28153),
(157182, 'ptBR', '', '<Os olhos aguçados de Shandris varrem o horizonte. Ela acena com a cabeça em reconhecimento.>', 28153),
(157181, 'ptBR', 'Encontrar o Helioguarda, então crivá-lo de flechas.', '', 28153),
(157180, 'ptBR', ' Minha estratégia?', '', 28153),
(157179, 'ptBR', 'A equipe de Operações Secretas de Gnomeregan plantará bombas para fazer o Helioguarda sair, e nós o atacaremos na confusão.', '', 28153),
(157178, 'ptBR', '', 'Ei, ei!', 28153),
(157177, 'ptBR', 'Positivo! Consequentemente, convoquei uma equipe de comandos de elite com a expertise técnica para tanto.', '', 28153),
(157176, 'ptBR', '', 'Você quer... explodir um monte de bombas ao mesmo tempo.', 28153),
(157175, 'ptBR', 'Gostaria de iniciar um ataque incendiário sincronizado a todos os sítios de escavação.', '', 28153),
(157174, 'ptBR', 'Sim. Nossas informações sugerem pelo menos três escavações.', '', 28153),
(157173, 'ptBR', '', 'Arqueologia?', 28153),
(157172, 'ptBR', 'Helioguarda está aqui numa missão arqueológica, como integrante do Relicário.', '', 28153),
(157171, 'ptBR', 'Eu... não me lembro. Mas é melhor assim.', '', 28153),
(157170, 'ptBR', '', 'Com licença, camarada... qual é o seu nome mesmo? Foi de você que Malfurion falou?', 28153),
(157168, 'ptBR', 'Entreguei seu bilhete a B\'wizati.', 'Entreguei seu bilhete a B\'wizati.', 28153),
(157167, 'ptBR', '', 'E os civis... nem eles foram poupados. Tomara que alguns tenham conseguido fugir antes...', 28153),
(157166, 'ptBR', '', 'Nossos postos avançados foram pegos de surpresa. Eles caíram um por um. Os guardas foram envenenados.', 28153),
(157165, 'ptBR', '', '%s enxuga uma lágrima quando ela se levanta.', 28153),
(157164, 'ptBR', '', 'Nós tentamos armar uma emboscada para a Horda. Não deu certo. Não conseguimos impedi-los.', 28153),
(157163, 'ptBR', 'Fico feliz em ver que tu está bem, $n. \n\nEstou bem, também.\n\nAkunda me deu a chance de recomeçar.', '', 28153),
(157162, 'ptBR', 'Qual é o seu plano, Alto-comandante?', 'Qual é o seu plano, Alto-comandante?', 28153),
(157161, 'ptBR', 'A 7ª Legião representa o melhor que Azeroth tem a oferecer.\n\nPela Aliança!', '', 28153),
(157160, 'ptBR', 'Quem? Não conheço nenhum troll com esse nome... será?', '', 28153),
(157159, 'ptBR', '', 'Os corpos... quantos corpos...', 28153),
(157158, 'ptBR', 'Deixa eu te mostrar um negócio, $n. Um presente para ajudar o povo destes pagos.', '', 28153),
(157157, 'ptBR', 'Um anão... feito de diamante... no coração de Zuldazar! Quem é?!', '', 28153),
(157156, 'ptBR', '', 'Já vi de tudo um pouco por essas matas, mas nada assim.', 28153),
(157155, 'ptBR', 'Você sentiu isso? O chão tremeu...', '', 28153),
(157153, 'ptBR', 'A Chefe Guerreira ordenou que eu ajudasse você.', 'A Chefe Guerreira ordenou que eu ajudasse você.', 28153),
(157152, 'ptBR', 'Tenho que voar até Geringontzan, em Tanaris.', 'Tenho que voar até Geringontzan, em Tanaris.', 28153),
(157151, 'ptBR', 'Vocês precisam...', '', 28153),
(157150, 'ptBR', 'Eu condenaria... minha alma... por toda eternidade... se isso trouxesse a felicidade da minha família... por favor! Vocês precisam...', '', 28153),
(157149, 'ptBR', '', 'É algo que me pergunto todos os dias, Zelão.', 28153),
(157148, 'ptBR', 'Alvo localizado.', '', 28153),
(157147, 'ptBR', '', 'Todos nós enlouquecemos um pouco quando nos tornamos Renegados. Alguns mais que os outros.', 28153),
(157146, 'ptBR', 'Você conhece Akunda?', 'Você conhece Akunda?', 28153),
(157145, 'ptBR', 'Deixe que Akunda levante o fardo que pesa em seu coração.', 'Deixe que Akunda levante o fardo que pesa em seu coração.', 28153),
(157144, 'ptBR', 'Akunda nos dá a chance de recomeçar.', 'Akunda nos dá a chance de recomeçar.', 28153),
(157143, 'ptBR', 'Você sempre será bem-vind$Uo:a; aqui.', 'Você sempre será bem-vind$Uo:a; aqui.', 28153),
(157142, 'ptBR', 'O loa dá as boas-vindas a todos no templo dele.', 'O loa dá as boas-vindas a todos no templo dele.', 28153),
(157141, 'ptBR', 'Você conhece Akunda?', 'Você conhece Akunda?', 28153),
(157140, 'ptBR', 'Deixe que Akunda levante o fardo que pesa em seu coração.', 'Deixe que Akunda levante o fardo que pesa em seu coração.', 28153),
(157139, 'ptBR', 'Akunda nos dá a chance de recomeçar.', 'Akunda nos dá a chance de recomeçar.', 28153),
(157138, 'ptBR', 'Você sempre será bem-vind$Uo:a; aqui.', 'Você sempre será bem-vind$Uo:a; aqui.', 28153),
(157137, 'ptBR', 'O loa dá as boas-vindas a todos no templo dele.', 'O loa dá as boas-vindas a todos no templo dele.', 28153),
(157136, 'ptBR', 'Estou aqui para ajudar, Nyse.', 'Estou aqui para ajudar, Nyse.', 28153),
(157135, 'ptBR', 'Ah, o pesadelo acabou.', 'Ah, o pesadelo acabou.', 28153),
(157134, 'ptBR', 'Apontado e preparado! Mandem esse kraken de volta para as profundezas!', 'Apontado e preparado! Mande esse kraken de volta para as profundezas!', 28153),
(157133, 'ptBR', 'Pronto para disparar!', 'Pronto para disparar!', 28153),
(157132, 'ptBR', 'Doraso, preciso voar até Coroa de Barro no Pântano Vadeoso.', 'Doraso, preciso voar até Coroa de Barro no Pântano Vadeoso.', 28153),
(157131, 'ptBR', 'O canhão está pronto! Façam picadinho desse monstro!', 'O canhão está pronto! Faça picadinho desse monstro!', 28153),
(157130, 'ptBR', 'Não... NÃO!', 'Não... NÃO!', 28153),
(157129, 'ptBR', 'Agradecido! Deixe que eu preparo o canhão para dar o troco!', 'Agradecida! Deixe que eu preparo o canhão para dar o troco!', 28153),
(157128, 'ptBR', 'Zabanji ronca.', 'Zabanji ronca.', 28153),
(157127, 'ptBR', 'Eu lhe devo uma! Um segundo, eu vou botar esse canhão para funcionar!', 'Eu lhe devo uma! Um segundo, eu vou botar esse canhão para funcionar!', 28153),
(157126, 'ptBR', 'Era tudo um sonho?', 'Era tudo um sonho?', 28153),
(157125, 'ptBR', 'Não deixe esse monstro me comer!', 'Não deixe esse monstro me comer!', 28153),
(157124, 'ptBR', 'Queimem-nos até não restar nem cinzas!', '', 28153),
(157123, 'ptBR', 'Tire essa coisa de cima de mim!', 'Tire essa coisa de cima de mim!', 28153),
(157122, 'ptBR', '$p, pega uma tocha e bate em qualquer coisa que se mexer. Essas abominações mortas-vivas não merecem nossa consideração!', '', 28153),
(157121, 'ptBR', 'Isso mesmo, soldado. Tem um sem-fim de monstros para matarmos neste porto maldito.', '', 28153),
(157120, 'ptBR', 'Socorro!', 'Socorro!', 28153),
(157119, 'ptBR', 'E ninguém para roubar nossos abates, senhor.', '', 28153),
(157118, 'ptBR', 'Quem é você? Onde estamos?', 'Quem é você? Onde estamos?', 28153),
(157117, 'ptBR', 'Não tem reforços. Não vai ter resgate se a gente falhar.', '', 28153),
(157116, 'ptBR', 'Escutem bem, soldados. Esta é uma missão não autorizada.', '', 28153),
(157115, 'ptBR', 'O que você está esperando, $p?\n\nTemos armas e temos inimigos. Embarca logo!', 'O que você está esperando, $p?\n\nTemos armas e temos inimigos. Embarca logo!', 28153),
(157114, 'ptBR', 'Akunda, o Fatigado, ronca.', 'Akunda, a Fatigada, ronca.', 28153),
(157113, 'ptBR', 'Somos todos... Akunda.', 'Somos todos... Akunda.', 28153),
(157112, 'ptBR', 'Mais trabalho?', '', 28153),
(157111, 'ptBR', 'Certinho.', '', 28153),
(157110, 'ptBR', 'Muito bem.', '', 28153),
(157109, 'ptBR', 'Sim, milorde.', '', 28153),
(157108, 'ptBR', '', 'Sim, senhor.', 28153),
(157107, 'ptBR', 'Certo. Vamos seguir em frente sem ela. Se ela não acordar em breve... preparem suas lâminas.', '', 28153),
(157106, 'ptBR', '', 'Ela está levando algum... tempo para se aclimatar.', 28153),
(157105, 'ptBR', '', 'Hnn.... gh....', 28153),
(157104, 'ptBR', 'Rocha, faça-me uma gentileza e me diga o nome do herói de guerra mais importante deste cemitério.', '', 28153),
(157103, 'ptBR', 'Agora que você finalmente chegou, podemos começar.', '', 28153),
(157102, 'ptBR', 'Lutem por seus irmãos e irmãs!', 'Lutem por seus irmãos e irmãs!', 28153),
(157101, 'ptBR', 'Vitória para a Aliança!', 'Vitória para a Aliança!', 28153),
(157100, 'ptBR', 'À batalha!', 'À batalha!', 28153),
(157099, 'ptBR', 'Você deu um jeito naquela bagunça, $p. Todo mundo vai para casa tranquilo, hoje à noite.', '', 28153),
(157098, 'ptBR', 'Arathi é nossa!', 'Arathi é nossa!', 28153),
(157097, 'ptBR', 'Morte à Horda!', 'Morte à Horda!', 28153),
(157096, 'ptBR', 'Sigam-me!', 'Sigam-me!', 28153),
(157095, 'ptBR', 'Pela Aliança!', 'Pela Aliança!', 28153),
(157094, 'ptBR', 'Por aqui! Temos uma guerra a vencer!', 'Por aqui! Temos uma guerra a vencer!', 28153),
(157093, 'ptBR', 'A Horda espantou todos os bichos para os baixios. Ajude os caçadores a dar um jeito nos ursos.', '', 28153),
(157092, 'ptBR', 'Você... você me fez matar meu amigo! Agora você vai morrer!', '', 28153),
(157091, 'ptBR', 'Irmãos e irmãs, contemplem nosso glorioso destino!', '', 28153),
(157090, 'ptBR', 'Obrigado, camarada. O vale está contigo.', 'Eu estou tão feliz em ver você, $p. Não me esquecerei disso.', 28153),
(157089, 'ptBR', 'Consigo me virar agora. Tome cuidado.', 'Você é um colírio para os meus olhos!', 28153),
(157088, 'ptBR', 'Achei que tinha chegado minha hora!', 'Agradeço, não vou me esquecer disso.', 28153),
(157087, 'ptBR', 'Ha! Talvez esses javalis não sejam tão ruins, afinal. Será que gostam de mariscos no vapor...', '', 28153),
(157086, 'ptBR', 'Alguém viu javalis desprotegidos do lado de fora do urzal. Se você quiser, pode montar num desses bichos para enfrentar os javatuscos!', '', 28153),
(157085, 'ptBR', 'Vingue-me... Odrogtap...', '', 28153),
(157084, 'ptBR', '', 'Até que enfim... o tormento se encerra...', 28153),
(157083, 'ptBR', '', 'Sim... liberdade...', 28153),
(157082, 'ptBR', '', 'Era... uma armadilha...', 28153),
(157081, 'ptBR', '', 'Heh... a caçadora se tornou a presa...', 28153),
(157080, 'ptBR', '', 'Ele vem para todos nós...', 28153),
(157079, 'ptBR', 'Só um momento, Majestade! Novas informações vieram à luz.', '', 28153),
(157078, 'ptBR', '', 'Isso não era... para ter... acontecido...', 28153),
(157077, 'ptBR', '', 'Tão conveniente quando a presa vem até você sozinha!', 28153),
(157076, 'ptBR', '', 'Olha só o que acabou de cair na minha armadilha!', 28153),
(157075, 'ptBR', '', 'Você não é lá muito grande, mas vou tirar seu couro mesmo assim!', 28153),
(157074, 'ptBR', '', 'Eles me prometeram toda a riqueza da floresta!', 28153),
(157073, 'ptBR', '', 'Sua pele vai dar um bom dinheiro!', 28153),
(157072, 'ptBR', '', 'Outro pelego para tomar!', 28153),
(157071, 'ptBR', 'Você vai... cair...', '', 28153),
(157070, 'ptBR', 'Eu retorno... à terra.', '', 28153),
(157069, 'ptBR', 'O fim... se aproxima...', '', 28153),
(157068, 'ptBR', 'O que você quer?! Buu! Vai embora!', '', 28153),
(157067, 'ptBR', 'Minha alma... está maculada...', '', 28153),
(157066, 'ptBR', 'O véu tombou...', '', 28153),
(157065, 'ptBR', 'Thros consumirá todos nós!', '', 28153),
(157064, 'ptBR', 'Ele fala do além!', '', 28153),
(157063, 'ptBR', 'Tomem a vingança e tomem o tesouro!', '', 28153),
(157062, 'ptBR', 'Issaê, pega uma tocha e mãos à obra, $p!', 'Issaê, pega uma tocha e mãos à obra, $p!', 28153),
(157061, 'ptBR', 'Issaê, vamos arrebentar com eles e mandar todos pro fundo das profundezas!', '', 28153),
(157060, 'ptBR', 'Então a gente vai passar fogo neles, né?', 'Então a gente vai passar fogo neles, né?', 28153),
(157059, 'ptBR', 'Nossa velha tripulação maldita no Porto de Zem\'lan tá mandando uns bandos enormes de saque hoje, e a gente é um dos alvos.', '', 28153),
(157058, 'ptBR', 'Boas-vindas ao mar salgado, marujos!', '', 28153),
(157057, 'ptBR', 'Todos a postos!', 'Todos a postos!', 28153),
(157056, 'ptBR', 'Depois que eu sacar melhor este feitiço, talvez eles me deixem voltar. Que tal... Rohl emoé leinad!', '', 28153),
(157055, 'ptBR', 'Odrogtap, se você puder me entender, queria dizer que lamento ter polimorfado você. Sabe, permanentemente.', '', 28153),
(157054, 'ptBR', 'Será que o seu nome vai funcionar, Odrogtap? Vamos tentar, Ohnid rogé Odrogtap!', '', 28153),
(157053, 'ptBR', 'Não foi justo eles me jubilarem, Odrogtap. Vou lhes mostrar meu maior poder... err... depois que eu lembrar as palavras mágicas.', '', 28153),
(157052, 'ptBR', 'Hmm... não, acho que não é isso.', '', 28153),
(157051, 'ptBR', 'Não me lembro daquele maldito feitiço. Como é que era mesmo, Odrogtap? Leinad alguma coisa... Nos fatsug?', '', 28153),
(157050, 'ptBR', 'Me abriram os olhos!', '', 28153),
(157049, 'ptBR', 'Seu sangue alimentará a floresta!', '', 28153),
(157048, 'ptBR', 'Rrrraaaaagh!', '', 28153),
(157047, 'ptBR', 'Excelente trabalho. Talvez um dia este lugar possa ser usado para adoração novamente.', '', 28153),
(157046, 'ptBR', 'A magia daqui vai conspurcar as águas circunvizinhas se não for controlada. Atrase os sábios das marés o máximo que puder.', '', 28153),
(157045, 'ptBR', 'Espero que almas tão desencaminhadas possam ser levadas pelas ondas para um lugar de paz.', '', 28153),
(157044, 'ptBR', 'A influência sombria da Casa Trovamare foi trazida para este lugar por indivíduos específicos. Acabe com eles antes que tenham a oportunidade de causar ainda mais mal.', '', 28153),
(157043, 'ptBR', 'Bom trabalho! Dá para ver a fumaça daqui! Vamos atacar de novo assim que possível.', '', 28153),
(157042, 'ptBR', 'Espero que você se entenda bem com os grifos! Fale com a Bernadete Robledo. Ela criou um plano para atacar a Horda na Guarnição Presa de Guerra.', '', 28153),
(157041, 'ptBR', '', 'Iaarr?', 28153),
(157040, 'ptBR', 'Você é fraco sem os loas! Acabe com ele!', '', 28153),
(157039, 'ptBR', 'O demônio tá se protegendo atrás do poder de Rezan! Eu vou roubar de volta dele!', '', 28153),
(157038, 'ptBR', 'Lembre-se, continental, o que habita as profundezas deve ser temido. Nada de bom vive na mais negra escuridão.', '', 28153),
(157037, 'ptBR', 'Alguns sábios das marés estão tentando convocar uma força que dizimaria Boralus. Eles têm de ser impedidos!', '', 28153),
(157036, 'ptBR', '', 'Deixe que ela guie, e ela trará você de volta em segurança.', 28153),
(157035, 'ptBR', '', 'Ela está pronta para decolar!', 28153),
(157034, 'ptBR', '', 'Ela é o grifo mais rápido do vale. Se alguém discordar, é mentiroso.', 28153),
(157033, 'ptBR', 'Você é $Uo próximo:a próxima; na fila!', 'Você é $Uo próximo:a próxima; na fila!', 28153),
(157032, 'ptBR', 'Você e o passarinho não são legais.', 'Você e o passarinho não são legais.', 28153),
(157031, 'ptBR', 'Mim quer voar também!', 'Mim quer voar também!', 28153),
(157030, 'ptBR', 'Odeio a Aliança.', 'Odeio a Aliança.', 28153),
(157029, 'ptBR', 'Olha! Passarinho bonitinho.', 'Olha! Passarinho bonitinho.', 28153),
(157028, 'ptBR', '', 'O Módulo de Recriação tá pronto. Agora a gente vai lá e acaba com a peste do G\'huun de uma vez por todas.', 28153),
(157027, 'ptBR', 'O Módulo de Recriação tá pronto. É só ativar que a gente estoura G\'huun feito a bolha de pus que ele é.', '', 28153),
(157026, 'ptBR', 'Eu que foi... esmagada?', 'Eu que foi... esmagada?', 28153),
(157025, 'ptBR', 'Vermezinho! Vou te esmagar que nem um inseto!', 'Vermezinho! Vou te esmagar que nem um inseto!', 28153),
(157024, 'ptBR', 'Me tira daqui!', 'Me tira daqui!', 28153),
(157023, 'ptBR', 'O bezerro escornante muge e corre para a mãe!', 'O bezerro escornante muge e corre para a mãe!', 28153),
(157022, 'ptBR', 'Me levem!', 'Me levem!', 28153),
(157021, 'ptBR', 'Precisa de uma carona?', 'Precisa de uma carona?', 28153),
(157020, 'ptBR', '', 'Everardo lhe deu um bom treinamento. Sei que ele estaria orgulhoso.', 28153),
(157019, 'ptBR', '', 'Obrigada, minha senhora. Eu não a decepcionarei.', 28153),
(157018, 'ptBR', '', 'Eu a nomeio Marechal Claralvor e a promovo a líder da Guarda Capelo.', 28153),
(157017, 'ptBR', '', 'Mas Drustvar necessita mais dos seus serviços em ampla escala.', 28153),
(157016, 'ptBR', '', 'Inquisidora Claralvor, você superou nossas expectativas, demonstrando compaixão, bravura, liderança e astúcia.', 28153),
(157015, 'ptBR', '', 'Todos sentimos a dor da perda, mas a chama da esperança brilha intensa.', 28153),
(157014, 'ptBR', 'Nada pessoal.', 'Nada pessoal.', 28153),
(157013, 'ptBR', 'Nosso inimigo controla o Círculo dos Elementos... por enquanto.', 'Nosso inimigo controla o Círculo dos Elementos... por enquanto.', 28153),
(157012, 'ptBR', 'Vejo estandartes da Horda no Círculo dos Elementos!', 'Vejo estandartes da Horda no Círculo dos Elementos!', 28153),
(157011, 'ptBR', 'A Horda controla o Círculo dos Elementos!', 'A Horda controla o Círculo dos Elementos!', 28153),
(157010, 'ptBR', 'O Círculo dos Elementos carrega os nossos estandartes!', 'O Círculo dos Elementos carrega os nossos estandartes!', 28153),
(157009, 'ptBR', 'Nossas forças controlam o Círculo dos Elementos.', 'Nossas forças controlam o Círculo dos Elementos.', 28153),
(157008, 'ptBR', 'O Círculo dos Elementos continua sob nosso controle.', 'O Círculo dos Elementos continua sob nosso controle.', 28153),
(157007, 'ptBR', 'Novaterra traz os estandartes da Horda... por enquanto.', 'Novaterra traz os estandartes da Horda... por enquanto.', 28153),
(157006, 'ptBR', 'Esses monstros acham que controlam Novaterra? Vamos mostrar a eles...', 'Esses monstros acham que controlam Novaterra? Vamos mostrar a eles...', 28153),
(157005, 'ptBR', 'Esses malditos não vão controlar Novaterra para sempre.', 'Esses malditos não vão controlar Novaterra para sempre.', 28153),
(157004, 'ptBR', 'Nossas forças tomaram o controle de Novaterra.', 'Nossas forças tomaram o controle de Novaterra.', 28153),
(157003, 'ptBR', 'Novaterra está sob nosso controle.', 'Novaterra está sob nosso controle.', 28153),
(157002, 'ptBR', 'Parece que tomamos o controle de Novaterra. Vamos manter as coisas desse jeito.', 'Parece que tomamos o controle de Novaterra. Vamos manter as coisas desse jeito.', 28153),
(157001, 'ptBR', 'O loa dos reis caiu. Temos que ser cuidadosos se quisermos iniciar outra caçada.\n\nRastakhan está gravemente ferido e envelhecendo rápido. Só o poder de Rezan poderia manter o Bwonsamdi afastado. Eu lhe ofereceria meu poder, mas não é da minha alçada desafiar o loa da morte.', '', 28153),
(157000, 'ptBR', 'Que foi, senhora?', '', 28153),
(156999, 'ptBR', '', 'A Senhora das Feras L\'kala espia desconfiada o goblin ao lado dela.', 28153),
(156998, 'ptBR', '', 'Parece que o teu pequenino ficou cansado depois daquela luta toda. Ele vai ficar bem aqui. Vou tomar conta pessoalmente.', 28153),
(156996, 'ptBR', 'O filhote de escornante boceja e fecha os olhos.', 'O filhote de escornante boceja e fecha os olhos.', 28153),
(156995, 'ptBR', 'Hora de partir!', 'Hora de partir!', 28153),
(156994, 'ptBR', 'Parece que alguém arrancou minha alma do meu corpo.', '', 28153),
(156993, 'ptBR', 'Essa foi por pouco! Obrigado pela ajuda!', 'Essa foi por pouco! Obrigada pela ajuda!', 28153),
(156992, 'ptBR', 'Agradeço pela ajuda! Alguma coisa fez minhas chinelas limpa-meleca pararem de funcionar.', 'Agradeço pela ajuda! Alguma coisa fez minhas chinelas limpa-meleca pararem de funcionar.', 28153),
(156991, 'ptBR', 'Muito obrigado! Assim que voltar, eu vou registrar uma reclamação. As barreiras logísticas dessa expedição vão muito além do escopo do nosso briefing.', 'Muito obrigada! Assim que voltar, eu vou registrar uma reclamação. As barreiras logísticas dessa expedição vão muito além do escopo do nosso briefing.', 28153),
(156990, 'ptBR', 'Rapaz, depois dessa, eu vou ficar uma semana no Limpatron!', 'Rapaz, depois dessa, eu vou ficar uma semana no Limpatron!', 28153),
(156989, 'ptBR', 'Aquilo sim era situação pegajosa! Muito obrigado, hein!', 'Aquilo sim era situação pegajosa! Muito obrigada, hein!', 28153),
(156988, 'ptBR', 'Que os mares abençoem este minério e que nunca tentem retomar o que um dia abençoaram.', 'Que os mares abençoem este minério e que nunca tentem retomar o que um dia abençoaram.', 28153),
(156987, 'ptBR', 'Você poderia abençoar esses lingotes de prata procelosa?', 'Você poderia abençoar esses lingotes de prata procelosa?', 28153),
(156986, 'ptBR', 'Ninguém devia ver os Renegados como segunda chance de nada.', '', 28153),
(156985, 'ptBR', 'Não estou gostando do que você está insinuando, Zelão.', '', 28153),
(156984, 'ptBR', 'É isso aí! O poder dos crustáceos!', '', 28153),
(156983, 'ptBR', 'Parece que você vai voltar pra casca de mão abanando. Sacou? Casca? Caranguejo! Ganhei!', '', 28153),
(156982, 'ptBR', 'Isso não vai ficar assim! Você ainda vai se ver com o Capitão Hermes e seu trio de caranguejos durões!', '', 28153),
(156981, 'ptBR', 'Como é que pode?!', '', 28153),
(156980, 'ptBR', 'Finalmente surge um desafiante!', '', 28153),
(156979, 'ptBR', 'Zarpar para o Vale Trovamare.', 'Zarpar para o Vale Trovamare.', 28153),
(156978, 'ptBR', 'Zarpar para o Estreito Tiragarde.', 'Zarpar para o Estreito Tiragarde.', 28153),
(156977, 'ptBR', 'Zarpar para Drustvar.', 'Zarpar para Drustvar.', 28153),
(156976, 'ptBR', 'Quê?', '', 28153),
(156974, 'ptBR', 'Aquele sujeito de camisa vermelha ali disse que \"eu não estou na história oficial\"! É claro que não, eu estou na naval!', '', 28153),
(156973, 'ptBR', 'Você pode falar sobre Kul Tiraz outra vez?', 'Você pode falar sobre Kul Tiraz outra vez?', 28153),
(156972, 'ptBR', 'Nós vamos endireitar tudo.', '', 28153),
(156971, 'ptBR', '', 'Sim, em que posso te ajudar?', 28153),
(156970, 'ptBR', 'Bravíssimo! Você certamente cortou os planos deles pela raiz.', '', 28153),
(156969, 'ptBR', 'Os mares chamam por você como chamam por mim?', '', 28153),
(156968, 'ptBR', 'Eu tenho que saber se minha família está em segurança! <cof>', '', 28153),
(156967, 'ptBR', '', 'Eu disse para não me pr...', 28153),
(156966, 'ptBR', 'Estou ouvindo relatos de que tem uma espécie de planta monstruosa perto do urzal. Nossos ajudantes mecânicos devem tirar isso de letra.', '', 28153),
(156965, 'ptBR', 'Que os mares guiem seu caminho.', '', 28153),
(156964, 'ptBR', 'Como a Casa Proudmore pode lhe servir?', '', 28153),
(156963, 'ptBR', 'Zarpar para Zuldazar.', 'Zarpar para Zuldazar.', 28153),
(156962, 'ptBR', 'Zarpar para Nazmir.', 'Zarpar para Nazmir.', 28153),
(156961, 'ptBR', 'Juntos, somos fortes.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156960, 'ptBR', 'Eu honrarei o legado do meu pai.', '', 28153),
(156959, 'ptBR', 'Passei anos no mar juntando o grupo mais mortal de caranguejos ermitões que já se viu no mundo. Tem coragem de encarar ou tem medo de acabar morrendo na praia?', '', 28153),
(156958, 'ptBR', 'Bom trabalho. Vamos colocar nossos melhores pesquisadores para estudar esses escritos. Muito obrigado.', '', 28153),
(156957, 'ptBR', 'Nossos magos de batalha encontraram vários pergaminhos de magia tortollana entre os caídos. Temos que recolher o máximo antes que a Horda os descubra. Traga todos que encontrar.', '', 28153),
(156956, 'ptBR', 'A Aliança retomou Stromgarde!', 'A Aliança retomou Stromgarde!', 28153),
(156955, 'ptBR', 'Ei, $n! Aqui!', '', 28153),
(156954, 'ptBR', 'Io-ho aí, $p. Fiquei sabendo que tu é chapa do Kiro velho e dos vulperas.\n\nA gente não tem tempo pra bater um papo, mas a palavra do Kiro serve pra mim.\n\nSe topar uma pilhagenzinha em mar aberto, tem lugar pra você na nossa tripulação.\n\nQuando quiser, é só entrar no barco que a gente zarpa.', '', 28153),
(156953, 'ptBR', 'Interessante... Pedirei aos magos que se debrucem imediatamente sobre este pergaminho a fim de estudá-lo. Obrigado!', '', 28153),
(156952, 'ptBR', 'Io-ho, $p! Que bom te ver de novo.\n\nTopa uma pilhagenzinha à beira-mar? Zem\'lan tá mandando as tripulações pros barcos. Com isso, eles são alvos fáceis pra nós... se sua mira for boa.\n\nMas eu já te vi em ação, sei que tu dá um jeito nesses esqueletos caquéticos rapidinho.\n\nQuando quiser ir, é só entrar no barco.', '', 28153),
(156951, 'ptBR', 'Eu vou voltar para o Redenção do Vento. Avise à Grã-almirante quando estiver tudo pronto para retornar a Boralus.', '', 28153),
(156950, 'ptBR', 'Eu passei anos no mar procurando os caranguejos mais durões que se pode enfrentar. Quer ver seus mascotes levarem um caldo?', '', 28153),
(156949, 'ptBR', '$n! Em que posso ajudar?', '', 28153),
(156948, 'ptBR', 'Qué isssho?', 'Qué isssho?', 28153),
(156947, 'ptBR', '$n! Que bom revê-l$Uo:a;! A última vez foi quando servi sob seu comando em Draenor.', '', 28153),
(156946, 'ptBR', 'Os kultirenos vão descobrir o que é medo!', '', 28153),
(156945, 'ptBR', 'O que... é...', 'O que... é...', 28153),
(156944, 'ptBR', 'Eca! Amargo!', 'Eca! Amargo!', 28153),
(156943, 'ptBR', 'Tem gosto de... anzol...', 'Tem gosto de... anzol...', 28153),
(156942, 'ptBR', 'Eu sou o quê? Vraikal?... <hic!>', 'Eu sou o quê? Vraikal?... <hic!>', 28153),
(156941, 'ptBR', 'Eu... odeio... <hic!> cerveja clara...', 'Eu... odeio... <hic!> cerveja clara...', 28153),
(156940, 'ptBR', 'Abra um portal para trazer nossas tropas.', 'Abra um portal para trazer nossas tropas.', 28153),
(156939, 'ptBR', 'Será uma honra servir à Horda como parte dos meus estudos de telemancia sob Oculeth. \n\nTambém será uma honra sair deste lugar assim que minha missão acabar.', '', 28153),
(156938, 'ptBR', 'Meus cães... ladraram... mas não morderam...', 'Meus cães... ladraram... mas não morderam...', 28153),
(156937, 'ptBR', 'Perfeito, a caça veio até nós!', 'Perfeito, a caça veio até nós!', 28153),
(156936, 'ptBR', 'Dê poder ao amuleto... talvez essa seja a única forma de salvá-la!', '', 28153),
(156935, 'ptBR', 'Sentiu isso? Pareceu um... tremor...', '', 28153),
(156934, 'ptBR', '', 'Indivíduo: Azeroth. Arritmia grave detectada.\n\nSinais vitais excedendo parâmetros aceitáveis.\n\nTentando atualizar relatórios de incidentes...\n\nERRO. ERRO. ERRO. ERRO.', 28153),
(156933, 'ptBR', 'Uff! Que forte!', '', 28153),
(156932, 'ptBR', 'Mmmm... isso me lembra... de quando eu trabalhava nas minas... o macete é dar a picaretada no ângulo certo... assim o minério...', '', 28153),
(156931, 'ptBR', '', 'ALERTA: Múltiplas brechas de contenção registradas.\n\nExpurgo das seguintes instalações é recomendado:\n\nUldaman. Uldum. Uldorus. Ulduar. Uldir. Uldaz. Uld... Uld... Uld... Uld...', 28153),
(156930, 'ptBR', 'Urgh... Essa não desceu bem...', '', 28153),
(156929, 'ptBR', 'Pelo meus cálculos, nós perdemos dois vírgula cinco três nove — repetidos, claro — por cento da nossa probabilidade de sucesso. Temos que acelerar os reparos!', 'Pelo meus cálculos, nós perdemos dois vírgula cinco três nove — repetidos, claro — por cento da nossa probabilidade de sucesso. Temos que acelerar os reparos!', 28153),
(156928, 'ptBR', 'Vamos logo! Consertem esses tanques! Estamos nos atrasando!', 'Vamos logo! Consertem esses tanques! Estamos nos atrasando!', 28153),
(156927, 'ptBR', 'Rápido, pessoal! Só temos uma pequena janela de tempo para deixar esses tanques de cerco operacionais antes que a Horda nos descubra aqui.', 'Rápido, pessoal! Só temos uma pequena janela de tempo para deixar esses tanques de cerco operacionais antes que a Horda nos descubra aqui.', 28153),
(156926, 'ptBR', 'Oferecer Café Espumante do Major', 'Oferecer Café Espumante do Major', 28153),
(156925, 'ptBR', 'Oferecer \"Aurora Borealis\"', 'Oferecer \"Aurora Borealis\"', 28153),
(156924, 'ptBR', 'Oferecer Vodca da Raiz Sombria Amarga', 'Oferecer Vodca da Raiz Sombria Amarga', 28153),
(156923, 'ptBR', 'Oferecer Conhaque de Maçã de Brennadam', 'Oferecer Conhaque de Maçã de Brennadam', 28153),
(156922, 'ptBR', 'Oferecer Gim da Ponta do Gancho', 'Oferecer Gim da Ponta do Gancho', 28153),
(156921, 'ptBR', 'Oferecer Hidromel de Mildião', 'Oferecer Hidromel de Mildião', 28153),
(156920, 'ptBR', 'Oferecer Cerveja Clara de Bosquebranco', 'Oferecer Cerveja Clara de Bosquebranco', 28153),
(156919, 'ptBR', 'Oferecer Asassangue dos Dentenegro', 'Oferecer Asassangue dos Dentenegro', 28153),
(156918, 'ptBR', 'Leve-nos a Boralus.', 'Leve-nos a Boralus.', 28153),
(156917, 'ptBR', '', 'Tá, tá! Eu não vou te decepcionar, $n, eu juro!', 28153),
(156916, 'ptBR', '', 'Uh, dá licença? $USeu:Dona; $n? Aqui!', 28153),
(156915, 'ptBR', 'Ah, você quer algo de mim?', '', 28153),
(156914, 'ptBR', 'Onde devemos concentrar nossos esforços?', '', 28153),
(156913, 'ptBR', 'Vamos voltar para Zuldazar.', 'Vamos voltar para Zuldazar.', 28153),
(156912, 'ptBR', '', 'Você precisa de um barco? Enviar uma mensagem?\n\nDE REPENTE AJUDA PRA FURAR ALGUÉM?', 28153),
(156911, 'ptBR', 'Vai embora, cara... Tu não tá vendo... <hic!> que eu tô ocupado?', '', 28153),
(156910, 'ptBR', '', 'Indivíduo: Azeroth.\n\nALERTA: Falha sistêmica catastrófica em progresso.\n\nIntegridade planetária em —\n\ncalculando... calculando... calculando...', 28153),
(156909, 'ptBR', 'Isso não estava nos meus cálculos...', 'Isso não estava nos meus cálculos...', 28153),
(156908, 'ptBR', 'Pelos meus cálculos, sua chance de sucesso é... zero!', 'Pelos meus cálculos, sua chance de sucesso é... zero!', 28153),
(156907, 'ptBR', '', 'O mojo daquele javatusco era forte, mas não era páreo para você.', 28153),
(156906, 'ptBR', '', 'A terra se move de acordo com a vontade de um xamã javatusco. Dá um jeito nesse novo inimigo antes que nosso plano seja prejudicado.', 28153),
(156905, 'ptBR', 'Eu vou dormir mais tranquilo sabendo que tem menos pedregulhos correndo soltos por Trovamare.', '', 28153),
(156904, 'ptBR', 'O pterrorzinho selvagem solta um guinchado de alerta!', 'O pterrorzinho selvagem solta um guinchado de alerta!', 28153),
(156903, 'ptBR', 'Tem um Arauto da Terra javatusco aqui evocando um exército de elementais. Bote o exército para correr, depois bote ele para correr!', '', 28153),
(156902, 'ptBR', 'Não sei como agradecer. Achei que fosse o meu fim.', 'Não sei como agradecer. Achei que fosse o meu fim.', 28153),
(156901, 'ptBR', 'Fico feliz por ainda existirem pessoas boas neste mundo.', 'Fico feliz por ainda existirem pessoas boas neste mundo.', 28153),
(156900, 'ptBR', 'Valeu! Daqui, eu me viro sozinho.', 'Valeu! Daqui, eu me viro sozinha.', 28153),
(156899, 'ptBR', 'Vingue os que não puderam ser salvos.', 'Vingue os que não puderam ser salvos.', 28153),
(156898, 'ptBR', 'Você não faz ideia do que eles fizeram com a gente...', 'Você não faz ideia do que eles fizeram com a gente...', 28153),
(156897, 'ptBR', 'Você salvou a minha vida!', 'Você salvou a minha vida!', 28153),
(156896, 'ptBR', 'Você tem a minha gratidão.', 'Você tem a minha gratidão.', 28153),
(156895, 'ptBR', 'Eu lhe devo uma.', 'Eu lhe devo uma.', 28153),
(156894, 'ptBR', 'Sua bravura é inigualável.', 'Sua bravura é inigualável.', 28153),
(156893, 'ptBR', 'Eu não esquecerei sua gentileza.', 'Eu não esquecerei sua gentileza.', 28153),
(156892, 'ptBR', 'Você chegou bem a tempo!', 'Você chegou bem a tempo!', 28153),
(156891, 'ptBR', 'Sua compaixão não será esquecida.', 'Sua compaixão não será esquecida.', 28153),
(156890, 'ptBR', 'Eu lhe devo a minha vida.', 'Eu lhe devo a minha vida.', 28153),
(156889, 'ptBR', 'É melhor eu voltar para a luta.', 'É melhor eu voltar para a luta.', 28153),
(156888, 'ptBR', 'Mexa tudo até ficar homogêneo!', '', 28153),
(156887, 'ptBR', 'Misture bem!', '', 28153),
(156886, 'ptBR', 'Por fim, esquentar!', '', 28153),
(156885, 'ptBR', 'Para dar mais um gostinho!', '', 28153),
(156884, 'ptBR', 'Um de cada vez!', '', 28153),
(156883, 'ptBR', 'Vale a pena salvar o vale.', '', 28153),
(156882, 'ptBR', 'Você tem suprimentos sobrando?', 'Você tem suprimentos sobrando?', 28153),
(156881, 'ptBR', 'Rezan... ele... ele se foi. Aquela coisa... não é um loa.', '', 28153),
(156880, 'ptBR', 'Argh! A câmara está em ruínas. Não vai ficar de pé muito tempo!', '', 28153),
(156879, 'ptBR', 'Kul Tiraz enfrenta um grave perigo, Magni. Mas suponho que você tenha vindo por... outras razões.', '', 28153),
(156878, 'ptBR', '', 'Onde foi que eu coloquei aquela vara de pescar? Jurava que tava aqui...', 28153),
(156877, 'ptBR', '', 'Tem muito lugar bom pra caçar e pescar por aqui, se tu souber onde procurar.', 28153),
(156876, 'ptBR', '<A madeira velha range seu lamento com o vento que roça na lateral da carruagem.\n\nParece que uma das rodas emperrou.>', '', 28153),
(156875, 'ptBR', '<Dê um empurrão na carroça.>', '<Dê um empurrão na carroça.>', 28153),
(156874, 'ptBR', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tVocê está perto do navio da Horda. Cuidado!', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tVocê está perto do navio da Horda. Cuidado!', 28153),
(156873, 'ptBR', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tVocê está perto do navio da Aliança. Cuidado!', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tVocê está perto do navio da Aliança. Cuidado!', 28153),
(156872, 'ptBR', '', 'A muralha tem que se romper para o mar voltar.', 28153),
(156871, 'ptBR', '$n... Vá mostrar serviço em outro canto. Quando voltar a precisar, eu chamo.', '', 28153),
(156870, 'ptBR', 'Lilian e Rocha, me ajudem a encontrar um desses... sábios das marés.', '', 28153),
(156869, 'ptBR', 'Eu estou farto disso. Toda hora aparece algum problema.', '', 28153),
(156868, 'ptBR', 'E então, $n? O que você trouxe? Passe para cá.', '', 28153),
(156867, 'ptBR', 'Tu tem trabalho pra fazer. A plataforma de teleporte vai te levar de volta pros teus aliados. Boa sorte... pra todos nós.', '', 28153),
(156866, 'ptBR', 'Eu vou continuar procurando um jeito de curar o dano causado a Azeroth. Quando eu precisar de ti, posso te contatar pelo talismã.', '', 28153),
(156865, 'ptBR', 'Guarda esse amuleto perto do teu coração, $n. Ele vai te conduzir pelos tempos sombrios que vêm pela frente.', '', 28153),
(156864, 'ptBR', 'Então só precisamos de alguma coisa que nos leve até ele.', '', 28153),
(156863, 'ptBR', '', 'As muralhas da fortaleza desabarão sob os seus ataques.', 28153),
(156862, 'ptBR', '', 'Ataque as muralhas ao meu sinal, Skoloth.', 28153),
(156861, 'ptBR', '', 'Você receberá a recompensa pelos seus serviços.', 28153),
(156860, 'ptBR', '', 'Amália, conte a Nathanos sobre os sábios das marés.', 28153),
(156859, 'ptBR', '', 'Com ajuda... podem localizar... navios naufragados...', 28153),
(156858, 'ptBR', '', 'Sábios das marés... sacerdotes... do mar...', 28153),
(156857, 'ptBR', '', 'Ah, acho que isso já está resolvido.', 28153),
(156856, 'ptBR', 'Perdido no mar?! Precisamos achar o corpo!', '', 28153),
(156855, 'ptBR', '', 'Marechal M. Valentim... vencedor da Segunda Guerra... perdido no mar...', 28153),
(156854, 'ptBR', 'Quero voltar ao Estreito Tiragarde.', 'Quero voltar ao Estreito Tiragarde.', 28153),
(156853, 'ptBR', 'Eu vou deixar as velas de prontidão enquanto você vai lá resolver tudo.', '', 28153),
(156851, 'ptBR', 'CADÊ O CORPO?!', '', 28153),
(156850, 'ptBR', 'Espera... O que é isso?', '', 28153),
(156849, 'ptBR', 'Valentim... Já faz um bom tempo que você nos escapa.', '', 28153),
(156848, 'ptBR', 'Não podemos deixar Valentim esperando.', '', 28153),
(156847, 'ptBR', 'Sabrezord, ativar... urgh!', '', 28153),
(156846, 'ptBR', 'O quê?! Não estamos prontos!', '', 28153),
(156845, 'ptBR', 'Ninguém resiste ao Sabrezord!', '', 28153),
(156844, 'ptBR', 'Cinco gatinhos se juntam para formar um superfelino!', '', 28153),
(156843, 'ptBR', 'Suas garras não mais protegerão este navio.', '', 28153),
(156842, 'ptBR', 'Sumam daqui, trevas malditas.', '', 28153),
(156841, 'ptBR', 'Que as ondas consumam sua carne iníqua.', '', 28153),
(156840, 'ptBR', '', 'Não deixe que machuquem Biriba!', 28153),
(156839, 'ptBR', '', 'Socooorro!', 28153),
(156838, 'ptBR', 'Zarpar para Vol\'dun.', 'Zarpar para Vol\'dun.', 28153),
(156837, 'ptBR', 'Mesmo morta, essa coisa vai continuar assombrando meus pesadelos.', '', 28153),
(156836, 'ptBR', 'É um... hmm... uma coisa! Mata! Taca fogo!', '', 28153),
(156835, 'ptBR', '|A:Warfront-AllianceWave3:25:23:0:0|a Uma força de ataque da Aliança foi lançada!', '|A:Warfront-AllianceWave3:25:23:0:0|a Uma força de ataque da Aliança foi lançada!', 28153),
(156834, 'ptBR', 'Os sethraks avistaram a carroça de Meerah nas dunas. Ela está sozinha lá e precisa de ajuda para se defender deles, caso decidam atacar.', '', 28153),
(156833, 'ptBR', '', 'O desejo da Dama Sombria é uma ordem.', 28153),
(156832, 'ptBR', '', 'Traga este homem de volta. Ele foi escolhido para se tornar um Renegado.', 28153),
(156831, 'ptBR', 'Lilian. Podemos encontrar outros Sábios das Marés. Você sabe que a família dele não o aceitará.', '', 28153),
(156830, 'ptBR', '', 'Lilian Voss. Por que você me convocou?', 28153),
(156829, 'ptBR', 'Um breve inconveniente. Mostre que isso não fará diferença no plano.', '', 28153),
(156828, 'ptBR', 'Querer é uma palavra forte. É uma coisa que eu... estou disposto a enfrentar, pelo bem da minha família.', '', 28153),
(156827, 'ptBR', '', 'Dolorosamente.', 28153),
(156826, 'ptBR', 'Mas parte de você sobreviveu, certo?', '', 28153),
(156825, 'ptBR', '', 'Vamos esperar que você viva tempo suficiente para nos ajudar a encontrar Valentim.', 28153),
(156824, 'ptBR', 'Vamos!', 'Vamos!', 28153),
(156823, 'ptBR', '', 'É possível requisitar forças extras da Horda imediatamente. Basta falar.', 28153),
(156822, 'ptBR', 'Hunf. É bom mesmo.', '', 28153),
(156821, 'ptBR', '', 'Eu pego ela, Nathanos. Vai sem a gente.', 28153),
(156820, 'ptBR', '', 'Pare!', 28153),
(156819, 'ptBR', '', 'AAHHHH!', 28153),
(156818, 'ptBR', '', 'Não... consigo...', 28153),
(156817, 'ptBR', '', 'Acho que é um bom começo. Vamos ver do que mais você é capaz.', 28153),
(156816, 'ptBR', 'Há forças da Aliança e kultirenas no Enclave dos Sábios. Elas estão à espera de reforços, e neste exato momento estão vulneráveis.', '', 28153),
(156815, 'ptBR', 'Minha família está em segurança?', '', 28153),
(156814, 'ptBR', '', 'Ótimo. Mostre o quanto você pode ser útil para a Horda, e nós veremos quanto tempo permitimos que você continue nesta vida.', 28153),
(156813, 'ptBR', 'Eles estão bem. Ajude-nos, e continuaremos a lhes garantir a segurança.', '', 28153),
(156812, 'ptBR', '<cof> Eu... Eu vou fazer o que puder, Senhorita Voss. Você quer saber onde está alguém ou alguma coisa, não é? Vejamos o que posso fazer sem o meu livro...', '', 28153),
(156811, 'ptBR', '', 'Não teste a minha paciência, ou farei você desejar que a sua doença já o tivesse matado. Eu preciso ver do que sua magia é capaz antes de prosseguirmos.', 28153),
(156810, 'ptBR', 'Senhorita Voss. Você continuou com alguma doença, com alguma moléstia que tinha em vida quando retornou?', '', 28153),
(156809, 'ptBR', '', 'Lilian Voss. Eu faço as perguntas. Você pode encontrar pessoas? Objetos?', 28153),
(156808, 'ptBR', 'Uma Renegada. Talvez seja um <cof> sinal. Diga-me, senhorita...?', '', 28153),
(156807, 'ptBR', '', '$n tem razão, em parte. Você não vai se ferir se nos ajudar, de preferência antes de morrer.', 28153),
(156806, 'ptBR', 'Que a Dama Sombria zele por você.', '', 28153),
(156805, 'ptBR', 'Solicito reforços.', 'Solicito reforços.', 28153),
(156804, 'ptBR', 'Precisa de reforços? Faça a solicitação que eu cuido do transporte de Ventobravo.', '', 28153),
(156803, 'ptBR', 'Não temos tempo a perder. O que é preciso?', '', 28153),
(156802, 'ptBR', 'Você é duro de matar... bem mais do que aquele adversário.', '', 28153),
(156801, 'ptBR', 'Estamos trabalhando de improviso aqui. Elimine o perigo e trate de não morrer.', '', 28153),
(156799, 'ptBR', '%s masca o alimento fresco.', '', 28153),
(156798, 'ptBR', '%s mastiga com vontade as folhas verdes.', '', 28153),
(156797, 'ptBR', '%s enfia o focinho na comida.', '', 28153),
(156796, 'ptBR', 'Eu vou achatar tua cabeça!', 'Eu vou achatar tua cabeça!', 28153),
(156795, 'ptBR', 'Quem quer morrer agora?!', 'Quem quer morrer agora?!', 28153),
(156794, 'ptBR', 'Vamos!', 'Vamos!', 28153),
(156793, 'ptBR', '[CENA] - Jaina chegou! As forças dela conseguiram derrubar a muralha da Bastilha de Lordaeron! E só para deixar claro: foi SI-NIS-TRO.', '[CENA] - Jaina chegou! As forças dela conseguiram derrubar a muralha da Bastilha de Lordaeron! E só para deixar claro: foi SI-NIS-TRO.', 28153),
(156792, 'ptBR', '[CENA] - Sylvana está esperando na sala do trono quando Anduin chega. Ele lhe dá a chance de se render. Em vez disso, ela explode a cidade toda. Mas também, né? O que ele estava esperando?', '[CENA] - Sylvana está esperando na sala do trono quando Anduin chega. Ele lhe dá a chance de se render. Em vez disso, ela explode a cidade toda. Mas também, né? O que ele estava esperando?', 28153),
(156791, 'ptBR', '', 'Se eu conseguir trazer Kul Tiraz de volta para a Aliança...', 28153),
(156790, 'ptBR', '', 'Meu povo lidera a mais poderosa esquadra de toda Azeroth.', 28153),
(156789, 'ptBR', '', 'É um feitiço simples, se a pessoa colaborar.', 28153),
(156788, 'ptBR', '', 'Tome. Beba isso.', 28153),
(156787, 'ptBR', '', 'Certo, Amália. Só um instantinho...', 28153),
(156786, 'ptBR', 'Estou aqui para pedir sua ajuda, não para matar você.', 'Estou aqui para pedir sua ajuda, não para matar você.', 28153),
(156785, 'ptBR', '<cof> A Horda. Achei que aqui eu ia morrer em paz. \n\nE então? O que você está esperando?', '', 28153),
(156784, 'ptBR', '', 'Ei, $n... perto do retalhador.', 28153),
(156783, 'ptBR', 'Para conseguir a ajuda deste Sábio das Marés, vamos ter que nos apressar.', '', 28153),
(156782, 'ptBR', '', 'Nada que você pudesse fazer seria pior que a doença... ele seguiu para o leste, para morrer em paz, longe das crianças. Por favor, nos deixe quietos.', 28153),
(156781, 'ptBR', 'Eu só quero saber onde está seu marido. Nenhum mal recairá sobre sua família.', '', 28153),
(156780, 'ptBR', '', 'A Horda... vocês vieram tomar ainda mais de mim? Meu marido está morrendo, eu não tenho dinheiro nenhum... deixem as crianças em paz, por favor.', 28153),
(156779, 'ptBR', 'Não há honra nisso. Podemos só perguntar. Não temos inimizade com uma mãe aos prantos.', '', 28153),
(156778, 'ptBR', 'Melhor você se afastar agora!', '', 28153),
(156777, 'ptBR', 'Vai sobrar pipoco.', '', 28153),
(156776, 'ptBR', 'Eu trago a tempestade de areia!', '', 28153),
(156775, 'ptBR', 'Você marca o alvo...', '', 28153),
(156774, 'ptBR', 'Eu amo meu trabalho.', '', 28153),
(156773, 'ptBR', 'Ha! Parece que aquele troço abocanhou mais do que conseguia engolir!', '', 28153),
(156772, 'ptBR', 'Tá saindo o monstro.', '', 28153),
(156771, 'ptBR', 'Não vão nem ver o que bateu neles.', '', 28153),
(156770, 'ptBR', 'Alguém pediu um acertador?', '', 28153),
(156769, 'ptBR', 'Acho que você vai gostar disso!', '', 28153),
(156768, 'ptBR', 'AR-8 chegando agora.', '', 28153),
(156767, 'ptBR', 'Espera aí! Estou fazendo e acontecendo.', '', 28153),
(156766, 'ptBR', 'Positivo e operante.', '', 28153),
(156765, 'ptBR', '', 'Hnngh...', 28153),
(156764, 'ptBR', '', 'Quanto mais rápido você coletar as plantas, mais rápido poderei ajudar Amália a ser útil.', 28153),
(156763, 'ptBR', 'Ouvi umas histórias de que tem vermes gigantes se empanturrando de podridão e fazendo uma algazarra na superfície. Se aparecer um, a gente dá uma tunda nele!', '', 28153),
(156762, 'ptBR', 'Você salvou os meninos. Aposto que agora eles querem fugir para ficar que nem você!', '', 28153),
(156761, 'ptBR', 'Um bando de moleques da Água Morta fugiram, crentes que iam virar piratas, e acabaram virando prisioneiros dos Maré-férrea. Você tem que salvar esses meninos!', '', 28153),
(156760, 'ptBR', '', 'Psiu, $n... aqui!', 28153),
(156759, 'ptBR', '', 'Uma monstruosidade a menos pra aterrorizar meu povo na superfície. Os loas tão contentes com você.', 28153),
(156758, 'ptBR', '', 'Ouvi dizer que tem vermes devorando a podridão e causando um caos na superfície. Temos que matar todos que aparecerem!', 28153),
(156757, 'ptBR', 'Disseram se ia ter docinho?', 'Eu sou pirata agora?', 28153),
(156756, 'ptBR', 'Olha, chefia, eu sei que você está patrocinando a expedição, mas o Gallywix vai querer que a Dama Sombria receba a cota dela.', '', 28153),
(156755, 'ptBR', 'Preciso de uma carona até o Cemitério Tumbapétrea.', 'Preciso de uma carona até o Cemitério Tumbapétrea.', 28153),
(156754, 'ptBR', '', 'Eu tenho os foguetes mais seguros de toda Kul Tiraz.$b$bNão liga pro meu sobrenome.', 28153),
(156753, 'ptBR', 'Recuar! É preciso viver para lutar outro dia.', '', 28153),
(156752, 'ptBR', 'Zandalari, recuar e reagrupar. Eles podem viver… por hoje.', '', 28153),
(156751, 'ptBR', 'Destruam os invasores!', '', 28153),
(156750, 'ptBR', 'Criatura fraca!', '', 28153),
(156749, 'ptBR', 'Sua morte está próxima!', '', 28153),
(156748, 'ptBR', 'Eu sou o terrível pirata Beuford! Não haverá sobreviventes!', 'Acho que eu vi meu gatinho!', 28153),
(156747, 'ptBR', 'Adentre a tempestade para podermos acabar com isso.', '', 28153),
(156746, 'ptBR', 'Você não é pirata!', 'Disseram que iam me dar um chapéu!', 28153),
(156745, 'ptBR', 'Argh! Me dá um caneco de rum!', 'Me leva na cabine do penico!', 28153),
(156744, 'ptBR', '', 'Ótimo, suas mãos continuam limpas.', 28153),
(156743, 'ptBR', 'Quero voltar a Zuldazar.', 'Quero voltar a Zuldazar.', 28153),
(156742, 'ptBR', 'Vou deixar as velas içadas pra facilitar o pinote. Vai pegar a Azerita!', '', 28153),
(156741, 'ptBR', '', '$n, eu cuido do corpo. Vá encontrar Nathanos. Diga a ele que está tudo indo de acordo com o plano.', 28153),
(156740, 'ptBR', 'Eu não vou me envolver na transformação desse homem em Renegado. Cuide você disso.', 'Eu não vou me envolver na transformação desse homem em Renegado. Cuide você disso.', 28153),
(156739, 'ptBR', '', 'Você vai aprender a cooperar... e eu vou ajudar.', 28153),
(156738, 'ptBR', 'Não pedi pra ninguém me salvar!', 'Eu sou pirata. Você não manda em mim.', 28153),
(156737, 'ptBR', '', 'Agora você é um de nós. Eles não vão aceitar você.', 28153),
(156736, 'ptBR', 'Lilian, você mata Zelão.', 'Lilian, você mata Zelão.', 28153),
(156735, 'ptBR', '', 'Rocha, eu entendo o que você tem passado. Você não pode deixar que essa mudança lhe afete a cabeça, como eu deixei.', 28153),
(156734, 'ptBR', 'Não é justo! Eu ia ser pirata.', 'Greta me vendeu para os piratas!', 28153),
(156733, 'ptBR', 'Lilian, faça o que for preciso com o Zelão.', 'Lilian, faça o que for preciso com o Zelão.', 28153),
(156732, 'ptBR', '', 'Vamos ver, talvez possa ser diferente... só dessa vez.', 28153),
(156731, 'ptBR', '', 'Terrível. Os poucos que não se afastam, nunca mais tratam você do mesmo jeito. Ao se olhar no espelho, tudo que você vê é um monstro. Você não se reconhece.', 28153),
(156730, 'ptBR', 'Por favor... eu tenho que... cuidar... da minha família... a qualquer custo.', '', 28153),
(156729, 'ptBR', '', 'Você será rejeitado caso se torne um de nós. Ao se olhar num espelho, verá apenas um monstro.', 28153),
(156728, 'ptBR', 'Senhorita Voss, <cof> por favor... me traga de volta... tenho que ajudar minha família... eu faço qualquer coisa... qualquer coisa...', '', 28153),
(156727, 'ptBR', '', 'O quê? Sua família vai achar que você é um monstro, não seja ridículo!', 28153),
(156726, 'ptBR', '', 'Tudo bem. De toda sorte, tem uma coisa que eu quero saber.', 28153),
(156725, 'ptBR', '<puf, puf> Me... desculpe. Não.. consigo... Não sobrou mais nada... em mim...', '', 28153),
(156724, 'ptBR', '', 'Zelão! Maldito seja, precisamos de você vivo!', 28153),
(156723, 'ptBR', 'Sim! Finalmente eu terei a vida eterna! Eu estou pronto!', '', 28153),
(156722, 'ptBR', '', 'Certo, Zelão. Você compreende, realmente compreende, o que está prestes a acontecer?', 28153),
(156721, 'ptBR', 'Excelente trabalho. Você mostrou a eles como é que se faz no vale.', '', 28153),
(156720, 'ptBR', 'Os batedores informaram que tem um novo perigo na região. Acabe com ele antes que o problema aumente.', '', 28153),
(156719, 'ptBR', 'Tenha cuidado, Jaina. Que a Luz esteja com você.', '', 28153),
(156718, 'ptBR', '', 'Se não for para voltar com a frota... eu nem voltarei.', 28153),
(156717, 'ptBR', 'Vai ser difícil... e perigoso.', '', 28153),
(156716, 'ptBR', 'Acredito que sim... e acredito que você consiga.', '', 28153),
(156715, 'ptBR', '', 'E lidar com isso é a única esperança que temos de trazê-los de volta.', 28153),
(156714, 'ptBR', 'Jaina, foi por sua causa que eles deixaram a Aliança.', '', 28153),
(156713, 'ptBR', '', 'Então teremos que fazer nossos próprios aliados.', 28153),
(156710, 'ptBR', '', 'Mostre-nos... mostre o que aconteceu...', 28153),
(156709, 'ptBR', 'Se a Horda se aliar aos Zandalari, nossas forças não serão capazes de detê-los.', '', 28153),
(156708, 'ptBR', 'Impossível! É mais um truque da Sylvana. Tem que ser...', '', 28153),
(156707, 'ptBR', 'E uma imensa frota Zandalari.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156706, 'ptBR', 'Os sobreviventes dizem que se depararam com uma magia estranha, aterradora.', '', 28153),
(156705, 'ptBR', 'Só um retornou.', '', 28153),
(156704, 'ptBR', 'Eu sei. E quanto aos oito navios de guerra que mandamos no encalço deles?', '', 28153),
(156703, 'ptBR', 'Uma princesa. E um profeta.', '', 28153),
(156702, 'ptBR', 'Não muito tempo atrás, agentes da Horda entraram no Cárcere e libertaram dois prisioneiros Zandalari.', '', 28153),
(156701, 'ptBR', 'Jaina, será que você pode nos ajudar a ver a cena que este sobrevivente testemunhou?', '', 28153),
(156700, 'ptBR', 'Muitos viajantes foram mortos na região. Eu preciso que você elimine quem está por trás desses ataques.', '', 28153),
(156699, 'ptBR', 'Todos estão aqui. Que notícias você traz, Mestre Espião?', '', 28153),
(156698, 'ptBR', 'Que trabalho estupendo! Eu sabia que podíamos contar com você.', '', 28153),
(156697, 'ptBR', 'Eu também preciso duma aeronave. Vou dar a ela o nome do meu filho!', '', 28153),
(156696, 'ptBR', 'Eu roubei esse aqui sozinho! Chamei ele de Sorte de Mala... Em homenagem à minha filha!', '', 28153),
(156695, 'ptBR', 'Quando falaram que a gente ia lidar com piratas, na hora eu disse \"então eu quero um navio pirata\"!', '', 28153),
(156694, 'ptBR', 'As nagas estão tramando alguma!', '', 28153),
(156693, 'ptBR', 'Sim... eternidade!', '', 28153),
(156692, 'ptBR', 'Quando tiver tudo pronto, é só usar a corda. Eu quero te mostrar meu barco!', '', 28153),
(156691, 'ptBR', '', 'O próximo que reclamar morre!', 28153),
(156690, 'ptBR', '', 'Trabalhem mais rápido, seus vira-latas inúteis!', 28153),
(156689, 'ptBR', '', 'Menos conversa, mais trabalho! Vamos tratar de extrair essa azerita!', 28153),
(156688, 'ptBR', '', 'E isso lá é trabalho? Sorte de vocês que a gente não tá pagando, seus cães!', 28153),
(156687, 'ptBR', '', 'De volta ao trabalho, cães! Quero ver esforço!', 28153),
(156686, 'ptBR', 'Por favor, mate-me! Garanta-me a eternidade como Renegado!', '', 28153),
(156685, 'ptBR', 'Eu sei que você andou roubando da empresa. E eu vim aqui para garantir que isso não vai se repetir...', 'Eu sei que você andou roubando da empresa. E eu vim aqui para garantir que isso não vai se repetir...', 28153),
(156684, 'ptBR', 'Tá querendo levar uma surra? Vai cuidar da tua vida!', 'Tá querendo levar uma surra? Vai cuidar da tua vida!', 28153),
(156683, 'ptBR', 'Circulando, tripulante. Não tem nada pra ver aqui...', 'Circulando, tripulante. Não tem nada pra ver aqui...', 28153),
(156682, 'ptBR', 'Tá olhando o quê, tripulante?', 'Tá olhando o quê, tripulante?', 28153),
(156681, 'ptBR', '<cof> Senhorita Voss, como foi que virou Renegada?', '', 28153),
(156680, 'ptBR', 'Os ladrões da Horda estão roubando azerita da Companhia Comercial Grimpagris. Esmague os inimigos e tome os recursos para a 7ª Legião!', '', 28153),
(156679, 'ptBR', 'Eu só roubei para preencher o vazio de nunca ter conhecido o amor!', 'Eu só roubei para preencher o vazio de nunca ter conhecido o amor!', 28153),
(156678, 'ptBR', 'Eu só fiz isso porque não tive educação em casa!', 'Eu só fiz isso porque não tive educação em casa!', 28153),
(156677, 'ptBR', 'Eu não faço nunca mais! Juro!', 'Eu não faço nunca mais! Juro!', 28153),
(156676, 'ptBR', 'Aquele cão sarnento do Harrington chamou os capangas!', 'Aquele cão sarnento do Harrington chamou os capangas!', 28153),
(156675, 'ptBR', 'Eu não roubo mais! Já parei!', 'Eu não roubo mais! Já parei!', 28153),
(156674, 'ptBR', 'Não me mate, por favor! Eu juro que não roubo mais!', 'Não me mate, por favor! Eu juro que não roubo mais!', 28153),
(156673, 'ptBR', 'Nossos soldados estão sendo mantidos reféns por exilados de Zuldazar. Não negociamos com aliados da Horda. Mostre a eles a força da Aliança!', '', 28153),
(156672, 'ptBR', 'Você deu cabo deles com facilidade. Muito bem.', '', 28153),
(156671, 'ptBR', 'Os espiões localizaram um pequeno acampamento de tropas da Horda nas dunas. Ataque rápido e dizime as forças inimigas!', '', 28153),
(156670, 'ptBR', 'Foi um prazer fazer negócios com você. Se um dia quiser um trampo de pirata, pode entrar na minha tripulação!', '', 28153),
(156669, 'ptBR', 'Eu sou homem de palavra, $c. O cofre do capitão é todo seu!', '', 28153),
(156668, 'ptBR', 'Encontro você nos aposentos do capitão depois que Hartford estiver morto. Não se preocupe com o cofre. Tudo que estiver dentro será seu!', '', 28153),
(156667, 'ptBR', '', 'Não terminamos ainda. Você tem boas informações, mas precisamos ver quanto poder você tem.', 28153),
(156666, 'ptBR', 'Por favor! Certamente é o bastante, seu campeão semeou caos e destruição no Enclave dos Sábios. Torne-me um Renegado!', '', 28153),
(156665, 'ptBR', '', 'A gente... errou... em ajudar a Aliança?', 28153),
(156664, 'ptBR', '', 'A Horda jamais vencerá a determinação de Kul Tiraz!', 28153),
(156663, 'ptBR', 'O livro... jogue o livro... no mar...', '', 28153),
(156662, 'ptBR', 'Você não vai levar esse livro. Ele é perigoso demais!', '', 28153),
(156661, 'ptBR', '', 'Você estará morto antes da próxima tosse ridícula, Zelão. Quer me testar?', 28153),
(156660, 'ptBR', '<puf, puf> Você não tem medo que eu ataque? Tente fugir?', '', 28153),
(156659, 'ptBR', 'A Capitã Rocha enlouqueceu quando foi tornada? Sei bem o que aconteceu com ela.', '', 28153),
(156658, 'ptBR', '', 'Tornar-se Renegado é um processo imprevisível. Seu corpo e mente com certeza vão mudar, mas, em que medida, é impossível saber... Como você vai lidar com a transformação também é um mistério.', 28153),
(156657, 'ptBR', 'Não, mas você pode me responder uma pergunta? Quando você se torna um Renegado, se livra de todas as doenças?', '', 28153),
(156656, 'ptBR', 'Com você ao meu lado, vou ficar mais perto de sair desse deserto desgraçado!', '', 28153),
(156655, 'ptBR', 'Vá me procurar no Porto Rubrapedra quando terminar o serviço.', '', 28153),
(156654, 'ptBR', 'É, a ideia foi... bem criativa.', '', 28153),
(156653, 'ptBR', 'Nossos aliados não têm como cumprir a missão com a Horda zanzando pelas ruínas. Os Ferro Negro têm uma ideia de como resolver a situação.', '', 28153),
(156652, 'ptBR', 'Faltam 2 minutos para começar a batalha por Stromgarde.', '', 28153),
(156651, 'ptBR', 'Acho que perdi meu chapéu fabuloso.', 'Acho que perdi meu chapéu fabuloso.', 28153),
(156650, 'ptBR', 'Vamos para o Vale Trovamare.', 'Vamos para o Vale Trovamare.', 28153),
(156649, 'ptBR', 'Muito bom. Vamos ver se isso acaba sendo útil.', '', 28153),
(156648, 'ptBR', 'Essas ruínas parecem ser um templo que afundou no mar. A presença de nagas é preocupante. Vai lá dar uma olhada e boa sorte.', '', 28153),
(156647, 'ptBR', 'Estou pronto para negociar, Ty\'jin.', 'Estou pronta para negociar, Ty\'jin.', 28153),
(156646, 'ptBR', 'Avisa quando tiver tudo pronto pra ir, chefia.', '', 28153),
(156645, 'ptBR', 'Bom trabalho. Melhor prevenir agora do que ter que remediar depois.', '', 28153),
(156644, 'ptBR', 'Nossos batedores encontraram uma infestação de murlocs. Temos que impedir que eles se multipliquem e ataquem nossos flancos.', '', 28153),
(156643, 'ptBR', '', 'Você se saiu bem! Os loas sorriem hoje.', 28153),
(156642, 'ptBR', '', 'A Empreendimentos S.A. tá devastando as terras de um aliado muito importante. Os loas não iam gostar disso. Acaba com a graça deles e ajuda a limpar essa bagunça.', 28153),
(156641, 'ptBR', '', 'Bom trabalho! Os tortollanos vão lembrar quem salvou eles daquele destino.', 28153),
(156640, 'ptBR', '', 'Me disseram que as nagas escravizam tortollanos na costa pra algum fim obscuro. Não deixa isso acontecer! Mata as nagas e liberta os tortollanos.', 28153),
(156639, 'ptBR', 'Os sábios das marés há tempos guiam as almas perdidas no mar... mas não assim.', '', 28153),
(156637, 'ptBR', 'Bom trabalho. Vamos torcer para os tortollanos se lembrarem disso quando precisarmos deles!', '', 28153),
(156636, 'ptBR', 'Estou pronto para velejar a Lordaeron.', 'Estou pronta para velejar a Lordaeron.', 28153),
(156635, 'ptBR', 'A Empreendimentos S.A. está criando uma balbúrdia na costa. Vamos ganhar a simpatia dos tortollanos fazendo uma limpeza aqui.', '', 28153),
(156634, 'ptBR', '', 'Férias escolares... para sempre...', 28153),
(156633, 'ptBR', '', 'Eu vou lhe ensinar uma lição!', 28153),
(156632, 'ptBR', 'Excelente trabalho. Não gosto nem de pensar no que as nagas tinham em mente para esses tortollanos.', '', 28153),
(156631, 'ptBR', 'Os batedores informaram que nagas estão capturando tortollanos nesta área. Seja o que for que estão planejando, temos que detê-las agora.', '', 28153),
(156630, 'ptBR', '', 'Você luta que nem caipira!', 28153),
(156629, 'ptBR', 'Bom trabalho, $p! Estamos um passo mais próximos da vitória!', '', 28153),
(156628, 'ptBR', 'Isso vai reduzir o número de pragas... por enquanto. Bom trabalho.', '', 28153),
(156627, 'ptBR', 'Eu sei que as víboras emplumadas são conhecidas pelas infestações, mas elas já estão passando dos limites! Destrua os ovos imediatamente.', '', 28153),
(156626, 'ptBR', 'As glândulas estão ótimas. Os soldados feridos ficarão gratos pela ajuda, camarada.', '', 28153),
(156625, 'ptBR', 'Precisamos aproveitar os recursos da região. Arranje umas glândulas salivares de pterrordax selvagem. Vamos usar suas propriedades medicinais para tratar dos feridos.', '', 28153),
(156624, 'ptBR', 'Com um bucho desses, dá para comer até pedra! Estão perfeitos. Obrigado, camarada.', '', 28153),
(156623, 'ptBR', 'Nós precisamos de suprimentos não perecíveis. Dizem que mucosa de estômago de ravassauro aguenta tudo. Arranje um punhado para nós, fazendo favor.', '', 28153),
(156622, 'ptBR', 'Arghh... que o baú de Neptulon... te carregue...', '', 28153),
(156621, 'ptBR', 'O que é isso... motim?! Você vai ver só, criatura imunda!', '', 28153),
(156620, 'ptBR', 'Pela Horda!', 'Pela Horda!', 28153),
(156619, 'ptBR', '', 'Minha pesquisa está completa, por enquanto. Agradeço a sua ajuda.', 28153),
(156618, 'ptBR', '', 'Isso vai ensinar a Horda a se meter! Esta magia não pode jamais cair nas mãos deles...', 28153),
(156617, 'ptBR', '', 'Sua ajuda foi muito bem-vinda. A barreira é tão resistente...', 28153),
(156616, 'ptBR', 'A imortalidade está ao meu alcance! Mal posso esperar para me tornar um Renegado! Imagina as possibilidades! \n\nQuando você tiver um tempo, diga-me como é. A morte-viva, a eternidade, ter o mundo nas mãos!', '', 28153),
(156615, 'ptBR', 'Eu me recuso a aceitar que minha vida acabe aqui por causa de uma... doença. Eu tenho que continuar vivendo para proteger minha família.', '', 28153),
(156614, 'ptBR', 'Não perturbe os mortos, $r.', '', 28153),
(156613, 'ptBR', '', 'Preciso de ajuda aqui!', 28153),
(156612, 'ptBR', 'Quem não está avançando, está ficando para trás. É o que eu sempre digo!', '', 28153),
(156611, 'ptBR', '', 'Preciso fazer alguns testes e juntar dados. Fique de olho em qualquer um que possa interferir.', 28153),
(156610, 'ptBR', '', 'Talvez seja possível controlar essa magia, ou até replicá-la.', 28153),
(156609, 'ptBR', '', 'A magia usada aqui é fascinante! Nunca vi nada parecido.', 28153),
(156608, 'ptBR', '', 'Isso ainda não acabou!', 28153),
(156607, 'ptBR', 'Mas você tem tempo a perder?', '', 28153),
(156606, 'ptBR', 'Preciso de outro disfarce.', 'Preciso de outro disfarce.', 28153),
(156605, 'ptBR', 'A Horda está aqui. Fujam! Não existe nenhum lugar seguro?!', 'A Horda está aqui. Fujam! Não existe nenhum lugar seguro?!', 28153),
(156604, 'ptBR', 'Ótimo, mais problemas com a Horda agora que a Aliança está aqui!', 'Ótimo, mais problemas com a Horda agora que a Aliança está aqui!', 28153),
(156603, 'ptBR', 'Se a Horda já está aqui, eu não vou arriscar minha vida!', 'Se a Horda já está aqui, eu não vou arriscar minha vida!', 28153),
(156602, 'ptBR', 'Corram! É isso que ganhamos por ajudar a Aliança!', 'Corram! É isso que ganhamos por ajudar a Aliança!', 28153),
(156601, 'ptBR', 'Achei que estávamos a salvo da Horda!', 'Achei que estávamos a salvo da Horda!', 28153),
(156600, 'ptBR', 'Como a Horda veio parar aqui?!', 'Como a Horda veio parar aqui?!', 28153),
(156599, 'ptBR', 'A Horda! Corram!', 'A Horda! Corram!', 28153),
(156598, 'ptBR', 'Isso aqui é um texto de teste que terá um texto bem bonito no futuro.', '', 28153),
(156597, 'ptBR', '', 'Adeus, Nathanos.', 28153),
(156596, 'ptBR', '', '<Sylvana vai indo embora, então hesita e olha por sobre os ombros.>', 28153),
(156595, 'ptBR', 'Não falharemos. Boa viagem, minha senhora.', '', 28153),
(156594, 'ptBR', '', 'Cuide para que a missão seja cumprida, e não deixe de me manter informada.', 28153),
(156593, 'ptBR', 'Será feito, Chefe Guerreira.', '', 28153),
(156592, 'ptBR', '', 'Ótimo. Nosso campeão e você determinarão onde nos estabeleceremos primeiro.', 28153),
(156591, 'ptBR', 'Sim, minha senhora. O Lamento da Banshee está pronto para partir quando a ordem for dada.', '', 28153),
(156590, 'ptBR', '', 'Está tudo correndo bem?', 28153),
(156589, 'ptBR', '<Nathanos faz uma reverência profunda.>', '', 28153),
(156588, 'ptBR', 'Minha rainha.', '', 28153),
(156587, 'ptBR', '$n, sua presença é requisitada no Lamento da Banshee. A Dama Sombria ordena que iniciemos nossa campanha na costa de Kul Tiraz.', '', 28153),
(156586, 'ptBR', '', 'Venha comigo.', 28153),
(156585, 'ptBR', '', '$n.', 28153),
(156584, 'ptBR', 'A líder do grupo é Garona Meiorken. Ela orquestrará as missões com a sua ajuda.', '', 28153),
(156583, 'ptBR', 'Reunimos uma tropa de elite para executar as ordens da Dama Sombria.', '', 28153),
(156582, 'ptBR', 'Bom trabalho, $p.', '', 28153),
(156581, 'ptBR', 'A Horda foi alertada da nossa presença aqui e está mandando tropas para atacar. Ajude nossos exploradores a cumprir a missão deles!', '', 28153),
(156580, 'ptBR', '', 'Bom, acho que consigo dar um jeito, Zelão, mas só se você provar estar à altura da Horda.', 28153),
(156579, 'ptBR', 'Meu nome é Tomás Zelão, eu sou um sábio das marés, um sábio das marés ILUMINADO! Eu faço o que você pedir, até ajudo a atacar a Aliança, mas me ajude a virar um Renegado!', '', 28153),
(156578, 'ptBR', 'A carroça chegou ao destino em segurança. Sua recompensa está à espera na bastilha.', '', 28153),
(156577, 'ptBR', '', 'Quem é você? Por que você acha que merece tamanha dádiva?', 28153),
(156576, 'ptBR', 'Finalmente, uma Renegada! Por favor, mate-me, torne-me um Renegado... conceda-me a dádiva da imortalidade!', '', 28153),
(156575, 'ptBR', '', 'Bem, eu posso ameaçar a mulher, para ver se ela nos dá alguns detalhes...', 28153),
(156574, 'ptBR', 'O Caos, os elementos <cof>... nada pode deter essa doença maldita? Por que tinha que acabar assim?', '', 28153),
(156573, 'ptBR', 'Hrm, o Sábio das Marés estava aqui. Eu vi ele protegendo e servindo a família.', '', 28153),
(156572, 'ptBR', 'Alguma ideia de onde podemos achar um Sábio das Marés?', 'Alguma ideia de onde podemos achar um Sábio das Marés?', 28153),
(156571, 'ptBR', 'Avistamos uma movimentação de suprimentos da Horda pelo campo de batalha. Balinda está atrás de voluntários para ajudar a... repor nossas reservas.', '', 28153),
(156570, 'ptBR', 'Recebemos informações de que batedores da Horda estão rondando a mina. Fale com Guerda na oficina para saber mais detalhes.', '', 28153),
(156569, 'ptBR', 'Guerda precisa de ajuda na oficina. Nossos suprimentos estão acabando.', '', 28153),
(156568, 'ptBR', 'Aí tem dinheiro. Mais terras para se explorar... $B$BQue bela época para se estar vivo!', '', 28153),
(156567, 'ptBR', 'Na verdade não.', '', 28153),
(156566, 'ptBR', 'Misha, fique aqui. O resto de nós vai atrás do Sábio das Marés, aí a Lilian faz... seja lá o que for que você está planejando.', '', 28153),
(156565, 'ptBR', '', 'Não quer saber os detalhes, Rexxar?', 28153),
(156564, 'ptBR', 'Estou pronto para ir à Cidade Baixa.', 'Estou pronta para ir à Cidade Baixa.', 28153),
(156563, 'ptBR', '', 'Plangemortis já era. Quando quiser, levarei você até o Distrito dos Magos para falar com o Lorde Supremo.', 28153),
(156562, 'ptBR', '', 'Campeões, a hora se aproxima. A Aliança luta para se apoderar da nossa valiosa Bastilha de Lordaeron, mas sucumbirá sob nossas lâminas.', 28153),
(156560, 'ptBR', 'Campeões da Aliança, chegou a hora de tomar o que é nosso de direito! A última investida para retomar a Bastilha de Lordaeron começa ao amanhecer. A Horda e sua Chefe Guerreira vão responder pelos crimes que cometeram!', '', 28153),
(156559, 'ptBR', '', 'Seu amigo Filho da Noite está no Salão dos Antigos Caminhos. Dê uma volta para conhecer o lugar e depois venha falar comigo.', 28153),
(156558, 'ptBR', '', 'Meu pai guarda um monte de tesouros aqui na câmara real.', 28153),
(156557, 'ptBR', '', 'Dizem que o Grande Selo é uma das únicas coisas no mundo mais antigas do que o Império Zandalari.', 28153),
(156556, 'ptBR', '', 'Venha comigo. Vou lhe mostrar as redondezas.', 28153),
(156555, 'ptBR', 'É melhor tu levar isso.', '', 28153),
(156554, 'ptBR', 'Já perdi a conta do tempo que passei nesta cela. Mas, no fim das contas, não importa.', '', 28153),
(156553, 'ptBR', 'Meu nome é Sam. Sam Guilhem. Finalmente, alguém armado do nosso lado... que bom.', '', 28153),
(156552, 'ptBR', 'Esses piratas são gente da pior estirpe. Mate todos sem piedade.', 'Esses piratas são gente da pior estirpe. Mate todos sem piedade.', 28153),
(156551, 'ptBR', 'Onde é que nós fomos nos meter?', 'Onde é que nós fomos nos meter?', 28153),
(156550, 'ptBR', 'Vocês ainda vão ouvir falar de mim, monstros!', 'Vocês ainda vão ouvir falar de mim, monstros!', 28153),
(156549, 'ptBR', 'Eu ainda matei uns dez monstros antes de eles me derrotarem!', 'Eu ainda matei uns dez monstros antes de eles me derrotarem!', 28153),
(156548, 'ptBR', 'Pela Aliança!', 'Pela Aliança!', 28153),
(156547, 'ptBR', 'Ninguém fica pra trás!', 'Ninguém fica pra trás!', 28153),
(156546, 'ptBR', 'Eu sabia que o Serpecida não ia nos abandonar!', 'Eu sabia que o Serpecida não ia nos abandonar!', 28153),
(156545, 'ptBR', 'Eu te pago uma bebida quando voltarmos pro barco.', 'Eu te pago uma bebida quando voltarmos pro barco.', 28153),
(156544, 'ptBR', 'Eu nunca imaginei que eles pudessem comer tanto...', '', 28153),
(156543, 'ptBR', 'Os ranishus têm um apetite insaciável, mas uma mente simplória. Eles comem tudo pela frente, inclusive outros ranishus. Vamos tirar vantagem disso!', '', 28153),
(156542, 'ptBR', '', '<Garona gira as lâminas tão rápido que parecem desaparecer.>', 28153),
(156541, 'ptBR', 'Essas águias de guerra nos levarão até o destino. Tudo pronto? Então subam a bordo!', '', 28153),
(156540, 'ptBR', 'Vamos em frente.', '', 28153),
(156539, 'ptBR', 'Minha rainha cuidou de tudo. Nosso transporte nos aguarda nas muralhas.', '', 28153),
(156538, 'ptBR', 'Eu só queria um pouquinho do tesouro deles.', 'Eu só queria um pouquinho do tesouro deles.', 28153),
(156537, 'ptBR', 'Eu voltarei, seus piratas! Vocês vão pagar por tudo isso!', 'Eu voltarei, seus piratas! Vocês vão pagar por tudo isso!', 28153),
(156536, 'ptBR', 'Mata aquele bando de covardes!', 'Mata aquele bando de covardes!', 28153),
(156535, 'ptBR', 'Tô com saudades de Zuldazar... Até quando vou ter que sofrer por aqui?', 'Tô com saudades de Zuldazar... Até quando vou ter que sofrer por aqui?', 28153),
(156534, 'ptBR', 'Não estou vendo tesouro nenhum aqui. Que bando de mentirosos!', 'Não estou vendo tesouro nenhum aqui. Que bando de mentirosos!', 28153),
(156533, 'ptBR', 'Não me deixaram entrar pra tripulação! Isso não é justo.', 'Não me deixaram entrar pra tripulação! Isso não é justo.', 28153),
(156532, 'ptBR', 'Uma rara gentileza no deserto.', 'Uma rara gentileza no deserto.', 28153),
(156531, 'ptBR', 'Eu não esperava que alguém viesse me ajudar. Agradeço profundamente.', 'Eu não esperava que alguém viesse me ajudar. Agradeço profundamente.', 28153),
(156530, 'ptBR', 'Alguma coisa se abriu.', '', 28153),
(156529, 'ptBR', 'Ainda não acabou...', '', 28153),
(156528, 'ptBR', 'Acho que já foram todos. Bom trabalho, $p. Eu sabia que podia contar com você.', '', 28153),
(156527, 'ptBR', 'Ainda há muitos vulperas aprisionados nas tocas. Podemos contar com você para ajudá-los a escapar?', '', 28153),
(156526, 'ptBR', 'O varredor cuidadosamente calibrado emite uma nota curta por não ter encontrado nenhum fóssil por perto.', 'O varredor cuidadosamente calibrado emite uma nota curta por não ter encontrado nenhum fóssil por perto.', 28153),
(156525, 'ptBR', 'O elemental de escavação ribomba aborrecido por não ter encontrado nenhum fóssil por perto.', 'O elemental de escavação ribomba aborrecido por não ter encontrado nenhum fóssil por perto.', 28153),
(156524, 'ptBR', '', 'Por Guilnéas!', 28153),
(156523, 'ptBR', '', 'Guardas, venham cá! Tragam-me a cabeça deles!', 28153),
(156522, 'ptBR', '|TINTERFACE\\ICONS\\SPELL_HOLY_DIVINEPROVIDENCE:20|t O Guardião Titânico Hezrel começa a lançar |cFFF00000|Hspell:269310|h[Luz Purificante]|h|r!', '', 28153),
(156521, 'ptBR', '', 'Então a Horda decidiu nos atacar aqui? Já me poupa o esforço de ir atrás. Guilneanos, atacar!', 28153),
(156520, 'ptBR', 'É cálculo demais para a minha cabeça. Volte daqui a pouco para pegar sua parte do tesouro.', '', 28153),
(156519, 'ptBR', '', 'Assim como o banco de Altaforja, é um serviço para cinco pessoas.', 28153),
(156518, 'ptBR', 'A gente vai ser herói... herói rico!', '', 28153),
(156517, 'ptBR', 'Me dá riqueza, $p. Eu quero comprar uma dentadura de ouro!', '', 28153),
(156516, 'ptBR', '', 'Como vai o dente, Edgar?', 28153),
(156514, 'ptBR', '', 'Eu tive um sonho parecido, só que no banco de Altaforja.', 28153),
(156513, 'ptBR', '', 'Assim que botarmos a mão no ouro, vou fazer umas compras e tomar um banho de perfume.', 28153),
(156512, 'ptBR', 'Talvez nos encontremos de novo algum dia. Adeus!', '', 28153),
(156511, 'ptBR', 'A gente tá livre...', '', 28153),
(156510, 'ptBR', 'A gente... tem que fugir...', '', 28153),
(156509, 'ptBR', '', 'Obrigada pela ajuda, $n. Seguirei para outra parte.', 28153),
(156508, 'ptBR', '', 'Não vou nem fingir que entendo seus motivos, $n, mas agradeço por abater outro Cavaleiro da Morte.', 28153),
(156507, 'ptBR', '', 'Observe os céus, $n! Estou sentindo que alguém se aproxima!', 28153),
(156506, 'ptBR', 'E aí, $p?', 'Se tem ouro no meio, pode contar comigo!', 28153),
(156505, 'ptBR', 'Eu preciso da sua ajuda.', 'Eu preciso da sua ajuda.', 28153),
(156504, 'ptBR', 'Eu sobrevivi ao Lich Rei e acabei perecendo nas mãos de alguém do seu nível... Argh...', '', 28153),
(156503, 'ptBR', 'Que desperdício...', '', 28153),
(156502, 'ptBR', 'Eu preciso da sua ajuda.', 'Eu preciso da sua ajuda.', 28153),
(156501, 'ptBR', 'Você venceu... Dragão...', '', 28153),
(156500, 'ptBR', 'Uma morte... definitiva...', '', 28153),
(156499, 'ptBR', 'Não é... justo...', '', 28153),
(156498, 'ptBR', 'Então vou tomar o que é meu por direito... à força!', '', 28153),
(156497, 'ptBR', 'Estou entendendo, $n! Você quer ser $Uo único Cavaleiro da Morte:a única Cavaleira da Morte; a ter essa montaria esplêndida!', '', 28153),
(156496, 'ptBR', 'Mas eu já estava de olho naquela fera ossuda ancestral que está atrás de você. Então, se não se importa, eu vou pegar o que é meu.', '', 28153),
(156495, 'ptBR', 'O draco que está lá é pequeno... e ainda vive. Não será um grande obstáculo.', '', 28153),
(156494, 'ptBR', 'Eu estou acompanhando seus passos. Você veio me auxiliar? Vejo que trouxe um presente!', '', 28153),
(156493, 'ptBR', '$USenhor da Morte:Senhora da Morte; $n! Que surpresa!', '', 28153),
(156492, 'ptBR', 'Hunf. Se você quer que seja do jeito mais difícil, então assim será!', '', 28153),
(156491, 'ptBR', '', '$n, me proteja! O ritual precisa ser concluído!', 28153),
(156490, 'ptBR', 'Então afaste-se, pequeno draco. Eu tenho uma questão a tratar com aquela pilha de ossos.', '', 28153),
(156489, 'ptBR', 'Acho que vou seguir meu plano original e ficar com o antigo.', '', 28153),
(156488, 'ptBR', 'Vamos dar o fora daqui!', 'Vamos dar o fora daqui!', 28153),
(156487, 'ptBR', 'Só a melhor de todas as montarias pode servir a um cavaleiro esplêndido como eu.', '', 28153),
(156486, 'ptBR', 'Dois dragões! Mas que surpresa! Embora o que está vivo seja... mirrado.', '', 28153),
(156485, 'ptBR', '', 'Você não é $Ubem-vindo:bem-vinda; aqui, $UCavaleiro da Morte:Cavaleira da Morte;.', 28153),
(156484, 'ptBR', 'Ora, ora... O que temos aqui?', '', 28153),
(156483, 'ptBR', 'Os seguidores de Zul não deixarão que Rezan escape tão facilmente do destino dele. Teremos que sair daqui lutando.\n\nVocê está pront$Uo:a;?', '', 28153),
(156482, 'ptBR', 'Por que a pressa? Calma. Descanse um pouco... tire um cochilo! Aqui, você está a salvo.', '', 28153),
(156481, 'ptBR', 'Meu pai ensinou a gente a usar a forja... Esse martelo foi a primeira coisa que fizemos juntos.', '', 28153),
(156480, 'ptBR', 'Meu martelo! Tu trouxe de volta!', '', 28153),
(156479, 'ptBR', '', 'Os exilados são o que eu tenho de família.', 28153),
(156478, 'ptBR', '', 'Bem-vind$Uo:a; à gangue, $p.', 28153),
(156477, 'ptBR', 'Bem-vind$Uo:a; à gangue, $p.', '', 28153),
(156476, 'ptBR', '', 'Bem-vind$Uo:a; à gangue, $p.', 28153),
(156475, 'ptBR', 'Bem-vind$Uo:a; à gangue, $p.', '', 28153),
(156474, 'ptBR', 'Você quer uma bebida forte ou algo para comer?', 'Você quer uma bebida forte ou algo para comer?', 28153),
(156473, 'ptBR', 'Ah, é você, $p? Os Zangareia não te seguiram, seguiram?', '', 28153),
(156472, 'ptBR', 'Se a gente emboscar mais umas caravanas, já vai dar pra atacar a arena e fazer um saque de responsa!', '', 28153),
(156471, 'ptBR', 'Tô com sede! Vai roubar aquele goró bonzão dos Zandalari pra mim!', '', 28153),
(156470, 'ptBR', 'Tamos ficando sem lenha. Vamo procurar outra caravana de vulpera pra assaltar!', '', 28153),
(156469, 'ptBR', 'Os desertos são dos Zangareia! Se alguém entrar, é invasor!', '', 28153),
(156468, 'ptBR', 'Me traz mais escravo. Eu ainda tenho muita lança pra jogar.', '', 28153),
(156467, 'ptBR', 'Arrebenta com eles! Arrebenta pra valer!', '', 28153),
(156466, 'ptBR', 'Cadê aquela pompa toda agora, hein, ô Zandalari arrogante?', '', 28153),
(156465, 'ptBR', 'Rá! Peguei um! Bem no meio do peito, vulpera feioso...', '', 28153),
(156464, 'ptBR', 'Você quer seu martelo de volta, sua batata sujismunda toda cabeluda? VEM PEGAR.', '', 28153),
(156463, 'ptBR', 'Vamos expurgar a escória kultirena das nossas terras! $n, convoque a Horda e vamos pôr um fim nisso.', '', 28153),
(156462, 'ptBR', 'Controle sua língua. Yazma é a Alta-sacerdotisa da minha loa e tem a confiança do Rei Rastakhan.$b$bE, se os boatos forem verdade, ela tem bem mais do que isso em relação ao grande Profeta Zul.', 'Controle sua língua. Yazma é a Alta-sacerdotisa da minha loa e tem a confiança do Rei Rastakhan.$b$bE, se os boatos forem verdade, ela tem bem mais do que isso em relação ao grande Profeta Zul.', 28153),
(156461, 'ptBR', 'Shadra é a loa mais bem conceituada no Conselho Zanchuli, então os seguidores dela, como eu, têm privilégios. Por exemplo, o direito de não dar satisfações a gente como você.', 'Shadra é a loa mais bem conceituada no Conselho Zanchuli, então os seguidores dela, como eu, têm privilégios. Por exemplo, o direito de não dar satisfações a gente como você.', 28153),
(156460, 'ptBR', 'Maldição...', 'Maldição...', 28153),
(156459, 'ptBR', 'Você vai perder...', 'Você vai perder...', 28153),
(156458, 'ptBR', 'Meu Rei... Sinto muito...', 'Meu Rei... Sinto muito...', 28153),
(156457, 'ptBR', 'Você vai... pagar...', 'Você vai... pagar...', 28153),
(156456, 'ptBR', 'Pela... Aliança...', 'Pela... Aliança...', 28153),
(156455, 'ptBR', 'Os seguidores de Shadra acompanharam sua raça com grande interesse.$b$BVemos que sua Horda avança cada vez mais em uma enorme rede de mentiras. A armadilha se fechará, e vocês só se darão conta quando for tarde.', 'Os seguidores de Shadra acompanharam sua raça com grande interesse.$b$BVemos que sua Horda avança cada vez mais em uma enorme rede de mentiras. A armadilha se fechará, e vocês só se darão conta quando for tarde.', 28153),
(156454, 'ptBR', 'Morra!', 'Morra!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156453, 'ptBR', 'Vou mandar você de volta a Orgrimmar em pedacinhos!', 'Vou mandar você de volta a Orgrimmar em pedacinhos!', 28153),
(156452, 'ptBR', 'Você vai pagar pelos seus crimes contra a Aliança!', 'Você vai pagar pelos seus crimes contra a Aliança!', 28153),
(156451, 'ptBR', 'Eu sirvo Shadra, senhora dos espiões e loa dos venenos. Quem você serve de fato?', 'Eu sirvo Shadra, senhora dos espiões e loa dos venenos. Quem você serve de fato?', 28153),
(156450, 'ptBR', 'Morra, escória da Horda!', 'Morra, escória da Horda!', 28153),
(156449, 'ptBR', 'Pela Aliança!', 'Pela Aliança!', 28153),
(156448, 'ptBR', 'A senhora notou a sua presença nos domínios dela. Vá com cuidado.', 'A senhora notou a sua presença nos domínios dela. Vá com cuidado.', 28153),
(156447, 'ptBR', 'Vá com a Mãe Terra, $n.', 'Vá com a Mãe Terra, $n.', 28153),
(156446, 'ptBR', 'Nossa caçada nesta terra está apenas começando.', '', 28153),
(156445, 'ptBR', 'Rhan\'ka ainda está escondido no oásis? Uma hora dessas tenho que fazer uma visita para ele...', '', 28153),
(156444, 'ptBR', 'Eu sabia que você ia voltar atrás de mais! Tenho um bocado fresquinho aqui, só para você.', '', 28153),
(156443, 'ptBR', '[CENA MOSTRANDO O GENERAL JAKRA\'ZET E O IMPERADOR KORTHEK FAZENDO CONLUIO.]', '', 28153),
(156442, 'ptBR', 'As profundezas... te observam...', 'As profundezas... te observam...', 28153),
(156441, 'ptBR', 'Eu vou atirar sua carcaça estropiada no mar!', 'Eu vou atirar sua carcaça estropiada no mar!', 28153),
(156440, 'ptBR', '', 'Eu devia ter nascido goblina. Eles mostram mais reconhecimento pelas minhas habilidades.', 28153),
(156439, 'ptBR', 'Devia fazer negócio com os Maré-férrea. São mais otários ainda.', '', 28153),
(156438, 'ptBR', 'Faça o que for necessário enquanto buscamos Zul, $Upequeno herói:pequena heroína;. Mas fique de prontidão, vamos precisar da sua ferocidade muito em breve.', '', 28153),
(156437, 'ptBR', '', 'Vamos caçar esses hereges até os confins de Azeroth. Eu vou reunir meu bando e lançar uma chuva de pedras e morte na cabeça dessas criaturas malignas que ousaram nos desafiar.\n\nPor enquanto, minha revoada vai vasculhar os céus e descobrir o que Zul e seus traidores estão armando.', 28153),
(156436, 'ptBR', 'Tu acertou o golpe mortal... desta vez...', '', 28153),
(156435, 'ptBR', '<Entrar com meu grupo na Fila para Expedição Insular JxJ.>', '<Entrar com meu grupo na Fila para Expedição Insular JxJ.>', 28153),
(156434, 'ptBR', '<Entrar na Fila para Expedição Insular JxJ.>', '<Entrar na Fila para Expedição Insular JxJ.>', 28153),
(156433, 'ptBR', 'Use o fetiche de Jin\'Tiki para destruir Zulajin!', 'Use o fetiche de Jin\'Tiki para destruir Zulajin!', 28153),
(156432, 'ptBR', 'Espero ter escondido minha chave bem para que só você a encontre.', '', 28153),
(156431, 'ptBR', 'Sua bravura é inquestionável, mas você não está em condições de lutar. $n, eu vou com nosso camarada. Venha nos encontrar na torre bélica quando puder.', '', 28153),
(156430, 'ptBR', 'Obrigado, eu vou proteger a torre bélica. Nós vamos precisar dela para reunir o resto das tropas.', 'Obrigada, eu vou proteger a torre bélica. Nós vamos precisar dela para reunir o resto das tropas.', 28153),
(156429, 'ptBR', '', 'Minhas irmãs... matarão vocês...', 28153),
(156428, 'ptBR', 'A Horda sucumbirá...', 'A Horda sucumbirá...', 28153),
(156427, 'ptBR', 'Vocês seguem uma lunática...', 'Vocês seguem uma lunática...', 28153),
(156426, 'ptBR', 'Seus monstros...', 'Seus monstros...', 28153),
(156425, 'ptBR', 'Eu... vou matar... vocês...', 'Eu... vou matar... vocês...', 28153),
(156424, 'ptBR', 'A Horda pagará...', 'A Horda pagará...', 28153),
(156423, 'ptBR', 'Por Teldrassil...', 'Por Teldrassil...', 28153),
(156422, 'ptBR', 'Irmãs... eu tentei...', 'Irmãs... eu tentei...', 28153),
(156421, 'ptBR', '', 'Minha família morreu em Teldrassil! Eu vou matar você!', 28153),
(156420, 'ptBR', '', 'Nós nos vingaremos por Teldrassil!', 28153),
(156419, 'ptBR', 'Os kultirenos vão pensar duas vezes antes de se meterem com a Horda.', '', 28153),
(156418, 'ptBR', 'Por Teldrassil e pela Aliança!', 'Por Teldrassil e pela Aliança!', 28153),
(156417, 'ptBR', 'Morram sofrendo, escória da Horda!', 'Morram sofrendo, escória da Horda!', 28153),
(156416, 'ptBR', '', 'Assassinos! Como ousam dar as caras aqui?', 28153),
(156415, 'ptBR', 'Nós vai por aqui!', '', 28153),
(156414, 'ptBR', 'Agora eu vai andar!', '', 28153),
(156413, 'ptBR', 'Nós vai onde eu quero!', '', 28153),
(156412, 'ptBR', 'Eu agora ter pernas!', '', 28153),
(156411, 'ptBR', 'Eu vai pilotar agora!', '', 28153),
(156410, 'ptBR', 'Seja $Upurificado:purificada; pelo fogo sagrado!', '', 28153),
(156409, 'ptBR', 'Não... Eu preciso encontrar... o anel...', '', 28153),
(156408, 'ptBR', 'Monstros! Eu vou mandar suas cabeças para a Chefe Guerreira!', 'Monstros! Eu vou mandar suas cabeças para a Chefe Guerreira!', 28153),
(156407, 'ptBR', 'Sua cabeça será um presente para minha rainha!', '', 28153),
(156406, 'ptBR', '', 'A Horda pagará pelo que fez a Teldrassil!', 28153),
(156405, 'ptBR', '', 'Vou lhe mostrar como queimar uma carcaça!', 28153),
(156404, 'ptBR', '', 'Parece que o nosso trabalho aqui acabou! Vê se te cuida, $p.', 28153),
(156403, 'ptBR', 'Meus homens serão vingados. Eu juro.', 'Meus homens serão vingados. Eu juro.', 28153),
(156402, 'ptBR', 'Mortais tolos. Vocês não podem impedir meu retorno.', '', 28153),
(156401, 'ptBR', '', 'Você aí da Horda. Preciso das suas habilidades.', 28153),
(156400, 'ptBR', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Há uma nova |cFFFF0404|Hspell:263420|h[Matriz de Poder]|h|r disponível.', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Há uma nova |cFFFF0404|Hspell:263420|h[Matriz de Poder]|h|r disponível.', 28153),
(156399, 'ptBR', 'Aquele troll é mais pirado que ranishu com fome.', '', 28153),
(156398, 'ptBR', 'Rikati revira os olhos.', '', 28153),
(156397, 'ptBR', 'Certo, meu amigo. Farei isso! Obrigado!', '', 28153),
(156396, 'ptBR', 'Não tem tempo pra bate-papo, Rikati! Os Zangareia tão quebrando tudo! Esconde teu mel!', '', 28153),
(156395, 'ptBR', 'O Anel das Marés será nosso! A Rainha Azshara o quer!', 'O Anel das Marés será nosso! A Rainha Azshara o quer!', 28153),
(156394, 'ptBR', 'Não vamos parar enquanto o anel não for nosso!', 'Não vamos parar enquanto o anel não for nosso!', 28153),
(156393, 'ptBR', 'Como é que é? Tu acha que eu vou ficar contando? Eu? Tu que tem que contar.\n\nO jeito é começar de novo, né.', '', 28153),
(156392, 'ptBR', 'Onde está o Anel das Marés? Não esconda de nós!', 'Onde está o Anel das Marés? Não esconda de nós!', 28153),
(156391, 'ptBR', 'O Anel das Marés foi perdido nas redondezas. Ele tem de voltar para a rainha!', 'O Anel das Marés foi perdido nas redondezas. Ele tem de voltar para a rainha!', 28153),
(156390, 'ptBR', 'O Rastro da Tempestade só cresce. Você está conosco?', 'O Rastro da Tempestade só cresce. Você está conosco?', 28153),
(156389, 'ptBR', 'Já cheguei a um milhão de almas?', 'Já cheguei a um milhão de almas?', 28153),
(156388, 'ptBR', 'Ninguém há de ficar no caminho da nossa Rainha!', 'Ninguém há de ficar no caminho da nossa Rainha!', 28153),
(156387, 'ptBR', 'O Anel das Marés é nosso de direito!', 'O Anel das Marés é nosso de direito!', 28153),
(156386, 'ptBR', 'Ainda podemos deter o Lorde Trovamare.', 'Ainda podemos deter o Lorde Trovamare.', 28153),
(156385, 'ptBR', 'O anel será nosso!', 'O anel será nosso!', 28153),
(156384, 'ptBR', 'A Rainha Azshara quer o Anel das Marés!', 'A Rainha Azshara quer o Anel das Marés!', 28153),
(156383, 'ptBR', '|TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t A Serpente Dourada absorve um Ouro Vivo, ganhando |cFFFF0000|Hspell:265991|h[Esplendor]|h|r!', 'A Serpente Dourada absorve um Ouro Vivo, ganhando |TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t um incrível |cFFFF0000|Hspell:265991|h[Esplendor]|h|r!', 28153),
(156382, 'ptBR', '', 'O-ôu! Isso não é nada bom! NADA BOM!', 28153),
(156381, 'ptBR', 'Use uma das cordas para descer até um veículo de desembarque... a menos que você prefira nadar.', '', 28153),
(156380, 'ptBR', 'Eu não lavo mais nenhuma dessas cuecas e calcinhas imundas de humano!', '', 28153),
(156379, 'ptBR', '', 'Estou encharcada até o osso! Obrigada.', 28153),
(156378, 'ptBR', '', 'Eu estou farta!', 28153),
(156377, 'ptBR', 'Você me salvou de uma sina terrível.', '', 28153),
(156375, 'ptBR', 'Enquanto você se aventurava, eu estudei a lâmina.', 'Enquanto você se aventurava, eu estudei a lâmina.', 28153),
(156374, 'ptBR', '<Mestre Espião Shaw assente com a cabeça.>', '', 28153),
(156373, 'ptBR', 'Chegamos, Mestre Espião.', '', 28153),
(156372, 'ptBR', 'Eu vou trabalhar com o Mestre Espião Shaw. Não é dos sujeitos mais amistosos, mas dá conta da refrega.', '', 28153),
(156371, 'ptBR', 'O Rei trouxe uns heróis impressionantes para essa campanha.', '', 28153),
(156370, 'ptBR', 'Asinha, vá encontrar comida.', '', 28153),
(156369, 'ptBR', 'Vem comigo, $Uguri:guria;.', '', 28153),
(156368, 'ptBR', 'Acertei bem no joelho!', 'Ai... essa deve ter doído!', 28153),
(156367, 'ptBR', 'Nós não desistimos tão fácil.', 'Deviam ter fugido enquanto podiam.', 28153),
(156366, 'ptBR', 'Lá se foi outro!', 'Não eram tão fortes quanto pensavam!', 28153),
(156365, 'ptBR', 'Olá, Capitã Rocha. Eu estava ansioso por esse encontro.', '', 28153),
(156364, 'ptBR', 'Então coloque-o na carroça. Você está sendo mais útil do que eu esperava, Senhorita Voss.', '', 28153),
(156363, 'ptBR', '', 'Intacto o bastante.', 28153),
(156362, 'ptBR', 'Praticamente intacto?', '', 28153),
(156361, 'ptBR', '', 'Aqui mesmo, Arauto da Praga. Eu recuperei o corpo.', 28153),
(156360, 'ptBR', 'Bom trabalho, $p. Pois bem... Onde está Lilian?', '', 28153),
(156359, 'ptBR', 'Você tem que correr... eles vão atrás do Rezan!', '', 28153),
(156358, 'ptBR', 'Eles... eles me fizeram contar como os Drakkari conseguiram.', '', 28153),
(156357, 'ptBR', 'Excelente. Taelia deixará você por dentro de tudo.', '', 28153),
(156356, 'ptBR', '', 'Senhor! O relatório de situação está pronto!', 28153),
(156355, 'ptBR', '', 'Você transformou o exército delas em cinzas! Meus parabéns.', 28153),
(156354, 'ptBR', '', 'As bruxas estão começando a recompor as forças. Tome o controle de um demolidor e destrua o exército delas!', 28153),
(156353, 'ptBR', '', 'Temos que mostrar aos kultirenos o que significa ser inimigo da Horda.', 28153),
(156352, 'ptBR', 'Lembrem-se: Porto da Ponte é um grande assentamento muito bem guardado. Tentem ficar nos limites da cidade... por enquanto.', '', 28153),
(156351, 'ptBR', 'Fizemos a nossa parte, $p. Tenho orgulho do que realizamos aqui.\n\nMas chegou a hora de cuidar do meu povo e garantir a segurança deles.\n\nSem dúvida, nos encontraremos de novo. Sinto-me honrado em chamar você de $Uamigo e aliado:amiga e aliada;.', '', 28153),
(156350, 'ptBR', 'Os Ímpios tratam suas feras com crueldade. Não é difícil virá-las contra os mestres.', '', 28153),
(156349, 'ptBR', 'Eu não tenho que aceitar isso. Quem me colocou na minha posição foi o Profeta Zul!', '', 28153),
(156348, 'ptBR', '', 'Agora ESSA foi uma batalha digna de canções!\n\nFoi uma honra lutar ao lado de você e Vorrik. Espero que possa acontecer de novo em breve.\n\nSempre há mais Ímpios para matar, afinal.', 28153),
(156347, 'ptBR', 'Vamos terminar isso juntos.', '', 28153),
(156346, 'ptBR', '', 'Vamos dar uma lição nesses sethraks.', 28153),
(156345, 'ptBR', '', 'Esses suprimentos vão nos ajudar na luta contra o conventículo. Obrigada.', 28153),
(156344, 'ptBR', 'Venha, a fortaleza fica logo ali na frente.', '', 28153),
(156343, 'ptBR', 'Ótimo. Então eles serão o nosso alvo.', '', 28153),
(156342, 'ptBR', '', 'Essa cidade por onde passamos, Porto da Ponte, parece ser a maior ameaça da região.', 28153),
(156341, 'ptBR', 'Rexxar! <tosse> Muitos ainda resistem. E-eles não têm muito tempo.', 'Rexxar! <tosse> Muitos ainda resistem. E-eles não têm muito tempo.', 28153),
(156340, 'ptBR', 'Aquela criatura não vai mais fazer soldados da Horda de café da manhã. Excelente trabalho.', '', 28153),
(156339, 'ptBR', '', 'Nossa prata está acabando. Entre nas minas e pegue o máximo que puder.', 28153),
(156338, 'ptBR', 'Rakjan parece estar disposto a nos ajudar, e é fácil entender o motivo.\n\nOs Ímpios foram cruéis a ele e sua ninhada. Veja só as cicatrizes no corpo dele e os poleiros vazios no pico.\n\nEle merece vingança tanto quanto qualquer um de nós. Vamos conquistá-la juntos.', '', 28153),
(156337, 'ptBR', 'Logo, Samuel. Aguente firme só mais um pouco.', '', 28153),
(156336, 'ptBR', 'Eu estou com tanto frio. Quando as vozes vão parar?', '', 28153),
(156335, 'ptBR', '$n, dá uma mexida no meu ensopado, para não queimar.', '', 28153),
(156334, 'ptBR', 'Um trabalho e tanto. Agora, vamos fazer com que essa festa do conselho seja a última.', '', 28153),
(156333, 'ptBR', 'Bom trabalho, ô riqueza. Agora a gente tá pronto pra acabar com a festa do conselho.', '', 28153),
(156332, 'ptBR', 'Calma, a dor vai passar com essas plantas. Você sabe nos dizer o que está acontecendo lá dentro? Tem mais alguém vivo?', '', 28153),
(156331, 'ptBR', '|TInterface\\ICONS\\ABILITY_DEATHKNIGHT_SOULREAPER:20|t O dano de Golias Vinculado aumenta a cada aplicação de |cFFFF0404|Hspell:260512|h[Colheita de Almas]|h|r!', '', 28153),
(156330, 'ptBR', 'Cuidado! Este aqui ainda está respirando!', '', 28153),
(156329, 'ptBR', 'Muitos bravos guerreiros morreram na batalha. Sua chegada foi muito bem-vinda.', '', 28153),
(156328, 'ptBR', 'Os kultirenos atacaram enquanto tentávamos salvar a tripulação. Nossas tropas estavam dispersas demais para defendermos as duas posições. Fomos obrigados a fugir para a praia.', '', 28153),
(156327, 'ptBR', 'O ataque foi hoje, de manhã cedo. Os magos kultirenos usaram um objeto estranho para evocar os horrores que você viu enroscados nos nossos navios.', '', 28153),
(156326, 'ptBR', 'Confirmado. Missão bem-sucedida. É a perfeição encarnada! Adoro quando um plano dá certo. Câmbio e desligo.', '', 28153),
(156325, 'ptBR', 'Execute as ordens a seguir. Vê um grande botão vermelho? Saia da área e APERTE o grande botão vermelho. Execute quando quiser. Câmbio.', '', 28153),
(156324, 'ptBR', 'O código de autenticação é um-nove-nove. Alinhamento de instrumento fora dos parâmetros aceitos... Cancele isso... vou fazer funcionar. Fique no aguardo, câmbio.', '', 28153),
(156323, 'ptBR', 'Entendido. Calibração concluída. Direcionem os instrumentos em localizações bem específicas. Entrem em contato quando estiverem ajustados. Câmbio.', '', 28153),
(156322, 'ptBR', 'Testando. Aqui quem fala é o Alfa 1. Grupo de abordagem, esquadrão alfa. Estão me ouvindo? Câmbio.', '', 28153),
(156321, 'ptBR', 'Uma batalha gloriosa! E nós saímos com vida, $p!', '', 28153),
(156320, 'ptBR', '', 'A chama nunca se apaga...', 28153),
(156319, 'ptBR', '', 'Do pó vieste...', 28153),
(156318, 'ptBR', 'Ficamos muito gratos por seus feitos, $p.', '', 28153),
(156317, 'ptBR', '', 'Seus ossos acenderão minha lareira.', 28153),
(156316, 'ptBR', '', 'Não vou deixar ninguém para chorar sobre as suas cinzas.', 28153),
(156315, 'ptBR', 'Na nossa história, tivemos poucos dias tão bons como este!', '', 28153),
(156314, 'ptBR', 'Eu vou criar uma receita de sopa em sua homenagem!', '', 28153),
(156313, 'ptBR', 'Sopa de tartaruga não chega nem perto de sopa de $r.\n\nSó traz a carne de minhoca da lama e deixa as tartaruguinhas em paz.\n\nVem me visitar qualquer hora. A gente pode experimentar outras receitas de sopa!', '', 28153),
(156312, 'ptBR', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t %s começa a lançar |cFFFF0000|Hspell:267334|h[Orbe da Corrupção]|h|r!', 'Uma projeção aparece ao longe...', 28153),
(156311, 'ptBR', '', 'É fácil perder nosso caminho.', 28153),
(156310, 'ptBR', 'Se precisar de ajuda, é só falar comigo!', '', 28153),
(156309, 'ptBR', 'Agora que tá tudo resolvido aqui, eu vou voltar.', '', 28153),
(156308, 'ptBR', '|cFF0000FF(Missão)|r Zarpar para o Estreito Tiragarde.', '|cFF0000FF(Missão)|r Zarpar para o Estreito Tiragarde.', 28153),
(156307, 'ptBR', '|TInterface\\Icons\\ABILITY_DEATHKNIGHT_DEATHSIPHON2.BLP:20|t %s começa a lançar |cFFFF0000|Hspell:265360|h[Trapaça Turbulenta]|h|r!', 'Uma projeção aparece ao longe...', 28153),
(156306, 'ptBR', '', 'Sou grata pela sua ajuda.', 28153),
(156305, 'ptBR', '', 'Estamos cercados por sombras do passado.', 28153),
(156304, 'ptBR', 'Sabe qual é o meu lugar preferido? O campo. Campo de trabalho forjado. Ahahahaha!', '', 28153),
(156303, 'ptBR', 'Tu tá atrás de sarna pra se coçar?', '', 28153),
(156302, 'ptBR', 'Não me faz bater o martelão!', '', 28153),
(156301, 'ptBR', 'Que tua forja nunca esfrie.', '', 28153),
(156300, 'ptBR', 'Não deixa o fogo da tua forja apagar.', '', 28153),
(156299, 'ptBR', 'Vai pela sombra!', '', 28153),
(156298, 'ptBR', 'Tu viu minha chave de boca por aí?', '', 28153),
(156297, 'ptBR', 'Como posso te ajudar?', '', 28153),
(156296, 'ptBR', 'Manda!', '', 28153),
(156286, 'ptBR', '', 'Tanta tristeza. Tanta perda.', 28153),
(156285, 'ptBR', '', 'Qual caminho devo seguir?', 28153),
(156284, 'ptBR', '', 'Preciso descobrir uma forma de superar esta situação.', 28153),
(156283, 'ptBR', 'A areia está vermelha.', 'A areia está vermelha.', 28153),
(156282, 'ptBR', 'Como eu vim parar aqui?', 'Como eu vim parar aqui?', 28153),
(156281, 'ptBR', 'Meus amigos vão me vingar.', 'Meus amigos vão me vingar.', 28153),
(156280, 'ptBR', 'Então o Turalyon fica brilhante e a Alleria fica sombria... Hmm... Acho que agora que estou de volta à ação é melhor eu arrumar um truque desses!', '', 28153),
(156279, 'ptBR', 'Eu me saí bem?', 'Eu me saí bem?', 28153),
(156278, 'ptBR', 'Vou destruir você!', 'Vou destruir você!', 28153),
(156277, 'ptBR', 'Chegou a sua hora!', 'Chegou a sua hora!', 28153),
(156276, 'ptBR', 'Vocês não vão nos deter!', 'Vocês não vão nos deter!', 28153),
(156275, 'ptBR', 'Graças à Luz, finalmente saí da Fortaleza da Honra. Aquele lugar já estava passando do ponto.', '', 28153),
(156274, 'ptBR', 'Hoje não, demônio!', 'Hoje não, demônio!', 28153),
(156273, 'ptBR', 'Eu e Hadggar nos juntamos semanalmente para uma partida de damas. (Quem avisa amigo é... ele trapaceia.)', '', 28153),
(156272, 'ptBR', 'Cada um de nós precisa fazer sua parte.', '', 28153),
(156271, 'ptBR', 'Por Stromgarde!', '', 28153),
(156270, 'ptBR', 'Eu não vou mentir pra tu, chefia.\n\nEu sempre sonhei em participar de um motim.', '', 28153),
(156269, 'ptBR', 'Pela Aliança!', '', 28153),
(156268, 'ptBR', 'A Aliança triunfará.', '', 28153),
(156267, 'ptBR', 'Lute bem.', '', 28153),
(156266, 'ptBR', 'Azeroth chama e precisamos agir.', '', 28153),
(156265, 'ptBR', 'Vamos lutar pelo que é nosso.', '', 28153),
(156264, 'ptBR', 'Aconteça o que acontecer, enfrentaremos juntos.', '', 28153),
(156263, 'ptBR', 'Minha vida pela Aliança.', '', 28153),
(156262, 'ptBR', 'Stromgarde retornará à glória.', '', 28153),
(156261, 'ptBR', 'Pode revirar os olhos, mas eu não vou deixar de falar... TÁ NA HORA DO MARTELO!', '', 28153),
(156260, 'ptBR', 'Acho que dá pra dizer que tenho síndrome do filho do meio. Mas quando um irmão é feito de diamante e o outro é um explorador famoso, é difícil achar teu espaço!', '', 28153),
(156259, 'ptBR', 'Mas o que...?! Alguém acabou de me chamar de \"Rei do Doce\" e me pediu um pirulito!', '', 28153),
(156258, 'ptBR', 'Nunca desistimos de uma batalha!', '', 28153),
(156257, 'ptBR', 'O clã Barbabronze te agradece.', '', 28153),
(156256, 'ptBR', 'Altaforja vencerá.', '', 28153),
(156255, 'ptBR', 'Que teu caminho te leve à glória.', '', 28153),
(156254, 'ptBR', 'Que teu martelo seja certeiro.', '', 28153),
(156253, 'ptBR', 'Que a Forja te proteja.', '', 28153),
(156252, 'ptBR', 'Martelo, machado... Vamos à peleja!', '', 28153),
(156251, 'ptBR', 'Você está aqui para ajudar a Aliança?', '', 28153),
(156250, 'ptBR', 'Os Três Martelos lutam como um.', '', 28153),
(156249, 'ptBR', 'Altaforja chegou para fazer sua parte.', '', 28153),
(156248, 'ptBR', 'Você sabe o que aconteceu com as seis primeiras legiões? Quer descobrir?', '', 28153),
(156247, 'ptBR', 'Querendo ir a ferros, soldado?', '', 28153),
(156246, 'ptBR', 'Você está abusando da minha paciência.', '', 28153),
(156245, 'ptBR', 'Nosso trabalho está apenas começando.', '', 28153),
(156244, 'ptBR', 'Até nosso próximo encontro.', '', 28153),
(156243, 'ptBR', 'Que a Luz esteja com você.', '', 28153),
(156242, 'ptBR', 'Pela força da Aliança, nossos inimigos conhecerão somente a derrota.', '', 28153),
(156241, 'ptBR', 'Pela Luz, o primeiro ataque é nosso.', '', 28153),
(156240, 'ptBR', 'Sua lenda se engrandece.', '', 28153),
(156239, 'ptBR', 'O destino sorri para nós hoje.', '', 28153),
(156238, 'ptBR', 'A Horda sucumbirá.', '', 28153),
(156237, 'ptBR', 'Soldado.', '', 28153),
(156236, 'ptBR', 'Nós somos os filhos e filhas da Aliança.', '', 28153),
(156235, 'ptBR', '', 'Temos que defender este mundo. Avante, Ferro Negro! À peleja, marchamos!', 28153),
(156234, 'ptBR', '', 'O mesmo sangue que flui em nossas veias... flui também por Azeroth.', 28153),
(156233, 'ptBR', '', 'Nosso reino foi forjado a martelo e bigorna. Com corações de fogo... e uma determinação de ferro.', 28153),
(156232, 'ptBR', '', 'A montanha nos dá vida. Ela nos dá força.', 28153),
(156231, 'ptBR', '', 'Thurgaden e Thaelin conceberam uma armadura à altura dos teus feitos. Usa ela com orgulho, $n.', 28153),
(156230, 'ptBR', '', 'Agora a Aliança sabe que os Ferro Negro tão prontos pro que der e vier. Eu não podia ter ninguém melhor para representar nosso povo.', 28153),
(156229, 'ptBR', '', 'Volta pra montanha. A gente tem uma coisa especial pra ti.', 28153),
(156228, 'ptBR', '', 'Tu nos dá muito orgulho, $n. Ouvi muito sobre a tua bravura nas jornadas por Azeroth.', 28153),
(156227, 'ptBR', '', 'Fomos forjados nas chamas da montanha, $n. Mostra teu fogo pro mundo.', 28153),
(156226, 'ptBR', '', 'Azeroth espera por ti, com Ventobravo sendo a primeira centelha da bigorna.', 28153),
(156225, 'ptBR', '', 'Chegou a hora dos Ferro Negro emergirem das sombras.', 28153),
(156224, 'ptBR', '', 'Muitos aconselharam a não virmos pra superfície. Mas os valentes não se intimidam.', 28153),
(156223, 'ptBR', 'Pela Aliança!', '', 28153),
(156222, 'ptBR', '', 'Os Ferro Negro aceitam seu convite. Pela Aliança!', 28153),
(156221, 'ptBR', '', 'Bah, é só formalidade! Não foi nada, Rei.', 28153),
(156220, 'ptBR', 'Mesmo assim, nunca pedimos ao seu clã que se juntasse oficialmente à Aliança... um descuido que espero que você perdoe e que me permita corrigir.', '', 28153),
(156219, 'ptBR', '', 'Sim.', 28153),
(156218, 'ptBR', 'Embora o clã Ferro Negro seja conhecido por seu... espírito independente, não podemos questionar a determinação nem a lealdade do seu povo.', '', 28153),
(156217, 'ptBR', 'A sua posição no Conselho dos Três Martelos ajudou a manter a ordem e a estabilidade em Altaforja.', '', 28153),
(156216, 'ptBR', '', 'Digo-te o mesmo, Rei Wrynn.', 28153),
(156215, 'ptBR', 'Rainha Regente Thaurissan, como é bom revê-la.', '', 28153),
(156214, 'ptBR', 'Ei! Tem gente trabalhando aqui.', '', 28153),
(156213, 'ptBR', '', 'Obrigada. Temos que preservar o que resta das fazendas de Drustvar.', 28153),
(156212, 'ptBR', '', 'Os porcos da fazenda aqui perto sumiram na área mais fechada do bosque. Vá salvá-los antes que os esporos os peguem!', 28153),
(156211, 'ptBR', '', 'As bruxas foram desmascaradas, e o meu povo está seguro outra vez. Obrigada.', 28153),
(156210, 'ptBR', '', 'Esse conventículo está querendo se infiltrar no Brado de Arom. Descubra o que estão tramando e acabe com o plano antes que corrompam alguém.', 28153),
(156209, 'ptBR', '<Oferecer Pó de Coagulação: |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', '<Oferecer Pó de Coagulação: |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', 28153),
(156208, 'ptBR', '<Oferecer Pergaminho Tortollano Ancestral: |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', '<Oferecer Pergaminho Tortollano Ancestral: |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', 28153),
(156207, 'ptBR', '<Oferecer Salmoura de Ouriço do Mar: |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t', '<Oferecer Salmoura de Ouriço do Mar: |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t', 28153),
(156206, 'ptBR', '<Oferecer Temperos Adstringentes: |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', '<Oferecer Temperos Adstringentes: |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', 28153),
(156205, 'ptBR', 'Fique alerta, $n. Passarei instruções conforme precisar de mais ingredientes.', '', 28153),
(156204, 'ptBR', 'Isso está além de todos nós, camarada. O loa da morte está com ele!', '', 28153),
(156203, 'ptBR', 'Bem. Isto está... um pouco além do meu conjunto de habilidades, infelizmente.', '', 28153),
(156202, 'ptBR', 'Jamil Abul\'housin se encolhe de terror!', '', 28153),
(156201, 'ptBR', 'Jamil?', '', 28153),
(156200, 'ptBR', 'A qualquer momento.', '', 28153),
(156199, 'ptBR', 'Pronto... o rei deve acordar, agora.', '', 28153),
(156198, 'ptBR', 'O sangramento não está parando. Rápido, $n, traga o pó de coagulação imediatamente!', '', 28153),
(156196, 'ptBR', 'O cântico de Jamil Abul\'housin vai ficando mais alto e desesperado.', '', 28153),
(156195, 'ptBR', 'Feito! Agora eu vou aplicar a poção.', '', 28153),
(156194, 'ptBR', 'Jamil Abul\'housin começa a entoar uma prece em voz baixa.', '', 28153),
(156193, 'ptBR', 'Certo, TRÊS pitadas.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156192, 'ptBR', 'Já faz setecentos anos desde que eu não faço. Queria bem ver você se lembrar de uma coisa mais velha que o avô do seu avô.', '', 28153),
(156191, 'ptBR', 'Tu esqueceu a receita?!', '', 28153),
(156190, 'ptBR', 'Eram uma ou duas pitadas? $n, traga-me o meu pergaminho.', '', 28153),
(156188, 'ptBR', 'Agradeço. Estou misturando o mais rápido que posso. Paciência.', '', 28153),
(156187, 'ptBR', 'Nada? Jol, é melhor você correr com o remédio...', '', 28153),
(156186, 'ptBR', 'Agora a salmoura. Confira a despensa.', '', 28153),
(156185, 'ptBR', 'Não deixem os crorgs fugir!', 'Não deixem os crorgs fugir!', 28153),
(156184, 'ptBR', 'Estou pronto, Jol.', 'Estou pronta, Jol.', 28153),
(156183, 'ptBR', 'Esses ingredientes são complicados. Vão exigir minha atenção completa. Você será minhas mãos para finalizar este preparado. Lembre-se, a vida do rei está em risco.\n\nPodemos começar?', '', 28153),
(156182, 'ptBR', '', 'Se o que o exilado disse for verdade, você vai ter que investigar. Mas toma cuidado. Jakra\'zet pode estar por perto.', 28153),
(156181, 'ptBR', 'Ora, eu achei que você não se importasse! Por onde começar?\n\nNós fazemos a peregrinação para Nazmir de poucos em poucos anos. Às vezes leva cinco, às vezes vinte. Depende de quando Torga está pronto para contar uma história.\n\nQuando sussurros e rumores de que Torga tem histórias para nos contar chegam aos nossos ouvidos, nós começamos a peregrinação. Nós chegamos aqui, nos sentamos e ouvimos a todas as histórias que Torga tem para contar, então passamos essas histórias adiante quando encontramos alguém.\n\nVocê pode se considerar com sorte. É raro ver tantos de nós reunidos assim. É uma história especial, se $ualgum:alguma; $uamigo:amiga; $r quiser ouvir...', '', 28153),
(156180, 'ptBR', 'Por cima do meu... cadáver...', 'Por cima do meu... cadáver...', 28153),
(156179, 'ptBR', 'Conte sobre essa peregrinação que você está fazendo.', 'Conte sobre essa peregrinação que você está fazendo.', 28153),
(156178, 'ptBR', 'Ninguém me escapa!', 'Ninguém me escapa!', 28153),
(156177, 'ptBR', 'Digamos que foi empate.', '', 28153),
(156176, 'ptBR', 'Um novo tipo de pólvora, como eu nunca vi na vida.', '', 28153),
(156175, 'ptBR', 'Boralus me pertence.', '', 28153),
(156174, 'ptBR', 'O que está acontecendo?', 'O que está acontecendo?', 28153),
(156173, 'ptBR', '', 'Pela Horda!', 28153),
(156172, 'ptBR', '', 'Ótimo! Agora nos leve para longe dos explosivos, depois da ponte.', 28153),
(156171, 'ptBR', '', 'Vamos avançando! Reúna todos os guardas da cidades... e o líder deles!', 28153),
(156170, 'ptBR', '', 'Venham nos pegar, seus covardes!', 28153),
(156169, 'ptBR', '', 'A Horda vai acabar com você!', 28153),
(156168, 'ptBR', '', 'Kultirenos! Seu pacto com a Aliança será sua sentença de morte!', 28153),
(156167, 'ptBR', '', 'Vá para a cidade e reúna o maior número de guardas que puder!', 28153),
(156166, 'ptBR', '', 'Filinto! Por aqui!', 28153),
(156165, 'ptBR', 'Como eu pude falhar?', 'Como eu pude falhar?', 28153),
(156164, 'ptBR', '', 'É isso aí. Acaba com o capitão que os Neblineiros vão continuar sendo homens e mulheres livres!', 28153),
(156163, 'ptBR', '', 'Então você acha que sabe o que é namorar um \"bad boy\"? Sabe de nada, inocente...', 28153),
(156162, 'ptBR', '', 'Engraçado... nem percebi que tinha perdido meu sotaque kultireno.', 28153),
(156161, 'ptBR', '', 'É claro que tenho meu cajado de ovelha. Quem você acha que cunhou o termo \"Ovelhomante\"?', 28153),
(156160, 'ptBR', 'Vamos roubar algumas armas antes de ir.', 'Vamos roubar algumas armas antes de ir.', 28153),
(156159, 'ptBR', 'Comprar e vender pessoas... Isso não é certo.', 'Comprar e vender pessoas... Isso não é certo.', 28153),
(156158, 'ptBR', 'Mexendo', 'Mexendo', 28153),
(156157, 'ptBR', 'Nós, vulperas, não vamos mais aceitar isso!', 'Nós, vulperas, não vamos mais aceitar isso!', 28153),
(156156, 'ptBR', 'Não é a última vez que nos encontramos!', '', 28153),
(156155, 'ptBR', 'Espero nunca mais ver um sethrak.', 'Espero nunca mais ver um sethrak.', 28153),
(156154, 'ptBR', 'É por isso que não se cutuca uma tartaruga!', '', 28153),
(156153, 'ptBR', 'Acho que eles planejavam me comer!', 'Acho que eles planejavam me comer!', 28153),
(156152, 'ptBR', 'Pelas areias, ainda bem que você apareceu!', 'Pelas areias, ainda bem que você apareceu!', 28153),
(156151, 'ptBR', '', 'Depois de todos esses anos você CONTINUA tentando me irritar? Algumas coisas nunca mudam...', 28153),
(156150, 'ptBR', '', 'A verdadeira batalha nos aguarda.', 28153),
(156149, 'ptBR', '', 'Eu farei o possível.', 28153),
(156148, 'ptBR', '', 'O caminho à frente não será fácil.', 28153),
(156147, 'ptBR', 'Doeu mais do que eu esperava.', 'Doeu mais do que eu esperava.', 28153),
(156146, 'ptBR', 'Peguei alguns cristais. Quem ri por último, ri melhor. Ha!', '', 28153),
(156145, 'ptBR', 'Este casco não está à venda!', '', 28153),
(156144, 'ptBR', 'Nenhum desses sethraks conseguiria arcar comigo, de toda sorte.', '', 28153),
(156143, 'ptBR', 'Os Ímpios não têm respeito algum por idade nem sabedoria.', '', 28153),
(156142, 'ptBR', 'Todos vão ouvir essa história em Zuldazar!', '', 28153),
(156141, 'ptBR', '', 'Não podemos permitir que o mundo seja tomado pelas trevas.', 28153),
(156140, 'ptBR', 'Finalmente minha sorte mudou para melhor!', '', 28153),
(156139, 'ptBR', 'A Chefe Guerreira ordena que dizimemos a presença da Aliança nesta região. Acabe com eles sem demora!', '', 28153),
(156138, 'ptBR', '', 'A hora de sonhar acabou.', 28153),
(156137, 'ptBR', 'Os tolos da Aliança assumiram uma posição nas proximidades. Faça-lhes uma visita... e prove que as aspirações deles são fúteis.', '', 28153),
(156136, 'ptBR', 'Forças da Aliança estão se estabelecendo perto de você. Faça com que hoje elas encontrem a ruína.', '', 28153),
(156135, 'ptBR', '', 'O que você quer da filha do mar?', 28153),
(156134, 'ptBR', 'A Aliança estremece perante nós! A Dama Sombria ficará satisfeita.', '', 28153),
(156133, 'ptBR', 'Que brutalidade impressionante! A Aliança sentiu nossa ira em toda a sua extensão.', '', 28153),
(156132, 'ptBR', 'Abrir fogo!', '', 28153),
(156131, 'ptBR', 'Aliança... deplorável! Eles vão pensar duas vezes antes de interferir em nossos planos novamente.', '', 28153),
(156130, 'ptBR', '', 'Temos um longo caminho à nossa frente.', 28153),
(156129, 'ptBR', 'Prenda a respiração, $p!', '', 28153),
(156128, 'ptBR', '', 'A Aliança resistirá.', 28153),
(156127, 'ptBR', '', 'Eu sei o que precisa ser feito.', 28153),
(156126, 'ptBR', '', 'Uma única centelha pode incendiar o mundo.', 28153),
(156125, 'ptBR', '', 'Controle seu poder... ou ele controlará você.', 28153),
(156124, 'ptBR', 'Por Lordaeron.', 'Por Lordaeron.', 28153),
(156123, 'ptBR', '', 'Eu nunca esquecerei.', 28153),
(156122, 'ptBR', '', 'Todos temos nossos fantasmas.', 28153),
(156121, 'ptBR', 'Até que enfim, um pouco de diversão!', 'Até que enfim, um pouco de diversão!', 28153),
(156120, 'ptBR', '', 'Cuidado em quem você confia.', 28153),
(156119, 'ptBR', 'Minha alma está sedenta.', 'Minha alma está sedenta.', 28153),
(156118, 'ptBR', 'É hora de sangrar!', 'É hora de sangrar!', 28153),
(156117, 'ptBR', 'Um abate eficiente muito me apetece. Assim, nosso esforço de guerra não fica atrasado.', '', 28153),
(156116, 'ptBR', 'Típico... mais um inimigo a enfrentar a força da Horda... e ser sobrepujado.', '', 28153),
(156115, 'ptBR', 'A Dama Sombria escolhe bem seus campeões.', '', 28153),
(156114, 'ptBR', 'Um trabalho adequadamente eficiente... ainda que tenha faltado alguma finesse. Pode retornar às suas atribuições normais.', '', 28153),
(156113, 'ptBR', 'Ah... o prazer de pôr um inimigo em seu devido lugar. Não é por ser trabalho que não se pode saborear um vitória!', '', 28153),
(156112, 'ptBR', 'Bom trabalho. Nossas operações podem seguir em frente conforme o planejado.', '', 28153),
(156111, 'ptBR', 'A Horda em breve reivindicará esta área, mas temos um inimigo poderoso em nosso caminho. Contribua com as nossas forças.', '', 28153),
(156110, 'ptBR', 'Os planos da Chefe Guerreira para esta área não incluem um... monstro. Acabe com a criatura!', '', 28153),
(156109, 'ptBR', '', 'Escuta aí, sabe-tudo... Você já parou para pensar que talvez a SUA linha do tempo seja a \"história alternativa\" e a MINHA seja a VERDADEIRA? Hehe...', 28153),
(156108, 'ptBR', 'Um inimigo notável está próximo de você. Traga um corpo para nossos pesquisadores estudarem... o que acha?', '', 28153),
(156107, 'ptBR', 'Um inimigo na área tem dizimado nossos recrutas café-com-leite. Acredito que um \"campeão da Horda\" terá melhores resultados.', '', 28153),
(156106, 'ptBR', '', 'Você travou uma guerra contra a Legião... mas não pensou em nos chamar? Sério? O destino de todo o universo estava na balança, mas você não podia... ah, que seja!', 28153),
(156105, 'ptBR', 'Relatórios indicam a presença de um inimigo poderoso numa posição próxima da sua. Acabe com ele... e não se esqueça de saborear o abate!', '', 28153),
(156104, 'ptBR', 'A Chefe Guerreira quer que você elimine um alvo nesta área. Não a decepcione.', '', 28153),
(156103, 'ptBR', '', 'Desde que cheguei na cidade, esses orcs de Orgrimmar parecem andar mais eretos.', 28153),
(156102, 'ptBR', '', 'Um orc verde disse que a cor dos meus olhos era \"magisTHRALL\"... então eu estilhacei a coluna dele.', 28153),
(156101, 'ptBR', 'Eu estava ficando com fome...', 'Eu estava ficando com fome...', 28153),
(156100, 'ptBR', '', 'Fale agora! Há batalhas a se ganhar!', 28153),
(156099, 'ptBR', '', 'O coração dos Mag\'har é puro e forte.', 28153),
(156098, 'ptBR', '', 'Estamos aqui para vencer essa guerra.', 28153),
(156097, 'ptBR', '', 'Ouvirei suas palavras... mas julgarei suas ações.', 28153),
(156096, 'ptBR', '', 'Nem consigo imaginar o que teria acontecido se tivéssemos permitido que elas continuassem com esses rituais. Obrigada pela ajuda.', 28153),
(156095, 'ptBR', '', 'Fale.', 28153),
(156094, 'ptBR', '', 'Verei os céus de Draenor mais uma vez.', 28153),
(156093, 'ptBR', '', 'Tudo que conhecemos é a guerra.', 28153),
(156092, 'ptBR', '', 'Que seus inimigos rastejem a seus pés.', 28153),
(156091, 'ptBR', '', 'As bruxas de Corlain parecem estar tentando um novo tipo de ritual. Detenha-as antes que isso vá longe demais!', 28153),
(156090, 'ptBR', '', 'Lutem com honra. Morram com glória!', 28153),
(156089, 'ptBR', '', 'A vitória será dos Mag\'har.', 28153),
(156088, 'ptBR', '', 'Morra bem.', 28153),
(156087, 'ptBR', '', 'Vá com honra.', 28153),
(156086, 'ptBR', '', 'Throm-ka!', 28153),
(156085, 'ptBR', '', 'Lok-tar!', 28153),
(156084, 'ptBR', 'Pobres pássaros.. Que seus espíritos voem livres para sempre.', '', 28153),
(156083, 'ptBR', 'Os falcões daqui foram amaldiçoados pelas bruxas. Eu gostaria de salvá-los, mas creio que seja impossível. Essas cebolas vão ajudar você a lidar com eles!', '', 28153),
(156082, 'ptBR', '', 'Bom trabalho. Quando a Aliança vai perceber que ninguém vai deter os Zandalari?', 28153),
(156081, 'ptBR', '', 'Você se saiu bem. A Aliança vai temer as forças dos Zandalari.', 28153),
(156080, 'ptBR', '', 'A Aliança logo vai aprender que ninguém vence os Zandalari.', 28153),
(156079, 'ptBR', '', 'Recebi notícias de que a Aliança está reunindo forças aqui por perto. Acaba com a festa deles.', 28153),
(156078, 'ptBR', '', 'A Aliança acha que pode desafiar o império Zandalari. Mostra que eles estão errados.', 28153),
(156077, 'ptBR', '', 'Certo, rapazes, hora do motim! Os Neblineiros se recusam a vender nossa liberdade!', 28153),
(156076, 'ptBR', '', 'No começo eu me aporrinhava com essa agachada de \"siiiiiiiiim, rainha\". Mas, vá lá... permitirei que tu prossigas!', 28153),
(156075, 'ptBR', '', 'A Aliança tá tramando alguma coisa por aqui. Acaba com eles. Faz eles sentirem medo dos Zandalari.', 28153),
(156074, 'ptBR', 'Podemos descansar um pouco melhor, agora que o problema foi resolvido.', '', 28153),
(156073, 'ptBR', 'Os soldados que lutam pela Aliança não vão esquecer o que você fez hoje.', '', 28153),
(156072, 'ptBR', 'Você se saiu muito bem. Eu tenho que lhe contar umas histórias da Terceira Guerra. Isso me fez lembrar daquela época.', '', 28153),
(156071, 'ptBR', 'Bom trabalho. Esses recursos vão ser de grande ajuda a longo prazo.', '', 28153),
(156070, 'ptBR', 'Esta área está dando trabalho pras nossas forças. Me lembra da Segunda Guerra. Você pode dar uma ajuda?', '', 28153),
(156069, 'ptBR', 'Andamos tendo problemas nas imediações. Você pode cuidar disso?', '', 28153),
(156068, 'ptBR', '', 'Mas decerto que eu tenho uma relação embretada com meu velho. Já é difícil se dar bem com os pais, ainda mais um feito de diamante!', 28153),
(156067, 'ptBR', 'A área aí por perto pode ser de grande utilidade pra nós. Temos que garantir que ela fique segura.', '', 28153),
(156066, 'ptBR', 'Recebemos informações de que tem recursos vitais pelas redondezas. Eles vão ajudar a gente a virar o jogo.', '', 28153),
(156065, 'ptBR', '', 'Vai em frente... faz uma piada de anão. Vamos ver se tu vai gostar de ficar sem teu joelho!', 28153),
(156064, 'ptBR', 'Não corta a minha onda.', '', 28153),
(156063, 'ptBR', 'O que você está fazendo aqui?', 'O que você está fazendo aqui?', 28153),
(156062, 'ptBR', '', 'Kiro e eu só estamos de passagem. Próxima parada, o Império Ímpio. \n\nMeu plano está pronto. \n\nOs sethraks serão pegos de surpresa.', 28153),
(156061, 'ptBR', '', 'Então nos encontramos de novo.', 28153),
(156060, 'ptBR', 'Você honra os homens da 7ª Legião que sucumbiram. Faremos bom uso desta área.', '', 28153),
(156059, 'ptBR', 'Você se saiu bem. Deixe o resto com meus soldados.', '', 28153),
(156058, 'ptBR', '', 'Meu povo mora dentro de um vulcão. Continua me cutucando e eu vou te mostrar a erupção dos Ferro Negro!', 28153),
(156057, 'ptBR', 'Excelente tática. Vamos poder usar essa área em breve.', '', 28153),
(156056, 'ptBR', 'Excelente trabalho. Esses recursos vão manter a 7ª Legião por um bom tempo.', '', 28153),
(156055, 'ptBR', 'Precisamos da sua ajuda para proteger esta área. Minhas forças não vão conseguir tomá-la sozinhas.', '', 28153),
(156054, 'ptBR', 'Vários dos meus soldados sucumbiram tentando tomar a área próxima. Faça dela um lugar seguro.', '', 28153),
(156053, 'ptBR', 'Os batedores da 7ª Legião determinaram que este local é de extrema importância. Ajude-nos a fazer uso dele.', '', 28153),
(156052, 'ptBR', '', 'Os Três Martelos lutam como um.', 28153),
(156051, 'ptBR', 'A 7ª Legião requer recursos localizados aqui por perto. Proteja-os custe o que custar.', '', 28153),
(156050, 'ptBR', '', 'Que teu martelo seja certeiro.', 28153),
(156049, 'ptBR', '', 'Que a Bigorna Negra te proteja.', 28153),
(156048, 'ptBR', '', 'Os Ferro Negro reivindicarão seu lugar de direito neste mundo.', 28153),
(156047, 'ptBR', '', 'Bem, fala logo. Estou pegada na faina!', 28153),
(156046, 'ptBR', '', 'Tu podes sair.', 28153),
(156045, 'ptBR', '', 'Eu te dispenso.', 28153),
(156044, 'ptBR', 'Bombardeiem meu alvo!', 'Bombardeiem meu alvo!', 28153),
(156043, 'ptBR', 'Canhões! Fogo!', 'Canhões! Fogo!', 28153),
(156042, 'ptBR', 'Alvo marcado para destruição!', 'Alvo marcado para destruição!', 28153),
(156041, 'ptBR', 'Artilharia! Fogo no meu alvo!', 'Artilharia! Fogo no meu alvo!', 28153),
(156040, 'ptBR', '', 'Vamos ao que interessa, então.', 28153),
(156039, 'ptBR', '', 'Então? Estou ouvindo.', 28153),
(156038, 'ptBR', '', 'É melhor você se comportar na presença de uma rainha.', 28153),
(156037, 'ptBR', 'É bom ver que as areias ainda não engoliram você.', '', 28153),
(156036, 'ptBR', '', 'A montanha nos concede sua força.', 28153),
(156035, 'ptBR', '', 'Você está se dirigindo à Rainha Regente do clã Ferro Negro.', 28153),
(156034, 'ptBR', '', 'O clã Ferro Negro terá o respeito que merece.', 28153),
(156033, 'ptBR', '', 'A Aliança precisa de nossa feitiçaria, assim como de nossa força.', 28153),
(156032, 'ptBR', 'Vestindo-se', 'Vestindo-se', 28153),
(156031, 'ptBR', 'Limpando', 'Limpando', 28153),
(156030, 'ptBR', '', 'Excelente trabalho. Esses recursos vão ajudar muito os Zandalari.', 28153),
(156029, 'ptBR', '', 'Impressionante. Todo mundo vai saber que não é uma boa se meter com o império Zandalari.', 28153),
(156028, 'ptBR', '', 'Mais uma vitória da Horda. Acho que dá pra me acostumar com você dando uma força.', 28153),
(156027, 'ptBR', '', 'Os Zandalari agradecem seus esforços.', 28153),
(156026, 'ptBR', '', 'Nathanos acha que a gente não dá conta dessa área. Prova que ele está redondamente enganado.', 28153),
(156025, 'ptBR', '', 'A área no seu entorno tem que ser liberada pra nossa campanha continuar. Vai lá e faz o que você faz de melhor.', 28153),
(156024, 'ptBR', '', 'A gente tem que deixar essa área segura pros nossos aliados. Não tenha piedade nenhuma de quem tentar te impedir.', 28153),
(156023, 'ptBR', '', 'Tem recursos nas redondezas que vão ser úteis para nossa campanha. Traz eles pra gente.', 28153),
(156022, 'ptBR', 'Biriba e Boneca vão devorar isso num instante.', '', 28153),
(156021, 'ptBR', 'Quando Biriba e Boneca empacam, pode esquecer. Esses bichos não trabalham de barriga vazia de jeito nenhum. Tente encontrar alguma coisa pra eles comerem.', '', 28153),
(156020, 'ptBR', 'Xô!', 'Xô!', 28153),
(156019, 'ptBR', 'Vai embora!', 'Vai embora!', 28153),
(156018, 'ptBR', 'Não encosta não!', 'Não encosta não!', 28153),
(156017, 'ptBR', 'Se chegar mais perto, eu te amassa a cabeça com pedra!', 'Se chegar mais perto, eu te amassa a cabeça com pedra!', 28153),
(156016, 'ptBR', 'Sai fora, senão eu te mata!', 'Sai fora, senão eu te mata!', 28153),
(156015, 'ptBR', '', 'Vai. Arranja o que for preciso pra curar esse homem-cobra. Eu vou contar pra Julwaba o que a gente tá sabendo.', 28153),
(156014, 'ptBR', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|aNova construção disponível!', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|aNova construção disponível!', 28153),
(156013, 'ptBR', 'Servi muitos chefes guerreiros. Viaje um pouco pelo mundo. Você sem dúvida encontrará vários deles.', '', 28153),
(156012, 'ptBR', 'Por que continua me importunando? Há outra guerra a se travar? O que estou dizendo... SEMPRE há outra guerra a se travar.', '', 28153),
(156011, 'ptBR', 'Se você soubesse quanto sangue já sujou meu machado, não me incomodaria com tanta displicência!', '', 28153),
(156010, 'ptBR', 'Não tenho mais idade para essas bobagens.', '', 28153),
(156009, 'ptBR', 'Eu sirvo à Horda.', '', 28153),
(156008, 'ptBR', 'Fale rápido... e fale a verdade.', '', 28153),
(156007, 'ptBR', 'Agora não é hora para cordialidades.', '', 28153),
(156006, 'ptBR', 'O que você requer de mim?', '', 28153),
(156005, 'ptBR', 'Throm-ka!', '', 28153),
(156004, 'ptBR', 'Lok-tar!', '', 28153),
(156003, 'ptBR', 'Eu sou Saurfang. Irmão de Broxigar.', '', 28153),
(156002, 'ptBR', 'A Horda resistirá.', '', 28153),
(156001, 'ptBR', 'Eu não gosto mais disso não. Hora de vazar!', 'Eu não gosto mais disso não. Hora de vazar!', 28153),
(156000, 'ptBR', 'Em combate, ter estratégia é tão importante quanto ter força.', '', 28153),
(155999, 'ptBR', 'Oba! Tô livre!', 'Oba! Tô livre!', 28153),
(155998, 'ptBR', 'Eu vai cair fora!', 'Eu vai cair fora!', 28153),
(155997, 'ptBR', 'Nós somos o verdadeiro poder de Kalimdor.', '', 28153),
(155996, 'ptBR', 'Por que isso acontecendo?', 'Por que isso acontecendo?', 28153),
(155995, 'ptBR', 'Eu não vai morrer, protege eu!', 'Eu não vai morrer, protege eu!', 28153),
(155994, 'ptBR', 'O que tá acontecendo!?!', 'O que tá acontecendo!?!', 28153),
(155993, 'ptBR', 'Cuidado, tem humano maluco pra todo lado!', 'Cuidado, tem humano maluco pra todo lado!', 28153),
(155992, 'ptBR', 'Se puder, não envelheça...', '', 28153),
(155991, 'ptBR', 'Se não temos honra, não temos nada.', '', 28153),
(155990, 'ptBR', 'Morrer hoje, no campo de batalha, é morrer como um orc.', '', 28153),
(155989, 'ptBR', 'Que você morra em batalha contra um inimigo odiado.', '', 28153),
(155988, 'ptBR', 'Veja se consegue ajudar Loh a chegar até a segurança das algas.', '', 28153),
(155987, 'ptBR', '\"Loh e o Mar.\" Um jovem tortollano tem que chegar à segurança logo após emergir das areias.', '', 28153),
(155986, 'ptBR', '', 'As forças das bruxas foram rechaçadas, e os trabalhadores podem voltar. Obrigada por tê-los defendido.', 28153),
(155985, 'ptBR', 'Vou só apagar isso aqui...', '', 28153),
(155984, 'ptBR', '', 'As bruxas mandaram lacaios para tomar o controle das nossas madeireiras. Junte os lenhadores e queimem essas bruxas!', 28153),
(155983, 'ptBR', '', 'A Clareira do Flecheiro está livre da influência do conventículo. Muito obrigada.', 28153),
(155982, 'ptBR', '', 'A Clareira do Flecheiro foi tomada pelo conventículo! Liberte os cidadãos e recupere a cidade!', 28153),
(155981, 'ptBR', 'Pssst... por aqui, $n!', '', 28153),
(155980, 'ptBR', '', 'Temos que lutar pelo que é certo.', 28153),
(155979, 'ptBR', '', 'Quando a hora chegar, eu estarei lá.', 28153),
(155978, 'ptBR', '', 'Cuide logo disso.', 28153),
(155977, 'ptBR', '', 'Temos que ajudar quem não pode cuidar de si.', 28153),
(155976, 'ptBR', '', 'Sem honra, não somos nada.', 28153),
(155975, 'ptBR', '', 'Se você contar o que aconteceu a UMA SÓ PESSOA, darei você de comer para o meu grifo. Entendido?!', 28153),
(155974, 'ptBR', '', 'Eu vou lutar até o fim.', 28153),
(155973, 'ptBR', '', '<bufa> Ah, não... V-você não ouviu isso.', 28153),
(155972, 'ptBR', '', 'Eu sou... uma escudeira... altamente disciplinada... com força de vontade férrea...', 28153),
(155971, 'ptBR', '', 'Pare, isso faz cócegas! Chega!', 28153),
(155970, 'ptBR', '', 'Ei! Pare com isso!', 28153),
(155969, 'ptBR', '', 'Nós vamos conseguir.', 28153),
(155968, 'ptBR', '', 'Sirva com honra.', 28153),
(155967, 'ptBR', '', 'Siga a rota.', 28153),
(155966, 'ptBR', '', 'Ventos às costas, amigos. Mas minha luta é aqui, lado a lado com os vulperas.', 28153),
(155965, 'ptBR', '', 'Volte com histórias!', 28153),
(155964, 'ptBR', '', 'Por Kul Tiraz!', 28153),
(155963, 'ptBR', '', 'O dever chama.', 28153),
(155962, 'ptBR', '', 'Adeus.', 28153),
(155961, 'ptBR', '', 'Qual é a situação?', 28153),
(155960, 'ptBR', '', 'Finalmente, um pouco de ação!', 28153),
(155959, 'ptBR', '', 'Eu treinei a minha vida inteira para este momento.', 28153),
(155956, 'ptBR', '', 'Juntos podemos unificar Kul Tiraz.', 28153),
(155955, 'ptBR', '', 'Sempre sonhei com aventuras.', 28153),
(155953, 'ptBR', 'Lar é onde o vale está.', '', 28153),
(155952, 'ptBR', 'Eu te protejo, se você também me proteger.', '', 28153),
(155950, 'ptBR', 'Tome cuidado lá fora.', '', 28153),
(155947, 'ptBR', 'Estamos nisto juntos.', '', 28153),
(155946, 'ptBR', '', 'Atualização. Impacto da recriação está se aproximando do poder máximo.', 28153),
(155945, 'ptBR', '', 'Atenção. Impacto da recriação está se aproximando da capacidade máxima.', 28153),
(155944, 'ptBR', '', 'Atenção. Poder total iminente.', 28153),
(155943, 'ptBR', '', 'Atualização. Nível de poder perto do máximo.', 28153),
(155942, 'ptBR', 'Não tem nada que um dia de trabalho duro não resolva.', '', 28153),
(155941, 'ptBR', 'Meu coração pertence a este vale.', '', 28153),
(155939, 'ptBR', '', 'Como posso ajudar?', 28153),
(155938, 'ptBR', 'Ouviu isso? As profundezas sussurram algo em meus ouvidos. É... é sobre você! O quê? Arrã. Entendo. Elas disseram: \"Pare de clicar no Pique, seu monstro.\" Incrível!', '', 28153),
(155937, 'ptBR', 'Ah, é muito útil para um monte de coisas!$b$bAlém do uso óbvio como objeto pontiagudo de perfuração, os espinhos também têm várias outras propriedades relevantes. Se você macerar até virar um pó fino, serve como adesivo. Você pode ferver e usar o óleo para limpeza. E, em caso de necessidade, dá para usar como palito de dente!', '', 28153),
(155936, 'ptBR', 'Vou ter que matar você e esses seus amigos palermas com minhas próprias mãos!', '', 28153),
(155935, 'ptBR', 'Tongo... morto por alguém de fora? Acho que superestimei a força dele!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155934, 'ptBR', 'Não desse jeito... não... argghh...', '', 28153),
(155933, 'ptBR', 'Jurei manter a paz nestas terras. Por você, estou disposto a abrir uma exceção.', '', 28153),
(155932, 'ptBR', 'Incomode o quanto quiser. A paciência de um Sábio das Marés é lendária.', '', 28153),
(155931, 'ptBR', '', 'Saudações!', 28153),
(155930, 'ptBR', 'E para que servem esses espinhos, aliás?', 'E para que servem esses espinhos, aliás?', 28153),
(155929, 'ptBR', 'Oferecendo', 'Oferecendo', 28153),
(155928, 'ptBR', 'Você bebeu, foi? E nem pensou em dividir? Magoei.', '', 28153),
(155927, 'ptBR', 'Calma aí. Eu sei que sou bonito, mas temos trabalho a fazer.', '', 28153),
(155926, 'ptBR', 'Bem, a menos que você tenha sido obrigado a entrar na marinha... ou capturado por piratas... e DEPOIS ter sido capturado pela marinha...', '', 28153),
(155925, 'ptBR', 'Ah, o mar aberto. Uma cantiga nos lábios. O vento batendo no cabelo do peito. ISSO é que é liberdade.', '', 28153),
(155924, 'ptBR', 'Não olhe para trás.', '', 28153),
(155923, 'ptBR', 'De olho no horizonte.', '', 28153),
(155922, 'ptBR', 'A próxima rodada é por minha conta.', '', 28153),
(155921, 'ptBR', 'Vamos lá receber.', '', 28153),
(155920, 'ptBR', 'Te vejo por aí.', '', 28153),
(155919, 'ptBR', '<A respiração do Rei Rastakhan é curta e pesada. As bandagens em seu peito estão encharcadas de sangue.>', '', 28153),
(155918, 'ptBR', 'Tome cuidado por essas bandas.', '', 28153),
(155917, 'ptBR', 'Não deixe a pólvora molhar.', '', 28153),
(155916, 'ptBR', 'O que você me conta?', '', 28153),
(155915, 'ptBR', 'Excelente! Vou começar a fazer o que precisamos imediatamente. Tenho certeza de que os pescadores locais também vão aprovar a redução na revoada.', '', 28153),
(155914, 'ptBR', 'Eu sou Jamil Abul\'housin, o Médico Real. Essa não é a primeira vez que eu cuido do Rei, e os loas não deixarão que seja a última.', '', 28153),
(155913, 'ptBR', 'Preciso de componentes dos peixes e caranguejos locais. Infelizmente, as gaivotas também estão atrás deles. Obtenha os suprimentos de que preciso e acabe com alguns desses pássaros!', '', 28153),
(155912, 'ptBR', 'Como vai o tratamento?', 'Como vai o tratamento?', 28153),
(155911, 'ptBR', 'Sim... sim! Que esta terra estremeça ante a força da Horda!', '', 28153),
(155910, 'ptBR', 'A gente já passou por muita coisa juntos, eu e o velho Rastakhan...\n\n<Jamil aponta para o corpo alquebrado do Rei.>\n\nEle tá mal.', '', 28153),
(155909, 'ptBR', '<Jol não tira os olhos das suas misturas.>\n\nO tempo do Rei tá acabando.', '', 28153),
(155908, 'ptBR', 'Serviço é serviço, camarada.', '', 28153),
(155907, 'ptBR', 'Isso deve bastar. Uma pena essa ameaça não poder ser usada como arma contra os nossos inimigos.', '', 28153),
(155906, 'ptBR', 'Há um inimigo poderoso aqui perto que se mostrou... problemático para as nossas forças. Estou certo de que você sabe o que deve ser feito.', '', 28153),
(155905, 'ptBR', 'A Chefe Guerreira vai ficar satisfeita com seu sucesso.', '', 28153),
(155904, 'ptBR', 'Um inimigo perigoso espreita as redondezas. Elimine-o antes que ele atrapalhe nossos planos.', '', 28153),
(155903, 'ptBR', 'As forças inimigas nesta área são um obstáculo para os nossos planos. A Chefe Guerreira espera que esse problema seja resolvido. Não a decepcione.', '', 28153),
(155902, 'ptBR', 'Como Rhenik foi deixar isso acontecer?!', 'Como Rhenik foi deixar isso acontecer?!', 28153),
(155901, 'ptBR', 'De novo não!', 'De novo não!', 28153),
(155900, 'ptBR', 'Alguém vai pagar por isso!', 'Alguém vai pagar por isso!', 28153),
(155899, 'ptBR', 'Por que sempre destroem o grogue?!', 'Por que sempre destroem o grogue?!', 28153),
(155898, 'ptBR', 'O grogue não!', 'O grogue não!', 28153),
(155897, 'ptBR', 'Sangue ou ouro, tudo tem um custo.', '', 28153),
(155896, 'ptBR', 'Bem, não é isso que acontece na história. Que tal tentar de novo?', '', 28153),
(155895, 'ptBR', 'Você está com sede? Eu estou com sede.', '', 28153),
(155894, 'ptBR', 'Sou todo ouvidos.', '', 28153),
(155893, 'ptBR', 'Novidades?', '', 28153),
(155892, 'ptBR', 'Io-hô.', '', 28153),
(155891, 'ptBR', 'Toma cuidado lá fora.', '', 28153),
(155890, 'ptBR', 'Até a próxima.', '', 28153),
(155889, 'ptBR', 'Saúde!', '', 28153),
(155888, 'ptBR', 'Grogue ou cerva? Ou os dois?', '', 28153),
(155887, 'ptBR', 'O que é que vai ser?', '', 28153),
(155886, 'ptBR', 'Muito bem, $n!', '', 28153),
(155885, 'ptBR', 'O que posso fazer por você?', '', 28153),
(155884, 'ptBR', 'Você consegue levar Loh até todos os alimentos da ilha, depois de volta para a cabana, sem cruzar o caminho dele?', '', 28153),
(155883, 'ptBR', '\"Uma vida simples\". Um dia Loh decidiu viver uma vida tranquila, em uma ilha remota.', '', 28153),
(155882, 'ptBR', 'Sabe como a gente chamava cadetes feito você na Segunda Guerra? Cracas... Quando colam no seu traseiro, não desgrudam mais!', '', 28153),
(155881, 'ptBR', 'Não raro, as viagens de Loh traziam muitos perigos. Veja esta história, por exemplo...', '', 28153),
(155880, 'ptBR', 'Nós, tortollanos, adoramos a história de Loh, um jovem tortollano que viajou pelo mundo.', '', 28153),
(155879, 'ptBR', 'O que você quer, uma história de guerra?', '', 28153),
(155878, 'ptBR', 'No MEU tempo, a gente sabia quando uma conversa tinha acabado.', '', 28153),
(155877, 'ptBR', '', 'O ciclo da vida pode ser cruel...', 28153),
(155876, 'ptBR', '', 'Uma tartaruga chegou à água!', 28153),
(155875, 'ptBR', '', 'Muito obrigada, $n!', 28153),
(155874, 'ptBR', '', 'Os tortollanos começam a vida em meio a grande perigo, como as tartarugas desta praia. Proteja-as, para que cheguem em segurança ao oceano!', 28153),
(155873, 'ptBR', '', 'Bom trabalho! A máquina não foi feita para isso, mas acabou servindo mais que bem.', 28153),
(155872, 'ptBR', '', 'Se não estiverem com distintivo, podem matar à vontade!', 28153),
(155871, 'ptBR', '', 'Quem foi o idiota que perdeu as caixas com as bombas?', 28153),
(155870, 'ptBR', '', 'Homens de Brado de Arom conseguiram fazer a máquina de mineração funcionar. Use ela contra os próprios criadores!', 28153),
(155869, 'ptBR', '', 'Eu posso eliminar você da lista de funcionários para reduzir os custos!', 28153),
(155868, 'ptBR', '', 'Vou ter que fazer alguns cortes para fechar as contas.', 28153),
(155867, 'ptBR', 'Intrusos na fundição! Repito: INTRU...', 'Intrusos na fundição! Repito: INTRU...', 28153),
(155866, 'ptBR', 'Que a honra te guie.', '', 28153),
(155865, 'ptBR', 'Pela Lorde-almirante.', '', 28153),
(155864, 'ptBR', 'Por Kul Tiraz.', '', 28153),
(155863, 'ptBR', 'Não deixe te verem tremer nas bases!', '', 28153),
(155862, 'ptBR', 'Sempre alerta.', '', 28153),
(155861, 'ptBR', 'Bons ventos e mares tranquilos.', '', 28153),
(155860, 'ptBR', 'Debandar!', '', 28153),
(155859, 'ptBR', '', '', 28153),
(155858, 'ptBR', '', '', 28153),
(155857, 'ptBR', 'Fale!', '', 28153),
(155856, 'ptBR', '', '', 28153),
(155855, 'ptBR', 'Eu já vi guerra suficiente pra nós dois.', '', 28153),
(155854, 'ptBR', 'Notícias do front?', '', 28153),
(155853, 'ptBR', 'Do que você precisa?', '', 28153),
(155852, 'ptBR', 'Esses ossos velhos ainda anseiam pela batalha.', '', 28153),
(155851, 'ptBR', 'Alguma coisa pra informar?', '', 28153),
(155850, 'ptBR', 'Saudações!', '', 28153),
(155849, 'ptBR', '', 'Não peça nada a ninguém.', 28153),
(155848, 'ptBR', '', 'Ao vento e ao mar, permanecemos livres.', 28153),
(155847, 'ptBR', '', 'Kul Tiraz há de superar qualquer tempestade.', 28153),
(155846, 'ptBR', '', 'Eu estou ouvindo.', 28153),
(155845, 'ptBR', '', 'Diga suas intenções.', 28153),
(155844, 'ptBR', 'Precisamos prosseguir.', '', 28153),
(155843, 'ptBR', 'Não tema a correnteza.', '', 28153),
(155842, 'ptBR', 'Que as correntezas te guiem.', '', 28153),
(155841, 'ptBR', 'Não esqueça os mortos.', '', 28153),
(155840, 'ptBR', 'Olhos para o mar.', '', 28153),
(155839, 'ptBR', '', 'Não tenho o menor interesse em jogar conversa fora.', 28153),
(155838, 'ptBR', 'A tempestade desperta em todos nós.', '', 28153),
(155837, 'ptBR', 'Estou aqui para duelar.', 'Estou aqui para duelar.', 28153),
(155836, 'ptBR', 'Não deu. Tente outra vez.', '', 28153),
(155835, 'ptBR', 'Ó, uma combinação!', '', 28153),
(155834, 'ptBR', 'Muito bem, $n!', '', 28153),
(155833, 'ptBR', 'Acabei juntando muita coisa ao longo dos anos. Veja se consegue fazer combinações.', '', 28153),
(155832, 'ptBR', 'Claro, se você gostar de correr. Se quiser voar, fala com Pa\'kul, a loa dos ventos. Ela tem poucos totens, mas eles funcionam como atalhos pra voar pela cidade.', '', 28153),
(155831, 'ptBR', '', 'Gonk, o mestre das formas e senhor da caçada, é um loa poderoso. Ele pode lhe dar acesso aos seus muitos totens espalhados pela cidade que aumentarão sua velocidade só de estar perto deles.', 28153),
(155830, 'ptBR', 'As profundezas avisaram de sua chegada.', '', 28153),
(155829, 'ptBR', 'Estou ouvindo.', '', 28153),
(155828, 'ptBR', 'Você precisa de mim?', '', 28153),
(155827, 'ptBR', 'Que o mar te abençoe.', '', 28153),
(155826, 'ptBR', 'Levantem as pranchas, vamos zarpar imediatamente. A última coisa de que preciso é de buracos no meu navio.', '', 28153),
(155825, 'ptBR', 'Pelo jeito também estão atrás da azerita. Espertos, muito espertos, mas não rápidos o bastante para nos alcançar. Vamos andando antes de chamar a atenção deles.', '', 28153),
(155824, 'ptBR', 'E por hoje é só pessoal. Parece que limpamos a ilha e na hora certa. Tem um navio Zandalari no horizonte.', '', 28153),
(155823, 'ptBR', 'E eles também estão coletando azerita. Bom, que conveniente. Basta matá-los e saquear tudo.', '', 28153),
(155822, 'ptBR', 'Hozens? Aqui? Hm, acho que a gente nunca sabe quem vai aparecer nessas ilhas.', '', 28153),
(155821, 'ptBR', 'Acabamos de avistar uma carga enorme de azerita. Essa vai ser boa.', '', 28153),
(155820, 'ptBR', 'Boa. Quer dizer, é sangrento e nojento, mas fazer o quê? Azerita é azerita.', '', 28153),
(155819, 'ptBR', 'Uau, que monstrão! E está totalmente coberto de resíduo de azerita. Vocês matam o monstro, eu extraio a azerita.', '', 28153),
(155818, 'ptBR', 'Muito bem, o detector está apontando para outra fonte de azerita próxima à sua posição. Deem uma olhada.', '', 28153),
(155817, 'ptBR', 'Aêê! Que belo carregamento. Bom trabalho!', '', 28153),
(155816, 'ptBR', 'Uau, isso que é pedaço de azerita. Extraiam essa belezinha e vamos levar os estilhaços de volta para o navio agora mesmo.', '', 28153),
(155815, 'ptBR', 'Nosso detector de azerita está mostrando que há uma fonte de... bem, azerita, perto daqui. Por que vocês não vão lá investigar? E eu? bom, eu vou ficar aqui.', '', 28153),
(155814, 'ptBR', 'Vamos nos aproximar. Tente não bater em nada. E abaixe as pranchas, obrigado.', '', 28153),
(155813, 'ptBR', 'Sabe, também podia ter, tipo, aranhas gigantes aqui. Só estou falando, nunca se sabe.', '', 28153),
(155812, 'ptBR', 'Eu tô quase certo de que esse é o lugar. Era para ter muita azerita por aqui.', '', 28153),
(155811, 'ptBR', '$n! Graças à Dama Sombria você chegou! Rexxar arrastou um monte de kultirenos pra dentro daquelas construções. Ele precisa de ajuda!', '$n! Graças à Dama Sombria você chegou! Rexxar arrastou um monte de kultirenos pra dentro daquelas construções. Ele precisa de ajuda!', 28153),
(155810, 'ptBR', 'Depressa, vá para o convés inferior e pegue uma arma! Temos que ajudar nossas tropas!', '', 28153),
(155809, 'ptBR', 'Sobrou apenas isso de Vadekius. Era um dragão poderoso.', 'Sobrou apenas isso de Vadekius. Era um dragão poderoso.', 28153),
(155808, 'ptBR', 'Mas não se anime muito, não.', 'Mas não se anime muito, não.', 28153),
(155807, 'ptBR', 'Só um poder imenso e muito sombrio poderia tê-lo matado.', 'Só um poder imenso e muito sombrio poderia tê-lo matado.', 28153),
(155806, 'ptBR', 'Sobrou apenas isso de Vadekius. Era um dragão poderoso.', 'Sobrou apenas isso de Vadekius. Era um dragão poderoso.', 28153),
(155805, 'ptBR', 'Mas já é um começo.', 'Mas já é um começo.', 28153),
(155804, 'ptBR', 'Meu coração não é grande como o da minha rainha.', 'Meu coração não é grande como o da minha rainha.', 28153),
(155803, 'ptBR', 'O que você fez a Kyranastrasz não é algo que eu perdoarei facilmente.', 'O que você fez a Kyranastrasz não é algo que eu perdoarei facilmente.', 28153),
(155802, 'ptBR', 'Acho que devo agradecer, não é?', 'Acho que devo agradecer, não é?', 28153),
(155801, 'ptBR', 'Agradeço-lhe pela ajuda, $n.', 'Agradeço-lhe pela ajuda, $n.', 28153),
(155800, 'ptBR', 'Não queremos que esses acontecimentos terríveis se repitam.', 'Não queremos que esses acontecimentos terríveis se repitam.', 28153),
(155799, 'ptBR', 'Para achar o lugar onde ele repousa, o Senhor da Morte invadiu nosso Santuário Rubi.', 'Para achar o lugar onde ele repousa, o Senhor da Morte invadiu nosso Santuário Rubi.', 28153),
(155798, 'ptBR', 'Durante a guerra contra a Legião, um dos nossos foi reanimado como criatura morta-viva.', 'Durante a guerra contra a Legião, um dos nossos foi reanimado como criatura morta-viva.', 28153),
(155797, 'ptBR', 'Então, $n e eu cuidaremos disso. Venha, $c, eu levarei você ao lugar do ritual.', 'Então, $n e eu cuidaremos disso. Venha, $c, eu levarei você ao lugar do ritual.', 28153),
(155796, 'ptBR', '', '$n retornou da missão. Talvez possa ajudar você, Zallestrasza.', 28153),
(155795, 'ptBR', 'Vocês estão fazendo muito barulho por nada. Já estou me sentindo bem melhor.', 'Vocês estão fazendo muito barulho por nada. Já estou me sentindo bem melhor.', 28153),
(155794, 'ptBR', 'Fique onde está que eu ajudo com a cura.', 'Fique onde está que eu ajudo com a cura.', 28153),
(155793, 'ptBR', 'Você mal consegue ficar sentado, Téo!', 'Você mal consegue ficar sentado, Téo!', 28153),
(155792, 'ptBR', '', 'Muito bem, $n! Vamos entrar no meu novo escritório.', 28153),
(155791, 'ptBR', '', 'Esse abate era meu. Estou contando para chegar a mil!', 28153),
(155790, 'ptBR', 'Precisarei de um poder incrível para enfrentar Korthek em combate. Ele sempre foi melhor de luta do que eu.\n\nDrenarei tudo que eu puder desses cristais, e vamos rezar para que baste.', '', 28153),
(155789, 'ptBR', '', 'As aranhas foram reduzidas a um número mais seguro. Nosso povo já pode cruzar a floresta sem o risco de ficar preso nas teias.', 28153),
(155788, 'ptBR', '', 'Essa selva está infestada de aranhas terríveis que ameaçam os caçadores de Drustvar. Taque fogo nelas!', 28153),
(155787, 'ptBR', 'Trocando', 'Trocando', 28153),
(155786, 'ptBR', '', 'Bom trabalho. Esses suprimentos vão ajudar nossas forças a encarar o clima da área.', 28153),
(155785, 'ptBR', '', 'Os batedores disseram que esses humanos arrumaram um jeito de arranjar pelegos sem machucar os bichos. É estranho... mas eficiente.', 28153),
(155784, 'ptBR', 'Tem alguma coisa perversa perambulando pelo depósito de madeira. Tá perto demais de Boralus. Demais.', '', 28153),
(155783, 'ptBR', 'Um abate perfeito! O monstro tava com os dias contados desde quando deu as caras na costa kultirena.', '', 28153),
(155782, 'ptBR', 'Os Rompe-onda fisgaram alguma coisa grande. Eles precisam da sua ajuda.', '', 28153),
(155781, 'ptBR', 'Queimando', 'Queimando', 28153),
(155780, 'ptBR', 'A gente tá nessa junto. Eu não vou recuar!', 'A gente tá nessa junto. Eu não vou recuar!', 28153),
(155779, 'ptBR', 'Se eu morrer hoje... vou morrer lutando!', 'Se eu morrer hoje... vou morrer lutando!', 28153),
(155778, 'ptBR', 'Mojambo nunca vai me pegar com vida!', 'Mojambo nunca vai me pegar com vida!', 28153),
(155777, 'ptBR', 'Eu me recuso a me curvar para Mojambo e seu bando!', 'Eu me recuso a me curvar para Mojambo e seu bando!', 28153),
(155776, 'ptBR', 'Eu vou lutar até meu último suspiro!', 'Eu vou lutar até meu último suspiro!', 28153),
(155775, 'ptBR', 'Mojambo não vai levar a melhor contra a gente sem uma boa briga!', 'Mojambo não vai levar a melhor contra a gente sem uma boa briga!', 28153),
(155774, 'ptBR', 'A batalha está chegando. Pegue esta espada e fique alerta.', 'A batalha está chegando. Pegue esta espada e fique alerta.', 28153),
(155773, 'ptBR', 'Aqui é o nosso lar. Não seremos expulsos sem lutar.', 'Aqui é o nosso lar. Não seremos expulsos sem lutar.', 28153),
(155772, 'ptBR', '', 'Bom trabalho! Um problema a menos para os fuzileiros se preocuparem.', 28153),
(155771, 'ptBR', '', 'Que abate! Sinto que eu poderia aprender muito observando você lutar.', 28153),
(155770, 'ptBR', '', 'As estradas de Kul Tiraz estão mais seguras devido às suas ações no dia de hoje.', 28153),
(155769, 'ptBR', '', 'Os militares tiveram problemas com uma fera aqui no passado. Vamos resolver isso para eles!', 28153),
(155768, 'ptBR', '', 'Há uma fera cruel na área. Pelo bem de Kul Tiraz, não podemos ignorar essa ameaça!', 28153),
(155767, 'ptBR', '', 'Não podemos mais permitir que tal abominação semeie caos entre civis inocentes. Elimine-a!', 28153),
(155766, 'ptBR', 'Você não quer ver se eu estou na esquina?', 'Você não quer ver se eu estou na esquina?', 28153),
(155765, 'ptBR', 'Ei, tá olhando o quê?', 'Ei, tá olhando o quê?', 28153),
(155764, 'ptBR', 'Você está bem longe de casa, camarada!', 'Você está bem longe de casa, camarada!', 28153),
(155763, 'ptBR', 'À noite céu vermelho, deleite do marinheiro; de manhã céu vermelho, toma cuidado, marinheiro!', '', 28153),
(155762, 'ptBR', 'Eu quero um teleporte para G\'huun.', 'Eu quero um teleporte para G\'huun.', 28153),
(155761, 'ptBR', 'Eu quero um teleporte para Mythrax.', 'Eu quero um teleporte para Mythrax.', 28153),
(155760, 'ptBR', 'Eu quero um teleporte para Zul.', 'Eu quero um teleporte para Zul.', 28153),
(155759, 'ptBR', 'Eu quero um teleporte para o Elemental do Sangue.', 'Eu quero um teleporte para o Elemental do Sangue.', 28153),
(155758, 'ptBR', 'Eu quero um teleporte para Zek\'voz.', 'Eu quero um teleporte para Zek\'voz.', 28153),
(155757, 'ptBR', 'Eu quero um teleporte para a Devoradora Fétida.', 'Eu quero um teleporte para a Devoradora Fétida.', 28153),
(155756, 'ptBR', 'Eu quero um teleporte para a M.A.D.R.E.', 'Eu quero um teleporte para a M.A.D.R.E.', 28153),
(155755, 'ptBR', 'Saudações e obrigado por ajudar a testar Uldir!\n\nEu posso teleportar você diretamente para qualquer chefe que esteja disponível para teste.', 'Saudações e obrigada por ajudar a testar Uldir!\n\nEu posso teleportar você diretamente para qualquer chefe que esteja disponível para teste.', 28153),
(155754, 'ptBR', '', 'Meu gato sumiu.', 28153),
(155753, 'ptBR', 'Enfrente a tempestade que não puder evitar, e evite a tempestade que não puder enfrentar!', '', 28153),
(155752, 'ptBR', 'Lembra que o lado molhado é pra baixo!', '', 28153),
(155750, 'ptBR', 'Quer conhecer o Bwonsamdi?', '', 28153),
(155749, 'ptBR', 'Que vidinha triste essa sua de viver em terra.', '', 28153),
(155748, 'ptBR', 'Quando olhar pra Baía dos Reis e vir as chamas azuis abençoadas, lembra que hoje a maré virou graças a você! Foi uma grande vitória, $n. A frota pertence a Zandalar pra sempre!', '', 28153),
(155747, 'ptBR', 'Te boto pra andar na prancha sem hesitar.', '', 28153),
(155746, 'ptBR', 'Que suas velas sejam cheias de vento e sua alma, cheia de propósito!', '', 28153),
(155745, 'ptBR', 'A gente se vê!', '', 28153),
(155744, 'ptBR', 'Vá com os ventos! Os mares me chamam!', '', 28153),
(155743, 'ptBR', 'Se tu tá de boa na lagoa, é porque tu não aprendeu nada.', '', 28153),
(155742, 'ptBR', 'Bons ventos e mares tranquilos para você!', '', 28153),
(155741, 'ptBR', 'Que um dia as marés nos aproximem novamente!', '', 28153),
(155740, 'ptBR', 'Vá com os ventos! Encontre novos horizontes!', '', 28153),
(155739, 'ptBR', 'Está sentindo o sal no ar? Agora você está em casa.', '', 28153),
(155738, 'ptBR', 'Taz\'okun! Boas-vindas, viajante!', '', 28153),
(155737, 'ptBR', 'Missão cumprida... mas você podia ter deixado um rastro de sangue menos anêmico. Tente se sair melhor na próxima vez.', '', 28153),
(155736, 'ptBR', 'Issaê! É você!', '', 28153),
(155735, 'ptBR', 'A Chefe Guerreira ordena que você tome o controle desta área em nome da Horda. Use o método que achar apropriado... desde que alcance a vitória.', '', 28153),
(155734, 'ptBR', 'Um dia sem terra à vista é um bom dia!', '', 28153),
(155733, 'ptBR', 'Tudo pronto para a jornada épica?', '', 28153),
(155732, 'ptBR', 'Quero ir para Uldir (Raide).', 'Quero ir para Uldir (Raide).', 28153),
(155731, 'ptBR', 'Bom trabalho! Nossas aves vão encontrar um lugar mais seguro e agora temos menos inimigos com que nos preocupar.', '', 28153),
(155730, 'ptBR', 'Aguardo seu retorno ansiosamente!', '', 28153),
(155729, 'ptBR', 'Por favor, volte imediatamente!', '', 28153),
(155728, 'ptBR', 'Apontar!', 'Apontar!', 28153),
(155727, 'ptBR', 'Hmm, de novo...', '', 28153),
(155726, 'ptBR', 'Imagino que você tenha quebrado alguma coisa...', '', 28153),
(155725, 'ptBR', 'Posso ajudar?', '', 28153),
(155724, 'ptBR', 'Pois não, posso ajudar?', '', 28153),
(155723, 'ptBR', 'Protejam-se!!!', 'Protejam-se!!!', 28153),
(155722, 'ptBR', 'Sorte sua que eu curto a sua pessoa, porque eu vou consertar... de novo...', '', 28153),
(155721, 'ptBR', 'É mesmo? Empilhar todo o peso numa coisinha só acabou quebrando a coisinha? Quem teria imaginado...', '', 28153),
(155720, 'ptBR', 'Você não pode ser muito mais espert$Uo:a; que o meu martelo.', '', 28153),
(155719, 'ptBR', 'Acho muito que essa é a mesma coisa que eu consertei da última vez.', '', 28153),
(155718, 'ptBR', 'Queria que esses patetas parassem de quebrar as coisas.', '', 28153),
(155717, 'ptBR', 'Quero ir para a Mansão Capelo (Masmorra).', 'Quero ir para a Mansão Capelo (Masmorra).', 28153),
(155716, 'ptBR', 'Quero ir para Tol Dagor (Masmorra).', 'Quero ir para Tol Dagor (Masmorra).', 28153),
(155715, 'ptBR', 'Quero ir para o Cerco de Boralus (Masmorra).', 'Quero ir para o Cerco de Boralus (Masmorra).', 28153),
(155714, 'ptBR', 'Quero ir para o Santuário da Tempestade (Masmorra).', 'Quero ir para a Angra do Facão (Masmorra).', 28153),
(155713, 'ptBR', 'Quero ir para a Angra do Facão (Masmorra).', 'Quero ir para a Angra do Facão (Masmorra).', 28153),
(155712, 'ptBR', 'Pelas penas de Pluméria! Você me assustou!', '', 28153),
(155711, 'ptBR', 'Os enfeitiçados pelas bruxas roubaram nossas aves! Eliminem os lacaios delas e libertem os falcões!', '', 28153),
(155710, 'ptBR', 'Precisa de alguma engenhoca? Uma geringonça? Quem sabe uma traquitana?', '', 28153),
(155709, 'ptBR', 'Quero ir para a Terra Podre (Masmorra).', 'Quero ir para a Terra Podre (Masmorra).', 28153),
(155708, 'ptBR', 'Quero ir para A MEGAMINA (Masmorra).', 'Quero ir para A MEGAMINA (Masmorra).', 28153),
(155707, 'ptBR', 'Quero ir para o Templo de Sethraliss (Masmorra).', 'Quero ir para o Templo de Sethraliss (Masmorra).', 28153),
(155706, 'ptBR', 'Quero ir para o Repouso do Rei (Masmorra).', 'Quero ir para o Repouso do Rei (Masmorra).', 28153),
(155705, 'ptBR', 'Os Rompe-ondas estão preparados para tudo!', '', 28153),
(155704, 'ptBR', 'Nossos amigos emplumados estão livres da magia das bruxas mais uma vez.', '', 28153),
(155703, 'ptBR', 'As bruxas estão usando amuletos para enfeitiçar as aves assim que chocam! Livre-se dos amuletos e de todos os falcoeiros enfeitiçados que vir pela frente, antes que o problema se espalhe!', '', 28153),
(155702, 'ptBR', '', 'Vaza.', 28153),
(155701, 'ptBR', '', 'Eu tenho uma arma e não tenho medo de usá-la.', 28153),
(155700, 'ptBR', '', 'Cansei da sua cara.', 28153),
(155699, 'ptBR', '', 'Mostre-me uma fera e meus Rompe-ondas cuidarão dela.', 28153),
(155698, 'ptBR', '', 'Mufinho, seu treloso. Vem já aqui!', 28153),
(155697, 'ptBR', '', 'Aqui, gatinho, gatinho!', 28153),
(155696, 'ptBR', 'Eu quero ir para Atal\'Dazar (Masmorra).', 'Eu quero ir para Atal\'Dazar (Masmorra).', 28153),
(155695, 'ptBR', '', 'Avise quando quiser brincar com gente grande.', 28153),
(155694, 'ptBR', '', 'Tenho monstros para matar.', 28153),
(155693, 'ptBR', '', 'O que foi agora?', 28153),
(155692, 'ptBR', 'Missão cumprida, imagino eu? Ótimo. Eu comunicarei o êxito à Chefe Guerreira.', '', 28153),
(155691, 'ptBR', 'Saudações, e obrigado por ajudar a testar o Beta de Battle for Azeroth! \n\nEu posso teleportar você diretamente para vários raides e masmorras abertos para teste. Isso é só um teleporte, não um serviço de formação de grupos, então eu espero que você tenha um grupo pronto para enfrentar os desafios que os aguardam. Caso contrário, talvez seja uma boa ideia conferir nosso novo Localizador de Grupos para encontrar aliados.\n\nLembre-se de escolher a dificuldade que deseja testar antes de se teleportar, pois você não poderá sair facilmente se quiser mudá-la!', 'Saudações, e obrigada por ajudar a testar o Beta de Battle for Azeroth! \n\nEu posso teleportar você diretamente para vários raides e masmorras abertos para teste. Isso é só um teleporte, não um serviço de formação de grupos, então eu espero que você tenha um grupo pronto para enfrentar os desafios que os aguardam. Caso contrário, talvez seja uma boa ideia conferir nosso novo Localizador de Grupos para encontrar aliados.\n\nLembre-se de escolher a dificuldade que deseja testar antes de se teleportar, pois você não poderá sair facilmente se quiser mudá-la!', 28153),
(155690, 'ptBR', '$n (Horda) está marcado no seu mapa como |c00FFFF00|Hspell:272296|h[Assassino]|h|r! Mate essa pessoa para receber uma recompensa.', '$n (Horda) está marcado no seu mapa como |c00FFFF00|Hspell:272296|h[Assassino]|h|r! Mate esse alvo para receber uma recompensa.', 28153),
(155689, 'ptBR', '$n (Aliança) está marcado no seu mapa como |c00FFFF00|Hspell:272295|h[Assassino]|h|r! Mate essa pessoa para receber uma recompensa.', '$n (Aliança) está marcado no seu mapa como |c00FFFF00|Hspell:272295|h[Assassino]|h|r! Mate esse alvo para receber uma recompensa.', 28153),
(155688, 'ptBR', 'Precisamos conter as forças inimigas na área. Conto com você.', '', 28153),
(155687, 'ptBR', '', 'Nunca encontrei um monstro que eu não conseguisse derrotar.', 28153),
(155686, 'ptBR', 'Demorou demais para o meu gosto... mas o resultado foi aceitável. A campanha continua.', '', 28153),
(155685, 'ptBR', 'A Chefe Guerreira exige a posse de todos os recursos da área. Peguem o que é o nosso.', '', 28153),
(155684, 'ptBR', 'Já falei para não tocar no nome da minha irmã.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155683, 'ptBR', '', 'Faremos bom proveito desses suprimentos! Bom trabalho.', 28153),
(155682, 'ptBR', '', 'Você luta como sua irmã.', 28153),
(155681, 'ptBR', '', 'Nossa Ordem poderia se beneficiar dos recursos daqui. Controle a área para tirarmos proveito disso!', 28153),
(155680, 'ptBR', 'Como queira, mamãe...', '', 28153),
(155679, 'ptBR', '', 'Gatinho, cadê você?', 28153),
(155678, 'ptBR', '', 'Venha, Artur.', 28153),
(155677, 'ptBR', '', 'Marechal, faça-me a gentileza de levar a Lucília para os meus aposentos, depois de se livrar dessas pestes...', 28153),
(155676, 'ptBR', '', 'Você viu meu gato por aí?', 28153),
(155675, 'ptBR', '', 'Ora, Marechal, isso lá é jeito de tratar uma Lady? Eu deveria lhe ensinar bons modos.', 28153),
(155674, 'ptBR', '', 'Acha que consegue acompanhar?', 28153),
(155673, 'ptBR', 'Fique longe dela, sua bruxa desalmada!', '', 28153),
(155672, 'ptBR', '', 'Agradeça, garota! Além do seu pai estar vivo e passar bem, em breve ele será o regente de toda Kul Tiraz! Junte-se a nós, criança...', 28153),
(155671, 'ptBR', '', 'O que... O que você fez com ele?!', 28153),
(155670, 'ptBR', '', 'Fico tão feliz que tenha se juntado a nós, minha querida. Seu pai sentiu tanto a sua falta.', 28153),
(155669, 'ptBR', '', 'Mamãe? É... você?', 28153),
(155668, 'ptBR', '', 'Está longe o bastante.', 28153),
(155667, 'ptBR', 'Pelo que me disseram, tem a ver com aquelas caixas que a gente vem recebendo dos Grimpagris.', 'Pelo que me disseram, tem a ver com aquelas caixas que a gente vem recebendo dos Grimpagris.', 28153),
(155666, 'ptBR', 'A Capitã Rocha está muito irritada com alguma coisa.', 'A Capitã Rocha está muito irritada com alguma coisa.', 28153),
(155665, 'ptBR', 'Ainda bem que me escalaram pra trabalhar aqui fora.', 'Ainda bem que me escalaram pra trabalhar aqui fora.', 28153),
(155664, 'ptBR', 'O quê?! Isso é uma BOMBA? Achei que era um abacate.', '', 28153),
(155663, 'ptBR', '', 'Cuidado aí, João. Essa pólvora vai acabar arrancando a sua mão.', 28153),
(155662, 'ptBR', 'Subam as pranchas! Vamos zarpar! Bom trabalho.', '', 28153),
(155661, 'ptBR', 'Parece que eles também tão atrás da azerita. Vamos sair na surdina antes que notem a nossa presença. A gente precisa voltar e repassar a informação.', '', 28153),
(155660, 'ptBR', 'Isso é tudo. Parece que limpamos a ilha e na hora certa. Tem um navio kultireno aparecendo no horizonte.', '', 28153),
(155659, 'ptBR', 'Parece que também tão coletando azerita. Isso é bom pra gente... vai ficar tudo junto no mesmo lugar, rá! Podem ir lá, tomem tudo deles.', '', 28153),
(155658, 'ptBR', 'Hozens! Ha! Nunca se sabe quem vai aparecer nesses lugares.', '', 28153),
(155657, 'ptBR', 'A gente viu um montão de azerita logo adiante de onde vocês estão. Vão lá dar uma olhada agora.', '', 28153),
(155656, 'ptBR', 'Isso que é maré. Vamos encher nosso casco em duas brisas.', '', 28153),
(155655, 'ptBR', 'Isso é que é monstro cabuloso, e ainda por cima todo coberto de resíduo de azerita. Acabem com ele pra gente pegar o minério.', '', 28153),
(155654, 'ptBR', 'Parece que tem outra fonte de azerita perto de vocês. É melhor irem lá depois.', '', 28153),
(155653, 'ptBR', 'Muito bem, esse carregamento está safo. Bom trabalho.', '', 28153),
(155652, 'ptBR', 'Ah, sim, esse pedaço é grande. Podem extrair. Vamos levar a azerita de volta pro navio rapidinho.', '', 28153),
(155651, 'ptBR', 'A máquina tá dizendo que tem azerita por perto. Vão lá dar uma olhadinha.', '', 28153),
(155650, 'ptBR', 'Abaixem as pranchas. É aqui.', '', 28153),
(155649, 'ptBR', 'A gente não sabe o que mais vamos encontrar aqui. Então cuidado para não darem com os burros n\'água.', '', 28153),
(155648, 'ptBR', 'Quase lá. Os batedores disseram que a ilha tá cheinha de azerita.', '', 28153),
(155647, 'ptBR', 'É claro, capitã.', 'É claro, capitã.', 28153),
(155646, 'ptBR', '', 'Então coloque-os no navio! Esses explosivos são uma ameaça à nossa segurança.', 28153),
(155645, 'ptBR', 'C-claro, Capitã Rocha.', 'C-claro, Capitã Rocha.', 28153),
(155644, 'ptBR', '', 'Esses carregamentos de pólvora vieram da Fundição Grimpagris?', 28153),
(155643, 'ptBR', 'Sangue e trovão! Que feitiçaria é essa? Nossos navios foram destruídos e nossas tropas empurradas para o mar!', '', 28153),
(155642, 'ptBR', 'Sabe, quem começar a vender tampões de ouvido na Angra do Facão vai ficar rico.', '', 28153),
(155641, 'ptBR', 'Você... você ouviu isso? Espera! De novo não! Mata, mata logo!', '', 28153),
(155640, 'ptBR', 'Boa! Talvez agora a Angra do Facão se torne um lugar mais seguro. Ah, quem eu tô querendo enganar?', '', 28153),
(155639, 'ptBR', 'Rá! Toma essa, seu papagaio!', '', 28153),
(155638, 'ptBR', 'Ótimo! Uma dívida a menos para me preocupar.', '', 28153),
(155637, 'ptBR', 'O que fede a grogue e usa um chapéu vermelho? Um pirata. E nem é um dos bonzinhos.', '', 28153),
(155636, 'ptBR', 'Uns amigos meus viram um homem procurado nas redondezas. Vamos reivindicar a recompensa para nós!', '', 28153),
(155635, 'ptBR', 'Tem um bandido especialmente perigoso na área. É melhor você dar cabo dele.', '', 28153),
(155634, 'ptBR', 'Opa, nossos amigos da Empreendimentos S.A vieram ajudar a carregar a Azerita. Só gente fina. Vão lá, vocês vão gostar deles.', '', 28153),
(155633, 'ptBR', 'A Empreendimentos S.A. está iniciando operações em vários locais da ilha. Você deveria levá-los à bancarrota.', '', 28153),
(155632, 'ptBR', 'A Empreendimentos S.A. veio fazer o que os goblins fazem de melhor: faturar em cima da Azerita alheia.', '', 28153),
(155631, 'ptBR', 'Avistamos capangas da Empreendimentos S.A. ao redor da ilha. Parece que uma aquisição hostil está a caminho.', '', 28153),
(155630, 'ptBR', 'Barcos, obra de vraikal, e não é pouco, não. Parece que um dos clãs se lançou aos mares atrás da Azerita.', '', 28153),
(155629, 'ptBR', 'Acabou de desembarcar um monte de vraikal. Devem estar atrás do nosso estoque. Não deixem eles triscarem a mão, combinado?', '', 28153),
(155628, 'ptBR', 'Uma frota vraikalen acabou de atracar. Um bando de guerreiros bem mal-encarados está montando acampamento ao redor da ilha. Isso é o que eu consegui ver além desse barril.', '', 28153),
(155627, 'ptBR', 'Navios vraikalen estão a caminho. Parecem um grupo de invasão. Estão sempre invadindo os lugares... é o que eles fazem.', '', 28153),
(155626, 'ptBR', 'Uns trolls ilhéus nada amigáveis decidiram invadir a festa. Estão montando acampamento pela ilha.', '', 28153),
(155625, 'ptBR', 'Canoas de trolls ilhéus no horizonte, vão chegar a qualquer momento. Essa Azerita atrai tudo de ruim que tem no mundo.', '', 28153),
(155624, 'ptBR', 'Alguns trolls ilhéus apareceram, provavelmente querendo pilhar a azerita. Seria bom se vocês pudessem manter eles longe do navio.', '', 28153),
(155623, 'ptBR', 'Vejam só, acabou de chegar um bocado de navios trólicos. Nada como um monte de trolls. Um exército inteiro de trolls, por que não? Ótima ideia.', '', 28153),
(155622, 'ptBR', 'Aí um dragão ENORME apareceu do nada porque era só isso que faltava acontecer hoje, né? Foi uma daquelas semanas pra esquecer. Enfim, é, dragão.', '', 28153),
(155621, 'ptBR', 'Ei, amigos...? Um dragão grande decidiu se juntar à festa e parece que está interessado na azerita de vocês. Só pra avisar.', '', 28153),
(155620, 'ptBR', 'Dragões, tem dragão à beça de olho no navio. Acho que me viram. Será que dá para alguém, hã... dar uma ajudinha?', '', 28153),
(155619, 'ptBR', 'Tem tipo uma revoada dragônica inteira que acabou de pousar aqui, e eu aposto que sei o que eles querem. Boa sorte!', '', 28153),
(155618, 'ptBR', 'Que negócio esquisito é esse no céu? Por que ficou escuro assim? E que MONTE de cadáver é esses na ilha? Ah, rapaz...', '', 28153),
(155617, 'ptBR', 'Olha, esse é o cheiro MAIS desagradável que eu já senti na vida. Quem foi que? Ah, são os mortos. Aí pessoal, os mortos estão aqui e querem a azerita! Só pra variar.', '', 28153),
(155616, 'ptBR', 'E para deixar tudo melhor, parece que os mortos-vivos estão se espalhando pela ilha. Eu prefiro nem saber.', '', 28153),
(155615, 'ptBR', 'Morto-vivo? Aqui? Não faço ideia do que está acontecendo, mas coisa boa não é.', '', 28153),
(155614, 'ptBR', 'Atenção, tem navios tol\'vir no horizonte e não parece que estão aqui para negociar pacificamente. Olha, será que dá para sairmos logo daqui? Por favor?', '', 28153),
(155613, 'ptBR', 'Eita, tol\'vir, é? Não vejo um navio desses faz um tempão. Bom, os bichos estão na área e vieram com sangue nos olhos.', '', 28153),
(155612, 'ptBR', 'Os tol\'vir acabaram de atracar. Como é que todo mundo sabe onde tem azerita? Detesto isso. Será que vocês podem ir lidar com eles?', '', 28153),
(155611, 'ptBR', 'Que bicho é aquele, um centauro? Um homotauro? Ei, apareceram uns, err... tol\'vir, sei lá.', '', 28153),
(155610, 'ptBR', 'Navio pirata no horizonte. Também devem estar querendo saquear esse lugar. Pirata adora fazer isso, né?', '', 28153),
(155609, 'ptBR', 'Tem uma tripulação pirata chegando. Porque onde há uma ilha com tesouro, sempre há piratas. É sempre a mesma coisa.', '', 28153),
(155608, 'ptBR', 'E agora apareceu um TERCEIRO navio, lógico, porque tudo que tem de bom sobra para mim. São piratas, aliás, caso alguém queira saber.', '', 28153),
(155607, 'ptBR', 'Oua! A bala de canhão passou por um triz. Tem pirata a dar com pau desembarcando na praia.', '', 28153),
(155606, 'ptBR', 'Sauroks acabaram de aparecer. Devem ter farejado a azerita. Pera aí, eles têm nariz? Eu é que não vou perguntar para eles.', '', 28153),
(155605, 'ptBR', 'Olha, eu juro que acabou de brotar um bando de saurok do meio do mar. Pois é.', '', 28153),
(155604, 'ptBR', 'O que é aquilo nas ondas? Ah, nossa, claro, um bando de sauroks acabou de emergir das profundezas. Agora é com você.', '', 28153),
(155603, 'ptBR', 'Tem uns lagartos mal encarados de olho no navio e é por causa da Azerita. Eu não deixava. Vocês vão deixar?', '', 28153),
(155602, 'ptBR', 'Chegou mais gente. Nunca vi esse pessoal antes. Duvido muito que estejam na intenção de ajudar.', '', 28153),
(155601, 'ptBR', 'Acabei de avistar novos visitantes. Parece que também estão coletando azerita, mas tem algo... de errado com eles.', '', 28153),
(155600, 'ptBR', 'Ah! De onde saiu esse pessoal? Parece que surgiram do nada. E aí, heróis? Chegou visita.', '', 28153),
(155599, 'ptBR', 'Quem são esses caras? Eu não consigo ver o rosto deles. Se são amigáveis? Provavelmente não.', '', 28153),
(155598, 'ptBR', 'E agora, pelo visto, a gente conquistou a atenção de nada menos que um deus antigo e seus lacaios. Será que vocês, hã... podem dar um jeito na situação?', '', 28153),
(155597, 'ptBR', 'Brotaram umas monstruosidades com cara de tentáculo na ilha e é isso aí, para mim já deu, estou fora, vou descendo, tchau e bênção.', '', 28153),
(155596, 'ptBR', 'Mais alguém está ouvindo sussurros? Das duas uma: ou estou enlouquecendo, ou tem sem-rosto na ilha. Ah, e eles estão aqui pela azerita.', '', 28153),
(155595, 'ptBR', 'Aquela é uma tempestade de escuridão sombria. Ótimo. Devem ser os Deuses Antigos. Cuidado com os tentáculos.', '', 28153),
(155594, 'ptBR', 'E ainda tem mogu de sobra atrás da Azerita. Devem estar loucos para dar uma chegada aqui.', '', 28153),
(155593, 'ptBR', 'Acabei de ver alguns mogus na ilha. Fique de olhos bem abertos... nós, hm, não somos amigos.', '', 28153),
(155592, 'ptBR', 'Alguns mogus acabaram de aterrissar na ilha. Não tenho certeza do que estão fazendo. Vou deixar você dar uma olhada.', '', 28153),
(155591, 'ptBR', 'Tem um esquadrão de serpentes mogus na área. Foi a Azerita que entregou a gente. Toda vez é isso.', '', 28153),
(155590, 'ptBR', 'Pronto, ainda me chegam as nagas. Agora não falta mais nada. Façam-me o favor de não morrerem, hein?', '', 28153),
(155589, 'ptBR', 'Avistamos algumas nagas pela luneta. Vão chegar logo mais. Tratem de dar uma boa recepção, ouviram bem?', '', 28153),
(155588, 'ptBR', 'Algumas nagas acabaram de chegar na ilha e estão em busca de azerita. Sem dúvida, em missão pra nossa amiga Azshara. Qual é o problema dela, afinal?', '', 28153),
(155587, 'ptBR', 'Há nagas saindo das profundezas, parece que estão rastejando em direção ao nosso estoque. E eu vou começar a carregar os canhões.', '', 28153),
(155586, 'ptBR', 'Lá vem o nevoeiro. Espera, e aqueles navios podres? Ah, são os kvaldir. Maravilha.', '', 28153),
(155585, 'ptBR', 'E aí? Acabamos de avistar navios dos Kvaldir, e eles estarão aqui em breve. Devem estar em busca da azerita. Por que que aceitei esse trabalho?', '', 28153),
(155584, 'ptBR', 'As coisas estão ficando bem nebulosas por aqui. Devem ser os Kvaldir. Fique de olho... se você conseguir, sabe, enxergar alguma coisa, claro.', '', 28153),
(155583, 'ptBR', 'Opa, que cheiro de alga marinha! Olha só, tem um monte de kvaldir aqui, pessoal.', '', 28153),
(155582, 'ptBR', 'Vamos ficar com insetos até o pescoço aqui. Tem um enxame de mantídeos enorme se aproximando. Eu vou pra debaixo do convés, e vocês se divirtam!', '', 28153),
(155581, 'ptBR', 'Já ouvi falar nesse pessoal, os mantídeos, se não me engano. Você, hã... cuida deles pra gente, combinado? Eu sou alérgico.', '', 28153),
(155580, 'ptBR', 'Aquilo é um enxame de abelhas? Não, grande demais. Hum, é mantídeo mesmo, e eles chegam jáááá, já.', '', 28153),
(155579, 'ptBR', 'Vocês vão adorar a novidade. Os mantídeos acabaram de chegar. É óbvio que estão atrás da azerita também. Óbvio.', '', 28153),
(155578, 'ptBR', 'Opa! O que foi que acabou de voar por cima da gente? Você viu aquilo? Tem um dragão grande em algum lugar da ilha. Fica de olho nele.', '', 28153),
(155577, 'ptBR', 'Então, pessoal, apareceu um dragãozão com um bocado de dragõezinhos e eles estão fulos da vida porque estamos levando a Azerita.', '', 28153),
(155576, 'ptBR', 'Era só o que me faltava: um dragão negro. Um dragão negro! Com metade da revoada! Justo aqui! Só faltava essa.', '', 28153),
(155575, 'ptBR', 'Hmm, um dragão grande acabou de pousar na ilha. Você sabe que meu barco é inflamável, né? Que ele fique tão, tão distante da gente.', '', 28153),
(155574, 'ptBR', 'Os tol\'vir tão entrando na caçada por azerita. Pisem macio pra não se estreparem.', '', 28153),
(155573, 'ptBR', 'Opa, tem alguns tol\'vir aqui. Eles tão procurando azerita que nem a gente! Haha.', '', 28153),
(155572, 'ptBR', 'Nunca pensei que fosse ver outro navio Tol\'vírico. Tem um bocado encostando na praia e eles tão fulos da vida.', '', 28153),
(155571, 'ptBR', 'Chegaram uns barcos que eu só vi uma vez na vida, coisa de Tol\'vir. Não parecem muito amigáveis.', '', 28153),
(155570, 'ptBR', '', 'Tenta trazer a relíquia de volta inteira, $n. O Astrandis é... meio empolgado.', 28153),
(155569, 'ptBR', '', 'É do interesse de todos nós manter os mares livres de piratas. Você tem minha gratidão, campeão.', 28153),
(155568, 'ptBR', 'Eu vou jogar você no porto.', '', 28153),
(155567, 'ptBR', 'Não é só o mar que está bravo.', '', 28153),
(155566, 'ptBR', 'Você não sabe com quem mexeu.', '', 28153),
(155565, 'ptBR', '', 'Precisamos saber o que os piratas estão armando. Intercepte as ordens deles... custe o que custar.', 28153),
(155564, 'ptBR', 'A maré sempre volta.', '', 28153),
(155561, 'ptBR', 'Que as boas correntes conduzam você.', '', 28153),
(155560, 'ptBR', 'Nunca se afaste do mar.', '', 28153),
(155558, 'ptBR', 'Eu detesto pássaros. Bichos mais escandalosos. Vamos cuidar de coisa séria.', '', 28153),
(155557, 'ptBR', 'Um de nossos contatos na Angra do Facão precisa de ajuda para... acalmar seus pássaros. Conto com você.', '', 28153),
(155556, 'ptBR', 'Eu sirvo às marés.', '', 28153),
(155554, 'ptBR', 'Você está sentindo... o poder... da pedra?', '', 28153),
(155553, 'ptBR', 'Vamos ficar RICOS com essa pedra! Ela não será sua!', '', 28153),
(155552, 'ptBR', 'Que as marés guiem você.', '', 28153),
(155551, 'ptBR', 'Se ouvir o mar, você vai aprender muito sobre o mundo.', '', 28153),
(155550, 'ptBR', 'Tenho minhas suspeitas...', '', 28153),
(155549, 'ptBR', 'Não me faça chamar a guarda.', '', 28153),
(155548, 'ptBR', 'Se tem algo a dizer, por favor, diga!', '', 28153),
(155547, 'ptBR', 'Por favor... poupe o meu gatinho.', '', 28153),
(155546, 'ptBR', 'Por favor, sou um homem muito ocupado.', '', 28153),
(155545, 'ptBR', 'Por favor, volte com mais histórias das suas aventuras!', '', 28153),
(155543, 'ptBR', 'Lá vem a rapaziada do Netinho! Vou plantar eles na lama, que nem fiz com os outros!', '', 28153),
(155540, 'ptBR', 'Exemplar!', '', 28153),
(155539, 'ptBR', 'Excelente! Divirta-se a valer! ', '', 28153),
(155538, 'ptBR', 'Sinta-se em casa. Minha propriedade é sua propriedade.', '', 28153),
(155536, 'ptBR', 'Coma, beba, se divirta!', '', 28153),
(155535, 'ptBR', 'Receba as boas-vindas ao Festival de Hipismo e Caça da Casa Lancastre!', '', 28153),
(155534, 'ptBR', '', 'E 500 bilhões de norgabytes de imagens com felinos fofinhos.', 28153),
(155533, 'ptBR', 'Bem na hora. Estamos sendo atacados por troggs!', '', 28153),
(155532, 'ptBR', '', 'Eles estão brincando com forças de que ninguém deveria nem chegar perto. Nós temos que manter os mares protegidos!', 28153),
(155531, 'ptBR', 'Guerreiros da Horda! Tá na hora de mostrar pra Aliança por que a gente luta! Vamos com tudo pra cima da fortaleza!', '', 28153),
(155530, 'ptBR', '', 'Juntos! Avancem! Arathi será nossa!', 28153),
(155529, 'ptBR', '', 'Os humanos estão convocando alguma coisa terrível das profundezas. Detenha todos!', 28153),
(155528, 'ptBR', 'Tortollano?', 'Tortollano?', 28153),
(155527, 'ptBR', '', 'A concha com braço e perna, logo ali! \n\nNão se deixe enganar. É um bicho esperto e enxerido! Está sempre catando lixo, pergaminhos e relíquias antigas. \n\nNão podemos deixar ele encontrar o tesouro primeiro.', 28153),
(155526, 'ptBR', 'Meu tio ficará sabendo disso!', '', 28153),
(155525, 'ptBR', 'Por favor, dê alguns passo para trás.', '', 28153),
(155524, 'ptBR', 'Por favor, você poderia me deixar em paz?', '', 28153),
(155522, 'ptBR', 'Bem, então é isso.', '', 28153),
(155521, 'ptBR', 'Ninguém me avisou... como é difícil ser líder.', '', 28153),
(155520, 'ptBR', 'Estou fazendo o que posso.', '', 28153),
(155516, 'ptBR', 'O Caniço está sob minha proteção!', '', 28153),
(155515, 'ptBR', 'Preciso provar meu valor para o meu tio.', '', 28153),
(155514, 'ptBR', 'Que as boas marés lhe recebam.', '', 28153),
(155513, 'ptBR', 'Tudo bem.', '', 28153),
(155512, 'ptBR', 'Se você não precisa de mais nada, vá embora, por favor.', '', 28153),
(155511, 'ptBR', 'De volta ao meu posto.', '', 28153),
(155510, 'ptBR', 'Eu tenho um dever a cumprir.', '', 28153),
(155509, 'ptBR', 'Hunf.', '', 28153),
(155508, 'ptBR', 'Fantástico! Vai dar para fazer umas poções... interessantes com esses ingredientes.', '', 28153),
(155507, 'ptBR', 'A região está cheia de recursos naturais e reagentes alquímicos de grande serventia para nós! Recolha o que achar de valioso para mim.', '', 28153),
(155506, 'ptBR', '', 'Nossos fazendeiros estão gratos pela sua ajuda com as feras.', 28153),
(155505, 'ptBR', '', 'Feras selvagens estão invadindo nossas fazendas junto à costa. Ajude os fazendeiros e cuide do problema.', 28153),
(155504, 'ptBR', 'Se você nos tocar mais uma vez causará uma reação severa e potencialmente fatal.', '', 28153),
(155503, 'ptBR', 'Repita isso e você vai ver que nem sempre somos uma pessoa divertida.', '', 28153),
(155502, 'ptBR', 'Se a gente perder o chapéu, você vai se arrepender.', '', 28153),
(155501, 'ptBR', 'Isso é tudo?', '', 28153),
(155500, 'ptBR', 'Cresça com honra. Nossa mente está limpa.', '', 28153),
(155499, 'ptBR', 'Que os esporos estejam com você.', '', 28153),
(155498, 'ptBR', 'Vemos você.', '', 28153),
(155497, 'ptBR', 'Nossas saudações!', '', 28153),
(155496, 'ptBR', 'Sempre vai existir... um Líquen Rei...', '', 28153),
(155495, 'ptBR', 'Fúngico Lamento tem fome!', '', 28153),
(155494, 'ptBR', 'Argh!', '', 28153),
(155493, 'ptBR', 'Que esporos caiam sobre nós...', '', 28153),
(155492, 'ptBR', 'Não... podemos... ouvir...', '', 28153),
(155491, 'ptBR', 'Matar você! Matar! Matar!', '', 28153),
(155490, 'ptBR', 'Junte-se a nós!', '', 28153),
(155489, 'ptBR', 'Morram! Morram! Morram!', '', 28153),
(155488, 'ptBR', '', 'Rá! Esse é o tipo de abate que causaria inveja nos Rompe-ondas.', 28153),
(155487, 'ptBR', 'Alguma monstruosidade vem forrando o bucho com as entranhas dos nosso recrutas. Mate-a... antes que eu seja forçado a recrutar mais uma leva de incompetentes.', '', 28153),
(155486, 'ptBR', '', 'Guardas kultirenos relataram a presença de uma grande fera nessa área. É uma ameaça a todos que viajam pelos mares.', 28153),
(155485, 'ptBR', 'Piratas contam histórias de um esqueleto demoníaco que vive na enseada. Essa explicação é bem melhor.', '', 28153),
(155484, 'ptBR', 'Uma grande fera se arrastou até a praia. Não sei de onde veio, mas parece perigosa.', '', 28153),
(155483, 'ptBR', 'Bom trabalho! Não é por acaso que alguns detentos de Tol Dagor estavam aí dentro. Ele era um deles.', '', 28153),
(155482, 'ptBR', '', 'Que homem insano. Você salvou a vida de muita gente hoje.', 28153),
(155481, 'ptBR', 'Eu me vou...', 'Eu me vou...', 28153),
(155480, 'ptBR', 'Estou salvo.', 'Estou salva.', 28153),
(155479, 'ptBR', 'Obrigado.', 'Obrigada.', 28153),
(155478, 'ptBR', 'Eu quero descanso...', 'Eu quero descanso...', 28153),
(155477, 'ptBR', 'Eu estava tão perdido...', 'Eu estava tão perdida...', 28153),
(155476, 'ptBR', 'Eu tive tanto medo... agora não mais...', 'Eu tive tanto medo... agora não mais...', 28153),
(155475, 'ptBR', 'Está bem?', '', 28153),
(155474, 'ptBR', 'A Luz é tão cálida...', 'A Luz é tão cálida...', 28153),
(155473, 'ptBR', '', 'Agradeço a sua ajuda. Jamais nos esqueceremos.', 28153),
(155471, 'ptBR', 'Por aqui.', 'Por aqui.', 28153),
(155470, 'ptBR', 'Recarregar!', 'Recarregar!', 28153),
(155469, 'ptBR', '', 'Herege! Você não vai interferir!', 28153),
(155468, 'ptBR', 'Disparar!!!', 'Disparar!!!', 28153),
(155467, 'ptBR', '', 'Zandalar é feita de ouro. Será que tem jeito de roubar a cidade inteira?', 28153),
(155466, 'ptBR', '', 'Um fugitivo da prisão humana desembarcou no porto da Horda. Ele é um perigo para todos nós.', 28153),
(155465, 'ptBR', 'Acho que conheço aquele cara! Pera aí... eu com certeza conheço aquele cara. E isso não é nada bom.', '', 28153),
(155464, 'ptBR', 'As profundezas... nos darão... muito mais!', '', 28153),
(155463, 'ptBR', 'Este poder é uma dádiva das profundezas!', '', 28153),
(155462, 'ptBR', 'Eu pensei que esses kultirenos fossem se mostrar adversários dignos... mas eles desabam à toa, como qualquer covarde da Aliança.', '', 28153),
(155461, 'ptBR', 'Uma patrulheira sombria fisgou um dos conselheiros da Grã-almirante. A armadilha foi preparada... eu lhe dou a honra de dispará-la.', '', 28153),
(155460, 'ptBR', '', 'Os espíritos dos mortos podem descansar uma vez mais.', 28153),
(155459, 'ptBR', 'Tá bem... mas você volta, né?', '', 28153),
(155458, 'ptBR', 'Tudo bem, até mais tarde!', '', 28153),
(155457, 'ptBR', 'Isso vai ensinar a Horda a não se meter com nossos fuzileiros! Bom trabalho.', '', 28153),
(155456, 'ptBR', 'Um oficial dos Proudmore encurralou uma patrulheira sombria! Ajude-o!', '', 28153),
(155455, 'ptBR', 'Eu tenho muito orgulho do meu pai!', '', 28153),
(155454, 'ptBR', 'Vai ser um bom dia!', '', 28153),
(155453, 'ptBR', 'O papai disse que às vezes gente grande tem medo. Você tem medo?', '', 28153),
(155452, 'ptBR', 'Olha só que pôneis bonitos!', '', 28153),
(155451, 'ptBR', 'Nunca se é velho demais para começar a aprender!', '', 28153),
(155450, 'ptBR', 'Até mais ver!', '', 28153),
(155449, 'ptBR', '', 'Os espíritos dos mortos foram atiçados pelos lacaios das bruxas. Elimine o poder corruptor e conduza as almas perdidas de volta ao seu descanso.', 28153),
(155448, 'ptBR', 'Bom... pelo menos provei um Reserva Zanchuli uma...<hic!>... última vez antes de morrer!', '', 28153),
(155447, 'ptBR', 'Ouvi dizer que o Mojambo contratou reforços pra batalha. O pessoal do Tongo agora tá do lado dele...', '', 28153),
(155446, 'ptBR', 'Avistei gente do Mojambo investigando a área...', '', 28153),
(155445, 'ptBR', 'Você cumpriu sua parte no trato, então eu vou cumprir a minha...', '', 28153),
(155444, 'ptBR', 'Ahhh! Já tinha uns anos que eu não saboreava um Reserva Zanchuli...<hic!>', '', 28153),
(155443, 'ptBR', 'Aqui está o rum. Conte o que sabe.', 'Aqui está o rum. Conte o que sabe.', 28153),
(155442, 'ptBR', 'Tudo bem, adeus! Eu estarei... aqui.', '', 28153),
(155441, 'ptBR', 'Estou em busca de conhecimento. O que você busca?', '', 28153),
(155440, 'ptBR', 'Viemos de muito longe, mas finalmente chegamos!', '', 28153),
(155439, 'ptBR', 'Boa caçada.', '', 28153),
(155438, 'ptBR', 'Pela Horda!', '', 28153),
(155437, 'ptBR', 'Precisa rastrear alguma coisa?', '', 28153),
(155436, 'ptBR', 'Com garras e presas.', '', 28153),
(155435, 'ptBR', 'Já chega! Vou caçar você!', '', 28153),
(155434, 'ptBR', 'É sério, pare com isso!', '', 28153),
(155433, 'ptBR', 'Eu... hm... caço sozinho.', '', 28153),
(155432, 'ptBR', 'Que a caçada comece.', '', 28153),
(155431, 'ptBR', 'Que assim seja.', '', 28153),
(155430, 'ptBR', 'À espreita.', '', 28153),
(155429, 'ptBR', 'A caçada começa.', '', 28153),
(155428, 'ptBR', 'Minha presa se aproxima.', '', 28153),
(155427, 'ptBR', 'Eu ouço o chamado da natureza.', '', 28153),
(155426, 'ptBR', 'Você está vendo aqueles cavalos? Criaturas majestosas!', '', 28153),
(155425, 'ptBR', 'Tomara que não demore a voltar!', '', 28153),
(155424, 'ptBR', 'Lembre-se de não alimentar os animais!', '', 28153),
(155423, 'ptBR', 'Aproveite o resort!', '', 28153),
(155422, 'ptBR', '...', '', 28153),
(155421, 'ptBR', 'Por que estamos aqui embaixo?', 'Por que estamos aqui embaixo?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155420, 'ptBR', 'O que você ia me dizer?', 'O que você ia me dizer?', 28153),
(155419, 'ptBR', 'Não podemos perder tempo. Não temos muito tempo.', 'Não podemos perder tempo. Não temos muito tempo.', 28153),
(155418, 'ptBR', 'Como vai você?', '', 28153),
(155417, 'ptBR', 'Olá!', '', 28153),
(155416, 'ptBR', 'Boas-vindas ao Resort das Fontes Gasosas!', '', 28153),
(155415, 'ptBR', '', 'Minhas irmãs... terão o poder... da pedra!', 28153),
(155414, 'ptBR', '', 'A mamãe vai adorar o poder dessa pedra!', 28153),
(155413, 'ptBR', 'A região de que cuidaremos primeiro fica por sua conta. Faça sua escolha, e zarparemos imediatamente.', '', 28153),
(155412, 'ptBR', 'Pois bem, $n. Quem sabe faz a hora, não espera acontecer. Temos um agente pronto para encarar uma importante missão.', '', 28153),
(155411, 'ptBR', 'Que a Luz esteja convosco, Rei Wrynn.', '', 28153),
(155410, 'ptBR', 'Boa viagem, Majestade.', '', 28153),
(155409, 'ptBR', 'Tenho muito a resolver em Ventobravo, mas espero receber notícias do seu progresso. Sei que a campanha está em boas mãos. Boa sorte a todos vocês.', '', 28153),
(155408, 'ptBR', 'Campeão.', '', 28153),
(155407, 'ptBR', 'Para as situações que exigem uma abordagem mais... sutil, pode contar com a ajuda do Mestre Mathias Shaw e dos agentes da AVIN.', '', 28153),
(155406, 'ptBR', 'É uma honra trabalhar com você, $n.', '', 28153),
(155405, 'ptBR', 'Você terá ajuda total da 7ª Legião, os melhores soldados da Aliança, sob liderança do Alto-comandante Haraldo Serpecida.', '', 28153),
(155404, 'ptBR', 'Como um dos maiores heróis da Aliança, você terá um papel muito importante para vencermos essa guerra. Não podemos deixar que a Horda se alie aos Zandalari.', '', 28153),
(155403, 'ptBR', '$n, chegou a hora de lutarmos em Zandalar. Aguardo a sua chegada no Redenção do Vento, lá em Boralus.', '', 28153),
(155402, 'ptBR', 'Essa mata é amaldiçoada! Saia daqui! Fuja enquanto pode!', 'Essa mata é amaldiçoada! Saia daqui! Fuja enquanto pode!', 28153),
(155401, 'ptBR', 'Nunca tinha visto tamanha insanidade!', 'Nunca tinha visto tamanha insanidade!', 28153),
(155400, 'ptBR', 'Eles comeram o meu cachorro! E eu era o próximo!', 'Eles comeram o meu cachorro! E eu era a próxima!', 28153),
(155399, 'ptBR', 'O que está havendo, em nome do barco cheio de craca do meu avô?', 'O que está havendo, em nome do barco cheio de craca do meu avô?', 28153),
(155398, 'ptBR', 'Tinha um monte de coelho me perseguindo. Eu disse coelhos!', 'Tinha um monte de coelho me perseguindo. Eu disse coelhos!', 28153),
(155397, 'ptBR', 'Ahhhhhhhhhhhhhhhhhhhhhh!', 'Ahhhhhhhhhhhhhhhhhhhhhh!', 28153),
(155396, 'ptBR', 'Os animais enlouqueceram!', 'Os animais enlouqueceram!', 28153),
(155395, 'ptBR', 'Agradeço, $Uamigo:amiga;!', 'Agradeço, $Uamigo:amiga;!', 28153),
(155394, 'ptBR', 'Tem nagas rastejando pela praia. Elas estão querendo saquear a ilha.', '', 28153),
(155393, 'ptBR', 'Avistamos as nagas. Deve ter sido a azerita que a gente coletou. Fiquem alertas.', '', 28153),
(155392, 'ptBR', 'Tropas de naga na área. Vocês vão fazer a festa, ha.', '', 28153),
(155391, 'ptBR', 'Tem naga saindo das profundezas, atrás das gemas que nem a gente. Olho aberto.', '', 28153),
(155390, 'ptBR', 'Se cuidem, acabou de despontar um dragãozão com a revoada inteira lá longe, e tão vindo pra cá.', '', 28153),
(155389, 'ptBR', 'Acabou de chegar um monte de dragão, e eles tão catando a Azerita toda. Pode ser boa ideia botar um fim nessa história.', '', 28153),
(155388, 'ptBR', 'Opa, temos visitas. Uma revoada de dragões acabou de passar por aqui de olho no nosso navio.', '', 28153),
(155387, 'ptBR', 'Tem alguma coisa chegando pelo ar... parece que são dragões. Devem estar atrás da azerita. Tomem cuidado.', '', 28153),
(155386, 'ptBR', 'Dragões negros... aqui? Devem estar atrás da azerita. Fiquem espertos.', '', 28153),
(155385, 'ptBR', 'Dragões... nunca achei que fosse ver um adulto. Eles tão atrás de Azerita, da nossa Azerita.', '', 28153),
(155384, 'ptBR', 'Sim, tem uns dragões pousando aqui. Parece que a azerita chamou a atenção deles.', '', 28153),
(155383, 'ptBR', 'O céu tá escurecendo... é dragão negro! Trouxe a revoada pra saquear a ilha. Socorro!', '', 28153),
(155382, 'ptBR', 'Chegou uma cabeçada da Empreendimentos S.A, cheia de equipamento. Tão atrás da Azerita.', '', 28153),
(155381, 'ptBR', 'A Empreendimentos S.A. quer começar uma operação nesta ilha. Acho bom vocês não deixarem isso acontecer.', '', 28153),
(155380, 'ptBR', 'Tem uns investidores da Empreendimentos S.A. interessados no nosso depósito. Acho que vocês vão ter que fazer uma reunião de negócios com eles.', '', 28153),
(155379, 'ptBR', 'Aí, meus camaradas, a Empreendimentos S.A. está aqui. Parece que estão montando uma base agora mesmo.', '', 28153),
(155378, 'ptBR', 'Epa, olha ali, um monte de navio de troll ilhéu. Tão atrás da Azerita também. Não deixem eles botarem as patas, ha!', '', 28153),
(155377, 'ptBR', 'Alguns trolls ilhéus acabaram de chegar. Aposto que querem saquear a ilha. Fiquem alerta.', '', 28153),
(155376, 'ptBR', 'Canoas de trolls ilhéus no horizonte. Nunca gostei dessa gente. Mata uns por mim, faz favor?', '', 28153),
(155375, 'ptBR', 'Também estão chegando trolls ilhéus, e com cara de poucos amigos.', '', 28153),
(155374, 'ptBR', 'Tá chovendo bala de canhão aqui. Navio pirata ancorando pra saquear a ilha.', '', 28153),
(155373, 'ptBR', 'Epa, agora tem pirata também. Acabaram de chegar na praia. Vão lá receber eles.', '', 28153),
(155372, 'ptBR', 'Uma tripulação pirata está desembarcando, estão atrás do mesmo tesouro que nós. Tomem cuidado.', '', 28153),
(155371, 'ptBR', 'Não gosto de você...', 'Você... realmente devia ir embora...', 28153),
(155370, 'ptBR', 'Tem outro navio no horizonte... parece que são piratas. Deem um jeito neles antes que roubem todo o nosso tesouro.', '', 28153),
(155369, 'ptBR', 'Eu conheço esse assobio. Tem um bando saurok vindo aí. Se cuidem.', '', 28153),
(155368, 'ptBR', 'É, as ondas tão meio bizarras. Parece que os sauroks acabaram de chegar... e são muitos', '', 28153),
(155367, 'ptBR', 'Tem uns lagartos mal-encarados de olho no nosso navio. Vai ver é o caso de correr com eles, e rápido.', '', 28153),
(155366, 'ptBR', 'Tem um bando de sauroks saindo da água. Parece que eles também tão atrás da azerita.', '', 28153),
(155365, 'ptBR', 'Não... Na cara não!', 'Você já pode parar...', 28153),
(155364, 'ptBR', 'Vou perder meu prazo!', 'Meu seguro não cobre isso!', 28153),
(155363, 'ptBR', 'Ouviram isso? Os mantídeos também tão aqui atrás de azerita. Cuidado pra não se ferroar! Haha!', '', 28153),
(155362, 'ptBR', 'Tem um bando de insetos chegando. Se cuidem... eles estão aqui pelos mesmos motivos que nós.', '', 28153),
(155361, 'ptBR', 'Apareceram uns caras aí, acho que uns mantídeos. Pelo visto também tão recolhendo Azerita.', '', 28153),
(155360, 'ptBR', 'Esse zumbido... tá vindo lá do céu. Deve ter inseto de monte vindo pra ilha.', '', 28153),
(155359, 'ptBR', 'Meu seguro paga o dobro por isso...', 'Que constrangedor!', 28153),
(155358, 'ptBR', 'Espíritos... me levem...', 'Espíritos... me levem...', 28153),
(155357, 'ptBR', 'Que cheiro de alga marinha é esse? Ali, um monte de barcos Kvaldir aproando na praia.', '', 28153),
(155356, 'ptBR', 'Não dá pra enxergar nada no meio desse nevoeiro. Só pode ser coisa de Kvaldir. Se cuidem.', '', 28153),
(155355, 'ptBR', 'Barcos podres se aproximam com catinga de kvaldir. Eles tão atrás da nossa azerita.', '', 28153),
(155354, 'ptBR', 'As coisas estão ficando nebulosas, e não é uma névoa qualquer, não. Já, já os kvaldir dão as caras por aqui.', '', 28153),
(155353, 'ptBR', 'Isso... não foi... o que eu planejei...', 'Isso... não foi... o que eu planejei...', 28153),
(155352, 'ptBR', 'Sempre quis um navio pirata, chefia. Batizei com o nome da minha filha, Mala!\n\nSe eu arrumar uma aeronave, vou dar o nome do meu filho!', '', 28153),
(155351, 'ptBR', 'Como foi que você inventou o nome?', 'Como foi que você inventou o nome?', 28153),
(155350, 'ptBR', 'Eheheheheheheh...\n\nEssa é uma história pra um outro dia, chefia.', '', 28153),
(155349, 'ptBR', 'Onde foi que você arranjou esse navio?', 'Onde foi que você arranjou esse navio?', 28153),
(155348, 'ptBR', 'A Garona me mandou achar um navio. Então eu achei um.', '', 28153),
(155347, 'ptBR', 'Por que você tem um navio pirata?', 'Por que você tem um navio pirata?', 28153),
(155346, 'ptBR', 'Apareceram uns camaradas gente fina, aí. Guerreiros vraikalen, pelo jeito.', '', 28153),
(155345, 'ptBR', 'Ei, tem gente chegando. Parece que são invasores vraikalen. Tomem cuidado.', '', 28153),
(155344, 'ptBR', 'Barcos vraikalen tão largando ferro. Um grupo de invasão... Eles tão atrás do nosso estoque.', '', 28153),
(155343, 'ptBR', 'Ei, chefia. Tá na fissura de um motim?', '', 28153),
(155342, 'ptBR', 'Tem barco no horizonte. Devem ser vraikalen atrás das gemas.', '', 28153),
(155341, 'ptBR', 'Tem alguma coisa mandando os mortos pra cima da gente. Coisa de outro mundo. Fiquem de olho.', '', 28153),
(155340, 'ptBR', 'Os espíritos me dizem que os mortos estão aqui e que eles querem a sua azerita.', '', 28153),
(155339, 'ptBR', 'Eca, que catinga. Deve ter morto-vivo atrás do que é nosso. Fiquem ligados.', '', 28153),
(155338, 'ptBR', 'Esse breu não é normal, tem alguma coisa vindo atrás dessa Azerita. Alguma coisa maligna.', '', 28153),
(155337, 'ptBR', 'Chegou um pessoal estranho atrás da nossa Azerita. Parece uma seita ou coisa parecida.', '', 28153),
(155336, 'ptBR', 'Oua, nem vi esses caras chegando. Tem visita pra vocês. Se cuidem!', '', 28153),
(155335, 'ptBR', 'Opa, quem são esses caras? Parece que eles também tão recolhendo azerita. Se eu fosse vocês, não deixava.', '', 28153),
(155334, 'ptBR', 'Opa, temos companhia. Nunca vi esse pessoal antes. Devem estar atrás da azerita.', '', 28153),
(155333, 'ptBR', 'Tem serpente mogu na praia. Elas vão chegar mais hora, menos hora.', '', 28153),
(155332, 'ptBR', 'Tem mogu na área de olho no que é nosso. Vão dar as boas-vindas pros caras, ha.', '', 28153),
(155331, 'ptBR', 'Um dos mogus quer pegar nossa azerita. Fiquem de olho em grupos de invasão.', '', 28153),
(155330, 'ptBR', 'Vi algumas serpentes voando perto daqui. Mogus devem vir logo atrás.', '', 28153),
(155329, 'ptBR', 'Tempestade de sombras vindo aí... com sem-rosto a rodo.', '', 28153),
(155328, 'ptBR', 'Vocês ouviram alguém cochichando? Deve ser um deus antigo mandando os súditos pra cá. Olho aberto.', '', 28153),
(155327, 'ptBR', 'Apareceram uns caras de tentáculo atrás da Azerita, amizade. Eu... vou dar uma descidinha.', '', 28153),
(155326, 'ptBR', 'A azerita atraiu a atenção dos sem-rosto. Apareceu um bando deles por aqui.', '', 28153),
(155325, 'ptBR', 'Pássaro feio! Nada de sangue.', 'Pássaro feio! Nada de sangue.', 28153),
(155324, 'ptBR', 'Xô!', 'Xô!', 28153),
(155323, 'ptBR', '', 'Nossos caçadores já podem andar pelas selvas do Arroio do Vale.', 28153),
(155322, 'ptBR', '', 'Os animais foram influenciados pelas bruxas e agora estão atacando nossos caçadores! Você precisa salvá-los! Acabe com essas criaturas malditas!', 28153),
(155321, 'ptBR', '', 'Você é tipo $Uo meu ajudante engraçado:a minha ajudante engraçada;, $p.', 28153),
(155320, 'ptBR', '', 'Você não me é estranh$Uo:a;... cumpriu pena em Tol Dagor?', 28153),
(155319, 'ptBR', '', 'Meus parabéns. A fauna do contraforte não será mais uma ameaça às comunidades da região.', 28153),
(155318, 'ptBR', '', 'A fauna dessas colinas está enfeitiçada pela maldição das bruxas! Ponha um fim nisso, antes que os animais cheguem na cidade.', 28153),
(155317, 'ptBR', 'Está ficando difícil de respirar!', 'Está ficando difícil de respirar!', 28153),
(155312, 'ptBR', 'Levará um tempo para que se recuperem desse ataque. Pela Dama Sombria!', '', 28153),
(155311, 'ptBR', 'As forças da Chefe Guerreira conquistaram um território na academia militar. Vá ajudá-los!', '', 28153),
(155310, 'ptBR', '', 'Treinei com alguns desses homens! A Horda pagará pelo sofrimento que causou!', 28153),
(155309, 'ptBR', '', 'Um contingente de elites da Horda entrou na Academia Proudmore. Os fuzileiros precisam de nossa ajuda para defendê-la!', 28153),
(155308, 'ptBR', '', 'Refúgio Outonal está segura outra vez, mas não podemos descuidar.', 28153),
(155307, 'ptBR', '', 'Outra vez, Refúgio Outonal é acossada pela maldição das bruxas. Quebre-a ou a cidade está perdida!', 28153),
(155306, 'ptBR', '', 'Hah... o poder das rochas... pertence... aos Trovamare!', 28153),
(155305, 'ptBR', '', 'Esta pedra é uma dádiva das profundezas que jamais será sua!', 28153),
(155304, 'ptBR', 'Quando o talo murchou, eu sabia que estava por minha conta, então eu arranjei um emprego aqui nas docas na mesma hora. Aquela flor me salvou de viver no abandono, como tantos outros.', 'Quando o talo murchou, eu sabia que estava por minha conta, então eu arranjei um emprego aqui nas docas na mesma hora. Aquela flor me salvou de viver no abandono, como tantos outros.', 28153),
(155303, 'ptBR', 'Sejam javatuscos ou invasores da Horda, o povo do vale não se curvará.', '', 28153),
(155302, 'ptBR', 'Deixa... pedra do trogg...', '', 28153),
(155301, 'ptBR', 'Minhas pedra...', '', 28153),
(155300, 'ptBR', 'Esmagar... você...', '', 28153),
(155299, 'ptBR', 'Trogg... esmagado...', '', 28153),
(155298, 'ptBR', 'Trogg desaba...', '', 28153),
(155297, 'ptBR', 'Trogg... mata...', '', 28153),
(155296, 'ptBR', 'Arrraagh!', '', 28153),
(155295, 'ptBR', 'Garuuu...', '', 28153),
(155294, 'ptBR', 'Aqui terra de trogg! Você sair!', '', 28153),
(155293, 'ptBR', 'Aaaraauuh! Trogg matar você!', '', 28153),
(155292, 'ptBR', 'Você virar pedrinhas!', '', 28153),
(155291, 'ptBR', '', 'Eu sempre mantive as coisas nos eixos por toda Kul Tiraz. Como posso ajudar?', 28153),
(155290, 'ptBR', 'Pedra brilhenta é do trogg! Vai embora!', '', 28153),
(155289, 'ptBR', 'Graaaaraah! Destruir!', '', 28153),
(155288, 'ptBR', 'Trogg quebrar tua cara!', '', 28153),
(155287, 'ptBR', 'Trogg esmagar tua cabeça!', '', 28153),
(155286, 'ptBR', 'Aqui terra de trogg!', '', 28153),
(155285, 'ptBR', 'Troggzor!', '', 28153),
(155284, 'ptBR', 'Pedra minha! Não sua!', '', 28153),
(155283, 'ptBR', 'Meu tesouro! Só meu!', '', 28153),
(155282, 'ptBR', 'Rarrragh!', '', 28153),
(155281, 'ptBR', 'Aaaaaraaagh!', '', 28153),
(155280, 'ptBR', 'Esmagar! Quebrar! MATAR!', '', 28153),
(155279, 'ptBR', 'Trogg esmaga!', '', 28153),
(155278, 'ptBR', 'Trogg não ser burro!', '', 28153),
(155277, 'ptBR', 'Ei! Viu o que a Princesa fez com a Aliança? Do lado esquerdo, dá pra ver parte dos destroços. Foi muito poder de loa!', '', 28153),
(155276, 'ptBR', 'As nagas sumiram por um tempo. Rolou um papo de reconstrução, mas com o Gral desaparecido ou fraco demais pra ajudar, ficou só na conversa.', '', 28153),
(155275, 'ptBR', 'Até o último dos seguidores dele foi massacrado. Gral ficou furioso! Todo mundo que tava perto da água naquela noite sentiu a dor dele... a cada um que tombava.', '', 28153),
(155274, 'ptBR', 'Oh ho! Foi como se um peso tivesse sumido! Soubemos que aquela bruxa com cabelo de cobra tinha morrido!', '', 28153),
(155273, 'ptBR', 'Tenha um dia extraordinário.', '', 28153),
(155272, 'ptBR', 'Cuidado. Esta terra já não é mais segura.', '', 28153),
(155271, 'ptBR', 'Em Trovamare, há tesouros por toda parte.', '', 28153),
(155270, 'ptBR', 'Boas-vindas ao vale.', '', 28153),
(155269, 'ptBR', 'Saudações!', '', 28153),
(155268, 'ptBR', 'Brennadam é meu lar, e eu o protegerei.', '', 28153),
(155267, 'ptBR', '', 'Eu sou uma mulher de palavra. Você e a Horda são bem-vindos no meu porto.', 28153),
(155266, 'ptBR', 'Isso aí, capitão. A gente vai apoiar a tua causa. Só quero ver se você vai apoiar a nossa também.', '', 28153),
(155265, 'ptBR', '', 'Liberdade... Parece que você manteve mesmo a sua palavra.', 28153),
(155264, 'ptBR', 'Por que você... veio até aqui?', '', 28153),
(155263, 'ptBR', 'Você destruiu um espinho... mas o urzal ainda vive...', '', 28153),
(155262, 'ptBR', 'Graaah!', '', 28153),
(155261, 'ptBR', 'Não... as gemas...', '', 28153),
(155260, 'ptBR', 'Você não pode... matar todos nós...', '', 28153),
(155259, 'ptBR', 'Estou definhando...', '', 28153),
(155258, 'ptBR', 'Me quebraram...', '', 28153),
(155257, 'ptBR', 'Os espinhos... quebraram...', '', 28153),
(155256, 'ptBR', 'As gemas brilhantes daqui são nossas, só nossas!', '', 28153),
(155255, 'ptBR', 'As pedras fortalecem nossos espinhos!', '', 28153),
(155254, 'ptBR', 'Reivindicamos esta terra e seu poder!', '', 28153),
(155253, 'ptBR', 'Seu corpo não é nada para as nossas lanças de espinhos.', '', 28153),
(155252, 'ptBR', 'Vou pendurar seu corpo na minha cabana!', '', 28153),
(155251, 'ptBR', 'Escolhemos bem.', '', 28153),
(155250, 'ptBR', 'Nosso urzal vai tomar essa ilha e todos que moram nela!', '', 28153),
(155249, 'ptBR', 'Quebra-espinho! Sua laia não tem vez aqui.', '', 28153),
(155248, 'ptBR', 'Lacaios, me protejam!', '', 28153),
(155247, 'ptBR', 'Dá pra eles um gostinho do próprio remédio!', '', 28153),
(155246, 'ptBR', 'Ninguém consegue deter o urzal selvagem!', '', 28153),
(155245, 'ptBR', 'Seu sangue alimentará o urzal.', '', 28153),
(155244, 'ptBR', 'Balas disparadas!', '', 28153),
(155243, 'ptBR', 'Manda ver!', '', 28153),
(155242, 'ptBR', 'Você vai definhar, inimigo dos espinhos.', '', 28153),
(155241, 'ptBR', 'Este lugar é nosso!', '', 28153),
(155240, 'ptBR', 'Não teríamos ajudado muito sentados numa jaula.', '', 28153),
(155239, 'ptBR', 'Perfurem a carne deles!', '', 28153),
(155238, 'ptBR', 'Destrocem os intrusos!', '', 28153),
(155237, 'ptBR', '', 'Águas turbulentas adiante.', 28153),
(155236, 'ptBR', 'Invasores!', '', 28153),
(155235, 'ptBR', 'Morra, quebra-espinho!', '', 28153),
(155234, 'ptBR', '', 'Que as marés guiem você.', 28153),
(155233, 'ptBR', 'As relíquias estão protegidas. Gral ainda não está perdido.', '', 28153),
(155232, 'ptBR', 'Sangue e trovão, camarada.', '', 28153),
(155231, 'ptBR', 'Ah, eu também achei esse berloque interessante.', '', 28153),
(155230, 'ptBR', 'Parece que nós nos precipitamos ao deixar o posto avançado.', '', 28153),
(155229, 'ptBR', '', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_01.BLP:20|t%s marca você com um estopim ardente. Fique longe dos Barris de Munição!', 28153),
(155228, 'ptBR', 'Aproveita as tuas últimas horas de vida, Razgaji. O nosso próximo encontro... vai ser o seu último!', '', 28153),
(155227, 'ptBR', 'A jornada nos trouxe até aqui. As descobertas que fizemos são mais uma peça deste quebra-cabeça.', '', 28153),
(155226, 'ptBR', '', 'Tome cuidado por aí.', 28153),
(155225, 'ptBR', '', 'A prefeita chegou. Em que posso ajudar?', 28153),
(155224, 'ptBR', '', 'Tenho que proteger os cidadãos de Trovamare.', 28153),
(155223, 'ptBR', '', 'Você pode dar uma mão?', 28153),
(155222, 'ptBR', 'Pela Horda!', '', 28153),
(155221, 'ptBR', 'Veja como se debate na rede! Eu vou adorar estripar isso aí!', 'Veja como se debate na rede! Eu vou adorar estripar isso aí!', 28153),
(155220, 'ptBR', 'Hah! Peguei outro!', 'Hah! Peguei outro!', 28153),
(155219, 'ptBR', 'Pô, cara. Tu não vai acreditar nas histórias que eu tenho pra contar!', '', 28153),
(155218, 'ptBR', '', 'Aí, Ty\'jin. Já que vamos trabalhar juntos, por que não me fala mais da Horda?', 28153),
(155217, 'ptBR', 'Toda a azerita... será... nossa...', '', 28153),
(155216, 'ptBR', 'Essa azerita é propriedade da Companhia Grimpagris!', '', 28153),
(155215, 'ptBR', '', 'As forças inimigas estão avançando. Você precisa detê-las!', 28153),
(155214, 'ptBR', '', 'Agora nossas tropas terão como respirar um pouco.', 28153),
(155213, 'ptBR', '', 'As bruxas foram embora! Muito bem!', 28153),
(155212, 'ptBR', '', 'O conventículo está atacando a área. Acabe com elas!', 28153),
(155211, 'ptBR', '', 'Você nos deu tempo para respirar. Obrigada.', 28153),
(155210, 'ptBR', '', 'Os cidadãos de Drustvar estão sendo atacados pelas forças do conventículo! Tire essas bruxas daqui!', 28153),
(155209, 'ptBR', '', 'Em nome do meu povo, eu agradeço a sua ajuda.', 28153),
(155208, 'ptBR', '', 'Meu povo precisa da sua ajuda. Por favor, você tem que ajudá-los!', 28153),
(155207, 'ptBR', 'Não! Vamos deixar ele levar essa. A gente vai embora agora... mas não vai ser tão generoso na próxima!', '', 28153),
(155206, 'ptBR', 'Eu dou conta $Udo:da; $r, chefe! Pode deixar!', 'Eu dou conta $Udo:da; $r, chefe! Pode deixar!', 28153),
(155205, 'ptBR', 'Eu não vou voltar contigo. Tu acha que os teus cafumangos vão dar conta $Udo meu:da minha; colega aqui? Não vai entrar em treta que tu não ganha, hein...', '', 28153),
(155204, 'ptBR', 'Já chega? Sou eu quem decide quando você pula fora! Tu sabe o que acontece com desertor!', '', 28153),
(155203, 'ptBR', 'Pra mim, já chega, Mojambo. Cansei de matar e roubar pra ganhar a vida. Eu vou seguir o meu caminho...', '', 28153),
(155202, 'ptBR', 'Hehehe...', 'Hehehe...', 28153),
(155201, 'ptBR', 'Tu não tava se escondendo dos teus velhos parças, tava?', '', 28153),
(155200, 'ptBR', 'Ora, ora, se não é Razgaji! Te falei que a gente ia encontrar ele aqui...', '', 28153),
(155199, 'ptBR', 'Fiquem ligados. O Mojambo não é de confiança...', '', 28153),
(155198, 'ptBR', 'Pronto. Vamos nessa.', 'Pronto. Vamos nessa.', 28153),
(155197, 'ptBR', 'Que o mar abençoe esses lingotes e nunca tente reavê-los.', 'Que o mar abençoe esses lingotes e nunca tente reavê-los.', 28153),
(155196, 'ptBR', '', 'Com o poder do nosso mestre do nosso lado, nos reergueremos de novo!', 28153),
(155195, 'ptBR', 'Você poderia abençoar esses lingotes de prata procelosa?', 'Você poderia abençoar esses lingotes de prata procelosa?', 28153),
(155194, 'ptBR', 'Vai na brisa, $r.', 'Vai na brisa, $r.', 28153),
(155193, 'ptBR', '', 'Todos se curvarão perante a Rainha Azshara!', 28153),
(155192, 'ptBR', '', 'Seus olhos queimarão enquanto a vontade dele consumir você!', 28153),
(155191, 'ptBR', 'Tire o arpão.', 'Tire o arpão.', 28153),
(155190, 'ptBR', '<A criatura olha para você sem forças, e depois volta os olhos para o arpão preso no flanco.>', '<A criatura olha para você sem forças, e depois volta os olhos para o arpão preso no flanco.>', 28153),
(155189, 'ptBR', 'Tu vai aonde?', '', 28153),
(155188, 'ptBR', 'Muga magudu! Pancada eles!', '', 28153),
(155187, 'ptBR', 'Ugafa! Eu bater, você doer!', '', 28153),
(155186, 'ptBR', 'Ooooh! Vocês gente ruim! Sai daqui!', '', 28153),
(155185, 'ptBR', 'Quem ser esse maguda?', '', 28153),
(155184, 'ptBR', 'Guaahr! Essas pedra... minhas pedra!', '', 28153),
(155183, 'ptBR', 'Aaaah! Cê não pegar tesouro!', '', 28153),
(155182, 'ptBR', 'Gwaaah? Quem ser esse?', '', 28153),
(155181, 'ptBR', 'Bwaaguugh! Você virar comida de peixe!', '', 28153),
(155180, 'ptBR', 'Aguu...?', '', 28153),
(155179, 'ptBR', 'Hurg!', '', 28153),
(155178, 'ptBR', 'Gafu... mogo...', '', 28153),
(155177, 'ptBR', 'Uug...', '', 28153),
(155176, 'ptBR', 'Mug!?', '', 28153),
(155175, 'ptBR', 'Matufa...', '', 28153),
(155174, 'ptBR', 'Gurk!', '', 28153),
(155173, 'ptBR', 'A-bu-bu-bu-bu!', '', 28153),
(155172, 'ptBR', 'Urga magu!?', '', 28153),
(155171, 'ptBR', 'Griiip!', '', 28153),
(155170, 'ptBR', 'Buga buga!', '', 28153),
(155169, 'ptBR', 'Augh!', '', 28153),
(155168, 'ptBR', 'Oka magodo!', '', 28153),
(155167, 'ptBR', 'Bokum?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155166, 'ptBR', 'Buga mabugu!', '', 28153),
(155165, 'ptBR', 'Ah gah mah gahma!', '', 28153),
(155164, 'ptBR', 'O coração dele fica cada vez mais fraco... não há mais nada que eu possa fazer por ele, além de acabar com seu sofrimento.', '', 28153),
(155163, 'ptBR', 'Grimpagris pôs um preço na sua cabeça!', 'Grimpagris pôs um preço na sua cabeça!', 28153),
(155162, 'ptBR', 'Vou fazer um troféu com o seu cadáver!', 'Vou fazer um troféu com o seu cadáver!', 28153),
(155161, 'ptBR', 'Vocês não podem derrotar os Grimpagris!', 'Vocês não podem derrotar os Grimpagris!', 28153),
(155160, 'ptBR', 'A cidade é nossa!', 'A cidade é nossa!', 28153),
(155159, 'ptBR', 'Boralus vai queimar!', 'Boralus vai queimar!', 28153),
