INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152010, 'ptBR', 'Pestilência se espalha!', '', 28153),
(152009, 'ptBR', 'Gestação violenta!', '', 28153),
(152008, 'ptBR', 'Consumir cadáveres!', '', 28153),
(152007, 'ptBR', 'Chega! Agora a Horda vai ter o que merece.', '', 28153),
(152006, 'ptBR', 'Lesão fatal. Contágio bem-sucedido.', '', 28153),
(152005, 'ptBR', 'Perdi o meu disfarce. Você tem outro pergaminho?', 'Perdi o meu disfarce. Você tem outro pergaminho?', 28153),
(152004, 'ptBR', 'O Engolidor da Selva dá um salto e cai na água!', '', 28153),
(152003, 'ptBR', 'Apodreça!', '', 28153),
(152002, 'ptBR', 'Perfeito para infectar!', '', 28153),
(152001, 'ptBR', 'Irrupção inevitável...', '', 28153),
(152000, 'ptBR', '', 'Maneiro? BAH. Ele não tem nada de maneiro.', 28153),
(151999, 'ptBR', '', 'Você já encontrou aquele pulha do Seu Maneiro?', 28153),
(151998, 'ptBR', 'Hospedeiros novos!', '', 28153),
(151990, 'ptBR', 'Agora... é hora de arrancar nosso troféu.', '', 28153),
(151989, 'ptBR', 'A pérola é nossa! Com ela, nossos navios vão se tornar os predadores do mar.', '', 28153),
(151987, 'ptBR', '', 'Aproveite esta vitória. Será sua última.', 28153),
(151986, 'ptBR', 'É a lei da selva. Os fortes se aproveitam dos fracos.', '', 28153),
(151985, 'ptBR', 'Fique de olhos abertos. Uma força misteriosa anda à nossa espreita.', '', 28153),
(151983, 'ptBR', 'A Aliança não vai levar esse prêmio. Todos que se opuserem vão cair!', '', 28153),
(151982, 'ptBR', '', 'Com certeza. Você me devolveu meu trabalho. Com a Mari como Chefe, a gente vai voltar a ganhar dinheiro por aqui.', 28153),
(151981, 'ptBR', 'Você vai apoiar Mari Mettebronka?', 'Você vai apoiar Mari Mettebronka?', 28153),
(151980, 'ptBR', '', 'Esse lugar já foi muito mais lucrativo.', 28153),
(151979, 'ptBR', '', 'Vamos sair daqui antes de nos tornarmos os encurralados. Venha!', 28153),
(151978, 'ptBR', 'A Casa Trovamare vai governar este reino afogado. A ira da Mãe das Marés fará disso uma realidade.', '', 28153),
(151977, 'ptBR', 'A frota... será dela...', '', 28153),
(151976, 'ptBR', 'Eu só estava brincando com eles, milorde. Assim será!', '', 28153),
(151975, 'ptBR', 'Nosso destino está quase aqui. Eles não podem entrar no Santuário da Tempestade.', '', 28153),
(151974, 'ptBR', '', 'Veja só o que você se tornou. Esse derramamento de sangue está nas suas mãos!', 28153),
(151973, 'ptBR', 'O pergaminho flutua e zumbe, visões de outros lugares obscurecidas por magia.', '', 28153),
(151972, 'ptBR', 'Sobrevivência da alma do mundo: improvável...', '', 28153),
(151971, 'ptBR', 'Infecção planetária iminente.', '', 28153),
(151970, 'ptBR', 'Vamos deixar os Maré-férrea ficarem com o tesouro.', 'Vamos deixar os Maré-férrea ficarem com o tesouro.', 28153),
(151969, 'ptBR', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s cria uma |cFFFF0000|Hspell:267891|h[Proteção de Rapidez]|h|r!', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s cria uma |cFFFF0000|Hspell:267891|h[Proteção de Rapidez]|h|r!', 28153),
(151968, 'ptBR', '<Apunhale ele logo.>', '<Apunhale ele logo.>', 28153),
(151967, 'ptBR', 'Tá falando sério?', 'Tá falando sério?', 28153),
(151966, 'ptBR', 'Isso é um acinte! Não vou pagar isso!', 'Isso é um acinte! Não vou pagar isso!', 28153),
(151965, 'ptBR', 'Um lugar no chão é 50 ouros. Se quiser ficar perto do fogo, 60. Traga suas cobertas.\n\nAs camas custam cem ouros.\n\nPara vincular sua pedra de regresso, são 75 ouros por semana.\n\nNão gostou? \n\n<Ele zomba e cruza os braços com um sorriso maroto.>\n\nSó lamento, as tarifas são essas.', '', 28153),
(151964, 'ptBR', 'As profundezas falaram de sua chegada... e da sua morte!', '', 28153),
(151963, 'ptBR', 'Ruptura imensa detectada.', '', 28153),
(151962, 'ptBR', '', 'Temos que reunir nossas forças e deter a podridão na origem.', 28153),
(151961, 'ptBR', '', 'O titã nos ganhou tempo, só que G\'huun não vai ficar contido por muito tempo.', 28153),
(151960, 'ptBR', 'Espécime virulento detectado. Prioridade número um: contenção.', '', 28153),
(151959, 'ptBR', 'Devorar! Consumir! Espalhar!', '', 28153),
(151958, 'ptBR', '', 'Esse troço tá procurando a ma\'ma dele? Vamos torcer que nos leve à alguma coisa que possa deter a expansão dessa praga.', 28153),
(151957, 'ptBR', 'Contenção de G\'huun falhando. M.A.D.R.E. não está reagindo.', '', 28153),
(151954, 'ptBR', '', 'Se esse troço se espalhar até a superfície, não vamos conseguir contê-lo.', 28153),
(151953, 'ptBR', '', 'Eu nunca vi esse tipo de corrupção antes.', 28153),
(151952, 'ptBR', '', 'Esse negócio não pode alcançar a superfície! Destruam agora!', 28153),
(151951, 'ptBR', '', 'Argh! Que tipo de criatura é essa?!', 28153),
(151950, 'ptBR', '', 'Fiquem atentos. Quem vai saber o que se esconde nessas cavernas.', 28153),
(151949, 'ptBR', '', 'Os trolls sangrentos estão espalhados, mas temos que encontrar a fonte da podridão e destruí-la.', 28153),
(151948, 'ptBR', 'Trouxemos um presente pra você, ó grande loa da morte!', '', 28153),
(151947, 'ptBR', 'Se isso significa trazer caras novas pra cá, deixa comigo.', '', 28153),
(151946, 'ptBR', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t $s começa a lançar |cFFFF0404|Hspell:260773|h[Ritual Atroz]|h|r!', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t %s começa a lançar |cFFFF0404|Hspell:260773|h[Ritual Atroz]|h|r!', 28153),
(151945, 'ptBR', 'Você vai apoiar Mari Mettebronka?', 'Você vai apoiar Mari Mettebronka?', 28153),
(151944, 'ptBR', 'Tá comprando ou vendendo?', '', 28153),
(151943, 'ptBR', '', 'Isso não é bom...', 28153),
(151942, 'ptBR', 'Com prazer. Eles sofrerão em seu nome!', '', 28153),
(151941, 'ptBR', 'Contágio detectado. Higienizar.', '', 28153),
(151940, 'ptBR', 'Explosão pestilenta!', '', 28153),
(151939, 'ptBR', 'Ativando salvaguarda final. Destruir fonte virulenta.', '', 28153),
(151938, 'ptBR', 'Imediatamente, milorde. Eu só preciso me livrar dessas pestes.', 'Imediatamente, milorde. Eu só preciso me livrar dessas pestes.', 28153),
(151937, 'ptBR', 'Purificando a área.', '', 28153),
(151936, 'ptBR', 'Protocolos de expurgo ativados.', '', 28153),
(151935, 'ptBR', 'Ruptura torpe!', '', 28153),
(151934, 'ptBR', 'Só uns ossos quebrados... nada demais.', '', 28153),
(151933, 'ptBR', 'Leva a gente pro acampamento vulperino, $p. A gente carrega o tesouro.', '', 28153),
(151932, 'ptBR', 'Jorrar sangue!', '', 28153),
(151931, 'ptBR', '', 'Baixem as armas! Vocês não precisam fazer isso!', 28153),
(151930, 'ptBR', 'Temos... que espalhar...', '', 28153),
(151929, 'ptBR', 'Toque da praga!', '', 28153),
(151928, 'ptBR', 'Infecção!', '', 28153),
(151927, 'ptBR', 'Carne corrompida.', '', 28153),
(151926, 'ptBR', 'Consumir!', '', 28153),
(151925, 'ptBR', 'Espalhar!', '', 28153),
(151924, 'ptBR', 'Só vê se não esquece a tua parte do trato, hein...', '', 28153),
(151923, 'ptBR', 'Hahahaha! Tá vendo, majestade? Bwonsamdi sempre honra os compromissos!', '', 28153),
(151922, 'ptBR', 'Ergam-se... ergam-se! Não sejam preguiçosos! Peguem tuas lanças de novo e LUTEM!', '', 28153),
(151921, 'ptBR', 'Calma lá, Tua Majestade. O Bwonsamdi sempre ajuda os parceiros...', '', 28153),
(151920, 'ptBR', '', 'Tá aí me olhando no batente por quê? Você também tem que trabalhar.', 28153),
(151919, 'ptBR', 'O barco tá pronto para partir.', '', 28153),
(151918, 'ptBR', 'Esses traidores estão entre mim e o meu reino? Onde está a ajuda que você prometeu? Você pretende manter sua palavra?', '', 28153),
(151916, 'ptBR', 'Tu fez bem. Já sinto Azeroth recuperando a força, graças a ti.', '', 28153),
(151915, 'ptBR', 'Várias feridas de azerita estão expostas por acá. Usa o Coração de Azeroth para curá-las!', '', 28153),
(151913, 'ptBR', 'Fujam enquanto ainda podem!', '', 28153),
(151912, 'ptBR', 'Tsc, tsc! Isso lá é jeito de falar com o teu loa, Tua Majestade? Mas tô ligado que as almas que eu vou coletar hoje compensam a falta de respeito!', '', 28153),
(151911, 'ptBR', 'Estamos no mesmo barco agora, $p.\n\nMotim ou verga.', '', 28153),
(151910, 'ptBR', 'Bwonsamdi, apareça!', '', 28153),
(151909, 'ptBR', 'Zul tem aliados demais. Só resta um caminho…', '', 28153),
(151908, 'ptBR', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s vê |cFFFF0000$n|r e se prepara para |cFFFF0000|Hspell:266951|h[Sair da Frente]|h|r!', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s vê |cFFFF0000$n|r e se prepara para |cFFFF0000|Hspell:266951|h[Sair da Frente]|h|r!', 28153),
(151907, 'ptBR', 'As antigas proteções que defendiam o Coração de Sethraliss foram desativadas por um grupo de Zandalari...', 'As antigas proteções que defendiam o Coração de Sethraliss foram desativadas por um grupo de Zandalari...', 28153),
(151906, 'ptBR', 'Sim, Mari pode contar com o meu apoio.', '', 28153),
(151905, 'ptBR', 'Comecem logo, seus goblins preguiçosos, quero a Base Portátil montada agora!', 'Comecem logo, seus goblins preguiçosos, quero a Base Portátil montada agora!', 28153),
(151904, 'ptBR', 'Você vai apoiar Mari Mettebronka?', 'Você vai apoiar Mari Mettebronka?', 28153),
(151902, 'ptBR', 'Hmmmmm. Sim. Deixa eu ver.\n\n<Kuda fica remexendo algum tempo até pegar um pote bem no fundo da sacola.>\n\nComprei uns duzentos anos atrás. Tinha me esquecido completamente disso. Acho que podemos fazer negócio.', '', 28153),
(151901, 'ptBR', 'Já ouviu falar de uma coisa chamada \"Molho Secular\"? Você tem aí?', 'Já ouviu falar de uma coisa chamada \"Molho Secular\"? Você tem aí?', 28153),
(151900, 'ptBR', 'Olá, $r! Você tem alguma coisa interessante para vender?', '', 28153),
(151899, 'ptBR', 'Pelas marés, está vindo!', 'Pelas marés, está vindo!', 28153),
(151898, 'ptBR', 'Fome insaciável, o rei tudo devora.', '', 28153),
(151897, 'ptBR', 'A ferida solta pus. O mundo apodrece.', '', 28153),
(151896, 'ptBR', 'Nós sempre estivemos na sua mente.', '', 28153),
(151895, 'ptBR', 'O grito dos putrefatos anunciará sua chegada.', '', 28153),
(151894, 'ptBR', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|tZanazal, o Sábio, começa a lançar a |cFFFF0000|Hspell:267273|h[Nova Venenosa]|h|r!', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|tZanazal, o Sábio, começa a lançar a |cFFFF0000|Hspell:267273|h[Nova Venenosa]|h|r!', 28153),
(151893, 'ptBR', '', 'Os rastejantes despertaram!', 28153),
(151892, 'ptBR', '', 'Kril lax qutholil!', 28153),
(151890, 'ptBR', 'Você enfrentou as nagas como meu avatar e trouxe um fim ao ataque ao meu templo.', '', 28153),
(151889, 'ptBR', '', 'Uau! Há tempos que eu sonho com o Molho Secular! É um tempero em pasta feito com uma mistura de vários ingredientes, que fica fermentando durante séculos. Quanto maior o tempo de fermentação, maior a complexidade. Dizem que deixa qualquer prato com um inconfundível sabor picante.\n\nParece que é vendido por alguns comerciantes tortollanos, mas é raro e absurdamente caro.\n\n<Xun Xun suspira de melancolia.>\n\nÉ o ingrediente dos sonhos de qualquer chef!', 28153),
(151888, 'ptBR', 'Você tem uma despensa e tanto. Está precisando de alguma especiaria?', 'Você tem uma despensa e tanto. Está precisando de alguma especiaria?', 28153),
(151887, 'ptBR', '', 'Uma cara nova! E que veio em paz. Deseja alguma coisa especial? Ou está em busca de receitas ou especiarias raras?', 28153),
(151886, 'ptBR', 'O Coração de Azeroth está mais forte, graças a ti. Estamos mais perto de curar as feridas de Azeroth.', '', 28153),
(151885, 'ptBR', 'Eu sinto azerita por perto... e também aqueles que querem abusar dela para seus próprios fins. Tu tens que detê-los!', '', 28153),
(151884, 'ptBR', 'Venha, brotinho. Apascente seu coração e me ajude a curar este homem.', '', 28153),
(151883, 'ptBR', '', 'O sangue jorra nas profundezas.', 28153),
(151882, 'ptBR', '', 'Debaixo do mar, jaz a verdade.', 28153),
(151881, 'ptBR', '', 'Ouça a música dos afogados.', 28153),
(151880, 'ptBR', '', 'A escuridão cria raízes. A pestilência se espalha. A porta se abriu.', 28153),
(151879, 'ptBR', '', 'Só de pensar nisso você vai emudecer!', 28153),
(151878, 'ptBR', '', 'Eu vivo dentro do seu peito!', 28153),
(151877, 'ptBR', '', 'Eu aguardo você... nas trevas...', 28153),
(151876, 'ptBR', '', 'Você me pertence!', 28153),
(151875, 'ptBR', '', 'Seus aliados viram você morrer com gosto.', 28153),
(151874, 'ptBR', '', 'Nós estaremos para sempre unidos nas vastas profundezas.', 28153),
(151873, 'ptBR', 'Não há uma qualidade digna de nota em você.', '', 28153),
(151872, 'ptBR', 'Que frágil! É imprestável!', '', 28153),
(151871, 'ptBR', 'Você veio na cepa mais fraca!', '', 28153),
(151870, 'ptBR', 'Como isso é... possível...', '', 28153),
(151869, 'ptBR', 'Ul basha krix.', '', 28153),
(151868, 'ptBR', '', 'Rasguem o céu com fogo! Acabem com eles.', 28153),
(151867, 'ptBR', 'Criaturas inferiores têm que servir... ou morrer!', '', 28153),
(151866, 'ptBR', '', 'Pela Horda!', 28153),
(151865, 'ptBR', '', 'Não tenham misericórdia!', 28153),
(151864, 'ptBR', 'Ug\' crish zul Thraxas!', '', 28153),
(151863, 'ptBR', '', 'Mantenham o fogo! Nossas forças terrestres dependem de você.', 28153),
(151862, 'ptBR', '', 'Continuem atirando!', 28153),
(151861, 'ptBR', 'Esta tumba vai ser teu túmulo!', '', 28153),
(151860, 'ptBR', 'Vocês vão tombar diante dos Zandalari!', '', 28153),
(151859, 'ptBR', 'Este templo tá sob o poder de G\'huun!', '', 28153),
(151858, 'ptBR', 'Os Zandalari vão prevalecer!', '', 28153),
(151857, 'ptBR', '', 'Por aqui! Uma luta gloriosa nos espera!', 28153),
(151856, 'ptBR', 'G\'huun não pode ser detido!', '', 28153),
(151855, 'ptBR', 'Sangre pro Deus do Sangue!', '', 28153),
(151854, 'ptBR', 'Vou dar uma fuçada por conta própria. Quando eu descobrir alguma coisa, tu vai ficar sabendo primeiro.', '', 28153),
(151853, 'ptBR', 'Tu escutou ele! Melhor nós descobrirmos a fonte dessa corrupção de Deus Antigo... para marretarmos o martelo nela!', '', 28153),
(151852, 'ptBR', 'Ha! Se isso era o teu melhor, Zul, não me espanta que o império troll tenha caído!', '', 28153),
(151850, 'ptBR', 'Podia ter metido teu cadáver doente num desses sarcófagos.', '', 28153),
(151849, 'ptBR', 'Glória e honra, eu luto pelo Rastro da Tempestade!', 'Glória e honra, eu luto pelo Rastro da Tempestade!', 28153),
(151848, 'ptBR', 'Minha lâmina é sua.', 'Minha lâmina é sua.', 28153),
(151847, 'ptBR', 'Eu ainda não estou morto!', 'Eu ainda não estou morta!', 28153),
(151846, 'ptBR', 'Nós cuidaremos desses demônios juntos!', 'Nós cuidaremos desses demônios juntos!', 28153),
(151845, 'ptBR', 'O vale permanecerá livre enquanto eu viver!', 'O vale permanecerá livre enquanto eu viver!', 28153),
(151844, 'ptBR', 'Se o Rastro da Tempestade me chamar, eu atenderei.', 'Se o Rastro da Tempestade me chamar, eu atenderei.', 28153),
(151843, 'ptBR', 'É vida ou morte. A nossa hora chegou.', 'É vida ou morte. A nossa hora chegou.', 28153),
(151842, 'ptBR', 'Eu estou com você!', 'Eu estou com você!', 28153),
(151841, 'ptBR', 'É uma pena tu não estar aqui, Zul, para ver teu constructo quebrar.', '', 28153),
(151840, 'ptBR', 'Bah! É o que vamos ver, seu troll frouxo!', '', 28153),
(151839, 'ptBR', 'Logo eles vão se erguer, e todos os que se opõem a G\'huun vão cair!', '', 28153),
(151838, 'ptBR', 'Pode ser que ainda tenhamos chance! Pelo Rastro da Tempestade!', 'Pode ser que ainda tenhamos chance! Pelo Rastro da Tempestade!', 28153),
(151837, 'ptBR', 'Tolos! Meu poder já vinculou os espíritos ancestrais à vontade do meu mestre.', '', 28153),
(151836, 'ptBR', 'Eu ouço a canção da tempestade. Ainda há esperança!', 'Eu ouço a canção da tempestade. Ainda há esperança!', 28153),
(151835, 'ptBR', 'Outros virão. Não estamos todos perdidos!', 'Outros virão. Não estamos todos perdidos!', 28153),
(151834, 'ptBR', 'Não sei que magia de sombras criou raiz aqui, mas é melhor descobrirmos como dissipar.', '', 28153),
(151833, 'ptBR', 'Não é isso que somos. Ainda podemos deter o Lorde Trovamare!', 'Não é isso que somos. Ainda podemos deter o Lorde Trovamare!', 28153),
(151832, 'ptBR', 'De acordo com a minha pesquisa, este é o repouso final do primeiro rei de Zandalar.', '', 28153),
(151831, 'ptBR', 'O portão caiu. Agora avancem! Retomem Arathi para a Aliança!', '', 28153),
(151830, 'ptBR', 'Pique continua vivo? Eu vou atrás dele agora mesmo.', 'Pique continua vivo? Eu vou atrás dele agora mesmo.', 28153),
(151829, 'ptBR', 'O portão caiu. Agora vão, reivindiquem Arathi da Horda!', '', 28153),
(151828, 'ptBR', 'Pronto, os portões caíram. Vão! Vão! Vão!', '', 28153),
(151827, 'ptBR', '', 'Os portões tombaram! Continuem atacando!', 28153),
(151826, 'ptBR', 'O portão já era! Invadam a fortaleza!', '', 28153),
(151825, 'ptBR', 'Pelo bem de Zandalar... e dos seus reinos também... você tem que impedir ele.', '', 28153),
(151824, 'ptBR', 'Os portões caíram! Vamos tomar a fortaleza!', '', 28153),
(151823, 'ptBR', 'Temos que abrir o Santuário da Tempestade imediatamente!', 'Temos que abrir o Santuário da Tempestade imediatamente!', 28153),
(151822, 'ptBR', 'O mestre dele se fortalece mais e mais. Zul não vai descansar enquanto o mundo inteiro não estiver nas garras do Deus do Sangue.', '', 28153),
(151821, 'ptBR', 'Acabou. Arathi é nossa mais uma vez. Pela Aliança!', '', 28153),
(151820, 'ptBR', 'A tempestade despertou dentro de mim. Eu lutarei contra as sombras!', 'A tempestade despertou dentro de mim. Eu lutarei contra as sombras!', 28153),
(151819, 'ptBR', '', 'Nossa vitória sempre foi certeza. Pela Horda!', 28153),
(151818, 'ptBR', 'Tu me libertou duma sina cruel, mas Zul não passa de um fantoche num drama muito maior.', '', 28153),
(151817, 'ptBR', 'Volta pro teu mestre pra ver como ele trata os fracassados!', '', 28153),
(151816, 'ptBR', 'Eu sabia que esse dia iria chegar. Eu me juntarei aos outros.', 'Eu sabia que esse dia iria chegar. Eu me juntarei aos outros.', 28153),
(151815, 'ptBR', 'Impossível! O G\'huun não vai ser rejeitado!', '', 28153),
(151814, 'ptBR', 'Você rompeu o domínio de Zul! Eu não sirvo mais àquele porco!', '', 28153),
(151813, 'ptBR', 'Reclame o quanto quiser, meu rei... mas tu deveria ter sacado que não havia como escapar de G\'huun.', '', 28153),
(151812, 'ptBR', 'Os intrusos vão morrer... mas eu não tenho por que tolerar a sua lenga-lenga enquanto cuido disso.', '', 28153),
(151811, 'ptBR', 'Eu não passei a vida toda resistindo ao seu mestre para você me curvar à vontade dele na morte.', '', 28153),
(151810, 'ptBR', 'Silêncio, falso profeta!', '', 28153),
(151809, 'ptBR', 'Este é o lugar de descanso do primeiro rei de Zandalar. Dazar era teimoso... só que agora ele é um servo!', '', 28153),
(151808, 'ptBR', 'Você perdeu o juízo?', 'Você perdeu o juízo?', 28153),
(151807, 'ptBR', 'Diga o que quer.', 'Diga o que quer.', 28153),
(151806, 'ptBR', 'Só que, na morte, eu os vinculei a um único propósito. Te matar.', '', 28153),
(151805, 'ptBR', 'A terra me leva.', 'A terra me leva.', 28153),
(151804, 'ptBR', 'Eles se odiavam em vida e acabaram se destruindo mutuamente.', '', 28153),
(151803, 'ptBR', 'Você se aproxima de três soberanos que controlaram o império num tempo em que nenhum troll foi capaz de controlar o trono.', '', 28153),
(151802, 'ptBR', 'Não permitimos gente de fora aqui.', 'Não permitimos gente de fora aqui.', 28153),
(151801, 'ptBR', 'Os mares vão recuar, a terra vai se erguer!', 'Os mares recuam e a terra vai se erguer!', 28153),
(151800, 'ptBR', 'Sei que não terei problemas em descartar você.', '', 28153),
(151799, 'ptBR', 'Enquanto os mortos sufocavam nos templos, golens foram construídos para descartar os corpos contaminados.', '', 28153),
(151798, 'ptBR', 'Milhares de anos atrás, uma moléstia do sangue quase varreu os Zandalari.', '', 28153),
(151797, 'ptBR', 'Logo eles vão se erguer, e todos os que se opõem a G\'huun vão cair!', '', 28153),
(151796, 'ptBR', 'Meu poder já criou raízes, atando os espíritos ancestrais à vontade do meu mestre.', '', 28153),
(151795, 'ptBR', 'Boas-vindas à tumba do primeiro rei troll. Queria poder estar lá para receber você pessoalmente.', '', 28153),
(151794, 'ptBR', 'Eu já disse, não vou tomar parte nessa loucura!', 'Eu já disse, não vou tomar parte nessa loucura!', 28153),
(151793, 'ptBR', 'Não vou cair nessa de novo.', 'Não vou cair nessa de novo.', 28153),
(151792, 'ptBR', 'Mas... é seguro?', 'Mas... é seguro?', 28153),
(151791, 'ptBR', 'Somos empreendedores e especialistas em recolocação. Não temos nada a ver com esses mercenários de vermelho. Não somos piratas.', '', 28153),
(151790, 'ptBR', '', 'Vamos voltar até Katherine.', 28153),
(151789, 'ptBR', '', 'Vocês três. Formem uma equipe de busca e desçam lá para encontrá-la!', 28153),
(151788, 'ptBR', '', 'Espera, não!', 28153),
(151787, 'ptBR', '', 'RATO insolente. Isso não vai ficar assim!', 28153),
(151786, 'ptBR', '', 'Acabou. Você não tem para onde correr.', 28153),
(151785, 'ptBR', '', 'Sai da reta, cabeça-de-minhoca!', 28153),
(151784, 'ptBR', '', 'Toma isso!', 28153),
(151783, 'ptBR', '', 'Seu truquezinho não adiantou nada! A cidade é MINHA!', 28153),
(151782, 'ptBR', 'Vou esperar aqui, caso um deles consiga voltar para casa.', '', 28153),
(151781, 'ptBR', '', 'As coisas vão ser muito melhores quando eu for Chefe.\n\nDepois que esses piratas Maré-férrea forem varridos daqui, todo mundo vai poder comprar e vender sem problemas. Vai ser ótimo!', 28153),
(151780, 'ptBR', '', 'Ugh! Tudo era melhor antes desses idiotas de vermelho aparecerem por aqui.', 28153),
(151779, 'ptBR', 'Olha, só estou tentando trabalhar.', '', 28153),
(151778, 'ptBR', 'Vergavela e seu povo atrapalham os negócios. Se a coisa piorar muito, vou pegar minhas aves e meter o pé.', '', 28153),
(151777, 'ptBR', 'Eu ia ser rico...', '', 28153),
(151776, 'ptBR', 'Você tá querendo atrapalhar nosso esquema? Já matei por muito menos!', '', 28153),
(151775, 'ptBR', '', 'Você não vai tomar esse bosque!', 28153),
(151774, 'ptBR', '', 'Obrigada. Achei que dava pra encarar eles sozinha. Vou voltar para Morwin.', 28153),
(151773, 'ptBR', 'Nossa, adorei a casa.', '', 28153),
(151772, 'ptBR', 'Nós, tortollanos, comerciamos neste local durante muito tempo. Os zandalari chegaram e trouxeram tempos difíceis junto com eles. Mas nós vamos permanecer, é claro.', '', 28153),
(151771, 'ptBR', 'Eu trabalho aqui. Não preciso ir para estrada perigosa.', '', 28153),
(151770, 'ptBR', 'Lok-tar ogar!', 'Lok-tar ogar!', 28153),
(151769, 'ptBR', 'Lok-narash!', 'Lok-narash!', 28153),
(151768, 'ptBR', 'Gakarah ma!', 'Gakarah ma!', 28153),
(151767, 'ptBR', 'Caia aos pés da Horda!', 'Caia aos pés da Horda!', 28153),
(151766, 'ptBR', 'Pela Horda!', 'Pela Horda!', 28153),
(151765, 'ptBR', 'Morte aos inimigos!', 'Morte aos inimigos!', 28153),
(151764, 'ptBR', 'Você não passa de hoje!', 'Você não passa de hoje!', 28153),
(151763, 'ptBR', 'Uma... morte... honrada...', 'Uma... morte... honrada...', 28153),
(151762, 'ptBR', 'Ah, chegou para o serviço, afinal. Coloque isso no baú e vá trabalhar!', '', 28153),
(151761, 'ptBR', 'Ancestrais... estou chegando...', 'Ancestrais... estou chegando...', 28153),
(151760, 'ptBR', 'Você vai perder... a guerra...', 'Você vai perder... a guerra...', 28153),
(151759, 'ptBR', 'Seu fim... vai chegar...', 'Seu fim... vai chegar...', 28153),
(151758, 'ptBR', 'Eu morro... como um guerreiro...', 'Eu morro... como uma guerreira...', 28153),
(151757, 'ptBR', 'Minha batalha... terminou...', 'Minha batalha... terminou...', 28153),
(151756, 'ptBR', 'Meu espírito volta... a Draenor...', 'Meu espírito volta... a Draenor...', 28153),
(151755, 'ptBR', 'Morra bem.', 'Morra bem.', 28153),
(151754, 'ptBR', 'Não tenho mais nada a dizer.', 'Não tenho mais nada a dizer.', 28153),
(151753, 'ptBR', 'Cace seu rumo.', 'Cace seu rumo.', 28153),
(151752, 'ptBR', 'Vá com honra.', 'Vá com honra.', 28153),
(151751, 'ptBR', 'Que sua lâmina nunca perca o fio.', 'Que sua lâmina nunca perca o fio.', 28153),
(151750, 'ptBR', 'Vá buscar a vitória.', 'Vá buscar a vitória.', 28153),
(151749, 'ptBR', 'Vai ser assim então.', 'Vai ser assim então.', 28153),
(151748, 'ptBR', 'Fale.', 'Fale.', 28153),
(151747, 'ptBR', 'Bom te ver.', 'Bom te ver.', 28153),
(151746, 'ptBR', 'Lok-tar!', 'Lok-tar!', 28153),
(151745, 'ptBR', 'Throm-ka!', 'Throm-ka!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151744, 'ptBR', 'Do que você precisa?', 'Do que você precisa?', 28153),
(151743, 'ptBR', 'Zug-zug.', 'Zug-zug.', 28153),
(151742, 'ptBR', 'Força e honra.', 'Força e honra.', 28153),
(151741, 'ptBR', 'Compre mais na próxima.', 'Compre mais na próxima.', 28153),
(151740, 'ptBR', 'Tomara que você aproveite bem.', 'Tomara que você aproveite bem.', 28153),
(151739, 'ptBR', 'Sem devoluções!', 'Sem devoluções!', 28153),
(151738, 'ptBR', 'O que está procurando?', 'O que você está procurando?', 28153),
(151737, 'ptBR', 'Do que você precisa?', 'Do que você precisa?', 28153),
(151736, 'ptBR', 'Dá uma olhada.', 'Dá uma olhada.', 28153),
(151735, 'ptBR', 'Todo mundo em Azeroth é aporrinhante desse jeito?', 'Todo mundo em Azeroth é aporrinhante desse jeito?', 28153),
(151734, 'ptBR', 'Meu passatempo é matar coisas que me incomodam. Você TEM CERTEZA que quer continuar me enchendo?', 'Meu passatempo é matar coisas que me incomodam. Você TEM CERTEZA que quer continuar me enchendo?', 28153),
(151733, 'ptBR', 'Olha, cara, você está me dando nos nervos! Você não vai gostar nada-nada de me ver nervoso.', 'Olha, cara, você tá me dando nos nervos! Você não vai gostar nada-nada de me ver nervosa.', 28153),
(151732, 'ptBR', 'ORC... ESMAGA!!!!!', 'ORQUISA... ESMAGA!!!!!', 28153),
(151731, 'ptBR', 'Venha... venha, meu querido Reban. Hora de comer!', '', 28153),
(151730, 'ptBR', '<Som de aplausos>', '', 28153),
(151729, 'ptBR', '<Bocejo>', '', 28153),
(151728, 'ptBR', '<Comemoração curta - Uuuuh!>', '', 28153),
(151727, 'ptBR', '<Comemoração um pouco mais longa - Uhuu!>', '', 28153),
(151726, 'ptBR', '<Som de galinha>', '', 28153),
(151725, 'ptBR', '<Som de choro>', '', 28153),
(151724, 'ptBR', '<Sons de choro; variação>', '', 28153),
(151723, 'ptBR', '<Sons de choro; variação>', '', 28153),
(151722, 'ptBR', '<Beijo>', '', 28153),
(151721, 'ptBR', '<Som de risada>', '', 28153),
(151720, 'ptBR', '<Risada>', '', 28153),
(151719, 'ptBR', '<Soltar um muxoxo com os beiços: Pfffthblth!>', '', 28153),
(151718, 'ptBR', '<Rugido dominante>', '', 28153),
(151717, 'ptBR', '<Rugido; variação>', '', 28153),
(151716, 'ptBR', '<Suspiro>', '', 28153),
(151715, 'ptBR', '<Barulhos de trem: xique-xique chu-chu!>', '', 28153),
(151714, 'ptBR', 'Eu... me arrependi.', '', 28153),
(151713, 'ptBR', 'Patético! Você tombará aos pés dos Mag\'har!', '', 28153),
(151712, 'ptBR', 'Sou grato.', '', 28153),
(151711, 'ptBR', 'Eu lhe agradeço.', '', 28153),
(151710, 'ptBR', 'Eu lhe devo uma.', '', 28153),
(151709, 'ptBR', 'Você cairá aos meus pés!', '', 28153),
(151708, 'ptBR', 'Pelas luas de Draenor!', '', 28153),
(151707, 'ptBR', 'Eu só cumpri meu dever.', '', 28153),
(151706, 'ptBR', 'Não me peça isso outra vez.', '', 28153),
