(151628, 'ptBR', 'Está recarregando.', '', 28153),
(151627, 'ptBR', 'Não deixe a pólvora molhar.', 'Não deixe a pólvora molhar.', 28153),
(151626, 'ptBR', 'Sempre leal.', 'Sempre leal.', 28153),
(151625, 'ptBR', 'Desce o lastro e sobe o mastro.', 'Desce o lastro e sobe o mastro.', 28153),
(151624, 'ptBR', 'A maré não espera.', 'A maré não espera.', 28153),
(151623, 'ptBR', 'Invém tempestade. Dá pra sentir nas veias.', 'Invém tempestade. Dá pra sentir nas veias.', 28153),
(151622, 'ptBR', 'O conventículo vai cair.', 'O conventículo vai cair.', 28153),
(151621, 'ptBR', 'Bruxa boa é bruxa morta.', 'Bruxa boa é bruxa morta.', 28153),
(151620, 'ptBR', 'Glória à Casa Capelo.', 'Glória à Casa Capelo.', 28153),
(151619, 'ptBR', 'O vento te leve com âncora firme.', 'O vento te leve com âncora firme.', 28153),
(151618, 'ptBR', 'Olho aberto pro tempo certo.', 'Olho aberto pro tempo certo.', 28153),
(151617, 'ptBR', 'Bons ventos e mares tranquilos.', 'Bons ventos e mares tranquilos.', 28153),
(151616, 'ptBR', 'Por Kul Tiraz!', 'Por Kul Tiraz!', 28153),
(151615, 'ptBR', 'Não posso saquear isso no momento.', '', 28153),
(151614, 'ptBR', 'Não tenho nenhum alvo.', '', 28153),
(151613, 'ptBR', 'Preciso de um alvo antes.', '', 28153),
(151612, 'ptBR', 'Preciso de um alvo.', '', 28153),
