(151610, 'ptBR', 'Preciso de permissão para isso.', '', 28153),
(151609, 'ptBR', 'Não posso atacar esse alvo.', '', 28153),
(151608, 'ptBR', 'Não posso atacar isso.', '', 28153),
(151607, 'ptBR', 'Meu inventário está cheio.', '', 28153),
(151606, 'ptBR', 'Não posso carregar mais.', '', 28153),
(151605, 'ptBR', 'Está trancado.', '', 28153),
(151604, 'ptBR', 'Não tenho como carregar mais disso.', '', 28153),
(151603, 'ptBR', 'Stromgarde ainda está frágil e não vai conseguir resistir a um ataque direto de demolidores. Destruam eles antes que se aproximem!', '', 28153),
(151602, 'ptBR', 'Ainda não posso usar esse item.', '', 28153),
(151601, 'ptBR', 'Ainda não está pronto.', '', 28153),
(151600, 'ptBR', 'Esse item ainda está recarregando.', '', 28153),
(151599, 'ptBR', 'Nossas fortificações ainda estão frágeis. Rápido, destruam esses demolidores antes que cheguem mais perto!', '', 28153),
(151598, 'ptBR', 'Fúria insuficiente.', '', 28153),
(151597, 'ptBR', 'Minha fúria está baixa.', '', 28153),
(151596, 'ptBR', 'Não tenho dor suficiente.', '', 28153),
(151595, 'ptBR', 'Minha dor está baixa.', '', 28153),
(151594, 'ptBR', 'Isso não é uma bolsa.', '', 28153),
(151593, 'ptBR', 'Precisamos deter esses demolidores antes que consigam nos demolir!', '', 28153),
(151592, 'ptBR', 'Me falta o dinheiro.', '', 28153),
(151591, 'ptBR', 'Não tenho como pagar.', '', 28153),
(151590, 'ptBR', '', 'Ativem os demolidores, agora! Não podemos permitir que a Aliança garanta uma posição!', 28153),
(151589, 'ptBR', 'Caro demais.', '', 28153),
(151588, 'ptBR', 'Tu nunca viu pança de kraken? Continua assim e vai ver logo mais.', 'Tu nunca viu pança de kraken? Continua assim e vai ver logo mais.', 28153),
(151587, 'ptBR', 'Mandem os demolidores! Temos que esmagar esses insetos da Aliança antes que eles esmaguem a gente!', '', 28153),
(151586, 'ptBR', 'Tu tem cara de quem pula da prancha pelo lado errado.', 'Tu tem cara de quem pula da prancha pelo lado errado.', 28153),
(151585, 'ptBR', 'Traga os demolidores! Os muros de Stromgarde vão ruir diante da força da Horda!', '', 28153),
(151584, 'ptBR', 'Iaar! Larga do meu pé ou te passo na querena!', 'Iaar! Larga do meu pé ou te passo na querena!', 28153),
(151583, 'ptBR', 'Máquinas de cerco! Transformem eles em cinzas!', '', 28153),
(151582, 'ptBR', 'Seus vermes sem vergonha, vocês não têm direito de estar aqui.', '', 28153),
(151581, 'ptBR', '', 'Eles trouxeram máquinas de cerco! Precisamos destruir essas coisas antes que cheguem perto da nossa base.', 28153),
(151580, 'ptBR', 'Essa é uma arma de duas mãos.', '', 28153),
(151579, 'ptBR', 'Essa habilidade não está pronta.', '', 28153),
(151578, 'ptBR', 'Ainda não posso fazer isso.', '', 28153),
(151577, 'ptBR', 'Ainda não está pronto.', '', 28153),
(151576, 'ptBR', 'Não posso colocar isso ali.', '', 28153),
(151575, 'ptBR', 'A bolsa está cheia.', '', 28153),
(151574, 'ptBR', 'Não posso fazer isso aqui.', '', 28153),
(151573, 'ptBR', 'Não posso largar isso.', '', 28153),
(151572, 'ptBR', 'Isso está vinculado a mim.', '', 28153),
(151571, 'ptBR', 'Não posso usar isso.', '', 28153),
(151570, 'ptBR', 'Não tenho nível suficiente para usar isso.', '', 28153),
(151569, 'ptBR', 'Ainda não posso usar isso.', '', 28153),
(151568, 'ptBR', 'Não tenho nível de perícia suficiente para usar isso.', '', 28153),
(151567, 'ptBR', 'Nunca vou poder usar isso.', '', 28153),
(151566, 'ptBR', 'Uma coisa de cada vez. Precisamos de madeira da Serraria Terras Altas. Também precisamos de ferro, que dá para conseguir no Veio do Galson.', '', 28153),
(151565, 'ptBR', 'Não posso aprender esse feitiço.', '', 28153),
(151564, 'ptBR', 'Aí que você se engana, Lady Liadrin. As bandeiras da Aliança vão tremular sobre Arathi mais uma vez.', '', 28153),
(151563, 'ptBR', '', 'Encerre esta farsa, Danath. O direito dos Matatrolls sobre esta terra acabou há muitos anos.', 28153),
(151562, 'ptBR', 'Não posso saquear isso.', '', 28153),
(151561, 'ptBR', 'Isso não é meu.', '', 28153),
(151560, 'ptBR', 'Preciso chegar mais perto.', '', 28153),
(151559, 'ptBR', 'Prazer nenhum da minha parte, caçador sombrio.', '', 28153),
(151558, 'ptBR', 'Está longe demais.', '', 28153),
(151557, 'ptBR', 'Não consigo alcançar.', '', 28153),
(151556, 'ptBR', 'Danath Matatroll. Que prazer finalmente te conhecer...', '', 28153),
(151555, 'ptBR', 'Não posso trocar isso.', '', 28153),
(151554, 'ptBR', 'Não posso usar isso.', '', 28153),
(151553, 'ptBR', 'Não estou equipado com o item.', '', 28153),
(151552, 'ptBR', 'Não, Arathi é minha. Você e sua Horda vão pagar caro pela invasão, Eitrigg.', '', 28153),
(151551, 'ptBR', 'Preciso me equipar primeiro.', '', 28153),
(151550, 'ptBR', 'Matatroll! Segue teu rumo. Arathi é da Horda agora.', '', 28153),
(151549, 'ptBR', 'Mas antes é preciso fortificar nossa posição. Tragam madeira e ferro.', '', 28153),
(151548, 'ptBR', 'Arrebentem o inimigo!', '', 28153),
(151547, 'ptBR', 'Com certeza, Lady Liadrin. Mal posso esperar para exercer justiça contra uma paladina desencaminhada a serviço da Horda.', '', 28153),
(151546, 'ptBR', 'No meu alvo!', '', 28153),
(151545, 'ptBR', 'Derrubem o inimigo!', '', 28153),
(151544, 'ptBR', 'Vem por aqui.', '', 28153),
(151543, 'ptBR', 'Deixem o orc liderar.', '', 28153),
(151542, 'ptBR', '', 'Turalyon? Isso será interessante...', 28153),
(151541, 'ptBR', 'Vem comigo.', '', 28153),
(151540, 'ptBR', 'Pela Horda!', '', 28153),
(151539, 'ptBR', 'Me acertaram!', '', 28153),
(151538, 'ptBR', 'Curandeiro, uma ajuda!', '', 28153),
(151537, 'ptBR', 'Não fique só olhando, me ajude!', '', 28153),
(151536, 'ptBR', 'Ajude aqui!', '', 28153),
(151535, 'ptBR', 'Aguente aí.', '', 28153),
(151534, 'ptBR', 'Não saia daqui.', '', 28153),
(151533, 'ptBR', 'A luz está conosco, Rokhan. Não temos medo das sombras.', '', 28153),
(151532, 'ptBR', 'Cuidado com as sombras, Turalyon. Eu e a Horda vamo pegar vocês...', '', 28153),
(151531, 'ptBR', 'Morram com honra!', '', 28153),
(151530, 'ptBR', 'Atacar!', '', 28153),
(151529, 'ptBR', 'Mok-thora ka!', '', 28153),
(151528, 'ptBR', 'Esmaguem nossos inimigos!', '', 28153),
(151527, 'ptBR', 'Vou livrar as colinas de Arathi de você e do exército da Horda, Eitrigg.', '', 28153),
(151526, 'ptBR', 'Quebrem a formação deles!', '', 28153),
(151525, 'ptBR', 'Recuem ou morram!', '', 28153),
(151524, 'ptBR', 'Vamos lutar outro dia!', '', 28153),
(151523, 'ptBR', 'Vai! Corre daqui!', '', 28153),
(151522, 'ptBR', 'Tô sentindo fedor de escória da Aliança no meu campo de batalha. Hora de lutar.', '', 28153),
(151521, 'ptBR', 'Preparem-se!', '', 28153),
(151520, 'ptBR', 'Verifique constantemente. A gente não pode se dar ao luxo de desperdiçar o ferro desse baú.', '', 28153),
(151519, 'ptBR', 'Queimem todos !', '', 28153),
(151518, 'ptBR', 'Abrir fogo!', '', 28153),
(151517, 'ptBR', 'Eles já estão chegando. Temos que construir a base, e para isso precisamos de madeira e ferro.', '', 28153),
(151516, 'ptBR', 'Eu vou é sentar o braço pra tirar esses estrupícios da Horda daqui ligeiro! Rá!', '', 28153),
(151515, 'ptBR', '', 'Baixe as armas, Muradin. Esse território pertence à Horda.', 28153),
(151514, 'ptBR', 'Pues que não, tô procurando uns piá da Horda pra passar no meu novo facão, tchê!', '', 28153),
(151513, 'ptBR', 'Tá fazendo o que aqui, Muradin? Procurando encrenca?', '', 28153),
(151512, 'ptBR', 'Por que tu não volta pra sua charneca malcheirosa, seu orc pelotudo!', '', 28153),
(151511, 'ptBR', 'Muradin! Seus anões pisaram fora da estância. Volte logo pra sua montanha.', '', 28153),
(151510, 'ptBR', '', 'A Aliança logo estará aqui. Precisamos ser rápidos. Façam um estoque de madeira e ferro para estabelecer uma posição.', 28153),
(151509, 'ptBR', '', 'Não se iluda, velhote. Estamos aqui para retomar Stromgarde.', 28153),
(151508, 'ptBR', 'Lady Liadrin! Bem-vinda a Arathi. Veio aqui para se render, certo?', '', 28153),
(151507, 'ptBR', '', 'Você ficou afastado por muito tempo, Turalyon. O mundo continuou girando sem você.', 28153),
(151506, 'ptBR', 'O quê? Invasores da Horda comandados por uma paladina? Onde este mundo vai parar?', '', 28153),
(151505, 'ptBR', '', 'Quero ver você conseguir, Muradin. Isso aqui é território da Horda.', 28153),
(151504, 'ptBR', 'Melhor apear aqui, vivente, se não quiser levar uma chuva de morteiros da Aliança na cabeça.', '', 28153),
(151503, 'ptBR', 'Danath Matatroll, temos um assunto a tratar! Te vejo no campo de batalha...', '', 28153),
(151502, 'ptBR', 'Vocês ousam invadir Arathi e ainda trazem um TROLL como comandante? Cometeram um grave erro.', '', 28153),
(151501, 'ptBR', '\"Pele verde?\" Assim você me ofende...', '', 28153),
(151500, 'ptBR', 'Recuperando', 'Recuperando', 28153),
(151499, 'ptBR', '<Claus dá uma risada>\n\nProvavelmente. Tenho parentes para tudo quanto é lado.', '', 28153),
(151498, 'ptBR', 'Como ousam invadir Stromgarde, lar dos Matatrolls? Sai da minha frente, pele verde.', '', 28153),
(151497, 'ptBR', 'Hoje vamos reivindicar o que é nosso por direito! Pela Aliança!', '', 28153),
(151496, 'ptBR', 'Stromgarde já foi sugada pelos invasores tempo demais.', '', 28153),
(151495, 'ptBR', 'Pela Aliança!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151494, 'ptBR', 'Soldados da Aliança! Hoje vamos retomar a nobre cidade de Stromgarde da Horda monstruosa.', '', 28153),
(151493, 'ptBR', 'Hoje nós vamos retomar as colinas de Arathi... Pela Aliança!', '', 28153),
(151492, 'ptBR', 'Carreguem os fuzis e façam a defesa.', '', 28153),
(151491, 'ptBR', '', 'Arathi será nossa! Pela Horda!', 28153),
(151490, 'ptBR', '', 'Preste atenção no que é preciso fazer. Primeiro, capturamos Ar\'gorok, depois rumamos para Stromgarde!', 28153),
(151489, 'ptBR', 'Belvento? Conheço alguém com esse nome.', 'Belvento? Conheço alguém com esse nome.', 28153),
(151488, 'ptBR', 'Juntem tudo, rapazes! Vamos tirar essas armas daqui!', '', 28153),
(151487, 'ptBR', 'A Bastilha de Stromgarde agora é um Castelo.', '', 28153),
(151486, 'ptBR', 'Terminamos a construção da Armaria.', '', 28153),
(151485, 'ptBR', 'A oficina está preparada.', '', 28153),
(151484, 'ptBR', 'Nossa Prefeitura agora é uma Bastilha.', '', 28153),
(151483, 'ptBR', 'O Altar dos Reis está concluído.', '', 28153),
(151482, 'ptBR', 'Nossa Bastilha agora é um Castelo!', '', 28153),
(151481, 'ptBR', 'A armaria foi construída.', '', 28153),
(151480, 'ptBR', 'A oficina está pronta para construir nossos tanques.', '', 28153),
(151479, 'ptBR', 'Nossa Prefeitura foi transformada em Bastilha.', '', 28153),
(151478, 'ptBR', 'O Altar dos Reis está concluído.', '', 28153),
(151477, 'ptBR', 'É isso aí! Transformamos nossa Bastilha em um Castelo!', '', 28153),
(151476, 'ptBR', 'A Armaria está pronta para equipar nossas forças!', '', 28153),
(151475, 'ptBR', 'A oficina está pronta e operacional. Hora de construir os tanques!', '', 28153),
(151474, 'ptBR', 'A Prefeitura foi transformada em Bastilha!', '', 28153),
(151473, 'ptBR', 'O Altar dos Reis tá pronto!', '', 28153),
(151472, 'ptBR', '', 'Nosso Baluarte agora é uma Fortaleza. Pela Horda!', 28153),
(151471, 'ptBR', '', 'Com a nova armaria poderemos equipar melhor nossas tropas.', 28153),
(151470, 'ptBR', '', 'A oficina está completa.', 28153),
(151469, 'ptBR', '', 'Nossa base está mais forte. O Grande Salão agora é um Baluarte.', 28153),
(151468, 'ptBR', '', 'O Altar das Tempestades está pronto.', 28153),
(151467, 'ptBR', 'Nosso Quartel está pronto para treinar nossas forças.', '', 28153),
(151466, 'ptBR', 'Nosso quartel está pronto. Hora de treinar nossas tropas.', '', 28153),
(151465, 'ptBR', 'Nós temos um quartel! Comece a treinar tropas!', '', 28153),
(151464, 'ptBR', '', 'O quartel está pronto para treinar nossos soldados.', 28153),
(151463, 'ptBR', 'O Baluarte virou uma Fortaleza!', '', 28153),
(151462, 'ptBR', 'Tamos melhorando o Grande Salão pra um Baluarte.', '', 28153),
(151461, 'ptBR', 'O Altar das Tempestades tá pronto.', '', 28153),
(151460, 'ptBR', 'O quartel tá pronto. Vamos ganhar essa guerra nas costas dos brutos.', '', 28153),
(151459, 'ptBR', 'Nosso baluarte agora é uma fortaleza!', '', 28153),
(151458, 'ptBR', 'Nossa grande salão agora é um baluarte!', '', 28153),
(151457, 'ptBR', 'O Altar das Tempestades foi concluído.', '', 28153),
(151456, 'ptBR', 'Nós temos um quartel, agora vai treinar esses brutos!', '', 28153),
(151455, 'ptBR', '', 'Nem pensar! Cavaleiros Sangrentos, acabem com eles!', 28153),
(151454, 'ptBR', 'E eu não sou chamado de caçador sombrio à toa. Assassinos, apareçam agora!', '', 28153),
(151453, 'ptBR', 'Eu conheço bem a \"justiça da Aliança\". Mantícoras, mostrem a eles a fúria da Horda!', '', 28153),
(151452, 'ptBR', '', 'Nunca!', 28153),
(151451, 'ptBR', 'Nem um grão desta terra é teu, Matatroll. Os trolls já tavam aqui muito antes de vocês.', '', 28153),
(151450, 'ptBR', 'Hah! Isso é o que você pensa.', '', 28153),
(151449, 'ptBR', '', 'Já estou farta da sua falação. Cavaleiros Sangrentos, ataquem com a fúria da Luz!', 28153),
(151448, 'ptBR', 'A Luz não vai te salvar agora. Caçadores Sombrios, apresentem-se!', '', 28153),
(151447, 'ptBR', 'Mantícoras, iniciar ataque dos céus!', '', 28153),
(151446, 'ptBR', '', 'É o que veremos, Turalyon. Você ainda tem que lidar comigo.', 28153),
(151445, 'ptBR', 'E eu vou estar esperando.', '', 28153),
(151444, 'ptBR', 'Não se eu puder ajudar, Turalyon.', '', 28153),
(151443, 'ptBR', '', 'Não será suficiente, anão. Cavaleiros Sangrentos, às armas!', 28153),
(151442, 'ptBR', 'Tu caiu bonito na minha armadilha, Muradin! Caçadores Sombrios, apresentem-se!', '', 28153),
(151441, 'ptBR', 'Agora, mantícoras! Ataquem!', '', 28153),
(151440, 'ptBR', '', 'Nunca.', 28153),
(151439, 'ptBR', 'Fica esperto, Muradin!', '', 28153),
(151438, 'ptBR', 'Por pouco tempo, anão. Pela Horda!', '', 28153),
(151437, 'ptBR', 'Já perdi essa cidade um vez, não vou perder de novo. Não para a sua laia. Defensores, mostrem a força de Stromgarde!', '', 28153),
(151436, 'ptBR', 'Eu tô seguro agora. Vou trabalhar.', '', 28153),
(151435, 'ptBR', 'A Luz está ao meu lado. Defensores, avante!', '', 28153),
(151434, 'ptBR', 'Defenderei Stromgarde até a morte, Liadrin. Defensores, aguentem firme!', '', 28153),
(151433, 'ptBR', 'Não comemore cedo demais, elfo sangrento. Você ainda precisa negociar comigo.', '', 28153),
(151432, 'ptBR', 'Estou contando com isso.', '', 28153),
(151431, 'ptBR', 'Haha! O terreno mais alto não é nada demais!', '', 28153),
(151430, 'ptBR', 'Este velho tolo ainda tem alguns truques na manga, troll. Defensores, mostrem a força de Stromgarde!', '', 28153),
(151429, 'ptBR', 'A Luz sempre derrotará a Sombra, Rokhan. Defensores, avante!', '', 28153),
(151428, 'ptBR', 'Vem pra peleia, Rokhan! Tava te esperando, mesmo. Defensores, mostrem como é que fazemos!', '', 28153),
(151427, 'ptBR', 'Cala a boca, troll. A Aliança vai derrotar o seu exército de monstros nojento.', '', 28153),
(151426, 'ptBR', 'E a Luz ainda brilha sobre Stromgarde.', '', 28153),
(151425, 'ptBR', 'Em breve, guri. Vou mandar meus carabineiros irem devagar no começo.', '', 28153),
(151424, 'ptBR', 'Stromgarde continua de pé, orc. Vou adorar ver o seu cadáver flutuando no meu fosso. Defensores, mostrem a força da nossa cidade!', '', 28153),
(151423, 'ptBR', 'Venci e perdi mais batalhas do que você verá em toda a sua vida, Eitrigg. E esta aqui está longe de acabar. Defensores, avante!', '', 28153),
(151422, 'ptBR', 'Tu vai precisar passar por nós primeiro, guria. Defensores, botem eles para correr!', '', 28153),
(151421, 'ptBR', 'Pfff, vocês são todos iguais. Você vai morrer de joelhos, como todos os outros.', '', 28153),
(151420, 'ptBR', 'Tenha paciência, orc. Não vai demorar muito mais.', '', 28153),
(151419, 'ptBR', 'Eu tô sentindo o seu bafo daqui! Vem pra peleia, orc!', '', 28153),
(151418, 'ptBR', 'Agora, máquinas de cerco, destruam o portão. Quero a cabeça daquela elfa sangrenta na ponta duma lança!', '', 28153),
(151417, 'ptBR', 'Agora, máquinas de cerco, destruam o portão e me tragam Rokhan! Não me chamam de Matatroll à toa...', '', 28153),
(151416, 'ptBR', 'Agora, máquinas de cerco, destruam o portão. Esse orc imundo vai provar o gosto da justiça da Aliança!', '', 28153),
(151415, 'ptBR', 'Alcândora é nossa. Essa é sua última chance, elfa sangrenta. Renda-se, e talvez eu poupe a sua vida.', '', 28153),
(151414, 'ptBR', 'Já asseguramos Alcândora. O saque de Ar\'gorok é só questão de tempo. Vamos tomar o que é nosso por direito!', '', 28153),
(151413, 'ptBR', 'Alcândora é nossa. Esses invasores não perdem por esperar.', '', 28153),
(151412, 'ptBR', 'O controle do Veio do Galson garante suprimento infinito de ferro. O que vai ser muito útil.', '', 28153),
(151411, 'ptBR', 'Perfeito. A Serraria Terras Altas tem toda a madeira de que precisamos para reconstruir Stromgarde.', '', 28153),
(151410, 'ptBR', 'Esta é a nossa chance. Cerquem o portão! Vinguem-se dos invasores da Horda!', '', 28153),
(151409, 'ptBR', 'Essa é a nossa chance. Cerquem o portão! A luz veio pegar você, Rokhan!', '', 28153),
(151408, 'ptBR', 'Essa é a nossa chance. Cerquem o portão! Sua hora chegou, Eitrigg!', '', 28153),
(151407, 'ptBR', 'Alcândora foi capturada! A Luz está do lado da Aliança.', '', 28153),
(151406, 'ptBR', 'Alcândora é nossa, e Ar\'gorok logo será a próxima. Em breve será sua vez, Rokhan.', '', 28153),
(151405, 'ptBR', 'Asseguramos Alcândora. Em breve vamos acabar de vez com as forças da Horda.', '', 28153),
(151404, 'ptBR', 'Excelente. Com o Veio do Galson, o suprimento de ferro está garantido.', '', 28153),
(151403, 'ptBR', 'A madeira dessa serraria será crucial para a construção da nossa base.', '', 28153),
(151402, 'ptBR', 'Rápido, tragam as máquinas de cerco! Derrubem o portão! Vamos dar uma tunda de laço nessa elfa sangrenta!', '', 28153),
(151401, 'ptBR', 'Rápido, tragam as máquinas de cerco! Derrubem o portão! Vamos fazer churrasco de troll!', '', 28153),
(151400, 'ptBR', 'Rápido, tragam as máquinas de cerco! Derrubem o portão! Vamos passar o facão nesses orcs!', '', 28153),
(151399, 'ptBR', 'Alcândora é da Aliança! Não está na hora de levantar a bandeira branca, não?', '', 28153),
(151398, 'ptBR', 'Tomamos Alcândora! Agora é a tua vez, Rokhan.', '', 28153),
(151397, 'ptBR', 'Putz... Não paguei a conta no bar...', 'Putz... Não paguei a conta no bar...', 28153),
(151396, 'ptBR', 'Alcândora é nossa! Pela Aliança!', '', 28153),
(151395, 'ptBR', 'Que tal... a gente fazer um acordo...', 'Que tal... a gente fazer um acordo...', 28153),
(151394, 'ptBR', 'Com o Veio do Galson em nossas mãos, não vai faltar ferro.', '', 28153),
(151393, 'ptBR', 'Muito bem, asseguramos a Serraria Terras Altas. Podemos usar a madeira serrada para construir nossa base.', '', 28153),
(151392, 'ptBR', '', 'Essa briga exige habilidade. Coisa que vocês não têm!', 28153),
(151391, 'ptBR', '', 'Tragam os demolidores! Destruam o portão! Quero ver Stromgarde em ruínas!', 28153),
(151390, 'ptBR', 'Toma cuidado!', 'Toma cuidado!', 28153),
(151389, 'ptBR', '', 'Tragam os demolidores! Destruam o portão! Sua hora chegou, Turalyon!', 28153),
(151388, 'ptBR', 'Qual é a grande ideia?', 'Qual é a grande ideia?', 28153),
(151387, 'ptBR', '', 'Tragam os demolidores! Destruam o portão! Obriguem o anão a mostrar a cara!', 28153),
(151386, 'ptBR', '', 'Alcândora é nossa! Estamos mais perto de tomar Arathi em nome da Horda!', 28153),
(151385, 'ptBR', '', 'Reivindicamos a Alcândora! A Horda logo atacará você, Turalyon.', 28153),
(151384, 'ptBR', '', 'Já tomamos Alcândora e agora estamos em vantagem. A maré está virando para o nosso lado.', 28153),
(151383, 'ptBR', '', 'Muito bem. Não dá para ir longe sem o ferro daquela mina.', 28153),
(151382, 'ptBR', 'Nem na morte vocês prestam! Saiam da frente e aprendam como se faz!', '', 28153),
(151381, 'ptBR', '', 'Vamos usar a madeira da Serra do Machado pra construir as fundações da nossa base. Excelente trabalho.', 28153),
(151380, 'ptBR', 'Manda os demolidores! Destruam o portão! E me tragam a cabeça do idiota do Matatroll!', '', 28153),
(151379, 'ptBR', 'Manda os demolidores! Não tem Luz que livre a cara daquele paladino do poder da Horda!', '', 28153),
(151378, 'ptBR', 'Manda os demolidores! O anão não vai se esconder atrás do portão pra sempre!', '', 28153),
(151377, 'ptBR', 'Alcândora tá caindo nas mãos da Horda, Matatroll.', '', 28153),
(151376, 'ptBR', 'Alcândora é nosso, Turalyon. As sombras se aproximam...', '', 28153),
(151375, 'ptBR', 'Muradin... tamos tomando a Alcândora. Tu tá pronto pra vir lutar?', '', 28153),
(151374, 'ptBR', 'A Mina Bigodesseco pertence à Horda.', '', 28153),
(151373, 'ptBR', '', 'Vocês são tão imprestáveis na morte quanto foram na vida. Eu cuido deles!', 28153),
(151372, 'ptBR', 'Ótimo. Vamos usar a lenha da Serra do Machado pra construir nosso baluarte.', '', 28153),
(151371, 'ptBR', 'Tragam os demolidores! Derrubem o portão! Vamos mostrar pro idiota do Matatroll a força dos peles-verdes!', '', 28153),
(151370, 'ptBR', '', 'Você se tornou uma mulher corajosa, Taelia. Seu pai ficaria orgulhoso.', 28153),
(151369, 'ptBR', 'Tragam os demolidores! Derrubem o portão! Essa batalha tá no papo!', '', 28153),
(151368, 'ptBR', 'Tragam os demolidores! Derrubem o portão! Vamos enfiar a cabeça podre daquele anão em uma estaca!', '', 28153),
(151367, 'ptBR', 'Chefe num vai ficar feliz...', 'Chefe num vai ficar feliz...', 28153),
(151366, 'ptBR', 'Alcândora é da Horda. Ou, melhor dizendo, dos \"peles verdes\".', '', 28153),
(151365, 'ptBR', 'Alcândora é nossa. Cadê a retaliação, Turalyon? Estou esperando...', '', 28153),
(151364, 'ptBR', 'Ai!', 'Ai!', 28153),
(151363, 'ptBR', 'Não era nada... pessoal...', 'Não era nada... pessoal...', 28153),
(151362, 'ptBR', 'Capturamos a Alcândora. Muradin! Tô vendo seu narigão daqui de cima!', '', 28153),
(151361, 'ptBR', 'Eu tava só... trabalhando...', 'Eu tava só... trabalhando...', 28153),
(151360, 'ptBR', '', 'Taelia... claro. Nossa jovem protetora de além-mar. Já faz tanto tempo assim?', 28153),
(151359, 'ptBR', 'Ótimo. Com a Mina Bigodesseco sob nosso controle, nunca mais ficaremos sem ferro.', '', 28153),
(151358, 'ptBR', 'A Serra do Machado é nossa. Podemos usar a serraria para construir a base.', '', 28153),
(151357, 'ptBR', 'Ó, isso aqui não é bagunça, não!', 'Ó, isso aqui não é bagunça, não!', 28153),
(151356, 'ptBR', 'A Passagem Clamabravo agora é nossa. Continuem atacando!', '', 28153),
(151355, 'ptBR', '', 'Taelia, senhora.', 28153),
(151354, 'ptBR', 'Muito bem. Recapturamos o Círculo dos Elementos.', '', 28153),
(151353, 'ptBR', 'As bandeiras da Aliança voltaram a tremular em Novaterra.', '', 28153),
(151352, 'ptBR', '', 'Certamente. E qual é o seu nome?', 28153),
(151351, 'ptBR', 'Asseguramos a Passagem Clamabravo.', '', 28153),
(151350, 'ptBR', 'O Círculo dos Elementos agora é da Aliança.', '', 28153),
(151349, 'ptBR', 'Muito bem, soldados. Novaterra é nossa.', '', 28153),
(151348, 'ptBR', 'Para com isso!', 'Para com isso!', 28153),
(151347, 'ptBR', '', 'Lorde-almirante, talvez seja melhor a senhora voltar para a bastilha. Assim, terei como analisar as provas contra a Casa Grimpagris.', 28153),
(151346, 'ptBR', 'Ótimo, expulsamos os viventes da Passagem Clamabravo. Agora, adelante!', '', 28153),
(151345, 'ptBR', 'Nós tomamos o Círculo dos Elementos!', '', 28153),
(151344, 'ptBR', 'Agora você passou dos limites!', 'Agora você passou dos limites!', 28153),
(151343, 'ptBR', 'Saqueamos Novaterra!', '', 28153),
(151342, 'ptBR', '', 'O Círculo dos Elementos é nosso.', 28153),
(151341, 'ptBR', '', 'Conquistamos Novaterra com sucesso.', 28153),
(151340, 'ptBR', 'A gente sabe muito bem como lidar com arruaceiros!', 'A gente sabe muito bem como lidar com arruaceiros!', 28153),
(151338, 'ptBR', '', 'Pronto, isso deve nos dar algum fôlego.', 28153),
(151337, 'ptBR', 'Ei!', 'Ei!', 28153),
(151336, 'ptBR', 'Cuidado com as sombras, escória da Aliança. A Horda vai pegar vocês...', '', 28153),
(151335, 'ptBR', 'Muito bem. Agora a Encruzilhada do Aprisco Norte é nossa, vamos pensar em alvos mais importantes.', '', 28153),
(151333, 'ptBR', '', 'Ei! Posso falar com você?', 28153),
(151332, 'ptBR', 'Por anos sem conta eu esperei para realizar minha vingança, até que, finalmente, sua mãe me ofereceu os meios.', '', 28153),
(151331, 'ptBR', 'Seus ancestrais devastaram meu povo, mas não conseguiram me destruir.', '', 28153),
(151330, 'ptBR', '', 'Gorak Tul?! Como é possível? Meus ancestrais o derrotaram há séculos!', 28153),
(151329, 'ptBR', 'Máquinas de cerco, destruam aquela base!', '', 28153),
(151328, 'ptBR', 'Vocês foram avisados, corja da Horda. Agora se preparem para ser aniquilados.', '', 28153),
(151327, 'ptBR', 'Isso aqui são terras da Aliança! Os muros de Stromgarde têm a benção da Luz e jamais vão cair nas mãos de gente da sua laia.', '', 28153),
(151326, 'ptBR', 'É a Horda que eu vejo no meu campo de batalha? Eu bem estava esperando por uma bela peleja!', '', 28153),
(151324, 'ptBR', 'Tu tem que detê-los e absorver a azerita para energizar o coração!', '', 28153),
(151323, 'ptBR', 'Tem ferimentos aparecendo por toda Azeroth, e mais forças querendo tomar a azerita para seus próprios fins.', '', 28153),
(151322, 'ptBR', 'O Coração de Azeroth é a chave para curar o mundo... mas precisamos de mais energia se quisermos ter alguma chance.', '', 28153),
(151321, 'ptBR', 'Magni, estou pront$Uo:a; para energizar o Coração de Azeroth.', 'Magni, estou pront$Uo:a; para energizar o Coração de Azeroth.', 28153),
(151320, 'ptBR', 'Preciso falar contigo em Silithus. Temos muito a fazer para salvar o mundo!', '', 28153),
(151319, 'ptBR', '', 'Vou comer vocês na vassourada!', 28153),
(151318, 'ptBR', '', 'Para trás, seus urubus do mar!', 28153),
(151317, 'ptBR', '', 'Fora da minha escada!', 28153),
(151316, 'ptBR', '', 'Xô, xôooo, passarada nojenta!', 28153),
(151315, 'ptBR', 'Paguem tudo, nanicos!', '', 28153),
(151314, 'ptBR', 'Feras de pesadelo, aproximem-se!', '', 28153),
(151313, 'ptBR', 'Estou com um bom pressentimento. É hoje que achamos esse negócio.', 'Estou com um bom pressentimento. É hoje que achamos esse negócio.', 28153),
(151312, 'ptBR', 'Essas botas vão ficar um arraso em mim.', 'Essas botas vão ficar um arraso em mim.', 28153),
(151311, 'ptBR', 'Vou te retalhar!', 'Vou te retalhar!', 28153),
(151310, 'ptBR', 'Ninguém vai te salvar aqui, sua escória.', 'Ninguém vai te salvar aqui, sua escória.', 28153),
(151309, 'ptBR', 'Cuidado onde pisa.', 'Cuidado onde pisa.', 28153),
(151308, 'ptBR', 'Você vai se dobrar rapidinho...', 'Você vai se dobrar rapidinho...', 28153),
(151307, 'ptBR', 'Espere só para ver...', 'Espere só para ver...', 28153),
(151306, 'ptBR', 'Ei, nada disso é seu!', 'Ei, nada disso é seu!', 28153),
(151305, 'ptBR', 'Oba, carne fresca!', 'Oba, carne fresca!', 28153),
(151304, 'ptBR', 'Oceanos investem! Ergam-se, meus lacaios!', '', 28153),
(151303, 'ptBR', 'Horrores rastejantes, venham se alimentar!', '', 28153),
(151302, 'ptBR', 'Criaturas das profundezas, ouçam meu chamado!', '', 28153),
(151301, 'ptBR', 'Ar fresquinho aqui. Não é que nem mina cheia de orc.', '', 28153),
(151300, 'ptBR', 'Que as trevas levem você!', '', 28153),
(151299, 'ptBR', 'Estou ficando farto. Seu fim chegou!', '', 28153),
(151298, 'ptBR', 'Os lacaios de Azshara são infinitos. Por que resistir?', '', 28153),
(151297, 'ptBR', 'Nem tô com muito medo, só cansado de carregar pedra.', '', 28153),
(151295, 'ptBR', 'Ele já consegue ouvir os sussurros. Acho que não temos muito tempo.', '', 28153),
(151294, 'ptBR', '', 'Eu vou logo atrás. Não precisa esperar!', 28153),
(151293, 'ptBR', 'Sob as marés... aguardando... chamando...', '', 28153),
(151292, 'ptBR', 'Por aqui. Eu pego o ferro.', '', 28153),
(151291, 'ptBR', 'Procure cavaletes de armas. Os Ímpios guardam em vários lugares por aqui.\n\nVou ficar na encolha até você voltar.', 'Procure cavaletes de armas. Os Ímpios guardam em vários lugares por aqui.\n\nVou ficar na encolha até você voltar.', 28153),
(151290, 'ptBR', '', 'Ventos, me protejam!', 28153),
(151289, 'ptBR', 'Volto assim que encontrar uma arma para você.', 'Volto assim que encontrar uma arma para você.', 28153),
(151288, 'ptBR', '', 'A brisa sopra a nosso favor!', 28153),
(151287, 'ptBR', 'Vou te reduzir a farpas!', '', 28153),
(151286, 'ptBR', 'Meu casco é impenetrável!', '', 28153),
(151285, 'ptBR', 'Os elementos estão em fúria!', 'Os elementos estão em fúria!', 28153),
(151284, 'ptBR', 'Os ladrões mortais vão morrer.', 'Os ladrões mortais vão morrer.', 28153),
(151283, 'ptBR', 'Vamos pegar tudo o que vocês pilharam!', 'Vamos pegar tudo o que vocês pilharam!', 28153),
(151282, 'ptBR', 'Os elementos reinarão supremos!', 'Os elementos reinarão supremos!', 28153),
(151281, 'ptBR', 'Você não vai tomar nada da gente!', 'Você não vai tomar nada da gente!', 28153),
(151280, 'ptBR', 'Essas gemas pertencem aos senhores dos elementos!', 'Essas gemas pertencem aos senhores dos elementos!', 28153),
(151279, 'ptBR', '<Liberte o escravo e dê-lhe uma arma para lutar.>', '<Liberte o escravo e dê-lhe uma arma para lutar.>', 28153),
(151278, 'ptBR', 'Com esse poder, vamos reconquistar o mundo!', 'Com esse poder, vamos reconquistar o mundo!', 28153),
(151277, 'ptBR', '<Liberte o escravo e dê-lhe uma arma para lutar.>', '<Liberte o escravo e dê-lhe uma arma para lutar.>', 28153),
(151276, 'ptBR', 'Meu senhor vai me recompensar por destruir você.', 'Meu senhor vai me recompensar por destruir você.', 28153),
(151275, 'ptBR', 'Me dá uma arma que eu te garanto dez Ímpios mortos.', 'Me dá uma arma que eu te garanto dez Ímpios mortos.', 28153),
(151274, 'ptBR', 'Arrume suas coisas. Você vem comigo.', 'Arrume suas coisas. Você vem comigo.', 28153),
(151273, 'ptBR', 'Quebra essas correntes, camarada. Os vulperas nasceram para ser livres.', 'Quebra essas correntes, camarada. Os vulperas nasceram para ser livres.', 28153),
(151272, 'ptBR', 'Quero trabalhar, mas não é seguro.', '', 28153),
(151271, 'ptBR', 'Me liberte, $pr, que eu te ajudo a matar os Ímpios.', 'Me liberte, $pr, que eu te ajudo a matar os Ímpios.', 28153),
(151270, 'ptBR', 'Nada de misericórdia com os Ímpios. Não depois do que fizeram.', 'Nada de misericórdia com os Ímpios. Não depois do que fizeram.', 28153),
(151269, 'ptBR', 'Vou fazer os Ímpios pagarem pelo que fizeram comigo.', 'Vou fazer os Ímpios pagarem pelo que fizeram comigo.', 28153),
(151268, 'ptBR', 'Foi a Nisha que te mandou? Seja o que for, tô dentro.', 'Foi a Nisha que te mandou? Seja o que for, tô dentro.', 28153),
(151267, 'ptBR', 'Me arruma uma arma, camarada, que do resto cuido eu.', 'Me arruma uma arma, camarada, que do resto cuido eu.', 28153),
(151266, 'ptBR', 'Só preciso de uma arma.', 'Só preciso de uma arma.', 28153),
(151265, 'ptBR', 'Não... as gemas são minhas... não podem... ser suas...', '', 28153),
(151264, 'ptBR', 'Não! Idiotas!', '', 28153),
(151263, 'ptBR', 'Vocês... não... venceram...', '', 28153),
(151262, 'ptBR', 'Eu voltarei!', '', 28153),
(151261, 'ptBR', 'Nossa hora está chegando...', '', 28153),
(151260, 'ptBR', 'Você só está adiando... o inevitável...', '', 28153),
(151259, 'ptBR', 'O caos... não será reprimido...', '', 28153),
(151258, 'ptBR', 'Os elementos... não podem ser detidos...', '', 28153),
(151257, 'ptBR', 'Seus selos vão ferver, seu céu vai se partir, montanhas vão se erguer, e nós vamos voltar!', '', 28153),
(151256, 'ptBR', 'A aurora dos elementos está chegando!', '', 28153),
(151255, 'ptBR', 'Seu tempo está acabando, mortais.', '', 28153),
(151254, 'ptBR', 'Com essas gemas, finalmente nós vamos destruir você.', '', 28153),
(151253, 'ptBR', 'Os elementos vão governar novamente!', '', 28153),
(151252, 'ptBR', 'Os minerais dourados nos energizam!', '', 28153),
(151251, 'ptBR', 'Seu mundo será nosso novamente!', '', 28153),
(151250, 'ptBR', 'Como se atreve a me enfrentar em meu próprio avião?', '', 28153),
(151249, 'ptBR', 'Tô meu turno. Muito ocupado!', '', 28153),
(151248, 'ptBR', 'Me leve para Orgrimmar.', 'Me leve para Orgrimmar.', 28153),
(151247, 'ptBR', '', '$n, que bom te ver. Vou ficar aqui pra ficar perto de Krag\'wa.\n\nMeu pai e minha mãe já contaram umas histórias maneiras do Loa Sapo. Vai ser a mó honra proteger ele desses trolls sangrentos.', 28153),
(151246, 'ptBR', 'Essas devem bastar. Obrigado!', 'Isso deve bastar. Agradeço!', 28153),
(151245, 'ptBR', 'Ei, vá buscar as balas de canhão para eu continuar atirando!', 'Ei, vá buscar as balas de canhão para eu continuar atirando!', 28153),
(151244, 'ptBR', '', 'Dra-e-nór. Dráinór? Drainôr. Draenor. <Suspiro>. Acho mais fácil dizer que sou de Terralém.', 28153),
(151243, 'ptBR', '', 'Pode-se dizer que eu sou incorrupta, mas eu prefiro pensar que sou uma orquisa orgânica.', 28153),
(151242, 'ptBR', '', 'Eu pintei o cabelo de verde uma vez. O Chefe Guerreiro Grito Infernal não gostou muito.', 28153),
(151241, 'ptBR', '', 'Chega desse barato muito doido de espaço-tempo... BLÁ! Me deixa arrebentar minhas coisas!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151240, 'ptBR', '', 'Os membros da Mão Despedaçada são guerreiros lendários, mas nunca peça uma massagem nas costas a um deles. Vai por mim... <gemidos doloridos>', 28153),
(151239, 'ptBR', '', 'Azeroth tem tantas regras pra definir quem você pode esfaquear, quem você pode esmurrar, quem não pode... Vocês têm que relaxar mais, galera!', 28153),
(151238, 'ptBR', '', 'Ei... não foi você que abandonou aquela guarnição cheia de entulho lá em Fogofrio?', 28153),
(151237, 'ptBR', '', 'Pode ficar quanto tempo quiser, mas não esquece: quebrou, pagou, ok?', 28153),
(151236, 'ptBR', '', 'Antes da gente continuar, eu preciso saber... Qual é o seu limite de dor?', 28153),
(151235, 'ptBR', '', 'Só porque eu estou gostando da companhia, isso não quer dizer que eu não queira lhe dar um murro.', 28153),
(151234, 'ptBR', '', 'Um xamã Olhos Sangrentos acabou de me paquerar. Pelo menos, eu acho. Ou ele deu uma piscadela pra mim ou acabou de sacrificar um olho.', 28153),
(151233, 'ptBR', '', 'O último que deu em cima de mim acabou debaixo da terra.', 28153),
(151232, 'ptBR', '', 'Um orc verde me deu um bombom com a mensagem \"amor maior que já se vil.\" Mandei enfiar o sangue de demônio no angu e enfiei-lhe uma macetada na fuça.', 28153),
(151231, 'ptBR', '', 'Você sabe se o Saurfang tá solteiro? Ele tem um charme de coroa sedutor...', 28153),
(151230, 'ptBR', '', 'Você não precisa de um Portal Negro... porque já invadiu meu coração.', 28153),
(151229, 'ptBR', '', 'Eu... me arrependi.', 28153),
(151228, 'ptBR', '', 'Patético! Você tombará aos pés dos Mag\'har!', 28153),
(151227, 'ptBR', 'Se quer alguma coisa bem feita...', 'Se quer alguma coisa bem feita...', 28153),
(151226, 'ptBR', 'Devia ter pedido... aquela promoção...', 'Acho que... me queimei...', 28153),
(151225, 'ptBR', 'Me enterrem... com meu dinheiro...', 'A morte não cobra imposto...', 28153),
(151224, 'ptBR', 'Essa... doeu...', 'Vocês vão pagar... por isso...', 28153),
(151223, 'ptBR', 'Não valeu... a pena...', 'Não valeu... a pena...', 28153),
(151222, 'ptBR', 'Devia ter pedido bônus... de periculosidade...', 'Não valeu... a pena...', 28153),
(151221, 'ptBR', '', 'Sou grata.', 28153),
(151220, 'ptBR', '', 'Eu lhe agradeço.', 28153),
(151219, 'ptBR', 'A Chefe Guerreira liberou os danos colaterais. Bota fogo em tudo!', 'A Chefe Guerreira liberou os danos colaterais. Bota fogo em tudo!', 28153),
(151218, 'ptBR', 'Dano colateral aprovado! Queima, criança!', 'Tem uma recompensa pelas suas cabeças... e ela vai ser minha!', 28153),
(151217, 'ptBR', '', 'Eu lhe devo uma.', 28153),
(151216, 'ptBR', '', 'Você cairá aos meus pés!', 28153),
(151215, 'ptBR', 'Ninguém... vai deter... ela...', 'Você nunca vai... detê-la...', 28153),
(151214, 'ptBR', 'Você tentou salvar a cidade errada, chapa.', 'Você acaba de cometer um erro dos grandes!', 28153),
(151213, 'ptBR', '', 'Pelas luas de Draenor!', 28153),
(151212, 'ptBR', 'Eu vou adorar isso!', 'Ah! Gente, eu adoro queimar coisas!', 28153),
(151211, 'ptBR', 'Pela Horda... e pelos lucros!', 'Pela Horda!', 28153),
(151210, 'ptBR', '', 'Eu só cumpri o meu dever.', 28153),
(151209, 'ptBR', '', 'Não me peça isso outra vez.', 28153),
(151208, 'ptBR', '', 'Não há de quê.', 28153),
(151207, 'ptBR', '', 'Não.', 28153),
(151206, 'ptBR', '', 'De forma alguma!', 28153),
(151205, 'ptBR', '', 'Nunca!', 28153),
(151204, 'ptBR', '', 'Isso mesmo.', 28153),
(151203, 'ptBR', '', 'Certo.', 28153),
(151202, 'ptBR', '', 'De fato.', 28153),
(151201, 'ptBR', '', 'Eu envergonhei o meu clã!', 28153),
(151200, 'ptBR', '', 'Deixe eu recuperar meu mana.', 28153),
(151199, 'ptBR', '', 'Preciso de mana!', 28153),
(151198, 'ptBR', '', 'Morra bem.', 28153),
(151197, 'ptBR', '', 'Não tenho mais nada a dizer.', 28153),
(151196, 'ptBR', '', 'Pode ir agora.', 28153),
(151195, 'ptBR', '', 'Vá com honra.', 28153),
(151194, 'ptBR', '', 'Fale.', 28153),
(151193, 'ptBR', '', 'Bom te ver.', 28153),
(151192, 'ptBR', '', 'Lok-tar!', 28153),
(151191, 'ptBR', '', 'Throm-ka!', 28153),
(151190, 'ptBR', '', 'Por favor! Eu imploro!', 28153),
(151189, 'ptBR', '', 'Tenha dó dessa pobre orquisa!', 28153),
(151188, 'ptBR', '', 'Dá uma moral pra peoa aqui!', 28153),
(151187, 'ptBR', '', 'Excelente trabalho.', 28153),
(151186, 'ptBR', '', 'Impressionante, não nego.', 28153),
(151185, 'ptBR', '', '<Humpf.> Meus parabéns.', 28153),
(151184, 'ptBR', 'Andem, miseráveis, essas defesas não vão se pagar sozinhas!', '', 28153),
(151183, 'ptBR', '', 'Arrebentem o inimigo!', 28153),
(151182, 'ptBR', '', 'No meu alvo!', 28153),
(151181, 'ptBR', '', 'Derrubem o inimigo por terra!', 28153),
(151180, 'ptBR', '', 'Morram com honra!', 28153),
(151179, 'ptBR', '', 'Atacar!', 28153),
(151178, 'ptBR', '', 'Mok-thora ka!', 28153),
(151177, 'ptBR', 'Por que você luta?', 'Por que você luta?', 28153),
(151176, 'ptBR', 'A Horda prevalecerá.', 'A Horda prevalecerá.', 28153),
(151175, 'ptBR', '', 'Estamos sendo atacados!', 28153),
(151174, 'ptBR', '', 'Esmaguem nossos inimigos!', 28153),
(151173, 'ptBR', '', 'Quebrem a formação deles!', 28153),
(151172, 'ptBR', '', 'Recuem ou morram!', 28153),
(151171, 'ptBR', '', 'Vamos lutar em outro dia!', 28153),
(151170, 'ptBR', '', 'Vai! Corre daqui!', 28153),
(151169, 'ptBR', '', 'Vem por aqui.', 28153),
(151168, 'ptBR', '', 'Deixem a orquisa liderar.', 28153),
(151167, 'ptBR', 'Companheiros... sigam sem mim...', 'Companheiros... sigam sem mim...', 28153),
(151166, 'ptBR', 'Eu vou descansar agora.', 'Eu vou descansar agora.', 28153),
(151165, 'ptBR', '', 'Vem comigo.', 28153),
(151164, 'ptBR', 'Espíritos... guiem-me.', 'Espíritos... guiem-me.', 28153),
(151163, 'ptBR', 'Saia da frente e você pode sair daqui com vida.', 'Saia da frente e você pode sair daqui com vida.', 28153),
(151162, 'ptBR', 'Nos curamos, mas se preciso, também ferimos.', 'Nos curamos, mas se preciso, também ferimos.', 28153),
(151161, 'ptBR', '', 'Pela Horda!', 28153),
(151160, 'ptBR', 'Horda, comigo! Eu curarei suas feridas!', 'Horda, comigo! Eu curarei suas feridas!', 28153),
(151159, 'ptBR', '', 'Me acertaram!', 28153),
(151158, 'ptBR', '', 'Curandeiro, uma ajuda!', 28153),
(151157, 'ptBR', 'Mãe Terra... guie-nos...', 'Mãe Terra... guie-nos...', 28153),
(151156, 'ptBR', 'Pela Horda!', 'Pela Horda!', 28153),
(151155, 'ptBR', '', 'Não fique só olhando, me ajude!', 28153),
(151154, 'ptBR', '', 'Ajude aqui!', 28153),
(151153, 'ptBR', '', 'Preparem-se!', 28153),
