(148712, 'ptBR', 'Como... isso pôde...', 'Como... isso pôde...', 28153),
(148711, 'ptBR', 'Morro... com dignidade...', 'Morro... com dignidade...', 28153),
(148710, 'ptBR', 'Os espíritos dos meus seguidores estão presos numa batalha sem fim.', '', 28153),
(148709, 'ptBR', 'Derrotado... por mãos continentais?', 'Derrotada... por mãos continentais?', 28153),
