(148701, 'ptBR', 'Isso não tá no meu contrato!', 'Isso não tá no meu contrato…', 28153),
(148700, 'ptBR', 'Eu não ganho o suficiente pra isso!', 'Não sou paga pra isso!', 28153),
(148699, 'ptBR', '', 'Segurança em primeiro lugar!', 28153),
(148698, 'ptBR', '', 'Eu adoro o cheiro de explosivos pela manhã!', 28153),
(148697, 'ptBR', 'É uma longa história, depois eu te conto. Ele vai encontrar o Bwonsamdi rapidinho se a gente não correr.', 'É uma longa história, depois eu te conto. Ele vai acabar nos braços de Bwonsamdi se a gente não correr.', 28153),
(148696, 'ptBR', '', 'Você se aliou a um sethrak?', 28153),
(148695, 'ptBR', 'Eu estou bem, mas meu amigo aqui está em maus lençóis.', 'Eu estou bem, mas meu amigo aqui está em maus lençóis.', 28153),
(148694, 'ptBR', 'Então a Aliança acha que pode ir pra lá e pra cá com suprimentos sem dividir com a gente? O Drom\'kal vai precisar de alguns voluntários na armaria pra gente poder entrar em ação... e rápido!', '', 28153),
(148693, 'ptBR', 'Aí! Eu tô vendo uns lenhadores da Aliança desprotegidos! Aquela madeira vai ser nossa... assim que você matar eles.', '', 28153),
(148692, 'ptBR', 'Ih não, não pode ser coisa boa! Cascasseca vindo do leste!', '', 28153),
(148691, 'ptBR', 'Nós faremos o vale voltar a ser como era.', 'Nós faremos o vale voltar a ser como era.', 28153),
(148690, 'ptBR', 'Vê se não dá com os burros n\'água por aí.', 'Vê se não dá com os burros n\'água por aí.', 28153),
