INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148608, 'ptBR', 'As melhores mercadorias de Kul Tiraz.', 'As melhores mercadorias de Kul Tiraz.', 28153),
(148607, 'ptBR', 'Aqui só tem material de primeira.', 'Aqui só tem material de primeira.', 28153),
