(148584, 'ptBR', 'Ventos largos e mares calmos.', 'Ventos largos e mares calmos.', 28153),
(148583, 'ptBR', 'Meu medo é nunca conhecermos a paz.', 'Meu medo é nunca conhecermos a paz.', 28153),
(148582, 'ptBR', 'Alguma novidade do continente?', 'Alguma novidade do continente?', 28153),
(148581, 'ptBR', 'O mar não está pra peixe ultimamente, não é?', 'O mar não está pra peixe ultimamente, não é?', 28153),
(148580, 'ptBR', 'Volte depois para ver produtos novos.', 'Volte depois pra ver os produtos novos.', 28153),
(148579, 'ptBR', 'Itens exóticos chegam todos os dias.', 'Itens exóticos chegam todos os dias.', 28153),
(148578, 'ptBR', 'Não deixe de voltar.', 'Não deixe de voltar.', 28153),
(148577, 'ptBR', 'Fique à vontade, veja o que quiser.', 'Fique à vontade, veja o que quiser.', 28153),
(148576, 'ptBR', 'Venha, podemos conversar.', 'Venha, podemos conversar.', 28153),
(148575, 'ptBR', 'Isso... não é... o fim...', '', 28153),
(148574, 'ptBR', 'Você chegou tarde demais...', '', 28153),
(148573, 'ptBR', 'Nós nunca vamos nos render...', '', 28153),
(148572, 'ptBR', 'Esta terra... será... nossa...', '', 28153),
