(145862, 'ptBR', 'Tô impressionado.', '', 28153),
(145861, 'ptBR', 'Não sai por aí fazendo acordos com os espíritos.', '', 28153),
(145860, 'ptBR', 'Que o Bwonsamdi passe longe da tua porta.', '', 28153),
(145859, 'ptBR', 'O loa te guarde e crie.', '', 28153),
