INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145767, 'ptBR', 'Não posso aprender esse feitiço.', '', 28153),
(145766, 'ptBR', 'Não posso saquear isso.', '', 28153),
(145765, 'ptBR', 'Isso não é meu.', '', 28153),
(145764, 'ptBR', 'Preciso chegar mais perto.', '', 28153),
(145763, 'ptBR', 'Está longe demais.', '', 28153),
(145762, 'ptBR', 'Não consigo alcançar.', '', 28153),
(145761, 'ptBR', 'Não posso trocar isso.', '', 28153),
(145760, 'ptBR', 'Não posso usar isso.', '', 28153),
(145759, 'ptBR', 'Não estou equipado com o item.', '', 28153),
(145758, 'ptBR', 'Preciso me equipar primeiro.', '', 28153),
(145757, 'ptBR', 'Não posso saquear isso no momento.', '', 28153),
(145756, 'ptBR', 'Não tenho nenhum alvo.', '', 28153),
(145755, 'ptBR', 'Preciso de um alvo antes.', '', 28153),
(145754, 'ptBR', 'Preciso de um alvo.', '', 28153),
(145753, 'ptBR', 'Não posso fazer isso.', '', 28153),
(145752, 'ptBR', 'Preciso de permissão para isso.', '', 28153),
(145751, 'ptBR', 'Ataca o meu inimigo!', '', 28153),
(145750, 'ptBR', 'Ataca meu alvo!', '', 28153),
(145749, 'ptBR', 'Concentrem os ataques!', '', 28153),
(145748, 'ptBR', 'Atacar!', '', 28153),
(145747, 'ptBR', 'Ataquem juntos!', '', 28153),
(145746, 'ptBR', 'Por Zandalar!!', '', 28153),
(145745, 'ptBR', 'Todas as tropas, avançar!', '', 28153),
(145744, 'ptBR', 'Faz eles ir pra trás!', '', 28153),
(145743, 'ptBR', 'Recuar!', '', 28153),
(145742, 'ptBR', 'Sujou! Volta!', '', 28153),
(145741, 'ptBR', 'Vai! Corre daqui!', '', 28153),
(145740, 'ptBR', 'Vem comigo.', '', 28153),
(145739, 'ptBR', 'Eu mostro o caminho.', '', 28153),
(145738, 'ptBR', 'Me segue.', '', 28153),
(145737, 'ptBR', 'Pela Horda!', '', 28153),
(145736, 'ptBR', 'Estou muito machucado.', '', 28153),
(145735, 'ptBR', 'Eu preciso de cura!', '', 28153),
(145734, 'ptBR', 'Eu preciso de ajuda!', '', 28153),
(145733, 'ptBR', 'Dá uma força aê!', '', 28153),
(145732, 'ptBR', 'Perigo chegando!', '', 28153),
(145731, 'ptBR', 'Todas as armas, atacar!', '', 28153),
(145730, 'ptBR', 'Abrir fogo!', '', 28153),
(145729, 'ptBR', 'Fica aqui.', '', 28153),
(145728, 'ptBR', 'Não se mexe.', '', 28153),
(145727, 'ptBR', 'Agora que meus irmãos estão livres, eu vou atrás do Zandalari na aldeia. Não nos resta mais nada por aqui.', '', 28153),
(145726, 'ptBR', 'Eu não sei lutar. Encontro você garganta adentro, depois que tiver libertado meus irmãos.', '', 28153),
(145725, 'ptBR', 'E a gorjeta?', 'E a gorjeta?', 28153),
(145724, 'ptBR', 'Sinto o poder de Reid chamando como um farol. Rápido!', '', 28153),
(145723, 'ptBR', 'Acho que você já bebeu demais. Chispa daqui!', '', 28153),
(145722, 'ptBR', 'Colocando', 'Colocando', 28153),
(145721, 'ptBR', '', 'A biologia evolucionária da espécie silitídea é fascinante e extraordinária!', 28153),
(145720, 'ptBR', 'Você deve gostar mesmo de gatos.', 'Você deve gostar mesmo de gatos.', 28153),
(145719, 'ptBR', 'Dona Fofolete?', 'Dona Fofolete?', 28153),
(145718, 'ptBR', 'Eles parecem ser bem cuidados.', 'Eles parecem ser bem cuidados.', 28153),
(145717, 'ptBR', '<Você tenta comentar, mas é cortad$go:a; da conversa.>', '<Você tenta comentar, mas é cortad$go:a; da conversa.>', 28153),
(145716, 'ptBR', '', '<Ela começa a chorar.>\n\nDesculpe, eu fico emocionada... É que eu amo gatos. Eu amo todo tipo de gato. Gato de raça, gato rajado, gato siamês, gato tigrado, gato vilinfuso, gato não vilinfuso, sabre-da-aurora, sabrevil, sabre-das-chamas, sabre-do-gelo, manassabre, sabre-da-lua, sabre-da-noite, sabre-do-trovão, leão, lince, pantera, panthara — a cor deles é maravilhosa, especialmente com pelagem índigo, mas dizem que o temperamento deles é difícil, mas eu acho que o problema é que as pessoas não entendem eles como eu entendo —, tigre, tigre espectral... A primeira coisa que eu fiz quando saí de Suramar foi procurar todo tipo de gato que eu pudesse. Eu queria abraçar todos, mas não dá para abraçar todos.\n\n<Ela começa a chorar de novo.>', 28153),
(145715, 'ptBR', '', '<Ela aponta para um terceiro gatinho de mana.>\n\nOlhe só que bonitinha ela sentada, tão quietinha... Ela tem uma imaginação fértil que só quando o assunto é comida. O normal seria ficar feliz com os peixes maravilhosos daqui, mas não: a Dona Fofolete tem um paladar muito refinado. Acredite se quiser, a comida favorita dela é, coisa que até eu às vezes duvido, bolo de mana! \n\nAcho que faz sentido, já que meus pais costumavam dar esse petis... digo, P-E-T-I-S-C-O para ela quando eu era criança. Filha única, única gata. Uma bela dupla.', 28153),
(145714, 'ptBR', '', 'Esses gatinhos merecem o melhor, porque são maravilhosos. E queria poder compartilhar eles com todo mundo do mundo inteiro, mas não dá... acredite em mim, eu tentei. É tão importante que você esteja aqui e que eu possa fazer carinho neles. Ainda bem que tinha outros dois gatos para alisar enquanto eu ganhava a confiança de Mio, porque se não tivesse... não quero nem pensar, seria muito sofrimento! Imagina chegar em casa e não ter gato! Não dá nem para dizer que é uma casa. É só um lugar onde se mora. E, se a pessoa não tem gato, para que viver? Falando nos dois gatos, esta aqui é uma: Dona Fofolete!', 28153),
(145713, 'ptBR', '', 'No começo, ele parecia bem desconfiado e não deixava que eu tocasse nele. Claro que isso só me fez insistir mais. Foram muitos anos de persistência e P-E-T-I-S-C-O, nunca subestime o poder do P-E-T-I-S-C-O, mas ele acabou se aproximando e agora é meu MELHOR AMIGO, como todos os outros gatinhos! \n\nEu tenho que soletrar a palavra para ele não ouvir, senão vai miar e implorar e... bom, como resistir ao encanto desses olhinhos? Olha só para isso, olha só! Tão cheios de amor e carinho. Me dá uma sensação tão grande de felicidade e de reconforto! Eu tento regular o máximo possível, para ele não ficar mal acostumado... Ah, para que fingir... a verdade é que eu dou a quantidade que ele quiser!', 28153),
(145712, 'ptBR', '', 'Pode colocar o vinho arcano naquele cantinho... hã, não me lembro de você. Deve ter chegado aqui faz pouco tempo! E isso quer dizer que ainda não conheceu meus fofuchos! \n\n<Ela aponta para um dos gatinhos de mana.>\n\nAquele é o Sombra. Ele vive perdendo os brinquedinhos nas suas aventuras. Aonde você vai, pequenino? Para o Viveiro, ver os animais exóticos do mundo? Para o Vinhedo do Crepúsculo? Você bem que podia me trazer um berloque da viagem! Bom, uma vez ele trouxe: meu querido Mio! Um dia abri a porta para deixá-lo entrar e tomei um susto quando vi que tinha trazido um amiguinho! E, como não podia deixar de ser, se é amigo do Sombra é amigo meu.', 28153),
(145706, 'ptBR', '', 'O que foi isso? Vocês três! Vão conferir os motores!', 28153),
(145703, 'ptBR', 'Tu acabou de assinar tua sentença de morte. Tu vai ver...', '', 28153),
(145702, 'ptBR', 'Tu derramou meu grogue! Vai pra prancha!', '', 28153),
(145701, 'ptBR', 'Vou esfregar o convés com a tua cara!', '', 28153),
(145700, 'ptBR', 'Então tu não tem medo de sair no braço, né? Bora ver se tu guenta um Lobo do Mar veterano!', '', 28153),
(145699, 'ptBR', 'Aí, rapaziada, bora mostrar pra esse $r o que acontece com quem se mete com a Horda!', '', 28153),
(145698, 'ptBR', 'Se tu acha que guenta com os Lobos do Mar, pode esperar que lá vem bordoada!', '', 28153),
(145697, 'ptBR', 'Então $Go sarnento:a sarnenta; da Aliança resolveu mostrar a cara?', '', 28153),
(145686, 'ptBR', '', 'Hoje você dorme com os peixes-sabre, $n.', 28153),
(145685, 'ptBR', '', 'Eu vou rezar por você!', 28153),
(145684, 'ptBR', '', 'Não gaste dinheiro com o meu caixão.', 28153),
