(145289, 'ptBR', 'Não se mexa.', '', 28153),
(145288, 'ptBR', 'Uma planta carnívora decorativa.', 'Uma planta carnívora decorativa.', 28153),
(145287, 'ptBR', '', 'Me deixa pegar mana!', 28153),
(145286, 'ptBR', '', 'Preciso recuperar mana.', 28153),
