(145280, 'ptBR', 'O fogo.', 'O fogo.', 28153),
(145279, 'ptBR', 'O que é, o que é?\n\nSe eu beber, morro. Se comer, vivo. Quem sou eu?', '', 28153),
(145278, 'ptBR', 'Vamos!', 'Vamos!', 28153),
(145277, 'ptBR', 'Acertou!\n\nVamos para a próxima?', '', 28153),
(145276, 'ptBR', 'Uuna foi engolida pelas trevas.', 'Uuna foi engolida pelas trevas.', 28153),
(145275, 'ptBR', '', 'Aaaghhh! Não! Socorro!', 28153),
(145273, 'ptBR', '', 'Uma voz trovejante deixa você na ponta dos pés.', 28153),
(145272, 'ptBR', '', 'Tô te implorando!', 28153),
(145271, 'ptBR', '', 'Tenha um pouco de bondade, tchê!', 28153),
(145270, 'ptBR', '', 'Tem dó de mim!', 28153),
(145269, 'ptBR', '', 'Capaz!', 28153),
(145268, 'ptBR', '', 'A la pucha!', 28153),
(145267, 'ptBR', '', 'Barbaridade!', 28153),
(145266, 'ptBR', '', 'Mas... não ainda.', 28153),
(145265, 'ptBR', '', 'Sei que um dia terei de voltar para mamãe e papai.', 28153),
(145264, 'ptBR', '', 'Que a forja te ilumine.', 28153),
(145263, 'ptBR', '', 'Tu me mostraste tanta coisa interessante. És u$Gm:ma; amig$Go:a; sem igual!', 28153),
(145262, 'ptBR', '', 'Estou farta de ti.', 28153),
(145261, 'ptBR', '', 'Tu vai pagar CARO pelo que fez!', 28153),
(145260, 'ptBR', '', 'Chispa daqui!', 28153),
(145259, 'ptBR', '', 'Um forte quebra-costela.', 28153),
(145258, 'ptBR', '', 'MUITO obrigada por me mostrar isso, amig$Go:a;!', 28153),
(145257, 'ptBR', '', 'Eles não morreram todos em Argus?', 28153),
(145256, 'ptBR', '', 'Meu povo está aqui! Eles sobreviveram!', 28153),
(145255, 'ptBR', '', 'É tão... bonito...', 28153),
(145254, 'ptBR', '', 'Que bobeira, amig$Go:a;.', 28153),
(145253, 'ptBR', '', 'É como se mover na água... um lago brilhante?', 28153),
(145252, 'ptBR', '', 'Desembucha.', 28153),
(145251, 'ptBR', 'Eu quero, sim.', 'Eu quero, sim.', 28153),
(145250, 'ptBR', 'Errou!\n\nQuer tentar outra vez?', '', 28153),
(145249, 'ptBR', 'Um loa.', 'Um loa.', 28153),
(145248, 'ptBR', 'Uma vela.', 'Uma vela.', 28153),
(145247, 'ptBR', '', 'Olha lá embaixo. Tudo brilha!', 28153),
(145246, 'ptBR', '', 'Onde estamos? Por que está tão enfumaçado?', 28153),
(145245, 'ptBR', '', 'Tem cuidado, hein?', 28153),
(145244, 'ptBR', 'Uma árvore.', 'Uma árvore.', 28153),
