INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145242, 'ptBR', '', 'Saludos.', 28153),
(145241, 'ptBR', '', 'Eu não sabia que existiam montanhas tão altas!', 28153),
(145240, 'ptBR', '', 'Eu consigo ver tudo daqui!', 28153),
(145239, 'ptBR', '', 'Não tá morto quem peleia.', 28153),
(145238, 'ptBR', '', 'Buenas.', 28153),
(145237, 'ptBR', '', 'Crá crá crá crá crá!', 28153),
(145236, 'ptBR', '', 'Nã-não.', 28153),
(145235, 'ptBR', '', 'Não.', 28153),
(145234, 'ptBR', '', 'Caça teu rumo.', 28153),
(145233, 'ptBR', '', 'Isso mesmo.', 28153),
(145232, 'ptBR', '', 'A-ham.', 28153),
(145231, 'ptBR', '', 'Si.', 28153),
(145230, 'ptBR', '', 'Estou muito grata.', 28153),
(145229, 'ptBR', '', 'Tu tem a minha gratidão.', 28153),
(145228, 'ptBR', 'Um gnomo.', 'Um gnomo.', 28153),
(145227, 'ptBR', '', 'Te devo uma.', 28153),
(145226, 'ptBR', '', 'Pela Bigorna Negra!', 28153),
(145225, 'ptBR', '', 'Uns... DEZ pássaros!', 28153),
(145224, 'ptBR', '', 'Tu não tem nada de melhor, tchê?', 28153),
(145222, 'ptBR', '', 'Dou-te um murro nessas fuças!', 28153),
(145221, 'ptBR', '', 'Pergunto-me quantos pássaros viverão naquela árvore. Devem ser muitos!', 28153),
(145220, 'ptBR', 'O que é, o que é?\n\nEu sou alto na juventude e baixinho na velhice. Quem sou eu?', '', 28153),
(145219, 'ptBR', '', 'Fiz pra ajudar.', 28153),
(145218, 'ptBR', '', 'Amig$Go:a;, olha! Estamos debaixo de uma árvore gigante!', 28153),
(145217, 'ptBR', '', 'É um prazer ajudar, tchê.', 28153),
(145216, 'ptBR', '', 'Gracias, vivente.', 28153),
(145215, 'ptBR', 'Vamos brincar.', 'Vamos brincar.', 28153),
(145214, 'ptBR', 'Pront$Go:a; para testar sua mente?', '', 28153),
(145213, 'ptBR', '', 'Posso ter um de mascote?', 28153),
(145212, 'ptBR', '', 'Mas para pássaros-lagartos.', 28153),
(145211, 'ptBR', '', 'É uma torre gigante. Feito uma... casa de pássaro gigante!', 28153),
(145210, 'ptBR', '', 'Ei, o que são aquelas coisas voando? Como são bonitas!', 28153),
(145209, 'ptBR', '', 'Pensando bem... vives tu em ALGUM lugar?', 28153),
(145208, 'ptBR', '', 'Tu vives aqui?', 28153),
(145207, 'ptBR', '', 'Eu nem sabia que isso existia!', 28153),
(145206, 'ptBR', '', 'Uau... uma cidade voadora! Como é possível?!', 28153),
(145205, 'ptBR', '', 'Queres brincar de princesa comigo?', 28153),
(145204, 'ptBR', '', 'Sabes quem vive aqui? Aposto que é uma princesa.', 28153),
(145203, 'ptBR', '', 'Uau! Deve ser a casa mais bonita que já vi!', 28153),
(145202, 'ptBR', '', 'Ecaaa!', 28153),
(145201, 'ptBR', '', 'São insetos? Aposto que são insetos. Eca! Eu odeio insetos!', 28153),
(145200, 'ptBR', '', 'O que achas que eles pretendiam afastar com isso?', 28153),
(145199, 'ptBR', '', 'Uau! É a maior muralha que já vi!', 28153),
(145197, 'ptBR', '', 'Uuna abraça você.', 28153),
(145196, 'ptBR', 'Não trisca no butim!', '', 28153),
(145195, 'ptBR', '', 'Tudo bem, vamos embora daqui, amig$Go:a;! Há muitos lugares a visitar!', 28153),
(145194, 'ptBR', '', 'Diz a mamãe e papai que sinto falta deles... e que estou esperando pra revê-los!', 28153),
(145193, 'ptBR', '', 'Amig$Go:a;! A Luz diz que posso ficar! Oba!', 28153),
(145192, 'ptBR', '', 'Posso ficar com $Gmeu amigo:minha amiga;? Só mais um pouquinho?', 28153),
(145191, 'ptBR', '', 'Tem tanto que jamais fiz. Tantos lugares que jamais vi...', 28153),
(145190, 'ptBR', '', 'Espera um instante...', 28153),
(145189, 'ptBR', '', 'Mamãe! Papai! Eles esperam por mim!', 28153),
(145188, 'ptBR', '', 'A luz... está me dizendo para segui-la...', 28153),
(145187, 'ptBR', '', 'O que... o que está acontecendo?', 28153),
(145186, 'ptBR', '', 'Nós conseguimos, amig$Go:a;! Nós os vencemos!', 28153),
(145185, 'ptBR', '', 'A escuridão se foi! Eu consigo ver!', 28153),
(145184, 'ptBR', '', 'Tu vai pagar caro pelo que fez!', 28153),
(145183, 'ptBR', 'Maldit$go:a;. Maldit$go:a;! Eu não tinha acabado...', '', 28153),
(145182, 'ptBR', 'A Rainha Banshee vai comemorar a sua morte!', '', 28153),
(145181, 'ptBR', 'Lixo da Aliança! Eu vou levar sua cabeça para a Dama Sombria!', '', 28153),
(145180, 'ptBR', '', 'Eu vou cortar tua garganta, $n!', 28153),
(145179, 'ptBR', 'Cascos ecoam ao longe. Tem alguma coisa chegando.', 'Cascos ecoam ao longe. Tem alguma coisa chegando.', 28153),
(145178, 'ptBR', '', 'Como ousa me interromper? Tu vai pagar com a vida, $n!', 28153),
(145177, 'ptBR', '', 'Tô de olho em tu, $n.', 28153),
(145176, 'ptBR', 'Tu tá frit$Go:a;, que nem teu rei-cachorro! Pela Horda!', '', 28153),
(145175, 'ptBR', 'Você sente cheiro de ozônio e a estática no ar.', 'Você sente cheiro de ozônio e a estática no ar.', 28153),
(145173, 'ptBR', '', 'Atrevid$Go:a;, mas eu não me resumo à magia.', 28153),
(145172, 'ptBR', 'Estou pronto. Vamos começar o ritual.', 'Estou pronta. Vamos começar o ritual.', 28153),
(145171, 'ptBR', 'Ouço os clamores do mundo sob meus pés. Azeroth estremece de dor! Tenho que encontrar um jeito de aplacar esse sofrimento...', '', 28153),
(145170, 'ptBR', '', 'Não vou morrer tão fácil, $n. Tu vai sofrer a minha ira!', 28153),
(145169, 'ptBR', '', 'Finalmente encontrei você, $n.', 28153),
(145168, 'ptBR', 'Eu vou esmagar seu crânio!', '', 28153),
(145167, 'ptBR', 'Eu vou arrancar a carne dos seus ossos!', '', 28153),
(145166, 'ptBR', 'Eu vou pisar no seu túmulo por toda a eternidade.', '', 28153),
(145165, 'ptBR', 'Me tiraram toda a esperança.', '', 28153),
(145164, 'ptBR', 'Maldição. De novo, não.', '', 28153),
(145163, 'ptBR', 'Você vai sofrer pelo que fez comigo.', '', 28153),
(145162, 'ptBR', 'Eu vou drenar sua força vital.', '', 28153),
(145161, 'ptBR', 'Eu adoro o clangor dos metais e o cheiro do medo.', '', 28153),
(145160, 'ptBR', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t Você está sob o |cFFF00000|Hspell:260953|h[Olhar Férreo]|h|r!', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t Você está |cFFF00000|Hspell:257459|h[No Gancho]|h|r!', 28153),
(145159, 'ptBR', '', 'EU NÃO TEREI MAIS MEDO!', 28153),
(145158, 'ptBR', '', 'Minha luz é superpoderosa!', 28153),
(145157, 'ptBR', 'Quero ir pra casa.', '', 28153),
(145156, 'ptBR', '', 'E, enquanto minha luz estiver comigo, a escuridão não pode vencer!', 28153),
(145155, 'ptBR', '', 'Mamãe me diz que a Luz sempre me acharia. És tu, amig$Go:a;. Tu és minha luz!', 28153),
(145154, 'ptBR', '', 'A-amig$Go:a;, tu estás aqui! Tu não me deixastes!', 28153),
(145153, 'ptBR', 'Não... não...', 'Não... não...', 28153),
(145152, 'ptBR', 'Dama Sombria... eu fracassei...', 'Dama Sombria... eu fracassei...', 28153),
(145151, 'ptBR', 'Eu sou aquele ali embaixo no totem, cara.', '', 28153),
(145150, 'ptBR', 'Finalmente...', 'Finalmente...', 28153),
(145149, 'ptBR', 'Ah... de novo, não...', 'Ah... de novo, não...', 28153),
(145148, 'ptBR', 'Pela Dama Sombria!', 'Pela Dama Sombria!', 28153),
(145147, 'ptBR', 'Abandone a esperança!', 'Abandone a esperança!', 28153),
(145146, 'ptBR', 'Acompanhe-nos na morte!', 'Acompanhe-nos na morte!', 28153),
(145145, 'ptBR', 'Vou me banquetear com seus ossos!', 'Vou me banquetear com seus ossos!', 28153),
(145144, 'ptBR', 'Morte aos vivos!', 'Morte aos vivos!', 28153),
(145143, 'ptBR', 'Por Sylvana!', 'Por Sylvana!', 28153),
(145142, 'ptBR', '', 'Uuna se abraça e começa a chorar.', 28153),
(145141, 'ptBR', '', 'Eu... Eu não consigo! Eu só quero ir para casa!', 28153),
(145140, 'ptBR', '', 'Amig$Go:a;? Tu ainda estás aqui? Tenho medo!', 28153),
(145139, 'ptBR', 'A urucubaca vai te pegar!', '', 28153),
(145137, 'ptBR', 'Teus ancestrais tão te chamando no além.', '', 28153),
(145136, 'ptBR', 'Que tu seja amaldiçoad$Go:a; com a feiura do meu irmão.', '', 28153),
(145135, 'ptBR', 'Qual é a tu linha de vodu?', '', 28153),
(145133, 'ptBR', 'Os ossos caem onde têm que cair.', '', 28153),
(145130, 'ptBR', 'Os espinhos querem sua alma!', '', 28153),
(145129, 'ptBR', 'Então ele se virou e sumiu mata adentro. Desde então, os justos e valentes encontram abrigo junto ao Cervo Branco da floresta.', 'Então ele se virou e sumiu mata adentro. Desde então, os justos e valentes encontram abrigo junto ao Cervo Branco da floresta.', 28153),
(145128, 'ptBR', '\"Eu sou Athair, o coração desta floresta. Enquanto eu viver, protegerei você e os seus, bastando que me procurem\", disse o cervo.', '\"Eu sou Athair, o coração desta floresta. Enquanto eu viver, protegerei você e os seus, bastando que me procurem\", disse o cervo.', 28153),
(145127, 'ptBR', '\"Pela Luz! Um cervo falante!\", exclamou Arom.', '\"Pela Luz! Um cervo falante!\", exclamou Arom.', 28153),
(145126, 'ptBR', '', '<Som de aplausos>', 28153),
(145125, 'ptBR', '', '<Bocejo>', 28153),
(145124, 'ptBR', '', '<Comemoração curta - Uuuuh!>', 28153),
(145123, 'ptBR', '', '<Comemoração um pouco mais longa - Uhuu!>', 28153),
(145122, 'ptBR', 'O fogo será sua ruína!', '', 28153),
(145121, 'ptBR', '', '<Som de galinha>', 28153),
(145120, 'ptBR', '', '<Som de choro>', 28153),
(145119, 'ptBR', '\"Não há de quê. Eu só devolvi o favor que você me fez.\"', '\"Não há de quê. Eu só devolvi o favor que você me fez.\"', 28153),
(145118, 'ptBR', '', '<Sons de choro; variação>', 28153),
(145117, 'ptBR', '', '<Sons de choro; variação>', 28153),
(145116, 'ptBR', '', '<Beijo>', 28153),
(145115, 'ptBR', '\"Obrigado, meu amigo\", agradeceu Arom ao cervo.', '\"Obrigado, meu amigo\", agradeceu Arom ao cervo.', 28153),
(145114, 'ptBR', '', '<Som de risada>', 28153),
(145113, 'ptBR', '', '<Risada>', 28153),
(145112, 'ptBR', '', '<Soltar um muxoxo com os beiços: Pfffthblth!>', 28153),
(145111, 'ptBR', 'Juntos, Arom e o Cervo Branco enfrentaram e derrotaram os guerreiros.', 'Juntos, Arom e o Cervo Branco enfrentaram e derrotaram os guerreiros.', 28153),
(145110, 'ptBR', '', '<Rugido dominante>', 28153),
(145109, 'ptBR', '', '<Rugido; variação>', 28153),
(145108, 'ptBR', '', '<Suspiro>', 28153),
(145107, 'ptBR', '', '<Barulhos de trem: xique-xique chu-chu!>', 28153),
(145106, 'ptBR', 'O cervo tinha voltado, e atropelou alguns dos drustos!', 'O cervo tinha voltado, e atropelou alguns dos drustos!', 28153),
(145105, 'ptBR', 'Um urro reverberou pela floresta!', 'Um urro reverberou pela floresta!', 28153),
(145104, 'ptBR', 'Determinado a levar consigo todos os guerreiros que pudesse, o Lorde lutou bravamente.', 'Determinado a levar consigo todos os guerreiros que pudesse, o Lorde lutou bravamente.', 28153),
(145103, 'ptBR', 'Lorde Arom viu-se contra dez guerreiros! Ele lutou com valentia e astúcia, porém estava cercado e em minoria!', 'Lorde Arom viu-se contra dez guerreiros! Ele lutou com valentia e astúcia, porém estava cercado e em minoria!', 28153),
(145102, 'ptBR', 'Curioso.', 'Curioso.', 28153),
(145101, 'ptBR', 'À noite, os drustos atacaram!', 'À noite, os drustos atacaram!', 28153),
(145100, 'ptBR', 'O cervo sumiu na mata, e Arom acampou ali perto.', 'O cervo sumiu na mata, e Arom acampou ali perto.', 28153),
(145099, 'ptBR', '\"Qualquer um capaz de enfrentar tantos drustos assim tem lugar nas minhas florestas\", pensou ele. Então Lorde Arom tratou os ferimentos do cervo.', '\"Qualquer um capaz de enfrentar tantos drustos assim tem lugar nas minhas florestas\", pensou ele. Então Lorde Arom tratou os ferimentos do cervo.', 28153),
(145098, 'ptBR', 'Cuidado com os espinhos!', '', 28153),
(145097, 'ptBR', 'O povo de Lorde Arom precisava de comida e o cervo alimentaria muitas bocas, mas ele decidiu não abatê-lo.', 'O povo de Lorde Arom precisava de comida e o cervo alimentaria muitas bocas, mas ele decidiu não abatê-lo.', 28153),
(145096, 'ptBR', 'O cervo tinha sido atacado pelos drustos. O animal matou muitos, mas acabou ferido.', 'O cervo tinha sido atacado pelos drustos. O animal matou muitos, mas acabou ferido.', 28153),
(145095, 'ptBR', 'Um dia, Lorde Arom caçava na floresta e se deparou com um cervo branco imenso.', 'Um dia, Lorde Arom caçava na floresta e se deparou com um cervo branco imenso.', 28153),
(145094, 'ptBR', 'Isso! Nos liberte!', '', 28153),
(145093, 'ptBR', 'Você... nos libertou...', '', 28153),
(145092, 'ptBR', 'Até que enfim... livre...', '', 28153),
(145091, 'ptBR', 'Obri... gado...', '', 28153),
(145090, 'ptBR', 'Um dos nossos.', '', 28153),
(145089, 'ptBR', 'Não há escapatória.', '', 28153),
(145088, 'ptBR', '', 'Derrubem aquele ali!', 28153),
(145087, 'ptBR', '', 'Matem o meu alvo!', 28153),
(145086, 'ptBR', '', 'Fixa no inimigo!', 28153),
(145085, 'ptBR', 'Fujam! Não há esperanças!', '', 28153),
(145084, 'ptBR', 'Juntos... pela eternidade.', '', 28153),
(145083, 'ptBR', '', 'Às armas!', 28153),
(145082, 'ptBR', '', 'Pela rainha!', 28153),
(145081, 'ptBR', '', 'Pelo poder da montanha!', 28153),
(145080, 'ptBR', 'Sintam o nosso tormento!', '', 28153),
(145079, 'ptBR', '', 'Senta o relho neles!', 28153),
(145078, 'ptBR', '', 'Frenteia o inimigo!', 28153),
(145077, 'ptBR', '', 'Vocês precisam recuar!', 28153),
(145076, 'ptBR', '', 'Todo mundo! Recuar!', 28153),
(145075, 'ptBR', '', 'Corram pros pampas!', 28153),
(145074, 'ptBR', '', 'Por aqui.', 28153),
(145073, 'ptBR', '', 'Eu vou na frente.', 28153),
(145072, 'ptBR', '', 'Vem comigo.', 28153),
(145071, 'ptBR', '', 'Pela Aliança!', 28153),
(145070, 'ptBR', '', 'Arrego!', 28153),
(145069, 'ptBR', '', 'Me dá uma mão!', 28153),
(145068, 'ptBR', '', 'Lá vem aporrinhação!', 28153),
(145067, 'ptBR', '', 'Senta o relho!', 28153),
(145066, 'ptBR', '', 'Larga o dedo!', 28153),
(145065, 'ptBR', '', 'Fica aqui.', 28153),
(145064, 'ptBR', '', 'Não se mexa.', 28153),
(145063, 'ptBR', '', 'Estou muy ferida!', 28153),
(145062, 'ptBR', '', 'Eu preciso de cura!', 28153),
