(145060, 'ptBR', '', '<Grande ataque: 5 no total>', 28153),
(145059, 'ptBR', '', '<Soltando poder ou investindo contra inimigo: 4-6 no total>', 28153),
(145058, 'ptBR', '', '<Soltar feitiço, liberando energia: 3-5 no total>', 28153),
(145057, 'ptBR', '', '<Conjurando poder. Acumulando energia: 5-7 no total>', 28153),
(145056, 'ptBR', '', '<Investindo para atacar inimigo: 5-7 no total>', 28153),
(145055, 'ptBR', '', '<Sons ao morrer: 5 no total>', 28153),
