(145045, 'ptBR', '', '<Jogador sofre ferimento: 10 no total>', 28153),
(145044, 'ptBR', '', '<Jogador sofre ferimento grave: 5 no total>', 28153),
(145043, 'ptBR', '', 'Não tire os olhos do alvo.', 28153),
(145042, 'ptBR', '', 'Fazemos o que for preciso por aqueles que amamos.', 28153),
(145041, 'ptBR', '', 'Mire certo.', 28153),
(145040, 'ptBR', '', 'Adeus.', 28153),
(145039, 'ptBR', '', 'As sombras podem ser nossas aliadas... se bem controladas.', 28153),
(145038, 'ptBR', '', 'Saudações.', 28153),
(145037, 'ptBR', '', 'Não podemos convidar mais ninguém.', 28153),
(145036, 'ptBR', '', 'Cada um segue um caminho. Escolha o seu.', 28153),
(145035, 'ptBR', '', 'Não posso beber mais agora.', 28153),
(145034, 'ptBR', '', 'Ainda não tenho essa habilidade.', 28153),
(145033, 'ptBR', '', 'Ainda não posso empunhar isso.', 28153),
(145032, 'ptBR', '', 'O feitiço ainda não está pronto.', 28153),
(145031, 'ptBR', '', 'Alguma novidade?', 28153),
(145030, 'ptBR', '', 'Ainda não posso lançar isso.', 28153),
(145029, 'ptBR', '', 'Está recarregando.', 28153),
(145028, 'ptBR', '', 'Use todas as armas à sua disposição.', 28153),
(145027, 'ptBR', '', 'O dia está bom para uma caçada.', 28153),
(145026, 'ptBR', '', 'Eu desapareço por anos e anos e é assim que você me trata?', 28153),
(145025, 'ptBR', '', 'Não posso fazer isso.', 28153),
(145024, 'ptBR', '', 'Preciso de permissão pra isso.', 28153),
(145023, 'ptBR', '', 'Não posso atacar esse alvo.', 28153),
(145022, 'ptBR', '', 'Meu caos vai consumir você... é só pedir com jeitinho.', 28153),
(145021, 'ptBR', '', 'Não posso atacar isso.', 28153),
(145020, 'ptBR', '', 'Meu inventário está cheio.', 28153),
(145019, 'ptBR', '', 'Não posso carregar mais.', 28153),
(145018, 'ptBR', '', 'Irmãs sãos complicadas. Especialmente as mortas-vivas.', 28153),
(145017, 'ptBR', '', 'Está trancado.', 28153),
(145016, 'ptBR', '', 'Não tenho como carregar mais disso.', 28153),
