(145009, 'ptBR', '', 'Minha dor está baixa.', 28153),
(145008, 'ptBR', '', 'Isso não é uma bolsa.', 28153),
(145007, 'ptBR', '', 'Não tenho moedas suficientes.', 28153),
(145006, 'ptBR', '', 'Não tenho como pagar.', 28153),
(145005, 'ptBR', '', 'Caro demais.', 28153),
(145004, 'ptBR', '', 'Essa pessoa não pode entrar no grupo.', 28153),
