(145002, 'ptBR', '', 'Sem energia suficiente.', 28153),
(145001, 'ptBR', '', 'Não tenho energia suficiente.', 28153),
(145000, 'ptBR', '', 'Preciso de mana primeiro.', 28153),
(144999, 'ptBR', '', 'Meu mana está baixo.', 28153),
(144998, 'ptBR', '', 'Preciso de mana.', 28153),
(144997, 'ptBR', '', 'Raiva insuficiente.', 28153),
(144996, 'ptBR', '', 'Preciso de mais raiva.', 28153),
(144995, 'ptBR', '', 'Longe demais.', 28153),
(144994, 'ptBR', '', 'Ora, é lógico que ainda o amo. Dá para cuidar da sua vida?', 28153),
