INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144985, 'ptBR', '', 'Não posso fazer isso aqui.', 28153),
(144984, 'ptBR', '', 'Não posso largar isso.', 28153),
(144983, 'ptBR', '', 'Isso está vinculado a mim.', 28153),
(144982, 'ptBR', '', 'Não posso usar isso.', 28153),
(144981, 'ptBR', '', 'Não tenho nível suficiente pra usar isso.', 28153),
(144980, 'ptBR', '', 'Ainda não posso usar isso.', 28153),
(144979, 'ptBR', '', 'Não tenho nível de perícia suficiente para usar isso.', 28153),
(144978, 'ptBR', '', 'Nunca vou poder usar isso.', 28153),
(144977, 'ptBR', '', 'Não posso aprender esse feitiço.', 28153),
(144976, 'ptBR', '', 'Não posso saquear isso.', 28153),
(144975, 'ptBR', '', 'Isso não é meu.', 28153),
(144974, 'ptBR', '', 'Preciso chegar mais perto.', 28153),
(144973, 'ptBR', '', 'Está longe demais.', 28153),
(144972, 'ptBR', '', 'Não consigo alcançar.', 28153),
(144971, 'ptBR', '', 'Não posso trocar isso.', 28153),
(144970, 'ptBR', '', 'Não posso usar isso.', 28153),
(144969, 'ptBR', '', 'Não estou equipada com o item.', 28153),
(144968, 'ptBR', '', 'Preciso me equipar primeiro.', 28153),
(144967, 'ptBR', '', 'Não posso saquear isso no momento.', 28153),
(144966, 'ptBR', '', 'Não tenho nenhum alvo.', 28153),
(144965, 'ptBR', '', 'Preciso de um alvo antes.', 28153),
(144964, 'ptBR', '', 'Preciso de um alvo.', 28153),
(144963, 'ptBR', '', 'Das energias macabras os espíritos aparecem, e graças a eles as minhas vinhas crescem!', 28153),
(144962, 'ptBR', '', 'Me passa logo a íris, irmã!', 28153),
(144961, 'ptBR', '', 'Meus espinhos vão te rasgar ao meio!', 28153),
(144960, 'ptBR', '', 'Quanto mais resistir, mais sangrará!', 28153),
(144959, 'ptBR', '', 'Você tem a marca negra!', 28153),
(144958, 'ptBR', '', 'Seus crânios darão um ótimo enfeite.', 28153),
(144956, 'ptBR', '', 'Minhas raízes brotarão de novo…', 28153),
(144955, 'ptBR', '', 'Adoro o som de ossos quebrando.', 28153),
(144954, 'ptBR', 'Vou comer bem hoje de noite. Muito obrigado, e os deuses te abençoem.', 'Vou comer bem hoje de noite. Muito obrigada, e os deuses te abençoem.', 28153),
(144953, 'ptBR', 'Só tenho gratidão. Valeu!', 'Só tenho gratidão. Valeu!', 28153),
(144952, 'ptBR', 'Obrigado, camarada.', 'Obrigada, camarada.', 28153),
(144951, 'ptBR', '', 'Mas que ossos frágeis!', 28153),
(144950, 'ptBR', '<Dê dez moedas de ouro.>', '<Dê dez moedas de ouro.>', 28153),
(144949, 'ptBR', '<Dê uma moeda de ouro.>', '<Dê uma moeda de ouro.>', 28153),
(144948, 'ptBR', '<Dê cinco moedas de cobre.>', '<Dê cinco moedas de cobre.>', 28153),
(144947, 'ptBR', 'Uma esmola, amizade?', 'Uma esmola, amizade?', 28153),
(144946, 'ptBR', '', 'Cadáveres podres e gritos horrendos, eu sinto alegria em vê-los morrendo!', 28153),
(144945, 'ptBR', '', 'Sua destruição está próxima!', 28153),
(144944, 'ptBR', '', 'Você teve a sua chance!', 28153),
(144943, 'ptBR', '', '...e Rezan rugiu sobre os cadáveres do exército sanguitrólico. Triunfante!', 28153),
(144942, 'ptBR', '', 'Seu tormento está longe de acabar.', 28153),
(144941, 'ptBR', '', 'Que delícia de agonia!', 28153),
(144940, 'ptBR', '', 'Meu corpo se foi... mas minha maldição... ainda vive...', 28153),
(144939, 'ptBR', '', 'Arrancarei gritos do seu corpo!', 28153),
(144938, 'ptBR', '', 'Alma enegrecida, tenebrosa escuridão, acabe com aqueles que estão na minha visão!', 28153),
(144937, 'ptBR', '', 'Você pertence a mim!', 28153),
(144936, 'ptBR', '', 'Dance, meu fantoche! Dance!', 28153),
(144935, 'ptBR', '', 'Entregue-me a íris, sua idiota! Só eu sei canalizar o poder dela!', 28153),
(144934, 'ptBR', '', 'Suas almas pertencem a mim... para sempre.', 28153),
(144933, 'ptBR', '', 'A morte não me deterá...', 28153),
(144932, 'ptBR', '', 'Mas que alma frágil!', 28153),
(144931, 'ptBR', '', 'Você não tem poder aqui!', 28153),
(144930, 'ptBR', '', '$n, vem comigo. O resto vai com Rokhan pra linha do norte.', 28153),
(144929, 'ptBR', 'Olha essas tropas da Aliança! Eles tão vindo com tudo pra cima da gente!', '', 28153),
(144928, 'ptBR', 'Eles mandaram uma penca de soldados pra cá! Não deixa eles passarem!', '', 28153),
(144926, 'ptBR', '', 'Saudações, $c.', 28153),
(144925, 'ptBR', '', 'Sempre carregue consigo o que significa ser jurado à Luz.', 28153),
(144924, 'ptBR', '', '<Fareeya recebe você com um sorriso caloroso.>$B$BBom trabalho nas provações, $c. Mas sinto que tua história está apenas começando.', 28153),
(144923, 'ptBR', 'Se é Maela que procuras, ela está ajudando nas linhas de frente!$B$BVentobravo abriga vários alfaiates competentes, capazes de ensinar-te algo.', '', 28153),
(144921, 'ptBR', '', 'Que a Luz leve esta mesa! Eu talvez jamais consiga usar esta oficina outra vez.$B$BA mácula das peles das feras de Argus persiste, não importa o quanto eu esfregue o tampo.', 28153),
(144908, 'ptBR', 'A Vindicaar espera a próxima viagem dela.\n\nAssim como eu.', '', 28153),
(144907, 'ptBR', 'Agradeço a tua ajuda, $Gguri:guria;! Te devo uma!', '', 28153),
(144906, 'ptBR', 'Bom, agora vou na taberna traguear.', '', 28153),
(144905, 'ptBR', 'Ah, agora, sim. Uma armadura digna de herói! Um herói cujos feitos lendários abalam até as bases de Azeroth!', '', 28153),
(144904, 'ptBR', 'Tu pode apostar! Eu comprei essa armadura sem entrevero, apesar de ainda faltar uns caraminguás.', '', 28153),
(144903, 'ptBR', '', 'Parece que hoje é seu dia de sorte, Sr. Pedracenho. Pode pegar a mercadoria de volta.', 28153),
(144902, 'ptBR', 'Tira tuas patas de cima de mim, bola de pelo!', '', 28153),
(144901, 'ptBR', '', 'Sim, madame.', 28153),
(144900, 'ptBR', '', 'Ide embora! Não temos medo de vós!', 28153),
(144899, 'ptBR', '%s acena com a cabeça.', '', 28153),
(144898, 'ptBR', '', 'Mestre Chu, por favor acompanhe este anão. Srta. Xiulan, coloque a armadura à venda de novo.', 28153),
(144897, 'ptBR', 'Eu juro que mandei o pagamento hoje de manhã! Tu não pode me deixar a ver navios!', '', 28153),
(144896, 'ptBR', '', 'Você atrasou seu pagamento mais uma vez, Sr. Pedracenho. Conforme dispõe nosso contrato, estou tomando de volta a mercadoria.', 28153),
(144895, 'ptBR', '', 'Eles estão aqui...', 28153),
(144894, 'ptBR', '', 'Nós vamos salvá-lo. Pode descansar.', 28153),
(144893, 'ptBR', 'Eles saíram da floresta. Nó...no... nós lutamos. O Mestre Azinhal me tirou da frente, mas acabou sendo levado. Nós temos que salvá-lo!', '', 28153),
(144892, 'ptBR', '', 'Eu sei que sim, Martino. Diga o que aconteceu.', 28153),
(144891, 'ptBR', 'Eu fiz de tudo para detê-los!', '', 28153),
(144889, 'ptBR', '', 'Então... por que você trouxe o anão? Demonstração de força? Dissuasão?', 28153),
(144888, 'ptBR', 'Funcionou exatamente como eu imaginei que funcionaria.', '', 28153),
(144887, 'ptBR', '... Certo... Sim. É claro!', '', 28153),
(144886, 'ptBR', 'Não podemos esquecer do nosso objetivo aqui: achar o Olho antes da Aliança.', '', 28153),
(144885, 'ptBR', '', 'E pensar que os trolls talvez estejam sentados sobre o maior achado arqueológico do milênio!', 28153),
(144884, 'ptBR', '', 'A batalha começou! Lidere a nossa vitória!', 28153),
(144883, 'ptBR', 'Quando saiu, você disse ao seu pai que estava saindo para explorar. E não para negociar com aqueles inúteis da Horda.', '', 28153),
(144882, 'ptBR', 'Princesa.', '', 28153),
(144881, 'ptBR', 'Seu pai está esperando.', '', 28153),
(144880, 'ptBR', '', 'Princesa... permita que eu seja o primeiro a dar as boas-vindas...', 28153),
(144879, 'ptBR', '', 'Fique sabendo... meu pai é cabeça-dura, mas observa tudo. Eu aposto que ele já sabe o papel que você teve na minha fuga de Ventobravo.', 28153),
(144878, 'ptBR', '', 'O destino deles não será decidido por você, General.', 28153),
(144877, 'ptBR', 'A melhor forma de proteger o reino seria eu banir essa... coisa... pra Vol\'dun. Não tem lugar pra Horda em Zandalar.', '', 28153),
(144876, 'ptBR', '', 'Você jurou proteger esse reino. Se não cumprir o seu dever, eu vou encontrar alguém que cumpra.', 28153),
(144875, 'ptBR', '<Toque a lágrima.>', '<Toque a lágrima.>', 28153),
(144874, 'ptBR', '', 'General.', 28153),
(144873, 'ptBR', '<Uma lágrima de dragão verde, lançada na sombra por forças desconhecidas.>', '', 28153),
(144872, 'ptBR', '', 'Enquanto isso, o Conselho Zanchuli nega o perigo. Esse bando de políticos corruptos e velhos caquéticos convenceu meu pai de que nada precisa ser feito.', 28153),
(144871, 'ptBR', '', 'Os trolls sangrentos estão entrando pela fronteira do norte. Eles arrastam nosso povo pros pântanos de Nazmir e dão sumiço neles.', 28153),
(144870, 'ptBR', '', 'Zandalar está cercada de inimigos, por dentro e por fora. Por isso eu fui atrás da Horda... e atrás de você, que tem façanhas heroicas incomparáveis.', 28153),
(144869, 'ptBR', '', 'Nossa privacidade não vai durar muito tempo, $n. Tem coisas sobre o meu reino que você precisa saber.', 28153),
(144868, 'ptBR', '', 'Venha, valente da Horda. Vamos fazer uma visitinha ao meu pai. Zul... nos falamos depois.', 28153),
(144867, 'ptBR', '', 'Tze\'na! Oi, mocinha. Sentiu minha falta?', 28153),
(144866, 'ptBR', '', 'Eu ouvi os gritos dessa criança a que tu te referes.\n\nEu te darei uma marca, para que tu possas atravessar este reino e procurá-la.\n\nEla vive em um lugar onde a barreira entre os reinos da vida e da morte é fina e permite a passagem.\n\nSaiba que tu não terás poder nesse lugar: os que lá habitam não podem ser feridos pelos mortais.\n\nPor mais que tentes, talvez não possas prestar auxílio à tua amiga.', 28153),
(144864, 'ptBR', 'Que a Luz esteja contigo.', 'Que a Luz esteja contigo.', 28153),
(144863, 'ptBR', 'Estou procurando uma garotinha chamada Uuna. Ela passou por aqui?', 'Estou procurando uma garotinha chamada Uuna. Ela passou por aqui?', 28153),
(144862, 'ptBR', '', 'T\'paartos nos ensinou a jogar pedregulho, pergaminho e lâmina, mas eu esqueci as regras.', 28153),
(144860, 'ptBR', 'O Portão da Aliança foi destruído!', '', 28153),
(144859, 'ptBR', '', 'Grifos! Atacar!', 28153),
(144853, 'ptBR', 'Nossos mais bravos guerreiros geralmente são a vanguarda. Cuidar da família deles até que voltem é o mínimo que posso fazer.', 'Nossos mais bravos guerreiros geralmente são a vanguarda. Cuidar da família deles até que voltem é o mínimo que posso fazer.', 28153),
(144852, 'ptBR', 'Entrou nos meus túneis? Que idiotice!', '', 28153),
(144851, 'ptBR', '', 'A cauda é tão fofinha!', 28153),
(144850, 'ptBR', '', 'Posso ficar?', 28153),
(144849, 'ptBR', '', 'Não! Fica para contar histórias de aventuras, T\'paartos!', 28153),
(144848, 'ptBR', '', 'Ele voltou!', 28153),
(144847, 'ptBR', '', 'É T\'paartos!', 28153),
(144846, 'ptBR', 'Não se preocupem! T\'paartos retornará com mais histórias e talvez trazendo outro amiguinho.', '', 28153),
(144845, 'ptBR', 'Agora T\'paartos tem de levar esta criaturinha de volta. Despeçam-se, crianças.', '', 28153),
(144842, 'ptBR', '', 'Aah!', 28153),
(144841, 'ptBR', 'Me diga o que aconteceu no banquete.', 'Me diga o que aconteceu no banquete.', 28153),
(144840, 'ptBR', 'A Dama Sombria tem um trabalho importante para você, $c. Espero que você esteja pront$Go:a;...', '', 28153),
(144839, 'ptBR', '', 'T\'paartos!', 28153),
(144838, 'ptBR', '', 'Promete que não me deixarás aqui, amig$Go:a;. Mesmo quando escurecer...', 28153),
(144837, 'ptBR', '', 'Mas agora tu estás aqui. Juntos, nós podemos enfrentá-los! Eu acho...', 28153),
(144836, 'ptBR', '', 'Eu corro, corro... mas eles acabam me encontrando.', 28153),
(144835, 'ptBR', '', 'Em breve eles estarão aqui, amig$Go:a;.', 28153),
(144834, 'ptBR', '', 'Aí estás! Ainda bem.', 28153),
(144833, 'ptBR', 'Haha! T\'paartos fica feliz em ver que você está bem! T\'paartos também trouxe um presente. Esta coisa diminuta estava em Val\'sharah.', '', 28153),
(144832, 'ptBR', 'Você está BRINCANDO?!', '', 28153),
(144831, 'ptBR', 'Parece que esses globos contém algum tipo de poder. Será que se eu remover a camada externa...', '', 28153),
(144830, 'ptBR', 'Gah!', '', 28153),
(144829, 'ptBR', 'Estes olhos estão bem cheios e redondos. Eu vou apenas espremer umas gotas deles e...', '', 28153),
(144828, 'ptBR', '', 'Estou com tanto frio, e está tão escuro aqui. Não sei o que fazer!', 28153),
(144827, 'ptBR', '', 'Eu não desistirei, amig$Go:a;! Eu prometo!', 28153),
(144826, 'ptBR', '', 'Amig$Go:a;? És tu?', 28153),
(144825, 'ptBR', 'Nossos agentes já se infiltraram na operação de mineração dos goblins. Em breve ficaremos sabendo o que eles estão armando...', '', 28153),
(144824, 'ptBR', 'Devia ter... cavado... mais...', 'Devia ter... cavado... mais...', 28153),
(144823, 'ptBR', '$GUm elfo:Uma elfa;... cavando... ha!', '$GUm elfo:Uma elfa;... cavando... ha!', 28153),
(144822, 'ptBR', 'Chegou tarde. Agora é nosso...', 'Chegou tarde. Agora é nosso...', 28153),
(144821, 'ptBR', 'Achado não é roubado...', 'Achado não é roubado...', 28153),
(144820, 'ptBR', 'Tu nunca vai encontrar...', 'Tu nunca vai encontrar...', 28153),
(144819, 'ptBR', 'Tua busca acabou. Morra!', 'Tua busca acabou. Morra!', 28153),
(144818, 'ptBR', 'Eu vou te enterrar é com gosto.', 'Eu vou te enterrar é com gosto.', 28153),
(144817, 'ptBR', 'Nós vamos cavar até a sola da tua bota!', 'Nós vamos cavar até a sola da tua bota!', 28153),
(144816, 'ptBR', 'Quem mandou tu te meter com os Ferro Negro? Ideia de jerico.', 'Quem mandou tu te meter com os Ferro Negro? Ideia de jerico.', 28153),
(144815, 'ptBR', 'Elfos intrometidos! Essas ruínas pertencem ao Ferro Negro!', 'Elfos intrometidos! Essas ruínas pertencem ao Ferro Negro!', 28153),
(144812, 'ptBR', '', 'Reforços inimigos vindo aí!', 28153),
(144811, 'ptBR', 'A leitura é inconfundível! Para o oeste!', '', 28153),
(144810, 'ptBR', '', 'A ravina é nossa! Reagrupar! Temos que planejar o próximo ataque.', 28153),
(144809, 'ptBR', '', 'Tu quer enfiar um totem quadrado no lugar do totem redondo. Vodu não é bagunça, goblina.', 28153),
(144808, 'ptBR', 'Eles surgiram das sombras. Estão em toda parte!', 'Eles surgiram das sombras. Estão em toda parte!', 28153),
(144807, 'ptBR', '', 'Uma virtude e tanto. É algo que admiro nele.', 28153),
(144806, 'ptBR', '', 'Ah, sim, igual a ontem, anteontem e antes de anteontem!', 28153),
(144805, 'ptBR', 'Os túneis estão sob controle. Abram o portão!', '', 28153),
(144804, 'ptBR', 'Ele está bem animado hoje, não é?', '', 28153),
(144803, 'ptBR', '', 'O inimigo vem aí! Bwonsalaka!', 28153),
(144802, 'ptBR', 'Retornarei aos outros. Precisamos dar fim a essa situação enquanto ainda há tempo.', '', 28153),
(144801, 'ptBR', 'Obrigado, $p. Temo que seja muito pior do que pensávamos.', '', 28153),
(144800, 'ptBR', 'Me diga o que aconteceu no Repouso do Leão.', 'Me diga o que aconteceu no Repouso do Leão.', 28153),
(144799, 'ptBR', 'Meus agentes tomaram o controle desta área. Ainda assim, é sempre prudente manter a voz baixa.', '', 28153),
(144798, 'ptBR', 'Bwon\'chaga di choka!', 'Bwon\'chaga di choka!', 28153),
(144796, 'ptBR', '', 'O vodu toca todos os corações, Cala, eles acreditando ou não.', 28153),
(144795, 'ptBR', '', 'Dá para ler mente de dinossauro com vodu? Sério!?', 28153),
(144794, 'ptBR', '', 'Isso é questão de amor, Cala. O coração, até o seu, sabe que o vodu é melhor que o cérebro.', 28153),
(144792, 'ptBR', 'Agora, tua vontade me pertence!', 'Agora, tua vontade me pertence!', 28153),
(144791, 'ptBR', 'Os vapores trazem a verdade!', 'Os vapores trazem a verdade!', 28153),
(144790, 'ptBR', 'Respira fundo!', 'Respira fundo!', 28153),
(144789, 'ptBR', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|tRezan |cFFFF0000|Hspell:260683|h[desperta]|h|r todas as outras pilhas de ossos!', '||TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|tRezan |cFFFF0000|Hspell:260683|h[desperta]|h|r todas as outras pilhas de ossos!', 28153),
(144788, 'ptBR', '', 'G\'huun...', 28153),
(144787, 'ptBR', '', 'Não... assim, não...', 28153),
(144786, 'ptBR', '', 'As manas... vão... me... vingar...', 28153),
(144785, 'ptBR', '', 'Gachaga!', 28153),
(144784, 'ptBR', '', 'Zuldazar... vai... cair...', 28153),
(144783, 'ptBR', '', 'A máter... me vingará...', 28153),
(144782, 'ptBR', '', 'Mas eu devia ser a mais forte...', 28153),
(144781, 'ptBR', '', 'Pohkiza...', 28153),
(144780, 'ptBR', 'Que maravilha...', '', 28153),
(144779, 'ptBR', 'Excelente trabalho com as poções, $n. Agora só basta eu adicionar umas gotas de cada uma e...', '', 28153),
(144778, 'ptBR', '', 'Vai ser molezinha!', 28153),
(144777, 'ptBR', '', 'Vai ser rápido!', 28153),
(144776, 'ptBR', '', 'Rá! Tu não dá nem pro começo!', 28153),
(144775, 'ptBR', '', 'Mais um crânio pra minha coleção!', 28153),
(144774, 'ptBR', '', 'Estas terras são nossas!', 28153),
(144773, 'ptBR', 'Vamos! Por aqui! Temos trabalho a fazer!', '', 28153),
(144772, 'ptBR', 'É bom parar para descansar vez ou outra.$B$BEspecialmente após um empreendimento lucrativo!', '', 28153),
(144771, 'ptBR', 'Apague aqueles incêndios e eu providencio o que precisamos no laboratório. Oh, vai ser tão divertido!', '', 28153),
(144770, 'ptBR', 'Eu estou sem matéria-prima no momento. Perdão.', '', 28153),
(144769, 'ptBR', 'Tenho vários globos para você, Elric.', 'Tenho vários globos para você, Elric.', 28153),
(144768, 'ptBR', 'Trouxe estas plantas para você.', 'Trouxe estas plantas para você.', 28153),
(144767, 'ptBR', 'Aqui estão os olhos que você pediu.', 'Aqui estão os olhos que você pediu.', 28153),
(144766, 'ptBR', 'Aqui estão as poções de que você precisava.', 'Aqui estão as poções de que você precisava.', 28153),
(144765, 'ptBR', 'Ah, $gum:uma; colega de alquimia! Talvez você se interesse por algumas das minhas últimas receitas.$b$bMinha especialidade é criar poções, mas eu também mexo com transmutação de vez em quando.', '', 28153),
(144764, 'ptBR', 'Seja muito bem-vind$Uo:a; à minha loja, $c! Que tal se refrescar tomando um trago? Ou alguma outra coisa despertou seu interesse?$b$bMinha especialidade é criar poções, mas eu também mexo com transmutação de vez em quando.', '', 28153),
(144763, 'ptBR', '', 'Carne fresca!', 28153),
(144762, 'ptBR', '', 'Vou botar as orelhas deles num colar!', 28153),
(144761, 'ptBR', '', 'Sangue para G\'huun!', 28153),
(144760, 'ptBR', 'Shh! Não te mexas! A visão dele depende de movimento.', 'Shh! Não te mexas! A visão dele depende de movimento.', 28153),
(144759, 'ptBR', 'Que a Luz me preserve... ele voltou.', 'Que a Luz me preserve... ele voltou.', 28153),
(144758, 'ptBR', 'O Vindicante Forjado a Luz geme.', 'O Vindicante Forjado a Luz geme.', 28153),
(144757, 'ptBR', 'Creio que minha mente se perdeu.', 'Creio que minha mente se perdeu.', 28153),
(144756, 'ptBR', 'Que a Mãe Terra abençoe você!', 'Que a Mãe Terra abençoe você!', 28153),
(144755, 'ptBR', 'Foi horrível, $r.', 'Foi horrível, $r.', 28153),
(144754, 'ptBR', 'Tenho que... Minha mente... Tenho que sair deste lugar!', 'Tenho que... Minha mente... Tenho que sair deste lugar!', 28153),
(144753, 'ptBR', 'Os sussurros... estavam me enlouquecendo!', 'Os sussurros... estavam me enlouquecendo!', 28153),
(144752, 'ptBR', 'Agradeço, campe$Gão:ã;.', 'Agradeço, campe$Gão:ã;.', 28153),
(144751, 'ptBR', '', 'Até as melhores armas perdem o fio com o tempo. Você deve se recuperar, T\'paartos.', 28153),
(144750, 'ptBR', 'T\'paartos oferece gratidão a Lysara. T\'paartos sente que está pronto para lutar novamente!', '', 28153),
(144749, 'ptBR', 'Pouco tempo disponível para deter T\'paartos!', '', 28153),
(144748, 'ptBR', 'Toma aqui meu amuleto de efígie. Confia em mim, é a melhor parada que eu tenho.', '', 28153),
(144747, 'ptBR', 'Isso é que é que manjar das forjarias! Com quem tu descolou isso? Não precisa dizer o nome! Só manda vir falar comigo.', '', 28153),
(144746, 'ptBR', 'Fica de bico fechado. Não conta pra ninguém onde tu arrumou isso, senão te mostro de onde vem meu nome.', '', 28153),
(144745, 'ptBR', '', 'De novo, T\'paartos? Quantas vezes você...', 28153),
(144744, 'ptBR', 'Não é a cabeça de uma elfa noturna qualquer... Milhares de anos atrás, ela era da realeza!', '', 28153),
(144743, 'ptBR', 'Só o tempo dirá. Tome cuidado com essa flor-de-século, $p. Elas só surgem a cada cem anos.', '', 28153),
(144742, 'ptBR', '', 'Sementes douradas! A gente tem que plantar isso agora mesmo pro rei. O que tu acha que vai brotar, Jaden?', 28153),
(144741, 'ptBR', 'Essa pimenta vai casar direitinho com meu próximo chili extra-apimentado... e aquelas sementes douradas têm gosto de pano de chão!', '', 28153),
(144740, 'ptBR', '', 'Elas eram reais. São reais. Lady Lucília está determinada a retomar nossas terras e nosso povo.', 28153),
(144739, 'ptBR', 'Se ela fizer isso, terá todo o meu apoio.', '', 28153),
(144738, 'ptBR', 'Foi mesmo? Achei que era só lenda!', '', 28153),
(144737, 'ptBR', '', 'É inquisidora agora, Prefeita. Lady Lucília reformou a Ordem das Brasas para combater essas bruxas.', 28153),
(144736, 'ptBR', 'Não temos como agradecer o fato de você ter aparecido na hora certa, Tenente.', '', 28153),
(144735, 'ptBR', '', 'Valeu, $p! O estoque de pedra de regresso da gente tava no fim. Toma uma aí por conta da casa.', 28153),
(144734, 'ptBR', 'Tu tá a fim de pegar trampo, $p? Acha alguém que tenha pedra de regresso. Se tu conseguir fazer um esquema bom, eu dou um jeito de te recompensar.', '', 28153),
(144733, 'ptBR', 'Já sabe o que isso significa... madeira grátis!', '', 28153),
(144732, 'ptBR', 'Ei, hã... chefia? Tão rolando uns boatos de que tem uma coisa... tipo um... monstro-árvore perambulando pela mata.', '', 28153),
(144731, 'ptBR', 'Currupaco! Tua mãe é um trogg! Currupaco!', '', 28153),
(144730, 'ptBR', 'Seus buchos de lombriga desenxabidos! Currupaco!', '', 28153),
(144729, 'ptBR', 'QUAC!', '', 28153),
(144728, 'ptBR', 'Psiu, $p, tu já quis socar alguém na fuça, mas não socou porque ia dar ruim? Eu tenho a solução pro teu problema!', '', 28153),
(144727, 'ptBR', 'Amuletos magníficos! Relíquias raras! Promoções especiais pra compradores de primeira classe!', '', 28153),
(144726, 'ptBR', 'Escute os sussurros. São tão belos.', 'Escute os sussurros. São tão belos.', 28153),
(144725, 'ptBR', 'As sombras consumirão você.', 'As sombras consumirão você.', 28153),
(144724, 'ptBR', 'Bênção e grito de guerra é coisa do passado! Só azerita pra dar conta dos perigos e tretas desse mundão louco de hoje. Ooolha o suquinho de azerita! Oooolha o suco! Na minha mão é mais barato! Ooooolha o suco!', '', 28153),
(144723, 'ptBR', 'Sua morte é necessária.', 'Sua morte é necessária.', 28153),
(144722, 'ptBR', 'FAÇA ISSO PARAR!', 'FAÇA ISSO PARAR!', 28153),
(144721, 'ptBR', 'A Escuridão se aproxima...', 'A Escuridão se aproxima...', 28153),
(144720, 'ptBR', 'Se Vol\'jin tivesse com o totem da invulnerabilidade lá na Costa Partida, ele ainda tava aqui hoje. Não vai dar o mesmo vacilo que o cara!', '', 28153),
(144719, 'ptBR', 'Espie teus inimigos, fique de olho nos amigos e ainda dê aquela bizolhada na corte real... tudo isso com este incrível totem de fogos-fátuos sussurrantes!', '', 28153),
(144718, 'ptBR', 'A chama desse totem tá acesa desde que o Rei Rastakhan sentou no trono. Essa parte da história Zandalari pode ser tua hoje mesmo!', '', 28153),
(144717, 'ptBR', 'Promoção do Trambik: comprou sem perguntar, ganha desconto!', '', 28153),
(144716, 'ptBR', 'T\'paartos está aqui!', '', 28153),
(144715, 'ptBR', '', 'Já me sinto bem melhor.', 28153),
(144714, 'ptBR', 'T\'PAARTOS!', '', 28153),
(144713, 'ptBR', '', 'Tu não podes enfrentar a escuridão sem coroa, amig$Go:a;. É a regra.', 28153),
(144712, 'ptBR', '', 'Solta estrelas! Os malvados odeiam isso.', 28153),
(144711, 'ptBR', 'Nós somos coletores e mantenedores do conhecimento. \n\nMeu trabalho é cuidar para que nossas descobertas sejam arquivadas da forma correta.', '', 28153),
(144706, 'ptBR', 'Eu tenho muito o que fazer. Cuide deles.', 'Eu tenho muito o que fazer. Cuidem deles.', 28153),
(144705, 'ptBR', 'Essa conversinha me cansa.', 'Essa conversinha me cansa.', 28153),
(144704, 'ptBR', 'Essas vozes contam apenas mentiras!', '', 28153),
(144703, 'ptBR', 'Você não sente a Grandiosa nas profundezas? Graças a ela é que voltaremos à plenitude!', 'Você não sente a Grandiosa nas profundezas? Graças a ela é que voltaremos à plenitude!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144702, 'ptBR', 'Juramos proteger Brennadam. Proteger nosso povo! Você esqueceu nossos juramentos?', '', 28153),
(144701, 'ptBR', 'Você sempre foi fraco demais para servir o Lorde Trovamare, vadeando por Brennadam feito um tolo.', 'Você sempre foi fraco demais para servir o Lorde Trovamare, mofando em Brennadam feito um tolo.', 28153),
(144700, 'ptBR', 'É você quem está perdido!', '', 28153),
(144699, 'ptBR', 'Que os mares... lhe traguem...', '', 28153),
(144698, 'ptBR', 'Minha vida... por... Azshara...', '', 28153),
(144697, 'ptBR', 'Que o abismo carregue você...', '', 28153),
(144696, 'ptBR', 'Minha rainha... eu... fracassei...', '', 28153),
(144695, 'ptBR', 'A maré... recua...', '', 28153),
(144694, 'ptBR', '', 'A maré... recua...', 28153),
(144693, 'ptBR', '', 'Minha rainha... eu... fracassei...', 28153),
(144692, 'ptBR', '', 'Que o abismo carregue você...', 28153),
(144691, 'ptBR', '', 'Minha vida por Azshara!', 28153),
(144690, 'ptBR', '', 'Que os mares... lhe traguem...', 28153),
(144689, 'ptBR', 'Tenho outra pergunta...', 'Tenho outra pergunta...', 28153),
(144688, 'ptBR', 'Parece que você está precisando de uma mão amiga.', 'Parece que você está precisando de uma mão amiga.', 28153),
(144687, 'ptBR', 'O que vocês estão fazendo?', 'O que vocês estão fazendo?', 28153),
(144686, 'ptBR', 'Eu vim ajudar, Kugro!', 'Eu vim ajudar, Kugro!', 28153),
(144685, 'ptBR', 'Pode dar uma olhada neste pergaminho?', 'Pode dar uma olhada neste pergaminho?', 28153),
(144684, 'ptBR', 'Poupe seu fôlego, jovem. \n\nSeja lá o que você quer, eu não tenho tempo.', '', 28153),
(144683, 'ptBR', 'Mão amiga, não. Mas uma mão trabalhadora seria bom.', '', 28153),
(144682, 'ptBR', 'Eu posso lhe dizer o que eu não vou fazer: ficar de conversa mole com $Gum:uma; $r quando tem tanto trabalho a fazer.', '', 28153),
(144681, 'ptBR', 'Nesse caso, espero que você consiga fazer várias coisas ao mesmo tempo.', '', 28153),
(144680, 'ptBR', 'Eu não estou pegando outros serviços agora. Eu já estou atrasado aqui. Se eu não redigir esses pergaminhos, ninguém o fará.', '', 28153),
(144679, 'ptBR', 'Estou no vermelho.', '', 28153),
(144678, 'ptBR', '', '<O olhar de Arluelle vaga por algum lugar distante.>$B$BSe ao menos meu irmão pudesse ver a cidade agora...', 28153),
(144677, 'ptBR', '', 'Tenho a impressão de que nossa cidade será convocada em breve. Espero estar pronta quando o momento chegar.', 28153),
(144676, 'ptBR', 'É uma pena que não pudemos convencer os Forjados a Luz a se aliarem a nós. A destreza marcial deles é formidável.', '', 28153),
(144675, 'ptBR', 'Em que número eu parei mesmo? Argh!', '', 28153),
(144674, 'ptBR', 'Será bom para a Vigia Crepuscular ter a Victória novamente.', '', 28153),
(144673, 'ptBR', '', 'É melhor a gente ir.', 28153),
(144672, 'ptBR', 'Fico feliz de ver que Arluelle continua treinando. Ela até já parece mais forte.$B$BTalvez eu deva avaliar o quanto ela evoluiu.', '', 28153),
(144671, 'ptBR', 'A maré virou, Irmão. Se você não ficar do nosso lado, está perdido.', 'A maré virou, Irmão. Se você não ficar do nosso lado, está perdido.', 28153),
(144670, 'ptBR', 'Um pra você. Dois para mim.', '', 28153),
(144669, 'ptBR', 'Maquiar as contas deixa tudo lindo!', '', 28153),
(144668, 'ptBR', 'Reid! A frota deve retornar a Kul Tiraz imediatamente!', '', 28153),
(144667, 'ptBR', 'Eu já contei esta pilha?', '', 28153),
(144666, 'ptBR', 'Um... Dois... Sete... Vermelho... Dois...', '', 28153),
(144665, 'ptBR', '', 'Caso você não saiba, eu sou ótima com explosivos... e adivinha quem tá subindo rapidinho na minha lista de alvos!', 28153),
(144664, 'ptBR', '', 'Vai, continua assim e depois não reclama se acontecer algum \"acidentezinho\".', 28153),
(144663, 'ptBR', '', 'Ugh! Você me paga por isso!', 28153),
(144662, 'ptBR', '', 'Falou, chapa.', 28153),
(144661, 'ptBR', '', 'Ahn? É só isso?', 28153),
(144660, 'ptBR', '', 'Até mais!', 28153),
(144659, 'ptBR', '', 'Tá precisando do quê, cara?', 28153),
(144658, 'ptBR', '', 'Tudo in riba?', 28153),
(144657, 'ptBR', '', 'E aí, chapa, qual a boa?', 28153),
(144656, 'ptBR', 'É, acho que a minha vida agora vai ser ASSIM. Ótimo. Tô a-do-ran-do.', '', 28153),
(144655, 'ptBR', 'Ah, então é assim que vai ser, né? Serião? Beleza, então vai, cutuca, cutuca, cutuca, cutuca...', '', 28153),
(144654, 'ptBR', 'Você não tem nada melhor pra fazer? Tipo, hm... beijar um murloc, sei lá?', '', 28153),
(144653, 'ptBR', 'Ah, qual é! Eu mereço mais respeito que isso!', '', 28153),
(144652, 'ptBR', 'Tá, tá... tanto faz.', '', 28153),
(144651, 'ptBR', 'Vamos lá, circulando...', '', 28153),
(144650, 'ptBR', 'Até!', '', 28153),
(144649, 'ptBR', 'Carregado e engatilhado!', '', 28153),
(144648, 'ptBR', 'Pronto pra briga!', '', 28153),
(144647, 'ptBR', 'Continua essa clicação pra ver. Eu te arranco o dedo.', '', 28153),
(144646, 'ptBR', 'Meu dia até que tava indo bem.', '', 28153),
(144645, 'ptBR', 'Oi, meu nome é Mathiaz, mas pode me chamar de \"senhor\".', '', 28153),
(144644, 'ptBR', 'Massacres são subestimados.', '', 28153),
(144643, 'ptBR', 'Adoro quando um plano infalível dá certo.', '', 28153),
(144642, 'ptBR', 'Até.', '', 28153),
(144641, 'ptBR', 'Qual é o plano?', '', 28153),
(144640, 'ptBR', 'Qual é a ordem?', '', 28153),
(144639, 'ptBR', 'Aê!', '', 28153),
(144638, 'ptBR', 'Isso é pra lacrar? Todo mundo só quer saber de lacrar, agora.', '', 28153),
(144637, 'ptBR', 'Quer saber onde eu descolei essas caveiras?', '', 28153),
(144636, 'ptBR', 'Infelizmente já existe uma tribo \"Lançabesta\".', '', 28153),
(144635, 'ptBR', 'Eu perdi minha cabeça! Ela é tipo... hm... desse tamanho. Se achar, me dá um toque.', '', 28153),
(144634, 'ptBR', 'Aparece, se precisar da minha ajuda.', '', 28153),
(144633, 'ptBR', 'Vê se não se mete com vodu.', '', 28153),
(144632, 'ptBR', 'Te cuida.', '', 28153),
(144631, 'ptBR', 'Qual é a boa, chefia?', '', 28153),
(144630, 'ptBR', 'Pelos Lançanegra!', '', 28153),
(144629, 'ptBR', 'Tô ouvindo.', '', 28153),
(144628, 'ptBR', 'Muito bem... você pediu. Recomendando apagamento total e reinício do universo.', '', 28153),
(144627, 'ptBR', 'Cutucões sucessivos não fazem o sistema operar mais rápido.', '', 28153),
(144626, 'ptBR', 'Novo alvo potencial para contenção.', '', 28153),
(144625, 'ptBR', 'Erro. Repetição pode ocasionar erro fatal.', '', 28153),
(144624, 'ptBR', 'Interação concluída.', '', 28153),
(144623, 'ptBR', 'Retomando protocolo de contenção.', '', 28153),
(144622, 'ptBR', 'Repetindo varreduras.', '', 28153),
(144621, 'ptBR', '', 'Olá, $p! Novas terras e novos aliados nos aguardam por toda Azeroth.$B$BOculeth já preparou os portais no andar inferior para quando você estiver $gpronto:pronta;.', 28153),
(144620, 'ptBR', 'Corrupção detectada. Deve ser contida a qualquer custo.', '', 28153),
(144619, 'ptBR', 'Protocolo de alta prioridade: contenham a corrupção.', '', 28153),
(144618, 'ptBR', 'Unidade Hezrel está online. Objetivo: contenção da corrupção.', '', 28153),
(144617, 'ptBR', '', 'Você tá me cansando... e velho cansa rápido!', 28153),
(144616, 'ptBR', '', 'Você já ouviu a história da tortollana que perdeu a cabeça e atacou a peste que veio azucrinar ela?', 28153),
(144614, 'ptBR', '', 'Tá batendo uma vontade de brigar.', 28153),
(144613, 'ptBR', '', 'Tudo pronto?', 28153),
(144612, 'ptBR', '', 'Vai incomodar outro na próxima.', 28153),
(144611, 'ptBR', '', 'Você demorou demais.', 28153),
(144610, 'ptBR', '', 'Urgh. O que foi?', 28153),
(144609, 'ptBR', '', 'Essa conversa é de extrema importância?', 28153),
(144608, 'ptBR', '', 'O que foi agora?', 28153),
(144605, 'ptBR', 'Sai daqui... antes que eu use a tua alma como pagamento!', '', 28153),
(144604, 'ptBR', 'Vô bater pa tu... Nunca faz acordo com um loa da morte!', '', 28153),
(144603, 'ptBR', 'Não perca sua alma.', '', 28153),
(144602, 'ptBR', 'Cuidado onde pisa agora.', '', 28153),
(144601, 'ptBR', 'Te cuida.', '', 28153),
(144600, 'ptBR', 'Saudações.', '', 28153),
(144599, 'ptBR', 'O que tu quer com Hanzabu?', '', 28153),
(144598, 'ptBR', 'Eu tenho muito mais o que fazer.', '', 28153),
(144597, 'ptBR', 'Eu mandei você parar!', '', 28153),
(144596, 'ptBR', 'Seu coaxo não é esse escracho todo, não.', '', 28153),
(144595, 'ptBR', 'Eu estou muito furioso agora!', '', 28153),
(144594, 'ptBR', 'Você não veio aqui me beijar, veio?', '', 28153),
(144593, 'ptBR', 'Até a próxima.', '', 28153),
(144592, 'ptBR', 'Olhe antes de saltar.', '', 28153),
(144591, 'ptBR', 'Que nunca te faltem moscas.', '', 28153),
(144590, 'ptBR', 'Fale.', '', 28153),
(144589, 'ptBR', 'Falou com Krag\'wa?', '', 28153),
(144588, 'ptBR', 'Sim, pequeno ser.', '', 28153),
(144587, 'ptBR', 'Te vejo em breve... MUITO breve.', '', 28153),
(144586, 'ptBR', 'Vaza!', '', 28153),
(144585, 'ptBR', 'Mais cedo ou mais tarde... todo mundo vem pra mim.', '', 28153),
(144584, 'ptBR', 'Que cara é essa? Tá pensando na MORTE da bezerra? Hahaha!', '', 28153),
(144583, 'ptBR', 'Eu vejo gente morta. É o meu lance.', '', 28153),
(144582, 'ptBR', 'Hm... alguém gosta de perigo.', '', 28153),
(144581, 'ptBR', 'Calma. Não esquece com quem você tá lidando.', '', 28153),
(144580, 'ptBR', 'Fala aí! Veio fazer um trato?', '', 28153),
(144579, 'ptBR', 'O que tu quer da morte?', '', 28153),
(144578, 'ptBR', 'E aí... veio fazer uma visitinha pra esse Bwonsamdi velho?', '', 28153),
(144577, 'ptBR', 'Estou pronto.', 'Estou pronta.', 28153),
(144576, 'ptBR', 'Nós temos que por fim a essa loucura antes que seja tarde.', '', 28153),
(144575, 'ptBR', '', 'Hei de vigiar para que não se perca outra vez.', 28153),
(144574, 'ptBR', 'Bem debaixo do nosso nariz! Que afronta!', '', 28153),
(144573, 'ptBR', 'Não, não pode ser. Pelos meus cálculos, teria que ser...', '', 28153),
(144572, 'ptBR', 'Esses resultados são tão confusos. Se esses... como você os chama? Barbudinhos? Se eles ao menos deixassem eu me concentrar!', '', 28153),
(144571, 'ptBR', 'Tenho que tentar novamente. Você se saiu bem, apesar de eu ter imaginado inimigos um pouco mais altos.', '', 28153),
(144570, 'ptBR', 'Se alguém interromper, posso contar com você?', '', 28153),
(144569, 'ptBR', 'É por aqui! Quando eu usar a vidência, toda a minha atenção ficará concentrada.', '', 28153),
(144568, 'ptBR', 'Argus, o Descriador, está lançando Módulos de Recriação!', 'Argus, o Descriador, está lançando Módulos de Recriação!', 28153),
(144567, 'ptBR', '', 'Olha, amig$Go:a;, Nuu veio ajudar! Eu sabia que você ia nos achar, Nuu!', 28153),
(144566, 'ptBR', 'Há extensos danos estruturais e energia instável nos aquedutos. O portão continuará fechado, por ora.', 'Há extensos danos estruturais e energia instável nos aquedutos. O portão continuará fechado, por ora.', 28153),
(144565, 'ptBR', 'Eu vou ficar de olho nele. Acho que brincando no jardim ele sossega o facho.', 'Eu vou ficar de olho nele. Acho que brincando no jardim ele sossega o facho.', 28153),
(144564, 'ptBR', '', 'Muito bem! Foi impressionante!', 28153),
(144563, 'ptBR', '', 'Direcionar a energia de chi para o alvo é difícil no começo.\n\nVocê aí na frente! Tente acertar aquele boneco ali.', 28153),
(144562, 'ptBR', 'Psst, $pr... Tá querendo comprar?', '', 28153),
(144561, 'ptBR', 'O que você tem aí, $p? É uma flor-de-século?', '', 28153),
(144560, 'ptBR', '', 'A gente tem que começar a se preparar pra próxima safra, Jaden.', 28153),
(144559, 'ptBR', 'Hmm... tá faltando algum lance nesse chili... tá precisando de ardência.', '', 28153),
(144558, 'ptBR', '', 'Zancha! Tu esqueceu de novo de encher o estoque de pedra de regresso?', 28153),
(144557, 'ptBR', 'Tchaaaaaau!', '', 28153),
(144556, 'ptBR', 'Você nada bem à beça.', '', 28153),
(144555, 'ptBR', 'Água é tão legal. Eu gosto de água. Você gosta de água? O que você gosta mais na água? Eu gosto porque ela é molhada. Água é bem legal, né?', '', 28153),
(144554, 'ptBR', 'Minha mãe me disse que a gente é ambífio... anfívio... é... hmmm... é ANFÍBIO! Ufa, saiu!', '', 28153),
(144553, 'ptBR', 'Tortollar, tortollar, para o lado eu vou rolar. Tortollar, tortollar, meus pezinhos vão pro ar.', '', 28153),
(144552, 'ptBR', 'Quando crescer, eu vou ler TUDO!', '', 28153),
(144551, 'ptBR', 'Como você carrega suas coisas sem casco?', '', 28153),
(144550, 'ptBR', 'Eu gosto de rolar!', '', 28153),
(144549, 'ptBR', 'Logo, logo eu vou ter a sua idade!', '', 28153),
(144548, 'ptBR', 'Tudo bem, pode ir. Eu não tinha mais nada para dizer mesmo.', '', 28153),
(144547, 'ptBR', 'Nem tudo no mar é tão bonito ou tão gentil quanto eu.', '', 28153),
(144546, 'ptBR', 'Se achar alguma coisa exótica, traga para mim.', '', 28153),
(144545, 'ptBR', 'Volte com histórias melhores.', '', 28153),
(144544, 'ptBR', 'Eu já vi coisas que te fariam borrar o casco.', '', 28153),
(144543, 'ptBR', 'Chegue mais perto e pare de balbuciar.', '', 28153),
(144542, 'ptBR', 'Saudações, senhor e/ou senhora.', '', 28153),
(144541, 'ptBR', 'Tem alguma antiguidade para trocar? Tem que ter pelo menos dois séculos.', '', 28153),
(144540, 'ptBR', '', 'Você tá me dando as costas?', 28153),
(144539, 'ptBR', '', 'Tchau.', 28153),
(144538, 'ptBR', '', 'Teve uma vez que eu roubei uma alpaca e levei pro templo. Mas aí, a minha ma\'ma me mandou soltar ela.', 28153),
(144537, 'ptBR', '', 'Teve uma vez que eu matei um aventureiro e peguei a caveira dele. Era maior que você...', 28153),
(144536, 'ptBR', '', 'Teve uma vez que eu peguei um brutossauro pelo rabo. Deixei ele me carregar durante 32 respirações e meia.', 28153),
(144535, 'ptBR', 'Um albatroz violento mergulha na direção do ovo.', '', 28153),
(144534, 'ptBR', '', 'Teve uma vez... Teve uma vez que eu peguei um saurídeo. Era muito, mas muito grande. Enorme mesmo. Disseram que era um ravassauro, mas eu acho que era mentira.', 28153),
(144533, 'ptBR', '', 'Teve uma vez que eu peguei o maior peixe de todos os tempos, mas era só um guarda bagatado.', 28153),
(144532, 'ptBR', '', 'Taz\'okun!', 28153),
(144531, 'ptBR', '', 'Taz\'dingo!', 28153),
(144530, 'ptBR', '', 'Meu loa é mais forte que o teu loa!', 28153),
(144529, 'ptBR', '', 'Hoje é dia de loa! Coisa boa!', 28153),
(144528, 'ptBR', 'Tchau, amizade.', '', 28153),
(144527, 'ptBR', 'Aonde você vai?', '', 28153),
(144526, 'ptBR', 'Os loa é mó legal. Quase tudo tem tamanho pra te comer!', '', 28153),
(144525, 'ptBR', 'Vou ser um brutossauro druida quando crescer. Raaaur!', '', 28153),
(144524, 'ptBR', 'Eu tenho dez dedos do pé... mas só quatro são meus mesmo.', '', 28153),
(144523, 'ptBR', 'Alguém roubou minha caixa de cabeças encolhidas. Foi você?', '', 28153),
(144522, 'ptBR', 'Ah, oi.', '', 28153),
(144521, 'ptBR', 'Taz\'okun!', '', 28153),
(144520, 'ptBR', 'Taz\'dingo!', '', 28153),
(144519, 'ptBR', 'Raaaur!', '', 28153),
(144518, 'ptBR', 'Os loas são fortes aqui.', 'Os loas são fortes aqui.', 28153),
(144517, 'ptBR', 'Que os espíritos estejam contigo.', 'Que os espíritos estejam contigo.', 28153),
(144516, 'ptBR', 'Os loas estão sempre de prontidão.', 'Os loas estão sempre de prontidão.', 28153),
(144515, 'ptBR', 'Rá! Se liga, toma dois desses e me encontra de manhã.', 'Rá! Se liga, toma dois desses e me encontra de manhã.', 28153),
(144513, 'ptBR', 'Tu tá abusando da sorte fazendo isso.', 'Tu tá abusando da sorte fazendo isso.', 28153),
(144512, 'ptBR', 'Aqui só tem urucubaca da melhor qualidade.', 'Aqui só tem urucubaca da melhor qualidade.', 28153),
(144511, 'ptBR', 'Os espíritos sussurram o seu nome.', 'Os espíritos sussurram o seu nome.', 28153),
(144510, 'ptBR', 'Com que loa você faz negócio?', 'Com que loa você faz negócio?', 28153),
(144509, 'ptBR', '', 'Avante! Pelo futuro de Zandalar!', 28153),
(144508, 'ptBR', 'Bom, essa apresentação foi meio esquisita... Melhor eu voltar logo, senão Kugro não vai ficar contente.', '', 28153),
(144498, 'ptBR', 'Zandalar vai resistir.', 'Zandalar vai resistir.', 28153),
(144497, 'ptBR', 'Jamais se acovarde diante dos fracos.', '', 28153),
(144496, 'ptBR', 'Rasgue feridas em seus inimigos.', '', 28153),
(144495, 'ptBR', 'Que você saboreie a carne dos seus inimigos.', '', 28153),
(144494, 'ptBR', 'O que foi, criança da Horda?', '', 28153),
(144493, 'ptBR', 'Você está nas minhas terras.', '', 28153),
(144492, 'ptBR', 'Predador... ou presa?', '', 28153),
(144491, 'ptBR', 'Você veio barganhar?', '', 28153),
(144490, 'ptBR', 'Fale de mim para o mundo.', '', 28153),
(144489, 'ptBR', 'Que seus inimigos nunca sintam a sua presença.', '', 28153),
(144488, 'ptBR', 'Leve força para o seu bando.', '', 28153),
(144486, 'ptBR', 'Se quiser fugir, lembre-se, eu sei abrir portas.', '', 28153),
(144484, 'ptBR', 'É melhor parar se não quiser ser a minha próxima presa.', '', 28153),
(144481, 'ptBR', 'Eu sou o mestre das formas, o líder do bando, o senhor da caçada.', '', 28153),
(144480, 'ptBR', 'O que você quer com o senhor da caçada?', '', 28153),
(144479, 'ptBR', 'Você veio pechinchar?', '', 28153),
(144478, 'ptBR', '', 'Que os ventos soprem a seu favor... e levem você para bem longe de mim.', 28153),
(144477, 'ptBR', '', 'Não se esqueça, os céus são meus.', 28153),
(144476, 'ptBR', '', 'A morte vai vir de cima.', 28153),
(144475, 'ptBR', '', 'O vento é a minha vontade.', 28153),
(144474, 'ptBR', '', 'Eu vou levar você para o alto... e soltar numa pedra!', 28153),
(144473, 'ptBR', '', 'Você está evocando a minha ira?', 28153),
(144472, 'ptBR', '', 'Você está testando a minha paciência, jovem.', 28153),
(144471, 'ptBR', '', 'Por que eu tenho que respirar o mesmo ar que você?', 28153),
(144470, 'ptBR', '', 'O que foi, criança?', 28153),
(144469, 'ptBR', '', 'Você veio pechinchar?', 28153),
(144468, 'ptBR', '', 'Psst, $pr... Cansou dessa cara de saurídeo? Meu mojo vai te deixar com cara de demossauro!', 28153),
(144462, 'ptBR', '', 'Escolha o seu loa com sabedoria.', 28153),
(144461, 'ptBR', '', 'Que você sempre encontre o rastro dos seus inimigos.', 28153),
(144460, 'ptBR', '', 'Pela matilha.', 28153),
(144459, 'ptBR', '', 'Nunca domestique sua fera interior.', 28153),
(144458, 'ptBR', '', 'Dá uma volta no mundo animal.', 28153),
(144457, 'ptBR', '', 'Fica por aí. De repente a gente repete mais tarde.', 28153),
(144456, 'ptBR', '', 'Tô pregaaada.', 28153),
(144455, 'ptBR', '', 'Então tá, continua.', 28153),
(144454, 'ptBR', '', 'Se tu não parar de fazer isso, meu marido vai ficar enciumado.', 28153),
(144453, 'ptBR', '', 'Já passeou no mundo animal?', 28153),
(144452, 'ptBR', 'Está na hora de eu mesmo cuidar disso. Eu não vou deixar você arruinar essa operação!', '', 28153),
(144451, 'ptBR', 'Agradeço, $n. Parece que Kugro andou ocupado. Agora... o que fazer com todos esses pergaminhos?', '', 28153),
(144450, 'ptBR', '', 'Os loas são fortes aqui.', 28153),
(144449, 'ptBR', '', 'Foi essa forma que você escolheu pra andar por aí?', 28153),
(144448, 'ptBR', 'Você não é meu contato! Venham aqui, pessoal! Tem carne fresca no pedaço!', '', 28153),
(144447, 'ptBR', '', 'Eu sirvo Gonk, mestre das formas.', 28153),
(144446, 'ptBR', '<Dê os pergaminhos a Itokka.>', '<Dê os pergaminhos a Itokka.>', 28153),
(144445, 'ptBR', '', 'Se estivesse aqui, Nuu saberia o que fazer.', 28153),
(144444, 'ptBR', '', 'Ah, olá! Quem és tu? Eu sou Uuna. Queres ser $Gmeu amigo:minha amiga;? Talvez juntos consigamos sair deste lugar.', 28153),
(144443, 'ptBR', 'Ei! Eu tenho uma parada ideal pra tu. O repelente de saurídeo do Zul! Aquelas pragas não vão chegar nem perto!', '', 28153),
(144442, 'ptBR', '', 'É muito brilhante! Quanto brilho! Ahhh!', 28153),
(144441, 'ptBR', 'Muitas bênçãos, viajante. \n\nAbaixe sua arma e descanse um pouco.\n\nA guerra pode esperar.', '', 28153),
(144440, 'ptBR', 'Saudações, Pakura\'ai!', '', 28153),
(144439, 'ptBR', 'Escolha o seu loa com sabedoria.', '', 28153),
(144438, 'ptBR', 'Já dizia a minha loa... Sai daqui.', '', 28153),
(144437, 'ptBR', 'Que Pa\'kul espione seus inimigos antes que eles espionem você.', '', 28153),
(144436, 'ptBR', 'Que os ventos da guerra estejam sempre a seu favor.', '', 28153),
(144435, 'ptBR', 'Agora sim! Acertou em cheio!', '', 28153),
(144434, 'ptBR', 'Ah, isso, isso, bem aí, bem aí... um pouquinho mais pra direita...', '', 28153),
(144433, 'ptBR', 'Se a minha mulher me desse tanta atenção quanto você...', '', 28153),
(144432, 'ptBR', 'Já dizia a minha loa... Não toca nisso!', '', 28153),
(144431, 'ptBR', 'Já dizia a minha loa... Fica ligado! Hahahahaha!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144430, 'ptBR', 'Quer voar com os dinossauros?', '', 28153),
(144429, 'ptBR', 'Os céus são meus olhos.', '', 28153),
(144428, 'ptBR', 'Eu sirvo a Pa\'kul, uma das loas mais antigas.', '', 28153),
(144427, 'ptBR', '', 'Eu luto para proteger os fracos e oprimidos.', 28153),
(144425, 'ptBR', 'Todo mundo tem um papel a desempenhar, até você.', '', 28153),
(144424, 'ptBR', 'Vi muitos dos grandes acontecimentos do nosso tempo e, em todos, tu tava lá. Estranho...', '', 28153),
(144423, 'ptBR', 'Uns dias horríveis vêm aí.', '', 28153),
(144422, 'ptBR', 'A coisa tá feia, cara. Feiaça.', '', 28153),
(144421, 'ptBR', 'O império troll vai se erguer novamente. Eu prevejo isso.', '', 28153),
(144420, 'ptBR', 'Os trolls foram os primeiros a governar este mundo, e nós vamos ser os últimos.', '', 28153),
(144419, 'ptBR', 'O destino não tá contigo, camarada.', '', 28153),
(144418, 'ptBR', 'Eu já previ o que você vai dizer, então desembucha de uma vez.', '', 28153),
(144417, 'ptBR', 'Eu vi o fim deste mundo. Tu não vai gostar nem um pouco.', '', 28153),
(144416, 'ptBR', '', 'Zandalar vai resistir.', 28153),
(144415, 'ptBR', '', 'Vingança pelos mortos.', 28153),
(144414, 'ptBR', '', 'Que o crânio do inimigo seja o adorno do seu traje.', 28153),
(144413, 'ptBR', '', 'Os tempos mudam, e os Zandalari também.', 28153),
(144412, 'ptBR', '', 'Há muito o que fazer. Fale logo.', 28153),
(144411, 'ptBR', 'Que seus inimigos tremam na sua presença.', '', 28153),
(144410, 'ptBR', 'Zandalar para sempre.', '', 28153),
(144409, 'ptBR', 'Rezan lhe dará forças.', '', 28153),
(144408, 'ptBR', 'É bom ser o Rei.', '', 28153),
(144407, 'ptBR', 'Você está diante do Rei Rastakhan.', '', 28153),
(144406, 'ptBR', 'Boas-vindas a Zuldazar.', '', 28153),
(144405, 'ptBR', 'Predador... ou presa?', '', 28153),
(144404, 'ptBR', '', 'Eu queria enxergar um pouco melhor. Está sempre tão escuro aqui!', 28153),
(144403, 'ptBR', '', 'Mas tenho-te como $Gamigo:amiga;. Sei que vai ficar tudo bem.', 28153),
(144402, 'ptBR', '', 'Pelo menos estamos junt$Gos:as; agora. Só não sabemos... onde estamos.', 28153),
(144401, 'ptBR', '', 'Socorro! SOCORRO!', 28153),
(144400, 'ptBR', '', 'Quem é você? Pode me ajudar?', 28153),
(144399, 'ptBR', '', 'Que escuridão! Vejo nada!', 28153),
(144397, 'ptBR', '', 'A questão com Elisande está encerrada, mas ainda há muito a ser feito pela cidade.', 28153),
(144396, 'ptBR', '', 'Os Filhos da Noite estão de fato livres. Não precisamos mais da Nascente da Noite nem do poder dela.$B$BPodemos forjar nosso próprio destino.', 28153),
(144395, 'ptBR', 'Eu trouxe provinhas para desmentir os boatos de que o nosso vinho é fuleiro demais... quer dizer, frutado demais!', '', 28153),
(144394, 'ptBR', 'Nossos vinicultores desistiram de cuidar dos vinhedos e partiram para outras linhas de botânica.', '', 28153),
(144393, 'ptBR', 'Os trolls sangrentos tavam brigando com os guardas quando a gente chegou. Nem tavam esperando um ataque por trás.', '', 28153),
(144392, 'ptBR', 'Opa, esse é grandão. Vou precisar da sua ajuda para derrubá-lo!', '', 28153),
(144391, 'ptBR', 'Se você vir um grupo deles, jogue uma dessas bombas espinhosas para eles provarem do próprio remédio!', '', 28153),
(144390, 'ptBR', 'Aposto que isso doeu, né? Saia das minhas terras!', '', 28153),
(144389, 'ptBR', 'Hah, acertei bem no meio da testa!', '', 28153),
(144388, 'ptBR', 'Pode voltar e dizer a Roz que estou bem, mas nunca vou abandonar minha fazenda. Nunca vou deixá-los.', '', 28153),
(144387, 'ptBR', 'Sim, está bom. Eles sempre gostaram desse local...', '', 28153),
(144386, 'ptBR', 'Você pode usar o portal de Orgrimmar para encontrar nossos aliados da Horda na capital deles, em Kalimdor.', '', 28153),
(144385, 'ptBR', '', 'Rokhan! Tudo bem? Parece que uma batalha passou por aqui.', 28153),
(144384, 'ptBR', 'Eu soube que tem um piso inteiro em Dalaran dedicado a magias de transporte. $B$BQuantas possibilidades!', '', 28153),
(144383, 'ptBR', 'Esses portais são uma chatice de se manter e, pior ainda, eles desviam a atenção de pesquisas valiosíssimas!$B$BEu tenho certeza de que com a telemancia vamos chegar a resultados muito mais estáveis.', '', 28153),
(144382, 'ptBR', 'Quem disse que goblin não tem cultura?', '', 28153),
(144381, 'ptBR', 'Eles cataram até os nossos tambores!', '', 28153),
(144380, 'ptBR', '... e acha um tambor livre!', '', 28153),
(144379, 'ptBR', 'Boas-vindas ao Batuqueiro Chapado, $pr! Toma um trago...', '', 28153),
(144378, 'ptBR', 'Argh! Achei que meu plano fosse à prova de vacilo, cara!', '', 28153),
(144377, 'ptBR', 'Mané! Tu vai pagar por baixar na minha ponte!', '', 28153),
(144376, 'ptBR', 'Aí, cara! Essa ponte é minha, tá ligado? Passa um troco pro troll, cara, senão vai pagar com sangue!', '', 28153),
(144375, 'ptBR', 'Tudo pronto para começar o teste.', 'Tudo pronto para começar o teste.', 28153),
(144374, 'ptBR', '', 'E se a gente amarrasse uns explosivos neles? Seria hilário... explodir uns dinossauros!', 28153),
(144373, 'ptBR', '', 'Seu entusiamo é admirável, Shuga. Mas com certeza os Zandalari preferem armas encantadas com magias poderosas, e não com essas firulas.', 28153),
(144372, 'ptBR', 'O que... o que foi que nos tornamos?', '', 28153),
(144371, 'ptBR', '', 'Não! Solte-me! Socorro, amig$Go:a;! SOCORRO!', 28153),
(144370, 'ptBR', '', 'Escureceu de novo! Aonde tu foste? Não me deixa aqui!', 28153),
(144369, 'ptBR', '', 'Eu tinha uma varinha igual a essa! Perdi, no entanto, há muito tempo.', 28153),
(144368, 'ptBR', '', 'Uma coroa! Deveras bonita!', 28153),
(144367, 'ptBR', '', 'Nuu-nuu! Pensei que não fosse te ver nunca mais! Como vieste parar aqui?', 28153),
(144366, 'ptBR', '', 'Ah! Ficou mais claro! Dá pra ver... um pouquinho.', 28153),
(144365, 'ptBR', '', 'O que é isso? Uma luz na escuridão! É tão brilhante...', 28153),
(144364, 'ptBR', 'Ela... prometeu...', '', 28153),
(144363, 'ptBR', 'Disseram que essa seria a forma de ficarmos juntos!', '', 28153),
(144362, 'ptBR', '', 'Com a proteção dos loas e coragem no coração, a vitória será nossa!', 28153),
(144361, 'ptBR', '', 'Nós vamos acabar com os trolls sangrentos. Não vamos deixar que as abominações que eles trouxeram à vida sejam usadas contra nós jamais!', 28153),
(144360, 'ptBR', '', 'O inimigo quer destruir tudo o que a gente mais ama. Não podemos deixar os planos deles vingarem! O futuro de Zandalar depende da nossa garra hoje!', 28153),
(144359, 'ptBR', '', 'Soldados... parceiros. Nós enfrentamos muitas dificuldades, mas o fim de nossa luta está à vista.', 28153),
(144358, 'ptBR', 'Mostre-me para onde posso ir de balsa.', 'Mostre-me para onde posso ir de balsa.', 28153),
(144357, 'ptBR', 'Procurando uma balsa?', 'Procurando uma balsa?', 28153),
(144356, 'ptBR', '', 'Ainda bem que eu estava de botas!', 28153),
(144355, 'ptBR', 'Eu vou pegar uns tortollanos e partir pra Zul\'jan a pé. Boa sorte pra vocês.', '', 28153),
(144354, 'ptBR', 'Eu vivo e morro... pela Horda!', 'Eu vivo e morro... pela Horda!', 28153),
(144353, 'ptBR', 'Sangue e honra!', 'Sangue e honra!', 28153),
(144352, 'ptBR', 'Arathi pertence à Horda!', 'Arathi pertence à Horda!', 28153),
(144351, 'ptBR', 'Venham comigo!', 'Venham comigo!', 28153),
(144350, 'ptBR', 'Morte à Aliança!', 'Morte à Aliança!', 28153),
(144349, 'ptBR', 'Pela Horda!', 'Pela Horda!', 28153),
(144348, 'ptBR', 'Por aqui! À luta!', 'Por aqui! À luta!', 28153),
(144347, 'ptBR', 'Vamos lá, brutos! Temos que vencer essa guerra!', 'Vamos lá, brutos! Temos que vencer essa guerra!', 28153),
(144346, 'ptBR', 'Meu nome é Gral!', '', 28153),
(144345, 'ptBR', 'Ao sul, tu vai encontrar o que sobrou do meu templo. Eu vou te trombar lá e a gente vai mostrar pra essas nagas a fúria do loa tubarão!', '', 28153),
(144344, 'ptBR', 'Ah... estava uma delícia.', '', 28153),
(144343, 'ptBR', 'Não tem profundeza escura demais para tu!', '', 28153),
(144342, 'ptBR', 'Nagas não são bem-vindas em Atal\'Gral!', '', 28153),
(144341, 'ptBR', 'O aroma intenso e gostoso de sangue naga cheio de raiva... os pedacinhos adocicados... Eu vou ficar no aguardo.', '', 28153),
(144340, 'ptBR', '', 'Mãe, o Benjamin me contou tudo.\n\nVocê não me ouvia antes, mas quem sabe agora ouça? Eu só queria uma explicação.', 28153),
(144339, 'ptBR', '', 'Mãe, eu sei que você não está aqui. Mas se você estiver me ouvindo...', 28153),
(144338, 'ptBR', 'Eu não sou ninguém, mas mamãe era uma gerente incrível. Como pode ter decaído tanto...$b$bNós vamos superar, $n. Obrigado pela ajuda.', '', 28153),
(144337, 'ptBR', '', 'Aonde você vai?', 28153),
(144336, 'ptBR', '', 'Por favor, não me abandone.', 28153),
(144335, 'ptBR', 'O mestre que habita sob as ondas nos conduzirá à vitória!', 'O mestre que habita sob as ondas nos conduzirá à vitória!', 28153),
(144334, 'ptBR', 'Que bom que todo mundo voltou inteiro. A gente tem que agradecer a uma pessoa!', '', 28153),
(144333, 'ptBR', 'Vai ficar ou vai partir?', '', 28153),
(144332, 'ptBR', 'Com licença. Eu preciso ver minha irmã.', '', 28153),
(144331, 'ptBR', 'Quando o pai morreu, mamãe sumiu. Mas eu nunca imaginei...', '', 28153),
(144330, 'ptBR', 'Ela e meu pai trabalharam a vida inteira para construir esse negócio e sustentar a mim e minha irmã.', '', 28153),
(144329, 'ptBR', 'Aquela bruxa... era minha mãe.', '', 28153),
(144328, 'ptBR', 'Parece que você tem experiência com feras. O que precisa?', '', 28153),
(144327, 'ptBR', 'O que foi agora? Perdeu alguma coisa?', '', 28153),
(144326, 'ptBR', 'Excelente! Mais uma vez, do início.', '', 28153),
(144325, 'ptBR', 'Gastar muita energia de uma vez só é perigoso. Atenção ao andamento, turma.', '', 28153),
(144324, 'ptBR', 'O chi concentrado é muito poderoso. O Mestre Tau Li guiará você quando estiver tudo pronto.', '', 28153),
(144323, 'ptBR', 'Ao realizar uma cura, você deve reunir a sua força interior para passar a alguém.', '', 28153),
(144322, 'ptBR', 'Ainda bem que não tive que entregar TUDO.', 'Ainda bem que não tive que entregar TUDO.', 28153),
(144321, 'ptBR', 'Nossos irmãos e irmãs corrompidos ainda vagam pela mata.', 'Nossos irmãos e irmãs corrompidos ainda vagam pela mata.', 28153),
(144320, 'ptBR', '', 'Minha vida... pela Horda.', 28153),
(144319, 'ptBR', '', 'Te vejo por aí em breve.', 28153),
(144318, 'ptBR', '', 'Sangue e trovão!', 28153),
(144317, 'ptBR', '', 'Eu vou fatiar você.', 28153),
(144316, 'ptBR', '', 'Minhas espadas querem provar da sua carne.', 28153),
(144315, 'ptBR', '', 'Sua força não é páreo para o poder de um orc!', 28153),
(144314, 'ptBR', '', 'Seus ossos não são páreo para a minha lâmina!', 28153),
(144313, 'ptBR', '', 'Mantenham a formação! Ninguém passa!', 28153),
(144312, 'ptBR', 'Eu agradeço, camarada.', '', 28153),
(144311, 'ptBR', 'Se eu não me lembrar de você numa próxima ocasião, mil perdões.', '', 28153),
(144310, 'ptBR', 'Agradeço por você ter cuidado de Torok. Ele se recusou a ver os perigos por trás do poder que almeja.', 'Agradeço por você ter cuidado de Torok. Ele se recusou a ver os perigos por trás do poder que almeja.', 28153),
(144309, 'ptBR', '<O tauren adormecido ronca estrondosamente e rola para o lado.>', '<O tauren adormecido ronca estrondosamente e rola para o lado.>', 28153),
(144308, 'ptBR', 'ZZZzzz...', 'ZZZzzz...', 28153),
(144307, 'ptBR', 'Conta comigo, princesa. Até o fim.', '', 28153),
(144306, 'ptBR', '', 'É o único jeito de salvar meu povo, Rokhan. Eu tô disposta a abrir mão de tudo pela segurança deles. Você tá comigo?', 28153),
(144305, 'ptBR', 'Ainda não acredito que meus irmãos e irmãs sucumbiram à força vil.', 'Ainda não acredito que meus irmãos e irmãs sucumbiram à força vil.', 28153),
(144304, 'ptBR', '', 'Filhas, é assim que a gente recebe os convidados!', 28153),
(144303, 'ptBR', '', 'O sangue... vai me vingar...', 28153),
(144302, 'ptBR', '', 'Pelas mães-da-guerra!', 28153),
(144301, 'ptBR', 'Agora, concentre seu chi. Empurre a energia para longe.', '', 28153),
(144300, 'ptBR', '', 'Tua essência vai ser mais útil aqui fora!', 28153),
(144299, 'ptBR', '', 'Vai ser divertido te drenar.', 28153),
(144298, 'ptBR', '', 'Teu sangue vai ser nosso alimento!', 28153),
(144297, 'ptBR', '', 'Vou tirar teu sangue. O resto pode apodrecer!', 28153),
(144296, 'ptBR', '', 'Vou molhar minha arma com teu sangue.', 28153),
(144295, 'ptBR', 'Se precisar de uma carona, sabe onde me encontrar!', '', 28153),
(144294, 'ptBR', '', 'Sangue para os cantossangues!', 28153),
(144293, 'ptBR', '', 'Vou fazer um chicote com tua pele!', 28153),
(144292, 'ptBR', '', 'Os céus... chamam.', 28153),
(144291, 'ptBR', '', 'Que ótimo dia pra batalhar.', 28153),
(144290, 'ptBR', '', 'Os crorgs vão comer bem hoje!', 28153),
(144289, 'ptBR', 'Continue firme! Vou ver como Satao está.', '', 28153),
(144288, 'ptBR', 'ENTRADA – Experimento Visgo\n\nA operação para dotar os visgos de vontade própria foi um êxito. Em vez de dissolver matéria orgânica, como carne ou verduras, eles podem subsistir inteiramente de mel. As sobras podem ser fermentadas em barris, produzindo um hidromel de sabor e potência excepcionais.\n\nSe não forem devidamente controlados, os visgos passam a caçar e consumir colmeias inteiras. Eles tendem a ficar mais agressivos e acabam saindo de controle.\n\nNaturalmente, as abelhas reagem ficando mais defensivas, o que dificulta o manejo. Uma hora eu terei que encontrar uma solução para o problema, uma vez que as abelhas não são fáceis de se substituir.', '', 28153),
(144287, 'ptBR', '', 'Pohkiza...', 28153),
(144286, 'ptBR', '', 'O Deus do Sangue... quer... todos...', 28153),
(144285, 'ptBR', '', 'Ahahaha!', 28153),
(144284, 'ptBR', '', 'Zuldazar... vai cair...', 28153),
(144283, 'ptBR', '', 'Gachaga!', 28153),
(144282, 'ptBR', '', 'Minhas irmãs... vão me vingar...', 28153),
(144281, 'ptBR', '', 'Meu sangue... pra... G\'huun!', 28153),
(144280, 'ptBR', '', 'G\'huun!', 28153),
(144279, 'ptBR', '<Tsunga grunhe de maneira afetuosa para você.>', '', 28153),
(144278, 'ptBR', 'Eu vim das brumas pra alertar o povo de Zandalar. A azerita agraciou os gorilas com uma grande inteligência. Com a inteligência, vem a guerra.', '', 28153),
(144277, 'ptBR', 'Pohkiza...', '', 28153),
(144276, 'ptBR', 'O Deus do Sangue... quer... todos...', '', 28153),
(144275, 'ptBR', 'Você... já perdeu... Hahahaha', '', 28153),
(144274, 'ptBR', 'Zuldazar... vai... cair...', '', 28153),
(144273, 'ptBR', 'Gachaga!', '', 28153),
(144272, 'ptBR', 'Minha vida pelas ma\'mas!', '', 28153),
(144271, 'ptBR', 'Meu sangue... pra... G\'huun!', '', 28153),
(144270, 'ptBR', 'G\'huun!', '', 28153),
(144269, 'ptBR', 'Muito, muito bom! Mais uma vez!', '', 28153),
(144268, 'ptBR', 'Para de se debater.', '', 28153),
(144266, 'ptBR', '', 'Eu vou ajudar a reforçar as defesas da vila. Nos encontramos lá!', 28153),
(144265, 'ptBR', '', 'Conseguimos dobrá-los. Venha! Vamos falar com o Prefeito Reimão.', 28153),
(144264, 'ptBR', '', 'Alleria suspira com o cenho franzido.', 28153),
(144263, 'ptBR', '<Fique um pouco e escute.>', '<Fique um pouco e escute.>', 28153),
(144262, 'ptBR', '', '<Os olhos de Alleria se movem do semblante frio da estátua para a placa em que o epitáfio está gravado.>', 28153),
(144261, 'ptBR', 'Não cedam! Mantenham a formação!', 'Não cedam! Mantenham a formação!', 28153),
(144260, 'ptBR', 'Você ouve um breve lamento junto com o último suspiro de Rohn\'kor.', '', 28153),
(144259, 'ptBR', '', 'Eu vou usar tua barriga pra fazer um chapéu novo!', 28153),
(144258, 'ptBR', '', 'Não! Meu bebê!', 28153),
(144257, 'ptBR', '', 'Para de machucar o preciosinho! Tu não vai sair dessa caverna!', 28153),
(144256, 'ptBR', '', 'Tão querendo empacotar a gente! Come eles, ajudante!', 28153),
(144255, 'ptBR', 'Bwonsamdi... tenha piedade!', 'Bwonsamdi... tenha piedade!', 28153),
(144254, 'ptBR', 'Zandalar... para... sempre...', 'Zandalar... pra sempre...', 28153),
(144253, 'ptBR', 'A gente vai te botar pra descansar, Urok! Foi mal que tenha que ser assim!', '', 28153),
(144252, 'ptBR', 'Mas o quê... O que essas coisas tão fazendo dentro do Urok?', '', 28153),
(144251, 'ptBR', 'A gente tá tão perto agora! Só me falta equipar minhas tralhas...', '', 28153),
(144250, 'ptBR', 'Assim, não...', 'Assim, não...', 28153),
(144249, 'ptBR', 'Bwonsamdi... está vindo... me buscar...', 'Bwonsamdi... tá vindo me buscar...', 28153),
(144248, 'ptBR', 'Mantenham a formação! Mais inimigos se aproximam!', 'Mantenham a formação! Mais inimigos se aproximam!', 28153),
(144247, 'ptBR', 'Minha... vida... por Zandalar...', 'Minha... vida... por Zandalar...', 28153),
(144245, 'ptBR', 'Di chuka Zandalar!', 'Di chuka Zandalar!', 28153),
(144243, 'ptBR', 'Mate todos eles!', 'Mate todos eles!', 28153),
(144242, 'ptBR', 'Zandalar, primeira e única!', 'Zandalar, primeira e única!', 28153),
(144240, 'ptBR', 'Seu sangue vai sujar nosso chão!', 'Seu sangue vai sujar nosso chão!', 28153),
(144239, 'ptBR', 'Vou te mandar pra vala!', 'Vou te mandar pra vala!', 28153),
(144238, 'ptBR', 'Tu vai morrer por aí!', 'Tu vai morrer aqui!', 28153),
(144237, 'ptBR', 'Zandalar para sempre!', 'Zandalar para sempre!', 28153),
(144236, 'ptBR', 'A princesa mandou encontrar os monstros, mas são todos monstros!', '', 28153),
(144235, 'ptBR', 'Cadê o sol? Não dá pra ver nada nessa porcaria de pântano.', '', 28153),
(144234, 'ptBR', 'Que sem sentido! Eu tô vendo um buracão. Não tem buraco nesse mapa!', '', 28153),
(144233, 'ptBR', 'Oh! Isso aqui é... é... nada. É decepcionante.', '', 28153),
(144232, 'ptBR', 'Taz\'okun! Pode ser um pedaço de azerita!', '', 28153),
(144231, 'ptBR', 'Será que isso é um tipo de agulha? Ugh. Por que é pegajoso?', '', 28153),
(144230, 'ptBR', 'Ah, que ótimo. Talvez Talanji goste disso.', '', 28153),
(144229, 'ptBR', 'Você está na mira de um besteiro embagatado! Mexa-se!', '', 28153),
(144228, 'ptBR', 'Não me pedem muito para fazer espadas aqui, mas eu gosto muito. Por outro lado, não gosto da razão de precisarmos de tantas!', '', 28153),
(144227, 'ptBR', 'Agora eu sei por que as pessoas têm medo deste pântano.', '', 28153),
(144226, 'ptBR', 'Que bizarro.', '', 28153),
(144225, 'ptBR', 'Acho que nunca mais vou conseguir tirar essa sujeira das mãos. Meus pobres pergaminhos.', '', 28153),
(144224, 'ptBR', 'Que pedra estranha... Ih! Se mexeu!', '', 28153),
(144223, 'ptBR', 'Fascinante.', '', 28153),
(144222, 'ptBR', 'Que Gonk guie seus passos.', 'Que Gonk guie seus passos.', 28153),
(144221, 'ptBR', 'Que Pa\'kul te proteja.', 'Que Pa\'kul te proteja.', 28153),
(144220, 'ptBR', 'Que Rezan te dê forças.', 'Que Rezan te dê forças.', 28153),
(144219, 'ptBR', 'Vai com cuidado.', 'Vai com cuidado.', 28153),
(144218, 'ptBR', 'É melhor tomar cuidado aqui na nossa cidade.', 'É melhor tomar cuidado aqui na nossa cidade.', 28153),
(144217, 'ptBR', 'Zandalar para sempre!', 'Zandalar pra sempre!', 28153),
(144216, 'ptBR', 'Tá precisando de proteção?', 'Tá precisando de proteção?', 28153),
(144215, 'ptBR', 'Tu não vai achar oferta melhor.', 'Tu não vai achar oferta melhor.', 28153),
(144214, 'ptBR', 'O que você veio fazer aqui?', 'O que você veio fazer aqui?', 28153),
(144213, 'ptBR', 'Saudações.', 'Saudações.', 28153),
(144209, 'ptBR', 'Eu jurei defender a família real.', 'Eu jurei defender a família real.', 28153),
(144208, 'ptBR', 'Nosso reino vai ser defendido.', 'Nosso reino vai ser defendido.', 28153),
(144201, 'ptBR', 'Vamos começar.', 'Vamos começar.', 28153),
(144200, 'ptBR', 'Estamos muito perto, $n.$b$bQuando você quiser, eu darei início ao uso da vidência.$b$bAh, eu esqueci de avisar. Nossos adversários levantaram um acampamento logo adiante, ao longo da praia. É melhor ficar de olho aberto para não sermos emboscados.$b$bConfio em você para me defender se formos pegos!', '', 28153),
(144199, 'ptBR', 'Continuem, pessoal! Estamos rechaçando esses desgraçados!', '', 28153),
(144198, 'ptBR', 'A noite se aproxima! Não esqueça de acender as fogueiras! Avise se precisar de mais combustível.', '', 28153),
(144197, 'ptBR', 'Não deixe esses monstros passarem! Matamos aquele beemote, mas perdemos muitas embarcações.', '', 28153),
(144196, 'ptBR', 'Se você tiver descansado, troque de lugar com alguém que está na barricada! Vamos sobreviver a esses inimigos!', '', 28153),
(144195, 'ptBR', 'Preciso de voluntários para ir até a casa de Azinhal! Talvez ele consiga arranjar uns sinalizadores.', '', 28153),
(144194, 'ptBR', 'Cuidem para que as crianças sejam alimentadas primeiro, depois os feridos!', '', 28153),
(144193, 'ptBR', 'Os curandeiros têm que se revezar para descansar! Inclusive você, Krystin!', '', 28153),
(144192, 'ptBR', 'Ajude a reforçar a barricada! Use tudo que não estiver pregado no chão. E, quando acabar, pode arrancar os pregos também!', '', 28153),
(144191, 'ptBR', 'O crorguinho emite uns sons estranhos, como guinchados, e arrasta os pés na ninfeia.', '', 28153),
(144190, 'ptBR', 'Aqueles marinheiros é que deviam estar de olho na Horda, não a gente.', 'Aqueles marinheiros é que deviam estar de olho na Horda, não a gente.', 28153),
(144189, 'ptBR', 'Quanto mais rápido encontrarmos esse negócio e zarparmos, melhor.', 'Quanto mais rápido encontrarmos esse negócio e zarparmos, melhor.', 28153),
(144188, 'ptBR', 'A Horda está próxima, cuidado!', 'A Horda está próxima, cuidado!', 28153),
(144187, 'ptBR', 'A Liga dos Exploradores podia ter mandado mais gente para a expedição.', 'A Liga dos Exploradores podia ter mandado mais gente para a expedição.', 28153),
(144186, 'ptBR', 'Se nós não estivéssemos de olho nos Ferro Negro, o que eles não estariam aprontando agora?', 'Se nós não estivéssemos de olho nos Ferro Negro, o que eles não estariam aprontando agora?', 28153),
(144185, 'ptBR', '', 'E as crianças também! Eu posso botar uma cabine de fotos e umas pelúcias de dinossauro. Aí você tira tua parte, Jangalar. Eu levo 70%, e você 30%, coisa do tipo. Eu fico com a margem maior, já que tive a ideia.', 28153),
(144184, 'ptBR', 'Se tu tiver disposição, tem mais gente precisando de ajuda ali na frente.', '', 28153),
(144183, 'ptBR', '', 'Chegou a hora de usar o injetor pra enfurecer Ben\'jin e depois ir atrás dele pra ajudar a destruir a espécie invasora.', 28153),
(144182, 'ptBR', 'Quando terminarmos de cavar, a Horda já vai estar quase em Altaforja!', 'Quando terminarmos de cavar, a Horda já vai estar quase em Altaforja!', 28153),
(144181, 'ptBR', 'Os Ferro Negro não ligam para o calor. Mas essa umidade...', 'Os Ferro Negro não ligam para o calor. Mas essa umidade...', 28153),
(144180, 'ptBR', 'A Liga dos Exploradores gosta mesmo dessas escavações, mesmo quando tem uma guerra a se vencer.', 'A Liga dos Exploradores gosta mesmo dessas escavações, mesmo quando tem uma guerra a se vencer.', 28153),
(144179, 'ptBR', 'Nós saímos da nossa montanha pra isso?', 'Nós saímos da nossa montanha pra isso?', 28153),
(144178, 'ptBR', 'Não precisa de todo esse drama.', '', 28153),
(144177, 'ptBR', '', 'Esses rastros... a remoção desigual da terra... como é que nós vamos exibir isso?!', 28153),
(144176, 'ptBR', 'Sério, foi tão ruim assim?', '', 28153),
(144175, 'ptBR', '', 'Espere!', 28153),
(144174, 'ptBR', 'Se quiser apressar as coisas, fique à vontade. Esse dispositivo será útil.', '', 28153),
(144173, 'ptBR', 'Gratificante? Madame, a gente vai ficar o ano todo aqui a essa velocidade.', '', 28153),
(144172, 'ptBR', '', 'Aaahhhh, que maravilha. Não é gratificante?', 28153),
(144171, 'ptBR', '', 'Tente não danificar o fóssil... Excelente.', 28153),
(144170, 'ptBR', '', 'Ótimo. Agora, mantenha as mãos firmes.', 28153),
(144169, 'ptBR', '', 'Cuidado onde pisam, druidas! Este lugar é uma armadilha mortal!', 28153),
(144168, 'ptBR', 'Trabalho excelente! Com isso poderemos enfrentar aquelas monstruosas criaturas de madeira. Ah... mas não deixe derramar.', '', 28153),
(144167, 'ptBR', 'Eu agradeço por tê-la trazido de volta pra mim.', '', 28153),
(144166, 'ptBR', '', 'Tá aqui a caixa da engenhoca injetora. Agora é só instalar.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144165, 'ptBR', '', 'Oi, papai!', 28153),
(144164, 'ptBR', 'Pâmela! Ah, minha filhinha!', '', 28153),
(144163, 'ptBR', 'Seus avanços na Serraria são apenas temporários! Nós vamos tomá-la de volta!', '', 28153),
(144162, 'ptBR', 'Vamos procurar seu pai.', 'Vamos procurar seu pai.', 28153),
(144161, 'ptBR', '', 'Olá! Qual é o seu nome?', 28153),
(144160, 'ptBR', 'Não percebe o perigo que você está correndo?', 'Não percebe o perigo que você está correndo?', 28153),
(144159, 'ptBR', 'Você não pode deter todos nós!', 'Você não pode deter todos nós!', 28153),
(144158, 'ptBR', 'Você jamais encontrará todos nós!', 'Você jamais encontrará todos nós!', 28153),
(144157, 'ptBR', 'Minha posição foi comprometida!', 'Minha posição foi comprometida!', 28153),
(144156, 'ptBR', 'Olha! Eles cataram um dos nossos tambores!\n\nQuem falou que goblin não tem cultura?', '', 28153),
(144153, 'ptBR', 'Agora precisamos de umas gotas de seiva volátil. Cuidado para não sacolejar demais o frasco!', '', 28153),
(144152, 'ptBR', 'Pode colocar enxofre. Cuidado com os vapores!', '', 28153),
(144151, 'ptBR', 'Agora coloque florescilar, mas com cuidado.', '', 28153),
(144150, 'ptBR', 'Temos que colocar salitre para dar um toque especial!', '', 28153),
(144148, 'ptBR', 'Krag\'wa acena com a cabeça para o seu companheiro.', '', 28153),
(144147, 'ptBR', 'Krag\'wa e o crorguinho jovem parecem estar se comunicando.', '', 28153),
(144146, 'ptBR', 'Não! Eu jamais voltarei pra aquela cela! JAMAIS!', '', 28153),
(144145, 'ptBR', '', 'Defendam o santuário! Não podemos perdê-lo.', 28153),
(144144, 'ptBR', 'Excelente! Eu lhe direi o que deve ser colocado no caldeirão. Siga minhas instruções à risca, senão tudo pode ir pelos ares.', '', 28153),
(144142, 'ptBR', 'Tchau, Pâmela!', '', 28153),
(144141, 'ptBR', '', 'Sim! Até a próxima, Zé!', 28153),
(144140, 'ptBR', '', 'Ei, Zé!', 28153),
(144139, 'ptBR', 'Ah, oi, Pâmela. Está indo ver seu pai?', '', 28153),
(144138, 'ptBR', 'Qual é o problema dessas pessoas?!', '', 28153),
(144137, 'ptBR', '', 'Eu preciso de cura!', 28153),
(144136, 'ptBR', '', 'Renda-se aos elementos!', 28153),
(144135, 'ptBR', '$n, não há nada que eu possa fazer para reverter a situação dele. Ele terá uma vida melhor ao seu lado. Leve-o consigo. Proteja-o.', '', 28153),
(144134, 'ptBR', 'Entendo.', '', 28153),
(144133, 'ptBR', 'Aproxime-se, jovem.', '', 28153),
(144132, 'ptBR', 'Pesadelo...', '', 28153),
(144131, 'ptBR', 'A lua... está nascendo...', '', 28153),
(144130, 'ptBR', 'Praias distantes...', '', 28153),
(144129, 'ptBR', 'Não mexe... na panela...', '', 28153),
(144128, 'ptBR', 'Mais duas doses... e uma pimenta bitela...', '', 28153),
(144127, 'ptBR', 'A montanha central... desmorona...', '', 28153),
(144126, 'ptBR', 'Mais dez minutinhos...', '', 28153),
(144125, 'ptBR', 'Ainda não...', '', 28153),
(144124, 'ptBR', 'Tretínio ruge num tom protetor.', '', 28153),
(144123, 'ptBR', 'Encare seu fim!', 'Encare seu fim!', 28153),
(144122, 'ptBR', 'Veja a verdade... da sua destruição...', '', 28153),
(144121, 'ptBR', 'Não há vitória... para você... só... a morte...', '', 28153),
(144120, 'ptBR', 'Insignificante... contra... o... Caos...', '', 28153),
(144119, 'ptBR', 'Você... não venceu.... nada...', '', 28153),
(144118, 'ptBR', 'Os mestres... acordarão...', '', 28153),
(144117, 'ptBR', 'O Caos chega... para todos...', '', 28153),
(144116, 'ptBR', 'Inútil... tudo será... trevas...', '', 28153),
(144115, 'ptBR', 'Vão achar seu corpo nas docas!', 'Vão achar seu corpo nas docas!', 28153),
(144114, 'ptBR', 'Kul Tiraz não precisa da Aliança!', 'Kul Tiraz não precisa da Aliança!', 28153),
(144113, 'ptBR', 'Eu vou jogar você nas garras das ondas!', 'Eu vou jogar você nas garras das ondas!', 28153),
(144112, 'ptBR', '<Fila para a Batalha de Stromgarde>', '<Fila para a Batalha de Stromgarde>', 28153),
(144111, 'ptBR', 'Nesta mesa, você pode entrar na fila para lutar em um Front de Guerra.', '', 28153),
(144110, 'ptBR', 'Katherine ia nos deixar morrer afogados!', 'Katherine ia nos deixar morrer afogados!', 28153),
(144109, 'ptBR', 'Azeroth é nossa.', '', 28153),
(144108, 'ptBR', 'O império renascerá!', '', 28153),
(144107, 'ptBR', 'Encontrem eles!', '', 28153),
(144106, 'ptBR', 'Tudo estará perdido.', '', 28153),
(144105, 'ptBR', 'Todos tombarão.', '', 28153),
(144104, 'ptBR', 'Sem esperança... sem vida.', '', 28153),
(144103, 'ptBR', 'Todos serão consumidos.', '', 28153),
(144102, 'ptBR', 'Tudo será sombra.', '', 28153),
(144101, 'ptBR', 'O Caos traga tudo.', '', 28153),
(144100, 'ptBR', '', 'Druidas da Garra, ATACAR!', 28153),
(144099, 'ptBR', '<Assobio>', '', 28153),
(144097, 'ptBR', '', 'Então vai ser o \"Plano B\"...', 28153),
(144096, 'ptBR', 'As informações tão comigo. A gente só tem que dar o fora daqui com elas!', '', 28153),
(144095, 'ptBR', '', 'Descobriram a gente!', 28153),
(144094, 'ptBR', 'S-s-s-s <estática> sangue de Azeroth detectado. Solicitação: instalação de núcleo de da-da-da-da <estática>.', '', 28153),
(144093, 'ptBR', 'Ugh. Que troço ruim!', '', 28153),
(144092, 'ptBR', 'Jabari, tu tem a memória de um elekk e a sagacidade de Gonk.', '', 28153),
(144091, 'ptBR', 'Claro, vamos equiparar \"picante\" a injeções venenosas e mortais. É uma comparação justa...', '', 28153),
(144090, 'ptBR', 'Não preciso de tu me paparicando, Jabari! Eu comi o chili do Haw\'li e vivi pra contar!', '', 28153),
(144089, 'ptBR', 'Pare. Está parecendo um bicho com a garganta inflamada.', '', 28153),
(144088, 'ptBR', 'Psiu, mano. Pega isso.', '', 28153),
(144087, 'ptBR', 'Para de mexer nisso!', '', 28153),
(144086, 'ptBR', 'Exatamente! Agora, vejamos o que mais...', '', 28153),
(144085, 'ptBR', 'Dá para notar que você já praticou alquimia antes!', '', 28153),
(144084, 'ptBR', 'Muito bem! Agora precisamos...', '', 28153),
(144082, 'ptBR', 'Já está carregado. Depois que eu disparar, eles vão saber que estamos aqui.$b$bVocê está $Upronto:pronta;?', '', 28153),
(144081, 'ptBR', 'É só questão de tempo até virem conferir aqui...', '', 28153),
(144080, 'ptBR', '', 'Certo! Vamos lá!', 28153),
(144079, 'ptBR', '', 'Espere! Temos que dar as mãos!', 28153),
(144078, 'ptBR', 'Proudmore cairá!', 'Proudmore cairá!', 28153),
(144077, 'ptBR', 'Minha morte não impede a mudança da maré.', 'Minha morte não impede a mudança da maré.', 28153),
(144076, 'ptBR', 'Você se arrependerá disso!', 'Você se arrependerá disso!', 28153),
(144075, 'ptBR', 'Você não devia estar aqui!', 'Você não devia estar aqui!', 28153),
(144074, 'ptBR', 'Boralus é nossa!', 'Boralus é nossa!', 28153),
(144073, 'ptBR', '', 'Zul tem muitas forças daqui até Atal\'Dazar. Temos que acabar com elas.', 28153),
(144072, 'ptBR', 'Elfos...', 'Elfos...', 28153),
(144071, 'ptBR', 'O Impositor Rastali cospe no chão.', 'O Impositor Rastali suspira.', 28153),
(144070, 'ptBR', 'De jeito nenhum. É tão primitivo. Beleza, em 3... 2... 1...', '', 28153),
(144069, 'ptBR', '', 'Não deixe de pegar aquele templo feioso lá no fundo.', 28153),
(144068, 'ptBR', '', 'Nossos amigos em Luaprata vão morrer de ciúmes quando virem o retrato.', 28153),
(144067, 'ptBR', 'Minha provação está concluída. Eu terminei a última parte da minha história e voltei ao reino material.', 'Minha provação está concluída. Eu terminei a última parte da minha história e voltei ao reino material.', 28153),
(144066, 'ptBR', 'A criatura me olhou nos olhos e penetrou minha mente, enchendo-me do conhecimento necessário para evocá-la.', 'A criatura me olhou nos olhos e penetrou minha mente, enchendo-me do conhecimento necessário para evocá-la.', 28153),
(144065, 'ptBR', 'Ela terminou de se formar e gritou com a força da vida que nascia.', 'Ela terminou de se formar e gritou com a força da vida que nascia.', 28153),
(144064, 'ptBR', 'Quando o ritual foi concluído, vi uma criatura amalgamar-se diante de mim.', 'Quando o ritual foi concluído, vi uma criatura amalgamar-se diante de mim.', 28153),
(144063, 'ptBR', 'Quando entrei na câmara, notei quatro runas espalhadas pelo chão. Deve ser para isso que a tinta servia.', 'Quando entrei na câmara, notei quatro runas espalhadas pelo chão. Deve ser para isso que a tinta servia.', 28153),
(144062, 'ptBR', 'Depois que coletei tinta suficiente, senti que algo me puxava para uma ponta dos salões.', 'Depois que coletei tinta suficiente, senti que algo me puxava para uma ponta dos salões.', 28153),
(144061, 'ptBR', 'Um esqueleto no chão me lembra da minha própria mortalidade. Pergunto-me se outros falharam nessa provação.', 'Um esqueleto no chão me lembra da minha própria mortalidade. Pergunto-me se outros falharam nessa provação.', 28153),
(144060, 'ptBR', 'Esses viscosos estavam começando a se tornar um aborrecimento.', 'Esses viscosos estavam começando a se tornar um aborrecimento.', 28153),
(144059, 'ptBR', 'Os lodos eram a chave da charada. E até aqui eu tinha encontrado o que precisava.', 'Os lodos eram a chave da charada. E até aqui eu tinha encontrado o que precisava.', 28153),
(144058, 'ptBR', 'De algum modo, eu sabia o que devia fazer. Eu decidi continuar.', 'De algum modo, eu sabia o que devia fazer. Eu decidi continuar.', 28153),
(144057, 'ptBR', 'Cuidado com o jorro, colete o rubro, e seu matador vinculado ao sangue se erguerá.\"', 'Cuidado com o jorro, colete o rubro, e seu matador vinculado ao sangue se erguerá.\"', 28153),
(144056, 'ptBR', '\"O que de uma pena escorre, e de uma veia escorre, aqui é mesclado.', '\"O que de uma pena escorre, e de uma veia escorre, aqui é mesclado.', 28153),
(144055, 'ptBR', 'Eu acordei em uma câmara. Uma voz estranha recitava um poema na minha mente.', 'Eu acordei em uma câmara. Uma voz estranha recitava um poema na minha mente.', 28153),
(144054, 'ptBR', 'Você começa a escrever no livro: \"Quando minha pena tocou a página, eu senti uma atração.\"', 'Você começa a escrever no livro: \"Quando minha pena tocou a página, eu senti uma atração.\"', 28153),
(144053, 'ptBR', 'Ao folhear o resto do livro, você vê que todas as páginas parecem estar vazias. Você lança um olhar de frustração para Kronah, se perguntando se ela sabe algum truque deste teste.', '', 28153),
(144052, 'ptBR', 'Não vejo a hora de ler o relato do seu encontro.', '', 28153),
(144051, 'ptBR', 'Basta pegar uma pena e começar a escrever. Não se preocupe, o livro fará o restante.', '', 28153),
(144050, 'ptBR', 'Bom, é simples. Você tem de escrever a sua própria história no livro.', '', 28153),
(144049, 'ptBR', 'Ai, não. Lá vem...', '', 28153),
(144048, 'ptBR', 'Eu tenho uns espinhos para trocar.', 'Eu tenho uns espinhos para trocar.', 28153),
(144047, 'ptBR', 'Minha nossa, essa saiu totalmente fora dos planos. Hora de tentar de novo!', '', 28153),
(144046, 'ptBR', 'Alquimia é uma ciência muito precisa! Tente prestar mais atenção.', '', 28153),
(144045, 'ptBR', 'Bom, não estava certo. Teremos que recomeçar do começo!', '', 28153),
(144044, 'ptBR', 'A mistura entrou em combustão! Temos que começar novamente!', 'A mistura entrou em combustão! Temos que começar novamente!', 28153),
(144043, 'ptBR', 'Zul previu este dia. Lutando para mudar o destino só prova a verdade inevitável!', '', 28153),
(144042, 'ptBR', 'Zul... não falou... que eu ia perder...', '', 28153),
(144041, 'ptBR', 'Vocês nunca chegarão ao precipício a tempo!', '', 28153),
(144040, 'ptBR', 'Estou pronto para começar!', 'Estou pronta para começar!', 28153),
(144039, 'ptBR', 'Peraí! Eu já estou melhor! Ungh...', 'Peraí! Eu já estou melhor! Ungh...', 28153),
(144038, 'ptBR', 'Que tolice a minha!', 'Que tolice a minha!', 28153),
(144037, 'ptBR', 'Não escuto mais a canção dela...', 'Não escuto mais a canção dela...', 28153),
(144036, 'ptBR', 'Ela nunca vai amar você!', 'Ela nunca vai amar você!', 28153),
(144035, 'ptBR', 'Nããão, meu amor!', 'Nããão, meu amor!', 28153),
(144034, 'ptBR', 'O amor machuca.', 'O amor machuca.', 28153),
(144033, 'ptBR', 'Vale a pena!', 'Vale a pena!', 28153),
(144032, 'ptBR', 'Calca-me a dor com tanto afã.', 'Calca-me a dor com tanto afã.', 28153),
(144031, 'ptBR', 'Ei, gata, olha só como eu sou forte.', 'Ei, gata, olha só como eu sou forte.', 28153),
(144030, 'ptBR', 'Tá olhando pra minha namorada?!', 'Tá olhando pra minha namorada?!', 28153),
(144029, 'ptBR', 'O amor tudo suporta!', 'O amor tudo supera!', 28153),
(144028, 'ptBR', 'Ela é minha! MINHA!', 'Ela é minha! MINHA!', 28153),
(144027, 'ptBR', 'Só temos a agradecer. Você salvou esta vila e me inspirou a coragem. Albe e Teroldo, empenhem-se na recuperação do Caniço. Nos falaremos novamente em breve.', '', 28153),
(144026, 'ptBR', 'Não toque nela!', 'Não toque nela!', 28153),
(144025, 'ptBR', 'Zul quer acordar Dazar?! Não ficarei parado enquanto esse \"profeta\" corrompe os ossos do primeiro rei. Vem, $gcampeão:campeã; e se junte a nós no portão sul deste lugar.', '', 28153),
(144024, 'ptBR', 'Agora tenho que voltar para casa. Meu tio e seus Sábios das Marés no Vale Trovamare talvez tenham mais informações sobre essa magia negra.', '', 28153),
(144023, 'ptBR', 'Guardafunda... ele sempre foi inteligente, mas eu não sabia que ele mexia com magia. Manipular um poder capaz de causar tanto pavor ao oceano...', '', 28153),
(144022, 'ptBR', 'Cai fora, ela já tem dono!', 'Cai fora, ela já tem dono!', 28153),
(144021, 'ptBR', '', 'Sim! Uma brecha entre os mata-céus deles. Voem, crianças! Matem os hereges!', 28153),
(144020, 'ptBR', 'O Caniço foi salvo, mas meu medo persiste. Guardafunda, mesmo sendo um homem inteligente, não tinha tanto poder antes.', '', 28153),
(144019, 'ptBR', 'Eu protegerei você, meu amor!', 'Eu protegerei você, meu amor!', 28153),
(144018, 'ptBR', 'Eu a amo tanto!', 'Eu a amo tanto!', 28153),
(144017, 'ptBR', 'A MÃO DO DESTINO FOI SACIADA. EU FAREI COM QUE VOCÊ CHEGUE A UM LUGAR SEGURO. ÀS VEZES, O DESTINO É BONDOSO.', '', 28153),
(144016, 'ptBR', 'Sai da nossa cidade, $p! Você vai amaldiçoar a gente!', '', 28153),
(144015, 'ptBR', 'Abram alas pr$Go:a; $p, abençoad$Go:a; dos loas!', '', 28153),
(144013, 'ptBR', '', 'Os presságios tão misturados... Tu vai enfrentar desafios impossíveis, mas vai superar eles. Os loas não vão te abandonar.', 28153),
(144012, 'ptBR', '', 'Vixe, só tem sinal ruim aqui... Vai ter treta pra caramba no teu futuro. Foi mal aí.', 28153),
(144011, 'ptBR', '', 'Evita a água hoje. Ela tá perigosa.', 28153),
(144010, 'ptBR', '', 'Vazio? Não... tu tem que mudar isso.', 28153),
(144009, 'ptBR', '', 'Tu vai ser expost$uo:a; a grandes dificuldades e traições. Escolhe teus parceiros com cuidado hoje.', 28153),
(144008, 'ptBR', '', 'Eu não recebo esse presságio faz muito, muito tempo... Tu vai ter que mudar teu destino.', 28153),
(144007, 'ptBR', '', 'Não tome atalhos pra alcançar teus objetivos hoje. Qualquer risco ou imprudência vai levar a um fim trágico.', 28153),
(144006, 'ptBR', '', 'Mandaram o aviso lá do Outro Lado. Te cuida.', 28153),
(144005, 'ptBR', '', 'Cuidado com a Cidade de Ouro. Ela não vale a pena.', 28153),
(144004, 'ptBR', '', 'É, tu vai ter que adentrar o futuro às cegas.', 28153),
(144003, 'ptBR', '', 'Gral é puxado pras profundezas por uma mão invisível.', 28153),
(144002, 'ptBR', '', 'O ninho de Shadra está vazio.', 28153),
(144001, 'ptBR', '', 'Torcali dorme.', 28153),
(144000, 'ptBR', '', 'Rezan cai por terra... morto.', 28153),
(143999, 'ptBR', '', 'Bwonsamdi propõe um acordo com malícia.', 28153),
(143998, 'ptBR', '', 'Krag\'wa devora uma manada de escornantes azuis.', 28153),
(143997, 'ptBR', '', 'Gonk está sozinho, nadando num rio de ouro.', 28153),
(143996, 'ptBR', '', 'Pa\'kul fecha os olhos nas trevas.', 28153),
(143995, 'ptBR', '', 'Difícil ver presságio pior do que esse. Vá com cuidado.', 28153),
(143994, 'ptBR', '', 'Um sinal ruim pra todos nós. O que tu trouxe pra nossa praia?', 28153),
(143993, 'ptBR', '', 'Tu tá desperdiçando o seu potencial. Aproveita as oportunidades, ou seja esquecid$uo:a; entre as lápides sem nome.', 28153),
(143992, 'ptBR', '', 'A divisão entre tu e teus aliados é um risco pra geral. Tu tem que unir Zandalar.', 28153),
(143991, 'ptBR', '', 'É um presságio ruim, mas tu é capaz de vencer ele com força e determinação.', 28153),
(143990, 'ptBR', '', 'Líderes divididos não servem pra liderar. Se não colar com teus rivais, tu vai sofrer as consequências.', 28153),
(143989, 'ptBR', '', 'Vai surgir uma escuridão que vai consumir até os mais fortes. Inclusive tu.', 28153),
(143988, 'ptBR', '', 'Um sinal ruim pra todos nós...', 28153),
(143987, 'ptBR', '', 'A morte de um novo amigo.', 28153),
(143986, 'ptBR', '', 'O sol se pondo no pântano sombrio de Nazmir.', 28153),
(143985, 'ptBR', '', 'Um vaso trincado, vazando vinho.', 28153),
(143984, 'ptBR', '', 'Dois sacerdotes se matando.', 28153),
(143983, 'ptBR', '', 'Um navio humano atracando na nossa praia...', 28153),
(143982, 'ptBR', '', 'Um trono estropiado de fogo e gelo...', 28153),
(143981, 'ptBR', '', 'Um brutossauro afogando em sangue.', 28153),
(143980, 'ptBR', '', 'Um rio de sangue com defuntos subindo a correnteza...', 28153),
(143979, 'ptBR', 'Anda, Coçadinha! Vamos!', 'Anda, Coçadinha! Vamos!', 28153),
(143978, 'ptBR', 'Viva! Obrigada!', 'Viva! Obrigada!', 28153),
(143977, 'ptBR', 'Opa. Agora melhorou!', '', 28153),
(143976, 'ptBR', 'Eu falei pra darem no pé, mas eles queriam ver mais... Quase fecharam meu paletó... se não fosse tu, eu já teria empacotado.', '', 28153),
(143975, 'ptBR', '', 'Fala por Zetoa, seu receptáculo!', 28153),
(143974, 'ptBR', '', 'Fala por Iluna, seu receptáculo!', 28153),
(143973, 'ptBR', '', 'Tudo pronto. Preencham meus receptáculos e revelem o futuro.', 28153),
(143972, 'ptBR', '', 'Espíritos dos mortos, espíritos dos loas, dos perdidos e atribulados, ouçam minha voz!', 28153),
(143971, 'ptBR', 'Vou voltar para a linha de defesa!', 'Vou voltar para a linha de defesa!', 28153),
(143970, 'ptBR', 'Não dava para eu me mexer!', 'Não dava para eu me mexer!', 28153),
(143969, 'ptBR', 'Achei que fossem me arrastar para dentro da floresta!', 'Achei que fossem me arrastar para dentro da floresta!', 28153),
(143968, 'ptBR', 'Eles já levaram as pessoas para a floresta!', 'Eles já levaram as pessoas para a floresta!', 28153),
(143967, 'ptBR', 'Vou voltar para a barricada!', 'Vou voltar para a barricada!', 28153),
(143966, 'ptBR', '', 'Só presságio bom pra tu... Vai sem medo hoje que vai rolar!', 28153),
(143965, 'ptBR', 'Achei que era o meu fim!', 'Achei que era o meu fim!', 28153),
(143964, 'ptBR', 'Eu agradeço!', 'Eu agradeço!', 28153),
(143963, 'ptBR', '', 'Um estampido...', 28153),
(143962, 'ptBR', '', 'Um presságio leve... Não deixe a ansiedade te dominar. A felicidade e o bom humor vão te levar ao sucesso.', 28153),
(143961, 'ptBR', 'A praga floresce!', '', 28153),
(143960, 'ptBR', 'Tudo... se decompõe...', '', 28153),
(143959, 'ptBR', '', 'A bênção mais comum de Shadra, com uma coisinha a mais. É coisa boa, mas não dá pra entender completamente.', 28153),
(143958, 'ptBR', '', 'A bênção do defensor... Tu vai salvar muitas vidas, mas talvez entregue a tua.', 28153),
(143957, 'ptBR', '', 'O loa do rei é um presságio raro. Forte e poderoso. Tu vai destruir os inimigos do rei.', 28153),
(143956, 'ptBR', '', 'Um bom presságio de vida longa e morte tranquila.', 28153),
(143955, 'ptBR', 'Tenho que me alimentar!', '', 28153),
(143954, 'ptBR', 'Murche!', '', 28153),
(143953, 'ptBR', 'A corrupção cresce!', '', 28153),
(143952, 'ptBR', '', 'Considerando que tu não é da ilha, é um bom presságio.', 28153),
(143951, 'ptBR', 'Cresça!', '', 28153),
(143950, 'ptBR', '', 'Teus aliados sempre vão lutar do teu lado. Gonk não vai te abandonar na hora do desespero.', 28153),
(143949, 'ptBR', '', 'Pa\'kul vai guiar tua jornada e te livrar dos inimigos...', 28153),
(143948, 'ptBR', 'Bom adubo pro solo.', '', 28153),
(143947, 'ptBR', '', 'Gral se lança sobre a frota do rei...', 28153),
(143946, 'ptBR', '', 'Os ovos de Shadra se chocam. Mil olhos vêm observar...', 28153),
(143945, 'ptBR', '', 'Torcali se ergue no topo da montanha, sozinho...', 28153),
(143944, 'ptBR', '', 'Rezan pisa e os trolls sangrentos se espalham...', 28153),
(143943, 'ptBR', '', 'Bwonsamdi desvia o olhar...', 28153),
(143942, 'ptBR', '', ' Krag\'wa devora uma ilha...', 28153),
(143941, 'ptBR', 'Apodrecer!', '', 28153),
(143940, 'ptBR', '', 'Gonk corre ao lado de seu bando...', 28153),
(143939, 'ptBR', 'Colher!', '', 28153),
(143938, 'ptBR', 'Espalhem a podridão!', '', 28153),
(143937, 'ptBR', '', 'Quase todos bons presságios, mas vai depender do teu amigo...', 28153),
(143936, 'ptBR', '', 'É um bom presságio pra geral. Tua presença é muito bem-vinda em Zandalar.', 28153),
(143935, 'ptBR', '', 'Apesar da opinião geral, tu ainda não atingiu todo teu potencial. Teu poder vai aumentar e tua força vai superar todas as expectativas.', 28153),
(143934, 'ptBR', '', 'Presságio... inusitado pra $Gum forasteiro:uma forasteira;. O isso quer dizer?', 28153),
(143933, 'ptBR', '', 'Um presságio poderoso! É bom sinal pra tu...', 28153),
(143932, 'ptBR', '', 'Um bom presságio da expansão e crescimento do nosso povo. Interessante ter vindo pra tu...', 28153),
(143931, 'ptBR', '', 'Um bom presságio de prosperidade e tradição.', 28153),
(143930, 'ptBR', '', 'Um bom presságio de força, poder e sucesso.', 28153),
(143929, 'ptBR', '', 'Um antigo amigo ressuscitado...', 28153),
(143928, 'ptBR', '', 'O sol nascendo sobre águas douradas...', 28153),
(143927, 'ptBR', '', 'Um ovo grande, chacoalhando, mas sem se romper...', 28153),
(143926, 'ptBR', '', 'Todas as tribos trólicas unidas sob o estandarte Zandalari...', 28153),
(143925, 'ptBR', '', 'Uma cabeça élfica decapitada...', 28153),
(143924, 'ptBR', '', 'Águas antigas, em paz há gerações...', 28153),
(143923, 'ptBR', '', 'Máscaras de ouro...', 28153),
(143922, 'ptBR', '', 'A sombra de Pa\'kul caminha pelas pedras...', 28153),
(143921, 'ptBR', '', 'Beleza. Bora ver o que os espíritos têm a dizer pra tu...', 28153),
(143920, 'ptBR', '', 'Tem certeza que quer saber, $p?\n\nNem todo futuro acaba com grandes feitos e finais felizes...', 28153),
(143919, 'ptBR', 'Eu não tenho medo. Pode me contar o que viu no futuro.', 'Eu não tenho medo. Pode me contar o que viu no futuro.', 28153),
(143918, 'ptBR', 'O que você vê no meu futuro?', 'O que você vê no meu futuro?', 28153),
(143917, 'ptBR', '', 'Ouçam, espíritos, perdidos e ancestrais. Encham meus receptáculos pra revelar o futuro.', 28153),
(143916, 'ptBR', 'Não importa. Estamos espalhados... sob seus pés.', '', 28153),
(143915, 'ptBR', 'Vocês são fracos... Nossa tribo... é forte.', 'Vocês são fracos... Nossa tribo... é forte.', 28153),
(143914, 'ptBR', '', 'Boas-vindas à Tenda do Espírito Perdido, $p.\n\nTu tá atrasad$Uo:a;. Achei que não fosse chegar.\n\nMe conta, como a Madame Konawla pode te ajudar hoje?', 28153),
(143913, 'ptBR', 'Aceito a morte...', 'Aceito a morte...', 28153),
(143912, 'ptBR', 'Nossos espinhos... vão cobrir a terra...', 'Nossos espinhos... vão cobrir a terra...', 28153),
(143911, 'ptBR', 'Os Dorsarça... vão continuar fortes...', 'Os Dorsarça... vão continuar fortes...', 28153),
(143910, 'ptBR', 'Minha caminhada... termina.', 'Minha caminhada... termina.', 28153),
(143909, 'ptBR', 'Sua morte vai trazer honra.', 'Sua morte vai trazer honra.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143908, 'ptBR', 'Os espinhos vão crescer fortes com seu sangue.', 'Os espinhos vão crescer fortes com seu sangue.', 28153),
(143907, 'ptBR', 'Retroceder Nunca, Render-se Jamais', 'Sem se render, sem recuar!', 28153),
(143906, 'ptBR', 'Por que o Compêndio do Sangue Derramado está em branco?', 'Por que o Compêndio do Sangue Derramado está em branco?', 28153),
(143905, 'ptBR', 'Você vai virar comida de javali.', 'Você vai virar comida de javali.', 28153),
(143904, 'ptBR', 'Você não pode nos deter!', 'Você não pode deter a gente!', 28153),
(143903, 'ptBR', 'Nós vamos tomar esta terra!', 'Nós vamos tomar esta terra!', 28153),
(143902, 'ptBR', 'Começar a escrever o livro.', 'Começar a escrever o livro.', 28153),
(143901, 'ptBR', 'Passar o restante do livro inteiro.', 'Passar o restante do livro inteiro.', 28153),
(143900, 'ptBR', 'Coçadinhaaa! Você ainda tá aí em cima!? Dá duas miadinhas se estiver me ouvindo!', 'Coçadinhaaa! Você ainda está aí em cima!? Solte dois miados se estiver me ouvindo!', 28153),
(143899, 'ptBR', 'As páginas seguintes também parece estar em branco.', '', 28153),
(143898, 'ptBR', 'Vamos tirar você daí, Coçadinha! Fica bonzinho!', 'Vamos tirar você daí, Coçadinha! Não se mexa!', 28153),
(143897, 'ptBR', 'Vai ficar tudo bem, Coçadinha! Espera aí!', 'Vai ficar tudo bem, Coçadinha! Espere aí!', 28153),
(143896, 'ptBR', 'Virar mais algumas páginas.', 'Virar mais algumas páginas.', 28153),
(143895, 'ptBR', 'As páginas do livro parecem estar em branco.', '', 28153),
(143894, 'ptBR', 'MiAUUuuuu.', '', 28153),
(143893, 'ptBR', 'Aguenta firme, Coçadinha! A ajuda já tá chegando!', 'Aguente firme, Coçadinha! A ajuda está vindo!', 28153),
(143892, 'ptBR', 'Desce, Coçadinha! Vem! É perigoso ficar aí!', 'Desce, Coçadinha! Vem! É perigoso ficar aí!', 28153),
(143891, 'ptBR', 'Pode pular, Coçadinha! Eu pego você!', 'Pode pular, Coçadinha! Eu pego você!', 28153),
(143890, 'ptBR', 'Coçadiiiiinhaaa! Desce daí!!!', 'Coçadiiiiinhaaa! Desce daí!!!', 28153),
(143889, 'ptBR', '', 'Tu vai virar comida dos meus bichinhos, $r!', 28153),
(143888, 'ptBR', 'Campeão. Por aqui.', '', 28153),
(143887, 'ptBR', 'Aqui!', '', 28153),
(143886, 'ptBR', 'Cuidado!', '', 28153),
(143885, 'ptBR', 'Por aqui.', '', 28153),
(143884, 'ptBR', 'Por aqui.', '', 28153),
(143883, 'ptBR', 'Cuidado!', '', 28153),
(143882, 'ptBR', 'Aqui!', '', 28153),
(143881, 'ptBR', 'Você. Aqui.', '', 28153),
(143879, 'ptBR', 'Expurgar!', '', 28153),
(143876, 'ptBR', 'Está feito.', '', 28153),
(143875, 'ptBR', 'Sangue! Sangue! Sangue!', '', 28153),
(143874, 'ptBR', 'Zuldazar vai cair!', '', 28153),
(143873, 'ptBR', 'Carne fresca!', '', 28153),
(143872, 'ptBR', 'Quero teu sangue!', '', 28153),
(143871, 'ptBR', 'Vamos aproveitar todos os teus ossos!', '', 28153),
(143870, 'ptBR', 'Seu sangue pra G\'huun!', '', 28153),
(143869, 'ptBR', 'Ninguém se esconde do Deus do Sangue!', '', 28153),
(143868, 'ptBR', 'Guzincha!', '', 28153),
(143867, 'ptBR', 'Kachago!', '', 28153),
(143865, 'ptBR', 'Você não leu o anúncio, $Grapaz:moça;?\n\nSem reembolso. Sem exceções. Sem choradeira.\n\nSabe o que vai animar você... um Pulo Porreta Pé-de-pena!', '', 28153),
(143864, 'ptBR', 'Me vê um Pulo Porreta Pé-de-pena!', 'Me vê um Pulo Porreta Pé-de-pena!', 28153),
(143863, 'ptBR', 'Eu quero um reembolso.', 'Eu quero um reembolso.', 28153),
(143862, 'ptBR', 'Bem-$Gvindo:vinda; de volta, $p!\n\nTomara que você esteja aproveitando a Família Pulos Porretas Pé-de-pena.\n\nComo membro credenciad$Go:a;, você tem direito a um número ilimitado de quedas lentas do topo do zigurate. Quando quiser mais uma, é só avisar!\n\nNão trabalhamos com reembolso.', '', 28153),
(143861, 'ptBR', 'Entre para a Família Pulos Porretas Pé-de-pena hoje mesmo!\n\nPor uma pequena taxa, você ganha um número ilimitado de quedas lentas do topo do zigurate. Sobrevivência garantida!\n\nNão trabalhamos com reembolso.', '', 28153),
(143860, 'ptBR', 'Os ventos sopram mais forte aqui em cima do que na Alta Montanha. A decisão de entrar na Horda já está valendo a pena.', '', 28153),
(143859, 'ptBR', 'Retornem à tempestade e recebam a paz. Venham ao Santuário para que possamos compartilhar sua força.', '', 28153),
(143858, 'ptBR', '', 'Que cidade maravilhosa. Explorar o mundo é incrível!', 28153),
(143857, 'ptBR', 'Ouçam nosso chamado, ó decaídos. Seus feitos perversos serão perdoados hoje.', '', 28153),
(143856, 'ptBR', 'Quando estiver tudo pronto, liberte as almas no sino.', '', 28153),
(143855, 'ptBR', 'Rosaline, desculpe, mas você tem que esperar. Hoje estamos com problemas mais urgentes do que caçadas.', '', 28153),
(143854, 'ptBR', '', 'Ei! Teroldo! Chega de lenga-lenga. A gente precisa da bênção pra ir à caça!', 28153),
(143853, 'ptBR', 'Volte logo, $p!', '', 28153),
(143852, 'ptBR', 'Dez pontos por cuspir nos trolls sangrentos que você vir!', '', 28153),
(143851, 'ptBR', 'Pulos Porretas Pé-de-pena! Conte pros amigos!', '', 28153),
(143850, 'ptBR', 'Bom ver você de novo, $p. Feliz queda!', '', 28153),
(143849, 'ptBR', 'Tente pousar no brutossauro!', '', 28153),
(143848, 'ptBR', 'Tente pousar em uma cachoeira!', '', 28153),
(143847, 'ptBR', 'Cuidado com os pterrordaxes!', '', 28153),
(143846, 'ptBR', 'Boa viagem, $p.', '', 28153),
(143845, 'ptBR', 'Aaaaaaaaaugh!', '', 28153),
(143844, 'ptBR', 'Pela Aliança.', '', 28153),
(143843, 'ptBR', 'Pela Horda!', '', 28153),
(143842, 'ptBR', 'Stromgarde já era. Te rende logo, Rogers, e salva tua pele.', '', 28153),
(143841, 'ptBR', 'Agora, sim! Esse é... meu martelo!', '', 28153),
(143840, 'ptBR', 'Ô de casa! Tem um tampinha chamado Barbabronze aí?', '', 28153),
(143839, 'ptBR', 'A Luz ainda me acompanha. Não cairei tão fácil assim!', '', 28153),
(143838, 'ptBR', 'Almirante Rogers! Arrombamos sua fortaleza. Onde está sua retaliação agora, paladina?', '', 28153),
(143837, 'ptBR', 'Eles tão pensando que um bando de cavaleiro vai deter a gente? Hah! Mostra pra eles como é que a banda toca com a Horda!', '', 28153),
(143836, 'ptBR', 'O baluarte tá precisando de reforços. Destrói os tanques pra eles não avançarem mais!', '', 28153),
(143835, 'ptBR', 'Nossas defesas ainda estão fracas. Tropas da Horda, voltem à base e defendam nossa posição!', '', 28153),
(143834, 'ptBR', 'Muito bem. Se vocês querem guerra, então terão guerra. Despachem um batalhão montado para cuidar deles!', '', 28153),
(143833, 'ptBR', 'O Círculo dos Elementos agora tá sob controle da Horda.', '', 28153),
(143832, 'ptBR', 'Novaterra é nossa... e, com ela, vêm os cavalga-lobos.', '', 28153),
(143831, 'ptBR', 'A armaria tá prontinha, cara.', '', 28153),
(143830, 'ptBR', 'A oficina tá pronta. Os demolidores vão derrubar as muralhas da Aliança rapidinho!', '', 28153),
(143829, 'ptBR', 'Máquinas de cerco, destruam!', '', 28153),
(143828, 'ptBR', 'Vocês foram avisados, corja da Horda. Agora se preparem para ser aniquilados.', '', 28153),
(143827, 'ptBR', 'Isso era tudo terra dos trolls muito antes da Aliança saber que existia, Turalyon.', '', 28153),
(143826, 'ptBR', 'Hunf. Você vai se misturar logo.', '', 28153),
(143825, 'ptBR', 'Essa roupa vai ter que servir por enquanto.', '', 28153),
(143824, 'ptBR', 'A gente tem que começar do começo. Precisamos de madeira e ferro pra construir uma base da Horda aqui. Deve ter a rodo por aí.', '', 28153),
(143823, 'ptBR', 'Também tô esperando, Muradin.', '', 28153),
(143822, 'ptBR', 'Talvez essa roupa melhore suas habilidades de coleta.', '', 28153),
(143821, 'ptBR', 'Pff! Engole essa sua retaliação, Turalyon!', '', 28153),
(143820, 'ptBR', 'Estas terras são da Aliança! A retaliação contra esses invasores da Horda será implacável!', '', 28153),
(143819, 'ptBR', 'Agora, pertencem à Horda!', '', 28153),
(143818, 'ptBR', 'Cem anos atrás, essas terras aqui, era tudo dos trolls.', '', 28153),
(143817, 'ptBR', 'Ah... com prazer, $gguri:guria;. Agora tu mexeu com o anão errado.', '', 28153),
(143816, 'ptBR', 'Muradin! Apareça, seu covarde!', '', 28153),
(143815, 'ptBR', 'Nossas defesas ainda estão fracas. Detenha aqueles tanques antes que cheguem à nossa base!', '', 28153),
(143814, 'ptBR', 'Muito menos feio que você, Barbabronze!', '', 28153),
(143813, 'ptBR', 'Perdão, Avaliadora.', '', 28153),
(143812, 'ptBR', 'É uma honra servir você, Avaliadora.', '', 28153),
(143811, 'ptBR', '', 'Acabou a batalha... e nós sobrevivemos. Ateena vai pagar caro por essa loucura!', 28153),
(143810, 'ptBR', '', 'Eis o destruidor de Zuldazar! Quer tentar parar a gente? Pode vir, vai ser lindo te ver sofrer!', 28153),
(143809, 'ptBR', '', 'Tu chegou aqui e aqui vai ficar quando a fúria do mestre cair sobre você!', 28153),
(143808, 'ptBR', 'Trabalhar no Relicário é exaustivo...', '', 28153),
(143807, 'ptBR', 'Hah, fácil demais! Tente a sorte no campo. É sempre bom ter mais lenha.', '', 28153),
(143806, 'ptBR', 'É pra já, Avaliadora.', '', 28153),
(143805, 'ptBR', 'É um prazer poder ser útil, Avaliadora.', '', 28153),
(143804, 'ptBR', 'Com prazer, Avaliadora.', '', 28153),
(143803, 'ptBR', '', 'Seu corpo vai cair como uma luva para o mestre!', 28153),
(143802, 'ptBR', '', 'A Horda vai ser a próxima a cair. Tu vai pagar pela morte do Hir\'eek! Tu não têm saída.', 28153),
(143801, 'ptBR', '', 'Zuldazar vai cair... e meu mestre enfim estará livre! Seus loas ridículos não são páreo para ele!', 28153),
(143800, 'ptBR', 'É para já, Avaliadora.', '', 28153),
(143799, 'ptBR', 'Já vou, Avaliadora.', '', 28153),
(143798, 'ptBR', '', 'Interessante... Baeloth, venha ver isso e me dizer o que você acha.', 28153),
(143797, 'ptBR', '', 'Para onde você fugiu, Baeloth? Eu tenho mais epifanias de valor imensurável para você anotar.', 28153),
(143796, 'ptBR', '', 'Baeloth, meu anjo, venha ver isso.', 28153),
(143795, 'ptBR', '', 'Não temos tempos para descanso no Relicário, Baeloth.', 28153),
(143794, 'ptBR', '', 'Baeloth, não toque nos artefatos!', 28153),
(143793, 'ptBR', '', 'Que maravilha... Baeloth, venha ver que maravilha!', 28153),
(143792, 'ptBR', '', 'O escudo de Hezrel tá ativado! Entrem nele!', 28153),
(143791, 'ptBR', '', 'Sonhando de novo, Baeloth? Você bem que poderia me dar uma ajudinha aqui.', 28153),
(143790, 'ptBR', '', 'Baeloth, faça o favor de transcrever tudo que eu disser.', 28153),
(143789, 'ptBR', 'Os Rompe-ondas precisam de muitos suprimentos para continuar trabalhando na capacidade máxima! É meu dever rastrear e reabastecer as lojas, além de reparar engenhocas quebradas!$b$b...$b$bEles quebram inúmeras engenhocas por dia.$b$bNão são pessoas muito delicadas.', '', 28153),
(143788, 'ptBR', '', '$n, eu poderia falar com você? Preciso do seu auxílio.', 28153),
(143787, 'ptBR', '<< Ocorre um evento em que eu e outros trabalhadores seguimos pela estrada elevada com canhões. >>', '', 28153),
(143786, 'ptBR', 'Três pares de sapatos. Três pares d\'sapatos. T\'pares d\'sapatos. T\'pares d\'spatos. T\'pars paartos. T\'paastos. T\'paartos!', '', 28153),
(143785, 'ptBR', 'Eles parecem todos ter caído na minha encenação! Eu considero extraordinário que eles possam crer que eu seja assim tão simplório, a ponto de... Espere, quer dizer que eles podem me ouvir? Eu, hum... T\'paartos!', '', 28153),
(143784, 'ptBR', 'Lista de coisas que T\'paartos não gosta: cobra, criança malvada, cobra, caverna escura, cobra... e fracotes que atazanam T\'paartos.', '', 28153),
(143783, 'ptBR', 'Claro, T\'paartos já leu livros. Livros com poucas palavras e muitas figuras... mas figura conta, né.', '', 28153),
(143782, 'ptBR', 'Fracote não está tentando tirar vantagem da natureza bondosa de T\'paartos... está?', '', 28153),
(143781, 'ptBR', 'T\'paartos tem um leve medo de cobra.', '', 28153),
(143780, 'ptBR', 'T\'paartos tem orgulho de ser Forjado a Luz!', '', 28153),
(143779, 'ptBR', 'Venha falar com T\'paartos sempre que quiser.', '', 28153),
(143778, 'ptBR', 'T\'paartos tem que voltar ao trabalho agora.', '', 28153),
(143777, 'ptBR', 'T\'paartos tem muito a fazer.', '', 28153),
(143776, 'ptBR', 'T\'paartos verá você em breve.', '', 28153),
(143775, 'ptBR', 'T\'paartos.', '', 28153),
(143774, 'ptBR', 'Depressa, $n. Há vidas dependendo disso.', '', 28153),
(143773, 'ptBR', 'T\'paartos está pronto!', '', 28153),
(143772, 'ptBR', 'Que a Luz esteja contigo, camarada.', '', 28153),
(143771, 'ptBR', 'Perigo? T\'paartos ri do perigo!', '', 28153),
(143770, 'ptBR', 'Fracote precisa de alguma coisa do T\'paartos?', '', 28153),
(143769, 'ptBR', 'T\'paartos saúda fracote.', '', 28153),
(143768, 'ptBR', 'T\'paartos?', '', 28153),
(143767, 'ptBR', 'T\'paartos!', '', 28153),
(143766, 'ptBR', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s começa a lançar |cFFFF0000|Hspell:259610|h[Apocalipse Sangrento]|h|r! Procure abrigo!', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s começa a lançar |cFFFF0000|Hspell:259610|h[Apocalipse Sangrento]|h|r! Procure abrigo!', 28153),
(143765, 'ptBR', '', 'Bora! Luta! Seu sofrimento alimenta meu mestre!', 28153),
(143764, 'ptBR', 'Jaina? Está mais para Chataina. Modera? Está mais para... hum... olha, você não pode esperar que eu mande bem todas as vezes, está bem?', '', 28153),
(143763, 'ptBR', 'Hadggar? Está mais para Malagar. Não é não?', '', 28153),
(143762, 'ptBR', 'Kirin Tor? Está mais para Tenha Dó. Não é não?', '', 28153),
(143761, 'ptBR', 'Se vocês todos apenas fizessem o que eu mando em vez de pensar por conta própria, Azeroth estaria muito melhor.', '', 28153),
(143760, 'ptBR', 'Seria uma tolice nos enfrentar.', '', 28153),
(143759, 'ptBR', 'Por Quel\'Thalas.', '', 28153),
(143758, 'ptBR', 'Nós superamos muitos percalços.', '', 28153),
(143757, 'ptBR', 'Nós construímos o nosso futuro com base na tradição.', '', 28153),
(143756, 'ptBR', 'Vá cuidar do seu trabalho.', '', 28153),
(143755, 'ptBR', 'Não deixe que os forasteiros interfiram.', '', 28153),
(143754, 'ptBR', 'Respeite os nossos costumes.', '', 28153),
(143753, 'ptBR', 'O sol eterno ainda nos guia.', '', 28153),
(143752, 'ptBR', 'O que você quer de mim?', '', 28153),
(143751, 'ptBR', 'Eu sirvo a Luaprata.', '', 28153),
(143750, 'ptBR', 'Eu estou muito ocupado.', '', 28153),
(143749, 'ptBR', 'Não desperdice os nossos recursos.', '', 28153),
(143748, 'ptBR', 'O que foi?', '', 28153),
(143747, 'ptBR', 'A Nascente do Sol precisa ser protegida.', '', 28153),
(143746, 'ptBR', 'Aceite isto como agradecimento.', '', 28153),
(143745, 'ptBR', '', 'Planos? Euzinha? Que tipo de planos eu poderia ter?', 28153),
(143744, 'ptBR', '', 'Você acha que eu não vi o jeito como você olha para os meus patrulheiros? Eu sugiro que você mantenha seus olhos e pensamentos consigo mesmo.', 28153),
(143743, 'ptBR', '', 'Eu percebi o seu progresso. Parece que talvez eu tenha que mandar você a Nathanos para um treinamento básico.', 28153),
(143742, 'ptBR', '', 'Sem dúvida que eu sou a sua irmã Correventos favorita... né? Né?', 28153),
(143741, 'ptBR', '', 'O sangue vital de Azeroth pertence à Horda.', 28153),
(143740, 'ptBR', 'Eu comecei a me perguntar se existia mesmo uma criatura assim!', '', 28153),
(143739, 'ptBR', '', 'Nós vamos tomar o que é nosso.', 28153),
(143738, 'ptBR', '', 'No fim, todos servirão à Horda.', 28153),
(143737, 'ptBR', '', 'Eu vou engrossar as fileiras dos Renegados. De um jeito... ou de outro.', 28153),
(143736, 'ptBR', '', 'Vamos deixar a Aliança de joelhos.', 28153),
(143735, 'ptBR', '', 'Sirva à Horda. Sirva a mim.', 28153),
(143734, 'ptBR', 'Ele é lindo!', '', 28153),
(143733, 'ptBR', '', 'Vá. Eu tenho muito a fazer.', 28153),
(143732, 'ptBR', '', 'Sirva-me bem, e a recompensa será justa.', 28153),
(143731, 'ptBR', '', 'Haverá um novo futuro para a Horda.', 28153),
(143730, 'ptBR', '', 'Nosso verdadeiro trabalho está só começando.', 28153),
(143729, 'ptBR', '', 'Saudações, campeão.', 28153),
(143728, 'ptBR', '', 'Aproxime-se.', 28153),
(143727, 'ptBR', '', 'Espero que você não desperdice meu tempo.', 28153),
(143726, 'ptBR', '', 'Diga qual é seu assunto com sua Chefe Guerreira.', 28153),
(143725, 'ptBR', '', 'Os elementos de Zandalar já sofreram demais. Temos que acabar com esse abuso de poder dos xamãs sombrios.', 28153),
(143724, 'ptBR', 'Meu nome é Botelho, e eu sou meio fanático por cavalos.\n\nCorre o boato de que há uma criatura magnífica semelhante a um cavalo a oeste deste resort, em algo como uma montanha. Aceitei este emprego na esperança de poder vê-la.\n\nAh, eu daria qualquer coisa para ver essa maravilha...', '', 28153),
(143721, 'ptBR', 'Afirmativo. Desnecessário estimar posição do Guardião Titânico Hezrel. A caminho de área cuja designação é Zul\'Nazman.', '', 28153),
(143720, 'ptBR', '', 'Hezrel, os trolls sangrentos tão se reunindo em Zul\'Nazman. Se você vai ajudar a gente, é pra lá que você tem que ir.', 28153),
(143719, 'ptBR', 'Me paga um goró aí, $pr.\n\nMeu povo salvou o mundo enquanto vocês fugiam com esse rabinho cotó entre as pernas, pra esconder na neblina.\n\nTu me deve uma birita.', '', 28153),
(143718, 'ptBR', 'Sistemas do Guardião Titânico Hezrel operando a 50% da capacidade. Necessário conservar energia para expurgo de trolls sangrentos.', '', 28153),
(143717, 'ptBR', 'Aqui antigamente era o meu bar. A família real recebia a nobreza do mundo todo, e eu preparava as bebidas pra geral.\n\nAgora é um antro de estrangeiros sujos e gente da pior laia. Quanta desgraça.', '', 28153),
(143716, 'ptBR', 'Eu dou moral pra alguns cartéis goblínicos. Neutros e fortes, disposição pra comprar briga. Que nem os Zandalari... só que bem piores.\n\nMas vocês da Borraquilha são uma desgraça. Tão de amizade com os elfos e a Horda. Bando de vendidos.', '', 28153),
(143715, 'ptBR', 'Sinta meu poder!', '', 28153),
(143714, 'ptBR', 'Eu gosto dos métodos da Horda, $p. Líderes fortes. Propósitos definidos. Abastecimento confiável.\n\nVocês tão recrutando?', '', 28153),
(143713, 'ptBR', 'Estou pronto para buscar nosso próximo aliado.', 'Estou pronta para buscar nosso próximo aliado.', 28153),
(143712, 'ptBR', '', 'Finalmente, as ameaças vazias entre Horda e Aliança se tornarão fatos.$b$bA hora da guerra se aproxima.', 28153),
(143711, 'ptBR', 'Sempre achei esquisito os Lançanegra colarem com a Horda. Vocês não dão conta do recado sozinhos, só pode.\n\nA quantas anda o Vol\'jin?', '', 28153),
(143710, 'ptBR', 'Olha aqui, Sua Elfeza. Esse bar não é mais meu, acabou a falsa simpatia.\n\nDá o pira da minha frente, zé ruela.', '', 28153),
(143709, 'ptBR', 'Essa cara feia é sede? Bebe alguma coisa. Fica aí pra jogar conversa fora.\n\nZuldazar tá na área desde que o mundo é mundo. E não vai acabar tão cedo.', '', 28153),
(143708, 'ptBR', 'Fiquei sabendo que vocês vão pra Nazmir. Se eu fosse vocês, pulava fora desse barco. Nada que presta sai daquele pântano já faz é tempo.', '', 28153),
(143707, 'ptBR', 'Ouvi dizer que o bicho tá pegando nas dunas de Vol\'dun mais do que de costume. Abre teu olho se for pintar por lá.', '', 28153),
(143706, 'ptBR', 'Meu povo levantou a civilização no início dos tempos e vem carregando vocês nas costas até hoje.\n\nDiz aí, $pr, o que a tua gente fez de importante nessa história?\n\nQue eu saiba, nada.', '', 28153),
(143705, 'ptBR', '(Subir nos ombros de Hezrel para retornar ao Bosque da Solidão.)', '(Subir nos ombros de Hezrel para retornar ao Bosque da Solidão.)', 28153),
(143704, 'ptBR', 'Conserto da contenção de G\'huun falhou. Necessário impedir unidades denominadas trolls sangrentos de destruir Zuldazar para impedir libertação de G\'huun.\n\nEstrutura cercada de trolls sangrentos. O Guardião Titânico Hezrel garantirá segurança de $n e da Princesa Talanji.\n\nSubir nos ombros. Manter cabeça baixa.', '', 28153),
(143703, 'ptBR', 'Imundície. Nojeira. Tu fede mais que troll sangrento.\n\nSe esse bar ainda fosse meu, eu te botava pra fora junto com o lixo.', '', 28153),
(143702, 'ptBR', 'O que tu tá sabendo das coisas fora da cidade?', '', 28153),
(143700, 'ptBR', 'Gallywix iniciou operações em Silithus. Vá até lá agora. E, se você vir gente da Aliança se esgueirando pela área, acabe logo com eles.', '', 28153),
(143699, 'ptBR', 'Nós estabelecemos uma base improvisada em Silithus. Fale com nossos operativos por lá, e fique de olhos abertos contra agressões da Horda.', '', 28153),
(143698, 'ptBR', 'Orc é bom de caneco, na moral.\n\nMas manda esses teus amigos élficos darem o pira daqui, beleza?', '', 28153),
(143697, 'ptBR', 'Alleria e Turalyon? Sem chance. Tipo assim... não que eu esteja torcendo contra eles, mas... Hum, a gente tem mesmo que ficar falando nisso?', '', 28153),
(143696, 'ptBR', 'Acho que posso perdoar você por não ser fã dos elfos. Afinal, metade de nós odeia muito a outra metade.', '', 28153),
(143695, 'ptBR', 'Admito, roxo nunca foi a minha cor favorita. Só que, ultimamente, está virando a minha cor. Literalmente.', '', 28153),
(143694, 'ptBR', 'Elfo superior? Fala sério. Pra que ser um elfo superior quando se pode ser todo trágico e dramático?', '', 28153),
(143693, 'ptBR', 'Mantenha o foco e o controle.', '', 28153),
(143692, 'ptBR', 'Não se dobre aos sussurros.', '', 28153),
(143691, 'ptBR', 'Não rejeite as possibilidades.', '', 28153),
(143690, 'ptBR', 'Que as Sombras zelem por você.', '', 28153),
(143689, 'ptBR', 'Nós servimos à Aliança.', '', 28153),
(143688, 'ptBR', 'A Luz não é o único caminho.', '', 28153),
(143687, 'ptBR', 'Os ren\'dorei provarão nosso valor.', '', 28153),
(143686, 'ptBR', 'Eu tenho muito a lhe ensinar.', '', 28153),
(143685, 'ptBR', 'Venha com a mente aberta.', '', 28153),
(143684, 'ptBR', 'Todos os caminhos são possíveis.', '', 28153),
(143683, 'ptBR', 'Nós acolhemos o poder. Não o tememos.', '', 28153),
(143682, 'ptBR', 'As sombras nos servem.', '', 28153),
(143681, 'ptBR', 'Bal\'a dash, malanore.', '', 28153),
(143680, 'ptBR', 'Saudações, viajante.', '', 28153),
(143679, 'ptBR', 'Meu tapa-olho nunca mudou de lado! Tipo... quem ia se confundir com uma coisa assim?', '', 28153),
(143678, 'ptBR', 'Trabalhar para Sylvana é... desafiador. Estar morta deixou ela ainda mais mandona. Mas, hum... não diga a ela que eu disse isso.', '', 28153),
(143677, 'ptBR', 'Campeão da rainha ou não, minha mira é melhor que a do Nathanos.', '', 28153),
(143676, 'ptBR', 'Um cabelo lindão assim não acontece sozinho. Ele exige atenção constante.', '', 28153),
(143675, 'ptBR', 'Nunca mais um rei reinará em Luaprata.', '', 28153),
(143674, 'ptBR', 'Somos uma nação em ascensão.', '', 28153),
(143673, 'ptBR', 'Al diel shala.', '', 28153),
(143672, 'ptBR', 'Nós encontramos força na Horda.', '', 28153),
(143671, 'ptBR', 'Tudo que faço, eu faço por Quel\'thalas.', '', 28153),
(143670, 'ptBR', 'Que a luz da Nascente do Sol esteja convosco.', '', 28153),
(143669, 'ptBR', 'Luaprata conhecerá a prosperidade outra vez.', '', 28153),
(143668, 'ptBR', 'A beleza de Canto Eterno perdura.', '', 28153),
(143667, 'ptBR', 'O sol eterno ainda nos guia.', '', 28153),
(143666, 'ptBR', 'A reconstrução continua.', '', 28153),
(143665, 'ptBR', 'Nós fizemos muitos sacrifícios.', '', 28153),
(143664, 'ptBR', 'Eu me orgulho de servir como Lorde-regente.', '', 28153),
(143663, 'ptBR', 'Bal\'a dash, malanore.', '', 28153),
(143662, 'ptBR', 'Eu saúdo você em nome de Luaprata.', '', 28153),
(143651, 'ptBR', 'Ah, acho que peguei um grande!', '', 28153),
(143650, 'ptBR', 'Hezrel revela que G\'huun é um deus antigo que sofreu experimentos e revela que os trolls sangrentos querem destruir Zuldazar para libertar G\'huun. Impossível consertar contenção atual. Necessário proteger Zuldazar. Ateena, matriarca dos trolls sangrentos, chega, fere gravemente Hezrel e se prepara para atacar.', 'CENA TEMPORÁRIA - Hezrel conta que G\'huun é um deus antigo que sofreu experimentos e revela que os trolls sangrentos querem destruir Zuldazar para libertar G\'huun. Impossível consertar contenção atual. Necessário proteger Zuldazar. Ateena, matriarca dos trolls sangrentos, chega, fere gravemente Hezrel e se prepara para atacar', 28153),
(143649, 'ptBR', '', 'Para trás, $r! A voz dele é minha!', 28153),
(143648, 'ptBR', '', 'Tem tanto... poder... aqui...', 28153),
(143647, 'ptBR', '', 'Cuidado, Umbric. As respostas a tais mistérios podem cobrar um alto preço.', 28153),
(143646, 'ptBR', 'Considere este cubo, por exemplo. É um dispositivo ancestral, talvez mais antigo até que a vida em Azeroth. Parece que está trancado, e ainda não conseguimos abri-lo.', '', 28153),
(143645, 'ptBR', 'Realmente! Como você, nós acreditamos que o Caos pode ser usado para defender a vida, em vez de consumi-la. Nós fizemos grande progresso, Lady Correventos, mas muitos mistérios continuam.', '', 28153),
(143644, 'ptBR', '', 'Outra hora, talvez. Este campeão e eu estávamos procurando você. Nós sabemos do seu exílio de Luaprata e sentimos que temos coisas em comum.', 28153),
(143643, 'ptBR', 'Meu povo e eu ouvimos histórias do que aconteceu em Argus. Como você deve imaginar, nós temos um grande interesse na sua interação com os naarus obscurecidos.', '', 28153),
(143642, 'ptBR', 'Alleria Correventos!? Como foi que... Nossa, que honra inesperada!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143641, 'ptBR', '', 'Magíster Umbric! Eu sou Alleria Correventos.', 28153),
(143640, 'ptBR', '', 'Lá, logo adiante. Aquele deve ser Umbric.', 28153),
(143639, 'ptBR', '', 'Com base nessas anotações, eu acredito que poderei reabrir a passagem para esse mundo que ele mencionou. Deixe-me ver...', 28153),
(143638, 'ptBR', '', '<Pousando de pulo: 3 no total>', 28153),
(143637, 'ptBR', 'Drathir acreditava que este local continha um objeto ancestral de poder indizível. Talvez essa seja a chave que nos permitirá controlar as sombras.', '', 28153),
(143636, 'ptBR', 'Segundo as anotações, o mundo fica dentro de uma fenda no tecido da realidade. Ele nunca encontrou o lugar... mas eu triunfei onde ele fracassou. O caminho logo estará livre para nós!', '', 28153),
(143635, 'ptBR', 'A busca por poder de Drathir o levou a sair atrás dos fragmentos de um mundo antigo, um mundo que se encontrava à beira do caos.', '', 28153),
(143634, 'ptBR', '<Pousando de pulo: 3 no total>', '', 28153),
(143633, 'ptBR', '', 'Vamos. Temos que ir para a Torre Aurestela.', 28153),
(143632, 'ptBR', 'Ainda assim, eu acho que esse conhecimento pode ser usado para o bem. O grosso da pesquisa de Drathir foi feito na Torre Aurestela. É para lá que temos que ir.', '', 28153),
(143631, 'ptBR', 'Foi a traição de Drathir que possibilitou que Arthas corrompesse a Nascente do Sol... deixando nosso reino em ruínas. Agora entendi porque Rommath se opõe aos nossos estudos.', '', 28153),
(143630, 'ptBR', 'Pelo visto, nós não fomos os primeiros do nosso povo a tentar controlar o caos. Eu encontrei os cadernos de um elfo cujo nome se tornou uma maldição... Dar\'Khan Drathir.', '', 28153),
(143629, 'ptBR', '<Pousando de pulo: 3 no total>', '', 28153),
(143628, 'ptBR', '', 'Parece que encontramos algumas anotações.', 28153),
(143627, 'ptBR', '', '<Pousando de pulo: 3 no total>', 28153),
(143626, 'ptBR', 'Infelizmente, parece que a pesquisa chegou a um impasse. Eu acho que existem informações na Propriedade Andilien que podem catapultar a pesquisa.', '', 28153),
(143625, 'ptBR', 'Grão-magíster, é importante compreender que esse poder é crucial para as defesas de Luaprata. Nunca mais os sin\'dorei sofrerão nas mãos dos seus inimigos!', '', 28153),
(143624, 'ptBR', 'Os experimentos com o caos estão fazendo progresso. Devemos estar prestes a fazer uma descoberta... apesar das queixas mesquinhas de Rommath.', '', 28153),
(143623, 'ptBR', '<Pousando de pulo: 3 no total>', '', 28153),
(143622, 'ptBR', '', '<Pousando de pulo: 3 no total>', 28153),
(143621, 'ptBR', '<Grito em apuros: 3 no total>', '', 28153),
(143620, 'ptBR', '<Pousando de pulo: 3 no total>', '', 28153),
(143619, 'ptBR', 'Hezrel, começa a varredura pra encontrar uma solução pra corrupção do deus antigo em Nazmir.', 'Hezrel, começa a varredura pra encontrar uma solução pra corrupção do deus antigo em Nazmir.', 28153),
(143618, 'ptBR', 'Vamos ver se esses peixes estão querendo morder a isca!', '', 28153),
(143617, 'ptBR', '', '<Pousando de pulo: 3 no total>', 28153),
(143616, 'ptBR', '', 'Essa mata já trouxe muita alegria a mim e às minhas irmãs. Ver ela neste estado... enche meu coração de tristeza.', 28153),
(143615, 'ptBR', 'Juntos, mostraremos como estavam errados.', '', 28153),
(143614, 'ptBR', 'Vai levar um tempo para nos ajustarmos a esta nova forma. Nós estaremos à sua espera, Lady Correventos. E $p... ficamos profundamente gratos a você.', '', 28153),
(143613, 'ptBR', '', 'Em troca, eu ajudarei você nas suas jornadas. Eu e você $p transmitiremos as boas novas ao Alto-rei Wrynn. Depois disso, eu volto para dar início ao seu treinamento.', 28153),
(143612, 'ptBR', 'Luaprata nos deu as costas faz tempo. Hoje nós renascemos... e nada mais justo do que seguirmos um novo caminho. De hoje em diante, nossa lealdade pertence à Aliança.', '', 28153),
(143611, 'ptBR', '', 'Eu sinto os poderes sob seu comando. Eles são... consideráveis. Vocês dariam bons aliados para a Aliança.', 28153),
(143610, 'ptBR', 'Minha arrogância quase causou nossa ruína. Eu me meti com poderes muito além do meu controle. Se você nos treinar, Alleria, nós seguiremos as suas ordens.', '', 28153),
(143609, 'ptBR', '', 'Eu autorizei a construção de uma embaixada em Orgrimmar. A partir dela, nós ganharemos mais gente para a nossa causa. Me encontre lá.', 28153),
(143608, 'ptBR', '', 'A liderança inconsequente da Horda na guerra contra a Legião deixou nossas fileiras desbastadas. Nossos inimigos sonham em roubar aquilo que é nosso. Nós não permitiremos isso.', 28153),
(143607, 'ptBR', '', 'Você acompanhou as operações em Silithus, $p. A Aliança está fazendo tudo em seu poder para atrapalhar os nossos objetivos.', 28153),
(143606, 'ptBR', 'É hora da Aliança trazer novos membros para lutar pela nossa causa. Nós estabelecemos uma embaixada em Ventobravo para liderar a empreitada. Me encontre lá.', '', 28153),
(143605, 'ptBR', 'A Horda fará de tudo para dominar o sangue vital de Azeroth. Eu receio que, depois da guerra contra a Legião, nossas fileiras estejam desfalcadas demais para lidar com a investida deles.', '', 28153),
(143604, 'ptBR', 'Você viu com os próprios olhos como Silithus ficou devastada, $p. Você sabe bem o que está em jogo.', '', 28153),
(143603, 'ptBR', 'Me encontre em frente ao Castelo Grommash. Mantenha sigilo absoluto... ou haverá graves consequências.', '', 28153),
(143602, 'ptBR', 'Vieram à luz informações cruciais para os interesses da Horda. Nós temos que permanecer um passo à frente dos nossos rivais.', '', 28153),
(143601, 'ptBR', '$p! A Dama Sombria quer encontrar você em Orgrimmar.', '', 28153),
(143600, 'ptBR', 'Me encontre no Repouso do Leão. Nem preciso dizer que esse assunto fica só entre nós.', '', 28153),
(143599, 'ptBR', 'Nós descobrimos algumas... informações delicadas, e ele faz questão de que você esteja a par de tudo.', '', 28153),
(143598, 'ptBR', '$p, o Alto-rei Wrynn exige a sua presença em Ventobravo.', '', 28153),
(143597, 'ptBR', 'Também vim trazer uma pessoa de longe que quer falar contigo, ó poderoso loa.', '', 28153),
(143596, 'ptBR', '', 'Os filhos da noite são sábios e poderosos. O conhecimento ancestral que vocês possuem será de grande valor para a nossa causa.', 28153),
(143595, 'ptBR', '', 'Chega de cordialidades. Você tem muito a fazer. Aonde quer que leve o seu caminho, lembre-se de que você luta... pela Horda!', 28153),
(143594, 'ptBR', '', 'Fique sabendo que eu tomarei nota dos seus passos. Como Chefe Guerreira, eu espero bastante de você... e sei ser generosa com quem merece.', 28153),
(143593, 'ptBR', '', 'A Horda tem muitos rivais neste mundo. Alguns nos consideram inimigos... outros, párias. Mas nós encontramos força na união... e na rebeldia contra aqueles que ameaçam a nossa liberdade.', 28153),
(143592, 'ptBR', '', 'Os taurens de Alta Montanha são fortes e corajosos. Qualidades que nós precisaremos bastante nos dias por vir.', 28153),
(143591, 'ptBR', '', 'Ah, finalmente eu vou conhecer você, $go jovem herói:a jovem heroína; $p. Me disseram que você tem grande potencial. Tomara que essa impressão se comprove.', 28153),
(143590, 'ptBR', 'Boa viagem, $p. Que a Luz esteja sempre com você.', '', 28153),
(143589, 'ptBR', 'Os elfos caóticos acabaram de entrar nas nossas fileiras, mas Alleria Correventos é uma das nossas maiores heroínas. Sob a tutela dela, vocês ajudarão bastante a nossa causa.', '', 28153),
(143588, 'ptBR', 'Vamos expulsar você destas terras!', '', 28153),
(143587, 'ptBR', 'Boa viagem, $p. Ainda que caminhe entre as sombras, você é o farol da esperança para todos nós.', '', 28153),
(143586, 'ptBR', 'Eu estou ansioso para acompanhar o seu progresso. Algo me diz que nos falaremos de novo em breve.', '', 28153),
(143585, 'ptBR', 'São tempos conturbados para Azeroth. Nos dias por vir, você enfrentará muitas provações... e muitos adversários. Saiba que você jamais estará sozinho contra a escuridão, pois a Aliança estará com você.', '', 28153),
(143584, 'ptBR', 'Os Forjados a Luz acabaram de entrar nas nossas fileiras, mas os draeneis eu conheço bem. Confio em vocês para lutar com a dedicação e a coragem do Exército da Luz.', '', 28153),
(143583, 'ptBR', 'Boas-vindas, $p. Eu sou o Rei Anduin Wrynn. Gosto de cumprimentar os novos membros da Aliança pessoalmente.', '', 28153),
(143582, 'ptBR', 'Eu preciso de cura!', '', 28153),
(143581, 'ptBR', 'Vai arranjar uma serraria pra você!', '', 28153),
(143580, 'ptBR', 'Que cantinho mais obscuro e interessante do mundo a Horda foi arranjar para a gente.\n\nTomara que os outros estabelecimentos da minha facção sejam mais elegantes e limpos do que este...', '', 28153),
(143579, 'ptBR', 'Com licença, $p.\n\nEu adoraria ficar para conversar, mas creio que vou vomitar.\n\nPasse longe do vinho.', '', 28153),
(143578, 'ptBR', '<O Vinheiro Thesnala encara o garçom enquanto derrama o vinho aos pés dele, bem lentamente.>', '', 28153),
(143577, 'ptBR', 'Você já experimentou o vinho?\n\nTem que experimentar. Não dá para acreditar de tão ruim.\n\nOs bardos vão escrever canções sobre aquela textura de chapisco.\n\nÉ um verdadeiro desperdício de uvas, a própria ressaca engarrafada, o passaporte para a sarjeta.', '', 28153),
(143576, 'ptBR', 'Eu confio na capacidade dos Zandalari para construir prédios grandes e feios.\n\nPara fazer vinho, NÃO.', '', 28153),
(143575, 'ptBR', 'Se não é para fazer um vinho honesto, melhor não fazer vinho nenhum.', '', 28153),
(143574, 'ptBR', 'Me compre outra taça de vinho para eu poder cuspir essa porcaria no chão outra vez.', '', 28153),
(143573, 'ptBR', 'Chamam essa lavagem de vinho? Por isso que os trolls estão abandonando a cidade.', '', 28153),
(143572, 'ptBR', 'Finalmente livres! Rápido, vamos embora daqui!', 'Finalmente livres! Rápido, vamos embora daqui!', 28153),
(143571, 'ptBR', 'Essas abominações de madeira parecem que saíram de um pesadelo!', '', 28153),
(143569, 'ptBR', 'Vou querer um... adicional de periculosidade...', 'Vou querer um... adicional de periculosidade...', 28153),
(143568, 'ptBR', '', 'Mesmo devastado como está, esse lugar me parece familiar...', 28153),
(143567, 'ptBR', 'Quero ver esforço, seus sacos de batatas inúteis!', 'Quero ver esforço, seus sacos de batatas inúteis!', 28153),
(143566, 'ptBR', 'Interior da estrutura sob controle. Ser designado \"Princesa Talanji\" incorporado ao grupo.', '', 28153),
(143565, 'ptBR', 'A ordem foi dada. Nós vamos para Corlain!', '', 28153),
(143562, 'ptBR', 'Tarde demais. É impossível conter G\'huun. Todos sucumbirão. Todos morrerão.', '', 28153),
(143561, 'ptBR', 'Seu fim se aproxima. G\'huun será libertado. Azeroth será nossa.', '', 28153),
(143560, 'ptBR', 'Põe seus itens de valor no cofre e segue em frente, $p.\n\nTô de olho em você...', '', 28153),
(143559, 'ptBR', 'São tempos sombrios para Drustvar, mas nós tomaremos nossa terra de volta!', '', 28153),
(143558, 'ptBR', 'Por Zandalar!', '', 28153),
(143557, 'ptBR', 'Vamos à caça, Rezan.', '', 28153),
(143556, 'ptBR', 'Tenho. Nós partiremos ao sinal da continental.', '', 28153),
(143555, 'ptBR', 'Pa\'kul, loa dos ventos, suba aos céus e procure os hereges. Descubra os planos deles e nos encontre no templo.', '', 28153),
(143554, 'ptBR', 'Gonk, loa da caça, lidere teus seguidores até o Templo do Profeta e mate quem cruzar o teu caminho. Expulse nossos inimigos de lá.', '', 28153),
(143553, 'ptBR', 'Irmãos e irmãs de Zandalar, chegou a hora de cortar a cabeça desses traidores que juraram lealdade a Zul.', '', 28153),
(143552, 'ptBR', '', 'Enquanto isso, nós vamos nos preparando para a expedição a Corlain. Marechal, o senhor tem um plano de ataque, não tem?', 28153),
(143551, 'ptBR', '', 'Sim, senhora!', 28153),
(143550, 'ptBR', '', 'Leve essa receita de fogo alquímico ao Mestre Azinhal, na Mata do Falcão. Ele vai saber o que fazer.', 28153),
(143549, 'ptBR', '', 'Felizmente, eu conheço um especialista em alquimia na Mata do Falcão, ao sul. A mata é traiçoeira, então é melhor ir pela estrada velha das montanhas.', 28153),
(143548, 'ptBR', '', 'Tem uma receita de fogo alquímico no tomo, mas ninguém aqui dá conta de fazer direito.', 28153),
(143547, 'ptBR', '', 'Se quisermos derrotar o conventículo para valer, só prata não adianta. Vamos precisar de fogo.', 28153),
(143546, 'ptBR', '', 'Obrigada, senhor! Como posso lhe servir, milady?', 28153),
(143545, 'ptBR', 'A Capitã Claralvor... Perdão, a Inquisidora Claralvor é de total confiança. Tenho certeza absoluta que ela dá conta do recado.', '', 28153),
(143544, 'ptBR', '', 'Recomenda alguém, Marechal?', 28153),
(143543, 'ptBR', '', 'Antes de partirmos, eu preciso que alguém cuide de uma tarefa especial para a Ordem.', 28153),
(143542, 'ptBR', 'Você acredita que a Horda nunca teve uma secretaria pública de telemancia? Eu não faço ideia de como faziam para garantir a segurança dos viajantes. Só de pensar naquele tanto de portais rasgando o tecido da realidade sem nenhuma ancoragem...\n\nBom, de qualquer forma, fico feliz de poder oferecer uma rede de teleporte estável para a Horda. Queira seguir adiante.', '', 28153),
(143540, 'ptBR', 'O povo da minha cidade é forte, mas isso está testando nossos limites.', '', 28153),
(143539, 'ptBR', '', 'Afoguem os insetos, minhas crianças. Mostrem que são dignas do meu orgulho.', 28153),
(143537, 'ptBR', 'Brgl! Brglrgl!', '', 28153),
(143536, 'ptBR', 'Mrgl, mrglrglrgl! Mrrrg! Mrrrg!!', '', 28153),
(143531, 'ptBR', 'Arrombando', 'Arrombando', 28153),
(143530, 'ptBR', 'Tá pra você, jovem! Sobe aí!', '', 28153),
(143529, 'ptBR', 'Tem coisa errada no Garra de Rezan. A gente põe um batedor voando perto do acampamento.', '', 28153),
(143523, 'ptBR', 'Me dá seu ouro. Eu tenho uma conferência de acionistas em cinco minutos!', '', 28153),
(143520, 'ptBR', 'Estou pronto para aplicar a essência sintética de G\'huun em mim.', 'Estou pronta para aplicar a essência sintética de G\'huun em mim.', 28153),
(143519, 'ptBR', 'Rei Da\'ka! Ele achou a gente! Socorro!', '', 28153),
(143518, 'ptBR', 'Vocês... perderam? Para eles? Patético! Apresentem-se na Cidade Baixa para o treinamento de reforço. Pelo jeito vamos ter que recomeçar do zero...', '', 28153),
(143517, 'ptBR', 'Isso passou longe de ser uma vitória elegante, mas pelo menos vocês colocaram os cães da Aliança no devido lugar. Pela Horda!', '', 28153),
(143516, 'ptBR', 'Isso é cheiro de... worgen? É difícil ter certeza nesse fedor insuportável de soberba da Aliança.', '', 28153),
(143515, 'ptBR', 'Derrubem eles! Vocês NÃO VÃO gostar nada se a Chefe Guerreira ficar decepcionada!', '', 28153),
(143514, 'ptBR', 'A Aliança chama isso de soldado? Miseráveis! A criatura mal consegue segurar a espada!', '', 28153),
(143513, 'ptBR', 'Fogo! Não deixem um sequer desses desgraçados vivos!', '', 28153),
(143512, 'ptBR', 'Diabos! Ainda tem mais azerita para recolher. Sigam o mapa e dominem os pontos marcados!', '', 28153),
(143511, 'ptBR', 'Aconteceram mais erupções de azerita neste inferno de ilha! Confira no seu mapa.', '', 28153),
(143510, 'ptBR', 'Quase lá. Sem fraquejar. Mais azerita!', '', 28153),
(143509, 'ptBR', 'Ha! Arrancamos o negócio das mãos da Aliança! Bem jogado!', '', 28153),
(143508, 'ptBR', 'O resultado foi aceitável, mas precisamos de mais azerita!', '', 28153),
(143507, 'ptBR', 'Vão buscar os suprimentos, se for preciso. Mas sem perder de vista o prêmio da Rainha Banshee!', '', 28153),
(143506, 'ptBR', 'Suprimentos a caminho. Eu acho bom vocês recolherem tudo antes da Aliança!', '', 28153),
(143505, 'ptBR', 'Ali embaixo... azerita! Peguem tudo para a Chefe Guerreira. Se a Aliança entrar no caminho, empilhem seus corpos pela praia. Andem logo!', '', 28153),
(143504, 'ptBR', 'Vejamos o que temos aqui. Argh... patético! Por que não mandaram os patrulheiros sombrios? É, vou ter que me contentar com vocês.', '', 28153),
(143503, 'ptBR', 'Embarcação da Aliança! Aqueles cachorros não largam nossos calcanhares. Aos seus postos de batalha!', '', 28153),
(143502, 'ptBR', 'Nossa missão aqui é simples. Recolher cada pedacinho de azerita e não deixar nada para a Aliança. Nada muito difícil de entender.', '', 28153),
(143501, 'ptBR', 'Campeões da Horda! Nós encontramos depósitos de azerita numa ilhota miserável, perto da costa de Feralas. É nosso dever tomá-la em nome da Dama Sombria!', '', 28153),
(143500, 'ptBR', 'Mandem eles embora! A ilha é nossa!', '', 28153),
(143499, 'ptBR', 'Lutem pelo rei! Lutem pela Aliança!', '', 28153),
(143498, 'ptBR', 'Essa Horda se acha muito espertinha. Dê uma lição neles!', '', 28153),
(143497, 'ptBR', 'Fogo! Eliminem os curadores!', '', 28153),
(143496, 'ptBR', 'Vocês parecem duros na queda. Hum... eu precisava era de uns ladinos, na verdade... mas podem ser vocês mesmo!', '', 28153),
(143495, 'ptBR', 'Droga! A Horda saiu na frente desta vez. Mas eu juro pelo Repouso do Leão que a vitória ainda será nossa!', '', 28153),
(143494, 'ptBR', 'Muito bem feito, campeões! O Rei Wrynn ficará feliz de saber da nossa vitória. Pela Aliança!', '', 28153),
(143493, 'ptBR', 'Suprimentos chegando! Recolham tudo, campeões!', '', 28153),
(143492, 'ptBR', 'Mais erupções de azerita! Localize os pontos no mapa e tome todos para nós!', '', 28153),
(143491, 'ptBR', 'Vocês fizeram um bom trabalho. Só um pouquinho mais de azerita e pronto!', '', 28153),
(143490, 'ptBR', 'Vocês não deixaram a Horda chegar perto dessa azerita. Bom trabalho!', '', 28153),
(143489, 'ptBR', 'Vocês estão indo bem, heróis. Mas nós precisamos de mais azerita!', '', 28153),
(143488, 'ptBR', 'Heróis! Nós vamos jogar suprimentos para vocês. Não deixem a Horda botar as mãos neles!', '', 28153),
(143487, 'ptBR', 'Nós localizamos mais erupções de azerita em volta da ilha! Os pontos estão marcados no seu mapa.', '', 28153),
(143486, 'ptBR', 'Tem um bom depósito de azerita abundante aqui embaixo, heróis. Desçam lá para recolher tudo que puderem. E se os brutos da Horda entrarem na frente... acabem com eles!', '', 28153),
(143485, 'ptBR', 'Embarcação da Horda se aproximando! Sem dúvida eles seguiram a gente. Aos seus postos!', '', 28153),
(143484, 'ptBR', 'Nós trouxemos o navio para o meio da ilha. Recolham o máximo de azerita possível. É assim que vamos vencer!', '', 28153),
(143483, 'ptBR', 'Campeões, nós localizamos depósitos de azerita numa ilha perto da costa de Feralas. Temos que tomá-los antes que a Horda o faça.', '', 28153),
(143482, 'ptBR', '', 'Seria uma honra, Lady Liadrin. Oculeth tem as coordenadas para a sua capital. Eu reunirei Silgryn e Valtrois para encontrar você em Luaprata.', 28153),
(143481, 'ptBR', '', 'Com certeza o Lorde-regente vai gostar de saber do seu interesse. Vamos partir?', 28153),
(143480, 'ptBR', '', 'É por isso que recebi o convite para ir a Luaprata com gratidão. Eu gostaria de saber se existe lugar para os filhos da noite na Horda.', 28153),
(143479, 'ptBR', '', 'A Aliança é muito encastelada... enclausurada demais. Meu povo não vai suportar tamanha estagnação outra vez.', 28153),
(143478, 'ptBR', '', 'Tyrande e seu povo orgulhoso zombam dos sin\'dorei. Porém, por muitas eras eles hibernaram em tocas e se esconderam nas árvores, enquanto meu povo lutava para salvar este o mundo.', 28153),
(143477, 'ptBR', '', 'Pelo visto a \"sabedoria de Eluna\" a afastou dos laços que nos uniam. Que assim seja.', 28153),
(143476, 'ptBR', '', 'Os kaldorei lutarão até que a Legião tenha sido derrotada e a Nascente da Noite, destruída. Depois disso... veremos até onde a sabedoria de Eluna nos guiará.', 28153),
(143475, 'ptBR', '', 'Não queremos nos tornar escravos da Nascente da Noite. Queremos expulsar a Legião de Suramar e acabar com a opressão de Elisande.', 28153),
(143474, 'ptBR', '', 'Arcanista Thalyssra. Eu me lembro da sua posição na Guerra dos Antigos. Como vamos saber se você não nos trairá e se tornará a próxima Elisande... a próxima Azshara?', 28153),
(143473, 'ptBR', '', 'Imaginei que os nossos primos de Kalimdor dariam bons aliados. Porém sua arrogância e desconfiança logo mostraram o contrário.', 28153),
(143472, 'ptBR', '', 'Eu admito que, quando ouvi falar na Horda, não achei que fôssemos ter tanta coisa em comum.', 28153),
(143471, 'ptBR', '', 'A Horda lutou ao seu lado, contra a Legião Ardente, com orgulho, milady.', 28153),
(143470, 'ptBR', '', 'Nós estamos em grande dívida com vocês. Vocês foram fundamentais para a nossa causa.', 28153),
(143469, 'ptBR', '', 'É bom ver sua cidade livre, Primeira Arcanista.', 28153),
(143468, 'ptBR', '', 'Saudações, Lady Liadrin e $p. $GBem-vindos:Bem-vindas; de volta a Suramar. Fico feliz por $Grecebê-los:recebê-las; em circunstâncias mais agradáveis.', 28153),
(143467, 'ptBR', '', 'Decepcionante, mas esperado... Você não recebeu a bênção dos loas, criança. Não vai se juntar a nós no Terraço dos Escolhidos.', 28153),
(143466, 'ptBR', 'Bom, você realmente viajou um bocado para me ver, jovem.$b$bEu tenho vários romances sobre a história dos caranguejos. É isso que você procura?', '', 28153),
(143465, 'ptBR', '', 'Resistência e orgulho, qualidades para vencer inimigos e tempestades. Vamos precisar da sua força para defender nossa cidade.', 28153),
(143464, 'ptBR', '', 'Isso é... muito estranho. Vamos precisar da sua força no futuro próximo.', 28153),
(143463, 'ptBR', '', 'Egoísta e desonrad$Go:a;... É melhor buscar outro caminho, pequenin$Go:a;.', 28153),
(143462, 'ptBR', '', 'Interessante... Furtividade e sagacidade, você ataca das sombras. A surpresa será sua maior arma.', 28153),
(143461, 'ptBR', '', 'Entendi. Você é rápid$Go:a; e observado$Gr:ra;, certeir$Go:a; nos golpes. Sua paciência será recompensada.', 28153),
(143460, 'ptBR', '', 'Busque lá no fundo, criança. Me mostre como caça sua presa. Com sabedoria, força ou algo completamente distinto?', 28153),
(143459, 'ptBR', '', 'O chamado da matilha afeta você pra valer. Abrace os laços dessa irmandade e vá caçar com seus irmãos e irmãs.', 28153),
(143458, 'ptBR', 'Está sentindo esse cheiro? É cheiro de repolho.$b$b<Kronah se aproxima e cheira você.>$b$bNão é você, mas é alguma coisa aqui. $b$bMe diga: como anda sua caligrafia? Quer ter umas aulas? Eu sou mestre-escriba, acredite ou não.', '', 28153),
(143457, 'ptBR', 'Estamos sendo atacados!', 'Estamos sendo atacados!', 28153),
(143456, 'ptBR', 'Peguem suas lâminas, irmãos e irmãs!', 'Peguem suas lâminas, irmãos e irmãs!', 28153),
(143455, 'ptBR', 'Há inimigos entre nós!', 'Há inimigos entre nós!', 28153),
(143454, 'ptBR', 'Intrusos! Às armas!', 'Intrusos! Às armas!', 28153),
(143452, 'ptBR', 'Com prazer.', '', 28153),
(143451, 'ptBR', 'Mexa-se!', '', 28153),
(143450, 'ptBR', 'Temos que atender às solicitações!', '', 28153),
(143449, 'ptBR', '', 'Por favor, não distraia as crianças.\n\nEu estou testando sinais de conexão com os loas. As crianças que tiverem sido abençoadas por algum loa vão receber formação sacerdotal, com todas as honras e privilégios.\n\nAs outras terão oportunidade de ser grandes guerreiras algum dia.\n\nAs que forem reprovadas nesses dois testes não têm serventia. Vão acabar batendo carteira nas docas ou mendigando no Zocalo.', 28153),
(143448, 'ptBR', 'Posso fazer isso.', '', 28153),
(143447, 'ptBR', 'Tá bom.', '', 28153),
(143446, 'ptBR', 'Trabalho, trabalho.', '', 28153),
(143445, 'ptBR', 'Precisamos de mais madeira!', '', 28153),
(143444, 'ptBR', 'Você vai descansar quando morrer. Até lá, temos que atender às solicitações!', '', 28153),
(143443, 'ptBR', 'Eu vou voltar ao vilarejo agora mesmo, antes que tudo desapareça. Talvez eles ainda não tenham se esquecido de mim.', '', 28153),
(143442, 'ptBR', 'Eu não posso voltar a viver como antes. Como um símio boçal. Não depois do que vi e senti, ainda que breve.', '', 28153),
(143441, 'ptBR', 'Da\'ka tinha razão. Minha mente já está voltando ao seu estado primitivo.', '', 28153),
(143440, 'ptBR', 'Oi, viajante. Você gosta de pergaminhos?$b$bOu quem sabe de tintas raríssimas, feitas de plantas exóticas?', '', 28153),
(143439, 'ptBR', 'Mas miolo de goblin é menor que paciência de carneiro. Tu vai ter que sentar o laço em mais uns cem pra lição ficar bem ensinadinha.', '', 28153),
(143438, 'ptBR', 'Tu ensinou direitinho pra esses goblins o que acontece quando alguém se mete com os anões Ferro Negro!', '', 28153),
(143437, 'ptBR', 'Quebra as máquinas! Arrebenta com as ferramentas! Pisa em todas as coisinhas verdes que aparecerem na frente!', '', 28153),
(143436, 'ptBR', 'Os goblins tão corrompendo a azerita às pampas! A gente não pode deixar isso assim!', '', 28153),
(143435, 'ptBR', 'O Inimigo de Ferro finalmente tá ao nosso alcance. Ensina pra essa goblinada o que acontece com quem rouba dos Ferro Negro!', '', 28153),
(143434, 'ptBR', 'Quem tá aí? Quem apagou neblina? Rei Da\'ka vai te matar!', '', 28153),
(143433, 'ptBR', 'Pela Horda!', 'Pela Horda!', 28153),
(143432, 'ptBR', 'Tikinha encara os porcos com voracidade.', '', 28153),
(143431, 'ptBR', 'Tikinha se agita, bem sapeca.', '', 28153),
(143430, 'ptBR', '', 'Quem é a raptorzinha mais zangada, virada no capiroto? Você! É você!', 28153),
(143429, 'ptBR', '', 'Oh, que bom vê-$Ulo:la; novamente, pequenin$Uo:a;! $n... Obrigada.', 28153),
(143428, 'ptBR', '', 'Essa é a Tika?!?!', 28153),
(143427, 'ptBR', 'Tikinha solta um trinado alegre.', '', 28153),
(143426, 'ptBR', '', 'Haverá... outros...', 28153),
(143425, 'ptBR', '', 'O sol se põe no império Zandalari. Os Ímpios tomarão o que restar!', 28153),
(143424, 'ptBR', 'Vou mandar arrancar sua pele!', 'Vou mandar arrancar sua pele!', 28153),
(143423, 'ptBR', 'Tikinha sente o vento com o focinho. Ela solta um uivo.', '', 28153),
(143422, 'ptBR', 'De joelhos perante a rainha!', 'De joelhos perante a rainha!', 28153),
(143421, 'ptBR', 'Ela também... há de te levar...', 'Ela também... há de te levar...', 28153),
(143420, 'ptBR', 'A Casa Trovamare vai governar esta terra!', 'A Casa Trovamare vai governar essa terra!', 28153),
(143419, 'ptBR', '', 'Obrigada pela ajuda, vocês dois! $n, se prepara pra ir na caverna do Cauda-triste pra ajudar o Ben\'jin quando isso funcionar.', 28153),
(143418, 'ptBR', '', 'Eu poderia desenvolver um dispositivo para ler a atividade cerebral dos brutossauros e analisar isso. Tô só dizendo mesmo.', 28153),
(143417, 'ptBR', '', 'A ciência é a única resposta, Jangalar. Eu não tenho intenção de denegrir seus poderes, mas a charlatanice nunca vai substituir uma alquimia racional e agressiva.', 28153),
(143416, 'ptBR', 'Vamos mostrar a esses humanos fracotes a força da Horda!', '', 28153),
(143415, 'ptBR', 'Esses humanos deviam morrer de medo antes mesmo de nossas lâminas encostarem neles!', '', 28153),
(143414, 'ptBR', 'Pela Horda!', '', 28153),
(143413, 'ptBR', 'Eu vou voltar pra Zuldazar... Não esquenta comigo, eu sei me cuidar. Aparece pra me ver da próxima vez que tu der as caras na cidade.', '', 28153),
(143412, 'ptBR', 'Espera, Jin\'Tiki. Leva o raptor. Parece que ele... curte mais você do que eu.', '', 28153),
(143411, 'ptBR', 'Fique de olho! Não quero esses humanos chafurdando perto da nossa serraria!', '', 28153),
(143410, 'ptBR', 'Mantenham o ritmo!', '', 28153),
(143409, 'ptBR', 'Parece que o serviço aqui acabou. Tá na hora de eu voltar pra Vol\'dun pra pagar pelos meus crimes.', '', 28153),
(143408, 'ptBR', 'Se eu pegar alguém dormindo no serviço, eu mesmo vou jogar para os lobos!', '', 28153),
(143407, 'ptBR', 'Continue trazendo esses recursos!', '', 28153),
(143404, 'ptBR', 'Sua ruína... se aproxima...', 'Sua ruína... se aproxima...', 28153),
(143403, 'ptBR', 'Como... pode ser...', 'Como... pode ser...', 28153),
(143402, 'ptBR', '', 'Junta tuas feras e segue pra cidade. Vou te trazer uma cesta de cabeças de cobras quando a gente terminar!', 28153),
(143401, 'ptBR', 'A tempestade... há de cair...', 'A tempestade... há de cair...', 28153),
(143400, 'ptBR', 'Seu fim... há de chegar...', 'Seu fim... há de chegar...', 28153),
(143399, 'ptBR', 'Ali. É dali que saem as brumas que vêm das profundezas.', '', 28153),
(143398, 'ptBR', 'Minha alma... corre para o mar...', 'Minha alma... corre para o mar...', 28153),
(143397, 'ptBR', 'Parto agora... mar adentro...', 'Parto agora... mar adentro...', 28153),
(143396, 'ptBR', 'Eles mataram nosso Chefe! O vilarejo já era!', '', 28153),
(143395, 'ptBR', 'O duto principal fica lá dentro. Vem rápido!', '', 28153),
(143394, 'ptBR', 'De volta... às profundezas...', 'De volta... às profundezas...', 28153),
(143391, 'ptBR', 'Até a maré mais intensa... recua...', 'Até a maré mais intensa... recua...', 28153),
(143390, 'ptBR', 'O poder dela corre em minhas veias!', 'O poder dela corre em minhas veias!', 28153),
(143389, 'ptBR', 'Aceite seu fim!', 'Aceite seu fim!', 28153),
(143388, 'ptBR', 'Os tentáculos da ruína levarão a todos!', 'Os tentáculos da ruína levarão a todos!', 28153),
(143387, 'ptBR', 'Restará apenas sua carcaça à deriva!', 'Restará apenas sua carcaça à deriva!', 28153),
(143386, 'ptBR', 'O ar lhe faltará, e sua luz se apagará!', 'O ar lhe faltará, e sua luz se apagará!', 28153),
(143385, 'ptBR', 'Ninguém pode impedir a maré infinda!', 'Ninguém pode impedir a maré infinda!', 28153),
(143384, 'ptBR', 'Ouçam o chamado das profundezas!', 'Ouçam o chamado das profundezas!', 28153),
(143383, 'ptBR', 'O mar há de carregar vocês!', 'O mar há de carregar vocês!', 28153),
(143382, 'ptBR', 'Assim cai... o Rei Da\'ka.', '', 28153),
(143381, 'ptBR', '', 'Mas... me prometeram... a glória...', 28153),
(143380, 'ptBR', 'Algoz! Tu és como a vela, cuja função é ser extinta.', '', 28153),
(143379, 'ptBR', '', 'Você é forte, mas tombará como todos que enfrentam o conventículo!', 28153),
(143378, 'ptBR', '', 'Tanto faz. Sua descoberta morrerá junto com você. Ao ataque, minhas feras!', 28153),
(143377, 'ptBR', '', 'Então você descobriu a gente. Deve estar se achando o tal.', 28153),
(143376, 'ptBR', 'Ha! De que adianta inteligência se ela não traz poder? Eu vou ser o Rei de Zandalar. E, quem ficar no meu caminho, vai pra vala!', '', 28153),
(143375, 'ptBR', 'Alguém tem que deter você, Da\'ka. Nossa inteligência não devia nem existir, e muito menos causar uma guerra!', '', 28153),
(143374, 'ptBR', 'Tsunga... tu trouxe uma criatura inferior aqui, pras brumas sagradas. O que você quer?', '', 28153),
(143373, 'ptBR', 'O que está acontecendo aqui?', 'O que está acontecendo aqui?', 28153),
(143372, 'ptBR', 'Eu vi a verdade... nas profundezas...', 'Eu vi a verdade... nas profundezas...', 28153),
(143371, 'ptBR', 'Meu sangue... é o sangue da maré...', 'Meu sangue... é o sangue da maré...', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143370, 'ptBR', 'Vai, a origem da neblina tá dentro da caverna. Não sei bem onde o Rei Da\'ka tá. Anda logo!', '', 28153),
(143369, 'ptBR', 'A magia de sangue é forte aqui. Nem precisa ser mandingueiro pra sentir a parada no ar... em todo lugar...', '', 28153),
(143368, 'ptBR', '', 'Ah... O que traz você aqui, continental?\n\nPosso ajudar de alguma forma?', 28153),
(143367, 'ptBR', 'Quem tu quer ver morto?', '', 28153),
(143366, 'ptBR', 'Taz\'dingo!', '', 28153),
(143365, 'ptBR', 'Pela Horda!', '', 28153),
(143364, 'ptBR', 'Hora de matar!', '', 28153),
(143363, 'ptBR', 'Matar é mole.', '', 28153),
(143362, 'ptBR', 'Nada de piedade!', '', 28153),
(143361, 'ptBR', 'Cabeças vão rolar!', '', 28153),
(143360, 'ptBR', 'Glória à Horda!', '', 28153),
(143359, 'ptBR', '', 'Glória à Horda!', 28153),
(143358, 'ptBR', '', 'Cabeças vão rolar!', 28153),
(143357, 'ptBR', '', 'Nada de piedade!', 28153),
(143356, 'ptBR', 'Nós nunca... descansaremos...', 'Nós nunca... descansaremos...', 28153),
(143355, 'ptBR', 'Minha morte não... significa nada...', 'Minha morte não... significa nada...', 28153),
(143354, 'ptBR', 'Nós já... vencemos...', 'Nós já... vencemos...', 28153),
(143353, 'ptBR', '', 'Matar é mole.', 28153),
(143352, 'ptBR', 'Eu só estava... seguindo ordens...', 'Eu só estava... seguindo ordens...', 28153),
(143351, 'ptBR', 'Sábios das Marés... me salvem...', 'Sábios das Marés... me salvem...', 28153),
(143350, 'ptBR', 'Minha vida... pelo mar...', 'Minha vida... pelo mar...', 28153),
(143349, 'ptBR', 'Kul Tiraz pertence ao mar!', 'Kul Tiraz pertence ao mar!', 28153),
(143348, 'ptBR', 'Como ousa desafiar a Casa Trovamare?', 'Como ousa desafiar a Casa Trovamare?', 28153),
(143347, 'ptBR', 'Somos mais inclementes que o mar!', 'Somos mais inclementes que o mar!', 28153),
(143346, 'ptBR', 'Quem ficar no nosso caminho vai morrer!', 'Quem ficar no nosso caminho vai morrer!', 28153),
(143345, 'ptBR', 'Nossa frota vai esmagar você!', 'Nossa frota vai esmagar você!', 28153),
(143344, 'ptBR', '', 'Hora de matar!', 28153),
(143343, 'ptBR', '', 'Vem ni mim, doidona!', 28153),
(143342, 'ptBR', 'Sem nós, Kul Tiraz vira comida de peixe!', 'Sem nós, Kul Tiraz vira comida de peixe!', 28153),
(143341, 'ptBR', '', 'Vem ni mim, filhão!', 28153),
(143340, 'ptBR', 'Este vale é nosso, ratazana!', 'Este vale é nosso, ratazana!', 28153),
(143339, 'ptBR', 'Em nome de Trovamare!', 'Em nome de Trovamare!', 28153),
(143338, 'ptBR', '', 'Quantos sauros mortos... eu criei eles desde o ovo. É como ver meus filhos mortos.$b$bEsses homens cobra vão pagar.', 28153),
(143337, 'ptBR', 'Corrupção descomunal ao redor da estrutura próxima. Ação imediata requerida.', '', 28153),
(143336, 'ptBR', 'Restauração parcial bem-sucedida. É preciso continuar adiante para reparar contenção de corrupção.', '', 28153),
(143335, 'ptBR', 'Aprimorando sistemas auxiliares. Por favor, aguarde...', '', 28153),
(143334, 'ptBR', 'Você conserta equipamentos?', 'Você conserta equipamentos?', 28153),
(143333, 'ptBR', 'O vilarejo já era, mas, a minha forja, só tiram passando por cima do meu cadáver.', '', 28153),
(143332, 'ptBR', '', 'Pela Horda!', 28153),
(143331, 'ptBR', '', 'Taz\'dingo!', 28153),
(143330, 'ptBR', '', 'Quem tu quer ver morto?', 28153),
(143329, 'ptBR', 'Os inocentes estão a salvo, mas ainda há muito a ser feito.', '', 28153),
(143328, 'ptBR', '', 'Só ouço histórias e mais histórias de Ventobravo. Acho que vou até lá explorar todas essas ruas e maravilhas. Que as sombras guiem seu caminho, $n.', 28153),
(143327, 'ptBR', 'Que a luz esteja contigo, $n. Meu plano é caçar a Legião em Azeroth para dar continuidade à nossa eterna batalha.', '', 28153),
(143326, 'ptBR', 'Não, é óbvio que eu não vou fazer isso... Mas eu quaaaase pensei no assunto!', '', 28153),
(143325, 'ptBR', 'Olha, tenho que admitir. Eu quase cogitei dar uma fatiazinha dos lucros pra vocês.', '', 28153),
(143324, 'ptBR', 'Ótimo trabalho! Agora a parte nobre da aventura... Assinar todos os papéis e passar a mina pro meu nome. Tudo carimbado e autenticado.', '', 28153),
(143323, 'ptBR', 'Mas, é sério, acho melhor vocês destruírem todos eles antes que me causem prejuízo.', '', 28153),
(143322, 'ptBR', 'Objetivo concluído. Movimentação à frente. Entregar conclusão em nova localização.', '', 28153),
(143321, 'ptBR', 'Eita! Olha só como eles foram esmagados! Esses elementais são duros na queda.', '', 28153),
(143320, 'ptBR', 'Tikinha chia baixinho em tom de ameaça.', '', 28153),
(143319, 'ptBR', 'Tikinha pia com aflição!', '', 28153),
(143318, 'ptBR', 'O mundo está sangrando, e vocês ainda abrem mais a ferida?! Morram!', '', 28153),
(143317, 'ptBR', 'Eu quero ver explosões, caos, violência pra dar e vender! Tá ligado? Esse lance que só você sabe fazer.', '', 28153),
(143316, 'ptBR', 'Mostre a esses filhinhos de papai da Empreendimentos S.A. que não existe nada que eu não possa tomar.', '', 28153),
(143315, 'ptBR', 'Só tem um probleminha... Era pra ser tudo meu! E é aí que você entra.', '', 28153),
(143314, 'ptBR', 'Então é daqui que vem todo o contrabando de azerita, é? Nada mal... Nada mal mesmo.', '', 28153),
(143313, 'ptBR', '', 'Não sei o que é essa tal de \"mataworg\", mas... Espere, o que é isso?', 28153),
(143312, 'ptBR', 'Sua bondade era demais para este mundo, irmão. Eu lhe darei um enterro digno.', '', 28153),
(143311, 'ptBR', 'Eu adoro o cheiro de mojo pela manhã!', '', 28153),
(143310, 'ptBR', '', 'Rokhan disse que você tem experiência em lidar com esse tipo de coisa. Faça o que for possível. Eu vou ficar aqui, esperando o G.O.P.E.', 28153),
(143308, 'ptBR', '', '$n, nós vamos precisar de aliados. Vá ajudar o guardião assim que puder.', 28153),
(143307, 'ptBR', 'Auxílio requerido. Reparar Hezrel. Chegar ao interior da estrutura próxima. Conter toda a corrupção em Nazmir.', '', 28153),
(143306, 'ptBR', 'Corrupção descomunal detectada em Nazmir. Aplicação de contenção necessária.', '', 28153),
(143305, 'ptBR', 'Eu já lutei muito... mas nunca vi um monstro como esse... na vida...', '', 28153),
(143304, 'ptBR', 'Você nunca vai me pegar vivo!', '', 28153),
(143303, 'ptBR', 'Tá bom, Vol\'dun deve ser mais segura que aqui!', '', 28153),
(143302, 'ptBR', 'Não! Não! Os raptores... vão me comer!', '', 28153),
(143301, 'ptBR', 'Valeu, Zaluto. Talvez, numa outra vida, a gente podia ter sido irmão.', '', 28153),
(143300, 'ptBR', 'Usa o fetiche de sangue no Zulajin pra absorver o poder dele e despachar aquele encosto pra cova!', '', 28153),
(143299, 'ptBR', 'Sem estresse, cara! Eu cuido do capitão aqui enquanto você faz a limpa nas ruínas!', '', 28153),
(143298, 'ptBR', 'Tá bom! Agora bota a camuflagem e pega a chave!', '', 28153),
(143297, 'ptBR', 'Você vai precisar de um disfarce pra passar por Zulajin. Volte logo que pegar os suprimentos!', '', 28153),
(143296, 'ptBR', 'Eu sou bandido, mas não sou malvado. Não vou te deixar aqui pra morrer!', '', 28153),
(143295, 'ptBR', 'Por causa de você, se eu morrer... vai ser com a minha honra intacta...', '', 28153),
(143294, 'ptBR', 'Aqui! Aqui! Um brinde $Gao:à; $Gbravo:brava; $Gcampeão:campeã; que nos salvará!', '', 28153),
(143293, 'ptBR', '', 'Vá para Orgrimmar. Junte-se aos nossos aliados para forjar um novo futuro.', 28153),
(143292, 'ptBR', '', 'Enquanto percorre as estradas de Azeroth, conte a história dos filhos da noite àqueles com quem cruzar... e mostre a eles que nós não vivemos mais em reclusão.', 28153),
(143291, 'ptBR', 'O que nós sabemos sobre os filhos da noite?', 'O que nós sabemos sobre os filhos da noite?', 28153),
(143290, 'ptBR', '', '$n, que bom que você está aqui. Temos que convencer a chefe guerreira a buscar uma aliança com os filhos da noite.', 28153),
(143289, 'ptBR', 'O que nós sabemos sobre o tauren de Alta Montanha?', 'O que nós sabemos sobre o tauren de Alta Montanha?', 28153),
(143288, 'ptBR', '', 'Agora é a nossa vez de mostrar a força e honra que estamos trazendo para a Horda.', 28153),
(143287, 'ptBR', 'Nós e os taurens de Alta Montanha temos muito em comum. Sei que eles serão ótimos aliados de hoje em diante.', '', 28153),
(143286, 'ptBR', '', 'Não se preocupa com Tsunga. Nós vamos cuidar dele. Ainda que ele não se lembre mais nem do próprio nome.', 28153),
(143285, 'ptBR', '', 'Nossa, esse era dos grandes, hein? Bom trabalho, camarada!', 28153),
(143284, 'ptBR', '', 'Que as estrelas guiem seu caminho, $p. Ouvi falar coisas curiosas do Contraforte de Eira dos Montes. Acho que vou para lá.', 28153),
(143283, 'ptBR', '', 'Tu tem certeza disso, Tsunga? Tu sabe o que a gente vai perder se alguém impedir a passagem das brumas?', 28153),
(143282, 'ptBR', 'Eu vou preparar o ritual para libertar essas almas. Venha me encontrar na praia ao norte daqui.', '', 28153),
(143281, 'ptBR', 'Eu tenho plena consciência das consequências. Mas eu acredito que, por mais difícil que seja perder algumas coisas, o melhor é perder elas mesmo.', '', 28153),
(143280, 'ptBR', 'Eu vou tomar outro caminho pra Garganta. Encontro você lá.', '', 28153),
(143279, 'ptBR', 'Não quebrem a formação! Os reforços estão a caminho. Não deixe as nagas destruírem o dique!', '', 28153),
(143278, 'ptBR', 'Que seu coração não conheça mais ódio.', '', 28153),
(143277, 'ptBR', '', 'Mas os sin\'dorei, os elfos sangrentos, demonstraram respeito e compreensão. Eles mostraram que havia mais gente em Azeroth que partilhava dos nossos valores.', 28153),
(143276, 'ptBR', '', 'Quando nossa cidade enfrentou seu pior momento, os heróis de Azeroth lutaram conosco para rechaçar a Legião. Alguns com relutância.', 28153),
(143275, 'ptBR', '', 'Eu vou lhe dar a roupa tradicional de Suramar. Vista ela como uma recordação do nosso passado... e do futuro que forjaremos junto dos nossos aliados.', 28153),
(143274, 'ptBR', 'Nem precisa dizer duas vezes!', '', 28153),
(143273, 'ptBR', '', 'Você mostrou à Horda e a todos os povos de Azeroth que os filhos da noite possuem força de vontade e coragem para defender o nosso mundo.', 28153),
(143272, 'ptBR', 'Siga até à praia do outro lado do estaleiro. Encontre uma jovem cadete Proudmore chamada... Taelia. Vá!', '', 28153),
(143271, 'ptBR', '', 'Volte a Suramar para que possamos agradecer você por ajudar nosso povo a reivindicar um lugar neste mundo.', 28153),
(143270, 'ptBR', '', 'Você estará entre os primeiros shal\'dorei a partir para desbravar os rincões de Azeroth. Mas agora é hora de voltar para casa.', 28153),
(143269, 'ptBR', 'Os trabalhadores... eles estão presos por magia dos sábios das marés! Temos que ajudá-los.', '', 28153),
(143268, 'ptBR', 'Graças às marés, nem todo mundo perdeu a cabeça. Metade da casa ficou maluca!', '', 28153),
(143267, 'ptBR', 'Flanela demais não dá.', 'Flanela demais não dá.', 28153),
(143266, 'ptBR', '', 'Eu vou na frente. Encontro você lá na costa!', 28153),
(143265, 'ptBR', 'Você está com uma aparência ótima, $n.', '', 28153),
(143264, 'ptBR', 'Temos trabalho a fazer.', '', 28153),
(143263, 'ptBR', 'Flanela nunca é demais.', 'Flanela nunca é demais.', 28153),
(143262, 'ptBR', '', 'Às armas!', 28153),
(143261, 'ptBR', '', 'Pelo rei!', 28153),
(143260, 'ptBR', '', 'Ao ataque!', 28153),
(143259, 'ptBR', '', 'Até a morte!', 28153),
(143258, 'ptBR', '', 'Por Ventobravo!', 28153),
(143257, 'ptBR', '', 'Pela Aliança!', 28153),
(143256, 'ptBR', '', 'Retroceder nunca!', 28153),
(143255, 'ptBR', '', 'Eu me lançarei contra eles!', 28153),
(143254, 'ptBR', '', 'De que corrupção você tá falando? $n, talvez essa coisa veja os trolls sangrentos como \"corrupção\".', 28153),
(143253, 'ptBR', '', '$n, você sabe o que é isso? Será que esse negócio pode nos ajudar?', 28153),
(143252, 'ptBR', '', 'Que vodu é esse?! Talvez ele ajude a gente a deter os trolls sangrentos e G\'huun...', 28153),
(143251, 'ptBR', 'Eu me lançarei contra eles!', '', 28153),
(143250, 'ptBR', 'Retroceder nunca!', '', 28153),
(143249, 'ptBR', 'Pela Aliança!', '', 28153),
(143248, 'ptBR', 'Por Ventobravo!', '', 28153),
(143247, 'ptBR', 'Até a morte!', '', 28153),
(143246, 'ptBR', 'Ao ataque!', '', 28153),
(143245, 'ptBR', 'Pelo rei!', '', 28153),
(143244, 'ptBR', 'Às armas!', '', 28153),
(143243, 'ptBR', 'Nossa, o detector está pirado. Só pode ter sido uma grande explosão de azerita em algum lugar da ilha.', '', 28153),
(143242, 'ptBR', 'Temos que achar a origem dessa profanação e acabar com ela.', '', 28153),
(143241, 'ptBR', '', 'Que esta armadura sirva como recordação dos seus feitos, $p. Aceite-a de coração.', 28153),
(143240, 'ptBR', 'Certeza.', '', 28153),
(143239, 'ptBR', 'V... você acha que as criaturas marinhas também foram afetadas?', '', 28153),
(143238, 'ptBR', 'Eu vou te dar outro \"mau agouro\". A baía tá cheia de presas dos Rompe-onda.', '', 28153),
(143237, 'ptBR', 'Tsunga espia a entrada da caverna, preocupado.', '', 28153),
(143236, 'ptBR', '', 'Muitos duvidaram que os ren\'dorei pudessem manipular o caos sem se tornarem vítimas do seu poder. Você é a prova de que estavam errados.', 28153),
(143235, 'ptBR', 'Os gritos da água ficam cada vez mais altos, à medida que entramos na baía. Eu sinto o tormento das marés. É um mau agouro, sem dúvida.', '', 28153),
(143234, 'ptBR', '', 'Você se tornou uma arma formidável para a Aliança, $p. Volte à fissura do caos para que possamos honrar esse grande feito.', 28153),
(143233, 'ptBR', 'Bem, vamos lá.', '', 28153),
(143230, 'ptBR', 'Eu vou trabalhar no treinamento. Vá falar com Tagart, ele tem mais para você.', '', 28153),
(143229, 'ptBR', 'Guardião Titânico Hezrel reinicializado. Protocolo: conter corrupção desenfreada em Nazmir. Tarefa impossível devido a sistemas danificados.', '', 28153),
(143228, 'ptBR', '', 'Ao longo de suas jornadas por Azeroth, você dominou as forças que vinham tentando controlar você o tempo todo.', 28153),
(143227, 'ptBR', 'Essa foi boa, colega. Vamos ver como se sai. Iá!', '', 28153),
(143226, 'ptBR', 'Ho, ho! Olha só que baita surpresa! Inacreditável!', '', 28153),
(143224, 'ptBR', 'Eu vou avisar pro Rei Rastakhan que, quando as torres estiverem acesas, a gente vai ter retomado os nossos navios. Vai ser o sinal pra minha tripulação voltar pra casa!', '', 28153),
(143223, 'ptBR', 'O objeto não ficou claro na imagem, Gisberto não vai querer isso.', 'O objeto não ficou claro na imagem, Gisberto não vai querer isso.', 28153),
(143222, 'ptBR', 'Por favor, camarada, ajude-me!', '', 28153),
(143221, 'ptBR', 'Meus funcionários... Eu fracassei.', '', 28153),
(143220, 'ptBR', '', 'Socorro! O comandante foi atingido!', 28153),
(143219, 'ptBR', 'Socorro! Estão me atacando!', '', 28153),
(143218, 'ptBR', 'Você vai pagar por isso!', '', 28153),
(143217, 'ptBR', 'Esse cara me deixa fulo das calças!', '', 28153),
(143216, 'ptBR', 'Relaxa que o seguro cobre!', '', 28153),
(143215, 'ptBR', 'Eu tô pagando vocês pra quê?! Consertem logo essa coisa!', '', 28153),
(143214, 'ptBR', 'Eu sou o goblin do calibre grosso!', '', 28153),
(143213, 'ptBR', 'Então toma 300 balas por minuto!', '', 28153),
(143212, 'ptBR', 'Assim que eu gosto! Todo mundo na sola do meu sapato!', '', 28153),
(143211, 'ptBR', 'Vai comer terra!', '', 28153),
(143210, 'ptBR', '', 'Eu vou fazer o reconhecimento da área, encontro você mais adiante!', 28153),
(143209, 'ptBR', 'Você nunca vai me pegar com vida!', '', 28153),
(143208, 'ptBR', 'Eu devia... ter comprado... a cadeira ejetora...', '', 28153),
(143207, 'ptBR', 'A sua família vai pagar as balas que eu gastei.', '', 28153),
(143206, 'ptBR', '', 'Usem as lições que eu ensinei para manter o controle. Tornem-se uma arma para a Aliança... ainda que caminhem à beira da escuridão.', 28153),
(143205, 'ptBR', 'Muitos duvidarão de você. Questionarão o seu valor e a sua capacidade de dominar poderes que causaram a queda de mentes mais fracas.', '', 28153),
(143204, 'ptBR', '', 'Mas nós enxergamos as alternativas. Muitas estradas e possibilidades em aberto para nós.', 28153),
(143203, 'ptBR', '', 'Há quem diga que a Luz é o único caminho. A única arma capaz de deter os inimigos de Azeroth.', 28153),
(143202, 'ptBR', 'Seus imbecis! Vocês têm noção do dano que causaram à minha propriedade?!', '', 28153),
(143201, 'ptBR', 'Deem as boas-vindas aos Casca Grossa!', '', 28153),
(143200, 'ptBR', 'Que nem aquela cobra velha falou. Sobe aí. O Rei tá esperando.', '', 28153),
(143199, 'ptBR', 'Esmagar!', '', 28153),
(143198, 'ptBR', 'Esmagar!', '', 28153),
(143197, 'ptBR', 'Pulverizar! HAHAHHA!', '', 28153),
(143196, 'ptBR', 'Que pena que eu não consegui ensinar pra ele a lição mais importante de todas.', '', 28153),
(143195, 'ptBR', 'Conta pro Rastakhan velho de guerra que eu volto quando quiser. Ah, valeu pela ajuda, hein.', '', 28153),
(143193, 'ptBR', 'Quando eu botar as garras em Yazma e Zul, eles vão comer grama pela raiz!', '', 28153),
(143192, 'ptBR', 'Nossa presa tá por perto. O sangue de Zul, Yazma e daqueles hereges logo vai se derramar. Vai ser uma grande caçada.', '', 28153),
(143191, 'ptBR', 'Glória a Pa\'kul!', 'Glória a Pa\'kul!', 28153),
(143190, 'ptBR', 'O navio vai ser nosso!', 'O navio vai ser nosso!', 28153),
(143189, 'ptBR', 'Taz\'okun!', 'Taz\'okun!', 28153),
(143188, 'ptBR', 'É só um arranhão. Acho que vou ficar bem...', '', 28153),
(143185, 'ptBR', '', 'Você vai arder em chamas!', 28153),
(143184, 'ptBR', '', 'Eu vou queimar tudinho!', 28153),
(143183, 'ptBR', '', 'Você tá querendo azerita? Então toma na cara!', 28153),
(143182, 'ptBR', '', 'Vou ter que zerar a plaquinha de \"dias sem mortes horrendas\".', 28153),
(143181, 'ptBR', 'Dinheiro nenhum paga isso!', '', 28153),
(143180, 'ptBR', '', 'Essa falta de experiência vai te matar!', 28153),
(143179, 'ptBR', 'Pela Aliança!', '', 28153),
(143178, 'ptBR', '', 'É uma honra servi-lo uma vez mais, Alto-rei. Pela Aliança!', 28153),
(143177, 'ptBR', '', 'Mais um candidato sem qualificação!', 28153),
(143176, 'ptBR', 'Você e $go campeão:a campeã; $p nos prestaram um grande serviço hoje, Lady Correventos. Eu agradeço.', '', 28153),
(143175, 'ptBR', 'Pode levar um tempo para os elfos caóticos conquistarem a confiança de alguns dos nossos. Mas contanto que sigam os seus ensinamentos, eles serão bem-vindos na Aliança.', '', 28153),
(143174, 'ptBR', '', 'Cadê o meu... adicional... de periculosidade?', 28153),
(143173, 'ptBR', '', 'Eu lhes servirei de guia. Treinarei eles para que controlem as vozes das sombras. Em troca, eles lutarão pela Aliança contra todos os seus adversários.', 28153),
(143172, 'ptBR', '', 'Alto-rei Wrynn, eu e $gnosso campeão:nossa campeã; $p encontramos os exilados sin\'dorei. Assim como eu, eles foram transformados pelo caos... mas ainda são donos de suas mentes e corações.', 28153),
(143171, 'ptBR', '', 'Se quiser que seja bem feito... use explosivos mais fortes!', 28153),
(143170, 'ptBR', '', 'Foi você quem ferrou com o meu projeto?', 28153),
(143169, 'ptBR', '', 'Ôu! Aonde você pensa que vai?', 28153),
(143168, 'ptBR', 'Intrusos?! Corram!', 'Intrusos?! Corram!', 28153),
(143167, 'ptBR', 'Não sei que escuridão tomou sua mente, irmã, mas ela não há mais de atormentar nosso povo.', '', 28153),
(143166, 'ptBR', 'Vai que é sua!', '', 28153),
(143165, 'ptBR', 'Pega fujão!', '', 28153),
(143164, 'ptBR', '', 'Não quero ouvir nem mais um pio sobre condições insalubres!', 28153),
(143163, 'ptBR', 'É perigoso aqui. O melhor a fazer é deixar este lugar.', '', 28153),
(143162, 'ptBR', 'A ilha nem é tão boa mesmo!', '', 28153),
(143161, 'ptBR', 'Nós estamos condenados!', '', 28153),
(143160, 'ptBR', 'Parta! Seu trabalho aqui terminou.', '', 28153),
(143159, 'ptBR', 'O bicho se soltou! Para trás!', '', 28153),
(143158, 'ptBR', 'Vocês estão agora livres, irmãos e irmãs.', '', 28153),
(143157, 'ptBR', '', 'Quem reclama não prende a respiração! Então a culpa de inalar gases tóxicos é sua.', 28153),
(143156, 'ptBR', 'Voltem para as suas famílias. Nós vamos cuidar disso.', '', 28153),
(143155, 'ptBR', 'Fujam, tolos!', '', 28153),
(143154, 'ptBR', 'Deixa que tua alma se solte da concha mortal e mergulhe nas águas.', '', 28153),
(143153, 'ptBR', 'Ouve a trova do mar; com ela vem a paz.', '', 28153),
(143152, 'ptBR', 'Não te inquietes mais; é a ti que a luz mostra o caminho.', '', 28153),
(143151, 'ptBR', '', 'Pela Horda!', 28153),
(143150, 'ptBR', '', 'Pela Horda!', 28153),
(143149, 'ptBR', '', 'Suramar lutará pela Horda!', 28153),
(143148, 'ptBR', '', 'Suramar lutou sozinha por milhares de anos. Hoje, vocês se tornam parte de algo maior. Eu aceito os seus serviços, Thalyssra.', 28153),
(143147, 'ptBR', '', 'É hora dos filhos da noite fazerem aliados entre os reinos de Azeroth. Se você nos aceitar, nós lutaremos pela sua causa com orgulho.', 28153),
(143146, 'ptBR', '', 'A Horda representa força. Determinação. Individualidade. Qualidades que nós, shal\'dorei, estimamos bastante.', 28153),
(143145, 'ptBR', '', 'De fato, Primeira Arcanista.', 28153),
(143144, 'ptBR', '', 'É uma honra, Chefe Guerreira. Eu lutei ao lado de Lady Liadrin e do lorde-regente. A coragem deles só aumenta os méritos da Horda.', 28153),
(143143, 'ptBR', 'Não tema, irmão. As ondas não te julgam a superfície.', '', 28153),
(143142, 'ptBR', 'Da maré alta à baixa, do além-mar à costa, que seu espírito parta.', '', 28153),
(143141, 'ptBR', 'Seu espírito intrépido há de encontrar o descanso eterno.', '', 28153),
(143140, 'ptBR', 'Que as profundezas abissais acolham sua alma extenuada.', '', 28153),
(143139, 'ptBR', 'Que a Mãe das Marés purifique sua carne iníqua.', '', 28153),
(143138, 'ptBR', 'As correntes hão de te carregar, ó padecente.', '', 28153),
(143137, 'ptBR', 'A terra vai devorar você!', '', 28153),
(143136, 'ptBR', 'Do mar ao mar, das cinzas às cinzas, da maré à maré.', '', 28153),
(143135, 'ptBR', 'Destruição!', '', 28153),
(143134, 'ptBR', 'O sangue de Azeroth corre em suas veias!', '', 28153),
(143133, 'ptBR', 'Não podemos permitir que essas almas perdidas continuem a vagar. Precisamos conversar, $p.', '', 28153),
(143132, 'ptBR', 'Liberte seu poder!', '', 28153),
(143131, 'ptBR', 'Tá bem enxarcado, mas ainda dá para ler. Esses encantamentos vão nos ser úteis.', '', 28153),
(143130, 'ptBR', 'A névoa marítima ofusca a visão, mas, com este sinalizador, conseguiremos chegar até eles.', '', 28153),
(143129, 'ptBR', 'Levante-se!', '', 28153),
(143128, 'ptBR', '', 'Boas-vindas, criança. Minhas vistas me abandonaram, mas Pa\'kul não me abandonou.\n\nSente-se aqui e pergunte o que quer saber. Eu responderei tudo o que sei do grande loa.', 28153),
(143127, 'ptBR', 'Ótimo, a lâmina ainda está afiada. Lâmina afiada é lâmina boa.', '', 28153),
(143126, 'ptBR', 'Esse aí não causa mais problema.', '', 28153),
(143125, 'ptBR', 'Quanto vale o seu sangue?', '', 28153),
(143124, 'ptBR', '', 'Chefe Guerreira Sylvana Correventos, essa é a Primeira Arcanista Thalyssra de Suramar.', 28153),
(143123, 'ptBR', '', 'Eu vou me juntar aos outros e aguardar o seu sinal, $c.', 28153),
(143122, 'ptBR', '', 'Eu tenho minhas dúvidas... mas cumprirei as ordens.', 28153),
(143121, 'ptBR', '', 'Então o Marechal Ribas acredita que você seja a solução para vencer o conventículo?', 28153),
(143120, 'ptBR', 'Pode acertar com vontade!', '', 28153),
(143119, 'ptBR', 'Até que enfim.', '', 28153),
(143118, 'ptBR', 'Coloca força nisso aí!', '', 28153),
(143117, 'ptBR', 'Puxe!', '', 28153),
(143116, 'ptBR', 'Vamos, Calisto. Temos que dar um jeito nessas bruxas.', '', 28153),
(143115, 'ptBR', 'Bastam mais uns cortes para resolver.', '', 28153),
(143114, 'ptBR', 'Quase lá! Só mais um pouquinho.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143113, 'ptBR', 'Novas ordens, é?', '', 28153),
(143112, 'ptBR', 'Obrigado por transmitir as ordens, $c. Eu me apresentarei à Senhorita Capelo imediatamente.', '', 28153),
(143111, 'ptBR', 'E eu pensando que isso era tudo fruto da cabecinha de um historiador de imaginação fértil.', '', 28153),
(143110, 'ptBR', 'Vocês não passam de parasitas.', '', 28153),
(143109, 'ptBR', 'Então os rumores eram verdade? A Ordem das Brasas foi refeita?', '', 28153),
(143108, 'ptBR', 'Tenho que cuidar... das feridas...', '', 28153),
(143107, 'ptBR', '', 'Pode contar com a minha lâmina, $c.', 28153),
(143106, 'ptBR', 'Vocês estão invadindo minhas terras!', '', 28153),
(143105, 'ptBR', '', 'Não sou afeita a misticismo, mas não vou ficar de braços cruzados enquanto o conventículo vem atrás das nossas cabeças.', 28153),
(143104, 'ptBR', '', 'Então é você quem está por trás da tal \"Ordem das Brasas\" de que tanto falam.', 28153),
(143103, 'ptBR', '<Entregar as ordens do Marechal Ribas.>', '<Entregar as ordens do Marechal Ribas.>', 28153),
(143102, 'ptBR', '', 'Os constructos avançam sobre o campo de batalha. Não sobrou um guerreiro vivo, então ele teve que criar um novo exército. Mas o que dá vida às pedras?', 28153),
(143101, 'ptBR', '', 'Em que posso ajudar, $c?', 28153),
(143100, 'ptBR', '', 'Esse aí é Gorak Tul, o maior líder que eles já tiveram. Ah! Ele está conduzindo um ritual para criar constructos de pedra!', 28153),
(143099, 'ptBR', '<O Tenente Maré-severa cumprimenta você com um aceno da cabeça.>', '', 28153),
(143098, 'ptBR', 'Um belo espécime, não? A Casa Capelo tem fama de ser especialista na arte da falcoaria.\n\nInfelizmente, quase todos os pássaros bons foram vitimados pela maldição do conventículo. O Calisto foi um dos poucos que não caiu no feitiço das bruxas.\n\nÉ uma situação deveras lamentável.', '', 28153),
(143097, 'ptBR', '', 'Mas isso... eles glorificaram a chacina! Os kultirenos nem estão armados!', 28153),
(143096, 'ptBR', 'As forças do mal se agitam na floresta, continental. À noite, um antigo monumento drusto no seio da mata emite uma luz profana.\n\nSe eu fosse você, passaria longe daquele lugar nas suas jornadas.', '', 28153),
(143095, 'ptBR', '', 'O que foi, continental?\n\nNão sei se deu para reparar, mas eu estou meio ocupada.', 28153),
(143094, 'ptBR', 'ELIMINAR INVASOR. PU-PURIFICAR. PURIFICAR.', '', 28153),
(143093, 'ptBR', 'LIBERAÇÃO DE CORRUPÇÃO IMINENTE. AT-ATIVANDO PROTOCOLOS DE SEG-SEGURANÇA. INV-INVASOR ENCONTRADO.', '', 28153),
(143092, 'ptBR', 'ERRO... INVASÃO... DET-DETECTADA... PROCURANDO... CORRUPÇÃO.', '', 28153),
(143091, 'ptBR', 'Uso de gases tóxicos aprovado.', '', 28153),
(143090, 'ptBR', 'Voltagem aumentada.', '', 28153),
(143089, 'ptBR', 'Sistemas ativados. Iniciando espancamento.', '', 28153),
(143088, 'ptBR', '', 'Pelo jeito os kultirenos perto do monólito são... civis? Marinheiros e um punhado de agricultores?', 28153),
(143087, 'ptBR', '', 'Até o líder deles fugiu do campo de batalha.', 28153),
(143086, 'ptBR', '', 'HA! Chegou a hora de dar o troco!', 28153),
(143085, 'ptBR', '', 'Que interessante, os constructos deles não vieram para o campo de batalha.', 28153),
(143084, 'ptBR', 'A Empreendimentos S.A. agradece a preferência. Divirta-se com o seu conjunto de espancamento profissional.', '', 28153),
(143083, 'ptBR', '', 'Uma vitória sobre mais um assentamento kultireno. A figura maior no centro é o líder lendário, imagino.', 28153),
(143082, 'ptBR', 'A Empreendimentos S.A. agradece a preferência. Divirta-se com o seu conjunto de espancamento básico.', '', 28153),
(143081, 'ptBR', 'Me dá uns meses, e esse lugar vai ter virado um resort seis estrelas de primeira!', '', 28153),
(143080, 'ptBR', 'Idiota! NINGUÉM compra a garantia estendida!', 'Idiota! NINGUÉM compra a garantia estendida!', 28153),
(143079, 'ptBR', 'Tá bom, tá bom! Pera... será que vale a pena comprar a garantia estendida?', 'Tá bom, tá bom! Pera... será que vale a pena comprar a garantia estendida?', 28153),
(143078, 'ptBR', '', '', 28153),
(143077, 'ptBR', 'A gente vai morrer!', 'A gente vai morrer!', 28153),
(143076, 'ptBR', 'Não me apressa! Eu tô lendo os termos de adesão!', 'Não me apressa! Eu tô lendo os termos de adesão!', 28153),
(143075, 'ptBR', 'Depressa! Eles estão vindo!', 'Depressa! Eles estão vindo!', 28153),
(143074, 'ptBR', 'Só tava fazendo um intervalo.', '', 28153),
(143073, 'ptBR', 'Calma, garota. Calma.', '', 28153),
(143072, 'ptBR', 'Sistemas... em pane. Erro ao liberar... moedas.', '', 28153),
(143071, 'ptBR', 'Quem quer fazer um voo? Quer fazer um voo? Vamos fazer um voo!', '', 28153),
(143070, 'ptBR', 'Sem morder!', '', 28153),
(143069, 'ptBR', 'Rotina de controle de danos iniciada.', '', 28153),
(143068, 'ptBR', 'Danos a essa unidade violam os Termos de Uso.', '', 28153),
(143067, 'ptBR', 'Lá vai bomba!', 'Lá vai bomba!', 28153),
(143066, 'ptBR', 'Cuidado aí embaixo, seus vermes!', 'Cuidado aí embaixo, seus vermes!', 28153),
(143065, 'ptBR', 'Você aí. De volta ao trabalho!', 'Você aí. De volta ao trabalho!', 28153),
(143064, 'ptBR', 'Força letal autorizada.', '', 28153),
(143063, 'ptBR', 'Multidão acima dos limites aceitáveis. Dispersar.', '', 28153),
(143062, 'ptBR', 'Oferecemos serviços funerários a preços convidativos.', '', 28153),
(143061, 'ptBR', 'Mais um cliente satisfeito.', '', 28153),
(143060, 'ptBR', 'A Empreendimentos S.A. não se responsabiliza pela devolução de membros perdidos.', '', 28153),
(143059, 'ptBR', 'A Horda se defendeu contra um ataque!', 'A Horda se defendeu contra um ataque!', 28153),
(143058, 'ptBR', 'E espalhem-se! Esses cães da Aliança vão mandar reforços contra nós.', '', 28153),
(143057, 'ptBR', '', 'Assim que o navio tomar o porto, eu vou virar capitã! Vão se acostumando logo a baixar a cabeça pra mim!', 28153),
(143056, 'ptBR', '', 'Esses prisioneiros não sabem a sorte que deram! Eles vão estar com Zul logo mais.', 28153),
(143055, 'ptBR', '', 'Se for pra tomar o porto, a gente vai ter que trabalhar dobrado!', 28153),
(143054, 'ptBR', 'Não consigo... evitar... AAAAAAAUUURGH!', '', 28153),
(143050, 'ptBR', 'Não! Eu não posso morrer aqui! Não é minha hora!', '', 28153),
(143049, 'ptBR', 'Ele sabia... o tempo... todo...', '', 28153),
(143048, 'ptBR', 'Isso... isso não tá acontecendo!', '', 28153),
(143047, 'ptBR', 'Vocês são fortes, mas minha visão é maior!', '', 28153),
(143046, 'ptBR', 'Sai daqui! Eu ordeno!', '', 28153),
(143045, 'ptBR', 'Meus escolhidos! Venham até mim! Seu mestre precisa de vocês!', '', 28153),
(143044, 'ptBR', 'É tu que vai morrer aqui!', '', 28153),
(143043, 'ptBR', 'Tu não tá na vantagem não, meu velho!', '', 28153),
(143042, 'ptBR', 'Tem razão. Eu não. Mas tem alguém que vai.', '', 28153),
(143041, 'ptBR', 'A gente sabe que cê não vai me matar. Tu não pode me deter.', '', 28153),
(143040, 'ptBR', 'Boa menina. Está quase na hora do lanche!', '', 28153),
(143039, 'ptBR', 'Cansei de brincar disso. Você entregou sua mensagem. Agora é hora de encarar o seu destino.', '', 28153),
(143038, 'ptBR', 'Zul traga a poção num longo gole. O gosto o faz estremecer.', '', 28153),
(143037, 'ptBR', 'A primeira que tu botar os olhos. Nem pensa duas vezes.', '', 28153),
(143036, 'ptBR', 'Os lacaios dele vão tentar te impedir. Fica de olho.', '', 28153),
(143035, 'ptBR', 'Hum.', '', 28153),
(143034, 'ptBR', 'Vem cá. Tá na hora.', '', 28153),
(143033, 'ptBR', 'Boa. Agora troca uma poção do Vol\'jamba pela que eu te dei.', '', 28153),
(143032, 'ptBR', 'Pensando melhor... arreda um pouquinho pra esquerda.', '', 28153),
(143031, 'ptBR', 'Agora ponha a urna perto do arco.', '', 28153),
(143030, 'ptBR', 'Ande sempre armad$Uo:a; quando não estiver na embaixada, $p. Os Zandalari não têm força de vontade para manter o controle. Eles precisam de uma Chefe Guerreira forte como a nossa.\n\nAgora, o que posso fazer por você?', 'Ande sempre armad$Uo:a; quando não estiver na embaixada, $p. Os Zandalari não têm força de vontade para manter o controle. Eles precisam de uma Chefe Guerreira forte como a nossa.\n\nAgora, o que posso fazer por você?', 28153),
(143029, 'ptBR', 'Se você vir alguém da Aliança por aí, me avise. Eu dou um jeito na situação.\n\nEnquanto isso, o que você procura?', 'Se você vir alguém da Aliança por aí, me avise. Eu dou um jeito na situação.\n\nEnquanto isso, o que você procura?', 28153),
(143028, 'ptBR', 'Uma coisa não se pode negar, os Zandalari sabem como construir uma embaixada. E essa cidade é imensa!\n\nVocê está perdid$Uo:a;?', 'Uma coisa não se pode negar, os Zandalari sabem como construir uma embaixada. E essa cidade é imensa!\n\nVocê está perdid$Uo:a;?', 28153),
(143027, 'ptBR', 'Estou ocupado. Não abuse.', 'Estou ocupada. Não abuse.', 28153),
(143026, 'ptBR', 'Posso ajudar, $pr?', 'Posso ajudar, $pr?', 28153),
(143025, 'ptBR', 'Glória à Chefe Guerreira! Procurando alguma coisa?', 'Glória à Chefe Guerreira! Procurando alguma coisa?', 28153),
(143024, 'ptBR', 'Essa embaixada é a prova de que os Zandalari respeitam a força da nossa Chefe Guerreira. Que tenham respeito e temor.\n\nE então, o que você quer?', 'Essa embaixada é a prova de que os Zandalari respeitam a força da nossa Chefe Guerreira. Que tenham respeito e temor.\n\nE então, o que você quer?', 28153),
(143023, 'ptBR', 'Essa umidade faz suar até os ossos. O que eu posso fazer por você?', 'Essa umidade faz suar até os ossos. O que eu posso fazer por você?', 28153),
(143022, 'ptBR', 'Tamos subindo na vida, grandão. Algum dia, isso tudo aqui vai ser nosso.', '', 28153),
(143021, 'ptBR', 'A gente tá te pagando pra você ficar de bobeira?', '', 28153),
(143020, 'ptBR', '', 'Talvez a morte seja o verdadeiro Legado dos Correventos.', 28153),
(143019, 'ptBR', '', 'Sem dúvida. Às vezes sinto que eu já morri duas vezes. Uma quando estávamos supostamente perdidos em Draenor, outra quando fomos agarrados pela sombra do Naaru decaído.', 28153),
(143018, 'ptBR', 'É inquietante observar essas homenagens à nossa passagem.', '', 28153),
(143017, 'ptBR', '', 'Chegou a hora, Turalyon. Preciso rever minha terra natal com meus próprios olhos... e ouvir de Sylvana como ela teve coragem de vestir o manto de Chefe Guerreira.', 28153),
(143016, 'ptBR', 'Cada um de vós tem um caminho a seguir. Se a Luz quiser que tais caminhos se cruzem, assim será. Não temos por que forçar o destino.', '', 28153),
(143015, 'ptBR', 'Tu não precisas ir. Não precisas vê-la.', '', 28153),
(143014, 'ptBR', '', 'Como nenhuma outra, meu amor.', 28153),
(143013, 'ptBR', 'Tu estás com ansiedade. Tu disfarças bem, mas eu te conheço.', '', 28153),
(143012, 'ptBR', 'Eu sei que temos muito o que fazer nos próximos dias, mas aconteça o que acontecer... nunca se esqueça do teu dever com Azeroth!', '', 28153),
(143011, 'ptBR', 'A energia que flui nessa tua arma... Eu nunca vi nada do tipo! Mas lembre-se... todo poder tem seu preço.', '', 28153),
(143010, 'ptBR', 'Deu certo! A espada de Sargeras está adormecida. Ainda temos que curar Azeroth... mas agora temos mais tempo pra pensar.', '', 28153),
(143009, 'ptBR', 'Juntos, campeões! Por Azeroth!', '', 28153),
(143008, 'ptBR', 'Ergam-nas como uma só... Vamos tirar a corrupção da lâmina do Titã Sombrio!', '', 28153),
(143007, 'ptBR', 'A única coisa capaz de conter tamanho poder... seria uma das nossas armas.', '', 28153),
(143006, 'ptBR', 'A espada de Sargeras está envenenando a energia vital do mundo.', '', 28153),
(143005, 'ptBR', 'Vamos para Silithus... enquanto ainda temos um mundo para salvar!', '', 28153),
(143004, 'ptBR', 'Eu sei que a coisa tá feia... mas eu preciso de novo da ajuda de vocês.', '', 28153),
(143003, 'ptBR', 'Campeões, vocês uniram as ordens e lutaram juntos para expulsar a Legião de Azeroth.', '', 28153),
(143002, 'ptBR', 'A tempestade se aproxima, $p. Se a gente não der um jeito de curar Azeroth... não vai restar pedra sobre pedra.', '', 28153),
(143001, 'ptBR', 'Eu não sei como consertar isso. Nem sei se alguém sabe. Mas não podemos desistir agora.', '', 28153),
(143000, 'ptBR', 'Desde que Argus voltou, os gritos de Azeroth têm sido... desesperadores. Quanta dor...', '', 28153),
(142999, 'ptBR', 'Ah... Como é bom ver um rostinho conhecido em tempos tão sombrios.', '', 28153),
(142998, 'ptBR', 'A gente ainda tá esperando eles, princesa. Mas também descolamos uma pista sobre o loa Krag\'wa.', '', 28153),
(142997, 'ptBR', '', 'E esse foi o destino do Torga. Alguma notícia dos reforços da Horda?', 28153),
(142996, 'ptBR', 'Já tamos quase terminando isso, $n. Vamo continuar só um pouco mais.', '', 28153),
(142995, 'ptBR', 'Não acredito que esses monstros estriparam o Torga...', '', 28153),
(142994, 'ptBR', 'Meh, agora Torga está morto, e não tem nada de interessante para contar quando eu voltar.', '', 28153),
(142993, 'ptBR', 'Onde está Kisha? Achei que ela estaria aqui para orientar...', '', 28153),
(142992, 'ptBR', 'Muito bem, eu vou para o Bosque da Solidão para ver no que vai dar essa loucura.', '', 28153),
(142991, 'ptBR', 'Hã... bom, acho que uma luta contra um hoste de trolls sangrentos daria uma história interessante. Está bem, eu vou para o Bosque da Solidão.', '', 28153),
(142990, 'ptBR', 'Vocês... O QUÊ? Eu não vou perder essa história. Vou para o Bosque da Solidão.', '', 28153),
(142989, 'ptBR', 'Certo, Kisha. Vamos para o Bosque da Solidão para chamar os nossos irmãos. E você junta todo mundo que faltar, $n.', '', 28153),
(142988, 'ptBR', '', 'Eu vou pro Bosque da Solidão. Você cuida dos tortollanos pelo caminho.', 28153),
(142987, 'ptBR', '$n, use os canhões!', '', 28153),
(142986, 'ptBR', 'Boa sorte, $p. Eu agora vou testar minha habilidade no Vale Gris. Pela Horda!', '', 28153),
(142985, 'ptBR', 'O Sopro de Pa\'kul e o Garra de Rezan deram a volta no mundo e voltaram. Ajuda eles no caminho que falta pra casa.', '', 28153),
(142984, 'ptBR', 'Quando os navios voltaram, trouxeram uma escuridão com eles. Daí veio uma sensação ruim, lá no fundo do meu estômago.', '', 28153),
(142983, 'ptBR', 'O Sopro de Pa\'kul foi meu lar por muitos anos. Meu coração, como esse porto, fica vazio sem ele.', '', 28153),
(142982, 'ptBR', 'O rugido de Anji, o Trovejante, enche você de vigor.', '', 28153),
(142981, 'ptBR', 'Ei! Entra no barco! O Capitão disse que o Sopro de Pa\'kul tá com problema!', '', 28153),
(142980, 'ptBR', '', 'Comandante, viemos para ajudar. O dique não vai se romper hoje!', 28153),
(142979, 'ptBR', '', 'Vamos até o dique. Comandante Ridão não gosta de esperar!', 28153),
(142977, 'ptBR', 'Não há lugar para furta-cebolas aqui!', '', 28153),
(142976, 'ptBR', 'Antrecosto de carrapato, eis o que tu és!', '', 28153),
(142975, 'ptBR', 'Eu desprezo tua audácia, ádvena deplorável!', '', 28153),
(142974, 'ptBR', 'Raspa-te, ignóbil!', '', 28153),
(142973, 'ptBR', 'Hei de esmagar-te sob meus austeros calcanhares!', '', 28153),
(142972, 'ptBR', 'Tu há de sofrer uma derrocada clamorosa!', '', 28153),
(142971, 'ptBR', 'Tua arcada dentária restará destroçada no fim!', '', 28153),
(142970, 'ptBR', 'Sentido!', '', 28153),
(142969, 'ptBR', '', 'Com a autoridade da Casa Capelo, eu os nomeio Inquisidores da Ordem das Brasas.', 28153),
(142968, 'ptBR', '', 'Hoje vocês se tornam o farol da esperança contra o inimigo infindo.', 28153),
(142967, 'ptBR', '', 'Hoje vocês se tornam a lâmina refulgente que trespassa a maldade.', 28153),
(142966, 'ptBR', '', 'Irmãos e irmãs, hoje vocês se tornam o fogo abrasador que queima a escuridão.', 28153),
(142965, 'ptBR', '', 'Ah, achei.', 28153),
(142964, 'ptBR', '', 'Tinha umas palavrinhas de iniciação em alguma parte do tomo. Deixe-me ver...', 28153),
(142963, 'ptBR', '', 'Obrigada por botar seus homens à disposição, Marechal. Agora sim, estamos começando a virar uma Ordem decente!', 28153),
(142962, 'ptBR', 'Já faz dias que eu tô esperando pra ver o Rei. Achei que ele ia estar mais interessado em saber o que os goblins vieram fazer nas nossas terras.', '', 28153),
(142961, 'ptBR', 'Nós temos bons soldados aquartelados aqui, milady. Eles darão ótimos recrutas para a Ordem das Brasas.', '', 28153),
(142960, 'ptBR', '', 'Marechal, acho que encontramos as armas para combater o conventículo. Vamos precisar de soldados para usá-las.', 28153),
(142959, 'ptBR', 'Eu nunca ia trair os loas ou a cidade!', '', 28153),
(142958, 'ptBR', 'Eu adoro Pa\'kul. Magia de sangue é crime!', '', 28153),
(142957, 'ptBR', 'Tô falando a verdade. Eu não sei de nada de relíquia do sangue!', '', 28153),
(142956, 'ptBR', 'Eu sou inocente! Me dá uma moral aí.', '', 28153),
(142955, 'ptBR', 'Eu nunca ia contrabandear relíquia do sangue. Magia de sangue é maligna!', '', 28153),
(142954, 'ptBR', 'Nunca vi relíquia do sangue nenhuma!', '', 28153),
(142953, 'ptBR', 'Eu não sei do que tu tá falando!', '', 28153),
(142952, 'ptBR', 'Não fiz nada de errado!', '', 28153),
(142951, 'ptBR', 'Não me faz te esfaquear de novo...', '', 28153),
(142950, 'ptBR', 'Pra quem tu vendeu as relíquias do sangue?', '', 28153),
(142949, 'ptBR', 'Tu me dá nojo, seu traíra.', '', 28153),
(142948, 'ptBR', 'Vou te fazer sofrer, Pro\'ditor. Tu vai servir de exemplo para todo mundo.', '', 28153),
(142947, 'ptBR', 'Se tu confessar, prometo que te mato rápido.', '', 28153),
(142946, 'ptBR', 'Tu é o lixo do lixo, Pro\'ditor. A magia de sangue tá matando nosso povo!', '', 28153),
(142945, 'ptBR', 'A gente sabe que você andou contrabandeando relíquias do sangue.', '', 28153),
(142944, 'ptBR', 'Conte como conseguiu as relíquias do sangue, Pro\'ditor!', '', 28153),
(142943, 'ptBR', 'Esse lixo andou contrabandeando relíquias do sangue aqui na cidade.\n\nEle vai confessar e a gente vai fazer ele de exemplo.', '', 28153),
(142942, 'ptBR', 'Não fiz nada de errado! Conta pra eles!', '', 28153),
(142941, 'ptBR', '(Sair)', '(Sair)', 28153),
(142940, 'ptBR', '<Mal dá para reconhecer os restos ensanguentados e estropiados do fugitivo Teshyambi. Parece ter sido obra de raptores que estão por perto.>', '<Mal dá para reconhecer os restos ensanguentados e estropiados do fugitivo Teshyambi. Parece ter sido obra de raptores que estão por perto.>', 28153),
(142939, 'ptBR', 'Eu sei quem é você, Mojoba. Prossiga para Vol\'dun e viva em paz no seu exílio.', 'Eu sei quem é você, Mojoba. Prossiga para Vol\'dun e viva em paz no seu exílio.', 28153),
(142938, 'ptBR', 'Hein? Quem é você? O que você quer, hein?', '', 28153),
(142937, 'ptBR', 'Lamento, mas você foi exilado para Vol\'dun devido aos seus crimes.', 'Lamento, mas você foi exilado para Vol\'dun devido aos seus crimes.', 28153),
(142936, 'ptBR', 'Shh! Estou me escondendo dos raptores e do Zulajin. Tenho que voltar pra Zuldazar.', '', 28153),
(142935, 'ptBR', '', 'Você até que é bom... para um fugitivo.', 28153),
(142934, 'ptBR', '', 'Agora que conseguimos as chaves e tomamos o controle da prisão, podemos retomar a azerita e libertar os reféns.', 28153),
(142933, 'ptBR', '', 'Parece que a Lady Grimpagris vai abrir uma vaga para feitor.', 28153),
(142932, 'ptBR', 'Cuidado com as chamas! Estou falando com você, feiticeiro do fogo. Se uma dessas munições de azerita explodir, nós todos iremos pelos ares!', '', 28153),
(142931, 'ptBR', 'Preparem-se, homens! Eles estão chegando!', '', 28153),
(142930, 'ptBR', '', 'Nós vamos tomar os andares de baixo enquanto você procura o feitor.', 28153),
(142929, 'ptBR', '', 'Muito bem. Parece que você está com tudo sob controle.', 28153),
(142928, 'ptBR', 'Quando botarmos as mãos nos reféns do Feitor, vamos encher o rabo de dinheiro!', '', 28153),
(142927, 'ptBR', 'Vamos, rapazes! Arrombem essas portas!', '', 28153),
(142926, 'ptBR', '', 'Acho bom mesmo, senão a primeira tarefa do seu substituto vai ser te jogar no mar com esse monte de lixo.', 28153),
(142925, 'ptBR', 'Peço perdão, Lady Grimpagris. Sei que meus homens trarão a ordem de volta.', '', 28153),
(142924, 'ptBR', '', 'Korgus! Posso saber por que você não inundou os andares de baixo e afogou esses ratos pestilentos?!', 28153),
(142923, 'ptBR', '', 'Argh! Vocês tiveram que passar por aí pra fugir? Vão na frente... quem sabe o cheiro não melhora?', 28153),
(142922, 'ptBR', '', 'Com uma criatura dessas, o Feitor não precisava mesmo de muitos guardas nesse lado da ilha. Bom trabalho.', 28153),
(142921, 'ptBR', '', 'Vamos cuidar dos guardas do perímetro enquanto você avança até a entrada do esgoto. Deve haver um caminho até a prisão.', 28153),
(142920, 'ptBR', '', 'Segundo os nossos informantes, as chaves de acesso aos depósitos de azerita e à ala de reféns ficam com o feitor... no pescoço dele.', 28153),
(142919, 'ptBR', '', 'Fiquem quietos! Eles ainda não nos viram.', 28153),
(142918, 'ptBR', 'Eu tenho mesmo que fazer isso?', '', 28153),
(142917, 'ptBR', 'O que foi?', '', 28153),
(142916, 'ptBR', 'Pronto para trabalhar.', '', 28153),
(142915, 'ptBR', 'Nosso Quartel foi destruído!', '', 28153),
(142914, 'ptBR', 'Precisamos de reforços para vencer esta guerra.', '', 28153),
(142913, 'ptBR', 'De volta ao trabalho!', '', 28153),
(142912, 'ptBR', 'Alguém tem que erguer essa construção!', '', 28153),
(142911, 'ptBR', 'Bate forte com esse martelo!', '', 28153),
(142910, 'ptBR', '', 'Alleria fica tensa e desconfiada.', 28153),
(142909, 'ptBR', 'Você salvou a minha vida!', 'Você salvou a minha vida!', 28153),
(142908, 'ptBR', 'Acho que eu consigo chegar a um lugar seguro. Agradeço muito.', 'Acho que eu consigo chegar a um lugar seguro. Agradeço muito.', 28153),
(142907, 'ptBR', 'Os ataques deles são impiedosos. Agradeço sua ajuda.', 'Os ataques deles são impiedosos. Agradeço sua ajuda.', 28153),
(142906, 'ptBR', 'Não esquecerei sua bravura.', 'Não esquecerei sua bravura.', 28153),
(142905, 'ptBR', 'Achei que eu fosse morrer ali!', 'Achei que eu fosse morrer ali!', 28153),
(142904, 'ptBR', 'Nossa aldeia precisa de outros heróis como você!', 'Nossa aldeia precisa de outros heróis como você!', 28153),
(142903, 'ptBR', 'Vingue aqueles que não puderam ser salvos.', 'Vingue aqueles que não puderam ser salvos.', 28153),
(142902, 'ptBR', 'As nagas são monstros!', 'As nagas são monstros!', 28153),
(142901, 'ptBR', 'Vou fincar essa lâmina no teu peito!', '', 28153),
(142900, 'ptBR', 'Tem intrusos entrando pelo esgoto!', '', 28153),
(142898, 'ptBR', 'Esta pedra canta uma canção silente e poderosa. Apenas uma criatura é capaz de ouvir sua melodia, e só nos resta esperar que ela jamais venha para cá.', '', 28153),
(142897, 'ptBR', 'Eu vi tudo que precisava. Esta pedra é maligna, e deve ser destruída.', '', 28153),
(142894, 'ptBR', 'Duvido que ela nos seja entregue voluntariamente; você vai ter que arrancar aquela arma das mãos de um cadáver.', '', 28153),
(142893, 'ptBR', 'Avistei nossa próxima presa ao sul. É melhor ir rápido.', '', 28153),
(142892, 'ptBR', 'Infelizmente, destruir essa embarcação vai permitir que os kultirenos se reagrupem.', '', 28153),
(142891, 'ptBR', 'A Dama Sombria vai gostar de ter você conosco.', '', 28153),
(142890, 'ptBR', '', 'Com todo o prazer, Lorde-regente. Nos vemos em Luaprata, $Gcampeão:campeã;.', 28153),
(142889, 'ptBR', 'Excelente! Lady Liadrin, queira retornar a Orgrimmar e dar as boas novas à chefe guerreira.', '', 28153),
(142888, 'ptBR', '', 'Em nome dos filhos da noite, eu aceito a sua proposta. Deste dia em diante, Suramar lutará pela Horda.', 28153),
(142887, 'ptBR', 'É isso que a Horda lhe oferece, Primeira Arcanista. Junte-se a nós. Os portões de Luaprata estão abertos.', '', 28153),
(142886, 'ptBR', '', 'Suramar sempre será nossa casa. Mas alguns entre nós desejam desbravar o mundo para reconquistar nosso lugar em Azeroth. Para fazer isso, nós precisamos de aliados.', 28153),
(142885, 'ptBR', '', 'Nossos aliados nos deram força... mas nós não deixamos de ser quem somos.', 28153),
(142884, 'ptBR', '', 'Pelo contrário. O conflito demonstrou que você é dedicado ao seu povo. Vê-se que a Horda permitiu que vocês mantivessem suas tradições... uma coisa de grande importância para nós.', 28153),
(142883, 'ptBR', 'Eu lamento que você tenha tido que presenciar isso, Thalyssra. Meus planos para a sua visita eram outros.', '', 28153),
(142882, 'ptBR', '', 'Como desejar, Lorde-regente. Por enquanto.', 28153),
(142881, 'ptBR', 'Basta! Você vai embora imediatamente, Alleria. Acidente ou não, sua presença é um risco para Quel\'thalas. Volte para Ventobravo... Luaprata não é mais o seu lar.', '', 28153),
(142880, 'ptBR', '', 'Eu não serei prisioneira em minhas próprias terras.', 28153),
(142879, 'ptBR', 'Guardas! Peguem a sabotadora.', '', 28153),
(142878, 'ptBR', 'A Nascente do Sol está a salvo. Sua ajuda foi inestimável, Thalyssra. E também a sua, $Gcampeão:campeã;.', '', 28153),
(142877, 'ptBR', 'Você só está adiando o inevitável! O prêmio será meu.', '', 28153),
(142876, 'ptBR', '', 'Agora! Concentrem seu poder com o meu!', 28153),
(142875, 'ptBR', 'A porta se abre. Sim... isso vai servir ao nosso propósito.', '', 28153),
(142874, 'ptBR', '', 'Diga-nos o que fazer, e nossa força estará às ordens.', 28153),
(142873, 'ptBR', '', 'Eu posso fechar a fenda, mas vou precisar de ajuda.', 28153),
(142872, 'ptBR', 'Tem alguma coisa tentando abrir uma fenda dentro da câmara. Se conseguir, nós podemos perder a Nascente do Sol.', '', 28153),
(142871, 'ptBR', 'Comece a lançar o feitiço, Rikal.', 'Comece a lançar o feitiço, Rikal.', 28153),
(142870, 'ptBR', 'Cedo ou tarde, a maré vai mudar. É sempre assim.', '', 28153),
(142869, 'ptBR', 'Seu Agarre está soltando!', '', 28153),
(142868, 'ptBR', '|TInterface\\Icons\\ABILITY_ROGUE_FANOFKNIVES:20|t%s está se preparando para lançar |cFFFF0000|Hspell:257785|h[Adagas Dardejantes]|h|r! Esconda-se!', '', 28153),
(142867, 'ptBR', 'Bal\'a dash, malanore.', '', 28153),
(142866, 'ptBR', 'Cada um de nós deve fazer o próprio caminho.', '', 28153),
(142865, 'ptBR', 'Nosso povo representa um novo futuro.', '', 28153),
(142864, 'ptBR', 'Não se deve tomar nada por certo.', '', 28153),
(142863, 'ptBR', 'O universo é cheio de mistérios.', '', 28153),
(142862, 'ptBR', 'Novas oportunidades se apresentam.', '', 28153),
(142861, 'ptBR', 'O passado está escrito. O futuro, não.', '', 28153),
(142860, 'ptBR', 'Shorel\'aran.', '', 28153),
(142859, 'ptBR', 'Nosso povo não teme as sombras.', '', 28153),
(142858, 'ptBR', 'Não há uma verdade única.', '', 28153),
(142857, 'ptBR', 'As vozes não nos controlam.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142856, 'ptBR', 'Todo impulso deve ficar sob controle.', '', 28153),
(142855, 'ptBR', 'Não tema o poder. Controle-o.', '', 28153),
(142854, 'ptBR', 'Considere todas as possibilidades.', '', 28153),
(142853, 'ptBR', 'Seu comportamento infantil não vai me afetar.', '', 28153),
(142852, 'ptBR', '\"Lembrem-se da Nascente do Sol?\" Por favor. Que antiquado.', '', 28153),
(142851, 'ptBR', 'Se um portal para o vazio absoluto se abrir sob seus pés e consumir você por inteiro na minha presença, saiba que foi pura coincidência. Acidentes acontecem, não é mesmo?', '', 28153),
(142850, 'ptBR', 'Ah, claro, eu sou transformado por uma força cósmica notória por induzir à loucura e de repente passo a ser \"suspeito\". Preconceito nenhum nisso...', '', 28153),
(142849, 'ptBR', 'O que procura?', '', 28153),
(142848, 'ptBR', 'Mercadorias raras de reinos distantes.', '', 28153),
(142847, 'ptBR', 'Tudo tem um preço... é só estar disposto a pagar.', '', 28153),
(142846, 'ptBR', 'Tomara que você goste dos produtos.', '', 28153),
