(142762, 'ptBR', '', 'Bal\'a dash, malanore.', 28153),
(142761, 'ptBR', 'Avistei um alvo de grande valor no distrito vizinho usando artilharia de azerita. Tome aquelas armas para a Horda.', '', 28153),
