INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142041, 'ptBR', '', 'Mordida do Demônio é um ataque que causa dano e gera Fúria.', 28153),
(142040, 'ptBR', 'Use Mordida do Demônio no boneco-alvo.', '', 28153),
(142039, 'ptBR', 'Mordida do Demônio é um ataque que causa dano e gera Fúria.', '', 28153),
(142038, 'ptBR', 'Agora que você está ao alcance, é hora de desferir golpes cruéis.', '', 28153),
(142036, 'ptBR', '', 'Use Impulso Vil para arremeter contra o boneco-alvo.', 28153),
(142035, 'ptBR', 'O que foi que o vento trouxe?', '', 28153),
(142034, 'ptBR', 'O rio nos sustenta.', '', 28153),
(142033, 'ptBR', 'Saudações, viajante.', '', 28153),
(142032, 'ptBR', '', 'Com uma agilidade inigualável, você escolhe onde e quando enfrentar seus inimigos.', 28153),
(142031, 'ptBR', '', 'Como caçadora de demônios de Devastação, você sacrificou muito para dominar o poder vil dos demônios.', 28153),
(142030, 'ptBR', '', 'Como caçador de demônios de Devastação, você sacrificou muito para dominar o poder vil dos demônios.', 28153),
(142029, 'ptBR', 'A Alta Montanha resiste.', '', 28153),
(142028, 'ptBR', 'Como caçador de demônios de Devastação, você sacrificou muito para dominar o poder vil dos demônios.', '', 28153),
(142027, 'ptBR', 'Use Impulso Vil para arremeter contra o boneco-alvo.', '', 28153),
(142026, 'ptBR', 'Com uma agilidade inigualável, você escolhe onde e quando enfrentar os seus inimigos.', '', 28153),
(142025, 'ptBR', 'Como caçador de demônios de Devastação, você sacrificou muito para dominar o poder vil dos demônios.', '', 28153),
(142022, 'ptBR', 'Tu tá com cara de quem já tem um plano, princesa.', '', 28153),
(142021, 'ptBR', '', 'Esse tal de \"G\'huun\" deve estar dando poder a eles... mais do que podemos enfrentar. Precisamos traçar uma nova estratégia.', 28153),
(142020, 'ptBR', 'Eles têm um o QUÊ?! Achei que tu tinha dito que essas coisas só moravam no pântano!', '', 28153),
(142019, 'ptBR', 'Ouçam, ouçam! O Lorde Trovamare tem algo a dizer para aqueles que creem!', 'Ouçam, ouçam! O Lorde Trovamare tem algo a dizer para aqueles que creem!', 28153),
(142018, 'ptBR', 'O Encarregado Spolitto perdeu o juízo. Todo mundo perdeu!', 'O Encarregado Spolitto perdeu o juízo. Todo mundo perdeu!', 28153),
(142017, 'ptBR', 'Achei que eu fosse desmaiar!', 'Achei que eu fosse desmaiar!', 28153),
(142016, 'ptBR', 'Não vão nos deixar ir embora!', 'Não vão nos deixar ir embora!', 28153),
(142015, 'ptBR', 'Que o mar te abençoe!', 'Que o mar te abençoe!', 28153),
(142014, 'ptBR', 'Muitíssimo obrigado, $Uforasteiro:forasteira;!', 'Muitíssimo obrigada, $Uforasteiro:forasteira;!', 28153),
(142013, 'ptBR', 'Os ceifadores se voltaram contra nós!', 'Os ceifadores se voltaram contra nós!', 28153),
(142012, 'ptBR', 'O mar me protege!', 'O mar me protege!', 28153),
(142011, 'ptBR', 'Eu sabia que o mar não tinha nos abandonado!', 'Eu sabia que o mar não tinha nos abandonado!', 28153),
(142007, 'ptBR', 'Uma hora... você vai ter o que merece...', 'Uma hora... você vai ter o que merece...', 28153),
(142006, 'ptBR', 'Quanta... insu... bordinação...', 'Quanta... insu... bordinação...', 28153),
(142004, 'ptBR', 'Você está... dispensado...', 'Já vai tarde.', 28153),
(142003, 'ptBR', 'Meus bichinhos estão famintos.', '', 28153),
(142002, 'ptBR', 'Arrebentar!', '', 28153),
(142001, 'ptBR', 'Devolvam... meu corpo... aos mares...', '', 28153),
(142000, 'ptBR', 'Não é fácil... achar... bons ajudantes...', 'Não é fácil... achar... bons ajudantes...', 28153),
(141999, 'ptBR', 'Você vai... levar uma advertência... por isso...', 'Você vai... levar uma advertência... por isso...', 28153),
(141998, 'ptBR', 'Ahhh... diacho...', 'Ahhh... diacho...', 28153),
(141997, 'ptBR', 'Nada sobrevive às profundezas.', '', 28153),
(141996, 'ptBR', 'Isso... é o seu... melhor?', 'Isso... é o seu... melhor...', 28153),
(141995, 'ptBR', 'Verme... imprestável...', 'Verme... imprestável...', 28153),
(141994, 'ptBR', 'Eu mandei você parar?!', 'Eu mandei você parar?!', 28153),
(141993, 'ptBR', 'Pulverizado!', '', 28153),
(141992, 'ptBR', 'Eu vou te usar para dar exemplo!', 'Eu vou te usar pra dar exemplo!', 28153),
(141991, 'ptBR', 'A pausa acabou, inseto!', 'A pausa acabou, inseto!', 28153),
(141990, 'ptBR', 'Você vai se arrepender de me irritar!', 'Você vai se arrepender de me irritar!', 28153),
(141989, 'ptBR', 'Você se atreve a sair da linha?!', 'Você se atreve a sair da linha?!', 28153),
(141988, 'ptBR', 'Quem desobedece, tem que pagar!', 'Quem desobedece, tem que pagar!', 28153),
(141987, 'ptBR', 'Você não nasceu pra isso.', '', 28153),
(141986, 'ptBR', 'Em fila!', 'Em fila!', 28153),
(141985, 'ptBR', 'De volta ao trabalho, verme!', 'De volta ao trabalho, verme!', 28153),
(141984, 'ptBR', 'Energia em nível crítico.', '', 28153),
(141983, 'ptBR', 'Reinicialização do sistema necessária.', '', 28153),
(141982, 'ptBR', 'O mar será o seu túmulo!', '', 28153),
(141981, 'ptBR', 'Entidade estranha detectada na porta A.', '', 28153),
(141980, 'ptBR', 'Unidade desativada.', '', 28153),
(141979, 'ptBR', 'Falha em protocolo de colheita.', '', 28153),
(141978, 'ptBR', 'Teus ossos ficarão a cinco braças!', '', 28153),
(141977, 'ptBR', 'Integridade estrutural: 0%%.', '', 28153),
(141976, 'ptBR', 'Vazamento detectado.', '', 28153),
(141975, 'ptBR', 'Sistema fora do ar.', '', 28153),
(141974, 'ptBR', 'Entidade hostil identificada.', '', 28153),
(141973, 'ptBR', 'Ativando contramedidas.', '', 28153),
(141972, 'ptBR', 'Inicializando servomecanismos de ceifa.', '', 28153),
(141971, 'ptBR', 'Alerta de intruso.', '', 28153),
(141970, 'ptBR', 'Usuário não autorizado.', '', 28153),
(141969, 'ptBR', 'Sequência de ataque iniciada.', '', 28153),
(141968, 'ptBR', 'Atacando.', '', 28153),
(141967, 'ptBR', 'Ameaça detectada.', '', 28153),
(141966, 'ptBR', 'Artilharia! Tirem esse lixo do meu campo de batalha!', '', 28153),
(141965, 'ptBR', 'Canhões! Disparar na minha área!', '', 28153),
(141964, 'ptBR', 'Dormiu, a onda leva!', '', 28153),
(141963, 'ptBR', 'Prepare-se para morrer!', '', 28153),
(141962, 'ptBR', 'Eu vou matar você!', '', 28153),
(141961, 'ptBR', 'Sinta o aço!', '', 28153),
(141960, 'ptBR', 'É o que podemos esperar da Horda.', '', 28153),
(141959, 'ptBR', 'Que deselegante!', '', 28153),
(141958, 'ptBR', 'O mar comerá seus ossos!', '', 28153),
(141957, 'ptBR', 'Vocês... não merecem... vencer...', '', 28153),
(141956, 'ptBR', 'Seu fim está próximo, escória da Horda!', '', 28153),
(141955, 'ptBR', 'Por Boralus!', '', 28153),
(141954, 'ptBR', 'O inimigo está nos cercando!', '', 28153),
(141953, 'ptBR', 'Cuidado!', '', 28153),
(141952, 'ptBR', 'Por aqui!', '', 28153),
(141951, 'ptBR', 'Por aqui!', '', 28153),
(141950, 'ptBR', '', 'Veste essa armadura com orgulho, $p. Será uma honra eterna, tua presença no Exército da Luz.', 28153),
(141949, 'ptBR', '', 'Em tuas jornadas, tu foste o farol da Luz nas escuridão. Tu mostraste à Aliança o que significa ser Forjado a Luz.', 28153),
(141948, 'ptBR', '', 'Vem, encontra-me na Vindicaar. Está na hora de recompensar tua dedicação.', 28153),
(141947, 'ptBR', '', 'O serviço que tu prestaste à Aliança é inestimável, $p. Eu não teria feito melhor. Digo, até teria... Mas apenas um pouco melhor.', 28153),
(141946, 'ptBR', 'Atacar!', '', 28153),
(141945, 'ptBR', 'Queima!', '', 28153),
(141944, 'ptBR', '', 'Eu tenho a honra de lhe dar a armadura do nosso povo. Aonde quer que você vá, ela será o lembrete das suas origens.', 28153),
(141943, 'ptBR', '', 'Nos tempos mais sombrios, você foi forte, valente, firme. Graças a você, $p, a Horda sabe o que significa ser da Alta Montanha.', 28153),
(141942, 'ptBR', 'Toma ganchada!', '', 28153),
(141941, 'ptBR', '', 'Agora, o Totem do Trovão chama você de volta. Está na hora de agradecer por tudo que você fez pela gente.', 28153),
(141940, 'ptBR', '', 'Você já trilhou muitos caminhos por toda Azeroth, $p. E nesse meio tempo, trouxe honra para Alta Montanha.', 28153),
(141939, 'ptBR', 'Vem aqui!', '', 28153),
(141938, 'ptBR', 'Você é o próximo!', '', 28153),
(141937, 'ptBR', 'Você não pode fugir!', '', 28153),
(141936, 'ptBR', 'Eu vou devorar suas entranhas!', '', 28153),
(141935, 'ptBR', 'A Câmera S.E.L.F.I.E. captura o Filtro Argus!', 'A Câmera S.E.L.F.I.E. captura o Filtro Argus!', 28153),
(141934, 'ptBR', 'A Câmera S.E.L.F.I.E. captura o Filtro Gélido Lamento!', 'A Câmera S.E.L.F.I.E. captura o Filtro Gélido Lamento!', 28153),
(141933, 'ptBR', 'A Câmera S.E.L.F.I.E. captura o Filtro Sha!', 'A Câmera S.E.L.F.I.E. captura o Filtro Sha!', 28153),
(141932, 'ptBR', 'A Câmera S.E.L.F.I.E. captura o Filtro Terras do Fogo!', 'A Câmera S.E.L.F.I.E. captura o Filtro Terras do Fogo!', 28153),
(141931, 'ptBR', 'A Câmera S.E.L.F.I.E. captura o Filtro Crepúsculo!', 'A Câmera S.E.L.F.I.E. captura o Filtro Crepúsculo!', 28153),
(141930, 'ptBR', 'Não me joguem no lixo...', '', 28153),
(141929, 'ptBR', 'Mas que petiscos suculentos!', '', 28153),
(141928, 'ptBR', 'Mais isca pra jogar na água!', '', 28153),
(141927, 'ptBR', '|TInterface\\Icons\\Ability_Argus_WastingPlague:20|tVocê foi afligido pela |cFFFF0000|Hspell:248396|h[Praga Anímica]|h|r!', '|TInterface\\Icons\\Ability_Argus_WastingPlague:20|tVocê foi afligido pela |cFFFF0000|Hspell:248396|h[Praga Anímica]|h|r!', 28153),
(141926, 'ptBR', 'Isso é que eu chamo de corte de primeira!', '', 28153),
(141925, 'ptBR', 'Vou fazer picadinho de vocês!', '', 28153),
(141924, 'ptBR', '<O pescador observa fixamente a água, resmungando sozinho. Ele tem os lábios rachados, as mãos ensaguentadas e o corpo coberto de cortes e arranhões, provavelmente provocados pelas aves de rapina que pululam na costa.\n\nParece que não sai dali há dias. \n\nÉ evidente que está sob o feitiço do conventículo, mas ao contrário dos outros, ele consegue se mexer e falar, ainda que não se dirija a você com a sua aproximação.>', '', 28153),
(141923, 'ptBR', 'Ovelhas para o matadouro.', '', 28153),
(141922, 'ptBR', '', 'Lembre-se sempre de quem você é. Se sentir saudade de casa, saiba que a Alta Montanha estará de portas abertas. Sempre.', 28153),
(141921, 'ptBR', '', 'Vá até Orgrimmar. Conheça nossos novos aliados e descubra com o que eles se preocupam... e pelo que eles lutam.', 28153),
(141920, 'ptBR', '', 'Hoje você dará início a uma nova jornada, $p. Você será a nossa voz nas terras além da montanha.', 28153),
(141919, 'ptBR', '', 'Está na hora de mudarmos isso.', 28153),
(141918, 'ptBR', '', 'Por muitos anos, nosso povo chamou as Ilhas Partidas de lar. Pouco sabíamos de Azeroth, essa terra de além-mar.', 28153),
(141917, 'ptBR', 'Ouvi dizer que há espiões! E agora, o que faço?', 'Ouvi dizer que há espiões! E agora, o que faço?', 28153),
(141916, 'ptBR', '', 'E nunca deixa de trilhar o caminho da Luz, $p.', 28153),
(141915, 'ptBR', '', 'Teu dever começa em Ventobravo. Explora este mundo de Azeroth. Conhece o povo e os lugares que juramos defender.', 28153),
(141914, 'ptBR', '', 'Mas não podemos baixar as guardas. Uma guerra termina, outra começa. Essa é a sina do soldado.', 28153),
(141913, 'ptBR', '', 'Agora, pela primeira vez em eras, podemos caminhar sob um céu livre da corrupção da Legião... e sentir a terra sob nossos cascos.', 28153),
(141912, 'ptBR', '', 'Por milhares de anos, os Forjados a Luz combateram demônios na Espiral Etérea. A Xenedar era nosso único lar.', 28153),
(141911, 'ptBR', 'Ah, chegaste bem na hora. Tu serás testemunha de como um soldado se torna Forjado a Luz. Prossegue, Fareeya.', '', 28153),
(141910, 'ptBR', '', 'Sabes como eu gosto dos teus discursos, mas não será melhor esperar? Estamos prestes a enviar esses novatos para a provação.', 28153),
(141909, 'ptBR', 'De fato. Ele está ansioso para ver o Exército da Luz lutando ao lado da Aliança. Junta nossas forças, capitã, que farei o pronunciamento.', '', 28153),
(141908, 'ptBR', '', 'Eu não te esperava tão cedo, Alto-exarca. Correu tudo bem no teu encontro com o rei?', 28153),
(141905, 'ptBR', 'Amarante! Pelas profundezas...', '', 28153),
(141902, 'ptBR', 'Volte para o caos que te criou!', '', 28153),
(141901, 'ptBR', 'O Penhasco do Trovão vai se livrar de você!', '', 28153),
(141900, 'ptBR', 'Como é bom brandir minha maça outra vez!', '', 28153),
(141899, 'ptBR', 'Expulsaremos a sua sombra de Mulgore!', '', 28153),
(141898, 'ptBR', 'Pela Aliança!', '', 28153),
(141897, 'ptBR', 'Pela Aliança!', '', 28153),
(141896, 'ptBR', 'Costumo me perguntar se ele tem razão.', '', 28153),
(141895, 'ptBR', 'Precisaremos dessas duas qualidades num futuro bem próximo. E obrigado por nos ajudar a trazê-los para o nosso lado, $p.', '', 28153),
(141894, 'ptBR', 'Por mil anos, eu lutei ao lado desses draeneis na Espiral Etérea. Tu não encontrarás soldados mais habilidosos e leais do que eles.', '', 28153),
(141893, 'ptBR', 'A força dos Forjados a Luz é mais do que bem-vinda em nossas fileiras, Alto-exarca.', '', 28153),
(141892, 'ptBR', 'Alto-rei Wrynn. O Exército da Luz jura defender a Aliança.', '', 28153),
(141891, 'ptBR', 'O Lorde Trovamare agora proíbe esses rituais. Ele está concentrando na construção de novas naus.', '', 28153),
(141890, 'ptBR', 'Quando eu vasculho a superfície da água, encontro uma tempestade tenebrosa que nubla minha visão.', '', 28153),
(141889, 'ptBR', '', 'Você sabe onde está a frota?', 28153),
(141888, 'ptBR', 'A Casa Trovamare mudou quando a frota não voltou.', '', 28153),
(141887, 'ptBR', 'Um dos meus irmãos... e respostas, espero.', '', 28153),
(141886, 'ptBR', '', 'E o que encontraremos lá, exatamente?', 28153),
(141885, 'ptBR', 'A Praia do Marujo fica bem perto daqui. Venha.', '', 28153),
(141884, 'ptBR', 'Fiquem no chão!', '', 28153),
(141883, 'ptBR', '', 'Nenhum de vocês vai voltar de Nazmir. Nosso pobre Rei, perdendo a própria filha pra essa cruzada idiota!', 28153),
(141882, 'ptBR', 'Eu tô indo pra Nazmir, $n. Se prepara, não sobrou nada lá além de troll sangrento e vodu negro.', '', 28153),
(141881, 'ptBR', '', 'Meus bichos não vão virar comida de troll sangrento! Ninguém volta de Nazmir.', 28153),
(141880, 'ptBR', 'Mas, antes de você ir, deixe eu falar sobre os três próximos santuários.', '', 28153),
(141879, 'ptBR', 'É um lugar chamado Zandalar. Talvez você tenha que fretar um barco, porque é praticamente do outro lado do mundo.', '', 28153),
(141878, 'ptBR', 'Acho que sei onde ficam mais alguns, mas é em território hostil.', '', 28153),
(141877, 'ptBR', 'Enquanto você estava fora, eu dei uma olhada no diário para tentar descobrir se há outros santuários.', '', 28153),
(141876, 'ptBR', '', 'Com prazer, Alto-exarca.', 28153),
(141875, 'ptBR', 'Está na hora de voltarmos a Ventobravo. Fareeya, espalha a notícia. Os Forjados a Luz agora lutam pela Aliança.', '', 28153),
(141874, 'ptBR', 'T\'paartos é um tanto... fora do comum. Mas ele servirá bem à nossa causa.', '', 28153),
(141873, 'ptBR', 'T\'paartos!', '', 28153),
(141872, 'ptBR', '', 'Pheta thones gamera. Luz, abre nossos caminhos!', 28153),
(141871, 'ptBR', 'Deste dia em diante, tu és um Forjado a Luz.', '', 28153),
(141870, 'ptBR', 'T\'paartos sente muito.', '', 28153),
(141869, 'ptBR', 'Dá uma fungada no bafo do Wees\'ki. Eita!', '', 28153),
(141868, 'ptBR', 'A gente acabou de ter a melhor noite de todas. Pena que não lembro de nadinha.\n\nPelo menos tem ovo de dino pro café da manhã!', '', 28153),
(141867, 'ptBR', 'Eu e meus caçadores sombrios vamos fazer reconhecimento adiante. E você, $n, te confio a guarda da princesa.', '', 28153),
(141866, 'ptBR', 'Tu tá lembrando o que rolou ontem à noite?\n\nNem eu.', '', 28153),
(141865, 'ptBR', 'Princesa, a Horda vai mandar reforços logo, logo. Eu acho que a gente não tem tempo pra se meter nisso.', '', 28153),
(141864, 'ptBR', 'Ungh... eu tenho que começar... a me cuidar melhor...', '', 28153),
(141863, 'ptBR', 'Vai na frente. Eu vou me curar... só preciso de... AIII! Eu... só preciso de um tempo.', '', 28153),
(141862, 'ptBR', 'A gente não tem tempo pra isso! \n\nA Horda vai mandar reforços em breve. A gente vai precisar de um porto pra receber essa galera.', '', 28153),
(141861, 'ptBR', '', 'Desta vez, há muitos deles! Fogo!', 28153),
(141860, 'ptBR', 'Eu bem que gostaria de saber.', '', 28153),
(141859, 'ptBR', '', 'O que está acontecendo aqui, irmão?', 28153),
(141858, 'ptBR', '', 'Cidadãos, debandar já!', 28153),
(141857, 'ptBR', 'Você não tomará o tesouro do meu mestre. Prepare-se para encarar sua aniquilação!', '', 28153),
(141856, 'ptBR', 'QUEM SE ATREVE A ENTRAR NA CAIXA-FORTE?!', '', 28153),
(141855, 'ptBR', '', 'Quando você atrair a atenção deles, eu os tiro daqui.', 28153),
(141852, 'ptBR', 'O medo... ele seguiu T\'paartos por toda a parte!', '', 28153),
(141851, 'ptBR', 'T\'paartos se arrepende de chamar você, $p, de fracote.', '', 28153),
(141850, 'ptBR', 'T\'paartos não sente medo!', '', 28153),
(141849, 'ptBR', 'Aqui, amigo!', '', 28153),
(141848, 'ptBR', 'Cuidado!', '', 28153),
(141847, 'ptBR', 'Por aqui!', '', 28153),
(141846, 'ptBR', 'Por aqui!', '', 28153),
(141845, 'ptBR', 'Já tomamos o carregamento de azerita, e os guardas Grimpagris estão sob nosso controle. A prisão é nossa.', 'Já tomamos o carregamento de azerita e os guardas Grimpagris estão sob nosso controle. A prisão é nossa.', 28153),
(141844, 'ptBR', 'Espero que Korgus tenha pagado por toda a crueldade.', 'Espero que Korgus tenha pagado por toda a crueldade.', 28153),
(141843, 'ptBR', 'Muito obrigado!', 'Muito obrigada!', 28153),
(141842, 'ptBR', 'Já protegemos os prisioneiros e garantimos o perímetro. Os andares de baixo são nossos.', 'Já protegemos os prisioneiros e garantimos o perímetro. Os andares de baixo são nossos.', 28153),
(141841, 'ptBR', '', 'Imediatamente, Alto-exarca.', 28153),
(141840, 'ptBR', 'Fareeya, preciso de um sinalizador para a Vindicaar.', '', 28153),
(141839, 'ptBR', 'Por aqui, $Gcampeão:campeã;.', '', 28153),
(141838, 'ptBR', 'Assim será, Alto-rei.', '', 28153),
(141837, 'ptBR', 'Eu estou ansioso pela entrada dos Forjados a Luz na Aliança. Turalyon, leve o campeão à Vindicaar, assim vocês podem instruir as tropas juntos.', '', 28153),
(141836, 'ptBR', '', 'Eu gosto de você. Nunca está satisfeito, que nem eu. Esta é a sua busca pela perfeição.$B$BSabe, eu não tenho tanta certeza. Pegaram o melhor da engenharia goblínica e enfiaram nessa caixinha. Isso é receita para potencial sem limites.$B$BPor que você não encontra uma fonte de poder e... vê o que acontece? Não posso prometer nada.', 28153),
(141835, 'ptBR', '', 'Niko, mais luz! Ei, belezinha, não tinha visto você aí. O que posso fazer por você?', 28153),
(141834, 'ptBR', '', 'Sabe, eu não tenho como ter certeza! Tem uma engenharia pesada aí, então é provável que tenha uma função ou duas a mais.$B$BExperimente levar ela para perto de alguma fonte de poder. Vai ver assim ela pega no tranco!', 28153),
(141833, 'ptBR', 'Essa câmera tem alguma outra função?', 'Essa câmera tem alguma outra função?', 28153),
(141832, 'ptBR', 'Perdi minha câmera. Você poderia me arranjar outra?', 'Perdi minha câmera. Você poderia me arranjar outra?', 28153),
(141831, 'ptBR', '', 'Sistema Extrator de Luz Focalizada Incrivelmente Enaltecedor.', 28153),
(141830, 'ptBR', 'O que significa S.E.L.F.I.E.?', 'O que significa S.E.L.F.I.E.?', 28153),
(141829, 'ptBR', '', 'Ah, oi! Você queria tirar uma S.E.L.F.I.E. comigo?', 28153),
(141828, 'ptBR', 'Exigimos respostas, Pique!', 'Exigimos respostas, Pique!', 28153),
(141827, 'ptBR', 'Estão ocupados demais levando nossa colheita para os \"soldados\"!', 'Estão ocupados demais levando nossa colheita para os \"soldados\"!', 28153),
(141826, 'ptBR', 'Faz dias que a milícia não sai em patrulha!', 'Faz dias que a milícia não sai em patrulha!', 28153),
(141825, 'ptBR', 'A Cidade Baixa está sendo atacada! Vá para o Portal de Mago!', 'A Cidade Baixa está sendo atacada! Vá para o Portal de Mago!', 28153),
(141824, 'ptBR', 'Agora vamos ter que simplesmente abandonar tudo e evacuar para Orgrimmar?', 'Agora vamos ter que simplesmente abandonar tudo e evacuar para Orgrimmar?', 28153),
(141823, 'ptBR', 'Começaram a fechar os portões de repente. O que está acontecendo?', 'Começaram a fechar os portões de repente. O que está acontecendo?', 28153),
(141822, 'ptBR', 'Seguro ou não, eu não quero perder toda a minha mercadoria nessa guerra!', 'Seguro ou não, eu não quero perder toda a minha mercadoria nessa guerra!', 28153),
(141821, 'ptBR', 'Eu tenho que encontrar os meus amigos!', 'Eu tenho que achar meus amiguinhos!', 28153),
(141820, 'ptBR', 'Minha mãe disse que os soldados sempre cuidavam dos malvados. Pra onde os soldados foram?', 'Minha mãe disse que os soldados sempre cuidavam dos malvados. Pra onde os soldados foram?', 28153),
(141819, 'ptBR', 'Eu fiquei com tanto medo! Obrigado!', 'Eu fiquei com tanto medo! Obrigada!', 28153),
(141818, 'ptBR', 'Eu quero meu pai!', 'Eu quero meu pai!', 28153),
(141817, 'ptBR', 'Onde está a milícia?', 'Onde está a milícia?', 28153),
(141816, 'ptBR', 'Você me salvou. Muito obrigado!', 'Você me salvou. Muito obrigada!', 28153),
(141815, 'ptBR', 'Eles nunca nos atacaram com tanta virulência assim!', 'Eles nunca nos atacaram com tanta virulência assim!', 28153),
(141814, 'ptBR', 'Daqui em diante, eu posso me virar. Rezo para que os outros estejam bem!', 'Daqui em diante, eu posso me virar. Rezo para que os outros estejam bem!', 28153),
(141813, 'ptBR', 'Eu... não sei. Mayla, nós temos que seguir em frente. Baine, vá com o campeão, reúna os demais e nos encontre no cume.', '', 28153),
(141812, 'ptBR', 'Cria da... O que ele quis dizer?', '', 28153),
(141811, 'ptBR', 'Isso... venha! A sua força será nossa, cria da escuridão!', '', 28153),
(141810, 'ptBR', 'A última proteção foi colocada no Cume da Alta Montanha. É para lá que temos que ir. Assim como Huln lutou ao lado de seus aliados, nós também temos que ficar juntos.', '', 28153),
(141809, 'ptBR', 'Exato. E quando eu deixei a montanha para visitar Mulgore, as proteções se enfraqueceram, e a Escuridão se infiltrou.', '', 28153),
(141808, 'ptBR', '', 'Todo esse tempo, os Necrotrevas estavam à espreita nas sombras, esperando a ordem do mestre.', 28153),
(141807, 'ptBR', 'Então Huln traçou outro plano. As proteções foram colocadas para afastar a influência dos Deuses Antigos. Embora o general tenha sobrevivido, a essência de Uul\'gyneth foi aprisionada.', '', 28153),
(141806, 'ptBR', 'Huln reuniu heróis de várias tribos. Eles lutaram contra os servos de Uul\'gyneth, os Necrotrevas... mas as forças das sombras eram fortes demais.', '', 28153),
(141805, 'ptBR', 'Tempos atrás, os Deuses Antigos tentaram tomar a Alta Montanha. Essa investida foi liderada por uma terrível criatura... Uul\'gyneth, a Escuridão.', '', 28153),
(141804, 'ptBR', '', 'Mas nosso trabalho ainda não acabou. Chifre de Ébano, temos que descobrir o que a Escuridão quer.', 28153),
(141803, 'ptBR', 'Saudações! Griscéu me contou da sua bravura.', '', 28153),
(141802, 'ptBR', 'Minha mente me pertence de novo. Volte ao Totem do Trovão. Vamos reunir forças para encarar o que está por vir.', '', 28153),
(141801, 'ptBR', '', 'Anda logo! Já dá para ouvir eles.', 28153),
(141800, 'ptBR', '', 'Eu ficarei aqui enquanto Griscéu ajuda você. Rezo para que as proteções curem a mente de Chifre de Ébano.', 28153),
(141799, 'ptBR', '', 'As águas acalmaram Chifre de Ébano, mas temo que ele esteja sucumbindo.', 28153),
(141798, 'ptBR', 'Vá até Alta Montanha e ajude Mayla. Eu me juntarei a vocês em breve.', '', 28153),
(141797, 'ptBR', 'Preciso garantir que os lacaios dos Deuses Antigos sejam expulsos de Mulgore.', '', 28153),
(141796, 'ptBR', 'Seus mestres não tomarão minha cidade, seu monstro!', '', 28153),
(141795, 'ptBR', 'Destruam-nos! Não deixem que atrapalhem meu retorno!', '', 28153),
(141794, 'ptBR', '', 'Os trolls sangrentos vão ficar invencíveis se soltarem aquele monstro. Mesmo contigo e com a Horda do nosso lado, não vai ter jeito. Precisamos de um novo plano.', 28153),
(141793, 'ptBR', '', 'Eles não estão atrás da gente. Acho que a barra tá limpa.', 28153),
(141792, 'ptBR', 'Pois bem. Vamos expulsar esses deuses malditos do Penhasco do Trovão.', '', 28153),
(141791, 'ptBR', '', 'Compreendo. Baine, preciso levar Chifre de Ébano de volta à Alta Montanha.', 28153),
(141790, 'ptBR', 'Mayla... Os lagos...', '', 28153),
(141789, 'ptBR', '', 'Não tenho medo de você nem dos seus monstros! Vou matar todos com as minhas próprias mãos!', 28153),
(141788, 'ptBR', '', 'Corre, princesinha! Nada vai te salvar do meu mestre! G\'huun vai te devorar!', 28153),
(141787, 'ptBR', '', 'Nós temos que avançar! Aguentem aí!', 28153),
(141786, 'ptBR', '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|tA Rainha d\'Areia se |cFFFF0000|Hspell:257609|h[Enfurece]|h|r!', '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|tA Rainha d\'Areia se |cFFFF0000|Hspell:257609|h[Enfurece]|h|r!', 28153),
(141784, 'ptBR', 'As proteções estão mais fracas! É o fim dele!', '', 28153),
(141783, 'ptBR', 'Juntos, retornaremos ao mar. Juntos, seremos novamente poderosos!', '', 28153),
(141782, 'ptBR', 'Nossos poderosos sábios das marés nos conduzirão à vitória com a força do próprio mar!', '', 28153),
(141781, 'ptBR', 'Temos que trabalhar juntos, unindo nossas forças. Kul Tiraz há de pertencer sempre ao seu povo!', '', 28153),
(141780, 'ptBR', 'A Casa Trovamare precisa tomar o controle deste reino despedaçado e lhe restaurar a glória de outrora!', '', 28153),
(141779, 'ptBR', 'Não trabalharemos mais nos campos, construindo navios, sem receber nada em troca da elite esnobe de Boralus.', '', 28153),
(141778, 'ptBR', 'Filhos do mar, o dia de hoje traz a aurora de uma nova era para todos nós.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141777, 'ptBR', 'Eu tive uma visão que pode te fazer mudar de ideia. Venha a mim, e eu te mostro.', '', 28153),
(141776, 'ptBR', '|TInterface\\Icons\\ACHIEVEMENT_ZONE_VASHJIR:20|tGolganneth escolheu você para receber a |cFFFF0000|Hspell:257306|h[Dádiva do Mar]|h|r!', '|TInterface\\Icons\\ACHIEVEMENT_ZONE_VASHJIR:20|tGolganneth escolheu você para receber a |cFFFF0000|Hspell:257306|h[Dádiva do Mar]|h|r!', 28153),
(141775, 'ptBR', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_AIR:20|tGolganneth escolheu você para receber a |cFFFF0000|Hspell:257313|h[Dádiva dos Céus]|h|r!', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_AIR:20|tGolganneth escolheu você para receber a |cFFFF0000|Hspell:257313|h[Dádiva dos Céus]|h|r!', 28153),
(141774, 'ptBR', 'Energia do sistema em nível baixo.', '', 28153),
(141773, 'ptBR', 'Seleção de alvo f-f-falhando...', '', 28153),
(141772, 'ptBR', 'Pontos de vida esgotando. Necessária assistência.', '', 28153),
(141771, 'ptBR', 'Defeito!', '', 28153),
(141770, 'ptBR', '', 'Santuário dourado? Deve ser Atal\'Dazar. É uma cidade. De ouro. Uma cidade dourada.$b$bMas santuário? De repente pro ouro. Ou pros dinossauros. Ou dinossauros banhados a ouro!$b$bEu tentaria lá!', 28153),
(141769, 'ptBR', 'Eles devem ter sido levados pra lá, pro topo da geleira a noroeste.', '', 28153),
(141768, 'ptBR', 'Você já ouviu falar de um tal \"santuário dourado\"?', 'Você já ouviu falar de um tal \"santuário dourado\"?', 28153),
(141767, 'ptBR', 'Sua missão é desentocar aqueles vermes, acabar com eles, e garantir que nossos cidadãos cheguem a Ogrimmar em segurança.', '', 28153),
(141766, 'ptBR', 'Isolamos os covardes no Distrito dos Magos para proteger o resto da cidade.', '', 28153),
(141765, 'ptBR', 'Os inimigos estão atacando a Cidade Baixa. O objetivo deles é tomar Lordaeron.', '', 28153),
(141764, 'ptBR', 'A Cidade Baixa não é mais segura para civis. A guerra ruge acima, e dezenas de espiões se infiltraram em nossas muralhas.', '', 28153),
(141762, 'ptBR', 'Soldados da Horda, a hora chegou!', '', 28153),
(141761, 'ptBR', '', 'Siga para o Vale da Honra quando chegar a Orgrimmar! Aqui não é seguro!', 28153),
(141760, 'ptBR', '', 'Meu portal está aberto. Temos que evacuar!', 28153),
(141759, 'ptBR', '', 'Siga para Orgrimmar! Não é seguro aqui!', 28153),
(141758, 'ptBR', 'Belo... tiro...', '', 28153),
(141757, 'ptBR', 'Pode correr à vontade. Eu nunca erro.', '', 28153),
(141756, 'ptBR', 'Vocês vão morrer no tiro cruzado!', '', 28153),
(141755, 'ptBR', 'Tô doido pra testar essas balas em alvos vivos.', '', 28153),
(141754, 'ptBR', 'Considerem-se reabilitados.', '', 28153),
(141753, 'ptBR', 'Aproveite seu último prato... de chumbo!', '', 28153),
(141752, 'ptBR', 'Eu sentencio você à morte!', '', 28153),
(141751, 'ptBR', 'Quanta gentileza... Vocês voltarem para morrer.', '', 28153),
(141750, 'ptBR', 'Lá vem bomba!', '', 28153),
(141749, 'ptBR', 'Sim, senhora!', '', 28153),
(141748, 'ptBR', '', 'Eu quero mais fogo! Mais fogo!', 28153),
(141747, 'ptBR', '', 'Mais lenha para as chamas! Depressa!', 28153),
(141746, 'ptBR', '', 'Vou reduzir vocês a cinzas!', 28153),
(141745, 'ptBR', '', 'Queimem na fogueira!', 28153),
(141744, 'ptBR', '', 'A noite é escura e cheia de terrores!', 28153),
(141743, 'ptBR', 'Você machucou meu amigo!', '', 28153),
(141742, 'ptBR', '', 'A estrela mais forte... é a que queima... mais depressa.', 28153),
(141741, 'ptBR', 'Você vai pagar pelo que fez!', '', 28153),
(141740, 'ptBR', 'Você distrai eles, eu meto a faca.', '', 28153),
(141739, 'ptBR', '', 'A gente tem que achar a arma antes que Jakra\'zet bote as mãos nela.', 28153),
(141738, 'ptBR', '', 'Não faço ideia do que é a tal arma, ou de onde ela tá, mas se o Jakra\'zet tá escondendo do rei, coisa boa não pode ser.', 28153),
(141737, 'ptBR', '', 'Eles tão passando um pente fino nas dunas, procurando uma arma capaz de destruir a cidade, matando quem fica no caminho.', 28153),
(141736, 'ptBR', '', 'Como eu suspeitava. O General Jakra\'zet tem tropas no deserto, sem o conhecimento do rei.', 28153),
(141735, 'ptBR', 'Prospectando', 'Prospectando', 28153),
(141734, 'ptBR', 'Pode ter certeza! Vem cá, $Gmoleque:menina;. Eu tenho um serviço pra você.', '', 28153),
(141733, 'ptBR', 'Ei, Rufino! Ess$Ue:a; jovem tem potencial! Tá precisando de algum serviço?', '', 28153),
(141732, 'ptBR', '', 'Eu gosto de bolhas. Me sinto segura!', 28153),
(141731, 'ptBR', 'Você acredita que tem cidades por aí sem nenhuma bolhinha mágica em volta? Como esse povo faz para não juntar poeira? Selvagens.', '', 28153),
(141730, 'ptBR', '', 'Pensei que eu não ia ver ela nunca mais...', 28153),
(141729, 'ptBR', 'Vão voltando as memórias, vai voltando a dor...', '', 28153),
(141728, 'ptBR', '', 'Esse aí não aguentou o calor!', 28153),
(141727, 'ptBR', '', 'Hmmm... Chega a carne dele derrete!', 28153),
(141726, 'ptBR', '', 'Vou usar seus corpos de combustível.', 28153),
(141725, 'ptBR', '', 'Estou louca para derreter vocês.', 28153),
(141724, 'ptBR', '', '$p, vem rápido! A memória da Rakera tá voltando!', 28153),
(141723, 'ptBR', 'Era você... quem devia... sangrar...', '', 28153),
(141722, 'ptBR', '', 'Minha cabeça... Jaka, é você?', 28153),
(141721, 'ptBR', 'Hora da caçada!', '', 28153),
(141720, 'ptBR', 'Vocês mataram meu irmão. Eu vou retalhar vocês em mil pedaços.', '', 28153),
(141719, 'ptBR', 'Maninho!', '', 28153),
(141718, 'ptBR', 'Se apruma, irmãozinho! Temos muito o que matar.', '', 28153),
(141717, 'ptBR', 'Depressa, homens! Mostrem quem é que manda por aqui!', '', 28153),
(141716, 'ptBR', 'Eu amolei essas aqui pra vocês.', '', 28153),
(141715, 'ptBR', 'Mas eu ia... conseguir... a condicional...', '', 28153),
(141714, 'ptBR', 'Vocês deviam ter ficado nas celas.', '', 28153),
(141713, 'ptBR', 'Me mande para Ulduar. (Raide de Caminhada Temporal)', 'Me mande para Ulduar. (Raide de Caminhada Temporal)', 28153),
(141712, 'ptBR', '', 'Saudações, $n. Você não deve se lembrar de mim, nós nos encontramos semana que vem.$b$bGostaria de revisitar Ulduar?', 28153),
(141711, 'ptBR', 'Eu sou o macho alfa!', '', 28153),
(141710, 'ptBR', 'Mais um morto.', '', 28153),
(141709, 'ptBR', 'Baaah! Carne fresca!', '', 28153),
(141708, 'ptBR', 'Enfraqueça o grifo sem perder a firmeza com |TInterface\\ICONS\\INV_MISC_DESECRATED_LEATHERGLOVE.BLP:20|t |cFFFF0000|Hspell:269442|h[Segura Firme]|h|r', '', 28153),
(141707, 'ptBR', 'Tudo pronto para partir.', 'Tudo pronto para partir.', 28153),
(141706, 'ptBR', '', 'Ao trabalho.', 28153),
(141705, 'ptBR', '', 'Agora tá tranquilo. Vamos ter que ir rápido depois de desembarcar nas Ruínas de Zul\'jan.', 28153),
(141704, 'ptBR', '', 'Os trolls sangrentos são cruéis e infinitos, se alimentando do poder de um deus antigo.', 28153),
(141703, 'ptBR', '', 'Que bom que você percebeu isso, Mathiaz. Você tá um passo à frente do meu pai.', 28153),
(141701, 'ptBR', '', 'Mortos-vivos! Marchando pra Zuldazar! Temos que acabar com eles!', 28153),
(141696, 'ptBR', 'Parece que o patuá não está funcionando. Teste em alguns servos amaldiformados primeiro.', '', 28153),
(141695, 'ptBR', 'Esse cara não parece muito esperto.', '', 28153),
(141694, 'ptBR', 'Caudassorte corre para as cachoeiras!', '', 28153),
(141693, 'ptBR', '', '', 28153),
(141692, 'ptBR', '|cffffff00+$1i Sobras de Armadura|r', '|cffffff00+$1i Sobras de Armadura|r', 28153),
(141691, 'ptBR', 'Caudassorte foge para se esconder!', '', 28153),
(141690, 'ptBR', '', 'O que os sectários fizeram com a Rakera... Ela não lembra nem do próprio nome.', 28153),
(141689, 'ptBR', 'Você! É, você. Chega mais, na maciota. Não chama atenção.', '', 28153),
(141688, 'ptBR', '', 'O que fizeram contigo...', 28153),
(141687, 'ptBR', '', 'Todos somos Akunda.', 28153),
(141686, 'ptBR', '', 'Rakera?', 28153),
(141685, 'ptBR', '', 'Ela tá aqui! Ela tá viva! Rakera!', 28153),
(141684, 'ptBR', '', 'Rakera!', 28153),
(141683, 'ptBR', '', 'Alguém nesse templo estranho deve saber de alguma coisa.', 28153),
(141682, 'ptBR', 'Não estou nem aí pras suas mutretas com o Rei e a filha dele. Tu não é bem-vind$Go:a; em Zuldazar.$b$bE por mais que a Princesa tenha autoridade, ela não é rainha ainda.$b$bAté lá, o verdadeiro poder de Zuldazar está comigo e com o Conselho Zanchuli.', '', 28153),
(141681, 'ptBR', '', 'Esta é uma cerimônia oficial. Não interrompe.', 28153),
(141680, 'ptBR', 'Agora T\'paartos sabe disso.', '', 28153),
(141679, 'ptBR', 'Todos temos a escuridão dentro de si. Essa é uma verdade dura de aceitar.', '', 28153),
(141678, 'ptBR', '', 'T\'paartos... Tu confrontaste teus medos, teus fracassos... e renasceste.', 28153),
(141677, 'ptBR', '', 'Seja bem-vindo de volta, T\'paartos.', 28153),
(141676, 'ptBR', '', 'Se a Rakera estiver neste templo, a gente vai encontrar ela.', 28153),
(141675, 'ptBR', 'Você tem um cheiro estranho! Raauuuttt!', '', 28153),
(141674, 'ptBR', 'Desculpa! Vocês têm cheiro de cocô de papagaio! Currupaco!', '', 28153),
(141673, 'ptBR', 'Currupaco! Kragg morreu! Isca de Tubarão pede desculpa!', '', 28153),
(141672, 'ptBR', '', 'Ah, um membro da Horda. Curioso...', 28153),
(141671, 'ptBR', '$n atacou as forças da Aliança na Serraria!', '$n atacou as forças da Aliança na Serraria!', 28153),
(141669, 'ptBR', '', 'O poder dos loas aqui é tão grande que dá vida até pros ventos. Pa\'kul voa em algum lugar desse céu, eu sinto a presença dela.$b$bEu nunca tinha botado os pés em Zandalar, mas meu avô contava muitas histórias daqui.', 28153),
(141668, 'ptBR', '', 'Os loas tão poderosos aqui. Dá pra sentir a presença do meu loa, Gonk, na maciota atrás de cada árvore e arbusto.$b$bGonk tá perto. Vai ser maneiríssimo ver ele em pessoa.', 28153),
(141667, 'ptBR', 'Nós não vamos nos render. Soldados, retomem a Serraria!', '', 28153),
(141666, 'ptBR', 'Saudações, pequenin$Uo:a;.$b$bEu sou o Senhor da Bagata Raal, o primeiro entre os seguidores de Pa\'kul, loa dos ventos, e membro do Conselho Zanchuli.$b$bEu sou muito importante e muito ocupado. O que você quer?', '', 28153),
(141665, 'ptBR', '', 'Nosso tempo com o Senhor da Bagata é curto. Não vem interromper. Temos muito pra discutir.', 28153),
(141664, 'ptBR', 'Meu amigo!', '', 28153),
(141663, 'ptBR', '', 'Agora os sethraks vão aprender a temer os vulperas!', 28153),
(141662, 'ptBR', 'O General Jakra\'zet, aquele troll Zangareia arrogante que comanda os militares de Zuldazar, decidiu retirar os guardas dele do porto.\n\nNem todos os trolls gostaram do decreto da Princesa Talanji de permitir a entrada de outras raças ali, pelo jeito. \n\nEla vai precisar de pelo menos um membro do Conselho Zanchuli pra ajudar nessa. Por sorte, eu sei onde achar dois.', '', 28153),
(141660, 'ptBR', '', 'Os vulperas podem ser tudo, menos fracos. Vamos botar medo neles!', 28153),
(141658, 'ptBR', 'Drenando', 'Drenando', 28153),
(141657, 'ptBR', '', 'Esses sethraks vão pagar pelo que fizeram com o nosso lar.', 28153),
(141655, 'ptBR', 'Não, não se preocupe comigo, $Gshenhor:shenhora;. -hic!- Eu shó vou sheguir meu caminho... hã... onde diabo eu tô?$b$bEshcuta aqui, deixa eu ficar maish shóbrio aqui e quando vochê voltar, eu vou eshtar melhor. Eu juro.', '', 28153),
(141654, 'ptBR', 'Haha, esha é a parte engrachada. Eshcuta, ele acabou consheguindo sher -hic!- preso! Aquele eshtúpido tentou matar alguém.$b$bBotaram ele na prisjão com o reshto dosh inutéish -hic!-. She ainda tiver com ele, eu aposhto -hic!- que o único jeito de tirar dele é arrancando -hic!- dash mãosh do cadáver.$b$bVochê num vai tentar me matar também não, né? -hic!- Eu nunca fizsh nada pra vochê.$b$bEshcuta, eu vou shair daqui e achar um lugar pra pashar eshe pileque -hic!-. Promesha de marinheiro, haha.', '', 28153),
(141653, 'ptBR', 'Onde está esse sujeito que pegou a joia?', 'Onde está esse sujeito que pegou a joia?', 28153),
(141652, 'ptBR', 'Aquele filho de baiacu deu no pé com nosha -hic!- joia. A gente pashou o maior tempo lapidando esha porcaria e aí o que ele fazsh? -hic!-$b$bDesapareche no meio da -hic!- noitche! A gente ia vender aquele treco e ficar ricosh pra chuchu! -hic!-$b$b<Salton toma outro gole do frasco.>$b$bPor acasjo $Go shenhor:a shenhora; tem algum ouro shobrando aí?', '', 28153),
(141651, 'ptBR', '', 'Tudo pronto. Vamos caçar uns sethraks.', 28153),
(141649, 'ptBR', 'Diz a Princesa Talanji que precisa da tua ajuda com Jakra\'zet.', 'Diz a Princesa Talanji que precisa da tua ajuda com Jakra\'zet.', 28153),
(141648, 'ptBR', '', 'Tu tá diante da Druidesa-de-guerra Loti, devota de Gonk, campeão da caçada e mestre das trilhas. O que tu quer, $c?', 28153),
(141647, 'ptBR', 'Liguem as serras! Precisamos de mais madeira.', '', 28153),
(141646, 'ptBR', 'Ah, tá rolando um probleminha. Jakra\'zet se recusa a cumprir a vontade da Princesa.$b$bEu preciso da ajuda de outro membro do Conselho Zanchuli, mas os dois presentes na área tão ocupados com uma disputa tribal.$b$bVai atrás de Tal\'aman ou Tal\'farrak e vê se consegue convencer um dos dois conselheiros a dar uma moral.$b$bEu só não vou porque sou importante demais pra isso.', '', 28153),
(141645, 'ptBR', 'A Princesa Talanji quer saber onde estão os guardas.', 'A Princesa Talanji quer saber onde estão os guardas.', 28153),
(141644, 'ptBR', 'Assim que eu vi tua cara em Ventobravo, eu saquei que a profecia ia se cumprir.$b$bOs espíritos me mostram muita coisa e, nessas visões, eu vi tua cara na dianteira de muitos grandes eventos que tão pra acontecer.$b$bAs coisas tão em curso, $c. Daqui a pouco, eu e tu vamos chacoalhar este mundo.', '', 28153),
(141643, 'ptBR', 'Se eu fosse você, faria o mesmo. Boa sorte.', 'Se eu fosse você, faria o mesmo. Boa sorte.', 28153),
(141642, 'ptBR', 'Isso... aceita, T\'paartos. Abraça o verdadeiro poder!', '', 28153),
(141641, 'ptBR', 'Livra-te das correntes que a Luz usou para te prender.', '', 28153),
(141640, 'ptBR', 'A Luz não é o caminho que leva à verdadeira força.', '', 28153),
(141639, 'ptBR', 'Este poder pode ser nosso, T\'paartos.', '', 28153),
(141638, 'ptBR', 'A Luz sempre esteve com T\'paartos! Ele JAMAIS vai abandonar a Luz!', '', 28153),
(141637, 'ptBR', 'CHEGA!!!', '', 28153),
(141636, 'ptBR', 'Não...', '', 28153),
(141635, 'ptBR', 'Não... não pode ser. Este não é o T\'paartos que eu conheço!', '', 28153),
(141634, 'ptBR', 'Ugh! Será que $p pode dar um jeito nas cobras?', '', 28153),
(141633, 'ptBR', 'Isso... é um pouco embaraçoso para T\'paartos.', '', 28153),
(141632, 'ptBR', 'T\'paartos pode mover montanhas!', '', 28153),
(141631, 'ptBR', 'T\'paartos enfrentou muitos demônios no Exército da Luz.', '', 28153),
(141630, 'ptBR', 'Ahh, Ika. T\'paartos criou esse elekk depois que a mãe morreu.', '', 28153),
(141629, 'ptBR', 'Não! A escuridão não levará T\'paartos!', '', 28153),
(141628, 'ptBR', 'Esse é o caminho de T\'paartos? T\'paartos é digno de ser Forjado a Luz?', '', 28153),
(141623, 'ptBR', 'Você salvou minha pele de novo! Vou voltar ao acampamento antes que eu pegue um resfriado.', '', 28153),
(141620, 'ptBR', '', 'Não vá matá-los sem mim!', 28153),
(141619, 'ptBR', '', 'Os vulperas estão prontos. Os Ímpios nos temerão.', 28153),
(141618, 'ptBR', 'Mmmm... te pegar... mmmm...', '', 28153),
(141617, 'ptBR', 'Eu ia usjar aquele ouro pra me casjar <choramingando>.', '', 28153),
(141616, 'ptBR', 'Ashim que eu -hic!- consheguir um barco... eu vou te pegar!', '', 28153),
(141615, 'ptBR', 'Vochê pegou nosha joia, sheu eshper -hic!- talhão!', '', 28153),
(141614, 'ptBR', 'Vochê pegou nosha -hic!-...', '', 28153),
(141613, 'ptBR', 'Nisso que dá deixar a Nisha fazer os planos...', '', 28153),
(141612, 'ptBR', '', 'Eu duvido que ela conseguiria. A maioria do seu povo não consegue. Bem, não mais.', 28153),
(141611, 'ptBR', 'Cuidado, Meerah. Nossas carroças nem sempre rodam bem nas antigas estradas trólicas.', '', 28153),
(141610, 'ptBR', '', 'Os sethraks vão se arrepender de atacar nossa caravana.', 28153),
(141609, 'ptBR', 'Nada de folga nas cordas! Segurem firme!', '', 28153),
(141608, 'ptBR', '', 'Prontinho, $n. A tradução do seu diário. Uma leitura eletrizante, não dá pra desgrudar os olhos até o fim.', 28153),
(141607, 'ptBR', '', 'Sim? Sim! É isso! Onde estão meus livros em branco... Ah, aqui tem um.', 28153),
(141606, 'ptBR', '', 'AH! Então essa runa é ISSO. Interessante...', 28153),
(141605, 'ptBR', '', 'Você matou todos?! Excelente, $n. Agora, vamos à tradução deste diário.', 28153),
(141604, 'ptBR', '<O soldado está balbuciando coisas incoerentes em voz baixa.>', '<A soldada está balbuciando coisas incoerentes em voz baixa.>', 28153),
(141603, 'ptBR', 'Aqui estão os livros que você pediu.', 'Aqui estão os livros que você pediu.', 28153),
(141602, 'ptBR', 'O mar está enchendo ou estamos caindo?\n\nCada vez mais fundo...', 'O mar está enchendo ou estamos caindo?\n\nCada vez mais fundo...', 28153),
(141601, 'ptBR', 'Perfeito, perfeito, disse que tudo tinha que ficar perfeito...\n\nQuem disse isso?', 'Perfeito, perfeito, disse que tudo tinha que ficar perfeito...\n\nQuem disse isso?', 28153),
(141600, 'ptBR', 'Esses Zandalari vão ter uma surpresa em pouco tempo!', 'Esses Zandalari vão ter uma surpresa em pouco tempo!', 28153),
(141599, 'ptBR', 'Os crorgs tão crescendo que é uma beleza. Em pouco tempo vai dar pra montar neles.', 'Os crorgs tão crescendo que é uma beleza. Em pouco tempo vai dar pra montar neles.', 28153),
(141598, 'ptBR', 'Desculpa, ma\'ma. Eu vou sair do teu caminho bem depressa.', 'Desculpa, ma\'ma. Eu vou sair do teu caminho bem depressa.', 28153),
(141597, 'ptBR', 'É bom ir afiando bem essa faca. Disseram que a gente vai lutar contra os Zandalari.', 'É bom ir afiando bem essa faca. Disseram que a gente vai lutar contra os Zandalari.', 28153),
(141596, 'ptBR', 'Chefe Guerreira Sylvana Correventos, eu lhe apresento a Chefe Mayla Alta Montanha.', '', 28153),
(141595, 'ptBR', 'Um mochilão nosso. Parece que achamos o lugar.', '', 28153),
(141594, 'ptBR', 'Esse machado é nosso. Estamos no caminho certo.', '', 28153),
(141593, 'ptBR', 'Esse coitado morreu faz tempo. Vamos procurar a carroça pro leste.', '', 28153),
(141592, 'ptBR', 'Eu nunca te vi antes. Melhor tu entrar logo. Tá rolando um boato que o grupo de trabalho da Najima apareceu tudo morto.', 'Eu nunca te vi antes. Melhor tu entrar logo. Tá rolando um boato que o grupo de trabalho da Najima apareceu tudo morto.', 28153),
(141591, 'ptBR', 'A última proteção foi colocada no Cume da Alta Montanha. É para lá que temos que ir. Assim como Huln lutou ao lado de seus aliados, nós também temos que ficar juntos.', '', 28153),
(141590, 'ptBR', 'Exato. E quando eu deixei a montanha para visitar Mulgore, as proteções se enfraqueceram, e a Escuridão tomou o controle.', '', 28153),
(141589, 'ptBR', '', 'Então os Necrotrevas estavam à espreita nas sombras, esperando a ordem do mestre.', 28153),
(141588, 'ptBR', 'Então Huln traçou outro plano. As proteções foram colocadas para afastar a influência dos Deuses Antigos. Embora o general tenha sobrevivido, a essência de Uul\'gyneth foi aprisionada.', '', 28153),
(141587, 'ptBR', 'Huln reuniu heróis de várias tribos. Eles lutaram contra os servos de Uul\'gyneth, os Necrotrevas... mas as forças das sombras eram fortes demais.', '', 28153),
(141586, 'ptBR', 'Tempos atrás, os Deuses Antigos tentaram tomar a Alta Montanha. Essa investida foi liderada por um terrível general... Uul\'gyneth, a Escuridão.', '', 28153),
(141585, 'ptBR', 'Venha comigo.', '', 28153),
(141584, 'ptBR', '<O prefeito não responde.>', '', 28153),
(141583, 'ptBR', '<Procure a origem do feitiço.>', '<Procure a origem do feitiço.>', 28153),
(141582, 'ptBR', '<A efígie que se ergue no centro da cidade emana uma energia sombria, parecida com a que hipnotizou os camponeses. Ela pode estar servindo como âncora para fixar o feitiço.\n\nSe for destruída, pode ser que o feitiço se quebre.>', '', 28153),
(141581, 'ptBR', '<O homem bate com a descrição de Altino Branco, prefeito do Refúgio Outonal. Infelizmente ele não está em condições de ajudar agora.\n\nO prefeito e o resto dos residentes do Refúgio Outonal parecem estar sob efeito de uma magia estranha. Apesar de respirando, ele não reage nem se mexe.\n\nVocê vai ter que encontrar um jeito de quebrar a maldição se quiser a ajuda dele para entrar em contato com a Casa Capelo.>', '', 28153),
(141580, 'ptBR', 'Você chegou na hora certa! Para onde será que os Casca Grossa vão me mandar agora...', '', 28153),
(141579, 'ptBR', 'As proteções estão mais fracas! É o fim dele!', '', 28153),
(141578, 'ptBR', 'Vocês fracassaram! A Escuridão emerge... este será o fim da Alta Montanha!', '', 28153),
(141577, 'ptBR', 'A Legião não se compara ao nosso poder! Rendam-se!', '', 28153),
(141576, 'ptBR', 'Os Chifre Celeste servirão aos meus mestres! Vocês se tornarão a sombra que escurece os céus!', '', 28153),
(141575, 'ptBR', 'Sirvam aos seus verdadeiros mestres, drogbares! Todos que se opuserem morrerão!', '', 28153),
(141573, 'ptBR', '', 'Olá! Hã... você teria interesse na história de Kul Tiraz? Eu tenho vários volumes sobre a fundação e a política da nossa grande nação. É um assunto muito interessante, eu juro.$b$bEu também sou especialista em escrita. Posso treinar você na arte de usar pena e tinta!', 28153),
(141572, 'ptBR', 'Um passo em falso e tu acaba na vala.', '', 28153),
(141571, 'ptBR', 'Meerah, prepare a carroça e pegue suprimentos no porto. Nossos novos aliados podem ir junto para continuar a busca deles.', '', 28153),
(141570, 'ptBR', 'Essa umidade tá mais feia que a tua fuça.', 'Essa umidade tá mais feia que a tua fuça.', 28153),
(141569, 'ptBR', 'Perdeu alguma coisa aqui?', 'Perdeu alguma coisa aqui?', 28153),
(141568, 'ptBR', 'Como tu é confidente do rei, não vamos te matar, por enquanto.', 'Como tu é confidente do rei, não vamos te matar, por enquanto.', 28153),
(141567, 'ptBR', 'Usurpadores. Tua Horda vai pagar pelo que fez com meu povo em Tanaris.', 'Usurpadores. Tua Horda vai pagar pelo que fez com meu povo em Tanaris.', 28153),
(141566, 'ptBR', 'Bom dia para você, $Gsenhor:madame;. Posso lhe mostrar a bela arte da lapidação?$b$bOu, como é mais conhecida, joalheira?', '', 28153),
(141565, 'ptBR', 'Vai rindo, $c. Um passo em falso aqui e a gente te mata com as próprias mãos.', 'Vai rindo, $c. Um passo em falso aqui e a gente te mata com as próprias mãos.', 28153),
(141564, 'ptBR', 'A Horda escolheu os elfos sangrentos em vez da gente. E aí eles mataram nosso maior líder, Zul\'jin.$b$bSangue. Teu povo deve muito sangue pra gente, cara.', '', 28153),
(141563, 'ptBR', 'Cuidado onde pisa, cara. Assim que a princesa de dispensar, tu vai ter uma conversinha com a minha faca sobre o que a Horda fez com Zul\'jin.', '', 28153),
(141562, 'ptBR', 'Tu tem a marca da Princesa Talanji, e a gente não pode te matar, mas não somos obrigados a gostar de ti.', '', 28153),
(141561, 'ptBR', 'Perdeu alguma coisa aqui?', '', 28153),
(141559, 'ptBR', 'O templo tá só o pó da rabiola! É pior do que eu imaginava...', '', 28153),
(141558, 'ptBR', 'Eu tenho que voltar pro templo. O lugar deve ter virado uma zona na minha ausência...', '', 28153),
(141557, 'ptBR', '', 'Agora pertencem a mim!', 28153),
(141556, 'ptBR', 'Estou livre das garras dos Deuses Antigos. Muito obrigado, meus amigos.', '', 28153),
(141555, 'ptBR', 'Mayla! Temos que ficar juntos!', '', 28153),
(141554, 'ptBR', '', 'Não posso deixar que a Escuridão tome o corpo de meu pai!', 28153),
(141552, 'ptBR', 'Eu queria... ver...', 'Eu queria... ver...', 28153),
(141549, 'ptBR', 'Tu vai pro caldeirão!', 'Tu vai pro caldeirão!', 28153),
(141547, 'ptBR', 'Ah, valeu por me soltar! Eu não devia ter confiado naqueles traíras dos Tortakas!', '', 28153),
(141546, 'ptBR', 'Vol\'jamba prometeu...', 'Vol\'jamba prometeu...', 28153),
(141544, 'ptBR', 'Ele... estava errado?', 'Ele estava... errado?', 28153),
(141538, 'ptBR', 'Só Vol\'jamba pode nos salvar!', 'Só Vol\'jamba pode nos salvar!', 28153),
(141536, 'ptBR', 'Vem... sente o cheiro. Bora ver quem aguenta mais!', '', 28153),
(141535, 'ptBR', 'Eu nunca... vou me render...', 'Eu nunca vou... me render...', 28153),
(141528, 'ptBR', 'Ele disse... que a gente... ia sobreviver...', 'Ele disse... que a gente... ia sobreviver...', 28153),
(141527, 'ptBR', 'Por que ninguém escuta?! O fim tá chegando!', 'Por que ninguém escuta?! O fim tá chegando!', 28153),
(141524, 'ptBR', 'Você que manda, chefe.', '', 28153),
(141523, 'ptBR', 'Leo!', '', 28153),
(141522, 'ptBR', 'Ladrões de madeira! Pega eles, Leo!', '', 28153),
(141519, 'ptBR', '', '$n, é você? Onde a gente tá?', 28153),
(141518, 'ptBR', 'T\'paartos jurou lealdade à Luz e, no entanto... vai ter com a escuridão? Essa não pode ser a sina de T\'paartos!', '', 28153),
(141517, 'ptBR', 'Tudo como meu profeta disse. É por isso que não abro mão de ter ele do meu lado.', '', 28153),
(141512, 'ptBR', 'Pega o selo que eu te dei e carimba o gongo.', '', 28153),
(141510, 'ptBR', 'Bah!', '', 28153),
(141509, 'ptBR', 'Sai fora! Não encosta!', '', 28153),
(141508, 'ptBR', 'A visão é tipo assim: velas douradas marcam a vinda final. O manipulador vem pra romper o selo.', '', 28153),
(141507, 'ptBR', 'Eu tô na boa, posso até te ouvir. Mas tem gente que não vai querer não...', '', 28153),
(141506, 'ptBR', 'Tenho umas coisas pra dizer pra um velho pupilo. Você vai me encontrar quando tiver terminado de cuidar dos idiotas que dão ouvidos pra ele.', '', 28153),
(141505, 'ptBR', 'Para de se esconder atrás de máscara. Tu só tá ganhando tempo... E nem tanto assim.', '', 28153),
(141504, 'ptBR', 'Então leva nosso novo porta-voz e acaba com isso.', '', 28153),
(141503, 'ptBR', 'Como quiser, assim será feito. Mas... eu previ que Vol\'jamba não vai morrer pelas minhas mãos.', '', 28153),
(141502, 'ptBR', 'Tu criou essa confusão, meu profeta. Agora, resolve aí.', '', 28153),
(141501, 'ptBR', '|TInterface\\Icons\\Sha_Ability_Rogue_BloodyEye_nightmare:20|tO |cFFFF0000|Hspell:258068|h[Olhar de Sargeras]|h|r é lançado na batalha...', '|TInterface\\Icons\\Sha_Ability_Rogue_BloodyEye_nightmare:20|tO |cFFFF0000|Hspell:258068|h[Olhar de Sargeras]|h|r é lançado na batalha...', 28153),
(141500, 'ptBR', 'Miguel! Achei você!', '', 28153),
(141499, 'ptBR', '', 'Que graça tem explorar se não tiver perigo? Nem sequer um arranhão.', 28153),
(141498, 'ptBR', '', 'E foi só o que o que eu consegui arrastar de lá.', 28153),
(141497, 'ptBR', 'Fico feliz de tu ter saído de lá, ainda que se arrastando.', '', 28153),
(141496, 'ptBR', 'O caminho leva à grandeza? À glória? Ou à aniquilação?', '', 28153),
(141495, 'ptBR', 'Na alma existem muitas verdades. Algumas nobres. Outras...', '', 28153),
(141494, 'ptBR', 'A oferta foi recusada... mas o medo permanece.', '', 28153),
(141493, 'ptBR', 'Para superar o medo da escuridão talvez seja preciso abraçá-la.', '', 28153),
(141492, 'ptBR', 'O medo é implacável. Inexorável. Um inimigo a se vencer.', '', 28153),
(141491, 'ptBR', 'Seguro. Longe de tudo. De tudo e de todos.', '', 28153),
(141490, 'ptBR', 'A solidão é a resposta? Ninguém pode machucá-lo quando se está só.', '', 28153),
(141489, 'ptBR', 'Inimigos espreitam nas sombras. Será possível deter a escuridão?', '', 28153),
(141488, 'ptBR', 'Não é justo! Não é! Nada é o que parece ser!', '', 28153),
(141487, 'ptBR', 'A distração é uma fuga.', '', 28153),
(141486, 'ptBR', 'Recuar mais... encontrar segurança... conforto...', '', 28153),
(141485, 'ptBR', 'Isso nunca vai acabar? Nunca?', '', 28153),
(141484, 'ptBR', 'Mesmo em meio à desesperança, há trégua.', '', 28153),
(141483, 'ptBR', 'Angústia e dor... a busca por consolo.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141482, 'ptBR', 'Não há nenhuma bondade aqui.', '', 28153),
(141481, 'ptBR', 'A dor é a arquiteta da memória.', '', 28153),
(141480, 'ptBR', 'Só resta seguir em frente.', '', 28153),
(141479, 'ptBR', 'Eu me lembro de um tempo quando só os trolls podiam entrar em Zandalar. Bem... Trolls e tortollanos, é claro.\n\nAh, tentaram se livrar de nós uma vez. Acredito que tenha sido o bisavô do Rastakhan, Rei Tezlekhan, o Virulento. Meio cheio de si, aquele lá. Fizemos com que ele mudasse de ideia mais rápido que um elemental numa reunião de xamãs.\n\nÉ espantoso quanta lama dá para se arrumar sobre uma família real, quando se vive mais do que eles.', 'Eu me lembro de um tempo quando só os trolls podiam entrar em Zandalar. Bem... Trolls e tortollanos, é claro.\n\nAh, tentaram se livrar de nós uma vez. Acredito que tenha sido o bisavô do Rastakhan, Rei Tezlekhan, o Virulento. Meio cheio de si, aquele lá. Fizemos com que ele mudasse de ideia mais rápido que um elemental numa reunião de xamãs. \n\nÉ espantoso quanta lama dá para se arrumar sobre uma família real quando se vive mais do que eles.', 28153),
(141478, 'ptBR', 'Os Zandalari concedem livre passagem ao nosso povo por conta das informações úteis que lhes oferecemos.\n\nO que o seu povo prometeu a eles, eu me pergunto?', 'Os Zandalari concedem livre passagem ao nosso povo por conta das informações úteis que lhes oferecemos.\n\nO que o seu povo prometeu a eles, eu me pergunto?', 28153),
(141477, 'ptBR', 'Ah, $gum:uma; $c. E de que continente você veio?', 'Ah, $Uum:uma; $c. E de que continente você veio?', 28153),
(141476, 'ptBR', '', 'Vamos torcer pro Rokhan e os outros voltarem em segurança pra Zul\'jan... senão nossa viagem acaba rapidinho.', 28153),
(141475, 'ptBR', 'Ah, $gum aventureiro:uma aventureira;. Quanto você cobra? Posso precisar de ajuda mais tarde com a recuperação bem... perigosa... de um item precioso.', 'Ah, $Uum aventureiro:uma aventureira;. Quanto você cobra? Posso precisar de ajuda mais tarde com a recuperação bem... perigosa... de um item precioso.', 28153),
(141474, 'ptBR', 'Nós já nos conhecemos? Minha memória não está mais tão boa quanto há cem anos.', 'Já nos conhecemos? Minha memória não está mais tão boa quanto há cem anos.', 28153),
(141473, 'ptBR', 'Ah, eles deixaram a Horda entrar em Zuldazar? Que progressista.', 'Ah, eles deixaram a Horda entrar em Zuldazar? Que progressistas.', 28153),
(141472, 'ptBR', '', '', 28153),
(141471, 'ptBR', '', 'Acaba com esses trolls sangrentos! Eles não podem afundar nossa barcaça!', 28153),
(141470, 'ptBR', '', 'Olha! Trolls sangrentos! Eles devem estar se preparando para atacar minha cidade.', 28153),
(141469, 'ptBR', '|TInterface\\Icons\\SPELL_FIRE_IMMOLATION.BLP:20|tSaia das baias de construção durante o |cFFFF0000|Hspell:248061|h[Protocolo de Expurgação]|h|r para não morrer!', '|TInterface\\Icons\\SPELL_FIRE_IMMOLATION.BLP:20|tSaia das baias de construção durante o |cFFFF0000|Hspell:248061|h[Protocolo de Expurgação]|h|r para não morrer!', 28153),
(141468, 'ptBR', '|TInterface\\ICONS\\ABILITY_HUNTER_SNIPERSHOT.BLP:20|tCorra para longe do chefe durante o |cFFF00000|Hspell:246220|h[Bombardeio Vil]|h|r para não receber dano!', '', 28153),
(141467, 'ptBR', '|TInterface\\ICONS\\spell_shadow_shadesofdarkness.blp:20|t Fique perto dos seus aliados para evitar o |cFFF00000|Hspell:243963|h[Sussurro nas Trevas]|h|r!', '', 28153),
(141466, 'ptBR', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|tOs Destruidores Vilinfusos causam dano a Eonar com o |cFFFF0000|Hspell:246305|h[Ataque de Artilharia]|h|r. Acabe com eles depressa.', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|tOs Destruidores Vilinfusos causam dano a Eonar com o |cFFFF0000|Hspell:246305|h[Ataque de Artilharia]|h|r. Acabe com eles depressa.', 28153),
(141465, 'ptBR', 'Esta criatura ataca os jogadores. Certifique-se de que ela esteja atacando o tanque antes de atacá-la!', 'Esta criatura ataca os jogadores. Certifique-se de que ela esteja atacando o tanque antes de atacá-la!', 28153),
(141464, 'ptBR', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE.BLP:20|tFaça de tudo para não ser atingido pela |cFFFF0000|Hspell:248333|h[Tempestade de Meteoros]|h|r.', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE.BLP:20|tFaça de tudo para não ser atingido pela |cFFFF0000|Hspell:248333|h[Tempestade de Meteoros]|h|r.', 28153),
(141463, 'ptBR', 'Que barulho é esse?', '', 28153),
(141462, 'ptBR', 'Olá? Tem alguém aí?', '', 28153),
(141461, 'ptBR', 'NABO NABO, VENHA JÁ AQUI PRA CIMA ESFREGAR ESSE CONVÉS!', '', 28153),
(141460, 'ptBR', 'Vai logo, lagartixa com cara de tacho.', 'Vai logo, lagartixa com cara de tacho.', 28153),
(141459, 'ptBR', '', 'Tu tá negociando feito um verme. Desembucha logo, o que você quer?', 28153),
(141458, 'ptBR', '', 'Raal, tua mulher tentou me matar hoje de manhã. O que ela acha que tu tá fazendo aqui?', 28153),
(141457, 'ptBR', '', 'Raal, a gente tem que resolver isso. Esses pedidos dos Amani têm que parar.', 28153),
(141456, 'ptBR', 'Um yeti! Bom, não estou de todo errado. Tem forma de homem e é peludo feito urso.', '', 28153),
(141455, 'ptBR', '', 'Ungh... só de PENSHAR em alga marinha já me dá um... enjoo... <golfada> Opa...', 28153),
(141454, 'ptBR', '', 'Alguma coisja com cobrir de algash marinhash?', 28153),
(141453, 'ptBR', '', '<Arroto.> Ah, shim. Eu lembro d\'um shujeito falando de tesjouro.', 28153),
(141452, 'ptBR', 'Por que a gente tem que ficar de guarda aqui, cara? Que parada xarope.', 'Por que a gente tem que ficar de guarda aqui, cara? Que parada xarope.', 28153),
(141451, 'ptBR', '', 'UouuuuOOu! <hic>$B$BHein? Que foi?', 28153),
(141450, 'ptBR', '<Suspiro.> Isso não ajudas Nabo Nabo, pode teres certeza.', '', 28153),
(141449, 'ptBR', 'Tudo que ele dizes é que tavas \"em um lugar com areia\". Isso ajudas em quê?!', '', 28153),
(141448, 'ptBR', 'Nabo Nabo ouves falar de tesouro. A taberna toda ouves falar!', '', 28153),
(141447, 'ptBR', 'Precisa esfregares alguma coisa?', '', 28153),
(141446, 'ptBR', 'TESOURO. ENTERRADO.', 'TESOURO. ENTERRADO.', 28153),
(141445, 'ptBR', 'ESTOURO FERRADO?!', '', 28153),
(141444, 'ptBR', 'Não, não. Tesouro enterrado.', 'Não, não. Tesouro enterrado.', 28153),
(141443, 'ptBR', 'BESOURO ENLATADO?', '', 28153),
(141442, 'ptBR', 'MAS OUTRO DIA TINHA UM CARA NA TABERNA SE GABANDO DAS RELAÇÕES MATRIMONIAIS. COMO SE ALGUÉM TIVESSE INTERESSE NISSO.', '', 28153),
(141441, 'ptBR', 'NÃO, NÃO SEI DE NADICA DE NADA SOBRE TESOURO NENHUM.', '', 28153),
(141440, 'ptBR', 'AHHHH. TESOURO ENTERRADO.', '', 28153),
(141439, 'ptBR', '<Mostra o cartaz.> O que você sabe sobre esse tesouro enterrado?', '<Mostra o cartaz.> O que você sabe sobre esse tesouro enterrado?', 28153),
(141438, 'ptBR', 'QUÊÊ? FALA MAIS ALTO. EU NÃO ESCUTO BEM DESDE...$B$BO INCIDENTE.', '', 28153),
(141435, 'ptBR', 'Pedrim Dissimulado!', '', 28153),
(141434, 'ptBR', '', 'Sorriam o tempo todo! Nunca se sabe quando os convidados estarão olhando, especialmente os sorrateiros!', 28153),
(141433, 'ptBR', '', 'Lembrem-se: se um convidado fizer uma pergunta e você não souber a resposta, invente! Use a engenhosidade gnômica.', 28153),
(141432, 'ptBR', '', 'Trabalhem essas covinhas, recrutas! Vamos mostrar como nós, gnomos, somos adoráveis!', 28153),
(141431, 'ptBR', 'O que?! Isso não é justo. NÃO É JUSTO!', '', 28153),
(141430, 'ptBR', '', 'Filinto! Aguenta firme!', 28153),
(141429, 'ptBR', 'Dez mil de ouro para quem me trouxer as cabeças deles!', '', 28153),
(141428, 'ptBR', 'Os Proudmore estão acabados! Quando a Lady Grimpagris assumir o trono, eu comandarei a frota dela!', '', 28153),
(141427, 'ptBR', 'Basta! De qualquer forma, é tarde demais! Nosso ataque ao Portão de Daelin já começou!', '', 28153),
(141426, 'ptBR', 'Agh! Esses dados estão amaldiçoados! Vão lá logo!', '', 28153),
(141425, 'ptBR', 'Arlão esvazia um saco cheio de dados, quase todos com tesouros.', 'Arlão esvazia um saco cheio de dados, quase todos com tesouros.', 28153),
(141424, 'ptBR', 'Arlão joga de novo e tira um canhão e duas caveiras.', 'Arlão joga de novo e tira um canhão e duas caveiras.', 28153),
(141423, 'ptBR', 'Arlão tira dois tesouros e uma bússola.', 'Arlão tira dois tesouros e uma bússola.', 28153),
(141422, 'ptBR', 'Arlão tira três espadas.', 'Arlão tira três espadas.', 28153),
(141421, 'ptBR', 'Melhor assim! Eu já disse que ser justo não é meu forte? Haha!', '', 28153),
(141420, 'ptBR', 'Quê?! Não, não, não. Isso está errado.', '', 28153),
(141419, 'ptBR', 'Ugh! Tá! Outra rodada!', '', 28153),
(141418, 'ptBR', 'Ah, vejam só, gente nova! Tomara que você seja mais interessante do que esse povo.', '', 28153),
(141417, 'ptBR', 'Ooooh! Que azar, hahah! Façam picadinho deles!', '', 28153),
(141416, 'ptBR', 'Hmm... O que fazer com ratos amotinados? Deixemos os dados decidirem!', '', 28153),
(141415, 'ptBR', 'Oh ho ho! \"Recruta\" novo na área! Vai ser divertido!', '', 28153),
(141414, 'ptBR', '', 'Meu marido nunca vai parar de explorar essa gente...', 28153),
(141413, 'ptBR', 'As coisas mudaram, Filinto. Sou o capitão. Quando os Proudmore tiverem fora do caminho, saquearemos Kul Tiraz de cima a baixo!', '', 28153),
(141412, 'ptBR', 'Nghh... fuja...', '', 28153),
(141411, 'ptBR', 'Isso mesmo, rapazes! Divirtam-se com ele.', '', 28153),
(141410, 'ptBR', '', 'Chegou a hora de você ir além dos nossos picos sagrados.', 28153),
(141409, 'ptBR', '', 'Nós já estivemos divididos e também já perdemos o rumo, mas os espíritos dos nossos ancestrais nos lembraram que somos unidos pela terra, pelo rio e pelo céu... que somos uma só família e que devemos lutar por isso.', 28153),
(141408, 'ptBR', '', 'Essas palavras vão além de terras e pedras. Elas falam da nossa história, da miséria sem fim e da união dos povos contra inimigos em comum.', 28153),
(141407, 'ptBR', '', 'A Alta Montanha resiste.', 28153),
(141406, 'ptBR', '', 'É uma estupidez se colocar no meu caminho!', 28153),
(141405, 'ptBR', '', 'Silgryn! Valtrois! Ajudem o Lorde-regente!', 28153),
(141404, 'ptBR', 'Basta! Temos que acabar com essa corrupção antes que a nascente se perca!', '', 28153),
(141403, 'ptBR', '', 'Eu não esperava que a minha presença fosse...', 28153),
(141402, 'ptBR', 'Foi por isso que eu mandei exilar Umbric e seus radicais. Qualquer pessoa que se envolva com o Caos é um perigo para a Nascente do Sol!', '', 28153),
(141401, 'ptBR', 'O que está acontecendo?', '', 28153),
(141400, 'ptBR', 'Fique longe!', '', 28153),
(141399, 'ptBR', '', 'A Nascente do Sol está diferente... mas sua beleza é a mesma. Já faz tanto tempo.', 28153),
(141398, 'ptBR', '', 'A Nascente do Sol foi corrompida pelos nossos inimigos, mas o sacrifício de um naaru purificou suas águas. Agora, a essência da Luz nos sustenta.', 28153),
(141397, 'ptBR', '', 'Dá para sentir o poder. Forte como a Nascente da Noite, mas de outra natureza.', 28153),
(141396, 'ptBR', 'Por favor, siga-me.', '', 28153),
(141395, 'ptBR', 'Rommath, faça a gentileza de abrir caminho para nós.', '', 28153),
(141394, 'ptBR', '', 'Seria uma verdadeira honra poder ver a Nascente do Sol, Lor\'themar. E eu prefiro que meus amigos me chamem de Thalyssra.', 28153),
(141393, 'ptBR', 'Não importa no que ela se tornou, Alleria é filha de Quel\'thalas. Não impedirei sua peregrinação até o nosso santuário. Primeira Arcanista, você e sua comitiva são bem-vindas para se juntar a nós.', '', 28153),
(141392, 'ptBR', 'Não acho que seja uma boa ideia. Não sabemos se ela não...', '', 28153),
(141391, 'ptBR', '', 'Faz mil anos desde a última vez que vi a Nascente do Sol. Será que eu posso visitá-la?', 28153),
(141389, 'ptBR', '', 'Parece que a minha oferta foi antecipada... e rejeitada. Pois bem. Mas, antes de partir, eu gostaria de fazer um pedido.', 28153),
(141388, 'ptBR', 'Se você duvida das minhas palavras, como quer que confiemos na sua? Você nega que os senhores do Caos falam com você? Não foi você quem se entregou à sombra em Argus?', '', 28153),
(141387, 'ptBR', '', 'Palavras audaciosas, Lor\'themar. Elas são suas mesmo, ou aquele zeloso patrulheiro virou porta-voz da Chefe Guerreira?', 28153),
(141384, 'ptBR', 'Eu tinha esperanças de que sua visita tivesse sido motivada por amor à Luaprata, mas você veio aqui a mando do reizinho da Aliança. Que decepção.', '', 28153),
(141383, 'ptBR', '', 'Como quiser. Trago uma oferta do Alto-rei Anduin Wr...', 28153),
(141382, 'ptBR', 'Mas que besteira. Seja lá o que você tenha a dizer, pode fazê-lo na frente dos nossos convidados.', '', 28153),
(141381, 'ptBR', '', 'A honra é toda minha, Primeira Arcanista. Não quero atrapalhar a sua visita. Talvez seja melhor eu voltar outra hora.', 28153),
(141380, 'ptBR', '', 'Um honra inesperada, Senhora Correventos. Silgryn me contou de seus feitos na campanha de Argus.', 28153),
(141379, 'ptBR', 'Por favor, me chame de Lor\'themar. Ora, cadê os meus modos? Permita-me apresentar outra convidada: Senhora Alleria Correventos, uma heroína da Luaprata de outrora.', '', 28153),
(141376, 'ptBR', '', 'É um prazer enfim visitar a sua bela cidade. Obrigada por estender o convite, Lorde-regente.', 28153),
(141375, 'ptBR', '', 'Primeira Arcanista Thalyssra e honoríficos convidados. Bem-vindos a Luaprata.', 28153),
(141374, 'ptBR', 'Não temos por que esconder nada dos nossos aliados, Alleria. Por falar nisso, acabam de chegar alguns dos nossos novos amigos.', '', 28153),
(141373, 'ptBR', '', 'Olá outra vez, Liadrin. Campe$gão:ã;. Lor\'themar, vim aqui tratar de um assunto que devemos discutir em particular.', 28153),
(141372, 'ptBR', 'Lady Liadrin... $Gcampeão:campeã;. Vocês são muito $Gbem-vindos:bem-vindas;. Como podem ver, temos um visitante... inesperado.', '', 28153),
(141371, 'ptBR', '', 'Como quiser, Chefe Guerreira. Nos encontramos no lar de Lady Thalyssra em Suramar, $p.', 28153),
(141370, 'ptBR', '', 'Conto com vocês. Não voltem até que Suramar jure lealdade à Horda.', 28153),
(141369, 'ptBR', '', 'O lorde-regente convidou os Filhos da Noite para Luaprata. Eu irei para Suramar para acompanhar Lady Thalyssra à reunião.', 28153),
(141366, 'ptBR', '', 'Para garantir o futuro do nosso povo, você tem que nos ajudar a conquistar um lugar em Azeroth.', 28153),
(141365, 'ptBR', '', 'Nossos líderes se mancomunaram com os demônios... e nos traíram. Mas nós lutamos contra a tirania. Rechaçamos os demônios. Suramar é nossa novamente — nós jamais permitiremos que ela sucumba à escuridão.', 28153),
(141364, 'ptBR', '', 'Com o passar das eras, Azeroth se transformava à nossa volta... sucumbindo ao guante da Legião.', 28153),
(141363, 'ptBR', '', 'Por dez mil anos, Suramar foi o único mundo que conhecemos.', 28153),
(141362, 'ptBR', '', 'Tu és Forjado a Luz. Tu serás o pendão da esperança contra a escuridão.', 28153),
(141361, 'ptBR', '', 'Até que enfim, nosso inimigo foi abatido. A Legião se foi, mas a guerra está longe de acabar. Novas ameaças conspiram nas sombras, esperando a hora certa de atacar.', 28153),
(141360, 'ptBR', '', 'Nesses milênios de guerra, a Luz nos mostrou o caminho da verdade.', 28153),
(141359, 'ptBR', '', 'Somos soldados.', 28153),
(141358, 'ptBR', '', 'O Caos nos moldou... nos transformou. Mas você se tornará mestre dele.', 28153),
(141357, 'ptBR', '', 'Mas nós compreendemos uma verdade que eles não compreendem.', 28153),
(141356, 'ptBR', '', 'Sábios e eruditos temem o Caos.', 28153),
(141355, 'ptBR', '', 'O Caos. Uma força de voracidade sem fim.', 28153),
(141354, 'ptBR', '', 'Eu vou pro barco. Me encontra lá.', 28153),
(141353, 'ptBR', 'Bwonsamdi te abençoe, estranh$Uo:a;.', '', 28153),
(141352, 'ptBR', '', 'Os goblins garantiram que esse plano vai funcionar... é por isso que eu preciso de você aqui, pra garantir que vai mesmo.$B$BPront$Uo:a; pra descer o rio?', 28153),
(141351, 'ptBR', 'A lenda que dorme com os peixes... literalmente! O Atroz da Angra do Facão... o Campeão dos Cruzados na Cabeça... o Poderoso Predador Pugilista... Trothak, o Soca-tubarões!', '', 28153),
(141350, 'ptBR', 'Incrível! Esses cães sarnentos deram uma coça no Gryff e no Stevin! Só nos resta um desafiante, e esse aqui dispensa apresentação.', '', 28153),
(141349, 'ptBR', 'Os Filhos Famintos da Fulminação... as Crias Carniceiras de Cruz-credo... a Dupla de Dois Destruidores... Gryff e Stevin!', '', 28153),
(141348, 'ptBR', 'Sem mais delongas, lá vem a temível dupla do outro lado do oceano. Duas feras indomáveis que incitam medo até mesmo nos guerreiros mais corajosos.', '', 28153),
(141347, 'ptBR', 'Sofra, profanad$Gor:ora;!', '', 28153),
(141345, 'ptBR', 'Você não sairá daqui com vida!', '', 28153),
(141344, 'ptBR', 'E Ludovico beija o chão! Mas que luta, minha gente! Esses bucaneiros fedorentos não são flor que se cheire... e o próximo desafio será o ápice da brutalidade.', '', 28153),
(141343, 'ptBR', 'Salve-se...', '', 28153),
(141342, 'ptBR', '', 'Criança desgraçada! Meu esquema com o Bwonsamdi era pra viver em troca da sua alma! Você vai estragar tudo!', 28153),
(141341, 'ptBR', 'Dos esgotos da Angra do Facão, vem um tortollano que vive para torturar os outros com a velocidade de uma tartaruga. Ele é a Mão que Maltrata e Machuca... o Cascudo no Cocuruto do Capiroto... o Pai da Paciência Plena... ele é... Ludovico!', '', 28153),
(141340, 'ptBR', 'Mas vejam só... Pegaram o porco. Agora acho que já podemos partir para um desafio mais... emocionante!', '', 28153),
(141334, 'ptBR', '', 'Tu nunca ouviu falar no clã Caninegro? Normal, a tribo foi exterminada pelo Martelo do Crepúsculo.\n\nOs Zandalari ainda têm um representante como lembrança do passado. Agora não passo de curiosidade.\n\nNão é tão ruim. Nunca tenho que pagar pelos meus drinques.', 28153),
(141332, 'ptBR', 'Dizem que o Rei Rastakhan não tá lá muito bem hoje em dia. É só uma questão de tempo pra Zandalar inteira cair. E aí, como é que a gente fica?', 'Dizem que o Rei Rastakhan não tá lá muito bem hoje em dia. É só uma questão de tempo pra Zandalar inteira cair. E aí, como é que a gente fica?', 28153),
(141331, 'ptBR', 'Um dia os Zandalari governaram todos os trolls. Agora, não mantêm nem as fronteiras seguras.', 'Um dia os Zandalari governaram todos os trolls. Agora, não mantêm nem as fronteiras seguras.', 28153),
(141330, 'ptBR', 'Os Zandalari tão deixando magia de sangue entrar nas terras deles. Logo, logo, eles vão ser destruídos.', 'Os Zandalari tão deixando magia de sangue entrar nas terras deles. Logo, logo, eles vão ser destruídos.', 28153),
