(159034, 'ruRU', 'Мы... вернемся...', 'Мы... вернемся...', 28153),
(159033, 'ruRU', 'Черные драконы возродятся!', 'Черные драконы возродятся!', 28153),
(159032, 'ruRU', 'Твой род будет уничтожен!', 'Твой род будет уничтожен!', 28153),
(159031, 'ruRU', 'Огонь и смерть!', 'Огонь и смерть!', 28153),
(159030, 'ruRU', 'Ты смеешь бросать вызов дракону?', 'Ты смеешь бросать вызов дракону?', 28153),
(159029, 'ruRU', 'Черные драконы восстанут!', 'Черные драконы восстанут!', 28153),
(159028, 'ruRU', 'Слава черным драконам!', 'Слава черным драконам!', 28153),
(159027, 'ruRU', 'За хранителей земли!', 'За хранителей земли!', 28153),
(159026, 'ruRU', 'Я буду защищать свой род!', 'Я буду защищать свой род!', 28153),
(159025, 'ruRU', 'За тебя... моя императрица...', 'За тебя... моя императрица...', 28153),
(159024, 'ruRU', 'Ты можешь сокрушить одного... но придут другие...', 'Ты можешь сокрушить одного... но придут другие...', 28153),
(159023, 'ruRU', 'Нужно доставить руду... императрице...', 'Нужно доставить руду... императрице...', 28153),
(159022, 'ruRU', 'Ее зов... это музыка...', 'Ее зов... это музыка...', 28153),
(159021, 'ruRU', 'Я слышу ее... хотя жизнь и покидает меня...', 'Я слышу ее... хотя жизнь и покидает меня...', 28153),
(159020, 'ruRU', 'Песня императрицы... стихает...', 'Песня императрицы... стихает...', 28153),
(159019, 'ruRU', 'Нас... тысячи... Тебе нас не остановить...', 'Нас... тысячи... Тебе нас не остановить...', 28153),
(159018, 'ruRU', 'Ш-ш-ш... это конец...', 'Ш-ш-ш... это конец...', 28153),
(159017, 'ruRU', 'Я убью тебя, и рой полакомится твоим трупом!', 'Я убью тебя, и рой полакомится твоим трупом!', 28153),
(159016, 'ruRU', 'Ты добровольно идешь навстречу смерти?', 'Ты добровольно идешь навстречу смерти?', 28153),
(159015, 'ruRU', 'Золотая руда наша! Мы преподнесем ее в дар императрице!', 'Золотая руда наша! Мы преподнесем ее в дар императрице!', 28153),
(159014, 'ruRU', 'Мы служим императрице!', 'Мы служим императрице!', 28153),
(159013, 'ruRU', 'Рой не остановить!', 'Рой не остановить!', 28153),
(159012, 'ruRU', 'Сладостный зов императрицы велит мне убить тебя!', 'Сладостный зов императрицы велит мне убить тебя!', 28153),
(159011, 'ruRU', 'Я повинуюсь императрице!', 'Я повинуюсь императрице!', 28153),
(159010, 'ruRU', 'За императрицу!', 'За императрицу!', 28153),
(159009, 'ruRU', 'Бесславное правление королевы банши закончится, и Альянс переживет его.', '', 28153),
(159008, 'ruRU', 'Она надеется, что горе сломит нас. Разрушит наше единство. Но я клянусь...', '', 28153),
(159007, 'ruRU', 'Ар-р-р! Честная победа...', 'Ар-р-р! Честная победа...', 28153),
(159006, 'ruRU', 'Ар-р-р! Такая смерть как раз по мне!', 'Ар-р-р! Такая смерть как раз по мне!', 28153),
(159005, 'ruRU', 'Но этой мечте не сбыться, пока Сильвана Ветрокрылая стоит во главе Орды.', '', 28153),
(159004, 'ruRU', 'Я плыву... к заходящему солнцу...', 'Я плыву... к заходящему солнцу...', 28153),
(159003, 'ruRU', 'Всю жизнь я просил о том, чтобы на Азероте наступил мир.', '', 28153),
(159002, 'ruRU', 'Я займу свое место среди воинов древности...', 'Я займу свое место среди воинов древности...', 28153),
(159001, 'ruRU', 'Я ценю твою выдержку и доблесть в этот трагический для Альянса день.', '', 28153),
(159000, 'ruRU', 'Духи, благословите меня в последний путь...', 'Духи, благословите меня в последний путь...', 28153),
(158999, 'ruRU', '', 'Пока отдыхай. Набирайся сил перед новыми битвами. Ты мне еще пригодишься.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158998, 'ruRU', 'Славная смерть в славном бою!', 'Славная смерть в славном бою!', 28153),
(158997, 'ruRU', 'Клан отомстит за меня...', 'Клан отомстит за меня...', 28153),
(158996, 'ruRU', '', 'Но их рана глубока. Гнев не придаст им силы в этой войне. Наоборот, лишь ослабит.', 28153),
(158995, 'ruRU', 'Смерть идет за тобой...', 'Смерть идет за тобой...', 28153),
(158994, 'ruRU', 'Еще один жалкий противник!', 'Еще один жалкий противник!', 28153),
(158993, 'ruRU', 'Еще одна славная битва!', 'Еще одна славная битва!', 28153),
(158992, 'ruRU', 'Я вырежу тебе глаза!', 'Я вырежу тебе глаза!', 28153),
(158991, 'ruRU', '', 'Но мы не довели дело до конца. Альянс будет мстить. Они придут за тобой. За мной. За нами.', 28153),
(158990, 'ruRU', '', 'Мы хотели закончить войну, не начав ее... Сегодня мы должны были отнять у врагов дом и перебить их вождей. Выпустить из Альянса всю кровь.', 28153),
(158989, 'ruRU', '', 'Посылая тебя на это задание, я не ждала такого исхода.', 28153),
(158988, 'ruRU', 'Тысяча кораблей принесут вам погибель!', 'Тысяча кораблей принесут вам погибель!', 28153),
(158987, 'ruRU', 'Жизнь за Иорун!', 'Жизнь за Иорун!', 28153),
(158986, 'ruRU', 'За Кровавый Киль!', 'За Кровавый Киль!', 28153),
(158985, 'ruRU', 'Умри с честью!', 'Умри с честью!', 28153),
(158984, 'ruRU', 'Я сожру твое сердце!', 'Я сожру твое сердце!', 28153),
(158983, 'ruRU', 'Мрглрг-г-г...', 'Мрглрг-г-г...', 28153),
(158982, 'ruRU', 'Мррг мргл?', 'Мррг мргл?', 28153),
(158981, 'ruRU', 'Рглл мгргл... ргл...', 'Рглл мгргл... ргл...', 28153),
(158980, 'ruRU', 'Гргл...', 'Гргл...', 28153),
(158979, 'ruRU', 'Мрг!', 'Мрг!', 28153),
(158978, 'ruRU', 'Ргл... мрг...', 'Ргл... мрг...', 28153),
(158977, 'ruRU', 'Мрррмгрл!', 'Мрррмгрл!', 28153),
(158976, 'ruRU', 'Мрглргл? Мрг! Ргл!', 'Мрглргл? Мрг! Ргл!', 28153),
(158975, 'ruRU', 'Ргрмл грмл грмл!', 'Ргрмл грмл грмл!', 28153),
(158974, 'ruRU', '', 'О, это просто превосходно! Спасибо тебе, $p. Это так мило с твой стороны. Вот, возьми немного печенья.', 28153),
(158973, 'ruRU', 'Мрг! Грмл?!', 'Мрг! Грмл?!', 28153),
(158972, 'ruRU', 'Мргл? Ргл!', 'Мргл? Ргл!', 28153),
(158971, 'ruRU', 'Мрглрглргл!', 'Мрглрглргл!', 28153),
(158970, 'ruRU', 'Смерть – ничто для бескрайней Бездны...', 'Смерть – ничто для бескрайней Бездны...', 28153),
(158969, 'ruRU', 'Узри его второе пришествие...', 'Узри его второе пришествие...', 28153),
(158968, 'ruRU', 'Твоя судьба уже поднимается из глубин...', 'Твоя судьба уже поднимается из глубин...', 28153),
(158967, 'ruRU', 'Нас не уничтожить... нам нет числа...', 'Нас не уничтожить... нам нет числа...', 28153),
(158966, 'ruRU', 'Ты падешь... твои друзья покинут тебя...', 'Ты падешь... твои друзья покинут тебя...', 28153),
(158965, 'ruRU', 'Слышишь зов тьмы из глубин?', 'Слышишь зов тьмы из глубин?', 28153),
(158964, 'ruRU', 'Бездну безумия не сдержать!', 'Бездну безумия не сдержать!', 28153),
(158963, 'ruRU', 'Мое мертвое тело породит тысячи таких, как я.', 'Мое мертвое тело породит тысячи таких, как я.', 28153),
(158962, 'ruRU', 'Великая тьма предвещает конец всего сущего.', 'Великая тьма предвещает конец всего сущего.', 28153),
(158961, 'ruRU', 'Пожиратель из глубин уничтожит ваш мир!', 'Пожиратель из глубин уничтожит ваш мир!', 28153),
(158960, 'ruRU', 'Ты не можешь победить то, чего боишься!', 'Ты не можешь победить то, чего боишься!', 28153),
(158959, 'ruRU', 'Наше влияние будет расти, пока весь ваш мир не захлестнет ужас.', 'Наше влияние будет расти, пока весь ваш мир не захлестнет ужас.', 28153),
(158958, 'ruRU', 'Беспросветные глубины зовут тебя.', 'Беспросветные глубины зовут тебя.', 28153),
(158957, 'ruRU', 'Глубины поглотят твои крики ужаса!', 'Глубины поглотят твои крики ужаса!', 28153),
(158956, 'ruRU', 'Мы поглотим вас всех!', 'Мы поглотим вас всех!', 28153),
(158955, 'ruRU', 'Тьма пожрет твою плоть!', 'Тьма пожрет твою плоть!', 28153),
(158954, 'ruRU', 'Иду ко дну...', 'Иду ко дну...', 28153),
(158953, 'ruRU', 'Мне всегда думалось... что я умру в море...', 'Мне всегда думалось... что я умру в море...', 28153),
(158952, 'ruRU', 'Я не хочу... так умирать...', 'Я не хочу... так умирать...', 28153),
(158951, 'ruRU', 'Во всем виноват... штурман...', 'Во всем виноват... штурман...', 28153),
(158950, 'ruRU', 'Спасите меня... вы, псы...', 'Спасите меня... вы, псы...', 28153),
(158949, 'ruRU', 'Уж лучше умереть... чем маяться тут...', 'Уж лучше умереть... чем маяться тут...', 28153),
(158948, 'ruRU', 'Не надо нам было... сюда лезть...', 'Не надо нам было... сюда лезть...', 28153),
(158947, 'ruRU', 'Самая... ужасная... команда...', 'Самая... ужасная... команда...', 28153),
(158946, 'ruRU', 'Мы заберем ваш корабль, салаги!', 'Мы заберем ваш корабль, салаги!', 28153),
(158945, 'ruRU', 'Ребята, теперь у нас есть и богатство, и способ убраться отсюда!', 'Ребята, теперь у нас есть и богатство, и способ убраться отсюда!', 28153),
(158944, 'ruRU', 'У них есть корабль! Бей их!', 'У них есть корабль! Бей их!', 28153),
(158943, 'ruRU', 'Не надо было тебе сюда приходить!', 'Не надо было тебе сюда приходить!', 28153),
(158942, 'ruRU', 'Ар-р-р! Не надо было так налегать на ром...', 'Ар-р-р! Не надо было так налегать на ром...', 28153),
(158941, 'ruRU', 'Не спите, псы, на нас напали! Всем подъем!', 'Не спите, псы, на нас напали! Всем подъем!', 28153),
(158940, 'ruRU', 'Они приплыли не за тем, чтоб нас спасти. Схватить их!', 'Они приплыли не за тем, чтоб нас спасти. Схватить их!', 28153),
(158939, 'ruRU', 'Ар-р-р! Мы выберемся отсюда, ребята! Бей их!', 'Ар-р-р! Мы выберемся отсюда, ребята! Бей их!', 28153),
(158938, 'ruRU', 'Я возвращаюсь в пучину... как настоящий моряк...', 'Я возвращаюсь в пучину... как настоящая морячка...', 28153),
(158937, 'ruRU', 'Ар-р-р... дай выпить рому перед смертью...', 'Ар-р-р... дай выпить рому перед смертью...', 28153),
(158936, 'ruRU', 'Здесь стало... так темно...', 'Здесь стало... так темно...', 28153),
(158935, 'ruRU', 'Ох... грязный прием...', 'Ох... грязный прием...', 28153),
(158934, 'ruRU', 'Все... на корабль...', 'Все... на корабль...', 28153),
(158933, 'ruRU', 'Ар-р-р! Прямо в брюхо...', 'Ар-р-р! Прямо в брюхо...', 28153),
(158932, 'ruRU', 'Мои сокровища... не найдете...', 'Мои сокровища... не найдете...', 28153),
(158931, 'ruRU', 'Ар-р-р... мое сокровище...', 'Ар-р-р... мое сокровище...', 28153),
(158930, 'ruRU', 'Защищайте меня, рохли!', 'Защищайте меня, рохли!', 28153),
(158929, 'ruRU', 'Ко мне, паршивые псы! Нас берут на абордаж!', 'Ко мне, паршивые псы! Нас берут на абордаж!', 28153),
(158928, 'ruRU', 'Не надо было сюда лезть! Это владения пиратов!', 'Не надо было сюда лезть! Это владения пиратов!', 28153),
(158927, 'ruRU', 'Ар-р-р! К нам пожаловали незваные гости, ребята!', 'Ар-р-р! К нам пожаловали незваные гости, ребята!', 28153),
(158926, 'ruRU', 'Воруй, убивай! Ар-р-р!', 'Воруй, убивай! Ар-р-р!', 28153),
(158925, 'ruRU', 'Хочешь саблю в живот?', 'Хочешь саблю в живот?', 28153),
(158924, 'ruRU', 'Я тебя за борт спущу!', 'Я тебя за борт спущу!', 28153),
(158923, 'ruRU', 'Полундра, салаги! Нас атакуют!', 'Полундра, салаги! Нас атакуют!', 28153),
(158922, 'ruRU', 'Никто не помешает нашей охоте за Онохо!', '', 28153),
(158921, 'ruRU', 'Нам тебя подарило само море. Тебе уже не уйти...', '', 28153),
(158920, 'ruRU', 'Мы будем оттачивать свое мастерство, пока море не укажет нам путь!', '', 28153),
(158919, 'ruRU', 'Водные потоки предвещали эту встречу.', '', 28153),
(158918, 'ruRU', 'Мы – клан великих охотников. Неужели ты надеешься выжить?', '', 28153),
(158917, 'ruRU', 'Море принесло нам свежее мясо и оружие! Благодарение волнам!', '', 28153),
(158916, 'ruRU', 'Твоя плоть и снаряжение пригодятся нам в великой охоте. Спасибо тебе!', '', 28153),
(158915, 'ruRU', 'Наш клан ведет великую охоту уже много лет, и тебе нас не остановить!', '', 28153),
(158914, 'ruRU', 'Отмель... открыла мне эту судьбу...', '', 28153),
(158913, 'ruRU', 'Волны... примите меня...', '', 28153),
(158912, 'ruRU', 'Охота забрала... еще одну жизнь...', '', 28153),
(158911, 'ruRU', 'Ты тоже... хороший... охотник...', '', 28153),
(158910, 'ruRU', 'Хр-р... крепкий удар...', '', 28153),
(158909, 'ruRU', 'Все мы в итоге канем в море...', '', 28153),
(158908, 'ruRU', 'Охота продолжится... без меня...', '', 28153),
(158907, 'ruRU', 'Мы ни о чем... не сожалеем...', '', 28153),
(158906, 'ruRU', 'Похоже, на берег вынесло чужеземцев.', '', 28153),
(158905, 'ruRU', 'Благодарим тебя за жертву.', '', 28153),
(158904, 'ruRU', 'Забрать их припасы! Сегодня у нас будет пир!', '', 28153),
(158903, 'ruRU', 'Ты смеешь идти против нашего клана?', '', 28153),
(158902, 'ruRU', 'Твоя кровь поддержит нашу охоту.', '', 28153),
(158901, 'ruRU', 'Твое тело накормит нас. Спасибо тебе.', '', 28153),
(158900, 'ruRU', 'Море принесло нам новые припасы...', '', 28153),
(158899, 'ruRU', 'Волны предсказали твое появление.', '', 28153),
(158898, 'ruRU', '', 'Просто обожаю всех этих малипусек. Кролики, птицы, крабы – кого тут только нет! Я тренировала нескольких питомцев специально для этих боев. Видишь эту огромную тушу? Мои питомцы управились с ней всего за четыре минуты. Эти малыши всегда хотят есть. Хочешь посмотреть на них в деле?', 28153),
(158897, 'ruRU', '', 'Присмотри за Миирой, хорошо? \n\nОна не понимает, насколько опасна пустыня. Не хотелось бы, чтобы она пропала в зыбучих песках...', 28153),
(158896, 'ruRU', '', 'Твоему другу заметно лучше. Я рада, что Киро с Миирой смогли помочь.', 28153),
(158895, 'ruRU', '', 'Приветствую тебя в нашем доме, $n. По крайней мере, пока что это наш дом. \n\nКараваны готовы выдвигаться сразу же, если наше убежище обнаружат сетраки.', 28153),
(158894, 'ruRU', 'Попробуй довести Ло до убежища, собрав по пути все водоросли.', '', 28153),
(158893, 'ruRU', '', 'Разумеется! Вот, возьми эти мучные бомбы. Только, пожалуйста, обращайся с ними осторожнее.', 28153),
(158892, 'ruRU', 'Хочешь обменять что-нибудь на медвежатину?', '', 28153),
(158891, 'ruRU', 'Куа\'фон бежит прочь!', '', 28153),
(158890, 'ruRU', 'Куа\'фон не отдает вам череп, озорно виляя хвостом.', '', 28153),
(158889, 'ruRU', 'Я все равно... сильнее.', '', 28153),
(158888, 'ruRU', 'Я просто заберу, что хочу!', '', 28153),
(158887, 'ruRU', 'Неплохое снаряжение... Хочешь, поменяемся?', '', 28153),
(158886, 'ruRU', 'Вернуться... к воде...', '', 28153),
(158885, 'ruRU', 'Наш клан не погибнет... с-с-сегодня...', '', 28153),
(158884, 'ruRU', 'Гр-р-р... но как?..', '', 28153),
(158883, 'ruRU', 'Я вернусь... к волнам...', '', 28153),
(158882, 'ruRU', 'С-с-сокровище... было моим...', '', 28153),
(158881, 'ruRU', 'С-с-с... ты поплатишься...', '', 28153),
(158880, 'ruRU', 'Хс-с-с... воры...', '', 28153),
(158879, 'ruRU', 'Ох... моя кровь...', '', 28153),
(158878, 'ruRU', 'Хс-с-с! Убить их! Защитить сокровище!', '', 28153),
(158877, 'ruRU', 'Камни придают нашему клану с-с-силу! Мы не с-с-склонимся перед тобой!', '', 28153),
(158876, 'ruRU', 'Я отведаю твоей плоти! Обглодаю твои кости!', '', 28153),
(158875, 'ruRU', 'Ты ос-с-смеливаешься бросить вызов великому воину?', '', 28153),
(158874, 'ruRU', 'Я защищаю клан! Тебя ждет смерть!', '', 28153),
(158873, 'ruRU', 'Чужаки! С-с-сокрушите их, воины!', '', 28153),
(158872, 'ruRU', 'Это с-с-сокровище принадлежит моему клану! Вы воры!', '', 28153),
(158871, 'ruRU', 'Мой клан силен! Тебе нас не остановить!', '', 28153),
(158870, 'ruRU', 'Попробую найти.', 'Попробую найти.', 28153),
(158869, 'ruRU', 'Твое сокровище станет нашим!', '', 28153),
(158868, 'ruRU', 'Вот тебе мороженое!', 'Вот тебе мороженое!', 28153),
(158867, 'ruRU', 'Я вспорю тебе брюхо, как рыбе!', '', 28153),
(158866, 'ruRU', 'Защищайте клан!', '', 28153),
(158865, 'ruRU', 'Порубить их! Принести мне их с-с-сокровище!', '', 28153),
(158864, 'ruRU', 'С-с-с-с! Нас атакуют!', '', 28153),
(158863, 'ruRU', 'Теплокровные!', '', 28153),
(158862, 'ruRU', 'Убить их! Заберем их вещички!', '', 28153),
(158861, 'ruRU', 'Хс-с-с! С-с-сражу тебя!', '', 28153),
(158860, 'ruRU', 'А вот и свежая еда, дети мои!', 'А вот и свежая еда, дети мои!', 28153),
(158859, 'ruRU', 'Конечно. Чем могу помочь?', 'Конечно. Чем могу помочь?', 28153),
(158858, 'ruRU', 'Еще одна жертва оказалась в нашем логове. Тебе конец...', 'Еще одна жертва оказалась в нашем логове. Тебе конец...', 28153),
(158857, 'ruRU', 'Заходи в наше логово, лакомый кусочек. Будет вкусно...', 'Заходи в наше логово, лакомый кусочек. Будет вкусно...', 28153),
(158856, 'ruRU', 'Твоя кровь вскормит наше потомство, твоей плотью насытятся королевы, а я съем твой мозг!', 'Твоя кровь вскормит наше потомство, твоей плотью насытятся королевы, а я съем твой мозг!', 28153),
(158855, 'ruRU', 'Тебе никогда не найти яйца! Наш рой вечен!', 'Тебе никогда не найти яйца! Наш рой вечен!', 28153),
(158854, 'ruRU', 'Не сопротивляйся, добыча, не продлевай свои мучения!', 'Не сопротивляйся, добыча, не продлевай свои мучения!', 28153),
(158853, 'ruRU', 'А, еще одна жертва попалась в наш-ш-шу паутину!', 'А, еще одна жертва попалась в наш-ш-шу паутину!', 28153),
(158852, 'ruRU', 'Мы будем защищать стаю до последнего!', 'Мы будем защищать стаю до последнего!', 28153),
(158851, 'ruRU', 'Берегитесь... чужаков...', 'Берегитесь... чужаков...', 28153),
(158850, 'ruRU', 'Яйца... тебе... не найти...', 'Яйца... тебе... не найти...', 28153),
(158849, 'ruRU', 'Всех нас... тебе не найти...', 'Всех нас... тебе не найти...', 28153),
(158848, 'ruRU', 'Не для того мы старались... чтобы пасть от твоей руки...', 'Не для того мы старались... чтобы пасть от твоей руки...', 28153),
(158847, 'ruRU', 'Мое тело станет пищей для наших детей...', 'Мое тело станет пищей для наших детей...', 28153),
(158846, 'ruRU', 'Ш-ш-ш... больно...', 'Ш-ш-ш... больно...', 28153),
(158845, 'ruRU', 'Защитить... выводок...', 'Защитить... выводок...', 28153),
(158844, 'ruRU', 'Каш-ш-ш...', 'Каш-ш-ш...', 28153),
(158843, 'ruRU', 'Наши дети отведают твоей плоти!', 'Наши дети отведают твоей плоти!', 28153),
(158842, 'ruRU', 'Ш-ш-шагай прямо в мою паутину!', 'Ш-ш-шагай прямо в мою паутину!', 28153),
(158841, 'ruRU', 'Чужаки!', 'Чужаки!', 28153),
(158840, 'ruRU', 'Мы защитим выводок!', 'Мы защитим выводок!', 28153),
(158839, 'ruRU', 'Свеж-ж-жая кровь...', 'Свеж-ж-жая кровь...', 28153),
(158838, 'ruRU', 'А вот и добыча...', 'А вот и добыча...', 28153),
(158837, 'ruRU', 'Кто потревож-ж-жил наш-ш-шу паутину?', 'Кто потревож-ж-жил наш-ш-шу паутину?', 28153),
(158836, 'ruRU', 'Кш-ш-ш... чуж-ж-жаки...', 'Кш-ш-ш... чуж-ж-жаки...', 28153),
(158835, 'ruRU', '', 'Я стала такой сластеной в последнее время. С радостью отведала бы клубничного мороженого! \n\nБуду тебе невероятно признательна, если ты его мне найдешь. И если тебя не затруднит, принеси побольше – оставлю на потом. Надеюсь, я тебе не сильно докучаю!', 28153),
(158834, 'ruRU', '', 'Еще чуть-чуть и твою стройность можно будет назвать худобой, дорогуша. Не маловато ли ты ешь?', 28153),
(158833, 'ruRU', '', 'О, как мило. Проделать такой путь, чтобы повидать меня?', 28153),
(158832, 'ruRU', '', 'Здравствуй, дорогуша. Рада тебя видеть.', 28153),
(158831, 'ruRU', 'Ра-а-ар! Ар-р-р!', '', 28153),
(158830, 'ruRU', 'Ты... нет...', '', 28153),
(158829, 'ruRU', 'Ар-р-р...', '', 28153),
(158828, 'ruRU', 'Гр-р-р...', '', 28153),
(158827, 'ruRU', 'Ты... плохо пахнешь...', '', 28153),
(158826, 'ruRU', 'Надо... бежать...', '', 28153),
(158825, 'ruRU', 'Хух...', '', 28153),
(158824, 'ruRU', 'Ух... р-рах...', '', 28153),
(158823, 'ruRU', 'Новый запах... нехорошо, рар-р-р!', '', 28153),
(158822, 'ruRU', 'Ар-р-р, чую мясо!', '', 28153),
(158821, 'ruRU', 'Гра-ар! Мы покормимся тобой!', '', 28153),
(158820, 'ruRU', 'Укушу, съем твое мясо!', '', 28153),
(158819, 'ruRU', 'Умри! Ар-р-р!', '', 28153),
(158818, 'ruRU', 'Р-р-р! Тебя... убью!', '', 28153),
(158817, 'ruRU', 'Гра-а-р!', '', 28153),
(158816, 'ruRU', 'Мр-р-р!', '', 28153),
(158815, 'ruRU', 'Эти земли гораздо старше тебя, и они тебя переживут.', 'Эти земли гораздо старше тебя, и они тебя переживут.', 28153),
(158814, 'ruRU', 'Сияющие камни – дар природы, и мы защитим их от подобных тебе!', 'Сияющие камни – дар природы, и мы защитим их от подобных тебе!', 28153),
(158813, 'ruRU', 'Сегодня ты вернешься в круговорот жизни, а твои останки будут питать нас.', 'Сегодня ты вернешься в круговорот жизни, а твои останки будут питать нас.', 28153),
(158812, 'ruRU', 'Я покончу с тобой прежде, чем ты осквернишь наши земли.', 'Я покончу с тобой прежде, чем ты осквернишь наши земли.', 28153),
(158811, 'ruRU', 'Ты удобришь землю, попранную тобой по пути сюда.', 'Ты удобришь землю, попранную тобой по пути сюда.', 28153),
(158810, 'ruRU', 'Вы нарушаете равновесие и не можете быть частью этого мира. Я это исправлю.', 'Вы нарушаете равновесие и не можете быть частью этого мира. Я это исправлю.', 28153),
(158809, 'ruRU', 'Мне нужно убить тебя и восстановить нарушенное тобой равновесие.', 'Мне нужно убить тебя и восстановить нарушенное тобой равновесие.', 28153),
(158808, 'ruRU', 'Нам поручено оберегать эти земли и их обитателей. Тебе здесь не место!', 'Нам поручено оберегать эти земли и их обитателей. Тебе здесь не место!', 28153),
(158807, 'ruRU', 'Вы... чума этого мира...', 'Вы... чума этого мира...', 28153),
(158806, 'ruRU', 'Вы осквернили... наши земли...', 'Вы осквернили... наши земли...', 28153),
(158805, 'ruRU', 'Природу... не убить...', 'Природу... не убить...', 28153),
(158804, 'ruRU', 'Мы вновь... прорастем...', 'Мы вновь... прорастем...', 28153),
(158803, 'ruRU', 'Подобным тебе... не выжить...', 'Подобным тебе... не выжить...', 28153),
(158802, 'ruRU', 'Земля насытится... мною...', 'Земля насытится... мною...', 28153),
(158801, 'ruRU', 'Ты нарушаешь... равновесие...', 'Ты нарушаешь... равновесие...', 28153),
(158800, 'ruRU', 'Я возвращаюсь... к природе...', 'Я возвращаюсь... к природе...', 28153),
(158799, 'ruRU', 'Нам поручено оберегать это место!', 'Нам поручено оберегать это место!', 28153),
(158798, 'ruRU', 'Сияющие камни – дар этим землям!', 'Сияющие камни – дар этим землям!', 28153),
(158797, 'ruRU', 'Мы должны сохранять равновесие!', 'Мы должны сохранять равновесие!', 28153),
(158796, 'ruRU', 'Ты не осквернишь нашу рощу!', 'Ты не осквернишь нашу рощу!', 28153),
(158795, 'ruRU', 'Я внемлю зову природы!', 'Я внемлю зову природы!', 28153),
(158794, 'ruRU', 'Тебе не осквернить эту землю!', 'Тебе не осквернить эту землю!', 28153),
(158793, 'ruRU', 'Природа направит мой гнев!', 'Природа направит мой гнев!', 28153),
(158792, 'ruRU', 'Мне нужно защитить лес!', 'Мне нужно защитить лес!', 28153),
(158791, 'ruRU', 'Я каждый день прихожу, чтобы поговорить с дедушкой и бабушкой. Кажется, они меня слышат!', '', 28153),
(158790, 'ruRU', 'Ох...', 'Ох...', 28153),
(158789, 'ruRU', 'Где я?..', 'Где я?..', 28153),
(158788, 'ruRU', 'Ох... кровь...', 'Ох... кровь...', 28153),
(158787, 'ruRU', '', 'Когда выиграем битву, начнется настоящая работа.', 28153),
(158786, 'ruRU', 'Моя ярость... угасает...', 'Моя ярость... угасает...', 28153),
(158785, 'ruRU', 'Ты... за что?..', 'Ты... за что?..', 28153),
(158784, 'ruRU', 'Надо... бежать...', 'Надо... бежать...', 28153),
(158783, 'ruRU', 'Мой взор... прояснился...', 'Мой взор... прояснился...', 28153),
(158782, 'ruRU', 'А-а... боль...', 'А-а... боль...', 28153),
(158781, 'ruRU', 'Ра-ар!', 'Ра-ар!', 28153),
(158780, 'ruRU', 'Ощути мою ярость!', 'Ощути мою ярость!', 28153),
(158779, 'ruRU', 'Мне незнаком твой запах...', 'Мне незнаком твой запах...', 28153),
(158778, 'ruRU', 'Чую страх...', 'Чую страх...', 28153),
(158777, 'ruRU', 'Уходи... ар-р-р...', 'Уходи... ар-р-р...', 28153),
(158776, 'ruRU', 'Убью... тебя...', 'Убью... тебя...', 28153),
(158775, 'ruRU', 'Гр-р-р...', 'Гр-р-р...', 28153),
(158774, 'ruRU', 'Ар-р-р!', 'Ар-р-р!', 28153),
(158773, 'ruRU', 'Смотри, какой вымахал! Весь в отца.', '', 28153),
(158772, 'ruRU', 'Проклятье...', 'Проклятье...', 28153),
(158771, 'ruRU', 'Я вижу... предков...', 'Я вижу... предков...', 28153),
(158770, 'ruRU', 'Духи... приветствуют меня...', 'Духи... приветствуют меня...', 28153),
(158769, 'ruRU', 'У тебя... нет чести...', 'У тебя... нет чести...', 28153),
(158768, 'ruRU', 'Ох... твоя взяла...', 'Ох... твоя взяла...', 28153),
(158767, 'ruRU', 'Всех нас... тебе не перебить...', 'Всех нас... тебе не перебить...', 28153),
(158766, 'ruRU', 'Я отомщу тебе... и после смерти...', 'Я отомщу тебе... и после смерти...', 28153),
(158765, 'ruRU', 'Я отправляюсь к духам...', 'Я отправляюсь к духам...', 28153),
(158764, 'ruRU', 'Я сделаю из твоих костей куклу и прокляну твою семью!', 'Я сделаю из твоих костей куклу и прокляну твою семью!', 28153),
(158763, 'ruRU', 'Для нас ты как грязь под ногами. Тебе здесь не место!', 'Для нас ты как грязь под ногами. Тебе здесь не место!', 28153),
(158762, 'ruRU', '', 'Кажется, будто вчера у нас появился этот малыш. А теперь посмотри на него!', 28153),
(158761, 'ruRU', 'Эй, а ты еще кто? Тебе здесь нечего делать, понятно?', 'Эй, а ты еще кто? Тебе здесь нечего делать, понятно?', 28153),
(158760, 'ruRU', 'Посмотрим, чего ты стоишь...', 'Посмотрим, чего ты стоишь...', 28153),
(158759, 'ruRU', 'Теперь камни наши! Мой клан станет сильнейшим!', 'Теперь камни наши! Мой клан станет сильнейшим!', 28153),
(158758, 'ruRU', 'Хе-хе, меня так просто не одолеть.', 'Хе-хе, меня так просто не одолеть.', 28153),
(158757, 'ruRU', 'Это мой остров и мои камешки, а тебя тут ждет только смерть.', 'Это мой остров и мои камешки, а тебя тут ждет только смерть.', 28153),
(158756, 'ruRU', 'Мы первыми здесь обосновались, и нашу землю тебе не отнять!', 'Мы первыми здесь обосновались, и нашу землю тебе не отнять!', 28153),
(158755, 'ruRU', 'Это наш остров!', 'Это наш остров!', 28153),
(158754, 'ruRU', 'Ты что делаешь на этом острове?', 'Ты что делаешь на этом острове?', 28153),
(158753, 'ruRU', 'На нас напали! Быстро сюда!', 'На нас напали! Быстро сюда!', 28153),
(158752, 'ruRU', 'Сейчас порубим!', 'Сейчас порубим!', 28153),
(158751, 'ruRU', 'Я тебя живьем съем!', 'Я тебя живьем съем!', 28153),
(158750, 'ruRU', 'Мы с тебя кожу сдерем!', 'Мы с тебя кожу сдерем!', 28153),
(158749, 'ruRU', 'Я сделаю бусы из твоих костей!', 'Я сделаю бусы из твоих костей!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158748, 'ruRU', 'Я вскрою тебе брюхо и выпью всю кровь!', 'Я вскрою тебе брюхо и выпью всю кровь!', 28153),
(158747, 'ruRU', 'Ра-а-ар! Я умираю с честью!', '', 28153),
(158746, 'ruRU', 'Ты... захватчик... мы ни в чем не провинились...', '', 28153),
(158745, 'ruRU', 'Камни... нас не спасли...', '', 28153),
(158744, 'ruRU', 'Мы вернемся... с подкреплением...', '', 28153),
(158743, 'ruRU', 'Звезды... лгали...', '', 28153),
(158742, 'ruRU', 'Я слышу зов... предков...', '', 28153),
(158741, 'ruRU', 'Духи приветствуют меня...', '', 28153),
(158740, 'ruRU', 'Я возвращаюсь... к предкам...', '', 28153),
(158739, 'ruRU', 'Звезды укажут цель моим кулакам. Пути грядущего начертаны твоей кровью!', '', 28153),
(158738, 'ruRU', 'Ветра поведали мне, что сегодня ты погибнешь.', '', 28153),
(158737, 'ruRU', 'Духи наделили меня мощью неугасимого пламени!', '', 28153),
(158736, 'ruRU', 'В этом бою тебе не победить, жалкое создание!', '', 28153),
(158735, 'ruRU', 'Богатства острова принадлежат нам, глупцы.', '', 28153),
(158734, 'ruRU', 'Предки наделили меня силой и мудростью!', '', 28153),
(158733, 'ruRU', 'Я обагрю свои рога вашей кровью, глупцы!', '', 28153),
(158732, 'ruRU', 'Я буду защищать свой клан!', '', 28153),
(158731, 'ruRU', 'Воины, ко мне!', '', 28153),
(158730, 'ruRU', 'Тревога! Нас атакуют!', '', 28153),
(158729, 'ruRU', 'Это наш остров, и тебе тут делать нечего!', '', 28153),
(158728, 'ruRU', 'Сияющие камни – наши. Тебе не на что рассчитывать!', '', 28153),
(158727, 'ruRU', 'Это место – наше, и ты его не получишь!', '', 28153),
(158726, 'ruRU', 'Нас атакуют! Дадим им отпор!', '', 28153),
(158725, 'ruRU', 'Духи направят мое оружие!', '', 28153),
(158724, 'ruRU', 'За предков!', '', 28153),
(158723, 'ruRU', 'Было... больно...', '', 28153),
(158722, 'ruRU', 'Зачем... ты здесь?..', '', 28153),
(158721, 'ruRU', 'А-а-а! Прямо в брюхо...', '', 28153),
(158720, 'ruRU', 'Ты... ворюга...', '', 28153),
(158719, 'ruRU', 'Нет! Мои камешки...', '', 28153),
(158718, 'ruRU', 'Ты... чего творишь?', '', 28153),
(158717, 'ruRU', 'Ух... плохо дело...', '', 28153),
(158716, 'ruRU', 'Почему стало темно?', '', 28153),
(158715, 'ruRU', '', 'Есть такие, для кого уговор – просто сделка. Пустые обещания, слова. Сиюминутные блага в обмен на неизвестность будущего.\n\nНо запомни: Бвонсамди возьмет свое, так или иначе.', 28153),
(158714, 'ruRU', 'Огры мои, пора крушить!', '', 28153),
(158713, 'ruRU', 'Нет! Мои камушки! Не твои! Мне нужней!', '', 28153),
(158712, 'ruRU', 'Камни делать нас сильными. Мы сильнее тебя!', '', 28153),
(158711, 'ruRU', 'Твоя голова стать мой трофей!', '', 28153),
(158710, 'ruRU', 'Взять их! Ломать им хребты!', '', 28153),
(158709, 'ruRU', 'Это мой остров, мелюзга. Мой!', '', 28153),
(158708, 'ruRU', 'Я тебя крушить и твою кровь пить!', '', 28153),
(158707, 'ruRU', 'Я тебя расплющить! Ра-а-ар!', '', 28153),
(158706, 'ruRU', 'Это мои камни! Ра-а-ар!', '', 28153),
(158705, 'ruRU', 'Не трожь наше добро!', '', 28153),
(158704, 'ruRU', 'Взять их!', '', 28153),
(158703, 'ruRU', 'Не трожь камушки!', '', 28153),
(158702, 'ruRU', 'Это мой остров! Проваливай!', '', 28153),
(158701, 'ruRU', 'Убить чужака!', '', 28153),
(158700, 'ruRU', 'Крушить! Ломать! Убивать!', '', 28153),
(158699, 'ruRU', 'Я крушить тебя!', '', 28153),
(158698, 'ruRU', 'Может, если в этот раз я поклянусь вести себя хорошо, а не как раньше?..', 'Может, если в этот раз я поклянусь вести себя хорошо, а не как раньше?..', 28153),
(158697, 'ruRU', 'Что, по-твоему, от меня нужно Бвонсамди?', 'Что, по-твоему, от меня нужно Бвонсамди?', 28153),
(158696, 'ruRU', 'Что же делать... что делать... должен же быть какой-то выход!', 'Что же делать... что делать... должен же быть какой-то выход!', 28153),
(158695, 'ruRU', 'Если я договорюсь с Бвонсамди, то все станет, как прежде, да?', 'Если я договорюсь с Бвонсамди, то все станет, как прежде, да?', 28153),
(158694, 'ruRU', 'Ненавижу! Все ненавижу!', 'Ненавижу! Все ненавижу!', 28153),
(158693, 'ruRU', 'Это немыслимо! Неужели меня не узнали?', 'Это немыслимо! Неужели меня не узнали?', 28153),
(158692, 'ruRU', 'Я отомщу тому, кто сделал это со мной! Чего бы это ни стоило!', 'Я отомщу тому, кто сделал это со мной! Чего бы это ни стоило!', 28153),
(158691, 'ruRU', 'Как же так? Это нечестно!', 'Как же так? Это нечестно!', 28153),
(158690, 'ruRU', 'Лучше не станет, и ты меня в этом не убедишь.', 'Лучше не станет, и ты меня в этом не убедишь.', 28153),
(158689, 'ruRU', 'Все было прекрасно... а теперь меня просто нет.', 'Все было прекрасно... а теперь меня просто нет.', 28153),
(158688, 'ruRU', 'Никогда мне больше не ощутить тепло солнца.', 'Никогда мне больше не ощутить тепло солнца.', 28153),
(158687, 'ruRU', 'Мне бы еще несколько дней... Столько всего можно было бы успеть!', 'Мне бы еще несколько дней... Столько всего можно было бы успеть!', 28153),
(158686, 'ruRU', 'Что значит мертв? Нет, я просто отдыхаю.', 'Что значит мертва? Нет, я просто отдыхаю.', 28153),
(158685, 'ruRU', 'Ты кто? Можешь не отвечать, это уже неважно...', 'Ты кто? Можешь не отвечать, это уже неважно...', 28153),
(158684, 'ruRU', 'Если не смотреть, то ничего и нет. Вот и все.', 'Если не смотреть, то ничего и нет. Вот и все.', 28153),
(158683, 'ruRU', 'Просто идти дальше... идти дальше... в итоге все получится...', 'Просто идти дальше... идти дальше... в итоге все получится...', 28153),
(158682, 'ruRU', 'Как ты смеешь хозяйничать в моей твердыне?! Пора это прекратить!', '', 28153),
(158681, 'ruRU', 'Силенок не хватает? Сразись со мной по-честному!', '', 28153),
(158680, 'ruRU', 'Думаешь, твоя жалкая машина поможет меня одолеть?!', '', 28153),
(158679, 'ruRU', 'Мне бросили вызов! Защищайтесь!', '', 28153),
(158678, 'ruRU', 'Но... Я слишком красив, чтобы умирать...', '', 28153),
(158677, 'ruRU', '', 'Я тебя... выпотрошу...', 28153),
(158676, 'ruRU', '', 'Я тебя в клочки порву!', 28153),
(158675, 'ruRU', 'Похороните меня в море...', '', 28153),
(158674, 'ruRU', 'Я протащу тебя под килем!', '', 28153),
(158673, 'ruRU', 'Уф... Не знаю, что хуже – его прическа или его стихи. Но стоит признать, Риду и правда не занимать опыта в амурных делах... и в бою.', '', 28153),
(158672, 'ruRU', 'Беккетт считает себя настоящей легендой.', '', 28153),
(158671, 'ruRU', 'У Луны, скажем так... суровый нрав.', '', 28153),
(158670, 'ruRU', 'Хе... вечны в этом мире... только налоги и...', '', 28153),
(158669, 'ruRU', 'Что тут у нас? Похоже, с кое-кого требуется взыскать долг.', '', 28153),
(158668, 'ruRU', '', 'Поспеши, $n, нельзя терять ни минуты. Верни мне мою дочь.', 28153),
(158666, 'ruRU', '', 'Предел Судьбы – это остров, куда ссылают самых опасных преступников и предателей. Оттуда нет возврата.', 28153),
(158665, 'ruRU', '', '$n! Что удалось узнать?', 28153),
(158661, 'ruRU', 'Я сматываю удочки! Спасибо тебе за помощь, $p!', '', 28153),
(158660, 'ruRU', 'Куа\'фон издает пронзительный визг и взволнованно машет хвостом.', '', 28153),
(158659, 'ruRU', 'Куа\'фон отдает вам череп.', '', 28153),
(158658, 'ruRU', 'Куа\'фон роняет череп и игриво вскрикивает.', '', 28153),
(158657, 'ruRU', '', 'Мы проиграли. Тельдрассил скоро падет.', 28153),
(158656, 'ruRU', 'Тебя смоет приливом!', '', 28153),
(158655, 'ruRU', 'Идем. Вождь приведет нас... к победе.', '', 28153),
(158654, 'ruRU', '', 'Сработало! Залезайте!', 28153),
(158653, 'ruRU', 'Нет. Это я дам тебе выбор. Забери мужа в Дарнас и погибни вместе с ним, когда мы придем... или унеси его подальше, и вы оба выживете.', '', 28153),
(158652, 'ruRU', '', 'Ты пощадил Малфуриона, и я дам тебе выбор.', 28153),
(158651, 'ruRU', '', 'Не сдавайтесь.', 28153),
(158650, 'ruRU', 'У нас есть цель. Мы проливаем кровь, чтобы спасти Орду.', '', 28153),
(158649, 'ruRU', '', 'Как и во всей этой войне! Как вы посмели пролить столько невинной крови... ни за что?!', 28153),
(158648, 'ruRU', 'Я ударил в спину. В этом не было чести.', '', 28153),
(158647, 'ruRU', '', 'Ты не убил его. Почему?', 28153),
(158646, 'ruRU', '', 'Малфурион! Нет!', 28153),
(158645, 'ruRU', 'Ты ведешь... Орду... под знаменами... смерти. Однажды... ты пожалеешь...', '', 28153),
(158642, 'ruRU', '', 'Исцели свои раны и отдохни. Здесь ты в безопасности.', 28153),
(158641, 'ruRU', 'Я бился с ящером, и он оказался мне не по силам. Ты же знаешь, как это бывает.', 'Я билась с ящером, и он оказался мне не по силам. Ты же знаешь, как это бывает.', 28153),
(158640, 'ruRU', 'Я понимаю не больше твоего.', 'Я понимаю не больше твоего.', 28153),
(158639, 'ruRU', 'Чили Ха\'ли оказалось слишком острым.', 'Чили Ха\'ли оказалось слишком острым.', 28153),
(158638, 'ruRU', 'Смерть настигла меня во время Торканаты. И я снова сделал бы это, если б мог!', 'Смерть настигла меня во время Торканаты. И я снова сделала бы это, если б могла!', 28153),
(158637, 'ruRU', 'Тело свое оставишь у двери, да?', 'Тело свое оставишь у двери, да?', 28153),
(158636, 'ruRU', 'Меня молния ударила во время прогулки по Сокало.', 'Меня молния ударила во время прогулки по Сокало.', 28153),
(158635, 'ruRU', 'Меня угораздило рухнуть с пирамиды, а потом я как-то сразу оказался здесь.', 'Меня угораздило рухнуть с пирамиды, а потом я как-то сразу оказалась здесь.', 28153),
(158634, 'ruRU', 'Наряд есть, а пойти некуда.', 'Наряд есть, а пойти некуда.', 28153),
(158633, 'ruRU', 'Вычислить точные координаты для размещения портала в Боралусе было непросто, но для меня чем сложнее задача, тем интереснее! Расскажешь потом, как все прошло?', '', 28153),
(158632, 'ruRU', 'Как прикажешь, Натанос.', '', 28153),
(158631, 'ruRU', 'Зеллинг, $n, отправляйтесь в Боралус. Окулет уже открыл портал.', '', 28153),
(158630, 'ruRU', 'Здорово. Надо бы нам поговорить.', '', 28153),
(158629, 'ruRU', 'Это лучшее место в зале... Получишь его, только когда я уйду.', '', 28153),
(158628, 'ruRU', '', '$p? Пф, я о тебе даже не слышала.', 28153),
(158627, 'ruRU', 'Хобарт будет ждать тебя снаружи, когда захочешь отправиться к кораблям.', '', 28153),
(158626, 'ruRU', 'Потом не говори, что мы тебя не предупреждали.', 'Потом не говори, что мы тебя не предупреждали.', 28153),
(158625, 'ruRU', 'Стой! Иначе пожалеешь!', 'Стой! Иначе пожалеешь!', 28153),
(158624, 'ruRU', 'Куа\'фон дрожит от страха.', '', 28153),
(158623, 'ruRU', 'Ветер сейчас как раз попутный, не так ли, $n?', '', 28153),
(158622, 'ruRU', 'Я чувствую, нас с тобой ждет большой успех.', '', 28153),
(158621, 'ruRU', 'Ты не можешь меня здесь бросить! У меня слишком старые и хрупкие кости, я не могу работать в шахте.', 'Ты не можешь меня здесь бросить! У меня слишком старые и хрупкие кости, я не могу работать в шахте.', 28153),
(158620, 'ruRU', 'Теперь я понимаю, где мы могли ошибиться на стадии ферментации.', '', 28153),
(158619, 'ruRU', 'Значит, появление невидимых загрязнителей может влиять на процесс первоначального изменения состояния.', '', 28153),
(158618, 'ruRU', 'Сделаем.', '', 28153),
(158617, 'ruRU', 'Помогу, чем смогу.', '', 28153),
(158616, 'ruRU', 'Пора на работу.', '', 28153),
(158615, 'ruRU', 'Конечно, я помогу.', '', 28153),
(158614, 'ruRU', 'Думаю, смогу помочь.', '', 28153),
(158612, 'ruRU', '', 'Посмотри вокруг. У деревьев есть глаза. Ослепи их.', 28153),
(158611, 'ruRU', 'Первым делом нам следует сосредоточиться на стабилизации ключевых компонентов.', '', 28153),
(158610, 'ruRU', 'Ого! Это многое объясняет! \"Первый закон алхимии: чтобы получить что-то полезное, необходимо обеспечить эквивалентный обмен\".', '', 28153),
(158609, 'ruRU', 'Вперед!', 'Вперед!', 28153),
(158608, 'ruRU', 'Важнее всего тщательно выверенное использование нагрева... Это интригует.', '', 28153),
(158607, 'ruRU', 'А-а! Думаю, я понял, что было не так с катализатором.', '', 28153),
(158606, 'ruRU', 'Странно... это невозможно было предсказать.', '', 28153),
(158605, 'ruRU', 'Хм... что ж, это интересно.', '', 28153),
(158604, 'ruRU', 'Наших ребят взяли в оборот. Ты уж выручи их, а?', '', 28153),
(158603, 'ruRU', 'Эй! Кто-то стырил наши припасы! БЫСТРО верните их, а с воров выбейте процентик!', '', 28153),
(158602, 'ruRU', 'Ух-х, да тут раненые ПОВСЮДУ! Срочно нужна помощь лекарей!', '', 28153),
(158601, 'ruRU', 'Разбойники, хватит прятаться! Есть работка.', '', 28153),
(158600, 'ruRU', 'Найдешь какие-нибудь запчасти – неси их ко мне! Когда подлатаем эту крошку – можешь покататься.', '', 28153),
(158599, 'ruRU', 'Кажется, тут есть кому задать хорошенькую кезанскую трепку.', '', 28153),
(158598, 'ruRU', 'Ох ты, что за ГРОМАДИНА! Кто возьмется ее завалить?', '', 28153),
(158597, 'ruRU', 'Наших союзников захватили в плен. Не желаете устроить для них побег?', '', 28153),
(158596, 'ruRU', 'Враги скрылись с большим запасом полезных припасов. Покажем им, что такое правосудие Альянса!', '', 28153),
(158595, 'ruRU', 'У нас есть раненые. Кто-нибудь может помочь?', '', 28153),
(158594, 'ruRU', 'Да, дитя. Элуна даровала друидам достаточно силы, чтобы призвать попутный ветер.', '', 28153),
(158593, 'ruRU', '', 'Сокрытое море смилостивилось?', 28153),
(158592, 'ruRU', 'Отправь меня обратно в бухту.', 'Отправь меня обратно в бухту.', 28153),
(158591, 'ruRU', 'Отправь меня на корабль поменьше.', 'Отправь меня на корабль поменьше.', 28153),
(158590, 'ruRU', 'Я ищу добровольцев для тайной операции. Умение прятаться и бить в спину приветствуется.', '', 28153),
(158589, 'ruRU', 'Мы разбираем вражескую боевую машину на запчасти. Соберите столько, сколько сможете.', '', 28153),
(158588, 'ruRU', 'Ага. Обнаружилась подходящая цель.', '', 28153),
(158587, 'ruRU', 'На поле боя появился крупный и опасный монстр. Охота начинается!', '', 28153),
(158586, 'ruRU', 'Хочешь поздороваться с моим маленьким дружком?', '', 28153),
(158585, 'ruRU', 'На взрыв нарываешься?', '', 28153),
(158584, 'ruRU', 'Эй. Полегче.', '', 28153),
(158583, 'ruRU', 'Голову по дороге не потеряй!', '', 28153),
(158582, 'ruRU', 'Не зевай!', '', 28153),
(158581, 'ruRU', 'Осторожнее там.', '', 28153),
(158580, 'ruRU', 'Что нового?', '', 28153),
(158579, 'ruRU', 'Как оно?', '', 28153),
(158578, 'ruRU', 'Неплохо выглядишь!', '', 28153),
(158577, 'ruRU', 'Свет милосердный, где бы выпить...', '', 28153),
(158576, 'ruRU', 'Офицерам за такое не платят.', '', 28153),
(158575, 'ruRU', 'Да, да...', '', 28153),
(158574, 'ruRU', 'Иди своей дорогой.', '', 28153),
(158573, 'ruRU', 'Вольно.', '', 28153),
(158572, 'ruRU', 'Не теряй врага из виду.', '', 28153),
(158571, 'ruRU', 'Да?', '', 28153),
(158570, 'ruRU', 'Я весь внимание.', '', 28153),
(158569, 'ruRU', 'Слава Альянсу.', '', 28153),
(158568, 'ruRU', '', 'Нет... не может быть.', 28153),
(158565, 'ruRU', '', 'Ты поможешь мне выяснить пределы моей силы!', 28153),
(158564, 'ruRU', '', 'Некоторые говорят, что моя магия жестока, но я лишь изучаю границы возможного.', 28153),
(158563, 'ruRU', 'Выкапывание', 'Выкапывание', 28153),
(158562, 'ruRU', 'Миа... МИА! Посмотри на меня... любовь моя...', '', 28153),
(158561, 'ruRU', 'Да хранит вас ваша богиня.', '', 28153),
(158560, 'ruRU', 'Королева банши отняла у меня сына и корону. Тебя она не отнимет!', '', 28153),
(158559, 'ruRU', '', 'Они... не пойдут...', 28153),
(158558, 'ruRU', 'Астария, вы сделали все, что могли! Вели жрицам уходить с нами!', '', 28153),
(158557, 'ruRU', 'Нет! Я спасу вас обеих!', '', 28153),
(158555, 'ruRU', '', 'Древо... Они подожгли Древо... Забери ребенка. Уходи...', 28153),
(158554, 'ruRU', 'Здесь нельзя оставаться! Давай уйдем через портал вместе!', '', 28153),
(158553, 'ruRU', '', 'Астария, у нас мало времени! Уводите мирных жителей, пока город не сгорел дотла!', 28153),
(158551, 'ruRU', '', 'Добей его, и забудем об этом. Можешь не торопиться... Принеси его голову к Древу Жизни.', 28153),
(158550, 'ruRU', '', 'Моя победа была неотвратима. Он только тратил мое время.', 28153),
(158549, 'ruRU', 'Я не должен был вмешиваться.', '', 28153),
(158548, 'ruRU', '', 'Ты все сделал правильно.', 28153),
(158547, 'ruRU', 'Это был... подлый удар... Мне жаль.', '', 28153),
(158546, 'ruRU', 'А-а-а! Саур... фанг?!', '', 28153),
(158545, 'ruRU', 'Вождь сражается с Малфурионом одна! Я должен...', '', 28153),
(158544, 'ruRU', 'С севера? Но как?.. Конечно же!.. Они перешли через горы!', '', 28153),
(158543, 'ruRU', 'Вы с Деларин перехватите Орду в Аубердине. Я пойду на север.', '', 28153),
(158542, 'ruRU', 'Еще немного – и Орда прорвется через стену и нападет с обеих сторон.', '', 28153),
(158541, 'ruRU', 'Огоньки... Они разлетаются! Стена рушится!', '', 28153),
(158540, 'ruRU', '', 'Этот звук... это... Шан\'до! Орда наступает с севера!', 28153),
(158539, 'ruRU', '', 'Время пришло. Древо Жизни будет нашим! Найди Саурфанга. Покончим с этим раз и навсегда.', 28153),
(158537, 'ruRU', '', 'Посмотри, какой восхитительный вид! Огоньки разлетаются один за другим. Стена рушится на глазах.', 28153),
(158536, 'ruRU', '', 'Саурфанг! Наконец-то.', 28153),
(158535, 'ruRU', 'ЗА ОРДУ!', '', 28153),
(158534, 'ruRU', '', 'Куда же ты упорхнул?', 28153),
(158533, 'ruRU', '', 'А-а! Глаза! Мои глаза!', 28153),
(158532, 'ruRU', 'Сгинь, ведьма!', '', 28153),
(158531, 'ruRU', '', 'Надо же... Прибежал защищать свои драгоценные деревья?', 28153),
(158530, 'ruRU', '', 'Малфурион! Как мило, что ты нас посетил...', 28153),
(158529, 'ruRU', 'Сильвана! Ты оскверняешь эту священную землю! Анду-фала-дор!', '', 28153),
(158528, 'ruRU', '', 'Отныне у них не будет ни одной спокойной ночи. Это война.', 28153),
(158527, 'ruRU', '', 'Мы будем делать все возможное, чтобы не давать калдорай передышки.', 28153),
(158526, 'ruRU', '', 'Пока мы ждем вестей от Саурфанга, я буду проводить войска через стену.', 28153),
(158525, 'ruRU', '', 'Держимся прежнего плана.', 28153),
(158524, 'ruRU', '', 'Бой у Петляющей реки затянется надолго, и Малфурион об этом знает.', 28153),
(158523, 'ruRU', '', 'Герои Орды, выступайте к Петляющей реке! Это наш шанс на победу!', 28153),
(158522, 'ruRU', '', 'Мне пора на охоту.', 28153),
(158521, 'ruRU', '', 'Не мешкай. Собери столько азерита, сколько сможешь, и передай инженерам.', 28153),
(158520, 'ruRU', '', 'Этот корабль прибыл из Дарнаса, а значит...', 28153),
(158519, 'ruRU', '', 'Осторожнее – кажется, Альянс добрался до него раньше нас.', 28153),
(158518, 'ruRU', '', 'Азерит... С его помощью мы уничтожим всех, кто встанет на нашем пути.', 28153),
(158517, 'ruRU', '', 'Саперы! Берите снаряжение и за мной! Нам нужны крошшеры.', 28153),
(158516, 'ruRU', '', 'Успокой их, иначе кровь наших солдат зальет этот лес.', 28153),
(158515, 'ruRU', '', 'Вижу, ты сомневаешься. Древней обратили даже против вас, друидов. Против их собственной природы.', 28153),
(158514, 'ruRU', 'Телия! Самое время подобрать нас!', '', 28153),
(158513, 'ruRU', 'То есть \"сигануть с обрыва подобру-поздорову\"!', '', 28153),
(158512, 'ruRU', 'И эффектно смыться!', '', 28153),
(158511, 'ruRU', 'Нужно только схватить сейф...', '', 28153),
(158510, 'ruRU', 'Никогда не думал, что солнце может так сильно жечь то, что осталось от кожи.', 'Никогда не думала, что солнце может так сильно жечь то, что осталось от кожи.', 28153),
(158509, 'ruRU', 'Уверяю, мой план безупречен.', '', 28153),
(158508, 'ruRU', 'Полагаю, у тебя есть план, как нам его отсюда вынести?', 'Полагаю, у тебя есть план, как нам его отсюда вынести?', 28153),
(158507, 'ruRU', 'Харлан усилил защиту – повесил еще один замок на свой сейф.\n\n<Флинн потирает подбородок.>\n\nДа. Сейчас нам ничего не остается... только украсть его.', '', 28153),
(158506, 'ruRU', 'Молодец, Харлан. Молодец.', '', 28153),
(158505, 'ruRU', 'Всем, кого найду, придется навернуть по сто кругов вокруг академии.', '', 28153),
(158504, 'ruRU', 'Они должны быть где-то рядом.', '', 28153),
(158503, 'ruRU', 'Мы не просили, чтобы нас возвращали к жизни... И не хотели проходить через все это.', 'Мы не просили, чтобы нас возвращали к жизни... И не хотели проходить через все это.', 28153),
(158502, 'ruRU', 'Что? Четыре замка?!', '', 28153),
(158501, 'ruRU', 'И Альянс считает монстрами нас?!', 'И Альянс считает монстрами нас?!', 28153),
(158500, 'ruRU', 'Куда запропастились эти кадеты?..', '', 28153),
(158499, 'ruRU', 'А вот и он. Сейф Красавчика Харлана.', '', 28153),
(158498, 'ruRU', 'Учитывая произошедшее, я ей не завидую. Возможно, ей пора передать бразды правления Кул-Тирасом более достойному лидеру.', 'Учитывая произошедшее, я ей не завидую. Возможно, ей пора передать бразды правления Кул-Тирасом более достойному лидеру.', 28153),
(158497, 'ruRU', 'С каждым днем становится все очевиднее, что Кэтрин просто пользуется наследием своего покойного мужа.', 'С каждым днем становится все очевиднее, что Кэтрин просто пользуется наследием своего покойного мужа.', 28153),
(158496, 'ruRU', 'Еще одна неделя без встреч благородных домов.', 'Еще одна неделя без встреч благородных домов.', 28153),
(158495, 'ruRU', 'Это точно. Любой уважающий себя тирагардский дворянин догадался бы не давать жертве шанса обернуть эту душещипательную историю себе на пользу.', 'Это точно. Любой уважающий себя тирагардский дворянин догадался бы не давать жертве шанса обернуть эту душещипательную историю себе на пользу.', 28153),
(158494, 'ruRU', 'Убийство средь бела дня, да к тому же перед самой свадьбой. Это явно планировали дилетанты.', 'Убийство средь бела дня, да к тому же перед самой свадьбой. Это явно планировали дилетанты.', 28153),
(158493, 'ruRU', 'Вы о ее женихе? Разумеется. Такая трагедия!', 'Вы о ее женихе? Разумеется. Такая трагедия!', 28153),
(158492, 'ruRU', 'Слышали, что стряслось с дочерью Уэйкрестов?', 'Слышали, что стряслось с дочерью Уэйкрестов?', 28153),
(158491, 'ruRU', 'Какой позор! Штормсонг, не способный повелевать морем? Будь я главой семейства, давно бы отрекся от этого мальчишки.', 'Какой позор! Штормсонг, не способный повелевать морем? Будь я главой семейства, давно бы отреклась от этого мальчишки.', 28153),
(158490, 'ruRU', 'Так дядя просто сослал его сюда и повесил эту обузу на нас?', 'Так дядя просто сослал его сюда и повесил эту обузу на нас?', 28153),
(158489, 'ruRU', 'Говорят, Брэннон вернулся и теперь работает на поморье.', 'Говорят, Брэннон вернулся и теперь работает на поморье.', 28153),
(158488, 'ruRU', 'Хорошо, что Джайна похожа на мать. Дэлин яркой внешностью не отличался.', 'Хорошо, что Джайна похожа на мать. Дэлин яркой внешностью не отличался.', 28153),
(158487, 'ruRU', '', '<Из спины тролля торчит кинжал, а все ее вещи украдены.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158486, 'ruRU', '', '<Труп зандаларского тролля еще не остыл.>', 28153),
(158485, 'ruRU', '<Осмотреть тело.>', '<Осмотреть тело.>', 28153),
(158484, 'ruRU', 'Уэйкресты давненько не появлялись в Боралусе. Неужели Мередит наконец-то поняла, что ее здесь не желают видеть?', 'Уэйкресты давненько не появлялись в Боралусе. Неужели Мередит наконец-то поняла, что ее здесь не желают видеть?', 28153),
(158483, 'ruRU', 'Видели, во что вырядился лорд Штормсонг в прошлый раз? По-моему, шляпа со щупальцами – прошлый век.', 'Видели, во что вырядился лорд Штормсонг в прошлый раз? По-моему, шляпа со щупальцами – прошлый век.', 28153),
(158482, 'ruRU', '<Саймон смотрит на Кунгу.>\n\nХм, да... Ха! Ха-ха! А у тебя хорошее чувство юмора!\n\nХа-ха! Очень смешно!\n\nУходи-ка отсюда побыстрее, пока еще кто-нибудь не нашелся. Ха-ха!\n\nПоследи за боем, пока я... пополняю запасы.', '', 28153),
(158481, 'ruRU', 'Я нашел труп за палаткой.', 'Я нашла труп за палаткой.', 28153),
(158480, 'ruRU', 'Привет... э-э... да.\n\nДобро пожаловать в мою лавку... \"Лавку... Саймона... продавца... разных штук\".\n\nЯ продаю...\n\n<Саймон бросает взгляд за спину.>\n\n...оружие. Самое разное. Но сейчас не время.\n\nПриходи после того, как я... расширю ассортимент.', '', 28153),
(158479, 'ruRU', 'Я тебя прикончу, отродье Орды!', '', 28153),
(158478, 'ruRU', 'Альянс не имеет никаких прав на наши земли!', 'Альянс не имеет никаких прав на наши земли!', 28153),
(158477, 'ruRU', 'Все лучше, чем питаться одним хлебом.', '', 28153),
(158476, 'ruRU', 'Все наши ресурсы брошены на то, чтобы выиграть время для эвакуации и сдержать Орду. Поищи что-нибудь съестное для наших часовых.', '', 28153),
(158475, 'ruRU', '', 'Я отправлю тебя прямиком на морское дно!', 28153),
(158474, 'ruRU', 'А в кармане-то у меня не моджо!', '', 28153),
(158473, 'ruRU', 'Тебе я пропишу самое горькое лекарство!', '', 28153),
(158472, 'ruRU', 'Я тебя сейчас в жабу превращу!', '', 28153),
(158471, 'ruRU', 'Ты это перестань. Я старый, а это значит, что я знаю толк в проклятьях.', '', 28153),
(158470, 'ruRU', 'Эй, молодежь, не распускай руки.', '', 28153),
(158469, 'ruRU', 'Я всю жизнь обучаю племя Черного Копья.', '', 28153),
(158468, 'ruRU', 'Удачи! И держи хорошее моджо под рукой.', '', 28153),
(158467, 'ruRU', '', 'Все лучше, чем сухие пайки.', 28153),
(158466, 'ruRU', '', 'Сытый солдат – хороший солдат. По крайней мере, так говорят. В этом лесу должно быть что-нибудь съестное.', 28153),
(158465, 'ruRU', 'Помни: не все можно регенерировать.', '', 28153),
(158464, 'ruRU', 'Берегись!', '', 28153),
(158463, 'ruRU', 'Почти готово, еще немного! Буквально минуточку...', '', 28153),
(158462, 'ruRU', 'Хм-м, отделить листья сложнее, чем казалось... но, кажется, дело идет на лад!', '', 28153),
(158461, 'ruRU', 'Тут придется повозиться. Сбор листьев – дело трудоемкое.', '', 28153),
(158460, 'ruRU', 'Годы берут свое.', '', 28153),
(158459, 'ruRU', 'Пусть духи хранят тебя.', '', 28153),
(158458, 'ruRU', 'Икум бокум.', '', 28153),
(158457, 'ruRU', 'Знахаря вызывали?', '', 28153),
(158456, 'ruRU', 'Помочь как-то?', '', 28153),
(158455, 'ruRU', 'Ну, чего, как?', '', 28153),
(158454, 'ruRU', 'Я хочу, чтобы духи указали мне путь.', 'Я хочу, чтобы духи указали мне путь.', 28153),
(158453, 'ruRU', 'Духи могут указать тебе путь.', '', 28153),
(158452, 'ruRU', 'Уна\'фе, $n. Аванпост в твоем распоряжении.', '', 28153),
(158451, 'ruRU', '', 'Нужно найти поставщиков взрывчатки, иначе бандиты скоро снова вооружатся.', 28153),
(158450, 'ruRU', '', 'Наедайся досыта и отдохни немного!', 28153),
(158449, 'ruRU', 'Печать в этом зале защищает душу мира. Но сюда проникает столько азерита, что она может не выдержать!', '', 28153),
(158448, 'ruRU', 'Собери азерит в амулет и используй его силу чтобы укрепить печать!', '', 28153),
(158447, 'ruRU', '', 'Говорят, в руки к местным бандитам попала мощная азеритовая взрывчатка. Пока ты ее не найдешь, весь Боралус в опасности!', 28153),
(158446, 'ruRU', 'Мой корабль затонул, и мы все оказались в воде. Через час приплыли акулы. Маленькие, большие и очень злые. Мы отчаянно дрались с ними, но когда застывшие черные глаза акулы смотрят прямо на тебя – это нечто. Даже не верится, что перед тобой живое существо – пока она не кинется на тебя. Потом вдруг вода вокруг становится красной, в глазах темнеет – и через пару мгновений тебя просто разрывают на куски. В первую ночь акулы, должно быть, растерзали половину из нас. Даже десяток акул – это все равно что тысяча. Наконец прибыла помощь. Может, дней через пять – уже слишком поздно. Всего нас было триста шестнадцать – семерых спасли, а остальных съели акулы. \n\nВсе, хватит болтать. Не желаешь ли сразиться с акулами?', '', 28153),
(158445, 'ruRU', 'Спасибо. Я все же рискну. Дай мне ботинки.', 'Спасибо. Я все же рискну. Дай мне ботинки.', 28153),
(158444, 'ruRU', '', 'Ой! Я хотела сдвинуть ящики, которые... ну... упали с повозки.\n\nПо крайней мере, Кода в порядке. Моего лапочку ничто не берет!\n\nЕсли решишь вернуться на север, то у меня есть еще одна пара ботинок. Но предупреждаю: я их еще не проверяла.', 28153),
(158443, 'ruRU', '', 'Мы опоздали.', 28153),
(158442, 'ruRU', '', 'Помоги этим людям. Я полечу вперед!', 28153),
(158441, 'ruRU', '', 'Но сначала нужно отбить атаку.', 28153),
(158440, 'ruRU', '', 'Нет...', 28153),
(158439, 'ruRU', '', 'Мы знаем. Он получит по заслугам.', 28153),
(158438, 'ruRU', 'Харлан... Этот мерзавец продался Эшвейн... Он... А-а!', '', 28153),
(158437, 'ruRU', 'Уф... везде... <кашляет>', '', 28153),
(158436, 'ruRU', '', 'Флинн! Спокойно, приятель! С тобой все в порядке? Где болит?', 28153),
(158435, 'ruRU', 'Ух... а-у-у-а-а-А-А!!!', '', 28153),
(158434, 'ruRU', '', 'Хорошо. Пойдем, мама. Нам пора домой.', 28153),
(158433, 'ruRU', '', 'Держись крепче!', 28153),
(158432, 'ruRU', 'Я готов уходить.', 'Я готова уходить.', 28153),
(158431, 'ruRU', '', '$c, я перенесу нас отсюда, когда скажешь.\n\nПожалуйста, поспеши, мне не хочется здесь больше оставаться.', 28153),
(158430, 'ruRU', 'РОЛИК!', 'РОЛИК!', 28153),
(158429, 'ruRU', 'Ночные эльфы – замечательные соседи, но к огонькам еще привыкнуть надо.', '', 28153),
(158428, 'ruRU', 'Вот вам земля, пашите. На том и порешили.', '', 28153),
(158427, 'ruRU', 'То, что случилось с деревом, – настоящая трагедия.', '', 28153),
(158426, 'ruRU', 'Думаешь, ты помешаешь нам забрать тело Дерека? Тебя ждет сюрприз!', '', 28153),
(158425, 'ruRU', 'В этот раз Ло нужно просто достичь цели, но берегись опасностей, которые таятся в лабиринте.', '', 28153),
(158424, 'ruRU', 'А теперь проведи Ло сначала к сокровищу, а потом к цели, не пересекая собственный след.', '', 28153),
(158423, 'ruRU', 'Несложно, правда, $n?', '', 28153),
(158422, 'ruRU', 'Вот простое задание: приведи Ло к цели.', '', 28153),
(158421, 'ruRU', 'Во время рассказа юные тортолланы играют в Ло и решают головоломки в лабиринтах.', '', 28153),
(158420, 'ruRU', 'Готовы приступить к тренировке?', 'Готовы приступить к тренировке?', 28153),
(158419, 'ruRU', 'Покажем, на что мы способны, $p!', 'Покажем, на что мы способны, $p!', 28153),
(158418, 'ruRU', 'Удачный поход прибавил Ло уверенности и вдохновил на новые удивительные приключения.', '', 28153),
(158416, 'ruRU', 'Поможешь Ло собрать все сокровища и выйти наружу, не пересекая собственные следы?', '', 28153),
(158415, 'ruRU', 'Он стал исследовать древние развалины, нередко полные неслыханных сокровищ.', '', 28153),
(158414, 'ruRU', '\"Ло Кладоискатель\". С годами Ло становился все любознательнее.', '', 28153),
(158413, 'ruRU', 'Трудолюбие Ло окупилось с лихвой, и земля хорошо кормила его.', '', 28153),
(158412, 'ruRU', 'Поможешь Ло осмотреть все растения в саду? Всего один разочек!', '', 28153),
(158411, 'ruRU', 'Каждое утро он приходил в свой сад посмотреть на растения.', '', 28153),
(158410, 'ruRU', '', 'Очевидно, друстов не заботит, живы ли их пленники. Нельзя допустить, чтобы Джайну постигла та же участь!', 28153),
(158409, 'ruRU', '\"Жатва Ло\". Ло любил наблюдать, как растет и развивается все живое.', '', 28153),
(158408, 'ruRU', 'Ло едва унес ноги и решил заняться чем-то менее опасным.', '', 28153),
(158407, 'ruRU', 'Можешь помочь Ло отключить светящиеся плиты и вывести ловушку из строя?', '', 28153),
(158406, 'ruRU', '\"Любопытный тортоллан\". Однажды любопытство чуть не погубило Ло – он активировал древнюю зандаларскую ловушку!', '', 28153),
(158405, 'ruRU', '', 'Моли о пощаде!', 28153),
(158404, 'ruRU', 'Ло не понравилась городская суета. Он вернулся к простой и спокойной жизни.', '', 28153),
(158403, 'ruRU', 'И заблудился! Поможешь Ло зайти в каждую лавку и вернуться в таверну, не пересекая собственных следов?', '', 28153),
(158402, 'ruRU', '\"Жизнь в большом городе\". Однажды Ло приехал в большой город, похожий на ваш Боралус.', '', 28153),
(158401, 'ruRU', 'Теперь Ло наслаждается покоем... и приятной сытостью.', '', 28153),
(158399, 'ruRU', '', 'Мне удалось поймать рядом со святилищами несколько малых элементалей. Это просто потрясающе! Хочешь посмотреть, на что они способны?', 28153),
(158398, 'ruRU', 'Гости, бегите... Тут |3-6($pr)...', '', 28153),
(158397, 'ruRU', 'Есть хочу...', '', 28153),
(158396, 'ruRU', 'Эй, включите свет обратно!', '', 28153),
(158395, 'ruRU', 'Пока, Галливикс...', '', 28153),
(158394, 'ruRU', 'Только без драк!', '', 28153),
(158393, 'ruRU', 'Первый рабочий день! Вот свезло!', '', 28153),
(158392, 'ruRU', '|3-2($PR) сюда нельзя!', '', 28153),
(158391, 'ruRU', 'Сюдой нельзя!', '', 28153),
(158390, 'ruRU', 'Ты сегодня... даже до худшего клиента не дотягиваешь...', 'Ты сегодня... даже до худшего клиента не дотягиваешь...', 28153),
(158389, 'ruRU', 'Один гоблин... со льдом...', 'Один гоблин... со льдом...', 28153),
(158388, 'ruRU', 'Последний заказ... на каджа-колу...', 'Последний заказ... на каджа-колу...', 28153),
(158387, 'ruRU', 'Только попробуй... не дать на чай...', 'Только попробуй... не дать на чай...', 28153),
(158386, 'ruRU', 'Я так и не научился... играть в гольф...', 'Я так и не научилась... играть в гольф...', 28153),
(158385, 'ruRU', 'Ты всего лишь... подставка для клюшек...', 'Ты всего лишь... подставка для клюшек...', 28153),
(158384, 'ruRU', 'Только в униформе не хороните... Срам один...', 'Только в униформе не хороните... Срам один...', 28153),
(158383, 'ruRU', 'Ну хоть клюшки больше таскать не придется...', 'Ну хоть клюшки больше таскать не придется...', 28153),
(158382, 'ruRU', 'Большой Гэ... заставит тебя за это заплатить...', 'Большой Гэ... заставит тебя за это заплатить...', 28153),
(158381, 'ruRU', 'Эй, а как же... удовольствия?..', 'Эй, а как же... удовольствия?..', 28153),
(158380, 'ruRU', 'Нет... Я уход не отметил...', 'Нет... Я уход не отметила...', 28153),
(158379, 'ruRU', 'Пусть Галливикс... продолжает мне платить.', 'Пусть Галливикс... продолжает мне платить.', 28153),
(158378, 'ruRU', 'Уверен, чаевых я от тебя не получу. Нищеброды...', 'Уверена, чаевых я от тебя не получу. Нищеброды...', 28153),
(158377, 'ruRU', 'Руки прочь от каджа-колы!', 'Руки прочь от каджа-колы!', 28153),
(158376, 'ruRU', 'Я из твоей селезенки мартини сделаю... будет мартенка!', 'Я из твоей селезенки мартини сделаю... будет мартенка!', 28153),
(158375, 'ruRU', 'Я что-то слышу...', 'Я что-то слышу...', 28153),
(158374, 'ruRU', 'Напитки в стоимость билета не входят!', 'Напитки в стоимость билета не входят!', 28153),
(158373, 'ruRU', 'А что если я проделаю тебе лунку... в коленке!', 'А что если я проделаю тебе лунку... в коленке!', 28153),
(158372, 'ruRU', '<Врач поворачивается к вам и шепчет.>$b$bОни очень серьезно ранены. Мы не можем их перемещать в таком состоянии. Лучшее, что я могу сделать, – это немного их подлатать и уносить оттуда ноги.$b$bТам просто ужас что творится...', 'n/a', 28153),
(158371, 'ruRU', 'Все лучше, чем смотреть, как эти мазилы весь день в лунку попасть не могут.', 'Все лучше, чем смотреть, как эти мазилы весь день в лунку попасть не могут.', 28153),
(158370, 'ruRU', 'В такой ситуации я рекомендую бить клюшкой в лицо!', 'В такой ситуации я рекомендую бить клюшкой в лицо!', 28153),
(158369, 'ruRU', 'Наконец-то я что-нибудь ударю!', 'Наконец-то я что-нибудь ударю!', 28153),
(158368, 'ruRU', 'Ха! Надурил! Я из охраны!', 'Ха! Надурила! Я из охраны!', 28153),
(158367, 'ruRU', 'Не боись, у меня все схвачено.', 'Не боись, у меня все схвачено.', 28153),
(158366, 'ruRU', 'Гостей не трогай!', 'Гостей не трогай!', 28153),
(158365, 'ruRU', 'Мне за это не платят.', 'Мне за это не платят.', 28153),
(158364, 'ruRU', 'Я только еще немножко... полежу на солнышке...', 'Я только еще немножко... полежу на солнышке...', 28153),
(158363, 'ruRU', 'Оставьте меня на солнце... переверните, когда начну подгорать...', 'Оставьте меня на солнце... переверните, когда начну подгорать...', 28153),
(158362, 'ruRU', 'Ха! А говорили, меня солнце убьет...', 'Ха! А говорили, меня солнце убьет...', 28153),
(158361, 'ruRU', 'О нет, мое прекрасное загорелое тело...', 'О нет, мое прекрасное загорелое тело...', 28153),
(158360, 'ruRU', 'Я Галливиксу... все выскажу...', 'Я Галливиксу... все выскажу...', 28153),
(158359, 'ruRU', 'Мне просто хотелось повеселиться...', 'Мне просто хотелось повеселиться...', 28153),
(158358, 'ruRU', 'Ни дворца... ни удовольствий...', 'Ни дворца... ни удовольствий...', 28153),
(158357, 'ruRU', 'Но я... очень важная персона...', 'Но я... очень важная персона...', 28153),
(158356, 'ruRU', 'Кэдди, отнеси меня... к лунке.', 'Кэдди, отнеси меня... к лунке.', 28153),
(158355, 'ruRU', 'Хотя бы... быстрая смерть.', 'Хотя бы... быстрая смерть.', 28153),
(158354, 'ruRU', 'Похороните меня... в песчаной ловушке.', 'Расскажите всем... что я играл, как боженька.', 28153),
(158353, 'ruRU', 'Расскажите всем... что я играл, как боженька.', 'Расскажите всем... что я играла, как боженька.', 28153),
(158352, 'ruRU', 'Лучшая вечерника... в моей жизни.', 'Лучшая вечерника... в моей жизни.', 28153),
(158351, 'ruRU', 'Худшая вечерника... в моей жизни.', 'Худшая вечерника... в моей жизни.', 28153),
(158350, 'ruRU', 'Я требую... компенсации.', 'Я требую... компенсации.', 28153),
(158349, 'ruRU', 'Еще... один... глоточек...', 'Еще... один... глоточек...', 28153),
(158348, 'ruRU', 'Все занято! Иди поплещись где-нибудь в другом месте!', 'Все занято! Иди поплещись где-нибудь в другом месте!', 28153),
(158347, 'ruRU', 'Это бассейн не для |3-8($pr)!', 'Это бассейн не для |3-8($pr)!', 28153),
(158346, 'ruRU', 'Нет, ну вы видели, как я нырнул? Десять из десяти!', 'Нет, ну вы видели, как я нырнула? Десять из десяти!', 28153),
(158345, 'ruRU', 'Эй, |3-6($pr)! Ты мне солнце загораживаешь!', 'Эй, |3-6($pr)! Ты мне солнце загораживаешь!', 28153),
(158344, 'ruRU', 'Клянусь, с охраной у Галливикса все хуже и хуже.', 'Клянусь, с охраной у Галливикса все хуже и хуже.', 28153),
(158343, 'ruRU', 'За что я столько денег отвалил? Чтобы на меня нападали всякие уроды вроде |3-1($pr)?', 'За что я столько денег отвалила? Чтобы на меня нападали всякие уроды вроде |3-1($pr)?', 28153),
(158342, 'ruRU', 'Сгинь, $p. Иди доставай народ в другом месте.', 'Сгинь, $p. Иди доставай народ в другом месте.', 28153),
(158341, 'ruRU', 'Подержи-ка мою каджа-колу. Я разберусь.', 'Подержи-ка мою каджа-колу. Я разберусь.', 28153),
(158340, 'ruRU', 'Держись от газона подальше! Всю траву вытопчешь!', 'Держись от газона подальше! Всю траву вытопчешь!', 28153),
(158339, 'ruRU', 'Кэдди, водителя мне! Тут народ нарывается.', 'Кэдди, водителя мне! Тут народ нарывается.', 28153),
(158338, 'ruRU', 'Следующий мяч будет у тебя в черепе!', 'Следующий мяч будет у тебя в черепе!', 28153),
(158337, 'ruRU', 'Тут препятствие! Чур я делаю вторую попытку!', 'Тут препятствие! Чур я делаю вторую попытку!', 28153),
(158336, 'ruRU', 'Катись отсюда, |3-6($pr)! Не мешай пить, есть и снова пить!', 'Катись отсюда, |3-6($pr)! Не мешай пить, есть и снова пить!', 28153),
(158335, 'ruRU', 'О, дополнительные развлечения!', 'О, дополнительные развлечения!', 28153),
(158334, 'ruRU', 'Охрана! Увести отсюда |3-1($pr)!', 'Охрана! Увести отсюда |3-1($pr)!', 28153),
(158333, 'ruRU', 'Я читерный комплект Альянса не покупал!', 'Я читерный комплект Альянса не покупала!', 28153),
(158332, 'ruRU', 'Больненько...', '', 28153),
(158331, 'ruRU', 'Гоблины... бежите!', '', 28153),
(158330, 'ruRU', 'Просто хотеть... блестяшку...', '', 28153),
(158329, 'ruRU', 'Я старался...', '', 28153),
(158328, 'ruRU', 'Передайте Большому Гэ... я извиняюся...', '', 28153),
(158327, 'ruRU', 'Вы работайте...', '', 28153),
(158326, 'ruRU', 'Спать охота...', '', 28153),
(158325, 'ruRU', 'Не останавливаться... золото...', '', 28153),
(158324, 'ruRU', 'Не трогать!', '', 28153),
(158323, 'ruRU', 'Наше золотишечко!', '', 28153),
(158322, 'ruRU', 'Большой Гэ говорить бить |3-3($pr).', '', 28153),
(158321, 'ruRU', 'Не трожь гоблинов!', '', 28153),
(158320, 'ruRU', 'Отдай золото!', '', 28153),
(158319, 'ruRU', 'Галлавик лучше всех!', '', 28153),
(158318, 'ruRU', 'Никаких перекуров!', '', 28153),
(158317, 'ruRU', 'Никаких задержек!', '', 28153),
(158316, 'ruRU', 'Они склонятся перед Бездной.', 'Они склонятся перед Бездной.', 28153),
(158315, 'ruRU', 'Я вижу их сквозь завесу. За мной.', 'Я вижу их сквозь завесу. За мной.', 28153),
(158314, 'ruRU', 'Не бойтесь, крошки-гоблины, идите сюда...', 'Не бойтесь, крошки-гоблины, идите сюда...', 28153),
(158313, 'ruRU', '', 'Наши войска заняли позиции в Ар\'гороке. Собери союзников и захвати Стромгард!', 28153),
(158312, 'ruRU', '<Покинуть корабль и присоединиться к осаде Лордерона.>', '<Покинуть корабль и присоединиться к осаде Лордерона.>', 28153),
(158311, 'ruRU', 'Сюрпризы продолжатся до улучшения настроения.', '', 28153),
(158310, 'ruRU', 'Вы будете рассказывать об этом друзьям.', '', 28153),
(158309, 'ruRU', 'Приготовьте камеры. 3... 2... 1...', '', 28153),
(158308, 'ruRU', 'Запускаю протокол празднования.', '', 28153),
(158307, 'ruRU', 'Получен запрос на сюрприз. Выделяю безудержную энергию.', '', 28153),
(158306, 'ruRU', 'Необходимо превысить максимальный уровень веселья.', '', 28153),
(158305, 'ruRU', 'К скучающим гостям будут приняты меры.', '', 28153),
(158304, 'ruRU', 'Обнаружен недостаток веселья. Исправляю.', '', 28153),
(158303, 'ruRU', '', 'Скажу, когда война закончится.', 28153),
(158302, 'ruRU', 'Неважно.', 'Неважно.', 28153),
(158301, 'ruRU', 'Да.', 'Да.', 28153),
(158300, 'ruRU', '', 'Отсюда до лагеря Орды рукой подать, а ты спрашиваешь, зачем мне зелье невидимости?', 28153),
(158299, 'ruRU', 'Зачем тебе зелье невидимости?', 'Зачем тебе зелье невидимости?', 28153),
(158298, 'ruRU', 'А ну вон отсюда! А то меня раскроют!', '', 28153),
(158297, 'ruRU', 'Отправь меня на флагман.', 'Отправь меня на флагман.', 28153),
(158296, 'ruRU', 'Если тебе надо прокатиться к кораблям, только скажи!', '', 28153),
(158295, 'ruRU', 'Огромное ходячее дерево – это просто что-то с чем-то.', '', 28153),
(158294, 'ruRU', 'Ты зачем нервируешь Вог\'риша? Сейчас как дам!', '', 28153),
(158293, 'ruRU', 'Такого с Вог\'ришем еще не было!', '', 28153),
(158292, 'ruRU', 'А-а-а! Вог\'ришу стыдно!', '', 28153),
(158291, 'ruRU', 'Уж эльфы-то знают, как ухаживать за растениями.', '', 28153),
(158290, 'ruRU', 'Я тебе покажу, что на самом деле может Вог\'риш!', '', 28153),
(158289, 'ruRU', 'Готовьтесь к апокалипсису, слабаки!', '', 28153),
(158288, 'ruRU', 'Огр злиться!', '', 28153),
(158287, 'ruRU', 'Помощь никогда не бывает лишней.', '', 28153),
(158286, 'ruRU', '', 'Шандриса... ты должна... выжить...', 28153),
(158285, 'ruRU', '', 'Спаси... мой... народ...', 28153),
(158284, 'ruRU', 'Вог\'риш тебе ноги сожжет!', '', 28153),
(158283, 'ruRU', 'Магия Вог\'риша вышла из-под контроля!', '', 28153),
(158282, 'ruRU', '', 'Раздели со мной смерть!', 28153),
(158281, 'ruRU', 'Смотри на мою прекрасную силу!', '', 28153),
(158280, 'ruRU', 'Самое время.', '', 28153),
(158279, 'ruRU', '', 'Похоже, долго ждать вам не придется, Натанос.', 28153),
(158278, 'ruRU', '', 'Как сверкают! Скажу, что большую благословили жрецы моря, а закрученная – с пиратского сундука с сокровищами!', 28153),
(158277, 'ruRU', '', 'Меньше огоньков – меньше проблем для наших солдат. Хорошая работа.', 28153),
(158276, 'ruRU', '', 'Нужно очистить эту территорию, чтобы наши войска могли пройти. Не стоит недооценивать огоньки – они очень опасны в больших количествах.', 28153),
(158275, 'ruRU', '', 'Ты просто не поверишь, что водится в местных водоемах. Я тут недавно таких экзотов выловила... хочешь с ними подраться?', 28153),
(158274, 'ruRU', 'Лилиан твердит мне, что Орда для Отрекшихся – как семья.\n\nНу, раз теперь моя собственная семья меня не примет... Поддержка мне не помешает.\n\nТем более, Лилиан пообещала, что мои родные будут в безопасности. И если я могу добиться этого, помогая Орде...\n\nЗначит, так тому и быть.', '', 28153),
(158273, 'ruRU', '', 'Нужно уходить отсюда!', 28153),
(158272, 'ruRU', '', 'Покупайте морские ракушки! Самые красивые в Кул-Тирасе. А нет, в Азероте! Самые красивые в Азероте!', 28153),
(158271, 'ruRU', '', 'Я понемногу прихожу в чувство, $n.\n\nМожет, с помощью Лилиан я смогу принять свою новую жизнь.\n\nХотя должна сказать... чем дальше я смогу уехать из Кул-Тираса, тем лучше...', 28153),
(158270, 'ruRU', 'Спасибо за возможность доказать, насколько ценными союзниками могут быть рен\'дорай.\n\nМы сделаем все необходимое, чтобы Альянс добился победы.', '', 28153),
(158269, 'ruRU', '', 'Главнокомандующий Змеевержец произвел на меня впечатление.\n\nОн использует весьма разнообразную тактику и быстро приспосабливается к новым обстоятельствам.\n\nКампания Альянса в надежных руках. Как и ты, я очень рада, что мне выпала возможность сыграть в ней свою роль.', 28153),
(158268, 'ruRU', '', 'Сан\'лейн нужно устранить. Безрассудство Орды ставит под угрозу нас всех.', 28153),
(158267, 'ruRU', 'Скоро все будет. Огонь! Да, большой огонь!', '', 28153),
(158266, 'ruRU', 'Я дам знать, когда ты снова мне понадобишься. За Альянс.', '', 28153),
(158265, 'ruRU', 'Нужно немедленно рассказать об этом королю Андуину. Наше задание выполнено, но работа только начинается.', '', 28153),
(158264, 'ruRU', 'Неужели Орда и в самом деле использует эльфов-вампиров? Как низко они пали.', '', 28153),
(158263, 'ruRU', 'Дым уже есть, огонь подтянется!', '', 28153),
(158262, 'ruRU', 'То, о чем ты говоришь, похоже на сан\'лейн... кровавого принца.', '', 28153),
(158261, 'ruRU', '', 'Что? Гуззи мертв?', 28153),
(158260, 'ruRU', 'Где дым, там и огонь... надо только подождать!', '', 28153),
(158259, 'ruRU', 'Пора переходить к следующей части плана.', '', 28153),
(158258, 'ruRU', 'Тело Дерека Праудмура у нас. Но пока хватит оживлять култирасцев.', '', 28153),
(158257, 'ruRU', 'Будем надеяться, твои труды не были напрасны.', '', 28153),
(158256, 'ruRU', 'Война достигла Темных берегов, и мы должны сделать все, чтобы защитить наш народ. Направь все огоньки, которые сможешь найти, на передовую и устрани любые угрозы.', '', 28153),
(158255, 'ruRU', '', 'Ха! Я слышу крики предателя!', 28153),
(158254, 'ruRU', '', 'Отдых усталым, еду голодным.', 28153),
(158253, 'ruRU', '', 'Я на кул-тирасский флот в своей бухте не подписывалась.\n\nНадеюсь, у вас есть план. Потому что за решетку я не собираюсь.', 28153),
(158252, 'ruRU', 'Начинай ритуал.', 'Начинай ритуал.', 28153),
(158251, 'ruRU', 'Откуда ты родом?', 'Откуда ты родом?', 28153),
(158250, 'ruRU', 'Сколько ты уже здесь?', 'Сколько ты уже здесь?', 28153),
(158249, 'ruRU', 'Это мой единственный дом. \n\nКуда песок – туда и мы.', 'Это мой единственный дом. \n\nКуда песок – туда и мы.', 28153),
(158248, 'ruRU', 'В моем караване эти пески считают своим домом дольше, чем я живу на свете. \n\nКто-то из моего народа обитает за морем, только мне их видеть не доводилось.', 'В моем караване эти пески считают своим домом дольше, чем я живу на свете. \n\nКто-то из моего народа обитает за морем, только мне их видеть не доводилось.', 28153),
(158247, 'ruRU', 'Глупости. Вы прекрасно справились, магистр. Альянс гордится вами.', '', 28153),
(158246, 'ruRU', 'От имени всех эльфов Бездны прошу прощения за неудачу.', '', 28153),
(158245, 'ruRU', '', 'Залезай! Летим к Дозорному Холму.', 28153),
(158244, 'ruRU', 'Куа\'фон радостно стрекочет и сворачивается калачиком, чтобы вздремнуть.', '', 28153),
(158243, 'ruRU', 'Мирный житель стонет от боли.', 'Мирный житель стонет от боли.', 28153),
(158242, 'ruRU', 'Мок\'ра, $n! Застава в твоем распоряжении.', '', 28153),
(158241, 'ruRU', '', 'Хм...', 28153),
(158240, 'ruRU', 'Не волнуйся, мы щедро наградим тебя за беспокойство.', '', 28153),
(158239, 'ruRU', '', 'Натанос! Я разрешила войскам Орды разместиться в моей бухте. Но вот чего я точно не разрешала, так это притаскивать сюда флот Праудмуров!', 28153),
(158238, 'ruRU', 'Скипетр – это артефакт, дающий власть над морем. С его помощью мы получим превосходство над флотом Кул-Тираса.', '', 28153),
(158237, 'ruRU', '', 'Как вы собираетесь проникнуть в Боралус? Вряд ли нам можно так просто заявиться туда...', 28153),
(158236, 'ruRU', 'Я отправил Валентайна в Боралус с сообщением для леди Праудмур – она должна во что бы то ни стало узнать, что ее сын у нас.', '', 28153),
(158235, 'ruRU', 'Сохраняйте спокойствие, друзья мои. Уверяю вас, этот пират заплатит за свои преступления. Но мы должны дождаться, когда суд огласит приговор.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158234, 'ruRU', 'Наша задача – добыть скипетр глубин. Он находится в монастыре Штормов в Боралусе.', '', 28153),
(158233, 'ruRU', '', 'Идем, $n. Натанос введет тебя в курс дела.', 28153),
(158232, 'ruRU', 'Суд постановил твою вину в ростовщичестве. Твои займы с огромными процентами лишили сбережений многих в Большом Крюке. Из-за твоих преступлений многие оказались на улице.', '', 28153),
(158231, 'ruRU', 'Суд признал твою вину в следующих преступлениях: пиратство, воровство и убийство. Пиратство – одно из самых тяжких преступлений по законам Кул-Тираса – так пусть же свершится правосудие.', '', 28153),
(158230, 'ruRU', 'Вымогательство и поборы! Многие из присутствующих здесь семей пали жертвами твоих преступных планов. Ты обирал честный народ Кул-Тираса, но теперь платить придется тебе.', '', 28153),
(158229, 'ruRU', 'Идем. Я открою путь прямо к Аллерии и главнокомандующему.', '', 28153),
(158228, 'ruRU', 'Это, конечно, не абсолютная победа Альянса, на которую я рассчитывал, но опаздывать точно не стоит.', '', 28153),
(158227, 'ruRU', 'То есть мы все это время гонялись за двойником Галливикса? Гоблины – это просто мрак.', '', 28153),
(158226, 'ruRU', 'Пока, неудачники!', '', 28153),
(158225, 'ruRU', 'Эти экзоскелеты – удовольствие не из дешевых! Я пришлю тебе счет, $p, так и знай!', '', 28153),
(158224, 'ruRU', 'Вы попались на самую старую уловку в учебнике картеля Трюмных Вод: низкооплачиваемый высококвалифицированный наемный труд!', '', 28153),
(158223, 'ruRU', 'Ха! Видели бы вы сейчас свои рожи!', '', 28153),
(158222, 'ruRU', '', 'Мысль о том, что любая душа может избежать встречи с Бвонсамди, впечатляет. Надеюсь, что связи с его друзьями будет достаточно для того, чтобы мы могли связаться с ним и на Той Стороне.', 28153),
(158221, 'ruRU', '$n! В западной части лагеря есть подзорная труба. Поищи-ка Гузберта, ладно?', '', 28153),
(158220, 'ruRU', 'Хм... и правда, а где Гузберт? Он уже должен был вернуться.', '', 28153),
(158219, 'ruRU', '', 'Я первая, что ли? А где Гуззи?', 28153),
(158218, 'ruRU', 'С возвращением, мисс Стализвон.', '', 28153),
(158217, 'ruRU', '', 'Привет, босс! Слышал \"бум\"? Кажется, я запустила гоблина на низкую орбиту.', 28153),
(158216, 'ruRU', 'Гузберт и Келси должны вернуться с минуты на минуту.', '', 28153),
(158215, 'ruRU', 'А для меня кто-нибудь что-нибудь сотворил?', '', 28153),
(158214, 'ruRU', 'У тебя эго чуть ли не больше твоей туши. Подумай, сколько добра ты бы мог сотворить!', '', 28153),
(158213, 'ruRU', 'Ты сказочно богат, Галливикс, но это – все, что ты построил? Логово порока!', '', 28153),
(158212, 'ruRU', '', 'Полностью восстанови здоровье способностью \"Оживить\".', 28153),
(158211, 'ruRU', 'Полностью восстанови здоровье способностью \"Оживить\".', '', 28153),
(158210, 'ruRU', '', 'В бою получения урона не избежать, но тебе подвластна целебная сила туманов. Залечи раны способностью \"Оживить\".', 28153),
(158209, 'ruRU', 'В бою получения урона не избежать, но тебе подвластна целебная сила туманов. Залечи раны способностью \"Оживить\".', '', 28153),
(158208, 'ruRU', 'Альянс побежден!', '', 28153),
(158207, 'ruRU', '|A:Warfront-HordeWave3:25:23:0:0|aОрда отправила штурмовой отряд!', '|A:Warfront-HordeWave3:25:23:0:0|aОрда отправила штурмовой отряд!', 28153),
(158206, 'ruRU', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aДорога Храброгласа потеряна!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aДорога Храброгласа потеряна!', 28153),
(158205, 'ruRU', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aНовоземье потеряно!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aНовоземье потеряно!', 28153),
(158204, 'ruRU', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aКруг стихий потерян!!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aКруг стихий потерян!!', 28153),
(158203, 'ruRU', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aГнездо потеряно!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aГнездо потеряно!', 28153),
(158202, 'ruRU', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aСеверный перекресток потерян!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aСеверный перекресток потерян!', 28153),
(158201, 'ruRU', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|aРудник Гальсона потерян!', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|aРудник Гальсона потерян!', 28153),
(158200, 'ruRU', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|aВерхние вырубки потеряны!', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|aВерхние вырубки потеряны!', 28153),
(158199, 'ruRU', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aНа рудник Гальсона напали!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aНа рудник Гальсона напали!', 28153),
(158198, 'ruRU', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aНа Верхние вырубки напали!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aНа Верхние вырубки напали!', 28153),
(158197, 'ruRU', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|aНа вашего командира напали!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aНа вашего командира напали!', 28153),
(158196, 'ruRU', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aНа дорогу Храброгласа напали!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aНа дорогу Храброгласа напали!', 28153),
(158195, 'ruRU', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aНа Новоземье напали!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aНа Новоземье напали!', 28153),
(158194, 'ruRU', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aНа Круг стихий напали!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aНа Круг стихий напали!', 28153),
(158193, 'ruRU', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aНа Северный перекресток напали!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aНа Северный перекресток напали!', 28153),
(158192, 'ruRU', 'Нажать большую красную кнопку, когда ты мне скажешь. Понятно.', 'Нажать большую красную кнопку, когда ты мне скажешь. Понятно.', 28153),
(158191, 'ruRU', 'Покажи, куда я могу отправиться.', 'Покажи, куда я могу отправиться.', 28153),
(158190, 'ruRU', 'Куда направляешься?', '', 28153),
(158189, 'ruRU', 'Опять мою цену перебили! Почему некоторые так и хотят нажиться на несчастье других?', 'Опять мою цену перебили! Почему некоторые так и хотят нажиться на несчастье других?', 28153),
(158188, 'ruRU', 'У нас почти ничего не осталось на продажу.', 'У нас почти ничего не осталось на продажу.', 28153),
(158187, 'ruRU', 'Надеюсь, нам хватит на самое необходимое.', 'Надеюсь, нам хватит на самое необходимое.', 28153),
(158186, 'ruRU', 'Сколько у нас осталось золота?', 'Сколько у нас осталось золота?', 28153),
(158185, 'ruRU', 'Еды не хватает...', 'Еды не хватает...', 28153),
(158183, 'ruRU', 'Ты только с дороги не сходи. Кто знает, что там скрывается в тенях.', 'Ты только с дороги не сходи. Кто знает, что там скрывается в тенях.', 28153),
(158182, 'ruRU', 'Ой... Ой... Костюм сломался!', '', 28153),
(158181, 'ruRU', 'Вороны смотрят! Кто-то все время смеется! Они идут за мной!', '', 28153),
(158180, 'ruRU', '', 'Я... из-за тебя... все разлила...', 28153),
(158179, 'ruRU', '', 'Думаешь, сможешь меня обдурить? Раздавлю, как червя! <ик!>', 28153),
(158178, 'ruRU', '', 'Неплохо сработано. Увидимся на другом конце лагеря.', 28153),
(158177, 'ruRU', 'Смотри, Галливикс!', 'Смотри, Галливикс!', 28153),
(158176, 'ruRU', 'Альянс? Здесь, в Зандаларе?', '', 28153),
(158175, 'ruRU', 'Мы движемся за песком.', 'Мы движемся за песком.', 28153),
(158174, 'ruRU', 'В дюнах полно сокровищ, которые только и ждут того, чтобы их кто-нибудь отыскал.', 'В дюнах полно сокровищ, которые только и ждут того, чтобы их кто-нибудь отыскал.', 28153),
(158173, 'ruRU', 'Фургон – наш единственный дом.', 'Фургон – наш единственный дом.', 28153),
(158171, 'ruRU', '|TInterface\\Icons\\INV_Mace_2H_CapturedTitanConstruct_D_01:20|t%s начинает применять против вас способность |cFFFF0000|Hspell:271296|h[Кровавый отбойник]|h|r!', '', 28153),
(158170, 'ruRU', '', 'Эти несчастные души... Когда спасем Джайну, нужно будет найти способ вернуться за ними.', 28153),
(158169, 'ruRU', 'Одно ясно точно – все в Друстваре пошло наперекосяк.', 'Одно ясно точно – все в Друстваре пошло наперекосяк.', 28153),
(158168, 'ruRU', 'Я что-то слышал про оленей, которые охотились на людей.', 'Я что-то слышала про оленей, которые охотились на людей.', 28153),
(158167, 'ruRU', 'Что-то там про чудовищ и деревянных демонов? Да, слыхал такое.', 'Что-то там про чудовищ и деревянных демонов? Да, слыхала такое.', 28153),
(158166, 'ruRU', 'Слышь, что говорят? Откуда здесь столько беженцев?', 'Слышь, что говорят? Откуда здесь столько беженцев?', 28153),
(158165, 'ruRU', 'Иногда мне кажется, что я жужжу достаточно хорошо для того, чтобы пчелы меня поняли, но, наверное, этого не хватит, пока я не закончу костюм пчелы. К слову, мои пчелы – лучшие в этих краях. Хочешь с ними сразиться? Или кишка тонка?', '', 28153),
(158164, 'ruRU', '', 'Наша воля крепче, чем вражеские машины.', 28153),
(158163, 'ruRU', 'Калдорай не забудут твоих подвигов, $n. Возможно, именно благодаря тебе у нас еще есть шансы.', '', 28153),
(158162, 'ruRU', 'В тяжкие времена не нужно поддаваться унынию. Богиня дает нам силы, и их нужно использовать.', '', 28153),
(158161, 'ruRU', 'Одна битва не решает исход войны. Придет и наше время.', '', 28153),
(158160, 'ruRU', 'Король Андуин отправил к нам войска. Нужно продержаться до их прибытия.', '', 28153),
(158159, 'ruRU', 'Слава Элуне, наши корабли вернулись из Силитуса. Нам не хватало поддержки флота.', '', 28153),
(158158, 'ruRU', 'Стена огоньков еще держится, но Орда продолжает наступать.', '', 28153),
(158157, 'ruRU', 'Их боевой дух перебит другим духом. Психологическая атака в чистом виде.', '', 28153),
(158156, 'ruRU', 'Ты произнесла перед Натаносом сильную речь.', 'Ты произнесла перед Натаносом сильную речь.', 28153),
(158155, 'ruRU', 'Пираты Вольной Гавани наглеют день ото дня. Нужно посеять панику в их рядах. Поднимись в небо и, гхм, обстреляй их с ног до головы!', '', 28153),
(158154, 'ruRU', '', 'А говорили, что все моряки боятся пения сирен...', 28153),
(158153, 'ruRU', '', 'Сирены погубили очередной кул-тирасский грузовой корабль. Поищи полезные вещи среди обломков... но смотри, не поддайся песням этих тварей!', 28153),
(158152, 'ruRU', 'Вас ждет судьба хуже самой смерти...', '', 28153),
(158151, 'ruRU', 'Думаете, вы победили? Моя гибель повлечет за собой вашу!', '', 28153),
(158150, 'ruRU', 'Хорошо. Теперь им нечем будет от нас отбиваться.', '', 28153),
(158149, 'ruRU', 'Нужно остановить производство азеритового оружия в Кул-Тирасе. Устрой диверсию в литейной!', '', 28153),
(158148, 'ruRU', '', 'Когда в твоей преданности сомневается фанатик, ты, считай, не жилец.\n\nМеня обязали участвовать в этой войне. Тебя, возможно, тоже. Мы должны делать все, что нужно, и говорить то, что от нас требуется, чтобы ее пережить.\n\nНо помни: только одна война имеет значение. И это не она.', 28153),
(158147, 'ruRU', 'Вы разделите ее судьбу...', '', 28153),
(158146, 'ruRU', 'Вам ее... уже не спасти...', '', 28153),
(158145, 'ruRU', 'Вас всех ждут мучения...', '', 28153),
(158144, 'ruRU', 'Она все равно обречена...', '', 28153),
(158143, 'ruRU', 'Месть скоро свершится!', '', 28153),
(158142, 'ruRU', 'Праудмур наша!', '', 28153),
(158141, 'ruRU', 'Вы тоже сгинете!', '', 28153),
(158140, 'ruRU', 'Вы будете страдать вместе с ней!', '', 28153),
(158139, 'ruRU', '', 'Я здесь довольно давно работаю и находила интересные свидетельства того, на что способен этот самый азерит. Хочешь попытать счастья в бою с бродячими азеритоменталями, которых я откопала?', 28153),
(158138, 'ruRU', 'Глупцы! Вам не понять, с какими силами вы заигрываете!', '', 28153),
(158137, 'ruRU', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aНа Гнездо напали!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aНа Гнездо напали!', 28153),
(158136, 'ruRU', '', 'Я сама вызвалась. Если видишь возможность – хватайся за нее.\n\nУ меня всегда были планы на будущее. Пришла пора эти планы осуществить.', 28153),
(158135, 'ruRU', 'Я думал, ты служишь Некоронованным. У тебя сменились хозяева?', 'Я думал, ты служишь Некоронованным. У тебя сменились хозяева?', 28153),
(158134, 'ruRU', 'Я свободен! Благодарю... а теперь ваши души утолят мой бездонный голод!', '', 28153),
(158133, 'ruRU', 'Выбери, с какой области начать, и мы отправимся в путь немедленно.', '', 28153),
(158132, 'ruRU', '', 'Спасибо. Остальных перебьет стража. Нам следует пристальней следить за усадьбой.', 28153),
(158131, 'ruRU', '', 'Из усадьбы Уэйкрестов идет толпа поганищ! Останови их, пока они не добрались до Заставы Арома!', 28153),
(158129, 'ruRU', 'Мы должны победить, $n. Во имя Альянса!', '', 28153),
(158128, 'ruRU', 'Изучи позиции врага в землях троллей и подорви деятельность Орды везде, где сможешь.', '', 28153),
(158127, 'ruRU', 'Аванпосты в Зандаларе – первый шаг к победе. Теперь мы будем сражаться на территории Орды!', '', 28153),
(158126, 'ruRU', 'Но война заставляет постоянно менять планы. Настала пора сместить приоритеты.', '', 28153),
(158125, 'ruRU', 'Как хочется есть...', 'Как хочется есть...', 28153),
(158124, 'ruRU', 'Успех важнейшей операции в Кул-Тирасе – твоя заслуга. Сила Альянса – в его союзниках.', '', 28153),
(158123, 'ruRU', 'За Альянс!', '', 28153),
(158122, 'ruRU', 'Ты – живой пример для всех, кому посчастливилось сражаться вместе с тобой. Прими мою благодарность.', '', 28153),
(158121, 'ruRU', 'Твои услуги еще понадобятся Альянсу, $n. Мы не сможем победить Сильвану, пока не разорвем ее союз с империей Зандалари. Но это случится... уже скоро.', '', 28153),
(158120, 'ruRU', 'Хотелось бы сказать, что наша миссия выполнена. Однако предрассветный час самый темный, и нам еще предстоит его пережить.', '', 28153),
(158119, 'ruRU', 'Долгая и тяжелая кампания против безжалостного врага лишь подчеркнула твою исключительную смелость и благородство.', '', 28153),
(158118, 'ruRU', '', '...во славу Орды!', 28153),
(158117, 'ruRU', '', 'Ты – воплощение достоинств Орды, $n. Ты станешь той искрой, что спалит Боралус дотла...', 28153),
(158116, 'ruRU', '', 'Альянс собирает войска в Кул-Тирасе. Возвращение флота взбодрило их. Но скоро эти ничтожества поплатятся за то, что бросили нам вызов.', 28153),
(158115, 'ruRU', '', 'Победа становится ближе с каждым днем. Мы не остановимся, пока последний огонек надежды в сердце мальчишки-короля не погаснет.', 28153),
(158114, 'ruRU', '', 'Солдат в мире полно, и не многие из них созданы для войны. Однако ты, похоже, знаешь и любишь вкус битвы.', 28153),
(158113, 'ruRU', '', 'Отними у них надежду, и ты победишь, $n. За Орду!', 28153),
(158112, 'ruRU', '', 'Используй аванпосты, основанные тобой в Кул-Тирасе, чтобы подорвать силы короля-мальчишки.', 28153),
(158111, 'ruRU', '', 'Но победа – это не только триумф оружия. Мы должны растоптать наших врагов, чтобы они больше не поднялись.', 28153),
(158110, 'ruRU', '', 'Никто кроме тебя не склонил бы зандаларов на нашу сторону. Это я тоже знала.', 28153),
(158109, 'ruRU', '', 'Когда принцесса Таланджи обратилась к нам за помощью, я поняла, что ее империя может стать ценным союзником.', 28153),
(158108, 'ruRU', 'Сама земля мертва. Это жуть. Настоящая жуть.', '', 28153),
(158107, 'ruRU', '', 'Отдохни, |3-6($c), погрейся у огня.', 28153),
(158106, 'ruRU', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t %s начинает использовать заклинание |cFFFF0000|Hspell:273361|h[Омут тьмы]|h|r!', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t %s начинает использовать заклинание |cFFFF0000|Hspell:273361|h[Омут тьмы]|h|r!', 28153),
(158105, 'ruRU', 'Добро пожаловать на аванпост Порывистого Ветра, $n. Он в твоем распоряжении.', '', 28153),
(158104, 'ruRU', 'Надо было... брать... гарантию...', '', 28153),
(158103, 'ruRU', 'Добро пожаловать во дворец боли Галливикса, грязный воришка!', '', 28153),
(158102, 'ruRU', 'Попросить Фозрука напасть на Ар\'горок.', 'Попросить Фозрука напасть на Ар\'горок.', 28153),
(158101, 'ruRU', 'Заражение распространяется быстрее, чем я предполагал...', '', 28153),
(158100, 'ruRU', 'Это... неправильные споры! Откуда они взялись?', '', 28153),
(158099, 'ruRU', 'В следующей жизни они обретут покой. Мы сделали, что могли.', '', 28153),
(158098, 'ruRU', 'Местные духи страдают. Прервите их мучения.', '', 28153),
(158097, 'ruRU', '', 'Теперь они спокойны. Спасибо.', 28153),
(158096, 'ruRU', '', 'Духи взволнованы. Успокойте их.', 28153),
(158095, 'ruRU', '', 'По этим спорам мы найдем источник гнили и уничтожим его.', 28153),
(158094, 'ruRU', '', 'Гниль расползается. Чтобы понять, как ее вычистить, нужно собрать споры.', 28153),
(158093, 'ruRU', 'Братья и сестры! Орда продолжает наступать! Сбор у Петляющей реки!', '', 28153),
(158092, 'ruRU', 'Вас наполняет сила ветра!', 'Вас наполняет сила ветра!', 28153),
(158091, 'ruRU', 'Переправьте золото во дворец как можно быстрее и...', '', 28153),
(158090, 'ruRU', 'Никаких задержек! Никаких оправданий! Никаких повышений!', '', 28153),
(158089, 'ruRU', 'А ну с дороги! Тут Альянс!', '', 28153),
(158088, 'ruRU', 'Гоблин... не может меня убить.', '', 28153),
(158087, 'ruRU', 'Альянс рассчитывает на эльфов Бездны. Мы не подведем.', '', 28153),
(158086, 'ruRU', 'Галливи-и-и-и-и-икс!', 'Галливи-и-и-и-и-икс!', 28153),
(158085, 'ruRU', 'Альянс! Сматываемся!', 'Альянс! Сматываемся!', 28153),
(158084, 'ruRU', '', 'Похоже, Орда согнала фурболгов с насиженных мест.', 28153),
(158083, 'ruRU', '', 'Орда... Сколько же у них солдат...', 28153),
(158082, 'ruRU', 'Ох, золотишко мое! Откуда тут эльф?!', 'Ох, золотишко мое! Откуда тут эльф?!', 28153),
(158081, 'ruRU', '', 'Обычно фурболги не агрессивны. Но кто угодно разъярится, если выгнать его из дома.', 28153),
(158078, 'ruRU', '', 'Иду сквозь тень.', 28153),
(158077, 'ruRU', '', 'Будет сделано!', 28153),
(158076, 'ruRU', '', 'Тише! Нас не должны заметить!', 28153),
(158075, 'ruRU', '', 'Убей врага, пока не подняли тревогу!', 28153),
(158074, 'ruRU', '', 'Осторожнее! Не привлекай внимание...', 28153),
(158073, 'ruRU', 'Ланфа, я сейчас!', '', 28153),
(158072, 'ruRU', '', 'Я пойду за тобой, $n. Если надо кого-нибудь вывести из строя, скажи. Только тихо.', 28153),
(158071, 'ruRU', 'Харли сперва отвезет тебя, а потом вернется за мной. Мне нужно проведать приятеля!', '', 28153),
(158070, 'ruRU', 'Урок был хорош. Посмотрим, как они его усвоят.', '', 28153),
(158069, 'ruRU', 'Видимо, эти \"дворфы\" не понимают намеков. Пора показать им, как зандалары расправляются с захватчиками.', '', 28153),
(158068, 'ruRU', 'Если кто покажется на холме – убить на месте!', '', 28153),
(158067, 'ruRU', 'Как только мы покончим с флотом, Зандалар будет принадлежать нам!', '', 28153),
(158066, 'ruRU', 'Поднять столпы!', '', 28153),
(158065, 'ruRU', '<Немного подождать, пока Генн убеждает Кэтрин в по-настоящему крутом ролике.>', '<Немного подождать, пока Генн убеждает Кэтрин в по-настоящему крутом ролике.>', 28153),
(158064, 'ruRU', 'Народ Кул-Тираса теперь един, но в его главенствующем доме все еще нет мира, а Альянсу не хватает одного из наших сильнейших лидеров.\n\nНадеюсь, что этот раскол также удастся вылечить.', '', 28153),
(158063, 'ruRU', 'Встретимся у семейного мемориала в крепости Праудмур. Если повезет, мы убедим лорда-адмирала отменить приговор своей дочери.', '', 28153),
(158062, 'ruRU', 'Тебе удалось объединить всех жителей Кул-Тираса и заручиться их поддержкой. Быть может, теперь у тебя получится примирить мать с дочерью.', '', 28153),
(158061, 'ruRU', 'Хорошо. Без горючего наступление Орды замедлится.', '', 28153),
(158060, 'ruRU', 'Гоблины выкачивают из земли топливо для боевых машин! Останови это!', '', 28153),
(158059, 'ruRU', '', 'Пожар продолжается, а мы наступаем.', 28153),
(158058, 'ruRU', '', 'Пустим элементалей на топливо для разрушителей. Убивай их и всех калдорай, которые встанут на пути.', 28153),
(158057, 'ruRU', 'Чтобы не терять времени, мы можем пройти через Бездну. Следуй за мной.', '', 28153),
(158056, 'ruRU', 'Галливикс – тот еще скользкий тип. Он на открытом пространстве долго задерживаться не станет.', '', 28153),
(158055, 'ruRU', 'Надо было догадаться, что гоблин вроде Галливикса не сможет отказаться от мысли ограбить город, целиком состоящий из золота.', '', 28153),
(158054, 'ruRU', '', 'Нас заметили! Быстрее собирай азерит, и уходим отсюда!', 28153),
(158053, 'ruRU', '', 'Элуна милостивая... это азерит! Он повсюду!', 28153),
(158052, 'ruRU', 'Здесь повсюду азеритовые выбросы.', 'Здесь повсюду азеритовые выбросы.', 28153),
(158051, 'ruRU', '<Положить руку на азеритовый выброс.>', '<Положить руку на азеритовый выброс.>', 28153),
(158050, 'ruRU', '<Азеритовый выброс гудит от наполняющей его силы.>', '', 28153),
(158049, 'ruRU', '', 'Займись крошшером. Я выгоню захватчиков из рощи!', 28153),
(158048, 'ruRU', 'Роща Древних! О боги...', 'Роща Древних! О боги...', 28153),
(158047, 'ruRU', 'Будет сделано!', 'Будет сделано!', 28153),
(158046, 'ruRU', 'Поосторожнее с фурболгами. Их почему-то стало очень много.', 'Поосторожнее с фурболгами. Их почему-то стало очень много.', 28153),
(158045, 'ruRU', 'Я уже в пути!', 'Я уже в пути!', 28153),
(158044, 'ruRU', 'Фурболги ведут себя необычно агрессивно...', 'Фурболги ведут себя необычно агрессивно...', 28153),
(158043, 'ruRU', '|TInterface\\Icons\\INV_misc_boilingblood:20|t%s начинает применять против вас способность |cFFFF0000|Hspell:271224|h[Выброс плазмы]|h|r!', '', 28153),
(158042, 'ruRU', 'Не стоит недооценивать свои действия. Пока Орда оправляется от полученного удара, мы копим силы.', '', 28153),
(158041, 'ruRU', 'Враги пытаются закрепиться здесь. Разрушь их планы.', '', 28153),
(158040, 'ruRU', '', 'Детеныши выжили! Ты молодец!', 28153),
(158039, 'ruRU', '', 'Детеныши ящеров попали в беду. Помоги им, и Гонк улыбнется тебе.', 28153),
(158038, 'ruRU', 'Превосходно. Теперь нам не придется иметь с ними дело на суше.', '', 28153),
(158037, 'ruRU', '', 'Да здравствует Зандалар!', 28153),
(158036, 'ruRU', '', 'Если бы не помощь героев Орды, мы потеряли бы еще больше жизней.$bЧтобы империя процветала, нам пора отбросить предрассудки и наладить связи с миром!', 28153),
(158035, 'ruRU', '', 'Пусть этот клинок напоминает о том, что мы – зандалары! В самый темный час, пережив ужасные потери, мы способны измениться.$bМы способны выжить!', 28153),
(158034, 'ruRU', '', 'Того, кто загубил множество наших братьев и сестер.', 28153),
(158033, 'ruRU', '', 'Это кровь Г\'ууна. Того, кто погубил Шадру, Хи\'рика, Торгу и... Резана.', 28153),
(158032, 'ruRU', 'В море замечен боевой корабль Орды. Проследи, чтобы Орда не получила с него подкреплений.', '', 28153),
(158031, 'ruRU', '', 'Но это не моя заслуга.', 28153),
(158030, 'ruRU', 'Благодаря тебе агенты увидят очередной рассвет и даже напишут об этом рапорт.', '', 28153),
(158029, 'ruRU', 'Им нужна легенда, и ты станешь ею.', '', 28153),
(158028, 'ruRU', 'Именно ты спасла свой народ. Теперь троллям нужен правитель, которого они полюбят и которому доверятся.', '', 28153),
(158027, 'ruRU', 'Ты привела сюда героев Орды против воли отца. Ты раскрыла козни Г\'ууна, когда никто не хотел тебя слушать.', '', 28153),
(158026, 'ruRU', 'В эту область были отправлены несколько агентов ШРУ, и с тех пор от них нет вестей. Разберись, почему они не выходят на связь.', '', 28153),
(158025, 'ruRU', 'Покажи им, владыка Зандалара. Покажи клинок тем, кто должен его увидеть. Обрадуй их.', '', 28153),
(158024, 'ruRU', '', 'Вол\'джин, ты слышишь нас? Покажись, бесплотный дух!', 28153),
(158023, 'ruRU', 'За каждую пядь земли Орда будет платить кровью. Даже небольшие победы помогают склонить чашу весов всей войны.', '', 28153),
(158022, 'ruRU', 'Смерть... Потери. Смятение. Никто не укажет путь... Никто не свершит правосудие. Г\'уун украл надежду.', '', 28153),
(158021, 'ruRU', 'Ордынцы считают, что они здесь как дома. Поможем им избавиться от этого заблуждения.', '', 28153),
(158020, 'ruRU', '', 'Тс-с.', 28153),
(158019, 'ruRU', 'Я слышу его!', '', 28153),
(158018, 'ruRU', 'Смерть...', '', 28153),
(158017, 'ruRU', '', 'Вол\'джин, сын Сен\'джина, услышь голос своих друзей и родных. Они хотят узнать, где ты.', 28153),
(158016, 'ruRU', 'Разместить азерит', 'Разместить азерит', 28153),
(158015, 'ruRU', 'Нужно защитить рощу Древних!', 'Нужно защитить рощу Древних!', 28153),
(158014, 'ruRU', 'Я на страже.', 'Я на страже.', 28153),
(158013, 'ruRU', '<Помочь ему подняться.>', '<Помочь ему подняться.>', 28153),
(158012, 'ruRU', 'Буду с тобой откровенен – это еще не дно.\n\nНо разница не особо большая.', '', 28153),
(158011, 'ruRU', '', 'Древни зовут нас! Собери друидов-хищников в лесу и найди меня в роще Древних!', 28153),
(158009, 'ruRU', '', 'Наконец-то передышка. Часовые, сомкнуть ряды!', 28153),
(158008, 'ruRU', '', 'Никого такого не видела. Боюсь, твоего друга утащили сирены.', 28153),
(158007, 'ruRU', '<Спросить, не видела ли она Флинна.>', '<Спросить, не видела ли она Флинна.>', 28153),
(158006, 'ruRU', 'Потеряны? Что значит \"потеряны\"? Я требую возмещения!', 'Потеряны? Что значит \"потеряны\"? Я требую возмещения!', 28153),
(158005, 'ruRU', '', 'Ты не единственный, кто запрашивал у ШРУ досье.', 28153),
(158004, 'ruRU', 'Откуда почетный эльфийский генерал что-то обо мне знает?', '', 28153),
(158003, 'ruRU', '', 'Ты и сам герой, Кишан. Ты участвовал в первых трех войнах и многократно проявил себя в Красногорье.', 28153),
(158002, 'ruRU', 'Как по мне, то я вообще не достоин служить рядом с вами. Меньшее, что я могу сделать, – молчать и всячески выражать свое почтение.', '', 28153),
(158001, 'ruRU', 'Мэм, я читал ваше досье в ШРУ. Вы живете уже больше десяти тысяч лет и участвовали в большем количестве войн, чем я могу себе представить.', '', 28153),
(158000, 'ruRU', '', 'Кишан, ты можешь оставить формальности.', 28153),
(157999, 'ruRU', 'Она говорила, что должна убивать Альянс на поле боя, а не заниматься всякой чепухой. После этого я понял, что пора улепетывать, а не договариваться об историях.', '', 28153),
(157998, 'ruRU', 'Эта Арейель, которую вы ищете, сидит в Некрополе с кучей ордынцев! Похоже, ей не дает покоя какое-то послание, которое ей доставили.', '', 28153),
(157997, 'ruRU', 'Будет здорово! Я дам тебе то, что ты хочешь, а ты за это расскажешь мне о своем военном опыте.', '', 28153),
(157996, 'ruRU', '', 'Я живу уже 10 000 лет и сражалась во всех войнах. Я своими глазами видела изначальный Источник Вечности.', 28153),
(157995, 'ruRU', 'Я участвовал в первых трех войнах, был в плену у орков-варваров и помог убить черного дракона.', '', 28153),
(157994, 'ruRU', 'Хорошая история! Я ожидал, что Торга расскажет мне что-нибудь интересное, но он теперь мертв. Тебе есть, что мне рассказать?', '', 28153),
(157993, 'ruRU', 'Мы тебя только что спасли. Чего тебе еще нужно?', '', 28153),
(157992, 'ruRU', 'Я тебе все расскажу об Орде. Только я хочу кое-что взамен.', '', 28153),
(157991, 'ruRU', 'Спасибо, мэм.', '', 28153),
(157990, 'ruRU', '', '$n, Кишан! Спасибо вам за помощь. Мне нужно продолжить охоту на Древена. Да хранит вас Элуна.', 28153),
(157989, 'ruRU', 'Я прикрою вас с фланга!', '', 28153),
(157988, 'ruRU', '', '$n, Кишан, идемте. Надо возвращаться в форт Победы... и запросить для моих друзей достойные похороны.', 28153),
(157987, 'ruRU', '', 'Эльфы, люди... все мы равны, Кишан. Жизнь каждого из нас имеет одинаковое значение.', 28153),
(157986, 'ruRU', 'Я... быстро встану на ноги... но... лучше бы вместо меня был кто-то другой. Твои друзья должны были выжить.', '', 28153),
(157985, 'ruRU', '', 'Кишан! Слава Элуне, хоть кто-то выжил в этой бойне.', 28153),
(157984, 'ruRU', '<кашляет> Мэм... я еще... не совсем умер. Без своих прислужничков... не так-то он и силен...', '', 28153),
(157983, 'ruRU', '', 'Фалия... Лириас... Эолин... Кишан... Клянусь тебе, $n, Древен за все заплатит!', 28153),
(157982, 'ruRU', 'А-а!', '', 28153),
(157981, 'ruRU', 'Я никогда не сдамся, Шандриса Оперенная Луна. Смотри, какие у тебя хрупкие союзники!', '', 28153),
(157980, 'ruRU', 'Пойдем отсюда. Их души сами найдут дорогу к Бвонсамди.', '', 28153),
(157979, 'ruRU', 'Тролли крови вернутся, это точно. Но теперь они знают, что мы достанем их и дома, и просто так нападать не станут.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157978, 'ruRU', '', 'Шандриса... дальше иди... без меня...', 28153),
(157977, 'ruRU', 'Я проберусь вперед и поищу безопасное место для встречи. Буду ждать тебя у деревни.', '', 28153),
(157976, 'ruRU', 'Отдайся смерти вместе со мной, ночной эльф!', '', 28153),
(157975, 'ruRU', 'Пора показать тебе, на что способен этот жалкий человек!', '', 28153),
(157974, 'ruRU', '', 'Опустите щит! Нам нужно использовать эту возможность! Стромгард будет нашим!', 28153),
(157973, 'ruRU', '', 'Огонь из всех пушек!', 28153),
(157972, 'ruRU', '', 'Да?', 28153),
(157971, 'ruRU', 'Наверняка нам позволят вернуться за своими ценностями. Когда дым рассеется, конечно.', 'Наверняка нам позволят вернуться за своими ценностями. Когда дым рассеется, конечно.', 28153),
(157970, 'ruRU', 'Все наши сбережения остались в Ветви Вечности!', 'Все наши сбережения остались в Ветви Вечности!', 28153),
(157969, 'ruRU', 'Ты будешь жалеть, что не сгорела в Дарнасе!', '', 28153),
(157968, 'ruRU', 'Шандриса Оперенная Луна. Что это, засада? Как смело.', '', 28153),
(157967, 'ruRU', 'Пожалуй, стоит преподать вам урок. На примере этого жалкого человечишки.', '', 28153),
(157966, 'ruRU', '', 'Сегодня твоим бесчинствам придет конец, Древен.', 28153),
(157965, 'ruRU', 'Сколько мне еще вас убивать, чтобы вы наконец-то поняли, что не стоит нам мешать?', '', 28153),
(157964, 'ruRU', 'Альянс. Я так и знал, что наша предыдущая встреча вас ничему не научила.', '', 28153),
(157963, 'ruRU', 'Кажется, пришло время взять плохих боевых пауков и заменить их хорошими боевыми пауками.', '', 28153),
(157962, 'ruRU', 'Один парниша, три паука, двадцать шесть ног в сумме. У тебя не было ни единого шанса.', '', 28153),
(157961, 'ruRU', 'Когда один падет, его место займет другой!', '', 28153),
(157960, 'ruRU', 'Тихо, кроха. Ты поможешь нам?', 'Тихо, кроха. Ты поможешь нам?', 28153),
(157959, 'ruRU', '<Хлопп смотрит на вас с опаской.>\n\nХлопп?', '', 28153),
(157958, 'ruRU', 'Да, да! Мы плохие парни! Вперед и с песнями!', '', 28153),
(157957, 'ruRU', 'Я готов убить Древена и его союзников.', 'Я готова убить Древена и его союзников.', 28153),
(157956, 'ruRU', 'Привет! Я Дилберт Макклинт, эколог. Всегда приятно сразиться с другим арахнофилом.', '', 28153),
(157955, 'ruRU', 'Кажется, мы стали наживкой для кучки голодных кровососущих эльфов. Надеюсь, ты понимаешь, что последует дальше!', '', 28153),
(157954, 'ruRU', '', 'Я дам знать остальным. Кишан ждет тебя в туннеле.', 28153),
(157953, 'ruRU', '', 'Спасибо! Дальше мы справимся сами.', 28153),
(157952, 'ruRU', '', 'Враги сломили нашу оборону! Они строят укрепления! Оседлай дракончика и отбрось их!', 28153),
(157951, 'ruRU', 'Когда ты пойдешь через ближайшую чащу, то наверняка подумаешь, что паукам не нравится ветер и открытое пространство, но на самом деле они в этом отношении такие же, как мы с тобой. Ну, и паука сразу же выдает паутина.', '', 28153),
(157950, 'ruRU', '', 'Встретимся возле руин Зо\'бала. Будь осторожнее.', 28153),
(157949, 'ruRU', 'М-м, охотничий азарт. Чувствуешь его? Я – да.', '', 28153),
(157948, 'ruRU', '', 'Отдых усталым, еду – голодным.', 28153),
(157947, 'ruRU', 'Обязательно, принцесса.', '', 28153),
(157946, 'ruRU', '', 'Понятно. Мне нужно вернуться в Зулдазар. Держи меня в курсе того, как проходит операция Орды в Назмире. И будь осторожен, Рокхан.', 28153),
(157945, 'ruRU', 'Сильвана хочет дать им шанс. У них ничего не осталось. Если они смогут с нами сотрудничать, мы примем их в Орде, как родных. Если не смогут – им конец.', '', 28153),
(157944, 'ruRU', 'Это чудовище нападает на корабли, которые мы отправляем на Кул-Тирас. Расправься с ним.', '', 28153),
(157943, 'ruRU', '', 'Не доверяю я этому Древену, Рокхан. Вот уж кого, а сан\'лейн в этот конфликт впутывать не слишком мудро.', 28153),
(157942, 'ruRU', 'Я сделаю то, о чем ты просишь. По крайней мере сейчас. Мы расчистим туннель и дадим тебе знать, когда войскам можно будет выдвигаться.', '', 28153),
(157941, 'ruRU', 'Потому что вы договорились с Сильваной соблюдать принятую в Орде военную иерархию, а я старше тебя по званию, братишка.', '', 28153),
(157940, 'ruRU', 'Ты хочешь использовать наши способности... чтобы расчистить завалы? А с чего мне выполнять твои приказы, тролль?', '', 28153),
(157939, 'ruRU', 'Назмир и Вол\'дун соединяет обрушенный туннель. Расчисти его вместе со своими соратниками, и тогда мы сможем внезапно напасть на основные силы Альянса.', '', 28153),
(157938, 'ruRU', '', 'К югу отсюда находится обрушенный туннель, который соединяет Назмир и Вол\'дун. Расчистите его, и Орда с легкостью нанесет удар по основной базе Альянса в Вол\'дуне.', 28153),
(157937, 'ruRU', 'Сильване это не понравится. Нам нужно поторопиться и остановить Альянс, принц Древен.', '', 28153),
(157936, 'ruRU', 'Такая вот у меня отличительная черта. Альянс разбил силы Орды в Некрополе, тогда же погибла и Арейель.', '', 28153),
(157935, 'ruRU', '', 'Принцесса Таланджи, принц Древен. И откуда вам это известно?', 28153),
(157934, 'ruRU', 'Капитан Арейель не придет, потому что она мертва, Таланджи.', '', 28153),
(157933, 'ruRU', '', 'И все-таки ее здесь нет. Неужели она так занята?', 28153),
(157932, 'ruRU', 'Арейель сражается и с Альянсом, и с троллями крови. Она помогла нам создать базу в Некрополе.', '', 28153),
(157931, 'ruRU', '', 'Прошу прощения за задержку, Рокхан. Доложи обстановку. Капитан Арейель оказалась вам полезной?', 28153),
(157930, 'ruRU', 'Принцесса! Спасибо, что прилетели к нам из самого Зулдазара. Мы усердно работаем над тем, чтобы сдерживать троллей крови и войска Альянса.', '', 28153),
(157929, 'ruRU', '', 'Добро пожаловать, $n. Аванпост в твоем распоряжении.', 28153),
(157927, 'ruRU', 'К твоим услугам.', '', 28153),
(157926, 'ruRU', '(Выпить зелье невидимости.)', '(Выпить зелье невидимости.)', 28153),
(157925, 'ruRU', '', 'Не высовывайся. Туда должен пойти кто-то один. Я останусь здесь и прослежу, чтобы никто не понял, что мы собираемся сделать.\n\nУ меня с собой есть особое зелье – оно поможет тебе действовать скрытно. Тот, кто его выпьет, становится совершенно невидимым... на короткое время.\n\nПей и отправляйся в руины. Узнай, что замышляет Орда, а потом уходи оттуда.', 28153),
(157924, 'ruRU', 'Боюсь, маленькие победы лишь оттягивают неизбежное.', '', 28153),
(157923, 'ruRU', 'Мы сдерживаем Орду, но сейчас они переключили внимание на извержение азерита, произошедшее на берегу. Нужно им помешать.', '', 28153),
(157920, 'ruRU', 'Подойди поближе, зайка. Вунджа слепая, но не глухая! Кхе-хе-хе! Хочешь от Вунджи зелье?', 'Подойди поближе, зайка. Вунджа слепая, но не глухая! Кхе-хе-хе! Хочешь от Вунджи зелье?', 28153),
(157919, 'ruRU', '', 'Большому Гэ это не понравится...', 28153),
(157918, 'ruRU', '', 'Ух я тебе наподдам, прям по хлебалу!', 28153),
(157917, 'ruRU', '$p, мои бойцы готовы. За Альянс.', '', 28153),
(157916, 'ruRU', '', '$p, встретимся у лагеря Реликвария.', 28153),
(157915, 'ruRU', 'Фитиликс, пойдем.', '', 28153),
(157914, 'ruRU', 'Я сражался во всех трех войнах. И думал, все самое плохое в Азероте уже повидал.\n\nНо я ошибался.', '', 28153),
(157913, 'ruRU', '', 'У меня есть для тебя подарок.', 28153),
(157912, 'ruRU', '', 'Остаешься только ты. Отправляйся к капитану Летней Луне, укрепите границу!', 28153),
(157911, 'ruRU', '', 'Лучницы на гиппогрифах, за мной. Мы перегруппируемся в Лор\'данеле, будем следить за ситуацией и оперативно реагировать.', 28153),
(157910, 'ruRU', '', 'Стражи, создайте линию обороны у Петляющей реки! Призовите союзников из рощи Древних!', 28153),
(157909, 'ruRU', '', 'Охотницы, укрепите южную границу Темных берегов! Возьмите с собой метатели глеф!', 28153),
(157908, 'ruRU', '', 'Нужно действовать немедленно! Часовые, вперед!', 28153),
(157907, 'ruRU', 'Капитан, Орда подошла к Петляющей реке! Мы не сможем сдерживать их слишком долго!', 'Капитан, Орда подошла к Петляющей реке! Мы не сможем сдерживать их слишком долго!', 28153),
(157906, 'ruRU', 'Альпака! Ура!', '', 28153),
(157905, 'ruRU', 'Точно?', 'Точно?', 28153),
(157904, 'ruRU', '', 'Слушаюсь!', 28153),
(157903, 'ruRU', '<Просто атаковать.>', '<Просто атаковать.>', 28153),
(157902, 'ruRU', 'А как насчет золотишка?', 'А как насчет золотишка?', 28153),
(157900, 'ruRU', 'Сильвана хочет лично сразиться со мной, и я приму ее вызов. Мы послали за флотом... скоро он прибудет, если дозволит Элуна.', '', 28153),
(157899, 'ruRU', 'Ты же, $n, отправишься оборонять Дарнас.', '', 28153),
(157898, 'ruRU', 'Деларин, скорее собери солдат со всех наших застав и приведи их сюда.', '', 28153),
(157897, 'ruRU', '', 'А ты, шан\'до?', 28153),
(157896, 'ruRU', 'Королева банши идет к Древу Жизни.', '', 28153),
(157895, 'ruRU', '', 'Малфурион! Орда стянула войска к заставе Зорам\'гар.', 28153),
(157894, 'ruRU', 'Проходи, $n. Огоньки не причинят тебе вреда.', '', 28153),
(157893, 'ruRU', '', 'Даже перед смертью ты не видишь в людях их истинного потенциала.', 28153),
(157892, 'ruRU', '', 'Ты по-прежнему цепляешься за свои устаревшие взгляды. Надо было уже давно тебя прикончить.', 28153),
(157891, 'ruRU', '', 'Я должна жить вечно, я не собираюсь здесь умирать!', 28153),
(157890, 'ruRU', '', 'Как жаль, Шандриса, что ты на стороне этого жалкого человечишки! Они умирают, так ничего и не совершив в своей жизни.', 28153),
(157889, 'ruRU', '', 'Шандриса! Сколько лет прошло... две тысячи? Три? Кто бы мог подумать, что мы встретимся вновь при таких обстоятельствах... и что ты будешь помогать человеку!', 28153),
(157888, 'ruRU', '', 'Тьма... Сильвана... ты ее видела... не от нее ли хотела нас уберечь?', 28153),
(157887, 'ruRU', '', 'А я-то думала, это будет обычная разведывательная операция.', 28153),
(157886, 'ruRU', '', 'Все кончено. Найди документы и возвращайся в дозор Редфилда.', 28153),
(157885, 'ruRU', '|cFF0000FF(Задание)|r Отправиться в Ксибалу в Зулдазаре.', '|cFF0000FF(Задание)|r Отправиться в Ксибалу в Зулдазаре.', 28153),
(157884, 'ruRU', 'Спасибо! Тварь уничтожена, и воины смогут свободно двигаться дальше.', '', 28153),
(157883, 'ruRU', 'Ром – только для настоящих стальноволнцев. Руки убери!', 'Ром – только для настоящих стальноволнцев. Руки убери!', 28153),
(157882, 'ruRU', 'Через болото и так нелегко прокладывать путь, а тут еще и волшебные твари мешают. Убей это чудовище.', '', 28153),
(157881, 'ruRU', '', 'Хорошо! Больше это существо нам не помеха.', 28153),
(157880, 'ruRU', '', 'Эту тварь питает злое моджо! Верни души Бвонсамди.', 28153),
(157879, 'ruRU', '', 'Еще одна победа.', 28153),
(157878, 'ruRU', 'Кто путается под ногами, того я затаптываю! Иди-ка, прогуляйся.', '', 28153),
(157877, 'ruRU', '', 'Мои разведчики сообщают, что на Темных берегах произошло внезапное извержение азерита. Помоги нашим союзникам-гоблинам со сбором.', 28153),
(157876, 'ruRU', 'Не подходи слишком близко к Бвонсамди!', 'Не подходи слишком близко к Бвонсамди!', 28153),
(157875, 'ruRU', 'А что уши?$B$BСейчас так модно – ясно же.', '', 28153),
(157874, 'ruRU', 'Ах ты хозен-ворюга! Ну, если у меня хоть капля рома пропала...', 'Ах ты хозен-ворюга! Ну, если у меня хоть капля рома пропала...', 28153),
(157873, 'ruRU', 'Бесполезные трюмные крысы, хватит набубениваться ромом!', 'Бесполезные трюмные крысы, хватит набубениваться ромом!', 28153),
(157872, 'ruRU', 'Наша задача – разрушить союз Орды и империи Зандалари. Для этого нужно основать аванпосты на вражеской территории.', '', 28153),
(157871, 'ruRU', '$n! Пора показать Орде, на что способен 7-й легион.', '', 28153),
(157870, 'ruRU', '', 'Солдаты... Назад! Назад!!!', 28153),
(157869, 'ruRU', 'Так, все работает? Да? Супер.', '', 28153),
(157868, 'ruRU', 'Ха, это была просто бойня! Орда не скоро оправится от такого разгрома. Прекрасно.', '', 28153),
(157867, 'ruRU', 'Мы смогли захватить одно из осадных орудий Орды. Пора побить врага его же оружием!', '', 28153),
(157866, 'ruRU', 'Не может быть! Шефу это не понравится. Старый Бвонсамди не упускал души с тех пор, как... Ай, какой позор.', '', 28153),
(157865, 'ruRU', 'Эй, Вол\'джин! Вылезай из горшка! А где... нет! Где его дух?! Куда дели Вол\'джина?!', '', 28153),
(157864, 'ruRU', 'Нечего тебе тут делать. Гуляй.', '', 28153),
(157863, 'ruRU', 'К счастью, обычные рабочие на нас внимания не обращают... Только громилы пристают.\n\nПонятно, что от тебя требуется?', '', 28153),
(157862, 'ruRU', 'Сегодня мы многого достигли. Перегруппируемся снаружи.', 'Сегодня мы многого достигли. Перегруппируемся снаружи.', 28153),
(157861, 'ruRU', '', 'Джакра\'зета надо остановить.', 28153),
(157860, 'ruRU', 'Что делает король ради спасения нашей родины?', 'Что делает король ради спасения нашей родины?', 28153),
(157859, 'ruRU', 'У Штормграда недостаточно ресурсов. На всех нас не хватит.', 'У Штормграда недостаточно ресурсов. На всех нас не хватит.', 28153),
(157858, 'ruRU', 'Нет-нет-нет, малютка. Здесь его оставлять нельзя.', '', 28153),
(157857, 'ruRU', 'Прекрасно! Очередная угроза миновала.', '', 28153),
(157856, 'ruRU', 'Вместо того, чтобы драться из-за руин, Альянс должен вернуть нашу родину!', 'Вместо того, чтобы драться из-за руин, Альянс должен вернуть нашу родину!', 28153),
(157855, 'ruRU', 'Мы лишились дома уже дважды.', 'Мы лишились дома уже дважды.', 28153),
(157854, 'ruRU', 'Куда нам теперь идти?', 'Куда нам теперь идти?', 28153),
(157853, 'ruRU', 'Славно. С ее смертью у новых поколений появится шанс.', '', 28153),
(157852, 'ruRU', 'Ставки слишком высоки, генерал. Мы должны принять эту информацию к сведению и сделать выводы.', '', 28153),
(157851, 'ruRU', '', 'Этот монстр не должен уйти, Змеевержец.', 28153),
(157850, 'ruRU', 'Тупица из племени Черного Копья! Уходи, это место для правильных троллей!', '', 28153),
(157849, 'ruRU', 'Ордынской погани здесь не место. Мы, племя Песчаной Бури, бросаем вам вызов!', 'Ордынской погани здесь не место. Мы, племя Песчаной Бури, бросаем вам вызов!', 28153),
(157848, 'ruRU', '', 'Спасибо, Аллерия. Я ценю твою помощь.', 28153),
(157847, 'ruRU', 'Мудрый план. Я согласен.', '', 28153),
(157846, 'ruRU', '', 'Мы выследим его и принесем его голову. А Шандриса пусть бросит все силы на поиски кровавого принца.', 28153),
(157845, 'ruRU', '', 'Мои эльфы Бездны могут возглавить операцию по устранению Галливикса.', 28153),
(157844, 'ruRU', '', 'Аллерия открывает врата бездны у себя за спиной.', 28153),
(157843, 'ruRU', '', 'Мы не можем себе позволить упустить ни одну из этих целей... и мы их не упустим.', 28153),
(157842, 'ruRU', '', 'Простите, что вмешиваюсь, но мне кажется, вы оба правы.', 28153),
(157841, 'ruRU', '', 'Я видела, на что способен Древен, Змеевержец. Что, если он не один такой?', 28153),
(157840, 'ruRU', 'Если мыслить тактически, то он – слабое звено. Это редкая возможность. Мы должны нанести удар немедленно.', '', 28153),
(157839, 'ruRU', 'Галливикс оплачивает военные расходы Орды, и он знает об азерите больше, чем остальные лидеры.', '', 28153),
(157838, 'ruRU', '', 'Мы можем прикончить этого жирного гоблина и потом! А если Древен сбежит, другой такой возможности может не представиться.', 28153),
(157837, 'ruRU', 'Скоро мы разберемся с кровавым принцем Древеном, генерал. Но у нас есть редкая возможность обезглавить армию Орды. Все остальное подождет.', '', 28153),
(157836, 'ruRU', 'Крылатая тварь скармливает моих солдат своим детенышам! Накорми ее сталью, и досыта!', '', 28153),
(157835, 'ruRU', 'Ты не приведешь ордынскую мразь в священное место!', '', 28153),
(157834, 'ruRU', '', 'Наши союзники ждут твоего приказа.', 28153),
(157833, 'ruRU', 'Великая Па\'ку решила, что Джи\'арак задержалась на этом свете. Собери войско и убей ее.', '', 28153),
(157832, 'ruRU', 'С прибытием, $n. Нас ждут дела.', '', 28153),
(157831, 'ruRU', 'Это... кровь? В самом деле? Ты говоришь, что эту штуковину окружает щит из настоящей крови?\n\nХорошо... Теперь я точно видел все.', '', 28153),
(157830, 'ruRU', '', 'Круг теперь наш! Все по местам!', 28153),
(157829, 'ruRU', 'Кончится одна – начнется другая.', '', 28153),
(157828, 'ruRU', 'Свет вечен и пребудет после нас. Но когда война кончится, что останется у тебя?', '', 28153),
(157827, 'ruRU', 'Вера в Свет? Или в Туралиона?', '', 28153),
(157826, 'ruRU', 'Наоборот! Когда Туралион вернулся, я убедился, что Свет не покинул его, укрепил, дал силы. И это только еще раз показало мне что моя вера не была ошибочной.', '', 28153),
(157825, 'ruRU', 'Ну, а когда выяснилось, что он на самом деле жив, ты не пожалел о своем решении?', '', 28153),
(157824, 'ruRU', 'Когда он отправился в Запределье и пропал без вести, Свет открыл мне глаза. Я понял, что можно быть и солдатом, и паладином. В память о Туралионе я и принес свою клятву.', '', 28153),
(157823, 'ruRU', 'Но один из первых паладинов подал мне блестящий пример. Вера направляла и укрепляла Туралиона. Благодаря ей он стал великолепным лидером.', '', 28153),
(157822, 'ruRU', 'Друкан прилег отдохнуть.', '', 28153),
(157821, 'ruRU', 'В дни основания ордена я был рыцарем и не понимал, как служение Свету можно сочетать с владением оружием. Так что я занимался оружием.', '', 28153),
(157820, 'ruRU', 'Скажи, Халфорд, как вышло, что паладин командует отрядом элитных солдат? Вы разве занимаетесь не вещами вроде освящения храмов?', '', 28153),
(157819, 'ruRU', 'Да, конечно.', '', 28153),
(157818, 'ruRU', 'Спасибо за добрые слова. Но если выбирать между честью и хорошо сделанной работой, я выберу последнее. Ради Альянса, конечно.', '', 28153),
(157817, 'ruRU', 'Если честно, раньше я сомневался, нужны ли Альянсу шпионы и наемные убийцы. Но все эти годы ты верно служил королю, и мои сомнения рассеялись.', '', 28153),
(157816, 'ruRU', 'ШРУ действует скрытно. Я предпочитаю не выходить из тени... на всеобщее обозрение.', '', 28153),
(157815, 'ruRU', 'Зачем считать? Я иду, куда приказывает Альянс... и куда ведет Свет. Ты ведь и сам знаешь, какова судьба солдата.', '', 28153),
(157814, 'ruRU', 'Сколько войн с Ордой ты пережил на своем веку, Змеевержец?', '', 28153),
(157813, 'ruRU', '$n, ты с этой штукой поаккуратнее.', '', 28153),
(157812, 'ruRU', 'Я подумал, вдруг это важно.', '', 28153),
(157811, 'ruRU', 'Мастерская открыта! Если тебе что-то понадобится, то деталей и рук у нас хватит!', '', 28153),
(157810, 'ruRU', 'Любой урон по Клыку Войны воздастся сторицей!', '', 28153),
(157809, 'ruRU', 'Я больше не боюсь смерти. Теперь она боится меня...', '', 28153),
(157808, 'ruRU', 'Вождь этого так не оставит.', '', 28153),
(157807, 'ruRU', 'Смерть для тебя – это роскошь.', '', 28153),
(157806, 'ruRU', 'Я сожру твой труп!', '', 28153),
(157805, 'ruRU', 'Я разрублю тебя напополам!', '', 28153),
(157804, 'ruRU', '', 'Надеюсь, на этот раз они усвоили урок...', 28153),
(157803, 'ruRU', '', 'Пираты снова напали на Дозорный Холм! Помоги морпехам задать им трепку!', 28153),
(157802, 'ruRU', 'Спасибо! Мне надо вернуться к семье.', 'Спасибо! Мне надо вернуться к семье.', 28153),
(157801, 'ruRU', 'Как они на тебя смотрели, умора! Теперь им неделю придется отмываться!', '', 28153),
(157800, 'ruRU', 'Орда – настоящие варвары!', 'Орда – настоящие варвары!', 28153),
(157799, 'ruRU', 'Столь коварную порчу надо искоренять... пока она не заразила Орду.', '', 28153),
(157798, 'ruRU', 'Нельзя позволять порождениям глубин осквернять наши земли!', '', 28153),
(157797, 'ruRU', 'Иногда мы с Венриком как следует заправлялись и гоняли на ездовых попугаях. Попробуй, это весело! Заодно подгадим бандитам.', '', 28153),
(157796, 'ruRU', 'Перемелю...', '', 28153),
(157795, 'ruRU', 'Я... просчитался.', '', 28153),
(157794, 'ruRU', 'Это чудовище – воплощенное безумие и порча. Убей его немедленно!', '', 28153),
(157793, 'ruRU', 'Надеюсь, моя семья успела спастись.', 'Надеюсь, моя семья успела спастись.', 28153),
(157792, 'ruRU', 'Дым был таким густым. Мы заблудились бы в нем, если бы не королева Седогрив.', 'Дым был таким густым. Мы заблудились бы в нем, если бы не королева Седогрив.', 28153),
(157791, 'ruRU', 'Уничтожь этого монстра, отправь его обратно в пучину!', '', 28153),
(157790, 'ruRU', 'Мы еле выбрались оттуда живыми.', 'Мы еле выбрались оттуда живыми.', 28153),
(157789, 'ruRU', 'Зачем они это сделали?', 'Зачем они это сделали?', 28153),
(157788, 'ruRU', 'Ты мне на нервы действуешь!', '', 28153),
(157787, 'ruRU', 'Это все мое-е-е-е!', '', 28153),
(157786, 'ruRU', 'Я засверлю тебя насмерть!', '', 28153),
(157785, 'ruRU', '', 'Страже Праудмуров пришлось бы нелегко без этих припасов. Благодаря тебе, они спасены!', 28153),
(157784, 'ruRU', '', 'В южном проливе сел на мель один из наших кораблей. Команде удалось спастись, но ценные припасы они побросали.', 28153),
(157783, 'ruRU', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t Вестник войны Йенаж начинает применять заклинание |cFFF00000|Hspell:274932|h[Бездонный провал]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t Вестник войны Йенаж начинает применять заклинание |cFFF00000|Hspell:274932|h[Бездонный провал]|h|r!', 28153),
(157782, 'ruRU', 'Выпивка?! Ну почему не деньги?! Мы бы их лихо пропили!', '', 28153),
(157781, 'ruRU', 'В Вольной Гавани говорят, что некий пират спрятал часть своей наживы под водой у доков. Попробуй найти сокровище!', '', 28153),
(157780, 'ruRU', 'Хорошо! Теперь в Боралусе станет меньше азеритового оружия, и мы сможем заняться восстановлением порядка.', '', 28153),
(157779, 'ruRU', 'Корпорация Эшвейнов никак не прекратит производство оружия. Положи конец их работе в литейной, но не трогай мирных жителей.', '', 28153),
(157778, 'ruRU', 'Подыщем детишкам приемные семьи. Главное – чтобы у них были кров, еда и защита.', '', 28153),
(157777, 'ruRU', 'Корпорация Эшвейнов заманивает сирот на литейную, обещая им еду, и обращает их в рабство. Спаси детей!', '', 28153),
(157776, 'ruRU', 'Говорят, Лазуретос поднимал кракена из воды одной лапой. Он был и правда опасен. О тебе сложат легенды.', '', 28153),
(157775, 'ruRU', 'Есть одна матросская песня о Лазуретосе, который одним взмахом крыла переворачивает корабль. Убей его, и песни будут слагать о тебе.', '', 28153),
(157774, 'ruRU', '', 'Верховный воевода Саурфанг ждет вас. Преподайте Альянсу урок. За Орду!', 28153),
(157773, 'ruRU', 'Каждый раз, закрывая глаза... Я вижу огонь.', 'Каждый раз, закрывая глаза... Я вижу огонь.', 28153),
(157772, 'ruRU', 'Надеюсь, наши друзья в безопасности...', 'Надеюсь, наши друзья в безопасности...', 28153),
(157771, 'ruRU', 'Неужели мы потеряли Калимдор?', 'Неужели мы потеряли Калимдор?', 28153),
(157770, 'ruRU', 'Не могу поверить, что Древо Жизни... сгорело...', 'Не могу поверить, что Древо Жизни... сгорело...', 28153),
(157769, 'ruRU', 'Эти шелудивые псы из Орды уничтожили наш дом!', 'Эти шелудивые псы из Орды уничтожили наш дом!', 28153),
(157768, 'ruRU', 'Что тебе нужно? О, ты напоминаешь инженера. Коллега?', '', 28153),
(157767, 'ruRU', 'Я хочу спросить еще кое-что.', 'Я хочу спросить еще кое-что.', 28153),
(157766, 'ruRU', 'Этот сумасшедший повар? Он, наверное, троюродный брат. У него все мысли об одном: бомбы, чем больше, тем лучше. Грустно, конечно. Настоящий гений думает о том, как создать источник энергии для машин, которые будут рвать, кромсать и взрывать все подряд как можно дольше.', '', 28153),
(157765, 'ruRU', 'Добрый день, доктор. Я хочу купить один из твоих реакторов и готов щедро заплатить.', 'Добрый день, доктор. Я хочу купить один из твоих реакторов и готова щедро заплатить.', 28153),
(157764, 'ruRU', 'Это ты! Доктор Бум?', 'Это ты! Доктор Бум?', 28153),
(157763, 'ruRU', 'О, я вижу... Значит, ты действительно опытный инженер! До меня тебе, конечно, далеко, но это нормально.', '', 28153),
(157762, 'ruRU', '', 'Не знаю, кто это, но ее лучше убить!', 28153),
(157761, 'ruRU', 'Доктор, это совершенно потрясающая технология!', 'Доктор, это совершенно потрясающая технология!', 28153),
(157760, 'ruRU', '', 'Сбор у Черной наковальни! Нужно сосчитать потери.', 28153),
(157759, 'ruRU', 'Эй, я тут работаю, не мешай мне! Вернись, когда станешь опытным и умелым инженером.', '', 28153),
(157758, 'ruRU', '', 'Быстро вы с ними разобрались! Открываем дверь. Слышу, с той стороны нас уже ждут. Всем приготовиться!', 28153),
(157757, 'ruRU', 'Последние пять лет я занимаюсь исключительно тем, что ремонтирую, совершенствую и настраиваю самую продвинутую и смертоносную армию роботов в мире. Хочешь проверить, как твои обычный скучные питомцы справятся с роботами, созданными самым гениальным техником-недоучкой во вселенной?', '', 28153),
(157756, 'ruRU', 'Поломка?! Но как такое могло случиться?', '', 28153),
(157755, 'ruRU', 'Мой гениальный ум создает еще более гениальные изобретения. Это гениально.', '', 28153),
(157754, 'ruRU', '', 'Казалось бы, просто ходячий булыжник, а беды не оберешься.', 28153),
(157753, 'ruRU', '', 'В горах проснулся каменный колосс! Необходимо разрушить его, пока он не передавил мирных жителей!', 28153),
(157752, 'ruRU', 'Невероятно! В следующий раз сделаю роботов покрупнее.', '', 28153),
(157751, 'ruRU', 'Никакой питомец не выстоит против моей команды. Я неудержим!', '', 28153),
(157750, 'ruRU', 'Приготовься сразиться с моей непобедимой командой измененных до неузнаваемости и идеально настроенных роботов!', '', 28153),
(157749, 'ruRU', 'Краг\'ва, я готов.', 'Краг\'ва, я готова.', 28153),
(157748, 'ruRU', 'Тролли крови по-прежнему продолжают убивать мой народ. $b$bЯ помогу тебе добраться до их лидера, но потом мне придется поспешить в болота. Мне надо защитить моих детей.', '', 28153),
(157747, 'ruRU', 'Краг\'ва, предводительница троллей крови скрывается вон в том большом здании. Пожалуйста, помоги нам с ней справиться.', 'Краг\'ва, предводительница троллей крови скрывается вон в том большом здании. Пожалуйста, помоги нам с ней справиться.', 28153),
(157746, 'ruRU', 'Э... кхе. Давай не сейчас, Венрик. Мы тут по серьезному делу.', '', 28153),
(157745, 'ruRU', '', 'Я пришла помочь. В бой!', 28153),
(157744, 'ruRU', '', 'Я сражаюсь за свой народ.', 28153),
(157743, 'ruRU', '', 'Легкая добыча. Разделаемся с ней!', 28153),
(157742, 'ruRU', 'У которой \"волосы, как вороново крыло\". Ха-ха!', '', 28153),
(157741, 'ruRU', '', 'В память о Дарнасе!', 28153),
(157740, 'ruRU', '', 'Я с радостью покину это ужасное место.', 28153),
(157739, 'ruRU', '', 'Надо выбираться отсюда, пока не пришел... кто-то еще.', 28153),
(157738, 'ruRU', '', 'Да... Ничего страшного.', 28153),
(157737, 'ruRU', 'Слышь, Флинн? Как там твои дела с той дамой, о которой ты все рассказывал?', '', 28153),
(157736, 'ruRU', '', 'Мама! Ты в порядке?', 28153),
(157735, 'ruRU', '', 'Ты вернешь молот? Он таит в себе великую силу. Если гоблины поймут, как им пользоваться, ничего хорошего это нам не сулит.', 28153),
(157734, 'ruRU', '', '$n! У меня есть для тебя еще одно задание. Эти дикари были из Торговой компании. А это значит, что они направились в Кезан и сейчас наверняка уже передают Сталебой в грязные лапы шефа Разданка.', 28153),
(157733, 'ruRU', '', 'Тургаден, Телин, придумайте, как починить наковальню.', 28153),
(157732, 'ruRU', '', 'Сталебой украли, а Черная наковальня разрублена пополам!', 28153),
(157731, 'ruRU', '', 'А Кул-Тирас никогда не сдастся.', 28153),
(157730, 'ruRU', 'Друсты никогда... не отступят...', '', 28153),
(157729, 'ruRU', 'Будь я проклят!', '', 28153),
(157728, 'ruRU', 'Вы, двое, разуйте глаза! Посмотрите на Черную наковальню!', '', 28153),
(157727, 'ruRU', '', 'Вот же сын глубин! Видимо, это та же машина, которая напала на меня!', 28153),
(157726, 'ruRU', 'На меня напал какой-то железный громила и стащил Сталебой!', '', 28153),
(157725, 'ruRU', '', 'Да. Ты на себя-то посмотри.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157724, 'ruRU', 'Королева-регент! С тобой все в порядке?', '', 28153),
(157723, 'ruRU', '', 'Так, девочки и мальчики, заканчиваем с этим!', 28153),
(157722, 'ruRU', '', 'Мой народ уже побеждал вас. И мы сделаем это снова!', 28153),
(157721, 'ruRU', 'Фрос поглотит вас всех! Я отомщу!', '', 28153),
(157720, 'ruRU', '', 'Только все стало налаживаться...', 28153),
(157719, 'ruRU', '', '<Мойра что-то бормочет себе под нос.>', 28153),
(157718, 'ruRU', '', 'Телин, прорывайся через Зал ремесла! Кажется, они направляются в Черное хранилище.', 28153),
(157717, 'ruRU', '', '$n, отправляйся на тракт Черного Железа и зачисти его!', 28153),
(157716, 'ruRU', '', 'Тан наковальни! Собери своих чародеев для контратаки!', 28153),
(157715, 'ruRU', '', 'Мелкая зеленая погань?! В нашем доме?!', 28153),
(157714, 'ruRU', 'Гоблины! Они в туннелях!', '', 28153),
(157713, 'ruRU', '', '$n! К оружию!', 28153),
(157712, 'ruRU', '', 'Никто не смеет угрожать моей семье!', 28153),
(157711, 'ruRU', '', 'Мама!', 28153),
(157710, 'ruRU', '', 'Мама, осторожно!', 28153),
(157709, 'ruRU', '', 'Ого, вот это здоровяк!', 28153),
(157708, 'ruRU', 'Никто не уйдет!', '', 28153),
(157707, 'ruRU', '', 'Пойдем, милая. Нам пора уходить отсюда.', 28153),
(157706, 'ruRU', '', 'Новая волна!', 28153),
(157705, 'ruRU', '', 'Элементали атакуют!', 28153),
(157704, 'ruRU', '', 'Как выяснилось, сочетание мощной магии и азерита может вызывать... неожиданные эффекты.', 28153),
(157703, 'ruRU', '', 'Джайна? Это правда ты?', 28153),
(157702, 'ruRU', 'Старый хрыч хочет сказать, что тебе придется защищать нас от элементалей.', '', 28153),
(157701, 'ruRU', 'Вы... опоздали...', '', 28153),
(157700, 'ruRU', '$C! Пока мы будем придавать азериту форму, может произойти азеритогенез с непредсказуемыми последствиями. Как думаешь, справишься с ними?', '', 28153),
(157699, 'ruRU', 'Не подкинешь на наковальню еще азерита, $n?', '', 28153),
(157698, 'ruRU', 'Теперь ваш черед!', '', 28153),
(157697, 'ruRU', 'Глупцы! Вам ее уже не спасти!', '', 28153),
(157696, 'ruRU', 'Да, королева-регент.', '', 28153),
(157695, 'ruRU', '', 'Телин, Тургаден, давайте за работу.', 28153),
(157694, 'ruRU', '', 'Хватит! Довольно иллюзий, чудовище!', 28153),
(157693, 'ruRU', '', 'Прогресс налицо. Андуин чуть ли не каждый день интересуется, как идут дела, так что я решила показать тебе, что мы узнали.', 28153),
(157692, 'ruRU', '', 'С тех пор, как азерит впервые появился в наших шахтах, над его очисткой работают лучшие из лучших.', 28153),
(157691, 'ruRU', '', 'Рада тебя видеть, $n!', 28153),
(157690, 'ruRU', '', 'Отец... прошу тебя...', 28153),
(157689, 'ruRU', '', 'Встретимся у статуи на холме.', 28153),
(157688, 'ruRU', '', 'Великий Краг\'ва! Нам нужна твоя помощь!', 28153),
(157687, 'ruRU', 'Как в Третьей войне.', '', 28153),
(157686, 'ruRU', 'За команду \"Браво\"!', '', 28153),
(157685, 'ruRU', 'Прямо как на Дреноре!', '', 28153),
(157684, 'ruRU', 'Прямо как на Второй войне было.', '', 28153),
(157683, 'ruRU', 'Мф мф-мф мф.', 'Мф мф-мф мф.', 28153),
(157682, 'ruRU', 'Расскажи мне о плане убийства капитана Арейель.', 'Расскажи мне о плане убийства капитана Арейель.', 28153),
(157681, 'ruRU', 'Генерал.', '', 28153),
(157680, 'ruRU', '', 'Выступаем немедленно. $n займет позицию. Остальные обеспечат поддержку и разведают территорию. Кишан, ты в том числе.', 28153),
(157679, 'ruRU', '', 'Мы спасем тортолланов и получим информацию о перемещениях Орды. Это поможет нам найти капитана Арейель.', 28153),
(157678, 'ruRU', 'Мэм, в Назмире обнаружены тортолланы, и, согласно разведданным, им известно о действиях Орды. Нескольких из них взяли в плен тролли крови.', '', 28153),
(157677, 'ruRU', 'Лещам – по щам!', 'Лещам – по щам!', 28153),
(157676, 'ruRU', 'Плотве – по ботве!', 'Плотве – по ботве!', 28153),
(157675, 'ruRU', '', 'Чтобы выполнить поставленную задачу, нам понадобится информация и союзники в Назмире. Нам повезло, у нас есть хорошая возможность. Кишан?', 28153),
(157674, 'ruRU', '', 'Гибель капитана Арейель помешает операциям Орды в Назмире и ослабит темных следопытов Сильваны.', 28153),
(157673, 'ruRU', 'Эти тролли слишком долго обижали моих детей! Теперь охотиться буду я.', '', 28153),
(157672, 'ruRU', 'Я всегда считал, что Мертвецкая Трясина в другой стороне, нет?', '', 28153),
(157671, 'ruRU', '', 'С тех пор, как Недли исчез, у нас тут тишина и покой.', 28153),
(157670, 'ruRU', 'Этого нельзя допустить. Собери союзников. Стромгард должен принадлежать только Альянсу!', '', 28153),
(157669, 'ruRU', 'Однако Орда собирается отбить у нас город. В случае успеха она захватит стратегически важную позицию в Восточных королевствах.', '', 28153),
(157668, 'ruRU', 'Во времена Лордеронского Альянса Стромгард был одной из важнейших столиц. Нужно вернуть ему этот статус.', '', 28153),
(157667, 'ruRU', 'Организуй экспедицию и добудь азерит... пока он не достался Орде.', '', 28153),
(157666, 'ruRU', 'Разведчики мастера Шоу обнаружили в океане острова с залежами азерита. Альянсу очень нужен этот ресурс.', '', 28153),
(157665, 'ruRU', 'Ваши агенты будут проводить тайные операции против Орды... ради нашей общей победы.', '', 28153),
(157664, 'ruRU', 'Собери диверсионный отряд. Помогать тебе в этом будет настоящий знаток шпионажа – мастер Матиас Шоу.', '', 28153),
(157663, 'ruRU', 'Для победы в войне в первую очередь нужны войска и оружие. Но иногда приходится действовать... более тонко.', '', 28153),
(157662, 'ruRU', 'Я готов призвать Краг\'ву.', 'Я готова призвать Краг\'ву.', 28153),
(157661, 'ruRU', '', 'Зеллинг разговаривает со своей семьей. Не подходи – мы увидим, если мне надо будет вмешаться.', 28153),
(157660, 'ruRU', '', 'Найдите слабые места в обороне противника и используйте их.', 28153),
(157659, 'ruRU', '', 'Гарона Полуорчиха поможет тебе собрать самых хитрых и коварных лазутчиков. Они займутся тайными операциями в Кул-Тирасе и Зандаларе.', 28153),
(157658, 'ruRU', '', 'Тебе пригодится помощник с... уникальными навыками, и у меня как раз есть такой. Уверена, вместе вы справитесь намного быстрее и эффективнее.', 28153),
(157657, 'ruRU', '', 'В том районе много патрулей Альянса, поэтому надо действовать быстро и скрытно. Обыщи останки корабля ночью.', 28153),
(157656, 'ruRU', '', 'Хорошая новость, Натанос. Брат Зеллинг начинает приносить нам пользу. Он указал, где искать затонувший корабль.', 28153),
(157655, 'ruRU', '', 'Теперь король-мальчишка хочет восстановить город. Нельзя этого допустить.', 28153),
(157654, 'ruRU', '', 'Стромгард был одной из столиц Альянса в Восточных королевствах... пока не превратился в руины.', 28153),
(157653, 'ruRU', '', 'Исследуй эти острова и добудь весь азерит, пока до него не добрался Альянс!', 28153),
(157652, 'ruRU', '', 'Все-таки гоблины – ценные союзники. Они обнаружили залежи азерита на островах и поделились находкой с нами.', 28153),
(157651, 'ruRU', '', 'На войне один удар кинжалом в спину может оказаться гораздо эффективнее, чем атака тысячи воинов.', 28153),
(157650, 'ruRU', '', 'Милденхолл совсем свихнулся! Порождения его экспериментов заполонили всю медоварню. Что, если они выйдут из-под контроля? Займись ими.', 28153),
(157649, 'ruRU', '', 'Я благодарю тебя и твою Орду за то, что помогли спасти мою команду.\n\nПока я у руля, братство Туманных Парусов будет свободным!', 28153),
(157648, 'ruRU', '', 'Это он был последней жертвой... мы ошиблись.', 28153),
(157647, 'ruRU', 'Нет... не может быть!', '', 28153),
(157646, 'ruRU', 'Но я вам покажу!', '', 28153),
(157645, 'ruRU', 'Страданий? Вы еще не знаете, что это такое...', '', 28153),
(157644, 'ruRU', 'Телия, если у вас будет возможность посетить Штормград, я с радостью приму вас. Я столько могу рассказать о вашем отце.', '', 28153),
(157643, 'ruRU', '', 'Но потом письма прекратились. У меня... столько вопросов...', 28153),
(157642, 'ruRU', '', 'Убейте его быстро. Хватит на сегодня страданий.', 28153),
(157641, 'ruRU', '', '\"Моя звездочка\".', 28153),
(157640, 'ruRU', 'Теперь я вспомнил... Он иногда писал вам письма. В них он называл вас...', '', 28153),
(157639, 'ruRU', 'Он был великим человеком. Героем для всего Альянса – и для меня.', '', 28153),
(157638, 'ruRU', '', 'Вы знали моего отца?', 28153),
(157637, 'ruRU', '<Джакра\'зет стонет.>', '', 28153),
(157636, 'ruRU', 'Телия, прошу, встаньте. Это честь для меня.', '', 28153),
(157635, 'ruRU', '', 'Дочь Болвара. После Третьей войны она воспитывалась у нас.', 28153),
(157634, 'ruRU', 'Фордрагон?!', '', 28153),
(157633, 'ruRU', '', 'Телия Фордрагон.', 28153),
(157632, 'ruRU', '', 'Ваше величество. Меня зовут Телия.', 28153),
(157631, 'ruRU', '', 'Она сыграла огромную роль в спасении нашего королевства... и моей жизни.', 28153),
(157630, 'ruRU', '', 'Король, позвольте вас кое с кем познакомить...', 28153),
(157629, 'ruRU', 'Я с радостью и гордостью вновь приветствую Кул-Тирас в рядах Альянса. Пусть Свет укажет нам путь к победе.', '', 28153),
(157628, 'ruRU', '', 'Спасибо... Клянусь, я сделаю все, чтобы оправдать ваше доверие.', 28153),
(157627, 'ruRU', '', 'Что скажете?', 28153),
(157626, 'ruRU', '', 'Все кончено, генерал. Заговоры. Ложь. Убийства.', 28153),
(157625, 'ruRU', '', 'Сэм! Нет!', 28153),
(157624, 'ruRU', 'ШТОРМСОНГ!', '', 28153),
(157623, 'ruRU', 'Ты сам привел сюда свою погибель, Пайк. А я передам флот нашей спасительнице.... Азшаре.', '', 28153),
(157622, 'ruRU', 'Все, что я вижу, это заблудшие души.', '', 28153),
(157621, 'ruRU', 'Сдавайся, Штормсонг! Ты окружен! Оглядись вокруг!', '', 28153),
(157620, 'ruRU', 'Сразу видно мастера. Если надо будет еще что-то разрушить, позову тебя!', '', 28153),
(157619, 'ruRU', 'С оружием у нас не очень, так что придется брать хитростью. Нанеси врагам как можно больше ущерба и незаметно сделай ноги.', '', 28153),
(157618, 'ruRU', '', 'Даже не знаю, что эта тварь могла бы сделать с кораблями... И не узнаю, благодаря тебе!', 28153),
(157617, 'ruRU', '', 'Ты всегда была слишком слабой, Кэтрин.', 28153),
(157616, 'ruRU', '', 'А я... Присцилла... Как ты могла предать наше королевство? Предать меня?', 28153),
(157615, 'ruRU', '', 'Этот голем способен разбить корабль в щепки! Нельзя оставлять лорду Штормсонгу оружие такой силы.', 28153),
(157614, 'ruRU', '', 'Вы наняли пиратов, вооружили их до зубов и послали убивать свой народ.', 28153),
(157613, 'ruRU', '', 'Это азерит. Альянс и Орда уже ведут войну за обладание им.', 28153),
(157612, 'ruRU', '', 'Врата Дэлина разрушило ВАШЕ оружие, начиненное вот этим!', 28153),
(157611, 'ruRU', '', 'Леди Присцилла Эшвейн, я обвиняю вас в организации контрабанды, сговоре с пиратами и предательстве адмиралтейства Кул-Тирас!', 28153),
(157610, 'ruRU', 'Океан щедр на дары, но его глубины таят опасность.', '', 28153),
(157609, 'ruRU', '', 'Что все это значит, девчонка?!', 28153),
(157608, 'ruRU', '', 'Так вот зачем ты все это подстроила!', 28153),
(157607, 'ruRU', '', 'Лгунья!', 28153),
(157606, 'ruRU', 'Древний ужас снова поднялся из самых глубин. Отправь его обратно в пучину.', '', 28153),
(157605, 'ruRU', '', 'Леди Эшвейн была мне опорой с того дня, когда мы обе потеряли мужей. Теперь она станет опорой королевства. Она...', 28153),
(157603, 'ruRU', '', 'Но этого недостаточно.', 28153),
(157602, 'ruRU', '', 'Вот и еще один день мы проживем без потопа.', 28153),
(157601, 'ruRU', 'Последний раз я видел столько дыма, когда бабуля Дэвенпорт учила внука печь пироги. Спасибо тебе!', '', 28153),
(157600, 'ruRU', '', 'Молчать!', 28153),
(157599, 'ruRU', '', 'Наги призвали живое осадное орудие для штурма дамбы! Нам срочно нужно туда!', 28153),
(157598, 'ruRU', 'Пираты?! Праудмуры теперь даже с пиратами не справляются?!', '', 28153),
(157597, 'ruRU', '', 'Пиратский флот обрушил на них невероятную мощь...', 28153),
(157596, 'ruRU', 'Шторм опасен и непредсказуем, но тебе удалось усмирить его!', '', 28153),
(157595, 'ruRU', 'Я чувствую магию жрецов моря. Уничтожь ее источник любой ценой!', '', 28153),
(157594, 'ruRU', 'Мы тесним врагов, но они быстро оправляются от потерь. Нужно лишить Орду древесины. Спали их запасы! Полностью!', '', 28153),
(157593, 'ruRU', '', 'Это правда. Врата Дэлина... уничтожены.', 28153),
(157592, 'ruRU', 'Ничего себе грохнуло, аж уши заложило! Там что-нибудь осталось, кроме развалин?', '', 28153),
(157591, 'ruRU', '', 'Урожай спасен! А этих маленьких негодяев мы увезем подальше от деревни.', 28153),
(157590, 'ruRU', '', 'Я знала, что мы не зря стараемся. Хорошо, что бывают такие старушки!', 28153),
(157589, 'ruRU', '', 'Кто-то поедает семена, не давая им прорасти. Посмотри, что можно сделать!', 28153),
(157588, 'ruRU', '', 'Мисс Дэвенпорт собрала припасы для фронта и просит доставить их солдатам. Старушка – кремень! Только безумец откажется помочь ей.', 28153),
(157587, 'ruRU', 'Мы будем без устали очищать Святилище, пока оно не освободится от порчи.', '', 28153),
(157586, 'ruRU', 'Враги хотят осквернить нашу святыню. Останови их!', '', 28153),
(157585, 'ruRU', '', 'Я понимаю, что истребление вредителей – не геройское дело, но фермеры на тебя не нарадуются.', 28153),
(157584, 'ruRU', '', 'Два Жернова как будто проклял кто! На местных складах завелись стаи вредителей. Помоги крестьянам спасти урожай.', 28153),
(157583, 'ruRU', 'Однажды здесь снова зазвучат священные заклинания жрецов моря... но до того дня еще далеко.', '', 28153),
(157582, 'ruRU', '', 'Надеюсь, теперь эти великаны уберутся к себе в горы и больше не явятся сюда!', 28153),
(157581, 'ruRU', 'Чары моего бывшего лорда укоренились глубоко. Избавь нас от них.', '', 28153),
(157580, 'ruRU', 'Спасибо. Жители долины не забудут твоих подвигов.', '', 28153),
(157579, 'ruRU', '', 'Эттины терроризируют Два Жернова, местные жители парализованы ужасом. Мы – их последняя надежда!', 28153),
(157578, 'ruRU', 'Бреннадаму до сих пор не хватает сил для контратаки. Твоя помощь сейчас была бы неоценима!', '', 28153),
(157577, 'ruRU', 'Приготовься к отплытию и поговори с капитаном Анжеликой.', '', 28153),
(157576, 'ruRU', '', 'Ой, надо же было спросить, нет ли у тебя аллергии на пчел. Но раз ты в порядке, теперь я знаю, к кому обращаться в следующий раз!', 28153),
(157575, 'ruRU', 'Благодарю за быструю явку, $n. Ты отправишься в путь с Третьим флотом.', '', 28153),
(157574, 'ruRU', 'Замечательно. Подобному злу не место в нашем мире.', '', 28153),
(157573, 'ruRU', '', 'Пчелы с медоварни летают по всей округе и жалят местных жителей. А Милденхоллы ничего не могут поделать — какой сюрприз!', 28153),
(157572, 'ruRU', 'Мастер Шоу, меня прислал король Андуин.', 'Мастер Шоу, меня прислал король Андуин.', 28153),
(157571, 'ruRU', '', 'Что-то на ферме сводит вендиго с ума. Они вели себя тише воды, пока эти безумцы Милденхоллы не въехали туда.', 28153),
(157570, 'ruRU', '', 'На медоварню Милденхоллов напали вендиго. Сможешь выручить медоваров и отразить нападение?', 28153),
(157569, 'ruRU', 'К\'тиры совершают темные ритуалы на борту \"Мелодии глубин\". Очисти корабль от их порчи!', '', 28153),
(157568, 'ruRU', 'Нас мало, но мы держим рубежи благодаря тебе.', '', 28153),
(157567, 'ruRU', 'Жрецы моря разбудили погибших моряков и напали на Перекресток Течений. Скорее туда!', '', 28153),
(157566, 'ruRU', '', 'Похоже, когда-то это был почтенный грибостраж. Гибель столь благородного воина – всегда трагедия.', 28153),
(157565, 'ruRU', '', 'В пещере к югу отсюда завелся кто-то очень большой. И страшный настолько, что от одних рассказов у меня волосы дыбом...', 28153),
(157564, 'ruRU', '', 'Спасибо. Клянусь, это был последний раз, когда мы спасали его шкуру!', 28153),
(157563, 'ruRU', 'Мы никак не можем избавиться от аванпоста Орды. Лиши врага припасов. Можешь взорвать склады, если потребуется!', '', 28153),
(157562, 'ruRU', '', 'Оружие из мастерских Штормсонга должно защищать людей, а не убивать их.', 28153),
(157561, 'ruRU', 'Может, это задание показалось тебе несерьезным, но кому еще его поручить?', '', 28153),
(157560, 'ruRU', 'В охотничьих угодьях Кеннингса что-то не так. Они сорвали все сроки по поставкам для Адмиралтейства. Разберись, в чем там дело.', '', 28153),
(157559, 'ruRU', '', 'Жаль, что столь ценные припасы пропадают без дела. Думаю, ты знаешь, что делать.', 28153),
(157558, 'ruRU', 'Без ополчения следить за свинобразами приходится нам.', '', 28153),
(157557, 'ruRU', 'Из лабиринтов свинобразов опять доносится подозрительная возня. Сорви их планы.', '', 28153),
(157556, 'ruRU', 'Нура, я хочу помочь.', 'Нура, я хочу помочь.', 28153),
(157555, 'ruRU', '', 'Что заставило тебя проделать такой путь?', 28153),
(157554, 'ruRU', 'Встретимся в городе и все поделим.', '', 28153),
(157553, 'ruRU', 'Ты можешь меня подбросить до Верхнего пути в Южных степях?', 'Ты можешь меня подбросить до Верхнего пути в Южных степях?', 28153),
(157552, 'ruRU', 'Корабль без парусов – будто кавалерист без лошади. Он... просто бесполезен.', '', 28153),
(157551, 'ruRU', 'Шторм бушует на складах. Усмири его, а то плакали наши снасти!', '', 28153),
(157550, 'ruRU', 'Память об Аддингтоне будет жить вечно. Спасибо тебе за все.', '', 28153),
(157549, 'ruRU', 'Брат Аддингтон никогда не допустил бы этого кошмара. Почти его память – отбей верфь.', '', 28153),
(157548, 'ruRU', '', 'Все начинается с простого сырья. Красоту создают тяжелый труд и мастерство.', 28153),
(157547, 'ruRU', '', 'Нашим корабелам нет равных, но что они могут без древесины? Наведи здесь порядок!', 28153),
(157546, 'ruRU', '', 'Так им и надо! Наша долина открыта для всех!', 28153),
(157545, 'ruRU', '', 'Войска Штормсонга опять выставили заставу на дороге. Освободи путь для купцов!', 28153),
(157544, 'ruRU', 'А теперь поторопись!', '', 28153),
(157543, 'ruRU', 'Поговори с Изабеллой. Она переправит тебя в целости и сохранности к точке сбора в Подгороде.', '', 28153),
(157542, 'ruRU', 'Когда мы соберем достаточно бойцов, я введу вас всех в курс дела.', '', 28153),
(157541, 'ruRU', 'Рад тебя видеть, $n. Нам нельзя терять ни минуты.', '', 28153),
(157540, 'ruRU', 'Защищать, беречь и направлять – вот истинный долг жрецов моря.', '', 28153),
(157539, 'ruRU', 'Все жрецы моря клянутся защищать свой народ. Помоги нам сдержать священные обеты!', '', 28153),
(157538, 'ruRU', 'Враг не сдается. Но благодаря тебе у нас остаются шансы на победу!', '', 28153),
(157537, 'ruRU', 'Похоже, ритуал благополучно провалился. Злобная магия наг больше не будет осквернять море.', '', 28153),
(157536, 'ruRU', 'Прислужники Азшары готовят новый ритуал. Отправь их в любезные их сердцам темные глубины, да поглубже и потемнее.', '', 28153),
(157535, 'ruRU', '', 'Наги становятся все агрессивнее с каждым днем. Боюсь, еще немного, и мы с ними не справимся.', 28153),
(157534, 'ruRU', '', 'Орден никак не придет в себя после нападения наг. Помоги им восстановить нормальное течение жизни.', 28153),
(157533, 'ruRU', 'Эти ресурсы нам очень пригодятся. Прихвати как можно больше!', '', 28153),
(157532, 'ruRU', 'Пока мы живы, враг не захватит долину. Клянусь океаном!', '', 28153),
(157531, 'ruRU', 'Все в жизни бывает впервые... но надеюсь, второго раза в этом случае не будет.', '', 28153),
(157530, 'ruRU', 'Не знаю, что и думать... в городе происходят странные вещи. Разберись, в чем дело, пожалуйста.', '', 28153),
(157529, 'ruRU', '', 'Если отречься от всех чувств... внутри останется лишь пустота.', 28153),
(157528, 'ruRU', '', 'Джайна, милая... никто не может всегда повиноваться голосу разума.', 28153),
(157527, 'ruRU', '', 'Джайна, все это – лишь иллюзия!', 28153),
(157526, 'ruRU', '', 'Но... меня обманули...', 28153),
(157525, 'ruRU', 'А я думал, ты станешь настоящим лидером!', '', 28153),
(157524, 'ruRU', 'Ты использовала Кирин-Тор ради личных целей!', '', 28153),
(157523, 'ruRU', '', 'Жаль, что твой отец так этого и не понял...', 28153),
(157522, 'ruRU', '', 'Остановить кровопролитие – благородная цель, Джайна...', 28153),
(157521, 'ruRU', 'Армия лорда Штормсонга угрожает захватить эту землю. Ты ведь не допустишь этого?', '', 28153),
(157520, 'ruRU', '', 'Отойди от нее!', 28153),
(157519, 'ruRU', 'Хир\'ик – лоа ночи. Больше тебе ничего знать не надо.', 'Хир\'ик – лоа ночи. Больше тебе ничего знать не надо.', 28153),
(157518, 'ruRU', '', 'Я во всем виновата...', 28153),
(157517, 'ruRU', 'Но ты... ты остановила меня. Сколько солдат Альянса пало в той битве? И во всех последующих?', '', 28153),
(157516, 'ruRU', 'Я мог с ними покончить! С Траллом... Сильваной... Только представь, каким был бы наш мир без их проклятой Орды!', '', 28153),
(157515, 'ruRU', '', 'Нет. Это одна из тварей, которые мучают Джайну. Поспешим!', 28153),
(157514, 'ruRU', '', 'Этот голос... Дэлин?!', 28153),
(157513, 'ruRU', '', 'Снова иллюзия? Значит, Джайна все еще где-то здесь.', 28153),
(157512, 'ruRU', '', 'Мы должны найти и освободить ее.', 28153),
(157511, 'ruRU', '', 'Моя дочь все еще где-то здесь. Прячется. Страдает.', 28153),
(157510, 'ruRU', 'Течения разнесут весть о твоем подвиге далеко за пределы долины.', '', 28153),
(157509, 'ruRU', '', 'Нужно искать дальше.', 28153),
(157508, 'ruRU', '', 'Исчезла... это была не Джайна, а лишь отголосок ее страданий.', 28153),
(157507, 'ruRU', '', 'Но даже самые сильные из нас не могут спасти всех.', 28153),
(157506, 'ruRU', '', 'Джайна... ты была... и остаешься... гордостью Кул-Тираса... Воплощением его мощи...', 28153),
(157505, 'ruRU', '', 'Нет! Джайна, не слушай их!', 28153),
(157504, 'ruRU', '', 'Я... подвела их... всех...', 28153),
(157503, 'ruRU', '', 'Ты могла помешать ему! Ты могла нас спасти!', 28153),
(157502, 'ruRU', 'Жду приказаний, верховный владыка.', 'Жду приказаний, верховный владыка.', 28153),
(157501, 'ruRU', 'Ордену снова нужна твоя помощь. Пусть волны приведут тебя к победе.', '', 28153),
(157500, 'ruRU', 'Ты бросила нас умирать!', '', 28153),
(157499, 'ruRU', '', 'Пойдем дальше, $p.', 28153),
(157498, 'ruRU', '', 'Я всегда ее находила... найду и в этот раз.', 28153),
(157497, 'ruRU', '', 'Когда Джайна в детстве чего-то боялась, она пряталась.', 28153),
(157496, 'ruRU', '', 'Стой!', 28153),
(157495, 'ruRU', '', 'Нет! Ты мне не поможешь! Никто мне не поможет!', 28153),
(157494, 'ruRU', '', 'Все хорошо, милая...', 28153),
(157493, 'ruRU', '', 'Я вижу Джайну! Идем, скорее!', 28153),
(157492, 'ruRU', 'Фрос... поглотит вас...', '', 28153),
(157491, 'ruRU', '', 'Я не дам вам ее удерживать.', 28153),
(157490, 'ruRU', 'Праудмурова дочка наша, чужаки!', '', 28153),
(157489, 'ruRU', '', '$n, скорее идем за ней!', 28153),
(157488, 'ruRU', '', 'Джайна! Стой!', 28153),
(157487, 'ruRU', '', 'Нет! Не подходи!', 28153),
(157486, 'ruRU', '', 'Джайна?!', 28153),
(157485, 'ruRU', '', 'Это... я виновата...', 28153),
(157484, 'ruRU', '', 'Бесплотный мир... подходящее название...', 28153),
(157483, 'ruRU', 'Да благословит тебя море за помощь.', '', 28153),
(157482, 'ruRU', 'Океан великий... нужно избавить долину от этого кошмара раз и навсегда!', '', 28153),
(157481, 'ruRU', 'Так будет со всеми, кто обратит дары Матери волн во зло.', '', 28153),
(157480, 'ruRU', 'Тот, кто нарушает законы моря, должен быть наказан.', '', 28153),
(157479, 'ruRU', 'Торга – крохотное существо огромной силы. Мы, тортолланы, будем помнить все, что он нам рассказывал.', '', 28153),
(157478, 'ruRU', 'Давай пока остановимся здесь, $p.', '', 28153),
(157477, 'ruRU', 'Грал – мудрый лоа. Он смотрит в суть вещей. Его царство – морские глубины, его владения – бездонный океан.', 'Грал – мудрый лоа. Он смотрит в суть вещей. Его царство – морские глубины, его владения – бездонный океан.', 28153),
(157476, 'ruRU', 'Пусть море отвергнет всех, кто отверг свой народ.', '', 28153),
(157475, 'ruRU', 'Вот теперь нам ничего не жмет и не колет!', '', 28153),
(157474, 'ruRU', 'Свинобразы затеяли какую-то возню на ферме у лабиринта. Выясни, что они задумали, и помешай им.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157473, 'ruRU', 'Еще одна нечестивая душа на службе Штормсонга. Останови ее.', '', 28153),
(157472, 'ruRU', 'Покойся с миром. Твои страдания окончены.', '', 28153),
(157471, 'ruRU', 'Сколько же мерзости наплодили мои братья... Убей эту тварь.', '', 28153),
(157470, 'ruRU', 'Я пошел.', 'Я пошла.', 28153),
(157469, 'ruRU', 'Да... милорд.', 'Да... милорд.', 28153),
(157468, 'ruRU', 'Ч-что там?', 'Ч-что там?', 28153),
(157467, 'ruRU', 'Ну, я пошел.', 'Ну, я пошла.', 28153),
(157466, 'ruRU', 'Еще работа?', 'Еще работа?', 28153),
(157465, 'ruRU', '', 'Уже лечу, босс!', 28153),
(157464, 'ruRU', 'Да, я вижу еще одно небольшое место раскопок к западу отсюда. Келси?', '', 28153),
(157463, 'ruRU', 'Держитесь вместе. Мы должны победить любой ценой!', '', 28153),
(157462, 'ruRU', 'Самые крупные участки находятся дальше к югу. Как я и подозревал.', '', 28153),
(157461, 'ruRU', 'Орда подожгла город! Скорее, туши здания, пока не запылала вся долина!', '', 28153),
(157460, 'ruRU', 'Огонь гаснет, и даже разрушений не так много! Спасибо тебе!', '', 28153),
(157459, 'ruRU', 'Сетраки и своей добычи не унесут отсюда, уж об этом я позабочусь!', 'Сетраки и своей добычи не унесут отсюда, уж об этом я позабочусь!', 28153),
(157458, 'ruRU', 'Я не могу призвать наших моряков домой, но корабли определенно не погибли. Теперь судьба флота в руках Праудмуров.', '', 28153),
(157457, 'ruRU', 'Джани – лоа ненужных вещей и живых существ, которых отвергают или не замечают другие. Он защищает сирот вроде меня или тех, кого сильно потрепала жизнь.', '', 28153),
(157456, 'ruRU', 'Здесь моя магия действует сильнее всего. Если флот еще можно найти, нужно попробовать.', '', 28153),
(157455, 'ruRU', 'Э-э... уходи... <ик!> Я занят.', '', 28153),
(157454, 'ruRU', 'Мы – последователи Торкали, Блуждающей горы и Скитающегося бастиона. Пока лоа с нами, наши щиты остановят кого угодно.', '', 28153),
(157453, 'ruRU', '', 'Одной угрозой для долины меньше! Спасибо!', 28153),
(157452, 'ruRU', '', 'Слов нет... Невероятное мастерство!', 28153),
(157451, 'ruRU', 'Стойте. Кажется, я что-то вижу...', '', 28153),
(157450, 'ruRU', 'Я и не думал, что у нас получится, но это золото поможет людям вернуться к мирной жизни!', '', 28153),
(157449, 'ruRU', 'Да... Я чувствую корабли... Наш флот! Черный туман вокруг него рассеивается!', '', 28153),
(157448, 'ruRU', 'Я здесь, чтобы разобраться с твоими проблемами, Крог.', 'Я здесь, чтобы разобраться с твоими проблемами, Крог.', 28153),
(157447, 'ruRU', '', 'Орден сообщил нам, что поблизости бродит опасное животное. Расправься с ним!', 28153),
(157446, 'ruRU', '', 'В холмах завелся опасный хищник. Найди и убей его!', 28153),
(157445, 'ruRU', 'Жители Мертвецкой Трясины готовы пожертвовать золото на восстановление Бреннадама. Но золото придется собирать тебе.', '', 28153),
(157444, 'ruRU', 'Артур...', '', 28153),
(157443, 'ruRU', 'Дорас, мне нужен ветрокрыл в деревню Гиблотопь.', 'Дорас, мне нужен ветрокрыл в деревню Гиблотопь.', 28153),
(157442, 'ruRU', '', 'Прекрасная работа! Помогая Ай\'твену, ты радуешь всех тортолланов... и, видимо, лоа.', 28153),
(157441, 'ruRU', 'Так я и обрушил! Просто они оказались очень злыми.', '', 28153),
(157440, 'ruRU', 'Тебе поручали обрушить насыпи.', '', 28153),
(157439, 'ruRU', 'Ой, да брось! Ведь все хорошо. Мы расправились с большим каменным монстром и выжили! Полная победа.', '', 28153),
(157438, 'ruRU', 'Артур! Что тебе говорилось насчет того, чтобы сломя голову бросаться на поиски приключений?', '', 28153),
(157437, 'ruRU', '', 'Тортолланы поклоняются великой черепахе Ай\'твену, их древнему союзнику. Защищай и корми его, тогда он поможет и нам.', 28153),
(157436, 'ruRU', 'Убирайтесь отсюда!', '', 28153),
(157435, 'ruRU', 'Ты следуешь верным курсом! Твои подвиги стали примером для нас.', '', 28153),
(157434, 'ruRU', 'Мы пойдем дальше на юг. Будем на связи, Гузберт.', '', 28153),
(157433, 'ruRU', 'Давай, Гуззи! Ты сможешь!', '', 28153),
(157432, 'ruRU', '', 'Покажи класс, Гузберт!', 28153),
(157431, 'ruRU', '...с ОГРОМНОЙ КУЧЕЙ БОМБ!', '', 28153),
(157430, 'ruRU', 'Раскопки, да? Кажется, это работа для гнома...', '', 28153),
(157429, 'ruRU', 'Реликварий проводит раскопки на небольшом участке где-то в пятистах метрах к востоку отсюда.', '', 28153),
(157428, 'ruRU', '$n, сзади! Помоги мне разобраться с этими паразитами.', '', 28153),
(157427, 'ruRU', 'Древняя черепаха Ай\'твен – одно из чудес света, и его нужно беречь. Помоги тортолланам ухаживать за ним.', '', 28153),
(157426, 'ruRU', 'Мы должны призвать лорда Штормсонга к ответу за все... любой ценой.', '', 28153),
(157425, 'ruRU', 'Жители долины заслужили мирную жизнь. Карай без пощады всех, кто угрожает их спокойствию.', '', 28153),
(157424, 'ruRU', 'Нужно поспешить, иначе Азшара заберет наши корабли.', '', 28153),
(157423, 'ruRU', 'Здесь опасно. Пойдем, рядом есть аванпост, с которого хорошо просматривается Святилище.', '', 28153),
(157422, 'ruRU', 'Его не забудут. Мы этого не допустим.', '', 28153),
(157421, 'ruRU', 'Голос становится неотличим от вашего. Вы чувствуете, что он ищет ответ на вопрос, который мучает и вас тоже.\n\n\"Зачем?\"', '', 28153),
(157420, 'ruRU', 'Вы морщитесь от боли, когда голос у вас в голове срывается на крик.\n\n\"С чего все началось?\"', '', 28153),
(157419, 'ruRU', 'Уже скоро фермеры вернутся к работе в полях. Спасибо тебе!', '', 28153),
(157418, 'ruRU', 'От фермеров пришла просьба о помощи. Выясни, что случилось, и наведи в долине порядок!', '', 28153),
(157417, 'ruRU', 'Голос звучит громче и настойчивее.\n\n\"Еще! Еще! Еще!\"', '', 28153),
(157416, 'ruRU', 'Отголоски древнего голоса доносятся из глубин вашего сознания.\n\n\"Что ты ищешь?\"', '', 28153),
(157415, 'ruRU', 'Ты меня постоянно удивляешь! Не дашь пару уроков боевого мастерства?', '', 28153),
(157414, 'ruRU', 'Хорошо. Если тебе нужно незаметно покинуть Боралус, положись на моих агентов.', '', 28153),
(157413, 'ruRU', 'Я вернусь в лагерь и расскажу обо всем Березняку. Увидимся!', '', 28153),
(157412, 'ruRU', 'Ха! Вот это мощь!', '', 28153),
(157411, 'ruRU', '', 'Сэм... его... больше нет...', 28153),
(157410, 'ruRU', 'Когда последний из его подданных будет убит и вернется Отрекшимся, мальчишка склонится перед Темной Госпожой. Она станет единственной королевой и будет править всеми.', '', 28153),
(157409, 'ruRU', 'Месть. Презрение. Называй, как хочешь.', '', 28153),
(157408, 'ruRU', '', 'Тобой движет месть. Я это прекрасно понимаю.', 28153),
(157407, 'ruRU', 'Когда хватка Короля-лича ослабла, Сильвана стала искать союзников. Но люди открыли охоту на павших защитников Лордерона. И поэтому теперь я охочусь на них.', '', 28153),
(157406, 'ruRU', '', 'Отвернулся?', 28153),
(157405, 'ruRU', 'Когда-то я сражался за Альянс. Но, с тех пор как он отвернулся от нас, его невыносимая надменность возросла многократно.', '', 28153),
(157404, 'ruRU', '', 'Рвение, с которым ты воюешь за Орду, явно возникло не из одного почтения к Сильване.', 28153),
(157403, 'ruRU', '', 'Одного короля я прикончила. Возможно, настала очередь и второго.', 28153),
(157402, 'ruRU', 'Хорошо. Альянс не заслуживает жалости. Заставь их страдать, и Темная Госпожа вознаградит тебя.', '', 28153),
(157401, 'ruRU', '', 'Верно. Не сомневайся и в том, что я была союзницей Альянса, лишь пока это отвечало моим интересам. Я им ничем не обязана. Мой дом – Орда.', 28153),
(157400, 'ruRU', 'Глупцы...', '', 28153),
(157399, 'ruRU', 'Именем Кул-Тираса, убирайтесь отсюда!', '', 28153),
(157398, 'ruRU', 'Я знаю эту историю. Но ты убила Ллейна Ринна не по своей воле.', '', 28153),
(157397, 'ruRU', '', 'Потому что я дружила с дедом юного короля? Если помнишь, я же его и убила.', 28153),
(157396, 'ruRU', 'Твои операции против Альянса прошли блестяще. Признаться, я опасался, что твоя верность Орде могла... пошатнуться.', '', 28153),
(157395, 'ruRU', 'Ха-ха... свежее мясо!', '', 28153),
(157394, 'ruRU', 'Познай гнев природы!', '', 28153),
(157393, 'ruRU', 'Я сотру тебя в порошок!', '', 28153),
(157392, 'ruRU', 'Вы уверены, что хотите продолжить?', 'Вы уверены, что хотите продолжить?', 28153),
(157391, 'ruRU', 'Благодарю, $p. Жители долины перед тобой в неоплатном долгу.', '', 28153),
(157390, 'ruRU', 'Спи. Спи и смотри сны о Затонувшем городе.', 'Спи. Спи и смотри сны о Затонувшем городе.', 28153),
(157389, 'ruRU', 'Нашедшие себя в тени его взгляда...', 'Нашедшие себя в тени его взгляда...', 28153),
(157388, 'ruRU', 'Потерянные в ее неумолимых объятиях...', 'Потерянные в ее неумолимых объятиях...', 28153),
(157387, 'ruRU', 'Дыши мудростью утопленников...', 'Дыши мудростью утопленников...', 28153),
(157386, 'ruRU', 'Битва при Лютых холмах продолжается уже много дней. Помоги выжившим и дай им возможность восстановить силы.', '', 28153),
(157383, 'ruRU', 'Это был замечательный фейерверк! Хорошо, что вы с Токи не подорвались.', '', 28153),
(157382, 'ruRU', 'Напейся вволю из сияющей волны...', 'Напейся вволю из сияющей волны...', 28153),
(157381, 'ruRU', 'Торговая компания перекопала весь берег. Найди Токи и попробуй чем-нибудь помочь ему.', '', 28153),
(157380, 'ruRU', 'Уф...', 'Уф...', 28153),
(157379, 'ruRU', 'Вы обнаруживаете зловещий алтарь. Когда вы кладете на него руку, у вас в голове начинают звучать слова.\n\n\"С чего ты начнешь?\"', '', 28153),
(157378, 'ruRU', 'Неплохо! В следующий раз я угощаю!', '', 28153),
(157377, 'ruRU', 'Я запущу в тебя свои когти!', '', 28153),
(157376, 'ruRU', 'Я разорву тебя на части!', '', 28153),
(157375, 'ruRU', 'Пора выгнать братство Стальных Волн из наших земель. Устрой этим пиратам веселую жизнь – может, тогда они сами решат уйти.', '', 28153),
(157374, 'ruRU', 'За Друствар!', '', 28153),
(157373, 'ruRU', 'Вперед! Превратим это чудовище в груду обломков!', '', 28153),
(157372, 'ruRU', '', 'Тортолланы благодарны тебе. И я тоже.', 28153),
(157371, 'ruRU', '', 'Громилы Торговой компании продолжают нападать на тортолланов! Поговори с Токи и помоги беднягам!', 28153),
(157370, 'ruRU', '', 'Теперь наши враги знают, что у Орды есть герои, способные разрушить их планы.', 28153),
(157369, 'ruRU', '', 'Наши враги наглеют с каждым днем! Отними у них ресурсы – и жизнь, если потребуется.', 28153),
(157368, 'ruRU', '', 'Враги стали слабее, а наша сила растет! Большие победы складываются из малых.', 28153),
(157367, 'ruRU', '', 'Впроголодь много не навоюешь. Добудь побольше медвежьего мяса, а если враги будут мешать тебе, убей их.', 28153),
(157362, 'ruRU', 'Ужасное древнее зло возвращается. Будь начеку.', 'Ужасное древнее зло возвращается. Будь начеку.', 28153),
(157361, 'ruRU', 'Кто же знал, что мертвые поднимутся!', 'Никто не думал, что мертвые будут просто так разгуливать при свете дня!', 28153),
(157360, 'ruRU', 'Такой мощи мы не ожидали! Будь настороже.', 'Такой мощи мы не ожидали! Будь настороже.', 28153),
(157359, 'ruRU', 'Големов нужно уничтожить! Пожалуйста, помоги!', 'Големов нужно уничтожить! Пожалуйста, помоги!', 28153),
(157358, 'ruRU', 'Спасибо за помощь, очень вовремя.', 'Спасибо за помощь, очень вовремя.', 28153),
(157357, 'ruRU', '$p, стой. Ты это видишь?', '', 28153),
(157356, 'ruRU', 'Атака отбита, и город снова уцелел. Мы обязаны тебе жизнью.', '', 28153),
(157355, 'ruRU', 'Орда вернулась с подкреплением, чтобы завершить начатое. Останови врагов любой ценой!', '', 28153),
(157354, 'ruRU', 'Спасибо тебе! Голдфилд не из пугливых, но порой даже ему нужна помощь.', '', 28153),
(157353, 'ruRU', 'Ферма Голдфилда подвергается нападениям, и у него кончаются припасы. Помоги ему, чем можешь.', '', 28153),
(157352, 'ruRU', 'То-то! Больше никаких туннелей. Почеши собачкам пузико за меня.', '', 28153),
(157351, 'ruRU', 'Свинобразы расширяют сеть туннелей, подвергая опасности всю долину. Возьми с собой гончих – они помогут тебе взять след.', '', 28153),
(157350, 'ruRU', '$p, пошли.', '', 28153),
(157349, 'ruRU', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t Вы поражены эффектом |cFFFF0000|Hspell:272536|h[Неизбежное уничтожение]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t Вы поражены эффектом |cFFFF0000|Hspell:272536|h[Неизбежное уничтожение]|h|r!', 28153),
(157348, 'ruRU', 'Здесь стоило бы разместить экспозицию антиквариата из королевских запасников. Я...', '', 28153),
(157347, 'ruRU', '', 'Я буду неподалеку.', 28153),
(157346, 'ruRU', 'Шандриса, не привлекай к себе внимания. Держись в тени... если сможешь ее найти.', '', 28153),
(157345, 'ruRU', '', 'Так точно, главнокомандующий! Вперед!', 28153),
(157344, 'ruRU', 'Келси, ты будешь нашими глазами в небе. Докладывай обо всем, что заметишь.', '', 28153),
(157343, 'ruRU', 'Можешь еще раз описать положение дел?', 'Можешь еще раз описать положение дел?', 28153),
(157342, 'ruRU', 'Родители всегда говорили, что у меня слишком буйная фантазия.', '', 28153),
(157341, 'ruRU', 'Представляешь, катались с холмов на тележках! А еще Хоббс очень похоже и смешно изображал тигра!', '', 28153),
(157340, 'ruRU', 'В детстве мы с Хоббсом вечно искали приключений себе на голову.', '', 28153),
(157339, 'ruRU', 'Покажи.', 'Покажи.', 28153),
(157338, 'ruRU', 'Видения помогут нам следить за битвой, $r.', 'Видения помогут нам следить за битвой, $r.', 28153),
(157337, 'ruRU', 'Скоро она озарит флот своим величием, и весь Кул-Тирас склонится перед светом, идущим из глубин.', '', 28153),
(157336, 'ruRU', 'Ты слеп. Дары Матери волн вернули нам былую силу.', '', 28153),
(157335, 'ruRU', 'Падшие души, исполните свой обет. Разбейте ворота!', '', 28153),
(157334, 'ruRU', '', '|TINTERFACE\\ICONS\\INV_TikiMan2_Bloodtroll.blp:20|t Старейшина Ликса начинает применять заклинание |cFFF00000|Hspell:264603|h[Кровавое зеркало]|h|r!', 28153),
(157333, 'ruRU', '', 'Я чую в этой пещере потенциал. Прям вижу там кучу золота.', 28153),
(157332, 'ruRU', 'Короче, я нырнул этой твари прямо в глотку и распорол гадине брюхо изнутри!', 'Короче, я нырнула этой твари прямо в глотку и распорола гадине брюхо изнутри!', 28153),
(157331, 'ruRU', 'Ну ладно, Леска и Грузило помогли чуток. Но все остальное – истинная правда!', 'Ну ладно, Леска и Грузило помогли чуток. Но все остальное – истинная правда!', 28153),
(157330, 'ruRU', 'Мф, мф, мф! Мф-мф!', 'Умф-умф-умф-умф, умф-умф!', 28153),
(157329, 'ruRU', 'Заткнись, Леска. Дай закончить!', 'Заткнись, Леска. Дай закончить!', 28153),
(157328, 'ruRU', '', 'Золота нет, зато рома навалом!', 28153),
(157327, 'ruRU', 'Ага! Моей убойной удочкой!', 'Ага! Моей убойной удочкой!', 28153),
(157326, 'ruRU', 'Ну, я сообразительный, сразу смекнул, как эту тварь завалить.', 'Ну, я сообразительная, сразу смекнула, как эту тварь завалить.', 28153),
(157325, 'ruRU', 'И тут я увидел в море нечто. В жизни не видел ничего подобного!', 'И тут увидела в море нечто. В жизни не видела ничего подобного!', 28153),
(157324, 'ruRU', 'Стою я, значит, первую вахту, высматриваю гадских наг.', 'Стою я, значит, первую вахту, высматриваю гадских наг.', 28153),
(157323, 'ruRU', 'А теперь я расскажу, откуда взялись эти недоумки.', 'Дай-ка я расскажу тебе о моей первой встрече с этими балбесами.', 28153),
(157322, 'ruRU', 'Да уж, согласен... Эй, что ты этим хочешь сказать?', 'Да уж, согласна... Эй, что ты этим хочешь сказать?', 28153),
(157321, 'ruRU', 'Этот шлем давит тебе на мозги. Я скорее поверю, что Леска что-то поймает, чем ты!', 'Этот шлем давит тебе на мозги. Я скорее поверю, что Леска что-то поймает, чем ты!', 28153),
(157320, 'ruRU', 'Мф, мф-мф-мф-мф, мф-мф, мф.', 'Умф, умф-умф-умф-умф. Умф...', 28153),
(157319, 'ruRU', 'МФ!!!', 'Умф!!!', 28153),
(157318, 'ruRU', 'Мф-мф, мф.', 'Мф-мф, мф.', 28153),
(157317, 'ruRU', 'По счастью, я всегда ношу с собой пульку на шнурке, как раз для таких случаев.', 'По счастью, я всегда ношу с собой пульку на шнурке, как раз для таких случаев.', 28153),
(157316, 'ruRU', 'Я сторожу ром до возвращения капитана.', '', 28153),
(157315, 'ruRU', 'Капитан... я ни капли не пил.', '', 28153),
(157314, 'ruRU', '', 'А где пираты, там обычно и золото!', 28153),
(157313, 'ruRU', '', 'Некоторые рабочие говорят, что видели в этой пещере призрак пирата.', 28153),
(157312, 'ruRU', '', 'До Бреннадама недалеко. Вперед!', 28153),
(157311, 'ruRU', '', 'Без флота Кул-Тирас уязвим. Нападение будет лишь вопросом времени.', 28153),
(157310, 'ruRU', '', 'Нужно срочно найти брата Пайка. Надеюсь, он поможет нам вернуть флот домой.', 28153),
(157309, 'ruRU', '', 'Правда, красиво? Неудивительно, что столько людей селится здесь.', 28153),
(157308, 'ruRU', '', 'Это единственная дорога, ведущая в долину. Штормсонги явно что-то затевают.', 28153),
(157307, 'ruRU', '', 'Бреннадам – второй после Боралуса центр торговли во всем Кул-Тирасе.', 28153),
(157306, 'ruRU', 'За работу, ленивые мешки с костями!', 'За работу, ленивые мешки с костями!', 28153),
(157305, 'ruRU', 'Он здесь! Здоровенный, двухголовый!', 'Он сейчас нападет!', 28153),
(157304, 'ruRU', 'Занимайся своими делами. У меня официальная миссия!', 'Занимайся своими делами. У меня официальная миссия!', 28153),
(157303, 'ruRU', 'Что ты здесь делаешь? Надо эвакуироваться!', 'Что ты здесь делаешь? Надо эвакуироваться!', 28153),
(157302, 'ruRU', 'Дубина! Поберегись!', 'Лучше беги, нас больше!', 28153),
(157301, 'ruRU', 'Это твоя вина... мы оба так считаем.', 'Это твоя вина... мы оба так считаем.', 28153),
(157300, 'ruRU', 'Сразись со мной... то есть с нами!', 'Сразись со мной... то есть с нами!', 28153),
(157299, 'ruRU', 'Я возьму на себя правую голову.', 'А он больше, чем я думала.', 28153),
(157298, 'ruRU', 'Изучение', 'Изучение', 28153),
(157296, 'ruRU', 'С возвращением, друзья! А я разучил новую песенку!', '', 28153),
(157294, 'ruRU', 'Убью тебя, а потом растопчу весь город!', 'Убью тебя, а потом растопчу весь город!', 28153),
(157293, 'ruRU', 'Орден Возрождения Шторма поведет флот к победе под флагом Альянса, как и прежде.', '', 28153),
(157292, 'ruRU', '', 'Дом Уэйкрестов на вашей стороне. И на стороне Альянса.', 28153),
(157291, 'ruRU', '', 'Прошу довериться Альянсу, чьи герои спасли нас от самоуничтожения.', 28153),
(157290, 'ruRU', '', 'Я прошу вас довериться моей дочери Джайне – истинному лорду-адмиралу.', 28153),
(157289, 'ruRU', '', 'Кроме того, нам угрожает Орда. Эти дикари хотят нас уничтожить.', 28153),
(157288, 'ruRU', '', 'Раздоры ослабили нас. Враги проникли в самое сердце королевства.', 28153),
(157287, 'ruRU', '', 'Спасибо, что пришли. Это очень важно.', 28153),
(157286, 'ruRU', 'Точно тебе говорю, мы с тобой без труда справимся с этими чудовищами!', '', 28153),
(157285, 'ruRU', 'Когда Дэлин попросил меня уйти из гвардии и заняться воспитанием ребенка из Восточных королевств, я этого не понял. \n\nЗа что мне эта обуза? Почему он лишил меня чести сражаться вместе с ним? Я подумал, что сделал что-то не так и потерял его расположение. \n\nНо с годами понял, что все наоборот. Дэлин хотел, чтобы Телия выросла сильной и благородной – и верил, что я буду хорошим учителем.', '', 28153),
(157284, 'ruRU', '', 'Это правда, что из Штормграда в Стальгорн можно попасть по подземному туннелю?$B$BПросто невероятно! Надеюсь, когда-нибудь я это увижу.', 28153),
(157283, 'ruRU', 'И это одна щепотка! Представьте, что можно наделать, если добыть такого пороха побольше.', '', 28153),
(157282, 'ruRU', '', 'Спасибо. Теперь крестьяне смогут вернуться к своим посевам.', 28153),
(157281, 'ruRU', '', 'На местных фермеров нападает кровожадное чудовище. Надо им помочь!', 28153),
(157280, 'ruRU', '', 'Уверена, они найдут этим припасам достойное применение.', 28153),
(157279, 'ruRU', '', 'Надеюсь, придет тот день, когда жители Кул-Тираса вновь смогут доверять жрецам моря. А до тех пор нам придется самим прокладывать курс.', 28153),
(157278, 'ruRU', '', 'Это даст нам столь необходимую передышку. Спасибо.', 28153),
(157277, 'ruRU', '', 'Жители долины Штормов не забудут твоих подвигов!', 28153),
(157276, 'ruRU', '', 'Эти холмы богаты ресурсами. Помоги ордену Возрождения Шторма пополнить запасы.', 28153),
(157275, 'ruRU', '', 'Подручные Штормсонга снова зашевелились. Нужно остановить их темные ритуалы!', 28153),
(157274, 'ruRU', '', 'Мы теряем позиции! Скорее, отбрось врагов с захваченных земель!', 28153),
(157273, 'ruRU', '', 'Ордену Возрождения Шторма нужны герои. Помоги вернуть мир и покой в долину!', 28153),
(157272, 'ruRU', '', 'Канониры! Приготовиться к последнему залпу!', 28153),
(157271, 'ruRU', '', 'Держите щит! Кораблю и так уже изрядно досталось!', 28153),
(157270, 'ruRU', 'Отрекшиеся. Я не думал... <кашляет> Скажите, госпожа...', '', 28153),
(157269, 'ruRU', '<кашляет> Орда. А я-то думал, что умру спокойно.\n\nТы из Отрекшихся? Как интересно. Но уже слишком поздно.\n\nНу, и чего ты ждешь?', '', 28153),
(157268, 'ruRU', 'Увидимся у повозки, $p!', '', 28153),
(157267, 'ruRU', '', 'Ха-ха! Пора собирать добычу!', 28153),
(157266, 'ruRU', 'Я хочу вернуться.', 'Я хочу вернуться.', 28153),
(157265, 'ruRU', 'Спасибо тебе за помощь. Нам надо возвращаться.', 'Спасибо тебе за помощь. Нам надо возвращаться.', 28153),
(157264, 'ruRU', 'Наблюдать за встречей Зеллинга с семьей.', 'Наблюдать за встречей Зеллинга с семьей.', 28153),
(157263, 'ruRU', 'Как всегда, великолепно. Если все всадники Альянса ездят так же, как ты, я буду рад принять их в своем поместье!', '', 28153),
(157262, 'ruRU', 'Чудесный денек для скачек! Седлай лошадь и езжай на ипподром!', '', 28153),
(157261, 'ruRU', '', 'Как знаешь. Пошли, $n!', 28153),
(157260, 'ruRU', 'Я вернусь на базу. Я знаю, чем это кончится, и не хочу этого видеть.', '', 28153),
(157259, 'ruRU', 'Знай свое место! У меня дело к ведуну, не мешай нам беседовать.', '', 28153),
(157258, 'ruRU', '', 'Это отвадит наг от наших фортов.', 28153),
(157257, 'ruRU', '', 'Даю тебе слово. Идем. $n, возвращайся к Натаносу и скажи ему, что у нас есть все необходимое.', 28153),
(157256, 'ruRU', 'Я пойду с вами... и помогу найти маршала Валентайна. Только пообещайте, что моей семье ничто не будет угрожать.', '', 28153),
(157255, 'ruRU', '', 'Наги снова штурмуют форт! Разберись с ними по-тортоллански!', 28153),
(157254, 'ruRU', '', 'Присоединяйся к Отрекшимся и ищи свой собственный путь. Ты будешь среди тех, кто примет тебя таким, каким ты стал.', 28153),
(157253, 'ruRU', 'И что мне остается? Стать безмозглым слугой Сильваны?', '', 28153),
(157252, 'ruRU', '', 'Чужаки редко удостаиваются этой чести. Давай пройдемся, и ты расскажешь мне об этом Вол\'джине.', 28153),
(157250, 'ruRU', '', 'Я предупреждала, Зеллинг. Превращение меняет. Живые не примут тебя.', 28153),
(157249, 'ruRU', 'Нет... Джулия... Мэттью... Ханна... что я наделал? Во что я превратился?', '', 28153),
(157248, 'ruRU', '', 'Прогони это чудовище!', 28153),
(157247, 'ruRU', '', 'Оставь нас в покое!', 28153),
(157246, 'ruRU', 'Прогони его!', '', 28153),
(157245, 'ruRU', 'Тихо!', '', 28153),
(157244, 'ruRU', '', 'Я не знаю, кто ты такой, но мой муж никогда не обижал ни меня, ни детей. Мы уходим... не иди за нами!', 28153),
(157243, 'ruRU', 'Я... я...', '', 28153),
(157242, 'ruRU', 'Ну все, хватит!', '', 28153),
(157241, 'ruRU', 'Мама, спаси нас!', '', 28153),
(157240, 'ruRU', '', 'Не подпускай его к нам!', 28153),
(157239, 'ruRU', 'Папа вернулся! Прислушайся, это же мой голос! Как ты не понимаешь?!', '', 28153),
(157238, 'ruRU', '', 'Не подходи!', 28153),
(157237, 'ruRU', 'Мама, я боюсь этого монстра!', '', 28153),
(157236, 'ruRU', 'Пойми ты наконец! Это я, твой муж... Дети, я ваш папа!', '', 28153),
(157235, 'ruRU', '', 'В последний раз повторяю, отойди прочь! Ты не мой муж!', 28153),
(157234, 'ruRU', 'Сила не оставляет меня никогда... даже в посмертии.', '', 28153),
(157233, 'ruRU', 'Твоим оружием меня в бою не одолеть!', '', 28153),
(157232, 'ruRU', 'Зеллинг, помоги нам найти тело маршала Валентайна.', 'Зеллинг, помоги нам найти тело маршала Валентайна.', 28153),
(157231, 'ruRU', 'Моя семья за меня... отомстит.', '', 28153),
(157230, 'ruRU', 'Я вымещу на тебе весь свой гнев!', '', 28153),
(157229, 'ruRU', '', '...Ладно, посмотрим, что будет дальше.', 28153),
(157228, 'ruRU', 'Я... Я жив! Ха-ха-ха! Я должен сейчас же пойти к Джулии и детям. Они будут в восторге!', '', 28153),
(157227, 'ruRU', '', 'Не всякий дух настолько... упорен. Мастер Гадрин, отнесите прах этого вождя в Атал\'Дазар. Если его дух достоин, он заслуживает место среди наших величайших королей.', 28153),
(157226, 'ruRU', 'После такого Залазан не вернется. Даже после смерти Вол\'джин помогает нам.', '', 28153),
(157225, 'ruRU', 'И падут мертвые!', '', 28153),
(157224, 'ruRU', 'Подкрепление ждет твоего приказа.', '', 28153),
(157223, 'ruRU', 'Если Орде нужна война, то мы покажем им все, на что способны!', '', 28153),
(157222, 'ruRU', 'Надеюсь, у тебя хорошие новости.', '', 28153),
(157221, 'ruRU', 'Долина Штормов выдержит любую бурю.', '', 28153),
(157220, 'ruRU', 'Спокойного плавания.', '', 28153),
(157219, 'ruRU', 'Слушай голос волн.', '', 28153),
(157218, 'ruRU', 'Здорово! Мы найдем применение и припасам, и поросятам.', '', 28153),
(157217, 'ruRU', 'Свинобразы снова разорили наши склады. Долг платежом красен. Верни наше добро и утащи все, что сочтешь полезным!', '', 28153),
(157216, 'ruRU', 'Сделаем.', '', 28153),
(157215, 'ruRU', '', 'Есть, сэр!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157214, 'ruRU', '', 'Милостивая Элуна, благослови павших.', 28153),
(157213, 'ruRU', 'Телия, обойди посты городской стражи. Вели обращать внимание на необычное оружие нездешнего производства.', '', 28153),
(157212, 'ruRU', '', 'Да будет так. Вол\'джин, сын Сен\'джина, достоин права быть погребенным в наших священных гробницах. Однако в Атал\'Дазар вам придется пробиваться силой. Идите вместе, и даруйте покой праху вашего бывшего вождя.', 28153),
(157211, 'ruRU', '', 'Всегда трудно идти против воли правителей.', 28153),
(157210, 'ruRU', 'Когда стало ясно, что вождь Гаррош ведет Орду по бесчестному пути, Вол\'джин возглавил восстание, чтобы свергнуть его.', '', 28153),
(157209, 'ruRU', '', 'В то время отцу нравилось будущее империи, о котором говорил Зул. Но должна признать, что ваш вождь оказался дальновиднее.', 28153),
(157208, 'ruRU', 'Когда зандалары объединяли все племена, Вол\'джин предпочел мир для своего народа темной силе пророка.', '', 28153),
(157207, 'ruRU', 'Он заключил сделку с Бвонсамди, чтобы победить могучего Залазана.', '', 28153),
(157206, 'ruRU', '', 'Я даже не могу сосчитать огоньки. Столько смертей...', 28153),
(157205, 'ruRU', 'Мы принесли прах Вол\'джина, сына Сен\'джина, чтобы упокоить его в этом священном месте.', '', 28153),
(157204, 'ruRU', 'Флинн, для тебя есть работенка. Нужно выяснить источник этого пороха.', '', 28153),
(157203, 'ruRU', 'В эти земли возвращается древнее зло. Будь начеку.', '', 28153),
(157202, 'ruRU', 'Призыватель ветров, я здесь по приказу Вождя.', 'Призывательница ветров, я здесь по приказу Вождя.', 28153),
(157201, 'ruRU', 'Да, мне нужно в Силитус.', 'Да, мне нужно в Силитус.', 28153),
(157200, 'ruRU', 'Почему я здесь, человек?', 'Почему я здесь, человек?', 28153),
(157199, 'ruRU', '$n, помоги-ка мне провести наглядную демонстрацию для этих скептиков.', '', 28153),
(157198, 'ruRU', 'Но не такое мощное.', '', 28153),
(157197, 'ruRU', 'Это не новость! Они постоянно что-то изобретают.', '', 28153),
(157196, 'ruRU', '', 'Ну, Флинн, о чем ты хотел нам рассказать? У Эшвейнов появился новый порох?', 28153),
(157195, 'ruRU', 'Мне нужен ветрокрыл до укрытия Маршалла, это в кратере Ун\'Горо.', 'Мне нужен ветрокрыл до укрытия Маршалла, это в кратере Ун\'Горо.', 28153),
(157194, 'ruRU', 'С возвращением! Я не решался сказать принцессе, что здесь шастает алмазный дворф и ворует ее героев!', '', 28153),
(157193, 'ruRU', 'Ух, как мы славно потрудились!', '', 28153),
(157192, 'ruRU', 'Нам нужно вернуть груз. Когда я говорю \"нам\", я имею в виду тебя.', '', 28153),
(157191, 'ruRU', 'Надеюсь, что ты скоро вернешься. Принцессе очень нужна твоя помощь!', 'Надеюсь, что ты скоро вернешься. Принцессе очень нужна твоя помощь!', 28153),
(157190, 'ruRU', 'Потрясающе! Это стоит записать!', 'Потрясающе! Это стоит записать!', 28153),
(157189, 'ruRU', 'Защита своих тылов – дело важное. Налеты на вражеские, впрочем, тоже.', '', 28153),
(157188, 'ruRU', 'Обломки корабля Альянса? Всегда добрый знак. Обыщи их на предмет того, что может нам пригодиться.', '', 28153),
(157187, 'ruRU', 'Это было несложно.', '', 28153),
(157186, 'ruRU', 'На экстрактор напали! Защити его!', '', 28153),
(157185, 'ruRU', 'Орде всегда нужны ресурсы. Хвалю.', '', 28153),
(157184, 'ruRU', 'Защищай экстрактор! Нам нужен этот азерит!', '', 28153),
(157183, 'ruRU', 'Какой у тебя план, Шандриса?', 'Какой у тебя план, Шандриса?', 28153),
(157182, 'ruRU', '', '<Шандриса зорко оглядывает горизонт. Она утвердительно кивает вам.>', 28153),
(157181, 'ruRU', 'Найти Солнечного Стража и нашпиговать его стрелами.', '', 28153),
(157180, 'ruRU', 'Мой план?', '', 28153),
(157179, 'ruRU', 'Секретная служба Гномрегана установит бомбы, чтобы выманить Солнечного Стража, а мы нападем на него, пока он будет соображать, что происходит.', '', 28153),
(157178, 'ruRU', '', 'Привет!', 28153),
(157177, 'ruRU', 'Именно! Я собрал команду опытных бойцов с отменными техническими знаниями. Они этим и займутся.', '', 28153),
(157176, 'ruRU', '', 'То есть... подорвать несколько бомб одновременно?', 28153),
(157175, 'ruRU', 'Я хочу нанести по всем их позициям массированные бомбовые удары.', '', 28153),
(157174, 'ruRU', 'Да. Разведка сообщает по меньшей мере о трех раскопках.', '', 28153),
(157173, 'ruRU', '', 'Археологией?', 28153),
(157172, 'ruRU', 'Солнечный Страж – член Реликвария, он явно прибыл сюда для чего-то связанного с археологией.', '', 28153),
(157171, 'ruRU', 'Я... Я не помню. Но так гораздо лучше.', '', 28153),
(157170, 'ruRU', '', 'Извини... Напомни, пожалуйста, кто ты? Это о тебе говорил Малфурион?', 28153),
(157168, 'ruRU', 'Я доставил твою записку Б\'визати.', 'Я доставила твою записку Б\'визати.', 28153),
(157167, 'ruRU', '', 'И даже мирных жителей... не пощадили. Надеюсь, хоть кто-то успел сбежать до того, как...', 28153),
(157166, 'ruRU', '', 'На наших заставах не ожидали нападения. Они пали одна на другой. Всех отравили.', 28153),
(157165, 'ruRU', '', '%s утирает слезу и встает.', 28153),
(157164, 'ruRU', '', 'Мы пытались использовать ловушки. Но Орду они не остановили.', 28153),
(157163, 'ruRU', 'Рад, что у тебя все хорошо $n.\n\nИ у меня все хорошо.\n\nАкунда дал мне новую жизнь.', '', 28153),
(157162, 'ruRU', 'Какой у тебя план, главнокомандующий?', 'Какой у тебя план, главнокомандующий?', 28153),
(157161, 'ruRU', 'В 7-м легионе служат лучшие бойцы Азерота.\n\nЗа Альянс!', '', 28153),
(157160, 'ruRU', 'Кто? Никогда не слышал о тролле с таким именем.', '', 28153),
(157159, 'ruRU', '', 'Столько... столько убитых...', 28153),
(157158, 'ruRU', 'У меня есть кое-что важное, $n. То, что поможет этой земле и ее народу.', '', 28153),
(157157, 'ruRU', 'Дворф... алмазный... в сердце Зулдазара! Ты кто?..', '', 28153),
(157156, 'ruRU', '', 'Мне много всякого довелось повидать в этих лесах, но такое...', 28153),
(157155, 'ruRU', 'Ты чувствуешь? Земля дрожит...', '', 28153),
(157153, 'ruRU', 'Вождь приказала помочь тебе.', 'Вождь приказала помочь тебе.', 28153),
(157152, 'ruRU', 'Мне нужно в Танарис, в Прибамбасск.', 'Мне нужно в Танарис, в Прибамбасск.', 28153),
(157151, 'ruRU', 'Умоляю...', '', 28153),
(157150, 'ruRU', 'Я готов... обречь свою душу... на вечное проклятие... ради счастья моей семьи... пожалуйста! Прошу вас...', '', 28153),
(157149, 'ruRU', '', 'Я задаю себе этот вопрос каждый день, Зеллинг.', 28153),
(157148, 'ruRU', 'Вижу цель.', '', 28153),
(157147, 'ruRU', '', 'Мы все немного сходим с ума, когда становимся Отрекшимися. Кто-то больше, кто-то меньше.', 28153),
(157146, 'ruRU', 'Ты знаешь Акунду?', 'Ты знаешь Акунду?', 28153),
(157145, 'ruRU', 'Позволь Акунде снять тяжелый груз с твоего сердца.', 'Позволь Акунде снять тяжелый груз с твоего сердца.', 28153),
(157144, 'ruRU', 'Акунда дает нам возможность начать все сначала.', 'Акунда дает нам возможность начать все сначала.', 28153),
(157143, 'ruRU', 'Тебе здесь всегда рады.', 'Тебе здесь всегда рады.', 28153),
(157142, 'ruRU', 'В храме этого лоа рады всем.', 'В храме этого лоа рады всем.', 28153),
(157141, 'ruRU', 'Ты знаешь Акунду?', 'Ты знаешь Акунду?', 28153),
(157140, 'ruRU', 'Позволь Акунде снять тяжелый груз с твоего сердца.', 'Позволь Акунде снять тяжелый груз с твоего сердца.', 28153),
(157139, 'ruRU', 'Акунда дает нам возможность начать все сначала.', 'Акунда дает нам возможность начать все сначала.', 28153),
(157138, 'ruRU', 'Тебе здесь всегда рады.', 'Тебе здесь всегда рады.', 28153),
(157137, 'ruRU', 'В храме этого лоа рады всем.', 'В храме этого лоа рады всем.', 28153),
(157136, 'ruRU', 'Я пришел помочь, Нице.', 'Я пришла помочь, Нице.', 28153),
(157135, 'ruRU', 'Теперь кошмар позади.', 'Теперь кошмар позади.', 28153),
(157134, 'ruRU', 'Пушка заряжена! Загоним монстра обратно в пучину!', 'Пушка заряжена! Загоним монстра обратно в пучину!', 28153),
(157133, 'ruRU', 'Пушка готова!', 'Пушка готова!', 28153),
(157132, 'ruRU', 'Дорас, мне нужно в Шестермуть, это в Пылевых топях.', 'Дорас, мне нужно в Шестермуть, это в Пылевых топях.', 28153),
(157131, 'ruRU', 'Пушка готова! Пустим монстра на корм рыбам!', 'Пушка готова! Пустим монстра на корм рыбам!', 28153),
(157130, 'ruRU', 'Нет.... НЕТ!', 'Нет.... НЕТ!', 28153),
(157129, 'ruRU', 'Спасибо вам! А теперь пора подлатать пушку и дать этой твари отпор!', 'Спасибо вам! А теперь пора подлатать пушку и дать этой твари отпор!', 28153),
(157128, 'ruRU', 'Забанджи храпит.', 'Забанджи храпит.', 28153),
(157127, 'ruRU', 'За мной должок! А теперь дайте-ка я починю пушку!', 'За мной должок! А теперь дайте-ка я починю пушку!', 28153),
(157126, 'ruRU', 'Это был сон?', 'Это был сон?', 28153),
(157125, 'ruRU', 'Не дайте этому чудовищу меня сожрать!', 'Не дайте этому чудовищу меня сожрать!', 28153),
(157124, 'ruRU', 'Прожарим их до золотистой корочки!', '', 28153),
(157123, 'ruRU', 'Уберите от меня эту штуку!', 'Уберите от меня эту штуку!', 28153),
(157122, 'ruRU', '$p! Хватай факел и бей все, что движется. Эти поганища недостойны существовать.', '', 28153),
(157121, 'ruRU', 'Это да, рядовой. В этом нечестивом порту огромное множество монстров, которых нужно убить.', '', 28153),
(157120, 'ruRU', 'Помогите!', 'На помощь!', 28153),
(157119, 'ruRU', 'Так и путаницы, кто кого убил, не будет, сэр.', '', 28153),
(157118, 'ruRU', 'Кто ты? Где я?', 'Кто ты? Где я?', 28153),
(157117, 'ruRU', 'Подкрепления ждать не приходится. Если облажаемся, нас никто не спасет.', '', 28153),
(157116, 'ruRU', 'Слушайте сюда, солдаты. Это неофициальное задание.', '', 28153),
(157115, 'ruRU', 'Чего ты ждешь, $p?\n\nВот оружие, а вот враг! Давай в лодку!', 'Чего ты ждешь, $p?\n\nВот оружие, а вот враг! Давай в лодку!', 28153),
(157114, 'ruRU', 'Акунда Уставший храпит.', 'Акунда Уставший храпит.', 28153),
(157113, 'ruRU', 'Мы все... Акунда.', 'Мы все... Акунда.', 28153),
(157112, 'ruRU', 'Еще работа?', '', 28153),
(157111, 'ruRU', 'Понял.', '', 28153),
(157110, 'ruRU', 'Хорошо.', '', 28153),
(157109, 'ruRU', 'Будет сделано.', '', 28153),
(157108, 'ruRU', '', 'Да, сэр.', 28153),
(157107, 'ruRU', 'Ладно. Начнем без нее. Если она не придет в себя в ближайшее время... держи клинки наготове.', '', 28153),
(157106, 'ruRU', '', 'Ей нужно... еще немного времени.', 28153),
(157105, 'ruRU', '', 'А-а-а... а-а...', 28153),
(157104, 'ruRU', 'Стоун, будь любезна, назови нам самого известного героя, похороненного на этом кладбище.', '', 28153),
(157103, 'ruRU', 'Раз уж ты здесь, давай начнем.', '', 28153),
(157102, 'ruRU', 'Сражайтесь за наших братьев и сестер!', 'Сражайтесь за наших братьев и сестер!', 28153),
(157101, 'ruRU', 'Побед будет за Альянсом!', 'Победа будет за Альянсом!', 28153),
(157100, 'ruRU', 'К бою!', 'К бою!', 28153),
(157099, 'ruRU', 'Хорошо, что ты нам помогаешь, $p. Сегодня здесь будет безопасно.', '', 28153),
(157098, 'ruRU', 'Арати принадлежит нам!', 'Арати принадлежит нам!', 28153),
(157097, 'ruRU', 'Смерть Орде!', 'Смерть Орде!', 28153),
(157096, 'ruRU', 'За мной!', 'За мной!', 28153),
(157095, 'ruRU', 'За Альянс!', 'За Альянс!', 28153),
(157094, 'ruRU', 'За мной! Война не ждет!', 'За мной! Война не ждет!', 28153),
(157093, 'ruRU', 'Из-за Орды дикие звери ушли в низину. Помоги охотникам справиться с медведями.', '', 28153),
(157092, 'ruRU', 'Ты! Из-за тебя я убил друга! Тебе конец!', '', 28153),
(157091, 'ruRU', 'Братья и сестры, нас ждет великое предназначение!', '', 28153),
(157090, 'ruRU', 'Спасибо. Жители долины помогут тебе.', 'Я так рада видеть тебя, $n. Я этого не забуду.', 28153),
(157089, 'ruRU', 'Дальше я сам... Будь осторожнее.', 'Как же я рада вас видеть.', 28153),
(157088, 'ruRU', 'Я уж думал, мне конец!', 'Спасибо. Я этого не забуду!', 28153),
(157087, 'ruRU', 'Ха! Эти свинки совсем неплохи! Интересно, им нравятся моллюски на пару?', '', 28153),
(157086, 'ruRU', 'У лабиринта обнаружены оставленные без присмотра кабаны. Можешь оседлать одного из них и отправиться в бой верхом!', '', 28153),
(157085, 'ruRU', 'Отомстите... Таптаф...', '', 28153),
(157084, 'ruRU', '', 'Наконец-то... мои муки окончены...', 28153),
(157083, 'ruRU', '', 'Да... свобода...', 28153),
(157082, 'ruRU', '', 'Это... была ловушка...', 28153),
(157081, 'ruRU', '', 'Хе... охотник... стал добычей...', 28153),
(157080, 'ruRU', '', 'Он придет за всеми нами...', 28153),
(157079, 'ruRU', 'Ваше величество, постойте! У меня есть новые сведения.', '', 28153),
(157078, 'ruRU', '', 'Этого не должно... было... случиться...', 28153),
(157077, 'ruRU', '', 'Очень удобно, когда добыча сама идет в руки!', 28153),
(157076, 'ruRU', '', 'Посмотрите-ка, что попалось в мои в капканы!', 28153),
(157075, 'ruRU', '', 'Мяса в тебе, конечно, маловато, но шкуру я все равно сдеру!', 28153),
(157074, 'ruRU', '', 'Мне обещали все богатства леса!', 28153),
(157073, 'ruRU', '', 'Я выручу за твою шкуру хорошую цену!', 28153),
(157072, 'ruRU', '', 'Еще одна шкура в коллекцию!', 28153),
(157071, 'ruRU', 'Ты... падешь...', '', 28153),
(157070, 'ruRU', 'Я возвращаюсь в землю…', '', 28153),
(157069, 'ruRU', 'Конец... близок...', '', 28153),
(157068, 'ruRU', 'Чего тебе надо?! Кыш! Уходи!', '', 28153),
(157067, 'ruRU', 'Моя душа... сгнила...', '', 28153),
(157066, 'ruRU', 'Пелена пала...', '', 28153),
(157065, 'ruRU', 'Трос поглотит всех нас!', '', 28153),
(157064, 'ruRU', 'Он вещает из пустоты!', '', 28153),
(157063, 'ruRU', 'И отомстим, и сокровища заберем!', '', 28153),
(157062, 'ruRU', 'Эй, $p, хватай факел и за работу!', 'Эй, $p, хватай факел и за работу!', 28153),
(157061, 'ruRU', 'Мы им покажем кракенову мать. Будут у нас рыб кормить в темных глубинах!', '', 28153),
(157060, 'ruRU', 'Так, значит, мы их сожжем?', 'Так, значит, мы их сожжем?', 28153),
(157059, 'ruRU', 'Сегодня наша старая проклятая команда из порта Зем\'лана отправила несколько рейдовых групп, и мы – одна из их целей.', '', 28153),
(157058, 'ruRU', 'С возвращением в море, касатики!', '', 28153),
(157057, 'ruRU', 'Навались!', 'Навались!', 28153),
(157056, 'ruRU', 'Может, если я вспомню это заклинание, мне позволят вернуться? Ну-ка... Та эргси леинад!', '', 28153),
(157055, 'ruRU', 'Таптаф, если ты меня понимаешь, то прости, пожалуйста, за то, что я тебя превратил. Навсегда.', '', 28153),
(157054, 'ruRU', 'Таптаф, может, твое имя сработает? Ну-ка, попробуем. Нолем аси Таптаф!', '', 28153),
(157053, 'ruRU', 'Они гадко поступили, когда изгнали меня, Таптаф. Я им покажу всю свою силу! Только заклинание вспомню...', '', 28153),
(157052, 'ruRU', 'Хм... нет, что-то не то.', '', 28153),
(157051, 'ruRU', 'Будь проклято это заклинание. Ни слова не помню. Как там было, Таптаф? Леинад чего-то там... нос фатсуг?', '', 28153),
(157050, 'ruRU', 'Мне открыли глаза!', '', 28153),
(157049, 'ruRU', 'Твоя кровь напитает лес!', '', 28153),
(157048, 'ruRU', 'Ра-а-а!', '', 28153),
(157047, 'ruRU', 'Прекрасно. Когда-нибудь мы восстановим это святилище.', '', 28153),
(157046, 'ruRU', 'Если не остановить жрецов моря, они осквернят всю воду в окрестностях. Прерви их ритуал.', '', 28153),
(157045, 'ruRU', 'Пусть течение унесет их заблудшие души в тихую гавань.', '', 28153),
(157044, 'ruRU', 'Оборви жизни тех, кто принес в долину темную магию Штормсонга. Нужно остановить их, пока не они не сотворили что-нибудь ужасное.', '', 28153),
(157043, 'ruRU', 'Даже отсюда видно дым! Нужно почаще проводить такие вылазки.', '', 28153),
(157042, 'ruRU', 'Надеюсь, ты не боишься грифонов? У Бернадетты Робельс есть план, как пощипать Орду в крепости Клыка Войны. Найди ее.', '', 28153),
(157041, 'ruRU', '', 'Йо-хо-хо?', 28153),
(157040, 'ruRU', 'Без лоа тебе конец! Добей его!', '', 28153),
(157039, 'ruRU', 'Мерзавец воспользовался силой Резана! Я верну ее!', '', 28153),
(157038, 'ruRU', 'Бойся тех, кто живет в темных пучинах. Созданиям Света не пристало скрываться в тени.', '', 28153),
(157037, 'ruRU', 'Жрецы моря пытаются призвать чудовище, способное сровнять Боралус с землей. Останови их.', '', 28153),
(157036, 'ruRU', '', 'Она сама тебя доставит, куда надо. Вернешься в целости и сохранности.', 28153),
(157035, 'ruRU', '', 'Она готова.', 28153),
(157034, 'ruRU', '', 'Это самый быстрый грифон в долине. А если кто-то говорит иначе, то он бессовестный лгун.', 28153),
(157033, 'ruRU', 'Ты следующий!', 'Ты следующая!', 28153),
(157032, 'ruRU', 'Вы с птицей плохие.', 'Вы с птицей плохие.', 28153),
(157031, 'ruRU', 'Я тоже хочу летать!', 'Я тоже хочу летать!', 28153),
(157030, 'ruRU', 'Ненавижу Альянс.', 'Ненавижу Альянс.', 28153),
(157029, 'ruRU', 'Смотрите! Птичка!', 'Смотрите! Птичка!', 28153),
(157028, 'ruRU', '', 'Реактор пересозидания готов. Пора покончить с чумой Г\'ууна раз и навсегда!', 28153),
(157027, 'ruRU', 'Реактор пересозидания готов. Включите его и вскройте Г\'ууна, как гнойный нарыв!', '', 28153),
(157026, 'ruRU', 'Меня... раздавили?', 'Меня... раздавили?', 28153),
(157025, 'ruRU', 'Жалкая букашка! Я тебя раздавлю!', 'Жалкая букашка! Я тебя раздавлю!', 28153),
(157024, 'ruRU', 'Забери меня отсюда!', 'Забери меня отсюда!', 28153),
(157023, 'ruRU', 'Детеныш дикорога рычит и бежит за своей матерью!', 'Детеныш дикорога рычит и бежит за своей матерью!', 28153),
(157022, 'ruRU', 'Доставь меня туда!', 'Доставь меня туда!', 28153),
(157021, 'ruRU', 'Подбросить тебя?', 'Тебя подбросить?', 28153),
(157020, 'ruRU', '', 'Эверит вас хорошо подготовил. Он бы вами гордился.', 28153),
(157019, 'ruRU', '', 'Благодарю, миледи. Я не подведу.', 28153),
(157018, 'ruRU', '', 'Я присваиваю вам звание маршала и назначаю главой стражи.', 28153),
(157017, 'ruRU', '', 'Но теперь вы нужны Друствару в новом качестве.', 28153),
(157016, 'ruRU', '', 'Инквизитор Клирдоун, вы превзошли все наши ожидания, проявив и храбрость, и сострадание.', 28153),
(157015, 'ruRU', '', 'Все мы познали горечь потерь, но свет надежды все еще сияет.', 28153),
(157014, 'ruRU', 'Ничего личного.', 'Ничего личного.', 28153),
(157013, 'ruRU', 'Круг стихий сейчас под контролем врага... Пока что.', 'Круг стихий сейчас под контролем врага... Пока что.', 28153),
(157012, 'ruRU', 'Вижу знамена Орды в Круге стихий!', 'Вижу знамена Орды в Круге стихий!', 28153),
(157011, 'ruRU', 'Круг стихий под контролем Орды!', 'Круг стихий под контролем Орды!', 28153),
(157010, 'ruRU', 'В Круге стихий наши знамена!', 'В Круге стихий наши знамена!', 28153),
(157009, 'ruRU', 'Круг стихий у нас под контролем.', 'Круг стихий у нас под контролем.', 28153),
(157008, 'ruRU', 'Круг стихий по-прежнему наш.', 'Круг стихий по-прежнему наш.', 28153),
(157007, 'ruRU', 'Новоземье сейчас под знаменами Орды... Пока что.', 'Новоземье сейчас под знаменами Орды... Пока что.', 28153),
(157006, 'ruRU', 'Эти чудовища думают, что Новоземье у них под контролем? Мы им покажем...', 'Эти чудовища думают, что Новоземье у них под контролем? Мы им покажем...', 28153),
(157005, 'ruRU', 'Эти выродки не смогут вечно удерживать Новоземье.', 'Эти выродки не смогут вечно удерживать Новоземье.', 28153),
(157004, 'ruRU', 'Новоземье у нас под контролем.', 'Новоземье у нас под контролем.', 28153),
(157003, 'ruRU', 'Новоземье контролируем мы.', 'Новоземье контролируем мы.', 28153),
(157002, 'ruRU', 'Похоже, Новоземье под нашим контролем. Пусть так будет и дальше.', 'Похоже, Новоземье под нашим контролем. Пусть так будет и дальше.', 28153),
(157001, 'ruRU', 'Лоа королей пал. Нам нужно соблюдать осторожность, если вновь отправимся на охоту.\n\nРастахан тяжело ранен и быстро стареет. Только сила Резана была способна сдерживать Бвонсамди. Я бы поделился с королем моей силой, но не имею права бросать вызов лоа смерти.', '', 28153),
(157000, 'ruRU', 'Да, госпожа?', '', 28153),
(156999, 'ruRU', '', 'Повелительница ящеров Л\'кала с подозрением смотрит на стоящего перед ней гоблина.', 28153),
(156998, 'ruRU', '', 'Кажется, малыш устал от сражений. Здесь он будет в безопасности. Я сама за ним присмотрю.', 28153),
(156996, 'ruRU', 'Детеныш дикорога зевает и закрывает глаза.', 'Детеныш дикорога зевает и закрывает глаза.', 28153),
(156995, 'ruRU', 'Пора уходить!', 'Пора уходить!', 28153),
(156994, 'ruRU', 'Из меня как будто вынули душу.', '', 28153),
(156993, 'ruRU', 'Еле-еле пронесло. Спасибо за помощь!', 'Еле-еле пронесло. Спасибо за помощь!', 28153),
(156992, 'ruRU', 'Спасибо за помощь! Почему-то мои противослизевые шлепанцы работают не так, как надо.', 'Спасибо за помощь! Почему-то мои противослизевые шлепанцы работают не так, как надо.', 28153),
(156991, 'ruRU', 'Большое спасибо! Когда вернусь, тут же подам жалобу. Снабжение этой экспедиции оставляет желать лучшего – преграды, с которыми мы столкнулись, находятся далеко за пределами нашей компетенции.', 'Большое спасибо! Когда вернусь, тут же подам жалобу. Снабжение этой экспедиции оставляет желать лучшего – преграды, с которыми мы столкнулись, находятся далеко за пределами нашей компетенции.', 28153),
(156990, 'ruRU', 'О, после такого я неделю из \"Санитрона\" не вылезу!', 'О, после такого я неделю из \"Санитрона\" не вылезу!', 28153),
(156989, 'ruRU', 'Вот уж действительно – грязное дело! Спасибо тебе!', 'Вот уж действительно – грязное дело! Спасибо тебе!', 28153),
(156988, 'ruRU', 'Да благословит море эту руду и да не отнимет у владельца то, что будет сделано из нее.', 'Да благословит море эту руду и да не отнимет у владельца то, что будет сделано из нее.', 28153),
(156987, 'ruRU', 'Ты можешь благословить эти слитки штормового серебра?', 'Ты можешь благословить эти слитки штормового серебра?', 28153),
(156986, 'ruRU', 'Никто не должен думать, что, став Отрекшимся, можно получить второй шанс на что бы то ни было.', '', 28153),
(156985, 'ruRU', 'Мне не нравятся твои намеки, Зеллинг.', '', 28153),
(156984, 'ruRU', 'Да! Вот она, истинная сила ракообразных!', '', 28153),
(156983, 'ruRU', 'Кажется, у нас тут кто-то бесхребетный. Дошло? Бесхребетный. Как раки! Я победил!', '', 28153),
(156982, 'ruRU', 'Я еще отыграюсь! Это далеко не все, на что способен капитан Гермес со своим трио беспощадных раков!', '', 28153),
(156981, 'ruRU', 'Но как же так?!', '', 28153),
(156980, 'ruRU', 'Наконец-то нашелся достойный противник!', '', 28153),
(156979, 'ruRU', 'Отправиться в долину Штормов.', 'Отправиться в долину Штормов.', 28153),
(156978, 'ruRU', 'Отправиться на Тирагардское поморье.', 'Отправиться на Тирагардское поморье.', 28153),
(156977, 'ruRU', 'Отправиться в Друствар.', 'Отправиться в Друствар.', 28153),
(156976, 'ruRU', '...Что?', '', 28153),
(156974, 'ruRU', 'Какой-то парень в красной рубахе заявил, что \"меня не было в каноне\". Еще бы – я же моряк, а не канонир!', '', 28153),
(156973, 'ruRU', 'Можешь еще раз рассказать о Кул-Тирасе?', 'Можешь еще раз рассказать о Кул-Тирасе?', 28153),
(156972, 'ruRU', 'Мы исправим ошибки прошлого.', '', 28153),
(156971, 'ruRU', '', 'Да, чем могу помочь?', 28153),
(156970, 'ruRU', 'Прекрасно! Планы свинобразов удалось пресечь на корню.', '', 28153),
(156969, 'ruRU', 'Ты тоже слышишь голос моря?', '', 28153),
(156968, 'ruRU', 'Я должен убедиться, что с моей семьей все будет в порядке! <кашляет>', '', 28153),
(156967, 'ruRU', '', 'Я же сказала, не испытывай мое...', 28153),
(156966, 'ruRU', 'Возле лабиринта видели кошмарное растительное чудовище. Наш фермерский голем сможет быстро с ним расправиться.', '', 28153),
(156965, 'ruRU', 'Пусть волны приведут тебя домой.', '', 28153),
(156964, 'ruRU', 'Чем дом Праудмуров может тебе помочь?', '', 28153),
(156963, 'ruRU', 'Отправиться в Зулдазар.', 'Отправиться в Зулдазар.', 28153),
(156962, 'ruRU', 'Отправиться в Назмир.', 'Отправиться в Назмир.', 28153),
(156961, 'ruRU', 'Вместе мы сильнее.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156960, 'ruRU', 'Я сохраню наследие отца.', '', 28153),
(156959, 'ruRU', 'Я много лет собирал в море самых опасных в мире раков-отшельников. Хочешь со мной сразиться или боишься ударить в грязь лицом?', '', 28153),
(156958, 'ruRU', 'Отличная работа. Мы поручим нашим лучшим исследователям приступить к изучению этих записей. Спасибо.', '', 28153),
(156957, 'ruRU', 'Наши боевые маги обнаружили свитки с тортолланскими заклинаниями среди останков. Нужно собрать их, пока Орда о них не прознала. За дело.', '', 28153),
(156956, 'ruRU', 'Альянс отвоевал Стромгард!', 'Альянс отвоевал Стромгард!', 28153),
(156955, 'ruRU', 'Эй, $n! Сюда!', '', 28153),
(156954, 'ruRU', 'Йо-хо-хо, $p. Говорят, ты водишь дружбу со стариком Киро и вульперами.\n\nУ нас нет времени на долгие разговоры, так что слова Киро мне будет вполне достаточно.\n\nЕсли захочешь заняться грабежом на море, в нашей команде тебе всегда рады.\n\nЗапрыгивай в лодку, когда подготовишься, и отчаливаем.', '', 28153),
(156953, 'ruRU', 'Занятно... я передам свиток магам для дальнейшего изучения. Спасибо!', '', 28153),
(156952, 'ruRU', 'Йо-хо-хо, $p! Рад снова видеть тебя.\n\nХочешь заняться грабежом? Зем\'лан рассаживает свою команду по шлюпкам, так что они теперь для нас легкая добыча.... если хорошенько прицелиться, конечно.\n\nЯ уже видел тебя в деле и думаю, ты быстро расправишься с этими мерзкими скелетами.\n\nЗапрыгивай в лодку, когда подготовишься.', '', 28153),
(156951, 'ruRU', 'Я вернусь на \"Искупление ветра\". Поговори с верховным адмиралом, когда захочешь вернуться в Боралус.', '', 28153),
(156950, 'ruRU', 'Я годами искал в море самых беспощадных раков. Хочешь посмотреть, как твои питомцы пойдут ко дну?', '', 28153),
(156949, 'ruRU', '$n! Чем могу помочь?', '', 28153),
(156948, 'ruRU', 'Шта это?', 'Шта это?', 28153),
(156947, 'ruRU', '$n! Рад снова видеть тебя. Много воды утекло с тех пор, как я служил под твоим началом на Дреноре.', '', 28153),
(156946, 'ruRU', 'Култирасцы познают страх!', '', 28153),
(156945, 'ruRU', 'Что... даже...', 'Что... даже...', 28153),
(156944, 'ruRU', 'Ик! Горькое!', 'Ик! Горькое!', 28153),
(156943, 'ruRU', 'По вкусу... как крючки...', 'По вкусу... как крючки...', 28153),
(156942, 'ruRU', 'Кто я?.. врайкул?.. <ик>', 'Кто я?.. врайкул?.. <ик>', 28153),
(156941, 'ruRU', 'Ненавижу... <ик!> светлый эль...', 'Ненавижу... <ик!> светлый эль...', 28153),
(156940, 'ruRU', 'Открой портал и впусти наши войска.', 'Открой портал и впусти наши войска.', 28153),
(156939, 'ruRU', 'Для меня честь служить Орде по ходу обучения телемантии у Окулета. \n\nИ для меня будет честью покинуть это место, как только мы здесь закончим.', '', 28153),
(156938, 'ruRU', 'Мои псы... они... только лают... и не кусают...', 'Мои псы... они... только лают... и не кусают...', 28153),
(156937, 'ruRU', 'Отлично, на ловца и зверь бежит!', 'Отлично, на ловца и зверь бежит!', 28153),
(156936, 'ruRU', 'Наполни амулет силой... и тогда, быть может, мы успеем спасти наш мир.', '', 28153),
(156935, 'ruRU', 'Вы чувствуете вибрацию? Что это?', '', 28153),
(156934, 'ruRU', '', 'Объект исследования: Азерот. Выявлено значительное нарушение биоритма.\n\nПоказатели превышают допустимый предел.\n\nОбновление отчета об инциденте...\n\nОшибка. Ошибка. Ошибка. Ошибка.', 28153),
(156933, 'ruRU', 'Ого! Крепкое!', '', 28153),
(156932, 'ruRU', 'Мм-м... вспомнились времена... когда я был шахтером... Весь фокус был в том, чтобы ударить киркой под нужным углом... это позволяет сохранить... руду...', '', 28153),
(156931, 'ruRU', '', 'Внимание: зарегистрированы множественные нарушения изоляции.\n\nРекомендуется провести очистку следующих объектов:\n\nУльдаман. Ульдум. Ульдорус. Ульдуар. Ульдир. Ульдаз. Ульд... Ульд... Ульд... Ульд...', 28153),
(156930, 'ruRU', 'О... это мне не по вкусу...', '', 28153),
(156929, 'ruRU', 'По моим расчетам наши шансы на успех снизились на две целых пятьсот тридцать девять тысячных в периоде процентов. Нужно ускориться с ремонтом!', 'По моим расчетам наши шансы на успех снизились на две целых пятьсот тридцать девять тысячных в периоде процентов. Нужно ускориться с ремонтом!', 28153),
(156928, 'ruRU', 'Ну же! Отремонтируйте эти танки! Мы уже отстаем от графика!', 'Ну же! Отремонтируйте эти танки! Мы уже отстаем от графика!', 28153),
(156927, 'ruRU', 'Поторопитесь! У нас осталось совсем мало времени, чтобы разместить осадные танки, пока Орда нас не обнаружила.', 'Поторопитесь! У нас осталось совсем мало времени, чтобы разместить осадные танки, пока Орда нас не обнаружила.', 28153),
(156926, 'ruRU', 'Предложить майорский кофе с пенкой', 'Предложить майорский кофе с пенкой', 28153),
(156925, 'ruRU', 'Предложить \"Северное сияние\"', 'Предложить \"Северное сияние\"', 28153),
(156924, 'ruRU', 'Предложить водку из горького черного корня', 'Предложить водку из горького черного корня', 28153),
(156923, 'ruRU', 'Предложить яблочный бренди из Бреннадама', 'Предложить яблочный бренди из Бреннадама', 28153),
(156922, 'ruRU', 'Предложить шнапс из Большого Крюка', 'Предложить шнапс из Большого Крюка', 28153),
(156921, 'ruRU', 'Предложить мед Милденхолла', 'Предложить мед Милденхолла', 28153),
(156920, 'ruRU', 'Предложить светлый эль Белых Кущ', 'Предложить светлый эль Белых Кущ', 28153),
(156919, 'ruRU', 'Предложить кровавое вино братства Чернозубых', 'Предложить кровавое вино братства Чернозубых', 28153),
(156918, 'ruRU', 'Я хочу вернуться в Боралус.', 'Я хочу вернуться в Боралус.', 28153),
(156917, 'ruRU', '', 'Ого! Я тебя не подведу, $n, клянусь!', 28153),
(156916, 'ruRU', '', 'Э-э, прошу прощения? $n? Я здесь!', 28153),
(156915, 'ruRU', 'Ой, тебе что-то нужно?', '', 28153),
(156914, 'ruRU', 'Куда нам направить усилия?', '', 28153),
(156913, 'ruRU', 'Я хочу вернуться в Зулдазар.', 'Я хочу вернуться в Зулдазар.', 28153),
(156912, 'ruRU', '', 'Тебе нужна лодка? Или доставить послание?\n\nИли, может, кинжалом кого ткнуть?', 28153),
(156911, 'ruRU', 'Уха-а-а-ади-и-и... Ты што, не видиш-ш-ш-ш... <икает> Я занят!', '', 28153),
(156910, 'ruRU', '', 'Объект исследования: Азерот.\n\nВНИМАНИЕ: катастрофический сбой системы.\n\nЦелостность планеты составляет...\n\nИдут вычисления...', 28153),
(156909, 'ruRU', 'Этого не было в моих расчетах...', 'Этого не было в моих расчетах...', 28153),
(156908, 'ruRU', 'Согласно моим расчетам твои шансы на успех равны... нулю!', 'Согласно моим расчетам твои шансы на успех равны... нулю!', 28153),
(156907, 'ruRU', '', 'У этого свинобраза было сильное моджо, но тебе он все равно не ровня.', 28153),
(156906, 'ruRU', '', 'Шаман свинобразов подчинил себе саму силу земли! Избавься от него, пока он не помешал нашим планам.', 28153),
(156905, 'ruRU', 'Когда по долине не бродят ожившие камни, спится спокойнее.', '', 28153),
(156904, 'ruRU', 'Дикий маленький терродактиль встревоженно вскрикивает!', 'Дикий маленький терродактиль встревоженно вскрикивает!', 28153),
(156903, 'ruRU', 'Свинобраз-заклинатель призывает целую армию элементалей. Уничтожь и эту армию, и его самого.', '', 28153),
(156902, 'ruRU', 'Спасибо. Я уж думал, что обречен.', 'Спасибо. Я уж думала, что обречена.', 28153),
(156901, 'ruRU', 'Хорошо, что в этом мире еще есть место доброте.', 'Хорошо, что в этом мире еще есть место доброте.', 28153),
(156900, 'ruRU', 'Спасибо! Дальше я сам.', 'Спасибо! Дальше я сама.', 28153),
(156899, 'ruRU', 'Отомсти за тех, кого уже не спасти!', 'Отомсти за тех, кого уже не спасти!', 28153),
(156898, 'ruRU', 'Ты не представляешь, через что нам пришлось пройти...', 'Ты не представляешь, через что нам пришлось пройти...', 28153),
(156897, 'ruRU', 'Я спасен!', 'Я спасена!', 28153),
(156896, 'ruRU', 'Спасибо тебе.', 'Спасибо тебе.', 28153),
(156895, 'ruRU', 'Я у тебя в долгу.', 'Я у тебя в долгу.', 28153),
(156894, 'ruRU', 'Твоей отваге нет равных.', 'Твоей отваге нет равных.', 28153),
(156893, 'ruRU', 'Я не забуду твоей доброты.', 'Я не забуду твоей доброты.', 28153),
(156892, 'ruRU', 'Ты как раз вовремя!', 'Ты как раз вовремя!', 28153),
(156891, 'ruRU', 'Твое сострадание не будет забыто.', 'Твое сострадание не будет забыто.', 28153),
(156890, 'ruRU', 'Я обязан тебе жизнью.', 'Я обязана тебе жизнью.', 28153),
(156889, 'ruRU', 'Мне нужно вернуться в бой.', 'Мне нужно вернуться в бой.', 28153),
(156888, 'ruRU', 'Теперь размешаем до однородной массы!', '', 28153),
(156887, 'ruRU', 'Смешай хорошенько!', '', 28153),
(156886, 'ruRU', 'И наконец – запекаем!', '', 28153),
(156885, 'ruRU', 'А это для аромата!', '', 28153),
(156884, 'ruRU', 'По одному!', '', 28153),
(156883, 'ruRU', 'Наша долина заслуживает спасения.', '', 28153),
(156882, 'ruRU', 'У тебя нет лишних припасов?', 'У тебя нет лишних припасов?', 28153),
(156881, 'ruRU', 'Резана... больше нет. Эта тварь... не лоа.', '', 28153),
(156880, 'ruRU', '$n, стены зала повреждены. Долго они не выстоят!', '', 28153),
(156879, 'ruRU', 'Кул-Тирасу грозит опасность, Магни. Но, видимо, ты явился... по другому поводу.', '', 28153),
(156878, 'ruRU', '', 'Куда же я дела удочку? Готова поклясться, что она только что была здесь...', 28153),
(156877, 'ruRU', '', 'Здесь можно и поохотиться, и порыбачить – надо только знать места.', 28153),
(156876, 'ruRU', '<Ветхие доски трещат и скрипят, когда повозку обдувает ветер.\n\nОдно из колес, похоже, заклинило.>', '', 28153),
(156875, 'ruRU', '<Толкнуть повозку.>', '<Толкнуть повозку.>', 28153),
(156874, 'ruRU', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tВы подошли слишком близко к кораблю Орды. Берегитесь!', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tВы подошли слишком близко к кораблю Орды. Берегитесь!', 28153),
(156873, 'ruRU', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tВы подошли слишком близко к кораблю Альянса. Берегитесь!', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tВы подошли слишком близко к кораблю Альянса. Берегитесь!', 28153),
(156872, 'ruRU', '', 'Стена должна рухнуть, тогда море возвратится.', 28153),
(156871, 'ruRU', '$n... Займись еще чем-нибудь полезным. Я сообщу, когда ты снова понадобишься.', '', 28153),
(156870, 'ruRU', 'Лилиан. Стоун. Идем со мной, поможете найти одного из этих... жрецов моря.', '', 28153),
(156869, 'ruRU', 'Как же мне надоели эти постоянные задержки.', '', 28153),
(156868, 'ruRU', 'Ну, $n, что тебе удалось найти? Давай его сюда.', '', 28153),
(156867, 'ruRU', 'Ладно, нам всем пора за работу. Телепортер доставит тебя к союзникам. Удачи... всем нам.', '', 28153),
(156866, 'ruRU', 'Я продолжу поиски способа залечить раны Азерот. Если ты мне понадобишься, я обращусь к тебе через талисман.', '', 28153),
(156865, 'ruRU', 'Держи амулет близко к сердцу, $n. Он придаст тебе сил в самый темный час.', '', 28153),
(156864, 'ruRU', 'Значит, нам нужен какой-то связанный с ним предмет.', '', 28153),
(156863, 'ruRU', '', 'Пусть твои удары сокрушат стены цитадели.', 28153),
(156862, 'ruRU', '', 'Атакуй стены по сигналу, Сколот.', 28153),
(156861, 'ruRU', '', 'Ты получишь награду за службу.', 28153),
(156860, 'ruRU', '', 'Амалия, расскажи Натаносу о жрецах моря.', 28153),
(156859, 'ruRU', '', 'По предметам... находить... затонувшие корабли...', 28153),
(156858, 'ruRU', '', 'Жрецы... моря... могут...', 28153),
(156857, 'ruRU', '', 'А, это не проблема.', 28153),
(156856, 'ruRU', 'Пропал без вести?! Нам нужно его тело!', '', 28153),
(156855, 'ruRU', '', 'Маршал М. Валентайн... герой Второй войны... пропал без вести в море...', 28153),
(156854, 'ruRU', 'Я хочу вернуться на Тирагардское поморье.', 'Я хочу вернуться на Тирагардское поморье.', 28153),
(156853, 'ruRU', 'Буду ждать тебя с поднятыми парусами.', '', 28153),
(156851, 'ruRU', 'Где тело?!', '', 28153),
(156850, 'ruRU', 'Постой... Что это?', '', 28153),
(156849, 'ruRU', 'Валентайн... Долго же ты от нас бегал.', '', 28153),
(156848, 'ruRU', 'Не будем заставлять Валентайна ждать.', '', 28153),
(156847, 'ruRU', 'Активация \"Саблетрона\"... ой!', '', 28153),
(156846, 'ruRU', 'Что? Мы еще не готовы!', '', 28153),
(156845, 'ruRU', '\"Саблетрона\" не победить!', '', 28153),
(156844, 'ruRU', 'Пять маленьких кошек собираются в одну большую!', '', 28153),
(156843, 'ruRU', 'Ты не защитишь этот корабль от возмездия!', '', 28153),
(156842, 'ruRU', 'Сгинь, порождение тьмы!', '', 28153),
(156841, 'ruRU', 'Волны поглотят твою мерзкую плоть!', '', 28153),
(156840, 'ruRU', '', 'Защити Крапинку!', 28153),
(156839, 'ruRU', '', 'На помощь!', 28153),
(156838, 'ruRU', 'Отправиться в Вол\'дун.', 'Отправиться в Вол\'дун.', 28153),
(156837, 'ruRU', 'Эта тварь все равно будет сниться мне в кошмарах.', '', 28153),
(156836, 'ruRU', 'Это... я не знаю, что это! Убей его!', '', 28153),
(156835, 'ruRU', '|A:Warfront-AllianceWave3:25:23:0:0|aАльянс отправил штурмовой отряд!', '|A:Warfront-AllianceWave3:25:23:0:0|aАльянс отправил штурмовой отряд!', 28153),
(156834, 'ruRU', 'Сетраки выследили повозку Мииры в дюнах. Она – одна-одинешенька, и если сетраки решаться напасть, ей совсем не помешает помощь.', '', 28153),
(156833, 'ruRU', '', 'Как прикажешь, если на то будет воля Темной Госпожи.', 28153),
(156832, 'ruRU', '', 'Воскреси его. Он решил стать Отрекшимся.', 28153),
(156831, 'ruRU', 'Лилиан, мы можем найти других жрецов моря. Ты же знаешь, что семья его не примет.', '', 28153),
(156830, 'ruRU', '', 'Лилиан Восс. Зачем ты призвала меня?', 28153),
(156829, 'ruRU', 'Мелкое неудобство. Докажи, что нашим планам это не помеха.', '', 28153),
(156828, 'ruRU', '\"Желать\" – это слишком громко сказано. Скорее... Я готов это выдержать, лишь бы помочь своей семье.', '', 28153),
(156827, 'ruRU', '', 'Болезненно.', 28153),
(156826, 'ruRU', 'Но часть вас осталась жива, верно ведь?', '', 28153),
(156825, 'ruRU', '', 'Надеюсь, ты проживешь достаточно долго, чтобы помочь нам найти Валентайна.', 28153),
(156824, 'ruRU', 'Вперед!', 'Вперед!', 28153),
(156823, 'ruRU', '', 'Подкрепление Орды можно запросить прямо сейчас. Только скажи.', 28153),
(156822, 'ruRU', 'Хм... Уж постарайся.', '', 28153),
(156821, 'ruRU', '', 'Я верну ее, Натанос. Продолжайте пока без нас.', 28153),
(156820, 'ruRU', '', 'Стой!', 28153),
(156819, 'ruRU', '', 'А-а-а!', 28153),
(156818, 'ruRU', '', 'Я... Я не могу...', 28153),
(156817, 'ruRU', '', 'Хорошее начало. Посмотрим, чем еще ты нам пригодишься.', 28153),
(156816, 'ruRU', 'В Цитадели жрецов расположились войска Альянса и Кул-Тираса. Они ждут подкрепления и сейчас очень уязвимы.', '', 28153),
(156815, 'ruRU', 'Моя семья в безопасности?', '', 28153),
(156814, 'ruRU', '', 'Хорошо. Докажи свою полезность Орде, и тогда мы решим, сколько еще тебе можно прожить.', 28153),
(156813, 'ruRU', 'С ними все в порядке. Помоги нам, и так будет и впредь.', '', 28153),
(156812, 'ruRU', '<кашляет> Я... я сделаю, что смогу, госпожа Восс. Вам нужно найти кого-то или что-то, верно? Посмотрим, что я могу сделать без своей книги...', '', 28153),
(156811, 'ruRU', '', 'Не испытывай мое терпение, или пожалеешь, что твоя болезнь еще не прикончила тебя. Мне нужно знать, на что способна твоя магия, прежде чем заключать с тобой сделку.', 28153),
(156810, 'ruRU', 'Госпожа Восс. Остаются ли с вами в новом существовании болезни, подхваченные при жизни?', '', 28153),
(156809, 'ruRU', '', 'Лилиан Восс. И вопросы здесь задаю я. Ты можешь с помощью своих способностей находить людей? Или предметы?', 28153),
(156808, 'ruRU', 'Отрекшиеся. Возможно, это... <кашляет> знак. Скажите, госпожа...', '', 28153),
(156807, 'ruRU', '', '$n верно говорит. Мы не причиним тебе вреда, если ты нам поможешь – лучше до того, как умрешь.', 28153),
(156806, 'ruRU', 'Темная Госпожа следит за тобой.', '', 28153),
(156805, 'ruRU', 'Мне нужно подкрепление.', 'Мне нужно подкрепление.', 28153),
(156804, 'ruRU', 'Нужно подкрепление? Отдай приказ, и я организую транспорт из Штормграда.', '', 28153),
(156803, 'ruRU', 'У нас мало времени. Что тебе нужно?', '', 28153),
(156802, 'ruRU', 'Тебя сложно убить... Твой враг согласился бы с этим.', '', 28153),
(156801, 'ruRU', 'Не то, чтобы у нас был четкий план, – просто устрани угрозу и постарайся не умереть.', '', 28153),
(156799, 'ruRU', '%s принимается за свежую еду.', '', 28153),
(156798, 'ruRU', '%s с удовольствием уплетает зеленые листья.', '', 28153),
(156797, 'ruRU', '%s зарывается носом в еду.', '', 28153),
(156796, 'ruRU', 'Я раздавлю твой череп!', 'Я раздавлю твой череп!', 28153),
(156795, 'ruRU', 'Кому еще жить надоело?', 'Кому еще жить надоело?', 28153),
(156794, 'ruRU', 'Вперед!', 'Вперед!', 28153),
(156793, 'ruRU', '[КАТ-СЦЕНА] – Появляется Джайна! Ее войска успешно прорываются через стену крепости Лордерона! И, кстати, это было очень круто.', '[КАТ-СЦЕНА] – Появляется Джайна! Ее войска успешно прорываются через стену крепости Лордерона! И, кстати, это было очень круто.', 28153),
(156792, 'ruRU', '[КАТ-СЦЕНА] – Сильвана ждет в тронном зале. Входит Андуин и предлагает ей сдаться. Однако она вместо этого взрывает город. А чего вы ждали?', '[КАТ-СЦЕНА] – Сильвана ждет в тронном зале. Входит Андуин и предлагает ей сдаться. Однако она вместо этого взрывает город. А чего вы ждали?', 28153),
(156791, 'ruRU', '', 'Если бы я смогла убедить их вернуться в Альянс...', 28153),
(156790, 'ruRU', '', 'У култирасцев самый мощный флот на всем Азероте.', 28153),
(156789, 'ruRU', '', 'Это несложно, если он не будет сопротивляться.', 28153),
(156788, 'ruRU', '', 'Вот. Выпей это.', 28153),
(156787, 'ruRU', '', 'Так, Амалия. Секунду...', 28153),
(156786, 'ruRU', 'Я здесь затем, чтобы попросить помощи, а не убивать тебя.', 'Я здесь затем, чтобы попросить помощи, а не убивать тебя.', 28153),
(156785, 'ruRU', '<кашляет> Орда. А я-то думал, хоть помру спокойно. \n\nНу? Чего ты ждешь?', '', 28153),
(156784, 'ruRU', '', 'Эй... $n, я тут, у крошшера.', 28153),
(156783, 'ruRU', 'Нам придется поторопиться, если мы рассчитываем получить помощь этого жреца моря.', '', 28153),
(156782, 'ruRU', '', 'Что бы вы ни сделали, хуже этой болезни все равно быть не может... он ушел на восток, чтобы умереть вдали от детей. Пожалуйста, оставьте нас в покое.', 28153),
(156781, 'ruRU', 'Я всего лишь хочу знать, где твой муж. Тебе и твоей семье никто не причинит вреда.', '', 28153),
(156780, 'ruRU', '', 'Вы из Орды... Пришли, чтобы забрать у меня последнее? Мой муж умирает, у меня не осталось средств к существованию... Пожалуйста, только не трогайте детей.', 28153),
(156779, 'ruRU', 'В этом нет чести. Можно же просто спросить. Мы не воюем с плачущими матерями.', '', 28153),
(156778, 'ruRU', 'Лучше отойти от греха подальше...', '', 28153),
(156777, 'ruRU', 'Дарю вам мирный реконфигулятом!', '', 28153),
(156776, 'ruRU', 'Сейчас устрою песчаную бурю!', '', 28153),
(156775, 'ruRU', 'Только укажите мне цель...', '', 28153),
(156774, 'ruRU', 'Обожаю это дело.', '', 28153),
(156773, 'ruRU', 'Наконец-то чудовище обломало себе зубы.', '', 28153),
(156772, 'ruRU', 'Пес спущен с цепи.', '', 28153),
(156771, 'ruRU', 'Смерть придет незаметно.', '', 28153),
(156770, 'ruRU', 'Реконфигулятора вызывали?', '', 28153),
(156769, 'ruRU', 'Вам это понравится!', '', 28153),
(156768, 'ruRU', '\"АР-8\" на подходе.', '', 28153),
(156767, 'ruRU', 'Держитесь, сейчас тряхнет.', '', 28153),
(156766, 'ruRU', 'Вас понял, вылетаем.', '', 28153),
(156765, 'ruRU', '', 'А-а-ар-р...', 28153),
(156764, 'ruRU', '', 'Чем скорее ты принесешь цветы, тем скорее Амалия сможет нам помочь.', 28153),
(156763, 'ruRU', 'Поговаривают, что черви выползают на поверхность и наводят ужас на местных жителей. Убейте одного из этих чудовищ!', '', 28153),
(156762, 'ruRU', 'Прекрасно сработано. Теперь эти дети будут мечтать стать такими, как ты!', '', 28153),
(156761, 'ruRU', 'Несколько детей сбежали из Мертвецкой Трясины, чтобы стать пиратами... Теперь они в плену у братства Стальных Волн. Спаси малышей!', '', 28153),
(156760, 'ruRU', '', 'Тсс... $n, сюда!', 28153),
(156759, 'ruRU', '', 'Больше это чудище не будет наводить ужас на мой народ. Лоа тобой довольны.', 28153),
(156758, 'ruRU', '', 'Говорят, черви выползают на поверхность и наводят ужас на местных жителей. Надо избавиться от них!', 28153),
(156757, 'ruRU', 'Мне дадут конфеты?', 'Я теперь пират?', 28153),
(156756, 'ruRU', 'Слушай, босс, я знаю, что эту экспедицию оплачиваешь ты, но Галливикс захочет убедиться, что Темная Госпожа получила свою долю.', '', 28153),
(156755, 'ruRU', 'Мне нужно добраться до кладбища на холме.', 'Мне нужно добраться до кладбища на холме.', 28153),
(156754, 'ruRU', '', 'Мои ракеты – самые безопасные во всем Кул-Тирасе!$b$bПусть моя фамилия не вводит тебя в заблуждение.', 28153),
(156753, 'ruRU', 'Отступайте. Мы еще повоюем.', '', 28153),
(156752, 'ruRU', 'Зандалары, перестроиться! Враги должны умереть здесь и сейчас.', '', 28153),
(156751, 'ruRU', 'Убить чужаков!', '', 28153),
(156750, 'ruRU', 'Вы слабы.', '', 28153),
(156749, 'ruRU', 'Ваша смерть близка.', '', 28153),
(156748, 'ruRU', 'Я злобный пират Бьюфорд! Я никого не оставляю в живых!', 'Кажется, это моя кошка!', 28153),
(156747, 'ruRU', 'Покончим с этим. Становись в центр шторма.', '', 28153),
(156746, 'ruRU', 'Ты не пират!', 'Они сказали, что дадут мне шляпу!', 28153),
(156745, 'ruRU', 'А-а-а! Дайте мне рома!', 'Мне нужно на палубу юта!', 28153),
(156744, 'ruRU', '', 'Хорошо, пусть твои руки остаются чистыми.', 28153),
(156743, 'ruRU', 'Я хочу вернуться в Зулдазар.', 'Я хочу вернуться в Зулдазар.', 28153),
(156742, 'ruRU', 'Подниму паруса заранее, чтобы можно было убраться отсюда как можно скорее. Иди же, добудь азерит!', '', 28153),
(156741, 'ruRU', '', '$n, я позабочусь о теле. А ты возвращайся к Натаносу и скажи, что все идет по плану.', 28153),
(156740, 'ruRU', 'Я не хочу участвовать в обращении этого человека в Отрекшегося. Ты займись этим.', 'Я не хочу участвовать в обращении этого человека в Отрекшегося. Ты займись этим.', 28153),
(156739, 'ruRU', '', 'Ты приспособишься. Я помогу тебе.', 28153),
(156738, 'ruRU', 'Не надо меня спасать!', 'Я теперь пират. И не буду тебя слушать.', 28153),
(156737, 'ruRU', '', 'Ты теперь одна из нас. Люди никогда не примут тебя.', 28153),
(156736, 'ruRU', 'Лилиан, убей Зеллинга.', 'Лилиан, убей Зеллинга.', 28153),
(156735, 'ruRU', '', 'Стоун, я понимаю, каково это. Не дай этой перемене свести тебя с ума, как это когда-то случилось со мной.', 28153),
(156734, 'ruRU', 'Нечестно! Я хотел стать пиратом.', 'Меня продали пиратам!', 28153),
(156733, 'ruRU', 'Лилиан, сделай с Зеллингом то, что нужно сделать.', 'Лилиан, сделай с Зеллингом то, что нужно сделать.', 28153),
(156732, 'ruRU', '', 'Посмотрим. Может, на этот раз все пойдет по-другому.', 28153),
(156731, 'ruRU', '', 'Это ужасно. Даже те, кто не будет тебя сторониться, уже не станут относиться к тебе, как прежде. Ты будешь смотреть в зеркало и видеть там лишь монстра, понимая, что это не ты.', 28153),
(156730, 'ruRU', 'Умоляю... мне нужно... заботиться... о семье... что бы ни случилось.', '', 28153),
(156729, 'ruRU', '', 'Если ты станешь одним из нас, тебя будут сторониться. Ты будешь смотреть в зеркало и видеть там монстра.', 28153),
(156728, 'ruRU', 'Госпожа Восс... <кашляет> прошу... воскресите меня... Я должен помочь семье... я на что угодно готов... на что угодно...', '', 28153),
(156727, 'ruRU', '', 'Что? Не говори глупостей, твоя семья будет считать тебя чудовищем!', 28153),
(156726, 'ruRU', '', 'Ладно. Я все равно собиралась кое-что узнать.', 28153),
(156725, 'ruRU', '<хрипит> Простите. Не могу... во мне... ничего не осталось...', '', 28153),
(156724, 'ruRU', '', 'Зеллинг! Проклятье! Ты нужен нам живым!', 28153),
(156723, 'ruRU', 'Да! Вечная жизнь, наконец-то! Я готов получить этот дар!', '', 28153),
(156722, 'ruRU', '', 'Так, Зеллинг. Ты точно понимаешь, что сейчас произойдет?', 28153),
(156721, 'ruRU', 'Чудесно. Пусть знают, как мы решаем проблемы в нашей долине.', '', 28153),
(156720, 'ruRU', 'Разведчики сообщают о новой угрозе в этих местах. Расправься с ней, пока это не стало проблемой.', '', 28153),
(156719, 'ruRU', 'Удачи, Джайна. Да хранит вас Свет.', '', 28153),
(156718, 'ruRU', '', 'Я вернусь с флотом... или не вернусь вовсе.', 28153),
(156717, 'ruRU', 'Но будет трудно... и опасно.', '', 28153),
(156716, 'ruRU', 'Согласен... Это по силам только вам.', '', 28153),
(156715, 'ruRU', '', 'Значит, именно я должна все исправить и восстановить союз.', 28153),
(156714, 'ruRU', 'Джайна, они вышли из Альянса из-за тебя.', '', 28153),
(156713, 'ruRU', '', 'Нам нужны новые союзники.', 28153),
(156710, 'ruRU', '', 'Вспомни... покажи нам, что случилось...', 28153),
(156709, 'ruRU', 'Если Орда объединится с зандаларами, мы не сможем противостоять ей.', '', 28153),
(156708, 'ruRU', 'Не может быть. Это все фокусы Сильваны. Наверное...', '', 28153),
(156707, 'ruRU', 'И огромном зандаларском флоте.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156706, 'ruRU', 'Выжившие говорят о \"страшной, невиданной магии\".', '', 28153),
(156705, 'ruRU', 'Вернулся только один.', '', 28153),
(156704, 'ruRU', 'Я знаю. Мы послали за ними восемь кораблей.', '', 28153),
(156703, 'ruRU', 'Принцессу и пророка.', '', 28153),
(156702, 'ruRU', 'Не так давно агенты Орды проникли в тюрьму Штормграда и освободили двух зандаларов.', '', 28153),
(156701, 'ruRU', 'Джайна, вы сможете заглянуть в память этого бедняги?', '', 28153),
(156700, 'ruRU', 'В этих местах погибло немало путешественников. Уничтожь монстра, который за всем этим стоит.', '', 28153),
(156699, 'ruRU', 'Все в сборе. Что вы хотели нам сообщить, Матиас?', '', 28153),
(156698, 'ruRU', 'Великолепно. Я знал, что ты сможешь нас защитить.', '', 28153),
(156697, 'ruRU', 'Теперь хочу себе воздушный корабль. Назову его именем сына!', '', 28153),
(156696, 'ruRU', 'Эту лодку я сам украл! Назвал \"Фортуна Малы\"... В честь дочки!', '', 28153),
(156695, 'ruRU', 'Раз уж придется иметь дело с пиратами, нужен настоящий пиратский корабль!', '', 28153),
(156694, 'ruRU', 'Наги что-то замышляют!', '', 28153),
(156693, 'ruRU', 'Да... вечность!..', '', 28153),
(156692, 'ruRU', 'Как подготовишься, используй веревку. С удовольствием покажу тебе свою лодку!', '', 28153),
(156691, 'ruRU', '', 'Кто будет жаловаться, тот труп!', 28153),
(156690, 'ruRU', '', 'Работайте быстрее, псы шелудивые!', 28153),
(156689, 'ruRU', '', 'Меньше слов, больше дела! Азерит сам себя не добудет!', 28153),
(156688, 'ruRU', '', 'И вы называете это работой? Вам повезло, что мы вам за это не платим!', 28153),
(156687, 'ruRU', '', 'А ну за работу, псы! И не халтурить!', 28153),
(156686, 'ruRU', 'Прошу, убейте меня! Подарите мне вечность, сделайте Отрекшимся!', '', 28153),
(156685, 'ruRU', 'Я знаю, что ты воруешь у корпорации. Я позабочусь, чтобы этого не повторилось...', 'Я знаю, что ты воруешь у корпорации. Я позабочусь, чтобы этого не повторилось...', 28153),
(156684, 'ruRU', 'Хочешь, чтобы тебя побили? Не лезь не в свое дело!', 'Хочешь, чтобы тебя побили? Не лезь не в свое дело!', 28153),
(156683, 'ruRU', 'Давай проходи. Здесь не на что смотреть.', 'Давай проходи. Здесь не на что смотреть.', 28153),
(156682, 'ruRU', 'Чего пялишься?', 'Чего пялишься?', 28153),
(156681, 'ruRU', '<кашляет> Госпожа Восс, как вы стали Отрекшейся?', '', 28153),
(156680, 'ruRU', 'Ордынские ворюги крадут азерит у корпорации Эшвейнов. Задай им урок и добудь ресурсы для 7-го легиона.', '', 28153),
(156679, 'ruRU', 'Я воровал, чтобы заполнить пустоту в сердце, ведь оно никогда не знало любви!', 'Я воровала, чтобы заполнить пустоту в сердце, ведь оно никогда не знало любви!', 28153),
(156678, 'ruRU', 'Я это сделал из-за плохого воспитания!', 'Я это сделала из-за плохого воспитания!', 28153),
(156677, 'ruRU', 'Я больше не буду, обещаю!', 'Я больше не буду, обещаю!', 28153),
(156676, 'ruRU', 'Этот проклятый Харрингтон позвал на помощь громилу!', 'Этот проклятый Харрингтон позвал на помощь громилу!', 28153),
(156675, 'ruRU', 'Я завязал с воровством! Хватит!', 'Я завязала с воровством! Хватит!', 28153),
(156674, 'ruRU', 'Прошу, не убивай меня! Я больше не буду воровать!', 'Прошу, не убивай меня! Я больше не буду воровать!', 28153),
(156673, 'ruRU', 'Зулдазарские изгои захватили наших солдат и требуют выкуп. С такими переговоров не ведут. Покажи им мощь Альянса!', '', 28153),
(156672, 'ruRU', 'Вижу, задача оказалась несложной.', '', 28153),
(156671, 'ruRU', 'Разведчики сообщили, что в дюнах стоит небольшой лагерь Орды. Если ударить быстро, враг даже не успеет опомниться.', '', 28153),
(156670, 'ruRU', 'С тобой было очень приятно иметь дело. Если когда-нибудь захочешь стать пиратом, присоединяйся к моей команде!', '', 28153),
(156669, 'ruRU', '$c, я человек слова. Можешь забрать сундук капитана!', '', 28153),
(156668, 'ruRU', 'Встретимся на капитанском дворе, когда Хартфорд будет мертв. Насчет сундука не беспокойся: все, что в нем, достанется тебе.', '', 28153),
(156667, 'ruRU', '', 'Мы еще не закончили. Твоя информация оказалась полезной, но мы должны проверить, насколько ты могущественен.', 28153),
(156666, 'ruRU', 'Пожалуйста! Вам удалось разорить Цитадель жрецов, наверняка этого достаточно! Сделай меня Отрекшимся!', '', 28153),
(156665, 'ruRU', '', 'Неужели мы... зря... поддержали Альянс?', 28153),
(156664, 'ruRU', '', 'Орда не сломит дух Кул-Тираса!', 28153),
(156663, 'ruRU', 'Книгу надо... выбросить... в море...', '', 28153),
(156662, 'ruRU', 'Ты не получишь эту книгу! Она слишком опасна!', '', 28153),
(156661, 'ruRU', '', 'Ты не доживешь до следующего приступа своего жалкого кашля, Зеллинг. Хочешь проверить?', 28153),
(156660, 'ruRU', '<хрипит> Вы не боитесь, что я нападу на вас? Или сбегу?', '', 28153),
(156659, 'ruRU', 'Капитан Стоун сошла с ума после превращения? Я в курсе того, что с ней произошло.', '', 28153),
(156658, 'ruRU', '', 'Превращение в Отрекшегося – процесс непредсказуемый. Твое тело и разум точно претерпят изменения, но до какой степени... Это невозможно предсказать заранее. Как и то, насколько ты справишься с этими изменениями.', 28153),
(156657, 'ruRU', 'Нет, но... вы можете ответить на мой вопрос? Когда человек становится Отрекшимся, он исцеляется от всех болезней?', '', 28153),
(156656, 'ruRU', 'С тобой я на шаг ближе к тому, чтобы вырваться из этой проклятой пустыни!', '', 28153),
(156655, 'ruRU', 'Когда все сделаешь, найди меня в гавани Красных Скал.', '', 28153),
(156654, 'ruRU', 'Довольно... изобретательно.', '', 28153),
(156653, 'ruRU', 'Наши союзники не справятся с заданием, пока в руинах бродят ордынцы. У клана Черного Железа есть план, как их разогнать.', '', 28153),
(156652, 'ruRU', '2 минуты до начала битвы за Стромгард.', '', 28153),
(156651, 'ruRU', 'Кажется, моя стильная шляпа где-то слетела.', 'Кажется, моя стильная шляпа где-то слетела.', 28153),
(156650, 'ruRU', 'Мы хотим отправиться в долину Штормов.', 'Мы хотим отправиться в долину Штормов.', 28153),
(156649, 'ruRU', 'Ну-ка, посмотрим, что здесь есть полезного...', '', 28153),
(156648, 'ruRU', 'Это развалины затонувшего храма. Правда, в них полно наг, от которых неплохо бы избавиться. Желаю удачи.', '', 28153),
(156647, 'ruRU', 'Я готов к переговорам, Ту\'джин.', 'Я готова к переговорам, Ту\'джин.', 28153),
(156646, 'ruRU', 'Скажи, когда можно будет идти дальше, босс.', '', 28153),
(156645, 'ruRU', 'Прекрасная работа. Угрозу нужно пресекать в зародыше.', '', 28153),
(156644, 'ruRU', 'Сообщают, что местные мурлоки расплодились сверх меры. Разберись с ними, пока они не напали на нас.', '', 28153),
(156643, 'ruRU', '', 'Лоа улыбаются, глядя на твои подвиги.', 28153),
(156642, 'ruRU', '', 'Торговая компания испоганила земли наших союзников... Лоа недовольны. Избавься от гоблинов и прибери за ними.', 28153),
(156641, 'ruRU', '', 'Спасибо! Тортолланы не забудут, кто спас их от ужасной судьбы.', 28153),
(156640, 'ruRU', '', 'Мне сообщили, что наги зачем-то угоняют тортолланов в рабство. Нужно прекратить это бесчинство! Убей наг и освободи пленников!', 28153),
(156639, 'ruRU', 'Жрецы моря издавна направляли души к морю... но не так.', '', 28153),
(156637, 'ruRU', 'Спасибо! Надеюсь, тортолланы запомнят, кто им помог.', '', 28153),
(156636, 'ruRU', 'Я готов отплыть в Лордерон.', 'Я готова отплыть в Лордерон.', 28153),
(156635, 'ruRU', 'Торговая компания превратила берег в помойку. Давай поможем тортолланам и уберемся здесь.', '', 28153),
(156634, 'ruRU', '', 'Школа закрыта... навсегда...', 28153),
(156633, 'ruRU', '', 'Я преподам тебе урок!', 28153),
(156632, 'ruRU', 'Спасибо. Боюсь даже представить, зачем нагам понадобились рабы-тортолланы.', '', 28153),
(156631, 'ruRU', 'Мне доложили, что наги захватывают тортолланов в плен. Что бы они ни задумали, мы должны их остановить!', '', 28153),
(156630, 'ruRU', '', 'Ты дерешься, как деревенщина!', 28153),
(156629, 'ruRU', 'Потрясающе, $p! Мы еще на шаг ближе к победе!', '', 28153),
(156628, 'ruRU', 'Вот теперь гадюк станет поменьше. Спасибо.', '', 28153),
(156627, 'ruRU', 'Пернатые змеи всегда были агрессивны, но сейчас их стало слишком много! Разбей их яйца, пора сокращать поголовье.', '', 28153),
(156626, 'ruRU', 'Неплохо. Наши раненые будут очень тебе благодарны.', '', 28153),
(156625, 'ruRU', 'Слюна местных терродактилей обладает лечебными свойствами. Набери побольше слюнных желез для наших лекарей.', '', 28153),
(156624, 'ruRU', 'Неудивительно, что равазавры могут сожрать что угодно! Спасибо тебе за помощь.', '', 28153),
(156623, 'ruRU', 'Нам нужны прочные материалы. Желудки равазавров выдерживают огромную нагрузку. Собери несколько штук.', '', 28153),
(156622, 'ruRU', 'Ар-р-р... Чтоб тебя... рыбы съели...', '', 28153),
(156621, 'ruRU', 'Это что... бунт?! Получай, свинья!', '', 28153),
(156620, 'ruRU', 'За Орду!', 'За Орду!', 28153),
(156619, 'ruRU', '', 'Мои исследования завершены... во всяком случае, пока. Спасибо за помощь.', 28153),
(156618, 'ruRU', '', 'Теперь Орда будет знать, как лезть не в свои дела! Эта магия не должна попасть к ним в руки...', 28153),
(156617, 'ruRU', '', 'Большое спасибо за помощь. Эта преграда очень прочная...', 28153),
(156616, 'ruRU', 'Я в шаге от бессмертия! Поскорее бы стать Отрекшимся! Столько новых возможностей! \n\nКогда у тебя будет время, расскажи, каково это – быть нежитью. Когда целая вечность и весь мир в твоем распоряжении!', '', 28153),
(156615, 'ruRU', 'Моя жизнь не может закончиться вот так... от какой-то болезни. Я должен жить и заботиться о своей семье.', '', 28153),
(156614, 'ruRU', 'Не нарушай покой мертвецов, |3-6($r).', '', 28153),
(156613, 'ruRU', '', 'Мне бы не помешала помощь!', 28153),
(156612, 'ruRU', 'Если ты не движешься вперед, ты отстаешь. Вот мой девиз!', '', 28153),
(156611, 'ruRU', '', 'Мне надо провести кое-какие испытания и собрать данные. Проследи, чтобы мне никто не мешал.', 28153),
(156610, 'ruRU', '', 'Может, мы сумеем использовать эту магию или даже воспроизвести ее.', 28153),
(156609, 'ruRU', '', 'Здесь присутствует удивительная магия! Впервые вижу нечто подобное.', 28153),
(156608, 'ruRU', '', 'Мы еще встретимся!', 28153),
(156607, 'ruRU', 'Но стоит ли тратить на это время?', '', 28153),
(156606, 'ruRU', 'Мне нужна новая маскировка.', 'Мне нужна новая маскировка.', 28153),
(156605, 'ruRU', 'Орда здесь, бежим! Неужели от них нигде нельзя укрыться?', 'Орда здесь, бежим! Неужели от них нигде нельзя укрыться?', 28153),
(156604, 'ruRU', 'Отлично, из-за Альянса у нас новые проблемы с Ордой!', 'Отлично, из-за Альянса у нас новые проблемы с Ордой!', 28153),
(156603, 'ruRU', 'Я не буду рисковать своей жизнью, если Орда уже здесь!', 'Я не буду рисковать своей жизнью, если Орда уже здесь!', 28153),
(156602, 'ruRU', 'Бежим! Вот что бывает, когда помогаешь Альянсу!', 'Бежим! Вот что бывает, когда помогаешь Альянсу!', 28153),
(156601, 'ruRU', 'Я думал, Орда нам не угрожает!', 'Я думала, Орда нам не угрожает!', 28153),
(156600, 'ruRU', 'Откуда здесь Орда?!', 'Откуда здесь Орда?!', 28153),
(156599, 'ruRU', 'Орда... бежим!', 'Орда... бежим!', 28153),
(156598, 'ruRU', 'Это такая проверка, я говорю разные вещи.', '', 28153),
(156597, 'ruRU', '', 'Прощай, Натанос.', 28153),
(156596, 'ruRU', '', '<Сильвана собирается уходить, но останавливается и бросает взгляд через плечо.>', 28153),
(156595, 'ruRU', 'Непременно. Попутного вам ветра.', '', 28153),
(156594, 'ruRU', '', 'Работайте. Я буду ждать от вас подробных отчетов.', 28153),
(156593, 'ruRU', 'Как прикажете, вождь.', '', 28153),
(156592, 'ruRU', '', 'Посоветуйтесь и выберите, откуда начать наступление.', 28153),
(156591, 'ruRU', 'Да, госпожа. \"Вой банши\" готов к отплытию по вашему приказу.', '', 28153),
(156590, 'ruRU', '', 'Все под контролем?', 28153),
(156589, 'ruRU', '<Натанос низко кланяется.>', '', 28153),
(156588, 'ruRU', 'Королева.', '', 28153),
(156587, 'ruRU', '$n, Темная Госпожа начинает кампанию на берегах Кул-Тираса. Мы ждем тебя на борту \"Воя банши\". Поторопись.', '', 28153),
(156586, 'ruRU', '', 'За мной.', 28153),
(156585, 'ruRU', '', 'Приступим.', 28153),
(156584, 'ruRU', 'Командовать этим отрядом будет Гарона. Твоя задача - помогать ей всеми силами.', '', 28153),
(156583, 'ruRU', 'Мы собрали элитный отряд для особого задания Темной Госпожи.', '', 28153),
(156582, 'ruRU', 'Прекрасная работа, $p.', '', 28153),
(156581, 'ruRU', 'Орда отправила отряд, чтобы напасть на наших геологов, работающих неподалеку. Сорви эту атаку.', '', 28153),
(156580, 'ruRU', '', 'Думаю, я смогу это устроить, Зеллинг, но только если ты докажешь свою ценность для Орды.', 28153),
(156579, 'ruRU', 'Я – Томас Зеллинг, жрец моря. Просвещенный жрец моря! Я сделаю все, что ты скажешь, даже помогу вам атаковать местный гарнизон Альянса, только, пожалуйста, сделай меня Отрекшимся!', '', 28153),
(156578, 'ruRU', 'Груз прибыл в целости и сохранности. На базе вас ждет награда.', '', 28153),
(156577, 'ruRU', '', 'Кто ты такой? Почему ты думаешь, что заслужил этот дар?', 28153),
(156576, 'ruRU', 'Наконец-то! Отрекшиеся! Пожалуйста, убей меня, сделай меня Отрекшимся... подари мне бессмертие!', '', 28153),
(156575, 'ruRU', '', 'Так... я могла бы надавить на женщину. Пригрозить ей... вдруг она что-нибудь расскажет.', 28153),
(156574, 'ruRU', 'Бездна, стихии <кашляет>... неужели ничто не избавит меня от этой проклятой болезни? Почему все должно закончиться вот так?', '', 28153),
(156573, 'ruRU', 'Хм, жрец моря был тут недавно. Я видел, как он оберегал и защищал свою семью.', '', 28153),
(156572, 'ruRU', 'Ты знаешь, где искать жреца моря?', 'Ты знаешь, где искать жреца моря?', 28153),
(156571, 'ruRU', 'Мы заметили на поле боя обозы Орды. Это хороший шанс... пополнить наши запасы. Балинда ищет добровольцев.', '', 28153),
(156570, 'ruRU', 'У рудника замечены разведчики Орды. Найдите Гинни в мастерской и узнайте, в чем там дело.', '', 28153),
(156569, 'ruRU', 'У нас заканчиваются припасы. Узнайте у Гинни в мастерской, что нам нужно.', '', 28153),
(156568, 'ruRU', 'Огромные деньги. Новые земли, которые можно грабить... $B$BМы живем в удивительное время!', '', 28153),
(156567, 'ruRU', 'Нет. Не интересуют.', '', 28153),
(156566, 'ruRU', 'Миша, останься здесь. Мы выследим этого жреца моря, и Лилиан сделает... то, что вы собирались сделать.', '', 28153),
(156565, 'ruRU', '', 'Подробности тебя не интересуют, Рексар?', 28153),
(156564, 'ruRU', 'Я готов отправиться в Подгород.', 'Я готова отправиться в Подгород.', 28153),
(156563, 'ruRU', '', 'Похоронного Звона... больше нет. Я доставлю тебя в квартал магов на встречу с верховным воеводой, когда захочешь.', 28153),
(156562, 'ruRU', '', 'Герои, ваш час настал! На рассвете Альянс пойдет штурмом на крепость Лордерона – и падет от наших клинков.', 28153),
(156560, 'ruRU', 'Герои Альянса! Наконец пришла пора вернуть то, что является нашим по праву! На рассвете начнется штурм крепости Лордерона. Орда и ее вождь ответят за свои преступления!', '', 28153),
(156559, 'ruRU', '', 'Твои друзья-ночнорожденные ждут тебя в зале Древних Путей. Когда освободишься, найди меня.', 28153),
(156558, 'ruRU', '', 'В королевской сокровищнице отец хранит свои богатства.', 28153),
(156557, 'ruRU', '', 'Говорят, Великая Печать древнее самой империи Зандалари. Мало что сохранилось с тех пор.', 28153),
(156556, 'ruRU', '', 'Идем, я покажу тебе дворец.', 28153),
(156555, 'ruRU', 'Лучше иди туда ты.', '', 28153),
(156554, 'ruRU', 'Я уже и забыл, сколько дней провел в этой клетке. Впрочем, какая разница?', '', 28153),
(156553, 'ruRU', 'Я Сэм. Сэм Уильямс. Хорошо, что теперь и на нашей стороне есть кто-то с оружием.', '', 28153),
(156552, 'ruRU', 'Эти пираты – подлые проклятые твари. Убивай их без пощады.', 'Эти пираты – подлые проклятые твари. Убивай их без пощады.', 28153),
(156551, 'ruRU', 'Во что мы ввязались?..', 'Во что мы ввязались?..', 28153),
(156550, 'ruRU', 'Я вам еще покажу, монстры!', 'Я вам еще покажу, монстры!', 28153),
(156549, 'ruRU', 'Я убил не меньше дюжины этих мерзких тварей, пока они меня не одолели!', 'Я убила не меньше дюжины этих мерзких тварей, пока они меня не одолели!', 28153),
(156548, 'ruRU', 'За Альянс!', 'За Альянс!', 28153),
(156547, 'ruRU', 'Мы никого не бросим!', 'Мы никого не бросим!', 28153),
(156546, 'ruRU', 'Я знал, что Змеевержец нас тут не бросит!', 'Я знала, что Змеевержец нас тут не бросит!', 28153),
(156545, 'ruRU', 'Когда вернемся на корабль, с меня выпивка.', 'Когда вернемся на корабль, с меня выпивка.', 28153),
(156544, 'ruRU', 'Сколько же они способны сожрать...', '', 28153),
(156543, 'ruRU', 'Ранишу – ненасытные, но безмозглые твари. Жрут всех и вся, включая и своих сородичей. Нужно этим воспользоваться.', '', 28153),
(156542, 'ruRU', '', '<Гарона взмахивает клинками, и они исчезают.>', 28153),
(156541, 'ruRU', 'Боевые орлы мигом домчат нас до места. Ну, чего ждете? Залезайте!', '', 28153),
(156540, 'ruRU', 'Идем, скорее.', '', 28153),
(156539, 'ruRU', 'Королева обо всем позаботилась. Транспорт уже ждет нас.', '', 28153),
(156538, 'ruRU', 'Я надеялся добраться до их сокровища...', 'Я надеялась добраться до их сокровища...', 28153),
(156537, 'ruRU', 'Я вернусь, пираты! Вы у меня еще получите!', 'Я вернусь, пираты! Вы у меня еще получите!', 28153),
(156536, 'ruRU', 'Убей этих трусов, всю их команду!', 'Убей этих трусов, всю их команду!', 28153),
(156535, 'ruRU', 'Я скучаю по Зулдазару... Сколько мне еще здесь страдать?', 'Я скучаю по Зулдазару... Сколько мне еще здесь страдать?', 28153),
(156534, 'ruRU', 'Не вижу тут никаких сокровищ. Что за брехня!', 'Не вижу тут никаких сокровищ. Что за брехня!', 28153),
(156533, 'ruRU', 'Они не берут меня в команду! Так нечестно.', 'Они не берут меня в команду! Так нечестно.', 28153),
(156532, 'ruRU', 'Редкое проявление доброты в пустыне.', 'Редкое проявление доброты в пустыне.', 28153),
(156531, 'ruRU', 'Не думал, что за мной кто-то придет. Спасибо тебе.', 'Не думала, что за мной кто-то придет. Спасибо тебе.', 28153),
(156530, 'ruRU', 'Что-то открылось.', '', 28153),
(156529, 'ruRU', 'Осталось еще немного...', '', 28153),
(156528, 'ruRU', 'Все на свободе! Я знал, что могу на тебя положиться, $p!', '', 28153),
(156527, 'ruRU', 'Многие вульперы до сих пор не могут выбраться с Покинутой стоянки. Ты ведь поможешь им?', '', 28153),
(156526, 'ruRU', 'Тщательно откалиброванный метельщик издает короткий сигнал, не находя поблизости ни одной окаменелости.', 'Тщательно откалиброванный метельщик издает короткий сигнал, не находя поблизости ни одной окаменелости.', 28153),
(156525, 'ruRU', 'Археологический элементаль раздраженно грохочет, не найдя ни одной окаменелости.', 'Археологический элементаль раздраженно грохочет, не найдя ни одной окаменелости.', 28153),
(156524, 'ruRU', '', 'За Гилнеас!', 28153),
(156523, 'ruRU', '', 'Стража, сюда! Принесите мне их головы!', 28153),
(156522, 'ruRU', '|TINTERFACE\\ICONS\\SPELL_HOLY_DIVINEPROVIDENCE:20|t Хранитель титанов Хезрел начинает применять заклинание |cFFF00000|Hspell:269310|h[Очищающий свет]|h|r!', '', 28153),
(156521, 'ruRU', '', 'Орда решила напасть на нас здесь? Хорошо, не придется самому вас искать. Гилнеасцы, в атаку!', 28153),
(156520, 'ruRU', 'Очень сложные подсчеты... За своей долей сокровищ приходи позже.', '', 28153),
(156519, 'ruRU', '', 'Тут как в банке Стальгорна. Работа на пятерых.', 28153),
(156518, 'ruRU', 'Мы станем героями... богатыми героями!', '', 28153),
(156517, 'ruRU', 'Сделай меня богачом, $p. Хочу купить пару золотых зубов!', '', 28153),
(156516, 'ruRU', '', 'Эддард, как твой зуб?', 28153),
(156514, 'ruRU', '', 'Мне снилось что-то такое... но то было в банке Стальгорна.', 28153),
(156513, 'ruRU', '', 'Когда золотишко будет наше, я куплю самые пахучие духи – и искупаюсь в них!', 28153),
(156512, 'ruRU', 'Быть может, наши с тобой пути еще пересекутся. Прощай!', '', 28153),
(156511, 'ruRU', 'Мы свободны...', '', 28153),
(156510, 'ruRU', 'Нужно... спасаться...', '', 28153),
(156509, 'ruRU', '', 'Спасибо за помощь, $n. Я продолжу свое дело в других краях.', 28153),
(156508, 'ruRU', '', 'Я не знаю, что тобой движет, $n, но ценю твою готовность поднять оружие против другого рыцаря смерти.', 28153),
(156507, 'ruRU', '', 'Не спускай глаз с неба, $n! Кто-то приближается, я это чувствую!', 28153),
(156506, 'ruRU', 'Как дела, $p?', 'Если речь о золоте, я в деле!', 28153),
(156505, 'ruRU', 'Мне нужна твоя помощь.', 'Мне нужна твоя помощь.', 28153),
(156504, 'ruRU', 'Пережить Короля-лича, но пасть от руки... а-а-а...', '', 28153),
(156503, 'ruRU', 'Какая потеря...', '', 28153),
(156502, 'ruRU', 'Мне нужна твоя помощь.', 'Мне нужна твоя помощь.', 28153),
(156501, 'ruRU', 'Твоя... взяла... драконица...', '', 28153),
(156500, 'ruRU', 'Вечный... покой...', '', 28153),
(156499, 'ruRU', 'Так... нечестно...', '', 28153),
(156498, 'ruRU', 'Тогда я возьму то, что мне причитается... силой!', '', 28153),
(156497, 'ruRU', 'Так вот оно что, $n! Ты хочешь быть единственным рыцарем смерти с таким прекрасным скакуном!', '', 28153),
(156496, 'ruRU', 'Но меня интересуют древние кости у тебя за спиной. Так что, с твоего позволения, я возьму то, что мне причитается.', '', 28153),
(156495, 'ruRU', 'Тот дракон маловат... и он еще живой. Не самое серьезное препятствие.', '', 28153),
(156494, 'ruRU', 'Я следую твоему примеру. Хочешь мне помочь? Что это у тебя, подарок для меня?', '', 28153),
(156493, 'ruRU', 'О, $n! Какая неожиданность!', '', 28153),
(156492, 'ruRU', 'Ладно, если хочешь по-плохому, будет по-плохому!', '', 28153),
(156491, 'ruRU', '', '$n, защити меня! Ритуал должен быть завершен!', 28153),
(156490, 'ruRU', 'Так что отойди и не мешай, маленький дракончик, мне нужна та куча костей.', '', 28153),
(156489, 'ruRU', 'У меня был план, и я от него не отступлю. Мне нужны эти древние останки.', '', 28153),
(156488, 'ruRU', 'Бежим отсюда!', 'Бежим отсюда!', 28153),
(156487, 'ruRU', 'У такого прекрасного рыцаря, как я, должен быть самый лучший скакун.', '', 28153),
(156486, 'ruRU', 'Целых два дракона! Ну надо же, какой сюрприз! Хотя живая... совсем крохотная.', '', 28153),
(156485, 'ruRU', '', 'Тебе здесь не место, рыцарь смерти.', 28153),
(156484, 'ruRU', 'Ну и ну. Кто тут у нас?', '', 28153),
(156483, 'ruRU', 'Последователи Зула не дадут Резану так просто избежать этой участи. Нам придется силой проложить себе путь.\n\nТы $gготов:готова;?', '', 28153),
(156482, 'ruRU', 'Куда ты спешишь? Угомонись. Переведи дыхание... ляг поспи! С нами тебе ничто не грозит.', '', 28153),
(156481, 'ruRU', 'Отец научил меня кузнечному делу... этот молот – первый инструмент, который мы сделали вместе.', '', 28153),
(156480, 'ruRU', 'Мой молот! Тебе удалось его вернуть!', '', 28153),
(156479, 'ruRU', '', 'Эти изгои заменяют мне семью.', 28153),
(156478, 'ruRU', '', 'Добро пожаловать в банду, $p.', 28153),
(156477, 'ruRU', 'Добро пожаловать в банду, $p.', '', 28153),
(156476, 'ruRU', '', 'Добро пожаловать в банду, $p.', 28153),
(156475, 'ruRU', 'Добро пожаловать в банду, $p.', '', 28153),
(156474, 'ruRU', 'Хочешь выпить или перекусить?', 'Хочешь выпить или перекусить?', 28153),
(156473, 'ruRU', 'О, это ты, $p? Эти типы из племени Песчаной Бури за тобой не следили?', '', 28153),
(156472, 'ruRU', 'Ограбим еще пару караванов, и можно нападать на арену. Вот где настоящая добыча!', '', 28153),
(156471, 'ruRU', 'Я хочу пить. Идите и украдите еще этой зандаларской выпивки! Знатное пойло!', '', 28153),
(156470, 'ruRU', 'У нас кончаются дрова. Найдите еще один вульперский караван, который можно ограбить!', '', 28153),
(156469, 'ruRU', 'Пустыня принадлежит племени Песчаной Бури! Остальным сюда путь заказан!', '', 28153),
(156468, 'ruRU', 'Приведите мне больше рабов. У меня еще полно копий!', '', 28153),
(156467, 'ruRU', 'Бейте их! Бейте, как собак!', '', 28153),
(156466, 'ruRU', 'Где теперь ваша гордость? Я сбил с вас спесь, зандалары!', '', 28153),
(156465, 'ruRU', 'Ха! Попал точно в грудь. Мерзкие вульперы...', '', 28153),
(156464, 'ruRU', 'Хочешь вернуть свой молот, ковыряющаяся в грязи волосатая картофелина! Иди и возьми!', '', 28153),
(156463, 'ruRU', 'Мы очистим нашу землю от кул-тирасского отребья! $n, созывай бойцов Орды, давай покончим с этим.', '', 28153),
(156462, 'ruRU', 'Следи за тем, что говоришь. Язма – верховная жрица моей лоа, ей внемлет сам король Растахан.$b$bА с великим пророком Зулом, если верить слухам, их объединяет больше, чем просто дружба.', 'Следи за тем, что говоришь. Язма – верховная жрица моей лоа, ей внемлет сам король Растахан.$b$bА с великим пророком Зулом, если верить слухам, их объединяет больше, чем просто дружба.', 28153),
(156461, 'ruRU', 'Шадра – лоа, которая пользуется особым почтением в Совете Занчули, и ее последователи, такие как я, имеют много привилегий. В том числе мы не обязаны отвечать на вопросы таким, как ты.', 'Шадра – лоа, которая пользуется особым почтением в Совете Занчули, и ее последователи, такие как я, имеют много привилегий. В том числе мы не обязаны отвечать на вопросы таким, как ты.', 28153),
(156460, 'ruRU', 'Проклятие...', 'Проклятие...', 28153),
(156459, 'ruRU', 'Вы проиграете...', 'Вы проиграете...', 28153),
(156458, 'ruRU', 'Мой король... прости меня...', 'Мой король... прости меня...', 28153),
(156457, 'ruRU', 'Ты... заплатишь...', 'Ты... заплатишь...', 28153),
(156456, 'ruRU', 'За... Альянс...', 'За... Альянс...', 28153),
(156455, 'ruRU', 'Последователи Шадры следят за вами с большим интересом.$b$BМы видим, как ваша Орда все больше запутывается в огромной паутине лжи. Скоро капкан захлопнется, а вы этого даже не поймете... пока не станет слишком поздно.', 'Последователи Шадры следят за вами с большим интересом.$b$BМы видим, как ваша Орда все больше запутывается в огромной паутине лжи. Скоро капкан захлопнется, а вы этого даже не поймете... пока не станет слишком поздно.', 28153),
(156454, 'ruRU', 'Умри!', 'Умри!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156453, 'ruRU', 'Я отправлю тебя в Оргриммар по частям!', 'Я отправлю тебя в Оргриммар по частям!', 28153),
(156452, 'ruRU', 'Ты заплатишь за преступления против Альянса!', 'Ты заплатишь за преступления против Альянса!', 28153),
(156451, 'ruRU', 'Я служу Шадре, повелительнице шпионов и лоа ядов. А кому на самом деле служишь ты?', 'Я служу Шадре, повелительнице шпионов и лоа ядов. А кому на самом деле служишь ты?', 28153),
(156450, 'ruRU', 'Умри, отродье Орды!', 'Умри, отродье Орды!', 28153),
(156449, 'ruRU', 'За Альянс!', 'За Альянс!', 28153),
(156448, 'ruRU', 'Госпожа знает, что ты находишься в ее владениях. Берегись!', 'Госпожа знает, что ты находишься в ее владениях. Берегись!', 28153),
(156447, 'ruRU', 'Да не оставит тебя Мать-Земля, $n.', 'Да не оставит тебя Мать-Земля, $n.', 28153),
(156446, 'ruRU', 'Наша охота в этих землях только начинается.', '', 28153),
(156445, 'ruRU', 'Раан\'ка еще прячется в оазисе? Надо его как-нибудь навестить, что ли...', '', 28153),
(156444, 'ruRU', 'Я знал, что ты еще вернешься! Недавно пришла новая партия товара, как раз для тебя.', '', 28153),
(156443, 'ruRU', '[СЦЕНА ПОКАЗЫВАЕТ, КАК ГЕНЕРАЛ ДЖАКРА\'ЗЕТ И ИМПЕРАТОР КОРТЕК ВСТУПАЮТ В СГОВОР.]', '', 28153),
(156442, 'ruRU', 'Глубины... следят... за тобой...', 'Глубины... следят... за тобой...', 28153),
(156441, 'ruRU', 'Я утоплю твой труп в море!', 'Я утоплю твой труп в море!', 28153),
(156440, 'ruRU', '', 'Мне надо было родиться среди гоблинов. Они бы оценили мои уникальные способности!', 28153),
(156439, 'ruRU', 'Надо договориться со Стальными Волнами. Они еще глупее.', '', 28153),
(156438, 'ruRU', 'Занимайся своими делами, маленькое создание, а мы будем искать Зула. Но будь наготове, скоро нам понадобится вся твоя ярость.', '', 28153),
(156437, 'ruRU', '', 'Мы будем преследовать этих еретиков по всему Азероту. Я соберу свою стаю, и мы обрушим смертельные камни на головы отвратительных тварей, что посмели отвернуться от нас.\n\nА пока мои дети поднимутся в небо и узнают, что задумал Зул и его предатели.', 28153),
(156436, 'ruRU', 'Последний удар за тобой... на этот раз...', '', 28153),
(156435, 'ruRU', '<Встать в очередь на островную экспедицию группой (PvP).>', '<Встать в очередь на островную экспедицию группой (PvP).>', 28153),
(156434, 'ruRU', '<Очередь на островную экспедицию (PvP).>', '<Очередь на островную экспедицию (PvP).>', 28153),
(156433, 'ruRU', 'Используйте фетиш Джин\'Тики, чтобы уничтожить Зуладжина!', 'Используйте фетиш Джин\'Тики, чтобы уничтожить Зуладжина!', 28153),
(156432, 'ruRU', 'Остается лишь надеяться, что я достаточно хорошо спрятал свой ключ, и его сможешь найти только ты.', '', 28153),
(156431, 'ruRU', 'Кага, никто не сомневается в твоей доблести, но ты сейчас не в состоянии драться. $n, я пойду с Кагой. Когда закончишь, приходи к башне.', '', 28153),
(156430, 'ruRU', 'Спасибо. Я захвачу башню. Она нам понадобится, чтобы призвать остальные войска.', 'Спасибо. Я захвачу башню. Она нам понадобится, чтобы призвать остальные войска.', 28153),
(156429, 'ruRU', '', 'Мои сестры... убьют тебя...', 28153),
(156428, 'ruRU', 'Орда будет уничтожена...', 'Орда будет уничтожена...', 28153),
(156427, 'ruRU', 'Вы служите сумасшедшей...', 'Вы служите сумасшедшей...', 28153),
(156426, 'ruRU', 'Вы монстры...', 'Вы монстры...', 28153),
(156425, 'ruRU', 'Я... убью... вас...', 'Я... убью... вас...', 28153),
(156424, 'ruRU', 'Орда за это заплатит...', 'Орда за это заплатит...', 28153),
(156423, 'ruRU', 'За Тельдрассил...', 'За Тельдрассил...', 28153),
(156422, 'ruRU', 'Сестры... я старалась...', 'Сестры... я старалась...', 28153),
(156421, 'ruRU', '', 'Моя семья погибла на Тельдрассиле! Я убью вас всех!', 28153),
(156420, 'ruRU', '', 'Мы отомстим за Тельдрассил!', 28153),
(156419, 'ruRU', 'Мы заставим култирасцев еще раз подумать, стоит ли выступать против Орды.', '', 28153),
(156418, 'ruRU', 'За Тельдрассил и Альянс!', 'За Тельдрассил и Альянс!', 28153),
(156417, 'ruRU', 'Сдохни в муках, отродье Орды!', 'Сдохни в муках, отродье Орды!', 28153),
(156416, 'ruRU', '', 'Убийцы! Как вы смеете здесь появляться?', 28153),
(156415, 'ruRU', 'Мы пойдем вон туда!', '', 28153),
(156414, 'ruRU', 'Теперь я буду ходить!', '', 28153),
(156413, 'ruRU', 'Теперь мы идем туда, куда я хочу!', '', 28153),
(156412, 'ruRU', 'Меня повысили! Теперь я – наши ноги!', '', 28153),
(156411, 'ruRU', 'Теперь я за главного!', '', 28153),
(156410, 'ruRU', 'Очиститесь священным огнем!', '', 28153),
(156409, 'ruRU', 'Нет... Надо найти... кольцо...', '', 28153),
(156408, 'ruRU', 'Тварь! Я отрежу тебе голову и отправлю ее твоему вождю!', 'Тварь! Я отрежу тебе голову и отправлю ее твоему вождю!', 28153),
(156407, 'ruRU', 'Я преподнесу твою голову королеве!', '', 28153),
(156406, 'ruRU', '', 'Орда заплатит за то, что сделала с Тельдрассилом!', 28153),
(156405, 'ruRU', '', 'Я вам покажу, как горят трупы!', 28153),
(156404, 'ruRU', '', 'Кажется, здесь мы свое дело сделали! Береги себя, $p.', 28153),
(156403, 'ruRU', 'Я отомщу за своих бойцов. Клянусь!', 'Я отомщу за своих бойцов. Клянусь!', 28153),
(156402, 'ruRU', 'Глупцы... Вам меня не остановить.', '', 28153),
(156401, 'ruRU', '', 'Ты! Орда. Мне нужны твои способности.', 28153),
(156400, 'ruRU', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Доступна новая |cFFFF0404|Hspell:263420|h[силовая матрица]|h|r.', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Доступна новая |cFFFF0404|Hspell:263420|h[силовая матрица]|h|r.', 28153),
(156399, 'ruRU', 'Этот тролль чокнутый, как стая голодных ранишу.', '', 28153),
(156398, 'ruRU', 'Рикати закатывает глаза.', '', 28153),
(156397, 'ruRU', 'Хорошо, дружище. Будет сделано! Спасибо!', '', 28153),
(156396, 'ruRU', 'Нет времени болтать, Рикати! Племя Песчаной Бури вышло на тропу войны! Прячь мед!', '', 28153),
(156395, 'ruRU', 'Кольцо приливов будет нашим! Такова воля королевы Азшары!', 'Кольцо приливов будет нашим! Такова воля королевы Азшары!', 28153),
(156394, 'ruRU', 'Мы не остановимся, пока кольцо не будет нашим!', 'Мы не остановимся, пока кольцо не будет нашим!', 28153),
(156393, 'ruRU', 'Ты о чем? Я, по-твоему, должен считать души? Это не мое дело. Тебе надо, ты и считай.\n\nИ, кстати, давай начнем сначала.', '', 28153),
(156392, 'ruRU', 'Где Кольцо приливов? Не прячьте его от нас!', 'Где Кольцо приливов? Не прячьте его от нас!', 28153),
(156391, 'ruRU', 'Кольцо приливов потеряли где-то здесь. Надо вернуть его королеве!', 'Кольцо приливов потеряли где-то здесь. Надо вернуть его королеве!', 28153),
(156390, 'ruRU', 'Орден Возрождения Шторма растет. Ты с нами?', 'Орден Возрождения Шторма растет. Ты с нами?', 28153),
(156389, 'ruRU', 'Ну что, уже есть миллион душ?', 'Ну что, уже есть миллион душ?', 28153),
(156388, 'ruRU', 'Никто не встанет на пути нашей королевы!', 'Никто не встанет на пути нашей королевы!', 28153),
(156387, 'ruRU', 'Кольцо приливов наше по праву!', 'Кольцо приливов наше по праву!', 28153),
(156386, 'ruRU', 'Мы еще можем остановить лорда Штормсонга.', 'Мы еще можем остановить лорда Штормсонга.', 28153),
(156385, 'ruRU', 'Кольцо будет нашим!', 'Кольцо будет нашим!', 28153),
(156384, 'ruRU', 'Королева Азшара требует Кольцо приливов!', 'Королева Азшара требует Кольцо приливов!', 28153),
(156383, 'ruRU', '|TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t Золотой Змей поглощает ожившее золото и получает эффект |cFFFF0000|Hspell:265991|h[Блеск]|h|r!', 'Золотой Змей поглощает ожившее золото и получает эффект |TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t |cFFFF0000|Hspell:265991|h[Блеск]|h|r!', 28153),
(156382, 'ruRU', '', 'Ой-ой! Это не очень хорошо. Вообще нехорошо!', 28153),
(156381, 'ruRU', 'Хватай веревку и спускайся в десантную шлюпку... если не хочешь добираться вплавь.', '', 28153),
(156380, 'ruRU', 'Я больше не буду стирать нижнее белье этих мерзких людей!', '', 28153),
(156379, 'ruRU', '', 'Я промокла до нитки! Спасибо.', 28153),
(156378, 'ruRU', '', 'Ну все, с меня хватит!', 28153),
(156377, 'ruRU', 'Я спасен! Это было ужасно...', '', 28153),
(156375, 'ruRU', 'Пока вы решали судьбы мира, я изучил клинок.', 'Пока вы решали судьбы мира, я изучила клинок.', 28153),
(156374, 'ruRU', '<Мастер Шоу кивает.>', '', 28153),
(156373, 'ruRU', 'Мы здесь, мастер.', '', 28153),
(156372, 'ruRU', 'Я буду работать с мастером Шоу. Он, может быть, не самый приятный тип, но свое дело знает.', '', 28153),
(156371, 'ruRU', 'Король призвал для этой кампании немало могучих героев.', '', 28153),
(156370, 'ruRU', 'Быстрокрыл, лети, поймай себе что-нибудь вкусное.', '', 28153),
(156369, 'ruRU', 'Иди за мной.', '', 28153),
(156368, 'ruRU', 'Точно в колено!', 'Ох... больно, наверное!', 28153),
(156367, 'ruRU', 'Мы так просто не сдадимся.', 'Им надо было сразу бежать.', 28153),
(156366, 'ruRU', 'Еще один готов!', 'Они не такие крутые, как думали!', 28153),
(156365, 'ruRU', 'Здравствуй, капитан Стоун. Я с нетерпением жду нашей встречи.', '', 28153),
(156364, 'ruRU', 'Хорошо, положи его в повозку. Ты оказалась полезнее, чем я ожидал, Лилиан.', '', 28153),
(156363, 'ruRU', '', 'Более-менее.', 28153),
(156362, 'ruRU', 'Оно целое?', '', 28153),
(156361, 'ruRU', '', 'Я здесь, Гнилостень. Тело у меня.', 28153),
(156360, 'ruRU', 'Хорошая работа, $p. Хм, а где Лилиан?', '', 28153),
(156359, 'ruRU', 'Прошу, поспешите... они хотят убить Резана!', '', 28153),
(156358, 'ruRU', 'Они... заставили меня рассказать, как драккари это сделали...', '', 28153),
(156357, 'ruRU', 'Очень хорошо. Телия введет тебя в курс дела.', '', 28153),
(156356, 'ruRU', '', 'Оперативная сводка готова!', 28153),
(156355, 'ruRU', '', 'Враги пошли на дрова. Великолепно!', 28153),
(156354, 'ruRU', '', 'Ведьмы снова собирают силы. Возьми под контроль разрушителя и уничтожь их армию!', 28153),
(156353, 'ruRU', '', 'Мы должны показать култирасцам, что бывает с врагами Орды.', 28153),
(156352, 'ruRU', 'Имей в виду, Бриджпорт – большое и хорошо охраняемое поселение. Не заходи слишком далеко, держись на окраине... пока что.', '', 28153),
(156351, 'ruRU', 'Мы сделали свое дело, $p. Я горжусь тем, что мы совершили.\n\nНо теперь я должен позаботиться о своих сородичах и оберегать их.\n\nНе сомневаюсь, что мы еще встретимся. Я горжусь нашей дружбой – и нашим союзом.', '', 28153),
(156350, 'ruRU', 'Отступники плохо обращаются со своими животными. Их можно легко натравить на хозяев.', '', 28153),
(156349, 'ruRU', 'Я не собираюсь это терпеть! Меня назначил генералом сам пророк Зул!', '', 28153),
(156348, 'ruRU', '', 'Вот это была битва, о которой стоит сложить песни!\n\nДля меня было честью сражаться вместе с тобой и Ворриком. Надеюсь, вскоре повторим этот опыт.\n\nМы избавились еще не от всех отступников.', 28153),
(156347, 'ruRU', 'Давай покончим с этим вместе.', '', 28153),
(156346, 'ruRU', '', 'Проучим этих сетраков.', 28153),
(156345, 'ruRU', '', 'Теперь мы сможем и дальше сражаться против ковена. Спасибо.', 28153),
(156344, 'ruRU', 'За мной, здесь недалеко.', '', 28153),
(156343, 'ruRU', 'Хорошо. Он и будет нашей целью.', '', 28153),
(156342, 'ruRU', '', 'Город, который мы недавно прошли, Бриджпорт – главная угроза в этих краях.', 28153),
(156341, 'ruRU', 'Рексар! <кашляет> Многие еще держатся. Но у них... мало времени.', 'Рексар! <кашляет> Многие еще держатся. Но у них... мало времени.', 28153),
(156340, 'ruRU', 'Наконец-то солдаты Орды перестанут служить пищей для монстров. Спасибо.', '', 28153),
(156339, 'ruRU', '', 'Серебро на исходе, а без него нам с ведьмами не справиться. Спустись в шахту и добудь столько, сколько сможешь.', 28153),
(156338, 'ruRU', 'Ракжан готов нам помочь, и нетрудно понять, почему.\n\nОтступники жестоко обошлись с ним и его стаей. Посмотри на его шрамы, посчитай, сколько пустых насестов на его пике.\n\nОн имеет право отомстить, как и любой из нас. И мы отомстим вместе.', '', 28153),
(156337, 'ruRU', 'Скоро. Держись, Сэмюэл.', '', 28153),
(156336, 'ruRU', 'Холодно. Когда они замолчат?', '', 28153),
(156335, 'ruRU', '$n, помешай мое варево, чтобы не подгорело.', '', 28153),
(156334, 'ruRU', 'Молодцы. А теперь сделаем так, чтобы эта сходка стала для них последней.', '', 28153),
(156333, 'ruRU', 'Шикарно! Теперь-то мы покажем капитанам, что к чему.', '', 28153),
(156332, 'ruRU', 'Не дергайся. Эти травы залечат твои раны. Ты можешь рассказать, что там, в крепости? Есть еще выжившие?', '', 28153),
(156331, 'ruRU', '|TInterface\\ICONS\\ABILITY_DEATHKNIGHT_SOULREAPER:20|t Берегитесь! Оживленный голиаф наносит больше урона с каждым эффектом |cFFFF0404|Hspell:260512|h[Жатвы душ]|h|r!', '', 28153),
(156330, 'ruRU', 'Смотри! Тут кто-то еще дышит!', '', 28153),
(156329, 'ruRU', 'В том сражении погибло много храбрых воинов. Вы прибыли очень вовремя.', '', 28153),
(156328, 'ruRU', 'Вражеская пехота пошла в атаку, когда мы спасали команды. Но наши силы были слишком растянуты, чтобы удержать обе позиции, и нам пришлось отойти к берегу.', '', 28153),
(156327, 'ruRU', 'Они напали рано утром. У кул-тирасских магов был странный предмет, с помощью которого они призвали ужасных тварей, схвативших наши корабли.', '', 28153),
(156326, 'ruRU', 'Ха! Подтверждаю, миссия выполнена безупречно! Люблю, когда все идет по плану. Конец связи.', '', 28153),
(156325, 'ruRU', 'Слушай мою команду. Видишь красную кнопку? Покинь область поражения и нажми красную кнопку. Выполняй. Прием.', '', 28153),
(156324, 'ruRU', 'Код доступа один-девять-девять. Показания прибора вне ожидаемого диапазона... Отставить... Сейчас перекалибрую. Ждите. Прием.', '', 28153),
(156323, 'ruRU', 'Понял, калибровка окончена. Расставьте приборы в обозначенных точках. Доложите, когда закончите. Конец связи.', '', 28153),
(156322, 'ruRU', 'Проверка связи, я \"Альфа-один\". Отряд \"Альфа\", как слышно меня? Прием.', '', 28153),
(156321, 'ruRU', 'Славная битва! И мы целы, $p!', '', 28153),
(156320, 'ruRU', '', 'Огонь никогда не гаснет...', 28153),
(156319, 'ruRU', '', 'Пепел к пеплу...', 28153),
(156318, 'ruRU', 'Мы смиренно благодарим тебя за подвиги. Спасибо, $p!', '', 28153),
(156317, 'ruRU', '', 'Твои кости отлично сгодятся на растопку.', 28153),
(156316, 'ruRU', '', 'Я не оставлю никого, кто мог бы оплакать твой пепел.', 28153),
(156315, 'ruRU', 'Это один из самых славных дней за всю нашу долгую историю!', '', 28153),
(156314, 'ruRU', 'Я придумаю новый суп и назову его в твою честь!', '', 28153),
(156313, 'ruRU', 'Суп из |3-8($r) вдвое вкуснее черепашьего.\n\nПросто добудь мне мяса грязевых червей и не трогай маленьких черепах.\n\nА прочие супы мы в другой раз попробуем!', '', 28153),
(156312, 'ruRU', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t %s начинает использовать способность |cFFFF0000|Hspell:267334|h[Сфера порчи]|h|r!', 'Вдалеке появляется проекция...', 28153),
(156311, 'ruRU', '', 'Как легко сбиться с пути...', 28153),
(156310, 'ruRU', 'Если тебе понадобится моя помощь, скажи!', '', 28153),
(156309, 'ruRU', 'Ну, раз мы тут все уладили, я, пожалуй, пойду.', '', 28153),
(156308, 'ruRU', '|cFF0000FF(Задание)|r Отправиться на Тирагардское поморье.', '|cFF0000FF(Задание)|r Отправиться на Тирагардское поморье.', 28153),
(156307, 'ruRU', '|TInterface\\Icons\\ABILITY_DEATHKNIGHT_DEATHSIPHON2.BLP:20|t %s начинает использовать способность |cFFFF0000|Hspell:265360|h[Тревожный обман]|h|r!', 'Вдалеке появляется проекция...', 28153),
(156306, 'ruRU', '', 'Спасибо тебе за помощь.', 28153),
(156305, 'ruRU', '', 'Нас окружают тени прошлого.', 28153),
(156304, 'ruRU', 'Не понимаешь моих искрометных метафор? Так я сейчас объясню – для тех, кто в танке. Ха-ха-ха! В ТАНКЕ!', '', 28153),
(156303, 'ruRU', 'Будешь сжигать мосты – обожжешься!', '', 28153),
(156302, 'ruRU', 'Я ведь могу и погорячиться.', '', 28153),
(156301, 'ruRU', 'Пусть твое пламя не гаснет.', '', 28153),
(156300, 'ruRU', 'Пусть все твои дела спорятся.', '', 28153),
(156299, 'ruRU', 'Желаю удачи!', '', 28153),
(156298, 'ruRU', 'Тебе нигде не попадался мой гаечный ключ?', '', 28153),
(156297, 'ruRU', 'Тебе нужна помощь?', '', 28153),
(156296, 'ruRU', 'Жги!', '', 28153),
(156286, 'ruRU', '', 'Столько скорби. Столько потерь.', 28153),
(156285, 'ruRU', '', 'Куда ведет мой путь?', 28153),
(156284, 'ruRU', '', 'Я должна найти верный путь.', 28153),
(156283, 'ruRU', 'Какой красный песок...', 'Какой красный песок...', 28153),
(156282, 'ruRU', 'Как я здесь оказался?', 'Как я здесь оказалась?', 28153),
(156281, 'ruRU', 'Мои друзья отомстят за меня.', 'Мои друзья отомстят за меня.', 28153),
(156280, 'ruRU', 'Значит, Туралион наш сияет внутренним светом, Аллерия обзавелась обликом Бездны... Хм... Раз уж я снова в деле, надо и мне придумать какой-нибудь фокус с внешностью!', '', 28153),
(156279, 'ruRU', 'Я хорошо дрался?', 'Я хорошо дралась?', 28153),
(156278, 'ruRU', 'Я убью тебя!', 'Я убью тебя!', 28153),
(156277, 'ruRU', 'Тебе конец!', 'Тебе конец!', 28153),
(156276, 'ruRU', 'Ты нас не остановишь!', 'Ты нас не остановишь!', 28153),
(156275, 'ruRU', 'Слава Свету, я выбрался из Оплота Чести. Достал он меня до печенок.', '', 28153),
(156274, 'ruRU', 'Не сегодня, дружище!', 'Не сегодня, дружище!', 28153),
(156273, 'ruRU', 'Раз в неделю мы с Кадгаром играем в шашки... Он всегда жульничает.', '', 28153),
(156272, 'ruRU', 'Каждый должен делать свое дело.', '', 28153),
(156271, 'ruRU', 'За Стромгард!', '', 28153),
(156270, 'ruRU', 'Скажу честно, босс.\n\nЯ всегда хотел поучаствовать в мятеже.', '', 28153),
(156269, 'ruRU', 'За Альянс!', '', 28153),
(156268, 'ruRU', 'Альянс победит.', '', 28153),
(156267, 'ruRU', 'Доброй битвы!', '', 28153),
(156266, 'ruRU', 'Мы должны ответить на зов Азерота.', '', 28153),
(156265, 'ruRU', 'Мы будем сражаться за свою землю.', '', 28153),
(156264, 'ruRU', 'Любую опасность мы встретим вместе.', '', 28153),
(156263, 'ruRU', 'Жизнь за Альянс.', '', 28153),
(156262, 'ruRU', 'Стромгард вернет былое величие.', '', 28153),
(156261, 'ruRU', 'Знаешь, что? Мне плевать, что ты подумаешь. Я хочу это сказать, и я скажу это: \"МОЛОООТ ПООШЕЕЕЕЕЕЛ!!!\"', '', 28153),
(156260, 'ruRU', 'Можете говорить о синдроме среднего сына... Но когда один брат – знаменитый исследователь, а другой – вообще алмаз, трудно найти свое место в жизни!', '', 28153),
(156259, 'ruRU', 'Что за?!.. Какой-то ребенок назвал меня \"карамельным королем\" и потребовал леденец!', '', 28153),
(156258, 'ruRU', 'Мы никогда не сдаемся!', '', 28153),
(156257, 'ruRU', 'Клан Бронзобородов благодарит тебя.', '', 28153),
(156256, 'ruRU', 'Стальгорн победит.', '', 28153),
(156255, 'ruRU', 'Пусть слава осияет твой путь.', '', 28153),
(156254, 'ruRU', 'Верной руки и крепкого молота.', '', 28153),
(156253, 'ruRU', 'Да согреет тебя жар кузни!', '', 28153),
(156252, 'ruRU', 'Молот есть, топор тоже... За работу!', '', 28153),
(156251, 'ruRU', 'Ты поможешь Альянсу?', '', 28153),
(156250, 'ruRU', 'Три Клана едины.', '', 28153),
(156249, 'ruRU', 'Стальгорн выполнит свою задачу.', '', 28153),
(156248, 'ruRU', 'Знаешь, что случилось с первыми шестью легионами? Сейчас узнаешь!', '', 28153),
(156247, 'ruRU', 'На гауптвахту хочешь?', '', 28153),
(156246, 'ruRU', 'Мое терпение на исходе.', '', 28153),
(156245, 'ruRU', 'Самое трудное впереди.', '', 28153),
(156244, 'ruRU', 'До новой встречи.', '', 28153),
(156243, 'ruRU', 'Да хранит тебя Свет.', '', 28153),
(156242, 'ruRU', 'Клянусь мощью Альянса, наших врагов ждет лишь поражение.', '', 28153),
(156241, 'ruRU', 'Клянусь Светом, первый удар принадлежит нам.', '', 28153),
(156240, 'ruRU', 'Ты становишься легендой!', '', 28153),
(156239, 'ruRU', 'Сегодня судьба нам улыбнулась.', '', 28153),
(156238, 'ruRU', 'Орде не победить.', '', 28153),
(156237, 'ruRU', 'Честь имею.', '', 28153),
(156236, 'ruRU', 'Мы все – сыны и дочери Альянса.', '', 28153),
(156235, 'ruRU', '', 'Мы защитим этот мир. Вперед, клан Черного Железа! Битва ждет!', 28153),
(156234, 'ruRU', '', 'Кровь, текущая в наших жилах... это кровь самой Азерот.', 28153),
(156233, 'ruRU', '', 'Год за годом мы ковали свое королевство. Наша воля – сталь. Наши сердца – угли.', 28153),
(156232, 'ruRU', '', 'Гора дает нам жизнь. Дает нам силу.', 28153),
(156231, 'ruRU', '', 'Тургаден и Телин изготовили специальную броню, чтобы тебя отблагодарить. Носи ее с гордостью, $n!', 28153),
(156230, 'ruRU', '', 'Теперь Альянс знает, на что способен клан Черного Железа. И это – твоя заслуга.', 28153),
(156229, 'ruRU', '', 'Возвращайся. У нас для тебя есть кое-что особенное.', 28153),
(156228, 'ruRU', '', 'Мы все гордимся тобой, $n. До меня дошли рассказы о твоих храбрых подвигах на поверхности Азерота.', 28153),
(156227, 'ruRU', '', 'Нас закалило пламя горы, $n. Покажи свой огонь всему миру.', 28153),
(156226, 'ruRU', '', 'Азерот ждет. Штормград – первая искра над твоей наковальней.', 28153),
(156225, 'ruRU', '', 'Пришло время клану Черного Железа показать себя.', 28153),
(156224, 'ruRU', '', 'Многие сородичи советовали нам оставаться под землей. Но храбрецам они не указ.', 28153),
(156223, 'ruRU', 'За Альянс!', '', 28153),
(156222, 'ruRU', '', 'Клан Черного Железа принимает приглашение. За Альянс!', 28153),
(156221, 'ruRU', '', 'Это просто формальность. Ничего страшного.', 28153),
(156220, 'ruRU', 'Однако мы никогда не предлагали вам вступить в Альянс официально. Простите мне эту оплошность и позвольте исправить ее.', '', 28153),
(156219, 'ruRU', '', 'Все так.', 28153),
(156218, 'ruRU', 'И пускай ваш клан славится... духом независимости, никто не сомневается в вашей верности и решимости.', '', 28153),
(156217, 'ruRU', 'Много лет вы достойно представляли свой народ в совете Трех Кланов и поддерживали порядок в Стальгорне.', '', 28153),
(156216, 'ruRU', '', 'Взаимно, король Ринн.', 28153),
(156215, 'ruRU', 'Королева-регент Тауриссан, рад снова видеть вас.', '', 28153),
(156214, 'ruRU', 'Эй! Я тут работаю.', '', 28153),
(156213, 'ruRU', '', 'Спасибо. Важно сохранить те немногие фермы, что остались в Друстваре.', 28153),
(156212, 'ruRU', '', 'Свиньи с местной фермы заблудились в лесу. Верни их, пока до них не добрались споры!', 28153),
(156211, 'ruRU', '', 'Ведьмы наказаны, а жители Заставы в безопасности! Спасибо.', 28153),
(156210, 'ruRU', '', 'Ковен отправил лазутчиков на Заставу Арома. Выведи ведьм на чистую воду и пресеки их козни.', 28153),
(156209, 'ruRU', '<Предложить свертывающий порошок: |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', '<Предложить свертывающий порошок: |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', 28153),
(156208, 'ruRU', '<Предложить древний тортолланский свиток: |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', '<Предложить древний тортолланский свиток: |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', 28153),
(156207, 'ruRU', '<Предложить рассол из морского ежа: |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', '<Предложить рассол из морского ежа: |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', 28153),
(156206, 'ruRU', '<Предложить вяжущие специи: |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', '<Предложить вяжущие специи: |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', 28153),
(156205, 'ruRU', 'Не зевай, $n. Я скажу, когда мне понадобятся новые ингредиенты.', '', 28153),
(156204, 'ruRU', 'Тут недостаточно чьих угодно умений, друг мой. Он в объятиях лоа смерти!', '', 28153),
(156203, 'ruRU', 'Ох! Это... боюсь, моих скромных умений тут недостаточно.', '', 28153),
(156202, 'ruRU', 'Джамиль Абул\'хусин дрожит от страха!', '', 28153),
(156201, 'ruRU', 'Джамиль?', '', 28153),
(156200, 'ruRU', 'В любую минуту.', '', 28153),
(156199, 'ruRU', 'Вот так... скоро король должен очнуться.', '', 28153),
(156198, 'ruRU', 'Кровь никак не останавливается. Быстрее, $n, подай свертывающий порошок!', '', 28153),
(156196, 'ruRU', 'Пение Джамиля Абул\'хусина становится громче, в его голосе звучит отчаяние.', '', 28153),
(156195, 'ruRU', 'Готово! Теперь я дам ему зелье.', '', 28153),
(156194, 'ruRU', 'Джамиль Абул\'хусин начинает еле слышно петь молитву.', '', 28153),
(156193, 'ruRU', 'Точно, три щепотки!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156192, 'ruRU', 'В последний раз я это делал семьсот лет назад. Попробуй сам вспомни то, что было до рождения прадеда твоего прадеда.', '', 28153),
(156191, 'ruRU', 'Ты забыл рецепт?!', '', 28153),
(156190, 'ruRU', 'Одна щепотка или две?.. $n, принеси мой свиток.', '', 28153),
(156188, 'ruRU', 'Спасибо. Я постараюсь все сделать побыстрее. Терпение...', '', 28153),
(156187, 'ruRU', 'Ничего? Джол, давай быстрее свое лекарство...', '', 28153),
(156186, 'ruRU', 'Теперь рассол. Он на полке.', '', 28153),
(156185, 'ruRU', 'Не дайте крогам сбежать!', 'Не дайте крогам сбежать!', 28153),
(156184, 'ruRU', 'Я готов, Джол.', 'Я готова, Джол.', 28153),
(156183, 'ruRU', 'Ингредиенты весьма специфические, так что надо хорошенько сосредоточиться. Ты станешь моими руками и поможешь в приготовлении. Не забывай, что жизнь короля висит на волоске.\n\nУ тебя точно все готово?', '', 28153),
(156182, 'ruRU', '', 'Если изгой говорит правду, нужно все разузнать. Но будь осторожнее: Джакра\'зет, возможно, все еще где-то рядом.', 28153),
(156181, 'ruRU', 'Тебе это интересно? Ну, ладно! С чего бы начать?\n\nКаждые несколько лет мы совершаем паломничество в Назмир. Иногда раз в пять лет, иногда в двадцать – все зависит от того, когда Торга захочет поведать очередную историю.\n\nКак только до нас доходят слухи о том, что Торга готов что-то рассказать, мы отправляемся в путь. Приходим к нему, рассаживаемся вокруг и слушаем истории, а потом расходимся и пересказываем их всем, кто нам встречается по пути.\n\nТебе очень повезло. Мало кому удается встретить такую большую группу тортолланов. Это тоже интересная история, – если вы, |3-7($r), интересуетесь такими вещами.', '', 28153),
(156180, 'ruRU', 'Только через мой... труп...', 'Только через мой... труп...', 28153),
(156179, 'ruRU', 'Расскажи мне о вашем паломничестве.', 'Расскажи мне о вашем паломничестве.', 28153),
(156178, 'ruRU', 'Никто не сбежит, пока я на посту!', 'Никто не сбежит, пока я на посту!', 28153),
(156177, 'ruRU', 'Предлагаю ничью.', '', 28153),
(156176, 'ruRU', 'Какой-то новый порох невиданной мощи!', '', 28153),
(156175, 'ruRU', 'Боралус принадлежит мне.', '', 28153),
(156174, 'ruRU', 'Что происходит?', 'Что происходит?', 28153),
(156173, 'ruRU', '', 'За Орду!', 28153),
(156172, 'ruRU', '', 'Хорошо, хорошо! Теперь езжай через мост и мимо взрывчатки.', 28153),
(156171, 'ruRU', '', 'Шевелись! Собери всех городских стражников... и их командира!', 28153),
(156170, 'ruRU', '', 'Давайте, трусы, идите сюда!', 28153),
(156169, 'ruRU', '', 'Орда разорвет вас на части!', 28153),
(156168, 'ruRU', '', 'Култирасцы! Союз с Альянсом станет вашим смертным приговором!', 28153),
(156167, 'ruRU', '', 'Езжай в город и собери столько стражников, сколько сможешь!', 28153),
(156166, 'ruRU', '', 'Флинн! Сюда!', 28153),
(156165, 'ruRU', 'Неужели я проиграл?', 'Неужели я проиграла?', 28153),
(156164, 'ruRU', '', 'Час настал. Убьем капитана, и братство Туманных Парусов останется свободным!', 28153),
(156163, 'ruRU', '', 'Думаешь, у тебя проблемы в личной жизни? Я тебе такое расскажу...', 28153),
(156162, 'ruRU', '', 'Забавно... Я даже не заметила, как у меня пропал кул-тирасский акцент.', 28153),
(156161, 'ruRU', '', 'Ну конечно у меня есть овцепосох. А также веретено судьбы и прялка предубеждения.', 28153),
(156160, 'ruRU', 'Давай украдем немного оружия и двинем отсюда.', 'Давай украдем немного оружия и двинем отсюда.', 28153),
(156159, 'ruRU', 'Покупать и продавать тех, с кем можно поговорить... это неправильно.', 'Покупать и продавать тех, с кем можно поговорить... это неправильно.', 28153),
(156158, 'ruRU', 'Помешивание', 'Помешивание', 28153),
(156157, 'ruRU', 'Мы, вульперы, больше не будем это терпеть!', 'Мы, вульперы, больше не будем это терпеть!', 28153),
(156156, 'ruRU', 'Они еще не видели меня в гневе!', '', 28153),
(156155, 'ruRU', 'Надеюсь, я больше не увижу ни одного сетрака.', 'Надеюсь, я больше не увижу ни одного сетрака.', 28153),
(156154, 'ruRU', 'Не стоит дразнить черепаху!', '', 28153),
(156153, 'ruRU', 'Кажется, они хотели меня съесть!', 'Кажется, они хотели меня съесть!', 28153),
(156152, 'ruRU', 'Клянусь песками, как же здорово, что ты здесь!', 'Клянусь песками, как же здорово, что ты здесь!', 28153),
(156151, 'ruRU', '', 'Столько лет прошло, а ты все еще продолжаешь мне докучать.', 28153),
(156150, 'ruRU', '', 'Настоящая битва – впереди.', 28153),
(156149, 'ruRU', '', 'Я сделаю все, что смогу.', 28153),
(156148, 'ruRU', '', 'Наш путь не будет легким.', 28153),
(156147, 'ruRU', 'Это больнее, чем я думал.', 'Это больнее, чем я думала.', 28153),
(156146, 'ruRU', 'Мне удалось стащить пару их кристаллов... теперь посмотрим, кто будет смеяться последним. Ха!', '', 28153),
(156145, 'ruRU', 'Этот панцирь не продается!', '', 28153),
(156144, 'ruRU', 'Я этим сетракам все равно не по карману.', '', 28153),
(156143, 'ruRU', 'Отступники не уважают возраст и мудрость.', '', 28153),
(156142, 'ruRU', 'Я об этом расскажу всем в Зулдазаре!', '', 28153),
(156141, 'ruRU', '', 'Наш мир не должен погрузиться во тьму.', 28153),
(156140, 'ruRU', 'Наконец-то удача снова мне улыбнулась!', '', 28153),
(156139, 'ruRU', 'Вождь требует, чтобы мы очистили этот район от Альянса. Иди и расправься с врагами!', '', 28153),
(156138, 'ruRU', '', 'Не время витать в облаках.', 28153),
(156137, 'ruRU', 'Солдаты Альянса заняли территорию неподалеку отсюда. Глупцы... Загляни к ним и наглядно объясни всю тщетность их усилий.', '', 28153),
(156136, 'ruRU', 'Где-то рядом копошатся слуги Альянса. Пусть этот день станет для них последним.', '', 28153),
(156135, 'ruRU', '', 'О чем ты спросишь дочь морей?', 28153),
(156134, 'ruRU', 'Альянс дрогнул! Темная Госпожа будет довольна.', '', 28153),
(156133, 'ruRU', 'Восхитительная жестокость! Теперь Альянс в полной мере ощутил наш гнев.', '', 28153),
(156132, 'ruRU', 'Огонь!', '', 28153),
(156131, 'ruRU', 'В следующий раз Альянс дважды подумает, прежде чем вмешиваться в наши планы.', '', 28153),
(156130, 'ruRU', '', 'Впереди долгий путь.', 28153),
(156129, 'ruRU', 'Задержи дыхание, $p!', '', 28153),
(156128, 'ruRU', '', 'Альянс не сдается.', 28153),
(156127, 'ruRU', '', 'Я знаю, что должна сделать.', 28153),
(156126, 'ruRU', '', 'Одна искра может сжечь весь мир.', 28153),
(156125, 'ruRU', '', 'Обуздай свою силу... иначе она поработит тебя.', 28153),
(156124, 'ruRU', 'За Лордерон.', 'За Лордерон.', 28153),
(156123, 'ruRU', '', 'Я помню. Я все помню.', 28153),
(156122, 'ruRU', '', 'Всех нас преследуют призраки.', 28153),
(156121, 'ruRU', 'Наконец что-то интересное!', 'Наконец что-то интересное!', 28153),
(156120, 'ruRU', '', 'Не все заслуживают доверия.', 28153),
(156119, 'ruRU', 'Моя душа томится...', 'Моя душа томится...', 28153),
(156118, 'ruRU', 'Сейчас прольется кровь!', 'Сейчас прольется кровь!', 28153),
(156117, 'ruRU', 'Быстрые, эффективные убийства – лучшее подспорье для нашей кампании.', '', 28153),
(156116, 'ruRU', 'Как всегда. Еще один враг столкнулся с Ордой и потерпел поражение.', '', 28153),
(156115, 'ruRU', 'Темная Госпожа не ошиблась в тебе.', '', 28153),
(156114, 'ruRU', 'Достойно... Хоть и недостаточно изящно. Можешь возвращаться к своим делам.', '', 28153),
(156113, 'ruRU', 'Что может быть лучше, чем поставить врага на место? Долг есть долг, но ведь важно и наслаждаться победой!', '', 28153),
(156112, 'ruRU', 'Прекрасно. Теперь можно снова действовать по плану.', '', 28153),
(156111, 'ruRU', 'Орда почти захватила эту местность, но нам мешает мощный враг. Очисти дорогу для наших войск.', '', 28153),
(156110, 'ruRU', 'В планах вождя не было ни слова об этом... монстре. Разделайся с ним!', '', 28153),
(156109, 'ruRU', '', 'Тебе никогда не приходило в голову, что это ваша история – альтернативная, а наша – настоящая? Хе-хе, вот ходи теперь и думай...', 28153),
(156108, 'ruRU', 'Рядом с тобой необычный враг. Принеси его труп нашим исследователям, ладно?', '', 28153),
(156107, 'ruRU', 'Поблизости враг, которому наши зеленые рекруты на один зуб. Думаю, \"герой Орды\" справится лучше всех.', '', 28153),
(156106, 'ruRU', '', 'Вот вы сражались с Легионом... а нас позвать не додумались? Серьезно? Судьба Вселенной висела на волоске, а вы даже не попытались... Ой, все!', 28153),
(156105, 'ruRU', 'По данным разведки, неподалеку от тебя сильный враг. Убей его... И не забудь получить удовольствие!', '', 28153),
(156104, 'ruRU', 'Вождь приказывает уничтожить важную цель в этой местности. Не разочаруй мою королеву.', '', 28153),
(156103, 'ruRU', '', 'С тех пор, как я попала в Оргриммар, у стражи улучшилась осанка.', 28153),
(156102, 'ruRU', '', 'Какой-то орк предложил мне вступить в партию \"зеленых\"... И я сломала ему позвоночник.', 28153),
(156101, 'ruRU', 'Я как раз проголодался...', 'Я как раз проголодалась...', 28153),
(156100, 'ruRU', '', 'Говори быстрее. Нас ждет битва!', 28153),
(156099, 'ruRU', '', 'Сердца маг\'харов чисты и непреклонны.', 28153),
(156098, 'ruRU', '', 'Мы пришли побеждать.', 28153),
(156097, 'ruRU', '', 'Я тебя выслушаю... но судить буду по поступкам.', 28153),
(156096, 'ruRU', '', 'Представить не могу, что случилось бы, позволь мы им продолжать эти ритуалы. Спасибо тебе за помощь.', 28153),
(156095, 'ruRU', '', 'Говори.', 28153),
(156094, 'ruRU', '', 'Когда-нибудь я снова увижу небо Дренора.', 28153),
(156093, 'ruRU', '', 'Война – наша жизнь.', 28153),
(156092, 'ruRU', '', 'Пусть враги падут перед тобой.', 28153),
(156091, 'ruRU', '', 'Корлейнские ведьмы хотят провести какой-то новый ритуал. Останови их, пока не поздно!', 28153),
(156090, 'ruRU', '', 'Дерись с честью. Умри со славой!', 28153),
(156089, 'ruRU', '', 'Маг\'хары победят.', 28153),
(156088, 'ruRU', '', 'Умри достойно.', 28153),
(156087, 'ruRU', '', 'Иди с честью.', 28153),
(156086, 'ruRU', '', 'Тром-ка!', 28153),
(156085, 'ruRU', '', 'Лок\'тар!', 28153),
(156084, 'ruRU', 'Бедняжки... Вечной им свободы.', '', 28153),
(156083, 'ruRU', 'Ведьмы прокляли здешних соколов. Мне очень жаль, но птиц уже не спасти. Как с ними справиться? Вот, возьми эти луковицы!', '', 28153),
(156082, 'ruRU', '', 'Прекрасно. Когда уже Альянс поймет, что зандаларов не остановить?', 28153),
(156081, 'ruRU', '', 'Очень хорошо. Альянс должен бояться мощи зандаларов.', 28153),
(156080, 'ruRU', '', 'Скоро Альянс поймет, что зандаларов невозможно покорить.', 28153),
(156079, 'ruRU', '', 'Мне сообщили, что Альянс собирает здесь войска. Не знаю, что они задумали, но им надо помешать.', 28153),
(156078, 'ruRU', '', 'Альянс хочет бросить вызов империи Зандалари. Объясни им, что это ошибка.', 28153),
(156077, 'ruRU', '', 'Так, братва, мы поднимаем бунт! Туманные Паруса не продают свободу!', 28153),
(156076, 'ruRU', '', 'Сперва меня раздражало, когда передо мной падали ниц. А теперь... пообвыклась. Ну, чего стоишь? Падай!', 28153),
(156075, 'ruRU', '', 'Альянс здесь, и они что-то задумали... Убей их всех. Зандаларов должны бояться!', 28153),
(156074, 'ruRU', 'Теперь проблема решена, и можно немного расслабиться.', '', 28153),
(156073, 'ruRU', 'Солдаты Альянса никогда не забудут твоей доблести.', '', 28153),
(156072, 'ruRU', 'Спасибо. Как-нибудь расскажу тебе о Третьей войне. Сейчас все почти как тогда.', '', 28153),
(156071, 'ruRU', 'Замечательно. Эти ресурсы нам точно пригодятся.', '', 28153),
(156070, 'ruRU', 'Нам никак не удается захватить эту область. Прямо как во Вторую войну... Поможешь?', '', 28153),
(156069, 'ruRU', 'У нас тут возникли кое-какие проблемы. Поможешь их решить?', '', 28153),
(156068, 'ruRU', '', 'Конечно, у меня сложные отношения с отцом. Любой предок не сахар, особенно алмазный!', 28153),
(156067, 'ruRU', 'Эти земли нам очень пригодятся. Очисти их от врагов.', '', 28153),
(156066, 'ruRU', 'Мы узнали, что где-то рядом можно найти ценные ресурсы. Добудем их – и получим преимущество.', '', 28153),
(156065, 'ruRU', '', 'Давай проверим, как далеко ты убежишь без коленных чашечек!', 28153),
(156064, 'ruRU', 'Не делай императору облом.', '', 28153),
(156063, 'ruRU', 'Что ты здесь делаешь?', 'Что ты здесь делаешь?', 28153),
(156062, 'ruRU', '', 'Мы с Киро просто шли мимо. Наша цель – империя отступников! \n\nСкоро мой план будет приведен в исполнение. \n\nСетраки даже не успеют понять, откуда пришел удар.', 28153),
(156061, 'ruRU', '', 'Какая встреча.', 28153),
(156060, 'ruRU', 'Захватив эти земли, мы почтили память павших солдат 7-го легиона. Спасибо тебе.', '', 28153),
(156059, 'ruRU', 'Хорошо. Об остальном мы сами позаботимся.', '', 28153),
(156058, 'ruRU', '', 'Мой народ живет внутри вулкана. Ткнешь меня еще раз, и я покажу тебе стихийное бедствие!', 28153),
(156057, 'ruRU', 'Блестящая тактика. Мы найдем применение новой территории.', '', 28153),
(156056, 'ruRU', 'Прекрасно! Этих ресурсов 7-му легиону надолго хватит.', '', 28153),
(156055, 'ruRU', 'Помоги нам захватить эту территорию. Мои войска не справляются.', '', 28153),
(156054, 'ruRU', 'Мы потеряли несколько солдат при захвате этой местности. Покончи с угрозой.', '', 28153),
(156053, 'ruRU', 'Разведчики 7-го легиона считают, что эта область чрезвычайно важна для нас. Очисти ее от врагов.', '', 28153),
(156052, 'ruRU', '', 'Три Клана едины.', 28153),
(156051, 'ruRU', 'Эта область богата ресурсами, которые нужны 7-му легиону. Добудь их любым способом.', '', 28153),
(156050, 'ruRU', '', 'Верной руки и крепкого молота.', 28153),
(156049, 'ruRU', '', 'Да хранит тебя Черная наковальня.', 28153),
(156048, 'ruRU', '', 'Наш клан займет достойное место в мире.', 28153),
(156047, 'ruRU', '', 'Ступай. Я занята!', 28153),
(156046, 'ruRU', '', 'Иди, я разрешаю.', 28153),
(156045, 'ruRU', '', 'Можешь идти.', 28153),
(156044, 'ruRU', 'Бомбардируйте эту цель!', 'Бомбардируйте эту цель!', 28153),
(156043, 'ruRU', 'Орудия! Огонь!', 'Орудия! Огонь!', 28153),
(156042, 'ruRU', 'Цель отмечена, уничтожьте ее!', 'Цель отмечена, уничтожьте ее!', 28153),
(156041, 'ruRU', 'Артиллерия! Огонь по цели!', 'Артиллерия! Огонь по цели!', 28153),
(156040, 'ruRU', '', 'Меньше слов, больше дела.', 28153),
(156039, 'ruRU', '', 'Ну? Я слушаю.', 28153),
(156038, 'ruRU', '', 'Помни о манерах – перед тобой королева.', 28153),
(156037, 'ruRU', 'Рад видеть, что пески еще не поглотили тебя.', '', 28153),
(156036, 'ruRU', '', 'Гора дает нам силу.', 28153),
(156035, 'ruRU', '', 'Ты говоришь с королевой-регентом клана Черного Железа.', 28153),
(156034, 'ruRU', '', 'Клан Черного Железа достоин уважения.', 28153),
(156033, 'ruRU', '', 'Альянсу нужны наши магия и сила.', 28153),
(156032, 'ruRU', 'Одевание', 'Одевание', 28153),
(156031, 'ruRU', 'Очищает', 'Очищает', 28153),
(156030, 'ruRU', '', 'Великолепно. Эти ресурсы пригодятся зандаларам.', 28153),
(156029, 'ruRU', '', 'Чудесно. Скоро все узнают, как опасно вставать на пути у зандаларов.', 28153),
(156028, 'ruRU', '', 'Еще одна победа во славу зандаларов и Орды. Нам повезло с таким сильным союзником.', 28153),
(156027, 'ruRU', '', 'Зандалары благодарны тебе за труды.', 28153),
(156026, 'ruRU', '', 'Натанос думает, что мы не захватим эту землю. Он ошибается.', 28153),
(156025, 'ruRU', '', 'Чтобы продолжить кампанию, надо очистить эту область от врагов. Ты знаешь, что делать.', 28153),
(156024, 'ruRU', '', 'Эти земли необходимы нашим союзникам. Не жалей тех, кто встанет у тебя на пути.', 28153),
(156023, 'ruRU', '', 'Поблизости есть ресурсы, которые пригодятся для нашей кампании. Добудь их.', 28153),
(156022, 'ruRU', 'Крапинка и Долли это мигом слопают.', '', 28153),
(156021, 'ruRU', 'Долли и Крапинка на пустой желудок работать не будут. Помоги найти для них еду.', '', 28153),
(156020, 'ruRU', 'Кыш!', 'Кыш!', 28153),
(156019, 'ruRU', 'Уходи!', 'Уходи!', 28153),
(156018, 'ruRU', 'Не трогай!', 'Не трогай!', 28153),
(156017, 'ruRU', 'Еще шаг, и я врежу тебе камнем по голове!', 'Еще шаг, и я врежу тебе камнем по голове!', 28153),
(156016, 'ruRU', 'Убирайся, или я тебя убью!', 'Убирайся, или я тебя убью!', 28153),
(156015, 'ruRU', '', 'Иди, добудь все нужное для лечения змея. А я расскажу Джулвабе, что мы узнали.', 28153),
(156014, 'ruRU', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|aДоступно новое здание!', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|aДоступно новое здание!', 28153),
(156013, 'ruRU', 'Я служил многим вождям. Иди, посмотри мир. Наверняка пару-тройку из них встретишь.', '', 28153),
(156012, 'ruRU', 'Ну что ты тыкаешь? Война началась, что ли? Хотя... война-то и не заканчивалась.', '', 28153),
(156011, 'ruRU', 'Те, кто знает, сколько крови выпил мой топор, остерегаются дергать меня по пустякам!', '', 28153),
(156010, 'ruRU', 'Я слишком стар для этого... бреда.', '', 28153),
(156009, 'ruRU', 'Служу Орде.', '', 28153),
(156008, 'ruRU', 'Говори быстро... и только правду.', '', 28153),
(156007, 'ruRU', 'Не время для любезностей.', '', 28153),
(156006, 'ruRU', 'Чего ты хочешь?', '', 28153),
(156005, 'ruRU', 'Тром-ка!', '', 28153),
(156004, 'ruRU', 'Лок\'тар!', '', 28153),
(156003, 'ruRU', 'Я Саурфанг. Брат Броксигара.', '', 28153),
(156002, 'ruRU', 'Орда не сдается.', '', 28153),
(156001, 'ruRU', 'Мне тут больше не нравится. Я побежал!', 'Мне тут больше не нравится. Я побежала!', 28153),
(156000, 'ruRU', 'В бою стратегия не менее важна, чем сила.', '', 28153),
(155999, 'ruRU', 'Ура! Я свободен!', 'Ура! Я свободна!', 28153),
(155998, 'ruRU', 'Пора валить отсюда!', 'Пора валить отсюда!', 28153),
(155997, 'ruRU', 'В нас – истинная мощь Калимдора.', '', 28153),
(155996, 'ruRU', 'Почему это происходит?', 'Почему это происходит?', 28153),
(155995, 'ruRU', 'Я не хочу умирать... прикрой меня!', 'Я не хочу умирать... прикрой меня!', 28153),
(155994, 'ruRU', 'Что происходит?!', 'Что происходит?!', 28153),
(155993, 'ruRU', 'Осторожно, тут везде сумасшедшие люди!', 'Осторожно, тут везде сумасшедшие люди!', 28153),
(155992, 'ruRU', 'Старости лучше избегать.', '', 28153),
(155991, 'ruRU', 'Без чести нет жизни.', '', 28153),
(155990, 'ruRU', 'Настоящий орк умирает на поле боя.', '', 28153),
(155989, 'ruRU', 'Желаю погибнуть в бою с заклятым врагом.', '', 28153),
(155988, 'ruRU', 'Проследи, чтобы Ло добрался до убежища в водорослях.', '', 28153),
(155987, 'ruRU', '\"Ло и море\". Юный тортоллан должен отыскать безопасное убежище сразу после рождения среди песков.', '', 28153),
(155986, 'ruRU', '', 'Угроза миновала, и дровосеки могут спокойно продолжать работу. Спасибо.', 28153),
(155985, 'ruRU', 'Пожалуй, я это сотру...', '', 28153),
(155984, 'ruRU', '', 'Прислужники ведьм мешают нам добывать древесину. Собери дровосеков и прогони врагов!', 28153),
(155983, 'ruRU', '', 'Лощина Лучников снова свободна! Спасибо тебе за это!', 28153),
(155982, 'ruRU', '', 'Ковен захватил Лощину Лучников! Освободи горожан и уничтожь источники порчи.', 28153),
(155981, 'ruRU', 'Тсс! Иди сюда, $n!', '', 28153),
(155980, 'ruRU', '', 'Следуй зову чести.', 28153),
(155979, 'ruRU', '', 'Когда время придет, я не подведу.', 28153),
(155978, 'ruRU', '', 'Сделай то, что нужно.', 28153),
(155977, 'ruRU', '', 'Надо помогать тем, кто не может спастись сам.', 28153),
(155976, 'ruRU', '', 'Грош нам цена без чести.', 28153),
(155975, 'ruRU', '', 'Разболтаешь хоть ЕДИНОЙ ДУШЕ – скормлю тебя грифону. Ясно?', 28153),
(155974, 'ruRU', '', 'Я никогда не сдамся.', 28153),
(155973, 'ruRU', '', '(фыркает) Ой... это... Это не я!', 28153),
(155972, 'ruRU', '', 'Я... тренированный... солдат... с железными... нервами...', 28153),
(155971, 'ruRU', '', 'Перестань! Мне щекотно!', 28153),
(155970, 'ruRU', '', 'Эй! Хватит!', 28153),
(155969, 'ruRU', '', 'Мы справимся.', 28153),
(155968, 'ruRU', '', 'Служи с честью.', 28153),
(155967, 'ruRU', '', 'Не сбивайся с курса.', 28153),
(155966, 'ruRU', '', 'Попутного ветра, друзья. Я останусь здесь и буду сражаться вместе с остальными вульперами.', 28153),
(155965, 'ruRU', '', 'Возвращайся с новыми историями!', 28153),
(155964, 'ruRU', '', 'За Кул-Тирас!', 28153),
(155963, 'ruRU', '', 'Долг зовет.', 28153),
(155962, 'ruRU', '', 'Прощай.', 28153),
(155961, 'ruRU', '', 'Доложи обстановку.', 28153),
(155960, 'ruRU', '', 'Наконец-то нашлось дело!', 28153),
(155959, 'ruRU', '', 'Я всю жизнь готовилась к этому.', 28153),
(155956, 'ruRU', '', 'Вместе мы объединим Кул-Тирас.', 28153),
(155955, 'ruRU', '', 'Я всегда мечтала о приключениях.', 28153),
(155953, 'ruRU', 'Долина – наш единственный дом.', '', 28153),
(155952, 'ruRU', 'Прикрывай меня, а я прикрою тебя.', '', 28153),
(155950, 'ruRU', 'Будь осторожнее. Береги себя.', '', 28153),
(155947, 'ruRU', 'Мы с тобой заодно.', '', 28153),
(155946, 'ruRU', '', 'Уровень заряда почти достиг максимума.', 28153),
(155945, 'ruRU', '', 'Внимание: лазер пересозидания почти заряжен.', 28153),
(155944, 'ruRU', '', 'Внимание: критический уровень заряда.', 28153),
(155943, 'ruRU', '', 'Уровень заряда близок к максимальному.', 28153),
(155942, 'ruRU', 'Упорный труд – средство от всех проблем.', '', 28153),
(155941, 'ruRU', 'Долина мне дороже всего.', '', 28153),
(155939, 'ruRU', '', 'Чем могу помочь?', 28153),
(155938, 'ruRU', 'В глубинах раздается голос, его услышишь ты вот-вот: \"Не щелкай мышью брата Пайка, удод!\"', '', 28153),
(155937, 'ruRU', 'О, они вполне пригодны для совершенно разных целей!$b$bПомимо очевидного применения в качестве острого инструмента для прокалывания, сами иглы обладают несколькими полезными свойствами. Если их растереть в порошок, получится замечательное вяжущее средство. Их можно сварить и полученный жир будет прекрасным моющим средством. Ну, а в крайнем случае они сойдут за зубочистки!', '', 28153),
(155936, 'ruRU', 'Придется самому убить тебя и всех твоих тупых друзей!', '', 28153),
(155935, 'ruRU', 'Тонго... убит чужаком? Видать, я его переоценивал!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155934, 'ruRU', 'Только не так... нет... Ах...', '', 28153),
(155933, 'ruRU', 'Я дал клятву оберегать мир на этой земле. Но для тебя сделаю исключение.', '', 28153),
(155932, 'ruRU', 'Тормоши меня сколько угодно. Жрецы моря бесконечно терпеливы.', '', 28153),
(155931, 'ruRU', '', 'Рада встрече!', 28153),
(155930, 'ruRU', 'А зачем нужны эти иглы?', 'А зачем нужны эти иглы?', 28153),
(155929, 'ruRU', 'Подношение', 'Подношение', 28153),
(155928, 'ruRU', 'По-моему, кто-то накидался и не поделился со мной. Обидно до жути.', '', 28153),
(155927, 'ruRU', 'Вольно, матрос. Я, конечно, неотразим, но у нас еще есть дела.', '', 28153),
(155926, 'ruRU', 'Ну, конечно, если тебя не загнали на флот силой... Или не захватили пираты... а потом загнали на флот силой...', '', 28153),
(155925, 'ruRU', 'Эх, открытое море, удалая песня, ветер треплет непокорные локоны на груди. Вот это СВОБОДА.', '', 28153),
(155924, 'ruRU', 'Не оглядывайся назад.', '', 28153),
(155923, 'ruRU', 'Стремись за горизонт.', '', 28153),
(155922, 'ruRU', 'В следующий раз я угощаю!', '', 28153),
(155921, 'ruRU', 'Пора за деньжатами!', '', 28153),
(155920, 'ruRU', 'До скорого.', '', 28153),
(155919, 'ruRU', '<Король Растахан тяжело и часто дышит. Повязки на его груди пропитались кровью.>', '', 28153),
(155918, 'ruRU', 'Береги себя.', '', 28153),
(155917, 'ruRU', 'Держи порох сухим.', '', 28153),
(155916, 'ruRU', 'Что расскажешь?', '', 28153),
(155915, 'ruRU', 'Прекрасно! Начну готовить зелья прямо сейчас. Наверняка местные рыбаки тоже обрадуются, что птиц стало меньше.', '', 28153),
(155914, 'ruRU', 'Я Джамиль Абул\'хусин, королевский лекарь. Уже не в первый раз я исцеляю раны короля – и, если на то будет воля лоа, не последний.', '', 28153),
(155913, 'ruRU', 'Я хочу добыть образцы местной морской фауны для реагентов, но мне постоянно мешают чайки. Принеси мне реагенты и избавься от этих проклятых птиц!', '', 28153),
(155912, 'ruRU', 'Как идет исцеление?', 'Как идет исцеление?', 28153),
(155911, 'ruRU', 'Да... Да! Пусть эти земли познают всю мощь Орды!', '', 28153),
(155910, 'ruRU', 'За долгие годы мы с Растаханом прошли через многое. Но это...\n\n<Джамиль указывает на бездыханного короля.>\n\nЭто плохо.', '', 28153),
(155909, 'ruRU', '<Джол не отрывается от своих зелий.>\n\nУ короля осталось мало времени.', '', 28153),
(155908, 'ruRU', 'Работа есть работа.', '', 28153),
(155907, 'ruRU', 'Хорошо. Жаль, что эту угрозу нельзя было обратить против наших врагов.', '', 28153),
(155906, 'ruRU', 'Рядом с тобой мощный враг, с которым у наших солдат возникли... затруднения. Думаю, ты знаешь, что делать.', '', 28153),
(155905, 'ruRU', 'Вождь будет довольна твоими успехами.', '', 28153),
(155904, 'ruRU', 'Поблизости рыщет опасный враг. Уничтожь его, пока он не нарушил наши планы.', '', 28153),
(155903, 'ruRU', 'Враги, обосновавшиеся здесь, явно не согласны с нашими планами. Вождь приказала решить эту проблему. Не подведи ее.', '', 28153),
(155902, 'ruRU', 'Как Реник мог это допустить?', 'Как Реник мог это допустить?', 28153),
(155901, 'ruRU', 'Сколько можно?!', 'Сколько можно?!', 28153),
(155900, 'ruRU', 'Кто-то за это заплатит!', 'Кто-то за это заплатит!', 28153),
(155899, 'ruRU', 'Почему с грогом вечно что-то происходит?', 'Почему с грогом вечно что-то происходит?', 28153),
(155898, 'ruRU', 'Не трогай грог!', 'Не трогай грог!', 28153),
(155897, 'ruRU', 'У всего есть цена. Кто-то платит золотом, а кто-то – кровью.', '', 28153),
(155896, 'ruRU', 'Все должно было закончиться совсем не так. Попробуешь еще раз?', '', 28153),
(155895, 'ruRU', 'Хочешь пить? Я – так очень!', '', 28153),
(155894, 'ruRU', 'Я весь внимание.', '', 28153),
(155893, 'ruRU', 'Какие новости?', '', 28153),
(155892, 'ruRU', 'Здорово.', '', 28153),
(155891, 'ruRU', 'Осторожнее там.', '', 28153),
(155890, 'ruRU', 'До скорого.', '', 28153),
(155889, 'ruRU', 'Бывай!', '', 28153),
(155888, 'ruRU', 'Грог или эль? Или все сразу?', '', 28153),
(155887, 'ruRU', 'Что на этот раз?', '', 28153),
(155886, 'ruRU', 'Прекрасно, $n!', '', 28153),
(155885, 'ruRU', 'Ну, чем пригодишься?', '', 28153),
(155884, 'ruRU', 'Поможешь Ло собрать всю еду и вернуться домой, не пересекая собственные следы?', '', 28153),
(155883, 'ruRU', '\"Спокойная жизнь\". Однажды Ло решил отправиться жить на тихий уединенный остров.', '', 28153),
(155882, 'ruRU', 'Знаешь, как во Вторую войну называли таких вот надоедливых? \"Прилипалы\"!', '', 28153),
(155881, 'ruRU', 'Часто странствия Ло были полны опасностей. Взять, например, эту историю...', '', 28153),
(155880, 'ruRU', 'Наш народ любит историю о Ло – юном тортоллане, путешествовавшем по миру.', '', 28153),
(155879, 'ruRU', 'Чего тебе, байку рассказать?', '', 28153),
(155878, 'ruRU', 'В мое время затягивать беседу было неприлично.', '', 28153),
(155877, 'ruRU', '', 'Цикл жизни бывает жестоким...', 28153),
(155876, 'ruRU', '', 'Черепаха добралась до воды!', 28153),
(155875, 'ruRU', '', 'Спасибо, $n!', 28153),
(155874, 'ruRU', '', 'С первых дней своей жизни тортолланы окружены множество врагов... прямо как эти черепахи! Помоги им добраться до океана!', 28153),
(155873, 'ruRU', '', 'Браво! Неординарное, но эффективное применение геологической техники.', 28153),
(155872, 'ruRU', '', 'Увидите кого-нибудь без пропуска – убивайте на месте!', 28153),
(155871, 'ruRU', '', 'Какой придурок потерял несколько ящиков с бомбами?', 28153),
(155870, 'ruRU', '', 'На Заставе Арома смогли запустить ордынскую буровую машину. Обрати ее против ее же создателей!', 28153),
(155869, 'ruRU', '', 'Я закрою дыры в бюджете за счет твоей зарплаты!', 28153),
(155868, 'ruRU', '', 'Возможно, придется провести сокращение. Бюджет-то не резиновый!', 28153),
(155867, 'ruRU', 'Чужаки в литейной! Повторяю, чужа...', 'Чужаки в литейной! Повторяю, чужа...', 28153),
(155866, 'ruRU', 'Следуй голосу чести.', '', 28153),
(155865, 'ruRU', 'За лорда-адмирала.', '', 28153),
(155864, 'ruRU', 'За Кул-Тирас.', '', 28153),
(155863, 'ruRU', 'Не показывай врагам усталости!', '', 28153),
(155862, 'ruRU', 'Не теряй бдительности.', '', 28153),
(155861, 'ruRU', 'Попутного ветра и семь футов под килем.', '', 28153),
(155860, 'ruRU', 'Вольно!', '', 28153),
(155859, 'ruRU', '', '', 28153),
(155858, 'ruRU', '', '', 28153),
(155857, 'ruRU', 'Докладывай!', '', 28153),
(155856, 'ruRU', '', '', 28153),
(155855, 'ruRU', 'Я навоевался на две жизни вперед.', '', 28153),
(155854, 'ruRU', 'Есть вести с фронта?', '', 28153),
(155853, 'ruRU', 'Чего тебе надо?', '', 28153),
(155852, 'ruRU', 'Старые кости соскучились по битве.', '', 28153),
(155851, 'ruRU', 'Доложись!', '', 28153),
(155850, 'ruRU', 'Рад встрече!', '', 28153),
(155849, 'ruRU', '', 'Ни о чем не проси.', 28153),
(155848, 'ruRU', '', 'Ветер и волны дарят нам свободу.', 28153),
(155847, 'ruRU', '', 'Кул-Тирас переживет любой шторм.', 28153),
(155846, 'ruRU', '', 'Я выслушаю тебя.', 28153),
(155845, 'ruRU', '', 'Говори.', 28153),
(155844, 'ruRU', 'Не время сдаваться.', '', 28153),
(155843, 'ruRU', 'Не бойся смены течений.', '', 28153),
(155842, 'ruRU', 'Пусть волны несут тебя.', '', 28153),
(155841, 'ruRU', 'Не забывай о павших.', '', 28153),
(155840, 'ruRU', 'Море знает все ответы.', '', 28153),
(155839, 'ruRU', '', 'У меня нет времени на пустые разговоры.', 28153),
(155838, 'ruRU', 'В каждом из нас дремлет шторм.', '', 28153),
(155837, 'ruRU', 'Я хочу сразиться на дуэли.', 'Я хочу сразиться на дуэли.', 28153),
(155836, 'ruRU', 'Нет. Попробуй еще раз.', '', 28153),
(155835, 'ruRU', 'О, подходит!', '', 28153),
(155834, 'ruRU', 'Прекрасно, $n!', '', 28153),
(155833, 'ruRU', 'Я много вещей собрал за свою жизнь. Попробуй их рассортировать!', '', 28153),
(155832, 'ruRU', 'Если ты любишь летать, навести Па\'ку, повелительницу ветров. Ее тотемы быстро перенесут тебя по воздуху в любую точку города.', '', 28153),
(155831, 'ruRU', '', 'Гонк – могучий лоа охоты и мастер перевоплощения. Его тотемы в городе придадут тебе ускорение, если ты окажешься рядом с ними.', 28153),
(155830, 'ruRU', 'Волны рассказали о тебе.', '', 28153),
(155829, 'ruRU', 'Слушаю.', '', 28153),
(155828, 'ruRU', 'Чем могу помочь?', '', 28153),
(155827, 'ruRU', 'Легкого плавания.', '', 28153),
(155826, 'ruRU', 'Поднять трап, мы отчаливаем! Чего мне не хватало, так это лишних дырок в борту.', '', 28153),
(155825, 'ruRU', 'Видать, тоже приплыли за азеритом. Какие молодцы! Только они опоздали. Убираемся отсюда, пока нас не заметили.', '', 28153),
(155824, 'ruRU', 'Ну, вот и все. Мы добыли все, что могли, и как раз вовремя: на горизонте зандаларский корабль.', '', 28153),
(155823, 'ruRU', 'Они тоже добывали азерит? Как удобно. Просто убейте их и заберите добычу.', '', 28153),
(155822, 'ruRU', 'Хозены? Здесь? Никогда не угадаешь, кого встретишь на этих островах.', '', 28153),
(155821, 'ruRU', 'Где-то рядом находится крупный груз азерита. У меня уже руки чешутся.', '', 28153),
(155820, 'ruRU', 'Чудесно! Конечно, крови многовато, но что поделать? Азерит не пахнет.', '', 28153),
(155819, 'ruRU', 'Ого-го, да это чудище, полностью покрытое азеритом. Убейте его и добудьте ценный ресурс.', '', 28153),
(155818, 'ruRU', 'Детектор показывает еще одно скопление азерита неподалеку от вас. Гляньте, что там.', '', 28153),
(155817, 'ruRU', 'Вот это да! Вот это урвали! Молодцы!', '', 28153),
(155816, 'ruRU', 'Ух ты, вот это лакомый кусочек! Вы извлеките его, а мы уж займемся транспортировкой на корабль.', '', 28153),
(155815, 'ruRU', 'Наш детектор азерита показывает поблизости месторождение... гм, азерита. Может, сходите и проверите? Я пока здесь подожду.', '', 28153),
(155814, 'ruRU', 'Давайте, швартуйтесь, только не врежьтесь в берег. И опустите трап.', '', 28153),
(155813, 'ruRU', 'Правда, вместе с ним мы можем найти еще и гигантских пауков. Никогда не знаешь, что тебя ждет.', '', 28153),
(155812, 'ruRU', 'Мы на месте. Уверен, азерит, который мы ищем, должен быть где-то здесь.', '', 28153),
(155811, 'ruRU', '$n! Хвала Темной Госпоже, ты здесь! Рексару удалось заманить култирасцев в те здания. Но ему нужна помощь!', '$n! Хвала Темной Госпоже, ты здесь! Рексару удалось заманить култирасцев в те здания. Но ему нужна помощь!', 28153),
(155810, 'ruRU', 'Скорее, спускайся на нижнюю палубу и становись за пушку! Нашим войскам нужна поддержка!', '', 28153),
(155809, 'ruRU', 'Вот все, что осталось от Вадекия. Он был сильным драконом.', 'Вот все, что осталось от Вадекия. Он был сильным драконом.', 28153),
(155808, 'ruRU', 'Только ни на что не рассчитывай.', 'Только ни на что не рассчитывай.', 28153),
(155807, 'ruRU', 'Чтобы убить его, нужна была поистине темная мощь.', 'Чтобы убить его, нужна была поистине темная мощь.', 28153),
(155806, 'ruRU', 'Вот все, что осталось от Вадекия. Он был сильным драконом.', 'Вот все, что осталось от Вадекия. Он был сильным драконом.', 28153),
(155805, 'ruRU', 'Но это уже кое-что.', 'Но это уже кое-что.', 28153),
(155804, 'ruRU', 'Мое сердце не такое доброе, как у королевы.', 'Мое сердце не такое доброе, как у королевы.', 28153),
(155803, 'ruRU', 'То, что ты сделал с Киранастразом, не так-то просто сбросить со счетов.', 'То, что ты сделала с Киранастразом, не так-то просто сбросить со счетов.', 28153),
(155802, 'ruRU', 'Спасибо, наверное.', 'Спасибо, наверное.', 28153),
(155801, 'ruRU', 'Спасибо тебе за помощь, $n.', 'Спасибо тебе за помощь, $n.', 28153),
(155800, 'ruRU', 'Мы не хотим, чтобы эти ужасные события вновь повторились.', 'Мы не хотим, чтобы эти ужасные события вновь повторились.', 28153),
(155799, 'ruRU', 'Чтобы найти его последнее пристанище, в Рубиновое святилище вторгся могущественный рыцарь смерти.', 'Чтобы найти его последнее пристанище, в Рубиновое святилище вторгся могущественный рыцарь смерти.', 28153),
(155798, 'ruRU', 'Во время последней войны с Легионом одну из наших дракониц превратили в нежить.', 'Во время последней войны с Легионом одну из наших дракониц превратили в нежить.', 28153),
(155797, 'ruRU', 'Тогда мы с |3-4($n) займемся делом. Пойдем, |3-6($c), я отвезу тебя к месту проведения ритуала.', 'Тогда мы с |3-4($n) займемся делом. Пойдем, |3-6($c), я отвезу тебя к месту проведения ритуала.', 28153),
(155796, 'ruRU', '', 'Вижу, $n возвращается. Вот кто сможет тебе помочь, Заллестраза.', 28153),
(155795, 'ruRU', 'Ты слишком суетишься! Мне уже гораздо лучше.', 'Ты слишком суетишься! Мне уже гораздо лучше.', 28153),
(155794, 'ruRU', 'Не дергайся, дай мне тебя исцелить.', 'Не дергайся, дай мне тебя исцелить.', 28153),
(155793, 'ruRU', 'Тео, ты едва можешь сидеть!', 'Тео, ты едва можешь сидеть!', 28153),
(155792, 'ruRU', '', 'Отлично, $n! А теперь пройдем в мой новый офис.', 28153),
(155791, 'ruRU', '', 'Этот был мой. Я их считаю!', 28153),
(155790, 'ruRU', 'Мне нужна огромная сила, чтобы сразиться с Кортеком. В бою он всегда меня превосходил.\n\nЯ вытяну все, что смогу, из этих кристаллов – будем надеяться, этого хватит.', '', 28153),
(155789, 'ruRU', '', 'Пауков стало значительно меньше, и теперь охотники смогут ходить на промысел, не боясь угодить в паутину.', 28153),
(155788, 'ruRU', '', 'В лесах завелись опасные пауки. Помоги охотникам Друствара, уничтожь их!', 28153),
(155787, 'ruRU', 'Замена', 'Замена', 28153),
(155786, 'ruRU', '', 'Спасибо. Эти припасы помогут нашим солдатам в суровом климате.', 28153),
(155785, 'ruRU', '', 'Наши разведчики говорят, что эти люди придумали способ добывать мех, не вредя животным. Способ странный... но эффективный.', 28153),
(155784, 'ruRU', 'Рядом с лесопилкой видели жуткое существо... Совсем рядом с Боралусом!', '', 28153),
(155783, 'ruRU', 'Прекрасно! Монстр был обречен уже тогда, когда показался на берегах Кул-Тираса.', '', 28153),
(155782, 'ruRU', 'Гарпунщики наткнулись на что-то крупное. Им бы пригодилась твоя помощь.', '', 28153),
(155781, 'ruRU', 'Поджигание', 'Поджигание', 28153),
(155780, 'ruRU', 'Мы с тобою заодно. Я не отступлю!', 'Мы с тобою заодно. Я не отступлю!', 28153),
(155779, 'ruRU', 'Если сегодня мне суждено умереть... то я умру, сражаясь!', 'Если сегодня мне суждено умереть... то я умру, сражаясь!', 28153),
(155778, 'ruRU', 'Моджамбо меня живым не возьмет!', 'Моджамбо меня живой не возьмет!', 28153),
(155777, 'ruRU', 'Я отказываюсь склониться перед Моджамбо и его бандой!', 'Я отказываюсь склониться перед Моджамбо и его бандой!', 28153),
(155776, 'ruRU', 'Я буду сражаться до последнего вздоха!', 'Я буду сражаться до последнего вздоха!', 28153),
(155775, 'ruRU', 'Без битвы мы Моджамбо не сдадимся!', 'Без битвы мы Моджамбо не сдадимся!', 28153),
(155774, 'ruRU', 'Грядет битва. Держи меч и будь наготове.', 'Грядет битва. Держи меч и будь наготове.', 28153),
(155773, 'ruRU', 'Это наш дом. Без боя нас отсюда не выкурят.', 'Это наш дом. Без боя нас отсюда не выкурят.', 28153),
(155772, 'ruRU', '', 'Одной головной болью для морпехов меньше. Спасибо!', 28153),
(155771, 'ruRU', '', 'Вот это да! Наблюдая за тобой, я многому учусь!', 28153),
(155770, 'ruRU', '', 'Благодаря тебе дороги Кул-Тираса стали спокойнее.', 28153),
(155769, 'ruRU', '', 'У наших войск вечно проблемы с истреблением хищников. Давай поможем им!', 28153),
(155768, 'ruRU', '', 'Неподалеку завелся свирепый хищник. Ради Кул-Тираса, убей его!', 28153),
(155767, 'ruRU', '', 'Подобным чудищам не место здесь. Избавься от него!', 28153),
(155766, 'ruRU', 'Валите отсюда куда-нибудь уже!', 'Валите отсюда куда-нибудь уже!', 28153),
(155765, 'ruRU', 'Эй, ты чего на меня так пялишься?', 'Эй, ты чего на меня так пялишься?', 28153),
(155764, 'ruRU', 'Далеко ж вас занесло!', 'Далеко ж вас занесло!', 28153),
(155763, 'ruRU', 'Красный закат – моряк будет рад. Красный рассвет сулит много бед.', '', 28153),
(155762, 'ruRU', 'Я хочу телепортироваться к Г\'ууну.', 'Я хочу телепортироваться к Г\'ууну.', 28153),
(155761, 'ruRU', 'Я хочу телепортироваться к Митраксу.', 'Я хочу телепортироваться к Митраксу.', 28153),
(155760, 'ruRU', 'Я хочу телепортироваться к Зулу.', 'Я хочу телепортироваться к Зулу.', 28153),
(155759, 'ruRU', 'Я хочу телепортироваться к элементалю крови.', 'Я хочу телепортироваться к элементалю крови.', 28153),
(155758, 'ruRU', 'Я хочу телепортироваться к Зек\'возу.', 'Я хочу телепортироваться к Зек\'возу.', 28153),
(155757, 'ruRU', 'Я хочу телепортироваться к зловонному пожирателю.', 'Я хочу телепортироваться к зловонному пожирателю.', 28153),
(155756, 'ruRU', 'Я хочу телепортироваться к МАТРИАРХу.', 'Я хочу телепортироваться к МАТРИАРХу.', 28153),
(155755, 'ruRU', 'Приветствую и благодарю за помощь в тестировании Ульдира!\n\nЯ могу перенести тебя к любому из боссов, доступных для тестирования на данный момент.', 'Приветствую и благодарю за помощь в тестировании Ульдира!\n\nЯ могу перенести тебя к любому из боссов, доступных для тестирования на данный момент.', 28153),
(155754, 'ruRU', '', 'Мой котик пропал.', 28153),
(155753, 'ruRU', 'Если бури не избежать, выдержи ее. Если бурю не выдержать... избегай ее!', '', 28153),
(155752, 'ruRU', 'Не забывай, мокрой стороной вниз!', '', 28153),
(155750, 'ruRU', 'Хочешь увидеть Бвонсамди?', '', 28153),
(155749, 'ruRU', 'Представляю, как печальна и ничтожна жизнь на суше.', '', 28153),
(155748, 'ruRU', 'Когда ты посмотришь на залив Королей и увидишь благословенное голубое пламя, знай, что сегодня благодаря тебе все обернулось в нашу пользу! Это достойная победа, $n. Флот всегда будет принадлежать зандаларам!', '', 28153),
(155747, 'ruRU', 'Имей в виду, протащу под килем – и глазом не моргну.', '', 28153),
(155746, 'ruRU', 'Пусть в жизни будет цель, а в парусах ветер!', '', 28153),
(155745, 'ruRU', 'Увидимся!', '', 28153),
(155744, 'ruRU', 'Счастливо! Море зовет!', '', 28153),
(155743, 'ruRU', 'Спокойное плавание не учит ничему новому.', '', 28153),
(155742, 'ruRU', 'Попутного тебе ветра и семь футов под килем!', '', 28153),
(155741, 'ruRU', 'Надеюсь, волны еще принесут тебя сюда!', '', 28153),
(155740, 'ruRU', 'Вперед, к новым горизонтам!', '', 28153),
(155739, 'ruRU', 'Если в воздухе чувствуется соль, значит ты дома.', '', 28153),
(155738, 'ruRU', 'Таз\'окун! Добро пожаловать!', '', 28153),
(155737, 'ruRU', 'Дело сделано... Правда, крови можно было бы пустить и побольше. Подумай над этим.', '', 28153),
(155736, 'ruRU', 'А, привет-привет!', '', 28153),
(155735, 'ruRU', 'Вождь отдала приказ: захватить эту область во имя Орды. Используй любые средства, которые сочтешь нужными... Ведь победителей не судят.', '', 28153),
(155734, 'ruRU', 'День в открытом море – хороший день!', '', 28153),
(155733, 'ruRU', 'Ну что, айда в великое плавание?', '', 28153),
(155732, 'ruRU', 'Я хочу отправиться в Ульдир (рейд).', 'Я хочу отправиться в Ульдир (рейд).', 28153),
(155731, 'ruRU', 'Хорошо! Теперь и врагов стало меньше, и у птиц появилось безопасное гнездовье.', '', 28153),
(155730, 'ruRU', 'Страшно жду твоего возвращения!', '', 28153),
(155729, 'ruRU', 'Возвращайся поскорее!', '', 28153),
(155728, 'ruRU', 'Целься!', 'Целься!', 28153),
(155727, 'ruRU', 'А, опять ты...', '', 28153),
(155726, 'ruRU', 'Я так понимаю, мне опять придется что-то чинить?', '', 28153),
(155725, 'ruRU', 'Чем могу помочь?', '', 28153),
(155724, 'ruRU', 'Тебе помочь?', '', 28153),
(155723, 'ruRU', 'Прячьтесь за укрытием!!!', 'Прячьтесь за укрытием!!!', 28153),
(155722, 'ruRU', 'Тебе повезло, я сегодня добрый и починю эту штуку... в очередной раз...', '', 28153),
(155721, 'ruRU', 'Серьезно? Они сложили все так, что весь вес пришелся на эту крохотную штучку и она сломалась? Какая неожиданность...', '', 28153),
(155720, 'ruRU', 'Похоже, ума у тебя не больше, чем у моего молота.', '', 28153),
(155719, 'ruRU', 'Уверен, что в прошлый раз я чинил эту же штуковину.', '', 28153),
(155718, 'ruRU', 'Вот бы эти идиоты прекратили все ломать, что за жизнь настала бы тогда...', '', 28153),
(155717, 'ruRU', 'Я хочу отправиться в усадьбу Уэйкрестов (подземелье).', 'Я хочу отправиться в усадьбу Уэйкрестов (подземелье).', 28153),
(155716, 'ruRU', 'Я хочу отправиться в Тол Дагор (подземелье).', 'Я хочу отправиться в Тол Дагор (подземелье).', 28153),
(155715, 'ruRU', 'Я хочу отправиться на осаду Боралуса (подземелье).', 'Я хочу отправиться на осаду Боралуса (подземелье).', 28153),
(155714, 'ruRU', 'Я хочу отправиться в Святилище Штормов (подземелье).', 'Я хочу отправиться в Вольную Гавань (подземелье).', 28153),
(155713, 'ruRU', 'Я хочу отправиться в Вольную Гавань (подземелье).', 'Я хочу отправиться в Вольную Гавань (подземелье).', 28153),
(155712, 'ruRU', 'Ох, спаси меня Дымка, как же я напугался!', '', 28153),
(155711, 'ruRU', 'Рабы проклятых ведьм украли наших птиц! Освободи соколов и убей ведьминых прислужников!', '', 28153),
(155710, 'ruRU', 'Нужны детальки? Приспособления? Штучки-дрючки?', '', 28153),
(155709, 'ruRU', 'Я хочу отправиться в Подгнилье (подземелье).', 'Я хочу отправиться в Подгнилье (подземелье).', 28153),
(155708, 'ruRU', 'Я хочу отправиться на ЗОЛОТУЮ ЖИЛУ (подземелье).', 'Я хочу отправиться на ЗОЛОТУЮ ЖИЛУ (подземелье).', 28153),
(155707, 'ruRU', 'Я хочу отправиться в храм Сетралисс (подземелье).', 'Я хочу отправиться в храм Сетралисс (подземелье).', 28153),
(155706, 'ruRU', 'Я хочу отправиться в Гробницу королей (подземелье).', 'Я хочу отправиться в Гробницу королей (подземелье).', 28153),
(155705, 'ruRU', 'Гарпунщики готовы ко всему!', '', 28153),
(155704, 'ruRU', 'Нашим пернатым друзьям больше не угрожает колдовство.', '', 28153),
(155703, 'ruRU', 'Ведьмы насылают сглаз на птенцов, как только те вылупляются! Уничтожь амулеты и порабощенных сокольничих, чтобы остановить это!', '', 28153),
(155702, 'ruRU', '', 'Кыш.', 28153),
(155701, 'ruRU', '', 'Я легко пускаю в ход оружие.', 28153),
(155700, 'ruRU', '', 'Не мозоль мне глаза.', 28153),
(155699, 'ruRU', '', 'Найди мне чудовище, и Гарпунщики разберутся с ним.', 28153),
(155698, 'ruRU', '', 'Мохнатик, ну что ты за дурашка. Иди ко мне скорее!', 28153),
(155697, 'ruRU', '', 'Кис-кис-кис!', 28153),
(155696, 'ruRU', 'Я хочу отправиться в Атал\'Дазар (подземелье).', 'Я хочу отправиться в Атал\'Дазар (подземелье).', 28153),
(155695, 'ruRU', '', 'Скажи, когда захочешь поиграть с большими детками.', 28153),
(155694, 'ruRU', '', 'Мне пора на охоту.', 28153),
(155693, 'ruRU', '', 'Что на этот раз?', 28153),
(155692, 'ruRU', 'Я полагаю, задание выполнено? Хорошо. Я сообщу вождю.', '', 28153),
(155691, 'ruRU', 'Приветствую и благодарю за помощь в тестировании бета-версии дополнения Battle for Azeroth! \n\nЯ могу телепортировать тебя в различные рейдовые или групповые подземелья, которые в данный момент доступны для тестирования. Это всего лишь телепортация, а не очередь, так что, надеюсь, у тебя уже есть команда, готовая к испытаниям. Если же нет, можешь воспользоваться нашей новой системой поиска группы, чтобы заручиться поддержкой союзников.\n\nПеред телепортацией удостоверься в том, что желаемый уровень сложности для тестирования выбран тобою верно, потому что потом покинуть зону, чтобы сменить уровень сложности, будет не так-то просто!', 'Приветствую и благодарю за помощь в тестировании бета-версии дополнения Battle for Azeroth! \n\nЯ могу телепортировать тебя в различные рейдовые или групповые подземелья, которые в данный момент доступны для тестирования. Это всего лишь телепортация, а не очередь, так что, надеюсь, у тебя уже есть команда, готовая к испытаниям. Если же нет, можешь воспользоваться нашей новой системой поиска группы, чтобы заручиться поддержкой союзников.\n\nПеред телепортацией удостоверься в том, что желаемый уровень сложности для тестирования выбран тобою верно, потому что потом покинуть зону, чтобы сменить уровень сложности, будет не так-то просто!', 28153),
(155690, 'ruRU', 'Игрок $n (Орда) отмечен у вас на карте как |c00FFFF00|Hspell:272296|h[убийца]|h|r! Убейте его, чтобы получить награду.', 'Игрок $n (Орда) отмечен у вас на карте как |c00FFFF00|Hspell:272296|h[убийца]|h|r! Убейте его, чтобы получить награду.', 28153),
(155689, 'ruRU', 'Игрок $n (Альянс) отмечен у вас на карте как |c00FFFF00|Hspell:272295|h[убийца]|h|r! Убейте его, чтобы получить награду.', 'Игрок $n (Альянс) отмечен у вас на карте как |c00FFFF00|Hspell:272295|h[убийца]|h|r! Убейте его, чтобы получить награду.', 28153),
(155688, 'ruRU', 'Нам нужно сдержать врага на этой территории. Ты ведь справишься, не так ли?', '', 28153),
(155687, 'ruRU', '', 'Не было еще чудовищ, с которыми я бы не справилась.', 28153),
(155686, 'ruRU', 'Я думал, ты справишься быстрее... Но и твои темпы приемлемы. Наша кампания продолжится.', '', 28153),
(155685, 'ruRU', 'Вождь объявила, что все ресурсы в этой местности принадлежат Орде. Добудь их.', '', 28153),
(155684, 'ruRU', 'Не смей даже говорить о ней. Я все еще злюсь.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155683, 'ruRU', '', 'Спасибо. Мы немедленно пустим эти ресурсы в ход!', 28153),
(155682, 'ruRU', '', 'Дерешься, как твоя сестра.', 28153),
(155681, 'ruRU', '', 'Возьми эту область под контроль и захвати все ресурсы, которые могут пригодиться Ордену.', 28153),
(155680, 'ruRU', 'Как прикажете...', '', 28153),
(155679, 'ruRU', '', 'Кисонька, ты где?', 28153),
(155678, 'ruRU', '', 'Пойдем, Артур.', 28153),
(155677, 'ruRU', '', 'Маршал, будьте добры, отведите Люсиль в мои покои. Но сперва покончите с этими плебеями...', 28153),
(155676, 'ruRU', '', 'Где моя киса?', 28153),
(155675, 'ruRU', '', 'Маршал, разве так следует обращаться к леди? Я научу вас манерам.', 28153),
(155674, 'ruRU', '', 'Ну как, еще воюешь?', 28153),
(155673, 'ruRU', 'Не подходи, бездушная ведьма!', '', 28153),
(155672, 'ruRU', '', 'Не бойся, доченька. Твой отец жив-здоров и скоро будет править всем Кул-Тирасом. Присоединяйся к нам...', 28153),
(155671, 'ruRU', '', 'Что... что ты с ним сделала?', 28153),
(155670, 'ruRU', '', 'Я так рада, что ты наконец пришла. А уж как твой отец соскучился.', 28153),
(155669, 'ruRU', '', 'Мама? Это... ты?', 28153),
(155668, 'ruRU', '', 'Ни шагу дальше.', 28153),
(155667, 'ruRU', 'Говорят, это как-то связано с ящиками, которые поступают из литейной Эшвейнов.', 'Говорят, это как-то связано с ящиками, которые поступают из литейной Эшвейнов.', 28153),
(155666, 'ruRU', 'Капитан Стоун что-то на взводе.', 'Капитан Стоун что-то на взводе.', 28153),
(155665, 'ruRU', 'Какое счастье, что мы сегодня здесь.', 'Какое счастье, что мы сегодня здесь.', 28153),
(155664, 'ruRU', 'А? Это что, бомбы? А я думал, авокадо.', '', 28153),
(155663, 'ruRU', '', 'Осторожно, Джон. А то руку оторвет.', 28153),
(155662, 'ruRU', 'Отдать концы! Уходим! Славно поработали.', '', 28153),
(155661, 'ruRU', 'Тоже, наверное, ищут азерит. Давайте потихоньку выбираться отсюда, пока нас не заметили. Надо бы сообщить об этом начальству.', '', 28153),
(155660, 'ruRU', 'Вроде все. Последний азерит с острова мы выгребли, и как раз вовремя. Похоже, сюда идет кул-тирасский корабль.', '', 28153),
(155659, 'ruRU', 'Видимо, они тоже прибыли за азеритом. Вот и славно! Идите и заберите все, что они успели накопать.', '', 28153),
(155658, 'ruRU', 'Хозены! Ха! Кого только не занесет на эти острова.', '', 28153),
(155657, 'ruRU', 'В паре шагов от вас должна быть целая гора азерита. Пойдите посмотрите, правда ли это.', '', 28153),
(155656, 'ruRU', 'Вот это молодцы. Скоро мы забьем трюм доверху.', '', 28153),
(155655, 'ruRU', 'Ого, это здоровенный монстр, покрытый азеритом. Убейте его, и мы соскоблим азерит с его шкуры.', '', 28153),
(155654, 'ruRU', 'Где-то недалеко от вас есть скопление азерита. Займитесь им, как будет время.', '', 28153),
(155653, 'ruRU', 'Вот это я понимаю, неплохо затарились!', '', 28153),
(155652, 'ruRU', 'О, здоровенький кусочек! Выкопайте его, а мы погрузим наше сокровище на корабль в два счета.', '', 28153),
(155651, 'ruRU', 'Эта штука показывает, что где-то рядом есть азерит. Идите-ка проверьте, сколько его там.', '', 28153),
(155650, 'ruRU', 'Приплыли. Спускайте трап.', '', 28153),
(155649, 'ruRU', 'Правда, неизвестно, какие тут могут быть сюрпризы. Не расслабляйтесь.', '', 28153),
(155648, 'ruRU', 'Мы почти на месте. Это тот самый остров, где полно залежей азерита.', '', 28153),
(155647, 'ruRU', 'Да, капитан.', 'Да, капитан.', 28153),
(155646, 'ruRU', '', 'Погрузить все на корабль! Эта взрывчатка опасна.', 28153),
(155645, 'ruRU', 'Д-да, капитан Стоун.', 'Д-да, капитан Стоун.', 28153),
(155644, 'ruRU', '', 'Это порох из литейной Эшвейнов?', 28153),
(155643, 'ruRU', 'Кровь и гром, что это за колдовство? Наши корабли уничтожены, а войска поглотило море!', '', 28153),
(155642, 'ruRU', 'В Вольной Гавани продавец ушных затычек мог бы стать миллионером.', '', 28153),
(155641, 'ruRU', 'Ты... ты слышишь? Только не это! Быстрее, убей ее!', '', 28153),
(155640, 'ruRU', 'Вот теперь Вольная Гавань заживет спокой... а, тьфу, кого я пытаюсь обмануть?..', '', 28153),
(155639, 'ruRU', 'Ха! Получай, попугаелюб!', '', 28153),
(155638, 'ruRU', 'Здорово! Теперь один должок можно списать.', '', 28153),
(155637, 'ruRU', 'Кто пахнет грогом и носит красную шляпу? Конечно, пират. Правда, враждебный.', '', 28153),
(155636, 'ruRU', 'Говорят, где-то рядом скрывается бандит. И за его голову обещают награду!', '', 28153),
(155635, 'ruRU', 'Неподалеку бродит опасный преступник. Придется избавиться от него.', '', 28153),
(155634, 'ruRU', 'О, друзья из Торговой компании решили избавить нас от излишков азерита. Они вам понравятся, идите, познакомьтесь.', '', 28153),
(155633, 'ruRU', 'Торговая компания развернула бурную деятельность в нескольких точках острова. Было бы неплохо выбить их отсюда.', '', 28153),
(155632, 'ruRU', 'А вот и Торговая компания пожаловала. Собираются прикарманить весь азерит. Истинные гоблины.', '', 28153),
(155631, 'ruRU', 'На острове замечены головорезы Торговой компании. Похоже, без кровопролития не обойтись.', '', 28153),
(155630, 'ruRU', 'Драккары, врайкульские, очень много. Похоже, в поход за азеритом отправился целый клан.', '', 28153),
(155629, 'ruRU', 'На берег высадился рейд врайкулов. Наверняка им нужна наша добыча. Разберитесь с ними, ладно?', '', 28153),
(155628, 'ruRU', 'Прибыла флотилия врайкулов. Целая ватага грозных воинов уже на острове. Они разбивают лагерь... насколько я могу видеть из бочки.', '', 28153),
(155627, 'ruRU', 'На подходе корабли врайкулов. Похоже, грабители. Врайкулы вечно норовят кого-нибудь ограбить.', '', 28153),
(155626, 'ruRU', 'На огонек пожаловали недружелюбные островные тролли. Должно быть, их лагерь где-то неподалеку.', '', 28153),
(155625, 'ruRU', 'На горизонте каноэ островных троллей. Будут здесь с минуты на минуту. Азерит продолжает притягивать всех, кого я ненавижу.', '', 28153),
(155624, 'ruRU', 'Свой кусок азерита хотят урвать все, даже островные тролли. Будьте так любезны, не подпускайте их к моему кораблю.', '', 28153),
(155623, 'ruRU', 'О, тролльские корабли пожаловали. Только их нам и не хватало. Целый рейд троллей! Всегда о таком мечтал.', '', 28153),
(155622, 'ruRU', 'ОГРОМНЫЙ дракон просто взял и прилетел. Как раз то, чего мне не хватало. В завершение прекрасной рабочей недели, так сказать. В общем, он ваш.', '', 28153),
(155621, 'ruRU', 'Эй, друзья! У нас в гостях здоровенный дракон, которому тоже нужен азерит. Просто делюсь информацией, так сказать.', '', 28153),
(155620, 'ruRU', 'Тут драконы, и они облизываются на наш корабль. Меня заметили! Вы... поможете, правда?', '', 28153),
(155619, 'ruRU', 'К нам тут прилетел целый драконий выводок. Спорим, я знаю, что им тут понадобилось? Удачи вам!', '', 28153),
(155618, 'ruRU', 'А что с небом? Почему так темно? И откуда на острове появились все эти трупы? Ой-ей...', '', 28153),
(155617, 'ruRU', 'Что же это ТАК воняет? Ага, мертвечина! Все слыхали? Тут полно нежити, которая просто жить не может без азерита, хе-хе. Вы знаете, что с ней делать.', '', 28153),
(155616, 'ruRU', 'Спешу доложить: ко всем нашим радостям добавились живые мертвецы. Хотите с ними познакомиться? Я – пас.', '', 28153),
(155615, 'ruRU', 'Мертвяки? Здесь? Понятия не имею, что происходит, но уж точно ничего хорошего.', '', 28153),
(155614, 'ruRU', 'На горизонте тол\'вирские корабли, и не похоже, чтобы это были мирные торговцы. Поэтому прошу вас, разберитесь с ними побыстрее!', '', 28153),
(155613, 'ruRU', 'Ух ты, тол\'виры? Я таких кораблей сто лет не видал. В общем, они тут, и они не очень дружелюбные.', '', 28153),
(155612, 'ruRU', 'Тол\'вирские корабли пристали к берегу. Вы ведь разберетесь с ними? Откуда все знают, где искать азерит? Чтоб им пусто было!', '', 28153),
(155611, 'ruRU', 'Это что, кентавры? Эй! Тут появились эти... их вроде тол\'вирами зовут.', '', 28153),
(155610, 'ruRU', 'На горизонте корабль пиратов. Зуб даю, приплыли грабить и убивать. На то они и пираты.', '', 28153),
(155609, 'ruRU', 'К берегу пристал пиратский корабль! Конечно, если на острове есть сокровище, значит и пираты тут как тут.', '', 28153),
(155608, 'ruRU', 'А вот и ТРЕТИЙ корабль. Ну почему мне вечно достаются такие задания? Кстати, если у вас вдруг были сомнения, это пираты.', '', 28153),
(155607, 'ruRU', 'Ого! По нам тут из пушек стреляют! А еще на берег высаживается куча пиратов.', '', 28153),
(155606, 'ruRU', 'Сауроки! Видать, пронюхали, что здесь можно найти азерит. Интересно, у них вообще есть носы?', '', 28153),
(155605, 'ruRU', 'Хм, из океана только что появился полный рейд сауроков. Такие дела.', '', 28153),
(155604, 'ruRU', 'Что это там среди волн? А-а, целый косяк сауроков. Приплыли, милашки. Они ваши, целиком и полностью.', '', 28153),
(155603, 'ruRU', 'На наш корабль и наш азерит жадно пялятся злобные ящерицы. Вы уж не пускайте их сюда! Пожалуйста!', '', 28153),
(155602, 'ruRU', 'Тут незваные гости. И такие, каких я еще не видал. Не думаю, что они хотят нам помочь.', '', 28153),
(155601, 'ruRU', 'У нас какие-то новые неведомые гости. Судя по всему, им, как и нам, нужен азерит, но вот только... что-то с ними не так.', '', 28153),
(155600, 'ruRU', 'О! А эти ребятки откуда взялись? Из воздуха, что ли? Эй, герои! У нас гости.', '', 28153),
(155599, 'ruRU', 'Это еще что за ребята? Никак не разгляжу лиц. Может, это друзья? Хотя, вряд ли.', '', 28153),
(155598, 'ruRU', 'Похоже, мы привлекли внимание целого Древнего бога и его прислужников. Вы уж разберитесь с ними, ладно?', '', 28153),
(155597, 'ruRU', 'Тут к нам на остров пожаловали товарищи с щупальцами на лицах. Все, с меня хватит, я посижу в трюме.', '', 28153),
(155596, 'ruRU', 'Кто-нибудь еще слышит шепот? Тут одно из двух: либо я схожу с ума, либо где-то на острове безликие. Да, им тоже нужен азерит.', '', 28153),
(155595, 'ruRU', 'Темная буря. Потрясающе. Попахивает Древними богами. Остерегайтесь щупалец.', '', 28153),
(155594, 'ruRU', 'Теперь азерит и могу понадобился, да еще такой толпе. Наверняка плывут сюда.', '', 28153),
(155593, 'ruRU', 'Я заметил на острове отряд могу. Будьте настороже, мы с ними... не очень ладим.', '', 28153),
(155592, 'ruRU', 'Отряд могу только что высадился на острове. Не знаю, что им нужно. Может, вы узнаете?', '', 28153),
(155591, 'ruRU', 'Змеи могу на горизонте, и немало. Наверняка их привлек азерит. Ну, как обычно.', '', 28153),
(155590, 'ruRU', 'А вот и наги. Только их и не хватало. Смотрите там, не помрите ненароком.', '', 28153),
(155589, 'ruRU', 'Вижу в подзорную трубу стаю наг. Они будут тут с минуты на минуту. Поприветствуйте их как следует, хорошо?', '', 28153),
(155588, 'ruRU', 'На остров прибыли наги. Наверняка наша общая знакомая Азшара послала их сюда за азеритом. Что она никак не успокоится?', '', 28153),
(155587, 'ruRU', 'Наги вынырнули из глубин, жадные до нашего добра. Отшутиться от них вряд ли выйдет, так что пойду заряжу пушки.', '', 28153),
(155586, 'ruRU', 'Туман... А, нет, сгнившие корабли. Это квалдиры. Просто чудесно.', '', 28153),
(155585, 'ruRU', 'Тут такое дело. К нам вот-вот пожалуют квалдирские корабли. Должно быть, приплыли за азеритом. Зачем я только взялся за это дело?', '', 28153),
(155584, 'ruRU', 'Ну и туман. Где-то рядом квалдиры, точно вам говорю. Глядите в оба... если, конечно, сможете что-либо разглядеть.', '', 28153),
(155583, 'ruRU', 'Откуда так водорослями несет? Эй, народ, тут квалдиры пожаловали.', '', 28153),
(155582, 'ruRU', 'Сюда движется огромный рой богомолов – сейчас они тут все облепят. Я пережду в трюме, а вы развлекайтесь.', '', 28153),
(155581, 'ruRU', 'Эти твари вроде богомолами зовутся, да? Вы же с ними разберетесь? А то у меня аллергия.', '', 28153),
(155580, 'ruRU', 'Это что, рой пчел? Нет, для пчел великоваты. Ну точно, богомолы! И они уже почти здесь.', '', 28153),
(155579, 'ruRU', 'О, богомолы, ваши любимцы! Конечно же, им тоже нужен азерит. Конечно же.', '', 28153),
(155578, 'ruRU', 'Ого! Что это пролетело? Вы видели? Этот драконище где-то на острове. Будьте бдительны.', '', 28153),
(155577, 'ruRU', 'Короче, тут откуда ни возьмись появился огромный дракон с кучей мелких драконов, и им почему-то не нравится, что мы собираем азерит.', '', 28153),
(155576, 'ruRU', 'Ну, прекрасно. Черный дракон. И половина его стаи в придачу! Здесь! Просто прекрасно.', '', 28153),
(155575, 'ruRU', 'На острове приземлился здоровый дракон. Не подпускайте его к кораблю даже близко! Он сгорит во мгновение ока.', '', 28153),
(155574, 'ruRU', 'Тол\'виры вышли на охоту за азеритом. Просто предупреждаю.', '', 28153),
(155573, 'ruRU', 'Эй, тут нарисовались тол\'виры. Ищут азерит – так же, как и мы, ха-ха.', '', 28153),
(155572, 'ruRU', 'Не думал, что снова увижу корабль тол\'виров. Они сходят на берег. Будьте осторожнее!', '', 28153),
(155571, 'ruRU', 'Какие странные корабли, я такие только раз в жизни видал. Это же тол\'виры!', '', 28153),
(155570, 'ruRU', '', 'Постарайся вернуть реликвию в целости и сохранности. Хорошо, $n? Энтузиазм Астрандиса... пугает.', 28153),
(155569, 'ruRU', '', 'Для нас жизненно важно защищать эти воды от пиратов. Прими мою благодарность.', 28153),
(155568, 'ruRU', 'Я тебя в гавани утоплю своими руками.', '', 28153),
(155567, 'ruRU', 'Сейчас бушевать начнет не только море.', '', 28153),
(155566, 'ruRU', 'Напрасно ты меня злишь.', '', 28153),
(155565, 'ruRU', '', 'Нам надо знать, что задумали пираты. Перехвати их приказы... во что бы то ни стало.', 28153),
(155564, 'ruRU', 'Волны всегда возвращаются.', '', 28153),
(155561, 'ruRU', 'Пусть море будет благосклонно к тебе.', '', 28153),
(155560, 'ruRU', 'Всегда повинуйся морю.', '', 28153),
(155558, 'ruRU', 'Ненавижу птиц. Шумные, грязные твари... Ладно, я отвлекся.', '', 28153),
(155557, 'ruRU', 'Наш союзник в Вольной Гавани просил помочь... успокоить его птиц. Думаю, ты справишься.', '', 28153),
(155556, 'ruRU', 'Я служу морю.', '', 28153),
(155554, 'ruRU', 'Мы тоже... чувствуешь... силу камня?', '', 28153),
(155553, 'ruRU', 'Эти камни сделают нас богатыми! Не отдам!', '', 28153),
(155552, 'ruRU', 'Слушай голос волн.', '', 28153),
(155551, 'ruRU', 'Слушай прибой – и многое узнаешь.', '', 28153),
(155550, 'ruRU', 'У меня есть подозрение...', '', 28153),
(155549, 'ruRU', 'Не заставляй меня звать стражу.', '', 28153),
(155548, 'ruRU', 'Если тебе есть что сказать, говори!', '', 28153),
(155547, 'ruRU', 'Прошу... только кота пощадите.', '', 28153),
(155546, 'ruRU', 'Я очень занятой человек.', '', 28153),
(155545, 'ruRU', 'Возвращайся с новыми историями!', '', 28153),
(155543, 'ruRU', 'Еще один прихвостень Недли! Ты у меня тоже поныряешь в грязь!', '', 28153),
(155540, 'ruRU', 'Приветствую!', '', 28153),
(155539, 'ruRU', 'Славно провести время!', '', 28153),
(155538, 'ruRU', 'Будь как дома. Мое поместье – твое поместье.', '', 28153),
(155536, 'ruRU', 'Ешь, пей, веселись!', '', 28153),
(155535, 'ruRU', 'Добро пожаловать на конно-охотничий фестиваль Норвингтонов!', '', 28153),
(155534, 'ruRU', '', 'И пятьсот миллиардов норгабайт изображений няшных представителей семейства кошачьих.', 28153),
(155533, 'ruRU', 'Как же ты вовремя. Трогги идут в атаку на поместье!', '', 28153),
(155532, 'ruRU', '', 'Они играют с запретными силами. Море должно быть свободным!', 28153),
(155531, 'ruRU', 'Воины Орды! Покажите Альянсу, что вам есть, за что сражаться! В атаку!', '', 28153),
(155530, 'ruRU', '', 'Все вместе! В атаку! Арати будет нашим!', 28153),
(155529, 'ruRU', '', 'Люди призывают что-то ужасное из глубин. Останови их!', 28153),
(155528, 'ruRU', 'Тортоллан?', 'Тортоллан?', 28153),
(155527, 'ruRU', '', 'Вон тот панцирь с руками и ногами!\n\nНе дай ему задурить тебе голову. Он умный и очень пронырливый! Вечно тут ошивается, собирает древние реликвии, свитки и прочий мусор. \n\nОн не должен найти сокровище первым.', 28153),
(155526, 'ruRU', 'Я все расскажу дяде!', '', 28153),
(155525, 'ruRU', 'Просто отойди.', '', 28153),
(155524, 'ruRU', 'Я вынужден просить тебя удалиться.', '', 28153),
(155522, 'ruRU', 'Пора прощаться, видимо.', '', 28153),
(155521, 'ruRU', 'Никто не предупредил меня, что власть – это так... сложно.', '', 28153),
(155520, 'ruRU', 'Я делаю все, что могу.', '', 28153),
(155516, 'ruRU', 'Мыс Рыбака под моей опекой!', '', 28153),
(155515, 'ruRU', 'Я должен показать дяде, на что я способен.', '', 28153),
(155514, 'ruRU', 'Здесь тебе рады.', '', 28153),
(155513, 'ruRU', 'Давай.', '', 28153),
(155512, 'ruRU', 'Если у тебя нет ко мне дел – уходи.', '', 28153),
(155511, 'ruRU', 'Пора на пост.', '', 28153),
(155510, 'ruRU', 'Меня зовет долг.', '', 28153),
(155509, 'ruRU', 'М?', '', 28153),
(155508, 'ruRU', 'Чудесно! Из этих реагентов я смогу сделать пару... интересных зелий.', '', 28153),
(155507, 'ruRU', 'Эти края богаты природными ресурсами и уникальными алхимическими реагентами. Мне бы они очень пригодились! Прошу, добудь их.', '', 28153),
(155506, 'ruRU', '', 'Фермеры передают тебе благодарность за спасение!', 28153),
(155505, 'ruRU', '', 'Фермы на побережье страдают от набегов диких зверей. Помоги крестьянам.', 28153),
(155504, 'ruRU', 'Следующий контакт с нами может обернуться травмами и летальным исходом.', '', 28153),
(155503, 'ruRU', 'Мы, конечно, очень терпеливые, но уж если разозлишь нас – лучше грибы отсюда!', '', 28153),
(155502, 'ruRU', 'Если мы потеряем шляпку, ты об этом пожалеешь.', '', 28153),
(155501, 'ruRU', 'Все, что ли?', '', 28153),
(155500, 'ruRU', 'Держи шляпку ровно.', '', 28153),
(155499, 'ruRU', 'Да пребудет с тобой силос.', '', 28153),
(155498, 'ruRU', 'Мы тебя видим.', '', 28153),
(155497, 'ruRU', 'Приветствуем тебя!', '', 28153),
(155496, 'ruRU', 'Всегда должен быть... Король-лишайник...', '', 28153),
(155495, 'ruRU', 'Грибная Скорбь жаждет крови!', '', 28153),
(155494, 'ruRU', 'Ай!', '', 28153),
(155493, 'ruRU', 'Споры нашли нас...', '', 28153),
(155492, 'ruRU', 'Мы... не слышим...', '', 28153),
(155491, 'ruRU', 'Убьем тебя! Убьем! Убьем!', '', 28153),
(155490, 'ruRU', 'Стань нами!', '', 28153),
(155489, 'ruRU', 'Умри! Умри! Умри!', '', 28153),
(155488, 'ruRU', '', 'Ха! Такой сноровке позавидуют и Гарпунщики!', 28153),
(155487, 'ruRU', 'Какой-то монстр повадился питаться нашими новобранцами. Убей его. А то мне придется набирать очередную группу неумелых рекрутов.', '', 28153),
(155486, 'ruRU', '', 'Кул-тирасская стража заметила в воде чудовище. Если с ним не разобраться, оно потопит все суда в порту.', 28153),
(155485, 'ruRU', 'Пираты рассказывали о костяном демоне, живущем на поморье. Теперь ясно, откуда эти слухи.', '', 28153),
(155484, 'ruRU', 'На берег выползло гигантское морское... нечто. Не знаю, откуда оно взялось, но выглядит опасно.', '', 28153),
(155483, 'ruRU', 'Некоторые сидят в Тол Дагоре за дело. Этот был одним из таких молодчиков.', '', 28153),
(155482, 'ruRU', '', 'Безумцу конец! Теперь многие обязаны тебе жизнью.', 28153),
(155481, 'ruRU', 'Теперь я пойду...', 'Теперь я пойду...', 28153),
(155480, 'ruRU', 'Теперь я в безопасности.', 'Теперь я в безопасности.', 28153),
(155479, 'ruRU', 'Спасибо.', 'Спасибо.', 28153),
(155478, 'ruRU', 'Теперь я упокоюсь...', 'Теперь я упокоюсь...', 28153),
(155477, 'ruRU', 'Мне было так плохо...', 'Мне было так плохо...', 28153),
(155476, 'ruRU', 'Мне было так страшно... Но больше я не боюсь...', 'Мне было так страшно... Но больше я не боюсь...', 28153),
(155475, 'ruRU', 'Ты как тут?', '', 28153),
(155474, 'ruRU', 'Свет такой теплый...', 'Свет такой теплый...', 28153),
(155473, 'ruRU', '', 'Спасибо за помощь! Мы этого не забудем!', 28153),
(155471, 'ruRU', 'За мной.', 'За мной.', 28153),
(155470, 'ruRU', 'Заряжай!', 'Заряжай!', 28153),
(155469, 'ruRU', '', 'Еретики! Вам тут не место!', 28153),
(155468, 'ruRU', 'Огонь!', 'Огонь!', 28153),
(155467, 'ruRU', '', 'Зулдазар построен из золота. Наверняка же есть способ украсть целый город?', 28153),
(155466, 'ruRU', '', 'Из человеческой тюрьмы сбежал опасный преступник. Он уже подобрался к гавани Орды. Разберись с ним.', 28153),
(155465, 'ruRU', 'Кажется, я знаю этого парня! Ну да, точно знаю! Ох, не к добру он тут появился.', '', 28153),
(155464, 'ruRU', 'Глубины... дадут... еще!', '', 28153),
(155463, 'ruRU', 'Эта сила – дар глубин!', '', 28153),
(155462, 'ruRU', 'Я думал, култирасцы будут достойными противниками... но они такие же бесхребетные трусы, как и все прислужники Альянса.', '', 28153),
(155461, 'ruRU', 'Темному следопыту удалось заманить в ловушку советника верховного адмирала... Честь нанести удар я оставлю тебе.', '', 28153),
(155460, 'ruRU', '', 'Теперь духи мертвых снова обретут покой.', 28153),
(155459, 'ruRU', 'Хорошо... но ты же вернешься?', '', 28153),
(155458, 'ruRU', 'Ладно, увидимся!', '', 28153),
(155457, 'ruRU', 'Это отучит Орду связываться с нашими морпехами!', '', 28153),
(155456, 'ruRU', 'Один из офицеров загнал в угол темного следопыта! Помоги ему!', '', 28153),
(155455, 'ruRU', 'Я так горжусь папой!', '', 28153),
(155454, 'ruRU', 'Какой хороший денек!', '', 28153),
(155453, 'ruRU', 'Папа говорит, взрослые иногда боятся. А ты боишься?', '', 28153),
(155452, 'ruRU', 'О! Смотри, какие пони!', '', 28153),
(155451, 'ruRU', 'Учиться никогда не поздно!', '', 28153),
(155450, 'ruRU', 'Пока-пока!', '', 28153),
(155449, 'ruRU', '', 'Прислужники ведьм довели духов до исступленной ярости. Устрани источник этой порчи и верни покой заблудшим душам.', 28153),
(155448, 'ruRU', 'Эх! Ну, хотя бы \"Занчульского резервного\" отведал...<ик!>...еще разок... перед смертью!', '', 28153),
(155447, 'ruRU', 'Говорят, что Моджамбо нанял для битвы подкрепление. Теперь ему помогает банда Тонго.', '', 28153),
(155446, 'ruRU', 'Я видел, что по арене рыщет банда Моджамбо...', '', 28153),
(155445, 'ruRU', 'Твоя часть сделки выполнена, теперь дело за мной...', '', 28153),
(155444, 'ruRU', 'А-а! Сто лет не пил \"Занчульского резервного\"... <ик!>', '', 28153),
(155443, 'ruRU', 'Держи ром. Расскажи мне все.', 'Держи ром. Расскажи мне все.', 28153),
(155442, 'ruRU', 'Ладно, давай! Я буду... здесь.', '', 28153),
(155441, 'ruRU', 'Я ищу знаний. А ты?', '', 28153),
(155440, 'ruRU', 'Мы долго были в пути, и вот мы здесь.', '', 28153),
(155439, 'ruRU', 'Доброй охоты.', '', 28153),
(155438, 'ruRU', 'За Орду!', '', 28153),
(155437, 'ruRU', 'Нужно кого-нибудь выследить?', '', 28153),
(155436, 'ruRU', 'Клык и коготь.', '', 28153),
(155435, 'ruRU', 'Ну все, теперь я не промахнусь!', '', 28153),
(155434, 'ruRU', 'Да хватит уже!', '', 28153),
(155433, 'ruRU', 'Я... эм... Я охочусь в одиночку.', '', 28153),
(155432, 'ruRU', 'Да начнется охота.', '', 28153),
(155431, 'ruRU', 'Да будет так.', '', 28153),
(155430, 'ruRU', 'Добыча не уйдет.', '', 28153),
(155429, 'ruRU', 'Охота начинается.', '', 28153),
(155428, 'ruRU', 'Добыча близко.', '', 28153),
(155427, 'ruRU', 'Я слышу зов природы.', '', 28153),
(155426, 'ruRU', 'Смотри, какие грациозные животные!', '', 28153),
(155425, 'ruRU', 'До скорой встречи, надеюсь!', '', 28153),
(155424, 'ruRU', 'Запомни – животных не кормить!', '', 28153),
(155423, 'ruRU', 'Приятного отдыха!', '', 28153),
(155422, 'ruRU', '...', '', 28153),
(155421, 'ruRU', 'Что мы здесь делаем?', 'Что мы здесь делаем?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155420, 'ruRU', 'Ты хочешь что-то мне сказать?', 'Ты хочешь что-то мне сказать?', 28153),
(155419, 'ruRU', 'Не будем мешкать. У нас много дел.', 'Не будем мешкать. У нас много дел.', 28153),
(155418, 'ruRU', 'Денек добрый!', '', 28153),
(155417, 'ruRU', 'Привет!', '', 28153),
(155416, 'ruRU', 'Добро пожаловать в \"Кипящие Ключи\"!', '', 28153),
(155415, 'ruRU', '', 'Мои сестры... получат... силу камня!', 28153),
(155414, 'ruRU', '', 'Мама будет рада такому сильному камню!', 28153),
(155413, 'ruRU', 'Тебе решать, куда мы направимся. Сделай выбор – и мы отплывем без промедления.', '', 28153),
(155412, 'ruRU', 'Ну что, $n, пора приниматься за дело. Один из моих оперативников уже готов к первому важному заданию.', '', 28153),
(155411, 'ruRU', 'Да пребудет с вами Свет.', '', 28153),
(155410, 'ruRU', 'Легкой дороги.', '', 28153),
(155409, 'ruRU', 'Дела зовут меня в Штормград. Но я уверен, что кампания остается в надежных руках, и жду от вас регулярных отчетов. Успехов!', '', 28153),
(155408, 'ruRU', 'Мое почтение.', '', 28153),
(155407, 'ruRU', 'С решением более... деликатных задач тебе поможет мастер Матиас Шоу и его агенты ШРУ.', '', 28153),
(155406, 'ruRU', 'Это честь для меня, $n.', '', 28153),
(155405, 'ruRU', 'Я призвал под наши знамена лучших солдат на всем Азероте – 7-й легион и главнокомандующего Халфорда Змеевержца.', '', 28153),
(155404, 'ruRU', 'Твои подвиги хорошо известны всему Альянсу, и я верю, что ты сыграешь важную роль в нашей кампании. Нельзя допустить, чтобы Орда и зандалары объединились.', '', 28153),
(155403, 'ruRU', '$n, пришло время начать кампанию в Зандаларе. Я буду ждать тебя на борту \"Искупления ветра\" в Боралусе.', '', 28153),
(155402, 'ruRU', 'Эти леса прокляты! Уходи! Беги, пока еще можешь!', 'Эти леса прокляты! Уходи! Беги, пока еще можешь!', 28153),
(155401, 'ruRU', 'Никогда не видел такого безумия!', 'Никогда не видела такого безумия!', 28153),
(155400, 'ruRU', 'Они сожрали мою собаку! И меня собирались!', 'Они сожрали мою собаку! И меня собирались!', 28153),
(155399, 'ruRU', 'Что, во имя покрытого прилипалами дедушкиного драккара, здесь происходит?', 'Что, во имя покрытого прилипалами дедушкиного драккара, здесь происходит?', 28153),
(155398, 'ruRU', 'За мной гналась стая кроликов. Кроликов!', 'За мной гналась стая кроликов. Кроликов!', 28153),
(155397, 'ruRU', 'А-а-а!', 'А-а-а!', 28153),
(155396, 'ruRU', 'Животные с ума посходили!', 'Животные с ума посходили!', 28153),
(155395, 'ruRU', 'Спасибо, дружище.', 'Спасибо, дружище.', 28153),
(155394, 'ruRU', 'На берег выползли наги, целый выводок. Хотят разграбить этот остров, не иначе.', '', 28153),
(155393, 'ruRU', 'Мы заметили наг. Должно быть, их привлек азерит, что вы собрали. Будьте начеку.', '', 28153),
(155392, 'ruRU', 'Наги пожаловали. Задайте-ка им жару, ха-ха.', '', 28153),
(155391, 'ruRU', 'Из моря вышли наги. Тоже ищут азерит, небось. Будьте осторожнее.', '', 28153),
(155390, 'ruRU', 'Осторожно! Я заметил огромного дракона и его стаю. Они летят к нам!', '', 28153),
(155389, 'ruRU', 'Только что сюда прилетела целая стая драконов, и они собирают азерит. Пожалуй, с этим надо покончить.', '', 28153),
(155388, 'ruRU', 'Только что пролетали драконы, поглядывали на нашу лоханку. Ждите гостей.', '', 28153),
(155387, 'ruRU', 'Кто там летит... драконы, кажется. Должно быть, азерит ищут. Готовьтесь к бою.', '', 28153),
(155386, 'ruRU', 'Черные драконы? Здесь? Прилетели за азеритом, значит. Осторожней там!', '', 28153),
(155385, 'ruRU', 'Кто бы мог подумать, что я когда-нибудь увижу взрослых драконов. Им нужен азерит – наш азерит!', '', 28153),
(155384, 'ruRU', 'Эй, тут на азерит слетелись драконы. Вон там приземлились, видите?', '', 28153),
(155383, 'ruRU', 'Небеса темнеют... Это черный дракон! Привел целую стаю грабить наш остров!', '', 28153),
(155382, 'ruRU', 'Глядите-ка, рабочие Торговой компании пожаловали. Им точно нужен азерит.', '', 28153),
(155381, 'ruRU', 'Торговая компания собирается обосноваться на острове. Надо бы их прогнать.', '', 28153),
(155380, 'ruRU', 'Тут инвесторы из Торговой компании явились облегчить наши сундуки. Идите-ка, проведите с ними деловые переговоры.', '', 28153),
(155379, 'ruRU', 'Тут недалеко копошатся рабочие Торговой компании. Разбивают лагерь.', '', 28153),
(155378, 'ruRU', 'Эй, смотрите-ка, корабли островных троллей. Им тоже нужен азерит. Сделайте с ними что-нибудь!', '', 28153),
(155377, 'ruRU', 'Прибыли островные тролли. Наверняка ищут сокровища. Не зевайте.', '', 28153),
(155376, 'ruRU', 'Вижу каноэ островных троллей. Они мне никогда не нравились. Убейте для меня парочку!', '', 28153),
(155375, 'ruRU', 'Островные тролли сходят на берег, и не за тем, чтобы поздороваться.', '', 28153),
(155374, 'ruRU', 'По нам стреляют из пушек. Пиратский корабль бросил якорь, и его команда готовится разграбить остров.', '', 28153),
(155373, 'ruRU', 'О, а вот и пираты пожаловали. Вон они, сходят на берег. Поприветствуйте их.', '', 28153),
(155372, 'ruRU', 'На берег сходит команда пиратов. Осторожней, они претендуют на нашу добычу.', '', 28153),
(155371, 'ruRU', 'Ты мне не нравишься...', 'Тебе... лучше уйти...', 28153),
(155370, 'ruRU', 'Еще один корабль – похоже, это пираты. Разделайтесь с ними скорее, пока они не увели нашу добычу.', '', 28153),
(155369, 'ruRU', 'Знакомые звуки. К нам нагрянул рейд сауроков. Будьте начеку.', '', 28153),
(155368, 'ruRU', 'В воде какое-то странное движение. А-а, это сауроки, и немало!', '', 28153),
(155367, 'ruRU', 'На наш корабль облизываются злобные ящерицы. Может, лучше их перебить?', '', 28153),
(155366, 'ruRU', 'Боевые сауроки лезут прямо из воды. И, конечно же, им тоже нужен азерит.', '', 28153),
(155365, 'ruRU', 'Только не по лицу!', 'Перерыв...', 28153),
(155364, 'ruRU', 'Ну вот, провалил все сроки!', 'Эй, у меня нет страховки!', 28153),
(155363, 'ruRU', 'Слышали? Это богомолы, тоже азерит ищут. Смотрите, чтобы вас не покусали!', '', 28153),
(155362, 'ruRU', 'Приближается большой рой богомолов. Вы там поосторожней... им нужно то же, что и вам.', '', 28153),
(155361, 'ruRU', 'Тут вроде богомолы пожаловали. Похоже, им тоже нужен азерит.', '', 28153),
(155360, 'ruRU', 'Что за жужжание? Вроде сверху. Кажется, на остров скоро прилетит рой насекомых.', '', 28153),
(155359, 'ruRU', 'Двойная страховая выплата...', 'Какой позор!', 28153),
(155358, 'ruRU', 'Духи... заберите меня...', 'Духи... заберите меня...', 28153),
(155357, 'ruRU', 'Откуда водорослями несет? Смотрите, там у берега квалдирские лодки!', '', 28153),
(155356, 'ruRU', 'В тумане ничего не разобрать. Тут наверняка полно квалдиров, будьте начеку.', '', 28153),
(155355, 'ruRU', 'Сюда плывут гнилые лодки, от которых за милю несет квалдирами. Им нужен наш азерит.', '', 28153),
(155354, 'ruRU', 'Туман сгущается. И это не просто туман – скоро здесь будут квалдиры.', '', 28153),
(155353, 'ruRU', 'Все не так... как я думал...', 'Все не так... как я думала...', 28153),
(155352, 'ruRU', 'Я всегда хотел быть пиратом, босс. Вот и назвал его в честь дочки!\n\nА если у меня будет воздушный корабль, назову его именем сына!', '', 28153),
(155351, 'ruRU', 'Почему корабль называется \"Мала\"?', 'Почему корабль называется \"Мала\"?', 28153),
(155350, 'ruRU', 'Хе-хе-хе...\n\nДавай не будем сейчас об этом да?', '', 28153),
(155349, 'ruRU', 'Откуда у тебя корабль?', 'Откуда у тебя корабль?', 28153),
(155348, 'ruRU', 'Гарона велела мне найти лодку. Ну я и нашел.', '', 28153),
(155347, 'ruRU', 'Откуда у тебя пиратский корабль?', 'Откуда у тебя пиратский корабль?', 28153),
(155346, 'ruRU', 'К нам пожаловали новые друзья, ха-ха. Врайкулы, похоже.', '', 28153),
(155345, 'ruRU', 'Кто там на горизонте? Кажется, врайкулы-мародеры. Осторожнее там.', '', 28153),
(155344, 'ruRU', 'К острову причалили врайкулы. Прибыли за нашей добычей, не иначе.', '', 28153),
(155343, 'ruRU', 'Привет, босс. Как насчет организовать небольшой мятеж?', '', 28153),
(155342, 'ruRU', 'Вижу на горизонте драккары. Видимо, врайкулы явились за азеритом.', '', 28153),
(155341, 'ruRU', 'Что-то привело мертвых на остров. Что-то не из этого мира. Будьте осторожны.', '', 28153),
(155340, 'ruRU', 'Духи говорят мне, что на остров за нашим азеритом явились мертвецы.', '', 28153),
(155339, 'ruRU', 'Ну и вонь. Сюда заявились мертвецы. Смотрите в оба.', '', 28153),
(155338, 'ruRU', 'Странная какая-то темнота. Наверняка за азеритом явился кто-то злобный.', '', 28153),
(155337, 'ruRU', 'Тут какие-то странные ребятки пришли за азеритом. Выглядят как сектанты какие-то.', '', 28153),
(155336, 'ruRU', 'Ого, а эти откуда взялись? У нас гости, будьте поосторожнее!', '', 28153),
(155335, 'ruRU', 'Эй, что это за ребята? Видать, им тоже нужен азерит. Вы уж объясните им, что к чему.', '', 28153),
(155334, 'ruRU', 'У нас новые друзья – никогда таких раньше не видел. Наверняка явились за азеритом.', '', 28153),
(155333, 'ruRU', 'К берегу причалили змеи могу, так что ждите их тут с минуты на минуту.', '', 28153),
(155332, 'ruRU', 'Тут могу приперлись, наверняка хотят наше добро забрать. Наподдайте-ка им!', '', 28153),
(155331, 'ruRU', 'Отряд могу явился за нашим азеритом. Будьте поосторожнее там.', '', 28153),
(155330, 'ruRU', 'Я видел в воздухе летучих змеев. Скоро здесь будут могу.', '', 28153),
(155329, 'ruRU', 'Темная буря... значит, скоро мы увидим безликих.', '', 28153),
(155328, 'ruRU', 'Вы слышите этот шепот? Какой-то Древний бог натравил на нас своих подручных!', '', 28153),
(155327, 'ruRU', 'За нашим азеритом пришли друзья с щупальцами на лицах. Я... спущусь лучше в трюм.', '', 28153),
(155326, 'ruRU', 'Азерит привлек на остров безликих... и немало безликих, скажу я вам.', '', 28153),
(155325, 'ruRU', 'Плохая птица! Лети отсюда!', 'Плохая птица! Лети отсюда!', 28153),
(155324, 'ruRU', 'Кыш!', 'Кыш!', 28153),
(155323, 'ruRU', '', 'В лесах Гленбрука снова можно охотиться. Спасибо.', 28153),
(155322, 'ruRU', '', 'Ведьмы околдовали лесных зверей, и теперь дичь убивает охотников! Уничтожь заколдованных зверей и спаси людей.', 28153),
(155321, 'ruRU', '', 'Ты напоминаешь мне моего нелепого помощника, $p.', 28153),
(155320, 'ruRU', '', 'Твое лицо кажется знакомым... мы в Тол Дагоре не встречались?', 28153),
(155319, 'ruRU', '', 'Местным жителям больше не нужно бояться нападений животных. Очень хорошо!', 28153),
(155318, 'ruRU', '', 'Ведьмы околдовали диких зверей в холмах! Убей агрессивных животных, пока они не добрались до города.', 28153),
(155317, 'ruRU', 'Становится тяжело дышать!', 'Становится тяжело дышать!', 28153),
(155312, 'ruRU', 'Врагу понадобится время, чтобы восстановить силы. Темная Госпожа будет довольна!', '', 28153),
(155311, 'ruRU', 'Наши войска заняли плацдарм в военной академии. Отправляйся туда и помоги им.', '', 28153),
(155310, 'ruRU', '', 'А ведь я знала многих из этих солдат... Орда заплатит за каждую каплю их крови!', 28153),
(155309, 'ruRU', '', 'Элитные войска Орды прорвались на территорию академии Праудмуров. Помоги морпехам отбить атаку!', 28153),
(155308, 'ruRU', '', 'Город в безопасности, но нам нужно всегда быть на страже.', 28153),
(155307, 'ruRU', '', 'Проклятие ведьм снова пало на эту землю. Сними его, пока мы не потеряли город!', 28153),
(155306, 'ruRU', '', 'Ха... сила камней... будет принадлежать... Штормсонгам!', 28153),
(155305, 'ruRU', '', 'Этот камень – дар глубин, и ты его не получишь!', 28153),
(155304, 'ruRU', 'Когда цветок увял, я сразу понял, что остался один, и тут же нанялся на работу в доки. Благодаря морскому стеблю я не стал бродягой, как многие другие.', 'Когда цветок увял, я сразу поняла, что осталась одна, и тут же нанялась на работу в доки. Благодаря морскому стеблю я не стала бродягой, как многие другие.', 28153),
(155303, 'ruRU', 'Орда, свинобразы... наша долина все равно выстоит!', '', 28153),
(155302, 'ruRU', 'Не брать... камни трогга....', '', 28153),
(155301, 'ruRU', 'Мои камни...', '', 28153),
(155300, 'ruRU', 'Бить... тебя...', '', 28153),
(155299, 'ruRU', 'Трогг... сломать...', '', 28153),
(155298, 'ruRU', 'Трогг падать...', '', 28153),
(155297, 'ruRU', 'Трогг... убить...', '', 28153),
(155296, 'ruRU', 'А-а-а!', '', 28153),
(155295, 'ruRU', 'Ау-у-у...', '', 28153),
(155294, 'ruRU', 'Это земля трогга! Уходи!', '', 28153),
(155293, 'ruRU', 'А-а-а! Трогг тебя убивать!', '', 28153),
(155292, 'ruRU', 'Стирай в порошок!', '', 28153),
(155291, 'ruRU', '', 'Я слежу за тем, чтобы дела в Кул-Тирасе шли спокойно. Чем могу помочь?', 28153),
(155290, 'ruRU', 'Блестяшки трогга! Уходи!', '', 28153),
(155289, 'ruRU', 'Гр-р-р! Круши!', '', 28153),
(155288, 'ruRU', 'Трогг ломать тебе лицо!', '', 28153),
(155287, 'ruRU', 'Трогг бить по черепушке!', '', 28153),
(155286, 'ruRU', 'Это земля трогга!', '', 28153),
(155285, 'ruRU', 'Троггзор!', '', 28153),
(155284, 'ruRU', 'Мои камни! Не твои!', '', 28153),
(155283, 'ruRU', 'Мое сокровище! Мое!', '', 28153),
(155282, 'ruRU', 'Р-р-р!', '', 28153),
(155281, 'ruRU', 'А-а-а!', '', 28153),
(155280, 'ruRU', 'Крушить! Ломать! УБИВАТЬ!', '', 28153),
(155279, 'ruRU', 'Трогг крушить!', '', 28153),
(155278, 'ruRU', 'Трогг не тупой!', '', 28153),
(155277, 'ruRU', 'Кстати! Ты в курсе, что принцесса сотворила с Альянсом? Видишь обломки слева? Лоа постарался на славу!', '', 28153),
(155276, 'ruRU', 'Какое-то время о нагах не было ни слуху, ни духу. Ходили разговоры о том, чтобы все заново отстроить, но Грал то ли куда-то делся, то ли сильно ослаб, поэтому разговорами все и ограничилось.', '', 28153),
(155275, 'ruRU', 'И перебили всех последователей Грала до единого. Как же он разозлился! Все, кто был в ту ночь у воды, ощутили его боль... и погибли.', '', 28153),
(155274, 'ruRU', 'Хо-хо! Как гора с плеч! Мы узнали, что змееголовая ведьма мертва!', '', 28153),
(155273, 'ruRU', 'Великих тебе свершений!', '', 28153),
(155272, 'ruRU', 'Берегись. В долине нынче опасно.', '', 28153),
(155271, 'ruRU', 'В долине Штормов полно сокровищ.', '', 28153),
(155270, 'ruRU', 'Добро пожаловать в долину.', '', 28153),
(155269, 'ruRU', 'Приветствую!', '', 28153),
(155268, 'ruRU', 'Бреннадам – мой дом, и я буду защищать его.', '', 28153),
(155267, 'ruRU', '', 'Я тоже человек слова. Мой порт открыт для тебя и твоей Орды.', 28153),
(155266, 'ruRU', 'Да, капитан. Мы сделаем для тебя все, что в наших силах. И надеемся, что ты сделаешь для нас то же самое.', '', 28153),
(155265, 'ruRU', '', 'Свобода... Похоже, ты свое слово держишь.', 28153),
(155264, 'ruRU', 'Зачем вы... пришли?..', '', 28153),
(155263, 'ruRU', 'Сломаешь колючку... лоза будет жить...', '', 28153),
(155262, 'ruRU', 'Гра-а!', '', 28153),
(155261, 'ruRU', 'Нет... самоцветы...', '', 28153),
(155260, 'ruRU', 'Все нас... не убить...', '', 28153),
(155259, 'ruRU', 'Я вяну...', '', 28153),
(155258, 'ruRU', 'Меня сломали...', '', 28153),
(155257, 'ruRU', 'Шипы... сломаны...', '', 28153),
(155256, 'ruRU', 'Все светящиеся самоцветы принадлежат нам!', '', 28153),
(155255, 'ruRU', 'Камни делают колючки сильнее!', '', 28153),
(155254, 'ruRU', 'Это наша земля, и ее сила тоже наша!', '', 28153),
(155253, 'ruRU', 'Ваша плоть ничто перед нашими копьями.', '', 28153),
(155252, 'ruRU', 'Я сделаю из тебя чучело!', '', 28153),
(155251, 'ruRU', 'Мы сделали верный выбор.', '', 28153),
(155250, 'ruRU', 'Лоза опутает и этот остров, и вашу плоть!', '', 28153),
(155249, 'ruRU', 'Вам здесь нечего делать, ломатели колючек!', '', 28153),
(155248, 'ruRU', 'Слуги, на помощь!', '', 28153),
(155247, 'ruRU', 'Пусть-ка сами попробуют, каково это!', '', 28153),
(155246, 'ruRU', 'Лозу не удержать!', '', 28153),
(155245, 'ruRU', 'Лоза выпьет твою кровь.', '', 28153),
(155244, 'ruRU', 'Сбросить бомбы!', '', 28153),
(155243, 'ruRU', 'Взры-ы-ы-ывай!', '', 28153),
(155242, 'ruRU', 'Ты увянешь, враг колючек!', '', 28153),
(155241, 'ruRU', 'Это наш дом!', '', 28153),
(155240, 'ruRU', 'От сидения в клетке толку тоже мало.', '', 28153),
(155239, 'ruRU', 'Пронзить их плоть!', '', 28153),
(155238, 'ruRU', 'Выпотрошить чужаков!', '', 28153),
(155237, 'ruRU', '', 'Поднимаются волны.', 28153),
(155236, 'ruRU', 'Нас атакуют!', '', 28153),
(155235, 'ruRU', 'Умри, ломатель колючек!', '', 28153),
(155234, 'ruRU', '', 'Слушай голос моря.', 28153),
(155233, 'ruRU', 'Реликвии под защитой. Грал еще не утерян.', '', 28153),
(155232, 'ruRU', 'Кровь и гром.', '', 28153),
(155231, 'ruRU', 'А еще я нашел эту занятную штучку.', '', 28153),
(155230, 'ruRU', 'Похоже, не надо было так спешить уходить с заставы.', '', 28153),
(155229, 'ruRU', '', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_01.BLP:20|t%s отмечает вас горящим запалом. Держитесь подальше от бочонков с взрывчаткой!', 28153),
(155228, 'ruRU', 'Радуйся последним денькам, Разгаджи. Когда мы встретимся в следующий раз... тебе конец!', '', 28153),
(155227, 'ruRU', 'Наш путь привел нас сюда. А открытия, которые мы сделали в дороге, помогают лучше понять происходящее.', '', 28153),
(155226, 'ruRU', '', 'Береги себя.', 28153),
(155225, 'ruRU', '', 'Какое у тебя дело к мэру?', 28153),
(155224, 'ruRU', '', 'Я должна защитить жителей долины.', 28153),
(155223, 'ruRU', '', 'Хочешь помочь?', 28153),
(155222, 'ruRU', 'За Орду!', '', 28153),
(155221, 'ruRU', 'Ух, как извивается в сетях! Сейчас повеселюсь!', 'Ух, как извивается в сетях! Сейчас повеселюсь!', 28153),
(155220, 'ruRU', 'Ха! Поймал!', 'Ха! Поймала!', 28153),
(155219, 'ruRU', 'Хорошо. Ух, я тебе такого расскажу!', '', 28153),
(155218, 'ruRU', '', 'Ту\'джин. Если хочешь, чтобы я с тобой работала, расскажи мне об Орде.', 28153),
(155217, 'ruRU', 'Весь азерит... будет... нашим...', '', 28153),
(155216, 'ruRU', 'Этот азерит принадлежит корпорации Эшвейнов!', '', 28153),
(155215, 'ruRU', '', 'Вражеские войска пошли в атаку! Останови их!', 28153),
(155214, 'ruRU', '', 'Теперь у наших войск будет время передохнуть.', 28153),
(155213, 'ruRU', '', 'Ведьмы отступили! Задача выполнена!', 28153),
(155212, 'ruRU', '', 'Ведьмы атакуют эту местность. Избавься от них!', 28153),
(155211, 'ruRU', '', 'Теперь у нас есть время передохнуть. Спасибо!', 28153),
(155210, 'ruRU', '', 'Ковен напал на жителей Друствара! Отрази атаку ведьм!', 28153),
(155209, 'ruRU', '', 'Мои люди в долгу перед тобой. И я тоже.', 28153),
(155208, 'ruRU', '', 'Мои люди нуждаются в помощи. Прошу, сделай все, что в твоих силах!', 28153),
(155207, 'ruRU', 'Нет! Пусть будет так. Мы уйдем... но когда вернемся, пощады уже не будет!', '', 28153),
(155206, 'ruRU', 'Я займусь |3-4($r), босс! Без проблем.', 'Я займусь |3-4($r), босс! Без проблем.', 28153),
(155205, 'ruRU', 'Никуда я с вами не пойду. Ты правда думаешь, что твои хиляки справятся с нами? Не ввязывайся в бой, в котором не можешь победить.', '', 28153),
(155204, 'ruRU', '\"Завязал\"? Здесь я решаю, кто завязал, а кто нет! Ты знаешь, что бывает с дезертирами!', '', 28153),
(155203, 'ruRU', 'Моджамбо, я завязал. Устал убивать и воровать, чтобы еле сводить концы с концами. Дальше я сам по себе...', '', 28153),
(155202, 'ruRU', 'Хе-хе-хе...', 'Хе-хе-хе...', 28153),
(155201, 'ruRU', 'Зачем ты прячешься от старых друзей?', '', 28153),
(155200, 'ruRU', 'Так-так, да это же Разгаджи! Я же говорил, что он здесь...', '', 28153),
(155199, 'ruRU', 'Будь начеку. Моджамбо нельзя доверять...', '', 28153),
(155198, 'ruRU', 'Ну все. Можно идти.', 'Ну все. Можно идти.', 28153),
(155197, 'ruRU', 'Море благословляет эти слитки.', 'Море благословляет эти слитки.', 28153),
(155196, 'ruRU', '', 'Сила нашего господина вновь возвеличит нас!', 28153),
(155195, 'ruRU', 'Ты можешь благословить эти слитки штормового серебра?', 'Ты можешь благословить эти слитки штормового серебра?', 28153),
(155194, 'ruRU', 'Попутного ветра, |3-6($r).', 'Попутного ветра, |3-6($r).', 28153),
(155193, 'ruRU', '', 'Все склонятся перед Королевой Азшарой!', 28153),
(155192, 'ruRU', '', 'Его воля выжжет тебе глаза!', 28153),
(155191, 'ruRU', 'Вытащить гарпун.', 'Вытащить гарпун.', 28153),
(155190, 'ruRU', '<Животное вяло смотрит на вас, а потом поворачивает голову к гарпуну, торчащему у него из бока.>', '<Животное вяло смотрит на вас, а потом поворачивает голову к гарпуну, торчащему у него из бока.>', 28153),
(155189, 'ruRU', 'Ты куда это?', '', 28153),
(155188, 'ruRU', 'Муга магуду! Бей их!', '', 28153),
(155187, 'ruRU', 'Угафа! Как наподдам!', '', 28153),
(155186, 'ruRU', 'Ах вы вонючки! Вон!', '', 28153),
(155185, 'ruRU', 'Это еще что за магуда?', '', 28153),
(155184, 'ruRU', 'Гуа-а-а-а! Эти камни - мои камни!', '', 28153),
(155183, 'ruRU', 'Уа-а-а! Не трогать сокровище!', '', 28153),
(155182, 'ruRU', 'Уа-а-а? Это кто?', '', 28153),
(155181, 'ruRU', 'Бва-а-а-а-а! Я скормлю тебя рыбам!', '', 28153),
(155180, 'ruRU', 'Агу?..', '', 28153),
(155179, 'ruRU', 'Хург!', '', 28153),
(155178, 'ruRU', 'Гафу... мого...', '', 28153),
(155177, 'ruRU', 'Уг...', '', 28153),
(155176, 'ruRU', 'Муг?!', '', 28153),
(155175, 'ruRU', 'Матуфа...', '', 28153),
(155174, 'ruRU', 'Гурк!', '', 28153),
(155173, 'ruRU', 'А-бу-бу-бу-бу!', '', 28153),
(155172, 'ruRU', 'Урга магуу?!', '', 28153),
(155171, 'ruRU', 'И-и-ип!', '', 28153),
(155170, 'ruRU', 'Буга буга!', '', 28153),
(155169, 'ruRU', 'А-а!', '', 28153),
(155168, 'ruRU', 'Ока магаду!', '', 28153),
(155167, 'ruRU', 'Бокум?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155166, 'ruRU', 'Буга мабугу!', '', 28153),
(155165, 'ruRU', 'А га ма гамба!', '', 28153),
(155164, 'ruRU', 'Его сердце совсем ослабло... я больше ничего не могу для него сделать. Только положить конец его страданиям.', '', 28153),
(155163, 'ruRU', 'Эшвейны назначили цену за твою голову!', 'Эшвейны назначили цену за твою голову!', 28153),
(155162, 'ruRU', 'Я ограблю твой труп!', 'Я ограблю твой труп!', 28153),
(155161, 'ruRU', 'Тебе не победить Эшвейнов!', 'Тебе не победить Эшвейнов!', 28153),
(155160, 'ruRU', 'Теперь этот город наш!', 'Теперь этот город наш!', 28153),
(155159, 'ruRU', 'Боралус сгорит!', 'Боралус сгорит!', 28153),
(155158, 'ruRU', 'Встретимся с тобой в безопасном месте!', 'Встретимся с тобой в безопасном месте!', 28153),
(155157, 'ruRU', 'Мне нужно в Друствар.', 'Мне нужно в Друствар.', 28153),
(155156, 'ruRU', 'Зачем... ты здесь?', '', 28153),
(155155, 'ruRU', 'Булыжники... мои...', '', 28153),
(155154, 'ruRU', 'Моя свеча!', '', 28153),
(155153, 'ruRU', 'Ой-ой-ой!', '', 28153),
(155152, 'ruRU', 'Гра-а!', '', 28153),
(155151, 'ruRU', 'Свеча... погасла...', '', 28153),
(155150, 'ruRU', 'А-а-а!', '', 28153),
(155149, 'ruRU', 'Нет!', '', 28153),
(155148, 'ruRU', 'Сжечь их, как большую свечку!', '', 28153),
(155147, 'ruRU', 'Теперь это моя свеча!', '', 28153),
(155146, 'ruRU', 'Бить! Крушить! Обирать!', '', 28153),
(155145, 'ruRU', 'Получи по черепушке!', '', 28153),
(155144, 'ruRU', 'Не трогать блестящие булыжники!', '', 28153),
(155143, 'ruRU', 'Мой остров! Я король!', '', 28153),
(155142, 'ruRU', 'Мои блестящие булыжники! Мои!', '', 28153),
(155141, 'ruRU', 'Мы нашли это место, не вы!', '', 28153),
(155140, 'ruRU', 'Это мое место!', '', 28153),
(155139, 'ruRU', 'Куси их! Забрать их свечки!', '', 28153),
(155138, 'ruRU', 'Гра-а! Нас атакуют!', '', 28153),
(155135, 'ruRU', 'Не трогай свечу!', '', 28153),
(155134, 'ruRU', 'Бишибош!', '', 28153),
(155133, 'ruRU', 'Блестящие булыжники – наши!', '', 28153),
(155132, 'ruRU', 'Блестящие булыжники – горящие свечи!', '', 28153),
(155131, 'ruRU', 'Удачи, и да помогут тебе боги... если они у тебя, конечно, есть.', 'Удачи, и да помогут тебе боги... если они у тебя, конечно, есть.', 28153),
(155130, 'ruRU', 'Все, вылезай. Дальше я не поплыву.', 'Все, вылезай. Дальше я не поплыву.', 28153),
(155129, 'ruRU', 'Я как-то бросил там якорь – так мне волки чуть ногу не оттяпали...', 'Я как-то бросила там якорь – так мне волки чуть ногу не оттяпали...', 28153),
(155128, 'ruRU', 'Мы пристанем чуть дальше. Гавань мясников сейчас – не самое приятное место.', 'Мы пристанем чуть дальше. Гавань мясников сейчас – не самое приятное место.', 28153),
(155127, 'ruRU', 'Не знаю, что у тебя там за дела, но лучше делай их побыстрее.', 'Не знаю, что у тебя там за дела, но лучше делай их побыстрее.', 28153),
(155126, 'ruRU', 'Я вот человек не суеверный, хоть и култирасец, но от Друствара даже у меня мурашки по коже.', 'Я вот не суеверная, хоть и из Кул-Тираса, но от Друствара даже у меня мурашки по коже.', 28153),
(155125, 'ruRU', 'Но теперь рудники будто истощились, а мясники вообще куда-то пропали.', 'Но теперь рудники будто истощились, а мясники вообще куда-то пропали.', 28153),
(155124, 'ruRU', 'Еще недавно торговцы часто захаживали в Друствар скупать товар у фермеров и шахтеров.', 'Еще недавно торговцы часто захаживали в Друствар скупать товар у фермеров и шахтеров.', 28153),
(155123, 'ruRU', 'Так-то паромщики туда больше не суются – из-за всяких мрачных слухов.', 'Так-то паромщики туда больше не суются – из-за всяких мрачных слухов.', 28153),
(155122, 'ruRU', 'В Друствар собираешься? Повезло тебе, что я туда еще хожу.', 'В Друствар собираешься? Повезло тебе, что я туда еще хожу.', 28153),
(155121, 'ruRU', 'Ай! Ой! А-а-а!', '', 28153),
(155120, 'ruRU', 'Ох...', '', 28153),
(155119, 'ruRU', 'Чтоб... ты... грукнул...', '', 28153),
(155118, 'ruRU', 'Ой! Прямо по орешкам!', '', 28153),
(155117, 'ruRU', 'А-а!', '', 28153),
(155116, 'ruRU', 'Гадкие... шнуропсы...', '', 28153),
(155115, 'ruRU', 'Бортельный... дукер...', '', 28153),
(155114, 'ruRU', 'Не-е-ет, мои блестяшки!', '', 28153),
(155113, 'ruRU', 'Разнообразная флора и фауна Зандалара требует исследования и каталогизации.', 'Разнообразная флора и фауна Зандалара требует исследования и каталогизации.', 28153),
(155112, 'ruRU', 'Откуда эти дукеры взялись?', '', 28153),
(155111, 'ruRU', 'Я тебя щас как укну!', '', 28153),
(155110, 'ruRU', 'Всех отгрукать, всех отдукать!', '', 28153),
(155109, 'ruRU', 'Великолепно! Лаборатория снова готова к работе!', '', 28153),
(155108, 'ruRU', 'Прости, за новую работу не берусь. Заказов по... э, да у тебя деньжата есть? Забудь, что я сказал. Чем могу помочь?', 'Прости, за новую работу не берусь. Заказов по... э, да у тебя деньжата есть? Забудь, что я сказала. Чем могу помочь?', 28153),
(155107, 'ruRU', 'У нас кончаются алхимические реагенты! Их можно набрать в окрестностях. Только не забывай про медведей, хорошо?', '', 28153),
(155106, 'ruRU', '', 'Соколиный Холм атакуют силы ковена! Очисти город от их порочных чар и восстанови порядок!', 28153),
(155105, 'ruRU', '', 'Ведьмы получили по заслугам, а Соколиный Холм снова в безопасности. Благодарю тебя.', 28153),
(155104, 'ruRU', 'Добро пожаловать! Все, что ты видишь, было тщательно отобрано... у местных. Попробуй что-нибудь новое и экзотическое!', 'Добро пожаловать! Все, что ты видишь, было тщательно отобрано... у местных. Попробуй что-нибудь новое и экзотическое!', 28153),
(155103, 'ruRU', 'Сукни отсюда, мои блестяшки!', '', 28153),
(155102, 'ruRU', 'Ах вы шнуропсы погруканые, это мой остров!', '', 28153),
(155101, 'ruRU', 'Растопчу, дукер!', '', 28153),
(155100, 'ruRU', 'Напильником по рубильнику!', 'Убить!', 28153),
(155099, 'ruRU', 'Сейчас будет производственная травма!', 'Забудем про технику безопасности!', 28153),
(155098, 'ruRU', 'Неудачников сразу видно!', 'Где мой разводной ключ! Кое-кого надо починить!', 28153),
(155097, 'ruRU', 'Срезали... лучше б выкрутили...', '', 28153),
(155096, 'ruRU', 'Ты убиваешь, но не побеждаешь...', '', 28153),
(155095, 'ruRU', 'Споры поглотят тебя...', '', 28153),
(155094, 'ruRU', 'Смерть... это не конец...', '', 28153),
(155093, 'ruRU', 'Мы покидаем это тело...', '', 28153),
(155092, 'ruRU', 'Наконец... славная... смерть.', '', 28153),
(155091, 'ruRU', 'Пора в землю.', '', 28153),
(155090, 'ruRU', 'Мы еще... отрастем...', '', 28153),
(155089, 'ruRU', 'За грибницу!', '', 28153),
(155088, 'ruRU', 'Единая воля!', '', 28153),
(155087, 'ruRU', 'Эй! У нас тут правила, а ты нарушаешь их все!', 'Я тебя... уволю!', 28153),
(155086, 'ruRU', 'Беги! Мы победили!', '', 28153),
(155085, 'ruRU', 'Пощекочем тебя ножиком!', '', 28153),
(155084, 'ruRU', 'Защитимся!', '', 28153),
(155083, 'ruRU', 'Этот бой тебе не выиграть!', '', 28153),
(155082, 'ruRU', 'Мало тренируешься!', '', 28153),
(155081, 'ruRU', 'Мы снесем тебе шляпку!', '', 28153),
(155080, 'ruRU', 'Пожалуйста, спасите Боралус!', 'Пожалуйста, спасите Боралус!', 28153),
(155079, 'ruRU', 'Эти пираты раздирают Боралус на части!', 'Эти пираты раздирают Боралус на части!', 28153),
(155078, 'ruRU', 'Спасибо тебе!', 'Спасибо тебе!', 28153),
(155077, 'ruRU', 'Наподдай шнуропсам!', '', 28153),
(155076, 'ruRU', 'Я тут король, шнуропсы!', '', 28153),
(155075, 'ruRU', 'Убить их! Взять их!', '', 28153),
(155074, 'ruRU', 'Злюкерные приплавцы!', '', 28153),
(155073, 'ruRU', 'Бей шнуропса!', '', 28153),
(155072, 'ruRU', 'Блестяшки делать нас сильнее!', '', 28153),
(155071, 'ruRU', 'Остров наш! Не ваш!', '', 28153),
(155070, 'ruRU', 'Иди в ук!', '', 28153),
(155069, 'ruRU', 'Не трожь блестяшки!', '', 28153),
(155068, 'ruRU', 'Шнуропсы нельзя!', '', 28153),
(155067, 'ruRU', 'Когда-то я научил Залазана и Вол\'джина всему, что знал сам. Кто бы мог подумать, что их судьбы так потрясут этот мир.', '', 28153),
(155066, 'ruRU', 'Я же просто работал!', 'Я же просто работала!', 28153),
(155065, 'ruRU', 'Надо было работать на тебя!', 'Надо было работать на тебя!', 28153),
(155064, 'ruRU', '', 'М-м-мда? Могу я чем-нибудь помочь?', 28153),
(155063, 'ruRU', 'Столько еще не выпито...', 'Столько еще не выпито...', 28153),
(155062, 'ruRU', 'Так и знал, что работенка дрянь!', 'Так и знала, что работенка дрянь!', 28153),
(155061, 'ruRU', 'Духи... я иду к вам...', 'Духи... я иду к вам...', 28153),
(155060, 'ruRU', 'Прилягу... на минутку...', 'Прилягу... на минутку...', 28153),
(155059, 'ruRU', 'Я про тебя... все расскажу...', '', 28153),
(155058, 'ruRU', 'Другой раз дай победить...', '', 28153),
(155057, 'ruRU', 'Ха-ха! Я победить... ой, нет...', '', 28153),
(155056, 'ruRU', 'Нет... я не проиграть...', '', 28153),
(155055, 'ruRU', 'Ты проблема... я исправлю.', '', 28153),
(155054, 'ruRU', 'Я термотехник. Я умный. Я делать огонь!', '', 28153),
(155053, 'ruRU', 'Ты сидеть в нефти... я дам спичку!', 'Ты сидеть в нефти... я дам спичку!', 28153),
(155052, 'ruRU', 'Я не любить огонь... у тебя огонь!', 'Я не любить огонь... у тебя огонь!', 28153),
(155051, 'ruRU', 'Поджарю тебя до корочки.', 'Поджарю тебя до корочки.', 28153),
(155050, 'ruRU', 'Зачем лезешь, куда не надо?', 'Зачем лезешь, куда не надо?', 28153),
(155049, 'ruRU', 'Не лезь ко мне, обожжешься!', 'Не лезь ко мне, обожжешься!', 28153),
(155048, 'ruRU', 'Ты у меня пошкварчишь!', 'Ты у меня пошкварчишь!', 28153),
(155047, 'ruRU', 'Кто-то просил погорячее?', 'Кто-то просил погорячее?', 28153),
(155046, 'ruRU', 'В пучине ему самое место.', '', 28153),
(155045, 'ruRU', 'Чудовище вернулось! Скорее, прогони его, пока оно не повредило стену еще сильнее.', '', 28153),
(155044, 'ruRU', 'Что? Вол\'джин... как ты получил такую силу... без...', '', 28153),
(155043, 'ruRU', 'Даже после смерти... я доберусь до тебя... и разорву на клочки!', '', 28153),
(155042, 'ruRU', 'Ты не победишь – только отсрочишь свою гибель.', '', 28153),
(155041, 'ruRU', 'Пока Бвонсамди терзал мою душу, я многому научился у него. Сейчас ты познаешь вуду смерти!', '', 28153),
(155040, 'ruRU', 'Вы не сможете прятать его от меня вечно. Я отомщу Вол\'джину и племени Черного Копья!', '', 28153),
(155039, 'ruRU', 'Слуги! Убейте врага и принесите мне прах Вол\'джина!', '', 28153),
(155038, 'ruRU', 'Где? Где вы спрятали Вол\'джина? Где его искать?', '', 28153),
(155037, 'ruRU', 'Где же вы прячете его? Где мой старинный друг?', '', 28153),
(155036, 'ruRU', 'Убейте этих троллей и найдите прах.', '', 28153),
(155035, 'ruRU', 'Отыщите прах Вол\'джина и принесите его мне.', '', 28153),
(155034, 'ruRU', 'Эти жуки жрут все, что найдут. Отвратительно.', '', 28153),
(155033, 'ruRU', 'Стая ранишу разрастается! Сократи их поголовье, а то у нас начнутся проблемы!', '', 28153),
(155032, 'ruRU', 'Думаю, да. Попутного ветра.', 'Думаю, да. Попутного ветра.', 28153),
(155031, 'ruRU', 'Вы указали мне нужное направление. С вами все будет в порядке?', 'Вы указали мне нужное направление. С вами все будет в порядке?', 28153),
(155030, 'ruRU', 'Мне жаль, что мы больше ничем не можем помочь.', 'Мне жаль, что мы с братом больше ничем не можем помочь.', 28153),
(155029, 'ruRU', '', 'Спасибо тебе! Я рада, что ты сражаешься на нашей стороне.', 28153),
(155028, 'ruRU', '', 'Песчаные пауки устроили гнездо рядом с ареной. Уничтожь его!', 28153),
(155027, 'ruRU', 'Похоже, это гномское изобретение. В общем, должно сработать!', '', 28153),
(155026, 'ruRU', 'Наши бойцы нашли интересное оружие. Если б только понять, как с ним управляться... ну-ка, испытай его на диких животных.', '', 28153),
(155025, 'ruRU', '', 'Славно! Им понадобятся недели, чтобы восполнить потери!', 28153),
(155024, 'ruRU', '', 'Корпорация Эшвейнов занимается темными делами неподалеку отсюда. Разберись с этим.', 28153),
(155023, 'ruRU', 'Сослать сотню неудачников на остров, забитый оружием! И продавать билеты на дирижабли над ним!', 'Сослать сотню неудачников на остров, забитый оружием! И продавать билеты на дирижабли над ним!', 28153),
(155022, 'ruRU', 'Вводим налог на роботов, а потом делаем роботов сборщиками налогов! Бесконечная прибыль!', 'Вводим налог на роботов, а потом делаем роботов сборщиками налогов! Бесконечная прибыль!', 28153),
(155021, 'ruRU', 'Лампочка наоборот! Как лампочка, только наоборот!', 'Лампочка наоборот! Как лампочка, только наоборот!', 28153),
(155020, 'ruRU', 'Маленькие строгие шляпы, которые можно надевать на каждодневные шляпы для официальных мероприятий!', 'Маленькие строгие шляпы, которые можно надевать на каждодневные шляпы для официальных мероприятий!', 28153),
(155019, 'ruRU', 'Моремы! Как тотемы, только для путешествий по морю!', 'Моремы! Как тотемы, только для путешествий по морю!', 28153),
(155018, 'ruRU', 'Ботинки-пистолеты! А, нет... уже было. НОСКИ-пистолеты!', 'Ботинки-пистолеты! А, нет... уже было. НОСКИ-пистолеты!', 28153),
(155017, 'ruRU', 'Ракеты многократного использования!', 'Ракеты многократного использования!', 28153),
(155016, 'ruRU', 'Всегоблинская бомбслейная команда!', 'Всегоблинская бомбслейная команда!', 28153),
(155015, 'ruRU', 'Оружейный сыр.', 'Оружейный сыр.', 28153),
(155014, 'ruRU', 'Двуручные боевые клинки с цепной пилой! И продавать их иллидари!', 'Двуручные боевые клинки с цепной пилой! И продавать их иллидари!', 28153),
(155013, 'ruRU', '\"Перидотовая дрема\" – когда хочется немного вздремнуть!', '\"Перидотовая дрема\" – когда хочется немного вздремнуть!', 28153),
(155012, 'ruRU', 'Тактические щипцы для барбекю!', 'Тактические щипцы для барбекю!', 28153),
(155011, 'ruRU', 'Роман... о любви человека и... э... цзинь-юй!', 'Роман... о любви человека и... э... цзинь-юй!', 28153),
(155010, 'ruRU', 'Спасибо тебе! Я рад, что ты сражаешься на нашей стороне.', '', 28153),
(155009, 'ruRU', 'Поддерживать крышу? Вчерашний день! Эта колонна не дает подняться полу!', 'Поддерживать крышу? Вчерашний день! Эта колонна не дает подняться полу!', 28153),
(155008, 'ruRU', 'Гнездо песчаных пауков перекрывает вход в каньон. Пожалуйста, расчисти путь для наших войск.', '', 28153),
(155007, 'ruRU', 'Азеритовый гадальный шар! Самые точные предсказания!', 'Азеритовый гадальный шар! Самые точные предсказания!', 28153),
(155006, 'ruRU', 'Угольные брикеты из Тельдрассила! Густой аромат барбекю!', 'Угольные брикеты из Тельдрассила! Густой аромат барбекю!', 28153),
(155005, 'ruRU', 'Машины, которые ездят по морю, аки по суху!', 'Машины, которые ездят по морю, аки по суху!', 28153),
(155004, 'ruRU', 'Барды!', 'Барды!', 28153),
(155003, 'ruRU', 'Свисток, который призывает к вам распорядителя полетов!', 'Свисток, который призывает к вам распорядителя полетов!', 28153),
(155002, 'ruRU', 'Спасибо! Вол\'дун, конечно, в рай не превратился, и все же в ущелье стало чуть спокойнее!', '', 28153),
(155001, 'ruRU', 'Какой-то чародейный кристалл, который делает вас лучше во всех отношениях! Немного нестабильный, ну да ладно!', 'Какой-то чародейный кристалл, который делает вас лучше во всех отношениях! Немного нестабильный, ну да ладно!', 28153),
(155000, 'ruRU', 'Огромный ранишу опустошает ущелье. Нападать на него опасно – он слишком свиреп. Найди другой способ остановить его.', '', 28153),
(154999, 'ruRU', 'Дробовики из туалетной бумаги! Экономят уйму времени!', 'Дробовики из туалетной бумаги! Экономят уйму времени!', 28153),
(154998, 'ruRU', 'Двухэтажные лодки! Сразу столько места освободится! Чур я сверху!', 'Двухэтажные лодки! Сразу столько места освободится! Чур я сверху!', 28153),
(154997, 'ruRU', 'Жвачка многократного применения! Делитесь с друзьями, питомцами и незнакомцами!', 'Жвачка многократного применения! Делитесь с друзьями, питомцами и незнакомцами!', 28153),
(154996, 'ruRU', 'Мда, грязная работенка. Но кто-то должен был за нее взяться... Кто-то, кроме меня.', '', 28153),
(154995, 'ruRU', 'Чтобы выжить, нам надо научиться обеспечивать себя едой. Для пустынной почвы нужны удобрения... Поищи что-нибудь.', '', 28153),
(154994, 'ruRU', 'Меня терзали смутные сомнения, но теперь они рассеялись. Тотем нам пригодится.', '', 28153),
(154993, 'ruRU', 'Тача раскопала в руинах очередной зандаларский тотем. Узнай, для чего его можно использовать.', '', 28153),
(154992, 'ruRU', 'Вот это да! Теперь я готов к теплой встрече с орками!', '', 28153),
(154991, 'ruRU', 'Операция удалась! Им понадобятся недели, чтобы восполнить потери!', '', 28153),
(154990, 'ruRU', 'Разведчики нашли этот тотем среди руин. Давай посмотрим, каково его действие.', '', 28153),
(154989, 'ruRU', 'Корпорация Эшвейнов незаконно присвоила рудник неподалеку отсюда. Разберись с этим.', '', 28153),
(154988, 'ruRU', 'Даже в вечных песках остается жизнь.', '', 28153),
(154987, 'ruRU', 'Вол\'дунские оазисы – бесценное сокровище. Мы должны беречь их.', '', 28153),
(154986, 'ruRU', 'Не каждая победа одерживается в славной битве. Припасы помогут нам выжить.', '', 28153),
(154985, 'ruRU', 'За уулл ог нук и фсш зз уу ийокк эз уу гул\'кафх анагг.', '', 28153),
(154984, 'ruRU', 'Этот оазис даст нам тактическое преимущество при продвижении вглубь континента.', '', 28153),
(154983, 'ruRU', 'Моя смерть – лишь удар пульса в бездонной тьме.', '', 28153),
(154982, 'ruRU', 'Вынужден признать, все прошло на удивление гладко.', '', 28153),
(154981, 'ruRU', 'Наши... нежданные союзники придумали новый план. Если ты им доверяешь, помоги им.', '', 28153),
(154980, 'ruRU', 'Ха! Будут знать, как связываться с Альянсом!', '', 28153),
(154979, 'ruRU', 'Наши солдаты угнали лодку и нагрузили ее оружием. Пора сразиться с нежитью!', '', 28153),
(154978, 'ruRU', 'Спасибо! В следующий раз они дважды подумают, прежде чем нападать на войска Альянса.', '', 28153),
(154977, 'ruRU', 'Пираты-нежить взяли в плен наших солдат. Освободи их. Мы своих не бросаем!', '', 28153),
(154976, 'ruRU', '', 'Спасибо. Даже изгои не заслуживают такой судьбы.', 28153),
(154975, 'ruRU', '', 'Зандалары-изгои попали в плен к пиратам Зем\'лана. Освободи их!', 28153),
(154974, 'ruRU', 'Отступники в растерянности. Обрушь на их головы смерть!', '', 28153),
(154973, 'ruRU', 'Они непременно вернутся. Но пока можно наслаждаться миром.', '', 28153),
(154972, 'ruRU', 'Отступникам нет числа. Нужно задержать их здесь.', '', 28153),
(154971, 'ruRU', 'Слава Сетралисс! Ее имя будет вечно жить в наших сердцах.', '', 28153),
(154970, 'ruRU', 'Я дам тебе силу, которая очистит наши земли от отступников.', '', 28153),
(154969, 'ruRU', '', 'Что ты... со мной делаешь?..', 28153),
(154968, 'ruRU', '', 'Эта сила... сковала меня...', 28153),
(154967, 'ruRU', 'Жизнь... уходит...', '', 28153),
(154966, 'ruRU', 'Не могу... пошевелиться...', '', 28153),
(154965, 'ruRU', 'Н-н-нг...', '', 28153),
(154964, 'ruRU', 'Вы думали, что можно бросить вызов богу? Умрите!', '', 28153),
(154963, 'ruRU', 'Больше крови! Утолите мою жажду!', '', 28153),
(154962, 'ruRU', 'Ваша кровь даст мне силу!', '', 28153),
(154961, 'ruRU', 'Работа – гадость! Хватит! Буду тренироваться! Стану знаменитым!', 'Работа – гадость! Хватит! Буду тренироваться! Стану знаменитой!', 28153),
(154960, 'ruRU', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t Азерокк готовится к применению |cFFFF0000|Hspell:258622|h[Резонансного импульса]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t Азерокк готовится к применению |cFFFF0000|Hspell:258622|h[Резонансного импульса]|h|r!', 28153),
(154959, 'ruRU', 'Единственное, чего вы добьетесь от этого грифона, так это того, что он вам руки пооткусывает.', 'Единственное, чего вы добьетесь от этого грифона, так это того, что он вам руки пооткусывает.', 28153),
(154956, 'ruRU', 'Тени растут. Избранные в сборе. Час пробил.', '', 28153),
(154955, 'ruRU', 'Ваша плоть насытит меня.', '', 28153),
(154954, 'ruRU', '', 'Моя сила... мое проклятье... не может быть...', 28153),
(154953, 'ruRU', 'Если... вернешься.', '', 28153),
(154952, 'ruRU', 'Когда я вернусь, мы поговорим о чести... и о том, как ее восстановить.', '', 28153),
(154951, 'ruRU', 'Отправьте его в тюрьму Штормграда.', '', 28153),
(154950, 'ruRU', 'Вы нужны только для пропитания.', '', 28153),
(154949, 'ruRU', 'Сейчас сужу именно я.', '', 28153),
(154948, 'ruRU', 'Не тебе об этом судить, король Альянса!', '', 28153),
(154947, 'ruRU', 'Но знай: в этой смерти не будет чести.', '', 28153),
(154946, 'ruRU', 'Отец говорил мне, что Варок Саурфанг – воплощение чести Орды.', '', 28153),
(154945, 'ruRU', 'Нет! Я требую честной смерти!', '', 28153),
(154944, 'ruRU', 'Солдаты, стойте!', '', 28153),
(154940, 'ruRU', '', 'Какие вы упорные! Что же, вам выпала честь увидеть момент моего торжества.', 28153),
(154939, 'ruRU', 'Всем сосредоточить огонь на чудовище! Наги не должны пробить нашу стену!', '', 28153),
(154937, 'ruRU', '<Встать в очередь на островную экспедицию на эпохальном уровне сложности группой.>', '<Встать в очередь на островную экспедицию на эпохальном уровне сложности группой.>', 28153),
(154936, 'ruRU', '<Встать в очередь на островную экспедицию на героическом уровне сложности группой.>', '<Встать в очередь на островную экспедицию на героическом уровне сложности группой.>', 28153),
(154935, 'ruRU', '<Встать в очередь на островную экспедицию на эпохальном уровне сложности.>', '<Встать в очередь на островную экспедицию на эпохальном уровне сложности.>', 28153),
(154934, 'ruRU', '<Встать в очередь на островную экспедицию на героическом уровне сложности.>', '<Встать в очередь на островную экспедицию на героическом уровне сложности.>', 28153),
(154933, 'ruRU', 'Ступай, возведи мне статую на ступенях Дазар\'алора. Покажи всем мощь нашей стаи, и я одарю тебя своей милостью.', '', 28153),
(154932, 'ruRU', '', 'Вот тебе свитки. С ними путешествовать веселее. И быстрее!', 28153),
(154931, 'ruRU', '|TInterface\\ICONS\\Ability_Skyreach_Four_Wind.BLP:20|t %s смотрит на |cFFFF0000|3-1($n)|r и готовится применить |cFFFF0000|Hspell:268403|h[Порыв борея]|h|r!', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s готовится применить |cFFFF0000|Hspell:268932|h[Сотрясающий землю прыжок]|h|r к игроку |cFFFF0000$n|r!', 28153),
(154930, 'ruRU', 'Хотя бы я умру... на своих двоих...', '', 28153),
(154929, 'ruRU', 'Прекрасный бросок! Наконец кто-то, достойный моего внимания.', '', 28153),
(154928, 'ruRU', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t%s находится |cFFFF0000|Hspell:271556|h[в саркофаге]|h|r! Найдите саркофаг, по крышке которого стучат!', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t%s находится |cFFFF0000|Hspell:271556|h[в саркофаге]|h|r! Найдите саркофаг, по крышке которого стучат!', 28153),
(154927, 'ruRU', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t Вы погребены! |cFFFF0000|Hspell:267764|h[Стучите]|h|r по крышке саркофага, чтобы дать союзникам знать, где вы находитесь!', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t Вы погребены! |cFFFF0000|Hspell:267764|h[Стучите]|h|r по крышке саркофага, чтобы дать союзникам знать, где вы находитесь!', 28153),
(154926, 'ruRU', 'Надо скорее возвращаться в святилище и остановить Джакра\'зета, пока он не выпустил Митракса!', '', 28153),
(154925, 'ruRU', 'Глупец! Никто не сможет повелевать Митраксом!', '', 28153),
(154924, 'ruRU', 'Он воскресит Митракса, и вместе мы завоюем Азерот!', '', 28153),
(154923, 'ruRU', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s готовится к |cFFFF0000|Hspell:267702|h[Погребению]|h|r игрока |cFFFF0000$n|r!', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s готовится к |cFFFF0000|Hspell:267702|h[Погребению]|h|r игрока |cFFFF0000$n|r!', 28153),
(154922, 'ruRU', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s готовится применить |cFFFF0000|Hspell:268932|h[Сотрясающий землю прыжок]|h|r к игроку |cFFFF0000$n|r!', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s готовится применить |cFFFF0000|Hspell:268932|h[Сотрясающий землю прыжок]|h|r к игроку |cFFFF0000$n|r!', 28153),
(154921, 'ruRU', 'Кортек, выходи! Ты заплатишь за предательство!', '', 28153),
(154920, 'ruRU', '', 'Моя задача – наблюдать. Зандаларов очень интересуют Отрекшиеся.', 28153),
(154919, 'ruRU', '', 'О, я тебя не разочарую, Гнилостень.', 28153),
(154918, 'ruRU', '', 'Я выясню, почему дорога перекрыта. Попробуй договориться с солдатами.', 28153),
(154917, 'ruRU', 'Сворачиваемся. У нас есть дела поважнее.', 'Сворачиваемся. У нас есть дела поважнее.', 28153),
(154916, 'ruRU', 'Отцепись, вша!', 'Отцепись, вша!', 28153),
(154915, 'ruRU', 'Да провались ты!..', 'Да провались ты!..', 28153),
(154914, 'ruRU', 'Я поддавался.', 'Я поддавалась.', 28153),
(154913, 'ruRU', 'Как я от тебя устал.', 'Как я от тебя устала.', 28153),
(154912, 'ruRU', '', 'Ты слишком много внимания уделяешь деталям! Все будет нормально!', 28153),
(154911, 'ruRU', '', 'У всего своя цена – и эти мерзкие ползуны принесут мне целое состояние! Надо только переправить их в Калимдор.', 28153),
(154910, 'ruRU', '', 'Чтобы выжить, им нужна кровь. Чем ты собираешься их кормить?', 28153),
(154909, 'ruRU', '', 'Зачем ты складываешь в коробку паразитов?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154908, 'ruRU', 'Немедленно освободите проезд.', 'Немедленно освободите проезд.', 28153),
(154907, 'ruRU', 'Вижу, годы не притупили твой ум и не смягчили характер. Мы накажем отступников за то, что они сделали с тобой и твоими детьми.', '', 28153),
(154906, 'ruRU', 'Только через мой труп.', 'Только через мой труп.', 28153),
(154905, 'ruRU', 'Тебе что, уши заложило? Долина закрыта.', 'Тебе что, уши заложило? Долина закрыта.', 28153),
(154904, 'ruRU', 'Противогаз и канистру с чумой, пожалуйста. Хочу посмотреть, на что способна эта штука.', 'Противогаз и канистру с чумой, пожалуйста. Хочу посмотреть, на что способна эта штука.', 28153),
(154903, 'ruRU', 'Мне, пожалуйста, только противогаз.', 'Мне, пожалуйста, только противогаз.', 28153),
(154902, 'ruRU', 'А ну назад, трюмная крыса.', 'А ну назад, трюмная крыса.', 28153),
(154901, 'ruRU', 'Нет документов – нет прохода. Такие правила.', 'Нет документов – нет прохода. Такие правила.', 28153),
(154899, 'ruRU', 'Сильная спина Ай\'твена, моя гениальная стратегия и твоя смелость – вот залог успеха.', '', 28153),
(154898, 'ruRU', 'А я поднимусь на вершину горы к Ракжану. Надеюсь, он помнит меня. Столько лет прошло...', '', 28153),
(154897, 'ruRU', '', 'Отдохну, когда раненые перестанут поступать.', 28153),
(154896, 'ruRU', '', 'Со мной все в порядке. Я нужна этим морякам.', 28153),
(154895, 'ruRU', 'Такими темпами тебе самой скоро понадобится лекарь. Если сляжешь, то точно ничем им не поможешь.', '', 28153),
(154894, 'ruRU', 'Феория, ты устала, тебе надо отдохнуть.', '', 28153),
(154893, 'ruRU', 'Заряди мой посох энергией подавляющих шпилей отступников.', '', 28153),
(154892, 'ruRU', 'Мы с Ай\'твеном подождем тебя у минного поля Торговой компании.', '', 28153),
(154891, 'ruRU', 'Мама! $p с Миирой нас спасли!', 'Мама! $p с Миирой нас спасли!', 28153),
(154890, 'ruRU', 'А я говорила, что Миира про нас не забудет! Она лучше всех!', 'А я говорила, что Миира про нас не забудет! Она лучше всех!', 28153),
(154889, 'ruRU', '', 'Киро! Я так рада, что ты вернулся! Ну, как там? Страшно было? Где ты взял этого кролуска? Как его зовут? Можно я дам ему имя? Он не кусается?', 28153),
(154888, 'ruRU', 'Миира, я тебе все расскажу, но сперва давай отведем наших в безопасное место.', '', 28153),
(154887, 'ruRU', 'Кажется... было весело?', '', 28153),
(154886, 'ruRU', 'Прыгай на кролуска. Пора убираться, пока не пришло подкрепление.', '', 28153),
(154885, 'ruRU', '', 'Что это там? Буревестница, давай на посадку!', 28153),
(154884, 'ruRU', '', 'Начнем поиски в Бреннадаме. По крайней мере, поговорим с этим братом Пайком.', 28153),
(154883, 'ruRU', '', 'Лорд Штормсонг – глава дома и всей долины. Уверена, он знает ответы на все вопросы, но в Боралусе его уже давно не видели.', 28153),
(154882, 'ruRU', '', 'Для начала нужно разобраться с домом Штормсонгов. Они управляют жрецами моря, а те – флотом.', 28153),
(154881, 'ruRU', '', 'Трепещите перед знаменами вульпер, мерзкие отступники!', 28153),
(154880, 'ruRU', 'Чтобы выжить среди чумы, тебе понадобится противогаз. Если хочешь, можешь заодно взять канистру с чумой.', 'Чтобы выжить среди чумы, тебе понадобится противогаз. Если хочешь, можешь заодно взять канистру с чумой.', 28153),
(154879, 'ruRU', '', 'Боюсь, Кул-Тирас мало чем сможет помочь Альянсу, пока не вернется флот.', 28153),
(154878, 'ruRU', '', 'А наши соплеменники, которых держат в цепях, пусть знают, что мы их не оставили!', 28153),
(154877, 'ruRU', '', 'И ладно! Пусть знают, кто их убьет.', 28153),
(154876, 'ruRU', 'Ниша, это опасно. Отступники узнают, что мы здесь.', '', 28153),
(154875, 'ruRU', 'Теперь солдаты лича перестанут убивать наших разведчиков, и мы сможем сосредоточиться на Орде.', '', 28153),
(154874, 'ruRU', 'В Друстваре полно ведьм, а в Назмире сидит лич. Истреби его армию и уничтожь источник его силы.', '', 28153),
(154873, 'ruRU', '', 'Ниша будет рада тебя видеть! Она у кратера, охотится на сетраков... как обычно.', 28153),
(154872, 'ruRU', 'Впечатляет. Правда, гномы принципиально отказываются работать с технологиями гоблинов. Но теперь мы хотя бы знаем, на что эта машина способна.', '', 28153),
(154871, 'ruRU', 'Мы захватили экспериментальный гоблинский агрегат. Рядом как раз собралась армия троллей крови – предлагаю испытать его на них.', '', 28153),
(154870, 'ruRU', 'Думается, у наг еще остались и силы, и злодейские планы. Будь начеку.', '', 28153),
(154869, 'ruRU', 'Наги! Хватит им нагонять страх на жителей нашего мира. Разберись с ними!', '', 28153),
(154866, 'ruRU', 'Со времен Третьей войны я не видал, чтобы кто-либо сражался с Ордой так яростно.', '', 28153),
(154864, 'ruRU', 'Жители Кул-Тираса обязательно узнают о твоих подвигах.', '', 28153),
(154863, 'ruRU', 'Надеюсь, этот конфликт закончится лучше, чем Вторая война.', '', 28153),
(154861, 'ruRU', '', 'Детей держат в кратере внизу. Пожалуйста, будь осторожнее!', 28153),
(154859, 'ruRU', 'Молодца! Орду не остановить!', '', 28153),
(154858, 'ruRU', 'Орда что-то затевает. Я потерял нескольких разведчиков, но все без толку. Выясни, что происходит.', '', 28153),
(154857, 'ruRU', 'Вот это да! Надо бы мне у тебя поучиться!', '', 28153),
(154856, 'ruRU', 'Один враг мертв, другой еще не занял его место. Можно отдохнуть.', '', 28153),
(154855, 'ruRU', '', 'Я позову Буревестницу. Она подберет нас на площадке в восточном доке.', 28153),
(154854, 'ruRU', 'Победа! Сладкий вкус победы!', '', 28153),
(154853, 'ruRU', 'Во время Третьей войны я изучил тактику Орды, и то, что они делают сейчас, мне очень не нравится. Останови их.', '', 28153),
(154852, 'ruRU', 'Ха-ха, что, не ждали такого?', '', 28153),
(154851, 'ruRU', 'Нынешняя тактика Орды напоминает мне о Второй войне. Нужно сорвать их операцию, пока не поздно.', '', 28153),
(154850, 'ruRU', 'Вот это ты даешь!', '', 28153),
(154848, 'ruRU', 'Сильный дух где-то рядом. Упокой его!', '', 28153),
(154846, 'ruRU', 'Где-то рядом прячется враг. Убей его!', '', 28153),
(154845, 'ruRU', 'Выражаю тебе благодарность от всего 7-го легиона!', '', 28153),
(154843, 'ruRU', 'Славная победа. Теперь 7-й легион сможет двигаться дальше!', '', 28153),
(154842, 'ruRU', 'Король Андуин узнает о твоих подвигах.', '', 28153),
(154838, 'ruRU', 'Разведчики доложили, что неподалеку проходит отряд Орды. Устрой засаду и уничтожь их!', '', 28153),
(154836, 'ruRU', 'Большой отряд Орды встал лагерем неподалеку отсюда. Самое время нанести удар!', '', 28153),
(154833, 'ruRU', 'Цель рядом! Скорее, атакуй!', '', 28153),
(154832, 'ruRU', 'Седьмой легион обнаружил силы Орды на марше недалеко отсюда. Что бы они ни задумали, помешай им!', '', 28153),
(154831, 'ruRU', 'Еще одна угроза. Ты знаешь, что делать.', '', 28153),
(154830, 'ruRU', 'Духи говорят о сильном враге. Нужно убить его, пока он не натворил тут дел.', '', 28153),
(154829, 'ruRU', 'Я чувствую серьезную угрозу. Устрани ее!', '', 28153),
(154828, 'ruRU', 'Замечательно! Если ты когда-нибудь захочешь вступить в 7-й легион, мы с удовольствием тебя примем!', '', 28153),
(154827, 'ruRU', 'Прекрасно. За короля Андуина! За Альянс!', '', 28153),
(154826, 'ruRU', '7-й легион и армия Альянса благодарят тебя за службу.', '', 28153),
(154825, 'ruRU', 'Благодарю тебя от имени всех бойцов 7-го легиона.', '', 28153),
(154824, 'ruRU', 'Я расскажу королю Андуину о твоей храбрости.', '', 28153),
(154823, 'ruRU', 'Разведчики сообщают: рядом с твоей позицией замечен опасный враг. Убей его.', '', 28153),
(154822, 'ruRU', '7-му легиону приказано уничтожить важную цель... Ты как раз рядом с ней.', '', 28153),
(154821, 'ruRU', 'В следующий раз им стоит быть осторожней. Мы не всегда сможем вытаскивать их из передряг. Спасибо тебе.', '', 28153),
(154820, 'ruRU', 'Нежить поймала в ловушку команду исследователей! Скорее, спаси их!', '', 28153),
(154819, 'ruRU', 'Мы и сами справимся. Пора уже покончить с Г\'ууном.', '', 28153),
(154818, 'ruRU', 'Фу, так это живой труп? Давайте зароем его обратно в землю!', '', 28153),
(154817, 'ruRU', 'Я узнаю этого безобразного тролля. Зул, ты ли это?', '', 28153),
(154816, 'ruRU', '...', '', 28153),
(154815, 'ruRU', '...', '', 28153),
(154814, 'ruRU', '...', '', 28153),
(154813, 'ruRU', '...', '', 28153),
(154812, 'ruRU', '...', '', 28153),
(154811, 'ruRU', '...', '', 28153),
(154810, 'ruRU', '...', '', 28153),
(154809, 'ruRU', '...', '', 28153),
(154808, 'ruRU', 'Все, да не все!', '', 28153),
(154807, 'ruRU', '', 'В лаборатории проводились эксперименты с целью поиска способов борьбы с порчей Древних богов.', 28153),
(154806, 'ruRU', 'Ого! Это что за пугало?!', '', 28153),
(154805, 'ruRU', '...', '', 28153),
(154804, 'ruRU', 'Я слышал рассказы о слугах Н\'Зота, но не думал, что когда-нибудь встречу одного из них. Надеюсь, это был последний раз.', '', 28153),
(154803, 'ruRU', 'Чуть не сплоховали. Если бы это чудище ушло от нас, кто знает, скольких бы оно заразило.', '', 28153),
(154802, 'ruRU', 'Так и сделаем. И раз уж мы тут, я гляну, какие еще секреты титаны могли оставить.', '', 28153),
(154801, 'ruRU', '...', '', 28153),
(154800, 'ruRU', 'Охо-хо! Боюсь, столько времени у нас нет. Надо разделаться с Г\'ууном, пока от его гнили всем не поплохело.', '', 28153),
(154799, 'ruRU', 'И как, есть результаты?', '', 28153),
(154798, 'ruRU', 'Теперь ясно, почему вокруг столько троллей крови. Но зачем титанам оставлять в живых Древнего бога?', '', 28153),
(154797, 'ruRU', 'Как же я рад вас видеть! Судя по всему, мы в каком-то исследовательском комплексе.', '', 28153),
(154796, 'ruRU', 'Ага! Есть контакт! Любая штуковина поддастся, если делать все по уму.', '', 28153),
(154795, 'ruRU', 'В двенадцатый раз!', '', 28153),
(154794, 'ruRU', 'Что?! Треклятая дверь запечатана! Крушите все, вдруг что-нибудь откроется!', '', 28153),
(154793, 'ruRU', 'Сейчас открою дверь. Плевое дело.', '', 28153),
(154792, 'ruRU', 'А, вот и вы! Один момент, я как раз натолкнулся на смотрительницу лаборатории. Это она тут всем заправляет.', '', 28153),
(154791, 'ruRU', 'Я стал легендой.', '', 28153),
(154789, 'ruRU', 'Битва не стихает. Продолжай бороться с нашими врагами!', '', 28153),
(154788, 'ruRU', 'Поблизости замечена важная цель. Уничтожь ее, и как можно скорее!', '', 28153),
(154787, 'ruRU', 'Где-то поблизости очень опасный враг. Уничтожь его. Никакой пощады!', '', 28153),
(154780, 'ruRU', 'Готовься к бою.', 'Готовься к бою.', 28153),
(154779, 'ruRU', '', 'Торканата! Ха! Ха!', 28153),
(154777, 'ruRU', '', 'Сегодня у нас Торканата! Хватай факел и приготовься бежать.', 28153),
(154774, 'ruRU', '', 'Похоже, ты делаешь верные шаги в отношениях с зандаларами. Удачи тебе. А меня ждут неотложные дела.', 28153),
(154772, 'ruRU', '', 'Окулет, посмотри, на что годится эта сеть. Нам нужно наладить постоянное сообщение со столицами Орды.', 28153),
(154770, 'ruRU', 'Мы должны проникнуть в крепость Кортека, $p. Встретимся в руинах Бволджина.', '', 28153),
(154769, 'ruRU', '', 'Принцесса Таланджи любезно сообщила нам о старой сети порталов, к которой можно подключиться.', 28153),
(154768, 'ruRU', '', 'Скажите, когда будете готовы покончить с флотом Эшвейн.', 28153),
(154767, 'ruRU', '', 'Вы храбро сражались, но Боралусу все еще грозит опасность.', 28153),
(154766, 'ruRU', 'Продолжайте работу. Это свои.', 'Продолжайте работу. Это свои.', 28153),
(154765, 'ruRU', 'Брат, посторонним нельзя входить в архивы.', 'Брат, посторонним нельзя входить в архивы.', 28153),
(154764, 'ruRU', 'Я стоял на пляже, в окружении злобных гоблинов... и явился герой! О! И снова здравствуй, $n!', '', 28153),
(154763, 'ruRU', 'Найди свитки! А я вернусь в лагерь... по живописному пути! И расскажу остальным обо всем, что мы узнали.', '', 28153),
(154762, 'ruRU', 'Что бы Альянс ни делал, их ожидает поражение.', '', 28153),
(154761, 'ruRU', 'Герои Альянса пытаются спасти город и вступили в бой с пиратами. Помешайте им.', '', 28153),
(154760, 'ruRU', 'Теперь мы посеем в рядах Альянса настоящую панику.', '', 28153),
(154759, 'ruRU', 'Бойцы Эшвейн обстреливают город из азеритовых орудий... И эти орудия пригодятся Орде.', '', 28153),
(154758, 'ruRU', 'Вместе с офицерами култирасцы потеряют и последние шансы на победу.', '', 28153),
(154757, 'ruRU', 'Кто-то из кул-тирасских офицеров пытается организовать оборону. Разберитесь с ними.', '', 28153),
(154756, 'ruRU', '', 'Так их! Никому и никогда не захватить Боралус!', 28153),
(154755, 'ruRU', '', 'Мародеры из Орды воспользовались осадой и грабят город! Выгоните их из Боралуса!', 28153),
(154754, 'ruRU', '', 'Ух ты! Против ваших навыков не устоят никакие наемники!', 28153),
(154753, 'ruRU', '', 'Один из наемников Эшвейн наводит ужас на местных жителей. Убейте его.', 28153),
(154752, 'ruRU', '', 'Молодцы. Уж кто должен сидеть в оковах, так это пираты.', 28153),
(154751, 'ruRU', '', 'Пираты угоняют мирных жителей в рабство! Остановите их!', 28153),
(154750, 'ruRU', 'Горак Тул... придет...', '', 28153),
(154749, 'ruRU', 'Кул-Тирас обречен. И ты будешь первой жертвой!', '', 28153),
(154748, 'ruRU', 'Ты умрешь, вопя от боли!', '', 28153),
(154747, 'ruRU', 'Ооу ф\'магг ан\'ков нук.', '', 28153),
(154746, 'ruRU', 'Ивак онгг уул\'гва но Ан\'зиг!', '', 28153),
(154745, 'ruRU', 'Арви риу ирр ооу кам!', '', 28153),
(154744, 'ruRU', 'Ан\'зиг вга кам за зиктаг...', '', 28153),
(154743, 'ruRU', 'Ан\'зиг вга ззоф!', '', 28153),
(154742, 'ruRU', 'Ивак фсш вга кам!', '', 28153),
(154741, 'ruRU', 'Уулг\'ма зиктаг ирр!', '', 28153),
(154740, 'ruRU', 'Накф ивак шуул\'ва явифк ирр уулл зз тизз!', '', 28153),
(154739, 'ruRU', 'Уходите, пока можете! Вы привлекли слишком много внимания.', 'Уходите, пока можете! Вы привлекли слишком много внимания.', 28153),
(154738, 'ruRU', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t На вас нацелено заклинание |cFFFF0000|Hspell:260838|h[Мощный удар буром]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t На вас нацелено заклинание |cFFFF0000|Hspell:260838|h[Мощный удар буром]|h|r!', 28153),
(154737, 'ruRU', 'Ог кам шфк вга иикаа халас ма!', '', 28153),
(154736, 'ruRU', 'Найдите брата Пайка в Бреннадаме. Отдайте ему эту подвеску. Ему понадобится ваша помощь.', 'Найдите брата Пайка в Бреннадаме. Отдайте ему эту подвеску. Ему понадобится ваша помощь.', 28153),
(154735, 'ruRU', 'Мак ооу каакст зз ак\'ук ирр ск\'иахф ма!', '', 28153),
(154734, 'ruRU', 'Жрецы моря связались с темными силами. Но среди нас есть и те, кто пытается сопротивляться.', 'Жрецы моря связались с темными силами. Но среди нас есть и те, кто пытается сопротивляться.', 28153),
(154733, 'ruRU', 'Зук аг\'ксиг ка\'кар за вга!', '', 28153),
(154732, 'ruRU', 'Пуул ки\'плаф ни ооу бормакс!', '', 28153),
(154731, 'ruRU', 'Ксит вга!', '', 28153),
(154729, 'ruRU', 'Наз ракул!', '', 28153),
(154728, 'ruRU', 'И вга фар\'ал зук ни шн!', '', 28153),
(154727, 'ruRU', 'Флот не потерялся. Его удерживают в сверхъестественном шторме.', 'Флот не потерялся. Его удерживают в сверхъестественном шторме.', 28153),
(154726, 'ruRU', 'Зук вга кам н\'лиет!', '', 28153),
(154725, 'ruRU', 'Зук аг\'ксиг гаг вга наггуа\'фсш!', '', 28153),
(154724, 'ruRU', 'Зук аг\'ксиг бормакс ооу иикаат!', '', 28153),
(154723, 'ruRU', 'Вы в порядке? Зря я рассчитывал, что Уэйд не поддастся тьме, которая поглотила дом Штормсонгов.', 'Вы в порядке? Зря я рассчитывал, что Уэйд не поддастся тьме, которая поглотила дом Штормсонгов.', 28153),
(154722, 'ruRU', '', 'Что значит \"опасность\"?', 28153),
(154721, 'ruRU', 'Хорошо, брат.', 'Хорошо, брат.', 28153),
(154720, 'ruRU', 'Никого не пускать. У меня гости.', 'Никого не пускать. У меня гости.', 28153),
(154719, 'ruRU', 'Вы не представляете, какая вам грозит опасность.', '', 28153),
(154718, 'ruRU', 'За мной. Глаза в пол.', '', 28153),
(154717, 'ruRU', 'Наши укрепления еще не готовы. Остановите ордынский отряд, пока он не дошел до стен!', '', 28153),
(154716, 'ruRU', 'Стромгард еще не укреплен, ему не выдержать штурма. Уничтожьте авангард Орды на подходе!', '', 28153),
(154715, 'ruRU', 'Вот как надо прославлять Па\'ку!', '', 28153),
(154714, 'ruRU', 'Высылаем войска! Раздавим тварей до того, как они укрепятся!', '', 28153),
(154713, 'ruRU', '', 'Время пришло! Взойди на ступени Занчула и вознеси хвалу нашему лоа. С его помощью Зандалар выстоит! Пусть Гонк гордится тобой!', 28153),
(154712, 'ruRU', '', 'Войска, в бой! Не позволим Альянсу удержать контроль над крепостью!', 28153),
(154711, 'ruRU', 'К оружию! Сейчас будет драка!', '', 28153),
(154710, 'ruRU', 'Начать наступление! Стены Стромгарда не выстоят перед мощью Орды!', '', 28153),
(154709, 'ruRU', 'Крепость надо спасать! Не подпускайте врагов слишком близко.', '', 28153),
(154708, 'ruRU', 'Быстро в Святилище Штормов! Карты нужны лорду как можно скорее!', '', 28153),
(154707, 'ruRU', 'Солдаты, в атаку! Сровняем их базу с землей.', '', 28153),
(154706, 'ruRU', '', 'У жрецов моря одна из лучших библиотек в мире. Уверена, этот архивариус наверняка там.', 28153),
(154705, 'ruRU', '', 'Альянс выступает к Ар\'гороку! Не подпускайте их к крепости!', 28153),
(154704, 'ruRU', 'Солдаты Альянса! Уничтожьте врага!', '', 28153),
(154703, 'ruRU', 'В атаку, солдаты Лиги!', '', 28153),
(154702, 'ruRU', 'Орда, в бой! Перебейте этих трусов, пока они не прорвались за ворота!', '', 28153),
(154701, 'ruRU', '', 'Заряжай! Заряжай!', 28153),
(154700, 'ruRU', 'Заряжай! Заряжай!', '', 28153),
(154699, 'ruRU', '', 'Похоже, он не шутит. Пойдем-ка отсюда.', 28153),
(154698, 'ruRU', 'Катитесь в архивы к этому идиоту Алену! А не то брошу вас в разлом.', '', 28153),
(154697, 'ruRU', 'Идиоты, удвоить усилия! Мы теряем контроль!', '', 28153),
(154696, 'ruRU', '', 'Ладно, как скажешь.', 28153),
(154695, 'ruRU', '', 'Вам больше нечем заняться? Идите доставайте Алена.', 28153),
(154694, 'ruRU', '', 'Откройте души морю. Вы услышите шепот истины!', 28153),
(154693, 'ruRU', 'Посев семян', 'Посев семян', 28153),
(154692, 'ruRU', '', 'Гилнеасцы, заряжай! Вперед!', 28153),
(154691, 'ruRU', 'Дамы и господа, заводите моторы! В атаку!', '', 28153),
(154690, 'ruRU', 'Стрелки, оружие к бою! Заряжай!', 'Стрелки, оружие к бою! Заряжай!', 28153),
(154689, 'ruRU', '', 'Твой корабль будет в безопасности. За достойную цену, разумеется.', 28153),
(154688, 'ruRU', '', 'Какая трагедия. Думаю, больше не стоит устраивать здесь венчания.', 28153),
(154687, 'ruRU', '', 'Радостная церемония безнадежно испорчена. Перебей монстров, которые в ответе за это, и спаси гостей!', 28153),
(154686, 'ruRU', '', 'Видимо, это значит \"нет\"?', 28153),
(154685, 'ruRU', '', 'Вы почти так же невыносимы, как брат Ален.', 28153),
(154684, 'ruRU', '', 'Эй, кто здесь за главного?', 28153),
(154683, 'ruRU', '<Хмыкает>', '<Хмыкает>', 28153),
(154682, 'ruRU', 'Осушите свои раны. Пойте в агонии!', '', 28153),
(154681, 'ruRU', 'Не бегите от безумия. Впитайте его!', '', 28153),
(154680, 'ruRU', 'Узрите красоту в упадке и примите ее!', '', 28153),
(154679, 'ruRU', 'От вас останется лишь пепел!', '', 28153),
(154678, 'ruRU', 'Залзеикс требует разрушения!', '', 28153),
(154677, 'ruRU', 'Никто не выживет!', '', 28153),
(154676, 'ruRU', 'Вы все будете уничтожены!', '', 28153),
(154675, 'ruRU', 'От теней не скрыться!', '', 28153),
(154674, 'ruRU', 'Истребление!', '', 28153),
(154673, 'ruRU', 'Уничтожение!', '', 28153),
(154672, 'ruRU', 'Вы покоритесь моей воле.', '', 28153),
(154671, 'ruRU', 'Отдайтесь во власть чумы!', '', 28153),
(154670, 'ruRU', 'Г\'ууна не остановить...', '', 28153),
(154669, 'ruRU', 'Гниль поглотит все.', '', 28153),
(154668, 'ruRU', 'Твой труп принадлежит Г\'ууну.', '', 28153),
(154667, 'ruRU', 'Больше пищи для гнили!', '', 28153),
(154666, 'ruRU', 'Г\'уун восстанет!', '', 28153),
(154665, 'ruRU', 'Вашему миру конец!', '', 28153),
(154664, 'ruRU', 'Вы все равно сгниете.', '', 28153),
(154663, 'ruRU', 'Я – комок в ваших глотках. Я – зуд в ваших мозгах. Я всегда был с вами.', '', 28153),
(154662, 'ruRU', 'Вся жизнь угасает. Смиритесь и переродитесь.', '', 28153),
(154661, 'ruRU', '', 'Реактор пересозидания перезапущен. Доступ в камеру открыт.', 28153),
(154660, 'ruRU', '', 'Консоль активирована. Перезагрузка систем безопасности.', 28153),
(154659, 'ruRU', 'А, и еще одна штука... то есть две.', '', 28153),
(154658, 'ruRU', '', 'Первая консоль активирована. Восстанавливаю энергоматрицу.', 28153),
(154657, 'ruRU', '', 'Объект Г\'уун уничтожен. Образцов живой ткани не осталось.', 28153),
(154656, 'ruRU', '', 'Уровень порчи снижается. Целостность системы восстановлена.', 28153),
(154655, 'ruRU', 'А когда планета лопнет, как гигантский нарыв, гниль рассеется по всему космосу.', '', 28153),
(154654, 'ruRU', 'Вы разнесете чуму, и весь мир превратится в огромную пузырящуюся кисту!', '', 28153),
(154653, 'ruRU', 'Мои радушные хозяева. Вы первыми получите мой дар.', '', 28153),
(154652, 'ruRU', 'Печати сломаны. Титаны мертвы. Грядет эпоха гниения.', '', 28153),
(154651, 'ruRU', '', 'Это тебе за разрушенный Дазар\'алор, подлая тварь!', 28153),
(154650, 'ruRU', '', 'Не беспокойся. Мы сами остановим чуму Г\'ууна.', 28153),
(154649, 'ruRU', '', 'Тревога! Угроза заражения возрастает. Согласно протоколу карантина я не могу следовать дальше.', 28153),
(154648, 'ruRU', 'Прекрасно, $p! У нас хватит мин, чтобы нанести сокрушительный удар Торговой компании.', '', 28153),
(154647, 'ruRU', '', 'Неважно, как он воскрес. Мой нож отправит его обратно в бездну.', 28153),
(154646, 'ruRU', 'Столько мин – выбирай любую!', '', 28153),
(154645, 'ruRU', '', 'Анализ выявил высокий уровень порчи. Гипотеза: Г\'уун реанимировал эту особь и усилил ее. Требуется дальнейшее изучение.', 28153),
(154644, 'ruRU', '', 'Зул?! Как он выжил? Я видела, как мой отец убил его!', 28153),
(154643, 'ruRU', 'Мины не реагируют на черепах! Можно спокойно их собирать.', '', 28153),
(154642, 'ruRU', '', 'Очевидно, кроме одного.', 28153),
(154641, 'ruRU', '', 'Изучалась способность порчи Г\'ууна восстанавливать отжившие ткани. Безрезультатно. Все образцы были уничтожены.', 28153),
(154640, 'ruRU', '', 'Верное наблюдение. Эксперименты над лоа проводились с целью поиска способов борьбы с порчей Древних богов.', 28153),
(154639, 'ruRU', '', 'Что это за создание?! Похоже, когда-то это был лоа.', 28153),
(154638, 'ruRU', '', 'Если у Г\'ууна такие слуги, нужно покончить с ним, пока он не отправил свою армию на поверхность.', 28153),
(154637, 'ruRU', '', 'Ошибка. Диск поврежден. Запущен поток неверных данных.', 28153),
(154636, 'ruRU', '', 'Инициирую загрузку.', 28153),
(154635, 'ruRU', '', 'Пройдите в медицинский отсек, чтобы сдать образцы нервных и мозговых тканей.', 28153),
(154634, 'ruRU', '', 'Анализ коры головного мозга показывает, что все присутствующие ранее контактировали с порчей Древних богов.', 28153),
(154633, 'ruRU', '', 'Любая предоставленная вами информация может оказаться полезной.', 28153),
(154632, 'ruRU', '', 'Анализ коры головного мозга показывает, что некоторые из присутствующих контактировали с порчей Древних богов.', 28153),
(154631, 'ruRU', '', 'И девятьсот пятьдесят миллиардов норгабайт музыкальных сборников и автопортретов.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154630, 'ruRU', '', 'Семьдесят пять норгабайт описаний всех химических соединений.', 28153),
(154629, 'ruRU', '', 'В данный момент на дисках размещено пятьдесят норгабайт биоданных обо всех известных формах жизни в космосе.', 28153),
(154628, 'ruRU', '', 'Вы в информационном хранилище. Здесь содержатся накопленные титанами знания.', 28153),
(154627, 'ruRU', 'Вы сопротивляетесь неизбежному. Мою чуму не остановить. Она уже укоренилась в вас.', '', 28153),
(154626, 'ruRU', '', 'Выпусти мы этого монстра, он бы заразил все живое на поверхности.', 28153),
(154625, 'ruRU', 'А, добро пожаловать! Посетителей и так стало слишком мало, а в архивы и подавно никто не ходит.\n\nЧем я могу помочь?', 'А, добро пожаловать! Посетителей и так стало слишком мало, а в архивы и подавно никто не ходит.\n\nЧем я могу помочь?', 28153),
(154624, 'ruRU', '', 'Тревога. Целостность камеры нарушена. Приближается опасный объект. Высокий риск заражения.', 28153),
(154623, 'ruRU', '', 'В этой лаборатории хранятся штаммы опаснейших вирусов. Для удобства образцы отсортированы в алфавитном порядке.', 28153),
(154622, 'ruRU', '', 'Здесь находится крыло вирусологии.', 28153),
(154621, 'ruRU', '', 'Применяй \"Слово силы: Щит\" постоянно, чтобы \"Искупление вины\" не прекращало действовать.', 28153),
(154620, 'ruRU', 'Применяй \"Слово силы: Щит\" постоянно, чтобы \"Искупление вины\" не прекращало действовать.', '', 28153),
(154619, 'ruRU', '', 'Примени к себе заклинание \"Слово силы: Щит\" и порази манекен, чтобы исцелить свои раны.', 28153),
(154618, 'ruRU', 'Примени к себе заклинание \"Слово силы: Щит\" и порази манекен, чтобы исцелить свои раны.', '', 28153),
(154617, 'ruRU', '', 'Нанося урон, ты восполняешь здоровье союзникам, на которых действует этот эффект.', 28153),
(154616, 'ruRU', 'Нанося урон, ты восполняешь здоровье союзникам, на которых действует этот эффект.', '', 28153),
(154615, 'ruRU', '', 'Некоторые заклинания, такие как \"Слово силы: Щит\", применяют к цели эффект \"Искупление вины\".', 28153),
(154614, 'ruRU', 'Ты знаешь что-нибудь о пропавшем флоте?', 'Ты знаешь что-нибудь о пропавшем флоте?', 28153),
(154613, 'ruRU', 'Некоторые заклинания, такие как \"Слово силы: Щит\", накладывают на цель эффект \"Искупление вины\".', '', 28153),
(154612, 'ruRU', 'Осталось уговорить вождя. Это и будет твоя задача.', '', 28153),
(154611, 'ruRU', 'Думаю, пора напомнить о старом долге и пополнить наши ряды верными бойцами.', '', 28153),
(154610, 'ruRU', 'Я знаю, $n, ты любишь Орду так же, как и я. Но, боюсь, без нашей помощи ей не пережить эту войну.', '', 28153),
(154609, 'ruRU', '', 'План ясен. Активируем консоли и покончим с заразой Г\'ууна раз и навсегда.', 28153),
(154608, 'ruRU', '', 'После активации откроется доступ в камеру Г\'ууна, где объект можно будет устранить, запустив реактор пересозидания.', 28153),
(154607, 'ruRU', '', 'Чтобы уничтожить объект, нужно реактивировать консоли, находящиеся в этом крыле.', 28153),
(154606, 'ruRU', '', 'Это слишком долго! Г\'ууна нужно остановить прямо сейчас!', 28153),
(154605, 'ruRU', '', 'Ответ отрицательный. Полученные данные неоднозначны. Разрабатываются новые тесты, запланированные на ближайшие две тысячи триста шестьдесят четыре цикла.', 28153),
(154604, 'ruRU', 'Ого! Вот это мощь!', '', 28153),
(154603, 'ruRU', '', 'И как, много вы поняли?', 28153),
(154602, 'ruRU', 'Теперь нужна только искра... отойди-ка назад.', '', 28153),
(154601, 'ruRU', 'Может, взорвем замок? Посыпь на него порохом.', '', 28153),
(154600, 'ruRU', '', 'Сбор данных необходим для противостояния Древним богам. Понимание биологии Г\'ууна может стать ключом к победе над ними.', 28153),
(154599, 'ruRU', '', 'Вы не убили эту погань сразу?! Почему?', 28153),
(154598, 'ruRU', '', 'Объект \"Ульдир\". Создан для изучения и содержания сущности, известной как Г\'уун.', 28153),
(154597, 'ruRU', '', 'Что это за место?', 28153),
(154596, 'ruRU', '', 'Системы комплекса взломаны. Будьте осторожны.', 28153),
(154595, 'ruRU', '', 'Двери закрылись! Вырубите эту машину, пока от нас не остались одни угли!', 28153),
(154594, 'ruRU', '', 'Тревога. Зараженные объекты. Активирую испепелители.', 28153),
(154593, 'ruRU', '', 'Похоже, это она сдерживает порчу и не дает ей захватить весь комплекс.', 28153),
(154592, 'ruRU', '', 'Я – матрона репликации, инкубации и архивации. Сокращенно: МАТРИАРХ.', 28153),
(154591, 'ruRU', '', 'За Орду!', 28153),
(154590, 'ruRU', '', 'Чей это голос?', 28153),
(154589, 'ruRU', '', 'За Орду!', 28153),
(154588, 'ruRU', 'Лок\'тар огар! За Орду!', '', 28153),
(154587, 'ruRU', '', 'Опасный объект устранен. Открываю камеру обеззараживания.', 28153),
(154586, 'ruRU', '', 'Я принимаю вашу клятву, воевода. Оргриммар с радостью примет вас и ваших солдат!', 28153),
(154585, 'ruRU', '', 'Дренор разрушен, но Азерот станет нашим новым домом. Отныне ваши враги – это наши враги!', 28153),
(154584, 'ruRU', 'Посыпать порохом', 'Посыпать порохом', 28153),
(154583, 'ruRU', '', 'Ваши посланники проявили смелость и благородство. Если таковы все подданные Орды, мы охотно встанем под ваши знамена.', 28153),
(154582, 'ruRU', '', 'Талок пережил удар \"КМЖС\"?! Тогда придется добить его, прежде чем мы займемся Г\'ууном!', 28153),
(154581, 'ruRU', 'Бвонсамди...', 'Так далеко от дома...', 28153),
(154580, 'ruRU', 'Я знаю, что ты расстроена, солнышко, но тут настоящие чудовища. Нам надо уходить.', 'Я знаю, что ты расстроена, солнышко, но тут настоящие чудовища. Нам надо уходить.', 28153),
(154578, 'ruRU', '', 'Мы живем честью! И верность для маг\'харов – это не пустое слово.', 28153),
(154577, 'ruRU', 'Мы купим еще один торт, только пойдем.', 'Мы купим еще один торт, только пойдем.', 28153),
(154576, 'ruRU', 'Я знаю, что ты злишься, зайка, но нам нужно идти.', 'Я знаю, что ты злишься, зайка, но нам нужно идти.', 28153),
(154575, 'ruRU', 'Солнышко, нам нужно уходить.', 'Солнышко, нам нужно уходить.', 28153),
(154574, 'ruRU', '', 'Эйтригг рассказывал мне о силе ваших соплеменников. Надеюсь, честь для вас не пустой звук?', 28153),
(154572, 'ruRU', 'Посмотри на мое платье! Оно было идеальным! Этот шелк привезли из самого Кель\'Таласа! А вуаль мне от матери досталась! Как у тебя только ума на такое хватило!', 'Посмотри на мое платье! Оно было идеальным! Этот шелк привезли из самого Кель\'Таласа! А вуаль мне от матери досталась! Как у тебя только ума на такое хватило!', 28153),
(154570, 'ruRU', 'Все прошло по плану, вождь! Воевода Гейя\'ра готова предоставить солдат Орде.', '', 28153),
(154569, 'ruRU', 'Вот дался тебе этот ресторатор?! Он даже закуски не успел сервировать!', 'Вот дался тебе этот ресторатор?! Он даже закуски не успел сервировать!', 28153),
(154568, 'ruRU', 'Пустыня забрала меня.', 'Это хорошая смерть!', 28153),
(154567, 'ruRU', 'Ты заплатишь за то, что испоганило мою свадьбу, чудовище!', 'Ты заплатишь за то, что испоганило мою свадьбу, чудовище!', 28153),
(154566, 'ruRU', 'Ты хоть представляешь, на что мне пришлось пойти, чтобы все было идеально?', 'Ты хоть представляешь, на что мне пришлось пойти, чтобы все было идеально?', 28153),
(154565, 'ruRU', 'Как ты смеешь портить самый главный день в моей жизни?!', 'Как ты смеешь портить самый главный день в моей жизни?!', 28153),
(154564, 'ruRU', 'Наконец-то всё.', 'Только не это...', 28153),
(154563, 'ruRU', 'Я хлеба четыре месяца не ела!', 'Я хлеба четыре месяца не ела!', 28153),
(154562, 'ruRU', 'Пустыня поглотит всех.', 'Смерть – единственный выход.', 28153),
(154561, 'ruRU', 'Ты хоть представляешь, во сколько мне торт обошелся?!', 'Ты хоть представляешь, во сколько мне торт обошелся?!', 28153),
(154560, 'ruRU', 'Я это место за два года забронировала!', 'Я это место за два года забронировала! Два! Года!!!', 28153),
(154559, 'ruRU', 'Смерть меня еще никогда не останавливала...', '', 28153),
(154558, 'ruRU', 'Я тебя одним мизинцем раздавлю.', '', 28153),
(154557, 'ruRU', '', 'Получите новую силовую матрицу.', 28153),
(154556, 'ruRU', '', 'Силовая матрица готова.', 28153),
(154555, 'ruRU', '', 'Внимание. Доступна новая силовая матрица.', 28153),
(154554, 'ruRU', '', 'Тревога. Срочно покиньте область, чтобы избежать пересозидания.', 28153),
(154553, 'ruRU', '', 'Тревога. Запущена процедура пересозидания. Покиньте область.', 28153),
(154551, 'ruRU', 'Орда побеждена!', '', 28153),
(154550, 'ruRU', 'Скоро ты поймешь, как бессмысленно твое сопротивление!', 'Скоро ты поймешь, как бессмысленно твое сопротивление!', 28153),
(154549, 'ruRU', 'Выходи и встреть свою судьбу!', 'Выходи и встреть свою судьбу!', 28153),
(154548, 'ruRU', 'Тому, кто в глубинах таится, твоя кожа на плащ сгодится!', 'Тому, кто в глубинах таится, твоя кожа на плащ сгодится!', 28153),
(154547, 'ruRU', 'Давай, борись за свою жалкую жизнь! Бесконечный прилив все равно ее заберет!', 'Давай, борись за свою жалкую жизнь! Бесконечный прилив все равно ее заберет!', 28153),
(154546, 'ruRU', '', 'Исцели свои раны \"Исповедью\".', 28153),
(154545, 'ruRU', 'Что это за порох такой?! Возьми-ка отсюда немножко...', '', 28153),
(154544, 'ruRU', 'Исцели свои раны \"Исповедью\".', '', 28153),
(154543, 'ruRU', '', 'Применив \"Исповедь\" к себе или союзнику, ты восполнишь здоровье, а не отнимешь его.', 28153),
(154542, 'ruRU', 'Применив \"Исповедь\" к себе или союзнику, ты восполнишь здоровье, а не отнимешь его.', '', 28153),
(154541, 'ruRU', 'Убейте этих тварей!', 'Убейте этих тварей!', 28153),
(154540, 'ruRU', 'Это должен был быть настоящий праздник!', 'Это должен был быть настоящий праздник!', 28153),
(154539, 'ruRU', 'Что такое? Что происходит? Что это за чудовища?', 'Что такое? Что происходит? Что это за чудовища?', 28153),
(154538, 'ruRU', 'Это в тысячу раз хуже пьяных родственников!', 'Это в тысячу раз хуже пьяных родственников!', 28153),
(154537, 'ruRU', 'Что тут вообще происходит?', 'Что тут вообще происходит?', 28153),
(154536, 'ruRU', 'Мы даже не станцевали \"Пьяного крылобега\"!', 'Мы даже не станцевали \"Пьяного крылобега\"!', 28153),
(154535, 'ruRU', 'Это же должен был быть праздник!', 'Это же должен был быть праздник!', 28153),
(154534, 'ruRU', 'А-а-а!', 'А-а-а!', 28153),
(154533, 'ruRU', 'Как скажешь, вождь... Идем, $n.', '', 28153),
(154532, 'ruRU', '', 'Наши союзники-ночнорожденные хорошо разбираются в телепортации. Используйте их знания и проложите путь.', 28153),
(154531, 'ruRU', 'Я нашел фрагмент артефакта, с помощью которого Гаррош отправился туда. Думаю, портал все еще можно открыть... но мне понадобится помощь.', '', 28153),
(154530, 'ruRU', '', 'Интересный план. Но, по моим сведениям, портал на... другой Дренор закрыт.', 28153),
(154529, 'ruRU', 'Пойду поговорю с Оувингс. Я люблю свою работу и хочу продолжать ее исполнять. На собственных условиях.', '', 28153),
(154528, 'ruRU', 'Это значит... Ясно.', '', 28153),
(154527, 'ruRU', 'Хм... Я не верю, что капитан решил отказаться от союза с Эшвейнами. Он был довольно... твердо настроен.', '', 28153),
(154526, 'ruRU', '', 'Что скажешь, $n? Обзаведемся новыми союзниками?', 28153),
(154525, 'ruRU', '', 'Маг\'хары славятся боевой выучкой и бесстрашием. В ближайшее время мне потребуются такие солдаты.', 28153),
(154524, 'ruRU', '', 'Армия орков из другого мира? Обученные солдаты... готовое оружие против Альянса. Интересно...', 28153),
(154523, 'ruRU', 'Мы спасли этот мир от Гарроша и Легиона, и теперь тамошние орки доверяют нам. Они в долгу перед Ордой, и я предлагаю напомнить об этом.', '', 28153),
(154522, 'ruRU', 'Вождь, когда Орда преследовала Гарроша Адского Крика, мы попали на Дренор. Хоть и не совсем наш Дренор.', '', 28153),
(154521, 'ruRU', 'Капитан решил ответить Эшвейнам отказом. Вот бумаги.', 'Капитан решил ответить Эшвейнам отказом. Вот бумаги.', 28153),
(154520, 'ruRU', 'Крутой прикид. Тебе что-нибудь нужно?', '', 28153),
(154519, 'ruRU', 'Пей, золотце. А то совсем усохнешь... Ха!', 'Пей, золотце. А то совсем усохнешь... Ха!', 28153),
(154518, 'ruRU', 'Уничтожение', 'Уничтожение', 28153),
(154516, 'ruRU', 'Ты не $gученик:ученица;. Надеюсь, у тебя есть достойная причина прерывать мой урок.', 'Ты не $gученик:ученица;. Надеюсь, у тебя есть достойная причина прерывать мой урок.', 28153),
(154515, 'ruRU', '<Похоже, Даррел вас не замечает.>', '<Похоже, Даррел вас не замечает.>', 28153),
(154514, 'ruRU', 'Тебя учили, что мешать другим некультурно?', 'Тебя учили, что мешать другим некультурно?', 28153),
(154513, 'ruRU', 'Беглый осмотр не дал мне ни малейшего представления о том, куда делись остальные гномы. Я изучу твою информацию и сообщу, если найду что-нибудь интересное.', '', 28153),
(154512, 'ruRU', '|cFF0000FF(Задание)|r Отправиться в долину Штормов.', '|cFF0000FF(Задание)|r Отправиться в долину Штормов.', 28153),
(154511, 'ruRU', 'Внимание, внимание! Тревога! Нападение!', '', 28153),
(154510, 'ruRU', '', 'Прими этот дар, традиционные доспехи нашего народа. Носи их с гордостью в память о родине. Дранош\'эк маг\'хар!', 28153),
(154509, 'ruRU', '', 'Каждый твой подвиг на стороне Орды приносит славу всем маг\'харам.', 28153),
(154508, 'ruRU', '', 'Возвращайся в Оргриммар. Я вознагражу тебя за верность нашему народу.', 28153),
(154507, 'ruRU', '', 'У тебя за плечами бесчисленные сражения и победы на Азероте. Теперь и друзья, и враги узнали силу маг\'харов!', 28153),
(154506, 'ruRU', '', 'Куда бы ни забросила тебя судьба, помни: в твоей груди бьется сердце Дренора. Лок\'тар огар!', 28153),
(154505, 'ruRU', '', 'Каждая победа Орды станет нашей победой. Покажи Азероту, как мы умеем воевать!', 28153),
(154504, 'ruRU', '', 'Сейчас Орда просит помощи в борьбе с Альянсом. И мы отзовемся на эту просьбу.', 28153),
(154503, 'ruRU', '', 'После этого Громмаш остался вождем всех орков. Больше нет разных племен. Только маг\'хары.', 28153),
(154502, 'ruRU', '', 'Некогда герои Азерота прибыли на Дренор и сражались с нами против Пылающего Легиона.', 28153),
(154501, 'ruRU', '', 'Дорогой Рокхан, племя Темного Копья заслужило поддержку зандаларов. Я помогу тебе, чем смогу.', 28153),
(154500, 'ruRU', 'Мне нужна помощь сильного союзника. Старый враг ускользнул от Бвонсамди и угрожает моему племени.', '', 28153),
(154499, 'ruRU', 'Я готов. Начинай ритуал.', 'Я готова. Начинай ритуал.', 28153),
(154498, 'ruRU', '', 'Кто-нибудь должен знать хоть что-то. Флоты просто так не пропадают!', 28153),
(154497, 'ruRU', 'Взамен мы... откроем порт для кораблей Орды?', '', 28153),
(154496, 'ruRU', 'Мы не подчинимся Эшвейнам..', '', 28153),
(154495, 'ruRU', 'Я могу тебе верить, |3-6($r)? Дай-ка сюда.', '', 28153),
(154494, 'ruRU', 'Приказ капитана, сэр. Он решил не присоединяться к Эшвейнам!', 'Приказ капитана, сэр. Он решил не присоединяться к Эшвейнам!', 28153),
(154493, 'ruRU', 'Откуда ты вообще? Уж точно не из этих мест.', '', 28153),
(154492, 'ruRU', '', 'Что? Дай-ка посмотреть.', 28153),
(154491, 'ruRU', 'У меня новости от капитана, боцман.', 'У меня новости от капитана, боцман.', 28153),
(154490, 'ruRU', '', 'Ведь нужно не только вернуть флот, но и объединить Кул-Тирас. Ну или... \"искоренить заразу\", как говорит Сайрус.', 28153),
(154489, 'ruRU', '', 'Ты кто? Чего тебе надо?', 28153),
(154488, 'ruRU', '', 'Еще они благословляют все кул-тирасские корабли. Именно это прежде всего отличает наши суда от других.', 28153),
(154487, 'ruRU', '', 'Впервые вижу столько азерита сразу. Это меня и радует, и беспокоит.', 28153),
(154486, 'ruRU', '', 'Элементаль из чистого азерита? Убей его, но оставь целым. И собери как можно больше смолы!', 28153),
(154485, 'ruRU', '', 'Сегодня воины наедятся вволю. Наверное.', 28153),
(154484, 'ruRU', '', 'Орки – хорошие солдаты, но один орк жрет как десять гоблинов. Пока разбираешься с калдорай, забей несколько зверей помясистее и пополни запасы провизии.', 28153),
(154483, 'ruRU', '', 'Всегда срезай розы, пока у них не выросли шипы.', 28153),
(154482, 'ruRU', '', 'Опять калдорай путаются под ногами. Как невовремя! Избавься от их командира, пока она не собрала подкрепление.', 28153),
(154481, 'ruRU', '', 'Я знала, что никто не справится лучше тебя.', 28153),
(154480, 'ruRU', '', 'Саурфанг поднялся на хребет между Темными берегами и Оскверненным лесом. Встреться с ним в долине Пронзающего Копья и проводи, куда нужно.', 28153),
(154479, 'ruRU', 'Мы победили! Зем\'лан на некоторое время мертв, и сокровища наши!', '', 28153),
(154478, 'ruRU', '', 'Я всегда верила в тебя.', 28153),
(154477, 'ruRU', '', 'Калдорай получили подкрепление. Теперь сражаться с ними будет сложнее, но нам нужна победа.', 28153),
(154476, 'ruRU', '', 'Ты подаешь хороший пример остальным. У тебя есть и выучка, и характер.', 28153),
(154475, 'ruRU', '', 'Альянс прочесывает Темные берега, чтобы найти и разрушить наши базы. Защити их!', 28153),
(154474, 'ruRU', '', 'На войне либо убиваешь ты, либо убивают тебя. Третьего не дано.', 28153),
(154473, 'ruRU', '', 'Эти дикие эльфы не знают пощады. И ты их тоже не щади.', 28153),
(154472, 'ruRU', '', 'Мы нанесли мощный удар по их резерву. Замечательно.', 28153),
(154471, 'ruRU', '', 'Калдорай особенно сильны ночью. Нужно разделаться с ними до заката. Приступай!', 28153),
(154470, 'ruRU', '', 'Ты оправдываешь мое доверие. Скоро калдорай падут перед нами.', 28153),
(154469, 'ruRU', '', 'Армия Малфуриона наступает нам на пятки. Пока у нас еще преимущество, нужно пробиваться дальше.', 28153),
(154468, 'ruRU', '', 'Бедняжка. У нее не было никаких шансов.', 28153),
(154467, 'ruRU', '', 'Эта ночная эльфийка действует мне на нервы. Убей ее.', 28153),
(154466, 'ruRU', '', 'Проспать тысячи лет только затем, чтобы вот так бесславно проснуться. Мне их даже жаль!', 28153),
(154465, 'ruRU', '', 'Древни проснулись и хотят повоевать? Передай им от меня \"доброе утро\".', 28153),
(154464, 'ruRU', 'Могло быть и хуже... Не допусти, чтобы его смола попала в руки Орды.', '', 28153),
(154463, 'ruRU', '', 'Элементаль из чистого азерита! Не знаю, опасен ли он, но на всякий случай будь осторожнее!', 28153),
(154462, 'ruRU', 'Ночные эльфы будут драться за каждый клочок земли.', 'Ночные эльфы будут драться за каждый клочок земли.', 28153),
(154461, 'ruRU', '', 'Умеешь обращаться с азеритовыми бомбами? Хочешь увидеть захватывающее зрелище? Приготовься. Тебя ждет сюрприз.', 28153),
(154460, 'ruRU', 'Прекрасный образец! Только представь, сколько из него получится алхимических реагентов.', '', 28153),
(154459, 'ruRU', 'Новичкам жутковато с непривычки. Но такие приключения закаляют характер!', '', 28153),
(154458, 'ruRU', '', 'Калдорай будут сопротивляться... если только мы не сломим их дух.\n\nНужно нанести удар, который покажет им, как высоки ставки. Они должны потерять что-то... кого-то... кому они полностью доверяют, на кого уповают. Символ надежды.\n\n<Глаза Темной Госпожи сужаются.>\n\nМалфурион Ярость Бури должен умереть.', 28153),
(154457, 'ruRU', 'Рыбаки говорят, что видели в воде что-то большое и странное. Было бы неплохо добыть образец для исследований.', '', 28153),
(154456, 'ruRU', '', 'Наши враги вспомнили об осадных машинах? Как оригинально. Покажи им, на что способна Орда.', 28153),
(154455, 'ruRU', 'Нам отчаянно не хватает железа. Даже учебными снарядами нельзя разбрасываться. Правда, солдаты научились делать их многоразовыми...', '', 28153),
(154454, 'ruRU', '', 'Эти руины богаты природными ресурсами... и они принадлежат нам! Не дай калдорай добраться до них.', 28153),
(154453, 'ruRU', '', 'Пора тебе прокатиться на ветрокрыле. Возьми взрывчатку и разнеси стену из огоньков. Это будет наш пламенный привет Малфуриону.', 28153),
(154452, 'ruRU', '', 'Отлично бьешь в цель! Правда, мне всегда жаль тех, кто бегает за ядрами.', 28153),
(154451, 'ruRU', 'Шаманка Торговой компании научилась управлять азеритовыми элементалями! Нечего ей такой силой ворочать, избавьтесь от нее.', '', 28153),
(154450, 'ruRU', '', 'На тренировочных площадках начались стрельбы. Покажи-ка новобранцам, как правильно обращаться с пушкой.', 28153),
(154449, 'ruRU', '', 'Мастерская работа. Это оружие необходимо нам для победы.', 28153),
(154448, 'ruRU', '', 'Так или иначе, без помощи жрецов нам сейчас точно не обойтись.', 28153),
(154447, 'ruRU', 'Ну даешь! Многие потеряли кучу денег на твоем поединке. Включая меня.', '', 28153),
(154446, 'ruRU', '', 'Никто не знает, почему корабли до сих пор не вернулись в гавань.', 28153),
(154445, 'ruRU', '', 'Говорят, жрецы утрачивают силу, но возможно, они пытаются добиться власти – как Эшвейны, например.', 28153),
(154444, 'ruRU', '', 'Этот груз – собственность Орды! Он не должен попасть в руки Альянса!', 28153),
(154443, 'ruRU', 'Время от времени братство Волнорезов проводит турнир поединщиков, и участников никто особо не проверяет.', '', 28153),
(154442, 'ruRU', '', 'Несмотря на подготовку, следопыты не смогли рассчитать свои силы. Велю Натаносу провести разъяснительную работу...', 28153),
(154441, 'ruRU', '', 'На каждом большом корабле есть жрец моря, который оберегает от бурь, успокаивает волны и призывает ветра.', 28153),
(154440, 'ruRU', '', 'Темным следопытам нужна помощь. Если встретишь их, не проходи мимо!', 28153),
(154439, 'ruRU', '', 'Пока этого достаточно. Гоблины соберут остальное, а тебя ждет новое задание.', 28153),
(154438, 'ruRU', 'Я многое понимаю, но кормить огра кровью живой планеты и надеяться, что он поумнеет?! Ну и чушь! Наверно... Хм, прибей их, на всякий случай.', '', 28153),
(154437, 'ruRU', 'Потрясающе! Это наверняка все заметят!', '', 28153),
(154436, 'ruRU', '', 'Бочонки с азеритовым порохом выбросило за борт! Собери их, пока они не утонули!', 28153),
(154435, 'ruRU', 'У меня кончились все снимки для рекламы. Если у тебя будет свободное время, сделаешь пару-тройку кадров?', '', 28153),
(154434, 'ruRU', '', 'Лагерь в безопасности, но нужно сохранять бдительность.', 28153),
(154433, 'ruRU', 'Здесь главный оружейник Торговой компании! Мы этого поганца давно выслеживаем. Иди, прибей его.', '', 28153),
(154432, 'ruRU', '', 'Жаль, что в этот раз не получится увидеть флот. Думаю, он бы даже тебя поразил!', 28153),
(154431, 'ruRU', 'Боралус! Город уличных банд и грызущихся аристократов. В Гномрегане мы как-то обходились без этого.', '', 28153),
(154430, 'ruRU', 'Я хочу показать в своей рекламе еще пару местных достопримечательностей. Начнем, пожалуй, с города.', '', 28153),
(154429, 'ruRU', '', 'На крепость напали диверсанты Альянса! Скорее вышвырни их вон!', 28153),
(154428, 'ruRU', '', 'Итак, самое время использовать пропуск на паром!', 28153),
(154427, 'ruRU', 'Моего лучшего оружейника переманила Торговая компания. Я его очень понимаю, золота было действительно много. Жаль, что тебе придется его убить, правда?', '', 28153),
(154426, 'ruRU', 'Вот и чудно! Знаешь, чем хороши фотографии? На них лошади не пахнут.', '', 28153),
(154425, 'ruRU', 'Лорд Норвингтон хочет, чтобы его шикарное поместье красовалось в новой рекламе \"Кипящих Ключей\". Я, конечно, только за!', '', 28153),
(154424, 'ruRU', 'Торговая компания пытается сделать своих огров умнее, пичкая их азеритом. Вряд ли получится, но... ты разберись с этим. Так, на всякий.', '', 28153),
(154423, 'ruRU', '', 'Вода из лунного колодца пригодится тебя в бою. Не забывай поступать так же со всеми колодцами, освященными калдорай.', 28153),
(154422, 'ruRU', '', 'Для восстановления сил калдорай пьют воду из лунных колодцев. Набери как можно больше этой воды, а затем оскверни вражеские запасы.', 28153),
(154421, 'ruRU', 'Как ты вовремя! Еще немного, и моя репутация владельца курорта точно пострадала бы.', '', 28153),
(154420, 'ruRU', 'Осторожнее, Телия. Не доверяю я этим типам в капюшонах.', '', 28153),
(154419, 'ruRU', 'Поговаривают, что в Торговой компании научились приручать элементалей из чистого азерита. Нам бы разобраться с этим. Вернее, вам.', '', 28153),
(154418, 'ruRU', '', 'Я прикажу мастерам наложения чар добавить в эти подвески азерит. Теперь они послужат Орде!', 28153),
(154417, 'ruRU', '', 'Калдорай черпают силу из подвесок с лунным камнем. Делай что хочешь, но добудь мне эти побрякушки.', 28153),
(154416, 'ruRU', '', 'Очень хорошо. Азерит всегда пригодится Орде.', 28153),
(154415, 'ruRU', '', 'В руинах на Темных берегах произошел выброс азерита. Собери его весь, чтобы Альянсу не досталось ни крошки!', 28153),
(154414, 'ruRU', '', 'Хвалю. Надеюсь, Малфурион поймет смысл этого послания.', 28153),
(154413, 'ruRU', '', 'Огоньки – не более, чем обычные вредные насекомые. Дави их одного за другим. Пусть небо над лесом станет черным.', 28153),
(154412, 'ruRU', 'Это катастрофа! Ключи спятили и нападают на гостей!', '', 28153),
(154411, 'ruRU', '', 'Глупцы! Г\'ууна не победить, можете не пытаться!', 28153),
(154410, 'ruRU', '', 'Теперь наши повара приготовят настоящий пир! Спасибо тебе!', 28153),
(154409, 'ruRU', '', 'У наших друидов аппетит... поистине медвежий! Прошу, помоги нам пополнить запасы.', 28153),
(154408, 'ruRU', 'Пора выполнять договор. Огонь!', '', 28153),
(154407, 'ruRU', 'Ха-ха! Неплохо.', 'Ха-ха! Неплохо.', 28153),
(154406, 'ruRU', 'Как грубо.', 'Как грубо.', 28153),
(154405, 'ruRU', 'Зачем ты это делаешь?', 'Зачем ты это делаешь?', 28153),
(154404, 'ruRU', 'Что, во имя всех лоа, ты творишь?', 'Что, во имя всех лоа, ты творишь?', 28153),
(154403, 'ruRU', 'Прекрати!', 'Прекрати!', 28153),
(154402, 'ruRU', 'С дороги! Артиллерия идет!', '', 28153),
(154401, 'ruRU', 'Вот и последний. Да ты теперь богатеище, с целой-то монеткой!', '', 28153),
(154400, 'ruRU', 'У пиратов есть обычай – делить монетки на восемь частей. Сильно повезет тому, кто найдет все кусочки! Около Вольной Гавани их должно быть много.', '', 28153),
(154399, 'ruRU', 'Сама напросилась, прям скажем. Ну, кто медуз давно не ел? Ха-ха.', '', 28153),
(154398, 'ruRU', 'В заливе Вольной Гавани поселилась огромная медуза. Сколько в нее гарпунами ни тыкай – возвращается за добавкой!', '', 28153),
(154397, 'ruRU', 'Вы одолели Вандегрима и упокоили его душу! Ох, сколько сокровищ освободилось от его проклятия...', '', 28153),
(154396, 'ruRU', 'Капитан Вандегрим наводил страх на все побережье. А еще говорят, он был настолько жаден, что грабить не бросил, даже загремев в могилу.', '', 28153),
(154395, 'ruRU', 'Иггкш ивак аг\'рр ни ки!', '', 28153),
(154394, 'ruRU', 'А\'шел ивак кам ирр вот\'гл!', '', 28153),
(154393, 'ruRU', 'Вот и последний кусочек. Теперь у тебя целая монетка! Ух!', '', 28153),
(154392, 'ruRU', 'За аг\'рр вга тизз зук!', '', 28153),
(154391, 'ruRU', 'У пиратов есть обычай – резать монетки на восемь частей. Сильно повезет тому, кто найдет все кусочки! Около Вольной Гавани их должно быть много.', '', 28153),
(154390, 'ruRU', 'Сама напросилась, что уж. Кому жареной медузки?', '', 28153),
(154389, 'ruRU', 'В заливе Вольной Гавани поселилась огромная медуза. Сколько в нее гарпунами ни тыкай – возвращается за добавкой.', '', 28153),
(154388, 'ruRU', 'Га аг\'рр ез Ан\'зиг вга кит зук!', '', 28153),
(154387, 'ruRU', 'Вы одолели Вандегрима и упокоили его душу! Ох, сколько сокровищ освободилось от его проклятия...', '', 28153),
(154386, 'ruRU', 'Капитан Вандегрим наводил страх на все побережье. А жадность его была такова, что грабить он не бросил даже после смерти.', '', 28153),
(154385, 'ruRU', 'Это... не то будущее, что было мне обещано...', '', 28153),
(154384, 'ruRU', 'В моих жилах кровь Г\'ууна! Трепещите перед моей мощью!', '', 28153),
(154383, 'ruRU', 'Я такое видел...', 'Какой приятный сюрприз!', 28153),
(154382, 'ruRU', 'Я слишком силен для вас!', '', 28153),
(154381, 'ruRU', 'Спасибо. Мои силы были на исходе.', 'Спасибо. Я побегу!', 28153),
(154380, 'ruRU', 'Г\'уун принесет вам погибель!', '', 28153),
(154379, 'ruRU', 'Надежда умрет вместе с вами!', '', 28153),
(154378, 'ruRU', 'Придите, избранные! Мы утопим этот мир в крови!', '', 28153),
(154377, 'ruRU', 'Восстаньте из моей крови. Сокрушите слабых!', '', 28153),
(154376, 'ruRU', 'Ко мне, слуги! Пожрите этих глупцов!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154375, 'ruRU', 'Верните мне свою кровь!', '', 28153),
(154374, 'ruRU', 'Г\'уун! Прими это кровавое подношение!', '', 28153),
(154373, 'ruRU', 'У тебя не было будущего.', '', 28153),
(154372, 'ruRU', 'Я знал, что вы слабы.', '', 28153),
(154371, 'ruRU', 'Все, как я и предвидел!', '', 28153),
(154370, 'ruRU', 'Глупцы! Я уже видел вашу смерть.', '', 28153),
(154369, 'ruRU', 'Моя мать умерла, когда я был еще совсем мальчишкой, и меня растил отец. Он был моряком и всегда оставлял мне цветок морского стебля, когда уходил в плавание.', 'Моя мать умерла, когда я была еще совсем девчонкой, и меня растил отец. Он был моряком и всегда оставлял мне цветок морского стебля, когда уходил в плавание.', 28153),
(154368, 'ruRU', '', 'Тревога. Проявление темной проекции.', 28153),
(154367, 'ruRU', '', 'Тревога. Сбой системы сдерживания Бездны.', 28153),
(154366, 'ruRU', '', 'Это был благородный поступок.', 28153),
(154365, 'ruRU', '', 'Тревога. Опасный уровень энергии Бездны.', 28153),
(154363, 'ruRU', '', 'Внимание. Запущена репликация новых нерубов.', 28153),
(154362, 'ruRU', 'Баланс восстановлен. Ану\'дорини тала.', '', 28153),
(154361, 'ruRU', 'Благословенный свет Элуны найдет даже тех, кто прячется в тени. Ступай и устрани эту угрозу.', '', 28153),
(154360, 'ruRU', '', 'Внимание. Запущена репликация новых силитидов.', 28153),
(154359, 'ruRU', 'Пф! Будь он проклят! Морской стебель для меня значит только то, что хорошие моряки не вернутся домой, а груз лежит на дне морском.', 'Пф! Проклятые штуковины! Морской стебель для меня значит только то, что хорошие моряки не вернутся домой, а груз лежит на дне морском.', 28153),
(154358, 'ruRU', '', 'Митраксу не место в этом мире.', 28153),
(154357, 'ruRU', '', 'Твое сердце горит ярче звезд. Да хранит тебя Элуна.', 28153),
(154356, 'ruRU', '', 'Мои лучники держатся из последних сил. Помоги всем, кого встретишь!', 28153),
(154355, 'ruRU', '', 'Эта война должна прекратиться.', 28153),
(154354, 'ruRU', '', 'Я буду приглядывать за тобой.', 28153),
(154353, 'ruRU', '', 'Загрузка завершена. Отключение диска.', 28153),
(154352, 'ruRU', '', 'И задание выполнено, и орудие уцелело. Это выше всяких похвал!', 28153),
(154351, 'ruRU', '', 'Порядок должен быть восстановлен.', 28153),
(154350, 'ruRU', '', 'У каждого есть свое место. Мое – здесь.', 28153),
(154349, 'ruRU', '', 'Я слаба, но я снова среди вас.', 28153),
(154348, 'ruRU', '', 'Тебе уже приходилось управлять осадным орудием? Держись крепче.', 28153),
(154347, 'ruRU', '', 'Доступ получен. Загрузка поврежденных данных.', 28153),
(154346, 'ruRU', 'Я отправлю туда как можно больше солдат. Надеюсь, они смогут отразить атаку. Мы не можем позволить себе войну на два фронта.', '', 28153),
(154345, 'ruRU', 'Я чувствую, на севере что-то происходит. Неужели Орда идет в атаку со стороны гор? Скорее разберись, в чем дело!', '', 28153),
(154344, 'ruRU', '', 'У тебя потрепанный вид. Что-то пошло не так?', 28153),
(154343, 'ruRU', '', 'Даже под водой азеритовый порох довольно опасен. Взорви бочонки с ним, пока они не всплыли. И пожалуйста, осторожнее! Хотелось бы вновь увидеть тебя в добром здравии.', 28153),
(154342, 'ruRU', '', 'Матрица данных перегружена. Получен доступ к нескольким дискам.', 28153),
(154341, 'ruRU', 'Морской стебель? В моей команде есть ребята, которые всегда оставляют своим родным цветок, когда уходят в море. Не могу их винить. Они не хотят, чтобы их семья терзалась неведением, если что случится.', 'Морской стебель? В моей команде есть ребята, которые всегда оставляют своим родным цветок, когда уходят в море. Не могу их винить. Они не хотят, чтобы их семья терзалась неведением, если что случится.', 28153),
(154340, 'ruRU', '', 'Никогда в тебе не сомневалась.', 28153),
(154339, 'ruRU', '', 'Орда прислала в наши леса огромную армию. Ее нельзя недооценивать. В этом отряде – исключительно мощные бойцы. Будь осторожнее.', 28153),
(154338, 'ruRU', '', 'Доступ получен. Загрузка данных Йогг-Сарона.', 28153),
(154337, 'ruRU', '', 'Доступ получен. Загрузка данных К\'Туна.', 28153),
(154335, 'ruRU', '', 'Среди нас диверсанты Орды! Найди их! Пусть они заплатят за наши страдания!', 28153),
(154334, 'ruRU', '', 'Должна признать, ты метко стреляешь. Моим часовым стоит у тебя поучиться.', 28153),
(154333, 'ruRU', '', 'Клин клином вышибают. Уничтожь ордынские разрушители и отбрось врагов в Степи, где им самое место!', 28153),
(154332, 'ruRU', '', 'Элуна благодарит тебя. И я тоже.', 28153),
(154331, 'ruRU', '', 'Орда пытается разорить наши лунные колодцы! Не дай мародерам осквернить священные воды!', 28153),
(154330, 'ruRU', '', 'Пусть эти мародеры буянят у себя в степях. Покажем им, как соваться в наш лес!', 28153),
(154329, 'ruRU', '', 'Войско Орды разбило лагерь у границы Ясеневого леса. Собери охраняющих лес друидов!', 28153),
(154328, 'ruRU', '', 'Ты сражаешься яростно и умело!', 28153),
(154327, 'ruRU', '', 'Орда крадет наши ресурсы! Останови это, пока они не разорили священный лес.', 28153),
(154326, 'ruRU', '', 'Тысячи лет смерти не притупили их навыков. Хорошо, что вам удалось их упокоить.', 28153),
(154325, 'ruRU', '', 'Это... лучшие стражи короля Дазара! С ними будет нелегко.', 28153),
(154324, 'ruRU', 'Так-то! Хватит нежить нежить! Чудесная работа.', '', 28153),
(154323, 'ruRU', 'Ух, эти мертвяки явно посерьезнее остальных!', '', 28153),
(154322, 'ruRU', 'Расскажи мне о морском стебле.', 'Расскажи мне о морском стебле.', 28153),
(154321, 'ruRU', '', 'Прекрасные образцы. Твой подвиг не останется без награды.', 28153),
(154320, 'ruRU', '', 'У Орды есть азеритовое оружие. Надо бы конфисковать несколько образцов, как думаешь?', 28153),
(154319, 'ruRU', '...Чертоги Камня не в счет.', '', 28153),
(154318, 'ruRU', 'Пф-ф. Вот дворфийские механизмы работают как часики!', '', 28153),
(154317, 'ruRU', '', 'Блестящая работа! Я прикажу алхимикам спрятать этот азерит понадежнее.', 28153),
(154316, 'ruRU', 'Типичная тролльская поделка! У голема замкнуло контакты. Надо его подчинить... и починить!', '', 28153),
(154315, 'ruRU', '', 'Джакра\'зет не должен найти Джулвабу раньше нас.', 28153),
(154314, 'ruRU', '', 'На стража гробницы действует темное вуду Зула. Успокойте его – и мы его починим.', 28153),
(154313, 'ruRU', '', 'Зул... То, что ты сделал с нашей святыней – настоящее кощунство.', 28153),
(154312, 'ruRU', '', 'Прощай, Халу. Покойся с миром.', 28153),
(154311, 'ruRU', '', 'Мастер Халу... Он обучал моего отца, и отца моего отца. Но его время истекло. Упокойте его мятежный дух.', 28153),
(154310, 'ruRU', 'Ха! Вы показали ему, кто настоящий мастер!', '', 28153),
(154309, 'ruRU', 'Здесь блуждает дух боевого наставника зандаларских принцев. Пора его упокоить!', '', 28153),
(154308, 'ruRU', '', 'Теперь мои лучники справятся сами. Благодаря тебе перевес сил оказался на нашей стороне. Спасибо.', 28153),
(154307, 'ruRU', '', 'Враг нападает с севера. Пора оттеснить его и перейти от обороны к наступлению.', 28153),
(154306, 'ruRU', 'Пропустить их!', '', 28153),
(154305, 'ruRU', '', 'Еще немного! Голос Акунды уже звучит у меня в голове.', 28153),
(154304, 'ruRU', '', 'Я постараюсь восстановить разум Акунды, но тебе придется столкнуться с его ожившими воспоминаниями.', 28153),
(154303, 'ruRU', 'Ивак онгг ан\'ков и лал халахс нук.', '', 28153),
(154302, 'ruRU', 'Ивак мх\'наус вгах заикс зиктаг.', '', 28153),
(154301, 'ruRU', 'Ты ответишь... перед Моджамбо...', '', 28153),
(154300, 'ruRU', '', 'Где... где я? Как я тут оказалась?', 28153),
(154299, 'ruRU', 'Ооу тизз лал ак\'ук куаз. Зук шкул ма ск\'тек...', '', 28153),
(154298, 'ruRU', '', 'Они мало говорят о себе, но в Кул-Тирасе их ценят. Жрецы помогают рыбакам с уловом, а пахарям – с дождями.', 28153),
(154297, 'ruRU', '', 'Большинство култирасцев обращается за помощью к морю, как жители других земель – к Свету. Но у наших жрецов особая связь с водой.', 28153),
(154296, 'ruRU', '', 'Обычно я летаю на Буревестнице, но жрецы моря настаивают, чтобы гости приплывали на лодках.', 28153),
(154295, 'ruRU', '', 'Не волнуйся, Сайрус. Я могу за себя постоять, а в такой компании точно не пропаду!', 28153),
(154294, 'ruRU', 'Ооу иикзз ез тизз фкуати зук!', '', 28153),
(154293, 'ruRU', 'Ооу гул\'каф лал лвхук!', '', 28153),
(154292, 'ruRU', 'Кам ооу иилт ез и аутгсшу амун он\'ма!', '', 28153),
(154291, 'ruRU', 'Лог\'лот в\'ок. Онг!', '', 28153),
(154290, 'ruRU', '', 'На Темных берегах появился азерит. Мы должны добраться до него раньше, чем это сделает Орда!', 28153),
(154289, 'ruRU', 'В\'ок ун\'агт ез кам. Шандай!', '', 28153),
(154288, 'ruRU', 'Аутгсш шн онгг шг\'уллвак!', '', 28153),
(154287, 'ruRU', 'Зук аг\'ксиг бормаз аг\'тизак!', '', 28153),
(154286, 'ruRU', 'Спасибо тебе!', 'Спасибо тебе!', 28153),
(154285, 'ruRU', 'За квалар аг\'ксиг за ал\'та!', '', 28153),
(154284, 'ruRU', 'Мне для такого слишком мало платят!', 'Мне для такого слишком мало платят!', 28153),
(154283, 'ruRU', 'А-А-А!', 'А-А-А!', 28153),
(154282, 'ruRU', 'Благодарю за спасение!', 'Благодарю за спасение!', 28153),
(154281, 'ruRU', 'Я уж думал, что пойду на сосиски!', 'Я уж думала, что пойду на сосиски!', 28153),
(154280, 'ruRU', 'Ооу вуаху. Хн аг\'ксиг шфк зук!', '', 28153),
(154279, 'ruRU', 'Спасибо, дружище.', 'Спасибо, дружище.', 28153),
(154278, 'ruRU', 'И онгг за ивак квсакф.', '', 28153),
(154277, 'ruRU', 'Вуа ооу каакст зз ивак ийок. Аг\'злг фхшш и онма.', '', 28153),
(154276, 'ruRU', 'За аутгсшу вга уулг\'ма иваг зейкс.', '', 28153),
(154275, 'ruRU', 'Кам ооу ухниш кит зук. Онг за фшш ас\'рр.', '', 28153),
(154274, 'ruRU', 'Ивак зук иваг шн\'ма. Бо\'ал за квор.', '', 28153),
(154273, 'ruRU', 'Ооу кам пуул зиктахг ивак ворз. Кам ма шн\'ма.', '', 28153),
(154272, 'ruRU', 'Ооу шат\'яр лвхук шн\'ма ирр шанди агт фсш.', '', 28153),
(154271, 'ruRU', 'Когда огоньки спокойны, в лесу дышать легче. Спасибо!', '', 28153),
(154270, 'ruRU', 'Огоньки утратили прежнюю жизненную силу. Согрей их своим прикосновением. Подари им покой.', '', 28153),
(154269, 'ruRU', 'Меня не зря зовут верховным ведуном.', '', 28153),
(154268, 'ruRU', 'Возьми мой жезл и преврати этих жрецов во что-нибудь поинтереснее.', '', 28153),
(154267, 'ruRU', 'Думаешь, это было жестоко? Ты не знаешь, что иногда вытворяют лоа...', '', 28153),
(154266, 'ruRU', 'Если мы не остановим распространение порчи, то кто это сделает?', 'Если мы не остановим распространение порчи, то кто это сделает?', 28153),
(154265, 'ruRU', 'Друиды Гонка очень скучные. Проверни пару шуточек у их алтарей, посмеши ребят. Правда, они попробуют тебя убить....', '', 28153),
(154264, 'ruRU', 'Если рана будет расти... Азерот обречена.', 'Если рана будет расти... Азерот обречена.', 28153),
(154263, 'ruRU', 'Природа рыдает от боли... как положить конец этому безумию?', 'Природа рыдает от боли... как положить конец этому безумию?', 28153),
(154262, 'ruRU', 'Все наши попытки ни к чему не приводят... как мы можем исцелить планету?', 'Все наши попытки ни к чему не приводят... как мы можем исцелить планету?', 28153),
(154261, 'ruRU', '', 'Вот это был полет! Вы оба молодцы.', 28153),
(154260, 'ruRU', '', 'Волшебные дракончики не привычны к сбруе, так что полет будет не из легких. Оседлай дракончика и соверши боевой вылет.', 28153),
(154259, 'ruRU', 'Я питаюсь вашим страхом!', '', 28153),
(154258, 'ruRU', 'Воины Стальгорна! Атакуйте базу врага!', '', 28153),
(154257, 'ruRU', 'Сокрушите Ар\'горок во имя Аратора! За Стромгард! ЗА АЛЬЯНС!', '', 28153),
(154256, 'ruRU', '', 'Ты сражаешься, как легендарные зандалары.', 28153),
(154255, 'ruRU', '', 'Спасибо тебе. Ты очень ценный союзник.', 28153),
(154252, 'ruRU', '', 'Теперь и зандалары, и Орда в безопасности.', 28153),
(154251, 'ruRU', '', 'Больше этот враг не помешает нам.', 28153),
(154246, 'ruRU', '', 'Убежище уже близко. Там можно отсидеться, хотя бы на время.', 28153),
(154245, 'ruRU', '', 'Надеюсь, больше мы не услышим об этой угрозе.', 28153),
(154244, 'ruRU', '', 'Лоа предсказали твою победу. Я рада, что они не ошиблись.', 28153),
(154243, 'ruRU', '', 'Твои друзья-ордынцы будут рады узнать об этом подвиге.', 28153),
(154242, 'ruRU', '', 'Я знала, что этот враг тебе не ровня.', 28153),
(154240, 'ruRU', 'Я внутри вас. Я – червь в ваших хребтах.', '', 28153),
(154239, 'ruRU', '', 'Неподалеку могучий враг, и он желает твоей смерти. Убей его без жалости.', 28153),
(154238, 'ruRU', '', 'Среди воинов Орды идет молва о коварном противнике, который действует неподалеку. Развей их опасения.', 28153),
(154237, 'ruRU', '', 'Разведчики нашли опасного врага. Они считают, что его надо убить, и побыстрее. Я думаю, это хороший план!', 28153),
(154234, 'ruRU', 'Кажется, в Назмире этих дикарей бесчисленное множество. Спасибо тебе за помощь.', '', 28153),
(154232, 'ruRU', 'Ха! Да у тебя настоящий талант! Наверное, некоторые просто рождаются верхом на пингвине!', '', 28153),
(154230, 'ruRU', 'Тролли крови осаждают наши ворота. Дадим бой этим дикарям!', '', 28153),
(154228, 'ruRU', 'Сегодня работы не будет. Почти все Сорвиголовы умотали кататься на пингвинах. Иди тоже проветрись, чего киснуть-то!', '', 28153),
(154225, 'ruRU', '', 'Осторожнее, рядом с тобой могучий враг. Убей его, пока он не устроил тебе неприятности.', 28153),
(154224, 'ruRU', 'Элуна славит твою доблесть.', '', 28153),
(154223, 'ruRU', '', 'Лоа говорят, где-то поблизости опасный враг. Они говорят: сотри его с лица Азерота.', 28153),
(154222, 'ruRU', 'Войска Сильваны беспрерывно атакуют. Обыщи лес и очисти его от присутствия темных сил!', '', 28153),
(154221, 'ruRU', '', 'Разведчики обнаружили сильного врага. Убей его, пока он не натворил бед.', 28153),
(154220, 'ruRU', 'Мои войска вновь готовы вступить в бой. Благодаря тебе у них было время перегруппироваться.', '', 28153),
(154219, 'ruRU', '', 'Будь настороже, где-то рядом опасный враг. Убей его, пока он не убил тебя!', 28153),
(154218, 'ruRU', 'Угроза миновала. Древни снова погружаются в мирную дрему.', '', 28153),
(154217, 'ruRU', '', 'Где-то рядом сильный враг. Он опасен для твоих союзников. Убей его.', 28153),
(154216, 'ruRU', 'Убивай всех, кто не зандалар!', '', 28153),
(154215, 'ruRU', 'Предчувствие беды разбудило лес. Устрани Орду, чтобы вернуть деревьям покой.', '', 28153),
(154213, 'ruRU', 'Благодаря тебе мы сможем немного отдохнуть.', '', 28153),
(154212, 'ruRU', 'Орда продвигается все дальше в наши леса. Деревья стонут и гнутся от ее тяжкой поступи. Пора остановить захватчиков!', '', 28153),
(154211, 'ruRU', 'Береги себя.', 'Береги себя.', 28153),
(154210, 'ruRU', 'Пустыня пожирает слабых.', 'Пустыня пожирает слабых.', 28153),
(154209, 'ruRU', 'Не доверяй никому.', 'Поосторожней там.', 28153),
(154208, 'ruRU', 'Никто не заслуживает такой судьбы.', 'Никто не заслуживает такой судьбы.', 28153),
(154207, 'ruRU', 'Чего надо?', 'Здесь всем рады.', 28153),
(154205, 'ruRU', 'Ну, здравствуй.', 'Ну, здравствуй.', 28153),
(154204, 'ruRU', '', 'Я по-прежнему слышу тебя... господин...', 28153),
(154203, 'ruRU', 'Мой шепот растопит ваш разум.', '', 28153),
(154202, 'ruRU', 'Пей их кровь. Пусть голод ведет тебя.', '', 28153),
(154201, 'ruRU', 'Иди к союзникам. Раздели мой дар с ними.', '', 28153),
(154200, 'ruRU', 'Великолепно. А теперь пора избавиться от остальных отступников!', '', 28153),
(154199, 'ruRU', 'Гниль проникла в тебя. Не сопротивляйся ей.', '', 28153),
(154198, 'ruRU', 'Отберите одно из устройств у колдунов-отступников и зарядите его. Я награжу вас.', '', 28153),
(154197, 'ruRU', 'Наши колдуны обнаружили в храме мощные электрические потоки.', '', 28153),
(154196, 'ruRU', 'Да начнется пир тысячи утроб!', '', 28153),
(154195, 'ruRU', 'Молодцы! Осталось найти сердце Сетралисс.', '', 28153),
(154194, 'ruRU', 'Верните мне эти реликвии, и я вас награжу.', '', 28153),
(154193, 'ruRU', 'Ешьте, дети мои!', '', 28153),
(154192, 'ruRU', 'Насколько я понимаю, отступники спрятали артефакты нашего народа на рыночной площади у центра храма.', '', 28153),
(154191, 'ruRU', 'Ко мне, слуги. Обед ждет!', '', 28153),
(154190, 'ruRU', 'Чудесный образец! Ну а теперь покончите с отступниками!', '', 28153),
(154189, 'ruRU', 'Я слышал, в храме обосновался выводок редких кролусков. Принесите мне их детеныша – и вас ждет награда.', '', 28153),
(154188, 'ruRU', 'Мою чуму ничто не остановит!', '', 28153),
(154187, 'ruRU', 'От этой болезни нет спасения!', '', 28153),
(154186, 'ruRU', 'Титаны вас не спасут!', '', 28153),
(154185, 'ruRU', 'Зараза найдет вас везде!', '', 28153),
(154184, 'ruRU', 'Печати сломаны. Близится конец. Вы будете первыми, кто получит мой дар.', '', 28153),
(154183, 'ruRU', 'Народ не знает, как тебя благодарить. Никому не охота идти под нож.', '', 28153),
(154182, 'ruRU', 'Болезнь... поселилась внутри вас...', '', 28153),
(154181, 'ruRU', 'Ведьмы снова напали на Гавань мясников! Спаси работников, пока из них не сделали отбивные!', '', 28153),
(154180, 'ruRU', '', 'Друсты повержены, а древние духи обрели покой. Прекрасная работа.', 28153),
(154179, 'ruRU', '', 'Вечная битва угрожает беженцам на Заставе Арома. Успокой призраков!', 28153),
(154178, 'ruRU', 'Призови бурю, $n. Свергни узурпатора!', '', 28153),
(154177, 'ruRU', 'Моя сила хорошо послужила тебе, $n.', '', 28153),
(154176, 'ruRU', 'Дитя мое... Наконец-то ты меня слышишь. В нашем храме завелся предатель.', '', 28153),
(154175, 'ruRU', '', 'Инквизитор, нам угрожает кошмарное создание. Убей его.', 28153),
(154174, 'ruRU', '', 'Ведьмы наслали на наши земли грозное чудовище. Уничтожь его!', 28153),
(154173, 'ruRU', '', 'Теперь друстварцы получат хотя бы небольшую передышку.', 28153),
(154172, 'ruRU', '', 'Спасибо, инквизитор! Вряд ли этот враг снова сунется в Друствар.', 28153),
(154171, 'ruRU', 'Наконец-то я свободен! Спасибо тебе, $p.', '', 28153),
(154170, 'ruRU', '', 'Разведчики докладывают, что поблизости затаился опасный враг. Убей его!', 28153),
(154169, 'ruRU', '', 'Нам угрожает могущественный враг, обитающий в этой области. Убей его.', 28153),
(154168, 'ruRU', 'Как я умудрился проиграть?', '', 28153),
(154167, 'ruRU', '', 'Мой народ безмерно тебе благодарен. Сегодня мы все можем спать спокойнее.', 28153),
(154166, 'ruRU', '', 'Народ Друствара благодарит тебя за помощь.', 28153),
(154165, 'ruRU', 'Это было не слишком умно.', '', 28153),
(154164, 'ruRU', '', 'В этой местности видели опасного врага. Убей его.', 28153),
(154163, 'ruRU', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t Г\'уун использует против вас |cFFFF0404|Hspell:272506|h[взрывоопасную порчу]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t Г\'уун использует против вас |cFFFF0404|Hspell:272506|h[взрывоопасную порчу]|h|r!', 28153),
(154162, 'ruRU', 'Наконец-то покой...', '', 28153),
(154161, 'ruRU', '', 'Жителям Друствара угрожает опасный враг. Разделайся с ним!', 28153),
(154160, 'ruRU', 'Раз уж океан меня не убил, почему ты думаешь, что у тебя получится?', '', 28153),
(154159, 'ruRU', 'Я заполню собой этот мир.', '', 28153),
(154158, 'ruRU', 'Нам нужен паром в монастырь Штормов.', 'Нам нужен паром в монастырь Штормов.', 28153),
(154157, 'ruRU', 'Твое тело послужит новому хозяину.', '', 28153),
(154155, 'ruRU', 'Я столько не успел написать...', '', 28153),
(154154, 'ruRU', 'У меня еще остались силы!', '', 28153),
(154153, 'ruRU', 'Эхо твоих криков будет звучать вечно!', '', 28153),
(154152, 'ruRU', 'Проклятие плоти поглотит вас!', '', 28153),
(154151, 'ruRU', 'Эпидемия началась!', '', 28153),
(154150, 'ruRU', '', 'Это мой долг, Каджа. А долг превыше всего.', 28153),
(154149, 'ruRU', '', 'Джакра\'зет – предатель, но королю нужны доказательства.', 28153),
(154148, 'ruRU', 'Кажется... Можно отдохнуть...', 'Кажется... Можно отдохнуть...', 28153),
(154147, 'ruRU', 'Мы же вас предупреждали!', 'Мы же вас предупреждали!', 28153),
(154146, 'ruRU', '', 'Иди. Узнай все, что сможешь. Я не оставлю Ракиру.', 28153),
(154145, 'ruRU', 'Слова Акунды каждый должен услышать в одиночку. Подойди же к алтарю и вознеси молитву.', '', 28153),
(154144, 'ruRU', 'Чтобы впустить Акунду в свой разум, тебе нужно очиститься.', '', 28153),
(154143, 'ruRU', 'Я хочу вернуться в это место.', 'Я хочу вернуться в это место.', 28153),
(154142, 'ruRU', 'Уровень максимальный. Продолжаю сбор.', '', 28153),
(154141, 'ruRU', '<Альтаир тепло на вас смотрит.>', '<Альтаир тепло на вас смотрит.>', 28153),
(154140, 'ruRU', '<Альтаир пристально на вас смотрит.>', '<Альтаир пристально на вас смотрит.>', 28153),
(154139, 'ruRU', 'Идет выброс жидкости. Отключение систем.', '', 28153),
(154138, 'ruRU', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t Г\'уун начинает использовать способность |cFFFF0404|Hspell:267700|h[Взор Г\'ууна]|h|r.', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t Г\'уун начинает использовать способность |cFFFF0404|Hspell:267700|h[Взор Г\'ууна]|h|r.', 28153),
(154133, 'ruRU', 'Образец подлежит уничтожению.', '', 28153),
(154132, 'ruRU', 'Начинаю извлечение крови из носителя.', '', 28153),
(154131, 'ruRU', 'Начинаю извлечение отбойника.', '', 28153),
(154130, 'ruRU', 'Размещаю отбойник.', '', 28153),
(154129, 'ruRU', 'Топливо на и-и-исходе. Отключаюсь...', '', 28153),
(154128, 'ruRU', '', 'Дранош\'эк маг\'хар!', 28153),
(154127, 'ruRU', 'Объекты готовы к заражению.', '', 28153),
(154126, 'ruRU', '', 'Гром войны сотрясает этот мир. Но мы не дрогнем... и завоюем победу!', 28153),
(154125, 'ruRU', '', 'Мы – потомки гордого народа. Непокорные. Незапятнанные. Маг\'хары.', 28153),
(154124, 'ruRU', '', 'Для нас это не пустые слова, а смысл жизни.', 28153),
(154123, 'ruRU', '', 'Сила и честь. Кровь и гром.', 28153),
(154122, 'ruRU', 'Катализатор для гнили.', '', 28153),
(154121, 'ruRU', 'Новый объект для заражения.', '', 28153),
(154120, 'ruRU', 'Обнаружены носители. Начинаю заражение.', '', 28153),
(154119, 'ruRU', '', 'Поверь, они очень даже реальны. И опасны. В этот каньон не хотят соваться даже сетраки.', 28153),
(154118, 'ruRU', 'Начинаю сбор плазмы.', '', 28153),
(154117, 'ruRU', 'Быстрее, слизняки! Почините – получите деньги!', '', 28153),
(154116, 'ruRU', 'Какой прекрасный остров...', 'Какой прекрасный остров...', 28153),
(154115, 'ruRU', 'Это ведь был славный бой?', 'Это ведь был славный бой?', 28153),
(154114, 'ruRU', '', 'Не стоит задерживаться. В пустыне Ракира долго не протянет.', 28153),
(154113, 'ruRU', 'Это не так уж и больно...', 'Это не так уж и больно...', 28153),
(154112, 'ruRU', 'Что я сделал не так?', 'Что я сделала не так?', 28153),
(154111, 'ruRU', 'Сгинь, стервятник!', 'Сгинь, стервятник!', 28153),
(154110, 'ruRU', 'Тебе меня не одолеть!', 'Тебе меня не одолеть!', 28153),
(154109, 'ruRU', 'Ну и где теперь твоя Королева банши?', 'Ну и где теперь твоя Королева банши?', 28153),
(154108, 'ruRU', 'Я не для того спасся из океана, чтобы меня убивали какие-то наги!', 'Я не для того спаслась из океана, чтобы меня убивали какие-то наги!', 28153),
(154107, 'ruRU', '', 'Я так не думаю.', 28153),
(154106, 'ruRU', 'Делаем, как задумала Ниша. Мы застанем сетраков врасплох.', '', 28153),
(154105, 'ruRU', '', 'Надо было вложить в охрану больше денег.', 28153),
(154104, 'ruRU', '', 'Хватит меня отвлекать! Мое время стоит денег!', 28153),
(154103, 'ruRU', '', 'Если понадобится, бей рабочих! Мне нужно, чтобы \"Рифолом\" заработал немедленно!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154102, 'ruRU', 'Она тяжело ранена. Может не выжить.', '', 28153),
(154101, 'ruRU', '', 'Конечно цела. Эта – тоже из сбитых чужаков?', 28153),
(154100, 'ruRU', 'Спаси, что можешь, пока все это не оказалось уничтожено.', 'Спаси, что можешь, пока все это не оказалось уничтожено.', 28153),
(154099, 'ruRU', 'Здесь много удивительных вещей.', 'Здесь много удивительных вещей.', 28153),
(154098, 'ruRU', 'Спасибо за помощь. У нас не хватает стражников, и мы не можем охранять Старый торговый тракт, как раньше.', '', 28153),
(154097, 'ruRU', 'Спасибо...', 'Спасибо...', 28153),
(154096, 'ruRU', 'О нет... опять...', 'О нет... опять...', 28153),
(154095, 'ruRU', 'Не дайте им меня съесть...', 'Не дайте им меня съесть...', 28153),
(154094, 'ruRU', 'Мне говорили... будет просто...', 'Мне говорили... будет просто...', 28153),
(154093, 'ruRU', 'Из твоей головы выйдет трофей что надо.', 'Из твоей головы выйдет трофей что надо.', 28153),
(154092, 'ruRU', 'Наши торговцы попросили охрану для каравана. Сопроводишь их?', '', 28153),
(154091, 'ruRU', 'Чума тебя заберет!', 'Чума тебя заберет!', 28153),
(154090, 'ruRU', 'Тебя не забрало море, но я это исправлю!', 'Тебя не забрало море, но я это исправлю!', 28153),
(154089, 'ruRU', 'Здесь ты и умрешь!', 'Здесь ты и умрешь!', 28153),
(154088, 'ruRU', 'ТЫ ПОКАЗАЛ СВОЮ ИСТИННУЮ СУЩНОСТЬ, ВЛАДЫКА СМЕРТИ! ИЗЫДИ ИЗ ЭТОГО СВЯЩЕННОГО МЕСТА!', 'ТЫ ПОКАЗАЛА СВОЮ ИСТИННУЮ СУЩНОСТЬ, ВЛАДЫЧИЦА СМЕРТИ! ИЗЫДИ ИЗ ЭТОГО СВЯЩЕННОГО МЕСТА!', 28153),
(154087, 'ruRU', 'Самый важный шаг, который кто-либо может сделать, $n, – следующий. Не сходи со своего пути.', 'Самый важный шаг, который кто-либо может сделать, $n, – следующий. Не сходи со своего пути.', 28153),
(154086, 'ruRU', 'Ты – чудовище, созданное по образу и подобию Артаса, $n. Надеюсь, что когда тебя настигнет последняя смерть, она будет такой же долгой и мучительной, как и все те страдания, которые ты принес другим. \n\nКогда весь мир был занят тем, чтобы справиться с нависшей над ним бедой, ты пронесся по планете и вдохнул в мертвых проклятие посмертия. Уверена, ты считал, что делаешь это ради всеобщего блага. Но помяни мои слова, Владыка смерти, – у твоих действий буду серьезные последствия.\n\n<Заллестраза встряхивает головой.>\n\nА пока ты можешь нам пригодиться.', 'Ты – чудовище, созданное по образу и подобию Артаса, $n. Надеюсь, что когда тебя настигнет последняя смерть, она будет такой же долгой и мучительной, как и все те страдания, которые ты принесла другим. \n\nКогда весь мир был занят тем, чтобы справиться с нависшей над ним бедой, ты пронеслась по планете и вдохнула в мертвых проклятие посмертия. Уверена, ты считала, что делаешь это ради всеобщего блага. Но помяни мои слова, Владычица смерти, – у твоих действий буду серьезные последствия.\n\n<Заллестраза встряхивает головой.>\n\nА пока ты можешь нам пригодиться.', 28153),
(154085, 'ruRU', '<Выражение лица Заллестразы немного смягчается.>\n\nМы следили за твоими действиями, $n. Нас осталось очень мало, и жизнь каждого крайне ценна.\n\nЭто не извиняет того, что ты сделал с моими драконами, но мы уважаем твою... сдержанность. Такому существу, как ты, это, должно быть, далось непросто.', '<Выражение лица Заллестразы немного смягчается.>\n\nМы следили за твоими действиями, $n. Нас осталось очень мало, и жизнь каждого крайне ценна.\n\nЭто не извиняет того, что ты сделала с моими драконами, но мы уважаем твою... сдержанность. Такому существу, как ты, это, должно быть, далось непросто.', 28153),
(154084, 'ruRU', 'Да, Владыка смерти $n.\n\nМы знаем, что это ты напал на святилище. Мы знаем, что это ты осквернил и подчинил Киранастраза. \n\nКогда-нибудь ты ответишь за свои проступки.', 'Да, Владычица смерти $n.\n\nМы знаем, что это ты напала на святилище. Мы знаем, что это ты осквернила и подчинила Киранастраза. \n\nКогда-нибудь ты ответишь за свои проступки.', 28153),
(154083, 'ruRU', 'Мы знаем обо всех твоих проступках, рыцарь смерти. Твои действия помогли спасти Азерот от Пылающего Легиона, но наше доверие к тебе теперь подорвано. \n\nБудь осторожен.', 'Мы знаем обо всех твоих проступках, рыцарь смерти. Твои действия помогли спасти Азерот от Пылающего Легиона, но наше доверие к тебе теперь подорвано. \n\nБудь осторожна.', 28153),
(154082, 'ruRU', 'Похоже, несколько драконов в Рубиновом святилище я не заметил. <Попытаться убить ее.>', 'Похоже, несколько драконов в Рубиновом святилище я не заметила. <Попытаться убить ее.>', 28153),
(154081, 'ruRU', 'Надеюсь, теперь ты станешь хоть немного мне доверять.', 'Надеюсь, теперь ты станешь хоть немного мне доверять.', 28153),
(154080, 'ruRU', 'Твои сородичи слабы. Они все равно бы погибли. Так они всего лишь быстрее избавились от страданий.', 'Твои сородичи слабы. Они все равно бы погибли. Так они всего лишь быстрее избавились от страданий.', 28153),
(154079, 'ruRU', 'Я спас всех, кого смог.', 'Я спасла всех, кого смогла.', 28153),
(154078, 'ruRU', 'Ты меня знаешь?', 'Ты меня знаешь?', 28153),
(154077, 'ruRU', 'Нет! Нет! Не-е-ет!', 'Нет! Нет! Не-е-ет!', 28153),
(154076, 'ruRU', '', 'Ради Альянса.', 28153),
(154075, 'ruRU', 'Прочь! Спасайся!', 'Прочь! Спасайся!', 28153),
(154074, 'ruRU', 'Кажется, я опростоволосился...', 'Кажется, я опростоволосилась...', 28153),
(154073, 'ruRU', 'Заберите меня отсюда!', 'Заберите меня отсюда!', 28153),
(154072, 'ruRU', 'Спасибо тебе! Я уж думал, мне крышка.', 'Спасибо тебе! Я уж думала, мне крышка.', 28153),
(154071, 'ruRU', 'Что это за твари?! Я сматываю удочки!', 'Что это за твари?! Я сматываю удочки!', 28153),
(154070, 'ruRU', 'Я спасен! Это чудище меня чуть не сожрало!', 'Я спасена! Это чудище меня чуть не сожрало!', 28153),
(154069, 'ruRU', 'Пф! Не так уж и страшно было.', '', 28153),
(154068, 'ruRU', 'Невероятно... С какими еще порождениями тьмы связался Штормсонг?', '', 28153),
(154067, 'ruRU', 'В святилище нас ждет нечто ужасное. Но мы готовы сразиться с любым врагом!', '', 28153),
(154066, 'ruRU', 'Я чувствую сгусток темной энергии внутри святилища. Нельзя дать ему разрастись! Скорее, вперед!', '', 28153),
(154065, 'ruRU', 'Хм, с виду в вас вроде ничего не изменилось... Ладно, пора продолжать охоту.', '', 28153),
(154064, 'ruRU', 'Правда, успокаивает? И уверенности прибавилось! А теперь давайте завершим начатое.', '', 28153),
(154063, 'ruRU', 'Говорят, жрецы моря черпают силу из очищающих купелей. Проверим, правда ли это, а затем продолжим путь в святилище.', '', 28153),
(154062, 'ruRU', 'Ох! Тогда за мной!', '', 28153),
(154061, 'ruRU', 'Перед входом в святилище необходимо очиститься. Пройдите обряд благословения в каждой из очищающих купелей, а потом сможете зайти внутрь.', '', 28153),
(154060, 'ruRU', 'Сейчас важна каждая капля. За Орду!', '', 28153),
(154059, 'ruRU', 'Я рад, что лорд не подчинил своему безумию все святилище. Спасибо вам.', '', 28153),
(154058, 'ruRU', 'Эти пруды заряжены энергией. Ищите капли чистой воды и запасайте силу!', '', 28153),
(154057, 'ruRU', 'Здесь еще остались следы былой святости. Ищите капли чистой воды – с их помощью мы восстановим ауру святилища.', '', 28153),
(154056, 'ruRU', 'Они меня чуть не прибили. Спасибо тебе, |3-6($c).', 'Они меня чуть не прибили. Спасибо тебе, |3-6($c).', 28153),
(154055, 'ruRU', '', 'Область заражения растет.', 28153),
(154054, 'ruRU', '', 'Заражение прогрессирует.', 28153),
(154053, 'ruRU', '', 'Обнаружен новый штамм.', 28153),
(154052, 'ruRU', '', 'Хирургическое поле активно. Выполняю сбор образцов.', 28153),
(154051, 'ruRU', '', 'Критический уровень заражения. Начинаю дезинфекцию.', 28153),
(154050, 'ruRU', '', 'Вентилирую камеру сдерживания.', 28153),
(154049, 'ruRU', '', 'Тест на устойчивость бактерий к высоким температурам.', 28153),
(154048, 'ruRU', '', 'Протокол вивисекции запущен.', 28153),
(154047, 'ruRU', '', 'Система восстановлена. Уровни угрозы нормализованы.', 28153),
(154046, 'ruRU', 'Шуму вышло многовато, зато результат налицо.', '', 28153),
(154045, 'ruRU', '', 'Вот и все! Больше Язма не сможет подглядывать за нами.', 28153),
(154044, 'ruRU', '', 'У Язмы глаза повсюду. Ее пауки следят за нами. Раздавите их.', 28153),
(154043, 'ruRU', '', 'Дезинфекция завершена.', 28153),
(154042, 'ruRU', 'Это спасательная миссия. Найди пленных солдат, освободи их и выйди к точке эвакуации. Охранников убивать разрешается... и даже рекомендуется.', '', 28153),
(154041, 'ruRU', '', 'Уровень заражения снижен.', 28153),
(154040, 'ruRU', 'Превосходно. Теперь второй отряд с легкостью выполнит свою миссию.', '', 28153),
(154039, 'ruRU', '', 'Больше Рази не будет убивать моих подданных! Благодарю вас.', 28153),
(154038, 'ruRU', '', 'Инфекция уничтожена.', 28153),
(154037, 'ruRU', 'Нам нужна неразбериха. Отдельный отряд готовится освободить наших пленных солдат, но сначала тебе предстоит разобраться со стражей. Пробейся внутрь, убей побольше врагов и уходи.', '', 28153),
(154036, 'ruRU', '', 'Где-то здесь бродит один из доверенных убийц Язмы. Берегитесь!', 28153),
(154035, 'ruRU', '', 'Обнаружен опасный штамм. Начинаю полную нейтрализацию.', 28153),
(154034, 'ruRU', '', 'Это отучит Язму и ее слуг играть с силами зла.', 28153),
(154033, 'ruRU', '', 'Протокол очистки запущен.', 28153),
(154032, 'ruRU', '', 'Злое вуду Язмы оживило маски! Уничтожьте эти оскверненные творения.', 28153),
(154031, 'ruRU', 'Молодцы! Теперь Лига сможет спокойно заниматься исследованием храма.', '', 28153),
(154030, 'ruRU', 'Здесь куча убитых зандаларов. Сдается мне, что Лиге исследователей рановато соваться в храм, где творятся такие безобразия. Выясните, что там происходит, и расчистите путь!', '', 28153),
(154029, 'ruRU', 'Вот, другое дело! Теперь и экспедицию отправлять можно.', '', 28153),
(154028, 'ruRU', 'Я не пошлю своих ребят в храм, пока там летают эти маски. Многовато колдовства!', '', 28153),
(154027, 'ruRU', 'Славно! Хотя мне до сих пор мерещится эта пакость в бороде.', '', 28153),
(154026, 'ruRU', 'Пауки! Опять пауки! Язма наплодила их выше крыши. Невозможно работать! Как насчет передавить их, а?', '', 28153),
(154025, 'ruRU', 'Озаренные, уничтожьте разрушители!', '', 28153),
(154024, 'ruRU', 'Наездники, на крыло!', '', 28153),
(154023, 'ruRU', 'Клан Черного Железа, атакуйте из-под земли!', '', 28153),
(154022, 'ruRU', '', 'Что ж, улики у нас есть. Правда, теперь у пиратов не хватит сил, чтобы выполнить свой план... Но я не против!', 28153),
(154021, 'ruRU', 'Слава... Альянсу...', '', 28153),
(154020, 'ruRU', 'Хоть я и хожу с Туманными Парусами, но как тебе только в голову пришло, что я соглашусь оскорбить свои альянсовские корни союзом с Ордой!', '', 28153),
(154019, 'ruRU', '', 'Пираты из Вольной Гавани вечно что-то затевают. Выясни, что у них на уме в этот раз.', 28153),
(154018, 'ruRU', 'Благодаря тебе у легиона стало куда меньше проблем.', '', 28153),
(154017, 'ruRU', 'Браво! Скоро все эти земли покорятся Альянсу!', '', 28153),
(154016, 'ruRU', 'Задача была сложной, но у тебя все получилось. Так держать!', '', 28153),
(154015, 'ruRU', 'Мы застали врага врасплох. Жаль, что пришлось прибегнуть к насилию, но это было необходимо.', '', 28153),
(154014, 'ruRU', 'Жаль, что тебя не было в моем отряде во время Третьей войны. Ты умеешь сражаться.', '', 28153),
(154013, 'ruRU', 'На Второй войне тебе не было бы цены. Спасибо.', '', 28153),
(154012, 'ruRU', 'Прекрасно сработано. Одной угрозой стало меньше.', '', 28153),
(154011, 'ruRU', 'Спасибо тебе за помощь. Ты – надежда тех, кто не предал Сетралисс!', '', 28153),
(154010, 'ruRU', '', 'Бей по больному – по кошельку!', 28153),
(154009, 'ruRU', '', 'Достать бы учетную книгу этой банды. Тогда можно было бы подпортить им баланс!', 28153),
(154008, 'ruRU', 'Раненых пока нельзя эвакуировать, зато мы выиграли время.', 'Раненых пока нельзя эвакуировать, зато мы выиграли время.', 28153),
(154007, 'ruRU', 'Вот, это остановит кровотечение...', 'Вот, это остановит кровотечение...', 28153),
(154006, 'ruRU', 'Да, знаю – больно, но прошу, не шевелись...', 'Да, знаю – больно, но прошу, не шевелись...', 28153),
(154005, 'ruRU', 'Тихо! Нас услышат...', 'Тихо! Нас услышат...', 28153),
(154004, 'ruRU', 'Приведите подмогу! А я попробую остановить заражение в самом Ульдире!', '', 28153),
(154003, 'ruRU', '', 'Я почерк Оувингс везде узнаю. Я убью тебя, а потом и эту предательницу!', 28153),
(154002, 'ruRU', 'Ворота закрываются! Я не могу упустить такой шанс!', '', 28153),
(154001, 'ruRU', '', 'Вот она, на месте!', 28153),
(154000, 'ruRU', '', 'Капитан! Мятеж!', 28153),
(153999, 'ruRU', 'Мне послышалось, или он сказал \"Г\'уун\"? Быстро, за ним!', '', 28153),
(153997, 'ruRU', 'Видимо, это что-то из Ульдира. Надо разобраться!', '', 28153),
(153996, 'ruRU', 'Я всякую порчу видел, но чтоб такую!..', '', 28153),
(153995, 'ruRU', '', 'Привет, |3-6($c). Хочешь поучиться алхимии?$b$bЯ лучшая во всем Зандаларе, точно тебе говорю.', 28153),
(153994, 'ruRU', 'Представьте, сколько она хранит тайн! Может, здесь мы и найдем ключ к победе над Древними богами!', '', 28153),
(153993, 'ruRU', 'После падения Темной Империи титаны построили эту лабораторию, чтобы экспериментировать над чудищами.', '', 28153),
(153992, 'ruRU', 'Ого! Это что за чудовище?!', '', 28153),
(153991, 'ruRU', 'Эти тоннели ведут к легендарному Ульдиру!', '', 28153),
(153990, 'ruRU', 'Благодаря тебе в пустыне стало намного безопаснее.', '', 28153),
(153989, 'ruRU', '', 'Задача была сложной, но тебе все удалось. Так держать!', 28153),
(153988, 'ruRU', '', 'Одной проблемой меньше. Прекрасно!', 28153),
(153987, 'ruRU', '', 'Очень хорошо. Враг получил урок, который нескоро забудет.', 28153),
(153986, 'ruRU', 'Показывай дорогу.', 'Показывай дорогу.', 28153),
(153985, 'ruRU', '', 'В этом доме полно секретов. Если зачистить верхние этажи, я смогу показать тебе тайный путь в подвал.', 28153),
(153984, 'ruRU', 'Спасибо за подмогу. Вот бы в Вол\'дуне было больше таких, как ты!', '', 28153),
(153983, 'ruRU', 'Благодаря тебе в пустыне стало немного безопаснее.', '', 28153),
(153982, 'ruRU', 'В Вол\'дуне стало одной угрозой меньше. Спасибо тебе!', '', 28153),
(153981, 'ruRU', 'Но... столько же золота...', '', 28153),
(153980, 'ruRU', 'Ты хоть понимаешь, чему пытаешься помешать? Эшвейны дадут нам такую силу, о которой мы и не мечтали!', '', 28153),
(153979, 'ruRU', 'Ты больше не причинишь нам зла!', '', 28153),
(153978, 'ruRU', 'Камни... повсюду... могу... заберут их все!', '', 28153),
(153977, 'ruRU', 'Сюда! Враг здесь!', '', 28153),
(153976, 'ruRU', '', 'Кажется, оторвались. Здорово ты их.', 28153),
(153975, 'ruRU', 'С этими камнями могу станут непобедимыми!', '', 28153),
(153974, 'ruRU', 'Это ты?! Прочь с глаз моих!', '', 28153),
(153973, 'ruRU', '', 'Вот пристали. Подбрось им огоньку, $p!', 28153),
(153972, 'ruRU', '', 'Держись! Прокатимся с ветерком.', 28153),
(153971, 'ruRU', 'Сейчас старый волк покажет зубы!', '', 28153),
(153970, 'ruRU', 'Ну все!', '', 28153),
(153969, 'ruRU', 'Кто-то смелости набрался? Ха!', '', 28153),
(153968, 'ruRU', '', 'Я так не думаю.', 28153),
(153967, 'ruRU', '', 'Ничтожества.', 28153),
(153966, 'ruRU', '', 'Не сегодня.', 28153),
(153965, 'ruRU', 'Разведчики сообщают: где-то здесь мощный враг. Нужно с ним расправиться.', '', 28153),
(153962, 'ruRU', 'Здесь убили нескольких моих солдат. Отомсти за их смерть!', '', 28153),
(153959, 'ruRU', 'Разведчики 7-го легиона обнаружили опасного врага. Разберись с ним.', '', 28153),
(153958, 'ruRU', 'Нет сокровищ... только тьма.', 'Золото, куда ни глянь...', 28153),
(153957, 'ruRU', 'Освободи меня...', 'Неужели... свобода?', 28153),
(153956, 'ruRU', 'Проклятое золото...', 'Проклятые воры...', 28153),
(153955, 'ruRU', 'Брось меня в общую кучу...', 'Золотые кости...', 28153),
(153954, 'ruRU', 'Мне доложили, что в этой области небезопасно. Найди источник угрозы и искорени его.', '', 28153),
(153953, 'ruRU', 'Здесь кто-то напал на наших разведчиков и убил их. Отомсти за них и разберись с врагом!', '', 28153),
(153952, 'ruRU', 'Осторожно, где-то здесь бродит опасное существо. Убей его, пока не поздно!', '', 28153),
(153951, 'ruRU', 'Неплохо выглядишь, босс. Но если тебе не нравится, мы еще поищем.', '', 28153),
(153950, 'ruRU', 'У меня есть по зелью для каждого. Только не спешите их пить.', '', 28153),
(153949, 'ruRU', 'Вы этот город расшевелили на славу. Неплохая работа.\n\nПредлагаю не тратить зря время на поиск виноватых.', '', 28153),
(153948, 'ruRU', 'Я уже слышал эту историю. (Пропустить сценарий и переместиться в порт Зулдазара на Зандаларе)', 'Я уже слышала эту историю. (Пропустить сценарий и переместиться в порт Зулдазара на Зандаларе)', 28153),
(153947, 'ruRU', 'Это будет уроком для твоих хозяев. Наш орден никогда не сдастся!', '', 28153),
(153946, 'ruRU', 'Не дай ему проникнуть в твой разум!', '', 28153),
(153945, 'ruRU', '', 'Все наши мучения – из-за тебя, ЧУДОВИЩЕ!', 28153),
(153944, 'ruRU', 'Я защищу нас!', '', 28153),
(153943, 'ruRU', 'Ни плахф. Ни бормаз. Уу сшокк\'мег ввык ййг\'фар.', '', 28153),
(153942, 'ruRU', 'Золото. Золото.', 'Больше сокровищ.', 28153),
(153941, 'ruRU', 'Нет света. Нет спасения. Забытый король возвращается.', '', 28153),
(153940, 'ruRU', 'Тебе тут не место...', 'Беги...', 28153),
(153939, 'ruRU', 'Все сокровища – Зем\'лану.', 'Сокровища – только для Зем\'лана.', 28153),
(153938, 'ruRU', 'Теперь надо вас представить. Первая помощница Оувингс, это $n. $n, это Оувингс. А теперь к делу.', '', 28153),
(153937, 'ruRU', '', 'Я говорила Киро, что сетраки рано или поздно нападут. Мы могли подготовиться... Может, теперь он меня послушает?', 28153),
(153936, 'ruRU', '', 'Мы не были готовы к нападению. Сетраки убивают и угоняют в рабство без сожаления.', 28153),
(153935, 'ruRU', 'Золото...', 'Блестяшки...', 28153),
(153934, 'ruRU', 'Где-то здесь бродит опасное существо. Убей его, пока оно не напало на кого-нибудь.', '', 28153),
(153933, 'ruRU', 'Кто-то напал на наших союзников неподалеку отсюда. Устрани угрозу как можно скорее.', '', 28153),
(153930, 'ruRU', 'Неподалеку бродит опасное существо. Его нужно обезвредить, пока оно не натворило бед.', '', 28153),
(153929, 'ruRU', '', 'Мне доложили об опасности в этой области. Найди и устрани ее.', 28153),
(153928, 'ruRU', '', 'Неподалеку кто-то напал на наших союзников. Сделай так, чтобы этого больше не повторилось!', 28153),
(153927, 'ruRU', '', 'Где-то рядом скрывается нечто опасное. Убей его, пока оно не убило тебя.', 28153),
(153926, 'ruRU', 'Мне доложили, что в этой области охотится опасное существо. Убей его как можно скорее.', '', 28153),
(153925, 'ruRU', 'Скорей, ко мне!', '', 28153),
(153924, 'ruRU', 'На один из наших караванов напали. Устрани угрозу, чтобы этого больше не повторилось!', '', 28153),
(153923, 'ruRU', 'Она, конечно, человек, но постарайся отнестись к этому с пониманием.', '', 28153),
(153922, 'ruRU', 'Все просто: мы поможем ей поднять мятеж, и нам разрешат остаться тут. Это и будет наш плацдарм.', '', 28153),
(153921, 'ruRU', 'Оувингс не хочет добровольно отказываться от свободы, как остальные пираты.', '', 28153),
(153920, 'ruRU', 'Где-то неподалеку бродит опасное существо. Займись им, пока не поздно!', '', 28153),
(153919, 'ruRU', 'Я о ней впервые услышал, когда исследовал потенциальные места высадки на поморье.', '', 28153),
(153918, 'ruRU', 'Привет, друг-пират!', '', 28153),
(153917, 'ruRU', 'Утонувший мир приветствует ваши пустые души.', '', 28153),
(153916, 'ruRU', 'Уу к\'тот шуул фквати йвак уулг\'ма он\'ма', '', 28153),
(153915, 'ruRU', 'Его больше нет. Осталась только тьма.', '', 28153),
(153914, 'ruRU', '', 'Сэм, я знаю, ты еще с нами. Не сдавайся!', 28153),
(153913, 'ruRU', 'Правду говорят, монстры вам не помеха.', '', 28153),
(153912, 'ruRU', '', 'Прекрасно! Теперь путь свободен.', 28153),
(153911, 'ruRU', 'Так это просто модель... Никому ни слова об этом.', '', 28153),
(153910, 'ruRU', '', 'Давайте вскроем ее и узнаем, что там за тайна.', 28153),
(153909, 'ruRU', 'Этого хватит. Госпожа будет довольна.', '', 28153),
(153908, 'ruRU', '', 'Здорово! Нам любые припасы пригодятся.', 28153),
(153907, 'ruRU', 'Так, босс. Пойдем найдем первую помощницу. Веди себя по-пиратски.', '', 28153),
(153906, 'ruRU', 'А я красавчик! Йо-хо-хо!', '', 28153),
(153905, 'ruRU', 'Какое-то агрессивное чудище преградило нам путь. Убейте его.', '', 28153),
(153904, 'ruRU', '', 'Гигантский хищник мешает нам зачистить берег. Избавьтесь от него, и тогда мы сможем подготовить путь к отступлению.', 28153),
(153903, 'ruRU', 'Дай-ка я тоже приоденусь, босс.', '', 28153),
(153902, 'ruRU', 'Разведчики докладывают, что в Тол Дагоре стоит \"Гордость Кул-Тираса\". Если это правда, украдите для нас этот корабль.', '', 28153),
(153901, 'ruRU', '', 'Надзиратель прячет фамильную реликвию в модели корабля. Достаньте ее, если сможете.', 28153),
(153900, 'ruRU', 'Орде нужны оружие и доспехи. Пока вы там, соберите все, что сможете, и возвращайтесь ко мне.', '', 28153),
(153899, 'ruRU', '', 'В этом хаосе владельцы наверняка бросили часть груза, а мародеры забыли его растащить. Посмотрим, найдется ли для нас что-нибудь полезное...', 28153),
(153898, 'ruRU', 'Они убили твоего отца... Бросили твоего короля умирать... Кого еще ты оставишь на растерзание Орде?', '', 28153),
(153897, 'ruRU', 'Орда – сборище монстров. Неудивительно, что они предали тебя!', '', 28153),
(153896, 'ruRU', 'Ты предпочла этих тварей собственной семье!', '', 28153),
(153895, 'ruRU', 'Ты стояла и смотрела, как меня убивают. И чего ты добилась этим предательством?', '', 28153),
(153894, 'ruRU', 'Тролли из племени Сухокожих идут на Стромгард с востока. Распугайте самых трусливых и убейте остальных.', '', 28153),
(153893, 'ruRU', 'Эту жечь не надо. На ней мы уплывем с острова.', '', 28153),
(153892, 'ruRU', 'Враги сбили нескольких грифонов. Найдите уцелевших всадников на поле боя.', '', 28153),
(153891, 'ruRU', '', 'Ага, увидели? Поняли? Г\'уун всех заберет!', 28153),
(153890, 'ruRU', '', 'Если освободить это чудовище, оно уничтожит Зулдазар!', 28153),
(153889, 'ruRU', '', 'Я знала, что тролли крови опасны, но такого не ожидала...', 28153),
(153888, 'ruRU', 'Кто ты?', 'Кто ты?', 28153),
(153886, 'ruRU', 'Приветствую, $n. Нам известно о твоих деяниях во славу Азерота.', 'Приветствую, $n. Нам известно о твоих деяниях во славу Азерота.', 28153),
(153885, 'ruRU', 'Гадкие твари! Возвращайтесь на дно!', '', 28153),
(153884, 'ruRU', 'Боюсь, сектанты из дома Штормсонгов хотят распространить свое влияние на весь Боралус. Выведи их на чистую воду.', '', 28153),
(153883, 'ruRU', '', 'Значит, это правда... Что ж, хоть сейчас положение исправлено.', 28153),
(153882, 'ruRU', 'За мной! Вместе мы сильны!', '', 28153),
(153881, 'ruRU', 'Поспешим! Его разум терзает тьма!', '', 28153),
(153880, 'ruRU', '', 'Держись, Сэм, мы уже почти на месте!', 28153),
(153879, 'ruRU', 'ПОДНИМИСЬ, КРОВАВЫЙ ПРИЛИВ!', '', 28153),
(153878, 'ruRU', '', 'Говорят, бандиты подкупают стражников Боралуса. Можешь проверить, так ли это?', 28153),
(153877, 'ruRU', 'Уф. Теперь они угомонятся... на целых пять минут.', '', 28153),
(153876, 'ruRU', 'Птицы сошли с ума! Подбросишь им чего-нибудь поесть, чтобы успокоились?', '', 28153),
(153875, 'ruRU', 'Конечно, моего кошелька тут нет, но... Я их поберегу, пока не найдутся законные владельцы.', '', 28153),
(153874, 'ruRU', 'Где мой кошелек? Эй, мелюзга, это ты воруешь тут?! Держи вора!', '', 28153),
(153873, 'ruRU', '', 'Надеюсь, остальные в безопасности.', 28153),
(153872, 'ruRU', '', 'В основном, вульперы – мирный народ. Мы путешествуем, собираем, что получится, по пути и торгуем с о всеми, кого встретим.', 28153),
(153871, 'ruRU', 'Получилось, $p. Ай\'твен пробуждается!', '', 28153),
(153870, 'ruRU', '', 'Смотри, что сетраки сделали с нашим домом...', 28153),
(153869, 'ruRU', '', 'Как раз то, что я люблю.', 28153),
(153868, 'ruRU', 'Огры из клана Тяжелого Кулака идут на Стромгард. Покажите пивопузым подонкам, почем полкило пинков по пятницам!', '', 28153),
(153867, 'ruRU', 'Терпение. Они уже в пути.', '', 28153),
(153866, 'ruRU', '', 'Твои собратья из ордена Возрождения Шторма успеют?', 28153),
(153865, 'ruRU', 'Можно отвести их домой, в деревушку на юго-западе, и получить награду. Только в воду лучше не заходить... Ведь мурлоки размножаются именно там.', '', 28153),
(153864, 'ruRU', 'Неподалеку отсюда резвится стайка малышей-мурлоков.', '', 28153),
(153863, 'ruRU', 'Разведчики нашли украденную вагонетку с рудой у северо-восточной шахты. Было бы неплохо отбить ее.', '', 28153),
(153862, 'ruRU', 'Мы обнаружили дровосеков Орды без охраны. Давайте снимем с этих олухов стружку.', '', 28153),
(153861, 'ruRU', 'Хоть он и соображает кой-чего, а все равно дуб дубом. Пустим его на дрова.', '', 28153),
(153860, 'ruRU', 'Из леса вышел древесный владыка Алдрий.', '', 28153),
(153859, 'ruRU', 'Каменный великан Фозрук бродит на юго-востоке. Не попадитесь ему под ноги.', '', 28153),
(153858, 'ruRU', 'Может, разозлить его и натравить на авангард Орды?', '', 28153),
(153857, 'ruRU', 'В восточных холмах замечен гигантский элементаль земли.', '', 28153),
(153856, 'ruRU', 'Солдаты Лиги, ваше время пришло!', '', 28153),
(153855, 'ruRU', 'Рыцари! Вперед, на Ар\'горок, во имя Света!', '', 28153),
(153854, 'ruRU', 'Враги подбираются к руднику Гальсона. Не дайте им зажилить наше железо!', '', 28153),
(153853, 'ruRU', 'Враги атакуют нашу лесопилку. Пора бы их вырубить и выпилить!', '', 28153),
(153852, 'ruRU', 'Силы Орды вошли в Стромгард. Защитите командира и выставьте незваных гостей за ворота!', '', 28153),
(153851, 'ruRU', 'Войска Орды атакуют Гнездо! Предлагаю спустить захватчиков с холма!', '', 28153),
(153850, 'ruRU', '', 'Подай сигнал, и мы начнем!', 28153),
(153849, 'ruRU', '', 'Вождь требует, чтобы все герои Орды всегда были в форме и готовы к бою. Не будем терять время, давай потренируемся.', 28153),
(153848, 'ruRU', '', 'Добро пожаловать в Силитус. Здесь мы охраняем месторождения азерита от поползновений Альянса.', 28153),
(153847, 'ruRU', 'Чешуя... кольца... шепот...', '', 28153),
(153846, 'ruRU', 'Дай знать, как подготовишься, и мы начнем.', '', 28153),
(153845, 'ruRU', 'Пока мы просто патрулируем, есть время отточить боевые навыки.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153844, 'ruRU', 'Приветствую! Когда мы столкнемся с Ордой, королю Ринну понадобится помощь каждого героя Альянса.', '', 28153),
(153843, 'ruRU', 'Смотрите под ноги. Этот пролив не зря так называется.', '', 28153),
(153842, 'ruRU', '', 'Неплохо. А теперь мы... Погоди, это же... К оружию! Альянс нападает!', 28153),
(153841, 'ruRU', 'От прилива... не спастись...', '', 28153),
(153840, 'ruRU', 'Удерживайте террасы! Зулу нужно время, чтобы сокрушить этих жалких тварей.', '', 28153),
(153839, 'ruRU', 'Войска Орды подошли к Кругу стихий. Надо преподать им урок волшебства!', '', 28153),
(153838, 'ruRU', '', 'За моего отца!', 28153),
(153837, 'ruRU', '', 'Я не стану поддаваться!', 28153),
(153836, 'ruRU', 'Чудесно! А теперь мы... Погоди, это же... К оружию! Орда нападает!', '', 28153),
(153835, 'ruRU', '', 'Твое время пришло!', 28153),
(153834, 'ruRU', '', 'За Кул-Тирас!', 28153),
(153833, 'ruRU', 'Орда атакует Северный перекресток! Отправляйте танки в бой! Угостите противника огнем!', '', 28153),
(153832, 'ruRU', '', '\"Метаморфоза\" превращает тебя в демона, усиливая \"Удар хаоса\" и \"Танец клинков\".', 28153),
(153831, 'ruRU', '', 'Мы с тобой!', 28153),
(153830, 'ruRU', 'Орда вышла на дорогу Храброгласа. Так и наша база окажется под угрозой. Остановите их.', '', 28153),
(153829, 'ruRU', '\"Метаморфоза\" превращает тебя в демона, усиливая \"Удар хаоса\" и \"Танец клинков\".', '', 28153),
(153828, 'ruRU', 'Орда атакует Новоземье. Пора навести там порядок!', '', 28153),
(153827, 'ruRU', '', '\"Танец клинков\" – это шквал ударов, поражающий всех врагов поблизости.', 28153),
(153826, 'ruRU', '\"Танец клинков\" – это шквал ударов, поражающий всех врагов поблизости.', '', 28153),
(153825, 'ruRU', '', 'Он требует немало гнева, но это твоя самая мощная атака. Используй ее почаще.', 28153),
(153824, 'ruRU', 'Он требует немало гнева, но это твоя самая мощная атака. Используй ее почаще.', '', 28153),
(153823, 'ruRU', '', '\"Пронзающий взгляд\" позволяет сжигать врагов демоническим огнем.', 28153),
(153822, 'ruRU', '\"Пронзающий взгляд\" позволяет сжигать врагов демоническим огнем.', '', 28153),
(153821, 'ruRU', '', 'Это одна из твоих сильнейших атак. Используй ее почаще, не давай гневу пропадать.', 28153),
(153820, 'ruRU', 'Это одна из твоих сильнейших атак. Используй ее почаще, не давай гневу пропадать.', '', 28153),
(153819, 'ruRU', 'Мне как раз нужна была помощь, а ты тут как тут! Даже никуда идти не пришлось.', '', 28153),
(153818, 'ruRU', 'Приближаются силы Орды. Удерживайте позиции!', '', 28153),
(153817, 'ruRU', '', 'Отработай \"Превосходство\" на манекене.', 28153),
(153816, 'ruRU', 'Отработай \"Превосходство\" на манекене.', '', 28153),
(153815, 'ruRU', 'Мы разворошили осиное гнездо. Орда готовится к массированному удару.', '', 28153),
(153814, 'ruRU', '', 'Кроме того, эта атака усиливает \"Смертельный удар\". Используй ее первой и как можно чаще.', 28153),
(153813, 'ruRU', 'Кроме того, эта атака усиливает \"Смертельный удар\". Используй ее первой и как можно чаще.', '', 28153),
(153812, 'ruRU', '', '\"Превосходство\" позволяет обрушить на врага всю твою мощь и нанести критический урон.', 28153),
(153811, 'ruRU', '\"Превосходство\" позволяет обрушить на врага всю твою мощь и нанести непоправимый ущерб.', '', 28153),
(153810, 'ruRU', '', 'Похоже, тебе нанесли урон, но это не беда.', 28153),
(153809, 'ruRU', 'Похоже, тебе нанесли урон, но это не беда.', '', 28153),
(153804, 'ruRU', 'Полностью восполни здоровье \"Похищением жизни\".', '', 28153),
(153803, 'ruRU', '', 'Полностью восполни здоровье \"Похищением жизни\".', 28153),
(153802, 'ruRU', '', '\"Похищение жизни\" вытягивает здоровье цели и передает его тебе.', 28153),
(153801, 'ruRU', '\"Похищение жизни\" вытягивает здоровье цели и передает его тебе.', '', 28153),
(153798, 'ruRU', '', 'Отработай \"Стрелу Тьмы\" на манекене.', 28153),
(153797, 'ruRU', 'Отработай \"Стрелу Тьмы\" на манекене.', '', 28153),
(153796, 'ruRU', '', 'Используй \"Стрелу Тьмы\", когда другие твои заклятия уже терзают цель.', 28153),
(153795, 'ruRU', 'Используй \"Стрелу Тьмы\", когда другие твои заклятия уже терзают цель.', '', 28153),
(153794, 'ruRU', '', 'Поразив врага \"Агонией\" и \"Порчей\", не останавливайся, продолжай атаковать магией Тьмы.', 28153),
(153793, 'ruRU', 'Поразив врага \"Агонией\" и \"Порчей\", не останавливайся, продолжай атаковать магией Тьмы.', '', 28153),
(153792, 'ruRU', 'Тени поглотят вас.', '', 28153),
(153791, 'ruRU', '', 'Кроме того, \"Ужасное бешенство\" сокращает время восстановления \"Звериного гнева\".', 28153),
(153790, 'ruRU', 'Кроме того, \"Ужасное бешенство\" сокращает время восстановления \"Звериного гнева\".', '', 28153),
(153789, 'ruRU', '', 'Вас ждет праведная кара!', 28153),
(153788, 'ruRU', '', 'Атакуй манекен и используй \"Ужасное бешенство\".', 28153),
(153787, 'ruRU', 'Атакуй манекен и используй \"Ужасное бешенство\".', '', 28153),
(153786, 'ruRU', '', '\"Ужасное бешенство\" разъяряет питомца и позволяет тебе сосредоточиться на других способностях.', 28153),
(153785, 'ruRU', '\"Ужасное бешенство\" разъяряет питомца и позволяет тебе сосредоточиться на других способностях.', '', 28153),
(153784, 'ruRU', '', 'По твоему приказу питомец может совершить серию яростных атак.', 28153),
(153783, 'ruRU', 'По твоему приказу питомец может совершить серию яростных атак.', '', 28153),
(153782, 'ruRU', '', 'Бросай огнебомбы и сожги всех врагов.', 28153),
(153781, 'ruRU', 'Бросай огнебомбы и сожги всех врагов.', '', 28153),
(153780, 'ruRU', '', 'Они эффективны против скоплений противников, ведь огонь поражает все цели за той, в которую попала бомба.', 28153),
(153779, 'ruRU', 'Они эффективны против скоплений противников, ведь огонь поражает все цели за той, в которую попала бомба.', '', 28153),
(153778, 'ruRU', '', 'Огнебомбы – это еще одна уловка в твоем арсенале. Они медленно, но верно сжигают врагов.', 28153),
(153777, 'ruRU', 'Огнебомбы – это еще одна уловка в твоем арсенале. Они медленно, но верно сжигают врагов.', '', 28153),
(153776, 'ruRU', '', 'Отработай \"Укус змеи\" на манекене.', 28153),
(153775, 'ruRU', 'Отработай \"Укус змеи\" на манекене.', '', 28153),
(153774, 'ruRU', '', '\"Укус змеи\" – это выстрел отравленной стрелой, постепенно убивающей врага.', 28153),
(153773, 'ruRU', '\"Укус змеи\" – это выстрел отравленной стрелой, постепенно убивающей врага.', '', 28153),
(153772, 'ruRU', '', 'Ты – мастер выживания. А оно требует, чтобы враги были мертвы.', 28153),
(153771, 'ruRU', 'Ты – мастер выживания. А оно требует, чтобы враги были мертвы.', '', 28153),
(153770, 'ruRU', 'Эта гадюка...', '', 28153),
(153769, 'ruRU', 'Попутного ветра!', 'Попутного ветра!', 28153),
(153768, 'ruRU', 'Берегись сирен!', 'Берегись сирен!', 28153),
(153767, 'ruRU', 'Мой лоа страдает! Ересь Зула безгранична!', '', 28153),
(153766, 'ruRU', 'Не мерзни!', 'Не мерзни!', 28153),
(153765, 'ruRU', 'Верни мой корабль, $n, и мы покончим с теми, кто посягнул на мой трон.', '', 28153),
(153764, 'ruRU', 'Поднять якорь!', 'Поднять якорь!', 28153),
(153763, 'ruRU', 'Пока!', 'Пока!', 28153),
(153762, 'ruRU', 'Рыбы что-то скрывают.', 'Рыбы что-то скрывают.', 28153),
(153761, 'ruRU', 'А у тебя есть цинга? Покажешь?', 'А у тебя есть цинга? Покажешь?', 28153),
(153759, 'ruRU', 'Я сыграл... свою роль...', '', 28153),
(153758, 'ruRU', 'Тортолланы клевые!', 'Тортолланы клевые!', 28153),
(153757, 'ruRU', 'Хочу деревянную ногу... и руку!', 'Хочу деревянную ногу... и руку!', 28153),
(153756, 'ruRU', 'Ар-р! Я похож на пирата?', 'Ар-р! Я похожа на пирата?', 28153),
(153755, 'ruRU', 'Йо-хо-хо!', 'Йо-хо-хо!', 28153),
(153754, 'ruRU', '', 'Отработай команду \"Взять!\" на манекене несколько раз.', 28153),
(153753, 'ruRU', 'Отработай команду \"Взять!\" на манекене несколько раз.', '', 28153),
(153752, 'ruRU', '', 'Выполняя команду \"Взять!\", питомец совершает мощную атаку и дает тебе нужную для других способностей концентрацию.', 28153),
(153751, 'ruRU', 'Выполняя команду \"Взять!\", питомец совершает мощную атаку и дает тебе нужную для других способностей концентрацию.', '', 28153),
(153750, 'ruRU', 'А у вашего корабля ватерлиния скрипит!', 'А у вашего корабля ватерлиния скрипит!', 28153),
(153749, 'ruRU', '', 'Когда цель оказывается на расстоянии удара, наступает твой звездный час.', 28153),
(153748, 'ruRU', 'Когда цель оказывается на расстоянии удара, наступает твой звездный час.', '', 28153),
(153747, 'ruRU', 'Мне так... холодно...', 'Мне так... холодно...', 28153),
(153746, 'ruRU', 'Убирайся отсюда!', 'Убирайся отсюда!', 28153),
(153745, 'ruRU', 'Согласен. $n, отправляйся на Кезан. Добудь нам технологию очистки азерита... И пусть Разданк пожалеет о том, что осмелился предать Темную Госпожу.', '', 28153),
(153744, 'ruRU', 'Эта сделка того не стоила. Достичь цели можно было намного проще... избавившись от посредника. Смекаешь?', '', 28153),
(153743, 'ruRU', 'Вождю это не понравится. Без технологии Разданка нам будет гораздо сложнее выиграть войну у Альянса.', '', 28153),
(153742, 'ruRU', 'Ну простии-и-ите, принц банши. Виноват я, разволновался, едва не погибнув при заключении сделки, которую даже не одобрял!', '', 28153),
(153741, 'ruRU', 'Возьми себя в руки, Галливикс. Испуганный лепет не к лицу одному из лидеров Орды.', '', 28153),
(153740, 'ruRU', 'Шеф Разданк нас кинул! Это безумие! Впервые вижу, чтоб зеленый поганец так разрывал сделку. Ты не пове...', '', 28153),
(153739, 'ruRU', 'Мистер Гнилостень, плохие новости...', '', 28153),
(153738, 'ruRU', '', 'Троллям крови... нужно... больше силы!', 28153),
(153737, 'ruRU', '', 'Сила! СИЛИЩА!', 28153),
(153736, 'ruRU', 'Ай\'твен отдыхает и набирается сил до тех пор, пока его помощь не понадобится вновь.', '', 28153),
(153735, 'ruRU', 'Телепортироваться к Г\'ууну.', 'Телепортироваться к Г\'ууну.', 28153),
(153734, 'ruRU', 'Телепортироваться к Митраксу.', 'Телепортироваться к Митраксу.', 28153),
(153733, 'ruRU', 'Телепортироваться к Спуску скорби.', 'Телепортироваться к Спуску скорби.', 28153),
(153732, 'ruRU', 'Телепортироваться к входу в Ульдир.', 'Телепортироваться к входу в Ульдир.', 28153),
(153731, 'ruRU', 'Телепортационная площадка в рабочем состоянии, функции стабильны.', 'Телепортационная площадка в рабочем состоянии, функции стабильны.', 28153),
(153730, 'ruRU', 'Новый день, новая победа!', '', 28153),
(153729, 'ruRU', 'Стража сообщает о том, что трогги готовятся к новой атаке. Останови чудовищ, пока не поздно!', '', 28153),
(153728, 'ruRU', 'Готово? Хорошо. Чем меньше вокруг голодных бешеных зверей, тем лучше.', '', 28153),
(153727, 'ruRU', 'Заколдованные медведи?! Это уже слишком. Избавь нас от них.', '', 28153),
(153726, 'ruRU', '', 'Думай что хочешь, но ходячие деревья мне не нравятся.', 28153),
(153725, 'ruRU', '', 'На лесопилке Алгерсона опять что-то стряслось. Сходи туда, разберись.', 28153),
(153724, 'ruRU', 'Прелестно! Вы с моим лохматым приятелем – настоящая банда!', '', 28153),
(153723, 'ruRU', 'Медяк весь извертелся, хочет погонять соколов. Может, вы с ним прогуляетесь, разомнетесь?', '', 28153),
(153722, 'ruRU', 'Полный ягдташ – отрада для глаз! Браво!', '', 28153),
(153721, 'ruRU', 'Новый день, новая охота! Посмотрим, какая добыча тебе попадется!', '', 28153),
(153720, 'ruRU', 'В последнее время в городе творится что-то неладное. На воде лучше. Здесь хорошо.', '', 28153),
(153719, 'ruRU', 'Пару лет назад пришли наги. Их громилы разрушили храм.', '', 28153),
(153718, 'ruRU', 'Жаль, что так вышло с Атал\'Гралом.', '', 28153),
(153717, 'ruRU', 'По ночам я постоянно проверяю, что происходит под днищем лодки. Эти наги повсюду!', '', 28153),
(153716, 'ruRU', 'Атал\'Грал', 'Атал\'Грал', 28153),
(153715, 'ruRU', 'Порт Зулдазара', 'Порт Зулдазара', 28153),
(153714, 'ruRU', '', 'А Грал подобрался к ним слишком близко.', 28153),
(153713, 'ruRU', '', 'Доберитесь до Атал\'Грала. Надеюсь, храм до сих пор стоит.', 28153),
(153712, 'ruRU', 'С твоей помощью мы спасем Мыс Рыбака!', '', 28153),
(153711, 'ruRU', 'Влияние Дипуордена здесь все еще сильно. Надо вернуть жизнь на верфи в нормальное русло!', '', 28153),
(153710, 'ruRU', 'Волны вздохнули с облегчением. Благодаря тебе, боль моря утихла.', '', 28153),
(153709, 'ruRU', 'Нужно избавить бухту от остатков порчи. Очисти воды от зараженных существ!', '', 28153),
(153708, 'ruRU', 'Спасибо. Я сейчас же отправлю эту партию на аванпост!', '', 28153),
(153707, 'ruRU', 'Розалине опять нужны жала. Помочь не желаешь?', '', 28153),
(153706, 'ruRU', 'Пусть Майо неуверенно сидит в седле, зато уверенно забирается в него!', '', 28153),
(153705, 'ruRU', 'Наш добрый друг Майо осваивает верховую езду с поистине черепашьей скоростью! Поднеси ему стаканчик для храбрости, чтобы он не сбавлял темп.', '', 28153),
(153704, 'ruRU', '', 'Надеюсь, они усвоили урок. Преступление – не лучший способ заработка!', 28153),
(153703, 'ruRU', '', 'Контрабандисты хотят вывезти оружие из Боралуса. Покажи им, что это не так просто!', 28153),
(153702, 'ruRU', 'Дети, в укрытие! Быстрее!', 'Дети, в укрытие! Быстрее!', 28153),
(153701, 'ruRU', 'Не бойся, я рядом, все хорошо...', 'Не бойся, я рядом, все хорошо...', 28153),
(153700, 'ruRU', 'Скорее, сюда!', 'Скорее, сюда!', 28153),
(153699, 'ruRU', 'Вот теперь другое дело. О, смотри-ка, и глаза вроде у всех на месте. Прекрасно!', '', 28153),
(153698, 'ruRU', 'Моря Кул-Тираса поглотят вас всех!', 'Моря Кул-Тираса поглотят вас всех!', 28153),
(153697, 'ruRU', 'Что ж... хоть моя семья в безопасности.', 'Что ж... хоть моя семья в безопасности.', 28153),
(153696, 'ruRU', 'Вы заплатите за это!', 'Вы заплатите за это!', 28153),
(153695, 'ruRU', 'Дикари!', 'Дикари!', 28153),
(153694, 'ruRU', 'Птицы атакуют площадь! Уведи горожан в укрытие, пока чайки не выклевали им глаза! Только не повторяй им мои слова.', '', 28153),
(153693, 'ruRU', 'Сюда! На помощь!', 'Сюда! На помощь!', 28153),
(153692, 'ruRU', 'Только не так...', 'Только не так...', 28153),
(153691, 'ruRU', 'Мне страшно!', 'Мне страшно!', 28153),
(153690, 'ruRU', 'А папа и мама?..', 'А папа и мама?..', 28153),
(153689, 'ruRU', 'Мы умрем?', 'Мы умрем?', 28153),
(153688, 'ruRU', 'Почему ты не шевелишься? Мне страшно!', 'Почему ты не шевелишься? Мне страшно!', 28153),
(153687, 'ruRU', 'Проснись! Пожалуйста, проснись...', 'Проснись! Пожалуйста, проснись...', 28153),
(153686, 'ruRU', 'ПАПА!', 'ПАПА!', 28153),
(153685, 'ruRU', 'МАМА!', 'МАМА!', 28153),
(153684, 'ruRU', 'Осторожнее там! Попутного ветра!', '', 28153),
(153683, 'ruRU', '', 'О твоем появлении говорилось в свитках.', 28153),
(153682, 'ruRU', 'А-а-а, $n. Да, это хорошая идея.', '', 28153),
(153681, 'ruRU', 'Мне нужно кое-что отремонтировать.', 'Мне нужно кое-что отремонтировать.', 28153),
(153680, 'ruRU', '', 'Не забывай отдыхать. Усталый солдат ничем Альянсу не поможет.', 28153),
(153679, 'ruRU', 'Орда захватила Круг стихий!', 'Орда захватила Круг стихий!', 28153),
(153678, 'ruRU', '$n захватывает Круг стихий!', '$n захватывает Круг стихий!', 28153),
(153677, 'ruRU', 'Орда захватила рудник Гальсона!', 'Орда захватила рудник Гальсона!', 28153),
(153676, 'ruRU', '$n захватывает рудник Гальсона!', '$n захватывает рудник Гальсона!', 28153),
(153675, 'ruRU', 'Орда захватила Северный перекресток!', 'Орда захватила Северный перекресток!', 28153),
(153674, 'ruRU', '$n захватывает Северный перекресток!', '$n захватывает Северный перекресток!', 28153),
(153673, 'ruRU', 'Орда захватила Гнездо!', 'Орда захватила Гнездо!', 28153),
(153672, 'ruRU', '$n захватывает Гнездо!', '$n захватывает Гнездо!', 28153),
(153671, 'ruRU', 'Орда захватила Новоземье!', 'Орда захватила Новоземье!', 28153),
(153670, 'ruRU', '$n захватывает Новоземье!', '$n захватывает Новоземье!', 28153),
(153669, 'ruRU', 'Орда захватила Верхние вырубки!', 'Орда захватила Верхние вырубки!', 28153),
(153668, 'ruRU', '$n захватывает Верхние вырубки!', '$n захватывает Верхние вырубки!', 28153),
(153667, 'ruRU', 'Орда захватила дорогу Храброгласа!', 'Орда захватила дорогу Храброгласа!', 28153),
(153666, 'ruRU', '$n захватывает дорогу Храброгласа!', '$n захватывает дорогу Храброгласа!', 28153),
(153665, 'ruRU', 'Наши подвиги войдут в анналы военной истории.', '', 28153),
(153664, 'ruRU', 'Противник поражен нашей стратегией и ее безупречным исполнением!', '', 28153),
(153663, 'ruRU', 'Они были совершенно не готовы.', '', 28153),
(153662, 'ruRU', '', 'Виктория... больше не с нами...', 28153),
(153661, 'ruRU', '', 'Все во двор за Натаносом! Я прикрою отступление и задержу Альянс.', 28153),
(153660, 'ruRU', 'Солдаты, на позиции! Альянс наступает!', '', 28153),
(153659, 'ruRU', '', 'Зандалары и не подозревают, что за кошмар их ждет. Надо их предупредить.', 28153),
(153658, 'ruRU', '', 'Королева Азшара что-то затевает, и у нее есть союзники.', 28153),
(153657, 'ruRU', '', 'Ну и ну! Просто ужас какой-то. Это приказ убить всех, кто поклоняется Гралу!', 28153),
(153656, 'ruRU', 'У нас будет свобода маневра и десятикратный перевес!', '', 28153),
(153655, 'ruRU', 'Не возвращай меня в голема...', 'Отпусти мой дух. Прошу...', 28153),
(153654, 'ruRU', 'Мы идем за тобой, Зак\'ражан...', 'Ты следующий, Зак\'ражан...', 28153),
(153653, 'ruRU', 'Неужели... меня ждет покой?', 'Наконец-то... я обрету покой.', 28153),
(153652, 'ruRU', 'Бвонсамди... не даст мне умереть...', 'Где же... Та Сторона?', 28153),
(153651, 'ruRU', 'Саженец съели дикие звери!', 'Саженец съели дикие звери!', 28153),
(153650, 'ruRU', 'У-А-А!', '', 28153),
(153649, 'ruRU', 'Не дайте лазутчикам Орды скрыться!', '', 28153),
(153648, 'ruRU', 'Стража! В городе враги! Все по местам! Закрыть ворота, перекрыть выезды!', '', 28153),
(153647, 'ruRU', 'Отлично. Погнали!', '', 28153),
(153646, 'ruRU', 'Конечно.', 'Конечно.', 28153),
(153645, 'ruRU', 'Всех твоих друзей запытали и убили ведьмы.', 'Всех твоих друзей запытали и убили ведьмы.', 28153),
(153644, 'ruRU', 'Вот проклятье! Плохо, очень плохо.\n\nНо у меня есть и хорошие новости. Я почти закончил обустраивать аванпост в горах. Хочешь посмотреть?', '', 28153),
(153643, 'ruRU', 'Похоже, вы из леса. Как там дела у ребят?', '', 28153),
(153642, 'ruRU', 'Мда. А я тут как раз закончил изобретать волкоцикл.', '', 28153),
(153641, 'ruRU', 'Босс, это вы! И трицикл ваш тоже!', '', 28153),
(153640, 'ruRU', '1 минута до начала битвы за Стромгард.', '', 28153),
(153639, 'ruRU', 'Вместе мы сильнее.', '', 28153),
(153638, 'ruRU', 'Никогда не сдавайся. Всегда выживай.', '', 28153),
(153637, 'ruRU', 'Будь осторожней.', '', 28153),
(153636, 'ruRU', 'Я же просил – без глупостей.', '', 28153),
(153635, 'ruRU', 'Изгои приветствуют тебя.', '', 28153),
(153634, 'ruRU', 'Хочешь подсобить?', '', 28153),
(153633, 'ruRU', 'Что привело тебя сюда?', '', 28153),
(153632, 'ruRU', 'Попутного тебе ветра.', '', 28153),
(153631, 'ruRU', 'Сила и доблесть.', '', 28153),
(153630, 'ruRU', 'Иди с честью.', '', 28153),
(153629, 'ruRU', 'Эта земля... восстанет против вас...', 'Эта земля... восстанет против вас...', 28153),
(153628, 'ruRU', 'Нет! Мне нужна твоя голова...', 'Нет! Мне нужна твоя голова...', 28153),
(153627, 'ruRU', 'Жалкие псы... Альянса...', 'Жалкие псы... Альянса...', 28153),
(153626, 'ruRU', 'Долго вам не продержаться...', 'Долго вам не продержаться...', 28153),
(153625, 'ruRU', 'Империя... вечна...', 'Империя... вечна...', 28153),
(153624, 'ruRU', 'Нас так просто не остановить...', 'Нас так просто не остановить...', 28153),
(153623, 'ruRU', 'Я слушаю тебя.', '', 28153),
(153622, 'ruRU', 'Это еще не конец...', 'Это еще не конец...', 28153),
(153621, 'ruRU', 'Здесь тебе всегда рады.', '', 28153),
(153620, 'ruRU', 'За... Орду.', 'За... Орду.', 28153),
(153619, 'ruRU', 'За твою голову меня щедро наградят!', 'За твою голову меня щедро наградят!', 28153),
(153618, 'ruRU', 'Думаешь, ты умнее нас? Ха!', 'Думаешь, ты умнее нас? Ха!', 28153),
(153617, 'ruRU', 'Из ваших голов выйдут знатные трофеи!', 'Из ваших голов выйдут знатные трофеи!', 28153),
(153616, 'ruRU', 'Всех нас тебе не найти!', 'Всех нас тебе не найти!', 28153),
(153615, 'ruRU', 'Выходи, крошка из Альянса, поиграем!', 'Выходи, крошка из Альянса, поиграем!', 28153),
(153614, 'ruRU', 'Эти земли принадлежат зандаларам!', 'Эти земли принадлежат зандаларам!', 28153),
(153613, 'ruRU', 'Вы пожалеете, что пришли сюда!', 'Вы пожалеете, что пришли сюда!', 28153),
(153612, 'ruRU', 'Убирайся отсюда!', 'Убирайся отсюда!', 28153),
(153611, 'ruRU', 'Ну уж нет. Только дикари бросают своих.', 'Ну уж нет. Только дикари бросают своих.', 28153),
(153610, 'ruRU', 'Я не уйду без тебя!', 'Я не уйду без тебя!', 28153),
(153609, 'ruRU', 'Я вытащу тебя отсюда!', 'Я вытащу тебя отсюда!', 28153),
(153608, 'ruRU', 'Я тебя не брошу!', 'Я тебя не брошу!', 28153),
(153607, 'ruRU', 'Что ты делаешь? Спасайся!', 'Что ты делаешь? Спасайся!', 28153),
(153606, 'ruRU', 'Я в порядке. Беги за подмогой!', 'Я в порядке. Беги за подмогой!', 28153),
(153605, 'ruRU', 'Беги отсюда. Все кончено...', 'Беги отсюда. Все кончено...', 28153),
(153604, 'ruRU', 'Нужно бежать отсюда...', 'Нужно бежать отсюда...', 28153),
(153603, 'ruRU', 'Я не спускаю с тебя глаз.', '', 28153),
(153602, 'ruRU', 'Возможно, в следующий раз они будут осторожнее. Им повезло, что Орда всегда готова прийти на помощь в трудную минуту.', '', 28153),
(153601, 'ruRU', 'Союзникам нужна наша помощь: похоже, они попали в плен. Сделай одолжение, освободи их.', '', 28153),
(153600, 'ruRU', 'С этими разведданными мы получим преимущество над Альянсом. Твоя служба будет вознаграждена.', '', 28153),
(153599, 'ruRU', 'Наши разведчики докладывают, что здесь скоро проследует гонец с важным сообщением. Перехвати его во что бы то ни стало.', '', 28153),
(153598, 'ruRU', 'Лоа благоволят тебе. Это хорошо... Только нос не задирай.', '', 28153),
(153597, 'ruRU', 'Враги вновь заполонили Сад лоа. Преподай им урок хороших манер, и да пребудет с тобой сила лоа!', '', 28153),
(153596, 'ruRU', 'Встретимся на заставе. Мы должны найти ответ. Похоже на потенциальный подъем.', '', 28153),
(153595, 'ruRU', 'Это грязная, но необходимая работа. Мы должны держать врага в неведении.', '', 28153),
(153594, 'ruRU', 'Альянс отправил шпионов, чтобы вынюхать наши секреты. Не дай им узнать ничего о наших планах.', '', 28153),
(153593, 'ruRU', 'Без флота зандаларов эта война с Альянсом станет для нас последней.', '', 28153),
(153592, 'ruRU', 'Альянс не будет ждать, пока мы построим флот. Нам нужен союз с зандаларами.', '', 28153),
(153591, 'ruRU', 'Заставь зандаларов служить Орде.', '', 28153),
(153590, 'ruRU', 'Нам нужен зандаларский флот.', '', 28153),
(153589, 'ruRU', 'Воля вождя должна быть исполнена.', '', 28153),
(153588, 'ruRU', 'С тобой и Ай\'твеном все должно пройти как по маслу.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153587, 'ruRU', 'Что-то зандалары от меня не в восторге.', '', 28153),
(153586, 'ruRU', 'Голос Орды.', '', 28153),
(153585, 'ruRU', 'Флот зандаларов ДОЛЖЕН присоединиться к Орде. Я на тебя рассчитываю.', '', 28153),
(153584, 'ruRU', '', 'Герои Орды спасли меня и Зула из Штормградской тюрьмы. Неужели ты откажешь им в аудиенции?', 28153),
(153583, 'ruRU', 'Мой король, Орда пришла сюда только затем, чтобы украсть наши корабли!', '', 28153),
(153582, 'ruRU', 'Товар качественный, без вопросов.', 'Товар качественный, без вопросов.', 28153),
(153581, 'ruRU', 'Я привожу припасы из Крутогорья.', 'Я привожу припасы из Крутогорья.', 28153),
(153580, 'ruRU', '(Просмотреть события, которые привели к образованию раны на теле Азерот.)', '(Просмотреть события, которые привели к образованию раны на теле Азерот.)', 28153),
(153579, 'ruRU', '<На панели управления титанов отображается несколько записей. Вы можете выбрать одну из них для просмотра.>', '', 28153),
(153578, 'ruRU', 'Надеюсь, на тебе огнеупорное белье!', 'Надеюсь, на тебе огнеупорное белье!', 28153),
(153577, 'ruRU', 'Ух, сейчас будет жарко!', 'Ух, сейчас будет жарко!', 28153),
(153576, 'ruRU', 'Пора зажигать!', 'Пора зажигать!', 28153),
(153575, 'ruRU', 'Этот \"алмазный дворф\" – голос нашего мира. Он появляется только в самый трудный час.', '', 28153),
(153574, 'ruRU', '', 'Представляешь, этот алмазный дворф может перенести нас в любую точку планеты!', 28153),
(153573, 'ruRU', 'Во дела! Из ниоткуда возникает алмазный дворф и раздает мощные артефакты...', '', 28153),
(153572, 'ruRU', 'Магни, я понимаю, что это важно. Но ради всего Кул-Тираса, пожалуйста, поторопись.', '', 28153),
(153571, 'ruRU', 'Следуй за мной, $n! Азерот зовет тебя!', '', 28153),
(153570, 'ruRU', 'Ох, забыл, что я его сюда же и привязал.', 'Ох, забыла, что назначила точку возвращения сюда. Проклятье!', 28153),
(153569, 'ruRU', 'Я слишком стар для этого. Хватит с меня!', 'Я слишком стара для этого. Хватит с меня!', 28153),
(153568, 'ruRU', 'Возьми себя в руки, рядовой.', 'Возьми себя в руки, рядовой.', 28153),
(153567, 'ruRU', 'Сэр, я... Я исправлюсь, сэр.', 'Сэр, я... Я исправлюсь, сэр.', 28153),
(153566, 'ruRU', 'Рядовой Джеймс, твои родители что, не уделяли тебе в детстве достаточно внимания? Почему мне приходится тратить свое время на то, чтобы искать тебя непонятно где?', 'Рядовой Джеймс, твои родители что, не уделяли тебе в детстве достаточно внимания? Почему мне приходится тратить свое время на то, чтобы искать тебя непонятно где?', 28153),
(153565, 'ruRU', 'Сержант... спасибо, что пришли за мной... сэр.', 'Сержант... спасибо, что пришли за мной... сэр.', 28153),
(153564, 'ruRU', 'Вперед!', 'Вперед!', 28153),
(153563, 'ruRU', 'Пора возвращаться. Змеевержцу нужен полный доклад.', 'Пора возвращаться. Змеевержцу нужен полный доклад.', 28153),
(153562, 'ruRU', '', 'Шипошкурые меня не убили, и они об этом пожалеют.', 28153),
(153561, 'ruRU', '', 'Надо будет сменить декор, когда вернусь. На что-нибудь связанное с клыками... где бы их взять?$b$b<Дил зловеще ухмыляется.>', 28153),
(153560, 'ruRU', '', 'Сперва опрокину стаканчик, а потом займусь отстройкой дома. Благодаря тебе их стало меньше, и это прекрасно!', 28153),
(153559, 'ruRU', 'Я не могу здесь задерживаться, нужно возвращаться на ферму. Это по просьбе мэра пришел сюда поблагодарить за помощь с Шипошкурыми.$b$bУ тебя отлично вышло.', '', 28153),
(153558, 'ruRU', 'Так этим свинобразам! Они твою взбучку надолго запомнят!', '', 28153),
(153557, 'ruRU', 'Я не могу здесь задерживаться. Нужно починить роботов и исправить тот ужас, который они сотворили с полями.$b$bГлавное – не забывать время от времени отдыхать.', '', 28153),
(153556, 'ruRU', 'Роботы на ферме находятся в режиме самозащиты. Но, уверен, все обойдется.', '', 28153),
(153555, 'ruRU', 'Если увидишь где иглы свинобразов, хватай тут же. Они на удивление полезны в работе. Даже сами свинобразы кладут их в свои варева!', '', 28153),
(153554, 'ruRU', 'На севере Орда, на западе свинобразы. Вот как тут будешь доверять ополчению?', '', 28153),
(153553, 'ruRU', 'Надеюсь, с Рольфом, Мортом и Спиффом все в порядке.', '', 28153),
(153552, 'ruRU', '', 'Мои шпионы докладывают, что без нашего флота войну против Альянса вам не выиграть. \n\nА это значит... что все самые противные задачи, которые сегодня на меня свалятся, будешь делать ты. И попробуй только откажись!', 28153),
(153551, 'ruRU', '', 'Я пытаюсь втолковать Золани и Таланджи, что порт в безопасности. И что, слушают они меня? Нет.$b$bЧто происходит кругом? Драки. Головорезы везде бродят. Потасовки на каждом углу. Это всегда пожалуйста! Но ничего такого, чтобы стоило отвлекать короля от более важных дел.', 28153),
(153550, 'ruRU', 'Следуйте за мной, если не боитесь.', 'Следуйте за мной, если не боитесь.', 28153),
(153549, 'ruRU', 'У меня есть кое-что важное, $n. То, что поможет и этой земле.', '', 28153),
(153548, 'ruRU', 'Спокойно, друзья! Это Магни Бронзобород... Бывший король Стальгорна, а теперь – Вестник Азерот.', '', 28153),
(153547, 'ruRU', 'Это что-то новое.', '', 28153),
(153546, 'ruRU', 'Колдовство!', '', 28153),
(153545, 'ruRU', '', 'Ого, алмазный дворф!', 28153),
(153544, 'ruRU', 'Высвободи мощь Сердца!', '', 28153),
(153543, 'ruRU', 'Ужасные новости. Нужно немедленно сообщить об этом главнокомандующему.', 'Ужасные новости. Нужно немедленно сообщить об этом главнокомандующему.', 28153),
(153542, 'ruRU', 'Кортек безумен! Его нужно остановить!', 'Кортек безумен! Его нужно остановить!', 28153),
(153541, 'ruRU', 'Но Кортек устал от мира. Он пренебрег жертвой Сетралисс и по собственной глупости пытается найти все ключи, чтобы обрушить ярость К\'тракси на своих врагов.', 'Но Кортек устал от мира. Он пренебрег жертвой Сетралисс и по собственной глупости пытается найти все ключи, чтобы обрушить ярость К\'тракси на своих врагов.', 28153),
(153540, 'ruRU', 'Великий мудрец Султис заручился нашей с Кортеком помощью, чтобы воздвигнуть вокруг павшего К\'тракси магический барьер. Мы поклялись, что никогда больше не позволим подобному ужасу разгуливать на свободе.', 'Великий мудрец Султис заручился нашей с Кортеком помощью, чтобы воздвигнуть вокруг павшего К\'тракси магический барьер. Мы поклялись, что никогда больше не позволим подобному ужасу разгуливать на свободе.', 28153),
(153539, 'ruRU', 'Высвобожденная разрушением мощь была просто невероятной. Наши земли полностью изменились.', 'Высвобожденная разрушением мощь была просто невероятной. Наши земли полностью изменились.', 28153),
(153538, 'ruRU', 'Мы спаслись только благодаря вмешательству нашей лоа. Сетралисс пожертвовала собой, чтобы подчинить К\'тракси, но он все же успел уничтожить древнюю пирамиду, которая стояла в самом центре этой земли.', 'Мы спаслись только благодаря вмешательству нашей лоа. Сетралисс пожертвовала собой, чтобы подчинить К\'тракси, но он все же успел уничтожить древнюю пирамиду, которая стояла в самом центре этой земли.', 28153),
(153537, 'ruRU', 'Давным-давно, прежде чем пустыня начала расти, на эту землю пришел ужасный К\'тракси. Он убивал все и всех на своем пути, будь то тролль или сетрак.', 'Давным-давно, прежде чем пустыня начала расти, на эту землю пришел ужасный К\'тракси. Он убивал все и всех на своем пути, будь то тролль или сетрак.', 28153),
(153536, 'ruRU', '', 'Нужно сохранять бдительность. Нападения Орды на Бреннадам не прекращаются.', 28153),
(153535, 'ruRU', '', 'Если ты увидишь еще каких-нибудь тварей, которые соберутся напасть на мой город, обязательно сообщи. Буду очень благодарна.', 28153),
(153534, 'ruRU', '', 'Все надеются на то, что я спасу город. И я их не подведу!', 28153),
(153533, 'ruRU', '', 'Похоже, пока все в безопасности...', 28153),
(153532, 'ruRU', 'Это не просто камень, это ключ. Один из ключей, которые удерживают взаперти великое и ужасное зло.', 'Это не просто камень, это ключ. Один из ключей, которые удерживают взаперти великое и ужасное зло.', 28153),
(153531, 'ruRU', 'О! Тут какой-то камень.', 'О! Тут какой-то камень.', 28153),
(153530, 'ruRU', '\"Беги от дочери морей!\"', '\"Беги от дочери морей!\"', 28153),
(153529, 'ruRU', 'Он отдал последний свой приказ:', 'Он отдал последний свой приказ:', 28153),
(153528, 'ruRU', 'Обломки кораблей,', 'Обломки кораблей,', 28153),
(153527, 'ruRU', '', 'У этого дворфа есть артефакт, который может спасти мой народ. Я готова пойти на риск.', 28153),
(153526, 'ruRU', 'Окинув взглядом в смертный час', 'Окинув взглядом в смертный час', 28153),
(153525, 'ruRU', 'Осталась в стороне.', 'Осталась в стороне.', 28153),
(153524, 'ruRU', 'И только дочь в решающем бою', 'И только дочь в решающем бою', 28153),
(153523, 'ruRU', 'Был готов к войне,', 'Был готов к войне,', 28153),
(153522, 'ruRU', 'Но грозный враг в неведомом краю', 'Но грозный враг в неведомом краю', 28153),
(153521, 'ruRU', 'Чтоб дочь спасли от бед.', 'Чтоб дочь спасли от бед.', 28153),
(153520, 'ruRU', 'Повел свой флот, молясь морским ветрам,', 'Повел свой флот, молясь морским ветрам,', 28153),
(153519, 'ruRU', 'Принцесса, вы же не собираетесь просто так довериться алмазному королю?', '', 28153),
(153518, 'ruRU', 'Ушел за солнцем вслед.', 'Ушел за солнцем вслед.', 28153),
(153517, 'ruRU', 'Бежала ты, и старый адмирал', 'Бежала ты, и старый адмирал', 28153),
(153516, 'ruRU', 'Найти в тебе врага?', 'Найти в тебе врага?', 28153),
(153515, 'ruRU', 'Скажи, как мог народ земли твоей', 'Скажи, как мог народ земли твоей', 28153),
(153514, 'ruRU', 'Ты бросила родные берега?', 'Ты бросила родные берега?', 28153),
(153513, 'ruRU', 'Зачем, зачем, наследница морей,', 'Зачем, зачем, наследница морей,', 28153),
(153512, 'ruRU', 'Но дочь была не с ним.', 'Но дочь была не с ним.', 28153),
(153511, 'ruRU', 'Шел в Терамор за смертью адмирал,', 'Шел в Терамор за смертью адмирал,', 28153),
(153510, 'ruRU', 'Их ждал огонь и дым.', 'Их ждал огонь и дым.', 28153),
(153509, 'ruRU', 'О, Калимдор, моих ты братьев знал.', 'О, Калимдор, моих ты братьев знал.', 28153),
(153508, 'ruRU', 'Унося предсмертный крик.', 'Унося предсмертный крик.', 28153),
(153507, 'ruRU', 'Ревел прибой все яростней и злей,', 'Ревел прибой все яростней и злей,', 28153),
(153506, 'ruRU', 'Я помню этот миг...', 'Я помню этот миг...', 28153),
(153505, 'ruRU', '\"Беги, беги от дочери морей!\"', '\"Беги, беги от дочери морей!\"', 28153),
(153504, 'ruRU', 'Добрый день, |3-6($r).', '', 28153),
(153502, 'ruRU', 'У тебя в карманах что-нибудь есть?', 'У тебя в карманах что-нибудь есть?', 28153),
(153501, 'ruRU', 'Я останусь здесь и займусь обороной. Спасибо тебе.', 'Я останусь здесь и займусь обороной. Спасибо тебе.', 28153),
(153500, 'ruRU', '', '', 28153),
(153499, 'ruRU', '', 'Слуги! Убейте их!', 28153),
(153498, 'ruRU', 'Если бы не вы с сержантом, меня бы уже не было в живых. Спасибо тебе еще раз.', 'Если бы не вы с сержантом, меня бы уже не было в живых. Спасибо тебе еще раз.', 28153),
(153497, 'ruRU', '', 'Я сообщу Зулу. Он решит, нужно ли об этом знать Растахану.', 28153),
(153496, 'ruRU', 'Убейте их, пока они не пробились!', '', 28153),
(153495, 'ruRU', 'До пристани побежим без передышки. Скажи, когда начинать, $n.', '', 28153),
(153494, 'ruRU', 'Смерти ищешь?', '', 28153),
(153493, 'ruRU', 'Не выдавай нас, $n.', '', 28153),
(153492, 'ruRU', 'Хочешь, чтобы нас всех поубивали?', '', 28153),
(153491, 'ruRU', 'Эй! Не убегай!', '', 28153),
(153490, 'ruRU', 'Иди сюда!', '', 28153),
(153489, 'ruRU', 'О, хвала Свету, это ты, $n! Я побегу в храм. Здесь небезопасно.', '', 28153),
(153488, 'ruRU', 'Надеюсь, ты его избежишь.', '', 28153),
(153487, 'ruRU', 'Выбор между верностью и честью – тяжелейший из всех.', '', 28153),
(153486, 'ruRU', 'Что ты имеешь в виду?', 'Что ты имеешь в виду?', 28153),
(153485, 'ruRU', 'После всего, что она сделала, я не могу вернуться в ее Орду.', '', 28153),
(153484, 'ruRU', 'Ты считаешь, что вернешь меня в Оргриммар, к вождю. Но ты ошибаешься.', '', 28153),
(153483, 'ruRU', 'Пришла пора нанести Торговой компании стратегический удар!', '', 28153),
(153482, 'ruRU', 'Жду твоей команды, $n.', '', 28153),
(153477, 'ruRU', '', 'Рано тебе умирать. У нас еще есть дела.', 28153),
(153476, 'ruRU', '', 'Бвонсамди еще не звал тебя, $n.', 28153),
(153475, 'ruRU', '', 'Вставай. Жить будешь.', 28153),
(153474, 'ruRU', '', 'Вставай, $n. Мы еще не закончили.', 28153),
(153473, 'ruRU', '', 'Лоа не дадут тебе умереть, $n.', 28153),
(153472, 'ruRU', 'Кажется, наша разведка ошибалась, считая всех сетраков плохими.', 'Кажется, наша разведка ошибалась, считая всех сетраков плохими.', 28153),
(153471, 'ruRU', 'В эту игру могут играть двое!', 'В эту игру могут играть двое!', 28153),
(153470, 'ruRU', '', 'Грядет новая империя троллей. Мы, наконец, проснулись!', 28153),
(153469, 'ruRU', '', 'Зул предрек этот день. Восстаньте... восстаньте, служители крови. Возвестите начало новой эпохи!', 28153),
(153468, 'ruRU', 'Нет! Нет...', 'Нет! Нет...', 28153),
(153467, 'ruRU', 'Как вы смеете забирать мою долю...', 'Как вы смеете забирать мою долю...', 28153),
(153466, 'ruRU', 'Вы свое получите...', 'Вы свое получите...', 28153),
(153465, 'ruRU', 'Герои, за мной!', '', 28153),
(153464, 'ruRU', 'Я... вас достану...', 'Я... вас достану...', 28153),
(153463, 'ruRU', 'Вы покойники! Вы все покойники!', 'Вы покойники! Вы все покойники!', 28153),
(153462, 'ruRU', 'Думаете, вы просто так сможете заставить меня отдать мою долю?', 'Думаете, вы просто так сможете заставить меня отдать мою долю?', 28153),
(153461, 'ruRU', 'Предатели! Я с вас головы поснимаю!', 'Предатели! Я с вас головы поснимаю!', 28153),
(153460, 'ruRU', 'Предатели! Все предатели!', 'Предатели! Все предатели!', 28153),
(153459, 'ruRU', 'Капитан Юдора... приведет нас к победе...', '', 28153),
(153458, 'ruRU', 'Свежее мясо? Трюмные крысы, обед подоспел!', '', 28153),
(153457, 'ruRU', 'Сегодня великие лоа услышат ваши боевые кличи и звон оружия! А павшие устремятся к ним... на Ту Сторону!', '', 28153),
(153456, 'ruRU', 'Подари ей достойную смерть...', '', 28153),
(153455, 'ruRU', 'Подари ему достойную смерть...', '', 28153),
(153454, 'ruRU', 'А-а-а?!', '', 28153),
(153453, 'ruRU', 'Прими смерть...', '', 28153),
(153452, 'ruRU', 'Сегодня лоа были не с тобой.', '', 28153),
(153451, 'ruRU', 'За Зандалар!', '', 28153),
(153450, 'ruRU', 'Продано! Разноцветный меч, 281 золотой! Незаметно к врагу вам теперь не подкрасться!', '', 28153),
(153449, 'ruRU', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t На вас нацелено заклинание |cFFFF0000|Hspell:260838|h[Самонаводящаяся ракета]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t На вас нацелено заклинание |cFFFF0000|Hspell:260838|h[Самонаводящаяся ракета]|h|r!', 28153),
(153448, 'ruRU', 'Добрый вечер, Кул-Тирас!', '', 28153),
(153447, 'ruRU', 'Сколько ушей сегодня пойдет на трофеи!', '', 28153),
(153446, 'ruRU', 'Бой продолжается, это еще не конец!', '', 28153),
(153445, 'ruRU', 'Тихо! Бой еще не окончен!', '', 28153),
(153444, 'ruRU', 'Будет, будет вам кровь! Наберитесь терпения!', '', 28153),
(153443, 'ruRU', 'Продано! \"Мучительные воспоминания\", 18 золотых! Если честно, я бы и ломаного гроша за это не дал. Но свои деньги тратьте, как заблагорассудится.', '', 28153),
(153442, 'ruRU', 'Нет-нет. Хорошее исцеление.', '', 28153),
(153441, 'ruRU', 'Ты даже умереть не можешь как култирасцы.', '', 28153),
(153440, 'ruRU', 'Вот незадача!', '', 28153),
(153439, 'ruRU', 'Добрый вечер, Кул-Тирас!', '', 28153),
(153438, 'ruRU', 'Скоро на арене будет грязно, так что не советую подходить близко. Ну что, вы готовы?', '', 28153),
(153437, 'ruRU', 'И лишь последнему выжившему достанется эта честь!', '', 28153),
(153436, 'ruRU', 'Друзья, мы собрались здесь, чтобы посмотреть, как бандиты, головорезы и пройдохи будут биться за право зваться култирасцами!', '', 28153),
(153435, 'ruRU', 'Продано! Милая леди получает большую ракету любви за 1412 золотых! Теперь о ней несомненно будет говорить весь город!', '', 28153),
(153434, 'ruRU', 'Продано! Молодой человек получает наплечье неустрашимости за 756 золотых! Вряд ли вы сможете его надеть, ну да ладно!', '', 28153),
(153433, 'ruRU', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t Азерокк использует способность |cFFFF0000|Hspell:257597|h[Усиление азеритом]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t Азерокк использует способность |cFFFF0000|Hspell:257597|h[Усиление азеритом]|h|r!', 28153),
(153432, 'ruRU', 'Измена! Взять ее!', '', 28153),
(153431, 'ruRU', 'Кортек не должен заполучить мой ключ. Мы почти на месте, храм как раз перед нами.', '', 28153),
(153430, 'ruRU', 'Я положил его в карман узника, которого они только что схватили. Кажется, его звали Джеймс.', '', 28153),
(153429, 'ruRU', 'Эти глупцы схватили и обыскали меня, но ключ уже был там, где его точно не станут искать.', '', 28153),
(153428, 'ruRU', 'Но Султис погиб, а Кортек предал нас. Теперь он вместе со своими последователями охотится за мной и моим ключом.', '', 28153),
(153427, 'ruRU', 'Давным-давно мы с другими хранителями, Кортеком и Султисом, правили, как один – в полном согласии. Наша лоа доверила нам три ключа, которые сдерживали древнее злобное создание, заточенное под песками.', '', 28153),
(153426, 'ruRU', 'Наш храм – последний бастион в войне против отступников.', '', 28153),
(153425, 'ruRU', '', 'Ладно, ладно. Возможно, у нас есть крохотные осложнения, но королю не о чем беспокоиться!', 28153),
(153424, 'ruRU', '', 'Мы больше не станем заискивать перед лоа! Настал час крови!', 28153),
(153423, 'ruRU', '', 'Не стоит беспокоиться о мелких проступках. Нас ждут более важные дела.', 28153),
(153421, 'ruRU', '', 'Надеюсь, тебе понравилось!', 28153),
(153419, 'ruRU', '', 'Вот, держи. Не могу же я отпустить тебя на голодный желудок!', 28153),
(153418, 'ruRU', '', 'А-а-а, они просто идеальны!', 28153),
(153417, 'ruRU', '', 'Минутку, дорогуша. У меня для тебя кое-что есть.', 28153),
(153416, 'ruRU', 'Вот так! От такого удара содрогнется вся их империя!', '', 28153),
(153415, 'ruRU', 'Я выбираю Па\'ку, повелительницу ветров.', 'Я выбираю Па\'ку, повелительницу ветров.', 28153),
(153414, 'ruRU', 'Я выбираю Гонка, повелителя стаи.', 'Я выбираю Гонка, повелителя стаи.', 28153),
(153413, 'ruRU', 'Зандалары вырастили монстра и надеются, что он их защитит. Покажи им, что это не так!', '', 28153),
(153412, 'ruRU', 'Наконец-то Стромгард снова наш.', '', 28153),
(153411, 'ruRU', 'Сдохни, собака!', '', 28153),
(153410, 'ruRU', 'Знай свое место.', '', 28153),
(153409, 'ruRU', 'По тебе плакать не будут.', '', 28153),
(153408, 'ruRU', 'Рано или поздно Стромгард вернется к Альянсу.', '', 28153),
(153407, 'ruRU', 'Расстреляйте Орду!', '', 28153),
(153406, 'ruRU', 'Третий взвод, огонь!', '', 28153),
(153405, 'ruRU', 'Я хочу изменить изображенного здесь лоа из Зулдазара.', 'Я хочу изменить изображенного здесь лоа из Зулдазара.', 28153),
(153404, 'ruRU', 'Стрелки, огонь!', '', 28153),
(153403, 'ruRU', 'Восстаньте, тени прошлого!', '', 28153),
(153402, 'ruRU', 'Духи Аратора сокрушат вас!', '', 28153),
(153401, 'ruRU', 'Злу не укрыться от нас даже в самых глухих уголках! Спасибо тебе.', '', 28153),
(153400, 'ruRU', 'Предки мои! Защитите родной дом!', '', 28153),
(153399, 'ruRU', 'Я перебил тысячи ваших собратьев. Вы будете следующими.', '', 28153),
(153398, 'ruRU', 'Еще одна победа во славу империи Зандалари и Орды!', '', 28153),
(153397, 'ruRU', 'В этой глуши вызревает великое зло. Расправься с ним, пока не поздно!', '', 28153),
(153396, 'ruRU', 'Могучий обитатель джунглей угрожает нам в этих краях. Выследи и убей его!', '', 28153),
(153395, 'ruRU', 'Победа всегда на стороне праведных.', '', 28153),
(153394, 'ruRU', 'Я очистил тебя!', '', 28153),
(153393, 'ruRU', 'Твоя судьба была предрешена.', '', 28153),
(153392, 'ruRU', 'Правосудие свершилось.', '', 28153),
(153391, 'ruRU', 'Мы потеряли Стромгард, но Альянс никогда не падет.', '', 28153),
(153390, 'ruRU', 'Я покажу вам мощь Света!', '', 28153),
(153389, 'ruRU', 'Бойтесь Света, нечистые создания!', '', 28153),
(153388, 'ruRU', 'Свет сокрушит тебя.', '', 28153),
(153387, 'ruRU', 'Еще одной угрозой меньше, еще одна победа Альянса!', '', 28153),
(153386, 'ruRU', 'Свет принесет нам победу!', '', 28153),
(153385, 'ruRU', '', 'Я – первый летописец. Король поручил мне высекать в камне нашу историю, чтобы она жила веками.', 28153),
(153384, 'ruRU', 'Свет очистит вас!', '', 28153),
(153383, 'ruRU', 'Мой народ запомнит тебя как защитника зандаларов. Спасибо тебе!', '', 28153),
(153382, 'ruRU', 'Свет уничтожит тебя!', '', 28153),
(153381, 'ruRU', 'Во имя Света!', '', 28153),
(153380, 'ruRU', 'Зло здесь повсюду... как удушающие лианы! Уничтожь его на корню и защити наши войска.', '', 28153),
(153379, 'ruRU', 'Никто не смеет угрожать моему народу. Сокруши врага!', '', 28153),
(153378, 'ruRU', 'Путь свободен, и мы снова можем выступать против зандаларов. Благодарю тебя.', '', 28153),
(153377, 'ruRU', 'Еще один враг повержен во славу империи Зандалари.', '', 28153),
(153376, 'ruRU', 'Это мерзкое чудовище угрожает нашим войскам. Избавь нас от него!', '', 28153),
(153375, 'ruRU', 'Я не смирюсь с этой угрозой на моей земле. Избавь меня от нее!', '', 28153),
(153374, 'ruRU', 'Запрыгивай на трицикл, как соберешься в путь.', '', 28153),
(153372, 'ruRU', '', 'Эти наги напуганы. Ими движет нечто большее, чем простая лояльность к королеве Азшаре.', 28153),
(153371, 'ruRU', '', 'Приветствую.', 28153),
(153370, 'ruRU', 'И что, и все? Ха! Как-то несерьезно!', '', 28153),
(153369, 'ruRU', 'Вот это веселье!', '', 28153),
(153368, 'ruRU', 'Больше ты сюда не сунешься.', '', 28153),
(153367, 'ruRU', 'Передавай привет духам предков!', '', 28153),
(153366, 'ruRU', 'Я этого так не оставлю!', '', 28153),
(153365, 'ruRU', 'Эх, размахнись, рука!', '', 28153),
(153364, 'ruRU', 'Ха-ха-ха! Вот это по-нашему!', '', 28153),
(153363, 'ruRU', 'А ну, отойди!', '', 28153),
(153362, 'ruRU', 'За Каз Модан!', '', 28153),
(153361, 'ruRU', 'Лови подарочек!', '', 28153),
(153360, 'ruRU', 'А это тебе!', '', 28153),
(153359, 'ruRU', 'Эй, лови!', '', 28153),
(153357, 'ruRU', 'Сейчас я вам устрою!', '', 28153),
(153351, 'ruRU', 'Магни, что Азерот хочет мне передать?', 'Магни, что Азерот хочет мне передать?', 28153),
(153350, 'ruRU', 'С гориллами покончено, и теперь можно сосредоточиться на Орде. Спасибо.', '', 28153),
(153349, 'ruRU', 'Впитав сущность каджа\'мита, эти гориллы невероятно поумнели. Нельзя позволить, чтобы они расселились за пределами этой теснины.', '', 28153),
(153348, 'ruRU', 'Обнаружен запуск ракеты \"АТОМЫЧ\"', 'Обнаружен запуск ракеты \"АТОМЫЧ\"', 28153),
(153347, 'ruRU', 'Орде явно не хватает мозгов. Брать наших в плен – это же надо додуматься! Спасибо тебе от имени всех освобожденных.', '', 28153),
(153346, 'ruRU', 'Мне не будет покоя, пока не вся моя команда в сборе.', 'Мне не будет покоя, пока не вся моя команда в сборе.', 28153),
(153345, 'ruRU', 'Теперь за нами фактор внезапности. Спасибо тебе!', '', 28153),
(153344, 'ruRU', 'С тех пор как мы заняли позицию в Зулдазаре, Орда следит за нами. Закрой ее глаза и заткни уши. Пусть знает, что Альянс не терпит шпионов!', '', 28153),
(153343, 'ruRU', 'Никогда больше не полезу в такие штуки без ключа!', 'Никогда больше не полезу в такие штуки без ключа!', 28153),
(153342, 'ruRU', 'Еще минута в этой штуке, и дело запахло бы керосином!', 'Еще минута в этой штуке, и дело запахло бы керосином!', 28153),
(153341, 'ruRU', 'И зачем Тургаден так долго держал нас в этих консервных банках? Уф!', 'И зачем Тургаден так долго держал нас в этих консервных банках? Уф!', 28153),
(153340, 'ruRU', 'Там было жарче, чем на Огненных Просторах!', 'Там было жарче, чем на Огненных Просторах!', 28153),
(153339, 'ruRU', 'Я отправлю гонца передать Змеевержцу, что у нас все под контролем. Спасибо тебе за помощь, $n.', '', 28153),
(153338, 'ruRU', 'Да ну, обычное дело.', '', 28153),
(153337, 'ruRU', 'Вот это было страшное зрелище!', '', 28153),
(153336, 'ruRU', 'Мы черпаем силу Огненных Просторов, но не боись, на этот зов чудовища не отвечают.', '', 28153),
(153335, 'ruRU', 'Хватит трясти бородой, Телин. Я не такой глупец, как тан-чародей Тауриссан.', '', 28153),
(153334, 'ruRU', 'Ты там поосторожнее с призывами, тан наковальни.', '', 28153),
(153333, 'ruRU', 'Отличный призыв, ребятки. Это существо подчиняется тебе, $n. Покажи ордынцам, что бывает, если встать на пути у клана Черного Железа!', '', 28153),
(153332, 'ruRU', '$C, положи немного шлака вот сюда, на нестабильную магму. И приготовься.', '', 28153),
(153331, 'ruRU', 'Битва за Стромгард началась!', '', 28153),
(153330, 'ruRU', '30 секунд до начала битвы за Стромгард.', '', 28153),
(153329, 'ruRU', 'Хорошо, не проблема.', '', 28153),
(153328, 'ruRU', 'Стой, так ключ у тебя?', '', 28153),
(153327, 'ruRU', 'Похоже, мои шаманы застряли в буровых установках. Я знал, что что-то забыл.', '', 28153),
(153326, 'ruRU', 'Уже неплохо. Чего еще не хватает?', '', 28153),
(153325, 'ruRU', 'Вы не представляете, какие силы противостоят вам.', '', 28153),
(153324, 'ruRU', '<Засунуть руку внутрь и вытащить что-нибудь более похожее на здание.>', '<Засунуть руку внутрь и вытащить что-нибудь более похожее на здание.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153323, 'ruRU', '<Засунуть руку внутрь и что-нибудь вытащить.>', '<Засунуть руку внутрь и что-нибудь вытащить.>', 28153),
(153322, 'ruRU', '<Перед вами червоточина. Видимо, с ее помощью вы должны как-то построить здание.>', '', 28153),
(153321, 'ruRU', 'Мое терпение лопнуло. Умрите!', '', 28153),
(153320, 'ruRU', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_CTHUN.BLP:20|t %s начинает использовать способность |cFFFF0000|Hspell:264382|h[Пронзающий взгляд]|h|r!', 'Вдалеке появляется проекция...', 28153),
(153319, 'ruRU', 'Море – наш дом. Но что-то нас туда не пускает. Надеюсь, ты с этим разберешься!', '', 28153),
(153318, 'ruRU', 'Ты собираешься встретиться с искателями, да? Серьезные ребята, с ними ты будешь в безопасности.', '', 28153),
(153317, 'ruRU', 'Корабли не возвращаются из плавания. Шторма появляются там, где их быть не должно. Народ боится выходить в море.', '', 28153),
(153316, 'ruRU', 'Ходят слухи, что на берегу творится что-то неладное.', '', 28153),
(153315, 'ruRU', 'Как скажете.', '', 28153),
(153314, 'ruRU', 'И... присмотрите за Джайной.', '', 28153),
(153313, 'ruRU', 'Закрепитесь на Кул-Тирасе. Сейчас это самое важное.', '', 28153),
(153312, 'ruRU', 'Возьмите один из кораблей 7-го легиона.', '', 28153),
(153311, 'ruRU', 'Хмф. Ни капельки.', '', 28153),
(153310, 'ruRU', 'Пусть море отвергнет тебя, как отвергаешь ты свой народ.', '', 28153),
(153309, 'ruRU', 'Тебя ждут лишь страдания и ненависть.', '', 28153),
(153308, 'ruRU', 'Шторм возрождается. Конец близок.', '', 28153),
(153307, 'ruRU', 'Отринь страх, ибо суд уже близок.', '', 28153),
(153306, 'ruRU', 'Генн... Вас не укачивает?', '', 28153),
(153305, 'ruRU', 'Услышь плач моего народа. Твое время пришло.', '', 28153),
(153304, 'ruRU', 'Тебе не искупить свои грехи.', '', 28153),
(153303, 'ruRU', 'Твоя душа взвешена и измерена.', '', 28153),
(153302, 'ruRU', 'Да пребудет твоя душа в вечной тоске.', '', 28153),
(153301, 'ruRU', '', 'Дай мне только добраться до оружия...', 28153),
(153300, 'ruRU', '', 'Убить меня они не смогли – и это была их первая ошибка.', 28153),
(153299, 'ruRU', '', 'У них хватило совести разрушить мою ферму и взять меня в плен. Это им просто так с рук не сойдет!', 28153),
(153298, 'ruRU', 'Я не уйду, пока мы не расправимся с этой угрозой!', 'Я не уйду, пока мы не расправимся с этой угрозой!', 28153),
(153297, 'ruRU', 'Они за все заплатят!', 'Они за все заплатят!', 28153),
(153296, 'ruRU', 'Ух, эти свинобразы у меня получат!', 'Ух, эти свинобразы у меня получат!', 28153),
(153295, 'ruRU', '', 'Заходи еще! Поторгуемся!', 28153),
(153294, 'ruRU', '', 'Наконец-то свобода! Я покажу этим грязным свиньям, что бывает, если поднять копыто на мою ферму!', 28153),
(153293, 'ruRU', 'О, кто тут у нас очухался?', '', 28153),
(153292, 'ruRU', 'Беги... беги... от дочери морей...', '', 28153),
(153291, 'ruRU', 'Держи это... от меня подальше. Единственное... в чем я хочу потонуть... это бутылка! *ик*', 'Держи это... от меня подальше. Единственное... в чем я хочу потонуть... это бутылка! *ик*', 28153),
(153290, 'ruRU', 'Прежде чем отправиться в четырехмесячное плавание, муж моей сестры подарил ей морской стебель, а на третий день он увял. Она была вне себя от горя, зато тут же начала экономить – надо же было детей прокормить. Хорошо, что сразу узнала.', 'Прежде чем отправиться в четырехмесячное плавание, муж моей сестры подарил ей морской стебель, а на третий день он увял. Она была вне себя от горя, зато тут же начала экономить – надо же было детей прокормить. Хорошо, что сразу узнала.', 28153),
(153289, 'ruRU', 'Наверху мы поставили койки, а в подвале можно сложить экипировку. \n\nНе слишком удобно, но все лучше, чем прозябать с ведьмами.', 'Наверху мы поставили койки, а в подвале можно сложить экипировку. Не слишком удобно, но все лучше, чем прозябать с ведьмами.', 28153),
(153288, 'ruRU', 'Некоторые моряки относятся к нему с опасением, и боятся искушать судьбу. А другие хотят, чтобы их родным не пришлось долго ждать плохих вестей. Я лично не могу винить ни тех, ни других.', 'Некоторые моряки относятся к нему с опасением, и боятся искушать судьбу. А другие хотят, чтобы их родным не пришлось долго ждать плохих вестей. Я лично не могу винить ни тех, ни других.', 28153),
(153287, 'ruRU', 'Помни: пока стоят деревья, мы тоже должны держаться. Мы не можем пожертвовать своими жизнями ради этого места.', '', 28153),
(153286, 'ruRU', 'Нам нужно найти своих. Возможно, вместе нам удастся исцелить раны Друствара.', '', 28153),
(153285, 'ruRU', '', 'Но!..', 28153),
(153284, 'ruRU', 'Мы взяли из этой рощи все самое важное, саженец. Если бы не нападение грибостражей, порча с юга дошла бы и до нас.', '', 28153),
(153283, 'ruRU', '', 'Что? Куда идти? Ясеневая роща – наш дом, Морвин. И вся она покрыта спорами. Мы не можем просто так уйти!', 28153),
(153282, 'ruRU', 'Отлично сработано, Амалия. А теперь нам пора идти.', '', 28153),
(153278, 'ruRU', 'Расскажи мне о морском стебле.', 'Расскажи мне о морском стебле.', 28153),
(153277, 'ruRU', 'Барабанный бой', 'Барабанный бой', 28153),
(153276, 'ruRU', '|cFF0000FF(Задание)|r Отправиться в Зулдазар.', '|cFF0000FF(Задание)|r Отправиться в Зулдазар.', 28153),
(153275, 'ruRU', 'Силы возвращаются ко мне!', '', 28153),
(153274, 'ruRU', 'Здесь все было тихо, пока не началась буря. $C, после этого другие искатели перестали возвращаться. Что там происходит?', '', 28153),
(153273, 'ruRU', 'Прими мою искреннюю благодарность и небольшую часть личного запаса. А теперь мне пора выдвигаться!', '', 28153),
(153272, 'ruRU', 'Подумать только, ну и история со мной приключилась. Будь лапушкой и помоги мне.', '', 28153),
(153271, 'ruRU', 'О, спасибо, это так мило с твоей стороны. Вот тебе за труды. Пока-пока!', 'О, спасибо, это так мило с твоей стороны. Вот тебе за труды. Пока-пока!', 28153),
(153270, 'ruRU', '', 'Эй, ты! Помоги мне, будь другом! Я тут совсем одна, обратиться не к кому, представляешь?', 28153),
(153269, 'ruRU', 'Весь свой азерит я тебе не дам, но вот, держи, сколько не жалко, и проваливай.', '', 28153),
(153268, 'ruRU', 'Так, ну-ка помоги мне с этой чертовщиной!', '', 28153),
(153267, 'ruRU', 'Слушайте, это всего лишь костюм! Видишь? На, потрогай!$b$bСкажи им, чтобы они меня выпустили! Ну пожалуйста! Я просто пошутил! Не было никакого вторжения Дробителя в Штормград!', 'Слушайте, это всего лишь костюм! Видишь? На, потрогай!$b$bСкажи им, чтобы они меня выпустили! Ну пожалуйста! Я просто пошутила! Не было никакого вторжения Дробителя в Штормград!', 28153),
(153266, 'ruRU', '', 'Пасиб! Тебе, по ходу, нужен мой азерит. И правильно, что уж тут.', 28153),
(153265, 'ruRU', '', 'Эй, ты! Помоги-ка мне, а?', 28153),
(153264, 'ruRU', '', 'Наверное, я заслужила это.', 28153),
(153263, 'ruRU', '', 'Придется это вытерпеть...', 28153),
(153262, 'ruRU', 'Она вернулась, чтобы убить нас!', '', 28153),
(153261, 'ruRU', 'Убийца!', 'Убийца!', 28153),
(153260, 'ruRU', 'Предательница!', 'Предательница!', 28153),
(153259, 'ruRU', 'Это же дочь морей!', '', 28153),
(153258, 'ruRU', '', 'Леди Джайна... это правда она?', 28153),
(153257, 'ruRU', '', 'Так, пойдем домой. Живо!', 28153),
(153256, 'ruRU', 'Мама, кто эта леди?', 'Мама, кто эта леди?', 28153),
(153255, 'ruRU', 'Эх, Гамлета... нашпиговали тебя трюфелями...', '', 28153),
(153254, 'ruRU', 'Моя голова... Что стало со свинками?!', '', 28153),
(153253, 'ruRU', 'Я всем расскажу о твоей сегодняшней победе. Так что... ты уж победи!', '', 28153),
(153252, 'ruRU', 'Вернитесь в Багровый лес!', 'Вернитесь в Багровый лес!', 28153),
(153250, 'ruRU', 'Отгоните гражданских, установите периметр!', '', 28153),
(153249, 'ruRU', '%s убегает.', '%s убегает.', 28153),
(153248, 'ruRU', '', 'Теперь я для них преступница.', 28153),
(153247, 'ruRU', '', 'Дисциплина стражи как всегда на высоте. Отец гордился бы ими.', 28153),
(153246, 'ruRU', 'Не торопи меня! Я стараюсь спасти твоего хозяина!', '', 28153),
(153245, 'ruRU', 'Эй, $n! Сюда!', 'Эй, $n! Сюда!', 28153),
(153244, 'ruRU', 'Вот я неудачник! Ехал в Дол\'вату, и тут мое животное заболело. Вот уж точно говорят, проблемы растут, как снежный ком.', '', 28153),
(153243, 'ruRU', 'Я Ралли!', 'Я Ралли!', 28153),
(153242, 'ruRU', 'Сколько же там ордынцев. Ты там всех не убивай, оставь на мою долю, ага?', 'Сколько же там ордынцев. Ты там всех не убивай, оставь на мою долю, ага?', 28153),
(153241, 'ruRU', 'Может, сначала помучим?', 'Может, сначала помучим?', 28153),
(153240, 'ruRU', 'Ты слышал приказ. Чужаков убивать.', 'Ты слышал приказ. Чужаков убивать.', 28153),
(153239, 'ruRU', '', 'Не отходи далеко. Нас могут заметить.', 28153),
(153238, 'ruRU', '', 'Соберись, $n.', 28153),
(153237, 'ruRU', '', 'Ты что, хочешь нас выдать?', 28153),
(153236, 'ruRU', 'Эй, Борис... По ходу, мы доворовались...', '', 28153),
(153235, 'ruRU', 'Держись подальше от моей птички!', '', 28153),
(153234, 'ruRU', 'Вот это другой разговор! Вы только посмотрите, сколько тут азерита!', '', 28153),
(153233, 'ruRU', 'Босс! Это ты!', '', 28153),
(153231, 'ruRU', 'С дороги! Мы ведем опасную преступницу.', '', 28153),
(153230, 'ruRU', 'Стоять! Зачем явились?', '', 28153),
(153229, 'ruRU', '', 'Погуляем по городу в другой раз.', 28153),
(153228, 'ruRU', 'Д-да заткнись ты.', '', 28153),
(153227, 'ruRU', 'Ой-ой, может, это сделала ВЕДЬМА?', '', 28153),
(153226, 'ruRU', 'Еще один твой разведчик, Галливикс. Мертвый.', '', 28153),
(153225, 'ruRU', 'Нам нужно пробиться к центру города и увести остальных горожан!', '', 28153),
(153224, 'ruRU', 'Б-берегитесь...', '', 28153),
(153223, 'ruRU', '', 'Мы почти на месте! Поспешите, герои!', 28153),
(153222, 'ruRU', '', 'Шевелитесь!', 28153),
(153220, 'ruRU', 'Герои, за мной! Собираемся в крепости! Приказ вождя!', '', 28153),
(153217, 'ruRU', '', 'Саурфанг! Куда он делся?', 28153),
(153216, 'ruRU', 'Будь осторожнее, на обрушенных полях по-прежнему опасно! Правая дорога приведет тебя к ветряной мельнице. На ней должно быть не так опасно. Сразу за мельницей находится ферма Дил.', '', 28153),
(153215, 'ruRU', '', 'Если умеешь драться, бежим вместе.', 28153),
(153214, 'ruRU', '', 'Здесь полно сетраков, а у меня зелья кончились. И до повозки далеко.', 28153),
(153213, 'ruRU', '', 'Эй, ты там дышишь еще? Оружие при себе есть?', 28153),
(153212, 'ruRU', '', 'Размечтались, змеюки!', 28153),
(153211, 'ruRU', 'Перенеси меня к входу.', 'Перенеси меня к входу.', 28153),
(153210, 'ruRU', 'Благодаря вашим усилиям аватара Сетралисс вновь полна сил.', 'Благодаря вашим усилиям аватара Сетралисс вновь полна сил.', 28153),
(153209, 'ruRU', 'Магни, отправь меня обратно в Зандалар.', 'Магни, отправь меня обратно в Зандалар.', 28153),
(153207, 'ruRU', 'Этот телепорт перенесет нас куда надо. Идем, скорее.', '', 28153),
(153206, 'ruRU', 'Победите всех оставшихся противников.', 'Победите всех оставшихся противников.', 28153),
(153205, 'ruRU', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|tАватара присоединяется к вам, |cFFFF0000|Hspell:269670|h[усиливая]|h|r вас, чтобы вы могли закончить бой!', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|tАватара присоединяется к вам, |cFFFF0000|Hspell:269670|h[усиливая]|h|r вас, чтобы вы могли закончить бой!', 28153),
(153204, 'ruRU', '<Перед вами аватара Сетралисс. Она еще жива, но манипуляции троллей ее сильно ослабили. Вокруг вас пробуждаются древние защитные устройства...>', '<Перед вами аватара Сетралисс. Она еще жива, но манипуляции троллей ее сильно ослабили. Вокруг вас пробуждаются древние защитные устройства...>', 28153),
(153203, 'ruRU', '|cffffff00+$1i ед. древесины|r', '|cffffff00+$1i ед. древесины|r', 28153),
(153202, 'ruRU', 'Слышали приказ принцессы? Огонь!', '', 28153),
(153201, 'ruRU', '', 'Смотрите! Щит начал слабеть!', 28153),
(153199, 'ruRU', 'Только без паники! Простите за неожиданное появление. Я Магни Бронзобород, вестник Азерот.', '', 28153),
(153198, 'ruRU', '', 'А, вот ты где, $n. Идем, надо обсудить дальнейшие планы.', 28153),
(153197, 'ruRU', 'А, вот ты где, $n. Нам бы с тобой переговорить.', '', 28153),
(153196, 'ruRU', '[ВИР - Аудиенция с Кэтрин - Джайна доверяет свою судьбу Кэтрин. Леди Эшвейн считает, что Джайна предательница, и Кэтрин распоряжается, чтобы Джайна предстала перед лицом правосудия. \"Для меня она уже мертва\". Игрока арестовывают.]', '[ВИР - Аудиенция с Кэтрин - Джайна доверяет свою судьбу Кэтрин. Леди Эшвейн считает, что Джайна предательница, и Кэтрин распоряжается, чтобы Джайна предстала перед лицом правосудия. \"Для меня она уже мертва\".]', 28153),
(153195, 'ruRU', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t На вас нацелено заклинание |cFFFF0000|Hspell:265212|h[Вызревание]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t На вас нацелено заклинание |cFFFF0000|Hspell:265212|h[Вызревание]|h|r!', 28153),
(153194, 'ruRU', 'Мы вернем тебя к жизни!', 'Мы вернем тебя к жизни!', 28153),
(153193, 'ruRU', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t Вектис начинает применять способность |cFFFF0000|Hspell:265217|h[Разжижение]|h|r!', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t Вектис начинает применять способность |cFFFF0000|Hspell:265217|h[Разжижение]|h|r!', 28153),
(153192, 'ruRU', 'Не обращай на Галливикса внимания. Мы направляемся в Друствар, чтобы разведать позиции врага. Источники дохода – это второстепенная задача.', '', 28153),
(153191, 'ruRU', 'Теперь... только тишина.', '', 28153),
(153190, 'ruRU', 'О, я умираю...', '', 28153),
(153189, 'ruRU', 'Убедись в том, что Эйтригг и капитан готовы. Пора делать деньги!', '', 28153),
(153188, 'ruRU', 'Я... сокрушен...', '', 28153),
(153187, 'ruRU', 'Отныне и впредь... Я больше не скажу ни слова.', '', 28153),
(153186, 'ruRU', 'Стой, достаточно!', '', 28153),
(153185, 'ruRU', 'Чудовище, убийца!', '', 28153),
(153184, 'ruRU', 'О, я убит!', '', 28153),
(153183, 'ruRU', 'Теперь пусть сражается мой дух, я больше... не могу.', '', 28153),
(153182, 'ruRU', '', 'Нет. Ты больше не навредишь моему народу. Я прекращу это безумие!', 28153),
(153180, 'ruRU', '', 'Верно, принцесса!', 28153),
(153177, 'ruRU', 'Порчу сдерживают три печати.', '', 28153),
(153174, 'ruRU', '[Отличная кат-сцена.]', '[Отличная кат-сцена.]', 28153),
(153173, 'ruRU', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t Вектис применяет заклинание |cFFFF0000|Hspell:266948|h[Чумная бомба]|h|r!', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t Вектис применяет заклинание |cFFFF0000|Hspell:266948|h[Чумная бомба]|h|r!', 28153),
(153172, 'ruRU', '', 'Древний бог?! Вот почему тролли крови нападают на город...', 28153),
(153171, 'ruRU', 'Данные получены. Источник порчи – Древний бог, заключенный в Назмире.', '', 28153),
(153169, 'ruRU', '...и четыре целых, одна десятая литра текилы!', '...и четыре целых, одна десятая литра текилы!', 28153),
(153168, 'ruRU', '|cFF0000FF(Задание)|r Отправиться в Друствар.', '|cFF0000FF(Задание)|r Отправиться в Друствар.', 28153),
(153167, 'ruRU', '', '\"Вой банши\" – один из лучших кораблей Темной Госпожи. Может, он и неказист, но очень крепок и вооружен по последнему слову техники.\n\nНу и капитан у него что надо.', 28153),
(153166, 'ruRU', 'Да, я готов отправиться в Друствар.', 'Да, я готова отправиться в Друствар.', 28153),
(153165, 'ruRU', 'Не позволяй этому гоблину запудрить тебе мозги, $n. Наша задача – собрать важные данные об Альянсе, а не захапать как можно больше азерита.\n\nНу что, в путь?', '', 28153),
(153164, 'ruRU', 'Не давай Торговому принцу сбить тебя с пути. Наша основная задача – сбор информации... а не нажива.', '', 28153),
(153163, 'ruRU', 'Говорят, посреди океана нас ждет просто куча азерита. Нам надо его только собрать. Этим-то ты и займешься.\n\nТолько чур, если тебя убьют, я заберу твою шляпу! Ха-ха!', '', 28153),
(153162, 'ruRU', 'Продолжайте питать аватару Сетралисс и расправляться с незваными гостями.', 'Продолжайте питать аватару Сетралисс и расправляться с незваными гостями.', 28153),
(153161, 'ruRU', 'Хорошо, $n. Мы должны тщательно оберегать храм от джунглевых пауков.', '', 28153),
(153160, 'ruRU', 'Руины храма заполонили джунглевые ткачи. Истреби их и вызволи моих последователей из паутины.', '', 28153),
(153159, 'ruRU', 'Полностью восстановите здоровье аватаре.', 'Полностью восстановите здоровье аватаре.', 28153),
(153158, 'ruRU', 'Проклятые пауки!', '', 28153),
(153157, 'ruRU', 'Спасибо, $n! Я обязан тебе жизнью.', '', 28153),
(153156, 'ruRU', 'Я снова могу дышать! Спасибо!', '', 28153),
(153155, 'ruRU', 'Эти пауки жрут все подряд!', '', 28153),
(153154, 'ruRU', 'Спасибо! Еще бы чуть-чуть...', '', 28153),
(153153, 'ruRU', 'Я уж думал, мне конец!', '', 28153),
(153152, 'ruRU', 'Что тебе от нас нужно?', 'Что тебе от нас нужно?', 28153),
(153151, 'ruRU', 'Нет, пожалуйста...', 'Нет, пожалуйста...', 28153),
(153150, 'ruRU', '', 'Тогда в путь! $n, мы поскачем вперед и попробуем найти мастера Эштона. Встретимся в Багровом лесу!', 28153),
(153149, 'ruRU', 'Мои кости! Больно!', 'Больно! Мои кости!', 28153),
(153148, 'ruRU', 'Как же я соскучился по этому зрелищу.', 'Как же я соскучилась по этому зрелищу.', 28153),
(153147, 'ruRU', 'Мне с тобой наскучило. Давай-ка сделаем тебя... поинтереснее.', 'Мне с тобой наскучило. Давай-ка сделаем тебя... поинтереснее.', 28153),
(153146, 'ruRU', 'Ну как, тебе больно?', 'Ну как, тебе больно?', 28153),
(153145, 'ruRU', 'Думаю, да.', '', 28153),
(153144, 'ruRU', '', 'Мартен, ты выдержишь путешествие?', 28153),
(153143, 'ruRU', 'Город в надежных руках. Может, объясните, что здесь происходит?', '', 28153),
(153142, 'ruRU', 'Конечно! Не знаю, зачем тебе понадобилась моя помощь, но ты ее определенно получишь!\n\nОднако, возможно, придется немного подождать. Наверняка в городе царит хаос.', '', 28153),
(153141, 'ruRU', 'Нужно уходить отсюда!', 'Нужно уходить отсюда!', 28153),
(153140, 'ruRU', 'Они, опять они!', 'Они, опять они!', 28153),
(153139, 'ruRU', 'Если б не ты, я бы погиб...', 'Если б не ты, я бы погибла...', 28153),
(153138, 'ruRU', 'Ордынцы! Откуда здесь ордынцы?!', 'Откуда здесь ордынцы?!', 28153),
(153137, 'ruRU', 'Якоря встали, командир!', 'Якоря встали, командир!', 28153),
(153136, 'ruRU', 'Я заберу тебя оттуда быстрее, чем летают чайки. Просто дай знать, как приготовишься.', '', 28153),
(153135, 'ruRU', 'Вы ищете Эштона? Следуйте за мной. Я не знаю, где он, зато видел его ученика.', '', 28153),
(153134, 'ruRU', 'Ого... Это блюдо не для слабых духом. Или брюхом.', '', 28153),
(153133, 'ruRU', 'Я не раз слышал о заморском пустынном деликатесе из крыльев канюка и жал скорпидов. Хочу поэкспериментировать и приготовить собственную версию.', '', 28153),
(153132, 'ruRU', 'Так держать, рулевой.', 'Так держать, рулевой.', 28153),
(153131, 'ruRU', 'Идиот! В ДРУГУЮ СТОРОНУ!', 'Идиот! В ДРУГУЮ СТОРОНУ!', 28153),
(153130, 'ruRU', 'Нечистые не допускаются в чертоги мертвых.', '', 28153),
(153129, 'ruRU', 'Вы не можете продолжить путь.', '', 28153),
(153128, 'ruRU', 'Доступ запрещен.', '', 28153),
(153127, 'ruRU', 'Пока.', '', 28153),
(153126, 'ruRU', 'Привет.', '', 28153),
(153125, 'ruRU', '', 'Я плохо вас учила.', 28153),
(153124, 'ruRU', '', 'Перемена.', 28153),
(153123, 'ruRU', '', 'Вы все... свободны.', 28153),
(153122, 'ruRU', '', 'Начинаем урок!', 28153),
(153121, 'ruRU', '', 'Пора научить тебя принципу трех \"Р\" – руны, ритуалы, реликвии!', 28153),
(153120, 'ruRU', '', 'Тебе следует преподать урок!', 28153),
(153119, 'ruRU', 'Кто теперь будет присматривать за погребами?', '', 28153),
(153118, 'ruRU', 'Эта партия... испорчена.', '', 28153),
(153117, 'ruRU', 'Не трогай наши запасы!', '', 28153),
(153116, 'ruRU', 'Эта коллекция только для гостей!', '', 28153),
(153115, 'ruRU', 'Этих семян хватит надолго. Ну... если я не стрескаю их прямо сейчас.', '', 28153),
(153114, 'ruRU', 'Местные существа удивительно живучи. У плеточников крайне прочные – и вкусные! – семена. Собери их, только берегись шипов!', '', 28153),
(153113, 'ruRU', '...Мне нравится ход твоих мыслей, Уолт.', '', 28153),
(153112, 'ruRU', 'Или... Нам уже заплатили, так почему бы не сказать в Хазерфорде, что на нас напали и отобрали весь мед, – и выпить его самим?', '', 28153),
(153111, 'ruRU', 'Так... Кажется, теперь мы в безопасности. Давай доставим эти бочки в Хазерфорд.', '', 28153),
(153110, 'ruRU', 'Я постараюсь выяснить, где может быть Джеймс, а ты пока вызови корабль. Я не допущу, чтобы мои солдаты остались в плену у этих подлых ублюдков.', 'Я постараюсь выяснить, где может быть Джеймс, а ты пока вызови корабль. Я не допущу, чтобы мои солдаты остались в плену у этих подлых ублюдков.', 28153),
(153109, 'ruRU', 'Из этой твари мед буквально течет!', '', 28153),
(153108, 'ruRU', 'Иди сюда, глупая тварь!', '', 28153),
(153107, 'ruRU', 'Ну... Я в полной боевой готовности. Ну что, посмотрим, сколько в нас влезет!', '', 28153),
(153106, 'ruRU', 'Приступим!', 'Приступим!', 28153),
(153105, 'ruRU', '$C, другие свирепые звери могут появиться в любую секунду. Защищай мед всеми силами!', '', 28153),
(153103, 'ruRU', 'Выше нос, Брэдфорд! Мы не позволим им взять верх над нами!', '', 28153),
(153102, 'ruRU', 'Так, Уолт, это конец. Не знаю, сколько еще мы сможем продержаться против этих тварей.', '', 28153),
(153101, 'ruRU', '%s обращает полностью заряженную азеритовую пушку к осадной башне.', '', 28153),
(153100, 'ruRU', '$n! Нужна твоя помощь, скорее!', '$n! Нужна твоя помощь, скорее!', 28153),
(153099, 'ruRU', 'Да чтоб тебя, Леонард, я не разрешал тебе уходить!', 'Да чтоб тебя, Леонард, я не разрешала тебе уходить!', 28153),
(153098, 'ruRU', 'Все остальные пойдут со мной – мы их с фланга обойдем.', 'Все остальные пойдут со мной – мы их с фланга обойдем.', 28153),
(153097, 'ruRU', 'Какие изумительные маленькие скитальцы! Сколько историй они могли бы рассказать!', '', 28153),
(153096, 'ruRU', 'Вообще-то шлепокряды живут всего пару месяцев. Но местные чем-то отличаются от обычных. Налови мне мотыльков, а я их изучу. Но осторожно – это очень хрупкие создания.', '', 28153),
(153093, 'ruRU', '', 'Кто теперь будет за всем здесь присматривать?', 28153),
(153092, 'ruRU', '', 'Я возвращаюсь к земле.', 28153),
(153091, 'ruRU', '', 'Я тебя на удобрения пущу.', 28153),
(153090, 'ruRU', '', 'Скоро ты пожнешь плоды своих стараний!', 28153),
(153089, 'ruRU', '', 'В моем саду чужаки!', 28153),
(153088, 'ruRU', '', 'На мелкие кусочки.', 28153),
(153087, 'ruRU', '', 'Мой план... раскрыт.', 28153),
(153086, 'ruRU', '', 'Мое полотно предрекает тебе гибель!', 28153),
(153085, 'ruRU', '', 'Конец близок!', 28153),
(153084, 'ruRU', '', 'Я вплету ваши души в свое полотно!', 28153),
(153083, 'ruRU', 'Отличная получилась охота.', '', 28153),
(153082, 'ruRU', 'Какая свирепость.', '', 28153),
(153081, 'ruRU', 'Никогда не думал... что сам стану трофеем.', '', 28153),
(153080, 'ruRU', 'Время нанести удар!', '', 28153),
(153079, 'ruRU', 'Из вас получатся отличные трофеи для моей коллекции!', '', 28153),
(153078, 'ruRU', 'Охота началась!', '', 28153),
(153077, 'ruRU', 'О, свежее мясо для гриля!', '', 28153),
(153076, 'ruRU', 'Обед готов!', '', 28153),
(153075, 'ruRU', 'Святилище нужно открыть снова. Пришло время искупления!', '', 28153),
(153074, 'ruRU', 'Тьма не преградит нам путь.', '', 28153),
(153073, 'ruRU', 'Мы не забудем подвиг жуков, героически пожертвовавших собой во имя спасения Костяного ущелья от ужасного Ракатаки!', '', 28153),
(153072, 'ruRU', 'Знаешь, мы убиваем и за меньшее.', '', 28153),
(153071, 'ruRU', 'Кажется, от жары у тебя испарились чувство такта и дисциплина.', '', 28153),
(153070, 'ruRU', 'Все на что-нибудь сгодится, даже ты.', '', 28153),
(153069, 'ruRU', 'Пустыня не щадит расточительных.', '', 28153),
(153068, 'ruRU', 'Пески укажут нам путь.', '', 28153),
(153067, 'ruRU', 'Куда песок – туда и мы.', '', 28153),
(153066, 'ruRU', 'В пустыне есть все.', '', 28153),
(153065, 'ruRU', 'Выживать в пустыне – значит находить пользу там, где другие не смогли.', '', 28153),
(153064, 'ruRU', 'Бесполезных вещей не бывает!', '', 28153),
(153063, 'ruRU', 'Говори, как есть.', '', 28153),
(153062, 'ruRU', 'Привет.', '', 28153),
(153061, 'ruRU', 'Что там у тебя?', '', 28153),
(153060, 'ruRU', 'Хочешь что-нибудь купить?', '', 28153),
(153059, 'ruRU', 'Тебе что-нибудь нужно?', '', 28153),
(153058, 'ruRU', '', 'Зандалар выстоит.', 28153),
(153057, 'ruRU', '', 'Смотри под ноги.', 28153),
(153056, 'ruRU', '', 'Никто не заслуживает смерти в песках.', 28153),
(153055, 'ruRU', '', 'Чем могу помочь?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153054, 'ruRU', '', 'Говори быстро.', 28153),
(153053, 'ruRU', '', 'Слушаю.', 28153),
(153052, 'ruRU', '', 'Да?', 28153),
(153051, 'ruRU', 'Мы никогда не сдадимся.', 'Мы никогда не сдадимся.', 28153),
(153050, 'ruRU', 'Империя отступников падет.', 'Империя отступников падет.', 28153),
(153049, 'ruRU', 'Сетралисс спасет нас.', 'Сетралисс спасет нас.', 28153),
(153048, 'ruRU', 'Кортек начал эту войну.', 'Кортек начал эту войну.', 28153),
(153047, 'ruRU', 'Мы должны быть сильными.', 'Мы должны быть сильными.', 28153),
(153046, 'ruRU', 'Ты хочешь нам помочь?', 'Ты хочешь нам помочь?', 28153),
(153045, 'ruRU', 'Король Ракатака терроризирует Костяное ущелье! Драться с ним бесполезно, а вот закормить до смерти можно. Король самоубийственно прожорлив.', '', 28153),
(153044, 'ruRU', 'Знаешь, мы убиваем и за меньшее.', 'Знаешь, мы убиваем и за меньшее.', 28153),
(153043, 'ruRU', 'Кажется, от жары у тебя испарились чувство такта и дисциплина.', 'Кажется, от жары у тебя испарились чувство такта и дисциплина.', 28153),
(153042, 'ruRU', 'Все на что-нибудь сгодится, даже ты.', 'Все на что-нибудь сгодится, даже ты.', 28153),
(153041, 'ruRU', 'Главное – прыткость и смекалка.', 'Главное – прыткость и смекалка.', 28153),
(153040, 'ruRU', 'Хочешь выжить – умей вертеться.', 'Хочешь выжить – умей вертеться.', 28153),
(153039, 'ruRU', 'Бесполезных вещей не бывает!', 'Бесполезных вещей не бывает!', 28153),
(153038, 'ruRU', 'В пустыне все есть.', 'В пустыне все есть.', 28153),
(153037, 'ruRU', 'Береги себя. За тебя этого никто не сделает.', 'Береги себя. За тебя этого никто не сделает.', 28153),
(153036, 'ruRU', 'Ты там смотри не умри.', 'Ты там смотри не умри.', 28153),
(153035, 'ruRU', 'Что у тебя есть для меня?', 'Что у тебя есть для меня?', 28153),
(153034, 'ruRU', 'Тебе что-нибудь нужно?', 'Тебе что-нибудь нужно?', 28153),
(153033, 'ruRU', 'Хочешь что-нибудь купить? Продать?', 'Хочешь что-нибудь купить? Продать?', 28153),
(153032, 'ruRU', 'Хей-хей.', 'Хей-хей.', 28153),
(153031, 'ruRU', 'Есть что для меня?', 'Есть что для меня?', 28153),
(153030, 'ruRU', 'Принеси мне что-нибудь из своего следующего приключения!', 'Принеси мне что-нибудь из своего следующего приключения!', 28153),
(153029, 'ruRU', 'Мы теперь друзья, да?', 'Мы теперь друзья, да?', 28153),
(153028, 'ruRU', 'Спасибо за беседу.', 'Спасибо за беседу.', 28153),
(153027, 'ruRU', 'Ты сейчас занимаешься чем-то очень важным, да? Это так круто!', 'Ты сейчас занимаешься чем-то очень важным, да? Это так круто!', 28153),
(153026, 'ruRU', 'Тебе не доводилось специально есть песок?', 'Тебе не доводилось специально есть песок?', 28153),
(153025, 'ruRU', 'Если ты умрешь, можно я заберу твои вещи?', 'Если ты умрешь, можно я заберу твои вещи?', 28153),
(153024, 'ruRU', 'Мы никогда не сдадимся.', '', 28153),
(153023, 'ruRU', 'Империя отступников падет.', '', 28153),
(153022, 'ruRU', 'Сетралисс спасет нас.', '', 28153),
(153021, 'ruRU', 'Кортек начал эту войну.', '', 28153),
(153020, 'ruRU', 'Мы должны быть сильными.', '', 28153),
(153019, 'ruRU', 'Ты хочешь нам помочь?', '', 28153),
(153018, 'ruRU', 'Мы исполняем свой долг.', '', 28153),
(153017, 'ruRU', 'Сетралисс – наше спасение.', '', 28153),
(153016, 'ruRU', 'Отступники не получат наш храм.', '', 28153),
(153015, 'ruRU', 'Кортек начал эту войну.', '', 28153),
(153014, 'ruRU', 'Мы должны быть сильными.', '', 28153),
(153013, 'ruRU', 'Ты хочешь нам помочь?', '', 28153),
(153012, 'ruRU', '', 'Зря мы тебя спасли... Эй, ну я же пошутила!..', 28153),
(153011, 'ruRU', '', 'Ты опять? Серьезно?!', 28153),
(153010, 'ruRU', '', 'Может, хватит уже?', 28153),
(153009, 'ruRU', '', 'Что ты делаешь?', 28153),
(153008, 'ruRU', '', 'Ты же вернешься, правда?', 28153),
(153007, 'ruRU', '', 'Только смотри не умри!', 28153),
(153006, 'ruRU', '', 'В одиночку странствовать опасно.', 28153),
(153005, 'ruRU', '', 'Ты нравишься Долли. Точно нравишься.', 28153),
(153004, 'ruRU', '', 'Никто не знает эти дюны лучше, чем я.', 28153),
(153003, 'ruRU', '', 'Привет!', 28153),
(153002, 'ruRU', '', 'Я могу помочь!', 28153),
(153001, 'ruRU', '', 'Наш город выстоит.', 28153),
(153000, 'ruRU', '', 'Смотри под ноги.', 28153),
(152999, 'ruRU', '', 'Я поклялась защищать королевскую семью.', 28153),
(152998, 'ruRU', '', 'Мы все переживем.', 28153),
(152997, 'ruRU', '', 'Говори быстро.', 28153),
(152996, 'ruRU', '', 'Да?', 28153),
(152995, 'ruRU', '', 'Слушаю.', 28153),
(152994, 'ruRU', 'Пусть мои грехи утонут в песках.', '', 28153),
(152993, 'ruRU', 'В пустыне всегда будет опасно.', '', 28153),
(152992, 'ruRU', 'Не все можно изменить.', '', 28153),
(152991, 'ruRU', 'Чего тебе?', '', 28153),
(152990, 'ruRU', 'Помогу, чем смогу.', '', 28153),
(152989, 'ruRU', 'Я заслужил свою судьбу.', '', 28153),
(152988, 'ruRU', 'Уходи, пока можешь.', '', 28153),
(152987, 'ruRU', 'Я слежу за тобой.', '', 28153),
(152986, 'ruRU', 'Не расслабляйся.', '', 28153),
(152985, 'ruRU', 'Тебе здесь не место!', '', 28153),
(152984, 'ruRU', 'У меня нет на тебя времени.', '', 28153),
(152983, 'ruRU', 'Чего тебе надо?', '', 28153),
(152982, 'ruRU', 'Следуй за бурей.', '', 28153),
(152981, 'ruRU', 'Не бойся бури.', '', 28153),
(152980, 'ruRU', 'После бури всегда выходит солнце.', '', 28153),
(152979, 'ruRU', 'Буря зовет.', '', 28153),
(152978, 'ruRU', 'Здесь всем рады.', '', 28153),
(152977, 'ruRU', 'Буря – это я.', '', 28153),
(152976, 'ruRU', 'Что привело тебя сюда?', '', 28153),
(152975, 'ruRU', 'Пусть начнется пиршество!', '', 28153),
(152973, 'ruRU', '', 'Мне бы не помешал новый шлем...', 28153),
(152972, 'ruRU', '', 'Ты напоминаешь мне одного сетрака. Он меня тоже тыкнул. Один раз.', 28153),
(152971, 'ruRU', '', '', 28153),
(152970, 'ruRU', '', 'Попутного ветра... и надежных клинков.', 28153),
(152969, 'ruRU', '', 'Заставь их бояться.', 28153),
(152968, 'ruRU', '', 'Оставь и мне пару сетраков.', 28153),
(152967, 'ruRU', '', 'Никогда не сдавайся.', 28153),
(152966, 'ruRU', '', 'Скажи, сколько сетраков у тебя на счету?', 28153),
(152965, 'ruRU', '', 'Хороший день для битвы. Хотя для битвы любой день хорош.', 28153),
(152964, 'ruRU', '', 'Вульперы сильнее, чем кажутся.', 28153),
(152963, 'ruRU', '', 'Мой народ будет свободным.', 28153),
(152962, 'ruRU', '', 'Я готова сражаться.', 28153),
(152961, 'ruRU', 'Жизнь за короля.', '', 28153),
(152960, 'ruRU', 'Держи оружие наготове.', '', 28153),
(152959, 'ruRU', 'Да пребудут с тобой лоа.', '', 28153),
(152958, 'ruRU', 'Зандалар не падет.', '', 28153),
(152957, 'ruRU', 'Я всегда смотрю в лицо опасности.', '', 28153),
(152956, 'ruRU', 'Наши враги падут.', '', 28153),
(152955, 'ruRU', '', 'Ну разумеется.', 28153),
(152954, 'ruRU', 'Мы не подведем, королева.', '', 28153),
(152953, 'ruRU', '', 'Возьметесь за это дело?', 28153),
(152952, 'ruRU', '', 'Альянс удерживает политическую узницу, которая способна изменить ход войны. Проникните в Штормград и освободите ее.', 28153),
(152951, 'ruRU', '', 'Я хочу отнять у юного короля то, что ему не принадлежит.', 28153),
(152950, 'ruRU', '', 'Сейчас Орде нужны сильные союзники.', 28153),
(152949, 'ruRU', '', 'Но поверьте, я крайне осмотрительна.', 28153),
(152948, 'ruRU', '', 'В Орде бытует мнение, что некоторые из моих поступков были... необдуманны.', 28153),
(152947, 'ruRU', '', 'Мне понадобится помощь кого-то, кому я могу доверять.', 28153),
(152946, 'ruRU', '', 'А, вот и ты. Я уже начала беспокоиться.', 28153),
(152945, 'ruRU', 'Орде.', '', 28153),
(152944, 'ruRU', 'Мы храним верность...', '', 28153),
(152943, 'ruRU', 'Возможно, моя королева сомневается в верности этих советников.', '', 28153),
(152942, 'ruRU', 'Как нам помогать вождю, если вождь не доверяет советникам?', '', 28153),
(152941, 'ruRU', 'Это тебя не касается.', '', 28153),
(152940, 'ruRU', 'Тебя она тоже призвала?', '', 28153),
(152939, 'ruRU', 'Даже я ничего о нем не знаю.', '', 28153),
(152938, 'ruRU', 'Вождь желает дать тебе задание огромной важности... и секретности.', '', 28153),
(152937, 'ruRU', 'Скажи друзьям, пусть приходят в \"Золотой клык\".', '', 28153),
(152936, 'ruRU', 'Не забудь оставить отзыв.', '', 28153),
(152935, 'ruRU', 'Не умирай там.', '', 28153),
(152934, 'ruRU', 'Эй, бананы есть?', '', 28153),
(152933, 'ruRU', 'Мы в \"Золотом клыке\" – одна семья.', '', 28153),
(152932, 'ruRU', 'Добро пожаловать в таверну \"Золотой клык\"!', '', 28153),
(152931, 'ruRU', 'Мятеж или рея.', '', 28153),
(152930, 'ruRU', 'Будь примером для команды.', '', 28153),
(152929, 'ruRU', 'Пучина коварна.', '', 28153),
(152928, 'ruRU', 'В тот день в Тераморе она потеряла не только мужа, но и дочь.', '', 28153),
(152927, 'ruRU', 'Хватит языком трепать! А то скоро все уже будут знать.', 'Хватит языком трепать! А то скоро все уже будут знать.', 28153),
(152926, 'ruRU', 'Тихо! Тут есть кое-что хорошее.', 'Тихо! Тут есть кое-что хорошее.', 28153),
(152925, 'ruRU', 'Тсс! Мы же не хотим, чтобы нас услышали любопытные.', 'Тсс! Мы же не хотим, чтобы нас услышали любопытные.', 28153),
(152924, 'ruRU', 'Живым не место в Зем\'лане.', '', 28153),
(152923, 'ruRU', 'Ищешь команду?', '', 28153),
(152921, 'ruRU', 'Здорово!', '', 28153),
(152920, 'ruRU', 'На Кэтрин столько всего свалилось. А возвращение Джайны стало последней каплей.', '', 28153),
(152918, 'ruRU', '', 'Мы должны вновь объединить дома под знаменем Праудмуров и разыскать наши корабли. Иначе Кул-Тирас развалится еще до начала войны.', 28153),
(152917, 'ruRU', 'Сумеречный Молот истребил весь мой клан. Я выжил лишь потому, что мой брат Киланд посадил меня на грифона и отослал прочь. Он спас мне жизнь.\n\nЯ почти весь мир объездил, пока не решил осесть в Кул-Тирасе. Местные охотились на грифонов ради мяса и шкур. Я показал им, что грифоны могут приносить пользу иначе. Так они стали новым поколением наездников на грифонах.\n\nНе думаю, что когда-нибудь вернусь домой. Теперь мой клан здесь.', '', 28153),
(152916, 'ruRU', 'Отвези меня обратно в Зул\'джан.', 'Отвези меня обратно в Зул\'джан.', 28153),
(152915, 'ruRU', 'Распиливание', 'Распиливание', 28153),
(152914, 'ruRU', 'Что привело сюда дворфа из клана Громового Молота?', 'Что привело сюда дворфа из клана Громового Молота?', 28153),
(152913, 'ruRU', 'Сегодня мы разбогатеем.', 'Сегодня мы разбогатеем.', 28153),
(152912, 'ruRU', 'Эти тупицы не видят, сколько всего ценного валяется у них под ногами.', 'Эти тупицы не видят, сколько всего ценного валяется у них под ногами.', 28153),
(152911, 'ruRU', 'Я знаю кое-кого в Луносвете – он хорошо заплатит за эти реликвии.', 'Я знаю кое-кого в Луносвете – он хорошо заплатит за эти реликвии.', 28153),
(152910, 'ruRU', 'Вот этим вещам точно в музее не место.', '', 28153),
(152907, 'ruRU', 'Много в Назмире разной пакости... Но здесь особенно погано. Не зевай по сторонам.', '', 28153),
(152906, 'ruRU', 'Вижу, Хезрел занят делом! Но что ему тут нужно?', '', 28153),
(152905, 'ruRU', 'Мы думали, Хезрел поможет нам в бою, но он ушел по своим делам. Что этот голем задумал?', '', 28153),
(152900, 'ruRU', 'Руки прочь от моих сокровищ...', 'Я все равно вернусь за тобой...', 28153),
(152899, 'ruRU', 'Эта земля проклята... и мы вместе с ней...', 'Проклятие... не даст нам умереть...', 28153),
(152898, 'ruRU', 'Я ничего не чувствую...', 'Сухопутная крыса!', 28153),
(152897, 'ruRU', 'Я доложу об этом... капитану...', 'Ты ответишь... перед королем пиратов...', 28153),
(152896, 'ruRU', 'Давай отправимся в путь и встретимся с хранителем титанов Хезрелом.', 'Давай отправимся в путь и встретимся с хранителем титанов Хезрелом.', 28153),
(152895, 'ruRU', '', 'Я должна обо всем рассказать отцу. Мы одержали великую победу, но война с троллями крови еще не окончена.', 28153),
(152894, 'ruRU', '', 'Я никогда не забуду всего, что Орда для нас сделала. Без вашей помощи у нас бы ничего не вышло.', 28153),
(152893, 'ruRU', '', 'Приказывайте!', 28153),
(152892, 'ruRU', '', 'Пещера рушится! Бежим!', 28153),
(152891, 'ruRU', 'Даже если вы не умрете здесь, мои вассалы разорвут вас в клочья. До моей победы вам не дожить.', '', 28153),
(152890, 'ruRU', '', 'Я заберу вас с собой!', 28153),
(152889, 'ruRU', '', 'Еще немного!', 28153),
(152888, 'ruRU', '', 'Давай устроим взрыв!', 28153),
(152887, 'ruRU', '', 'Ну что, обнимемся?', 28153),
(152886, 'ruRU', 'За мной, быстрее! Не отставайте!', 'За мной, быстрее! Не отставайте!', 28153),
(152885, 'ruRU', '|TInterface\\Icons\\Spell_shadow_mindflay.blp:20|t|cFFFF0000|Hspell:269131|h[Древний подчинитель разума]|h|r поселяется в теле |cFFFF0000|3-1($n)|r!', '', 28153),
(152884, 'ruRU', 'Герои Третьего флота! Немедленно отправляйтесь к королю Седогриву!', 'Герои Третьего флота! Немедленно отправляйтесь к королю Седогриву!', 28153),
(152883, 'ruRU', 'А, не, все нормально. Это эль. Да, эль.', '', 28153),
(152882, 'ruRU', '', '.', 28153),
(152881, 'ruRU', '', 'Наши войска пока сдерживают троллей крови, но долго они не выстоят. Нужно покончить с этим, и побыстрее.', 28153),
(152880, 'ruRU', '', '.', 28153),
(152879, 'ruRU', '', 'Но вот уже несколько месяцев как от флота ничего не слышно! А жрецы удалились в монастыри и не торопятся его искать.', 28153),
(152878, 'ruRU', '', 'Дом Уэйкрестов веками поддерживал дружбу с Праудмурами, но их представитель почему-то не явился на последнее собрание совета.', 28153),
(152877, 'ruRU', 'Вернись, моя прелесть!', '', 28153),
(152876, 'ruRU', 'Не хотел, чтобы остыло.', 'Не хотела, чтобы остыло.', 28153),
(152875, 'ruRU', 'Дай мне умереть, Бвонсамди... Умоляю...', '', 28153),
(152874, 'ruRU', 'Говори уже.', '', 28153),
(152873, 'ruRU', '', 'Мы продолжим... Почему ты так странно на меня смотришь? Ты что, против?!', 28153),
(152872, 'ruRU', 'Да, совершенно верно. Мы это сделаем безотлагательно!', '', 28153),
(152871, 'ruRU', 'Э, я видал и похуже. Но все равно печально это все. Нам нужно доложить главнокомандующему, что мы обнаружили.', '', 28153),
(152870, 'ruRU', 'Какой ужас. Все даже хуже, чем я предполагал. Приношу свои глубочайшие извинения за то, что поставил вас в такое опасное положение, господин Бронзобород.', '', 28153),
(152869, 'ruRU', 'Ну? Эта дамочка взбесилась похлеще, чем мурлок при луне. Чуть было не принесла нашего друга в жертву какому-то кровавому богу по имени Г\'уун.', '', 28153),
(152868, 'ruRU', 'У капитана Конрад все хорошо, я полагаю?', '', 28153),
(152867, 'ruRU', 'В Зул\'Назмане, видимо. Или Тул\'воре? А вообще, это одно и то же. Ну почти.', '', 28153),
(152866, 'ruRU', 'Это ничего не меняет. Нам нужно во всем разобраться. Где нам искать этого капитана?', '', 28153),
(152865, 'ruRU', 'О боги... Наверняка капитан Конрад ничего не знала об этих ужасных обстоятельствах.', '', 28153),
(152864, 'ruRU', 'Гарри бледнеет.', '', 28153),
(152863, 'ruRU', 'Это еще что такое, Гарри?! Эти твои подношения... Из солдат выкачали всю кровь! Опустошили, как кружки эля на Хмельном фестивале.', '', 28153),
(152862, 'ruRU', 'Ну уж нет! Они не получат от нас ни единого медяка, пока мы не разузнаем, что к чему. $n составит мне компанию.', '', 28153),
(152861, 'ruRU', 'Торговые соглашения с троллями! Мы уже приготовили нетопырей, которые доставят наше предложение в Заламар.', '', 28153),
(152860, 'ruRU', 'О боги! Ну, вообще-то, да. Полагаю, что так и есть. Но капитан Конрад справится. Ее таланты поистине впечатляют.', '', 28153),
(152859, 'ruRU', 'Говорят, они дикари и практикуют кровавые жертвоприношения.', '', 28153),
(152858, 'ruRU', 'Все по плану, смею вас заверить. Наш славный капитан ведет переговоры насчет торговых соглашений с местными троллями.', '', 28153),
(152857, 'ruRU', 'Ясно, значит, капитана нет. Как вообще идут дела?', '', 28153),
(152856, 'ruRU', 'А! Ну конечно. Сразу к делу, да-да. Для беспокойства нет причин! Все в полном порядке. Может быть, пойдем в более безопасное место? За стены нашего форта, например?', '', 28153),
(152855, 'ruRU', 'Где капитан?', '', 28153),
(152854, 'ruRU', 'Капитан Конрад оставила мне распоряжения.', '', 28153),
(152853, 'ruRU', 'Мы вас ждали, наши уважаемые советники и будущие друзья.', '', 28153),
(152852, 'ruRU', 'Добро пожаловать! Добро пожаловать!', '', 28153),
(152851, 'ruRU', 'Ага, нас уже встречают. Гарри – любопытный тип. Не стоит им пренебрегать.', '', 28153),
(152850, 'ruRU', 'И... фу, лучше зажми нос. Почему здесь воняет дохлятиной?', '', 28153),
(152849, 'ruRU', 'Впрочем, ладно. Вот что я тебе скажу. Будь всегда начеку. Эта земля ошибок не прощает, $n.', '', 28153),
(152848, 'ruRU', 'Как бы то ни было, на этой земле живут враги зандаларов, а значит, и Орды. Враг моего врага... постой-ка, как же там обычно говорят?', '', 28153),
(152847, 'ruRU', 'Мы отправили туда капитана Конрад, чтобы построить форт. Говорят, что местные тролли крови, возможно, даже пожелают торговать с нами, но я думаю, это нам слишком дорого обойдется.', '', 28153),
(152846, 'ruRU', 'Мне это нравится! Где ты, там всегда приключения и перспективы узнать что-то новое.', '', 28153),
(152845, 'ruRU', 'У меня мурашки по коже от этого места...', '', 28153),
(152844, 'ruRU', 'Жаль, вы этого уже не увидите. Восстань, страж, и уничтожь чужаков!', '', 28153),
(152843, 'ruRU', 'Мы очистим наши земли от кул-тирасской чумы и вернем их себе!', '', 28153),
(152842, 'ruRU', 'Твои предки – глупцы... впрочем, как и ты!', '', 28153),
(152841, 'ruRU', 'Спусти одну из веревок к десантной шлюпке, $n. Удачи тебе, мы будем ждать твоего сигнала.', '', 28153),
(152840, 'ruRU', '', 'Еще одна стела. Давай посмотрим, что на ней изображено!', 28153),
(152839, 'ruRU', '', 'Горак Тул не выжил! Об этом писали очевидцы!', 28153),
(152838, 'ruRU', 'Местные власти разрешили нам открывать здесь порталы.', 'Местные власти разрешили нам открывать здесь порталы.', 28153),
(152837, 'ruRU', 'Это место пропитано магией. Чувствуешь?\n\nИнтересно, что за ритуалы они здесь проводили?', 'Это место пропитано магией. Чувствуешь?\n\nИнтересно, что за ритуалы они здесь проводили?', 28153),
(152836, 'ruRU', '', 'Еще одна стела! На ней тоже изображен Горак Тул.', 28153),
(152835, 'ruRU', '|cFF0000FF(Задание)|r Отправиться в Вол\'дун.', '|cFF0000FF(Задание)|r Отправиться в Вол\'дун.', 28153),
(152834, 'ruRU', '|cFFEF0201+$1i|r |cFFFFFF00ед. азерита|r', '|cFFEF0201+$1i|r |cFFFFFF00ед. азерита|r', 28153),
(152833, 'ruRU', 'Мне сказали, что мне предстоит работать с <кашляет> крови. \"С эльфами крови?\" – переспросил я. Нет, говорят, с <кашляет> крови.\n\nС троллями крови. А не эльфами. Ох... В них нет ни капли благородства.', '', 28153),
(152832, 'ruRU', '', 'Есть, сэр!', 28153),
(152831, 'ruRU', '', 'Стой... Что происходит?', 28153),
(152830, 'ruRU', 'Наша сила – в единстве.', '', 28153),
(152829, 'ruRU', 'Так. Я сделал тут пометку насчет красных цветов. Даже обвел ее. Красным цветом. Спасибо за помощь, без тебя все могло бы плохо закончиться.', '', 28153),
(152828, 'ruRU', 'Вот ты где. Я хочу собрать образцы редкого пустынного цветка. Поможешь мне?', '', 28153),
(152827, 'ruRU', 'Это надо же – так рехнуться! Встретимся у форта Победы. Уходим из этой дыры, пока они не опомнились.', '', 28153),
(152826, 'ruRU', 'Я готов.', 'Я готова.', 28153),
(152825, 'ruRU', 'В этой части мира он встречается редко. Говорят, листья красного плеточника обладают мистическими целебными свойствами.$b$bЯ бы хотел собрать немного, но запах растения привлечет местных животных.$b$bЗащити меня от них, пока я буду собирать листья. За это я тебя вознагражу.', '', 28153),
(152824, 'ruRU', 'Аллерия, возьмите остальные войска и рассейте вражеские силы.', '', 28153),
(152823, 'ruRU', 'ЖИЗНЬ ЗА ОРДУ!', '', 28153),
(152822, 'ruRU', 'Мой отец отдал Альянсу все. Ты готов сделать то же самое для Орды?', '', 28153),
(152821, 'ruRU', 'Я НИКОГДА не отступлю! Я жил с оружием в руках, и умру так же. А что ты сделал для своего народа?', '', 28153),
(152820, 'ruRU', 'Я бы поговорил о чести с твоим отцом. Ты о ней ничего не знаешь.', '', 28153),
(152819, 'ruRU', 'Уходи, Саурфанг. Это не твоя война. Твоя смерть не принесет никому чести.', '', 28153),
(152818, 'ruRU', '', 'Я готова!', 28153),
(152817, 'ruRU', 'Блестяще. А теперь идем дальше!', '', 28153),
(152816, 'ruRU', 'Четыре глаза... она идет!', '', 28153),
(152815, 'ruRU', 'Вечная тьма... тысяча рук...', '', 28153),
(152814, 'ruRU', 'Я стольким тебе обязан, $p. И я об этом не забуду.\n\nСейчас нужно помочь Норе и другим вульперам перерыть все украденные сокровища Зем\'лана. Но если тебе понадобится помощь мертвых пиратов, говори, не стесняйся.\n\nМятеж удался на славу, но одно я знаю точно: Зем\'лану не пришлось всех заставлять становиться монстрами. Многие стали ими по своей воле.\n\nСоблюдай осторожность, если захочешь вернуться в порт.', '', 28153),
(152813, 'ruRU', 'Жезл Виктории поможет нам открыть дорогу к святилищу. Ее жертва не должна стать напрасной.', '', 28153),
(152812, 'ruRU', 'Бунт или нок-рея, $p. Я пойду за тобой.', '', 28153),
(152811, 'ruRU', 'Столько сокровищ в одном месте!\n\nВот чего добиваются те, кто занимается пиратством всю свою вечную жизнь. Это так здорово...', '', 28153),
(152810, 'ruRU', '', '<Ана громко храпит, притворяясь спящей.>', 28153),
(152809, 'ruRU', 'Ударь в гонг, чтобы вызвать Зем\'лана на поединок. Я готов к бою.', '', 28153),
(152808, 'ruRU', 'Значит, мы донесем до Кэтрин Праудмур простую истину, которая далась мне так тяжело.', '', 28153),
(152807, 'ruRU', 'Ух ты! Древние тролльские монеты стоят целое состояние! Вот твоя доля.', '', 28153),
(152806, 'ruRU', 'Во дворе Зак\'ражана я нашел древний тотем, способный оживлять мертвых. Отнеси его к яме с костями и добудь зарытое там сокровище!', '', 28153),
(152805, 'ruRU', 'Ладно, забудь! У меня нет времени на ерунду. Мне пора на вечеринку!', '', 28153),
(152804, 'ruRU', 'Какие все пошли нетерпеливые. Дай хоть разогреться.', '', 28153),
(152803, 'ruRU', 'Будешь меня доставать, я расскажу тебе историю. Очень долгую и нудную.', '', 28153),
(152802, 'ruRU', 'Обменяемся историями в другой раз.', '', 28153),
(152801, 'ruRU', 'Ладно. У меня есть другие дела.', '', 28153),
(152800, 'ruRU', 'А ты все куда-то торопишься.', '', 28153),
(152799, 'ruRU', 'Не шуми!', '', 28153),
(152798, 'ruRU', 'Есть что рассказать?', '', 28153),
(152797, 'ruRU', 'Да-да... слушаю.', '', 28153),
(152796, 'ruRU', 'В джунглях флора может оказаться куда хуже фауны. Тут главное смотреть в оба.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152795, 'ruRU', 'Больше ноги моей в этом руднике не будет!', 'Больше ноги моей в этом руднике не будет!', 28153),
(152794, 'ruRU', 'Они появились словно ниоткуда!', 'Они появились словно ниоткуда!', 28153),
(152793, 'ruRU', 'Спасибо! Я уж думал, мне конец.', 'Спасибо! Я уж думала, мне конец.', 28153),
(152792, 'ruRU', 'Заберите меня отсюда!', 'Заберите меня отсюда!', 28153),
(152791, 'ruRU', '', 'Поток отнесет вас прямо к мосту.', 28153),
(152790, 'ruRU', 'Хочешь познакомиться с моим башмаком? Твоя физиономия по нему плачет.', '', 28153),
(152789, 'ruRU', 'Улетай, птичка...', '', 28153),
(152788, 'ruRU', 'Увидимся в небе.', '', 28153),
(152787, 'ruRU', '', 'На севере жрецы моря под началом дома Штормсонгов строят и благословляют корабли для нашего флота.', 28153),
(152786, 'ruRU', 'Ладно. Бывай.', '', 28153),
(152785, 'ruRU', 'Все, за работу!', '', 28153),
(152784, 'ruRU', 'Чего хочешь?', '', 28153),
(152783, 'ruRU', 'Чего надо?', '', 28153),
(152782, 'ruRU', 'Чего? У меня много дел.', '', 28153),
(152781, 'ruRU', 'Спасибо! Стервятники здорово докучали вол\'дунским караванщикам.', '', 28153),
(152780, 'ruRU', 'Твердоклювые стервятники слишком быстро плодятся, никакого сладу с ними нет. Сократи их поголовье и разрушь гнезда.', '', 28153),
(152779, 'ruRU', 'Можешь походить здесь, осмотреться. Только, пожалуйста, ничего не трогай.$b$bЭти растения очень хрупкие.', '', 28153),
(152778, 'ruRU', '', 'Горный регион Друствар на западе обеспечивает все королевство рудой и крепкими бойцами.', 28153),
(152777, 'ruRU', '', 'За Тирагардским поморьем лежат земли Уэйкрестов и Штормсонгов.', 28153),
(152776, 'ruRU', 'Тебя ждет только боль!', 'Тебя ждет только боль!', 28153),
(152775, 'ruRU', 'Я знаю, как заставить тебя заговорить!', 'Я знаю, как заставить тебя заговорить!', 28153),
(152774, 'ruRU', 'Я сломлю твой дух.', 'Я сломлю твой дух.', 28153),
(152773, 'ruRU', 'Все живое сгорит дотла...', '', 28153),
(152772, 'ruRU', 'Лечить его было слишком поздно.', '', 28153),
(152771, 'ruRU', 'Моя страна в большой беде... и я прошу вас о помощи. Альянс нужен Кул-Тирасу не меньше, чем Кул-Тирас – Альянсу.', '', 28153),
(152770, 'ruRU', 'Но она не замечает, что зараза уже распространилась по всему королевству.', '', 28153),
(152769, 'ruRU', 'Третья война изранила Кул-Тирас. И Кэтрин Праудмур сильнее всех чувствует эти раны.', '', 28153),
(152768, 'ruRU', '', 'Постарайся не выставить меня в дурном свете, ладно?', 28153),
(152767, 'ruRU', 'Через пару дней он проснулся среди ночи от боли и лихорадки. Заражение зашло слишком далеко. Парень не дожил до рассвета.', '', 28153),
(152766, 'ruRU', '', 'Если тут монеты кончились, поищи в другом месте.', 28153),
(152765, 'ruRU', 'Ему следовало вернуться и подлечиться, но он решил, что стыдно бросать друзей на фронте из-за пары царапин. Перевязался – и никому не сказал о ранении.', '', 28153),
(152763, 'ruRU', 'Наш транспорт попал под огонь орочьего корабля, и моего товарища ранило щепками от планширя.', '', 28153),
(152762, 'ruRU', 'Кажется, это была Вторая война. Я все время их путаю. Сколько лет прошло...', '', 28153),
(152761, 'ruRU', 'Хм... Расскажу-ка я вам одну историю.', '', 28153),
(152760, 'ruRU', 'Почему вы нам помогаете?', '', 28153),
(152759, 'ruRU', 'Кэтрин Праудмур обвинила свою дочь в измене и отказалась принять нас.', '', 28153),
(152758, 'ruRU', 'Странствующий зандалар продал мне это зелье. Оно мгновенно готовит пищу из всего, на что попадает. Попробуй применить его к местной фауне. Я никогда не откажусь от бесплатного мяса!', '', 28153),
(152757, 'ruRU', 'Телия! Приготовь отчет для наших гостей.', '', 28153),
(152756, 'ruRU', 'Вы все сгинете.', '', 28153),
(152755, 'ruRU', 'Король Седогрив, это честь для меня! В порту Боралуса вы под моей защитой.', '', 28153),
(152754, 'ruRU', 'На вид аппетитно! Но сначала дадим кусочек на пробу моим зубастым друзьям...', '', 28153),
(152753, 'ruRU', '', 'Они хотят обрести силу. Они жаждут познать высшую истину. Они следуют зову крови.', 28153),
(152752, 'ruRU', '', 'Поначалу ритуалы назмани меня... несколько смущали. Но я узнала их поближе и прониклась. Это простой народ, и желания у них простые.', 28153),
(152751, 'ruRU', '', 'Сейчас расскажу, что я узнала.', 28153),
(152750, 'ruRU', '', 'Мне еще многое предстоит о них узнать. Эта магия крови... Она куда более могущественна, чем вы можете себе представить.', 28153),
(152749, 'ruRU', '', 'Они могут стать мощным оружием против зандаларов и Орды.', 28153),
(152748, 'ruRU', '', 'Я добилась даже большего расположения среди назманийских троллей крови, чем предполагала.', 28153),
(152747, 'ruRU', 'А-а-а, захлопни пасть!', '', 28153),
(152746, 'ruRU', '', 'А-а-а!', 28153),
(152745, 'ruRU', '', 'Ничего личного, ты же понимаешь. Я не могу позволить тебе свести на нет все мои усилия. Я столько узнала... И мне еще столько предстоит для себя открыть.', 28153),
(152744, 'ruRU', '', 'Мы принесем этого зандалара в жертву и умножим нашу силу.', 28153),
(152743, 'ruRU', 'Мы за тобой в огонь и в воду.', 'Мы за тобой в огонь и в воду.', 28153),
(152742, 'ruRU', 'Здесь недалеко лагерь вульпер. Присоединимся к ним, пока буря не утихнет.', '', 28153),
(152741, 'ruRU', 'Шавки Зем\'лана наверняка будут нас искать.', '', 28153),
(152740, 'ruRU', 'Да! Но сперва придется ненадолго затихариться.', '', 28153),
(152739, 'ruRU', 'И добычу никому не отдавать.', 'И добычу никому не отдавать.', 28153),
(152738, 'ruRU', 'Можем грабить всех подряд.', 'Можем грабить всех подряд.', 28153),
(152737, 'ruRU', 'Нам открыты все моря.', 'Нам открыты все моря.', 28153),
(152736, 'ruRU', 'Вот и все, ребятки. Зем\'лан нам больше не указ!', '', 28153),
(152735, 'ruRU', 'Навались! Полный ход к берегу!', 'Навались! Полный ход к берегу!', 28153),
(152734, 'ruRU', 'Ты, должно быть, эмиссар Альянса. Хорошо, что Флинн и Телия вытащили тебя из той проклятой тюрьмы. \n\nЯ Сайрус Крестфол. От имени адмиралтейства Праудмуров приветствую тебя в Кул-Тирасе.\n\n<Сайрус дружелюбно протягивает свою мощную руку.>', '', 28153),
(152733, 'ruRU', '<Пожать руку.>', '<Пожать руку.>', 28153),
(152732, 'ruRU', 'Мне не так долго осталось жить.\n\nИ я не намерен провести остаток своих дней, наблюдая, как Кул-Тирас приходит в упадок.', '', 28153),
(152731, 'ruRU', 'Матросы! Хватайте добычу и тащите на борт!', '', 28153),
(152730, 'ruRU', 'Уинстон улетел слишком далеко от вас. Вернитесь в Корлейн!', '', 28153),
(152729, 'ruRU', 'Принцесса, $n, разведчики заметили хранителя титанов Хезрела у подножия пирамиды.', '', 28153),
(152728, 'ruRU', 'Со времен Хаккара разум гурубаши подвержен слабости. Их слишком легко сбить с пути, поэтому с ними нужно разделаться.', '', 28153),
(152727, 'ruRU', '', 'Вам... не победить...', 28153),
(152726, 'ruRU', 'Так точно, кэп!', '', 28153),
(152725, 'ruRU', '', 'Корлейн принадлежит ковену!', 28153),
(152724, 'ruRU', 'Отдыхайте, развлекайтесь. Завтра подумаем над тем, как забрать остатки сокровищ.', 'Отдыхайте, развлекайтесь. Завтра подумаем над тем, как забрать остатки сокровищ.', 28153),
(152723, 'ruRU', 'Добро пожаловать!', 'Добро пожаловать!', 28153),
(152722, 'ruRU', 'Ну что ж...', 'Ну что ж...', 28153),
(152721, 'ruRU', 'Да. На острове, откуда мы приплыли, их видимо-невидимо.', '', 28153),
(152720, 'ruRU', 'Можно подумать, вульпер это когда-то останавливало. А еще сокровища есть?', 'Можно подумать, вульпер это когда-то останавливало. А еще сокровища есть?', 28153),
(152719, 'ruRU', 'Одна беда – сокровище проклято.', 'Одна беда – сокровище проклято.', 28153),
(152718, 'ruRU', 'Мы ищем новую команду. Если вы примете нас, мы поделимся добычей.', '', 28153),
(152717, 'ruRU', 'Вашего друга убил король пиратов Зем\'лан. Мы подняли бунт и забрали его сокровища.', '', 28153),
(152716, 'ruRU', 'Я слушаю...', 'Я слушаю...', 28153),
(152715, 'ruRU', 'Отставить! Мы пришли заключить мир.', '', 28153),
(152714, 'ruRU', 'С-с-скелеты! Н-н-нора, убей их!', 'С-с-скелеты! Н-н-нора, убей их!', 28153),
(152713, 'ruRU', 'Ха! Когда по тебе стреляют из твоих же орудий, это деморализует.', '', 28153),
(152712, 'ruRU', 'Хорошая драка – это мое все!', 'Хорошая драка – это мое все!', 28153),
(152711, 'ruRU', 'Отступники не прекращают атаковать! Беги к одной из захваченных нами пушек и помоги защитить храм!', '', 28153),
(152710, 'ruRU', '', 'Патч, давай!', 28153),
(152709, 'ruRU', 'Я готов.', 'Я готова.', 28153),
(152708, 'ruRU', 'Может, пойдем уже? Мы не прохлаждаться сюда приехали.', '', 28153),
(152707, 'ruRU', 'Начинайте обстрел!', '', 28153),
(152706, 'ruRU', 'Пли!', '', 28153),
(152705, 'ruRU', 'Не жалейте снарядов!', '', 28153),
(152704, 'ruRU', 'Вижу цель! Огонь!', '', 28153),
(152703, 'ruRU', 'Огонь на поражение!', '', 28153),
(152702, 'ruRU', 'Вижу цель! Огонь!', '', 28153),
(152701, 'ruRU', 'Ха-ха-ха...', '', 28153),
(152700, 'ruRU', '...Ага. Может отпугнуть потенциальных клиентов.', '', 28153),
(152699, 'ruRU', 'Слишком страшно?', '', 28153),
(152698, 'ruRU', 'Я тут подсчитал прибыль и убытки и решил, что нам не стоит терять здесь время.', '', 28153),
(152697, 'ruRU', 'Так... как насчет твоего азерита?', '', 28153),
(152696, 'ruRU', 'Хорошо. Садись на мотоцикл. Погнали отсюда.', '', 28153),
(152695, 'ruRU', 'Да уж.', '', 28153),
(152694, 'ruRU', 'Так... э-э... ты, наверное, хочешь убраться отсюда?', '', 28153),
(152693, 'ruRU', 'Нет-нет-нет...', '', 28153),
(152692, 'ruRU', 'Лучше бы тебе преодолеть свой страх перед ведьмами, Эйтригг. Тут же полно азерита, и... гкх!', '', 28153),
(152691, 'ruRU', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t%s получает |cFFFF0000|Hspell:263246|h[Щит молний]|h|r!', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t%s получает |cFFFF0000|Hspell:263246|h[Щит молний]|h|r!', 28153),
(152690, 'ruRU', 'Еще одна!', '', 28153),
(152689, 'ruRU', '', 'Ваша кровь принадлежит мне!', 28153),
(152688, 'ruRU', 'Да какая разница? Вы азерит нашли?', '', 28153),
(152687, 'ruRU', 'Что? В чем дело?', '', 28153),
(152686, 'ruRU', 'Д-да заткнись ты.', '', 28153),
(152685, 'ruRU', 'Ха-ха-ха! Большой взрослый орк боится ведьм.', '', 28153),
(152684, 'ruRU', 'НЕТ! В смысле, нет, просто они мне не нравятся, вот и все.', '', 28153),
(152683, 'ruRU', 'Что ты сказал?', '', 28153),
(152682, 'ruRU', 'Берегитесь... ведьм...', '', 28153),
(152681, 'ruRU', 'Эйтригг... ты боишься ведьм?', '', 28153),
(152680, 'ruRU', 'Он сказал... ведьм?..', '', 28153),
(152679, 'ruRU', 'В общественных местах небезопасно! Эти птицы повсюду!', 'В общественных местах небезопасно! Эти птицы повсюду!', 28153),
(152678, 'ruRU', 'Ну что, давайте, защищайте меня!', '', 28153),
(152677, 'ruRU', 'Нет... Но я вижу кое-что другое. Мы тут не одни.', '', 28153),
(152676, 'ruRU', 'Пф... С ними такое происходит постоянно. Видишь где-нибудь азерит?', '', 28153),
(152675, 'ruRU', 'Они везде!', 'Они везде!', 28153),
(152674, 'ruRU', 'Галливикс... видишь этот изувеченный труп? Этот разведчик мертв.', '', 28153),
(152673, 'ruRU', 'Да, да, как скажешь.', '', 28153),
(152672, 'ruRU', 'Ладно, посмотрим, что там с азеритом. Но потом займемся Альянсом, и никаких \"но\"!', '', 28153),
(152671, 'ruRU', 'Слишком... много... птиц!', 'Слишком... много... птиц!', 28153),
(152670, 'ruRU', 'Я теперь буду держаться подальше от чаек!', 'Я теперь буду держаться подальше от чаек!', 28153),
(152669, 'ruRU', 'Леди МакМиллан правду говорила. Эти птицы – зло!', 'Леди МакМиллан правду говорила. Эти птицы – зло!', 28153),
(152668, 'ruRU', 'Пф! Работнички.', '', 28153),
(152667, 'ruRU', 'Проверим эту информацию первым же делом.', '', 28153),
(152666, 'ruRU', 'Самое главное! Разведчики докладывают, что в Друстваре находится огромная азеритовая жила.', '', 28153),
(152665, 'ruRU', 'Тогда вон с глаз моих, а не то то, что тебя тут напугало, покажется еще цветочками!', '', 28153),
(152664, 'ruRU', 'Нам надо быть осторожными. Его слова... вызывают беспокойство.', '', 28153),
(152663, 'ruRU', 'Да, но...', '', 28153),
(152662, 'ruRU', '...ужасное проклятие... остальных... всех...', '', 28153),
(152661, 'ruRU', 'Надо возвращаться! Тут...', '', 28153),
(152660, 'ruRU', '', 'Хм... Я думала, оно будет больше.', 28153),
(152659, 'ruRU', '', 'Недостаточно заряда. Нужно больше энергии.', 28153),
(152658, 'ruRU', 'Нам больше по душе красоты природы, чем холодный камень города. Многие зандалары считают нас еретиками. Говорят, что наша матрона вовсе не лоа. \n\nМы не станем их переубеждать. Лун\'алай издревле обладают даром принимать формы, созданные природой. Наш путь – гармония, мы не приемлем споров и разногласий.', '', 28153),
(152655, 'ruRU', 'Блестяще! Какая красота! Ой, тут немного песка... ну ладно. Спасибо огромное!', '', 28153),
(152654, 'ruRU', 'Волны приносят сюда много красивых морских стеклышек, но мурлоки все растаскивают! Можешь собрать для меня горстку-другую?', '', 28153),
(152653, 'ruRU', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Язма начинает применять заклинание |cFFFF0404|Hspell:249924|h[Раздирание души]|h|r!', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Язма начинает применять заклинание |cFFFF0404|Hspell:249924|h[Раздирание души]|h|r!', 28153),
(152652, 'ruRU', 'Слишком поздно. Вторжение уже началось!', 'Слишком поздно. Вторжение уже началось!', 28153),
(152651, 'ruRU', 'Думаешь, я работаю в одиночку? Познакомься с моими помощниками!', 'Думаешь, я работаю в одиночку? Познакомься с моими помощниками!', 28153),
(152650, 'ruRU', '', 'Все деяния ковена ужасны, но здесь ведьмы превзошли сами себя! Я глубоко признательна вам за то, что вы остановили эту... мясорубку.', 28153),
(152649, 'ruRU', 'Ковен отрицает любые принципы. Это было одно из их самых мерзостных начинаний.', '', 28153),
(152648, 'ruRU', 'А теперь пора в путь! Встретимся у лодки. Погрузку сокровищ я беру на себя.', '', 28153),
(152647, 'ruRU', '', 'Каждая спасенная жизнь – это маленькая победа.', 28153),
(152646, 'ruRU', 'Очень хорошо. Все должны помнить, что смерть и перерождение подвластны только нам.', '', 28153),
(152645, 'ruRU', '', 'Благодаря вам в небе над Друстваром снова чисто и безопасно. Спасибо.', 28153),
(152644, 'ruRU', 'Не создавай нам проблем.', 'Не создавай нам проблем.', 28153),
(152643, 'ruRU', 'Эти перья – именно то, чего не хватало нашим следопытам.', '', 28153),
(152642, 'ruRU', 'Вечный разбой и грабеж... без тебя!', '', 28153),
(152641, 'ruRU', 'Что может быть лучше, чем вечный разбой и грабеж?', '', 28153),
(152640, 'ruRU', 'Ты изверг, Зем\'лан. Команда заслуживает лучшей доли!', '', 28153),
(152639, 'ruRU', '', 'Придется, иначе мы все погибнем. Идите!', 28153),
(152638, 'ruRU', '', 'Мы не бросим тебя умирать!', 28153),
(152637, 'ruRU', '', 'Еле справились... Нам нужно тщательнее следить не только за песками, но и за морем.', 28153),
(152636, 'ruRU', '', 'Еще бы чуть-чуть... Нам нужно внимательно следить за морем и за пустыней.', 28153),
(152635, 'ruRU', '', 'К нам в гости пожаловал гигантский морской монстр. Нужно остановить его, пока он не натворил дел на суше.', 28153),
(152634, 'ruRU', '', 'На побережье хозяйничает гигантский морской монстр. Нужно остановить его, пока он не подобрался к нашему лагерю.', 28153),
(152633, 'ruRU', '', 'Заклинатель клыков Ксоррет был важной фигурой в армии сетраков. Это большая победа для нас.', 28153),
(152632, 'ruRU', '', 'Заклинатель клыков Ксоррет был важной фигурой в армии сетраков. Это большая победа для нас.', 28153),
(152631, 'ruRU', '', 'Разведчики вульпер доложили, что видели неподалеку сетракийского командира. Нужно устранить его, пока есть возможность.', 28153),
(152630, 'ruRU', '', 'Разведчики доложили, что видели сетракийского командира высшего ранга неподалеку. Нам нужно устранить его, пока есть возможность.', 28153),
(152629, 'ruRU', '', 'Спасибо! Без вождя мурлоки перестанут угрожать нам.', 28153),
(152628, 'ruRU', '', 'Отличная работа! Без вождя племя быстро разбредется.', 28153),
(152627, 'ruRU', '', 'Одно племя мурлоков создает проблемы местным жителям. Устрани их вождя, и племя больше не будет представлять угрозы.', 28153),
(152626, 'ruRU', '', 'Племя мурлоков создает проблемы местным жителям. Убей их вождя – без него мурлоки разбегутся.', 28153),
(152625, 'ruRU', '', 'Отлично. Наши разведчики обрадуются, что Мор\'фани им больше не помеха.', 28153),
(152624, 'ruRU', '', 'Хорошо. Вульперы будут рады, что Мор\'фани им больше не угрожает.', 28153),
(152623, 'ruRU', 'Ковен зачаровал огромного ворона, и теперь он нападает на горожан. У меня нет симпатий к жителям Друствара, но из перьев этой птицы могли бы получиться превосходные стрелы.', '', 28153),
(152622, 'ruRU', 'Одна из верховных ведьм ковена приносит в жертву послушников, чтобы стать сильнее. Убейте ее и покажите этим выскочкам, что только Темная Госпожа властна над смертью.', '', 28153),
(152621, 'ruRU', 'Похоже, здешних поваров \"нанял\" ковен, отчего качество блюд резко... изменилось. Вам следует уничтожить их как можно быстрее.', '', 28153),
(152620, 'ruRU', '', 'Ковен Мертвых Сердец подчинил огромного друстварского ворона. Убейте его, пока он не начал охоту на горожан!', 28153),
(152619, 'ruRU', '', 'Ведьма из ковена леди Уэйкрест приносит в жертву своих послушников. Остановите ритуал, пока не поздно!', 28153),
(152618, 'ruRU', '', 'Один зандаларский изгой нападает на наших разведчиков. Найди и устрани его, пока он еще кого-нибудь не убил.', 28153),
(152617, 'ruRU', '', 'Один изгой постоянно нападает на вульпер. Найди и убей его, пока он не унес еще больше жизней.', 28153),
(152616, 'ruRU', '', 'Местные повара подают очень сомнительные блюда ничего не подозревающим гостям. Положите конец этим кулинарным изуверствам!', 28153),
(152615, 'ruRU', 'Есть, сэр!', '', 28153),
(152614, 'ruRU', 'Н-нет, сэр.', '', 28153),
(152613, 'ruRU', 'Так что пропусти их. Мы с гостями поговорим в конторе.', '', 28153),
(152612, 'ruRU', 'Вот именно! Ты служишь Кул-Тирасу! Носишь герб Праудмуров! И приказы тебе отдаю я.', '', 28153),
(152611, 'ruRU', 'В Вол\'дуне не вырастишь урожай без удобрения. Обычно его нам поставляют гиены, но сейчас у них что-то с этим туго. Покорми бедняг, чтобы... ускорить процесс.', '', 28153),
(152610, 'ruRU', 'Леди Эшвейн? А ты кому служишь, леди Эшвейн? У тебя на щите что? Герб Эшвейнов?', '', 28153),
(152609, 'ruRU', 'Но сэр... леди Эшвейн приказала...', '', 28153),
(152608, 'ruRU', 'Отставить! Вы знаете, кто это?', '', 28153),
(152607, 'ruRU', 'М-м-м, отменное качество! Ты молодчага... только не забудь помыть руки!', '', 28153),
(152606, 'ruRU', 'Видимо, нам придется вмешаться?', '', 28153),
(152605, 'ruRU', 'Неужели там паруса на горизонте? Возможно, они хотят заключить сделку с зандаларами.', '', 28153),
(152604, 'ruRU', 'Удар ногой', 'Удар ногой', 28153),
(152603, 'ruRU', 'Коробка издает спокойный звон.', '', 28153),
(152602, 'ruRU', 'Коробка издает радостный звон.', '', 28153),
(152601, 'ruRU', 'Коробка издает спокойный звон.', '', 28153),
(152600, 'ruRU', 'Без понятия. Но я сегодня угощаю.', '', 28153),
(152599, 'ruRU', '', 'Что это?', 28153),
(152598, 'ruRU', '', 'Я с большим удовольствием телепортирую тебя на дно Великого моря! За Орду!', 28153),
(152597, 'ruRU', 'Что...', '', 28153),
(152596, 'ruRU', '', 'Ввиду распространения слухов о захватчиках и шпионах, осторожность лишней не будет. Следуйте распоряжениям во избежание недоразумений.', 28153),
(152595, 'ruRU', '', 'Плату обсудим позже, начальник дока.', 28153),
(152594, 'ruRU', 'Ага, вот оно. Упакуем и отправим в Штормград.', '', 28153),
(152591, 'ruRU', '', 'Окулет... Прости меня...', 28153),
(152590, 'ruRU', 'Стрелка указывает на восток. Встретимся в руинах, $n.', '', 28153),
(152589, 'ruRU', '', 'Слишком медленно, дворф.', 28153),
(152588, 'ruRU', 'Держись рядом. Здесь повсюду бродит Орда. Я их чую.', '', 28153),
(152587, 'ruRU', 'Какие цветастые эльфы. Это что, новая разновидность?', '', 28153),
(152586, 'ruRU', 'Это не то место. А вдобавок за нами еще и ночнорожденные увязались. Вот уж радость.', '', 28153),
(152585, 'ruRU', 'Мы уже близко. Не подпускай ко мне этих агрессивных маноманов, $n.', '', 28153),
(152584, 'ruRU', 'Прямо у меня под ногами... а где?..', '', 28153),
(152583, 'ruRU', 'Ай! Что за грязный трюк!', '', 28153),
(152581, 'ruRU', 'Ящик тихонько гудит.', '', 28153),
(152580, 'ruRU', 'Ящик тихонько гудит.', '', 28153),
(152579, 'ruRU', 'Ящик тихонько гудит.', '', 28153),
(152578, 'ruRU', 'Отставить! Их явно нельзя уничтожить. А еще они пробудили недобрые воспоминания...', '', 28153),
(152577, 'ruRU', 'У нашей планеты в сердце торчит огромный меч, а ты стоишь тут и достаешь меня? Иди, займись делом!', '', 28153),
(152576, 'ruRU', 'Помни о долге перед Азерот.', '', 28153),
(152575, 'ruRU', 'Мы должны исцелить наш мир!', '', 28153),
(152574, 'ruRU', 'Азерот стонет от боли.', '', 28153),
(152573, 'ruRU', 'Азерот нужна наша помощь.', '', 28153),
(152572, 'ruRU', '', 'Подумать только, археологическая находка века буквально валялась у троллей под ногами!', 28153),
(152571, 'ruRU', 'Осторожнее тут. Я чую здесь силу. Мы заберем ее прямо из-под носа у Орды.', '', 28153),
(152570, 'ruRU', '', 'Очень хорошо. Ровными движениями.', 28153),
(152569, 'ruRU', '', 'Постарайся не повредить. Да, вот так...', 28153),
(152568, 'ruRU', '', 'Ах, ты только посмотри. Из тебя выйдет хороший археолог!', 28153),
(152567, 'ruRU', 'Серьезно? Ты собираешься сидеть и ковыряться тут руками?', '', 28153),
(152566, 'ruRU', 'Поручи это моему элементалю. Он все сделает за тебя.', '', 28153),
(152565, 'ruRU', '', 'Стой!', 28153),
(152564, 'ruRU', 'Хорошо. А теперь начинается настоящая работа.', '', 28153),
(152563, 'ruRU', '', 'Здесь царапина! В таком виде выставлять нельзя!', 28153),
(152562, 'ruRU', 'Да, вот так неплохо.', '', 28153),
(152561, 'ruRU', 'Мои кости устали. Проклятие – тяжкое бремя.', '', 28153),
(152560, 'ruRU', 'Зем\'лан надолго запомнит этот день.', '', 28153),
(152559, 'ruRU', '', 'К конторе капитана порта можно пройти здесь.', 28153),
(152558, 'ruRU', 'И одежду постирать не помешает...', '', 28153),
(152557, 'ruRU', 'Надежный молот – это бесценное орудие и прекрасное оружие.', '', 28153),
(152556, 'ruRU', 'Когда у меня с собой нет молота, я ничего не могу сделать. Без него – как без рук.', '', 28153),
(152555, 'ruRU', '', 'Я не смогу долго их сдерживать. Хватайте жезл – и бегите отсюда!', 28153),
(152554, 'ruRU', 'Изучение', 'Изучение', 28153),
(152553, 'ruRU', 'Эти пещеры кишат кобольдами-вредителями.', '', 28153),
(152552, 'ruRU', 'Все на борт! Увидимся, $p.', '', 28153),
(152551, 'ruRU', 'Мы почти готовы сняться с якоря. Захватим Зем\'лана врасплох.', '', 28153),
(152550, 'ruRU', 'Да.', 'Да.', 28153),
(152549, 'ruRU', 'Да.', 'Да.', 28153),
(152548, 'ruRU', 'Да. Зем\'лан – изверг, а не капитан. Точно надо бунтовать.', 'Да. Зем\'лан – изверг, а не капитан. Точно надо бунтовать.', 28153),
(152547, 'ruRU', 'Договорились, значит?', '', 28153),
(152546, 'ruRU', 'Ага! И поживимся заодно.', '', 28153),
(152545, 'ruRU', 'Сколько же тут золота...', 'Сколько же тут золота...', 28153),
(152544, 'ruRU', 'Ну да, мы же затеяли бунт, пустая ты башка! Вскроем Зем\'лану костлявое пузо!', 'Ну да, мы же затеяли бунт, пустая ты башка! Вскроем Зем\'лану костлявое пузо!', 28153),
(152543, 'ruRU', 'И мы плывем прямо к ним в гости...', 'И мы плывем прямо к ним в гости...', 28153),
(152542, 'ruRU', 'Их участь еще горше нашей.', '', 28153),
(152541, 'ruRU', 'Некоторых матросов Зем\'лан превратил в золотых рабов. У них одна цель – охранять сокровища.', '', 28153),
(152540, 'ruRU', 'Мы плывем на Золотой остров, куда Зем\'лан свозил все сокровища, награбленные нами за несчетные годы.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152539, 'ruRU', 'Навались!', 'Навались!', 28153),
(152538, 'ruRU', '*Здесь будет крутая анимация с вагонеткой.*', '', 28153),
(152537, 'ruRU', 'Здесь так светло... верни мои кости в яму.', 'Здесь так светло... верни мои кости в яму.', 28153),
(152536, 'ruRU', '', 'Кул-Тирасом правят несколько знатных домов. Когда-то всеобщим лидером был Дэлин Праудмур, но после его гибели в Тераморе все изменилось.', 28153),
(152535, 'ruRU', '', 'Кэтрин Праудмур заняла место мужа и стала лордом-адмиралом. Она командует армией и стражей.', 28153),
(152534, 'ruRU', '', 'Но, несмотря на ее старания, в Кул-Тирасе все больше проблем с коррупцией, пиратством и преступностью. Праудмуры теряют доверие народа.', 28153),
(152533, 'ruRU', '', '.', 28153),
(152532, 'ruRU', '', '.', 28153),
(152531, 'ruRU', 'Добрый день. Тебе нужно отдохнуть? Или, может быть, перекусить?', '', 28153),
(152530, 'ruRU', 'Это честь для меня – служить кастеляном у лорда и леди Норвингтон. Если тебе нужна комната, я всегда готов помочь.', '', 28153),
(152529, 'ruRU', 'Содержание такого поместья требует больших усилий. Кузнецу постоянно нужно то подковы ковать, то грабли чинить, то еще что-нибудь по мелочи.', '', 28153),
(152528, 'ruRU', 'Тебе нужно что-то починить? Я больше по части подков, но могу посмотреть, что можно сделать с твоей броней.', '', 28153),
(152527, 'ruRU', '', 'Бегите!', 28153),
(152526, 'ruRU', '', 'Все очень просто. Не получай ран, и мне не придется тебя лечить.', 28153),
(152525, 'ruRU', '', 'Я буду сдерживать их, сколько смогу!', 28153),
(152524, 'ruRU', 'Я знал, что ты справишься! И, главное, руки-ноги на месте. Вот это настоящая удача!', '', 28153),
(152523, 'ruRU', 'В дюнах обитают песчаные черви. Они опасные хищники, но их зубы очень ценны! Вот, возьми мою удочку. Посмотрим, что ты поймаешь!', '', 28153),
(152522, 'ruRU', 'Все могло быть и хуже. Мы делаем все, что в наших силах, с теми ресурсами, какие есть.', '', 28153),
(152521, 'ruRU', 'Флот Кул-Тираса в моей власти. Скоро будете и вы!', '', 28153),
(152520, 'ruRU', '', 'Я... Я больше не могу.', 28153),
(152519, 'ruRU', '', 'Давай, еще пару шагов. Мы тебя не бросим!', 28153),
(152518, 'ruRU', 'Я покажу вам мощь наших новых союзников.', '', 28153),
(152517, 'ruRU', 'Мне больше нечего тебе дать, Зем\'лан... Ты забрал у меня все.', 'Мне больше нечего тебе дать, Зем\'лан... Ты забрал у меня все.', 28153),
(152516, 'ruRU', 'Еще одно мясистое смертное существо! Это будет весело.', 'Еще одно мясистое смертное существо! Это будет весело.', 28153),
(152514, 'ruRU', '', 'Вперед, мы почти у цели!', 28153),
(152513, 'ruRU', '', 'Осталось добраться до того алтаря.', 28153),
(152512, 'ruRU', 'Вы хотите мне помешать, но судьба Кул-Тираса давно решена.', '', 28153),
(152507, 'ruRU', 'Иди сообщи хорошие новости. А я прослежу, чтобы о пушках позаботились как надо.', '', 28153),
(152506, 'ruRU', 'Это последние!', '', 28153),
(152505, 'ruRU', 'Ха, еще один выведен из строя. И один остался...', '', 28153),
(152504, 'ruRU', 'ОГОНЬ!', '', 28153),
(152503, 'ruRU', 'Это определенно привлекло их внимание. Погляди, чтобы Орда не подошла слишком близко, пока я перезаряжаю!', '', 28153),
(152502, 'ruRU', 'Ну что, начнем. Заткните-ка уши!', '', 28153),
(152501, 'ruRU', 'Нет бы исцелить Азерот, вместо того чтобы еще сильней ранить ее! Спасибо тебе.', '', 28153),
(152500, 'ruRU', 'Кто-то тянет энергию из месторождения азерита. Останови это!', '', 28153),
(152499, 'ruRU', 'А я приведу вас к счастливому, светлому будущему в глубине океана.', '', 28153),
(152498, 'ruRU', '', 'Это сила... будет... нашей!', 28153),
(152497, 'ruRU', '', 'Никто не сможет устоять против мощи сетраков!', 28153),
(152496, 'ruRU', 'Найдите самоцветы и верните их в глазницы, иначе нам не пройти дальше!', '', 28153),
(152495, 'ruRU', 'Глаза Сетралисс! Они украдены!', '', 28153),
(152494, 'ruRU', 'У меня есть все, что нужно. Скажи, когда можно будет приступить к ритуалу.', '', 28153),
(152493, 'ruRU', 'Я видел, как он шел к городу. Надеюсь, он не попадет в передрягу и о нем позаботятся.', '', 28153),
(152492, 'ruRU', 'Я давно за тобой наблюдаю. И видел твои успехи с малышом. Ты можешь им гордиться. И собой тоже – ты так о нем заботишься. Немногие согласились бы его взять.\n\nПродолжай в том же духе, и он станет тебе верным другом – пусть он и не очень хорошо летает.', '', 28153),
(152491, 'ruRU', '', 'Г\'ууну... нужна... эта сила...', 28153),
(152490, 'ruRU', '', 'Эта энергия придает нам сил! Ты ничего не сможешь сделать!', 28153),
(152489, 'ruRU', 'Помощь', 'Помощь', 28153),
(152488, 'ruRU', 'Потрошение', 'Потрошение', 28153),
(152487, 'ruRU', 'Иногда кажется, что все обитатели этих болот охотятся на нас. Хорошо, что у нас есть ты!', '', 28153),
(152486, 'ruRU', 'У меня плохое предчувствие... Наши разведчики уже давно должны были вернуться. Выясни, что их задержало.', '', 28153),
(152484, 'ruRU', '', 'Идем дальше.', 28153),
(152483, 'ruRU', '', 'Когда-то давно в эту долину нас привел его отец.', 28153),
(152482, 'ruRU', '', 'Конечно, нет. Это голоса свели его с ума.', 28153),
(152481, 'ruRU', '', 'Лорд Штормсонг всегда был... таким?', 28153),
(152480, 'ruRU', '', 'Нас все-таки заметили.', 28153),
(152479, 'ruRU', '', 'Ты что, бросишь меня тут умирать?!', 28153),
(152478, 'ruRU', 'В этом камне заключена сила самой Азшары! Отнеси его в форт, там разберутся, что с ним делать.', '', 28153),
(152477, 'ruRU', 'Спасибо. Но нам лучше убраться отсюда!', 'Спасибо. Но нам лучше убраться отсюда!', 28153),
(152476, 'ruRU', 'Нет уж, я – не еда для маленьких терродактилей!', 'Нет уж, я – не еда для маленьких терродактилей!', 28153),
(152475, 'ruRU', 'Командир с меня шкуру снимет за то, что попался зверям.', 'Командир с меня шкуру снимет за то, что попалась зверям.', 28153),
(152474, 'ruRU', 'Спасибо! Я думал, что веду себя осмотрительно, но тут на меня налетело одно из этих созданий. Умная девочка.', 'Спасибо! Я думала, что веду себя осмотрительно, но тут на меня налетело одно из этих созданий. Умная девочка.', 28153),
(152473, 'ruRU', 'Ух, как же больно впиваются их когти!', 'Ух, как же больно впиваются их когти!', 28153),
(152472, 'ruRU', 'Эти проклятые терродактили – сущее наказание. Я не хочу, чтобы мои войска сожрали!', 'Эти проклятые терродактили – сущее наказание. Я не хочу, чтобы мои войска сожрали!', 28153),
(152471, 'ruRU', 'Эти проклятые терродактили – сущее наказание. Я не хочу, чтобы мои войска сожрали!', 'Эти проклятые терродактили – сущее наказание. Я не хочу, чтобы мои войска сожрали!', 28153),
(152470, 'ruRU', 'Я думал, мы сможем от них избавиться и занять выгодную позицию на холме, но нас уносят по одному, как мышей.', 'Я думала, мы сможем от них избавиться и занять выгодную позицию на холме, но нас уносят по одному, как мышей.', 28153),
(152469, 'ruRU', 'Могу... найдут... больше камней...', '', 28153),
(152468, 'ruRU', 'Сила этого камня поможет возродить империю могу!', '', 28153),
(152467, 'ruRU', 'Надо же, их было больше, чем я ожидал.', '', 28153),
(152466, 'ruRU', 'Гурубаши довели себя до изуверского бешенства! Смерть станет для них избавлением. Ударь в гонг, и они тут же сбегутся.', '', 28153),
(152465, 'ruRU', 'Среди троллей в этой области наблюдается необычное оживление. Боюсь, атака неизбежна. Надо проредить их войско. Ударь в гонг наверху, чтобы они напали раньше времени!', '', 28153),
(152464, 'ruRU', 'Любая помощь будет весьма кстати.', 'Любая помощь будет весьма кстати.', 28153),
(152463, 'ruRU', 'Дайте мне топор и я всех порублю на кусочки!', '', 28153),
(152462, 'ruRU', 'Да мне хоть плетеный человек, хоть дикие животные... Всех порублю!', '', 28153),
(152461, 'ruRU', 'Култирасцы без боя не сдаются!', '', 28153),
(152460, 'ruRU', 'Спасибо за помощь, друг.', '', 28153),
(152459, 'ruRU', '', 'Мы здесь не одни!', 28153),
(152458, 'ruRU', 'Вперед! Вперед! Вперед!', 'Вперед! Вперед! Вперед!', 28153),
(152457, 'ruRU', 'Так, солдаты, слушайте меня! Атаку на побережье возглавит $n. Вот, возьми это сигнальное ружье и подсвечивай все, что движется.', 'Так, солдаты, слушайте меня! Атаку на побережье возглавит $n. Вот, возьми это сигнальное ружье и подсвечивай все, что движется.', 28153),
(152456, 'ruRU', 'За Альянс!', 'За Альянс!', 28153),
(152455, 'ruRU', 'Убейте этих чужаков, иначе никакой вам надбавки за риск!', '', 28153),
(152454, 'ruRU', 'Выполняется протокол аварийного ремонта...', '', 28153),
(152453, 'ruRU', 'Азерит нас всех приободрит!', '', 28153),
(152452, 'ruRU', 'Бури, малышка, бури!', '', 28153),
(152451, 'ruRU', '', 'Но лучше бы Штормсонг нас там не заметил.', 28153),
(152450, 'ruRU', '', 'Так быстрее.', 28153),
(152449, 'ruRU', '', 'А так... можно?', 28153),
(152448, 'ruRU', '', 'По этой запретной тропе жрецы ходят в Святилище за благословением.', 28153),
(152447, 'ruRU', '', 'Твои раны не затянутся, пока на тебе проклятие!', 28153),
(152446, 'ruRU', '', 'Все не может закончиться так!', 28153),
(152445, 'ruRU', '', 'Без вас мне конец!', 28153),
(152444, 'ruRU', '', 'Нет! Держись!', 28153),
(152443, 'ruRU', 'Внимание! Критически низкий уровень топлива!', '', 28153),
(152442, 'ruRU', 'Внимание! Обнаружен несанкционированный пользователь.', '', 28153),
(152441, 'ruRU', 'Внимание! На вашей лицензии осталось 0 баллов.', '', 28153),
(152440, 'ruRU', 'Вот еще один, приготовься!', 'Вот еще один, приготовься.', 28153),
(152439, 'ruRU', 'Плюй выше – тогда не будет недолетов.', 'Плюй выше – тогда не будет недолетов.', 28153),
(152438, 'ruRU', 'Готовься!', 'Готовься!', 28153),
(152437, 'ruRU', 'Главное - плевать как раз когда они начинают взлетать. Так точно не промахнемся!', 'Главное - плевать как раз когда они начинают взлетать. Так точно не промахнемся!', 28153),
(152436, 'ruRU', 'Побереги-и-ись!', '', 28153),
(152435, 'ruRU', 'Азерит плохо действует на духов стихий. Ну вот и лишняя причина вылечить нашу планету.', '', 28153),
(152434, 'ruRU', 'Вкрапления азерита сводят элементалей земли с ума. Убей несчастных и извлеки азерит из их тел.', '', 28153),
(152433, 'ruRU', 'Они здесь! Поджигайте взрывчатку!', '', 28153),
(152432, 'ruRU', '', 'Камни шевелятся... мы заберем их все!', 28153),
(152431, 'ruRU', '', 'Сила этого камня напитает нашу империю!', 28153),
(152430, 'ruRU', '<Глибб с любопытством взирает на вас. Бранн не решается сказать ему, что он не обезьяна.>', '<Глибб с любопытством взирает на вас. Бранн не решается сказать ему, что он не обезьяна.>', 28153),
(152429, 'ruRU', 'Добро пожаловать в \"Соколиное гнездо\". Благодаря тебе мы справились с нашествием монстров и теперь можем вернуть себе город. Ты можешь оставаться здесь сколько душе угодно.', 'Добро пожаловать в \"Соколиное гнездо\". Благодаря тебе мы справились с нашествием монстров и теперь можем вернуть себе город. Ты можешь оставаться здесь сколько душе угодно.', 28153),
(152428, 'ruRU', 'Похоже, это гоблинское изобретение. В общем, против сетраков сработает!', '', 28153),
(152427, 'ruRU', 'Ниша нашла интересное оружие. Если мы поймем, как с ним управляться, то сможем дать достойный отпор сетракам!', '', 28153),
(152426, 'ruRU', 'Никогда не видел таких чудовищ!', 'Никогда не видела таких чудовищ!', 28153),
(152425, 'ruRU', 'Отсюда можно улететь?', 'Отсюда можно улететь?', 28153),
(152424, 'ruRU', 'Боюсь, что сейчас нет. \n\nЯ пытался улететь, когда все это началось, но они стали обстреливать нас магией с земли. Лионелю подбили крыло, и мы еле-еле смогли вернуться в Соколиный Холм. \n\nМэр Ройстон велел оставаться здесь, пока мы не отвоюем город или пока положение не улучшится.\n\nТак что извиняй, сейчас улететь не выйдет.', 'Боюсь, что сейчас нет. \n\nЯ пыталась улететь, когда все это началось, но они стали обстреливать нас магией с земли. Лионелю подбили крыло, и мы еле-еле смогли вернуться в Соколиный Холм. \n\nМэр Ройстон велел оставаться здесь, пока мы не отвоюем город или пока положение не улучшится.\n\nТак что извиняй, сейчас улететь не выйдет.', 28153),
(152423, 'ruRU', 'Такого я уж точно не ожидал! Наверняка наши маги захотят на это взглянуть. Хорошая работа.', '', 28153),
(152422, 'ruRU', 'Наши разведчики сообщили, что Орда хочет добыть у сетраков какой-то артефакт. А давай-ка попробуем их опередить?', '', 28153),
(152421, 'ruRU', 'Вперед, $n.', '', 28153),
(152420, 'ruRU', 'О-о-о!', '', 28153),
(152417, 'ruRU', '', 'Вот и хорошо! В земле им самое место.', 28153),
(152416, 'ruRU', '', 'Грязные твари... Они выращивают плотоядные растения на крови собственных воинов. Не дай им расплодить чудовищ!', 28153),
(152415, 'ruRU', '<Встать в очередь на островную экспедицию на нормальном уровне сложности группой.>', '<Встать в очередь на островную экспедицию на нормальном уровне сложности группой.>', 28153),
(152414, 'ruRU', '', 'Азерит... будет... нашим!', 28153),
(152413, 'ruRU', '', 'На азерит наложены чары магии крови!', 28153),
(152412, 'ruRU', 'Якорь мне в дышло! Конечно, я за бунт. Я тут уже несколько недель болтаюсь!', 'Якорь мне в дышло! Конечно, я за бунт. Я тут уже несколько недель болтаюсь!', 28153),
(152411, 'ruRU', '', 'Любопытно. Может быть, теперь нам удастся понять, что за странные дела творятся в Назмире и откуда взялись тролли крови.', 28153),
(152410, 'ruRU', '', 'Исследователи просят собирать любые артефакты, чтобы они не попали в руки Орды. Обыщи развалины и принеси мне все, что посчитаешь полезным.', 28153),
(152409, 'ruRU', 'Бунт – это всегда хорошо. Я с вами.', 'Бунт – это всегда хорошо. Я с вами.', 28153),
(152407, 'ruRU', 'Бунт? Я только за, матрос. Король пиратов Зем\'лан заплатит за то, что со мной стало.', 'Бунт? Я только за, матрос. Король пиратов Зем\'лан заплатит за то, что со мной стало.', 28153),
(152406, 'ruRU', 'Если у тебя есть золото, ты можешь потратить его здесь.\n\nПросто не мешай нашим делам, а мы не будем лезть в твои, все ясно?', 'Если у тебя есть золото, ты можешь потратить его здесь.\n\nПросто не мешай нашим делам, а мы не будем лезть в твои, все ясно?', 28153),
(152405, 'ruRU', '', 'Поговори с большими шишками – Клаусом Фэйрвиндом, Кейном Карлайлом, Кланком Маслокапом и Фикси Вихлеточкой.\n\nСкажи, что ты от меня, и спроси, не нужно ли им чем помочь. Мне потребуется их поддержка.\n\nИ если у тебя все, мне нужно еще поговорить с этими добропорядочными гражданами, озабоченными текущим положением дел.', 28153),
(152404, 'ruRU', 'С кем мне лучше поговорить?', 'С кем мне лучше поговорить?', 28153),
(152403, 'ruRU', 'Вдвоем бунт не поднимешь, $p. Собери побольше народу!', '', 28153),
(152402, 'ruRU', 'Где твой хозяин?', '', 28153),
(152401, 'ruRU', 'Ты не очень-то хорошо себя ведешь.', '', 28153),
(152400, 'ruRU', 'Я собирался это съесть.', '', 28153),
(152399, 'ruRU', 'Тебе лучше прекратить.', '', 28153),
(152398, 'ruRU', 'Ты за это ответишь!', 'Ты за это ответишь!', 28153),
(152397, 'ruRU', 'Это не твое!', 'Это не твое!', 28153),
(152396, 'ruRU', 'Эй! А ну выплюнь!', 'Эй! А ну выплюнь!', 28153),
(152395, 'ruRU', 'Мои кости снова восстанут.', '', 28153),
(152394, 'ruRU', 'Восстаньте, мои слуги! Убейте чужака!', '', 28153),
(152393, 'ruRU', 'Стервятники, сюда!.. Вас ждет славный пир...', '', 28153),
(152392, 'ruRU', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t$n |cFFFF0000|Hspell:267343|h[роняет]|h|r сферу!', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t$n |cFFFF0000|Hspell:267343|h[роняет]|h|r сферу!', 28153),
(152391, 'ruRU', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t$n |cFFFF0000|Hspell:267633|h[лишается]|h|r сферы!', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t$n |cFFFF0000|Hspell:267633|h[лишается]|h|r сферы!', 28153),
(152390, 'ruRU', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t%s |cFFFF0000|Hspell:265755|h[получает]|h|r одну из сфер!', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t%s |cFFFF0000|Hspell:265755|h[получает]|h|r одну из сфер!', 28153),
(152389, 'ruRU', 'Я подвешу тебя за ноги и скормлю стервятникам!', '', 28153),
(152388, 'ruRU', 'Сначала придется собрать ребят. Заодно ты поймешь, с кем нам придется сразиться.', '', 28153),
(152387, 'ruRU', 'Значится, бунт!', '', 28153),
(152386, 'ruRU', 'Я хочу спросить кое-что еще.', 'Я хочу спросить кое-что еще.', 28153),
(152385, 'ruRU', 'Эй! Прекрати!', 'Эй! Прекрати!', 28153),
(152384, 'ruRU', 'Уходи!', 'Уходи!', 28153),
(152383, 'ruRU', 'Кыш! Кыш!', 'Кыш! Кыш!', 28153),
(152382, 'ruRU', 'А ну прекрати!', 'А ну прекрати!', 28153),
(152381, 'ruRU', 'Спускайся оттуда!', 'Спускайся оттуда!', 28153),
(152380, 'ruRU', 'Попугай? И никаких воздушных змеев?', 'Попугай? И никаких воздушных змеев?', 28153),
(152379, 'ruRU', '<Тан презрительно усмехается>\n\nПопугаи умнее и интереснее, чем воздушный змей.\n\n<Тан открывает один глаз и смотрит на свою птицу.>\n\nПравда, иногда они поднимают шум просто потому, что захотелось развлечься.', '<Тан презрительно усмехается>\n\nПопугаи умнее и интереснее, чем воздушный змей.\n\n<Тан открывает один глаз и смотрит на свою птицу.>\n\nПравда, иногда они поднимают шум просто потому, что захотелось развлечься.', 28153),
(152378, 'ruRU', 'С тех пор, как тут появилось братство Стальных Волн, все полеты проходят с дозволения Ричарда Торнсейла.\n\nГоворят, так они заботятся о \"секретности\" и \"безопасности\" Порта, но я думаю, он просто хочет контролировать всех и вся.\n\nТак что нужно его разрешение. Если я ослушаюсь, они с меня шкуру спустят, а моей птичке крылья обрежут.\n\n<Тан подается вперед и понижает голос.>\n\nИли можно поставить у руля кого-то еще.', 'С тех пор, как тут появилось братство Стальных Волн, все полеты проходят с дозволения Ричарда Торнсейла.\n\nГоворят, так они заботятся о \"секретности\" и \"безопасности\" Порта, но я думаю, он просто хочет контролировать всех и вся.\n\nТак что нужно его разрешение. Если я ослушаюсь, они с меня шкуру спустят, а моей птичке крылья обрежут.\n\n<Тан подается вперед и понижает голос.>\n\nИли можно поставить у руля кого-то еще.', 28153),
(152377, 'ruRU', 'Отсюда можно добраться по воздуху?', 'Отсюда можно добраться по воздуху?', 28153),
(152376, 'ruRU', 'Помоги мне спуститься. После побега меня очень уж крепко связали.', '', 28153),
(152375, 'ruRU', 'Потрясающе! Я ухожу отсюда!', 'Потрясающе! Я ухожу отсюда!', 28153),
(152374, 'ruRU', 'Может быть, если тебе достанет смелости... Скажи ему, что в следующий раз я принесу шляпу!', '', 28153),
(152373, 'ruRU', 'И где твоя грозность? Вперед, слуга. Укуси эту крысу Олфина, который велел убивать моих детей, – и снова будешь выглядеть как богатеище.', '', 28153),
(152372, 'ruRU', 'Орда здесь? Откуда они взялись?! Кто нас защитит?', 'Орда здесь? Откуда они взялись?! Кто нас защитит?', 28153),
(152371, 'ruRU', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|tМеректа |cFFFF0000|Hspell:264206|h[закапывается]|h|r в землю и пересекает поле боя!', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|tМеректа |cFFFF0000|Hspell:264206|h[закапывается]|h|r в землю и пересекает поле боя!', 28153),
(152370, 'ruRU', 'Спасибо. Без тебя мне бы не поздоровилось!', 'Спасибо. Без тебя мне бы не поздоровилось!', 28153),
(152369, 'ruRU', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t$n $gпопался:попалась; в |cFFFF0000|Hspell:263958|h[клубок змей]|h|r, освободите $gего:ее;!', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t$n $gпопался:попалась; в |cFFFF0000|Hspell:263958|h[клубок змей]|h|r, освободите $gего:ее;!', 28153),
(152368, 'ruRU', 'Тот день, когда на порт Зем\'лана легло проклятие...', '', 28153),
(152367, 'ruRU', 'Возьми мой медальон. Он откроет тебе видение прошлого.', '', 28153),
(152366, 'ruRU', 'С-с-спасибо, $p. М-м-мики – хороший друг.', 'С-с-спасибо, $p. М-м-мики – хороший друг.', 28153),
(152365, 'ruRU', 'Кортек... Я подвел тебя...', '', 28153),
(152364, 'ruRU', 'Можешь загадать последнее желание!', '', 28153),
(152363, 'ruRU', 'Нас... не остановить...', '', 28153),
(152362, 'ruRU', 'Какая наглость! Ты заплатишь за свою неосторожность!', '', 28153),
(152361, 'ruRU', '', 'Твой командир ждет на поле боя.', 28153),
(152360, 'ruRU', 'Это еще не все...', 'Это еще не все...', 28153),
(152359, 'ruRU', 'К нам попал загадочный свиток, который, предположительно, призывает существо невиданной силы. Вдоль берега бродят толпы нежити. Испытай свиток на них.', '', 28153),
(152358, 'ruRU', 'Это еще не все...', 'Это еще не все...', 28153),
(152357, 'ruRU', 'Жизнь... за империю...', 'Жизнь... за империю...', 28153),
(152356, 'ruRU', 'Не может быть...', 'Не может быть...', 28153),
(152355, 'ruRU', 'Пески... не остановятся...', 'Пески... не остановятся...', 28153),
(152354, 'ruRU', 'За меня... отомстят...', 'За меня... отомстят...', 28153),
(152353, 'ruRU', 'Кортек... Я подвел тебя...', 'Кортек... Я подвела тебя...', 28153),
(152352, 'ruRU', 'Вы... не победите...', 'Вы... не победите...', 28153),
(152351, 'ruRU', 'Нас... не остановить...', 'Нас не остановить!', 28153),
(152349, 'ruRU', 'Жизнь... за империю...', 'Жизнь... за империю...', 28153),
(152348, 'ruRU', 'Не может быть...', 'Не может быть...', 28153),
(152347, 'ruRU', 'Пески... не остановятся...', 'Пески... не остановятся...', 28153),
(152346, 'ruRU', 'За меня... отомстят...', 'За меня... отомстят...', 28153),
(152345, 'ruRU', 'Кортек... Я подвел тебя...', 'Кортек... Я подвела тебя...', 28153),
(152344, 'ruRU', 'Вы... не победите...', 'Вы... не победите...', 28153),
(152343, 'ruRU', 'Нас... не остановить...', 'Нас... не остановить...', 28153),
(152342, 'ruRU', '', 'Благодарю. Хорошо, что на тебя всегда можно положиться.', 28153),
(152341, 'ruRU', '', 'Тролли крови напали на форт Победы. Покажи им, что мы такого не прощаем!', 28153),
(152340, 'ruRU', 'Шевелитесь, крысы! Азерит сам себя не добудет!', '', 28153),
(152339, 'ruRU', '', 'Бреннадам сгорел, а с ним и наши дома.', 28153),
(152338, 'ruRU', 'Быстрее, он догоняет нас!', '', 28153),
(152337, 'ruRU', 'Ты напоминаешь мне одного юного хозена. Он, кажется, считал себя королем обезьян. Тоже все время меня донимал.', '', 28153),
(152336, 'ruRU', 'Думаешь, ты сможешь надоесть мне сильнее, чем я тебе?', '', 28153),
(152335, 'ruRU', 'Думаю, нам нужно наладить торговлю со всеми расами. Кроме наг. Ужасные создания.', '', 28153),
(152334, 'ruRU', 'Если найдешь артефакты, неси их мне. Даже не думай использовать их самостоятельно.', '', 28153),
(152333, 'ruRU', 'Хм-м. Могущественные артефакты должны быть в руках старейшин, а не вздорных искателей приключений.', '', 28153),
(152332, 'ruRU', 'Нельзя недооценивать ценность и силу чего угодно возрастом более двух столетий.', '', 28153),
(152331, 'ruRU', 'Да-да-да, давай скорее.', '', 28153),
(152330, 'ruRU', 'Каковы твои расценки на подвиги и возможные расходы на похороны?', '', 28153),
(152329, 'ruRU', 'О, это ты. Мне пригодится твоя помощь.', '', 28153),
(152328, 'ruRU', 'Это... блок-цепь!', '', 28153),
(152327, 'ruRU', 'За этим будущее, парни!', '', 28153),
(152326, 'ruRU', 'Поздравляю, парни, мы скоро разбогатеем!', '', 28153),
(152325, 'ruRU', '', 'Ну же! Не трусь!', 28153),
(152324, 'ruRU', 'Никогда не принимай дары Темной Империи.', '', 28153),
(152323, 'ruRU', 'Быть может, мы еще встретимся на поле боя. Мы будем стоять спина к спине, а враг будет превосходить нас числом и умением. Хи-хи.', '', 28153),
(152322, 'ruRU', 'Мой черед, а ты пока рыбу принеси!', '', 28153),
(152321, 'ruRU', 'Присядь, сестренка!', '', 28153),
(152320, 'ruRU', 'Тебе еще учиться и учиться!', '', 28153),
(152319, 'ruRU', 'Эй! Нечего мне рыбу распугивать!', '', 28153),
(152318, 'ruRU', '', 'Р-ра-ак! Я Па\'ку! Я лечу!', 28153),
(152317, 'ruRU', '', 'Гляди, я Грал!', 28153),
(152316, 'ruRU', '', 'Таз\'окун!', 28153),
(152315, 'ruRU', '', 'У-у-у!', 28153),
(152314, 'ruRU', 'Удачи. Постарайся выжить.', '', 28153),
(152313, 'ruRU', 'Будь осторожней. Или отрасти панцирь.', '', 28153),
(152312, 'ruRU', 'Ты... заплатишь...', 'Ты... заплатишь...', 28153),
(152311, 'ruRU', 'Это... Нечестно...', 'Это... Нечестно...', 28153),
(152310, 'ruRU', 'Вперед, мои последователи! К священным водам приближаются чужаки!', '', 28153),
(152309, 'ruRU', 'Нет... Таверна моя...', 'Нет... Таверна моя...', 28153),
(152308, 'ruRU', 'Как... ты... смеешь...', 'Как... ты... смеешь...', 28153),
(152307, 'ruRU', 'Ты за это расплатишься своей шкурой!', 'Ты за это расплатишься своей шкурой!', 28153),
(152306, 'ruRU', 'Я обожаю заварушки! Больше скажу, порой я совсем не прочь поучаствовать в разборке. Или даже в замесе.', '', 28153),
(152305, 'ruRU', 'А за такое двойная ставка!', 'А за такое двойная ставка!', 28153),
(152304, 'ruRU', 'Похоже, мне придется с тебя взыскать три шкуры!', 'Похоже, мне придется с тебя взыскать три шкуры!', 28153),
(152303, 'ruRU', 'Эй! Тебе это дорого обойдется!', 'Эй! Тебе это дорого обойдется!', 28153),
(152302, 'ruRU', 'Меня пытались застать врасплох столько раз и так коварно, что даже не думай об этом.', '', 28153),
(152301, 'ruRU', 'Смерть – единственное проявление милосердия, на которое могут рассчитывать враги Зем\'лана. И то не все.', '', 28153),
(152300, 'ruRU', 'Копание', 'Копание', 28153),
(152299, 'ruRU', 'Я готов.', 'Я готова.', 28153),
(152298, 'ruRU', '', 'Я не успокоюсь, пока голова лорда Штормсонга не будет висеть среди трофеев на стене.', 28153),
(152297, 'ruRU', '', 'Вот такая огневая мощь нам и нужна!', 28153),
(152296, 'ruRU', 'Хе... честная... сделка...', 'Хе... честная... сделка...', 28153),
(152295, 'ruRU', 'Ты... заплатишь...', 'Ты... заплатишь...', 28153),
(152294, 'ruRU', 'Меня... нельзя... победить...', 'Меня... нельзя... победить...', 28153),
(152293, 'ruRU', 'Но... я здесь главный...', 'Но... я здесь главная...', 28153),
(152292, 'ruRU', 'Думаешь, ты справишься с боссом? Ха! Да я тебя под орех разделаю!', 'Думаешь, ты справишься с боссом? Ха! Да я тебя под орех разделаю!', 28153),
(152291, 'ruRU', 'Я тут главный! Делай, что я говорю!', 'Я тут главная! Делай, что я говорю!', 28153),
(152290, 'ruRU', 'Можно потише? Живой ваш Мики. Дайте поспать.', 'Можно потише? Живой ваш Мики. Дайте поспать.', 28153),
(152289, 'ruRU', 'Я тебя под килем пропущу!', 'Я тебя под килем пропущу!', 28153),
(152288, 'ruRU', 'Никому не по силам справиться со Стальными Волнами!', 'Никому не по силам справиться со Стальными Волнами!', 28153),
(152287, 'ruRU', 'Как ты смеешь!', 'Как ты смеешь!', 28153),
(152286, 'ruRU', 'Если тебе попадутся сокровища, их тоже приноси. Мы наградим тебя за труды.', 'Если тебе попадутся сокровища, их тоже приноси. Мы наградим тебя за труды.', 28153),
(152285, 'ruRU', 'Ты заплатишь...', 'Ты заплатишь...', 28153),
(152284, 'ruRU', 'Никому не по силам справиться со Стальными Волнами...', 'Никому не по силам справиться со Стальными Волнами...', 28153),
(152283, 'ruRU', 'Я до тебя... доберусь...', 'Я до тебя... доберусь...', 28153),
(152282, 'ruRU', 'Прости... босс...', 'Прости... босс...', 28153),
(152281, 'ruRU', 'Тебе здесь не место!', 'Тебе здесь не место!', 28153),
(152280, 'ruRU', 'Что это ты тут вынюхиваешь?!', 'Что это ты тут вынюхиваешь?!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152279, 'ruRU', 'Прочь отсюда!', 'Прочь отсюда!', 28153),
(152278, 'ruRU', 'Эй!', 'Эй!', 28153),
(152277, 'ruRU', '', 'Кстати, суп из акульих плавников диво как хорош. Помогает от панцирного почешуя. О чем мы там говорили?', 28153),
(152276, 'ruRU', '', 'Ну, то есть как \"все\"... Те, у кого водится золотишко. Люди, гоблины, таурены, эльфы – все равно. Золото у всех одинаковое.\n\n<Цеси меряет вас взглядом.>\n\nА! Ты хочешь спросить, буду ли я вести дела с Ордой.\n\nСлушай, мне нужно на жизнь зарабатывать. Если от какого-то корабля случайно отвалился якорь, я продам его первому, кто за ним придет. Так всегда дела делаются. Когда я стану боссом, вести дела в Бухте контрабандистов сможет каждый.\n\nТы ведь не хочешь иметь дело с братством Стальных Волн, да?\n\nМожешь мне поверить – дела сразу пойдут в гору.', 28153),
(152275, 'ruRU', 'У моих детей манеры лучше, чем у тебя.', '', 28153),
(152274, 'ruRU', 'Кого ты имеешь в виду под \"всеми\"?', 'Кого ты имеешь в виду под \"всеми\"?', 28153),
(152271, 'ruRU', 'Не тыкай меня! Если, конечно, не собираешься принести этот палец мне в жертву.', '', 28153),
(152270, 'ruRU', 'Местную таверну наводнили беженцы, но если тебе нужен ночлег, у меня есть свободная комната.', '', 28153),
(152269, 'ruRU', 'Если находишь что-нибудь ценное, неси это Джани всенепременно.', '', 28153),
(152268, 'ruRU', 'Когда ты умрешь, я заберу твое добро?', '', 28153),
(152266, 'ruRU', 'Ищи друзей в самых неожиданных местах. Ха!', '', 28153),
(152265, 'ruRU', 'Вот это по-нашему! Не оставляй эти земли без защиты.', '', 28153),
(152264, 'ruRU', 'Разведчики обнаружили поблизости новую угрозу. Избавься от нее!', '', 28153),
(152263, 'ruRU', '', 'Соберите их и убейте монстра, иначе нам не справиться с флотом Эшвейн!', 28153),
(152262, 'ruRU', '', 'Он был очень достойным тортолланом, как говорится, панцирь ему всегда был мал. Жаль, съела беднягу китовая акула.', 28153),
(152261, 'ruRU', '', 'А я и не заметила, что она храпит. Такой уж у нее голос. Кстати, у моего второго внучка был такой же.', 28153),
(152260, 'ruRU', '', 'Говорят, я несу вздор. Не знаю, вот сестру мою было невозможно слушать. Представь, однажды она заснула на полуслове!', 28153),
(152259, 'ruRU', 'Куча хлама это идеальное место для хранения своих сокровищ, пока ты ищешь другие сокровища.', '', 28153),
(152258, 'ruRU', '', 'Герои нынче такие учтивые.', 28153),
(152257, 'ruRU', '', 'Правда, здорово поболтали?', 28153),
(152256, 'ruRU', '', 'Заходи еще к старушке Ноле.', 28153),
(152255, 'ruRU', '', 'Я тут вспомнила одну историю...', 28153),
(152254, 'ruRU', '', 'Ух, сколько в тебе прыти.', 28153),
(152253, 'ruRU', '', 'Как же я рада тебя видеть.', 28153),
(152252, 'ruRU', 'Трансмогрификатор. Делает самые ужасные идеи не самыми ужасными!', 'Трансмогрификатор. Делает самые ужасные идеи не самыми ужасными!', 28153),
(152251, 'ruRU', 'Каджа-Кола – теперь с настоящей водой!', 'Каджа-Кола – теперь с настоящей водой!', 28153),
(152250, 'ruRU', '', 'Хочешь, расскажу преинтереснейшую историю?', 28153),
(152249, 'ruRU', '', 'Когда добудешь жезл, ищи меня к северу от этой дыры. Ориентир – куча трупов.', 28153),
(152248, 'ruRU', 'Сейчас ты узнаешь, почему меня называют ворчуном.', '', 28153),
(152246, 'ruRU', 'Привет, богатеище.', '', 28153),
(152243, 'ruRU', 'Как я люблю говорить, \"что для одного хлам, для другого лоа\".', '', 28153),
(152241, 'ruRU', '', 'В Назмире много разной нечисти. Но теперь ее стало меньше.', 28153),
(152239, 'ruRU', '', 'Что это за твари?! Истреби их, пока они не заполонили наш лагерь! Возьми это оружие и принимайся за дело!', 28153),
(152232, 'ruRU', 'С тобой приятно дружить! Благодаря тебе в дюнах стало спокойнее.', '', 28153),
(152231, 'ruRU', 'Наши караванщики заметили в дюнах какую-то опасность. Но ты ведь с ней справишься?', '', 28153),
(152230, 'ruRU', 'Друзья, здесь вам придется закончить без меня. Встретимся у Святилища... как только мы с Сэмюэлом доберемся туда.', '', 28153),
(152229, 'ruRU', 'Беседа', 'Беседа', 28153),
(152228, 'ruRU', 'Я сразу разглядел в тебе потенциал. Ну что ж, встретимся на месте.', 'Я сразу разглядела в тебе потенциал. Ну что ж, встретимся на месте.', 28153),
(152227, 'ruRU', 'Удачи тебе! Я контрабандист, а не наемник.', 'Удачи тебе! Я контрабандистка, а не наемница.', 28153),
(152226, 'ruRU', 'Тогда, возможно, пора сделать что-то с братством Стальных Волн.', 'Тогда, возможно, пора сделать что-то с братством Стальных Волн.', 28153),
(152225, 'ruRU', 'Братство Стальных Волн трясет с меня золото, Цеси. Я с трудом свожу концы с концами.', 'Братство Стальных Волн трясет с меня золото, Цеси. Я с трудом свожу концы с концами.', 28153),
(152224, 'ruRU', 'Да начнется охота!', '', 28153),
(152223, 'ruRU', '', 'Мы все еще можем получить с этого прибыль!', 28153),
(152222, 'ruRU', '', 'Эти люди пытались бежать. Должны быть и выжившие.', 28153),
(152221, 'ruRU', 'Это тест.', 'Это тест.', 28153),
(152220, 'ruRU', 'Ударим сейчас, пока лорд Штормсонг в неведении.', '', 28153),
(152219, 'ruRU', '|cFF0000FF(Задание)|r Отправиться в Назмир.', '|cFF0000FF(Задание)|r Отправиться в Назмир.', 28153),
(152218, 'ruRU', '', 'Корабль в твоем распоряжении, $n. Моя команда готова к любым неожиданностям.', 28153),
(152217, 'ruRU', 'Куда нам направить усилия?', '', 28153),
(152216, 'ruRU', 'Да не переживайте. Только представьте, как сладка будет месть, когда вы снова увидите этих ребят.', '', 28153),
(152215, 'ruRU', 'Не расстраивайтесь, мы же не с пустыми руками возвращаемся.', '', 28153),
(152214, 'ruRU', 'Все на борт! Надо сматываться, пока мы корабля не лишились.', '', 28153),
(152213, 'ruRU', 'Ну, всей добычи не соберешь. Вернемся в другой раз.', '', 28153),
(152212, 'ruRU', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|tНекоторые защитные приспособления |cFFFF0000|Hspell:267931|h[перегружены]|h|r!', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|tНекоторые защитные приспособления |cFFFF0000|Hspell:267931|h[перегружены]|h|r!', 28153),
(152211, 'ruRU', 'Мы закончили. Пора выбираться отсюда.', '', 28153),
(152210, 'ruRU', 'Не всякий бой можно выиграть. Такова жизнь.', '', 28153),
(152209, 'ruRU', 'Пора отчаливать. Утрете нос Альянсу в другой раз.', '', 28153),
(152208, 'ruRU', 'Молодцы! Утерли нос врагам! Ха-ха!', '', 28153),
(152207, 'ruRU', 'Готово! Не забудьте помахать ручкой Альянсу. Ха-ха!', '', 28153),
(152206, 'ruRU', 'Трюм заполнен. Поднимаем паруса и отплываем.', '', 28153),
(152205, 'ruRU', 'Вот мы и закончили. А теперь отходим!', '', 28153),
(152204, 'ruRU', 'Грузите, сколько успеете, и отправляемся.', '', 28153),
(152203, 'ruRU', 'На том корабле готовятся к отплытию. Поторопитесь.', '', 28153),
(152202, 'ruRU', 'Кул-тирасский корабль почти заполнен. Нам тоже пора закругляться.', '', 28153),
(152201, 'ruRU', 'Осталось немного. Только давайте без глупостей!', '', 28153),
(152200, 'ruRU', 'Трюм почти заполнен. Осталось еще чуть-чуть.', '', 28153),
(152199, 'ruRU', 'Мы почти закончили! Не останавливайтесь.', '', 28153),
(152198, 'ruRU', 'Ха! Трясет так, что я еле держусь на ногах. Видимо, к нам заявился могущественный элементаль земли, который тоже ищет азерит.', '', 28153),
(152197, 'ruRU', 'Порывы ветра сносят все вокруг. Где-то рядом должен быть неслабый воздушный элементаль. И наверняка с азеритом.', '', 28153),
(152196, 'ruRU', 'Эта метель неспроста. К нам точно заявился повелитель воды. Завалите его побыстрее, ненавижу стужу.', '', 28153),
(152195, 'ruRU', 'Жарковато становится. Видимо сюда за азеритом прибыл повелитель огня. Остудите его пыл, пока паруса не загорелись.', '', 28153),
(152194, 'ruRU', 'Тут явно замешан сильный элементаль. Избавьтесь от него и заберите его азерит.', '', 28153),
(152193, 'ruRU', 'Сегодня стихии против нас. Видимо, им тоже нужен азерит.', '', 28153),
(152192, 'ruRU', 'Мы привлекли внимание мощных элементалей. Остерегайтесь их повелителя.', '', 28153),
(152191, 'ruRU', 'Это не каприз погоды! За нашим азеритом явно пожаловал могучий элементаль.', '', 28153),
(152190, 'ruRU', 'Осталась еще половина. Не расслабляйтесь!', '', 28153),
(152189, 'ruRU', 'Полдела сделано. Так держать!', '', 28153),
(152188, 'ruRU', 'Трюм наполовину заполнен. Продолжайте в том же духе.', '', 28153),
(152187, 'ruRU', 'Дело приобретает интересный оборот.', '', 28153),
(152186, 'ruRU', 'К нам пожаловали \"друзья\".', '', 28153),
(152185, 'ruRU', 'Будьте начеку, у нас гости.', '', 28153),
(152184, 'ruRU', 'Мы прибыли на место. Азерит ждет. За работу!', '', 28153),
(152183, 'ruRU', 'Корабль встал на якорь. Удачи, и будьте там поаккуратнее.', '', 28153),
(152182, 'ruRU', 'Трапы спущены, друзья. Скоро настроим детектор.', '', 28153),
(152181, 'ruRU', 'Эй, где-то рядом появилось очень много азерита. Бегом туда!', '', 28153),
(152180, 'ruRU', 'Из-под земли только что вышла огромная глыба азерита. Бегом к ней!', '', 28153),
(152179, 'ruRU', 'Устройство просто зашкаливает. Где-то рядом очень много азерита.', '', 28153),
(152178, 'ruRU', 'Устройство работает. Отмечаю скопления азерита на вашей карте.', '', 28153),
(152177, 'ruRU', 'Детектор включен. Скопления азерита отмечены на карте.', '', 28153),
(152176, 'ruRU', 'Я просто хотел дать глазам отдохнуть! Уже иду!', '', 28153),
(152175, 'ruRU', 'Все, босс, уже иду обратно в рудники.', '', 28153),
(152174, 'ruRU', 'Спать... так хочется спать...', '', 28153),
(152173, 'ruRU', 'Ой! Ладно, $n, пойду работать!', '', 28153),
(152172, 'ruRU', 'Устраните проклинателей худу и их тотемы заземления.', 'Устраните проклинателей худу и их тотемы заземления.', 28153),
(152171, 'ruRU', 'Новый континент – новая охота на очередного демона.', '', 28153),
(152170, 'ruRU', 'Что я люблю в героях, так это то, что они не подводят.', '', 28153),
(152169, 'ruRU', 'Вот и все! Прекрасная работа! Возвращаемся домой.', '', 28153),
(152168, 'ruRU', 'Трюм набит азеритом! А теперь давайте быстро свалим, пока враги не прознали.', '', 28153),
(152167, 'ruRU', 'Ого! Вы только взгляните на этот улов! Отчаливаем!', '', 28153),
(152166, 'ruRU', 'Орда нас вот-вот обставит! Собирайте азерит как можно быстрее!', '', 28153),
(152165, 'ruRU', 'Я отправляюсь... к Ксибале...', '', 28153),
(152164, 'ruRU', 'Орда почти закончила. Мы станем легкой добычей, если не поспешим.', '', 28153),
(152163, 'ruRU', 'Орда почти закончила. Набирайте, сколько успеете, и отплываем.', '', 28153),
(152162, 'ruRU', 'Корабль Орды почти заполнен азеритом. Как только они закончат, нам тоже придется отчаливать.', '', 28153),
(152161, 'ruRU', 'Мы почти закончили. Все идет по плану, но будьте начеку!', '', 28153),
(152160, 'ruRU', 'Наш трюм искрится и сверкает. Еще немного азерита, и отчаливаем!', '', 28153),
(152159, 'ruRU', 'Трюм почти забит азеритом. Расправляйте паруса! Как закончим, сразу выходим в море!', '', 28153),
(152158, 'ruRU', 'Ура, мы почти закончили! Еще немного, и можем возвращаться!', '', 28153),
(152157, 'ruRU', 'Почему земля трясется? Меня сейчас укачает. Раз тут крутятся элементали земли, где-то рядом и их владыка. Займитесь им, пока меня наизнанку не вывернуло.', '', 28153),
(152156, 'ruRU', 'Паруса не выдержат ураганного ветра. За нашим азеритом явно пожаловали слуги владыки элементалей. С такой компанией мы далеко не уйдем.', '', 28153),
(152155, 'ruRU', 'Г-герои, водный владыка прислал элементалей за нашим азеритом, а я тут з-з-замерзаю. Разберитесь с ними, а то я не захватил шубу.', '', 28153),
(152154, 'ruRU', 'Почему так жарко? А, все понятно. Владыка огня послал своих слуг за азеритом. Чудесно, изумительно. Просто огонь!', '', 28153),
(152153, 'ruRU', 'Половина трюма заполнена. Продолжайте в том же духе, и мы быстро управимся.', '', 28153),
(152152, 'ruRU', 'Трюм наполовину заполнен азеритом. Продолжайте в том же духе!', '', 28153),
(152151, 'ruRU', 'Это священная земля!', '', 28153),
(152150, 'ruRU', 'Я готов.', 'Я готова.', 28153),
(152149, 'ruRU', 'Исследование привело к этим руинам. Лагерь Орды находится у подножья холма к северо-востоку – нам лучше управиться как можно скорее.\n\nМы доберемся до Дыхания Ксибалы раньше них, это я могу гарантировать.\n\nСкажи, когда можно начинать исследование.', '', 28153),
(152148, 'ruRU', 'Детектор заработал! Поглядывайте на карту, там все отмечено.', '', 28153),
(152147, 'ruRU', 'Детектор включен. Отмечаю залежи азерита на карте. Наслаждайтесь.', '', 28153),
(152146, 'ruRU', 'Где-то рядом зарождается огромное скопление азерита. Оно и вызывает эти толчки.', '', 28153),
(152145, 'ruRU', 'Ого. У нас тут нешуточный выброс азерита. Нужно добраться до него раньше Орды.', '', 28153),
(152144, 'ruRU', 'Якорь брошен, трапы спущены. Мы запустим детектор азерита, а вы займитесь встречающими.', '', 28153),
(152143, 'ruRU', 'Мы на месте! Наслаждайтесь видами, а я пока займусь детектором азерита.', '', 28153),
(152142, 'ruRU', 'Мы на месте. Ветерок, конечно, не из приятных. Так что давайте быстренько соберем азерит и отчалим.', '', 28153),
(152141, 'ruRU', 'Похоже, нашим азеритом заинтересовался владыка элементалей. Мы с командой побудем в каютах, пока вы... урегулируете ситуацию.', '', 28153),
(152140, 'ruRU', 'Азерит привлек внимание стихийных созданий, да еще и во главе с владыкой. Но кто первый встал, того и тапки, правильно?', '', 28153),
(152139, 'ruRU', 'Орда тоже прознала про это место. Их корабль прибыл.', '', 28153),
(152138, 'ruRU', 'Похоже, Орда тоже здесь. Осторожней там, ладно?', '', 28153),
(152137, 'ruRU', 'Вижу судно. Золотые... да все золотое! Зандаларский корабль! Орда здесь, будьте начеку.', '', 28153),
(152136, 'ruRU', 'Когда-то я тоже был искателем приключений... А потом поумнел. Ха-ха.', '', 28153),
(152135, 'ruRU', 'Похоже, тебе доводилось бывать в битвах. Хочешь, обменяемся интересными историями?', '', 28153),
(152134, 'ruRU', 'Я помню великую войну между королем Ракой и его сестрой королевой Толой. Ну, некоторые эпизоды. Скажем так, я почти уверен, что война была. Пятьдесят на пятьдесят.', '', 28153),
(152133, 'ruRU', 'Ты напоминаешь мне соратника, с которым мы штурмовали берег Красарангских джунглей во времена третьей династии. Могу мало что от него оставили.', '', 28153),
(152132, 'ruRU', 'Не лучший день для Клювика! Арр!', '', 28153),
(152131, 'ruRU', 'Вот поэтому я и не люблю напарников.', '', 28153),
(152130, 'ruRU', 'Когда ты назвался \"Проклятьем Скверны\", я подумал, это тебя скверной прокляли, а не наоборот.', '', 28153),
(152129, 'ruRU', 'Пора их взорвать!', '', 28153),
(152128, 'ruRU', '\"Поехали в джунгли\", – говорил ты. \"Полюбуемся видами\", – говорил ты. Надо было догадаться, что это все доведет нас до беды.', '', 28153),
(152127, 'ruRU', 'Если мы погибнем, я буду винить тебя.', '', 28153),
(152126, 'ruRU', 'Я слышал, что ты где-то неподалеку.$b$bБлагодаря... опрометчивости... не моей, а Мариуса, мы попали в эту сырую дыру, а тут не только полно тварей, которые обожают глодать кости, но и жуткая демоница.$b$bПомоги нам, и потом сможешь забрать все, что у нее найдется.$b$bНам нужен только клочок бумаги. Нет смысла его читать – там ничего интересного.', '', 28153),
(152125, 'ruRU', 'Арр! Все для вас!', '', 28153),
(152124, 'ruRU', 'Клювик хочет рыбки!', '', 28153),
(152123, 'ruRU', 'Хватит драться! Мой человек!', '', 28153),
(152122, 'ruRU', 'Вы ничему не учитесь.', '', 28153),
(152121, 'ruRU', 'Может, не стоило так часто их повторять. Арр!', '', 28153),
(152120, 'ruRU', 'Сто якорей... тебе в корму...', 'Сто якорей... тебе в корму...', 28153),
(152119, 'ruRU', '', 'Ну ладно, ладно, согласна.', 28153),
(152118, 'ruRU', '', 'Лети сюда, Клювик, хватит бездельничать!', 28153),
(152117, 'ruRU', '', 'Отстань, птица, мне не нужна помощь!', 28153),
(152116, 'ruRU', '', 'Даже не больно. Это все, что ты можешь, акулья приманка?', 28153),
(152115, 'ruRU', 'Ха! Я как раз думал, на ком бы злость сорвать.', 'Ха! Я как раз думала, на ком бы злость сорвать.', 28153),
(152114, 'ruRU', '', 'Я была вежлива до невозможности... пока они не отказались выполнять команды...', 28153),
(152113, 'ruRU', '', 'Что значит \"вы\"?', 28153),
(152112, 'ruRU', '', 'А не пойти ли им с моего корабля? Ты уж поверь – я перестрою \"Большой рог\" и насажу на бушприт головы всех предателей!', 28153),
(152111, 'ruRU', '', 'Бесполезные отбросы!', 28153),
(152110, 'ruRU', 'Она будет править... вечно...', 'Она будет править... вечно...', 28153),
(152109, 'ruRU', 'Я... все равно... сильнее...', 'Я... все равно... сильнее...', 28153),
(152108, 'ruRU', 'Орда... всегда будет... принадлежать... ей...', 'Орда... всегда будет... принадлежать... ей...', 28153),
(152107, 'ruRU', 'Что... опять?..', 'Что... опять?..', 28153),
(152106, 'ruRU', 'Смерть – единственный выход!', 'Смерть – единственный выход!', 28153),
(152105, 'ruRU', 'Слышишь крики?', 'Слышишь крики?', 28153),
(152104, 'ruRU', 'Никого не щадить!', 'Никого не щадить!', 28153),
(152103, 'ruRU', 'За Темную Госпожу!', 'За Темную Госпожу!', 28153),
(152102, 'ruRU', 'Лок\'тар огар!', 'Лок\'тар огар!', 28153),
(152101, 'ruRU', 'Лок\'нараш!', 'Лок\'нараш!', 28153),
(152100, 'ruRU', 'Гакара ма!', 'Гакара ма!', 28153),
(152099, 'ruRU', 'Победа или смерть!', 'Победа или смерть!', 28153),
(152098, 'ruRU', 'За Орду!', 'За Орду!', 28153),
(152097, 'ruRU', 'Смерть нашим врагам!', 'Смерть нашим врагам!', 28153),
(152096, 'ruRU', 'Сегодня ты умрешь!', 'Сегодня ты умрешь!', 28153),
(152095, 'ruRU', 'Достойная... смерть...', 'Достойная... смерть...', 28153),
(152094, 'ruRU', 'Предки... я иду к вам...', 'Предки... я иду к вам...', 28153),
(152093, 'ruRU', 'Вам не выиграть... эту войну...', 'Вам не выиграть... эту войну...', 28153),
(152092, 'ruRU', 'Вас всех ждет... смерть...', 'Вас всех ждет... смерть...', 28153),
(152091, 'ruRU', 'Я умру... как воин...', 'Я умру... как воин...', 28153),
(152090, 'ruRU', 'Моя битва... окончена...', 'Моя битва... окончена...', 28153),
(152089, 'ruRU', 'Жизнь... за Дренор...', 'Жизнь... за Дренор...', 28153),
(152088, 'ruRU', 'Иди своей дорогой.', 'Иди своей дорогой.', 28153),
(152087, 'ruRU', 'Ступай.', 'Ступай.', 28153),
(152086, 'ruRU', 'Не подведи Орду.', 'Не подведи Орду.', 28153),
(152085, 'ruRU', 'Умри достойно.', 'Умри достойно.', 28153),
(152084, 'ruRU', 'Мне больше нечего сказать.', 'Мне больше нечего сказать.', 28153),
(152083, 'ruRU', 'Уходи.', 'Уходи.', 28153),
(152082, 'ruRU', 'Иди с честью.', 'Иди с честью.', 28153),
(152081, 'ruRU', 'Да не затупятся твои клинки.', 'Да не затупятся твои клинки.', 28153),
(152080, 'ruRU', 'Иди! Побеждай!', 'Иди! Побеждай!', 28153),
(152079, 'ruRU', 'Помни о долге.', 'Помни о долге.', 28153),
(152078, 'ruRU', 'Что тебе нужно?', 'Что тебе нужно?', 28153),
(152077, 'ruRU', 'У меня нет времени на глупости.', 'У меня нет времени на глупости.', 28153),
(152076, 'ruRU', 'Ну? Я жду...', 'Ну? Я жду...', 28153),
(152075, 'ruRU', 'Говори.', 'Говори.', 28153),
(152074, 'ruRU', 'Рад встрече.', 'Рада встрече.', 28153),
(152073, 'ruRU', 'Лок\'тар!', 'Лок\'тар!', 28153),
(152072, 'ruRU', 'Тром-ка!', 'Тром-ка!', 28153),
(152071, 'ruRU', 'Чего тебе?', 'Чего тебе?', 28153),
(152070, 'ruRU', 'Заг-заг.', 'Заг-заг.', 28153),
(152069, 'ruRU', 'Сила и честь.', 'Сила и честь.', 28153),
(152068, 'ruRU', 'Вы на Азероте все такие надоедливые?', 'Вы на Азероте все такие надоедливые?', 28153),
(152067, 'ruRU', 'Мое хобби – давить назойливых букашек. Просто предупреждаю.', 'Мое хобби – давить назойливых букашек. Просто предупреждаю.', 28153),
(152066, 'ruRU', 'Ты выводишь меня из себя. А это очень плохо.', 'Ты выводишь меня из себя. А это очень плохо.', 28153),
(152065, 'ruRU', 'Орк... крушить!', 'Орк... крушить!', 28153),
(152064, 'ruRU', 'Видимо, сражаются с прислужниками ковена за стенами.', '', 28153),
(152063, 'ruRU', '', 'А где остальные инквизиторы?', 28153),
(152062, 'ruRU', 'Лок\'тар огар!', 'Лок\'тар огар!', 28153),
(152061, 'ruRU', 'Моя ярость сметет тебя!', 'Моя ярость сметет тебя!', 28153),
(152060, 'ruRU', 'Твоя судьба предрешена!', 'Твоя судьба предрешена!', 28153),
(152059, 'ruRU', 'На колени перед Ордой!', 'На колени перед Ордой!', 28153),
(152058, 'ruRU', 'За Орду!', 'За Орду!', 28153),
(152057, 'ruRU', 'Смерть нашим врагам!', 'Смерть нашим врагам!', 28153),
(152056, 'ruRU', 'Сегодня ты умрешь!', 'Сегодня ты умрешь!', 28153),
(152055, 'ruRU', 'Достойная... смерть...', 'Достойная... смерть...', 28153),
(152054, 'ruRU', 'Предки... я иду к вам...', 'Предки... я иду к вам...', 28153),
(152053, 'ruRU', 'Вам не выиграть... эту войну...', 'Вам не выиграть... эту войну...', 28153),
(152052, 'ruRU', 'Вас всех ждет... смерть...', 'Вас всех ждет... смерть...', 28153),
(152051, 'ruRU', 'Духи... заберите меня...', 'Духи... заберите меня...', 28153),
(152050, 'ruRU', 'Моя битва... окончена...', 'Моя битва... окончена...', 28153),
(152049, 'ruRU', 'Мой дух возвращается... на Дренор...', 'Мой дух возвращается... на Дренор...', 28153),
(152048, 'ruRU', 'Возвращайся и приноси побольше денег.', 'Возвращайся и приноси побольше денег.', 28153),
(152047, 'ruRU', 'Пусть мои товары тебе пригодятся.', 'Пусть мои товары тебе пригодятся.', 28153),
(152046, 'ruRU', 'Приходи еще.', 'Приходи еще.', 28153),
(152045, 'ruRU', 'Умри достойно.', 'Умри достойно.', 28153),
(152044, 'ruRU', 'Я все сказал.', 'Я все сказала.', 28153),
(152043, 'ruRU', 'Мы закончили.', 'Мы закончили.', 28153),
(152042, 'ruRU', 'Иди с честью.', 'Иди с честью.', 28153),
(152041, 'ruRU', 'Да направят тебя духи!', 'Да направят тебя духи!', 28153),
(152040, 'ruRU', 'Иди! Побеждай!', 'Иди! Побеждай!', 28153),
(152039, 'ruRU', 'Да будет так.', 'Да будет так.', 28153),
(152038, 'ruRU', 'Что тебя интересует?', 'Что тебя интересует?', 28153),
(152037, 'ruRU', 'Чего тебе надо?', 'Чего тебе надо?', 28153),
(152036, 'ruRU', 'Взгляни, что у меня есть.', 'Взгляни, что у меня есть.', 28153),
(152035, 'ruRU', 'Говори.', 'Говори.', 28153),
(152034, 'ruRU', 'Рад встрече.', 'Рада встрече.', 28153),
(152033, 'ruRU', 'Лок\'тар!', 'Лок\'тар!', 28153),
(152032, 'ruRU', 'Тром-ка!', 'Тром-ка!', 28153),
(152031, 'ruRU', 'Чего тебе?', 'Чего тебе?', 28153),
(152030, 'ruRU', 'Заг-заг.', 'Заг-заг.', 28153),
(152029, 'ruRU', 'Сила и честь.', 'Сила и честь.', 28153),
(152028, 'ruRU', 'Вы на Азероте все такие надоедливые?', 'Вы на Азероте все такие надоедливые?', 28153),
(152027, 'ruRU', 'Мое хобби – давить назойливых букашек. Просто предупреждаю.', 'Мое хобби – давить назойливых букашек. Просто предупреждаю.', 28153),
(152026, 'ruRU', 'Ты выводишь меня из себя. А это очень плохо.', 'Ты выводишь меня из себя. А это очень плохо.', 28153),
(152025, 'ruRU', 'Орк... крушить!', 'Орк... крушить!', 28153),
(152024, 'ruRU', 'Готовлю свежую рыбу. Вкуснее ничего в мире не бывает.', '', 28153),
(152023, 'ruRU', '', 'Мы отправились в путь в надежде уйти от всего этого. Забавно, как далеко мы забрались. Виды тут просто потрясающие.', 28153),
(152017, 'ruRU', 'Как он разорвал цепи?!', 'Как он разорвал цепи?!', 28153),
(152016, 'ruRU', 'Выяснять ничего не будем!', 'Выяснять ничего не будем!', 28153),
(152015, 'ruRU', 'Заражение крови!', '', 28153),
(152014, 'ruRU', 'Изучение цветка', 'Изучение цветка', 28153),
(152013, 'ruRU', 'С аватары Сетралисс снята порча! Полностью восстановите ее здоровье, чтобы отключить защиту!', 'С аватары Сетралисс снята порча! Полностью восстановите ее здоровье, чтобы отключить защиту!', 28153),
(152012, 'ruRU', 'Эволюция!', '', 28153),
(152011, 'ruRU', 'Заражение!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152010, 'ruRU', 'Чума распространяется!', '', 28153),
(152009, 'ruRU', 'Насильственное вызревание!', '', 28153),
(152008, 'ruRU', 'Поглотить останки!', '', 28153),
(152007, 'ruRU', 'Ну все! Сейчас Орда получит.', '', 28153),
(152006, 'ruRU', 'Смертельный штамм. Оптимален для заражения.', '', 28153),
(152005, 'ruRU', 'Я потерял маскировку! Есть еще свиток?', 'Я потеряла маскировку! Есть еще свиток?', 28153),
(152004, 'ruRU', 'Джунглевый большерот прыгает в воду!', '', 28153),
(152003, 'ruRU', 'Гной!', '', 28153),
(152002, 'ruRU', 'Подойдет для заражения!', '', 28153),
(152001, 'ruRU', 'Вспышка неизбежна...', '', 28153),
(152000, 'ruRU', '', 'Прекрасно. Пф! Ничего прекрасного в этом нет.', 28153),
(151999, 'ruRU', '', 'Подлый зачинщик Мистер Доб\'ряк уже найден?', 28153),
(151998, 'ruRU', 'Новые носители!', '', 28153),
(151990, 'ruRU', 'А я... заберу свой трофей.', '', 28153),
(151989, 'ruRU', 'Жемчужина у нас! Теперь нашим кораблям не будет равных!', '', 28153),
(151987, 'ruRU', '', 'Посмотрим, кто окажется сильнее.', 28153),
(151986, 'ruRU', 'Таков закон природы. Сильные отнимают у слабых.', '', 28153),
(151985, 'ruRU', 'Будьте настороже. Я чувствую невидимую угрозу.', '', 28153),
(151983, 'ruRU', 'Не дайте Альянсу ее заполучить. Смерть всем, кто встанет у нас на пути!', '', 28153),
(151982, 'ruRU', '', 'Мне вернули мое дело, так что да. С Цеси в начальницах мы снова начнем зарабатывать настоящие деньги.', 28153),
(151981, 'ruRU', 'А что если поддержать Шальную Цеси?', 'А что если поддержать Шальную Цеси?', 28153),
(151980, 'ruRU', '', 'Раньше это место приносило больше прибыли.', 28153),
(151979, 'ruRU', '', 'Уходим, иначе мы окажемся в ловушке. Скорее!', 28153),
(151978, 'ruRU', 'Дом Штормсонгов будет править этими землями во имя Матери волн!', '', 28153),
(151977, 'ruRU', 'Флот... принадлежит госпоже...', '', 28153),
(151976, 'ruRU', 'Я просто играл с ними, мой господин. Будет сделано!', '', 28153),
(151975, 'ruRU', 'Скоро решится наша судьба. Не дай им попасть в Святилище Штормов!', '', 28153),
(151974, 'ruRU', '', 'Посмотри, что с тобой стало. Сколько крови на твоих руках!', 28153),
(151973, 'ruRU', 'Свиток парит в воздухе и гудит, магия скрывает прочие видения.', '', 28153),
(151972, 'ruRU', 'Гибель души мира: крайне вероятна...', '', 28153),
(151971, 'ruRU', 'Начинается глобальное заражение.', '', 28153),
(151970, 'ruRU', 'Надо было оставить сокровище братству Стальных Волн.', 'Надо было оставить сокровище братству Стальных Волн.', 28153),
(151969, 'ruRU', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s создает |cFFFF0000|Hspell:267891|h[оберег проворства]|h|r!', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s создает |cFFFF0000|Hspell:267891|h[оберег проворства]|h|r!', 28153),
(151968, 'ruRU', '<Просто ударьте его ножом.>', '<Просто ударьте его ножом.>', 28153),
(151967, 'ruRU', 'Серьезно?', 'Серьезно?', 28153),
(151966, 'ruRU', 'Это возмутительно! Я не буду за это платить!', 'Это возмутительно! Я не буду за это платить!', 28153),
(151965, 'ruRU', 'Переночевать на полу – пятьдесят золотых. Шестьдесят, если хочешь лежать у огня. Одеяло неси свое. \n\nКровати по сотне золотых. \n\nПривязать камень возвращения – семьдесят пять золотых в неделю.\n\nЧто, не нравится? \n\n<Хмыкает и с самодовольной ухмылкой скрещивает руки на груди.>\n\nОчень жаль. Но такие вот у нас цены.', '', 28153),
(151964, 'ruRU', 'Глубины шептали, что вы придете... и погибнете!', '', 28153),
(151963, 'ruRU', 'Обнаружен значительный прорыв.', '', 28153),
(151962, 'ruRU', '', 'Нам нужно собрать силы и остановить порчу.', 28153),
(151961, 'ruRU', '', 'Титан отсрочил освобождение Г\'ууна, но ненадолго.', 28153),
(151960, 'ruRU', 'Обнаружена зараженная особь. Требуется немедленный карантин.', '', 28153),
(151959, 'ruRU', 'Пожирать! Поглощать! Заражать!', '', 28153),
(151958, 'ruRU', '', '\"Матриарх\"? У него есть ма\'да?! А вдруг он приведет нас к чему-то, что поможет остановить эту порчу?', 28153),
(151957, 'ruRU', 'Сдерживание Г\'ууна прекращено. МАТРИАРХ не отвечает.', '', 28153),
(151954, 'ruRU', '', 'Если она выйдет на поверхность, нам ее ни за что не сдержать.', 28153),
(151953, 'ruRU', '', 'Впервые встречаю такой вид порчи.', 28153),
(151952, 'ruRU', '', 'Нельзя выпускать ее отсюда! Убейте ее!', 28153),
(151951, 'ruRU', '', 'Фу! Что это за странная тварь?', 28153),
(151950, 'ruRU', '', 'Берегитесь. Кто знает, что обитает в этих пещерах.', 28153),
(151949, 'ruRU', '', 'Тролли крови разбиты. Теперь нам нужно найти и уничтожить источник порчи.', 28153),
(151948, 'ruRU', 'Мы принесли тебе дары, лоа смерти!', '', 28153),
(151947, 'ruRU', 'Если это значит, что к нам придут еще новички, то – да, я согласен.', '', 28153),
(151946, 'ruRU', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t $s начинает использовать заклинание |cFFFF0404|Hspell:260773|h[Ужасный ритуал]|h|r!', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t %s начинает использовать заклинание |cFFFF0404|Hspell:260773|h[Ужасный ритуал]|h|r!', 28153),
(151945, 'ruRU', 'А что если поддержать Шальную Цеси?', 'А что если поддержать Шальную Цеси?', 28153),
(151944, 'ruRU', 'Ты покупаешь или продаешь?', '', 28153),
(151943, 'ruRU', '', 'Все очень плохо...', 28153),
(151942, 'ruRU', 'С удовольствием. Я заставлю их страдать!', '', 28153),
(151941, 'ruRU', 'Обнаружено заражение. Требуется дезинфекция.', '', 28153),
(151940, 'ruRU', 'Взрыв гнили!', '', 28153),
(151939, 'ruRU', 'Ограничения сняты. Уничтожьте источник инфекции.', '', 28153),
(151938, 'ruRU', 'Слушаюсь, господин. Только разберусь с... вредителями.', 'Слушаюсь, господин. Только разберусь с... вредителями.', 28153),
(151937, 'ruRU', 'Выполняю очистку.', '', 28153),
(151936, 'ruRU', 'Протокол очищения активирован.', '', 28153),
(151935, 'ruRU', 'Нагноение!', '', 28153),
(151934, 'ruRU', 'Всего пара сломанных костей... ничего особенного.', '', 28153),
(151933, 'ruRU', 'Веди нас к вульперам, $p. А мы потащим добычу.', '', 28153),
(151932, 'ruRU', 'Выброс крови!', '', 28153),
(151931, 'ruRU', '', 'Брось оружие! У тебя еще есть выбор!', 28153),
(151930, 'ruRU', 'Разнести... заразу...', '', 28153),
(151929, 'ruRU', 'Гниль!', '', 28153),
(151928, 'ruRU', 'Заражение!', '', 28153),
(151927, 'ruRU', 'Нечистая плоть.', '', 28153),
(151926, 'ruRU', 'Поглотить!', '', 28153),
(151925, 'ruRU', 'Разнести заразу!', '', 28153),
(151924, 'ruRU', 'Смотри, не забудь теперь о своей части сделки...', '', 28153),
(151923, 'ruRU', 'Ха-ха-ха! Видишь, твое величество? Бвонсамди всегда держит слово!', '', 28153),
(151922, 'ruRU', 'Вставайте! Эй, бодрее, бодрее! Хватайте копья – и в бой! ВПЕРЕД!', '', 28153),
(151921, 'ruRU', 'Спокойно, король... Бвонсамди всегда помогает друзьям...', '', 28153),
(151920, 'ruRU', '', 'Теперь за мной не нужно наблюдать. У нас обоих полно работы.', 28153),
(151919, 'ruRU', 'Лодка готова, можем отправляться.', '', 28153),
(151918, 'ruRU', 'Эти предатели хотят отнять у меня трон. Где обещанная помощь? Ты собираешься сдержать слово?', '', 28153),
(151916, 'ruRU', 'Ты молодчага. Я уже чувствую, как Азерот восстанавливает силы.', '', 28153),
(151915, 'ruRU', 'Неподалеку открылось несколько азеритовых ран. Залечи их с помощью Сердца!', '', 28153),
(151913, 'ruRU', 'Убегай, пока можешь!', '', 28153),
(151912, 'ruRU', 'Ай-ай-ай! Зачем так неуважительно обращаться к лоа. Хотя, души, которые я соберу сегодня, будут хорошей платой за это!', '', 28153),
(151911, 'ruRU', 'Теперь ты с нами, $p.\n\nБунт или нок-рея.', '', 28153),
(151910, 'ruRU', 'Бвонсамди, покажись!', '', 28153),
(151909, 'ruRU', 'У Зула слишком много союзников. У меня нет выбора...', '', 28153),
(151908, 'ruRU', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s сосредотачивает внимание на |cFFFF0000|3-5($n)|r и готовится использовать способность |cFFFF0000|Hspell:266951|h[Прорыв]|h|r!', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s сосредотачивает внимание на |cFFFF0000|3-5($n)|r и готовится использовать способность |cFFFF0000|Hspell:266951|h[Прорыв]|h|r!', 28153),
(151907, 'ruRU', 'Оберег древних, защищавший Сердце Сетралисс, был снят зандаларами...', 'Оберег древних, защищавший Сердце Сетралисс, был снят зандаларами...', 28153),
(151906, 'ruRU', 'Да, Цеси может рассчитывать на мою полную поддержку.', '', 28153),
(151905, 'ruRU', 'А ну за работу, ленивые гоблины, разберитесь уже с этой коробкой!', 'А ну за работу, ленивые гоблины, разберитесь уже с этой коробкой!', 28153),
(151904, 'ruRU', 'Ты поддерживаешь Шальную Цеси?', 'Ты поддерживаешь Шальную Цеси?', 28153),
(151902, 'ruRU', 'Хм... Да. Дай посмотрю.\n\n<Кууда долго копается в рюкзаке, а потом вытаскивает банку.>\n\nКупил его пару сотен лет назад. И совсем о нем забыл. Наверное, его можно и продать.', '', 28153),
(151901, 'ruRU', 'Тебе не попадалась штука под названием \"соус столетий\"? Может, поделишься?', 'Тебе не попадалась штука под названием \"соус столетий\"? Может, поделишься?', 28153),
(151900, 'ruRU', 'Приветствую, |3-6($r)! Есть что-нибудь интересное на продажу?', '', 28153),
(151899, 'ruRU', 'Клянусь приливом!', 'Клянусь приливом!', 28153),
(151898, 'ruRU', 'Голод не утолить, король пирует.', '', 28153),
(151897, 'ruRU', 'Рана гноится. Мир разлагается.', '', 28153),
(151896, 'ruRU', 'Мы всегда были у тебя в голове.', '', 28153),
(151895, 'ruRU', 'Мерзкие крики огласят его приход.', '', 28153),
(151894, 'ruRU', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|tЗаназал Мудрый начинает использовать способность |cFFFF0000|Hspell:267273|h[Выброс яда]|h|r!', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|tЗаназал Мудрый начинает использовать способность |cFFFF0000|Hspell:267273|h[Выброс яда]|h|r!', 28153),
(151893, 'ruRU', '', 'Ползучие пробудились!', 28153),
(151892, 'ruRU', '', 'Крил лакс кутолил!', 28153),
(151890, 'ruRU', 'Благодаря тебе мой храм спасен – наги ему больше не угрожают.', '', 28153),
(151889, 'ruRU', '', 'О! Я давным-давно хотела попробовать соус столетий! Это паста из разных ингредиентов, которую настаивают многие столетия. Чем дольше она настаивается, тем сложнее вкус. Говорят, это потрясающая приправа, подходящая к любому блюду.\n\nХодят слухи, ее можно купить у некоторых тортолланских торговцев, но она редкая и очень дорогая.\n\n<Сюнь-Сюнь вздыхает с тоской.>\n\nТакой ингредиент – это мечта повара!', 28153),
(151888, 'ruRU', 'Какой большой выбор. У тебя есть все специи? Может, чего-то не хватает?', 'Какой большой выбор. У тебя есть все специи? Может, чего-то не хватает?', 28153),
(151887, 'ruRU', '', 'О, вижу новое лицо! И кажется, дружелюбно настроенное. Хочешь попробовать что-нибудь особенное? Или, может, ищешь редкие специи или рецепты?', 28153),
(151886, 'ruRU', 'Благодаря тебе Сердце Азерот станет сильнее. Мы на шаг ближе к тому, чтобы исцелить планету.', '', 28153),
(151885, 'ruRU', 'Чую рядом источник азерита... и кто-то уже пытается добыть его для своих грязных целей!', '', 28153),
(151884, 'ruRU', 'Иди сюда, малыш. Успокой свое сердце и помоги мне исцелить этого человека.', '', 28153),
(151883, 'ruRU', '', 'Кровь льется в пучину.', 28153),
(151882, 'ruRU', '', 'Под водой ты найдешь истину.', 28153),
(151881, 'ruRU', '', 'Слушай песнь утопленников.', 28153),
(151880, 'ruRU', '', 'Тьма сочится. Зараза распространяется. Проход открыт.', 28153),
(151879, 'ruRU', '', 'Волны заглушат твои крики!', 28153),
(151878, 'ruRU', '', 'Я наполняю твои легкие!', 28153),
(151877, 'ruRU', '', 'Я буду ждать тебя... во тьме...', 28153),
(151876, 'ruRU', '', 'Ты в моей власти!', 28153),
(151875, 'ruRU', '', 'Твоим друзьям понравилась твоя смерть.', 28153),
(151874, 'ruRU', '', 'Мы навеки в плену бездонных глубин.', 28153),
(151873, 'ruRU', 'В тебе живет только слабость.', '', 28153),
(151872, 'ruRU', 'Вы такие слабые и бесполезные!', '', 28153),
(151871, 'ruRU', 'Твое племя – самое слабое!', '', 28153),
(151870, 'ruRU', 'Как... такое возможно...', '', 28153),
(151869, 'ruRU', 'Ул баша крикс.', '', 28153),
(151868, 'ruRU', '', 'Пусть горит само небо! Разите их!', 28153),
(151867, 'ruRU', 'Низшее создание, покорись... или умри!', '', 28153),
(151866, 'ruRU', '', 'За Орду!', 28153),
(151865, 'ruRU', '', 'Не щадить никого!', 28153),
(151864, 'ruRU', 'Уг\' криш зул Траксас!', '', 28153),
(151863, 'ruRU', '', 'Не прекращать огонь! Наша пехота рассчитывает на вас.', 28153),
(151862, 'ruRU', '', 'Стреляйте!', 28153),
(151861, 'ruRU', 'Эта гробница станет вашей братской могилой!', '', 28153),
(151860, 'ruRU', 'Вам не выстоять против зандаларов!', '', 28153),
(151859, 'ruRU', 'Этот храм станет домом Г\'ууна!', '', 28153),
(151858, 'ruRU', 'Зандалары будут править миром!', '', 28153),
(151857, 'ruRU', '', 'Сюда! Нас ждет славная битва!', 28153),
(151856, 'ruRU', 'Г\'ууна не остановить!', '', 28153),
(151855, 'ruRU', 'Больше крови кровавому богу!', '', 28153),
(151854, 'ruRU', 'Я сам тоже тут покопаюсь. Если что найду – сразу расскажу вам.', '', 28153),
(151853, 'ruRU', 'Слышали? Надо найти источник порчи Древних богов... и разнести его подчистую!', '', 28153),
(151852, 'ruRU', 'Ха, и это лучшие из лучших? Теперь понятно, как ваша империя пала!', '', 28153),
(151850, 'ruRU', 'А то бы и твою тушку заодно в саркофаг запихали.', '', 28153),
(151849, 'ruRU', 'Честь и слава! Я сражаюсь за орден Возрождения Шторма!', 'Честь и слава! Я сражаюсь за орден Возрождения Шторма!', 28153),
(151848, 'ruRU', 'Мой клинок к твоим услугам.', 'Мой клинок к твоим услугам.', 28153),
(151847, 'ruRU', 'Я еще жив!', 'Я еще жива!', 28153),
(151846, 'ruRU', 'Вместе мы остановим этих тварей!', 'Вместе мы остановим этих тварей!', 28153),
(151845, 'ruRU', 'Пока я жив, эта долина будет свободной!', 'Пока я жива, эта долина будет свободной!', 28153),
(151844, 'ruRU', 'Орден Возрождения Шторма зовет, и я иду на зов.', 'Орден Возрождения Шторма зовет, и я иду на зов.', 28153),
(151843, 'ruRU', 'Живи – или умри! Наше время пришло.', 'Живи – или умри! Наше время пришло.', 28153),
(151842, 'ruRU', 'Я с тобой!', 'Я с тобой!', 28153),
(151841, 'ruRU', 'Жаль, что ты не видел гибели своего голема, Зул.', '', 28153),
(151840, 'ruRU', 'Это мы еще посмотрим, трусливый тролль!', '', 28153),
(151839, 'ruRU', 'Скоро они восстанут, а враги Г\'ууна падут!', '', 28153),
(151838, 'ruRU', 'Быть может, у нас все же есть шанс! За Орден Возрождения Шторма!', 'Быть может, у нас все же есть шанс! За орден Возрождения Шторма!', 28153),
(151837, 'ruRU', 'Глупцы! Я уже подчинил древних духов воле своего повелителя.', '', 28153),
(151836, 'ruRU', 'Я слышу песнь бури. Надежда еще жива!', 'Я слышу песнь бури. Надежда еще жива!', 28153),
(151835, 'ruRU', 'Я не один. Не все мы потеряны!', 'Я не одна. Не все мы потеряны!', 28153),
(151834, 'ruRU', 'Не знаю, что это за темная магия, но нам обязательно нужно ее рассеять.', '', 28153),
(151833, 'ruRU', 'Это не наш путь. Мы еще можем остановить лорда Штормсонга!', 'Это не наш путь. Мы еще можем остановить лорда Штормсонга!', 28153),
(151832, 'ruRU', 'Если я не ошибаюсь, тут покоится первый король Зандалара.', '', 28153),
(151831, 'ruRU', 'Ворота пали! В атаку! Вернем Арати Альянсу!', '', 28153),
(151830, 'ruRU', 'Пайк еще жив? Я немедленно отправлюсь к нему.', 'Пайк еще жив? Я немедленно отправлюсь к нему.', 28153),
(151829, 'ruRU', 'Ворота разрушены. Вперед! Вернем Арати Альянсу!', '', 28153),
(151828, 'ruRU', 'Ворота сломаны! Вперед!', '', 28153),
(151827, 'ruRU', '', 'Ворота разрушены! В атаку!', 28153),
(151826, 'ruRU', 'Ворота рухнули. Атакуйте цитадель!', '', 28153),
(151825, 'ruRU', 'Его нужно остановить... ради Зандалара и ради ваших королевств.', '', 28153),
(151824, 'ruRU', 'Ворота разрушены. Теперь черед крепости!', '', 28153),
(151823, 'ruRU', 'Мы должны открыть Святилище Штормов!', 'Мы должны открыть Святилище Штормов!', 28153),
(151822, 'ruRU', 'Его властелин копит силы. Зул хочет, чтобы весь мир служил Кровавому богу.', '', 28153),
(151821, 'ruRU', 'Победа! Нагорье Арати снова наше. Слава Альянсу!', '', 28153),
(151820, 'ruRU', 'Шторм возрождается в моей душе. Я буду сражаться против сил тьмы!', 'Шторм возрождается в моей душе. Я буду сражаться против сил тьмы!', 28153),
(151819, 'ruRU', '', 'Наша победа была неизбежной! За Орду!', 28153),
(151818, 'ruRU', 'Вы избавили меня от страшной участи. Но помните, что Зул – всего лишь пешка.', '', 28153),
(151817, 'ruRU', 'Ползи к своему повелителю! Посмотрим, как он тебя примет!', '', 28153),
(151816, 'ruRU', 'Я знал, что этот день придет. Я последую за остальными.', 'Я знала, что этот день придет. Я последую за остальными.', 28153),
(151815, 'ruRU', 'Никто не может сопротивляться Г\'ууну!', '', 28153),
(151814, 'ruRU', 'Я свободен! Зул больше не имеет власти надо мной!', '', 28153),
(151813, 'ruRU', 'Жалуйся, сколько хочешь, король, но знай, что теперь ты навеки принадлежишь Г\'ууну.', '', 28153),
(151812, 'ruRU', 'Так и быть, я убью этих чужаков... но не смей больше докучать мне своей болтовней.', '', 28153),
(151811, 'ruRU', 'Я всю жизнь сопротивлялся Г\'ууну, и ты посмел подчинить меня после смерти.', '', 28153),
(151810, 'ruRU', 'Замолчи, лживый пророк!', '', 28153),
(151809, 'ruRU', 'Здесь покоится первый король зандаларов. У него был гордый нрав, но и он покорился повелителю!', '', 28153),
(151808, 'ruRU', 'Ты в своем уме?', 'Ты в своем уме?', 28153),
(151807, 'ruRU', 'Говори.', 'Говори.', 28153),
(151806, 'ruRU', 'Но теперь у них появилась общая цель: убить вас.', '', 28153),
(151805, 'ruRU', 'Земля принимает меня.', 'Земля принимает меня.', 28153),
(151804, 'ruRU', 'При жизни они ненавидели друг друга и погибли в междоусобной войне.', '', 28153),
(151803, 'ruRU', 'Перед вами – три властителя, что правили в те времена, когда никто не мог удержать трон в одиночку.', '', 28153),
(151802, 'ruRU', 'Чужакам сюда нельзя.', 'Чужакам сюда нельзя.', 28153),
(151801, 'ruRU', 'Море отступит, и земля поднимется!', 'Море отступит, и земля поднимется!', 28153),
(151800, 'ruRU', 'А для этого голема вы и есть горстка покойников.', '', 28153),
(151799, 'ruRU', 'Им даже пришлось создать големов, которые бы избавлялись от груд мертвых тел в храмах.', '', 28153),
(151798, 'ruRU', 'Тысячи лет назад кровавая порча едва не уничтожила зандаларов.', '', 28153),
(151797, 'ruRU', 'Скоро они восстанут, а враги Г\'ууна падут!', '', 28153),
(151796, 'ruRU', 'Моя сила возрастает. Я уже подчинил древних духов воле своего хозяина.', '', 28153),
(151795, 'ruRU', 'Это гробница первого короля троллей. Хотел бы я лично вас там встретить.', '', 28153),
(151794, 'ruRU', 'Я уже говорил, что не буду участвовать в этом безумии.', 'Я уже говорила, что не буду участвовать в этом безумии.', 28153),
(151793, 'ruRU', 'Я больше на такое не куплюсь.', 'Я больше на такое не куплюсь.', 28153),
(151792, 'ruRU', 'Здесь... уже безопасно?', 'Здесь... уже безопасно?', 28153),
(151791, 'ruRU', 'Мы предприниматели и высококвалифицированные специалисты по логистике. Не то что эти проклятые наемники в красном. Мы не пираты.', '', 28153),
(151790, 'ruRU', '', 'А мы пока вернемся к Кэтрин.', 28153),
(151789, 'ruRU', '', 'Отправьте поисковую группу! Найдите ее!', 28153),
(151788, 'ruRU', '', 'Стой! Нет!', 28153),
(151787, 'ruRU', '', 'Нахальная девчонка! Мы еще поговорим!', 28153),
(151786, 'ruRU', '', 'Все кончено. Тебе некуда бежать.', 28153),
(151785, 'ruRU', '', 'С дороги, болваны!', 28153),
(151784, 'ruRU', '', 'Получи!', 28153),
(151783, 'ruRU', '', 'Твое вмешательство ничего не изменит! Этот город МОЙ!', 28153),
(151782, 'ruRU', 'Побуду здесь, вдруг кто домой вернется!', '', 28153),
(151781, 'ruRU', '', 'Вот стану я боссом и уж точно наведу тут порядок.\n\nКогда братство Стальных Волн уберется отсюда, спокойно торговать здесь смогут все. Вот здорово будет!', 28153),
(151780, 'ruRU', '', 'Ох! Все было куда лучше, пока не появились эти негодяи в красном.', 28153),
(151779, 'ruRU', 'Послушай, я просто зарабатываю себе на жизнь.', '', 28153),
(151778, 'ruRU', 'Торнсейл и его ребята мешают мне вести дела. Если станет хуже, я заберу своих пташек и уберусь восвояси.', '', 28153),
(151777, 'ruRU', 'Я собирался стать богачом...', '', 28153),
(151776, 'ruRU', 'Ты хочешь нас остановить? Я убивал и за меньшее!', '', 28153),
(151775, 'ruRU', '', 'Вам не взять эту рощу!', 28153),
(151774, 'ruRU', '', 'Спасибо. Я думала, что смогу выйти против них одна. Теперь вернусь к Морвину.', 28153),
(151773, 'ruRU', 'Как вы тут все сделали здорово.', '', 28153),
(151772, 'ruRU', 'Мы, тортолланы, очень долго торговали на этом месте. Зандалары возвели тут поселение, но потом для них наступили темные времена. Мы-то, разумеется, переживем любые невзгоды.', '', 28153),
(151771, 'ruRU', 'Буду работать тут. Не надо ходить на опасную дорогу.', '', 28153),
(151770, 'ruRU', 'Лок\'тар огар!', 'Лок\'тар огар!', 28153),
(151769, 'ruRU', 'Лок\'нараш!', 'Лок\'нараш!', 28153),
(151768, 'ruRU', 'Гакара ма!', 'Гакара ма!', 28153),
(151767, 'ruRU', 'На колени перед Ордой!', 'На колени перед Ордой!', 28153),
(151766, 'ruRU', 'За Орду!', 'За Орду!', 28153),
(151765, 'ruRU', 'Смерть нашим врагам!', 'Смерть нашим врагам!', 28153),
(151764, 'ruRU', 'Сегодня ты умрешь!', 'Сегодня ты умрешь!', 28153),
(151763, 'ruRU', 'Достойная... смерть...', 'Достойная... смерть...', 28153),
(151762, 'ruRU', 'Ха! Вижу, ты ждешь приказаний. Брось эту штуку в сундук, и за работу!', '', 28153),
(151761, 'ruRU', 'Предки... я иду к вам...', 'Предки... я иду к вам...', 28153),
(151760, 'ruRU', 'Вам не выиграть... эту войну...', 'Вам не выиграть... эту войну...', 28153),
(151759, 'ruRU', 'Вас всех ждет... смерть...', 'Вас всех ждет... смерть...', 28153),
(151758, 'ruRU', 'Я умру... как воин...', 'Я умру... как воин...', 28153),
(151757, 'ruRU', 'Моя битва... окончена...', 'Моя битва... окончена...', 28153),
(151756, 'ruRU', 'Мой дух возвращается... на Дренор...', 'Мой дух возвращается... на Дренор...', 28153),
(151755, 'ruRU', 'Умри достойно.', 'Умри достойно.', 28153),
(151754, 'ruRU', 'Мне больше нечего сказать.', 'Мне больше нечего сказать.', 28153),
(151753, 'ruRU', 'Уходи.', 'Уходи.', 28153),
(151752, 'ruRU', 'Иди с честью.', 'Иди с честью.', 28153),
(151751, 'ruRU', 'Да не затупятся твои клинки.', 'Да не затупятся твои клинки.', 28153),
(151750, 'ruRU', 'Иди! Побеждай!', 'Иди! Побеждай!', 28153),
(151749, 'ruRU', 'Да будет так.', 'Да будет так.', 28153),
(151748, 'ruRU', 'Говори.', 'Говори.', 28153),
(151747, 'ruRU', 'Рад встрече.', 'Рада встрече.', 28153),
(151746, 'ruRU', 'Лок\'тар!', 'Лок\'тар!', 28153),
(151745, 'ruRU', 'Тром-ка!', 'Тром-ка!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151744, 'ruRU', 'Чего тебе?', 'Чего тебе?', 28153),
(151743, 'ruRU', 'Заг-заг.', 'Заг-заг.', 28153),
(151742, 'ruRU', 'Сила и честь.', 'Сила и честь.', 28153),
(151741, 'ruRU', 'В другой раз купи побольше.', 'В другой раз купи побольше.', 28153),
(151740, 'ruRU', 'Пусть мои товары тебе пригодятся.', 'Пусть мои товары тебе пригодятся.', 28153),
(151739, 'ruRU', 'Товар возврату не подлежит!', 'Товар возврату не подлежит!', 28153),
(151738, 'ruRU', 'Что тебя интересует?', 'Что тебя интересует?', 28153),
(151737, 'ruRU', 'Чего тебе надо?', 'Чего тебе надо?', 28153),
(151736, 'ruRU', 'Взгляни, что у меня есть.', 'Взгляни, что у меня есть.', 28153),
(151735, 'ruRU', 'Вы на Азероте все такие надоедливые?', 'Вы на Азероте все такие надоедливые?', 28153),
(151734, 'ruRU', 'Мое хобби – давить назойливых букашек. Просто предупреждаю.', 'Мое хобби – давить назойливых букашек. Просто предупреждаю.', 28153),
(151733, 'ruRU', 'Ты выводишь меня из себя. А это очень плохо.', 'Ты выводишь меня из себя. А это очень плохо.', 28153),
(151732, 'ruRU', 'Орк... крушить!', 'Орк... крушить!', 28153),
(151731, 'ruRU', 'Иди ко мне, Ребан. Пришло время кормежки!', '', 28153),
(151730, 'ruRU', '<Applause sounds>', '', 28153),
(151729, 'ruRU', '<Yawning sound>', '', 28153),
(151728, 'ruRU', '<Short cheer--Wooooo!>', '', 28153),
