(148644, 'ruRU', 'Может, хватит раскачивать лодку?', 'Может, хватит раскачивать лодку?', 28153),
(148643, 'ruRU', 'Море прокормит нас.', 'Море прокормит нас.', 28153),
(148642, 'ruRU', 'На каждом пути есть препятствия.', 'На каждом пути есть препятствия.', 28153),
(148641, 'ruRU', 'Мы вернем то, что у нас отняли.', 'Мы вернем то, что у нас отняли.', 28153),
(148640, 'ruRU', 'Раньше все было проще.', 'Раньше все было проще.', 28153),
(148639, 'ruRU', 'Любая помощь нам пригодится.', 'Любая помощь нам пригодится.', 28153),
(148638, 'ruRU', 'Издалека, поди, занесло?', 'Издалека, поди, занесло?', 28153),
(148637, 'ruRU', 'Деньги есть? Товар подоспеет.', 'Деньги есть? Товар подоспеет.', 28153),
(148636, 'ruRU', 'Лучшие товары со всего Кул-Тираса.', 'Лучшие товары со всего Кул-Тираса.', 28153),
(148635, 'ruRU', 'Давай покажу свои товары.', 'Давай покажу, что у меня есть.', 28153),
(148634, 'ruRU', 'Удачных странствий.', 'Удачных странствий.', 28153),
(148633, 'ruRU', 'Рад услужить.', 'Рада услужить.', 28153),
(148632, 'ruRU', 'Ты заглядывай!', 'Ты заглядывай!', 28153),
(148631, 'ruRU', 'Пусть беды минуют тебя.', 'Пусть беды минуют тебя.', 28153),
(148630, 'ruRU', 'Ветра в твои паруса!', 'Ветра в твои паруса!', 28153),
(148629, 'ruRU', 'Море знает все ответы.', 'Море знает все ответы.', 28153),
(148628, 'ruRU', 'Счастливого плавания.', 'Счастливого плавания.', 28153),
(148627, 'ruRU', 'День добрый!', 'День добрый!', 28153),
(148626, 'ruRU', 'Здорово!', 'Здорово!', 28153),
(148625, 'ruRU', 'Поднимаем якоря.', 'Поднимаем якоря.', 28153),
(148624, 'ruRU', 'Держи порох сухим.', 'Держи порох сухим.', 28153),
(148623, 'ruRU', 'Честь и верность.', 'Честь и верность.', 28153),
(148622, 'ruRU', 'Что-то случилось?', 'Что-то случилось?', 28153),
(148621, 'ruRU', 'Мы близки к своей цели.', '', 28153),
(148620, 'ruRU', 'На страже Праудмуров и к твоим услугам!', 'На страже Праудмуров и к твоим услугам!', 28153),
(148619, 'ruRU', 'Пусть беды минуют тебя.', 'Пусть беды минуют тебя.', 28153),
(148618, 'ruRU', 'Ветра в твои паруса!', 'Ветра в твои паруса!', 28153),
(148617, 'ruRU', 'Море знает все ответы.', 'Море знает все ответы.', 28153),
(148616, 'ruRU', 'Счастливого плавания.', 'Счастливого плавания.', 28153),
(148615, 'ruRU', 'У слизистой оболочки желудка равазавров есть множество применений. Ее можно варить, коптить, тушить... кажись, пора перекусить.', '', 28153),
(148614, 'ruRU', 'Удачных странствий.', 'Удачных странствий.', 28153),
(148613, 'ruRU', 'Рад услужить.', 'Рада услужить.', 28153),
(148612, 'ruRU', 'Ты заглядывай!', 'Ты заглядывай!', 28153),
(148611, 'ruRU', 'Жена кормит равазавров чем попало! Значит, их желудки любую дрянь стерпят. Мне нужны слизистые оболочки – добудь их, только не попадайся на глаза Лоти.', '', 28153),
(148610, 'ruRU', 'У меня тут много всякой всячины. Выбирай.', 'У меня тут много всякой всячины. Выбирай.', 28153),
(148609, 'ruRU', 'Есть новости?', 'Есть новости?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148608, 'ruRU', 'Лучшие товары со всего Кул-Тираса.', 'Лучшие товары со всего Кул-Тираса.', 28153),
(148607, 'ruRU', 'У меня только лучший товар.', 'У меня только лучший товар.', 28153),
(148606, 'ruRU', 'Чем могу помочь?', 'Чем могу помочь?', 28153),
(148605, 'ruRU', 'Да хранит нас лорд-адмирал!', 'Да хранит нас лорд-адмирал!', 28153),
(148604, 'ruRU', 'Держи ноги в тепле.', 'Держи ноги в тепле.', 28153),
(148603, 'ruRU', 'День добрый!', 'День добрый!', 28153),
(148602, 'ruRU', 'Сейчас бы чайку...', 'Сейчас бы чайку...', 28153),
(148601, 'ruRU', 'Сторонись подворотен.', 'Сторонись подворотен.', 28153),
(148600, 'ruRU', 'Держи верный курс.', 'Держи верный курс.', 28153),
(148599, 'ruRU', 'В городе нынче опасно.', 'В городе нынче опасно.', 28153),
(148598, 'ruRU', 'Крикни, если найдешь что-нибудь! Твое имя будут помнить в веках.', '', 28153),
(148597, 'ruRU', 'Если мы найдем это, император сможет покорить весь мир во славу сетраков! Мне всегда хотелось попутешествовать.', '', 28153),
(148596, 'ruRU', 'Спящий пробудится.', '', 28153),
(148595, 'ruRU', 'Если он действительно проснется, кто-нибудь из нас сможет спастись?', '', 28153),
(148594, 'ruRU', 'Думаешь, ключ действительно существует?', '', 28153),
(148593, 'ruRU', 'Император Кортек верит, что если мы найдем ключ, то сможем снова объединить сетраков.', '', 28153),
(148592, 'ruRU', 'Вы что-нибудь слышали?', '', 28153),
(148591, 'ruRU', 'Занят делами империи, босс.', '', 28153),
(148590, 'ruRU', 'Эти жалкие \"преданные\" скоро покорятся нам.', '', 28153),
(148589, 'ruRU', 'Ну и ветер сегодня.', 'Ну и ветер сегодня.', 28153),
(148588, 'ruRU', 'Надеюсь, ты тут не мерзнешь.', 'Надеюсь, ты тут не мерзнешь.', 28153),
(148587, 'ruRU', 'Надзиратель говорит, что ключ здесь. Чем скорее его найдем, тем скорее выберемся отсюда. Мне здесь не по себе.', '', 28153),
(148586, 'ruRU', 'Держи ноги в тепле.', 'Держи ноги в тепле.', 28153),
(148585, 'ruRU', 'Праудмуры всегда защищали наш народ. Положись на них.', 'Праудмуры всегда защищали наш народ. Положись на них.', 28153),
(148584, 'ruRU', 'Попутного ветра и целого паруса.', 'Попутного ветра и целого паруса.', 28153),
(148583, 'ruRU', 'Боюсь, покой нескоро вернется в наши земли.', 'Боюсь, покой нескоро вернется в наши земли.', 28153),
(148582, 'ruRU', 'Есть новости с материка?', 'Есть новости с материка?', 28153),
(148581, 'ruRU', 'Тяжко дела обстоят, да?', 'Тяжко дела обстоят, да?', 28153),
(148580, 'ruRU', 'Заходи почаще, я регулярно получаю новинки.', 'Заходи почаще, я регулярно получаю новинки.', 28153),
(148579, 'ruRU', 'У нас каждый день новые экзотические товары.', 'У нас каждый день новые экзотические товары.', 28153),
(148578, 'ruRU', 'Заходи в любое время.', 'Заходи в любое время.', 28153),
(148577, 'ruRU', 'Смотри, выбирай.', 'Смотри, выбирай.', 28153),
(148576, 'ruRU', 'Ну что, поговорим о делах?', 'Ну что, поговорим о делах?', 28153),
(148575, 'ruRU', 'Это... не... конец...', '', 28153),
(148574, 'ruRU', 'Слишком поздно...', '', 28153),
(148573, 'ruRU', 'Мы не остановимся...', '', 28153),
(148572, 'ruRU', 'Эта земля... будет нашей...', '', 28153),
(148571, 'ruRU', 'Я возвращаюсь... во Фрос...', '', 28153),
(148570, 'ruRU', 'Поговорим о делах?', 'Поговорим о делах?', 28153),
(148569, 'ruRU', 'Мы отомстим!', '', 28153),
(148568, 'ruRU', 'Пощады не будет!', '', 28153),
(148567, 'ruRU', 'Друсты вернут себе эту землю!', '', 28153),
(148566, 'ruRU', 'Ты склонишься перед Гораком Тулом!', '', 28153),
(148565, 'ruRU', 'Я пробудился!', '', 28153),
(148564, 'ruRU', 'А нет ли у тебя более важных дел?', 'А нет ли у тебя более важных дел?', 28153),
(148563, 'ruRU', 'Слышишь? Кажется, тебя кто-то зовет. Наверняка это очень важно!', 'Слышишь? Кажется, тебя кто-то зовет. Наверняка это очень важно!', 28153),
(148562, 'ruRU', 'Ой-ой... только посмотри на часы. Тебе ведь давно пора?', 'Ой-ой... только посмотри на часы. Тебе ведь давно пора?', 28153),
(148561, 'ruRU', 'Займись делом.', 'Займись делом.', 28153),
(148560, 'ruRU', 'Не сбивайся с курса.', 'Не сбивайся с курса.', 28153),
(148559, 'ruRU', 'Сохраняй спокойствие и делай, что должно.', 'Сохраняй спокойствие и делай, что должно.', 28153),
(148553, 'ruRU', 'Спалим эту дыру дотла!', 'Убивай змеюк! Будь как Ниша!', 28153),
(148552, 'ruRU', 'Желаю удачи.', 'Желаю удачи.', 28153),
(148551, 'ruRU', 'Следующий змеюк мой!', 'Этот меч напьется змеиной крови!', 28153),
(148550, 'ruRU', 'Так приятно снова держать в руках оружие.', 'Пусть боятся вульпер!', 28153),
(148549, 'ruRU', 'Вижу, я тебя очаровал.', 'Вижу, я тебя очаровала.', 28153),
(148548, 'ruRU', 'Чему обязан?', 'Чему обязана?', 28153),
(148547, 'ruRU', '', 'О, самое оно! За Раала не беспокойся, он как-нибудь да переживет.', 28153),
(148546, 'ruRU', '', 'Мой муж не хочет собирать слюну терродактилей для зельеваров. Совсем обленился. Давай ты сходи и набери побольше их желез!', 28153),
(148545, 'ruRU', 'Мда, нашим колдунам теперь будет что изучить.', '', 28153),
(148544, 'ruRU', 'Какие сплетни принес ветер?', 'Какие сплетни принес ветер?', 28153),
(148543, 'ruRU', 'Рад знакомству.', 'Рада знакомству.', 28153),
(148542, 'ruRU', 'Многие тортолланы полегли от рук этих жутких троллей. Но их знания не должны быть утрачены. Отыщи их свитки!', '', 28153),
(148541, 'ruRU', 'На помощь! Меня угнетают!', 'На помощь! Меня угнетают!', 28153),
(148540, 'ruRU', '', 'Этого... не может быть...', 28153),
(148539, 'ruRU', 'Высшая исполнительная власть не должна базироваться на сомнительном водном аттракционе.', 'Высшая исполнительная власть не должна базироваться на сомнительном водном аттракционе.', 28153),
(148538, 'ruRU', '', 'Магия... не спасла меня?', 28153),
(148537, 'ruRU', '', 'Я должна была стать... великой...', 28153),
(148536, 'ruRU', 'Пока их души не свободны, я не могу принять новых служителей. Это вопрос чести.', '', 28153),
(148535, 'ruRU', 'Сидящая в пруду тетка, раздающая мечи, не может служить основой государственного устройства.', 'Сидящая в пруду тетка, раздающая мечи, не может служить основой государственного устройства.', 28153),
(148534, 'ruRU', '', 'Сила... утекает...', 28153),
(148533, 'ruRU', '', 'Мои сестры прикончат тебя...', 28153),
(148532, 'ruRU', '', 'Твоя кровь усилит мои ритуалы.', 28153),
(148531, 'ruRU', '', 'Из тебя выйдет хорошая жертва!', 28153),
(148530, 'ruRU', '', 'Все будут служить ковену!', 28153),
(148529, 'ruRU', '', 'Мать, дай мне силу!', 28153),
(148528, 'ruRU', 'Но когда мои клыки пронзили сердце их предводительницы, она прокляла моих последователей.', '', 28153),
(148527, 'ruRU', '', 'Жизнь за ковен!', 28153),
(148526, 'ruRU', 'Ее смерть меня уже не волнует. Тем меньше народу будет меня отвлекать.', '', 28153),
(148525, 'ruRU', 'Она обратилась к ведьмовству, чтобы отомстить мне...', '', 28153),
(148524, 'ruRU', 'Я истребил всех оставшихся наг. Ни одна не скрылась от моего гнева...', '', 28153),
(148523, 'ruRU', 'Моя работа – это моя жизнь! Не Петула, не Бенджамин, вот – мое наследие.', '', 28153),
(148522, 'ruRU', 'Я поднялся из грязи! И начал это дело, чтобы обеспечить жену и родных.', '', 28153),
(148521, 'ruRU', 'Слава дому Уэйкрестов.', 'Слава дому Уэйкрестов.', 28153),
(148520, 'ruRU', 'Я не всегда был президентом успешной деревообрабатывающей компании.', '', 28153),
(148519, 'ruRU', 'Держись подальше от ведьмовских дел.', 'Держись подальше от ведьмовских дел.', 28153),
(148518, 'ruRU', 'Остерегайся незнакомцев.', 'Остерегайся незнакомцев.', 28153),
(148517, 'ruRU', 'А вот и гости с материка...', 'А вот и гости с материка...', 28153),
(148516, 'ruRU', 'Кто ты, друг или враг?', 'Кто ты, друг или враг?', 28153),
(148515, 'ruRU', 'Чем обязан?', 'Чем обязана?', 28153),
(148514, 'ruRU', 'Много веков назад на мой храм напали наги. Я не успел спасти своих последователей от гибели.', '', 28153),
(148513, 'ruRU', 'Я сочувствую племени Тортака и их бедствиям, но, увы, не могу их защитить.', '', 28153),
(148512, 'ruRU', 'Пусть моря будут к тебе милостивы.', 'Пусть моря будут к тебе милостивы.', 28153),
(148511, 'ruRU', 'На каждом пути есть препятствия.', 'На каждом пути есть препятствия.', 28153),
(148510, 'ruRU', 'Мы вернем то, что у нас отняли.', 'Мы вернем то, что у нас отняли.', 28153),
(148509, 'ruRU', 'Раньше все было проще.', 'Раньше все было проще.', 28153),
(148508, 'ruRU', 'Любая помощь нам пригодится.', 'Любая помощь нам пригодится.', 28153),
(148507, 'ruRU', 'Издалека, поди, занесло?', 'Издалека, поди, занесло?', 28153),
(148506, 'ruRU', 'Мы очистим долину Штормов.', 'Мы очистим долину Штормов.', 28153),
(148505, 'ruRU', 'Бойся того, что таится в глубинах.', 'Бойся того, что таится в глубинах.', 28153),
(148504, 'ruRU', 'Пусть море будет благосклонно к тебе.', 'Пусть море будет благосклонно к тебе.', 28153),
(148503, 'ruRU', 'Мы выстоим перед любой угрозой.', 'Мы выстоим перед любой угрозой.', 28153),
(148502, 'ruRU', 'Я рад всем, кто чтит море.', 'Я рада всем, кто чтит море.', 28153),
(148501, 'ruRU', 'Здесь тебе рады.', 'Здесь тебе рады.', 28153),
(148500, 'ruRU', 'Мы вернем единство Долине Штормов.', 'Мы вернем единство Долине Штормов.', 28153),
(148499, 'ruRU', 'Будь начеку да гляди в оба.', 'Будь начеку да гляди в оба.', 28153),
(148498, 'ruRU', 'Слушай песню шторма.', 'Слушай песню шторма.', 28153),
(148497, 'ruRU', 'Мы не дрогнем.', 'Мы не дрогнем.', 28153),
(148496, 'ruRU', 'Долине Штормов все нипочем.', 'Долине Штормов все нипочем.', 28153),
(148495, 'ruRU', 'Далеко ж тебя занесло.', 'Далеко ж тебя занесло.', 28153),
(148493, 'ruRU', 'Ты тоже. И, кстати, $n, в тебе есть настоящее моджо. Найди меня, если окажешься в Вол\'дуне, хорошо?', '', 28153),
(148492, 'ruRU', 'Прощай, Джин\'Тики. Постарайся остаться в живых.', '', 28153),
(148491, 'ruRU', 'Я разберусь.', '', 28153),
(148490, 'ruRU', 'Договорились. Идем.', '', 28153),
(148489, 'ruRU', 'Ха! Это самый безумный день в моей жизни.', '', 28153),
(148488, 'ruRU', 'Зуладжин мертв! Убираемся отсюда!', '', 28153),
(148487, 'ruRU', 'Прекрасно! Продолжай в том же духе!', '', 28153),
(148486, 'ruRU', 'Фу!', 'Фу!', 28153),
(148485, 'ruRU', 'Не ешь меня!', 'Не ешь меня!', 28153),
(148484, 'ruRU', 'Ой!', 'Ой!', 28153),
(148483, 'ruRU', 'Над чем же работал папа, что получилось такое?..', '', 28153),
(148482, 'ruRU', 'Почему этот мед двигается сам по себе?', '', 28153),
(148481, 'ruRU', '<резко вздыхает> Ох, $p... м-мед что, о-ожил?!', '', 28153),
(148480, 'ruRU', 'Не знаю, кто ты, но спасибо!', 'Не знаю, кто ты, но спасибо!', 28153),
(148479, 'ruRU', 'Сетраки и своей добычи не унесут. Уж я об этом позабочусь!', 'Сетраки и своей добычи не унесут отсюда. Уж я об этом позабочусь!', 28153),
(148478, 'ruRU', 'Время для забавной игры, которую я называю \"Змеи и лисы\"...', 'Время для забавной игры, которую я называю \"Змеи и лисы\"...', 28153),
(148477, 'ruRU', 'О да-а! Наконец-то я свободен! И ты не хочешь меня съесть!', 'О да-а! Наконец-то я свободна! И ты не хочешь меня съесть!', 28153),
(148476, 'ruRU', 'Ну все, теперь я заберу отсюда вдвое больше, чем собирался!', 'Ну все, теперь я заберу отсюда вдвое больше, чем собиралась!', 28153),
(148475, 'ruRU', '', 'Рада, что пески еще не поглотили тебя, $n!', 28153),
(148473, 'ruRU', 'Великий лоа, прими подношение от племени Тортака.', 'Великий лоа, прими подношение от племени Тортака.', 28153),
(148472, 'ruRU', 'Бросай!', '', 28153),
(148471, 'ruRU', 'Не так быстро!', '', 28153),
(148470, 'ruRU', 'Ты об этом пожалеешь.', '', 28153),
(148469, 'ruRU', 'На твоем месте я бы этого не делал.', '', 28153),
(148468, 'ruRU', 'А ну верни!', '', 28153),
(148467, 'ruRU', 'Ну уж нет! Это мое.', '', 28153),
(148466, 'ruRU', 'Брось – это не твое, дружище.', '', 28153),
(148463, 'ruRU', 'Глупое решение.', '', 28153),
(148462, 'ruRU', 'Никогда не откажусь от хорошей драки.', '', 28153),
(148461, 'ruRU', 'Ты заплатишь за это!', '', 28153),
(148460, 'ruRU', 'Эй, ты!', '', 28153),
(148459, 'ruRU', 'Ты об этом пожалеешь!', '', 28153),
(148458, 'ruRU', 'Сегодня не ваш день!', '', 28153),
(148456, 'ruRU', 'Будь начеку.', '', 28153),
(148455, 'ruRU', 'Моя подзорная труба на нижнем уступе с северной стороны кратера.', '', 28153),
(148454, 'ruRU', '', 'Дикорожья диномантия! Удивительно. Надо спрятать их подальше, чтобы Коджо не нашел.', 28153),
(148453, 'ruRU', '', 'Я нашла несколько старых свитков, но не знаю, для чего они. Может, проверишь, как они работают? Это может быть весело.', 28153),
(148452, 'ruRU', 'Используй фетиш! Разнеси его в клочья!', '', 28153),
(148451, 'ruRU', 'Беги!', '', 28153),
(148450, 'ruRU', 'А-а-а!', '', 28153),
(148449, 'ruRU', 'Э-э... что-то не так. Я чую какую-то дурную магию крови...', '', 28153),
(148448, 'ruRU', 'Получилось! Зуладжину конец!', '', 28153),
(148447, 'ruRU', 'Ха! Расскажу об этом Па\'ку!', '', 28153),
(148446, 'ruRU', 'Ночнорожденные придумали, как разобраться с чужаками в Ксибале. Обещают нам зрелище.', '', 28153),
(148420, 'ruRU', '', 'Прекрасно. Может, когда-нибудь эти воды снова станут безопасными.', 28153),
(148419, 'ruRU', '', 'Хватит с нас вашего пения!', 28153),
(148418, 'ruRU', '', 'Отлично, все в сборе. Давайте не будем тратить время впустую.', 28153),
(148416, 'ruRU', 'Старый воин благодарит тебя за помощь. Уверяю, они это заслужили.', '', 28153),
(148415, 'ruRU', 'Эти выродки кромсают тело Торги! Это не может продолжаться! Убей их всех!', '', 28153),
(148414, 'ruRU', '', 'Кто у нас славный зандаларский лицеед? Конечно, ты!', 28153),
(148413, 'ruRU', '', 'Нашим союзникам нужно научиться сражаться. Покажи этому малютке, что такое настоящая битва.', 28153),
(148412, 'ruRU', 'Вот что рассказывают.\n\nОднажды великий лоа, обращаясь к своим последователям, сказал:\n\n\"Как ягуар, подстерегающий жертву по несколько дней, мудрые всегда и во всем действуют терпеливо. Глупцами правят их желания и эмоции, однако глупцам в джунглях долго не прожить.\n\nДжунгли дают дар жизни, но они же дарят смертельное касание. Те, кто способен видеть, знают, что природа не принадлежит им – напротив, они принадлежат ей. Они уважают естественный порядок вещей и берут лишь столько, сколько им нужно, чтобы прожить\".\n\nУслышав эти слова, последователи Эрака но Кимбула преисполнились терпения и уважения.', '', 28153),
(148411, 'ruRU', 'Вот что рассказывают.\n\nОднажды великий лоа, обращаясь к своим последователям, сказал:\n\n\"Король не меняет свое величайшее сокровище на пригоршню грязи – так и честные не отказываются от своей праведности ради славы или богатства. Проживите жизнь с честью, и это будет хорошо прожитая жизнь.\n\nКаньон – результат постоянного тока воды, а все великие дела – результат стойкости. Идите по жизни с непреклонной решимостью, и неудачам вас никогда не сломить\".\n\nУслышав эти слова, последователи Эрака но Кимбула преисполнились добродетели и усердия.', '', 28153),
(148410, 'ruRU', 'Вот что рассказывают.\n\nОднажды великий лоа, обращаясь к своим последователям, сказал:\n\n\"Как тигр, который перепрыгивает камни и пропасти во время охоты, храбрые не теряют времени на то, чтобы трепетать от страха перед лицом опасности. Действуйте храбро всегда и во всем – тогда вы не упустите из виду свою жертву.\n\nКак разложение пожирает цветы в джунглях, старение пожирает силу молодости. Источник могущества – не физическая сила, а несгибаемая воля, которую старению не уничтожить\".\n\nУслышав эти слова, последователи Эрака но Кимбула преисполнились храбрости и решимости.', '', 28153),
(148408, 'ruRU', 'Эрака но Кимбул, лоа тигров, повелитель зверей, король кошек и губитель добычи.', '', 28153),
(148400, 'ruRU', 'Мои шрамы старше, чем твой язык.', '', 28153),
(148399, 'ruRU', 'Мне нужен молодой и крепкий доброволец, готовый сражаться с силами зла... за вознаграждение.', '', 28153),
(148398, 'ruRU', '', 'Хочешь поговорить со старушкой Нолой?', 28153),
(148397, 'ruRU', 'Работа идет полным ходом!', 'Работа идет полным ходом!', 28153),
(148396, 'ruRU', 'Когда мы освободимся, тебе это не понравится.', 'Когда мы освободимся, тебе это не понравится.', 28153),
(148395, 'ruRU', 'Ладно! Ладно!', 'Ладно! Ладно!', 28153),
(148394, 'ruRU', 'Ой! Отцепись!', 'Ой! Отцепись!', 28153),
(148393, 'ruRU', '<Кажется, на статуе есть какие-то отметины. Но даже если они что-то означают, это давно уже невозможно понять.>', '', 28153),
(148392, 'ruRU', '<Кажется, на статуе есть какие-то отметины. Но даже если они что-то означают, это давно уже невозможно понять.>', '<Кажется, на статуе есть какие-то отметины. Но даже если они что-то означают, это давно уже невозможно понять.>', 28153),
(148391, 'ruRU', '<Кажется, на статуе есть какие-то отметины. Но даже если они что-то означают, это давно уже невозможно понять.>', '', 28153),
(148389, 'ruRU', 'Султис погиб, но успел надежно спрятать свой ключ. Тем, кто остался предан Сетралисс, пришлось покинуть свой дом и скрываться. С тех пор мы сражаемся с отступниками.', '', 28153),
(148388, 'ruRU', 'Кортек собрал армию сетраков-единомышленников, которые начали убивать всех несогласных.', '', 28153),
(148387, 'ruRU', '', 'Мы должны предупредить принцессу.', 28153),
(148386, 'ruRU', '', 'Оружие... Так вот что нужно Джакра\'зету! К\'тракси...', 28153),
(148385, 'ruRU', 'Он задумал использовать генерала К\'тракси как оружие и захватить весь континент.', '', 28153),
(148384, 'ruRU', 'С годами Кортеку наскучила наша новая жизнь. Мы никогда не враждовали с соседями-троллями, но Кортек жаждал войны.', '', 28153),
(148383, 'ruRU', 'Долгие годы мы жили в мире, как того желала Сетралисс. Наши земли страдали, наша лоа погибла, но мы приспособились. Мы точно знали, что рано или поздно Сетралисс вернется.', '', 28153),
(148382, 'ruRU', 'Каждый из нас создал по ключу. Чтобы развеять магию, с помощью которой был сотворен барьер, нужно собрать все три ключа вместе. Так мы стали хранителями.', '', 28153),
(148381, 'ruRU', 'Те из нас, кто остался верен Сетралисс, потеряли свой дом и стали изгоями. С тех пор мы и ведем войну с отступниками.', '', 28153),
(148380, 'ruRU', 'Он собрал армию единомышленников, и они начали убивать всех, кто осмеливался противостоять им... Султис пал первым, но успел спрятать свой ключ.', '', 28153),
(148379, 'ruRU', 'Со временем в Кортеке разгорелась жажда завоеваний. Он замыслил вернуть К\'тракси к жизни и с его помощью покорить весь континент.', '', 28153),
(148378, 'ruRU', 'Султис был очень силен, но даже он не смог бы создать барьер в одиночку. Мы с Кортеком помогли ему заточить Митракса внутри великой пирамиды.', '', 28153),
(148377, 'ruRU', 'Увидев, на какие разрушения он был способен, мы решили сделать так, чтобы никто не смог воскресить Митракса.', '', 28153),
(148376, 'ruRU', 'Наша лоа пожертвовала собой, чтобы спасти нас от чудовища. Она сразила К\'тракси, но тот все же успел разрушить диск в сердце Атул\'Амана.', '', 28153),
(148375, 'ruRU', 'Давным-давно в наши земли вторгся Митракс Развоплотитель. Он не щадил никого: ни троллей, ни сетраков.', '', 28153),
(148374, 'ruRU', 'Это ключ первого хранителя. Его звали Султис. И он пал от руки Кортека.', '', 28153),
(148365, 'ruRU', '', 'Ага! Значит, Мэйнард, как всегда, посылает решать проблемы своих громил! Ну что ж, добро пожаловать, громила. Я разберусь с тобой, как и с остальными!', 28153),
(148364, 'ruRU', 'Ведьма... почему ведьма хочет нам навредить?! Мне нужно выбраться отсюда! Я скажу отцу!', '', 28153),
(148361, 'ruRU', 'Франсуа замечает ваш набитый кошелек. Теперь он считает, что вы достойны его внимания.', '', 28153),
(148360, 'ruRU', 'Вы слегка встряхиваете свой кошелек.', 'Вы слегка встряхиваете свой кошелек.', 28153),
(148359, 'ruRU', 'Если ты убьешь этого паука... то поможешь очень многим.', '', 28153),
(148358, 'ruRU', 'Ну... похоже, достаточно этих тварей перебито и я смогу выбраться сам.', '', 28153),
(148357, 'ruRU', 'Франсуа клюет ваши ступни.', '', 28153),
(148356, 'ruRU', 'Император с тобой разберется.', '', 28153),
(148355, 'ruRU', '$Pr, как ты смеешь прерывать мою трапезу! Я убивал и за меньшее.', '', 28153),
(148354, 'ruRU', '<Отдать Воррику камень Султиса.>', '<Отдать Воррику камень Султиса.>', 28153),
(148353, 'ruRU', 'Берег чист! Кто знал, что жабье моджо такое сильное.', '', 28153),
(148352, 'ruRU', 'Наги похищают силу лоа-жабы! Убей их и разрушь их лагерь!', '', 28153),
(148351, 'ruRU', 'Не знаю кто ты, но спасибо тебе. Мои крылатые друзья готовы доставить тебя по воздуху куда угодно.', 'Не знаю кто ты, но спасибо тебе. Мои крылатые друзья готовы доставить тебя по воздуху куда угодно.', 28153),
(148350, 'ruRU', 'Я снова жив! Спасибо тебе. Теперь я всегда к твоим услугам.', 'Я снова жива! Спасибо тебе. Теперь я всегда к твоим услугам.', 28153),
(148349, 'ruRU', 'Благослови тебя Бвонсамди!', 'Благослови тебя Бвонсамди!', 28153),
(148348, 'ruRU', 'Мой камень! Не твой камень!', '', 28153),
(148347, 'ruRU', '', 'Мы должны поговорить с Ворриком.', 28153),
(148345, 'ruRU', 'Остановись. Если они ищут Воррика, возможно, они нам помогут...', '', 28153),
(148344, 'ruRU', 'Я чувствую себя обновленным! Не знаю, кто ты, но благодарю тебя.', 'Я чувствую себя обновленной! Не знаю, кто ты, но благодарю тебя.', 28153),
(148342, 'ruRU', '', 'Вижу, ты привел подкрепление.', 28153),
(148340, 'ruRU', '', 'Без паники. Этот сетрак на нашей стороне.', 28153),
(148339, 'ruRU', 'Да! В том-то все и дело, Нимми, – в раковинах. Раковины нужно ценить.', '', 28153),
(148338, 'ruRU', 'На минуту все прекратилось. Мне было холодно. Мне было жарко... О чем это я?..', '', 28153),
(148337, 'ruRU', 'И Корл, в него попал тот клинок... Его глаза, они просто... Погасли...', '', 28153),
(148336, 'ruRU', 'Плавники и клинки, смех во мраке... Была кровь...', '', 28153),
(148335, 'ruRU', 'Это был скучнейший пост в этом море... До того, как все изменилось... Пришли они...', '', 28153),
(148334, 'ruRU', 'Что ни говори, битва была славная! Просто жуткая!', '', 28153),
(148333, 'ruRU', 'Подожди, ты ведь живое существо, правда? Мне случалось ошибаться на этот счет...', '', 28153),
(148332, 'ruRU', 'Да ладно тебе... все слышали о расселине Скарвина.', '', 28153),
(148331, 'ruRU', 'Что?! Ты ничего не знаешь о расселине Скарвина?', '', 28153),
(148330, 'ruRU', 'Про битву в расселине Скарвина знаешь? Так вот, там, внизу...', '', 28153),
(148329, 'ruRU', 'Итак, мы с Корлом обсуждали эту битву.', '', 28153),
(148328, 'ruRU', 'Ты мне нравишься, мой маленький чешуйчатый друг.', '', 28153),
(148327, 'ruRU', 'Однажды я его видел – было просто здорово!', '', 28153),
(148326, 'ruRU', 'А ты знаешь, что там, под водой, огонь?!', '', 28153),
(148325, 'ruRU', 'Но я сейчас не об этом, на самом деле я хотел сказать...', '', 28153),
(148324, 'ruRU', 'А он не обрадовался. Он просто посмотрел на меня, а потом раздавил краба...', '', 28153),
(148323, 'ruRU', 'Тебе бы это доставило радость, не так ли? Или можно было хотя бы притвориться...', '', 28153),
(148322, 'ruRU', 'Мне от этого стало грустно.', '', 28153),
(148321, 'ruRU', 'Нашел я однажды раковину. Симпатичная была раковина. Рассказал о ней Корлу. Но Корлу было все равно.', '', 28153),
(148320, 'ruRU', 'Мне не нравятся прилипчивые ракушки. Корл говорит что те, кому они нравятся, – злые люди.', '', 28153),
(148318, 'ruRU', 'Сколько же времени прошло с тех пор, как мы с Кортеком вместе доносили мудрость Сетралисс до ее последователей в этих стенах...\n\nНыне святые места в руинах, а Сетралисс в лучшем случае предана забвению, если не проклятию.\n\nКортек, друг мой... Что же ты сотворил с нашим народом?', '', 28153),
(148317, 'ruRU', 'Прилипчивые ракушки – это плохо. Тебе нравятся ракушки, Нимми?', '', 28153),
(148316, 'ruRU', 'Мне не нравятся прилипчивые ракушки, потому что от них у меня чешутся ступни. Корл говорит, что ему они тоже не нравятся.', '', 28153),
(148315, 'ruRU', 'Прилипчивые ракушки – это плохо.', '', 28153),
(148314, 'ruRU', 'Значит, мой друг Корл... знаешь Корла? Так вот, дружище, Корл говорит, что можно избавляться от ракушек с помощью баллисты – просто засовывать ее между пальцев ног.', '', 28153),
(148313, 'ruRU', 'Эй, тебя кто сюда пустил?!', 'Эй, тебя кто сюда пустил?!', 28153),
(148312, 'ruRU', 'Я тебе покажу как связываться с кланом Черного Железа!', 'Я те покажу как связываться с кланом Черного Железа!', 28153),
(148311, 'ruRU', 'Я покажу тебе мощь горы!', 'Я покажу тебе мощь горы!', 28153),
(148310, 'ruRU', 'Щас я тебя подровняю!', 'Щас я тебя подровняю!', 28153),
(148309, 'ruRU', 'Давай, покажи, что можешь!', 'Давай, покажи, что можешь!', 28153),
(148308, 'ruRU', 'Дыши глубже, пока еще можешь!', 'Дыши глубже, пока еще можешь!', 28153),
(148307, 'ruRU', 'Сгори в огне моей ярости!', 'Сгори в огне моей ярости!', 28153),
(148306, 'ruRU', 'Мое... пламя... не... угаснет...', 'Мое... пламя... не... угаснет...', 28153),
(148305, 'ruRU', 'Мой клан... отомстит...', 'Мой клан... отомстит...', 28153),
(148304, 'ruRU', 'Мой дух... вернется... к Наковальне...', 'Мой дух... вернется... к Наковальне...', 28153),
(148303, 'ruRU', 'Мне бы... горло промочить...', 'Мне бы... горло промочить...', 28153),
(148302, 'ruRU', 'Чтоб... тебя...', 'Чтоб... тебя...', 28153),
(148301, 'ruRU', 'Жизнь... за королеву...', 'Жизнь... за королеву...', 28153),
(148300, 'ruRU', 'Я возрожусь... в пламени...', 'Я возрожусь... в пламени...', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148299, 'ruRU', 'Эй, тебя кто сюда пустил?!', 'Эй, тебя кто сюда пустил?!', 28153),
(148298, 'ruRU', 'Я те покажу как связываться с кланом Черного Железа!', 'Я те покажу как связываться с кланом Черного Железа!', 28153),
