(145615, 'ruRU', '', 'Назад! Все назад!', 28153),
(145614, 'ruRU', '', 'Нам сюда.', 28153),
(145613, 'ruRU', '', 'Я укажу путь.', 28153),
(145612, 'ruRU', '', 'За мной.', 28153),
(145611, 'ruRU', '', 'За Орду!', 28153),
(145610, 'ruRU', '', 'Меня тяжело ранили.', 28153),
(145609, 'ruRU', 'Это верный ответ! Осталась всего одна загадка.\n\nМожно?', '', 28153),
(145608, 'ruRU', 'Моя тень.', 'Моя тень.', 28153),
(145607, 'ruRU', '', 'Мне нужно лечение!', 28153),
