(145438, 'ruRU', 'Ага.', '', 28153),
(145437, 'ruRU', 'Маны бы подкопить.', '', 28153),
(145436, 'ruRU', 'Отгадай загадку.\n\nУ чего есть вода, но оно не пьет? Есть и ложе, но сон нейдет? Может бегать, но не ходит? Денег нет – злато находят?', '', 28153),
(145435, 'ruRU', 'Что? Еще столько же?', 'Что? Еще столько же?', 28153),
(145434, 'ruRU', 'Я готов!', 'Я готова!', 28153),
(145433, 'ruRU', 'Да! Тебе удалось преодолеть половину пути.\n\nХочешь продолжить?', '', 28153),
(145432, 'ruRU', 'Завтра.', 'Завтра.', 28153),
(145431, 'ruRU', 'Вождь.', 'Вождь.', 28153),
