(145428, 'ruRU', 'Не совсем!\n\nЖелаешь попробовать еще раз?', '', 28153),
(145427, 'ruRU', 'Сейчас, только маны подкоплю.', '', 28153),
(145426, 'ruRU', 'Премного благодарен!', '', 28153),
