(145352, 'ruRU', 'Некуда класть.', '', 28153),
(145351, 'ruRU', 'Я не смогу нести больше.', '', 28153),
(145350, 'ruRU', 'Заперто.', '', 28153),
(145349, 'ruRU', 'У меня уже достаточно таких предметов.', '', 28153),
(145348, 'ruRU', 'Я пока не могу это использовать.', '', 28153),
(145347, 'ruRU', 'Этот предмет еще не готов.', '', 28153),
(145346, 'ruRU', 'Нужно подождать.', '', 28153),
(145345, 'ruRU', 'Недостаточно гнева.', '', 28153),
(145344, 'ruRU', 'У меня мало гнева.', '', 28153),
(145343, 'ruRU', 'Недостаточно боли.', '', 28153),
(145342, 'ruRU', 'Нужно больше боли.', '', 28153),
(145341, 'ruRU', 'Это не сумка.', '', 28153),
(145340, 'ruRU', 'Мне не хватает средств.', '', 28153),
(145339, 'ruRU', 'Это мне не по карману.', '', 28153),
(145338, 'ruRU', 'Слишком дорого.', '', 28153),
(145337, 'ruRU', 'Не могу пригласить участника другой группы.', '', 28153),
(145336, 'ruRU', 'Не хватает боеприпасов.', '', 28153),
(145335, 'ruRU', 'Недостаточно энергии.', '', 28153),
(145334, 'ruRU', 'Мне не хватает энергии.', '', 28153),
(145333, 'ruRU', 'Мне не хватает маны.', '', 28153),
(145332, 'ruRU', 'У меня мало маны.', '', 28153),
(145331, 'ruRU', 'Мне нужна мана.', '', 28153),
(145330, 'ruRU', 'Недостаточно ярости.', '', 28153),
(145329, 'ruRU', 'Нужно больше ярости.', '', 28153),
(145328, 'ruRU', 'Слишком далеко.', '', 28153),
(145327, 'ruRU', 'Я слишком далеко.', '', 28153),
(145326, 'ruRU', 'Нужно подойти поближе.', '', 28153),
(145325, 'ruRU', 'Мы больше не можем никого пригласить.', '', 28153),
(145324, 'ruRU', 'Я пока не могу выпить больше.', '', 28153),
(145323, 'ruRU', 'Мне пока недоступна эта способность.', '', 28153),
(145322, 'ruRU', 'Я этому пока не обучен.', '', 28153),
(145321, 'ruRU', 'Это заклинание еще не готово.', '', 28153),
(145320, 'ruRU', 'Я пока не могу применить это заклинание.', '', 28153),
(145319, 'ruRU', 'Нужно подождать.', '', 28153),
(145318, 'ruRU', 'Отгадай загадку.\n\nЕсли у меня это есть, я этим не делюсь. Если я этим делюсь, у меня этого нет. Что это такое?', '', 28153),
(145317, 'ruRU', 'Завалим эту цель!', '', 28153),
(145316, 'ruRU', 'Убейте мою цель!', '', 28153),
(145315, 'ruRU', 'Все внимание на врага!', '', 28153),
(145314, 'ruRU', 'К оружию!', '', 28153),
(145313, 'ruRU', 'За королеву!', '', 28153),
(145312, 'ruRU', 'Во славу Черной горы!', '', 28153),
(145311, 'ruRU', 'Уничтожим врага!', '', 28153),
(145310, 'ruRU', 'Перебьем всех!', '', 28153),
(145309, 'ruRU', 'Валим, пока целы!', '', 28153),
(145308, 'ruRU', 'Вы чувствуете на себе незнакомый пристальный взгляд. Он кажется таким... самоуверенным?', 'Вы чувствуете на себе незнакомый пристальный взгляд. Он кажется таким... самоуверенным?', 28153),
(145307, 'ruRU', 'Отходим!', '', 28153),
(145306, 'ruRU', 'Убираемся отсюда!', '', 28153),
(145305, 'ruRU', 'Идем.', '', 28153),
(145304, 'ruRU', 'Все за мной.', '', 28153),
(145303, 'ruRU', 'За мной.', '', 28153),
(145302, 'ruRU', 'Серьезно?', 'Серьезно?', 28153),
(145301, 'ruRU', 'Я готов!', 'Я готова!', 28153),
(145300, 'ruRU', 'Те, кто играет в недотрогу, – всегда самая сладкая добыча. Я иду за тобой!', '', 28153),
(145299, 'ruRU', 'Правильно! \n\nНу что, следующую загадку?', '', 28153),
(145298, 'ruRU', 'За Альянс!', '', 28153),
(145297, 'ruRU', 'Ох, мне досталось!', '', 28153),
(145296, 'ruRU', 'Эй, подлечите!', '', 28153),
(145295, 'ruRU', 'Помогите!', '', 28153),
(145294, 'ruRU', 'Ну-ка, подсобите!', '', 28153),
(145293, 'ruRU', 'Берегитесь!', '', 28153),
(145292, 'ruRU', 'Не зевать, огонь!', '', 28153),
(145291, 'ruRU', 'Открыть огонь!', '', 28153),
(145290, 'ruRU', 'Побудьте здесь.', '', 28153),
(145289, 'ruRU', 'Никуда не уходите!', '', 28153),
(145288, 'ruRU', 'Плотоядное комнатное растение.', 'Плотоядное комнатное растение.', 28153),
(145287, 'ruRU', '', 'Сейчас, только маны подкоплю.', 28153),
(145286, 'ruRU', '', 'Маны бы подкопить.', 28153),
(145285, 'ruRU', 'Рыба.', 'Рыба.', 28153),
(145283, 'ruRU', 'Еще одну попытку!', 'Еще одну попытку!', 28153),
(145282, 'ruRU', 'Нет!\n\nЕще одну попытку?', '', 28153),
(145281, 'ruRU', 'Пандарен.', 'Пандарен.', 28153),
(145280, 'ruRU', 'Огонь.', 'Огонь.', 28153),
(145279, 'ruRU', 'Отгадай загадку.\n\nЕсли я пью, то умру. Если я ем, то живу. Кто я?', '', 28153),
(145278, 'ruRU', 'Я готов!', 'Я готова!', 28153),
(145277, 'ruRU', 'Верно!\n\nНу что, следующую загадку?', '', 28153),
(145276, 'ruRU', 'Ууну поглотила тьма.', 'Ууну поглотила тьма.', 28153),
(145275, 'ruRU', '', 'А-а-а-а-а! Нет! На помощь!', 28153),
(145273, 'ruRU', '', 'Гулкий голос звенит, действуя вам на нервы.', 28153),
(145272, 'ruRU', '', 'Ну пожалуйста!', 28153),
(145271, 'ruRU', '', 'Будь душкой, а?', 28153),
(145270, 'ruRU', '', 'Умоляю!', 28153),
(145269, 'ruRU', '', 'Неплохо!', 28153),
(145268, 'ruRU', '', 'Ну даешь.', 28153),
(145267, 'ruRU', '', 'Недурно.', 28153),
(145266, 'ruRU', '', 'Но... не сейчас.', 28153),
(145265, 'ruRU', '', 'Я знаю, что когда-нибудь должна буду вернуться к маме с папой.', 28153),
(145264, 'ruRU', '', 'Да осветит твой путь свет горнила.', 28153),
(145263, 'ruRU', '', 'Я столько всего удивительного увидела... Ты $gсамый лучший друг:самая лучшая подруга; на свете!', 28153),
(145262, 'ruRU', '', 'Иди займись делом.', 28153),
(145261, 'ruRU', '', 'Вы заплатите за то, что совершили!', 28153),
(145260, 'ruRU', '', 'Двигай давай!', 28153),
(145259, 'ruRU', '', 'Бывай.', 28153),
(145258, 'ruRU', '', 'Спасибо БОЛЬШОЕ, что $gпоказал:показала; мне все это!', 28153),
(145257, 'ruRU', '', 'Выходит, не все они погибли на Аргусе?', 28153),
(145256, 'ruRU', '', 'Здесь мои сородичи! Они выжили!', 28153),
(145255, 'ruRU', '', 'Так красиво...', 28153),
(145254, 'ruRU', '', 'Это правда глупо.', 28153),
(145253, 'ruRU', '', 'И движется, как вода... Это озеро-светлячок?', 28153),
(145252, 'ruRU', '', 'Ну здрасте.', 28153),
(145251, 'ruRU', 'Попробую снова.', 'Попробую снова.', 28153),
(145250, 'ruRU', 'Неверно!\n\nПопробуешь еще раз?', '', 28153),
(145249, 'ruRU', 'Лоа.', 'Лоа.', 28153),
(145248, 'ruRU', 'Свеча.', 'Свеча.', 28153),
(145247, 'ruRU', '', 'Глянь вниз. Там все светится!', 28153),
(145246, 'ruRU', '', 'Где мы? Почему тут столько дыма?', 28153),
(145245, 'ruRU', '', 'Так что будь осторожней, хорошо?', 28153),
(145244, 'ruRU', 'Дерево.', 'Дерево.', 28153),
(145243, 'ruRU', '', 'Смотри не упади! Мне-то ничего не будет, а ты разобьешься в лепешку!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145242, 'ruRU', '', 'Приветствую.', 28153),
(145241, 'ruRU', '', 'Я и не знала, что бывают такие высокие горы!', 28153),
(145240, 'ruRU', '', 'Отсюда видно все!', 28153),
(145239, 'ruRU', '', 'Рада тебя видеть.', 28153),
(145238, 'ruRU', '', 'Рада встрече.', 28153),
(145237, 'ruRU', '', 'Кар-кар-кар!', 28153),
(145236, 'ruRU', '', 'Нет.', 28153),
(145235, 'ruRU', '', 'Не-а.', 28153),
(145234, 'ruRU', '', 'Ни за что.', 28153),
(145233, 'ruRU', '', 'Дело говоришь.', 28153),
(145232, 'ruRU', '', 'Агамс.', 28153),
(145231, 'ruRU', '', 'Ага.', 28153),
(145230, 'ruRU', '', 'Премного благодарна!', 28153),
(145229, 'ruRU', '', 'Благодарствую.', 28153),
(145228, 'ruRU', 'Гном.', 'Гном.', 28153),
(145227, 'ruRU', '', 'Я в долгу не останусь.', 28153),
(145226, 'ruRU', '', 'Наковальня меня зашиби!', 28153),
(145225, 'ruRU', '', 'Думаю, там целых... ДЕСЯТЬ птиц!', 28153),
(145224, 'ruRU', '', 'И это все?', 28153),
(145222, 'ruRU', '', 'Я те накостыляю!', 28153),
(145221, 'ruRU', '', 'Интересно, сколько птиц на нем живет. Наверное, очень много!', 28153),
(145220, 'ruRU', 'Отгадай загадку.\n\nЯ высок, когда молод, и низок, когда стар. Кто я?', '', 28153),
(145219, 'ruRU', '', 'Всегда пожалуйста.', 28153),
(145218, 'ruRU', '', 'Посмотри! Мы под гигантским деревом!', 28153),
(145217, 'ruRU', '', 'Рада помочь.', 28153),
(145216, 'ruRU', '', 'Да обращайся.', 28153),
(145215, 'ruRU', 'Давай поиграем.', 'Давай поиграем.', 28153),
(145214, 'ruRU', 'Ну что, испытаешь свой разум?', '', 28153),
(145213, 'ruRU', '', 'А можно мне одну забрать с собой?', 28153),
(145212, 'ruRU', '', 'Но для ящериц.', 28153),
(145211, 'ruRU', '', 'Эта башня... будто огромный птичник.', 28153),
(145210, 'ruRU', '', 'Эй, а кто это там летает? Такие красивые!', 28153),
(145209, 'ruRU', '', 'Слушай... А где ты вообще живешь?..', 28153),
(145208, 'ruRU', '', 'Ты тут живешь?', 28153),
(145207, 'ruRU', '', 'Как такое может быть?', 28153),
(145206, 'ruRU', '', 'Ух ты... Летающий город?! Глазам не верю!', 28153),
(145205, 'ruRU', '', 'Поиграем в принцесс?', 28153),
(145204, 'ruRU', '', 'Знаешь, кто тут живет? Наверняка какая-нибудь принцесса!', 28153),
(145203, 'ruRU', '', 'Ух ты! Это самый красивый дом в мире!', 28153),
(145202, 'ruRU', '', 'Фу-у-у-у-у!', 28153),
(145201, 'ruRU', '', 'Это жуки? Точно жуки. Фу! Ненавижу жуков!', 28153),
(145200, 'ruRU', '', 'Как думаешь, что за ней хотели спрятать?', 28153),
(145199, 'ruRU', '', 'Ого! Никогда еще таких больших стен не видела!', 28153),
(145197, 'ruRU', '', 'Ууна обнимает вас.', 28153),
(145196, 'ruRU', 'Ты не получишь трофей!', '', 28153),
(145195, 'ruRU', '', 'А теперь – вперед! Нас ждет столько удивительных мест!', 28153),
(145194, 'ruRU', '', 'Скажи моим маме и папе, что я скучаю по ним... И что скоро мы увидимся!', 28153),
(145193, 'ruRU', '', 'Свет говорит, что я могу остаться! Ура!', 28153),
(145192, 'ruRU', '', 'Можно мне еще немного погулять? Совсем чуть-чуть!', 28153),
(145191, 'ruRU', '', 'Но я хотела бы еще столько увидеть! Везде побывать...', 28153),
(145190, 'ruRU', '', 'Но...', 28153),
(145189, 'ruRU', '', 'Мама! Папа! Они ждут меня!', 28153),
(145188, 'ruRU', '', 'Свет... Он зовет меня за собой...', 28153),
(145187, 'ruRU', '', 'Что... что происходит?', 28153),
(145186, 'ruRU', '', 'Ура! Мы справились! Мы победили их!', 28153),
(145185, 'ruRU', '', 'Тьма ушла! Я все вижу!', 28153),
(145184, 'ruRU', '', 'Вы заплатите за то, что сделали!', 28153),
(145183, 'ruRU', 'Проклятье на твою голову! Да чтоб тебя! Я не закончил...', '', 28153),
(145182, 'ruRU', 'Твоя смерть порадует королеву банши!', '', 28153),
(145181, 'ruRU', 'Альянсово отродье! Я принесу Темной Госпоже твою голову!', '', 28153),
(145180, 'ruRU', '', 'Я перережу тебе глотку, $n!', 28153),
(145179, 'ruRU', 'Вдалеке слышен неистовый топот копыт. Что-то приближается.', 'Вдалеке слышен неистовый топот копыт. Что-то приближается.', 28153),
(145178, 'ruRU', '', 'Как ты смеешь прерывать меня! Ты заплатишь за это жизнью, $n!', 28153),
(145177, 'ruRU', '', 'Я следила за тобой, $n.', 28153),
(145176, 'ruRU', 'Я поджарю тебя, как и твоего пса-короля! За Орду!', '', 28153),
(145175, 'ruRU', 'Вы слышите, как в воздухе начинает потрескивать озон.', 'Вы слышите, как в воздухе начинает потрескивать озон.', 28153),
(145173, 'ruRU', '', 'Хитро, но я – это не только магия.', 28153),
(145172, 'ruRU', 'Я готов. Начнем ритуал.', 'Я готова. Начнем ритуал.', 28153),
(145171, 'ruRU', 'Я чувствую страдания нашего мира. Азерот плачет от боли! Мы должны найти способ помочь ей...', '', 28153),
(145170, 'ruRU', '', 'Я так просто не умру, $n. Ты ощутишь мой гнев!', 28153),
(145169, 'ruRU', '', 'Наконец-то я нашла тебя, $n.', 28153),
(145168, 'ruRU', 'Я раздавлю твой череп!', '', 28153),
(145167, 'ruRU', 'Я срежу плоть с твоих костей!', '', 28153),
(145166, 'ruRU', 'Я вечно буду стоять над твоей могилой.', '', 28153),
(145165, 'ruRU', 'Я исчерпал всю надежду.', '', 28153),
(145164, 'ruRU', 'Проклятье. Только не это.', '', 28153),
(145163, 'ruRU', 'Ты будешь страдать за то, что со мной стало.', '', 28153),
(145162, 'ruRU', 'Я выпью твою жизненную силу.', '', 28153),
(145161, 'ruRU', 'Я наслаждаюсь звуком лязгающего металла и запахом страха.', '', 28153),
(145160, 'ruRU', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t На вас действует эффект |cFFF00000|Hspell:260953|h[Железный взгляд]|h|r!', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t Вы |cFFF00000|Hspell:257459|h[на крюке]|h|r!', 28153),
(145159, 'ruRU', '', 'Я БОЛЬШЕ НЕ БУДУ БОЯТЬСЯ!', 28153),
(145158, 'ruRU', '', 'Мой свет – самый сильный!', 28153),
(145157, 'ruRU', 'Я хочу домой.', '', 28153),
(145156, 'ruRU', '', 'Пока со мной мой свет, тьме не победить!', 28153),
(145155, 'ruRU', '', 'Мама говорила, что Свет всегда меня найдет. Значит, это ты! Ты мой Свет!', 28153),
(145154, 'ruRU', '', 'Ура, ты здесь! Ты меня не $gбросил:бросила;!', 28153),
(145153, 'ruRU', 'Нет... Нет...', 'Нет... Нет...', 28153),
(145152, 'ruRU', 'Темная Госпожа... Я не справился...', 'Темная Госпожа... Я не справилась...', 28153),
(145151, 'ruRU', 'Я буду самым низким на тотемном столбе, приятель.', '', 28153),
(145150, 'ruRU', 'Наконец-то...', 'Наконец-то...', 28153),
(145149, 'ruRU', 'О... только не снова...', 'О... только не снова...', 28153),
(145148, 'ruRU', 'За Темную Госпожу!', 'За Темную Госпожу!', 28153),
(145147, 'ruRU', 'Оставь надежду!', 'Оставь надежду!', 28153),
(145146, 'ruRU', 'Раздели с нами смерть!', 'Раздели с нами смерть!', 28153),
(145145, 'ruRU', 'Я обглодаю твои кости!', 'Я обглодаю твои кости!', 28153),
(145144, 'ruRU', 'Смерть всем живым!', 'Смерть всем живым!', 28153),
(145143, 'ruRU', 'За Сильвану!', 'За Сильвану!', 28153),
(145142, 'ruRU', '', 'Ууна обхватывает себя руками и начинает плакать.', 28153),
(145141, 'ruRU', '', 'Я... Я не могу! Хочу домой!', 28153),
(145140, 'ruRU', '', 'Эй! Ты еще тут? Мне страшно!', 28153),
(145139, 'ruRU', 'Зловещее джуджу настигнет тебя!', '', 28153),
(145137, 'ruRU', 'Твои предки призывают тебя к себе.', '', 28153),
(145136, 'ruRU', 'Чтоб тебе досталась уродская рожа моего братишки.', '', 28153),
(145135, 'ruRU', 'Что у тебя за вуду?', '', 28153),
(145133, 'ruRU', 'Пусть кости падут туда, куда падут.', '', 28153),
(145130, 'ruRU', 'Шипы метят вам в душу!', '', 28153),
(145129, 'ruRU', 'Затем он повернулся и исчез в лесу. С тех пор храбрые и верные находят убежище рядом с Белым Оленем.', 'Затем он повернулся и исчез в лесу. С тех пор храбрые и верные находят убежище рядом с Белым Оленем.', 28153),
(145128, 'ruRU', '\"Я – Атаир, сердце этого леса. Покуда я существую, я буду защищать тебя и твой род\", – сказал олень.', '\"Я – Атаир, сердце этого леса. Покуда я существую, я буду защищать тебя и твой род\", – сказал олень.', 28153),
(145127, 'ruRU', '\"Во имя Света! Ты умеешь говорить!\" – воскликнул Аром!', '\"Во имя Света! Ты умеешь говорить!\" – воскликнул Аром!', 28153),
(145126, 'ruRU', '', '<Applause sounds>', 28153),
(145125, 'ruRU', '', '<Yawning sound>', 28153),
(145124, 'ruRU', '', '<Short cheer--Wooooo!>', 28153),
(145123, 'ruRU', '', '<Slightly longer cheer--Woohoo!>', 28153),
(145122, 'ruRU', 'Огонь убьет его!', '', 28153),
(145121, 'ruRU', '', '<Chicken sounds>', 28153),
(145120, 'ruRU', '', '<Crying sounds>', 28153),
(145119, 'ruRU', '\"Не за что. Я отплатил за доброту, что ты проявил ко мне\".', '\"Не за что. Я отплатил за доброту, что ты проявил ко мне\".', 28153),
(145118, 'ruRU', '', '<Crying sounds, variant>', 28153),
(145117, 'ruRU', '', '<Crying sounds, variant.>', 28153),
(145116, 'ruRU', '', '<Kiss sound>', 28153),
(145115, 'ruRU', '\"Благодарю тебя, друг мой\", – сказал Аром оленю.', '\"Благодарю тебя, друг мой\", – сказал Аром оленю.', 28153),
(145114, 'ruRU', '', '<Laughing sounds>', 28153),
(145113, 'ruRU', '', '<Laughing>', 28153),
(145112, 'ruRU', '', '<Making a raspberry sound--Pfffthblth!>', 28153),
(145111, 'ruRU', 'Вместе Аром и белый олень сразились с друстами и победили их.', 'Вместе Аром и белый олень сразились с друстами и победили их.', 28153),
(145110, 'ruRU', '', '<Roar of dominance>', 28153),
(145109, 'ruRU', '', '<Variant roar>', 28153),
(145108, 'ruRU', '', '<Sighing sound>', 28153),
(145107, 'ruRU', '', '<Train noises--chugga chugga choo choo!>', 28153),
(145106, 'ruRU', 'Белый олень вернулся и разметал часть друстов!', 'Белый олень вернулся и разметал часть друстов!', 28153),
(145105, 'ruRU', 'Но тут из леса раздался могучий рев!', 'Но тут из леса раздался могучий рев!', 28153),
(145104, 'ruRU', 'Полный решимости убить столько врагов, сколько сможет, он не отступал ни на шаг.', 'Полный решимости убить столько врагов, сколько сможет, он не отступал ни на шаг.', 28153),
(145103, 'ruRU', 'Лорд Аром сражался один против десяти воинов! Он отважно бился, но их было много, и его окружили!', 'Лорд Аром сражался один против десяти воинов! Он отважно бился, но их было много, и его окружили!', 28153),
(145102, 'ruRU', 'Любопытно.', 'Любопытно.', 28153),
(145101, 'ruRU', 'Под покровом ночи на него напали друсты!', 'Под покровом ночи на него напали друсты!', 28153),
(145100, 'ruRU', 'Олень ускакал в лес, а Аром разбил лагерь.', 'Олень ускакал в лес, а Аром разбил лагерь.', 28153),
(145099, 'ruRU', '\"В своих лесах я готов приветствовать любого, кто способен сражаться с таким количеством друстов\", – подумал он. Итак, лорд Аром исцелил раны оленя.', '\"В своих лесах я готов приветствовать любого, кто способен сражаться с таким количеством друстов\", – подумал он. Итак, лорд Аром исцелил раны оленя.', 28153),
(145098, 'ruRU', 'Остерегайтесь шипов!', '', 28153),
(145097, 'ruRU', 'Людям лорда Арома была нужна пища, и большой олень мог прокормить многих, но лорд решил не убивать прекрасное животное.', 'Людям лорда Арома была нужна пища, и большой олень мог прокормить многих, но лорд решил не убивать прекрасное животное.', 28153),
(145096, 'ruRU', 'Олень отбивался от друстов и убил многих, но был ранен.', 'Олень отбивался от друстов и убил многих, но был ранен.', 28153),
(145095, 'ruRU', 'Однажды, когда лорд Аром охотился в лесу, он обнаружил большого белого оленя.', 'Однажды, когда лорд Аром охотился в лесу, он обнаружил большого белого оленя.', 28153),
(145094, 'ruRU', 'Да! Освободите нас!', '', 28153),
(145093, 'ruRU', 'Вы... освободили нас...', '', 28153),
(145092, 'ruRU', 'Наконец-то... свобода...', '', 28153),
(145091, 'ruRU', 'Спасибо... вам...', '', 28153),
(145090, 'ruRU', 'Теперь ты с нами.', '', 28153),
(145089, 'ruRU', 'Спасения нет.', '', 28153),
(145088, 'ruRU', '', 'Завалим эту цель!', 28153),
(145087, 'ruRU', '', 'Убейте мою цель!', 28153),
(145086, 'ruRU', '', 'Все внимание на врага!', 28153),
(145085, 'ruRU', 'Бегите! Надежды нет!', '', 28153),
(145084, 'ruRU', 'Вместе... навсегда.', '', 28153),
(145083, 'ruRU', '', 'К оружию!', 28153),
(145082, 'ruRU', '', 'За королеву!', 28153),
(145081, 'ruRU', '', 'Во славу Черной горы!', 28153),
(145080, 'ruRU', 'Наши страдания погубят вас!', '', 28153),
(145079, 'ruRU', '', 'Уничтожим врага!', 28153),
(145078, 'ruRU', '', 'Перебьем всех!', 28153),
(145077, 'ruRU', '', 'Валим, пока целы!', 28153),
(145076, 'ruRU', '', 'Отходим!', 28153),
(145075, 'ruRU', '', 'Убираемся отсюда!', 28153),
(145074, 'ruRU', '', 'Идем.', 28153),
(145073, 'ruRU', '', 'Все за мной.', 28153),
(145072, 'ruRU', '', 'За мной.', 28153),
(145071, 'ruRU', '', 'За Альянс!', 28153),
(145070, 'ruRU', '', 'Помогите!', 28153),
(145069, 'ruRU', '', 'Ну-ка, подсобите!', 28153),
(145068, 'ruRU', '', 'Берегитесь!', 28153),
(145067, 'ruRU', '', 'Не зевать, огонь!', 28153),
(145066, 'ruRU', '', 'Открыть огонь!', 28153),
(145065, 'ruRU', '', 'Побудьте здесь.', 28153),
(145064, 'ruRU', '', 'Никуда не уходите!', 28153),
(145063, 'ruRU', '', 'Ох, мне досталось!', 28153),
(145062, 'ruRU', '', 'Эй, подлечите!', 28153),
