(145044, 'ruRU', '', '<Player takes significant wound: Total 5>', 28153),
(145043, 'ruRU', '', 'Не своди глаз с цели.', 28153),
(145042, 'ruRU', '', 'Мы делаем то, что должны, ради тех, кого любим.', 28153),
(145041, 'ruRU', '', 'Бей без промаха.', 28153),
(145040, 'ruRU', '', 'Прощай.', 28153),
(145039, 'ruRU', '', 'Тени могут быть союзниками... если держать их в узде.', 28153),
(145038, 'ruRU', '', 'Приветствую.', 28153),
(145037, 'ruRU', '', 'Мы больше не можем никого пригласить.', 28153),
(145036, 'ruRU', '', 'Мы все следуем определенному пути. Выбери свой.', 28153),
(145035, 'ruRU', '', 'Я пока не могу выпить больше.', 28153),
(145034, 'ruRU', '', 'Мне пока недоступна эта способность.', 28153),
(145033, 'ruRU', '', 'Я этому пока не обучена.', 28153),
(145032, 'ruRU', '', 'Это заклинание еще не готово.', 28153),
(145031, 'ruRU', '', 'Есть новости?', 28153),
(145030, 'ruRU', '', 'Я пока не могу применить это заклинание.', 28153),
(145029, 'ruRU', '', 'Нужно подождать.', 28153),
(145028, 'ruRU', '', 'Используй все доступное оружие.', 28153),
(145027, 'ruRU', '', 'Хороший день для охоты.', 28153),
(145026, 'ruRU', '', 'Меня не было столько лет, и ты так со мной обращаешься?', 28153),
(145025, 'ruRU', '', 'Я не могу этого сделать.', 28153),
(145024, 'ruRU', '', 'Для этого мне нужно разрешение.', 28153),
(145023, 'ruRU', '', 'Я не могу атаковать эту цель.', 28153),
(145022, 'ruRU', '', 'Бездна поглотит тебя... если хорошенько попросишь.', 28153),
(145021, 'ruRU', '', 'Неподходящая цель.', 28153),
(145020, 'ruRU', '', 'Некуда класть.', 28153),
(145019, 'ruRU', '', 'Я не смогу нести больше.', 28153),
(145018, 'ruRU', '', 'Сестры создают кучу проблем. Особенно когда они – нежить.', 28153),
(145017, 'ruRU', '', 'Заперто.', 28153),
(145016, 'ruRU', '', 'У меня уже достаточно таких предметов.', 28153),
(145015, 'ruRU', '', 'Я пока не могу это использовать.', 28153),
(145014, 'ruRU', '', 'Этот предмет еще не готов.', 28153),
(145013, 'ruRU', '', 'Нужно подождать.', 28153),
(145012, 'ruRU', '', 'Недостаточно гнева.', 28153),
(145011, 'ruRU', '', 'У меня мало гнева.', 28153),
(145010, 'ruRU', '', 'Недостаточно боли.', 28153),
(145009, 'ruRU', '', 'Нужно больше боли.', 28153),
(145008, 'ruRU', '', 'Это не сумка.', 28153),
(145007, 'ruRU', '', 'Мне не хватает средств.', 28153),
(145006, 'ruRU', '', 'Это мне не по карману.', 28153),
(145005, 'ruRU', '', 'Слишком дорого.', 28153),
(145004, 'ruRU', '', 'Не могу пригласить участника другой группы.', 28153),
(145003, 'ruRU', '', 'Не хватает боеприпасов.', 28153),
(145002, 'ruRU', '', 'Недостаточно энергии.', 28153),
(145001, 'ruRU', '', 'Мне не хватает энергии.', 28153),
(145000, 'ruRU', '', 'Мне не хватает маны.', 28153),
(144999, 'ruRU', '', 'У меня мало маны.', 28153),
(144998, 'ruRU', '', 'Мне нужна мана.', 28153),
(144997, 'ruRU', '', 'Недостаточно ярости.', 28153),
(144996, 'ruRU', '', 'Нужно больше ярости.', 28153),
(144995, 'ruRU', '', 'Слишком далеко.', 28153),
(144994, 'ruRU', '', 'Да, я все еще люблю его. А какое тебе вообще дело?', 28153),
(144993, 'ruRU', '', 'Я слишком далеко.', 28153),
