INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144985, 'ruRU', '', 'Это неподходящее место.', 28153),
(144984, 'ruRU', '', 'Я не могу это выбросить.', 28153),
(144983, 'ruRU', '', 'Этот предмет может быть только моим.', 28153),
(144982, 'ruRU', '', 'Я не могу это использовать.', 28153),
(144981, 'ruRU', '', 'Мой уровень недостаточно высок, чтобы этим пользоваться.', 28153),
(144980, 'ruRU', '', 'Я пока не могу это использовать.', 28153),
(144979, 'ruRU', '', 'Мой уровень недостаточно высок, чтобы это использовать.', 28153),
(144978, 'ruRU', '', 'Я никогда не смогу это использовать.', 28153),
(144977, 'ruRU', '', 'Я не могу изучить это заклинание.', 28153),
(144976, 'ruRU', '', 'Я не могу забрать эту добычу.', 28153),
(144975, 'ruRU', '', 'Это не мое. Я не могу это взять.', 28153),
(144974, 'ruRU', '', 'Мне нужно подойти ближе.', 28153),
(144973, 'ruRU', '', 'Слишком далеко.', 28153),
(144972, 'ruRU', '', 'Не могу достать.', 28153),
(144971, 'ruRU', '', 'Я не могу это отдать.', 28153),
(144970, 'ruRU', '', 'Я не могу это использовать.', 28153),
(144969, 'ruRU', '', 'Этот предмет нужно надеть или взять в руки.', 28153),
(144968, 'ruRU', '', 'Сначала этот предмет нужно надеть или взять в руки.', 28153),
(144967, 'ruRU', '', 'Сейчас это невозможно.', 28153),
(144966, 'ruRU', '', 'У меня нет цели.', 28153),
(144965, 'ruRU', '', 'Сначала нужно выбрать цель.', 28153),
(144964, 'ruRU', '', 'Мне нужна цель.', 28153),
(144963, 'ruRU', '', 'Высшие силы и духи земли, сделайте так, чтоб побеги росли!', 28153),
(144962, 'ruRU', '', 'Отдай мне кристалл, сестра!', 28153),
(144961, 'ruRU', '', 'Мои шипы растерзают тебя!', 28153),
(144960, 'ruRU', '', 'Чем сильнее будешь дергаться, тем сильнее поранишься.', 28153),
(144959, 'ruRU', '', 'На тебе черная метка!', 28153),
(144958, 'ruRU', '', 'Ваши черепа послужат отличным украшением.', 28153),
(144956, 'ruRU', '', 'Мои семена снова прорастут...', 28153),
(144955, 'ruRU', '', 'Я люблю этот звук ломающихся костей.', 28153),
(144954, 'ruRU', 'Сегодня вечером я хорошо поем. Спасибо, да благословят тебя лоа.', 'Сегодня вечером я хорошо поем. Спасибо, да благословят тебя лоа.', 28153),
(144953, 'ruRU', 'Такая щедрость! Спасибо тебе!', 'Такая щедрость! Спасибо тебе!', 28153),
(144952, 'ruRU', 'Спасибо тебе.', 'Спасибо тебе.', 28153),
(144951, 'ruRU', '', 'Такие хрупкие кости!', 28153),
(144950, 'ruRU', '<Дать десять золотых.>', '<Дать десять золотых.>', 28153),
(144949, 'ruRU', '<Дать один золотой.>', '<Дать один золотой.>', 28153),
(144948, 'ruRU', '<Дать пять медяков.>', '<Дать пять медяков.>', 28153),
(144947, 'ruRU', 'У тебя не найдется пары медяков?', 'У тебя не найдется пары медяков?', 28153),
(144946, 'ruRU', '', 'Гниющая плоть и ужаса крик. Как же прекрасен сей сладостный миг!', 28153),
(144945, 'ruRU', '', 'Твоя смерть – лишь дело времени!', 28153),
(144944, 'ruRU', '', 'Теперь моя очередь!', 28153),
(144943, 'ruRU', '', '...а Резан рычал над трупами троллей крови. Триумф!', 28153),
(144942, 'ruRU', '', 'Ваши мучения только начинаются.', 28153),
(144941, 'ruRU', '', 'Прекрасная агония!', 28153),
(144940, 'ruRU', '', 'Мое тело умрет... но мое проклятье будет жить...', 28153),
(144939, 'ruRU', '', 'Сама ваша плоть будет кричать от боли.', 28153),
(144938, 'ruRU', '', 'Черная, как ночь, душа, рвется прочь, врагов кроша!', 28153),
(144937, 'ruRU', '', 'Теперь ты принадлежишь мне!', 28153),
(144936, 'ruRU', '', 'Попляши для меня!', 28153),
(144935, 'ruRU', '', 'Отдай кристалл! Только мне подвластна его мощь!', 28153),
(144934, 'ruRU', '', 'Ваши души теперь мои... навсегда.', 28153),
(144933, 'ruRU', '', 'Смерть не остановит меня...', 28153),
(144932, 'ruRU', '', 'Какая слабая душа!', 28153),
(144931, 'ruRU', '', 'Здесь вы бессильны!', 28153),
(144930, 'ruRU', '', '$n, ты со мной. Остальные – помогите Рокхану на севере.', 28153),
(144929, 'ruRU', 'Взгляните на эти отряды Альянса! Они отправили всех, кто у них был!', '', 28153),
(144928, 'ruRU', 'Они выслали целую кучу солдат! Нельзя дать им прорваться!', '', 28153),
(144926, 'ruRU', '', 'Приветствую, |3-6($c).', 28153),
(144925, 'ruRU', '', 'Всегда помни, что значит присягнуть Свету.', 28153),
(144924, 'ruRU', '', '<Фария встречает вас теплой улыбкой.>$B$BТы достойно $gпрошел:прошла; испытание, |3-6($c), но, сдается мне, твоя история только начинается.', 28153),
(144923, 'ruRU', 'Если ты ищешь Маэлу, то она на фронте, помогает нашим.$B$BВ Штормграде есть и другие умелые портные, которые могут научить тебя кое-чему.', '', 28153),
(144921, 'ruRU', '', 'Свет этот стол забери! Возможно, мне придется распрощаться с мыслью снова работать в этой мастерской.$B$BПорча от этих звериных шкур с Аргуса не сходит со стола, сколько бы я его ни полировала.', 28153),
(144908, 'ruRU', '\"Виндикар\" ждет следующего полета.\n\nКак и я.', '', 28153),
(144907, 'ruRU', 'Спасибо за помощь, $Gприятель:подруга;! За мной должок!', '', 28153),
(144906, 'ruRU', 'Ну, я в таверну.', '', 28153),
(144905, 'ruRU', 'Так-то лучше. Броня, достойная могучего героя, чьи деяния сотрясут основы Азерота!', '', 28153),
(144904, 'ruRU', 'И заберу! Я честно купил эти доспехи, хоть пока за них и не заплатил.', '', 28153),
(144903, 'ruRU', '', 'Похоже, вам сегодня повезло, мистер Камнелоб. Можете забирать товар.', 28153),
(144902, 'ruRU', 'Лапы прочь, мохнатик!', '', 28153),
(144901, 'ruRU', '', 'Да, госпожа.', 28153),
(144900, 'ruRU', '', 'Уходи! Мы тебя не боимся!', 28153),
(144899, 'ruRU', '%s кивает.', '', 28153),
(144898, 'ruRU', '', 'Мистер Чу, прошу, выведите этого дворфа. Мисс Сюлань, проведите повторную инвентаризацию.', 28153),
(144897, 'ruRU', 'Клянусь, я отправил чек по почте этим утром! Нельзя же меня оставлять совсем без гроша!', '', 28153),
(144896, 'ruRU', '', 'С меня хватит просроченных платежей, мистер Камнелоб. Согласно контракту, я изымаю ваши товары.', 28153),
(144895, 'ruRU', '', 'Они здесь...', 28153),
(144894, 'ruRU', '', 'Мы вернем его. Жди здесь.', 28153),
(144893, 'ruRU', 'Они пришли из леса. Мы бились. Мастер Эштон оттолкнул меня, и они забрали его. Мы должны его спасти!', '', 28153),
(144892, 'ruRU', '', 'Не сомневаюсь в этом, Мартен. Что случилось?', 28153),
(144891, 'ruRU', 'Я сражался изо всех сил!', '', 28153),
(144889, 'ruRU', '', 'Так... Но зачем нам дворфийский труп? Для демонстрации силы? Или для устрашения?', 28153),
(144888, 'ruRU', 'Все прошло в точности, как и было задумано.', '', 28153),
(144887, 'ruRU', 'А... да, да... Естественно!', '', 28153),
(144886, 'ruRU', 'Нельзя забывать о нашей цели. Мы должны найти Глаз раньше Альянса.', '', 28153),
(144885, 'ruRU', '', 'Возможно, тролли возможно все это время сидели на археологической находке тысячелетия!', 28153),
(144884, 'ruRU', '', 'Битва началась! Веди нас к победе!', 28153),
(144883, 'ruRU', 'Ты сказала отцу, что хочешь увидеть чужие земли, а сама ведешь переговоры с ордынскими псами?', '', 28153),
(144882, 'ruRU', 'Принцесса.', '', 28153),
(144881, 'ruRU', 'Мы заставляем вашего отца ждать.', '', 28153),
(144880, 'ruRU', '', 'Принцесса... позвольте мне первой поприветствовать...', 28153),
(144879, 'ruRU', '', 'Знай... Мой отец несговорчив, но из виду ничего не упускает. Думаю, он уже знает, кто помог мне сбежать из Штормграда.', 28153),
(144878, 'ruRU', '', 'Не тебе это решать, генерал.', 28153),
(144877, 'ruRU', 'Ради защиты королевства лучше изгнать это... существо... в Вол\'дун. Орде не место в Зандаларе.', '', 28153),
(144876, 'ruRU', '', 'Ты поклялся защищать королевство. Не будешь справляться – я найду тех, кто сделает это за тебя.', 28153),
(144875, 'ruRU', '<Коснуться слезы.>', '<Коснуться слезы.>', 28153),
(144874, 'ruRU', '', 'Генерал.', 28153),
(144873, 'ruRU', '<Слеза зеленого дракона, погруженная во Тьму неведомыми силами.>', '', 28153),
(144872, 'ruRU', '', 'А совет Занчули – это просто сборище бесчестных политиканов и древних стариков. Они убеждают моего отца, что угрозы нет.', 28153),
(144871, 'ruRU', '', 'Тролли крови осаждают северную границу. Они уводят наших в болота Назмира, откуда нет возврата.', 28153),
(144870, 'ruRU', '', 'Враги терзают Зандалар изнутри и извне. Вот почему я обратилась к Орде... и к тебе, одному из ее величайших героев.', 28153),
(144869, 'ruRU', '', 'Наконец-то мы можем поговорить наедине, $n. Пора тебе кое-что узнать о моем королевстве.', 28153),
(144868, 'ruRU', '', 'Идем, нам надо навестить моего отца. А с тобой, Зул, мы поговорим позже.', 28153),
(144867, 'ruRU', '', 'Тзе\'на! Девочка моя, ты скучала?', 28153),
(144866, 'ruRU', '', 'Я слышала плач девочки, о которой ты говоришь.\n\nЯ отмечу тебя знаком, позволяющим пройти в этот мир и найти ее.\n\nОна потерялась там, где граница между обителями жизни и смерти тонка, и два мира сливаются воедино.\n\nНо помни: ты будешь $gлишен:лишена; своих сил. Смертные не могут навредить местным обитателям.\n\nМожешь попробовать, но ты вряд ли сможешь помочь своей подруге.', 28153),
(144864, 'ruRU', 'Да хранит тебя Свет.', 'Да хранит тебя Свет.', 28153),
(144863, 'ruRU', 'Я ищу девочку по имени Ууна. Она тебе не попадалась?', 'Я ищу девочку по имени Ууна. Она тебе не попадалась?', 28153),
(144862, 'ruRU', '', 'Т\'паартос научил нас играть в \"булыжник, клинок, пергамент\", но я забыла правила.', 28153),
(144860, 'ruRU', 'Ворота крепости Альянса разрушены!', '', 28153),
(144859, 'ruRU', '', 'Грифоны! В атаку!', 28153),
(144853, 'ruRU', 'Наши доблестные воины сражаются на передовой. Это меньшее, что я могу сделать для их семей, пока они не вернутся.', 'Наши доблестные воины сражаются на передовой. Это меньшее, что я могу сделать для их семей, пока они не вернутся.', 28153),
(144852, 'ruRU', 'Проваливай из моих туннелей, глупое создание!', '', 28153),
(144851, 'ruRU', '', 'Хвостик такой пушистый!', 28153),
(144850, 'ruRU', '', 'А можно я его оставлю?', 28153),
(144849, 'ruRU', '', 'Нет, Т\'паартос, останься! Расскажи еще о приключениях!', 28153),
(144848, 'ruRU', '', 'Он вернулся!', 28153),
(144847, 'ruRU', '', 'Это Т\'паартос!', 28153),
(144846, 'ruRU', 'Не бойтесь, Т\'паартос вернется с новыми историями... или даже новыми друзьями.', '', 28153),
(144845, 'ruRU', 'Т\'паартос должен вернуть малютку. Скажите \"пока\", детишки.', '', 28153),
(144842, 'ruRU', '', 'Ой!', 28153),
(144841, 'ruRU', 'Скажи, что произошло на пиру.', 'Скажи, что произошло на пиру.', 28153),
(144840, 'ruRU', '$c, у Темной Госпожи для тебя важное задание. Надеюсь, ты справишься...', '', 28153),
(144839, 'ruRU', '', 'Т\'паартос!', 28153),
(144838, 'ruRU', '', 'Пообещай, что не покинешь меня! Даже если станет темно...', 28153),
(144837, 'ruRU', '', 'Но теперь со мной ты, и мы... мы можем их победить! Наверное...', 28153),
(144836, 'ruRU', '', 'Я убегаю и убегаю, но они всегда меня находят.', 28153),
(144835, 'ruRU', '', 'Они скоро будут здесь!', 28153),
(144834, 'ruRU', '', 'А, вот ты где! Так-то лучше.', 28153),
(144833, 'ruRU', 'Ха, Т\'паартос тоже вам рад! Т\'паартос даже принес подарок. Эта штучка из Валь\'шары.', '', 28153),
(144832, 'ruRU', 'Это шутка?!', '', 28153),
(144831, 'ruRU', 'Похоже, в этих сферах содержится некая сила. Возможно, если снять оболочку...', '', 28153),
(144830, 'ruRU', 'А!', '', 28153),
(144829, 'ruRU', 'Глаза славные и плотные. Я выжму из них несколько капель, и...', '', 28153),
(144828, 'ruRU', '', 'Я так замерзла, а здесь так темно... Что мне делать?', 28153),
(144827, 'ruRU', '', 'Я не сдамся, обещаю!', 28153),
(144826, 'ruRU', '', 'Мой друг, это ты?', 28153),
(144825, 'ruRU', 'Наши агенты уже проникли в шахты. Если гоблины что-то затевают, мы быстро об этом узнаем...', '', 28153),
(144824, 'ruRU', 'Надо... копать... глубже...', 'Надо... копать... глубже...', 28153),
(144823, 'ruRU', 'Эльф... копает... ха!', 'Эльф... копает... ха!', 28153),
(144822, 'ruRU', 'Вы опоздали. Мы уже нашли...', 'Вы опоздали. Мы уже нашли...', 28153),
(144821, 'ruRU', 'Кто нашел, тот и хозяин...', 'Кто нашел, тот и хозяин...', 28153),
(144820, 'ruRU', 'Вам его не найти...', 'Вам его не найти...', 28153),
(144819, 'ruRU', 'Твои поиски сейчас окончатся. Умри!', 'Твои поиски сейчас окончатся. Умри!', 28153),
(144818, 'ruRU', 'Я с радостью тебя закопаю.', 'Я с радостью тебя закопаю.', 28153),
(144817, 'ruRU', 'Мы тебе ноги лопатой отрежем!', 'Мы тебе ноги лопатой отрежем!', 28153),
(144816, 'ruRU', 'Кто-то решил потягаться с кланом Черного Железа? Это зря.', 'Кто-то решил потягаться с кланом Черного Железа? Это зря.', 28153),
(144815, 'ruRU', 'Назойливый эльф! Эти руины принадлежат клану Черного Железа!', 'Назойливый эльф! Эти руины принадлежат клану Черного Железа!', 28153),
(144812, 'ruRU', '', 'Вражеское подкрепление!', 28153),
(144811, 'ruRU', 'Результаты совершенно однозначны! Мы пойдем на запад!', '', 28153),
(144810, 'ruRU', '', 'Лощина наша! Соберитесь и готовьтесь к следующей атаке.', 28153),
(144809, 'ruRU', '', 'Так, ты вставляешь круглый тотем в квадратную подставку. Вуду знает толк в чувствах, гоблин.', 28153),
(144808, 'ruRU', 'Они нападают из теней, они повсюду!', 'Они нападают из теней, они повсюду!', 28153),
(144807, 'ruRU', '', 'Эта черта мне в нем определенно нравится.', 28153),
(144806, 'ruRU', '', 'О да. Как и вчера, позавчера, и еще за день до этого!', 28153),
(144805, 'ruRU', 'Тоннели зачищены. Откройте ворота!', '', 28153),
(144804, 'ruRU', 'Похоже, у него сегодня прекрасное настроение?', '', 28153),
(144803, 'ruRU', '', 'Враг приближается. Бвонсалака!', 28153),
(144802, 'ruRU', 'Я вернусь к остальным. Мы должны покончить с этим, пока еще не поздно.', '', 28153),
(144801, 'ruRU', 'Спасибо тебе, $p. Боюсь, все гораздо хуже, чем я думал.', '', 28153),
(144800, 'ruRU', 'Расскажи, что произошло в Покое Льва.', 'Расскажи, что произошло в Покое Льва.', 28153),
(144799, 'ruRU', 'Мои агенты проверили это место. Тем не менее всегда разумнее говорить потише.', '', 28153),
(144798, 'ruRU', 'Бвон\'чага ди чока!', 'Бвон\'чага ди чока!', 28153),
(144796, 'ruRU', '', 'Вуду касается всех сердец, Кала, верят они в него или нет.', 28153),
(144795, 'ruRU', '', 'Вуду позволяет тебе читать мысли динозавров? Серьезно?', 28153),
(144794, 'ruRU', '', 'Это все любовь, Кала. Сердце, даже твое, знает, что вуду лучше мозгов.', 28153),
(144792, 'ruRU', 'Я заберу твою волю!', 'Я заберу твою волю!', 28153),
(144791, 'ruRU', 'Истина в парах!', 'Истина в парах!', 28153),
(144790, 'ruRU', 'Вдыхай глубже!', 'Вдыхай глубже!', 28153),
(144789, 'ruRU', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|tРезан |cFFFF0000|Hspell:260683|h[пробуждает]|h|r все оставшиеся груды костей!', '||TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|tРезан |cFFFF0000|Hspell:260683|h[пробуждает]|h|r все оставшиеся груды костей!', 28153),
(144788, 'ruRU', '', 'Г\'уун!', 28153),
(144787, 'ruRU', '', 'Нет... только не так...', 28153),
(144786, 'ruRU', '', 'Сестры... отомстят... за меня...', 28153),
(144785, 'ruRU', '', 'Гачага!', 28153),
(144784, 'ruRU', '', 'Зулдазар... падет...', 28153),
(144783, 'ruRU', '', 'Госпожа... отомсти за меня...', 28153),
(144782, 'ruRU', '', 'Но я была сильнее всех...', 28153),
(144781, 'ruRU', '', 'Покиза...', 28153),
(144780, 'ruRU', 'Это просто замечательно.', '', 28153),
(144779, 'ruRU', 'Прекрасная работа, $n. Теперь добавим по капле каждого зелья и...', '', 28153),
(144778, 'ruRU', '', 'Это будет просто!', 28153),
(144777, 'ruRU', '', 'Я с тобой быстро расправлюсь!', 28153),
(144776, 'ruRU', '', 'Ха! Ты мне не ровня!', 28153),
(144775, 'ruRU', '', 'Еще один череп в мою коллекцию!', 28153),
(144774, 'ruRU', '', 'Это наша земля!', 28153),
(144773, 'ruRU', 'Идем! За мной! Нам предстоит много работы!', '', 28153),
(144772, 'ruRU', 'Хорошо в кои-то веки отдохнуть.$B$BОсобенно после того как провернул выгодное дело!', '', 28153),
(144771, 'ruRU', 'Туши огонь, а я посмотрю, что нам нужно для опытов, в лаборатории! Намечается веселье!', '', 28153),
(144770, 'ruRU', 'У меня больше не осталось материалов. Прошу прощения.', '', 28153),
(144769, 'ruRU', 'Могу предложить тебе несколько сфер, Элрик.', 'Могу предложить тебе несколько сфер, Элрик.', 28153),
(144768, 'ruRU', 'Я принес вам эти травы.', 'Я принесла вам эти травы.', 28153),
(144767, 'ruRU', 'Вот глаза, которые тебе были нужны.', 'Вот глаза, которые тебе были нужны.', 28153),
(144766, 'ruRU', 'Здесь все нужные зелья.', 'Здесь все нужные зелья.', 28153),
(144765, 'ruRU', 'А, коллега-алхимик! Возможно, мои последние рецепты тебя заинтересуют.$b$bМоя специальность – зелья, но время от времени я занимаюсь и трансмутацией.', '', 28153),
(144764, 'ruRU', 'Добро пожаловать в мою лавку, |3-6($c)! Предложить тебе глоток чего-нибудь освежающего, или твое внимание привлекло что-то еще?$b$bМоя специальность – зелья, но время от времени я занимаюсь и трансмутацией.', '', 28153),
(144763, 'ruRU', '', 'Свежее мясо!', 28153),
(144762, 'ruRU', '', 'Я добавлю твои уши к своему ожерелью!', 28153),
(144761, 'ruRU', '', 'Кровь для Г\'ууна!', 28153),
(144760, 'ruRU', 'Тс-с! Не шевелись! Он видит только тех, кто движется.', 'Тс-с! Не шевелись! Он видит только тех, кто движется.', 28153),
(144759, 'ruRU', 'Свет сохрани, он вернулся!', 'Свет сохрани, он вернулся!', 28153),
(144758, 'ruRU', 'Озаренный-воздаятель вздыхает.', 'Озаренная-воздаятельница вздыхает.', 28153),
(144757, 'ruRU', 'Казалось, будто я утратил рассудок.', 'Казалось, будто я утратила рассудок.', 28153),
(144756, 'ruRU', 'Да благословит тебя Мать-Земля!', 'Да благословит тебя Мать-Земля!', 28153),
(144755, 'ruRU', 'Это был настоящий кошмар.', 'Это был настоящий кошмар, $r.', 28153),
(144754, 'ruRU', 'Я должен... Мой разум... Нужно уйти отсюда!', 'Я должна... Мой разум... Нужно уйти отсюда!', 28153),
(144753, 'ruRU', 'Голоса... Они сводят меня с ума!', 'Голоса... Они сводят меня с ума!', 28153),
(144752, 'ruRU', 'Спасибо тебе.', 'Спасибо тебе.', 28153),
(144751, 'ruRU', '', 'Даже лучшее оружие со временем тупится. Тебе нужно восстановить свои силы, Т\'паартос.', 28153),
(144750, 'ruRU', 'Т\'паартос благодарен Лисаре. Т\'паартос чувствует, что снова может драться!', '', 28153),
(144749, 'ruRU', 'Нет, так Т\'паартоса не остановить!', '', 28153),
(144748, 'ruRU', 'Возьми для этого амулет чучельника. Поверь, это лучшее, что у меня есть.', '', 28153),
(144747, 'ruRU', 'А это отличная подделка! Откуда это у тебя? Не говори, как зовут мастера! Просто отправь его ко мне.', '', 28153),
(144746, 'ruRU', 'Держи язык за зубами о том, где тебе удалось это достать, а не то я покажу, как получил это имя.', '', 28153),
(144745, 'ruRU', '', 'Снова, Т\'паартос? Сколько это может продолжаться?..', 28153),
(144744, 'ruRU', 'Это не просто голова ночной эльфийки... Тысячи лет назад она была членом королевской семьи!', '', 28153),
(144743, 'ruRU', 'Время покажет. Присмотри за столетним цветом, $p. Он цветет всего раз в сто лет.', '', 28153),
(144742, 'ruRU', '', 'Золотые семечки! Мы должны немедленно посадить их для короля. Как думаешь, что из них вырастет, Джаден?', 28153),
(144741, 'ruRU', 'Этот перец идеально подойдет для следующей партии моего экстра-чили... а те золотые семечки на вкус как грязь!', '', 28153),
(144740, 'ruRU', '', 'Как видите, нет. Леди Люсиль полна решимости вернуть наши земли и спасти наших людей.', 28153),
(144739, 'ruRU', 'Если так, то я полностью ее поддерживаю.', '', 28153),
(144738, 'ruRU', 'Правда? Я думал, орден – просто легенда!', '', 28153),
(144737, 'ruRU', '', 'Теперь я инквизитор, господин мэр. Леди Люсиль возродила орден Пылающих Углей, чтобы сражаться с ведьмами.', 28153),
(144736, 'ruRU', 'Даже не знаю, как отблагодарить вас за помощь, лейтенант.', '', 28153),
(144735, 'ruRU', '', 'Спасибо, $p! Наш заряд камня возвращения был совсем низким. Возьми перчик за счет заведения.', 28153),
(144734, 'ruRU', 'Тебя интересует работа, $p? Найди того, кто купит эти камни возвращения. Обменяй их на что-нибудь действительно полезное, а я назначу тебе хорошую цену.', '', 28153),
(144733, 'ruRU', 'А это значит... бесплатная древесина!', '', 28153),
(144732, 'ruRU', 'Эй, э... босс? Тут докладывают что по лесу расхаживает какой-то огромный древесный монстр.', '', 28153),
(144731, 'ruRU', 'Кра-ак! Твоя мамка была тр-роггом! Кра-ак!', '', 28153),
(144730, 'ruRU', 'ГР-Р-РОГ! СИДР-Р!', '', 28153),
(144729, 'ruRU', 'КР-Р-РВА...', '', 28153),
(144728, 'ruRU', 'Эй, $p, тебе хотелось когда-нибудь дать кому-то по морде, когда делать этого было нельзя? У меня есть для тебя решение!', '', 28153),
(144727, 'ruRU', 'Потрясающие амулеты! Невероятные редкости! У меня особые цены для первоклассных торговцев!', '', 28153),
(144726, 'ruRU', 'Прислушайся к голосам. Они прекрасны.', 'Прислушайся к голосам. Они прекрасны.', 28153),
(144725, 'ruRU', 'Тени поглотят тебя.', 'Тени поглотят тебя.', 28153),
(144724, 'ruRU', 'Всякие там благословения уже устарели! Только азерит придаст сил для жизни в нынешнем опасном и жестоком мире. Попробуйте питьевой азерит уже сегодня!', '', 28153),
(144723, 'ruRU', 'Тебе необходимо умереть.', 'Тебе необходимо умереть.', 28153),
(144722, 'ruRU', 'ОСТАНОВИ ЭТО!', 'ОСТАНОВИ ЭТО!', 28153),
(144721, 'ruRU', 'Тьма грядет...', 'Тьма грядет...', 28153),
(144720, 'ruRU', 'Будь у Вол\’джина на Расколотом берегу его надежный тотем неуязвимости, сегодня он был бы с нами. Не совершай той же ошибки.', '', 28153),
(144719, 'ruRU', 'Шпионь за врагами, следи за друзьями, прокрадись в королевские палаты... и все это с невероятным тотемом шепчущих огоньков!', '', 28153),
(144718, 'ruRU', 'Пламя этого тотема горит ярко с тех пор, как король Растахан в первый раз сел на трон. Купи эту часть зандаларской истории уже сегодня!', '', 28153),
(144717, 'ruRU', 'Жуль гарантирует: не задаешь вопросов – получаешь скидку!', '', 28153),
(144716, 'ruRU', 'А вот и Т\'паартос!', '', 28153),
(144715, 'ruRU', '', 'Мне стало гораздо лучше.', 28153),
(144714, 'ruRU', 'Т\'паартос!', '', 28153),
(144713, 'ruRU', '', 'Нельзя победить темноту без короны. Таковы правила.', 28153),
(144712, 'ruRU', '', 'Он стреляет звездочками! Плохишам от этого плохо!', 28153),
(144711, 'ruRU', 'Мой род – хранители и собиратели знаний. \n\nМоя работа – проследить, чтобы все наши находки были задокументированы и помещены в архивы.', '', 28153),
(144706, 'ruRU', 'У меня еще много дел. Расправься с ними.', 'У меня еще много дел. Расправься с ними.', 28153),
(144705, 'ruRU', 'Меня утомила твоя болтовня.', 'Меня утомила твоя болтовня.', 28153),
(144704, 'ruRU', 'Не верь этим голосам. Они лгут!', '', 28153),
(144703, 'ruRU', 'Разве ты не слышишь Ту, что зовет из глубин? Она вернет нам былое величие!', 'Разве ты не слышишь Ту, что зовет из глубин? Она вернет нам былое величие!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144702, 'ruRU', 'Мы поклялись защищать Бреннадам. Защищать наш народ! Ты забыл наши обеты?', '', 28153),
(144701, 'ruRU', 'Ты всегда был слишком слаб, чтобы служить лорду Штормсонгу, предпочитал прозябать в своем городишке.', 'Ты всегда был слишком слаб, чтобы служить лорду Штормсонгу, предпочитал прозябать в своем городишке.', 28153),
(144700, 'ruRU', 'Это ты безумен!', '', 28153),
(144699, 'ruRU', 'Море... поглотит тебя...', '', 28153),
(144698, 'ruRU', 'Жизнь... за... Азшару...', '', 28153),
(144697, 'ruRU', 'Пучина заберет тебя...', '', 28153),
(144696, 'ruRU', 'Моя королева... Я... не справился...', '', 28153),
(144695, 'ruRU', 'Прилив... отступает...', '', 28153),
(144694, 'ruRU', '', 'Прилив... схлынул...', 28153),
(144693, 'ruRU', '', 'Моя королева... Я... не справился...', 28153),
(144692, 'ruRU', '', 'Да заберет тебя бездна...', 28153),
(144691, 'ruRU', '', 'Моя жизнь – за Азшару!', 28153),
(144690, 'ruRU', '', 'Море... поглотит тебя...', 28153),
(144689, 'ruRU', 'Еще один вопрос...', 'Еще один вопрос...', 28153),
(144688, 'ruRU', 'Похоже, тебе не помешал бы друг.', 'Похоже, тебе не помешал бы друг.', 28153),
(144687, 'ruRU', 'Что ты делаешь?', 'Что ты делаешь?', 28153),
(144686, 'ruRU', 'Я пришел помочь, Кугро!', 'Я пришла помочь, Кугро!', 28153),
(144685, 'ruRU', 'Можешь взглянуть на этот свиток?', 'Можешь взглянуть на этот свиток?', 28153),
(144684, 'ruRU', 'Поубавь прыти, дитя. \n\nУ меня нет времени на твои просьбы.', '', 28153),
(144683, 'ruRU', 'Друг? Нет, а вот помощник – да.', '', 28153),
(144682, 'ruRU', 'Я скажу тебе, что точно не буду делать: болтать с тобой, пока тут полно работы.', '', 28153),
(144681, 'ruRU', 'В таком случае, надеюсь, ты эффективно работаешь в условиях сжатых сроков.', '', 28153),
(144680, 'ruRU', 'Я сейчас не беру заказов со стороны. И так слишком отстаю. Эти свитки сами собой не напишутся.', '', 28153),
(144679, 'ruRU', 'Баланс... не сошелся...', '', 28153),
(144678, 'ruRU', '', '<Арлуэль глядит вдаль.>$B$BЕсли бы только мой брат мог сейчас увидеть город...', 28153),
(144677, 'ruRU', '', 'У меня есть предчувствие, что война скоро дойдет и до нашего города. Я хочу подготовиться.', 28153),
(144676, 'ruRU', 'Жаль, что не удалось убедить озаренных встать на нашу сторону. Их воинская доблесть неизмерима.', '', 28153),
(144675, 'ruRU', 'На чем я остановился?.. Р-р!', '', 28153),
(144674, 'ruRU', 'Сумеречная стража с радостью вновь примет Викторию в свои ряды.', '', 28153),
(144673, 'ruRU', '', 'Вперед, в бой.', 28153),
(144672, 'ruRU', 'Я рад, что Арлуэль продолжает обучение. Она стала заметно сильнее.$B$BПожалуй, мне стоит это учесть.', '', 28153),
(144671, 'ruRU', 'Течение переменилось, брат! Не последовать за нами – безумие.', 'Течение переменилось, брат. Не последовать за нами – безумие.', 28153),
(144670, 'ruRU', 'Это тебе... Это мне.', '', 28153),
(144669, 'ruRU', 'Чернее ночи бухгалтерия!', '', 28153),
(144668, 'ruRU', 'Рид! Флот нужно немедленно вернуть в Кул-Тирас!', '', 28153),
(144667, 'ruRU', 'Я уже пересчитал эту стопку?', '', 28153),
(144666, 'ruRU', 'Один... Два... Семь... Много... Два...', '', 28153),
(144665, 'ruRU', '', 'Если вдруг непонятно, я чертовски люблю взрывы... И угадай, чья кандидатура на большой бум теперь у меня первая?', 28153),
(144664, 'ruRU', '', 'Еще немного, и тут случится маленькое \"происшествие\".', 28153),
(144663, 'ruRU', '', 'Я этого так не оставлю.', 28153),
(144662, 'ruRU', '', 'Давай, до скорого.', 28153),
(144661, 'ruRU', '', 'Что? И все?', 28153),
(144660, 'ruRU', '', 'Увидимся!', 28153),
(144659, 'ruRU', '', 'Чего надо?', 28153),
(144658, 'ruRU', '', 'Ну что, вперед?', 28153),
(144657, 'ruRU', '', 'Привет! Как делишки?', 28153),
(144656, 'ruRU', 'Такова, значит, моя судьба... Прекрасно. Просто великолепно...', '', 28153),
(144655, 'ruRU', 'Это лучшее, что ты можешь придумать? Серьезно?', '', 28153),
(144654, 'ruRU', 'У тебя что, нет других дел? Например, ну... пойти мурлоков целовать?', '', 28153),
(144653, 'ruRU', 'Ну хватит уже! Я заслуживаю больше уважения!', '', 28153),
(144652, 'ruRU', 'Ладно-ладно.', '', 28153),
(144651, 'ruRU', 'Да, да... Двигай уже.', '', 28153),
(144650, 'ruRU', 'До встречи.', '', 28153),
(144649, 'ruRU', 'Вооружен и опасен!', '', 28153),
(144648, 'ruRU', 'К бою готов!', '', 28153),
(144647, 'ruRU', 'Щелкай, щелкай... если хочешь лишиться пальца.', '', 28153),
(144646, 'ruRU', 'А день так хорошо начинался.', '', 28153),
(144645, 'ruRU', 'Меня зовут Патч, но ты можешь звать меня \"сэр\".', '', 28153),
(144644, 'ruRU', 'Крайние меры недооценивают.', '', 28153),
(144643, 'ruRU', 'Люблю, когда все идет по плану.', '', 28153),
(144642, 'ruRU', 'До встречи.', '', 28153),
(144641, 'ruRU', 'Что будем делать?', '', 28153),
(144640, 'ruRU', 'Приказы будут?', '', 28153),
(144639, 'ruRU', 'Йоу!', '', 28153),
(144638, 'ruRU', 'Это что, твоя фишка? Сейчас у всех есть своя фишка.', '', 28153),
(144637, 'ruRU', 'Хочешь знать, откуда эти черепа?', '', 28153),
(144636, 'ruRU', 'К сожалению, название \"Розовое Копье\" уже было занято.', '', 28153),
(144635, 'ruRU', 'Я потерял голову! Примерно... такого размера. Найдешь – дай мне знать.', '', 28153),
(144634, 'ruRU', 'Нужна будет помощь – приходи.', '', 28153),
(144633, 'ruRU', 'Не связывайся с вуду.', '', 28153),
(144632, 'ruRU', 'Будь настороже.', '', 28153),
(144631, 'ruRU', 'Что у тебя, босс?', '', 28153),
(144630, 'ruRU', 'За Черное Копье!', '', 28153),
(144629, 'ruRU', 'Я слушаю.', '', 28153),
(144628, 'ruRU', 'Что ж... видимо, придется. Начинаю процесс пересоздания вселенной.', '', 28153),
(144627, 'ruRU', 'Интенсивность нажатий не влияет на быстродействие системы.', '', 28153),
(144626, 'ruRU', 'Новая потенциальная цель для сдерживания.', '', 28153),
(144625, 'ruRU', 'Ошибка. Не повторяйте попытку.', '', 28153),
(144624, 'ruRU', 'Взаимодействие окончено.', '', 28153),
(144623, 'ruRU', 'Возобновляю протокол сдерживания.', '', 28153),
(144622, 'ruRU', 'Повторное сканирование.', '', 28153),
(144621, 'ruRU', '', 'Здравствуй, $p! Пришло время странствий по Азероту – новые земли и союзники ждут!$B$BОкулет уже подготовил порталы – ты найдешь их внизу.', 28153),
(144620, 'ruRU', 'Порча обнаружена. Задача: остановить любой ценой.', '', 28153),
(144619, 'ruRU', 'Протокол высшего приоритета: сдерживание порчи.', '', 28153),
(144618, 'ruRU', 'Хезрел включен. Цель: сдерживание порчи.', '', 28153),
(144617, 'ruRU', '', 'Твои шутки устарели... они даже старше меня.', 28153),
(144616, 'ruRU', '', 'Знаешь историю о тортолланке, которая впала в бешенство и набросилась на одно надоедливое создание?', 28153),
(144614, 'ruRU', '', 'Не буди во мне черепашку-ниндзя.', 28153),
(144613, 'ruRU', '', 'Мы закончили?', 28153),
(144612, 'ruRU', '', 'Подоставай кого-нибудь другого.', 28153),
(144611, 'ruRU', '', 'Ну наконец-то.', 28153),
(144610, 'ruRU', '', 'Уф. Что такое?', 28153),
(144609, 'ruRU', '', 'Тебе правда нужно поговорить со мной?', 28153),
(144608, 'ruRU', '', 'Что ты хочешь?', 28153),
(144605, 'ruRU', 'Завязывай с этим... иначе и твоя душа пойдет в оплату долга!', '', 28153),
(144604, 'ruRU', 'Бесплатный совет... Никогда не заключай сделок с лоа смерти!', '', 28153),
(144603, 'ruRU', 'Смотри не потеряй душу.', '', 28153),
(144602, 'ruRU', 'Ступай осторожно.', '', 28153),
(144601, 'ruRU', 'Береги себя.', '', 28153),
(144600, 'ruRU', 'Приветствую.', '', 28153),
(144599, 'ruRU', 'Что тебе нужно от Ханзабу?', '', 28153),
(144598, 'ruRU', 'Еще столько нужно сделать.', '', 28153),
(144597, 'ruRU', 'Отстань, или проглотишь жабу! Живьем!', '', 28153),
(144596, 'ruRU', 'Твое кваканье не убедит даже головастика.', '', 28153),
(144595, 'ruRU', 'Моя ярость сейчас выпрыгнет наружу!', '', 28153),
(144594, 'ruRU', 'Хочешь поцеловать меня? Я так и думал.', '', 28153),
(144593, 'ruRU', 'До скорого.', '', 28153),
(144592, 'ruRU', 'Смотри не квакнись.', '', 28153),
(144591, 'ruRU', 'Пусть тебе попадаются только свежие мухи.', '', 28153),
(144590, 'ruRU', 'Говори.', '', 28153),
(144589, 'ruRU', 'Ты хочешь поговорить с Краг\'вой?', '', 28153),
(144588, 'ruRU', 'Чего тебе?', '', 28153),
(144587, 'ruRU', 'Скоро увидимся... ОЧЕНЬ скоро.', '', 28153),
(144586, 'ruRU', 'Все, иди уже!', '', 28153),
(144585, 'ruRU', 'Рано или поздно... все приходят ко мне.', '', 28153),
(144584, 'ruRU', 'Хочешь выпить? Как насчет коктейля \"зомби\"? Ха-ха-ха!', '', 28153),
(144583, 'ruRU', 'Я вижу мертвых людей. И не только людей.', '', 28153),
(144582, 'ruRU', 'Хм... Вижу, кому-то нравятся опасные игры.', '', 28153),
(144581, 'ruRU', 'Потише там. Не забывай, с кем имеешь дело.', '', 28153),
(144580, 'ruRU', 'Привет-привет! Хочешь заключить сделку?', '', 28153),
(144579, 'ruRU', 'Чего ты попросишь у смерти?', '', 28153),
(144578, 'ruRU', 'Что привело тебя к старому одинокому Бвонсамди?', '', 28153),
(144577, 'ruRU', 'Я готов.', 'Я готова.', 28153),
(144576, 'ruRU', 'Мы должны остановить это безумие, пока еще не поздно.', '', 28153),
(144575, 'ruRU', '', 'Буду держаться рядом с ним, а то он снова потеряется.', 28153),
(144574, 'ruRU', 'Забрали прямо у нас из-под носа! Это ужасно!', '', 28153),
(144573, 'ruRU', 'Нет-нет, это какая-то ошибка. По моим вычислениям, он должен быть...', '', 28153),
(144572, 'ruRU', 'Странные результаты. Если бы только эти... как же их... маленькие... э... бородатики?.. дали мне сосредоточиться!', '', 28153),
(144571, 'ruRU', 'Я должен попробовать снова. Кстати, отличная работа. Правда, я думал, наши враги будут несколько повыше.', '', 28153),
(144570, 'ruRU', 'Я так понимаю, ты справишься с любым вмешательством?', '', 28153),
(144569, 'ruRU', 'Сюда! Как только я начну провидение, то сосредоточу на нем все свое внимание.', '', 28153),
(144568, 'ruRU', 'Аргус Порабощенный разворачивает модули пересозидания!', 'Аргус Порабощенный разворачивает модули пересозидания!', 28153),
(144567, 'ruRU', '', 'Нуу пришел помочь нам. Я знала, что ты нас найдешь!', 28153),
(144566, 'ruRU', 'Акведуки сильно повреждены и содержат нестабильную энергию. Пока что проход туда закрыт.', 'Акведуки сильно повреждены и содержат нестабильную энергию. Пока что проход туда закрыт.', 28153),
(144565, 'ruRU', 'Я присмотрю за ним. Кажется, ему нравится бродить по саду.', 'Я присмотрю за ним. Кажется, ему нравится бродить по саду.', 28153),
(144564, 'ruRU', '', 'Отлично! Я впечатлен!', 28153),
(144563, 'ruRU', '', 'Поначалу направление ци на объект кажется сложным.\n\nТы, в первом ряду, попробуй ударить вон тот манекен.', 28153),
(144562, 'ruRU', 'Эй, $p... Хочешь что-то купить?', '', 28153),
(144561, 'ruRU', 'Что там у тебя, $p? Это что, столетний цвет?', '', 28153),
(144560, 'ruRU', '', 'Нам надо начинать готовиться к следующему сезону посадки, Джаден.', 28153),
(144559, 'ruRU', 'Хм... этому чили чего-то не хватает... Надо добавить жару.', '', 28153),
(144558, 'ruRU', '', 'Занча! Камень возвращения опять не перезаряжен?', 28153),
(144557, 'ruRU', 'Покаа-а-а-а-а-а!', '', 28153),
(144556, 'ruRU', 'Хорошо тебе поплавать.', '', 28153),
(144555, 'ruRU', 'Вода – это круто. Я люблю купаться. А ты любишь воду? А за что любишь? Я – потому что она мокрая. Ну круто же, да?', '', 28153),
(144554, 'ruRU', 'Я амфуби... фанфиби... э-э... гр-р... амфибия!', '', 28153),
(144553, 'ruRU', 'Тортол-тортол-тортол, я качу, куда хочу. Тортол-тортол-тортол, мои лапки, как у жабки.', '', 28153),
(144552, 'ruRU', 'Когда я вырасту, я прочитаю все-все-ВСЕ свитки!', '', 28153),
(144551, 'ruRU', 'А где ты носишь вещи, если у тебя нет панциря?', '', 28153),
(144550, 'ruRU', 'Обожаю кувыркаться!', '', 28153),
(144549, 'ruRU', 'Скоро мне будет столько же лет, сколько тебе!', '', 28153),
(144548, 'ruRU', 'Ладно, ступай. О чем с тобой разговаривать...', '', 28153),
(144547, 'ruRU', 'Помни – не все в океане так же очаровательны и благовоспитанны, как я.', '', 28153),
(144546, 'ruRU', 'Найдешь что-нибудь редкое – приноси.', '', 28153),
(144545, 'ruRU', 'Возвращайся, когда будет, что рассказать.', '', 28153),
(144544, 'ruRU', 'Я видел такое, от чего всякий бы посерел.', '', 28153),
(144543, 'ruRU', 'Подойди ближе и не мямли.', '', 28153),
(144542, 'ruRU', 'Здравствуй, господин и/или госпожа.', '', 28153),
(144541, 'ruRU', 'Есть какие-нибудь древности? Хотя бы от двухсот лет.', '', 28153),
(144540, 'ruRU', '', 'Ты куда это собираешься?!', 28153),
(144539, 'ruRU', '', 'Пока-пока.', 28153),
(144538, 'ruRU', '', 'Однажды я украла альпаку и отвела в храм. Но мама велела ее отпустить.', 28153),
(144537, 'ruRU', '', 'Как-то раз я победила искателя приключений и забрала его череп. Он был больше твоего...', 28153),
(144536, 'ruRU', '', 'Однажды я поймала за хвост брутозавра, и он тянул меня за собой тридцать два с половиной шага!', 28153),
(144535, 'ruRU', 'Злобный альбатрос спикировал на вылупляющееся яйцо.', '', 28153),
(144534, 'ruRU', '', 'Однажды я поймала саурида. Он был очень-очень-очень-очень-очень-очень большой. Мне сказали, это равазавр, но, наверное, взрослые как всегда наврали.', 28153),
(144533, 'ruRU', '', 'Однажды я поймала вот такую здоровенную рыбу. Но это оказался всего лишь проклятый стражник.', 28153),
(144532, 'ruRU', '', 'Таз\'окун!', 28153),
(144531, 'ruRU', '', 'Таз\'динго!', 28153),
(144530, 'ruRU', '', 'Мой лоа твоего лоа побьет!', 28153),
(144529, 'ruRU', '', 'Когда я вырасту, стану лоа!', 28153),
(144528, 'ruRU', 'Не забывай – мы теперь друзья!', '', 28153),
(144527, 'ruRU', 'Ты куда?', '', 28153),
(144526, 'ruRU', 'Лоа такие здоровские. Они могут просто взять и проглотить тебя!', '', 28153),
(144525, 'ruRU', 'Когда я вырасту, я стану друидом-брутозавром. Р-р-р!', '', 28153),
(144524, 'ruRU', 'У меня есть десять пальцев. И только шесть из них мои.', '', 28153),
(144523, 'ruRU', 'Кто-то украл мой ящик сушеных голов. Не ты?', '', 28153),
(144522, 'ruRU', 'О, привет.', '', 28153),
(144521, 'ruRU', 'Таз\'окун!', '', 28153),
(144520, 'ruRU', 'Таз\'динго!', '', 28153),
(144519, 'ruRU', 'Р-р-р!', '', 28153),
(144518, 'ruRU', 'Лоа здесь особенно сильны.', 'Лоа здесь особенно сильны.', 28153),
(144517, 'ruRU', 'Пусть духи хранят тебя.', 'Пусть духи хранят тебя.', 28153),
(144516, 'ruRU', 'Лоа всегда следят за нами.', 'Лоа всегда следят за нами.', 28153),
(144515, 'ruRU', 'Выпей эти две пилюли и проспись. Утром поговорим.', 'Выпей эти две пилюли и проспись. Утром поговорим.', 28153),
(144513, 'ruRU', 'Ты испытываешь судьбу!', 'Ты испытываешь судьбу!', 28153),
(144512, 'ruRU', 'У меня только лучшее джуджу.', 'У меня только лучшее джуджу.', 28153),
(144511, 'ruRU', 'Духи шепчут твое имя.', 'Духи шепчут твое имя.', 28153),
(144510, 'ruRU', 'С каким лоа у тебя сделка?', 'С каким лоа у тебя сделка?', 28153),
(144509, 'ruRU', '', 'Вперед, за будущее Зандалара!', 28153),
(144508, 'ruRU', 'Уф... Не лучшие условия для знакомства. Мне лучше вернуться поскорее, а то Кугро будет недоволен.', '', 28153),
(144498, 'ruRU', 'Зандалары выстоят.', 'Зандалары выстоят.', 28153),
(144497, 'ruRU', 'Не пресмыкайся перед слабыми.', '', 28153),
(144496, 'ruRU', 'Пролей кровь своих врагов.', '', 28153),
(144495, 'ruRU', 'Да насытит тебя плоть твоих врагов.', '', 28153),
(144494, 'ruRU', 'Чего тебе, дитя Орды?', '', 28153),
(144493, 'ruRU', 'Ты ходишь по моим землям.', '', 28153),
(144492, 'ruRU', 'Ты хищник или жертва?', '', 28153),
(144491, 'ruRU', 'Хочешь заключить сделку?', '', 28153),
(144490, 'ruRU', 'Расскажи другим обо мне.', '', 28153),
(144489, 'ruRU', 'Да не учуют тебя враги.', '', 28153),
(144488, 'ruRU', 'Сделай свою стаю сильнее.', '', 28153),
(144486, 'ruRU', 'Если думаешь, что сможешь убежать, помни – я умею открывать двери.', '', 28153),
(144484, 'ruRU', 'Продолжай в том же духе и станешь моей добычей.', '', 28153),
(144481, 'ruRU', 'Я мастер перевоплощения, вожак стаи и владыка охоты.', '', 28153),
(144480, 'ruRU', 'Что привело тебя к владыке охоты?', '', 28153),
(144479, 'ruRU', 'Желаешь заключить сделку?', '', 28153),
(144478, 'ruRU', '', 'Пусть ветер дует тебе в спину... и уносит подальше.', 28153),
(144477, 'ruRU', '', 'Помни, небеса – мои.', 28153),
(144476, 'ruRU', '', 'Да обрушишь ты смерть с небес.', 28153),
(144475, 'ruRU', '', 'Ветра подчиняются моей воле.', 28153),
(144474, 'ruRU', '', 'Я сброшу тебя на скалы!', 28153),
(144473, 'ruRU', '', 'Хочешь увидеть мою ярость?', 28153),
(144472, 'ruRU', '', 'Ты испытываешь мое терпение.', 28153),
(144471, 'ruRU', '', 'Почему я должна дышать твоим воздухом?', 28153),
(144470, 'ruRU', '', 'Что такое, дитя?', 28153),
(144469, 'ruRU', '', 'Хочешь заключить сделку?', 28153),
(144468, 'ruRU', '', 'Эй, |3-6($pr)... Тебе не надоело выглядеть как саурид? После моего моджо будешь выглядеть как дьявозавр.', 28153),
(144462, 'ruRU', '', 'Выбирай лоа с умом.', 28153),
(144461, 'ruRU', '', 'Никогда не теряй следа врага.', 28153),
(144460, 'ruRU', '', 'За стаю.', 28153),
(144459, 'ruRU', '', 'Никогда не приручай зверя внутри себя.', 28153),
(144458, 'ruRU', '', 'Дай волю своей дикости.', 28153),
(144457, 'ruRU', '', 'Будь неподалеку, может, ты мне еще пригодишься.', 28153),
(144456, 'ruRU', '', 'И-и... пока хватит.', 28153),
(144455, 'ruRU', '', 'Так что давай, продолжай.', 28153),
(144454, 'ruRU', '', 'Если не прекратишь, мой муж будет ревновать.', 28153),
(144453, 'ruRU', '', 'Не сдерживай в себе зверя.', 28153),
(144452, 'ruRU', 'Пора взять ситуацию в свои руки. Я не позволю тебе сорвать эту операцию!', '', 28153),
(144451, 'ruRU', 'Спасибо, $n. Похоже, Кугро не сидел без дела. Итак... что делать со всеми этими свитками?', '', 28153),
(144450, 'ruRU', '', 'Лоа здесь особенно сильны.', 28153),
(144449, 'ruRU', '', 'Что заставило тебя выбрать этот облик?', 28153),
(144448, 'ruRU', 'Ты не мой связной! Сюда, ребята, здесь свежее мясо!', '', 28153),
(144447, 'ruRU', '', 'Я служу Гонку, мастеру перевоплощения.', 28153),
(144446, 'ruRU', '<Отдать свитки Итокке.>', '<Отдать свитки Итокке.>', 28153),
(144445, 'ruRU', '', 'Если бы Нуу был здесь... Он всегда знает, что делать.', 28153),
(144444, 'ruRU', '', 'О, привет! Ты кто? Я Ууна. Хочешь дружить? Может, вместе мы выберемся отсюда!', 28153),
(144443, 'ruRU', 'Эй! У меня для тебя кое-что есть! Личный оберег Зула для защиты от сауридов! Отгоняет этих мерзких воришек!', '', 28153),
(144442, 'ruRU', '', 'Слишком ярко! Слишком ярко! О-ой!', 28153),
(144441, 'ruRU', 'Приветствую тебя, $gпутник:путница;. \n\nОтложи оружие и отдохни немного.\n\nВойна подождет.', '', 28153),
(144440, 'ruRU', 'Приветствую, пакура\'ай!', '', 28153),
(144439, 'ruRU', 'Выбирай лоа с умом.', '', 28153),
(144438, 'ruRU', 'Как говорит мой лоа: \"Уходи!\"', '', 28153),
(144437, 'ruRU', 'Пусть Па\'ку выследит твоих врагов!', '', 28153),
(144436, 'ruRU', 'Лети на крыльях ветра войны!', '', 28153),
(144435, 'ruRU', 'Отлично! Именно здесь!', '', 28153),
(144434, 'ruRU', 'Да-да, продолжай... Только чуть правее...', '', 28153),
(144433, 'ruRU', 'Вот бы моя жена уделяла мне столько же внимания.', '', 28153),
(144432, 'ruRU', 'Как говорит мой лоа: \"Не трогай!\"', '', 28153),
(144431, 'ruRU', 'Как говорит мой лоа... Пригнись! Ха-ха-ха-ха!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144430, 'ruRU', 'Хочешь полетать с ящерами?', '', 28153),
(144429, 'ruRU', 'Небо – мои глаза.', '', 28153),
(144428, 'ruRU', 'Я служу Па\'ку, одной из старейших лоа.', '', 28153),
(144427, 'ruRU', '', 'Я защищаю тех, кто не в силах защитить себя.', 28153),
(144425, 'ruRU', 'У всех есть своя роль, даже у тебя.', '', 28153),
(144424, 'ruRU', 'Ни одно из великих событий нашего времени не обошлось без твоего участия. Интересно...', '', 28153),
(144423, 'ruRU', 'Близятся жуткие дни.', '', 28153),
(144422, 'ruRU', 'Жутко будет. Правда жутко.', '', 28153),
(144421, 'ruRU', 'Империя троллей возродится. Я предвидел это.', '', 28153),
(144420, 'ruRU', 'Тролли были первыми правителями этого мира, будут и последними.', '', 28153),
(144419, 'ruRU', 'Судьба не на твоей стороне.', '', 28153),
(144418, 'ruRU', 'Я уже знаю, что ты скажешь, поэтому давай быстрее.', '', 28153),
(144417, 'ruRU', 'Я видел конец этого мира, и тебе он не понравится.', '', 28153),
(144416, 'ruRU', '', 'Зандалары выстоят.', 28153),
(144415, 'ruRU', '', 'Мы отомстим за павших.', 28153),
(144414, 'ruRU', '', 'Пусть черепа врагов украсят твои одежды.', 28153),
(144413, 'ruRU', '', 'Времена меняются. И зандалары должны меняться вместе с ними.', 28153),
(144412, 'ruRU', '', 'Дела не ждут. Говори скорее.', 28153),
(144411, 'ruRU', 'Пусть враги трепещут от одного твоего имени.', '', 28153),
(144410, 'ruRU', 'Да здравствует Зандалар!', '', 28153),
(144409, 'ruRU', 'Пусть Резан дарует тебе силу.', '', 28153),
(144408, 'ruRU', 'Хорошо быть королем.', '', 28153),
(144407, 'ruRU', 'Перед тобой король Растахан.', '', 28153),
(144406, 'ruRU', 'Добро пожаловать в Зулдазар.', '', 28153),
(144405, 'ruRU', 'Ты хищник... или жертва?', '', 28153),
(144404, 'ruRU', '', 'Здесь так темно. Мне бы хоть что-то рассмотреть.', 28153),
(144403, 'ruRU', '', 'Но ведь мы друзья. Значит, все будет хорошо.', 28153),
(144402, 'ruRU', '', 'Зато теперь мы вместе. Просто... не знаем, где мы.', 28153),
(144401, 'ruRU', '', 'Помогите! Помогите!!!', 28153),
(144400, 'ruRU', '', 'Кто ты? Ты поможешь мне?', 28153),
(144399, 'ruRU', '', 'Так темно... Я ничего не вижу.', 28153),
(144397, 'ruRU', '', 'Вопрос с Элисандой решен, но в городе еще столько всего нужно сделать...', 28153),
(144396, 'ruRU', '', 'Ночнорожденные воистину свободны. Мы больше не нуждаемся в Ночном Колодце и силе, которую он даровал.$B$BТеперь мы сами распоряжаемся своей судьбой.', 28153),
(144395, 'ruRU', 'Я принес несколько образцов, чтобы развеять безосновательные слухи о том, что наше вино слишком мерзкое... то есть резкое!', '', 28153),
(144394, 'ruRU', 'Некоторые виноторговцы бросили свое традиционное ремесло и занялись культивированием других растений.', '', 28153),
(144393, 'ruRU', 'Когда мы прибыли, тролли крови бились со стражей. Они не ждали нападения сзади.', '', 28153),
(144392, 'ruRU', 'Ого какой огромный. Мне понадобится твоя помощь.', '', 28153),
(144391, 'ruRU', 'Если увидишь кучку свинобразов, брось в них иглобомбу – пусть узнают, каково это!', '', 28153),
(144390, 'ruRU', 'Наверняка это было больно! Проваливай с моей земли!', '', 28153),
(144389, 'ruRU', 'Ха, прямо промеж глаз!', '', 28153),
(144388, 'ruRU', 'Можешь вернуться и передать Роуз, что со мной все в порядке, но я не уйду с фермы. Я никогда не покину их.', '', 28153),
(144387, 'ruRU', 'Да, так пойдет. Они всегда любили это место...', '', 28153),
(144386, 'ruRU', 'Можешь пройти через портал в Оргриммар, чтобы встретиться с нашими союзниками-ордынцами в их столице в Калимдоре.', '', 28153),
(144385, 'ruRU', '', 'Рокхан! Ты в порядке? Похоже, тут была битва.', 28153),
(144384, 'ruRU', 'Слышал, что в Даларане под нужды магической транспортировки выделен целый этаж. $B$BТолько подумать, сколько возможностей!', '', 28153),
(144383, 'ruRU', 'Поддерживать эти порталы открытыми крайне утомительно. К тому же, они отвлекают меня от важных исследований!$B$BУверен, с помощью телемантии можно достичь более стабильных результатов.', '', 28153),
(144382, 'ruRU', 'Кто сказал, что у гоблинов нет культуры?', '', 28153),
(144381, 'ruRU', 'У них даже наш барабан есть!', '', 28153),
(144380, 'ruRU', '...и найди свободный барабан!', '', 28153),
(144379, 'ruRU', 'Добро пожаловать в \"Пьяный барабанщик\", $p! Выпей чего-нибудь...', '', 28153),
(144378, 'ruRU', 'Ах ты! А я думал, у меня был верный план!', '', 28153),
(144377, 'ruRU', 'Бестолочь! Ты заплатишь за проход под моим мостом!', '', 28153),
(144376, 'ruRU', 'Здорово! Это мой мост. Хочешь пройти – плати дань троллю, или заплатишь кровью!', '', 28153),
(144375, 'ruRU', 'Я готов приступить к испытанию.', 'Я готова приступить к испытанию.', 28153),
(144374, 'ruRU', '', 'А если привязать к ним взрывчатку? Вот будет умора... Взрывающиеся динозавры!', 28153),
(144373, 'ruRU', '', 'Мне нравится твой энтузиазм, Сахарр. Но зандалары наверняка любят, чтобы их оружие зачаровывали мощной магией, а не уродством, истекающим жиром.', 28153),
(144372, 'ruRU', 'Что... что с нами стало?', '', 28153),
(144371, 'ruRU', '', 'Нет! Отпусти! На помощь! Где же ты? ПОМОГИ МНЕ!', 28153),
(144370, 'ruRU', '', 'И снова темно! Куда делся свет? Не бросай меня!', 28153),
(144369, 'ruRU', '', 'У меня был такой же жезл! Но я давно его потеряла.', 28153),
(144368, 'ruRU', '', 'Корона! Ой, какая красивая!', 28153),
(144367, 'ruRU', '', 'Нуу! Я боялась, что уже тебя не увижу! Как ты здесь оказался?', 28153),
(144366, 'ruRU', '', 'Ой, стало чуть светлее! Я даже что-то вижу... почти.', 28153),
(144365, 'ruRU', '', 'Что это? Свет во тьме! Такой яркий...', 28153),
(144364, 'ruRU', 'Она... обещала...', '', 28153),
(144363, 'ruRU', 'Она сказала, что так мы сможем быть вместе!', '', 28153),
(144362, 'ruRU', '', 'Лоа с нами, и наши сердца полны отваги! Нас ждет победа!', 28153),
(144361, 'ruRU', '', 'Мы перебьем троллей крови. Они не успеют выпустить против нас чудовище, которое хотят призвать!', 28153),
(144360, 'ruRU', '', 'Враги хотят уничтожить все, что нам дорого, но мы не дадим их планам сбыться! Будущее Зандалара зависит от нас!', 28153),
(144359, 'ruRU', '', 'Солдаты... друзья! Мы выдержали немало испытаний, но уже скоро все решится.', 28153),
(144358, 'ruRU', 'Покажи, куда я могу отправиться.', 'Покажи, куда я могу отправиться.', 28153),
(144357, 'ruRU', 'Тебе нужен паром?', 'Тебе нужен паром?', 28153),
(144356, 'ruRU', '', 'Хорошо, что я в сапожках!', 28153),
(144355, 'ruRU', 'Я возьму с собой отряд тортолланов и отправлюсь в Зул\'джан пешком. А вам удачи.', '', 28153),
(144354, 'ruRU', 'Я живу и умру... за Орду!', 'Я живу и умру... за Орду!', 28153),
(144353, 'ruRU', 'Кровь и честь!', 'Кровь и честь!', 28153),
(144352, 'ruRU', 'Арати принадлежит Орде!', 'Арати принадлежит Орде!', 28153),
(144351, 'ruRU', 'За мной!', 'За мной!', 28153),
(144350, 'ruRU', 'Смерть Альянсу!', 'Смерть Альянсу!', 28153),
(144349, 'ruRU', 'За Орду!', 'За Орду!', 28153),
(144348, 'ruRU', 'Сюда! К бою!', 'Сюда! К бою!', 28153),
(144347, 'ruRU', 'Вперед, рубаки! Нам нужно выиграть войну!', 'Вперед, рубаки! Нам нужно выиграть войну!', 28153),
(144346, 'ruRU', 'Я – Грал!', '', 28153),
(144345, 'ruRU', 'К югу ты найдешь то, что осталось от моего храма. Я встречу тебя там, и мы покажем этим нагам ярость лоа акулы!', '', 28153),
(144344, 'ruRU', 'О... это было вкусно.', '', 28153),
(144343, 'ruRU', 'Вас надо загнать в самые темные глубины!', '', 28153),
(144342, 'ruRU', 'Нагам не место в Атал\'Грале!', '', 28153),
(144341, 'ruRU', 'Вкусный и терпкий запах насыщенной яростью крови наг... сладкие нежные кусочки... Это мне по нраву.', '', 28153),
(144340, 'ruRU', '', 'Матушка, Бенджамин все мне рассказал.\n\nРаньше ты меня не слышала, но, может быть, теперь слышишь? Я хочу, чтобы ты мне объяснила.', 28153),
(144339, 'ruRU', '', 'Матушка, я знаю, что тебя здесь нет. Но если ты все же меня слышишь...', 28153),
(144338, 'ruRU', 'Может, управляющий я не из лучших, но моя мать была невероятна. И видеть, что она так низко пала...$b$bМы справимся, $n. Спасибо тебе за помощь.', '', 28153),
(144337, 'ruRU', '', 'Эй, ты куда?', 28153),
(144336, 'ruRU', '', 'Пожалуйста, не бросай меня.', 28153),
(144335, 'ruRU', 'Повелительница глубин приведет нас к победе!', 'Повелительница глубин приведет нас к победе!', 28153),
(144334, 'ruRU', 'Рад видеть всех в целости и сохранности, все благодаря... а вот и наша героиня дня!', '', 28153),
(144333, 'ruRU', 'Ты остаешься или уходишь?', '', 28153),
(144332, 'ruRU', 'Прошу прощения. Я должен найти сестру.', '', 28153),
(144331, 'ruRU', 'Когда отец умер, матушка исчезла. Но я никогда не думал...', '', 28153),
(144330, 'ruRU', 'Они с моим отцом всю жизнь трудились, чтобы наладить это дело и обеспечить нас с сестрой.', '', 28153),
(144329, 'ruRU', 'Эта ведьма... она была моей матерью.', '', 28153),
(144328, 'ruRU', 'Похоже, ты знаешь толк в животных. Чем могу помочь?', '', 28153),
(144327, 'ruRU', 'Что такое? Ищешь что-то?', '', 28153),
(144326, 'ruRU', 'Великолепно! А теперь еще раз, с начала.', '', 28153),
(144325, 'ruRU', 'Сразу тратить много энергии опасно. Умерьте пыл, ученики.', '', 28153),
(144324, 'ruRU', 'Сконцентрированная ци очень сильна. Мастер Тау Ли вам все покажет.', '', 28153),
(144323, 'ruRU', 'Для исцеления нужно сосредоточить внутреннюю энергию и передать ее.', '', 28153),
(144322, 'ruRU', 'Хорошо, что нам не пришлось отдать ВСЕ, ЧТО ЕСТЬ.', 'Хорошо, что нам не пришлось отдать ВСЕ, ЧТО ЕСТЬ.', 28153),
(144321, 'ruRU', 'Наши оскверненные сородичи все еще скитаются в лесах.', 'Наши оскверненные сородичи все еще скитаются в лесах.', 28153),
(144320, 'ruRU', '', 'Моя жизнь... за Орду.', 28153),
(144319, 'ruRU', '', 'Мы скоро увидимся.', 28153),
(144318, 'ruRU', '', 'Кровь и гром!', 28153),
(144317, 'ruRU', '', 'Тебе конец!', 28153),
(144316, 'ruRU', '', 'Мои клинки жаждут твоей плоти.', 28153),
(144315, 'ruRU', '', 'Тебе не по силам тягаться с орком!', 28153),
(144314, 'ruRU', '', 'Твои кости – ничто для моих клинков!', 28153),
(144313, 'ruRU', '', 'Держать строй! Враг не пройдет!', 28153),
(144312, 'ruRU', 'Спасибо тебе.', '', 28153),
(144311, 'ruRU', 'Если я не вспомню тебя, когда мы встретимся снова, ну извини.', '', 28153),
(144310, 'ruRU', 'Спасибо за помощь с Тороком. Он отказывался признать опасность желанной им силы.', 'Спасибо, что $gразделался:разделалась; с Тороком. Он отказывался видеть опасность в той силе, которой добивался.', 28153),
(144309, 'ruRU', '<Спящий таурен громко храпит и переворачивается на бок.>', '<Спящая тауренка громко храпит и переворачивается на бок.>', 28153),
(144308, 'ruRU', 'Хр-р-р...', 'Хр-р-р...', 28153),
(144307, 'ruRU', 'Да, принцесса. Что бы ни случилось.', '', 28153),
(144306, 'ruRU', '', 'Только так можно спасти мой народ, Рокхан. Ради безопасности своих подданных я пойду на все. Ты со мной?', 28153),
(144305, 'ruRU', 'До сих пор не могу поверить, что мои братья и сестры поддались Скверне.', 'До сих пор не могу поверить, что мои братья и сестры поддались Скверне.', 28153),
(144304, 'ruRU', '', 'Дочери мои, вот так нужно принимать гостей!', 28153),
(144303, 'ruRU', '', 'Моя кровь... отомстит...', 28153),
(144302, 'ruRU', '', 'За матриархов!', 28153),
(144301, 'ruRU', 'Сосредоточьтесь. Выпустите из себя энергию ци.', '', 28153),
(144300, 'ruRU', '', 'Твоя сущность послужит другим!', 28153),
(144299, 'ruRU', '', 'Как же приятно будет вытянуть из тебя все силы.', 28153),
(144298, 'ruRU', '', 'Твоя кровь пригодится для наших ритуалов!', 28153),
(144297, 'ruRU', '', 'Я заберу твою кровь. Остальное сгниет.', 28153),
(144296, 'ruRU', '', 'Твоя кровь напоит мой клинок.', 28153),
(144295, 'ruRU', 'Если тебя нужно подбросить, ты знаешь, где меня найти.', '', 28153),
(144294, 'ruRU', '', 'Больше крови ма\'дам!', 28153),
(144293, 'ruRU', '', 'Из твоей кожи получится хорошая упряжь.', 28153),
(144292, 'ruRU', '', 'Небеса... зовут.', 28153),
(144291, 'ruRU', '', 'Славный денек для битвы.', 28153),
(144290, 'ruRU', '', 'Кроги хорошо сегодня поужинают!', 28153),
(144289, 'ruRU', 'Держись! Я посмотрю, как там Сатао.', '', 28153),
(144288, 'ruRU', 'НАЧАЛО – Эксперимент со слизью\n\nОживление слизи оказалось успешным. Вместо растворения органической материи, такой как мясо или растительность, они могут кормиться исключительно медом. Обильные отходы можно ферментировать в бочках, из них получается очень крепкий и вкусный мед.\n\nОднако если не соблюдать условия содержания, слизь в итоге будет искать и поглощать целые ульи. В процессе слизи становятся более агрессивными и неуправляемыми.\n\nЕстественно, в ответ пчелы начинают лучше защищаться, и с ними становится сложнее работать. Очевидно, что в конце концов мне нужно найти решение, ведь заменить пчел не так-то легко.', '', 28153),
(144287, 'ruRU', '', 'Покиза...', 28153),
(144286, 'ruRU', '', 'Кровавый бог... поглотит... все...', 28153),
(144285, 'ruRU', '', 'Ха-ха-ха!', 28153),
(144284, 'ruRU', '', 'Зулдазар... падет...', 28153),
(144283, 'ruRU', '', 'Гачага!', 28153),
(144282, 'ruRU', '', 'Сестры... отомстят... за меня...', 28153),
(144281, 'ruRU', '', 'Г\'уун... забери мою... кровь...', 28153),
(144280, 'ruRU', '', 'Г\'уун!', 28153),
(144279, 'ruRU', '<Тсунга ласково ворчит на вас.>', '', 28153),
(144278, 'ruRU', 'Я явился из тумана, чтобы предупредить народ Зандалара. Азерит помог гориллам обрести высочайший интеллект. А это значит, что грядет война.', '', 28153),
(144277, 'ruRU', 'Покиза...', '', 28153),
(144276, 'ruRU', 'Кровавый бог... поглотит... все...', '', 28153),
(144275, 'ruRU', 'Вы... уже... проиграли...', '', 28153),
(144274, 'ruRU', 'Зулдазар... падет...', '', 28153),
(144273, 'ruRU', 'Гачага!', '', 28153),
(144272, 'ruRU', 'Жизнь за ма\'ду!', '', 28153),
(144271, 'ruRU', 'Г\'уун... забери мою... кровь...', '', 28153),
(144270, 'ruRU', 'Г\'уун!', '', 28153),
(144269, 'ruRU', 'Хорошо, хорошо. Еще раз!', '', 28153),
(144268, 'ruRU', 'Не суетись.', '', 28153),
(144266, 'ruRU', '', 'Я помогу укрепить защиту города. Встретимся у баррикады!', 28153),
(144265, 'ruRU', '', 'Мы побеждаем! Идем, нужно поговорить с мэром Ройстоном.', 28153),
(144264, 'ruRU', '', 'Аллерия вздыхает и хмурится.', 28153),
(144263, 'ruRU', '<Постоять и послушать.>', '<Постоять и послушать.>', 28153),
(144262, 'ruRU', '', '<Взгляд Аллерии соскальзывает с безучастного лица статуи на табличку, где выгравирована эпитафия.>', 28153),
(144261, 'ruRU', 'Не отступать! Мы удержим строй!', 'Не отступать! Мы удержим строй!', 28153),
(144260, 'ruRU', 'С последним вздохом Рон\'кора слышится тихий стон.', '', 28153),
(144259, 'ruRU', '', 'Я сошью себе новую шляпу из твоего желудка!', 28153),
(144258, 'ruRU', '', 'Нет! Моя крошка!', 28153),
(144257, 'ruRU', '', 'Не трогай моего малыша! Ты никогда не выйдешь из этой ямы!', 28153),
(144256, 'ruRU', '', 'Они хотят нас убить! Взять их, моя крошка!', 28153),
(144255, 'ruRU', 'Бвонсамди... будь милостив!', 'Бвонсамди... будь милостив!', 28153),
(144254, 'ruRU', 'Да здравствует... Зандалар...', 'Да здравствует... Зандалар...', 28153),
(144253, 'ruRU', 'Мы тебя упокоим, Урок! Прости нас, но выбора нет!', '', 28153),
(144252, 'ruRU', 'Что за... Что эти твари делали внутри Урока?', '', 28153),
(144251, 'ruRU', 'Мы уже близко! Мне только снаряжение нужно...', '', 28153),
(144250, 'ruRU', 'Почему так?..', 'Почему так?..', 28153),
(144249, 'ruRU', 'Бвонсамди... идет... за мной...', 'Бвонсамди... идет... за мной...', 28153),
(144248, 'ruRU', 'Держать строй, приближаются новые враги!', 'Держать строй, приближаются новые враги!', 28153),
(144247, 'ruRU', 'Жизнь... за Зандалар...', 'Жизнь... за Зандалар...', 28153),
(144245, 'ruRU', 'Ди чука Зандалар!', 'Ди чука Зандалар!', 28153),
(144243, 'ruRU', 'Убить всех!', 'Убить всех!', 28153),
(144242, 'ruRU', 'За истинный Зандалар!', 'За истинный Зандалар!', 28153),
(144240, 'ruRU', 'Твоя кровь напоит нашу землю!', 'Твоя кровь напоит нашу землю!', 28153),
(144239, 'ruRU', 'Мы тебя закопаем!', 'Мы тебя закопаем!', 28153),
(144238, 'ruRU', 'Ты умрешь здесь и сейчас!', 'Ты умрешь здесь и сейчас!', 28153),
(144237, 'ruRU', 'Да здравствует Зандалар!', 'Да здравствует Зандалар!', 28153),
(144236, 'ruRU', 'Принцесса велела найти монстров. Но здесь повсюду монстры!', '', 28153),
(144235, 'ruRU', 'Где же солнце? Ничего не вижу в этом болоте.', '', 28153),
(144234, 'ruRU', 'Бессмыслица какая-то! Я вижу большую нору. На этой карте нет норы!', '', 28153),
(144233, 'ruRU', 'О! Это... здесь... ничего... Какое разочарование.', '', 28153),
(144232, 'ruRU', 'Таз\'окун! Возможно, это кусок азерита!', '', 28153),
(144231, 'ruRU', 'Это что, какая-то иголка? Фу! Почему она липкая?', '', 28153),
(144230, 'ruRU', 'Как это мило. Таланджи наверняка понравится.', '', 28153),
(144229, 'ruRU', 'Вы на прицеле у порабощенного проклятием арбалетчика! Уклоняйтесь!', '', 28153),
(144228, 'ruRU', 'Мне здесь не часто заказывают мечи, но я люблю их ковать. А вот причина, почему нам нужно столько, мне не нравится!', '', 28153),
(144227, 'ruRU', 'Теперь понятно, почему этого болота боятся.', '', 28153),
(144226, 'ruRU', 'Как странно.', '', 28153),
(144225, 'ruRU', 'Вряд ли я когда-нибудь отмою эту грязь с рук. Мои бедные свитки.', '', 28153),
(144224, 'ruRU', 'Какой странный камень... О! Он пошевелился!', '', 28153),
(144223, 'ruRU', 'Это же просто удивительно...', '', 28153),
(144222, 'ruRU', 'Пусть Гонк не даст тебе сбиться с пути.', 'Пусть Гонк не даст тебе сбиться с пути.', 28153),
(144221, 'ruRU', 'Да хранит тебя Па\'ку.', 'Да хранит тебя Па\'ку.', 28153),
(144220, 'ruRU', 'Пусть Резан даст тебе силу.', 'Пусть Резан даст тебе силу.', 28153),
(144219, 'ruRU', 'Смотри под ноги.', 'Смотри под ноги.', 28153),
(144218, 'ruRU', 'Не забывай – ты гость в нашем городе.', 'Не забывай – ты гость в нашем городе.', 28153),
(144217, 'ruRU', 'Да здравствует Зандалар!', 'Да здравствует Зандалар!', 28153),
(144216, 'ruRU', 'Нужна защита?', 'Нужна защита?', 28153),
(144215, 'ruRU', 'Лучшего предложения тебе не найти.', 'Лучшего предложения тебе не найти.', 28153),
(144214, 'ruRU', 'Ты здесь зачем?', 'Ты здесь зачем?', 28153),
(144213, 'ruRU', 'Привет тебе.', 'Привет тебе.', 28153),
(144209, 'ruRU', 'Я поклялся защищать королевскую семью.', 'Я поклялась защищать королевскую семью.', 28153),
(144208, 'ruRU', 'Мы защитим наше королевство.', 'Мы защитим наше королевство.', 28153),
(144201, 'ruRU', 'Начнем.', 'Начнем.', 28153),
(144200, 'ruRU', 'Мы совсем близко, $n.$b$bОдно слово, и я начну поиски с помощью провидения.$b$bО, совсем забыл. Наши противники разбили лагерь прямо на той стороне, на пляже. Внимательно следи за местностью, а то вдруг мы попадем в засаду.$b$bНадеюсь, ты защитишь меня, если на нас нападут!', '', 28153),
(144199, 'ruRU', 'Продолжайте в том же духе! Сдерживайте этих ублюдков!', '', 28153),
(144198, 'ruRU', 'Ночь спускается! Поддерживайте костры! Кричите, если нужно больше дров.', '', 28153),
(144197, 'ruRU', 'Не пропускайте ни одного монстра! Мы убили здоровяка, но потеряли слишком много лодок.', '', 28153),
(144196, 'ruRU', 'Если отдохнули, меняйтесь с кем-нибудь на баррикаде! Мы все выдержим!', '', 28153),
(144195, 'ruRU', 'Мне нужны добровольцы, которые отправятся к Эштону! Он может соорудить дымовые шашки.', '', 28153),
(144194, 'ruRU', 'В первую очередь накормите детей, потом – раненых!', '', 28153),
(144193, 'ruRU', 'Лекарям нужно смениться и отдохнуть! И тебе тоже, Кристин!', '', 28153),
(144192, 'ruRU', 'Укрепляйте баррикады! Тащите все, что не прибито, а если неприбитого не осталось, вырывайте гвозди!', '', 28153),
(144191, 'ruRU', 'Детеныш крога издает странный писк и шаркает ногами по кувшинке.', '', 28153),
(144190, 'ruRU', 'Эти моряки должны присматривать за Ордой, а не за нами.', 'Эти моряки должны присматривать за Ордой, а не за нами.', 28153),
(144189, 'ruRU', 'Чем быстрее мы найдем то, что ищем, и уплывем, тем лучше.', 'Чем быстрее мы найдем то, что ищем, и уплывем, тем лучше.', 28153),
(144188, 'ruRU', 'Орда близко, берегись!', 'Орда близко, берегись!', 28153),
(144187, 'ruRU', 'Хорошо бы, Лига исследователей выделила больше людей для этой экспедиции.', 'Хорошо бы, Лига исследователей выделила больше людей для этой экспедиции.', 28153),
(144186, 'ruRU', 'Если бы мы здесь не присматривали за кланом Черного Железа, кто знает, что бы они натворили?', 'Если бы мы здесь не присматривали за кланом Черного Железа, кто знает, что бы они натворили?', 28153),
(144185, 'ruRU', '', 'А еще их детеныши! Я организую фотобудку и плюшевых динозавриков. Конечно, ты тоже получишь свою долю, Джангалар. Где-то 70 на 30. В мою пользу, ведь это была моя идея.', 28153),
(144184, 'ruRU', 'Идем, там еще одному из наших нужна помощь.', '', 28153),
(144183, 'ruRU', '', 'ПОВТОРНОЕ ИСПОЛЬЗОВАНИЕ: С помощью инжектора надо разозлить Бен\'джина, а потом последовать за ним и помочь ему уничтожить паразитов.', 28153),
(144182, 'ruRU', 'Когда мы закончим тут копать, Орда уже будет на полпути к Стальгорну!', 'Когда мы закончим тут копать, Орда уже будет на полпути к Стальгорну!', 28153),
(144181, 'ruRU', 'Клан Черного Железа не против жара. Но эта влажность...', 'Клан Черного Железа не против жара. Но эта влажность...', 28153),
(144180, 'ruRU', 'Лиге исследователей явно нравится копаться в земле, хотя надо выиграть войну.', 'Лиге исследователей явно нравится копаться в земле, хотя надо выиграть войну.', 28153),
(144179, 'ruRU', 'И мы ушли из нашей горы ради этого?', 'И мы ушли из нашей горы ради этого?', 28153),
(144178, 'ruRU', 'Не стоит так драматизировать.', '', 28153),
(144177, 'ruRU', '', 'Царапины... почва убрана неравномерно... и как теперь выставлять этот образец?!', 28153),
(144176, 'ruRU', 'Ну вот, вполне неплохо.', '', 28153),
(144175, 'ruRU', '', 'Стой!', 28153),
(144174, 'ruRU', 'Я рекомендую ускорить темп. Воспользуйся этим устройством.', '', 28153),
(144173, 'ruRU', 'Прекрасно? Мадам, такими темпами мы целый год провозимся.', '', 28153),
(144172, 'ruRU', '', 'Ах, чудесно! Разве это не прекрасно?', 28153),
(144171, 'ruRU', '', 'Постарайся не повредить окаменелость... Превосходно.', 28153),
(144170, 'ruRU', '', 'Очень хорошо. Ровными движениями.', 28153),
(144169, 'ruRU', '', 'Осторожнее! Это место – смертельная ловушка!', 28153),
(144168, 'ruRU', 'Прекрасная работа! Это зелье должно помочь нам одолеть деревянных чудовищ. Только осторожно, не пролей.', '', 28153),
(144167, 'ruRU', 'Спасибо тебе за ее возвращение.', '', 28153),
(144166, 'ruRU', '', 'ПОВТОРНОЕ ИСПОЛЬЗОВАНИЕ: Вот корпус для хитроумного устройства – инжектора. Пожалуйста, вставьте.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144165, 'ruRU', '', 'Привет, папочка!', 28153),
(144164, 'ruRU', 'Пенни! Моя милая девочка!', '', 28153),
(144163, 'ruRU', 'Все эти победы на лесопилке – временны! Скоро она снова будет нашей!', '', 28153),
(144162, 'ruRU', 'Пошли искать твоего папу.', 'Пошли искать твоего папу.', 28153),
(144161, 'ruRU', '', 'Привет! Как тебя зовут?', 28153),
(144160, 'ruRU', 'Ты даже не представляешь, в какой ты опасности!', 'Ты даже не представляешь, в какой ты опасности!', 28153),
(144159, 'ruRU', 'Нас слишком много, вы обречены!', 'Нас слишком много, вы обречены!', 28153),
(144158, 'ruRU', 'Всех не переловите!', 'Всех не переловите!', 28153),
(144157, 'ruRU', 'Меня раскрыли!', 'Меня раскрыли!', 28153),
(144156, 'ruRU', 'Смотрите! У них даже наш барабан есть!\n\nКто сказал, что у гоблинов нет культуры?', '', 28153),
(144153, 'ruRU', 'Теперь надо добавить пару капель взрывчатой смолы. Только не тряси колбу!', '', 28153),
(144152, 'ruRU', 'Добавь немного серы. Смотри не вдохни пары!', '', 28153),
(144151, 'ruRU', 'Осторожно добавь щепотку лепестков жар-цвета.', '', 28153),
(144150, 'ruRU', 'Добавь селитры, чтобы усилить эффект!', '', 28153),
(144148, 'ruRU', 'Краг\'ва кивает вашему спутнику.', '', 28153),
(144147, 'ruRU', 'Краг\'ва и детеныш крога общаются между собой.', '', 28153),
(144146, 'ruRU', 'Нет! Я ни за что не вернусь в камеру!', '', 28153),
(144145, 'ruRU', '', 'Защищайте святилище! Нельзя терять контроль.', 28153),
(144144, 'ruRU', 'Чудесно! Я буду говорить, что добавлять в котел. Внимательно следуй моим указаниям, иначе результаты получатся... взрывоопасными.', '', 28153),
(144142, 'ruRU', 'Пока, Пенни!', '', 28153),
(144141, 'ruRU', '', 'Ага! До скорого, Джо!', 28153),
(144140, 'ruRU', '', 'Привет, Джо!', 28153),
(144139, 'ruRU', 'Привет, Пенни. Ты к папе идешь?', '', 28153),
(144138, 'ruRU', 'Да что со всеми творится?!', '', 28153),
(144137, 'ruRU', '', 'Мне нужно лечение!', 28153),
(144136, 'ruRU', '', 'Сдавайтесь стихиям!', 28153),
(144135, 'ruRU', '$n, я не могу сделать его прежним. Ему лучше остаться с тобой. Заботься о нем. И оберегай.', '', 28153),
(144134, 'ruRU', 'Понятно.', '', 28153),
(144133, 'ruRU', 'Подойди ближе, малыш.', '', 28153),
(144132, 'ruRU', 'Кошмар...', '', 28153),
(144131, 'ruRU', 'Луна... восходит...', '', 28153),
(144130, 'ruRU', 'Дальние берега...', '', 28153),
(144129, 'ruRU', 'Так, больше не мешай...', '', 28153),
(144128, 'ruRU', 'Еще две кружки... и самый большой перчик...', '', 28153),
(144127, 'ruRU', 'Центральная гора... опрокидывается...', '', 28153),
(144126, 'ruRU', 'Еще десять минут...', '', 28153),
(144125, 'ruRU', 'Пока нет...', '', 28153),
(144124, 'ruRU', 'Слинки предостерегающе рычит.', '', 28153),
(144123, 'ruRU', 'Тебе конец!', 'Тебе конец!', 28153),
(144122, 'ruRU', 'Пойми... вы все уже мертвы...', '', 28153),
(144121, 'ruRU', 'Вас всех ждет... только... смерть...', '', 28153),
(144120, 'ruRU', 'Ты ничто... против... Бездны.', '', 28153),
(144119, 'ruRU', 'Моя смерть... ничего не значит...', '', 28153),
(144118, 'ruRU', 'Владыки... знают...', '', 28153),
(144117, 'ruRU', 'Бездна заберет... всех...', '', 28153),
(144116, 'ruRU', 'Все равно... все погрузится... во Тьму...', '', 28153),
(144115, 'ruRU', 'Твой труп найдут в гавани!', 'Твой труп найдут в гавани!', 28153),
(144114, 'ruRU', 'Кул-Тирасу Альянс не нужен!', 'Кул-Тирасу Альянс не нужен!', 28153),
(144113, 'ruRU', 'Я сброшу тебя в волны!', 'Я сброшу тебя в волны!', 28153),
(144112, 'ruRU', '<Встать в очередь на \"Битву за Стромгард\">', '<Встать в очередь на \"Битву за Стромгард\">', 28153),
(144111, 'ruRU', 'С помощью этого стола вы можете вставать в очередь на фронт.', '', 28153),
(144110, 'ruRU', 'Кэтрин хочет, чтобы мы все отправились на дно!', 'Кэтрин хочет, чтобы мы все отправились на дно!', 28153),
(144109, 'ruRU', 'Азерот принадлежит нам.', '', 28153),
(144108, 'ruRU', 'Империя возродится!', '', 28153),
(144107, 'ruRU', 'Найдите их!', '', 28153),
(144106, 'ruRU', 'Все сгинет.', '', 28153),
(144105, 'ruRU', 'Все падут.', '', 28153),
(144104, 'ruRU', 'Надежды нет... жизни нет.', '', 28153),
(144103, 'ruRU', 'Все исчезнет.', '', 28153),
(144102, 'ruRU', 'Все станет тенью.', '', 28153),
(144101, 'ruRU', 'Бездна поглотит все.', '', 28153),
(144100, 'ruRU', '', 'Друиды, в атаку!', 28153),
(144099, 'ruRU', '<свистит>', '', 28153),
(144097, 'ruRU', '', 'Значит, план \"Б\"...', 28153),
(144096, 'ruRU', 'Мы собрали все данные. Нужно только выбраться с ними.', '', 28153),
(144095, 'ruRU', '', 'Нас раскрыли!', 28153),
(144094, 'ruRU', 'Об-об-об-об-наружена <помехи> кровь Азерот. Запрос: установка недостающей матрицы <помехи> данных.', '', 28153),
(144093, 'ruRU', 'Ох... Отвратительно!', '', 28153),
(144092, 'ruRU', 'Джабари, у тебя память элекка и острый ум Гонка.', '', 28153),
(144091, 'ruRU', 'Конечно, \"жгучие\" специи и смертельная доза яда – совсем одно и то же...', '', 28153),
(144090, 'ruRU', 'Не надо со мной нянчиться, Джабари! Я пробовал стряпню Ха\'ли – и ничего!', '', 28153),
(144089, 'ruRU', 'Хватит! Ты как брутозавр с больным горлом.', '', 28153),
(144088, 'ruRU', 'Тише, брат. Вот, возьми.', '', 28153),
(144087, 'ruRU', 'Да успокойся уже наконец!', '', 28153),
(144086, 'ruRU', 'Вот так! Посмотрим, что дальше...', '', 28153),
(144085, 'ruRU', 'А тебе явно не чужда алхимия! Уж я-то вижу!', '', 28153),
(144084, 'ruRU', 'Отлично! А теперь...', '', 28153),
(144082, 'ruRU', 'Первый снаряд готов. Когда я начну стрелять, они поймут, что мы здесь.$b$bНу что, начнем?', '', 28153),
(144081, 'ruRU', 'Рано или поздно они сюда заглянут...', '', 28153),
(144080, 'ruRU', '', 'Ну ладно! Пошли!', 28153),
(144079, 'ruRU', '', 'Стой! Возьми меня за руку!', 28153),
(144078, 'ruRU', 'Праудмур падет!', 'Праудмур падет!', 28153),
(144077, 'ruRU', 'Моя смерть ничего не изменит.', 'Моя смерть ничего не изменит.', 28153),
(144076, 'ruRU', 'Ты об этом пожалеешь!', 'Ты об этом пожалеешь!', 28153),
(144075, 'ruRU', 'Тебе здесь не место, чужак!', 'Тебе здесь не место, чужак!', 28153),
(144074, 'ruRU', 'Боралус принадлежит нам!', 'Боралус принадлежит нам!', 28153),
(144073, 'ruRU', '', 'Между нами и Атал\'Дазаром полно воинов Зула. Нужно от них избавиться.', 28153),
(144072, 'ruRU', 'Эльфы...', 'Эльфы...', 28153),
(144071, 'ruRU', 'Растарский ликтор сплевывает на землю.', 'Растарский ликтор вздыхает.', 28153),
(144070, 'ruRU', 'Ну, конечно. Он же тако-о-ой примитивный! Итак, 3... 2... 1...', '', 28153),
(144069, 'ruRU', '', 'Смотри, чтобы на фоне был этот здоровый уродливый храм.', 28153),
(144068, 'ruRU', '', 'Все наши друзья в Луносвете будут так завидовать, когда увидят эту картину.', 28153),
(144067, 'ruRU', 'Мое испытание окончено, последний штрих моей истории завершен, я вернулся в материальный мир.', 'Мое испытание окончено, последний штрих моей истории завершен, я вернулась в материальный мир.', 28153),
(144066, 'ruRU', 'Существо поймало мой взгляд и проникло в разум, внушая знания, нужные для его призыва.', 'Существо поймало мой взгляд и проникло в разум, внушая знания, нужные для его призыва.', 28153),
(144065, 'ruRU', 'Формирование завершилось, существо обрело жизнь и закричало.', 'Формирование завершилось, существо обрело жизнь и закричало.', 28153),
(144064, 'ruRU', 'Ритуал завершен, я видел, как существо срослось на моих глазах.', 'Ритуал завершен, я видела, как существо срослось на моих глазах.', 28153),
(144063, 'ruRU', 'Войдя в комнату, я заметил на полу четыре руны. Видимо, для них и предназначались чернила.', 'Войдя в комнату, я заметила на полу четыре руны. Видимо, для них и предназначались чернила.', 28153),
(144062, 'ruRU', 'Когда я достал достаточно чернил, то почувствовал, что меня странным образом тянет в одну из дальних комнат этих залов.', 'Когда я достала достаточно чернил, то почувствовала, что меня странным образом тянет в одну из дальних комнат этих залов.', 28153),
(144061, 'ruRU', 'Скелет на полу напомнил мне о том, что я смертен. Интересно, а прочие проваливали это испытание?', 'Скелет на полу напомнил мне о том, что я смертна. Интересно, а прочие проваливали это испытание?', 28153),
(144060, 'ruRU', 'Эти липучки становились проблемой.', 'Эти липучки становились проблемой.', 28153),
(144059, 'ruRU', 'Тина была ключом к загадке. И пока я находил все, что мне нужно.', 'Тина была ключом к загадке. И пока я находила все, что мне нужно.', 28153),
(144058, 'ruRU', 'Каким-то образом я понял, что надо делать. И решил продолжать.', 'Каким-то образом я поняла, что надо делать. И решила продолжать.', 28153),
(144057, 'ruRU', '\"Цвет черный – прочь, цвет алый – тянет. Убийца кровный твой восстанет\".', '\"Цвет черный – прочь, цвет алый – тянет. Убийца кровный твой восстанет\".', 28153),
(144056, 'ruRU', '\"Что льет перо, что вены льют, – тотчас смешается все тут\".', '\"Что льет перо, что вены льют, – тотчас смешается все тут\".', 28153),
(144055, 'ruRU', 'Я проснулся в какой-то комнате. Странный голос читал стихи у меня в голове.', 'Я проснулась в какой-то комнате. Странный голос читал стихи у меня в голове.', 28153),
(144054, 'ruRU', 'Вы начинаете писать в книге: \"Когда мое перо коснулось страницы, я почувствовал, как меня затягивает\".', 'Вы начинаете писать в книге: \"Когда мое перо коснулось страницы, я почувствовала, как меня затягивает\".', 28153),
(144053, 'ruRU', 'Вы просматриваете всю книгу, но все страницы в ней пусты. Вы в раздражении смотрите на Крондо: может, она знает, как пройти это испытание?', '', 28153),
(144052, 'ruRU', 'Скорее бы прочитать о том, что с тобой произошло.', '', 28153),
(144051, 'ruRU', 'Возьми одно из перьев и начни писать. Не волнуйся, книга довершит остальное.', '', 28153),
(144050, 'ruRU', 'Все просто, радость моя. Нужно написать в книге свою собственную историю.', '', 28153),
(144049, 'ruRU', 'О нет, начинается...', '', 28153),
(144048, 'ruRU', 'Мне бы хотелось обменять часть игл.', 'Мне бы хотелось обменять часть игл.', 28153),
(144047, 'ruRU', 'Мда, все пошло совсем не по плану. Попробуем еще раз!', '', 28153),
(144046, 'ruRU', 'Алхимия – наука точная! Пожалуйста, постарайся быть внимательнее.', '', 28153),
(144045, 'ruRU', 'Что-то пошло не так. Придется начать с самого начала!', '', 28153),
(144044, 'ruRU', 'Смесь воспламенилась! Нужно начать заново!', 'Смесь воспламенилась! Нужно начать заново!', 28153),
(144043, 'ruRU', 'Зул предвидел этот день. А вы напрасно пытаетесь изменить свою неотвратимую участь.', '', 28153),
(144042, 'ruRU', 'Зул... не говорил... что победят меня...', '', 28153),
(144041, 'ruRU', 'Вы ни за что не успеете вовремя!', '', 28153),
(144040, 'ruRU', 'Я готов начинать!', 'Я готова начинать!', 28153),
(144039, 'ruRU', 'Погоди! Мне уже лучше! Ох...', 'Стой! Мне уже лучше! Ох...', 28153),
(144038, 'ruRU', 'Каким же я был глупцом!', 'Каким же я был глупцом!', 28153),
(144037, 'ruRU', 'Я больше не могу слышать ее песню...', 'Я больше не могу слышать ее песню...', 28153),
(144036, 'ruRU', 'Она никогда тебя не полюбит!', 'Она никогда тебя не полюбит!', 28153),
(144035, 'ruRU', 'Не-е-ет, любовь моя!', 'Не-е-ет, любовь моя!', 28153),
(144034, 'ruRU', 'Любовь ранит.', 'Любовь ранит.', 28153),
(144033, 'ruRU', 'Она того стоила!', 'Она того стоила!', 28153),
(144032, 'ruRU', 'Сколько... сладкой муки.', 'Сколько... сладкой муки.', 28153),
(144031, 'ruRU', 'Эй, детка! Смотри, сейчас я кому-то наваляю.', 'Эй, детка! Смотри, сейчас я кому-то наваляю.', 28153),
(144030, 'ruRU', 'На мою девушку пялишься?!', 'На мою девушку пялишься?!', 28153),
(144029, 'ruRU', 'Любовь побеждает все!', 'Любовь побеждает все!', 28153),
(144028, 'ruRU', 'Она моя! МОЯ!', 'Она моя! МОЯ!', 28153),
(144027, 'ruRU', 'Благодаря тебе город спасен, а я наконец обрел уверенность в себе. Элби и Терольд, займитесь восстановлением. Думаю, мы скоро встретимся.', '', 28153),
(144026, 'ruRU', 'Не смей ее трогать!', 'Не смей ее трогать!', 28153),
(144025, 'ruRU', 'Зул хочет пробудить Дазара?! Я не буду спокойно смотреть, как этот так называемый пророк оскверняет останки первого короля. Идем с нами. Встречаемся у южных ворот.', '', 28153),
(144024, 'ruRU', 'Мне пора возвращаться в долину Штормов. Мой дядя и жрецы моря могут что-то знать об этой темной магии.', '', 28153),
(144023, 'ruRU', 'Дипуорден... Он всегда был непрост, но я не ждал, что он овладеет столь мощной магией. Обуздать силу, способную причинить океану столько боли...', '', 28153),
(144022, 'ruRU', 'Отвали, она занята!', 'Отвали, она занята!', 28153),
(144021, 'ruRU', '', 'Наконец-то! Небесные баллисты уничтожены. Летите, дети мои, убейте этих еретиков!', 28153),
(144020, 'ruRU', 'Мыс Рыбака спасен, но я не уверен, что все закончено. Дипуорден был хитер, но раньше такое ему было не по плечу.', '', 28153),
(144019, 'ruRU', 'Я защищу тебя, любовь моя!', 'Я защищу тебя, любовь моя!', 28153),
(144018, 'ruRU', 'Я так ее люблю!', 'Я так ее люблю!', 28153),
(144017, 'ruRU', 'Рука судьбы насытилась. Я доставлю тебя в безопасное место. Судьба иногда бывает благосклонной.', '', 28153),
(144016, 'ruRU', 'Уходи из нашего города, $p! Ты обречешь нас всех на смерть!', '', 28153),
(144015, 'ruRU', 'Дорогу $p, избраннику великих лоа!', '', 28153),
(144013, 'ruRU', '', 'Знамения противоречивы... Тебя ждут тяжкие испытания, но ты их преодолеешь. Лоа не покинут тебя.', 28153),
(144012, 'ruRU', '', 'Боюсь, это все дурные предзнаменования... В будущем тебя ждут бесконечные беды. Мне жаль.', 28153),
(144011, 'ruRU', '', 'Избегай сегодня воды. Это опасно.', 28153),
(144010, 'ruRU', '', 'Пусто? Нет... Это нужно изменить.', 28153),
(144009, 'ruRU', '', 'Тебя ждут великие трудности и предательство. Осторожнее выбирай спутников.', 28153),
(144008, 'ruRU', '', 'Я уже очень, очень давно не слышала такого предзнаменования... Тебе нужно изменить свою судьбу.', 28153),
(144007, 'ruRU', '', 'Не стоит срезать углы на пути к своим целям. Любой компромисс или беспечность сулят ужасный конец.', 28153),
(144006, 'ruRU', '', 'Предупреждение с Той Стороны. Будь осторожнее.', 28153),
(144005, 'ruRU', '', 'Избегай Золотого города. Его посещение не стоит риска.', 28153),
(144004, 'ruRU', '', 'Боюсь, в будущее тебе придется отправиться вслепую.', 28153),
(144003, 'ruRU', '', 'Грала тянет в глубину невидимая рука.', 28153),
(144002, 'ruRU', '', 'Гнездо Шадры опустело.', 28153),
(144001, 'ruRU', '', 'Торкали спит.', 28153),
(144000, 'ruRU', '', 'Резан падает на землю... мертвым.', 28153),
(143999, 'ruRU', '', 'Бвонсамди предлагает сделку с ухмылкой.', 28153),
(143998, 'ruRU', '', 'Краг\'ва глотает стадо синих дикорогов...', 28153),
(143997, 'ruRU', '', 'Гонк совсем один, переплывает золотую реку.', 28153),
(143996, 'ruRU', '', 'Па\'ку закрывает глаза в темноте.', 28153),
(143995, 'ruRU', '', 'Это одно из самых страшных знамений. Будь осторожнее.', 28153),
(143994, 'ruRU', '', 'Темное знамение для всех нас. Что пришло с тобой к нашим берегам?', 28153),
(143993, 'ruRU', '', 'Ты зря тратишь свой потенциал. Обрети возможности, что лежат пред тобой, – или тебя предадут забвению, и ты пополнишь ряды безымянных мертвецов.', 28153),
(143992, 'ruRU', '', 'Разногласия между тобой и твоими союзниками угрожают всем нам. Тебе придется объединить Зандалар.', 28153),
(143991, 'ruRU', '', 'Недоброе знамение, но силой и упорством ты его одолеешь.', 28153),
(143990, 'ruRU', '', 'Враждующие вожди – это и не вожди вовсе. Нужно работать со своими соперниками, иначе будут последствия.', 28153),
(143989, 'ruRU', '', 'Надвигается тьма, что поглотит даже сильнейших из нас. Включая тебя.', 28153),
(143988, 'ruRU', '', 'Темное знамение для всех нас...', 28153),
(143987, 'ruRU', '', 'Смерть нового друга.', 28153),
(143986, 'ruRU', '', 'Солнце садится в темные болота Назмира.', 28153),
(143985, 'ruRU', '', 'Треснувшая чаша, из нее сочится вино.', 28153),
(143984, 'ruRU', '', 'Два жреца убивают друг друга.', 28153),
(143983, 'ruRU', '', 'Корабль людей пристает к нашим берегам...', 28153),
(143982, 'ruRU', '', 'Разрушенный трон из огня и льда...', 28153),
(143981, 'ruRU', '', 'Брутозавр тонет в крови.', 28153),
(143980, 'ruRU', '', 'Река крови, трупы плывут против течения...', 28153),
(143979, 'ruRU', 'За мной, Царапка, пошли!', 'За мной, Царапка, пошли!', 28153),
(143978, 'ruRU', 'Ура! Спасибо!', 'Ура! Спасибо!', 28153),
(143977, 'ruRU', 'Ого! Так-то лучше!', '', 28153),
(143976, 'ruRU', 'Я велел своим уходить, но они хотели все выяснить... Я еле выбрался... Если бы не ты, так бы и остался гнить в болоте.', '', 28153),
(143975, 'ruRU', '', 'Говори устами своего сосуда, Зетоа!', 28153),
(143974, 'ruRU', '', 'Говори устами своего сосуда, Илуны!', 28153),
(143973, 'ruRU', '', 'Мы готовы. Наполните мои сосуды и раскройте нам будущее.', 28153),
(143972, 'ruRU', '', 'Духи мертвых, духи лоа, духи заблудших и беспокойных, услышьте меня!', 28153),
(143971, 'ruRU', 'Я возвращаюсь на баррикады!', 'Я возвращаюсь на баррикады!', 28153),
(143970, 'ruRU', 'Я не мог пошевелиться!', 'Я не могла пошевелиться!', 28153),
(143969, 'ruRU', 'Я думал, меня утащат в лес!', 'Я думала, меня утащат в лес!', 28153),
(143968, 'ruRU', 'Они забрали наших людей в лес!', 'Они забрали наших людей в лес!', 28153),
(143967, 'ruRU', 'Я вернусь на баррикады!', 'Я вернусь на баррикады!', 28153),
(143966, 'ruRU', '', 'Все это – хорошие предзнаменования... Так действуй сегодня отважно!', 28153),
(143965, 'ruRU', 'Я уж думал, мне конец!', 'Я уж думала, мне конец!', 28153),
(143964, 'ruRU', 'Спасибо!', 'Спасибо!', 28153),
(143963, 'ruRU', '', 'Ящеры бегут в панике...', 28153),
(143962, 'ruRU', '', 'Веселое знамение... Не позволяй тревоге овладеть тобой. Счастье и чувство юмора приведут тебя к успеху.', 28153),
(143961, 'ruRU', 'Гниль разрастается!', '', 28153),
(143960, 'ruRU', 'Все... увядает...', '', 28153),
(143959, 'ruRU', '', 'Обычное благословение Шадры, но с неожиданным дополнением. Оно доброе, но я не совсем его понимаю.', 28153),
(143958, 'ruRU', '', 'Благословение защитника... Ты спасешь множество жизней, но, возможно, отдашь свою.', 28153),
(143957, 'ruRU', '', 'Лоа короля – это редкое знамение. Невероятно могущественное. Ты уничтожишь врагов короля.', 28153),
(143956, 'ruRU', '', 'Доброе знамение для долгой жизни и легкой смерти.', 28153),
(143955, 'ruRU', 'Нужно... питаться!', '', 28153),
(143954, 'ruRU', 'Увядайте!', '', 28153),
(143953, 'ruRU', 'Порча расцветает!', '', 28153),
(143952, 'ruRU', '', 'Учитывая, что этот остров – не твоя родина, это хорошее предзнаменование.', 28153),
(143951, 'ruRU', 'Растите!', '', 28153),
(143950, 'ruRU', '', 'Ты всегда будешь сражаться плечом к плечу с союзниками. Гонк не покинет тебя в час нужды.', 28153),
(143949, 'ruRU', '', 'Па\'ку направляет тебя на верный путь и очищает его от врагов...', 28153),
(143948, 'ruRU', 'Такая плодородная почва...', '', 28153),
(143947, 'ruRU', '', 'Грал перепрыгивает через королевский флот...', 28153),
(143946, 'ruRU', '', 'Яйца Шадры вылупляются. Бесчисленные глаза устремляются вперед...', 28153),
(143945, 'ruRU', '', 'Торкали стоит на вершине горы в одиночестве...', 28153),
(143944, 'ruRU', '', 'Резан топает ногой, и тролли крови разбегаются...', 28153),
(143943, 'ruRU', '', 'Бвонсамди отворачивается...', 28153),
(143942, 'ruRU', '', 'Краг\'ва глотает остров...', 28153),
(143941, 'ruRU', 'Гниение!', '', 28153),
(143940, 'ruRU', '', 'Гонк бежит рядом со своей стаей...', 28153),
(143939, 'ruRU', 'Время жатвы!', '', 28153),
(143938, 'ruRU', 'Гниль должна расти!', '', 28153),
(143937, 'ruRU', '', 'Почти всегда доброе предзнаменование, но все зависит от твоего друга...', 28153),
(143936, 'ruRU', '', 'Доброе знамение для всех нас. Тебе должны быть рады в Зандаларе.', 28153),
(143935, 'ruRU', '', 'Пусть многие считают иначе, но твой потенциал еще не раскрыт. Твоя сила возрастет, и мощь твоя будет выше всех ожиданий.', 28153),
(143934, 'ruRU', '', 'Это... неожиданное предзнаменование для чужака. Что это значит?', 28153),
(143933, 'ruRU', '', 'Сильное знамение! Оно сулит тебе что-то хорошее...', 28153),
(143932, 'ruRU', '', 'Доброе знамение! Наш народ будет расти и процветать. Интересно, что получаешь его именно ты...', 28153),
(143931, 'ruRU', '', 'Доброе знамение изобилия и наследия.', 28153),
(143930, 'ruRU', '', 'Доброе знамение силы, власти и успеха.', 28153),
(143929, 'ruRU', '', 'Бывший друг восстает из мертвых...', 28153),
(143928, 'ruRU', '', 'Солнце всходит над золотой водой...', 28153),
(143927, 'ruRU', '', 'Большое яйцо сильно раскачивается, но не трескается...', 28153),
(143926, 'ruRU', '', 'Все племена троллей, объединенные под знаменем зандаларов...', 28153),
(143925, 'ruRU', '', 'Отрубленная голова эльфа...', 28153),
(143924, 'ruRU', '', 'Древние воды, никем не тронутые...', 28153),
(143923, 'ruRU', '', 'Золотые маски...', 28153),
(143922, 'ruRU', '', 'Тень Па\'ку пересекает каменную тропу...', 28153),
(143921, 'ruRU', '', 'Ну хорошо. Посмотрим, что скажут тебе духи...', 28153),
(143920, 'ruRU', '', 'Ты точно хочешь это знать, $p?\n\nНе все предсказания говорят о великих деяниях и счастливых финалах...', 28153),
(143919, 'ruRU', 'Я не боюсь. Скажи, что там в моем будущем.', 'Я не боюсь. Скажи, что там в моем будущем.', 28153),
(143918, 'ruRU', 'Что там в моем будущем?', 'Что там в моем будущем?', 28153),
(143917, 'ruRU', '', 'Услышьте меня, духи потерянные и древние. Наполните мои сосуды и раскройте нам будущее.', 28153),
(143916, 'ruRU', 'Моя смерть ничего не изменит. Мы повсюду... у вас под ногами.', '', 28153),
(143915, 'ruRU', 'Вы все слабые... А мое племя... сильное...', 'Вы все слабые. А мое племя сильное.', 28153),
(143914, 'ruRU', '', 'Добро пожаловать в \"Салон заблудших душ\", $p.\n\nЧто-то ты поздно. Я и не знала, доберешься ли ты сюда.\n\nНу скажи, как тебе может помочь мадам Конавла?', 28153),
(143913, 'ruRU', 'Достойная... смерть.', 'Достойная... смерть.', 28153),
(143912, 'ruRU', 'Мы... покроем шипами весь мир!', 'Мы покроем шипами... весь мир...', 28153),
(143911, 'ruRU', 'Мое племя... станет только сильнее...', 'Мое племя... станет только сильнее...', 28153),
(143910, 'ruRU', 'Мой путь... окончен.', 'Мой путь... окончен.', 28153),
(143909, 'ruRU', 'Твоя смерть принесет мне славу!', 'Твоя смерть добавит мне почета.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143908, 'ruRU', 'Твоя кровь удобрит землю, шипы будут расти лучше!', 'Да! Твоя кровь удобрит землю, шипы будут расти лучше!', 28153),
(143907, 'ruRU', 'Мы не отступим! И не сдадимся!', 'Мы не отступим! И не сдадимся!', 28153),
(143906, 'ruRU', 'Почему компендиум кровопролития пуст?', 'Почему компендиум кровопролития пуст?', 28153),
(143905, 'ruRU', 'Ты пойдешь на корм вепрям.', 'Ты пойдешь на корм вепрям.', 28153),
(143904, 'ruRU', 'Нас не остановить!', 'Нас не остановить!', 28153),
(143903, 'ruRU', 'Эта земля теперь наша!', 'Теперь это наша земля!', 28153),
(143902, 'ruRU', 'Начать писать в книге.', 'Начать писать в книге.', 28153),
(143901, 'ruRU', 'Пролистать всю книгу.', 'Пролистать всю книгу.', 28153),
(143900, 'ruRU', 'Цара-а-апка-а!! Ты еще там?! Мяукни дважды, если меня слышишь!!!', 'Цара-а-апка-а! Ты еще там?! Мяукни дважды, если меня слышишь!!!', 28153),
(143899, 'ruRU', 'Следующие несколько страниц тоже пусты.', '', 28153),
(143898, 'ruRU', 'Мы тебя спустим, Царапка! Только будь паинькой!', 'Мы тебя спустим, Царапка! Только будь паинькой!', 28153),
(143897, 'ruRU', 'Все будет хорошо, Царапка! Держись там!', 'Все будет хорошо, Царапка! Держись там!', 28153),
(143896, 'ruRU', 'Перевернуть еще несколько страниц.', 'Перевернуть еще несколько страниц.', 28153),
(143895, 'ruRU', 'Страницы этой книги пусты.', '', 28153),
(143894, 'ruRU', 'Мрр-мяу!', '', 28153),
(143893, 'ruRU', 'Держись, Царапка! Помощь уже в пути!!!', 'Держись, Царапка! Помощь уже в пути!!!', 28153),
(143892, 'ruRU', 'Спускайся, Царапка, спускайся! Там опасно!', 'Спускайся, Царапка, спускайся! Там опасно!', 28153),
(143891, 'ruRU', 'Прыгай, Царапка! Я тебя поймаю!', 'Прыгай, Царапка! Я тебя поймаю!', 28153),
(143890, 'ruRU', 'Цара-а-апка-а-а!!! Спускайся!!!', 'Цара-а-апка-а-а!!! Спускайся!!!', 28153),
(143889, 'ruRU', '', '$r, я скормлю тебя своим питомцам!', 28153),
(143888, 'ruRU', 'Эй. Подойди-ка сюда.', '', 28153),
(143887, 'ruRU', 'Сюда!', '', 28153),
(143886, 'ruRU', 'Берегись!', '', 28153),
(143885, 'ruRU', 'Сюда.', '', 28153),
(143884, 'ruRU', 'Сюда.', '', 28153),
(143883, 'ruRU', 'Берегись!', '', 28153),
(143882, 'ruRU', 'Сюда!', '', 28153),
(143881, 'ruRU', 'Эй! Сюда.', '', 28153),
(143879, 'ruRU', 'Очищение!', '', 28153),
(143876, 'ruRU', 'Вот и все.', '', 28153),
(143875, 'ruRU', 'Кровь! Кровь! Кровь!', '', 28153),
(143874, 'ruRU', 'Зулдазар падет!', '', 28153),
(143873, 'ruRU', 'Свежее мясо!', '', 28153),
(143872, 'ruRU', 'Отдай свою кровь!', '', 28153),
(143871, 'ruRU', 'Твои кости нам пригодятся!', '', 28153),
(143870, 'ruRU', 'Твоя кровь будет моим даром Г\'ууну!', '', 28153),
(143869, 'ruRU', 'От Кровавого бога не спрячешься!', '', 28153),
(143868, 'ruRU', 'Гузинча!', '', 28153),
(143867, 'ruRU', 'Качаго!', '', 28153),
(143865, 'ruRU', 'А то, что мелким шрифтом, прочитать не судьба?\n\nДеньги не возвращаются. Никаких исключений. Никакого нытья.\n\nЯ знаю, что поднимет тебе настроение... \"Потрясающее падение от Крылонога\"!', '', 28153),
(143864, 'ruRU', 'Одно \"Потрясающее падение от Крылонога\", пожалуйста!', 'Одно \"Потрясающее падение от Крылонога\", пожалуйста!', 28153),
(143863, 'ruRU', 'Верни мне деньги.', 'Верни мне деньги.', 28153),
(143862, 'ruRU', 'С возвращением, $p!\n\nНесомненно, тебе нравится проводить время в обществе поклонников \"Потрясающего падения от Крылонога\"!\n\nТеперь, как его полноправный член, ты можешь совершать бессчетное число замедленных падений с этого смешного зиккурата. Только скажи, когда захочешь сделать это еще раз!\n\nДеньги не возвращаются. Никогда.', '', 28153),
(143861, 'ruRU', 'Вступайте в общество \"Потрясающего падения от Крылонога\" уже сегодня!\n\nЗа малую одноразовую плату вы сможете совершить бессчетное число замедленных падений с этого зиккурата. Ваше выживание гарантировано!\n\nДеньги не возвращаются.', '', 28153),
(143860, 'ruRU', 'Ветра здесь сильнее, чем в Крутогорье. Наше решение присоединиться к Орде уже окупается.', '', 28153),
(143859, 'ruRU', 'Обретите покой. Пройдите через Святилище и поделитесь своей силой с живыми.', '', 28153),
(143858, 'ruRU', '', 'Какой чудесный город. Исследовать мир – это так здорово!', 28153),
(143857, 'ruRU', 'Услышьте мой зов, братья и сестры. Ваши грехи прощены.', '', 28153),
(143856, 'ruRU', 'Начнем ритуал. Выпусти души из колокола.', '', 28153),
(143855, 'ruRU', 'Розалина, тебе придется подождать. У нас сегодня есть более насущные дела, чем охота.', '', 28153),
(143854, 'ruRU', '', 'Эй, Терольд, хватит прохлаждаться. Лучше благослови нашу охоту!', 28153),
(143853, 'ruRU', 'Заходи еще, $p!', '', 28153),
(143852, 'ruRU', 'Десять очков за плевок на любого тролля крови!', '', 28153),
(143851, 'ruRU', '\"Потрясающее падение от Крылонога!\" Расскажи друзьям!', '', 28153),
(143850, 'ruRU', 'Рад снова тебя видеть, $p. Счастливого падения!', '', 28153),
(143849, 'ruRU', 'Попробуй приземлиться на брутозавра!', '', 28153),
(143848, 'ruRU', 'Попробуй приземлиться в водопад!', '', 28153),
(143847, 'ruRU', 'Берегись терродактилей!', '', 28153),
(143846, 'ruRU', 'Счастливого пути, $p.', '', 28153),
(143845, 'ruRU', 'А-а-а!', '', 28153),
(143844, 'ruRU', 'Слава Альянсу.', '', 28153),
(143843, 'ruRU', 'Слава Орде!', '', 28153),
(143842, 'ruRU', 'Стромгард пал. Сдавайся, Роджерс, и спасешь свою шкуру.', '', 28153),
(143841, 'ruRU', 'А вот и он... мой молот!', '', 28153),
(143840, 'ruRU', 'Тук-тук, малыш Бронзобород. Есть кто дома?', '', 28153),
(143839, 'ruRU', 'Свет еще хранит меня. Я не проиграю так легко!', '', 28153),
(143838, 'ruRU', 'Адмирал Роджерс! Мы взяли штурмом цитадель. Ну и где твое возмездие, паладин?', '', 28153),
(143837, 'ruRU', 'Они считают, что пара солдат на лошадках нас остановит? Ха! Покажем им, на что способна Орда!', '', 28153),
(143836, 'ruRU', 'Крепость надо спасать! Подбейте вражьи танки, пока они далеко.', '', 28153),
(143835, 'ruRU', 'Наша оборона еще слаба. Войска Орды, вернитесь на базу и защищайте наши позиции!', '', 28153),
(143834, 'ruRU', 'Хорошо. Если хотите войны, вы ее получите. Высылайте батальон кавалерии, пусть их уничтожат!', '', 28153),
(143833, 'ruRU', 'Орда захватила контроль над Кругом стихий.', '', 28153),
(143832, 'ruRU', 'Новоземье у нас... Ждите в гости волков.', '', 28153),
(143831, 'ruRU', 'Оружейная готова.', '', 28153),
(143830, 'ruRU', 'Мастерская готова. Разрушители быстро разнесут укрепления Альянса!', '', 28153),
(143829, 'ruRU', 'Осадные машины, уничтожить их!', '', 28153),
(143828, 'ruRU', 'Тебя предупреждали, ордынское отродье. Готовься к смерти.', '', 28153),
(143827, 'ruRU', 'Эти земли принадлежали троллям, когда Альянс о них и слыхом не слыхивал.', '', 28153),
(143826, 'ruRU', 'Хм... А тебе подойдет.', '', 28153),
(143825, 'ruRU', 'Пока этой одежды будет достаточно.', '', 28153),
(143824, 'ruRU', 'Для строительства базы нам нужны железо и древесина. И то и другое можно добыть поблизости.', '', 28153),
(143823, 'ruRU', 'И не ты один, Бронзобород.', '', 28153),
(143822, 'ruRU', 'Может, в такой одежде тебе будет легче добывать древесину.', '', 28153),
(143821, 'ruRU', 'Ха! Подавись своим возмездием, Туралион!', '', 28153),
(143820, 'ruRU', 'Это земли Альянса! Захватчиков ожидает неотвратимое возмездие!', '', 28153),
(143819, 'ruRU', 'А теперь она принадлежит Орде!', '', 28153),
(143818, 'ruRU', 'Когда-то вся эта земля принадлежала троллям.', '', 28153),
(143817, 'ruRU', 'А... с радостью. Ты связался не с тем дворфом.', '', 28153),
(143816, 'ruRU', 'Мурадин! Покажись, подлый трус!', '', 28153),
(143815, 'ruRU', 'Оборона все еще слаба. Не дайте танкам подойти к нашим позициям!', '', 28153),
(143814, 'ruRU', 'На свою бы посмотрел, Бронзобород!', '', 28153),
(143813, 'ruRU', 'Прости меня, исследовательница.', '', 28153),
(143812, 'ruRU', 'Рад служить, исследовательница.', '', 28153),
(143811, 'ruRU', '', 'Битва окончена... а мы еще живы. Атина поплатится за это безумие!', 28153),
(143810, 'ruRU', '', 'Узрите разрушителя Зулдазара! Попробуйте нас остановить! Я хочу видеть ваши муки!', 28153),
(143809, 'ruRU', '', 'Вас даже немного жаль... все старания зря!', 28153),
(143808, 'ruRU', 'Работать на Реликварий – это так утомительно...', '', 28153),
(143807, 'ruRU', 'Ха! Слишком просто! Попробуй себя в деле. Дровам мы всегда рады.', '', 28153),
(143806, 'ruRU', 'Как скажешь, исследовательница.', '', 28153),
(143805, 'ruRU', 'Полностью располагай мною, исследовательница.', '', 28153),
(143804, 'ruRU', 'Счастлив помочь, исследовательница.', '', 28153),
(143803, 'ruRU', '', 'Хозяину будет хорошо в твоей шкуре!', 28153),
(143802, 'ruRU', '', 'Орда падет следом за Зулдазаром. Вы заплатите за то, что убили Хир\'ика! Вам некуда бежать.', 28153),
(143801, 'ruRU', '', 'Зулдазар падет... Мой хозяин освободится! Ваши лоа не остановят его!', 28153),
(143800, 'ruRU', 'Конечно, исследовательница.', '', 28153),
(143799, 'ruRU', 'Я скоро буду, исследовательница.', '', 28153),
(143798, 'ruRU', '', 'Интересно... Белот, посмотри на это и скажи, что ты видишь.', 28153),
(143797, 'ruRU', '', 'Куда ты удрал, Белот? Ты должен записать еще несколько ценных наблюдений.', 28153),
(143796, 'ruRU', '', 'Мой дорогой Белот, взгляни на это.', 28153),
(143795, 'ruRU', '', 'Нет времени отдыхать в Реликварии, Белот.', 28153),
(143794, 'ruRU', '', 'Белот, не трогай артефакты!', 28153),
(143793, 'ruRU', '', 'Это чудесно... Белот, иди и посмотри, насколько это чудесно!', 28153),
(143792, 'ruRU', '', 'Хезрел поднял щит! Прячься за ним!', 28153),
(143791, 'ruRU', '', 'Белот, ты опять замечтался? Мне бы не помешала твоя помощь.', 28153),
(143790, 'ruRU', '', 'Белот, будь любезен, запиши все, что я скажу.', 28153),
(143789, 'ruRU', 'Вольным гарпунщикам нужно много припасов для максимально эффективной работы! Моя задача – следить за запасами и пополнять их, а еще – чинить сломанные устройства и механизмы!$b$b...$b$bЗа день Гарпунщики много всего ломают.$b$bАккуратностью они не отличаются.', '', 28153),
(143788, 'ruRU', '', '$n, можно с тобой поговорить? Мне бы пригодилась твоя помощь.', 28153),
(143787, 'ruRU', '<<Событие начнется, когда мы с работниками подойдем к гатям с пушками. >>', '', 28153),
(143786, 'ruRU', 'Парадокс. Пара-докс. Па-ра-докс. Пар-ток-с. Пар-ток. Ток-пар. Ток-партос. Т\'паартос. Т\'паартос!', '', 28153),
(143785, 'ruRU', 'Они купились на мою уловку! Я всех обвел вокруг пальца. Приняли меня за простака... Уж теперь-то я им... Э-э... кто тут подслушивает?! М-м... Т\'паартос!', '', 28153),
(143784, 'ruRU', 'Т\'паартос не любит змей, злых детей, змей, темных пещер, змей... и малявок, которые тревожат Т\'паартоса понапрасну.', '', 28153),
(143783, 'ruRU', 'Конечно, Т\'паартос читал книги. В них было мало слов и много картинок... но были страницы!', '', 28153),
(143782, 'ruRU', 'Малявка же не злоупотребляет добротой Т\'паартоса, да?', '', 28153),
(143781, 'ruRU', 'Т\'паартос все еще немного боится змей.', '', 28153),
(143780, 'ruRU', 'Т\'паартос – озаренный! Т\'паартос гордится.', '', 28153),
(143779, 'ruRU', 'Т\'паартос всегда будет рад тебя видеть.', '', 28153),
(143778, 'ruRU', 'Т\'паартос возвращается к работе.', '', 28153),
(143777, 'ruRU', 'У Т\'паартоса много дел.', '', 28153),
(143776, 'ruRU', 'Т\'паартос будет ждать новой встречи.', '', 28153),
(143775, 'ruRU', 'Т\'паартос.', '', 28153),
(143774, 'ruRU', 'Торопись, $n. От этого зависит множество жизней.', '', 28153),
(143773, 'ruRU', 'Т\'паартос готов!', '', 28153),
(143772, 'ruRU', 'Да хранит тебя Свет.', '', 28153),
(143771, 'ruRU', 'Опасность? Т\'паартос презирает опасность!', '', 28153),
(143770, 'ruRU', 'Малявке нужен Т\'паартос?', '', 28153),
(143769, 'ruRU', 'Т\'паартос приветствует малявку.', '', 28153),
(143768, 'ruRU', 'Т\'паартос?', '', 28153),
(143767, 'ruRU', 'Т\'паартос!', '', 28153),
(143766, 'ruRU', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s начинает использовать заклинание |cFFFF0000|Hspell:259610|h[Кровавый апокалипсис]|h|r! Скорее в укрытие!', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s начинает использовать заклинание |cFFFF0000|Hspell:259610|h[Кровавый апокалипсис]|h|r! Скорее в укрытие!', 28153),
(143765, 'ruRU', '', 'Страдайте! Ваши муки питают хозяина!', 28153),
(143764, 'ruRU', 'Джайна? Я зову ее \"Раздражайна\". Модера? Я зову ее... Послушай, даже мое остроумие может иссякнуть.', '', 28153),
(143763, 'ruRU', 'Кадгар? Я зову его \"Гад-гар\". Разве я не прав?', '', 28153),
(143762, 'ruRU', 'Из-за леса, из-за гор показался Кирин-Тор... Продолжать?', '', 28153),
(143761, 'ruRU', 'Если бы вы все просто выполняли мои приказы, а не пытались что-то придумывать, Азерот вздохнул бы с облегчением.', '', 28153),
(143760, 'ruRU', 'Горе тем, кто противостоит нам.', '', 28153),
(143759, 'ruRU', 'За Кель\'Талас.', '', 28153),
(143758, 'ruRU', 'Мы многое преодолели.', '', 28153),
(143757, 'ruRU', 'Мы строим будущее на основе традиций.', '', 28153),
(143756, 'ruRU', 'Занимайся своими делами.', '', 28153),
(143755, 'ruRU', 'Не позволяй чужакам вмешиваться в дела твоего народа.', '', 28153),
(143754, 'ruRU', 'Уважай наши традиции.', '', 28153),
(143753, 'ruRU', 'Вечное солнце не оставит нас.', '', 28153),
(143752, 'ruRU', 'Чего ты хочешь?', '', 28153),
(143751, 'ruRU', 'Я служу Луносвету.', '', 28153),
(143750, 'ruRU', 'Я очень занят.', '', 28153),
(143749, 'ruRU', 'Не растрачивай ресурсы.', '', 28153),
(143748, 'ruRU', 'В чем дело?', '', 28153),
(143747, 'ruRU', 'Мы защитим Солнечный Колодец.', '', 28153),
(143746, 'ruRU', 'Прими это в знак благодарности.', '', 28153),
(143745, 'ruRU', '', 'Планы? Я тебя умоляю. Какие у меня могут быть планы?', 28153),
(143744, 'ruRU', '', 'Думаешь, я не замечаю, как ты посматриваешь на моих темных следопытов? Лучше следи за своими глазами... и мыслями.', 28153),
(143743, 'ruRU', '', 'Я тут понаблюдала за тобой... Кажется, пора тебя отправить к Натаносу на переподготовку.', 28153),
(143742, 'ruRU', '', 'Признай, я лучшая из сестер Ветрокрылых. А? А? А?', 28153),
(143741, 'ruRU', '', 'Кровь Азерота принадлежит Орде.', 28153),
(143740, 'ruRU', 'Я начал сомневаться в том, что подобное создание существует!', '', 28153),
(143739, 'ruRU', '', 'Мы возьмем то, что принадлежит нам по праву.', 28153),
(143738, 'ruRU', '', 'Рано или поздно все покорятся Орде.', 28153),
(143737, 'ruRU', '', 'Армия Отрекшихся будет расти... Уж я об этом позабочусь.', 28153),
(143736, 'ruRU', '', 'Мы поставим Альянс на колени.', 28153),
(143735, 'ruRU', '', 'Служи Орде. Служи мне.', 28153),
(143734, 'ruRU', 'Он прекрасен!', '', 28153),
(143733, 'ruRU', '', 'Уходи. У меня много дел.', 28153),
(143732, 'ruRU', '', 'Служи мне преданно, и тебя ждет награда.', 28153),
(143731, 'ruRU', '', 'Орду ждет новое будущее.', 28153),
(143730, 'ruRU', '', 'Все это – только начало.', 28153),
(143729, 'ruRU', '', 'Приветствую.', 28153),
(143728, 'ruRU', '', 'Подойди ближе.', 28153),
(143727, 'ruRU', '', 'Надеюсь, это заслуживает моего внимания.', 28153),
(143726, 'ruRU', '', 'Ты разговариваешь с вождем Орды.', 28153),
(143725, 'ruRU', '', 'Стихиям Зандалара выпала незавидная доля. Нам нужно защитить их от темных шаманов, что пытаются использовать их силу в своих личных целях.', 28153),
(143724, 'ruRU', 'Меня зовут Бертольд, и я схожу с ума по лошадям.\n\nПо слухам, к западу отсюда, на какой-то горе водится величественное конеподобное создание. Я устроился здесь на работу, чтобы увидеть его.\n\nО, я бы отдал что угодно ради такого зрелища...', '', 28153),
(143721, 'ruRU', 'Принято. Дальнейшие размышления о необходимости передислоцирования не требуются. Отправляюсь в область \"Зул\'Назман\".', '', 28153),
(143720, 'ruRU', '', 'Хезрел, тролли крови собираются в Зул\'Назмане. Если хочешь нам помочь, тебе туда.', 28153),
(143719, 'ruRU', 'Угостишь меня, а?\n\nМой народ спас весь мир, а вы сбежали и спрятались, как трусы, в своем тумане.\n\nЯ имею право выпить за твой счет.', '', 28153),
(143718, 'ruRU', 'Системы хранителя Хезрела работают на 50%% мощности. Нужно экономить энергию для устранения троллей крови.', '', 28153),
(143717, 'ruRU', 'Раньше я готовил здесь коктейли. Королевская семья устраивала приемы для аристократов со всего мира, а я услаждал их вкус своими творениями.\n\nТеперь же это логово грязных чужаков и их уродливых друзей. Какой позор.', '', 28153),
(143716, 'ruRU', 'Я уважаю некоторые гоблинские картели. Они сильны и блюдут нейтралитет, они готовы на все. Как и зандалары... только хуже, конечно.\n\nНо вы, из картеля Трюмных Вод, просто позорище. Подстилка для эльфов и Орды. Продажные твари.', '', 28153),
(143715, 'ruRU', 'Ощути мою силу!', '', 28153),
(143714, 'ruRU', 'Мне нравится, как действует эта ваша Орда, $p. Сильные вожди. Объединяющая цель. Надежные поставки продовольствия.\n\nНовобранцев набираете?', '', 28153),
(143713, 'ruRU', 'Я готов к поискам новых союзников.', 'Я готова к поискам новых союзников.', 28153),
(143712, 'ruRU', '', 'Наконец-то этот бессмысленный обмен любезностями между Ордой и Альянсом прекратится.$b$bПробил час войны.', 28153),
(143711, 'ruRU', 'Меня всегда удивляло, что племя Черного Копья вступило в Орду. С другой стороны, сами по себе вы всегда были слишком слабы.\n\nКак там Вол\'джин?', '', 28153),
(143710, 'ruRU', 'Слышь, эльфятина. Я больше не владелец этого бара, так что мне не надо притворяться, что ты мне нравишься.\n\nОтвали от меня, эльфийское отродье.', '', 28153),
(143709, 'ruRU', 'Тебя явно мучает жажда. Выпей. Останься, поболтай немного.\n\nЗулдазар стоит здесь с древних времен. В одночасье он не исчезнет.', '', 28153),
(143708, 'ruRU', 'Я слышал, кто-то из вас отправляется в Назмир. Сваливать надо с такого задания. Вот уже сотни лет из этих болот ничего хорошего не вылезало.', '', 28153),
(143707, 'ruRU', 'Я слышал, в песках Вол\'дуна сейчас беспокойнее, чем обычно. Будь осторожнее, если отправишься туда.', '', 28153),
(143706, 'ruRU', 'Мой народ основал цивилизацию на заре времен и с той поры всех на своем хребте тащит.\n\nСкажи мне, $p, что твой народ сотворил такого, что достойно воспоминаний?\n\nЧто-то я не припомню.', '', 28153),
(143705, 'ruRU', '(Прыгнуть на плечо Хезрела, чтобы вернуться в Мрачную низину.)', '(Прыгнуть на плечо Хезрела, чтобы вернуться в Мрачную низину.)', 28153),
(143704, 'ruRU', 'Попытка ремонта камеры Г\'ууна не привела к требуемым результатам. Чтобы предотвратить его освобождение, требуется помешать существам из группировки \"тролли крови\" уничтожить Зулдазар.\n\nЗдание окружают тролли крови. $n и принцесса Таланджи будут в безопасности благодаря хранителю титанов Хезрелу.\n\nПрыгай на плечи. Не высовывайся.', '', 28153),
(143703, 'ruRU', 'Какая гадость. Мерзость. Ты пахнешь хуже тролля крови.\n\nБудь это по-прежнему мой бар, я вышвырнул бы тебя вместе с мусором.', '', 28153),
(143702, 'ruRU', 'Что нового за стенами города?', '', 28153),
(143700, 'ruRU', 'Галливикс руководит операцией в Силитусе. Немедленно отправляйся туда. Если повстречаешь шпионов Альянса – разберись с ними.', '', 28153),
(143699, 'ruRU', 'Наши агенты основали временную базу в Силитусе. Отправляйся туда, но будь начеку: Орда может напасть в любой момент.', '', 28153),
(143698, 'ruRU', 'Вы, орки, пить умеете. Это да.\n\nНо передай своим заносчивым эльфийским друзьям – пусть держатся отсюда подальше.', '', 28153),
(143697, 'ruRU', 'Аллерия и Туралион? Без вариантов. Я, конечно, ничего против них не имею, но... Нельзя ли сменить тему?', '', 28153),
(143696, 'ruRU', 'Я понимаю, почему ты не любишь эльфов. Мы и сами друг друга не очень жалуем. По крайней мере, одна половина эльфов – другую.', '', 28153),
(143695, 'ruRU', 'С каждым днем я становлюсь все лиловей и лиловей... А ведь это даже не мой любимый цвет.', '', 28153),
(143694, 'ruRU', 'Зачем быть высшим эльфом, когда можно изображать страдание и тяжкие думы?', '', 28153),
(143693, 'ruRU', 'Сохраняй внимание и контроль.', '', 28153),
(143692, 'ruRU', 'Не слушай голоса.', '', 28153),
(143691, 'ruRU', 'Не упускай возможностей.', '', 28153),
(143690, 'ruRU', 'Да хранят тебя тени.', '', 28153),
(143689, 'ruRU', 'Мы служим Альянсу.', '', 28153),
(143688, 'ruRU', 'Путь Света – не единственный путь.', '', 28153),
(143687, 'ruRU', 'Рен\'дорай заслужат свое место в рядах Альянса.', '', 28153),
(143686, 'ruRU', 'Я многому могу тебя научить.', '', 28153),
(143685, 'ruRU', 'Открой свой разум.', '', 28153),
(143684, 'ruRU', 'Для нас открыты все пути.', '', 28153),
(143683, 'ruRU', 'Мы используем силу, а не боимся ее.', '', 28153),
(143682, 'ruRU', 'Тени служат нам.', '', 28153),
(143681, 'ruRU', 'Бал-а даш, маланоре.', '', 28153),
(143680, 'ruRU', 'Приветствую тебя.', '', 28153),
(143679, 'ruRU', 'Я всегда носил повязку на одном и том же глазу! Я бы ни за что не перепутал.', '', 28153),
(143678, 'ruRU', 'С Сильваной непросто сработаться... После смерти характер у нее совсем испортился. Только ей не говори.', '', 28153),
(143677, 'ruRU', 'Да будь он хоть трижды защитник королевы, я одолею Натаноса одной левой.', '', 28153),
(143676, 'ruRU', 'Секрет моих волос? Правильное питание и постоянный уход.', '', 28153),
(143675, 'ruRU', 'Ни один король не будет править Луносветом.', '', 28153),
(143674, 'ruRU', 'Нас ждет новый расцвет.', '', 28153),
(143673, 'ruRU', 'Аль диель шала.', '', 28153),
(143672, 'ruRU', 'Наша сила – в Орде.', '', 28153),
(143671, 'ruRU', 'Все ради Кель\'Таласа.', '', 28153),
(143670, 'ruRU', 'Да хранит тебя свет Солнечного Колодца!', '', 28153),
(143669, 'ruRU', 'Луносвет возродится.', '', 28153),
(143668, 'ruRU', 'Красота лесов Вечной Песни не увянет.', '', 28153),
(143667, 'ruRU', 'Вечное солнце не оставит нас.', '', 28153),
(143666, 'ruRU', 'Восстановление Кель\'Таласа продолжается.', '', 28153),
(143665, 'ruRU', 'Мы принесли много жертв.', '', 28153),
(143664, 'ruRU', 'Носить титул лорда-регента – честь для меня.', '', 28153),
(143663, 'ruRU', 'Бал-а даш, маланоре.', '', 28153),
(143662, 'ruRU', 'Луносвет приветствует тебя.', '', 28153),
(143651, 'ruRU', 'Кажется, я поймал большую рыбу!', '', 28153),
(143650, 'ruRU', 'ВРЕМЕННАЯ СЦЕНА – Хезрел рассказывает, что Г\'уун – древний бог, об экспериментах и о том, что тролли крови хотят уничтожить Зулдазар, чтобы освободить Г\'ууна. В настоящее время восстановить систему сдерживания невозможно, необходимо защитить Зулдазар. Появляется Атина, матриарх троллей крови, наносит тяжелые повреждения Хезрелу и готовится нанести сокрушительный удар.', 'ВРЕМЕННАЯ СЦЕНА - Хезрел рассказывает о древнем боге Г\'ууне, об экспериментах и о том, что тролли крови хотят уничтожить Зулдазар, чтобы освободить Г\'ууна. В настоящее время восстановить систему сдерживания невозможно, необходимо защитить Зулдазар. Появляется Атина, матриарх троллей крови, наносит тяжелые повреждения Хезрелу и готовится нанести сокрушительный удар.', 28153),
(143649, 'ruRU', '', '$R, убирайся! Его голос принадлежит мне!', 28153),
(143648, 'ruRU', '', 'Здесь... столько... силы...', 28153),
(143647, 'ruRU', '', 'Не забывай, Умбрий: загадки древности порой таят в себе опасность.', 28153),
(143646, 'ruRU', 'Взять хотя бы этот куб: древнее устройство, созданное, вероятно, еще до появления жизни на Азероте. Мы тщетно пытаемся подобрать к нему ключ.', '', 28153),
(143645, 'ruRU', 'Весьма вероятно! Мы тоже считаем, что силы Бездны можно использовать во благо. И хотя мы уже многому научились, впереди еще немало загадок.', '', 28153),
(143644, 'ruRU', '', 'В другой раз. Мы искали тебя, так как узнали о вашем изгнании из Луносвета. Мне кажется, мы могли бы найти общий язык.', 28153),
(143643, 'ruRU', 'До нас дошли слухи о случившемся на Аргусе. Разумеется, нам было бы любопытно узнать о том, что произошло между тобой и темной наару.', '', 28153),
(143642, 'ruRU', 'Аллерия?! Но как... Хм, какая неожиданная честь!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143641, 'ruRU', '', 'Магистр Умбрий! Я Аллерия Ветрокрылая.', 28153),
(143640, 'ruRU', '', 'Смотри! Это должен быть Умбрий.', 28153),
(143639, 'ruRU', '', 'По этим заметкам я смогу вновь открыть проход в мир, о котором он пишет. Одну минутку...', 28153),
(143638, 'ruRU', '', '<Landing from jump: Total 3>', 28153),
(143637, 'ruRU', 'Дратир полагал, что там находится древний объект невообразимой силы. Может быть, именно он позволит нам получить власть над тенями.', '', 28153),
(143636, 'ruRU', 'Согласно его заметкам, этот мир располагается в разрыве полотна реальности. Дратиру так и не удалось его отыскать... Но мы оказались удачливее.', '', 28153),
(143635, 'ruRU', 'В погоне за могуществом Дратир пытался найти фрагменты древнего мира, что находится на границе Бездны.', '', 28153),
(143634, 'ruRU', '<Landing from jump: Total 3>', '', 28153),
(143633, 'ruRU', '', 'Идем. Нужно добраться до башни Утренней Звезды.', 28153),
(143632, 'ruRU', 'И все же его знания могут принести пользу. Дратир в основном проводил свои исследования в башне Утренней Звезды. Туда и лежит наш путь.', '', 28153),
(143631, 'ruRU', 'Именно предательство Дратира позволило Артасу осквернить Солнечный Колодец и погубить наше королевство. Я впервые склонен согласиться с Ромматом.', '', 28153),
(143630, 'ruRU', 'Полагаю, мы не первые, кто пытается обуздать силу Бездны. Я нашел заметки того, чье имя навеки проклято... Дар\'Кхана Дратира.', '', 28153),
(143629, 'ruRU', '<Landing from jump: Total 3>', '', 28153),
(143628, 'ruRU', '', 'Похоже, это чьи-то заметки.', 28153),
(143627, 'ruRU', '', '<Landing from jump: Total 3>', 28153),
(143626, 'ruRU', 'К сожалению, мы топчемся на месте. Может быть, знания, накопленные в поместье Андилиен, помогут нам продвинуться дальше.', '', 28153),
(143625, 'ruRU', 'Верховный магистр должен понять, что эта сила поможет нам отстоять Луносвет. Син\'дорай больше никогда не покорятся врагам!', '', 28153),
(143624, 'ruRU', 'Эксперименты с Бездной приносят результаты. Я уверен, что мы на пороге прорыва... несмотря на протесты Роммата.', '', 28153),
(143623, 'ruRU', '<Landing from jump: Total 3>', '', 28153),
(143622, 'ruRU', '', '<Landing from jump: Total 3>', 28153),
(143621, 'ruRU', '<Distressed cry: Total 3>', '', 28153),
(143620, 'ruRU', '<Landing from jump: Total 3>', '', 28153),
(143619, 'ruRU', 'Хезрел, за работу. Надо найти способ избавиться от порчи Древнего бога в Назмире.', 'Хезрел, за работу. Надо найти способ избавиться от порчи Древнего бога в Назмире.', 28153),
(143618, 'ruRU', 'Посмотрим, будет ли клевать!', '', 28153),
(143617, 'ruRU', '', '<Landing from jump: Total 3>', 28153),
(143616, 'ruRU', '', 'Раньше окрестные леса приносили мне и моим сестрам радость, а теперь я чувствую лишь боль.', 28153),
(143615, 'ruRU', 'Но мы докажем, что это возможно.', '', 28153),
(143614, 'ruRU', 'Мы еще нескоро привыкнем к нашим новым обличьям. Ждем твоего возвращения, Аллерия. И... прими нашу благодарность, $p.', '', 28153),
(143613, 'ruRU', '', 'А я обязуюсь помогать вам. Мы сообщим обо всем верховному королю Ринну, а затем я займусь вашим обучением.', 28153),
(143612, 'ruRU', 'Луносвет давно отвернулся от нас. Сегодня мы переродились и готовы избрать новый путь. С этого дня мы будем верны Альянсу.', '', 28153),
(143611, 'ruRU', '', 'Эта сила велика, и я чувствую ее в каждом из вас. Альянсу нужны такие союзники.', 28153),
(143610, 'ruRU', 'Моя гордыня чуть не погубила нас всех. Я играл с силой, которую не мог понять... Научи нас управлять ей – и мы пойдем за тобой.', '', 28153),
(143609, 'ruRU', '', 'Я распорядилась построить посольство в Оргриммаре. Оно позволит нам привлечь новых союзников. Встретимся там.', 28153),
(143608, 'ruRU', '', 'Жертвы в борьбе с Легионом ослабили Орду. Враги хотят воспользоваться моментом и отнять то, что принадлежит нам. Мы не можем этого допустить.', 28153),
(143607, 'ruRU', '', 'Ты уже знаешь о нашей операции в Силитусе, $p. Альянс явно делает все возможное, чтобы вставить нам палки в колеса.', 28153),
(143606, 'ruRU', 'Альянсу нужно найти новых cоюзников. В этих поисках нам поможет посольство, которое мы основали в Штормграде. Я буду ждать тебя там.', '', 28153),
(143605, 'ruRU', 'Орда пойдет на все, чтобы заполучить жизненную силу Азерота. Боюсь, из-за потерь в борьбе с Легионом мы сейчас не в состоянии дать врагам отпор.', '', 28153),
(143604, 'ruRU', 'Тебе довелось повидать разрушения в Силитусе, $p. Ты знаешь, что стоит на кону.', '', 28153),
(143603, 'ruRU', 'Встретимся у крепости Громмаш. И смотри не болтай... Или последствия не заставят ждать.', '', 28153),
(143602, 'ruRU', 'Мы получили крайне важное для Орды донесение. Нельзя допустить, чтобы нас опередили враги.', '', 28153),
(143601, 'ruRU', '$p! Темная Госпожа велела нам встретиться в Оргриммаре.', '', 28153),
(143600, 'ruRU', 'Встретимся в Покое Льва. Помни: об этой встрече не должен узнать никто.', '', 28153),
(143599, 'ruRU', 'Мы располагаем некой... конфиденциальной информацией, которой хотим с тобой поделиться.', '', 28153),
(143598, 'ruRU', '$p, король Ринн желает, чтобы мы встретились в Штормграде.', '', 28153),
(143597, 'ruRU', 'Еще я привел чужака, желающего говорить с тобой, великий лоа.', '', 28153),
(143596, 'ruRU', '', 'Ночнорожденные – мудрый и могущественный народ. Ваши древние знания нам обязательно пригодятся.', 28153),
(143595, 'ruRU', '', 'Впрочем, довольно любезностей. Тебя ждут подвиги. И помни, куда бы ни привела дорога... сражайся за Орду!', 28153),
(143594, 'ruRU', '', 'Я буду следить за твоими успехами. Я рассчитываю на тебя... и я щедро вознаграждаю тех, кто верно служит мне.', 28153),
(143593, 'ruRU', '', 'У Орды много соперников. Кое-кто называет нас врагами, а кое-кто – изгоями... но наша сила – в единстве и в борьбе против тех, кто посягает на нашу свободу.', 28153),
(143592, 'ruRU', '', 'Таурены Крутогорья сильны и бесстрашны. Нам нужны именно такие союзники.', 28153),
(143591, 'ruRU', '', 'А, вот и ты, $p. Если донесения моих советников не врут, тебя ждет большое будущее.', 28153),
(143590, 'ruRU', 'Береги себя, $p. Да пребудет с тобой Свет!', '', 28153),
(143589, 'ruRU', 'Эльфы Бездны лишь недавно вступили в наши ряды, но Аллерия Ветрокрылая – одна из наших величайших героинь. Под ее руководством ты принесешь нам пользу.', '', 28153),
(143588, 'ruRU', 'Мы освободим от вас эту землю!', '', 28153),
(143587, 'ruRU', 'Береги себя, $p. Пусть ты и предпочитаешь оставаться в тенях, ты несешь в себе свет.', '', 28153),
(143586, 'ruRU', 'Я буду следить за твоими успехами. Думаю, мы скоро встретимся вновь.', '', 28153),
(143585, 'ruRU', 'Для Азерота наступают суровые дни. Тебя ждет множество испытаний... множество битв, но ты никогда не будешь сражаться в одиночку, ведь за твоей спиной – весь Альянс.', '', 28153),
(143584, 'ruRU', 'Озаренные лишь недавно вступили в наши ряды, но я хорошо знаю дренеев и уверен, что ты следуешь идеалам верности и отваги Армии Света.', '', 28153),
(143583, 'ruRU', 'Добро пожаловать, $p. Я король Андуин Ринн. Я хотел лично поприветствовать нового члена Альянса.', '', 28153),
(143582, 'ruRU', 'Мне нужно лечение!', '', 28153),
(143581, 'ruRU', 'Постройте себе другую лесопилку!', '', 28153),
(143580, 'ruRU', 'В какую, однако, любопытную глушь нас завели интересы Орды.\n\nНадеюсь, обычно моя новая фракция подбирает более изысканные и чистые апартаменты для своих слуг?', '', 28153),
(143579, 'ruRU', 'Прошу меня извинить, $p.\n\nЯ бы с радостью поболтал, но, боюсь, мне сейчас станет дурно.\n\nВино тут не пробуй.', '', 28153),
(143578, 'ruRU', '<Винодел Теснала буравит бармена взглядом, медленно выливая вино на землю.>', '', 28153),
(143577, 'ruRU', 'Обязательно попробуй местное вино.\n\nНастоятельно рекомендую, у него непередаваемо гадкий вкус.\n\nКогда-нибудь барды сложат песни об этом кошмарном букете.\n\nВоистину, достижение: алкоголь самой низшей категории, убивающий любое веселье.', '', 28153),
(143576, 'ruRU', 'Я готов признать талант зандаларов в строительстве огромных уродливых зданий.\n\nВино у них получается заметно хуже.', '', 28153),
(143575, 'ruRU', 'Если не умеешь делать хорошее вино, лучше вообще его не делай.', '', 28153),
(143574, 'ruRU', 'Купи мне еще один бокал, я хочу снова выплюнуть эту гадость на землю.', '', 28153),
(143573, 'ruRU', 'Эти помои здесь называют вином? Теперь понятно, почему тролли бегут из этого города.', '', 28153),
(143572, 'ruRU', 'Мы свободны! Быстрее, валим отсюда!', 'Мы свободны! Быстрее, валим отсюда!', 28153),
(143571, 'ruRU', 'Эти деревянные чудовища – порождения ночных кошмаров!', '', 28153),
(143569, 'ruRU', 'Потребую... надбавку за вредность.', 'Потребую... надбавку за вредность.', 28153),
(143568, 'ruRU', '', 'Здесь все разрушено... Но мне знакомо это место.', 28153),
(143567, 'ruRU', 'За работу, ленивые мешки с костями!', 'За работу, ленивые мешки с костями!', 28153),
(143566, 'ruRU', 'Строение очищено. Обнаружено присутствие \"принцессы Таланджи\".', '', 28153),
(143565, 'ruRU', 'Час настал. Вперед, в Корлейн!', '', 28153),
(143562, 'ruRU', 'Слишком поздно. Г\'ууна невозможно сдержать. Все будет уничтожено. Все умрут.', '', 28153),
(143561, 'ruRU', 'Близится ваша погибель. Г\'уун обретет свободу. Азерот будет нашим.', '', 28153),
(143560, 'ruRU', 'Положи свои ценности в сейф и иди своей дорогой, $p.\n\nЯ за тобой слежу...', '', 28153),
(143559, 'ruRU', 'В Друстваре настали темные времена, но мы еще вернем себе нашу землю!', '', 28153),
(143558, 'ruRU', 'За Зандалар!', '', 28153),
(143557, 'ruRU', 'Резан, нам пора на охоту.', '', 28153),
(143556, 'ruRU', 'Да, миледи. Мы готовы выдвигаться.', '', 28153),
(143555, 'ruRU', 'Па\'ку, лоа ветров, взмывай в небо и высматривай еретиков. Узнай, что они задумали, а затем лети к храму.', '', 28153),
(143554, 'ruRU', 'Гонк, лоа охоты, веди своих приверженцев в храм Пророка. Выкурите врага оттуда и убейте всех, кого сможете.', '', 28153),
(143553, 'ruRU', 'Зандалары! Братья и сестры! Пришло время поотрубать головы предателям, присягнувшим Зулу.', '', 28153),
(143552, 'ruRU', '', 'Остальным нужно готовиться к отбытию в Корлейн. Маршал, у вас есть план нападения?', 28153),
(143551, 'ruRU', '', 'Есть, мэм!', 28153),
(143550, 'ruRU', '', 'Отнесите рецепт алхимического огня мастеру Эштону в Соколиный Холм. Он поймет, что с ним делать.', 28153),
(143549, 'ruRU', '', 'К счастью, я знаю опытного алхимика, что живет в Соколином Холме, к югу отсюда. В лесах опасно, так что добираться придется старыми горными тропами.', 28153),
(143548, 'ruRU', '', 'В книге есть рецепт алхимического огня, но среди нас нет никого, кто смог бы его воссоздать.', 28153),
(143547, 'ruRU', '', 'Чтобы навсегда покончить с ковеном, серебра недостаточно. Нужен еще и огонь.', 28153),
(143546, 'ruRU', '', 'Спасибо, сэр. Что нужно сделать, миледи?', 28153),
(143545, 'ruRU', 'Капитан... прошу прощения, инквизитор Клирдоун никогда меня не подводила. Уверен, она справится с любым заданием.', '', 28153),
(143544, 'ruRU', '', 'Кого порекомендуете, маршал?', 28153),
(143543, 'ruRU', '', 'Прежде чем мы выступим... мне понадобится человек для особого задания.', 28153),
(143542, 'ruRU', 'Невероятно, Орда так и не основала официальное подразделение телемантии! Не представляю, как ее подданные вообще путешествуют при таких стандартах безопасности. Сама мысль о случайных порталах, прорывающих дыры в реальности без надлежащих якорей...\n\nЧто ж, так или иначе, я рад предложить Орде сеть стабилизированных порталов. Пожалуйста, пользуйся на здоровье.', '', 28153),
(143540, 'ruRU', 'Народ у нас бывалый, но такого мы еще не видели.', '', 28153),
(143539, 'ruRU', '', 'Утопите их, дети мои. Докажите, что я не зря горжусь вами.', 28153),
(143537, 'ruRU', 'Бргл! Брглргл!', '', 28153),
(143536, 'ruRU', 'Мргл, мрглрлргл! Мрр-р-рг! Мрр-р-рг!!!', '', 28153),
(143531, 'ruRU', 'Открывание', 'Открывание', 28153),
(143530, 'ruRU', 'Ай молодца! Давай, залезай!', '', 28153),
(143529, 'ruRU', 'На \"Когте Резана\" что-то не так. Мы посылаем туда разведчика.', '', 28153),
(143523, 'ruRU', 'Давай сюда свое золото, мне через пять минут отчитываться о доходах!', '', 28153),
(143520, 'ruRU', 'Я готов. Замаскируй меня с помощью синтетической эссенции Г\'ууна.', 'Я готова. Замаскируй меня с помощью синтетической эссенции Г\'ууна.', 28153),
(143519, 'ruRU', 'Король Да\'ка! Он нас нашел! Помоги мне!', '', 28153),
(143518, 'ruRU', 'Вы проиграли ИМ? Какой позор! Отправляйтесь в Подгород на переподготовку. Снова придется вас всему учить...', '', 28153),
(143517, 'ruRU', 'Изящной эту победу не назовешь, но вы все же показали Альянсу, где их место. За Орду!', '', 28153),
(143516, 'ruRU', 'Мне кажется, или запахло воргеном? А, это просто псы Альянса крутятся поблизости.', '', 28153),
(143515, 'ruRU', 'Убейте всех! Вы же не хотите разочаровать вождя?', '', 28153),
(143514, 'ruRU', 'И это Альянс называет \"армией\"? Жалкое зрелище! Да они мечи едва держат!', '', 28153),
(143513, 'ruRU', 'Огонь! Никого не оставлять в живых!', '', 28153),
(143512, 'ruRU', 'Здесь даже больше азерита, чем мы думали! Я отметил нужные точки на карте!', '', 28153),
(143511, 'ruRU', 'Обнаружены новые точки выброса азерита на острове! Я отметил их на карте.', '', 28153),
(143510, 'ruRU', 'Мы почти у цели. Не мешкайте! Нам нужен азерит!', '', 28153),
(143509, 'ruRU', 'Ха! Альянс остался ни с чем! Славная работа!', '', 28153),
(143508, 'ruRU', 'Для начала неплохо, но нам нужно больше азерита!', '', 28153),
(143507, 'ruRU', 'Берите припасы, но не забывайте, за чем вас послала королева банши!', '', 28153),
(143506, 'ruRU', 'Припасы на подходе. Сделайте так, чтобы они достались вам, а не Альянсу!', '', 28153),
(143505, 'ruRU', 'Там внизу азерит! Соберите его для вождя. Если Альянс будет путаться под ногами, усейте остров трупами. За дело!', '', 28153),
(143504, 'ruRU', 'Дайте-ка я взгляну на вас. Печальное зрелище... Ни одного темного следопыта. Впрочем, и вы сойдете.', '', 28153),
(143503, 'ruRU', 'Судно Альянса на подходе! Эти псы нас выследили. Занять боевые посты!', '', 28153),
(143502, 'ruRU', 'Ваша задача предельно проста. Соберите весь азерит до последней крупицы, чтобы он не достался врагу. Надеюсь, вопросов нет?', '', 28153),
(143501, 'ruRU', 'Бойцы Орды! Мы нашли залежи азерита на каком-то чертовом острове у побережья Фераласа. Захватите его во имя Темной Госпожи!', '', 28153),
(143500, 'ruRU', 'Гоните Орду с острова! Он принадлежит нам!', '', 28153),
(143499, 'ruRU', 'Сражайтесь за короля! Сражайтесь за Альянс!', '', 28153),
(143498, 'ruRU', 'Ордынцы думают, что обставили нас. Преподайте им урок!', '', 28153),
(143497, 'ruRU', 'Огонь! Устраните лекарей!', '', 28153),
(143496, 'ruRU', 'Неплохой отряд. Конечно, еще разбойник-другой не помешал бы... но и вы сгодитесь.', '', 28153),
(143495, 'ruRU', 'Проклятье! Орда нас обошла, но клянусь Покоем Льва, в следующий раз мы победим!', '', 28153),
(143494, 'ruRU', 'Блестяще, герои! Король Ринн будет счастлив узнать о вашей победе. За Альянс!', '', 28153),
(143493, 'ruRU', 'А вот и припасы! Собирайте их!', '', 28153),
(143492, 'ruRU', 'Азерит снова выходит на поверхность! Захватите отмеченные точки!', '', 28153),
(143491, 'ruRU', 'Прекрасно! Еще немного азерита, и победа у нас в кармане!', '', 28153),
(143490, 'ruRU', 'Благодаря вам Орда не получит азерит. Превосходно!', '', 28153),
(143489, 'ruRU', 'Неплохо, герои, но нам нужно больше азерита!', '', 28153),
(143488, 'ruRU', 'Герои, мы сбросили вам припасы. Не дайте Орде до них добраться!', '', 28153),
(143487, 'ruRU', 'Мы обнаружили на острове еще несколько точек выброса азерита! Я отметил их на карте.', '', 28153),
(143486, 'ruRU', 'Герои, под нами богатые залежи азерита. Спускайтесь и соберите его столько, сколько сможете. И не щадите мародеров из Орды!', '', 28153),
(143485, 'ruRU', 'Приближается корабль Орды! Эти мерзавцы следили за нами! К бою!', '', 28153),
(143484, 'ruRU', 'Наш корабль находится прямо над центром острова. Соберите как можно больше азерита. В нем – залог нашей победы!', '', 28153),
(143483, 'ruRU', 'Герои, на острове у побережья Фераласа обнаружены залежи азерита. Нельзя допустить, чтобы до них добралась Орда.', '', 28153),
(143482, 'ruRU', '', 'Я готова, леди Лиадрин. У Окулета есть координаты вашей столицы. Я возьму с собой Силгрина и Вальтруа. Встретимся в Луносвете.', 28153),
(143481, 'ruRU', '', 'Я уверена, что ваш интерес порадует лорда-регента. Мы можем отправляться в путь?', 28153),
(143480, 'ruRU', '', 'Поэтому я признательна вам за приглашение в Луносвет. Я бы хотела узнать, найдется ли в вашей Орде место для ночнорожденных.', 28153),
(143479, 'ruRU', '', 'Альянс отгородился от мира непреодолимой стеной. Мы же больше не хотим жить в изоляции.', 28153),
(143478, 'ruRU', '', 'Она относится к син\'дорай с тем же презрением, но пока ее сородичи отсыпались в норах и прятались в лесах, именно мой народ защищал Азерот.', 28153),
(143477, 'ruRU', '', 'Похоже, \"мудрость Элуны\" затуманила разум Тиранды. Ну что ж, да будет так.', 28153),
(143476, 'ruRU', '', 'Калдорай будут сражаться, пока Легион не падет и Колодец не будет разрушен. А дальше... Элуна укажет нам путь.', 28153),
(143475, 'ruRU', '', 'Мы не будем рабами Ночного Колодца. Мы изгоним Легион из Сурамара и положим конец тирании Элисанды.', 28153),
(143474, 'ruRU', '', 'Чародейка Талисра. Я помню, на чьей стороне твой орден был в Войне древних. Откуда нам знать, что ты не предашь нас и не станешь новой Элисандой... или Азшарой?', 28153),
(143473, 'ruRU', '', 'Я думала, что мы скорее сблизимся с нашими сородичами из Калимдора, но просчиталась.', 28153),
(143472, 'ruRU', '', 'Когда я впервые услышала об Орде, мне показалось, что мы не сможем найти общий язык.', 28153),
(143471, 'ruRU', '', 'Именно такие союзники, как вы, помогли Орде одолеть Легион.', 28153),
(143470, 'ruRU', '', 'Без вашей неоценимой помощи это было бы невозможно.', 28153),
(143469, 'ruRU', '', 'А я рада, что ваш город снова свободен.', 28153),
(143468, 'ruRU', '', 'Леди Лиадрин, $p, приветствую вас. Я рада снова видеть вас в Сурамаре. Особенно в нынешних обстоятельствах.', 28153),
(143467, 'ruRU', '', 'Неудивительно, но все-таки жаль... Лоа не благословили тебя, дитя. Ты не присоединишься к нам на Террасе Избранных.', 28153),
(143466, 'ruRU', 'Тебе пришлось проделать дальний путь ради встречи со мной, дитя.$b$bУ меня есть несколько книг по истории крабов, если тебе это интересно.', '', 28153),
(143465, 'ruRU', '', 'Выносливость и гордость! Ты устоишь в бою с любым врагом, выдержишь любую грозу. Твоя сила поможет нам защищать город.', 28153),
(143464, 'ruRU', '', 'Это... очень необычно. Нам обязательно понадобится твоя сила.', 28153),
(143463, 'ruRU', '', 'Эгоизм и бесчестие... Лучше найди другой путь в жизни, дитя.', 28153),
(143462, 'ruRU', '', 'Любопытно... коварный боец, наносящий удары из тени. Внезапность – вот твое главное оружие.', 28153),
(143461, 'ruRU', '', 'Я вижу... Быстрый и наблюдательный боец, что наносит удары в нужный момент. Твое терпение будет вознаграждено.', 28153),
(143460, 'ruRU', '', 'Загляни себе в душу, дитя. Покажи мне, как ты будешь охотиться на свою жертву. Что станет твоим оружием? Сила, мудрость или что-то еще?', 28153),
(143459, 'ruRU', '', 'Стая зовет тебя. Услышь зов крови и выйди на охоту вместе со своими братьями и сестрами.', 28153),
(143458, 'ruRU', 'Ты чуешь этот запах? Здесь пахнет капустой.$b$b<Крондо наклоняется к вам и принюхивается.>$b$bНет, не от тебя... но что-то здесь точно пахнет капустой. $b$bКстати, у тебя хороший почерк? Хочешь урок каллиграфии? Веришь ли, я мастер-начертатель.', '', 28153),
(143457, 'ruRU', 'На нас напали!', 'На нас напали!', 28153),
(143456, 'ruRU', 'К оружию, братья и сестры!', 'К оружию, братья и сестры!', 28153),
(143455, 'ruRU', 'Враги среди нас!', 'Враги среди нас!', 28153),
(143454, 'ruRU', 'Чужак! К оружию!', 'Чужак! К оружию!', 28153),
(143452, 'ruRU', 'С удовольствием.', '', 28153),
(143451, 'ruRU', 'Шевелись!', '', 28153),
(143450, 'ruRU', 'Надо выполнять заказы!', '', 28153),
(143449, 'ruRU', '', 'Пожалуйста, не отвлекай ребенка.\n\nЯ проверяю, нет ли у кого-то из этих детей связи с лоа. Отмеченные благословением лоа пройдут обучение, станут жрецами и будут жить в почете и уважении.\n\nЛишенные благословения могут доказать, что вырастут сильными воинами.\n\nТе же, кто провалит оба испытания, просто никчемны. Скорее всего, они станут воришками в доках или попрошайками в Сокало.', 28153),
(143448, 'ruRU', 'Это я могу.', '', 28153),
(143447, 'ruRU', 'Лады.', '', 28153),
(143446, 'ruRU', 'Работать! Работать!', '', 28153),
(143445, 'ruRU', 'Нам нужно больше древесины!', '', 28153),
(143444, 'ruRU', 'После смерти отдохнете. А пока надо выполнять заказы!', '', 28153),
(143443, 'ruRU', 'Я поспешу в деревню, пока туман не рассеялся окончательно. Быть может, меня там не забудут.', '', 28153),
(143442, 'ruRU', 'Вряд ли я смогу вернуться к прежней жизни. Стать глупой обезьяной... после всего, что я увидел и почувствовал...', '', 28153),
(143441, 'ruRU', 'Да\'ка был прав. Я уже чувствую, как мой разум угасает.', '', 28153),
(143440, 'ruRU', 'Привет! Хочешь купить пару свитков?$b$bИли, может, экзотические чернила, сделанные из самых редких трав?', '', 28153),
(143439, 'ruRU', 'Правда, мозг у гоблина – меньше наперстка. Так что пришибите еще сотенку-другую; может, тогда до них дойдет.', '', 28153),
(143438, 'ruRU', 'Давно пора было показать гоблинам, что бывает, когда идешь против клана Черного Железа!', '', 28153),
(143437, 'ruRU', 'Ломайте их машины! Крушите механизмы! Давите зеленую погань без сожаления!', '', 28153),
(143436, 'ruRU', 'Чертовы гоблины портят азерит в промышленных масштабах! Хватит это терпеть!', '', 28153),
(143435, 'ruRU', 'Сталебой почти у нас в руках. Объясните этим зеленым рожам, что нельзя воровать у клана Черного Железа!', '', 28153),
(143434, 'ruRU', 'Кто там? Кто остановил туман? Король Да\'ка убьет тебя!', '', 28153),
(143433, 'ruRU', 'За Орду!', 'За Орду!', 28153),
(143432, 'ruRU', 'Малютка Тика смотрит на свиней голодными глазами.', '', 28153),
(143431, 'ruRU', 'Малютка Тика игриво ерзает.', '', 28153),
(143430, 'ruRU', '', 'Кто хороший маленький ящер? Кто грызет, кто кусает? Ты, мой хороший!', 28153),
(143429, 'ruRU', '', 'О, как я рада тебя видеть, малютка! $n... Спасибо тебе.', 28153),
(143428, 'ruRU', '', 'Это Тика?!', 28153),
(143427, 'ruRU', 'Малютка Тика издает довольную трель.', '', 28153),
(143426, 'ruRU', '', 'За мной придут... другие...', 28153),
(143425, 'ruRU', '', 'Империя Зандалари клонится к закату. Приходит время отступников!', 28153),
(143424, 'ruRU', 'Тебя за это повесят и четвертуют!', 'Тебя за это повесят и четвертуют!', 28153),
(143423, 'ruRU', 'Малютка Тика поднимает мордочку и издает тоскливый крик.', '', 28153),
(143422, 'ruRU', 'Ты склонишься перед королевой, чернь!', 'Ты склонишься перед королевой, чернь!', 28153),
(143421, 'ruRU', 'Она заберет... и тебя...', 'Она заберет... и тебя...', 28153),
(143420, 'ruRU', 'Дом Штормсонгов будет править этой землей!', 'Дом Штормсонгов будет править этой землей!', 28153),
(143419, 'ruRU', '', 'Спасибо за помощь! $n, приготовься отправиться в пещеру Мрачнохвоста, чтобы помочь Бен\'джину.', 28153),
(143418, 'ruRU', '', 'Я могла бы сделать устройство, анализирующее мозговую активность брутозавров. Просто в голову пришло.', 28153),
(143417, 'ruRU', '', 'Наука – вот единственный ответ, Джангалар. Я уважаю твою силу, но пляски с бубном никак не заменят агрессивную, но логичную алхимию.', 28153),
(143416, 'ruRU', 'Мы покажем слабым людям силу Орды!', '', 28153),
(143415, 'ruRU', 'Эти людишки должны бояться еще до того, как наши клинки вонзятся в их плоть!', '', 28153),
(143414, 'ruRU', 'За Орду!', '', 28153),
(143413, 'ruRU', 'Я вернусь в Зулдазар... не беспокойся, доберусь сам. Зайди ко мне, когда будешь в городе!', '', 28153),
(143412, 'ruRU', 'Подожди, Джин\'Тики. Возьми ящера. Кажется, ты... все равно нравишься ему больше меня.', '', 28153),
(143411, 'ruRU', 'Смотрите в оба! Я не хочу, чтобы вокруг нашей лесопилки шныряли людишки!', '', 28153),
(143410, 'ruRU', 'Поднажмем!', '', 28153),
(143409, 'ruRU', 'Кажется, здесь мы свое дело сделали. Пора мне отправиться в Вол\'дун и ответить за свои преступления.', '', 28153),
(143408, 'ruRU', 'Если я увижу, как кто-то спит на работе, лично скормлю волкам!', '', 28153),
(143407, 'ruRU', 'Не останавливайтесь! Нужно больше ресурсов!', '', 28153),
(143404, 'ruRU', 'Грядет... погибель...', 'Грядет... погибель...', 28153),
(143403, 'ruRU', 'Как?.. Невозможно...', 'Как?.. Невозможно...', 28153),
(143402, 'ruRU', '', 'Собирай ящеров и отправляйся в город. Я принесу тебе корзину змеиных голов, когда мы закончим!', 28153),
(143401, 'ruRU', 'Твой путь лежит в око бури...', 'Твой путь лежит в око бури...', 28153),
(143400, 'ruRU', 'Вы все... падете...', 'Вы все... падете...', 28153),
(143399, 'ruRU', 'Вот. Здесь туман поднимается из недр земли.', '', 28153),
(143398, 'ruRU', 'Мой дух... устремился к морю...', 'Мой дух... устремился к морю...', 28153),
(143397, 'ruRU', 'Волны... примут... меня...', 'Волны... примут... меня...', 28153),
(143396, 'ruRU', 'Они убили нашего вождя! Деревни больше нет!', '', 28153),
(143395, 'ruRU', 'Где-то там находится главная отдушина. Скорее!', '', 28153),
(143394, 'ruRU', 'Я вернусь... в пучину...', 'Я вернусь... в пучину...', 28153),
(143391, 'ruRU', 'Даже прилив... отступает...', 'Даже прилив... отступает...', 28153),
(143390, 'ruRU', 'Ее мощь течет по моим жилам!', 'Ее мощь течет по моим жилам!', 28153),
(143389, 'ruRU', 'Прими свою смерть!', 'Прими свою смерть!', 28153),
(143388, 'ruRU', 'Тебе не вырваться из пут судьбы!', 'Тебе не вырваться из пут судьбы!', 28153),
(143387, 'ruRU', 'Я оставлю от тебя безжизненную оболочку!', 'Я оставлю от тебя безжизненную оболочку!', 28153),
(143386, 'ruRU', 'Твой свет угаснет на дне морском!', 'Твой свет угаснет на дне морском!', 28153),
(143385, 'ruRU', 'Никто не сдержит бескрайний прилив!', 'Никто не сдержит бескрайний прилив!', 28153),
(143384, 'ruRU', 'Услышь зов морских глубин!', 'Услышь зов морских глубин!', 28153),
(143383, 'ruRU', 'Ты утонешь в пучине!', 'Ты утонешь в пучине!', 28153),
(143382, 'ruRU', 'Король Да\'ка... пал в бою.', '', 28153),
(143381, 'ruRU', '', 'Но... я должна была стать... великой....', 28153),
(143380, 'ruRU', 'Злобное создание! Твоя жизнь мимолетна как пламя свечи, и ее так же легко погасить!', '', 28153),
(143379, 'ruRU', '', 'Сила с тобой, но ты склонишься перед ковеном, как и все остальные!', 28153),
(143378, 'ruRU', '', 'Вот только твое открытие умрет вместе с тобой. Слуги, в атаку!', 28153),
(143377, 'ruRU', '', 'Тебе удалось найти нас. Думаешь, тебе повезло?', 28153),
(143376, 'ruRU', 'Ха! Зачем нужен разум, если не для того чтобы добиваться власти? Я стану королем Зандалара. И ты увидишь это, если доживешь!', '', 28153),
(143375, 'ruRU', 'Тебя надо остановить, Да\'ка. Мы обрели разум случайно – и не затем, чтобы начать войну!', '', 28153),
(143374, 'ruRU', 'Тсунга... ты привел низшее существо в наши священные туманы. Зачем ты здесь?', '', 28153),
(143373, 'ruRU', 'Что тут происходит?', 'Что тут происходит?', 28153),
(143372, 'ruRU', 'Я видел истину... в пучине...', 'Я видела истину... в пучине...', 28153),
(143371, 'ruRU', 'Моя кровь... соленая, как море...', 'Моя кровь... соленая, как море...', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143370, 'ruRU', 'Иди. Источник тумана в этой пещере. Не знаю, где скрывается сам король Да\'ка. Скорее!', '', 28153),
(143369, 'ruRU', 'Здесь присутствует могучая магия крови. Не надо быть знахарем, чтобы это почувствовать... она повсюду.', '', 28153),
(143368, 'ruRU', '', 'О... что ты здесь делаешь?\n\nЯ могу тебе чем-то помочь?', 28153),
(143367, 'ruRU', 'Кого убить?', '', 28153),
(143366, 'ruRU', 'Таз\'динго!', '', 28153),
(143365, 'ruRU', 'За Орду!', '', 28153),
(143364, 'ruRU', 'Пора убивать!', '', 28153),
(143363, 'ruRU', 'Убивать легко.', '', 28153),
(143362, 'ruRU', 'Пощады не будет!', '', 28153),
(143361, 'ruRU', 'Голову с плеч!', '', 28153),
(143360, 'ruRU', 'Во славу Орды!', '', 28153),
(143359, 'ruRU', '', 'Во славу Орды!', 28153),
(143358, 'ruRU', '', 'Голову с плеч!', 28153),
(143357, 'ruRU', '', 'Пощады не будет!', 28153),
(143356, 'ruRU', 'Мы никогда... не остановимся...', 'Мы не дождемся... покоя...', 28153),
(143355, 'ruRU', 'Моя смерть... ничего не изменит...', 'Моя смерть... ничего не изменит...', 28153),
(143354, 'ruRU', 'Мы уже... победили...', 'Мы уже... победили...', 28153),
(143353, 'ruRU', '', 'Убивать легко.', 28153),
(143352, 'ruRU', 'Я просто... выполнял приказ...', 'Я просто... выполняла приказ...', 28153),
(143351, 'ruRU', 'Жрецы моря... защитите...', 'Жрецы моря... защитите...', 28153),
(143350, 'ruRU', 'Жизнь... за море...', 'Жизнь... за море...', 28153),
(143349, 'ruRU', 'Море поглотит Кул-Тирас!', 'Море поглотит Кул-Тирас!', 28153),
(143348, 'ruRU', 'Ты смеешь идти против дома Штормсонгов?!', 'Ты смеешь идти против дома Штормсонгов?!', 28153),
(143347, 'ruRU', 'Бороться с нами – как бороться с морем!', 'Бороться с нами – как бороться с морем!', 28153),
(143346, 'ruRU', 'Все, кто пойдет против нас, сдохнут!', 'Все, кто пойдет против нас, сдохнут!', 28153),
(143345, 'ruRU', 'Наш флот раздавит вас!', 'Наш флот раздавит вас!', 28153),
(143344, 'ruRU', '', 'Пора убивать!', 28153),
(143343, 'ruRU', '', 'Иди сюда, сестренка!', 28153),
(143342, 'ruRU', 'Кул-Тирас без нас загнется!', 'Кул-Тирас без нас загнется!', 28153),
(143341, 'ruRU', '', 'Иди сюда, братишка!', 28153),
(143340, 'ruRU', 'Эта долина принадлежит нам, трюмная ты крыса!', 'Эта долина принадлежит нам, трюмная ты крыса!', 28153),
(143339, 'ruRU', 'За лорда Штормсонга!', 'За лорда Штормсонга!', 28153),
(143338, 'ruRU', '', 'Всюду мертвые ящеры... Я растила их с тех пор, как они вылупились... Словно мои дети умерли у меня на глазах.$b$bЭти змеюки за все заплатят.', 28153),
(143337, 'ruRU', 'Строение поблизости подвержено порче. Требуется вмешательство.', '', 28153),
(143336, 'ruRU', 'Частичное восстановление завершено. Задача – ремонт системы сдерживания.', '', 28153),
(143335, 'ruRU', 'Обновление вспомогательных систем. Ожидайте...', '', 28153),
(143334, 'ruRU', 'Ты умеешь чинить снаряжение?', 'Ты умеешь чинить снаряжение?', 28153),
(143333, 'ruRU', 'Деревни больше нет, но мой горн они получат только через мой труп!', '', 28153),
(143332, 'ruRU', '', 'За Орду!', 28153),
(143331, 'ruRU', '', 'Таз\'динго!', 28153),
(143330, 'ruRU', '', 'Кого убить?', 28153),
(143329, 'ruRU', 'Я рад, что невинные спасены, но у нас еще много работы.', '', 28153),
(143328, 'ruRU', '', 'Раньше я знала о Штормграде только по рассказам. Теперь я могу пройтись по его улицам и узнать, какие чудеса он таит. Да хранят тебя тени, $n.', 28153),
(143327, 'ruRU', 'Да пребудет с тобой Свет, $n. А я продолжу нашу вечную битву. Буду искать демонов Легиона по всему Азероту.', '', 28153),
(143326, 'ruRU', 'Бред, конечно... но мысль проскочила. Я даже сам удивился.', '', 28153),
(143325, 'ruRU', 'Вынужден признаться. Смотрю на вас и думаю: может, все-таки стоит взять в долю?', '', 28153),
(143324, 'ruRU', 'Так, с подвигами, наконец, разобрались. А теперь перейдем к делу: переоформлению бумаги на шахту!', '', 28153),
(143323, 'ruRU', 'Вы там вмешайтесь, а то как бы мое имущество не пострадало!', '', 28153),
(143322, 'ruRU', 'Цель достигнута. Буду ожидать выполнения текущих задач в новой области.', '', 28153),
(143321, 'ruRU', 'Этим салагам приходится тяжко! Элементали что-то совсем разбушевались!', '', 28153),
(143320, 'ruRU', 'Малютка Тика тихо, но угрожающе рычит.', '', 28153),
(143319, 'ruRU', 'Малютка Тика тревожно верещит!', '', 28153),
(143318, 'ruRU', 'Мир истекает кровью, а вы бередите его раны? Умрите!', '', 28153),
(143317, 'ruRU', 'Устройте тут взрывы, разборки, беспрецедентное насилие! В общем, как обычно.', '', 28153),
(143316, 'ruRU', 'Донесите до Торговой компании, что никаких прав у них здесь нет.', '', 28153),
(143315, 'ruRU', 'Но есть проблема... он не принадлежит мне! Поэтому вы здесь.', '', 28153),
(143314, 'ruRU', 'Так вот откуда азерит поступает на черный рынок. Неплохой бизнес!', '', 28153),
(143313, 'ruRU', '', 'Не знаю, что такое \"воргобой\", но... Так, а это что?', 28153),
(143312, 'ruRU', 'Этот мир тебя не заслуживал, брат. Я похороню тебя со всеми почестями.', '', 28153),
(143311, 'ruRU', 'Люблю запах моджо по утрам!', '', 28153),
(143310, 'ruRU', '', 'Рокхан сказал, у тебя есть опыт обращения с такими штуками. А я подожду здесь подрывной отряд.', 28153),
(143308, 'ruRU', '', 'Такой союзник нам точно не повредит. Помоги ему, $n.', 28153),
(143307, 'ruRU', 'Требуется помощь. Починить Хезрела. Попасть в строение поблизости. Сдержать порчу в Назмире.', '', 28153),
(143306, 'ruRU', 'В Назмире обнаружена обширная порча. Требуется сдерживание.', '', 28153),
(143305, 'ruRU', 'Я прошел через множество битв... но ни разу не видел ничего подобного этому монстру...', '', 28153),
(143304, 'ruRU', 'Живым я не дамся!', '', 28153),
(143303, 'ruRU', 'Ладно, в Вол\'дуне и то безопаснее, чем здесь!', '', 28153),
(143302, 'ruRU', 'Нет! Не надо! Ящеры... они меня сожрут!', '', 28153),
(143301, 'ruRU', 'Спасибо, Залуто. Может, в другой жизни мы были бы братьями.', '', 28153),
(143300, 'ruRU', 'Возьми фетиш крови, поглоти силу Зуладжина и отправь его обратно в могилу!', '', 28153),
(143299, 'ruRU', 'Не беспокойся! Пока ты будешь зачищать развалины, я позабочусь о капитане!', '', 28153),
(143298, 'ruRU', 'Круто! Теперь надень маскировку и возьми ключ!', '', 28153),
(143297, 'ruRU', 'Чтобы пройти мимо Зуладжина, тебе понадобится маскировка. Скорее возвращайся с припасами!', '', 28153),
(143296, 'ruRU', 'Я, может, и преступник, но не злодей какой-нибудь. Я не брошу тебя на произвол судьбы!', '', 28153),
(143295, 'ruRU', 'Спасибо. Теперь если я и умру... то умру с незапятнанной честью.', '', 28153),
(143294, 'ruRU', 'Да-да! Поднимем тост за отважного... ик... защитника и наше счастливое спасение!', '', 28153),
(143293, 'ruRU', '', 'Отправляйся к нашим союзникам в Оргриммар. Мы будем строить будущее вместе.', 28153),
(143292, 'ruRU', '', 'Пусть весь Азерот узнает о богатой и славной истории ночнорожденных... и о том, что время нашей изоляции прошло.', 28153),
(143291, 'ruRU', 'Что мы знаем о ночнорожденных?', 'Что мы знаем о ночнорожденных?', 28153),
(143290, 'ruRU', '', 'Я рада, что ты здесь, $n. Мы должны убедить вождя заключить союз с ночнорожденными.', 28153),
(143289, 'ruRU', 'Что мы знаем о тауренах Крутогорья?', 'Что мы знаем о тауренах Крутогорья?', 28153),
(143288, 'ruRU', '', 'Теперь пришел наш черед проявить силу и честь во славу Орды.', 28153),
(143287, 'ruRU', 'У нас много общего с тауренами Крутогорья. Я верю, что когда-нибудь они станут нашими верными союзниками.', '', 28153),
(143286, 'ruRU', '', 'За Тсунгу не беспокойся. Мы о нем позаботимся. Хоть он даже имя свое забыл...', 28153),
(143285, 'ruRU', '', 'Свет милосердный, какой же он был здоровый! Отличная работа!', 28153),
(143284, 'ruRU', '', 'Пусть звезды укажут тебе путь, $p. Я слышала много занимательных вещей о предгорьях Хилсбрада. Пожалуй, я отправлюсь туда.', 28153),
(143283, 'ruRU', '', 'Ты уверен, Тсунга? Ты знаешь, чего лишишься, если источник тумана иссякнет?', 28153),
(143282, 'ruRU', 'Я приготовлюсь к ритуалу, чтобы высвободить души. Встретимся на берегу к северу отсюда.', '', 28153),
(143281, 'ruRU', 'Я прекрасно понимаю, чем мне это грозит. Но я считаю, что некоторые жертвы необходимо приносить. Даже если это нелегко.', '', 28153),
(143280, 'ruRU', 'Я отправлюсь в ущелье другим путем, буду ждать тебя там.', '', 28153),
(143279, 'ruRU', 'Держать строй! Подкрепление уже в пути. Не дадим нагам разрушить дамбу!', '', 28153),
(143278, 'ruRU', 'Пусть ненависть покинет твое сердце.', '', 28153),
(143277, 'ruRU', '', 'Но син\'дорай, эльфы крови, отнеслись к нам с уважением и пониманием. Они показали, что разделяют наши ценности.', 28153),
(143276, 'ruRU', '', 'В час испытаний герои Азерота помогли нам изгнать Легион из Сурамара. Пусть некоторые и с неохотой.', 28153),
(143275, 'ruRU', '', 'Пусть это традиционное сурамарское одеяние напоминает тебе о нашей истории... и о будущем, что ждет нас и всю Орду.', 28153),
(143274, 'ruRU', 'Хорошо, уже бегу!', '', 28153),
(143273, 'ruRU', '', 'Благодаря тебе вся Орда и все народы Азерота узнали, что ночнорожденные готовы защищать наш мир.', 28153),
(143272, 'ruRU', 'Отправляйся на берег с другой стороны верфи. Отыщи Телию – она служит дому Праудмуров. Вперед!', '', 28153),
(143271, 'ruRU', '', 'Отправляйся в Сурамар, и мы отблагодарим тебя за помощь нашему народу.', 28153),
(143270, 'ruRU', '', 'Тебе посчастливилось быть в числе первых шал\'дорай, которые увидели Азерот. Но теперь пришло время вернуться домой.', 28153),
(143269, 'ruRU', 'Эти работники... Они под чарами жрецов моря! Им нужно помочь.', '', 28153),
(143268, 'ruRU', 'Хвала морям, не все еще с ума посходили. Но половина дома точно чокнулась!', '', 28153),
(143267, 'ruRU', 'Фланель надоела.', 'Фланель надоела.', 28153),
(143266, 'ruRU', '', 'Я пойду на разведку. Увидимся на берегу!', 28153),
(143265, 'ruRU', 'Классно выглядишь, $n.', '', 28153),
(143264, 'ruRU', 'У нас много работы.', '', 28153),
(143263, 'ruRU', 'Надо больше фланели!', 'Надо больше фланели!', 28153),
(143262, 'ruRU', '', 'К оружию!', 28153),
(143261, 'ruRU', '', 'За короля!', 28153),
(143260, 'ruRU', '', 'Получай!', 28153),
(143259, 'ruRU', '', 'Приготовься умереть!', 28153),
(143258, 'ruRU', '', 'За Штормград!', 28153),
(143257, 'ruRU', '', 'За Альянс!', 28153),
(143256, 'ruRU', '', 'Не отступать!', 28153),
(143255, 'ruRU', '', 'Держите меня семеро!', 28153),
(143254, 'ruRU', '', 'О какой порче ты говоришь? $n, может, он считает троллей крови \"порчей\"?', 28153),
(143253, 'ruRU', '', '$n, ты знаешь, кто это? Он согласится нам помочь?', 28153),
(143252, 'ruRU', '', 'Что это за вуду? Думаешь, он поможет нам остановить троллей крови и Г\'ууна?', 28153),
(143251, 'ruRU', 'Держите меня семеро!', '', 28153),
(143250, 'ruRU', 'Не отступать!', '', 28153),
(143249, 'ruRU', 'За Альянс!', '', 28153),
(143248, 'ruRU', 'За Штормград!', '', 28153),
(143247, 'ruRU', 'Приготовься умереть!', '', 28153),
(143246, 'ruRU', 'Получай!', '', 28153),
(143245, 'ruRU', 'За короля!', '', 28153),
(143244, 'ruRU', 'К оружию!', '', 28153),
(143243, 'ruRU', 'Детектор просто зашкаливает. Где-то на острове происходит мощный выброс азерита.', '', 28153),
(143242, 'ruRU', 'Мы должны найти источник заражения.', '', 28153),
(143241, 'ruRU', '', 'Пусть эти доспехи напоминают тебе о твоих достижениях, $p.', 28153),
(143240, 'ruRU', 'Уверен.', '', 28153),
(143239, 'ruRU', 'Т-ты думаешь, что и морских животных это затронуло?', '', 28153),
(143238, 'ruRU', 'Хотите еще один \"дурной знак\"? В бухте полно добычи для Гарпунщиков.', '', 28153),
(143237, 'ruRU', 'Тсунга озабоченно заглядывает в пещеру.', '', 28153),
(143236, 'ruRU', '', 'Многие сомневались, что рен\'дорай сумеют овладеть силой Бездны, не поддаваясь ее влиянию. Они ошибались.', 28153),
(143235, 'ruRU', 'Чем дальше мы от берега, тем явственнее слышен крик моря. Я чувствую, как страдают волны. Это дурной знак.', '', 28153),
(143234, 'ruRU', '', 'Теперь ты – могущественное орудие Альянса, $p. Возвращайся в разлом Бездны, и мы отметим твои успехи.', 28153),
(143233, 'ruRU', 'Пора покончить с этим.', '', 28153),
(143230, 'ruRU', 'Я начну тренировки. А ты иди к Тагарту, у него для тебя еще кое-что есть.', '', 28153),
(143229, 'ruRU', 'Хранитель Хезрел перезагружен. Протокол: сдерживание порчи в Назмире. Выполнение невозможно. Системы повреждены.', '', 28153),
(143228, 'ruRU', '', 'В странствиях по Азероту тебе всегда удавалось удерживать контроль над враждебной силой внутри себя.', 28153),
(143227, 'ruRU', 'Отлично. Посмотрим, как он летает. Ха!', '', 28153),
(143226, 'ruRU', 'Хо-хо! Посмотрите на добычу котенка! Невероятно!', '', 28153),
(143224, 'ruRU', 'Я скажу королю, что как только мы вернем корабли, на башнях зажгутся сигнальные огни. Так моя команда поймет, что можно возвращаться!', '', 28153),
(143223, 'ruRU', 'На этом изображении нет того, что интересует Вульферда. Он его не примет.', 'На этом изображении нет того, что интересует Вульферда. Он его не примет.', 28153),
(143222, 'ruRU', 'Прошу, помоги мне!', '', 28153),
(143221, 'ruRU', 'Я подвел... своих подданных...', '', 28153),
(143220, 'ruRU', '', 'На помощь! Наш командир ранен!', 28153),
(143219, 'ruRU', 'На помощь! На меня напали!', '', 28153),
(143218, 'ruRU', 'Вы за это заплатите!', '', 28153),
(143217, 'ruRU', 'Этот здоровяк мне не по душе.', '', 28153),
(143216, 'ruRU', 'О нет! Плакала моя страховка!', '', 28153),
(143215, 'ruRU', 'За что я вам плачу? Быстро сделали как было!', '', 28153),
(143214, 'ruRU', 'Кого угостить крупным калибром?', '', 28153),
(143213, 'ruRU', 'Получайте 300 пуль в минуту!', '', 28153),
(143212, 'ruRU', 'Тут тебе и место! У меня под ногами!', '', 28153),
(143211, 'ruRU', 'Лежать!', '', 28153),
(143210, 'ruRU', '', 'Я пойду вперед на разведку. Встретимся на дороге!', 28153),
(143209, 'ruRU', 'Живым вы меня не возьмете!', '', 28153),
(143208, 'ruRU', 'Зря... пожалел денег... на катапульту...', '', 28153),
(143207, 'ruRU', 'Я выставлю вам счет за боеприпасы!', '', 28153),
(143206, 'ruRU', '', 'Помни, чему я тебя учила. Сдерживай голоса Бездны. Стань орудием Альянса и оставайся им даже на краю тьмы.', 28153),
(143205, 'ruRU', 'Кто-то может усомниться в силе твоей воли, в твоей способности контролировать сокрытую в тебе опасную мощь.', '', 28153),
(143204, 'ruRU', '', 'Мы же знаем, что это не так. Мы используем все возможности, все доступные нам силы.', 28153),
(143203, 'ruRU', '', 'Многие считают, что Свет – единственное оружие, способное остановить врагов Азерота.', 28153),
(143202, 'ruRU', 'Вы хоть представляете, какой ущерб я получил?', '', 28153),
(143201, 'ruRU', 'Добро пожаловать в ряды Сорвиголов!', '', 28153),
(143200, 'ruRU', 'Все как и говорил тот старый змей. Ну, что же... залезай, король ждет нас.', '', 28153),
(143199, 'ruRU', 'Крушить!', '', 28153),
(143198, 'ruRU', 'Давить!', '', 28153),
(143197, 'ruRU', 'Стереть в порошок!', '', 28153),
(143196, 'ruRU', 'Жаль, что я так и не смог преподать ему самый главный урок.', '', 28153),
(143195, 'ruRU', 'Передай старику Растахану, что я вернусь, как придет время. И кстати... спасибо тебе.', '', 28153),
(143193, 'ruRU', 'Сначала я запущу когти в Язму и Зула, а потом сброшу их на скалы!', '', 28153),
(143192, 'ruRU', 'Наша добыча близко. Скоро прольется кровь Зула, Язмы и их последователей-еретиков. Это будет славная охота.', '', 28153),
(143191, 'ruRU', 'Слава Па\'ку!', 'Слава Па\'ку!', 28153),
(143190, 'ruRU', 'Корабль будет нашим!', 'Корабль будет нашим!', 28153),
(143189, 'ruRU', 'Таз\'окун!', 'Таз\'окун!', 28153),
(143188, 'ruRU', 'Это всего лишь царапина. Думаю, ничего страшного.', '', 28153),
(143185, 'ruRU', '', 'Сейчас вы будете гореть!', 28153),
(143184, 'ruRU', '', 'Горите! Горите ярче!', 28153),
(143183, 'ruRU', '', 'Хотели азерита? Подавитесь им!', 28153),
(143182, 'ruRU', '', 'Еще один несчастный случай на производстве!', 28153),
(143181, 'ruRU', 'Оно того не стоит!', '', 28153),
(143180, 'ruRU', '', 'Неопытность смертельно опасна!', 28153),
(143179, 'ruRU', 'За Альянс!', '', 28153),
(143178, 'ruRU', '', 'Для меня честь вернуться на службу, верховный король. За Альянс!', 28153),
(143177, 'ruRU', '', 'Неквалифицированный кадр!', 28153),
(143176, 'ruRU', 'Леди Ветрокрылая, $p, вы оказали Альянсу большую услугу. Спасибо вам.', '', 28153),
(143175, 'ruRU', 'Эльфам Бездны еще предстоит завоевать наше доверие, но если они будут следовать вашим наставлениям, Альянс будет рад такому союзу.', '', 28153),
(143174, 'ruRU', '', 'Забыла взять надбавку... за вредность...', 28153),
(143173, 'ruRU', '', 'Я буду их наставницей. Научу их сдерживать голоса теней. Они станут верными союзниками Альянса.', 28153),
(143172, 'ruRU', '', 'Верховный король, мы нашли изгнанников-син\'дорай. Бездна преобразила их, подобно мне, но не поработила их разум.', 28153),
(143171, 'ruRU', '', 'Чем больше взрывчатки, тем лучше результат!', 28153),
(143170, 'ruRU', '', 'Так это из-за вас моя бригада разбежалась?', 28153),
(143169, 'ruRU', '', 'Эй, а ну вернитесь немедленно!', 28153),
(143168, 'ruRU', 'Чужаки?! Сматываемся!', 'Чужаки?! Сматываемся!', 28153),
(143167, 'ruRU', 'Не знаю, что за тьма поглотила твой разум, сестра, но я не позволю ей истязать наш народ.', '', 28153),
(143166, 'ruRU', 'Ну же, ты справишься!', '', 28153),
(143165, 'ruRU', 'Бежим!', '', 28153),
(143164, 'ruRU', '', 'Хватит жаловаться! Никто не говорил, что это безопасная работа!', 28153),
(143163, 'ruRU', 'Здесь опасно. Вам нужно уходить.', '', 28153),
(143162, 'ruRU', 'Да кому он нужен, этот дурацкий остров!', '', 28153),
(143161, 'ruRU', 'Мы обречены!', '', 28153),
(143160, 'ruRU', 'Уходите! Работа окончена.', '', 28153),
(143159, 'ruRU', 'Он вырвался на свободу! Назад!', '', 28153),
(143158, 'ruRU', 'Братья и сестры, теперь вы свободны.', '', 28153),
(143157, 'ruRU', '', 'И пока вы тут жалуетесь, вы продолжаете вдыхать испарения! Так что пеняйте потом на себя.', 28153),
(143156, 'ruRU', 'Возвращайтесь к семьям. Мы со всем разберемся.', '', 28153),
(143155, 'ruRU', 'Бегите, глупцы!', '', 28153),
(143154, 'ruRU', 'Твоя душа освободится от смертной оболочки и вернется в море.', '', 28153),
(143153, 'ruRU', 'Песня шторма принесет тебе покой.', '', 28153),
(143152, 'ruRU', 'Не вопрошай, по ком светит маяк. По тебе.', '', 28153),
(143151, 'ruRU', '', 'За Орду!', 28153),
(143150, 'ruRU', '', 'За Орду!', 28153),
(143149, 'ruRU', '', 'Отныне Сурамар – часть Орды!', 28153),
(143148, 'ruRU', '', 'Сурамар провел тысячи лет в изоляции, но теперь все будет иначе. Я принимаю вашу присягу, Талисра.', 28153),
(143147, 'ruRU', '', 'Пришло время ночнорожденным найти союзников среди народов Азерота. Если вы согласитесь нас принять, мы готовы служить Орде.', 28153),
(143146, 'ruRU', '', 'Орда воплощает в себе силу, решимость и уважение к традициям – все то, что ценят шал\'дорай.', 28153),
(143145, 'ruRU', '', 'Они – наши герои.', 28153),
(143144, 'ruRU', '', 'Мое почтение, вождь. Я сражалась плечом к плечу с леди Лиадрин и лордом-регентом. Их отвага делает честь Орде.', 28153),
(143143, 'ruRU', 'Отринь страх. Волны тебя не осудят.', '', 28153),
(143142, 'ruRU', 'Волны унесут твои печали.', '', 28153),
(143141, 'ruRU', 'Да упокоится дух твой на веки вечные.', '', 28153),
(143140, 'ruRU', 'Пучина примет твою уставшую душу.', '', 28153),
(143139, 'ruRU', 'Мать волн очистит твою грешную плоть.', '', 28153),
(143138, 'ruRU', 'Волны унесут твою грешную душу.', '', 28153),
(143137, 'ruRU', 'Земля поглотит вас!', '', 28153),
(143136, 'ruRU', 'Море к морю, прах к праху, волна к волне.', '', 28153),
(143135, 'ruRU', 'Содрогнитесь!', '', 28153),
(143134, 'ruRU', 'В тебе течет кровь Азерота!', '', 28153),
(143133, 'ruRU', 'Нельзя, чтобы эти потерянные души скитались и дальше. $p, нам надо поговорить.', '', 28153),
(143132, 'ruRU', 'Покажи свою силу!', '', 28153),
(143131, 'ruRU', 'Немного промокло, но письмена читаются. Они нам еще послужат.', '', 28153),
(143130, 'ruRU', 'Морские туманы скрывают многое, но этот фонарь поможет увидеть сокрытое.', '', 28153),
(143129, 'ruRU', 'Восстаньте!', '', 28153),
(143128, 'ruRU', '', 'Здравствуй, дитя мое. Я потеряла зрение, но Па\'ку не оставила меня.\n\nСядь поближе. Что ты хочешь знать о великой лоа? Я постараюсь ответить на все твои вопросы.', 28153),
(143127, 'ruRU', 'Лезвие не затупилось. Хорошо. Острый — значит, надежный.', '', 28153),
(143126, 'ruRU', 'Ты больше не причинишь вреда.', '', 28153),
(143125, 'ruRU', 'Чего стоит твоя кровь?', '', 28153),
(143124, 'ruRU', '', 'Вождь Сильвана, представляю вам Талисру, первую чародейку Сурамара.', 28153),
(143123, 'ruRU', '', 'Буду ждать твоих распоряжений, |3-6($c).', 28153),
(143122, 'ruRU', '', 'Я в этом сомневаюсь... но приказ есть приказ.', 28153),
(143121, 'ruRU', '', 'Маршал Рид считает, что благодаря тебе мы победим ковен?', 28153),
(143120, 'ruRU', 'Бей изо всех сил!', '', 28153),
(143119, 'ruRU', 'Давно пора.', '', 28153),
(143118, 'ruRU', 'Навались!', '', 28153),
(143117, 'ruRU', 'Тянем-потянем!', '', 28153),
(143116, 'ruRU', 'Что ж, Уинстон, похоже, нас ждет охота на ведьм.', '', 28153),
(143115, 'ruRU', 'Еще пара хороших ударов – и готово.', '', 28153),
(143114, 'ruRU', 'Уже почти на месте! Еще немного!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143113, 'ruRU', 'Новые приказы?', '', 28153),
(143112, 'ruRU', 'Спасибо за уведомление, |3-6($c). Я немедленно отправлюсь к мисс Уэйкрест.', '', 28153),
(143111, 'ruRU', 'А я-то думал, что все рассказы о нем – плод фантазий замечтавшегося историка.', '', 28153),
(143110, 'ruRU', 'Без вас здесь станет только лучше.', '', 28153),
(143109, 'ruRU', 'Значит, слухи не врут? Орден правда восстановлен?', '', 28153),
(143108, 'ruRU', 'Нужно исцелить... рану...', '', 28153),
(143107, 'ruRU', '', 'Можешь на меня рассчитывать, |3-6($c).', 28153),
(143106, 'ruRU', 'Вы вторглись в мои владения!', '', 28153),
(143105, 'ruRU', '', 'Я в чудеса не верю, но все лучше, чем сидеть и ждать, пока ковен перебьет нас всех до единого.', 28153),
(143104, 'ruRU', '', 'Так это ты \"возрождаешь\" тот самый Орден, о котором все говорят?', 28153),
(143103, 'ruRU', '<Вручить приказ маршала Рида.>', '<Вручить приказ маршала Рида.>', 28153),
(143102, 'ruRU', '', 'Големов все больше. Видимо, живые воины заканчивались, и он создал новую армию. Но что за сила оживляла камни?', 28153),
(143101, 'ruRU', '', 'Чем могу быть полезна, |3-6($c)?', 28153),
(143100, 'ruRU', '', 'Это, очевидно, Горак Тул, вождь друстов. Он проводит ритуал создания каменных големов.', 28153),
(143099, 'ruRU', '<Стернтайд слегка кивает вам, когда вы подходите к нему.>', '', 28153),
(143098, 'ruRU', 'Прекрасный экземпляр, да? Уэйкресты всегда славились мастерством соколиной охоты.\n\nК сожалению, почти всех наших лучших птиц поразило проклятие ведьм. Уинстон – один из немногих соколов Уэйкрестов, на кого чары не подействовали.\n\nВоистину, плачевная ситуация.', '', 28153),
(143097, 'ruRU', '', 'А здесь... они наслаждаются резней, убивая безоружных култирасцев!', 28153),
(143096, 'ruRU', 'В этих лесах пробуждается какая-то злая сила. По ночам древний друстварский памятник мерцает от заключенной в нем темной силы.\n\nНа твоем месте я бы обходил его стороной.', '', 28153),
(143095, 'ruRU', '', 'Что тебе нужно?\n\nНе видишь, я тут немного занята?', 28153),
(143094, 'ruRU', 'Устранить нарушителя. На-начинаю ликвидацию.', '', 28153),
(143093, 'ruRU', 'Высвобождение порчи неотвратимо. Ак-активация про-про-протоколов безопасности. Обнаружено втор-вторжение.', '', 28153),
(143092, 'ruRU', 'Ошибка... обнаружено... втор-вторжение... Выполняется поиск... Порча...', '', 28153),
(143091, 'ruRU', 'Выпускаю токсичный газ.', '', 28153),
(143090, 'ruRU', 'Напряжение повышено.', '', 28153),
(143089, 'ruRU', 'Активация завершена. Начинаю обработку толпы.', '', 28153),
(143088, 'ruRU', '', 'На этой стеле изображены мирные жители Кул-Тираса... моряки... и фермеры.', 28153),
(143087, 'ruRU', '', 'И вождь друстов вынужден отступить.', 28153),
(143086, 'ruRU', '', 'Ха! А вот здесь наши дают отпор!', 28153),
(143085, 'ruRU', '', 'Странно, что нигде не видно каменных големов.', 28153),
(143084, 'ruRU', 'Торговая компания благодарит вас за заказ. Вы приобрели элитный пакет услуг по разгону незаконных массовых собраний.', '', 28153),
(143083, 'ruRU', '', 'Еще одно разоренное кул-тирасское поселение. В центре, по-видимому, легендарный вождь друстов.', 28153),
(143082, 'ruRU', 'Торговая компания благодарит вас за заказ. Вы приобрели базовый пакет услуг по разгону незаконных массовых собраний.', '', 28153),
(143081, 'ruRU', 'Дай мне несколько месяцев, и я превращу это место в образцовый курорт!', '', 28153),
(143080, 'ruRU', 'Тупица! Только дураки продлевают гарантию!', 'Тупица! Только дураки продлевают гарантию!', 28153),
(143079, 'ruRU', 'Ладно, ладно! Стоп... а гарантию продлевать надо?', 'Ладно, ладно! Стоп... а гарантию продлевать надо?', 28153),
(143078, 'ruRU', '', '', 28153),
(143077, 'ruRU', 'Они нас всех перебьют!', 'Они нас всех перебьют!', 28153),
(143076, 'ruRU', 'Не теребите! Я читаю договор!', 'Не теребите! Я читаю договор!', 28153),
(143075, 'ruRU', 'Живее! Они на подходе!', 'Живее! Они на подходе!', 28153),
(143074, 'ruRU', 'Мне надо было немного отдохнуть.', '', 28153),
(143073, 'ruRU', 'Успокойся, девочка. Все хорошо.', '', 28153),
(143072, 'ruRU', 'Сбой... системы. Выдача сдачи... невозможна.', '', 28153),
(143071, 'ruRU', 'Кто хочет полетать? Ты хочешь полетать? Давай полетаем!', '', 28153),
(143070, 'ruRU', 'Не кусаться!', '', 28153),
(143069, 'ruRU', 'Запускаю протокол контроля повреждений.', '', 28153),
(143068, 'ruRU', 'Повреждение этой установки незаконно.', '', 28153),
(143067, 'ruRU', 'Бомбы пошли!', 'Бомбы пошли!', 28153),
(143066, 'ruRU', 'Берегитесь, тюфяки!', 'Берегитесь, тюфяки!', 28153),
(143065, 'ruRU', 'Эй, ты! А ну за работу!', 'Эй, ты! А ну за работу!', 28153),
(143064, 'ruRU', 'Приступаю к летальному разгону.', '', 28153),
(143063, 'ruRU', 'Обнаружено незаконное сборище. Разойтись!', '', 28153),
(143062, 'ruRU', 'Погребальные услуги по доступным ценам.', '', 28153),
(143061, 'ruRU', 'Еще один довольный заказчик.', '', 28153),
(143060, 'ruRU', 'Возврат конечностей за отдельную плату.', '', 28153),
(143059, 'ruRU', 'Орда отразила нападение!', 'Орда отразила нападение!', 28153),
(143058, 'ruRU', 'И рассредоточьтесь! Псы Альянса направят сюда подкрепление.', '', 28153),
(143057, 'ruRU', '', 'Когда этот корабль войдет в гавань, я стану капитаном! Слушай внимательно, что я говорю, и учись кланяться!', 28153),
(143056, 'ruRU', '', 'Эти пленники сами не понимают, как им повезло! Скоро они будут с Зулом.', 28153),
(143055, 'ruRU', '', 'Если вы хотите захватить эту гавань, старайтесь лучше!', 28153),
(143054, 'ruRU', 'Не могу... сопротивляться... А-А-А!', '', 28153),
(143050, 'ruRU', 'Нет! Мне суждено умереть не здесь!', '', 28153),
(143049, 'ruRU', 'Откуда он... знает...', '', 28153),
(143048, 'ruRU', 'Как такое возможно?!', '', 28153),
(143047, 'ruRU', 'Твоя сила не сравнится с моим даром!', '', 28153),
(143046, 'ruRU', 'Что вы делаете? Не трогайте меня!', '', 28153),
(143045, 'ruRU', 'Воины! Защищайте своего господина!', '', 28153),
(143044, 'ruRU', 'Это вас ждет смерть!', '', 28153),
(143043, 'ruRU', 'Это тебе не поможет, старик!', '', 28153),
(143042, 'ruRU', 'Правда твоя. Но я пришел не один.', '', 28153),
(143041, 'ruRU', 'Мы оба прекрасно знаем, что ты меня не убьешь.', '', 28153),
(143040, 'ruRU', 'Молодец, девочка. Скоро поедим!', '', 28153),
(143039, 'ruRU', 'Я устал от этой игры. Ты сказал, что хотел. А теперь готовься встретить свою судьбу.', '', 28153),
(143038, 'ruRU', 'Зул выпивает зелье одним долгим глотком, содрогаясь от неприятного вкуса.', '', 28153),
(143037, 'ruRU', 'Бери первое попавшееся, долго не думай.', '', 28153),
(143036, 'ruRU', 'Осторожнее, его слуги будут мешать тебе.', '', 28153),
(143035, 'ruRU', 'Хм.', '', 28153),
(143034, 'ruRU', 'Иди сюда. Время пришло.', '', 28153),
(143033, 'ruRU', 'Хорошо. Теперь замени одно из зелий Вол\'джамбы тем, что я тебе дал.', '', 28153),
(143032, 'ruRU', 'Хотя... Подвинь-ка ее чу-уть левее.', '', 28153),
(143031, 'ruRU', 'Теперь поставь урну рядом с аркой.', '', 28153),
(143030, 'ruRU', 'За пределами посольства держи оружие наготове, $p. Зандаларам не хватает сил и решимости, чтобы поддерживать порядок. Им нужен настоящий вождь, такой как у нас.\n\nЧем могу тебе помочь?', 'За пределами посольства держи оружие наготове, $p. Зандаларам не хватает сил и решимости, чтобы поддерживать порядок. Им нужен настоящий вождь, такой как у нас.\n\nЧем могу тебе помочь?', 28153),
(143029, 'ruRU', 'Если увидишь шпионов Альянса, скажи мне. Я с ними разберусь.\n\nТы что-то ищешь?', 'Если увидишь шпионов Альянса, скажи мне. Я с ними разберусь.\n\nТы что-то ищешь?', 28153),
(143028, 'ruRU', 'Говори что хочешь о зандаларах, но посольства они строить умеют. Да и город просто огромный!\n\nПодсказать тебе дорогу?', 'Говори что хочешь о зандаларах, но посольства они строить умеют. Да и город просто огромный!\n\nПодсказать тебе дорогу?', 28153),
(143027, 'ruRU', 'Я занят. Говори быстро.', 'Я занята. Говори быстро.', 28153),
(143026, 'ruRU', 'Что тебе нужно, $p?', 'Что тебе нужно, $p?', 28153),
(143025, 'ruRU', 'Слава вождю! Ты что-то ищешь?', 'Слава вождю! Ты что-то ищешь?', 28153),
(143024, 'ruRU', 'Посольство огромное – видно, что зандалары уважают силу нашего вождя. Хорошо бы им еще и бояться ее.\n\nТебе что-то нужно?', 'Посольство огромное – видно, что зандалары уважают силу нашего вождя. Хорошо бы им еще и бояться ее.\n\nТебе что-то нужно?', 28153),
(143023, 'ruRU', 'От такой влажности у меня все кости отсыреют. Чем могу помочь?', 'От такой влажности у меня все кости отсыреют. Чем могу помочь?', 28153),
(143022, 'ruRU', 'Дела идут в гору, здоровяк. Когда-нибудь это все будет нашим.', '', 28153),
(143021, 'ruRU', 'За что мы тебе платим? За безделье?', '', 28153),
(143020, 'ruRU', '', 'Смерть словно преследует Ветрокрылых.', 28153),
(143019, 'ruRU', '', 'Да уж. Порой мне кажется, что я умерла дважды. Первый раз, когда мы не вернулись с Дренора, а второй, когда меня поглотила тень падшей наару.', 28153),
(143018, 'ruRU', 'Не могу сказать, что мне приятно видеть памятники в нашу честь.', '', 28153),
(143017, 'ruRU', '', 'Время пришло, Туралион. Я должна снова увидеть родину... И спросить у Сильваны, как она могла надеть мантию вождя.', 28153),
(143016, 'ruRU', 'У каждой из вас свой путь. И если Свет пожелает, чтобы они пересеклись, так и будет. Не испытывай судьбу.', '', 28153),
(143015, 'ruRU', 'Ты понимаешь, что не обязана встречаться с ней.', '', 28153),
(143014, 'ruRU', '', 'Как никто другой, любовь моя.', 28153),
(143013, 'ruRU', 'Ты скрываешь тревогу... но я-то тебя знаю.', '', 28153),
(143012, 'ruRU', 'И пусть впереди вас ждут нелегкие испытания... Не забывайте о своем долге перед Азеротом!', '', 28153),
(143011, 'ruRU', 'В вашем оружии столько силы... Никогда такого не видел! Но помните, любая сила имеет цену.', '', 28153),
(143010, 'ruRU', 'Получилось! Меч больше не излучает энергию. Это не исцелит Азерот... но даст нам время.', '', 28153),
(143009, 'ruRU', 'Все вместе! За Азерот!', '', 28153),
(143008, 'ruRU', 'Поднимите его... очистите клинок Темного титана от порчи!', '', 28153),
(143007, 'ruRU', 'Вобрать в себя такую силу способно только ваше могущественное оружие.', '', 28153),
(143006, 'ruRU', 'Меч Саргераса отравляет саму кровь нашего мира.', '', 28153),
(143005, 'ruRU', 'Отправляйтесь в Силитус... иначе скоро вам будет не за что сражаться.', '', 28153),
(143004, 'ruRU', 'Я знаю, что напряжение растет... Но вы должны снова сплотиться вместе.', '', 28153),
(143003, 'ruRU', 'Герои! Вы объединили свои ордена и вышвырнули Легион с Азерота.', '', 28153),
(143002, 'ruRU', 'Надвигается буря, $p. Если мы не придумаем, как исцелить Азерот... всему конец.', '', 28153),
(143001, 'ruRU', 'Я не знаю, что делать. Да и вряд ли кто-то знает. Но сдаваться нельзя.', '', 28153),
(143000, 'ruRU', 'После нашего возвращения с Аргуса Азерот ужасно страдает. Столько боли...', '', 28153),
(142999, 'ruRU', 'Ты здесь... Приятно видеть знакомые лица в темные времена.', '', 28153),
(142998, 'ruRU', 'Мы все еще ждем новостей, принцесса. Зато мы кое-что узнали о Краг\'ве.', '', 28153),
(142997, 'ruRU', '', '...вот что стало с Торгой. А что слышно от Орды? У нас будет подкрепление?', 28153),
(142996, 'ruRU', 'Мы почти закончили, $n. Осталось еще немного.', '', 28153),
(142995, 'ruRU', 'Поверить не могу, что эти монстры сотворили с Торгой такое...', '', 28153),
(142994, 'ruRU', 'Ну вот, Торга умер, и теперь мне совсем нечего рассказать остальным по возвращении.', '', 28153),
(142993, 'ruRU', 'А где Киша? Я думал, она будет тут и подскажет, куда дальше идти...', '', 28153),
(142992, 'ruRU', 'Ладно, я пойду в Мрачную низину и погляжу, что из этого выйдет.', '', 28153),
(142991, 'ruRU', 'А... Ну ладно, думаю, схватка с ордой троллей крови станет интересной историей. Так и быть, пойду в Мрачную низину.', '', 28153),
(142990, 'ruRU', 'Вы... Что вы сделали?! Уж я не упущу такую историю – отправлюсь в Мрачную низину сейчас же.', '', 28153),
(142989, 'ruRU', 'Ну что, Киша. Пора бы нам отправиться в Мрачную низину и собрать по дороге всех наших. $n, подберешь тех, кого мы пропустим?', '', 28153),
(142988, 'ruRU', '', 'Я пойду в Мрачную низину, а ты собери всех тортолланов, которых встретишь по пути.', 28153),
(142987, 'ruRU', '$n, к орудию!', '', 28153),
(142986, 'ruRU', 'Удачи, $p. Я же отправлюсь попробовать себя в Ясеневом лесу. За Орду!', '', 28153),
(142985, 'ruRU', '\"Дыхание Па\'ку\" и \"Коготь Резана\" обошли вокруг света и возвращаются домой. Помоги им проделать оставшуюся часть пути.', '', 28153),
(142984, 'ruRU', 'Когда корабли вернулись, с ними пришла тьма. Я чую беду, нутром чую!', '', 28153),
(142983, 'ruRU', '\"Дыхание Па\'ку\" много лет был моим домом. Без него мое сердце опустело, как и эта гавань.', '', 28153),
(142982, 'ruRU', 'Рык Анджи Громовержца придает вам сил.', '', 28153),
(142981, 'ruRU', 'Эй! Бегом в лодку! Капитан говорит, на \"Дыхании Па\'ку\" что-то случилось!', '', 28153),
(142980, 'ruRU', '', 'Командир, мы пришли на помощь. Сегодня дамба выстоит!', 28153),
(142979, 'ruRU', '', 'Вперед, к дамбе. Командор Рид не любит ждать!', 28153),
(142977, 'ruRU', 'Такие как ты недостойны этого места!', '', 28153),
(142976, 'ruRU', 'Ты трусливая мартышка!', '', 28153),
(142975, 'ruRU', 'Я презираю твой род, беззубое создание!', '', 28153),
(142974, 'ruRU', 'Убирайся, ничтожное существо!', '', 28153),
(142973, 'ruRU', 'Тебя ждет страшная кара!', '', 28153),
(142972, 'ruRU', 'Я буду давить тебя, пока ты не взмолишься о пощаде!', '', 28153),
(142971, 'ruRU', 'Я собственными руками лишу тебя всех зубов!', '', 28153),
(142970, 'ruRU', 'Внимание!', '', 28153),
(142969, 'ruRU', '', 'Именем дома Уэйкрестов, я нарекаю вас инквизиторами ордена Пылающих Углей.', 28153),
(142968, 'ruRU', '', 'Вы станете лучом надежды в борьбе против несметных полчищ врагов.', 28153),
(142967, 'ruRU', '', 'Вы станете сияющим клинком, карающим нечестивых.', 28153),
(142966, 'ruRU', '', 'Братья и сестры! Сегодня вы станете ярким огнем, который прогонит тьму.', 28153),
(142965, 'ruRU', '', 'Ага, вот она.', 28153),
(142964, 'ruRU', '', 'Где-то в книге я видела речь для посвящаемых... Ну-ка...', 28153),
(142963, 'ruRU', '', 'Спасибо, что предоставили своих людей, маршал. Теперь это и вправду похоже на орден!', 28153),
(142962, 'ruRU', 'Я жду аудиенции у короля уже много дней. Казалось бы, ему должно быть интересно, что в его землях делают гоблины.', '', 28153),
(142961, 'ruRU', 'Здесь много опытных воинов, миледи. Они готовы встать в ряды возрожденного ордена Пылающих Углей.', '', 28153),
(142960, 'ruRU', '', 'Маршал, возможно, мы нашли оружие против ковена. Но нам понадобятся умелые солдаты.', 28153),
(142959, 'ruRU', 'Я не предавал лоа и наш город!..', '', 28153),
(142958, 'ruRU', 'Я поклоняюсь Па\'ку. Магия крови под запретом!', '', 28153),
(142957, 'ruRU', 'Я говорю правду. Я ничего не знаю о реликвиях крови!', '', 28153),
(142956, 'ruRU', 'Я тут ни при чем! Пожалуйста, пощадите меня!', '', 28153),
(142955, 'ruRU', 'Я не занимался контрабандой реликвий крови! Магия крови – это зло!', '', 28153),
(142954, 'ruRU', 'Я не видел никаких реликвий крови!', '', 28153),
(142953, 'ruRU', 'Я не знаю, о чем ты!..', '', 28153),
(142952, 'ruRU', 'Я ни в чем не виноват!', '', 28153),
(142951, 'ruRU', 'Не заставляй меня снова бить тебя!', '', 28153),
(142950, 'ruRU', 'Кому ты продаешь реликвии крови?', '', 28153),
(142949, 'ruRU', 'Предатель... ты отвратителен.', '', 28153),
(142948, 'ruRU', 'Я заставлю тебя страдать, Про\'дитор. И ты послужишь примером для остальных.', '', 28153),
(142947, 'ruRU', 'Признавайся, и я убью тебя быстро. Обещаю.', '', 28153),
(142946, 'ruRU', 'Про\'дитор, ты худший из мерзавцев. Магия крови убивает наших братьев и сестер!', '', 28153),
(142945, 'ruRU', 'Мы знаем, что ты тайно ввозил в город реликвии крови.', '', 28153),
(142944, 'ruRU', 'Рассказывай, откуда у тебя реликвии крови, Про\'дитор.', '', 28153),
(142943, 'ruRU', 'Этот мерзавец провозил в наш город реликвии крови.\n\nОн во всем признается, и мы казним его в назидание остальным.', '', 28153),
(142942, 'ruRU', 'Я ни в чем не виноват! Скажи им!', '', 28153),
(142941, 'ruRU', '(Уйти)', '(Уйти)', 28153),
(142940, 'ruRU', '<Окровавленные останки беглой преступницы Тешиямби изуродованы до неузнаваемости. Скорее всего, это постарались местные ящеры.>', '<Окровавленные останки беглой преступницы Тешиямби изуродованы до неузнаваемости. Скорее всего, это постарались местные ящеры.>', 28153),
(142939, 'ruRU', 'Я знаю, кто ты, Моджоба. Отправляйся в Вол\'дун и живи в изгнании.', 'Я знаю, кто ты, Моджоба. Отправляйся в Вол\'дун и живи в изгнании.', 28153),
(142938, 'ruRU', 'Ты кто? Что тебе нужно?', '', 28153),
(142937, 'ruRU', 'Прости, но тебя изгнали в Вол\'дун за твои преступления.', 'Прости, но тебя изгнали в Вол\'дун за твои преступления.', 28153),
(142936, 'ruRU', 'Тсс! Я прячусь от ящеров и Зуладжина. Мне нужно вернуться в Зулдазар.', '', 28153),
(142935, 'ruRU', '', 'А вы ничего... хотя так сразу и не скажешь.', 28153),
(142934, 'ruRU', '', 'Теперь, когда мы завладели ключами и взяли тюрьму под контроль, можно приниматься за азерит и освобождение заложников.', 28153),
(142933, 'ruRU', '', 'Похоже, леди Эшвейн все же понадобится новый надзиратель.', 28153),
(142932, 'ruRU', 'Осторожнее с огнем! Да, ты, воспламенительница. Если хоть один ящик с азеритом взорвется, от нас останется только пепел.', '', 28153),
(142931, 'ruRU', 'Готовьтесь, ребята! Они идут!', '', 28153),
(142930, 'ruRU', '', 'Мы наведем порядок на нижних уровнях, а вы пробивайтесь к надзирателю.', 28153),
(142929, 'ruRU', '', 'Отлично. Похоже, вы неплохо справляетесь.', 28153),
(142928, 'ruRU', 'Как доберемся до пленников надзирателя, весь выкуп будет нашим.', '', 28153),
(142927, 'ruRU', 'Парни, ломаем двери!', '', 28153),
(142926, 'ruRU', '', 'Смотри. Иначе первым приказом нового надзирателя будет утопить тебя вместе с остальными.', 28153),
(142925, 'ruRU', 'Прошу прощения, леди Эшвейн. Уверен, мои стражники наведут порядок.', '', 28153),
(142924, 'ruRU', '', 'Корги! Почему ты не затопил нижние уровни, чтобы эти крысы захлебнулись?', 28153),
(142923, 'ruRU', '', 'Фу! И бежали вы тоже через эту дрянь? Постарайтесь держаться от меня подальше.', 28153),
(142922, 'ruRU', '', 'Думаю, именно из-за этого существа здесь было так мало патрулей. Хорошо, что вы от него избавились.', 28153),
(142921, 'ruRU', '', 'Мы снимем стражу по периметру, а вы найдите вход в канализацию. Через нее можно проникнуть в тюрьму.', 28153),
(142920, 'ruRU', '', 'По данным разведки, ключи от крыла, в котором находятся заложники и склад азерита, надзиратель носит на шее.', 28153),
(142919, 'ruRU', '', 'Тихо! Нас пока не заметили.', 28153),
(142918, 'ruRU', 'А это точно надо?', '', 28153),
(142917, 'ruRU', 'Чего надо?', '', 28153),
(142916, 'ruRU', 'К работе готов.', '', 28153),
(142915, 'ruRU', 'Наши казармы разрушены!', '', 28153),
(142914, 'ruRU', 'Нам нужно подкрепление, чтобы победить в этой войне.', '', 28153),
(142913, 'ruRU', 'За работу!', '', 28153),
(142912, 'ruRU', 'Это здание само себя не построит!', '', 28153),
(142911, 'ruRU', 'Бей сильнее!', '', 28153),
(142910, 'ruRU', '', 'Аллерия демонстративно напрягается.', 28153),
(142909, 'ruRU', 'Я спасен!', 'Я спасена!', 28153),
(142908, 'ruRU', 'Думаю, я смогу добраться до безопасного места. Спасибо.', 'Думаю, я смогу добраться до безопасного места. Спасибо.', 28153),
(142907, 'ruRU', 'Их атаки все не прекращаются. Спасибо тебе за помощь.', 'Их атаки все не прекращаются. Спасибо тебе за помощь.', 28153),
(142906, 'ruRU', 'Я не забуду твоей отваги!', 'Я не забуду твоей отваги!', 28153),
(142905, 'ruRU', 'Я думал, умру там!', 'Я думала, умру там!', 28153),
(142904, 'ruRU', 'Вот бы в нашей деревне было больше таких героев, как ты!', 'Вот бы в нашей деревне было больше таких героев, как ты!', 28153),
(142903, 'ruRU', 'Отомсти за тех, кого уже не спасти!', 'Отомсти за тех, кого уже не спасти!', 28153),
(142902, 'ruRU', 'Эти наги – монстры!', 'Эти наги – монстры!', 28153),
(142901, 'ruRU', 'Мои заточки пронзят вас насквозь!', '', 28153),
(142900, 'ruRU', 'Чужаки прорвались через стоки!', '', 28153),
(142898, 'ruRU', 'Этот камень поет беззвучную, но могучую песнь. Я знаю, кто способен услышать ее. Надеюсь, она никогда не появится на этих берегах.', '', 28153),
(142897, 'ruRU', 'Я увидел все, что хотел. Этот камень – зло, его нужно уничтожить.', '', 28153),
(142894, 'ruRU', 'Вряд ли он расстанется с ним по доброй воле – придется забрать оружие с его трупа.', '', 28153),
(142893, 'ruRU', 'Я заметил еще одну цель на юге. Не теряйте времени.', '', 28153),
(142892, 'ruRU', 'Жаль, что уничтожение этого судна поможет култирасцам в обороне.', '', 28153),
(142891, 'ruRU', 'Уверен, Темная Госпожа будет довольна.', '', 28153),
(142890, 'ruRU', '', 'С удовольствием, лорд-регент! До встречи в Луносвете, $n!', 28153),
(142889, 'ruRU', 'Прекрасно! Леди Лиадрин, вернитесь в Оргриммар и сообщите эту новость вождю.', '', 28153),
(142888, 'ruRU', '', 'От лица шал\'дорай я принимаю твое предложение. Отныне Сурамар сражается за Орду.', 28153),
(142887, 'ruRU', 'Орда позволит вам воплотить эту мечту. Двери Луносвета всегда открыты для вас.', '', 28153),
(142886, 'ruRU', '', 'Сурамар навсегда останется нашим домом, но мои сородичи также хотят повидать мир и снова стать частью Азерота. Для этого нам нужны союзники.', 28153),
(142885, 'ruRU', '', 'Мы ценим союзников, но не забываем о своем прошлом.', 28153),
(142884, 'ruRU', '', 'Напротив, я лишь убедилась в том, что для тебя нет ничего важнее твоего народа. Даже присоединившись к Орде, вы сохранили свои традиции... а это очень важно для нас.', 28153),
(142883, 'ruRU', 'Сожалею, что тебе пришлось увидеть эту сцену. Она не входила в программу визита.', '', 28153),
(142882, 'ruRU', '', 'Как прикажете, лорд-регент.', 28153),
(142881, 'ruRU', 'Довольно! Аллерия, уходи немедленно. Твое присутствие представляет угрозу для Кель\'Таласа. Возвращайся в Штормград. В Луносвете тебе больше не место.', '', 28153),
(142880, 'ruRU', '', 'Никто не посмеет взять меня под стражу в родном доме.', 28153),
(142879, 'ruRU', 'Стража! Взять ее!', '', 28153),
(142878, 'ruRU', 'Солнечный Колодец в безопасности. Спасибо, Талисра. Спасибо вам всем.', '', 28153),
(142877, 'ruRU', 'Вы лишь оттягиваете неизбежное. Колодец будет моим.', '', 28153),
(142876, 'ruRU', '', 'Объедините свою силу с моей!', 28153),
(142875, 'ruRU', 'Врата открываются. Да... то, что нужно.', '', 28153),
(142874, 'ruRU', '', 'Скажи, что делать, и мы поможем тебе!', 28153),
(142873, 'ruRU', '', 'Я могу закрыть разлом, но одна я не справлюсь.', 28153),
(142872, 'ruRU', 'Что-то пытается прорваться сюда. Если это случится, мы можем потерять Солнечный Колодец.', '', 28153),
(142871, 'ruRU', 'Приступай, Рикал.', 'Приступай, Рикал.', 28153),
(142870, 'ruRU', 'Рано или поздно течение изменится. Так всегда бывает.', '', 28153),
(142869, 'ruRU', 'Ваша хватка слабеет!', '', 28153),
(142868, 'ruRU', '|TInterface\\Icons\\ABILITY_ROGUE_FANOFKNIVES:20|t%s готовится метнуть |cFFFF0000|Hspell:257785|h[мелькающие кинжалы]|h|r! Прячьтесь!', '', 28153),
(142867, 'ruRU', 'Бал-а даш, маланоре.', '', 28153),
(142866, 'ruRU', 'Каждый должен идти своим путем.', '', 28153),
(142865, 'ruRU', 'Будущее за нами.', '', 28153),
(142864, 'ruRU', 'Ничего не принимай на веру.', '', 28153),
(142863, 'ruRU', 'Вселенная полна загадок.', '', 28153),
(142862, 'ruRU', 'Перед нами открыты новые возможности.', '', 28153),
(142861, 'ruRU', 'Прошлое не изменить. А будущее – можно.', '', 28153),
(142860, 'ruRU', 'Шорель-аран.', '', 28153),
(142859, 'ruRU', 'Наш народ не боится теней.', '', 28153),
(142858, 'ruRU', 'У каждого своя правда.', '', 28153),
(142857, 'ruRU', 'Мы не подчиняемся голосам.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142856, 'ruRU', 'Держи свои чувства под контролем.', '', 28153),
(142855, 'ruRU', 'Не бойся силы. Используй ее.', '', 28153),
(142854, 'ruRU', 'Рассматривай все варианты.', '', 28153),
(142853, 'ruRU', 'Я не буду отвечать на эту провокацию.', '', 28153),
(142852, 'ruRU', '\"Помни о Солнечном Колодце\"? Нет, это в прошлом.', '', 28153),
(142851, 'ruRU', 'Если в моем присутствии тебя случайно затянет в портал в бесконечную пустоту, который внезапно откроется прямо под ногами, знай, что это просто совпадение. Такое бывает... иногда.', '', 28153),
(142850, 'ruRU', 'Стоило мне лишь немного измениться под действием космической энергии, которая, по слухам, приводит к потере разума, как меня сразу считают \"подозрительным\". А еще говорят, гномов дискриминируют...', '', 28153),
(142849, 'ruRU', 'Что тебя интересует?', '', 28153),
(142848, 'ruRU', 'Я предлагаю редкие товары из далеких земель.', '', 28153),
(142847, 'ruRU', 'Всему есть своя цена... вопрос лишь в готовности ее заплатить.', '', 28153),
(142846, 'ruRU', 'Надеюсь, покупка тебя не разочарует.', '', 28153),
(142845, 'ruRU', 'Спасибо. Приходи еще.', '', 28153),
(142844, 'ruRU', 'Заходи в любое время.', '', 28153),
(142843, 'ruRU', '', 'Заходи в любое время.', 28153),
(142842, 'ruRU', '', 'Спасибо. Приходи еще.', 28153),
(142841, 'ruRU', '', 'Надеюсь, покупка тебя не разочарует.', 28153),
(142840, 'ruRU', '', 'Всему есть своя цена... вопрос лишь в готовности ее заплатить.', 28153),
(142839, 'ruRU', '', 'Я предлагаю редкие товары из далеких земель.', 28153),
(142838, 'ruRU', '', 'Что тебя интересует?', 28153),
(142837, 'ruRU', '', 'Стоило мне лишь немного измениться под действием космической энергии, которая, по слухам, приводит к потере разума, как меня сразу считают \"подозрительной\". А еще говорят, гномов дискриминируют...', 28153),
(142836, 'ruRU', '', 'Если в моем присутствии тебя случайно затянет в портал в бесконечную пустоту, который внезапно откроется прямо под ногами, знай, что это просто совпадение. Такое бывает... иногда.', 28153),
(142835, 'ruRU', '', '\"Помни о Солнечном Колодце\"? Нет, это в прошлом.', 28153),
(142834, 'ruRU', '', 'Я не буду отвечать на эту провокацию.', 28153),
(142833, 'ruRU', '', 'Рассматривай все варианты.', 28153),
(142832, 'ruRU', '', 'Не бойся силы. Используй ее.', 28153),
(142831, 'ruRU', '', 'Держи свои чувства под контролем.', 28153),
(142830, 'ruRU', '', 'Мы не подчиняемся голосам.', 28153),
(142829, 'ruRU', '', 'У каждого своя правда.', 28153),
(142828, 'ruRU', '', 'Наш народ не боится теней.', 28153),
(142827, 'ruRU', '', 'Шорель-аран.', 28153),
(142826, 'ruRU', '', 'Прошлое не изменить. А будущее – можно.', 28153),
(142825, 'ruRU', '', 'Перед нами открыты новые возможности.', 28153),
(142824, 'ruRU', '', 'Вселенная полна загадок.', 28153),
(142823, 'ruRU', '', 'Ничего не принимай на веру.', 28153),
(142822, 'ruRU', '', 'Будущее за нами.', 28153),
(142821, 'ruRU', '', 'Каждый должен идти своим путем.', 28153),
(142820, 'ruRU', '', 'Бал-а даш, маланоре.', 28153),
(142819, 'ruRU', 'Этот монстр преграждает вам путь. Убейте его, иначе вы не доберетесь до наших лодок на том берегу.', '', 28153),
(142818, 'ruRU', 'У леди Эшвейн есть кракен?!', '', 28153),
(142817, 'ruRU', 'Похоже, Эшвейн открыла нам путь к отступлению. Пора уходить... А Боралус пусть горит.', '', 28153),
(142816, 'ruRU', 'Оружие этого монстра усилено азеритом.', '', 28153),
(142815, 'ruRU', 'Бал-а даш, маланоре.', '', 28153),
(142814, 'ruRU', 'Выбери свой путь.', '', 28153),
(142813, 'ruRU', 'Мы сражаемся за свое будущее.', '', 28153),
(142812, 'ruRU', 'Сомневайся во всем.', '', 28153),
(142811, 'ruRU', 'Вселенная полна загадок.', '', 28153),
(142810, 'ruRU', 'Приветствую тебя.', '', 28153),
(142809, 'ruRU', 'Для нас открыты новые пути.', '', 28153),
(142808, 'ruRU', 'Шорель-аран.', '', 28153),
(142807, 'ruRU', 'Даже во тьме есть сила.', '', 28153),
(142806, 'ruRU', 'Мы сами вершим свою судьбу.', '', 28153),
(142805, 'ruRU', 'Я не подчиняюсь голосам.', '', 28153),
(142804, 'ruRU', 'Никогда не теряй контроль над собой.', '', 28153),
(142803, 'ruRU', 'Не страшись силы. Управляй ею.', '', 28153),
(142802, 'ruRU', 'Этот корабль нагружен азеритом. Избавьтесь от экипажа, а я переправлю груз из города.', '', 28153),
(142801, 'ruRU', 'Бездна дает безграничные возможности.', '', 28153),
(142800, 'ruRU', 'Я не буду отвечать на эту провокацию.', '', 28153),
(142799, 'ruRU', '\"Помни о Солнечном Колодце\"? Нет, это в прошлом.', '', 28153),
(142798, 'ruRU', 'Если в моем присутствии тебя случайно затянет в портал в бесконечную пустоту, который внезапно откроется прямо под твоими ногами, знай, что это просто совпадение. Такое бывает... иногда.', '', 28153),
(142797, 'ruRU', 'Стоило мне лишь немного измениться под действием космической энергии, которая, по слухам, приводит к потере разума, как меня сразу считают \"подозрительным\". А еще говорят, гномов дискриминируют...', '', 28153),
(142796, 'ruRU', 'Что тебя интересует?', '', 28153),
(142795, 'ruRU', 'Я предлагаю редкие товары из далеких земель.', '', 28153),
(142794, 'ruRU', 'Всему есть своя цена... вопрос лишь в готовности ее заплатить.', '', 28153),
(142793, 'ruRU', 'Надеюсь, покупка тебя не разочарует.', '', 28153),
(142792, 'ruRU', 'Спасибо. Приходи еще.', '', 28153),
(142791, 'ruRU', 'Заходи в любое время.', '', 28153),
(142790, 'ruRU', 'Вы захватили достаточно азеритового оружия. Судьба Боралуса скоро постигнет весь Альянс.', '', 28153),
(142789, 'ruRU', '', 'Заходи в любое время.', 28153),
(142788, 'ruRU', '', 'Спасибо. Приходи еще.', 28153),
(142787, 'ruRU', '', 'Надеюсь, покупка тебя не разочарует.', 28153),
(142786, 'ruRU', '', 'Всему есть своя цена... вопрос лишь в готовности ее заплатить.', 28153),
(142785, 'ruRU', '', 'Я предлагаю редкие товары из далеких земель.', 28153),
(142783, 'ruRU', '', 'Что тебя интересует?', 28153),
(142782, 'ruRU', '', 'Стоило мне лишь немного измениться под действием космической энергии, которая, по слухам, приводит к потере разума, как меня сразу считают \"подозрительной\". А еще говорят, гномов дискриминируют...', 28153),
(142781, 'ruRU', '', 'Если в моем присутствии тебя случайно затянет в портал в бесконечную пустоту, который внезапно откроется прямо под ногами, знай, что это просто совпадение. Такое бывает... иногда.', 28153),
(142780, 'ruRU', '', '\"Помни о Солнечном Колодце\"? Нет, это в прошлом.', 28153),
(142779, 'ruRU', '', 'Я не буду отвечать на эту провокацию.', 28153),
(142778, 'ruRU', '', 'Бездна дает безграничные возможности.', 28153),
(142777, 'ruRU', '', 'Не страшись силы. Управляй ею.', 28153),
(142776, 'ruRU', '', 'Никогда не теряй контроль над собой.', 28153),
