(142081, 'ruRU', '', 'Высвобождая своего внутреннего демона, ты временно обретаешь чудовищную силу.', 28153),
(142080, 'ruRU', '', 'Атакуй манекен и используй \"Метаморфозу\".', 28153),
(142079, 'ruRU', '', 'Увидимся.', 28153),
(142078, 'ruRU', '', 'У нас каждый день новинки.', 28153),
(142077, 'ruRU', 'Атакуй манекен и используй \"Метаморфозу\".', '', 28153),
(142076, 'ruRU', 'Высвобождая своего внутреннего демона, ты временно обретаешь чудовищную силу.', '', 28153),
(142075, 'ruRU', 'У нас каждый день новинки.', '', 28153),
(142074, 'ruRU', 'Увидимся.', '', 28153),
(142073, 'ruRU', 'Приятно иметь с тобой дело.', '', 28153),
(142072, 'ruRU', 'До скорой встречи!', '', 28153),
(142071, 'ruRU', 'У меня лучшие товары в Крутогорье.', '', 28153),
(142070, 'ruRU', 'Выбирай, не торопись.', '', 28153),
(142069, 'ruRU', 'У меня есть все, что тебе нужно.', '', 28153),
(142068, 'ruRU', 'Хочешь что-нибудь купить?', '', 28153),
(142067, 'ruRU', 'Иди-ка ты в самую глубокую пещеру и заблудись там.', '', 28153),
(142066, 'ruRU', 'Продолжишь в том же духе – получишь ускорение копытом.', '', 28153),
(142065, 'ruRU', 'Кто с мечом на гору придет – тот с горы упадет. А падать долго.', '', 28153),
(142064, 'ruRU', 'Будешь меня доставать – получишь рогами.', '', 28153),
(142063, 'ruRU', 'Помни заветы Матери-Земли.', '', 28153),
(142062, 'ruRU', 'Пусть Луна и солнце осветят твой путь.', '', 28153),
(142061, 'ruRU', 'Оседлай ветер.', '', 28153),
(142060, 'ruRU', 'Да будут полноводными твои реки.', '', 28153),
(142059, 'ruRU', 'Ан\'ше укажет тебе путь.', '', 28153),
(142058, 'ruRU', 'Вместе мы – Крутогорье.', '', 28153),
(142057, 'ruRU', 'Берегись глубоких пещер.', '', 28153),
(142056, 'ruRU', 'Вместе мы защитим наш мир.', '', 28153),
(142055, 'ruRU', 'Мира тебе и терпения.', '', 28153),
(142054, 'ruRU', 'Мы не убоимся тьмы.', '', 28153),
(142053, 'ruRU', '', 'Отработай \"Удар Хаоса\" на манекене.', 28153),
(142052, 'ruRU', '', '\"Удар Хаоса\" передает твой гнев клинкам и усиливает атаку.', 28153),
(142051, 'ruRU', 'Иди, $p. А мне нужно позаботиться о брате.', '', 28153),
(142050, 'ruRU', 'Отработай \"Удар Хаоса\" на манекене.', '', 28153),
(142049, 'ruRU', '\"Удар Хаоса\" передает твой гнев клинкам и усиливает атаку.', '', 28153),
(142048, 'ruRU', '', 'Ты на позиции. Давай отработаем парочку опасных приемов.', 28153),
(142042, 'ruRU', '', 'Отработай \"Укус демона\" на манекене.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142041, 'ruRU', '', '\"Укус демона\" наносит урон и позволяет накопить гнев.', 28153),
(142040, 'ruRU', 'Отработай \"Укус демона\" на манекене.', '', 28153),
(142039, 'ruRU', '\"Укус демона\" наносит урон и позволяет накопить гнев.', '', 28153),
(142038, 'ruRU', 'Ты на позиции. Давай отработаем парочку опасных приемов.', '', 28153),
(142036, 'ruRU', '', 'Используй \"Рывок Скверны\", чтобы устремиться к манекену.', 28153),
(142035, 'ruRU', 'Что принесли ветра?', '', 28153),
(142034, 'ruRU', 'Река – источник жизни.', '', 28153),
(142033, 'ruRU', 'Приветствую тебя.', '', 28153),
(142032, 'ruRU', '', 'Благодаря своей ловкости ты и только ты решаешь, где и когда вступить в бой.', 28153),
(142031, 'ruRU', '', 'Иллидари-истребители жертвуют многим, чтобы овладеть нечистой силой демонов.', 28153),
(142030, 'ruRU', '', 'Иллидари-истребители жертвуют многим, чтобы овладеть нечистой силой демонов.', 28153),
(142029, 'ruRU', 'Крутогорье выстоит.', '', 28153),
(142028, 'ruRU', 'Иллидари-истребители жертвуют многим, чтобы овладеть нечистой силой демонов.', '', 28153),
(142027, 'ruRU', 'Используй \"Рывок Скверны\", чтобы устремиться к манекену.', '', 28153),
(142026, 'ruRU', 'Благодаря своей ловкости ты и только ты решаешь, где и когда вступить в бой.', '', 28153),
(142025, 'ruRU', 'Иллидари-истребители жертвуют многим, чтобы овладеть нечистой силой демонов.', '', 28153),
(142022, 'ruRU', 'Похоже, ты уже знаешь, как, принцесса.', '', 28153),
(142021, 'ruRU', '', 'Этот \"Г\'уун\" делает их сильнее... просто так нам не справиться. Нужно действовать иначе.', 28153),
(142020, 'ruRU', 'ЧТО?! Кажется, ты говорила, что эти тролли – кучка болотных дикарей!', '', 28153),
(142019, 'ruRU', 'Слушайте! Воззвание лорда Штормсонга ко всем верным последователям!', 'Слушайте! Воззвание лорда Штормсонга ко всем верным последователям!', 28153),
(142018, 'ruRU', 'Бригадир Скриппс выжил из ума! Они все из ума выжили!', 'Бригадир Скриппс выжил из ума! Они все из ума выжили!', 28153),
(142017, 'ruRU', 'А я уже собирался отдать концы!', 'А я уже собиралась отдать концы!', 28153),
(142016, 'ruRU', 'Они не отпускают нас домой!', 'Они не отпускают нас домой!', 28153),
(142015, 'ruRU', 'Да благословят тебя волны!', 'Да благословят тебя волны!', 28153),
(142014, 'ruRU', 'Тысяча благодарностей!', 'Тысяча благодарностей!', 28153),
(142013, 'ruRU', 'Големы вышли из-под контроля!', 'Големы вышли из-под контроля!', 28153),
(142012, 'ruRU', 'Хвала морям!', 'Хвала морям!', 28153),
(142011, 'ruRU', 'Слава волнам, море нас не оставило!', 'Слава волнам, море нас не оставило!', 28153),
(142007, 'ruRU', 'Ты еще... свое получишь...', 'Ты еще... свое получишь...', 28153),
(142006, 'ruRU', 'Нарушение... субор... динации...', 'Нарушение... субор... динации...', 28153),
(142004, 'ruRU', 'Все... вольно...', 'Все... вольно...', 28153),
(142003, 'ruRU', 'Мои питомцы проголодались.', '', 28153),
(142002, 'ruRU', 'Сокрушу!', '', 28153),
(142001, 'ruRU', 'Верните... мое тело... в море...', '', 28153),
(142000, 'ruRU', 'Как трудно... найти... хорошего бойца...', 'Как трудно... найти... хорошего бойца...', 28153),
(141999, 'ruRU', 'Тебя... за это... ждет выговор...', 'Тебя... за это... ждет выговор...', 28153),
(141998, 'ruRU', 'Твою...', 'Твою...', 28153),
(141997, 'ruRU', 'Море поглотит всех.', '', 28153),
(141996, 'ruRU', 'Это все... что ты можешь...', 'Это все... что ты можешь...', 28153),
(141995, 'ruRU', 'Бесполезный... червяк...', 'Бесполезный... червяк...', 28153),
(141994, 'ruRU', 'Я разрешил останавливаться?!', 'Я разрешила останавливаться?!', 28153),
(141993, 'ruRU', 'Растоптал!', '', 28153),
(141992, 'ruRU', 'Накажу тебя, чтоб другим неповадно было!', 'Накажу тебя, чтоб другим неповадно было!', 28153),
(141991, 'ruRU', 'Перерыв окончен, доходяга!', 'Перерыв окончен, доходяга!', 28153),
(141990, 'ruRU', 'Я покажу тебе, как нарушать дисциплину!', 'Я покажу тебе, как нарушать дисциплину!', 28153),
(141989, 'ruRU', 'Кто покинул строй?!', 'Кто покинул строй?!', 28153),
(141988, 'ruRU', 'Ты заплатишь за неподчинение!', 'Ты заплатишь за неподчинение!', 28153),
(141987, 'ruRU', 'Слишком глубоко для тебя.', '', 28153),
(141986, 'ruRU', 'Вернись в строй!', 'Вернись в строй!', 28153),
(141985, 'ruRU', 'Работай, червяк!', 'Работай, червяк!', 28153),
(141984, 'ruRU', 'Критический уровень энергии.', '', 28153),
(141983, 'ruRU', 'Требуется перезагрузка системы.', '', 28153),
(141982, 'ruRU', 'Вы упокоитесь в пучине!', '', 28153),
(141981, 'ruRU', 'Ошибка! Инородный предмет в порте А.', '', 28153),
(141980, 'ruRU', 'Механизмы отключены.', '', 28153),
(141979, 'ruRU', 'Протокол жатвы нарушен.', '', 28153),
(141978, 'ruRU', 'На дне увязнут ваши кости!', '', 28153),
(141977, 'ruRU', 'Целостность корпуса: 0%%.', '', 28153),
(141976, 'ruRU', 'Обнаружена утечка.', '', 28153),
(141975, 'ruRU', 'Отключение систем.', '', 28153),
(141974, 'ruRU', 'Обнаружен противник.', '', 28153),
(141973, 'ruRU', 'Активирую контрмеры.', '', 28153),
(141972, 'ruRU', 'Включаю жатвенные приводы.', '', 28153),
(141971, 'ruRU', 'Тревога! Посторонние!', '', 28153),
(141970, 'ruRU', 'Обнаружен посторонний.', '', 28153),
(141969, 'ruRU', 'Протокол нападения активирован.', '', 28153),
(141968, 'ruRU', 'Атакую.', '', 28153),
(141967, 'ruRU', 'Угроза обнаружена.', '', 28153),
(141966, 'ruRU', 'Артиллерия! Огонь по противнику!', '', 28153),
(141965, 'ruRU', 'Огонь по моей позиции!', '', 28153),
(141964, 'ruRU', 'Прилив накроет всех!', '', 28153),
(141963, 'ruRU', 'Готовься к смерти!', '', 28153),
(141962, 'ruRU', 'Я изрублю тебя на куски!', '', 28153),
(141961, 'ruRU', 'Отведайте стали!', '', 28153),
(141960, 'ruRU', 'Чего еще ожидать от Орды.', '', 28153),
(141959, 'ruRU', 'Никакой выправки!', '', 28153),
(141958, 'ruRU', 'Море примет твои кости!', '', 28153),
(141957, 'ruRU', 'Вы... не заслуживаете... победы...', '', 28153),
(141956, 'ruRU', 'Вам конец, ордынские отродья!', '', 28153),
(141955, 'ruRU', 'За Боралус!', '', 28153),
(141954, 'ruRU', 'Враги повсюду!', '', 28153),
(141953, 'ruRU', 'Берегись!', '', 28153),
(141952, 'ruRU', 'Сюда!', '', 28153),
(141951, 'ruRU', 'За мной!', '', 28153),
(141950, 'ruRU', '', 'Носи эти доспехи с честью, $p. Армия Света гордится тем, что ты состоишь в ее рядах.', 28153),
(141949, 'ruRU', '', 'Тебе удалось не просто послужить Альянсу, но также стать лучом Света во тьме и показать, чего стоят озаренные.', 28153),
(141948, 'ruRU', '', 'Встретимся на \"Виндикаре\". Пора вознаградить тебя за старания.', 28153),
(141947, 'ruRU', '', 'Твои заслуги впечатляют, $p. Я бы сама не справилась лучше. Хотя... Справилась бы, конечно. Но ненамного лучше.', 28153),
(141946, 'ruRU', 'Сейчас рванет!', '', 28153),
(141945, 'ruRU', 'Горите!', '', 28153),
(141944, 'ruRU', '', 'Для меня честь вручить тебе доспехи нашего народа. Они будут напоминать тебе о доме, куда бы ни завела дорога приключений.', 28153),
(141943, 'ruRU', '', '$p, в темные времена тебе удалось проявить храбрость и силу духа. Теперь Орда знает, чего стоит Крутогорье.', 28153),
(141942, 'ruRU', 'Насажу на крюк!', '', 28153),
(141941, 'ruRU', '', 'Теперь Громовой Тотем зовет тебя домой. Пришло время отблагодарить тебя за все.', 28153),
(141940, 'ruRU', '', 'Твое путешествие по Азероту было долгим, $p, и принесло Крутогорью славу.', 28153),
(141939, 'ruRU', 'Иди сюда!', '', 28153),
(141938, 'ruRU', 'Ты на очереди!', '', 28153),
(141937, 'ruRU', 'Не уйдешь!', '', 28153),
(141936, 'ruRU', 'Я сожру ваши кишки!', '', 28153),
(141935, 'ruRU', 'Камера СЕЛФИ получила фильтр Аргуса!', 'Камера СЕЛФИ получила фильтр Аргуса!', 28153),
(141934, 'ruRU', 'Камера СЕЛФИ получила фильтр Ледяной Скорби!', 'Камера СЕЛФИ получила фильтр Ледяной Скорби!', 28153),
(141933, 'ruRU', 'Камера СЕЛФИ получила фильтр ша!', 'Камера СЕЛФИ получила фильтр ша!', 28153),
(141932, 'ruRU', 'Камера СЕЛФИ получила фильтр Огненных Просторов!', 'Камера СЕЛФИ получила фильтр Огненных Просторов!', 28153),
(141931, 'ruRU', 'Камера СЕЛФИ получила сумеречный фильтр!', 'Камера СЕЛФИ получила сумеречный фильтр!', 28153),
(141930, 'ruRU', 'Меня... разделали...', '', 28153),
(141929, 'ruRU', 'Столько сочного мяса!', '', 28153),
(141928, 'ruRU', 'Пойдешь на корм рыбам!', '', 28153),
(141927, 'ruRU', '|TInterface\\Icons\\Ability_Argus_WastingPlague:20|tВы страдаете от |cFFFF0000|Hspell:248396|h[Изнуряющей чумы]|h|r!', '|TInterface\\Icons\\Ability_Argus_WastingPlague:20|tВы страдаете от |cFFFF0000|Hspell:248396|h[Изнуряющей чумы]|h|r!', 28153),
(141926, 'ruRU', 'Вот это я понимаю отбивная!', '', 28153),
(141925, 'ruRU', 'Разрублю на кусочки!', '', 28153),
(141924, 'ruRU', '<Рыбак заворожено смотрит в воду, бормоча что-то себе под нос. Его губы потрескались, его руки в крови, а тело покрыто мелкими ранами – вероятно, от когтей и клювов голодных птиц, в огромном количестве снующих над кромкой воды.\n\nКажется, он сидит тут уже много дней. \n\nОчевидно, это очередная жертва магии ведьм. В отличие от остальных, он может двигаться и разговаривать, но все же не поворачивается к вам, когда вы подходите ближе.>', '', 28153),
(141923, 'ruRU', 'Свежие туши.', '', 28153),
(141922, 'ruRU', '', 'Всегда оставайся собой. И, если соскучишься по дому, помни, что Крутогорье всегда ждет тебя.', 28153),
(141921, 'ruRU', '', 'Отправляйся в Оргриммар к нашим новым союзникам и узнай, за что они сражаются.', 28153),
(141920, 'ruRU', '', 'Сегодня начнется твое странствие, $p. Ты будешь представлять нас в землях, что лежат за горой.', 28153),
(141919, 'ruRU', '', 'Пришло время это изменить.', 28153),
(141918, 'ruRU', '', 'Сотни лет мы называли Расколотые острова своим домом. Мы мало знаем о том, что находится за их пределами.', 28153),
(141917, 'ruRU', 'Говорят, тут кругом шпионы! Что же мне делать?', 'Говорят, тут кругом шпионы! Что же мне делать?', 28153),
(141916, 'ruRU', '', 'И всегда следуй пути Света, $p.', 28153),
(141915, 'ruRU', '', 'Теперь ты отправишься в Штормград. Изучи Азерот. Познакомься с теми, кого мы поклялись защищать.', 28153),
(141914, 'ruRU', '', 'Но расслабляться нельзя. Одна война следует за другой – такова жизнь солдата.', 28153),
(141913, 'ruRU', '', 'Впервые за века мы видим небо, не омраченное безумием Легиона... и вновь ощущаем землю под копытами.', 28153),
(141912, 'ruRU', '', 'Тысячи лет озаренные сражались с демонами в Пустоте. \"Ксенодар\" был для нас единственным домом.', 28153),
(141911, 'ruRU', 'О, как раз вовремя, $n. Сейчас ты увидишь своими глазами, что значит стать озаренным. Начинайте, Фария.', '', 28153),
(141910, 'ruRU', '', 'Вы знаете, как я люблю ваши речи, но это не может подождать? Мы как раз собирались приступить к испытаниям.', 28153),
(141909, 'ruRU', 'Да. Верховный король согласен, чтобы Армия Света сражалась на стороне Альянса. Соберите войска, капитан. Я сообщу им об этом.', '', 28153),
(141908, 'ruRU', '', 'Не думала, что вы так скоро вернетесь, верховный экзарх. Встреча прошла успешно?', 28153),
(141905, 'ruRU', 'Аддингтон! Море милосердное...', '', 28153),
(141902, 'ruRU', 'Возвращайся в бездну, что тебя породила!', '', 28153),
(141901, 'ruRU', 'Тебе не место в Громовом Утесе!', '', 28153),
(141900, 'ruRU', 'Как же приятно снова взять в руки палицу!', '', 28153),
(141899, 'ruRU', 'Мы изгоним тьму из Мулгора!', '', 28153),
(141898, 'ruRU', 'За Альянс!', '', 28153),
(141897, 'ruRU', 'За Альянс!', '', 28153),
(141896, 'ruRU', 'И я не уверен, что это правильно.', '', 28153),
(141895, 'ruRU', 'Эти качества пригодятся в грядущей войне. Спасибо, $p. Без тебя этот союз был бы невозможен.', '', 28153),
(141894, 'ruRU', 'Тысячу лет я сражался в Пустоте плечом к плечу с этими дренеями. Во всей вселенной не найти более умелых и преданных солдат.', '', 28153),
(141893, 'ruRU', 'Мы рады приветствовать озаренных в наших рядах, верховный экзарх.', '', 28153),
(141892, 'ruRU', 'Верховный король Ринн, Армия Света поклялась защищать Альянс.', '', 28153),
(141891, 'ruRU', 'Лорд запретил нам проводить ритуалы поиска. Он строит новый флот.', '', 28153),
(141890, 'ruRU', 'Я пытался найти корабли, но мой взор застилает черная буря.', '', 28153),
(141889, 'ruRU', '', 'И найти его не получается?', 28153),
(141888, 'ruRU', 'Когда флот исчез, дом Штормсонгов изменился.', '', 28153),
(141887, 'ruRU', 'Одного из моих братьев... и, возможно, ответы.', '', 28153),
(141886, 'ruRU', '', 'Что вы рассчитываете там найти?', 28153),
(141885, 'ruRU', 'Берег мореходов неподалеку. Следуйте за мной.', '', 28153),
(141884, 'ruRU', 'Не вставать!', '', 28153),
(141883, 'ruRU', '', 'Никто из вас не вернется из Назмира. Бедный король потеряет дочь в этой глупой войне!', 28153),
(141882, 'ruRU', 'Приготовься, $n. В Назмире нас будут ждать только тролли крови и темное вуду.', '', 28153),
(141881, 'ruRU', '', 'Я не пущу их на корм троллям крови! Из Назмира никто не возвращается.', 28153),
(141880, 'ruRU', 'Но прежде чем ты отправишься в путь, позволь, я расскажу о трех следующих святилищах.', '', 28153),
(141879, 'ruRU', 'Эта страна называется Зандалар. Туда лучше плыть на корабле, это буквально на другом краю света.', '', 28153),
(141878, 'ruRU', 'Кажется, я знаю, где искать дальше... но это вражеская территория.', '', 28153),
(141877, 'ruRU', 'Пока тебя не было, я изучал журнал, стараясь понять, где искать остальные святилища.', '', 28153),
(141876, 'ruRU', '', 'С радостью, верховный экзарх.', 28153),
(141875, 'ruRU', 'А нам пора вернуться в Штормград. Фария, сообщи всем, что озаренные теперь сражаются за Альянс.', '', 28153),
(141874, 'ruRU', 'Т\'паартос немного... необычный. Но он послужит нашему делу.', '', 28153),
(141873, 'ruRU', 'Т\'паартос!', '', 28153),
(141872, 'ruRU', '', 'Фета тонес гамера. Да хранит нас Свет!', 28153),
(141871, 'ruRU', 'Сегодня ты стал озаренным.', '', 28153),
(141870, 'ruRU', 'Т\'паартос виноват.', '', 28153),
(141869, 'ruRU', 'Принюхивается к запаху у Вииз\'ки изо рта. Фу-у!', '', 28153),
(141868, 'ruRU', 'Это была лучшая ночь в нашей жизни! Жалко, я ничего не помню.\n\nЗато у нас на завтрак яйца динозавров!', '', 28153),
(141867, 'ruRU', 'Мы с темными охотниками двинемся вперед. А ты охраняй принцессу, $n.', '', 28153),
(141866, 'ruRU', 'Помнишь, что было прошлой ночью?\n\nВот и я тоже не помню.', '', 28153),
(141865, 'ruRU', 'Принцесса, Орда скоро пришлет подкрепление. Я не думаю, что нам стоит сейчас бросаться в бой.', '', 28153),
(141864, 'ruRU', 'Уф... пора бы начать... следить за здоровьем.', '', 28153),
(141863, 'ruRU', 'Ты иди. А я подлечусь и... Ох!.. Надо немного отдохнуть.', '', 28153),
(141862, 'ruRU', 'У нас мало времени! \n\nОрда скоро пришлет подкрепление, и нам нужен порт, чтобы его принять.', '', 28153),
(141861, 'ruRU', '', 'На этот раз их слишком много! Огонь!', 28153),
(141860, 'ruRU', 'Чтоб я знал.', '', 28153),
(141859, 'ruRU', '', 'Что здесь происходит, брат?', 28153),
(141858, 'ruRU', '', 'Граждане, расходитесь по домам!', 28153),
(141857, 'ruRU', 'Ты не получишь сокровище моего господина. Готовься к смерти, нарушитель!', '', 28153),
(141856, 'ruRU', 'Кто посмел сюда войти?!', '', 28153),
(141855, 'ruRU', '', 'Привлеки внимание людей, а я сделаю все остальное.', 28153),
(141852, 'ruRU', 'Страх... он преследовал Т\'паартоса повсюду!', '', 28153),
(141851, 'ruRU', 'Т\'паартос сожалеет, что назвал тебя малявкой, $p.', '', 28153),
(141850, 'ruRU', 'Т\'паартос не знает страха!', '', 28153),
(141849, 'ruRU', 'Сюда, скорее!', '', 28153),
(141848, 'ruRU', 'Берегись!', '', 28153),
(141847, 'ruRU', 'Сюда!', '', 28153),
(141846, 'ruRU', 'За мной!', '', 28153),
(141845, 'ruRU', 'Мы захватили азерит, а оставшаяся стража Эшвейнов сдалась. Тюрьма наша.', 'Мы захватили азерит, а оставшаяся стража Эшвейнов сдалась. Тюрьма наша.', 28153),
(141844, 'ruRU', 'Надеюсь, Корги дорого заплатил за свои зверства.', 'Надеюсь, Корги дорого заплатил за свои зверства.', 28153),
(141843, 'ruRU', 'Спасибо тебе!', 'Спасибо тебе!', 28153),
(141842, 'ruRU', 'Мы разобрались с заключенными и установили периметр. Нижние уровни под контролем.', 'Мы разобрались с заключенными и установили периметр. Нижние уровни под контролем.', 28153),
(141841, 'ruRU', '', 'Есть, верховный экзарх.', 28153),
(141840, 'ruRU', 'Фария, мне нужен маяк на \"Виндикар\".', '', 28153),
(141839, 'ruRU', 'Следуй за мной.', '', 28153),
(141838, 'ruRU', 'Как скажете, мой король.', '', 28153),
(141837, 'ruRU', 'Озаренные несомненно усилят Альянс. Туралион, отправляйтесь на \"Виндикар\" вместе и обратитесь к солдатам Армии Света.', '', 28153),
(141836, 'ruRU', '', 'Нравишься ты мне. Не останавливаешься на достигнутом, прямо как я, стремишься к совершенству.$B$BЯ даже и не знаю. Эта коробочка – настоящее чудо гоблинского инженерного дела. Безграничный потенциал, умещающийся на ладони.$B$BНайди какой-нибудь источник великой силы и... посмотри, что будет. Кто знает...', 28153),
(141835, 'ruRU', '', 'Нико, больше света! О, какое прелестное создание! Ты здесь впервые? Чем я могу помочь?', 28153),
(141834, 'ruRU', '', 'Понятия не имею. Эта штука устроена очень уж хитро. У нее вполне может найтись пара скрытых функций.$B$BПопробуй поднести ее к разным источникам великой силы. Там всегда что-то да происходит!', 28153),
(141833, 'ruRU', 'А что еще может эта камера?', 'А что еще может эта камера?', 28153),
(141832, 'ruRU', 'Я потерял свою камеру. Можешь сделать еще одну?', 'Я потеряла свою камеру. Можешь сделать еще одну?', 28153),
(141831, 'ruRU', '', 'Самовзводный Единственно Логичный Фиксатор Изображений.', 28153),
(141830, 'ruRU', 'Как расшифровывается \"СЕЛФИ\"?', 'Как расшифровывается \"СЕЛФИ\"?', 28153),
(141829, 'ruRU', '', 'Ой, привет! Хочешь сделать со мной СЕЛФИ?', 28153),
(141828, 'ruRU', 'Мы требуем ответов, Пайк!', 'Мы требуем ответов, Пайк!', 28153),
(141827, 'ruRU', 'Слишком заняты – отнимают урожай \"для солдат\"!', 'Слишком заняты – отнимают урожай \"для солдат\"!', 28153),
(141826, 'ruRU', 'Где ополчение? Где патрули?', 'Где ополчение? Где патрули?', 28153),
(141825, 'ruRU', 'На Подгород напали! Скорее, беги к порталу!', 'На Подгород напали! Скорее, беги к порталу!', 28153),
(141824, 'ruRU', 'Неужели мы должны все бросить и бежать в Оргриммар?', 'Неужели мы должны все бросить и бежать в Оргриммар?', 28153),
(141823, 'ruRU', 'Что происходит? Почему вдруг начали закрывать ворота?', 'Что происходит? Почему вдруг начали закрывать ворота?', 28153),
(141822, 'ruRU', 'Безопасно, небезопасно – я не собираюсь терять все нажитое из-за этой войны!', 'Безопасно, небезопасно – я не собираюсь терять все нажитое из-за этой войны!', 28153),
(141821, 'ruRU', 'Надо найти моих друзей!', 'Надо найти моих друзей!', 28153),
(141820, 'ruRU', 'Мама говорила, что солдаты всегда прогоняли врагов! Но где солдаты?', 'Мама говорила, что солдаты всегда прогоняли врагов! Но где солдаты?', 28153),
(141819, 'ruRU', 'Я так испугался! Спасибо тебе!', 'Я так испугалась! Спасибо тебе!', 28153),
(141818, 'ruRU', 'Я хочу к папе!', 'Я хочу к папе!', 28153),
(141817, 'ruRU', 'Где же ополчение?', 'Где же ополчение?', 28153),
(141816, 'ruRU', 'Я спасен. Спасибо!', 'Я спасена. Спасибо!', 28153),
(141815, 'ruRU', 'На нас еще ни разу не нападали такими силами!', 'На нас еще ни разу не нападали такими силами!', 28153),
(141814, 'ruRU', 'Дальше я сам. Надеюсь, остальные в безопасности!', 'Дальше я сама. Надеюсь, остальные в безопасности!', 28153),
(141813, 'ruRU', 'Я... не могу сказать. Майла, мы с тобой пойдем вперед. Бейн, вы вдвоем должны собрать остальных. Встретимся на вершине.', '', 28153),
(141812, 'ruRU', 'Тьмы... О чем это он?', '', 28153),
(141811, 'ruRU', 'Да... Твоя сила станет нашей, дитя тьмы!', '', 28153),
(141810, 'ruRU', 'Последний идол находился на вершине горы. Мы отправимся туда и сразимся с тьмой вместе, как Халн и его союзники.', '', 28153),
(141809, 'ruRU', 'Верно. Когда я покинул гору и отправился в Мулгор, идолы ослабели настолько, что Мрак вырвался.', '', 28153),
(141808, 'ruRU', '', 'Все это время Культ Смерти скрывался в тени. Они ждали, когда хозяин вновь призовет их.', 28153),
(141807, 'ruRU', 'Тогда Халн установил идолы, чтобы защитить Крутогорье от Древних богов. И хотя Уул\'гинет выжил, его сущность оказалась в ловушке.', '', 28153),
(141806, 'ruRU', 'Халн собрал лучших героев из всех наших племен. Они сражались против слуг Уул\'гинета, Культа Смерти... Но силы были неравны.', '', 28153),
(141805, 'ruRU', 'Давным-давно Древние боги решили захватить Крутогорье. Их армию вело кошмарное создание... Уул\'гинет Мрак.', '', 28153),
(141804, 'ruRU', '', 'Но это еще не все. Смоляной Рог, мы должны понять, чего хочет Мрак.', 28153),
(141803, 'ruRU', 'Серое Небо тебя очень хвалил.', '', 28153),
(141802, 'ruRU', 'Я вновь обрел разум. Возвращайся в Громовой Тотем. Мы должны приготовиться к битве с тьмой.', '', 28153),
(141801, 'ruRU', '', 'Я слышу наших. Мы уже близко.', 28153),
(141800, 'ruRU', '', 'С тобой пойдет Серое Небо. Надеюсь, восстановление идолов спасет Смоляного Рога.', 28153),
(141799, 'ruRU', '', 'Вода успокоила Смоляного Рога. Но, боюсь, мы его теряем.', 28153),
(141798, 'ruRU', 'Отправляйся в Крутогорье и помоги Майле. Я прибуду позже.', '', 28153),
(141797, 'ruRU', 'Я должен убедиться, что слуги Древних богов не грозят Мулгору.', '', 28153),
(141796, 'ruRU', 'Твои хозяева не получат мой город!', '', 28153),
(141795, 'ruRU', 'Убейте их! Не дайте им сорвать мое возвращение!', '', 28153),
(141794, 'ruRU', '', 'Если тролли крови освободят это чудовище, они станут непобедимы... Нам нужен новый план. Вас с Ордой будет мало.', 28153),
(141793, 'ruRU', '', 'Они возвращаются... похоже, мы в безопасности.', 28153),
(141792, 'ruRU', 'Хорошо. А мы пока избавимся от гнили Древних богов.', '', 28153),
(141791, 'ruRU', '', 'Я поняла. Бейн, я должна доставить Смоляного Рога в Крутогорье.', 28153),
(141790, 'ruRU', 'Майла... вода...', '', 28153),
(141789, 'ruRU', '', 'Я не боюсь ни тебя, ни твоих монстров. Я убью вас всех!', 28153),
(141788, 'ruRU', '', 'Беги, принцесска! Тебе не спастись от хозяина! Г\'уун сожрет тебя!', 28153),
(141787, 'ruRU', '', 'Погнали! Держись крепче!', 28153),
(141786, 'ruRU', '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|tКоролева песков впадает в |cFFFF0000|Hspell:257609|h[бешенство]|h|r!', '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|tКоролева песков впадает в |cFFFF0000|Hspell:257609|h[бешенство]|h|r!', 28153),
(141784, 'ruRU', 'Идолы слабеют! Он будет нашим!', '', 28153),
(141783, 'ruRU', 'Вместе мы вернемся в море. Вместе мы обретем былое величие!', '', 28153),
(141782, 'ruRU', 'Повелевая силами волн, наши могучие жрецы моря приведут нас к победе.', '', 28153),
(141781, 'ruRU', 'Мы должны сплотиться и собрать свою армию. Кул-Тирас будет принадлежать народу!', '', 28153),
(141780, 'ruRU', 'Дом Штормсонгов должен возглавить наше раздробленное королевство и вернуть ему славу!', '', 28153),
(141779, 'ruRU', 'Мы больше не будем безропотно отдавать урожай и строить корабли для чванливых дворян из Боралуса.', '', 28153),
(141778, 'ruRU', 'Дети моря, сегодня мы встречаем рассвет новой эпохи.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141777, 'ruRU', 'Если бы ты видел то же, что я, – делал бы так же. Заходи, сейчас поймешь!', '', 28153),
(141776, 'ruRU', '|TInterface\\Icons\\ACHIEVEMENT_ZONE_VASHJIR:20|tГолганнет выбрал вас для получения |cFFFF0000|Hspell:257306|h[Дара моря]|h|r!', '|TInterface\\Icons\\ACHIEVEMENT_ZONE_VASHJIR:20|tГолганнет выбрал вас для получения |cFFFF0000|Hspell:257306|h[Дара моря]|h|r!', 28153),
(141775, 'ruRU', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_AIR:20|tГолганнет выбрал вас для получения |cFFFF0000|Hspell:257313|h[Дара небес]|h|r!', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_AIR:20|tГолганнет выбрал вас для получения |cFFFF0000|Hspell:257313|h[Дара небес]|h|r!', 28153),
(141774, 'ruRU', 'Недостаточно энергии.', '', 28153),
(141773, 'ruRU', 'Система наведения от... отказывает...', '', 28153),
(141772, 'ruRU', 'Запас здоровья на исходе. Нужна помощь.', '', 28153),
(141771, 'ruRU', 'Неисправность!', '', 28153),
(141770, 'ruRU', '', 'Золотое святилище? Я думаю, имеется в виду Атал\'Дазар. Это такой город. Из золота. Золотой город.$b$bНо... святилище? Только если ты поклоняешься золоту. Или динозаврам. Или позолоченным динозаврам!$b$bВ общем, я бы начала оттуда!', 28153),
(141769, 'ruRU', 'Похоже, их потащили вон туда, по леднику на северо-запад.', '', 28153),
(141768, 'ruRU', 'Как ты думаешь, что такое \"Золотое святилище\"?', 'Как ты думаешь, что такое \"Золотое святилище\"?', 28153),
(141767, 'ruRU', 'Найдите, где они прячутся, выманите их из укрытия и убейте. А горожан эвакуируйте в Оргриммар.', '', 28153),
(141766, 'ruRU', 'Мы загнали лазутчиков в квартал магов и перекрыли остальные районы.', '', 28153),
(141765, 'ruRU', 'Наши враги напали на Подгород и хотят захватить Лордерон.', '', 28153),
(141764, 'ruRU', 'Для горожан здесь становится слишком опасно. Наверху идет бой, а среди нас скрываются шпионы.', '', 28153),
(141762, 'ruRU', 'Слушайте меня, защитники Орды!', '', 28153),
(141761, 'ruRU', '', 'Когда попадете в Оргриммар, собирайтесь на Аллее Чести. Здесь небезопасно!', 28153),
(141760, 'ruRU', '', 'Мой портал открыт, надо эвакуироваться!', 28153),
(141759, 'ruRU', '', 'Скорее в Оргриммар! Здесь небезопасно!', 28153),
(141758, 'ruRU', 'Какой... выстрел...', '', 28153),
(141757, 'ruRU', 'Можешь бежать! Я никогда не промахиваюсь!', '', 28153),
(141756, 'ruRU', 'Вам не спастись от перекрестного огня!', '', 28153),
(141755, 'ruRU', 'Давно хотел опробовать эти патроны на живых мишенях.', '', 28153),
(141754, 'ruRU', 'Зачту вам хорошее поведение.', '', 28153),
(141753, 'ruRU', 'Как тебе свинец на последний ужин?', '', 28153),
(141752, 'ruRU', 'Смертный приговор!', '', 28153),
(141751, 'ruRU', 'Как мило, что вы вернулись на свою казнь.', '', 28153),
(141750, 'ruRU', 'Отправляю новые бомбы.', '', 28153),
(141749, 'ruRU', 'Есть, мэм!', '', 28153),
(141748, 'ruRU', '', 'Пусть пламя разгорится ярче!', 28153),
(141747, 'ruRU', '', 'Еще! Огонь должен гореть сильнее!', 28153),
(141746, 'ruRU', '', 'Я обращу вас в пепел!', 28153),
(141745, 'ruRU', '', 'Сгиньте в огне!', 28153),
(141744, 'ruRU', '', 'Добавим жару!', 28153),
(141743, 'ruRU', 'Кто обидел моего друга?!', '', 28153),
(141742, 'ruRU', '', 'Яркие звезды... гаснут... первыми.', 28153),
(141741, 'ruRU', 'Ты за все заплатишь!', '', 28153),
(141740, 'ruRU', 'Не давай им опомниться, здоровяк! А я их подрежу.', '', 28153),
(141739, 'ruRU', '', 'Нужно найти это оружие прежде, чем оно окажется в руках Джакра\'зета.', 28153),
(141738, 'ruRU', '', 'Понятия не имею, что это за оружие и где его искать, но Джакра\'зет не просто так скрывает поиски от короля.', 28153),
(141737, 'ruRU', '', 'Они прочесывают дюны в поисках оружия, которое способно уничтожить наш город.', 28153),
(141736, 'ruRU', '', 'Все оказалось как я думала. Генерал отправлял войска в пустыню тайком от короля.', 28153),
(141735, 'ruRU', 'Просеивание', 'Просеивание', 28153),
(141734, 'ruRU', 'А то как же! Иди сюда, у меня есть для тебя одно дело.', '', 28153),
(141733, 'ruRU', 'Эй, Ральф! Тут кое-кто неплохо справляется! У тебя есть работенка?', '', 28153),
(141732, 'ruRU', '', 'Люблю пузыри. В них я чувствую себя в безопасности.', 28153),
(141731, 'ruRU', 'Подумать только, существуют города, не защищенные магическими барьерами! Как там вообще живут? В город же попадает пыль! Дикари!', '', 28153),
(141730, 'ruRU', '', 'Я думала, что больше никогда ее не увижу...', 28153),
(141729, 'ruRU', 'Память возвращается – и боль вместе с ней...', '', 28153),
(141728, 'ruRU', '', 'Что, слишком горячо для тебя?', 28153),
(141727, 'ruRU', '', 'Твоя плоть пылает!', 28153),
(141726, 'ruRU', '', 'Ваши трупы – прекрасное топливо.', 28153),
(141725, 'ruRU', '', 'Огонь расплавит вас.', 28153),
(141724, 'ruRU', '', '$p, скорее, сюда! К Ракире возвращается память!', 28153),
(141723, 'ruRU', 'Это... должна была быть... ваша кровь...', '', 28153),
(141722, 'ruRU', '', 'Моя голова... Каджа, это ты?', 28153),
(141721, 'ruRU', 'Время охоты!', '', 28153),
(141720, 'ruRU', 'Вы убили моего братишку. Я вас на куски разорву.', '', 28153),
(141719, 'ruRU', 'Братишка!', '', 28153),
(141718, 'ruRU', 'Сюда, братишка! Время убивать.', '', 28153),
(141717, 'ruRU', 'Вперед, ребята! Покажем, кто тут главный!', '', 28153),
(141716, 'ruRU', 'Я наточил клинки специально для вас.', '', 28153),
(141715, 'ruRU', 'Я... мог выйти... досрочно...', '', 28153),
(141714, 'ruRU', 'Сидели бы лучше по камерам.', '', 28153),
(141713, 'ruRU', 'Отправь меня в Ульдуар (рейд в режиме путешествий во времени).', 'Отправь меня в Ульдуар (рейд в режиме путешествий во времени).', 28153),
(141712, 'ruRU', '', 'Приветствую, $n. Ты, возможно, меня не помнишь – мы встречались на следующей неделе.$b$bХочешь вернуться в Ульдуар?', 28153),
(141711, 'ruRU', 'Я тут альфа!', '', 28153),
(141710, 'ruRU', 'Рубленое мясо.', '', 28153),
(141709, 'ruRU', 'Свежее мясо!', '', 28153),
(141708, 'ruRU', 'Утомите грифона быстрым полетом. Не забывайте поддерживать эффект |TInterface\\ICONS\\INV_MISC_DESECRATED_LEATHERGLOVE.BLP:20|t |cFFFF0000|Hspell:269442|h[Крепкая хватка]|h|r!', '', 28153),
(141707, 'ruRU', 'Я готов.', 'Я готова.', 28153),
(141706, 'ruRU', '', 'Пора приступать к делу.', 28153),
(141705, 'ruRU', '', 'Опасность позади. Как доплывем до руин Зул\'джана – не зевайте.', 28153),
(141704, 'ruRU', '', 'Тролли крови не знают страха и устали под влиянием Древнего бога.', 28153),
(141703, 'ruRU', '', 'Зришь в корень, Патч. Ты уж точно прозорливее моего отца.', 28153),
(141701, 'ruRU', '', 'Мертвяки! Они движутся в сторону Зулдазара. Уничтожим их!', 28153),
(141696, 'ruRU', 'Кажется, талисман не действует. Испытай его сначала на сотворенных проклятием рабах.', '', 28153),
(141695, 'ruRU', 'Этот малый не особо смышленый.', '', 28153),
(141694, 'ruRU', 'Фартохвост бежит к водопадам!', '', 28153),
(141693, 'ruRU', '', '', 28153),
(141692, 'ruRU', '|cffffff00+$1i ед. металлолома|r', '|cffffff00+$1i ед. металлолома|r', 28153),
(141691, 'ruRU', 'Фартохвост убегает в безопасное место!', '', 28153),
(141690, 'ruRU', '', 'Что эти сектанты сделали с Ракирой?.. Она не помнит даже своего имени.', 28153),
(141689, 'ruRU', 'Ты! Да, ты. Подойди, только тихо. Не привлекай внимания.', '', 28153),
(141688, 'ruRU', '', 'Что с тобой сделали?..', 28153),
(141687, 'ruRU', '', 'Мы все – Акунда.', 28153),
(141686, 'ruRU', '', 'Ракира?', 28153),
(141685, 'ruRU', '', 'Она здесь. Она жива! Ракира!', 28153),
(141684, 'ruRU', '', 'Ракира!', 28153),
(141683, 'ruRU', '', 'В этом странном храме должен быть кто-то, кто сможет нам помочь.', 28153),
(141682, 'ruRU', 'Мне все равно, о чем ты там надеешься договориться с королем и его дочерью. Знай, что в Зулдазаре тебе не рады.$b$bИ хотя влияние принцессы велико, она еще не королева.$b$bПока Таланджи не взошла на трон, настоящая власть в Зулдазаре принадлежит мне и Совету Занчули.', '', 28153),
(141681, 'ruRU', '', 'Тихо! Это официальная церемония.', 28153),
(141680, 'ruRU', 'Т\'паартос это понял.', '', 28153),
(141679, 'ruRU', 'В каждом из нас есть частица тьмы. И справиться с ней нелегко.', '', 28153),
(141678, 'ruRU', '', 'Т\'паартос... Ты преодолел свои страхи... и переродился.', 28153),
(141677, 'ruRU', '', 'С возвращением, Т\'паартос.', 28153),
(141676, 'ruRU', '', 'Если Ракира в этом храме, мы найдем ее.', 28153),
(141675, 'ruRU', 'Вы вонючки!', '', 28153),
(141674, 'ruRU', 'Жаль, что вы пахнете, как гуано!', '', 28153),
(141673, 'ruRU', 'Крагг мертв. Живцу жаль!', '', 28153),
(141672, 'ruRU', '', 'А, кто-то из Орды. Любопытно...', 28153),
(141671, 'ruRU', '$n атакует силы Альянса на лесопилке!', '$n атакует силы Альянса на лесопилке!', 28153),
(141669, 'ruRU', '', 'Даже ветер здесь полон силы лоа. Где-то в этих небесах парит Па\'ку, я чувствую ее присутствие.$b$bРаньше я никогда не бывала в Зандаларе, но мой дедушка много рассказывал мне о нем.', 28153),
(141668, 'ruRU', '', 'Лоа здесь очень сильны. Я чувствую присутствие своего лоа Гонка – словно он прячется за каждым деревом и кустом.$b$bГонк близко. Здорово будет увидеть его своими глазами.', 28153),
(141667, 'ruRU', 'Мы так просто не сдадимся. Воины – отбейте нашу лесопилку!', '', 28153),
(141666, 'ruRU', 'Приветствую тебя!$b$bЯ верховный ведун Раал, глава тех, кто заботится о благосклонности Па\'ку, лоа ветров. А еще я вхожу в Совет Занчули.$b$bУ меня очень важная работа, и я очень занят. Что тебе нужно?', '', 28153),
(141665, 'ruRU', '', 'У нас не так много времени, чтобы поговорить с верховным ведуном. Не мешай. Нам нужно многое обсудить.', 28153),
(141664, 'ruRU', 'Дружище!', '', 28153),
(141663, 'ruRU', '', 'Мы заставим сетраков бояться вульпер!', 28153),
(141662, 'ruRU', 'Кажется, этот выскочка генерал Джакра\'зет – тролль из племени Песчаной Бури, командующий войсками Зулдазара – решил отозвать охрану из гавани.\n\nВидимо, не все тролли одобряют указ принцессы Таланджи, по которому туда теперь допускаются другие существа. \n\nЕй понадобится поддержка хотя бы кого-то одного из Совета Занчули. К счастью, я знаю, где сейчас двое из советников.', '', 28153),
(141660, 'ruRU', '', 'Они считают, что вульперы слабы? Скоро их ждет сюрприз!', 28153),
(141658, 'ruRU', 'Иссушение', 'Иссушение', 28153),
(141657, 'ruRU', '', 'Сетраки заплатят за то, что сделали с нашим домом.', 28153),
(141655, 'ruRU', 'Нет, не волнуйся за меня... ик... я, пожалуй, пойду... э... а где же это я?$b$bСлушай, просто дай мне тут протрезветь немного, а когда ты... ик... вернешься, меня уже и след простынет. Даю слово.', '', 28153),
(141654, 'ruRU', 'Ха-ха, а это самое смешное. Слушай, он взял и... ик... попался! Глупый негодяй пытался кого-то прикончить.$b$bТеперь он в тюрьме со всеми остальными отбросами... ик... Если камень еще у него, готов... ик... поспорить, что расстанется он с ним не раньше, чем с... ик... жизнью.$b$bСкажи, а ты часом не собираешься и меня убить? Ик... я же тебе ничего не сделал.$b$bСлушай, я просто пойду куда-нить и... ик... протрезвлюсь. Слово моряка... ха-ха!', '', 28153),
(141653, 'ruRU', 'Где тот, кто украл бриллиант?', 'Где тот, кто украл бриллиант?', 28153),
(141652, 'ruRU', 'Этот прохвост украл наш... ик... бриллиант. Столько времени потратили, вырезая этот дурацкий камень... И что же он сделал? Ик...$b$bПросто сбежал посреди... ик... ночи. Мы же хотели продать эту штуку и жутко разбогатеть! Ик...$b$b<Солтон делает еще один глоток из своей фляжки.>$b$bСкажи, а у тебя случайно нет с собой денег?', '', 28153),
(141651, 'ruRU', '', 'Я готова. Давай поохотимся на сетраков.', 28153),
(141649, 'ruRU', 'Принцесса Таланджи говорит, ей нужна твоя помощь, чтобы справиться с Джакра\'зетом.', 'Принцесса Таланджи говорит, ей нужна твоя помощь, чтобы справиться с Джакра\'зетом.', 28153),
(141648, 'ruRU', '', 'Перед тобой боевой друид Лоти, преданная Гонку, непревзойденная охотница и искусный следопыт. Что тебе нужно, |3-6($c)?', 28153),
(141647, 'ruRU', 'Заводите пилы! Нам нужно больше древесины.', '', 28153),
(141646, 'ruRU', 'О, боюсь, с этим у нас проблема. Джакра\'зет отказывается исполнять волю принцессы.$b$bМне нужна помощь еще одного члена Совета Занчули, но те двое, что сейчас здесь, заняты – улаживают племенной спор.$b$bОтправляйся в Тал\'аман или Тал\'фаррак и попробуй уговорить кого-то из них помочь нам.$b$bЯ бы сам пошел, но у меня слишком важная должность для таких дел.', '', 28153),
(141645, 'ruRU', 'Принцесса Таланджи спрашивает, где стража.', 'Принцесса Таланджи спрашивает, где стража.', 28153),
(141644, 'ruRU', 'Когда я увидел тебя в Штормграде, то сразу понял, что пророчество начинает сбываться.$b$bДухи посылают мне много видений, и в этих видениях ты среди важнейших участников будущих великих событий.$b$bМир готовится к переменам, |3-6($c). Скоро мы с тобой потрясем его до основания.', '', 28153),
(141643, 'ruRU', 'И тебе советую поступить так же. Удачи.', 'И тебе советую поступить так же. Удачи.', 28153),
(141642, 'ruRU', 'Да... сдавайся, Т\'паартос. Прими эту силу!', '', 28153),
(141641, 'ruRU', 'Сбрось оковы Света! Не сдерживай себя.', '', 28153),
(141640, 'ruRU', 'Свет не даст тебе ничего подобного.', '', 28153),
(141639, 'ruRU', 'Нас ждет такая сила, Т\'паартос.', '', 28153),
(141638, 'ruRU', 'Свет всегда направлял Т\'паартоса! Т\'паартос НИКОГДА не оставит Свет!', '', 28153),
(141637, 'ruRU', 'ХВАТИТ!!!', '', 28153),
(141636, 'ruRU', 'Нет...', '', 28153),
(141635, 'ruRU', 'Нет... неправда. Это ненастоящий Т\'паартос!', '', 28153),
(141634, 'ruRU', 'А-а-а! $p, ты можешь прогнать этих змей?', '', 28153),
(141633, 'ruRU', 'Т\'паартосу... немного неловко.', '', 28153),
(141632, 'ruRU', 'Т\'паартос может свернуть горы!', '', 28153),
(141631, 'ruRU', 'Т\'паартос уже бился с такими тварями в Армии Света.', '', 28153),
(141630, 'ruRU', 'Ика... Маму этого элекка убили, и Т\'паартос его вырастил.', '', 28153),
(141629, 'ruRU', 'Нет! Тьма не заберет Т\'паартоса!', '', 28153),
(141628, 'ruRU', 'Это ли путь Т\'паартоса? Достоин ли Т\'паартос стать озаренным?', '', 28153),
(141623, 'ruRU', 'И снова ты меня спасаешь! Пойду обратно в лагерь, пока не простудился.', '', 28153),
(141620, 'ruRU', '', 'Не убивай их без меня!', 28153),
(141619, 'ruRU', '', 'Вульперы готовы. Отступники еще будут нас бояться.', 28153),
(141618, 'ruRU', 'Мм-м... вот поймаю тебя... мм-м...', '', 28153),
(141617, 'ruRU', 'Я хотел потратить золото на свою свадьбу <всхлипывает>.', '', 28153),
(141616, 'ruRU', 'Как доберусь до... ик... лодки... Я тебе покажу!', '', 28153),
(141615, 'ruRU', 'Верни наш бриллиант, ты, жалк-ик-кое отродье!', '', 28153),
(141614, 'ruRU', 'Это у тебя наш... ик...', '', 28153),
(141613, 'ruRU', 'Больше не позволю Нише придумывать планы...', '', 28153),
(141612, 'ruRU', '', 'Вряд ли. Для большинства из вас пустыня – это смерть. По крайней мере, теперь.', 28153),
(141611, 'ruRU', 'Осторожнее, Миира, древние тролльские дороги плохо подходят для наших повозок.', '', 28153),
(141610, 'ruRU', '', 'Сетраки еще пожалеют, что напали на наш караван.', 28153),
(141609, 'ruRU', 'Тяните за веревки! Не давать слабину!', '', 28153),
(141608, 'ruRU', '', 'Держи, $n. Это перевод твоих записок. Довольно увлекательное чтиво, мне кажется.', 28153),
(141607, 'ruRU', '', 'Да? Да! Точно! А где же мои чистые книги... А, вот одна.', 28153),
(141606, 'ruRU', '', 'Ой! Так вот что означает эта руна. Любопытно...', 28153),
(141605, 'ruRU', '', 'Тебе удалось найти их всех? Отличная работа, $n. Начинаю переводить записки.', 28153),
(141604, 'ruRU', '<Солдат неразборчиво бормочет себе под нос.>', '<Воительница неразборчиво бормочет себе под нос.>', 28153),
(141603, 'ruRU', 'Вот книги, которые тебе были нужны.', 'Вот книги, которые тебе были нужны.', 28153),
(141602, 'ruRU', 'Это вода поднимается или мы опускаемся?\n\nВсе глубже и глубже...', 'Это вода поднимается или мы опускаемся?\n\nВсе глубже и глубже...', 28153),
(141601, 'ruRU', 'Идеально, идеально, сказано, что все должно быть идеально...\n\nНо где сказано?', 'Идеально, идеально, сказано, что все должно быть идеально...\n\nНо где сказано?', 28153),
(141600, 'ruRU', 'Зандаларов скоро ждет большой сюрприз!', 'Зандаларов скоро ждет большой сюрприз!', 28153),
(141599, 'ruRU', 'Кроги растут хорошо. Скоро на них можно будет ездить.', 'Кроги растут хорошо. Скоро на них можно будет ездить.', 28153),
(141598, 'ruRU', 'Прости, ма\'да. Сейчас я уступлю тебе дорогу.', 'Прости, ма\'да. Сейчас я уступлю тебе дорогу.', 28153),
(141597, 'ruRU', 'Лучше наточи нож как следует. Говорят, скоро мы пойдем драться с зандаларами.', 'Лучше наточи нож как следует. Говорят, скоро мы пойдем драться с зандаларами.', 28153),
(141596, 'ruRU', 'Вождь Сильвана Ветрокрылая, представляю вам Майлу Крутогор.', '', 28153),
(141595, 'ruRU', 'Один из наших рюкзаков. Думаю, мы нашли то самое место.', '', 28153),
(141594, 'ruRU', 'О, этот топор из наших. Мы на верном пути.', '', 28153),
(141593, 'ruRU', 'Бедняга умер уже давно. Давай поищем повозку к востоку отсюда.', '', 28153),
(141592, 'ruRU', 'Я тебя здесь раньше не видел. Лучше заходи поскорее. Говорят, всех, кто был в отряде Наджимы, нашли мертвыми.', 'Я тебя здесь раньше не видела. Лучше заходи поскорее. Говорят, всех, кто был в отряде Наджимы, нашли мертвыми.', 28153),
(141591, 'ruRU', 'Последний идол был установлен на вершине Крутогорья. Туда мы и должны отправиться. И встать плечом к плечу, как Халн и его союзники.', '', 28153),
(141590, 'ruRU', 'Да. И когда я спустился с горы, чтобы отправиться в Мулгор, идолы чуть ослабли – но этого оказалось достаточно, чтобы Мрак сумел сбросить оковы.', '', 28153),
(141589, 'ruRU', '', 'Выходит, Культ Смерти скрывался во тьме, ожидая подходящего момента.', 28153),
(141588, 'ruRU', 'И тогда Халн придумал другой план. Идолы должны были защитить Крутогорье от Древних богов. И хотя генерал Уул\'гинет выжил, его сущность была заперта.', '', 28153),
(141587, 'ruRU', 'Халн собрал лучших героев племен, чтобы вместе дать врагу отпор. Они сражались с некротемными, слугами Уул\'гинета... но силы были неравны.', '', 28153),
(141586, 'ruRU', 'Давным-давно Древние боги решили захватить Крутогорье. Возглавлял их кампанию ужасный генерал... Уул\'гинет Тьма.', '', 28153),
(141585, 'ruRU', 'Следуй за мной.', '', 28153),
(141584, 'ruRU', '<Мэр не реагирует.>', '', 28153),
(141583, 'ruRU', '<Найти источник заклинания.>', '<Найти источник заклинания.>', 28153),
(141582, 'ruRU', '<Чучело, возвышающееся в центре города, источает темную энергию. Эта энергия похожа на ту, которая сковывает здешних жителей. Возможно, оно служит для фокусировки и поддержания заклинания.\n\nЕсли его уничтожить, заклинание может рассеяться.>', '', 28153),
(141581, 'ruRU', '<Этот мужчина подходит под описание Сирила Уайта, мэра Листопадной Бухты. К сожалению, в таком состоянии он ничем не может вам помочь.\n\nВидимо, мэр и другие жители Листопадной Бухты находятся под действием какой-то неизвестной магии. Они живы, но не могут двигаться или говорить.\n\nВам нужно узнать, как снять это проклятие, если вы рассчитываете, что мэр поможет вам установить контакт с домом Уэйкрестов.>', '', 28153),
(141580, 'ruRU', 'Я обязан тебе жизнью! Интересно, куда Сорвиголовы отправят меня в следующий раз...', '', 28153),
(141579, 'ruRU', 'Идолы слабеют! Он будет нашим!', '', 28153),
(141578, 'ruRU', 'Вы проиграли! Мрак восстанет... и тогда Крутогорье падет!', '', 28153),
(141577, 'ruRU', 'Никакой Легион не сравнится с нашей силой! Сдавайся!', '', 28153),
(141576, 'ruRU', 'Небесный Рог будет служить моим повелителям! Ваши тени затмят небо!', '', 28153),
(141575, 'ruRU', 'Служи своим истинным владыкам, дрогбар! Или умри!', '', 28153),
(141573, 'ruRU', '', 'Привет! Ты, это... тебя не интересует история Кул-Тираса? У меня есть несколько книг как об основании этой великой страны, так и ее политике. Готова поклясться, это и правда увлекательные темы.$b$bКроме того, я – отличная переписчица и могу сделать из тебя настоящего мастера пера и чернил!', 28153),
(141572, 'ruRU', 'Одна ошибка, и здесь будет твоя могила.', '', 28153),
(141571, 'ruRU', 'Миира, готовь повозку, нам нужно забрать припасы из порта. Наши новые союзники могут поехать с нами и продолжить свои поиски.', '', 28153),
(141570, 'ruRU', 'Бесит меня эта сырость – почти так же, как твоя физиономия.', 'Бесит меня эта сырость – почти так же, как твоя физиономия.', 28153),
(141569, 'ruRU', 'Чего пялишься?', 'Чего пялишься?', 28153),
(141568, 'ruRU', 'Принцесса слушает тебя, поэтому мы тебя не убьем – пока.', 'Принцесса слушает тебя, поэтому мы тебя не убьем – пока.', 28153),
(141567, 'ruRU', 'Узурпаторы. Орда заплатит за то, что сделала с нашим народом в Танарисе.', 'Узурпаторы. Орда заплатит за то, что сделала с нашим народом в Танарисе.', 28153),
(141566, 'ruRU', 'Добрый день! Хочешь узнать больше о тонком искусстве огранщика?$b$bИли, как его чаще называют, ювелирном деле?', '', 28153),
(141565, 'ruRU', 'Улыбайся, пока можешь, |3-6($c). Одно неверное движение, и мы сами с тобой разделаемся.', 'Улыбайся, пока можешь, |3-6($c). Одно неверное движение, и мы сами с тобой разделаемся.', 28153),
(141564, 'ruRU', 'Орда предала нас ради этих драгоценных эльфов крови. А затем они убили нашего величайшего лидера Зул\'джина.$b$bКровь... Вы нам прилично крови задолжали.', '', 28153),
(141563, 'ruRU', 'Гляди в оба, дорогуша. Как только принцесса забудет о тебе, придется поговорить с моим ножом – о том, что Орда сделала с Зул\'джином.', '', 28153),
(141562, 'ruRU', 'На тебе знак принцессы Таланджи – значит, мы не можем тебя убить. С другой стороны, убивать тебя не обязательно.', '', 28153),
(141561, 'ruRU', 'Чего пялишься?', '', 28153),
(141559, 'ruRU', 'Храм разрушен! Все даже хуже, чем я предполагал...', '', 28153),
(141558, 'ruRU', 'Мне надо поскорее вернуться в храм. Боюсь, без меня там дела идут неважно.', '', 28153),
(141557, 'ruRU', '', 'Теперь они принадлежат мне!', 28153),
(141556, 'ruRU', 'Я свободен от Древних богов. Спасибо вам, друзья.', '', 28153),
(141555, 'ruRU', 'Майла! Мы должны держаться вместе!', '', 28153),
(141554, 'ruRU', '', 'Я не позволю Мраку вселиться в тело моего отца!', 28153),
(141552, 'ruRU', 'Я хотел... увидеть...', 'Я хотела... увидеть...', 28153),
(141549, 'ruRU', 'Пора тебе в котел!', 'Пора тебе в котел!', 28153),
(141547, 'ruRU', 'О, спасибо тебе за свободу! Зря я поверил этим предателям из племени Тортака!', '', 28153),
(141546, 'ruRU', 'Вол\'джамба обещал...', 'Вол\'джамба обещал...', 28153),
(141544, 'ruRU', 'Он... ошибался?..', 'Он... ошибался?..', 28153),
(141538, 'ruRU', 'Только Вол\'джамба спасет нас!', 'Только Вол\'джамба спасет нас!', 28153),
(141536, 'ruRU', 'Давай... вдохни. Посмотрим, у кого воля сильнее!', '', 28153),
(141535, 'ruRU', 'Я никогда... не покорюсь...', 'Я никогда... не покорюсь...', 28153),
(141528, 'ruRU', 'Он говорил... мы выживем...', 'Он говорил... мы выживем...', 28153),
(141527, 'ruRU', 'Конец света близок! Почему никто не слушает?!', 'Конец света близок! Почему никто не слушает?!', 28153),
(141524, 'ruRU', 'Есть, босс!', '', 28153),
(141523, 'ruRU', 'Лео!', '', 28153),
(141522, 'ruRU', 'Они воруют дрова! Взять их, Лео!', '', 28153),
(141519, 'ruRU', '', '$n, это ты? Где мы?', 28153),
(141518, 'ruRU', 'Этот Т\'паартос предан Свету... но и тьме тоже? Это не судьба Т\'паартоса!', '', 28153),
(141517, 'ruRU', 'Все, как говорил мой пророк. Теперь ты понимаешь, зачем я его держу.', '', 28153),
(141512, 'ruRU', 'Возьми мою печать и прилепи ее к гонгу.', '', 28153),
(141510, 'ruRU', 'Да чтоб...', '', 28153),
(141509, 'ruRU', 'Нет! Не трогай!', '', 28153),
(141508, 'ruRU', 'Значится, видение такое: золотые паруса – символ конца. Обманщик хочет сломать печать.', '', 28153),
(141507, 'ruRU', 'Так и быть, я выслушаю твое \"пророчество\". Но ручаюсь только за себя...', '', 28153),
(141506, 'ruRU', 'Я хочу сказать пару слов своему ученику. Найди меня, когда покончишь с его недалекими слугами.', '', 28153),
(141505, 'ruRU', 'Хватит прятаться за масками. Ты только зря тянешь время.', '', 28153),
(141504, 'ruRU', 'Ну так возьми с собой Голос Орды и покончи с этим.', '', 28153),
(141503, 'ruRU', 'Как скажешь, мой король... Вот только... видение говорит, что Вол\'джамба умрет не от моей руки.', '', 28153),
(141502, 'ruRU', 'Это твоя вина, пророк. Исправь свою ошибку.', '', 28153),
(141501, 'ruRU', '|TInterface\\Icons\\Sha_Ability_Rogue_BloodyEye_nightmare:20|t|cFFFF0000|Hspell:258068|h[Взор Саргераса]|h|r обратился к полю боя...', '|TInterface\\Icons\\Sha_Ability_Rogue_BloodyEye_nightmare:20|t|cFFFF0000|Hspell:258068|h[Взор Саргераса]|h|r обратился к полю боя...', 28153),
(141500, 'ruRU', 'Найджел! Ты нашелся!', '', 28153),
(141499, 'ruRU', '', 'Не представляю работу исследователя без опасностей. И кстати, на мне ни царапины.', 28153),
(141498, 'ruRU', '', 'Вот и все, что я смогла вытащить сама.', 28153),
(141497, 'ruRU', 'Хорошо, что хоть себя смогла вытащить.', '', 28153),
(141496, 'ruRU', 'Этот путь ведет к величию? Славе? Или гибели?', '', 28153),
(141495, 'ruRU', 'У души множество сторон. Одни благородны, другие...', '', 28153),
(141494, 'ruRU', 'Дар был отвергнут... но страх никуда не делся.', '', 28153),
(141493, 'ruRU', 'Возможно, страх перед тьмой можно одолеть, лишь примирившись с ней.', '', 28153),
(141492, 'ruRU', 'Страх не слабеет. Не поддается. Его нужно победить.', '', 28153),
(141491, 'ruRU', 'Покой. Безопасность. Вдали от всего. Вдали от всех.', '', 28153),
(141490, 'ruRU', 'Одиночество спасает... Если рядом нет никого, никто не причинит боль.', '', 28153),
(141489, 'ruRU', 'В каждой тени скрывается враг. Как можно остановить эту тьму?', '', 28153),
(141488, 'ruRU', 'Нечестно! Несправедливо! Все не то, чем кажется!', '', 28153),
(141487, 'ruRU', 'Нужно отвлечься... забыться.', '', 28153),
(141486, 'ruRU', 'Бежать... туда, где безопасно... спокойно...', '', 28153),
(141485, 'ruRU', 'Неужели покой недостижим?', '', 28153),
(141484, 'ruRU', 'Даже в безысходной ситуации остается надежда.', '', 28153),
(141483, 'ruRU', 'Боль, мучения... и поиски утешения.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141482, 'ruRU', 'Здесь нет места милосердию.', '', 28153),
(141481, 'ruRU', 'Боль создает воспоминания.', '', 28153),
(141480, 'ruRU', 'Назад пути нет.', '', 28153),
(141479, 'ruRU', 'Помню время, когда в Зандалар пускали только троллей. Точнее... троллей и тортолланов, конечно.\n\nО, однажды они попытались от нас избавиться. Кажется, за этим стоял прадед Растахана, король Тезлехан Ядовитый. Он был немного самоуверенным. Мы сделали так, что он передумал – быстрее, чем элементаль на сборе шаманов. \n\nНе поверишь, сколько компрометирующей информации можно собрать о королевской семье, если живешь дольше ее членов.', 'Помню время, когда в Зандалар пускали только троллей. Точнее... троллей и тортолланов, конечно.\n\nО, однажды они попытались от нас избавиться. Кажется, за этим стоял прадед Растахана, король Тезлехан Ядовитый. Он был немного самоуверенным. Мы сделали так, что он передумал – быстрее, чем элементаль на сборе шаманов. \n\nНе поверишь, сколько компрометирующей информации можно собрать о королевской семье, если живешь дольше ее членов.', 28153),
(141478, 'ruRU', 'Зандалары разрешают нашему народу свободно путешествовать по своим землям в обмен на предоставление полезной информации.\n\nИнтересно, что им обещал твой народ?', 'Зандалары разрешают нашему народу свободно путешествовать по своим землям в обмен на предоставление полезной информации.\n\nИнтересно, что им обещал твой народ?', 28153),
(141477, 'ruRU', 'Ах... Это же |3-6($c). И с какого ты континента?', 'Ах... Это же |3-6($c). И с какого ты континента?', 28153),
(141476, 'ruRU', '', 'Надеюсь, Рокхан и остальные доберутся до Зул\'джана... иначе все быстро закончится.', 28153),
(141475, 'ruRU', 'А, искатель приключений. Сколько берешь за работу? Чуть позже мне может понадобиться помощь: нужно будет добыть довольно... опасную... и ценную вещь.', 'А, искатель приключений. Сколько берешь за работу? Чуть позже мне может понадобиться помощь: нужно будет добыть довольно... опасную... и ценную вещь.', 28153),
(141474, 'ruRU', 'Мы раньше не встречались? Память у меня уже не та, что сто лет назад.', 'Мы раньше не встречались? Память у меня уже не та, что сто лет назад.', 28153),
(141473, 'ruRU', 'О, они пустили Орду в Зулдазар? Какой смелый шаг с их стороны.', 'О, они пустили Орду в Зулдазар? Какой смелый шаг с их стороны.', 28153),
(141472, 'ruRU', '', '', 28153),
(141471, 'ruRU', '', 'Убейте троллей крови, пока они не потопили плот!', 28153),
(141470, 'ruRU', '', 'Тролли крови! Они готовятся атаковать мой город.', 28153),
(141469, 'ruRU', '|TInterface\\Icons\\SPELL_FIRE_IMMOLATION.BLP:20|tПокиньте производственные отсеки во время |cFFFF0000|Hspell:248061|h[Протокола очистки]|h|r, чтобы избежать смерти!', '|TInterface\\Icons\\SPELL_FIRE_IMMOLATION.BLP:20|tПокиньте производственные отсеки во время |cFFFF0000|Hspell:248061|h[Протокола очистки]|h|r, чтобы избежать смерти!', 28153),
(141468, 'ruRU', '|TInterface\\ICONS\\ABILITY_HUNTER_SNIPERSHOT.BLP:20|t Старайтесь отойти подальше от босса во время  |cFFF00000|Hspell:246220|h[Обстрела Скверны]|h|r, чтобы избежать урона!', '', 28153),
(141467, 'ruRU', '|TInterface\\ICONS\\spell_shadow_shadesofdarkness.blp:20|t Держитесь рядом с союзниками, чтобы избежать эффекта |cFFF00000|Hspell:243963|h[Один в темноте]|h|r!', '', 28153),
(141466, 'ruRU', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|tНаполненные Скверной разрушители атакуют Эонар |cFFFF0000|Hspell:246305|h[Артиллерийскими ударами]|h|r. Уничтожайте их как можно быстрее.', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|tНаполненные Скверной разрушители атакуют Эонар |cFFFF0000|Hspell:246305|h[Артиллерийскими ударами]|h|r. Уничтожайте их как можно быстрее.', 28153),
(141465, 'ruRU', 'Это существо атакует игроков. Перед тем, как атаковать его, убедитесь, что оно уже сражается с танками.', 'Это существо атакует игроков. Перед тем, как атаковать его, убедитесь, что оно уже сражается с танками.', 28153),
(141464, 'ruRU', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE.BLP:20|tИз области действия |cFFFF0000|Hspell:248333|h[Метеоритного шторма]|h|r можно выйти. Старайтесь избегать его воздействия.', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE.BLP:20|tИз области действия |cFFFF0000|Hspell:248333|h[Метеоритного шторма]|h|r можно выйти. Старайтесь избегать его воздействия.', 28153),
(141463, 'ruRU', 'Что это за звук?', '', 28153),
(141462, 'ruRU', 'Эй! Есть тут кто-нибудь?', '', 28153),
(141461, 'ruRU', 'НАБ НАБ, БЕГОМ СЮДА! ТУТ ДУКНЯ НЕДОДРАЕНА!', '', 28153),
(141460, 'ruRU', 'Пошевеливайся, ты, ящер с мертвыми зенками.', 'Пошевеливайся, ты, ящер с мертвыми зенками.', 28153),
(141459, 'ruRU', '', 'Твоя манера вести переговоры какая-то скользкая. Скажи честно, чего тебе надо?', 28153),
(141458, 'ruRU', '', 'Раал, твоя жена утром меня чуть не убила. Что ты там, по ее мнению, задумал?', 28153),
(141457, 'ruRU', '', 'Раал, надо это уладить. Таких прошений от племени Амани больше быть не должно.', 28153),
(141456, 'ruRU', 'А! Йети! Ну конечно, почти угадал. Вроде как человек, а шерсть, как у медведя.', '', 28153),
(141455, 'ruRU', '', 'Ох... от одной мысли о водорослях меня... тошнит... <отрыжка> Ой-ой-ой...', 28153),
(141454, 'ruRU', '', 'Что-то про то, что он накрыл его водорослями?', 28153),
(141453, 'ruRU', '', '<отрыжка> Ах да, я помню как какой-то болван хвастался каким-то сокровищем...', 28153),
(141452, 'ruRU', 'Зачем нам стоять тут на страже, дорогуша? Скукотища.', 'Зачем нам стоять тут на страже, дорогуша? Скукотища.', 28153),
(141451, 'ruRU', '', 'Вух! <ик>$B$BДа? В чем дело?', 28153),
(141450, 'ruRU', '<Вздыхает.> Наб Набу это не поможет, уж точно.', '', 28153),
(141449, 'ruRU', 'Он сказал только, что зарыто \"где-то в песках\". Кому это поможет?!', '', 28153),
(141448, 'ruRU', 'Наб Наб слышал о сокровище. Вся таверна слышала!', '', 28153),
(141447, 'ruRU', 'Что-то помыть?', '', 28153),
(141446, 'ruRU', 'ЗАРЫТОМ. СОКРОВИЩЕ.', 'ЗАРЫТОМ. СОКРОВИЩЕ.', 28153),
(141445, 'ruRU', 'УБИТОМ ЧУДОВИЩЕ?!', '', 28153),
(141444, 'ruRU', 'Нет-нет. Зарытом сокровище.', 'Нет-нет. Зарытом сокровище.', 28153),
(141443, 'ruRU', 'ЭЛЬФИЙСКОМ ПОЗОРИЩЕ?', '', 28153),
(141442, 'ruRU', 'ПРАВДА НЕДАВНО КАКОЙ-ТО ПАРЕНЬ РАЗГЛАГОЛЬСТВОВАЛ В ТАВЕРНЕ О ЗАБЫТОМ БОЛОТИЩЕ. КАК БУДТО ЭТО КОМУ-ТО ИНТЕРЕСНО.', '', 28153),
(141441, 'ruRU', 'Нет, про сокровища я ничего не знаю!', '', 28153),
(141440, 'ruRU', 'А-А-А. ЗАРЫТОМ СОКРОВИЩЕ.', '', 28153),
(141439, 'ruRU', '<Вы показываете плакат.> Что тебе известно об этом зарытом сокровище?', '<Вы показываете плакат.> Что тебе известно об этом зарытом сокровище?', 28153),
(141438, 'ruRU', 'Что?! Тебе лучше говорить погромче. Я плоховато слышу, с тех пор как... $B$BС того самого случая.', '', 28153),
(141435, 'ruRU', 'Пит Проныра!', '', 28153),
(141434, 'ruRU', '', 'Улыбайся постоянно! Никогда не знаешь, когда гости смотрят – особенно те, кто любит пошнырять.', 28153),
(141433, 'ruRU', '', 'Не забывай: если гость задает вопрос, а ты не знаешь, как ответить, – придумай что-нибудь! Используй знаменитую гномскую изобретательность!', 28153),
(141432, 'ruRU', '', 'Ну-ка покажите ямочки на мордочках как следует, новобранцы! Пусть видят, какими ужасно милыми бываем мы, гномы!', 28153),
(141431, 'ruRU', 'Что? Так нечестно! НЕЧЕСТНО!', '', 28153),
(141430, 'ruRU', '', 'Флинн! Держись!', 28153),
(141429, 'ruRU', 'Десять тысяч золотых за их головы!', '', 28153),
(141428, 'ruRU', 'С Праудмурами покончено! Когда леди Эшвейн займет трон, я встану во главе ее флота!', '', 28153),
(141427, 'ruRU', 'Довольно! Вы все равно опоздали! Атака на врата Дэлина уже началась!', '', 28153),
(141426, 'ruRU', 'Проклятые кости! Ребята, за дело!', '', 28153),
(141425, 'ruRU', 'Харлан высыпает из мешочка все кости. Выпадают в основном сокровища.', 'Харлан высыпает из мешочка все кости. Выпадают в основном сокровища.', 28153),
(141424, 'ruRU', 'Харлан снова бросает кости. Выпадает пушка и два черепа.', 'Харлан снова бросает кости. Выпадает пушка и два черепа.', 28153),
(141423, 'ruRU', 'Харлан бросает кости. Выпадает два сокровища и компас.', 'Харлан бросает кости. Выпадает два сокровища и компас.', 28153),
(141422, 'ruRU', 'Харлан бросает кости. Выпадает три меча.', 'Харлан бросает кости. Выпадает три меча.', 28153),
(141421, 'ruRU', 'Так-то лучше! Не люблю играть по правилам! Ха-ха!', '', 28153),
(141420, 'ruRU', 'Что? Не, это кости барахлят.', '', 28153),
(141419, 'ruRU', 'Ладно-ладно... Еще разок!', '', 28153),
(141418, 'ruRU', 'О, я всегда рад новым лицам! Надеюсь, ты поживее, чем местный народ.', '', 28153),
(141417, 'ruRU', 'Ой! Боюсь, вам не повезло! Прирежьте их!', '', 28153),
(141416, 'ruRU', 'Как же поступить с этими крысами?.. Пусть решат кости!', '', 28153),
(141415, 'ruRU', 'О! А вот и новый рекрут! Сейчас повеселимся.', '', 28153),
(141414, 'ruRU', '', 'Мой муж будет вечно эксплуатировать своих рабочих...', 28153),
(141413, 'ruRU', 'Все изменилось, Флинн. Теперь капитан – я. Когда с Праудмурами будет покончено, мы разграбим весь Кул-Тирас!', '', 28153),
(141412, 'ruRU', 'М-г-м... беги...', '', 28153),
(141411, 'ruRU', 'Вот так, ребята! Намните ему бока!', '', 28153),
(141410, 'ruRU', '', 'Пришло время покинуть священные вершины.', 28153),
(141409, 'ruRU', '', 'Было время, когда мы были разобщены. Когда сбились с пути. Но духи предков напомнили нам, что мы связаны землей, рекой и небом. Что мы — одна семья, а за семью стоит бороться.', 28153),
(141408, 'ruRU', '', 'Эти слова не о земле и камне. Это история нашего народа, отринувшего разногласия ради победы над общим врагом.', 28153),
(141407, 'ruRU', '', 'Крутогорье выстоит.', 28153),
(141406, 'ruRU', '', 'Мешать мне – очень глупо с твоей стороны!', 28153),
(141405, 'ruRU', '', 'Силгрин! Вальтруа! Помогите лорду-регенту!', 28153),
(141404, 'ruRU', 'Довольно! Избавимся от порчи, пока она не поразила Колодец!', '', 28153),
(141403, 'ruRU', '', 'Я не хотела ничего подобного...', 28153),
(141402, 'ruRU', 'Вот почему мы изгнали Умбрия и его радикалов! Все, кто связан с Бездной, опасны для Солнечного Колодца!', '', 28153),
(141401, 'ruRU', 'Что происходит?', '', 28153),
(141400, 'ruRU', 'Стой!', '', 28153),
(141399, 'ruRU', '', 'Солнечный Колодец изменился... Но все так же прекрасен.', 28153),
(141398, 'ruRU', '', 'Солнечный Колодец был осквернен врагом. Но жертва наару очистила его воды. И теперь Свет поддерживает нас.', 28153),
(141397, 'ruRU', '', 'Сила здесь почти осязаема. Она столь же велика, как в Ночном Колодце. Но иной природы.', 28153),
(141396, 'ruRU', 'Следуйте за мной.', '', 28153),
(141395, 'ruRU', 'Роммат, открой портал, пожалуйста.', '', 28153),
(141394, 'ruRU', '', 'Для меня честь увидеть Солнечный Колодец, Лор\'темар. Кстати, друзья обычно зовут меня Талисрой.', 28153),
(141393, 'ruRU', 'Что бы ни случилось с Аллерией, она остается дочерью Кель\'Таласа. Я не могу запретить ей посетить нашу святыню. Первая чародейка, я буду рад, если вы присоединитесь к нам.', '', 28153),
(141392, 'ruRU', 'Не думаю, что мы можем ей доверять. Вдруг она...', '', 28153),
(141391, 'ruRU', '', 'Я тысячу лет не видела Солнечный Колодец. Можно мне взглянуть на него хотя бы раз?', 28153),
(141389, 'ruRU', '', 'Что ж, похоже, мое предложение было взвешено... и отклонено. Но, прежде чем я уйду, позволь кое о чем попросить.', 28153),
(141388, 'ruRU', 'Ты сомневаешься в моих словах, но можно ли верить твоим? Не ты ли покорилась повелителям Бездны? Что они нашептывают тебе?', '', 28153),
(141387, 'ruRU', '', 'Какие серьезные слова, Лор\'темар. Ты их сам придумал или просто повторяешь то, что приказывает твой вождь?', 28153),
(141384, 'ruRU', 'Я-то надеялся, что ты просто соскучилась по Луносвету. А ты явилась просить за мальчишку-короля Альянса. Я разочарован.', '', 28153),
(141383, 'ruRU', '', 'Как пожелаешь. Верховный король Андуин Ринн предлагает...', 28153),
(141382, 'ruRU', 'Вздор! Что бы ты ни хотела сказать, сделай это перед нашими гостями.', '', 28153),
(141381, 'ruRU', '', 'А для меня честь познакомиться с вами, первая чародейка. Впрочем, не буду вам мешать. Пожалуй, вернусь позже.', 28153),
(141380, 'ruRU', '', 'Это честь для меня, леди Ветрокрылая. Силгрин рассказывал о ваших подвигах на Аргусе.', 28153),
(141379, 'ruRU', 'Прошу, зовите меня просто Лор\'темаром. Кстати, совсем забыл. Позвольте представить леди Аллерию Ветрокрылую, героиню Луносвета.', '', 28153),
(141376, 'ruRU', '', 'Мы рады наконец посетить ваш чудесный город. Благодарю вас за приглашение, лорд-регент.', 28153),
(141375, 'ruRU', '', 'Леди Талисра, уважаемые гости. Добро пожаловать в Луносвет.', 28153),
(141374, 'ruRU', 'У нас не должно быть секретов от союзников. Кстати, скоро прибудут наши новые друзья.', '', 28153),
(141373, 'ruRU', '', 'Рада вас видеть. Лор\'темар, я бы хотела обсудить с тобой один очень важный вопрос. Наедине.', 28153),
(141372, 'ruRU', 'Леди Лиадрин, $n. Рад вас видеть. Как вы могли заметить, у нас сегодня необычная гостья.', '', 28153),
(141371, 'ruRU', '', 'Как прикажешь, вождь. $p, встретимся в резиденции леди Талисры в Сурамаре.', 28153),
(141370, 'ruRU', '', 'Я рассчитываю на вас. Не возвращайтесь, пока Сурамар не присягнет Орде.', 28153),
(141369, 'ruRU', '', 'Лорд-регент Терон пригласил ночнорожденных в Луносвет. Я отправлюсь в Сурамар и сопровожу леди Талисру на встречу.', 28153),
(141366, 'ruRU', '', 'Теперь нашему народу предстоит снова завоевать свое место в Азероте.', 28153),
(141365, 'ruRU', '', 'Наши лидеры предали нас, заключив сделку с демонами. Но мы восстали против них... и изгнали врагов. Сурамар снова принадлежит нам, и мы больше никогда не поддадимся тьме.', 28153),
(141364, 'ruRU', '', 'Шли годы, Азерот менялся вокруг нас... пока не оказался в руках Легиона.', 28153),
(141363, 'ruRU', '', 'Десять тысяч лет Сурамар был для нас всем миром.', 28153),
(141362, 'ruRU', '', 'Мы – озаренные. Мы – луч надежды, оплот против тьмы.', 28153),
(141361, 'ruRU', '', 'И вот наконец Легион пал. Но наша война не окончена. Новый враг скрывается в тенях, выжидает момент, чтобы нанести удар.', 28153),
(141360, 'ruRU', '', 'Тысячи лет Свет указывал нам путь...', 28153),
(141359, 'ruRU', '', 'Мы – солдаты.', 28153),
(141358, 'ruRU', '', 'Бездна изменила нас. Но ты станешь повелевать ею.', 28153),
(141357, 'ruRU', '', 'Но мы знаем то, что неведомо им.', 28153),
(141356, 'ruRU', '', 'Мудрецы страшатся Бездны.', 28153),
(141355, 'ruRU', '', 'Бездна. Вечно голодная сила.', 28153),
(141354, 'ruRU', '', 'Встретимся у плота.', 28153),
(141353, 'ruRU', 'Да благословит тебя Бвонсамди.', '', 28153),
(141352, 'ruRU', '', 'Гоблины уверяют, что их план сработает... Вот почему мне нужна твоя помощь: проследи, чтобы он действительно сработал.$B$B$gГотов:Готова; отправиться в путь?', 28153),
(141351, 'ruRU', 'Он известен тем, что спит с рыбами... в прямом смысле слова! Гроза Вольной Гавани... Атаман Акульего Апперкота... Безумный Брутальный Боксер... Тротак-Акулобоец!', '', 28153),
(141350, 'ruRU', 'Невероятно! Эти крысы одолели Гриффа и Штевеня! У них остался только один противник, который не нуждается в представлениях.', '', 28153),
(141349, 'ruRU', 'Прожорливые Предвестники Полного Конца... Рьяные Раздиратели Рыб и Раков... Жуткие Живодеры... Грифф и Штевень!', '', 28153),
(141348, 'ruRU', 'Без долгих предисловий на ринг выходят наши заморские гости. Несравненная пара свирепых гладиаторов, вселяющих страх в сердца даже самых доблестных воинов.', '', 28153),
(141347, 'ruRU', 'Страдай, осквернитель!', '', 28153),
(141345, 'ruRU', 'Тебе отсюда не уйти!', '', 28153),
(141344, 'ruRU', 'Людвиг пал! Вот это зрелище! Вонючие буканьеры оказались крепче, чем мы думали. Но теперь им придется иметь дело с самим воплощением жестокости.', '', 28153),
(141343, 'ruRU', 'Спасайся...', '', 28153),
(141342, 'ruRU', '', 'Негодная девчонка! Я заключила сделку с Бвонсамди – моя жизнь в обмен на твою душу! Ты все испортишь!', 28153),
(141341, 'ruRU', 'Прямиком из стоков Вольной Гавани! Закованный в панцирь убийца, готовый крушить черепа... ха-ха! Разящая рептилия... Панцирный палач!... Людвиг!', '', 28153),
(141340, 'ruRU', 'Глядите-ка. Они поймали свинью. Может, настал черед более... опасных игр?', '', 28153),
(141334, 'ruRU', '', 'Знаешь что-нибудь о клане Темнозубов? Неудивительно – это племя истребил культ Сумеречного Молота.\n\nОдин представитель этого племени живет на попечении зандаларов – как напоминание о прошлом. Теперь я просто диковинка, не которую все глазеют.\n\nНе так уж это плохо. Никогда не приходится платить за выпивку.', 28153),
(141332, 'ruRU', 'Говорят, сейчас у короля Растахана дела идут не очень-то хорошо. Окончательный развал Зандалара – лишь вопрос времени. И что нам тогда делать?', 'Говорят, сейчас у короля Растахана дела идут не очень-то хорошо. Окончательный развал Зандалара – лишь вопрос времени. И что нам тогда делать?', 28153),
(141331, 'ruRU', 'Когда-то зандалары стояли во главе всех троллей. Теперь они не могут даже защитить собственные границы.', 'Когда-то зандалары стояли во главе всех троллей. Теперь они не могут даже защитить собственные границы.', 28153),
(141330, 'ruRU', 'Зандалары допустили в свои земли магию крови. Она их непременно уничтожит – это только вопрос времени.', 'Зандалары допустили в свои земли магию крови. Она их непременно уничтожит – это только вопрос времени.', 28153),
(141329, 'ruRU', 'Зандалары отправляют всех нарушителей спокойствия в пустыню. Никто не возвращается.', 'Зандалары отправляют всех нарушителей спокойствия в пустыню. Никто не возвращается.', 28153),
(141328, 'ruRU', 'Когда-то зандалары были самым гордым народом. Теперь здесь только на этой гордости все и держится.', 'Когда-то зандалары были самым гордым народом. Теперь здесь только на этой гордости все и держится.', 28153),
(141327, 'ruRU', 'Ты выглядишь аппетитно.', 'Ты выглядишь аппетитно.', 28153),
(141326, 'ruRU', 'Ненавижу эльфов. Ненавижу нежить. А в Орде и тех, и других полно.', 'Ненавижу эльфов. Ненавижу нежить. А в Орде и тех, и других полно.', 28153),
(141325, 'ruRU', 'Золотой флот – вот в чем главная сила зандаларов. Власть у того, у кого флот.', 'Золотой флот – вот в чем главная сила зандаларов. Власть у того, у кого флот.', 28153),
(141324, 'ruRU', 'Говорят, сейчас у короля Растахана дела идут не очень-то хорошо. Окончательный развал Зандалара – лишь вопрос времени. И что нам тогда делать?', 'Говорят, сейчас у короля Растахана дела идут не очень-то хорошо. Окончательный развал Зандалара – лишь вопрос времени. И что нам тогда делать?', 28153),
(141323, 'ruRU', 'Когда-то зандалары стояли во главе всех троллей. Теперь они не могут даже защитить собственные границы.', 'Когда-то зандалары стояли во главе всех троллей. Теперь они не могут даже защитить собственные границы.', 28153),
(141322, 'ruRU', 'Надо уничтожить Орду раз и навсегда.', 'Надо уничтожить Орду раз и навсегда.', 28153),
(141321, 'ruRU', 'Когда-то зандалары были самым гордым народом. Теперь здесь только на этой гордости все и держится.', '', 28153),
(141320, 'ruRU', 'Ненавижу эльфов. Ненавижу нежить. А в Орде и тех, и других полно.', '', 28153),
(141319, 'ruRU', 'Видимо, король Растахан теряет хватку. Пустить Орду в Зандалар без боя, подумать только!', '', 28153),
(141318, 'ruRU', 'У Орды новый вождь. Говорят, какая-то немощная эльфийка.', '', 28153),
(141316, 'ruRU', 'Только здесь так много племен может встретиться без кровопролития. Конечно, если стражи исчезнут хоть ненадолго... все изменится.', '', 28153),
(141313, 'ruRU', 'Зандаларам больше не удастся прятаться здесь. Их дни сочтены.', 'Зандаларам больше не удастся прятаться здесь. Их дни сочтены.', 28153),
(141312, 'ruRU', 'Племя Черного Копья предало своих сородичей. Зря они примкнули к Орде.', 'Племя Черного Копья предало своих сородичей. Зря они примкнули к Орде.', 28153),
(141311, 'ruRU', 'У Орды новый вождь. Говорят, что какая-то хилая эльфийка.', 'У Орды новый вождь. Говорят, что какая-то хилая эльфийка.', 28153),
(141310, 'ruRU', 'Говорят, сейчас у короля Растахана дела идут не особенно хорошо. Окончательный развал Зандалара – лишь вопрос времени. И что нам тогда делать?', 'Говорят, сейчас у короля Растахана дела идут не особенно хорошо. Окончательный развал Зандалара – лишь вопрос времени. И что нам тогда делать?', 28153),
(141309, 'ruRU', 'Джунгли здесь совсем не те, что дома. У нас единороги гораздо крупнее.', 'Джунгли здесь совсем не те, что дома. У нас единороги гораздо крупнее.', 28153),
(141308, 'ruRU', 'Зандаларам больше не удастся прятаться здесь. Их дни сочтены.', 'Зандаларам больше не удастся прятаться здесь. Их дни сочтены.', 28153),
(141307, 'ruRU', 'Золотой флот – вот в чем главная сила зандаларов. Власть у того, у кого флот.', 'Золотой флот – вот в чем главная сила зандаларов. Власть у того, у кого флот.', 28153),
(141306, 'ruRU', 'Зандалары думают, что они здесь лучше всех. На деле они – просто вымирающие ископаемые.', 'Зандалары думают, что они здесь лучше всех. На деле они – просто вымирающие ископаемые.', 28153),
(141305, 'ruRU', '|TInterface\\Icons\\SPELL_NATURE_ABOLISHMAGIC.BLP:20|tЭонар высвобождает свою |cFFFF0000|Hspell:250048|h[Жизненную силу]|h|r!', '|TInterface\\Icons\\SPELL_NATURE_ABOLISHMAGIC.BLP:20|tЭонар высвобождает свою |cFFFF0000|Hspell:250048|h[Жизненную силу]|h|r!', 28153),
(141304, 'ruRU', 'Зандалары допустили в свои земли магию крови. Она их непременно уничтожит – вопрос только когда.', 'Зандалары допустили в свои земли магию крови. Она их непременно уничтожит – вопрос только когда.', 28153),
(141303, 'ruRU', 'Ненавижу эльфов. Ненавижу нежить. А в Орде и тех, и других полно.', 'Ненавижу эльфов. Ненавижу нежить. А в Орде и тех, и других полно.', 28153),
(141302, 'ruRU', 'Говорят, король даже не знает, что происходит у него в городе. Как же он справится с этим кризисом?', 'Говорят, король даже не знает, что происходит у него в городе. Как же он справится с этим кризисом?', 28153),
(141301, 'ruRU', 'Когда-то зандалары были самым гордым народом. Теперь здесь только на этой гордости все и держится.', 'Когда-то зандалары были самым гордым народом. Теперь здесь только на этой гордости все и держится.', 28153),
(141300, 'ruRU', 'Кругом слишком много посланников. Но маловато принимающих.', 'Кругом слишком много посланников. Но маловато принимающих.', 28153),
(141299, 'ruRU', 'Говорят, сейчас у короля Растахана дела идут не очень-то хорошо. Окончательный развал Зандалара – лишь вопрос времени. И что нам тогда делать?', 'Говорят, сейчас у короля Растахана дела идут не очень-то хорошо. Окончательный развал Зандалара – лишь вопрос времени. И что нам тогда делать?', 28153),
(141298, 'ruRU', 'Будь начеку. А то получишь нож в спину.', 'Будь начеку. А то получишь нож в спину.', 28153),
(141297, 'ruRU', 'Будь начеку. А то получишь нож в спину.', 'Будь начеку. А то получишь нож в спину.', 28153),
(141296, 'ruRU', 'Видимо, король Растахан теряет хватку. Пустить Орду в Зандалар без боя, подумать только!', 'Видимо, король Растахан теряет хватку. Пустить Орду в Зандалар без боя, подумать только!', 28153),
(141295, 'ruRU', 'Зандалары думают, что они здесь лучше всех. На деле они – просто вымирающие ископаемые.', 'Зандалары думают, что они здесь лучше всех. На деле они – просто вымирающие ископаемые.', 28153),
(141294, 'ruRU', 'Ты веришь, что вождем Орды стала какая-то мелкая дохлая эльфиха? Даже не смешно.', 'Ты веришь, что вождем Орды стала какая-то мелкая дохлая эльфиха? Даже не смешно.', 28153),
(141293, 'ruRU', 'Орда? Пф! Они не стоят кучи дикорожьего навоза.', 'Орда? Пф! Они не стоят кучи дикорожьего навоза.', 28153),
(141292, 'ruRU', 'Зандаларам больше не удастся прятаться здесь. Их дни сочтены.', 'Зандаларам больше не удастся прятаться здесь. Их дни сочтены.', 28153),
(141291, 'ruRU', 'Зандалары любят разглагольствовать о своей ненависти к нежити. Но с новым вождем Орды они разговаривают по-другому!', 'Зандалары любят разглагольствовать о своей ненависти к нежити. Но с новым вождем Орды они разговаривают по-другому!', 28153),
(141290, 'ruRU', 'Кругом слишком много посланников. Но маловато принимающих.', 'Кругом слишком много посланников. Но маловато принимающих.', 28153),
(141289, 'ruRU', 'Ты веришь, что вождем Орды стала какая-то мелкая дохлая эльфиха? Даже не смешно.', 'Ты веришь, что вождем Орды стала какая-то мелкая дохлая эльфиха? Даже не смешно.', 28153),
(141288, 'ruRU', 'Зандалары думают, что они здесь – самое лучшее племя. Недолго им осталось так заблуждаться.', 'Зандалары думают, что они здесь – самое лучшее племя. Недолго им осталось так заблуждаться.', 28153),
(141287, 'ruRU', 'Когда-то зандалары были самым гордым народом. Теперь здесь только на этой гордости все и держится.', 'Когда-то зандалары были самым гордым народом. Теперь здесь только на этой гордости все и держится.', 28153),
(141286, 'ruRU', 'Ненавижу эльфов. Ненавижу нежить. А в Орде и тех, и других полно.', 'Ненавижу эльфов. Ненавижу нежить. А в Орде и тех, и других полно.', 28153),
(141285, 'ruRU', 'Только здесь так много племен может встретиться без кровопролития. Конечно, если стражи исчезнут хоть ненадолго... все изменится.', 'Только здесь так много племен может встретиться без кровопролития. Конечно, если стражи исчезнут хоть ненадолго... все изменится.', 28153),
(141284, 'ruRU', 'Дни Орды сочтены. Лучше поверь мне на слово.', 'Дни Орды сочтены. Лучше поверь мне на слово.', 28153),
(141283, 'ruRU', 'Зандалары любят разглагольствовать о своей ненависти к нежити. Но с новым вождем Орды они разговаривают по-другому!', 'Зандалары любят разглагольствовать о своей ненависти к нежити. Но с новым вождем Орды они разговаривают по-другому!', 28153),
(141282, 'ruRU', 'Кругом слишком много посланников. Но маловато принимающих.', 'Кругом слишком много посланников. Но маловато принимающих.', 28153),
(141281, 'ruRU', 'Не маловато ли в этом городе ступенек?', 'Не маловато ли в этом городе ступенек?', 28153),
(141280, 'ruRU', 'Зандалары отправляют всех нарушителей спокойствия в пустыню. Никто не возвращается.', 'Зандалары отправляют всех нарушителей спокойствия в пустыню. Никто не возвращается.', 28153),
(141279, 'ruRU', 'Племя Сломанного Клыка помнит, как Орда ему помогла. Мы не останемся в долгу.', 'Племя Сломанного Клыка помнит, как Орда ему помогла. Мы не останемся в долгу.', 28153),
(141278, 'ruRU', 'Отсюда до Внутренних земель не близко, но знай, что мы, племя Сломанного Клыка, – друзья Орды, и всегда ими останемся.', 'Отсюда до Внутренних земель не близко, но знай, что мы, племя Сломанного Клыка, – друзья Орды, и всегда ими останемся.', 28153),
(141277, 'ruRU', 'Зандаларам больше не удастся прятаться здесь. Их дни сочтены.', 'Зандаларам больше не удастся прятаться здесь. Их дни сочтены.', 28153),
(141276, 'ruRU', 'Обмазанная маслом свинья? А это точно профессиональная арена?.. Ох, ладно. Ловите свинью!', '', 28153),
(141275, 'ruRU', 'Сейчас на арене будет происходить нечто невероятное... невообразимое... нечто... что? Что за...', '', 28153),
(141274, 'ruRU', 'Будь начеку. А то получишь нож в спину.', 'Будь начеку. А то получишь нож в спину.', 28153),
(141273, 'ruRU', 'У Орды новый вождь. Говорят, какая-то немощная эльфийка.', 'У Орды новый вождь. Говорят, какая-то немощная эльфийка.', 28153),
(141272, 'ruRU', 'Золотой флот – вот в чем главная сила зандаларов. Власть у того, у кого флот.', 'Золотой флот – вот в чем главная сила зандаларов. Власть у того, у кого флот.', 28153),
(141271, 'ruRU', 'Видимо, король Растахан теряет хватку. Пустить Орду в Зандалар без боя, подумать только!', 'Видимо, король Растахан теряет хватку. Пустить Орду в Зандалар без боя, подумать только!', 28153),
(141266, 'ruRU', 'Ай! Ладно, ладно! Итак, вас ждет кровавое представление! Из дальних далей к нам прибыли... загадочные... опасные... малость потасканные и попахивающие буканьеры!', '', 28153),
(141265, 'ruRU', 'Давай, займись говорением!', '', 28153),
(141263, 'ruRU', 'А-а! Зачем ты меня тыкаешь? Ой! Водин, вставай! Работа ждет!', '', 28153),
(141262, 'ruRU', 'Не спать, сухопутные крысы!', '', 28153),
(141261, 'ruRU', 'Делайте ваши ставки! К нам пожаловали новые жерт... претенденты! А теперь слово Гаргтоку и Водину!', '', 28153),
(141260, 'ruRU', 'Драка? Здорово!', 'Драка? Здорово!', 28153),
(141259, 'ruRU', 'Добро пожаловать в Йо-хо-хо-лизей, заморыши! Готовы потягаться с самыми отборными злодеями?', '', 28153),
(141250, 'ruRU', 'Орда? Пф! Они не стоят кучи дикорожьего навоза.', 'Орда? Пф! Они не стоят кучи дикорожьего навоза.', 28153),
(141249, 'ruRU', '', 'Никакой ковен мне не указ!', 28153),
(141248, 'ruRU', 'Зандалары думают, что они здесь лучше всех. На деле они – просто вымирающие ископаемые.', 'Зандалары думают, что они здесь лучше всех. На деле они – просто вымирающие ископаемые.', 28153),
(141247, 'ruRU', 'Ты веришь, что вождем Орды стала какая-то мелкая дохлая эльфиха? Даже не смешно.', 'Ты веришь, что вождем Орды стала какая-то мелкая дохлая эльфиха? Даже не смешно.', 28153),
(141246, 'ruRU', 'Племя Черного копья предало своих сородичей. Зря они примкнули к Орде.', 'Племя Черного копья предало своих сородичей. Зря они примкнули к Орде.', 28153),
(141245, 'ruRU', '', 'Из-за тебя... все погибло...', 28153),
(141244, 'ruRU', '', 'Недостойная! Слабая! Я?!', 28153),
(141243, 'ruRU', '', 'Они станут корчиться и кричать от боли, когда я буду разрывать и пожирать их тела!', 28153),
(141238, 'ruRU', '', 'Поняла. Мой отряд поддержит вас.', 28153),
(141235, 'ruRU', 'Раздается скрежет, как будто что-то царапает камень.', 'Раздается скрежет, как будто что-то царапает камень.', 28153),
(141233, 'ruRU', 'Впереди проклятая чума. Мы не можем идти дальше.', '', 28153),
(141232, 'ruRU', 'Изготовление бальзама', 'Изготовление бальзама', 28153),
(141221, 'ruRU', 'Говорят, сейчас у короля Растахана дела идут не очень-то хорошо. Окончательный развал Зандалара – лишь вопрос времени. И что нам тогда делать?', 'Говорят, сейчас у короля Растахана дела идут не очень-то хорошо. Окончательный развал Зандалара – лишь вопрос времени. И что нам тогда делать?', 28153),
(141213, 'ruRU', 'Дикие животные Вол\'дуна должны оставаться свободными.', '', 28153),
(141212, 'ruRU', '', 'Позволь мне съесть твое сердце!', 28153),
(141211, 'ruRU', 'И что же это?', 'И что же это?', 28153),
(141210, 'ruRU', 'Я могу тебе чем-нибудь помочь?', 'Я могу тебе чем-нибудь помочь?', 28153),
(141209, 'ruRU', 'Что случилось?', 'Что случилось?', 28153),
(141208, 'ruRU', 'Почему ты плачешь?', 'Почему ты плачешь?', 28153),
(141207, 'ruRU', 'Да-да! Письмо дойдет быстро-быстро! Полный вперед, мои красивки!', '', 28153),
(141206, 'ruRU', 'Можешь отправить это письмо в Боралус, Телии?', 'Можешь отправить это письмо в Боралус, Телии?', 28153),
(141205, 'ruRU', 'Продолжение следует...\n\nСпасибо, что были с нами на BlizzCon!', '', 28153),
(141204, 'ruRU', 'Ты здесь, чтобы издеваться надо мной? Чтобы посмеяться над вестником павшей империи?$b$bВсе тролли Зул\'Драка, не погибшие в боях с Плетью, в конце концов оказались сломлены. В предсмертной агонии мой народ убил своих лоа, украв силу этих богов, чтобы обернуть ее против Плети. Затем и убийцы погибли.$b$bЯ еще здесь, но теперь я для этих зандаларов – всего лишь домашний питомец. Диковинка, которую они выводят, когда хотят показать детям что-то экзотическое.$b$bОставь меня в покое.', '', 28153),
(141202, 'ruRU', '', 'Когда ковен отверг меня, у меня словно вырвали душу! Теперь я заберу твою!', 28153),
(141201, 'ruRU', '', 'Ну... есть кое-что, что может помочь...', 28153),
(141200, 'ruRU', '', 'Вместе нас ждало такое чудесное будущее... но его у нас отняли.', 28153),
(141199, 'ruRU', '', 'Как же я не догадалась, как только они появились на пороге?.. Они никогда не приходят с хорошими новостями.\n\nЯ сразу поняла, что моей мечте конец.', 28153),
(141198, 'ruRU', '', 'Такая... такая... утрата... \n\nЯ и не думала, что может быть так больно...', 28153),
(141197, 'ruRU', 'Эй, ты! Сюда!', '', 28153),
(141196, 'ruRU', '<Женщина рыдает. Вы протягиваете руку, чтобы утешить ее.>', '<Женщина рыдает. Вы протягиваете руку, чтобы утешить ее.>', 28153),
(141194, 'ruRU', 'Вы уверены, что хотите переместиться в подземелье (Атал\'Дазар)?', 'Вы уверены, что хотите переместиться в подземелье (Атал\'Дазар)?', 28153),
(141193, 'ruRU', 'Вы уверены, что хотите переместиться в подземелье (Вольная Гавань)?', 'Вы уверены, что хотите переместиться в подземелье (Вольная Гавань)?', 28153),
(141192, 'ruRU', 'Перенестись в подземелье: Атал\'Дазар', 'Перенестись в Атал\'Дазар', 28153),
(141191, 'ruRU', 'Перенестись в подземелье: Вольная Гавань', 'Перенестись в Вольную Гавань', 28153),
(141190, 'ruRU', 'Добро пожаловать на BlizzCon 2017! Если хотите переместиться в подземелье своей фракции, пожалуйста, щелкните ниже!', 'Добро пожаловать на BlizzCon 2017! Если хотите переместиться в подземелье своей фракции, пожалуйста, щелкните ниже!', 28153),
(141189, 'ruRU', '', 'Прочь с глаз моих! Не возвращайся, пока не покажешь, чего ты стоишь!', 28153),
(141188, 'ruRU', 'Прости! Я пытался помочь, но какой из меня боец!', '', 28153),
(141187, 'ruRU', '', 'Все предрешено! Зулдазар обречен. Вы обречены. Г\'уун придет! Г\'уун проснется!', 28153),
(141186, 'ruRU', '', 'Вы убили НАШЕГО лоа... мы выследим вас... будем пытать... до смерти!', 28153),
(141185, 'ruRU', '', 'Хир\'ик служил Г\'ууну! Г\'уун уничтожит вас. А потом Зулдазар... а потом всю Орду!', 28153),
(141184, 'ruRU', '<Ракжан уважительно склоняет голову.>', '', 28153),
(141183, 'ruRU', 'Полетели.', 'Полетели.', 28153),
(141182, 'ruRU', '<Ракжан уважительно склоняет голову.>', '', 28153),
(141180, 'ruRU', 'Прощай, дурачина!', '', 28153),
(141178, 'ruRU', 'Думаю, на какое-то время мне стоит залечь на дно...', '', 28153),
(141177, 'ruRU', 'Жаль, этот черепах не явился сюда сам. Я бы немало выручил за его панцирь.', '', 28153),
(141176, 'ruRU', 'Я собираю отряд тауренов – охотников на демонов. Нам даже эти их клинки не нужны, будем пропускать скверну прямо через рога.', '', 28153),
(141175, 'ruRU', '\"Виндикар\" – очень быстрый корабль. Ведь он движется со скоростью Света.', '', 28153),
(141174, 'ruRU', '', 'Мы – крутогорцы. Но если ты не с нами, то будешь отстоегорцем.', 28153),
(141173, 'ruRU', '', 'Как тебе новый танец пророка Велена? Он называется Мак\'Арина.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141172, 'ruRU', '', 'Хм... Наверное, <ик!> струсил и удрал.', 28153),
(141171, 'ruRU', '', 'Где этот подлый трус, который оскорбляет <ик> братство Стальных Волн?!', 28153),
(141170, 'ruRU', '', 'Что?! <ик!> Я ему покажу, как поносить МОИХ ребят!', 28153),
(141169, 'ruRU', 'Йо-хо-хо! Какой-то салага с морской водой вместо мозгов поносит братство Стальных Волн! Вон там, за тем домом!', 'Йо-хо-хо! Какой-то салага с морской водой вместо мозгов поносит братство Стальных Волн! Вон там, за тем домом!', 28153),
(141168, 'ruRU', 'Что? Эта старая карга должна умереть и отдать мне свою душу! Убей ее. Я должен получить то, что мне причитается.', '', 28153),
(141167, 'ruRU', '', '<ик>$B$BДа? Чего тебе?', 28153),
(141166, 'ruRU', 'Ты... ЧТО?! Нельзя... нет, нет, никогда, ни за что... НЕЛЬЗЯ убивать лоа!', '', 28153),
(141165, 'ruRU', 'Джо\'чунга жив, но лоа Хир\'ик...', 'Джо\'чунга жив, но лоа Хир\'ик...', 28153),
(141164, 'ruRU', 'Вот ты где! А я уже начал волноваться. Что случилось?', '', 28153),
(141163, 'ruRU', 'Может быть, на улице я и дреней... но в спальне – эредар.', '', 28153),
(141162, 'ruRU', '|TInterface\\ICONS\\ABILITY_VEHICLE_SIEGEENGINECANNON.BLP:20|t Начинается |cFFF00000|Hspell:257585|h[Обстрел]|h|r!', '|TInterface\\ICONS\\ABILITY_VEHICLE_SIEGEENGINECANNON.BLP:20|t Начинается |cFFF00000|Hspell:257585|h[Обстрел]|h|r!', 28153),
(141161, 'ruRU', '<Вспомнить заточение Саргераса>', '<Вспомнить заточение Саргераса>', 28153),
(141160, 'ruRU', '<Вспомнить свое прибытие в Трон Пантеона>', '<Вспомнить свое прибытие в Трон Пантеона>', 28153),
(141159, 'ruRU', 'Я – воплощение Света... и жара.', '', 28153),
(141158, 'ruRU', 'Духостранник?!', '', 28153),
(141157, 'ruRU', 'У нас НЕТ щупальцев на лице! Если бы были, то это бы означало, что дренеи – тайные агенты Бездны, которые втираются в доверие, чтобы внедриться в ваше общество и уничтожить его изнутри. Ты ведь не на ЭТО намекаешь... верно?', '', 28153),
(141156, 'ruRU', 'Извини, если мои татуировки кажутся тускловатыми. Забыл поставить свой аккумулятор на ночь на зарядку.', '', 28153),
(141155, 'ruRU', '|TInterface\\Icons\\ABILITY_DEVOUR.BLP:20|tРезан использует |cFFFF0000|Hspell:255371|h[Ужасающий образ]|h|r, прячьтесь!', '|TInterface\\Icons\\ABILITY_DEVOUR.BLP:20|tРезан использует |cFFFF0000|Hspell:255371|h[Ужасающий образ]|h|r, прячьтесь!', 28153),
(141154, 'ruRU', '', 'Хозяин... одари меня...', 28153),
(141153, 'ruRU', '', 'Я запущу в вас камнем как следует! Вот увидите!', 28153),
(141152, 'ruRU', '', 'Прочь, вонючие трогги!', 28153),
(141151, 'ruRU', '<Увидеть благословение Короны.>', '<Увидеть благословение Короны.>', 28153),
(141150, 'ruRU', '<Посмотреть видение Ветрокрылой.>', '<Посмотреть видение Ветрокрылой.>', 28153),
(141149, 'ruRU', '', 'Не подпускать детенышей к Ракжану!', 28153),
(141148, 'ruRU', '<Увидеть \"Правосудие Света\".>', '<Увидеть \"Правосудие Света\".>', 28153),
(141147, 'ruRU', '', 'Извини пожалуйста! Можешь помочь мне?', 28153),
(141146, 'ruRU', '<Увидеть решение Триумвирата.>', '<Увидеть решение Триумвирата.>', 28153),
(141145, 'ruRU', '<Увидеть побег с Аргуса.>', '<Увидеть побег с Аргуса.>', 28153),
(141144, 'ruRU', '', 'Не дайте детенышам сбежать!', 28153),
(141143, 'ruRU', 'Эй! Сюда! Эй! Эй!!!', '', 28153),
(141142, 'ruRU', 'Раненый терродактиль останавливается, чтобы передохнуть.', '', 28153),
(141141, 'ruRU', '<Увидеть прибытие Агграмара.>', '<Увидеть прибытие Агграмара.>', 28153),
(141140, 'ruRU', '', 'Смотрите! Получилось! Ого, как красиво! И опасно!', 28153),
(141139, 'ruRU', '', 'Вот это... сила! Ха-ха-ха!', 28153),
(141138, 'ruRU', 'Интересно... Значит, эти шпили служат им для перемещения. А денек-то богат на открытия.', '', 28153),
(141137, 'ruRU', 'Э-э, босс... $n? Кажется, у нас опять \"змеиная проблема\".', '', 28153),
(141136, 'ruRU', '<Ракжан гордо поднимает голову.>', '', 28153),
(141135, 'ruRU', '', 'Может, я и озарена Светом, но прекрасно знаю, как повеселиться в темноте.', 28153),
(141134, 'ruRU', '', 'Если меня как следует завести, светится все: глаза, татуировки и даже доспехи!', 28153),
(141133, 'ruRU', '', 'Необязательно быть из племени Небесного Рога, чтобы войти в клуб десятитысячников.', 28153),
(141132, 'ruRU', '', 'Знаешь, жизнь высоко в горах делает нас очень выносливыми. Хочешь, докажу?', 28153),
(141131, 'ruRU', '', 'Я знаю Этель. Вообще-то, она обычно ходит быстро, просто ей нравится подшучивать над туристами.', 28153),
(141130, 'ruRU', 'Неупокоенные кости превращаются в оживленного ящера!', 'Неупокоенные кости превращаются в оживленного ящера!', 28153),
(141129, 'ruRU', 'Древняя груда костей поблизости начинает шевелиться.', 'Древняя груда костей поблизости начинает шевелиться.', 28153),
(141128, 'ruRU', 'Даларан над Расколотыми островами', 'Даларан над Расколотыми островами', 28153),
(141127, 'ruRU', 'Принцесса – будущее Зандалара. Мы должны защищать ее.', 'Принцесса – будущее Зандалара. Мы должны защищать ее.', 28153),
(141126, 'ruRU', 'Когда верховный экзарх отправил меня на Азерот, я не хотел покидать его. Думал, что кто-то другой справится с этим заданием куда лучше.\n\nНо теперь я понимаю, почему он это сделал. Он хотел, чтобы я увидел хоть толику того, за что он и госпожа Аллерия сражались.\n\nНаша война окончена, но впереди еще множество битв. Легион повержен, но это не значит, что все демоны капитулировали.\n\n<Лотраксион сжал кулак и улыбнулся.>\n\nПо крайней мере, пока.', '', 28153),
(141125, 'ruRU', 'Мы служим принцессе.', 'Мы служим принцессе.', 28153),
(141124, 'ruRU', 'Что тебе от меня надо?', 'Что тебе от меня надо?', 28153),
(141123, 'ruRU', 'Деревья ожили! Хватайте топоры!', '', 28153),
(141122, 'ruRU', 'Т\'паартос!', '', 28153),
(141121, 'ruRU', '', 'Приступайте. И да хранит вас Свет.', 28153),
(141120, 'ruRU', '', 'Необычный выбор... но в рамках правил. $p, насколько я знаю, ты никогда не отказываешься от испытаний.', 28153),
(141119, 'ruRU', 'Ладно! Т\'паартос выбирает... тебя, малявка!', '', 28153),
(141118, 'ruRU', '', 'Последний, кто попытался справиться в одиночку, не вернулся живым. Найди напарника или возвращайся в казармы.', 28153),
(141117, 'ruRU', 'Т\'паартосу не нужна помощь!', '', 28153),
(141116, 'ruRU', '', 'Т\'паартос... я же тебе говорила. Испытание нельзя проходить в одиночку. Где твой напарник?', 28153),
(141115, 'ruRU', '', 'Но, если вы готовы, выйдите вперед и примите свою судьбу.', 28153),
(141114, 'ruRU', '', 'Если сомневаетесь – не рискуйте. Мы расценим это как мудрость, а не трусость.', 28153),
(141113, 'ruRU', '', 'Этот ритуал сломил многих достойных дренеев. Иные и вовсе не вернулись.', 28153),
(141112, 'ruRU', '', 'Вам придется заглянуть в самую глубину собственной души и узнать, кто вы на самом деле.', 28153),
(141111, 'ruRU', '', 'Осталось последнее, самое сложное из всех.', 28153),
(141110, 'ruRU', '', 'Солдаты! Испытания, которые вы уже прошли, доказали силу Света в ваших сердцах.', 28153),
(141109, 'ruRU', 'Кажется, то, что было внутри, забрали трогги.', '', 28153),
(141108, 'ruRU', '<Продолжить поиски детей>', '<Продолжить поиски детей>', 28153),
(141107, 'ruRU', 'Думаю, что $n лучше разбирается в таких вещах, чем ты, Ингрид.', '', 28153),
(141106, 'ruRU', '', 'Так не честно, я хотела сделать это!', 28153),
(141105, 'ruRU', 'Когда мы отправились в путешествие, \"Виндикар\" был не вполне обкатан, и все же, он доставил нас домой в целости.\n\nВсе эти улучшения того стоили, как считаешь?\n\nХотя нет, не отвечай. Это разобьет мне сердце.\n\nВечно все недооценивают работу инженеров.', '', 28153),
(141104, 'ruRU', 'Я нашел их! Наконец-то нашел.\n\n<В улыбке Аратора читается неуверенность.>\n\nЛюдей, которые дали мне жизнь... и которых никогда в ней не было. Я знаю, что они сражались за мою безопасность, что многим пожертвовали, но...\n\nМы не можем в мгновение ока стать счастливой семьей. Они ничего обо мне не знают, а я слышал лишь легенды о них. Нам предстоит заново познакомиться друг с другом. И пройдет немало времени, прежде чем застарелые обиды останутся в прошлом.\n\nИ все же, теперь у нас есть шанс.', '', 28153),
(141103, 'ruRU', '', 'Аллерия изменилась. Ее новую силу я не в состоянии постичь. Но, несмотря ни на что, она осталась моей любимой сестрой. Я это знаю.\n\nНовости о Сильване легли на ее сердце тяжким грузом. Им есть, что обсудить... при встрече.\n\nВетрокрылые должны собраться вновь. И есть только одно подходящее место для этого.', 28153),
(141102, 'ruRU', '', 'Ты еще здесь?\n\n<Ишана озадаченно смотрит на вас.>\n\nВсе кончено, иди домой.\n\n<Ишана машет на вас.>\n\nДавай-давай!', 28153),
(141101, 'ruRU', 'Кампания против Легиона оказалась долгой и изматывающей. Мы пересекли не один мир, промчались по самой Круговерти... Все ради победы.\n\nЯ устал, $n. Но отдыхать нам некогда.\n\nЗловещие видения Магни потрясли меня до глубины души. Остался лишь один титан, и мы должны защитить ее.', '', 28153),
(141100, 'ruRU', '', 'Смотрите! Получилось! Ого, как красиво! И опасно!', 28153),
(141099, 'ruRU', 'Невыносимо долго я мечтал вернуться на Аргус. Увидеть, что стало с родным домом. Спасти его...\n\n<Велен ненадолго замолкает.>\n\nЕго нельзя было спасти. Но все же нам удалось победить.\n\nЧто будет дальше? Я не знаю. Но я не собираюсь ждать спасительных видений. Я сделаю все возможное, чтобы помочь королю Андуину, подготовить его к встрече угрозой, таящейся во тьме.', '', 28153),
(141098, 'ruRU', '', 'Я всей душой жажду вернуться на Азерот вместе с Туралионом. Снова увидеть родные леса...\n\nНо...\n\nВериса рассказала, что случилось с Сильваной. И, пускай меня страшит эта встреча, я должна своими глазами увидеть, в кого она превратилась.\n\nОсталась ли она моей сестрой? Или превратилась в отринутое Светом чудовище?\n\nКонечно, я тоже изменилась. И моя новая сила также не вызывает доверия.\n\n<Аллерия глубоко вздыхает.>\n\nЯ должна сохранять спокойствие. Мне многое следует обдумать...', 28153),
(141097, 'ruRU', 'Наконец, война закончилась.\n\nПризнаюсь, подчас я сомневался, что мы доживем до этого дня. Столько битв... Столько утрат...\n\n<Туралион вздыхает, его переполняют чувства.>\n\nА теперь мы возвращаемся домой. В мир, где я не был тысячу лет.\n\nМоя былая жизнь давно минула. Пора начать новую. И воссоединиться с сыном, он для меня – воплощение всего, ради чего я сражался.', '', 28153),
(141096, 'ruRU', 'Великолепно, Ингрид. Даже без конфузов обошлось.', '', 28153),
(141095, 'ruRU', 'Я готов.', '', 28153),
(141094, 'ruRU', '', 'Э-э, босс... Нам бы пригодился щит от этой молнии!', 28153),
(141093, 'ruRU', '', 'Я так давно этого ждала! Отойдите!', 28153),
(141092, 'ruRU', 'Если какой-нибудь абориген еще хоть раз назовет меня ходячей люстрой, клянусь, я...', '', 28153),
(141091, 'ruRU', '', 'Вообще мне не особо симпатичны дрогбары, но когда я вижу, как эти брулы таскают железо... скажем так, я ощущаю огонь в недрах.', 28153),
(141090, 'ruRU', 'Ингрид, я собираюсь усилить самоцвет призывателя небес своей собственной магией. Отойди.', 'Ингрид, я собираюсь усилить самоцвет призывателя небес своей собственной магией. Отойди.', 28153),
(141089, 'ruRU', 'Нужно усилить самоцвет призывателя небес.', 'Нужно усилить самоцвет призывателя небес.', 28153),
(141088, 'ruRU', 'Глазам не верю... $n! Сюда!', '', 28153),
(141087, 'ruRU', '', 'Хи-хи... Я знала, что нас спасут. Ну, или просто сильно надеялась. Сюда!', 28153),
(141086, 'ruRU', '', 'Эй! $n! Я слышала о тебе. Помоги мне выбраться отсюда!', 28153),
(141085, 'ruRU', 'Меня спасает $n? Просто невероятно!', '', 28153),
(141084, 'ruRU', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t Вы |cFFF00000|Hspell:257459|h[на крюке]|h|r!', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t Вы |cFFF00000|Hspell:257459|h[на крюке]|h|r!', 28153),
(141083, 'ruRU', 'Их победа ближе, чем ты думаешь.', '', 28153),
(141082, 'ruRU', 'Отголоски ее шепота – самые громкие.', '', 28153),
(141081, 'ruRU', 'Горящие... те, что хранили равновесие... теперь исчезли... исчезли.', '', 28153),
(141080, 'ruRU', 'Всему виной твоя гордость.', '', 28153),
(141079, 'ruRU', 'Настает ночь. Ее песня закончится.', '', 28153),
(141078, 'ruRU', 'Прими свою судьбу. Всему суждено утонуть.', '', 28153),
(141077, 'ruRU', 'Трещины все шире.', '', 28153),
(141075, 'ruRU', '$n пробуждает груду костей!', '$n пробуждает груду костей!', 28153),
(141074, 'ruRU', 'Привет! Если у тебя потерялись спутники, я могу их найти.', '', 28153),
(141073, 'ruRU', 'Мне приходилось иметь дело с животными. Если захочешь, я помогу тебе с ними.', '', 28153),
(141072, 'ruRU', 'Мы пришли, как только смогли.', '', 28153),
(141071, 'ruRU', '', 'Готовьте чуму! Обрушим ее на головы врагов!', 28153),
(141070, 'ruRU', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_SHADOW:20|tВы находитесь под действием |cFFFF0000|Hspell:251570|h[Бомбы души]|h|r!', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_SHADOW:20|tВы находитесь под действием |cFFFF0000|Hspell:251570|h[Бомбы души]|h|r!', 28153),
(141069, 'ruRU', '|TInterface\\Icons\\INV_ELEMENTAL_MOTE_SHADOW01:20|tВы находитесь под действием |cFFFF0000|Hspell:250669|h[Взрывной души]|h|r!', '|TInterface\\Icons\\INV_ELEMENTAL_MOTE_SHADOW01:20|tВы находитесь под действием |cFFFF0000|Hspell:250669|h[Взрывной души]|h|r!', 28153),
(141068, 'ruRU', '', 'Ваша судьба в ваших руках, Умбрий. Я помогу вам заглушить голоса. Заставить тени служить вашей воле, а не наоборот.', 28153),
(141067, 'ruRU', '', 'Дурзаан хотел дать вам бессмертие. И сделать вас рабами собственного голода...', 28153),
(141066, 'ruRU', 'Аллерия... $p... Мы свободны, но мы стали... другими. И эти голоса...', '', 28153),
(141065, 'ruRU', '', 'Нет. Они не будут тебе служить. Они не твои.', 28153),
(141064, 'ruRU', 'Не-е-е-е-е-ет...', '', 28153),
(141063, 'ruRU', '', 'Я вижу тебя насквозь, Дурзаан. Ты лжешь.', 28153),
(141062, 'ruRU', 'Почему ты противишься? Тебя ждет великая судьба.', '', 28153),
(141061, 'ruRU', '', 'Шторм Бездны – всего лишь проводник... Портал, который нужно закрыть.', 28153),
(141060, 'ruRU', '', 'Твоим хозяевам, эфириал, не заполучить ни меня... ни моих братьев и сестер.', 28153),
(141059, 'ruRU', 'Чему бы ни учил тебя предатель... Мы с тобой на одной стороне, Ветрокрылая.', '', 28153),
(141058, 'ruRU', '', 'Я – девушка приличная и не позволяю трогать рога на первом свидании.', 28153),
(141057, 'ruRU', 'Имена значат так мало. Куда более интересный вопрос... кем вы станете?', '', 28153),
(141056, 'ruRU', '', 'Идем, $p. Нужно остановить трансформацию, пока их еще можно спасти.', 28153),
(141055, 'ruRU', 'Арррргх! Я ощущаю силу... она зовет... меняет меня...', '', 28153),
(141054, 'ruRU', '', 'Не слушай голоса, Умбрий! Сопротивляйся! За этот \"дар\" вы заплатите свободой.', 28153),
(141053, 'ruRU', '', 'Кто ты? Покажись!', 28153),
(141052, 'ruRU', 'Наконец-то... мое видение сбылось. Спасибо за то, что открыла путь.', '', 28153),
(141051, 'ruRU', '', 'А потом он сказал, что мои рога точь в точь как у черпорога, голова которого висела над камином в доме его дедушки. Умеет же испортить настроение...', 28153),
(141050, 'ruRU', 'У меня большие не только рога... посмотри, какие рульки.', '', 28153),
(141049, 'ruRU', 'Ха-ха! Узри мою силу, смертное существо, и знай – часть ее может стать твоей...', '', 28153),
(141048, 'ruRU', 'Впереди опасно, назад!', 'Впереди опасно, назад!', 28153),
(141047, 'ruRU', '', 'Зул прошел через наши войска, как нож сквозь масло. Теперь они без всяких преград движутся в Атал\'Дазар. Как ты планируешь это уладить, о мой король?', 28153),
(141046, 'ruRU', '', 'Растахан, мы еле дождались, когда ты уделишь нам время.', 28153),
(141045, 'ruRU', 'Трудно сказать, хороший ли Зул стратег, или просто хороший пророк. В любом случае, пока что он во всем на шаг впереди нас.$b$bОн собирается заменить меня останками нашего старого короля Дазара.$b$bЯ был бы рад увидеть возрождение прежнего могущества троллей, но не желаю расплачиваться за темную ересь, к которой обратился Зул.', '', 28153),
(141044, 'ruRU', '', 'Даже старому Бвонсамди станет не по себе от того, что я с тобой сделаю.', 28153),
(141043, 'ruRU', '', 'Я сотворю с твоей душой ужасные вещи.', 28153),
(141042, 'ruRU', '', 'Смерть не освободит тебя от страданий.', 28153),
(141041, 'ruRU', '', 'Сначала я убью тебя, а затем как следует над тобой поработаю.', 28153),
(141040, 'ruRU', '', 'Вторжение в мой храм? О, это карается смертью.', 28153),
(141039, 'ruRU', '', 'Растахан здесь? Отлично. Отведи меня к этому запоздалому гостю.', 28153),
(141038, 'ruRU', 'Я хотел только помочь.', '', 28153),
(141037, 'ruRU', 'Впереди – лишь ослепительная красота горящего мира.', '', 28153),
(141036, 'ruRU', 'Посмотрите-ка, кто у нас тут могучий герой... ха!', '', 28153),
(141035, 'ruRU', '', 'Путь к сердцу женщины лежит через массаж копыт. Поверь моему опыту.', 28153),
(141034, 'ruRU', '', 'Таурены – хорошие поэты. Их стихи такие му-у-удрые.', 28153),
(141033, 'ruRU', '', 'Бр-р-р! Ну и холодина. Хочешь мороженку?', 28153),
(141032, 'ruRU', '', 'Наши собратья из племени Речной Гривы всегда такие спокойные, потому что научились плыть по течению.', 28153),
(141031, 'ruRU', '', 'Знаешь, что получится, если накормить крутогорских тауренов шоколадом? Конфеты \"Коровка\"!', 28153),
(141030, 'ruRU', 'Ты пытаешься повесить шляпу на мои рога? Серьезно? Я похож на вешалку?', '', 28153),
(141029, 'ruRU', 'Что пахнет хуже, чем дрогбар? Два дрогбара. Что пахнет хуже двух дрогбаров? Пока никто не выяснил – запах двоих и так убивает на месте.', '', 28153),
(141028, 'ruRU', 'Встретились как-то раз таурен, яунгол и таунка. Это не анекдот – так прошло воссоединение моей семьи.', '', 28153),
(141027, 'ruRU', 'Ха! Однажды мой приятель уговорил искателя приключений в эпичнейшем снаряжении пинать рыбу в реку! Так, стоп... это же ты, да?', '', 28153),
(141026, 'ruRU', 'Я, конечно, обычный таурен с горы, но по крайней мере я не роюсь в навозе в поисках добычи.', '', 28153),
(141025, 'ruRU', 'Давай сыграем в игру. Будем пить каждый раз, как какая-нибудь гарпия прокричит про камень и прах.', '', 28153),
(141024, 'ruRU', 'Что, еще кого-то приютить? Ну вроде на рогах еще место оставалось.', '', 28153),
(141023, 'ruRU', '', 'Размер рогов не имеет значения. Важно, как двигается тотем.', 28153),
(141022, 'ruRU', '', 'Хватит пялиться на мои рульки!', 28153),
(141020, 'ruRU', '', 'Хочешь проверить мои рога на прочность?', 28153),
(141018, 'ruRU', 'Ты, наверное алхимик? Я чувствую между нами химию.', '', 28153),
(141017, 'ruRU', 'Не стесняйся, можно и пожестче. У меня крепкая шкура.', '', 28153),
(141016, 'ruRU', 'Вместе мы можем сделать больше Крутогорья.', '', 28153),
(141015, 'ruRU', 'Мой тотем гремит. Всю. Ночь. Напролет.', '', 28153),
(141014, 'ruRU', 'Доверься мне... Я – мастер исследовать глубины.', '', 28153),
(141013, 'ruRU', 'Хочешь посмотреть спальни \"Виндикара\"? Могу устроить индивидуальную экскурсию.', '', 28153),
(141012, 'ruRU', '', 'Тебе просто обязательно нужно зайти на одну из вечеринок в Квартале Звезд. Я еще не встречала никого, кому была бы так необходима маска.', 28153),
(141011, 'ruRU', '', 'Ночные эльфы? Скорее уж деревенские! А что? Живут на деревьях, спят в берлогах... иногда даже рога отращивают. Они просто не приспособлены для жизни в городе.', 28153),
(141010, 'ruRU', '', 'Как-то один калдорай сказал, что мое платье – последний писк моды... Десятитысячелетней давности. Знаешь, как обидно было? Ночные эльфы точно не отличаются чувством такта.', 28153),
(141009, 'ruRU', '', 'Несмотря на возраст, Тиранда выглядит отменно. Как думаешь, она свободна?', 28153),
(141008, 'ruRU', '', 'Хочешь бокальчик чародейского вина? Я сама давила ягоды.', 28153),
(141007, 'ruRU', '', 'Розы прекрасны, как Сурамар. ЭТО ИЛЛЮЗИЯ?! Или кошмар?', 28153),
(141006, 'ruRU', '', 'Это аллюзия! На что ты намекаешь?', 28153),
(141005, 'ruRU', 'Ладно, признаю. Посадить огромного злого динозавра в клетку в зоопарке возможно было и не лучшей идеей. А вообще, я тут слышал в Нордсколе водятся очень красивые протодраконы...', '', 28153),
(141004, 'ruRU', 'Интересно, почему центр Сурамара называют Кварталом Звезд? Я провел там немало времени, но так и не встретил ни одной знаменитости.', '', 28153),
(141003, 'ruRU', 'Когда я был молод, существовал только один вид эльфов. ОДИН.', '', 28153),
(141002, 'ruRU', 'Это моя работа. Я пью чародейское вино и знаю всякие штуки.', '', 28153),
(141001, 'ruRU', 'Меня зовут Рой, и я тут подсел на магию.', '', 28153),
(141000, 'ruRU', 'Не могу понять, почему меня все просят повторить эту фразу! Ну ладно. Это иллюзия. Что ты скрываешь?', '', 28153),
(140999, 'ruRU', 'Вообще-то, большую часть времени все тут было очень даже так...', '', 28153),
(140998, 'ruRU', '', 'Предлагаешь пойти ко мне? А ты знаешь тактику?', 28153),
(140997, 'ruRU', '', 'Я видела одни и те же лица 10000 лет. Так что я совсем не против разнообразия.', 28153),
(140996, 'ruRU', '', 'Я покажу тебе мои силовые линии, если ты покажешь свои.', 28153),
(140995, 'ruRU', '', 'Анимация? Детонация? Может, сразу перейдем к репликации?', 28153),
(140994, 'ruRU', '', 'Знаешь, сурамарские ночи бывают очень даже жаркими.', 28153),
(140992, 'ruRU', '', 'Никаких иллюзий. Все, что ты видишь, очень даже настоящее.', 28153),
(140991, 'ruRU', '', 'Это у тебя в кармане иллюзия? Или ты просто рад меня видеть?', 28153),
(140990, 'ruRU', 'Ты напоминаешь мне плод Аркан\'дора. И мне кажется ты не хуже него сможешь утолить мою жажду...', '', 28153),
(140989, 'ruRU', 'Звезды судили тебя и сочли... горячей штучкой.', '', 28153),
(140988, 'ruRU', 'У меня такое чувство, что мы были ночно-рождены друг для друга.', '', 28153),
(140987, 'ruRU', 'Глядя на тебя, я чувствую... помрачение.', '', 28153),
(140986, 'ruRU', 'М-м-м, а можно потрогать твою силовую линию?', '', 28153),
(140985, 'ruRU', 'Путь к сердцу сурамарского мужчины лежит через катакомбы.', '', 28153),
(140984, 'ruRU', 'Наверное, ты тоже маг, потому как только я увидел тебя, все окружающие вдруг для меня исчезли.', '', 28153),
(140983, 'ruRU', 'Наверное, твое тело создано из чистой магии – меня так к нему и тянет.', '', 28153),
(140982, 'ruRU', '', 'Туралион был единственным человеком, которого я встретила за тысячу лет. Я думала, они все седые и со шрамами.', 28153),
(140981, 'ruRU', '', 'Мне нравится быть озаренной. Но минус в том, что СЕЛФИ всегда засвечены.', 28153),
(140980, 'ruRU', '', 'Мы еще не разбили \"Виндикар\"... Но, учитывая наш послужной список, это лишь вопрос времени.', 28153),
(140979, 'ruRU', '', 'Не советую ходить по \"Виндикару\" босыми копытами. На полу постоянно валяются обломки кристаллов.', 28153),
(140978, 'ruRU', '', 'И как вы только живете с этими пальцами на ногах. С копытами педикюр занимает намного меньше времени.', 28153),
(140977, 'ruRU', '', 'Хочешь, покажу тебе мою ферму? Я развожу милейших аркенон-поросят.', 28153),
(140976, 'ruRU', '', 'Нет, у меня нет сияющего штрих-кода над хвостом.', 28153),
(140975, 'ruRU', 'Жизнь за Айур... <кхм> Аргус. Жизнь за АРГУС!', '', 28153),
(140974, 'ruRU', 'Как же приятно наконец пройтись по земле. Когда целый день ходишь по жестким палубам, потом ужасно болят копыта!', '', 28153),
(140973, 'ruRU', 'Этот ваш мир очень странный. Говорящие медведи, которые занимаются кунг-фу? На Аргусе мы называем такое цирком.', '', 28153),
(140972, 'ruRU', 'Я думал, что на языке наару моя татуировка означает \"Защитник Света\". А оказалось, \"Светящийся козел\".', '', 28153),
(140971, 'ruRU', '', 'Когда кажется, нужно... трогать что-нибудь светящееся.', 28153),
(140970, 'ruRU', 'Мне кажется, или тут стало светлее? Наверное, я просто рад тебя видеть.', '', 28153),
(140969, 'ruRU', 'Ее кровь наполняет его силой. Твоя послужит для того же.', '', 28153),
(140968, 'ruRU', '|TINTERFACE\\ICONS\\SPELL_ARCANE_MINDMASTERY.BLP:20|t Ваш разум подвергается |cFFFF0000|Hspell:244172|h[Псионной атаке]|h|r!', '|TINTERFACE\\ICONS\\SPELL_ARCANE_MINDMASTERY.BLP:20|t Ваш разум подвергается |cFFFF0000|Hspell:244172|h[Псионной атаке]|h|r!', 28153),
(140967, 'ruRU', 'Пора уходить, нам нельзя здесь оставаться.', 'Пора уходить, нам нельзя здесь оставаться.', 28153),
(140966, 'ruRU', '', 'Будь прокляты трусы из Зулдазара, что не разделались с этой угрозой раньше! Мой отец думал, она исчезнет сама, – как глупо с его стороны.\n\nСейчас нам мало просто убить Атину. Все куда хуже, чем я могла себе представить.', 28153),
(140965, 'ruRU', 'Моя служба... окончена...', '', 28153),
(140964, 'ruRU', 'Прости меня, моя королева.', '', 28153),
(140963, 'ruRU', 'Моя королева... я подвел тебя...', '', 28153),
(140962, 'ruRU', 'Никому не дозволено приближаться к королеве!', '', 28153),
(140961, 'ruRU', 'Королеву нельзя тревожить!', '', 28153),
(140960, 'ruRU', 'Я буду защищать королеву вечно! Уходи!', '', 28153),
(140959, 'ruRU', '', 'Что за... Мы не подозревали что у них есть подобное! Почему отец их недооценивал?!', 28153),
(140958, 'ruRU', '', 'Приготовься, $n. Мы не представляем, что нас ждет.', 28153),
(140957, 'ruRU', '<Не будить спящего пса – как правило, мудрый совет.>', '', 28153),
(140954, 'ruRU', 'Люблю все делать при свете. Не то чтобы у меня был выбор...', '', 28153),
(140953, 'ruRU', '', 'Давай вернемся на мой корабль и устроим круговерть в пустоте.', 28153),
(140952, 'ruRU', '', 'Должно быть, в твоем роду были наару... потому что у тебя просто неземное тело.', 28153),
(140950, 'ruRU', '', 'Она должна быть неподалеку. Я не отступлюсь, мы были так близки, чтобы ее убить!', 28153),
(140949, 'ruRU', '', 'Атина, ты не уйдешь! И темное вуду тебе не поможет!', 28153),
(140945, 'ruRU', 'Генерал Эрод покидает свою капсулу!', 'Генерал Эрод покидает свою капсулу!', 28153),
(140944, 'ruRU', 'Главный инженер Ишкар покидает свою капсулу!', 'Главный инженер Ишкар покидает свою капсулу!', 28153),
(140942, 'ruRU', 'Адмирал Свиракс покидает свою капсулу!', 'Адмирал Свиракс покидает свою капсулу!', 28153),
(140939, 'ruRU', '', 'Вы познаете силу Г\'ууна! Безнадежно пытаться нас остановить! Я покажу вам...', 28153),
(140938, 'ruRU', '', 'Бедная Таланджи! Мы – дети могучего лоа. Тебе никогда не победить нас!', 28153),
(140937, 'ruRU', '', 'Тебе не запугать меня, Атина. Я убью и тебя, и твоего хозяина, кем бы он ни был!', 28153),
(140936, 'ruRU', '', 'Я спрячусь и дождусь подходящего момента, чтобы напасть. Вместе мы одолеем Атину!', 28153),
(140930, 'ruRU', 'Я на свободе!', 'Вечная неволя!', 28153),
(140929, 'ruRU', 'Замучаю!', 'Зак\'ражан всех предал!', 28153),
(140928, 'ruRU', 'Смерть Зак\'ражану!', 'От Зак\'ражана не уйти!', 28153),
(140927, 'ruRU', 'Ма\'да! Я видел, к северо-западу вроде было какое-то движение.', '', 28153),
(140926, 'ruRU', 'Приветствую тебя, ма\'да! Здесь все тихо.', '', 28153),
(140925, 'ruRU', 'Приветствую, ма\'да! У меня плохие новости. Мы потеряли след чужаков, которые убили подручных Наджимы.', '', 28153),
(140924, 'ruRU', '', 'Найди меня, когда закончишь, $n. Заставь троллей крови страдать за это святотатство!', 28153),
(140923, 'ruRU', '', 'Я не могу оставить тела павших... Эти монстры осквернят их!', 28153),
(140922, 'ruRU', 'Я топором деревья рублю, а это почти то же самое.', '', 28153),
(140921, 'ruRU', 'Этот топор сделан, чтобы рубить! И будет рубить!', '', 28153),
(140920, 'ruRU', 'Пауки... деревянные чудовища... Я их всех порешу!', '', 28153),
(140919, 'ruRU', '', '|TInterface\\Icons\\ABILITY_CREATURE_POISON_02:20|tОткрывается портал Скверны в Ранкору!', 28153),
(140918, 'ruRU', '', '|TInterface\\Icons\\SPELL_HOLY_CONSUMEMAGIC:20|tОткрывается мрачный портал в Натрезу!', 28153),
(140917, 'ruRU', '', '|TInterface\\Icons\\SPELL_MAGE_FLAMEORB:20|tОткрывается огненный портал в Зорот!', 28153),
(140916, 'ruRU', 'Я не вернусь в заточение!', 'Я сожру твою душу!', 28153),
(140915, 'ruRU', '|cffffff00Исследование выполнено|r', '|cffffff00Исследование выполнено|r', 28153),
(140914, 'ruRU', '', 'Еще немножко тотемов... Все, я готова!', 28153),
(140912, 'ruRU', 'Ладно пауки, но живые деревья? Я пас!', '', 28153),
(140911, 'ruRU', 'Я всю жизнь рублю деревья, но обычно они не сопротивляются!', '', 28153),
(140910, 'ruRU', 'Деревья ожили! Спасайся кто может!', '', 28153),
(140909, 'ruRU', '', 'Иди за мной. Я сделаю так, чтобы наш уход не заметили.', 28153),
(140907, 'ruRU', '', 'Шевелись. Кто знает, вдруг эта штука решит возродиться?', 28153),
(140906, 'ruRU', '', 'Ничего себе, сколько артефактов! Мне нужна сумка побольше!', 28153),
(140905, 'ruRU', 'Все молодцы! Хватайте что угодно, пока есть возможность.', '', 28153),
(140904, 'ruRU', '', 'Еще и пару блестяшек прихвачу.', 28153),
(140903, 'ruRU', '', 'Ах да, надо не забыть глаз голема с душой в нем. Тача делает из них крохотные, но очень мощные бомбы.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140902, 'ruRU', '', 'Проклятые идолы! Тача их любит... А реагентов-то сколько!', 28153),
(140901, 'ruRU', '', 'Давай посмотрим, что из этого магического барахла стоит взять.', 28153),
(140900, 'ruRU', '', 'Хорошие трофеи, $p. Лучшие из них я возьму, естественно для команды.', 28153),
(140899, 'ruRU', '', 'В основном обычное зандаларское оружие... О, а вот это, кажется, зачаровано!', 28153),
(140898, 'ruRU', '', 'Отличный бой. Давай-ка посмотрим, что у них тут есть.', 28153),
(140897, 'ruRU', 'Защищать жрицу! Никого не пускать!', 'Защищать жрицу! Никого не пускать!', 28153),
(140896, 'ruRU', 'Мы разобьем лагерь рядом, в руинах. А вы будьте осторожны. У меня дурное предчувствие.', '', 28153),
(140895, 'ruRU', 'Тебе пришлось быть на посылках у Лоти? По мне, нужно было проклясть это чудище, и дело с концом. Но торговцы жалуются, когда я так делаю.', '', 28153),
(140894, 'ruRU', '', 'Что-то спугнуло одного из брутозавров, и он пустился бежать. Хаос в городе нам точно не нужен. Помоги торговцам спасти товар, пока этот ящер тут все не растоптал!', 28153),
(140893, 'ruRU', '', 'Спасибо тебе. Дети нынче не уважают старших и тащат все, что плохо лежит. Вот в мое время...', 28153),
(140892, 'ruRU', '', 'На помощь! Малыши взяли наши свитки и превратились в животных. Вот свиток рассеивания. Используй его рядом с малышами. Только осторожно!', 28153),
(140891, 'ruRU', 'Прежде чем погибнуть, знай, что остальные твои сородичи буду служить нам в цепях!', '', 28153),
(140890, 'ruRU', 'Ваше жалкое отродье узнает свое место.', '', 28153),
(140889, 'ruRU', 'Все вы падете под нашими мечами.', '', 28153),
(140888, 'ruRU', 'Орда и Альянс падут!', '', 28153),
(140887, 'ruRU', 'Месть за императора!', '', 28153),
(140886, 'ruRU', 'Отомстим за Лэй Шэня!', '', 28153),
(140885, 'ruRU', 'Зул обещал, что мы отомстим твоему народу.', '', 28153),
(140880, 'ruRU', 'Диномант Киш\'о взывает о помощи!', 'Диномант Киш\'о взывает о помощи!', 28153),
(140869, 'ruRU', 'Поскорее достраивайте казармы.', '', 28153),
(140860, 'ruRU', 'Ой, кто там? Сюда! Помоги мне, пожалуйста!', '', 28153),
(140859, 'ruRU', '', 'Спасибо за помощь, $p. Заходи внутрь, когда подготовишься.', 28153),
(140858, 'ruRU', '', 'Я согласна. Это не наш бой. Пора уходить.', 28153),
(140857, 'ruRU', 'Все происходит слишком быстро. Теперь нам хватит припасов, чтобы напасть на сетраков.', '', 28153),
(140856, 'ruRU', 'Отправь меня на рудник Сухоусов.', 'Отправь меня на рудник Сухоусов.', 28153),
(140855, 'ruRU', 'Нанять гоблина-бомбиста.', 'Нанять гоблина-бомбиста.', 28153),
(140854, 'ruRU', 'Я пойду вперед и разведаю местность. Ты займешься призраками, а я заберу припасы.', 'Я пойду вперед и разведаю местность. Ты займешься призраками, а я заберу припасы.', 28153),
(140853, 'ruRU', '', 'Сначала тебе придется убить големов. Потом возьми тотемы и вытяни души из их тел.', 28153),
(140852, 'ruRU', 'Внутри постарайся двигаться как можно быстрее. Следующее место встречи – в дальней части руин, рядом с подземным залом.', '', 28153),
(140851, 'ruRU', 'Надежды нет! Все эти пустые обещания – ложь!', '', 28153),
(140850, 'ruRU', 'Ложь! Все это ложь!', '', 28153),
(140849, 'ruRU', 'Я не хочу это видеть! НЕТ!!!', '', 28153),
(140848, 'ruRU', 'Ты лишь марионетка. Даже смерть не принесет тебе избавления!', '', 28153),
(140847, 'ruRU', 'Покорись Г\'ууну!', '', 28153),
(140846, 'ruRU', '', 'Смерть меня не остановит...', 28153),
(140845, 'ruRU', '', 'Все подчинятся... Матери...', 28153),
(140844, 'ruRU', 'Ну вот, готово! В тебе дух тролля крови... ты превратишься, когда приблизишься к их деревне.', '', 28153),
(140843, 'ruRU', '', 'Это еще не конец...', 28153),
(140842, 'ruRU', '', 'Ковен... вездесущ...', 28153),
(140841, 'ruRU', '', 'Друствар наш!', 28153),
(140840, 'ruRU', '', 'Сопротивляться бесполезно.', 28153),
(140839, 'ruRU', '', 'Ты покоришься Матери!', 28153),
(140838, 'ruRU', '', 'Ковен захватит ваш городишко!', 28153),
(140837, 'ruRU', '', 'А вот и Оми с докладом разведки.', 28153),
(140836, 'ruRU', '', 'У меня дурные вести. Я обнаружила здесь призраков. Объявляю оранжевый уровень угрозы.', 28153),
(140834, 'ruRU', '', 'Пока ты займешься этим, я посмотрю, что там в руинах. Когда закончишь, приходи к месту встречи.', 28153),
(140833, 'ruRU', '', 'Не трать время на каждого голема. Найди среди них исправного.', 28153),
(140832, 'ruRU', 'Отправь меня на Кряж лесорубов.', 'Отправь меня на Кряж лесорубов.', 28153),
(140831, 'ruRU', 'Прежде чем отправиться сражаться в руины, мы соберемся в нашем месте встречи, на сломанном мосту.', '', 28153),
(140830, 'ruRU', 'Так, задания все получили? Удачной охоты.', '', 28153),
(140829, 'ruRU', 'Следуй за мной. Король Растахан где-то рядом.', 'Следуй за мной. Король Растахан где-то рядом.', 28153),
(140828, 'ruRU', '', 'Оружие к бою. Кто-то идет...', 28153),
(140827, 'ruRU', '', 'Когда Зул потребовал отдать ему останки Дазара, первого короля, мы думали, он шутит.$b$bИ прогнали его.$b$bТогда еще никто не знал, что у него есть армия, чтобы захватить наш храм.', 28153),
(140826, 'ruRU', 'В руинах полно сокровищ. Главное – не торопиться и все сделать как надо.', '', 28153),
(140825, 'ruRU', '', 'Ма\'да? Ма\'да, где ты?', 28153),
(140824, 'ruRU', '<Уинстоун открывает комплект карт. Откуда у него столько золота?>', '', 28153),
(140823, 'ruRU', '<Уинстоун уставился на карты у себя в руке.>', '', 28153),
(140822, 'ruRU', '<Уинстоун колдует над своей коллекцией карт, пытаясь составить новую колоду.$b$bПохоже, он переборщил со зверями.>', '', 28153),
(140821, 'ruRU', 'Отправь меня в Ар\'горок.', 'Отправь меня в Ар\'горок.', 28153),
(140820, 'ruRU', 'Чтобы найти Зал\'зикса, сначала надо отыскать Сетралисс.', '', 28153),
(140818, 'ruRU', 'Зак\'ражан использует наши души в качестве оружия. Вы обречены.', '', 28153),
(140817, 'ruRU', 'Это оружие бесполезно. Его защищают наши души.', '', 28153),
(140816, 'ruRU', 'Еще один труп для Зак\'ражана!', '', 28153),
(140815, 'ruRU', 'Твоя душа присоединится к остальным – в этом големе!', '', 28153),
(140814, 'ruRU', 'Выпусти нас...', '', 28153),
(140813, 'ruRU', 'Зак\'ражан – наш владыка...', '', 28153),
(140812, 'ruRU', 'Смерть чужестранцам!', '', 28153),
(140811, 'ruRU', 'Никаких королей. Только Зак\'ражан.', '', 28153),
(140810, 'ruRU', 'Давай, найди пропавшую маму, и пусть они снова будут вместе!', '', 28153),
(140809, 'ruRU', 'Хе-хе... малышка права. Ее мама не на Той Стороне.', '', 28153),
(140808, 'ruRU', 'Никаких лоа. Только Зак\'ражан.', '', 28153),
(140807, 'ruRU', 'Защитить двор любой ценой.', '', 28153),
(140806, 'ruRU', 'Помоги нам...', '', 28153),
(140805, 'ruRU', 'Еще одна жертва... для Зак\'ражана.', '', 28153),
(140804, 'ruRU', 'О-о, ты служишь какому-то культу? Если захочешь сменить веру, только скажи.', '', 28153),
(140803, 'ruRU', 'От кровомошек нынче спасу нет.', 'От кровомошек нынче спасу нет.', 28153),
(140802, 'ruRU', 'Ай!', 'Ой!', 28153),
(140801, 'ruRU', 'Понаехало криворуких.', 'Понаехало криворуких.', 28153),
(140800, 'ruRU', 'Эй! Смотри, куда тычешь эту штуку!', 'Эй! Смотри, куда тычешь эту штуку!', 28153),
(140799, 'ruRU', 'Чертовы чужаки...', 'Чертовы чужаки...', 28153),
(140798, 'ruRU', 'Ай! Какого черта ты творишь?!', 'Ай! Какого черта ты творишь?!', 28153),
(140797, 'ruRU', 'Мы проиграли. Пылающий Легион не остановить.', '', 28153),
(140796, 'ruRU', 'Гнусные мародеры! Я тут хозяин!', '', 28153),
(140795, 'ruRU', 'Смертные пали. Гибель всех миров неизбежна.', '', 28153),
(140794, 'ruRU', 'Стихии повинуются зову Орды. Так и должно быть.', '', 28153),
(140793, 'ruRU', '', 'Обитель духов готова принять тебя. Что надо?', 28153),
(140792, 'ruRU', 'Даже лоа покинули нас.', 'Даже лоа покинули нас.', 28153),
(140791, 'ruRU', 'Мы в рабстве у Зак\'ражана несчетные столетия. Освободи нас...', 'Мы в рабстве у Зак\'ражана несчетные столетия. Освободи нас...', 28153),
(140790, 'ruRU', 'Духи – грозное оружие... если ты можешь с ними совладать.', 'Духи – грозное оружие... если ты можешь с ними совладать.', 28153),
(140789, 'ruRU', 'Наши души служат ему защитой. Эту преграду оружием не пробить.', 'Наши души служат ему защитой. Эту преграду оружием не пробить.', 28153),
(140788, 'ruRU', 'Нам обещали несметные богатства. Но вместо этого угнали в рабство!', 'Нам обещали несметные богатства. Но вместо этого угнали в рабство!', 28153),
(140787, 'ruRU', 'Зак\'ражан запрещает нам поклоняться лоа. Мы должны чтить только его.', 'Зак\'ражан запрещает нам поклоняться лоа. Мы должны чтить только его.', 28153),
(140786, 'ruRU', 'Почему Бвонсамди не пускает нас на Ту Сторону?', 'Почему Бвонсамди не пускает нас на Ту Сторону?', 28153),
(140785, 'ruRU', 'Зак\'ражан заточил наши души в големов. Он заставляет нас служить ему.', 'Зак\'ражан заточил наши души в големов. Он заставляет нас служить ему.', 28153),
(140784, 'ruRU', 'Надеюсь, волки проголодались. Новоземье наше, и мы можем приступать к обучению наездников!', '', 28153),
(140783, 'ruRU', 'Оружейная готова. Разжигайте горны!', '', 28153),
(140781, 'ruRU', 'Строительство оружейной завершено. Что прикажешь?', '', 28153),
(140780, 'ruRU', 'Зак\'ражан должен заплатить за то, что заточил нас здесь!', 'Зак\'ражан должен заплатить за то, что заточил нас здесь!', 28153),
(140779, 'ruRU', 'Сетралисс хранит нас.', 'Сетралисс хранит нас.', 28153),
(140778, 'ruRU', '', 'Покойся с миром, милая Каджа. Мы тебя не забудем.', 28153),
(140777, 'ruRU', 'Султис был самым первым хранителем. Ему потребовалась наша с Кортеком помощь, чтобы запечатать тело Митракса в великой пирамиде.\n\nВместе мы создали магический барьер и заперли тело внутри.\n\nКаждый из нас создал ключ, наполненный нашей силой, чтобы никто не мог открыть гробницу.', '', 28153),
(140776, 'ruRU', 'Тихо, тихо, нам не нужно драться. Давайте просто присядем, выпьем и позагадываем загадки!', '', 28153),
(140775, 'ruRU', 'Ты не принимаешь Уинстоуна всерьез? Тогда смотри, как ловко утрет тебе он нос!', '', 28153),
(140774, 'ruRU', 'Я знаю Растахана, могущественного вечного короля. Ему следует аккуратнее выбирать своих протеже.', '', 28153),
(140773, 'ruRU', 'Думаешь, ждут тебя приключения? А не желаешь отведать печенья?', '', 28153),
(140772, 'ruRU', 'В \"Ледяной дукер\" заходи, не робей. В Зандаларе нигде нет напитков вкусней!', '', 28153),
(140771, 'ruRU', 'Это сердце приведет нас к Сетралисс.', '', 28153),
(140770, 'ruRU', 'Сердце связано с жизненной силой нашей лоа. Увиденное тобой красное свечение означает, что она в беде. Но гораздо важнее, что она еще жива!', '', 28153),
(140769, 'ruRU', 'Если ты говоришь правду, нам надо спешить!', '', 28153),
(140768, 'ruRU', 'Любопытно...', '', 28153),
(140767, 'ruRU', 'Нет-нет, мертвяком ты мне ни к чему. Я верну тебя к жизни... за определенную плату.', '', 28153),
(140766, 'ruRU', 'А ты чего тут делаешь? Твое время еще не пришло.', '', 28153),
(140764, 'ruRU', '', 'Она не знала, что это превратит джунгли в пустыню...', 28153),
(140762, 'ruRU', 'А-а-а!', '', 28153),
(140761, 'ruRU', 'Наш храм не достанется Отступникам.', '', 28153),
(140760, 'ruRU', 'Я использую их силу, чтобы исказить потоки времени.', '', 28153),
(140759, 'ruRU', 'А вы, все остальные, больше не вмешивайтесь в мои дела. Кто вмешается – заплатит.', '', 28153),
(140758, 'ruRU', 'Теперь возвращайся в свою темницу и страдай.', '', 28153),
(140757, 'ruRU', 'Я с двойными агентами дел не имею.', '', 28153),
(140756, 'ruRU', 'Пожалуйста, Бвонсамди, давай договоримся! Буду бить в барабаны каждый день! Мои люди будут молиться тебе вечно!', '', 28153),
(140755, 'ruRU', 'Я тоже ищу Ракиру. Змеюки говорят, тебе удалось ее отыскать. \n\nКак славно, что мы все снова будем вместе – если, конечно, они выпустят меня из клетки.', '', 28153),
(140754, 'ruRU', 'Тебе никогда не перейти на Ту Сторону. Никогда не увидеть предков. Ты теперь здесь навечно.', '', 28153),
(140753, 'ruRU', 'Да. Бвонсамди обид не прощает.', '', 28153),
(140752, 'ruRU', 'Но тебя обуяла гордыня. И ты запретил поклоняться всем лоа, велел почитать только тебя. Ты помнишь это?', '', 28153),
(140751, 'ruRU', 'изменить', 'изменить', 28153),
(140750, 'ruRU', 'У нас был уговор. Ты получаешь силу, а я – поклонение твоего народа.', '', 28153),
(140749, 'ruRU', 'Если ты во все это веришь, Зак\'ражан, то ты не только бессовестный, но и тупой.', '', 28153),
(140748, 'ruRU', 'Зандалар таит в себе много секретов. Возможно, нам попался тот, который не следует раскрывать.', '', 28153),
(140747, 'ruRU', '', 'Джакра\'зет поплатится за предательство.', 28153),
(140746, 'ruRU', 'Бвонсамди, никчемный старик, наконец-то я победил тебя!', '', 28153),
(140745, 'ruRU', 'Да! Наконец-то я воссоединюсь с предками в Темных землях!', '', 28153),
(140743, 'ruRU', 'Кто такие хранители?', 'Кто такие хранители?', 28153),
(140742, 'ruRU', 'Что это такое? Неужели моя душа наконец-то свободна?', '', 28153),
(140740, 'ruRU', 'Кто такая Сетралисс?', 'Кто такая Сетралисс?', 28153),
(140739, 'ruRU', 'Отступники – это воинственные сетраки, во главе которых стоит император Кортек.\n\nКогда-то давно мы жили в мире друг с другом – так, как хотела бы Сетралисс. \n\nПосле предательства Кортека отступники начали войну в этих землях. \n\nОни не остановятся, пока не подчинят себе весь мир.', '', 28153),
(140738, 'ruRU', 'Кортек – кто это?', 'Кортек – кто это?', 28153),
(140737, 'ruRU', 'Наш храм не достанется Отступникам.', '', 28153),
(140736, 'ruRU', 'Каз\'горот! Пусть герои станут подобны нам!', '', 28153),
(140735, 'ruRU', '', 'Восстаньте, герои! Сражайтесь за свой мир!', 28153),
(140734, 'ruRU', '', 'Надежда еще есть, Великий отец. В этих смертных еще не угасла искра жизни.', 28153),
(140733, 'ruRU', 'Нет! После стольких жертв... Все не может закончиться так!', '', 28153),
(140732, 'ruRU', 'Порабощенный, мне подчиняется само время! Сила, что укротит твой гнев!', '', 28153),
(140731, 'ruRU', 'Смертные не выстояли. Последнего титана... не спасти.', '', 28153),
(140730, 'ruRU', 'Ярость Порабощенного рвется наружу! Расправьтесь с этими сущностями!', '', 28153),
(140729, 'ruRU', '', 'Спасибо за помощь! Если захочешь с нами поохотиться – милости просим! Грифон доставит тебя на Мыс Рыбака. А мы тут приберемся.', 28153),
(140727, 'ruRU', '', 'Можно ли доверять Серрику? Думаешь, этот сетрак поможет нам найти Зал\'зикса?', 28153),
(140725, 'ruRU', '', 'Это дело рук Джакра\'зета? Он уже добрался до Зал\'зикса?', 28153),
(140724, 'ruRU', 'Слава! Слава морю!', '', 28153),
(140723, 'ruRU', 'Прилив не остановить...', '', 28153),
(140722, 'ruRU', 'Ифис яхф ан\'зиг...', '', 28153),
(140721, 'ruRU', 'Трепещи пред взором нашего господина!', '', 28153),
(140720, 'ruRU', 'Уотк в\'шх!', '', 28153),
(140719, 'ruRU', 'Море зовет тебя, |3-6($r).', '', 28153),
(140718, 'ruRU', 'Духи! Возвращайтесь в големов! Вы принадлежите мне!', '', 28153),
(140717, 'ruRU', 'Изучение', 'Изучение', 28153),
(140716, 'ruRU', '', 'Щит рассеян. В атаку!', 28153),
(140715, 'ruRU', '', 'Если ума в достатке, несложно заставить духов сделать за тебя самую сложную часть работы.', 28153),
(140714, 'ruRU', '', 'Вот потому-то, $p, я и держу старые тотемы, полные злобных духов...', 28153),
(140713, 'ruRU', '', 'Вот он! Сейчас я займусь этим дурацким щитом.', 28153),
(140712, 'ruRU', 'Норганнон, твой острый ум укажет героям слабости врагов!', '', 28153),
(140711, 'ruRU', 'Я наделю одного из них частью своей силы, Великий Отец.', '', 28153),
(140710, 'ruRU', 'Агграмар! Этим смертным нужна твоя помощь.', '', 28153),
(140709, 'ruRU', 'Ярость морей смоет эту скверну!', '', 28153),
(140708, 'ruRU', 'Голганнет, пусть сила моря и небес поможет героям!', '', 28153),
(140707, 'ruRU', 'Лучшего бортельного пойла не найдешь по тутову сторону моря. Лей в болтало и радуйся!', '', 28153),
(140706, 'ruRU', 'Шмурдячку хлебнешь, шнуропс?', '', 28153),
(140705, 'ruRU', '', 'Не знаю, говорит эта змеюка правду или врет, но вариантов у нас немного.', 28153),
(140704, 'ruRU', 'С кем мне погрокать, чтобы мне тут пойла набулькали?', 'С кем мне погрокать, чтобы мне тут пойла набулькали?', 28153),
(140703, 'ruRU', 'Есть что на продажу?', 'Есть что на продажу?', 28153),
(140702, 'ruRU', '', 'Нужно найти оружие, пока его не получил Джакра\'зет.', 28153),
(140701, 'ruRU', '', '<Свинобраз издает хрюкающие звуки, время от времени переходящие в визг.>', 28153),
(140700, 'ruRU', 'Вольные гарпунщики такие храбрые! Мне бы духу не хватило биться с морскими гадами! Ходить мне вечно на баржах.', 'Вольные гарпунщики такие храбрые! Мне бы духу не хватило биться с морскими гадами! Ходить мне вечно на баржах.', 28153),
(140699, 'ruRU', '', 'Пойдем, Окри. Гарпунщики ждут.', 28153),
(140698, 'ruRU', '', 'Терольд, мы устали ждать твоего благословения. Пора уже начинать охоту на монстров.', 28153),
(140697, 'ruRU', 'Как покончим с Зак\'ражаном, надо будет поделить добычу. Кто первый взял – тот и хозяин.', '', 28153),
(140696, 'ruRU', 'ЗАЧЕМ?!', 'ЗАЧЕМ?!', 28153),
(140695, 'ruRU', 'А-а-а!', 'А-а-а!', 28153),
(140694, 'ruRU', 'Горячо! Горячо! Горячо!', 'Горячо! Горячо! Горячо!', 28153),
(140693, 'ruRU', '', 'У меня есть все, чтобы разрушить щит Зак\'ражана. Просто покажи мне, где он...', 28153),
(140692, 'ruRU', 'Только не так!', 'Только не так!', 28153),
(140691, 'ruRU', 'Нет, нет, нет!!!', 'Нет, нет, нет!!!', 28153),
(140690, 'ruRU', 'Стой, стой... Нет!', 'Стой, стой... Нет!', 28153),
(140689, 'ruRU', '', 'Я укажу путь. Держитесь рядом.', 28153),
(140688, 'ruRU', '', 'Они пытались, но теперь мое свидание с Бвонсамди откладывается.', 28153),
(140687, 'ruRU', '', 'Не трогай ничего без меня.', 28153),
(140686, 'ruRU', '', 'Рада, что пески еще не поглотили тебя, Ракира.', 28153),
(140685, 'ruRU', '', 'Мы с разведчиками будем ждать тебя там.', 28153),
(140684, 'ruRU', '', 'Спасибо тебе за помощь. Понятия не имею, с чем мы здесь столкнулись. Впрочем, я рада, что мы хоть кого-то спасли.', 28153),
(140683, 'ruRU', '', 'Лорд Брэннон и остальные отправились в долину Штормов, чтобы рассказать о порче среди жрецов. А я предупрежу всех в Боралусе.', 28153),
(140682, 'ruRU', 'Там и увидимся, $n. Духовные вопросы требуют деликатного подхода.', '', 28153),
(140681, 'ruRU', '', 'Я знаю, что мне поможет...', 28153),
(140680, 'ruRU', '', 'Похоже, здесь все гораздо серьезнее, чем мы думали.', 28153),
(140678, 'ruRU', '', 'Мы подождем здесь. Не стоит привлекать внимание убийц Джакра\'зета.', 28153),
(140677, 'ruRU', 'Подожди немного...', '', 28153),
(140675, 'ruRU', '', 'Славный бой, Гарпунщики! Монстру конец!', 28153),
(140673, 'ruRU', '', 'Она появилась! Гарпунщики, к бою!', 28153),
(140672, 'ruRU', 'Убийца из племени Песчаной Бури скрывается в тенях.', 'Убийца из племени Песчаной Бури скрывается в тенях.', 28153),
(140671, 'ruRU', '', 'Держитесь, Гарпунщики, задайте ей жару!', 28153),
(140670, 'ruRU', '', 'Цельтесь в щупальца! Заставьте чудище всплыть!', 28153),
(140669, 'ruRU', '', 'Берегись убийц. Джакра\'зет назначил за мою голову неплохую цену.', 28153),
(140667, 'ruRU', 'Этот мир будет принадлежать нам. Зул предсказал это!', 'Этот мир будет принадлежать нам. Зул предсказал это!', 28153),
(140666, 'ruRU', 'Ты не сможешь предотвратить то, что скоро начнется. Зул это предвидел.', 'Ты не сможешь предотвратить то, что скоро начнется. Зул это предвидел.', 28153),
(140665, 'ruRU', 'Ты ведешь нашего короля-неудачника? Ему крышка, и ты с этим ничего не поделаешь.', 'Ты ведешь нашего короля-неудачника? Ему крышка, и ты с этим ничего не поделаешь.', 28153),
(140664, 'ruRU', 'Слишком поздно. Зул уже отправился на вершину.', 'Слишком поздно. Зул уже отправился на вершину.', 28153),
(140663, 'ruRU', 'Орда падет. Альянс падет. А Зандалар возвысится!', 'Орда падет. Альянс падет. А Зандалар возвысится!', 28153),
(140662, 'ruRU', 'Зандалары будут править миром!', 'Зандалары будут править миром!', 28153),
(140661, 'ruRU', 'Мы сражаемся за истинную империю троллей!', 'Мы сражаемся за истинную империю троллей!', 28153),
(140660, 'ruRU', 'Жизнь за Зула!', 'Жизнь за Зула!', 28153),
(140659, 'ruRU', 'Ужас морей, который служит темному повелителю Дипуордена! С таким даже Гарпунщики могут не справиться.', '', 28153),
(140656, 'ruRU', 'У меня были противники и поздоровее. Но мне никто не ровня.', '', 28153),
(140655, 'ruRU', 'Только не трогайте... мою добычу.', '', 28153),
(140654, 'ruRU', 'Невероятно...', '', 28153),
(140653, 'ruRU', 'Познакомьте этих дохляков с нашими тяжелыми орудиями.', '', 28153),
(140652, 'ruRU', 'Артиллерия! Разнесите этих псов в клочья!', '', 28153),
(140651, 'ruRU', 'Парни, гляньте, есть ли золотые зубы. Остальное скормите акулам.', '', 28153),
(140650, 'ruRU', 'Стук трупов о палубу... люблю этот звук!', '', 28153),
(140649, 'ruRU', '', 'Г\'уун обретет свободу, и последователи Хир\'ика будут вознаграждены!', 28153),
(140648, 'ruRU', 'Так, ребятки, соберите все ценное. Я возьму свою долю, а вы можете подраться за остатки.', '', 28153),
(140647, 'ruRU', 'Вы совершили банальную ошибку – сразились с Красавчиком Харланом за его сокровища!', '', 28153),
(140646, 'ruRU', 'Надрайте палубу их потрохами!', '', 28153),
(140645, 'ruRU', 'Всем на палубу!', '', 28153),
(140644, 'ruRU', '|TInterface\\Icons\\Shaman_PVP_RipplingWaters:20|t%s начинает произносить заклинание |cFFFF0000|Hspell:255594|h[\"Небо и море\"]|h|r!', '|TInterface\\Icons\\Shaman_PVP_RipplingWaters:20|t%s начинает произносить заклинание |cFFFF0000|Hspell:255594|h[\"Небо и море\"]|h|r!', 28153),
(140643, 'ruRU', '', 'Впечатляет. Вы зашли дальше, чем я думала... но я все равно выпью вашу кровь.', 28153),
(140642, 'ruRU', '', 'Резан был сильным лоа. Может, из вас выйдет достойная жертва Зулу.', 28153),
(140641, 'ruRU', '', 'Спасибо, что убили жрицу. Теперь моя власть над храмом только укрепится.', 28153),
(140640, 'ruRU', 'Вот это мне нравится! Неси еще... А мне нужно поговорить с хозяином!', '', 28153),
(140639, 'ruRU', '', 'Угроза безликих пока миновала, но я по-прежнему буду следить за тем, что происходит в Атул\'Амане, чтобы так оно и оставалось.', 28153),
(140638, 'ruRU', '', 'Вол\'каала опять порубили на части? Ничего... я соберу его снова. А вот вы... вы умрете навсегда.', 28153),
(140637, 'ruRU', 'Летим!', 'Летим!', 28153),
(140636, 'ruRU', 'Нас атакуют! Летим! Отразим натиск монстра!', '', 28153),
(140635, 'ruRU', 'Скажи, как приготовишься к полету. Время уходит, а это чудовище ждать не будет.', '', 28153),
(140634, 'ruRU', '', 'Скоро Зул пробудит Дазара, и тогда Империя троллей возродится!', 28153),
(140633, 'ruRU', '', 'Чужаки, вы опоздали! Теперь это храм моего хозяина.', 28153),
(140632, 'ruRU', 'ХА! Работает! Бей еще! Бей еще!', '', 28153),
(140631, 'ruRU', 'Числом нам сетраков не взять, придется брать умением.', '', 28153),
(140630, 'ruRU', '', 'Бери все, что можешь, когда можешь и у кого можешь.', 28153),
(140629, 'ruRU', '', 'Если долго хранить любую вещь, рано или поздно она для чего-нибудь пригодится.', 28153),
(140628, 'ruRU', '|TInterface\\Icons\\ABILITY_MOUNT_EPICBATMOUNT.BLP:20|t%s начинает использовать способность |cFFFF0000|Hspell:256497|h[Кровавый ужас]|h|r! Скорее в укрытие!', '', 28153),
(140627, 'ruRU', 'Хорошо... он думает, мы мертвы... нам нужен... новый план.', '', 28153),
(140626, 'ruRU', 'Думали убить меня... а теперь лежите мертвые в моем логове. Я сожру вас... только подлечусь.', '', 28153),
(140625, 'ruRU', '', 'Ветра направят тебя в Атул\'Аман... Приготовься!', 28153),
(140624, 'ruRU', '', 'Нам придется найти источник волнения и ликвидировать его.', 28153),
(140623, 'ruRU', '', 'Уже много веков в недрах Атул\'Амана обитает некая темная сила, которая неустанно растет. Я чувствую беспокойство стихий...', 28153),
(140622, 'ruRU', 'Мортирные расчеты! Разрушьте их цитадель до основания! До основания!!!', '', 28153),
(140621, 'ruRU', '', 'Эхо этого взрыва все еще сотрясает стихии. Что за сила могла вызвать такое разрушение?', 28153),
(140620, 'ruRU', '', 'Атул\'Аман когда-то был прекрасен, но тысячи лет назад он погиб во взрыве невероятной силы.', 28153),
(140619, 'ruRU', 'Ложись! Хир\'ик летит сюда!', '', 28153),
(140618, 'ruRU', '', 'Положи руки на камень шаманов, и я призову смерч, который перенесет тебя в Атул\'Аман.', 28153),
(140617, 'ruRU', '', 'Со стеклохвостыми скорпидами надо разобраться, но, боюсь, дальше нас ждут чудовища пострашнее.', 28153),
(140616, 'ruRU', 'А-а-а!!!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140615, 'ruRU', 'Вы сильны... но никто не устоит перед мощью лоа!', '', 28153),
(140614, 'ruRU', 'ХВАТИТ! Я переломаю и сожру ваши кости!', '', 28153),
(140613, 'ruRU', 'Сила хозяина струится во мне... Он исцелит меня от вашей заразы!', '', 28153),
(140612, 'ruRU', 'Я... А-а-а-а! Что это... за яд? Что вы сделали со мной?', '', 28153),
(140611, 'ruRU', 'Ха! Что вы сделаете против лоа? Я властелин неба!', '', 28153),
(140610, 'ruRU', '', 'А какой у нас есть выбор?', 28153),
(140609, 'ruRU', '', 'Ракира! И ты веришь в то, что он говорит?', 28153),
(140608, 'ruRU', '', 'Тогда мы поможем тебе, Серрик.', 28153),
(140607, 'ruRU', 'Собери реагенты для ритуала, и мы поможем тебе найти потерянный артефакт.', '', 28153),
(140606, 'ruRU', 'Это видение оказалось куда полезнее, чем мы предполагали. Зал\'заикс где-то рядом.', '', 28153),
(140605, 'ruRU', 'Что именно покажет этот ритуал? Мы скоро найдем Зал\'зикса?', '', 28153),
(140604, 'ruRU', 'Ты правда веришь этим змеям? Думаю, они знают больше, чем кажется...', '', 28153),
(140603, 'ruRU', 'Мои люди помогут тебе найти этого Зал... как там его? Зал\'зикса?', '', 28153),
(140602, 'ruRU', 'Ты что, просто дашь им сгноить меня в этой клетке, да?', '', 28153),
(140601, 'ruRU', 'Нам никогда не найти Ракиру. Ее судьба была предрешена в ту минуту, как ее изгнали в пески.', '', 28153),
(140600, 'ruRU', '', 'Хранилище было запечатано! Почему в нем пусто? Ничего не понимаю...', 28153),
(140599, 'ruRU', '', 'Что же сотворил Джакра\'зет...', 28153),
(140596, 'ruRU', 'Никто не остановит... пески...', '', 28153),
(140595, 'ruRU', 'Храм падет! Мы убьем всех, кто встанет у нас на пути.', '', 28153),
(140594, 'ruRU', 'С вами так приятно иметь дело. Но вынужден откланяться, пока меня не хватились.', '', 28153),
(140593, 'ruRU', 'Как и обещал, вот вам обновка от братства Волнорезов. Теперь хоть сойдете за приличных бандитов.', '', 28153),
(140592, 'ruRU', 'Я разобью тебя, как стекло!', 'Я разобью тебя, как стекло!', 28153),
(140591, 'ruRU', 'За императора!', 'За императора!', 28153),
(140590, 'ruRU', 'Ур-р-ра! Я верил в эту дворнягу. Как-никак лучший друг человека.', '', 28153),
(140589, 'ruRU', 'Мы раздавим вас, как насекомых!', 'Мы раздавим вас, как насекомых!', 28153),
(140588, 'ruRU', 'Пески забвения унесут тебя.', 'Пески забвения унесут тебя.', 28153),
(140587, 'ruRU', 'Пески поглотят тебя!', 'Пески поглотят тебя!', 28153),
(140586, 'ruRU', 'Все земли покорятся нам!', 'Все земли покорятся нам!', 28153),
(140585, 'ruRU', 'Пески не остановить!', 'Пески не остановить!', 28153),
(140584, 'ruRU', 'Ваши королевства будут следующими!', 'Ваши королевства будут следующими!', 28153),
(140583, 'ruRU', 'Ну, так как насчет... вы поможете мне, я – вам?', '', 28153),
(140582, 'ruRU', 'Но сперва... есть проблемка. Этот замок никак не хочет поддаваться. Ключ во-о-он у того паршивого пса. А он шустрый.', '', 28153),
(140581, 'ruRU', 'Ух, повеселюсь!', 'Ух, повеселюсь!', 28153),
(140580, 'ruRU', 'Джакра\'зет хочет твоей смерти!', 'Джакра\'зет хочет твоей смерти!', 28153),
(140579, 'ruRU', 'За твою голову хорошо заплатят!', 'За твою голову хорошо заплатят!', 28153),
(140578, 'ruRU', 'Если вам хочется реального угара – обращайтесь к Совету капитанов. Кстати, я могу в этом подсобить.', '', 28153),
(140576, 'ruRU', 'Я изрублю тебя!', 'Я изрублю тебя в куски!', 28153),
(140575, 'ruRU', 'Привет от Джакра\'зета!', 'Привет от Джакра\'зета!', 28153),
(140574, 'ruRU', 'Эй! Вы, похоже, заправские головорезы. Не та шваль, что выдает себя за пиратов в этих краях.', '', 28153),
(140573, 'ruRU', 'Острая сталь!', '', 28153),
(140572, 'ruRU', 'Защищайтесь!', '', 28153),
(140571, 'ruRU', '', 'Я не промахиваюсь.', 28153),
(140570, 'ruRU', '', 'Люблю смотреть, как жертва корчится.', 28153),
(140569, 'ruRU', 'Лови!', '', 28153),
(140568, 'ruRU', 'Свежий бочонок!', '', 28153),
(140567, 'ruRU', 'Найди Краг\'ву, и малыш придет к тебе.', '', 28153),
(140566, 'ruRU', 'Вы что, надеетесь победить, свиньи?! Сейчас я вам покажу!', '', 28153),
(140565, 'ruRU', '', 'Раньше я никогда не видела, чтобы сетрак просил пощады. Возможно, он говорит правду.', 28153),
(140564, 'ruRU', '', 'У нас нет времени на пленников. Казним его, и дело с концом!', 28153),
(140563, 'ruRU', '', 'Ложь! Сетраки убивают всех и разоряют все на своем пути!', 28153),
(140562, 'ruRU', 'Ощутите ярость моря!', '', 28153),
(140561, 'ruRU', 'Смотрите под ноги!', '', 28153),
(140560, 'ruRU', 'Я вам не враг! Поверьте мне!', '', 28153),
(140559, 'ruRU', 'Похороните меня... с моей саблей...', '', 28153),
(140558, 'ruRU', 'Я не желаю зла! Пожалуйста... не убивайте меня.', '', 28153),
(140557, 'ruRU', 'Я доберусь до тебя!', 'Я доберусь до тебя!', 28153),
(140556, 'ruRU', 'Не стоило приходить сюда!', 'Не стоило приходить сюда!', 28153),
(140555, 'ruRU', 'Нам приказано убить тебя.', 'Нам приказано убить тебя.', 28153),
(140554, 'ruRU', 'Что было твоим, станет моим!', 'Что было твоим, станет моим!', 28153),
(140553, 'ruRU', 'Неужели я так и не встречу достойного врага...', '', 28153),
(140552, 'ruRU', 'Это не твоя война!', 'Это не твоя война!', 28153),
(140551, 'ruRU', 'Ты слишком много знаешь!', 'Ты слишком много знаешь!', 28153),
(140550, 'ruRU', 'Тебе тут не место!', 'Тебе здесь не место!', 28153),
(140549, 'ruRU', 'Первая кровь!', '', 28153),
(140548, 'ruRU', 'Это был удар милосердия.', '', 28153),
(140546, 'ruRU', 'Скрестим клинки!', '', 28153),
(140545, 'ruRU', '', 'Подавитесь картечью!', 28153),
(140544, 'ruRU', '', 'Сейчас будет месиво!', 28153),
(140542, 'ruRU', '', 'Бегите... укрыться все равно негде!', 28153),
(140541, 'ruRU', '', 'Ты у меня на мушке!', 28153),
(140540, 'ruRU', '', 'Хороший... выстрел...', 28153),
(140539, 'ruRU', '', 'Эй, у меня еще полно патронов!', 28153),
(140538, 'ruRU', '', 'Пусть пока займутся сетраками. А мы с тобой откроем хранилище и найдем Зал\'зикса.', 28153),
(140537, 'ruRU', '', 'Прямо промеж глаз.', 28153),
(140536, 'ruRU', '', 'Еще одна засечка на стволе!', 28153),
(140535, 'ruRU', '', 'Сегодня вместо бутылок буду стрелять по вашим черепам.', 28153),
(140534, 'ruRU', 'Сейчас кого-то сдует за борт!', '', 28153),
(140533, 'ruRU', 'Я угощаю!', '', 28153),
(140532, 'ruRU', 'Пейте до дна, жалкие псы!', '', 28153),
(140531, 'ruRU', 'Ничего у него не выйдет. Мы останемся верны Растахану и не примем сторону лжепророка.', '', 28153),
(140530, 'ruRU', 'Раз-два!', '', 28153),
(140529, 'ruRU', 'Пей до дна, подонки!', '', 28153),
(140528, 'ruRU', 'Я позабочусь о том, чтобы ему досталась только встреча с Бвонсамди.', '', 28153),
(140527, 'ruRU', '', 'Иди настрой сферу. А мы отправимся в руины Атул\'Амана и поищем хранилище Зал\'зикса.', 28153),
(140526, 'ruRU', '', 'Сначала он отправил флот в Пандарию, а теперь, будто этого было недостаточно, хочет, чтобы ему достался весь Зулдазар!', 28153),
(140525, 'ruRU', '', 'Никогда не верила Зулу, этому сладкоречивому дьяволу!', 28153),
(140524, 'ruRU', 'Я вернусь, как только сделаю дело, ма\'да.', '', 28153),
(140523, 'ruRU', 'Что?.. Праздник закончен?..', '', 28153),
(140522, 'ruRU', 'Я пойду, ма\'да! Твое желание закон.', '', 28153),
(140521, 'ruRU', 'Эк тебя раскорячило!', '', 28153),
(140520, 'ruRU', 'Э, да ты совсем на ногах не держишься!', '', 28153),
(140519, 'ruRU', 'Твое желание закон, ма\'да!', '', 28153),
(140518, 'ruRU', 'Лагерю нужно больше камня. Иди и принеси самые лучшие в Назмире камни. Ровно шестьдесят штук.', 'Лагерю нужно больше камня. Иди и принеси самые лучшие в Назмире камни. Ровно шестьдесят штук.', 28153),
(140517, 'ruRU', 'Вы чего? У меня еще полбочонка осталось!', '', 28153),
(140516, 'ruRU', 'Лагерю нужно больше древесины. Иди и добудь тридцать кусков!', 'Лагерю нужно больше древесины. Иди и добудь тридцать кусков!', 28153),
(140515, 'ruRU', 'О, ма\'да! Я жду здесь, как мне и велено.', '', 28153),
(140514, 'ruRU', 'Нам нужно пятьдесят безупречных шкур кроколисков. Иди и не возвращайся, пока все не добудешь.', 'Нам нужно пятьдесят безупречных шкур кроколисков. Иди и не возвращайся, пока все не добудешь.', 28153),
(140513, 'ruRU', 'Ма\'да! Скажи, что я могу сделать для тебя?', '', 28153),
(140512, 'ruRU', 'Как тебе мои птички?', '', 28153),
(140511, 'ruRU', 'Покажи, куда я могу отправиться.', 'Покажи, куда я могу отправиться.', 28153),
(140510, 'ruRU', '', 'Отдай мне свою душу!', 28153),
(140509, 'ruRU', '', 'Теперь ты в моей власти!', 28153),
(140508, 'ruRU', '', 'Твоя душа будет страдать!', 28153),
(140507, 'ruRU', '', 'Я растерзаю твою душу!', 28153),
(140506, 'ruRU', '', 'За Орду!', 28153),
(140505, 'ruRU', 'За Орду!', '', 28153),
(140504, 'ruRU', '', 'За Орду!', 28153),
(140503, 'ruRU', '', 'Отныне Крутогорье клянется сражаться против ваших врагов.', 28153),
(140502, 'ruRU', '', 'Я принимаю вашу клятву. Орда дает защиту... но и требует повиновения.', 28153),
(140501, 'ruRU', '', 'Сегодня герои Орды продемонстрировали моему народу великую силу и храбрость.', 28153),
(140500, 'ruRU', '', 'Я слушаю вас, Майла.', 28153),
(140499, 'ruRU', 'А Орда с радостью примет вас! Давайте же отправимся в Оргриммар и сообщим вождю хорошие новости.', '', 28153),
(140498, 'ruRU', '', 'Таурены Крутогорья почтут за честь присоединиться к Орде.', 28153),
(140497, 'ruRU', '', 'Бейн Кровавое Копыто, сегодня ты проявил отвагу, честь и преданность. Теперь я уверена, что наши народы должны вновь объединиться.', 28153),
(140496, 'ruRU', 'Меня пугает даже мысль об этом. Если бы не наши союзники, все было бы кончено.', '', 28153),
(140495, 'ruRU', '', 'Если бы Уул\'гинет победил, мы все стали бы рабами Древних богов... Все, включая Смоляного Рога.', 28153),
(140494, 'ruRU', '', 'Сегодня беда чудом не пришла в Азерот.', 28153),
(140493, 'ruRU', '', 'Глупцы... Зул распотрошит... ваши... души.', 28153),
(140492, 'ruRU', 'Голоса... смолкли. Спасибо вам, друзья мои.', '', 28153),
(140491, 'ruRU', '', 'Смоляной Рог совсем плох. Мы должны привести его в чувство. Поговори с духостранником Серым Небом. Он может помочь.', 28153),
(140490, 'ruRU', 'Мулгор в опасности, пока мы не выясним, что произошло. Я отправлюсь в Громовой Тотем с тобой, Майла. Мы сразимся с тьмой вместе.', '', 28153),
(140489, 'ruRU', '', 'Я должна доставить Смоляного Рога в Крутогорье!', 28153),
(140488, 'ruRU', 'Я знаю, что это. Идем, $n! Нам нужна твоя помощь!', '', 28153),
(140487, 'ruRU', '', 'Смоляной Рог! Что за тьма терзает тебя?', 28153),
(140486, 'ruRU', 'Мне не стоило... покидать... Крутогорье...', '', 28153),
(140485, 'ruRU', 'Об этом я и хочу поговорить. Надеюсь...', '', 28153),
(140484, 'ruRU', '', 'Спасибо, что пригласил нас, Бейн. Пришло время нашим народам вновь объединиться.', 28153),
(140483, 'ruRU', 'Спасибо, что пришла, Майла. Для меня честь приветствовать вас в Мулгоре.', '', 28153),
(140482, 'ruRU', '', 'Твоя кровь теперь моя.', 28153),
(140481, 'ruRU', '', 'Ваша кровь еще послужит мне... Вам-то она больше ни к чему.', 28153),
(140480, 'ruRU', '', 'Дазар скоро пробудится, но вы этого уже не увидите!', 28153),
(140479, 'ruRU', 'Теперь наши войска могут носить стальную броню!', 'Теперь наши войска могут носить стальную броню!', 28153),
(140478, 'ruRU', 'У нас тут предатель? Взять!', 'У нас тут предатель? Взять!', 28153),
(140477, 'ruRU', 'А ну не трогай!', 'А ну не трогай!', 28153),
(140476, 'ruRU', 'Эй, ты что творишь?', 'Эй, ты что творишь?', 28153),
(140475, 'ruRU', 'Передай им мои слова, а затем отнеси кристалл на вершину горы Хиджал, к Источнику Вечности.', '', 28153),
(140474, 'ruRU', 'Я поместил в этот кристалл два послания. Одно для моего брата Малфуриона, другое – для Тиранды. Твоя задача – доставить их.', '', 28153),
(140473, 'ruRU', 'Какой бы ни была моя судьба, я приму ее. И все же... у меня остались незавершенные дела.', '', 28153),
(140472, 'ruRU', 'Как только открылся путь на Аргус... и я увидел родной мир Пылающего Легиона... я понял, что вряд ли вернусь домой.', '', 28153),
(140471, 'ruRU', 'Теперь наши войска могут воевать стальным оружием!', 'Теперь наши войска могут воевать стальным оружием!', 28153),
(140470, 'ruRU', 'Я терплю боль, ма\'да! Я готов убивать!', '', 28153),
(140469, 'ruRU', 'Я не слабый, мне боль не страшна! Я готов убивать!', '', 28153),
(140468, 'ruRU', 'Я терплю боль! Я убью всех на своем пути!', '', 28153),
(140467, 'ruRU', 'Я сильный! Бей меня еще, ма\'да!', '', 28153),
(140464, 'ruRU', '$n, скажи этому созданию, что ты меня знаешь. Он не может так просто держать меня в заточении!', '', 28153),
(140463, 'ruRU', 'Срыв плаката', 'Срыв плаката', 28153),
(140462, 'ruRU', 'Ух-х... Хорошо пошла.', '', 28153),
(140461, 'ruRU', 'Вот, держи. Ну, за светлые деньки!', '', 28153),
(140460, 'ruRU', 'Чего?', '', 28153),
(140459, 'ruRU', '', 'Годная жертва!', 28153),
(140458, 'ruRU', '', 'Залезай! Может, мы уже опоздали!', 28153),
(140457, 'ruRU', 'Хозяйка соберет меня снова...', '', 28153),
(140456, 'ruRU', 'Хозяйка использует ваши куски. Сделает меня сильнее!', '', 28153),
(140455, 'ruRU', 'Мясо для хозяйки.', '', 28153),
(140454, 'ruRU', 'Одни ошметки остались.', '', 28153),
(140453, 'ruRU', 'Я умру, вы – тоже!', '', 28153),
(140452, 'ruRU', 'Тотемы не трогать!', '', 28153),
(140451, 'ruRU', 'Сила уходит!', '', 28153),
(140450, 'ruRU', 'Не бить тотемы!', '', 28153),
(140449, 'ruRU', 'Н-е-ет!', '', 28153),
(140448, 'ruRU', 'Крушить!', '', 28153),
(140447, 'ruRU', 'Ломать!', '', 28153),
(140446, 'ruRU', 'Вы?! Я разорву вас!', '', 28153),
(140445, 'ruRU', '', 'Наконец-то ты тут. Стихии шептали мне о твоем приходе...', 28153),
(140444, 'ruRU', 'Мы с Зиссией побежим вперед и предупредим Воррика о твоем прибытии.', '', 28153),
(140441, 'ruRU', 'Что еще ты можешь рассказать?', 'Что еще ты можешь рассказать?', 28153),
(140439, 'ruRU', 'Кто такие отступники?', 'Кто такие отступники?', 28153),
(140438, 'ruRU', 'Отступники не прекратят осаду, но благодаря тебе у нас хотя бы появилось время. Ты найдешь нашего лоа и положишь конец этой войне.', '', 28153),
(140437, 'ruRU', 'Отступники осадили наш дом. Мы должны дать отпор! Нельзя позволить им захватить храм.', '', 28153),
(140436, 'ruRU', 'Ох, как же с тобой скучно!', 'Ох, как же с тобой скучно!', 28153),
(140435, 'ruRU', 'Ладно, тьфу на это! Думаю, мне пора домой.', 'Ладно, тьфу на это! Думаю, мне пора домой.', 28153),
(140434, 'ruRU', 'Рр-р! Рр-р... рр-ра... ой!', 'Рр-р! Рр-р... рр-ра... ой!', 28153),
(140433, 'ruRU', 'Ты умеешь испортить настроение, дорогуша.', 'Ты умеешь испортить настроение, дорогуша.', 28153),
(140432, 'ruRU', 'Ура! Быть большим куда веселее!', 'Ура! Быть большой куда веселее!', 28153),
(140431, 'ruRU', 'О да-а! Это так здорово... То есть... рр-р!', 'О да-а! Это так здорово... То есть... рр-р!', 28153),
(140430, 'ruRU', 'Ой, берегись! Я не вижу, куда ступаю!', 'Ой, берегись! Я не вижу, куда ступаю!', 28153),
(140429, 'ruRU', 'Я большой ящер, как Гонк! Ха-ха-ха!', 'Я большой ящер, как Гонк! Ха-ха-ха!', 28153),
(140428, 'ruRU', '', 'Да уж... С тобой скучно!', 28153),
(140427, 'ruRU', '', 'Ладно, тьфу на это! Пойду я домой.', 28153),
(140426, 'ruRU', '', 'Рр-р! Рр-р... рр-ра... ой!', 28153),
(140425, 'ruRU', '', 'Ну ты и зануда.', 28153),
(140424, 'ruRU', 'Разберись с ними. Наша работа почти окончена!', '', 28153),
(140423, 'ruRU', '', 'Ура! Быть большим так классно!', 28153),
(140422, 'ruRU', '', 'О да-а! Так здорово... То есть... \"рр-р!\"', 28153),
(140421, 'ruRU', '', 'Ой, осторожнее! Могу случайно наступить!', 28153),
(140420, 'ruRU', '', 'Я большой ящер, как Гонк! Ха-ха-ха!', 28153),
(140419, 'ruRU', 'Ты умеешь испортить настроение.', '', 28153),
(140418, 'ruRU', 'Рр-р! Рр-р... рр-ра... ой!', '', 28153),
(140417, 'ruRU', 'Ладно, тьфу на это! Думаю, мне пора домой.', '', 28153),
(140416, 'ruRU', 'Да уж... С тобой скучно!', '', 28153),
(140415, 'ruRU', 'Я большой равазавр, как Гонк! Ха-ха!', '', 28153),
(140414, 'ruRU', 'Ой, берегись! Я не вижу, куда ступаю!', '', 28153),
(140413, 'ruRU', 'О да-а! Это так здорово... То есть... \"рр-р!\"', '', 28153),
(140412, 'ruRU', 'Ура! Быть большим куда веселее!', '', 28153),
(140411, 'ruRU', 'Хозяйка хочет ваши кости!', '', 28153),
(140410, 'ruRU', 'Кр-рак! Крысы! Кр-рак!', '', 28153),
(140409, 'ruRU', 'Кр-рак! Дырявь борта! Кр-рак!', '', 28153),
(140408, 'ruRU', 'Кр-рак! На дно! Кр-рак!', '', 28153),
(140407, 'ruRU', 'Кр-рак! Балласт! Кр-рак!', '', 28153),
(140406, 'ruRU', 'Кр-рак! Свиньи! Кр-рак!', '', 28153),
(140405, 'ruRU', 'Получай пробоину!', '', 28153),
(140404, 'ruRU', 'На дно...', '', 28153),
(140403, 'ruRU', 'Только на приманку и годишься!', '', 28153),
(140402, 'ruRU', 'Мертвецы не болтают!', '', 28153),
(140401, 'ruRU', 'Привыкайте к морской жизни!', '', 28153),
(140400, 'ruRU', 'Что, нравится? Этот запах не скоро выветрится!', '', 28153),
(140399, 'ruRU', 'Получай в глухой иллюминатор!', '', 28153),
(140398, 'ruRU', 'Я продырявлю ваши шкуры!', '', 28153),
(140397, 'ruRU', 'Прямой наводкой в полуют!', '', 28153),
(140396, 'ruRU', 'Из-за вас я пролил самое дорогое!', '', 28153),
(140395, 'ruRU', 'Прощай, моя бутыль! Я тебя не забуду!', '', 28153),
(140394, 'ruRU', 'Проклятье! Из-за вас я замочил палубу!', '', 28153),
(140393, 'ruRU', 'Пощады не ждите!', '', 28153),
(140392, 'ruRU', 'На таран!', '', 28153),
(140391, 'ruRU', 'Зандалары не умирают!', '', 28153),
(140390, 'ruRU', 'Пора пустить кровь.', '', 28153),
(140389, 'ruRU', 'Пусть духи хранят тебя!', '', 28153),
(140388, 'ruRU', 'Я услышал зов!', '', 28153),
(140387, 'ruRU', 'Ладно, как скажешь... $n! Давай!', '', 28153),
(140386, 'ruRU', 'Пощадить? Глупцы! Мы уничтожим вас вместе со всем Зулдазаром!', '', 28153),
(140385, 'ruRU', 'Великий Хир\'ик! Мы взываем к твоей милости... пощади нас!', '', 28153),
(140384, 'ruRU', 'На абордаж!', '', 28153),
(140383, 'ruRU', 'Джо\'чунга, я готов. Давай приступим к выполнению нашего плана и остановим Хир\'ика.', 'Джо\'чунга, я готова. Давай приступим к выполнению нашего плана и остановим Хир\'ика.', 28153),
(140382, 'ruRU', 'Это безумие... Я вроде как не подписывался на убийство лоа.', '', 28153),
(140381, 'ruRU', 'Ар-р-р! Живец, продырявь им борта!', '', 28153),
(140380, 'ruRU', 'Идите сюда, осквернители, и примите смерть. Ваша кровь насытит Г\'ууна!', '', 28153),
(140379, 'ruRU', 'Не зевайте, свиньи гальюнные!', '', 28153),
(140378, 'ruRU', 'Последний взрыв!', '', 28153),
(140377, 'ruRU', 'Ты меня утомляешь!', '', 28153),
(140376, 'ruRU', 'А теперь заткнись и умри!', '', 28153),
(140375, 'ruRU', 'Здесь много троллей, но сражаться они не хотят.$b$bС таким отношением в Чертоги Доблести им не попасть. Мы ищем славы в бою!$b$bГде король? Он поймет нас. Может, даже сразится с нами!', '', 28153),
(140374, 'ruRU', 'Ты хочешь учиться боевому искусству? Мне как раз нужен партнер для тренировок.', '', 28153),
(140373, 'ruRU', '', 'Мы хотим закалить свои тела в бою и снискать славу, что откроет для нас врата Чертогов Доблести$b$bЗдешний король силен, он правит уже много сотен лет. Он будет достойным противником. Нам всего лишь нужно встретиться с королем и бросить ему вызов на славный бой!', 28153),
(140372, 'ruRU', '', 'Божественная кара!', 28153),
(140371, 'ruRU', '', 'След моей победы останется на твоей душе!', 28153),
(140370, 'ruRU', '', 'Вперед, воин! Бой ждет нас!', 28153),
(140369, 'ruRU', 'Сбросить бомбы!', '', 28153),
(140368, 'ruRU', '', 'Я ищу благородных воинов, которые будут сражаться вместе со мной.', 28153),
(140367, 'ruRU', 'Не обращайте внимания. Живец просто... сбрасывает балласт!', '', 28153),
(140366, 'ruRU', 'Вам каюк!', '', 28153),
(140364, 'ruRU', 'Живец, поднимай якорь и суши чертовы перья! К нам явились сухопутные крысы!', '', 28153),
(140363, 'ruRU', 'Чужаки!', '', 28153),
(140362, 'ruRU', 'Пишите завещания!', '', 28153),
(140361, 'ruRU', 'Стоять, сухопутные крысы!', '', 28153),
(140360, 'ruRU', 'Кого убить?', '', 28153),
(140359, 'ruRU', '', 'Мы останемся здесь и будем держать тебя в курсе событий!', 28153),
(140358, 'ruRU', 'Да здравствует король!', '', 28153),
(140357, 'ruRU', 'Бвонсамди дает мне еще один шанс!', '', 28153),
(140356, 'ruRU', 'Таз\'динго!', '', 28153),
(140355, 'ruRU', '', 'Это золото в моей власти!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140354, 'ruRU', '', 'Вам здесь не место!', 28153),
(140353, 'ruRU', '', 'Мои когти пронзят твое сердце.', 28153),
(140352, 'ruRU', '', 'Не будем терять время. Встретимся у пещеры!', 28153),
(140335, 'ruRU', 'Итак... или план сработает, или скоро мы будем мертвыми.', '', 28153),
(140334, 'ruRU', 'О нет... Хир\'ик!', '', 28153),
(140333, 'ruRU', 'Принцессу Таланджи чрезвычайно интересует то, что происходит на этих болотах.', '', 28153),
(140332, 'ruRU', '', 'Золото подчиняется мне.', 28153),
(140331, 'ruRU', '', 'Я вычищу порчу!', 28153),
(140330, 'ruRU', '', 'Сила Атал\'Дазара течет во мне!', 28153),
(140329, 'ruRU', '', 'Прими очищение!', 28153),
(140328, 'ruRU', '', 'Смерть тебе к лицу.', 28153),
(140327, 'ruRU', '', 'Нужно... очистить... резервуары...', 28153),
(140326, 'ruRU', '', 'Тут хоронят только достойных. А ваши кости сожрут ящеры.', 28153),
(140325, 'ruRU', '', 'Вам не стоило приходить сюда.', 28153),
(140324, 'ruRU', '', 'Вы пришли за золотом, но оставите здесь свои кости!', 28153),
(140323, 'ruRU', '', 'Здесь не место слугам Язмы!', 28153),
(140322, 'ruRU', 'Выходите! Я лично разделаюсь с вами.', '', 28153),
(140321, 'ruRU', 'Нас прислала Таланджи, чтобы проверить слухи о чудовищах на болотах. Мы и подумать не могли, что все настолько ужасно... Тролли крови создают их...', '', 28153),
(140320, 'ruRU', 'Я думал, ты помер! Только не говори, что работаешь на этих лизоблюдов!', '', 28153),
(140319, 'ruRU', 'Долгая история... Может, по стаканчику?', '', 28153),
(140318, 'ruRU', 'Сколько можно повторять? Стальным Волнам тут не... Флинн?!', '', 28153),
(140317, 'ruRU', 'Кхе-кхе. Эй, старая каракатица! Мы пришли за твоим сокровищем!', '', 28153),
(140316, 'ruRU', '', 'Что? Нет! Что проис-с-сходит... С-с-сила...', 28153),
(140315, 'ruRU', 'Добро пожаловать в банду \"Золотого клыка\", $p. Теперь мы одна семья!', '', 28153),
(140314, 'ruRU', '', 'Тебе когда-нибудь доводилось так сильно ударить сетрака кулаком, чтобы у него отвалился хвост?', 28153),
(140313, 'ruRU', 'У тебя есть сила, у меня – ум.\n\nМы отличная команда.', '', 28153),
(140312, 'ruRU', '', 'Не беспокойся: я этот барабан мигом починю.', 28153),
(140311, 'ruRU', '', '...все прямо как ворон сказал.', 28153),
(140310, 'ruRU', '', '...неподвижно лежат...', 28153),
(140309, 'ruRU', '', 'Все, кто не сбежал...', 28153),
(140308, 'ruRU', '', 'Остались игрушки да я.', 28153),
(140307, 'ruRU', 'Сбор', 'Сбор', 28153),
(140306, 'ruRU', '', 'Азшара... Я подвела тебя...', 28153),
(140305, 'ruRU', '', 'Твоя смерть порадует королеву. Во славу Назжатара!', 28153),
(140303, 'ruRU', 'Эй, выпей со мной и Флинном! За счет заведения!$B$BЧего налить?', '', 28153),
(140302, 'ruRU', 'Молока... в кружку из черепа.', 'Молока... в кружку из черепа.', 28153),
(140301, 'ruRU', 'Молока.', 'Молока.', 28153),
(140300, 'ruRU', 'Эля.', 'Эля.', 28153),
(140299, 'ruRU', '|TInterface\\Icons\\INV_AMMO_BULLET_03:20|t%s выбирает вас мишенью для своей способности |cFFFF0000|Hspell:256044|h[Меткий стрелок]|h|r!', '', 28153),
(140298, 'ruRU', 'Осторожно там. Творится что-то серьезное.', '', 28153),
(140297, 'ruRU', 'Тебе здесь всегда рады, $p. Теперь ты в нашей банде.', '', 28153),
(140296, 'ruRU', 'Таверна \"Золотой клык\" готова приветствовать гостей!', '', 28153),
(140295, 'ruRU', 'Спасибо за спасение...', '', 28153),
(140294, 'ruRU', 'Думаю, я тут задержусь. Помогу, чем смогу.', '', 28153),
(140293, 'ruRU', 'Поверить не могу, что снова нашел тебя, $p. Я так устал...', '', 28153),
(140292, 'ruRU', 'Не знаю, что у тебя с головой, но если бы не ты... Спасибо.', '', 28153),
(140291, 'ruRU', 'Выходит, с твоей помощью изгнанники открыли таверну в этой глуши?', '', 28153),
(140290, 'ruRU', 'Отступники гнали меня по пустыне... Пришлось отбиваться и от них, и от диких животных. Еле выжил.', '', 28153),
(140289, 'ruRU', 'Тролли крови сошли с ума – скармливают наших братьев своим нетопырям!', 'Тролли крови сошли с ума – скармливают наших братьев своим нетопырям!', 28153),
(140288, 'ruRU', 'Эти изверги хотели напоить своих нетопырей моей кровью!', 'Эти изверги хотели напоить своих нетопырей моей кровью!', 28153),
(140287, 'ruRU', 'Спасибо! Они чуть не скормили меня своим нетопырям.', 'Спасибо! Они чуть не скормили меня своим нетопырям.', 28153),
(140286, 'ruRU', 'Они хотели скормить меня нетопырям!', 'Они хотели скормить меня нетопырям!', 28153),
(140285, 'ruRU', 'Похоже, королева Азшара впала в отчаяние. Ну, на худой конец, мы испортим ей день.$B$BКак приятно.', '', 28153),
(140283, 'ruRU', 'Твоя маскировка слетела! А почему моя на месте? Хм-м... Это все меняет.', '', 28153),
(140282, 'ruRU', '$n! Что ты делаешь?', '', 28153),
(140281, 'ruRU', 'Ох, перед глазами все плывет... Я слышал зов Бвонсамди.', '', 28153),
(140280, 'ruRU', '', 'Знаю я, о чем ты думаешь: \"Разве зандалары не поработили гоблинов и не отправили их в шахты?\"$b$bСлушай, если не торговать с врагами, они будут торговать между собой. Это плохо сказывается на бизнесе.', 28153),
(140279, 'ruRU', '', 'Не стоит благодарности.', 28153),
(140278, 'ruRU', 'Не стоит благодарности.', '', 28153),
(140277, 'ruRU', 'Не за что.', '', 28153),
(140276, 'ruRU', '', 'Не за что.', 28153),
(140275, 'ruRU', 'Это честь для меня.', '', 28153),
(140274, 'ruRU', '', 'Это честь для меня.', 28153),
(140273, 'ruRU', '', 'Не стоит благодарности.', 28153),
(140272, 'ruRU', 'Не стоит благодарности.', '', 28153),
(140271, 'ruRU', '', 'Рада помочь.', 28153),
(140270, 'ruRU', 'Рад помочь.', '', 28153),
(140269, 'ruRU', 'Рад служить.', '', 28153),
(140268, 'ruRU', '', 'Рада служить.', 28153),
(140267, 'ruRU', '', 'Без сомнения.', 28153),
(140266, 'ruRU', 'Без сомнения.', '', 28153),
(140265, 'ruRU', 'Верно.', '', 28153),
(140264, 'ruRU', 'Не помню, когда я в последний раз пил. Скитался по дюнам, с тех пор как на нас напали!', '', 28153),
(140263, 'ruRU', '', 'Верно.', 28153),
(140262, 'ruRU', 'Что ты здесь делаешь, $p? Я думал, тебя уже нет!', '', 28153),
(140261, 'ruRU', 'Принято.', '', 28153),
(140260, 'ruRU', '', 'Принято.', 28153),
(140259, 'ruRU', '', 'Без сомнений.', 28153),
(140258, 'ruRU', 'Без сомнений.', '', 28153),
(140257, 'ruRU', 'Ждите здесь.', '', 28153),
(140256, 'ruRU', '', 'Ждите здесь.', 28153),
(140255, 'ruRU', '', 'Оставайтесь на месте.', 28153),
(140254, 'ruRU', 'Оставайтесь на месте.', '', 28153),
(140253, 'ruRU', 'Ждите здесь.', '', 28153),
(140252, 'ruRU', '', 'Ждите здесь.', 28153),
(140251, 'ruRU', '', 'Побудьте здесь.', 28153),
(140250, 'ruRU', 'Побудьте здесь.', '', 28153),
(140249, 'ruRU', 'Премного благодарен.', '', 28153),
(140248, 'ruRU', '', 'Премного благодарна.', 28153),
(140247, 'ruRU', '', 'Если тебе кажется, что я быстрая, то это тебе еще с моей сестрицей Нокси не доводилось встречаться. Бьет так, что из глаз звезды сыплются!', 28153),
(140246, 'ruRU', '', 'Я перед тобой в долгу.', 28153),
(140245, 'ruRU', 'Я перед тобой в долгу.', '', 28153),
(140244, 'ruRU', 'Спасибо тебе.', '', 28153),
(140243, 'ruRU', '', 'Спасибо тебе.', 28153),
(140242, 'ruRU', '', 'Спасибо тебе.', 28153),
(140241, 'ruRU', 'Спасибо тебе.', '', 28153),
(140240, 'ruRU', '', 'Свет благодарит тебя.', 28153),
(140239, 'ruRU', 'Свет благодарит тебя.', '', 28153),
(140238, 'ruRU', 'Прими мою благодарность.', '', 28153),
(140237, 'ruRU', '', 'Прими мою благодарность.', 28153),
(140236, 'ruRU', '', 'Мне нужна мана.', 28153),
(140235, 'ruRU', 'Мне нужна мана.', '', 28153),
(140234, 'ruRU', 'Нужно больше маны.', '', 28153),
(140233, 'ruRU', '', 'Мне не хватает маны.', 28153),
(140232, 'ruRU', '', 'Мне нужна мана.', 28153),
(140231, 'ruRU', 'Мне нужна мана.', '', 28153),
(140230, 'ruRU', 'У меня мало маны.', '', 28153),
(140229, 'ruRU', '', 'У меня мало маны.', 28153),
(140228, 'ruRU', '', 'Хочешь говорить – говори с Мокси.$b$bОбо мне не беспокойся, я обычный охранник. Но даже пальцем ее тронуть не моги. Я слежу за тобой.', 28153),
(140227, 'ruRU', '', 'Открыть огонь!', 28153),
(140226, 'ruRU', 'Открыть огонь!', '', 28153),
(140225, 'ruRU', 'Начать обстрел!', '', 28153),
(140224, 'ruRU', '', 'Начать обстрел!', 28153),
(140223, 'ruRU', '', 'Если считаешь, что я внушаю страх, так это тебе еще с моей сестрой Бокси не доводилось повстречаться. Она порхает, как облачный змей, и жалит, как силитид. Бум! Бах!', 28153),
(140222, 'ruRU', '', 'Хочешь поговорить – говори с Мокси. Она у нас главная по разговорам.$b$b<Нокси поднимает палицу и шлепает набалдашником по ладони другой руки.>$b$bМое дело – дробить черепа тех, кто делает глупости. Со мной разговаривать не надо.', 28153),
(140221, 'ruRU', 'Дайте волю ярости!', '', 28153),
(140220, 'ruRU', '', 'Дайте волю ярости!', 28153),
(140219, 'ruRU', '', 'Открыть огонь!', 28153),
(140218, 'ruRU', '', 'Можешь поговорить с боссом, но учти – я за тобой присматриваю.', 28153),
(140217, 'ruRU', '', 'Никаких подозрительных делишек в порту. Не люблю ничего подозрительного.', 28153),
(140216, 'ruRU', '', 'Открыть огонь!', 28153),
(140215, 'ruRU', '', 'Хорошо.', 28153),
(140214, 'ruRU', 'Хорошо.', '', 28153),
(140213, 'ruRU', 'Хочешь поговорить с боссом, говори.$b$bХочешь поговорить со мной? Нет, не думаю. Так что сгинь отсюда.', '', 28153),
(140212, 'ruRU', 'Воистину.', '', 28153),
(140211, 'ruRU', '', 'Воистину.', 28153),
(140210, 'ruRU', '$p?..', '', 28153),
(140209, 'ruRU', 'Да будет так.', '', 28153),
(140208, 'ruRU', '', 'Да будет так.', 28153),
(140207, 'ruRU', '', 'Да, я вижу, как Газрикс и его команда плетут свои интриги. Добром это для них не кончится. Как только мы добьемся аудиенции у короля, первым пунктом в повестке дня будет избавление от конкурентов.$b$bЗакон спроса и предложения помнишь? Если предлагать будем только мы, то кто ж с нас будет спрашивать!', 28153),
(140206, 'ruRU', '', 'Точно.', 28153),
(140205, 'ruRU', 'Точно.', '', 28153),
(140204, 'ruRU', 'Точно.', '', 28153),
(140203, 'ruRU', '', 'Точно.', 28153),
(140202, 'ruRU', '', 'Это недопустимо.', 28153),
(140201, 'ruRU', 'Это недопустимо.', '', 28153),
(140200, 'ruRU', 'Пожалуйста, я ранен... Сжальтесь над бедным зандаларом!', '', 28153),
(140199, 'ruRU', 'Недопустимо.', '', 28153),
(140198, 'ruRU', '', 'Недопустимо.', 28153),
(140197, 'ruRU', 'Эй? Есть тут кто?', '', 28153),
(140196, 'ruRU', '', 'Я так не думаю.', 28153),
(140195, 'ruRU', 'Я так не думаю.', '', 28153),
(140194, 'ruRU', 'Ни за что!', '', 28153),
(140193, 'ruRU', '', 'Конечно же нет.', 28153),
(140192, 'ruRU', 'Нет.', '', 28153),
(140191, 'ruRU', '', 'Нет.', 28153),
(140190, 'ruRU', '', 'Нет.', 28153),
(140189, 'ruRU', 'Нет.', '', 28153),
(140188, 'ruRU', 'Всем приготовиться... Первый посетитель! Как же здорово! Чур не убивать!', '', 28153),
(140187, 'ruRU', '', 'Мы здесь представляем интересы картеля Трюмных Вод. Даже если застрянем в гавани с этими дилетантами из Хитрой Шестеренки, это нас не остановит.$b$bПереговоры идут хорошо. Скоро я пообщаюсь с королем, он заглянет к нам, и мы покажем, как можно построить взаимовыгодные деловые отношения.', 28153),
(140186, 'ruRU', '', 'Картелю Трюмных Вод служат одни из лучших посредников в индустрии. Они могут купить что угодно и кого угодно – или откупиться от них. Некоторых это ужасно вдохновляет.$b$bМеня отправляют туда, где другие не справляются. Мы с девчонками займемся этим. Смотри и восхищайся.', 28153),
(140185, 'ruRU', 'Картель Трюмных Вод? Да, есть тут такие. Думают, что они все такие крутые, раз посылают Мокси и ее сестриц \"присматривать\" за нами. Можно подумать, нам есть что скрывать.$b$bПлюнь на них. Мне приходилось иметь дело с торговыми принцами, так что эти цацы меня не волнуют.', '', 28153),
(140184, 'ruRU', 'Какая удача, что я тебя здесь встретил. Можешь передать послание королю? Думаю, он будет рад узнать, какие широкие деловые возможности откроются в его славном городе с нашим приходом.', '', 28153),
(140183, 'ruRU', 'Враги на подходе!', '', 28153),
(140182, 'ruRU', '', 'Опасность близко.', 28153),
(140181, 'ruRU', 'Уверяю тебя, мы – официальные представители Картеля Хитрой Шестеренки и находимся здесь по делам бизнеса!$b$bБосс знает, что империя Зандалари просто огромна, а где огромная империя, там огромные возможности, сечешь?$b$bВ город они нас пока не пускают, но я подозреваю, что очень скоро все изменится.', '', 28153),
(140180, 'ruRU', '', 'Берегитесь! Опасность!', 28153),
(140179, 'ruRU', 'Берегитесь! Опасность!', '', 28153),
(140178, 'ruRU', 'Помогите, пожалуйста!', '', 28153),
(140177, 'ruRU', '', 'Помогите, пожалуйста!', 28153),
(140176, 'ruRU', 'На помощь!', '', 28153),
(140175, 'ruRU', '', 'На помощь!', 28153),
(140174, 'ruRU', '', 'Помогите!', 28153),
(140173, 'ruRU', 'Помогите!', '', 28153),
(140172, 'ruRU', 'Помогите!', '', 28153),
(140171, 'ruRU', '', 'Помогите!', 28153),
(140170, 'ruRU', 'Сурамар отстоял свою свободу.', '', 28153),
(140169, 'ruRU', '', 'Сурамар отстоял свою свободу.', 28153),
(140168, 'ruRU', '', 'Мы противостоим тьме.', 28153),
(140167, 'ruRU', 'Мы противостоим тьме.', '', 28153),
(140166, 'ruRU', 'Рад встрече.', '', 28153),
(140165, 'ruRU', '', 'Рада встрече.', 28153),
(140163, 'ruRU', 'Все, кто придет, будут поражены!', '', 28153),
(140161, 'ruRU', 'Вперед! Я знаю отличное местечко для этого клыка. Там его все смогут увидеть.', '', 28153),
(140160, 'ruRU', 'DO NOT TRANSLATE', '', 28153),
(140159, 'ruRU', 'Гроззток, убей непрошеного гостя! И не смей вновь упускать цель.', '', 28153),
(140158, 'ruRU', 'Тихо! Мы не одни...', '', 28153),
(140157, 'ruRU', 'Дальше не пройти. Вход запечатан неизвестным заклинанием.', '', 28153),
(140156, 'ruRU', 'Не стоило приходить в пустыню. Здесь принцесса тебя не спасет.', '', 28153),
(140155, 'ruRU', 'Ахеон Кор.', '', 28153),
(140154, 'ruRU', '', 'Ахеон Кор.', 28153),
(140153, 'ruRU', '', 'Аркенон порос.', 28153),
(140152, 'ruRU', 'Аркенон порос.', '', 28153),
(140151, 'ruRU', '', 'Тену\'бала.', 28153),
(140150, 'ruRU', 'Тену\'бала.', '', 28153),
