(140146, 'ruRU', '', 'Приветствую.', 28153),
(140145, 'ruRU', '', 'Мне нужен лекарь!', 28153),
(140144, 'ruRU', 'Мне нужен лекарь!', '', 28153),
(140143, 'ruRU', '', 'Мне нужно лечение!', 28153),
(140142, 'ruRU', 'Мне нужно лечение!', '', 28153),
(140141, 'ruRU', 'Исцелите меня!', '', 28153),
(140140, 'ruRU', '', 'Исцелите меня!', 28153),
(140139, 'ruRU', 'Исцелите меня!', '', 28153),
(140138, 'ruRU', '', 'Исцелите меня!', 28153),
(140137, 'ruRU', '', 'Прощай.', 28153),
(140136, 'ruRU', 'Прощай.', '', 28153),
(140135, 'ruRU', '', 'Стремись к миру, но готовься к войне!', 28153),
(140134, 'ruRU', 'Стремись к миру, но готовься к войне!', '', 28153),
(140133, 'ruRU', 'Служи с доблестью и смирением.', '', 28153),
(140132, 'ruRU', '', 'Служи с доблестью и смирением.', 28153),
(140131, 'ruRU', 'Мы найдем свое место в этом мире.', '', 28153),
(140130, 'ruRU', '', 'Мы найдем свое место в этом мире.', 28153),
(140129, 'ruRU', 'Черпай силы в даре аркан\'дора.', '', 28153),
(140128, 'ruRU', '', 'Черпай силы в даре аркан\'дора.', 28153),
