(140113, 'ruRU', '', 'Идем.', 28153),
(140112, 'ruRU', '', 'Идем.', 28153),
(140111, 'ruRU', 'За мной.', '', 28153),
(140110, 'ruRU', 'За мной.', '', 28153),
(140109, 'ruRU', 'Только между нами, $p, слышишь? Секрет \"Золотого клыка\".', '', 28153),
(140108, 'ruRU', 'Мм-м... этот фрукт выглядит аппетитно! Положим его на фуршетный стол.', '', 28153),
(140107, 'ruRU', 'Ты добудь фрукты, а я пока приготовлю шашлычки из скорпидов!', '', 28153),
(140106, 'ruRU', '$n насыщает чешую статическим электричеством!', '$n насыщает чешую статическим электричеством!', 28153),
(140105, 'ruRU', '', 'Первый полет твой, если хочешь, $p. Просто скажи мне, если тебе нужно куда-то отправиться по воздуху.', 28153),
(140104, 'ruRU', '', 'Осторожно. На кряже прячутся завролиски, они любят бросаться на добычу сверху.', 28153),
(140103, 'ruRU', 'Назад!', '', 28153),
(140102, 'ruRU', '', 'Назад!', 28153),
(140101, 'ruRU', 'Назад!', '', 28153),
(140100, 'ruRU', '', 'Уходим отсюда!', 28153),
(140099, 'ruRU', '', 'В укрытие!', 28153),
(140098, 'ruRU', 'В укрытие!', '', 28153),
(140097, 'ruRU', '', 'В укрытие!', 28153),
(140096, 'ruRU', 'В укрытие!', '', 28153),
(140095, 'ruRU', 'Отступаем!', '', 28153),
(140094, 'ruRU', '', 'Отступаем!', 28153),
(140093, 'ruRU', 'Отступаем!', '', 28153),
(140092, 'ruRU', '', 'Отступаем!', 28153),
(140091, 'ruRU', 'Да наделят тебя лоа быстротой ветра. Короля нужно предупредить как можно скорее!', '', 28153),
(140090, 'ruRU', 'Как только путь будет свободен, подходи к боевому кораблю Као. Да хранят тебя духи.', '', 28153),
(140089, 'ruRU', 'Да.', '', 28153),
(140088, 'ruRU', '', 'Да.', 28153),
(140087, 'ruRU', 'Да.', '', 28153),
(140086, 'ruRU', '', 'Да.', 28153),
(140085, 'ruRU', 'Наши воины собираются на верхней террасе. За Зулдазар!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140080, 'ruRU', '<Train noises--chugga chugga choo choo!>', '', 28153),
