(140061, 'ruRU', '', '<Laughing sounds>', 28153),
(140060, 'ruRU', '', '<Kiss sound>', 28153),
(140059, 'ruRU', '<Kiss sound>', '', 28153),
(140058, 'ruRU', '', '<Kiss sound>', 28153),
(140057, 'ruRU', '<Kiss sound>', '', 28153),
(140056, 'ruRU', 'Мы не убоимся тьмы.', '', 28153),
(140055, 'ruRU', 'Здесь тебе всегда рады.', '', 28153),
(140054, 'ruRU', 'Приветствую тебя.', '', 28153),
(140053, 'ruRU', 'Привет тебе.', '', 28153),
(140052, 'ruRU', 'Исцелите мои раны!', '', 28153),
(140051, 'ruRU', 'Исцелите меня!', '', 28153),
(140050, 'ruRU', 'Пусть гора дарует тебе тень и покой.', '', 28153),
(140049, 'ruRU', 'Пусть дорога приведет тебя к мудрости.', '', 28153),
(140048, 'ruRU', 'Пусть Мать-Земля укажет тебе путь.', '', 28153),
(140047, 'ruRU', 'До встречи.', '', 28153),
(140046, 'ruRU', 'За Орду!', '', 28153),
(140045, 'ruRU', '', 'За Орду!', 28153),
(140044, 'ruRU', 'За Альянс!', '', 28153),
(140043, 'ruRU', '', 'За Альянс!', 28153),
(140042, 'ruRU', 'За Орду!', '', 28153),
(140041, 'ruRU', '', 'Не отставайте.', 28153),
(140040, 'ruRU', 'На помощь!', '', 28153),
(140039, 'ruRU', 'Мне нужна помощь!', '', 28153),
(140038, 'ruRU', 'Приближается опасность!', '', 28153),
(140037, 'ruRU', '', '', 28153),
(140036, 'ruRU', '', '', 28153),
(140035, 'ruRU', '', '', 28153),
(140034, 'ruRU', 'Это недопустимо.', '', 28153),
(140033, 'ruRU', 'Я так не думаю.', '', 28153),
(140032, 'ruRU', 'Нет.', '', 28153),
(140031, 'ruRU', 'Ладно, попробуем... Джо\'чунга! А ну отправляйся в ту хижину и начинай готовиться к ритуалу!', 'Ладно, попробуем... Джо\'чунга! А ну отправляйся в ту хижину и начинай готовиться к ритуалу!', 28153),
(140030, 'ruRU', 'Скорее. Времени у нас в обрез!', '', 28153),
(140029, 'ruRU', 'Согласен.', '', 28153),
(140028, 'ruRU', 'Да будет так.', '', 28153),
(140027, 'ruRU', 'Тсс! Слушай, нам нельзя вызывать подозрений. У троллей крови всем заправляют женщины.$B$BПрикажи мне пойти вон в ту хижину – может, готовить кровавый ритуал или что-то в этом роде.$B$BНикого не удивит, если ты будешь мной помыкать.', '', 28153),
(140026, 'ruRU', 'Точно.', '', 28153),
(140025, 'ruRU', 'Открыть огонь!', '', 28153),
(140024, 'ruRU', 'Огонь по врагам!', '', 28153),
(140023, 'ruRU', 'Мне нужна мана.', '', 28153),
(140022, 'ruRU', 'Мне не хватает маны.', '', 28153),
(140021, 'ruRU', '', '', 28153),
(140020, 'ruRU', '', '', 28153),
(140019, 'ruRU', 'Не стоит благодарности.', '', 28153),
(140018, 'ruRU', 'Рад помочь.', '', 28153),
(140017, 'ruRU', 'Не за что.', '', 28153),
(140016, 'ruRU', 'Тысяча благодарностей.', '', 28153),
(140015, 'ruRU', 'Я перед тобой в неоплатном долгу!', '', 28153),
(140014, 'ruRU', 'Я твой должник.', '', 28153),
(140013, 'ruRU', '', '', 28153),
(140012, 'ruRU', 'Держите позицию.', '', 28153),
(140011, 'ruRU', 'Не уходите.', '', 28153),
(140010, 'ruRU', 'Так и есть.', '', 28153),
(140009, 'ruRU', 'Верно.', '', 28153),
(140008, 'ruRU', 'Да.', '', 28153),
(140004, 'ruRU', 'Я завидую вам. Вы лично увидите рассвет новой империи троллей. Жаль, старина Растахан его не застанет.', '', 28153),
(140003, 'ruRU', 'Могу сделали, что нужно, – отвлекли телохранителей короля.', '', 28153),
(140002, 'ruRU', 'Пророчество скоро исполнится. Прямо сейчас Зул делает свой ход.', '', 28153),
(140001, 'ruRU', 'Вилнак\'дор! Если Као сказал правду, с тобой будет то же самое!', '', 28153),
(140000, 'ruRU', '', 'Король?', 28153),
(139999, 'ruRU', 'Все равно... вашему королю конец...', '', 28153),
(139998, 'ruRU', 'Я знал, что этому негодяю нельзя верить! Он заплатит за это!', '', 28153),
(139997, 'ruRU', 'Зул обещал новую империю, и она БУДЕТ нашей.', '', 28153),
(139996, 'ruRU', 'Оглянись вокруг, Као. Ты проиграл! Сложи оружие!', '', 28153),
(139995, 'ruRU', 'Я ужас степей! Во мне сила грома! Я не могу проиграть!', '', 28153),
(139994, 'ruRU', '', 'Мы зандалары! Мы никогда не сдаемся!', 28153),
(139993, 'ruRU', 'Зулдазар наш по праву. Сдавайтесь, и я дарую вам быструю смерть.', '', 28153),
(139992, 'ruRU', 'Хм-м. Я думал, вы будете достойными противниками.', '', 28153),
(139991, 'ruRU', 'Таз\'динго! За короля Растахана!', '', 28153),
(139990, 'ruRU', '', 'Хабуту, расскажи королю Растахану о предательстве Зула. А $p поможет мне разобраться с этим существом.', 28153),
(139989, 'ruRU', 'Прибытие зандаларского флота', 'Прибытие зандаларского флота', 28153),
(139988, 'ruRU', 'Покажи-ка мне свои шляпы.', 'Покажи-ка мне свои шляпы.', 28153),
(139987, 'ruRU', 'Это ты?\n\nНет, серьезно, это снова ты, в целости и сохранности!\n\nА я перепугался, думаю, кто идет? Я тут прибирался в таверне вместе с Зулсаном, как и обещал... заметно?', '', 28153),
(139986, 'ruRU', 'Покажи мне свои камни!', 'Покажи мне свои камни!', 28153),
(139985, 'ruRU', 'У меня отличная идея: покупаешь две шляпы, одну надеваешь, другую отдаешь другу, коллеге или брату. Мне все равно.', '', 28153),
(139984, 'ruRU', 'Разумеется, я продаю шляпы парами. У меня же две головы!$b$bЯ погляжу, у тебя только одна. Ты уж извини. Но ты можешь оставить вторую шляпу про запас!', '', 28153),
(139983, 'ruRU', 'Хочешь купить шляпу? У меня их полно! Две по цене двух!', '', 28153),
(139982, 'ruRU', 'Хочешь обрести такую же силу, как у Бу\'лыжа? Купи у меня камень и бей им кого-нибудь каждый день. Тогда твоя сила сравнится с моей.$b$bНу, или не сравнится.', '', 28153),
(139981, 'ruRU', 'Купи у Бу\'лыжа камни! У меня самые лучшие камни, по самой лучшей цене!', '', 28153),
(139980, 'ruRU', 'Эй, ты! Хочешь купить камень? У меня только самые лучшие камни.', '', 28153),
(139979, 'ruRU', 'Сердце Сетралисс окутывает красное зарево. Что это значит?', 'Сердце Сетралисс окутывает красное зарево. Что это значит?', 28153),
(139978, 'ruRU', 'Нам надо держаться.', 'Нам надо держаться.', 28153),
(139977, 'ruRU', 'Найти Тропу Мертвеца несложно. Иди к темным зловещим скалам на северо-западе. Будет весело!', '', 28153),
(139976, 'ruRU', 'Когда придешь к лагерю, превратишься в одну из них. Но будь осторожнее! Облик может развеяться.', '', 28153),
(139975, 'ruRU', 'Тебе нужно быть на вид как их женщины. Они — главные в отрядах. Не волнуйся, мое вуду должно сработать.', '', 28153),
(139974, 'ruRU', 'Предупреждаю... будет больно... может, даже сильно больно!', '', 28153),
(139727, 'ruRU', 'Я готов приступить к ритуалу, который замаскирует меня под тролля крови.', 'Я готова приступить к ритуалу, который замаскирует меня под тролля крови.', 28153),
(139726, 'ruRU', 'Здесь повсюду действительно какое-то очень плохое вуду.', '', 28153),
(139592, 'ruRU', 'Если понадоблюсь, я буду где-нибудь подальше от Изарна.', '', 28153),
(139567, 'ruRU', 'Вижу, пока меня не было, у тебя появились новые друзья.', '', 28153),
(139482, 'ruRU', '', 'Мы должны удержаться здесь любой ценой! Нельзя дать могу прорваться дальше.', 28153),
(139443, 'ruRU', 'Твой друг свободен, но я бы не спускал с него глаз.', '', 28153),
(139410, 'ruRU', 'Будет сделано.', '', 28153),
(139408, 'ruRU', 'В городе беспорядки. Мы должны позаботиться о твоей безопасности!', '', 28153),
(139406, 'ruRU', 'Мой король, мы не оставим тебя.', '', 28153),
(139401, 'ruRU', 'У тебя был шанс. Зандалары не будут жить в страхе перед твоими прислужниками.', '', 28153),
(139397, 'ruRU', 'Мои солдаты прочешут город и поищут остальных.', '', 28153),
(139391, 'ruRU', 'Я обязан тебе жизнью, $p. Здесь опасно, поговорим в храме.', '', 28153),
(139390, 'ruRU', '', 'Эй! Вы болтать пришли или помогать? Вперед, на охоту!', 28153),
(139389, 'ruRU', 'Брат Терольд! Лорд Штормсонг! Вы прибыли как нельзя кстати! Ваша помощь нам очень пригодится!', '', 28153),
(139388, 'ruRU', 'Найдешь меня, когда все соберешь, я буду с остальными в безопасном месте. Надо кое-что подготовить.', '', 28153),
(139387, 'ruRU', 'Эй, ты! Иди сюда, пока чудища не вернулись добить меня.', '', 28153),
(139386, 'ruRU', 'Они могут забрать нашу землю, но они никогда не отнимут наши бессмертные души.', '', 28153),
(139385, 'ruRU', 'Спасибо тебе. Я сам найду дорогу домой.', 'Спасибо тебе. Я сама найду дорогу наружу.', 28153),
(139384, 'ruRU', 'Сюда! Мы охраняем блестяшки Каза\'джина.', 'Сюда! Мы охраняем блестяшки Каза\'джина.', 28153),
(139383, 'ruRU', '', 'Гарпунщики, приготовьтесь! С такими чудищами мы еще не сталкивались!', 28153),
(139375, 'ruRU', 'Береги пальцы. Ранишу всеядны. То есть они едят абсолютно все, понимаешь?', '', 28153),
(139374, 'ruRU', '', 'Если ты тоже ищешь Таджи, то он должен быть на холме к югу отсюда.', 28153),
(139372, 'ruRU', 'Как разберешься здесь, возвращайся к каравану. Я пока займусь ремонтом.', '', 28153),
(139371, 'ruRU', 'Поздравляю, $p. Тебе удалось выжить в бою с ранишу. Таких счастливчиков немного.', '', 28153),
(139370, 'ruRU', 'Прочная и долговечная... Эта древесина отлично подойдет для ремонта нашего каравана.', '', 28153),
(139369, 'ruRU', 'Благодаря качественной древесине, которую тебе удалось раздобыть, починка каравана идет бодро.', '', 28153),
(139368, 'ruRU', '', 'Ладно... Хм-м... Есть, нашла! Свиток невидимости... То, что нам нужно.', 28153),
(139367, 'ruRU', '', 'У нас нет на это времени!', 28153),
(139366, 'ruRU', 'Я не рассказывал эту невероятную историю? С чего бы начать?..', '', 28153),
(139365, 'ruRU', '', 'Ого... этот, похоже, написан на языке Древних богов. И где ты только такие откапываешь?', 28153),
(139364, 'ruRU', 'Нет! Ты хоть прочитала, для чего он? Впрочем... держи его под рукой. Пригодится попозже.', '', 28153),
(139363, 'ruRU', '', 'Так... свиток вечного возвращения подойдет?', 28153),
(139362, 'ruRU', 'Поможешь мне вернуться к Элби? Наверняка он волнуется.', '', 28153),
(139361, 'ruRU', 'Когда спасешь всех остальных, приходи на восточный склон, и мы сразимся с повелительницей приливов!', '', 28153),
(139360, 'ruRU', '', 'Ох, это займет вечность! Ты не представляешь, сколько свитков у этого старикана.', 28153),
(139358, 'ruRU', 'Мы должны помочь остальным!', 'Мы должны помочь остальным!', 28153),
(139357, 'ruRU', 'Защищайте флот!', 'Защищайте флот!', 28153),
(139356, 'ruRU', 'Порт должен выстоять!', 'Порт должен выстоять!', 28153),
(139355, 'ruRU', 'Во имя короля Растахана!', 'Во имя короля Растахана!', 28153),
(139354, 'ruRU', 'Я знал, что он где-то завалялся! Теперь тролли крови нас не заметят. Только держитесь ближе.', '', 28153),
(139353, 'ruRU', 'Когда-то я бы справился с целой стаей этих змеюк. Но они напали на меня в темноте всей толпой! Их становилось все больше, они кричали: \"Скорее! Азшаре нужен трофей!\"', '', 28153),
(139351, 'ruRU', 'Нам пригодятся любые сведения, мой господин. Расскажи нам все, что сможешь.', '', 28153),
(139350, 'ruRU', 'Наги здесь что-то ищут. И это \"что-то\" необходимо Азшаре. Их надо или остановить, или сбить с толку.', '', 28153),
(139348, 'ruRU', 'Я... Я не совладал с сектантами, и они захватили город.', '', 28153),
(139347, 'ruRU', 'Слышите? Это зов Бвонсамди! Вечность ждет нас!', 'Слышите? Это зов Бвонсамди! Вечность ждет нас!', 28153),
(139346, 'ruRU', 'Мой господин! Ты цел? Что случилось?', '', 28153),
(139345, 'ruRU', 'Брэннон!', '', 28153),
(139344, 'ruRU', 'Голос... Он зовет нас... Мы должны подчиниться!', 'Голос... Он зовет нас... Мы должны подчиниться!', 28153),
(139343, 'ruRU', 'Это еще что такое? Я был болен и лежал в постели... а теперь... Где я?', 'Это еще что такое? Я была больна и лежала в постели... а теперь... Где я?', 28153),
(139341, 'ruRU', 'Жизнь... за императора...', '', 28153),
(139339, 'ruRU', 'Я не смог стать для своих людей сильным правителем, и они обратились к другой силе.', '', 28153),
(139338, 'ruRU', 'Дядя доверил мне этот город, чтобы я поучился на практике, но... сектанты? Что я могу сделать с сектантами?!', '', 28153),
(139336, 'ruRU', 'Тысяча битв... тысяча побед.', '', 28153),
(139335, 'ruRU', 'Гром не заставишь замолчать.', '', 28153),
(139334, 'ruRU', 'Спасибо за помощь! Конвэй и его банда так быстро захватили город... Я такого не ожидал.', '', 28153),
(139333, 'ruRU', 'Буря... стихает...', '', 28153),
(139329, 'ruRU', 'Наша воля – воля богов...', '', 28153),
(139328, 'ruRU', 'Даже камень... можно разбить.', '', 28153),
(139327, 'ruRU', 'Твоя плоть... слаба...', '', 28153),
(139326, 'ruRU', 'Империя будет вечной...', '', 28153),
(139317, 'ruRU', 'Нам всегда нужны новые рабы.', '', 28153),
(139316, 'ruRU', 'Ощути ярость шторма!', '', 28153),
(139315, 'ruRU', 'На колени передо мной!', '', 28153),
(139314, 'ruRU', 'Я воплощение силы!', '', 28153),
(139312, 'ruRU', 'Зандалары исполнят обещанное или умрут.', '', 28153),
(139311, 'ruRU', 'Я раздавлю твой череп голыми руками!', '', 28153),
(139309, 'ruRU', 'Мы отстроим империю заново – из ваших костей!', '', 28153),
(139308, 'ruRU', 'Ты будешь служить нам!', '', 28153),
(139307, 'ruRU', 'Брэннон, неразумное дитя! Я заключил сделку и приведу этот город к процветанию без твоей помощи!', 'Брэннон, неразумное дитя! Я заключил сделку и приведу этот город к процветанию без твоей помощи!', 28153),
(139306, 'ruRU', 'Чтобы сдержать врага, нам нужны ресурсы – железо и древесина. За работу!', '', 28153),
(139305, 'ruRU', '', 'Что тебе известно о с-секретах этого острова? Говори!', 28153),
(139304, 'ruRU', 'Мы всссегда будем повелителями морей!', '', 28153),
(139303, 'ruRU', 'Ты захлебнешься в холодных волнах!', '', 28153),
(139298, 'ruRU', '', 'Ну ладно, я пойду к каравану. До скорой встречи, $p!', 28153),
(139295, 'ruRU', '$p, Кона, спасибо за помощь. Я перед вами в долгу.', '', 28153),
(139294, 'ruRU', '', 'Мы были готовы сражаться рядом с тобой до конца, Ручейник.', 28153),
(139293, 'ruRU', 'Хорошо, что Тун\'ка Пагубный освободился. Такой могущественный элементаль... доставил бы нам немало хлопот.', '', 28153),
(139292, 'ruRU', 'Значит, весь этот хаос из-за одного шамана? Спасибо за его ликвидацию.', '', 28153),
(139291, 'ruRU', 'Ха-ха! Получи, грязное отродье Орды!', '', 28153),
(139290, 'ruRU', 'Ритуал почти завершен! Тун\'ка Пагубный, я сковываю тебя своим заклинанием!', '', 28153),
(139288, 'ruRU', '', 'Тебе же хуже!... Пф-ф... самоуверенный наглец.', 28153),
(139287, 'ruRU', 'Да откуда тебе знать? Оставайтесь, если хотите, а мы пойдем вперед. Я знаю здесь каждый закуток.', '', 28153),
(139286, 'ruRU', 'Они вас прикончат. Эти тролли сильнее и злее тех, что мы встречали во время последнего паломничества.', '', 28153),
(139285, 'ruRU', 'Ха! Ты нам не указ. Мы пойдем и преподадим урок этим мясникам!', '', 28153),
(139284, 'ruRU', '', 'Нет, тролли крови вам не по зубам. Лучше останьтесь и помогите нам придумать план.', 28153),
(139283, 'ruRU', 'Киша, Лашк. Сейчас те, кто жрет останки Торги, пожалеют об этом.', '', 28153),
(139282, 'ruRU', '', 'Очень вовремя! Я думала, нас одних заботит смерть Торги.', 28153),
(139281, 'ruRU', 'Наконец кто-то решил вытащить голову из панциря и спуститься.', '', 28153),
(139250, 'ruRU', '|cffffff00+$1i ед. железа|r', '|cffffff00+$1i ед. железа|r', 28153),
(139241, 'ruRU', 'Не опускайте оружие!', '', 28153),
(139240, 'ruRU', '', 'Мы отличная команда, правда?', 28153),
(139204, 'ruRU', '', 'Я убила еще одного, Ручейник! Итого уже двадцать семь!', 28153),
(139198, 'ruRU', '|cffffff00+$1i ед. древесины|r', '|cffffff00+$1i ед. древесины|r', 28153),
(139168, 'ruRU', 'Да... твоя борьба... твои муки... нужны Г\'ууну.', '', 28153),
(139167, 'ruRU', 'Сражайся с Г\'ууном... терпи неудачу... страдай...', '', 28153),
(139165, 'ruRU', 'Ко мне.', '', 28153),
(139164, 'ruRU', 'Хватит.', '', 28153),
(139163, 'ruRU', 'Мастерская готова!', '', 28153),
(139162, 'ruRU', 'Мастерская готова. Наши разрушители покажут Альянсу, как легко ломаются стены.', '', 28153),
(139097, 'ruRU', '$n покрывает свои когти ядом!', '$n покрывает свои когти ядом!', 28153),
(139080, 'ruRU', 'Ты не видишь... того, что скрыто...', '', 28153),
(139079, 'ruRU', 'Никто не выстоит перед нашей мощью!', '', 28153),
(139078, 'ruRU', 'Вы все склонитесь перед новыми владыками!', '', 28153),
(139077, 'ruRU', 'Мы будем править этой землей. Мы должны...', '', 28153),
(139073, 'ruRU', 'Бури повинуются мне!', '', 28153),
(139072, 'ruRU', 'Ты об этом пожалеешь!', '', 28153),
(139071, 'ruRU', 'У меня больше силы, чем когда-либо будет у тебя!', '', 28153),
(139070, 'ruRU', 'Я предупреждал!', '', 28153),
(139065, 'ruRU', 'Наши слова исполнены силы. Эта земля будет принадлежать нам!', '', 28153),
(138870, 'ruRU', '', '$c, обитатели Лощины Лучников в долгу перед тобой. \n\nОтправляйся к мисс Уэйкрест. А мы займемся остатками ковена.', 28153),
(138865, 'ruRU', '', 'А вот и ты! С возвращением! Пожалуйста, скажи мне, что тебе удалось покончить с матроной!', 28153),
(138864, 'ruRU', '', 'С тех пор, как из шахты начала бить энергия, мы в нее не входили. \n\nЭто плетеное существо, которое тебе удалось подчинить, может оказаться нашей единственной надеждой.', 28153),
(138859, 'ruRU', '', 'Мы очень ценим твою помощь. До твоего вмешательства все выглядело хуже некуда.', 28153),
(138853, 'ruRU', 'Я продолжу разведку в деревне. Молюсь, чтобы ее жители уцелели!', '', 28153),
(138852, 'ruRU', 'Получилось! Теперь вы управляете сотворенным проклятием рабом!', '', 28153),
(138849, 'ruRU', 'Прочь!', '', 28153),
(138848, 'ruRU', '', 'Ну как? Теперь твоя душенька довольна?', 28153),
(138847, 'ruRU', '', 'Стою на месте? А если я буду ходить туда-сюда? Это считается?', 28153),
(138841, 'ruRU', 'Подойди ко мне, $p. Мы будем говорить.', '', 28153),
(138837, 'ruRU', '', 'Я тоже постараюсь что-нибудь узнать. Встретимся в городе.', 28153),
(138836, 'ruRU', '', 'Ты просто класс, $p. Надеюсь, мы еще встретимся!', 28153),
(138833, 'ruRU', 'Нам надо держаться.', '', 28153),
(138832, 'ruRU', 'Вперед, $n! Защищай народ Друствара!', '', 28153),
(138831, 'ruRU', 'Не волнуйтесь, дети моря. Чтобы найти лекарство, нужно верить в эти воды.', '', 28153),
(138830, 'ruRU', '', 'Если встретишь других гнусных ведьм, задай им как следует за меня!', 28153),
(138829, 'ruRU', '', 'Хорошо, что в нашем мире еще есть такие герои, как ты, $n.', 28153),
(138824, 'ruRU', '', 'Таджи и Кона уже должны были вернуться. Наверное, попали в переделку.', 28153),
(138823, 'ruRU', 'Наша главная задача – отыскать припасы. Нам надо есть.', '', 28153),
(138822, 'ruRU', 'О море, даруй облегчение больным и страдающим на Мысе Рыбака. Помоги найти источник болезни, что терзает нас!', '', 28153),
(138821, 'ruRU', 'Это большая удача, когда такие, как $n, оказываются рядом. Иначе никто бы вас не спас.', '', 28153),
(138820, 'ruRU', 'Продолжайте в том же духе – и будете сидеть дома три месяца!', '', 28153),
(138819, 'ruRU', 'Мы же исследователи!', '', 28153),
(138818, 'ruRU', '', 'Ой-ой-ой!', 28153),
(138817, 'ruRU', 'О-о! Ну ладно тебе, дедуля!', '', 28153),
(138816, 'ruRU', 'Вы у меня два месяца на улицу не выйдете!', '', 28153),
(138815, 'ruRU', '', 'Да, сэр.', 28153),
(138814, 'ruRU', 'Да, дедуля.', '', 28153),
(138813, 'ruRU', 'Да, дедуля.', '', 28153),
(138812, 'ruRU', 'Детям не следует сбегать из дома, и вы это знаете!', '', 28153),
(138811, 'ruRU', 'Надеюсь больше никогда не услышать эти звуки!', 'Надеюсь больше никогда не услышать эти звуки!', 28153),
(138810, 'ruRU', 'Наконец-то! Свобода!', 'Наконец-то! Свобода!', 28153),
(138809, 'ruRU', 'Ну все, теперь эта песня у меня из головы не выйдет.', 'Ну все, теперь эта песня у меня из головы не выйдет.', 28153),
(138808, 'ruRU', 'Спасибо тебе!', 'Спасибо тебе!', 28153),
(138807, 'ruRU', 'Смерть... наконец-то... теперь тебе предстоит... остановить Г\'ууна...', '', 28153),
(138804, 'ruRU', 'Думаешь, у тебя хватит сил остановить Г\'ууна? Это мы выясним на моей арене!', '', 28153),
(138803, 'ruRU', 'Назеш ведет себя весьма непочтительно. Преподай ей урок хороших манер, который она запомнит... навсегда. И помни про свиток, он поможет!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(138802, 'ruRU', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_EARTH.BLP:20|tКровь игрока $n |cFFFF0000|Hspell:255582|h[осквернена]|h|r!', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_EARTH.BLP:20|tКровь игрока $n |cFFFF0000|Hspell:255582|h[осквернена]|h|r!', 28153),
(138801, 'ruRU', '', '|TInterface\\Icons\\SPELL_HOLY_PURIFY.BLP:20|t$n использует заклинание |cFFFF0000|Hspell:255577|h[Переливание]|h|r!', 28153),
(138800, 'ruRU', '', '$n покрывает руки золотом.', 28153),
(138799, 'ruRU', 'Здесь жили только крохотные мурлоки, но потом разразилась буря, и на берегу появились наги. Меня схватили первым. Какой конфуз!', '', 28153),
(138798, 'ruRU', 'Освободи мой дух!', '', 28153),
(138797, 'ruRU', 'Я больше не могу терпеть! Избавь меня от этой боли!', '', 28153),
(138796, 'ruRU', 'Позволь мне отправиться к Бвонсамди, прошу!', '', 28153),
(138795, 'ruRU', 'Мне больно! Избавь меня от страданий!', '', 28153),
(138794, 'ruRU', 'Прогони боль!', '', 28153),
(138793, 'ruRU', 'Я себе не хозяин!', '', 28153),
(138792, 'ruRU', 'Прошу, я больше не хочу страдать!', '', 28153),
(138791, 'ruRU', '', 'Освободи мой дух!', 28153),
(138790, 'ruRU', '', 'Я больше не могу терпеть! Избавь меня от этой боли!', 28153),
(138789, 'ruRU', '', 'Позволь мне отправиться к Бвонсамди, прошу!', 28153),
(138788, 'ruRU', '', 'Мне больно! Избавь меня от страданий!', 28153),
(138787, 'ruRU', '', 'Прогони боль!', 28153),
(138786, 'ruRU', '', 'Я себе не хозяйка!', 28153),
(138785, 'ruRU', '', 'Прошу, я больше не хочу страдать!', 28153),
(138784, 'ruRU', '', 'Я внемлю зову стихий и иду, куда манят меня ветра.', 28153),
(138783, 'ruRU', 'Как эти твари вообще оказались у меня в желудке?!', 'Как эти твари вообще оказались у меня в желудке?!', 28153),
(138782, 'ruRU', 'Мне... Мне нехорошо...', 'Мне... Мне нехорошо...', 28153),
(138781, 'ruRU', 'Мой желудок давно не был так счастлив!', 'Мой желудок давно не был так счастлив!', 28153),
(138779, 'ruRU', 'Это... было у меня внутри?', 'Это... было у меня внутри?', 28153),
(138776, 'ruRU', '', 'Так что, если не собираешься помочь, ступай своей дорогой.', 28153),
(138775, 'ruRU', '', 'Добро пожаловать в Лощину Лучников, |3-6($c). Прости за бардак, у нас тут неприятности с ведьмами.', 28153),
(138774, 'ruRU', 'Я думал, эти духи меня убьют! Спасибо!', 'Я думала, эти духи меня убьют! Спасибо!', 28153),
(138773, 'ruRU', 'Спасибо. Сейчас найду своего питомца и уберусь прочь из этого проклятого места!', 'Спасибо. Сейчас найду своего питомца и уберусь прочь из этого проклятого места!', 28153),
(138772, 'ruRU', 'Спасибо тебе!', 'Спасибо тебе!', 28153),
(138771, 'ruRU', 'Никогда раньше не видел таких духов. Лучше пойду отсюда подальше!', 'Никогда раньше не видела таких духов. Лучше пойду отсюда подальше!', 28153),
(138770, 'ruRU', 'Благодарю за спасение.', 'Благодарю за спасение.', 28153),
(138769, 'ruRU', 'Спасибо тебе. Я уж думал, мне конец!', 'Спасибо тебе! Я уж думала, мне конец!', 28153),
(138768, 'ruRU', 'Прости, что потревожил. $n, я пришел со срочной просьбой.', '', 28153),
(138767, 'ruRU', 'Кто ты, незнакомец? Не тролль крови... иначе духи разорвали бы тебя.', '', 28153),
(138766, 'ruRU', 'Стой... что-то приближается.', '', 28153),
(138765, 'ruRU', 'Эти руины священны для Бвонсамди. Тролли крови сюда за нами не пойдут.', '', 28153),
(138762, 'ruRU', 'У меня их не так много, но они в вашем распоряжении.', '', 28153),
(138760, 'ruRU', '', 'Орда снова отступает? Я не понимаю их стратегию.', 28153),
(138759, 'ruRU', 'Нельзя дать вождю скрыться. Только взяв ее в плен, мы одержим победу в этой войне.', '', 28153),
(138758, 'ruRU', 'Ты ничто...', '', 28153),
(138757, 'ruRU', 'Эта бухта принадлежит повелительнице приливов Назеш! Мы найдем то, что сокрыто в Зулдазаре!', '', 28153),
(138756, 'ruRU', 'Хех... Свежее мясо.', 'Хех... Свежее мясо.', 28153),
(138755, 'ruRU', 'Очень неприятный. Лучше его пропустить. Я знаю укромное место, где можно спрятаться.', '', 28153),
(138754, 'ruRU', 'Это их ритуал вступления.', '', 28153),
(138753, 'ruRU', 'Ладно, проходите и отправляйтесь на... \"инструктаж\". Хе-хе.', '', 28153),
(138752, 'ruRU', 'Хм... У вас даже шляпы с собой...', '', 28153),
(138751, 'ruRU', 'Мы хотим присоединиться к братству Стальных Волн. Шляпы у нас свои.', 'Мы хотим присоединиться к братству Стальных Волн. Шляпы у нас свои.', 28153),
(138749, 'ruRU', 'Это священное место. Я буду вечно оберегать его.', '', 28153),
(138748, 'ruRU', 'Когда-то многие странники останавливались тут на пути в Некрополь.\n\nА теперь так тихо... Не нравится мне это. Совсем не нравится.', '', 28153),
(138747, 'ruRU', 'Я охранял это святилище с тех самых пор, как его возвели. И буду охранять, пока оно не рассыплется в прах.', '', 28153),
(138746, 'ruRU', 'Мы всегда рады тем, кто направляется в Некрополь.', '', 28153),
(138745, 'ruRU', 'По воле Бвонсамди я предлагаю отдых путникам, которые направляются в его храм.', '', 28153),
(138744, 'ruRU', 'Выглядит недурно. Скажем вербовщику, что мы добровольцы.', '', 28153),
(138743, 'ruRU', 'Шляпу надень. Без шляпы ты не морской волк!', '', 28153),
(138742, 'ruRU', 'Потерпи, Розалина. С помощью улучшенных гарпунов ты сможешь одолеть любого монстра.', '', 28153),
(138741, 'ruRU', '', 'Окри, как там дела с припасами? Я хочу отплыть при первой же возможности! Время не ждет!', 28153),
(138740, 'ruRU', 'Да? Чего надо?', 'Да? Чего надо?', 28153),
(138739, 'ruRU', 'Похоже, мне пока придется возвращаться в Боралус с пустыми руками. Встретимся там когда получишь свиток, и поговорим о награде.', '', 28153),
(138738, 'ruRU', 'А теперь слушай внимательно: свиток, который он должен тебе отдать, запечатан зеленым сургучом. Зеленым! Это важно!', '', 28153),
(138737, 'ruRU', 'Того, кто тебе нужен, зовут Карентан. Его магазин на юге города, на втором этаже.', '', 28153),
(138734, 'ruRU', 'Почему ты меня кусаешь? У меня даже мяса на костях нет.', '', 28153),
(138733, 'ruRU', 'Попробуй это, бешеная тварь!', '', 28153),
(138732, 'ruRU', 'Мне нравится твой задор! Сохрани его для сетраков!', '', 28153),
(138731, 'ruRU', 'Ха! Почти получилось!', '', 28153),
(138730, 'ruRU', 'Резан готовится |TInterface\\Icons\\ABILITY_MOUNT_FOSSILIZEDRAPTOR.BLP:20|t|cFFFF0000|Hspell:255421|h[пожрать]|h|r |3-3($n)!', '', 28153),
(138729, 'ruRU', 'Капитан Гулнаку заплатит за свой поступок.', '', 28153),
(138728, 'ruRU', 'Благодарю за спасение... За это оставлю тебя в живых.', '', 28153),
(138725, 'ruRU', 'Смотри, где копаешь! Я тут сплю!', 'Смотри, где копаешь! Я тут сплю!', 28153),
(138724, 'ruRU', 'Духи в этих краях не могут спокойно смотреть на то, как кто-то разрушает их дом...', '', 28153),
(138723, 'ruRU', 'Не думаю, что сбрасывать бомбы на кости – хорошая идея!', '', 28153),
(138722, 'ruRU', 'Я многих троллей спрашивал о Ксибале, и каждый раз слышал в ответ что-то новое – не важно, какие методы я применял на допросе.\n\nНекоторые говорили, что Ксибала заставлял тела врагов гнить и распухать.\n\nИли что каждый посмотревший на него становился живым скелетом.\n\nИли что он прятался в тени, выходил только ночью и пожирал спящих людей.\n\nИли что он ждал у дорог и насылал на проходящих мимо неизлечимый кровавый кашель, от которого они умирали. \n\nТак что понятно, почему местные держатся подальше!', '', 28153),
(138721, 'ruRU', 'Я так давно не бывал в этом месте. Но даже тогда его жители боялись и избегали нас... \n\nЗдесь полно злых духов, $n. Постарайся их не потревожить.', '', 28153),
(138717, 'ruRU', 'Зря ты тут бродишь, крыса, это дорожки Зем\'лана. Киффа, взять!', 'Зря ты тут бродишь, крыса, это дорожки Зем\'лана. Киффа, взять!', 28153),
(138716, 'ruRU', 'Орда... отомстит за меня...', '', 28153),
(138715, 'ruRU', 'Этот участок принадлежит Реликварию. Альянсу здесь делать нечего!', '', 28153),
(138709, 'ruRU', '', 'Не исключен сопутствующий ущерб, но думаю, со временем мы соберем кусочки воедино. Возможно, нам понадобятся еще лаборанты...', 28153),
(138707, 'ruRU', 'Эй, Залнон\'мак, в твоей шапке очень уютно! Пожалуй, оставлю ее себе!', '', 28153),
(138706, 'ruRU', 'Кто хочет выпить со мной?', '', 28153),
(138705, 'ruRU', 'Почему все так много работают? Разве вы не знаете, что мы живем вечно?', '', 28153),
(138704, 'ruRU', 'Эй, Сенджилак! Ксинанджи крадет твои вещи, когда ты не видишь!', '', 28153),
(138703, 'ruRU', 'Эй, Сегазея, от твоего прислужника воняет! Убери его отсюда!', '', 28153),
(138702, 'ruRU', 'Зулай, ты самое медлительное существо во всем мире!', '', 28153),
(138701, 'ruRU', 'Пить хочется? Печально!', '', 28153),
(138700, 'ruRU', 'Шевелитесь, тунеядцы. Мне нужен грог!', '', 28153),
(138699, 'ruRU', '$n захватывает рудник Сухоусов!', '$n захватывает рудник Сухоусов!', 28153),
(138698, 'ruRU', '', 'Никогда больше не смей убегать из дома. Слышишь? А теперь выдвигаемся. У нас много работы.', 28153),
(138691, 'ruRU', 'Я... Прошу вас, тише! Мы делаем все, что в наших силах. Мы найдем и лекарство, и источник заразы!', '', 28153),
(138690, 'ruRU', '', 'Терольд! Нам нужна твоя помощь! Нам нужно лекарство!', 28153),
(138689, 'ruRU', 'Откуда взялась эта болезнь?', '', 28153),
(138688, 'ruRU', '', 'Наши дети болеют!', 28153),
(138687, 'ruRU', 'Я требую реванша...', 'Я требую реванша...', 28153),
(138686, 'ruRU', 'Я весь день пил, чтобы к этому подготовиться...', 'Я весь день пила, чтобы к этому подготовиться...', 28153),
(138679, 'ruRU', 'Гулнаку это не понравится...', 'Гулнаку это не понравится...', 28153),
(138678, 'ruRU', 'Это моя карта сокровищ!', 'Это моя карта сокровищ!', 28153),
(138676, 'ruRU', 'Принеси голову вульперы и получи скидку на первую покупку!', '', 28153),
(138675, 'ruRU', 'Грог – лучшая профилактика обвала цен!', '', 28153),
(138674, 'ruRU', 'Повязок на глаз много не бывает!', '', 28153),
(138673, 'ruRU', 'Кто хочет выглядеть как сам Зем\'лан в последнем головном уборе Повязика? Подходи!', '', 28153),
(138672, 'ruRU', 'Йокса – лучший знаток моджо! Покупайте его новые зелья!', '', 28153),
(138671, 'ruRU', 'В продаже новые абордажные сабли! Гораздо острее старых!', '', 28153),
(138670, 'ruRU', 'Сразитесь вместе с ужасным тигром уже сегодня!', '', 28153),
(138669, 'ruRU', 'А вот кому вульперских стейков! С пылу с жару!', '', 28153),
(138668, 'ruRU', 'Сегодня у Огго скидки...', 'Сегодня у Огго скидки...', 28153),
(138666, 'ruRU', '', 'Я сама выберусь. А ты будь осторожнее.', 28153),
(138664, 'ruRU', 'Приберись тут... когда будешь уходить.', 'Приберись тут... когда будешь уходить.', 28153),
(138663, 'ruRU', 'Ты остановишься здесь... на веки вечные!', 'Ты остановишься здесь... на веки вечные!', 28153),
(138662, 'ruRU', '$c, нам нужна твоя помощь с одной маленькой проблемкой.', '', 28153),
(138661, 'ruRU', 'Мы будем вечно служить Зем\'лану.', 'Мы будем вечно служить Зем\'лану.', 28153),
(138660, 'ruRU', 'Я отдал все, чтобы защитить свою команду. Дальше ты не пройдешь!', 'Я отдала все, чтобы защитить свою команду. Дальше ты не пройдешь!', 28153),
(138659, 'ruRU', 'Мы вернемся с того света и снова отправимся в бой.', 'Мы вернемся с того света и снова отправимся в бой.', 28153),
(138658, 'ruRU', 'Я тебя разве не убивал? Или все было наоборот?', 'Я тебя разве не убивала? Или все было наоборот?', 28153),
(138655, 'ruRU', 'Я сожру твою плоть, а душу преподнесу хозяину!', '', 28153),
(138652, 'ruRU', 'Я срежу мясо с твоих костей!', '', 28153),
(138651, 'ruRU', 'Ты хорошо сражаешься для того, кто песка не нюхал... но я покончу с тобой!', '', 28153),
(138650, 'ruRU', 'Беги быстрее. Я буду охотиться за тобой целую вечность.', 'Беги быстрее. Я буду охотиться за тобой целую вечность.', 28153),
(138649, 'ruRU', 'Никто не заберет у меня мое сокровище! Ни ты, ни Зем\'лан – никто!', 'Никто не заберет у меня мое сокровище! Ни ты, ни Зем\'лан – никто!', 28153),
(138644, 'ruRU', 'Наша империя принесет вам погибель!', 'Наша империя принесет вам погибель!', 28153),
(138641, 'ruRU', 'Твоя смерть будет уроком для всех!', 'Твоя смерть будет уроком для всех!', 28153),
(138634, 'ruRU', '$Pr, не бойся. Я не собираюсь с тобой драться.\n\nЭто Зем\'лан со мной сотворил... Со всеми нами, не спрашивая, желаем ли мы этого.\n\nТолько посмотри на меня...\n\n<Кроткий Гунта тяжело вздыхает.>\n\nХочешь выпить?', '', 28153),
(138633, 'ruRU', 'Если хочешь выжить в Вол\'дуне, тебе придется смотреть в глаза смерти каждую минуту... и не вздумай моргнуть.', '', 28153),
(138631, 'ruRU', 'Нет добычи – нет получки!', 'Было твое – станет мое!', 28153),
(138628, 'ruRU', 'Наша сила в проклятии!', 'Мы отдали Зем\'лану все...', 28153),
(138627, 'ruRU', 'Живым не место в порту Зем\'лана.', 'Кто не в команде, тому не жить!', 28153),
(138625, 'ruRU', 'Я охраняю этот порт целую вечность.', 'Это наш порт!', 28153),
(138624, 'ruRU', 'Будь осторожнее! Не стоит недооценивать сетраков...', '', 28153),
(138623, 'ruRU', '', 'Дело сделано! Спасибо за помощь.', 28153),
(138622, 'ruRU', '', 'Я почти закончила...', 28153),
(138621, 'ruRU', '', 'И вот я наконец-то добралась до настоящих реликвий. Кажется, осталось еще немного.', 28153),
(138620, 'ruRU', '', 'А этой грудой костей, мы, видимо, обязаны Берчу, если судить по отметинам зубов.', 28153),
(138619, 'ruRU', '', '\"Настоящий прототип Лучеплавс\". Сколько металла перевела... но места для безделушек нет.', 28153),
(138618, 'ruRU', '', 'Несколько самых ценных находок осталось в том ящике. $c, ты прикрывай меня, а я попробую достать что смогу.', 28153),
(138615, 'ruRU', 'Мы не бросим храм.', '', 28153),
(138589, 'ruRU', 'Покуда существует этот храм, в его стенах тебе всегда будут рады.', '', 28153),
(138568, 'ruRU', '', 'О-о-ой! Дай только отдышаться, я тебе ка-а-ак врежу!', 28153),
(138567, 'ruRU', 'Стой! Я не собака! Я вообще удивляюсь, как ты бегаешь на этих своих ножках-обрубочках. Думал, ты скатишься по первому же склону.', '', 28153),
(138566, 'ruRU', '', 'Открытие! Я тебя обгоню, Берч! Тебе со мной не сравняться, даже будь у тебя в роду гончие!', 28153),
(138556, 'ruRU', 'Альянс захватил двор Стромгарда!', 'Альянс захватил двор Стромгарда!', 28153),
(138555, 'ruRU', '$n захватывает двор Стромгарда!', '$n захватывает двор Стромгарда!', 28153),
(138553, 'ruRU', '', 'Защищайте мирных жителей!', 28153),
(138552, 'ruRU', '', 'За мной, $n, на Высокогорную дорогу!', 28153),
(138551, 'ruRU', 'Надеюсь, что это так, миледи. Все по коням! Выдвигаемся!', '', 28153),
(138550, 'ruRU', '', 'Не желаю этого слушать, маршал. Поверьте, обо мне есть кому позаботиться.', 28153),
(138549, 'ruRU', 'Но для вашей же безопасности...', '', 28153),
(138548, 'ruRU', '', 'Маршал, отправляйтесь со своими людьми к Заставе Арома. Я вскоре присоединюсь к вам.', 28153),
(138547, 'ruRU', 'Альянс захватил дорогу Храброгласа!', 'Альянс захватил дорогу Храброгласа!', 28153),
(138546, 'ruRU', '$n захватывает дорогу Храброгласа!', '$n захватывает дорогу Храброгласа!', 28153),
(138545, 'ruRU', 'Кто следующий?', '', 28153),
(138544, 'ruRU', 'Добро пожаловать в команду проклятых, первый помощник.', '', 28153),
(138543, 'ruRU', 'А-а-а-а!', '', 28153),
(138542, 'ruRU', 'Джамбойя, воскресни!', '', 28153),
(138540, 'ruRU', 'Подойдите и примите мой дар. Мы будем одной командой до конца времен!', '', 28153),
(138539, 'ruRU', 'Это наш дом. Мы удержим порт во что бы то ни стало... Он наш навеки!', '', 28153),
(138538, 'ruRU', 'НЕТ!', 'НЕТ!', 28153),
(138537, 'ruRU', 'Сетраки думают, что мы сдадимся. А вы что скажете?', '', 28153),
(138535, 'ruRU', 'Мне недолго быть мертвым... До встречи, Джамбойя...', '', 28153),
(138534, 'ruRU', 'Бунтуешь, Джамбойя?! Да я тебя под килем протяну!', '', 28153),
(138533, 'ruRU', 'Что за трюмная крыса посмела бросить мне вызов?', '', 28153),
(138532, 'ruRU', '', 'Вы подчинитесь... Матери...', 28153),
(138531, 'ruRU', '', 'Сопротивляться глупо. Ковен будет править Кул-Тирасом.', 28153),
(138530, 'ruRU', 'Мы защитим леди. А ты убей эту ведьму.', '', 28153),
(138529, 'ruRU', '', 'Ты подчинишься Матери, Люсиль Уэйкрест!', 28153),
(138528, 'ruRU', 'Это еще что такое?', '', 28153),
(138527, 'ruRU', 'Ловушки не останавливают этих монстров. Их все больше!', '', 28153),
(138526, 'ruRU', 'Не волнуйся, Каль\'дран. Мы сможем победить Зардракса.', 'Не волнуйся, Каль\'дран. Мы сможем победить Зардракса.', 28153),
(138521, 'ruRU', '', 'Спасибо, констебль. Поможешь мне, |3-6($c)?', 28153),
(138520, 'ruRU', 'Мисс Уэйкрест, вы свободны... приношу свои извинения...', '', 28153),
(138519, 'ruRU', 'Слушайте все! Как выяснило следствие, в проклятии Лощины Лучников виновна другая ведьма.', '', 28153),
(138518, 'ruRU', '', 'Так-то лучше. А теперь...', 28153),
(138517, 'ruRU', '...я найду другого тролля крови. Их слишком много! Вы все обречены!', '', 28153),
(138516, 'ruRU', 'Нет! Нана\'квуг! Теперь мне придется...', '', 28153),
(138515, 'ruRU', 'Ха-ха... Это бессмысленно. Я слишком силен для вас!', '', 28153),
(138514, 'ruRU', 'Думаешь, это что-то изменит? По моим жилам струится сила Кровавого бога! Вам меня не остановить!', '', 28153),
(138513, 'ruRU', 'Я слабею... Ха-ха... Неужто ты и вправду думаешь, что это меня остановит?', '', 28153),
(138509, 'ruRU', 'Берегитесь! Враги идут из леса!', '', 28153),
(138502, 'ruRU', 'Готово! Это все, что я могу тебе дать, не истощая себя слишком сильно. Иди давай, жги кости.', '', 28153),
(138501, 'ruRU', 'Сосредоточься – я дам тебе частицу силы огненного моджо...', '', 28153),
(138500, 'ruRU', 'Я готов получить огненное моджо и уничтожить кости.', 'Я готова получить огненное моджо и уничтожить кости.', 28153),
(138499, 'ruRU', '', 'Что ж, придется нам самим ударить по ковену. И кажется, я знаю, как это сделать.', 28153),
(138498, 'ruRU', 'Он... в плену, миледи. Мы готовились вызволять его, когда узнали об этом... судилище.', '', 28153),
(138497, 'ruRU', '', 'А мой отец? Как он сражается против вторжения?', 28153),
(138496, 'ruRU', 'Они захватили земли за горами. Мы удерживаем Заставу Арома, но наши силы тают.', '', 28153),
(138495, 'ruRU', 'Миледи, все хуже некуда. Влияние ковена в Друстваре ширится, как лесной пожар.', '', 28153),
(138494, 'ruRU', '', 'Маршал! Что вы знаете об этом ковене? Что происходит на наших землях?', 28153),
(138449, 'ruRU', '', 'Ух ты! Посмотри, как выглядел старый Зем\'лан раньше!', 28153),
(138448, 'ruRU', '', 'Зем\'лан – тот еще мерзавец, да?', 28153),
(138439, 'ruRU', 'Собери идолов и приведи команду.', '', 28153),
(138438, 'ruRU', 'Сетраки не отнимут наш дом. Ни сегодня, ни через тысячу лет.', '', 28153),
(138437, 'ruRU', 'Я... Капитан, а по-другому никак? Команда...', '', 28153),
(138436, 'ruRU', 'Серьезно? Ты не шутишь?', 'Спасибо! Без тебя я бы точно не выжила!', 28153),
(138435, 'ruRU', 'Нет времени знакомиться. Я не собираюсь торчать в этой шахте ни минутой больше.', 'Нет времени знакомиться. Я не собираюсь торчать в этой шахте ни минутой больше.', 28153),
(138434, 'ruRU', 'Без лишних вопросов! Веди всех к алтарю! Живо!', '', 28153),
(138433, 'ruRU', 'Как же я рад тебя видеть!', 'Как же я рада тебя видеть!', 28153),
(138432, 'ruRU', 'Не знаю, кто ты и что ищешь, но спасибо.', 'Не знаю, кто ты и что ищешь, но спасибо.', 28153),
(138431, 'ruRU', 'Спасибо за помощь! Без тебя я бы точно не выжил!', 'Спасибо за помощь! Без тебя я бы точно не выжила!', 28153),
(138430, 'ruRU', 'Хоть руки у меня и устали, зато ноги готовы бежать отсюда что есть сил!', 'Не знаю, кто ты и что ищешь, но спасибо.', 28153),
(138429, 'ruRU', 'Проклятая пустыня! Проклятые змеи! Этот порт МОЙ!', '', 28153),
(138428, 'ruRU', 'Я у тебя в долгу.', 'Я у тебя в долгу.', 28153),
(138427, 'ruRU', 'Капитан, их слишком много! Надо отступать, иначе всей команде каюк.', '', 28153),
(138426, 'ruRU', 'Порубите этих змей на кусочки!', '', 28153),
(138373, 'ruRU', 'Будем надеяться, я бегаю быстрее этих головорезов!', '', 28153),
(138316, 'ruRU', 'Спасибо тебе, |3-6($c). Поговорим где-нибудь в более безопасном месте.', '', 28153),
(138288, 'ruRU', 'Не отступать! Кого не убьют сетраки, того убью я.', '', 28153),
(138282, 'ruRU', 'Собирай команду. Гони этих пьянчуг к воротам.', '', 28153),
(138281, 'ruRU', 'Никто не отберет его у меня!', '', 28153),
(138280, 'ruRU', 'Значит они так же глупы, как и остальные. Это порт Зем\'лана! МОЙ порт!', '', 28153),
(138279, 'ruRU', 'Капитан Зем\'лан, к нам идет армия сетраков! Их просто тьма!', '', 28153),
(138264, 'ruRU', 'Авиаинженер Краззл к твоим услугам!', '', 28153),
(138247, 'ruRU', 'Идите подыхайте в пустыню – вам там самое место.', '', 28153),
(138242, 'ruRU', 'А ваше заскорузлое тряпье мне не нужно. Так что вы, считай, все покойники.', '', 28153),
(138240, 'ruRU', 'На борт возьмем только тех, кто заплатит золотом!', '', 28153),
(138238, 'ruRU', 'Ну, конец так конец.', '', 28153),
(138235, 'ruRU', 'Если мы останемся на берегу, нам конец!', 'Если мы останемся на берегу, нам конец!', 28153),
(138234, 'ruRU', 'Беженцы, в сторону! Первыми на борт пойдут пираты!', '', 28153),
(138233, 'ruRU', 'Зем\'лан, пусти нас на корабль! Сетраки нас всех перебьют!', 'Зем\'лан, пусти нас на корабль! Сетраки нас всех перебьют!', 28153),
(138232, 'ruRU', 'Останется место – возьмем еще кого-нибудь.', '', 28153),
(138224, 'ruRU', '', 'Сейчас не самое подходящее время для визитов. \n\nЧто привело тебя сюда?', 28153),
(138214, 'ruRU', 'Ладно. Выходит, только мне.', '', 28153),
(138213, 'ruRU', '', 'Нисколько.', 28153),
(138212, 'ruRU', 'Не-а.', '', 28153),
(138211, 'ruRU', '', 'Нет.', 28153),
(138210, 'ruRU', 'Никому больше не кажется, что уничтожить столько сетраков из-за убийства нескольких из нас – это перебор?', '', 28153),
(138209, 'ruRU', 'Хорошо, что все закончилось, но мне кажется, это было чересчур.', '', 28153),
(138208, 'ruRU', '', 'Ха-ха! Вот здорово было! Это надо же – выжить после такого!', 28153),
(138203, 'ruRU', 'Дирижабль пошел!', '', 28153),
(138202, 'ruRU', 'Новый рекорд! Поздравляю!', '', 28153),
(138200, 'ruRU', 'Трогги пришли по моим следам. Это все я виноват. Пожалуйста, $n, помоги!', '', 28153),
(138123, 'ruRU', 'Ни один тортоллан не знал такой свободы!', '', 28153),
(138122, 'ruRU', 'Люблю этот ветер в панцире!', '', 28153),
(138121, 'ruRU', 'Я свободен как птица!', '', 28153),
(138120, 'ruRU', 'Ты такой крутой, пап!', '', 28153),
(138118, 'ruRU', 'Держи ее! Держи ее! Не отпускай!', '', 28153),
(138075, 'ruRU', 'Поможешь нам выбрать лошадь? Предупреждаю заранее: подойдет только идеальная!', '', 28153),
(138074, 'ruRU', 'Ленивые рабочие постоянно воруют. Если не можешь найти грог, поищи у рабочих.', '', 28153),
(138073, 'ruRU', 'Я держу ненужные вещи под водой. Чтобы не раскалялись.', '', 28153),
(138072, 'ruRU', '$p, а ты ничего так по упитанности. Захочешь чего-нибудь выпить – обращайся.', '', 28153),
(138071, 'ruRU', '', 'Вот тебе!', 28153),
(138070, 'ruRU', '', 'Тебе повезло, что я не могу достать выше! И не отпирайся! Это из-за тебя ловушка сработала!', 28153),
(138069, 'ruRU', 'Ай! Нога!', '', 28153),
(138068, 'ruRU', 'Я натворил? Я?! Это из-за тебя она сработала, несносная мелк...', '', 28153),
(138067, 'ruRU', '', '... исправить то, что ты натворил!', 28153),
(138066, 'ruRU', '', 'Тогда уходим отсюда. Надо найти кого-нибудь, с кем можно поторговать. Я умираю от голода.', 28153),
(138065, 'ruRU', '', 'Представляешь, я набрала достаточно камней и всяких штучек, чтобы покрыть месяц работы.', 28153),
(138064, 'ruRU', '', 'Да-да. Я тоже всех вас люблю.', 28153),
(138061, 'ruRU', '', 'Нам тут больше нечего ловить, ребята. Пакуемся и отчаливаем.', 28153),
(138060, 'ruRU', '', 'Я не удивлена. Было глупо рассчитывать на то, что проклятие удастся просто так рассеять.', 28153),
(138059, 'ruRU', 'Хочешь, покажу, как делается колбаса?', '', 28153),
(138058, 'ruRU', 'Я знаю, что будет с твоим мясом!', '', 28153),
(138057, 'ruRU', 'Из тебя получится отличный бекон!', '', 28153),
(138056, 'ruRU', 'Я... отправлю тебя... в мясорубку...', '', 28153),
(138055, 'ruRU', 'Ты... умрешь...', '', 28153),
(138054, 'ruRU', '', 'Пусть ветра несут тебя, $p... только не вздумай пополнять их ряды, ладно?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(138053, 'ruRU', '', 'Я вернусь к каравану и скажу всем, чтоб готовились обшарить это место, как только ты снимешь проклятье.', 28153),
(138052, 'ruRU', '', 'Вот, нашла кое-какие записи. Еще немного, и ритуал можно будет начинать.', 28153),
(138051, 'ruRU', '$c, мы так тебе благодарны за спасение от проклятья. Ты, наверное, умираешь с голоду.\n\nХочешь сосисок?', '', 28153),
(138050, 'ruRU', 'Веселись на здоровье! Развлекайся! Угощайся! Поместье в твоем распоряжении!', '', 28153),
(138049, 'ruRU', 'Тебе удалось спасти не только моего сына, но и мой фестиваль! Твои подвиги войдут в историю!', '', 28153),
(138048, 'ruRU', '', 'Что тебе предложить? Еду или еще чего?', 28153),
(138047, 'ruRU', 'Ободрение', 'Ободрение', 28153),
(138046, 'ruRU', '', 'Я подожду здесь, пока ты ищешь остальных идолов. Принеси их сюда, когда всех найдешь.', 28153),
(138045, 'ruRU', '', 'И один идол. Захватишь его, ладно?', 28153),
(138044, 'ruRU', '', 'По-моему, это был тронный зал Зем\'лана. Сколько там сокровищ!', 28153),
(138042, 'ruRU', 'Всем на позиции! Держать строй!', '', 28153),
(138040, 'ruRU', '', 'Мики, скорее всего, уже нет в живых. Уходи отсюда, пока можешь.', 28153),
(138039, 'ruRU', '', '$p, ты большой, толстый ангел! Мой герой!', 28153),
(138038, 'ruRU', 'Они увели Ану на юг, но я ухожу отсюда!', '', 28153),
(138037, 'ruRU', 'Мне надо вернуться в храм и восстанови силы. Буду ждать тебя там.', '', 28153),
(138036, 'ruRU', 'Наконец-то я свободен.', '', 28153),
(138035, 'ruRU', 'Возвращайся скорее, Нора.', '', 28153),
(138034, 'ruRU', '', 'Если уйдем сейчас, умрем от голода в дюнах.', 28153),
(138033, 'ruRU', '', 'Нет. И ты это знаешь.', 28153),
(138032, 'ruRU', 'Нора, ты не обязана это делать. Мы можем собраться и уехать, а Зем\'лан пусть остается.', '', 28153),
(138031, 'ruRU', '', 'Вигги, присмотри за караваном, пока меня не будет.', 28153),
(138029, 'ruRU', 'Давненько я тут не был... Надеюсь, у меня здесь еще остались друзья.', '', 28153),
(138028, 'ruRU', 'Найди доказательства того, что Эшвейны продают оружие этим выродкам. Как закончишь – встретимся на холме у главных ворот.', '', 28153),
(138026, 'ruRU', 'Ну, вот твои ноги. Что дальше?', 'Ну, вот твои ноги. Что дальше?', 28153),
(138025, 'ruRU', 'Это будет самый захватывающий фестиваль в истории! Седлай Бочонка и покажи этим троггам. Кстати, он весьма неплох в бою.', '', 28153),
(138024, 'ruRU', '$c, Листопадная Бухта перед тобой в неоплатном долгу. \n\nНадеюсь, когда-нибудь мы сможем отплатить тебе добром за добро.', '', 28153),
(138023, 'ruRU', 'Вы славно сработались с Бочонком! Можешь кататься на нем по всему поместью.', '', 28153),
(138021, 'ruRU', 'Многие никогда не узнают о твоих деяниях, но я буду помнить вечно.', '', 28153),
(138020, 'ruRU', '', '$c! Ты бросаешь мне вызов в моих же владениях?', 28153),
(138019, 'ruRU', '', 'Никто не услышит твои крики!', 28153),
(138018, 'ruRU', 'Приветствуем тебя, $n, наш достопочтенный гость!', '', 28153),
(138017, 'ruRU', '$n теперь с нами!', '', 28153),
(138016, 'ruRU', '$n, для нас честь приветствовать тебя в поместье Норвингтонов!', '', 28153),
(138015, 'ruRU', '', 'Меня зовут Джейн. Я служила наемницей на торговом судне, а потом на нас напали сирены.$B$BЭти ребята выловили меня из моря, дали новое имя и стали моей семьей.$B$BОни немного странные, но очень хорошие и честные. Кому-то из них кораблекрушение дало возможность покончить с прошлым и начать все с чистого листа. А кто-то просто хочет выжить и вернуться домой.', 28153),
(138014, 'ruRU', 'Ксенксуджу дал мне испить из Чаши грома. Благодаря ему мы скоро воссоединимся с Акундой!', '', 28153),
(138013, 'ruRU', '', 'У Кел\'вакса... много способов... расправиться с тобой...', 28153),
(138012, 'ruRU', '', 'Я принесу твой труп в дар Кел\'ваксу!', 28153),
(138009, 'ruRU', 'Давай без страшилок, Нора. Нам еще может понадобиться помощь.', 'Давай без страшилок, Нора. Нам еще может понадобиться помощь.', 28153),
(138008, 'ruRU', 'Скажи, тебе доводилось слышать легенду о Зем\'лане?', 'Скажи, тебе доводилось слышать легенду о Зем\'лане?', 28153),
(137999, 'ruRU', 'Я постою вон там. На свету... читать удобнее. Удачи!', '', 28153),
(137997, 'ruRU', '<Осмотреть рюкзак>', '<Осмотреть рюкзак>', 28153),
(137993, 'ruRU', '<Это детский рюкзак. К нему прикреплен значок \"Юный исследователь\".>', '', 28153),
(137988, 'ruRU', 'Сейчас захвачу еще одну штучку и побегу домой...', 'Сейчас захвачу еще одну штучку и побегу домой...', 28153),
(137987, 'ruRU', 'Спасибо. Побегу не оглядываясь.', 'Спасибо. Побегу не оглядываясь.', 28153),
(137986, 'ruRU', 'Я совершил ужасную ошибку.', 'Я совершила ужасную ошибку.', 28153),
(137985, 'ruRU', 'Ладно скелеты, но их питомцы... Кошмарное место!', 'Ладно скелеты, но их питомцы... Кошмарное место!', 28153),
(137984, 'ruRU', 'Спасибо тебе, $pr. Мои силы были уже на исходе.', 'Спасибо тебе, $pr. Мои силы были уже на исходе.', 28153),
(137983, 'ruRU', 'Я у тебя в долгу.', 'Я у тебя в долгу.', 28153),
(137982, 'ruRU', 'Весь мой караван перебили...', 'Весь мой караван перебили...', 28153),
(137981, 'ruRU', 'Я такое видел...', 'Я такое видела...', 28153),
(137926, 'ruRU', 'Твой друг мертв, $pr. Тут не место живым.', '', 28153),
(137925, 'ruRU', '', 'Значит, этим портом раньше правил тролль по имени Зем\'лан? Тогда это, должно быть, его тронный зал.', 28153),
(137924, 'ruRU', 'М-хм, а так хорошо все начиналось. Пойти к Торге, послушать истории... Ладно, так и быть, давайте с нами.', '', 28153),
(137913, 'ruRU', 'У меня есть превосходное лекарство от назойливых чужаков!', '', 28153),
(137912, 'ruRU', 'Этот кроха мне всегда нравился. Я имею в виду робота.', '', 28153),
(137911, 'ruRU', 'У меня был игрушечный робот. Маленький заводной человечек, которого я купил у гнома в Боралусе.', '', 28153),
(137909, 'ruRU', 'Сбор материалов для ритуала – первый шаг на пути к искуплению.', '', 28153),
(137908, 'ruRU', 'Не заставляй Ксенксуджу ждать... и помни, с ним шутки плохи.', '', 28153),
(137907, 'ruRU', '%s продолжает разглагольствовать об ответственности за свои действия еще несколько минут.', '', 28153),
(137906, 'ruRU', 'Хм... Компас, пожалуй. Он никогда меня не подводил! До тех пор, пока мы не оказались здесь. Но это, конечно, не компас виноват. Нельзя же во всем винить неодушевленный предмет...', '', 28153),
(137905, 'ruRU', 'Ну... ладно, идите с нами, только тихо! Это паломничество, а не карнавал.', '', 28153),
(137903, 'ruRU', '', 'Невероятно... но еще есть два лоа. Тортолланы совершают паломничество к Торге, лоа-черепахе, и нам стоит пойти с ними.', 28153),
(137902, 'ruRU', '', 'Погоди-ка, Бвонсамди помогает нам, а Хир\'ик УБИТ?!', 28153),
(137901, 'ruRU', 'Ой, конечно! Мою любимую коробку для завтраков. В ней всегда была вкусная еда. Мне так ее не хватает.', '', 28153),
(137900, 'ruRU', '', 'Наконец-то свобода!', 28153),
(137899, 'ruRU', 'Твою душу госпожа подчинит следующей!', '', 28153),
(137898, 'ruRU', '(Рассказать Таланджи о помощи Бвонсамди и смерти Хир\'ика.)', '(Рассказать Таланджи о помощи Бвонсамди и смерти Хир\'ика.)', 28153),
(137897, 'ruRU', 'Госпожа заберет твою душу!', '', 28153),
(137896, 'ruRU', 'Умри ради ее славы!', '', 28153),
(137895, 'ruRU', 'Я принесу госпоже твою голову!', '', 28153),
(137894, 'ruRU', '', 'Тебе нужно уходить... Я скоро изменюсь, и тебя не должно быть рядом, когда я стану такой...', 28153),
(137893, 'ruRU', 'Я Билл. Если тебе нужно что-то починить, то это ко мне.', '', 28153),
(137892, 'ruRU', '', 'Для меня уже слишком поздно... но у других надежда еще есть.', 28153),
(137891, 'ruRU', 'Привет! Тебя вынесло на берег, как и нас?$B$BЗнаю, лагерь у нас без изысков, но ты можешь оставаться здесь, сколько захочешь.', '', 28153),
(137890, 'ruRU', 'Найди в пустыне пропавших послушников. Я буду ждать тебя здесь.', '', 28153),
(137889, 'ruRU', 'Ты потерял что-нибудь ценное в кораблекрушении?', 'Ты потерял что-нибудь ценное в кораблекрушении?', 28153),
(137888, 'ruRU', 'Есть чего перекусить?', '', 28153),
(137887, 'ruRU', '', 'А вот это уже нехорошо. Спрыгивайте с повозки! Скорее!', 28153),
(137886, 'ruRU', '', 'Это воины Джакра\'зета!', 28153),
(137885, 'ruRU', '', 'Кажется, вон те тролли – не ваши друзья.', 28153),
(137869, 'ruRU', 'Тебе надо было бежать. Но теперь уже поздно! Сила Акунды будет моей!', '', 28153),
(137860, 'ruRU', '', 'Долли! Крапинка! Стойте! Там опасно!', 28153),
(137857, 'ruRU', 'Ого, $n! Тебе удалось выжить!', '', 28153),
(137851, 'ruRU', 'Во славу империи сетраков!', 'Во славу империи сетраков!', 28153),
(137810, 'ruRU', 'Ай! Кажется, я сломал ногу.', '', 28153),
(137807, 'ruRU', 'Приступим.', 'Приступим.', 28153),
(137806, 'ruRU', 'Ритуал в полном разгаре. Хир\'ик вот-вот появится. Приготовься!', '', 28153),
(137805, 'ruRU', 'Встретимся у ритуального круга.', '', 28153),
(137789, 'ruRU', 'Поосторожнее, |3-6($c).', 'Поосторожнее, |3-6($c).', 28153),
(137788, 'ruRU', '<Тело лоа удерживают магические узы.>', '', 28153),
(137787, 'ruRU', 'Добро пожаловать в мой храм, $n. Благодаря твоим свершениям тебе всегда будут здесь рады.', '', 28153),
(137785, 'ruRU', '', 'Спасибо. Ваша преданность важна для меня... и всех зандаларов.', 28153),
(137784, 'ruRU', '', 'Уверена, я смогу убедить других тортолланов помочь нам. Может, Шоак и Каджош тоже согласятся!', 28153),
(137783, 'ruRU', 'Ладно, принцесса. Мы поможем тебе биться с Кровавым богом. Только не доставай меня!', '', 28153),
(137782, 'ruRU', '', 'Позаботься об этом лоа, Лашк. А мы продолжим собирать союзников.', 28153),
(137781, 'ruRU', 'Ха! Старый хитрец... ему нужен был не вечный покой. Он хотел переродиться!', '', 28153),
(137780, 'ruRU', '', 'Что за дела?..', 28153),
(137779, 'ruRU', '', 'Не будет мне покоя, пока Г\'уун и тролли крови не сгинут навеки. Клянусь тебе в этом, Торга.', 28153),
(137778, 'ruRU', '', 'А я донесу до всех, как храбро ты сражался с прислужниками Г\'ууна.', 28153),
(137777, 'ruRU', 'Прощай, Торга. Я буду помнить твои истории... и делиться ими.', '', 28153),
(137776, 'ruRU', '', 'Твоя сила велика, но ты – ничто перед силами, которые служат мне!', 28153),
(137764, 'ruRU', '', 'Пожалуй... вернемся к святилищу.', 28153),
(137763, 'ruRU', 'Уф! Отдохнуть бы теперь.', '', 28153),
(137762, 'ruRU', '', 'Вот это да. У нас правда получилось!', 28153),
(137758, 'ruRU', '', 'Я иду за тобой. И со мной Орда. Я порублю тебя на мелкие кусочки!', 28153),
(137757, 'ruRU', '', 'Довольно! Мой народ больше не боится ни тебя, ни твоих троллей крови!', 28153),
(137755, 'ruRU', 'Это ничего... НЕ ЗНАЧИТ! Он... захватит... новое тело. Сломает... печати... Г\'уун... будет... свободен!', '', 28153),
(137754, 'ruRU', 'Прикончи его, пока он не понял, кто из нас опаснее и не занялся мной!', '', 28153),
(137753, 'ruRU', 'Отведай моих стрел, гнусное отродье!', '', 28153),
(137752, 'ruRU', 'Держи его на месте! Сложно попасть, когда цель все двигается!', '', 28153),
(137751, 'ruRU', '', 'Что ты делаешь? Стража, ко мне!', 28153),
(137750, 'ruRU', 'АAAAГХ! Вы ничто перед Г\'ууном! Страдайте и УМРИТЕ!', '', 28153),
(137749, 'ruRU', '', 'ЗА ТОРГУ!', 28153),
(137748, 'ruRU', '', 'Все вместе! ВПЕРЕД!', 28153),
(137747, 'ruRU', 'Ваши усилия... напрасны... Я недо... что? Нет. НЕТ!', '', 28153),
(137746, 'ruRU', '', 'Самонадеянность тебя погубит. Ты слаб, я легко рассею твои чары!', 28153),
(137745, 'ruRU', 'Все усилия... тщетны... Я... недосягаем.', '', 28153),
(137744, 'ruRU', '', 'Только представьте, все будут говорить о том, как мы убили вестника Г\'ууна!', 28153),
(137743, 'ruRU', 'Давно мое сердце так не пылало. За Торгу!', '', 28153),
(137742, 'ruRU', '', 'Вперед, за Зандалар и за Торгу!', 28153),
(137736, 'ruRU', '', 'О великий Хир\'ик, мы приносим тебе в жертву кровь и плоть!', 28153),
(137734, 'ruRU', 'Да, да. Мы идем!', '', 28153),
(137733, 'ruRU', '', 'За мной! Нам нужно готовиться к бою с вестником Кровавого бога.', 28153),
(137732, 'ruRU', 'Держись подальше от пауков, крошка-саурид. Я, конечно, бог секретов, но у Язмы целая армия шпионов. Ей нравится посылать лазутчиков в мои владения, чтобы они охотились на моих детей.', '', 28153),
(137731, 'ruRU', 'Я готов войти.', 'Я готова войти.', 28153),
(137730, 'ruRU', '', 'Не думала, что мне когда-нибудь доведется побывать в этих руинах. Просто удивительно!', 28153),
(137728, 'ruRU', 'Ну, и где твоя грозность? Вперед, слуга. Укуси эту крысу Нокано, который велел убивать моих детей – и снова будешь выглядеть как богатеище.', '', 28153),
(137721, 'ruRU', '', 'Это будет самая эпическая тортолланская история. О том, как мы одолели чудовище и отмстили за лоа!', 28153),
(137720, 'ruRU', 'А знаете, я думаю, что мы можем убить этого вестника Г\'ууна.', '', 28153),
(137719, 'ruRU', '', 'Поторопитесь! Нужно узнать, что еще замышляют тролли крови.', 28153),
(137718, 'ruRU', '', 'Мы здесь закончили, $n. Встретимся у Заставы Арома.', 28153),
(137716, 'ruRU', '', 'Ведьма была слишком сильна, и я оказалась в плену.', 28153),
(137715, 'ruRU', '', 'Спасибо тебе за избавление из этого гнусного голема.', 28153),
(137710, 'ruRU', '', 'Хорошо. Идем, и без лишних звуков, не то мигом окажетесь у троллей крови в лапах.', 28153),
(137709, 'ruRU', 'Конечно. Некоторые мои свитки старше тебя! Киша, загляни в мой рюкзак.', '', 28153),
(137708, 'ruRU', '', 'Нам нужно незаметно прокрасться к троллям, чтобы узнать, что они задумали. У вас найдется что-нибудь полезное?', 28153),
(137707, 'ruRU', '', 'Ход войны переломили наши ученые...', 28153),
(137706, 'ruRU', 'Кажется, я старею...', '', 28153),
(137705, 'ruRU', 'Магия крови! И кому могло прийти в голову заниматься чем-то подобным?', '', 28153),
(137704, 'ruRU', 'Я расскажу эту историю другим.', '', 28153),
(137703, 'ruRU', 'Они убили Торгу и теперь убивают нас! Что за чудовища эти тролли?', '', 28153),
(137702, 'ruRU', 'Они украли все мои свитки! Прошу, верни их.', '', 28153),
(137701, 'ruRU', 'Наконец-то удача снова мне улыбнулась!', '', 28153),
(137700, 'ruRU', '', 'Мы съедим тортолланов, и ты нам не помешаешь!', 28153),
(137699, 'ruRU', '', 'Лоа мы не едим... зато тортолланов еще как!', 28153),
(137697, 'ruRU', '', 'Качаго!', 28153),
(137696, 'ruRU', 'Не верь этому лживому торгашу никчемным мусором.\n\nЯ купил у него несколько манускриптов, и все, что там сказано, оказалось полнейшим абсурдом. \n\nЕсли он думает, что я просто так уйду и не придется возвращать мне деньги, его ждет неприятный сюрприз. В конце концов, тролли живут не так уж и долго.', '', 28153),
(137695, 'ruRU', 'Я не уйду, пока мне не вернут деньги.', '', 28153),
(137694, 'ruRU', 'В твоем рассказе нет логики. Я ничего не понимаю.', '', 28153),
(137693, 'ruRU', 'В твоих книгах говорится о местах, которых попросту не существует.', '', 28153),
(137692, 'ruRU', 'Да пребудет с вами удача, смертные. И... спасибо вам.', '', 28153),
(137691, 'ruRU', 'Ты торгуешь ложью, Телла.', '', 28153),
(137690, 'ruRU', 'Разрушьте лагеря вокруг меня. Так вы ослабите Джунго.', '', 28153),
(137689, 'ruRU', 'Принцесса. Тролли крови питают Джунго моими останками.', '', 28153),
(137678, 'ruRU', '', 'Великий мудрый Торга, скажи, как нам остановить троллей крови?', 28153),
(137677, 'ruRU', 'Я здесь. Зачем вы пришли?', '', 28153),
(137676, 'ruRU', 'Торга! Твой дух призывают. Доставай голову из панциря!', '', 28153),
(137675, 'ruRU', '', 'Гузинча!', 28153),
(137674, 'ruRU', 'Эх...', '', 28153),
(137673, 'ruRU', 'А-а-а!', '', 28153),
(137672, 'ruRU', '', 'От Кровавого бога не спрячешься!', 28153),
(137671, 'ruRU', '\"Тупой козел. Уходим, пока тебя не сожрали чудовища\".', '\"Тупой козел. Уходим, пока тебя не сожрали чудовища\".', 28153),
(137670, 'ruRU', '', 'Твоя кровь будет моим даром Г\'ууну!', 28153),
(137669, 'ruRU', '\"Привет, Марципан. Ты заблудился? Иди сюда, я провожу тебя домой. Не бойся\".', '\"Привет, Марципан. Ты заблудился? Иди сюда, я провожу тебя домой. Не бойся\".', 28153),
(137668, 'ruRU', '', 'Твои кости нам пригодятся!', 28153),
(137667, 'ruRU', '', 'Отдай свою кровь!', 28153),
(137666, 'ruRU', '', 'Свежее мясо!', 28153),
(137665, 'ruRU', '', 'Зулдазар падет!', 28153),
(137664, 'ruRU', 'Я здесь не затем, чтобы защищать торговцев или тебя. Нет, моя работа – бороться с кошмарами, которые могут напасть с севера. Тролли крови, змеелюди, Альянс и тому подобное.\n\nЕще приходится бороться со скукой, но в основном со всем остальным. А ты здесь зачем?', 'Я здесь не затем, чтобы защищать торговцев или тебя. Нет, моя работа – бороться с кошмарами, которые могут напасть с севера. Тролли крови, змеелюди, Альянс и тому подобное.\n\nЕще приходится бороться со скукой, но в основном со всем остальным. А ты здесь зачем?', 28153),
(137663, 'ruRU', '<Кажется, этот козленок с чьей-то фермы, и он заблудился.\n\nНа ошейнике написано \"Марципан\".>', '', 28153),
(137662, 'ruRU', '', 'Кровь! Кровь! Кровь!', 28153),
(137661, 'ruRU', 'Слышал, это благодаря тебе принцесса Таланджи вернулась домой. За это спасибо.\n\nНо еще говорят, с тобой вернулся и Зул. А вот за это тебя постигнет проклятие.\n\nЧто тебе нужно?', 'Слышала, это благодаря тебе принцесса Таланджи вернулась домой. За это спасибо.\n\nНо еще говорят, с тобой вернулся и Зул. А вот за это тебя постигнет проклятие.\n\nЧто тебе нужно?', 28153),
(137660, 'ruRU', 'Ты что, за торгаша меня принимаешь? Я воин! Это выше кастой, между прочим.\n\nЧего тебе надо?', 'Ты что, за торгашку меня принимаешь? Я воительница! Это выше кастой, между прочим.\n\nЧего тебе надо?', 28153),
(137659, 'ruRU', 'Хочешь что-то спросить? Если нет, иди своей дорогой.', 'Хочешь что-то спросить? Если нет, иди своей дорогой.', 28153),
(137658, 'ruRU', 'Вуду троллей крови есть? А если найду? Нет? Хорошо.\n\nТак что тебе нужно?', 'Вуду троллей крови есть? А если найду? Нет? Хорошо.\n\nТак что тебе нужно?', 28153),
(137657, 'ruRU', 'Говорят, тролли крови проникают в наше общество. Если не выйдет покорить нас силой, то они попытаются хитростью обратить нас в свою веру.\n\nВозможно, будут стараться сделать и то, и другое, но это сейчас не важно. Что тебе нужно?', 'Говорят, тролли крови проникают в наше общество. Если не выйдет покорить нас силой, то они попытаются хитростью обратить нас в свою веру.\n\nВозможно, будут стараться сделать и то, и другое, но это сейчас не важно. Что тебе нужно?', 28153),
(137656, 'ruRU', 'Мой кузен сражается в настоящей битве у Кровавых Врат. А меня отправили сюда гонять сауридов. Пф!\n\nИтак, чего тебе?', 'Мой кузен сражается в настоящей битве у Кровавых Врат. А меня отправили сюда гонять сауридов. Пф!\n\nИтак, чего тебе?', 28153),
(137655, 'ruRU', 'Бвонсамди, мы готовы. Призови дух Торги.', 'Бвонсамди, мы готовы. Призови дух Торги.', 28153),
(137654, 'ruRU', 'Отправляйся в Назмир, говорили они. Послушай истории Торги, говорили они. Будет весело, говорили они.', '', 28153),
(137652, 'ruRU', 'Этот лоа питает меня... и Г\'ууна.', '', 28153),
(137651, 'ruRU', 'Я голос Г\'ууна. Ты подчинишься... или умрешь.', '', 28153),
(137643, 'ruRU', 'Вот бы услышать их вопли! Но ты лучше держи себя в руках. Не хочу, чтобы и тебя поймали.', '', 28153),
(137642, 'ruRU', 'Наконец-то! Свобода!', '', 28153),
(137641, 'ruRU', 'А, да. Увидишь тролля по имени Сур\'джан – воткни ему мой коготь прямо в сердце! Он это заслужил!', '', 28153),
(137640, 'ruRU', 'Спасибо за все!', '', 28153),
(137639, 'ruRU', '', 'Когда детеныш Хир\'ика дарует нам способность летать и силу Кровавого бога, зандалары падут!', 28153),
(137638, 'ruRU', '$p, спасибо, что занимаешься этим. Как будешь уходить, передай, пожалуйста, Крипи, чтобы принесла воды, ладно?', '', 28153),
(137637, 'ruRU', 'Осторожно! Древни в ярости и убьют любого, кто подойдет близко.', '', 28153),
(137620, 'ruRU', 'Не важно – большой ты или маленький. Твой дух превосходит размерами все, что я видел в этих холмах.', '', 28153),
(137619, 'ruRU', '', 'Спасибо, Ручейник! Я всего лишь маленькая вульпера, но я хочу, чтобы ты научил меня всему, что знаешь сам!', 28153),
(137618, 'ruRU', 'Я вложил часть своей силы в этот тотем – возьми его. И используй мудро.', '', 28153),
(137616, 'ruRU', '', 'Не стоит благодарности, Ручейник. Мы с другом рады хоть как-то помочь тебе.', 28153),
(137615, 'ruRU', 'Я приятно удивлен. Это было мудрое решение – принести мне эссенцию.', '', 28153),
(137614, 'ruRU', '', 'Ай! Эта вода движется слишком быстро. Я не могу ее контролировать!', 28153),
(137610, 'ruRU', '', 'Ищи большие лужи воды. В Вол\'дуне их немного, так что ты легко их обнаружишь.', 28153),
(137609, 'ruRU', '', 'Если сможешь, сделай так, чтобы все сверкало. Нам нужно произвести на Ручейника впечатление.', 28153),
(137608, 'ruRU', '', 'Что бы там ни происходило, просто бери воду и уходи. Не ввязывайся ни во что.', 28153),
(137607, 'ruRU', 'Там, внизу, обитают могущественные существа, $p. Да направит мудрость твою руку, и да будет верным твой выбор.', '', 28153),
(137606, 'ruRU', 'Слава и честь тебе, $p.', '', 28153),
(137605, 'ruRU', '', 'Кем бы ты ни был, за работу всегда нужно платить.', 28153),
(137604, 'ruRU', 'Такой могущественный борец со злом, как $p, не станет убивать монстров за твои гроши, Майя. Мы делаем это ради славы!', '', 28153),
(137603, 'ruRU', '', 'Все можно исправить, Хиро, если приложить к этому достаточно усилий.', 28153),
(137602, 'ruRU', 'Ты правда считаешь, что эту повозку можно починить? Ранишу съели большую часть.', '', 28153),
(137601, 'ruRU', 'А теперь тебе пора вернуться к самому интересному: убивать и добывать для меня души!', '', 28153),
(137597, 'ruRU', 'В твоих жилах есть огонь, Таланджи. Но за мою помощь придется заплатить.', '', 28153),
(137594, 'ruRU', '', 'У нас нет времени на игры, Бвонсамди. Хочешь дух лоа? Хир\'ика недавно убили. Пойди и возьми его дух.', 28153),
(137590, 'ruRU', 'Ха... Как насчет небольшой... сделки? Принесите мне дух другого лоа, и будет вам Торга.', '', 28153),
(137588, 'ruRU', 'Дайте угадаю. Вы хотите поговорить с духом Торги.', '', 28153),
(137587, 'ruRU', 'Я готов призвать Бвонсамди.', 'Я готова призвать Бвонсамди.', 28153),
(137586, 'ruRU', 'Переговоры бесполезны. Нам придется найти другой способ их остановить. Или хотя бы переплюнуть, как ты.', '', 28153),
(137585, 'ruRU', 'Я расскажу Крипи и остальным. $pr... кто бы мог подумать, что ранишу их едят.', '', 28153),
(137584, 'ruRU', 'Ха-ха, как смешно $p перебирает ногами! Смотри не навернись!', '', 28153),
(137583, 'ruRU', 'Мунчи-Мунчи большой! Съесть маска! $pr съесть!', '', 28153),
(137582, 'ruRU', '', 'Тролли крови пожалеют, что перешли нам дорогу.', 28153),
(137581, 'ruRU', '<Потянуть факел на себя.>', '<Потянуть факел на себя.>', 28153),
(137580, 'ruRU', '<Вы осматриваете факел. Оказывается, он соединен с вмонтированным в стену механизмом.>', '', 28153),
(137579, 'ruRU', '<Это пара старых ботинок.\n\nА вы чего ждали?>', '', 28153),
(137578, 'ruRU', '<Вы поднимаете ковер, но никакого тайного прохода под ним нет.\n\nВпрочем, он отлично вписывается в дизайн комнаты.>', '', 28153),
(137577, 'ruRU', '<Как ни странно, выступающая вперед книга – вовсе не скрытый рычаг, открывающий потайную дверь.>', '', 28153),
(137576, 'ruRU', '<Якорь крепко приколочен к стене.>', '', 28153),
(137575, 'ruRU', '', 'Я знаю кто. Тролли крови. И они за это поплатятся... За мной!', 28153),
(137574, 'ruRU', '', 'Несчастный Торга! Кто мог такое с ним сделать?', 28153),
(137573, 'ruRU', 'Торга! НЕТ!', '', 28153),
(137572, 'ruRU', 'Торгу убили, словно какое-то обычное животное!', '', 28153),
(137571, 'ruRU', 'Все, о чем рассказывал Торга... все умерло вместе с ним!', '', 28153),
(137570, 'ruRU', 'Разве лоа может... умереть?', '', 28153),
(137569, 'ruRU', 'Как это могло произойти?', '', 28153),
(137568, 'ruRU', '', 'Ученые хранили записи здесь, подальше от посторонних глаз.', 28153),
(137563, 'ruRU', 'Я ищу работу.', 'Я ищу работу.', 28153),
(137561, 'ruRU', '', 'Я тебе что, экскурсовод? Я просто хочу послушать рассказы Торги.', 28153),
(137560, 'ruRU', '', 'Я лучше пойду, пока тут не собралась толпа желающих спросить дорогу.', 28153),
(137559, 'ruRU', '', 'Иди себе этой дорогой, не сворачивая, и найдешь Торгу. Он большой, не пропустишь.', 28153),
(137558, 'ruRU', '', 'Какое тебе вообще дело? Не тебе судить о том, как я паломничаю.', 28153),
(137557, 'ruRU', '\"Паломничество\"? Да ты просто стоишь на месте! Лашк говорит, ты знаешь, где искать Торгу.', '\"Паломничество\"? Да ты просто стоишь на месте! Лашк говорит, ты знаешь, где искать Торгу.', 28153),
(137556, 'ruRU', 'Лашк сказал, ты знаешь, где найти Торгу.', 'Лашк сказал, ты знаешь, где найти Торгу.', 28153),
(137555, 'ruRU', 'Чего тебе? Не видишь – я занята паломничеством!', '', 28153),
(137554, 'ruRU', 'Думаю, мы подружимся, принцесса.', '', 28153),
(137553, 'ruRU', '', 'Я не в первый раз имею дело с тортолланами... и с вашими историями. Шагайте себе и не отвлекайтесь!', 28153),
(137552, 'ruRU', 'Ладно, пойдем уже к Торге. Но только не шумите, я не хочу пропустить ни одной из его историй!', '', 28153),
(137551, 'ruRU', 'Мы не собираемся никому помогать, но вы можете просто пойти с нами.', '', 28153),
(137550, 'ruRU', 'Чего тебе?', '', 28153),
(137549, 'ruRU', 'Лучше подумай над ответом еще раз.', '', 28153),
(137548, 'ruRU', 'Я знаю только Акунду.', '', 28153),
(137547, 'ruRU', 'Я спрашиваю, как тебя зовут, а ты рассказываешь мне истории?', '', 28153),
(137546, 'ruRU', 'Смертокрыл? Что за немощное существо носит это имя?', '', 28153),
(137545, 'ruRU', 'Вы получите доступ к положительному эффекту от благословения лоа. Эта система в разработке.', 'Вы получите доступ к положительному эффекту от благословения лоа. Эта система в разработке.', 28153),
(137544, 'ruRU', 'Я этим займусь.', 'Я этим займусь.', 28153),
(137543, 'ruRU', '', 'Растения в этом ущелье борются за выживание... как и все мы.', 28153),
(137542, 'ruRU', 'Даже не знаю, как тебя благодарить. Хочу сбежать отсюда куда подальше.', 'Даже не знаю, как тебя благодарить. Хочу сбежать отсюда куда подальше.', 28153),
(137541, 'ruRU', '', 'Привет! Ты любишь огонь? А ракеты? Как насчет горящих ракет? У меня столько крутых вещиц. Руки так и чешутся показать!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137540, 'ruRU', 'Мать честная! Что это было?', 'Мать честная! Что это было?', 28153),
(137537, 'ruRU', '', 'Мы могли бы проехать через каньон, но там обитают кошмары.', 28153),
(137536, 'ruRU', '', 'Держитесь крепко. Сейчас будет трясти!', 28153),
(137535, 'ruRU', 'Неужели не было другой дороги...', '', 28153),
(137534, 'ruRU', '', 'Значит, на юг. Только знай, на горах лежит проклятие. Те, кто в них уходит, пропадают без вести.', 28153),
(137533, 'ruRU', 'Наверное, это здесь. Вижу впереди какое-то здание.', '', 28153),
(137531, 'ruRU', 'Надо двигаться на юг. Храм где-то среди тех холмов.', '', 28153),
(137530, 'ruRU', 'У меня все очень просто, но удобно, уверяю тебя.', '', 28153),
(137529, 'ruRU', 'Акунда дал нам шанс уничтожить прошлое и начать все сначала.', '', 28153),
(137528, 'ruRU', '', 'Орду нужно истребить. Зулдазар склонится перед Альянсом!', 28153),
(137526, 'ruRU', 'Здесь не так плохо. Мы – паломники. А ты, чувствую, хочешь сильно осложнить наше путешествие.', '', 28153),
(137525, 'ruRU', '', 'Что вы делаете в этом проклятом месте?', 28153),
(137523, 'ruRU', 'Ответ на этот вопрос может тебе не понравиться, $n. Но не буду скрывать: свое изгнание я заслужил.', '', 28153),
(137517, 'ruRU', 'Что ты такого сделал, что тебя изгнали сюда?', 'Что ты такого сделал, что тебя изгнали сюда?', 28153),
(137516, 'ruRU', 'Я бы с удовольствием покончил с прошлым и начал жизнь с чистого листа. Похоже, эти тролли не такие уж и чокнутые.', '', 28153),
(137515, 'ruRU', 'Я обязан Ракире жизнью. Без нее никто из изгнанников не выжил бы в песках.', '', 28153),
(137509, 'ruRU', 'Ладно, забирай! Просто отпусти меня!', '', 28153),
(137508, 'ruRU', 'Руперт, танцуй!', '', 28153),
(137505, 'ruRU', 'Я видел ту, о ком ты спрашиваешь. Она без труда прошла испытания, но надолго оставаться здесь не захотела. \n\nОна что-то искала. Расспрашивала всех, как и ты, но исчезла так же быстро, как и появилась. Отправилась на юг, и тебе туда дорога.\n\nВ этом храме небезопасно.', '', 28153),
(137504, 'ruRU', '', 'Мы все – Акунда.', 28153),
(137502, 'ruRU', 'Руперт, сюда!', '', 28153),
(137501, 'ruRU', 'Вы не видели мастера войны Ракиру?', 'Вы не видели мастера войны Ракиру?', 28153),
(137500, 'ruRU', 'Акунда дает нам силу.', 'Акунда дает нам силу.', 28153),
(137499, 'ruRU', 'Без Акунды мы ничто.', 'Без Акунды мы ничто.', 28153),
(137498, 'ruRU', 'Акунда дает нам свою силу.', 'Акунда дает нам свою силу.', 28153),
(137497, 'ruRU', 'Мы все – Акунда.', 'Все мы теперь Акунда.', 28153),
(137496, 'ruRU', 'Она не Акунда.', '', 28153),
(137495, 'ruRU', '', 'Если она не Акунда, ей сюда нельзя.', 28153),
(137494, 'ruRU', 'Только Акунде не заказан вход в храм.', '', 28153),
(137493, 'ruRU', 'Здесь нет никого с таким именем.', '', 28153),
(137492, 'ruRU', '', 'Я вижу лишь тех, кто достоин силы Акунды.', 28153),
(137491, 'ruRU', 'Какое тебе дело до тех, кто не Акунда?', '', 28153),
(137490, 'ruRU', '', 'Ракира? Какое странное имя.', 28153),
(137489, 'ruRU', 'Сладенько! Чавк! Чавк!', '', 28153),
(137488, 'ruRU', 'Говори тише... а то эти безумные сектанты нас услышат.', '', 28153),
(137487, 'ruRU', 'Ты желаешь слиться с Акундой, дитя мое? Служи мне верой и правдой, и я исполню твое желание...', '', 28153),
(137486, 'ruRU', 'Эй, ты! Не вздумай пить из той чаши.', '', 28153),
(137485, 'ruRU', 'Мунч! Мунч! Мунч!', '', 28153),
(137484, 'ruRU', 'Ты что, не слышишь? Не пей из кубка, пожалеешь!', '', 28153),
(137483, 'ruRU', 'Салджа спит в северной башне. Всего капля моего яда – и она больше никогда не проснется. Не забудь принести ключ!', '', 28153),
(137482, 'ruRU', '', 'Мы раньше не встречались? Твое лицо мне знакомо...', 28153),
(137480, 'ruRU', 'Когда я отсюда выберусь, вы мне заплатите!', '', 28153),
(137479, 'ruRU', 'Выпустите меня, иначе пожалеете, клянусь!', '', 28153),
(137478, 'ruRU', 'Выпустите меня из клетки, иначе я покажу вам, что такое кошмар!', '', 28153),
(137477, 'ruRU', 'Никогда не видел ничего подобного... Ранишу становился только голоднее. У Старого Подлесня не было шансов!', '', 28153),
(137476, 'ruRU', 'Ха! Щекотно... Ой! Больно! Хватит!', '', 28153),
(137475, 'ruRU', 'Я вам не разрешал меня поедать, мерзкие создания!', '', 28153),
(137472, 'ruRU', '<Глаза Старого Подлесня холодны и безжизненны.>', '', 28153),
(137466, 'ruRU', 'Ненасытный Ни-Ни обитает к северу отсюда. Это такой огромный жук, окруженный горой мертвечины. Просто прибей его и забери маску!', '', 28153),
(137465, 'ruRU', '', 'Кровь Торги питает нашу силу!', 28153),
(137464, 'ruRU', '', 'Кровь Торги теперь наша!', 28153),
(137463, 'ruRU', 'Ох, наконец-то перестало чесаться. Обожаю одиночество.', '', 28153),
(137462, 'ruRU', 'Не обращай на Руперта внимания. Знаток выискался... Из тебя получится отличный партнер.', '', 28153),
(137461, 'ruRU', 'Это медведь. Слушай, просто возьми и избавься от него, пока кто-нибудь из Холтонов его не заметил.', 'Это медведь. Слушай, просто возьми и избавься от него, пока кто-нибудь из Холтонов его не заметил.', 28153),
(137460, 'ruRU', 'Как это глупо. Я подобрал этого несчастного пса, когда охотился. И решил обучить его разным трюкам.', '', 28153),
(137459, 'ruRU', 'Это... это что, медведь?!', 'Это... это что, медведь?!', 28153),
(137458, 'ruRU', 'Руперт, нам принесли подарок. Давай, вырази свою благодарность! Танцуй!', '', 28153),
(137457, 'ruRU', 'Добро пожаловать, Акунда.', '', 28153),
(137456, 'ruRU', 'Добро пожаловать, Акунда.', '', 28153),
(137455, 'ruRU', 'Добро пожаловать, Акунда.', '', 28153),
(137454, 'ruRU', 'Я убил Смертокрыла. Наверняка вы слышали обо мне?', 'Я убила Смертокрыла. Наверняка вы слышали обо мне?', 28153),
(137453, 'ruRU', 'Рассказы о том, как я победил Короля-лича, до вас не доходили?', 'Рассказы о том, как я победила Короля-лича, до вас не доходили?', 28153),
(137452, 'ruRU', 'Я победил Пылающий Легион. Серьезно? Ты даже не знаешь, кто я?', 'Я победила Пылающий Легион. Серьезно? Ты даже не знаешь, кто я?', 28153),
(137451, 'ruRU', 'Прочь от меня, трусливые паразиты! Идите ешьте мясо, а деревья оставьте в покое!', '', 28153),
(137450, 'ruRU', 'Меня зовут Акунда Проворства.', 'Меня зовут Акунда Проворства.', 28153),
(137449, 'ruRU', 'Меня зовут Акунда Безмятежности.', 'Меня зовут Акунда Безмятежности.', 28153),
(137448, 'ruRU', 'Меня зовут Акунда Отваги.', 'Меня зовут Акунда Отваги.', 28153),
(137447, 'ruRU', 'Мое имя останется прежним.', 'Мое имя останется прежним.', 28153),
(137446, 'ruRU', 'Твоя прежняя жизнь не имела смысла. \n\nТвое старое имя и все твои дела должны быть забыты. \n\nПроизнеси же свое настоящее имя, чтобы его услышали все!', '', 28153),
(137444, 'ruRU', 'Многие ищут укрытия в нашем храме, но войти в него могут лишь достойные.', '', 28153),
(137438, 'ruRU', 'Ха! Вместе мы убьем это чудовище!', '', 28153),
(137437, 'ruRU', 'У Длинноклыка появились союзники, и он бросается в атаку с новыми силами.', '', 28153),
(137436, 'ruRU', 'Длинноклык торжествующе воет в знак благодарности, а затем наконец обретает вечный покой.', '', 28153),
(137435, 'ruRU', 'Благодарю тебя. Теперь я могу отдохнуть.', '', 28153),
(137434, 'ruRU', 'Приветствую тебя в моей роще, $p... по крайней мере в том, что от нее осталось.', '', 28153),
(137432, 'ruRU', 'Я не выдержу! Больше не могу!', '', 28153),
(137431, 'ruRU', 'Забудь! Может, если принести тебя в жертву, Хир\'ик дарует силу мне?', '', 28153),
(137430, 'ruRU', 'Нас больше не будут приносить в жертву! Восстаньте, братья!', '', 28153),
(137429, 'ruRU', 'Сдохните вместе со своей верховной жрицей!', '', 28153),
(137428, 'ruRU', 'Я не собираюсь жить, как животное!', '', 28153),
(137427, 'ruRU', 'Верховная жрица требует, чтобы вы совершили подношение в знак повиновения.\n[Освободить рабочего.]', 'Верховная жрица требует, чтобы вы совершили подношение в знак повиновения.\n[Освободить рабочего.]', 28153),
(137426, 'ruRU', 'Или ты принесешь нам еду, или мы съедим тебя!', '', 28153),
(137425, 'ruRU', 'В Вол\'дуне ничего не бывает легко.\n\nМне всего-то нужно немного древесины, чтобы подлатать караван.', '', 28153),
(137424, 'ruRU', '', 'Ха-ха... слишком поздно... Кровавый бог... уже здесь!', 28153),
(137423, 'ruRU', '', 'Глашатай уже готов! И ты ничего не сможешь с этим сделать!', 28153),
(137422, 'ruRU', 'Тебе это может показаться смешным, но ранишу – очень серьезное колдовство.\n\nХоть и щекотно немного.', '', 28153),
(137421, 'ruRU', 'Нас не остановить! Рабочие поднимут бунт!', '', 28153),
(137420, 'ruRU', 'Смотри в оба. Недолго вам, женщинам, оставаться у власти!', '', 28153),
(137419, 'ruRU', 'Вот увидишь, мы с братьями выберемся отсюда и сами будем править!', '', 28153),
(137418, 'ruRU', 'Снова хочешь меня наказать? Я не дрогну перед тобой!', '', 28153),
(137417, 'ruRU', 'Кровь Торги питает нашу силу!', '', 28153),
(137416, 'ruRU', 'Кровь Торги теперь наша!', '', 28153),
(137414, 'ruRU', 'Мы всем раздадим мясо лоа, и ты нас не остановишь!', '', 28153),
(137413, 'ruRU', 'Мясо лоа наше! И твое скоро будет!', '', 28153),
(137412, 'ruRU', '', 'А теперь пришла пора поохотиться на ведьм.', 28153),
(137411, 'ruRU', '', 'Орден Пылающих Углей возродился!', 28153),
(137410, 'ruRU', '', 'Древние знания помогут тебе и нашим бойцам уничтожить нечестивый ковен, что отравляет нашу землю.', 28153),
(137409, 'ruRU', '', 'Возьми эту книгу, чтобы продолжить дело ордена Пылающих Углей.', 28153),
(137408, 'ruRU', '', 'Вот оно... последнее пристанище ордена Пылающих Углей. Сколько же лет минуло с тех пор...', 28153),
(137407, 'ruRU', '', 'Идем, книга должна быть где-то здесь.', 28153),
(137406, 'ruRU', '', 'Хотя, что я говорю... Потребуется куда больше, чем несколько камней, чтобы свалить тебя с ног.', 28153),
(137405, 'ruRU', '', 'Никогда раньше не видела таких огромных. Ты в порядке?', 28153),
(137404, 'ruRU', '', 'Хир\'ик... отомстит... за меня...', 28153),
(137403, 'ruRU', '', 'Моя душа принадлежит Г\'ууну!', 28153),
(137402, 'ruRU', '<Помочь Генри Брейквотеру и отдать преимущество в битве ему.>', '<Помочь Генри Брейквотеру и отдать преимущество в битве ему.>', 28153),
(137401, 'ruRU', '', 'Мясо лоа наше!', 28153),
(137400, 'ruRU', '', '$C! Сзади!', 28153),
(137399, 'ruRU', '', 'Слава... Хир\'ику...', 28153),
(137398, 'ruRU', '', 'Мы берем мясо лоа, мы едим мясо лоа!', 28153),
(137397, 'ruRU', '', 'Погоди... что-то не так.', 28153),
(137396, 'ruRU', '', 'Хм-м... Путь завален обломками. Ты сможешь расчистить его?', 28153),
(137395, 'ruRU', '', 'Вооружившись этим знанием, наши люди стали вытеснять друстов обратно в горы.', 28153),
(137394, 'ruRU', '', 'Вместе они написали трактат, тактическое пособие о том, как вести войну против варваров.', 28153),
(137393, 'ruRU', '', 'Как я говорила, ход войны изменился, когда наши ученые нашли изъяны в магии друстов.', 28153),
(137392, 'ruRU', '', 'Спасибо, |3-6($c). Я уж было подумала о смерти.', 28153),
(137391, 'ruRU', '', 'Стой!.. Берегись!', 28153),
(137390, 'ruRU', '', 'Уэйкресты всегда умели за себя постоять, но магия друстов была слишком сильна...', 28153),
(137389, 'ruRU', '', 'Мои предки сражались с похожими каменными созданиями в той войне.', 28153),
(137388, 'ruRU', '', 'Прости, |3-6($c). Должно быть, духи древних друстов реагируют на магию ковена. Нам нужно быть осторожнее.', 28153),
(137387, 'ruRU', '', 'Берегись!', 28153),
(137386, 'ruRU', '', 'Что?.. Что это было?', 28153),
(137385, 'ruRU', '', 'Так продолжалось долгие годы, прежде чем наши предки решили, что больше с этим мириться нельзя.', 28153),
(137384, 'ruRU', '', 'Друствар был землей их предков. Отсюда они устраивали набеги на наши поселения.', 28153),
(137383, 'ruRU', '', 'Давным-давно, когда наши предки заселяли Кул-Тирас, они столкнулись с воинственным племенем варваров, называвших себя друстами.', 28153),
(137382, 'ruRU', '', 'Смотри! Проход открывается!', 28153),
(137381, 'ruRU', '', 'Нужно лишь отыскать вход!', 28153),
(137380, 'ruRU', '', 'Он хранит секрет тех дней, когда Уэйкресты впервые ступили на эту землю.', 28153),
(137379, 'ruRU', '', 'Поверить не могу! Я слышала столько историй об этом домике от отца.', 28153),
(137378, 'ruRU', '', 'Скачи к Заставе Арома, Белла!', 28153),
(137377, 'ruRU', '', 'Возьми с собой Беллу – она поможет тебе довезти найденные припасы.', 28153),
(137376, 'ruRU', '<Помочь Длинноклыку и отдать преимущество в битве ему.>', '<Помочь Длинноклыку и отдать преимущество в битве ему.>', 28153),
(137375, 'ruRU', '<Дух охотника Генри Брейквотера занят вечной битвой с духом волка по имени Длинноклык.\n\nОн так увлечен, что не замечает вас. Ни одна сторона не уступает другой по силе. Эта бесконечная борьба равных не прекращается даже после смерти.>', '', 28153),
(137374, 'ruRU', '<Дух могучего волка Длинноклыка даже в посмертии продолжает сражаться.\n\nБой между ним и Генри Брейквотером никогда не закончится.>', '', 28153),
(137296, 'ruRU', '', 'Больше крови для Хир\'ика!', 28153),
(137295, 'ruRU', '', 'Я заберу твою голову!', 28153),
(137294, 'ruRU', '', 'Ты умрешь здесь!', 28153),
(137292, 'ruRU', '', 'Хир\'ик выпьет всю твою кровь!', 28153),
(137290, 'ruRU', '', 'Я скормлю тебя своему нетопырю!', 28153),
(137289, 'ruRU', '', 'Я скормлю тебя Хир\'ику!', 28153),
(137287, 'ruRU', '', 'Кровавый бог говорил, что ты придешь!', 28153),
(137284, 'ruRU', 'Вы пытаетесь построить цитадель?! Ха-ха! Вот умора!', '', 28153),
(137282, 'ruRU', 'Готовьте артиллерию! Сровняем их базу с землей.', '', 28153),
(137281, 'ruRU', 'Так, кто тут у нас? Неужели Орда решила показать свою мерзкую рожу?', '', 28153),
(137280, 'ruRU', 'Я слабею с каждой минутой... Помоги мне... пока еще не поздно.', '', 28153),
(137279, 'ruRU', 'У тебя прирожденный талант!', '', 28153),
(137278, 'ruRU', 'А теперь мой любимый элемент – прыжки! Покажи, как ты умеешь преодолевать препятствия. Чем больше прыжков, тем лучше впечатление!', '', 28153),
(137277, 'ruRU', 'Сорвиголовы уже научили тебя обращаться с боласом! Попрактикуйся в метании боласа в дирижабли на скаку! Их мало, но за них дают много очков!', '', 28153),
(137276, 'ruRU', 'Кул-тирасские наездники — умелые бойцы. Покажи, как ты умеешь обращаться с гарпуном, на гноллах!', '', 28153),
(137275, 'ruRU', 'А может, и то и другое? Человекомедведь... или медведочел?', '', 28153),
(137274, 'ruRU', 'Опять раны, как от медведя. Бандит с ручным медведем?..', '', 28153),
(137271, 'ruRU', 'Или не медведь... Похоже ее убили бандиты, или что-то в этом духе...', '', 28153),
(137270, 'ruRU', 'Какие необычные раны. Как будто медведь напал. Что скажешь, похоже на медведя?', '', 28153),
(137269, 'ruRU', 'Все превратится... в пустыню... даже Назмир!', '', 28153),
(137268, 'ruRU', 'Я завоюю Назмир во славу империи сетраков!', '', 28153),
(137267, 'ruRU', 'Я пережил встречу с троллями крови, и что я получил? Пф!', 'Я пережила встречу с троллями крови, и что я получила? Пф!', 28153),
(137266, 'ruRU', 'Пф! Торги больше нет, и никаких историй я так и не услышал.', 'Пф! Торги больше нет, и никаких историй я так и не услышала.', 28153),
(137265, 'ruRU', 'Это еще что? Мне не нравится это место... Я здесь не останусь!', 'Это еще что? Мне не нравится это место... Я здесь не останусь!', 28153),
(137264, 'ruRU', 'Торга... умер?! Что вообще происходит?', 'Торга... умер?! Что вообще происходит?', 28153),
(137263, 'ruRU', '', 'Какое коварство! Я отрублю тебе голову!', 28153),
(137262, 'ruRU', '', 'Ну и куда его понесло? Теперь придется доплачивать егерю...', 28153),
(137261, 'ruRU', 'Прекрасно! Охота на лосей куда лучше капканов на медведей!', '', 28153),
(137260, 'ruRU', '', 'К западу отсюда есть небольшой лагерь, которому требуется...', 28153),
(137259, 'ruRU', 'Ха-ха! Молодец! Так держать!', '', 28153),
(137258, 'ruRU', 'Начали!', '', 28153),
(137257, 'ruRU', 'Джунджи постоянно влипает в неприятности. Если ящеры найдут его до тебя, ему придется туго!', '', 28153),
(137256, 'ruRU', 'Внимание...', '', 28153),
(137255, 'ruRU', 'Пусть на вкус они и не очень, зато сытные.', '', 28153),
(137254, 'ruRU', 'Рыкозуб мертв, и наши пропавшие альпаки вернулись. Осталась всего одна проблема: нас убьет Моджамбо...', '', 28153),
(137253, 'ruRU', 'Альпаки в пустыне долго не протянут. Их нужно разыскать!', '', 28153),
(137252, 'ruRU', 'Наше стадо альпак исчезло. Нужно найти их, пока еще не поздно!', '', 28153),
(137251, 'ruRU', 'Пустыня есть пустыня, но здесь можно найти еду, если знать, где искать!', '', 28153),
(137250, 'ruRU', 'Без еды и припасов мы долго не протянем...', '', 28153),
(137249, 'ruRU', 'Пока сетраки безнаказанно опустошают эти земли, мира ждать бесполезно.', '', 28153),
(137248, 'ruRU', 'Мы продолжим, когда ты как следует подготовишься.', '', 28153),
(137247, 'ruRU', '$n захватывает Новоземье!', '$n захватывает Новоземье!', 28153),
(137246, 'ruRU', 'Альянс захватил Новоземье.', 'Альянс захватил Новоземье.', 28153),
(137245, 'ruRU', 'Альянс захватил Кряж лесорубов.', 'Альянс захватил Кряж лесорубов.', 28153),
(137244, 'ruRU', '', 'Умоляю... У меня... почти не осталось времени.', 28153),
(137243, 'ruRU', '<В боку у бедолаги зияет большая рваная рана, окаймленная зеленоватой пеной.>', '', 28153),
(137242, 'ruRU', '', 'Я так волнуюсь за племянницу!', 28153),
(137241, 'ruRU', '', 'Какое счастье, что с тобой ничего не случилось, $p! И Долли и Крапинка тоже целы.', 28153),
(137240, 'ruRU', '', 'Долли и Крапинка уже проголодались. Тянуть повозку с троллями – нелегкий труд!', 28153),
(137239, 'ruRU', '', 'Долли и Крапинка – сильные и надежные. Они довезут нас куда угодно.', 28153),
(137235, 'ruRU', 'Я принимаю условия.', 'Я принимаю условия.', 28153),
(137234, 'ruRU', 'Медяк кладет сокола в свою сумку.', '', 28153),
(137233, 'ruRU', 'Вижу, в моем логове гость. Причем |3-6($c)! Скажи, |3-6($r), ты здесь затем, чтобы заключить сделку?\n\nКогда-то я разрешил моим последователям поклоняться также и другим лоа. Но если ты хочешь заслужить мое благословение, тебе нужно будет показать мою силу всему Зулдазару.\n\nЯ благословлю тебя, если ты вернешься на ступени Дазар\'алора и возведешь в мою честь алтарь, достойный богов.\n\nСделай это, и я приму тебя в свою стаю. Таковы мои условия.', '', 28153),
(137226, 'ruRU', 'Отпусти меня.', 'Отпусти меня.', 28153),
(137223, 'ruRU', 'Привет тебе, богатеище. Что сегодня привело тебя в святилище собирателей?', '', 28153),
(137212, 'ruRU', 'День 1. К обеду мы должны добраться до троггов Северных пещер. До ужина мы точно что-нибудь найдем! Вперед, навстречу приключениям!', '', 28153),
(137175, 'ruRU', '$n захватывает Северный перекресток!', '$n захватывает Северный перекресток!', 28153),
(137174, 'ruRU', 'Альянс захватил Северный перекресток!', 'Альянс захватил Северный перекресток!', 28153),
(137162, 'ruRU', 'А! Еще одна душа для Г\'ууна!', '', 28153),
(137161, 'ruRU', 'Тупой саурид, сколько можно умирать?', '', 28153),
(137157, 'ruRU', 'Хе-хе-хе!', '', 28153),
(137156, 'ruRU', '$n захватывает Гнездо!', '$n захватывает Гнездо!', 28153),
(137155, 'ruRU', 'Альянс захватил Гнездо!', 'Альянс захватил Гнездо!', 28153),
(137154, 'ruRU', 'Какое странное ощущение!', '', 28153),
(137153, 'ruRU', 'Йома! Ты это видишь? Я еду!', '', 28153),
(137152, 'ruRU', 'Альянс захватил Круг стихий!', 'Альянс захватил Круг стихий!', 28153),
(137151, 'ruRU', '$n захватывает Круг стихий!', '$n захватывает Круг стихий!', 28153),
(137148, 'ruRU', 'Вперед!', '', 28153),
(137144, 'ruRU', 'Нет! Слишком быстро! Сейчас упаду!', '', 28153),
(137143, 'ruRU', 'Думаю, я справлюсь...', '', 28153),
(137142, 'ruRU', 'А-а-а!', '', 28153),
(137141, 'ruRU', 'Р-р-рах! Разорвать! Убить!', '', 28153),
(137140, 'ruRU', 'Убить! Убить! Убить!', '', 28153),
(137139, 'ruRU', 'Рр-р!.. Крушить!', '', 28153),
(137138, 'ruRU', 'Раздавлю!', '', 28153),
(137137, 'ruRU', 'Рр-р!', '', 28153),
(137135, 'ruRU', 'Моя... тебя... убивай...', '', 28153),
(137134, 'ruRU', 'Я... рухаю...', '', 28153),
(137133, 'ruRU', 'Я... сломайся...', '', 28153),
(137132, 'ruRU', 'Сейчас моя тебя тоже есть!', '', 28153),
(137131, 'ruRU', 'Не трогать свежее мясо!', '', 28153),
(137130, 'ruRU', 'Земля тебя поломай!', '', 28153),
(137129, 'ruRU', 'Моя тебя есть!', '', 28153),
(137128, 'ruRU', 'Ладно, Йома! Отведи меня на тренировочную площадку. Раз уж мы решили освоить верховую езду...', '', 28153),
(137127, 'ruRU', 'Давай, папа! Держись крепче!', '', 28153),
(137122, 'ruRU', 'Мое...', '', 28153),
(137121, 'ruRU', 'Я... убить... тебя...', '', 28153),
(137120, 'ruRU', 'Моя... твою ломать...', '', 28153),
(137119, 'ruRU', 'Я тебя сломаю!', '', 28153),
(137118, 'ruRU', 'Я тебя сожру!', '', 28153),
(137117, 'ruRU', 'Убить!', '', 28153),
(137116, 'ruRU', 'Это сокровище – мое!', '', 28153),
(137113, 'ruRU', 'Харрисон Джонс – мой герой! Но Бранн Бронзобород тоже ничего.', '', 28153),
(137110, 'ruRU', 'Ура! Есть!', '', 28153),
(137109, 'ruRU', 'Ой! Вам попался злобный краб!', '', 28153),
(137108, 'ruRU', 'Леска порвалась!', '', 28153),
(137107, 'ruRU', 'Поз\'га!', '', 28153),
(137106, 'ruRU', 'А теперь Поз\'га тебя съест!', '', 28153),
(137105, 'ruRU', 'Когда приходит Поз\'га, мы бежим!', '', 28153),
(137104, 'ruRU', '', 'Я сама скормлю тебя Хир\'ику!', 28153),
(137101, 'ruRU', 'Как считаешь, здесь есть артефакты титанов? Я думаю, что есть. Именно потому тут все кишит троггами. И я найду все, что оставили титаны.', '', 28153),
(137100, 'ruRU', 'Эти детишки будут оставлены без сладкого пожизненно!', '', 28153),
(137099, 'ruRU', 'Мой внук вечно попадает в переделки, но тут явно что-то серьезное.', '', 28153),
(137098, 'ruRU', 'Потрошение', 'Потрошение', 28153),
(137097, 'ruRU', 'Ладно, ладно... Так и быть... Ты же мне поможешь?', '', 28153),
(137096, 'ruRU', 'Вперед! Бежим отсюда!', '', 28153),
(137095, 'ruRU', 'Папа, хватит увиливать! Давай уже взбирайся на лошадь!', '', 28153),
(137094, 'ruRU', 'Сынок, ты что! Только посмотри на ее хищный взгляд. Небось, мечтает мной полакомиться! Нет!', '', 28153),
(137093, 'ruRU', 'А как тебе эта? По-моему, очень милая!', '', 28153),
(137092, 'ruRU', 'Нет, сынок. Этот тоже не подойдет. Слишком резвый! Ты посмотри, как он гарцует! Мои старые кости такого не выдержат!', '', 28153),
(137091, 'ruRU', 'А вот этот ничего!', '', 28153),
(137090, 'ruRU', 'Нет, Йома. Эта слишком... нервная... Да-да, нервная! Она будет шарахаться от любого резкого движения.', '', 28153),
(137089, 'ruRU', 'Пап, может эту?', '', 28153),
(137088, 'ruRU', 'Ну ладно, хватит оттягивать этот момент. Пора подобрать идеальную лошадь!', '', 28153),
(137087, 'ruRU', 'Пока мы не начали... дайте мне минутку... собраться с духом...', '', 28153),
(137086, 'ruRU', 'Мы порежем вас на кусочки, и будет еще больше еды!', '', 28153),
(137085, 'ruRU', 'Хозяева будут рады отведать вашей плоти!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137084, 'ruRU', 'Мой папа все время говорит о лошадях! Он хочет научиться ездить верхом, но, кажется, боится.$b$bЯ знаю, как ему помочь!', '', 28153),
(137083, 'ruRU', 'Вероятно, это и искали сетраки!', '', 28153),
(137082, 'ruRU', 'Значит, гравировки на рунных камнях не лгали... сфера существует!', '', 28153),
(137080, 'ruRU', '', 'Твоя магия меня не проведет!', 28153),
(137079, 'ruRU', '', 'Зелья еще не готовы, приходи позже!', 28153),
(137078, 'ruRU', '', 'Говори. Почему ты тревожишь меня во время медитации?', 28153),
(137077, 'ruRU', 'Тун\'ка... Пагубный...', '', 28153),
(137076, 'ruRU', 'Тун\'ка... Пагубный...', '', 28153),
(137075, 'ruRU', '', 'Спасибо тебе за помощь. Не забывай чистить штаны от соли.', 28153),
(137074, 'ruRU', 'Приготовься! Этот вечер скоро станет еще интереснее!', '', 28153),
(137073, 'ruRU', 'Ты заплатишь за воровство!', 'Ты заплатишь за воровство!', 28153),
(137071, 'ruRU', 'Ты ничто перед империей!', 'Ты ничто перед империей!', 28153),
(137068, 'ruRU', 'Сила руин принадлежит нам!', 'Сила руин принадлежит нам!', 28153),
(137067, 'ruRU', 'Сила руин будет нашей!', 'Сила руин будет нашей!', 28153),
(137066, 'ruRU', '', 'Не каждый день удается заручиться помощью элементаля воды.', 28153),
(137065, 'ruRU', '', 'Твоя преданность впечатляет. Поставь статую в мою честь у ступеней Дазар\'алора, чтобы местные тролли помнили обо мне.', 28153),
(137063, 'ruRU', '', 'Ха-ха! Ну не в прямом же смысле.', 28153),
(137062, 'ruRU', '<Активировать колосса.>', '<Активировать колосса.>', 28153),
(137061, 'ruRU', 'Когда вы приближаетесь к древнему голему, он начинает светиться.', 'Когда вы приближаетесь к древнему голему, он начинает светиться.', 28153),
(137056, 'ruRU', 'Даже не мечтай подчинить меня своей воле еще раз, шаман. Я тебя уничтожу!', '', 28153),
(137055, 'ruRU', 'Эй! Не похоже, что ты из этих спесивых аристократов. Хочешь выпить с нами? Лорд Норвингтон пригласил нас сюда повеселиться – этим мы и занимаемся!', '', 28153),
(137054, 'ruRU', 'Тебе здесь делать нечего. Это мост троллей!', '', 28153),
(137053, 'ruRU', 'Только посмотри на этих великолепных скакунов. Мы пересекли континент, чтобы попасть на этот фестиваль. Я хочу узнать побольше об этих удивительных животных.$b$bИх благородство и сила вселяют в мое сердце благоговейный трепет.', '', 28153),
(137052, 'ruRU', 'Тун\'ка Пагубный поглотит эту долину!', '', 28153),
(137051, 'ruRU', 'Орда вернула Ар\'горок!', 'Орда вернула Ар\'горок!', 28153),
(137050, 'ruRU', '', 'В моем доме объявилась новая сила. Подойди, $p из Орды, я хочу увидеть, кто же ты на самом деле.$b$bТы ведь защищаешь свой народ, $r-|3-6($c)?$b$bВедун сказал, что ты ищешь моего благословения, но сперва я кое-что у тебя попрошу, как прошу у всех, кто чего-то хочет от меня.$b$BДокажи мне свою веру... просто прыгни с утеса.', 28153),
(137049, 'ruRU', 'Пойдем, пришла пора покончить с этой сектой.', '', 28153),
(137048, 'ruRU', 'Ты серьезно? Надо принимать его предложение!', '', 28153),
(137047, 'ruRU', 'Ха! Я прошел через многое – тебе не победить.', '', 28153),
(137046, 'ruRU', 'Ваш народ обречен! Примите мою сторону... и обретете спасение.', '', 28153),
(137045, 'ruRU', 'Решено.', 'Решено.', 28153),
(137041, 'ruRU', 'А, это ты! Добро пожаловать! Вот еда и напитки, ни в чем себе не отказывай. Если тебе понадобится что-то еще – буду рад помочь.', '', 28153),
(137040, 'ruRU', 'Здесь мы ухаживаем за лошадьми. О них заботятся как помощники смотрителя стойл, так и сами наездники.', '', 28153),
(137039, 'ruRU', '', 'Чего ты хочешь от лоа небес?', 28153),
(137038, 'ruRU', '', 'Мы с Марком где-нибудь спрячемся!', 28153),
(137037, 'ruRU', '', 'Спасибо! У меня почти закончились камни.', 28153),
(137036, 'ruRU', 'Умри!', '', 28153),
(137035, 'ruRU', '', 'Меня наполняет сила Зардракса!', 28153),
(137034, 'ruRU', '', 'Мощь Зардракса сокрушит тебя!', 28153),
(137033, 'ruRU', 'Я вернусь в Зул\'джан. Надо проверить, не заразился ли еще кто безумной идеей примкнуть к троллям крови.', '', 28153),
(137032, 'ruRU', 'Жаль, что Каль\'дран был слишком слаб и не понимал, что мы победим, да?', '', 28153),
(137031, 'ruRU', 'Удачи тебе, $n. Убей Зардракса, пока кто-нибудь еще не поддался его влиянию.', '', 28153),
(137030, 'ruRU', '$n все сделает как надо – избавит нас от этой проклинательницы.', '', 28153),
(137029, 'ruRU', 'Не знаю, Да\'джул... $n не сможет это остановить! Мы все умрем!', '', 28153),
(137028, 'ruRU', '', 'Пойду найду Марка! Увидимся!', 28153),
(137027, 'ruRU', '', 'О, спасибо! Здесь было довольно неудобно.', 28153),
(137026, 'ruRU', '', 'Это для меня слишком. Я уношу отсюда ноги!', 28153),
(137025, 'ruRU', 'Альянс штурмует шахту!', '', 28153),
(137024, 'ruRU', '$n штурмует золотую шахту!', '', 28153),
(137023, 'ruRU', 'Я сейчас же начну наполнять озеро водой.', '', 28153),
(137022, 'ruRU', 'Я чувствую мощь в этой эссенции. Должно быть, без Ручейника тут не обошлось.', '', 28153),
(137021, 'ruRU', 'Я найду Марка и буду ждать вместе с ним. Увидимся там!', '', 28153),
(137020, 'ruRU', 'О, спасибо! Кто бы мог подумать, что трогги умеют колдовать?', '', 28153),
(137019, 'ruRU', 'Я возвращаюсь к Ручейнику.', '', 28153),
(137018, 'ruRU', 'Я возродился.', '', 28153),
(137017, 'ruRU', 'Я вырос на рассказах о диких троллях крови. Но это куда хуже всего, что о них говорят.', '', 28153),
(137016, 'ruRU', 'Каль\'дран! $n, останови его. Даже если придется его убить.', '', 28153),
(137015, 'ruRU', 'Мы все обречены! Зардракс спасет нас, и если ты захочешь мне помешать, тебе конец!', '', 28153),
(137013, 'ruRU', 'Не могу... сдержать...', '', 28153),
(137012, 'ruRU', 'Добро пожаловать на конный фестиваль Норвингтонов! Мы еще готовимся к открытию, но тебе обязательно нужно поучаствовать. Отказа я не приму!', '', 28153),
(137011, 'ruRU', 'Уходите! Вам здесь больше нечего делать!', '', 28153),
(137010, 'ruRU', 'Давай, |3-6($c)!', '', 28153),
(137009, 'ruRU', 'Не верьте его пустой лжи, иначе обречете себя на гибель!', '', 28153),
(137008, 'ruRU', 'Лорда Отумвейла больше нет! Жажда могущества сгубила его!', '', 28153),
(137007, 'ruRU', 'Я видел... лик Г\'ууна... надежды нет... нет...', '', 28153),
(137006, 'ruRU', 'Надежды нет! Почему ты не хочешь присоединиться к Зардраксу?', '', 28153),
(137005, 'ruRU', 'Еще раз спасибо тебе, |3-6($c). Если бы не ты, они бы...', '', 28153),
(137003, 'ruRU', 'Ты обрекаешь нашу землю... на погибель...', '', 28153),
(137002, 'ruRU', 'Не вмешивайся в нашу работу, если не хочешь, чтобы тебя тоже принесли в жертву!', '', 28153),
(137001, 'ruRU', 'Они чокнутые! Помоги мне, |3-6($c)!', '', 28153),
(137000, 'ruRU', 'Нужно умилостивить Плетеного человека, не то наши несчастья продолжатся!', '', 28153),
(136999, 'ruRU', 'Да успокойся ты! Твоя смерть послужит высшей цели!', '', 28153),
(136998, 'ruRU', 'Так нельзя! Это убийство! Убийство!', '', 28153),
(136997, 'ruRU', 'Кажется, их стало поменьше. Думаю, я смогу вернуться сам.', '', 28153),
(136996, 'ruRU', 'Спасибо тебе. Я думал, пчелы меня отсюда живым не выпустят!', '', 28153),
(136995, 'ruRU', 'Они целятся мне в глаза! Мои глаза!', '', 28153),
(136994, 'ruRU', 'Только не пчелы! Н-е-ет!', '', 28153),
(136993, 'ruRU', '$C! Рад видеть дружелюбно... эй, а это еще что такое?', '', 28153),
(136992, 'ruRU', 'Слава Плетеному человеку!', 'Слава Плетеному человеку!', 28153),
(136991, 'ruRU', 'Смотри, $n! Это Магуу, мой новый скакун. Правда, он великолепен?$b$bЯ скучаю по Крутышу – такой славный был малый. Просто иногда он волновался! Я хочу, чтобы с Магуу у нас была особая связь, чтобы я мог точно определить, когда он взволнован.$b$bИ хочу стать первоклассным наездником – я продолжу занятия с Мелиссой, и когда-нибудь мы с Магуу станем отличной командой. Мы будем лучшими из лучших!', '', 28153),
(136990, 'ruRU', 'Соберитесь у Плетеного человека, послушники. Его благосклонность защитит нас от проклятий, которые поразили нашу землю.', '', 28153),
(136989, 'ruRU', '', 'Не знаю, как тебя и благодарить за спасение Эдди! Он хороший мальчик, а со временем станет и хорошим наездником.$b$bТолько на какое-то время придется ограничиться уроками в поместье.', 28153),
(136988, 'ruRU', 'Так... слаб...', '', 28153),
(136987, 'ruRU', 'Слушаюсь, ма\'да. Уже иду!', '', 28153),
(136986, 'ruRU', 'Меня прислал Кеджабу.', 'Меня прислал Кеджабу.', 28153),
(136985, 'ruRU', 'Но если последуешь за мной, то получишь такую силу, что тебе и не снилась!', '', 28153),
(136984, 'ruRU', 'Если будешь сопротивляться, наша армия тебя раздавит.', '', 28153),
(136983, 'ruRU', 'У тебя нет выбора. Зулдазар обречен. Г\'уун обретет свободу!', '', 28153),
(136982, 'ruRU', 'Ты выживешь, если будешь мне служить. Таково слово Г\'ууна.', '', 28153),
(136981, 'ruRU', 'Г\'уун поглотит все. Надежды нет.', '', 28153),
(136980, 'ruRU', 'Ха-ха... Ты сильнее многих. Но все равно все падут перед мощью Г\'ууна. Мое предложение остается в силе, подумайте над ним...', '', 28153),
(136979, 'ruRU', 'П-погоди, может быть, нам лучше присоединиться к Зардраксу! А то как мы все это остановим?', '', 28153),
(136978, 'ruRU', '$n ни за что не согласится! Покажи этому личу, что ты думаешь о его \"предложении\"!', '', 28153),
(136977, 'ruRU', 'Служи мне, и твоя жизнь будет спасена. Я дам тебе частичку силы Г\'ууна.', '', 28153),
(136976, 'ruRU', 'Зулдазар падет перед троллями крови и Г\'ууном. Но тебе не обязательно разделять его участь.', '', 28153),
(136975, 'ruRU', 'Ладно, лич, что ты предлагаешь?', 'Ладно, лич, что ты предлагаешь?', 28153),
(136974, 'ruRU', 'Следуй за мной, и гибель Зулдазара не коснется тебя!', '', 28153),
(136973, 'ruRU', 'Мы обречены! Как это можно остановить?', '', 28153),
(136972, 'ruRU', 'Сколько вообще у этих троллей крови источников силы?', '', 28153),
(136969, 'ruRU', '', 'Чудесно! Разумный выбор. Залезай, поедем к твоему новому покровителю.', 28153),
(136968, 'ruRU', 'Ха, я не сомневался, что ты сделаешь верный выбор. Давай-ка я отвезу тебя к Па\'ку.', '', 28153),
(136967, 'ruRU', 'Я хочу выбрать другого лоа.', 'Я хочу выбрать другого лоа.', 28153),
(136966, 'ruRU', 'Не-е-ет! Мерзкая ордынская погань! Я вырву дух из твоего тела!', '', 28153),
(136965, 'ruRU', 'Не останавливайтесь! Только не останавливайтесь!', '', 28153),
(136964, 'ruRU', 'Еще... больше крови! Дайте мне всю кровь!', '', 28153),
(136963, 'ruRU', 'Еще! Дайте мне еще!', '', 28153),
(136962, 'ruRU', 'Да-а... Да-а... ДА-А!!!', '', 28153),
(136961, 'ruRU', '', 'Нельзя было не опаздывать? Если мой летун от этого умрет, я повешу твою голову себе на стену!', 28153),
(136960, 'ruRU', 'Ты – самый неожиданный союзник в этом бою.', '', 28153),
(136959, 'ruRU', 'Я... думаю, это справедливо.', '', 28153),
(136958, 'ruRU', '', 'Так, Эдди. Пока будем проводить уроки в поместье.', 28153),
(136957, 'ruRU', '', 'Не время для лишних чувств, воевода.', 28153),
(136956, 'ruRU', 'Вождь, должен же быть другой способ!', '', 28153),
(136954, 'ruRU', '', 'Раал, бестолочь, ты куда вообще смотришь?! У нас тут кровавый ритуал прямо на вершине храма!', 28153),
(136953, 'ruRU', 'Последняя преграда... падет... Г\'уун... освободится!', '', 28153),
(136952, 'ruRU', 'Нет... моя связь с Г\'ууном... слабеет?', '', 28153),
(136951, 'ruRU', 'Я распространяю мощь Г\'ууна! Ты меня не остановишь!', '', 28153),
(136950, 'ruRU', 'Ты не понимаешь! Во мне сила Г\'ууна! Тебе не победить!', '', 28153),
(136949, 'ruRU', 'Самоуверенности тебе не занимать, $p. Подойди, нам надо поговорить.', '', 28153),
(136948, 'ruRU', '', 'Ха... Зардракса ничто не остановит... его сила... поможет нам уничтожить... Зулдазар...', 28153),
(136947, 'ruRU', '', 'С силой Зардракса и Г\'ууна мы станем непобедимыми!', 28153),
(136945, 'ruRU', 'Спасибо за помощь, $c. Теперь я тебе доверяю и помогу в твоем деле.', '', 28153),
(136944, 'ruRU', '', 'Кажется, он все же реагирует.', 28153),
(136943, 'ruRU', 'Он пошевелился! А, нет... постой... это был просто ветер?', '', 28153),
(136942, 'ruRU', 'Дело сделано. Прими наши подношения, Плетеный человек, и даруй нам свое благословение!', '', 28153),
(136941, 'ruRU', 'Кости? Отлично! Похоже, он их просто обожает.', '', 28153),
(136940, 'ruRU', 'Ах да, внутренности! Уверен, они нам пригодятся... для чего-нибудь.', '', 28153),
(136939, 'ruRU', 'Прутья? Самый простой выбор, но при этом все равно верный.', '', 28153),
(136938, 'ruRU', '', 'Нет, нет, нет! Это приправы, а не ритуальные травы! Ты что, их не различаешь?', 28153),
(136937, 'ruRU', '', 'Зачем ты тащишь сюда зерно? Мы же не чучело набиваем!', 28153),
(136936, 'ruRU', 'О, свитки... Возможно, они смогут пробудить плетеного человека, но вот только... их никто не может прочесть.', '', 28153),
(136935, 'ruRU', 'Фрукты?! Серьезно? Ты ведь шутишь, правда?', '', 28153),
(136934, 'ruRU', 'Наконец-то. Теперь Сильвана ответит за свои преступления. Герои, за мной.', '', 28153),
(136929, 'ruRU', '<Хиро непринужденно ударяет по бубну, который висит у него на бедре, и подмигивает вам.>', '', 28153),
(136927, 'ruRU', 'Вряд ли мы снова увидимся, $n. Спасибо.', '', 28153),
(136925, 'ruRU', '', 'Это еще не худшее, что приходило к нам из Вол\'дуна. Мы справимся.', 28153),
(136919, 'ruRU', 'Путь расчищен? Думаю, я смогу добраться до Мелиссы. Спасибо тебе за спасение!', '', 28153),
(136918, 'ruRU', 'Уже... Уже правда можно выходить? Трогги ужасно страшные!', '', 28153),
(136917, 'ruRU', '$n захватывает Кряж лесорубов!', '$n захватывает Кряж лесорубов!', 28153),
(136916, 'ruRU', 'Оставлю тебя с Лоти. Сообщи ей, что корни всех бед могут крыться в самом Занчуле.', '', 28153),
(136915, 'ruRU', 'Хм-м, что-то... изменилось. Я ощущаю источник большой силы где-то в Занчуле.', '', 28153),
(136914, 'ruRU', 'Каждую неделю все больше зандаларов, привлеченных магией крови, встает на сторону еретиков из Назмира.', '', 28153),
(136913, 'ruRU', 'Наша защита слабеет. Принцесса давно просила отправить больше войск. Король не послушал ее, вот она и обратилась к Орде.', '', 28153),
(136912, 'ruRU', 'Тогда-то мы и узнали на своей шкуре, что такое настоящая магия крови.', '', 28153),
(136911, 'ruRU', 'Несколько лет назад по нам прошелся Катаклизм. Северные врата пали, и толпы троллей крови хлынули внутрь.', '', 28153),
(136910, 'ruRU', 'Я укажу лучшие места, а ты сбросишь на них сторожевые тотемы.', '', 28153),
(136909, 'ruRU', 'На земле валяется мешочек с рассыпанными лошадиными бисквитами. Вы осматриваете его и замечаете, что на нем вышито имя \"Эдди\".$b$bПохоже, мальчик здесь был. И вряд ли по собственной воле. По холму тоже тянется цепочка бисквитных крошек.', 'На земле валяется мешочек с рассыпанными лошадиными бисквитами. Вы осматриваете его и замечаете, что на нем вышито имя \"Эдди\".$b$bПохоже, мальчик здесь был. И вряд ли по собственной воле. По холму тоже тянется цепочка бисквитных крошек.', 28153),
(136908, 'ruRU', 'Не знаю, сколько мы еще выдержим в войне с сетраками...', '', 28153),
(136907, 'ruRU', 'Ты, видимо, не из Зулдазара, раз не знаешь, кто я такой. Я был личным поваром генерала Джакра\'зета!$b$bМеня отправили в ссылку, когда генерал слег, отведав мое кушанье... но я не виноват!$b$bДругие повара мне завидовали. Видимо, один из них добавил яд в еду, когда я отвернулся.$b$bКогда-нибудь я докажу свою невиновность, а пока придется готовить навозников, чтобы выжить.', '', 28153),
(136906, 'ruRU', 'АЛЬЯНС, СТОЯТЬ ДО КОНЦА!', '', 28153),
(136905, 'ruRU', 'Что привело тебя в Вол\'дун?', 'Что привело тебя в Вол\'дун?', 28153),
(136904, 'ruRU', '$c, ты задаешь опасные вопросы.\n\nЯ свое прошлое не скрываю, но не все думают так же, как я...\n\nМою семью отправили в ссылку, когда я был еще мальчишкой. Отец сильно задолжал, а в те времена дети отправлялись в ссылку вместе с родителями.\n\nЯ остался совсем один и чуть не умер от жажды, но меня нашел Разгаджи. Он выходил меня и вырастил как сына. С тех пор я его не покидал.', '', 28153),
(136903, 'ruRU', 'Как ты оказался в Вол\'дуне?', 'Как ты оказался в Вол\'дуне?', 28153),
(136902, 'ruRU', '', 'Эй, ты. Я тебя раньше не видела. Подойди.', 28153),
(136901, 'ruRU', '', 'Хир\'ик доволен... но этого недостаточно! Нужна еще жертва!', 28153),
(136900, 'ruRU', '', 'Великий Хир\'ик, лоа нетопырей и слуга Г\'ууна. Эта жертва для тебя!', 28153),
(136899, 'ruRU', '', 'Ты найдешь ведуна Раала на другом конце террасы. Передай ему от меня что-нибудь гадкое.', 28153),
(136895, 'ruRU', 'Время вышло, король Андуин!', '', 28153),
(136894, 'ruRU', 'Убегать – удел беспомощной жертвы. Мы сразимся за то, во что верим... и погибнем, если будет нужно.', '', 28153),
(136889, 'ruRU', '', 'Говори, а не то на следующем ритуале мы вырвем тебе язык.', 28153),
(136888, 'ruRU', '', 'Хир\'ик дарует нам своих детей, а Кровавый бог – свою силу. Вместе мы непобедимы.', 28153),
(136887, 'ruRU', '', 'Что? Говори скорее, а не то станешь следующей жертвой.', 28153),
(136882, 'ruRU', 'Захват каната', 'Захват каната', 28153),
(136878, 'ruRU', '', 'На войне нужны... эффективные методы.', 28153),
(136876, 'ruRU', '', 'Змеи! Берегись!', 28153),
(136874, 'ruRU', 'Ты с Гонком уже $gпоговорил:поговорила;? Он – глава стаи. Он являлся некоторым троллям Черного копья и наставил их на путь друидизма.$b$bНо для нас он больше, чем голос. Мы можем увидеть его во плоти и поговорить с ним. Не с каким-то видением или частицей, а с ним самим.', 'Ты с Гонком уже $gпоговорил:поговорила;? Он – глава стаи. Он являлся некоторым троллям Черного копья и наставил их на путь друидизма.$b$bНо для нас он больше, чем голос. Мы можем увидеть его во плоти и поговорить с ним. Не с каким-то видением или частицей, а с ним самим.', 28153),
(136872, 'ruRU', 'Гонк научил всех троллей влиять на других лоа, становясь друидами. И мы будем вечно ему благодарны.', 'Гонк научил всех троллей влиять на других лоа, становясь друидами. И мы будем вечно ему благодарны.', 28153),
(136871, 'ruRU', 'Приверженцы Па\'ку еще обижены на то, что боевой друид Лоти покинула верховного ведуна Раала. Так печально. Так непрофессионально.', 'Приверженцы Па\'ку еще обижены на то, что боевой друид Лоти покинула верховного ведуна Раала. Так печально. Так непрофессионально.', 28153),
(136870, 'ruRU', 'Приверженцы Гонка все еще обижены на то, что верховный ведун Раал покинул боевого друида Лоти. Так печально. Так непрофессионально.', 'Приверженцы Гонка все еще обижены на то, что верховный ведун Раал покинул боевого друида Лоти. Так печально. Так непрофессионально.', 28153),
(136869, 'ruRU', 'Делай что угодно, но не слушай лживые речи этих последователей Гонка. Они просто завидуют величию нашего лоа – Па\'ку.', 'Делай что угодно, но не слушай лживые речи этих последователей Гонка. Они просто завидуют величию нашего лоа – Па\'ку.', 28153),
(136868, 'ruRU', 'Я подчиняюсь лоа Па\'ку, повелительнице ветров и хозяйке флота. Ее величие и сила невероятны. Советую тебе иметь дело только с ней. Другим нельзя доверять.', 'Я подчиняюсь лоа Па\'ку, повелительнице ветров и хозяйке флота. Ее величие и сила невероятны. Советую тебе иметь дело только с ней. Другим нельзя доверять.', 28153),
(136867, 'ruRU', 'Хм, $p. Лоа шептали твое имя. Кажется, твое появление в Зулдазаре – примечательное событие.', 'Хм, $p. Лоа шептали твое имя. Кажется, твое появление в Зулдазаре – примечательное событие.', 28153),
(136866, 'ruRU', 'Па\'ку – лоа ветров, повелительница разведчиков и флота. Она очень импульсивна и свободолюбива. Если захочешь узнать больше, поговори с ее защитником, верховным ведуном Раалом.', 'Па\'ку – лоа ветров, повелительница разведчиков и флота. Она очень импульсивна и свободолюбива. Если захочешь узнать больше, поговори с ее защитником, верховным ведуном Раалом.', 28153),
(136865, 'ruRU', 'А! Герой Орды. Верховный ведун Раал будет поражен. Понравишься ему – понравишься Па\'ку, а значит, и мне.', 'А! Герой Орды. Верховный ведун Раал будет поражен. Понравишься ему – понравишься Па\'ку, а значит, и мне.', 28153),
(136864, 'ruRU', 'Нечего тебе здесь делать!', 'Нечего тебе здесь делать!', 28153),
(136863, 'ruRU', 'Мне нечего тебе сказать.', 'Мне нечего тебе сказать.', 28153),
(136862, 'ruRU', 'Откуда ты? Тебя тут не должно быть.', 'Откуда ты? Тебя тут не должно быть.', 28153),
(136861, 'ruRU', 'Изгой. Пф!', 'Изгой. Пф!', 28153),
(136860, 'ruRU', 'Я не разговариваю с такими, как ты, деревенщина.', 'Я не разговариваю с такими, как ты, деревенщина.', 28153),
(136859, 'ruRU', '', 'Как и ожидалось, моя работа безупречна. Похоже, что-то блокирует ток воды в фонтане. Не посмотришь?', 28153),
(136858, 'ruRU', '', 'Давай-ка осмотрим этот фонтан повнимательнее.', 28153),
(136857, 'ruRU', 'Твоя кровь послужит моему следующему ритуалу.', 'Твоя кровь послужит моему следующему ритуалу.', 28153),
(136856, 'ruRU', 'Назойливое отродье Орды!', 'Назойливое отродье Орды!', 28153),
(136855, 'ruRU', 'Всех нас вам все равно не остановить!', 'Всех нас вам все равно не остановить!', 28153),
(136854, 'ruRU', 'Думаешь, тут только я пользуюсь магией крови? Тебя ждет неприятный сюрприз.', 'Думаешь, тут только я пользуюсь магией крови? Тебя ждет неприятный сюрприз.', 28153),
(136853, 'ruRU', 'Пф! Я не позволю какой-то мелкой сошке из Орды мне помешать!', 'Пф! Я не позволю какой-то мелкой сошке из Орды мне помешать!', 28153),
(136852, 'ruRU', 'Я думал, летуны должны искать следы троллей крови. Чего это мы должны делать за тебя твою работу?', 'Я думала, летуны должны искать следы троллей крови. Чего это мы должны делать за тебя твою работу?', 28153),
(136851, 'ruRU', 'Ты не помешаешь нашим ритуалам. Лоти об этом позаботится.', 'Ты не помешаешь нашим ритуалам. Лоти об этом позаботится.', 28153),
(136850, 'ruRU', 'Вы, фанатики, принесете Зандалару погибель!', 'Вы, фанатики, принесете Зандалару погибель!', 28153),
(136849, 'ruRU', 'Вас всех скормят лоа королей, если Раал будет продолжать нам мешать.', 'Вас всех скормят лоа королей, если Раал будет продолжать нам мешать.', 28153),
(136848, 'ruRU', '', 'Их слишком много. Только скажите – и я перенесу нас в безопасное место.', 28153),
(136846, 'ruRU', 'Все ходишь хвостом за Лоти? Ха! Оказывается, ты тупее, чем навозная муха.', 'Все ходишь хвостом за Лоти? Ха! Оказывается, ты тупее, чем навозная муха.', 28153),
(136845, 'ruRU', 'Это вы теперь в меньшинстве.', '', 28153),
(136844, 'ruRU', 'Когда здесь будет править Раал, он выдворит вас всех в лес, где вам самое место.', 'Когда здесь будет править Раал, он выдворит вас всех в лес, где вам самое место.', 28153),
(136843, 'ruRU', 'Твоего лоа зовут Гонк. Радоваться тут нечему.', 'Твоего лоа зовут Гонк. Радоваться тут нечему.', 28153),
(136842, 'ruRU', 'У вас, мерзких друидов, ничего не осталось. Прямо как у гурубаши.', 'У вас, мерзких друидов, ничего не осталось. Прямо как у гурубаши.', 28153),
(136841, 'ruRU', 'Ты ничем не лучше меня. На твоих руках... моя кровь.', '', 28153),
(136840, 'ruRU', 'Каждый тролль за себя. Убивай или умри!', '', 28153),
(136838, 'ruRU', '<Вы видите еще теплое тело Крутыша, пони Эдди.>$b$b<Вверх по холму тянется цепочка крошек. Похоже, Эдди оставил след.>', 'Вы видите еще теплое тело Крутыша, пони Эдди.$b$bВы надеетесь, что хотя бы Эдди еще жив.', 28153),
(136837, 'ruRU', 'Мальчики такие вкусные!', '', 28153),
(136836, 'ruRU', 'Я здесь! Ключ у него! Пожалуйста, помоги мне!', '', 28153),
(136835, 'ruRU', '', 'Нужно идти, $n. Лорд Норвингтон меня прикончит, если с его сыном что-то случится!', 28153),
(136832, 'ruRU', 'Мы – племя изгоев, нас изгнали из Зулдазара и бросили умирать в пустыне.\n\nКого-то из нас просто-напросто оклеветали и обвинили в чужих преступлениях. Но остальные заслужили эту долю.\n\nТеперь мы всего лишь хотим выжить.\n\nСоблюдай законы моего племени, и тебе всегда найдется место среди нас. Но если нарушишь их, наша расправа будет куда более скорой, чем у короля Растахана.', '', 28153),
(136831, 'ruRU', 'Чего ты хочешь, ма\'да?', '', 28153),
(136830, 'ruRU', 'Что такое? Ты... ты, наверное, следующая жертва?', '', 28153),
(136829, 'ruRU', 'Жрицы! Они нас всех перебьют!', '', 28153),
(136828, 'ruRU', 'Раз у тебя больше нет маскировки, будет гораздо больше шума и крови.', '', 28153),
(136827, 'ruRU', 'Расскажи мне о своем племени.', 'Расскажи мне о своем племени.', 28153),
(136825, 'ruRU', '', 'Это щит Ракиры... Где она? Что ты с ней сделал?', 28153),
(136824, 'ruRU', 'Это все Джакра\'зет... не я. Ракира меня спасла.', '', 28153),
(136823, 'ruRU', '', 'Миира, останови повозку! Там впереди что-то есть.', 28153),
(136822, 'ruRU', '', 'Неужели Ракира могла здесь выжить?', 28153),
(136820, 'ruRU', '', 'Трудно представить, но когда-то на месте этих пустошей были роскошные джунгли, жемчужина империи троллей. А теперь здесь один песок.', 28153),
(136819, 'ruRU', '', 'Киро зря переживает. Я всю жизнь вожу повозки. Но вы на всякий случай держитесь покрепче.', 28153),
(136818, 'ruRU', '', 'Ладно, ладно!', 28153),
(136816, 'ruRU', '$C нам в этом поможет. Такое моджо – я его прямо чую.', '', 28153),
(136815, 'ruRU', 'Ты не отличаешься от остальных сумасшедших, что добровольно отправились в Наз... что-о?', 'Ты не отличаешься от остальных сумасшедших, что добровольно отправились в Наз... что-о?', 28153),
(136814, 'ruRU', 'Пф! Сейчас я покажу вам всем, что этот парень спятил.', 'Пф! Сейчас я покажу вам всем, что этот парень спятил.', 28153),
(136813, 'ruRU', 'Я всем в лагере расскажу, что ты меня $gспас:спасла;!', '', 28153),
(136812, 'ruRU', 'Я свободен! Ура!', '', 28153),
(136811, 'ruRU', 'Если я верну себе силу, то смогу победить его...', '', 28153),
(136810, 'ruRU', 'Знакомьтесь: Урок – монстр-нежить, который всех вас перебьет.', '', 28153),
(136809, 'ruRU', 'Балда! Ты станешь кормом для Урока!', '', 28153),
(136808, 'ruRU', 'Тсс... Урок близко. Я чую его зубы...', '', 28153),
(136807, 'ruRU', 'Покажи мне Урока, грозу топей.', 'Покажи мне Урока, грозу топей.', 28153),
(136806, 'ruRU', '', 'Эдди!!!', 28153),
(136805, 'ruRU', 'Па\'ку, Па\'ку, Па\'ку – это твой верный путь.', 'Па\'ку, Па\'ку, Па\'ку – это твой верный путь.', 28153),
(136804, 'ruRU', 'Тебе нравится небо? Мне – да. Иди за Па\'ку. Это твой верный путь.', 'Тебе нравится небо? Мне – да. Иди за Па\'ку. Это твой верный путь.', 28153),
(136803, 'ruRU', 'А ну давай не зевай! В войско Па\'ку ты вступай!', 'А ну давай не зевай! В войско Па\'ку ты вступай!', 28153),
(136800, 'ruRU', 'С ним все в порядке! Не надо... А-а!', '', 28153),
(136799, 'ruRU', '', 'Вот так, Эдди. Только не заставляй Крутыша нервничать.', 28153),
(136798, 'ruRU', '', 'Жалкий червь! Хир\'ику ты не сгодишься даже для жертвоприношения!', 28153),
(136797, 'ruRU', '', 'Идем. Пробил твой час.', 28153),
(136789, 'ruRU', 'Бывай, $n. До скорой встречи.', '', 28153),
(136788, 'ruRU', 'Я возвращаюсь в Зо\'бал. Мне нужно больше душ, чтобы отдать свой долг.', '', 28153),
(136780, 'ruRU', 'Скованный ночной охотник издает булькающий вой.', '', 28153),
(136779, 'ruRU', 'Скованный ночной охотник что-то чует неподалеку!', '', 28153),
(136778, 'ruRU', 'Скованный ночной охотник принюхивается.', '', 28153),
(136769, 'ruRU', '', 'Мики заслуживал лучшей доли, но я знаю, что это не твоя вина.\n\nСпасибо тебе за помощь в его поисках. Лучше познать боль, чем прожить всю жизнь в сожалениях.\n\nМы как одна семья в этой пустыне, и теперь ты тоже часть этой семьи. Тебе всегда рады в нашем караване.', 28153),
(136768, 'ruRU', 'Твой разум должен оставаться чистым. Враги почуют любую слабину.', '', 28153),
(136767, 'ruRU', 'Хорош уже!', '', 28153),
(136766, 'ruRU', 'Хо-хо-хочу, чтобы Ана спела о твоих приключениях.\n\nОна со-со-сочиняет очень хорошую музыку. Не-не-не забудь рассказать ей свою историю!\n\nА м-м-мы позаботимся, чтобы ее все узнали.', '', 28153),
(136764, 'ruRU', '', 'Трагедия, восставшие из мертвых пираты, проклятые сокровища, бунт... Этому приключению просто суждено стать легендой.\n\nУ меня уже есть идеи для первого куплета песни, которая будет называться \"$p, отважный герой\".\n\nЛегенды о тебе будут жить в веках! По крайней мере среди тех, кто был в этом караване.\n\nПусть только все проснутся.', 28153),
(136763, 'ruRU', 'Деритесь изо всех сил! От исхода боя зависит наша судьба!', '', 28153),
(136762, 'ruRU', 'Мы сражаемся не только ради того чтобы защитить зандаларов, но и за их будущее. Отнесись к этому со всей серьезностью.', '', 28153),
(136761, 'ruRU', 'Нападать надо стремительно, но никогда не забывать о воинах рядом.', '', 28153),
(136760, 'ruRU', 'Цель надо поражать с силой... Но и не без грации.', '', 28153),
(136759, 'ruRU', 'Я уже много ездил в загоне, а здесь почти то же самое.', '', 28153),
(136758, 'ruRU', '', 'Держи вожжи крепче, Эдди.', 28153),
(136757, 'ruRU', '', 'Лорд Норвингтон доверил мне обучать его сына верховой езде. На ипподроме он уже делает успехи, но я пока боюсь отпускать его отсюда. Не уверена, что он сможет удержать своего пони, если тот чего-то испугается.$b$bНо надеюсь, до этого не дойдет!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(136756, 'ruRU', 'Крутыш ничего не боится. Он хороший мальчик!', '', 28153),
(136755, 'ruRU', 'По-моему, он слушает – смотри, как уши навострил!', '', 28153),
(136754, 'ruRU', 'Да, да!', '', 28153),
(136753, 'ruRU', '', 'Езжай медленно и осторожно. Здесь все что угодно может его спугнуть.', 28153),
(136752, 'ruRU', '', 'Удерживай его внимание на себе – вокруг много всякого происходит!', 28153),
(136751, 'ruRU', '', 'Эдди! Правь ногой, а не рукой.', 28153),
(136750, 'ruRU', 'Хм... Пустыня на болотах... Что эти сетраки задумали?', '', 28153),
(136747, 'ruRU', 'Хочу тебя поблагодарить за спасение от этих кошмарных завролисков. Чтоб я еще раз сунулся в русло реки в одиночку! Ну, разве когда постарше стану...', '', 28153),
(136746, 'ruRU', 'Ау! Тут есть кто-нибудь?', '', 28153),
(136745, 'ruRU', 'Альянс – ничто по сравнению с нами. Слава Орде!', '', 28153),
(136744, 'ruRU', 'Порт Зем\'лана мой!', '', 28153),
(136741, 'ruRU', 'Сур\'джан, не сходи с ума! После этого мы из Назмира больше ни шагу. Я в Зулдазар больше не вернусь.', '', 28153),
(136740, 'ruRU', 'Если ты мне поможешь, у меня хватит силы, чтобы снова сразиться с Уроком и победить его. Я подожду здесь – нужно готовиться к следующему ритуалу.', '', 28153),
(136738, 'ruRU', 'Эти монстры хотели меня съесть!', '', 28153),
(136732, 'ruRU', 'Что, Сур\'джан? Хм... да, ты прав.', '', 28153),
(136731, 'ruRU', 'Сур\'джан, мне следовало самому этим заняться. Не люблю сидеть сложа руки, когда другие работают.', '', 28153),
(136730, 'ruRU', 'Я пойду вперед! Подготовь все для схватки с Уроком!', '', 28153),
(136729, 'ruRU', 'Папа говорит, что в этом году я смогу участвовать в фестивале. Меня наконец-то учат ездить верхом!', '', 28153),
(136728, 'ruRU', 'Я забочусь о природном балансе.\n\nМолчать, Сур\'джан, ну конечно же, меня заботит природный баланс... типа. $gЕму:Ей; это знать не обязательно.', '', 28153),
(136727, 'ruRU', 'На болотах полно всяких ужасов – стань одним из них, если хочешь выжить.', '', 28153),
(136726, 'ruRU', 'Проклятье... исчезло? Я наконец-то свободен?', '', 28153),
(136725, 'ruRU', 'Ты на проклятой земле... Отсюда никто не уходит!', '', 28153),
(136724, 'ruRU', '', 'В тенях Зем\'лана таятся жуткие монстры.\n\nПостарайся не стать одним из них.', 28153),
(136723, 'ruRU', 'Се-се-семья должна держаться вместе, что бы ни случилось.', '', 28153),
(136722, 'ruRU', 'Да, и если что, я не шучу. Я хочу, чтобы этот тролль был мертв, как Урок. Удачной охоты.', '', 28153),
(136721, 'ruRU', 'Не будь дураком, Сур\'джан. $gОн:Она; не решит, что я шучу. Ладно, я позабочусь, чтобы не $gрешил:решила;.', '', 28153),
(136720, 'ruRU', 'С тобой приятно иметь дело. Если встретишь тролля по имени Круга, не забудь его прикончить. Ха!', '', 28153),
(136719, 'ruRU', 'Не будем терять время. С Уроком надо покончить!', '', 28153),
(136718, 'ruRU', 'Да! Время пришло... Мы покончим с Уроком!', '', 28153),
(136717, 'ruRU', 'Я чувствую это... Сила возвращается ко мне!', '', 28153),
(136713, 'ruRU', 'Ха-ха! Еще чуть-чуть... и мы сумеем убить Урока!', '', 28153),
(136712, 'ruRU', 'Отлично... я чувствую, как ко мне возвращается сила!', '', 28153),
(136711, 'ruRU', 'Ох... Этого мало! Нам нужно еще больше силы, чтобы убить Урока!', '', 28153),
(136710, 'ruRU', 'Это все, что мне нужно... Пришло время получить больше силы!', '', 28153),
(136698, 'ruRU', 'Нам повезло. Но не тебе. Еще нет.', '', 28153),
(136697, 'ruRU', 'Ей нужно то, что можно получить только в обмен на жертву.', '', 28153),
(136696, 'ruRU', '', 'За морем звезд лишь бесконечная тьма.', 28153),
(136695, 'ruRU', '', 'Скажи папе, что я его прощаю.', 28153),
(136694, 'ruRU', '', 'Она еще не предала тебя? Предаст...', 28153),
(136693, 'ruRU', '', 'Ты умрешь в одиночестве.', 28153),
(136692, 'ruRU', '', 'Повелитель ждет. Скоро ты присоединишься к нему...', 28153),
(136691, 'ruRU', '', 'Он очнулся. И увидел тебя.', 28153),
(136690, 'ruRU', '', 'Скоро ты вольешься в наши ряды.', 28153),
(136689, 'ruRU', '', 'Я знаю, что ты $gсделал:сделала;.', 28153),
(136688, 'ruRU', '', 'Вы слышите тихий смех.', 28153),
(136687, 'ruRU', '', 'Вы чувствуете, что на вас кто-то смотрит.', 28153),
(136686, 'ruRU', '', 'За вами следят.', 28153),
(136685, 'ruRU', '', 'Призрачная девочка смеется и убегает прочь.', 28153),
(136684, 'ruRU', 'Наша следующая встреча станет последней...', '', 28153),
(136683, 'ruRU', 'Твоя душа будет моей!', '', 28153),
(136681, 'ruRU', 'Ты оскверняешь это место своим присутствием. Берегись гнева Ксибалы!', 'Ты оскверняешь это место своим присутствием. Берегись гнева Ксибалы!', 28153),
(136680, 'ruRU', '', 'Тебе нужны самые лучшие моджо и сувениры с юга? Тогда заходи к Вундже!', 28153),
(136679, 'ruRU', 'Глупое смертное существо! Ксибала тебя уничтожит!', 'Глупое смертное существо! Ксибала тебя уничтожит!', 28153),
(136678, 'ruRU', 'Мы полетим на Ате Крылатом Властелине. Запрыгивай и не зевай.', '', 28153),
(136677, 'ruRU', 'Как говорит мой лоа: \"Не видишь источник порчи – взлетай выше\".', '', 28153),
(136676, 'ruRU', 'Лоти слишком приземленная. Я смотрю на вещи с высоты полета терродактиля.', '', 28153),
(136674, 'ruRU', 'К службе готов.', 'К службе готова.', 28153),
(136673, 'ruRU', '', 'Я боевой друид Лоти! Во мне сила Гонка – лоа перевоплощения и повелителя охоты.$b$bЯ также состою в Совете Занчули, но, думаю, тебе уже это известно.', 28153),
(136672, 'ruRU', 'Курьер кивает зандаларскому стражу.', '', 28153),
(136671, 'ruRU', 'Стражник внимательно изучает вас.', '', 28153),
(136670, 'ruRU', 'Стражник замечает вас.', '', 28153),
(136669, 'ruRU', 'Это послужит тебе уроком!', 'Это послужит тебе уроком!', 28153),
(136668, 'ruRU', 'Страж отдает вам честь, когда вы проходите мимо.', '', 28153),
(136667, 'ruRU', 'Страж кивает в вашу сторону.', '', 28153),
(136662, 'ruRU', 'Я – верховный ведун Раал, один из Совета Занчули и верховный жрец великой лоа Па\'ку, повелительницы ветров и покровительницы нашего флота. \n\nЧто тебе нужно?', '', 28153),
(136657, 'ruRU', 'За работу.', '', 28153),
(136655, 'ruRU', '', 'Да хранит тебя Свет!', 28153),
(136654, 'ruRU', 'Глупый Сур\'джан! Что ты при всех несешь всякий бред? Все решат, что ты спятил!', '', 28153),
(136653, 'ruRU', 'Пойду подготовлю все для ритуала. Как только я верну себе силу, мы сможем убить Урока.', '', 28153),
(136652, 'ruRU', 'Да, знаю, что ты думаешь: я из Назмира – значит, сумасшедший. Но выслушай меня! Вы все погибнете, если ты мне не поможешь!', '', 28153),
(136651, 'ruRU', 'Я знаю, ты думаешь, что я спятил, но мне нужна твоя помощь!', '', 28153),
(136650, 'ruRU', 'Хватит уворачиваться! Мне нужна твоя помощь!', '', 28153),
(136649, 'ruRU', 'Вот, его защита нам больше не помеха! Пора его прикончить!', '', 28153),
(136648, 'ruRU', '', 'Г\'уун возродил меня!', 28153),
(136647, 'ruRU', 'Окажи честь, сделай все... сложные дела. А я подожду у входа в логово.', '', 28153),
(136646, 'ruRU', 'Ха! Получилось! Сур\'джан, я же говорил! Мы его победили!', '', 28153),
(136645, 'ruRU', 'Разделайся с ведьмой. А эти пляшущие кости... ее \"слуги\"... падут перед истинным владыкой мертвых!', '', 28153),
(136644, 'ruRU', 'Урока защищают тотемы! Возьми мой факел и сожги их!', '', 28153),
(136643, 'ruRU', '<Рюкзак засыпан песком и наполовину погребен под ним, но, кажется, его содержимое цело.>', '', 28153),
(136642, 'ruRU', '', 'Я же говорила, держись подальше от шахты. Мы едва успели тебя вытащить!', 28153),
(136641, 'ruRU', 'Смерть идет за тобой!', 'Смерть идет за тобой!', 28153),
(136640, 'ruRU', 'Незваный гость!', 'Незваный гость!', 28153),
(136639, 'ruRU', 'Присоединись к нам!', 'Присоединись к нам!', 28153),
(136638, 'ruRU', '', 'Ничто не помешает моей работе! Уничтожить эту тварь!', 28153),
(136637, 'ruRU', 'Вперед! Вперед! Вперед!', 'Вперед! Вперед! Вперед!', 28153),
(136632, 'ruRU', 'Ха-ха, этот мой!', '', 28153),
(136615, 'ruRU', '', 'Восстаньте, слуги! Убейте этого лоа!', 28153),
(136614, 'ruRU', 'Мне нужна твоя помощь... Необходимо уничтожить кое-что очень плохое и злобное, и один я с ним не справлюсь.', '', 28153),
(136613, 'ruRU', '', 'Хвались, хвались. Всех, кто отказывает Г\'ууну, ждет смерть!', 28153),
(136611, 'ruRU', 'Никто не смеет указывать Бвонсамди! Думаешь, у тебя хватит сил тягаться со мной?', '', 28153),
(136610, 'ruRU', 'Ай-яй-яй. Вроде умная такая, а пришла мешать мне в моем же храме.', '', 28153),
(136609, 'ruRU', '', 'Я даю тебе один шанс подчиниться Кровавому богу. Сдавайся... или умри!', 28153),
(136608, 'ruRU', '', 'Бвонсамди! Наконец-то ты вылез из своих руин.', 28153),
(136607, 'ruRU', 'Чего стоишь тут и прохлаждаешься? Давай начнем!', '', 28153),
(136605, 'ruRU', 'Начнем.', 'Начнем.', 28153),
(136604, 'ruRU', 'Ритуал связывания – моджо, древнее, как мир. Он отправляет души всех, кого ты убьешь, прямиком к Бвонсамди. Проведешь ритуал – и заключим сделку.$b$bПриступим? Я готов.', '', 28153),
(136603, 'ruRU', '', 'Чего тебе надо?', 28153),
(136602, 'ruRU', '', 'Мои новобранцы готовы помочь в защите мирных жителей. Начинаем эвакуацию?', 28153),
(136601, 'ruRU', 'Я готов.', 'Я готова.', 28153),
(136600, 'ruRU', 'Ну и гадкая выходка, Мизинчик. Плохой дьявозавр! Плохой!', 'Ну и гадкая выходка, Мизинчик. Плохой дьявозавр! Плохой!', 28153),
(136599, 'ruRU', 'Приходи во Двор духов. Пора завершить нашу... сделку.', '', 28153),
(136591, 'ruRU', 'Это не обсуждается, сестра. У нас приказ от твоей принцессы.', '', 28153),
(136590, 'ruRU', '', 'А потом она приказала мне проследить, чтобы $n и, как она сказала, \"симпатяжка\" добрались до Назмира как можно скорее.', 28153),
(136589, 'ruRU', 'Шаркун обратился против своих создателей!', '', 28153),
(136588, 'ruRU', 'Похоже, раб на время отключен.', '', 28153),
(136587, 'ruRU', 'Раб приходит в бешенство!', '', 28153),
(136581, 'ruRU', 'Морской страж, разберись с пришельцем. Исполни мою волю.', '', 28153),
(136578, 'ruRU', 'Дань уважения', '', 28153),
(136577, 'ruRU', 'Уверен, на пристани найдется оружие Эшвейнов. Нужно узнать, кому оно предназначено.', '', 28153),
(136576, 'ruRU', '', 'У меня много сестер... Кул-Тирас падет...', 28153),
(136575, 'ruRU', '', 'Тебе не победить! Ковен не остановится, пока все не будут служить ему!', 28153),
(136574, 'ruRU', '', 'Познай мой гнев!', 28153),
(136573, 'ruRU', '', 'Впечатляет... но этого недостаточно, чтобы убить матрону ковена Мертвых Сердец!', 28153),
(136572, 'ruRU', '', 'Сейчас ты увидишь, что бывает с врагами ковена. Слуги, уничтожьте наше потерянное дитя!', 28153),
(136571, 'ruRU', '', 'Значит какая-то самонадеянная мошка решила обратить одно из наших созданий против меня?', 28153),
(136570, 'ruRU', 'Но я никогда не видел тут такого оживления. Что-то явно происходит.', '', 28153),
(136569, 'ruRU', 'Мародеры, наемники, даже пираты... Довольно... колоритный город.', '', 28153),
(136568, 'ruRU', 'В Вольной Гавани гуляет ветер свободы. В отличие от Боралуса сюда могут заходить любые корабли.', '', 28153),
(136567, 'ruRU', '', '$c, прости, но водоросли у нас кончились. Всем было так плохо, что выйти на их сбор никто не смог. Передай Терольду, что мне очень жаль.', 28153),
(136566, 'ruRU', '', 'Сестры отомстят за меня...', 28153),
(136565, 'ruRU', '', 'Не стоило тебе лезть сюда!', 28153),
(136564, 'ruRU', 'У тебя есть водоросли? Они нужны Терольду для лекарства.', 'У тебя есть водоросли? Они нужны Терольду для лекарства.', 28153),
(136563, 'ruRU', '', 'Ты падешь перед матроной...', 28153),
(136562, 'ruRU', '', 'Этот город принадлежит ковену!', 28153),
(136561, 'ruRU', '', 'Столько работы, как все успеть?$b$bНадо благословить рыбаков и их сети, понять, о чем говорят волны, помолиться о возвращении моряков...', 28153),
(136560, 'ruRU', '', 'Ты будешь служить ковену...', 28153),
(136559, 'ruRU', '', 'Ковен поглотит все!', 28153),
(136558, 'ruRU', 'Сегодня охотятся сирены, но они остаются на суше. Держитесь подальше от островов – и все будет хорошо.', 'Сегодня охотятся сирены, но они остаются на суше. Держитесь подальше от островов – и все будет хорошо.', 28153),
(136557, 'ruRU', 'Волны бушуют на востоке, но здесь, на западе, море тихое.', 'Волны бушуют на востоке, но здесь, на западе, море тихое.', 28153),
(136556, 'ruRU', 'Мое благословение будет хранить тебя даже в воде.', 'Мое благословение будет хранить тебя даже в воде.', 28153),
(136555, 'ruRU', 'Отправь рыбаков в воды возле доков у рынка. Сегодня там много рыбы.', 'Отправь рыбаков в воды возле доков у рынка. Сегодня там много рыбы.', 28153),
(136554, 'ruRU', 'Твои советы помогут нам вернуться невредимыми.', 'Твои советы помогут нам вернуться невредимыми.', 28153),
(136553, 'ruRU', 'Мы собираемся в глубокие воды. Каким путем лучше направиться?', 'Мы собираемся в глубокие воды. Каким путем лучше направиться?', 28153),
(136552, 'ruRU', 'Тогда мы можем не волноваться. Спасибо!', 'Тогда мы можем не волноваться. Спасибо!', 28153),
(136551, 'ruRU', 'Мы отправляемся в глубокие воды. Какие сейчас волны?', 'Мы отправляемся в глубокие воды. Какие сейчас волны?', 28153),
(136550, 'ruRU', 'Я чувствую, как твое благословение наполняет меня. Прими мою благодарность.', 'Я чувствую, как твое благословение наполняет меня. Прими мою благодарность.', 28153),
(136549, 'ruRU', 'Я собираюсь в логово чудовищ. Пожалуйста, даруй мне свое благословение!', 'Я собираюсь в логово чудовищ. Пожалуйста, даруй мне свое благословение!', 28153),
(136548, 'ruRU', 'Я скажу рыбакам.', 'Я скажу рыбакам.', 28153),
(136547, 'ruRU', 'Где сегодня больше всего рыбы?', 'Где сегодня больше всего рыбы?', 28153),
(136546, 'ruRU', 'О тебе говорит весь крааль. Отваги тебе не занимать!', '', 28153),
(136545, 'ruRU', '', 'Ты – среди тех, кто идет по пути лоа. Будь осторожнее, не все лоа ладят между собой.', 28153),
(136538, 'ruRU', 'Воины Орды! Сегодня наши топоры вволю напьются крови врагов!', '', 28153),
(136533, 'ruRU', 'Меггакрут, ваши машины смогут перелететь через чуму?', '', 28153),
(136532, 'ruRU', '', 'Сравняем шансы, король Ринн!', 28153),
(136528, 'ruRU', 'Джайна, перекройте проходы! Не дайте им вызвать подкрепление!', '', 28153),
(136527, 'ruRU', 'Этот храм падет! Жрица предвидела это!', '', 28153),
(136526, 'ruRU', 'Защищать жрицу!', '', 28153),
(136525, 'ruRU', 'Для ритуала жрице нужна кровь. Твоя сгодится.', '', 28153),
(136524, 'ruRU', 'За жрицу! За Г\'ууна!', '', 28153),
(136523, 'ruRU', 'У Бвонсамди нет над нами власти! За Кровавого бога!', '', 28153),
(136522, 'ruRU', 'Во имя полководца!', '', 28153),
(136521, 'ruRU', 'Чужак! Я уничтожу тебя!', '', 28153),
(136520, 'ruRU', 'За Малаку! За Кровавого бога!', '', 28153),
(136519, 'ruRU', 'Ты станешь хорошим рабом для полководца!', '', 28153),
(136518, 'ruRU', '', 'Как ты смеешь прерывать мой ритуал?', 28153),
(136517, 'ruRU', '', 'Хватит! Я сказала, что подумаю!', 28153),
(136516, 'ruRU', 'Но ты можешь удвоить – нет, утроить! – производительность! Мои эликсиры изготовлены только из натуральных ингредиентов, гарантирую...', '', 28153),
(136515, 'ruRU', '', 'Даже не знаю... Наши методы хорошо работают, и...', 28153),
(136514, 'ruRU', 'Серьезно, ты тако-о-ой шанс упускаешь! Подумай!', '', 28153),
(136513, 'ruRU', '', 'Ты об этом пожалеешь!', 28153),
(136512, 'ruRU', '', 'Начинаем ритуал! Сейчас я стану чем-то большим!', 28153),
(136511, 'ruRU', 'Нечего тут смотреть... проваливай!', '', 28153),
(136510, 'ruRU', 'Не нарывайся.', '', 28153),
(136509, 'ruRU', 'Эй! Ты что тут делаешь?', '', 28153),
(136508, 'ruRU', '', 'Все склонятся перед волей Кровавого бога...', 28153),
(136507, 'ruRU', '', 'Больше крови Кровавому богу!', 28153),
(136498, 'ruRU', 'Все с ума посходили! Я уматываю отсюда, пока есть возможность!', '', 28153),
(136497, 'ruRU', '', 'Все кончено.\n\nЯ... Так было нужно. Тьма поглотила ее.\n\n<Ребекка шмыгает носом.>\n\nПрости. Мне нужно время, чтобы это осознать.', 28153),
(136495, 'ruRU', '', 'Сначала мне казалось забавным то, чем занималась моя сестра, но это ведь просто безумие!\n\nОна пишет о том, чтобы создать целую армию этих древних големов! Если ее не остановить, она поработит весь Друствар!', 28153),
(136494, 'ruRU', 'Сгинь!', 'Сгинь!', 28153),
(136493, 'ruRU', '', 'Надеюсь, мы с мамой еще увидим тебя.', 28153),
(136492, 'ruRU', '', 'Да, мама поступила неправильно. Но я ее прощаю. Теперь мы вечно будем вместе на Той Стороне.', 28153),
(136491, 'ruRU', '', 'Теперь мы с мамой будем вместе... всегда!', 28153),
(136490, 'ruRU', '', 'Не-е-ет... Я должна была... жить... вечно...', 28153),
(136489, 'ruRU', 'Осторожно, тут много всяких тварей водится.', '', 28153),
(136488, 'ruRU', '', 'Что это? Нет! Зачем ко мне привели это... существо?!', 28153),
(136487, 'ruRU', '', 'Я нашла тебя, мама!', 28153),
(136486, 'ruRU', '', 'Кто посмел потревожить меня?', 28153),
(136485, 'ruRU', '<Попытаться открыть саркофаг.>', '<Попытаться открыть саркофаг.>', 28153),
(136484, 'ruRU', '<Саркофаг плотно заперт, но, приложив усилия, вы вполне можете его открыть.>', '', 28153),
(136483, 'ruRU', '', 'Думаю, мы близко! Мама! Где ты?', 28153),
(136482, 'ruRU', '', 'Как там темно... Ты иди, а я за тобой.', 28153),
(136481, 'ruRU', '', 'Не-не, это склеп великой королевы. Мама попала бы там в беду.', 28153),
(136480, 'ruRU', '', 'Фу, тот жрец воняет тухлыми червями! Нет, мама бы туда не пошла.', 28153),
(136479, 'ruRU', '', 'Мама и я встретили жрецов. Они дали мне этот наряд. Они здоровские!', 28153),
(136478, 'ruRU', 'Я знал, что ты мне не ровня!', 'Я знала, что ты мне не ровня!', 28153),
(136477, 'ruRU', '', 'Не думаю, что она здесь. В главный храм никого не пускают.', 28153),
(136476, 'ruRU', 'Надо больше тренироваться...', 'Надо больше тренироваться...', 28153),
(136475, 'ruRU', 'Проклятье! Ты сильнее, чем я думал.', 'Проклятье! Ты сильнее, чем я думала.', 28153),
(136474, 'ruRU', 'Хватит! Я сдаюсь!', 'Хватит! Я сдаюсь!', 28153),
(136473, 'ruRU', 'Победа за тобой. На этот раз...', 'Победа за тобой. На этот раз...', 28153),
(136472, 'ruRU', 'Довольно! Я сдаюсь!', 'Довольно! Я сдаюсь!', 28153),
(136471, 'ruRU', 'Постарайся не запачкать меня кровью!', 'Постарайся не запачкать меня кровью!', 28153),
(136470, 'ruRU', 'Глупо было бросать мне вызов!', 'Глупо было бросать мне вызов!', 28153),
(136469, 'ruRU', 'Надеюсь, твой меч так же остр, как твой язык!', 'Надеюсь, твой меч так же остр, как твой язык!', 28153),
(136468, 'ruRU', 'Кто смеет бросать мне вызов? Ты у меня умоешься собственной кровью!', 'Кто смеет бросать мне вызов? Ты у меня умоешься собственной кровью!', 28153),
(136467, 'ruRU', 'Бой со мной будет твоей последней ошибкой!', 'Бой со мной будет твоей последней ошибкой!', 28153),
(136466, 'ruRU', 'Если тебе хочется, чтобы тебя побили... уж я тебе не откажу!', 'Если тебе хочется, чтобы тебя побили... уж я тебе не откажу!', 28153),
(136465, 'ruRU', '', 'Она сказала, что идет в темное и страшное место. Интересно, где это?.. Брр... Не люблю темные места.', 28153),
(136464, 'ruRU', '', 'Ура! Мама говорила про сделку с Бвонсамди. Наверняка она все еще где-то в храме.', 28153),
(136463, 'ruRU', 'Разгаджи попросил меня вызвать тебя на дуэль.', 'Разгаджи попросил меня вызвать тебя на дуэль.', 28153),
(136462, 'ruRU', 'Лучше следи за собой. Я не очень-то люблю чужаков.', 'Лучше следи за собой. Я не очень-то люблю чужаков.', 28153),
(136461, 'ruRU', 'Спроси, что привело меня в Вол\'дун, и я дам тебе список кладбищ, которые стоит посетить...', 'Спроси, что привело меня в Вол\'дун, и я дам тебе список кладбищ, которые стоит посетить...', 28153),
(136460, 'ruRU', 'Разворачивайся и уходи отсюда. Считаю до трех... Три!', 'Разворачивайся и уходи отсюда. Считаю до трех... Три!', 28153),
(136459, 'ruRU', 'Не видишь, я тренируюсь? Получай!', 'Не видишь, я тренируюсь? Получай!', 28153),
(136458, 'ruRU', 'Рокхан, я пришел помочь тебе и принцессе Таланджи изучить Назмир.', 'Рокхан, я пришла помочь тебе и принцессе Таланджи изучить Назмир.', 28153),
(136457, 'ruRU', 'У нас приказ принцессы Таланджи. Нам нужны терродактили, чтобы добраться до Назмира.', '', 28153),
(136453, 'ruRU', '', 'Захватите город любой ценой. Я прибуду вскоре, чтобы лично осмотреть руины.', 28153),
(136451, 'ruRU', '', 'Там, в гробнице, есть реликвия, которая может пригодиться для наших ритуалов.', 28153),
(136450, 'ruRU', '', 'В Лощине Лучников местные шахтеры натолкнулись на неизведанные руины в недрах Старокаменной шахты.', 28153),
(136449, 'ruRU', '', 'Сестры ковена, слушайте меня.', 28153),
(136448, 'ruRU', '', 'Я уже потеряла там двух людей. Смотри не повтори их судьбу.', 28153),
(136447, 'ruRU', '', 'Не знаю, что там, но магия, которую источает это место, будто вытягивает жизненную силу.', 28153),
(136446, 'ruRU', '', 'Дружеский совет, |3-6($c). Держись подальше от шахты.', 28153),
(136445, 'ruRU', '', 'Все сели в лодку. Если повезет, они доберутся до Листопадной Бухты в целости.', 28153),
(136444, 'ruRU', '', 'Похоже, они послали самого здорового! Приготовьтесь, ребята!', 28153),
(136443, 'ruRU', '', 'Из города снова наступают! Держать строй!', 28153),
(136442, 'ruRU', '', 'Нас атакуют! Защищайте мирных жителей!', 28153),
(136441, 'ruRU', '', '$C, помоги стражам. Убивай все, что движется со стороны города!', 28153),
(136440, 'ruRU', '', 'Охраняйте дорогу, чтобы жители не пострадали при эвакуации.', 28153),
(136439, 'ruRU', '', 'Надеюсь, вслед за тобой придет целая армия.', 28153),
(136438, 'ruRU', '', 'Слышали, ребята? Нам помогут отбить город!', 28153),
(136437, 'ruRU', '', 'Просто поверь мне: эти жуткие плетеные существа здесь не для отвода глаз.\n\nВсе началось несколько недель назад с пропажи пары шахтеров. А потом вдруг стали появляться големы и утаскивать жителей из города. Тогда как раз Уэйкрестова дочка тут ошивалась. Но когда она уехала, дела пошли еще хуже.\n\nЭти твари уже все заполонили, да к тому же забрали большинство горожан. Нам с горсткой добровольцев удалось удержать эту позицию, но как мы должны отбить город? Ума не приложу.\n\nТак что если не собираешься помогать, просто иди своей дорогой.', 28153),
(136436, 'ruRU', 'Я хочу помочь.', 'Я хочу помочь.', 28153),
(136435, 'ruRU', 'Что здесь происходит?', 'Что здесь происходит?', 28153),
(136434, 'ruRU', '', 'С тех пор как эти кошмарные существа хлынули из шахты, весь наш город в огромной опасности. \n\nНадеюсь, тебе больше повезет в поисках источника этой проблемы, чем нам.', 28153),
(136432, 'ruRU', 'Я помогу тебе найти маму.', 'Я помогу тебе найти маму.', 28153),
(136431, 'ruRU', 'Я долго терпел.', 'Я долго терпела.', 28153),
(136430, 'ruRU', '', 'Без мамы так одиноко, так одиноко.$b$bПомоги мне ее найти! Ну пожалуйста! Обещаю, что буду паинькой.', 28153),
(136429, 'ruRU', '', 'Мама велела мне ждать ее здесь. Я жду уже целую вечность, а она все не возвращается!$b$bЯ уже устала ждать. Я хочу к маме!', 28153),
(136428, 'ruRU', 'Что ты здесь делаешь?', 'Что ты здесь делаешь?', 28153),
(136427, 'ruRU', '', 'Где моя мама? Я хочу домой!', 28153),
(136426, 'ruRU', '', 'Куда подевалась мама? Она ушла так давно.', 28153),
(136425, 'ruRU', '', 'Здесь так холодно... где мама?', 28153),
(136422, 'ruRU', 'Еще кто-то собрался в Назмир? Никто из вас оттуда не вернется, уж поверь мне.', '', 28153),
(136421, 'ruRU', '', 'Хм... Ни слова больше. Я отправляюсь в Назмир. Надеюсь, мы сможем догнать принцессу.', 28153),
(136420, 'ruRU', 'Таланджи уже в Назмире? Тогда мне лучше поторопиться. Встретимся там.', '', 28153),
(136419, 'ruRU', '', 'Из Соколиного Холма несколько дней не было вестей. Надо спешить.', 28153),
(136418, 'ruRU', '', 'Д-думаю, я смогу пробраться в пещеру к моей сестре. Встретимся там.', 28153),
(136417, 'ruRU', '', 'Я отправляюсь в Назмир. Увидимся!', 28153),
(136415, 'ruRU', 'В Вол\'дуне сложно достать качественные ингредиенты, но если глотать не жуя и с закрытыми глазами, то все не так плохо, как кажется!', '', 28153),
(136414, 'ruRU', 'Если хочешь узнать об альпаках, то ты как раз по адресу! Я знаю все, что можно знать, и даже больше.', '', 28153),
(136413, 'ruRU', 'Вол\'дун, конечно, пустынен и недружелюбен, но это мой дом.', '', 28153),
(136407, 'ruRU', 'Мы собираемся туда, куда по собственной воле не сунется ни один зулдазарец. Приготовься.', '', 28153),
(136406, 'ruRU', 'КРУШИТЬ!', '', 28153),
(136405, 'ruRU', 'Еще я привел чужака, желающего говорить с тобой, великий лоа.', '', 28153),
(136404, 'ruRU', 'Идем, скорее.', '', 28153),
(136403, 'ruRU', 'А, знакомый голос. И подарки, как мило. Входите, входите!', '', 28153),
(136402, 'ruRU', 'Повозка движется! Пришлите подкрепление!', '', 28153),
(136398, 'ruRU', 'Моя кожа! Горячо!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(136397, 'ruRU', 'А-а-а-а-а-а-а-а-а!', '', 28153),
(136396, 'ruRU', 'О великий Бвонсамди! Барабан бьет в твою честь! Дары ждут тебя!', '', 28153),
(136395, 'ruRU', 'Доба кужу та тобу! Мета бо чу!', '', 28153),
(136394, 'ruRU', 'Хорошо. Теперь бей в барабан!', '', 28153),
(136393, 'ruRU', 'Видение покажет тебе, как начертить ритуальный круг. Постарайся не ошибаться, Бвонсамди это не нравится.', '', 28153),
(136388, 'ruRU', 'Все, с халтурой разобрались? Может, пора бы уже <ик> заняться делом?', '', 28153),
(136387, 'ruRU', 'Ядовитые жала? Уверен, они нужны для самых благородных целей.', '', 28153),
(136386, 'ruRU', 'Эй, тут опасно! <ик> Не отходи далеко!', '', 28153),
(136385, 'ruRU', 'Ладно... Могу подождать.', '', 28153),
(136384, 'ruRU', '<Ик> Эй, я здесь!', '', 28153),
(136383, 'ruRU', 'Эй, чего стоим, кого ждем?!', '', 28153),
(136382, 'ruRU', '<ик> Привет, ящерка.', '', 28153),
(136380, 'ruRU', 'Клинки к бою! Лок\'тар огар!', '', 28153),
(136379, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [300] Выкопать туннель', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [300] Выкопать туннель', 28153),
(136378, 'ruRU', 'Эй, ты! Дай-ка расскажу о передовых технологиях, которые пригодятся тебе на фронте.\n\nТуннели.\n\nНет, тебе не послышалось. Всего за одну огромную кучу золота мы с напарником выроем для тебя и твоих соратников туннель на передовую. Что скажешь?', '', 28153),
(136377, 'ruRU', 'Народец тут суровый, так что говорить <ик> буду я.', '', 28153),
(136376, 'ruRU', 'А вот и она. Вольная Гавань.', '', 28153),
(136375, 'ruRU', 'Хм-м. В прошлый раз шли направо... значит, нам налево. Вроде, в голове проясняется.', '', 28153),
(136374, 'ruRU', '', 'Нужно вернуть сферу в лагерь, пока сетраки не поняли, что она пропала! Скорее!', 28153),
(136373, 'ruRU', 'Ага. Мы уже близко, нутром чую.', '', 28153),
(136372, 'ruRU', 'Уфф, ну и прогулочка. Надо бы еще поддать...', '', 28153),
(136371, 'ruRU', 'Ч-что? Ты кто? А это еще что?', 'Ч-что? Ты кто? А это еще что?', 28153),
(136370, 'ruRU', 'И эта штука подчинила мой мозг?!', 'И эта штука подчинила мой мозг?!', 28153),
(136369, 'ruRU', 'Ага, знакомое место. Похоже... кхм... мы на верном пути.', '', 28153),
(136368, 'ruRU', 'Ч-что? Что случилось?', 'Ч-что? Что случилось?', 28153),
(136367, 'ruRU', 'Ук наггва... наш хозяин... придет за тобой...', 'Ук наггва... наш хозяин... придет за тобой...', 28153),
(136366, 'ruRU', 'Слишком поздно! Волна уже близко, и вам ее не остановить!', 'Слишком поздно! Волна уже близко, и вам ее не остановить!', 28153),
(136365, 'ruRU', 'Хорошо пошла. Ладно, двигаем.', '', 28153),
(136364, 'ruRU', 'Черт, башка еще трещит. Надо выпить, чтобы лучше думалось.', '', 28153),
(136363, 'ruRU', 'Не, не. ТОЧНО помню – направо.', '', 28153),
(136362, 'ruRU', '<ик> Так, а куда дальше?.. Налево?', '', 28153),
(136361, 'ruRU', 'Шепот... заполнил мой разум...', 'Шепот... заполнил мой разум...', 28153),
(136360, 'ruRU', 'Отдаю душу морю...', 'Отдаю душу морю...', 28153),
(136359, 'ruRU', 'И\'за кам иикзз...', 'И\'за кам иикзз...', 28153),
(136358, 'ruRU', 'Твое любопытство завело тебя слишком далеко!', 'Твое любопытство завело тебя слишком далеко!', 28153),
(136357, 'ruRU', 'Твое сердце будет идеальным подношением!', 'Твое сердце будет идеальным подношением!', 28153),
(136356, 'ruRU', 'Я отдаюсь этой силе без остатка!', 'Я отдаюсь этой силе без остатка!', 28153),
(136350, 'ruRU', '%s следует за вами.', '', 28153),
(136349, 'ruRU', '%s устает следовать за вами и сбегает.', '', 28153),
(136348, 'ruRU', '', 'С бухтой разобрались, теперь можно заняться и пещерой.', 28153),
(136347, 'ruRU', 'Свечи расставлены, подношения готовы. Теперь надо начертить круг.', '', 28153),
(136346, 'ruRU', 'Самоцвет призывателя небес переполняет энергия! Кто знает, что может случиться, если вы решите использовать его в таком состоянии.', 'Самоцвет призывателя небес переполняет энергия! Кто знает, что может случиться, если вы решите использовать его в таком состоянии.', 28153),
(136345, 'ruRU', 'За Орду!', '', 28153),
(136341, 'ruRU', 'Начнем же.', 'Начнем же.', 28153),
(136340, 'ruRU', 'Мы оросим эти земли кровью наших врагов.', '', 28153),
(136327, 'ruRU', '', 'Берегись!', 28153),
(136326, 'ruRU', '', 'Берегись!', 28153),
(136325, 'ruRU', 'Думаю... я готов. Еще не поздно все исправить.', '', 28153),
(136324, 'ruRU', 'Попросить Фозрука напасть на Гнездо.', 'Попросить Фозрука напасть на Гнездо.', 28153),
(136323, 'ruRU', 'Попросить Фозрука напасть на дорогу Храброгласа.', 'Попросить Фозрука напасть на дорогу Храброгласа.', 28153),
(136322, 'ruRU', 'Попросить Фозрука напасть на Стромгард.', 'Попросить Фозрука напасть на Стромгард.', 28153),
(136321, 'ruRU', '<Фозрук взирает на вас сверху вниз.>', '', 28153),
(136320, 'ruRU', 'С удовольствием.', '', 28153),
(136319, 'ruRU', 'Я разорву тебя на куски!', '', 28153),
(136318, 'ruRU', 'Неразумное существо... придут другие... и заберут у тебя камень...', '', 28153),
(136317, 'ruRU', 'Мы откроем истинную силу самоцвета призывателя небес, и ты нас не остановишь!', '', 28153),
(136316, 'ruRU', 'Пустыня будет расти!', '', 28153),
(136315, 'ruRU', 'Назмир будет принадлежать сетракам!', '', 28153),
(136314, 'ruRU', 'Эту землю поглотят пески!', '', 28153),
(136313, 'ruRU', 'Вы будете следующими!', '', 28153),
(136312, 'ruRU', 'Наша власть нерушима!', '', 28153),
(136311, 'ruRU', 'Эти болота не будут прежними!', '', 28153),
(136310, 'ruRU', 'Мы будем править всеми!', '', 28153),
(136309, 'ruRU', 'Пустыня поглотит эти земли!', '', 28153),
(136297, 'ruRU', 'ТЫ ЧУДОВИЩЕ!', '', 28153),
(136296, 'ruRU', 'Это... Это была любовь всей моей жизни!', '', 28153),
(136295, 'ruRU', 'Серьезно?.. Меня разрубили надвое сетраки? Нет, так дело не пойдет.', '', 28153),
(136292, 'ruRU', 'Я дарую тебе благословение моря! Пусть оно примет тебя как друга и заключит в свои заботливые объятья.', '', 28153),
(136291, 'ruRU', 'Ксибала... заставит тебя страдать...', '', 28153),
(136290, 'ruRU', 'Это – священный храм Ксибалы. Он с радостью примет в свою коллекцию еще одну душу!', '', 28153),
(136278, 'ruRU', 'Этот мир утонет... ак яр ки\'лвхук х\'ивн...', 'Этот мир утонет... ак яр ки\'лвхук х\'ивн...', 28153),
(136277, 'ruRU', 'Слишком поздно! Вам нас не остановить!', 'Слишком поздно! Вам нас не остановить!', 28153),
(136276, 'ruRU', 'Ифис шуул ки\'нук иикзз...', '', 28153),
(136275, 'ruRU', 'Брэннон Штормсонг – слабый юнец! Истинная сила принадлежит морю!', '', 28153),
(136274, 'ruRU', 'Элби? Что происходит? Где лорд Штормсонг?', '', 28153),
(136273, 'ruRU', 'Если я скажу, ты не поверишь, Терольд. Это просто катастрофа.', '', 28153),
(136272, 'ruRU', 'Тише! Леди Сильвана будет недовольна, если мы провалим задание.', '', 28153),
(136271, 'ruRU', 'Такер! Нетрудно догадаться. По крайней мере, он заплатил за свою некомпетентность.', '', 28153),
(136270, 'ruRU', 'Это был Такер. Его сетраки убили первым.', '', 28153),
(136269, 'ruRU', 'Мы должны были предвидеть нападение. Кто стоял на стреме?', '', 28153),
(136268, 'ruRU', '', 'В этом нет нашей вины, босс, ведь на нас напали те, кого не должно было здесь быть.', 28153),
(136267, 'ruRU', 'Мы должны сделать все как надо, Ингрид.', '', 28153),
(136266, 'ruRU', '', 'Она когда-нибудь бывает довольна, босс?', 28153),
(136265, 'ruRU', 'Ладно, пора идти! Нам нужно хорошенько разведать это место и при этом не угодить в засаду, как в прошлый раз.', '', 28153),
(136264, 'ruRU', '<Кажется, что темный идол вышел из поля вашего зрения. Но если смотреть прямо на него, он остается неподвижным. Игра света? Вы так не думаете.>', '', 28153),
(136263, 'ruRU', '', 'Ну же!', 28153),
(136262, 'ruRU', 'Это секретная информация...', '', 28153),
(136261, 'ruRU', '', 'А когда тебя разрезали надвое впервые?', 28153),
(136260, 'ruRU', 'Меня уже не в первый раз надвое разрезают. Надеюсь, что в последний.', '', 28153),
(136259, 'ruRU', 'Не каждый раз, но можем.', '', 28153),
(136258, 'ruRU', '', 'Э-э... Клейтон, мы же нежить – и, конечно, выживем, если нас разрезать надвое.', 28153),
(136257, 'ruRU', 'Босс, как тебе удалось выжить? Я сам видел, как тебя разрезали надвое.', '', 28153),
(136256, 'ruRU', '', 'Удачи там с самоцветом! После ритуала он... почти как новенький.', 28153),
(136255, 'ruRU', 'Черви, вгрызающиеся в лицо? Пойду-ка я отсюда!', 'Черви, вгрызающиеся в лицо? Пойду-ка я отсюда!', 28153),
(136254, 'ruRU', 'Как руководство допускает такое? Хватит, пора нам создать профсоюз.', 'Как руководство допускает такое? Хватит, пора нам создать профсоюз.', 28153),
(136253, 'ruRU', 'Мне все равно пора передохнуть. Я сматываю удочки.', 'Мне все равно пора передохнуть. Я сматываю удочки.', 28153),
(136252, 'ruRU', 'Я заберусь повыше. Пусть остальные найдут меня там.', '', 28153),
(136251, 'ruRU', 'Я уже привык к грузам с частями тела разных монстров, но чтобы целые монстры... Нет уж, увольте.', 'Я уже привыкла к грузам с частями тела разных монстров, но чтобы целые монстры... Нет уж, увольте.', 28153),
(136250, 'ruRU', 'Вставь вот эту часть сюда...', '', 28153),
(136249, 'ruRU', '', 'Встретимся на другой стороне упаковочной зоны. Посмотрю, что там творится в городе.', 28153),
(136248, 'ruRU', '', 'Что тут... Что... Что это ТАКОЕ?!', 28153),
(136243, 'ruRU', '', '\"Не экспериментируй с темной магией\", – говорили они.$B$B\"Если продолжишь, обречешь на гибель весь Азерот\", – предупреждали они.$B$B\"Сейчас же отдай, это тебе не ингредиент!\" – кричал он, когда я оторвала ему руку.$B$BОй, прости, воспоминания нахлынули!', 28153),
(136242, 'ruRU', 'Ясно. Большинством голосов решено, что мы остаемся наблюдать за светопреставлением.', '', 28153),
(136241, 'ruRU', 'Я против.', '', 28153),
(136240, 'ruRU', 'Я против.', '', 28153),
(136239, 'ruRU', '...а кто против?', '', 28153),
(136238, 'ruRU', 'Я за.', '', 28153),
(136237, 'ruRU', 'Лучше мне тоже туда отправиться и проследить, чтобы все было сделано как надо.', '', 28153),
(136236, 'ruRU', '', 'Я за.', 28153),
(136235, 'ruRU', '', 'Я за.', 28153),
(136234, 'ruRU', 'Давайте проголосуем. Кто за то, чтобы остаться на болотах, полных опасностей, и посмотреть, как кто-то другой убивает змеелюдей с помощью самоцвета?', '', 28153),
(136233, 'ruRU', '', 'Да ладно тебе, Чадвик! Мы можем поджарить их с помощью самоцвета призывателя небес – $n его скоро принесет!', 28153),
(136232, 'ruRU', 'Мы с моими магами встретим тебя там, наверху.', '', 28153),
(136231, 'ruRU', 'Не думал встретить здесь товарища. Благодарю за спасение. Ингрид уже рассказала тебе о своем плане?', '', 28153),
(136230, 'ruRU', 'Зря мы отправились в такое опасное место без надлежащей подготовки...', '', 28153),
(136229, 'ruRU', '', 'Я пойду, а ты разберись тут со всем. А потом посмотрим, на что способен этот камушек!', 28153),
(136228, 'ruRU', 'Спасибо за помощь. Эти сетраки пришли в Назмир в поисках какой-то темной магии. Об их целях можно только догадываться.', '', 28153),
(136227, 'ruRU', '', 'Какое облегчение. Эти сетраки ищут какую-то магию, способную пробудить силу одного артефакта.', 28153),
(136226, 'ruRU', 'Все грузы приходят нормально?', 'Все грузы приходят нормально?', 28153),
(136225, 'ruRU', 'А-а-а! Сними с меня эту дрянь!', '', 28153),
(136224, 'ruRU', 'Тварь!', 'Тварь!', 28153),
(136223, 'ruRU', 'Он убил Кен\'ная! Скотина!', 'Он убил Кен\'ная! Скотина!', 28153),
(136222, 'ruRU', 'Возможно, у нас проблема. Берегись!', '', 28153),
(136221, 'ruRU', 'Я как раз только что получил груз! Хочешь взглянуть?', '', 28153),
(136220, 'ruRU', '', 'Я уже несколько дней не видела младшего Штормсонга. Мне бы хотелось, чтобы нашим городом правил кто-нибудь помудрее, но кто я такая, чтобы жаловаться?', 28153),
(136219, 'ruRU', 'Здесь происходило что-нибудь странное?', 'Здесь происходило что-нибудь странное?', 28153),
(136218, 'ruRU', 'Я уже несколько дней не получал свежих ингредиентов! Как мне готовить своего знаменитого жареного жесткозуба, если у меня нет свежих плавников?', '', 28153),
(136215, 'ruRU', 'Пора показать этим сетракам, что такое настоящая боль.', '', 28153),
(136212, 'ruRU', 'Вот так! Неплохо, тебе уже приходилось делать это раньше?', '', 28153),
(136211, 'ruRU', 'Ай! Нет, продолжай – это всегда немного больно. Только поверни чуть-чуть...', '', 28153),
(136210, 'ruRU', 'Осторожнее с моими ногами – они болтаются, если их отсоединить.', '', 28153),
(136207, 'ruRU', 'Эй! А ну отдай!', '', 28153),
(136206, 'ruRU', '', 'Уберите этих сауридов из моей таверны!', 28153),
(136205, 'ruRU', '', 'Что? Чего тебе надо?', 28153),
(136200, 'ruRU', 'Будет исполнено.', '', 28153),
(136199, 'ruRU', 'Генн, прикрывай нас с тыла. Отправлять все войска через один проход слишком рискованно. Уверен, Сильвана подготовила для нас ловушки.', '', 28153),
(136198, 'ruRU', '', 'Вперед!', 28153),
(136197, 'ruRU', 'Всем войскам – занять позиции! Атакуем по моей команде!', '', 28153),
(136196, 'ruRU', 'Верно. У Сильваны было немного времени на подготовку к нашему нападению, но мы не должны ее недооценивать.', '', 28153),
(136194, 'ruRU', 'Тебе не бросалось в глаза ничего необычного?', 'Тебе не бросалось в глаза ничего необычного?', 28153),
(136193, 'ruRU', 'Что-нибудь нужно?', '', 28153),
(136192, 'ruRU', '', 'Да. Чем могу помочь?', 28153),
(136191, 'ruRU', 'Добро пожаловать! Хочешь чего-нибудь поесть?', '', 28153),
(136187, 'ruRU', 'Протянешь товарищу руку помощи? Точнее, ногу – рук у меня пока хватает.', '', 28153),
(136179, 'ruRU', 'Пришла пора показать псам Альянса, на что способна Орда!', '', 28153),
(136178, 'ruRU', 'Наших волков с детства тренируют и готовят к бою.', '', 28153),
(136177, 'ruRU', 'Болтать нет времени! У нас много работы.', '', 28153),
(136176, 'ruRU', '', 'Да? Чем могу помочь?', 28153),
(136170, 'ruRU', 'Джайна! Хвала Свету, вы здесь! Нам вас отчаянно не хватало.', '', 28153),
(136169, 'ruRU', '', 'Раньше Кел\'вакс был нашим сыном, но теперь он ничуть не лучше любого монстра. Уничтожь его, чтобы мы смогли отправить его душу Бвонсамди.', 28153),
(136167, 'ruRU', '', 'Кел\'вакс хочет совершить то. что Бвонсамди считает самым гнусным. Найди филактерии, и мы положим этому конец.', 28153),
(136166, 'ruRU', '', 'Помоги нам очистить древнее святилище Бвонсамди. Только представь, каким величественным было это место когда-то...', 28153),
(136165, 'ruRU', '', 'Погоди... тут кто-то есть... и это не тролль крови! Эй, сюда!', 28153),
(136164, 'ruRU', '', 'Мои создания... нельзя победить...', 28153),
(136163, 'ruRU', '', 'Эти души – мои!', 28153),
(136162, 'ruRU', 'Так мы никогда не расчистим это место для Бвонсамди.', '', 28153),
(136161, 'ruRU', '', 'А, вот и ты! Мутумба мне все рассказала. Похоже, вам выпало то еще приключение.', 28153),
(136160, 'ruRU', '', 'При жизни я хранила эти леса от зла. Я не позволю каким-то ведьмам использовать меня!', 28153),
(136159, 'ruRU', 'Так... прекрасна...', '', 28153),
(136156, 'ruRU', '', 'Тише. Твои раны очень плохи.', 28153),
(136153, 'ruRU', 'Мы готовы отправиться в путь.', 'Мы готовы отправиться в путь.', 28153),
(136152, 'ruRU', '', 'В дюнах опасно путешествовать в одиночку.', 28153),
(136151, 'ruRU', 'Я защищал эти земли, пока был жив.\n\nИ даже смерть меня не остановит.', '', 28153),
(136150, 'ruRU', '', 'До встречи на Той Стороне.', 28153),
(136149, 'ruRU', 'Воля Бвонсамди исполнилась. Пора нам отправиться на покой.', '', 28153),
(136148, 'ruRU', 'Нет! Я не вижу Бвонсамди, я не хочу... прошу, не надо!', '', 28153),
(136147, 'ruRU', '', 'Пусть Бвонсамди решит твою судьбу. Молись, чтобы он оказался более милосердным, чем мы.', 28153),
(136146, 'ruRU', 'Нет! Мама, помоги мне!', '', 28153),
(136145, 'ruRU', 'Слишком поздно, сын мой. Ты предал Бвонсамди. И должен за это заплатить.', '', 28153),
(136144, 'ruRU', 'Мама... Отец... Мне так жаль. Прошу, простите меня. Замолвите за меня слово перед Бвонсамди!', '', 28153),
(136141, 'ruRU', 'Я занимаюсь мертвыми.$b$b<Аллен пожимает плечами.>$b$bТем и живу.', '', 28153),
(136140, 'ruRU', '', 'Глупый лоа! Здесь ты найдешь лишь смерть!', 28153),
(136116, 'ruRU', 'Давай вернемся в мое логово.', '', 28153),
(136115, 'ruRU', 'Ха-ха! Наши противники бегут!', '', 28153),
(136114, 'ruRU', 'Бвонсамди! Нет... Г\'уун говорил, что никто не сможет меня победить!', '', 28153),
(136113, 'ruRU', 'Хватит паниковать! По моему опыту, существа, которыми нас пугают суеверия, на деле всегда оказываются не такими страшными, как во всех этих небылицах.', '', 28153),
(136112, 'ruRU', 'У меня плохое предчувствие... Будь осторожнее, $n!', '', 28153),
(136111, 'ruRU', 'Хорошо! Со смертью вождя им долго не протянуть. Попируем на их костях!', '', 28153),
(136110, 'ruRU', 'А-А! Будьте прокляты вы! Будь проклят Бвонсамди! Он НЕ ВОЗЬМЕТ МОЮ ДУШУ!', '', 28153),
(136109, 'ruRU', 'Кровавый бог получит ваши души!', '', 28153),
(136108, 'ruRU', 'Кел\'вакс снова уязвим... действуй!', '', 28153),
(136107, 'ruRU', 'Что... невозможно! Меня не сковать. Ни вам, ни Бвонсамди!', '', 28153),
(136106, 'ruRU', 'Пора предстать перед судом Бвонсамди. Мы добыли филактерии, а благодаря |3-2($n) у меня есть кости, которые победят твое вуду!', '', 28153),
(136105, 'ruRU', 'Мать, отец...', '', 28153),
(136104, 'ruRU', '', 'Кел\'вакс, хватит!', 28153),
(136103, 'ruRU', 'Ты будешь вечно страдать вместе с прочими слугами Бвонсамди!', '', 28153),
(136102, 'ruRU', 'ХВАТИТ! Кровавый бог требует твоей смерти... и я выполню его пожелание, будь проклят Бвонсамди!', '', 28153),
(136101, 'ruRU', 'Неважно. Я видел восход и закат цивилизации... Ты меня не остановишь!', '', 28153),
(136100, 'ruRU', 'Что? Где мои зомби... мои скелеты? Что происходит?', '', 28153),
(136099, 'ruRU', 'Глупое смертное существо... Моя армия тебя уничтожит. Ко мне, мои слуги!', '', 28153),
(136096, 'ruRU', 'Эй! Я тебя не узнаю. Ты здесь, чтобы помочь, или зачем?', '', 28153),
(136095, 'ruRU', 'Все, хватит. Довольно игр!', 'Все, хватит. Довольно игр!', 28153),
(136094, 'ruRU', '', 'Будь поосторожнее, когда лезешь в дела Эшвейнов. Они не церемонятся.', 28153),
(136093, 'ruRU', 'Неплохо для \"зайца\". Радуйся, что я тебя раньше не нашла, а то бы вздернула на рее.', 'Неплохо для \"зайца\". Радуйся, что я тебя раньше не нашла, а то бы вздернула на рее.', 28153),
(136092, 'ruRU', 'Ну держитесь, морские ведьмы! Я с вас шкуры спущу!', 'Ну держитесь, морские ведьмы! Я с вас шкуры спущу!', 28153),
(136086, 'ruRU', '', 'Когда-то мой отец правил железной рукой. Никто не отваживался нарушить его законы. Но он также был добрым правителем, который всегда помогал нуждающимся, и за это его любили.$b$bИ что теперь? Его железную руку позабыли. Доверенные слуги отравляют его слух своими речами, а сами тайно к чему-то готовятся.$b$bНе знаю, что они замышляют, но лучше не сидеть и не ждать, пока все выяснится само собой.', 28153),
(136085, 'ruRU', '', 'Дети, убейте это существо!', 28153),
(136072, 'ruRU', 'Вас захлестнет волна крови с севера. У вас не останется выбора, кроме как преклонить колени!', 'Вас захлестнет волна крови с севера. У вас не останется выбора, кроме как преклонить колени!', 28153),
(136071, 'ruRU', 'Скоро они придут сюда из Назмира, и вы все увидите то, что видели мы!', 'Скоро они придут сюда из Назмира, и вы все увидите то, что видели мы!', 28153),
(136070, 'ruRU', 'Нет! Нет! Тебе нас не остановить! Он сказал, что ты не сможешь.', 'Нет! Нет! Тебе нас не остановить! Он сказал, что ты не сможешь.', 28153),
(136069, 'ruRU', 'За твою кровь дадут хорошую цену.', 'За твою кровь дадут хорошую цену.', 28153),
(136068, 'ruRU', 'Ты ничего не скажешь страже, если я заставлю тебя замолчать навсегда.', 'Ты ничего не скажешь страже, если я заставлю тебя замолчать навсегда.', 28153),
(136067, 'ruRU', 'Ты думаешь, что можешь одолеть нас?', 'Ты думаешь, что можешь одолеть нас?', 28153),
(136039, 'ruRU', 'Что это? Почему мы бежим от врагов? Если ты мне не поможешь, я сражусь с ними в одиночку.', '', 28153),
(136015, 'ruRU', 'Похоже, бочка наполнена самыми обыкновенными и не представляющими угрозы частями тела монстров.', '', 28153),
(136003, 'ruRU', 'Пора покончить с этим! Встретимся на берегу реки.', '', 28153),
(135928, 'ruRU', '', 'Эта нежить – оскорбление для Бвонсамди. Нам не будет покоя, пока мы все не исправим.', 28153),
(135927, 'ruRU', 'Воля Бвонсамди должна быть исполнена. Иначе нам не будет покоя.', '', 28153),
(135904, 'ruRU', 'Приходи в мое логово. Нам многое предстоит сделать.', '', 28153),
(135903, 'ruRU', '', 'Нет! Прости меня, Краг\'ва.', 28153),
(135901, 'ruRU', 'Я сам решаю, кто достоин моей благосклонности. Ты посмеешь оспорить мой выбор?', '', 28153),
(135900, 'ruRU', '', 'О Краг\'ва! Это большая честь, но я ее не заслужила... Я не смогла остановить наг.', 28153),
(135898, 'ruRU', 'Нарез! Ты доказала, что достойна стать моей последовательницей.', '', 28153),
(135875, 'ruRU', '', 'Я останусь здесь и присмотрю за нагами, чтобы доказать, что я достойна быть избранницей Краг\'вы. Увидимся позже.', 28153),
(135874, 'ruRU', 'Ну уж нет! Я не позволю тебе помешать моему делу!', '', 28153),
(135869, 'ruRU', 'Показывай дорогу.', 'Показывай дорогу.', 28153),
(135868, 'ruRU', 'Ты здесь недавно? Ты кто вообще?$b$bМистер Доб\'ряк будет недоволен – сперва тебе следовало поговорить с ним. Пошли.', '', 28153),
(135865, 'ruRU', '', 'А мне сказали, что я дура, когда я решила оставить такой \"узкоспециализированный\" свиток. Пф!', 28153),
(135861, 'ruRU', '%s умирает от ран.', '%s умирает от ран.', 28153),
(135843, 'ruRU', '', 'Злобогрызы... я только хотела сделать... еще... один...', 28153),
(135842, 'ruRU', '', 'Твоя сила наполнит мои тотемы!', 28153),
(135795, 'ruRU', '<В грязи лежит мертвая гигантская лягушка.>', '', 28153),
(135777, 'ruRU', 'Врассыпную!', '', 28153),
(135776, 'ruRU', 'А-а-а!', '', 28153),
(135774, 'ruRU', 'Бежим!', '', 28153),
(135772, 'ruRU', 'Ой!', '', 28153),
(135771, 'ruRU', 'Я пожалуюсь на тебя Мистеру Доб\'ряку!', '', 28153),
(135770, 'ruRU', 'Мне это было нужно!', '', 28153),
(135769, 'ruRU', 'А! Здесь чужак! Осторожно!', '', 28153),
(135768, 'ruRU', 'Мистеру Доб\'ряку это не понравится!', '', 28153),
(135741, 'ruRU', 'Что?', 'Что?', 28153),
(135740, 'ruRU', '$R что-то хочет сказать знахарю?', '', 28153),
(135733, 'ruRU', 'Он ошибался. Конечно, нам пришлось несладко, но Зул сбежал с нашим флотом и развязал несколько войн. Те, кто остались, все пережили. Мы вновь отстроили свои дома. Потому что именно так и должны поступать зандалары.', '', 28153),
(135732, 'ruRU', 'Видения Зула, тьфу! Он тебе не говорил, как предсказывал, что весь Зандалар будет скрыт под водой?', '', 28153),
(135726, 'ruRU', 'Я слежу за сотнями судов в этом порту и забочусь о том, чтобы грузы прибывали своевременно.$b$bГовори быстрее – у меня мало времени.', '', 28153),
(135719, 'ruRU', '', 'Давай.', 28153),
(135701, 'ruRU', 'О Ксибале сложено множество легенд, но я понятия не имею, каким из них стоит верить. Древние его боялись, это точно.\n\nГоворят, он мог сделать так, что кого-нибудь раздует от гноя!\n\nИли там: кто на него посмотрит, превращается в живого скелета.\n\nИли вот еще: он скрывался в тенях и выходил из них ночью, чтобы пожирать спящих.\n\nЕще говорят, что он поджидал кого-нибудь у дороги и заставлял путников харкать кровью до тех пор, пока они не умирали. \n\nДаже самые отчаянные храбрецы сторонятся этого места.', '', 28153),
(135699, 'ruRU', 'Кто это – Ксибала?', 'Кто это – Ксибала?', 28153),
(135694, 'ruRU', '', 'Д-думаю, я смогу пробраться в пещеру к моей сестре. Встретимся там.', 28153),
(135683, 'ruRU', 'Что тебе здесь надо?', '', 28153),
(135680, 'ruRU', 'Мы готовы начать испытания.', 'Мы готовы начать испытания.', 28153),
(135679, 'ruRU', 'Пытаться задержать суд бесполезно. Мы все равно скоро узнаем всю правду о мисс Уэйкрест!', '', 28153),
(135674, 'ruRU', 'Хоть виверны и пали, но наши руки еще способны держать топор!', '', 28153),
(135673, 'ruRU', 'С артиллерией или без, нам нет равных!', '', 28153),
(135670, 'ruRU', 'Мои клинки разрубят вашу плоть!', '', 28153),
(135638, 'ruRU', 'Эти мерзавцы убили моего последнего служителя. Я обрушу на них ярость десяти тысяч лет!', '', 28153),
(135610, 'ruRU', '', 'Эта платформа доставит тебя в нижний зал, Таланджи уже ждет тебя там. Только под ноги смотри.', 28153),
(135604, 'ruRU', '', 'Пойдем. Я покажу тебе, как проще всего спуститься.', 28153),
(135586, 'ruRU', '', 'Навести меня, как представится возможность. Мне не терпится поделиться с тобой информацией с этих гравюр!', 28153),
(135579, 'ruRU', '', 'Не беспокойся обо мне... Я смогу вернуться на арену и в одиночку.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(135578, 'ruRU', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Язма начинает применять заклинание |cFFFF0404|Hspell:249924|h[Раздирание души]|h|r к |cFFFF0000|3-2($n)|r!', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Язма начинает применять заклинание |cFFFF0404|Hspell:249924|h[Раздирание души]|h|r к |3-2($n)!', 28153),
(135577, 'ruRU', 'Силы возвращаются ко мне... Кажется, противоядие действует.', '', 28153),
(135576, 'ruRU', 'Не знаю, сколько еще протянет Джулваба... противоядие – ее единственная надежда.', '', 28153),
(135574, 'ruRU', 'Мы не видели Джулвабу и Таз\'джина уже несколько дней. Я начинаю за них беспокоиться...', '', 28153),
(135565, 'ruRU', 'Скорее, идем. Чтобы спасти последователей Краг\'вы, нужно убить наг.', '', 28153),
(135555, 'ruRU', '', 'Да пребудет с тобой благословение Краг\'вы. Покажи Залдраксии, что бывает, когда переходишь дорогу лоа.', 28153),
(135539, 'ruRU', 'Наг необходимо остановить, а обо мне не беспокойся.', '', 28153),
(135511, 'ruRU', 'Отведи меня к королю Растахану.', 'Отведи меня к королю Растахану.', 28153),
(135496, 'ruRU', 'На наш город напали!', 'На наш город напали!', 28153),
(135492, 'ruRU', 'Я отправлю несколько рабочих на выработку этой жилы.', '', 28153),
(135486, 'ruRU', 'На шахту напали!', 'На шахту напали!', 28153),
(135469, 'ruRU', '', 'В чем дело?', 28153),
(135466, 'ruRU', 'Негодный свиток... Давай уже работай и найди мне Шоака!', '', 28153),
(135465, 'ruRU', 'Эй! Я хочу, чтобы ты мне нашел Шоака, а не отскакивал от этого тотема!', '', 28153),
(135464, 'ruRU', 'Да работай уже! Найди мне Шоака!', '', 28153),
(135457, 'ruRU', '', 'Не исключен сопутствующий ущерб, но думаю, со временем мы соберем кусочки воедино. Возможно, нам понадобятся еще лаборанты...', 28153),
(135456, 'ruRU', 'Духам это не понравится. И не говори, что я тебя не предупреждал!', '', 28153),
(135455, 'ruRU', 'Эй! Постарайся не сбрасывать бомбы на кости!', '', 28153),
(135446, 'ruRU', '', 'Умри, чужак!', 28153),
(135445, 'ruRU', '', 'Ты будешь служить нам!', 28153),
(135444, 'ruRU', '', 'Нет... У меня должно было получиться!', 28153),
(135443, 'ruRU', '', 'Нет... Мне обещали... силу...', 28153),
(135442, 'ruRU', '', 'Ты будешь молить о смерти!', 28153),
(135441, 'ruRU', '', 'Ты станешь рабом!', 28153),
(135440, 'ruRU', '', 'Тебе меня не остановить!', 28153),
(135439, 'ruRU', 'Я отдам твое сердце госпоже!', '', 28153),
(135432, 'ruRU', 'Альянс захватил пласт азерита!', '', 28153),
(135431, 'ruRU', '$n защищает пласт азерита!', '', 28153),
(135430, 'ruRU', 'Орда захватила пласт азерита!', '', 28153),
(135429, 'ruRU', '$n захватывает пласт азерита!', '', 28153),
(135405, 'ruRU', 'Так и быть. Но знай, я буду требовать у короля голову этого отродья.', '', 28153),
(135400, 'ruRU', 'Довольно. Генерал, пропусти их. Этому слуге Орды удалось пройти испытания двух племен. По закону ты должен освободить путь.', '', 28153),
(135399, 'ruRU', '', '', 28153),
(135388, 'ruRU', 'Говорят, король не вставал с трона с того самого дня, как умерла его жена.', 'Говорят, король не вставал с трона с того самого дня, как умерла его жена.', 28153),
(135387, 'ruRU', 'Орда? Здесь, в Зулдазаре? Это плохо. Это очень плохо.', 'Орда? Здесь, в Зулдазаре? Это плохо. Это очень плохо.', 28153),
(135386, 'ruRU', 'Зул забрал с собой много наших. А сейчас говорят, что тролли крови нападают на наши северные границы.', 'Зул забрал с собой много наших. А сейчас говорят, что тролли крови нападают на наши северные границы.', 28153),
(135385, 'ruRU', '', 'Ох... боюсь, я вынуждена просить тебя еще об одном одолжении.', 28153),
(135384, 'ruRU', 'Тогда нам придется подождать.', '', 28153),
(135383, 'ruRU', '', 'На это уйдут недели!', 28153),
(135382, 'ruRU', 'C вас снимут обвинения, только когда мы узнаем, что на самом деле случилось с Лощиной Лучников.', '', 28153),
(135381, 'ruRU', '', 'Что?! После всего, что я вытерпела?..', 28153),
(135380, 'ruRU', 'Меня вы не убедили. Это не объясняет произошедшего.', '', 28153),
(135379, 'ruRU', 'Тихо! Здесь я выношу вердикт!', '', 28153),
(135378, 'ruRU', 'Может, она и впрямь не ведьма! Но как же наш город?', 'Может, она и впрямь не ведьма! Но как же наша деревня?', 28153),
(135377, 'ruRU', 'Ее стошнило! Это невозможно!', '', 28153),
(135376, 'ruRU', '', 'Ох... меня сейчас...', 28153),
(135375, 'ruRU', '', 'Придется. Давай сюда яд.', 28153),
(135374, 'ruRU', 'Мисс Уэйкрест, вы готовы доказать нам обратное?', '', 28153),
(135373, 'ruRU', 'Всем известно, что ведьма черпает силы не из обычной людской пищи, а из душ своих жертв. Ее нутро всегда пусто.', '', 28153),
(135372, 'ruRU', 'Интересно, но выводы делать рано. Впереди последнее испытание... очищение чрева.', '', 28153),
(135371, 'ruRU', 'Насекомые ее вовсе не избегают. Даже кусаются больше обычного!', 'Насекомые ее вовсе не избегают. Даже кусаются больше обычного!', 28153),
(135370, 'ruRU', '', 'Ай! Ой... Больно!', 28153),
(135369, 'ruRU', '', 'Не волнуйся за меня. Пару укусов я переживу.', 28153),
(135368, 'ruRU', 'Выпускайте мошек! Ее нечестивая плоть отгонит их, как дым!', '', 28153),
(135367, 'ruRU', 'Следующее испытание – укусы насекомых. Известно, что даже ненасытные кровомошки не станут пить кровь ведьмы.', '', 28153),
(135366, 'ruRU', 'Ну полно вам. Плачет она убедительно, но вдруг это хитрость. Продолжим.', '', 28153),
(135365, 'ruRU', 'Она плачет! Ведьмы ведь так не могут?', 'Она плачет! Ведьмы ведь так не могут?', 28153),
(135364, 'ruRU', '', 'Давай. Покажем им.', 28153),
(135363, 'ruRU', 'Способна ли подсудимая плакать? Попробуйте убедить нас в этом.', '', 28153),
(135362, 'ruRU', 'Начнем с проверки на слезы. Да будет известно всем, что мисс Уэйкрест за время суда не проронила ни единой слезы.', '', 28153),
(135361, 'ruRU', 'Я проявлю великодушие и позволю нашему гостю провести испытания, как того пожелала леди.', '', 28153),
(135360, 'ruRU', 'По традиции, леди Уэйкрест сама выбрала испытания, призванные доказать, что она непричастна к колдовству.', '', 28153),
(135359, 'ruRU', 'Наконец-то! Суд продолжается!', '', 28153),
(135358, 'ruRU', 'Вы там закончили? Я теряю терпение!', '', 28153),
(135357, 'ruRU', 'Мне когда-то рассказывали историю о ведьме, которая жила на болоте. Местные жители поняли, что дело нечисто, по тому, что кровомошки к ней и близко не подлетали. \n\nВот всех кусали, а ее нет! \n\nГоворят, это потому, что у ведьмы кровь такая гадкая, что даже мошкам не нужна!', '', 28153),
(135356, 'ruRU', 'Мне никогда раньше не приходилось видеть настоящей ведьмы. Правда, здорово?', '', 28153),
(135355, 'ruRU', 'Раньше мы бы просто привязали ей к ногам камень и бросили в реку! Если всплывет – значит, вмешалась нечистая сила, надо вешать! \n\nПо-моему, это лучший способ избавиться от ведьмы!', '', 28153),
(135354, 'ruRU', 'Проклятье ведьмы отняло у меня сына! Пусть наконец свершится правосудие!', '', 28153),
(135353, 'ruRU', '', 'Я... точно не знаю, но... \n\nХодят слухи, что ведьму не может стошнить, потому что темные духи, которые живут у нее внутри, постоянно поглощают содержимое желудка. \n\nТолько вот как это доказать?..', 28153),
(135352, 'ruRU', '', 'Нужно освободить наш город от проклятия. \n\nНаверняка оно разрушится, если убить ведьму, которая его навела?', 28153),
(135351, 'ruRU', 'Говорят, что плоть ведьм неуязвима для огня. Потому-то мы и вешаем тех, кого признают виновными! \n\nЕсли хочешь убедить меня в ее невиновности, поднеси к ней факел!', '', 28153),
(135350, 'ruRU', 'Эта женщина накликала беду на наш город. Она должна за это заплатить!', '', 28153),
(135349, 'ruRU', '', 'Ну, моя мама всегда говорила, что ведьма не может заплакать, пусть даже ей очень грустно или очень больно. \n\nМисс Уэйкрест и слезинки не проронила с тех пор, как ее решили отдать под суд. Видать, ведьма!', 28153),
(135348, 'ruRU', 'Как можно доказать, что кто-то не занимается ведьмовством?', 'Как можно доказать, что кто-то не занимается ведьмовством?', 28153),
(135347, 'ruRU', '', 'Все это так ужасно, но Лощина Лучников заслуживает правосудия!', 28153),
(135346, 'ruRU', 'Мисс Уэйкрест выбрала испытания, которые хочет пройти?', '', 28153),
(135345, 'ruRU', 'Наконец-то! На чем мы остановились?..', '', 28153),
(135344, 'ruRU', 'Констебль! Можете продолжать этот... суд.', '', 28153),
(135343, 'ruRU', 'Благодаря тебе мы выиграли немного времени. Будем надеяться, что эта толпа не желает леди зла.', '', 28153),
(135342, 'ruRU', '', 'Спасти? Ты собираешься здесь всех перерезать, чтобы освободить меня? \n\nНет, если хочешь помочь, то начни с маршала.\n\nХотя их обвинения и несправедливы, все же это мой народ, и я не позволю причинить им вред лишь потому, что мне доставили неудобства. Пусть состоится суд – я докажу свою невиновность.\n\nОднако, боюсь, что маршал возьмет дело в свои руки, а у меня руки связаны, как видишь. Убеди его не вмешиваться в судебное разбирательство.', 28153),
(135341, 'ruRU', 'Я пришел спасти вас.', 'Я пришла спасти вас.', 28153),
(135340, 'ruRU', '', 'Мне жаль, что тебя втянули во все это. Жители этих мест на самом деле добрые, просто времена сейчас суровые.', 28153),
(135339, 'ruRU', '', 'Маршал, не вмешивайтесь! Я приказываю вам!', 28153),
(135338, 'ruRU', 'У меня нет времени на споры. Если вы не подчинитесь, мы заберем ее силой!', '', 28153),
(135337, 'ruRU', 'Мисс Уэйкрест обвиняется в колдовстве! Мы ее не отпустим, если ее невиновность не будет доказана!', '', 28153),
(135336, 'ruRU', 'Констебль Фреймер! Приказываю вам передать леди Уэйкрест под мое попечение!', '', 28153),
(135335, 'ruRU', 'Что за напасть?! Кто на этот раз?!', '', 28153),
(135334, 'ruRU', 'Глядите! Из лесу скачут всадники!', 'Глядите! Из лесу скачут всадники!', 28153),
(135333, 'ruRU', 'Терпеть не могу, когда меня прерывают! Что привело тебя сюда?', '', 28153),
(135332, 'ruRU', 'Констебль! У нас гости!', 'Констебль! У нас гости!', 28153),
(135331, 'ruRU', 'Этот суд изучит вашу вину и...', '', 28153),
(135330, 'ruRU', 'Люсиль Уэйкрест! Вы обвиняетесь в том, что практиковали колдовство и наслали проклятие на Лощину Лучников.', '', 28153),
(135301, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [70] Призвать боевой трицикл', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [70] Призвать боевой трицикл', 28153),
(135286, 'ruRU', '', 'Было так глупо с моей стороны отправляться на поиски древних реликвий в одиночку...', 28153),
(135281, 'ruRU', 'Что... <ик!>…чего пялишься?', '', 28153),
(135272, 'ruRU', 'Давай обсудим, как нам победить троллей крови.', 'Давай обсудим, как нам победить троллей крови.', 28153),
(135265, 'ruRU', '', 'Еще один... Сюда!', 28153),
(135263, 'ruRU', '', 'Есть! Торга, лоа-черепаха. Мудрый и великодушный. Он нам точно поможет. Должен быть кто-то еще...', 28153),
(135261, 'ruRU', '', 'Назмир проклят... но лоа почему-то любят это место. Отойдите... я узнаю, кто здесь, с помощью вуду.', 28153),
(135226, 'ruRU', 'Спасибо! Это был просто кошмар.', '', 28153),
(135225, 'ruRU', 'Надо остановить ее!', '', 28153),
(135224, 'ruRU', 'Что происходит?', '', 28153),
(135221, 'ruRU', 'Я убью тебя!', '', 28153),
(135220, 'ruRU', 'Как ты смеешь прерывать работу госпожи!', '', 28153),
(135209, 'ruRU', '', 'Пойдем посмотрим, что еще там есть.', 28153),
(135190, 'ruRU', 'Сюда, Мизинчик! У меня для тебя вкусняшка!', 'Сюда, Мизинчик! У меня для тебя вкусняшка!', 28153),
(135189, 'ruRU', 'Альянс захватил шахту!', 'Альянс захватил шахту!', 28153),
(135188, 'ruRU', 'Мда, сумбурно как-то получилось. Но ведь получилось же! Ха-ха-ха!', '', 28153),
(135187, 'ruRU', 'Тот, кто владеет мачтой... направляет мою команду...', '', 28153),
(135185, 'ruRU', 'Кое-кто с нетерпением ждет возвращения флота. Но я отлично помню троллей, которые отправились в плаванье с Зулом. Очень злые ребята.', 'Кое-кто с нетерпением ждет возвращения флота. Но я отлично помню троллей, которые отправились в плаванье с Зулом. Очень злые ребята.', 28153),
(135184, 'ruRU', 'А правда, что Зула силком утащили обратно в Зандалар? Готов спорить, он не шибко этому рад.', 'А правда, что Зула силком утащили обратно в Зандалар? Готова спорить, он не шибко этому рад.', 28153),
(135179, 'ruRU', 'Я не очень люблю Орду, но если вы убиваете отребье из Альянса, то вы неплохие ребята.', 'Я не очень люблю Орду, но если вы убиваете отребье из Альянса, то вы неплохие ребята.', 28153),
(135178, 'ruRU', 'Тебе правда довелось сражаться плечом к плечу с принцессой Таланджи? Она учинила расправу над кем-нибудь? Взорвала чей-то разум? Как тебе ее сглаз?', 'Тебе правда довелось сражаться плечом к плечу с принцессой Таланджи? Она учинила расправу над кем-нибудь? Взорвала чей-то разум? Как тебе ее сглаз?', 28153),
(135177, 'ruRU', 'Говорят, вами правит умертвие. Старине Бвонсамди это не понравится.', 'Говорят, вами правит умертвие. Старине Бвонсамди это не понравится.', 28153),
(135176, 'ruRU', 'Ты из Орды? А правда, что Вол\'джин погиб?', 'Ты из Орды? А правда, что Вол\'джин погиб?', 28153),
(135175, 'ruRU', 'Слава лоа, принцесса Таланджи вернулась. Хоть она и недолго отсутствовала, но ее противникам ведь много и не надо.', 'Слава лоа, принцесса Таланджи вернулась. Хоть она и недолго отсутствовала, но ее противникам ведь много и не надо.', 28153),
(135174, 'ruRU', 'Сначала чужаки, а теперь еще и Орда? Кого еще Таланджи впустит в наш город?', 'Сначала чужаки, а теперь еще и Орда? Кого еще Таланджи впустит в наш город?', 28153),
(135173, 'ruRU', 'Орда? Здесь? Настали темные времена.', 'Орда? Здесь? Настали темные времена.', 28153),
(135147, 'ruRU', 'Я... Что случилось? Я уношу отсюда ноги!', '', 28153),
(135140, 'ruRU', 'Отец, помоги мне. Направь меня. Прошу тебя...', '', 28153),
(135138, 'ruRU', 'Мы потеряли осадные башни! У нас большие потери...', '', 28153),
(135002, 'ruRU', 'Я не могу оставить его здесь. Возьми уже, а не то заберу обратно!', '', 28153),
(135001, 'ruRU', 'Если контейнер не откроют в ближайшее время, мне придется активировать устройство для его отзыва!', '', 28153),
(134991, 'ruRU', 'Ну, не может же всегда везти. Не очень-то и хотелось!', '', 28153),
(134989, 'ruRU', 'Что? Никто не желает? Ну же, давайте!', '', 28153),
(134976, 'ruRU', 'Я первый увидел!', 'Я первая увидела!', 28153),
(134975, 'ruRU', 'Мне это надо!', 'Мне это надо!', 28153),
(134877, 'ruRU', 'Ладно, займемся делом! Кто первым откроет, тот все и забирает!', '', 28153),
(134876, 'ruRU', 'Осталось всего пятнадцать. Сейчас начнется настоящее веселье!', '', 28153),
(134875, 'ruRU', 'Открывание в процессе. Дай мне тридцать секунд, ладно?', '', 28153),
(134869, 'ruRU', 'Груз на подходе! Берегите головы!', '', 28153),
(134867, 'ruRU', 'Слушай сюда! Мы послали в Низину груз с припасами.', '', 28153),
(134811, 'ruRU', 'Открывание завершено! Победитель получит все!', '', 28153),
(134810, 'ruRU', 'Операция открытия завершится через 15 секунд!', '', 28153),
(134809, 'ruRU', 'Начинаю процедуру открытия! Осталось 30 секунд.', '', 28153),
(134790, 'ruRU', 'Взрывчатка заложена! Осторожнее там!', '', 28153),
(134789, 'ruRU', 'Припасы для Низины на подходе!', '', 28153),
(134699, 'ruRU', '', 'Иди дальше. А я останусь на пару слов с этой гадюкой.', 28153),
(134678, 'ruRU', 'Лягушек мы убивать не будем, но с тобой расправимся!', '', 28153),
(134676, 'ruRU', 'Мы поймаем всех твоих зеленых друзей и высосем из них силу!', '', 28153),
(134675, 'ruRU', 'Я должен защитить ее новый источник маны!', '', 28153),
(134674, 'ruRU', 'Ах ты дрянь, |3-6($r)! Мы все равно получим новый источник маны!', '', 28153),
(134673, 'ruRU', 'Мы поймаем еще больше лягушек, как только разделаемся с тобой!', '', 28153),
(134672, 'ruRU', 'Нам приказано не убивать лягушек, но тебя мы убить можем!', '', 28153),
(134671, 'ruRU', 'Ты нам не помешаешь. Этих лягушек нам хватит на много лет!', '', 28153),
(134670, 'ruRU', '', 'Наги не отдадут своих лягушек!', 28153),
(134669, 'ruRU', '', 'Это наши лягушки!', 28153),
(134668, 'ruRU', '', 'Смерть похитителям маны!', 28153),
(134667, 'ruRU', '', 'Теперь эти лягушки наши!', 28153),
(134666, 'ruRU', '', 'Эти лягушки наши!', 28153),
(134665, 'ruRU', '', 'Этих лягушек нам хватит на долгие годы!', 28153),
(134664, 'ruRU', '', 'Эти лягухи помогут спасти наш народ!', 28153),
(134663, 'ruRU', '', 'Эти лягушки будут нас кормить!', 28153),
(134661, 'ruRU', 'Орда трусливо напала на Тельдрассил и развязала новую войну... Враги четко обозначили свою цель.', '', 28153),
(134656, 'ruRU', 'Краг\'ва вознаградит тебя за веру. Идем.', '', 28153),
(134652, 'ruRU', '', 'Мой старик рассказывал мне о Краг\'ве. Никто ему не верил... а я верила. Я надеялась, что он существует.', 28153),
(134651, 'ruRU', 'Я знаю, что ты хранишь в своем сердце, Нарез. Все это время ты была верна Краг\'ве.', '', 28153),
(134650, 'ruRU', '', 'Стой! Пока ты еще здесь...', 28153),
(134649, 'ruRU', 'Мне пора вернуться на курган. Еще раз спасибо за помощь.', '', 28153),
(134648, 'ruRU', 'Говорят даже, что твой отец дал слабину и послал свою единственную дочь умолять Зула вернуться вместе с флотом. Все так, принцесса?', '', 28153),
(134647, 'ruRU', '', 'Да как ты смеешь говорить так...', 28153),
(134646, 'ruRU', 'Когда Залдраксия умрет, мы сможем дать нагам отпор. Удачи.', '', 28153),
(134639, 'ruRU', 'У южного строения Орды появился вражеский разрушитель!', 'У южного строения Орды появился вражеский разрушитель!', 28153),
(134638, 'ruRU', '', 'Всю жизнь провела в этих холмах, но таких чудовищ еще не видала!', 28153),
(134637, 'ruRU', '<Показать ей Слово Зула.>', '<Показать ей Слово Зула.>', 28153),
(134630, 'ruRU', '', 'Н-не знаю, что там з-затевает моя сестра со своими друзьями, но, это точно ч-что-то нехорошее. Для хороших вещей к-кровавые жертвоприношения не нужны!', 28153),
(134629, 'ruRU', '', 'Т-так много ног! И глаз! Они ищут меня!', 28153),
(134620, 'ruRU', '', 'Нам нужен истинный лидер! Не король-слабак.', 28153),
(134618, 'ruRU', '', 'Наши границы не защищены. Наш народ слаб. Нам нужна сила, которую может дать только Зул.', 28153),
(134617, 'ruRU', '', 'Вспомни слова нашего пророка Зула. Вспомни, какую участь он предрек нашему народу.', 28153),
(134616, 'ruRU', '', 'Король Растахан только и способен что сидеть на своем троне – он слишком слаб, а может быть, слишком труслив, чтобы предстать перед своим народом. Нам нужен сильный правитель!', 28153),
(134615, 'ruRU', '', 'Зул предвидел Катаклизм, и что мы сделали? Мы молча смотрели, как наш король изгнал его. Мы молча смотрели, как он забрал наших братьев и сестер с собой в ссылку. И мы увидели разрушения, которые принес Катаклизм!', 28153),
(134613, 'ruRU', '', 'Зул вернется и возродит нашу империю из пепла.', 28153),
(134610, 'ruRU', '', 'Время пришло! Надо сказать остальным. Те, кто по-прежнему верен ему, должны узнать.', 28153),
(134599, 'ruRU', '', 'Королева Азшара! Я не подведу тебя! Лягушки будут нашими, я лично за этим прослежу!', 28153),
(134598, 'ruRU', '', 'Все твои ненаглядные лягушки будут сидеть в клетках. Они будут жить лишь для того, чтобы питать нас!', 28153),
(134597, 'ruRU', '', 'Глупое создание! Наш народ наконец-то насытится магией. Больше никакой жажды! Больше никакого голода!', 28153),
(134596, 'ruRU', '', 'За что?.. Нам почти удалось... избавиться от жажды магии... навсегда...', 28153),
(134595, 'ruRU', '', 'Ты! Все проблемы из-за тебя... лягушки должны были питать нашу магию долгие годы!', 28153),
(134594, 'ruRU', 'Наги сполна заплатят за свои злодеяния.', '', 28153),
(134593, 'ruRU', 'Пусть Залдраксия заплатит за все, что сотворила с нами.', '', 28153),
(134592, 'ruRU', 'Да! Моя сила вернулась... спасибо тебе. Краг\'ва узнает обо всем.', '', 28153),
(134591, 'ruRU', 'О, да... как приятно вновь ощущать силу! Краг\'ва узнает о твоих успехах.', '', 28153),
(134590, 'ruRU', 'Я... ощущаю силу! Спасибо тебе, однако я должен вернуться к Краг\'ве.', '', 28153),
(134589, 'ruRU', '', 'Несколько лет назад он вернулся из ссылки с нашим флотом.$b$bЕго посетило видение о том дне, когда весь мир окрасится кровью, и он описывал тебя во всех подробностях.', 28153),
(134588, 'ruRU', 'Когда вы с Зулом говорили в последний раз?', 'Когда вы с Зулом говорили в последний раз?', 28153),
(134587, 'ruRU', '', 'Ты! Это ты!$b$bЗул мне тебя описывал. В деталях. Он даже упомянул вот эту... дрянь... у тебя на лице. Все сходится.$b$bСкажи, это правда? У тебя от него весточка?', 28153),
(134584, 'ruRU', 'Значит, время наконец-то пришло. Этот почтовый ящер у меня наготове с самых времен Властелина Грома. Кажется, наконец настал его час.', '', 28153),
(134583, 'ruRU', 'Магия лягушек прокормит наш народ. Мы больше никогда не будем голодать!', '', 28153),
(134581, 'ruRU', '<Показать ему Слово Зула.>', '<Показать ему Слово Зула.>', 28153),
(134580, 'ruRU', 'В чем дело?', '', 28153),
(134492, 'ruRU', '', 'Наконец-то кто-то пришел мне на помощь! Наги застали меня врасплох. Мы должны спасти лягушек.', 28153),
(134471, 'ruRU', '', 'Что это? Неужели штормградский львенок вышел поиграть? Тебя ожидает большой сюрприз, юный король... Мы только начали!', 28153),
(134465, 'ruRU', '', 'Уф... Терпеть не могу прятаться и ждать. Выясни, зачем нагам эти лягушки!', 28153),
(134464, 'ruRU', 'И это все, Ветрокрылая?!', '', 28153),
(134463, 'ruRU', 'Всем войскам! Штурмуйте ворота! Во славу Альянса!', '', 28153),
(134460, 'ruRU', '', 'Издевательства над лягушками этим нагам так просто с рук не сойдут!', 28153),
(134453, 'ruRU', 'Теперь-то принцесса тебя не спасет.', 'Теперь-то принцесса тебя не спасет.', 28153),
(134451, 'ruRU', 'Ха-ха! Кроме меня, тебя никто не спасет.', 'Ха-ха! Кроме меня, тебя никто не спасет.', 28153),
(134450, 'ruRU', 'Стража и двух медяков за твою чужеземную шкуру не даст!', 'Стража и двух медяков за твою чужеземную шкуру не даст!', 28153),
(134449, 'ruRU', 'Мой нож говорит, что ты мне дашь большую скидку.', 'Мой нож говорит, что ты мне дашь большую скидку.', 28153),
(134448, 'ruRU', 'Опять не платишь за \"крышу\" вовремя!', 'Опять не платишь за \"крышу\" вовремя!', 28153),
(134447, 'ruRU', 'Принцесса, разве ты не чуешь страх, пропитавший этот город?', '', 28153),
(134442, 'ruRU', 'Хе... Хе... Свежая партия колбасы уже в пути...', '', 28153),
(134439, 'ruRU', 'А! Новое мясо для мясорубки!', '', 28153),
(134438, 'ruRU', 'Ха! Смотри ж, какая самонадеянность! Дай-ка я покажу тебе, что есть в запасе у Орды.', '', 28153),
(134330, 'ruRU', 'Спасайся кто может!', 'Спасайся кто может!', 28153),
(134329, 'ruRU', 'Здесь творится полное безумие! Надо найти укрытие.', 'Здесь творится полное безумие! Надо найти укрытие.', 28153),
(134328, 'ruRU', 'Эти трогги появились словно ниоткуда!', 'Эти трогги появились словно ниоткуда!', 28153),
(134310, 'ruRU', 'Храм лежит в руинах. Все даже хуже, чем я предполагал...', '', 28153),
(134309, 'ruRU', 'Пока меня не убили, я был смотрителем этого храма. Страшно подумать, что с ним стало за долгие годы, прошедшие с моей смерти...', '', 28153),
(134300, 'ruRU', 'Ой! Плохой динозавр. Очень плохой!', 'Ой! Плохой динозавр. Очень плохой!', 28153),
(134299, 'ruRU', 'У тебя хорошо получается!', 'У тебя хорошо получается!', 28153),
(134298, 'ruRU', 'А-а-а! Только не пальцы!', 'А-а-а! Только не пальцы!', 28153),
(134297, 'ruRU', 'Будешь приставать – зашибу!', 'Будешь приставать – зашибу!', 28153),
(134296, 'ruRU', 'Эй! А ну не кусаться!', 'Эй! А ну не кусаться!', 28153),
(134295, 'ruRU', 'Осторожно... Осторожно!', 'Осторожно... Осторожно!', 28153),
(134292, 'ruRU', '%s дрожит и поскуливает.', '', 28153),
(134291, 'ruRU', '%s тревожно визжит.', '', 28153),
(134290, 'ruRU', '%s вопит от страха.', '', 28153),
(134289, 'ruRU', 'Я проведу тебя через руины храма.', 'Я проведу тебя через руины храма.', 28153),
(134288, 'ruRU', 'Медяк лает на горностая.', '', 28153),
(134279, 'ruRU', 'Они питаются моей магией!', '', 28153),
(134278, 'ruRU', 'Они похищают нашу магию!', '', 28153),
(134277, 'ruRU', 'О... моя магия уходит...', '', 28153),
(134276, 'ruRU', 'Меня... опустошили... забрали всю мою силу!', '', 28153),
(134275, 'ruRU', 'Эти злодеи похитили моих друзей!', '', 28153),
(134274, 'ruRU', 'Эти монстры высасывали мою магию!', '', 28153),
(134272, 'ruRU', 'Не бросает...', '', 28153),
(134271, 'ruRU', 'Альянс не бросает своих солдат.', '', 28153),
(134270, 'ruRU', 'Она поднимает мертвых! Эвакуируйте раненых!', '', 28153),
(134266, 'ruRU', 'ВО СЛАВУ ОТРЕКШИХСЯ!', '', 28153),
(134263, 'ruRU', 'Назад, мой король! Чума слишком опасна! Мы не можем...', '', 28153),
(134252, 'ruRU', 'Да хранит вас всех Свет. Несите раненых ко мне!', '', 28153),
(134233, 'ruRU', '', 'Спасибо. Дальше я справлюсь!', 28153),
(134230, 'ruRU', 'Проклятые... дикари!', 'Проклятые... дикари!', 28153),
(134229, 'ruRU', 'Я умираю... за короля... и за Лордерон...', 'Я умираю... за короля... за Лордерон...', 28153),
(134227, 'ruRU', 'Когда же это закончится... Они все идут и идут! Герои, помогите мне!', 'Когда же это закончится... Они все идут и идут! Герои, помогите мне!', 28153),
(134226, 'ruRU', '', 'Эм-м... Помог бы кто.', 28153),
(134224, 'ruRU', '', 'Лучники, на изготовку! Вперед!', 28153),
(134223, 'ruRU', 'Герои! Тут кругом враги! Я не могу исцелить всех!', '', 28153),
(134211, 'ruRU', 'Как красиво...', '', 28153),
(134209, 'ruRU', 'Ты это слышишь?', '', 28153),
(134208, 'ruRU', 'Рулевой, поворачивай в сторону!', 'Рулевой, поворачивай в сторону!', 28153),
(134186, 'ruRU', 'Ну конечно! Пора официально принять в банду свежее пополнение! Подготовим ритуал!', '', 28153),
(134164, 'ruRU', '', 'Идем, Дрекал, продолжим поиски.', 28153),
(134163, 'ruRU', '', 'Я не вижу ничего интересного.', 28153),
(134162, 'ruRU', '', 'Зачем мы здесь?', 28153),
(134161, 'ruRU', '', 'Знаешь, что случилось с |3-4($r), который кричал \"волки\"?', 28153),
(134159, 'ruRU', '', 'Это для тебя игра?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(134158, 'ruRU', 'Фу... В мою бочку кто-то помочился.', '', 28153),
(134157, 'ruRU', 'Заказчики требуют срочно доставить груз! Отчаливаем!', 'Заказчики требуют срочно доставить груз! Отчаливаем!', 28153),
(134156, 'ruRU', '', 'Так, планы изменились! Готовьтесь отчаливать!', 28153),
(134155, 'ruRU', '', 'Зачем ты тратишь наше время?', 28153),
(134151, 'ruRU', '', 'Эта сигнальная ракета – не игрушка.', 28153),
(134150, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Защищать строение Альянса на юге', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Защищать строение Альянса на юге', 28153),
(134149, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Защитите северное строение Альянса', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Защитите северное строение Альянса', 28153),
(134125, 'ruRU', '', 'Не важно, мы не можем его ждать. Я нашла того, кто якобы знает, где Ракира. Нам сюда.', 28153),
(134123, 'ruRU', '', 'Не будем задерживаться здесь дольше, чем нужно. Запусти ракету, если найдешь что-то важное.', 28153),
(134116, 'ruRU', 'Эти земли принадлежат нам, твари! Вы заплатите жизнью!', '', 28153),
(134115, 'ruRU', 'Солдаты! Стройся!', '', 28153),
(134111, 'ruRU', 'Не скажу, что буду скучать по этому месту.', '', 28153),
(134109, 'ruRU', '', 'Для того, кто стоит так близко от моего меча, у тебя многовато пожеланий.', 28153),
(134101, 'ruRU', 'Тебе здесь не место!', 'Тебе здесь не место!', 28153),
(134100, 'ruRU', 'Чур пустая бочка – моя! А ты полезай в другую.', '', 28153),
(134099, 'ruRU', 'Прячься! Живей!', '', 28153),
(134096, 'ruRU', 'Секретное оружие Эшвейн.', '', 28153),
(134095, 'ruRU', 'Что это было?!', '', 28153),
(134094, 'ruRU', 'Вы уверены, что хотите построить башню за 50 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t фронтовых золотых?', 'Вы уверены, что хотите построить башню за 50 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t фронтовых золотых?', 28153),
(134093, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Построить башню', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Построить башню', 28153),
(134092, 'ruRU', 'Да-да, Ман\'зул. Надо было слушать тебя. Ты не заслужил такой участи. Надо было действовать по плану. Ты такой умный. А теперь заткнись, не то опять за нос ущипну!', '', 28153),
(134091, 'ruRU', 'Ман\'зул! Это же приличная таверна. Где твои манеры?', '', 28153),
(134090, 'ruRU', 'Ха! Должен тебя разочаровать, $p. У него ничего нет, кроме дурацкой повязки и шикарной улыбки.', '', 28153),
(134089, 'ruRU', 'Волни, хватит вызывать гостей на дуэль! Последние двое даже заплатить не успели.', '', 28153),
(134088, 'ruRU', 'Говори громче! Мне трудно подслушивать, когда вы что-то лопочете, как тушканчики!', '', 28153),
(134087, 'ruRU', 'Кого ты хочешь обмануть, Волни? Тебе же нравится эта шляпа. Я не сниму ее, пока ты это не признаешь!', '', 28153),
(134086, 'ruRU', 'Погоди, она тебя не слышит из-за барабана. Гренджа, прервись на секунду и поздоровайся. Гренджа – наш бард. Извини, она иногда забывает, что с гостями надо разговаривать.', '', 28153),
(134085, 'ruRU', '...$p, ты в порядке? Ты пугаешь Гренджу... Может, у тебя тепловой удар?', '', 28153),
(134084, 'ruRU', 'Твоя правда, $p! В Зулдазаре Гренджа часто вытаскивала нас из неприятностей. Она придержала и сломала для нас немало дверей... и костей.', '', 28153),
(134079, 'ruRU', 'Что ж, за работу!', '', 28153),
(134078, 'ruRU', 'Тем не менее... Я благодарен тебе за большую услугу нашему городу. Посмотрю, что можно сделать...', '', 28153),
(134077, 'ruRU', 'Не думаю, что они захотят биться с тобой об заклад.', '', 28153),
(134076, 'ruRU', 'На этой земле лежит проклятье, и когда оно проявилось, Уэйкресты бежали, поджав хвост. Они прятались в своем особняке, пока невидимое зло одного за другим убивало их подданных.', '', 28153),
(134075, 'ruRU', 'Ты хочешь поговорить с этими трусами Уэйкрестами? Не думаю, что это хорошая мысль.', '', 28153),
(134074, 'ruRU', 'Мне надо встретиться с правителем дома Уэйкрестов.', 'Мне надо встретиться с правителем дома Уэйкрестов.', 28153),
(134073, 'ruRU', 'Даже не знаю, как тебя благодарить за помощь нашему городу. \n\nЛистопадная Бухта у тебя в долгу.', '', 28153),
(134072, 'ruRU', 'Чем я могу помочь, |3-6($c)?', '', 28153),
(134070, 'ruRU', '', 'А, вот и ты! Тебя не было дольше, чем мы думали. Были проблемы?', 28153),
(134069, 'ruRU', '', 'До базы можешь долететь на моей ракете. Билет в один конец, так что сперва закончи тут все дела.', 28153),
(134068, 'ruRU', '', 'Эм... Ты молодец и все такое, но дальше мы и сами справимся.', 28153),
(134067, 'ruRU', 'Пора выбираться отсюда.', 'Пора выбираться отсюда.', 28153),
(134066, 'ruRU', 'Трит уверяет, что эта ракета – удобное и безопасное средство передвижения. Но непрочная с виду конструкция говорит об обратном.', '', 28153),
(134065, 'ruRU', 'Крушите вс-с-сех, кто с-с-сопротивляется! Во с-с-славу королевы!', '', 28153),
(134064, 'ruRU', 'Уничтожайте вс-с-сех, кто покажетс-с-ся из храма!', '', 28153),
(134063, 'ruRU', 'Реликвии нужно с-с-собрать для королевы!', '', 28153),
(134062, 'ruRU', 'Реликвии нужно дос-с-ставить королеве! С-с-соберите их, быс-с-стро!', '', 28153),
(134061, 'ruRU', 'Рад видеть всех в целости и сохранности, все благодаря... а вот и наш герой дня!', '', 28153),
(134060, 'ruRU', 'Мои... сокровища...', '', 28153),
(134059, 'ruRU', 'Как ты смеешь трогать мои сокровища!', '', 28153),
(134018, 'ruRU', '<Попытаться открыть сундук.>', '<Попытаться открыть сундук.>', 28153),
(134017, 'ruRU', 'Сундук заперт, но, приложив усилия, его вполне можно открыть.', '', 28153),
(134016, 'ruRU', '', 'Я смотрю, прибыл еще один корабль Альянса. Надеюсь, их встретили теплее, чем Джайну...', 28153),
(134015, 'ruRU', 'Я обязан тебе жизнью!', '', 28153),
(134014, 'ruRU', 'Я этого не забуду. Спасибо!', '', 28153),
(134013, 'ruRU', 'С меня кружка эля!', '', 28153),
(134012, 'ruRU', 'Спасибо! Я уже было отчаялся.', '', 28153),
(134011, 'ruRU', 'Наги заковали остальных в цепи и увели прочь. Пожалуйста, освободи и их тоже!', '', 28153),
(134010, 'ruRU', 'Кровь и честь! Когда встретимся в следующий раз, я угощаю!', '', 28153),
(134009, 'ruRU', '', 'Не знаю, что с тобой случилось, но, кажется, это сработало! Ты... в порядке?', 28153),
(134007, 'ruRU', 'За Альянс!', 'За Альянс!', 28153),
(134003, 'ruRU', 'Сокрушим врага! За Альянс!', '', 28153),
(134001, 'ruRU', 'Королева банши ответит за свои преступления. Сегодня мы покончим с ней навсегда!', '', 28153),
(134000, 'ruRU', 'Они хотят не захватить наши города, а уничтожить все, что нам дорого, лишить нас всякой надежды.', '', 28153),
(133999, 'ruRU', 'Мы изгоним эту мерзость из наших земель! Знамена Альянса вновь будут реять над Лордероном!', '', 28153),
(133998, 'ruRU', 'Братья и сестры, слушайте меня!', '', 28153),
(133996, 'ruRU', 'Король Андуин возглавляет атаку! Проходите мимо резервов и зачистите поле боя!', '', 28153),
(133990, 'ruRU', 'Осадная машина готова к бою!', '', 28153),
(133989, 'ruRU', 'Эта осадная машина просто чудо – под стать тебе!', '', 28153),
(133988, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [100] Построить осадную машину', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [100] Построить осадную машину', 28153),
(133986, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Обучить специалиста мортирного расчета - атака с севера', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Обучить специалиста мортирного расчета - атака с севера', 28153),
(133985, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Обучить рыцарей - атака с севера', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Обучить рыцарей - атака с севера', 28153),
(133984, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Обучить стрелков - атака с севера', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Обучить стрелков - атака с севера', 28153),
(133983, 'ruRU', 'Чтобы заполнить заявки, мне от тебя понадобится кое-что еще.', '', 28153),
(133982, 'ruRU', 'Добро пожаловать в мой магазин!', '', 28153),
(133981, 'ruRU', '', 'Смотрительница стойл Люция Фарондейл к твоим услугам!', 28153),
(133980, 'ruRU', '', 'Подготовка наездников – дело весьма затратное, $n.', 28153),
(133979, 'ruRU', '', 'Рада снова видеть тебя, $n! Чем я могу тебе помочь?', 28153),
(133974, 'ruRU', '', 'Я не собираюсь никого учить за просто так!$B$BНеси золотишко – тогда и поговорим!', 28153),
(133971, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Обучить рыцарей - атака с юга', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Обучить рыцарей - атака с юга', 28153),
(133970, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Обучить специалиста мортирного расчета - атака с юга', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Обучить специалиста мортирного расчета - атака с юга', 28153),
(133969, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Обучить стрелков – атака с юга', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Обучить стрелков – атака с юга', 28153),
(133968, 'ruRU', '', 'Ты чего так долго? Пора за работу!', 28153),
(133960, 'ruRU', '<Вежливо представиться.>', '<Вежливо представиться.>', 28153),
(133959, 'ruRU', '<Вежливо представиться.>', '<Вежливо представиться.>', 28153),
(133958, 'ruRU', '', 'С ней все хорошо? Я велела Кадже не приходить за мной.', 28153),
(133953, 'ruRU', 'Этот затонувший город когда-то был красивым храмом, посвященным лоа моря, Гралу.$b$bНо пришли наги, уничтожили храм и убили всех его служителей.$B$BЕсли Грал и выжил, то очень ослаб.', '', 28153),
(133952, 'ruRU', 'Что такое? Нас атакуют?', '', 28153),
(133951, 'ruRU', 'Что-то упало с неба! Оно вон там!', '', 28153),
(133950, 'ruRU', 'Ненависть к нагам затмила разум моих братьев. Это не первый раз, когда госпожа Ссин и наги из клана Кольца Ужаса наводят нас на такую находку.$b$bВидишь ли, они знают, что нам известно нечто неизвестное им.', '', 28153),
(133947, 'ruRU', '', 'Ты будешь молить о пощаде!', 28153),
(133946, 'ruRU', 'Мне нужно добраться до Мрачной низины.', 'Мне нужно добраться до Мрачной низины.', 28153),
(133945, 'ruRU', 'Ты сгинешь от моего клинка.', 'Ты сгинешь от моего клинка.', 28153),
(133944, 'ruRU', 'Тебя подвезти?', '', 28153),
(133943, 'ruRU', 'Я не беру пленных!', 'Я не беру пленных!', 28153),
(133942, 'ruRU', '', 'Ты поплатишься жизнью!', 28153),
(133941, 'ruRU', '', 'Переверните лагерь вверх дном. Принесите все, над чем работал Годжи и его подручные.', 28153),
(133939, 'ruRU', 'Королева пиратов отомстит за мою смерть!', '', 28153),
(133938, 'ruRU', 'Кто пустил это недоразумение на мой корабль?', '', 28153),
(133936, 'ruRU', 'Сдохни, червь!', 'Сдохни, червь!', 28153),
(133935, 'ruRU', 'А ты, значит, не робкого десятка?', 'А ты, значит, не робкого десятка?', 28153),
(133934, 'ruRU', 'Было твое – станет мое!', 'Было твое – станет мое!', 28153),
(133933, 'ruRU', 'Эта земля принадлежит корпорации Эшвейнов!', 'Эта земля принадлежит корпорации Эшвейнов!', 28153),
(133929, 'ruRU', 'Нечего тебе тут делать!', 'Нечего тебе тут делать!', 28153),
(133928, 'ruRU', 'Тебе не уйти отсюда!', 'Тебе не уйти отсюда!', 28153),
(133926, 'ruRU', 'Я не забуду твоей доброты...', 'Я не забуду твоей доброты...', 28153),
(133925, 'ruRU', 'Наконец-то моим мучениям пришел конец...', 'Наконец-то моим мучениям пришел конец...', 28153),
(133924, 'ruRU', 'Спасибо тебе...', 'Спасибо тебе...', 28153),
(133923, 'ruRU', 'Я знал, что Эрака но Кимбул пошлет кого-нибудь на помощь...', 'Я знала, что Эрака но Кимбул пошлет кого-нибудь на помощь...', 28153),
(133919, 'ruRU', 'Наконец-то я могу покоиться с миром...', 'Наконец-то я могу покоиться с миром...', 28153),
(133918, 'ruRU', 'Я знал, что лоа о нас не забудут...', 'Я знала, что лоа о нас не забудут...', 28153),
(133917, 'ruRU', 'Перепрыгните через указанный барьер. Судья может не засчитать попытку, если прыжок придется не по центру!', 'Перепрыгните через указанный барьер. Судья может не засчитать попытку, если прыжок придется не по центру!', 28153),
(133916, 'ruRU', 'Если вы прикажете коню прыгать слишком рано или слишком поздно, он может сбросить вас с себя.', 'Если вы прикажете коню прыгать слишком рано или слишком поздно, он может сбросить вас с себя.', 28153),
(133915, 'ruRU', 'Не волнуйся, я не заблужусь! А если и заблужусь, ты все равно меня разыщешь.', '', 28153),
(133913, 'ruRU', 'Перейдите с легкого галопа на галоп, чтобы двигаться еще быстрее!', 'Идя легким галопом, вы можете галопировать еще быстрее!', 28153),
(133912, 'ruRU', 'Перейдите на легкий галоп, чтобы передвигаться быстрее. Это лучшая скорость для выполнения прыжков!', 'Перейдите на легкий галоп, чтобы передвигаться быстрее. Это лучшая скорость для выполнения прыжков!', 28153),
(133911, 'ruRU', 'Нажмите \"Идти\", чтобы двигаться вперед. Нажмите \"Остановиться\", чтобы прекратить движение в любой момент.', 'Нажмите \"Идти\", чтобы двигаться вперед. Нажмите \"Остановиться\", чтобы прекратить движение в любой момент.', 28153),
(133904, 'ruRU', 'Жаблины – ужасные создания. Но хоть мы их и презираем, эти крохотные безумные морские жители с радостью сожрут своих хозяев-наг.', '', 28153),
(133899, 'ruRU', 'Хм, возможно, Шоак поймет, что это место не исследовать надо, а уходить отсюда поскорее!', '', 28153),
(133893, 'ruRU', 'Пф... Всегда пожалуйста, балда. Смотри не удери снова!', '', 28153),
(133883, 'ruRU', 'У северного строения Орды появился вражеский разрушитель!', 'У северного строения Орды появился вражеский разрушитель!', 28153),
(133835, 'ruRU', 'К сожалению, армия – удовольствие не из дешевых, $n. Солдат надо кормить, тренировать, мастерить для них доспехи.\n\nВозвращайся, когда твои карманы станут чуть тяжелее.', '', 28153),
(133834, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Обучить пехоту - атака с юга', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Обучить пехоту - атака с юга', 28153),
(133833, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Обучить пехоту - атака с севера', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Обучить пехоту - атака с севера', 28153),
(133832, 'ruRU', '', 'Сколько же трупов... надо съесть... чтобы получить такую силу?', 28153),
(133831, 'ruRU', '', 'Голоса нашептали и о тебе... Я с удовольствием тебя съем!', 28153),
(133830, 'ruRU', '', 'Не смей... меня есть... чтобы получить... мою силу...', 28153),
(133829, 'ruRU', '', 'Я съем твою руку, а остальное брошу к тотему!', 28153),
(133828, 'ruRU', '', 'Голоса шептали... что плоть... сделает нас сильнее...', 28153),
(133827, 'ruRU', '', 'Голоса шепчут мне, что твоя плоть даст нам силу!', 28153),
(133820, 'ruRU', 'У вас недостаточно фронтового золота для строительства сооружения.', 'У вас недостаточно фронтового золота для строительства сооружения.', 28153),
(133819, 'ruRU', 'Мы не можем начать строительство, если уже начата постройка другого здания.', 'Мы не можем начать строительство, если уже начата постройка другого здания.', 28153),
(133806, 'ruRU', 'Если ты захочешь вернуться в этот храм, тебя примут как друга и почетного гостя.', '', 28153),
(133805, 'ruRU', 'Я ценю твою храбрость и хочу дать тебе благословение силы. Пусть оно хорошо послужит тебе в грядущих битвах.', '', 28153),
(133804, 'ruRU', 'Более того, тебе удалось спасти души моих последователей от гибели и помочь этому храму.', '', 28153),
(133803, 'ruRU', 'С Куппакой наконец покончено, и украденные артефакты власти вырваны из рук Тортаки.', '', 28153),
(133801, 'ruRU', 'Племя Тортака уже не спасти. Куппаку и его сородичей следует убить, а источники их темных сил – уничтожить.', '', 28153),
(133799, 'ruRU', 'Я и не думал, что жажда власти сделает их настолько злобными... что поделать?', '', 28153),
(133798, 'ruRU', 'Племя Тортака не остановится, пока не поглотит энергию всех духов в храме.', '', 28153),
(133794, 'ruRU', 'Вы уверены, что хотите построить кузницу за 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t фронтовых золотых?', 'Вы уверены, что хотите построить кузницу за 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t фронтовых золотых?', 28153),
(133793, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Построить кузницу', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Построить кузницу', 28153),
(133790, 'ruRU', 'Вы уверены, что хотите построить мастерскую за 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t фронтовых золотых?', 'Вы уверены, что хотите построить мастерскую за 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t фронтовых золотых?', 28153),
(133788, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Построить мастерскую', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Построить мастерскую', 28153),
(133786, 'ruRU', 'Вы уверены, что хотите построить стойла за 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t фронтовых золотых?', 'Вы уверены, что хотите построить стойла за 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t фронтовых золотых?', 28153),
(133785, 'ruRU', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Построить стойла', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Построить стойла', 28153),
(133784, 'ruRU', 'Выберите здание, которое хотите здесь построить.', 'Выберите здание, которое хотите здесь построить.', 28153),
(133775, 'ruRU', 'Шоак вляпался в неприятности по самые уши... Опять! Поверить не могу, что этот болван попался троллям крови.', '', 28153),
(133769, 'ruRU', 'Шоак! Где ты? Шоак!', '', 28153),
(133768, 'ruRU', 'Я знаю одно хорошее место. За мной!', '', 28153),
(133765, 'ruRU', 'Твоя душа обречена!', '', 28153),
(133764, 'ruRU', 'Твой лоа здесь бессилен!', '', 28153),
(133763, 'ruRU', 'Мы заберем твою душу!', '', 28153),
(133760, 'ruRU', 'Племя Тортака не терпит чужаков!', '', 28153),
(133759, 'ruRU', 'Тебя сюда никто не звал!', '', 28153),
(133758, 'ruRU', 'Эрака но Кимбул здесь не властен!', '', 28153),
(133757, 'ruRU', 'Сила этого мира теперь наша!', '', 28153),
(133756, 'ruRU', 'Даже сам лоа не сможет нас остановить!', '', 28153),
(133755, 'ruRU', 'Я покажу тебе мою истинную силу!', '', 28153),
(133754, 'ruRU', 'Сила будет нашей!', '', 28153),
(133752, 'ruRU', 'Мы выпьем твою душу!', '', 28153),
(133745, 'ruRU', '', 'Что тебе извес-с-стно о наших планах? Говори!', 28153),
(133742, 'ruRU', '', 'Говори! Какие с-с-секреты храма тебе извес-с-стны?', 28153),
(133741, 'ruRU', '', 'Говори – или отправишься на морс-с-ское дно!', 28153),
(133732, 'ruRU', 'Ты освободи Шоака, а я укроюсь в безопасном месте. Иначе тебе придется спасать уже двоих.', '', 28153),
(133731, 'ruRU', '[После перемещения на пароме...]', '[После перемещения на пароме...]', 28153),
(133730, 'ruRU', 'Спасибо, что подбросила. Я пойду к старику.', '', 28153),
(133729, 'ruRU', 'Ну и болван... Надо было ему угодить в плен к троллям крови!', '', 28153),
(133728, 'ruRU', '...ната\'ворские тролли схватили Шоака.', '', 28153),
(133727, 'ruRU', 'Нет... Нет, нет!', '', 28153),
(133726, 'ruRU', 'О, нет...', '', 28153),
(133725, 'ruRU', 'Хватит круги наворачивать, ищи Шоака!', '', 28153),
(133724, 'ruRU', 'Что за шум? Пойди проверь, а я посторожу принцессу.', '', 28153),
(133723, 'ruRU', 'Листопадная Бухта в долгу перед тобой. Чем мы можем тебя отблагодарить?', '', 28153),
(133722, 'ruRU', 'Спасибо... Я уже и не думал, что очнусь от этого кошмарного забытья...', '', 28153),
(133721, 'ruRU', 'Что?... что происходит?', '', 28153),
(133720, 'ruRU', '', 'А, вот и ты! И жители деревни, кажется, тоже на подходе!', 28153),
(133719, 'ruRU', '', 'Мое проклятье... нельзя разрушить...', 28153),
(133718, 'ruRU', '', 'С нами сила веков. У тебя нет шансов!', 28153),
(133717, 'ruRU', '', 'Я покажу тебе мощь ковена!', 28153),
(133716, 'ruRU', '', 'Уходи отсюда, или разделишь его судьбу.', 28153),
(133715, 'ruRU', '', 'Ты сама наивность, |3-6($c)! Этот город мой. Такова воля Матери!', 28153),
(133714, 'ruRU', 'Она опасна... Но куда опасней буду я, если узнаю, что ты задумал какую-то гадость!', 'Она опасна... Но куда опасней буду я, если узнаю, что ты задумал какую-то гадость!', 28153),
(133713, 'ruRU', 'Что бы ты ни задумал, я надеюсь, к этому непричастна та сумасшедшая из леса.', 'Что бы ты ни задумал, я надеюсь, к этому непричастна та сумасшедшая из леса.', 28153),
(133712, 'ruRU', 'Милый муж. Не знаю, зачем ты пытаешься меня обмануть, но я видела, как ты тайком пробирался к предгорьям, думая, что я сплю.', 'Милый муж. Не знаю, зачем ты пытаешься меня обмануть, но я видела, как ты тайком пробирался к предгорьям, думая, что я сплю.', 28153),
(133711, 'ruRU', 'Попробую отправить другую партию к концу недели.', 'Попробую отправить другую партию к концу недели.', 28153),
(133710, 'ruRU', 'Мои свинки начали страдать от недуга, вызывающего у них неестественную агрессию. Я едва смог согнать их вместе для транспортировки.', 'Мои свинки начали страдать от недуга, вызывающего у них неестественную агрессию. Я едва смог согнать их вместе для транспортировки.', 28153),
(133709, 'ruRU', 'Одна любезная пожилая дама дала мне корм для свиней и даже не взяла плату. Но, боюсь, он оказался испорченным.', 'Одна любезная пожилая дама дала мне корм для свиней и даже не взяла плату. Но, боюсь, он оказался испорченным.', 28153),
(133708, 'ruRU', 'Уважаемый бригадир Стогтон, я приношу извинения за задержку поставок мяса.', 'Уважаемый бригадир Стогтон, я приношу извинения за задержку поставок мяса.', 28153),
(133707, 'ruRU', 'Сообщайте мэру Уайту обо всех подозрительных лицах и происшествиях.', '', 28153),
(133706, 'ruRU', 'Также мы получили донесения об опасных существах, замеченных в предгорьях. Покидая город, будьте крайне осторожны.', '', 28153),
(133705, 'ruRU', 'Ради вашей же безопасности старайтесь не выходить из дома после заката.', '', 28153),
(133704, 'ruRU', 'В связи с исчезновениями людей, в Листопадной Бухте вводится комендантский час.', '', 28153),
(133703, 'ruRU', 'Готов поставить на то, что тут замешана эта старая карга!', 'Готов поставить на то, что тут замешана эта старая карга!', 28153),
(133702, 'ruRU', 'Так через месяц нам будет нечем кормить свиней. Что за проклятие постигло наш город?', 'Так через месяц нам будет нечем кормить свиней. Что за проклятие постигло наш город?', 28153),
(133701, 'ruRU', 'Не знаю, откуда взялась эта мерзкая мошкара, но она налетает по утрам уже вторую неделю.', 'Не знаю, откуда взялась эта мерзкая мошкара, но она налетает по утрам уже вторую неделю.', 28153),
(133700, 'ruRU', '', 'Ищи любые письменные свидетельства жителей деревни. Там может быть ключ к разгадке.', 28153),
(133699, 'ruRU', '', 'Попробую что-нибудь найти в городском реестре. Если местные жители видели что-то подозрительное, возможно, они где-то это записали.', 28153),
(133698, 'ruRU', '', 'О нет... и здесь тоже? Только не это!', 28153),
(133693, 'ruRU', '', 'Ты не понимаешь. Если у Джакра\'зета все получится, безопасных мест не останется.', 28153),
(133692, 'ruRU', '', 'Ну, я же не могла взять и бросить все на произвол судьбы! Мы можем сбежать от всего этого. Начать жизнь заново там, где будем в безопасности.', 28153),
(133691, 'ruRU', '', 'Тебе не следовало приходить, Каджа.', 28153),
(133690, 'ruRU', '', 'Я думала, что никогда больше тебя не увижу.', 28153),
(133689, 'ruRU', 'Уничтожить несколько тотемов – это уже кое-что. Давай попробуем поискать этого тупицу...', '', 28153),
(133688, 'ruRU', 'Шоак! Это уже не смешно – тут же совсем рядом застава троллей крови!', '', 28153),
(133686, 'ruRU', '', 'Ракира! Ты жива!', 28153),
(133685, 'ruRU', 'Золани, мы должны защитить храм. Вперед!', '', 28153),
(133672, 'ruRU', 'Да исполнится воля госпожи!', '', 28153),
(133670, 'ruRU', 'Сокрушу!', '', 28153),
(133669, 'ruRU', 'Ты готов, маленький король? Разгромим этих еретиков!', '', 28153),
(133668, 'ruRU', 'Но клянусь тебе и всем, кто меня слышит: я не остановлюсь, пока не заполучу голову Зула.', '', 28153),
(133667, 'ruRU', 'Да, я потерял хватку. Многие предупреждали меня, даже моя дочь. А я не слушал.', '', 28153),
(133666, 'ruRU', 'Не пора ли спросить себя: ты король или чья-то добыча?', '', 28153),
(133665, 'ruRU', 'Они почуяли кровь в воде.', '', 28153),
(133664, 'ruRU', 'Советники восстают против тебя. Друзья хотят твоей смерти.', '', 28153),
(133663, 'ruRU', 'Растахан, твои земли осаждают враги.', '', 28153),
(133648, 'ruRU', 'Великий лоа, ты еще дышишь? Давай снимем с тебя цепи.', '', 28153),
(133646, 'ruRU', 'Зул предвидел ваш приход. Все так, как он предсказал.', '', 28153),
(133645, 'ruRU', '', 'Ничтожество! Я могла бы просто раздавить тебя, отомстив за Вол\'каала.', 28153),
(133644, 'ruRU', '', 'Умри, Шадра. Умри навсегда и отдай мне свою силу!', 28153),
(133643, 'ruRU', 'Я пойду вперед, а ты уничтожь тотемы. Надеюсь, когда их не станет, мы сможем найти этого недоумка.', '', 28153),
(133638, 'ruRU', '', 'Вол\'каал! Избавься от чужаков, а я пока закончу с Шадрой.', 28153),
(133633, 'ruRU', '', 'Шадра! Веками ты указывала мне путь. Но с этого дня я служу новому хозяину!', 28153),
(133632, 'ruRU', '', 'Слишком поздно! Кровь лоа уже пролилась!', 28153),
(133610, 'ruRU', 'Гонк злиться! Гонк убивать Язму!', '', 28153),
(133606, 'ruRU', 'Твои действия не остались незамеченными. Прими мое благословение.', '', 28153),
(133605, 'ruRU', 'Спасибо тебе, $n. Прими мое благословение.', '', 28153),
(133591, 'ruRU', '<К корпусу ракеты прикреплено небольшое сообщение.>$b$bВНИМАНИЕ! Официальное сообщение.$B$BЕсли у вас нет ранга командира Орды, НЕ СМЕЙТЕ ЭТО ЧИТАТЬ!$b$bОтправитель: Патч, подрывной отряд$b$bМоя команда должна перевезти тяжелое оружие Орды для обеспечения успешного выполнения нашего плана в Назмире. Мы доставим пушку, которая позволит легко разделаться с любыми врагами.$B$BСейчас мы на \"Чарке\" и ищем, где пристать у восточного берега. Пришлите проводника, который сопроводит нас к точке сбора.', '', 28153),
(133582, 'ruRU', '*Рычит* Пока я останусь, но лишь затем, чтобы помочь духам моих помощников, которых убили из-за вашей глупости.', '', 28153),
(133581, 'ruRU', 'Да, я не справился... но оглядись вокруг! Разве это место не навевает приятные воспоминания? Останься, позволь нам восстановить этот храм в твою честь!', '', 28153),
(133580, 'ruRU', 'У тортолланов странные обычаи, мой господин. Откуда мне было знать, что отказ от предложения брака будет считаться актом агрессии?', '', 28153),
(133579, 'ruRU', 'У тебя было простое задание. Заключить мир с племенем Тортака и присматривать за моим храмом в мое отсутствие. А теперь посмотри, что с ним стало!', '', 28153),
(133578, 'ruRU', '*кхм* Это я, великий лоа, твой верный и преданный слуга Вунанджу.', '', 28153),
(133576, 'ruRU', '', 'В Кул-Тирасе есть одна старая поговорка.$B$BКогда что-то идет не так, моряки отмахиваются и говорят: \"Никто не может изменить ветер\".$B$BТерпеть не могу эту поговорку.', 28153),
(133575, 'ruRU', '', 'Сайрус воспитывал меня с детства. Он научил меня драться, ездить верхом, ходить под парусом.$B$BКогда пришло мое время вступить в гвардию, я была подготовлена лучше многих инструкторов.$B$BИм это не слишком понравилось.', 28153),
(133574, 'ruRU', '', 'Все изменилось с гибелью Дэлина Праудмура.$B$BНаверное, у Джайны были свои причины, да?', 28153),
(133573, 'ruRU', '', 'Я выросла на историях о великом королевстве Лордерон...$B$BИ рассказах о его падении.$B$BПлеть лишила меня отца, матери и родины задолго до того, как я стала достаточно взрослой, чтобы все это осознать.', 28153),
(133572, 'ruRU', 'Я готов принять решение.', 'Я готова принять решение.', 28153),
(133571, 'ruRU', 'Животное взбесилось!', '', 28153),
(133570, 'ruRU', '', 'Ну и что ты будешь делать дальше?', 28153),
(133569, 'ruRU', '', 'Я очень благодарна тебе, $n.', 28153),
(133568, 'ruRU', 'Если, прежде чем мы доберемся, ты опять потеряешься, я тебя искать больше не пойду!', '', 28153),
(133567, 'ruRU', 'Давай возвращаться к остальным. У меня столько историй накопилось!', '', 28153),
(133566, 'ruRU', 'Осторожно, у этих троллей не все в порядке с головой. Зачем они едят своих же собратьев?', '', 28153),
(133565, 'ruRU', 'Мм-м... вкусно! Вот бы мне еще немножко. Может, в другой раз...', '', 28153),
(133564, 'ruRU', 'Я так голоден, что и от мяса ящера не отказался бы.', '', 28153),
(133563, 'ruRU', 'Приготовься, смертное создание! Ведь к нам наконец-то вернулся повелитель животных!', '', 28153),
(133562, 'ruRU', 'Меня прислала мастер клинка Каджа.', 'Меня прислала мастер клинка Каджа.', 28153),
(133561, 'ruRU', '', 'Хорошо, что Джулваба все еще жива.', 28153),
(133560, 'ruRU', '', 'Я стольким тебе обязана, $n.', 28153),
(133559, 'ruRU', '', 'Надевай-ка лучше костюм и отправляйся в лагерь. Боюсь, что не сдержусь, если увижу тех, кто тронул Ракиру хоть пальцем.', 28153),
(133558, 'ruRU', 'Наши... сокровища...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(133557, 'ruRU', 'Эти сокровища принадлежат клану Гнусной Чешуи!', '', 28153),
(133556, 'ruRU', 'Мы же простые колбасники! Кому могло прийти в голову напасть на нас?', '', 28153),
(133555, 'ruRU', '', 'Я присмотрю за этим человеком. Если попытается сбежать, мой клинок его остановит.', 28153),
(133554, 'ruRU', 'Я отправляюсь на пляж. Встретимся там, когда добудешь то, что я просил.', '', 28153),
(133553, 'ruRU', 'Подношения на месте. У нас есть все, что нужно, чтобы призвать лоа.', '', 28153),
(133551, 'ruRU', 'В борьбе с этим злом зандаларам пригодится любая помощь. К счастью, Орда готова ее оказать.', '', 28153),
(133548, 'ruRU', '', 'Я присмотрю за ним, чтоб он никуда не делся.', 28153),
(133547, 'ruRU', '', 'Приближается кровавый ураган. Это конец, $n?', 28153),
(133540, 'ruRU', 'Обрушь на них мой гнев, $n. А я должен найти своего лоа, пока еще не поздно.', '', 28153),
(133539, 'ruRU', '', 'Но как... плоть должна была... дать мне... силу...', 28153),
(133538, 'ruRU', '', 'Не бывать этому... Вы не съедите меня, не получите мою силу!', 28153),
(133537, 'ruRU', '', 'Что? Мне было сказано, что я буду становиться сильнее, поедая плоть. Почему ты не умираешь?!', 28153),
(133536, 'ruRU', '', 'От тебя пахнет силой. И она станет моей, когда я тебя съем!', 28153),
(133534, 'ruRU', '', 'Ты не получишь артефакт!', 28153),
(133532, 'ruRU', 'Ах да, как же я глуп... Я забыл подношения! Нельзя призывать лоа с пустыми руками!', '', 28153),
(133527, 'ruRU', 'Хм... что-то явно не так. Идол стоит на алтаре, почему лоа не возвращается?', '', 28153),
(133526, 'ruRU', '', 'Это медальон Ракиры. Такие выдают всем мастерам войны в знак службы королю. По крайней мере, она не сдалась без боя.', 28153),
(133516, 'ruRU', 'Скоро Зул и его последователи узнают, что за отречение от лоа всегда нужно платить.\n\nИ их долг растет с каждой минутой.', '', 28153),
(133515, 'ruRU', '', 'Мы на месте! Что удалось найти?', 28153),
(133514, 'ruRU', '', 'Пойдем дальше. Мы уже близко.', 28153),
(133505, 'ruRU', '', 'Я с вами, мой король. Орда заплатит за все. Я задержу врагов, чтобы дать вам собраться с силами.', 28153),
(133503, 'ruRU', 'Как минимум два – и такие большие! Ах да, спасибо за исцеление.', '', 28153),
(133502, 'ruRU', 'Тебя чуть было не съели, и... сколько, говоришь, копий было в животе?', '', 28153),
(133501, 'ruRU', 'Да ну, Каджош, это было нечто! Воздух пропитан темной магией, тролли творят что-то очень странное. Они мне даже копьями живот проткнули!', '', 28153),
(133500, 'ruRU', 'Дубина! Ты хоть представляешь, как я волновался?!', '', 28153),
(133499, 'ruRU', 'Еле-еле пронесло. Я быстро оправлюсь – этот старый панцирь никуда не денется.', '', 28153),
(133498, 'ruRU', 'Я уже проснулся, видишь? Обязательно было это делать?', '', 28153),
(133497, 'ruRU', '', 'Хорошо, это была моя сигнальная ракета! Где Дрекал?', 28153),
(133496, 'ruRU', 'Ох... Я в порядке, идти могу. Пойду к Каджошу... Наверняка он... э-э... порядком на меня зол!', '', 28153),
(133495, 'ruRU', '', 'Ха... Твой... артефакт... все еще... у Джал\'айи...', 28153),
(133494, 'ruRU', '', 'Тебя мы съедим сразу после тортоллана!', 28153),
(133492, 'ruRU', '', 'На рынок приезжают путешественники со всего Азерота. А это моя любимая таверна!', 28153),
(133490, 'ruRU', '', 'Мне было видение... Зула и Язму нужно остановить, $n!', 28153),
(133489, 'ruRU', 'Меня прислал Каджош. Я разберусь со злобогрызами.', 'Меня прислал Каджош. Я разберусь со злобогрызами.', 28153),
(133488, 'ruRU', 'Если ты не собираешься меня есть... то лучше уходи отсюда! \n\nЗлобогрызы явятся... с минуты на минуту... Придут за своей \"едой\".', '', 28153),
(133487, 'ruRU', 'Вот и они, берегись!', '', 28153),
(133481, 'ruRU', 'Это на Шадру не похоже. Что с ней случилось?', 'Это на Шадру не похоже. Что с ней случилось?', 28153),
(133480, 'ruRU', 'Зул и Язма повинны в измене. Их надо остановить.', 'Зул и Язма повинны в измене. Их надо остановить.', 28153),
(133479, 'ruRU', 'Это была бы жалкая смерть. Спасибо за мое спасение!', 'Это была бы жалкая смерть. Спасибо за мое спасение!', 28153),
(133478, 'ruRU', 'Я расскажу об этом лоа!', 'Я расскажу об этом лоа!', 28153),
(133477, 'ruRU', 'Сегодня отличный день для битвы.', '', 28153),
(133476, 'ruRU', 'Магия крови запрещена! Предателей надо остановить!', '', 28153),
(133475, 'ruRU', 'Я снова... полон сил! Пришло время мести!', '', 28153),
(133474, 'ruRU', 'На этот раз Шадра зашла слишком далеко!', '', 28153),
(133473, 'ruRU', 'Хорошо! Моя сила растет! Остался последний тотем.', '', 28153),
(133472, 'ruRU', 'Иди за Шоаком, а я подожду здесь.', '', 28153),
(133471, 'ruRU', 'Он в храме позади нас. Это было несложно.', '', 28153),
(133470, 'ruRU', 'Ага! Он...', '', 28153),
(133469, 'ruRU', 'Зул заплатит за это!', '', 28153),
(133468, 'ruRU', 'Моя сила возвращается! Скорее, выпусти магию из следующего тотема.', '', 28153),
(133467, 'ruRU', 'Да благословят тебя лоа!', '', 28153),
(133466, 'ruRU', 'Так, в Назмире можно искать долго – Шоак может быть где угодно...', '', 28153),
(133465, 'ruRU', 'Я готов, прочти заклинание, которое поможет найти Шоака.', 'Я готова, прочти заклинание, которое поможет найти Шоака.', 28153),
(133463, 'ruRU', '', 'Как я тебя понимаю. Скоро полетаем, хорошо?', 28153),
(133461, 'ruRU', '(Назад)', '(Назад)', 28153),
(133460, 'ruRU', 'Я бы съел чего-нибудь привычного, но ведь мне никогда не доводилось пробовал мясо ящера. Зачем же упускать шанс попробовать?', '', 28153),
(133459, 'ruRU', 'Часть тотемов уничтожена. Теперь твое заклинание подействует?', 'Часть тотемов уничтожена. Теперь твое заклинание подействует?', 28153),
(133455, 'ruRU', '', 'А вот и моя девочка. Тяжко тебе весь день на месте сидеть?', 28153),
(133450, 'ruRU', 'Сейчас ты умрешь.', 'Сейчас ты умрешь.', 28153),
(133449, 'ruRU', 'Зул пообещал даровать силу тому, кто принесет твою голову.', 'Зул пообещал даровать силу тому, кто принесет твою голову.', 28153),
(133448, 'ruRU', 'Я принесу Зулу твою голову.', 'Я принесу Зулу твою голову.', 28153),
(133447, 'ruRU', 'Я разорву твой разум на части.', 'Я разорву твой разум на части.', 28153),
(133446, 'ruRU', 'Мы пустим тебе кровь.', 'Мы пустим тебе кровь.', 28153),
(133445, 'ruRU', 'Где король?', 'Где король?', 28153),
(133444, 'ruRU', 'Мы насадим твою голову на копье.', 'Мы насадим твою голову на копье.', 28153),
(133443, 'ruRU', 'Жизнь за Зула!', 'Жизнь за Зула!', 28153),
(133438, 'ruRU', '<Поверхность алтаря слегка вогнута, а у каждого угла видны глубокие насечки.$b$bПохоже, когда-то на алтаре возлежало нечто большое и тяжелое.$b$bНо что бы то ни было, теперь алтарь пуст.>', '', 28153),
(133432, 'ruRU', 'Осмотреть алтарь.', 'Осмотреть алтарь.', 28153),
(133430, 'ruRU', '<Кажется, комната пуста.$b$bРезной алтарь перед вами покрыт древними символами зандаларов и изображениями лоа Эрака но Кимбула.$b$bВидимо, на алтаре что-то раньше стояло – может, статуя?>', '', 28153),
(133428, 'ruRU', '', 'Счетную палату охраняют днем и ночью. Можешь спокойно хранить там свое добро.', 28153),
(133412, 'ruRU', 'Занчули видят все!', 'Занчули видят все!', 28153),
(133411, 'ruRU', 'От меня не скроешься!', 'От меня не скроешься!', 28153),
(133410, 'ruRU', 'Зул раскроет твои секреты!', 'Зул раскроет твои секреты!', 28153),
(133409, 'ruRU', 'Прощайся с жизнью!', 'Прощайся с жизнью!', 28153),
(133407, 'ruRU', 'Не стой у меня на пути!', 'Не стой у меня на пути!', 28153),
(133406, 'ruRU', 'Теперь Зандалар принадлежит занчули!', 'Теперь Зандалар принадлежит занчули!', 28153),
(133405, 'ruRU', 'За Зула! За занчули!', 'За Зула! За занчули!', 28153),
(133404, 'ruRU', 'Занчули возьмут то, что принадлежит им по праву!', 'Занчули возьмут то, что принадлежит им по праву!', 28153),
(133403, 'ruRU', 'Твоя сила станет моей!', 'Твоя сила станет моей!', 28153),
(133402, 'ruRU', 'Твоя смерть сделает меня сильнее.', 'Твоя смерть сделает меня сильнее.', 28153),
(133401, 'ruRU', 'Больше крови для Зула!', 'Больше крови для Зула!', 28153),
(133392, 'ruRU', '', 'Паромы ходят по всему внутреннему побережью поморья.', 28153),
(133389, 'ruRU', '', 'Тебе нужен пропуск от капитана порта. Но его нетрудно достать.', 28153),
(133387, 'ruRU', '', 'Не беспокойся насчет побега. Здесь ты ничем не отличаешься от обычных приезжих. Идем, я тебе все покажу.', 28153),
(133380, 'ruRU', '', 'Твою голову я оставлю на потом!', 28153),
(133379, 'ruRU', '', 'Вашего мяса мне надолго хватит!', 28153),
(133374, 'ruRU', '', 'Я обглодаю твои кости!', 28153),
(133372, 'ruRU', '', 'Тащите вертел – к нам идет еда!', 28153),
(133371, 'ruRU', '', 'А, свежая еда!', 28153),
(133370, 'ruRU', '', 'Твои ноги наверняка очень вкусные!', 28153),
(133369, 'ruRU', '', 'О, да у нас здесь еда!', 28153),
(133368, 'ruRU', '', 'Выглядишь очень аппетитно!', 28153),
(133359, 'ruRU', 'Шоак потерялся уже не в первый раз. Надеюсь, хоть сейчас это не какой-нибудь пустяк – раз уж он нам столько хлопот доставил.', '', 28153),
(133357, 'ruRU', 'За работу! Азерит сам себя не добудет.', 'За работу! Азерит сам себя не добудет.', 28153),
(133356, 'ruRU', 'Я готов, пойдем к храму.', 'Я готова, пойдем к храму.', 28153),
(133355, 'ruRU', 'Не надо было доверять этим лживым предателям из племени Тортака! Они убили меня и заперли в этом сосуде на сотню лет... или на две сотни? Я уже даже не помню!', '', 28153),
(133354, 'ruRU', '<Ужасный, полный боли рев раздается над Зеб\'ахари.>', '<Ужасный, полный боли рев раздается над Зеб\'ахари.>', 28153),
(133351, 'ruRU', 'Я отправлюсь на поиски лоа. Когда ты здесь закончишь, встретимся в храме.', '', 28153),
(133350, 'ruRU', 'Наконец-то свобода... Спасибо тебе! Я так ждал, чтобы меня выпустили из этого проклятого кувшина! Тесновато там было – даже для призрака!', '', 28153),
(133349, 'ruRU', '', 'Стены долго не продержатся. Не стоит медлить.', 28153),
(133348, 'ruRU', '', 'Отлично! У меня к тебе тоже есть дело, – война-то не ждет.', 28153),
(133346, 'ruRU', '', 'Кровавый бог... прими меня! Это... еще... не конец...', 28153),
(133345, 'ruRU', '', 'Сейчас или потом – кровавый бог свое возьмет! Ты нас не остановишь!', 28153),
(133344, 'ruRU', '', 'Скорее расскажи обо всем принцессе. Не заставляй ее ждать.', 28153),
(133343, 'ruRU', 'Вставай. Все не так страшно.', '', 28153),
(133342, 'ruRU', 'Не умирать! Еще столько нужно сделать!', '', 28153),
(133341, 'ruRU', 'Вставай! Рано тебе на покой!', '', 28153),
(133340, 'ruRU', 'Восстань! Мы призываем тебя.', '', 28153),
(133339, 'ruRU', 'Восстань!', '', 28153),
(133338, 'ruRU', 'Восстань! Твой король зовет тебя.', '', 28153),
(133337, 'ruRU', 'Я готов сразиться с троллями крови.', 'Я готова сразиться с троллями крови.', 28153),
(133336, 'ruRU', 'Тролли крови подтягивают армию для нового удара по мне и моим детям.$b$bНо на этот раз я буду их убивать!$b$bТы со мной?', '', 28153),
(133325, 'ruRU', 'Ордынцы направляются к казармам!', 'Ордынцы направляются к казармам!', 28153),
(133305, 'ruRU', '', 'Ну, вот, главное я тебе показала. А теперь – к Сайрусу!', 28153),
(133304, 'ruRU', '', 'Правда красавица? Сайрус мне ее совсем маленькой отдал.', 28153),
(133303, 'ruRU', 'Я встану на твою сторону, но сначала мне нужно снова стать сильным. Поможешь?', '', 28153),
(133302, 'ruRU', 'Зентимо верно служил мне. Его дух будет жить среди моих детей.', '', 28153),
(133300, 'ruRU', 'Рэндалл Редмонд плюет на песок.', '', 28153),
(133298, 'ruRU', 'На помощь! Сними их с меня!', '', 28153),
(133297, 'ruRU', '', 'Его раны были слишком серьезными... Мне очень жаль.', 28153),
(133295, 'ruRU', 'Вунанджу? *Рык* Ну конечно...', '', 28153),
(133294, 'ruRU', 'Кто смеет призывать меня в этот ветхий храм?', '', 28153),
(133274, 'ruRU', 'Я пойду первым и подготовлю ритуал. Встретимся на месте.', '', 28153),
(133265, 'ruRU', 'Готовьтесь узреть славу Эрака но Кимбула, лоа тигров, повелителя зверей, короля кошек и грозного охотника!', '', 28153),
(133264, 'ruRU', 'Тебе удалось найти идола! Теперь мы можем призвать лоа...', '', 28153),
(133263, 'ruRU', '', 'Я отведу этого парня к его лоа и убью всех, кого ты пропустишь.', 28153),
(133261, 'ruRU', 'Казармы разрушены! Их надо отремонтировать!', 'Казармы разрушены! Их надо отремонтировать!', 28153),
(133260, 'ruRU', 'Кузница разрушена! Отстройте ее заново!', 'Кузница разрушена! Отстройте ее заново!', 28153),
(133259, 'ruRU', 'Стойла разрушены! Восстановите их!', 'Стойла разрушены! Восстановите их!', 28153),
(133258, 'ruRU', 'Мастерская разрушена! Восстановите ее!', 'Мастерская разрушена! Восстановите ее!', 28153),
(133254, 'ruRU', 'У меня даже оружия нет!', '', 28153),
(133253, 'ruRU', 'Я не хочу умирать!', '', 28153),
(133252, 'ruRU', 'Я не могу работать в таких условиях!', '', 28153),
(133251, 'ruRU', 'Работает! Готовьтесь!', '', 28153),
(133250, 'ruRU', 'Мы испробуем заклинание обратного окаменения. Отойди!', '', 28153),
(133249, 'ruRU', 'Я готов.', 'Я готова.', 28153),
(133248, 'ruRU', 'Если сработает, не рассчитывай, что Ксибала так просто смирится.\n\nНадеюсь, неожиданности не выбьют тебя из колеи. Легко нам его не подчинить.', '', 28153),
(133247, 'ruRU', '', 'Сюда! Здесь раненый!', 28153),
(133240, 'ruRU', '', 'В наших суровых краях многим нужно убежище. Я помогаю, как могу.', 28153),
(133239, 'ruRU', 'Я тут жил еще до того, как зандалары построили вокруг меня дом.', '', 28153),
(133224, 'ruRU', 'Идола нужно вернуться в храм Кимбула. Ты держишь в руках ключ к возвращению лоа!', '', 28153),
(133223, 'ruRU', 'Мой дух слаб, и у меня мало времени. Слушай мои слова внимательно...', '', 28153),
(133214, 'ruRU', 'А теперь пойдем отсюда. Встретимся в святилище под названием Зо\'бал.', '', 28153),
(133213, 'ruRU', 'Ордынский командир пал! Вы победили!', 'Ордынский командир пал! Вы победили!', 28153),
(133212, 'ruRU', 'Гениально! Похоже, орки оставили здесь отличную взрывчатку. Интересно, что будет, если ее сбросить рядом с их уродливыми домишками?', '', 28153),
(133207, 'ruRU', 'Это место давно покинуто всеми, кроме древних духов. На то есть причина. \n\nОрда может получить знания, скрытые здесь, если, конечно, посмеет...', '', 28153),
(133204, 'ruRU', 'Даже в посмертии духи моего народа остаются верны великому лоа Эрака но Кимбулу. Наша вера не угасает со временем. Она сильнее даже оков смерти.', '', 28153),
(133201, 'ruRU', 'Шахта нам просто необходима, но орки ее без боя не отдадут. Предлагаю спуститься в забой и перебить их всех – тогда работники смогут построить казармы.', '', 28153),
(133200, 'ruRU', 'Конец пришел этой образине. Избавься от этого и за работу.', '', 28153),
(133199, 'ruRU', 'Так, бойцы, нам нужно укрепиться здесь, если мы хотим устранить командира-орка и уничтожить его базу раз и навсегда.', '', 28153),
(133198, 'ruRU', '', 'Это ничего... не изменит! Скоро... вы все... умрете!', 28153),
(133197, 'ruRU', 'Ты – первое смертное существо, посетившее мой храм за долгие годы. Приятно, что у меня снова есть последователи среди живых.', '', 28153),
(133158, 'ruRU', '', 'Мы справились. Только представь, что случится, когда этот огромный голем разрушит стены Зулдазара и впустит их в город. Помощь лоа придется нам как нельзя кстати.', 28153),
(133157, 'ruRU', '', 'Посмотри на них! Все они направляются в Зулдазар... осторожно! Не высовывайся!', 28153),
(133156, 'ruRU', '', 'Остров этот к югу отсюда. Я буду ждать тебя там.', 28153),
(133155, 'ruRU', '', 'Сюда. Лодка уже готова. Надеюсь, речных монстров не будет.', 28153),
(133154, 'ruRU', 'Да, вот так!', '', 28153),
(133153, 'ruRU', 'Только не взрывай!', '', 28153),
(133152, 'ruRU', 'БЕЙ, БЕЙ, НЕ ЖАЛЕЙ!', '', 28153),
(133151, 'ruRU', 'Чем могу помочь?', '', 28153),
(133150, 'ruRU', 'Послушай, бери все, что там найдешь. Можешь считать это выражением благодарности.', '', 28153),
(133149, 'ruRU', 'А-А-А... а-а-а...', '', 28153),
(133143, 'ruRU', 'Ты оскверняешь это место своим присутствием! Берегись гнева Ксибалы!', '', 28153),
(133141, 'ruRU', 'Теперь вы можете нанимать в мастерской дворфов-гренадеров.', 'Теперь вы можете нанимать в мастерской дворфов-гренадеров.', 28153),
(133140, 'ruRU', 'Теперь вы можете нанимать стрелков в кузнице.', 'Теперь вы можете нанимать стрелков в кузнице.', 28153),
(133139, 'ruRU', 'Теперь вы можете нанимать рыцарей в стойлах.', 'Теперь вы можете нанимать рыцарей в стойлах.', 28153),
(133138, 'ruRU', 'Теперь в казармах вы можете нанимать пехотинцев.', 'Теперь в казармах вы можете нанимать пехотинцев.', 28153),
(133136, 'ruRU', '', 'Ты уже совсем близко. Первое видение показало мне место у воды.', 28153),
(133133, 'ruRU', '', 'Подношение свежее. Странно. Похоже, у Бвонсамди здесь есть почитатели.', 28153),
(133131, 'ruRU', 'Троллей крови слишком много. Я больше не могу с ними сражаться.', '', 28153),
(133126, 'ruRU', 'Орда потеряла здание. Можно приступать к сооружению кузницы.', 'Орда потеряла здание. Можно приступать к сооружению кузницы.', 28153),
(133125, 'ruRU', 'Орда потеряла здание. Можно приступать к сооружению мастерской.', 'Орда потеряла здание. Можно приступать к сооружению мастерской.', 28153),
(133124, 'ruRU', 'Орда потеряла здание. Теперь вы можете построить стойла.', 'Орда потеряла здание. Теперь вы можете построить стойла.', 28153),
(133123, 'ruRU', '', 'Есть! Следуй за призраком. Давай узнаем, куда делся этот почитатель Бвонсамди.', 28153),
(133122, 'ruRU', '', 'Тролль крови? Похоже, ее принесли в жертву. Смотри, убийца оставил кинжал! Немного вуду, и...', 28153),
(133114, 'ruRU', 'Вытащи меня отсюда!', '', 28153),
(133113, 'ruRU', 'Бомбу уронили!', 'Бомбу уронили!', 28153),
(133112, 'ruRU', 'Бомба взята!', 'Бомба взята!', 28153),
(133111, 'ruRU', 'Бомба сейчас взорвется! Прочь!', 'Бомба сейчас взорвется! Прочь!', 28153),
(133108, 'ruRU', 'Пехотинец [25 фронтовых золотых] |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t', 'Пехотинец [25 фронтовых золотых] |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t', 28153),
(133104, 'ruRU', 'Начнем же.', 'Начнем же.', 28153),
(133103, 'ruRU', '', '', 28153),
(133102, 'ruRU', 'Альянс создает нам немало помех, и работа у нас идет медленно!', 'Альянс создает нам немало помех, и работа у нас идет медленно!', 28153),
(133101, 'ruRU', 'Я бы успевал куда больше, если б не приходилось каждый раз озираться в поисках диверсантов из Альянса...', 'Я бы успевала куда больше, если б не приходилось каждый раз озираться в поисках диверсантов из Альянса...', 28153),
(133100, 'ruRU', 'У Альянса нет прав на эти земли. Зулдазар – территория Орды!', 'У Альянса нет прав на эти земли. Зулдазар – территория Орды!', 28153),
(133099, 'ruRU', 'У нас ничего не получится, пока мы не выгоним этих проклятых дворфов из наших земель!', '', 28153),
(133085, 'ruRU', '', 'Победа будет... за Альянсом...', 28153),
(133084, 'ruRU', '', 'Это участок Лиги исследователей. Тебе нельзя здесь находиться!', 28153),
(133069, 'ruRU', 'За Альянс!', 'За Альянс!', 28153),
(133066, 'ruRU', 'Тебя сюда не звали!', 'Тебя сюда не звали!', 28153),
(133065, 'ruRU', 'Мы заберем эти артефакты!', 'Мы заберем эти артефакты!', 28153),
(133064, 'ruRU', 'Смерть Реликварию!', 'Смерть Реликварию!', 28153),
(133055, 'ruRU', '', 'Привет! А тебе когда-нибудь приходило в голову привязать себе к спине ракету и поджечь ее с завязанными глазами? Мне – да!', 28153),
(133054, 'ruRU', 'Альянс надо истребить! Зулдазар принадлежит Орде!', '', 28153),
(133053, 'ruRU', 'Это невероятно. Какая находка!', '', 28153),
(133048, 'ruRU', '', 'Здесь я донимаю путешественников, прошу их рассказать что-нибудь. Особенно люблю слушать истории из Восточных королевств!', 28153),
(133047, 'ruRU', '', 'А вот и гавань Боралуса. Самая охраняемая часть города после крепости Праудмур. И единственный район, в который пускают чужеземцев.', 28153),
(133045, 'ruRU', '', 'Тебе повезло, что он вообще заплатил. Греби давай!', 28153),
(133044, 'ruRU', 'Альянс?! Теперь ясно, чего Сайрус такой тихий был. Я б содрал с него вдвое больше!', '', 28153),
(133043, 'ruRU', '', 'Ты из Альянса! Вы приплыли сюда вместе с Джайной Праудмур!', 28153),
(133042, 'ruRU', '', 'Погоди... Я тебя знаю...', 28153),
(133041, 'ruRU', 'О! И спас кого надо, конечно. Коллега, это Телия. Телия, коллега.', '', 28153),
(133040, 'ruRU', '', 'Что там происходит? Вы что, бунт устроили?', 28153),
(133039, 'ruRU', 'Не понимаю, о чем ты. Зато я нашел-таки компромат на Эшвейнов.', '', 28153),
(133038, 'ruRU', 'Вот и она! Запрыгивай.', '', 28153),
(133037, 'ruRU', 'Давай спустимся вниз, там должен быть выход.', '', 28153),
(133036, 'ruRU', 'Так-то лучше. Без них я будто голый! Погнали.', '', 28153),
(133013, 'ruRU', '', 'У нас есть мех для ковров, мех для шуб, мех для чего угодно!', 28153),
(133012, 'ruRU', '', 'Мех для тепла, мех для удобства, мех для дела!', 28153),
(133011, 'ruRU', '', 'Лучшие меха со всего Кул-Тираса!', 28153),
(133009, 'ruRU', '', 'У меня самые надежные изобретения во всем Тирагарде, и это факт!', 28153),
(133008, 'ruRU', '', 'Не доверяй другим гномским изобретениям! Все мои конкуренты – шарлатаны!', 28153),
(133007, 'ruRU', '', 'Ты больше нигде не найдешь таких качественных устройств и гаджетов, как у меня!', 28153),
(133001, 'ruRU', 'Ух ты! Он... Он растет?! Ой!', 'Ух ты! Он... Он растет?! Ой!', 28153),
(132999, 'ruRU', 'Пробуждение...', 'Пробуждение...', 28153),
(132994, 'ruRU', 'Маги, возвращаемся в лагерь. Нам столько нужно изучить!', '', 28153),
(132993, 'ruRU', 'Тьфу! Хана ключикам. Вот это я понимаю, огневая мощь.', '', 28153),
(132992, 'ruRU', 'Хватай свой шмот. Пошли найдем надзирателя и заберем его ключи!', '', 28153),
(132991, 'ruRU', 'Похоже, тут не выбраться. Попробуем в другую сторону.', '', 28153),
(132990, 'ruRU', 'Доступно: казармы', 'Доступно: казармы', 28153),
(132989, 'ruRU', 'Бунт, ребятки! Задайте им!', '', 28153),
(132988, 'ruRU', '[Двери камер распахиваются. Заключенные выбегают и несутся по коридору.]', '[Двери камер распахиваются. Заключенные выбегают и несутся по коридору.]', 28153),
(132987, 'ruRU', 'Ордынцы направляются к мастерской!', 'Ордынцы направляются к мастерской!', 28153),
(132986, 'ruRU', 'Появление пехотинца', 'Появление пехотинца', 28153),
(132985, 'ruRU', 'Казармы захвачены, ведется восстановление.', 'Казармы захвачены, ведется восстановление.', 28153),
(132981, 'ruRU', 'Ордынцы направляются к стойлам!', 'Ордынцы направляются к стойлам!', 28153),
(132980, 'ruRU', 'Орда направляется к кузнице!', 'Орда направляется к кузнице!', 28153),
(132969, 'ruRU', '', 'Мам, там ребята играют без меня! Можно мне с ними? Ну пожа-а-алуйста!', 28153),
(132968, 'ruRU', '', 'Мне скучно! Можно мне пойти поиграть?', 28153),
(132967, 'ruRU', '', 'Я все дела сделала?', 28153),
(132966, 'ruRU', 'DELETE ME', '', 28153),
(132957, 'ruRU', '', 'Это старье?$B$B<Она искренне смеется.>$B$BПосмотри вокруг. Как думаешь, откуда оно у меня?', 28153),
(132955, 'ruRU', 'Интересный щит. Откуда он у тебя?', 'Интересный щит. Откуда он у тебя?', 28153),
(132954, 'ruRU', '', 'Может, ростом я и не вышла, но молотом могу махать лучше, чем то отребье из Орды, что тебе здесь встретится.', 28153),
(132945, 'ruRU', 'Что ты здесь делаешь?', 'Что ты здесь делаешь?', 28153),
(132944, 'ruRU', 'У нас как раз есть калибр им по размеру. Огонь!', '', 28153),
(132943, 'ruRU', 'А вот и морской великан! Тот самый, что развалил наш корабль! Пора платить по счетам!', '', 28153),
(132941, 'ruRU', 'Слушай... Я... э-э... забыл, что хотел сказать, но лучше ничего здесь не трогай.$B$BА то зальешь мне кровью все оборудование.', '', 28153),
(132940, 'ruRU', 'Высоким нужно больше времени на то, чтобы их эмоции достигли кульминации.$B$BПодожди немного.', '', 28153),
(132939, 'ruRU', 'Нам нужно провести пристрелку пушки, прежде чем отправляться в большое сражение. Почему бы не избавиться заодно от нескольких наг?', '', 28153),
(132938, 'ruRU', 'Берегись! Нас обстреливают из пушек! Накрой их кассетным залпом!', '', 28153),
(132935, 'ruRU', 'Под нами! Берегитесь!', '', 28153),
(132932, 'ruRU', '', 'И правда... Летим на запад, чтобы не попасться им на глаза.', 28153),
(132931, 'ruRU', 'Как видишь, больше не прячутся.', '', 28153),
(132928, 'ruRU', 'Что тебя интересует? Комната? Мои товары?', 'Что тебя интересует? Комната? Мои товары?', 28153),
(132926, 'ruRU', 'Все готово к испытанию. Запрыгивай – и погнали.', '', 28153),
(132924, 'ruRU', 'Дергай рычаг, живо!', '', 28153),
(132923, 'ruRU', 'Идем. Лодка будет ждать нас прямо у берега.', '', 28153),
(132922, 'ruRU', '', 'Расступись! Это золото мое по праву!', 28153),
(132920, 'ruRU', 'Пятьдесят тысяч золотых тому, кто первый добежит до точки сбора!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(132918, 'ruRU', 'Я тут смастерил несколько мин для защиты территории.', '', 28153),
(132917, 'ruRU', 'Официально заявляю. Я сваливаю отсюда.', '', 28153),
(132916, 'ruRU', 'Фу... Вонь, как будто флибустьер портянки сушит.', '', 28153),
(132915, 'ruRU', 'Команда, вперед!', '', 28153),
(132912, 'ruRU', 'Что за жизнь без риска? А как же дух игры? Тебе срочно нужно в казино.', '', 28153),
(132911, 'ruRU', '', 'Вполне достаточно. Зачем рисковать? Чтобы сорвать сделку?', 28153),
(132910, 'ruRU', 'Всего восемьдесят? Ты чего? Где твоя деловая хватка?', '', 28153),
(132909, 'ruRU', 'С возвращением в \"Золотой клык\", сестренка. Здесь тебе всегда рады.\n\nОтдохни и расслабься, а потом давай выпьем чего-нибудь!', '', 28153),
(132908, 'ruRU', 'С возвращением в \"Золотой клык\", братишка. Здесь тебе всегда рады.\n\nОтдохни и расслабься, а потом давай выпьем чего-нибудь!', '', 28153),
(132907, 'ruRU', 'Что ты делаешь? Это мое!', 'Что ты делаешь? Это мое!', 28153),
(132906, 'ruRU', 'На помощь! Диверсанты!', 'На помощь! Диверсанты!', 28153),
(132905, 'ruRU', 'Это очень хрупкое оборудование!', 'Это очень хрупкое оборудование!', 28153),
(132904, 'ruRU', 'Эй! А ну не трожь мое добро!', 'Эй! А ну не трожь мое добро!', 28153),
(132897, 'ruRU', 'Выпусти меня из клетки! Я ни в чем не виноват, клянусь!', 'Выпусти меня из клетки! Я ни в чем не виновата, клянусь!', 28153),
(132893, 'ruRU', 'Согласен, Гренджа. $p отлично справится, если Зулсан не вернется.', '', 28153),
(132891, 'ruRU', 'Кому вообще пришло в голову пройти возле этого проклятого грота?', 'Кому вообще пришло в голову пройти возле этого проклятого грота?', 28153),
(132890, 'ruRU', 'Наконец-то пение прекратилось!', 'Наконец-то пение прекратилось!', 28153),
(132889, 'ruRU', 'Это... эль?', 'Это... эль?', 28153),
(132880, 'ruRU', 'Хех, эта шутка никогда не устареет.', '', 28153),
(132879, 'ruRU', 'Я вскипятил кровь и смешал ее с жалами в церемониальном кубке \"Золотого клыка\". Да, это ананас. Не ешь его. Другого у нас нет.', '', 28153),
(132877, 'ruRU', 'Моя шкура спасена! Спасибо тебе!', '', 28153),
(132876, 'ruRU', 'Спасибо! И до встречи!', '', 28153),
(132849, 'ruRU', 'Теперь я вижу, что чуть не угодил в зловещую ловушку... спасибо тебе!', 'Теперь я вижу, что чуть не угодила в зловещую ловушку... спасибо тебе!', 28153),
(132848, 'ruRU', 'Не знаю, что на меня нашло...', 'Не знаю, что на меня нашло...', 28153),
(132847, 'ruRU', 'Пожалуйста, спаси остальных... Я немедленно отправлюсь к Кимбулу.', 'Пожалуйста, спаси остальных... Я немедленно отправлюсь к Кимбулу.', 28153),
(132846, 'ruRU', 'Мне изрядно досталось... спасибо тебе.', 'Мне изрядно досталось... спасибо тебе.', 28153),
(132845, 'ruRU', 'Этот обман едва не стоил мне души...', 'Этот обман едва не стоил мне души...', 28153),
(132844, 'ruRU', 'Теперь я понял, это были просто чары. Я отправлюсь к Кимбулу...', 'Теперь я поняла, это были просто чары. Я отправлюсь к Кимбулу...', 28153),
(132843, 'ruRU', 'Меня манил всепоглощающий свет. Благодарю тебя за спасение...', 'Меня манил всепоглощающий свет. Благодарю тебя за спасение...', 28153),
(132841, 'ruRU', '', 'Я не протяну долго без еды и воды. Весь день ходила кругами, а потом поняла, что у меня нет выбора: придется довериться бреду сумасшедшего. Пойду на юг. Может быть, там и правда есть убежище.', 28153),
(132840, 'ruRU', '', 'Ночью солдаты Джакра\'зета напали на наш лагерь. Многие из нас уже были обессилены, и ни у кого не было оружия. Мне еле удалось отбиться, но остальные выжившие разбежались и потерялись в песках. Теперь каждому из них придется выживать в одиночку.', 28153),
(132839, 'ruRU', '', 'Наконец-то закат. От невыносимой жары у многих начался бред. Один из наших особенно плох: он все время говорит о храме на юге, где все изгои найдут убежище. Вряд ли бедняга переживет эту ночь.', 28153),
(132838, 'ruRU', '', 'Я пишу этот дневник в клетке: меня и остальных изгнанников везут в пустыню, где мы проведем остаток дней. Судя по раскаленному воздуху, мы почти на месте.', 28153),
(132830, 'ruRU', '', 'Слишком поздно... лоа... все станут едой... для Кровавого бога.', 28153),
(132827, 'ruRU', 'Наги за это заплатят!', '', 28153),
(132826, 'ruRU', 'Огромное тебе спасибо!', '', 28153),
(132825, 'ruRU', 'Я у тебя в долгу!', '', 28153),
(132824, 'ruRU', 'Свобода!', '', 28153),
(132823, 'ruRU', 'Я обязан тебе жизнью. Гадюки заплатят за то, что сделали с нашим домом...', 'Я обязана тебе жизнью. Гадюки заплатят за то, что сделали с нашим домом...', 28153),
(132821, 'ruRU', '<Взять письмо.>', '<Взять письмо.>', 28153),
(132752, 'ruRU', 'Ниша, ты цела! Хвала пустыне!', '', 28153),
(132737, 'ruRU', '', 'Воистину, он самый добрый человек, которого мне довелось знать.', 28153),
(132736, 'ruRU', '%s бросается к вам, словно хочет вас остановить, но затем отходит, успокаивается и опять смотрит куда-то вдаль.', '', 28153),
(132735, 'ruRU', 'Ха, в первый раз ритуальная кровь скорпида всегда плохо заходит. Не держи в себе. Дальше будет легче.', '', 28153),
(132734, 'ruRU', 'Зулдазар нас предал. Нас изгнали, как каких-то чужеземцев. Но мы не предали друг друга. Мы в \"Золотом клыке\" – одна семья.', '', 28153),
(132733, 'ruRU', 'О, какая сладкая кровь... Выпей, $p, и увидишь то, что вижу я!', '', 28153),
(132714, 'ruRU', 'Профессиональное оружие для охотников любого уровня!', '', 28153),
(132713, 'ruRU', 'Идешь на охоту? Если нужно закупиться, лучшего места не найти!', '', 28153),
(132712, 'ruRU', 'Огнестрельное оружие, боеприпасы и взрывчатка для охотников любого уровня!', '', 28153),
(132711, 'ruRU', 'Молодой дикорог сонно зевает.', '', 28153),
(132710, 'ruRU', 'А, это? Этим я кормлю своих телохранителей. Хочешь купить? Продам по выгодной цене!', '', 28153),
(132696, 'ruRU', 'Все кончилось? Можно выходить?', '', 28153),
(132692, 'ruRU', 'Ха! Да, я знаю, что герой тебя даже не видит. Думает, я чокнутый. Ха!', '', 28153),
(132691, 'ruRU', 'Не переживай. Наш герой тебя даже не видит. Думает, я чокнутый. Ха!', '', 28153),
(132690, 'ruRU', 'Зулсан, тебя спасли! Я так рад!', '', 28153),
(132688, 'ruRU', 'Привет, $n! Торговый принц говорит, что пора начинать зарабатывать. Дай знать, если прослышишь о каких-нибудь сделках.', '', 28153),
(132684, 'ruRU', '', 'Дорогу невесте, дорогу невесте!', 28153),
(132683, 'ruRU', 'Сюда!', 'Сюда!', 28153),
(132682, 'ruRU', 'Впере-е-ед! Ты сможешь!', 'Впере-е-ед! Ты сможешь!', 28153),
(132681, 'ruRU', '<Шепнуть, что глазная повязка выглядит по-дурацки.>', '<Шепнуть, что глазная повязка выглядит по-дурацки.>', 28153),
(132680, 'ruRU', 'Можно мне взять твое добро?', 'Можно мне взять твое добро?', 28153),
(132679, 'ruRU', 'Твоя глазная повязка внушает страх.', 'Твоя глазная повязка внушает страх.', 28153),
(132678, 'ruRU', '<Глазная повязка Ман\'зула дергается от наполняющей ее магии.>', '', 28153),
(132677, 'ruRU', '<Постараться победить Гренджу, играя в гляделки.>', '<Постараться победить Гренджу, играя в гляделки.>', 28153),
(132676, 'ruRU', 'Наверняка тобой можно двери подпирать.', 'Наверняка тобой можно двери подпирать.', 28153),
(132675, 'ruRU', 'Рад встрече!', 'Рада встрече!', 28153),
(132674, 'ruRU', '<Гренджа выглядит на удивление довольной, учитывая, что она всего лишь череп.>', '', 28153),
(132673, 'ruRU', 'А ну тихо все! У нас гости.', '', 28153),
(132672, 'ruRU', '<Вежливо представиться.>', '<Вежливо представиться.>', 28153),
(132671, 'ruRU', '<Пробормотать о том, что вы не видите во всем этом смысла.>', '<Пробормотать о том, что вы не видите во всем этом смысла.>', 28153),
(132670, 'ruRU', 'Шляпа у тебя ничего.', 'Шляпа у тебя ничего.', 28153),
(132669, 'ruRU', 'Эм... Привет?', 'Эм... Привет?', 28153),
(132668, 'ruRU', 'Ух ты! Что это было? Чувствую себя просто отлично.', '', 28153),
(132667, 'ruRU', '', '<На черепе Волни застыла гримаса ужаса.>', 28153),
(132663, 'ruRU', '', 'Наши пряности придают любому блюду потрясающий цвет и аромат! Тебе понравится.', 28153),
(132662, 'ruRU', '', 'Качественные специи со всего Азерота!', 28153),
(132661, 'ruRU', '', 'Забудь про безвкусную еду! Взгляни на мои специи!', 28153),
(132657, 'ruRU', 'А-а-а! Постарайся отвлечь его игрушкой!', 'А-а-а! Постарайся отвлечь его игрушкой!', 28153),
(132656, 'ruRU', 'Ищешь рыбное место? Лучшая рыба на этом рынке – у меня!', 'Ищешь рыбное место? Лучшая рыба на этом рынке – у меня!', 28153),
(132655, 'ruRU', 'Что может быть лучше, чем только что выловленная рыба на ужин!', 'Что может быть лучше, чем только что выловленная рыба на ужин!', 28153),
(132654, 'ruRU', 'Рыба, свежий улов прямо с лодок клыкарров!', 'Рыба, свежий улов прямо с лодок клыкарров!', 28153),
(132653, 'ruRU', 'Сэр! Похоже, что к лагерям Орды на юго-востоке прибывает подкрепление. Сэр, кажется, они готовятся к атаке.', '', 28153),
(132651, 'ruRU', 'Не своди с них глаз! Кто двинется – ты знаешь, что делать.', '', 28153),
(132650, 'ruRU', 'Флинтвуд! Есть новости?', '', 28153),
(132648, 'ruRU', 'Спасение', 'Спасение', 28153),
(132646, 'ruRU', 'Огонь!', 'Огонь!', 28153),
(132645, 'ruRU', 'Ты, должно быть, $gтот самый посланник:та самая посланница; Орды, о котором все говорят. И у тебя есть детеныш дикорога? Повелительница ящеров наверняка захочет на него взглянуть. Проходи.', 'Ты, должно быть, $gтот самый посланник:та самая посланница; Орды, о котором все говорят. И у тебя есть детеныш дикорога? Повелительница ящеров наверняка захочет на него взглянуть. Проходи.', 28153),
(132636, 'ruRU', '', 'Как интересно...', 28153),
(132635, 'ruRU', '', 'Давай посмотрим, что тут у нас.', 28153),
(132634, 'ruRU', '', 'Поосторожнее там.', 28153),
(132629, 'ruRU', 'Используйте спринт, чтобы бежать быстрее!', 'Используйте спринт, чтобы бежать быстрее!', 28153),
(132628, 'ruRU', '', 'Мы убьем охотников и вернем твои тотемы.', 28153),
(132626, 'ruRU', '', 'Когда зандалары поймут, что ты на их стороне, у тебя снова появятся сторонники.', 28153),
(132624, 'ruRU', '', 'Ты могучий лоа. Вместе с тобой мы сокрушим троллей крови!', 28153),
(132622, 'ruRU', '', 'Великий Краг\'ва! Мы пришли просить тебя о помощи!', 28153),
(132620, 'ruRU', 'Я тебя поймал! Теперь твой черед!', '', 28153),
(132619, 'ruRU', 'Чур-чура! Ты водишь!', '', 28153),
(132613, 'ruRU', 'Используй частицу моей силы, чтобы Зентимо присоединился к моим детям.', '', 28153),
(132611, 'ruRU', '', '', 28153),
(132609, 'ruRU', 'Нападение было таким внезапным... мы... не смогли остановить их.', 'Нападение было таким внезапным... мы... не смогли остановить их.', 28153),
(132608, 'ruRU', 'Гигант... сокрушил нас...', 'Гигант... сокрушил нас...', 28153),
(132607, 'ruRU', 'Оружие... уничтожено...', 'Оружие... уничтожено...', 28153),
(132606, 'ruRU', 'Н... наги... повсюду!', 'Н... наги... повсюду!', 28153),
(132605, 'ruRU', 'Спа... спасибо!', 'Спа... спасибо!', 28153),
(132604, 'ruRU', 'Значит, вот как.', 'Значит, вот как.', 28153),
(132603, 'ruRU', 'Трус!', 'Трус!', 28153),
(132602, 'ruRU', 'Живым я не дамся!', 'Живой я не дамся!', 28153),
(132601, 'ruRU', 'Бесчестная тварь!', 'Бесчестная тварь!', 28153),
(132600, 'ruRU', 'Жалкое ничтожество!', 'Жалкое ничтожество!', 28153),
(132599, 'ruRU', 'Это смелый поступок – явиться сюда на Великую охоту. Сегодня точно будет что-то интересное, как считаешь?', '', 28153),
(132581, 'ruRU', 'Хватит возиться с букашками. Убьем их вождя.', '', 28153),
(132580, 'ruRU', 'Я больше не буду терпеть! Сокрушим этих троллей! Я Краг\'ва, а они – моя добыча!', '', 28153),
(132579, 'ruRU', 'Молодец, $n. Тебе удалось полностью доказать свою силу и храбрость. Возвращайся в храм и возьми свою награду.', '', 28153),
(132573, 'ruRU', 'В последний раз ранишу сожрали четыре каравана. Теперь это не повторится.', '', 28153),
(132572, 'ruRU', 'В Вол\'дун забрела стая брутозавров, и у ранишу появился неисчерпаемый источник пищи! Сократи их число, пока это еще возможно.', '', 28153),
(132571, 'ruRU', 'Если доказать свою силу и вернуться с подношениями, лоа даруют благословение.', '', 28153),
(132566, 'ruRU', 'Твое служение этому храму было достойно, $n. Взамен я благословлю тебя, если захочешь.', '', 28153),
(132565, 'ruRU', 'Нам нужно выяснить, где находится пещера заклинателя клыков, и незамедлительно убить его. От этого зависит безопасность храма!', '', 28153),
(132564, 'ruRU', 'Если не выгнать из каньона сетраков, храм будет в опасности.', '', 28153),
(132563, 'ruRU', 'Я принимаю твои подношения. Прошу, подойди ближе, эти старые глаза уже не те, что раньше.', '', 28153),
(132562, 'ruRU', 'Похоже, у нас гости, Джал\'Нанджи. Пожалуйста, посмотри, кто к нам пришел.', '', 28153),
(132560, 'ruRU', 'Вот это – настоящая охота!', '', 28153),
(132550, 'ruRU', 'Великий рокочущий ящер позволил нам укрыться в храме. Если лоа не против, здесь тебе будут рады.', '', 28153),
(132549, 'ruRU', 'НЕ-Е-ЕТ! Он уходит с нашей \"КМЖС\"! Если мы ее не вернем, то не расплатимся до конца жизни!', '', 28153),
(132547, 'ruRU', 'Удалось достать, что нужно?', '', 28153),
(132545, 'ruRU', '<Вы видите сотни фитилей, ведущих к маленьким сосудам со светящимся порошком.>', '', 28153),
(132544, 'ruRU', '<Клинки всех сабель в этом контейнере отливают знакомым цветом.>', '', 28153),
(132541, 'ruRU', '<В этом контейнере аккуратно уложены тысячи мушкетных зарядов.>', '', 28153),
(132537, 'ruRU', '<Из контейнера исходит специфический запах пороха.>', '', 28153),
(132536, 'ruRU', '<Вы снимаете с контейнера покрывало и видите блеск оружейного металла.>', '', 28153),
(132534, 'ruRU', 'Вот уж не подумал бы, что полезу на рожон из-за Сайруса во второй раз.$B$BХотя я даже не думал, что мы оба доживем до этого второго раза...', '', 28153),
(132533, 'ruRU', 'Когда узнаешь что-нибудь о поставках пороха – встретимся там.', '', 28153),
(132532, 'ruRU', 'Скажи детям, чтобы шли к западному краю литейной. Я буду ждать там и прослежу, чтобы их никто не тронул.', '', 28153),
(132531, 'ruRU', 'Кагни на своем пароме выловил эту девочку из воды. Она говорит, что сбежала из литейной.$B$BТо, что корпорация Эшвейнов использует детский труд, меня нисколько не удивляет. Я был ненамного старше ее, когда в Боралусе банды заставляли меня отвлекать стражников или обчищать карманы.$B$BЧем ты слабее, тем больше людей хочет нажиться за твой счет – такой уж у нас мир.', '', 28153),
(132495, 'ruRU', '', 'Г\'уун... это не то... что ты обещал...', 28153),
(132494, 'ruRU', '', 'Твоя душа принадлежит Г\'ууну!', 28153),
(132493, 'ruRU', '', 'Нет! Я... еще... не готова...', 28153),
(132492, 'ruRU', '', 'Как ты смеешь беспокоить меня в моей скорби? Ты об этом пожалеешь!', 28153),
(132453, 'ruRU', '', 'Я уж думала, что задохнусь! Спасибо за помощь!', 28153),
(132450, 'ruRU', '', 'Трит хватает ртом воздух.', 28153),
(132444, 'ruRU', 'Сюда!', 'Сюда!', 28153),
(132416, 'ruRU', 'Держись рядом!', '', 28153),
(132415, 'ruRU', 'Нам нужно в сад лоа, пока еще не поздно. Торопись!', '', 28153),
(132408, 'ruRU', '', 'Спасибо за всю твою помощь. Зем\'лан еще опаснее, чем гласят легенды.', 28153),
(132406, 'ruRU', 'Давно я не попадала в такое затруднительное положение. Спасибо, $n!', '', 28153),
(132404, 'ruRU', '', 'Когда я доберусь до Язмы и ее паучьей секты... ох, сколько крови прольется.', 28153),
(132403, 'ruRU', '$ct, спасибо тебе. За Орду!', '$ct, спасибо тебе. За Орду!', 28153),
(132398, 'ruRU', 'У меня нет времени болтать попусту.', '', 28153),
(132396, 'ruRU', 'Зачем ты такое спрашиваешь? Хочешь в пустыню отправиться?', '', 28153),
(132376, 'ruRU', '', 'Я заставлю тебя ответить за это...', 28153),
(132374, 'ruRU', 'А-а-а!', 'А-а-а!', 28153),
(132365, 'ruRU', 'Лоа вернулся в храм.', 'Лоа вернулся в храм.', 28153),
(132364, 'ruRU', 'Здесь небезопасно. Уходи, пока еще не поздно.', 'Здесь небезопасно. Уходи, пока еще не поздно.', 28153),
(132343, 'ruRU', 'За теми руинами есть отличное укромное место для базы. Скажи остальным, чтобы собирались там.', '', 28153),
(132342, 'ruRU', 'Кра\'гва бросает беглый взгляд на светлячков – ему нравится их свет.', '', 28153),
(132340, 'ruRU', 'Кра\'гва заглатывает мясо в мгновенье ока!', '', 28153),
(132325, 'ruRU', 'Оскорбляешь меня? Убирайся!', '', 28153),
(132324, 'ruRU', 'Краг\'ва приходит в исступление! Надо было быть проворнее!', '', 28153),
(132323, 'ruRU', 'Я принимаю подношение. А теперь покажи, что умеешь.', '', 28153),
(132322, 'ruRU', 'Краг\'ва раздраженно озирается. Кажется, ему становится скучно. Отвлеките его!', '', 28153),
(132321, 'ruRU', 'Кра\'гва облизывает губы и пристально смотрит на вас с голодным выражением лица. Покормите его!', '', 28153),
(132320, 'ruRU', 'О, подношения! Хорошо! Ты проживешь немного дольше.', '', 28153),
(132310, 'ruRU', 'Использовать маску духов', 'Использовать маску духов', 28153),
(132308, 'ruRU', 'Могучий Кра\'гва, я подношу тебе этот дар из плоти и мух.', 'Могучий Кра\'гва, я подношу тебе этот дар из плоти и мух.', 28153),
(132307, 'ruRU', 'Ты – друг лягух. Я не стану тебя есть.', '', 28153),
(132306, 'ruRU', 'Эй ты! Хочешь забрать моих детей? Я тебя съем.', '', 28153),
(132297, 'ruRU', 'Похоже, сюда ведет тропа...', '', 28153),
(132296, 'ruRU', 'В чем дело, Нотли?', '', 28153),
(132294, 'ruRU', 'Я тут собрал несколько камней – возьми их. Я уже стар и не могу носить с собой много всякого добра, как раньше. О-хо-хо!', '', 28153),
(132293, 'ruRU', 'О, здравствуй, не поможешь ли старику? Я тут попал в затруднительное положение.', '', 28153),
(132289, 'ruRU', 'Я придумаю, как все утрясти. Не беспокойся.', '', 28153),
(132288, 'ruRU', 'Грязная Борода говорит спасибо! Вот, держи блестяшки, они приносят мне несчастье.', '', 28153),
(132287, 'ruRU', '', 'Эй, мне не помешала бы твоя помощь!', 28153),
(132279, 'ruRU', '', 'Нам нужно укрепить позиции. Только мы можем спасти мою родину от неминуемой гибели.', 28153),
(132275, 'ruRU', '', 'Как ты смеешь осквернять наше последнее пристанище!', 28153),
(132274, 'ruRU', '', 'Уходи! Мы хотим страдать в одиночестве!', 28153),
(132267, 'ruRU', 'Неловко получилось. Но, по крайней мере, мое ружье нашлось.', '', 28153),
(132266, 'ruRU', 'Люблю разнообразие в охоте. А то вечно тролли крови да тролли крови.', '', 28153),
(132265, 'ruRU', 'Не двигайся. Твою голову мне нужно отрубить аккуратно.', '', 28153),
(132264, 'ruRU', 'Передавай привет Бвонсамди.', '', 28153),
(132263, 'ruRU', 'Подойди, не стесняйся.', '', 28153),
(132262, 'ruRU', 'Смотри под ноги...', '', 28153),
(132261, 'ruRU', 'Твоя голова мне пригодится.', '', 28153),
(132260, 'ruRU', 'Выходи, крошка |3-6($r), поиграем!', '', 28153),
(132254, 'ruRU', '', 'Засада!', 28153),
(132243, 'ruRU', '', 'Я решила отправиться в Восточный приют. Надеюсь, их не постигла та же судьба, что и Гленбрук.', 28153),
(132240, 'ruRU', '', 'Я чувствую злость и горе. Что бы ни случилось в этом месте, все явно закончилось плохо.', 28153),
(132237, 'ruRU', '<Вы видите, что неумолимые челюсти капкана вонзились в ногу павшего охотника.$B$BЕго доспехи в нескольких местах пробиты дротиками.$B$BНа лице охотника застыло удивленное выражение. Он так и не понял, что его убило.>', '', 28153),
(132236, 'ruRU', '', 'Песик, поиграй с гостем! У меня гости не уходят голодными. И вообще не уходят!', 28153),
(132221, 'ruRU', 'ВСТАВИТЬ ТИР', '', 28153),
(132205, 'ruRU', 'Джайну отправили в ссылку всего несколько дней назад. Если поторопимся, можем найти ее... пока еще не поздно.', '', 28153),
(132201, 'ruRU', '', 'Ты заплатишь за гибель моих сестер!', 28153),
(132190, 'ruRU', 'Повелительница ящеров говорит, что ты теперь с нами, так что можешь оставаться здесь. Но мы все равно будем за тобой присматривать.', '', 28153),
(132189, 'ruRU', '', 'От полета на терродактиле просто кровь стынет в жилах! Держись крепче!', 28153),
(132188, 'ruRU', 'Хорошо, отсюда и начнем.', '', 28153),
(132187, 'ruRU', 'Скорее всего, она пошла по дороге в надежде найти укрытие.', '', 28153),
(132186, 'ruRU', 'Мы что-нибудь придумаем, когда найдем Джайну, Мейс. Йоррик, что скажешь?', '', 28153),
(132185, 'ruRU', '', 'Есть у меня подозрение, что обратно нас не впустят...', 28153),
(132180, 'ruRU', '', 'Нам сюда, вот нужная тропа!', 28153),
(132179, 'ruRU', 'Чего тебе нужно от старого Бвонсамди?', '', 28153),
(132178, 'ruRU', 'Неплохо, неплохо! Может, у тебя есть задатки жнеца душ!', '', 28153),
(132177, 'ruRU', 'Как ты смеешь осквернять мой труп!', '', 28153),
(132169, 'ruRU', 'Альянс предлагает большую награду тому, кто вернет Джайну.', 'Альянс предлагает большую награду тому, кто вернет Джайну.', 28153),
(132168, 'ruRU', 'Так, значит, в Друстваре? Ты шутишь?!\n\nНет уж, мое место здесь, у стены, а моя работа – поставлять припасы этим славным воинам! Только глупец по своей воле отправится за эти ворота!', '', 28153),
(132152, 'ruRU', '', 'Признаю, ты достойный боец. Я помогу маршалу.', 28153),
(132149, 'ruRU', '', 'Назад дороги уже нет, Йоррик. Денхольм вряд ли простит стражника, напавшего на своих, – даже если он просто исполнял приказ.', 28153),
(132148, 'ruRU', 'Джайна?! Она – цель этой экспедиции? Но это же предательство!', '', 28153),
(132146, 'ruRU', 'Мне необходимо пойти на этот риск, капитан. Солдаты, за мной.', '', 28153),
(132145, 'ruRU', 'Рид, ты вправе, конечно, отказаться, но королева об этом узнает! И ты больше никогда не сможешь показаться в Боралусе!', '', 28153),
(132144, 'ruRU', 'Хватит, я сдаюсь!', '', 28153),
(132143, 'ruRU', 'На это нет времени! Солдаты, в бой!', '', 28153),
(132142, 'ruRU', 'Королева приказала никого не пропускать через ворота. Даже тебя.', '', 28153),
(132141, 'ruRU', 'Капитан Денхольм, у меня для этих солдат особое задание. Я приказываю вам отойти и пропустить нас!', '', 28153),
(132140, 'ruRU', 'Стоять! И куда это ты направляешься с моими людьми, маршал?', '', 28153),
(132139, 'ruRU', 'То, что надо! Скажи маршалу Риду, что интендант Нотли прибыл к месту службы!', '', 28153),
(132138, 'ruRU', 'Я... позаимствую здесь то, что нам нужно...', '', 28153),
(132137, 'ruRU', 'Награда, говоришь? Ну, это все меняет...', '', 28153),
(132136, 'ruRU', 'Прекратить огонь! Похоже, они пустились наутек.', '', 28153),
(132135, 'ruRU', 'Возьми арбалет и помоги мне!', '', 28153),
(132134, 'ruRU', 'Если я ему нужен, я приду, но считаю просто халатностью уйти и ничего не сделать с этими зверями.', '', 28153),
(132133, 'ruRU', 'Я предполагал, что маршал здесь не просто так, но я бы на твоем месте произносил это имя шепотом...', '', 28153),
(132132, 'ruRU', '', 'Давай договоримся: покажешь мне свой пыл – и я помогу Риду в этом его приключении. К бою!', 28153),
(132131, 'ruRU', '', 'Мертволесье меня вовсе не пугает, но вот возиться с чужаком, который за мной не поспевает, нет никакого желания.', 28153),
(132130, 'ruRU', '', '$R, добро пожаловать на Великую охоту. Здесь можно охотиться на все, что движется.$b$bУ нас в почете те, кто приносит с охоты самые лучшие трофеи.', 28153),
(132129, 'ruRU', 'Будь осторожней. У этой ведьмы сильное моджо!', '', 28153),
(132128, 'ruRU', 'Древняя табличка вот-вот рассыплется. Она резко контрастирует со свежими подношениями, лежащими перед ней.', 'Древняя табличка вот-вот рассыплется. Она резко контрастирует со свежими подношениями, лежащими перед ней.', 28153),
(132117, 'ruRU', '', 'Твои кости послужат госпоже!', 28153),
(132114, 'ruRU', 'Вся Орда – сплошной сброд!', '', 28153),
(132113, 'ruRU', 'Эта война когда-нибудь кончится?', '', 28153),
(132112, 'ruRU', 'Я вернусь в тень.', '', 28153),
(132111, 'ruRU', 'Береги себя, солдат.', '', 28153),
(132107, 'ruRU', 'Тебе надо на север. Иди вдоль реки. Доберешься до мели – перейди ее.', '', 28153),
(132106, 'ruRU', '', 'Я отправлюсь с ними и прослежу, чтобы все прошло гладко.', 28153),
(132105, 'ruRU', 'Добро пожаловать! Прости за беспорядок, к нам не так часто заходят живые посетители.', '', 28153),
(132096, 'ruRU', 'Хм, я услышал достаточно. Давай поговорим.', '', 28153),
(132095, 'ruRU', '', 'Клянусь!', 28153),
(132094, 'ruRU', 'Джасан, ну-ка, притормози! Вдруг эта никчемность нам еще пригодится. Возможно, девчонка говорит правду.', '', 28153),
(132093, 'ruRU', 'Отвлекаешь нас разговорами, пока не прибудут твои друзья?', '', 28153),
(132092, 'ruRU', '', 'Стой, это друг... $n, осторожно!', 28153),
(132081, 'ruRU', 'Мне очень жаль, что Зулсан не может лично тебя встретить. Он пришел бы в восторг от твоей прически.', '', 28153),
(132068, 'ruRU', 'Да, Ман\'зул, я все слышал. Но твоя повязка и правда уродливей, чем зад завролиска.', '', 28153),
(132067, 'ruRU', 'Ха! Волни, будь повежливее! Может, нашему гостю пришлось одеваться в темноте... но ты права!', '', 28153),
(132066, 'ruRU', 'Гренджа – наш бард. Она сыграет любую песню, если попросишь... но только на барабанах. Она любит бить и крушить. Так что береги лицо, ха-ха! Шучу, конечно... Хотя...', '', 28153),
(132057, 'ruRU', 'Нет, Гренджа, золотой барабан я тебе не куплю! Хватит ныть, не то отберу твою новую шляпу!', '', 28153),
(132055, 'ruRU', 'Тут нужно действовать хитро. Это болото – источник мощного вуду.', '', 28153),
(132054, 'ruRU', 'От тебя пахнет свежестью. Болотная вонь еще не въелась в твою плоть. Давай к делу.', '', 28153),
(132053, 'ruRU', '', 'Сестры позвали Энни, она их прогнала. Теперь в цепях, в пещере – наказана она.', 28153),
(132049, 'ruRU', '', 'Сэм был хороший фермер, но сгинул он в лесу. Теперь его свинюшки всю ферму разнесут!', 28153),
(132048, 'ruRU', '', 'Мистер Хейс был очень мил, всегда всем помогал. Как жаль, что сердце добряка пошло на ритуал!', 28153),
(132047, 'ruRU', '', 'Мисс Мэри предала нас, решила ведьмой стать. В деревне поселился страх, все стали умирать.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(132046, 'ruRU', 'Следуй сюда! Пройди через эту дверь и поднимись по подъемнику – король ждет тебя наверху.', '', 28153),
(132045, 'ruRU', '', 'Учти, за тобой следят. Ты стоишь перед одним из самых старых троллей в мире. А жив он до сих пор благодаря мне и моему брату. Так что не чуди.', 28153),
(132044, 'ruRU', 'Отомстим за Зул\'джина!', '', 28153),
(132043, 'ruRU', 'Надеюсь, в этой лодке есть еда!', 'Надеюсь, в этой лодке есть еда!', 28153),
(132042, 'ruRU', 'Мне бы погреться у костра!', 'Мне бы погреться у костра!', 28153),
(132041, 'ruRU', 'Пожалуйста, помоги и взрослым!', 'Пожалуйста, помоги и взрослым!', 28153),
(132040, 'ruRU', 'Спасибо!', 'Спасибо!', 28153),
(132039, 'ruRU', 'Я вернусь в школу...', 'Я вернусь в школу...', 28153),
(132038, 'ruRU', 'Они меня не поймают! Я слишком быстрый!', 'Они меня не поймают! Я слишком быстрая!', 28153),
(132037, 'ruRU', 'Побегу-ка я отсюда!', 'Все, пока!', 28153),
(132020, 'ruRU', '', 'Все в порядке, Дрекал! Эти создания приютили нас. Мы должны завоевать их доверие.', 28153),
(132019, 'ruRU', 'Ого, какая сильная душа! Старый Бвонсамди сейчас пустится в пляс!', '', 28153),
(132017, 'ruRU', '', 'У тебя была возможность получить силу...', 28153),
(132016, 'ruRU', 'Спасибо. Теперь они много не навоюют.', '', 28153),
(132015, 'ruRU', 'Сетраки расширяют свою империю. Они позарились на равнины, где живет наше племя. Нужно остановить завоевателей!', '', 28153),
(132010, 'ruRU', 'Иди к воде. Там ждет лодка. Скоро ты будешь в безопасности.', 'Иди к воде. Там ждет лодка. Скоро ты будешь в безопасности.', 28153),
(132009, 'ruRU', '', 'Глупец... Ты сам не понимаешь, во что вмешиваешься...', 28153),
(132004, 'ruRU', 'Тут были злые люди. Орали на всех – даже на взрослых!', 'Тут были злые люди. Орали на всех – даже на взрослых!', 28153),
(132003, 'ruRU', 'Ты – злюка?$B$BС виду, вроде, нет.', 'Ты – злюка?$B$BС виду, вроде, нет.', 28153),
(132002, 'ruRU', 'У меня нос замерз, у меня уши замерзли, у меня ноги замерзли...', 'У меня нос замерз, у меня уши замерзли, у меня ноги замерзли...', 28153),
(131999, 'ruRU', 'Они говорили, что будут нас кормить, но за все время я от них не видел даже жалкой корки хлеба!', 'Они говорили, что будут нас кормить, но за все время я от них не видела даже жалкой корки хлеба!', 28153),
(131998, 'ruRU', '', 'Мы с Дрекалом будем ждать тебя там, после того как осмотримся.', 28153),
(131997, 'ruRU', '', 'Тебе нужно отправиться в этот храм. Если этот лоа так силен, как говорят, он поможет нам найти Ракиру.', 28153),
(131996, 'ruRU', '<Кашляет>$B$BЯ хочу домой.', '<Кашляет>$B$BЯ хочу домой.', 28153),
(131995, 'ruRU', 'Пожалуйста, только не кричи на меня!', 'Пожалуйста, только не кричи на меня!', 28153),
(131994, 'ruRU', 'Я устал.', 'Я устала.', 28153),
(131939, 'ruRU', '', 'Ты здесь, чтобы сражаться за Альянс, так ведь?', 28153),
(131931, 'ruRU', 'Думаешь, это у тебя жизнь тяжелая? Ты даже не представляешь, как сложно уследить за тем, какая когда начинается война!', '', 28153),
(131897, 'ruRU', '', 'Надеюсь, нам не придется с ними знакомиться.', 28153),
(131894, 'ruRU', '', 'Придется лететь над болотом. Пока мы в воздухе и остаемся незамеченными, проблем быть не должно.', 28153),
(131893, 'ruRU', '', 'Каджа! Что это за твари внизу?', 28153),
(131888, 'ruRU', 'Ма\'да просит, ма\'да получает.', '', 28153),
(131887, 'ruRU', 'Жизнь за Великую Мать!', '', 28153),
(131886, 'ruRU', 'Мясо для матриархов!', '', 28153),
(131885, 'ruRU', 'Свежая кровь!', '', 28153),
(131884, 'ruRU', 'Ма\'да велела убить... нет... захватить в плен. Да! Захватить.', '', 28153),
(131883, 'ruRU', 'Сухожилия! Режьте сухожилия! Ма\'да так велела.', '', 28153),
(131882, 'ruRU', 'Умри! Умри! Умри!', '', 28153),
(131881, 'ruRU', '<В кармане вы находите письмо.>\n\nМилая Мэри!\n\nПрошу тебя, вернись домой. Расселл постоянно о тебе спрашивает. Что я должен ему сказать? Что его мать сбежала в лес, чтобы заниматься какими-то темными делишками? Нам тебя так не хватает, любовь моя. Без тебя наш дом опустел. Пожалуйста, вернись.\n\nС любовью,\nДжонатан', '', 28153),
(131880, 'ruRU', '*ик!* см-м-мотри, куда пр-р-решь...', '*ик!* см-м-мотри, куда пр-р-решь...', 28153),
(131878, 'ruRU', '<Осмотреть труп и попытаться его идентифицировать.>', '<Осмотреть труп и попытаться его идентифицировать.>', 28153),
(131875, 'ruRU', 'Что мы отправляем сегодня?', 'Что мы отправляем сегодня?', 28153),
(131874, 'ruRU', 'Да?', 'Да?', 28153),
(131869, 'ruRU', 'Вдовий грог! Три бочки.', 'Вдовий грог! Три бочки.', 28153),
(131868, 'ruRU', 'Пряное вино! Пять бочек! Эль Бездны! Семь бочек! И-и-и...', 'Пряное вино! Пять бочек! Эль Бездны! Семь бочек! И-и-и...', 28153),
(131867, 'ruRU', 'Внимание всем! Вот сегодняшний заказ!', 'Внимание всем! Вот сегодняшний заказ!', 28153),
(131855, 'ruRU', 'Еще раз спасибо за помощь. Я отнесу подношение в храм.', 'Еще раз спасибо за помощь. Я отнесу подношение в храм.', 28153),
(131851, 'ruRU', 'Тихо! Не суетитесь, все успеете познакомиться. Правда ведь, $p?', '', 28153),
(131845, 'ruRU', 'Этого пока достаточно. Иди найди принцессу на великой лестнице. А я продолжу патрулировать, на случай, если мы упустили еще какие-то силы Альянса.', '', 28153),
(131844, 'ruRU', 'Давайте разделимся и выследим этих посланников Альянса. Я сделаю все возможное, чтобы помочь в поисках.', '', 28153),
(131843, 'ruRU', 'Какая дерзость! Нападать на меня в моем же храме? Они крепко пожалеют... м-хм. Крепко пожалеют.', '', 28153),
(131842, 'ruRU', '', 'Я слишком долго скиталась по этому миру. Наконец-то покой!', 28153),
(131841, 'ruRU', 'Ну, вперед. Бвонсамди следит за тобой.', '', 28153),
(131840, 'ruRU', 'Очень хорошо. Сильвана будет довольна. Идем, \"посланник\", обсудим наш следующий шаг.', '', 28153),
(131839, 'ruRU', 'Подожди, нам что, всем придется драться с этой тварью? Я думал, мы... ну, знаешь... пошлем одного героя, что-то типа того!', '', 28153),
(131838, 'ruRU', 'Чтобы ударить в барабан, нужны молоты Мамбу и Джи\'ды. Оба молота ты найдешь на храмовых землях.', '', 28153),
(131832, 'ruRU', 'Спасибо, дружище.', '', 28153),
(131831, 'ruRU', 'Отвези меня в Зул\'джан.', 'Отвези меня в Зул\'джан.', 28153),
(131830, 'ruRU', '', 'Хотя я мертва, существа все равно приходят на мой зов.\n\nТебе нужно куда-то отправиться?', 28153),
(131829, 'ruRU', 'Надо поговорить. Тут кое-что требует твоего внимания.', '', 28153),
(131828, 'ruRU', 'О, привет! Я тебя везде обыскался!', '', 28153),
(131818, 'ruRU', 'Не забывай о нашей сделке. Ведь тебе нужен Бвонсамди... а Бвонсамди нужны свежие души.', '', 28153),
(131816, 'ruRU', 'Принцесса, не надо спешить. Для начала стоит разведать окрестности и составить план действий.', '', 28153),
(131803, 'ruRU', '', 'Я так понимаю, это о тебе говорила принцесса. Поможешь ей – и я все тебе расскажу. Я уже долго занимаюсь ранеными, но они все прибывают и прибывают.\n\nПринцесса отправляется в Назмир. Она может взять с собой только небольшую охрану, но твой Рокхан теперь тоже с нами. Мы отдали им столько припасов, сколько могли.\n\nОни выходят через северные ворота. С тех пор как тролли крови начали осаждать главные ворота, там никого нет.\n\nТам спрятаны глаза моего лоа. Соблюдай осторожность.', 28153),
(131777, 'ruRU', 'Я верну этот долг. Обещаю.', 'Я верну этот долг. Обещаю.', 28153),
(131776, 'ruRU', 'Я свободен? И ты ничего не требуешь взамен? Как необычно!', '', 28153),
(131774, 'ruRU', '', 'Ну там и бардак. Жаль, что мы не смогли удержать принцессу. Тролль крови уже у самых ворот, а король так ничего и не делает!', 28153),
(131771, 'ruRU', 'Она не провела здесь и дня, а уже отправляется в путь!\n\nТаланджи хочет добраться куда-то втайне от отца. Взяла только несколько телохранителей, чтобы не вызывать подозрений.\n\nМне кажется, что она собирается в Назмир, даже если никому не говорит об этом. Это нехорошее место, дорогуша. Если я не смогу отправиться туда сам, мне будет спокойнее, если это сделаешь ты.\n\nЕй нужны будут припасы. Скорее всего, принцесса будет останавливаться в знакомых местах. Дай взглянуть на твою карту.', '', 28153),
(131766, 'ruRU', 'Где Таланджи?', 'Где Таланджи?', 28153),
(131765, 'ruRU', 'Спасение нашей принцессы – это поступок, достойный уважения. Я не понаслышке знаю, что защищать ее – та еще головная боль. Она убеждена, что должна спасти зандаларов в одиночку.', '', 28153),
(131764, 'ruRU', 'Какой приятный сюрприз!', 'Какой приятный сюрприз!', 28153),
(131763, 'ruRU', 'Нет времени языком чесать, солдат, это Передовая ставка. Мы тут в самой гуще событий: вон там, из лагеря Таурахо на нас обрушиваются все новые полчища этих проклятых тауренов.\n\nЕсли нас выбьют с этой позиции, не знаю, как мы будем брать ворота.', '', 28153),
(131761, 'ruRU', 'От моджо не спрячешься!', '', 28153),
(131752, 'ruRU', 'Валджабу, тебе незачем отправляться на Ту Сторону. Покорись Г\'ууну, и получишь вечную жизнь!', '', 28153),
(131750, 'ruRU', 'Еще одно жалкое существо ищет в песках свою погибель?', '', 28153),
(131745, 'ruRU', '', 'Отправляйся с Рокханом в Назмир. Там и встретимся. Пора покончить с троллями крови.', 28153),
(131742, 'ruRU', '', 'Да благословит тебя Один, и вот заслуженная награда.', 28153),
(131741, 'ruRU', 'Ну что, парни, давайте ворвемся туда и перекрасим все стены в красный. У дверей надо поставить охрану – если вдруг они попытаются нас выдворить. А еще я хочу, чтобы здесь организовали бар. И вот еще что! Найдите мне новый камень для телепортации – на всякий случай.', '', 28153),
(131709, 'ruRU', 'Что здесь происходит? Почему мы сидим в клетках, как животные?', '', 28153),
(131706, 'ruRU', '', 'Йоррик, неси сюда свой полевой набор. У нас тут выживший!', 28153),
(131705, 'ruRU', 'Ой-ой! Да, сэр!', '', 28153),
(131703, 'ruRU', '', 'Подъем, лейтенант! Нужно найти способ выбраться отсюда!', 28153),
(131690, 'ruRU', 'Мастер клинка Хаззул без сознания.', '', 28153),
(131689, 'ruRU', '', 'Мастер клинка Джорана не подает признаков жизни.', 28153),
(131674, 'ruRU', 'Добро пожаловать в таверну \"Золотой клык\"!', '', 28153),
(131672, 'ruRU', 'Этот изгой, похоже, еще жив, хотя едва дышит. \n\nОн серьезно ранен, но болезненный вид указывает на то, что плохо ему не только от ран.', '', 28153),
(131671, 'ruRU', 'Из-за обломков, преграждающих путь, исходит свет. \n\nЕсли их убрать, вы, возможно, сможете выйти из руин.', '', 28153),
(131670, 'ruRU', 'Эти существа погибли от магии льда – верный признак того, что Джайна недавно здесь была.\n\nНо куда она направилась – вот в чем вопрос.', '', 28153),
(131668, 'ruRU', 'Похоже, это следы одного из зверей, напавших на вас и ваших спутников в лесу. Зверь как будто что-то волок позади себя.\n\nЧто странно, следы прерываются в одной точке, словно зверь просто исчез.', '', 28153),
(131667, 'ruRU', 'Берегись! Я так ЗОЛОДЕН!', '', 28153),
(131666, 'ruRU', '', 'Ничего себе! Это еще что?!', 28153),
(131665, 'ruRU', 'Детеныш дикорога удивленно пищит.', '', 28153),
(131664, 'ruRU', 'Молодой дикорог радостно сбивает вас с ног.', '', 28153),
(131663, 'ruRU', 'Молодой дикорог кусает вас от избытка чувств – правда не рассчитывает силы.', '', 28153),
(131662, 'ruRU', 'Молодой дикорог в восторге сбивает вас с ног.', '', 28153),
(131661, 'ruRU', 'Я так голоден, что съел бы и брутозавра!', '', 28153),
(131659, 'ruRU', 'Мама, а можно мне еще мяса? Ну пожалуйста!', '', 28153),
(131658, 'ruRU', 'Плеточники вкусные, но я хочу мяса!', '', 28153),
(131657, 'ruRU', '%s игриво рычит.', '', 28153),
(131656, 'ruRU', '%s ехидно смотрит на вас.', '', 28153),
(131655, 'ruRU', '%s радостно скачет вокруг.', '', 28153),
(131654, 'ruRU', '%s издает радостный возглас.', '', 28153),
(131653, 'ruRU', 'Слушай, в тебе есть искра, но посредник из тебя так себе. Очень так себе.$b$bПросто добейся у их короля аудиенции, и я уговорю его отказаться от флота, от трона, от золота, которым тут все украшено, и мне еще, может, парочку масок тики дадут на память.', '', 28153),
(131652, 'ruRU', 'Эге, только посмотрите! Может, ты чего-то и стоишь. Возвращайся в храм. У старого Бвонсамди есть что тебе предложить.', '', 28153),
(131651, 'ruRU', 'А, Салазе... она слишком задержалась среди живых. Ты уж постарайся, принеси ее душу терпеливому лоа смерти, а?', '', 28153),
(131650, 'ruRU', '', 'Если ты не можешь помочь мне воссоединиться с возлюбленным, просто уйди.', 28153),
(131649, 'ruRU', 'Мы готовы получить твое благословение.', 'Мы готовы получить твое благословение, о великий лоа.', 28153),
(131648, 'ruRU', 'Этот храм был воздвигнут много лет назад. И хотя его стены стоят, как прежде, лица моих последователей изменились.', '', 28153),
(131637, 'ruRU', 'Приветствую вас, малыши, я снова здесь. Сделайте шаг вперед, чтобы получить мое благословение.', '', 28153),
(131633, 'ruRU', 'Только зандаларам можно входить в священные залы! Закон гласит...', '', 28153),
(131632, 'ruRU', 'Решено. Отныне нарекаю тебя Голосом Орды.', '', 28153),
(131631, 'ruRU', 'Я здесь закон. Я король, и это мое королевство.', '', 28153),
(131630, 'ruRU', 'Мы будем внимательно следить за тобой. Отныне нарекаю тебя Голосом Орды.', '', 28153),
(131629, 'ruRU', 'Посмотрим, сможет ли Орда доказать свою ценность для Зандалара. Разместите их в зале Великой Печати... пока что.', '', 28153),
(131628, 'ruRU', 'Таланджи считает, что я не замечаю истинных врагов. Но знай, что я вовсе не слеп.', '', 28153),
(131627, 'ruRU', 'Но моя дочь тоже права. Вы спасли ее из плена и заслужили мое уважение.', '', 28153),
(131626, 'ruRU', 'Джакра\'зет прав... вы хотите получить мой флот, чтобы одолеть Альянс.', '', 28153),
(131625, 'ruRU', '', 'Чудесно! Присаживайся. Вы с Замарашкой поможете мне позвать последнего гостя!', 28153),
(131624, 'ruRU', '', 'Сюда! Это будет лучшее чаепитие на свете!', 28153),
(131623, 'ruRU', '', 'Пойдем! Пойдем! Пора начинать чаепитие!', 28153),
(131620, 'ruRU', '', 'Вашей с моим мужем жертвы будет достаточно, чтобы завершить ритуал!', 28153),
(131619, 'ruRU', '', 'Будь с нами, сестра, и мы обретем великую силу!', 28153),
(131618, 'ruRU', '<В груди этого человека зияет огромная дыра. Вы заглядываете в нее и видите, что сердце отсутствует.>', '', 28153),
(131617, 'ruRU', 'На рукояти вырезано \"С. Готорн\".', '', 28153),
(131616, 'ruRU', '', 'Мистер Готорн всегда отгонял собачек от своих свинок. Теперь-то собачки наедятся всласть.', 28153),
(131615, 'ruRU', '', 'Пропала деревня моя,', 28153),
(131609, 'ruRU', '', 'Мы должны быть настороже. Из Назмира не возвращаются.', 28153),
(131608, 'ruRU', '', 'Тролли крови – просто дикари. Они никогда не были опасны.', 28153),
(131607, 'ruRU', 'Довольно. Я сам решу, что делать с чужаками.', '', 28153),
(131606, 'ruRU', '', 'Нам нужны союзники против троллей крови. Я сделала то, что было нужно.', 28153),
(131605, 'ruRU', 'Таланджи притащила шавку из Орды. Это измена, принцесса.', '', 28153),
(131604, 'ruRU', '', 'Я вырву твою душу для Г\'ууна!', 28153),
(131603, 'ruRU', 'Это еще... не конец...', 'Это... еще... не конец...', 28153),
(131602, 'ruRU', '', 'Г\'уун – хозяин этой земли. Скоро даже глупец Бвонсамди будет служить ему.', 28153),
(131544, 'ruRU', 'Я готов.', 'Я готова.', 28153),
(131543, 'ruRU', '', '<Энни смотрит на вас невидящим взором. Ее одежда вся в крови, но сама она отделалась парой царапин. Она заикается, пытается что-то сказать, но слова разобрать невозможно.>', 28153),
(131542, 'ruRU', 'Мейс, Нотли и Йоррик сообщают, что готовы выдвигаться.', 'Мейс, Нотли и Йоррик сообщают, что готовы выдвигаться.', 28153),
(131541, 'ruRU', 'Ты из Гленбрука?', 'Ты из Гленбрука?', 28153),
(131540, 'ruRU', '', '<Энни сильно дрожит. Ее глаза смотрят в никуда.>', 28153),
(131539, 'ruRU', 'Пора. Давай встретимся у ворот – пришло время нанести удар по Друствару!', '', 28153),
(131505, 'ruRU', 'Я не оставлю его в таком состоянии. Иди и расскажи остальным, что с ним сделали, я найду тебя в храме.', '', 28153),
(131504, 'ruRU', '*Сопит* Пожалуйста, очнись...', '', 28153),
(131503, 'ruRU', 'Хакаси, теперь ты в безопасности... Хакаси? Эй... очнись...', '', 28153),
(131497, 'ruRU', 'Плохой дьявозавр! Очень плохой!', 'Плохой дьявозавр! Очень плохой!', 28153),
(131496, 'ruRU', 'Спасибо тебе за помощью и за передачу моих приказов. Я доложу маршалу Риду.', '', 28153),
(131494, 'ruRU', 'Однако время часто играет против разума.', '', 28153),
(131493, 'ruRU', 'Будет мудро переждать бурю, прежде чем отправляться на вражескую территорию.', '', 28153),
(131492, 'ruRU', 'Ладно, постараюсь приготовить припасы побыстрее.', '', 28153),
(131491, 'ruRU', 'Передайте маршалу Риду, что интендант Нотли прибыл.', '', 28153),
(131490, 'ruRU', '', 'Я буду ждать тебя у ворот. Надеюсь, ты хорошо подготовишься.', 28153),
(131489, 'ruRU', '', 'Ха! Так Рид хочет вломиться в леса Друствара? Наконец-то хоть какое-то веселье.', 28153),
(131487, 'ruRU', '', 'Надеюсь, ты отвлекаешь меня от дел не просто так? \n\n...или ты просто не видишь, что я занята?', 28153),
(131486, 'ruRU', 'На Мертволесье скоро обрушится буря. Нам еще повезет, если в таких условиях мы разглядим врагов у себя под носом!\n\nКак будто в Друстваре и без этой погодки не было опасно...', '', 28153),
(131485, 'ruRU', 'Маршал Рид приказывает присоединиться к его экспедиции по поискам Джайны.', 'Маршал Рид приказывает присоединиться к его экспедиции по поискам Джайны.', 28153),
(131484, 'ruRU', 'Ох, к нам сюда не часто заходят чужестранцы. \n\nТебе нужны припасы?', '', 28153),
(131479, 'ruRU', 'Должен признать, твоя храбрость удивляет меня. \n\nТы не из этих мест, но все равно подвергаешь себя опасности, чтобы спасти одного из нас. Надеюсь только, рука, что держит твой клинок, так же сильна, как и твой дух.\n\nМы отправляемся по первому твоему слову.', '', 28153),
(131478, 'ruRU', 'Держись, Хакаси... мы спасем тебя, обещаю!', '', 28153),
(131477, 'ruRU', 'Тебе это... так не пройдет, чудовище!', '', 28153),
(131476, 'ruRU', 'Что я вижу, это кто явился к нам на стену? Ты, вероятно, хочешь взглянуть на проклятый Друствар, не подвергая при этом себя опасности?\n\nВозвращайся-ка лучше домой, дорогуша. Путникам здесь не место.', '', 28153),
(131475, 'ruRU', 'Что?..\n\nПрошу прощения. Я... ошибся. \n\nТак выходит, ты – союзник дома Праудмуров? Значит, ты хочешь узнать новости о Джайне. Я не вижу другой причины заходить так далеко на север.\n\nЧто ж, возможно, ты как раз вовремя.', '', 28153),
(131472, 'ruRU', '<Отдать Риду записку от Телии>', '<Отдать Риду записку от Телии>', 28153),
(131471, 'ruRU', 'А, здравствуй, Ханзабу. Ты явился для уплаты долга?', '', 28153),
(131470, 'ruRU', 'Какие вести из далеких стран?', '', 28153),
(131469, 'ruRU', 'Его надо спасти!', '', 28153),
(131468, 'ruRU', 'Я слышал в пещере голос Хакаси! Кажется, у него неприятности...', '', 28153),
(131467, 'ruRU', '$n! Сюда!', '', 28153),
(131466, 'ruRU', 'Гвардия! Союзники! С юго-запада приближаются войска Орды! Защищайте ворота!', '', 28153),
(131465, 'ruRU', 'Ты позаботься о змееобразных, а я пойду искать Хакаси...', '', 28153),
(131461, 'ruRU', 'Ха-ха-ха! Ханзабу, ты что, за дурака меня держишь? Эти двое полягут не от твоей руки.', '', 28153),
(131460, 'ruRU', 'В двух я чую наибольшую силу. Их ведь будет достаточно, чтобы выполнить наш договор?', '', 28153),
(131459, 'ruRU', 'Бвонсамди, я принес больше душ, как и было уговорено.', '', 28153),
(131458, 'ruRU', '', 'Погоди... Кажется, я что-то слышу.', 28153),
(131457, 'ruRU', '', 'Преграда разрушена! Валим отсюда!', 28153),
(131456, 'ruRU', 'Она была бесполезна. Тролли крови вторглись с севера, Альянс пересек наши границы на юге, а теперь ты привела этих ордынских выродков прямо в нашу столицу.', '', 28153),
(131455, 'ruRU', '', 'Не знаю, что там тебе удалось совершить, но это прервало приток моджо к преграде. Давай поищем другие такие штуковины.', 28153),
(131454, 'ruRU', '', 'Ракира была одним из величайших героев в этом кор...', 28153),
(131453, 'ruRU', 'У меня новости о Хакаси.', 'У меня новости о Хакаси.', 28153),
(131452, 'ruRU', '', 'Нас атакуют!', 28153),
(131451, 'ruRU', '', 'Путь закрыт! Надо осмотреться. Должен быть какой-то способ разрушить эту преграду.', 28153),
(131450, 'ruRU', '', 'Никого не щадить!', 28153),
(131449, 'ruRU', '', 'Нас никто не остановит!', 28153),
(131448, 'ruRU', '', 'Один раздавлен!', 28153),
(131447, 'ruRU', '', 'Тауваниванга!', 28153),
(131446, 'ruRU', '<Вдалеке слышен рев монстра.>', '', 28153),
(131445, 'ruRU', 'Нам нужно отправиться на его поиски, пока не поздно! Как только подготовишься, встретимся у каньона.', '', 28153),
(131444, 'ruRU', 'Значит, Хакаси увидел в каньоне что-то подозрительное и пропал... плохо дело.', '', 28153),
(131443, 'ruRU', '', 'Осторожнее – духи здесь злые. Кажется, они уже долго тут заперты.', 28153),
(131442, 'ruRU', '', 'Наш гость пробудился.', 28153),
(131440, 'ruRU', '', 'Замарашка любит гулять в лесу. Нельзя, чтобы собачки его поймали!', 28153),
(131439, 'ruRU', 'Тебе меня не поймать, ведьма!', '', 28153),
(131435, 'ruRU', 'Помогите укротителям подчинить дьявозавра!', 'Помогите укротителям подчинить дьявозавра!', 28153),
(131434, 'ruRU', 'Атакуйте Красную смерть!', 'Атакуйте Красную смерть!', 28153),
(131431, 'ruRU', 'Бросьте дьявозавру игрушку, чтобы отвлечь его!', 'Бросьте дьявозавру игрушку, чтобы отвлечь его!', 28153),
(131430, 'ruRU', 'Совершите рывок, чтобы прорваться через препятствие.', 'Совершите рывок, чтобы прорваться через препятствие.', 28153),
(131429, 'ruRU', 'Бегите через северные ворота! И не попадитесь дьявозавру!', 'Бегите через северные ворота! И не попадитесь дьявозавру!', 28153),
(131428, 'ruRU', 'Удачи тебе!', '', 28153),
(131427, 'ruRU', 'Добро пожаловать на тренировочную площадку! Это Мизинчик, наш дерзкий молодой дьявозавр.', '', 28153),
(131426, 'ruRU', 'Этот груз принадлежит нам, отродье Альянса!', 'Этот груз принадлежит нам, отродье Альянса!', 28153),
(131425, 'ruRU', 'Продолжить осмотр тела.', 'Продолжить осмотр тела.', 28153),
(131424, 'ruRU', '<Раны глубоки. Разрезы сделаны с большой аккуратностью.$B$BВдоль краев ран видны остатки жидкой субстанции, которая блестит на свету.>', '', 28153),
(131419, 'ruRU', '', 'Мы отправимся, когда скажешь. Поторопись, Ракира долго в песках не протянет.', 28153),
(131418, 'ruRU', '', 'Мне не будет покоя, пока мы не найдем Ракиру.', 28153),
(131416, 'ruRU', 'Приходилось тренироваться с дьявозавром? Он кусается не слишком сильно... как правило!', 'Приходилось тренироваться с дьявозавром? Он кусается не слишком сильно... как правило!', 28153),
(131415, 'ruRU', '', 'Твоя правда. Вперед!', 28153),
(131414, 'ruRU', '', 'Да, твои слова мудры. Пошли, найдем выход из склепа.', 28153),
(131413, 'ruRU', '', 'То, что ты говоришь, разумно. Давай-ка осмотримся, должен же где-то быть выход.', 28153),
(131408, 'ruRU', 'Солдаты не сдаются, Бву\'я. А теперь возьми себя в руки и давай подумаем, как нам отсюда выбраться. За Орду!', 'Солдаты не сдаются, Бву\'я. А теперь возьми себя в руки и давай подумаем, как нам отсюда выбраться. За Орду!', 28153),
(131407, 'ruRU', 'Бву\'я, нам дали задание, и мы должны выполнить его во что бы то ни стало!', 'Бву\'я, нам дали задание, и мы должны выполнить его во что бы то ни стало!', 28153),
(131406, 'ruRU', 'Вот, значит, как ты служишь вождю? На нас многие рассчитывают!', 'Вот, значит, как ты служишь вождю? На нас многие рассчитывают!', 28153),
(131405, 'ruRU', '', 'Сражаться бесполезно, мы обречены!', 28153),
(131404, 'ruRU', 'Ты же темная охотница, Бву\'я. Покажи им, что этот титул – не пустые слова.', 'Ты же темная охотница, Бву\'я. Покажи им, что этот титул – не пустые слова.', 28153),
(131403, 'ruRU', 'Неужели ты без боя позволишь надеждам и мечтам твоих предков погибнуть здесь?', 'Неужели ты без боя позволишь надеждам и мечтам твоих предков погибнуть здесь?', 28153),
(131399, 'ruRU', 'Так сражайся! Верь в себя и заставь их гордиться!', 'Так сражайся! Верь в себя и заставь их гордиться!', 28153),
(131396, 'ruRU', '', 'Что? Конечно, нет!', 28153),
(131392, 'ruRU', 'Соберись. Ты можешь больше, ты же темный охотник!', 'Соберись. Ты можешь больше, ты же темная охотница!', 28153),
(131391, 'ruRU', 'Принцесса Таланджи никого не ждет. Они с Зулом уже покинули корабль. Поспеши, если хочешь их нагнать.', '', 28153),
(131389, 'ruRU', '', '', 28153),
(131388, 'ruRU', 'Если ты чувствуешь отчаяние, это всего лишь значит, что твой дух жив и ты можешь изменить ситуацию!', 'Если ты чувствуешь отчаяние, это всего лишь значит, что твой дух жив и ты можешь изменить ситуацию!', 28153),
(131387, 'ruRU', 'Он вырвался! Бегите!', 'Он вырвался! Бегите!', 28153),
(131386, 'ruRU', 'Надежда еще жива! Если мы будем работать сообща, то сможем побороть это проклятье!', 'Надежда еще жива! Если мы будем работать сообща, то сможем побороть это проклятье!', 28153),
(131385, 'ruRU', 'Пока что я дам вам с Рокханом возможность принимать решения, все-таки он знает этот народ лучше меня.$b$bКроме того, у троллей небольшой пунктик насчет таких, как я... тех, кто отказывается оставаться в мертвых. Не хочу, чтобы их узколобость помешала нам получить флот.$b$bМы обязаны преуспеть. Сильване нужен флот.', '', 28153),
(131384, 'ruRU', '', 'Да? И почему ты так думаешь?', 28153),
(131383, 'ruRU', 'Соберись – мы еще не утратили боевой дух!', 'Соберись – мы еще не утратили боевой дух!', 28153),
(131382, 'ruRU', 'Ты правда хочешь, встретив духов своих предков, сказать им, что ты сдаешься?', 'Ты правда хочешь, встретив духов своих предков, сказать им, что ты сдаешься?', 28153),
(131377, 'ruRU', 'Не отчаивайся! Мы найдем выход.', 'Не отчаивайся! Мы найдем выход.', 28153),
(131372, 'ruRU', 'Пора идти.', 'Пора идти.', 28153),
(131371, 'ruRU', 'Поверить не могу, что Хакаси ушел и свалил на нас всю эту работу. Он за это заплатит! Пусть только вернется!', '', 28153),
(131370, 'ruRU', '', 'Ха-ха! Пронзи его!', 28153),
(131369, 'ruRU', '', 'Это безнадежно. Как мы выберемся отсюда?', 28153),
(131333, 'ruRU', 'Он что-то говорил о беспорядках в каньоне. Я ответил, что волноваться, скорее всего, не о чем.', '', 28153),
(131332, 'ruRU', 'Хм... дай подумать. А, да! Он не так давно направлялся к каньону! Интересно, чего он там забыл?', '', 28153),
(131331, 'ruRU', 'Хакаси? Да, я его сегодня видела. Он собирал подношения для ритуала неподалеку.', '', 28153),
(131329, 'ruRU', '', 'Все врассыпную! Спасайтесь! Летите подальше от этих гадюк!', 28153),
(131327, 'ruRU', 'Каджа, нужно свернуть. Впереди земли империи сетраков.', '', 28153),
(131325, 'ruRU', '', 'Ты о двуногих змеях? Я думала, они прячутся под дюнами...', 28153),
(131322, 'ruRU', '', 'Впереди проход! Держитесь пониже и высматривайте Ракиру.', 28153),
(131306, 'ruRU', 'Тебе еще не доводилось встречаться с великим Акундой? Сейчас самое лучшее время для этого!', '', 28153),
(131305, 'ruRU', 'Мне столько всего надо сделать до прибытия Акунды! А времени нет... совсем нет времени!', '', 28153),
(131304, 'ruRU', 'Ты не знаешь, где Хакаси?', 'Ты не знаешь, где Хакаси?', 28153),
(131303, 'ruRU', 'Наш народ уже долгие годы не призывал Акунду. Не терпится снова ощутить его присутствие!', '', 28153),
(131302, 'ruRU', '%s с удовольствием ест, а потом изрыгает пламя.', '', 28153),
(131300, 'ruRU', '%s, чавкая, пожирает растение.', '', 28153),
(131299, 'ruRU', 'Наконец-то настоящий бой!\n\nЭти глупцы из Орды решили, что смогут пробить там брешь и пробраться в Передовую ставку. Что я об этом думаю?\n\nТьфу!\n\nВперед, убьем немного негодяев.', '', 28153),
(131298, 'ruRU', '', 'Как я рада тебя видеть, солдат! Мы тут еле держимся!\n\nФорт Триумфа – ключевая позиция в осаде Врат. Расселина на севере подвергается постоянным атакам войск Оргриммара. Если мы не сможем ее удержать, то все караваны из Терамора окажутся в опасности.', 28153),
(131297, 'ruRU', 'Как прикажешь, господин Хигаши...', '', 28153),
(131296, 'ruRU', 'Пробовать еду и готовить пир – не одно и то же! Я два раза повторять не буду, Рифу.', '', 28153),
(131295, 'ruRU', 'Но я уже готовлю пир!', '', 28153),
(131294, 'ruRU', 'Хакаси должен вот-вот вернуться с последними дарами. Возьми нашего нового друга и вместе принесите их сюда.', '', 28153),
(131293, 'ruRU', 'Да, мастер Хигаши!', '', 28153),
(131292, 'ruRU', 'Рифу! Познакомься с нашим гостем.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(131291, 'ruRU', 'Без них мы не сможем призвать лоа. Может, ты нам поможешь...', '', 28153),
(131290, 'ruRU', 'Время ритуала придет совсем скоро, но нам по-прежнему не хватает кое-чего для подношений.', '', 28153),
(131289, 'ruRU', 'Найдите в стенах храма древние таблички. Легенда об Акунде ждет вас.', '', 28153),
(131255, 'ruRU', 'Мы всегда будем приносить жертвы великому рокочущему ящеру. И пусть он вечно хранит эти джунгли.', '', 28153),
(131254, 'ruRU', '', 'Хорошо. Пришла пора выбрать яйцо, $gученик:ученица;. Если ящер примет тебя, ты услышишь в голове его голос...', 28153),
(131250, 'ruRU', '', '<Матриарх Джез\'лит задумчиво и оценивающе рассматривает вас>', 28153),
(131249, 'ruRU', '', 'Вот она. Сама свирепость и грация, правда? Сразись с ней, если осмелишься.', 28153),
(131248, 'ruRU', '', 'Этот памятник выглядит точно как святилище Бвонсамди в Зулдазаре, только древнее.', 28153),
(131247, 'ruRU', 'Мы с моим дикорогом не расстаемся с самого дня его рождения. Сражаемся, как единое целое.', 'Мы с моим дикорогом не расстаемся с самого дня его рождения. Сражаемся, как единое целое.', 28153),
(131246, 'ruRU', 'Заклинатель ящеров должен быть не только умелым, но еще и бесконечно терпеливым. С молодыми дикорогами очень много мороки!', 'Заклинательница ящеров должна быть не только умелой, но еще и бесконечно терпеливой. С молодыми дикорогами очень много мороки!', 28153),
(131245, 'ruRU', 'На этом самом месте мы возвели храм в честь Акунды. Мы больше никогда не предадим забвению великого лоа.', '', 28153),
(131244, 'ruRU', 'Когда осела пыль, мы забрались на высокую скалу. Перед нами лежало безжизненное тело Зул\'хана, но Акунды нигде не было.', '', 28153),
(131243, 'ruRU', 'Нам уже казалось, что битва никогда не кончится, но пыль рассеялась, и земля перестала дрожать...', '', 28153),
(131242, 'ruRU', 'Акунда вернулся, и в мгновение ока два зверя ринулись в бой. Земля содрогалась с каждым ударом!', '', 28153),
(131241, 'ruRU', 'И когда мы уже совсем утратили надежду, каньон огласил жуткий рык. Над скалами показалась фигура, застившая свет луны.', '', 28153),
(131240, 'ruRU', 'Мы обрушили на Зул\'хана всю нашу мощь, но он был слишком силен! Он вырвался... и мы были обречены.', '', 28153),
(131239, 'ruRU', 'Мы устроили засаду и заманили Зул\'хана в глубокий каньон. Сверху на него скинули огромную сеть...', '', 28153),
(131238, 'ruRU', 'Вожди племен встретились в сердце Вол\'Амана. Нужно было решить: будем мы сражаться все вместе – или возьмем все, что сможем унести, и покинем джунгли. Мы выбрали сражение!', '', 28153),
(131237, 'ruRU', 'Зул\'хан мог свободно бесчинствовать на наших землях. Он охотился на мой народ и уничтожал всех подряд. То были темные времена...', '', 28153),
(131236, 'ruRU', 'Мы перестали приносить жертвы великому рокочущему ящеру. В конце концов Акунда исчез из джунглей...', '', 28153),
(131235, 'ruRU', 'Акунда защищал нас от гнева Зул\'хана. Шли годы, и моим народом овладела беспечность.', '', 28153),
(131234, 'ruRU', 'Дьявозавр Зул\'хан завидовал силе лоа. Он рыскал в темных джунглях, охотился и убивал ради удовольствия.', '', 28153),
(131233, 'ruRU', 'Перед его силой и величием склонялись все обитатели джунглей. Все, кроме одного – властного Зул\'хана.', '', 28153),
(131232, 'ruRU', 'Давным-давно великий рокочущий ящер бродил по джунглям, и мой народ взирал на него с благоговением.', '', 28153),
(131231, 'ruRU', 'Я, Зан\'гаджи, вождь своего племени и архитектор этого храма, посвящаю его всесильному Акунде.', '', 28153),
(131230, 'ruRU', 'Я всю жизнь учился ремеслу заклинателя ящеров. А ты что умеешь?', 'Я всю жизнь училась ремеслу заклинательницы ящеров. А ты что умеешь?', 28153),
(131229, 'ruRU', 'К бою!', 'К бою!', 28153),
(131228, 'ruRU', '', 'Зандалар – навеки!', 28153),
(131227, 'ruRU', '', 'Лоа помогут мне!', 28153),
(131226, 'ruRU', '', 'За Зулдазар!', 28153),
(131224, 'ruRU', '', 'Ракира была моим командиром. Лучше нее в городе было не найти.', 28153),
(131223, 'ruRU', 'Я выполняю приказы. Вопросов не задаю. И ты лучше не задавай.', '', 28153),
(131222, 'ruRU', 'Если есть что сказать, говори, $n. Мне платят не за пустую болтовню.', '', 28153),
(131221, 'ruRU', '', 'Тебе жить надоело? У генерала Джакра\'зета глаза и уши повсюду.', 28153),
(131220, 'ruRU', '', 'Чего тебе? Не тяни.', 28153),
(131218, 'ruRU', '', 'Как видишь, среди нас еще есть те, кто разделяет ее подозрения.', 28153),
(131215, 'ruRU', '', 'Эй, ты! Да, ты. Тут говорят, тебя генерал интересует?', 28153),
(131214, 'ruRU', '', 'В дюнах никто не выживает. Я не хочу сидеть сложа руки, пока Ракира умирает в песках!', 28153),
(131213, 'ruRU', '', 'Не знаю, что она выведала, но за это ее отправили в пустыню.', 28153),
(131212, 'ruRU', '', 'Недавно она сказала мне, что генерал Джакра\'зет – предатель и что она докажет это. С тех пор ее не видели.', 28153),
(131211, 'ruRU', '', 'Давай постараемся не привлекать внимания.', 28153),
(131210, 'ruRU', 'Что ты можешь рассказать мне о генерале Джакра\'зете?', 'Что ты можешь рассказать мне о генерале Джакра\'зете?', 28153),
(131209, 'ruRU', '', 'Чем могу помочь?', 28153),
(131208, 'ruRU', 'Жаль, что вам пришлось во всем этом поучаствовать. Но теперь вы сможете встретиться с Бвонсамди. Вы же этого хотели? Хе-хе-хе...', '', 28153),
(131207, 'ruRU', 'Чудесно. Эта душа станет достойным подношением Бвонсамди!', '', 28153),
(131206, 'ruRU', 'Проклятие, меня обнаружили! Слушай, помоги – и посмотрим, что я смогу для тебя сделать, хорошо?', '', 28153),
(131205, 'ruRU', 'К оружию!', '', 28153),
(131204, 'ruRU', '', 'Маршал, нет!', 28153),
(131203, 'ruRU', 'Отпусти немедленно, ты...', '', 28153),
(131202, 'ruRU', '', 'Осторожно!', 28153),
(131201, 'ruRU', 'Мейс, Йоррик, пройдитесь по периметру и поищите...', '', 28153),
(131200, 'ruRU', '', 'Думаешь, она пошла... вниз?', 28153),
(131199, 'ruRU', 'Я не понимаю... Тропа ведет сюда...', '', 28153),
(131198, 'ruRU', 'Это тупик...', '', 28153),
(131197, 'ruRU', '', 'Что... это за место?', 28153),
(131196, 'ruRU', 'Кажется, вдали какое-то строение. Наверное, это туда отправилась Джайна!', '', 28153),
(131195, 'ruRU', 'Путь преграждают чудовища. Врежьтесь в них!', '', 28153),
(131194, 'ruRU', 'Нам нужно углубиться в лес! Держать строй!', '', 28153),
(131193, 'ruRU', 'Похоже на магию льда... Должно быть, Джайна проходила здесь!', '', 28153),
(131192, 'ruRU', 'Проклятье! Придется идти дальше без него... подожди-ка, это еще что?', '', 28153),
(131191, 'ruRU', 'Сэр! Никаких следов Нотли, а идти по следу по такой погоде не представляется возможным!', '', 28153),
(131190, 'ruRU', 'Плохо... очень плохо.', '', 28153),
(131189, 'ruRU', '', 'Что за...', 28153),
(131188, 'ruRU', 'Быстрее! Они пошли сюда!', '', 28153),
(131187, 'ruRU', '', 'Засада!', 28153),
(131186, 'ruRU', 'Ай-е-е!', '', 28153),
(131185, 'ruRU', 'Нотли, нет!', '', 28153),
(131184, 'ruRU', 'Постой... Мне кажется, я что-то вижу...', '', 28153),
(131183, 'ruRU', 'Пойдем, нам пора.', '', 28153),
(131182, 'ruRU', 'Мне хотелось бы в это верить. Нет, думаю, здесь замешана куда более темная сила.', '', 28153),
(131181, 'ruRU', '', 'Похоже, в этих лесах водятся не только звери. Думаешь, это сделал кто-то из изгоев?', 28153),
(131180, 'ruRU', 'Стой! Что это такое?', '', 28153),
(131179, 'ruRU', 'Все это не предвещает ничего хорошего...', '', 28153),
(131178, 'ruRU', 'Чудовища все смелее – теперь нападают и в открытую.', '', 28153),
(131177, 'ruRU', 'Что это было? Солдаты, к оружию!', '', 28153),
(131176, 'ruRU', 'За мной!', '', 28153),
(131175, 'ruRU', 'Тебе понадобится оружие и стальные нервы – мы отправляемся во тьму!', '', 28153),
(131174, 'ruRU', 'Звери в этих лесах не любят чужаков... да и вообще никого не любят.', '', 28153),
(131173, 'ruRU', 'Буря ограничит наш обзор, так что держись ближе и не сходи с дороги.', '', 28153),
(131172, 'ruRU', 'Я готов учиться.', 'Я готова учиться.', 28153),
(131171, 'ruRU', 'Я занимаюсь обучением животных любых видов и размеров. Даже грузовозов нужно учить правильно вести себя в бою!', '', 28153),
(131170, 'ruRU', 'Мы пойдем по дороге, ведущей к Пределу судьбы, – туда и направился бы караван изгнанников.', '', 28153),
(131169, 'ruRU', '', 'Духи... покидают... меня...', 28153),
(131168, 'ruRU', '', 'А-а-а!', 28153),
(131167, 'ruRU', '', 'Я больше... не могу...', 28153),
(131166, 'ruRU', '', 'Мы никогда не сдадимся! Я проклинаю вас всех! До встречи на Той Стороне.', 28153),
(131165, 'ruRU', '', 'Связь между ящером и наездником устанавливается с помощью фетиша. Коснись заврокамня, когда подготовишься.', 28153),
(131158, 'ruRU', 'От имени Акунды, великого лоа, я приветствую тебя в этом храме, странник.', '', 28153),
(131148, 'ruRU', '', 'Ты неплохо сражаешься. Мой малыш будет с тобой в безопасности.', 28153),
(131142, 'ruRU', '', 'Мои дети заслуживают только самого лучшего.', 28153),
(131115, 'ruRU', 'Покажем им, ребята!', '', 28153),
(131114, 'ruRU', 'Трусы! Пошлите своего лучшего чемпиона и посмотрим, чего он стоит!', '', 28153),
(131113, 'ruRU', 'Ну-ка, посмотрим, что нам приготовила Орда.', '', 28153),
(131112, 'ruRU', '', 'Пусть прольется кровь!', 28153),
(131111, 'ruRU', '', 'На этот раз ты от меня не уйдешь, Ханзабу! Ты заплатишь за смерть моих сестер!', 28153),
(131109, 'ruRU', 'Мы ищем лоа Бвонсамди.', 'Мы ищем лоа Бвонсамди.', 28153),
(131108, 'ruRU', 'Похоже, самое страшное позади. Давай передохнем немного и продолжим.', '', 28153),
(131107, 'ruRU', 'Отлично, эти воины станут хорошим подспорьем в нашей кампании.', '', 28153),
(131106, 'ruRU', 'Привал. Подождем здесь минутку-другую, а потом снова в путь.', '', 28153),
(131105, 'ruRU', 'Солдаты Альянса! Защитите этот храбрый караван на пути к Передовой ставке!', '', 28153),
(131098, 'ruRU', 'Эти когти... и зубы... Мне еще долго будут сниться кошмары.', 'Эти когти... и зубы... Мне еще долго будут сниться кошмары.', 28153),
(131097, 'ruRU', 'Ты очень вовремя!', 'Ты очень вовремя!', 28153),
(131096, 'ruRU', 'Я думал, что мне не выбраться живым. Спасибо тебе!', 'Я думала, что мне не выбраться живой. Спасибо тебе!', 28153),
(131094, 'ruRU', 'У тебя чистая одежда, и от тебя не воняет.$b$bТы кто? Что тебе нужно в этом болоте?', '', 28153),
(131093, 'ruRU', 'Кто ты? Пахнешь не троллем крови...', '', 28153),
(131088, 'ruRU', '', 'Да! это будет лучшее чаепитие в мире! Давай найдем еще гостей.', 28153),
(131087, 'ruRU', 'Что тебе нужно от Ханзабу?', '', 28153),
(131086, 'ruRU', '', 'Хоботуша! Ты же знаешь, что мисс Мэри запретила тебе заходить в дом! Ты все запачкаешь!', 28153),
(131085, 'ruRU', '', 'Мистер Манчи! Проголодались, наверное? Пойдемте. Пора чаевничать.', 28153),
(131081, 'ruRU', '', 'Несносный мэр Стриггс! Вечно отлыниваете от своих обязанностей. Теперь-то вы не убежите!', 28153),
(131080, 'ruRU', '', 'Я ему не доверяю. Нам на...', 28153),
(131079, 'ruRU', 'Тихо! Тихо! Хватит хныкать!', '', 28153),
(131078, 'ruRU', '', 'А-а-а!', 28153),
(131077, 'ruRU', 'О да, из тебя выйдет славное подношение!', '', 28153),
(131057, 'ruRU', '$n побеждает – оборона лесопилки оказалась успешной!', '', 28153),
(131056, 'ruRU', 'Альянс захватил обломки корабля!', '', 28153),
(131055, 'ruRU', 'Орда захватила обломки корабля!', '', 28153),
(131054, 'ruRU', '$n штурмует обломки корабля!', '', 28153),
(131049, 'ruRU', 'Орда привезла танк! Он на дороге, ведущей к крепости Северной стражи! Его необходимо уничтожить!', 'Орда привезла танк! Он на дороге, ведущей к крепости Северной стражи! Его необходимо уничтожить!', 28153),
(131048, 'ruRU', 'Сценарий завершен.', 'Сценарий завершен.', 28153),
(131033, 'ruRU', '', 'Расчистить путь седьмой флотилии! Мы выступим, как только прибудет подкрепление.', 28153),
(131032, 'ruRU', 'Тест', '', 28153),
(131030, 'ruRU', '', 'Смотри! След моджо ведет на север, пойдем в ту сторону.', 28153),
(131025, 'ruRU', '', 'Какие вести ты несешь с севера?', 28153),
(131010, 'ruRU', '', 'Мм-м... жертвоприношение, совсем свежее. Моджо от проведенного здесь ритуала оставило след. Посмотрим, куда он нас приведет.', 28153),
(131009, 'ruRU', 'Из спины трупа торчит маленький кинжал.', 'Из спины трупа торчит маленький кинжал.', 28153),
(131008, 'ruRU', '', 'Я ощущаю присутствие чего-то сильного на севере. Пойдем проверим.', 28153),
(131007, 'ruRU', '', 'Когда я была здесь в первый раз, этого подношения не видела. Видимо, у Бвонсамди по-прежнему есть последователи.', 28153),
(131000, 'ruRU', 'Суровые погодные условия в Назмире не пощадили большую часть текста на табличке. Различимыми остались только слова \"хвала\", \"дух\" и \"могила\".', 'Суровые погодные условия в Назмире не пощадили большую часть текста на табличке. Различимыми остались только слова \"хвала\", \"дух\" и \"могила\".', 28153),
(130979, 'ruRU', 'Разведчики сообщили, что войска Орды под покровом ночи движутся в сторону лагеря Северной стражи. Нам срочно нужна помощь!', '', 28153),
(130978, 'ruRU', '', 'Солдаты Альянса! Пришло наше время! Нападение на Великие врата Мулгора начинается здесь и сейчас. Держитесь друг дружку и сражайтесь с честью.', 28153),
(130977, 'ruRU', '', 'Все бегом в доки!', 28153),
(130969, 'ruRU', '', 'А, $p. Ты здесь, как и нашептал Г\'уун. Я заждалась!', 28153),
(130967, 'ruRU', '', 'Солдаты седьмого флота, близится час наступления. Собирайте вещи и готовьтесь.', 28153),
(130947, 'ruRU', 'Разве не видно, что я умираю с голоду?', '', 28153),
(130946, 'ruRU', 'Мама, дай поесть!', '', 28153),
(130945, 'ruRU', '%s радостно бодает вас.', '', 28153),
(130944, 'ruRU', '', 'Моя смерть – еще не конец.', 28153),
(130943, 'ruRU', 'Давай поиграем? Ты будешь убегать, а попробую тебя догнать и съесть!', '', 28153),
(130940, 'ruRU', '%s жалобно смотрит на вас.', '', 28153),
(130939, 'ruRU', '%s скулит от голода.', '', 28153),
(130938, 'ruRU', '%s скулит и с силой тыкается в вас носом.', '', 28153),
(130937, 'ruRU', '%s издает громкое урчание.', '', 28153),
(130936, 'ruRU', '%s приветливо вас обнюхивает.', '', 28153),
(130935, 'ruRU', '', 'Всех нас вам не победить. Дазар\'алор падет!', 28153),
(130934, 'ruRU', 'Я вытащу своих раненых. Когда закончишь, возвращайся в Раз\'лотек, и мы покончим с этой осадой.', '', 28153),
(130932, 'ruRU', 'Инкубация...', 'Инкубация...', 28153),
(130931, 'ruRU', '', 'Я тебя выпотрошу!', 28153),
(130930, 'ruRU', '', 'Я сниму с тебя шкуру!', 28153),
(130929, 'ruRU', '', 'Больше крови! Больше крови!', 28153),
(130928, 'ruRU', '', 'Ма\'де нужна твоя кровь.', 28153),
(130927, 'ruRU', '', 'Неплохие кости.', 28153),
(130926, 'ruRU', '', 'Свежая плоть, теплая кровь.', 28153),
(130925, 'ruRU', 'Проклятье, мне целую неделю придется заживлять все эти порезы.', 'Проклятье, мне целую неделю придется заживлять все эти порезы.', 28153),
(130924, 'ruRU', 'Проклятые дикари!', 'Проклятые дикари!', 28153),
(130923, 'ruRU', 'Ха! Ты моей крови не получишь!', 'Ха! Ты моей крови не получишь!', 28153),
(130922, 'ruRU', 'Они сказали, что моя кровь им пригодится.', 'Они сказали, что моя кровь им пригодится.', 28153),
(130921, 'ruRU', 'Ха! Не сегодня, дикари!', 'Ха! Не сегодня, дикари!', 28153),
(130920, 'ruRU', 'Они проводили ритуал. У меня даже кости начало ломить.', 'Они проводили ритуал. У меня даже кости начало ломить.', 28153),
(130919, 'ruRU', 'Они мне какие-то символы на руке вырезали. Дикари.', 'Они мне какие-то символы на руке вырезали. Дикари.', 28153),
(130918, 'ruRU', 'Да! Сегодня они меня не получат.', 'Да! Сегодня они меня не получат.', 28153),
(130917, 'ruRU', 'Спасибо! Огромное тебе спасибо!', 'Спасибо! Огромное тебе спасибо!', 28153),
(130915, 'ruRU', 'Не стрелять! Это наше подкрепление!', '', 28153),
(130914, 'ruRU', '', 'Пойдем, охота ждет нас!', 28153),
(130913, 'ruRU', '', 'Идем! Церемония скоро начнется.', 28153),
(130907, 'ruRU', 'Я готов.', 'Я готова.', 28153),
(130906, 'ruRU', '', 'Добро пожаловать в Крааль боевых ящеров, $n.\n\nЯ слыхала об Орде и знаю, что ты собираешься заключить сделку с Растаханом.\n\nПосмотрим, какая от тебя может быть польза. Может быть, тогда мы передадим пару добрых слов на вершину Дазар\'алора.', 28153),
(130905, 'ruRU', 'Я найду того, кто сделал это...', '', 28153),
(130904, 'ruRU', 'Тролли крови сражаются нечестно.', '', 28153),
(130903, 'ruRU', 'Темная магия. Это ненормально.', '', 28153),
(130902, 'ruRU', 'Что за проклятие на тебя наложили, старина?', '', 28153),
(130901, 'ruRU', 'Давай, старина. Ты справишься.', '', 28153),
(130900, 'ruRU', 'Держать строй! Поднимайте раненых и мертвых – все что угодно, только держите строй.', '', 28153),
(130899, 'ruRU', 'Не спускайте глаз с неба! Скоро кровобрюхов станет еще больше.', '', 28153),
(130898, 'ruRU', 'Дерись, как подобает зандаларам!', '', 28153),
(130897, 'ruRU', 'Поднимите раненого! Никто не должен достаться этим дикарям.', '', 28153),
(130896, 'ruRU', 'Не сдавайте позиции, братья и сестры! Мы не покоримся этим дикарям!', '', 28153),
(130842, 'ruRU', 'Применить ко всем положительный эффект.', 'Применить ко всем положительный эффект.', 28153),
(130841, 'ruRU', '', 'Возможно, ты сильнее, чем кажешься. Мой защитник поддаваться не будет. Вызови его на бой, когда сочтешь нужным.', 28153),
(130840, 'ruRU', '', 'Не ожидала, что с новичком тебе будет сложно справиться. Посмотрим, как ты сладишь с противником посильнее.', 28153),
(130839, 'ruRU', 'Я торгую положительными эффектами и прочими полезными на фронте вещами.', '', 28153),
(130838, 'ruRU', '', 'Ты правда примешь на себя такое обязательство? Еще не поздно передумать.', 28153),
(130822, 'ruRU', 'Новые генералы получают повышение!', 'Новые генералы получают повышение!', 28153),
(130797, 'ruRU', '', 'Решительности тебе не занимать, это точно. Пришла пора встретиться с матриархом Джез\'лит. Идем.', 28153),
(130796, 'ruRU', '', 'Готовься жертвовать своими желаниями ради детеныша. Знаешь, сколько они едят?', 28153),
(130795, 'ruRU', 'Связь с детенышами создается во время их вылупления и длится всю жизнь. Они – часть нашей семьи.', 'Связь с детенышами создается во время их вылупления и длится всю жизнь. Они – часть нашей семьи.', 28153),
(130794, 'ruRU', '', 'Дикороги травоядные, так что не вздумай предлагать им мясо!', 28153),
(130793, 'ruRU', 'Детеныши очень привередливы при выборе тех, с кем решают связать свою жизнь. Странно, что этот выбрал тебя!', 'Детеныши очень привередливы при выборе тех, с кем решают связать свою жизнь. Странно, что этот выбрал тебя!', 28153),
(130732, 'ruRU', '', 'Хир\'ик, лоа-нетопырь... он должен быть в Назмире. Хитрый и пронырливый, многое знает.', 28153),
(130731, 'ruRU', '', 'Я чувствую его силу... он близко. Ближе, чем другие лоа.', 28153),
(130730, 'ruRU', '', 'Бвонсамди... лоа смерти. Могучий, но коварный и опасный... всегда заключает сделки.', 28153),
(130710, 'ruRU', '', 'Краг\'ва, лоа-жаба. Он тоже в Назмире! Он очень силен и не потерпит злодеяний троллей крови.', 28153),
(130707, 'ruRU', 'Выходит, мы возьмем в союзники лоа смерти, лоа-черепаху, лоа-нетопыря и лоа-жабу...', '', 28153),
(130705, 'ruRU', '', 'Мы не сможем остановить троллей крови в одиночку. Нам нужна сила здешних лоа.', 28153),
(130692, 'ruRU', '', '<Смотрит на вас... с недвусмысленным намеком.>', 28153),
(130625, 'ruRU', '', 'Таланджи рассказывает о том, что ей удалось добиться частичной поддержки в Зулдазаре, пока игрок ищет помощи забытого лоа.', 28153),
(130566, 'ruRU', '', 'КРАСИВАЯ КАТ-СЦЕНА/ПЕРЕМЕЩЕНИЕ. Вы видите голема титанов, поврежденного порчей. Кровавый матриарх замечает вас и пленяет Таланджи с помощью чар.', 28153),
(130494, 'ruRU', '', 'Свобода! Пора убираться отсюда, залезай!', 28153),
(130490, 'ruRU', '', 'И снова мои воины. Но тропа ведет дальше, туда же следует пойти и нам.', 28153),
(130485, 'ruRU', '', 'Это... просто бойня! Теперь ты понимаешь, с каким злом мы сражаемся, $n? Тролли крови – чудовища.', 28153),
(130383, 'ruRU', '', 'Рокхан, ты мудрый советчик, но пришла пора действовать... без промедления. Троллей крови нужно остановить.', 28153),
(130372, 'ruRU', '', 'Будь быстрее ветра и неумолимее смерти. Мы с Зулом будем ждать тебя у подножия пирамиды. Ее трудно не заметить.', 28153),
(130361, 'ruRU', '', 'Если выживешь, приходи к входу на склад бочек. У меня будет для тебя задание.', 28153),
(130353, 'ruRU', 'Я раньше не бывал в Зандаларе. Не думал, что Зулдазар окажется настолько величественным.$b$bБудь с зандаларами настороже. Они вроде все такие благопристойные, но тролли есть тролли. У нас не принято прощать слабости.', '', 28153),
(130352, 'ruRU', 'Принцесса Таланджи ждет тебя на другом конце дока. Не мешкай и под страхом смерти не входи в город до завершения ритуалов.\n\nИ оставь этот говорящий труп здесь. Только король может разрешить впустить его.', '', 28153),
(130121, 'ruRU', '', 'Как вам угодно.', 28153),
(130120, 'ruRU', 'И ответишь за преступления против Кул-Тираса.', '', 28153),
(130119, 'ruRU', 'Не беспокойся, ты увидишь Кэтрин.', '', 28153),
(130099, 'ruRU', '<Короткий разговор, в котором я смеюсь над Зулом и унижаю его, а потом говорю своей дочери, что она пренебрегла своим долгом.>', '', 28153),
(130096, 'ruRU', 'Знай, что наш король пережил сто двадцать три покушения.$b$bГоловами нападавших он украсил тронный зал.', '', 28153),
(130081, 'ruRU', '', 'Хочешь увидеть короля? Тогда ударь в гонг, и мы найдем для тебя подходящее испытание.', 28153),
(130079, 'ruRU', '', 'Получай благословение и уходи. Не возвращайся, если жизнь тебе дорога.', 28153),
(130075, 'ruRU', '', 'Как там поживает Вол\'джин? Умер, говорят. Жаль. Некоторые из нас прямо так и мечтают убить его еще разок.', 28153),
(130032, 'ruRU', '$R, говори быстрее и уходи. Амани не забыли, что твоя Орда покалечила и убила Зул\'джина, который так много значил для нашего народа. \n\nИз уважения к зандаларам я тебя предупрежу: это посольство – территория племени Амани. Если не уйдешь, мы тебя здесь же и похороним.', '', 28153),
(130031, 'ruRU', 'Вот тебе благословение и убирайся отсюда. Орде в племени Амани не место.', '', 28153),
(130030, 'ruRU', 'Смело. Вряд ли ты понимаешь, на что подписываешься. Победи всех учеников, что стоят за мной, и тогда мы дадим тебе наше благословение.', '', 28153),
(130003, 'ruRU', '', 'Я хочу встретиться с матерью.', 28153),
(129998, 'ruRU', '', 'Я леди Джайна Праудмур. Я прошу аудиенции лорда-адмирала Кэтрин Праудмур... моей матери.', 28153),
(129993, 'ruRU', '', 'Будь что будет.', 28153),
(129983, 'ruRU', 'А! Нет! Газ\'рагон! Бессердечная ты ордынская тварь! Получай благословение и вали отсюда.', '', 28153),
(129980, 'ruRU', 'Многое изменилось, пока тебя не было, принцесса. Ракира оказалась слишком слабой. Ее изгнали в Вол\'дун.', '', 28153),
(129979, 'ruRU', '', 'Джакра\'зет. Где сейчас мастер войны Ракира?', 28153),
(129978, 'ruRU', 'Тебе здесь не место, ордынская погань.', '', 28153),
(129969, 'ruRU', '[Загрузочный экран -> ВИС - Корабль на воде, Джайне снится кошмар, прибытие к вратам Боралуса.]', '[Загрузочный экран -> ВИС - Корабль на воде, Джайне снится кошмар, прибытие к вратам Боралуса.]', 28153),
(129968, 'ruRU', 'Нужны испытания? Ты их получишь. Ударь в гонг вон там и получишь от нас сколько угодно испытаний.', '', 28153),
(129967, 'ruRU', '<Бросить вызов>', '<Бросить вызов>', 28153),
(129966, 'ruRU', 'О, привет! Когда-то давно твой народ причинил мне и моим близким много боли. Чего ты хочешь?', '', 28153),
(129965, 'ruRU', 'Альянс этого не потерпит!', 'Альянс этого не потерпит!', 28153),
(129964, 'ruRU', 'Мы расскажем об этом королю!', 'Мы расскажем об этом королю!', 28153),
(129963, 'ruRU', 'Ладно, на этот раз победа за тобой.', 'Ладно, на этот раз победа за тобой.', 28153),
(129962, 'ruRU', 'Вам эту землю не удержать.', 'Вам эту землю не удержать.', 28153),
(129961, 'ruRU', 'Мы еще вернемся!', 'Мы еще вернемся!', 28153),
(129960, 'ruRU', 'Ты о нас еще услышишь, $p!', 'Ты о нас еще услышишь, $p!', 28153),
(129959, 'ruRU', 'Вот ты дрянь!', 'Вот ты дрянь!', 28153),
(129958, 'ruRU', 'Умри!', 'Умри!', 28153),
(129957, 'ruRU', 'Я слышал о тебе, $p! Я стану героем, когда убью тебя.', 'Я слышала о тебе, $p! Я стану героем, когда убью тебя.', 28153),
(129956, 'ruRU', 'Пока ты дышишь, я отсюда не уйду.', 'Пока ты дышишь, я отсюда не уйду.', 28153),
(129955, 'ruRU', 'Зандалары не заключают союзов с мертвецами.', 'Зандалары не заключают союзов с мертвецами.', 28153),
(129954, 'ruRU', 'Тебе от меня так просто не избавиться!', 'Тебе от меня так просто не избавиться!', 28153),
(129953, 'ruRU', 'Отродье Орды!', 'Отродье Орды!', 28153),
(129952, 'ruRU', 'Ни с какими недоноскам из Орды зандалары не объединятся.', 'Ни с какими недоноскам из Орды зандалары не объединятся.', 28153),
(129951, 'ruRU', 'Принцесса повелела изгнать тебя. Убирайся или умри.', 'Принцесса повелела изгнать тебя. Убирайся или умри.', 28153),
(129950, 'ruRU', 'Не прикасайся ко мне, отродье Орды.', 'Не прикасайся ко мне, отродье Орды.', 28153),
(129949, 'ruRU', 'Так-так-так, представитель Орды здесь, в Зулдазаре... Интересно.', 'Так-так-так, представитель Орды здесь, в Зулдазаре... Интересно.', 28153),
(129948, 'ruRU', 'Тебе тоже это нужно? Так вот, я первый пришел, и куплю первым тоже я!', 'Тебе тоже это нужно? Так вот, я первая пришла, и куплю первой тоже я!', 28153),
(129947, 'ruRU', 'Чего надо? Мне не до тебя.', 'Чего надо? Мне не до тебя.', 28153),
(129946, 'ruRU', 'Чего тебе, ордынское отродье?', 'Чего тебе, ордынское отродье?', 28153),
(129944, 'ruRU', '', 'Мне нужно подготовить корабль к отплытию. Встретимся в порту.', 28153),
(129940, 'ruRU', 'Слушай сюда. У меня здесь одно правило: хочешь подраться – идешь на улицу и дерешься там.\n\nПока ты соблюдаешь это правило, можешь тут спокойно ночевать.\n\nА, и если увидишь, что кто-то здесь занимается темными делишками, то я ничего не знаю и ни в чем не замешан.', '', 28153),
(129883, 'ruRU', 'Ни один чужак не пройдет в Зулдазар, пока я не отведаю его плоти!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(129881, 'ruRU', 'Ступай, смертное существо. Скажи дочери Растахана, что я дозволил тебе войти в город.', '', 28153),
(129880, 'ruRU', 'Я хочу войти в город.', 'Я хочу войти в город.', 28153),
(129879, 'ruRU', 'От тебя исходит новый запах и аромат битв. Соблазнительная жертва. Чего тебе от меня нужно?', '', 28153),
(129660, 'ruRU', 'Я созываю военный совет в крепости Штормграда. Нам необходимо твое присутствие.', '', 28153),
(128197, 'ruRU', 'Я возвращаюсь из глубин!', '', 28153),
(128196, 'ruRU', 'Вроде как прибыли. Мы займемся детектором, а вы пока обследуйте остров.', '', 28153),
(128195, 'ruRU', 'Сюда, батраки. Стойте-ка, тут человечиной воняет! Эй, людишки, слышите меня? Этот остров принадлежит Бургтоку!', '', 28153),
(127581, 'ruRU', 'Странная погода для этих широт. Похоже, азерит привлек внимание могущественного элементаля. Остерегайтесь его... Или убейте...', '', 28153),
(127580, 'ruRU', '', 'Посылаю рабочих в шахту на месторождение азерита.', 28153),
(127579, 'ruRU', '$n, наши разведчики обнаружили несколько островов с богатыми залежами азерита. Срочно нужен твой корабль.', '', 28153),
(127578, 'ruRU', 'Альянс! Свет даровал нам этот остров. Мы не хотим крови. Уходите! Это последнее предупреждение!', '', 28153),
(127577, 'ruRU', '', 'Грабь, убивай! Ха-ха! Тупень, стреляй по всем, кто не мы. Пит, ищи псов Альянса и делай с ними... в общем, то, что обычно делаешь. И про азерит не забудьте!', 28153),
(127576, 'ruRU', 'Эй, у меня найдется для тебя пара полезных вещичек.', '', 28153),
(127575, 'ruRU', '', 'Ваши союзники-озаренные готовы прийти на помощь!', 28153),
(127574, 'ruRU', 'Сюда подходят корабли Орды. Думаю, вам стоит поторопиться.', '', 28153),
(127573, 'ruRU', 'Да? У нас есть приказ – азерит ждет. Взгляни на стол и дай мне знать, когда можно отправляться.\n\nЗнаю, от меня сложно оторвать взгляд, но нам нужно сосредоточиться на деле.', '', 28153),
(127569, 'ruRU', 'Перезапустить текущий остров.', 'Перезапустить текущий остров.', 28153),
(127568, 'ruRU', 'Полдела сделано. Не останавливайтесь!', '', 28153),
(127501, 'ruRU', 'Эй, ты! Спаси Грязную Бороду! Я дам тебе много блестяшек!', '', 28153),
(126508, 'ruRU', '|cFF0EA6DC+$1i|r |cFFFFFF00ед. азерита|r', '|cFF0EA6DC+$1i|r |cFFFFFF00ед. азерита|r', 28153),
(124726, 'ruRU', 'Расшифровать правила', 'Расшифровать правила', 28153),
(124724, 'ruRU', 'Перезапустить игру', 'Перезапустить игру', 28153),
(124723, 'ruRU', 'Начать игру', 'Начать игру', 28153),
(124717, 'ruRU', '------------------------------$bМАКСИМАЛЬНАЯ СЛОЖНОСТЬ$b------------------------------$b\nКогда вы кладете руку на консоль, она начинает гудеть и присвистывать. По центральному экрану проносятся бесконечные каскады символов, большинство из которых сопровождают изображения черепов или рожиц с крестиками вместо глаз. На этом уровне вы можете использовать дополнительное время, но один из таймеров заминирован.$b$bИграет веселая музыка. Видимо, консоль желает вам удачи в самом сложном испытании. Или прощается?', '', 28153),
(124716, 'ruRU', '---------------$b   УРОВЕНЬ 4$b---------------$b\nКонсоль привычно отвечает на ваше прикосновение появлением множества шестиугольников и радостной музыкой.$b$bРасшифровать древние символы, ползущие по центральному экрану, все так же трудно, но, как вы понимаете, большинство игроков, решивших попытать удачу на следующем уровне сложности, было безжалостно уничтожено.$b$bХорошая новость состоит в том, что в одной из фигур сокрыто дополнительное время.', '', 28153),
(124715, 'ruRU', '---------------$b  УРОВЕНЬ 3$b---------------$b\nВы видите на экране консоли теплое приветствие, несмотря на то, что игра уже несколько раз пыталась вас убить.$b$bСогласно символам, описывающим следующий уровень испытаний, подсказок и времени на этот раз будет меньше, а мин – больше.', '', 28153),
(124714, 'ruRU', '---------------$b  УРОВЕНЬ 2$b---------------$b\nКонсоль издает писк и чириканье, когда узнает вас по прикосновению. Видимо, правила изменились, и теперь пиктограммы показывают, что включен таймер.$b$bЕсли не разгадать головоломку вовремя, наказанием, скорее всего, будет не смерть, а боль. Это здорово.', '', 28153),
(124713, 'ruRU', 'Вы расшифровываете пиктограммы, изо всех сил стараясь не обращать внимания на предостережения о мгновенной смерти.$b$bКонсоль игры \"Магические мины\" делит пол на шестиугольники, которые реагируют на шаги. Несколько шестиугольников \"заминированы\" и приведут к гибели игрока. Если же вы наступите на \"безопасный\" участок, на нем появится цифра, обозначающая количество мин в смежных участках.$b$bЦель игры – \"расчистить\" поле, наступив на все безопасные шестиугольники и отметив заминированные предоставленными вам белыми флажками.$b$bНепонятно, почему игра считает нужным убивать игроков, наступивших на неверный шестиугольник.', '', 28153),
(124711, 'ruRU', '---------------$b   УРОВЕНЬ 1$b---------------$b\nОт вашего прикосновения эта таинственная магическая консоль пробуждается. По центральной панели страница за страницей пробегают инструкции. Язык вам незнаком, но значки не требуют пояснений:$bвы видите множество черепов.$b$bЭто \"Магические мины\", самая опасная игра, в которой игроку предстоит пересечь магическое минное поле и обнаружить все заминированные области. Наградой за любой неверный шаг служит мгновенная смерть.$b$bВы задаетесь вопросом, кто пойдет на это по собственной воле.', '', 28153),
(124677, 'ruRU', 'УРОВЕНЬ 5', '', 28153),
(124676, 'ruRU', 'УРОВЕНЬ 4', '', 28153),
(124675, 'ruRU', 'УРОВЕНЬ 3', '', 28153),
(124674, 'ruRU', 'УРОВЕНЬ 2', '', 28153),
(124673, 'ruRU', 'УРОВЕНЬ 1', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(167308, 'zhCN', 'I want to teleport to Waycrest Manor (Dungeon).', 'I want to teleport to Waycrest Manor (Dungeon).', 28153),
(167307, 'zhCN', 'I want to teleport to Tol Dagor (Dungeon).', 'I want to teleport to Tol Dagor (Dungeon).', 28153),
(167306, 'zhCN', 'I want to teleport to The Underrot (Dungeon).', 'I want to teleport to The Underrot (Dungeon).', 28153),
(167305, 'zhCN', 'I want to teleport to  The MOTHERLODE!! (Dungeon).', 'I want to teleport to  The MOTHERLODE!! (Dungeon).', 28153),
(167304, 'zhCN', 'I want to teleport to Temple of Sethraliss (Dungeon).', 'I want to teleport to Temple of Sethraliss (Dungeon).', 28153),
(167302, 'zhCN', 'I want to teleport to Siege of Boralus (Dungeon).', 'I want to teleport to Siege of Boralus (Dungeon).', 28153),
(167301, 'zhCN', 'I want to teleport to Shrine of the Storm (Dungeon).', 'I want to teleport to Shrine of the Storm (Dungeon).', 28153),
(167300, 'zhCN', 'I want to teleport to Kings\' Rest (Dungeon).', 'I want to teleport to Kings\' Rest (Dungeon).', 28153),
(167299, 'zhCN', 'I want to teleport to Freehold (Dungeon).', 'I want to teleport to Freehold (Dungeon).', 28153),
(167298, 'zhCN', 'I want to teleport to Atal\'dazar (Dungeon).', 'I want to teleport to Atal\'dazar (Dungeon).', 28153),
(167297, 'zhCN', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 28153),
(167296, 'zhCN', '', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 28153),
(162171, 'zhCN', '暗炉城', '暗炉城', 28153),
(162170, 'zhCN', '你不能擅离职守，快回达纳苏斯！', '你不能擅离职守，快回达纳苏斯！', 28153),
(162169, 'zhCN', '', '你准备好做个了断了吗，$n？', 28153),
(162168, 'zhCN', '<飞往达拉然>', '<飞往达拉然>', 28153),
(162167, 'zhCN', '你能引导洛找到所有的商店，然后前往旅店，其间还不去重复他走过的路吗？', '', 28153),
(162166, 'zhCN', '', '你准备好了吗？要不要护送这些年幼的海龟前往大海？', 28153),
(162165, 'zhCN', '我准备好了。', '我准备好了。', 28153),
(162164, 'zhCN', '欢迎，$n。你觉得自己的脑子灵光吗？要不要来玩玩我的配对游戏？', '', 28153),
(162161, 'zhCN', '你确定要跳过对黑海岸的介绍？', '你确定要跳过对黑海岸的介绍？', 28153),
(162160, 'zhCN', '怎么，$n？你好像心事重重……', '', 28153),
(162159, 'zhCN', '<失落的水手用挑剔的眼光看着你。你不应该来这儿。>', '<失落的水手用挑剔的眼光看着你。你不应该来这儿。>', 28153),
(162158, 'zhCN', '我以前听过这个故事……<跳过引导任务，从黑海岸开始你的旅程。>', '我以前听过这个故事……<跳过剧情，开始你的下一个任务。>', 28153),
(162157, 'zhCN', '我会把你安全送回去的，$n。抓紧了！', '', 28153),
