(159017, 'zhCN', '我要除掉你，然后用你的尸体去喂虫群！', '我要除掉你，然后用你的尸体去喂虫群！', 28153),
(159016, 'zhCN', '你就这么想消亡吗？', '你就这么想消亡吗？', 28153),
(159015, 'zhCN', '金矿石是我们的！献给女皇的礼物！', '金矿石是我们的！献给女皇的礼物！', 28153),
(159014, 'zhCN', '我们是女皇的虫群！', '我们是女皇的虫群！', 28153),
(159013, 'zhCN', '虫群势不可挡！', '虫群势不可挡！', 28153),
(159012, 'zhCN', '我们女皇甜美的歌声将赐予你死亡！', '我们女皇甜美的歌声将赐予你死亡！', 28153),
(159011, 'zhCN', '我听从女皇的命令！', '我听从女皇的命令！', 28153),
(159010, 'zhCN', '为了女皇！', '为了女皇！', 28153),
(159009, 'zhCN', '联盟必将永存……而女妖之王的邪恶统治必须终结。', '', 28153),
(159008, 'zhCN', '她以为这种暴行可以击垮我们的意志和团结。但我发誓……', '', 28153),
(159007, 'zhCN', '哇啊！荣耀的一击……', '哇啊！荣耀的一击……', 28153),
(159006, 'zhCN', '呀啊！这就是我渴望的死亡！', '呀啊！这就是我渴望的死亡！', 28153),
(159005, 'zhCN', '但只要希尔瓦娜斯·风行者还在领导部落，这个梦想就不可能实现。', '', 28153),
(159004, 'zhCN', '我驶向了……夕阳……', '我驶向了……夕阳……', 28153),
(159003, 'zhCN', '我这一生，都在为这个世界寻求和平。', '', 28153),
(159002, 'zhCN', '我会带着这些老战士夺回我的领地……', '我会带着这些老战士夺回我的领地……', 28153),
(159001, 'zhCN', '对联盟而言这是无比黑暗的一天，但你向我们展现了勇气与决心，勇士。', '', 28153),
(159000, 'zhCN', '灵魂会指引我的道路……', '灵魂会指引我的道路……', 28153),
(158999, 'zhCN', '', '养精蓄锐。准备好接下来的战斗。我还会找你的。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158998, 'zhCN', '我光荣地战死了！', '我光荣地战死了！', 28153),
(158997, 'zhCN', '部族会替我报仇……', '部族会替我报仇……', 28153),
(158996, 'zhCN', '', '不过他们已经元气大伤。在未来的战争中，怒火只会是他们的弱点，而非助益。', 28153),
(158995, 'zhCN', '你的死期到了……', '你的死期到了……', 28153),
(158994, 'zhCN', '又一个等着被征服的小角色！', '又一个等着被征服的小角色！', 28153),
(158993, 'zhCN', '又一场光荣的战斗！', '又一场光荣的战斗！', 28153),
(158992, 'zhCN', '我会挖出你的眼睛！', '我会挖出你的眼睛！', 28153),
(158991, 'zhCN', '', '但我们只成功了一半。联盟会来报仇的。他们会来找我们。找我。还有你。', 28153),
(158990, 'zhCN', '', '我们的进攻本来是为了在萌芽阶段就终结这场战争……一鼓作气攻占敌人的主城，消灭他们的领袖。让联盟从此元气大伤，无力回天。', 28153),
(158989, 'zhCN', '', '我派你去完成这项任务时，可没想到这个结果。', 28153),
(158988, 'zhCN', '千艘战舰将带来你的末日！', '千艘战舰将带来你的末日！', 28153),
(158987, 'zhCN', '为了约伦而战！', '为了约伦而战！', 28153),
(158986, 'zhCN', '为了赤潮！', '为了赤潮！', 28153),
(158985, 'zhCN', '为荣耀而死！', '为荣耀而死！', 28153),
(158984, 'zhCN', '我要吃了你的心！', '我要吃了你的心！', 28153),
(158983, 'zhCN', 'Mrglrggg...', 'Mrglrggg...', 28153),
(158982, 'zhCN', 'Mrrg mrgl？', 'Mrrg mrgl？', 28153),
(158981, 'zhCN', 'Rgll mgrgl...rgl...', 'Rgll mgrgl...rgl...', 28153),
(158980, 'zhCN', 'Grgl...', 'Grgl...', 28153),
(158979, 'zhCN', 'Mrg!', 'Mrg!', 28153),
(158978, 'zhCN', 'Rgl...mrg...', 'Rgl...mrg...', 28153),
(158977, 'zhCN', 'Mrrrmgrl!', 'Mrrrmgrl!', 28153),
(158976, 'zhCN', 'Mrglrgl？Mrg! Rgl！', 'Mrglrgl？Mrg！Rgl！', 28153),
(158975, 'zhCN', 'Rgrml grml grml!', 'Rgrml grml grml!', 28153),
(158974, 'zhCN', '', '我的天呐，这太完美了！非常感谢你，$p，你可真是个好心人。给你，带上一些饼干吧。', 28153),
(158973, 'zhCN', 'Mrg？Grml？！', 'Mrg？Grml？！', 28153),
(158972, 'zhCN', 'Mrgl？Rgl！', 'Mrgl？Rgl！', 28153),
(158971, 'zhCN', 'Mrglrglrgl!', 'Mrglrglrgl!', 28153),
(158970, 'zhCN', '对于无尽的虚空而言，死亡毫无意义……', '对于无尽的虚空而言，死亡毫无意义……', 28153),
(158969, 'zhCN', '准备好见证他的再次降临吧……', '准备好见证他的再次降临吧……', 28153),
(158968, 'zhCN', '深渊将带来你的末日……', '深渊将带来你的末日……', 28153),
(158967, 'zhCN', '你无法消灭我们……我们是无穷无尽的……', '你无法消灭我们……我们是无穷无尽的……', 28153),
(158966, 'zhCN', '你会失败的……你的朋友会抛弃你……', '你会失败的……你的朋友会抛弃你……', 28153),
(158965, 'zhCN', '你听到下面黑暗的呼唤了吗？', '你听到下面黑暗的呼唤了吗？', 28153),
(158964, 'zhCN', '疯狂的深渊是无法被抑制的！', '疯狂的深渊是无法被抑制的！', 28153),
(158963, 'zhCN', '我的尸体上还会重生数以千计的我。', '我的尸体上还会重生数以千计的我。', 28153),
(158962, 'zhCN', '蠕动的黑暗将敲响最后的钟声。', '蠕动的黑暗将敲响最后的钟声。', 28153),
(158961, 'zhCN', '深渊中的吞噬者渴望吃掉你们的世界！', '深渊中的吞噬者渴望吃掉你们的世界！', 28153),
(158960, 'zhCN', '你无法战胜你所恐惧的事物！', '你无法战胜你所恐惧的事物！', 28153),
(158959, 'zhCN', '我们将会暗中遍布四处，直到你们的世界被恐惧和眼睛所包围。', '我们将会暗中遍布四处，直到你们的世界被恐惧和眼睛所包围。', 28153),
(158958, 'zhCN', '黑暗的深渊在召唤你。', '黑暗的深渊在召唤你。', 28153),
(158957, 'zhCN', '尖叫着坠入深渊吧！', '尖叫着坠入深渊吧！', 28153),
(158956, 'zhCN', '我们会吞噬你们！', '我们会吞噬你们！', 28153),
(158955, 'zhCN', '你的躯体将滋养黑暗！', '你的躯体将滋养黑暗！', 28153),
(158954, 'zhCN', '这下翻船了……', '这下翻船了……', 28153),
(158953, 'zhCN', '我一直以为自己会……死在海上……', '我一直以为自己会……死在海上……', 28153),
(158952, 'zhCN', '不能就这样……死掉……', '不能就这样……死掉……', 28153),
(158951, 'zhCN', '都是……领航员惹的祸……', '都是……领航员惹的祸……', 28153),
(158950, 'zhCN', '救我……你们这帮狗东西……', '救我……你们这帮狗东西……', 28153),
(158949, 'zhCN', '死……总比继续待在这里强……', '死……总比继续待在这里强……', 28153),
(158948, 'zhCN', '咱们就……不应该来这里……', '咱们就……不应该来这里……', 28153),
(158947, 'zhCN', '你们是我带过最差的……一届船员……', '你们是我带过最差的……一届船员……', 28153),
(158946, 'zhCN', '你的船是我们的了，混蛋！', '你的船是我们的了，混蛋！', 28153),
(158945, 'zhCN', '看啊小的们，宝藏撞进了咱们怀里，还带来了一条出去的路！', '看啊小的们，宝藏撞进了咱们怀里，还带来了一条出去的路！', 28153),
(158944, 'zhCN', '他们有一艘船！抓住他们！', '他们有一艘船！抓住他们！', 28153),
(158943, 'zhCN', '你们会后悔来这里！', '你们会后悔来这里！', 28153),
(158942, 'zhCN', '啊，这次我好像朗姆酒喝多了一点……', '啊，这次我好像朗姆酒喝多了一点……', 28153),
(158941, 'zhCN', '你们这帮狗东西，咱们挨打了！所有人都起来！', '你们这帮狗东西，咱们挨打了！所有人都起来！', 28153),
(158940, 'zhCN', '没人会来救咱们了，抓住他们！', '没人会来救咱们了，抓住他们！', 28153),
(158939, 'zhCN', '啊，咱们得走了！快抓住他们！', '啊，咱们得走了！快抓住他们！', 28153),
(158938, 'zhCN', '我将回归深渊……像个水手那样死去……', '我将回归深渊……像个水手那样死去……', 28153),
(158937, 'zhCN', '啊……在我走之前再给我一杯朗姆酒……', '啊……在我走之前再给我一杯朗姆酒……', 28153),
(158936, 'zhCN', '这里……好黑……', '这里……好黑……', 28153),
(158935, 'zhCN', '啊……卑鄙的伎俩……', '啊……卑鄙的伎俩……', 28153),
(158934, 'zhCN', '到……船上去……', '到……船上去……', 28153),
(158933, 'zhCN', '呀啊！正中要害……', '呀啊！正中要害……', 28153),
(158932, 'zhCN', '你们永远不会发现……我的宝藏……', '你们永远不会发现……我的宝藏……', 28153),
(158931, 'zhCN', '啊...我的宝藏……', '啊...我的宝藏……', 28153),
(158930, 'zhCN', '保护我，你们这帮没用的蠢货！', '保护我，你们这帮没用的蠢货！', 28153),
(158929, 'zhCN', '来我身边，你们这群下流的狗东西，有人上船了！', '来我身边，你们这群下流的狗东西，有人上船了！', 28153),
(158928, 'zhCN', '你不该来这里，这里是海盗的地盘！', '你不该来这里，这里是海盗的地盘！', 28153),
(158927, 'zhCN', '啊，小的们，我们中出现了入侵者！', '啊，小的们，我们中出现了入侵者！', 28153),
(158926, 'zhCN', '烧杀抢掠，呀呼！', '烧杀抢掠，呀呼！', 28153),
(158925, 'zhCN', '你是想挨刀子了吧！', '你是想挨刀子了吧！', 28153),
(158924, 'zhCN', '我要让你去走木板！', '我要让你去走木板！', 28153),
(158923, 'zhCN', '你们这帮无赖快停下，快去赶走入侵者！', '你们这帮无赖快停下，快去赶走入侵者！', 28153),
(158922, 'zhCN', '没人能阻碍我们追猎欧诺霍！', '', 28153),
(158921, 'zhCN', '大海将你带给了我们，你休想脱身……', '', 28153),
(158920, 'zhCN', '在等待海洋的指引时，我们也能磨练战斗的技艺！', '', 28153),
(158919, 'zhCN', '潮起潮落预示了这次相遇。', '', 28153),
(158918, 'zhCN', '你面对着强大的狩猎部族，你还指望自己能活下来？', '', 28153),
(158917, 'zhCN', '大海带来了新鲜的肉和全新的武器，赞美海潮！', '', 28153),
(158916, 'zhCN', '你的血肉和补给将成为我们狩猎的猎物，感谢之至！', '', 28153),
(158915, 'zhCN', '我们的部族已经狩猎巨兽多年了，今日你无法阻止我们！', '', 28153),
(158914, 'zhCN', '浅滩……揭示过这个命运……', '', 28153),
(158913, 'zhCN', '海潮……会带我走……', '', 28153),
(158912, 'zhCN', '狩猎……又夺走了一条性命……', '', 28153),
(158911, 'zhCN', '你……也是……出色的猎手……', '', 28153),
(158910, 'zhCN', '啊……漂亮的一击……', '', 28153),
(158909, 'zhCN', '大海最终会吞噬所有人……', '', 28153),
(158908, 'zhCN', '即使没有了我……狩猎仍将继续……', '', 28153),
(158907, 'zhCN', '我们……绝不后悔……', '', 28153),
(158906, 'zhCN', '好像外来者都被冲上了海滩。', '', 28153),
(158905, 'zhCN', '我们感谢你的牺牲。', '', 28153),
(158904, 'zhCN', '夺取他们的补给品，我们今晚就要大摆宴席！', '', 28153),
(158903, 'zhCN', '你胆敢挑战我们的氏族？', '', 28153),
(158902, 'zhCN', '你就是这场狩猎的猎物。', '', 28153),
(158901, 'zhCN', '你的尸体可以滋养我们，多谢。', '', 28153),
(158900, 'zhCN', '海洋给我们送来了新的补给……', '', 28153),
(158899, 'zhCN', '海潮预言了你的到来。', '', 28153),
(158898, 'zhCN', '', '我就是喜欢这地方的各种有趣的小动物。兔子、飞鸟、螃蟹，你能想到的我都很喜欢。我已经把几只宠物训练成了冠军斗士，你看到我身边这个大块头的尸体了吗？我的宠物只花了四分钟就搞定了它。真是饥渴的小家伙们。想看看它们在战斗中的身姿吗？', 28153),
(158897, 'zhCN', '', '请你照看好米尔拉，好吗？\n\n她根本不了解沙漠真正的危险之处。我可不想看着她被流沙吞没……', 28153),
(158896, 'zhCN', '', '你的朋友看起来好多了。我很高兴基罗和米尔拉能帮上忙。', 28153),
(158895, 'zhCN', '', '欢迎来到我们的家，$n，虽然只是暂时的。\n\n就算蛇人发现了我们的藏身地，商队也能即刻出发。', 28153),
(158894, 'zhCN', '看看你能不能在穿过沿途所有海藻的同时，把洛引导到安全之处。', '', 28153),
(158893, 'zhCN', '', '我们当然会的！给你，带上一些面粉炸弹。请你对他们一定要小心。', 28153),
(158892, 'zhCN', '想换点熊肉吗？', '', 28153),
(158891, 'zhCN', '库亚冯飞奔而去！', '', 28153),
(158890, 'zhCN', '库亚冯在你的触及之外拿着头骨，尾巴淘气地拍打着。', '', 28153),
(158889, 'zhCN', '你没……那么好。', '', 28153),
(158888, 'zhCN', '我就要拿走我想要的！', '', 28153),
(158887, 'zhCN', '我喜欢你的装备……要交易吗？', '', 28153),
(158886, 'zhCN', '撤回……水中……', '', 28153),
(158885, 'zhCN', '部族不会灭亡……今日不会……', '', 28153),
(158884, 'zhCN', '呃……怎么会……？', '', 28153),
(158883, 'zhCN', '我将返回……海潮……', '', 28153),
(158882, 'zhCN', '宝藏……是我的……', '', 28153),
(158881, 'zhCN', '嘶……你们会遭报应的……', '', 28153),
(158880, 'zhCN', '嘶……强盗……', '', 28153),
(158879, 'zhCN', '呃啊……我的血……', '', 28153),
(158878, 'zhCN', '嘶！干掉他们！保卫这些宝藏！', '', 28153),
(158877, 'zhCN', '宝石会使我们的部族强大，我们绝不屈服！', '', 28153),
(158876, 'zhCN', '我会享用你的血肉，咀嚼你的骨头！', '', 28153),
(158875, 'zhCN', '你竟敢直面一位强大的战士？', '', 28153),
(158874, 'zhCN', '我会保护部族！去死吧！', '', 28153),
(158873, 'zhCN', '入侵者！仆从们，干掉他们嘶嘶！', '', 28153),
(158872, 'zhCN', '这宝藏属于我的部族，你们这些小偷嘶嘶嘶！', '', 28153),
(158871, 'zhCN', '我的部族强大无比，你们阻止不了我们！', '', 28153),
(158870, 'zhCN', '我去帮你找找看。', '我去帮你找找看。', 28153),
(158869, 'zhCN', '你们的宝藏归我们啦！', '', 28153),
(158868, 'zhCN', '我给你准备了一些冰淇淋！', '我给你准备了一些冰淇淋！', 28153),
(158867, 'zhCN', '我会把你开膛破肚，像条嘶嘶死鱼一样！', '', 28153),
(158866, 'zhCN', '保护部族！', '', 28153),
(158865, 'zhCN', '嘶嘶撕烂他们，把宝藏给我带回来！', '', 28153),
(158864, 'zhCN', '嘶！我们被打了！', '', 28153),
(158863, 'zhCN', '是温血动物！', '', 28153),
(158862, 'zhCN', '干掉他们。夺走他们的东西嘶嘶！', '', 28153),
(158861, 'zhCN', '嘶！干掉你们！', '', 28153),
(158860, 'zhCN', '我的孩子们又有东西吃了！', '我的孩子们又有东西吃了！', 28153),
(158859, 'zhCN', '我能为你做点什么？', '我能为你做点什么？', 28153),
(158858, 'zhCN', '呵咔咔，又一个掉到我们洞里的家伙，你的旅途到头了……', '呵咔咔，又一个掉到我们洞里的家伙，你的旅途到头了……', 28153),
(158857, 'zhCN', '美味的肉，送上了我们巢穴的门，太好了。', '美味的肉，送上了我们巢穴的门，太好了。', 28153),
(158856, 'zhCN', '你的鲜血将被喂食给幼体，你的肉体将用来滋养女王，而我将吃掉你的脑子！', '你的鲜血将被喂食给幼体，你的肉体将用来滋养女王，而我将吃掉你的脑子！', 28153),
(158855, 'zhCN', '你永远无法找到那些卵，我们的虫群是不朽的！', '你永远无法找到那些卵，我们的虫群是不朽的！', 28153),
(158854, 'zhCN', '不要反抗了，猎物，这只会延长你的痛苦！', '不要反抗了，猎物，这只会延长你的痛苦！', 28153),
(158853, 'zhCN', '哈，又一个网中的猎物，嘶！', '哈，又一个网中的猎物，嘶！', 28153),
(158852, 'zhCN', '我们誓死守护我们的巢群！', '我们誓死守护我们的巢群！', 28153),
(158851, 'zhCN', '小心……入侵者……', '小心……入侵者……', 28153),
(158850, 'zhCN', '你无法……伤害……虫卵……', '你无法……伤害……虫卵……', 28153),
(158849, 'zhCN', '你别想把我们……全找到……', '你别想把我们……全找到……', 28153),
(158848, 'zhCN', '我们还不该……被你干掉……', '我们还不该……被你干掉……', 28153),
(158847, 'zhCN', '你的血肉将被喂食给幼体……', '你的血肉将被喂食给幼体……', 28153),
(158846, 'zhCN', '啊嘶嘶……痛苦……', '啊嘶嘶……痛苦……', 28153),
(158845, 'zhCN', '保卫……巢群……', '保卫……巢群……', 28153),
(158844, 'zhCN', '咔嘶……', '咔嘶……', 28153),
(158843, 'zhCN', '你的肉体将会被拿去喂食幼体！', '你的肉体将会被拿去喂食幼体！', 28153),
(158842, 'zhCN', '呵咔咔，快到网里来！', '呵咔咔，快到网里来！', 28153),
(158841, 'zhCN', '入侵者！', '入侵者！', 28153),
(158840, 'zhCN', '我们会保护巢群！', '我们会保护巢群！', 28153),
(158839, 'zhCN', '嘶嘶嘶，新鲜的血液……', '嘶嘶嘶，新鲜的血液……', 28153),
(158838, 'zhCN', '猎物来了……', '猎物来了……', 28153),
(158837, 'zhCN', '你弄乱了我的网嘶嘶！', '你弄乱了我的网嘶嘶！', 28153),
(158836, 'zhCN', '嘶嘶……入侵者……', '嘶嘶……入侵者……', 28153),
(158835, 'zhCN', '', '我最近有点长蛀牙了。我真的很想吃美味的草莓冰淇淋！\n\n如果你能帮我找一些来，我会非常感激你。如果不是太麻烦的话，之后请再带足够的数量到店里来。希望我没有打扰你！', 28153),
(158834, 'zhCN', '', '你看起来消瘦了，亲爱的，你最近都有好好吃饭吗？', 28153),
(158833, 'zhCN', '', '啊。你大老远跑来就是为见我？', 28153),
(158832, 'zhCN', '', '你好啊，亲爱的。很高兴见到你。', 28153),
(158831, 'zhCN', '嗷！嗷呜！', '', 28153),
(158830, 'zhCN', '你……不能……', '', 28153),
(158829, 'zhCN', '呃啊……', '', 28153),
(158828, 'zhCN', '呃……', '', 28153),
(158827, 'zhCN', '你……难闻……', '', 28153),
(158826, 'zhCN', '快……跑……', '', 28153),
(158825, 'zhCN', '呼呃……', '', 28153),
(158824, 'zhCN', '啊……咯呃……', '', 28153),
(158823, 'zhCN', '新气味，不是好东西，哇啊！', '', 28153),
(158822, 'zhCN', '啊，闻到肉了！', '', 28153),
(158821, 'zhCN', '嘎嗷！我们吃了你！', '', 28153),
(158820, 'zhCN', '咬死你，吃你的肉！', '', 28153),
(158819, 'zhCN', '去死！哇啊！', '', 28153),
(158818, 'zhCN', '嗷……我……杀了你！', '', 28153),
(158817, 'zhCN', '嗷呜哇啊啊！', '', 28153),
(158816, 'zhCN', '嗷啊！', '', 28153),
(158815, 'zhCN', '这些荒野众生比你年长得多，而且还会比你活得更久。', '这些荒野众生比你年长得多，而且还会比你活得更久。', 28153),
(158814, 'zhCN', '这些发光的宝石是大自然给予我们的馈赠，我们会保护它们免遭你们的毒手！', '这些发光的宝石是大自然给予我们的馈赠，我们会保护它们免遭你们的毒手！', 28153),
(158813, 'zhCN', '你生命的循环将在今天终结，入侵者，你的尸体将成为我们成长的养料。', '你生命的循环将在今天终结，入侵者，你的尸体将成为我们成长的养料。', 28153),
(158812, 'zhCN', '我会在你进一步腐化我们的土地之前消除你这个威胁。', '我会在你进一步腐化我们的土地之前消除你这个威胁。', 28153),
(158811, 'zhCN', '你的尸体将成为你一路以来所蹂躏土地的肥料。', '你的尸体将成为你一路以来所蹂躏土地的肥料。', 28153),
(158810, 'zhCN', '你们的种群已经失去了平衡，无法再维系下去了。我必须进行干预。', '你们的种群已经失去了平衡，无法再维系下去了。我必须进行干预。', 28153),
(158809, 'zhCN', '为了保护被你破坏的平衡，我必须消灭你。', '为了保护被你破坏的平衡，我必须消灭你。', 28153),
(158808, 'zhCN', '我们负责保护这片土地和在此生存的野兽，我们不欢迎你！', '我们负责保护这片土地和在此生存的野兽，我们不欢迎你！', 28153),
(158807, 'zhCN', '你们的族群是……散播凋零的疫病……', '你们的族群是……散播凋零的疫病……', 28153),
(158806, 'zhCN', '你们污染了……我们的土地……', '你们污染了……我们的土地……', 28153),
(158805, 'zhCN', '你无法消灭……大自然……', '你无法消灭……大自然……', 28153),
(158804, 'zhCN', '我们会……重新生长……', '我们会……重新生长……', 28153),
(158803, 'zhCN', '你们的族群……无法长久……', '你们的族群……无法长久……', 28153),
(158802, 'zhCN', '我将……化为土地的养料……', '我将……化为土地的养料……', 28153),
(158801, 'zhCN', '你破坏了……平衡……', '你破坏了……平衡……', 28153),
(158800, 'zhCN', '我会回归……大自然……', '我会回归……大自然……', 28153),
(158799, 'zhCN', '我们负责守护这片土地！', '我们负责守护这片土地！', 28153),
(158798, 'zhCN', '发光的宝石是献给荒野的礼物！', '发光的宝石是献给荒野的礼物！', 28153),
(158797, 'zhCN', '我们必须维持平衡！', '我们必须维持平衡！', 28153),
(158796, 'zhCN', '你们无法腐化我们的林地！', '你们无法腐化我们的林地！', 28153),
(158795, 'zhCN', '我来响应自然的召唤！', '我来响应自然的召唤！', 28153),
(158794, 'zhCN', '这片土地不会被你所破坏，入侵者！', '这片土地不会被你所破坏，入侵者！', 28153),
(158793, 'zhCN', '自然将指引我的愤怒！', '自然将指引我的愤怒！', 28153),
(158792, 'zhCN', '我是荒野的守护者！', '我是荒野的守护者！', 28153),
(158791, 'zhCN', '我每天都会到这里和我的祖父祖母说话。我想他们能听得到我！', '', 28153),
(158790, 'zhCN', '呜啊……', '呜啊……', 28153),
(158789, 'zhCN', '我……这是在哪……？', '我……这是在哪……？', 28153),
(158788, 'zhCN', '啊……血……', '啊……血……', 28153),
(158787, 'zhCN', '', '等战斗胜利了，真正的工作才刚刚开始。', 28153),
(158786, 'zhCN', '我的怒气……消散了……', '我的怒气……消散了……', 28153),
(158785, 'zhCN', '你们……为什么……', '你们……为什么……', 28153),
(158784, 'zhCN', '必须……逃走……', '必须……逃走……', 28153),
(158783, 'zhCN', '我现在……看得更清楚了……', '我现在……看得更清楚了……', 28153),
(158782, 'zhCN', '呃啊……痛苦……', '呃啊……痛苦……', 28153),
(158781, 'zhCN', '吼呜！', '吼呜！', 28153),
(158780, 'zhCN', '我生气了！', '我生气了！', 28153),
(158779, 'zhCN', '陌生的……', '陌生的……', 28153),
(158778, 'zhCN', '闻到了恐惧……', '闻到了恐惧……', 28153),
(158777, 'zhCN', '滚开……呃呃……', '滚开……呃呃……', 28153),
(158776, 'zhCN', '斩除……你……', '斩除……你……', 28153),
(158775, 'zhCN', '呃……', '呃……', 28153),
(158774, 'zhCN', '啊啊！', '啊啊！', 28153),
(158773, 'zhCN', '看看他都长得多大了！就像他父亲一样。', '', 28153),
(158772, 'zhCN', '诅咒你……', '诅咒你……', 28153),
(158771, 'zhCN', '我看到……先祖们了……', '我看到……先祖们了……', 28153),
(158770, 'zhCN', '万灵……正在欢迎我……', '万灵……正在欢迎我……', 28153),
(158769, 'zhCN', '你毫无……荣耀……', '你毫无……荣耀……', 28153),
(158768, 'zhCN', '啊……你击败了我……', '啊……你击败了我……', 28153),
(158767, 'zhCN', '你无法把我们……都杀光……', '你无法把我们……都杀光……', 28153),
(158766, 'zhCN', '我会在另一个世界……向你复仇……', '我会在另一个世界……向你复仇……', 28153),
(158765, 'zhCN', '加入万灵之列……', '加入万灵之列……', 28153),
(158764, 'zhCN', '我要用你的骨头来作法，诅咒你全家！', '我要用你的骨头来作法，诅咒你全家！', 28153),
(158763, 'zhCN', '你不过是个一无是处的肮脏的外来者，你不属于这里！', '你不过是个一无是处的肮脏的外来者，你不属于这里！', 28153),
(158762, 'zhCN', '', '我们的小兄弟还是个小屁孩仿佛就是昨天的事。现在看看他！', 28153),
(158761, 'zhCN', '啊，你们是谁？这里不欢迎你们，懂吗？', '啊，你们是谁？这里不欢迎你们，懂吗？', 28153),
(158760, 'zhCN', '来看看你们有什么吧……', '来看看你们有什么吧……', 28153),
(158759, 'zhCN', '我们现在有宝石了，我的部族现在是最强的！', '我们现在有宝石了，我的部族现在是最强的！', 28153),
(158758, 'zhCN', '你们不会那么容易找到我的，嘿嘿。', '你们不会那么容易找到我的，嘿嘿。', 28153),
(158757, 'zhCN', '这是我的岛屿、我的宝石，你们在这里只是寻死罢了。', '这是我的岛屿、我的宝石，你们在这里只是寻死罢了。', 28153),
(158756, 'zhCN', '这地方是我们找到的，入侵者，你们别想把它抢走！', '这地方是我们找到的，入侵者，你们别想把它抢走！', 28153),
(158755, 'zhCN', '这是我们的岛！', '这是我们的岛！', 28153),
(158754, 'zhCN', '你们跑这座岛上来干什么？', '你们跑这座岛上来干什么？', 28153),
(158753, 'zhCN', '我们被攻击了，伙计们！快过来！', '我们被攻击了，伙计们！快过来！', 28153),
(158752, 'zhCN', '快点把他们切好！', '快点把他们切好！', 28153),
(158751, 'zhCN', '看我把你吃掉！', '看我把你吃掉！', 28153),
(158750, 'zhCN', '我们要把你活剥了！', '我们要把你活剥了！', 28153),
(158749, 'zhCN', '我要用你的骨头做成项链！', '我要用你的骨头做成项链！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158748, 'zhCN', '我要把你开肠破肚，然后喝你的血！', '我要把你开肠破肚，然后喝你的血！', 28153),
(158747, 'zhCN', '哇啊啊！我带着荣耀战死！', '', 28153),
(158746, 'zhCN', '你们……才是侵略者……我们什么也没……', '', 28153),
(158745, 'zhCN', '宝石……救不了我们……', '', 28153),
(158744, 'zhCN', '我们还会回来……带着更多人回来……', '', 28153),
(158743, 'zhCN', '群星……欺骗了……', '', 28153),
(158742, 'zhCN', '我听见了……先祖的召唤……', '', 28153),
(158741, 'zhCN', '灵魂在欢迎我……', '', 28153),
(158740, 'zhCN', '我会回归……先祖的身旁……', '', 28153),
(158739, 'zhCN', '群星会指引我的双拳，未来会用你的鲜血来书写！', '', 28153),
(158738, 'zhCN', '狂风已经向我预言，今日你会倒在这里。', '', 28153),
(158737, 'zhCN', '愿灵魂赐予我不息烈焰的力量！', '', 28153),
(158736, 'zhCN', '你挑起了自己赢不了的战斗，懦夫！', '', 28153),
(158735, 'zhCN', '这座岛屿的富产属于我们，白痴。', '', 28153),
(158734, 'zhCN', '先祖赐予了我力量和智慧！', '', 28153),
(158733, 'zhCN', '我要把你的血涂在我的角上，蠢货！', '', 28153),
(158732, 'zhCN', '我会保护我的部族，外来者！', '', 28153),
(158731, 'zhCN', '战士们，协助我！', '', 28153),
(158730, 'zhCN', '集结起来，我们正遭受攻击！', '', 28153),
(158729, 'zhCN', '这是我们的岛屿，这里的一切都不属于你们！', '', 28153),
(158728, 'zhCN', '这些发光的宝石是我们的，你们毫无机会！', '', 28153),
(158727, 'zhCN', '你们休想夺走我们的地盘，外来者！', '', 28153),
(158726, 'zhCN', '入侵者！击退他们！', '', 28153),
(158725, 'zhCN', '愿灵魂指引我的武器！', '', 28153),
(158724, 'zhCN', '为了先祖！', '', 28153),
(158723, 'zhCN', '那可……真疼……', '', 28153),
(158722, 'zhCN', '你为什么……来这儿……？', '', 28153),
(158721, 'zhCN', '啊！打到肚子了……', '', 28153),
(158720, 'zhCN', '你……小偷……', '', 28153),
(158719, 'zhCN', '不！我的宝石……', '', 28153),
(158718, 'zhCN', '你……为什么要那么做？', '', 28153),
(158717, 'zhCN', '哦……这可不好……', '', 28153),
(158716, 'zhCN', '这么早就天黑了？', '', 28153),
(158715, 'zhCN', '', '有些人认为，交易只是个交易而已。全是些空洞的承诺和惺惺作态罢了。今天这一切的回报换来的是不可知的未来。\n\n然而，记住这一点：邦桑迪有债必讨。终有一日，从无例外。', 28153),
(158714, 'zhCN', '食人魔们，打砸时间到了！', '', 28153),
(158713, 'zhCN', '不！我的宝石！不是你们的！我要宝石！', '', 28153),
(158712, 'zhCN', '宝石使我们强大，入侵者。比你强大！', '', 28153),
(158711, 'zhCN', '等我们打完了，我要割下你的脑袋做战利品！', '', 28153),
(158710, 'zhCN', '干掉他们！敲碎他们的骨头！', '', 28153),
(158709, 'zhCN', '这是我的海岛，小东西。我的！', '', 28153),
(158708, 'zhCN', '我会砸烂你，喝你的血！', '', 28153),
(158707, 'zhCN', '我要把你砸成碎块！啊啊！', '', 28153),
(158706, 'zhCN', '这是我的宝石！哇啊啊啊！', '', 28153),
(158705, 'zhCN', '不要抢我们的东西！', '', 28153),
(158704, 'zhCN', '干掉他们！', '', 28153),
(158703, 'zhCN', '你不能拿走宝石！', '', 28153),
(158702, 'zhCN', '这是我的海岛！你快滚！', '', 28153),
(158701, 'zhCN', '杀死入侵者！', '', 28153),
(158700, 'zhCN', '我砸，我碾，我杀！', '', 28153),
(158699, 'zhCN', '我要碾碎你！', '', 28153),
(158698, 'zhCN', '也许这次我只要承诺自己会成为一个更好的人……而不是像上次那样！', '也许这次我只要承诺自己会成为一个更好的人……而不是像上次那样！', 28153),
(158697, 'zhCN', '你觉得邦桑迪想从我这里得到什么？', '你觉得邦桑迪想从我这里得到什么？', 28153),
(158696, 'zhCN', '我要怎么办……怎么办……肯定有办法摆脱这个困境！', '我要怎么办……怎么办……肯定有办法摆脱这个困境！', 28153),
(158695, 'zhCN', '只要我和邦桑迪达成交易，一切就会回归正常了，对吗？', '只要我和邦桑迪达成交易，一切就会回归正常了，对吗？', 28153),
(158694, 'zhCN', '我恨这样！我恨这一切！', '我恨这样！我恨这一切！', 28153),
(158693, 'zhCN', '我无法接受！他们不知道我是谁吗？', '我无法接受！他们不知道我是谁吗？', 28153),
(158692, 'zhCN', '我一定要找出到底是谁对我做出这种事的！否则死不瞑目！', '我一定要找出到底是谁对我做出这种事的！否则死不瞑目！', 28153),
(158691, 'zhCN', '为什么会这样？这不公平！', '为什么会这样？这不公平！', 28153),
(158690, 'zhCN', '不会有好转了，你也没法说服我。', '不会有好转了，你也没法说服我。', 28153),
(158689, 'zhCN', '这对我来说很好了，看看我吧……现在我什么也不是。', '这对我来说很好了，看看我吧……现在我什么也不是。', 28153),
(158688, 'zhCN', '我再也无法感受阳光了。', '我再也无法感受阳光了。', 28153),
(158687, 'zhCN', '要是我还能多活几天……我本可以做那么多事。', '要是我还能多活几天……我本可以做那么多事。', 28153),
(158686, 'zhCN', '死？不，我只是稍微休息一下。', '死？不，我只是稍微休息一下。', 28153),
(158685, 'zhCN', '你是谁？算了，这不重要……', '你是谁？算了，这不重要……', 28153),
(158684, 'zhCN', '如果我没看到，那就没有发生。就那么简单。', '如果我没看到，那就没有发生。就那么简单。', 28153),
(158683, 'zhCN', '继续吧……继续前行吧……最终会证明是对的……', '继续吧……继续前行吧……最终会证明是对的……', 28153),
(158682, 'zhCN', '你怎么敢踏足我的领地。到此为止了！', '', 28153),
(158681, 'zhCN', '你太弱了。来真刀真枪地面对我！', '', 28153),
(158680, 'zhCN', '你觉得你那可悲的机器能对抗得了我！？', '', 28153),
(158679, 'zhCN', '哇哈，新的挑战者出现了！看招！', '', 28153),
(158678, 'zhCN', '但是……我不该就这么死去……', '', 28153),
(158677, 'zhCN', '', '我要……把你开膛剖肚……', 28153),
(158676, 'zhCN', '', '我要把你剁成碎块！', 28153),
(158675, 'zhCN', '把我葬入大海……', '', 28153),
(158674, 'zhCN', '我要对你施以水刑！', '', 28153),
(158673, 'zhCN', '啊，这家伙，都不知道从何说起，是滥用美发产品呢，还是他蹩脚的打油诗。可别小瞧他，里德既懂撩妹，也很能打。', '', 28153),
(158672, 'zhCN', '在贝克特眼中，他自己算得上是传奇人物。', '', 28153),
(158671, 'zhCN', '卢娜有些……算是比较“刺头”吧。', '', 28153),
(158670, 'zhCN', '呃……无法避免的事情。只有纳税和……', '', 28153),
(158669, 'zhCN', '瞧瞧这是什么？看起来我们有账要算了！', '', 28153),
(158668, 'zhCN', '', '希望我们还不算太迟，$n。快，全速前进。去找到我的女儿。', 28153),
(158666, 'zhCN', '', '命途之末是临近斯托颂海岸的一座小岛。是用来流放最凶恶的罪犯的，至今无人归还。', 28153),
(158665, 'zhCN', '', '$n！你找到了什么？', 28153),
(158661, 'zhCN', '我要离开这儿！感谢你的帮助，$p！', '', 28153),
(158660, 'zhCN', '库亚冯发出一声尖锐的鸣叫，兴奋地甩着自己的尾巴。', '', 28153),
(158659, 'zhCN', '库亚冯将头骨放回了你的手中。', '', 28153),
(158658, 'zhCN', '库亚冯将头骨丢到了地上，对着你调皮地尖叫了起来。', '', 28153),
(158657, 'zhCN', '', '我们输了。泰达希尔即将沦陷。', 28153),
(158656, 'zhCN', '潮汐会把你们统统吞噬！', '', 28153),
(158655, 'zhCN', '来吧，勇士。我们必须追随大酋长走向……胜利。', '', 28153),
(158654, 'zhCN', '', '成功了。所有人，上！', 28153),
(158653, 'zhCN', '我也给你一个选择。带他去达纳苏斯，然后在我们征服那里的时候双双被杀……或是逃得远远的，这样你们就能活下来。', '', 28153),
(158652, 'zhCN', '', '因为你放过了玛法里奥，我可以给你一个选择。', 28153),
(158651, 'zhCN', '', '准备好。', 28153),
(158650, 'zhCN', '不是无缘无故。这是为了部落能够长存。', '', 28153),
(158649, 'zhCN', '', '这场战争全都没有荣誉可言。你们怎么敢无缘无故地杀死这么多无辜者！', 28153),
(158648, 'zhCN', '我那一击毫无荣誉可言。我不配杀他。', '', 28153),
(158647, 'zhCN', '', '你没有杀他，兽人。为什么？', 28153),
(158646, 'zhCN', '', '玛法里奥！不！', 28153),
(158645, 'zhCN', '你带领着……你的部落……效忠了……死亡。你迟早……会后悔的……', '', 28153),
(158642, 'zhCN', '', '治疗你的伤口，休息一下吧。你在这里安全了。', 28153),
(158641, 'zhCN', '我死于惹到了不该惹的野兽。你知道是哪个。', '我死于惹到了不该惹的野兽。你知道是哪个。', 28153),
(158640, 'zhCN', '我和你一样困惑，头儿。', '我和你一样困惑，头儿。', 28153),
(158639, 'zhCN', '我受不了霍利辣椒的辣味。', '我受不了霍利辣椒的辣味。', 28153),
(158638, 'zhCN', '我在奔向托卡纳塔的路上死去了。但如果让我再来一次，我还会这样做！', '我在奔向托卡纳塔的路上死去了。但如果让我再来一次，我还会这样做！', 28153),
(158637, 'zhCN', '你是不打算管你的身体了，是吗？', '你是不打算管你的身体了，是吗？', 28153),
(158636, 'zhCN', '我在佐卡罗广场散步的时候被闪电给劈中了。', '我在佐卡罗广场散步的时候被闪电给劈中了。', 28153),
(158635, 'zhCN', '我死于从金字塔上掉下来，我都不记得自己是怎么到这儿来的。', '我死于从金字塔上掉下来，我都不记得自己是怎么到这儿来的。', 28153),
(158634, 'zhCN', '都打扮好了，却无处可去。', '都打扮好了，却无处可去。', 28153),
(158633, 'zhCN', '计算在伯拉勒斯放置传送门的正确位置可不是轻松的活，但我很欢迎这类挑战！记得向我汇报情况，好吗？', '', 28153),
(158632, 'zhCN', '如你所愿，纳萨诺斯。', '', 28153),
(158631, 'zhCN', '泽林，陪$n去伯拉勒斯。欧库勒斯开着传送门正等着呢。', '', 28153),
(158630, 'zhCN', '嗨，英雄，我们最好谈谈。', '', 28153),
(158629, 'zhCN', '这是特等席……等我起来就让你。', '', 28153),
(158628, 'zhCN', '', '$p？啐，压根就没听说过你。', 28153),
(158627, 'zhCN', '等你准备好前往舰队时，霍巴特会在外面助你一臂之力。', '', 28153),
(158626, 'zhCN', '别说我们没警告过你。', '别说我们没警告过你。', 28153),
(158625, 'zhCN', '退后！这是为了你好。', '退后！这是为了你好。', 28153),
(158624, 'zhCN', '库亚冯害怕得瑟瑟发抖。', '', 28153),
(158623, 'zhCN', '海潮已经转向对我们有利的方向了，你觉得呢，$n？', '', 28153),
(158622, 'zhCN', '我已经看见即将来临的伟大时刻，对于你我都是如此。', '', 28153),
(158621, 'zhCN', '你不能把我就丢在这里，我这身骨头已经老得不能在矿井里干了。', '你不能把我就丢在这里，我这身骨头已经老得不能在矿井里干了。', 28153),
(158620, 'zhCN', '我能看出我们在发酵阶段的哪一步出了问题。', '', 28153),
(158619, 'zhCN', '所以，引入不可见的污染物也许会影响最初的还原过程。', '', 28153),
(158618, 'zhCN', '没问题。', '', 28153),
(158617, 'zhCN', '什么忙我都能帮。', '', 28153),
(158616, 'zhCN', '我回去干活了。', '', 28153),
(158615, 'zhCN', '当然，我能帮你一把。', '', 28153),
(158614, 'zhCN', '也许我能助你一臂之力。', '', 28153),
(158612, 'zhCN', '', '抬头看看四周。这些树长着眼睛，勇士。弄瞎它们。', 28153),
(158611, 'zhCN', '我们首先得专注于稳定关键化合物。', '', 28153),
(158610, 'zhCN', '喔！这很能说明问题！“炼金术第一定律：要想获得有益物质，必须提供可等价交换的替代物质。', '', 28153),
(158609, 'zhCN', '我们动手吧！', '我们动手吧！', 28153),
(158608, 'zhCN', '有意思……准确运用加热非常关键。', '', 28153),
(158607, 'zhCN', '啊！我想我明白催化剂在哪个步骤失效了。', '', 28153),
(158606, 'zhCN', '奇怪……我们是不可能料到这个的。', '', 28153),
(158605, 'zhCN', '嗯……这下有意思了。', '', 28153),
(158604, 'zhCN', '我们的一些伙伴被俘虏了。你愿意帮帮他们吗？', '', 28153),
(158603, 'zhCN', '嘿！有人卷走了我们一批货物！我们得赶紧把东西抢回来。最好再收点利息。', '', 28153),
(158602, 'zhCN', '天啊，到处都是受伤的士兵。我们得帮帮那些伤员！', '', 28153),
(158601, 'zhCN', '附近有没有优秀的盗贼？这里有一项任务！', '', 28153),
(158600, 'zhCN', '听着，如果你找到了战车的零部件，就来告诉我。等它被修好之后你可以开了。', '', 28153),
(158599, 'zhCN', '我发现有东西需要经典的科赞式践踏。', '', 28153),
(158598, 'zhCN', '哇，看看那东西的体型。嘿！有人想去宰了它吗？', '', 28153),
(158597, 'zhCN', '我们的一些盟军被俘虏了。想不想开展一次救援行动？', '', 28153),
(158596, 'zhCN', '敌军带着一批重要的补给品潜逃了。不如我们用联盟的正义回敬一下这些窃贼？', '', 28153),
(158595, 'zhCN', '战场上有受伤的士兵。现在还有医师吗？', '', 28153),
(158594, 'zhCN', '是的，孩子。艾露恩与他们同在。她赐予了德鲁伊一种力量，让他们能够召唤强风来扬帆起航。', '', 28153),
(158593, 'zhCN', '', '迷雾之海善待了他们，对吗？', 28153),
(158592, 'zhCN', '送我回港口。', '送我回港口。', 28153),
(158591, 'zhCN', '送我去小型舰。', '送我去小型舰。', 28153),
(158590, 'zhCN', '为一场需要胆量的秘密行动找一些志愿者；这些人需要具备一定的隐匿水平和欺诈手段。', '', 28153),
(158589, 'zhCN', '我们正在尝试着利用敌人的一台战争机器。把你能找到的零部件通通带回来。', '', 28153),
(158588, 'zhCN', '啊。目标自己现身了。', '', 28153),
(158587, 'zhCN', '一些怀有敌意的大型野生动物正在战场上游荡。开始狩猎吧！', '', 28153),
(158586, 'zhCN', '你想跟我的小朋友打个招呼吗？', '', 28153),
(158585, 'zhCN', '你可真够烦人的，伙计。', '', 28153),
(158584, 'zhCN', '嘿。冷静点。', '', 28153),
(158583, 'zhCN', '活着回来，好吗？', '', 28153),
(158582, 'zhCN', '万事留意。', '', 28153),
(158581, 'zhCN', '万事小心。', '', 28153),
(158580, 'zhCN', '有新消息？', '', 28153),
(158579, 'zhCN', '怎么了？', '', 28153),
(158578, 'zhCN', '你气色不错。', '', 28153),
(158577, 'zhCN', '圣光在上，我得再喝一杯。', '', 28153),
(158576, 'zhCN', '哪怕给我军官的工资也不值得我受这份气。', '', 28153),
(158575, 'zhCN', '行了，行了……', '', 28153),
(158574, 'zhCN', '嗯快走吧。', '', 28153),
(158573, 'zhCN', '解散。', '', 28153),
(158572, 'zhCN', '盯紧你的敌人。', '', 28153),
(158571, 'zhCN', '嗯？', '', 28153),
(158570, 'zhCN', '我全心聆听你的话语。', '', 28153),
(158569, 'zhCN', '荣耀属于联盟。', '', 28153),
(158568, 'zhCN', '', '不……这不可能。', 28153),
(158565, 'zhCN', '', '我会用你检验我力量的极限！', 28153),
(158564, 'zhCN', '', '有人说我的魔法很残忍，但我不过是想探索可行事物的界线罢了。', 28153),
(158563, 'zhCN', '扎根', '扎根', 28153),
(158562, 'zhCN', '米亚……米亚！快醒醒，我的王后……我的爱人！', '', 28153),
(158561, 'zhCN', '愿女神能护佑你们。', '', 28153),
(158560, 'zhCN', '女妖杀了我儿子，偷走了我的王国。她不能再夺走我的挚爱！', '', 28153),
(158559, 'zhCN', '', '他们……不会走的……', 28153),
(158558, 'zhCN', '阿斯塔利，你已经尽力了！叫那些牧师跟我们一起走！', '', 28153),
(158557, 'zhCN', '不！两个我都要救！', '', 28153),
(158555, 'zhCN', '', '树……他们在烧树！去救……那个孩子。别管……我。', 28153),
(158554, 'zhCN', '不能再待在这儿了！我们得穿过传送门逃走！', '', 28153),
(158553, 'zhCN', '', '阿斯塔利，别浪费时间了。我们要在城市燃烧殆尽之前完成疏散！', 28153),
(158551, 'zhCN', '', '杀了他，了结这件事。如果你愿意，可以等会再要他的脑袋。去世界之树那里见我。', 28153),
(158550, 'zhCN', '', '我的胜利是必然的。他不过是在浪费时间。', 28153),
(158549, 'zhCN', '我不应该插手。', '', 28153),
(158548, 'zhCN', '', '不要后悔。你做得很好。', 28153),
(158547, 'zhCN', '这一击很不光彩。我……很后悔。', '', 28153),
(158546, 'zhCN', '啊！萨鲁……法尔？！', '', 28153),
(158545, 'zhCN', '大酋长在独自面对怒风！我必须……', '', 28153),
(158544, 'zhCN', '北边？难道……他们翻越了费伍德森林的山脉。我竟然没料到！', '', 28153),
(158543, 'zhCN', '勇士，戴勒琳——在奥伯丁拦截他们。我来负责北边。', '', 28153),
(158542, 'zhCN', '部落突破进来也只是时间问题了。他们要从两侧夹击我们。', '', 28153),
(158541, 'zhCN', '小精灵……正变得愈发混乱！墙要倒塌了！', '', 28153),
(158540, 'zhCN', '', '这声音……难道……？大导师！部落从北边攻过来了！', 28153),
(158539, 'zhCN', '', '时机已到。世界之树已是我们的囊中之物！找到萨鲁法尔。我们该彻底结束这场战争了。', 28153),
(158537, 'zhCN', '', '看看周围吧，英雄！多么美妙的景象啊。小精灵在四处逃散。墙在一点点地倒塌。', 28153),
(158536, 'zhCN', '', '萨鲁法尔！是时候了。', 28153),
(158535, 'zhCN', '为了部落！', '', 28153),
(158534, 'zhCN', '', '你要飞往哪里，小小鸟？', 28153),
(158533, 'zhCN', '', '嗷嗷！我的眼睛好疼！', 28153),
(158532, 'zhCN', '女巫，退散！', '', 28153),
(158531, 'zhCN', '', '谁能想到你居然会前来保护你珍贵的树木呢？', 28153),
(158530, 'zhCN', '', '玛法里奥，你能加入我们真是太好了……', 28153),
(158529, 'zhCN', '希尔瓦娜斯！你的肮脏行径亵渎了这片神圣的土地！Andu-falah-dor！', '', 28153),
(158528, 'zhCN', '', '我们不能让他们享受哪怕是一晚的平静。这就是战争。', 28153),
(158527, 'zhCN', '', '同时，我们要尽我们所能，继续给卡多雷施加压力。', 28153),
(158526, 'zhCN', '', '在我们等待萨鲁法尔的消息时，我会继续带领我们的士兵穿墙而过。', 28153),
(158525, 'zhCN', '', '现在我们必须坚持到底。', 28153),
(158524, 'zhCN', '', '急弯河陷入了僵局，玛法里奥知道这一点。', 28153),
(158523, 'zhCN', '', '部落的勇士们，急弯河需要你们的援助！这是我们获胜的好机会！', 28153),
(158522, 'zhCN', '', '……我要去狩猎乌鸦了。', 28153),
(158521, 'zhCN', '', '迅速完成这里的工作。把所有你能收集到的艾泽里特都交给我们的工程师。', 28153),
(158520, 'zhCN', '', '那艘船一定来自达纳苏斯……也就是说……', 28153),
(158519, 'zhCN', '', '小心点，勇士。看来联盟在这方面要比我们领先。', 28153),
(158518, 'zhCN', '', '艾泽里特……有它在手，就没人敢反对部落。', 28153),
(158517, 'zhCN', '', '工兵！拿上装备跟我走！带上我们所有的伐木机。', 28153),
(158516, 'zhCN', '', '终结它们，不然我们人民的血将洒满这片树林。', 28153),
(158515, 'zhCN', '', '我知道这让你很不好受，德鲁伊。这些古树违抗了你，违抗了他们神圣的职责。', 28153),
(158514, 'zhCN', '泰莉亚！我们搭个顺风车！', '', 28153),
(158513, 'zhCN', '我是指“飞跃悬崖，逃出生天”。来吧！', '', 28153),
(158512, 'zhCN', '然后华丽地撤退！', '', 28153),
(158511, 'zhCN', '我们只需要拿上箱子……', '', 28153),
(158510, 'zhCN', '我从没想过太阳会如此灼烧我们残余的皮肤。', '我从没想过太阳会如此灼烧我们残余的皮肤。', 28153),
(158509, 'zhCN', '我向你保证，我的计划天衣无缝。', '', 28153),
(158508, 'zhCN', '我猜你已经想好带着那东西离开这里的计划了吧？', '我猜你已经想好带着那东西离开这里的计划了吧？', 28153),
(158507, 'zhCN', '哈兰加强了安全措施，他给自己的保险箱加了一把锁。钥匙可能就在他身上。\n\n<弗林揉了揉下巴。>\n\n没错，现在除了偷走箱子……也没其他办法了。', '', 28153),
(158506, 'zhCN', '真不赖啊，哈兰，真有你的。', '', 28153),
(158505, 'zhCN', '我在考虑让我找到的每个学员都绕军校跑上一百圈。', '', 28153),
(158504, 'zhCN', '他们肯定就在这附近。', '', 28153),
(158503, 'zhCN', '我们从未想要复活……或是忍受这一切。', '我们从未想要复活……或是忍受这一切。', 28153),
(158502, 'zhCN', '四把锁？四把！？', '', 28153),
(158501, 'zhCN', '联盟竟敢把我们当作怪物？', '联盟竟敢把我们当作怪物？', 28153),
(158500, 'zhCN', '那些学员哪儿去了……', '', 28153),
(158499, 'zhCN', '啊，这就是了……哈兰·斯威提的保险箱。', '', 28153),
(158498, 'zhCN', '发生了这一切，她是挺惨的。但她现在也许该把库尔提拉斯让给更有能力的人去领导。', '发生了这一切，她是挺惨的。但她现在也许该把库尔提拉斯让给更有能力的人去领导。', 28153),
(158497, 'zhCN', '似乎随着时间推移，越来越能看出凯瑟琳只不过是继承了亡夫的名号罢了。', '似乎随着时间推移，越来越能看出凯瑟琳只不过是继承了亡夫的名号罢了。', 28153),
(158496, 'zhCN', '又一个星期过去了，几大家族也未曾会面过一次。', '又一个星期过去了，几大家族也未曾会面过一次。', 28153),
(158495, 'zhCN', '别说了，任何有教养的提拉加德贵族都该明白，不要哪壶不开提哪壶。', '别说了，任何有教养的提拉加德贵族都该明白，不要哪壶不开提哪壶。', 28153),
(158494, 'zhCN', '光天化日之下遭到谋害，还就在婚礼当天。真是个业余的计划。', '光天化日之下遭到谋害，还就在婚礼当天。真是个业余的计划。', 28153),
(158493, 'zhCN', '有关她未婚夫的事？当然听说了，真是可惜。', '有关她未婚夫的事？当然听说了，真是可惜。', 28153),
(158492, 'zhCN', '有没有听说维克雷斯女儿的事？', '有没有听说维克雷斯女儿的事？', 28153),
(158491, 'zhCN', '真丢人，什么样的斯托颂族人才会无力号令大海呢？假如我是那个家族的人，早就跟那小子断绝关系了。', '真丢人，什么样的斯托颂族人才会无力号令大海呢？假如我是那个家族的人，早就跟那小子断绝关系了。', 28153),
(158490, 'zhCN', '所以他叔叔把他送来给我们操心？', '所以他叔叔把他送来给我们操心？', 28153),
(158489, 'zhCN', '我听说布兰农回来这里做事了。', '我听说布兰农回来这里做事了。', 28153),
(158488, 'zhCN', '看到吉安娜长得随她母亲我就安心了，我觉得戴林长得可不怎么好看。', '看到吉安娜长得随她母亲我就安心了，我觉得戴林长得可不怎么好看。', 28153),
(158487, 'zhCN', '', '<一把匕首还插在她的背上，但她的所有财物都被抢走了。>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158486, 'zhCN', '', '<这个赞达拉巨魔似乎没死多久。>', 28153),
(158485, 'zhCN', '<检查尸体。>', '<检查尸体。>', 28153),
(158484, 'zhCN', '维克雷斯家族的人有段时间没来伯拉勒斯了。我猜梅瑞狄斯终于意识到自己在这有多不受欢迎了。', '维克雷斯家族的人有段时间没来伯拉勒斯了。我猜梅瑞狄斯终于意识到自己在这有多不受欢迎了。', 28153),
(158483, 'zhCN', '你有没有注意到斯托颂勋爵上次来这儿时的打扮？要我说的话，长触手的帽子有点过时了。', '你有没有注意到斯托颂勋爵上次来这儿时的打扮？要我说的话，长触手的帽子有点过时了。', 28153),
(158482, 'zhCN', '<西蒙瞥了昆加一眼。>\n\n呃，是的……哈！哈！你可真会开玩笑，朋友！\n\n哈！哈！太好笑了！\n\n现在你该走了，以后再来买吧。哈！哈！\n\n在我……补货时去观看战斗吧。', '', 28153),
(158481, 'zhCN', '我在帐篷后面发现了一具尸体。', '我在帐篷后面发现了一具尸体。', 28153),
(158480, 'zhCN', '你好，呃，是的。\n\n欢迎光临小店，西蒙…出售…东西…的店。\n\n我这里出售……\n\n<西蒙向他身后扫了一眼。>\n\n武器，各类武器，可是现在都没货。\n\n也许你可以等我……补货之后再来。', '', 28153),
(158479, 'zhCN', '我会干掉你们的，部落渣滓！', '', 28153),
(158478, 'zhCN', '联盟无权侵占我们的土地！', '联盟无权侵占我们的土地！', 28153),
(158477, 'zhCN', '最难吃的就是旅行面包了。', '', 28153),
(158476, 'zhCN', '我们所有的资源都用来为我们人民的撤离争取时间，并且抵挡部落的进攻。你去找找可以给们哨兵吃的食物吧。', '', 28153),
(158475, 'zhCN', '', '我要把你们送去深海！', 28153),
(158474, 'zhCN', '我口袋里装的可不是魔精。', '', 28153),
(158473, 'zhCN', '啊，我要让你尝尝自己种下的苦果！', '', 28153),
(158472, 'zhCN', '别逼我把你变成一只蟾蜍！', '', 28153),
(158471, 'zhCN', '你最好住手。我是年纪大了，但我这么多年可学会了不少厉害的妖术。', '', 28153),
(158470, 'zhCN', '放松点，伙计。你不需要这样到处乱摸吧。', '', 28153),
(158469, 'zhCN', '我训练过好几代暗矛巨魔。', '', 28153),
(158468, 'zhCN', '祝你好运，记得随身携带一瓶上好的魔精。', '', 28153),
(158467, 'zhCN', '', '最难吃的就是旅行干粮了。', 28153),
(158466, 'zhCN', '', '“三军未动，粮草先行”，我听说过类似的话。这片森林里肯定有值得一吃的东西。', 28153),
(158465, 'zhCN', '要记住，不是所有伤痕都能恢复。', '', 28153),
(158464, 'zhCN', '小心！', '', 28153),
(158463, 'zhCN', '我马上就要得到我需要的样本了！再等等……', '', 28153),
(158462, 'zhCN', '嗯，这些叶子比我想象的要顽固……但是我就快成功了。', '', 28153),
(158461, 'zhCN', '这需要点时间。摘除这些叶子可是个精细活。', '', 28153),
(158460, 'zhCN', '我这把老骨头可受不了这个。', '', 28153),
(158459, 'zhCN', '万灵与你同在。', '', 28153),
(158458, 'zhCN', 'Eekum bokum。', '', 28153),
(158457, 'zhCN', '有人需要医生吗？', '', 28153),
(158456, 'zhCN', '你需要我的帮助吗？', '', 28153),
(158455, 'zhCN', '你好，伙计。', '', 28153),
(158454, 'zhCN', '我希望得到灵魂的指引。', '我希望得到灵魂的指引。', 28153),
(158453, 'zhCN', '灵魂，它们能够指引你通过这里。', '', 28153),
(158452, 'zhCN', 'Una\'fe，$n。整座营地听候你的调遣。', '', 28153),
(158451, 'zhCN', '', '你暂时解除了他们的武装。在我们切断他们的供货之前，都必须保持警惕。', 28153),
(158450, 'zhCN', '', '饱餐一顿，休息一会儿！', 28153),
(158449, 'zhCN', '密室的封印保护着世界之魂，要是艾泽里特继续这样喷发下去，封印很快就会破碎了！', '', 28153),
(158448, 'zhCN', '如果用你的项链来吸收艾泽里特，它的能量应该可以修复密室的封印！', '', 28153),
(158447, 'zhCN', '', '有传言说那些帮派手上有一些肮脏的艾泽里特炸药。在那些炸药被找回之前，伯拉勒斯都会处于危险之中！', 28153),
(158446, 'zhCN', '我的船沉了，有几百号人落水。不到一小时，鲨鱼就出现了。小鲨鱼，大鲨鱼，怒气冲冲的鲨鱼。我们竭尽全力对抗它们，但当你直视鲨鱼的眼睛，看见那对毫无生气的黑眼珠时，就会觉得要不是它们会游上来咬你，简直就不像活物。接着海水就被染红了，周围变得漆黑一片，有人瞬间就被撕成碎片。第一个夜晚过去时，可能就损失了一半的人。搞不好那里有上千条鲨鱼。最后救援来了，可能已经是五天之后了，完全于事无补。三百一十六个人落到海里，只有七个人活了下来，剩下的全被鲨鱼吃了。\n\n不说了，想不想跟鲨鱼干一场？', '', 28153),
(158445, 'zhCN', '谢谢，我打算冒这个险。把那双靴子借给我吧。', '谢谢，我打算冒这个险。把那双靴子借给我吧。', 28153),
(158444, 'zhCN', '', '哎哟！我只是想移走那些……呃……从货车后面摔下来的箱子。\n\n至少可达没事，没有东西能伤到我的棒小伙！\n\n我有一双备用靴子，如果你得跳回北边去的话。丑话说在前头……我还没测试过这双靴子呢。', 28153),
(158443, 'zhCN', '', '我们来晚了。', 28153),
(158442, 'zhCN', '', '你去看看这些人需要什么帮助。我先到前面看看！', 28153),
(158441, 'zhCN', '', '首先我们必须守住大门！', 28153),
(158440, 'zhCN', '', '噢不……', 28153),
(158439, 'zhCN', '', '我们知道。你先歇会吧，他迟早会受到惩罚的。', 28153),
(158438, 'zhCN', '哈兰……那个混蛋把自己出卖给了艾什凡……他……呃啊！', '', 28153),
(158437, 'zhCN', '呃……全身都疼……<咳>', '', 28153),
(158436, 'zhCN', '', '弗林！冷静点，是我！你还好吗？哪儿疼？', 28153),
(158435, 'zhCN', '呃……啊……哇啊啊啊！', '', 28153),
(158434, 'zhCN', '', '非常好。来吧，母亲，我们回家了。', 28153),
(158433, 'zhCN', '', '抓紧了！', 28153),
(158432, 'zhCN', '我做好出发的准备了。', '我做好出发的准备了。', 28153),
(158431, 'zhCN', '', '等你准备好了，我就可以把我们从这里传送出去，$c。\n\n请快点，我想离开这地方。', 28153),
(158430, 'zhCN', '过场动画！', '过场动画！', 28153),
(158429, 'zhCN', '暗夜精灵是不错的邻居。不过……那些小精灵还是需要点时间来习惯。', '', 28153),
(158428, 'zhCN', '辛勤耕作，乐享收获。那就是我们过去的生活。', '', 28153),
(158427, 'zhCN', '他们那棵树的遭遇真是令人遗憾。', '', 28153),
(158426, 'zhCN', '你们以为能阻止我们取回德里克的尸体？那就等着吃苦头吧！', '', 28153),
(158425, 'zhCN', '这一次，洛只需要能抵达目标地点就行了。但要小心迷宫中潜藏着的危险。', '', 28153),
(158424, 'zhCN', '现在，你能引导洛找到宝藏，然后前往终点，其间还不去重复他走过的路吗？', '', 28153),
(158423, 'zhCN', '是不是很简单，$n？', '', 28153),
(158422, 'zhCN', '首先：引导洛前往终点。', '', 28153),
(158421, 'zhCN', '在讲故事的同时，我们要让年轻的始祖龟引导洛在一些小迷宫中完成不同的挑战。', '', 28153),
(158420, 'zhCN', '你准备好接受作战训练了吗？', '你准备好接受作战训练了吗？', 28153),
(158419, 'zhCN', '要想生活醇如酒，就得锅里添点蜜，$p！', '要想生活醇如酒，就得锅里添点蜜，$p！', 28153),
(158418, 'zhCN', '洛的初次胜利让他更加自信，所以他为了探索而找到了更多奇妙的区域。', '', 28153),
(158416, 'zhCN', '你能引导洛找到所有的宝藏，然后前往出口，其间还不去重复他走过的路吗？', '', 28153),
(158415, 'zhCN', '洛开始探索他遇到的远古废墟，通常还能发现奇珍异宝。', '', 28153),
(158414, 'zhCN', '“探索者洛”。随着洛渐渐长大，他对这个世界也愈发好奇。', '', 28153),
(158413, 'zhCN', '洛的勤勉得到了回报，大地为他提供了许多营养丰富的食物。', '', 28153),
(158412, 'zhCN', '一次就好，你能帮洛看一下花园里的所有植物吗？', '', 28153),
(158411, 'zhCN', '每天早上他都会去观察花园里的所有植物。', '', 28153),
(158410, 'zhCN', '', '显然德鲁斯特不想让他们的俘虏活下去。吉安娜有生命危险。', 28153),
(158409, 'zhCN', '“洛的丰收”。洛喜欢看着事物生长。', '', 28153),
(158408, 'zhCN', '洛几乎没能逃出生天；所以他决定要寻找一种不那么刺激的生活方式。', '', 28153),
(158407, 'zhCN', '你能帮助洛关掉所有发光的方格，解除这个陷阱吗？', '', 28153),
(158406, 'zhCN', '真是“好奇心害死龟。”洛的好奇心几乎要了他的命。他触发了一个赞达拉巨魔的古老陷阱！', '', 28153),
(158405, 'zhCN', '', '哭着求饶吧！', 28153),
(158404, 'zhCN', '大城市的生活并不适合洛。他决定回归简单的生活。', '', 28153),
(158403, 'zhCN', '但是他却不停地迷路。你能引导洛找到所有的商店，然后前往旅店，其间还不去重复他走过的路吗？', '', 28153),
(158402, 'zhCN', '“大城市的生活”。一次，洛去到了一个大城市，那里很像伯拉勒斯。', '', 28153),
(158401, 'zhCN', '洛继续过着安详而平静的生活……且吃喝不愁。', '', 28153),
(158399, 'zhCN', '', '我在这些神殿周围成功捕获了一些次级元素，它们相当迷人。介不介意见识一下它们的能力？', 28153),
(158398, 'zhCN', '客人跑光…$pr很强…', '', 28153),
(158397, 'zhCN', '还是很饿……', '', 28153),
(158396, 'zhCN', '灯怎么灭了？', '', 28153),
(158395, 'zhCN', '再见，加里维克斯……', '', 28153),
(158394, 'zhCN', '不准打架！', '', 28153),
(158393, 'zhCN', '第一天工作！祝你好运！', '', 28153),
(158392, 'zhCN', '禁止$pr参加！', '', 28153),
(158391, 'zhCN', '私人派对！', '', 28153),
(158390, 'zhCN', '第二烂的客人依然非你莫属……我今天受够了……', '第二烂的客人依然非你莫属……我今天受够了……', 28153),
(158389, 'zhCN', '一杯地精……加冰……', '一杯地精……加冰……', 28153),
(158388, 'zhCN', '卡亚可乐……最后机会……', '卡亚可乐……最后机会……', 28153),
(158387, 'zhCN', '你最好……多给点小费……', '你最好……多给点小费……', 28153),
