INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155166, 'zhCN', 'Booga mabugu！', '', 28153),
(155165, 'zhCN', 'Ah gah mah gahma！', '', 28153),
(155164, 'zhCN', '他的心脏衰竭了……除了结束他的痛苦之外，我没有什么可以为他做的。', '', 28153),
(155163, 'zhCN', '艾什凡正在悬赏你的人头！', '艾什凡正在悬赏你的人头！', 28153),
(155162, 'zhCN', '我要拿你的尸体去领赏！', '我要拿你的尸体去领赏！', 28153),
(155161, 'zhCN', '你无法战胜艾什凡！', '你无法战胜艾什凡！', 28153),
(155160, 'zhCN', '这座城市是我们的了!', '这座城市是我们的了!', 28153),
(155159, 'zhCN', '伯拉勒斯将会燃烧！', '伯拉勒斯将会燃烧！', 28153),
(155158, 'zhCN', '我会在其他更安全的地方和你碰头！', '我会在其他更安全的地方和你碰头！', 28153),
(155157, 'zhCN', '我需要一条前往德鲁斯瓦的渡船。', '我需要一条前往德鲁斯瓦的渡船。', 28153),
(155156, 'zhCN', '你……为什么来这里……？', '', 28153),
(155155, 'zhCN', '亮闪闪的宝石……是我的……', '', 28153),
(155154, 'zhCN', '我的蜡烛！', '', 28153),
(155153, 'zhCN', '哇哇哇！', '', 28153),
(155152, 'zhCN', '啊！', '', 28153),
(155151, 'zhCN', '蜡烛……熄灭了……', '', 28153),
(155150, 'zhCN', '啊啊啊啊啊啊啊啊啊！', '', 28153),
(155149, 'zhCN', '不！', '', 28153),
(155148, 'zhCN', '我要把你像蜡烛一样点燃！', '', 28153),
(155147, 'zhCN', '你的蜡烛现在是我的了！', '', 28153),
(155146, 'zhCN', '砸死你！抢走你的东西！', '', 28153),
(155145, 'zhCN', '我要在你的头上开个洞！', '', 28153),
(155144, 'zhCN', '别拿走我的宝石！', '', 28153),
(155143, 'zhCN', '我的领地！我是国王！', '', 28153),
(155142, 'zhCN', '亮闪闪的宝石……是我的……我的！', '', 28153),
(155141, 'zhCN', '我们找到的这里，不是你们！', '', 28153),
(155140, 'zhCN', '这是我的地盘!', '', 28153),
(155139, 'zhCN', '咬死他们！抢走他们的蜡烛！', '', 28153),
(155138, 'zhCN', '嘎! 入侵者！', '', 28153),
(155135, 'zhCN', '不要拿走蜡烛！\n', '', 28153),
(155134, 'zhCN', '毕须博须！', '', 28153),
(155133, 'zhCN', '亮闪闪的宝石是我们的！', '', 28153),
(155132, 'zhCN', '亮闪闪的宝石让蜡烛更明亮！', '', 28153),
(155131, 'zhCN', '祝你好运，陆地人。如果你信神的话，最好祈祷他们与你同在。', '祝你好运，陆地人。如果你信神的话，最好祈祷他们与你同在。', 28153),
(155130, 'zhCN', '到了，我最远只能带你到这里了。', '到了，我最远只能带你到这里了。', 28153),
(155129, 'zhCN', '上次我在那边下锚，差点被一匹狼啃掉了一条腿……', '上次我在那边下锚，差点被一匹狼啃掉了一条腿……', 28153),
(155128, 'zhCN', '我们会停在远一点的地方。最近屠夫港可不是什么友好的地方。', '我们会停在远一点的地方。最近屠夫港可不是什么友好的地方。', 28153),
(155127, 'zhCN', '不管你是去那边干嘛，我建议你速战速决。', '不管你是去那边干嘛，我建议你速战速决。', 28153),
(155126, 'zhCN', '库尔提拉斯人很迷信。虽然我不信这个，但我也觉得最近德鲁斯瓦会让我起一身鸡皮疙瘩。', '库尔提拉斯人很迷信。虽然我不信这个，但我也觉得最近德鲁斯瓦会让我起一身鸡皮疙瘩。', 28153),
(155125, 'zhCN', '但最近，这些矿洞好像都枯竭了，而屠夫们也不知所踪。', '但最近，这些矿洞好像都枯竭了，而屠夫们也不知所踪。', 28153),
(155124, 'zhCN', '不久以前，商人还经常来到这个渡口，从农夫和矿工手上收购货物。', '不久以前，商人还经常乘坐这艘船，从农夫和矿工手上收购货物。', 28153),
(155123, 'zhCN', '关于那边有很多可怕的谣言，大部分船夫都不愿意在那儿停船了。', '关于那边有很多可怕的谣言，大部分船夫都不愿意在那儿停船了。', 28153),
(155122, 'zhCN', '要去德鲁斯瓦是吗？算你走运，碰上我开船。', '要去德鲁斯瓦是吗？算你走运，碰上我开船。', 28153),
(155121, 'zhCN', '该死！啊啊啊！', '', 28153),
(155120, 'zhCN', '啊……', '', 28153),
(155119, 'zhCN', '杀了……你……', '', 28153),
(155118, 'zhCN', '噢！正中要害！', '', 28153),
(155117, 'zhCN', '啊！', '', 28153),
(155116, 'zhCN', '邪恶的……无毛怪……', '', 28153),
(155115, 'zhCN', '去死吧……混蛋……', '', 28153),
(155114, 'zhCN', '不，我的宝贝！', '', 28153),
(155113, 'zhCN', '赞达拉多样的动植物很值得研究与记录。', '赞达拉动植物的多样性需要研究与记录。', 28153),
(155112, 'zhCN', '这些混蛋是从哪里来的？', '', 28153),
(155111, 'zhCN', '我要让你受尽折磨！', '', 28153),
(155110, 'zhCN', '抓住他们，然后杀了他们！', '', 28153),
(155109, 'zhCN', '干得很好！我们马上就能继续制作强力药水了！', '', 28153),
(155108, 'zhCN', '抱歉伙计，我没空接新工作了。时间都排满了……等等，你愿意加钱？忘了我刚才说的吧，你需要什么帮助？', '抱歉伙计，我没空接新工作了。时间都排满了……等等，你愿意加钱？忘了我刚才说的吧，你需要什么帮助？', 28153),
(155107, 'zhCN', '我们的部队需要更多炼金补给！请在这片区域找点必需的材料。哦，对了，小心有熊出没。', '', 28153),
(155106, 'zhCN', '', '隼林镇正遭到女巫部队的袭击！清除她们邪恶魔法的痕迹，恢复城镇的秩序！', 28153),
(155105, 'zhCN', '', '女巫已经被赶走，隼林镇的人民再度获得了安全。我们感谢你。', 28153),
(155104, 'zhCN', '欢迎光临，这里所有的东西都是刚从当地人那里掠夺过来的。今天试试一些新玩意吧！', '欢迎光临，这里所有的东西都是刚从当地人那里掠夺过来的。今天试试一些新玩意吧！', 28153),
(155103, 'zhCN', '滚开，宝贝是我的！', '', 28153),
(155102, 'zhCN', '讨厌的无毛怪，这是我的领地！', '', 28153),
(155101, 'zhCN', '我要踩扁你们这些呆瓜！', '', 28153),
(155100, 'zhCN', '用扳手收拾他！', '杀了他们！', 28153),
(155099, 'zhCN', '这里要发生工伤事故了！', '安全生产放第二！', 28153),
(155098, 'zhCN', '我一眼就能认出失败者！', '给我扳手！我要修理这家伙！', 28153),
(155097, 'zhCN', '我们死在了……刀锋下……', '', 28153),
(155096, 'zhCN', '我们输了……但是你没有赢……', '', 28153),
(155095, 'zhCN', '孢子不会放过你……', '', 28153),
(155094, 'zhCN', '我们的存在……超越了死亡……', '', 28153),
(155093, 'zhCN', '我们放弃这个躯体……', '', 28153),
(155092, 'zhCN', '至少……我们死得……光荣……', '', 28153),
(155091, 'zhCN', '就这样，我们输了。', '', 28153),
(155090, 'zhCN', '我们会长出来……再次……战斗……', '', 28153),
(155089, 'zhCN', '为了孢子而战！', '', 28153),
(155088, 'zhCN', '我们有同一个意志！', '', 28153),
(155087, 'zhCN', '嘿！你破坏了这里的所有规矩！', '喂，你……你被解雇了！', 28153),
(155086, 'zhCN', '你怕了！我们赢了！', '', 28153),
(155085, 'zhCN', '尝尝我们的刀锋吧！', '', 28153),
(155084, 'zhCN', '意志保护着我们！', '', 28153),
(155083, 'zhCN', '这场战斗你必输无疑！', '', 28153),
(155082, 'zhCN', '你还需要多练一练！', '', 28153),
(155081, 'zhCN', '我们会把你从下往上切成肉泥！', '', 28153),
(155080, 'zhCN', '求求你，救救伯拉勒斯吧！', '求求你，救救伯拉勒斯吧！', 28153),
(155079, 'zhCN', '这些海盗把伯拉勒斯搞得四分五裂！', '这些海盗把伯拉勒斯搞得四分五裂！', 28153),
(155078, 'zhCN', '谢谢你！', '谢谢你！', 28153),
(155077, 'zhCN', '把无毛怪砸成碎片！', '', 28153),
(155076, 'zhCN', '我是这里的国王，无毛怪们！', '', 28153),
(155075, 'zhCN', '杀了他们！抢走他们的宝贝！', '', 28153),
(155074, 'zhCN', '会飞的无毛怪！', '', 28153),
(155073, 'zhCN', '杀死蠢蛋！', '', 28153),
(155072, 'zhCN', '闪亮的宝贝让我们强大！', '', 28153),
(155071, 'zhCN', '这是我们的岛屿！不是你们的！', '', 28153),
(155070, 'zhCN', '去死吧！', '', 28153),
(155069, 'zhCN', '不要拿走我的宝贝！', '', 28153),
(155068, 'zhCN', '不准蠢蛋肆意妄为！', '', 28153),
(155067, 'zhCN', '许多年前，我训练了扎拉赞恩和沃金，让他们精通各自的技艺。我从未想到他们的命运会撼动整个世界。', '', 28153),
(155066, 'zhCN', '我只是听命行事！', '我只是听命行事！', 28153),
(155065, 'zhCN', '看来我选错队了！', '看来我选错队了！', 28153),
(155064, 'zhCN', '', '嗯哼？我能为你做些什么？', 28153),
(155063, 'zhCN', '我会想念……那些啤酒的……', '我会想念……那些啤酒的……', 28153),
(155062, 'zhCN', '我就知道这不是什么好差事！', '我就知道这不是什么好差事！', 28153),
(155061, 'zhCN', '万灵啊……我将追随你们……', '英灵们……我将追随你们……', 28153),
(155060, 'zhCN', '我只是要休息……一会儿……', '我现在要休息……一小会儿……', 28153),
(155059, 'zhCN', '我要……告发你……', '', 28153),
(155058, 'zhCN', '下一次赢的会是我……', '', 28153),
(155057, 'zhCN', '哈哈！我赢了……呃，不对……', '', 28153),
(155056, 'zhCN', '不……我不会输……', '', 28153),
(155055, 'zhCN', '你是麻烦……我要修理你。', '', 28153),
(155054, 'zhCN', '我是热量专家。我聪明。我会放火！', '', 28153),
(155053, 'zhCN', '我来点火……送你一程！', '我来点火……送你一程！', 28153),
(155052, 'zhCN', '我不喜欢火……你快停火！', '我不喜欢火……你快停火！', 28153),
(155051, 'zhCN', '我应该把你煮熟了。', '也许我应该把你煮熟。', 28153),
(155050, 'zhCN', '你不该在这里瞎晃悠的。', '想清楚了，捣乱的后果很严重。', 28153),
(155049, 'zhCN', '别招惹我，不然就把你烧焦。', '别惹我发火，否则你会葬身火海。', 28153),
(155048, 'zhCN', '你马上就要被烤了。', '你很快就会被烤熟。', 28153),
(155047, 'zhCN', '哦，有人想来点温暖吗？', '有人想来点温暖吗？', 28153),
(155046, 'zhCN', '让它哪里来就回哪里去。', '', 28153),
(155045, 'zhCN', '那头野兽回来了！快，在它对城墙造成更大的损害前赶走它！', '', 28153),
(155044, 'zhCN', '什么？沃金……你不可能变得如此强大……除非你已经成为……', '', 28153),
(155043, 'zhCN', '你以为摧毁了我的身体……我就不能把你……撕成碎片了吗？', '', 28153),
(155042, 'zhCN', '你以为你能赢？你只不过是在延迟你的死期而已。', '', 28153),
(155041, 'zhCN', '邦桑迪折磨我的灵魂时，我学到了很多手段。让我来向你展示一些他的巫毒法术吧。', '', 28153),
(155040, 'zhCN', '你不可能永远帮他瞒着我。我终归会向沃金和所有暗矛一族复仇！', '', 28153),
(155039, 'zhCN', '仆从们！杀死他们的勇士，把沃金的骨灰给我抢来。快！', '', 28153),
(155038, 'zhCN', '在哪？你们把沃金藏到哪了？你们是怎么把他藏起来的？', '', 28153),
(155037, 'zhCN', '你们把他藏到哪了？我的老朋友在哪？', '', 28153),
(155036, 'zhCN', '摧毁暗矛部族，把骨灰找出来。', '', 28153),
(155035, 'zhCN', '仆从们，给我搜。找到沃金的骨灰，带回来给我。', '', 28153),
(155034, 'zhCN', '这些肮脏的虫子什么都吃。真恶心。', '', 28153),
(155033, 'zhCN', '球潮虫正在肆虐！在它们变成更大的麻烦前消灭它们。', '', 28153),
(155032, 'zhCN', '我们会的。一路顺风。', '我们会的。一路顺风。', 28153),
(155031, 'zhCN', '你能将我带往正确的方向。你们会没事的吧？', '你能将我带往正确的方向。你们会没事的吧？', 28153),
(155030, 'zhCN', '很抱歉我们没法帮上更多的忙。', '我很抱歉我和我的兄弟帮不了更多的忙。', 28153),
(155029, 'zhCN', '', '干得好！很高兴你能与我们并肩作战。', 28153),
(155028, 'zhCN', '', '竞技场附近有一个纺沙蛛的巢穴。你去将它们清理干净！', 28153),
(155027, 'zhCN', '看来这武器应该出自侏儒之手。不管怎样，战场上能用就行了。', '', 28153),
(155026, 'zhCN', '我们的海军找到些……有趣的武器，只要我们能找出使用方法，也许就能派上用场。去找这里的野兽试试吧。', '', 28153),
(155025, 'zhCN', '', '艾什凡公司得花好几周才能弥补那么多货物的损失。做得好！', 28153),
(155024, 'zhCN', '', '艾什凡公司正在附近制造麻烦。我需要你去阻止他们的行动。', 28153),
(155023, 'zhCN', '一百个倒霉蛋掉到了一座满是武器的小岛上！！立刻购票，从飞艇上欣赏他们的乱斗吧！', '一百个倒霉蛋掉到了一座满是武器的小岛上！！立刻购票，从飞艇上欣赏他们的乱斗吧！', 28153),
(155022, 'zhCN', '我们对机器人收税。接着，我们就开发收税机器人！这真是无穷无尽的财富啊！', '我们对机器人收税。接着，我们就开发收税机器人！这真是无穷无尽的财富啊！', 28153),
(155021, 'zhCN', '黑暗灯泡！起到了电灯泡的相反作用。', '黑暗灯泡！起到了电灯泡的相反作用。', 28153),
(155020, 'zhCN', '给你那些休闲的帽子套上正装的帽子，来应付正式的场合吧！', '给你那些休闲的帽子套上正装的帽子，来应付正式的场合吧！', 28153),
(155019, 'zhCN', '漂浮图腾：你在船上时最想要的图腾！', '漂浮图腾：你在船上时最想要的图腾！', 28153),
(155018, 'zhCN', '枪斗鞋！不，等等……我们以前卖过这个了。那就枪斗袜！', '枪斗鞋！不，等等……我们以前卖过这个了。那就枪斗袜！', 28153),
(155017, 'zhCN', '可回收火箭！', '可回收火箭！', 28153),
(155016, 'zhCN', '全地精炸弹雪橇小队！', '全地精炸弹雪橇小队！', 28153),
(155015, 'zhCN', '武器级的上好芝士。', '武器级的上好芝士。', 28153),
(155014, 'zhCN', '双持链锯战刃！伊利达雷指定产品！', '双持链锯战刃！伊利达雷指定产品！', 28153),
(155013, 'zhCN', '想要稍微打个盹儿？白日梦翠榄石帮你忙！', '想要稍微打个盹儿？白日梦翠榄石帮你忙！', 28153),
(155012, 'zhCN', '战术烧烤钳！', '战术烧烤钳！', 28153),
(155011, 'zhCN', '一个感人的爱情故事，男女主分别是人类和……呃，锦鱼人！', '一个感人的爱情故事，男女主分别是人类和……呃，锦鱼人！', 28153),
(155010, 'zhCN', '干得好，士兵！很高兴你能与我们并肩作战。', '', 28153),
(155009, 'zhCN', '一根上好的柱子，作用不在于支撑屋顶，而是在于压住地板！', '一根上好的柱子，作用不在于支撑屋顶，而是在于压住地板！', 28153),
(155008, 'zhCN', '附近有个纺沙蛛的巢穴挡住了通往峡谷的必经之路。你去为我们的军队扫清道路！', '', 28153),
(155007, 'zhCN', '艾泽里特魔法8号球？是幸运的呢，还是不幸？', '艾泽里特魔法8号球？是幸运的呢，还是不幸？', 28153),
(155006, 'zhCN', '泰达希尔焦炭球！浓厚的烟熏烧烤风味喔！', '泰达希尔焦炭球！浓厚的烟熏烧烤风味喔！', 28153),
(155005, 'zhCN', '能在水上开的车！', '能在水上开的车！', 28153),
(155004, 'zhCN', '游吟诗人！', '游吟诗人！', 28153),
(155003, 'zhCN', '有了这个哨子，飞行管理员召之即来！', '有了这个哨子，飞行管理员召之即来！', 28153),
(155002, 'zhCN', '干得好，士兵！沃顿，这片被称作致命陷阱的地方又少了一只怪物。', '', 28153),
(155001, 'zhCN', '能让你日趋强大的奥术水晶！可能不太稳定，但瑕不掩瑜！', '能让你日趋强大的奥术水晶！可能不太稳定，但瑕不掩瑜！', 28153),
(155000, 'zhCN', '有只巨大的球潮虫正在威胁峡谷，然而贸然进攻太过危险。你得另找办法阻止它！', '', 28153),
(154999, 'zhCN', '厕纸发射枪！想想能这节约多少宝贵的时间吧！', '厕纸发射枪！想想能这节约多少宝贵的时间吧！', 28153),
(154998, 'zhCN', '豪华游船！让你在航行中享受更大空间和更多乐趣。绝对是顶级的享受！', '豪华游船！让你在航行中享受更大空间和更多乐趣。绝对是顶级的享受！', 28153),
(154997, 'zhCN', '可重复食用的口香糖！和你的朋友、宠物、甚至是陌生人一起分享它吧！', '可重复食用的口香糖！和你的朋友、宠物、甚至是陌生人一起分享它吧！', 28153),
(154996, 'zhCN', '那是件脏活，但总得有人去做！派你去总比让我亲自去好，士兵！', '', 28153),
(154995, 'zhCN', '我们要想活下去，就得想办法在这片沙漠种出谷物。我们需要肥料……嗯你去看看能找到什么。', '', 28153),
(154994, 'zhCN', '我承认开始还有点怀疑，但看来用这个对付无信者会相当有用。', '', 28153),
(154993, 'zhCN', '塔查从废墟里又挖出一个赞达拉图腾。试试看，那东西有什么用。', '', 28153),
(154992, 'zhCN', '那看来很有趣！我会把它留着用来对付兽人！', '', 28153),
(154991, 'zhCN', '艾什凡公司得花好几周才能弥补那么多货物的损失。做得好！', '', 28153),
(154990, 'zhCN', '我们的斥候在一处废墟里发现了这个远古赞达拉图腾。让我们看看它有什么用。', '', 28153),
(154989, 'zhCN', '艾什凡公司正在附近进行非法采矿作业。你去阻止他们。', '', 28153),
(154988, 'zhCN', '流沙飞扬，生命不息。谢谢你。', '', 28153),
(154987, 'zhCN', '沃顿的绿洲是珍贵的资源。我们必须对它勤加养护。', '', 28153),
(154986, 'zhCN', '并非每场胜利都源自精彩的战斗。补给才是我们生存的关键。', '', 28153),
(154985, 'zhCN', 'Za uull og nuq i fssh zz oou iiyoq ez oou gul\'kafh anagg', '', 28153),
(154984, 'zhCN', '这片绿洲会是我们在此扩张的重要战术优势。', '', 28153),
(154983, 'zhCN', '我的陨落不过是无尽深渊中一次小小的失败。', '', 28153),
(154982, 'zhCN', '我必须承认，结果比我预想的还要好。', '', 28153),
(154981, 'zhCN', '我们在泽姆兰港的……奇怪的盟友们想出了一些新计划。要是你们相信他们，就伸出援手。', '', 28153),
(154980, 'zhCN', '哈！这能教会他们别惹联盟！', '', 28153),
(154979, 'zhCN', '我们的部队偷了一艘船并装上了武器。去消灭那些亡灵怪物吧！', '', 28153),
(154978, 'zhCN', '干得好！那些受诅咒的恶魔再想冒犯联盟可就要三思了。', '', 28153),
(154977, 'zhCN', '肮脏的亡灵海盗抓住了我们的士兵。救出他们。一个都不能少！', '', 28153),
(154976, 'zhCN', '', '谢谢你。即使流亡者也不应承受那样的命运。', 28153),
(154975, 'zhCN', '', '泽姆兰的海盗抓住了赞达拉流亡者。把他们救出来！', 28153),
(154974, 'zhCN', '无信者正分身乏术。从天上为他们降下死亡吧！', '', 28153),
(154973, 'zhCN', '他们肯定还会卷土重来的。但这至少能让我们享受片刻安宁。', '', 28153),
(154972, 'zhCN', '无信者的数量无穷无尽。我们必须将他们困在这里。', '', 28153),
(154971, 'zhCN', '为了塞塔里斯的荣耀！但愿有一天所有蛇人都能想起她……', '', 28153),
(154970, 'zhCN', '获取我的一部分力量，将无信者从这些土地上清除干净。', '', 28153),
(154969, 'zhCN', '', '我的力量……你做了什么？', 28153),
(154968, 'zhCN', '', '这等力量……我动不了了……', 28153),
(154967, 'zhCN', '我的生命……在流失……', '', 28153),
(154966, 'zhCN', '我动不了了……帮……我……', '', 28153),
(154965, 'zhCN', '呜啊……', '', 28153),
(154964, 'zhCN', '你认为面对神灵你会有机会活下来吗？去死吧！', '', 28153),
(154963, 'zhCN', '更多鲜血！必须平息这种饥渴！', '', 28153),
(154962, 'zhCN', '你的鲜血强化了我！', '', 28153),
(154961, 'zhCN', '工作好累，不想再干了！我要训练，我要成为一个大人物！', '工作好累，不想再干了！我要训练，我要成为一个大人物！', 28153),
(154960, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t艾泽洛克即将施放|cFFFF0000|Hspell:258622|h[回荡脉冲]|h|r！', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t艾泽洛克即将施放|cFFFF0000|Hspell:258622|h[回荡脉冲]|h|r！', 28153),
(154959, 'zhCN', '你从这只狮鹫身上只能找到一只断手，朋友。', '你从这只狮鹫身上只能找到一只断手，朋友。', 28153),
(154956, 'zhCN', '暗影增长。信徒汇聚。我们的时代来临了。', '', 28153),
(154955, 'zhCN', '我会给你的血肉赋予新的意义。', '', 28153),
(154954, 'zhCN', '', '我的力量……我的诅咒……这不可能……', 28153),
(154953, 'zhCN', '如果……你回得来的话。', '', 28153),
(154952, 'zhCN', '等我回来，我们再讨论何为荣誉……以及如何让部落重拾荣誉。', '', 28153),
(154951, 'zhCN', '把他送到监狱。', '', 28153),
(154950, 'zhCN', '你们存在的意义就是成为我的食粮。', '', 28153),
(154949, 'zhCN', '现在就是我说了算。', '', 28153),
(154948, 'zhCN', '这不由联盟的国王说了算！', '', 28153),
(154947, 'zhCN', '听我说，寻死并无荣耀可言。', '', 28153),
(154946, 'zhCN', '我父亲曾说，瓦罗克·萨鲁法尔代表了部落的荣誉……', '', 28153),
(154945, 'zhCN', '不！我想要光荣的战死！', '', 28153),
(154944, 'zhCN', '将士们……住手！', '', 28153),
(154940, 'zhCN', '', '还真是顽强！你们很荣幸，能活着目睹我引以为傲的武器。', 28153),
(154939, 'zhCN', '所有部队，集中火力攻击那头巨兽！今天纳迦休想突破城墙！', '', 28153),
(154937, 'zhCN', '<将我的队伍加入史诗难度的海岛探险队列。>', '<将我的队伍加入史诗难度的海岛探险队列。>', 28153),
(154936, 'zhCN', '<将我的队伍加入英雄难度的海岛探险队列。>', '<将我的队伍加入英雄难度的海岛探险队列。>', 28153),
(154935, 'zhCN', '<加入史诗难度的海岛探险队列。>', '<加入史诗难度的海岛探险队列。>', 28153),
(154934, 'zhCN', '<加入英雄难度的海岛探险队列。>', '<加入英雄难度的海岛探险队列。>', 28153),
(154933, 'zhCN', '去吧，兽群行者，在达萨罗的阶梯上为我树立一座雕像。让其他人明白兽群的力量，然后你将获得我的赐福。', '', 28153),
(154932, 'zhCN', '', '有了这三个卷轴，你来这里就会更轻松了。', 28153),
(154931, 'zhCN', '|TInterface\\ICONS\\Ability_Skyreach_Four_Wind.BLP:20|t %s面向|cFFFF0000$n|r并准备施放|cFFFF0000|Hspell:268403|h[强风劈砍]|h|r！', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s准备对|cFFFF0000$n|r施放|cFFFF0000|Hspell:268932|h[震地之跃]|h|r！', 28153),
(154930, 'zhCN', '至少我能双脚踏着大地死去。', '', 28153),
(154929, 'zhCN', '投得棒极了，外乡人！你令我印象深刻。', '', 28153),
(154928, 'zhCN', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t%s已被|cFFFF0000|Hspell:267702|h[埋葬]|h|r！寻找挣扎的迹象来找到他们！', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t%s已被|cFFFF0000|Hspell:267702|h[埋葬]|h|r！寻找挣扎的迹象来找到他们！', 28153),
(154927, 'zhCN', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t 你被困在了一座墓穴中！|cFFFF0000|Hspell:267764|h[挣扎]|h|r以便让你的同伴知道你在哪里！', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t 你被困在了一座墓穴中！|cFFFF0000|Hspell:267764|h[挣扎]|h|r以便让你的同伴知道你在哪里！', 28153),
(154926, 'zhCN', '我们必须赶回虔敬者圣殿，阻止加卡泽将军释放米斯拉克斯！', '', 28153),
(154925, 'zhCN', '你这个蠢货！米斯拉克斯无法被控制！', '', 28153),
(154924, 'zhCN', '他将唤醒米斯拉克斯，而我们将征服整个艾泽拉斯！', '', 28153),
(154923, 'zhCN', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s准备|cFFFF0000|Hspell:267702|h[埋葬]|h|r|cFFFF0000$n|r！', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s准备|cFFFF0000|Hspell:267702|h[埋葬]|h|r|cFFFF0000$n|r！', 28153),
(154922, 'zhCN', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s准备对|cFFFF0000$n|r施放|cFFFF0000|Hspell:268932|h[震地之跃]|h|r！', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s准备对|cFFFF0000$n|r施放|cFFFF0000|Hspell:268932|h[震地之跃]|h|r！', 28153),
(154921, 'zhCN', '呃啊！站出来吧，为你的罪行付出代价，柯泰克！', '', 28153),
(154920, 'zhCN', '', '我是来这里观察的。我们赞达拉巨魔对这些被遗忘者非常感兴趣。', 28153),
(154919, 'zhCN', '', '我向你保证，我感到荣幸之至，凋零者。', 28153),
(154918, 'zhCN', '', '不知道为什么路被封住了。看看你能不能说服那些士兵把路让开！', 28153),
(154917, 'zhCN', '快点，你们这些废物。我们还有大事要干。', '快点，你们这些废物。我们还有大事要干。', 28153),
(154916, 'zhCN', '滚开，虱子。', '滚开，跳蚤。', 28153),
(154915, 'zhCN', '从我眼前消失。', '从我眼前消失。', 28153),
(154914, 'zhCN', '是我对你手软了。', '我已经对你很客气了。', 28153),
(154913, 'zhCN', '反正我已经受够你了。', '反正我已经受够你了。', 28153),
(154912, 'zhCN', '', '你太过专注于细节了！没问题的！', 28153),
(154911, 'zhCN', '', '万物皆有价——这些吓人的爬虫能让我大赚一笔！就等我把它们运回卡利姆多了。', 28153),
(154910, 'zhCN', '', '他们需要血液才能活下去，你要怎么喂饱他们？', 28153),
(154909, 'zhCN', '', '你为什么要把害虫收集到盒子里？', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154908, 'zhCN', '立即打开这条通道。', '立即打开这条通道。', 28153),
(154907, 'zhCN', '我能看出岁月磨砺了你的野性和智慧，拉克加。我们会惩罚这些无信者，让他们为自己的所作所为付出代价。', '', 28153),
(154906, 'zhCN', '想进去就得先过我这一关，伙计。', '想进去就得先过我这一关，伙计。', 28153),
(154905, 'zhCN', '你是不是耳背，$G小子:丫头;？山谷已经封锁了。', '你是不是耳背，$G小子:丫头;？山谷已经封锁了。', 28153),
(154904, 'zhCN', '准备好防护面具和魔药之罐。我要看看这东西有什么用。', '准备好防护面具和魔药之罐。我要看看这东西有什么用。', 28153),
(154903, 'zhCN', '拜托，给我一副防护面具吧。', '拜托，给我一副防护面具吧。', 28153),
(154902, 'zhCN', '不想惹麻烦的话就退下去，船底耗子。', '不想惹麻烦的话就退下去，船底耗子。', 28153),
(154901, 'zhCN', '没有证件，禁止通行。这是规矩。', '没有证件，禁止通行。这是规矩。', 28153),
(154899, 'zhCN', '艾特文强壮的背，我高明的策略，加上你无畏的决心，我们将战无不胜。', '', 28153),
(154898, 'zhCN', '我会到山顶上去，确保拉克加过了这么多年还没把我忘掉。', '', 28153),
(154897, 'zhCN', '', '等伤员没那么多了我就去休息。', 28153),
(154896, 'zhCN', '', '我没事，这些水手需要我的帮助。', 28153),
(154895, 'zhCN', '照这个速度，你就需要自己找一位治疗者了。你可以从最基础的开始帮忙。', '', 28153),
(154894, 'zhCN', '你看上去累坏了，费欧莉雅，你应该休息一下。', '', 28153),
(154893, 'zhCN', '拿上我的法杖，从无信者的压制高塔汲取能量来为它充能。', '', 28153),
(154892, 'zhCN', '我和艾特文会去风险投资公司的水雷区与你会合。', '', 28153),
(154891, 'zhCN', '妈妈！是米尔拉和$p救了我们！', '妈妈！是米尔拉和$p救了我们！', 28153),
(154890, 'zhCN', '我说过米尔拉不会忘记我们的！她是最棒的！', '我说过米尔拉不会忘记我们的！她是最棒的！', 28153),
(154889, 'zhCN', '', '基罗，你能回来我太高兴了！那里很吓人吧？你是怎么从他们那儿弄到一只三叶虫的？起名字了吗？能让我起吗？它乖不乖？', 28153),
(154888, 'zhCN', '回头我再跟你讲故事吧，米尔拉。当务之急是让我们的人安全地离开这里。', '', 28153),
(154887, 'zhCN', '这真是……出奇地好玩！', '', 28153),
(154886, 'zhCN', '骑上这只三叶虫，我们得在无信者的增援到来之前离开这里！', '', 28153),
(154885, 'zhCN', '', '那下面出什么事了？狂风之心，送我们过去！', 28153),
(154884, 'zhCN', '', '我们先去布伦纳丹探一探吧。最不济，我们也有希望在那里找到这个派克修士。', 28153),
(154883, 'zhCN', '', '斯托颂勋爵执掌整个家族以及整座山谷。听起来他就是这一切的关键，但他已经好几个月没去伯拉勒斯了。', 28153),
(154882, 'zhCN', '', '我们必须先把斯托颂家族带回山谷中。他们掌控着海贤军队，而海贤军队掌握着舰队。', 28153),
(154881, 'zhCN', '', '在狐人旗帜的阴影下颤抖吧，无信者恶棍！', 28153),
(154880, 'zhCN', '你得戴上防护面具才能保护自己。如果你愿意的话，也可以带上魔药之罐来帮忙。', '你得戴上防护面具才能保护自己。如果你愿意的话，也可以带上魔药之罐来帮忙。', 28153),
(154879, 'zhCN', '', '恐怕在舰队安全返回之前，库尔提拉斯无法对联盟提供任何帮助。', 28153),
(154878, 'zhCN', '', '而我们被囚禁在下面的同胞也应该明白，我们没有放弃他们。', 28153),
(154877, 'zhCN', '', '很好，就该让他们知道自己是怎么死的。', 28153),
(154876, 'zhCN', '这样做太冒险了，尼莎。无信者会知道我们就在上面。', '', 28153),
(154875, 'zhCN', '干得好，那个巫妖一直在派兵攻击我们的侦察兵。现在我们应该能集中精力对付部落了。', '', 28153),
(154874, 'zhCN', '德鲁斯瓦有女巫，而纳兹米尔有的就是巫妖了。消灭这个魔头的军队，不管是什么强化了它的力量，统统摧毁。', '', 28153),
(154873, 'zhCN', '', '尼莎会很高兴见到你的！她又到地坑那边猎杀蛇人去了……她总是这样。', 28153),
(154872, 'zhCN', '非常精彩，尽管我知道侏儒拒绝经手与地精有关的任何科技。但至少我们知道这东西能干嘛。', '', 28153),
(154871, 'zhCN', '我们的部队从地精手里征用了一台实验用的机器。在附近的鲜血巨魔大军身上试试，看看它的威力。', '', 28153),
(154870, 'zhCN', '我有一种不好的预感，纳迦的阴谋不仅仅到此为止，对他们保持警惕。', '', 28153),
(154869, 'zhCN', '纳迦！他们在这个世界上散播恐怖已经够久了，让他们的阴谋就此破产吧。', '', 28153),
(154866, 'zhCN', '自从第三次大战以来，我还从没见过有人在对抗部落时拿出这样的勇猛气势。干得好。', '', 28153),
(154864, 'zhCN', '你在抗击部落的战斗中表现得非常精彩，库尔提拉斯人民将知晓你的英勇事迹。', '', 28153),
(154863, 'zhCN', '干得好，但愿这场战争的结局会比第二次大战要好。', '', 28153),
(154861, 'zhCN', '', '孩子们被囚禁在下面的坑里。请多加小心！', 28153),
(154859, 'zhCN', '干得好！没有人能阻挡部落！', '', 28153),
(154858, 'zhCN', '几名侦察兵在这片区域内和部落战斗时牺牲了，现在只能靠你来阻止他们的行动了。', '', 28153),
(154857, 'zhCN', '干得好！我想我可以从你身上学到一些东西，伙计。', '', 28153),
(154856, 'zhCN', '又一个敌人倒下了，很快就会有其他敌人步其后尘。但你可以暂时休息一下了。', '', 28153),
(154855, 'zhCN', '', '我会让狂风之心过来。东边码头附近有一座栖木，她会在那里等我们。', 28153),
(154854, 'zhCN', '啊，胜利！甜蜜的滋味，伙计！', '', 28153),
(154853, 'zhCN', '在第三次大战期间，我逐渐熟悉了部落的战术。他们似乎要在这里使用一种异常危险的战术。把他们干掉。', '', 28153),
(154852, 'zhCN', '哈哈！它根本不知道自己的对手是谁。', '', 28153),
(154851, 'zhCN', '部落在附近的行动让我想起了他们在第二次大战里惯用的手段，我们必须在他们得逞之前阻止他们。', '', 28153),
(154850, 'zhCN', '精彩至极，伙计！', '', 28153),
(154848, 'zhCN', '一个强大的灵魂就在附近。快，干掉它！', '', 28153),
(154846, 'zhCN', '一个敌人隐藏在附近，让我们干掉它！', '', 28153),
(154845, 'zhCN', '我代表第七军团的全体将士，感谢你在对抗部落的战斗中所做出的贡献。', '', 28153),
(154843, 'zhCN', '这里的部落已被打败，第七军团可以继续推进了。干得好！', '', 28153),
(154842, 'zhCN', '安度因国王将知晓你对抗部落的英勇事迹。', '', 28153),
(154838, 'zhCN', '我的侦察兵报告说部落正在靠近你所在的位置。他们对伏击毫无防备，干掉他们！', '', 28153),
(154836, 'zhCN', '我们接到报告称附近有大批部落正在集结，我们发起进攻的时机到了！', '', 28153),
(154833, 'zhCN', '附近有一个目标，迅速出击！', '', 28153),
(154832, 'zhCN', '第七军团发现部落军队正在附近活动，现在命令你前去阻击并破坏他们的企图！', '', 28153),
(154831, 'zhCN', '附近出现了新的威胁。你知道该怎么做。', '', 28153),
(154830, 'zhCN', '万灵告诉我某个强大的敌人就潜伏在附近，我们必须……在它成为威胁之前消灭它。', '', 28153),
(154829, 'zhCN', '附近潜伏着某种强大的威胁。消灭它！', '', 28153),
(154828, 'zhCN', '干得好！你有没有考虑过常驻第七军团？我们需要你这样的人才！', '', 28153),
(154827, 'zhCN', '干得漂亮，为了安度因国王，为了联盟！', '', 28153),
(154826, 'zhCN', '今天你为第七军团和联盟立下了汗马功劳。', '', 28153),
(154825, 'zhCN', '请接受我的谢意，也请接受第七军团每一位士兵的谢意。', '', 28153),
(154824, 'zhCN', '我保证会把你的英勇事迹传达给安度因国王。', '', 28153),
(154823, 'zhCN', '我的侦察兵报告，在你附近潜伏着一个强大的敌人，干掉它。', '', 28153),
(154822, 'zhCN', '第七军团接到命令，必须干掉你附近的一个目标。', '', 28153),
(154821, 'zhCN', '他们还是多加小心为好，我们不可能每次都在。谢谢你，勇士。', '', 28153),
(154820, 'zhCN', '有支勘测队被亡灵的陷阱困住了！快去解救他们！', '', 28153),
(154819, 'zhCN', '后面的事情就让我们来吧，终结戈霍恩的时候到了。', '', 28153),
(154818, 'zhCN', '咳，这么说，他是一具复生的尸体？我们把他埋到土里去吧。', '', 28153),
(154817, 'zhCN', '我认出那个丑巨魔了。祖尔他在打什么主意？', '', 28153),
(154816, 'zhCN', '……', '', 28153),
(154815, 'zhCN', '……', '', 28153),
(154814, 'zhCN', '……', '', 28153),
(154813, 'zhCN', '……', '', 28153),
(154812, 'zhCN', '……', '', 28153),
(154811, 'zhCN', '……', '', 28153),
(154810, 'zhCN', '……', '', 28153),
(154809, 'zhCN', '……', '', 28153),
(154808, 'zhCN', '你漏掉了一个！', '', 28153),
(154807, 'zhCN', '', '这座设施对各种生命形态进行实验，研究净化上古之神腐蚀的方法。', 28153),
(154806, 'zhCN', '哇！那究竟是什么鬼东西？', '', 28153),
(154805, 'zhCN', '……', '', 28153),
(154804, 'zhCN', '我以前听说过恩佐斯的爪牙，但从未亲眼见过。说实话，我希望以后再也别见到了。', '', 28153),
(154803, 'zhCN', '真是好险，如果它过了我们这一关，谁都不知道地面上会有多少人遭到它的感染。', '', 28153),
(154802, 'zhCN', '听上去不错。在我们解决这个问题的时候，我去找找泰坦其他的秘密。', '', 28153),
(154801, 'zhCN', '……', '', 28153),
(154800, 'zhCN', '哎！我想我们没那工夫了。最好在这种腐烂恶化之前干掉戈霍恩。', '', 28153),
(154799, 'zhCN', '你找到答案了吗？', '', 28153),
(154798, 'zhCN', '好吧，这就解释了鲜血巨魔潜伏在附近的原因了，但为何泰坦会让一个古神活到现在？', '', 28153),
(154797, 'zhCN', '你的出现让人深感宽慰。要是我没猜错的话，这是某种研究设施。', '', 28153),
(154796, 'zhCN', '好啦！这样就行了！如果你了解了这种科技的诀窍，就不会晕头转向了。', '', 28153),
(154795, 'zhCN', '第十二回！', '', 28153),
(154794, 'zhCN', '什么？！不！这些该死的门关上了！给我砸，直到门打开为止！', '', 28153),
(154793, 'zhCN', '给我点儿时间，我来打开这些门。', '', 28153),
(154792, 'zhCN', '你成功了！再给我点儿时间。我已经接入了某种守护者，是他在掌管这个设施的运行。', '', 28153),
(154791, 'zhCN', '我刚刚创造了传奇。', '', 28153),
(154789, 'zhCN', '战斗越来越激烈了，继续攻击我们的敌人！', '', 28153),
(154788, 'zhCN', '附近发现了一个重要目标，我们需要你马上干掉它。', '', 28153),
(154787, 'zhCN', '一个强大的敌人就在附近。消灭它。不用留情！', '', 28153),
(154780, 'zhCN', '准备战斗。', '准备战斗。', 28153),
(154779, 'zhCN', '', '托卡纳塔节！哈！哈！', 28153),
(154777, 'zhCN', '', '今天是托卡纳塔节！如果你想加入的话，就拿起一支火炬，做好起跑准备！', 28153),
(154774, 'zhCN', '', '勇士，你似乎正在逐渐博得赞达拉巨魔的信任。我得去处理其他事务了，祝你好运。', 28153),
(154772, 'zhCN', '', '欧库勒斯，你能不能设置好这里的传送系统。我们需要建立连接部落主城的物资补给线。', 28153),
(154770, 'zhCN', '尽快去波尔金之陨和我碰头，$p。我们一起潜入柯泰克的堡垒。', '', 28153),
(154769, 'zhCN', '', '塔兰吉公主好心地透露了一个古老传送网络的信息，我们也许可以善加利用。', 28153),
(154768, 'zhCN', '', '当你准备好歼灭艾什凡的舰队时，就来找我。', 28153),
(154767, 'zhCN', '', '你们做得很好，英雄们。但伯拉勒斯还没有彻底脱离危险。', 28153),
(154766, 'zhCN', '回去工作，他们是跟我一起的。', '回去工作吧。他们是跟我一起的。', 28153),
(154765, 'zhCN', '外人禁止进入档案室，修士。', '外人禁止进入档案室，修士。', 28153),
(154764, 'zhCN', '我站在海滩上，被恶臭的海地精团团包围……就在那时，一位英雄降临了！噢！你好，又见面了，$n！', '', 28153),
(154763, 'zhCN', '去拿到那些卷轴！我要走……风景优美的那条路，回到营地，然后分享你学到的东西。', '', 28153),
(154762, 'zhCN', '不管联盟派什么来对付我们，都只能品尝到失败。', '', 28153),
(154761, 'zhCN', '有一些联盟的勇士想来拯救这座城市，让他们知道这些努力都是徒劳的。', '', 28153),
(154760, 'zhCN', '有了这些弹药，我们就能对联盟造成严重的破坏。', '', 28153),
(154759, 'zhCN', '艾什凡的部队在用艾泽里特火炮攻击城市，把这些武器收到部落帐下！', '', 28153),
(154758, 'zhCN', '没有了军官，我们就能把库尔提拉斯人赶到海里去。', '', 28153),
(154757, 'zhCN', '有名库尔提拉斯军官正在试图集结防御。把他从战场上清除掉。', '', 28153),
(154756, 'zhCN', '', '干得漂亮。你让部落明白了，伯拉勒斯永远不会落入敌人手里！', 28153),
(154755, 'zhCN', '', '部落正在利用攻城的时机在城市里大肆劫掠！不要让他们洗劫伯拉勒斯！', 28153),
(154754, 'zhCN', '', '干得好，你让艾什凡知道了她的乌合之众根本不是你的对手。', 28153),
(154753, 'zhCN', '', '艾什凡的雇佣兵正在城市里制造破坏。阻止他们！', 28153),
(154752, 'zhCN', '', '干得好，只有这些恶棍才应该披枷带锁。', 28153),
(154751, 'zhCN', '', '海盗们正在捕捉平民充当奴隶！终止他们的恶行！', 28153),
(154750, 'zhCN', '高莱克·图尔……来了……', '', 28153),
(154749, 'zhCN', '苦难会降临到整个库尔提拉斯。第一个受苦的就是你！', '', 28153),
(154748, 'zhCN', '蠢货！你会尖叫着死去！', '', 28153),
(154747, 'zhCN', 'Oou ph\'magg an\'qov nuq.', '', 28153),
(154746, 'zhCN', 'Ywaq ongg uul\'gwa no AN\'zig!', '', 28153),
(154745, 'zhCN', 'Arwi ryiu yrr oou qam!', '', 28153),
(154744, 'zhCN', 'AN\'zig wgah qam za zyqtahg...', '', 28153),
(154743, 'zhCN', 'AN\'zig wgah zzof!', '', 28153),
(154742, 'zhCN', 'Ywaq fhssh wgah qam!', '', 28153),
(154741, 'zhCN', 'Uulg\'ma zyqtahg yrr!', '', 28153),
(154740, 'zhCN', 'Hnakf ywaq shuul\'wah yawifk yrr uull zz thyzz!', '', 28153),
(154739, 'zhCN', '趁着你还有机会，马上离开这里！其他人肯定察觉到你的动静了。', '趁着你还有机会，马上离开这里！其他人肯定察觉到你的动静了。', 28153),
(154738, 'zhCN', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t你已成为|cFFFF0000|Hspell:260838|h[钻地猛砸]|h|r的目标！', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t你已成为|cFFFF0000|Hspell:260838|h[钻地猛砸]|h|r的目标！', 28153),
(154737, 'zhCN', 'Og qam shfk wgah iiqaah halahs ma!', '', 28153),
(154736, 'zhCN', '在布伦纳丹找到派克修士，把吊坠交给他。我们的工作才刚刚开始，他需要你的帮助。', '在布伦纳丹找到派克修士，把吊坠交给他。我们的工作才刚刚开始，他需要你的帮助。', 28153),
(154735, 'zhCN', 'Maq oou kaaxth zz ak\'uq yrr sk\'yahf ma!', '', 28153),
(154734, 'zhCN', '虽然我们的人民被带往了一条黑暗的道路，但是反抗的种子已经在我们之中生根发芽。', '虽然我们的人民走上了一条黑暗的道路，但是反抗的种子已经在我们之中生根发芽。', 28153),
(154733, 'zhCN', 'Zuq ag\'xig ka\'kar za wgah!', '', 28153),
(154732, 'zhCN', 'Puul qi\'plahf ni oou bormax!', '', 28153),
(154731, 'zhCN', 'Xith wgah!', '', 28153),
(154729, 'zhCN', 'Naz raqul!', '', 28153),
(154728, 'zhCN', 'I wgah far\'al zuq ni shn!', '', 28153),
(154727, 'zhCN', '舰队并没有失踪，而是被禁锢在一股反常的风暴之中。', '舰队没有失踪，而是被禁锢在一股反常的风暴之中。', 28153),
(154726, 'zhCN', 'Zuq wgah qam n\'lyeth!', '', 28153),
(154725, 'zhCN', 'Zuq ag\'xig gag wgah naggwa\'fssh!', '', 28153),
(154724, 'zhCN', 'Zuq ag\'xig bormax oou iiqaath!', '', 28153),
(154723, 'zhCN', '你还好吗？我早该知道，韦德并没有独善其身，而是投靠了斯托颂家族。', '你还好吗？我早该知道，韦德不会比控制斯托颂家族的阴影好多少。', 28153),
(154722, 'zhCN', '', '你说“危险”是什么意思？', 28153),
(154721, 'zhCN', '好的，修士。', '好的，修士。', 28153),
(154720, 'zhCN', '不要让其他人进来，我有贵客。', '不要让其他人进来，我有贵客。', 28153),
(154719, 'zhCN', '你不知道这里有多危险。', '', 28153),
(154718, 'zhCN', '跟我来，别抬头。', '', 28153),
(154717, 'zhCN', '我们的防线还很脆弱。快，阻止部落的进犯，别让他们靠近！', '', 28153),
(154716, 'zhCN', '激流堡还很脆弱，无法承受正面攻击。摧毁部落的先锋军，别让它们靠近！', '', 28153),
(154715, 'zhCN', '哈！这确实表示了对帕库的尊重！', '', 28153),
(154714, 'zhCN', '派遣部队！我们要在这些联盟臭虫扩散之前踩死他们！', '', 28153),
(154713, 'zhCN', '', '是时候了！登上赞枢尔的阶梯，敬奉我们的洛阿神灵吧。有了它们的庇佑，赞达拉将万古长存！让贡克以你为豪！', 28153),
(154712, 'zhCN', '', '立刻部署部队！绝不能让联盟有立足之地！', 28153),
(154711, 'zhCN', '拿起武器！战斗开始了！', '', 28153),
(154710, 'zhCN', '部队就位！激流堡的城墙将在部落的力量面前灰飞烟灭！', '', 28153),
(154709, 'zhCN', '据点需要支援。把那些部队击退，别让他们靠近！', '', 28153),
(154708, 'zhCN', '不要耽误，斯托颂勋爵命令把这些地图立刻送到风暴神殿！', '', 28153),
(154707, 'zhCN', '派遣部队！我们要把这碍眼的基地夷为平地。', '', 28153),
(154706, 'zhCN', '', '海潮贤者们有着世界上藏书最完整的图书馆，我打赌我们可以在那边找到我们的档案员。', 28153),
(154705, 'zhCN', '', '联盟在向阿戈罗克进军！必须击败他们，不能让他们到达据点！', 28153),
(154704, 'zhCN', '联盟将士！把他们干掉！', '', 28153),
(154703, 'zhCN', '联军士兵，冲锋！', '', 28153),
(154702, 'zhCN', '部落，出战！碾碎那帮城堡里的懦夫，别让他们突破我们的大门！', '', 28153),
(154701, 'zhCN', '', '曲球！曲球！', 28153),
(154700, 'zhCN', '噢！曲球！曲球！', '', 28153),
(154699, 'zhCN', '', '这看上去可不太妙啊。我们走吧。', 28153),
(154698, 'zhCN', '走开，去档案馆里陪那个白痴阿伦吧！否则我就用你来稳定裂隙。', '', 28153),
(154697, 'zhCN', '加倍努力，蠢货，别让我们失去控制！', '', 28153),
(154696, 'zhCN', '', '那好吧。我们会去烦他的！', 28153),
(154695, 'zhCN', '', '如果你是来这里浪费时间的，就去烦阿伦吧。', 28153),
(154694, 'zhCN', '', '向海潮袒露你的灵魂。真相在潮汐的低语中！', 28153),
(154693, 'zhCN', '播种', '播种', 28153),
(154692, 'zhCN', '', '吉尔尼斯将士，装填炮弹！进攻！', 28153),
(154691, 'zhCN', '嗯，女士们，先生们，开动引擎！进攻！', '', 28153),
(154690, 'zhCN', '火枪手！上膛！前进！', '火枪手！上膛！前进！', 28153),
(154689, 'zhCN', '', '我们能保证你的船只安全通行，但有条件。', 28153),
(154688, 'zhCN', '', '悲剧不断啊，也许这儿真不是个办婚礼的好地方。', 28153),
(154687, 'zhCN', '', '婚礼本该充满欢乐，但却被这些怪兽毁掉了！消灭它们，营救参加婚礼的宾客！', 28153),
(154686, 'zhCN', '', '所以……你就是拒绝了？', 28153),
(154685, 'zhCN', '', '你简直就和阿伦修士一样令人不快。', 28153),
(154684, 'zhCN', '', '你好，这里谁做主？', 28153),
(154683, 'zhCN', '哼。', '哼。', 28153),
(154682, 'zhCN', '让血液从溃烂中流走，在痛苦中歌唱吧！', '', 28153),
(154681, 'zhCN', '不要拒绝疯狂！吞下它！', '', 28153),
(154680, 'zhCN', '欣赏腐化之美，向它敞开怀抱！', '', 28153),
(154679, 'zhCN', '我会让你化为灰烬！', '', 28153),
(154678, 'zhCN', '夏尔扎克斯渴望毁灭!', '', 28153),
(154677, 'zhCN', '你活不了的！', '', 28153),
(154676, 'zhCN', '你们逃脱不了被毁灭的命运！', '', 28153),
(154675, 'zhCN', '你们无法从阴影中挣脱！', '', 28153),
(154674, 'zhCN', '毁灭！', '', 28153),
(154673, 'zhCN', '消灭一切！', '', 28153),
(154672, 'zhCN', '你们无法抵抗我的召唤。', '', 28153),
(154671, 'zhCN', '把自己献给瘟疫吧！', '', 28153),
(154670, 'zhCN', '戈霍恩是无法阻止的……', '', 28153),
(154669, 'zhCN', '腐化会吞噬一切。', '', 28153),
(154668, 'zhCN', '你的躯壳属于戈霍恩。', '', 28153),
(154667, 'zhCN', '腐化又有祭品了！', '', 28153),
(154666, 'zhCN', '戈霍恩将会崛起！', '', 28153),
(154665, 'zhCN', '你们的世界将被终结！', '', 28153),
(154664, 'zhCN', '你的腐化不可避免。', '', 28153),
(154663, 'zhCN', '你喉咙里的瘙痒，和你大脑中的悸动。我一直都存在于你的体内。', '', 28153),
(154662, 'zhCN', '万物终会凋零。承认真相，并接受转化吧。', '', 28153),
(154661, 'zhCN', '', '起源重组引擎已恢复。允许访问房间。', 28153),
(154660, 'zhCN', '', '控制台已启动。设施守卫重启中。', 28153),
(154659, 'zhCN', '哦！还有一件事，不，两件。', '', 28153),
(154658, 'zhCN', '', '一号控制台启动。正在重建能量矩阵。', 28153),
(154657, 'zhCN', '', '实验样本戈霍恩已被消灭。无可用样本留存。', 28153),
(154656, 'zhCN', '', '腐化度降至安全等级。系统完整性已恢复。', 28153),
(154655, 'zhCN', '最后，这个星球会像巨大的疖子一样裂开，我的腐化也将传播到整个宇宙。', '', 28153),
(154654, 'zhCN', '你们将传播我的瘟疫，一个巨大的腐烂囊肿会覆盖这个世界，不断翻腾。', '', 28153),
(154653, 'zhCN', '真是迫不及待的宿主啊。你们将成为最早收到我馈赠的人。', '', 28153),
(154652, 'zhCN', '封印已解除，泰坦也已不在。属于腐化的时代开始了。', '', 28153),
(154651, 'zhCN', '', '这就是达萨罗的复仇，你这邪恶的怪物！', 28153),
(154650, 'zhCN', '', '剩下的就靠我们了。我们将彻底清除戈霍恩的疫病。', 28153),
(154649, 'zhCN', '', '警告，前方侦测到显著污染威胁。隔离协议不允许我继续前进。', 28153),
(154648, 'zhCN', '完美，$p！要向风险投资公司展开反击，这些水雷已经绰绰有余了。', '', 28153),
(154647, 'zhCN', '', '他以何种方式归来并不重要。反正我都会用匕首把他送回深渊。', 28153),
(154646, 'zhCN', '可供选择的水雷有很多。', '', 28153),
(154645, 'zhCN', '', '分析显示存在高强度腐化。理论解释：戈霍恩重新活化并且强化了该样本。需要进一步测试。', 28153),
(154644, 'zhCN', '', '祖尔？！他怎么还活着？我亲眼看到他死在我父亲的手里。', 28153),
(154643, 'zhCN', '这些水雷不是用来探测海龟的！我们可以安全地收集它们。', '', 28153),
(154642, 'zhCN', '', '你好像漏掉了一个。', 28153),
(154641, 'zhCN', '', '实验的焦点是戈霍恩利用腐化使已死亡组织重新活化的能力。实验结论尚不完全，所有样本已被销毁。', 28153),
(154640, 'zhCN', '', '观察正确。本设施使用洛阿神灵进行过很多实验，以此寻找消除上古之神腐化的办法。', 28153),
(154639, 'zhCN', '', '这是什么生物？看起来以前曾经是个洛阿神灵。', 28153),
(154638, 'zhCN', '', '既然这东西是戈霍恩的爪牙，我们就必须阻止他，免得他们的军队到达地表。', 28153),
(154637, 'zhCN', '', '错误。圆盘故障。损坏的数据流已被部署。', 28153),
(154636, 'zhCN', '', '开始启动序列。', 28153),
(154635, 'zhCN', '', '请前往医疗站报到，以便进行神经提取及脑组织采集。', 28153),
(154634, 'zhCN', '', '大脑皮层分析显示，在场的所有个体都曾与上古之神的样本进行过交互。', 28153),
(154633, 'zhCN', '', '你的以往经历中的任何可用数据都可以帮助本设施进行研究。', 28153),
(154632, 'zhCN', '', '大脑皮层分析显示，一些个体曾与上古之神样本进行过交互。', 28153),
(154631, 'zhCN', '', '并且存有总计950,000,000,000NB的音乐播放列表与自拍图像。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154630, 'zhCN', '', '75NB关于所有现存化合物的信息。', 28153),
(154629, 'zhCN', '', '这些圆盘目前记录了50NB关于宇宙中已知生命形态的生物学数据。', 28153),
(154628, 'zhCN', '', '正在进入数据库。这里收集了泰坦的各类知识。', 28153),
(154627, 'zhCN', '你的抗争是徒劳的。我的瘟疫不会停下。它早已在你的体内滋长。', '', 28153),
(154626, 'zhCN', '', '如果我们被它击败，地表上所有的生命都会被它感染。', 28153),
(154625, 'zhCN', '啊，欢迎。最近很少有客人来，档案室更是少人问津。\n\n我能帮你什么忙吗？', '啊，欢迎。最近很少有客人来，档案室更是少人问津。\n\n我能帮你什么忙吗？', 28153),
(154624, 'zhCN', '', '警报。病毒抑制装置被破坏。污染样本接近中。感染风险迫近。', 28153),
(154623, 'zhCN', '', '这个实验室存放着数千种已知宇宙中最致命的病毒株样本，它们按照字母顺序排列以便检索。', 28153),
(154622, 'zhCN', '', '正在进入病毒生态区。', 28153),
(154621, 'zhCN', '', '记得时刻保持真言术：盾，这样才能获得救赎的治疗效果。', 28153),
(154620, 'zhCN', '记得时刻保持真言术：盾，这样才能获得救赎的治疗效果。', '', 28153),
(154619, 'zhCN', '', '对你自己施放真言术：盾，然后对目标假人造成伤害，从而治疗你的伤势。', 28153),
(154618, 'zhCN', '对你自己施放真言术：盾，然后对目标假人造成伤害，从而治疗你的伤势。', '', 28153),
(154617, 'zhCN', '', '你对一名敌人造成伤害时，有你的救赎效果的人都会得到治疗。', 28153),
(154616, 'zhCN', '你对一名敌人造成伤害时，有你的救赎效果的人都会得到治疗。', '', 28153),
(154615, 'zhCN', '', '有些法术，比如真言术：盾，会对你的目标施加救赎效果。', 28153),
(154614, 'zhCN', '你能跟我说说失踪舰队的事吗？', '你能跟我说说失踪舰队的事吗？', 28153),
(154613, 'zhCN', '有些法术，比如真言术：盾，会对你的目标施加救赎效果。', '', 28153),
(154612, 'zhCN', '但我们先得说服大酋长。这就需要你帮忙了。来吧。', '', 28153),
(154611, 'zhCN', '也许我们该去讨还人情了。这样一来，我们就能为部落的军力添砖加瓦。', '', 28153),
(154610, 'zhCN', '$n，你我都热爱部落，但如果我们作壁上观，部落恐怕会在这场战争中灭亡。', '', 28153),
(154609, 'zhCN', '', '我们有个计划。激活所有控制台，彻底铲除戈霍恩的瘟疫。', 28153),
(154608, 'zhCN', '', '激活所有控制台才能打开戈霍恩的房间，可以激活起源重组引擎净化样本。', 28153),
(154607, 'zhCN', '', '要摧毁此样本，你必须重新激活这一区域所有房间的控制台。', 28153),
(154606, 'zhCN', '', '我们没有那么多时间了。必须现在就阻止戈霍恩!', 28153),
(154605, 'zhCN', '', '没有。数据不充分。正在开发替代试验，预计在2364个周期后部署。', 28153),
(154604, 'zhCN', '啊！这东西冲击力好大！', '', 28153),
(154603, 'zhCN', '', '你找到答案了吗？', 28153),
(154602, 'zhCN', '现在只需要一点火花……你最好退后点。', '', 28153),
(154601, 'zhCN', '也许我们可以把锁炸开？把刚才的火药撒点上去。', '', 28153),
(154600, 'zhCN', '', '必须收集数据，对抗上古之神。戈霍恩独有的生物特性或许就是消除威胁的答案。', 28153),
(154599, 'zhCN', '', '你一直留着那个怪物？！为什么？', 28153),
(154598, 'zhCN', '', '名称，奥迪尔。该研究设施旨在抑制并研究名为戈霍恩的实体。', 28153),
(154597, 'zhCN', '', '这是什么地方？', 28153),
(154596, 'zhCN', '', '设施系统受损。请务必小心。', 28153),
(154595, 'zhCN', '', '门被锁住了！在我们化为灰烬前关闭那台机器！', 28153),
(154594, 'zhCN', '', '警报。侦测到被污染的生命体。焚化装置启动。', 28153),
(154593, 'zhCN', '', '她一定是腐化未能完全侵蚀这个设施的原因。', 28153),
(154592, 'zhCN', '', '我是坚韧主母，无尽研究的使徒。简称：纯净圣母。', 28153),
(154591, 'zhCN', '', '为了部落！', 28153),
(154590, 'zhCN', '', '什么声音？', 28153),
(154589, 'zhCN', '', '为了部落！', 28153),
(154588, 'zhCN', 'Lok-tar ogar！为了部落！', '', 28153),
(154587, 'zhCN', '', '恶性样本已被清除。正在打开净化室。', 28153),
(154586, 'zhCN', '', '我接受你的效忠，大王。奥格瑞玛欢迎你的人民。', 28153),
(154585, 'zhCN', '', '德拉诺沦陷了，但我们会在艾泽拉斯建立新的家园。现在我们同仇敌忾！', 28153),
(154584, 'zhCN', '正在撒火药', '正在撒火药', 28153),
(154583, 'zhCN', '', '伊崔格和你的勇士证明了他们的勇气与高贵。如果他们是部落之心的体现，那我们很乐意与他们并肩作战。', 28153),
(154582, 'zhCN', '', '灭世机甲都没把塔罗克干掉？！绝不能让这个怪物成为我们消灭戈霍恩的绊脚石！', 28153),
(154581, 'zhCN', '邦桑迪……', '家，是那么遥远……', 28153),
(154580, 'zhCN', '我知道你很难过，亲爱的，但这里有真正的怪物。我们必须离开了。', '我知道你很难过，亲爱的，但这里有真正的怪物。我们必须离开了。', 28153),
(154578, 'zhCN', '', '荣耀是我们的一切！这份誓言对我们可不是儿戏，大酋长。', 28153),
(154577, 'zhCN', '蛋糕还可以再订，但现在我们该走了。', '蛋糕还可以再订，但现在我们该走了。', 28153),
(154576, 'zhCN', '我知道你很生气，但我们真的必须马上离开了，亲爱的。', '我知道你很生气，但我们真的必须马上离开了，亲爱的。', 28153),
(154575, 'zhCN', '亲爱的，我们必须走了。', '亲爱的，我们必须走了。', 28153),
(154574, 'zhCN', '', '伊崔格谈起过你的人民的力量。想必你们也像他一样看重荣耀？', 28153),
(154572, 'zhCN', '你毁了我的婚纱！这套婚纱如此完美！用的是奎尔萨拉斯的进口丝绸！这可是我母亲的头纱！你好大的胆子！', '你毁了我的婚纱！这套婚纱如此完美！用的是奎尔萨拉斯的进口丝绸！这可是我母亲的头纱！你好大的胆子！', 28153),
(154570, 'zhCN', '我们的使命成功了，大酋长。盖亚拉大王承诺，她的士兵会加入部落。', '', 28153),
(154569, 'zhCN', '你杀死了婚宴承包人！他连开胃菜都还没上！', '你杀死了婚宴承包人！他连开胃菜都还没上！', 28153),
(154568, 'zhCN', '我归于尘埃。', '终于，死得其所！', 28153),
(154567, 'zhCN', '你要为毁掉我的婚礼付出代价，你，你这个，管你是什么东西！', '你要为毁掉我的婚礼付出代价，你，你这个，管你是什么东西！', 28153),
(154566, 'zhCN', '我付出了多少心血才做得这么完美，你知道吗？', '我付出了多少心血才做得这么完美，你知道吗？', 28153),
(154565, 'zhCN', '你竟敢破坏我的大喜日子！？', '你竟敢破坏我的大喜日子！？', 28153),
(154564, 'zhCN', '终于……结束了。', '不能就这样……结束。', 28153),
(154563, 'zhCN', '我已经四个月没吃过面包了！', '我已经四个月没吃过面包了！', 28153),
(154562, 'zhCN', '狂沙将吞噬我们所有人。', '死亡是唯一的解脱方式。', 28153),
(154561, 'zhCN', '你知不知道那块蛋糕值多少钱！？', '你知不知道那块蛋糕值多少钱！？', 28153),
(154560, 'zhCN', '我为了订这个地方整整等了两年！', '我为了订这个地方整整等了两年！两！年！', 28153),
(154559, 'zhCN', '死亡未曾阻止我……', '', 28153),
(154558, 'zhCN', '我用一根手指头就能干掉你！', '', 28153),
(154557, 'zhCN', '', '可收集一个新的能量矩阵。', 28153),
(154556, 'zhCN', '', '可获取一个能量矩阵。', 28153),
(154555, 'zhCN', '', '注意。可获取一个新的能量矩阵。', 28153),
(154554, 'zhCN', '', '警告！重组冲击即将发射。请清空该区域。', 28153),
(154553, 'zhCN', '', '警报。重组冲击序列开启。请清空该区域。', 28153),
(154551, 'zhCN', '部落被击败了！', '', 28153),
(154550, 'zhCN', '很快你就会发现你的抵抗是多么愚蠢！', '很快你就会发现你的抵抗是多么愚蠢！', 28153),
(154549, 'zhCN', '出来受死吧！', '出来受死吧！', 28153),
(154548, 'zhCN', '潜伏在深渊的他，会用你的皮做成斗篷！', '潜伏在深渊的他，会用你的皮做成斗篷！', 28153),
(154547, 'zhCN', '可悲地挣扎求生吧！无尽的潮汐最终会将你吞没！', '可悲地挣扎求生吧！无尽的潮汐最终会将你吞没！', 28153),
(154546, 'zhCN', '', '使用苦修来治疗你的伤口。', 28153),
(154545, 'zhCN', '这是什么火药啊？喂，帮我抓一把。', '', 28153),
(154544, 'zhCN', '使用苦修来治疗你的伤口。', '', 28153),
(154543, 'zhCN', '', '对你自己或盟友施放苦修会造成治疗，而不是伤害。', 28153),
(154542, 'zhCN', '对你自己或盟友施放苦修会造成治疗，而不是伤害。', '', 28153),
(154541, 'zhCN', '干掉那些怪物！', '干掉那些怪物！', 28153),
(154540, 'zhCN', '这本该是一个愉快的场合！', '这本该是一个愉快的场合！', 28153),
(154539, 'zhCN', '怎么回事？发生什么事了？这些是什么怪物？', '怎么回事？发生什么事了？这些是什么怪物？', 28153),
(154538, 'zhCN', '这比烂醉如泥的亲戚们还糟！', '这比烂醉如泥的亲戚们还糟！', 28153),
(154537, 'zhCN', '为什么会这样？', '为什么会这样？', 28153),
(154536, 'zhCN', '我们连放克陆行鸟的舞都还没跳呢！', '我们连放克陆行鸟的舞都还没跳呢！', 28153),
(154535, 'zhCN', '今天本该是喜庆的日子！', '今天本该是喜庆的日子！', 28153),
(154534, 'zhCN', '啊啊啊！', '啊啊啊！', 28153),
(154533, 'zhCN', '我们就先行告退了，大酋长。来吧，$n。', '', 28153),
(154532, 'zhCN', '', '我们的夜之子盟友对传送法术有特别独到的理解。我建议你们此行可以去寻求他们的帮助。', 28153),
(154531, 'zhCN', '我找到了加尔鲁什前往那个世界时使用的神器碎片。这样就可以重新打开道路……但我需要帮助。', '', 28153),
(154530, 'zhCN', '', '这计划的确很棒。但我以为通向另一个德拉诺的大门早就关上了。', 28153),
(154529, 'zhCN', '我要去找欧维斯谈谈。我喜欢我的工作，也想一直做下去……按我自己的规矩来。', '', 28153),
(154528, 'zhCN', '这意思是……我明白了。', '', 28153),
(154527, 'zhCN', '唔……我不相信船长会拒绝加入艾什凡。他好像打定主意了。', '', 28153),
(154526, 'zhCN', '', '你怎么说，$n？准备好去寻求新盟友了吗？', 28153),
(154525, 'zhCN', '', '人们颂扬玛格汉兽人的战斗实力。接下来的日子里，我们的确需要这些无畏的士兵。', 28153),
(154524, 'zhCN', '', '来自另一个世界的好战兽人吗？一群训练有素的士兵……随时准备着将武器对准联盟。真有意思……', 28153),
(154523, 'zhCN', '这位英雄从加尔鲁什和燃烧军团手中拯救了德拉诺，因此也赢得了这些兽人的信任。他们欠部落一份情，是时候让他们好好报答一番了。', '', 28153),
(154522, 'zhCN', '大酋长，数年前，部落追杀逃亡的加尔鲁什，追到了另一个德拉诺世界，与我记忆中一样真切。', '', 28153),
(154521, 'zhCN', '我们要拒绝艾什凡，这是船长的命令。', '我们要拒绝艾什凡，这是船长的命令。', 28153),
(154520, 'zhCN', '你这身衣服真是不错呀，朋友。你有什么需要吗？', '', 28153),
(154519, 'zhCN', '开怀畅饮吧，朋友们。你们看上去干巴巴的……哈！', '开怀畅饮吧，朋友们。你们看上去干巴巴的……哈！', 28153),
(154518, 'zhCN', '破坏', '破坏', 28153),
(154516, 'zhCN', '你不是学生。你最好有充分的理由来解释为什么要妨碍我上课。', '你不是学生。你最好有充分的理由来解释为什么要妨碍我上课。', 28153),
(154515, 'zhCN', '<达雷尔似乎没有意识到你的存在。>', '<达雷尔似乎没有意识到你的存在。>', 28153),
(154514, 'zhCN', '妨碍别人是很无礼的行为，外来者。', '妨碍别人是很无礼的行为，外来者。', 28153),
(154513, 'zhCN', '乍看之下，好像没有什么线索告诉我侏儒同胞去哪儿了。让我仔细研究一下你收集的信息，如果有头绪了再联络你。', '', 28153),
(154512, 'zhCN', '|cFF0000FF(任务)|r启航前往斯托颂谷地。', '|cFF0000FF(任务)|r启航前往斯托颂谷地。', 28153),
(154511, 'zhCN', '警报！警报！入侵警报！入侵警报！', '', 28153),
(154510, 'zhCN', '', '接受这份礼物吧……我们部族的传统盔甲。把它作为我们家乡的纪念，骄傲地穿上吧。Dranosh\'ek mag\'har！', 28153),
(154509, 'zhCN', '', '你抵御强敌，守护部落，为玛格汉带来了荣耀。', 28153),
(154508, 'zhCN', '', '回奥格瑞玛来，我要嘉奖你对我们部族的贡献。', 28153),
(154507, 'zhCN', '', '你在艾泽拉斯经历了无数战斗。无论是盟友还是敌人，玛格汉的威名都如雷贯耳！', 28153),
(154506, 'zhCN', '', '不论你身在何处，别忘了，你胸膛里跳动的是德拉诺之心。Lok-tar ogar！', 28153),
(154505, 'zhCN', '', '你的每次胜利，都是在向艾泽拉斯的人民证明，我们是战争的主宰！', 28153),
(154504, 'zhCN', '', '如今部落需要我们的力量对抗联盟，我们便响应了这份号召。', 28153),
(154503, 'zhCN', '', '我们的人民在格罗玛什·地狱咆哮的领导下团结了起来，同属一个部族：玛格汉。', 28153),
(154502, 'zhCN', '', '几年前，这个世界的英雄前往德拉诺，与我们并肩作战，抗击燃烧军团。', 28153),
(154501, 'zhCN', '', '亲爱的洛坎，赞达拉巨魔对暗矛部族的协助天经地义。我将尽我所能帮助你。', 28153),
(154500, 'zhCN', '我需要借用一下这位勇士。我的宿敌不知怎么的从邦桑迪手里逃脱了，现在正在威胁我的家园。', '', 28153),
(154499, 'zhCN', '我准备好了，开始你的仪式吧。', '我准备好了，开始你的仪式吧。', 28153),
(154498, 'zhCN', '', '这里一定有人知道些什么。一整只舰队不可能凭空消失！', 28153),
(154497, 'zhCN', '相反，我们应该……向部落敞开港口？', '', 28153),
(154496, 'zhCN', '我们不可以把自己交给艾什凡……', '', 28153),
(154495, 'zhCN', '要我相信你吗，$r？把东西交出来。', '', 28153),
(154494, 'zhCN', '船长有令，长官。他已经决定拒绝加入艾什凡！', '船长有令，长官。他已经决定拒绝加入艾什凡！', 28153),
(154493, 'zhCN', '你到底是从哪里来的？你显然不是本地人。', '', 28153),
(154492, 'zhCN', '', '什么？让我看一下。', 28153),
(154491, 'zhCN', '船长又向你下达了新的命令，水手长。', '船长又向你下达了新的命令，水手长。', 28153),
(154490, 'zhCN', '', '不仅仅是将舰队带回来，而是让库尔提拉斯重归完整……或者用赛勒斯的话来说，是“治愈感染”。', 28153),
(154489, 'zhCN', '', '你是谁？你到底有什么事？', 28153),
(154488, 'zhCN', '', '他们还祝福每一艘库尔提拉斯舰船。这才是这里的船只与外来舰船的区别所在。', 28153),
(154487, 'zhCN', '', '我从来没有在一个地方看到过这么多艾泽里特。这既让我担忧，也让我高兴。', 28153),
(154486, 'zhCN', '', '一个纯净的艾泽里特元素，杀了它，勇士。但不要摧毁它，尽可能地的收集它的精华。', 28153),
(154485, 'zhCN', '', '这样应该够他们吃……一小会了。', 28153),
(154484, 'zhCN', '', '兽人是很好的士兵，但饭量是地精的十倍！我们需要补充食物库存。你介不介意在消灭卡多雷的时候，也带几头野兽回来？', 28153),
(154483, 'zhCN', '', '正如我常说的，在玫瑰长刺之前就把它砍掉。', 28153),
(154482, 'zhCN', '', '又一名卡多雷指挥官出现在了错误的时间和错误的地点。立刻送她上路，不能让她叫来援军。', 28153),
(154481, 'zhCN', '', '你的确是这个任务的绝佳人选，勇士。', 28153),
(154480, 'zhCN', '', '萨鲁法尔已经登上了黑海岸和费伍德森林之间的山地。在碎矛谷和他会合，保证他的通路安全。', 28153),
(154479, 'zhCN', '我们成功了，伙计们！海盗王泽姆兰死了，宝藏是我们的了！', '', 28153),
(154478, 'zhCN', '', '我从来没有怀疑过你的能力。', 28153),
(154477, 'zhCN', '', '卡多雷似乎召集了援军，也许这是场严峻的挑战，但我期待你凯旋归来。', 28153),
(154476, 'zhCN', '', '你的战斗充满了技巧与勇猛。所有士兵都受到了你的鼓舞，勇士。', 28153),
(154475, 'zhCN', '', '联盟正彻底搜查黑海岸，想要根除我们的据点。我们必须坚守阵地！守住据点！', 28153),
(154474, 'zhCN', '', '在战争中不是你死，就是我亡。没什么好说的。', 28153),
(154473, 'zhCN', '', '不要手软，英雄！这些野蛮的精灵是不会对你仁慈的。', 28153),
(154472, 'zhCN', '', '我们对他们的后备部队造成了严重的打击，干得漂亮。', 28153),
(154471, 'zhCN', '', '卡多雷在夜间会更危险。加入战斗，在天黑之前解决他们！', 28153),
(154470, 'zhCN', '', '你果然没有辜负我对你的信任。卡多雷的意志必将粉碎。', 28153),
(154469, 'zhCN', '', '我们的部队正紧逼着玛法里奥的军队！趁我们还有优势，必须把阵线推进到黑海岸！', 28153),
(154468, 'zhCN', '', '可怜的小家伙……她根本就没有还手的机会。', 28153),
(154467, 'zhCN', '', '那名暗夜精灵指挥官在挑战我的耐心。干掉她。', 28153),
(154466, 'zhCN', '', '想像一下，沉睡了千万年，一觉醒来却发现自己被打败了。真可悲！', 28153),
(154465, 'zhCN', '', '所以这些古树也蠢蠢欲动了，是吗？那我们就粗暴地唤醒它们吧。', 28153),
(154464, 'zhCN', '我想现在的情况已属万幸。千万不能让它的脂液落到部落手上。', '', 28153),
(154463, 'zhCN', '', '一个纯粹由艾泽里特构成的元素生物！我不知道它有多强，勇士……还请务必小心。', 28153),
(154462, 'zhCN', '暗夜精灵肯定会寸步不让地抵挡我们的攻击。', '暗夜精灵肯定会寸步不让地抵挡我们的攻击。', 28153),
(154461, 'zhCN', '', '你以前使用过艾泽里特炸弹吗？想不想见识一下真正的力量？做好心理准备吧，勇士。我相信它会给你带来惊喜。', 28153),
(154460, 'zhCN', '多棒的标本啊！我已经为这只生物设想了各种各样的炼金用途。', '', 28153),
(154459, 'zhCN', '对于新人来说，大惊小怪很正常。别担心，这能让人更坚强！', '', 28153),
(154458, 'zhCN', '', '我们的占领行动会招致卡多雷的反抗……除非我们摧垮他们的精神。\n\n我们必须打出关键一击，让他们明白事态的严重性。他们得失去某样东西……某个人……某个他们无条件信任的人，某个希望的象征。\n\n<黑暗女王皱了皱眉。>\n\n玛法里奥·怒风必须死。', 28153),
(154457, 'zhCN', '渔夫报告说水里有某种奇怪的巨大生物。取一份样本进行研究应该有所帮助。', '', 28153),
(154456, 'zhCN', '', '联盟想要用攻城武器对付我们？真是好笑。让他们见识一下部落的厉害。', 28153),
(154455, 'zhCN', '由于现在铁矿短缺，即使训练用的物品也不能被浪费。我们的海军发现了一个回收资源的完美办法。', '', 28153),
(154454, 'zhCN', '', '这些废墟中富含自然资源……就等我们收入囊中！不要让卡多雷妨碍我们，勇士。', 28153),
(154453, 'zhCN', '', '有一些驭风者可以为我们所用。去收集炸药，然后破坏那堵小精灵之墙。这将向玛法里奥传递一个信号。', 28153),
(154452, 'zhCN', '', '射得真准，英雄！我真为跑去捡炮弹的家伙感到难过。', 28153),
(154451, 'zhCN', '有个风险投资公司的萨满正在控制艾泽里特元素！顺手牵羊的地精草包配不上这种力量。碾碎她！', '', 28153),
(154450, 'zhCN', '', '听上去像是有人在训练区域练习射击。我敢打赌，你一定能让其他学员长长见识，让他们看看该怎么开炮。', 28153),
(154449, 'zhCN', '', '你取回的武器对我们的接下来的战事很有帮助，干得很好。', 28153),
(154448, 'zhCN', '', '无论如何，我们比以往任何时候，都需要海潮贤者的帮助……', 28153),
(154447, 'zhCN', '干得好！你让好几个押你的人大赚了一笔。包括我。', '', 28153),
(154446, 'zhCN', '', '现在没人知道，舰队为什么仍然迟迟未归。', 28153),
(154445, 'zhCN', '', '人们都说海潮贤者已经丧失了他们的魔法，我却认为他们和艾什凡家族一样，正在谋夺力量。', 28153),
(154444, 'zhCN', '', '那批货物属于部落！不能让它落到联盟手中！', 28153),
(154443, 'zhCN', '破浪海盗时不时会举行海盗决斗比赛，任何人都可以参赛。', '', 28153),
(154442, 'zhCN', '', '即使经历了如此多的训练，我的黑暗游侠还是误判了进攻形势。或许应该让凋零者和他们谈一谈……', 28153),
(154441, 'zhCN', '', '大型舰船上总会有一名海潮贤者为我们指引航向，驾驭波涛，并保佑我们一帆风顺。', 28153),
(154440, 'zhCN', '', '我的黑暗游侠需要你的帮助，英雄。找到并支援他们！', 28153),
(154439, 'zhCN', '', '勇士，其他地方需要你。我有一支地精小队已经准备好扫除残余的目标。', 28153),
(154438, 'zhCN', '说实在话……就算把这颗星球的生命之血喂给食人魔，难道他就能稍微变得聪明吗？！我是说……根本不可能，对吧？所以，我们直接把他做掉好了？', '', 28153),
(154437, 'zhCN', '太了不起了！这一定能抓人眼球！', '', 28153),
(154436, 'zhCN', '', '我们的艾泽里特火药桶掉下船了！在它们沉下去之前，赶紧收集起来！', 28153),
(154435, 'zhCN', '你上次带来的照片已经用完了。要是你正好有空，就再去多拍几张。', '', 28153),
(154434, 'zhCN', '', '我们的营地暂时安全了，但千万别放松警惕。', 28153),
(154433, 'zhCN', '风险投资公司的首席武器研究员就在这里！我们一直以来都在想方设法逮住他。替我好好揍他一顿！', '', 28153),
(154432, 'zhCN', '', '真希望你也能看看那些舰队。我认为即使像你这么见多识广的人，也会惊叹！', 28153),
(154431, 'zhCN', '啊，伯拉勒斯！这座光彩夺目的城市到处都是非法帮派和争论不休的贵族。你知道，诺莫瑞根从来没有这些问题。', '', 28153),
(154430, 'zhCN', '我决定在广告里再加几个当地景点。就从这座城市开始吧。', '', 28153),
(154429, 'zhCN', '', '联盟的破坏者渗透了我们的据点！把他们赶出去！让他们付出代价！', 28153),
(154428, 'zhCN', '', '不管怎么说，是时候去坐船瞧瞧了。', 28153),
(154427, 'zhCN', '我的首席武器研究员花了一整个发薪日为风险投资公司干活。他追求金钱无可厚非，但可惜你还是得替我杀了他，你会这么做的吧？', '', 28153),
(154426, 'zhCN', '太美了！你知道欣赏照片的优点是什么吗，就是不会闻到马尿味。', '', 28153),
(154425, 'zhCN', '诺文顿勋爵希望他宏伟的庄园能刊登在下期沸泉传单的显著位置。当然，我，非常乐意效劳。', '', 28153),
(154424, 'zhCN', '风险投资公司正给他们的食人魔喂食艾泽里特，认为这样能让他们更聪明些。虽然只是痴人说梦，但是……你还是应该去处理一下。以防万一嘛。', '', 28153),
(154423, 'zhCN', '', '月亮井的精华应该对你的战斗大有帮助。以后一定要让卡多雷再也接触不到他们神圣的井水。', 28153),
(154422, 'zhCN', '', '卡多雷使用月亮井来补充他们在战斗中失去的力量。尽量吸收月亮井的能量，然后……让卡多雷再也没法使用。明白了吗？', 28153),
(154421, 'zhCN', '真及时！要是再晚一点，我身为度假区主人的名誉可就要受损了。', '', 28153),
(154420, 'zhCN', '在外面要小心，泰莉亚。我完全不相信那些戴兜帽的祭司。', '', 28153),
(154419, 'zhCN', '听说有种元素全身都是艾泽里特，风险投资公司研究出了驯化的方法。我们得阻止研究。我说的“我们”指的就是你。', '', 28153),
(154418, 'zhCN', '', '我会命令附魔师向月亮石里注入艾泽里特，它们的力量将为部落所用！', 28153),
(154417, 'zhCN', '', '卡多雷可以从月亮石制成的吊坠中吸取能量。用一切你能想到的手段，让他们无法再使用这些小玩意。', 28153),
(154416, 'zhCN', '', '非常好，勇士。这些艾泽里特会给我们的事业添砖加瓦。', 28153),
(154415, 'zhCN', '', '艾泽里特已经在黑海岸的废墟中出现，就连残渣都不要留给联盟！', 28153),
(154414, 'zhCN', '', '这正是我要传达给玛法里奥的信息。干得很好。', 28153),
(154413, 'zhCN', '', '这些小精灵就像虫子一样，轻易就能捏碎。把它们的光芒逐个掐灭，很快黑暗便会笼罩整个天空。', 28153),
(154412, 'zhCN', '这简直是场灾难！泉水突然发疯了，它们在攻击我的客人！', '', 28153),
(154411, 'zhCN', '', '白痴！戈霍恩是不会失败的！你们的力量无济于事！', 28153),
(154410, 'zhCN', '', '有了这些，我们的大厨就能做出些美食了。谢谢你。', 28153),
(154409, 'zhCN', '', '我的德鲁伊朋友们，胃口比熊还大。补充军需是份脏活，但总得有人去做。你能帮忙吗？', 28153),
(154408, 'zhCN', '是时候拿工资了。随意射击！', '', 28153),
(154407, 'zhCN', '哈哈！干得好。', '哈哈！干得好。', 28153),
(154406, 'zhCN', '没素质。', '没素质。', 28153),
(154405, 'zhCN', '你为什么要那么做？', '你为什么要那么做？', 28153),
(154404, 'zhCN', '洛阿神灵在上，你到底在做什么？', '洛阿神灵在上，你到底在做什么？', 28153),
(154403, 'zhCN', '干掉那个！', '干掉那个！', 28153),
(154402, 'zhCN', '让开！把大炮端出来！', '', 28153),
(154401, 'zhCN', '这就是第八块，可以凑成一枚金币了，有钱人！', '', 28153),
(154400, 'zhCN', '海盗习惯把自己的金币分成八块。如果你把八块都找到了，那你一定是运气爆棚！自由镇上应该还散落着好多财宝。', '', 28153),
(154399, 'zhCN', '那玩意就是欠揍。现在谁想来点烤鱿鱼啊？哈哈。', '', 28153),
(154398, 'zhCN', '有只巨型水母在自由镇的水里安了家，不管拿鱼叉戳它多少次，它总会重新冒出来！', '', 28153),
(154397, 'zhCN', '你消灭了恐怖船长范迪格林，让他的灵魂安息了！想想你解除了多少财宝的诅咒！', '', 28153),
(154396, 'zhCN', '各大海岸上，范迪格林船长的名字都让人闻风丧胆。据说他的贪欲太强，死后还能从坟墓里爬出来继续抢劫。', '', 28153),
(154395, 'zhCN', 'Iggksh ywaq ag\'rr ni ky！', '', 28153),
(154394, 'zhCN', 'Ah\'shel ywaq qam yrr woth\'gl！', '', 28153),
(154393, 'zhCN', '这就是第八块，可以凑成一枚金币了，这下我们发达了！', '', 28153),
(154392, 'zhCN', 'Za ag\'rr wgah thyzz zuq！', '', 28153),
(154391, 'zhCN', '海盗习惯把自己的金币分成八块。如果你把八块都找到了，那你一定是运气爆棚！自由镇上应该还散落着不少财宝。', '', 28153),
(154390, 'zhCN', '那玩意儿就是欠揍。有谁想吃烤鱿鱼吗？', '', 28153),
(154389, 'zhCN', '有只巨型水母在自由镇的水里安了家，不管它身上被戳进了多少支鱼叉，它总会重新冒出来！', '', 28153),
(154388, 'zhCN', 'Ga ag\'rr ez AN\'zig wgha kyth zuq！', '', 28153),
(154387, 'zhCN', '你消灭了恐怖船长范迪格林，让他的灵魂得以安息！想想你解除了多少财宝的诅咒！', '', 28153),
(154386, 'zhCN', '各大海岸上，范迪格林船长的名字都让人闻风丧胆。据说他的贪欲太强，死亡也无法阻止他继续抢劫。', '', 28153),
(154385, 'zhCN', '等等……这……不是我应有的未来……', '', 28153),
(154384, 'zhCN', '戈霍恩的血液在我体内流淌！在我的力量面前战栗吧！', '', 28153),
(154383, 'zhCN', '我目睹的那些……', '没想到你心肠这么好。', 28153),
(154382, 'zhCN', '我的力量会击垮你！', '', 28153),
(154381, 'zhCN', '谢谢你，我都快坚持不下去了。', '谢谢你。我不会回头的。', 28153),
(154380, 'zhCN', '戈霍恩的力量会成为你的末日！', '', 28153),
(154379, 'zhCN', '见证你的末日，感受绝望吧！', '', 28153),
(154378, 'zhCN', '复活吧，我的选民！我们会用鲜血征服一切！', '', 28153),
(154377, 'zhCN', '从我的鲜血中崛起，碾碎弱者！', '', 28153),
(154376, 'zhCN', '来吧，兄弟们！吞噬这些无信者！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154375, 'zhCN', '把你的鲜血还给我！', '', 28153),
(154374, 'zhCN', '戈霍恩！接受这鲜血的供奉吧！', '', 28153),
(154373, 'zhCN', '你从来没有过未来。', '', 28153),
(154372, 'zhCN', '如我所料。软弱不堪。', '', 28153),
(154371, 'zhCN', '一切都和我所预见的一样！', '', 28153),
(154370, 'zhCN', '过来，白痴们！我已经看到了你们的结局。', '', 28153),
(154369, 'zhCN', '在我还很小的时候，我的母亲就去世了，我的父亲一手把我带大。他曾是一名水手，每次他出海的时候都会给我留下一束海潮茎干的花。', '在我还很小的时候，我的母亲就去世了，我的父亲一手把我带大。他曾是一名水手，每次他出海的时候都会给我留下一束海潮茎干的花。', 28153),
(154368, 'zhCN', '', '警报。黑暗投影正在具象化。', 28153),
(154367, 'zhCN', '', '警报。虚空抑制保险装置被突破。', 28153),
(154366, 'zhCN', '', '真是高尚的举动，英雄。', 28153),
(154365, 'zhCN', '', '警报。侦测到危险级别的虚空能量。', 28153),
(154363, 'zhCN', '', '警告。正在复制额外的蛛魔。', 28153),
(154362, 'zhCN', '万物重归平衡。Anu\'dorini talah!', '', 28153),
(154361, 'zhCN', '有敌人潜伏在阴影中，英雄。但艾露恩的神圣月光会让他们无所遁形。解决他们。', '', 28153),
(154360, 'zhCN', '', '警告。正在复制额外的异种蝎。', 28153),
(154359, 'zhCN', '啊！可恶！海潮茎干对我来说意味着那些没法回家的好水手，还有沉在海底的货物。', '啊！可恶！海潮茎干对我来说意味着那些没法回家的好水手，还有沉在海底的货物。', 28153),
(154358, 'zhCN', '', '米斯拉克斯不应该存在于这个世界。', 28153),
(154357, 'zhCN', '', '艾露恩赞美你，英雄。你闪耀着星辰的光辉。', 28153),
(154356, 'zhCN', '', '我的弓箭手需要你的帮助，勇士。你遇见他们的话，就帮他们一把吧！', 28153),
(154355, 'zhCN', '', '这场战争必须结束。', 28153),
(154354, 'zhCN', '', '我将关注你的一举一动。', 28153),
(154353, 'zhCN', '', '读取完成。圆盘关闭。', 28153),
(154352, 'zhCN', '', '你清除了威胁，还把攻城武器完好无损地送了回来，理应获得双倍的赞美。', 28153),
(154351, 'zhCN', '', '必须恢复秩序。', 28153),
(154350, 'zhCN', '', '我们都有自己的一席之地。而我的在这儿。', 28153),
(154349, 'zhCN', '', '我很虚弱，但我确实在此。', 28153),
(154348, 'zhCN', '', '之前有经验吗？抓紧了，你会吓一跳的。', 28153),
(154347, 'zhCN', '', '检索圆盘成功。正在读取损坏数据。', 28153),
(154346, 'zhCN', '我会尽量多派遣一些士兵来这里，希望他们能击退这次进攻。我们可没办法双线作战。', '', 28153),
(154345, 'zhCN', '我感觉北面出现了骚乱。怎么回事？难道是部落翻山越岭来攻打我们吗？快去看看！', '', 28153),
(154344, 'zhCN', '', '你怎么黑乎乎的，英雄？哪里不舒服吗？', 28153),
(154343, 'zhCN', '', '即使是在水下，这些艾泽里特火药桶还是很危险。我希望你在它们浮出水面前把它们引爆。当心别把你自己炸了，好吗？', 28153),
(154342, 'zhCN', '', '数据矩阵过载。多个圆盘被检索。', 28153),
(154341, 'zhCN', '海潮茎杆吗？我的一些船员会在出海之前为自己的爱人准备一根。比起让自己的另一半惴惴不安，他们更希望家人知道自己的情况，我能理解他们。', '海潮茎杆吗？我的一些船员会在出海之前为自己的爱人准备一根。比起让自己的另一半惴惴不安，他们更希望家人知道自己的情况，我能理解他们。', 28153),
(154340, 'zhCN', '', '我从没怀疑过你的能力。', 28153),
(154339, 'zhCN', '', '部落大军人数众多，而且实力不容小觑。尤其是这家伙，非常……顽强。小心点，英雄。', 28153),
(154338, 'zhCN', '', '检索圆盘成功。正在读取尤格-萨隆数据。', 28153),
(154337, 'zhCN', '', '检索圆盘成功。正在读取克苏恩数据。', 28153),
(154335, 'zhCN', '', '部落的捣乱分子混进入了我们的部队！把他们揪出来！让他们感受一下我们的痛苦！', 28153),
(154334, 'zhCN', '', '不得不说，那真是漂亮的进攻，英雄。连哨兵都得和你学两招。', 28153),
(154333, 'zhCN', '', '是时候以眼还眼了！我们必须摧毁部落的攻城车，把他们赶回那片名副其实的贫瘠之地！', 28153),
(154332, 'zhCN', '', '艾露恩向你微笑，英雄。我也一样。', 28153),
(154331, 'zhCN', '', '部落想从我们的月亮井里盗取精华！千万不能让他们玷污我们神圣的泉水！', 28153),
(154330, 'zhCN', '', '让部落的恶魔滚回他们的荒原去。教教他们什么叫远离我们的森林。', 28153),
(154329, 'zhCN', '', '部落在灰谷境外建立了一个据点。集结那些守卫森林的德鲁伊！', 28153),
(154328, 'zhCN', '', '干得漂亮，英雄。很有激情……', 28153),
(154327, 'zhCN', '', '部落的士兵正在窃取我们的资源！在他们耗尽我们神圣的森林之前阻止他们。', 28153),
(154326, 'zhCN', '', '数千年的死亡并未让他们变得迟钝。你战胜了他们，干得好。', 28153),
(154325, 'zhCN', '', '那是……那是达萨大王的首席卫士！他们可不会轻易落败！', 28153),
(154324, 'zhCN', '哈！看来你让那些不死怪物死透了！干得漂亮。', '', 28153),
(154323, 'zhCN', '那些不死巨魔看上去比其他巨魔更厉害。当心！', '', 28153),
(154322, 'zhCN', '关于这根海潮茎杆，你能告诉我什么？', '关于这根海潮茎杆，你能告诉我什么？', 28153),
(154321, 'zhCN', '', '有这些就足够了，英雄。你今天的贡献不会被遗忘。', 28153),
(154320, 'zhCN', '', '部落已经有艾泽里特武器了。干脆我们也抢点过来吧？', 28153),
(154319, 'zhCN', '……岩石大厅不算。', '', 28153),
(154318, 'zhCN', '呸。矮人的造物可不会像那样陷入混乱。', '', 28153),
(154317, 'zhCN', '', '干得漂亮！我会让我的炼金师把艾泽里特放在部落发现不了的地方。', 28153),
(154316, 'zhCN', '呸，又一个巨魔制造的劣质品。那魔像发疯了。好好给它点颜色瞧瞧！', '', 28153),
(154315, 'zhCN', '', '我们要在加卡泽之前找到丘瓦巴。', 28153),
(154314, 'zhCN', '', '祖尔的黑暗魔法腐蚀了这名守卫。抚平它的怒火，我们才能修好它。', 28153),
(154313, 'zhCN', '', '祖尔……你对这片神圣之地的所作所为无法被宽恕。', 28153),
(154312, 'zhCN', '', '永别了，哈鲁。安息吧。', 28153),
(154311, 'zhCN', '', '啊，武器大师哈鲁……他曾是我父亲的导师，还有我的祖父。他的职责已尽。让他迷茫的灵魂安息吧。', 28153),
(154310, 'zhCN', '哈！看来你让他知道了谁才是真正的武器大师！', '', 28153),
(154309, 'zhCN', '一名曾经训练过赞达拉王室的战士依然在这座坟墓里徘徊。让他安息吧！', '', 28153),
(154308, 'zhCN', '', '我的弓箭手应该能把剩下的敌人清理干净。你的出现改变了战局，勇士。非常感谢。', 28153),
(154307, 'zhCN', '', '敌人的军队正在从北面袭击我们。现在该由我们发起进攻了，勇士。', 28153),
(154306, 'zhCN', '让他们通过！', '', 28153),
(154305, 'zhCN', '', '就快要好了！我能听到阿昆达的声音进入了我的脑海。', 28153),
(154304, 'zhCN', '', '我会尽全力修复阿昆达的意志，但你也必须做好准备，遏制可能被唤醒的任何记忆。', 28153),
(154303, 'zhCN', 'Ywaq ongg an\'qov i lal halahs nuq.', '', 28153),
(154302, 'zhCN', 'Ywaq mh\'naus wgah zaix zyqtahg.', '', 28153),
(154301, 'zhCN', '莫加波会让……你血债血偿……', '', 28153),
(154300, 'zhCN', '', '我……我在哪？我在这里做什么？', 28153),
(154299, 'zhCN', 'Oou thyzz lal ak\'uq qwaz Zuq shkul ma sk\'tek...', '', 28153),
(154298, 'zhCN', '', '他们虽然神秘，但对库尔提拉斯来说却十分重要。他们为海岸的人民带来渔获，为谷地的田野降下雨水。', 28153),
(154297, 'zhCN', '', '这里的多数人寻求大海的指引，就如同我们寻求圣光一样，然而海潮贤者们与大海有着更深刻的联系。', 28153),
(154296, 'zhCN', '', '一般我会让狂风之心载你一起去。然而海潮贤者们只允许访客坐船前往。', 28153),
(154295, 'zhCN', '', '我没事，赛勒斯。我能保护自己。更何况，我身边还有联盟特使在呢！', 28153),
(154294, 'zhCN', 'Oou yyqzz ez thyzz phquathi zuq！', '', 28153),
(154293, 'zhCN', 'Oou gul\'kafh lal lwhuk！', '', 28153),
(154292, 'zhCN', 'Qam oou iilth ez i awtgsshu amun on\'ma!', '', 28153),
(154291, 'zhCN', 'Log\'loth w\'oq Ongg!', '', 28153),
(154290, 'zhCN', '', '艾泽里特出现在了黑海岸的废墟里。不能让部落抢了！', 28153),
(154289, 'zhCN', 'W\'oq uhn\'agth ez qam Shandai!', '', 28153),
(154288, 'zhCN', 'Awtgssh shn ongg shg\'ullwaq!', '', 28153),
(154287, 'zhCN', 'Zuq ag\'xig bormaz ag\'thyzak!', '', 28153),
(154286, 'zhCN', '谢谢你！', '谢谢你！', 28153),
(154285, 'zhCN', 'Za qualar ag\'xig za al\'tha!', '', 28153),
(154284, 'zhCN', '这么点报酬可不够！', '这么点报酬可不够！', 28153),
(154283, 'zhCN', '啊啊啊啊啊啊啊！', '啊啊啊啊啊啊啊！', 28153),
(154282, 'zhCN', '感谢救命之恩！', '感谢救命之恩！', 28153),
(154281, 'zhCN', '我还以为自己肯定会被做成香肠呢！', '我还以为自己肯定会被做成香肠呢！', 28153),
(154280, 'zhCN', 'Oou vwahuHn ag\'xig shfk zuq!', '', 28153),
(154279, 'zhCN', '谢谢，朋友们！', '谢谢，朋友们！', 28153),
(154278, 'zhCN', 'I ongg za ywaq qvsakf.', '', 28153),
(154277, 'zhCN', 'Vwah oou kaaxth zz ywaq iiyoq Ag\'xlg fhssh I on\'ma.', '', 28153),
(154276, 'zhCN', 'Za awtgsshu wgah uulg\'ma ywaq zaix.', '', 28153),
(154275, 'zhCN', 'Qam oou uhnish kyth zuq Ongg za fhssh as\'rr.', '', 28153),
(154274, 'zhCN', 'Ywaq zuq ywag shn\'ma Bo\'al za qwor.', '', 28153),
(154273, 'zhCN', 'Oou qam puul zyqtahg ywaq vorzz Qam ma shn\'ma.', '', 28153),
(154272, 'zhCN', 'Oou shath\'yar lwhuk shn\'ma yrr shandi agth fhssh.', '', 28153),
(154271, 'zhCN', '只有当灵魂平静下来，森林才能得到平静。谢谢你的帮助。', '', 28153),
(154270, 'zhCN', '这些灵魂现在只不过是他们过往的躯壳。用你的抚触温暖它们，勇士，让它们平静下来。', '', 28153),
(154269, 'zhCN', '他们管我叫妖术领主可是有原因的。', '', 28153),
(154268, 'zhCN', '拿上我的妖术杖，去把这些祭司变成更好玩的东西。', '', 28153),
(154267, 'zhCN', '你要是觉得这都算严厉的话，那你真该去看看其他洛阿神灵的追随者是什么样的。', '', 28153),
(154266, 'zhCN', '如果我们不能阻止这种腐蚀，还有谁能？', '如果我们不能阻止这种腐蚀，还有谁能？', 28153),
(154265, 'zhCN', '贡克的德鲁伊太严肃了。去他们的祭坛搞点恶作剧，活跃一下气氛。不过小心别被干掉。', '', 28153),
(154264, 'zhCN', '如果这种腐蚀扩散开来……艾泽拉斯注定毁灭。', '如果这种腐蚀扩散开来……艾泽拉斯注定毁灭。', 28153),
(154263, 'zhCN', '自然发出痛苦的哀鸣……我们如何能够阻止这场疯狂？', '自然发出痛苦的哀鸣……我们如何能够阻止这场疯狂？', 28153),
(154262, 'zhCN', '我们的力量没有产生任何影响……我们如何能够治愈这颗星球？', '我们的力量没有产生任何影响……我们如何能够治愈这颗星球？', 28153),
(154261, 'zhCN', '', '真刺激！干得漂亮，你俩都是。', 28153),
(154260, 'zhCN', '', '我们的灵龙不太习惯背着鞍具，所以旅途颠簸，敬请体谅。骑上去，指引它们攻击的方向。', 28153),
(154259, 'zhCN', '你们的恐惧就是我的食粮！', '', 28153),
(154258, 'zhCN', '铁炉堡的援军！向敌方基地进军！', '', 28153),
(154257, 'zhCN', '踏平阿戈罗克，为了阿拉索！为了激流堡！为了联盟！', '', 28153),
(154256, 'zhCN', '', '你战斗时就像一名传奇的赞达拉巨魔。令人印象深刻。', 28153),
(154255, 'zhCN', '', '你在不断证明你的价值。做得好。', 28153),
(154252, 'zhCN', '', '多亏了你，我们双方的人民都安全了。', 28153),
(154251, 'zhCN', '', '那名敌人死了，我们的努力不会白费。', 28153),
(154246, 'zhCN', '', '往前应该就是隐蔽基地了。那里很安全……至少目前是安全的。', 28153),
(154245, 'zhCN', '', '希望这是我最后一次听到那家伙的消息。', 28153),
(154244, 'zhCN', '', '神灵预言了你的胜利。我很高兴他们没有弄错。', 28153),
(154243, 'zhCN', '', '你的部落同胞知道你解决了这一威胁会很高兴的。', 28153),
(154242, 'zhCN', '', '我就知道那家伙根本不是你的对手。', 28153),
(154240, 'zhCN', '觉得身体已经不听使唤了吗？因为我已经腐化了你们。', '', 28153),
(154239, 'zhCN', '', '我收到消息说附近有一名强大的敌人想要你的命。那就不要手下留情。', 28153),
(154238, 'zhCN', '', '部落的战士们说你附近有一个麻烦的敌人。干掉它，减轻部落的负担。', 28153),
(154237, 'zhCN', '', '你们的部落斥候报告说附近有一名强大的敌人。我同意他们对处理此事的提议：马上杀了它。', 28153),
(154234, 'zhCN', '纳兹米尔的这些野蛮人似乎无穷无尽。感谢你把他们剔除了一部分。', '', 28153),
(154232, 'zhCN', '哈！你真是天生的滑雪高手！我很久没见过像你一样驾轻就熟的了！', '', 28153),
(154230, 'zhCN', '鲜血巨魔冲向了我们的大门。骑着三角战龙去和这些野蛮人作战吧。', '', 28153),
(154228, 'zhCN', '今天没什么工作。大多蛮项人为了活动下筋骨，都去滑雪了。你也找只企鹅开滑吧！', '', 28153),
(154225, 'zhCN', '', '小心。你附近有一名危险的敌人。我们得在它造成更多的麻烦前干掉它。', 28153),
(154224, 'zhCN', '艾露恩赞美你的壮举，英雄。', '', 28153),
(154223, 'zhCN', '', '洛阿神灵传来低语，说附近有一名强大的敌人。神灵要求将它从艾泽拉斯上彻底清除。', 28153),
(154222, 'zhCN', '女妖之王发动了残酷无情的进攻。净化这片森林，驱走她的黑暗气息！', '', 28153),
(154221, 'zhCN', '', '我的斥候们报告说附近有一名可怕的敌人。无论那是什么，在它成为真正的威胁前干掉它。', 28153),
(154220, 'zhCN', '我的军队准备好从这里接手了。感谢你为他们争取到了时间。', '', 28153),
(154219, 'zhCN', '', '警惕点，我感觉到某种不祥的存在。在它干掉你之前解决掉它！', 28153),
(154218, 'zhCN', '威胁暂时缓解了，古树们再次获得了宁静。', '', 28153),
(154217, 'zhCN', '', '这里有一个致命的敌人。在它伤害我们的盟友之前干掉它。', 28153),
(154216, 'zhCN', '非赞达拉巨魔者，格杀勿论！', '', 28153),
(154215, 'zhCN', '部落的威胁惊动了古树。把这些恶棍赶走，这样我们的森林才有可能回归平静。', '', 28153),
(154213, 'zhCN', '你今天的义举给予了我们喘息的宝贵机会。', '', 28153),
(154212, 'zhCN', '随着部落向我们的腹地进军，这片伟大的森林也在痛苦中轰然倒下。我们不能再让他们前进一步了！', '', 28153),
(154211, 'zhCN', '出门在外要当心点。', '出门在外要当心。', 28153),
(154210, 'zhCN', '沙漠会吞噬弱者。', '沙漠会吞噬弱者。', 28153),
(154209, 'zhCN', '不要轻易相信他人。', '在外面要当心你的背后。', 28153),
(154208, 'zhCN', '没人应该受到这种折磨。', '没人应该受到这种折磨。', 28153),
(154207, 'zhCN', '你需要什么吗？', '这里欢迎每一个人。', 28153),
(154205, 'zhCN', '你好，伙计。', '你好，伙计。', 28153),
(154204, 'zhCN', '', '我仍能听见您的声音……主人……', 28153),
(154203, 'zhCN', '我的低语会瓦解你们的意志。', '', 28153),
(154202, 'zhCN', '让饥饿吞噬你。吸收他们的血液吧。', '', 28153),
(154201, 'zhCN', '快去找你的同伴。散播我的礼物吧。', '', 28153),
(154200, 'zhCN', '干得漂亮。现在快去，铲除剩下的无信者！', '', 28153),
(154199, 'zhCN', '腐化会传遍你的每一根血管。让它传播。', '', 28153),
(154198, 'zhCN', '从无信者巫师身上抢一个这种装置来，将能量充满，我会奖励你的。', '', 28153),
(154197, 'zhCN', '我们的巫师在神庙里探测到某种不同寻常的强大电流。', '', 28153),
(154196, 'zhCN', '让千喉之宴开始吧！', '', 28153),
(154195, 'zhCN', '干得漂亮！现在去找塞塔里斯之心吧。', '', 28153),
(154194, 'zhCN', '帮我把圣物带来，我会好好犒赏你的。', '', 28153),
(154193, 'zhCN', '孩子们，过来吞噬吧！', '', 28153),
(154192, 'zhCN', '我知道无信者会把好些圣物藏在神庙中心前的集市上。', '', 28153),
(154191, 'zhCN', '来吧，腐化的仆人们。吞噬！', '', 28153),
(154190, 'zhCN', '完美的样本！现在快去，干掉神庙的无信者渣滓。', '', 28153),
(154189, 'zhCN', '我听说有一批品种奇特的三叶虫在神庙里筑了巢。你去帮我带只幼虫来，我会好好奖赏你。', '', 28153),
(154188, 'zhCN', '没有什么能够阻止我的瘟疫！', '', 28153),
(154187, 'zhCN', '我的腐化无法清除！', '', 28153),
(154186, 'zhCN', '泰坦也拯救不了你们！', '', 28153),
(154185, 'zhCN', '你们谁也逃脱不了被感染的命运！', '', 28153),
(154184, 'zhCN', '封印已经解除，末日已经降临。来吧，成为第一个接受我馈赠的人。', '', 28153),
(154183, 'zhCN', '工人们非常感激你挺身相救，你让他们得以脱险。', '', 28153),
(154182, 'zhCN', '你们的腐化……已经深入骨髓……', '', 28153),
(154181, 'zhCN', '女巫再次侵袭了屠夫港。快救救那些工人，别让他们被做成香肠！', '', 28153),
(154180, 'zhCN', '', '先祖的灵魂得以安息，而德鲁斯特也化为碎片。你做得很好。', 28153),
(154179, 'zhCN', '', '这场永无休止的战斗威胁着阿罗姆之台的难民。削减敌人的数量！', 28153),
(154178, 'zhCN', '召唤风暴吧, $n。推翻这个篡夺者!', '', 28153),
(154177, 'zhCN', '你很好地运用了我的力量，$n。', '', 28153),
(154176, 'zhCN', '我亲爱的孩子。终于，你能听到我的话语了。有一个叛徒就潜藏于我们神殿之中。', '', 28153),
(154175, 'zhCN', '', '一只异常扭曲的生物威胁着我的同胞，审判官。消灭它。', 28153),
(154174, 'zhCN', '', '女巫在这片区域中释放了一只强大的生物。消灭它！', 28153),
(154173, 'zhCN', '', '干得好！多亏了你，德鲁斯瓦的人民更安全了。', 28153),
(154172, 'zhCN', '', '干得漂亮，审判官！他们想重回德鲁斯瓦时可得三思了！', 28153),
(154171, 'zhCN', '终于，我自由了！谢谢，$p。', '', 28153),
(154170, 'zhCN', '', '斥候报告说附近潜伏着一个危险的敌人。把他干掉！', 28153),
(154169, 'zhCN', '', '这片地区有一个强大的敌人正在威胁我的人民。消灭那个威胁。', 28153),
(154168, 'zhCN', '我是怎么输的？', '', 28153),
(154167, 'zhCN', '', '我的人民由衷地感谢你。我们今晚都能睡得安稳一些了。', 28153),
(154166, 'zhCN', '', '德鲁斯瓦人民对你的帮助心怀感激。', 28153),
(154165, 'zhCN', '那可不明智。', '', 28153),
(154164, 'zhCN', '', '我们收到了此区域有敌人的报告。杀死他们。', 28153),
(154163, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t戈霍恩对你施放了|cFFFF0404|Hspell:272506|h[爆炸腐蚀]|h|r！', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t戈霍恩对你施放了|cFFFF0404|Hspell:272506|h[爆炸腐蚀]|h|r！', 28153),
(154162, 'zhCN', '最终，和平……', '', 28153),
(154161, 'zhCN', '', '一个危险的敌人正在威胁德鲁斯瓦的人民。去解决掉它！', 28153),
(154160, 'zhCN', '大海都杀不死我，你凭什么觉得自己可以？', '', 28153),
(154159, 'zhCN', '我会传播瘟疫，吞噬这个世界。', '', 28153),
(154158, 'zhCN', '我们需要一艘前往斯托颂修道院的渡船。', '我们需要一艘前往斯托颂修道院的渡船。', 28153),
(154157, 'zhCN', '你的躯壳现在属于新的主人。', '', 28153),
(154155, 'zhCN', '所有没说出口的话……', '', 28153),
(154154, 'zhCN', '我还能再战！', '', 28153),
(154153, 'zhCN', '你的惨叫将永远回荡！', '', 28153),
(154152, 'zhCN', '血肉诅咒会吞噬你们！', '', 28153),
(154151, 'zhCN', '爆发已经开始!', '', 28153),
(154150, 'zhCN', '', '你知道我别无选择，卡佳。使命高于一切。', 28153),
(154149, 'zhCN', '', '加卡泽是个叛徒，但大王不会在没有证据的情况下动手。', 28153),
(154148, 'zhCN', '看起来……我可以休息了……', '看起来……我可以休息了……', 28153),
(154147, 'zhCN', '我们警告过你了！', '我们警告过你了！', 28153),
(154146, 'zhCN', '', '去吧。看看你能发现什么吧。我绝不会离开莱克拉身边。', 28153),
(154145, 'zhCN', '你已经准备好聆听阿昆达的神谕，但只能单独聆听。当你做好准备，就前往祭坛祷告吧。', '', 28153),
(154144, 'zhCN', '在你被净化之后，阿昆达才会进入你的思维。', '', 28153),
(154143, 'zhCN', '我想要回到这个地方。', '我想要回到这个地方。', 28153),
(154142, 'zhCN', '达到最大等级。重新开始收集。', '', 28153),
(154141, 'zhCN', '<阿萨尔热情地向你问好。>', '<阿萨尔热情地向你问好。>', 28153),
(154140, 'zhCN', '<阿萨尔平静地向你问好。>', '<阿萨尔平静地向你问好。>', 28153),
(154139, 'zhCN', '排液程序进行中。进入待机模式。', '', 28153),
(154138, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t戈霍恩开始施放|cFFFF0404|Hspell:267700|h[戈霍恩的凝视]|h|r。', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t戈霍恩开始施放|cFFFF0404|Hspell:267700|h[戈霍恩的凝视]|h|r。', 28153),
(154133, 'zhCN', '准备摧毁样本。', '', 28153),
(154132, 'zhCN', '开始散播目标宿主血液。', '', 28153),
(154131, 'zhCN', '启动大槌回收。', '', 28153),
(154130, 'zhCN', '正在部署大槌。', '', 28153),
(154129, 'zhCN', '燃料耗尽。正在关闭……', '', 28153),
(154128, 'zhCN', '', 'Dranosh\'ek mag\'har！', 28153),
(154127, 'zhCN', '实验对象已准备好接受污染。', '', 28153),
(154126, 'zhCN', '', '战争席卷了这片土地。<大笑>不错！我们会在屠戮中狂欢……并夺取胜利！', 28153),
(154125, 'zhCN', '', '我们是一支骄傲氏族的最后幸存者。坚韧不拔、无法腐化的……玛格汉！', 28153),
(154124, 'zhCN', '', '对他人只是口号……对我们却是真理。', 28153),
(154123, 'zhCN', '', '力量与荣耀。鲜血与雷鸣。', 28153),
(154122, 'zhCN', '腐化能量又有来源了。', '', 28153),
(154121, 'zhCN', '新的腐化候选者。', '', 28153),
(154120, 'zhCN', '侦测到宿主。正在进行感染。', '', 28153),
(154119, 'zhCN', '', '我发誓，他们都是真实存在的。而且非常危险。就连蛇人都不敢踏足于峡谷之中。', 28153),
(154118, 'zhCN', '准备收集血浆。', '', 28153),
(154117, 'zhCN', '动作快点，懒鬼们！等你修好了才能拿到报酬！', '', 28153),
(154116, 'zhCN', '多么美丽的小岛……', '多么美丽的小岛……', 28153),
(154115, 'zhCN', '我死得光荣吗？', '我死得光荣吗？', 28153),
(154114, 'zhCN', '', '继续前进吧。莱克拉没法在这片沙漠中坚持太久。', 28153),
(154113, 'zhCN', '这还没我之前受的伤严重……', '这还没我之前受的伤严重……', 28153),
(154112, 'zhCN', '为什么我失败了？', '为什么我失败了？', 28153),
(154111, 'zhCN', '死吧，秃鹫！', '死吧，秃鹫！', 28153),
(154110, 'zhCN', '你无法击败我！', '你无法击败我！', 28153),
(154109, 'zhCN', '你的女妖之王现在在哪儿呢？', '你的女妖之王现在在哪儿呢？', 28153),
(154108, 'zhCN', '我从海里逃生，可不是为了到你这儿来送死的！', '我从海里逃生，可不是为了到你这儿来送死的！', 28153),
(154107, 'zhCN', '', '哦，我可不那么认为。', 28153),
(154106, 'zhCN', '是时候执行尼莎的计划了，蛇人绝对会被打个措手不及。', '', 28153),
(154105, 'zhCN', '', '我早该在安保上多花些钱的。', 28153),
(154104, 'zhCN', '', '我可承受不起你的三心二意！', 28153),
(154103, 'zhCN', '', '必要的话就教训他们一顿！我要暗礁破坏者现在就运作起来。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154102, 'zhCN', '她的伤很重，可能坚持不了多久了。', '', 28153),
(154101, 'zhCN', '', '我总能找到办法的。这是又一个幸存者吗？', 28153),
(154100, 'zhCN', '在它们都被毁掉之前，尽力抢救一些吧。', '在它们都被毁掉之前，尽力抢救一些吧。', 28153),
(154099, 'zhCN', '这里有许多奇妙的物品。', '这里有许多奇妙的物品。', 28153),
(154098, 'zhCN', '召集足够的人手来守住旧行商大道还需要一段时间，你能帮我们真是太好了。', '', 28153),
(154097, 'zhCN', '谢谢你……', '谢谢你……', 28153),
(154096, 'zhCN', '哦不……别再这样了。', '哦不……别再这样了。', 28153),
(154095, 'zhCN', '别让他们吃掉我……', '别让他们吃掉我……', 28153),
(154094, 'zhCN', '他们告诉我……这很轻松……', '他们告诉我……这很轻松……', 28153),
(154093, 'zhCN', '你的脑袋将成为我光荣的战利品。', '你的脑袋将成为我光荣的战利品。', 28153),
(154092, 'zhCN', '我们的一些商队正在寻找帮手，想做个护送任务吗？', '', 28153),
(154091, 'zhCN', '荒芜将带走你！', '荒芜将带走你！', 28153),
(154090, 'zhCN', '即便从海里逃生，也只不过是为了被我亲手杀死！', '即便从海里逃生，也只不过是为了死在我的刀下！', 28153),
(154089, 'zhCN', '你们将死在这里！', '你们将死在这里！', 28153),
(154088, 'zhCN', '你终于露出了本来的面目，死亡领主！离开这片神圣的土地！', '你终于露出了本来的面目，死亡领主！离开这片神圣的土地！', 28153),
(154087, 'zhCN', '最伟大的一步就是勇敢迈出的下一步，$n。继续沿着这条道路前行吧。', '最伟大的一步就是勇敢迈出的下一步，$n。继续沿着这条道路前行吧。', 28153),
(154086, 'zhCN', '你是阿尔萨斯以自己的形象造出来的怪物，$n。当你真正面临死亡时，我希望你缓慢而痛苦的死去，好让你感受到你对他人所做的一切。\n\n当整个世界都在面临重大的危机时，你跨越整个星球，将死者变为了受诅咒的亡灵。我肯定你当时告诉自己这是为了大局，但是记住我的话，死亡领主，这必将带来恶果。\n\n<扎莉斯塔萨微微颤抖>\n\n但是现在，或许你还有点用。', '你是阿尔萨斯以自己的形象造出来的怪物，$n。当你真正面临死亡时，我希望你缓慢而痛苦的死去，好让你感受到你对他人所做的一切。\n\n当整个世界都在面临重大的危机时，你跨越整个星球，将死者变为了受诅咒的亡灵。我肯定你当时告诉自己这是为了大局，但是记住我的话，死亡领主，这必将带来恶果。\n\n<扎莉斯塔萨微微颤抖>\n\n但是现在，或许你还有点用。', 28153),
(154085, 'zhCN', '<扎莉斯塔萨的表情微微舒缓。>\n\n并不是没人察觉，$n。我的人民为数不多，每一条生命都很宝贵。\n\n这不是你干扰我飞行的理由，不过我们认可并感谢你的……克制。对你来说，能做到这一点可不容易。', '<扎莉斯塔萨的表情微微舒缓。>\n\n并不是没人察觉，$n。我的人民为数不多，每一条生命都很宝贵。\n\n这不是你干扰我飞行的理由，不过我们认可并感谢你的……克制。对你来说，能做到这一点可不容易。', 28153),
(154084, 'zhCN', '我们知道，死亡领主，$n。我们知道是你袭击了我们的圣殿。我们知道你腐化并奴役了吉拉纳斯塔兹。这种亵渎生命的行为总有一天将遭到报应。', '我们知道，死亡领主，$n。我们知道是你袭击了我们的圣殿。我们知道你腐化并奴役了吉拉纳斯塔兹。这种亵渎生命的行为总有一天将遭到报应。', 28153),
(154083, 'zhCN', '我们知道你的罪行，死亡骑士。你的行为虽然将艾泽拉斯从燃烧军团的魔爪中解救了出来，但我们之间的信任已经受损。\n\n小心行事。', '我们知道你的罪行，死亡骑士。你的行为虽然将艾泽拉斯从燃烧军团的魔爪中解救了出来，但我们之间的信任已经受损。\n\n小心行事。', 28153),
(154082, 'zhCN', '看起来我在红玉圣地还漏了几条龙。<试着杀死她>', '看起来我在红玉圣地还漏了几条龙。<试着杀死她>', 28153),
(154081, 'zhCN', '我希望我的行动赢得了一些信任。', '我希望我的行动会赢得一些信任。', 28153),
(154080, 'zhCN', '你的人民都很虚弱，已经离死亡不远了。我只是更快地结束了你们的痛苦。', '你的人民都很虚弱，已经离死亡不远了。我只是更快地结束了你们的痛苦。', 28153),
(154079, 'zhCN', '我放过了那些我能饶恕的生命。', '我放过了那些我能饶恕的生命。', 28153),
(154078, 'zhCN', '你认得我？', '你认得我？', 28153),
(154077, 'zhCN', '不！不！不！！！', '不！不！不！！！', 28153),
(154076, 'zhCN', '', '为了联盟。', 28153),
(154075, 'zhCN', '快跑！保住自己的命！', '快跑！保住自己的命！', 28153),
(154074, 'zhCN', '我……我想我可能让自己陷入困境了……', '我……我想我可能让自己陷入困境了……', 28153),
(154073, 'zhCN', '快把我弄出去！', '快把我弄出去！', 28153),
(154072, 'zhCN', '谢谢你！我差点就成死人了。', '谢谢！我差点就成死人了。', 28153),
(154071, 'zhCN', '这些东西是什么！？我要离开这里了！', '这些东西是什么！？我要离开这里了！', 28153),
(154070, 'zhCN', '我得救了！我差点就被怪物吃掉了！', '我得救了！我差点就被怪物吃掉了！', 28153),
(154069, 'zhCN', '哼！看起来没什么挑战性。', '', 28153),
(154068, 'zhCN', '难以置信……斯托颂还在和别的恐魔私通？！', '', 28153),
(154067, 'zhCN', '神殿里有一只强大的恐魔在等着我们，来吧，亮出獠牙，我们去会会它！', '', 28153),
(154066, 'zhCN', '小心！我感觉到神殿中存在着大量的腐化，我们不能让它再蔓延了！', '', 28153),
(154065, 'zhCN', '你看上去并没有什么变化。哼，无所谓了，狩猎等待着我们。', '', 28153),
(154064, 'zhCN', '你有没有感觉到平静？信念更加坚定？我们继续前进吧，完成必须完成的使命。', '', 28153),
(154063, 'zhCN', '传言说海潮贤者可以从净化泉水中增强自己的力量。在我们进入神殿中央之前，先试验一下这是不是真的。', '', 28153),
(154062, 'zhCN', '呸！那就随我来！', '', 28153),
(154061, 'zhCN', '在踏入我们最神圣的地方之前，所有人都必须被净化。请你们在进入神殿之心前，先接受净化泉水的祝福。', '', 28153),
(154060, 'zhCN', '每一点都有帮助，勇士。为了部落！', '', 28153),
(154059, 'zhCN', '斯托颂勋爵并没有掌控一切，我很欣慰。感谢你。', '', 28153),
(154058, 'zhCN', '这些水池里蕴含着力量。收集纯水微粒，它们可以为我们提供力量！', '', 28153),
(154057, 'zhCN', '我感觉到仍有善良存在于这座圣地之内。取回一些纯水微粒，我们可以让这座神殿重新焕发出旧日的荣光。', '', 28153),
(154056, 'zhCN', '他们差点把我结果了。谢谢你，$c。', '他们差点把我结果了。谢谢你，$c。', 28153),
(154055, 'zhCN', '', '传染正在蔓延。', 28153),
(154054, 'zhCN', '', '病毒水平上升。', 28153),
(154053, 'zhCN', '', '侦测到新型病毒株。', 28153),
(154052, 'zhCN', '', '外科区域开启。正在准备研究样本。', 28153),
(154051, 'zhCN', '', '感染等级危险！全面清除启动。', 28153),
(154050, 'zhCN', '', '抑制室正在通风。', 28153),
(154049, 'zhCN', '', '使用极端高温测试病菌抗性。', 28153),
(154048, 'zhCN', '', '解剖协议激活。', 28153),
(154047, 'zhCN', '', '系......系......系......系统已恢复，警戒级别回归安全阈值。', 28153),
(154046, 'zhCN', '很明显这项行动的动静闹得挺大，但还算有效。', '', 28153),
(154045, 'zhCN', '', '这是最后一只了。亚兹玛再也没法窥探我们了！', 28153),
(154044, 'zhCN', '', '蜘蛛之眼在窥视我们，亚兹玛的耳目无处不在。踩扁它们。', 28153),
(154043, 'zhCN', '', '净化完成。', 28153),
(154042, 'zhCN', '这是一项营救任务。找到我们被俘的士兵，救出他们，带他们前往撤离点。我将授权你使用致命武力。事实上，我推荐你这么做。', '', 28153),
(154041, 'zhCN', '', '传染等级降低。', 28153),
(154040, 'zhCN', '很好。现在第二梯队可以轻松救出我们的战士了。', '', 28153),
(154039, 'zhCN', '', '暗影之刃莱兹再也不能残害我的人民了，谢谢你。', 28153),
(154038, 'zhCN', '', '感染被清除。', 28153),
(154037, 'zhCN', '这项行动很简单。制造混乱。我的另一队人马正准备营救被俘的战士们，但首先你得解决掉那些卫兵。杀进去，尽可能多消灭一些卫兵，再撤出来。', '', 28153),
(154036, 'zhCN', '', '亚兹玛最器重的一名刺客就在这片区域，要小心！', 28153),
(154035, 'zhCN', '', '侦测到恶性病毒株。必须将其根除。', 28153),
(154034, 'zhCN', '', '这下亚兹玛这种人渣应该不敢再涉足黑暗巫毒了。', 28153),
(154033, 'zhCN', '', '净化协议激活。', 28153),
(154032, 'zhCN', '', '亚兹玛的邪恶巫毒激活了那些蒂基面具！消灭她污秽的构造体。', 28153),
(154031, 'zhCN', '你成功了！现在探险者协会的小伙子们可以安全地调查神殿了。', '', 28153),
(154030, 'zhCN', '有人在杀害这些赞达拉巨魔，进入神殿对探险者协会来说太危险了，必须先做些什么！你进去，把问题的根源给解决了！', '', 28153),
(154029, 'zhCN', '太棒了！我们会立刻派出一支先遣队。', '', 28153),
(154028, 'zhCN', '我不能让我的小伙子们进入神殿，有好多蒂基面具呢。它们的魔法太强了！', '', 28153),
(154027, 'zhCN', '真不赖！可我还是感觉有几只爬进了我的胡子里！', '', 28153),
(154026, 'zhCN', '又是蜘蛛！这儿的蜘蛛全是个叫亚兹玛的家伙养的。快去踩死几只，这样我们才能安心工作！', '', 28153),
(154025, 'zhCN', '光铸者，把投石车给我砸掉！', '', 28153),
(154024, 'zhCN', '狮鹫骑士，起飞！', '', 28153),
(154023, 'zhCN', '黑铁矮人，趁现在！从下方突袭！', '', 28153),
(154022, 'zhCN', '', '好吧，虽然证据是有了，不过你也没留下几个活口，好让他们去执行计划！不管怎样，干得好。', 28153),
(154021, 'zhCN', '荣耀……属于联盟……', '', 28153),
(154020, 'zhCN', '我现在虽然是雾帆的一员，但是你们竟然以为我会可耻地背弃自己联盟的血脉而去效命部落……真是大胆！', '', 28153),
(154019, 'zhCN', '', '自由镇的海盗们总在谋划些什么。找出他们这次的计划。', 28153),
(154018, 'zhCN', '多亏了你，第七军团又少了一个威胁。', '', 28153),
(154017, 'zhCN', '打得漂亮！我们会守住这里，为了联盟！', '', 28153),
(154016, 'zhCN', '那可真是一个不得了的挑战，但你英勇地战胜了它。干得漂亮！', '', 28153),
(154015, 'zhCN', '敌人被消灭了。很遗憾我们得用这种暴力手段，但情势所迫，必须如此。', '', 28153),
(154014, 'zhCN', '要是你参加了第三次战争，我会让你在我身边效力。干得漂亮。', '', 28153),
(154013, 'zhCN', '要是你参加第二次战争也会干得不错。做得好。', '', 28153),
(154012, 'zhCN', '干得漂亮。我们又少了一个需要担心的威胁！', '', 28153),
(154011, 'zhCN', '谢谢你的鼎力相助。你真是虔敬者的勇士！', '', 28153),
(154010, 'zhCN', '', '哈哈，让他们知道钱包大出血的滋味！', 28153),
(154009, 'zhCN', '', '只要我们拿到一份帮派账本，就能干扰他们的财政运作！', 28153),
(154008, 'zhCN', '谢谢你。我们现在还没法转移伤员，但你为我们争取了时间。', '谢谢你。我们现在还没办法转移伤员，但是你为我们争取了宝贵的时间。', 28153),
(154007, 'zhCN', '拿着，这个能暂时止血……', '拿着，这个能暂时止血……', 28153),
(154006, 'zhCN', '不要动，我知道这很疼……', '不要动,虽然我知道这很疼……', 28153),
(154005, 'zhCN', '安静！他们会听见我们的……', '安静！他们会听见的……', 28153),
(154004, 'zhCN', '去寻找援军！我去奥迪尔里面看看，有什么办法可以阻止腐化！', '', 28153),
(154003, 'zhCN', '', '在什么地方我都能认出欧维斯的笔迹。我要杀了你，然后干掉那个叛徒！', 28153),
(154002, 'zhCN', '啊，入口要关上了！我决不能错过这次机会！', '', 28153),
(154001, 'zhCN', '', '车还停在原处！', 28153),
(154000, 'zhCN', '', '船长！有人叛变了……', 28153),
(153999, 'zhCN', '那玩意刚刚是在说戈霍恩？！跟着那台机器。', '', 28153),
(153997, 'zhCN', '也许这和奥迪尔有关。我们快去瞧瞧！', '', 28153),
(153996, 'zhCN', '我以前从没见过这种腐化。', '', 28153),
(153995, 'zhCN', '', '嘿，$c。 有兴趣学些炼金术吗？$b$b我告诉你，我可是整个大陆最好的训练师。', 28153),
(153994, 'zhCN', '天知道里面藏着什么样的秘密？说不定会有消灭古神的办法呢！', '', 28153),
(153993, 'zhCN', '黑暗帝国陨落后，泰坦建立了这个设施，对各种野兽进行研究。', '', 28153),
(153992, 'zhCN', '啊！这是什么鬼东西？！', '', 28153),
(153991, 'zhCN', '这些洞穴一定通往传说中的奥迪尔！', '', 28153),
(153990, 'zhCN', '谢谢你的帮助。多亏了你的努力，这片沙漠现在更安全了。', '', 28153),
(153989, 'zhCN', '', '真是不小的挑战，但你表现得很不错。继续保持你的良好表现吧！', 28153),
(153988, 'zhCN', '', '又少了一个需要担心的威胁。干得漂亮！', 28153),
(153987, 'zhCN', '', '干得漂亮。你给敌人好好地上了一课，他们不会轻易忘记的。', 28153),
(153986, 'zhCN', '带路吧。', '带路吧。', 28153),
(153985, 'zhCN', '', '这个屋子里充满了隐藏的秘密。楼上既然安全了，我可以向你展示通往地下室的密道了。', 28153),
(153984, 'zhCN', '谢谢你的帮助。沃顿需要更多你这样的英雄！', '', 28153),
(153983, 'zhCN', '干得漂亮。感谢你的帮助，这片沙漠现在变得更安全了。', '', 28153),
(153982, 'zhCN', '沃顿现在更加安全了。干得好！', '', 28153),
(153981, 'zhCN', '想想……那些黄金吧……', '', 28153),
(153980, 'zhCN', '你知道你惹了谁吗？艾什凡将使我们变得超乎想象的强大！', '', 28153),
(153979, 'zhCN', '你休想伤害我的人民！', '', 28153),
(153978, 'zhCN', '这些石头……到处都是……魔古将……把它们全部拿走！', '', 28153),
(153977, 'zhCN', '那里！进攻！', '', 28153),
(153976, 'zhCN', '', '我想我们安全了。刚才多亏了你。', 28153),
(153975, 'zhCN', '有了这些石头，魔古族将天下无敌！', '', 28153),
(153974, 'zhCN', '你终于露出真面目了！死吧！', '', 28153),
(153973, 'zhCN', '', '看来我们有伴了。把他们炸翻，$p！', 28153),
(153972, 'zhCN', '', '抓紧了！我们要一路狂奔了。', 28153),
(153971, 'zhCN', '让你们看看老狼的尖牙！', '', 28153),
(153970, 'zhCN', '你归我了！', '', 28153),
(153969, 'zhCN', '你现在有骨气了是吧？哈！', '', 28153),
(153968, 'zhCN', '', '恐怕不行。', 28153),
(153967, 'zhCN', '', '真可悲。', 28153),
(153966, 'zhCN', '', '今天不行。', 28153),
(153965, 'zhCN', '我的斥候报告说附近有一名危险的敌人。我需要你去干掉它。', '', 28153),
(153962, 'zhCN', '附近的一名敌人让我损失了不少士兵。为他们复仇！', '', 28153),
(153959, 'zhCN', '第七军团收到情报，附近有一名强大的敌人。立即消灭它。', '', 28153),
(153958, 'zhCN', '没有宝藏……只有黑暗。', '黄金，就在眼前……', 28153),
(153957, 'zhCN', '释放我……', '我……自由了？', 28153),
(153956, 'zhCN', '被诅咒的宝藏……和黄金……', '被诅咒的窃贼……', 28153),
(153955, 'zhCN', '把我也算进去……', '金骨头……', 28153),
(153954, 'zhCN', '我收到消息，说你附近有一名危险的敌人。干掉它，但要小心突发情况。', '', 28153),
(153953, 'zhCN', '附近有一名危险的敌人，让我们失去了好几名斥候。消灭他，以此纪念阵亡者。', '', 28153),
(153952, 'zhCN', '当心，附近有一个威胁。保持冷静，在它逃跑前消灭它。', '', 28153),
(153951, 'zhCN', '看起来真不赖，头儿。不过如果你不喜欢的话，你可以再找找。', '', 28153),
(153950, 'zhCN', '我会给每个人一瓶药剂。现在先别喝。', '', 28153),
(153949, 'zhCN', '很好。你成功地让一座沉睡的城市变得暴跳如雷。\n\n我们不要浪费时间推卸责任了，好吗？', '', 28153),
(153948, 'zhCN', '我以前听说过这个故事。(跳过场景战役，传送到赞达拉的祖达萨港)', '我以前听说过这个故事。(跳过场景战役，传送到赞达拉的祖达萨港)', 28153),
(153947, 'zhCN', '就用你的死亡去给你的主人报个信吧。风暴之末永不屈服！', '', 28153),
(153946, 'zhCN', '别让它侵入你的思想。坚强点！', '', 28153),
(153945, 'zhCN', '', '所有这些苦难都是你的错。怪物！', 28153),
(153944, 'zhCN', '我会保护大家免受攻击！', '', 28153),
(153943, 'zhCN', 'Ni plahf Ni bormaz Oou sshoq\'meg vwyq yyg\'far', '', 28153),
(153942, 'zhCN', '黄金。黄金。黄金。', '积累更多的宝藏。', 28153),
(153941, 'zhCN', '黑暗袭来。无处可逃。遗忘之王回来了。', '', 28153),
(153940, 'zhCN', '这里没人……', '跑……', 28153),
(153939, 'zhCN', '泽姆兰的所有宝物。', '只有泽姆兰能得到宝藏。', 28153),
(153938, 'zhCN', '先按顺序进行介绍吧。大副欧维斯，这是$n。 $n，这是欧维斯。我们直入正题好吧？', '', 28153),
(153937, 'zhCN', '', '我警告过基罗，告诉他蛇人很快就会袭击我们。我们本可以有所准备的……也许现在他终于能听进去了。', 28153),
(153936, 'zhCN', '', '我们对他们的袭击毫无防备。蛇人无情地残杀和奴役了我们。', 28153),
(153935, 'zhCN', '黄金……', '闪亮的……', 28153),
(153934, 'zhCN', '一个巨大的威胁正在附近游荡。在它残害更多无辜的生命之前消灭它。', '', 28153),
(153933, 'zhCN', '我们的盟友受到了攻击。你必须马上消除这个威胁。', '', 28153),
(153930, 'zhCN', '附近有一种危险的生物。在它伤害无辜之前，你必须把它除掉。', '', 28153),
(153929, 'zhCN', '', '我收到了附近有威胁的报告。尽快去消灭它！', 28153),
(153928, 'zhCN', '', '我们的一些士兵最近受到了攻击。找到威胁所在并将其清除！', 28153),
(153927, 'zhCN', '', '某种非常危险的东西正在这里游荡。你得先下手为强。', 28153),
(153926, 'zhCN', '我们收到报告，此区域有一种危险生物。拜托你尽快去消灭它。', '', 28153),
(153925, 'zhCN', '快，来帮我！', '', 28153),
(153924, 'zhCN', '我们的一支商队在附近遇袭。马上去消除威胁，以绝后患！', '', 28153),
(153923, 'zhCN', '我知道她是个人类，但是希望你能理解一下。', '', 28153),
(153922, 'zhCN', '我们的目标很简单。我们助她叛变成功，然后她会允许我们把这里作为我们进攻的据点。', '', 28153),
(153921, 'zhCN', '欧维斯可不会像其他海盗那样放弃自己的自由。', '', 28153),
(153920, 'zhCN', '附近有种危险的生物。拜托你尽快去解决它！', '', 28153),
(153919, 'zhCN', '我在提拉加德开拓登陆点的时候听人提起了我们的联系人。', '', 28153),
(153918, 'zhCN', '啊嘿，海盗伙计！', '', 28153),
(153917, 'zhCN', '沉没的王国欢迎你疲惫的灵魂。', '', 28153),
(153916, 'zhCN', 'Oou c\'toth shuul phquathi ywaq uulg\'ma on\'ma', '', 28153),
(153915, 'zhCN', '他已经迷失了。剩下的只有黑暗。', '', 28153),
(153914, 'zhCN', '', '萨缪尔，我知道你在那里。你必须战胜它！', 28153),
(153913, 'zhCN', '看来，没有什么活物能阻挡你太久。', '', 28153),
(153912, 'zhCN', '', '很好！现在道路安全了。', 28153),
(153911, 'zhCN', '这只是一个复制品。我们还是别提这个了。', '', 28153),
(153910, 'zhCN', '', '完美！我们把它拿回去，看看里面藏了什么。', 28153),
(153909, 'zhCN', '这就够了。我代表大酋长表示感谢。', '', 28153),
(153908, 'zhCN', '', '太棒了！这会对战事很有帮助。', 28153),
(153907, 'zhCN', '好了，头儿！我们先去见一见大副。要装得像点。', '', 28153),
(153906, 'zhCN', '我看起来不错吧，你觉得呢？啊哈！', '', 28153),
(153905, 'zhCN', '一头好斗的野兽挡住了我们离开监狱的出路。杀了它。', '', 28153),
(153904, 'zhCN', '', '一头强大的野兽阻碍了我们确保滩头立足点的行动。麻烦你去解决它，这样我们就能清出一条逃脱路线了。', 28153),
(153903, 'zhCN', '让我也打扮一下，头儿。', '', 28153),
(153902, 'zhCN', '我们的间谍大师说库尔提拉斯之傲就停在托尔达戈。如果情报是真的，那你就要去为我们偷走那艘船。', '', 28153),
(153901, 'zhCN', '', '狱长有一个传家宝，就藏在一个舰船模型复制品里。我要你去把它拿回来。', 28153),
(153900, 'zhCN', '部落战争机器需要武器和护甲。你在那里的时候，尽量多拿点东西，然后回来向我汇报。', '', 28153),
(153899, 'zhCN', '', '现在情况这么乱，肯定还有没被拿走的货物。看看能不能潜入进去，拿些补给箱。', 28153),
(153898, 'zhCN', '他们杀死了你的父亲……背叛了你的国王……而你却袖手旁观！你想让所有盟友都死在部落手上吗？', '', 28153),
(153897, 'zhCN', '部落不过是一群怪物。背叛你有什么好奇怪的！', '', 28153),
(153896, 'zhCN', '你跟那群杂种结盟，抛弃了骨肉至亲！', '', 28153),
(153895, 'zhCN', '那些禽兽杀死我的时候你却在袖手旁观。背叛亲人究竟有什么好处？', '', 28153),
(153894, 'zhCN', '有支枯木巨魔的部队正从东部向激流堡进军。别把他们全干掉，留几个活口，欣赏他们逃回茅屋的狼狈样吧。', '', 28153),
(153893, 'zhCN', '这艘船不要烧，伙计。我们要用它来离开这个岛屿。', '', 28153),
(153892, 'zhCN', '我们有不少狮鹫骑士都被击落了。请帮忙寻找战场上的生还者。', '', 28153),
(153891, 'zhCN', '', '现在你看到了！你明白了！戈霍恩会征服世界！', 28153),
(153890, 'zhCN', '', '如果那个怪物自由了，那就意味着祖达萨的末日！', 28153),
(153889, 'zhCN', '', '我早知道鲜血巨魔是个威胁，但是我从没想到……会这样……', 28153),
(153888, 'zhCN', '你是谁？', '你是谁？', 28153),
(153886, 'zhCN', '你好啊，$n，你作为艾泽拉斯勇士的英勇事迹已经家喻户晓了。', '你好啊，$n，你作为艾泽拉斯勇士的英勇事迹已经家喻户晓了。', 28153),
(153885, 'zhCN', '扭曲的怪物！滚回海里去吧！', '', 28153),
(153884, 'zhCN', '我担心来自斯托颂家族的教徒会试图在伯拉勒斯散布影响。揭示他们的真面目吧。', '', 28153),
(153883, 'zhCN', '', '所以，谣言是真的了。不过起码现在街道稍微安全点了。', 28153),
(153882, 'zhCN', '来吧，兄弟姐妹们。团结一致！', '', 28153),
(153881, 'zhCN', '继续前进。黑暗正在侵蚀他的思维！', '', 28153),
(153880, 'zhCN', '', '撑住，萨缪尔，我们就快到了！', 28153),
(153879, 'zhCN', '鲜血之潮！起来吧！起来吧！', '', 28153),
(153878, 'zhCN', '', '据说伯拉勒斯的守卫已经被帮派买通了。你可以去查一查吗？', 28153),
(153877, 'zhCN', '吁，这大概会让它们忙上……呃……整整五分钟吧？', '', 28153),
(153876, 'zhCN', '哇噢！这些鸟发疯了！给它们喂点东西之类的！快！', '', 28153),
(153875, 'zhCN', '好吧，这些钱包没有一个是我的，不过……在找到失主之前，还是由我来保管吧。', '', 28153),
(153874, 'zhCN', '哼？我的钱包呢？等等！是刚才那个小鬼拿了我的钱包吗？！追上他！', '', 28153),
(153873, 'zhCN', '', '我希望其他人能安全脱险。', 28153),
(153872, 'zhCN', '', '狐人是最与世无争的种族。我们乘坐大篷车旅行，四处收集物资和进行交易。', 28153),
(153871, 'zhCN', '你做到了，$p，艾特文醒过来了！', '', 28153),
(153870, 'zhCN', '', '看看蛇人对我们的家园做了什么……', 28153),
(153869, 'zhCN', '', '选得好，这东西我用得来。', 28153),
(153868, 'zhCN', '有几个石拳食人魔想攻击激流堡。这群长着啤酒肚的暴徒上次的下场可不怎么样，这次最好也提醒他们一下。', '', 28153),
(153867, 'zhCN', '耐心点，泰莉亚。他们会来的。', '', 28153),
(153866, 'zhCN', '', '风暴之末的其他人能及时赶到吗？', 28153),
(153865, 'zhCN', '你可以把这些捣蛋鬼送回西南边的湖旁边的村子，而且还能领赏。但我建议你不要涉水……毕竟鱼人都是在水里交配。', '', 28153),
(153864, 'zhCN', '看来我们有群活蹦乱跳的鱼人蝌蚪做伴了。', '', 28153),
(153863, 'zhCN', '我们的斥候报告说，在东北的矿洞附近发现一辆被盗的矿车。想夺回来的话，可能需要一点强制措施。', '', 28153),
(153862, 'zhCN', '我们发现了一些无人看守的部落伐木机。趁这机会去砍点木料你觉得怎样？', '', 28153),
(153861, 'zhCN', '要记住，即使是有意识的，会打人的木头也依然是……木头。而且，是一大堆木头。', '', 28153),
(153860, 'zhCN', '我们在树林边发现了枝条领主奥德鲁斯。', '', 28153),
(153859, 'zhCN', '石巨人弗兹鲁克正在东南边的道路上横冲直撞。小心别被踩扁了。', '', 28153),
(153858, 'zhCN', '我们先把它揍得服服帖帖，然后把它送上部落前线，怎么样？', '', 28153),
(153857, 'zhCN', '东面的山上出现了巨型土元素。', '', 28153),
(153856, 'zhCN', '联军的英勇将士，时候到了。', '', 28153),
(153855, 'zhCN', '十字军战士，向阿戈罗克进发！圣光保佑！', '', 28153),
(153854, 'zhCN', '部落正试图占领加尔森的矿洞。让他们看看在这里是谁做主，好吗？', '', 28153),
(153853, 'zhCN', '部落正在骚扰我们在高地伐木场的盟友，快用斧头把他们请出去。', '', 28153),
(153852, 'zhCN', '部落的部队已经进入了激流堡。保护好你的指挥官，把部落撵出去!', '', 28153),
(153851, 'zhCN', '远望栖地遭到了攻击。我看不如让部落统统滚下山吧？', '', 28153),
(153850, 'zhCN', '', '和我说一声，我们就开始！', 28153),
(153849, 'zhCN', '', '大酋长希望部落的英雄们能够保持警惕，准备参战。我建议我们利用这段时间进行战斗训练。', 28153),
(153848, 'zhCN', '', '你好！欢迎来到希利苏斯，我们要确保艾泽里特行动不被联盟干扰。', 28153),
(153847, 'zhCN', '蠕动……扭曲……低语……', '', 28153),
(153846, 'zhCN', '当你准备好开始了就和我说一声。', '', 28153),
(153845, 'zhCN', '我们在希利苏斯巡逻的时间可以用来磨砺你的战斗技能。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153844, 'zhCN', '欢迎加入！乌瑞恩国王需要联盟的每一位英雄都能在对抗部落时拿出最好的状态。', '', 28153),
(153843, 'zhCN', '小心脚下。这桥真是名副其实。', '', 28153),
(153842, 'zhCN', '', '厉害！接下来我们将看到……等一下，那是……？准备战斗！联盟来袭！', 28153),
(153841, 'zhCN', '潮汐将至……无人能逃……', '', 28153),
(153840, 'zhCN', '坚守平台！为祖尔争取时间，他会碾碎这些可悲的生物。', '', 28153),
(153839, 'zhCN', '部落的部队接近元素法阵了。也许我们应该给他们上一堂魔法课。', '', 28153),
(153838, 'zhCN', '', '为了我的父亲！', 28153),
(153837, 'zhCN', '', '我不会对你客气的！', 28153),
(153836, 'zhCN', '你学的不错！下一次我们要……等一下，那是……？拿起武器！部落来袭！', '', 28153),
(153835, 'zhCN', '', '你的死期到了！', 28153),
(153834, 'zhCN', '', '为了库尔提拉斯！', 28153),
(153833, 'zhCN', '部落攻击了我们在诺斯弗德路口的据点。既然他们这么“殷勤”，就让他们喝上一壶吧。', '', 28153),
(153832, 'zhCN', '', '恶魔变形将把你变成一个恶魔，强化你的混乱打击和刃舞。', 28153),
(153831, 'zhCN', '', '我们加入你！', 28153),
(153830, 'zhCN', '部落正在唤勇之路上前进。他们都到我们家门口了，我们当然得好好欢迎一下。', '', 28153),
(153829, 'zhCN', '恶魔变形将把你变成一个恶魔，强化你的混乱打击和刃舞。', '', 28153),
(153828, 'zhCN', '纽斯泰德遭到了部落的攻击。我们快结束这场闹剧吧。', '', 28153),
(153827, 'zhCN', '', '刃舞可以对你周围所有的敌人进行一连串的快速攻击。', 28153),
(153826, 'zhCN', '刃舞可以对你周围所有的敌人进行一连串的快速攻击。', '', 28153),
(153825, 'zhCN', '', '这个高消耗的技能也是你最强大的技能，请尽量频繁地使用它。', 28153),
(153824, 'zhCN', '这个高消耗的技能也是你最强大的技能，请尽量频繁地使用它。', '', 28153),
(153823, 'zhCN', '', '“眼棱”可以用你体内燃烧的混乱之力熔化你的敌人。', 28153),
(153822, 'zhCN', '眼棱可以用你体内燃烧的混乱之力熔化你的敌人。', '', 28153),
(153821, 'zhCN', '', '这是你最强大的攻击方式之一，经常使用它，以免浪费恶魔之怒。', 28153),
(153820, 'zhCN', '这是你最为强大的攻击方式之一，记得经常使用它，以免浪费恶魔之怒。', '', 28153),
(153819, 'zhCN', '我刚想去找人帮忙，你就出现了！省的我再跑一趟了。', '', 28153),
(153818, 'zhCN', '部落士兵来了。尽全力挡住他们，行吗？', '', 28153),
(153817, 'zhCN', '', '对目标假人使用压制。', 28153),
(153816, 'zhCN', '对目标假人使用压制。', '', 28153),
(153815, 'zhCN', '我们好像是捅了马蜂窝了。部落正在倾巢而出。', '', 28153),
(153814, 'zhCN', '', '这种强力的攻击也会强化你的下一次致死打击，记得尽早、尽量地使用它。', 28153),
(153813, 'zhCN', '这种强力的攻击也会强化你的下一次致死打击，记得尽早、尽可能多地使用它。', '', 28153),
(153812, 'zhCN', '', '压制会运用你的强大力量对敌人造成致命的伤害。', 28153),
(153811, 'zhCN', '压制会运用你的强大力量对敌人造成致命的伤害。', '', 28153),
(153810, 'zhCN', '', '你受伤了，但这对你来说根本不是问题。', 28153),
(153809, 'zhCN', '你受伤了，但这对你来说根本不是问题。', '', 28153),
(153804, 'zhCN', '用吸取生命为你自己恢复全部生命值。', '', 28153),
(153803, 'zhCN', '', '用吸取生命为你恢复全部生命值。', 28153),
(153802, 'zhCN', '', '吸取生命将会消耗你目标的生命，对你的敌人造成的伤害会为你治疗。', 28153),
(153801, 'zhCN', '吸取生命将会消耗你目标的生命，对你的敌人造成的伤害会为你治疗。', '', 28153),
(153798, 'zhCN', '', '对目标假人使用暗影箭。', 28153),
(153797, 'zhCN', '对目标假人使用暗影箭。', '', 28153),
(153796, 'zhCN', '', '在你的其它法术折磨你的敌人时施放暗影箭。', 28153),
(153795, 'zhCN', '在你的其它法术折磨你的敌人时施放暗影箭。', '', 28153),
(153794, 'zhCN', '', '在你对目标施加痛楚和腐蚀术之后，继续用邪恶的暗影魔法来攻击他。', 28153),
(153793, 'zhCN', '在你对目标施加痛楚和腐蚀术之后，继续用邪恶的暗影魔法来攻击他。', '', 28153),
(153792, 'zhCN', '暗影会吞噬你。', '', 28153),
(153791, 'zhCN', '', '使用“凶猛狂暴”也会缩短“狂野怒火”的冷却时间。', 28153),
(153790, 'zhCN', '使用凶猛狂暴也会缩短狂野怒火的冷却时间。', '', 28153),
(153789, 'zhCN', '', '你的行为是无法容忍的！', 28153),
(153788, 'zhCN', '', '在攻击目标假人时使用凶猛狂暴。', 28153),
(153787, 'zhCN', '在攻击目标假人时使用凶猛狂暴。', '', 28153),
(153786, 'zhCN', '', '凶猛狂暴会使你的宠物陷入狂怒，让你得以将精力集中在其它技能的使用上。', 28153),
(153785, 'zhCN', '凶猛狂暴会使你的宠物陷入狂怒，让你得以将精力集中在其它技能的使用上。', '', 28153),
(153784, 'zhCN', '', '你还可以命令你的宠物施展一连串野蛮的狂乱攻击。', 28153),
(153783, 'zhCN', '你还可以命令你的宠物施展一连串野蛮的狂乱攻击。', '', 28153),
(153782, 'zhCN', '', '使用野火炸弹来攻击所有敌人。', 28153),
(153781, 'zhCN', '使用野火炸弹来攻击所有敌人。', '', 28153),
(153780, 'zhCN', '', '用它们对付成群的敌人则更加有效，因为野火会覆盖你目标身后锥形区域的所有敌人。', 28153),
(153779, 'zhCN', '用它们对付成群的敌人则更加有效，因为野火会覆盖你目标身后锥形区域的所有敌人。', '', 28153),
(153778, 'zhCN', '', '野火炸弹是你的另一项可用技能，它可以点燃你的敌人并持续燃烧他们。', 28153),
(153777, 'zhCN', '野火炸弹是你的另一项可用技能，它可以点燃你的敌人并持续燃烧他们。', '', 28153),
(153776, 'zhCN', '', '对目标假人使用毒蛇钉刺。', 28153),
(153775, 'zhCN', '对目标假人使用毒蛇钉刺。', '', 28153),
(153774, 'zhCN', '', '毒蛇钉刺会发出一枚淬毒的箭矢，持续造成自然伤害。', 28153),
(153773, 'zhCN', '毒蛇钉刺会发出一枚淬毒的箭矢，持续造成自然伤害。', '', 28153),
(153772, 'zhCN', '', '你的生存技能为你提供了攻击敌人的多种强力手段。', 28153),
(153771, 'zhCN', '你的生存技能为你提供了攻击敌人的多种强力手段。', '', 28153),
(153770, 'zhCN', '那条蛇——', '', 28153),
(153769, 'zhCN', '一路顺风！', '一路顺风！', 28153),
(153768, 'zhCN', '避开海妖！', '避开海妖！', 28153),
(153767, 'zhCN', '神灵在哀嚎！祖尔的异端简直毫无底线！', '', 28153),
(153766, 'zhCN', '注意保暖！', '注意保暖！', 28153),
(153765, 'zhCN', '夺回我的船，$n，然后我们再对付那些觊觎我宝座的叛徒。', '', 28153),
(153764, 'zhCN', '起锚啦！', '起锚啦！', 28153),
(153763, 'zhCN', '拜拜！', '拜拜！', 28153),
(153762, 'zhCN', '鱼好奇怪啊。', '鱼好奇怪啊。', 28153),
(153761, 'zhCN', '你有坏血病吗？', '你有坏血病吗？', 28153),
(153759, 'zhCN', '我已经完成了……我的使命……', '', 28153),
(153758, 'zhCN', '我喜欢始祖龟。', '我喜欢始祖龟。', 28153),
(153757, 'zhCN', '哪边是右舷来着？', '哪边是右舷来着？', 28153),
(153756, 'zhCN', '咿呀！！我听起来像个海盗吗？', '咿呀！！我听起来像个海盗吗？', 28153),
(153755, 'zhCN', '啊嘿！', '啊嘿！', 28153),
(153754, 'zhCN', '', '对目标假人反复使用杀戮命令。', 28153),
(153753, 'zhCN', '对目标假人反复使用杀戮命令。', '', 28153),
(153752, 'zhCN', '', '杀戮命令会让你的宠物发起一次强力的攻击，并可以产生用于其它技能的集中值。', 28153),
(153751, 'zhCN', '杀戮命令会让你的宠物发起一次强力的攻击，并可以产生其它技能所需的集中值。', '', 28153),
(153750, 'zhCN', '爸爸说我得不晕船才行。可我看见船并不晕啊！', '爸爸说我得不晕船才行。可我看见船也不晕啊！', 28153),
(153749, 'zhCN', '', '现在猎物已在你的射程之内，是时候释放你的怒火了。', 28153),
(153748, 'zhCN', '现在猎物已在你的射程之内，是时候释放你的怒火了。', '', 28153),
(153747, 'zhCN', '我感觉……好冷……', '我感觉……好冷……', 28153),
(153746, 'zhCN', '你不属于这里！', '你不属于这里！', 28153),
(153745, 'zhCN', '确实。$n，去科赞吧。去获取他们的艾泽里特提纯技术……还有，让拉兹敦克为失信于黑暗女王而付出代价。', '', 28153),
(153744, 'zhCN', '这笔买卖的麻烦事比好处还要多。有一个更简单的办法……那就是省略中间商——你懂的。', '', 28153),
(153743, 'zhCN', '大酋长会不高兴的。我们还指望拉兹敦克的艾泽里特提纯法能帮助我们对抗联盟。', '', 28153),
(153742, 'zhCN', '请见谅，“女妖王子”。我在死里逃生之后有些心神不宁……这买卖我可是一开始就反对的！', '', 28153),
(153741, 'zhCN', '振作点，贸易大王。这样叽里呱啦可有损于一位部落领袖的尊严。', '', 28153),
(153740, 'zhCN', '商业大亨拉兹敦克背叛了我们！这太疯狂了！这绿皮杂种居然敢撕毁这种合同。不敢相……', '', 28153),
(153739, 'zhCN', '嘿，凋零者。我有个坏消息……', '', 28153),
(153738, 'zhCN', '', '鲜血巨魔……会得到更多……力量！', 28153),
(153737, 'zhCN', '', '力量！力量！', 28153),
(153736, 'zhCN', '艾特文一直在休息，他在为今后而积蓄力量。', '', 28153),
(153735, 'zhCN', '传送到戈霍恩。', '传送到戈霍恩。', 28153),
(153734, 'zhCN', '传送到米斯拉克斯。', '传送到米斯拉克斯。', 28153),
(153733, 'zhCN', '传送到破灭沉降梯。', '传送到破灭沉降梯。', 28153),
(153732, 'zhCN', '传送到奥迪尔的入口。', '传送到奥迪尔的入口。', 28153),
(153731, 'zhCN', '位移石板被激活并稳定下来了。', '位移石板被激活并稳定下来了。', 28153),
(153730, 'zhCN', '又是一天，又是一场胜利！', '', 28153),
(153729, 'zhCN', '守卫报告说穴居人似乎正在准备新一轮进攻！快去阻止他们！', '', 28153),
(153728, 'zhCN', '你搞定了？很好。这种能把我生吞的发疯动物，还是越少越好。', '', 28153),
(153727, 'zhCN', '着魔的熊……？不行！绝对不能要。还是请你……呃……消灭它们吧。', '', 28153),
(153726, 'zhCN', '', '说我疯了也好，但我真的很不喜欢会走路的树。', 28153),
(153725, 'zhCN', '', '听起来艾尔格森伐木场又有麻烦了。帮他们解决掉这个麻烦！', 28153),
(153724, 'zhCN', '好极了，我的朋友！你和你毛茸茸的朋友真是绝佳搭档。', '', 28153),
(153723, 'zhCN', '尼克尔嚷着要回去捕猎猎鹰。为什么不带着他一起练习下呢？', '', 28153),
(153722, 'zhCN', '啊，丰盛的猎获，一如既往，我的朋友。你真棒！', '', 28153),
(153721, 'zhCN', '又是狩猎的好日子！看看这一次你能打败什么！', '', 28153),
(153720, 'zhCN', '最近城市里发生了许多事情。回到船上的感觉真不错啊。还是海上好。', '', 28153),
(153719, 'zhCN', '几年前，纳迦出现了。他们的蛮兵摧毁了神殿。', '', 28153),
(153718, 'zhCN', '阿格塔罗尔发生的事情简直就是耻辱。', '', 28153),
(153717, 'zhCN', '我夜里一直在检查船下的动静。这些纳迦简直无处不在。', '', 28153),
(153716, 'zhCN', '阿塔格罗尔', '阿塔格罗尔', 28153),
(153715, 'zhCN', '祖达萨港口', '祖达萨港口', 28153),
(153714, 'zhCN', '', '格罗尔离真相太近了。', 28153),
(153713, 'zhCN', '', '去阿塔格罗尔。我真希望神殿还在。', 28153),
(153712, 'zhCN', '有了你的帮忙，尖角地区总有一天会复原。', '', 28153),
(153711, 'zhCN', '迪普沃登在尖角码头的势力依然猖獗。我们必须尽全力让码头恢复正常！', '', 28153),
(153710, 'zhCN', '海洋终于得以喘息。你减轻了它的痛苦，谢谢你。', '', 28153),
(153709, 'zhCN', '港湾需要人帮忙净化那些徘徊不去的腐化。去清理那些被感染的海域吧！', '', 28153),
(153708, 'zhCN', '感谢你，我的朋友。我会把这些东西马上送到岗哨！', '', 28153),
(153707, 'zhCN', '罗萨琳要求提供更多钩刺。你能帮忙吗？', '', 28153),
(153706, 'zhCN', '很好，我的朋友！这样应该能让玛乔振作一会了。', '', 28153),
(153705, 'zhCN', '我们那位带壳的朋友玛乔，一直在练习骑术。但他需要东西提神，你能找一些他喜欢的饮料吗？', '', 28153),
(153704, 'zhCN', '', '希望这些走私者能得到教训。犯罪不会有好下场！', 28153),
(153703, 'zhCN', '', '这些走私者以为，他们能带着我们的武器离开伯拉勒斯。该给他们上一课了！', 28153),
(153702, 'zhCN', '孩子们，快去安全的地方！快点！', '孩子们，快去安全的地方！快点！', 28153),
(153701, 'zhCN', '别担心，我就在你们后面……', '别担心，我就在你们后面……', 28153),
(153700, 'zhCN', '快点，快进去！', '快点，快进去！', 28153),
(153699, 'zhCN', '好了，剩下的可以交给我们了。嘿，大家的眼睛都还在！做得好！', '', 28153),
(153698, 'zhCN', '库尔提拉斯的海洋会吞噬你们所有人！', '库尔提拉斯的海洋会吞噬你们所有人！', 28153),
(153697, 'zhCN', '那就来吧，我的家人安全了。', '那就来吧，我的家人安全了。', 28153),
(153696, 'zhCN', '你会为此付出代价的！', '你会为此付出代价的！', 28153),
(153695, 'zhCN', '野蛮人！', '野蛮人！', 28153),
(153694, 'zhCN', '这个广场都被那些鸟占领了！你最好赶紧疏散平民，不然海鸥就要把他们的眼珠子给啄出来了——但别说是我说的！', '', 28153),
(153693, 'zhCN', '救命！救救我们！', '救命！救救我们！', 28153),
(153692, 'zhCN', '这不可能……', '这不可能……', 28153),
(153691, 'zhCN', '我害怕！', '我害怕！', 28153),
(153690, 'zhCN', '但爸爸妈妈……', '但爸爸妈妈……', 28153),
(153689, 'zhCN', '我们要死了吗？', '我们要死了吗？', 28153),
(153688, 'zhCN', '你为什么不理我？我好怕！', '你为什么不理我？我好怕！', 28153),
(153687, 'zhCN', '快醒醒！求你快醒醒……', '快醒醒！求你醒醒……', 28153),
(153686, 'zhCN', '爸爸！', '爸爸！', 28153),
(153685, 'zhCN', '妈妈！', '妈妈！', 28153),
(153684, 'zhCN', '注意安全！旅行者，祝你一路顺风！', '', 28153),
(153683, 'zhCN', '', '卷轴预言到了你今天的到来。', 28153),
(153682, 'zhCN', '啊，$n。很好。他们证明了自己的用处。', '', 28153),
(153681, 'zhCN', '我需要修理。', '我需要修理。', 28153),
(153680, 'zhCN', '', '记得休息。把你自己折腾的筋疲力尽对联盟也没好处。', 28153),
(153679, 'zhCN', '部落夺取了元素法阵的控制权！', '部落夺取了元素法阵的控制权！', 28153),
(153678, 'zhCN', '$n占领了元素法阵！', '$n占领了元素法阵！', 28153),
(153677, 'zhCN', '部落夺取了加尔森的矿洞的控制权！', '部落夺取了加尔森的矿洞的控制权！', 28153),
(153676, 'zhCN', '$n占领了加尔森的矿洞', '$n占领了加尔森的矿洞', 28153),
(153675, 'zhCN', '部落夺取了诺斯弗德路口的控制权！', '部落夺取了诺斯弗德路口的控制权！', 28153),
(153674, 'zhCN', '$n占领了诺斯弗德路口！', '$n占领了诺斯弗德路口！', 28153),
(153673, 'zhCN', '部落夺取了远望栖地的控制权！', '部落夺取了远望栖地的控制权！', 28153),
(153672, 'zhCN', '$n占领了远望栖地！', '$n占领了远望栖地！', 28153),
(153671, 'zhCN', '部落夺取了纽斯泰德的控制权！', '部落夺取了纽斯泰德的控制权！', 28153),
(153670, 'zhCN', '$n占领了纽斯泰德！', '$n占领了纽斯泰德！', 28153),
(153669, 'zhCN', '部落夺取了高地伐木场的控制权！', '部落夺取了高地伐木场的控制权！', 28153),
(153668, 'zhCN', '$n占领了高地伐木场！', '$n占领了高地伐木场！', 28153),
(153667, 'zhCN', '部落夺取了唤勇之路的控制权！', '部落夺取了唤勇之路的控制权！', 28153),
(153666, 'zhCN', '$n占领了唤勇之路！', '$n占领了唤勇之路！', 28153),
(153665, 'zhCN', '我们的英勇事迹将被载入军史卷轴。', '', 28153),
(153664, 'zhCN', '我们英明的战略和毫无瑕疵的执行力，让敌人乱成了一团。', '', 28153),
(153663, 'zhCN', '我想我们正好打了他们一个措手不及。', '', 28153),
(153662, 'zhCN', '', '维多利亚！她……没能活下来……', 28153),
(153661, 'zhCN', '', '所有人听着！跟着纳萨诺斯去庭院！我从后面挡住联盟！', 28153),
(153660, 'zhCN', '士兵们，准备战斗！联盟过来了！', '', 28153),
(153659, 'zhCN', '', '赞达拉人对即将到来的恐怖一无所知。必须警告他们。', 28153),
(153658, 'zhCN', '', '艾萨拉女王正在计划什么东西，而且她还有盟友。', 28153),
(153657, 'zhCN', '', '噢我的天！这太可怕了。这些命令是要消灭那些忠于格罗尔的人。', 28153),
(153656, 'zhCN', '而我们在开阔地带作战，就能创造十倍的人数优势！', '', 28153),
(153655, 'zhCN', '别让我再回到魔像里……', '让我的灵魂获得自由，拜托了……', 28153),
(153654, 'zhCN', '我们来见你了，扎克拉加……', '你就是下一个，扎克拉加……', 28153),
(153653, 'zhCN', '终于……结束了。', '终于结束了……让我安息吧……', 28153),
(153652, 'zhCN', '邦桑迪……是不会让我死的……', '彼界……在哪里？', 28153),
(153651, 'zhCN', '树苗被野生动物吃掉了！', '树苗被野生动物吃掉了！', 28153),
(153650, 'zhCN', '哇啊啊啊！', '', 28153),
(153649, 'zhCN', '绝不能放部落逃走！', '', 28153),
(153648, 'zhCN', '守卫！我们遭到攻击！回到你们的岗位！放下大门，拦住出口！', '', 28153),
(153647, 'zhCN', '太好了。我们骑车走吧！', '', 28153),
(153646, 'zhCN', '当然。', '当然。', 28153),
(153645, 'zhCN', '你的朋友们都被女巫折磨死了。', '你的朋友们都被女巫折磨死了。', 28153),
(153644, 'zhCN', '哎呀，真扫兴！算了吧。\n\n我有一些好消息。我在这座山上建的一个落脚点快要完工了。你想看看吗？', '', 28153),
(153643, 'zhCN', '看起来你们是从森林那边来的。下面的伙计们都怎么样？', '', 28153),
(153642, 'zhCN', '正好我也把这辆三轮狼托组装完毕了！', '', 28153),
(153641, 'zhCN', '老板，你来了！你还把三轮摩托带来了！', '', 28153),
(153640, 'zhCN', '激流堡之战将在1分钟后开始。', '', 28153),
(153639, 'zhCN', '团结起来，无人能挡。', '', 28153),
(153638, 'zhCN', '绝不投降，活到最后。', '', 28153),
(153637, 'zhCN', '小心。', '', 28153),
(153636, 'zhCN', '我怎么说来着，不要做傻事。', '', 28153),
(153635, 'zhCN', '流亡者欢迎你，旅行者。', '', 28153),
(153634, 'zhCN', '你是来帮忙的吗？', '', 28153),
(153633, 'zhCN', '什么风把你吹来了？', '', 28153),
(153632, 'zhCN', '愿你一路顺风。', '', 28153),
(153631, 'zhCN', '力量与美德。', '', 28153),
(153630, 'zhCN', '带着荣耀前进吧。', '', 28153),
(153629, 'zhCN', '这片土地上的人会……奋起反抗……', '这片土地上的人会……奋起反抗……', 28153),
(153628, 'zhCN', '不！我要砍了你的脑袋……', '不！我要砍了你的脑袋……', 28153),
(153627, 'zhCN', '弱小的……联盟……', '弱小的……联盟……', 28153),
(153626, 'zhCN', '你们活不了多久了……', '你们活不了多久了……', 28153),
(153625, 'zhCN', '帝国……永存……', '帝国……永存……', 28153),
(153624, 'zhCN', '我们的人源源不断……', '我们的人源源不断……', 28153),
(153623, 'zhCN', '我注意到你了。', '', 28153),
(153622, 'zhCN', '这不算完……', '这不算完……', 28153),
(153621, 'zhCN', '这里欢迎你。', '', 28153),
(153620, 'zhCN', '为了……部落。', '为了……部落。', 28153),
(153619, 'zhCN', '砍了你的头，我会得到奖励的。', '砍了你的头，我会得到奖励的。', 28153),
(153618, 'zhCN', '你以为你比我们更聪明？哈！', '你以为你比我们更聪明？哈！', 28153),
(153617, 'zhCN', '我们会砍掉你的脑袋作为战利品！', '我们会砍掉你的脑袋作为战利品！', 28153),
(153616, 'zhCN', '你无法找到我们所有人！', '你无法找到我们所有人！', 28153),
(153615, 'zhCN', '出来玩啊，小联盟。', '出来玩啊，小联盟。', 28153),
(153614, 'zhCN', '这片土地属于赞达拉！', '这片土地属于赞达拉！', 28153),
(153613, 'zhCN', '你会后悔来到这里！', '你会后悔来到这里！', 28153),
(153612, 'zhCN', '你不属于这片土地！', '你不属于这片土地！', 28153),
(153611, 'zhCN', '不可能，我们和这些野蛮人不一样。', '不可能，我们和这些野蛮人不一样。', 28153),
(153610, 'zhCN', '不，我们一起走！', '不，我们一起走！', 28153),
(153609, 'zhCN', '该死的，我们得离开这里！', '该死的，我们得离开这里！', 28153),
(153608, 'zhCN', '我不会丢下你！', '我不会丢下你！', 28153),
(153607, 'zhCN', '你在干什么？你自己快走！', '你在干什么？你自己快走！', 28153),
(153606, 'zhCN', '去找人帮忙！我会没事的！', '去找人帮忙！我会没事的！', 28153),
(153605, 'zhCN', '离开这里，已经太迟了……', '离开这里，已经太迟了……', 28153),
(153604, 'zhCN', '你得赶紧跑……', '你得赶紧跑……', 28153),
(153603, 'zhCN', '我在看着你。', '', 28153),
(153602, 'zhCN', '也许下一次他们会小心点，别那么容易被俘。他们很幸运，部落能有你这样能干的英雄可以找到他们。', '', 28153),
(153601, 'zhCN', '我们的盟友需要援助。他们好像忘了自己已经被俘了，去放了他们。', '', 28153),
(153600, 'zhCN', '有了这个情报，我们就可以取得对联盟的优势。你的辛苦会得到奖励。', '', 28153),
(153599, 'zhCN', '我们的间谍情报显示，有一份运送中的重要信件随时可能要经过这个区域，给我不惜一切手段把它给截下来。', '', 28153),
(153598, 'zhCN', '神灵眷顾着你。这是好事！只是别让它进到你的脑子里。', '', 28153),
(153597, 'zhCN', '我们的敌人又在洛阿神灵之园里肆虐，需要给他们好好上一堂礼仪课。神灵的力量与你同在！', '', 28153),
(153596, 'zhCN', '到岗哨和我们碰头。我们必须找到答案。这看上去像是某种动乱的先兆。', '', 28153),
(153595, 'zhCN', '虽然这份工作有点粗暴，但这很有必要。我们必须让敌人摸不清状况。做得很好。', '', 28153),
(153594, 'zhCN', '联盟派出了间谍，暗地里搜罗我们的秘密。绝不能让他们发现我们的计划，务必要留心。', '', 28153),
(153593, 'zhCN', '如果没有赞达拉巨魔的舰队，我们和联盟的战争必将失败。', '', 28153),
(153592, 'zhCN', '联盟不会坐等我们建立好舰队后才发动攻击。我们需要赞达拉巨魔。', '', 28153),
(153591, 'zhCN', '让这些赞达拉巨魔加入部落，英雄。', '', 28153),
(153590, 'zhCN', '我们需要赞达拉巨魔的舰队。', '', 28153),
(153589, 'zhCN', '大酋长的意志必将实现。', '', 28153),
(153588, 'zhCN', '有你和艾特文帮我们，计划不可能失败。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153587, 'zhCN', '赞达拉巨魔似乎不是很喜欢我。', '', 28153),
(153586, 'zhCN', '部落的代言人。', '', 28153),
(153585, 'zhCN', '赞达拉舰队必须加入部落。你得再努把力。', '', 28153),
(153584, 'zhCN', '', '这位勇士突破暴风城的重兵把守，把我和祖尔救了出来。如此英勇的行为应当获得您的表彰，父王。', 28153),
(153583, 'zhCN', '陛下，部落的目的只是为了盗取我们的海军，令其为他们的亡灵大酋长效命。', '', 28153),
(153582, 'zhCN', '我搞到一些好东西，怎么来的就不要问了。', '我搞到一些好东西，怎么来的就不要问了。', 28153),
(153581, 'zhCN', '我从至高岭带来了补给。', '我从至高岭带来了补给。', 28153),
(153580, 'zhCN', '（观看造成艾泽拉斯伤口的事件）', '（观看造成艾泽拉斯伤口的事件）', 28153),
(153579, 'zhCN', '<泰坦控制台上显示了一系列数据输入。您可以选择一个来查看。>', '', 28153),
(153578, 'zhCN', '我希望你的内衣可以防火！', '希望你的内衣可以防火！', 28153),
(153577, 'zhCN', '啊，马上就要变热了！', '马上就要变热了！', 28153),
(153576, 'zhCN', '我要把你烧了！', '我要把你烧了！', 28153),
(153575, 'zhCN', '这个“钻石矮人”是世界之魂的代言人。如果情况不是十万火急，他是不会像这样出手干涉的。', '', 28153),
(153574, 'zhCN', '', '哦，你能想象吗？这个钻石矮人可以把我们送到艾泽拉斯的任何地方！', 28153),
(153573, 'zhCN', '我喜欢这个传送钻石矮人，他送的礼物好厉害。我们能留着他吗？', '', 28153),
(153572, 'zhCN', '我知道这一定很重要，麦格尼。但是为了库尔提拉斯的安危……请抓紧时间。', '', 28153),
(153571, 'zhCN', '来吧，勇士。艾泽拉斯在呼唤你！', '', 28153),
(153570, 'zhCN', '啊，差点忘了我把它留在这里了。', '啊，差点忘了我把它留在这里了。', 28153),
(153569, 'zhCN', '我太老了，做不了这件事。我要离开这里！', '我太老了，做不了这件事。我要离开这里！', 28153),
(153568, 'zhCN', '你最好把自己收拾干净，列兵。', '你最好把自己收拾干净，列兵。', 28153),
(153567, 'zhCN', '长官，我……我会做的更好的，长官。', '长官，我……我会做的更好的，长官。', 28153),
(153566, 'zhCN', '列兵詹姆斯，你的父母没教好你吗？为什么你要一直浪费我的时间，让我们在这些未知的土地上追着你四处瞎跑？', '列兵詹姆斯，你的父母没教好你吗？为什么你要一直浪费我的时间，让我们在这些未知的土地上追着你四处瞎跑？', 28153),
(153565, 'zhCN', '中士……谢谢你来找我……长官。', '中士……谢谢你来找我……长官。', 28153),
(153564, 'zhCN', '我们走吧！', '我们走吧！', 28153),
(153563, 'zhCN', '是时候返航了。维姆班恩想要完整的报告。', '是时候返航了。维姆班恩想要完整的报告。', 28153),
(153562, 'zhCN', '', '棘背野猪人没杀掉我，它们会为此后悔的。', 28153),
(153561, 'zhCN', '', '我想，等我回去后我会重新装修。我考虑用一个獠牙主题的风格……那么要到哪里找獠牙呢？$b$b<迪尔邪恶地笑了。>', 28153),
(153560, 'zhCN', '', '我要先喝点东西，然后要去夺回并重建家园。谢谢你削减了它们的数量！', 28153),
(153559, 'zhCN', '不能在这里待太久，我得回我的农场去。镇长让我来这里，感谢你帮助我们解决棘背野猪人的问题。$b$b你做得好，孩子。', '', 28153),
(153558, 'zhCN', '朋友，干得漂亮，你解决了野猪人。', '', 28153),
(153557, 'zhCN', '我不能待太久。我们得修好农用机器人，才能修复它们对农田造成的破坏。$b$b不过劳逸结合也很重要。', '', 28153),
(153556, 'zhCN', '我把农用机器人设定为自我防御模式。它肯定没问题的。', '', 28153),
(153555, 'zhCN', '小心野猪人的棘刺。它们是非常有用的工具，野猪人甚至会把它们丢在大锅里用做调料。', '', 28153),
(153554, 'zhCN', '部落在北边，野猪人在西边。我们还能相信民兵吗？', '', 28153),
(153553, 'zhCN', '希望罗尔夫、默尔特和斯比夫能逃出来。', '', 28153),
(153552, 'zhCN', '', '我的间谍告诉我，没有我们的舰队，你们打不赢和联盟的战争。\n\n所以……也就是说我今天要做的每一件脏活儿，我都会分配给你，而你也只能乖乖去做。要不然有你受的！', 28153),
(153551, 'zhCN', '', '我一直跟佐拉妮和塔兰吉说港口是安全的。她们听进去了吗？没有。$b$b有战斗吗？有恶徒吗？有打斗吗？当然有。但没这都不值得惊动大王。', 28153),
(153550, 'zhCN', '如果你愿意的话，跟着我。', '如果你愿意的话，跟着我。', 28153),
(153549, 'zhCN', '我有份礼物要给$n看一下。这份礼物也能挽救这片土地。', '', 28153),
(153548, 'zhCN', '稍安勿躁。这是麦格尼·铜须，他曾是铁炉堡的国王，现在是艾泽拉斯的代言人。', '', 28153),
(153547, 'zhCN', '好吧，这还真是新东西。', '', 28153),
(153546, 'zhCN', '是巫术！', '', 28153),
(153545, 'zhCN', '', '一个……钻石矮人？！', 28153),
(153544, 'zhCN', '现在，释放艾泽拉斯的力量吧！', '', 28153),
(153543, 'zhCN', '这真是令人绝望的消息。我们必须把这件事向最高指挥官报告。', '这真是令人绝望的消息。我们必须把这件事向最高指挥官报告。', 28153),
(153542, 'zhCN', '柯泰克疯了！必须阻止他！', '柯泰克疯了！必须阻止他！', 28153),
(153541, 'zhCN', '柯泰克逐渐厌倦了和平。他背叛了塞塔里斯的牺牲，愚蠢地想把钥匙合二为一，施放克拉西斯消灭敌人。', '柯泰克逐渐厌倦了和平。他背叛了塞塔里斯的牺牲，愚蠢地想把钥匙合二为一，施放克拉西斯消灭敌人。', 28153),
(153540, 'zhCN', '伟大的贤者苏尔西斯在柯泰克和我的帮助下建立了一道魔法屏障，封印了堕落的克拉西斯。我们发誓，绝不会再释放这个恐怖的东西。', '伟大的贤者苏尔西斯在柯泰克和我的帮助下建立了一道魔法屏障，封印了堕落的克拉西斯。我们发誓，绝不会再释放这个恐怖的东西。', 28153),
(153539, 'zhCN', '那次毁灭中施放的巨大力量，让我们的土地被永远地改变。', '那次毁灭中施放的巨大力量，让我们的土地被永远地改变。', 28153),
(153538, 'zhCN', '只有借助神灵的干涉，我们才能有生路。塞塔里斯牺牲了自己压制住克拉西斯，但在那之前克拉西斯摧毁了这片土地中央的一座古老金字塔。', '只有借助神灵的干涉，我们才能有生路。塞塔里斯牺牲了自己压制住克拉西斯，但在那之前克拉西斯摧毁了这片土地中央的一座古老金字塔。', 28153),
(153537, 'zhCN', '很久之前，在这里变成沙漠之前，一个可怕的克拉西斯战争使者降临在我们的土地上。他屠杀了出现在自己面前的所有生灵，无论是巨魔还是蛇人。', '很久之前，在这里变成沙漠之前，一个可怕的克拉西斯战争使者降临在我们的土地上。他屠杀了出现在自己面前的所有生灵，无论是巨魔还是蛇人。', 28153),
(153536, 'zhCN', '', '我们必须警惕部落。他们还在进攻广场。', 28153),
(153535, 'zhCN', '', '如果你在外面看到有东西想入侵我的镇子，就发出警告，我会感激不尽。', 28153),
(153534, 'zhCN', '', '所有人都指望着我来领导镇子，我不会让他们失望的！', 28153),
(153533, 'zhCN', '', '所有人都安全了……但只是暂时的。', 28153),
(153532, 'zhCN', '那不是石头，是把钥匙。那是控制一个强大而恐怖力量的钥匙之一。', '那不是石头，是把钥匙。那是控制一个强大而恐怖力量的钥匙之一。', 28153),
(153531, 'zhCN', '噢！好像有块石头。', '噢！好像有块石头。', 28153),
(153530, 'zhCN', '“小心啊，大海的女儿。”', '“小心啊，大海的女儿。”', 28153),
(153529, 'zhCN', '化作对同胞绝望的呼喊，', '化作对同胞绝望的呼喊，', 28153),
(153528, 'zhCN', '家人背叛的罪。', '家人背叛的罪。', 28153),
(153527, 'zhCN', '', '这个矮人答应过我，给你的勇士更好的装备来拯救我的人民。我愿意冒险。', 28153),
(153526, 'zhCN', '深埋在海底的伤悲，', '深埋在海底的伤悲，', 28153),
(153525, 'zhCN', '女儿却袖手旁观。', '女儿却袖手旁观。', 28153),
(153524, 'zhCN', '当他面对，敌人势如潮水', '当他面对，敌人势如潮水', 28153),
(153523, 'zhCN', '危机在等待！', '危机在等待！', 28153),
(153522, 'zhCN', '乘风破浪，来到遥远陆地，', '乘风破浪，来到遥远陆地，', 28153),
(153521, 'zhCN', '期盼女儿平安。', '期盼女儿平安。', 28153),
(153520, 'zhCN', '扬帆千里，只为把她找寻，', '扬帆千里，只为把她找寻，', 28153),
(153519, 'zhCN', '我想我们得让这位勇士和钻石的王者走一趟了？', '', 28153),
(153518, 'zhCN', '父亲随她而去，', '父亲随她而去，', 28153),
(153517, 'zhCN', '当她远离，穿越深海西行，', '当她远离，穿越深海西行，', 28153),
(153516, 'zhCN', '为何，一去不返？', '为何，一去不返？', 28153),
(153515, 'zhCN', '我们的荣耀，因为你而存在，', '我们的荣耀，因为你而存在，', 28153),
(153514, 'zhCN', '为何？昨日时光你都忘记？', '为何？昨日时光你都忘记？', 28153),
(153513, 'zhCN', '为何？为何？哦大海的女儿？', '为何？为何？哦大海的女儿？', 28153),
(153512, 'zhCN', '因为她的离开。', '因为她的离开。', 28153),
(153511, 'zhCN', '英雄陨落，在塞拉摩，', '英雄陨落，在塞拉摩，', 28153),
(153510, 'zhCN', '水手为谁拼搏。', '水手为谁拼搏。', 28153),
(153509, 'zhCN', '血融浪波，在卡利姆多，', '血融浪波，在卡利姆多，', 28153),
(153508, 'zhCN', '随风去，沉落海底。', '随风去，沉落海底。', 28153),
(153507, 'zhCN', '海风扬起，那心碎的话语，', '海风扬起，那心碎的话语，', 28153),
(153506, 'zhCN', '你听，他在呼喊。', '你听，他在呼喊。', 28153),
(153505, 'zhCN', '“小心，小心，大海的女儿。”', '“小心，小心，大海的女儿。”', 28153),
(153504, 'zhCN', '日安，$r。', '', 28153),
(153502, 'zhCN', '你口袋里有东西吗？', '你口袋里有东西吗？', 28153),
(153501, 'zhCN', '我会在这里照看防御工事。再次感谢你，朋友。', '我会在这里照看防御工事。再次感谢你，朋友。', 28153),
(153500, 'zhCN', '', '', 28153),
(153499, 'zhCN', '', '仆从！消灭他们！', 28153),
(153498, 'zhCN', '没有你和中士的帮忙，我是没办法逃出来的。再次感谢。', '没有你和中士的帮忙，我是没办法逃出来的。再次感谢。', 28153),
(153497, 'zhCN', '', '我会通知祖尔。他会判断这件事是否需要拉斯塔哈过问。', 28153),
(153496, 'zhCN', '干掉他们，别让他们闯进来！', '', 28153),
(153495, 'zhCN', '接下来我们要一口气冲到码头。你准备好了就说一声，$n。', '', 28153),
(153494, 'zhCN', '你想死吗？', '', 28153),
(153493, 'zhCN', '别害我们被发现了，$n。', '', 28153),
(153492, 'zhCN', '你想害死我们吗？', '', 28153),
(153491, 'zhCN', '嘿！别乱跑！', '', 28153),
(153490, 'zhCN', '快回来，伙计！', '', 28153),
(153489, 'zhCN', '是$n，感谢圣光！我会前往神殿的，这里不安全。', '', 28153),
(153488, 'zhCN', '但愿你永远不用做出这种抉择。', '', 28153),
(153487, 'zhCN', '你要时刻牢记，分清忠诚与荣耀的区别。', '', 28153),
(153486, 'zhCN', '你的意思是？', '你的意思是？', 28153),
(153485, 'zhCN', '看看她都做了什么，我永远不会回到她所掌控下的部落。', '', 28153),
(153484, 'zhCN', '你以为你是被派来把我带回奥格瑞玛、带回大酋长身边的吗？你错了。', '', 28153),
(153483, 'zhCN', '是时候对风险投资公司进行战略性的打击了！', '', 28153),
(153482, 'zhCN', '就等你下令了，$n。', '', 28153),
(153477, 'zhCN', '', '别就这么死了。还有事情等着你做呢。', 28153),
(153476, 'zhCN', '', '别去和邦桑迪作伴，$n。', 28153),
(153475, 'zhCN', '', '你还能走呢。', 28153),
(153474, 'zhCN', '', '复活吧，$n。一切都还没有结束。', 28153),
(153473, 'zhCN', '', '我的神灵不会任凭你死亡，$n。', 28153),
(153472, 'zhCN', '看来我们的情报有误，并非所有蛇人都是坏的。', '看来我们的情报有误，并非所有蛇人都是坏的。', 28153),
(153471, 'zhCN', '这是个双人游戏！', '这是个双人游戏！', 28153),
(153470, 'zhCN', '', '崭新的巨魔帝国即将到来。我们长久的静滞结束了！', 28153),
(153469, 'zhCN', '', '祖尔预言过这一天。崛起……崛起吧，鲜血的信徒。准备进入世界的新时代！', 28153),
(153468, 'zhCN', '不！不……', '不！不……', 28153),
(153467, 'zhCN', '你竟敢抢走我的份额……', '你竟敢抢走我的份额……', 28153),
(153466, 'zhCN', '你会遭报应的……', '你会遭报应的……', 28153),
(153465, 'zhCN', '英雄们，跟我来！', '', 28153),
(153464, 'zhCN', '我会……抓住你……', '我会……抓住你……', 28153),
(153463, 'zhCN', '你死定了！你们都死定了！', '你死定了！你们都死定了！', 28153),
(153462, 'zhCN', '你以为你能抢走我那份？', '你以为你能抢走我那份？', 28153),
(153461, 'zhCN', '叛徒！我会砍下你的脑袋！', '叛徒！我会砍下你的脑袋！', 28153),
(153460, 'zhCN', '背叛者！你们都是背叛者！', '背叛者！你们都是背叛者！', 28153),
(153459, 'zhCN', '尤朵拉船长……带领我们走向胜利……', '', 28153),
(153458, 'zhCN', '新鲜的肉？水鼠帮！开饭了！', '', 28153),
(153457, 'zhCN', '今天，你们战斗的咆哮和武器撞击的声音将上达伟大神灵的天听！而阵亡者将回归……神的怀抱。', '', 28153),
(153456, 'zhCN', '赐予她光荣的死亡……', '', 28153),
(153455, 'zhCN', '赐予他光荣的死亡……', '', 28153),
(153454, 'zhCN', '嗯啊？！', '', 28153),
(153453, 'zhCN', '彼界再见吧……', '', 28153),
(153452, 'zhCN', '现在的你已经没有神灵的祝福了。', '', 28153),
(153451, 'zhCN', '为了赞达拉！', '', 28153),
(153450, 'zhCN', '成交！炫彩之剑，成交价281金币！拿着这把剑回头率一定很高。', '', 28153),
(153449, 'zhCN', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t你被|cFFFF0000|Hspell:260838|h[自控导弹]|h|r瞄准了！', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t你被|cFFFF0000|Hspell:260838|h[自控导弹]|h|r瞄准了！', 28153),
(153448, 'zhCN', '今天属于库尔提拉斯！', '', 28153),
(153447, 'zhCN', '今天，鲜血将染红这片土地。', '', 28153),
(153446, 'zhCN', '一切结束前，战斗必须继续。', '', 28153),
(153445, 'zhCN', '现在安静下来！战斗还没有结束！', '', 28153),
(153444, 'zhCN', '现在，死斗即将上演！请保持耐心。', '', 28153),
(153443, 'zhCN', '成交！闹鬼的纪念品，成交价18金币！老实说，这东西哪怕卖一个铜板我都不买。不过反正不是我出钱！', '', 28153),
(153442, 'zhCN', '噢，噢，噢。不错，这招不错。', '', 28153),
(153441, 'zhCN', '你死了，但也没当上真正的库尔提拉斯人。', '', 28153),
(153440, 'zhCN', '哎呀，糟糕！', '', 28153),
(153439, 'zhCN', '今晚属于库尔提拉斯！', '', 28153),
(153438, 'zhCN', '这场战斗不太可能有多公平，所以大家最好保持距离，好吗？现在，准备好了吗？', '', 28153),
(153437, 'zhCN', '只有最后活下来的那个人才能赢得这份殊荣。', '', 28153),
(153436, 'zhCN', '朋友们！我们今天聚集于此，来见证这些强盗，土匪，这些坏事做尽的人一起争夺真正的库尔提拉斯人的名号！', '', 28153),
(153435, 'zhCN', '成交！这位可爱的女士以1412金币的价格竞得爱情火箭！她绝对会成为镇上的舆论焦点！', '', 28153),
(153434, 'zhCN', '成交！前面这位年轻人以756金币的价格竞得无畏肩铠！虽然你好像穿不了，但那没关系！', '', 28153),
(153433, 'zhCN', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t 艾泽洛克正在施放|cFFFF0000|Hspell:257597|h[艾泽里特注入]|h|r！', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t 艾泽洛克正在施放|cFFFF0000|Hspell:257597|h[艾泽里特注入]|h|r！', 28153),
(153432, 'zhCN', '叛徒！抓住她！', '', 28153),
(153431, 'zhCN', '现在对我们来说最紧要的事是不能让钥匙落在柯泰克手上。快，我们的神殿就在前面。', '', 28153),
(153430, 'zhCN', '我偷偷地把它塞进一个刚被他们俘虏的囚犯的口袋里。我确信他称自己为“詹姆斯”。', '', 28153),
(153429, 'zhCN', '那帮蠢材！他们抓住了我，然后搜了我的身，不过我已经把钥匙藏在了他们猜不到的地方。', '', 28153),
(153428, 'zhCN', '但是柯泰克背叛了我们，苏尔西斯也被杀了。现在柯泰克和他的无信者手下在追捕我，想要夺走我的钥匙。', '', 28153),
(153427, 'zhCN', '很久以前，我们三人——柯泰克、苏尔西斯和我，一起领导着我们的人民。我们的神灵把三把钥匙托付给了我们三人保护。这三把钥匙将一个古老而邪恶的力量封印在沙漠之下。', '', 28153),
(153426, 'zhCN', '我们的神殿是对抗无信者的最后壁垒！', '', 28153),
(153425, 'zhCN', '', '是的，是的。下面似乎有点小问题。但还不至于让我们劳烦陛下。', 28153),
(153424, 'zhCN', '', '跟洛阿神灵讨价还价的日子结束了。鲜血的时代开始了！', 28153),
(153423, 'zhCN', '', '别为几项小罪而惴惴不安。我们有更重要的问题需要解决。', 28153),
(153421, 'zhCN', '', '希望你喜欢！', 28153),
(153419, 'zhCN', '', '给你。我不能让你饿着肚子去，对吧？', 28153),
(153418, 'zhCN', '', '啊，这些真是太完美了！', 28153),
(153417, 'zhCN', '', '稍等一会，亲爱的，我有东西给你。', 28153),
(153416, 'zhCN', '干得好！你的攻击让赞达拉帝国都为之颤抖！', '', 28153),
(153415, 'zhCN', '我要选择风之主宰帕库。', '我要选择风之主宰帕库。', 28153),
(153414, 'zhCN', '我要选择兽群主宰贡克。', '我要选择兽群主宰贡克。', 28153),
(153413, 'zhCN', '赞达拉巨魔将一头驯服的野兽牢牢栓住，以为这样就安全了。让他们知道自己犯下了大错！', '', 28153),
(153412, 'zhCN', '终于，激流堡回到了我们的手上。', '', 28153),
(153411, 'zhCN', '去死吧，杂种！', '', 28153),
(153410, 'zhCN', '真是自不量力。', '', 28153),
(153409, 'zhCN', '没人会想念那家伙的。', '', 28153),
(153408, 'zhCN', '终有一天，激流堡会重回联盟的怀抱。', '', 28153),
(153407, 'zhCN', '让死亡降临到部落头上！', '', 28153),
(153406, 'zhCN', '第三师，发射！', '', 28153),
(153405, 'zhCN', '我要从祖达萨选出一名神灵来替换代表这里的神。', '我要从祖达萨选出一名神灵来替换代表这里的神。', 28153),
(153404, 'zhCN', '城墙单位，准备放箭！', '', 28153),
(153403, 'zhCN', '往昔的回响，起来吧！', '', 28153),
(153402, 'zhCN', '阿拉索之魂会撕碎你！', '', 28153),
(153401, 'zhCN', '邪恶将无处可藏，就算在这片土地上也是。你做得很好。', '', 28153),
(153400, 'zhCN', '各位先祖，起来吧，保护你们的家园。', '', 28153),
(153399, 'zhCN', '倒在我刀下的巨魔成千上万，你也不会例外。', '', 28153),
(153398, 'zhCN', '赞达拉帝国又一次取得了胜利！做得好，部落的勇士。', '', 28153),
(153397, 'zhCN', '这片蛮荒之地有一个邪恶之物。把它赶出去！', '', 28153),
(153396, 'zhCN', '丛林中最强大的生物正在威胁这片区域。把它找出来，干掉它！', '', 28153),
(153395, 'zhCN', '正义必胜。', '', 28153),
(153394, 'zhCN', '净化了一个！', '', 28153),
(153393, 'zhCN', '你的命运已经注定。', '', 28153),
(153392, 'zhCN', '这是对你的审判。', '', 28153),
(153391, 'zhCN', '激流堡虽然失守，但联盟永远不会陷落。', '', 28153),
(153390, 'zhCN', '以圣光之力！', '', 28153),
(153389, 'zhCN', '别被圣光烧焦了，虫子！', '', 28153),
(153388, 'zhCN', '圣光会惩戒你。', '', 28153),
(153387, 'zhCN', '又一个威胁被消灭了，这是联盟的又一次胜利！', '', 28153),
(153386, 'zhCN', '圣光必将获胜！', '', 28153),
(153385, 'zhCN', '', '我是首席记载者。国王让我在石头上记录我们的历史，让历史得以流传亿万年。', 28153),
(153384, 'zhCN', '让圣光净化你！', '', 28153),
(153383, 'zhCN', '我的人民会知道你的名字，赞达拉的勇士。做得好！', '', 28153),
(153382, 'zhCN', '以圣光的名义净化你们！', '', 28153),
(153381, 'zhCN', '为了圣光！', '', 28153),
(153380, 'zhCN', '邪恶就像扼杀生灵的藤蔓一般在此滋生。消灭它们，保护我们的军队。', '', 28153),
(153379, 'zhCN', '我绝不会让我的人民受到威胁。碾碎他们！', '', 28153),
(153378, 'zhCN', '道路已经扫清，我们又能在这片区域增派兵力以对抗赞达拉巨魔了。谢谢你，勇士。', '', 28153),
(153377, 'zhCN', '以赞达拉帝国的名义，又一名敌人倒下了。', '', 28153),
(153376, 'zhCN', '我们的军队饱受这一恶心生物的威胁。为了联盟，消灭它！', '', 28153),
(153375, 'zhCN', '在我的国度不容许这样的威胁存在。消灭它们！', '', 28153),
(153374, 'zhCN', '你准备好出发后，就跳上三轮摩托。', '', 28153),
(153372, 'zhCN', '', '这些纳迦很害怕。有东西正在驱使他们。这不仅仅是对艾萨拉女王的忠诚。', 28153),
(153371, 'zhCN', '', '你好。', 28153),
(153370, 'zhCN', '你们就这点能耐？哈！真是不堪一击！', '', 28153),
(153369, 'zhCN', '哈哈，真爽！', '', 28153),
(153368, 'zhCN', '这下你可完蛋了。', '', 28153),
(153367, 'zhCN', '代我向你祖宗问好！', '', 28153),
(153366, 'zhCN', '你会后悔的！', '', 28153),
(153365, 'zhCN', '这一击灌注了我所有的力量。', '', 28153),
(153364, 'zhCN', '哈哈！我就喜欢这么干！', '', 28153),
(153363, 'zhCN', '滚远点！', '', 28153),
(153362, 'zhCN', '为了卡兹莫丹！', '', 28153),
(153361, 'zhCN', '送你一份礼物！', '', 28153),
(153360, 'zhCN', '给你一锤。', '', 28153),
(153359, 'zhCN', '喂，你，接着！', '', 28153),
(153357, 'zhCN', '放弃抵抗吧！', '', 28153),
(153351, 'zhCN', '麦格尼，艾泽拉斯想要我做什么？', '麦格尼，艾泽拉斯想要我做什么？', 28153),
(153350, 'zhCN', '击退那些猩猩后，我们就可以全力对抗部落了。做得很好。', '', 28153),
(153349, 'zhCN', '这些猩猩吸收了卡亚矿石的精华，获得了超乎寻常的智慧。我们不能让它们将这种智慧散播给其它猩猩。', '', 28153),
(153348, 'zhCN', '探测到“原子”发射信号', '探测到“原子”发射信号', 28153),
(153347, 'zhCN', '部落以为可以让我们沦为囚犯，真是异想天开。多亏你，我们的人民自由了。做得好！', '', 28153),
(153346, 'zhCN', '我的人还有一个在外面，我不能休息。', '我的人还有一个在外面，我不能休息。', 28153),
(153345, 'zhCN', '他们永远不会发现我们来了。哈！谢谢你，勇士。', '', 28153),
(153344, 'zhCN', '部落以为他们能秘密监视我们在祖达萨的驻地，他们错了！废掉他们的耳目，让他们知道，联盟不可撼动。', '', 28153),
(153343, 'zhCN', '没有钥匙的话，我绝对不想再进去！', '没有钥匙的话，我绝对不想再进去！', 28153),
(153342, 'zhCN', '再等一会，就能做个了断了！', '再等一会，就能做个了断了！', 28153),
(153341, 'zhCN', '为什么索加登把我们丢在锡罐里这么久？啊！', '为什么索加登把我们丢在锡罐里这么久？啊！', 28153),
(153340, 'zhCN', '这里比拉格纳罗斯的屁股还热！', '这里比拉格纳罗斯的屁股还热！', 28153),
(153339, 'zhCN', '我会派人告诉维姆班恩，我们已经牢牢守住这片区域。谢谢你的帮忙，$n。', '', 28153),
(153338, 'zhCN', '都在一天内完成！', '', 28153),
(153337, 'zhCN', '太恐怖了！', '', 28153),
(153336, 'zhCN', '我们正在从火焰之地抽取力量，但这次不会召唤出什么危险的东西。', '', 28153),
(153335, 'zhCN', '别怕，你吓得胡子都在发抖，塞林。我可不像巫王索瑞森那么愚蠢。', '', 28153),
(153334, 'zhCN', '小心你召唤出来的东西，铁砧守卫。', '', 28153),
(153333, 'zhCN', '完美的召唤，伙计们。你能控制它了，$n。让那帮部落知道，惹怒黑铁矮人会有什么后果！', '', 28153),
(153332, 'zhCN', '$C，放些炉渣在不稳定的熔岩上。然后做好准备。', '', 28153),
(153331, 'zhCN', '激流堡之战开始了！', '', 28153),
(153330, 'zhCN', '激流堡之战将在30秒后开始。', '', 28153),
(153329, 'zhCN', '还好，不是什么大问题。', '', 28153),
(153328, 'zhCN', '等等，你一直把钥匙放在自己身上？', '', 28153),
(153327, 'zhCN', '看来萨满还在钻探机里，我就说我好像忘了什么。', '', 28153),
(153326, 'zhCN', '很好的开始，还少了什么？', '', 28153),
(153325, 'zhCN', '孩子，你根本不知道你面对的是何种力量。', '', 28153),
(153324, 'zhCN', '<伸手进去拉一个似乎像是建筑的东西。>', '<伸手进去拉一个似乎像是建筑的东西。>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153323, 'zhCN', '<伸手进去拽点什么出来。>', '<伸手进去拽点什么出来。>', 28153),
(153322, 'zhCN', '<一个虫洞在你面前展开。很显然你应该可以用这个虫洞以某种方式制造一个建筑。>', '', 28153),
(153321, 'zhCN', '不要考验我的耐心，虫子。死吧。', '', 28153),
(153320, 'zhCN', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_CTHUN.BLP:20|t%s开始施放|cFFFF0000|Hspell:264382|h[眼棱]|h|r！', '远处出现了一个幻象……', 28153),
(153319, 'zhCN', '海洋就是我们的家。但有什么东西正逼着我们离开，希望你能解决！', '', 28153),
(153318, 'zhCN', '你要去见那些求知者，对吗？这船很结实，你会很安全的。', '', 28153),
(153317, 'zhCN', '船都不见了。那些之前常年风平浪静的地方，也出现了风暴。其他人都不敢下水了。', '', 28153),
(153316, 'zhCN', '一直有传言说，海岸上发生了奇怪的事。', '', 28153),
(153315, 'zhCN', '如您所愿。', '', 28153),
(153314, 'zhCN', '还有……请确保吉安娜的安全。', '', 28153),
(153313, 'zhCN', '在库尔提拉斯建立指挥中心。我们的计划绝不能失败。', '', 28153),
(153312, 'zhCN', '那就让一艘第七军团的船随行。', '', 28153),
(153311, 'zhCN', '哼。如履平地。', '', 28153),
(153310, 'zhCN', '深渊会拒绝你，因为你的人民怀念你。', '', 28153),
(153309, 'zhCN', '你代表的只是憎恨和痛苦。', '', 28153),
(153308, 'zhCN', '聆听风暴的觉醒，拥抱你的终结。', '', 28153),
(153307, 'zhCN', '不要害怕，你的审判就要来临了。', '', 28153),
(153306, 'zhCN', '那么吉恩……习惯坐船吗？', '', 28153),
(153305, 'zhCN', '聆听人们的哭喊，接受你的死期。', '', 28153),
(153304, 'zhCN', '你已经无法救赎。', '', 28153),
(153303, 'zhCN', '你的生命充满遗憾。', '', 28153),
(153302, 'zhCN', '愿你的灵魂永远凋零。', '', 28153),
(153301, 'zhCN', '', '要是我有武器……', 28153),
(153300, 'zhCN', '', '他们没杀掉我。这是他们犯下的第一个错误。', 28153),
(153299, 'zhCN', '', '他们毁了我的农场，还敢抓我。我绝对不会轻易放过他们！', 28153),
(153298, 'zhCN', '在解决掉这个威胁之前，我是不会离开的！', '在解决掉这个威胁之前，我是不会离开的！', 28153),
(153297, 'zhCN', '他们要为自己的所作所为付出代价！', '他们要为自己的所作所为付出代价！', 28153),
(153296, 'zhCN', '我得好好教训一下这些野猪人！', '我得好好教训一下这些野猪人！', 28153),
(153295, 'zhCN', '', '下次有空，记得再来看看。', 28153),
(153294, 'zhCN', '', '终于，自由了！我要让这些恶心的野猪人看看，在我的农场捣乱会有什么下场！', 28153),
(153293, 'zhCN', '嘿，看看是谁终于醒了。', '', 28153),
(153292, 'zhCN', '小心……小心……大海的女儿……唔唔……', '', 28153),
(153291, 'zhCN', '让那个东西……离我远点。我只想……喝个……痛快！*嗝儿！*', '让那个东西……离我远点。我只想……喝个……痛快！*嗝儿！*', 28153),
(153290, 'zhCN', '我妹妹的丈夫出海航行前给了她一株海潮茎杆，现在已经四个月过去了。那朵花第三天就枯萎了。她悲伤得不能自已，但也早就料到了这一天，也提前存够了钱来抚养孩子。', '我妹妹的丈夫出海航行前给了她一株海潮茎杆，现在已经四个月过去了。那朵花第三天就枯萎了。她悲伤得不能自已，但也早就料到了这一天，也提前存够了钱来抚养孩子。', 28153),
(153289, 'zhCN', '我们楼上有床，地下室有地方可以存放装备。\n\n虽然算不上豪华，但总比在外面跟女巫睡一起要好。', '我们楼上有床，地下室有地方可以存放装备。\n\n虽然算不上豪华，但总比在外面跟女巫睡一起要好。', 28153),
(153288, 'zhCN', '有些水手认为是自己倒霉，甚至是命中注定。其他人则只希望自己所爱的人别收到自己的死讯。这两种想法我都不喜欢。', '有些水手认为是自己倒霉，甚至是命中注定。其他人则只希望自己所爱的人别收到自己的死讯。这两种想法我都不喜欢。', 28153),
(153287, 'zhCN', '记住，只要这些树还活着，我们就必须活下去。我们不能把命丢在这里。', '', 28153),
(153286, 'zhCN', '我们去找同胞。只要我们齐心协力，也许就能治愈困扰德鲁斯瓦的病痛。', '', 28153),
(153285, 'zhCN', '', '但是……！', 28153),
(153284, 'zhCN', '我们带走了树苗，这就是灰树林里唯一重要的东西。即使真菌人没有进攻，南边的腐化也会扩散到我们这里。', '', 28153),
(153283, 'zhCN', '', '走？去哪？灰树林是我们的家，墨文。现在灰树林里全是孢子。我们不能坐视不管！', 28153),
(153282, 'zhCN', '干得好，艾米丽。现在，我想我们该走了。', '', 28153),
(153278, 'zhCN', '关于海潮茎秆，你能告诉我什么？', '关于海潮茎秆，你能告诉我什么？', 28153),
(153277, 'zhCN', '鼓声', '鼓声', 28153),
(153276, 'zhCN', '|cFF0000FF(任务)|r启航前往祖达萨。', '|cFF0000FF(任务)|r启航前往祖达萨。', 28153),
(153275, 'zhCN', '啊，我的力量回来了！', '', 28153),
(153274, 'zhCN', '这里本来很安静，接着来了一场风暴，其他求知者就再也没有回来，$c。到底发生了什么事？', '', 28153),
(153273, 'zhCN', '向你致以最真诚的感谢，对于给你造成的麻烦，这是我的一些个人私藏作为补偿。我必须马上出发了，你做得很好！', '', 28153),
(153272, 'zhCN', '哎呀，我这里有点小状况。你就发发善心，帮我一把吧。', '', 28153),
(153271, 'zhCN', '啊，谢谢，你真是好人。这是给你的小报酬。回头见！', '啊，谢谢，你真是好人。这是给你的小报酬。回头见！', 28153),
(153270, 'zhCN', '', '喂！你得帮帮我，伙计！我一个人在这里即孤独又绝望，你懂吗？', 28153),
(153269, 'zhCN', '你知道我不可能把所有的艾泽里特都给你，这些应该足以表达谢意了，还请让开，别挡我的路。', '', 28153),
(153268, 'zhCN', '好了伙计，能帮我解开这个吗？', '', 28153),
(153267, 'zhCN', '听着，这只是个道具？看到了吗？感受下！$b$b现在可以跟他们说，让我离开这里吗？只是个玩笑而已！霍格并没有真的恐吓暴风城！', '听着，这只是个道具？看到了吗？感受下！$b$b现在可以跟他们说，让我离开这里吗？只是个玩笑而已！霍格并没有真的恐吓暴风城！', 28153),
(153266, 'zhCN', '', '谢谢你！我猜你肯定想要一些艾泽里特来作为报酬。我也觉得这很公平。', 28153),
(153265, 'zhCN', '', '你好啊！你能帮帮我吗？', 28153),
(153264, 'zhCN', '', '也许这是我罪有应得。', 28153),
(153263, 'zhCN', '', '我必须承受这一切……', 28153),
(153262, 'zhCN', '她回来杀我们了！', '', 28153),
(153261, 'zhCN', '凶手！', '凶手！', 28153),
(153260, 'zhCN', '叛徒！', '叛徒！', 28153),
(153259, 'zhCN', '是大海的女儿！', '', 28153),
(153258, 'zhCN', '', '吉安娜女士……真的……是她？', 28153),
(153257, 'zhCN', '', '快，我们回家。马上！', 28153),
(153256, 'zhCN', '妈妈，那位女士是谁？', '妈妈，那位女士是谁？', 28153),
(153255, 'zhCN', '哈姆莱特……你做块菌也做够了……', '', 28153),
(153254, 'zhCN', '我的头……我的猪怎么了！？', '', 28153),
(153253, 'zhCN', '我会向人们歌颂你今天的伟大胜利的，呃……所以你一定要赢啊！', '', 28153),
(153252, 'zhCN', '回到赤红森林！', '回到赤红森林！', 28153),
(153250, 'zhCN', '别让平民靠近！构筑防线！', '', 28153),
(153249, 'zhCN', '%s逃跑了。', '%s逃跑了。', 28153),
(153248, 'zhCN', '', '但现在，他们却将我视作罪犯。', 28153),
(153247, 'zhCN', '', '城市的卫兵还是像以往一样纪律严明。父亲生前很为他们骄傲。', 28153),
(153246, 'zhCN', '别催我！我在想办法救你的主人！', '', 28153),
(153245, 'zhCN', '嘿，$n！这边！', '嘿，$n！这边！', 28153),
(153244, 'zhCN', '真是倒霉！我本来在去朵瓦萨的路上，然后我的野兽就病了。就像常言说的，真是祸不单行。', '', 28153),
(153243, 'zhCN', '我是拉雷！', '我是拉雷！', 28153),
(153242, 'zhCN', '外面等着送死的部落可真不少。记得给我留点儿，行吗？', '外面等着送死的部落可真不少。记得给我留点儿，行吗？', 28153),
(153241, 'zhCN', '让它受些苦吧。', '让它受些苦吧。', 28153),
(153240, 'zhCN', '我们接到了杀死它的命令。', '我们接到了杀死它的命令。', 28153),
(153239, 'zhCN', '', '跟紧了，朋友。我们可不想暴露自己。', 28153),
(153238, 'zhCN', '', '集中注意力，$n。', 28153),
(153237, 'zhCN', '', '你想让别人注意到我们吗？', 28153),
(153236, 'zhCN', '噢，波利斯……我想我们劫掠的日子已经结束了……', '', 28153),
(153235, 'zhCN', '别碰我的狮鹫！', '', 28153),
(153234, 'zhCN', '这才对嘛。看看这些艾泽里特！', '', 28153),
(153233, 'zhCN', '老大！你在这儿！', '', 28153),
(153231, 'zhCN', '让路！高危囚犯正在通过！', '', 28153),
(153230, 'zhCN', '停下！表明你们的来意！', '', 28153),
(153229, 'zhCN', '', '没时间瞎逛了。', 28153),
(153228, 'zhCN', '闭……闭嘴。', '', 28153),
(153227, 'zhCN', '哦……也许是一个女巫干的！', '', 28153),
(153226, 'zhCN', '你的另一个斥候，加里维克斯……这个已经死了。', '', 28153),
(153225, 'zhCN', '我们必须进入城市的中心，疏散那里剩下的市民。', '', 28153),
(153224, 'zhCN', '当心……', '', 28153),
(153223, 'zhCN', '', '我们就要成功了！快一点，英雄们！', 28153),
(153222, 'zhCN', '', '别停下！', 28153),
(153220, 'zhCN', '勇士们，跟我来！我们在城堡里集合！这是大酋长的命令！', '', 28153),
(153217, 'zhCN', '', '萨鲁法尔！你去哪儿了？', 28153),
(153216, 'zhCN', '小心，塌陷的农田仍然很危险！右边的路应该安全一些，并且通往风车磨坊。迪尔的农场就在它后面。', '', 28153),
(153215, 'zhCN', '', '如果你愿意战斗的话，就肯定能帮上忙。', 28153),
(153214, 'zhCN', '', '我的药水用完了，又有好多蛇人挡在我回货车的路上。', 28153),
(153213, 'zhCN', '', '你还活着吗？你的武器还好用吗？', 28153),
(153212, 'zhCN', '', '今天还不行，蛇人！', 28153),
(153211, 'zhCN', '请把我带回入口。', '请把我带回入口。', 28153),
(153210, 'zhCN', '塞塔里斯的化身复活了，这都是你和你盟友的功劳。', '塞塔里斯的化身复活了，这都是你和你盟友的功劳。', 28153),
(153209, 'zhCN', '麦格尼，送我回赞达拉。\n', '麦格尼，送我回赞达拉。\n', 28153),
(153207, 'zhCN', '啊，这个圣物可以带我们去到想去的地方。来吧，勇士。', '', 28153),
(153206, 'zhCN', '击败所有剩余的入侵者。', '击败所有剩余的入侵者。', 28153),
(153205, 'zhCN', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|t化身加入了你，她将用|cFFFF0000|Hspell:269670|h[强化]|h|r来帮助你结束战斗！', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|t化身加入了你，她将用|cFFFF0000|Hspell:269670|h[强化]|h|r来帮助你结束战斗！', 28153),
(153204, 'zhCN', '<你看见面前就是塞塔里斯的化身。她虽然还活着，但是却因为巨魔的行径而变得十分虚弱。你周围所有的防御性结界都活了过来……>', '<你看见面前就是塞塔里斯的化身。她虽然还活着，但是却因为巨魔的行径而变得十分虚弱。你周围所有的防御性结界都活了过来……>', 28153),
(153203, 'zhCN', '|cffffff00+$1i木头|r', '|cffffff00+$1i木头|r', 28153),
(153202, 'zhCN', '你们听到公主的话了！开火！', '', 28153),
(153201, 'zhCN', '', '护盾！快撑不住了！', 28153),
(153199, 'zhCN', '不要惊慌！尽管我想我的出现的确有些唐突……我是麦格尼·铜须，艾泽拉斯的代言人。', '', 28153),
(153198, 'zhCN', '', '啊，你在这里啊，$n。来，我们需要商讨一些计划。', 28153),
(153197, 'zhCN', '啊，你在这儿啊，$n。我必须要和你谈谈！', '', 28153),
(153196, 'zhCN', '[IGC - 听众与凯瑟琳在一起- 吉安娜的命运落到了凯瑟琳的手里。在女勋爵艾什凡的怂恿下，吉安娜被视作叛徒，凯瑟琳让人把吉安娜带走，去接受制裁。“她对我来说已经死了。”玩家被逮捕。]', '[IGC - 听众与凯瑟琳在一起- 吉安娜的命运落到了凯瑟琳的手里。在女勋爵艾什凡的怂恿下，吉安娜被视作叛徒，凯瑟琳让人把吉安娜带走，去接受制裁。“她对我来说已经死了。”]', 28153),
(153195, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t你成为了|cFFFF0000|Hspell:265212|h[育种]|h|r的目标！', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t 你是|cFFFF0000|Hspell:265212|h[育种]|h|r的目标！', 28153),
(153194, 'zhCN', '我们会给你恢复！', '我们会给你恢复！', 28153),
(153193, 'zhCN', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t 维克提斯开始施放|cFFFF0000|Hspell:265217|h[液化]|h|r！', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t 维克提斯开始施放|cFFFF0000|Hspell:265217|h[液化]|h|r！', 28153),
(153192, 'zhCN', '别理加里维克斯。我们是要去德鲁斯瓦侦察敌人的位置。赚钱是次要的。', '', 28153),
(153191, 'zhCN', '现在一切……归于沉寂。', '', 28153),
(153190, 'zhCN', '噢，我死了……', '', 28153),
(153189, 'zhCN', '去确保伊崔格和船长已经准备就绪了。我们要去赚上一笔！', '', 28153),
(153188, 'zhCN', '你……打败了我……', '', 28153),
(153187, 'zhCN', '我将自此……沉默。', '', 28153),
(153186, 'zhCN', '住手，够了！', '', 28153),
(153185, 'zhCN', '恶棍，是你伤害了我！', '', 28153),
(153184, 'zhCN', '啊，我要死了！', '', 28153),
(153183, 'zhCN', '我的灵魂正在流失，我……不行了。', '', 28153),
(153182, 'zhCN', '', '你错了。你别想再伤害我的人民。你的疯狂行径到此为止了！', 28153),
(153180, 'zhCN', '', '没错，公主！', 28153),
(153177, 'zhCN', '有三个用于封印腐化的装置。', '', 28153),
(153174, 'zhCN', '[棒到没话说的过场动画。]', '[棒到没话说的过场动画。]', 28153),
(153173, 'zhCN', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t维克提斯施放了|cFFFF0000|Hspell:266948|h[瘟疫炸弹]|h|r！', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t维克提斯施放了|cFFFF0000|Hspell:266948|h[瘟疫炸弹]|h|r！', 28153),
(153172, 'zhCN', '', '上古之神？！这就是鲜血巨魔来袭的原因吗……', 28153),
(153171, 'zhCN', '数据已恢复。纳兹米尔的腐化是源自于囚禁于该地中心的上古之神。', '', 28153),
(153169, 'zhCN', '……还有1.1加仑的龙舌兰！', '……还有1.1加仑的龙舌兰！', 28153),
(153168, 'zhCN', '|cFF0000FF(任务)|r启航前往德鲁斯瓦。', '|cFF0000FF(任务)|r启航前往德鲁斯瓦。', 28153),
(153167, 'zhCN', '', '女妖之啸号是黑暗女王最好的战舰之一。她也许外表看起来没那么厉害，但是她坚固又善战。\n\n她的船长也不赖。', 28153),
(153166, 'zhCN', '是的，我准备好前往德鲁斯瓦了。', '是的，我准备好前往德鲁斯瓦了。', 28153),
(153165, 'zhCN', '别让那个地精误导你，$n。我们的任务是去收集联盟的情报，而不仅仅是尽可能多地掠夺艾泽里特。\n\n你准备好出发了吗？', '', 28153),
(153164, 'zhCN', '别让贸易大王把你带偏了。我们的首要目标是侦察……不是赚钱。', '', 28153),
(153163, 'zhCN', '我听说那里有许多的艾泽里特在等着我们。我们要做的就是去拿来，这交给你了。\n\n要是你被杀了，那你的帽子就归我！哈哈！', '', 28153),
(153162, 'zhCN', '继续恢复塞塔里斯的化身的生命值，并干掉任何来犯的入侵者。', '继续恢复塞塔里斯的化身的生命值，并干掉任何来犯的入侵者。', 28153),
(153161, 'zhCN', '干得好，$n。我们必须保持警惕，消灭神殿附近的林网蜘蛛。', '', 28153),
(153160, 'zhCN', '林网蜘蛛正在侵占神殿废墟。消灭那些害虫，并救出困在网里的信徒们。', '', 28153),
(153159, 'zhCN', '完全恢复塞塔里斯的化身的生命值。', '完全恢复塞塔里斯的化身的生命值。', 28153),
(153158, 'zhCN', '鬼鬼祟祟的蜘蛛！', '', 28153),
(153157, 'zhCN', '谢谢，$n！我欠你一条命。', '', 28153),
(153156, 'zhCN', '我又可以呼吸了！谢谢！', '', 28153),
(153155, 'zhCN', '这些蜘蛛什么都吃！', '', 28153),
(153154, 'zhCN', '谢谢！真是好险……', '', 28153),
(153153, 'zhCN', '我还以为自己死定了呢！', '', 28153),
(153152, 'zhCN', '你想让我们干什么？', '你想让我们干什么？', 28153),
(153151, 'zhCN', '不，求求你……', '不，求求你……', 28153),
(153150, 'zhCN', '', '那就上来！$n，我们要继续前进，找到艾什顿大师。我们到赤红森林汇合！', 28153),
(153149, 'zhCN', '我的骨头！疼！', '我的骨头！疼！', 28153),
(153148, 'zhCN', '哦，真是怀念啊。', '哦，真是怀念啊。', 28153),
(153147, 'zhCN', '你很无趣。让我把你变得……有趣一点。', '你很无趣。让我把你变得……有趣一点。', 28153),
(153146, 'zhCN', '告诉我，疼吗？', '告诉我，疼吗？', 28153),
(153145, 'zhCN', '我应该能。', '', 28153),
(153144, 'zhCN', '', '马登，你现在能赶路吗？', 28153),
(153143, 'zhCN', '镇子已经解放了，你们可以跟我说说发生了什么事吗？', '', 28153),
(153142, 'zhCN', '当然了！我不知道为什么你会需要我的帮助，但你拯救了我的家园，你会得到帮助的！\n\n不过可能要等一会儿。镇子现在一团乱。', '', 28153),
(153141, 'zhCN', '我们得赶紧离开这儿！', '我们得赶紧离开这儿！', 28153),
(153140, 'zhCN', '别是他们，别再来了！', '别是他们，别再来了！', 28153),
(153139, 'zhCN', '要不是你我就死了……', '要不是你我就死了……', 28153),
(153138, 'zhCN', '是部落！他们在这里干什么？', '是部落！他们在这里干什么？', 28153),
(153137, 'zhCN', '起锚，指挥官！', '起锚，指挥官！', 28153),
(153136, 'zhCN', '我能让你飞的比海鸥还快。你准备好了就跟我说一声。', '', 28153),
(153135, 'zhCN', '在找艾什顿吗？跟我来。我没看到他，但我看到他的学徒了。', '', 28153),
(153134, 'zhCN', '喔，这肯定不适合那些胆小……或者肠胃不好的家伙。', '', 28153),
(153133, 'zhCN', '我曾经听说过一种美味的小吃，它来自海对岸的沙漠。去收集秃鹫的翅膀和蝎刺。我打算制作新版本的小吃，带点劲头的那种。', '', 28153),
(153132, 'zhCN', '稳住方向，舵手。', '稳住方向，舵手。', 28153),
(153131, 'zhCN', '不，你这傻子，走那边！', '不，你这傻子，走那边！', 28153),
(153130, 'zhCN', '不洁者不得进入亡者大厅。', '', 28153),
(153129, 'zhCN', '不得前进。', '', 28153),
(153128, 'zhCN', '不准进入。', '', 28153),
(153127, 'zhCN', '回头见。', '', 28153),
(153126, 'zhCN', '嘿。', '', 28153),
(153125, 'zhCN', '', '我不是一个合格的老师。', 28153),
(153124, 'zhCN', '', '该休息了。', 28153),
(153123, 'zhCN', '', '你们都……下课吧。', 28153),
(153122, 'zhCN', '', '上课！', 28153),
(153121, 'zhCN', '', '是时候教你们“三要素”了：那就是符文、仪式和圣物！', 28153),
(153120, 'zhCN', '', '我应该给你们上一课了！', 28153),
(153119, 'zhCN', '现在该谁来看管藏酒呢？', '', 28153),
(153118, 'zhCN', '这一批酒……毁掉了。', '', 28153),
(153117, 'zhCN', '你休想拿走我们的藏酒！', '', 28153),
(153116, 'zhCN', '这些藏酒仅限贵宾使用！', '', 28153),
(153115, 'zhCN', '太棒了！这些可以让我撑好长一段时间。如果我没有一口气全吃光的话。', '', 28153),
(153114, 'zhCN', '你会惊异于外界的生物为生存做出的改变。鞭笞者拥有最具弹性、最美味的种子！去弄一些回来，但要小心它们的荆棘！', '', 28153),
(153113, 'zhCN', '……我喜欢你的想法，沃特。', '', 28153),
(153112, 'zhCN', '或者……既然我们已经拿到报酬了，要不我们告诉梅瑟福特我们遇袭了……然后我们自己把蜂蜜酒喝了？', '', 28153),
(153111, 'zhCN', '好吧……我想现在也安全了。我们把这些酒桶带给海瑟福特吧。', '', 28153),
(153110, 'zhCN', '我要出去寻找詹姆斯的线索，这期间就由你来指挥这艘船。我不会让他就这么困在那些狡猾的杂种手里的。', '我要出去寻找詹姆斯的线索，这期间就由你来指挥这艘船。我不会让他就这么困在那些狡猾的杂种手里的。', 28153),
(153109, 'zhCN', '那玩意儿正在往下滴蜂蜜!', '', 28153),
(153108, 'zhCN', '到这儿来，你这个愚蠢的海鸥！', '', 28153),
(153107, 'zhCN', '嗯……我已经完全准备好了。让我看看你的能耐吧，大自然！', '', 28153),
(153106, 'zhCN', '我们上吧！', '我们上吧！', 28153),
(153105, 'zhCN', '随时都会有更多凶猛的野兽袭击这里，$c，你要誓死保护蜂蜜酒！', '', 28153),
(153103, 'zhCN', '振作起来，布拉弗德！我们不能被他们打败！', '', 28153),
(153102, 'zhCN', '好了沃特，这就是我俩的葬身之地了。我不确定我们还得抵挡多少这样的野兽！', '', 28153),
(153101, 'zhCN', '%s将一个完全充能的艾泽里特火炮转向了攻城塔。', '', 28153),
(153100, 'zhCN', '$n！我们现在需要你！', '$n！我们现在需要你！', 28153),
(153099, 'zhCN', '该死的，莱纳德，我可没允许你离开！', '该死的，莱纳德，我可没允许你离开！', 28153),
(153098, 'zhCN', '剩下的人跟我来，我们要绕过敌人的侧翼。', '剩下的人跟我来，我们要绕过敌人的侧翼。', 28153),
(153097, 'zhCN', '很有趣。真是些精巧的小旅客。我很想看看它们会告诉我什么样的故事。', '', 28153),
(153096, 'zhCN', '通常来说，飞蛾只能活几个月。但是这里的飞蛾有点不对劲。请帮我抓几只回来。要轻一点，它们很纤弱。', '', 28153),
(153093, 'zhCN', '', '现在该谁来看场子？', 28153),
(153092, 'zhCN', '', '尘归尘，土归土。', 28153),
(153091, 'zhCN', '', '你会成为很好的肥料的。', 28153),
(153090, 'zhCN', '', '你将自食其果！', 28153),
(153089, 'zhCN', '', '我花园里有入侵者！', 28153),
(153088, 'zhCN', '', '撕成碎片。', 28153),
(153087, 'zhCN', '', '我的计划……很明确。', 28153),
(153086, 'zhCN', '', '我的编织预示了你的末日！', 28153),
(153085, 'zhCN', '', '你的末日已经到来！', 28153),
(153084, 'zhCN', '', '我应该把你的灵魂织到我的挂毯里去！', 28153),
(153083, 'zhCN', '一场痛快的狩猎。', '', 28153),
(153082, 'zhCN', '真是凶猛啊。', '', 28153),
(153081, 'zhCN', '从来没想到……自己会成为战利品，', '', 28153),
(153080, 'zhCN', '是时候出击了！', '', 28153),
(153079, 'zhCN', '你会成为我挂在墙上的战利品！', '', 28153),
(153078, 'zhCN', '狩猎开始了！', '', 28153),
(153077, 'zhCN', '上烤架的鲜肉！', '', 28153),
(153076, 'zhCN', '晚饭准备好了！', '', 28153),
(153075, 'zhCN', '神殿必须再次打开。我们救赎的机会来了！', '', 28153),
(153074, 'zhCN', '黑暗无法挡住我们的去路。', '', 28153),
(153073, 'zhCN', '干得漂亮。让我们永远铭记那些勇敢的峡谷甲虫，它们牺牲了自己，将我们从拉卡塔卡大王的恐怖中解放了出来！', '', 28153),
(153072, 'zhCN', '我们可是会一言不合就夺人性命的。', '', 28153),
(153071, 'zhCN', '看起来，你既缺乏戒律之心，也不懂处世之道。', '', 28153),
(153070, 'zhCN', '万物都有价值。甚至连你都有。', '', 28153),
(153069, 'zhCN', '沙漠吞噬多余的事物。', '', 28153),
(153068, 'zhCN', '沙漠会为我们指引方向。', '', 28153),
(153067, 'zhCN', '我们遵循沙漠的的指引。', '', 28153),
(153066, 'zhCN', '沙漠里有我们需要的一切。', '', 28153),
(153065, 'zhCN', '在沙漠中存活下来，意味着要在被遗忘的事物中寻找价值。', '', 28153),
(153064, 'zhCN', '请记住，万物皆有用处。', '', 28153),
(153063, 'zhCN', '有话直说。', '', 28153),
(153062, 'zhCN', '你好。', '', 28153),
(153061, 'zhCN', '你带来了什么？', '', 28153),
(153060, 'zhCN', '你是来做买卖的吗？', '', 28153),
(153059, 'zhCN', '有什么需要吗？', '', 28153),
(153058, 'zhCN', '', '赞达拉永不陷落。', 28153),
(153057, 'zhCN', '', '走路小心点。', 28153),
(153056, 'zhCN', '', '没有人应当承受流亡沙漠的命运。', 28153),
(153055, 'zhCN', '', '我能为你做什么？', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153054, 'zhCN', '', '有话快说。', 28153),
(153053, 'zhCN', '', '我在听。', 28153),
(153052, 'zhCN', '', '什么事？', 28153),
(153051, 'zhCN', '我们绝不放弃。', '我们绝不放弃。', 28153),
(153050, 'zhCN', '无信者的帝国将会崩塌。', '无信者的帝国将会崩塌。', 28153),
(153049, 'zhCN', '塞塔里斯会拯救我们。', '塞塔里斯会拯救我们。', 28153),
(153048, 'zhCN', '柯泰克对我们发起了这场战争。', '柯泰克对我们发起了这场战争。', 28153),
(153047, 'zhCN', '我们必须保持坚强。', '我们必须保持坚强。', 28153),
(153046, 'zhCN', '你是来帮忙的吗？', '你是来帮忙的吗？', 28153),
(153045, 'zhCN', '骨屑峡谷正处在拉卡塔卡大王的恐怖统治之下！他太强大了，无法直接攻击他，但是他食欲旺盛。如果你不断地给他喂吃的，他会把自己撑死！', '', 28153),
(153044, 'zhCN', '我们可是会一言不合就夺人性命的。', '我们可是会一言不合就夺人性命的。', 28153),
(153043, 'zhCN', '看起来，你既缺乏戒律之心，也不懂处世之道。', '看起来，你既缺乏戒律之心，也不懂处世之道。', 28153),
(153042, 'zhCN', '万物都有价值，甚至连你都有。', '万物都有价值，甚至连你都有。', 28153),
(153041, 'zhCN', '行动要迅捷。头脑要灵活。', '行动要迅捷。头脑要灵活。', 28153),
(153040, 'zhCN', '生存意味着要足智多谋。', '生存意味着要足智多谋。', 28153),
(153039, 'zhCN', '请记住，万物皆有用处。', '请记住，万物皆有用处。', 28153),
(153038, 'zhCN', '沙丘里有我们需要的一切。', '沙丘里有我们需要的一切。', 28153),
(153037, 'zhCN', '照顾好你自己。其他人可不会管你。', '照顾好你自己。其他人可不会管你。', 28153),
(153036, 'zhCN', '可别死在外面了。', '可别死在外面了。', 28153),
(153035, 'zhCN', '你给我带了什么？', '你给我带了什么？', 28153),
(153034, 'zhCN', '有什么需要吗？', '有什么需要吗？', 28153),
(153033, 'zhCN', '你是来做买卖的吗？', '你是来做买卖的吗？', 28153),
(153032, 'zhCN', '你好。', '你好。', 28153),
(153031, 'zhCN', '有什么东西要给我吗？', '有什么东西要给我吗？', 28153),
(153030, 'zhCN', '下次冒险时给我带点战利品回来！', '下次冒险时给我带点战利品回来！', 28153),
(153029, 'zhCN', '我们现在是朋友了吗？', '我们现在是朋友了吗？', 28153),
(153028, 'zhCN', '谢谢你和我说话。', '谢谢你和我说话。', 28153),
(153027, 'zhCN', '你是在进行一场大冒险吗？太棒了！', '你是在进行一场大冒险吗？太棒了！', 28153),
(153026, 'zhCN', '你有特意尝过沙子的味道吗？', '你有特意尝过沙子的味道吗？', 28153),
(153025, 'zhCN', '如果你死了，你的东西可以给我吗？', '如果你死了，你的东西可以给我吗？', 28153),
(153024, 'zhCN', '我们绝不放弃。', '', 28153),
(153023, 'zhCN', '无信者的帝国将会崩塌。', '', 28153),
(153022, 'zhCN', '塞塔里斯会拯救我们。', '', 28153),
(153021, 'zhCN', '柯泰克对我们发起了这场战争。', '', 28153),
(153020, 'zhCN', '我们必须坚强。', '', 28153),
(153019, 'zhCN', '你是来帮忙的吗？', '', 28153),
(153018, 'zhCN', '我们别无选择。', '', 28153),
(153017, 'zhCN', '塞塔里斯会拯救我们。', '', 28153),
(153016, 'zhCN', '无信者夺不走我们的神庙。', '', 28153),
(153015, 'zhCN', '柯泰克对我们发起了这场战争。', '', 28153),
(153014, 'zhCN', '我们必须坚强。', '', 28153),
(153013, 'zhCN', '你是来帮忙的吗？', '', 28153),
(153012, 'zhCN', '', '我们当初真的不该救你的。等等！我不是那个意思……', 28153),
(153011, 'zhCN', '', '你别再这么做了……', 28153),
(153010, 'zhCN', '', '也许你应该停手。', 28153),
(153009, 'zhCN', '', '你在干什么？', 28153),
(153008, 'zhCN', '', '你会回来的，对吗？', 28153),
(153007, 'zhCN', '', '嘿，可别死在外面了！', 28153),
(153006, 'zhCN', '', '独自旅行并不安全。', 28153),
(153005, 'zhCN', '', '朵利好像很喜欢你。我看得出来。', 28153),
(153004, 'zhCN', '', '我比任何人都了解这片沙漠。', 28153),
(153003, 'zhCN', '', '嗨！', 28153),
(153002, 'zhCN', '', '我能帮忙！', 28153),
(153001, 'zhCN', '', '这座城市决不会陷落。', 28153),
(153000, 'zhCN', '', '走路小心点。', 28153),
(152999, 'zhCN', '', '我发誓要守护皇室。', 28153),
(152998, 'zhCN', '', '我们会坚持下去。', 28153),
(152997, 'zhCN', '', '有话快说。', 28153),
(152996, 'zhCN', '', '什么事？', 28153),
(152995, 'zhCN', '', '我在听。', 28153),
(152994, 'zhCN', '愿沙漠能吞噬我的罪孽。', '', 28153),
(152993, 'zhCN', '这片沙漠永远不会安全。', '', 28153),
(152992, 'zhCN', '总有无法抹平的伤疤。', '', 28153),
(152991, 'zhCN', '你需要什么吗？', '', 28153),
(152990, 'zhCN', '如果我能帮上忙，那我就义不容辞。', '', 28153),
(152989, 'zhCN', '这是我应得的命运。', '', 28153),
(152988, 'zhCN', '趁你的腿还能动，走开。', '', 28153),
(152987, 'zhCN', '我会盯着你的。', '', 28153),
(152986, 'zhCN', '当心你的背后。', '', 28153),
(152985, 'zhCN', '你不属于这里。', '', 28153),
(152984, 'zhCN', '我没时间见你。', '', 28153),
(152983, 'zhCN', '你有什么事？', '', 28153),
(152982, 'zhCN', '让风暴指引你。', '', 28153),
(152981, 'zhCN', '不要畏惧风暴。', '', 28153),
(152980, 'zhCN', '风暴过后总有宁静。', '', 28153),
(152979, 'zhCN', '风暴在召唤。', '', 28153),
(152978, 'zhCN', '这里欢迎所有人。', '', 28153),
(152977, 'zhCN', '我即是风暴。', '', 28153),
(152976, 'zhCN', '你为何而来？', '', 28153),
(152975, 'zhCN', '宴会开始！', '', 28153),
(152973, 'zhCN', '', '我需要一顶新的头盔……', 28153),
(152972, 'zhCN', '', '我想起来了，有个蛇人也戳过我一次，然后……就没有然后了。', 28153),
(152971, 'zhCN', '', '快去，让敌人品尝你的怒火。', 28153),
(152970, 'zhCN', '', '随风而动，利剑在手。', 28153),
(152969, 'zhCN', '', '让他们畏惧你。', 28153),
(152968, 'zhCN', '', '记得留一些蛇人给我。', 28153),
(152967, 'zhCN', '', '永远不要停止战斗！', 28153),
(152966, 'zhCN', '', '告诉我，你们弄死了多少蛇人？', 28153),
(152965, 'zhCN', '', '今天真适合战斗。每天都是。', 28153),
(152964, 'zhCN', '', '我们狐人可比看上去要坚强得多。', 28153),
(152963, 'zhCN', '', '我的人民将获得自由。', 28153),
(152962, 'zhCN', '', '我准备好战斗了。', 28153),
(152961, 'zhCN', '我的生命属于大王。', '', 28153),
(152960, 'zhCN', '时刻准备好你的武器。', '', 28153),
(152959, 'zhCN', '愿洛阿神灵与你同在。', '', 28153),
(152958, 'zhCN', '赞达拉傲然屹立。', '', 28153),
(152957, 'zhCN', '我会直面危险。', '', 28153),
(152956, 'zhCN', '我们的敌人必将覆灭。', '', 28153),
(152955, 'zhCN', '', '噢，我知道你不会。', 28153),
(152954, 'zhCN', '我们不会让您失望的……我的女王。', '', 28153),
(152953, 'zhCN', '', '你准备好执行任务了吗？', 28153),
(152952, 'zhCN', '', '你要潜入暴风城，解救一名政治囚犯，这名囚犯将帮助我们，彻底改变战局。', 28153),
(152951, 'zhCN', '', '小鬼国王拥有一件不属于他的东西。帮我带回来。', 28153),
(152950, 'zhCN', '', '要想赢得这场战争，部落需要盟友。', 28153),
(152949, 'zhCN', '', '然而我十分清楚谨慎的含义。', 28153),
(152948, 'zhCN', '', '有相当一部分部落成员认为我最近的举措有些……不够谨慎。', 28153),
(152947, 'zhCN', '', '我需要一位可以完全信赖的人来为我效劳。', 28153),
(152946, 'zhCN', '', '啊，你来了。我还开始担心了。', 28153),
(152945, 'zhCN', '……向着部落。', '', 28153),
(152944, 'zhCN', '她的顾问全都忠心……', '', 28153),
(152943, 'zhCN', '要是这些顾问的忠诚更值得信任，也许我的女王会更开诚布公一点。', '', 28153),
(152942, 'zhCN', '要是大酋长总把事情瞒着自己的顾问，我们要如何帮她？', '', 28153),
(152941, 'zhCN', '这与你无关。', '', 28153),
(152940, 'zhCN', '大酋长召见你了吗？', '', 28153),
(152939, 'zhCN', '甚至连我都不知道详细情况。', '', 28153),
(152938, 'zhCN', '大酋长需要你去执行一项十分重要的任务……绝密的任务。', '', 28153),
(152937, 'zhCN', '邀请你的朋友来金牙旅馆做客吧！', '', 28153),
(152936, 'zhCN', '别忘了在登记簿上签名。', '', 28153),
(152935, 'zhCN', '别死在我前面。', '', 28153),
(152934, 'zhCN', '喂，你有香蕉吗？', '', 28153),
(152933, 'zhCN', '金牙旅馆货真价实。', '', 28153),
(152932, 'zhCN', '欢迎来到金牙旅馆！', '', 28153),
(152931, 'zhCN', '要么叛变，要么上绞架。', '', 28153),
(152930, 'zhCN', '照顾好你的船员。', '', 28153),
(152929, 'zhCN', '当心深海。', '', 28153),
(152928, 'zhCN', '她为葬身塞拉摩的丈夫哀悼，而就在同一天，她也失去了自己的女儿。', '', 28153),
(152927, 'zhCN', '别啰嗦了！没必要告诉所有人。', '别啰嗦了！没必要告诉所有人。', 28153),
(152926, 'zhCN', '安静！我们找到好东西了。', '安静！我们找到好东西了。', 28153),
(152925, 'zhCN', '嘘！我们不需要任何人提意见。', '嘘！我们不需要任何人提意见。', 28153),
(152924, 'zhCN', '泽姆兰不适合生者。', '', 28153),
(152923, 'zhCN', '你在招募船员吗？', '', 28153),
(152921, 'zhCN', '啊嘿！', '', 28153),
(152920, 'zhCN', '凯瑟琳一定承受着巨大的负担。难怪她如此难以接受吉安娜的归来。', '', 28153),
(152918, 'zhCN', '', '我们必须将各大家族集结在普罗德摩尔的旗帜之下，找到舰队。否则在战争开始之前，库尔提拉斯就将土崩瓦解。', 28153),
(152917, 'zhCN', '我的族人都被暮光之锤杀掉了。我能幸免于难是因为我的兄弟克兰用他的狮鹫把我送了出来。他救了我的命。\n\n我几乎周游了世界，然后在库尔提拉斯安顿了下来。我找到那些为了肉和毛皮而捕猎狮鹫的人。告诉他们还有另外一条路可以走。现在他们即将成为下一代的狮鹫骑士。\n\n我不认为我会回家。现在这里就是我的家。', '', 28153),
(152916, 'zhCN', '带我返回祖尔加。', '带我返回祖尔加。', 28153),
(152915, 'zhCN', '锯开', '锯开', 28153),
(152914, 'zhCN', '蛮锤矮人到这儿有什么事？', '蛮锤矮人到这儿有什么事？', 28153),
(152913, 'zhCN', '这次大收获之后我们都要发财了。', '这次大收获之后我们都要发财了。', 28153),
(152912, 'zhCN', '这些傻瓜根本不知道自己脚底下的东西多值钱。', '这些傻瓜根本不知道自己脚底下的东西多值钱。', 28153),
(152911, 'zhCN', '我在银月城找到了一个买家，愿意出大价钱收购这些圣物。', '我在银月城找到了一个买家，愿意出大价钱收购这些圣物。', 28153),
(152910, 'zhCN', '这些东西都不会送去博物馆。', '', 28153),
(152907, 'zhCN', '纳兹米尔的一切都似乎不太对劲……这个地方太不正常了。提高警惕。', '', 28153),
(152906, 'zhCN', '赫兹雷尔很忙啊！不知道他在下面做什么呢？', '', 28153),
(152905, 'zhCN', '我们原本希望赫兹雷尔能在战斗中帮我们，但他跑去处理他自己的事了。那个构造体有什么用？', '', 28153),
(152900, 'zhCN', '别碰我的财宝……', '就算杀了我，我也能死而复生……', 28153),
(152899, 'zhCN', '这片土地被诅咒了……我们都被诅咒了……', '泽姆兰不让我们安息……这才是真正的诅咒……', 28153),
(152898, 'zhCN', '我一无所觉……', '去死吧你这个旱鸭子！', 28153),
(152897, 'zhCN', '船长……会找你算账的……', '海盗之王泽姆兰……会要你好看的……', 28153),
(152896, 'zhCN', '我们飞下去和泰坦赫兹雷尔会面。', '我们飞下去和泰坦赫兹雷尔会面。', 28153),
(152895, 'zhCN', '', '我必须把这里发生的事告诉父王。我们虽然大获全胜，但与鲜血巨魔的战争还在继续。', 28153),
(152894, 'zhCN', '', '我永远不会忘记部落为我的人民的付出。没有你，这一切都不会成功。', 28153),
(152893, 'zhCN', '', '听你指挥！', 28153),
(152892, 'zhCN', '', '洞穴正在坍塌！快跑！', 28153),
(152891, 'zhCN', '就在这碎石中死亡吧，或者被我的手下撕成碎片。你不会活着看到我的胜利了。', '', 28153),
(152890, 'zhCN', '', '我要带着你一起走！', 28153),
(152889, 'zhCN', '', '再近一点！', 28153),
(152888, 'zhCN', '', '尽情狂欢吧！', 28153),
(152887, 'zhCN', '', '来吧，给我一个拥抱！', 28153),
(152886, 'zhCN', '跟我来！快点，别走散了！', '跟着我！赶快，不要乱！', 28153),
(152885, 'zhCN', '|TInterface\\Icons\\Spell_shadow_mindflay.blp:20|t一个|cFFFF0000|Hspell:269131|h[上古摧心者]|h|r附到了|cFFFF0000$n|r身上！', '', 28153),
(152884, 'zhCN', '第三舰队的英雄们，做好准备！立刻向格雷迈恩国王报到！', '第三舰队的英雄们，准备好！立即向格雷迈恩国王报告！', 28153),
(152883, 'zhCN', '嗯……哦，没事。是啤酒。虚惊一场。', '', 28153),
(152882, 'zhCN', '', '.', 28153),
(152881, 'zhCN', '', '我们的部队抵御着其余鲜血巨魔的入侵，但他们坚持不了多久。我们必须速战速决。', 28153),
(152880, 'zhCN', '', '.', 28153),
(152879, 'zhCN', '', '然而，我们已经有好几个月没有听到舰队的消息了！海潮贤者们都回到了自己的修道院，对寻找失踪船只毫无兴趣。', 28153),
(152878, 'zhCN', '', '一直以来，维克雷斯家族都是普罗德摩尔的忠实拥护者，但最近的议会上却不见他们的身影，这让流言四起，令人不安。', 28153),
(152877, 'zhCN', '回来，宝贝！', '', 28153),
(152876, 'zhCN', '得趁热吃。', '得趁热吃。', 28153),
(152875, 'zhCN', '这次就让我死吧，邦桑迪……拜托了……', '', 28153),
(152874, 'zhCN', '有话快说。', '', 28153),
(152873, 'zhCN', '', '我们要继续我们的……你为什么要这样看着我？你不同意吗？', 28153),
(152872, 'zhCN', '是的，绝对刻不容缓！', '', 28153),
(152871, 'zhCN', '呃，不是我见到的最糟糕的情况，虽然的确是很悲伤。我们得让高级指挥官知道发生了什么事情。', '', 28153),
(152870, 'zhCN', '噢，天呐。情况比我担心的还要糟糕。非常抱歉，让您陷入这样危险的境地，铜须先生。', '', 28153),
(152869, 'zhCN', '什么？！那姑娘肯定是喝多了月蜜酒，变得比鱼人还疯了。居然想把我们可爱的$c献祭给名为戈霍恩的鲜血之神。', '', 28153),
(152868, 'zhCN', '我猜康拉德船长……没事？', '', 28153),
(152867, 'zhCN', '应该是祖纳兹曼。还是图尔瓦？实际上我觉得那就是一个地方。至少离得很近。', '', 28153),
(152866, 'zhCN', '无论知晓与否，都是时候去一探究竟了。队长去哪儿了？', '', 28153),
(152865, 'zhCN', '天……天呐。自负的康拉德队长肯定不知道这些可怕的情况。', '', 28153),
(152864, 'zhCN', '哈瑞的血从他脸上滴下。', '', 28153),
(152863, 'zhCN', '这是怎么会回事，哈瑞？！你送去的那些祭品……我们的士兵被献祭了！他们的血液都被抽干了，就像美酒节酒杯里的啤酒。', '', 28153),
(152862, 'zhCN', '见鬼去吧! 在我和$n去搞清情况之前，他们别想从我们这儿再拿到一分钱。', '', 28153),
(152861, 'zhCN', '和巨魔的贸易协定！我们甚至还准备了蝙蝠，打算向扎拉玛送去另一份贸易提议。', '', 28153),
(152860, 'zhCN', '天呐！不过，是的，确实如此。我想这消息应该准确，嗯。但是康拉德队长英勇无畏。他令人刮目相看，这点毫无疑问。', '', 28153),
(152859, 'zhCN', '听说他们是会举行鲜血祭祀的蛮族。', '', 28153),
(152858, 'zhCN', '我向你保证，没什么麻烦事！我们伟大的队长要去和当地巨魔协商贸易协定的事。', '', 28153),
(152857, 'zhCN', '好吧，还是没有队长的踪迹。怎么回事？', '', 28153),
(152856, 'zhCN', '啊！啊哈！正是时候，是的，没错。不用担心！一切尽在掌握。让我们退到城墙后面更安全地方吧，好吗？', '', 28153),
(152855, 'zhCN', '队长在哪儿？', '', 28153),
(152854, 'zhCN', '康拉德队长给我留了些指示。', '', 28153),
(152853, 'zhCN', '我们一直等着你们到来，我们尊敬的军师和可靠的朋友。', '', 28153),
(152852, 'zhCN', '欢迎！欢迎！', '', 28153),
(152851, 'zhCN', '看来这里就是我们的欢迎会了。哈瑞是个有趣的家伙。但可别轻易惹恼他。', '', 28153),
(152850, 'zhCN', '还有……嗯……最好捏住你的鼻子。那股死尸腐烂的恶臭是什么？', '', 28153),
(152849, 'zhCN', '不管了。好好看。好好听。时刻警惕。被遗忘者可不会忘了那些粗心大意的家伙，$n。', '', 28153),
(152848, 'zhCN', '你们可以在这里与我们一起对抗赞达拉和他们部落的同伙。敌人的敌人就是……呃，那话咋说来着？', '', 28153),
(152847, 'zhCN', '我们之前派出了康拉德队长去建立一座堡垒。他们说这里的鲜血巨魔可能愿意进行交易，但是我无法想象付出的代价会是什么。', '', 28153),
(152846, 'zhCN', '我喜欢！每次看你汗毛倒竖，就是有冒险或是探寻知识的机会了。', '', 28153),
(152845, 'zhCN', '这地方让我有些焦虑不安……', '', 28153),
(152844, 'zhCN', '但是你活不到那一天了。起来，守护者，消灭这些闯入者！', '', 28153),
(152843, 'zhCN', '我们终将消灭库尔提拉斯入侵者，夺回这片土地！', '', 28153),
(152842, 'zhCN', '你的祖先都是蠢材……你也一样！', '', 28153),
(152841, 'zhCN', '去用绳索降到登陆筏艇上，$n。祝你好运。', '', 28153),
(152840, 'zhCN', '', '那儿肯定也有。去看看！', 28153),
(152839, 'zhCN', '', '高莱克·图尔没活下来！目击者都说他被击败了！', 28153),
(152838, 'zhCN', '当地的官员批准我们在这里开启传送门。', '当地的官员批准我们在这里开启传送门。', 28153),
(152837, 'zhCN', '魔法浸透了这个地方。你能感觉到吗？\n\n他们会在这里举行什么仪式？我真好奇。', '魔法浸透了这个地方。你能感觉到吗？\n\n他们会在这里举行什么仪式？我真好奇。', 28153),
(152836, 'zhCN', '', '又是石碑！这一座上也是高莱克·图尔。', 28153),
(152835, 'zhCN', '|cFF0000FF(任务)|r启航前往沃顿。\n', '|cFF0000FF(任务)|r启航前往沃顿。', 28153),
(152834, 'zhCN', '|cFFEF0201+$1i|r |cFFFFFF00艾泽里特|r', '|cFFEF0201+$1i|r |cFFFFFF00艾泽里特|r', 28153),
(152833, 'zhCN', '他们说我一直在和鲜血<咳嗽>共事。我当时问：“血精灵？！”然后他们回答说： “鲜血<咳嗽>。\"\n\n鲜血巨魔。不是精灵。啊，真是没说到点子上。', '', 28153),
(152832, 'zhCN', '', '遵命，长官！', 28153),
(152831, 'zhCN', '', '等等……怎么回事？', 28153),
(152830, 'zhCN', '团结就是力量。', '', 28153),
(152829, 'zhCN', '……好了，我给这儿的红花加了注释，还画了个圈。感谢你的帮助，要不然结果可能会很糟。', '', 28153),
(152828, 'zhCN', '喂，就是你。我想采集一些这种稀有沙漠花朵的样本。请帮我个忙。', '', 28153),
(152827, 'zhCN', '真是个疯子！我会回胜利要塞和你碰头。在他们都赶来追捕我们之前，还是快点离开这个黑暗的地方吧。', '', 28153),
(152826, 'zhCN', '我准备好了。', '我准备好了。', 28153),
(152825, 'zhCN', '在世界的这个角落，这种景象实在罕见。红色鞭笞者的叶子据说有神奇的治疗效果。$b$b我想采集一些，但摘下叶子会导致这种植物的香气散发到空气中。那肯定会迎来当地野生动物的注意。$b$b你得在我采集的时候保护我。我会根据你得表现给你奖励的。', '', 28153),
(152824, 'zhCN', '奥蕾莉亚，你带领剩余的士兵，集中打击敌方部队。', '', 28153),
(152823, 'zhCN', '我誓死效忠部落！', '', 28153),
(152822, 'zhCN', '我的父亲把一切都献给了联盟！问题是，你愿意为部落付出一切吗？', '', 28153),
(152821, 'zhCN', '我绝不会让开！我枕戈待旦，誓死用剑守卫人民。你又为你的人民付出了什么？', '', 28153),
(152820, 'zhCN', '你父亲是一位荣耀的战士，孩子。但你却什么都不懂。', '', 28153),
(152819, 'zhCN', '让开，萨鲁法尔。这场战争的责任不在你一个人肩上，杀死你并无荣誉可言。', '', 28153),
(152818, 'zhCN', '', '我准备好了！', 28153),
(152817, 'zhCN', '干得漂亮，全体将士！我们继续前进。', '', 28153),
(152816, 'zhCN', '四只眼睛……末日……她崛起了！', '', 28153),
(152815, 'zhCN', '无尽的暗影……千万只手臂……', '', 28153),
(152814, 'zhCN', '我欠你天大的恩情，$p。我永远不会忘记的。\n\n现在，我们要帮助诺莱和其它狐人劫走所有泽姆兰偷走的东西。如果你需要我们这些亡灵海盗帮忙，尽管开口。\n\n我们领导了一场完美的叛变，但我知道，并非每个人都是被泽姆兰逼迫成为怪物的。许多人是自愿的。\n\n如果你回到了港口，记得小心点。', '', 28153),
(152813, 'zhCN', '我们不能让维多利亚白白牺牲。她的法杖是打开前往神殿通路的关键。', '', 28153),
(152812, 'zhCN', '不成功便成仁，$p。我站在你这边。', '', 28153),
(152811, 'zhCN', '你见过这么多财宝放在同一个地方的吗？\n\n这就是无尽的海盗人生带给你的回报。真美……', '', 28153),
(152810, 'zhCN', '', '<阿娜大声地打着呼噜，假装陷入了熟睡。>', 28153),
(152809, 'zhCN', '敲响那个铜锣，向海盗王泽姆兰发起挑战。我准备好面对他了。', '', 28153),
(152808, 'zhCN', '我明白了。那我们就向凯瑟琳证明，我付出了极大的代价，才明白的真理……', '', 28153),
(152807, 'zhCN', '干得漂亮！远古巨魔帝国的金币可是很值钱的！这是你的分成！', '', 28153),
(152806, 'zhCN', '我在扎克拉加之庭发现了一个远古的图腾，它拥有能够让死者复生的力量。把它带到白骨坑去，用它来挖掘被埋葬的宝物！', '', 28153),
(152805, 'zhCN', '噢，算了。没工夫陪你胡闹。我还得参加派对呢！', '', 28153),
(152804, 'zhCN', '如今的孩子啊，真是没耐心。我才刚开始呢。', '', 28153),
(152803, 'zhCN', '你再戳我，我就要讲故事了。这个故事可是又长，又无聊。', '', 28153),
(152802, 'zhCN', '下次再讲故事吧。', '', 28153),
(152801, 'zhCN', '好，走吧。我有事要忙。', '', 28153),
(152800, 'zhCN', '别着急呀。', '', 28153),
(152799, 'zhCN', '小声点！', '', 28153),
(152798, 'zhCN', '你有什么好故事吗？', '', 28153),
(152797, 'zhCN', '嗯，嗯……我听着呢。', '', 28153),
(152796, 'zhCN', '如果你不小心的话，这片丛林里的植物会比野兽还要危险。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152795, 'zhCN', '我再也不会踏进这个矿洞一步了！', '我再也不会踏进这个矿洞一步了！', 28153),
(152794, 'zhCN', '它们是从哪冒出来的！', '它们是从哪冒出来的！', 28153),
(152793, 'zhCN', '谢谢你！我还以为我死定了。', '谢谢你！我还以为我死定了。', 28153),
(152792, 'zhCN', '快把我弄出去！', '快把我弄出去！', 28153),
(152791, 'zhCN', '', '这会把你们带到下面那座桥上。', 28153),
(152790, 'zhCN', '你的脸还没跟我的靴子打过照面呢。要不要试试啊？！', '', 28153),
(152789, 'zhCN', '快滚吧，小鸟儿……', '', 28153),
(152788, 'zhCN', '天上再见。', '', 28153),
(152787, 'zhCN', '', '在斯托颂谷地的北面，斯托颂家族的海潮贤者为我们的传奇舰队建造船只，施以祝福。', 28153),
(152786, 'zhCN', '那好吧。再见。', '', 28153),
(152785, 'zhCN', '我们回去干活吧！', '', 28153),
(152784, 'zhCN', '抓紧点！', '', 28153),
(152783, 'zhCN', '你想要什么？', '', 28153),
(152782, 'zhCN', '嗯？我可是大忙人！', '', 28153),
(152781, 'zhCN', '这些野兽一直是许多商队在沃顿的心头之患。做得好。', '', 28153),
(152780, 'zhCN', '骨喙秃鹫野性难驯，已经成了大患。我们必须削减它们的数量，清除它们的巢穴。', '', 28153),
(152779, 'zhCN', '你可以四处看看，但请不要碰任何东西。$b$b这些植物非常纤弱。', '', 28153),
(152778, 'zhCN', '', '位于西边的是德鲁斯瓦，那里群山环绕，出产矿石……我们有些最英勇的战士也来自那里。', 28153),
(152777, 'zhCN', '', '越过提拉加德海峡那头，就是维克雷斯和斯托颂家族的领地。', 28153),
(152776, 'zhCN', '你将面临的只有痛苦！', '你将面临的只有痛苦！', 28153),
(152775, 'zhCN', '我有的是办法让你开口！', '我有的是办法让你开口！', 28153),
(152774, 'zhCN', '我要撕裂你的灵魂。', '我要撕裂你的灵魂。', 28153),
(152773, 'zhCN', '生命烧为灰烬……', '', 28153),
(152772, 'zhCN', '当时他想寻求帮助，但为时已晚。', '', 28153),
(152771, 'zhCN', '我深爱的国土正在分崩离析……因此我想请求你们的帮助。库尔提拉斯急需联盟的力量，就像你们需要我们一样。', '', 28153),
(152770, 'zhCN', '随后她又被误导了。她的顾问蒙蔽了她的双眼，让她对影响整个王国的恶疾一无所知。', '', 28153),
(152769, 'zhCN', '库尔提拉斯仍未从第三次战争的伤痛中恢复。尤其是凯瑟琳·普罗德摩尔。', '', 28153),
(152768, 'zhCN', '', '尽量别让我看起来太糟，好吗？', 28153),
(152767, 'zhCN', '几天后，他尖叫着醒来，浑身颤抖，冷汗不止。伤口感染撕扯着他的身体。我的朋友再也没有看到第二天的太阳。', '', 28153),
(152766, 'zhCN', '', '如果这里没有硬币了，就去其他地点看看。', 28153),
(152765, 'zhCN', '我们本应把他送回家，然而他却相当固执。说在战争结束前绝不离开战场。他给自己包扎了伤口，还和医师说他没事。', '', 28153),
(152763, 'zhCN', '有艘兽人军舰袭击了我们的运输舰。几片弹片击穿了甲板，重伤了我的一位朋友。', '', 28153),
(152762, 'zhCN', '许多年前，我参加了一场战争。那是……第二次战争？我记不太清楚细节了。', '', 28153),
(152761, 'zhCN', '哼……听我这个年迈的骑士讲个故事，好吗？', '', 28153),
(152760, 'zhCN', '你为什么要帮我们？', '', 28153),
(152759, 'zhCN', '凯瑟琳·普罗德摩尔拒绝协助我们，还把她的女儿当作叛徒赶了出去。', '', 28153),
(152758, 'zhCN', '这瓶药水是我跟一个流浪的赞达拉巨魔交易来的。据说这玩意可以瞬间烹熟任何东西，肉也一样。拿上它去找这里的生物试试吧。', '', 28153),
(152757, 'zhCN', '泰莉亚！为我们的客人详细介绍下情况。', '', 28153),
(152756, 'zhCN', '一切都会熔化。', '', 28153),
(152755, 'zhCN', '格雷迈恩国王，很荣幸见到你。我已经下令，你们可以在这个港口任意停留。', '', 28153),
(152754, 'zhCN', '效果真是没得说！不过为了安全起见，还是先让长着獠牙的朋友们尝一尝……', '', 28153),
(152753, 'zhCN', '', '那就是对力量的渴求。对更伟大的真相的渴望。对鲜血的热爱。', 28153),
(152752, 'zhCN', '', '起初，我对纳兹曼尼的行为方式感到……很恶心。但是我现在了解他们了。他们是很单纯的种族，有着很单纯的渴求。', 28153),
(152751, 'zhCN', '', '来，让你看看我学到的东西吧。', 28153),
(152750, 'zhCN', '', '关于他们，我们还有很多需要了解的地方。这种鲜血魔法……其中隐藏的力量超出你的想象。', 28153),
(152749, 'zhCN', '', '他们是对抗赞达拉巨魔和其部落盟友的强大工具。', 28153),
(152748, 'zhCN', '', '我已经取得了鲜血巨魔——这些纳兹曼尼的信任，情况比我预期的还要好。', 28153),
(152747, 'zhCN', '啊啊，闭上你的嘴！', '', 28153),
(152746, 'zhCN', '', '呃啊啊啊！', 28153),
(152745, 'zhCN', '', '这无关个人恩怨，你懂的。但是，你不能妨碍我已经取得的进展。那些我已经学到的东西……和那些我还有待发掘的东西。', 28153),
(152744, 'zhCN', '', '这个赞达拉巨魔的牺牲将会增强我们的力量。', 28153),
(152743, 'zhCN', '是你帮了我们。我们将追随于你。', '是你帮了我们。我们将追随你。', 28153),
(152742, 'zhCN', '$p知道附近有一队狐人，我提议在这一切结束之前暂时加入他们的队伍。 ', '', 28153),
(152741, 'zhCN', '泽姆兰的手下会在海上搜寻我们。', '', 28153),
(152740, 'zhCN', '是的。但是我们得先藏匿一小会儿。', '', 28153),
(152739, 'zhCN', '自由地留下我们自己的宝物。', '自由地留下我们自己的宝物。', 28153),
(152738, 'zhCN', '自由地肆意掠夺。', '自由地肆意掠夺。', 28153),
(152737, 'zhCN', '自由地在海上航行。', '自由地在海上航行。', 28153),
(152736, 'zhCN', '我们成功了，伙计们。我们终于摆脱了泽姆兰的控制！', '', 28153),
(152735, 'zhCN', '都上船！两倍速驶向海岸！', '都上船！两倍速驶向海岸！', 28153),
(152734, 'zhCN', '你肯定就是联盟特使了。我很高兴弗林和泰莉亚能把你从那个该死的监狱里救出来。\n\n我是赛勒斯·克雷斯弗爵士。我谨代表普罗德摩尔海军部，欢迎你来到库尔提拉斯。\n\n<赛勒斯热情地伸出了他的大手。>\n', '', 28153),
(152733, 'zhCN', '<和他握手。>', '<和他握手。>', 28153),
(152732, 'zhCN', '我现在已经时日无多。\n\n但我不会看着库尔提拉斯分崩离析。', '', 28153),
(152731, 'zhCN', '好了，水手们。拿走财宝然后上船！', '', 28153),
(152730, 'zhCN', '温斯顿就要飞出你的范围了。回到克莱因！', '', 28153),
(152729, 'zhCN', '公主，$n，我的斥候报告说泰坦守护者赫兹雷尔正在这座建筑的底部徘徊。', '', 28153),
(152728, 'zhCN', '哈卡在古拉巴什巨魔的心中留下了弱点。在那之后他们很容易被腐化，所以必须被“净化”。', '', 28153),
(152727, 'zhCN', '', '你们……赢不了的……', 28153),
(152726, 'zhCN', '遵命，船长。', '', 28153),
(152725, 'zhCN', '', '克莱因属于女巫会！', 28153),
(152724, 'zhCN', '今晚就在营地放松一下。明天，我们要计划一下如何找到剩下的宝物。', '今晚就在营地放松一下。明天，我们会计划一下如何找到剩下的宝物。', 28153),
(152723, 'zhCN', '欢迎来到商队！', '欢迎来到商队！', 28153),
(152722, 'zhCN', '那么……', '那么……', 28153),
(152721, 'zhCN', '当然，海岸对面的整座岛都是财宝，多得你数不清。', '', 28153),
(152720, 'zhCN', '小小的诅咒可无法阻止狐人找寻珍贵的宝物。你还能在哪儿找到更多吗？', '小小的诅咒可无法阻止狐人找寻珍贵的宝物。你还能在其他地方找到更多吗？', 28153),
(152719, 'zhCN', '唯一的问题就是那些宝藏被诅咒了。', '唯一的问题就是那些宝藏被诅咒了。', 28153),
(152718, 'zhCN', '我们正在招募新人。如果你加入我们，我们就和你分享宝物。', '', 28153),
(152717, 'zhCN', '海盗王泽姆兰杀死了你们的同伴。我们对泽姆兰发动叛变，偷走了他的财宝。', '', 28153),
(152716, 'zhCN', '我在听……', '我在听……', 28153),
(152715, 'zhCN', '等一下！我们是来和平谈判的。', '', 28153),
(152714, 'zhCN', '骷-骷-骷髅！诺-诺莱，干掉他们！', '骷-骷-骷髅！诺-诺拉，干掉他们！', 28153),
(152713, 'zhCN', '干得好。用他们的火炮来牵制他们，可以有效削弱无信者的攻势。', '', 28153),
(152712, 'zhCN', '精彩的战斗就是我生存的意义！', '精彩的战斗就是我生存的意义！', 28153),
(152711, 'zhCN', '无信者正在加强他们的攻势！快用我们夺来的火炮帮忙守卫神殿！', '', 28153),
(152710, 'zhCN', '', '补丁，趁现在！', 28153),
(152709, 'zhCN', '准备好了，就等你了。', '准备好了，就等你了。', 28153),
(152708, 'zhCN', '继续走吗？我们可不是来这度假的。', '', 28153),
(152707, 'zhCN', '向他们倾泻火力，伙计们！', '', 28153),
(152706, 'zhCN', '开炮！', '', 28153),
(152705, 'zhCN', '向他们开炮，伙计们！', '', 28153),
(152704, 'zhCN', '锁定目标！开火！', '', 28153),
(152703, 'zhCN', '自由攻击！', '', 28153),
(152702, 'zhCN', '发现目标！开火！', '', 28153),
(152701, 'zhCN', '哈哈哈……', '', 28153),
(152700, 'zhCN', '……是的。对你的潜在顾客来说是有点太吓人。', '', 28153),
(152699, 'zhCN', '太吓人了？', '', 28153),
(152698, 'zhCN', '我简单算了下盈亏，我觉得这片区域不值得我们花时间。', '', 28153),
(152697, 'zhCN', '那么……你的艾泽里特呢？', '', 28153),
(152696, 'zhCN', '很好。上车。我们开路了。\n', '', 28153),
(152695, 'zhCN', '好嘞。', '', 28153),
(152694, 'zhCN', '那么……唔……你是想离开这里吗？\n', '', 28153),
(152693, 'zhCN', '不不不……', '', 28153),
(152692, 'zhCN', '你最好克服下对女巫的恐惧，伊崔格。这片区域全是艾泽里特，还有……啊！', '', 28153),
(152691, 'zhCN', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t%s获得了|cFFFF0000|Hspell:263246|h[闪电之盾]|h|r！', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t%s获得了|cFFFF0000|Hspell:263246|h[闪电之盾]|h|r！', 28153),
(152690, 'zhCN', '别又来了！', '', 28153),
(152689, 'zhCN', '', '我要你的血！', 28153),
(152688, 'zhCN', '谁在乎呢！你找到艾泽里特矿层了吗？', '', 28153),
(152687, 'zhCN', '什么？你在说啥？', '', 28153),
(152686, 'zhCN', '闭……闭嘴。', '', 28153),
(152685, 'zhCN', '啊哈哈哈！兽人老家伙，害怕女巫。', '', 28153),
(152684, 'zhCN', '不！我才不害怕。我只是不喜欢她们，就这样。', '', 28153),
(152683, 'zhCN', '你刚才说什么？', '', 28153),
(152682, 'zhCN', '小心……女……巫……', '', 28153),
(152681, 'zhCN', '伊崔格……你是害怕女巫吗？\n', '', 28153),
(152680, 'zhCN', '他刚才说……女巫？', '', 28153),
(152679, 'zhCN', '平民们有危险！鸟群冲我们过来了！', '平民们有危险！鸟群冲我们过来了！', 28153),
(152678, 'zhCN', '好了，干你们的活儿，还有保护好我！', '', 28153),
(152677, 'zhCN', '我没……但我看到什么东西了。有东西过来了。', '', 28153),
(152676, 'zhCN', '呸……这种话听多了。你看到艾泽里特了吗？', '', 28153),
(152675, 'zhCN', '它们正在四下聚集！', '它们正在四下聚集！', 28153),
(152674, 'zhCN', '加里维克斯……你看到这具惨死的尸体了吗？你的斥候已经挂了。', '', 28153),
(152673, 'zhCN', '呃，随便啦！', '', 28153),
(152672, 'zhCN', '好吧，我们会调查艾泽里特，但接下来就必须集中注意力对付联盟！', '', 28153),
(152671, 'zhCN', '太……多……鸟了！', '太……多……鸟了！', 28153),
(152670, 'zhCN', '我再也不会信任海鸥了！', '我再也不会信任海鸥了！', 28153),
(152669, 'zhCN', '麦克米伦太太是对的。这些鸟是邪恶生物！', '麦克米伦太太是对的。这些鸟是邪恶生物！', 28153),
(152668, 'zhCN', '哼。苦工。', '', 28153),
(152667, 'zhCN', '我们先去那儿看看吧。', '', 28153),
(152666, 'zhCN', '先说要紧事！我的斥候告诉我，在德鲁斯瓦有一片巨大的艾泽里特矿脉。', '', 28153),
(152665, 'zhCN', '那就滚出我的视线，不然我就要让你体验一下真正的恐惧是什么！', '', 28153),
(152664, 'zhCN', '我们应该小心点。他的话……很令人担心。', '', 28153),
(152663, 'zhCN', '是的，但……', '', 28153),
(152662, 'zhCN', '……可怕的诅咒……其他人都……', '', 28153),
(152661, 'zhCN', '你快掉头回去吧！它……', '', 28153),
(152660, 'zhCN', '', '哼。我还以为它块头大些。', 28153),
(152659, 'zhCN', '', '敲打还不够。还得再下点功夫。', 28153),
(152658, 'zhCN', '比起城市里冰冷的石头，我们更喜欢自然的树林。许多赞达拉巨魔都觉得我们是异教徒。他们说我们的主母不是洛阿神灵。\n\n他们想怎么说都可以。我们伦阿莱一族长久以来拥有着自然所赠予的天赋，可以化作自然的形态。我们处世的原则是平衡，而非取巧。', '', 28153),
(152655, 'zhCN', '太棒了！多漂亮啊！噢，这一个上面有沙子，但没关系，你做得很好！', '', 28153),
(152654, 'zhCN', '许多闪亮的海洋玻璃被冲上了这片沼泽，然而鱼人却把它们全抢走了！去捡几块漂亮的玻璃回来，不管你用什么办法。', '', 28153),
(152653, 'zhCN', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t亚兹玛开始施放|cFFFF0404|Hspell:249924|h[碎魂]|h|r！', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t亚兹玛开始施放|cFFFF0404|Hspell:249924|h[碎魂]|h|r！', 28153),
(152652, 'zhCN', '你太迟了。入侵已经到眼前了！', '你太迟了。入侵已经到眼前了！', 28153),
(152651, 'zhCN', '你觉得我是单干？认识一下我的伙伴吧！', '你觉得我是单干？认识一下我的伙伴吧！', 28153),
(152650, 'zhCN', '', '女巫会卑鄙无耻，但这一行为又一次刷新了下限！你阻止了这种……暴行，我都不知道怎么感谢你才好。', 28153),
(152649, 'zhCN', '女巫会在亵渎之路上走得太远了。至少我们终结了其中一次黑暗的探寻。', '', 28153),
(152648, 'zhCN', '动作快！回船上见我，我保证会让水手把财宝装满船舱的。', '', 28153),
(152647, 'zhCN', '', '我们救出的每一条生命都是一场胜利。干得好。', 28153),
(152646, 'zhCN', '死亡与重生的过程只应由我们来维护。你做得很好。', '', 28153),
(152645, 'zhCN', '', '德鲁斯瓦的人民饱受这只恐怖大鸟的折磨，你救了他们。谢谢你。', 28153),
(152644, 'zhCN', '别惹出什么麻烦。', '别惹出什么麻烦。', 28153),
(152643, 'zhCN', '这些羽毛够我们的游侠用上一阵子了。', '', 28153),
(152642, 'zhCN', '那就是先杀了你……再永无止境的烧杀抢掠！', '', 28153),
(152641, 'zhCN', '还有什么能比永无止境的烧杀抢掠更好呢？', '', 28153),
(152640, 'zhCN', '你真是一个冷酷的船长，泽姆兰。船员们应该得到更好的待遇！', '', 28153),
(152639, 'zhCN', '', '必须如此，不然就满盘皆输了。快走！', 28153),
(152638, 'zhCN', '', '我们不会让你送死的！', 28153),
(152637, 'zhCN', '', '好险啊。看起来我们不仅得小心沃顿的沙漠，还得留意海面。', 28153),
(152636, 'zhCN', '', '真是好险。看起来我们不仅得留意大海，还得小心沙滩。', 28153),
(152635, 'zhCN', '', '一头巨大的海怪正在海岸肆虐。我们必须阻止这头野兽，不然它就要危及内陆了！', 28153),
(152634, 'zhCN', '', '一个巨大的海怪正在海岸肆虐。我们必须阻止这头野兽，不然它就要危及我们的营地了！', 28153),
(152633, 'zhCN', '', '索雷斯是蛇人军队的一位高级指挥官。除掉他对我们来说是一场大胜。', 28153),
(152632, 'zhCN', '', '吟牙者索雷斯是蛇人军队的一位高级指挥官。除掉他对我们来说是一场大胜。', 28153),
(152631, 'zhCN', '', '狐人斥候报告说有一位蛇人指挥官在附近出没。我们必须抓住这次良机干掉他。', 28153),
(152630, 'zhCN', '', '我们的斥候报告说有一位蛇人高级指挥官在附近出没。我们必须抓住这次良机干掉他。', 28153),
(152629, 'zhCN', '', '干得好！没有了酋长，这个部族很快就会分崩离析。', 28153),
(152628, 'zhCN', '', '干得漂亮！没有酋长的领导，这个部落很快就会分崩离析。', 28153),
(152627, 'zhCN', '', '这附近有一帮鱼人，并且它们已经造成了一些麻烦。干掉他们的首领，这帮家伙就会土崩瓦解了。', 28153),
(152626, 'zhCN', '', '这附近有一个鱼人氏族，他们一直在给我们制造麻烦。干掉他们的首领，这帮家伙就会土崩瓦解了。', 28153),
(152625, 'zhCN', '', '干得好。你干掉了莫凡尼，我们的斥候会很高兴的。', 28153),
(152624, 'zhCN', '', '干得好。你解决了莫凡尼，狐人会很高兴的。', 28153),
(152623, 'zhCN', '一只巨型乌鸦被女巫会魅惑，正在攻击村民。虽然我对德鲁斯瓦的居民没什么好感，但我们的黑暗游侠可以用它的羽毛制作上好的箭羽。', '', 28153),
(152622, 'zhCN', '有个强大的女巫会成员正在献祭助祭来获取更多的力量。去消灭她，让这些傲慢的家伙明白，只有黑暗女王才能统御死亡。', '', 28153),
(152621, 'zhCN', '看起来这儿的女巫会“雇佣”了庄园的大厨来制作恶心的料理。最好尽快消灭他们。', '', 28153),
(152620, 'zhCN', '', '毒心女巫会在德鲁斯瓦魅惑了一只巨型乌鸦。消灭它，别让它威胁到我们的村民。', 28153),
(152619, 'zhCN', '', '维克雷斯夫人的女巫会里有人想吸干助祭的生命。阻止仪式，挽救更多的生命！', 28153),
(152618, 'zhCN', '', '一个赞达拉流亡者一直威胁着我们斥候。在他杀死更多人之前找到并除掉他。', 28153),
(152617, 'zhCN', '', '有个新来的赞达拉流亡者一直在威胁狐人。在他继续作恶前找到并除掉他。', 28153),
(152616, 'zhCN', '', '这里的厨师会为毫不知情的客人呈上可疑的料理。别让他们继续发扬这种恶心的厨艺！', 28153),
(152615, 'zhCN', '遵命，长官！', '', 28153),
(152614, 'zhCN', '不、不，长官。', '', 28153),
(152613, 'zhCN', '现在退下，让他们通过。我要和他们在办公室详谈。', '', 28153),
(152612, 'zhCN', '对！你效忠库尔提拉斯！你身上的徽记属于普罗德摩尔！你听命于我。', '', 28153),
(152611, 'zhCN', '沃顿的土壤不施肥是种不出庄稼的。我们通常都收集土狼的肥料，不过最近它们排得不多了。给它们喂食，加速肥料生产！', '', 28153),
(152610, 'zhCN', '艾什凡女勋爵？你效忠的是艾什凡女勋爵吗？你盾牌上画的是艾什凡女勋爵的徽记吗？', '', 28153),
(152609, 'zhCN', '但是长官……艾什凡女勋爵下令——', '', 28153),
(152608, 'zhCN', '退下！你们不知道这是谁吗？', '', 28153),
(152607, 'zhCN', '这可真是高质量的肥料！干得好……不过别忘记洗手！', '', 28153),
(152606, 'zhCN', '……我们应该阻止他们，对吧？', '', 28153),
(152605, 'zhCN', '海平面那里是船帆吗？他们可能在和赞达拉巨魔做交易。', '', 28153),
(152604, 'zhCN', '踢', '踢', 28153),
(152603, 'zhCN', '盒子发出中性的鸣响。', '', 28153),
(152602, 'zhCN', '盒子发出欢快的鸣响。', '', 28153),
(152601, 'zhCN', '盒子发出中性的鸣响。', '', 28153),
(152600, 'zhCN', '不知道。但是我今晚就要买酒，小姑娘。', '', 28153),
(152599, 'zhCN', '', '什么事？', 28153),
(152598, 'zhCN', '', '我很高兴能把你传送到无尽之海的海底。为了部落！', 28153),
(152597, 'zhCN', '什——', '', 28153),
(152596, 'zhCN', '', '有传言说外国侵略者和间谍已经渗透到我们之中，我们必须提高警惕，未雨绸缪。服从监工的指令，以避免发生难堪的意外。', 28153),
(152595, 'zhCN', '', '我们之后再谈报酬的事，码头管理员。', 28153),
(152594, 'zhCN', '啊，在这里。我们要把它封存好，然后用船运回暴风城。', '', 28153),
(152591, 'zhCN', '', '欧库勒斯……对不起……', 28153),
(152590, 'zhCN', '指针指向了东方。我们在废墟中见吧，$n。', '', 28153),
(152589, 'zhCN', '', '太慢了，矮人。', 28153),
(152588, 'zhCN', '跟紧了。附近有部落的家伙潜伏。我能闻到他们。', '', 28153),
(152587, 'zhCN', '它比我预想的还要香。他们是有新的精灵种族了？', '', 28153),
(152586, 'zhCN', '它不在这里。看起来是夜之子在跟踪我们。真是有趣。', '', 28153),
(152585, 'zhCN', '我们越来越接近了。让那些该死的魔瘾者离我远点，$n。', '', 28153),
(152584, 'zhCN', '它就在我的脚下……哪里……？', '', 28153),
(152583, 'zhCN', '噢！真是卑鄙的手段！', '', 28153),
(152581, 'zhCN', '盒子发出轻柔的嗡嗡声。', '', 28153),
(152580, 'zhCN', '盒子发出轻柔的嗡嗡声。', '', 28153),
(152579, 'zhCN', '盒子发出轻柔的嗡嗡声。', '', 28153),
(152578, 'zhCN', '等等！那些雕像无法被摧毁，但是他们唤起了一段古老的回忆……我试图遗忘的回忆。', '', 28153),
(152577, 'zhCN', '有把巨剑插进了这颗星球的心脏……而你还有闲工夫来戳我寻开心？快滚回去干活！', '', 28153),
(152576, 'zhCN', '铭记你对艾泽拉斯的使命。', '', 28153),
(152575, 'zhCN', '必须治愈这个世界！', '', 28153),
(152574, 'zhCN', '艾泽拉斯在痛苦哭喊。', '', 28153),
(152573, 'zhCN', '世界需要我们，勇士。', '', 28153),
(152572, 'zhCN', '', '要知道，巨魔可能就干坐在本世纪最重大的考古发现上！', 28153),
(152571, 'zhCN', '镇定点儿。这里有一股力量，我能感觉到它。我们要从部落的眼皮子底下把它拿走。', '', 28153),
(152570, 'zhCN', '', '现在，小心你的手。慢一点，稳一点。', 28153),
(152569, 'zhCN', '', '不要损害它。对，就像这样……', 28153),
(152568, 'zhCN', '', '啊……看呐。你会成为一位合格的考古学家的！', 28153),
(152567, 'zhCN', '什么？你打算徒手做这件事？', '', 28153),
(152566, 'zhCN', '去吧，跟我的元素打声招呼。它会为你把这件事办好的。', '', 28153),
(152565, 'zhCN', '', '等等！', 28153),
(152564, 'zhCN', '很好。现在该做正事了。', '', 28153),
(152563, 'zhCN', '', '你把它刮伤了！我们不能就这样展览它！', 28153),
(152562, 'zhCN', '放心吧，小姑娘，没那么糟糕。', '', 28153),
(152561, 'zhCN', '诅咒太过沉重，我这把老骨头很疲惫。', '', 28153),
(152560, 'zhCN', '这一天会让海盗王泽姆兰永生难忘。', '', 28153),
(152559, 'zhCN', '', '马上就到港务长的办公室了。', 28153),
(152558, 'zhCN', '<闻了闻>哇，还得洗洗这件大衣。', '', 28153),
(152557, 'zhCN', '一把坚固的槌子既是一件珍贵的工具，也是一把牢靠的武器。', '', 28153),
(152556, 'zhCN', '没了我的槌子，我就毫无用处。就好像我失去了双手。', '', 28153),
(152555, 'zhCN', '', '我可能拖延不了太久。带上法杖，快离开这里！', 28153),
(152554, 'zhCN', '检查', '检查', 28153),
(152553, 'zhCN', '这些山洞里全是狗头人歹徒。', '', 28153),
(152552, 'zhCN', '所有人都上船！回头见，$p。', '', 28153),
(152551, 'zhCN', '我们即将准备起锚。泽姆兰根本想不到是我们来了。', '', 28153),
(152550, 'zhCN', '是的。', '是啊。', 28153),
(152549, 'zhCN', '是的。', '没错。', 28153),
(152548, 'zhCN', '是的。泽姆兰是一个暴君，并非一位好船长。叛变是唯一的办法了。', '是的。泽姆兰是一个暴君，并非一个好船长。叛变是唯一的办法了。', 28153),
(152547, 'zhCN', '我们谈拢了，对吧？', '', 28153),
(152546, 'zhCN', '对，还要拿走属于我们的那份宝物。', '', 28153),
(152545, 'zhCN', '看看那些黄金……', '看看那些黄金……', 28153),
(152544, 'zhCN', '这才叫叛变，你这个舱底鼠！我们要用利刃刺穿泽姆兰那全是骨头的肚子。', '这才叫叛变，你这个舱底鼠！我们要用利刃刺穿泽姆兰那全是骨头的肚子。', 28153),
(152543, 'zhCN', '而我们还偏要深入虎穴。', '而我们还偏要深入虎穴。', 28153),
(152542, 'zhCN', '下场比我们还惨的就只有他们了。', '', 28153),
(152541, 'zhCN', '那里没有活人，只有金仆，他们都是泽姆兰昔日的船员，被迫永世守护他的宝藏。', '', 28153),
(152540, 'zhCN', '我们会去金银岛，我们在数不清的年月里掠夺的所有宝物，都被他藏在了那里。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152539, 'zhCN', '全体登船！', '都上船！', 28153),
(152538, 'zhCN', '*这里正在进行一些有趣的采矿车交接活动。*', '', 28153),
(152537, 'zhCN', '外面太亮了……把我的骨头放回洞里。', '外面太亮了……把我的骨头放回洞里。', 28153),
(152536, 'zhCN', '', '库尔提拉斯由四大家族组成。他们由戴林·普罗德摩尔领导，但随着戴林在塞拉摩战败，同盟也渐渐分崩离析。', 28153),
(152535, 'zhCN', '', '现在这里由海军统帅凯瑟琳·普罗德摩尔统治，她同时掌管军队和守卫。', 28153),
(152534, 'zhCN', '', '虽然我们尽力维持秩序，但犯罪、腐败、海盗劫掠渐渐在库尔提拉斯横行。人们正对海军部失去信心。', 28153),
(152533, 'zhCN', '', '.', 28153),
(152532, 'zhCN', '', '.', 28153),
(152531, 'zhCN', '你好。您需要休息吗？还是想用餐？', '', 28153),
(152530, 'zhCN', '能作为管家来服侍诺文顿勋爵和夫人是我的荣幸。如果你想要一个房间休息，请向我询问，不要客气。', '', 28153),
(152529, 'zhCN', '像这样的别墅尤其需要大量的维护工作。做马蹄铁、修耙子，偶尔还要到处做些奇怪的工作，铁匠真是没得歇啊！', '', 28153),
(152528, 'zhCN', '要修东西吗？我很擅长修马蹄铁，不过我也可以修一修你的护甲。', '', 28153),
(152527, 'zhCN', '', '跑。快跑！', 28153),
(152526, 'zhCN', '', '这很简单。别受伤，这样我就不用治疗你了。', 28153),
(152525, 'zhCN', '', '我会尽力拖住他们。', 28153),
(152524, 'zhCN', '我就知道你是个天生的钓鱼好手！而且还没缺胳膊少腿……真是意外！', '', 28153),
(152523, 'zhCN', '沙虫是一种野蛮的掠食者，就潜伏在沙丘之下。虽然很危险，但它们的牙齿可是很值钱的! 拿上我的鱼竿，看看你能钓上些什么吧！', '', 28153),
(152522, 'zhCN', '事情总是会变得越来越糟。我们只能尽人事，听天命。', '', 28153),
(152521, 'zhCN', '库尔提拉斯的舰队都对我唯命是从，你也不会例外。', '', 28153),
(152520, 'zhCN', '', '我……我觉得我走不动了。', 28153),
(152519, 'zhCN', '', '只剩几步了。我们不会把你抛下的！', 28153),
(152518, 'zhCN', '让他们尝尝我们新盟友的力量。', '', 28153),
(152517, 'zhCN', '我没什么可以给你了，泽姆兰……你把一切都拿走了。', '我没什么可以给你了，泽姆兰……你把一切都拿走了。', 28153),
(152516, 'zhCN', '又一个可供驱使的肉体！这会很有趣的。', '又一个可供驱使的肉体！这会很有趣的。', 28153),
(152514, 'zhCN', '', '加油，我们就快到了！', 28153),
(152513, 'zhCN', '', '我们只需要到达前方的祭坛。', 28153),
(152512, 'zhCN', '别以为你可以阻止我，库尔提拉斯的命运早就注定了。', '', 28153),
(152507, 'zhCN', '我就让你去传递这个好消息吧。我要去确保这些火炮安然无恙。', '', 28153),
(152506, 'zhCN', '这是最后一个了！', '', 28153),
(152505, 'zhCN', '哈，又一个倒下了。还剩一个……', '', 28153),
(152504, 'zhCN', '开火！', '', 28153),
(152503, 'zhCN', '那样肯定吸引了他们的注意。在我装弹的时候留心部落！', '', 28153),
(152502, 'zhCN', '好了，我们走。捂上你的耳朵！', '', 28153),
(152501, 'zhCN', '如果他们用他们的力量来治愈艾泽拉斯，而不是用来伤害她就好了。干得好，勇士。', '', 28153),
(152500, 'zhCN', '有人正从附近的艾泽里特中汲取能量，你要阻止他们！', '', 28153),
(152499, 'zhCN', '我会为大家在波涛之下带来光明的未来。', '', 28153),
(152498, 'zhCN', '', '这力量……必将……属于……我们！', 28153),
(152497, 'zhCN', '', '没有人能对抗拥有如此强大力量的蛇人！', 28153),
(152496, 'zhCN', '我们要取回宝石，放进插槽里，这样才能通过！', '', 28153),
(152495, 'zhCN', '塞塔里斯的双眼不见了！', '', 28153),
(152494, 'zhCN', '我需要的都有了。你准备好开始仪式了，就和我说一声。', '', 28153),
(152493, 'zhCN', '我看见他朝着城里去了。希望他别大出洋相，也希望大家也能好好待他。', '', 28153),
(152492, 'zhCN', '我看你来来回回地跑了很长一段时间了。我看到了你和那个小家伙的努力与成功。你应该为他感到骄傲。你也该为你的坚持感到骄傲。在这里能做到这样的家伙可不多。\n\n好好对待库亚冯吧。他会是一个忠诚的伙伴，哪怕它的飞行技术不是最好的。', '', 28153),
(152491, 'zhCN', '', '戈霍恩……想要……这个力量……', 28153),
(152490, 'zhCN', '', '这种能量会给我们力量，你休想阻止！', 28153),
(152489, 'zhCN', '帮助', '帮助', 28153),
(152488, 'zhCN', '开膛破肚', '开膛破肚', 28153),
(152487, 'zhCN', '有时候真感觉整个沼泽都出动来对付我们了！好在你能应付挑战！', '', 28153),
(152486, 'zhCN', '我有种很不详的感觉……我们巡逻的斥候早就应该回来了。帮忙调查下这次延误的原因。', '', 28153),
(152484, 'zhCN', '', '我们继续前进吧。', 28153),
(152483, 'zhCN', '', '许多年前，是他父亲引导我们来到这座峡谷的。', 28153),
(152482, 'zhCN', '', '并不是。他在被低语控制前，是个很和善的人。', 28153),
(152481, 'zhCN', '', '斯托颂勋爵向来这么残忍吗？', 28153),
(152480, 'zhCN', '', '隐秘行动到此结束了。', 28153),
(152479, 'zhCN', '', '你是打算让我自生自灭吗？', 28153),
(152478, 'zhCN', '这块石头脉动着艾萨拉自身的力量！把它完好地交给堡垒部队士兵，他们知道该怎么做。', '', 28153),
(152477, 'zhCN', '谢谢你。但我们应该快点离开这里！', '谢谢你。但我们应该快点离开这里！', 28153),
(152476, 'zhCN', '我才不要做翼手龙宝宝的饲料！', '我才不要做翼手龙宝宝的饲料！', 28153),
(152475, 'zhCN', '指挥官要是知道我被野兽抓了，会剥了我的皮。', '指挥官要是知道我被野兽抓了，会剥了我的皮。', 28153),
(152474, 'zhCN', '谢谢你！我以为我很小心了，但一只野兽从旁边一下子把我扑倒。真机灵。', '谢谢你！我以为我很小心了，但一只野兽从旁边一下子把我扑倒。真机灵。', 28153),
(152473, 'zhCN', '哎呦，他们的爪子抓人好疼！', '哎呦，他们的爪子抓人好疼！', 28153),
(152472, 'zhCN', '这些该死的翼手龙是个大麻烦。我不希望我的部队变成它们的食物！', '这些该死的翼手龙是个大麻烦。我不希望我的部队变成它们的食物！', 28153),
(152471, 'zhCN', '这些该死的翼手龙是个大麻烦。我不希望我的部队变成它们的食物！', '这些该死的翼手龙是个大麻烦。我不希望我的部队变成它们的食物！', 28153),
(152470, 'zhCN', '我原本希望能扫清翼手龙，好利用山上的有利位置，但是我们被轻而易举地逐个干掉！', '我原本希望能扫清翼手龙，好利用山上的有利位置，但是我们被轻而易举地逐个干掉！', 28153),
(152469, 'zhCN', '魔古族……会找到……更多的……石头……', '', 28153),
(152468, 'zhCN', '这块石头的力量将复兴魔古帝国！', '', 28153),
(152467, 'zhCN', '干得好！他们的数量比我想象的还要多。', '', 28153),
(152466, 'zhCN', '古拉巴什已经让自己陷入了残忍的狂乱之中！让我们帮他们解脱吧……杀死他们！敲响铜锣，他们会跑出来的！', '', 28153),
(152465, 'zhCN', '有报告说这片区域内有一些不安分的巨魔，恐怕一场袭击已经迫在眉睫。是时候削减他们的数量了。敲响阶梯顶部的铜锣来激怒他们！', '', 28153),
(152464, 'zhCN', '你的任何帮助，我们都十分感激。', '你的任何帮助，我们都十分感激。', 28153),
(152463, 'zhCN', '给我把斧子，瞧我怎么砍！', '', 28153),
(152462, 'zhCN', '管他什么柳魔，还有什么野兽……全不是我的对手！', '', 28153),
(152461, 'zhCN', '库尔提拉斯人不会不战而降！', '', 28153),
(152460, 'zhCN', '谢谢你的帮助，朋友。', '', 28153),
(152459, 'zhCN', '', '我们有伴儿了！', 28153),
(152458, 'zhCN', '去吧！去吧！去吧！', '去吧！去吧！去吧！', 28153),
(152457, 'zhCN', '水手们，听着！当我们上岸后，我打算让$n先头侦察。用那把漂亮的信号枪点燃任何会动的东西。', '水手们，听着！当我们上岸后，我打算让$n先头侦察。用那把漂亮的信号枪点燃任何会动的东西。', 28153),
(152456, 'zhCN', '为了联盟！', '为了联盟！', 28153),
(152455, 'zhCN', '小崽子们，碾碎这些闯入者，否则我就吞了你们的风险津贴！', '', 28153),
(152454, 'zhCN', '紧急修复协议进行中……', '', 28153),
(152453, 'zhCN', '美妙的艾泽里特！', '', 28153),
(152452, 'zhCN', '钻头，可爱的钻头！', '', 28153),
(152451, 'zhCN', '', '只要斯托颂没注意到我们就好。', 28153),
(152450, 'zhCN', '', '这条路最近。', 28153),
(152449, 'zhCN', '', '这样……好吗？', 28153),
(152448, 'zhCN', '', '海潮贤者在寻求神殿的祝福时，会走过这条仪式之道。', 28153),
(152447, 'zhCN', '', '只要诅咒还在，你的伤口就不能愈合！', 28153),
(152446, 'zhCN', '', '结局不该是这样的。', 28153),
(152445, 'zhCN', '', '如果你们失败，我就将迷失！', 28153),
(152444, 'zhCN', '', '你不能倒下！', 28153),
(152443, 'zhCN', '警告！燃料不足！', '', 28153),
(152442, 'zhCN', '警告！侦测到未授权用户。', '', 28153),
(152441, 'zhCN', '警告！你的执照上剩余分数为零。', '', 28153),
(152440, 'zhCN', '又来了一个，准备！', '又来了一个，准备发射。', 28153),
(152439, 'zhCN', '射高一点，这样它就能飞得更远，你肯定能打中的。', '射高一点，这样它就能飞得更远，你肯定能打中的。', 28153),
(152438, 'zhCN', '准备好！', '准备好！', 28153),
(152437, 'zhCN', '在他们起飞的时候发射。肯定能打中他们！', '在他们起飞的时候发射。肯定能打中他们！', 28153),
(152436, 'zhCN', '矮人！！他们来啦！!', '', 28153),
(152435, 'zhCN', '很遗憾，艾泽里特把元素都逼疯了。必须了结这件事。', '', 28153),
(152434, 'zhCN', '一些土元素被注入了艾泽里特，已经发狂了。把它们击败并吸收他们的艾泽里特！', '', 28153),
(152433, 'zhCN', '它们在这里！点燃军需品！', '', 28153),
(152432, 'zhCN', '', '石头在晃动……全都是我们的！', 28153),
(152431, 'zhCN', '', '这个石头中的力量会使我们的帝国更加强大！', 28153),
(152430, 'zhCN', '<格里布好奇地看着你。布莱恩不忍心让他知道他不是只猴子。>', '<格里布好奇地看着你。布莱恩不忍心让他知道他不是只猴子。>', 28153),
(152429, 'zhCN', '欢迎来到隼林栖木。多亏有你，那些怪物已经撤退，我们可以夺回镇子。只要你喜欢，可以想待多久就待多久。', '欢迎来到隼林栖木。多亏有你，那些怪物已经撤退，我们可以夺回镇子。只要你喜欢，可以想待多久就待多久。', 28153),
(152428, 'zhCN', '那些武器看起来好像是地精生产的。无所谓，只要能打蛇人就行。', '', 28153),
(152427, 'zhCN', '尼莎找到些……有趣的武器，或许可以帮助我们对抗蛇人。前提是我们知道如何使用这些武器。', '', 28153),
(152426, 'zhCN', '我从来没见过这种怪物！', '我从来没见过这种怪物！', 28153),
(152425, 'zhCN', '我能飞离这里吗？', '我能飞离这里吗？', 28153),
(152424, 'zhCN', '恐怕现在不行。\n\n当这场混乱开始的时候我试过飞出去， 但他们从地面用魔法朝我们开火。莱昂内尔侧翼受到了攻击，我们差点没能活着回到隼林镇。\n\n镇长伊斯顿让我们待在这里，直到我们夺回镇子或情况有所改善再走。\n\n很抱歉，我们现在走不了。', '恐怕现在不行。\n\n当这场混乱开始的时候我试过飞出去， 但他们从地面用魔法朝我们开火。莱昂内尔侧翼受到了攻击，我们差点没能活着回到隼林镇。\n\n镇长伊斯顿让我们待在这里，直到我们夺回镇子或情况有所改善再走。\n\n很抱歉，我们现在走不了。', 28153),
(152423, 'zhCN', '哈，这可真是意外收获啊！我敢肯定我们的法师会想看看这东西，干得很好，英雄。', '', 28153),
(152422, 'zhCN', '根据我们情报人员的报告，部落正计划从这些蛇人身上获得某种神器。那我们不如捷足先登吧？', '', 28153),
(152421, 'zhCN', '我们进去吧，$n。', '', 28153),
(152420, 'zhCN', '呜啊啊啊啊啊啊！', '', 28153),
(152417, 'zhCN', '', '干得好，勇士！那些东西应该待在尘土之下，那才是它们该待的地方。', 28153),
(152416, 'zhCN', '', '肮脏的生物，他们在献祭自己来制造怪物。阻止他们，不然我们就要被食人植物淹没了！', 28153),
(152415, 'zhCN', '<将我的队伍加入普通难度的海岛探险队列。>', '<将我的队伍加入普通难度的海岛探险队列。>', 28153),
(152414, 'zhCN', '', '艾泽里特……是……我们的！', 28153),
(152413, 'zhCN', '', '艾泽里特会屈服于我的鲜血魔法！', 28153),
(152412, 'zhCN', '我的骨头都迫不及待了！我当然准备好叛变了。我已经被挂在这里几个星期了！', '我的骨头都迫不及待了！我当然准备好叛变了。我已经被挂在这里几个星期了！', 28153),
(152411, 'zhCN', '', '有趣。也许这些能帮助我们弄清楚出现在纳兹米尔的奇怪现象，还有这些凶恶的鲜血巨魔的起源。', 28153),
(152410, 'zhCN', '', '我们的研究员要我们留意发现的任何神器，特别是要保证它们不落入部落之手。搜寻这片废墟，找到任何有用的东西。', 28153),
(152409, 'zhCN', '我最喜欢叛变了。算我一个。', '我最喜欢叛变了。算我一个。', 28153),
(152407, 'zhCN', '我很高兴加入你们的叛变，水手。海盗王泽姆兰要为惹恼我而付出代价。', '我很高兴加入你们的叛变，水手。海盗王泽姆兰要为惹恼我而付出代价。', 28153),
(152406, 'zhCN', '如果你有金币，欢迎你来这里消费。\n\n但不要打扰我的生意，否则我的人会让你好看，知道吗？', '如果你有金币，欢迎你来这里消费。\n\n但不要打扰我的生意，否则我的人会让你好看，知道吗？', 28153),
(152405, 'zhCN', '', '和这里的几个有名头的人谈谈：克劳斯·法温德、凯恩·卡莱尔，克朗克·油点和菲克西·狡刃。\n\n替我去问问他们需不需要什么帮助。我也需要他们的支持。\n\n你没别的事了吧，我得继续跟这些善良正直但是心里有疑虑的人们谈事情。', 28153),
(152404, 'zhCN', '我应该跟谁谈谈？', '我应该跟谁谈谈？', 28153),
(152403, 'zhCN', '只有我们两个人可不能算是叛变，$p，再找些人手！', '', 28153),
(152402, 'zhCN', '你的监护人在哪里？', '', 28153),
(152401, 'zhCN', '你这头野兽可真不懂礼貌。', '', 28153),
(152400, 'zhCN', '那个本来是我准备自己吃的。', '', 28153),
(152399, 'zhCN', '……你该住嘴了。', '', 28153),
(152398, 'zhCN', '你要为此付出代价！', '你要为此付出代价！', 28153),
(152397, 'zhCN', '那不是你的东西！', '那不是你的东西！', 28153),
(152396, 'zhCN', '嘿！快吐出来！', '嘿！快吐出来！', 28153),
(152395, 'zhCN', '我的遗骨还会再次复生。', '', 28153),
(152394, 'zhCN', '复活吧，我的傀儡们！消灭这个入侵者！', '', 28153),
(152393, 'zhCN', '来吧，秃鹫们……为了这场盛宴……你们已经等待多时……', '', 28153),
(152392, 'zhCN', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t$n |cFFFF0000|Hspell:267343|h[丢下]|h|r 宝珠！', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t$n |cFFFF0000|Hspell:267343|h[丢下]|h|r 宝珠！', 28153),
(152391, 'zhCN', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t$n的宝珠|cFFFF0000|Hspell:267633|h被[夺走]|h|r了！', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t$n的宝珠|cFFFF0000|Hspell:267633|h被[夺走]|h|r了！', 28153),
(152390, 'zhCN', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t%s |cFFFF0000|Hspell:265755|h[夺回]|h|r其中一个宝珠！', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t%s |cFFFF0000|Hspell:265755|h[夺回]|h|r其中一个宝珠！', 28153),
(152389, 'zhCN', '我要用绳子把你倒挂起来，让秃鹫们把你活吃了！', '', 28153),
(152388, 'zhCN', '首先，我们得把话放出去，而你要明白我们要对抗的对手。', '', 28153),
(152387, 'zhCN', '那就叛变吧！', '', 28153),
(152386, 'zhCN', '我想问问其他的。', '我想问问其他的。', 28153),
(152385, 'zhCN', '嘿！快停下！', '嘿！快停下！', 28153),
(152384, 'zhCN', '走开！', '走开！', 28153),
(152383, 'zhCN', '嘘！嘘！', '嘘！嘘！', 28153),
(152382, 'zhCN', '别再吵闹了！', '别再吵闹了！', 28153),
(152381, 'zhCN', '从那里下来！', '从那里下来！', 28153),
(152380, 'zhCN', '鹦鹉？没有风筝？', '鹦鹉？没有风筝？', 28153),
(152379, 'zhCN', '<谭不屑地轻笑一声>\n\n鹦鹉比风筝聪明多了，也有趣得多。\n\n<谭睁开一只眼看着他的鸟。>\n\n虽然它们有时候会叽叽喳喳叫着玩。', '<谭不屑地轻笑一声>\n\n鹦鹉比风筝聪明多了，也有趣得多。\n\n<谭睁开一只眼看着他的鸟。>\n\n虽然它们有时候会叽叽喳喳叫着玩。', 28153),
(152378, 'zhCN', '自从铁潮来了后，理查德·托恩塞尔不得不批准飞行航班的进出。\n\n原来说是为了保持“机密”和“安全”。但要我说，他这么做是为了能掌控一切。\n\n他现在不得不批准。听着，如果我违抗他，我的毛皮和翅膀就保不住了。\n\n<谭向前靠了靠，压低了声音>\n\n不如让其他人来掌控局面。', '自从铁潮来了后，理查德·托恩塞尔不得不批准飞行航班的进出。\n\n原来说是为了保持“机密”和“安全”。但要我说，他这么做是为了能掌控一切。\n\n他现在不得不批准。听着，如果我违抗他，我的毛皮和翅膀就保不住了。\n\n<谭向前靠了靠，压低了声音>\n\n不如让其他人来掌控局面。', 28153),
(152377, 'zhCN', '我可以搭个顺风车飞离这里吗？', '我可以搭个顺风车飞离这里吗？', 28153),
(152376, 'zhCN', '你必须放我下来，自从我上次逃跑失败后，他们就把我五花大绑地吊了起来。', '', 28153),
(152375, 'zhCN', '太好了！我要离开这里！', '太好了！我要离开这里！', 28153),
(152374, 'zhCN', '也许……如果你够胆的话……告诉他下次我会带一个帽子过来！', '', 28153),
(152373, 'zhCN', '现在没那么高大强壮了吧？去吧，我的仆从。去找那个命令你杀我族类的鼠辈阿尔芬。咬死他，你就能再度恢复人形。', '', 28153),
(152372, 'zhCN', '部落在这里？他们是从哪儿来的！谁会保护我们？', '部落在这里？他们是从哪儿来的！谁会保护我们？', 28153),
(152371, 'zhCN', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t米利克萨通过|cFFFF0000|Hspell:264206|h[钻地]|h|r穿过了战场！', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t米利克萨通过|cFFFF0000|Hspell:264206|h[钻地]|h|r穿过了战场！', 28153),
(152370, 'zhCN', '感谢你，朋友。我都以为自己完了，直到你的到来！', '感谢你，朋友。我都以为自己完了，直到你的到来！', 28153),
(152369, 'zhCN', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t$n被|cFFFF0000|Hspell:263958|h[缠绕的蛇群]|h|r包围了，快救$g他:她;！', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t$n被|cFFFF0000|Hspell:263958|h[缠绕的蛇群]|h|r包围了，快救$g他:她;！', 28153),
(152368, 'zhCN', '很久以前……诅咒降临泽姆兰港的那一天。', '', 28153),
(152367, 'zhCN', '等你准备好时，我的勋章就能揭示我过去的幻象。', '', 28153),
(152366, 'zhCN', '谢-谢谢你，$p，米-米-米基真是一个好朋友。', '谢-谢谢你，$p，米-米-米基真是一个好朋友。', 28153),
(152365, 'zhCN', '我辜负了你……柯泰克……', '', 28153),
(152364, 'zhCN', '这家伙好像但求一死啊！那我就成全你！', '', 28153),
(152363, 'zhCN', '我们是不可……阻挡的……', '', 28153),
(152362, 'zhCN', '傲慢的白痴！你会为你的越轨付出代价！', '', 28153),
(152361, 'zhCN', '', '你的指挥官在下面的战场等你。', 28153),
(152360, 'zhCN', '还没……完……\n', '还没……完……\n', 28153),
(152359, 'zhCN', '我们发现了一个奇怪的卷轴，据说能召唤一个强大的存在。海岸边聚集了许多亡灵。让我们瞧瞧，传言可不可靠。', '', 28153),
(152358, 'zhCN', '还……没……完……\n', '还……没……完……\n', 28153),
(152357, 'zhCN', '我的生命……献给帝国……', '我的生命……献给帝国……', 28153),
(152356, 'zhCN', '这不可能……', '这不可能……', 28153),
(152355, 'zhCN', '沙漠会继续……扩张……', '沙漠会继续……扩张……', 28153),
(152354, 'zhCN', '有人会替我报仇的……', '有人会替我报仇的……', 28153),
(152353, 'zhCN', '我让你失望了……柯泰克……', '我让你失望了……柯泰克……', 28153),
(152352, 'zhCN', '你还……没赢呢……', '你……还没赢呢……', 28153),
(152351, 'zhCN', '我们……不可阻挡……', '我们……不可阻挡……', 28153),
(152349, 'zhCN', '我的生命……献给帝国……', '我的生命……献给帝国……', 28153),
(152348, 'zhCN', '这不可能……', '这不可能……', 28153),
(152347, 'zhCN', '沙漠会继续……扩张……', '沙漠会继续……扩张……', 28153),
(152346, 'zhCN', '有人……会替我……报仇的……', '有人……会替我……报仇的……', 28153),
(152345, 'zhCN', '我让你失望了……柯泰克……', '我让你失望了……柯泰克……', 28153),
(152344, 'zhCN', '你还……没赢呢……', '你还……没赢呢……', 28153),
(152343, 'zhCN', '我们……不可阻挡……', '我们……不可阻挡……', 28153),
(152342, 'zhCN', '', '干得漂亮。你一如既往地完成了我们的任务。', 28153),
(152341, 'zhCN', '', '勇士，这些巨魔正在进攻胜利要塞。让他们明白，侵犯我们会付出什么代价！', 28153),
(152340, 'zhCN', '动作快，老鼠们！艾泽里特自己可不会炸开！', '', 28153),
(152339, 'zhCN', '', '他们焚毁了布伦纳丹，我们没人能回去。', 28153),
(152338, 'zhCN', '我们必须得快点！', '', 28153),
(152337, 'zhCN', '你让我想起了以前遇到过的一只年轻的猢狲。它说自己是什么美猴王，还不停地拿棍子戳我。', '', 28153),
(152336, 'zhCN', '如果你自以为可以比我更能惹人厌，那你就大错特错了。', '', 28153),
(152335, 'zhCN', '我认为我们应该和不同种族、不同信仰的人做买卖……除了纳迦。可怕的生物。', '', 28153),
(152334, 'zhCN', '如果你找到了强大的神器，请带给我，别想着自己使用。', '', 28153),
(152333, 'zhCN', '哼。强力的神器就应该由长者掌管，而不是鲁莽的冒险者。', '', 28153),
(152332, 'zhCN', '如果有东西的历史超过了两百年，那就绝对不要低估它的价值和力量。', '', 28153),
(152331, 'zhCN', '一堆废话。有事快说。', '', 28153),
(152330, 'zhCN', '请你去逞英雄需要花多少钱？你的丧葬费又是多少？', '', 28153),
(152329, 'zhCN', '啊太好了，一个冒险者。我需要你为我服务。', '', 28153),
(152328, 'zhCN', '我给你……这根岩石链！', '', 28153),
(152327, 'zhCN', '你们现在看到的就是未来，伙计们！', '', 28153),
(152326, 'zhCN', '祝贺你们，我们要发财啦！', '', 28153),
(152325, 'zhCN', '', '进来啊！不要这么胆小！', 28153),
(152324, 'zhCN', '永远不要接受黑暗帝国的礼物。', '', 28153),
(152323, 'zhCN', '也许我们应该和他们再较量一次。然后肩并肩，背靠背，在数量、装备、职业上全部碾压。呵呵。', '', 28153),
(152322, 'zhCN', '到我了，你来抓鱼！', '', 28153),
(152321, 'zhCN', '坐下，女士！', '', 28153),
(152320, 'zhCN', '你太不成熟了！', '', 28153),
(152319, 'zhCN', '啊！你把我的鱼都吓跑了！', '', 28153),
(152318, 'zhCN', '', '呜哇！我是帕库！嗖嗖！', 28153),
(152317, 'zhCN', '', '嘿，看呀，我是格罗尔！', 28153),
(152316, 'zhCN', '', 'Taz\'okun！', 28153),
(152315, 'zhCN', '', '哇！', 28153),
(152314, 'zhCN', '祝你好运。尽量别死了。', '', 28153),
(152313, 'zhCN', '永远要当心你的背后，要不就背个龟壳吧。', '', 28153),
(152312, 'zhCN', '你会……付出代价……', '你会……付出代价……', 28153),
(152311, 'zhCN', '不……公平……', '不……公平……', 28153),
(152310, 'zhCN', '信徒们！入侵者正在靠近神圣的水池！', '', 28153),
(152309, 'zhCN', '不……这是我的……', '不……这是我的……', 28153),
(152308, 'zhCN', '你……竟敢……你……', '你……竟敢……你……', 28153),
(152307, 'zhCN', '看来我要把你剥了当酬劳了！', '看来我要把你剥了当酬劳了！', 28153),
(152306, 'zhCN', '我喜欢狂野的喧闹。有时候我也会加入争斗，甚至大打出手。', '', 28153),
(152305, 'zhCN', '我要收双倍了！', '我要收双倍了！', 28153),
(152304, 'zhCN', '看来我要收下你的一条胳膊和一条腿！', '看来我要收下你的一条胳膊和一条腿！', 28153),
(152303, 'zhCN', '嘿！你要付出代价了！', '嘿！你要付出代价了！', 28153),
(152302, 'zhCN', '从背后袭击过我的人多到你想不到，所以别动什么歪脑筋。', '', 28153),
(152301, 'zhCN', '死亡是泽姆兰唯一能给予的仁慈，即使如此，大多数人也无法得到死亡。', '', 28153),
(152300, 'zhCN', '挖掘', '挖掘', 28153),
(152299, 'zhCN', '我准备好了。', '我准备好了。', 28153),
(152298, 'zhCN', '', '在把斯托颂的脑袋挂在这些墙上之前，我是不会休息的。', 28153),
(152297, 'zhCN', '', '这才是我们需要的火力！', 28153),
(152296, 'zhCN', '咳……很……好……', '咳……很……好……', 28153),
(152295, 'zhCN', '你会……付出代价……', '你会……付出代价……', 28153),
(152294, 'zhCN', '我是……不会被……打败的……', '我是……不会被……打败的……', 28153),
(152293, 'zhCN', '但……我才是老大……', '但……我才是老大……', 28153),
(152292, 'zhCN', '想当海湾的老大吗？哈！我会击败你，就像上一个那样！', '想当海湾的老大吗？哈！我会击败你，就像上一个那样！', 28153),
(152291, 'zhCN', '我是这里的老大！你们最好守点规矩！', '我是这里的老大！你们最好守点规矩！', 28153),
(152290, 'zhCN', '大家安静。米基没事，我也要继续睡觉了。', '大家安静。米基没事，我要继续睡觉了。', 28153),
(152289, 'zhCN', '我要把你绑在船底！', '我要把你绑在船底！', 28153),
(152288, 'zhCN', '没人能反抗铁潮！', '没人能反抗铁潮！', 28153),
(152287, 'zhCN', '你怎么敢！', '你怎么敢！', 28153),
(152286, 'zhCN', '如果你在路上找到了宝物，也请把它带回来。我们不会让你白忙活的。', '如果你在路上找到了宝物，也请把它带回来。我们不会让你白忙活的。', 28153),
(152285, 'zhCN', '你会付出代价……', '你会付出代价……', 28153),
(152284, 'zhCN', '没人能反抗铁潮……', '没人能反抗铁潮……', 28153),
(152283, 'zhCN', '我会抓住……你……', '我会抓住……你……', 28153),
(152282, 'zhCN', '对不起……老板……', '对不起……老板……', 28153),
(152281, 'zhCN', '你不该在这里！', '你不该在这里！', 28153),
(152280, 'zhCN', '你在这里鬼鬼祟祟干什么！', '你在这里鬼鬼祟祟干什么！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152279, 'zhCN', '你不属于这里！', '你不属于这里！', 28153),
(152278, 'zhCN', '嘿！', '嘿！', 28153),
(152277, 'zhCN', '', '你知道你可以在汤里加入鲸鲨的鱼鳃吗？这样可以防止大规模的变质！哦，我们之前在聊什么来着？', 28153),
(152276, 'zhCN', '', '我说的“所有人”，其实是指所有会花钱的人。人类、地精、牛头人、精灵，都无所谓。他们的金币对我来说都一样。\n\n<瑟希上下打量着你>\n\n哦。你想知道我不会不跟部落做买卖。\n\n听着，我得讨生活。我要是有从船后面掉下来的锚，我会卖给第一个出现的客人。这就是生意。如果是我说了算，所有人都会来海湾做生意。\n\n你不会真想跟那些铁潮海盗打交道的，对吧？\n\n相信我，朋友，这样最棒了。', 28153),
(152275, 'zhCN', '我的孩子都比你懂事。', '', 28153),
(152274, 'zhCN', '对“所有人”开放贸易是什么意思？', '对“所有人”开放贸易是什么意思？', 28153),
(152271, 'zhCN', '不要戳我，除非你想拿你的手指当供品。', '', 28153),
(152270, 'zhCN', '这里的旅馆里挤满了难民，如果你需要歇脚的话，我还有一个空余的房间可以租给你。', '', 28153),
(152269, 'zhCN', '记住，如果找到什么亮晶晶的好玩意，一定要把它带给老加尼。', '', 28153),
(152268, 'zhCN', '你死后，遗物可以归我吗？', '', 28153),
(152266, 'zhCN', '愿你总能在低谷中找到朋友。哈！', '', 28153),
(152265, 'zhCN', '干得好，勇士！你的努力让这片土地更安全了。', '', 28153),
(152264, 'zhCN', '我们的探子发现了此区域中的一个威胁。去解决它！', '', 28153),
(152263, 'zhCN', '', '把它们重新装好，干掉艾什凡的宠物，否则我们就没有办法赶走艾什凡的舰队了！', 28153),
(152262, 'zhCN', '', '他可是一只相当自大的始祖龟，大到他的壳都快容不下他了，我想你明白我的意思。可惜他被一只鲸鲨吃掉了。', 28153),
(152261, 'zhCN', '', '我甚至都没有注意到她在打呼噜。她说话声音就是这么粗犷，跟我的二孙子一样。', 28153),
(152260, 'zhCN', '', '有人说我很散漫。拜托，我姐姐比我夸张多了。你知道吗，她有一次说话说到一半睡着了？', 28153),
(152259, 'zhCN', '垃圾堆只是你出去搜刮东西时用来堆放东西的地方。', '', 28153),
(152258, 'zhCN', '', '现在的冒险者都特别有礼貌。', 28153),
(152257, 'zhCN', '', '哇，那不是很好吗？', 28153),
(152256, 'zhCN', '', '有时间记得来看看老诺拉。', 28153),
(152255, 'zhCN', '', '这让我想起了一个故事……', 28153),
(152254, 'zhCN', '', '你好呀，活泼的小东西。', 28153),
(152253, 'zhCN', '', '真高兴见到你，亲爱的。', 28153),
(152252, 'zhCN', '变变变，把坏点子变得不那么糟糕!', '变变变，把坏点子变得不那么糟糕!', 28153),
(152251, 'zhCN', '卡亚可乐，掺水饮料！', '卡亚可乐，掺水饮料！', 28153),
(152250, 'zhCN', '', '你看起来是个懂得欣赏故事的人。', 28153),
(152249, 'zhCN', '', '你拿到法杖以后，就来北边，看到成堆的尸体，就能找到我了。', 28153),
(152248, 'zhCN', '时间久了你就知道他们干嘛叫我抱怨鬼了。', '', 28153),
(152246, 'zhCN', '你好啊，有钱人。', '', 28153),
(152243, 'zhCN', '就像我常说的，汝之蜜糖，彼之砒霜。', '', 28153),
(152241, 'zhCN', '', '纳兹米尔面临着太多的威胁。但起码现在又少了一个了。', 28153),
(152239, 'zhCN', '', '那到底是什么东西？英雄！我们的工程师正好有你需要的东西，拿上它，在那群虱子蔓延到我们的营地之前把它们都烧死！', 28153),
(152232, 'zhCN', '你可真是个好伙伴。这片沙漠因为你而变得更加安全了。', '', 28153),
(152231, 'zhCN', '我们的车队在沙漠里发现了危险情况，相信你能应付得来。', '', 28153),
(152230, 'zhCN', '泰莉亚，$p，这是你理应肩负的重担。等萨缪尔恢复后，我和他会和你在神殿会合。', '', 28153),
(152229, 'zhCN', '正在沟通', '正在沟通', 28153),
(152228, 'zhCN', '我知道你看起来很聪明。来吧，到那里见我。', '我知道你看起来很聪明。来吧，到那里见我。', 28153),
(152227, 'zhCN', '祝你好运，干掉他们！我是走私货物的，不是雇佣兵。', '祝你好运，干掉他们！我是走私货物的，不是雇佣兵。', 28153),
(152226, 'zhCN', '那么，是该把铁潮赶走了！', '那么，是该把铁潮赶走了！', 28153),
(152225, 'zhCN', '铁潮一直在从我身上榨取金币，瑟希。我现在连收支平衡都做不到了。', '铁潮一直在从我身上榨取金币，瑟希。我现在连收支平衡都做不到了。', 28153),
(152224, 'zhCN', '现在……狩猎开始！', '', 28153),
(152223, 'zhCN', '', '听着，这里还有利可图！', 28153),
(152222, 'zhCN', '', '这些人正想逃跑。别的地方一定还有生还者。', 28153),
(152221, 'zhCN', '这是一个测试', '这是一个测试', 28153),
(152220, 'zhCN', '我们应该立刻出击，不要让消息传到斯托颂勋爵耳中。', '', 28153),
(152219, 'zhCN', '|cFF0000FF(任务)|r启航前往纳兹米尔。', '|cFF0000FF(任务)|r启航前往纳兹米尔。', 28153),
(152218, 'zhCN', '', '这艘战船现在由你指挥，$n。我还准备了人手以应不测。', 28153),
(152217, 'zhCN', '我们应该先集中精力做什么？', '', 28153),
(152216, 'zhCN', '嘿，这是常有的事儿。等你下次再见到这些家伙，再想想该怎么狠狠地复仇吧。', '', 28153),
(152215, 'zhCN', '别太内疚了，我们的收获还算不少。', '', 28153),
(152214, 'zhCN', '所有人，我们得离开这儿，否则这艘船就不保了。', '', 28153),
(152213, 'zhCN', '不会万事都一帆风顺的，下次再教训他们。', '', 28153),
(152212, 'zhCN', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|t有些防御设施正开始|cFFFF0000|Hspell:267931|h[过载]|h|r！', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|t有些防御设施正开始|cFFFF0000|Hspell:267931|h[过载]|h|r！', 28153),
(152211, 'zhCN', '啊，已经够了，我们走吧。', '', 28153),
(152210, 'zhCN', '打架总是有赢有输的，这才是生活嘛。', '', 28153),
(152209, 'zhCN', '唉！我们得先撤了。下次绝不会饶了他们。', '', 28153),
(152208, 'zhCN', '今天干得漂亮！你把他们好好教训了一顿，啊哈哈！', '', 28153),
(152207, 'zhCN', '完事啦！喂，经过联盟的船时记得开两枪。哈哈哈哈！', '', 28153),
(152206, 'zhCN', '船舱装满了。撑起风帆，回家吧。', '', 28153),
(152205, 'zhCN', '这么多就够了，我们开船吧！啊哈哈！', '', 28153),
(152204, 'zhCN', '能拿的全拿上，我们马上就得开船了！', '', 28153),
(152203, 'zhCN', '另外那艘船好像马上要起航了。我们得快点行动。', '', 28153),
(152202, 'zhCN', '那艘库尔提拉斯的船快装满了。咱们还是早点撤吧。', '', 28153),
(152201, 'zhCN', '就快干完了，只要再加把劲就行。', '', 28153),
(152200, 'zhCN', '船里快装不下了。再装点我们就收工了。', '', 28153),
(152199, 'zhCN', '马上就完事了。你们干得真不赖！', '', 28153),
(152198, 'zhCN', '啥！地面抖得我都站不稳了！附近一定有个强大的土元素在寻找艾泽里特，就跟我们一样。', '', 28153),
(152197, 'zhCN', '狂风快把船帆都吹裂了……这背后肯定有个风元素领主，他身上应该还有一堆艾泽里特，是时候去抢回来了。', '', 28153),
(152196, 'zhCN', '这场暴风雪背后一定有一名强大的水元素领主。结束他的痛苦吧，我讨厌这种天气。', '', 28153),
(152195, 'zhCN', '外边变热了，一定是哪个火焰领主想来抢走我们的艾泽里特。你快去把他浇灭了，不然我们的船帆就要起火了，哈哈。', '', 28153),
(152194, 'zhCN', '幕后黑手肯定是个元素领主。把他们干掉，艾泽里特也一起拿走！', '', 28153),
(152193, 'zhCN', '元素今天总跟我们作对。可能他们也想要艾泽里特吧。', '', 28153),
(152192, 'zhCN', '有几个强大的元素生物盯上了我们。当心他们的首领！', '', 28153),
(152191, 'zhCN', '这天气可不正常。一定是有个厉害的元素生物想来抢我们的艾泽里特。', '', 28153),
(152190, 'zhCN', '还有半艘船等着装货呢。眼睛放亮点！', '', 28153),
(152189, 'zhCN', '你干得不赖，我们已经进展过半了。', '', 28153),
(152188, 'zhCN', '船里装了一半了。照这速度，我们不一会儿就可以收工了！', '', 28153),
(152187, 'zhCN', '噢，马上就有好玩的了！', '', 28153),
(152186, 'zhCN', '又多了几个新朋友，呵呵。', '', 28153),
(152185, 'zhCN', '喂，眼睛放亮点，我们有伴儿了。', '', 28153),
(152184, 'zhCN', '就是这里了。去吧，艾泽里特等待着你！', '', 28153),
(152183, 'zhCN', '船靠岸了。在外头保护好自己的小命，呵呵。', '', 28153),
(152182, 'zhCN', '船板放下了，朋友。我们马上激活探测器。', '', 28153),
(152181, 'zhCN', '喂，这儿有好多的艾泽里特。快过来瞧瞧。', '', 28153),
(152180, 'zhCN', '刚才有一大块艾泽里特冒了出来。冲过去！哈哈！', '', 28153),
(152179, 'zhCN', '啊，仪器在这儿响得跟疯了似的。一定有好大一块艾泽里特。', '', 28153),
(152178, 'zhCN', '探测器上线了！正在你的地图上标记艾泽里特矿点。', '', 28153),
(152177, 'zhCN', '探测器启动了！地图上会标出艾泽里特的富集地区。', '', 28153),
(152176, 'zhCN', '我只是休息下眼睛！马上回去工作！', '', 28153),
(152175, 'zhCN', '好的老板，我回矿洞去了。', '', 28153),
(152174, 'zhCN', '困啊……真是困死了……', '', 28153),
(152173, 'zhCN', '啊！是的，我去工作，$n！', '', 28153),
(152172, 'zhCN', '击败灾厄妖术师和他的根基图腾。', '击败灾厄妖术师和他的根基图腾。', 28153),
(152171, 'zhCN', '又一片大陆，又有恶魔要去追捕。', '', 28153),
(152170, 'zhCN', '哈，你从来不会让我失望。我就喜欢这样的船员。', '', 28153),
(152169, 'zhCN', '啊，收工了。干得好，我们返航吧。', '', 28153),
(152168, 'zhCN', '艾泽里特已经装满货舱了！我们马上出发，不要让他们觉察到。', '', 28153),
(152167, 'zhCN', '我们出发吧！哇，瞧瞧这船舱。你们干得真漂亮。', '', 28153),
(152166, 'zhCN', '部落就快打败我们了，尽你所能多收集点艾泽里特吧！', '', 28153),
(152165, 'zhCN', '我要去……希巴拉……', '', 28153),
(152164, 'zhCN', '部落好像在收工了，如果我们不赶紧离开，就要变成活靶子了。', '', 28153),
(152163, 'zhCN', '部落就快收工了，尽量多捡一点算一点，可以吗？', '', 28153),
(152162, 'zhCN', '我不是要打扰你，但是部落的船看上去收获了不少啊。要是他们装满了，我们也必须得走了。', '', 28153),
(152161, 'zhCN', '就快完工了！眼观六路，耳听八方，你能搞定的。', '', 28153),
(152160, 'zhCN', '我们的货舱里可真是金光闪亮！再装几块这种石头我们就可以走了。', '', 28153),
(152159, 'zhCN', '我们的船舱就快装满艾泽里特了，准备升帆！等你那边完事儿我们就能出发了。', '', 28153),
(152158, 'zhCN', '嘿，我们就快要完工了！再多来点儿我们就能起航了。', '', 28153),
(152157, 'zhCN', '地面为什么在震动？我都快吐了。听好了，我们发现了一些土元素，我打赌背后一定有某位元素领主在作怪。去对付他们吧，不然我午饭就白吃了。', '', 28153),
(152156, 'zhCN', '在这样的飓风里船帆可支撑不了多久，一定是某位风元素领主派出他的爪牙来抢夺这些艾泽里特了。只要有他们在，我们就很难驶出这片海域。', '', 28153),
(152155, 'zhCN', '嘿，英雄们？一个水元素领主派部队来偷我们的艾泽里特了，我、我快冻死了。快去把他们给收拾了，我、我衣服穿少了。', '', 28153),
(152154, 'zhCN', '天气怎么越来越热了，真是活见鬼……噢，原来如此。有一名火元素领主派兵来抢夺艾泽里特了。好极了，妙极了。', '', 28153),
(152153, 'zhCN', '我们已经完成一半了！保持现在的势头，很快就能离开这里了。', '', 28153),
(152152, 'zhCN', '艾泽里特已经塞满了半个船舱，加油，你们做得很好。', '', 28153),
(152151, 'zhCN', '你踏入了神圣的土地！', '', 28153),
(152150, 'zhCN', '我准备好了。', '我准备好了。', 28153),
(152149, 'zhCN', '勘测结果指向了这些废墟。部落的营地就在东北方的山脚下，我们最好用最快的速度进出。\n\n我们会在他们之前拿到希巴拉之息，我保证。\n\n你准备开始勘测了就和我说一声。', '', 28153),
(152148, 'zhCN', '探测器正在运转！你可以检查地图，看看艾泽里特都分布在哪里。', '', 28153),
(152147, 'zhCN', '探测器上线了，我会在地图上标出艾泽里特的位置。不用谢。', '', 28153),
(152146, 'zhCN', '我在不远处发现了大量的艾泽里特晶簇，地震一定是因为这个。', '', 28153),
(152145, 'zhCN', '哇，我们附近有大量的艾泽里特涌出，最好赶在部落发现前检查一下。', '', 28153),
(152144, 'zhCN', '船已停好，板已放下！我们负责启动艾泽里特探测器，你来对付坏家伙。', '', 28153),
(152143, 'zhCN', '船已靠岸！趁我们在调节艾泽里特探测器，享受你的冒险吧。', '', 28153),
(152142, 'zhCN', '我们到了，这里的风对我的发型不太友好。所以我们要速战速决，没问题吧？', '', 28153),
(152141, 'zhCN', '嘿，看来有一个元素领主和我们一样，也在寻找艾泽里特。我得到甲板底下处理一些事情，这里就……交给你了。', '', 28153),
(152140, 'zhCN', '看来这些艾泽里特被什么元素势力盯上了。好像还有一名元素领主眼馋我们的货。但谁捡到就是谁的，对吧？', '', 28153),
(152139, 'zhCN', '我想部落也发现了这个地方，他们的船刚刚下了锚。', '', 28153),
(152138, 'zhCN', '呃，好像有部落过来了。在外头小心点，好吗？', '', 28153),
(152137, 'zhCN', '我看到一艘船，通身金色……没错，绝对是赞达拉的船。部落来了，保持警惕。', '', 28153),
(152136, 'zhCN', '我以前和你一样也是个冒险家……后来我就出人头地了。哈哈。', '', 28153),
(152135, 'zhCN', '看来你经历过不少事情。我们应该交流一下彼此的战场经历。', '', 28153),
(152134, 'zhCN', '我记得莱卡国王和他的妹妹托拉女王之间的大战。至少，我能记起一部分。好吧，我几乎肯定它发生了，大概有一半可能吧。', '', 28153),
(152133, 'zhCN', '你让我想起了另一个人，在第三王朝，我和他扫荡了整个卡桑琅的海滩。魔古族竟然这么对待他，真是可耻。', '', 28153),
(152132, 'zhCN', '现在别烦情喙！呱！', '', 28153),
(152131, 'zhCN', '这就是我不喜欢搭档的原因。', '', 28153),
(152130, 'zhCN', '你说自己叫“魔灾”的时候，我还以为你是邪能的克星，没想到恰恰相反。', '', 28153),
(152129, 'zhCN', '是时候把他们炸飞了！', '', 28153),
(152128, 'zhCN', '“我们去丛林吧”、“去侦察一下吧”，这都是你说的。我早该知道你的无知会让我们陷入麻烦之中。', '', 28153),
(152127, 'zhCN', '如果我们死了，那就是你的错。', '', 28153),
(152126, 'zhCN', '我听说你一直在附近潜伏。$b$b由于马瑞斯的……而不是我的……轻率举动，我们不得不来到这个潮湿恶心的洞里寻找这个可怕的恶魔。而洞中充满了咀嚼骨头的生物。$b$b帮助我们，你就可以拿走她尸体上所有值钱的东西。$b$b我们只想要她身上的一页纸。上面没什么值得一读的内容。', '', 28153),
(152125, 'zhCN', '呱！都是你的了！', '', 28153),
(152124, 'zhCN', '情喙有鱼吃了？', '', 28153),
(152123, 'zhCN', '别打了！人类老爷！', '', 28153),
(152122, 'zhCN', '你们这些家伙永远学不会。', '', 28153),
(152121, 'zhCN', '也许你不该老是和他们这么说。呱！', '', 28153),
(152120, 'zhCN', '那个战利品……永远都是我的……', '那个战利品……永远都是我的……', 28153),
(152119, 'zhCN', '', '好吧，你把我难住了。', 28153),
(152118, 'zhCN', '', '进来，情喙，别磨蹭了！', 28153),
(152117, 'zhCN', '', '滚开，臭鸟，我不需要你的帮助！', 28153),
(152116, 'zhCN', '', '那都不疼。这就是你的实力了，鲨鱼饵？', 28153),
(152115, 'zhCN', '哈！我一直在找机会驱散烟雾！', '哈！我一直在找机会出出气！', 28153),
(152114, 'zhCN', '', '我起初非常满意……但是他们后来就不按我说的去做了……', 28153),
(152113, 'zhCN', '', '“你的人民”是什么意思？', 28153),
(152112, 'zhCN', '', '他们会离开我的船吗？我会重建巨角号，并把所有两面三刀的混蛋都插在船头的斜桅上！', 28153),
(152111, 'zhCN', '', '彻底没用的杂碎！', 28153),
(152110, 'zhCN', '她……会统治……千秋万代……', '她……会统治……千秋万代……', 28153),
(152109, 'zhCN', '居然被你这种人……打败……', '居然被你这种人……打败……', 28153),
(152108, 'zhCN', '部落……永远……属于她……', '部落……永远……属于她……', 28153),
(152107, 'zhCN', '怎么……又死了……', '怎么……又死了……', 28153),
(152106, 'zhCN', '死亡是唯一的解脱！', '死亡是唯一的解脱！', 28153),
(152105, 'zhCN', '听到自己的尖叫了吗？', '听到自己的尖叫了吗？', 28153),
(152104, 'zhCN', '不留活口！', '不留活口！', 28153),
(152103, 'zhCN', '为了黑暗女王！', '为了黑暗女王！', 28153),
(152102, 'zhCN', 'Lok-tar ogar！', 'Lok-tar ogar！', 28153),
(152101, 'zhCN', 'Lok-narash!', 'Lok-narash!', 28153),
(152100, 'zhCN', 'Gakarah ma！', 'Gakarah ma！', 28153),
(152099, 'zhCN', '不胜利，毋宁死！', '不胜利，毋宁死！', 28153),
(152098, 'zhCN', '为了部落！', '为了部落！', 28153),
(152097, 'zhCN', '是敌人，就得死！', '是敌人，就得死！', 28153),
(152096, 'zhCN', '今天是你的死期！', '今天是你的死期！', 28153),
(152095, 'zhCN', '荣耀……的……战死……', '荣耀……的……战死……', 28153),
(152094, 'zhCN', '先祖……我来了……', '先祖……我来了……', 28153),
(152093, 'zhCN', '你赢不了……这场战争……', '你赢不了……这场战争……', 28153),
(152092, 'zhCN', '你的末日……终将来临……', '你的末日……终将来临……', 28153),
(152091, 'zhCN', '我战死……沙场……', '我战死……沙场……', 28153),
(152090, 'zhCN', '我的战斗……到此为止了……', '我的战斗……到此为止了……', 28153),
(152089, 'zhCN', '我的生命……献给德拉诺……', '我的生命……献给德拉诺……', 28153),
(152088, 'zhCN', '快走开。', '快走开。', 28153),
(152087, 'zhCN', '走开。马上。', '走开，马上。', 28153),
(152086, 'zhCN', '别让部落失望。\n', '别让部落失望。\n', 28153),
(152085, 'zhCN', '祝你死得光荣。', '祝你死得光荣。', 28153),
(152084, 'zhCN', '不想再跟你聊了。', '不想跟你聊了。', 28153),
(152083, 'zhCN', '快走。', '快走。', 28153),
(152082, 'zhCN', '带着荣耀前进吧。', '带着荣耀前进吧。', 28153),
(152081, 'zhCN', '愿你的刀刃永远锋利。', '愿你的刀刃永远锋利。', 28153),
(152080, 'zhCN', '向胜利前进吧。', '向着胜利前进吧。', 28153),
(152079, 'zhCN', '别忘了你的职责。', '别忘了你的职责。', 28153),
(152078, 'zhCN', '有什么话就快说吧。', '有什么话就快说吧。', 28153),
(152077, 'zhCN', '我没功夫陪你犯傻。', '我没功夫陪你犯傻。', 28153),
(152076, 'zhCN', '什么？我可等着呢……', '什么？我可等着呢……', 28153),
(152075, 'zhCN', '有话就说。', '有话就说。', 28153),
(152074, 'zhCN', '很高兴见到你。', '很高兴见到你。', 28153),
(152073, 'zhCN', 'Lok-tar！', 'Lok-tar！', 28153),
(152072, 'zhCN', 'Throm-ka！', 'Throm-ka！', 28153),
(152071, 'zhCN', '你想要什么？', '你想要什么？', 28153),
(152070, 'zhCN', '哼哼。', '哼哼。', 28153),
(152069, 'zhCN', '力量与荣耀。', '力量与荣耀。', 28153),
(152068, 'zhCN', '艾泽拉斯人都这么讨厌吗？', '艾泽拉斯人都这么讨厌吗？', 28153),
(152067, 'zhCN', '我最大的爱好就是把烦我的家伙干掉。你真的还想继续戳我吗？', '我最大的爱好就是把烦我的家伙干掉。你真的还想继续戳我吗？', 28153),
(152066, 'zhCN', '伙计，你要惹我生气了，你不会喜欢我发怒的样子的。', '伙计，你要惹我生气了，你不会喜欢我发怒的样子。', 28153),
(152065, 'zhCN', '兽人……砸扁你！！！', '兽人……砸扁你！！！', 28153),
(152064, 'zhCN', '他们肯定还跟墙外那些女巫会的爪牙有联系。', '', 28153),
(152063, 'zhCN', '', '其他审判官去哪儿了？', 28153),
(152062, 'zhCN', 'Lok-tar ogar！', 'Lok-tar ogar！', 28153),
(152061, 'zhCN', '我的怒火会吞没你！', '我的怒火会吞噬你！', 28153),
(152060, 'zhCN', '你们的命运早已注定！', '你们的命运早已注定！', 28153),
(152059, 'zhCN', '在部落面前倒下吧！', '在部落面前倒下吧！', 28153),
