(152050, 'zhCN', '我的战斗……到此为止了……', '我的战斗……到此为止了……', 28153),
(152049, 'zhCN', '我将魂归……德拉诺……', '我将魂归……德拉诺……', 28153),
(152048, 'zhCN', '下次多带点金币。', '下次多带点金币。', 28153),
(152047, 'zhCN', '希望这些货里有你想要的。', '希望这些货里有你想要的。', 28153),
(152046, 'zhCN', '下次再来。', '下次再来。', 28153),
(152045, 'zhCN', '祝你死得光荣。', '祝你死得光荣。', 28153),
(152044, 'zhCN', '没别的想跟你聊了。', '没别的想跟你聊了。', 28153),
