INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152010, 'zhCN', '疫病扩散！', '', 28153),
(152009, 'zhCN', '狂暴育种！', '', 28153),
(152008, 'zhCN', '吞噬躯壳！', '', 28153),
(152007, 'zhCN', '我受够了！你们这些部落是自取灭亡！', '', 28153),
(152006, 'zhCN', '致命的病毒。传染很成功。', '', 28153),
(152005, 'zhCN', '我已经暴露了。你有另外一个卷轴吗？', '我已经暴露了。你有另外一个卷轴吗？', 28153),
(152004, 'zhCN', '丛林巨口蛙跳入了水中！', '', 28153),
(152003, 'zhCN', '溃烂！', '', 28153),
(152002, 'zhCN', '适合感染！', '', 28153),
(152001, 'zhCN', '爆发是必然的……', '', 28153),
(152000, 'zhCN', '', '好人。呸！他可不是什么好人。', 28153),
(151999, 'zhCN', '', '你找到卑鄙的幕后黑手”好人先生“了吗？', 28153),
(151998, 'zhCN', '血肉宿主！', '', 28153),
(151990, 'zhCN', '接下来……该拿战利品了。', '', 28153),
(151989, 'zhCN', '珍珠归我们了！有了它，我们的舰船将成为海上的霸主！', '', 28153),
(151987, 'zhCN', '', '享受这场胜利吧，不会再有下次了。', 28153),
(151986, 'zhCN', '弱肉强食，这就是荒野的法则。', '', 28153),
(151985, 'zhCN', '保持警惕。有看不见的力量在跟踪我们。', '', 28153),
(151983, 'zhCN', '联盟不配获得这件宝物。反抗我们的人都得死！', '', 28153),
(151982, 'zhCN', '', '你让我的生意回来了，所以是的。让瑟希做老大就意味着，我们能在这里再次赚大钱了。', 28153),
(151981, 'zhCN', '你会支持瑟希·狂炮吗？', '你会支持瑟希·狂炮吗？', 28153),
(151980, 'zhCN', '', '这地方曾经利润要高得多。', 28153),
(151979, 'zhCN', '', '我们先离开这里，跟我走！', 28153),
(151978, 'zhCN', '斯托颂家族将统治这片沉没的王国。潮汐之母的愤怒注定了这一切。', '', 28153),
(151977, 'zhCN', '舰队……将属于她……', '', 28153),
(151976, 'zhCN', '我之前只是在戏弄他们而已，大人。我保证完成任务！', '', 28153),
(151975, 'zhCN', '我们的命运就要降临。不能让他们进入风暴神殿。', '', 28153),
(151974, 'zhCN', '', '看看你变成了什么样子。这些血债都要算在你的头上。', 28153),
(151973, 'zhCN', '卷轴漂浮起来，发出嗡嗡的声响，其它地方都被魔法遮蔽了视线。', '', 28153),
(151972, 'zhCN', '世界之魂存活概率：近乎为零……', '', 28153),
(151971, 'zhCN', '行星感染即将到来。', '', 28153),
(151970, 'zhCN', '我们应该让铁潮海盗拿走财宝。', '我们应该让铁潮海盗拿走财宝。', 28153),
(151969, 'zhCN', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s制造一个|cFFFF0000|Hspell:267891|h[迅捷结界]|h|r!', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s制造一个|cFFFF0000|Hspell:267891|h[迅捷结界]|h|r!', 28153),
(151968, 'zhCN', '<直接捅他>', '<直接捅他>', 28153),
(151967, 'zhCN', '……你是认真的吗？', '……你是认真的吗？', 28153),
(151966, 'zhCN', '太扯了！我才不会为这个付钱！', '太扯了！我才不会为这个付钱！', 28153),
(151965, 'zhCN', '夜里的地铺是五十金币。如果想睡在火炉边，那是六十金币。毯子要自备。\n\n想睡床是一百金币。\n\n绑定炉石是每周七十五金币。\n\n不喜欢？\n\n<他咳了两声，双臂交叉，脸上带着假笑。>\n\n很遗憾。这就是现价。', '', 28153),
(151964, 'zhCN', '深海宣告了你的到来……以及死亡！', '', 28153),
(151963, 'zhCN', '侦测到大规模损害。', '', 28153),
(151962, 'zhCN', '', '我们必须聚集力量，斩草除根。', 28153),
(151961, 'zhCN', '', '泰坦守护者为我们争取到了时间，但我们无法抑制戈霍恩太久。', 28153),
(151960, 'zhCN', '侦测到剧毒样本。最高抑制优先级。', '', 28153),
(151959, 'zhCN', '吞食！消灭！扩散！', '', 28153),
(151958, 'zhCN', '', '它在找它的母亲？希望它能带我们找到什么有用的东西，帮助我们阻止这场灾难。', 28153),
(151957, 'zhCN', '戈霍恩抑制失败。纯净圣母无应答。', '', 28153),
(151954, 'zhCN', '', '要是让这东西离开这里，我们将再也无法阻止它。', 28153),
(151953, 'zhCN', '', '我以前从没见过这种腐化。', 28153),
(151952, 'zhCN', '', '不能让它出去！现在就消灭它！', 28153),
(151951, 'zhCN', '', '啊！这是什么鬼东西？！', 28153),
(151950, 'zhCN', '', '做好准备。天知道这些洞里藏着什么东西。', 28153),
(151949, 'zhCN', '', '鲜血巨魔四散溃败，但我们必须找出腐化的根源并消灭它。', 28153),
(151948, 'zhCN', '我们给你带来了礼物，伟大的死亡之神！', '', 28153),
(151947, 'zhCN', '如果这意味着这里会有些新面孔的话，我没意见。', '', 28153),
(151946, 'zhCN', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t $s开始施放|cFFFF0404|Hspell:260773|h[恐怖仪式]了|h|r！', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t %s开始施放|cFFFF0404|Hspell:260773|h[恐怖仪式]了|h|r！', 28153),
(151945, 'zhCN', '你会支持瑟希·狂炮吗？', '你会支持瑟希·狂炮吗？', 28153),
(151944, 'zhCN', '你是要买还是要卖？', '', 28153),
(151943, 'zhCN', '', '看起来不太妙……', 28153),
(151942, 'zhCN', '乐意至极。他们会在您的尊名下痛苦万分！', '', 28153),
(151941, 'zhCN', '侦测到感染。开始清理。', '', 28153),
(151940, 'zhCN', '疫病爆炸！', '', 28153),
(151939, 'zhCN', '正在启动最终防卫措施。摧毁传染根源。', '', 28153),
(151938, 'zhCN', '马上就办，大人。只是，我得先清理掉一些害虫。', '我会立刻行动，大人。只是，我需要先清理掉一些害虫。', 28153),
(151937, 'zhCN', '正在净化区域。', '', 28153),
(151936, 'zhCN', '执行净化协议。', '', 28153),
(151935, 'zhCN', '邪恶割裂！', '', 28153),
(151934, 'zhCN', '不过是断了几根骨头……没什么大不了的。', '', 28153),
(151933, 'zhCN', '带我们去狐人的营地吧，$p。财宝我们来拖。', '', 28153),
(151932, 'zhCN', '鲜血逐除！', '', 28153),
(151931, 'zhCN', '', '放下武器！你还有选择！', 28153),
(151930, 'zhCN', '必须……扩散……', '', 28153),
(151929, 'zhCN', '凋零扩散！', '', 28153),
(151928, 'zhCN', '感染成功！', '', 28153),
(151927, 'zhCN', '腐化血肉。', '', 28153),
(151926, 'zhCN', '吞噬！', '', 28153),
(151925, 'zhCN', '必须扩散！', '', 28153),
(151924, 'zhCN', '别忘了我们的交易，现在……', '', 28153),
(151923, 'zhCN', '哈哈哈哈！看见了吗，陛下？邦桑迪向来信守承诺！', '', 28153),
(151922, 'zhCN', '起来……起来吧！不要懒惰！带上你们的长矛去战斗！', '', 28153),
(151921, 'zhCN', '放轻松，陛下。邦桑迪永远会帮助他的朋友……', '', 28153),
(151920, 'zhCN', '', '别光在那看着我工作。我们都有活儿要干。', 28153),
(151919, 'zhCN', '等我们准备好，就可以乘小船出发了。', '', 28153),
(151918, 'zhCN', '那些叛徒让我失去了我的王国，而你承诺的帮助呢？你打算信守诺言吗？', '', 28153),
(151916, 'zhCN', '做得好，勇士。我能感觉到艾泽拉斯正在恢复她的力量，谢谢你。', '', 28153),
(151915, 'zhCN', '附近有多处暴露在外的艾泽里特伤痕，用你的艾泽拉斯之心治愈它们！', '', 28153),
(151913, 'zhCN', '在你还能逃跑的时候，赶快逃吧！', '', 28153),
(151912, 'zhCN', '啧啧！陛下，您和神灵说话的口气可不太尊重啊。但我想，我今天收集到的灵魂足以弥补你的失礼了！', '', 28153),
(151911, 'zhCN', '我们已经和你在一条船上了，$p。\n\n不成功便成仁。', '', 28153),
(151910, 'zhCN', '邦桑迪，现身吧！', '', 28153),
(151909, 'zhCN', '太多人站在祖尔一边。前路只有一条了……', '', 28153),
(151908, 'zhCN', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s 注意|cFFFF0000$n|r准备|cFFFF0000|Hspell:266951|h[翻滚]|h|r！', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s 注视着|cFFFF0000$n|r并准备施放|cFFFF0000|Hspell:266951|h[翻滚]|h|r！', 28153),
(151907, 'zhCN', '守护塞塔里斯之心的远古结界被一群赞达拉巨魔关闭了……', '守护塞塔里斯之心的远古结界被一群赞达拉巨魔关闭了……', 28153),
(151906, 'zhCN', '是的，我会支持瑟希的。', '', 28153),
(151905, 'zhCN', '快去干活，你这个懒惰的地精，我要那个盒子里的底座马上安好！', '快去干活，你这个懒惰的地精，我要那个盒子里的底座马上安好！', 28153),
(151904, 'zhCN', '你会支持瑟希·狂炮吗？', '你会支持瑟希·狂炮吗？', 28153),
(151902, 'zhCN', '唔。是的。让我看看。\n\n<库达翻来覆去找了半天，然后从背包深处找出一个罐子。>\n\n这个是几百年前买的。我都差点忘了它。我想我可以把它卖掉。', '', 28153),
(151901, 'zhCN', '你听说过一种叫“世纪酱汁”的东西吗？你这里有吗？', '你听说过一种叫“世纪酱汁”的东西吗？你这里有吗？', 28153),
(151900, 'zhCN', '你好$r。你有什么想要卖的吗？', '', 28153),
(151899, 'zhCN', '它乘着浪潮来了！', '它乘着浪潮来了！', 28153),
(151898, 'zhCN', '无穷的欲望，国王的盛宴。', '', 28153),
(151897, 'zhCN', '伤口在溃烂。世界在腐化。', '', 28153),
(151896, 'zhCN', '我们一直都在你心里。', '', 28153),
(151895, 'zhCN', '腐坏的尖叫预示着他的降临。', '', 28153),
(151894, 'zhCN', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|t智者扎纳扎尔开始施放|cFFFF0000|Hspell:267273|h[毒性新星]|h|r！', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|t智者扎纳扎尔开始施放|cFFFF0000|Hspell:267273|h[毒性新星]|h|r！', 28153),
(151893, 'zhCN', '', '蠕动者觉醒了！', 28153),
(151892, 'zhCN', '', 'Kril lax qutholil！', 28153),
(151890, 'zhCN', '你已经作为我的化身对抗纳迦，并且终结了我的神殿所受的袭击。', '', 28153),
(151889, 'zhCN', '', '噢！我想用世纪酱汁想了很多年！这是一种用多重原料混合在一起制作的烹饪酱汁，可以发酵几个世纪。发酵的时间越久，味道就越醇厚。据说能给任何菜肴都增添一种独特而浓烈的香料味道。\n\n也有传言说始祖龟商人带着它，但非常稀有且昂贵。\n\n<荀叹了口气，充满向往>\n\n那是厨师的梦想原料！', 28153),
(151888, 'zhCN', '哇！你这儿的货物真是应有尽有。但总感觉好像缺点什么，是不是？', '哇！你这儿的货物真是应有尽有。但总感觉好像缺点什么，是不是？', 28153),
(151887, 'zhCN', '', '一个新面孔！感觉还挺友善的。想来点特别的吗？还是说你在找稀有的调料和食谱？', 28153),
(151886, 'zhCN', '多亏有你，艾泽拉斯之心更强大了。距离治愈艾泽拉斯的伤口又近了一步。', '', 28153),
(151885, 'zhCN', '我感应到附近有艾泽里特……还有人想要为了自己的目的而滥用它。你要去阻止他们！', '', 28153),
(151884, 'zhCN', '来，小东西。让你的心平静下来，帮我治疗这个人。', '', 28153),
(151883, 'zhCN', '', '鲜血在深渊中倾泻。', 28153),
(151882, 'zhCN', '', '波涛之下，你的真理在等待。', 28153),
(151881, 'zhCN', '', '聆听溺亡者的乐音。', 28153),
(151880, 'zhCN', '', '黑暗生根。灾疫扩散。门扉开启。', 28153),
(151879, 'zhCN', '', '深渊会吞噬你的惨叫！', 28153),
(151878, 'zhCN', '', '我在你肺里安家了！', 28153),
(151877, 'zhCN', '', '我会在黑暗中……等你……', 28153),
(151876, 'zhCN', '', '你归我了！', 28153),
(151875, 'zhCN', '', '你的盟友喜欢看着你死去。', 28153),
(151874, 'zhCN', '', '我们被束缚在无尽的海渊中，直到永远。', 28153),
(151873, 'zhCN', '你全身上下毫无可取之处。', '', 28153),
(151872, 'zhCN', '脆弱不堪！一无是处！', '', 28153),
(151871, 'zhCN', '你是最羸弱的一支！', '', 28153),
(151870, 'zhCN', '这怎么……可能……', '', 28153),
(151869, 'zhCN', 'Ul basha krix。', '', 28153),
(151868, 'zhCN', '', '朝天空全力开火！把它们打下来。', 28153),
(151867, 'zhCN', '劣等生物要么臣服……要么灭亡！', '', 28153),
(151866, 'zhCN', '', '为了部落！', 28153),
(151865, 'zhCN', '', '不要对他们手软！', 28153),
(151864, 'zhCN', 'Ug\' crish zul Thraxas！', '', 28153),
(151863, 'zhCN', '', '瞄准开火！我们的地面部队就靠你们了。', 28153),
(151862, 'zhCN', '', '继续开火！', 28153),
(151861, 'zhCN', '这座陵墓将成为你的葬身之地！', '', 28153),
(151860, 'zhCN', '你是对抗不了赞达拉的！', '', 28153),
(151859, 'zhCN', '这座神殿将臣服于戈霍恩的力量！', '', 28153),
(151858, 'zhCN', '赞达拉将会统治一切！', '', 28153),
(151857, 'zhCN', '', '这边！战斗在召唤我们！', 28153),
(151856, 'zhCN', '戈霍恩是无法阻止的！', '', 28153),
(151855, 'zhCN', '为血神流血吧！', '', 28153),
(151854, 'zhCN', '我先自己去调查一下。不管我找到了啥，我都会在第一时间告诉你。', '', 28153),
(151853, 'zhCN', '你们都听到了！我们最好先查清楚上古之神腐化的源头……然后再一锤子朝它头上抡过去！', '', 28153),
(151852, 'zhCN', '哈！祖尔，你就只有这点能耐？难怪巨魔帝国会没落！', '', 28153),
(151850, 'zhCN', '你那病态的尸体也应该塞进这口棺材里面。', '', 28153),
(151849, 'zhCN', '为风暴之末的荣誉与荣耀而战！', '为风暴之末的荣誉与荣耀而战！', 28153),
(151848, 'zhCN', '我的利刃为你效力。', '我的利刃为你效力。', 28153),
(151847, 'zhCN', '我还没死呢！', '我还没死呢！', 28153),
(151846, 'zhCN', '我们要一起阻止这些恶魔！', '我们要一起阻止这些恶魔！', 28153),
(151845, 'zhCN', '只要我还活着，这个村庄就是自由的！', '只要我还活着，这个村庄就是自由的！', 28153),
(151844, 'zhCN', '如果风暴之末召唤我，我必须回应。', '如果风暴之末召唤我，我必须回应。', 28153),
(151843, 'zhCN', '无论生死，我们的时辰已到。', '无论生死，我们的时辰已到。', 28153),
(151842, 'zhCN', '我站在你这边！', '我站在你这边！', 28153),
(151841, 'zhCN', '可惜你不在这里，祖尔，不然你就能看到你的构造体碎成渣了。', '', 28153),
(151840, 'zhCN', '啊！我们走着瞧，你这巨魔懦夫！', '', 28153),
(151839, 'zhCN', '很快他们就会崛起，而反抗戈霍恩的人都会灭亡！', '', 28153),
(151838, 'zhCN', '或许我们还有机会！为了风暴之末！', '或许我们还有机会！为了风暴之末！', 28153),
(151837, 'zhCN', '愚蠢！我的力量已经将古代灵魂和我主人的意志相连。', '', 28153),
(151836, 'zhCN', '我听到了风暴之歌。希望依然存在！', '我听到了风暴之歌。希望依然存在！', 28153),
(151835, 'zhCN', '还有其他人。我们有一部分人没有迷失！', '还有其他人。我们有一部分人没有迷失！', 28153),
(151834, 'zhCN', '我不知道是什么黑暗魔法在此生根，但我们最好想办法驱散它。', '', 28153),
(151833, 'zhCN', '我们不是这种人。我们仍能阻止斯托颂勋爵！', '我们不是这种人。我们仍能阻止斯托颂勋爵！', 28153),
(151832, 'zhCN', '根据我的调查，这里是赞达拉第一位大王的安息之地。', '', 28153),
(151831, 'zhCN', '大门攻破了。快上！为联盟夺回阿拉希！', '', 28153),
(151830, 'zhCN', '派克还活着？我马上去找他。', '派克还活着？我马上去找他。', 28153),
(151829, 'zhCN', '大门攻破了。快上！从部落手上夺回阿拉希！', '', 28153),
(151828, 'zhCN', '看，大门打破了！上上上！', '', 28153),
(151827, 'zhCN', '', '攻破大门了！前进！', 28153),
(151826, 'zhCN', '大门攻破了！踏平要塞！', '', 28153),
(151825, 'zhCN', '为了赞达拉……也为了你们的国度……请务必阻止他。', '', 28153),
(151824, 'zhCN', '大门已经攻破！现在拿下堡垒！', '', 28153),
(151823, 'zhCN', '我们必须马上开启风暴神殿！', '我们必须马上开启风暴神殿！', 28153),
(151822, 'zhCN', '他主人的力量与日俱增。祖尔不会善罢甘休，他会让血神夺取整个世界。', '', 28153),
(151821, 'zhCN', '结束了，阿拉希回到了我们手上。为了联盟！', '', 28153),
(151820, 'zhCN', '风暴在我体内觉醒。我要对抗暗影！', '风暴在我体内觉醒。我要对抗暗影！', 28153),
(151819, 'zhCN', '', '我们必将胜利。为了部落！', 28153),
(151818, 'zhCN', '你们让我免遭残酷的命运，但祖尔只是更大阴谋中的一枚棋子。', '', 28153),
(151817, 'zhCN', '滚回你主子那儿去，看看他怎么惩罚你的失败！', '', 28153),
(151816, 'zhCN', '我就知道这一天迟早会来。我选择加入其他人。', '我就知道这一天迟早会来。我选择加入其他人。', 28153),
(151815, 'zhCN', '不可能！没人能抗拒戈霍恩之力！', '', 28153),
(151814, 'zhCN', '你们打破了祖尔的束缚！我再也不用听命于那头猪猡了！', '', 28153),
(151813, 'zhCN', '想抱怨就抱怨吧，我的国王……你应该知道，没人能从戈霍恩手中逃走。', '', 28153),
(151812, 'zhCN', '入侵者当然得死……但我可不想听你喋喋不休。', '', 28153),
(151811, 'zhCN', '我毕生都在对抗你的主人，但你却在我死后，用他的意志控制我。', '', 28153),
(151810, 'zhCN', '闭嘴，油嘴滑舌的先知！', '', 28153),
(151809, 'zhCN', '这里是赞达拉第一任国王的安息之地。达萨生性固执……但现在他只能听命于我！', '', 28153),
(151808, 'zhCN', '你疯了吗？', '你疯了吗？', 28153),
(151807, 'zhCN', '说出你的意见。', '说出你的意见。', 28153),
(151806, 'zhCN', '但在死后，我给了他们共同的目标，那就是杀死你。', '', 28153),
(151805, 'zhCN', '大地带我走。', '大地带我走。', 28153),
(151804, 'zhCN', '生前他们憎恨彼此，最终落得同归于尽的下场。', '', 28153),
(151803, 'zhCN', '曾有一段时期，巨魔帝国由三位君主分而治之。你正在接近这三位君主。', '', 28153),
(151802, 'zhCN', '这里不允许外乡人乱逛。', '这里不允许外乡人乱逛。', 28153),
(151801, 'zhCN', '海潮退去，大地升起！', '海潮退去，大地升起！', 28153),
(151800, 'zhCN', '我相信用它来对付你也绰绰有余。', '', 28153),
(151799, 'zhCN', '亡者堆满了神殿，我们便制造了魔像来处理这些病死的尸体。', '', 28153),
(151798, 'zhCN', '数千年前，一场血液传染病几乎摧毁了整个赞达拉。', '', 28153),
(151797, 'zhCN', '很快他们就会崛起，而反抗戈霍恩的人都会灭亡！', '', 28153),
(151796, 'zhCN', '我的力量已经在此扎根，让古代灵魂与我主人的意志相连。', '', 28153),
(151795, 'zhCN', '欢迎来到第一任巨魔国王的陵墓。我要是能亲自迎接你们就好了。', '', 28153),
(151794, 'zhCN', '我告诉过你，我不会掺和你们这些破事的！', '我告诉过你，我不会掺和你们这些破事的！', 28153),
(151793, 'zhCN', '我这次可不会失败了。', '我这次可不会失败了。', 28153),
(151792, 'zhCN', '那……那样安全吗？', '那……那样安全吗？', 28153),
(151791, 'zhCN', '我们是创业和乔迁专家。跟这些该死的红衣佣兵不一样。我们可不是海盗。', '', 28153),
(151790, 'zhCN', '', '英雄，我们回去找凯瑟琳吧。', 28153),
(151789, 'zhCN', '', '你们三个去下面搜查一下，看看能不能找到她！', 28153),
(151788, 'zhCN', '', '等等，不！', 28153),
(151787, 'zhCN', '', '臭小子。我跟你没完！', 28153),
(151786, 'zhCN', '', '都结束了。你无路可逃了。', 28153),
(151785, 'zhCN', '', '快闪开，猪脑袋！', 28153),
(151784, 'zhCN', '', '接招！', 28153),
(151783, 'zhCN', '', '你的小把戏根本没用！这城市是我的！', 28153),
(151782, 'zhCN', '我会在这里等着，以防有人找到了回家的路！', '', 28153),
(151781, 'zhCN', '', '如果是我说了算，情况一定会好得多。\n\n等那些铁潮海盗走了，所有人都可以来这里做买卖。那样太棒了！', 28153),
(151780, 'zhCN', '', '啊！那些红衣服的混蛋出现之前，一切都很好。', 28153),
(151779, 'zhCN', '听着，我只想糊口而已。', '', 28153),
(151778, 'zhCN', '托恩塞尔和他的人对生意没好处。如果情况再遭下去，我就要带着我的鸟一走了之。', '', 28153),
(151777, 'zhCN', '我当时就要发财了……', '', 28153),
(151776, 'zhCN', '你想妨碍我们？我干掉的家伙可不少！', '', 28153),
(151775, 'zhCN', '', '你抢不走这片林地！', 28153),
(151774, 'zhCN', '', '谢谢你。我以为我要独自面对他们。我马上回去找墨文。', 28153),
(151773, 'zhCN', '我喜欢你在这里做的一切。', '', 28153),
(151772, 'zhCN', '很久很久之前，我们始祖龟就开始在这个地方做生意了。最终，赞达拉巨魔也在我们身边一点一点强大起来，但是他们现在也不好过了。而我们自然还能忍耐下去。', '', 28153),
(151771, 'zhCN', '我就在这里干活。不用去冒险。', '', 28153),
(151770, 'zhCN', 'Lok-tar ogar！', 'Lok-tar ogar！', 28153),
(151769, 'zhCN', 'Lok-narash！', 'Lok-narash！', 28153),
(151768, 'zhCN', 'Gakarah ma！', 'Gakarah ma！', 28153),
(151767, 'zhCN', '在部落面前倒下吧！', '在部落面前倒下吧！', 28153),
(151766, 'zhCN', '为了部落！', '为了部落！', 28153),
(151765, 'zhCN', '是敌人，就得死！', '是敌人，就得死！', 28153),
(151764, 'zhCN', '今天是你的死期！', '今天是你的死期！', 28153),
(151763, 'zhCN', '荣耀……的……战死……', '荣耀……的……战死……', 28153),
(151762, 'zhCN', '哈！报告，我看到了。把它扔到箱子里，然后回去干活儿！', '', 28153),
(151761, 'zhCN', '先祖……我来了……', '先祖……我来了……', 28153),
(151760, 'zhCN', '你赢不了……这场战争……', '你赢不了……这场战争……', 28153),
(151759, 'zhCN', '你的末日……终将来临……', '你的末日……终将来临……', 28153),
(151758, 'zhCN', '我战死……沙场……', '我战死……沙场……', 28153),
(151757, 'zhCN', '我的战斗……到此为止了……', '我的战斗……到此为止了……', 28153),
(151756, 'zhCN', '我将魂归……德拉诺……', '我将魂归……德拉诺……', 28153),
(151755, 'zhCN', '祝你死得光荣。', '祝你死得光荣。', 28153),
(151754, 'zhCN', '不想再跟你聊了。', '不想再跟你聊了。', 28153),
(151753, 'zhCN', '快走吧。\n', '快走。', 28153),
(151752, 'zhCN', '带着荣耀前进吧。', '带着荣耀前进吧。', 28153),
(151751, 'zhCN', '愿你的刀刃永远锋利。', '愿你的刀刃永远锋利。', 28153),
(151750, 'zhCN', '向胜利前进吧。', '向胜利前进吧。', 28153),
(151749, 'zhCN', '就这样吧。', '就这样吧。', 28153),
(151748, 'zhCN', '有话就说。', '有话就说。', 28153),
(151747, 'zhCN', '很高兴见到你。', '很高兴见到你。', 28153),
(151746, 'zhCN', 'Lok-tar！', 'Lok-tar！', 28153),
(151745, 'zhCN', 'Throm-ka！', 'Throm-ka！', 28153);
