(151564, 'zhCN', '你错了，女伯爵莉亚德琳。联盟的旗帜将再次在阿拉希的上空飘扬。', '', 28153),
(151563, 'zhCN', '', '别惹我发笑了，达纳斯。托尔贝恩家族早就没落了。', 28153),
(151562, 'zhCN', '我不能拾取它。', '', 28153),
(151561, 'zhCN', '这不是我的东西。', '', 28153),
(151560, 'zhCN', '我需要再靠近一点。', '', 28153),
(151559, 'zhCN', '我可没听说过你，暗影猎手。', '', 28153),
(151558, 'zhCN', '太远了。', '', 28153),
(151557, 'zhCN', '我够不着它。', '', 28153),
(151556, 'zhCN', '达纳斯·托尔贝恩。真是久仰你的大名……', '', 28153),
(151555, 'zhCN', '我无法交易它。', '', 28153),
(151554, 'zhCN', '无法使用。', '', 28153),
(151553, 'zhCN', '我还没有装备它。', '', 28153),
(151552, 'zhCN', '不，阿拉希属于我。你和你的部落会因为擅闯此地而付出代价，伊崔格。', '', 28153),
(151551, 'zhCN', '我必须先装备它。', '', 28153),
(151550, 'zhCN', '托尔贝恩！你还是快滚吧。阿拉希已经属于部落了。', '', 28153),
(151549, 'zhCN', '但首先，我们得加固这里的防御。帮我们找点木材和铁矿。', '', 28153),
(151548, 'zhCN', '碾碎这个敌人！', '', 28153),
(151547, 'zhCN', '的确如此，女伯爵莉亚德琳。我很期待能对误入歧途的部落圣骑士施以正义的审判。', '', 28153),
(151546, 'zhCN', '攻击我的目标！', '', 28153),
(151545, 'zhCN', '击垮我的敌人！', '', 28153),
(151544, 'zhCN', '走这边。', '', 28153),
(151543, 'zhCN', '让兽人带路。', '', 28153),
(151542, 'zhCN', '', '图拉扬？这下子有意思了……', 28153),
(151541, 'zhCN', '跟我来。', '', 28153),
(151540, 'zhCN', '为了部落！', '', 28153),
(151539, 'zhCN', '我受伤了！', '', 28153),
(151538, 'zhCN', '治疗者，快帮我！', '', 28153),
(151537, 'zhCN', '不要傻站着——快帮我！', '', 28153),
(151536, 'zhCN', '马上来帮我！', '', 28153),
(151535, 'zhCN', '坚持住。', '', 28153),
(151534, 'zhCN', '待着别动。', '', 28153),
(151533, 'zhCN', '圣光与我们同在，洛坎。我们不惧怕暗影。', '', 28153),
(151532, 'zhCN', '当心暗影，图拉扬。我和部落会来找你的。', '', 28153),
(151531, 'zhCN', '为荣耀而死！', '', 28153),
(151530, 'zhCN', '攻击！', '', 28153),
(151529, 'zhCN', 'Mok-thora ka！', '', 28153),
(151528, 'zhCN', '碾碎我们的敌人吧！', '', 28153),
(151527, 'zhCN', '该把你和你的部落军队从阿拉希的丘陵里轰走了，伊崔格。', '', 28153),
(151526, 'zhCN', '击溃他们的阵线！', '', 28153),
(151525, 'zhCN', '不撤退就得死！', '', 28153),
(151524, 'zhCN', '改日再战！', '', 28153),
(151523, 'zhCN', '走！快走！', '', 28153),
(151522, 'zhCN', '我居然在战场上闻到了联盟的臭味？看来不打不行了。', '', 28153),
(151521, 'zhCN', '准备就绪！', '', 28153),
(151520, 'zhCN', '每隔一段时间检查下。我讨厌看到那个箱子里的钢铁被白白浪费。', '', 28153),
(151519, 'zhCN', '全都烧死！', '', 28153),
(151518, 'zhCN', '开火！', '', 28153),
(151517, 'zhCN', '他们马上就到了。我们得建好基地，也就是说得找点木材和铁矿。', '', 28153),
(151516, 'zhCN', '等我把你们这些部落打得屁滚尿流，你们就只能吃土啦！', '', 28153),
(151515, 'zhCN', '', '退下，穆拉丁。这里可是部落的领土。', 28153),
(151514, 'zhCN', '不，我只是想找几个部落杂种来试刀！', '', 28153),
(151513, 'zhCN', '你在这儿干什么，穆拉丁？想打架吗？', '', 28153),
(151512, 'zhCN', '还是滚回你们那片荒地吧，满身跳蚤的兽人！', '', 28153),
(151511, 'zhCN', '穆拉丁！你的矮人越界了。滚回你们的山里去。', '', 28153),
(151510, 'zhCN', '', '联盟很快就会打到我们门口。我们得快点行动，夺取木材和铁矿，建立基地。', 28153),
(151509, 'zhCN', '', '你真是老糊涂了。我们是来夺回激流堡的。', 28153),
(151508, 'zhCN', '女伯爵莉亚德琳！欢迎来到阿拉希。想必你是来投诚的吧？', '', 28153),
(151507, 'zhCN', '', '你离开太久了，图拉扬。这个世界没了你也能转。', 28153),
(151506, 'zhCN', '这是什么情况？圣骑士领导着一群部落的入侵者？这世界怎么变成这样了？', '', 28153),
(151505, 'zhCN', '', '你倒是试试啊，穆拉丁。这儿现在归部落了。', 28153),
(151504, 'zhCN', '你最好不要轻举妄动，丫头，小心被联盟的迫击炮炸糊了脸。', '', 28153),
(151503, 'zhCN', '达纳斯·托尔贝恩……你我可算是杠上了！我们待会儿在战场上一决雌雄吧……', '', 28153),
(151502, 'zhCN', '你们胆敢入侵阿拉希？还找个巨魔作为指挥官？这可是大错特错。', '', 28153),
(151501, 'zhCN', '“绿皮兽人”？哦呵呵……这下你可惹毛我了。', '', 28153),
(151500, 'zhCN', '夺回', '夺回', 28153),
(151499, 'zhCN', '<克劳斯不屑地一笑>\n\n是啊，很有可能。我们到处都有亲戚。', '', 28153),
(151498, 'zhCN', '你胆敢入侵托尔贝恩家族的领地激流堡？快给我滚，绿皮兽人。', '', 28153),
(151497, 'zhCN', '今天，我们要夺回自古以来的领土。为了联盟！', '', 28153),
(151496, 'zhCN', '长久以来，激流堡一直遭到入侵和劫掠。', '', 28153),
(151495, 'zhCN', '为了联盟！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151494, 'zhCN', '联盟的士兵们！今天，我们要从部落的禽兽手中夺回激流堡，这座城市是联盟的荣耀。', '', 28153),
(151493, 'zhCN', '今天，我们要夺回阿拉希高地……为了联盟！', '', 28153),
(151492, 'zhCN', '子弹上膛，利剑出鞘。', '', 28153),
(151491, 'zhCN', '', '阿拉希必将属于我们！为了部落！', 28153),
(151490, 'zhCN', '', '专心完成当前的任务。先攻下阿戈罗克，再向激流堡进军！', 28153),
(151489, 'zhCN', '法温德？我见过这个姓的人。', '法温德？我见过这个姓的人。', 28153),
(151488, 'zhCN', '把它打包装起来，伙计们！把这些武器运出去！', '', 28153),
(151487, 'zhCN', '激流堡的要塞已经升级成了城堡。', '', 28153),
(151486, 'zhCN', '军械库的修建已经完成。', '', 28153),
(151485, 'zhCN', '车间准备完毕。', '', 28153),
(151484, 'zhCN', '我们的议政厅已经升级为要塞。', '', 28153),
(151483, 'zhCN', '列王祭坛已经完工。', '', 28153),
(151482, 'zhCN', '我们的要塞现在是城堡了！', '', 28153),
(151481, 'zhCN', '军械库完工了。', '', 28153),
(151480, 'zhCN', '车间准备完毕，可以制造坦克了。', '', 28153),
(151479, 'zhCN', '我们的议政厅已经升级为要塞。', '', 28153),
(151478, 'zhCN', '列王祭坛已经完工。', '', 28153),
(151477, 'zhCN', '很好！我们的要塞已经升级成了城堡！', '', 28153),
(151476, 'zhCN', '军械库准备完毕，可以武装部队了！', '', 28153),
(151475, 'zhCN', '车间开始运转了。来造点坦克吧！', '', 28153),
(151474, 'zhCN', '议政厅已经升级为要塞！', '', 28153),
(151473, 'zhCN', '列王祭坛准备完毕！', '', 28153),
(151472, 'zhCN', '', '我们的据点升级为堡垒了。为了部落！', 28153),
(151471, 'zhCN', '', '新建的军械库可以为部队提供更好的装备。', 28153),
(151470, 'zhCN', '', '车间已经完工。', 28153),
(151469, 'zhCN', '', '我们的基地变强了。大厅升级成了据点。', 28153),
(151468, 'zhCN', '', '风暴祭坛准备就绪。', 28153),
(151467, 'zhCN', '兵营准备完毕，可以训练部队了。', '', 28153),
(151466, 'zhCN', '我们的兵营完工了。该训练部队了。', '', 28153),
(151465, 'zhCN', '我们有兵营了！开始训练部队吧！', '', 28153),
(151464, 'zhCN', '', '兵营准备就绪，可以训练部队了。', 28153),
(151463, 'zhCN', '据点现在升级为堡垒了！', '', 28153),
(151462, 'zhCN', '大厅已经升级为据点。', '', 28153),
(151461, 'zhCN', '风暴祭坛准备就绪。', '', 28153),
(151460, 'zhCN', '兵营准备就绪。这些步兵将是我们的中坚力量。', '', 28153),
(151459, 'zhCN', '我们的据点升级为堡垒了！', '', 28153),
(151458, 'zhCN', '我们的大厅升级为据点了！', '', 28153),
(151457, 'zhCN', '风暴祭坛建造完工。', '', 28153),
(151456, 'zhCN', '我们的兵营造好了，开始训练步兵吧！', '', 28153),
(151455, 'zhCN', '', '想都别想。血骑士，截住他们！', 28153),
(151454, 'zhCN', '我暗影猎手的名号也不是白叫的。好了，刺客们！现身吧！', '', 28153),
(151453, 'zhCN', '你们所谓的“联盟的正义”我听得太多了。驭风者，让他们见识下部落的愤怒！', '', 28153),
(151452, 'zhCN', '', '绝不！', 28153),
(151451, 'zhCN', '这片土地不属于你们，托尔贝恩。巨魔很早以前就在这里定居了。', '', 28153),
(151450, 'zhCN', '哈！真是自以为是。', '', 28153),
(151449, 'zhCN', '', '我已经我受够了你们的惺惺作态。血骑士，化作圣光之怒，出击！', 28153),
(151448, 'zhCN', '就算是圣光也救不了你。暗影猎手，现身吧！', '', 28153),
(151447, 'zhCN', '驭风者，空袭敌人！', '', 28153),
(151446, 'zhCN', '', '等着瞧，图拉扬。你还得过我这关。', 28153),
(151445, 'zhCN', '我恭候你的大驾。', '', 28153),
(151444, 'zhCN', '有我在就别想了，图拉扬。', '', 28153),
(151443, 'zhCN', '', '还差得远呢，矮人。血骑士，出击！', 28153),
(151442, 'zhCN', '你正好走进了我的陷阱，穆拉丁。暗影猎手，现身吧！', '', 28153),
(151441, 'zhCN', '趁现在，驭风者！攻击！', '', 28153),
(151440, 'zhCN', '', '决不。', 28153),
(151439, 'zhCN', '当心你背后吧，穆拉丁！', '', 28153),
(151438, 'zhCN', '别高兴得太早了，矮人。为了部落！', '', 28153),
(151437, 'zhCN', '我不会再让这座城市失守了，更何况是面对你们这群渣滓。防御者，让他们见识见识激流堡的力量！', '', 28153),
(151436, 'zhCN', '现在安全了。该回去工作了。', '', 28153),
(151435, 'zhCN', '圣光与我同在。防御者，前进！', '', 28153),
(151434, 'zhCN', '我会誓死守卫激流堡，莉亚德琳。防御者，站稳阵脚！', '', 28153),
(151433, 'zhCN', '先别高兴得太早，血精灵，你还得过我这关。', '', 28153),
(151432, 'zhCN', '好啊……我可等着你呢。', '', 28153),
(151431, 'zhCN', '呸！只不过是一个土坡而已！', '', 28153),
(151430, 'zhCN', '老狗也还有几颗牙，巨魔。防御者，让他们瞧瞧激流堡的力量！', '', 28153),
(151429, 'zhCN', '圣光永远都能战胜暗影，洛坎。防御者，上前来！', '', 28153),
(151428, 'zhCN', '来战吧，洛坎！我一直等着你呢。防御者，给他们点颜色瞧瞧！', '', 28153),
(151427, 'zhCN', '闭嘴，巨魔。联盟必将战胜你们这帮肮脏的怪物组成的军团。', '', 28153),
(151426, 'zhCN', '但圣光依旧照耀着激流堡。', '', 28153),
(151425, 'zhCN', '一会儿就好，小伙子。我还是先让手下的火枪手招呼你一下吧。', '', 28153),
(151424, 'zhCN', '激流堡依然挺立，兽人。我会看着你淹死在护城河里。防御者，让他们尝尝这座城市的力量！', '', 28153),
(151423, 'zhCN', '我经历过数千场战役，清楚胜利与失败的不同。而今天这场战斗还远未失败。防御者，上前来！', '', 28153),
(151422, 'zhCN', '那你也要过得来才行，小子。防御者，击退他们！', '', 28153),
(151421, 'zhCN', '哼。你跟你的同胞，最终都会下跪求饶，然后死在我的剑下。', '', 28153),
(151420, 'zhCN', '耐心点，兽人。你马上就知道自己的下场了。', '', 28153),
(151419, 'zhCN', '而我从这么远都能闻到你的口臭！放马过来吧，兽人！', '', 28153),
(151418, 'zhCN', '攻城坦克，轰开那扇大门。让那个血精灵尝尝联盟之矛的滋味！', '', 28153),
(151417, 'zhCN', '好了，攻城坦克，把大门砸开，把洛坎捉来见我！我托尔贝恩的名号可不是白叫的……', '', 28153),
(151416, 'zhCN', '好了，攻城坦克，把大门砸开。让这只恶心的兽人尝尝联盟的正义！', '', 28153),
(151415, 'zhCN', '远望栖地是我们的了。我再给你最后一次机会，血精灵。投降的话，我就饶你不死。', '', 28153),
(151414, 'zhCN', '我们已经拿下了远望栖地，接下来就是阿戈罗克，然后就能夺回本该属于我们的土地了！', '', 28153),
(151413, 'zhCN', '远望栖地是我们的了。我们正在努力消灭闯入者。', '', 28153),
(151412, 'zhCN', '有了加尔森的矿洞，就再也不用为铁矿的供应发愁了。好样的。', '', 28153),
(151411, 'zhCN', '不错。高地伐木场可以为我们提供木材，用来重建激流堡。', '', 28153),
(151410, 'zhCN', '时机到了，攻破大门！让他们尝尝与联盟作对的下场！\n', '', 28153),
(151409, 'zhCN', '机会来了。攻破大门！圣光已然降临，洛坎！', '', 28153),
(151408, 'zhCN', '机会来了。攻破大门！你完了，伊崔格！', '', 28153),
(151407, 'zhCN', '我们攻占了远望栖地。圣光与联盟同在。', '', 28153),
(151406, 'zhCN', '远望栖地归我们了，阿戈罗克也快了。我们马上冲你来了，洛坎。', '', 28153),
(151405, 'zhCN', '我们已经占领了远望栖地，很快就可以彻底消灭部落的军力了。', '', 28153),
(151404, 'zhCN', '干得漂亮。加尔森的矿洞应该可以满足我们所有的铁矿需求。', '', 28153),
(151403, 'zhCN', '伐木场的木材对修建基地至关重要。', '', 28153),
(151402, 'zhCN', '快，部署攻城坦克！砸烂大门！让那些血精灵尝尝矮人迫击炮的厉害！', '', 28153),
(151401, 'zhCN', '快，部署攻城坦克！砸烂大门！把巨魔的茅草屋炸飞！', '', 28153),
(151400, 'zhCN', '快，部署攻城坦克！砸烂大门！把兽人轰成渣！', '', 28153),
(151399, 'zhCN', '远望栖地属于联盟了！准备好投降了吗，小丫头？', '', 28153),
(151398, 'zhCN', '我们拿下了远望栖地！接下来就轮到你了，洛坎。', '', 28153),
(151397, 'zhCN', '咳……酒钱还没付清……', '咳……酒钱还没付清……', 28153),
(151396, 'zhCN', '远望栖地归我们了！为了联盟！', '', 28153),
(151395, 'zhCN', '也许……我们能做个交易……', '也许……我们能做个交易……', 28153),
(151394, 'zhCN', '我们拿下了加尔森的矿洞，铁矿的供给应该够了。', '', 28153),
(151393, 'zhCN', '很好，我们拿下了高地伐木场，有木材可以修建基地了。', '', 28153),
(151392, 'zhCN', '', '战斗需要的是技巧。你们可不行！', 28153),
(151391, 'zhCN', '', '启动投石车！把大门砸烂！把激流堡夷为平地！', 28153),
(151390, 'zhCN', '伙计，小心！', '伙计，小心！', 28153),
(151389, 'zhCN', '', '启动投石车！把大门砸烂！你完了，图拉扬！', 28153),
(151388, 'zhCN', '计划是什么？', '计划是什么？', 28153),
(151387, 'zhCN', '', '启动投石车！把大门砸烂！逼那个矮子开门！', 28153),
(151386, 'zhCN', '', '远望栖地归我们了！距离部落夺取阿拉希只有一步之遥！', 28153),
(151385, 'zhCN', '', '部落拿下了远望栖地！接下来就轮到你了，图拉扬。', 28153),
(151384, 'zhCN', '', '我们夺取了远望栖地，就是制高点。这下我们可占上风了。', 28153),
(151383, 'zhCN', '', '干得漂亮。没有铁矿，我们就无法获胜。', 28153),
(151382, 'zhCN', '你死后也是个窝囊废！滚一边去，瞧瞧我的本事！', '', 28153),
(151381, 'zhCN', '', '我们可以使用战斧山的木材为基地打基础。干得好。', 28153),
(151380, 'zhCN', '部署投石车！轰开大门！让那个老不死的托尔贝恩永远闭嘴！', '', 28153),
(151379, 'zhCN', '部署投石车！在部落的力量面前，连圣光也救不了你，圣骑士！', '', 28153),
(151378, 'zhCN', '部署投石车！那个矮人不可能永远躲在大门后面！', '', 28153),
(151377, 'zhCN', '远望栖地归部落了，托尔贝恩。', '', 28153),
(151376, 'zhCN', '远望栖地是我们的了，图拉扬。暗影逼近了……', '', 28153),
(151375, 'zhCN', '穆拉丁……我们拿下了远望栖地。你准备好出来打一架了吗？', '', 28153),
(151374, 'zhCN', '枯须矿洞属于部落了。', '', 28153),
(151373, 'zhCN', '', '哼，你们真没用，生前死后都一样。还得我来对付他们！', 28153),
(151372, 'zhCN', '很好。我们可以用战斧山的木材修筑据点。', '', 28153),
(151371, 'zhCN', '投石车，开动！轰开大门！让托尔贝恩那个蠢货瞧瞧绿皮兽人的厉害！', '', 28153),
(151370, 'zhCN', '', '你已经长大成人，英勇无畏，泰莉亚。你的父亲会为你自豪。', 28153),
(151369, 'zhCN', '投石车，开动！轰开大门！我们已经稳操胜券了！', '', 28153),
(151368, 'zhCN', '投石车，开动！轰开大门！我们要拿下那个矮人的狗命！', '', 28153),
(151367, 'zhCN', '老大会不高兴的……', '老大会不高兴的……', 28153),
(151366, 'zhCN', '远望栖地属于部落。或者说……“绿皮兽人”。', '', 28153),
(151365, 'zhCN', '远望栖地归我们了。我们的下场挺不错呢，图拉扬。', '', 28153),
(151364, 'zhCN', '哎……', '哎……', 28153),
(151363, 'zhCN', '不是……针对你……', '不是……针对你……', 28153),
(151362, 'zhCN', '我们占领了远望栖地。穆拉丁！我从这儿都能瞧见你那只大鼻子！', '', 28153),
(151361, 'zhCN', '只是……尽我的本职……', '只是……尽我的本职……', 28153),
(151360, 'zhCN', '', '泰莉亚……我想起来了。小时候你从大陆来此避难。已经过去这么久了吗？', 28153),
(151359, 'zhCN', '干得好。我们控制了枯须矿洞，这样就不会缺乏铁矿了。', '', 28153),
(151358, 'zhCN', '战斧山是我们的了。我们可以利用这里的伐木场来建造基地。', '', 28153),
(151357, 'zhCN', '不是针对你，但我们是有规矩的！', '不是针对你，但我们是有规矩的！', 28153),
(151356, 'zhCN', '唤勇之路归我们了。继续进攻！', '', 28153),
(151355, 'zhCN', '', '泰莉亚，夫人。', 28153),
(151354, 'zhCN', '干得不错。我们重新夺取了元素法阵。', '', 28153),
(151353, 'zhCN', '联盟的旗帜再度飘扬在纽斯泰德。', '', 28153),
(151352, 'zhCN', '', '当然。不过你是？', 28153),
(151351, 'zhCN', '我们拿下了唤勇之路！', '', 28153),
(151350, 'zhCN', '元素法阵现在归联盟了。', '', 28153),
(151349, 'zhCN', '干得漂亮，士兵们。纽斯泰德归我们了。', '', 28153),
(151348, 'zhCN', '停下！', '停下！', 28153),
(151347, 'zhCN', '', '海军统帅大人，也许该由我护送您回城堡。我可以在那里向您汇报艾什凡家族的罪证。', 28153),
(151346, 'zhCN', '很好，把他们从唤勇之路赶出去了。现在，继续进军！', '', 28153),
(151345, 'zhCN', '我们占领了元素法阵！', '', 28153),
(151344, 'zhCN', '你刚刚越界了！', '你刚刚越界了！', 28153),
(151343, 'zhCN', '我们搞定了纽斯泰德！', '', 28153),
(151342, 'zhCN', '', '元素法阵归我们了。', 28153),
(151341, 'zhCN', '', '我们成功占领了纽斯泰德。', 28153),
(151340, 'zhCN', '对待惹麻烦的人，我们有的是办法！', '对待惹麻烦的人，我们有的是办法！', 28153),
(151338, 'zhCN', '', '好的，这样我们就有了一些喘息的空间。', 28153),
(151337, 'zhCN', '嘿！', '嘿！', 28153),
(151336, 'zhCN', '当心暗影，联盟的渣滓。部落会来找你们的……', '', 28153),
(151335, 'zhCN', '打得好，占领了诺斯弗德路口，我们就能专注于更大的目标了。', '', 28153),
(151333, 'zhCN', '', '你！借一步说话。', 28153),
(151332, 'zhCN', '为了复仇，我等待了无数年。最终，是你母亲为我提供了机会。', '', 28153),
(151331, 'zhCN', '你的先祖灭绝了我的人民，但他们无法摧毁我。', '', 28153),
(151330, 'zhCN', '', '高莱克·图尔？！这怎么可能？我的祖先许多年前就把你打败了！', 28153),
(151329, 'zhCN', '攻城坦克，摧毁基地！', '', 28153),
(151328, 'zhCN', '我警告过你了，部落的渣滓。现在，准备迎接毁灭吧。', '', 28153),
(151327, 'zhCN', '这是属于联盟的土地！圣光会护佑激流堡，你们这样的怪物别想攻破它的城墙！', '', 28153),
(151326, 'zhCN', '我居然在战场上看到了部落？我好久没痛快地打一场了！', '', 28153),
(151324, 'zhCN', '你必须阻止这些势力……并吸收艾泽里特以强化艾泽拉斯之心！', '', 28153),
(151323, 'zhCN', '更多的伤口会在艾泽拉斯的各地出现，而更多的势力也会为了各自的利益，争夺艾泽里特的使用权。', '', 28153),
(151322, 'zhCN', '艾泽拉斯之心是治愈这颗星球的关键……但我们要想成功，就必须收集更多的能量。', '', 28153),
(151321, 'zhCN', '麦格尼，我准备好让你强化艾泽拉斯之心了。', '麦格尼，我准备好让你强化艾泽拉斯之心了。', 28153),
(151320, 'zhCN', '勇士，来希利苏斯见我。要治愈艾泽拉斯，我们还有很多事情要做！', '', 28153),
(151319, 'zhCN', '', '我可有扫帚，别以为我不敢用！', 28153),
(151318, 'zhCN', '', '退后，你们这帮会飞的啮齿动物！', 28153),
(151317, 'zhCN', '', '从我的背上下去！', 28153),
(151316, 'zhCN', '', '滚出去，你们这些肮脏的鸟！', 28153),
(151315, 'zhCN', '付出代价吧，小鬼们！', '', 28153),
(151314, 'zhCN', '梦魇之兽，现身吧！', '', 28153),
(151313, 'zhCN', '我有种好的预感。我们今天能找到它。', '我有种好的预感。我们今天能找到它。', 28153),
(151312, 'zhCN', '这些鞋子穿在我身上会很好看。', '这些鞋子穿在我身上会很好看。', 28153),
(151311, 'zhCN', '我要把你给切了！', '我要把你给切了！', 28153),
(151310, 'zhCN', '这里没人能救你了，混蛋。', '这里没人能救你了，混蛋。', 28153),
(151309, 'zhCN', '当心脚下。', '当心脚下。', 28153),
(151308, 'zhCN', '你会轻易地落败……', '你会轻易地落败……', 28153),
(151307, 'zhCN', '给我等着……', '给我等着……', 28153),
(151306, 'zhCN', '这些资源不属于你！', '这些资源不属于你！', 28153),
(151305, 'zhCN', '新货！', '新货！', 28153),
(151304, 'zhCN', '海潮升涌！崛起吧，我的仆从！', '', 28153),
(151303, 'zhCN', '蠕行恐魔，过来吃饭吧！', '', 28153),
(151302, 'zhCN', '深渊生物，聆听我的召唤！', '', 28153),
(151301, 'zhCN', '这里空气清新。不像矿洞里，全是兽人的臭味。', '', 28153),
(151300, 'zhCN', '让黑暗吞没你！', '', 28153),
(151299, 'zhCN', '我已经受够了，现在去死吧！', '', 28153),
(151298, 'zhCN', '艾萨拉的仆从是无穷无尽的，为什么要反抗呢？', '', 28153),
(151297, 'zhCN', '我现在不那么害怕了，但这些石头让我的胳膊酸痛。', '', 28153),
(151295, 'zhCN', '他已经能听到低语了。我们可能时间不多了。', '', 28153),
(151294, 'zhCN', '', '我等会就过来，不用等我！', 28153),
(151293, 'zhCN', '在海潮之下……等待……召唤……', '', 28153),
(151292, 'zhCN', '这边。我发现铁矿了。', '', 28153),
(151291, 'zhCN', '去周围的武器架找一找。无信者在这附近各处都放了武器架。\n\n我会保持隐蔽等你回来。', '去周围的武器架找一找。无信者在这附近各处都放了武器架。\n\n我会保持隐蔽等你回来。', 28153),
(151290, 'zhCN', '', '狂风，保护我！', 28153),
(151289, 'zhCN', '我给你找到武器之后就会回来。', '我给你找到武器之后就会回来。', 28153),
(151288, 'zhCN', '', '清风永远帮助着我们！', 28153),
(151287, 'zhCN', '我要把你们揍成肉泥！', '', 28153),
(151286, 'zhCN', '我的船身坚不可摧！', '', 28153),
(151285, 'zhCN', '元素之怒！', '元素之怒！', 28153),
(151284, 'zhCN', '窃取这个世界的凡人都将被灭绝。', '窃取这个世界的凡人都将被灭绝。', 28153),
(151283, 'zhCN', '我们将夺回你们所掠夺的一切！', '我们将夺回你们所掠夺的一切！', 28153),
(151282, 'zhCN', '元素将会再度统治一切！', '元素将会再度统治一切！', 28153),
(151281, 'zhCN', '你们无法从我们手上抢走这些！', '你们无法从我们手上抢走这些！', 28153),
(151280, 'zhCN', '这些宝石属于元素领主！', '这些宝石属于元素领主！', 28153),
(151279, 'zhCN', '<释放奴隶，并给他们配发武器，好让他们投入战斗。>', '<释放奴隶，并给他们配发武器，好让他们投入战斗。>', 28153),
(151278, 'zhCN', '有了这种力量，我们就能夺回这个世界！', '有了这种力量，我们就能夺回这个世界！', 28153),
(151277, 'zhCN', '<释放奴隶，并给他们配发武器，好让他们投入战斗。>', '<释放奴隶，并给他们配发武器，好让他们投入战斗。>', 28153),
(151276, 'zhCN', '毁灭你们后，我的主人会奖励我。', '毁灭你们后，我的主人会奖励我。', 28153),
(151275, 'zhCN', '给我一把武器，我就能帮你消灭十个无信者。', '给我一把武器，我就能帮你消灭十个无信者。', 28153),
(151274, 'zhCN', '拿上你的东西。跟我一起走。', '拿上你的东西。跟我一起走。', 28153),
(151273, 'zhCN', '打破这些锁链，朋友。狐人注定自由。', '打破这些锁链，朋友。狐人注定自由。', 28153),
(151272, 'zhCN', '我想工作，但现在不安全。', '', 28153),
(151271, 'zhCN', '放了我，$pr，我会帮你干掉无信者。', '放了我，$pr，我会帮你干掉无信者。', 28153),
(151270, 'zhCN', '不要对无信者留情。他们的所做所为不值得怜悯。', '不要对无信者留情。他们的所做所为不值得怜悯。', 28153),
(151269, 'zhCN', '我要无信者为他们对我的所作所为付出代价。', '我要无信者为他们对我的所作所为付出代价。', 28153),
(151268, 'zhCN', '尼莎派你来的？无论她有什么计划，都算我一个。', '尼莎派你来的？无论她有什么计划，都算我一个。', 28153),
(151267, 'zhCN', '给我把武器拿来，朋友，剩下的我会处理。', '给我把武器拿来，朋友，剩下的我会处理。', 28153),
(151266, 'zhCN', '我只需要一把武器。', '我只需要一把武器。', 28153),
(151265, 'zhCN', '不……宝石是我的……你不能……抢走它们……', '', 28153),
(151264, 'zhCN', '不！蠢货！', '', 28153),
(151263, 'zhCN', '你们……还没……赢……', '', 28153),
(151262, 'zhCN', '我还会回来的！', '', 28153),
(151261, 'zhCN', '我们的时代来临了……', '', 28153),
(151260, 'zhCN', '你们是在……螳臂当车……', '', 28153),
(151259, 'zhCN', '混乱……不会再被控制……', '', 28153),
(151258, 'zhCN', '元素们……是无法阻挡的……', '', 28153),
(151257, 'zhCN', '你们会看到海洋沸腾，天空崩裂，山峦迭起，而我们即将回归！', '', 28153),
(151256, 'zhCN', '元素的黎明到来了！', '', 28153),
(151255, 'zhCN', '你们时日无多了，凡人。', '', 28153),
(151254, 'zhCN', '有了这些宝石，我们最终将消灭你们。', '', 28153),
(151253, 'zhCN', '元素将再次统治一切！', '', 28153),
(151252, 'zhCN', '金矿会强化我们的力量！', '', 28153),
(151251, 'zhCN', '你们的世界将再次落在我们手上！', '', 28153),
(151250, 'zhCN', '你们竟敢在我的地盘上对抗我？', '', 28153),
(151249, 'zhCN', '我就看看。手拿不下了！', '', 28153),
(151248, 'zhCN', '送我去奥格瑞玛。', '送我去奥格瑞玛。', 28153),
(151247, 'zhCN', '', '$n，很高兴见到你。我现在开始就待在这里了，就守在卡格瓦的身边。\n\n我的父母一直告诉我关于青蛙之神的各种传说。能够守护他不被鲜血巨魔所伤，这是我的荣幸。', 28153),
(151246, 'zhCN', '这样就可以了。谢谢你！', '那应该足够了，谢谢！', 28153),
(151245, 'zhCN', '勇士，给我找点炮弹，炮击可不能停！', '勇士，给我找点炮弹，炮击可不能停！', 28153),
(151244, 'zhCN', '', '拉德诺。诺德拉？德诺拉。德拉诺。<叹气>。我还是说我是从外域来的好了。', 28153),
(151243, 'zhCN', '', '你可以管我叫未受污染的兽人，但我更喜欢“有机兽人”这个称呼。', 28153),
(151242, 'zhCN', '', '有一次我把头发染绿了，地狱咆哮酋长一看，不太高兴。', 28153),
(151241, 'zhCN', '', '别再扯什么“时间与波浪，变化无常”了……啊！我只想砸东西！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151240, 'zhCN', '', '碎手部族都是传奇战士，但千万别让他们给你揉背。相信我……<痛苦呻吟>', 28153),
(151239, 'zhCN', '', '艾泽拉斯有好多的条条框框。你可以砍谁，不能砍谁……可以揍谁，不能揍谁……你们就不能随便点吗！', 28153),
(151238, 'zhCN', '', '喂……你就是那个抛弃霜火岭的要塞，搞得现在杂草丛生的家伙吧？', 28153),
(151237, 'zhCN', '', '随便你待多久，但要记住。打碎了就得买下来，伙计！', 28153),
(151236, 'zhCN', '', '还想接着来的话，我得先问问你……你的疼痛阈值是多少？', 28153),
(151235, 'zhCN', '', '我喜欢有你陪伴不等于说我不想揍你。', 28153),
(151234, 'zhCN', '', '刚才有个血环萨满想勾引我，至少我是这么觉得的。如果他不是想用眨眼来暗送秋波，那他的那只眼睛就瞎得太不值了。', 28153),
(151233, 'zhCN', '', '上一个想跟我搭讪的人终于明白了“打”和“搧”是什么意思。', 28153),
(151232, 'zhCN', '', '有个绿皮兽人给了我一颗情人糖，上面写着“你是我的邪能”。我说：“恶魔之血这种玩意你还是自己留着吧。”然后给了他一锤。', 28153),
(151231, 'zhCN', '', '萨鲁法尔是不是单身？我好喜欢他那种成熟男人的味道……', 28153),
(151230, 'zhCN', '', '你不需要黑暗之门就来到了我的心里。', 28153),
(151229, 'zhCN', '', '我……很抱歉。', 28153),
(151228, 'zhCN', '', '真可悲！在玛格汉兽人面前倒下吧！', 28153),
(151227, 'zhCN', '还得我亲自出马……', '还得我亲自出马……', 28153),
(151226, 'zhCN', '应该争取……升职的……', '好像被烧死的……是我……', 28153),
(151225, 'zhCN', '把我和我的钱……埋在一起……', '只有死亡和纳税……不可避免……', 28153),
(151224, 'zhCN', '真是……疼啊……', '你会付出……代价的……', 28153),
(151223, 'zhCN', '这……不值……', '这……不值……', 28153),
(151222, 'zhCN', '我要我的……工伤保险……', '真是……不划算……', 28153),
(151221, 'zhCN', '', '我很感激。', 28153),
(151220, 'zhCN', '', '我感谢你。', 28153),
(151219, 'zhCN', '大酋长允许我们造成连带损伤。燃烧吧，宝贝儿！', '大酋长允许我们造成连带损伤。燃烧吧，宝贝儿！', 28153),
(151218, 'zhCN', '伤及无辜也不是事儿！烧吧，宝贝儿！', '有人出钱买你的人头……所以我来收账了！', 28153),
(151217, 'zhCN', '', '我欠你一个人情。', 28153),
(151216, 'zhCN', '', '你必将死在我手下！', 28153),
(151215, 'zhCN', '你别想……妨碍她……', '你别想……妨碍她……', 28153),
(151214, 'zhCN', '你帮错了地方，伙计。', '你犯了一个大错！', 28153),
(151213, 'zhCN', '', '以德拉诺双月之名！', 28153),
(151212, 'zhCN', '有好玩儿的了！', '宝贝儿，我最喜欢烧东西了！', 28153),
(151211, 'zhCN', '为了部落……顺便赚钱！', '为了部落！', 28153),
(151210, 'zhCN', '', '这是我应该做的。', 28153),
(151209, 'zhCN', '', '这种事不值一提。', 28153),
(151208, 'zhCN', '', '我的荣幸。', 28153),
(151207, 'zhCN', '', '不。', 28153),
(151206, 'zhCN', '', '我说了不行！', 28153),
(151205, 'zhCN', '', '绝不！', 28153),
(151204, 'zhCN', '', '就是这样。', 28153),
(151203, 'zhCN', '', '对。', 28153),
(151202, 'zhCN', '', '是啊。', 28153),
(151201, 'zhCN', '', '我是部族之耻！', 28153),
(151200, 'zhCN', '', '给我些时间回复法力值。', 28153),
(151199, 'zhCN', '', '需要法力值！', 28153),
(151198, 'zhCN', '', '祝你死得光荣。', 28153),
(151197, 'zhCN', '', '不想再跟你聊了。', 28153),
(151196, 'zhCN', '', '你可以走了。', 28153),
(151195, 'zhCN', '', '带着荣耀前进吧。', 28153),
(151194, 'zhCN', '', '有话就说。', 28153),
(151193, 'zhCN', '', '幸会。', 28153),
(151192, 'zhCN', '', 'Lok-tar！', 28153),
(151191, 'zhCN', '', 'Throm-ka！', 28153),
(151190, 'zhCN', '', '拜托！求求你了！', 28153),
(151189, 'zhCN', '', '可怜可怜这个兽人吧！', 28153),
(151188, 'zhCN', '', '苦工也需要爱！', 28153),
(151187, 'zhCN', '', '任务完成得不错。', 28153),
(151186, 'zhCN', '', '干得还不错。', 28153),
(151185, 'zhCN', '', '<哼。>我祝贺你。', 28153),
(151184, 'zhCN', '我们走吧，小气鬼们，这些防御设施可不会自己掏钱！', '', 28153),
(151183, 'zhCN', '', '碾碎这个敌人！', 28153),
