(151044, 'zhCN', '为什么我要……让我对付他们！', '', 28153),
(151043, 'zhCN', '我没看到……这个结局……', '真是……犀利呀……', 28153),
(151042, 'zhCN', '别让那帮欠债不还的家伙来我这儿赌，伙计！', '', 28153),
(151041, 'zhCN', '来吧，我准备好赢钱了！', '', 28153),
(151040, 'zhCN', '我们冲进去之前最好先研究一下，看看能不能发现这些巨魔在打什么算盘，还有怎么阻止他们。', '', 28153),
(151039, 'zhCN', '直觉告诉我，在神殿的深处还会有更多麻烦。', '', 28153),
(151038, 'zhCN', '你把那玩意解决掉了，干得不错。', '', 28153),
(151037, 'zhCN', '当然，被这力量吸引来的可不只有我们。', '', 28153),
(151036, 'zhCN', '啊，就是这儿。我从骨子里都能感觉到这些圣物里的力量。', '', 28153),
(151034, 'zhCN', '', '嘿，这边！我朋友把我留在这里等死。能救救我吗？', 28153),
(151031, 'zhCN', '', '嗯……太迷人了……', 28153),
(151030, 'zhCN', '你得学会自己做饭！永远别相信瘦不拉几的厨子！', '', 28153),
(151029, 'zhCN', '洛阿神灵……在召唤我……', '算你走运……', 28153),
(151028, 'zhCN', '部落……永存……', '部落……会胜利的……', 28153),
(151027, 'zhCN', '邦桑迪，我来了……', '邦桑迪，我来了……', 28153),
(151026, 'zhCN', '蠢货！这里供奉的神灵已经没有信众了，你居然要为他送死？！杀了他！', '', 28153),
(151025, 'zhCN', '邦桑迪……我来了……', '我看到了……彼界……', 28153),
(151024, 'zhCN', '坏家伙们朝你过来了！', '坏家伙来找你了！', 28153),
(151023, 'zhCN', '哦，是的。大酋长的命令，不留活口。', '哦，是的。大酋长的命令，不留活口。', 28153),
(151022, 'zhCN', '待着别动！', '你是躲不开的，朋友！', 28153),
(151021, 'zhCN', '瞧瞧这儿都有谁？几个人类，软弱无力，坐等宰割？', '瞧瞧这儿都有谁？几个人类，软弱无力，坐等宰割？', 28153),
(151020, 'zhCN', '拉兹敦克说你不属于这里，孩子。', '', 28153),
(151019, 'zhCN', '拉兹敦克向你问好。', '', 28153),
(151018, 'zhCN', '啊！快啊，我好饿啊！', '', 28153),
(151017, 'zhCN', '我的兄弟姐妹曾经作为森林的眷属照看这片土地。那个年代已经过去很久了。\n\n我们中有些人还没忘记那条道路。\n\n灰树林是我们其中一个庇护所。让我们可以从那个缓慢腐蚀整个赤红森林中得以喘息。\n\n随着感染在阴影中蔓延，它的时代也逐渐远去。现在我看着它的消逝，只能回忆起它曾经繁茂的样子。', '', 28153),
(151016, 'zhCN', '神灵指引我的利刃！', '我会送你去见邦桑迪！', 28153),
(151015, 'zhCN', '为了部落！', '为了部落！', 28153),
(151014, 'zhCN', '这片森林出了什么事吗？', '这片森林出了什么事吗？', 28153),
(151013, 'zhCN', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t 戈霍恩会召唤|cFFFF0404|Hspell:267509|h[千喉之灾]|h|r 来支援他！', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t 戈霍恩会召唤|cFFFF0404|Hspell:267509|h[千喉之灾]|h|r 来支援他！', 28153),
(151011, 'zhCN', '', '尽管我还没有完全恢复力量，但诅咒已经解除，我能够回来了。', 28153),
(151010, 'zhCN', '', '衷心地感谢你们，英雄。', 28153),
(151009, 'zhCN', '等等，这些入侵者又是谁？！他们正在腐化塞塔里斯！', '', 28153),
(151008, 'zhCN', '带我去战场。', '带我去战场。', 28153),
(151007, 'zhCN', '她的圣地应该就在前面。', '', 28153),
(151006, 'zhCN', '要不是她，世界早就陷入一片混沌了。', '', 28153),
(151005, 'zhCN', '塞塔里斯牺牲自己阻止米斯拉克斯时，我就在旁边。', '', 28153),
(151003, 'zhCN', '我在这里都能听到赤红森林那嗜血般的低吟。想不到腐化可以传到这么远的地方来。', '', 28153),
(151002, 'zhCN', '你每具尸体都要摸一遍吗？塞塔里斯还等着我们呢！', '', 28153),
(151001, 'zhCN', '看来，你确实战力超群。', '', 28153),
(151000, 'zhCN', '现在抓紧时间。我感到一股不断增长的黑暗力量在掌控神庙。', '', 28153),
(150999, 'zhCN', '你清除了威胁，谢谢你。', '', 28153),
(150998, 'zhCN', '她为了阻止米斯拉克斯牺牲了自己……然而随着她的死去，沃顿丛林风化成了沙漠。', '', 28153),
(150997, 'zhCN', '这座神庙是塞塔里斯的安息之所，他是一位强大的神灵，在很久以前保护了我的族人免于毁灭。', '', 28153),
(150996, 'zhCN', '', '耶！打得好！', 28153),
(150995, 'zhCN', '', '十枚金币押那个大块头！', 28153),
(150993, 'zhCN', '她重生的日子早已到来，然而恐怕有什么东西，正在阻止她归来。', '', 28153),
(150990, 'zhCN', '你正在离开指定区域，即将离开载具。', '你正在离开指定区域，即将离开载具。', 28153),
(150989, 'zhCN', '终于能暂时歇一口气了，希望我们有足够的时间重整旗鼓。', '', 28153),
(150988, 'zhCN', '快！我们的水手需要帮助！他们受伤了，部落冲进来了！', '', 28153),
(150987, 'zhCN', '愿海潮眷顾你。', '', 28153),
(150986, 'zhCN', '新鲜的卷心菜！', '', 28153),
(150985, 'zhCN', '愿你的航向永不偏移。', '', 28153),
(150984, 'zhCN', '一帆风顺，朋友。', '', 28153),
(150983, 'zhCN', '你好。', '', 28153),
(150982, 'zhCN', '你想要什么？', '', 28153),
(150981, 'zhCN', '幸会。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150980, 'zhCN', '暴揍时间到！', '', 28153),
(150979, 'zhCN', '为了部落！', '为了部落！', 28153),
(150978, 'zhCN', '部落势不可挡！', '部落势不可挡！', 28153),
(150977, 'zhCN', '我们是利矛之刃……', '我们是利矛之刃……', 28153),
(150976, 'zhCN', '', 'Ugalazul bwrxil\' qu rax。', 28153),
(150975, 'zhCN', '被你们这种家伙……打败了？', '被你们这种家伙……打败了？', 28153),
(150974, 'zhCN', '部落……必胜……', '我们会夺取……这片土地……', 28153),
(150973, 'zhCN', '我们是锋利的……战矛……', '我死得……光荣……', 28153),
(150972, 'zhCN', '我们是不可……阻挡的……', '没用的……废物……', 28153),
(150971, 'zhCN', '', '深渊会……吞噬这片大陆！', 28153),
(150970, 'zhCN', '', '不……我辜负了她！', 28153),
(150969, 'zhCN', '', '我诅咒你们！', 28153),
(150968, 'zhCN', '', '大海……收下我的灵魂！', 28153),
(150967, 'zhCN', '', '为了……我们的女王!', 28153),
(150966, 'zhCN', '', '它……从深海升起……', 28153),
(150965, 'zhCN', '', '我们的女王必胜……', 28153),
(150964, 'zhCN', '哦！我现在就回去。请别举报我！', '哦！我现在就回去。请别举报我！', 28153),
(150963, 'zhCN', '你将是一个旗鼓相当的对手。', '你将是一个旗鼓相当的对手。', 28153),
(150962, 'zhCN', '别再别人的地盘上乱晃！', '别再别人的地盘上乱晃！', 28153),
(150961, 'zhCN', '深渊会……吞噬这片大陆！', '', 28153),
(150960, 'zhCN', '不……我辜负了她！', '', 28153),
(150959, 'zhCN', '我诅咒你们！', '', 28153),
(150958, 'zhCN', '大海……收下我的灵魂！', '', 28153),
(150957, 'zhCN', '为了……我们的女王!', '', 28153),
(150956, 'zhCN', '你别想……妨碍她……', '', 28153),
(150955, 'zhCN', '它……从深海升起……', '', 28153),
(150954, 'zhCN', '我们的女王必胜……', '', 28153),
(150953, 'zhCN', '', '让他们没有立足之地，我们的家园就是安全的。你帮贡克完成了复仇，他会给你丰厚的奖励。', 28153),
(150952, 'zhCN', '', '让联盟在赞达拉建立据点将会带来灾难性的后果。尽力做好回收工作，但对联盟不要心慈手软。', 28153),
(150951, 'zhCN', '还得我亲自出马……', '', 28153),
(150950, 'zhCN', '你的死将带给我荣耀！', '今天就是你的末日！', 28153),
(150949, 'zhCN', '把他们都干掉！', 'Lok\'tar！', 28153),
(150948, 'zhCN', '你这个敌人值得一战！', '一个不留！', 28153),
(150947, 'zhCN', '为了……部落……', '为了……部落……', 28153),
(150946, 'zhCN', '啊，真美！这是你今天的分成。', '', 28153),
(150945, 'zhCN', '', '你……竟敢坏了我的好事？你以为有本事对抗我的意志吗？', 28153),
(150944, 'zhCN', '准备战斗。这头野兽是绝佳的猎物。', '', 28153),
(150943, 'zhCN', '它把我们引到了自己的老巢！', '', 28153),
(150942, 'zhCN', '哼……痕迹指向了这条臭烘烘的通道深处。', '', 28153),
(150941, 'zhCN', '珍珠不在这儿。看来艾萨拉的爪牙可能没我想的那么笨。', '', 28153),
(150940, 'zhCN', '你会成为我墙上的战利品！', '', 28153),
(150939, 'zhCN', '向你的女王求和吧，因为你的小命到此为止了。', '', 28153),
(150938, 'zhCN', '入侵者？！我要把你们的躯体扔入黑暗的深渊，让你们永世不得翻身！', '', 28153),
(150937, 'zhCN', '这个神灵太强大了！撤回海里去！我们输了！', '', 28153),
(150936, 'zhCN', '摧毁神庙！打碎每一颗石头，推倒每一座雕像！万物都将臣服于我们的女王！', '', 28153),
(150935, 'zhCN', '管你什么黑暗力量，都逃不过我们的猎杀！', '', 28153),
(150934, 'zhCN', '欢迎，入侵者。你正好能见识什么是真正的力量！', '', 28153),
(150933, 'zhCN', '干得漂亮……但真正的猎物逃进了神殿里。', '', 28153),
(150932, 'zhCN', '', '女王下令要你死！', 28153),
(150931, 'zhCN', '', '为了艾萨拉的荣耀！', 28153),
(150930, 'zhCN', '', '我们的命运即将降临！', 28153),
(150929, 'zhCN', '', '我会获得杀死你的荣耀！', 28153),
(150928, 'zhCN', '', '没人可以反对艾萨拉女王！', 28153),
(150927, 'zhCN', '', '潮汐之戒是我们的！', 28153),
(150926, 'zhCN', '', '你无法理解我们的力量！', 28153),
(150925, 'zhCN', '闭嘴，你不用穿鞋。', '', 28153),
(150924, 'zhCN', '', '要不就一双？我需要新鞋。', 28153),
(150923, 'zhCN', '耐心点，小姐！', '', 28153),
(150922, 'zhCN', '', '他们不会察觉的。没人说要光明正大地冲进营地里去，但是悄悄干掉几个敌人总没啥坏处！', 28153),
(150921, 'zhCN', '女王下令要你死！', '', 28153),
(150920, 'zhCN', '为了艾萨拉的荣耀！', '', 28153),
(150919, 'zhCN', '我们的命运即将降临！', '', 28153),
(150918, 'zhCN', '我会获得杀死你的荣耀！', '', 28153),
(150917, 'zhCN', '没人可以反对艾萨拉女王！', '', 28153),
(150916, 'zhCN', '潮汐之戒是我们的！', '', 28153),
(150914, 'zhCN', '我们必须要待在这里。要是你走了还把我们害死了，那就没人回去报信了。', '', 28153),
(150913, 'zhCN', '你无法理解我们的力量！', '', 28153),
(150912, 'zhCN', '我的卷心菜！', '', 28153),
(150911, 'zhCN', '再去抓一只狮鹫吧。骑上去！', '', 28153),
(150908, 'zhCN', '蛮项的工作有时不怎么光彩，但有钱拿。', '', 28153),
(150907, 'zhCN', '我们有一大宗狮鹫鞍的订单，但毛皮不够了。快干活儿！', '', 28153),
(150906, 'zhCN', '山上的越少，下山的也就越少。干得好！', '', 28153),
(150905, 'zhCN', '冰川上的雪怪数量剧增。快爬上去干点事！', '', 28153),
(150904, 'zhCN', '有了潮汐珍珠的力量，我们的舰队必将势不可挡。', '', 28153),
(150903, 'zhCN', '', '看起来你觉得我是黄金之类的东西做的！', 28153),
(150902, 'zhCN', '对不起，老大……', '', 28153),
(150901, 'zhCN', '', '你这个蠢货！这些东西很贵的！', 28153),
(150900, 'zhCN', '谢谢，英雄们。你们让库尔提拉斯的人民重新看到了希望。', '', 28153),
(150899, 'zhCN', '我能感觉到黑暗的气息正在消退，这座神殿又恢复如初了。', '', 28153),
(150898, 'zhCN', '不要听信它的低语！这个恐魔会扭曲你的灵魂！', '', 28153),
(150897, 'zhCN', '潮汐之母在上！', '', 28153),
(150896, 'zhCN', '当心，英雄们。黑暗中仍然潜伏着我们看不到的邪恶。我们必须将黑暗的影响从这座神殿中清除。', '', 28153),
(150895, 'zhCN', '有些不对劲，黑暗仍在此地滋生。', '', 28153),
(150894, 'zhCN', '主人，你与海潮为敌，结果只能是葬身海底。', '', 28153),
(150893, 'zhCN', '我要把你们的躯体扔入黑暗的深渊，让你们永世不得翻身。', '', 28153),
(150892, 'zhCN', '决不。', '', 28153),
(150891, 'zhCN', '我最后说一次，加入我，或者去死！', '', 28153),
(150890, 'zhCN', '白痴！我们必须回归大海，艾萨拉女王可以给予我们这种力量！', '', 28153),
(150889, 'zhCN', '主人！马上停止这疯狂的行为！不要让库尔提拉斯的舰队堕入黑暗！', '', 28153),
(150888, 'zhCN', '', '看来你有客人来了，斯托颂勋爵。', 28153),
(150887, 'zhCN', '', '言行恭谦一点，把话头交给他……这样他就不会把你扔下金字塔了。', 28153),
(150886, 'zhCN', '库尔提拉斯的舰队就快是你的了，我的女王。', '', 28153),
(150885, 'zhCN', '尘归尘，土归土，海潮归于大海。愿你的灵魂化作宁静的流水。', '', 28153),
(150884, 'zhCN', '英雄们，动作快！在我们失去舰队前阻止他们！', '', 28153),
(150883, 'zhCN', '泰坦圆盘已激活：订立腐化协议', '泰坦圆盘已激活：订立腐化协议', 28153),
(150882, 'zhCN', '泰坦圆盘已激活：正在订立欺诈协议', '泰坦圆盘已激活：正在订立欺诈协议', 28153),
(150881, 'zhCN', '', '仪式一旦完成，库尔提拉斯的舰队就将属于艾萨拉女王！', 28153),
(150880, 'zhCN', '欢迎你，派克修士。你正好能目睹我们胜利的时刻。', '', 28153),
(150879, 'zhCN', '斯托颂勋爵扭曲了这片圣地。我们必须继续前行，破坏他的邪恶计划。', '', 28153),
(150878, 'zhCN', '声音？', '声音？', 28153),
(150877, 'zhCN', '注意脚下，某种黑暗的存在仍在注视着我们。', '', 28153),
(150876, 'zhCN', '英雄们，我们必须将斯托颂的邪恶从神庙中净化干净。', '', 28153),
(150875, 'zhCN', '', '主人！不要抛弃我！不！！', 28153),
(150874, 'zhCN', '', '你真的以为能对抗戈霍恩的力量吗？为你的无知受苦吧！', 28153),
(150873, 'zhCN', '泥地中有声音！', '泥地中有声音！', 28153),
(150872, 'zhCN', '', '我们完了。\n\n莱赞的圣光抛弃了我们。只有少数追随洛阿神王的人还拥有那种力量，但即便是他们也开始动摇了。\n\n我们一生虔诚。现在我们会变成什么样子？', 28153),
(150871, 'zhCN', '是时候升级一下了！', '', 28153),
(150870, 'zhCN', '好吧，我不想公平对决了。', '', 28153),
(150869, 'zhCN', '太棒了！我们的士兵会好好利用那些补给品的。做得好！', '', 28153),
(150868, 'zhCN', '我们的斥候报告说，一艘赞达拉货船被鲜血巨魔的劫掠团抢占了。消灭他们，为我们夺取补给品。', '', 28153),
(150867, 'zhCN', '头抬起来，伙计们，要看起来就像我们有一帮律师撑腰一样！', '', 28153),
(150866, 'zhCN', '耶！自己去找个造型师吧！', '', 28153),
(150865, 'zhCN', '', '$n! 喂，$n！我们有个任务给你！', 28153),
(150864, 'zhCN', '跳！', '跳！', 28153),
(150863, 'zhCN', '你可躲不过邦桑迪的眼睛，小东西。', '', 28153),
(150862, 'zhCN', '你身上有点特别的东西……啊，是恶魔猎手的臭气。', '', 28153),
(150861, 'zhCN', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a你的指挥官正遭到攻击！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a你的指挥官正遭到攻击！', 28153),
(150860, 'zhCN', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a唤勇之路遭到攻击！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a唤勇之路遭到攻击！', 28153),
(150859, 'zhCN', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a纽斯泰德遭到攻击！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a纽斯泰德遭到攻击！', 28153),
(150858, 'zhCN', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a元素法阵正遭受攻击！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a元素法阵正遭受攻击！', 28153),
(150857, 'zhCN', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a远望栖地遭到攻击！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a远望栖地遭到攻击！', 28153),
(150856, 'zhCN', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a诺斯弗德路口遭到攻击！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a诺斯弗德路口遭到攻击！', 28153),
(150855, 'zhCN', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a枯须矿洞遭到攻击！', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a枯须矿洞遭到攻击！', 28153),
(150854, 'zhCN', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a战斧山遭到攻击！', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a战斧山遭到攻击！', 28153),
(150853, 'zhCN', '我们得找到我们的前哨斥候，快速清理掉这些飞来飞去的害虫！', '我们得找到我们的前哨斥候，快速清理掉这些飞来飞去的害虫！', 28153),
(150852, 'zhCN', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a失去唤勇之路！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a失去唤勇之路！', 28153),
(150851, 'zhCN', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a失去纽斯泰德！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a失去纽斯泰德！', 28153),
(150850, 'zhCN', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a元素法阵遭到攻击！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a元素法阵遭到攻击！', 28153),
(150849, 'zhCN', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a失去远望栖地！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a失去远望栖地！', 28153),
(150848, 'zhCN', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a失去诺斯弗德路口！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a失去诺斯弗德路口！', 28153),
(150847, 'zhCN', '你现在可没在梦境里，伙计。', '', 28153),
(150846, 'zhCN', '噢，现在万灵就在你身边了，伙计。', '', 28153),
(150845, 'zhCN', '啊，一位死亡骑士。你应该来看看我的死亡之门！', '', 28153),
(150844, 'zhCN', '接下来就轮到你们的土地了！', '接下来就轮到你们的土地了！', 28153),
(150843, 'zhCN', '你休想阻止沙暴蔓延！', '你休想阻止沙暴！', 28153),
(150842, 'zhCN', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a枯须矿洞遭到攻击！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a枯须矿洞遭到攻击！', 28153),
(150841, 'zhCN', '哈！你的地滚翻也没有躲过去。', '', 28153),
(150840, 'zhCN', '我们会统治万物！', '我们会统治万物！', 28153),
(150839, 'zhCN', '我们会干掉你，就像踩死虫子一样！', '我们会干掉你，就像踩死虫子一样！', 28153),
(150838, 'zhCN', '你之前是想假死吗，伙计？真丢人……', '', 28153),
(150837, 'zhCN', '为了大帝！', '为了大帝！', 28153),
(150836, 'zhCN', '我觉得你追随了错误的圣光，伙计。', '', 28153),
(150835, 'zhCN', '那个闪现术可没闪多远，是吧？', '', 28153),
(150834, 'zhCN', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a失去战斧山！', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a失去战斧山！', 28153),
(150833, 'zhCN', '耶！我是说他们虽然看起来情况不妙，但确实不一样了！', '', 28153),
(150832, 'zhCN', '', '嗯，那个冒险家显然与众不同。', 28153),
(150831, 'zhCN', '我想那是他们其中的一位“英雄”。闻起来就像有人站在火里一样！', '', 28153),
(150830, 'zhCN', '', '那到底是什么气味？！', 28153),
(150829, 'zhCN', '', '瓦多夫不是野猪人，只是另一位“英雄”！', 28153),
(150828, 'zhCN', '哈哈，你那身盔甲也救不了你了，是吧？', '', 28153),
(150827, 'zhCN', '噢，斯塔勒，把我的剑给我！有个野猪人沿路冲过来了！', '', 28153),
(150826, 'zhCN', '噢，你是不是弄丢了你那一小颗闪亮的灵魂石，嗯？', '', 28153),
(150825, 'zhCN', '', '你是对的！这看起来太糟糕了！', 28153),
(150824, 'zhCN', '你看到$n的装备了吗？它看起来可真不赖！', '', 28153),
(150823, 'zhCN', '啊，你来这里是为了和邦桑迪共度美好时光吗？', '', 28153),
(150822, 'zhCN', '哈哈！刚才你死得可真精彩！', '', 28153),
(150821, 'zhCN', '他们看起来穿得有些破……但我觉得他们看起来一直都是那样！', '', 28153),
(150820, 'zhCN', '', '好呀好呀，看看巨蜥拖了什么进来！是$n！', 28153),
(150819, 'zhCN', '', '嗯，那东西掉哪儿去了？在一个穴居人身上？', 28153),
(150818, 'zhCN', '嘿，斯塔勒，检查一下$n的装备！', '', 28153),
(150817, 'zhCN', '就是这样！天，他们闻起来比我想象得还臭！哈！', '', 28153),
(150816, 'zhCN', '', '喂，瓦多夫！这不是和吉安娜一起的那位“著名”的$r吗？', 28153),
(150815, 'zhCN', '', '耶！你好臭啊！哈哈哈！', 28153),
(150814, 'zhCN', '嘿，你！对，就是你，挂着脸的那个$r！', '', 28153),
(150813, 'zhCN', '我见过幻化更炫的马！', '', 28153),
(150812, 'zhCN', '', '噢！$n! 你觉得那个头盔和靴子一起跑了？', 28153),
(150811, 'zhCN', '我希望能知道一些其他的事。', '我希望能知道一些其他的事。', 28153),
(150810, 'zhCN', '', '古老的德鲁斯特。他们对库尔提拉斯的憎恨超过了对自己凡人生命的憎恨。即使是他们的残影也憎恨着我们的存在。\n\n我同情那些召唤了他们的蠢货。', 28153),
(150809, 'zhCN', '复仇亡者？', '复仇亡者？', 28153),
(150808, 'zhCN', '我要消灭你！', '', 28153),
(150807, 'zhCN', '', '这些女巫用的魔法很古老，而且被严重腐蚀。她们奴役扭曲的野生动物，打乱了平衡。她们那些悲惨的造物里寄存着复仇亡者的灵魂。', 28153),
(150806, 'zhCN', '', '愉快的狩猎，甜美的复仇！', 28153),
(150805, 'zhCN', '', '那帮天杀的叛徒还想玷污莱赞神殿。年迈的克兹罗特会教教他们亵渎诸王的洛阿神灵会有什么后果。', 28153),
(150804, 'zhCN', 'Naza bul rexil qalic ul\'。', '', 28153),
(150803, 'zhCN', '森林出了什么事？', '森林出了什么事？', 28153),
(150802, 'zhCN', 'Ca\' lish！', '', 28153),
(150801, 'zhCN', '', '你可以在附近的一个山洞里找到他。祝你好运，$n。', 28153),
(150800, 'zhCN', '', '绿地追猎者的力量被削弱了，但它回去捕猎只是个时间问题。', 28153),
(150799, 'zhCN', 'Ug\' bwafa qilikx za！', '', 28153),
(150798, 'zhCN', '这里的大门永远为你敞开。', '', 28153),
(150797, 'zhCN', '哦，可怜的小东西，你需要老邦桑迪的帮助吗？', '', 28153),
(150796, 'zhCN', '球潮虫毒害了我的孩子们。让他们虚弱不堪，奄奄一息。你救了我，现在用我的力量去拯救他们吧。', '', 28153),
(150795, 'zhCN', 'Hul bala miz rilakich……', '', 28153),
(150794, 'zhCN', '啧啧。没想到你这么快就来我这儿了。', '', 28153),
(150793, 'zhCN', 'Lok\'tar ogar！', 'Lok\'tar ogar！', 28153),
(150792, 'zhCN', '为了部落！', '为了部落！', 28153),
(150791, 'zhCN', '我是你们的主宰！', '', 28153),
(150790, 'zhCN', '部落的士兵们，准备好你们的利刃！今天，我们要进军卡多雷！', '', 28153),
(150789, 'zhCN', '我猜猜……你惹了解决不了的麻烦？', '', 28153),
(150788, 'zhCN', 'Il qul zerakish！', '', 28153),
(150787, 'zhCN', '你现在已经被修好了。去奥格瑞玛找希尔瓦娜斯，开始你史诗级的恶作剧吧。', '', 28153),
(150786, 'zhCN', '我开启了纳兹米尔，但是没有开启祖达萨。请修好我。', '我开启了纳兹米尔，但是没有开启祖达萨。请修好我。', 28153),
(150785, 'zhCN', '你想要什么？', '', 28153),
(150784, 'zhCN', '最好别让他们有什么起色。', '', 28153),
(150783, 'zhCN', '引开那些维克雷斯拥护者的注意力，你会得到重赏。', '', 28153),
(150781, 'zhCN', '召集你最能干的手下，前往杂货码头。你们可以从那儿开始，四处烧杀抢掠，夺取他们的物资，充实我们的金库。', '', 28153),
(150779, 'zhCN', '铅拳船长，我们的金主通知我说，维克雷斯家族现在已经陷入一片混乱。', '', 28153),
(150778, 'zhCN', '你为什么不在自己的岗位上？', '你为什么不在自己的岗位上？', 28153),
(150777, 'zhCN', '我想要选择吉布尔作为我的洛阿神灵。', '我想要选择吉布尔作为我的洛阿神灵。', 28153),
(150776, 'zhCN', '伟大的艾泽拉斯之心！', '', 28153),
(150775, 'zhCN', '<这座神龛是为了赞颂野兽之主吉布尔。>', '<这座神龛是为了赞颂野兽之主吉布尔。>', 28153),
(150773, 'zhCN', '嗯？', '嗯？', 28153),
(150772, 'zhCN', '我是她的代言人，而你，才是她的勇士。现在她需要你为她而战。', '', 28153),
(150771, 'zhCN', '艾泽拉斯在呼唤你，勇士。这是她送给你的礼物，由艾泽拉斯的精华所生。', '', 28153),
(150770, 'zhCN', '自由！我们必须到神殿里面的安全地方！', '自由！我们必须到神殿里面的安全地方！', 28153),
(150769, 'zhCN', '我……我身上发生了什么？', '我……我身上发生了什么？', 28153),
(150768, 'zhCN', '', '戈霍恩！赐予我力量！', 28153),
(150767, 'zhCN', '我在彼界欠你个人情，朋友。', '我在彼界欠你个人情，朋友。', 28153),
(150766, 'zhCN', '', '末日即将到来！', 28153),
(150765, 'zhCN', '', '尖叫着求饶吧！', 28153),
(150764, 'zhCN', '', '你们都将臣服于主人！', 28153),
(150763, 'zhCN', '终于能从那些被诅咒的白骨里解脱出来了！', '终于能从那些被诅咒的白骨里解脱出来了！', 28153),
(150762, 'zhCN', '现在可以让哈兰·斯威提上交财宝了。', '', 28153),
(150761, 'zhCN', '泰坦圆盘已激活：订立混沌协议', '泰坦圆盘已激活：订立混沌协议', 28153),
(150760, 'zhCN', '我会还的！我发誓！', '我会还的！我发誓！', 28153),
(150759, 'zhCN', '哈兰·斯威提完蛋了。接下来我们要征服所有海洋。', '', 28153),
(150758, 'zhCN', '啊啊！！', '啊啊！！', 28153),
(150757, 'zhCN', '这是我光明正大地偷来的！', '我是光明正大地偷来的！', 28153),
(150756, 'zhCN', '哈！我就知道赌你赢准没错！', '', 28153),
(150755, 'zhCN', '散开！', '快散开！', 28153),
(150754, 'zhCN', '啊！危险的陌生人！', '啊！危险的陌生人！', 28153),
(150753, 'zhCN', '我们去干掉几个杂碎，顺便赚点金币吧？', '', 28153),
(150752, 'zhCN', '整座岛现在处于禁闭状态，直到决斗场的活动结束为止。', '', 28153),
(150750, 'zhCN', '干得不赖，但是要让哈兰出来送死可不容易。', '', 28153),
(150749, 'zhCN', '有人邀请的话，事儿就好办了。直接冲进去对三个赫赫有名的船长捅刀子，后果可能有点严重。这事你说了算，有钱人。', '', 28153),
(150748, 'zhCN', '水鼠帮离开酒，就像鱼儿离开水！跟这群动物混熟了，尤朵拉船长就会想见你了。', '', 28153),
(150747, 'zhCN', '黑齿帮喜欢拿打架来练拳头。把他们的牙多敲碎几颗，拉乌尔船长就会想见你了。', '', 28153),
(150746, 'zhCN', '听说那些船长在聚会，我们混进去，把这只多头蛇的脑袋一起砍掉。', '', 28153),
(150745, 'zhCN', '这场战争不会轻易取胜。我们必须奋战到底！', '', 28153),
(150744, 'zhCN', '然后我们就把哈兰·斯威提彻底解决掉。', '', 28153),
(150743, 'zhCN', '我们的计划是，截杀破浪海盗，火烤水鼠帮，打碎黑齿帮，踏平铁潮海盗。', '', 28153),
(150742, 'zhCN', '成功的话，他的舰队就会威胁到我们在海上的利益。', '', 28153),
(150741, 'zhCN', '哈兰想利用铁潮的名号召集其他海盗来当他的手下。', '', 28153),
(150740, 'zhCN', '谢谢你救了我。我能感觉到邦桑迪在神殿里呼唤我，我们走。', '谢谢你救了我。我能感觉到邦桑迪在神殿里呼唤我，我们走。', 28153),
(150739, 'zhCN', '我还以为我会永远都是个丑陋的骷髅。我必须马上回到神殿里！', '我还以为我会永远都是个丑陋的骷髅。我必须马上回到神殿里！', 28153),
(150738, 'zhCN', '回到邦桑迪……神殿……快……', '回到邦桑迪……神殿……快……', 28153),
(150737, 'zhCN', '我残余的意识被他们肮脏的仪式影响变得迟钝……帮帮我，送我到神殿的阶梯那里。', '我残余的意识被他们肮脏的仪式影响变得迟钝……帮帮我，送我到神殿的阶梯那里。', 28153),
(150736, 'zhCN', '谢谢你，伙计！我快不行了，请帮帮我，送我到邦桑迪神殿。', '谢谢你，伙计！我快不行了，请帮帮我，送我到邦桑迪神殿。', 28153),
(150735, 'zhCN', '你手里拿着的是什么，有钱人？要送给老加尼一个亮晶晶的饰品？把它拿近一点……', '', 28153),
(150734, 'zhCN', '我是这里唯一会算数的！所以我负责看管开支，并确保每个人都不会乱伸手。', '', 28153),
(150733, 'zhCN', '苦工是这场战争的中坚力量。', '', 28153),
(150732, 'zhCN', '回来时可别缺胳膊少腿。', '', 28153),
(150731, 'zhCN', '小心那帮鲜血巨魔。', '', 28153),
(150730, 'zhCN', '当心点。你的命对我很重要！', '', 28153),
(150729, 'zhCN', '这是赞达拉的黑暗时代。', '', 28153),
(150728, 'zhCN', '呃。我对鲜血巨魔恨之入骨。', '', 28153),
(150727, 'zhCN', '我们要怎么解决这事？', '', 28153),
(150726, 'zhCN', '呵！部落得到教训了。我要把这个装置带到阿罗姆之台，看看有没有人用得上它。干得漂亮。', '', 28153),
(150719, 'zhCN', '我准备好保护赞达拉了。', '我准备好保护赞达拉了。', 28153),
(150718, 'zhCN', '这边！我们的地面部队在下面等着。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150717, 'zhCN', '', '森林在痛苦地哀嚎。你听得到吗？', 28153),
(150716, 'zhCN', '我们就要回家了！', '我们就要回家了！', 28153),
(150715, 'zhCN', '我想你已经不需要我的帮助了！我们用最快的速度赶了回来！', '', 28153),
(150714, 'zhCN', '我和达利尔在那些山上混了一辈子。我们在那里可以比任何部落的家伙活的都长。', '', 28153),
(150713, 'zhCN', '你想回到祖达萨被干掉，还是待在这里被那些迅猛龙干掉？', '你想回到祖达萨被干掉，还是待在这里被那些迅猛龙干掉？', 28153),
(150712, 'zhCN', '我不会去沃顿的，懂吗？我要回到城里继续过我的生活！', '', 28153),
(150711, 'zhCN', '', '新鲜的海龟，艾玛！你现在得付我的那份钱！', 28153),
(150710, 'zhCN', '你手里拿着的是什么，有钱人？要送给老加尼一个亮晶晶的饰品？把它拿近一点……', '', 28153),
(150709, 'zhCN', '', 'Xul krass qi\' UN skush！', 28153),
(150708, 'zhCN', '', 'Skitsh qi\'uthik illith！', 28153),
(150707, 'zhCN', '', '过程肯定很粗暴，把地板都弄脏了。', 28153),
(150706, 'zhCN', '', '要不要来地下室找我，一起欣赏美妙的“事物”？', 28153),
(150705, 'zhCN', '', '哦亲爱的，看来你们把我家的佣人都“辞退”了。', 28153),
(150704, 'zhCN', '<你看到一个年轻巨魔的身影，正在观看一个葬礼。他看上去惊恐又无辜。>', '<你看到一个年轻巨魔的身影，正在观看一个葬礼。他看上去惊恐又无辜。>', 28153),
(150703, 'zhCN', '离大门远一点！那里不安全。', '离大门远一点！那里不安全。', 28153),
(150702, 'zhCN', '库亚冯朝你咆哮。回到拉尔那里，或是立刻下来！', '库亚冯朝你咆哮。回到拉尔那里，或是立刻下来！', 28153),
(150701, 'zhCN', '', '在痛苦中挣扎吧！', 28153),
(150700, 'zhCN', '', '我要撕裂你的灵魂！', 28153),
(150699, 'zhCN', '', '用那东西把我的头发变成绿色！', 28153),
(150698, 'zhCN', '', '你的尖叫将永世回荡！', 28153),
(150697, 'zhCN', '', '万物都将屈从于我！', 28153),
(150696, 'zhCN', '', '基罗，他们还活着！我们不能把他们丢在这里……', 28153),
(150695, 'zhCN', '快，能拿的都拿上。尸体就留给秃鹫吧。', '', 28153),
(150694, 'zhCN', '你会葬身于这片沙漠。', '', 28153),
(150693, 'zhCN', '入侵者！', '', 28153),
(150692, 'zhCN', '你做好你分内的事，将军，我也会做好我的。', '', 28153),
(150691, 'zhCN', '我们必须加快进展，大王有一批不速之客……这可能是个麻烦。', '', 28153),
(150690, 'zhCN', '', '在托尔达戈有一个守卫，长得简直和你一模一样！', 28153),
(150689, 'zhCN', '', '你能帮我潜入\n伯拉勒斯银行吗？', 28153),
(150688, 'zhCN', '', '你担心过辐射吗？', 28153),
(150687, 'zhCN', '', '你会什么有用的技能吗？比如伪造或者开保险箱之类的？', 28153),
(150686, 'zhCN', '', '风暴散去，我也重拾了自我。谢谢你。', 28153),
(150685, 'zhCN', '', '你们的生命毫无意义，你们的死亡必将被遗忘。', 28153),
(150684, 'zhCN', '', '污染者！', 28153),
(150683, 'zhCN', '', '治疗我，我来关闭它们！', 28153),
(150682, 'zhCN', '', '妖术散去了，但神庙的防御措施也启动了！', 28153),
(150681, 'zhCN', '', '你的痛苦永无止境！', 28153),
(150680, 'zhCN', '我要看着你被烤熟！', '', 28153),
(150679, 'zhCN', '死吧，爬虫！', '', 28153),
(150678, 'zhCN', '电弧冲刺！', '', 28153),
(150677, 'zhCN', '撕裂！', '', 28153),
(150676, 'zhCN', '废物！', '', 28153),
(150675, 'zhCN', '跟玻璃一样脆！', '', 28153),
(150674, 'zhCN', '不是因为我害怕，我只是不想！', '', 28153),
(150673, 'zhCN', '没人能抵挡帝国的力量！', '', 28153),
(150672, 'zhCN', '我当然敢爬了。我可不是娘炮！', '', 28153),
(150671, 'zhCN', '我不用向你证明任何事！', '', 28153),
(150670, 'zhCN', '来嘛亚伯拉罕。我见过有孩子爬过。', '', 28153),
(150669, 'zhCN', '来吧，这又不高。', '', 28153),
(150668, 'zhCN', '我打赌你不敢爬。', '', 28153),
(150667, 'zhCN', '这不好玩！让我从这里下来！', '', 28153),
(150666, 'zhCN', '别乱晃悠了，快帮我下来！', '', 28153),
(150665, 'zhCN', '帮我下来!', '', 28153),
(150664, 'zhCN', '趁你还有机会赶快走吧！', '趁你还有机会赶快走吧！', 28153),
(150663, 'zhCN', '他们不能带走我！', '他们不能带走我！', 28153),
(150662, 'zhCN', '他们可以拿走我的那一份！', '他们可以拿走我的那一份！', 28153),
(150661, 'zhCN', '我们要杀掉所有的铁潮海盗！', '我们要杀掉所有的铁潮海盗！', 28153),
(150660, 'zhCN', '他们不能带走我！', '他们不能带走我！', 28153),
(150659, 'zhCN', '我不为海盗卖命！', '我不为海盗卖命！', 28153),
(150658, 'zhCN', '', '我会打扁你的脑袋！', 28153),
(150657, 'zhCN', '出去玩得开心吗？哈！', '', 28153),
(150656, 'zhCN', '有什么麻烦吗，亚伯拉罕？', '', 28153),
(150655, 'zhCN', '噢，傻瓜！你困在上面了！', '', 28153),
(150654, 'zhCN', '塞塔里斯牺牲自己拯救了我们的世界。如果米斯拉克斯卷土重来，她就白白牺牲了……', '', 28153),
(150653, 'zhCN', '即便是死了，米斯拉克斯残留此处的精华依然强大。如果他再活过来，我们的世界就危险了……', '', 28153),
(150652, 'zhCN', '这里有一股黑暗的力量。我们应该提高警惕……', '', 28153),
(150651, 'zhCN', '', '他们踏上了伟大的旅程。', 28153),
(150650, 'zhCN', '', '是时候让这些小家伙接受考验了，好让他们履行自己的使命。鼓励他们回到万民之厅。', 28153),
(150649, 'zhCN', '很好！这些生物会为猎人提供箭矢，还能做成护甲的内衬。', '', 28153),
(150648, 'zhCN', '将补给运输到这片沼泽可是一件难事，为了维持我们的战斗，你得替我们去打些野兽。', '', 28153),
(150647, 'zhCN', '哼，很好。我想那些滑溜溜的生物应该没给你这样的强者造成什么麻烦吧？', '', 28153),
(150646, 'zhCN', '一群喷刺者？它们的出现真是太及时了，我正好没墨水了！拿上这个卷轴，用它从喷刺者身上吸取宝贵的墨汁。', '', 28153),
(150645, 'zhCN', '', '看来这项技术对我们的军队非常有用。做得好！', 28153),
(150644, 'zhCN', '', '梅卡托克改进了他的蜂式直升机上搭载的技术，需要实地测试它的能力。我们听说附近藏着大量鲜血巨魔。用蜂式直升机把他们找出来，干掉他们！', 28153),
(150643, 'zhCN', '<上来！>', '<上来！>', 28153),
(150642, 'zhCN', '<库亚冯转过头来，打量着你。他发出了一声尖利的叫声来和你打招呼。>\n\n叽！', '', 28153),
(150641, 'zhCN', '', '肮脏的小怪物。', 28153),
(150640, 'zhCN', '', '球潮虫有好几个胃，所以当你挖到第一个后可千万别停。', 28153),
(150639, 'zhCN', '因为不能飞，所以他可能需要花些时间才能回到栖木上去。我相信他会平安无事的。$b$b过会儿再来吧，那时他应该回来了。', '', 28153),
(150638, 'zhCN', '好了，我把它修好了。顺带一说，不用客气。$b$b我发现他看起来有些孤单。也许你可以带他再飞一次！他也肯定需要一些锻炼。', '', 28153),
(150637, 'zhCN', '这风筝是怎么回事？', '这风筝是怎么回事？', 28153),
(150636, 'zhCN', '', '我们得追上她。走吧！', 28153),
(150635, 'zhCN', '', '我们要赶快找到莱克拉！', 28153),
(150634, 'zhCN', '还用你说，肯佐。', '', 28153),
(150633, 'zhCN', '谢谢你，$p。没有你我们无法做成这事儿。拿上你的那一份吧。', '', 28153),
(150632, 'zhCN', '而现在，塔查和欧米……我们要把这地方值钱的东西都搬干净了。', '', 28153),
(150631, 'zhCN', '够了！你们证明了自己的实力，可以死在我手上了！', '', 28153),
(150630, 'zhCN', '死亡也无法切断我们的联系，爱宠们。现在，吃吧，提扎拉……吃吧！', '', 28153),
(150629, 'zhCN', '没人能挡下我的利刃！', '', 28153),
(150628, 'zhCN', '流血吧！', '', 28153),
(150627, 'zhCN', '我要把你大卸八块！', '', 28153),
(150626, 'zhCN', '难道说？啊……终于！\n', '', 28153),
(150625, 'zhCN', '我会超越你的传说！', '', 28153),
(150624, 'zhCN', '别想抢走我的王冠！', '', 28153),
(150623, 'zhCN', '吾乃国王……而你们只是草芥。', '', 28153),
(150622, 'zhCN', '你们要为亵渎我的神殿付出代价！', '', 28153),
(150621, 'zhCN', '又到了狩猎的季节！', '', 28153),
(150620, 'zhCN', '我的毒可没得解！', '', 28153),
(150619, 'zhCN', '元素之灵，听我召唤！', '', 28153),
(150618, 'zhCN', '让你瞧瞧什么是真正的巫术！', '', 28153),
(150617, 'zhCN', '', '苦难降临！', 28153),
(150616, 'zhCN', '', '受死吧！', 28153),
(150615, 'zhCN', '', '尝尝斧子的滋味！', 28153),
(150614, 'zhCN', '', '你要是知道利害的话，最好继续走。', 28153),
(150613, 'zhCN', '', '有人的脑袋要落地了！', 28153),
(150612, 'zhCN', '请别把我……跟这些……白痴……埋在一起……', '', 28153),
(150611, 'zhCN', '', '我的头……也可以拿去……做战利品……', 28153),
(150610, 'zhCN', '', '啊……我的愤怒……是……不朽的……', 28153),
(150609, 'zhCN', '嘘……我在找蝴蝶！', '', 28153),
(150608, 'zhCN', '', '哦！你们的头很适合作为烛台。', 28153),
(150607, 'zhCN', '', '比你更厉害的虫子我也踩死过！', 28153),
(150606, 'zhCN', '巫毒法术取你性命！', '', 28153),
(150605, 'zhCN', '', '没人能抵挡我的怒火！', 28153),
(150603, 'zhCN', '我要拿走宝物！', '我要拿走宝物！', 28153),
(150602, 'zhCN', '让那声音停下！', '让那声音停下！', 28153),
(150601, 'zhCN', '宝物是我的！', '宝物是我的！', 28153),
(150599, 'zhCN', '', '哈！我帮你减轻了肩上的负担！', 28153),
(150598, 'zhCN', '哈！你不该唤醒我的力量。', '', 28153),
(150597, 'zhCN', '', '哈哈，鲜血与白骨！', 28153),
(150596, 'zhCN', '', '你逃不了了！', 28153),
(150595, 'zhCN', '医生来了！', '', 28153),
(150594, 'zhCN', '准备变尸体吧！', '', 28153),
(150593, 'zhCN', '一些蛋开始在北边孵化！', '一些蛋开始在北边孵化！', 28153),
(150592, 'zhCN', '你惊扰了死者！', '', 28153),
(150591, 'zhCN', '沙尘覆盖的蛋开始在东边孵化！', '沙尘覆盖的蛋开始在东边孵化！', 28153),
(150590, 'zhCN', '毒素覆盖的蛋开始在西边孵化！', '毒素覆盖的蛋开始在西边孵化！', 28153),
(150589, 'zhCN', '防止感染！摘除大脑！', '', 28153),
(150588, 'zhCN', '必须净化血肉诅咒！', '', 28153),
(150587, 'zhCN', '尸身……也要好好……保存……', '', 28153),
(150586, 'zhCN', '', '我告诉卡佳继续行动，我们必须要阻止加卡泽，不然就太迟了。', 28153),
(150585, 'zhCN', '清除疫病！', '', 28153),
(150584, 'zhCN', '尘归尘！', '', 28153),
(150583, 'zhCN', '安息吧。', '', 28153),
(150582, 'zhCN', '你的血液里充满诅咒！', '', 28153),
(150581, 'zhCN', '你们的肉体已经感染！', '', 28153),
(150580, 'zhCN', '', '啊……我的头……那是什么东西？', 28153),
(150574, 'zhCN', '我们走着瞧，你这丑八怪！', '', 28153),
(150573, 'zhCN', '风暴觉醒了。', '风暴觉醒了。', 28153),
(150572, 'zhCN', '走开！', '走开！', 28153),
(150571, 'zhCN', '当然，给我看看你给瓦利都弄到了什么。', '当然，给我看看你给瓦利都弄到了什么。', 28153),
(150570, 'zhCN', '为什么你需要钱？', '为什么你需要钱？', 28153),
(150569, 'zhCN', '那个长着獠牙的家伙一直来这里用硬币做交易。$B$B瓦利觉得在沃顿之外的地方，做买卖时硬币一定很重要！$B$B如果瓦利想要离开沃顿，瓦利就需要硬币。', '', 28153),
(150568, 'zhCN', '瓦利知道你有硬币！', '', 28153),
(150567, 'zhCN', '嘿，嗨！没错，就是你！你看起来需要些水！', '', 28153),
(150566, 'zhCN', '', '谢谢你，梅斯。这件事过去以后，你可以考虑担任我们家族的外交官。', 28153),
(150565, 'zhCN', '', '我信赖你。如果有谁敢找你麻烦，我会亲手敲烂他们的脑袋。', 28153),
(150564, 'zhCN', '我应该回到祭坛，得好好检查下这个精华。', '我应该回到祭坛，得好好检查下这个精华。', 28153),
(150563, 'zhCN', '需要修理吗？工具虽然老旧，但在我手里还能派上用途。', '需要修理吗？工具虽然老旧，但在我手里还能派上用途。', 28153),
(150562, 'zhCN', '我想要选择阿昆达作为我的洛阿神灵。', '我想要选择阿昆达作为我的洛阿神灵。', 28153),
(150561, 'zhCN', '<这座神龛是为了赞颂风暴之神阿昆达。>', '<这座神龛是为了赞颂风暴之神阿昆达。>', 28153),
(150560, 'zhCN', '', '你这不孝之女！等我告诉你父亲，一会就有你好瞧的。暂且先让我的仆人陪你们玩玩吧。', 28153),
(150559, 'zhCN', '', '我没有你这种母亲，女巫！', 28153),
(150558, 'zhCN', '', '欢迎回家，女儿。没想到你还带了客人。', 28153),
(150557, 'zhCN', '啊啊啊！！', '啊啊啊！！', 28153),
(150556, 'zhCN', '近距离调查织物。', '近距离调查织物。', 28153),
(150555, 'zhCN', '这台织布机和它的织物似乎浸染了女巫会的魔法。', '这台织布机和它的织物似乎浸染了女巫会的魔法。', 28153),
(150554, 'zhCN', '带上这个瓶子。', '带上这个瓶子。', 28153),
(150553, 'zhCN', '虽然这个瓶子里的东西早就变质了，但是对一个有经验的大厨来说，它仍然很有用。', '虽然这个瓶子里的东西早就变质了，但是对一个有经验的大厨来说，它仍然很有用。', 28153),
(150552, 'zhCN', '啊！发生什么了？！救命！', '', 28153),
(150551, 'zhCN', '摧毁未成熟的种荚。', '摧毁未成熟的种荚。', 28153),
(150550, 'zhCN', '一个充斥着病菌的种荚正处于休眠状态。看来有人正在怀着邪恶的目的培养它。', '一个充斥着病菌的种荚正处于休眠状态。看来有人正在怀着邪恶的目的培养它。', 28153),
(150549, 'zhCN', '带上这张地图。', '带上这张地图。', 28153),
(150548, 'zhCN', '一张老旧的地图，上面标出了当地的狩猎点和附近区域的皮货商人。', '一张老旧的地图，上面标出了当地的狩猎点和附近区域的皮货商人。', 28153),
(150547, 'zhCN', '你确定你要这么做？', '你确定你要这么做？', 28153),
(150546, 'zhCN', '你……你跳进锅里了！你是中了什么邪才会这么做！？我们得重新来过！', '', 28153),
(150545, 'zhCN', '', '路线打通了 ！顶住大门，等待下一波的突破。', 28153),
(150544, 'zhCN', '', '大师，$n会满足你的任何需要。我去罗伊斯顿镇长那儿看看。', 28153),
(150543, 'zhCN', '永远别想活捉我！', '永远别想活捉我！', 28153),
(150542, 'zhCN', '', '你这么说我很高兴，艾什顿大师。', 28153),
(150541, 'zhCN', '审判官，我乐意帮助你和露希尔女士完成任务。', '', 28153),
(150540, 'zhCN', '有意思！这配方真厉害！非常易燃！', '', 28153),
(150539, 'zhCN', '就是说，露希尔女士觉得有用？那我们试试吧！', '', 28153),
(150538, 'zhCN', '', '她发现了当时的一种炼金配方，对敌人有奇效，希望你能让它重现人间。', 28153),
(150537, 'zhCN', '', '露希尔女士重建了灰烬骑士团，利用古书记载的知识跟女巫作战，就像当年跟德鲁斯特的战斗一样。', 28153),
(150536, 'zhCN', '', 'Krax il\' oni OGOG！', 28153),
(150535, 'zhCN', '', 'Ul tala kraza。', 28153),
(150534, 'zhCN', '', 'Bwaxa za\' raga xil！', 28153),
(150533, 'zhCN', '', 'Kryl！', 28153),
(150532, 'zhCN', '我懂了……但为啥是我？', '', 28153),
(150531, 'zhCN', '', 'Bwixki amala zal qulllll……', 28153),
(150530, 'zhCN', '', 'Aglathrax hig\' thrixa。', 28153),
(150529, 'zhCN', '', '艾什顿大师，露希尔·维克雷斯女士派我们来找你。', 28153),
(150528, 'zhCN', '', 'ULL vera skish！！', 28153),
(150527, 'zhCN', '你凭什么来对抗我的力量？', '', 28153),
(150526, 'zhCN', '净化一个！', '', 28153),
(150525, 'zhCN', '清理垃圾！', '', 28153),
(150524, 'zhCN', '海潮……与我背道而驰……', '', 28153),
(150523, 'zhCN', '我很期待能亲手把你淹死！', '', 28153),
(150522, 'zhCN', '我不会再容忍你的傲慢了！', '', 28153),
(150521, 'zhCN', '涌动的水流，听我召唤！崛起吧，消灭这些入侵者！', '', 28153),
(150520, 'zhCN', '你们的到来，污染了这片圣地！', '', 28153),
(150519, 'zhCN', '在水下安眠吧！', '', 28153),
(150518, 'zhCN', '[场景：加卡泽和蛇人大帝柯泰克被蛇人所簇拥，正在密谋攻入金字塔。柯泰克把你从天上射了下来。]', '', 28153),
(150517, 'zhCN', '艾泽拉斯想要我做什么，麦格尼？', '艾泽拉斯想要我做什么，麦格尼？', 28153),
(150516, 'zhCN', '你们不该来海上的！', '', 28153),
(150515, 'zhCN', '请让我……回归大海……', '', 28153),
(150514, 'zhCN', '我要把你们丢进深渊！', '', 28153),
(150513, 'zhCN', '不！', '', 28153),
(150512, 'zhCN', '潮水会卷走你！', '', 28153),
(150511, 'zhCN', '没有力量能打破我们的羁绊。', '', 28153),
(150510, 'zhCN', '', '我的爱人，你与我的结合就是自然之力的化身。', 28153),
(150509, 'zhCN', '', '让风暴净化你！', 28153),
(150508, 'zhCN', '', '吹跑一个！', 28153),
(150507, 'zhCN', '|TInterface\\Icons\\INV_MISC_LESSERESSENCE:20|t%s获得了一个|cFFFF0000|Hcurrency:1559|h风暴精华|h|r！', '|TInterface\\Icons\\INV_MISC_LESSERESSENCE:20|t%s获得了一个|cFFFF0000|Hcurrency:1559|h风暴精华|h|r！', 28153),
(150506, 'zhCN', '', '乌云……散开了……', 28153),
(150505, 'zhCN', '', '狂风会剥开你们的血肉！', 28153),
(150504, 'zhCN', '', '亲爱的！不！', 28153),
(150503, 'zhCN', '没人比他命大。审判官，我去实验室的花园看看。', '', 28153),
(150502, 'zhCN', '', '谁都无法阻挡风暴！', 28153),
(150501, 'zhCN', '', '隼林镇受到了严重打击。希望艾什顿大师还活着。', 28153),
(150500, 'zhCN', '', '普里西拉正在骑马逃跑！骑上战马，去追她！', 28153),
(150499, 'zhCN', '艾什顿大师，我们需要你的帮助。', '艾什顿大师，我们需要你的帮助。', 28153),
(150498, 'zhCN', '真是谢谢你，我现在可以自己上路了。', '真是谢谢你，我现在可以自己上路了。', 28153),
(150497, 'zhCN', '我永远不会忘记的！我要离开这里！', '我永远不会忘记的！我要离开这里！', 28153),
(150496, 'zhCN', '我曾担心我会永远困在这里……这是我表示谢意的礼物！', '我曾担心我会永远困在这里……这是我表示谢意的礼物！', 28153),
(150495, 'zhCN', '谢谢你让我重获自由，也许它能帮到你。', '谢谢你让我重获自由，也许它能帮到你。', 28153),
(150494, 'zhCN', '感谢上天，你救了我！让我做些能帮你的事吧。', '感谢上天，你救了我！让我做些能帮你的事吧。', 28153),
(150493, 'zhCN', '别把我丢在这儿！', '别把我丢在这儿！', 28153),
(150492, 'zhCN', '放我出去！', '放我出去！', 28153),
(150491, 'zhCN', '', '请帮帮我们！如果不阻止高莱克·图尔，他的邪恶会扩散到整个艾泽拉斯。', 28153),
(150490, 'zhCN', '救命！', '救命！', 28153),
(150489, 'zhCN', '快，找到打开牢笼的办法！', '快，找到打开牢笼的办法！', 28153),
(150488, 'zhCN', '放我出去！', '放我出去！', 28153),
(150487, 'zhCN', '请帮帮我！', '请帮帮我！', 28153),
(150486, 'zhCN', '一头细颚龙？那玩意儿在这儿干嘛？', '', 28153),
(150485, 'zhCN', '', '不管他们是谁——我们需要他们的帮助。不能让高莱克·图尔进入我们的世界！', 28153),
(150484, 'zhCN', '', '放松点，艾什顿大师！我们不是敌人！', 28153),
(150483, 'zhCN', '已经太迟了！等等，你们是谁？！', '', 28153),
(150482, 'zhCN', '你们俩看着的确人畜无害。就是说，攻击结束了？', '', 28153),
(150480, 'zhCN', '走开！我可是炼金大师，有炼金药水！', '', 28153),
(150479, 'zhCN', '你们杀死维克雷斯夫人，反而为我打开了通往你们世界的大门。', '', 28153),
(150478, 'zhCN', '目光短浅的凡人，死亡是无法阻止的。', '', 28153),
(150477, 'zhCN', '', '你们逗留得太久了。很好。现在谁也别想走！', 28153),
(150476, 'zhCN', '', '再敢打扰我，我就让你们在折磨中慢慢死去。', 28153),
(150475, 'zhCN', '', '你们呆滞的表情说明，在你们居住的穷乡僻壤里，任何不是用大粪堆出来的“家”都足以让你们感到新奇不已。', 28153),
(150474, 'zhCN', '', '唔，当我没问过好了。', 28153),
(150473, 'zhCN', '', '在你们的故乡，谋杀女主人的仆人难道就是礼貌吗？', 28153),
(150472, 'zhCN', '我准备好了。我们去找其他人吧。', '我准备好了。我们去找其他人吧。', 28153),
(150471, 'zhCN', '我们没有时间去浪费了。你的朋友已经进入了阿图阿曼……', '', 28153),
(150470, 'zhCN', '库亚冯因为消化不良而尖叫，然后跑开了。', '', 28153),
(150469, 'zhCN', '', '小家伙！如果你想要回巢，你最好赶快跑。', 28153),
(150468, 'zhCN', '', '现在，我们要给它上一节示范课。', 28153),
(150467, 'zhCN', '', '你的小家伙对它的翅膀并没有信心。你必须继续向它展现翱翔天空的快乐。', 28153),
(150466, 'zhCN', '', '为什么你还在用腿跑路？！', 28153),
(150465, 'zhCN', '', '你们都活着。很好。正像我所说的——', 28153),
(150464, 'zhCN', '', '谢谢，英雄们。你们击溃了女巫会，还从高莱克·图尔手中解救了我们。我们欠你们一份情。', 28153),
(150463, 'zhCN', '', '瞧，只要有肌肉和利刃，没什么问题解决不了。', 28153),
(150462, 'zhCN', '我们成功了！高莱克·图尔被放逐了。', '', 28153),
(150461, 'zhCN', '即将发生冲撞，库亚冯发出了求救的尖啸！', '即将发生冲撞，库亚冯发出了求救的尖啸！', 28153),
(150460, 'zhCN', '来吧，凡人们。死亡在等待着你们。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150459, 'zhCN', '', '我和斯坦泰德会在这里拦住他们。你们必须终结这一切！', 28153),
(150458, 'zhCN', '', '庄园里的所有恐魔都在向我们扑来！', 28153),
(150457, 'zhCN', '', '绝不能让高莱克·图尔进入我们的世界！', 28153),
(150456, 'zhCN', '风筝开始剧烈的颤动。往回走，找找气流平缓的地方！', '风筝开始剧烈的颤动。往回走，找找气流平缓的地方！', 28153),
(150455, 'zhCN', '|TInterface\\ICONS\\INV_POTION_24:20|t 使用|cFFFF0404|Hspell:266198|h[炼金之火]|h|r摧毁亡触奴隶主的尸体！', '', 28153),
(150454, 'zhCN', '现在，你们的噩梦才刚刚开始。', '', 28153),
(150453, 'zhCN', '维克雷斯夫人仅仅是我力量的载体。你们杀死她，反而为我打开了通往你们世界的大门。', '', 28153),
(150452, 'zhCN', '吸收', '吸收', 28153),
(150451, 'zhCN', '愚蠢的孩子，你有眼无珠。死亡是无法阻止的力量，如影随形。', '', 28153),
(150450, 'zhCN', '', '终于，这场噩梦结束了。', 28153),
(150448, 'zhCN', '去吧，我的朋友。拿走他的帽子就能获得加尼的青睐。但小心别让凶恶的野兽发现你……', '', 28153),
(150446, 'zhCN', '', '你说得对。但人民知道是我的家族犯下了这等可怕罪行，要怎么做才能重新赢得信赖？', 28153),
(150445, 'zhCN', '', '当务之急是终结她的邪恶。', 28153),
(150444, 'zhCN', '', '我母亲向来残酷无情，但我没想到她能干出这种事。', 28153),
(150443, 'zhCN', '你继续吧。去找维克雷斯夫人，算算旧账。', '', 28153),
(150442, 'zhCN', '哼！死鬼。', '', 28153),
(150441, 'zhCN', '得让维克雷斯夫人为她邪恶的巫术付出代价。', '', 28153),
(150440, 'zhCN', '你们帮忙解放了这些灵魂。', '', 28153),
(150439, 'zhCN', '你继续追捕维克雷斯夫人。我来清理房间。', '', 28153),
(150438, 'zhCN', '得知这些邪恶生物不会在夜间徘徊，我也可以睡个安稳觉了。', '', 28153),
(150437, 'zhCN', '在你们解决她仆人的同时，我们会调查周边。狩猎愉快。', '', 28153),
(150436, 'zhCN', '', '英雄们，这里需要你们的力量。我们必须消灭这些邪恶的怪物。', 28153),
(150435, 'zhCN', '看来逃跑是不行了，我们是有备而来的……对吧？', '', 28153),
(150434, 'zhCN', '梅斯！', '', 28153),
(150433, 'zhCN', '', '回来，面对我的利刃！', 28153),
(150432, 'zhCN', '', '如你所愿，女主人。', 28153),
(150431, 'zhCN', '', '姑娘们，好好伺候一下我们的客人。', 28153),
(150430, 'zhCN', '', '看来有不速之客来到了这里。没关系，我相信他们会得到妥善的招待。', 28153),
(150429, 'zhCN', '你还真是让人惊喜连连啊。', '你还真是让人惊喜连连啊。', 28153),
(150428, 'zhCN', '干得好，$r！', '干得好，$p', 28153),
(150427, 'zhCN', '我自由了！', '我自由了！', 28153),
(150426, 'zhCN', '我欠你的！', '我欠你的！', 28153),
(150425, 'zhCN', '非常感谢！', '非常感谢！', 28153),
(150421, 'zhCN', '我会把一部分力量分给你，$p。我的屏障会让那些无信者灰飞烟灭。', '', 28153),
(150420, 'zhCN', '你在害怕吗，老朋友，躲在里面看着自己的子民遭难？出来做个了结吧，柯泰克！', '', 28153),
(150419, 'zhCN', '$p，你应该和我合作。我会找到它的。', '$p，你应该和我合作。我会找到它的。', 28153),
(150418, 'zhCN', '', '这只是场小小的失利！等部队集结完毕，这座可悲的小镇就归我们了！', 28153),
(150417, 'zhCN', '祖尔的背叛所造成的伤害比我想象的还要深。他的背叛几乎覆灭了我的军队。\n\n那些仍然忠于我的人正在我身后的战场上垂死挣扎，抵御着无穷无尽的鲜血巨魔。\n\n我真该听塔兰吉的话。', '', 28153),
(150416, 'zhCN', '我知道有个人知道它在哪儿。', '我知道有个人知道它在哪儿。', 28153),
(150415, 'zhCN', '你知道黄金在哪儿吗？', '你知道黄金在哪儿吗？', 28153),
(150414, 'zhCN', '你找到宝物的话我们可以平分。', '你找到宝物的话我们可以平分。', 28153),
(150413, 'zhCN', '我听说铁潮海盗已经找到它了。', '我听说铁潮海盗已经找到它了。', 28153),
(150412, 'zhCN', '嘿，谁来帮人找宝物啊！', '嘿，谁来帮人找宝物啊！', 28153),
(150411, 'zhCN', '这家伙有个朋友曾听到一个铁潮海盗说，他们知道宝藏在哪里。', '这家伙有个朋友曾听到一个铁潮海盗说，他们知道宝藏在哪里。', 28153),
(150410, 'zhCN', '也许，这些关于金子的传言都是假的。', '也许，这些关于金子的传言都是假的。', 28153),
(150409, 'zhCN', '我们要赶在铁潮的人袭击这里之前找到宝藏。', '我们要赶在铁潮的人袭击这里之前找到宝藏。', 28153),
(150408, 'zhCN', '', '也许是有人把那猫给吃了。', 28153),
(150407, 'zhCN', '飞回家吧，自豪的拉克加尼，告诉你的父亲是谁给了你自由。', '', 28153),
(150406, 'zhCN', '', '我会集合一些船员，然后让其他人乘坐附近的小船。祝你玩得开心，$n！', 28153),
(150405, 'zhCN', '快！在德鲁斯特之王复活它们之前烧掉它们！', '', 28153),
(150404, 'zhCN', '快！烧掉它！', '', 28153),
(150403, 'zhCN', '我们这里需要帮助！', '', 28153),
(150402, 'zhCN', '$n! 我们被压制住了！', '', 28153),
(150401, 'zhCN', '臣服于无垠的黑暗吧！', '', 28153),
(150400, 'zhCN', '起来吧！', '', 28153),
(150399, 'zhCN', '没人能够与我抗衡！', '', 28153),
(150398, 'zhCN', '你们一无是处！', '', 28153),
(150397, 'zhCN', '生灵俱灭。', '', 28153),
(150396, 'zhCN', '死亡……困不住我……', '', 28153),
(150395, 'zhCN', '死亡会吞噬一切！', '', 28153),
(150394, 'zhCN', '没人能逃过我的复仇！', '', 28153),
(150393, 'zhCN', '都来厨房！', '', 28153),
(150392, 'zhCN', '暴捶！', '', 28153),
(150391, 'zhCN', '今晚的菜单会多加几道菜……', '', 28153),
(150390, 'zhCN', '真是……甜美的……痛楚……', '', 28153),
(150388, 'zhCN', '', '狐人会支援你的， $p。\n\n把有问题的无信者送到我这里来，我会对付他们。乐意之至。', 28153),
(150387, 'zhCN', '美味多汁！', '', 28153),
(150386, 'zhCN', '新鲜的肉！', '', 28153),
(150385, 'zhCN', '我流口水了！', '', 28153),
(150384, 'zhCN', '晚餐时间！', '', 28153),
(150383, 'zhCN', '找到宝物的可以拿三倍奖金！', '', 28153),
(150382, 'zhCN', '你想要发财吗？给我去找宝物！', '', 28153),
(150381, 'zhCN', '莫克希，让这帮懒鬼干活！', '', 28153),
(150380, 'zhCN', '肮脏的铁潮海盗，你们永远得不到宝物！', '', 28153),
(150379, 'zhCN', '杀了那个戴海盗帽的家伙！对，就是那个！', '', 28153),
(150378, 'zhCN', '石头下面也得检查！所有地方都要检查！', '', 28153),
(150377, 'zhCN', '清除这里的铁潮海盗！', '', 28153),
(150376, 'zhCN', '<哞哞>', '', 28153),
(150375, 'zhCN', '', '<哞哞>', 28153),
(150374, 'zhCN', '', '我很抱歉……', 28153),
(150373, 'zhCN', '', '我是坚韧主母，无尽研究的使徒。简称：纯净圣母。', 28153),
(150372, 'zhCN', '', '无论你之前在这里做什么，到此为止了!', 28153),
(150371, 'zhCN', '', '钱在哪儿？', 28153),
(150370, 'zhCN', '', '我知道你在这儿藏了东西！', 28153),
(150369, 'zhCN', '', '你们所有人都将在庭院休息。', 28153),
(150368, 'zhCN', '', '你并没有我想得那么难对付。', 28153),
(150367, 'zhCN', '', '你要戴着这些锁链，直到抵达船坞！', 28153),
(150366, 'zhCN', '你好啊，有钱人。你为拾荒者圣地带来什么又坚固又结实的东西了吗？', '', 28153),
(150365, 'zhCN', '给他们吧，我怕你没命花！', '给他们吧，我怕你没命花！', 28153),
(150364, 'zhCN', '我不会丢下宝物的。它在这儿！', '我不会丢下宝物的。它在这儿！', 28153),
(150363, 'zhCN', '铁潮海盗来了！我们得赶快离开这里！', '铁潮海盗来了！我们得赶快离开这里！', 28153),
(150362, 'zhCN', '你好啊，有钱人。你为拾荒者圣地带来什么又闪亮又光滑的东西了吗？', '', 28153),
(150361, 'zhCN', '我们到了。天空如此晴朗，非常适合探险。', '', 28153),
(150360, 'zhCN', '这不像普通的地震！艾泽里特正从附近不断涌出。', '', 28153),
(150359, 'zhCN', '那玩意启动了，应该可以看到所有的艾泽里特了。', '', 28153),
(150358, 'zhCN', '当心，有艘库尔提拉斯的船靠岸了。', '', 28153),
(150357, 'zhCN', '不公平，你拿到了最后一个！', '不公平，你拿到了最后一个！', 28153),
(150356, 'zhCN', '嘿，那是我的！', '嘿，那是我的！', 28153),
(150355, 'zhCN', '搜一搜他的口袋！', '搜一搜他的口袋！', 28153),
(150354, 'zhCN', '拿上钥匙！', '拿上钥匙！', 28153),
(150353, 'zhCN', '傻瓜！拉兹加基这是送你上西天！', '', 28153),
(150352, 'zhCN', '', '这正是我心中所想，$n。你能去验证一下这个想法吗？', 28153),
(150351, 'zhCN', '有意思。这些小精灵只会听从玛法里奥的召唤。但如果有更多的生命哀求它们的帮助呢？', '', 28153),
(150350, 'zhCN', '', '我们没法消灭这些小精灵……它们数量太多了。但我们也许能声东击西。', 28153),
(150349, 'zhCN', '没人能从汤戈身上偷东西还不被抓到！', '', 28153),
(150348, 'zhCN', '', '我派去玛法里奥那里的侦察队低估了那些小精灵。他们为此付出了代价。', 28153),
(150347, 'zhCN', '一道小精灵之墙？我们的黑暗游侠和攻城车对付它们简直绰绰有余，女王大人。', '', 28153),
(150346, 'zhCN', '我不会……被击垮……', '', 28153),
(150345, 'zhCN', '又一条将被无信者宰杀的翼手龙！', '', 28153),
(150344, 'zhCN', '', '很高兴见到你！来吧，让你疲惫的脑袋歇一歇。', 28153),
(150343, 'zhCN', '', '需要什么就告诉我！', 28153),
(150342, 'zhCN', '', '欢迎来到我的酒馆！来吧，喝一杯。', 28153),
(150341, 'zhCN', '', '你还好吗，甜心？请进，就像自己家一样。', 28153),
(150340, 'zhCN', '', '你看起来需要休息！请坐下吃点东西吧！', 28153),
(150339, 'zhCN', '你好啊，有钱人。你为拾荒者圣地带来什么又带电又锋利的东西了吗？', '', 28153),
(150338, 'zhCN', '所有这些艾泽里特都是我的！', '所有这些艾泽里特都是我的！', 28153),
(150337, 'zhCN', '', '疼的话就吱一声……', 28153),
(150336, 'zhCN', '', '哇哦！你的血流得挺欢的！', 28153),
(150335, 'zhCN', '', '船长！侦测到附近有敌情。我可爱的刀子可以见血了！', 28153),
(150334, 'zhCN', '', '把火搞定……把爆炸也搞定……哼！把我当牲口呢！', 28153),
(150333, 'zhCN', '', '肯定有用，也肯定会爆炸，就不能两样都有吗！', 28153),
(150332, 'zhCN', '', '船长……不喜欢……这样……', 28153),
(150331, 'zhCN', '', '吃我一刀！', 28153),
(150330, 'zhCN', '', '大惊喜！', 28153),
(150329, 'zhCN', '', '刺刀时间！', 28153),
(150328, 'zhCN', '真有点儿疼！', '', 28153),
(150327, 'zhCN', '哦，蹦跶得挺欢！', '', 28153),
(150326, 'zhCN', '还是你去当鱼饵吧！', '', 28153),
(150325, 'zhCN', '你在看啥？', '', 28153),
(150324, 'zhCN', '喂鱼的……居然是我……', '', 28153),
(150323, 'zhCN', '哼，这岛上的敌人可不一般。看来绕道来这儿还真是赚翻了。', '', 28153),
(150322, 'zhCN', '只配做我的鱼饵！', '', 28153),
(150321, 'zhCN', '剁碎了拿去喂鱼！', '', 28153),
(150320, 'zhCN', '马上就要刮大风了！', '', 28153),
(150319, 'zhCN', '', '快！给我拿个桶！一滴血都别浪费！', 28153),
(150318, 'zhCN', '', '这座岛很有生气嘛，有人，有东西……还有部落。去给我弄点血来！', 28153),
(150317, 'zhCN', '', '好的，船员们，把鲜血……我最爱的鲜血给我带来！你们也可以顺便拿点战利品。', 28153),
(150316, 'zhCN', '', '部落的血……我的最爱！船员们，老规矩，上！', 28153),
(150315, 'zhCN', '', '你好。你身上有多余的血吗？能不能分我点儿……', 28153),
(150314, 'zhCN', '', '那么多血……太浪费了……', 28153),
(150313, 'zhCN', '', '快点干掉他们，我要嗜血！', 28153),
(150312, 'zhCN', '', '该流点血了！', 28153),
(150311, 'zhCN', '', '不留活口！', 28153),
(150310, 'zhCN', '啊！哈哈哈！', '', 28153),
(150309, 'zhCN', '嘿嘿嘿！', '', 28153),
(150308, 'zhCN', '联……盟！游戏时间到了！', '', 28153),
(150307, 'zhCN', '嗨！', '', 28153),
(150306, 'zhCN', '嘿……嘿嘿……', '', 28153),
(150305, 'zhCN', '别动！', '', 28153),
(150304, 'zhCN', '神偷皮特！', '', 28153),
(150303, 'zhCN', '神偷皮特！', '', 28153),
(150302, 'zhCN', '神偷皮特！', '', 28153),
(150301, 'zhCN', '别戳我！', '', 28153),
(150300, 'zhCN', '喂，好痒啊！', '', 28153),
(150299, 'zhCN', '吃我一炮！', '', 28153),
(150298, 'zhCN', '哈！干掉你了！', '', 28153),
(150297, 'zhCN', '大声地读出神秘的文本。', '大声地读出神秘的文本。', 28153),
(150295, 'zhCN', '送我去黄金王座。', '送我去黄金王座。', 28153),
(150294, 'zhCN', '', '$n，在我想出解决小精灵的办法前，不能让那些卡多雷闲着。', 28153),
(150293, 'zhCN', '', '嗯，小精灵散开了？很好，我们的计划要成功了……', 28153),
(150292, 'zhCN', '', '我的歼灭者会把你轰成碎片！你们不过是在苟延残喘！', 28153),
(150291, 'zhCN', '', '助祭，把路障拆掉！', 28153),
(150290, 'zhCN', '', '去吧，我的宠物！把他们撕成碎片！', 28153),
(150289, 'zhCN', '', '勇士们，跟我来。我邀请你们一同见证最终的华丽乐章。', 28153),
(150288, 'zhCN', '', '又或许，你还能有机会跟你儿子再见上一面。\n', 28153),
(150287, 'zhCN', '', '那你就像一名战士一样战死吧，萨鲁法尔大王。这对我而言没有区别。也许我会复活你残破的躯体，让它再次为我而战。', 28153),
(150286, 'zhCN', '', '也许对你来说，荣耀比你人民的死亡更重要。但对我而言，这个部落值得拯救。谁要是不认同，就不配与我们为伍。', 28153),
(150285, 'zhCN', '', '荣耀对死人毫无意义，萨鲁法尔。你尚且有资本蔑视死亡，可我对死亡的滋味是再熟悉不过了。', 28153),
(150284, 'zhCN', '相信大酋长的策略，塞隆。', '', 28153),
(150283, 'zhCN', '虚空精灵……必须惩罚这些背叛者！', '', 28153),
(150282, 'zhCN', '洛丹伦属于被遗忘者！不要退缩！', '', 28153),
(150281, 'zhCN', '他们的攻势很快就要减弱了，坚持住！', '', 28153),
(150280, 'zhCN', '勇士们，联盟已经不行了！他们超过半数的士兵已经倒下。', '', 28153),
(150279, 'zhCN', '哈哈！瞧瞧是谁加入了战斗。很好，希望你能让这场战斗变得更有趣！', '', 28153),
(150278, 'zhCN', '最好让她亲自告诉你。快走吧！', '', 28153),
(150277, 'zhCN', '你觉得你能挡住他们多久？大酋长的战术是什么？', '', 28153),
(150276, 'zhCN', '不，我和洛瑟玛会对付闯入者。我不能让大酋长身边无人守卫。你要寸步不离地呆在她的身边。', '', 28153),
(150275, 'zhCN', '明白了，我会尽快与你会合的。', '', 28153),
(150274, 'zhCN', '我们制造的阻塞点能阻止敌军在城堡侧面的狭窄路口展开阵形。', '', 28153),
(150273, 'zhCN', '没时间了！我们必须争分夺秒，不然就要失去地形优势了！', '', 28153),
(150272, 'zhCN', '好的，凋零者。但……萨鲁法尔去哪了？', '', 28153),
(150271, 'zhCN', '贝恩！把你能找到的所有投石车和药剂师集结起来。立刻把他们派到城堡！', '', 28153),
(150270, 'zhCN', '乐意效劳，凋零者。', '', 28153),
(150269, 'zhCN', '洛瑟玛，你在侧翼指挥游侠部队！把他们布置到屋顶上！', '', 28153),
(150268, 'zhCN', '瘟疫战车，你们来打头阵！在敌人与我方之间制造一片瘟疫带！', '', 28153),
(150267, 'zhCN', '遵命，我的女王。', '', 28153),
(150266, 'zhCN', '', '和洛瑟玛会合，快！不要辜负我的信任，纳萨诺斯！', 28153),
(150265, 'zhCN', '防毒面具！到这儿拿防毒面具！胆子够大的话，就拿上一个背包，开始工作！', '', 28153),
(150264, 'zhCN', '保持你的荣耀，英雄。Lok-narash。', '', 28153),
(150263, 'zhCN', '', '勇士们，把他们杀光！听好了，安度因国王和他的部队不是来这里观光的。他们的目标是消灭我们！不要手下留情，因为他们也不会对你手软！', 28153),
(150262, 'zhCN', '部落的士兵们！你们受伤的兄弟姐妹还躺在战场上，痛苦呻吟！如果我们抛下自己人，这场胜利就毫无荣誉可言！', '', 28153),
(150261, 'zhCN', 'Lok\'tar ogar！', '', 28153),
(150260, 'zhCN', '他们人数众多，但我们比他们更强。因为我们是部落！谁敢威胁我们，我们就把他们碾碎！', '', 28153),
(150259, 'zhCN', '勇士们！大酋长已经下令！拿起武器，和联盟决一死战的时候到了！', '', 28153),
(150258, 'zhCN', '', '那么是时候跟他们做个了断了。萨鲁法尔，集结你的部队，我会准备好艾泽里特机器。', 28153),
(150257, 'zhCN', '是的，大酋长。', '', 28153),
(150256, 'zhCN', '动作要快！别让大酋长久等！', '', 28153),
(150255, 'zhCN', '到我身边，快！我们必须继续推进，不要给部落反应的机会！', '', 28153),
(150254, 'zhCN', '这风力是很强，但我们团结起来，就会更强！坚持住，勇士们！', '', 28153),
(150253, 'zhCN', '别高兴得太早！', '', 28153),
(150252, 'zhCN', '', '动作要快！我的寒冰屏障撑不了多久！', 28153),
(150251, 'zhCN', '英雄！先集中打击增援部队，然后我们才能对付那些萨满祭司！', '', 28153),
(150250, 'zhCN', '大酋长……会……阻止你的……', '', 28153),
(150249, 'zhCN', '雄鹰之魂的烈风会剥离你的血肉！', '', 28153),
(150248, 'zhCN', '', '', 28153),
(150246, 'zhCN', '叽。', '', 28153),
(150245, 'zhCN', '叽叽叽！', '', 28153),
(150244, 'zhCN', '叽！', '', 28153),
(150242, 'zhCN', '这本书上充满了在书页上飞掠的魔法符文。', '这本书上充满了在书页上飞掠的魔法符文。', 28153),
(150241, 'zhCN', '我可以干掉他们吗？你说过我可以的。', '', 28153),
(150240, 'zhCN', '什么！？', '', 28153),
(150239, 'zhCN', '去拿你自己的盒子，你这个贪婪的$r！', '不，箱子是我的！\n\n我来这里找虫子做汤。有些始祖龟说海蟹肉做汤好喝，但我不同意。蟹肉汤根本不值得费力去和一个陌生人做朋友。\n\n而泥虫汤可以建立起持续一生的深厚友谊，我们始祖龟的一生可是很长的。\n\n给我找点泥虫肉块来，我会考虑把箱子给你。', 28153),
(150238, 'zhCN', '这……很痛……', '', 28153),
(150237, 'zhCN', '呀啊！', '', 28153),
(150236, 'zhCN', '你先听我说完再拔出武器……', '', 28153),
(150235, 'zhCN', '', '来人，搜刮一下他的遗物。', 28153),
(150234, 'zhCN', '', '岛上还有很多财宝没登上我的船。动起来，懒鬼！还有，把联盟的战利品也抢过来！', 28153),
(150233, 'zhCN', '', '我看到了联盟，他们还在活蹦乱跳。得解决他们。', 28153),
(150232, 'zhCN', '', '我们得搜刮这座岛，小伙子们，赶紧的！我最讨厌等人了。', 28153),
(150231, 'zhCN', '', '怎么了？', 28153),
(150230, 'zhCN', '', '什么都……不给你……', 28153),
(150229, 'zhCN', '', '我受够了！解决他们！', 28153),
(150228, 'zhCN', '', '我还是喜欢从死人身上拿东西。', 28153),
(150227, 'zhCN', '', '我听说过关于联盟的坏事。我们还是绕开他们吧。', 28153),
(150226, 'zhCN', '', '这样就好多了。', 28153),
(150225, 'zhCN', '', '交给我处理吧。', 28153),
(150224, 'zhCN', '', '你好。', 28153),
(150223, 'zhCN', '', '我……没……说错。', 28153),
(150222, 'zhCN', '', '噢，不，他们来了。', 28153),
(150221, 'zhCN', '或许撤退是明智的。', '', 28153),
(150220, 'zhCN', '你到此为止了。', '', 28153),
(150219, 'zhCN', '给我们让开，联盟。否则我只能将你们碾碎。', '', 28153),
(150218, 'zhCN', '你好。', '', 28153),
(150217, 'zhCN', '库亚冯狼吞虎咽地吃起了食物，弄得碎屑到处都是。', '', 28153),
(150216, 'zhCN', '圣光……我会……回归……', '', 28153),
(150215, 'zhCN', '释放你的怒气吧！', '', 28153),
(150214, 'zhCN', '浪费我的时间！', '', 28153),
(150213, 'zhCN', '', '悠着点。', 28153),
(150212, 'zhCN', '', '给我慢一点。', 28153),
(150211, 'zhCN', '', '你的死期到了。', 28153),
(150210, 'zhCN', '', '灰飞烟灭吧。', 28153),
(150209, 'zhCN', '', '风指引我们来到了这里……但还有联盟。有时我也搞不懂这些元素。', 28153),
(150208, 'zhCN', '', '听好了，联盟。人不犯我，我不犯人。', 28153),
(150207, 'zhCN', '', '这里的元素失去了平衡，看看我们能不能帮帮它们，但不要让联盟过来碍事。', 28153),
(150206, 'zhCN', '', '什么风把你吹来了？', 28153),
(150205, 'zhCN', '', '我的灵魂……将会……回归……', 28153),
(150204, 'zhCN', '', '你这是在挑战我的耐心。', 28153),
(150203, 'zhCN', '', '元素，请协助我们。', 28153),
(150202, 'zhCN', '', '我来帮忙吧。', 28153),
(150201, 'zhCN', '', '圣光照耀着你！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150200, 'zhCN', '', '我可不喜欢杀生。', 28153),
(150199, 'zhCN', '', '小心——敌人来了。还是尽量避开吧。', 28153),
(150198, 'zhCN', '<把|TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t|Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[超壮恐龙食品]|h|r喂给它>', '<把|TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t|Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[超壮恐龙食品]|h|r喂给它>', 28153),
(150197, 'zhCN', '', '圣光向你问好！', 28153),
(150196, 'zhCN', '', '我将回归……圣光……', 28153),
(150195, 'zhCN', '<库亚冯不耐烦地合上了下颚。>\n\n叽。', '', 28153),
(150194, 'zhCN', '', '投降吧！自杀毫无意义！', 28153),
(150193, 'zhCN', '<库亚冯闻了闻你。>\n\n叽。', '', 28153),
(150192, 'zhCN', '你确定要这么做？除了能炫耀之外，它对剧情毫无影响。', '你确定要这么做？除了能炫耀之外，它对剧情毫无影响。', 28153),
(150191, 'zhCN', '敌人实力非凡！', '', 28153),
(150190, 'zhCN', '圣光判你死刑！', '', 28153),
(150189, 'zhCN', '大酋长想要吓跑这些小精灵，是吗？我正好有她需要的东西。\n\n你是想要飞的还是想要炸的？', '', 28153),
(150188, 'zhCN', '此地的圣光十分耀眼，有许多艾泽里特在此沉眠。', '', 28153),
(150187, 'zhCN', '我还在思考这么做的可行性。我们或许会清掉几棵树，或者把一颗树弄得闪闪发光。\n\n看小精灵们从墙里被炸飞，留下一个个破坑，假装那样很有趣。', '我还在思考这么做的可行性。我们或许会清掉几棵树，或者把一颗树弄得闪闪发光。\n\n看小精灵们从墙里被炸飞，留下一个个破坑，假装那样很有趣。', 28153),
(150186, 'zhCN', '让我们飞吧。', '让我们飞吧。', 28153),
(150185, 'zhCN', '我会飞。但引发森林大火可不是我的作风。', '我会飞。但引发森林大火可不是我的作风。', 28153),
(150184, 'zhCN', '愿圣光与你同在。', '', 28153),
(150183, 'zhCN', '打得……不错……', '', 28153),
(150181, 'zhCN', '圣光啊，攻击我的敌人吧！', '', 28153),
(150180, 'zhCN', '为了圣光！', '', 28153),
(150179, 'zhCN', '', '给我悠着点。', 28153),
(150178, 'zhCN', '', '退后。', 28153),
(150177, 'zhCN', '', '了结这一切吧！', 28153),
(150176, 'zhCN', '', '我们胜利了！', 28153),
(150175, 'zhCN', '', '神秘的岛屿，还有隐秘的宝藏，这才是真正的冒险！等等，部落也在这里？', 28153),
(150174, 'zhCN', '', '让我们一同期待前方的冒险吧，只需要把部落解决了就好。', 28153),
(150173, 'zhCN', '', '暗影的居民，你们是赢不了的！圣光的复仇会将你们击溃！', 28153),
(150172, 'zhCN', '', '你好，朋友。', 28153),
(150171, 'zhCN', '', '圣光……会救赎我。', 28153),
(150170, 'zhCN', '', '你不是我们的对手！', 28153),
(150169, 'zhCN', '<库亚冯向你鸣叫问好。>\n\n叽！', '', 28153),
(150168, 'zhCN', '<库亚冯朝你的方向用力地摆头。>', '', 28153),
(150166, 'zhCN', '<库亚冯调皮地向你叽叽叫。>', '', 28153),
(150165, 'zhCN', '', '把他的灵魂喂给虚空！', 28153),
(150164, 'zhCN', '<当你靠近的时候，库亚冯将头歪向了一边。>\n\n叽？', '', 28153),
(150163, 'zhCN', '', '为了虚空！', 28153),
(150162, 'zhCN', '', '就是这里！我们在这里登陆，这是低语的指引！好！哈哈哈，对对对。', 28153),
(150161, 'zhCN', '', '什么？是谁说的？', 28153),
(150160, 'zhCN', '', '哈哈哈哈……虚空，我来了……', 28153),
(150159, 'zhCN', '', '吃吧，我的宠物！', 28153),
(150158, 'zhCN', '', '如此精致的灵魂，献给虚空！', 28153),
(150157, 'zhCN', '感受熵能之力！', '', 28153),
(150156, 'zhCN', '真可悲。', '', 28153),
(150155, 'zhCN', '那帮部落蛮子已经先到了，哼，他们根本不是虚空的对手。', '', 28153),
(150154, 'zhCN', '这是我们的蜡烛！', '这是我们的蜡烛！', 28153),
(150153, 'zhCN', '那就拿命来赌一赌？', '那就拿命来赌一赌？', 28153),
(150152, 'zhCN', '在这穷途末路，怎能轻易认输……', '在这穷途末路，怎能轻易认输……', 28153),
(150151, 'zhCN', '只想回到旅店的火炉！', '只想回到旅店的火炉！', 28153),
(150150, 'zhCN', '虚空，请滋养我！', '', 28153),
(150149, 'zhCN', '经过千辛万苦，杀出一条血路，', '经过千辛万苦，杀出一条血路，', 28153),
(150148, 'zhCN', '这些凶恶之徒，把你逼向绝路，别慌乱要冷静看好地图！', '这些凶恶之徒，把你逼向绝路，别慌乱要冷静看好地图！', 28153),
(150147, 'zhCN', '拥抱虚空吧！', '', 28153),
(150146, 'zhCN', '你犯下错误，你慌不择路，周围全是敌人陷阱满布！', '你犯下错误，你慌不择路，周围全是敌人陷阱满布！', 28153),
(150145, 'zhCN', '你不能拿蜡烛！', '你不能拿蜡烛！', 28153),
(150144, 'zhCN', '你不能拿蜡烛！', '你不能拿蜡烛！', 28153),
(150143, 'zhCN', '你能拥有全部，但有一样不能碰……', '你能拥有全部，但有一样不能碰……', 28153),
(150142, 'zhCN', '放轻脚步，在这地下深处，有世人梦寐以求的财富！', '放轻脚步，在这地下深处，有世人梦寐以求的财富！', 28153),
(150141, 'zhCN', '这里宝藏无数，但危机四伏，也许这就是一条不归路。', '这里宝藏无数，但危机四伏，也许这就是一条不归路。', 28153),
(150140, 'zhCN', '向你问好。', '', 28153),
(150139, 'zhCN', '踏上这漫漫寻宝征途。', '踏上这漫漫寻宝征途。', 28153),
(150138, 'zhCN', '啊……黑暗……拥抱我……', '', 28153),
(150137, 'zhCN', '多么可怜的队伍，马上就要被吞噬了。', '', 28153),
(150136, 'zhCN', '努力挣扎吧。', '', 28153),
(150135, 'zhCN', '你领取任务，在这遥远国度', '你领取任务，在这遥远国度', 28153),
(150134, 'zhCN', '那里有无尽的财宝在等待被发现……', '那里有无尽的财宝在等待被发现……', 28153),
(150133, 'zhCN', '我可以摆胜利的造型了吗？什么，必须要先打败他们？那行吧。', '', 28153),
(150132, 'zhCN', '传说有一片广袤无垠的地下世界……', '传说有一片广袤无垠的地下世界……', 28153),
(150131, 'zhCN', '是！', '是！', 28153),
(150130, 'zhCN', '噢，你看到我一定很激动！那就想像一下被我杀死的感觉吧！', '', 28153),
(150129, 'zhCN', '一艘部落的船！他们意识到我们也在时，会是什么样的脸色？真想看看。', '', 28153),
(150128, 'zhCN', '孩子们，想唱首歌吗？', '孩子们，想唱首歌吗？', 28153),
(150127, 'zhCN', '嗬嗬嗬', '嗬嗬嗬', 28153),
(150126, 'zhCN', '欢迎！', '', 28153),
(150125, 'zhCN', '哈哈！', '哈哈！', 28153),
(150124, 'zhCN', '我在这！', '', 28153),
(150123, 'zhCN', '怎么了？跟不上我吗？', '', 28153),
(150122, 'zhCN', '耶！', '耶！', 28153),
(150121, 'zhCN', '抓住他们！', '抓住他们！', 28153),
(150120, 'zhCN', '呃，今天可真倒霉……', '', 28153),
(150119, 'zhCN', '天呐！', '天呐！', 28153),
(150118, 'zhCN', '我来了！别担心，我会对你放水的。', '', 28153),
(150117, 'zhCN', '部落你好，我是克莱恩，很高兴见到你们。', '', 28153),
(150116, 'zhCN', '', '滚吧，蛆虫！', 28153),
(150115, 'zhCN', '如果你遇到格罗兹托克，不要犹豫，一刀捅进他的黑心吧。', '', 28153),
(150114, 'zhCN', '', '下等杂种！', 28153),
(150113, 'zhCN', '', '你居然把血洒在了我身上！下次请注意！', 28153),
(150112, 'zhCN', '', '哦，你这个联盟……真不幸啊。我们很快就会把你们撵回狗窝去。', 28153),
(150111, 'zhCN', '格罗兹托克遭到了应有的报应。但愿他死得并不安详。', '', 28153),
(150110, 'zhCN', '', '天哪！这可太不淑女了。', 28153),
(150109, 'zhCN', '我会死在这片沙漠里……是我活该。', '', 28153),
(150108, 'zhCN', '', '呵呵。交给我吧。', 28153),
(150107, 'zhCN', '', '哦，是你啊。你好。', 28153),
(150106, 'zhCN', '', '体验实在是……太差了……', 28153),
(150105, 'zhCN', '', '戴上手套！干脏活也要注意形象。', 28153),
(150104, 'zhCN', '', '喂，快来这儿补刀！', 28153),
(150103, 'zhCN', '', '好耶！你们看到了吗？', 28153),
(150102, 'zhCN', '', '快，统统都下船。我们得赶时间！快快快！', 28153),
(150101, 'zhCN', '', '我怎么能杵在这儿？我要去战斗！', 28153),
(150100, 'zhCN', '我们已经拿到了狱长的钥匙，接下来就能释放我们的“财产”，并用它们的能力来支援战争了。', '', 28153),
(150099, 'zhCN', '', '哈哈！精神可嘉！', 28153),
(150098, 'zhCN', '', '太慢了！', 28153),
(150097, 'zhCN', '黑暗女王会十分高兴的。', '', 28153),
(150096, 'zhCN', '', '不……公平！你们太……卑鄙……', 28153),
(150095, 'zhCN', '', '大伙一起进攻！', 28153),
(150094, 'zhCN', '', '你逃不出我的手心！', 28153),
(150093, 'zhCN', '趁现在！消灭这名敌人！', '', 28153),
(150092, 'zhCN', '这是你的宿命。', '', 28153),
(150091, 'zhCN', '去拿走他的钥匙，夺回我们的财产，杀掉任何碍事的家伙。', '', 28153),
(150090, 'zhCN', '时候到了。回想你的训练，让这些联盟杂种知道上层精灵的厉害。', '', 28153),
(150089, 'zhCN', '想办法前往顶楼，在那儿你能找到狱长。', '', 28153),
(150088, 'zhCN', '集中精神，有强敌临近了，还有联盟。', '', 28153),
(150087, 'zhCN', '最近的一起越狱事件已经在监狱下层引起了混乱，而我们可以利用这一点。', '', 28153),
(150086, 'zhCN', '联盟来了。引导好你的能量，我们不能犯错。', '', 28153),
(150085, 'zhCN', '我们的目标就在托尔达戈里面。', '', 28153),
(150084, 'zhCN', '向你问好。', '', 28153),
(150083, 'zhCN', '赶快……撤退……', '', 28153),
(150082, 'zhCN', '按计划行动！进攻！', '', 28153),
(150081, 'zhCN', '击垮他们！跟我上！', '', 28153),
(150080, 'zhCN', '噢，噢，噢，高优先级目标！', '', 28153),
(150079, 'zhCN', '我干掉一个！我干掉一个了！', '', 28153),
(150078, 'zhCN', '部落来了？你们确定吗？我的意思是我有很多易碎设备，而且它们很贵。', '', 28153),
(150077, 'zhCN', '你好！', '', 28153),
(150076, 'zhCN', '大伙儿……我是……对的……', '', 28153),
(150075, 'zhCN', '$n已经完全充能了！', '$n已经完全充能了！', 28153),
(150074, 'zhCN', '$n盈溢着能量！', '$n盈溢着能量！', 28153),
(150073, 'zhCN', '滚开！', '', 28153),
(150072, 'zhCN', '$n的充能等级又提高了……', '$n的充能等级又提高了……', 28153),
(150071, 'zhCN', '呃，我……我……不……不确定该不该这么做！', '', 28153),
(150070, 'zhCN', '$n的充能等级提高了……', '$n的充能等级提高了……', 28153),
(150069, 'zhCN', '', '医疗兵！', 28153),
(150068, 'zhCN', '一团混沌火花冲入了战场！', '一团混沌火花冲入了战场！', 28153),
(150067, 'zhCN', '', '目标已消灭。', 28153),
(150066, 'zhCN', '附近形成了一个能量核心。', '附近形成了一个能量核心。', 28153),
(150065, 'zhCN', '', '部落来了，小伙子们，子弹上膛，射完再抢。', 28153),
(150064, 'zhCN', '', '遇到好事千万不要拒绝。', 28153),
(150063, 'zhCN', '', '正在后撤。', 28153),
(150062, 'zhCN', '你前方的空中形成了一股纯净的能量！', '你前方的空中形成了一股纯净的能量！', 28153),
(150061, 'zhCN', '', '噢……好痛……', 28153),
(150060, 'zhCN', '', '敌人正在移动。', 28153),
(150059, 'zhCN', '', '瞄准头部，攻击他们的弱点！', 28153),
(150058, 'zhCN', '是时候干掉他们了。', '', 28153),
(150057, 'zhCN', '机甲打架，就不要用刀啦。', '', 28153),
(150056, 'zhCN', '他们干掉了我的机械陆行鸟！撤退！', '', 28153),
(150055, 'zhCN', '机械陆行鸟挂了！马上撤离！', '', 28153),
(150054, 'zhCN', '碾碎。', '', 28153),
(150053, 'zhCN', '只有死掉的臭虫才是好臭虫。你们部落也一样。', '', 28153),
(150052, 'zhCN', '历史证明，暴力是解决冲突的最好办法。我们也来为历史增添佐证吧。', '', 28153),
(150051, 'zhCN', '部落来了，听好了：做好本职工作，不然我就毙了你们。排好阵形！', '', 28153),
(150050, 'zhCN', '快来报到！', '', 28153),
(150049, 'zhCN', '小心火焰！', '', 28153),
(150048, 'zhCN', '你不要……让我失望……', '', 28153),
(150047, 'zhCN', '打起精神来，我们有伴了。', '', 28153),
(150046, 'zhCN', '敌人来袭！', '', 28153),
(150044, 'zhCN', '治疗时间。', '', 28153),
(150043, 'zhCN', '快点挖，我的宝物肯定就在附近！', '快点挖，我的宝物肯定就在附近！', 28153),
(150041, 'zhCN', '砰！', '', 28153),
(150040, 'zhCN', '把刀磨利点，我们还有几具尸体需要处理，要神不知鬼不觉。', '', 28153),
(150039, 'zhCN', '你想要啥？', '', 28153),
(150038, 'zhCN', '太慢了！', '', 28153),
(150037, 'zhCN', '哈……你……什么都不是……', '', 28153),
(150036, 'zhCN', '别眨眼，联盟。', '', 28153),
(150035, 'zhCN', '', '我们的人民对塔兰吉所提到的那种改变感到十分害怕。人一害怕，就会做蠢事。', 28153),
(150034, 'zhCN', '', '所有火炮，准备开火！', 28153),
(150033, 'zhCN', '', '我已经玩腻了。就算让你赢，我也得先把伯拉勒斯化为灰烬！', 28153),
(150032, 'zhCN', '', '你胆敢弄伤我的小宝贝儿！？', 28153),
(150031, 'zhCN', '', '下一个目标。', 28153),
(150030, 'zhCN', '', '一切都在计划之中。', 28153),
(150029, 'zhCN', '', '我把路线都计划好了，它既大胆、又高效，这才是好计划该有的样子。听我的吧。', 28153),
(150028, 'zhCN', '', '这身盔甲不错，要是刺儿再多点就好了。', 28153),
(150027, 'zhCN', '', '你阻止不了……计划……', 28153),
(150026, 'zhCN', '', '电击！', 28153),
(150025, 'zhCN', '', '为了库尔提拉斯！', 28153),
(150024, 'zhCN', '', '你根本没做好计划，对吧？', 28153),
(150023, 'zhCN', '回来干正经事了！', '', 28153),
(150022, 'zhCN', '收割时间到！', '', 28153),
(150021, 'zhCN', '嘿！这玩意儿的修理费很贵的！', '', 28153),
(150020, 'zhCN', '', '城门已经拿下！突破城市的防御，反抗者杀无赦！', 28153),
(150019, 'zhCN', '这堆破铜烂铁。', '', 28153),
(150018, 'zhCN', '哈哈哈！Cha-ching！', '', 28153),
(150017, 'zhCN', '这地方看上去棒极了！绿树成荫，财宝遍地……联盟？唉，这下都毁了。', '', 28153),
(150016, 'zhCN', '这蕴藏着巨大的商机。或许还可以把联盟垃圾当废品卖钱！', '', 28153),
(150015, 'zhCN', '', '请允许我演示一下。', 28153),
(150014, 'zhCN', '', '你们的胜利毫无意义，蠢货！没有库尔提拉斯的舰队，你们根本没希望打败我。', 28153),
(150013, 'zhCN', '闻到了吗？是战利品，而且数量庞大。把你们的麻袋准备好！', '', 28153),
(150012, 'zhCN', '怎么了？', '', 28153),
(150011, 'zhCN', '你还没见识过……我的真本事呢……', '', 28153),
(150010, 'zhCN', '', '你成功了！没了巨人，艾什凡的部队一定会被赶出城外。', 28153),
(150009, 'zhCN', '这台宝贝儿机器人就是干这个的！\n', '', 28153),
(150008, 'zhCN', '攻击系统，启动！', '', 28153),
(150007, 'zhCN', '战斗开始！', '', 28153),
(150006, 'zhCN', '呃，感觉我下手有点重了。', '', 28153),
(150005, 'zhCN', '*打呵欠* 我们已经到了吗？但现在是最适合睡觉的时间。', '', 28153),
(150004, 'zhCN', '要能早点结束战斗的话，我就不用干这事了。', '', 28153),
(150003, 'zhCN', '得有人舔舔你的伤口。', '', 28153),
(150002, 'zhCN', '欢迎！', '', 28153),
(150001, 'zhCN', '终于……能休息了……', '', 28153),
(150000, 'zhCN', '休息时间！', '', 28153),
(149999, 'zhCN', '*笑* 跑吧，部落猪。我们会放你一马的！', '', 28153),
(149998, 'zhCN', '', '上西天吧……猎物！', 28153),
(149997, 'zhCN', '', '看来我得找个新目标了！', 28153),
(149996, 'zhCN', '', '啊……空气里有猎物的味道。追猎是杀戮最好的前菜！', 28153),
(149995, 'zhCN', '', '你闻着很有意思……', 28153),
(149994, 'zhCN', '', '啊……鲜血的……香气……', 28153),
(149993, 'zhCN', '', '下一个……就是你！', 28153),
(149992, 'zhCN', '', '瞄准喉咙！', 28153),
(149991, 'zhCN', '干得好，勇士！你的努力让这片土地更安全了。', '', 28153),
(149990, 'zhCN', '捕杀猎物！', '', 28153),
(149989, 'zhCN', '这会让他们见识到赞达拉的力量！', '', 28153),
(149988, 'zhCN', '我能嗅到你的恐惧。', '', 28153),
(149987, 'zhCN', '我真喜欢这种感觉！', '', 28153),
(149986, 'zhCN', '是部落！我们会猎捕他们。让狩猎开始吧！*嚎叫*', '', 28153),
(149985, 'zhCN', '我们的间谍在这片区域发现了一个严重威胁。找出威胁，并干掉它！', '', 28153),
(149984, 'zhCN', '*嗅**嗅* 是部落！我现在要是在上风处就好了……', '', 28153),
(149983, 'zhCN', '', '无所谓。我的火炮会把任何敌人化为灰烬！', 28153),
(149982, 'zhCN', '跟狼群一起行动，不要走散。我闻到了恶心的气味。', '', 28153),
(149981, 'zhCN', '*咆哮*', '', 28153),
(149980, 'zhCN', '你不能让……大狗失望……', '', 28153),
(149979, 'zhCN', '他会为这个异教而感到后悔！莱赞永垂不朽！', '', 28153),
(149978, 'zhCN', '把他们撕成碎片！', '', 28153),
(149977, 'zhCN', '*嚎叫*狼群，攻击！', '', 28153),
(149976, 'zhCN', '', '颅骨我收下了，哈哈哈！', 28153),
(149975, 'zhCN', '', '噢，这座岛屿看上去很有前途。让开让开，我有些巫毒要搞。', 28153),
(149974, 'zhCN', '', '我会治好你的。', 28153),
(149973, 'zhCN', '', '你的头很不错！去世后把它送给我好吗？', 28153),
(149972, 'zhCN', '', '暗矛……永生不死…………', 28153),
(149971, 'zhCN', '', '你中妖术啦！', 28153),
(149970, 'zhCN', '', '厄运降临！', 28153),
(149969, 'zhCN', '', '嘿嘿，让我把你的头颅变小！', 28153),
(149968, 'zhCN', '干掉这家伙。', '', 28153),
(149967, 'zhCN', '看来我赢了。', '', 28153),
(149966, 'zhCN', '这小岛真不错，不知道我们会在这里发现什么。', '', 28153),
(149965, 'zhCN', '你需要什么？', '', 28153),
(149964, 'zhCN', '我需要……躺一下……', '', 28153),
(149963, 'zhCN', '睡吧！', '', 28153),
(149962, 'zhCN', '这些人从哪来的？来这儿干嘛？', '', 28153),
(149961, 'zhCN', '', '哇啊啊啊！', 28153),
(149960, 'zhCN', '', '再流点血！', 28153),
(149959, 'zhCN', '', '再来！我还要打！', 28153),
(149958, 'zhCN', '', '什么团队……战术……呸，杀个痛快！哇啊啊啊！', 28153),
(149957, 'zhCN', '', '是联盟！把他们都杀光！然后把心脏给我带来……', 28153),
(149956, 'zhCN', '', '冲进去，手撕敌人！鲜血四溅！哈哈哈哈！', 28153),
(149955, 'zhCN', '', '怎么了？', 28153),
(149954, 'zhCN', '', '我死得……像一名战士！*吐血*', 28153),
(149953, 'zhCN', '', '剁掉他们的手！', 28153),
(149952, 'zhCN', '想我了吗？', '', 28153),
(149951, 'zhCN', '冻结吧！', '', 28153),
(149950, 'zhCN', '嗯……你好啊。', '', 28153),
(149949, 'zhCN', '干得……漂亮……', '', 28153),
(149948, 'zhCN', '又得一分！ 我现在领先了。', '', 28153),
(149947, 'zhCN', '我迫不及待了！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149946, 'zhCN', '你得先买一张新面孔', '你得先买一张新面孔', 28153),
(149945, 'zhCN', '', '你的目光有所迟疑，$n。\n\n只要你愿意，我允许你询问我的计划。', 28153),
(149944, 'zhCN', '大酋长，敢问我们为什么要夺取泰达希尔？', '大酋长，敢问我们为什么要夺取泰达希尔？', 28153),
(149943, 'zhCN', '良机？', '良机？', 28153),
(149942, 'zhCN', '这还不确定，大酋长。', '这还不确定，大酋长。', 28153),
(149940, 'zhCN', '', '可以确定的是，联盟必然会把达纳苏斯作为把艾泽里特运往东部王国的安全港。安度因会打造强大的新武器，而且他迟早会把这些武器用在我们的国土上。他会先攻击幽暗城和银月城，然后就会把目光投向卡利姆多。\n\n为了部落的未来，我们必须先发制人。\n\n只要占领了达纳苏斯，我们就能控制艾泽里特的流通，以此确保艾泽里特不会被用来对付我们。联盟肯定不敢攻击自己的城市，因为他们担心会伤及平民。\n\n这样一来，我们就能确保数个世代的和平。', 28153),
(149939, 'zhCN', '', '我们的时间并不充裕，但我尊重你们想要了解更多情况的意愿。\n\n<希尔瓦娜斯指着地图上的希利苏斯>。\n\n这已经永远改变了艾泽拉斯的力量平衡。\n\n全世界到处都发现了艾泽里特矿藏，$n。虽然我们仍未得知它全部的潜力，但很显然，这种物质可以产生巨大的破坏力。\n\n二十年后的战争是什么样？一百年后呢？\n\n如果让联盟控制了艾泽里特的流通，部落拿什么来防御边境？', 28153),
(149938, 'zhCN', '', '你想问我什么事吗，$n？', 28153),
(149937, 'zhCN', '无信者在附近圈养了一些野兽。在我看来，这是一个好机会。', '', 28153),
(149936, 'zhCN', '看来部落来了。这下子可就……有意思了 。', '', 28153),
(149935, 'zhCN', '你就是离不开我，是吧？', '', 28153),
(149934, 'zhCN', '把他们干掉，小伙子们！', '', 28153),
(149933, 'zhCN', '你好，美人儿。', '', 28153),
(149932, 'zhCN', '打得好……我们……下次再见……', '', 28153),
(149931, 'zhCN', '哈！我又赢了！', '', 28153),
(149930, 'zhCN', '我的身体已经迫不及待了！', '', 28153),
(149929, 'zhCN', '不过，这些武器会为我们提供极大的优势。', '', 28153),
(149928, 'zhCN', '喜欢我的新翅膀吗？有了这么快的翅膀，没有滑水鱼可以逃出我的掌心！$b$b无毛怪也是如此。$b$b$b$b肮脏的无毛怪。', '', 28153),
(149927, 'zhCN', '赞达拉的滑水鱼很奇怪。很咸，有时候还会顶嘴。', '', 28153),
(149926, 'zhCN', '是部落！终于可以动真格的了。等我先把上衣脱掉！', '', 28153),
(149925, 'zhCN', '库亚冯发出开心的尖叫，一口吞下食物。', '', 28153),
(149924, 'zhCN', '库亚冯嗅了嗅食物，然后凶残地吞了下去。', '', 28153),
(149923, 'zhCN', '库亚冯在空中吞下食物。', '', 28153),
(149922, 'zhCN', '库亚冯扑向面前的食物，一口把它吞了下去。', '', 28153),
(149921, 'zhCN', '世上有甚多既神秘又神圣的秘密，你有你的秘密，我也有我的。', '', 28153),
(149920, 'zhCN', '唧唧？', '', 28153),
(149919, 'zhCN', '叽叽！', '', 28153),
(149918, 'zhCN', '唧唧！', '', 28153),
(149917, 'zhCN', '叽。', '', 28153),
(149916, 'zhCN', '会飞的猢狲？怎么做到的？', '会飞的猢狲？怎么做到的？', 28153),
(149915, 'zhCN', '必须进行战术撤退！', '', 28153),
(149914, 'zhCN', '我来帮忙！', '', 28153),
(149913, 'zhCN', '你好啊，是来观摩绝世高手的吗？', '', 28153),
(149912, 'zhCN', '我们的补给品并不充裕，但我可以分你一点。如果你帮我们，我也许能给你弄些好东西。', '我们的补给品并不充裕，但我可以分你一点。如果你帮我们，我也许能给你弄些好东西。', 28153),
(149911, 'zhCN', '<把|TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t|Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[放养恐龙大餐]|h|r喂给它>', '<把|TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t|Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[放养恐龙大餐]|h|r喂给它>', 28153),
(149910, 'zhCN', '我们的位置最好，宝物就在这里。', '我们的位置最好，宝物就在这里。', 28153),
(149909, 'zhCN', '你还没领教……我的……真本事……', '', 28153),
(149908, 'zhCN', '<库亚冯看着你的手，想要找食物。>\n\n叽？叽。', '', 28153),
(149907, 'zhCN', '自。不。量。力。', '', 28153),
(149906, 'zhCN', '滚远点！肮脏的部落臭虫！', '', 28153),
(149905, 'zhCN', '你马上就会被我的智慧击败！', '', 28153),
(149904, 'zhCN', '部落……无知，毫无想象力和智慧。哼，你们是怎么发现这座岛的？肯定是撞大运而已。', '', 28153),
(149903, 'zhCN', '为了方便你们理解，我会放慢语速。海岛……归我们。你们……离开。够简单了吧？', '', 28153),
(149902, 'zhCN', '部落的野人！只要把艾泽里特全都乖乖奉上，我们就接受你们的投降。希望你们的智力足以理解我的高屋建瓴。', '', 28153),
(149901, 'zhCN', '', '嗯？我认识你吗？', 28153),
(149900, 'zhCN', '', '啊！联盟的乌合之众，穿也穿得这么土气。你们还是快走吧……免得羞愧而死！', 28153),
(149899, 'zhCN', '', '联盟的船就长那样？是刚被海巨人砸过，还是本来就这么丑？', 28153),
(149898, 'zhCN', '这儿真热啊，是因为天气，还是因为我？开个玩笑……当然是因为我！', '', 28153),
(149897, 'zhCN', '烤熟了！', '', 28153),
(149896, 'zhCN', '再加点温度！', '', 28153),
(149895, 'zhCN', '煽风点火！', '', 28153),
(149894, 'zhCN', '我到上层去毁掉他们的火炮，你到峡谷里去放火。然后去他们的兽栏和我碰头。', '', 28153),
(149893, 'zhCN', '', '呃！如果不是为了干掉你，我一眼都不想看你！', 28153),
(149892, 'zhCN', '是用这片大海还是我的烈焰来洗刷你的臭味？自己选吧，联盟！', '', 28153),
(149891, 'zhCN', '啊！这是什么味儿？哦……联盟派出了“精兵”。你知道他们为什么这么臭吗？因为他们吃了太多奶酪。', '', 28153),
(149890, 'zhCN', '愿圣光祝福你。', '', 28153),
(149889, 'zhCN', '打的不错。不过我更强。', '', 28153),
(149888, 'zhCN', '正在回撤。', '', 28153),
(149887, 'zhCN', '圣光会治愈你！', '', 28153),
(149886, 'zhCN', '啊，是联盟。我今天本来心情很好。麻烦你们照顾一下我的情绪，离开好吗？', '', 28153),
(149885, 'zhCN', '这座岛是我们的，联盟。如果你们就此收手，我们就不会使用暴力。', '', 28153),
(149884, 'zhCN', '敌人已经来了！', '', 28153),
(149883, 'zhCN', '$n开始施放强效治疗术！', '$n开始施放强效治疗术！', 28153),
(149882, 'zhCN', '', '没有路就开一条路出来。我们必须争分夺秒。', 28153),
(149881, 'zhCN', '', '那就这样定了。萨鲁法尔，纳萨诺斯，立即出发。', 28153),
(149880, 'zhCN', '大多数走私商人都不希望和大王这样的人打交道……不过我们可以说服那个人来帮助我们。', '', 28153),
(149879, 'zhCN', '我可不蠢。永望镇的货物绝不可能是从合法途径运来的。走的一定是费伍德森林里的隐藏通道。', '', 28153),
(149878, 'zhCN', '你说什么？', '', 28153),
(149877, 'zhCN', '嗯……你认识很多走私商人吗，凋零者？', '', 28153),
(149876, 'zhCN', '', '我们要对玛法里奥发动两面夹击。', 28153),
(149875, 'zhCN', '', '萨鲁法尔，带领小队前往费伍德，找出通过山路前往黑海岸的道路。把攻城武器留给我来指挥。', 28153),
(149874, 'zhCN', '', '看来这些小精灵很容易分心。我们要利用这个弱点来通过它们。', 28153),
(149873, 'zhCN', '大酋长，想穿过费伍德森林，没有哪条路是安全的。', '', 28153),
(149872, 'zhCN', '', '祖达萨是在大分裂中得以幸存并仍旧繁荣的城市之一。在其鼎盛之时，赞达拉巨魔帝国曾统治着这个世界的半壁江山。在苏拉玛，我们仍然警告我们的子孙要小心那些巨魔还有他们黑暗的手段。\n\n我看见他们变成了嗜血的野蛮人。但是看到这幅景象……我不禁怀疑赞达拉巨魔和部落之间到底谁更需要对方。', 28153),
(149871, 'zhCN', '', '沙漠将扬起狐人复仇的怒火。让他们血债血偿！', 28153),
(149870, 'zhCN', '', '死期到了，无信者！', 28153),
(149869, 'zhCN', '', '去佐拉姆加，快！', 28153),
(149868, 'zhCN', '仪式就要开始了。', '仪式就要开始了。', 28153),
(149867, 'zhCN', '好吧，说起来有点尴尬。\n\n你瞧，我把演说都写在笔记里，但是我似乎……找不到了。\n\n笔记肯定就在这个房间的某个地方。如果你能帮我找到它，我会永远感激你！', '', 28153),
(149866, 'zhCN', '嘿，你好啊。恐怕我们还没见过，但谢谢你能到这里找我的亲爱的露希。\n\n有什么我能帮你的吗？', '', 28153),
(149865, 'zhCN', '别担心，在纳兹米尔瓦扎会照顾你的！', '', 28153),
(149864, 'zhCN', '露希尔不知道的是，每次她来雪林我都会去见她。\n\n她对这里发生的事充满绝望，这让她看不到我的灵魂。我只能希望她的内心深处知道我在这里。', '', 28153),
(149858, 'zhCN', '现在，你该去和他们做伴了。愿塞塔里斯原谅你。', '', 28153),
(149857, 'zhCN', '我们自己乱战了起来！', '我们自己乱战了起来！', 28153),
(149856, 'zhCN', '库亚冯吞掉了鱼。', '', 28153),
(149855, 'zhCN', '库亚冯警惕地嗅了嗅面前的鱼。', '', 28153),
(149854, 'zhCN', '<投喂闪鳍鱼肉。>', '<投喂闪鳍鱼肉。>', 28153),
(149853, 'zhCN', '<库亚冯恐惧地退缩，在你靠近时做出了回避。>$b$b也许这个小家伙需要一些劝说。或者一顿美餐？', '', 28153),
(149852, 'zhCN', '永远……', '', 28153),
(149851, 'zhCN', '我永远都在这儿，亲爱的露希……', '', 28153),
(149850, 'zhCN', '', '哦，亚历山大……如果你在这儿就好了……', 28153),
(149849, 'zhCN', '谢谢你，朋友。', '', 28153),
(149848, 'zhCN', '我终于……可以抛下这里的往事了。', '', 28153),
(149847, 'zhCN', '不，老朋友。我们的人民是因你而死。', '', 28153),
(149846, 'zhCN', '我从未强迫任何人追随我，沃里克……我们的人民是天生的征服者……', '', 28153),
(149845, 'zhCN', '你会后悔……看到这一切的……', '你会后悔……看到这一切的……', 28153),
(149844, 'zhCN', '维克雷斯夫人可不好惹……', '维克雷斯女士可不好惹……', 28153),
(149843, 'zhCN', '', '别搞砸了！', 28153),
(149842, 'zhCN', '别担心，我来干掉这个杂碎。', '不用担心，我会解决这只害虫的。', 28153),
(149841, 'zhCN', '', '蠢货！绝不能留下目击者！', 28153),
(149840, 'zhCN', '看来我们有客人了……', '看来我们有客人了……', 28153),
(149839, 'zhCN', '跟你做生意很高兴，女士。', '很高兴跟你做生意，女士。', 28153),
(149838, 'zhCN', '', '这是你的酬金，逃犯。钱拿好，别被人看见了！', 28153),
(149837, 'zhCN', '是偷袭！露希，到我身后来！卫兵，战斗！', '', 28153),
(149836, 'zhCN', '', '亚历山大，不！', 28153),
(149835, 'zhCN', '我只是公事公办，小子。', '我只是公事公办，小子。', 28153),
(149834, 'zhCN', '亚历山大，你准备好——等等，那是什么！？', '', 28153),
(149833, 'zhCN', '身为德鲁斯瓦的领主，以及露希尔的父亲，我很荣幸能在这片土地、天空和海洋的见证下，让这对眷侣结为夫妻。', '', 28153),
(149832, 'zhCN', '各位亲朋好友，贵客嘉宾。我们在这秋高气爽的日子欢聚一堂，庆祝露希尔和亚历山大喜结连理。', '', 28153),
(149831, 'zhCN', '好的。', '', 28153),
(149830, 'zhCN', '', '当然。开始吧，父亲。', 28153),
(149829, 'zhCN', '开始吧？', '', 28153),
(149828, 'zhCN', '她马上就下来。她让我代替她开始。', '', 28153),
(149827, 'zhCN', '', '没关系，父亲。母亲去哪儿了？', 28153),
(149826, 'zhCN', '请原谅我姗姗来迟。', '', 28153),
(149825, 'zhCN', '但维克雷斯夫人在哪？', '', 28153),
(149824, 'zhCN', '', '他来了！', 28153),
(149823, 'zhCN', '哦，顺便转达一下我的歉意，我太拖沓了。', '', 28153),
(149822, 'zhCN', '请告诉楼下的那对新人，我马上就下来。', '', 28153),
(149821, 'zhCN', '哦，你找到它了！感谢潮汐！', '', 28153),
(149820, 'zhCN', '', '你是想浪费我们的时间吗？', 28153),
(149819, 'zhCN', '', '我们找的是书。你以为我们不会先检查书架？', 28153),
(149818, 'zhCN', '', '我丈夫怎么会把笔记放在露希尔的背包里？你有脑子吗？', 28153),
(149817, 'zhCN', '我相信我没有把它放在露希的信件里，但还是确定一下比较好。', '', 28153),
(149816, 'zhCN', '虽然我很感激你能帮忙，但还是请你别在我女儿的内衣里翻来翻去……', '', 28153),
(149815, 'zhCN', '', '她内心的呼唤对我们家族可没什么帮助……', 28153),
(149814, 'zhCN', '露希不过是聆听了内心的呼唤，梅瑞狄斯。就像我娶你时一样。', '', 28153),
(149813, 'zhCN', '', '阿瑟，你不该同意这门亲事。我们的宝贝女儿怎么可以下嫁给一个穷商人！？', 28153),
(149812, 'zhCN', '', '感谢您大驾光临。我们非常荣幸。', 28153),
(149811, 'zhCN', '你为什么会来这里？', '', 28153),
(149810, 'zhCN', '露希？你终于……等等，你不是露希。', '', 28153),
(149809, 'zhCN', '你也一样。你父亲对你把这些生物带到这里的行为十分不满。他命我将你带走。', '', 28153),
(149807, 'zhCN', '当然是无论这里发生了什么，都要确保胜利。加卡泽将军已经拿到了我的钥匙，而现在……我猜他也拿到你们的了。', '', 28153),
(149806, 'zhCN', '你做了什么，柯泰克？', '', 28153),
(149805, 'zhCN', '告诉我，沃里克……既然你出现在这里，那又是谁来守卫你们神殿中的钥匙呢？', '', 28153),
(149804, 'zhCN', '', '我为保护我的人民而生。你将死在我这个贱种的手中！', 28153),
(149803, 'zhCN', '卑贱的狐人，你存在的意义就是侍奉我的帝国！', '', 28153),
(149802, 'zhCN', '', '', 28153),
(149801, 'zhCN', '我要买一副新牙，纯金的！', '我要买一副新牙，纯金的！', 28153),
(149800, 'zhCN', '我们会牢牢封印米斯拉克斯的监牢，团结我们的子民。', '', 28153),
(149799, 'zhCN', '都是我们干的活儿，所有黄金都该是我们的。', '都是我们干的活儿，所有黄金都该是我们的。', 28153),
(149798, 'zhCN', '不。你是我们的失败。塞塔里斯牺牲了自己，才让我们得以和平生活。', '', 28153),
(149797, 'zhCN', '我，才是蛇人真正的力量！', '', 28153),
(149796, 'zhCN', '你们最好别打我那一份的主意。', '你们最好别打我那一份的主意。', 28153),
(149795, 'zhCN', '要是让我找到，我就带着宝物跑路！', '要是让我找到，我就带着宝物跑路！', 28153),
(149794, 'zhCN', '他们会给找到它的人额外分一杯羹！', '他们会给找到它的人额外分一杯羹！', 28153),
(149793, 'zhCN', '价值三百万金币啊，我们要发财啦！', '价值三百万金币啊，我们要发财啦！', 28153),
(149792, 'zhCN', '也许我们挖错地方了？', '也许我们挖错地方了？', 28153),
(149791, 'zhCN', '我要买一座城堡，里面还要有热水浴缸和仆人。', '我要买一座城堡，里面还要有热水浴缸和仆人。', 28153),
(149790, 'zhCN', '奈特利说我们已经很接近了，随时会找到。', '奈特利说我们已经很接近了，随时会找到。', 28153),
(149789, 'zhCN', '我要买一艘比现在所有战舰都大的船！', '我要买一艘比现在所有战舰都大的船！', 28153),
(149788, 'zhCN', '300万的267分之一是多少？', '300万的267分之一是多少？', 28153),
(149787, 'zhCN', '这么多钱，就算是吉安娜·普罗德摩尔也会因此嫁给我的！', '这么多钱，就算是吉安娜·普罗德摩尔也会因此嫁给我的！', 28153),
(149786, 'zhCN', '', '……哦，这种事总是难免的。', 28153),
(149785, 'zhCN', '', '他们将首次感到风吹过翅膀的感觉。感到飞翔的快乐！和……', 28153),
(149784, 'zhCN', '', '啊……又有一只响应了天空的召唤！', 28153),
(149783, 'zhCN', '别去太久。我们必须立即对柯泰克大帝发起进攻。', '', 28153),
(149782, 'zhCN', '我会留在这准备进攻，你到无信者中间制造混乱。', '', 28153),
(149781, 'zhCN', '<将幼崽推出巢穴。>', '<将幼崽推出巢穴。>', 28153),
(149779, 'zhCN', '[客户端场景 - 泰莉亚走上前来，指控艾什凡女勋爵才是袭击的幕后黑手。你没发现吗，凯瑟琳？她一直以来的计划就是代替你。凯瑟琳转向普里西拉 - 这是真的吗？普里西拉抛开了“弱小而可怜”的演技。她厉声斥责凯瑟琳：懦弱！不配当权！是艾什凡家族建立了这座城市！用她的手枪朝凯瑟琳开了一枪。卫兵立刻采取行动。普里西拉朝人群附近的一辆货车上的木桶射击，引燃了一片烟幕。烟幕迅速笼罩了整个广场。混乱随之发生。]', '[客户端场景 - 泰莉亚走上前来，指控艾什凡女勋爵才是袭击的幕后黑手。你没发现吗，凯瑟琳？她一直以来的计划就是代替你。凯瑟琳转向普里西拉 - 这是真的吗？普里西拉抛开了“弱小而可怜”的演技。她厉声斥责凯瑟琳：懦弱！不配当权！是艾什凡家族建立了这座城市！用她的手枪朝凯瑟琳开了一枪。卫兵立刻采取行动。普里西拉朝人群附近的一辆货车上的木桶射击，引燃了一片烟幕。烟幕迅速笼罩了整个广场。混乱随之发生。]', 28153),
(149778, 'zhCN', '沃里克，我准备好面对柯泰克大帝了。', '沃里克，我准备好面对柯泰克大帝了。', 28153),
(149777, 'zhCN', '', '我的战利品……不……', 28153),
(149776, 'zhCN', '吞噬这艘被诅咒的船只，解救我们的人民！', '', 28153),
(149775, 'zhCN', '', '瞧瞧你那亮闪闪的武器，又有新的战利品了！', 28153),
(149774, 'zhCN', '大海的伟大风暴啊，请听从我的召唤！', '', 28153),
(149772, 'zhCN', '[PH]厉害，“老朋友”。但是这个还不足以阻止我！', '', 28153),
(149771, 'zhCN', '[PH]钥匙藏在我的要塞深处，沃里克。你真的以为我会蠢到把它放在身上？', '', 28153),
(149770, 'zhCN', '[PH]不过你说对了一件事。废话到此结束了！', '', 28153),
(149769, 'zhCN', '[Ph]别废话了， 我的老朋友。乖乖交出米拉斯克斯牢房的钥匙。你会毁灭了我们所有人的！', '', 28153),
(149768, 'zhCN', '在你们面前的是伟大的柯泰克，永恒的帝王！', '', 28153),
(149767, 'zhCN', '[PH]好了， 我可以吸取这座塔的力量了。到大门那儿，快！', '', 28153),
(149766, 'zhCN', '', '我的老天，见到你真高兴， $p! 我实在是不明白，这里……', 28153),
(149765, 'zhCN', '', '基罗总是神龙见首不见尾。他一直在忙些什么大计划。\n\n他和尼莎一起走了。但是我最近一次听到他的消息，是说他正准备深入峡谷去偷补给品或是破坏火炮之类的。', 28153),
(149764, 'zhCN', '', '尼莎正在下面的奴隶营地制造麻烦。出了这个洞穴之后向西走，然后沿着你右边的第一个斜坡下去。\n\n如果找不到方向，就听听濒死的蛇人所发出的声音，跟着那些声音走就行。她应该就在那附近。', 28153),
(149763, 'zhCN', '', '哦，这可是最棒的部分！在你来的路上，你估计都没注意到他们吧？\n\n隐匿的狐人正潜藏在逃跑的路线上，时刻提防着无信者！\n\n当他们认为路上安全时，我就会带一些狐人出去和车队碰面，带他们前往安全地带。\n\n然后我再溜回来，准备带领下一支队伍。这真是太刺激了，至今为止我也只惊叫过三次而已！\n\n如果你要离开，只要逃出洞穴然后一直向西就行了。穿过桥进入到废墟之后，你就彻底自由了。', 28153),
(149762, 'zhCN', '', '和你一样，我猜。看看这里的狐人……他们受伤了，需要别人的帮助。\n\n无信者奴役了我们无数人，逼迫我们替他们卖力，为他们战斗。\n\n我们世代受苦，却无力阻止他们。但是尼莎和基罗用行动证明了，我们是有能力反抗的。\n\n晚上，基罗一行人会潜入下方的奴隶营地，救出最为虚弱的狐人。\n\n他们会把大伙带回这里。然后我会护送大家安全地抵达沙漠，那里会有车队把他们转移到安全地点。\n\n这太危险了，我真的很想回到营地里，在篝火边听阿娜唱歌。但我又怎么忍心在朋友需要支援时临阵脱逃呢？', 28153),
(149761, 'zhCN', '我想要问问你别的事情。', '我想要问问你别的事情。', 28153),
(149760, 'zhCN', '尼莎在哪儿？', '尼莎在哪儿？', 28153),
(149759, 'zhCN', '基罗在哪儿？', '基罗在哪儿？', 28153),
(149758, 'zhCN', '你是怎么把奴隶偷送出去的？', '你是怎么把奴隶偷送出去的？', 28153),
(149757, 'zhCN', '你在这里干什么？', '你在这里干什么？', 28153),
(149756, 'zhCN', '', '$p！我就知道你会来的！我跟他们说过，$p很关心狐人，不会丢下我们不管。\n\n我也是来帮忙的！基罗和尼莎准备去营救狐人奴隶，我在组织车队送他们离开。\n\n从蛇人的眼皮底下经过，真有点吓人。但我知道这是正确的选择。尼莎是这么说的。\n\n哦，顺便欢迎你来到我们的小小避难所。', 28153),
(149755, 'zhCN', '带路吧。', '带路吧。', 28153),
(149754, 'zhCN', '如果你撒谎，你就会被吊死。', '如果你撒谎，你就会被吊死。', 28153),
(149753, 'zhCN', '我跟你一起。', '我跟你一起。', 28153),
(149752, 'zhCN', '', '我们的部队会好好使用这些物资的。干得好！', 28153),
(149751, 'zhCN', '', '我们发现了一艘小船的残骸，被鲜血巨魔袭击过。快去收集物资，别让鲜血巨魔抢走了！', 28153),
(149750, 'zhCN', '但愿是好事儿。', '但愿是好事儿。', 28153),
(149749, 'zhCN', '嗯。好吧，我们走！', '嗯。好吧，我们走！', 28153),
(149748, 'zhCN', '什么？！你最好是对的……', '什么？！你最好是对的……', 28153),
(149747, 'zhCN', '很好，我可靠的侍从，看起来我们在这里的工作已经完成了。如果没有别的事的话，我还要去杀双头怪。', '', 28153),
(149746, 'zhCN', '一个强盗！不必害怕，女士，有我保护你！', '', 28153),
(149745, 'zhCN', '星际恶魔？我可不会对这种侮辱烁影二世的话充耳不闻！准备好尝一尝强尼的——那是双头怪吗？', '', 28153),
(149744, 'zhCN', '我看见你和那个星际恶魔起了冲突！我命令你自己去消灭它！它打伤你了吗？', '', 28153),
(149743, 'zhCN', '', '凯瑟琳正在失去人民对她的信任……', 28153),
(149742, 'zhCN', '', '太好了……我们也许要闹一闹了。', 28153),
(149741, 'zhCN', '', '第一步，发起暴乱。', 28153),
(149740, 'zhCN', '[PH]够了。米斯拉克斯将会现身，而你们这些叛徒将迎来毁灭！', '', 28153),
(149739, 'zhCN', '[PH] 钥匙将会属于我们……米斯拉克斯会再度复活!', '', 28153),
(149738, 'zhCN', '烁影二世……你为什么没有飞……？', '', 28153),
(149737, 'zhCN', '[Ph]我要开始了……还需要点时间，柯泰克的爪牙来了!', '', 28153),
(149736, 'zhCN', '我准备好保护你免受蛇人的伤害了，开始吧。', '我准备好保护你免受蛇人的伤害了，开始吧。', 28153),
(149735, 'zhCN', '[PH]准备好了吗？我们必须抓紧时间，柯泰克的军队会阻止我获取尖塔中的力量，我需要你在我施法的时候保护我。', '', 28153),
(149730, 'zhCN', '这些小精灵都是哪来的？', '', 28153),
(149729, 'zhCN', '啊呀！该死的小精灵，还真疼！', '', 28153),
(149726, 'zhCN', '你为伯拉勒斯消灭了一个重要的威胁，英雄，但我以全身家当打赌，这座城市还没有脱离危险。', '', 28153),
(149725, 'zhCN', '没有了那个两面三刀的懦夫和他手下的船长们，这支海盗军队就像一盘散沙，只能树倒猢狲散了。', '', 28153),
(149724, 'zhCN', '哈兰早该知道，背叛我就会是这个下场。', '', 28153),
(149723, 'zhCN', '但这对你来说完全不是问题，对吧？', '', 28153),
(149722, 'zhCN', '呃，除了他手下那群恶毒的打手和杀人犯。', '', 28153),
(149720, 'zhCN', '[PH]我会找到通往尖塔的道路。在那儿和我碰头。柯泰克的爪牙肯定会阻止我们利用他们的力量。', '', 28153),
(149719, 'zhCN', '迷人的女士，是什么使你烦恼呢？北郡骑士麦斯米兰，为你效劳！', '', 28153),
(149717, 'zhCN', '', '没有你，我们就不可能找到莱克拉，小家伙。', 28153),
(149716, 'zhCN', '听起来是一位少女需要我们去救援。跟我来，侍从！', '', 28153),
(149715, 'zhCN', '你也看到了，侍从，虽然我上次尝试打败这个双头怪的结果不佳，但是我的骑枪确确实实扎进了它的身体里。所以，我给你的第一项任务就是——', '', 28153),
(149714, 'zhCN', '', '我们是朋友，对吧？', 28153),
(149713, 'zhCN', '', '废墟就在前往泽姆兰的道路上。我很乐意带你去那儿！虽然朵利和朵特都是很棒的伙伴，但有人聊天就好。', 28153),
(149712, 'zhCN', '那个泡泡是……哦！你喝不了盐水？那真是奇怪，小东西。', '', 28153),
(149711, 'zhCN', '不！！！！这不可能！！！！', '', 28153),
(149710, 'zhCN', '等等……狐人来这里做什么？', '', 28153),
(149709, 'zhCN', '那里已废弃多年，但会是一个理想之地，来谋划我们的——', '', 28153),
(149708, 'zhCN', '我自己的圣所远在山间。那是一个供奉塞塔里斯的小神殿，有时我会去那里冥想。', '', 28153),
(149707, 'zhCN', '那时，我和柯泰克一起领导所有的蛇人，信奉塞塔里斯。', '', 28153),
(149706, 'zhCN', '溺亡之梦吞噬了我！', '溺亡之梦吞噬了我！', 28153),
(149705, 'zhCN', '很久以前，我也在这里生活。那时柯泰克还没有为了谋求力量与疯狂而背叛我们的子民。', '', 28153),
(149704, 'zhCN', '那是片布满岩石和尘土的冰冷巢穴，到处都是背弃我们神灵的蛇人。', '', 28153),
(149703, 'zhCN', '我在无尽的虚空中畅饮。', '我在无尽的虚空中畅饮。', 28153),
(149702, 'zhCN', '我不再盲目。', '我不再盲目。', 28153),
(149701, 'zhCN', '我们将要进入无信者帝国的中心，$p。', '', 28153),
(149700, 'zhCN', '轮回……我看到了轮回！', '对……轮回……我看到了轮回！', 28153),
(149699, 'zhCN', '翻腾的阴影为我而来！', '哦……翻腾的阴影为我而来！', 28153),
(149698, 'zhCN', '我听到了声音！万千个真理！', '啊……我听到了声音！万千个真理！', 28153),
(149697, 'zhCN', '我会在深渊中永生。', '我会在深渊中永生。', 28153),
(149696, 'zhCN', '终于！通往哈兰·斯威提的道路已经敞开，没有什么可以阻挡我们了。', '', 28153),
(149695, 'zhCN', '我的灵魂属于古老的存在！', '我的灵魂属于古老的存在！', 28153),
(149694, 'zhCN', '', '我们会像保护自己的子民一样保护你们。', 28153),
(149693, 'zhCN', '所以，我们可以好好利用一下你的打架专长，怎么样？', '', 28153),
(149692, 'zhCN', '那该死的家伙让整座岛处于禁闭状态，直到决斗场的活动结束为止。', '', 28153),
(149691, 'zhCN', '我的衣领上没有宁神花，联盟的混蛋！', '我的衣领上没有宁神花，联盟的混蛋！', 28153),
(149690, 'zhCN', '我对矿道地铁一无所知！', '我对矿道地铁一无所知！', 28153),
(149689, 'zhCN', '现在剩下的就是让哈兰品尝一下冰冷的铁刃的滋味了。不过这可不容易做到。', '', 28153),
(149688, 'zhCN', '枭兽不会飞！你得走了！', '枭兽不会飞！你得走了！', 28153),
(149687, 'zhCN', '我不是间谍！', '我不是间谍！', 28153),
(149686, 'zhCN', '“鱼人什么的什么？”你脑子不正常吧！', '“鱼人什么的什么？”你脑子不正常吧！', 28153),
(149685, 'zhCN', '“一瓶巨魔的汗水？”我们这里不卖那玩意儿！', '“一瓶巨魔的汗水？”我们这里不卖那玩意儿！', 28153),
(149684, 'zhCN', '因为树很美，所以着火就不好了。你这是什么意思？', '因为树很美，所以着火就不好了。你这是什么意思？', 28153),
(149683, 'zhCN', '赞达拉万古长存！', '赞达拉万古长存！', 28153),
(149682, 'zhCN', '', '这个神殿有点不对劲。我们需要找到进去的路。', 28153),
(149681, 'zhCN', '如果你不当英雄的话，会是一名很好的海盗。', '', 28153),
(149680, 'zhCN', '我的沉眠……只为觉醒……', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149679, 'zhCN', '那……很好，麦斯米兰。我现在要走了。', '那……很好，麦斯米兰。我现在要走了。', 28153),
(149678, 'zhCN', '无尽的暗影……会拥抱我……', '', 28153),
(149677, 'zhCN', '你的希望……消散了……', '', 28153),
(149676, 'zhCN', '嗯……什么？', '嗯……什么？', 28153),
(149675, 'zhCN', '种子……已经生根……', '', 28153),
(149674, 'zhCN', '我不过是……万分之一……', '', 28153),
(149673, 'zhCN', '轮回……永续……', '', 28153),
(149672, 'zhCN', '就连死神……也会……死去……', '', 28153),
(149671, 'zhCN', '总有一天……你会接受真理……', '', 28153),
(149670, 'zhCN', '你听说了吗？戴林之门沦陷了！', '你听说了吗？戴林之门沦陷了！', 28153),
(149669, 'zhCN', '你对这一切有什么想法？', '你对这一切有什么想法？', 28153),
(149668, 'zhCN', '洪流会将你冲入深渊。', '', 28153),
(149667, 'zhCN', '啊，这噪音让我简直想要重操旧业了。', '', 28153),
(149666, 'zhCN', '黑齿帮喜欢比谁的拳头硬。如果你能敲下他们的牙齿，拉乌尔船长一定会想让你参加聚会。', '', 28153),
(149665, 'zhCN', '你嘴里发出的这些噪音是怎么回事？', '', 28153),
(149664, 'zhCN', '就连鱼都没有水鼠帮能喝！如果你能跟这群禽兽拼几轮酒，尤朵拉船长一定会忍不住邀请你参加聚会。', '', 28153),
(149663, 'zhCN', '你听说了关于袭击的哪些消息？', '你听说了关于袭击的哪些消息？', 28153),
(149662, 'zhCN', '别说我对战争毫无贡献。这是我的报告。', '别说我对战争毫无贡献。这是我的报告。', 28153),
(149661, 'zhCN', '', '朵利和朵特是我最好的朋友，拉着我的货车穿过一座座沙丘！', 28153),
(149660, 'zhCN', '我不知道……事态每天都在恶化。也许凯瑟琳是时候退位了。', '我不知道……事态每天都在恶化。也许凯瑟琳是时候退位了。', 28153),
(149659, 'zhCN', '我不会辜负联盟。即使是我也是在泥地里坐了三天才弄到了这个。请拿走我的报告。', '我不会辜负联盟。即使是我也是在泥地里坐了三天才弄到了这个。请拿走我的报告。', 28153),
(149658, 'zhCN', '', '朵特和朵利喜欢听我唱歌，会很放松。', 28153),
(149657, 'zhCN', '你能相信吗？有人居然觉得巨魔和暗夜精灵有关系？真是一次痛苦的经历。这是我的报告。', '你能相信吗？有人居然觉得巨魔和暗夜精灵有关系？真是一次痛苦的经历。这是我的报告。', 28153),
(149656, 'zhCN', '如果你能弄到一张邀请函，那会好办很多。或者你就直接冲进去，一次性干掉本地最恶名昭彰的三名海盗船长。你选吧，伙计。', '', 28153),
(149655, 'zhCN', '', '朵利和朵特是我最好的朋友，拉着我的货车穿过一座座沙丘。他们都有小小的牙齿，也喜欢吃东西……', 28153),
(149654, 'zhCN', '我说过为了向泰达希尔复仇，我什么都愿意去做。装成一个巨魔，显然也不在话下。这是我的报告。', '我说过为了向泰达希尔复仇，我什么都愿意去做。装成一个巨魔，显然也不在话下。这是我的报告。', 28153),
(149653, 'zhCN', '我的情报声称那些船长正在举行秘密聚会，如果我们闯进他们的派对，你就可以把多头蛇的脑袋一下子全部砍掉。', '', 28153),
(149652, 'zhCN', '我的翼手龙在哪儿？', '我的翼手龙在哪儿？', 28153),
(149651, 'zhCN', '我的宝宝出什么问题了？', '我的宝宝出什么问题了？', 28153),
(149650, 'zhCN', '他们说，只是一次小小的丛林旅程。他们说，会很轻松的。快拿走我的报告吧。', '他们说，只是一次小小的丛林旅程。他们说，我会没事的。快拿走我的报告吧。', 28153),
(149649, 'zhCN', '他为什么在制造噪音？！', '他为什么在制造噪音？！', 28153),
(149648, 'zhCN', '野蛮人。完完全全、彻头彻尾的野蛮人。请拿走我的报告吧。', '野蛮人。完完全全、彻头彻尾的野蛮人。请拿走我的报告吧。', 28153),
(149647, 'zhCN', '别问我昨晚是在哪儿睡的。这是你的报告。', '别问我昨晚是在哪儿睡的。这是你的报告。', 28153),
(149646, 'zhCN', '多谢。', '多谢。', 28153),
(149645, 'zhCN', '我比较擅长掌控大局，所以计划的细节就靠你落实了。', '', 28153),
(149644, 'zhCN', '然后就可以让哈兰得到应有的下场了。', '', 28153),
(149643, 'zhCN', '溺毙在永恒的鲜血中吧。', '', 28153),
(149642, 'zhCN', '我们的计划是，截杀破浪，火烤水鼠，打碎黑齿，踏平铁潮。', '', 28153),
(149641, 'zhCN', '如果成功的话，他统领的舰队就会威胁到整个地区的安宁。', '', 28153),
(149640, 'zhCN', '我好像听到了尖叫声，但是我不能离开巢穴去查看。$b$b你最好快一点，不然你就没有照顾翼手龙的机会了。不是所有翼手龙都能活到成年。', '', 28153),
(149639, 'zhCN', '哈兰·斯威提利用铁潮的名号召集其他海盗当他的手下。', '', 28153),
(149638, 'zhCN', '噢，他跑开了。也许是因为无聊吧。$b$b你最好在他受伤之前找到他。他还没法独立照顾自己。', '', 28153),
(149637, 'zhCN', '他明显看起来有些低落，对吧？$b$b我猜他是想他的妈妈了。嘿，那不就是你吗？', '', 28153),
(149636, 'zhCN', '你的灵魂将只剩饥渴。', '', 28153),
(149635, 'zhCN', '我们的晋升让群星颤栗。', '', 28153),
(149634, 'zhCN', '他发出那种声音，肯定是因为他饿了。$b$b在他咬掉指头之前最好给它喂点东西吃。$b$b如果你没带食物，可以去战兽栏里拿一些。', '', 28153),
(149633, 'zhCN', '接受真正虚无的拥抱吧。', '', 28153),
(149632, 'zhCN', '在尼奥罗萨永远沉眠吧。', '', 28153),
(149631, 'zhCN', '无尽深海可以吞没一切光芒。', '', 28153),
(149630, 'zhCN', '我是护风者戈加。帕库是我的洛阿神灵，我侍奉狂风之王，并看护她的后代。$b$b她告诉我你可能需要一些帮助。$b$b<护风者戈加轻声地笑了一下。>$b$b我能帮你做些什么？', '', 28153),
(149629, 'zhCN', '看清你死亡的阴影吧。', '', 28153),
(149628, 'zhCN', '我听说是海盗。你信吗？病怏怏、臭烘烘的海盗！普罗德摩尔家族还能保护我们吗？', '我听说是海盗。你信吗？病怏怏、臭烘烘的海盗！普罗德摩尔家族还能保护我们吗？', 28153),
(149627, 'zhCN', '啊！我忠实的随从！总是出现在我最需要的时候。\n\n我来到库尔提拉斯，是希望找到需要拯救的危难之人。我现在的任务，是将这个质朴村庄里的可怜渔夫们，从想要恐吓他们的双头怪手中解救出来。\n\n他们的皮特别厚。', '', 28153),
(149626, 'zhCN', '是的，其他人也需要。请排队，尽量不要扰乱秩序。群众已经很愤怒了。', '是的，其他人也需要。请排队，尽量不要扰乱秩序。群众已经很愤怒了。', 28153),
(149625, 'zhCN', '我需要立即和凯瑟琳·普罗德摩尔说话。', '我需要立即和凯瑟琳·普罗德摩尔说话。', 28153),
(149624, 'zhCN', '海军统帅普罗德摩尔正准备发表公开演讲。请保持耐心。', '海军统帅普罗德摩尔正准备发表公开演讲。请保持耐心。', 28153),
(149623, 'zhCN', '海军统帅有危险。跟我们来！', '海军统帅有危险。跟我们来！', 28153),
(149622, 'zhCN', '请保持冷静。一切都在掌控之中。', '请保持冷静。一切都在掌控之中。', 28153),
(149621, 'zhCN', '奈特利·格林纳可不喜欢被人占便宜。没人会比我抢先一步找到宝藏！', '', 28153),
(149620, 'zhCN', '你别以为我会放松警惕。\n\n如果你想骗我，我就把你卖给死忠派。', '', 28153),
(149619, 'zhCN', '潮汐之血不久前遭到了腐化。我应该有办法净化它。', '', 28153),
(149618, 'zhCN', '啊！它比我想的还不稳定。', '', 28153),
(149617, 'zhCN', '你好，旅行者！\n\n你是否一直在追随我的英雄故事，梦想有朝一日成为北郡骑士麦斯米兰的随从呢？\n\n你很幸运，你的梦想实现了！我需要一个随从，在我对付危险敌人的时候协助我完成任务。', '', 28153),
(149616, 'zhCN', '', '我会找到她，或是死在寻找她的路上。', 28153),
(149615, 'zhCN', '', '泽姆兰的港口就在南方。已经有很多年没有船驶入它的码头了，但我们很有可能在那里找到基罗和尼莎攻击蛇人所需的东西。', 28153),
(149614, 'zhCN', '', '你留意你朋友的踪迹。我会专心看路。', 28153),
(149613, 'zhCN', '', '这是大战之后，可是……图尔没死。他遍体鳞伤，但却没死！', 28153),
(149612, 'zhCN', '', '所有关于此事的历史记载都说，阿罗姆勋爵杀死了高莱克·图尔，他的部队也随之崩溃。但这里画的是，他被刺中后，力量崩溃，所有构造体也碎了。其中肯定有关联。', 28153),
(149611, 'zhCN', '', '那是阿罗姆·维克雷斯勋爵，当年他只是个上校，领导了总攻。而那边……是高莱克·图尔被维克雷斯一剑刺穿。', 28153),
(149610, 'zhCN', '', '这不是德鲁斯特刻的，而是库尔提拉斯人在德鲁斯特巨石上刻的。', 28153),
(149609, 'zhCN', '', '真有意思。我之前不知道构造体是他狗急跳墙才制造的。', 28153),
(149608, 'zhCN', 'Zuq yoh\'ghyl ma oou shandai nuq Ez iilth thyzz', '', 28153),
(149607, 'zhCN', 'Fhssh zzof og far\'al awtgsshu', '', 28153),
(149606, 'zhCN', '', '干得漂亮！你让卡格瓦的子嗣获得了喘息之机。谢谢你，英雄。', 28153),
(149605, 'zhCN', '库亚冯发出开心的尖叫，一口吞下食物。', '', 28153),
(149604, 'zhCN', '库亚冯嗅了嗅食物，然后凶残地吞了下去。', '', 28153),
(149603, 'zhCN', '库亚冯在空中吞下食物。', '', 28153),
(149602, 'zhCN', '库亚冯扑向面前的食物，一口吞了下去。', '', 28153),
(149601, 'zhCN', '', '鲜血巨魔又在狩猎卡格瓦的子嗣。青蛙之王的内心正燃烧着怒火。帮助他复仇吧！', 28153),
(149600, 'zhCN', '以斯托颂之名！', '以斯托颂之名！', 28153),
(149599, 'zhCN', '山谷属于我们，舱底鼠！', '山谷属于我们，舱底鼠！', 28153),
(149598, 'zhCN', '如果没有我们，库尔提拉斯必将葬身鱼腹！', '如果没有我们，库尔提拉斯必将葬身鱼腹！', 28153),
(149597, 'zhCN', '我们的舰队会让你灰飞烟灭！', '我们的舰队会让你灰飞烟灭！', 28153),
(149596, 'zhCN', '跟我们作对的人都得死！', '跟我们作对的人都得死！', 28153),
(149595, 'zhCN', '我们就像漆黑的海渊一样冰冷无情！', '我们就像漆黑的海渊一样冰冷无情！', 28153),
(149594, 'zhCN', '你竟敢忤逆斯托颂家族？', '你竟敢忤逆斯托颂家族？', 28153),
(149593, 'zhCN', '库尔提拉斯属于大海！', '库尔提拉斯属于大海！', 28153),
(149592, 'zhCN', '我的生命……献给大海……', '我的生命……献给大海……', 28153),
(149591, 'zhCN', '海潮贤者……请保护我……', '海潮贤者……请保护我……', 28153),
(149590, 'zhCN', '我只是……听命行事……', '我只是……听命行事……', 28153),
(149589, 'zhCN', '我们已经……胜利了……', '我们已经……胜利了……', 28153),
(149588, 'zhCN', '就算杀了我……也没用……', '就算杀了我……也没用……', 28153),
(149587, 'zhCN', '我们永不……停歇……', '我们永不……停歇……', 28153),
(149586, 'zhCN', '我为海潮……流尽鲜血……', '我为海潮……流尽鲜血……', 28153),
(149585, 'zhCN', '我在深渊中……看到了真理。', '我在深渊中……看到了真理。', 28153),
(149584, 'zhCN', '你不知道这有多耻辱。这是你的报告。', '你不知道这有多耻辱。这是你的报告。', 28153),
(149583, 'zhCN', '', '一群蠢货……至少现在我们知道小精灵有多危险了。', 28153),
(149582, 'zhCN', '', '下次我看到你，就别想逃跑了，玛法里奥！', 28153),
(149581, 'zhCN', '到此为止了，女妖之王！', '', 28153),
(149580, 'zhCN', '<库亚冯把头埋在翅膀里，轻轻啜泣。>', '', 28153),
(149579, 'zhCN', '', '杀戮时刻！', 28153),
(149577, 'zhCN', '[PH]让他们付出代价，$p。', '', 28153),
(149575, 'zhCN', '', '你想怎么样？它刚孵出来，肯定要吃东西。去兽栏找点肉来。\n', 28153),
(149574, 'zhCN', '召唤惊雷！', '', 28153),
(149573, 'zhCN', '', '我能听见。寄生虫的肺挺好。\n\n为什么你看起来这么害怕？', 28153),
(149571, 'zhCN', '<茫然地望着你。>', '<茫然地望着你。>', 28153),
(149570, 'zhCN', '我什么都没说。', '我什么都没说。', 28153),
(149569, 'zhCN', '给我一枚金币吧？', '给我一枚金币吧？', 28153),
(149568, 'zhCN', '你真是个长相奇怪的巨魔。', '你真是个长相奇怪的巨魔。', 28153),
(149567, 'zhCN', '……干嘛？', '……干嘛？', 28153),
(149566, 'zhCN', '你挡住我的视线了。', '你挡住我的视线了。', 28153),
(149565, 'zhCN', '<打嗝。>', '<打嗝。>', 28153),
(149564, 'zhCN', '<说出暗号。>', '<说出暗号。>', 28153),
(149563, 'zhCN', '你想要什么？', '你想要什么？', 28153),
(149562, 'zhCN', '海龟汤还没有$r汤一半的美味。\n\n去找点泥虫肉块，别管那些小海龟了。\n\n改天再来，我们还可以研究一下熬汤的其它原料！', '', 28153),
(149561, 'zhCN', '来点海龟汤？', '来点海龟汤？', 28153),
(149560, 'zhCN', '为了塞塔里斯！', '', 28153),
(149559, 'zhCN', '无信者挡住了我们寻找柯泰克大帝的道路，我们必须摧毁屏障！', '', 28153),
(149558, 'zhCN', '好了，听着！玛尔吉的车间需要人帮忙，好像是什么的零件……呃，这不属于我的专业范围，好么？', '', 28153),
(149557, 'zhCN', '干得漂亮。这份智慧对于我们至关重要。还有，我也不知道这次的暗号是谁想出来的。', '', 28153),
(149556, 'zhCN', '我们的间谍已经潜入了赞达拉的首都，但需要你去把他们的报告拿回来。与流浪者谈一谈。我们的间谍会回应你的暗号。', '', 28153),
(149555, 'zhCN', '呃，我们的基地附近出现了几个食人魔，他们好像不太开心。女士们先生们，拿起武器！', '', 28153),
(149554, 'zhCN', '在这里你只能找到阿昆达。只有那些使用他名号的人才能进入他的大厅。', '', 28153),
(149553, 'zhCN', '你们是来寻求救赎的吗？阿昆达欢迎所有人。', '', 28153),
(149552, 'zhCN', '', '我们在寻找一个名叫莱克拉的流亡者。我们认为她可能就在这座神殿里。', 28153),
(149551, 'zhCN', '', '我先去，万一有金子。', 28153),
(149550, 'zhCN', '', '我们刚登陆时，想谋求和平，但德鲁斯特立刻开战了。只有少数人接受了我们这些新邻居。', 28153),
(149549, 'zhCN', '', '等等，这上面画的是库尔提拉斯人早期的定居点，被摧毁的定居点之一。', 28153),
(149548, 'zhCN', '我会和毛卡说的。', '我会和毛卡说的。', 28153),
(149547, 'zhCN', '很好，我们都到齐了。', '', 28153),
(149545, 'zhCN', '嘿，伙计。', '', 28153),
(149544, 'zhCN', '', '我们又见面了，朋友。', 28153),
(149543, 'zhCN', '', '这个世界无法承受米斯拉克斯带来的毁灭。', 28153),
(149542, 'zhCN', '让他走吧，泰莉亚！', '', 28153),
(149541, 'zhCN', '', '萨缪尔，不！', 28153),
(149540, 'zhCN', '为了艾丁顿！为了斯托颂谷地！', '', 28153),
(149539, 'zhCN', '那些混账会为他们的所作所为付出代价！', '', 28153),
(149538, 'zhCN', '', '加卡泽罪有应得。', 28153),
(149537, 'zhCN', '我们与你同在。为了风暴之末！', '', 28153),
(149535, 'zhCN', '', '我已经为你集结了一支队伍。去拿回我的奖品吧。', 28153),
(149533, 'zhCN', '我看到更多的叛教者。很好，或许我们还没有全盘皆输。', '', 28153),
(149532, 'zhCN', '如果他们已混入我们当中，那舰队处境就相当危险了。', '', 28153),
(149531, 'zhCN', '大多数人认为他们只是传说，故事里总是用他们来警告我们不要窥探魔法。', '', 28153),
(149530, 'zhCN', '那些……东西……是克熙尔。他们来自海潮之下最黑暗的角落。', '', 28153),
(149529, 'zhCN', '', '', 28153),
(149528, 'zhCN', '您有什么吩咐，大酋长。', '您有什么吩咐，大酋长。', 28153),
(149527, 'zhCN', '', '贝恩，把他们撤回来！', 28153),
(149526, 'zhCN', '', '你要使用遥控指示器让艾力四处移动。把他派去地上颤动的地方，他会引出那些蠕虫！', 28153),
(149525, 'zhCN', '我们试图保护自己，抵抗它们，但恐怕我们已经失败了。', '', 28153),
(149523, 'zhCN', '慢慢地，这些低语声……变了。时而冷酷苛刻，时而残暴无情。', '', 28153),
(149522, 'zhCN', '长久以来，我的教派听从大海的声音来指引船只和人民。这些低语，大部分人是感知不到的。', '', 28153),
(149521, 'zhCN', '附近有座桥，我们可以从那儿看到风暴神殿的情况，预兆就是自此出现的。', '', 28153),
(149520, 'zhCN', '我会享受碾碎你的过程。', '', 28153),
(149519, 'zhCN', '', '小心拿着那东西，否则就得去跟外面那些废物打上一架了。不过如果你真想打架的话，就尽情的烧吧，宝贝。', 28153),
(149518, 'zhCN', '你这个蠢货。你死定了。', '', 28153),
(149517, 'zhCN', '这些囚犯属于赞达拉巨魔！', '', 28153),
(149516, 'zhCN', '哈哈哈！', '', 28153),
(149515, 'zhCN', '你死定了！', '', 28153),
(149514, 'zhCN', '渺小的联盟。', '', 28153),
(149513, 'zhCN', '我要撕碎你！', '', 28153),
(149512, 'zhCN', '你想接受审讯吗？', '', 28153),
(149511, 'zhCN', '新鲜的肉！', '', 28153),
(149510, 'zhCN', '那东西……安全吗？我愿意冒这个险！', '那东西……安全吗？我愿意冒这个险！', 28153),
(149509, 'zhCN', '快把我弄出去！', '快把我弄出去！', 28153),
(149508, 'zhCN', '潮汐之母啊……我们变成了什么怪物？', '', 28153),
(149507, 'zhCN', '你的时机无可挑剔！', '你的时机无可挑剔！', 28153),
(149506, 'zhCN', '那是……钻探机吗？', '那是……钻探机吗？', 28153),
(149505, 'zhCN', '我不想去地下……但更害怕这些巨魔！', '我不想去地下……但更害怕这些巨魔！', 28153),
(149504, 'zhCN', '谢谢你，谢谢你！', '谢谢你，谢谢你！', 28153),
(149503, 'zhCN', '你来的时机刚刚好！', '你来的时机刚刚好！', 28153),
(149502, 'zhCN', '我以为他们会吃了我！', '我以为他们会吃了我！', 28153),
(149501, 'zhCN', '指挥官，大酋长要求你的岗哨做好准备，迎接一支即将到来的军队。', '指挥官，大酋长要求你的岗哨做好准备，迎接一支即将到来的军队。', 28153),
(149500, 'zhCN', '我们要给大酋长的舰队腾出空间，你能去清理一下码头吗？', '我们要给大酋长的舰队腾出空间，你能去清理一下码头吗？', 28153),
(149499, 'zhCN', '大酋长需要为即将到来的部队准备粮草和营地。', '大酋长需要为即将到来的部队准备粮草和营地。', 28153),
(149498, 'zhCN', '你是说，和大酋长在一起的士兵有两百名？我会做好岗哨的迎接工作的。', '', 28153),
(149497, 'zhCN', '一切为了大酋长，我会马上召集卫兵去清理码头。胜利属于部落，朋友。', '', 28153),
(149496, 'zhCN', '', '大酋长的军队需要休整和给养？我们的储备应该可以满足需要，去年是丰春暖冬。', 28153),
(149495, 'zhCN', '她在杀死自己的部队……', '', 28153),
(149494, 'zhCN', '我来帮忙。我知道是什么让他如此痛苦。', '', 28153),
(149493, 'zhCN', '送我回暴风城。（返回/重新开始场景战役）', '送我回暴风城。（返回/重新开始场景战役）', 28153),
(149492, 'zhCN', '送我去祖达萨。（跳过前置场景。）', '送我去祖达萨。（跳过前置场景。）', 28153),
(149491, 'zhCN', '', '我们海军的很多船只都毁在了燃烧军团或联盟手里。我让我们的码头管理员加班加点，但我们还需要更多。', 28153),
(149490, 'zhCN', '停下。', '', 28153),
(149489, 'zhCN', '我是戈霍恩的……代言人。他会……引领一切。你……会臣服……然后死去。', '', 28153),
(149488, 'zhCN', '来吧。', '', 28153),
(149487, 'zhCN', '这个洛阿神灵的躯壳……滋养着我。滋养着……戈霍恩。', '', 28153),
(149486, 'zhCN', '你想……阻止……戈霍恩。你会……失败……并且受苦。', '', 28153),
(149485, 'zhCN', '对……挣扎吧……抵抗吧……戈霍恩渴望……你的痛苦。', '', 28153),
(149484, 'zhCN', '你的力量……毫无意义。我是……无敌的。', '', 28153),
(149483, 'zhCN', '你的力量……没有用……我是……无……什么？不。不！', '', 28153),
(149482, 'zhCN', '这……没有……意义！他会……再次……得到躯壳。封印……必将粉碎……戈霍恩……必将……重获自由！', '', 28153),
(149481, 'zhCN', '慢着……这是地下室里的吗？', '', 28153),
(149480, 'zhCN', '', '祝你好运。', 28153),
(149479, 'zhCN', '', '他们的巡逻队刚刚走过。你应该可以过去了。', 28153),
(149478, 'zhCN', '', '', 28153),
(149477, 'zhCN', '', '无信者根本不知道攻击来自何方。', 28153),
(149476, 'zhCN', '', '', 28153),
(149475, 'zhCN', '你追逐孩子们的时候，他们嬉笑着躲开了。', '你追逐孩子们的时候，他们嬉笑着躲开了。', 28153),
(149474, 'zhCN', '|TInterface\\Icons\\SPELL_NATURE_EARTHQUAKE:20|t%s瞄准|cFFFF0000$n|r施放|cFFFF0000|Hspell:257617|h[颠覆之击]|h|r！散开！', '', 28153),
(149473, 'zhCN', '我本以为可以消灭翼手龙，占据山坡上的有利位置，但我们却一个个被轻松地干掉了。\n', '我本以为可以消灭翼手龙，占据山坡上的有利位置，但我们却一个个被轻轻松松地干掉了。\n', 28153),
(149472, 'zhCN', '我不介意，女士。', '', 28153),
(149471, 'zhCN', '', '我不太喜欢演讲，所以我会尽量简短些。谢谢你。斯托颂谷地将永远是你的盟友。', 28153),
(149470, 'zhCN', '', '无意冒犯，卡尔文。', 28153),
(149469, 'zhCN', '', '将野猪人赶出去，穿过农场，深入沼泽腹地。拯救镇民和农民……你所做的比那些民兵能为我们……或者说应该为我们做的多太多了。', 28153),
(149468, 'zhCN', '', '我就不说那些冠冕堂皇的话了，朋友。反正我本来就不太擅长。', 28153),
(149466, 'zhCN', '赞达拉巨魔用舰船运输他们的战俘。我们决不能容忍！使用黑铁矮人的钻探机，把他们从刑讯和死亡中救出来。', '', 28153),
(149465, 'zhCN', '', '我们必须把那些攻击计划交到基罗手里。不能再浪费时间了，我们走！', 28153),
(149464, 'zhCN', '', '她说得对，阿罗姆·维克雷斯的确因为战功被封为勋爵。', 28153),
(149463, 'zhCN', '', '呃，如果我们执行命令，这些怪物就无法到达阿罗姆之台。来帮把手吧。', 28153),
(149462, 'zhCN', '', '她以为我们是她的民兵……', 28153),
(149461, 'zhCN', '', '血祭必须终结！这是阻止血神的第一步。', 28153),
(149460, 'zhCN', '', '祖纳兹曼的黑暗仪式将腐化散播到这片土地中，让死去的灵魂复生！净化那些遗体，让余下的灵魂安息吧！', 28153),
(149459, 'zhCN', '血……神……呃啊！', '血……神……呃啊！', 28153),
(149458, 'zhCN', '去阿图阿曼和我会合。其他人都在里面等你！', '', 28153),
(149457, 'zhCN', '他在召唤我们……', '他在召唤我们……', 28153),
(149456, 'zhCN', '看来我们的驭风者遇到麻烦了。检查战场，寻找幸存者！', '', 28153),
(149455, 'zhCN', '走开！', '走开！', 28153),
(149454, 'zhCN', '不不不！', '不不不！', 28153),
(149453, 'zhCN', '从我脑子里滚出去！', '从我脑子里滚出去！', 28153),
(149452, 'zhCN', '啊！', '啊！', 28153),
(149451, 'zhCN', '住手！', '住手！', 28153),
(149450, 'zhCN', '我希望无信者可以安于和平。我们曾经一直如此。\n\n但他们无情的攻击最终使得我们不得不采取行动。\n\n我们要消灭柯泰克大帝……我们还要沿路收集可用的东西。', '', 28153),
(149449, 'zhCN', '', '|TInterface\\Icons\\SPELL_MAGE_FLAMEORB:20|t快点将弹药桶移开火焰，以防%s炸掉它们！', 28153),
(149448, 'zhCN', '先锋军！准备支援维克雷斯上校！', '先锋军！准备支援阿罗姆上校！', 28153),
(149447, 'zhCN', '为了德鲁斯瓦，为了库尔提拉斯！', '为了德鲁斯瓦，为了库尔提拉斯！', 28153),
(149446, 'zhCN', '他们夺走了我们的儿女！让他们血债血偿！', '他们夺走了我们的儿女！让他们血债血偿！', 28153),
(149445, 'zhCN', '这是“光宗耀祖”的时刻！', '这是“光宗耀祖”的时刻！', 28153),
(149444, 'zhCN', '我们把他们击退了！继续！', '我们把他们击退了！继续！', 28153),
(149443, 'zhCN', '挺住！', '挺住！', 28153),
(149442, 'zhCN', '我们把敌人击退了！\n\n别站在那里，快去战斗！', '我们把敌人击退了！\n\n别站在那里，快去战斗！', 28153),
(149441, 'zhCN', '接触到%s之后，邪恶之云开始翻腾！', '接触到%s之后，邪恶之云开始翻腾！', 28153),
(149440, 'zhCN', '谢谢你……', '谢谢你……', 28153),
(149439, 'zhCN', '终于……可以安息了……', '终于……可以安息了……', 28153),
(149438, 'zhCN', '我的守望终结了……', '我的守望终结了……', 28153),
(149437, 'zhCN', '我可以……休息了……', '我可以……休息了……', 28153),
(149436, 'zhCN', '我的使命结束了……', '我的使命结束了……', 28153),
(149435, 'zhCN', '我会去找肉的。', '我会去找肉的。', 28153),
(149434, 'zhCN', '这个盒子是我的，你这个爱管闲事的$r。\n\n我需要泥虫肉块来做泥虫汤，但是虫子们都躲起来了！我可是很有耐心的，我能在这里再等几天，也许还能找到其它的盒子？\n\n你给我找一些泥虫肉块来，我就拿这个盒子跟你换。', '不，箱子是我的！\n\n我来这里找虫子做汤。有些始祖龟说海蟹肉做汤好喝，但我不同意。蟹肉汤根本不值得费力去和一个陌生人做朋友。\n\n而泥虫汤可以建立起持续一生的深厚友谊，我们始祖龟的一生可是很长的。\n\n给我找点泥虫肉块来，我会考虑把箱子给你。', 28153),
(149433, 'zhCN', '那个盒子？', '那个盒子？', 28153),
(149432, 'zhCN', '我在这里站了很久。然后我在泥里发现了这个有趣的箱子。', '我在这里站了很久。然后我在泥里发现了这个有趣的箱子。', 28153),
(149431, 'zhCN', '干得好，伙计。我……发疯了，我的灵魂变得枯萎了，像始祖龟一样迟缓！', '干得好，伙计。我……发疯了，我的灵魂变得枯萎了，像始祖龟一样迟缓！', 28153),
(149430, 'zhCN', '感谢你，陌生人。', '感谢你，陌生人。', 28153),
(149429, 'zhCN', '终于结束了。谢谢你。\n', '终于结束了。谢谢你。\n', 28153),
(149428, 'zhCN', '我又可以安息了，谢谢你，异乡人。', '我又可以安息了，谢谢你，异乡人。', 28153),
(149427, 'zhCN', '结束了……', '结束了……', 28153),
(149426, 'zhCN', '有什么计划？', '有什么计划？', 28153),
(149425, 'zhCN', '', '我在考虑电击或者火烧，也许直接把他炸死！\n\n但是杀死始祖龟会带来厄运，而我已经够倒霉了。\n\n所以，让我来看看你会怎么处理这个始祖龟吧？', 28153),
(149424, 'zhCN', '', '我们有麻烦了，$p。那只始祖龟找到一个箱子，而我们也想要！', 28153),
(149423, 'zhCN', '该死的沼泽！这里太潮湿了，什么东西都受不了！\n\n好吧，你需要什么？有事快说，我还有东西要修。', '该死的沼泽！这里太潮湿了，什么东西都受不了！\n\n好吧，你需要什么？有事快说，我还有东西要修。', 28153),
(149422, 'zhCN', '', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149421, 'zhCN', '只有最傲慢的蠢货才会以为将阿曼尼留在高墙之内是个明智的决定。你今天做得很好，勇士。', '', 28153),
(149420, 'zhCN', '只有死透的阿曼尼看上去才顺眼，然而赞达拉巨魔居然让他们在城市里建立了难民营。击溃他们，为了联盟！', '', 28153),
(149419, 'zhCN', '那头野兽死了！艾什凡，去占领上层！我来对付这个小偷……', '那头野兽死了！艾什凡，去占领上层！我来对付这个小偷……', 28153),
(149418, 'zhCN', '只要我还活着，就不会让这座堡垒陷落！', '', 28153),
(149417, 'zhCN', '这应该能让他们清楚自己的地位。', '', 28153),
(149416, 'zhCN', '<向柯拉姆出示乐石。>', '<向柯拉姆出示乐石。>', 28153),
(149415, 'zhCN', '阿曼尼部族会好好记住部落在祖达萨的实力的。要不你去给他们加深一下印象？去敲响他们的大锣，然后击败他们的信徒。', '', 28153),
(149414, 'zhCN', '我会继续前行，寻找那些农夫。你可千万不要被抓住！', '', 28153),
(149413, 'zhCN', '', '漂亮！', 28153),
(149411, 'zhCN', '这片泥地里可有不少宝贝呢。你和莫克希要合作把它们找出来！', '', 28153),
(149410, 'zhCN', '不，抱齿兽……不能释放它们……', '', 28153),
(149409, 'zhCN', '战斗吧！', '战斗吧！', 28153),
(149408, 'zhCN', '为了部落！', '为了部落！', 28153),
(149407, 'zhCN', '我们要并肩战斗。', '我们要并肩战斗。', 28153),
(149406, 'zhCN', '我同你一起战斗。', '我同你一起战斗。', 28153),
(149405, 'zhCN', '我欠你一份情，$n。', '我欠你的人情，$n。', 28153),
(149404, 'zhCN', '仪式还没有完成，必须制服这些抱齿兽！', '', 28153),
(149403, 'zhCN', '加强进攻。我能照顾好自己。', '', 28153),
(149402, 'zhCN', '', '我的力量……这是什么……？', 28153),
(149401, 'zhCN', '', '我的身体……我不能……啊!', 28153),
(149400, 'zhCN', '好吧。', '好吧。', 28153),
(149399, 'zhCN', '', '工人们说他们在泥地里听到了声音。这些声音让其中有些人发了疯！\n\n我就当没听见！', 28153),
(149398, 'zhCN', '', '有些库尔提拉斯人好像把我和某些抢劫案联系在了一起，可我真的一无所知。', 28153),
(149397, 'zhCN', '', '我会驶向……未知的海域……', 28153),
(149396, 'zhCN', '', '这家伙的反应就好像从来没见过侏儒！', 28153),
(149395, 'zhCN', '', '我受够了！', 28153),
(149394, 'zhCN', '', '屠戮者弹药……发射！', 28153),
(149393, 'zhCN', '', '一枪射进你的内脏！', 28153),
(149392, 'zhCN', '', '我要把你剁成碎片！', 28153),
(149391, 'zhCN', '', '扫清甲板！', 28153),
(149390, 'zhCN', '赞达拉巨魔……满嘴虚假的承诺。', '赞达拉巨魔……满嘴虚假的承诺。', 28153),
(149389, 'zhCN', '我的神灵会因此惩罚你们的……', '我的神灵会因此惩罚你们的……', 28153),
(149388, 'zhCN', '我们已经没有安全的地方了。', '我们已经没有安全的地方了。', 28153),
(149387, 'zhCN', '在他们自己的城市里……任由我们死去。', '在他们自己的城市里……任由我们死去。', 28153),
(149386, 'zhCN', '我们现在该怎么办？', '我们现在该怎么办？', 28153),
(149385, 'zhCN', '帝国……真的陷落了。', '帝国……真的陷落了。', 28153),
(149384, 'zhCN', '他们怎么会允许这种事……发生？', '他们怎么会允许这种事……发生？', 28153),
(149383, 'zhCN', '赞达拉巨魔……保证过我们的安全……', '赞达拉巨魔……保证过我们的安全……', 28153),
(149382, 'zhCN', '终于！有人找到了我为邦桑迪奉献的供品了！好好利用它吧！', '终于！有人找到了我为邦桑迪奉献的供品了！好好利用它吧！', 28153),
(149381, 'zhCN', '', '把他们的徽记给我带来！其他的随你们处置！', 28153),
(149380, 'zhCN', '', '如果你死了，我就拿走你的那一份！', 28153),
(149379, 'zhCN', '', '你的脑袋会成为一件不错的收藏品。', 28153),
(149378, 'zhCN', '', '我们现在已经算是朋友啦。我能向你借点钱吗？', 28153),
(149377, 'zhCN', '', '我在托尔达戈见过一个和你看起来很像的人。', 28153),
(149376, 'zhCN', '你们犯了一个大错！', '你们犯了一个大错！', 28153),
(149375, 'zhCN', '来人！平台受到攻击！', '来人！平台受到攻击！', 28153),
(149374, 'zhCN', '干掉他们！', '干掉他们！', 28153),
(149373, 'zhCN', '你不属于这里，伙计！', '你不属于这里，伙计！', 28153),
(149372, 'zhCN', '滚开！赞达拉属于巨魔！', '滚开！赞达拉属于巨魔！', 28153),
(149371, 'zhCN', '我就知道我闻到了什么臭味……', '我就知道我闻到了什么臭味……', 28153),
(149370, 'zhCN', '救命！我受到了攻击！', '救命！我受到了攻击！', 28153),
(149369, 'zhCN', '肮脏的杂种！', '肮脏的杂种！', 28153),
(149368, 'zhCN', '可达絮絮叨叨地说着，望向峡谷。', '', 28153),
(149367, 'zhCN', '', '我也很担心，可达。', 28153),
(149366, 'zhCN', '我要去东点哨站。', '我要去东点哨站。', 28153),
(149365, 'zhCN', '', '你要去哪里？', 28153),
(149364, 'zhCN', '', '谢谢你！还有，请多多拥抱可达！', 28153),
(149363, 'zhCN', '', '所有火炮……发射！', 28153),
(149362, 'zhCN', '船厂会成为你们的新家。', '', 28153),
(149361, 'zhCN', '你们都会进船厂工作，为斯托颂勋爵效力。', '', 28153),
(149360, 'zhCN', '大家都进马车。', '', 28153),
(149359, 'zhCN', '鲜血巨魔又来威胁我的孩子们了！$B$B来吧，小家伙，我们一起让他们记住，激怒卡格瓦会有什么后果！', '', 28153),
(149358, 'zhCN', '', '大伙儿，这座城市归我们了！', 28153),
(149357, 'zhCN', '', '我要把你们吊在桅杆上！', 28153),
(149356, 'zhCN', '', '刀上又多了个缺口！', 28153),
(149355, 'zhCN', '', '全体船员……攻击！', 28153),
(149354, 'zhCN', '', '不留活口！', 28153),
(149353, 'zhCN', '他们的等待快要结束了。', '', 28153),
(149352, 'zhCN', '要多久？', '要多久？', 28153),
(149351, 'zhCN', '铁潮海盗每天都袭击我们，部落的军队也正朝这边赶来。用不了多久，恐怕整个镇上的人就都得逃走。', '', 28153),
(149348, 'zhCN', '我会完成仪式的！', '', 28153),
(149347, 'zhCN', 'O.K.', 'O.K.', 28153),
(149346, 'zhCN', '失败？不……', '', 28153),
(149345, 'zhCN', '那个泥泞的湖底有着媲美一个王国财富的黄金。是一艘第二次大战时沉没的载有宝物的船！\n\n整座城镇都在齐心协力，想率先找到宝藏呢！时间紧迫，我们得加把劲！', '', 28153),
(149344, 'zhCN', 'Lith qul\'shoth wshh……yzsh uovssh qvask。', '', 28153),
(149343, 'zhCN', '', '结束了，加卡泽。你的计划失败了！', 28153),
(149341, 'zhCN', '你在上面挣扎……他却在下面等待。', '', 28153),
(149340, 'zhCN', '', '正好可以阻止你！', 28153),
(149339, 'zhCN', '你来得太及时了……', '', 28153),
(149338, 'zhCN', '', '耶！他们都跑回家了！', 28153),
(149337, 'zhCN', '仪式就快要完成了！', '', 28153),
(149336, 'zhCN', '', '请快点找到他们！如果可达失去家人，他会很难过的。', 28153),
(149335, 'zhCN', '宝物？', '宝物？', 28153),
(149334, 'zhCN', '铁潮海盗正在抓捕每一个人。他们打算阻止我们率先找到宝藏！', '', 28153),
(149333, 'zhCN', '', '回来，小家伙们！我们可以帮助你们！', 28153),
(149332, 'zhCN', '', '如果我们进去，那些蜜蜂会把我们也杀死的！', 28153),
(149331, 'zhCN', '', '我看不见他们，可达！', 28153),
(149330, 'zhCN', 'Zaix lal sk\'woth\'gl Zaix lal uulwi', '', 28153),
(149329, 'zhCN', '铁潮海盗正在抓捕每一个人，我们需要你的帮助！', '', 28153),
(149328, 'zhCN', '他们是救赎。他们是真理。', '', 28153),
(149327, 'zhCN', 'Zuq wgah nuq iilth zz oou ga\'halahs anagg', '', 28153),
(149326, 'zhCN', '你们都会淹没在黑暗的深渊中。', '', 28153),
(149325, 'zhCN', '', '如果没爆炸，就再试一次。', 28153),
(149323, 'zhCN', '我不赞同。我奉命直接带你去见大酋长。', '', 28153),
(149322, 'zhCN', '', '鉴于这是我的船，我觉得你该调整计划了。', 28153),
(149321, 'zhCN', '我们可以在路上讨论这个问题，殿下。', '', 28153),
(149320, 'zhCN', '', '来吧，我们向祖达萨起航。', 28153),
(149319, 'zhCN', '我想你应该说一声“谢谢。”', '', 28153),
(149318, 'zhCN', '看起来你的魔法……专精……在这种情况下非常有用，不是吗？', '', 28153),
(149317, 'zhCN', '', '不……这不可能。', 28153),
(149315, 'zhCN', '你可以尝试干掉我们，这你应该办得到。', '', 28153),
(149314, 'zhCN', '看啊，大火正在吞噬你们的城市。', '', 28153),
(149313, 'zhCN', '别那么心急，等一等。', '', 28153),
(149312, 'zhCN', '', '那就死吧。', 28153),
(149311, 'zhCN', '无意冒犯，但我们还有一班船要赶。', '', 28153),
(149310, 'zhCN', '', '投降吧，我会把你们送回监狱。你们会在那里接受国王的审判。', 28153),
(149309, 'zhCN', '等等。', '', 28153),
(149307, 'zhCN', '我早就想到了。等着瞧。', '', 28153),
(149306, 'zhCN', '别傻看着了，快打碎冰墙！', '', 28153),
(149305, 'zhCN', '我不认识莱赞，但我由衷感谢他。', '', 28153),
(149303, 'zhCN', '', '死吧，部落渣滓！', 28153),
(149302, 'zhCN', '', '她挡住了我们的去路！', 28153),
(149300, 'zhCN', '', '我需要二十只这样的鸟。', 28153),
(149299, 'zhCN', '啊哈！拉善，你这个聪明的家伙！', '', 28153),
(149298, 'zhCN', '不……但我想我知道为什么。快看。', '', 28153),
(149297, 'zhCN', '愿洛阿神灵保佑他们，祖尔。', '', 28153),
(149296, 'zhCN', '', '你们杀了很多无辜的人才走到这里。但你们的越狱小把戏结束了。', 28153),
(149295, 'zhCN', '', '他们不追上来吗？', 28153),
(149294, 'zhCN', '哈哈哈哈！', '', 28153),
(149292, 'zhCN', '', '他们的大军肯定从洛丹伦回来了。我们要如何才能突破重围？', 28153),
(149291, 'zhCN', '我们走！', '', 28153),
(149290, 'zhCN', '', '我的神灵，倾听祈祷吧。伟大的莱赞，请将力量借给我！', 28153),
(149289, 'zhCN', '', '你别想再伤害这个城市里的人！', 28153),
(149288, 'zhCN', '', '给我站住！', 28153),
(149287, 'zhCN', '小心脚下。看来联盟那位尽善尽美的外交家这次不想留活口了。', '', 28153),
(149286, 'zhCN', '呀！', '', 28153),
(149285, 'zhCN', '', '你找到我妈妈了！谢谢你把她从可怕的怪物手上救回来！', 28153),
(149284, 'zhCN', '', '谢谢你把我的玩具带来。如果看到我的妈妈，能让她回家吗，求你了。\n\n我好久没看到她了。', 28153),
(149283, 'zhCN', '现在。解开最终的封印。', '', 28153),
(149282, 'zhCN', '', '塔兰吉，你和你的勇士去追踪祖尔。我会尽力召集人手，尽我所能拖住拆解者。要打败那个家伙得有一支军队才行。', 28153),
(149281, 'zhCN', '他控制着米斯拉克斯。我们必须阻止黑暗帝国的仆从。', '', 28153),
(149280, 'zhCN', '', '勇士，我会和神灵一起尽量拖住米斯拉克斯。找到我的父王，把祖尔干掉！', 28153),
(149279, 'zhCN', '来吧，米斯拉克斯。来吧，拆解者。最后的封印必须被破坏。', '', 28153),
(149278, 'zhCN', '道路打开了，小家伙们。快走。米斯拉克斯要来了。', '', 28153),
(149277, 'zhCN', '', '赞达拉的兄弟姐妹们，让我们夺回我们的家园！前进，冲啊！', 28153),
(149276, 'zhCN', '', '勇士，去寻找滞留在佐卡罗广场的平民，把他们送到这里来。我们会在有能力一战时继续前进。', 28153),
(149275, 'zhCN', '', '很糟糕。我们被夹击了。洛阿神灵在尽其所能，我们需要集结所有还能作战的巨魔。', 28153),
(149274, 'zhCN', '', '非常时期得用非常手段。情况怎么样了？', 28153),
(149273, 'zhCN', '', '塔兰吉，原来是你在骑着洛阿作战。', 28153),
(149272, 'zhCN', '', '莱克拉，原来是你在指挥我们的军队。', 28153),
(149271, 'zhCN', '', '列阵！弓箭手准备。', 28153),
(149270, 'zhCN', '', '好吧……那真是……棘手。', 28153),
(149269, 'zhCN', '', '这位勇士报告说，拆解者米斯拉克斯已经复活。', 28153),
(149268, 'zhCN', '', '有东西在驱使这些蛇人发动攻击。他们的数量从没这么多。', 28153),
(149267, 'zhCN', '', '当心，父王。敌人在我们背地里计划了很久。', 28153),
(149266, 'zhCN', '塔兰吉，带上这位勇士，集结我们的军队。我将和卡格瓦一起去守卫碎枝林地。', '', 28153),
(149265, 'zhCN', '', '拉斯塔哈！沃顿的蛇人袭击了你们西面的边境。快点想想办法。', 28153),
(149264, 'zhCN', '敌人太多了。朝通往达萨罗的大桥移动。把他们逼入咽喉点。', '', 28153),
(149263, 'zhCN', '给老邦桑迪的礼物。', '', 28153),
(149262, 'zhCN', '死吧，入侵者！', '', 28153),
(149261, 'zhCN', '敌人太多了。', '', 28153),
(149260, 'zhCN', '鲜血关口被占领了。快，我们必须在入侵者抵达城市之前尽量多解决几个。', '', 28153),
(149259, 'zhCN', '', '你阻止不了……风暴……', 28153),
(149258, 'zhCN', '', '你阻止不了无信者帝国！', 28153),
(149257, 'zhCN', '我会自己离开的。你小心点！', '', 28153),
(149256, 'zhCN', '祝福你……我还以为死定了。', '', 28153),
(149255, 'zhCN', '这样应该可以了。一个人把整座城市变成了马蜂窝，感觉如何，$n？', '', 28153),
(149254, 'zhCN', '跑……快跑！！！', '', 28153),
(149253, 'zhCN', '还不是时候。他还没有屈服于主人的荣耀！', '', 28153),
(149252, 'zhCN', '不不不！整个城镇都被惊动了！我们得离开这里。', '', 28153),
(149250, 'zhCN', '试试看用我放在你口袋里的匕首。我想你会喜欢的。', '', 28153),
(149249, 'zhCN', '你先走，$n。标记安全的目标，我会去把他们干掉。', '', 28153),
(149248, 'zhCN', '信任一旦被打破，就难以修复。这会侵蚀赞达拉巨魔的统治。做得好，勇士。', '', 28153),
(149247, 'zhCN', '一些巨魔小部族的代表正团结在赞达拉的保护伞之下，但他们十分脆弱。消灭他们，在我们的敌人中散播不和的种子。', '', 28153),
(149246, 'zhCN', '烧掉他们的车，打断他们的骨头！', '烧掉他们的车，打断他们的骨头！', 28153),
(149245, 'zhCN', '如果这些蠕虫把钥匙藏了起来，我们会找到它的！', '如果这些蠕虫把钥匙藏了起来，我们会找到它的！', 28153),
(149244, 'zhCN', '别杀那些强壮的。他们能在市场上卖个好价钱。', '别杀那些强壮的。他们能在市场上卖个好价钱。', 28153),
(149243, 'zhCN', '搞定了吗？应该差不多搞定了吧！', '', 28153),
(149242, 'zhCN', '回到这里来！', '回到这里来！', 28153),
(149241, 'zhCN', '', '我们去西北的山上吧。阿罗姆之台应该是个发射信号的好地方。', 28153),
(149240, 'zhCN', '', '但我们走之前，应该利用优势，重创他们的部队！', 28153),
(149239, 'zhCN', '', '我们可以去西北边的高地发射信号，请求撤离。', 28153),
(149238, 'zhCN', '这太疯狂了！走慢点！', '', 28153),
(149237, 'zhCN', '我好喜欢它的震地践踏！', '', 28153),
(149236, 'zhCN', '', '拿女巫会自己的武器来对付她们还真爽。', 28153),
(149235, 'zhCN', '火焰会发出紫色烟雾。他们很快就能看到烟雾从树林里冒出来。', '', 28153),
(149234, 'zhCN', '首先，我会给其他人发信号，让他们开始突袭。', '', 28153),
(149233, 'zhCN', '不。他们还会回来找我们的。', '', 28153),
(149232, 'zhCN', '', '不追他们吗？', 28153),
(149231, 'zhCN', '不再和外来者讲条件……也不再和洛阿讨价还价。如今鲜血才是我们的道路……也就是戈霍恩的道路！', '', 28153),
(149230, 'zhCN', '我现在还不怎么饿。你晚点再来吧……', '', 28153),
(149229, 'zhCN', '如果我说这一切都在按计划进行，你会相信吗？我觉得你不信。', '', 28153),
(149228, 'zhCN', '好消息！我找到敌人的位置了！他们包围了我们。', '', 28153),
(149227, 'zhCN', '我们……我们能不能不告诉罗兹这件事？', '', 28153),
(149226, 'zhCN', '这下糗大了。', '', 28153),
(149225, 'zhCN', '我可以向你预言。巨魔帝国将像当初那样统治这个世界。而届时那位王者也会像当初那样登上王座，虽然我和你都活不到那一天了。但是我已经从我的神那里看到了这幅景象……', '', 28153),
(149224, 'zhCN', '你变得越来越僵化，老朋友。你让我们的帝国走向衰败。但是我已经预见到了巨魔帝国的再度崛起。', '', 28153),
(149223, 'zhCN', '你应该听塔兰吉的话。', '', 28153),
(149221, 'zhCN', '不！哈布图！', '', 28153),
(149220, 'zhCN', '哈！艺高人胆大！', '', 28153),
(149219, 'zhCN', '鲜血的时刻即将来临。', '', 28153),
(149218, 'zhCN', '神灵的时代……结束了。', '', 28153),
(149217, 'zhCN', '我不是你的信徒，', '', 28153),
(149216, 'zhCN', '莱赞啊莱赞……', '', 28153),
(149215, 'zhCN', '管好你的舌头，叛徒。', '', 28153),
(149214, 'zhCN', '啊，他来了，什么神来着……嗯……', '', 28153),
(149212, 'zhCN', '', '你的预言最好别出错。', 28153),
(149211, 'zhCN', '异教徒！', '', 28153),
(149210, 'zhCN', '', '提前预料同伴的下一步动作！', 28153),
(149209, 'zhCN', '', '像风一样发起攻击！格挡！', 28153),
(149208, 'zhCN', '', '训练没完成就不准停下！', 28153),
(149207, 'zhCN', '', '开始分组练习！发动攻击！', 28153),
(149206, 'zhCN', '指挥官！她……倒下了？！', '指挥官！她……倒下了？！', 28153),
(149205, 'zhCN', '姐妹，你没事吧？！我不是故意要这么用力的！', '姐妹，你没事吧？！我不是故意要这么用力的！', 28153),
(149204, 'zhCN', '我的天……我是不是……你没事吧？！', '我的天……我是不是……你没事吧？！', 28153),
(149200, 'zhCN', '没有什么能比干掉联盟指挥官更让人满足的了。而且还如此轻松……', '', 28153),
(149199, 'zhCN', '', '一路顺风，$n。', 28153),
(149198, 'zhCN', '', '灰烬骑士团再次挺身抗击高莱克·图尔。有了盟友的帮助，我们会继续高歌猛进。', 28153),
(149197, 'zhCN', '', '谢谢你帮我，$n。我可以向露希尔女士报告任务胜利完成了。', 28153),
(149196, 'zhCN', '真不敢想象，如果你和审判官没来，我大概已经玩完了。', '', 28153),
(149195, 'zhCN', '没死我就很满足了。', '', 28153),
(149194, 'zhCN', '', '如今飞越森林应该没危险了，希望他们能及时赶到。', 28153),
(149193, 'zhCN', '', '有狮鹫骑士正等着我们发信号。', 28153),
(149192, 'zhCN', '马虎，马虎，真马虎！下次别弄出声音！', '', 28153),
(149191, 'zhCN', '该死！我们得迅速且隐蔽。专心点！', '', 28153),
(149190, 'zhCN', '快点干掉这家伙，别让其他人发现我们！', '', 28153),
(149189, 'zhCN', '尽量别被发现！我们不能吸引太多注意……', '', 28153),
(149187, 'zhCN', '啊，不不。这个是我的。', '', 28153),
(149186, 'zhCN', '这事可和我没关系。我从来没杀过熟睡中的人。', '', 28153),
(149185, 'zhCN', '喂，对那些平民悠着点，这可能会让卫兵注意到我们。', '', 28153),
(149184, 'zhCN', '那不是守卫，但你要杀联盟我是不会拦你的。', '', 28153),
(149183, 'zhCN', '其实我们没必要杀掉那些平民……不过我喜欢你的方式。', '', 28153),
(149182, 'zhCN', '如此冷酷无情……我喜欢。', '', 28153),
(149181, 'zhCN', '我们的一名工程师在寻找备用零件时，在我们的矿洞附近看到了联盟的人。去车间找玛尔吉了解详细情况，还有……做好准备。', '', 28153),
(149180, 'zhCN', '胸口……我喘不上气了！', '胸口……我喘不上气了！', 28153),
(149179, 'zhCN', '我的喉咙……好干！', '我的喉咙……好干！', 28153),
(149178, 'zhCN', '我觉得我要生病了……', '我觉得我要生病了……', 28153),
(149177, 'zhCN', '我需要……歇一会儿……', '我需要……歇一会儿……', 28153),
(149176, 'zhCN', '一切都那么……暗……', '一切都那么……暗……', 28153),
(149175, 'zhCN', '我……感觉不对劲。', '我……感觉不对劲。', 28153),
(149174, 'zhCN', '不！不要啊！！', '', 28153),
(149173, 'zhCN', '什——什么？！', '', 28153),
(149172, 'zhCN', '你！站住！', '', 28153),
(149171, 'zhCN', '', '他们就像不要命了一样……我只希望他们的鲜血不会成为戈霍恩的养料。', 28153),
(149170, 'zhCN', '', '如果他们继续蔑视邦桑迪，是不会有好结果的。英雄，我们与死亡之神的契约仍然有效，将这些误入歧途的灵魂送回他身边！', 28153),
(149169, 'zhCN', '等等，不对。只不过是我的另一条腿。虚惊一场。', '', 28153),
(149168, 'zhCN', '我腿上有什么东西！', '', 28153),
(149167, 'zhCN', '老爷矿车平安无恙。来拿上你的份儿！', '', 28153),
(149166, 'zhCN', '我们的矿工好像撞大运了！如果你能把它完好无缺地运回基地，我们可就赚大了。', '', 28153),
(149165, 'zhCN', '', '走吧，我会密切关注你的。', 28153),
(149164, 'zhCN', '', '炸药永远不算多！', 28153),
(149163, 'zhCN', '', '你认识什么人傻钱多的库尔提拉斯贵族吗？', 28153),
(149162, 'zhCN', '', '$p，我正在寻找像你这样聪明的家伙来投资我新开发的业务。', 28153),
(149161, 'zhCN', '', '得有个侏儒帮她看着点这些库尔提拉斯人。', 28153),
(149160, 'zhCN', '', '如果有疑问，就炸了它。', 28153),
(149159, 'zhCN', '', '托尔巴拉德、托尔达戈、暴风城监狱，我都去过！', 28153),
(149158, 'zhCN', '发出信号。我们离开这里！', '发出信号。我们离开这里！', 28153),
(149157, 'zhCN', '', '求你了，莱克拉。别这么做！你会害死你自己的！', 28153),
(149156, 'zhCN', '', '感谢沙漠，你平安无事！', 28153),
(149155, 'zhCN', '', '你们的入侵到此为止了！别想打扰长母！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149154, 'zhCN', '这些小家伙看起来并不构成威胁，$r。', '', 28153),
(149151, 'zhCN', '', '你还活着，$p！你和我一样幸运。', 28153),
(149150, 'zhCN', '下回见。', '', 28153),
(149149, 'zhCN', '说完了？', '', 28153),
(149148, 'zhCN', '放轻松。', '', 28153),
(149147, 'zhCN', '别担心，朋友。', '', 28153),
(149146, 'zhCN', '你需要巫毒魔法吗？', '', 28153),
(149145, 'zhCN', '你想要什么？', '', 28153),
(149144, 'zhCN', '', '只要我还活着，鲜血巨魔就别想再对我们耍花样。', 28153),
(149143, 'zhCN', '', '鲜血巨魔想要偷袭我们。我有东西可以帮助你看到他们，利用它来消灭这些鲜血巨魔！', 28153),
(149142, 'zhCN', '调整呼吸。我们必须一直跑到船上。', '', 28153),
(149141, 'zhCN', '跑了！我跑了！', '跑了！我跑了！', 28153),
(149140, 'zhCN', '祖尔会杀死我们所有人。', '祖尔会杀死我们所有人。', 28153),
(149139, 'zhCN', '完蛋了！', '完蛋了！', 28153),
(149138, 'zhCN', '这对生意有害无益。', '这对生意有害无益。', 28153),
(149137, 'zhCN', '我要离开这里。', '我要离开这里。', 28153),
(149136, 'zhCN', '嘿！里面出什么事了？', '', 28153),
(149135, 'zhCN', '卫兵！卫兵！救命！噢！！', '', 28153),
(149134, 'zhCN', '啊！噢，大坏蛋！', '', 28153),
(149133, 'zhCN', '别害羞！使点劲。', '', 28153),
(149132, 'zhCN', '来啊，打我！', '', 28153),
(149131, 'zhCN', '打我。', '', 28153),
(149130, 'zhCN', '好吧，计划就是：', '', 28153),
(149129, 'zhCN', '记录三：我就快成功了！蜂群在壮大，并且产量得到成倍的增长。但我必须更加密切地观察蜂后。', '', 28153),
(149128, 'zhCN', '记录二：活化蜂蜜酒已经开始表现出侵略性。也许我的计算稍有失误。', '', 28153),
(149127, 'zhCN', '记录一：蜂蜜活了过来，但繁殖速度似乎超越了我的想象。我必须再做一些测试！', '', 28153),
(149126, 'zhCN', '快扑灭大火！拿下他们！', '', 28153),
(149125, 'zhCN', '看看他们，夹着尾巴逃窜！', '', 28153),
(149124, 'zhCN', '逃窜吧，你们这些老鼠！', '', 28153),
(149123, 'zhCN', '', '太愚蠢了。你会死在这里，只留下一座无名的坟墓。', 28153),
(149122, 'zhCN', '', '我知道部落都是残忍无情的。为了胜利不择手段。但这……？', 28153),
(149121, 'zhCN', '我发现他们了，国王！我会把他们的皮剥下来当战利品！', '', 28153),
(149120, 'zhCN', '别搞得好像不高兴见到我们一样。', '', 28153),
(149119, 'zhCN', '我很高兴。真的。现在，我们走吧。等你下令。', '', 28153),
(149118, 'zhCN', '', '你是个可怕的敌人，祖尔。', 28153),
(149117, 'zhCN', '', '我们不能与她纠缠。快跑！', 28153),
(149116, 'zhCN', '', '又怎么了？', 28153),
(149115, 'zhCN', '看来你们给我惹了场大麻烦。', '', 28153),
(149114, 'zhCN', '', '是港口！我们必须前进！', 28153),
(149113, 'zhCN', '有人还觉得石头建的城市不会那么容易……着火。', '', 28153),
(149112, 'zhCN', '他们想要包围我们。不能被他们逼入角落！', '', 28153),
(149111, 'zhCN', '我们最好留在这里。', '', 28153),
(149110, 'zhCN', '我们必须回到运河里。跟我来！', '', 28153),
(149109, 'zhCN', '看这个，应该会有用。', '', 28153),
(149108, 'zhCN', '', '我们得找掩护！', 28153),
(149107, 'zhCN', '', '小心！', 28153),
(149106, 'zhCN', '那头老狼闻到了我们的气味。快离开这里。', '', 28153),
(149105, 'zhCN', '', '他们数量太多了……屏障快坚持不住了！', 28153),
(149104, 'zhCN', '就是这样！阻止他们，别让他们到达大门！', '就是这样！阻止他们，别让他们到达大门！', 28153),
(149103, 'zhCN', '你以为你跑的掉吗？没那么容易！', '你以为你跑的掉吗？没那么容易！', 28153),
(149102, 'zhCN', '就在下面！把那些资源拿回来！', '就在下面！把那些资源拿回来！', 28153),
(149101, 'zhCN', '', '鲜血巨魔是病态和扭曲的生物。他们已经没有希望改变了。', 28153),
(149100, 'zhCN', '', '鲜血巨魔想要毁灭我的人民，你得去阻止他们！', 28153),
(149099, 'zhCN', '凶喙被骚动引来了！', '凶喙被骚动引来了！', 28153),
(149098, 'zhCN', '斧喙鸟被水中鱼饵的气味所吸引！', '斧喙鸟被水中鱼饵的气味所吸引！', 28153),
(149097, 'zhCN', '谢谢你，$c！我可不想被挂在长矛上示众。', '', 28153),
(149096, 'zhCN', '你来了！能帮我一把吗？', '', 28153),
(149095, 'zhCN', '你的行动力很棒，$c。我们会跟维克雷斯小姐汇合的。', '', 28153),
(149094, 'zhCN', '', '可以帮点忙吗？', 28153),
(149093, 'zhCN', '谢谢你的帮忙。', '', 28153),
(149092, 'zhCN', '诅咒那些女巫和她们的屏障！', '', 28153),
(149091, 'zhCN', '', '这些幼崽都做得很好。它们将来都会成为出色的战兽。', 28153),
(149090, 'zhCN', '', '年轻的战兽需要持续的关注和爱抚。它们必须学会与我们交流，就像我们必须学会跟它们交流一样。', 28153),
(149089, 'zhCN', '我听到了召唤！', '', 28153),
(149088, 'zhCN', '我失去了所有的武器，但至少我的命还在。', '', 28153),
(149087, 'zhCN', '他们趁着我侦察的时候偷袭我，不会再让他们这样了！', '', 28153),
(149086, 'zhCN', '我会回来的，要让这些鲜血巨魔付出代价！', '', 28153),
(149085, 'zhCN', '谢谢你，我这就回祖尔加去。', '', 28153),
(149084, 'zhCN', '', '谢谢你。那些地精最好能专心救援我的城市，而不是想尽办法捞上一笔！', 28153),
(149083, 'zhCN', '', '一队地精勘探员落入了亡灵的陷阱。我们必须营救他们！', 28153),
(149082, 'zhCN', '你知道这些焦油的用处吗？我也不知道，但听说能卖不少钱！', '', 28153),
(149081, 'zhCN', '这里全是坑，真的！我要离开这地方。', '', 28153),
(149080, 'zhCN', '好吧，反正我也打算要出去了，这些焦油可值不少钱！', '', 28153),
(149079, 'zhCN', '好险！嘿，帮我搞点焦油来，好吗？回去以后我们可以卖个好价钱。', '', 28153),
(149078, 'zhCN', '谢谢，谁能想到从禁忌沼泽里捞些焦油也会这么危险！', '', 28153),
(149076, 'zhCN', '柯泰克已经无可救药。我必须亲自解决这件事。在我离开后保护好钥匙。', '', 28153),
(149075, 'zhCN', '', '这应该能让鲜血巨魔们知道，他们的好日子就要到头了。', 28153),
(149074, 'zhCN', '', '地精小队有一个对付鲜血巨魔的计划。去看看你能做些什么，确保他们能活着回来。', 28153),
(149073, 'zhCN', '坐上灭世空战机甲，阻止鲜血巨魔大军。', '坐上灭世空战机甲，阻止鲜血巨魔大军。', 28153),
(149072, 'zhCN', '嘿！有群肮脏的鲜血巨魔在前往祖达萨。幸运的是，我们的灭世机甲升级了！\n\n好好看看灭世机甲的风采吧，这个宝贝会飞！天降死亡！\n\n当然了，我们必须把护盾拆掉，带着那东西可没法飞。\n\n你想试驾一下吗？我们可以把那支军队轰成渣！', '', 28153),
(149071, 'zhCN', '你一文不值……就像其他人一样……', '', 28153),
(149070, 'zhCN', '又有流亡者可杀了？今天是个好日子。', '', 28153),
(149066, 'zhCN', '去吧，小国王。有人想跟踪你的话，我就会把他吃掉。', '', 28153),
(149065, 'zhCN', '然而并不正常。', '', 28153),
(149064, 'zhCN', '', '祖尔没有害怕。这也许很正常。', 28153),
(149063, 'zhCN', '他们应该还没走远。你的警觉保护了我们所有人。', '', 28153),
(149062, 'zhCN', '部落渗透者已经突破了监狱！请居民们留在家中，直到威胁被清除！', '', 28153),
(149061, 'zhCN', '这是国王的命令！', '', 28153),
(149060, 'zhCN', '只要没人做傻事，我就能把大家都隐蔽起来。', '', 28153),
(149059, 'zhCN', '哈哈！别担心，我亲爱的安塞尔，这只是一个小挫折！我们很快就会恢复，重新开始运营的。', '哈哈！别担心，我亲爱的安塞尔，这只是一个小挫折！我们很快就会恢复，重新开始运营的。', 28153),
(149058, 'zhCN', '你——你——你说什么！？你差点害死你自己和整个农场！', '', 28153),
(149057, 'zhCN', '发展蜂蜜生产的艺术是我们的责任，不管付出任何代价！', '发展蜂蜜生产的艺术是我们的责任，不管付出任何代价！', 28153),
(149056, 'zhCN', '显然你并不需要。', '', 28153),
(149055, 'zhCN', '马上。', '', 28153),
(149054, 'zhCN', '啊？', '', 28153),
(149053, 'zhCN', '', '别担心，如果他有生命危险，他会让我们知道的。', 28153),
(149052, 'zhCN', '继续走。', '', 28153),
(149051, 'zhCN', '', '慢着……守卫去哪儿了？', 28153),
(149050, 'zhCN', '我们走。跟紧了。', '', 28153),
(149049, 'zhCN', '你就不能早点提醒我们。', '', 28153),
(149048, 'zhCN', '保持警觉。军情七处告诉我们，敌人已经接近要塞。', '', 28153),
(149047, 'zhCN', '跳下去。快。', '', 28153),
(149046, 'zhCN', '我们穿过那座桥。除非你的先知不同意。', '', 28153),
(149045, 'zhCN', '快走，避开大路。', '', 28153),
(149044, 'zhCN', '等等。', '', 28153),
(149043, 'zhCN', '注意，暴风城的市民们！', '', 28153),
(149042, 'zhCN', '好了。靠近点。我们现在是朋友了。', '', 28153),
(149041, 'zhCN', '', '城内守卫都出动了。我们不能在这逗留太久。', 28153),
(149040, 'zhCN', '我准备好起航了！', '我准备好起航了！', 28153),
(149039, 'zhCN', '', '你准备好起航前往库尔提拉斯了吗？', 28153),
(149038, 'zhCN', '', '多亏你的帮忙，我们有了回旋的余地，让卡格瓦可以加强他的防御。谢谢你。', 28153),
(149037, 'zhCN', '你别想阻止我取回属于我的东西！', '', 28153),
(149036, 'zhCN', '', '鲜血巨魔在继续攻击卡格瓦！切断他们的补给，让他们为攻击付出沉痛的代价！', 28153),
(149035, 'zhCN', '塞塔里斯……我已经忘却了你的声音……', '', 28153),
(149034, 'zhCN', '我们不应受神明的束缚。我们的力量属于自己！', '', 28153),
(149033, 'zhCN', '闯入者！你插手了你无法理解的事务。', '', 28153),
(149031, 'zhCN', 'PLACEHOLDER SCENE - 塔兰吉问是否真的结束了；洛坎说邪恶难除，他怀疑日后还会有这种遭遇。\n镜头：塔兰吉和洛坎的特写镜头，接着转至弹坑的不祥镜头。', 'PLACEHOLDER SCENE - 塔兰吉问是否真的结束了；洛坎说邪恶难除，他怀疑日后还会有这种遭遇。\n镜头：塔兰吉和洛坎的特写镜头，接着转至弹坑的不祥镜头。', 28153),
(149030, 'zhCN', '', '主人……我……失败了……', 28153),
(149029, 'zhCN', '', '高莱克·图尔……来了……', 28153),
(149028, 'zhCN', '', '高莱克·图尔承诺过……给我力量……', 28153),
(149027, 'zhCN', '', '虽然我在战斗中帮不上什么忙，但我的母亲必须接受正义的制裁……而我必须亲眼见证这一幕。', 28153),
(149026, 'zhCN', '', '为了我的父亲，为了德鲁斯瓦！', 28153),
(149025, 'zhCN', '', '我们在里面会合，审判官。', 28153),
(149024, 'zhCN', '', '审判官，集合！荣耀属于维克雷斯家族！', 28153),
(149023, 'zhCN', '', '听你命令。我们要把女巫会彻底铲除。', 28153),
(149022, 'zhCN', '', '审判官，最后的战斗就在你们面前。愿疾风助你们凯旋。', 28153),
(149021, 'zhCN', '', '母亲……你做了什么？', 28153),
(149020, 'zhCN', '', '元帅，不……', 28153),
(149019, 'zhCN', '我很……抱歉……', '', 28153),
(149018, 'zhCN', '亲爱的露希……我……让你失望了……', '', 28153),
(149017, 'zhCN', '', '元帅，别放弃！', 28153),
(149016, 'zhCN', '不……这……不对！', '', 28153),
(149015, 'zhCN', '我……遵从……', '', 28153),
(149014, 'zhCN', '我们来掩护侧翼！$n，跟紧元帅和露希尔！', '', 28153),
(149013, 'zhCN', '', '哼，我可不会任你尖叫的，巫婆！', 28153),
(149012, 'zhCN', '别停下，我们能搞定的！啄她们的眼睛，温斯顿！', '', 28153),
(149011, 'zhCN', '我就跟在你后面。', '我就跟在你后面。', 28153),
(149010, 'zhCN', '为了维克雷斯家族！', '', 28153),
(149009, 'zhCN', '靠近点，突破庄园大门之前都不要停下！', '', 28153),
(149008, 'zhCN', '按照这个速度，我们无法再坚持太久。我们必须前往码头。\n\n等你发令，我们就走。', '', 28153),
(149007, 'zhCN', '审判官！这是个机会，我们可以救下维克雷斯勋爵和夫人，消灭那个可恶的女巫会！', '', 28153),
(149005, 'zhCN', '', '我看到你在发抖。联盟，害怕了？', 28153),
(149004, 'zhCN', '', '头晕吗？', 28153),
(149003, 'zhCN', '', '你以为你们还有机会？', 28153),
(149002, 'zhCN', '', '居然被低贱的渣滓……暗算……', 28153),
(149001, 'zhCN', '你们胜利的机会微乎其微！', '', 28153),
(149000, 'zhCN', '你站错地方了！', '', 28153),
(148999, 'zhCN', '把它烧掉！', '', 28153),
(148998, 'zhCN', '你……耍诈……', '', 28153),
(148997, 'zhCN', '我来治疗你！', '', 28153),
(148996, 'zhCN', '防御阵形！', '', 28153),
(148995, 'zhCN', '圣光……会指引我回来。', '', 28153),
(148994, 'zhCN', '', '直取心脏！', 28153),
(148993, 'zhCN', '', '我要把你的灵魂献给高莱克·图尔！', 28153),
(148991, 'zhCN', '准备行动！敌人来了。', '准备行动！敌人来了。', 28153),
(148990, 'zhCN', '保护资源！', '保护资源！', 28153),
(148989, 'zhCN', '这森林属于我们！', '这森林属于我们！', 28153),
(148988, 'zhCN', '离我远点儿！', '离我远点儿！', 28153),
(148987, 'zhCN', '后退！', '后退！', 28153),
(148986, 'zhCN', '守护者是我们之中最为强大的人，负责将米斯拉克斯的尸体封印在大金字塔里。\n\n苏尔西斯是奠基人，但他无法单独封印坟墓。\n\n他向沃里克和柯泰克求助，他们齐心协力，一起对大金字塔施放了屏障，将米斯拉克斯的尸体封印在内。', '守护者是我们之中最为强大的人，负责将米斯拉克斯的尸体封印在大金字塔里。\n\n苏尔西斯是奠基人，但他无法单独封印坟墓。\n\n他向沃里克和柯泰克求助，他们齐心协力，一起对大金字塔施放了屏障，将米斯拉克斯的尸体封印在内。', 28153),
(148985, 'zhCN', '他自称为柯泰克大帝，但很久以前，他曾是一名守护者，负责保护坟墓。\n\n他对战争的渴望违背了我们的神灵所颂扬的一切，他甚至组建起一支军队，计划征服整个祖达萨，公开讨伐和污蔑我们的神灵。', '他自称为皇帝柯泰克，但很久以前，他曾是一名守护者，负责保护坟墓。\n\n他对战争的渴望违背了我们的神灵所颂扬的一切，他甚至组建起一支军队，计划征服整个祖达萨，公开讨伐和污蔑我们的神灵。', 28153),
(148984, 'zhCN', '无信者是一支蛇人部队，以柯泰克大帝为首。\n\n很久以前，我们曾团结一心，那也是塞塔里斯的愿望。\n\n自从柯泰克背叛之后，无信者为这片土地带来了战争。\n\n他们不会停下脚步，直到征服世界。', '无信者是一支蛇人部队，以皇帝柯泰克为首。\n\n很久以前，我们曾团结一心，那也是塞塔里斯的愿望。\n\n自从柯泰克背叛之后，无信者为这片土地带来了战争。\n\n他们不会停下脚步，直到征服世界。', 28153),
(148983, 'zhCN', '塞塔里斯是我们敬爱的神灵。\n\n当米斯拉克斯蹂躏我们的土地，威胁将我们灭族的时候，是她阻止了他，牺牲她的生命来拯救我们。\n\n与无信者不同，我们仍然能够感觉到她的存在，相信总有一天，她会回到我们身边。', '塞塔里斯是我们敬爱的神灵。\n\n当米斯拉克斯蹂躏我们的土地，威胁将我们灭族的时候，是她阻止了他，牺牲她的生命来拯救我们。\n\n与无信者不同，我们仍然能够感觉到她的存在，相信总有一天，她会回到我们身边。', 28153),
(148982, 'zhCN', '守护者是我们之中最为强大的人，负责将米斯拉克斯的尸体封印在大金字塔里。\n\n苏尔西斯是奠基人，但他无法单独封印坟墓。\n\n他向沃里克和柯泰克求助，他们齐心协力，一起对大金字塔施放了屏障，将米斯拉克斯的尸体封印在内。', '', 28153),
(148981, 'zhCN', '他自称为柯泰克大帝，但很久以前，他曾是一名守护者，负责保护坟墓。\n\n他对战争的渴望违背了我们的神灵所颂扬的一切，他甚至组建起一支军队，计划征服整个祖达萨，公开讨伐和污蔑我们的神灵。', '', 28153),
(148980, 'zhCN', '塞塔里斯是我们敬爱的神灵。\n\n当米斯拉克斯蹂躏我们的土地，威胁将我们灭族的时候，是她阻止了他，牺牲她的生命来拯救我们。\n\n与无信者不同，我们仍然能够感觉到她的存在，相信总有一天，她会回到我们身边。', '', 28153),
(148979, 'zhCN', '', '我要求你们立刻前往奥格瑞玛去执行一项极为紧迫的任务。不要让我等得太久。', 28153),
(148978, 'zhCN', '', '我们在这场战争中的成功与否将取决于你们的能力。', 28153),
(148977, 'zhCN', '无信者是一支蛇人部队，以柯泰克大帝为首。\n\n很久以前，我们曾团结一心，那也是塞塔里斯的愿望。\n\n自从柯泰克背叛之后，无信者为这片土地带来了战争。\n\n他们不会停下脚步，直到征服世界。', '', 28153),
(148976, 'zhCN', '', '勇士，部落和联盟现在已经开战了。', 28153),
(148975, 'zhCN', '这座岛屿正在吐出数量可观的艾泽里特。附近应该存在大型的艾泽里特晶簇。', '', 28153),
(148974, 'zhCN', '艾泽里特探测器已经启动！我们现在应该可以看到岛的全貌了。', '', 28153),
(148973, 'zhCN', '塞塔里斯是我们敬爱的神灵。\n\n当米斯拉克斯蹂躏我们的土地，威胁将我们灭族的时候，是她阻止了他，牺牲她的生命来拯救我们。\n\n与无信者不同，我们仍然能够感觉到她的存在，相信总有一天，她会回到我们身边。', '', 28153),
(148972, 'zhCN', '他自称为柯泰克大帝，但很久以前，他曾是一名守护者，负责保护坟墓。\n\n他对战争的渴望违背了我们的神灵所颂扬的一切，他甚至组建起一支军队，计划征服整个祖达萨，公开讨伐和污蔑我们的神灵。', '', 28153),
(148971, 'zhCN', '我们永远不会忘记我们的神灵为我们所做的一切。', '我们永远不会忘记我们的神灵为我们所做的一切。', 28153),
(148970, 'zhCN', '', '谢谢你，勇士。我的手下都吵着要检查这些文本，我希望他们能解析出有助于我们对抗鲜血之神的信息。', 28153),
(148969, 'zhCN', '', '这个装置可能会告诉我们一些可以用来封印或消灭戈霍恩的信息。搜寻任何有用的圣物或者文本。', 28153),
(148968, 'zhCN', '信念使我们强大。', '我们的信念使我们强大。', 28153),
(148966, 'zhCN', '我们会不惜一切代价保卫神庙！', '我们会不惜一切代价保卫神庙！', 28153),
(148965, 'zhCN', '我们不会放弃神殿。', '我们不会放弃神殿。', 28153),
(148962, 'zhCN', '一艘船进入地牢。派克表现出密切的关注，为什么一艘载着村民的船会进入他的教团圣地。', '一艘船进入地牢。派克表现出密切的关注，为什么一艘载着村民的船会进入他的教团圣地。', 28153),
(148959, 'zhCN', '什么事？', '什么事？', 28153),
(148958, 'zhCN', '我的感觉很强烈。有什么黑暗的东西在活动。', '', 28153),
(148955, 'zhCN', '不知道爸爸到底在这里干什么……', '', 28153),
(148954, 'zhCN', '我们必须离开这里。我可以让我们偷偷溜过所有的守卫。\n\n等你准备好行动时，就告诉我。', '', 28153),
(148953, 'zhCN', '让个道！', '', 28153),
(148952, 'zhCN', '一直往右走！我想我看到出路了！', '', 28153),
(148946, 'zhCN', '很好！这些材料应该很适合做箭矢和盔甲的衬里。', '', 28153),
(148945, 'zhCN', '纳兹米尔很危险，但是也有很多的资源，只要你知道在哪儿找。去海岸边捕猎野生动物来补给我们的部队。', '', 28153),
(148944, 'zhCN', '我们该怎么办，$p！？', '', 28153),
(148943, 'zhCN', '', '倒霉！', 28153),
(148942, 'zhCN', '', '你应该回去向希奥克报告！矿井得到控制的消息会让他高兴的。', 28153),
(148941, 'zhCN', '', '我们做到了！', 28153),
(148940, 'zhCN', '', '我……死了……离戈霍恩……那么远……？', 28153),
(148939, 'zhCN', '', '鲜血献给戈霍恩！', 28153),
(148938, 'zhCN', '我回实验室等你！', '我回实验室等你！', 28153),
(148936, 'zhCN', '神庙就在前面。', '', 28153),
(148935, 'zhCN', '我们会不惜一切代价去阻止他。', '', 28153),
(148934, 'zhCN', '他带领他们战斗，寻找剩余的钥匙，用来打破阿图阿曼四周的屏障，并使用里面的东西征服整个祖达萨。', '', 28153),
(148933, 'zhCN', '但随着柯泰克的背叛，无信者们将战争带到了这片土地。', '', 28153),
(148932, 'zhCN', '很久以前，如我们的神灵曾经希望的那样，我们团结一致。', '', 28153),
(148931, 'zhCN', '我们的神庙是对抗无信者的最后堡垒！', '', 28153),
(148930, 'zhCN', '部落的战士们，听从战斗的召唤！给他们个痛快。', '', 28153),
(148929, 'zhCN', '我觉得你想要只始祖龟，是吗？', '我觉得你想要只始祖龟，是吗？', 28153),
(148928, 'zhCN', '买一只你自己的始祖龟吧！你可以养着他们，或者用他们的龟壳存放东西。', '买一只你自己的始祖龟吧！你可以养着他们，或者用他们的龟壳存放东西。', 28153),
(148927, 'zhCN', '还有更高的出价吗？刚从纳兹米尔的朝圣之旅中捕捉到的始祖龟！', '还有出价的吗？刚从纳兹米尔的朝圣之旅中捕捉到的始祖龟！', 28153),
(148925, 'zhCN', '其他地方没有我这么好的狐人！', '其他地方没有我这么好的狐人！', 28153),
(148924, 'zhCN', '来买属于你的狐人吧，精力充沛！', '来买属于你的狐人吧，精力充沛！', 28153),
(148923, 'zhCN', '还有为狐人出价的吗？他们会很好地为你服务！', '还有为狐人出价的吗？他们会很好地为你服务！', 28153),
(148922, 'zhCN', '必须阻止无信者！', '必须阻止无信者！', 28153),
(148921, 'zhCN', '我应该能自己找到安全的地方。', '我应该能自己找到安全的地方。', 28153),
(148920, 'zhCN', '谢谢你，我自己能行了。', '谢谢你，我自己能行了。', 28153),
(148919, 'zhCN', '为那些没有获救的人报仇。', '为那些没有获救的人报仇。', 28153),
(148918, 'zhCN', '你不知道他们让我们经历了什么……', '你不知道他们让我们经历了什么……', 28153),
(148917, 'zhCN', '小心点，$p，你这是要直入虎穴。', '', 28153),
(148916, 'zhCN', '当你取回柯泰克之石以后，在那里和我们会面。', '', 28153),
(148910, 'zhCN', '谁给你的胆子踏上这片猎场？！', '谁给你的胆子踏上这片猎场？！', 28153),
(148909, 'zhCN', '你会为此付出代价的！', '你会为此付出代价的！', 28153),
(148908, 'zhCN', '联盟不允许进入这里！', '联盟不允许进入这里！', 28153),
(148907, 'zhCN', '这片禁猎区属于赞达拉！', '这片禁猎区属于赞达拉！', 28153),
(148906, 'zhCN', '想讨论巨魔的话，就请便。', '', 28153),
(148905, 'zhCN', '', '外面，如果巨魔值得信任的话。', 28153),
(148904, 'zhCN', '这是通往哪里？', '', 28153),
(148903, 'zhCN', '', '闻起来……令人作呕。', 28153),
(148902, 'zhCN', '', '让那些鲜血巨魔知道，我们再也不会躲藏下去了。干得漂亮。', 28153),
(148901, 'zhCN', '', '来人……阻止他们……', 28153),
(148900, 'zhCN', '', '没有人能躲过第七军团。去死吧，部落的渣滓！', 28153),
(148899, 'zhCN', '', '我的斥候报告说，鲜血巨魔正在附近集结军队。让他们明白，反抗赞达拉是件多么愚蠢的事。', 28153),
(148898, 'zhCN', '', '你们别想继续前进了！', 28153),
(148897, 'zhCN', '', '这是禁魔结界。我无法释放法术！', 28153),
(148896, 'zhCN', '这是什么讨厌的巫毒。塔莉萨？', '', 28153),
(148895, 'zhCN', '', '我得歇会儿。我已经为打破这个牢笼努力了很久了。', 28153),
(148894, 'zhCN', '', '你永远都摧毁不了我的诅咒！', 28153),
(148893, 'zhCN', '每一只野兽未来都有可能为部落效力。我们不能让这种事情发生。', '', 28153),
(148892, 'zhCN', '野兽的数量也许很快就能恢复，但部落培养一名野兽管理员需要花很长时间。干得好！', '', 28153),
(148891, 'zhCN', '赞达拉禁猎区里全是适合战用的野兽，但它们缺乏训练。毒死它们，把野兽管理员引出来。他们才是你的真正目标。', '', 28153),
(148890, 'zhCN', '', '你最好没弄错，祖尔。', 28153),
(148889, 'zhCN', '不是那条路。走另一边。', '', 28153),
(148888, 'zhCN', '这边！', '', 28153),
(148887, 'zhCN', '', '要怎么出去！', 28153),
(148886, 'zhCN', '', '多亏了你，我们离彻底消除鲜血巨魔的威胁又近了一步。', 28153),
(148885, 'zhCN', '', '我感觉附近有邪恶的魔精，肯定是鲜血巨魔！把他们找出来，阻止他们的阴谋！', 28153),
(148884, 'zhCN', '', '我们得离开这里！', 28153),
(148883, 'zhCN', '', '封锁出口！', 28153),
(148879, 'zhCN', '云收雨歇……风暴平息……', '', 28153),
(148878, 'zhCN', '我是风暴的预兆！', '', 28153),
(148877, 'zhCN', '客套话可以等会再说。', '', 28153),
(148876, 'zhCN', '', '我们代表部落而来。我是塔莉萨，这位是洛坎。', 28153),
(148875, 'zhCN', '', '嗯……谢谢你。我的先知告诉我，你们是我的盟友。', 28153),
(148874, 'zhCN', '哈哈哈，喏喏喏，伙计，我认识你。你就是那条狡猾的——', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148872, 'zhCN', '啊，我们的护卫来了。正如我所言，公主殿下。', '', 28153),
(148871, 'zhCN', '来吧，$n。这边走。', '', 28153),
(148870, 'zhCN', '[PH]我需要休息一会儿。', '', 28153),
(148868, 'zhCN', '[PH]柯泰克以为躲在一堵墙后面就能逃过我们了？真是个蠢货。', '', 28153),
(148867, 'zhCN', '按计划进行。我会跟上的。', '', 28153),
(148858, 'zhCN', '', '我懂了……要是您确定的话，萨鲁法尔大王。', 28153),
(148857, 'zhCN', '我确定。Lok\'tar。', '', 28153),
(148856, 'zhCN', '所以你不会跟我们走了。', '', 28153),
(148855, 'zhCN', '你我都心知肚明。你们真正要找的人在大厅下面。', '', 28153),
(148854, 'zhCN', '根据报告，我认为在大帝在市场的时候袭击他的难度最低。市场就在附近。', '', 28153),
(148853, 'zhCN', '我觉得你最好拿上这个。', '', 28153),
(148852, 'zhCN', '', '我们来引开他们的注意。当心点。', 28153),
(148851, 'zhCN', '我先去前面寻找俘虏。掩护我。', '', 28153),
(148850, 'zhCN', '第七军团在这里。不管我们谁去，与那些人类正面交锋都没有胜算。', '', 28153),
(148849, 'zhCN', '我会来找你的。祝你好运。', '', 28153),
(148848, 'zhCN', '那就是我们的撤离点。一旦找到俘虏，就去那艘船。', '', 28153),
(148847, 'zhCN', '我给你们每个人都准备了一份轻松就义的机会。要是走投无路的话，就安心上路。', '', 28153),
(148846, 'zhCN', '要是你被捕，大酋长以及部落将否认对此次任务知情。', '', 28153),
(148845, 'zhCN', '我们的斥候找到了一处隐蔽入口。我和牛头人会掩护你们逃跑。', '', 28153),
(148844, 'zhCN', '你，塔莉萨，还有洛坎要潜入监狱，救出俘虏。', '', 28153),
(148843, 'zhCN', '听仔细了。一旦进入暴风城我们就无法再保持联系。', '', 28153),
(148842, 'zhCN', '', '我们要确保野猪人再也不能发动这种规模的战争。', 28153),
(148841, 'zhCN', '你的末日……即将降临……', '你的末日……即将降临……', 28153),
(148840, 'zhCN', '怎么……可能……', '怎么……可能……', 28153),
(148839, 'zhCN', '你终将面对……风暴……之眼……', '你终将面对……风暴……之眼……', 28153),
(148838, 'zhCN', '你……会……陨落……', '你……会……陨落……', 28153),
(148837, 'zhCN', '我的灵魂……归于……大海……', '我的灵魂……归于……大海……', 28153),
(148836, 'zhCN', '我要前往……波涛……之下……', '我要前往……波涛……之下……', 28153),
(148835, 'zhCN', '我会回归……深渊……', '我会回归……深渊……', 28153),
(148834, 'zhCN', '潮水终将……退去……', '潮水终将……退去……', 28153),
(148833, 'zhCN', '她的力量在我的血液中涌动！', '她的力量在我的血液中涌动！', 28153),
(148832, 'zhCN', '拥抱末日吧！', '拥抱末日吧！', 28153),
(148831, 'zhCN', '让命运的触须吞噬你！', '让命运的触须吞噬你！', 28153),
(148830, 'zhCN', '生命会脱离你的躯壳！', '生命会脱离你的躯壳！', 28153),
(148829, 'zhCN', '你的生命会在溺亡时寂灭！', '你的生命会在溺亡时寂灭！', 28153),
(148828, 'zhCN', '没人能阻止无尽的浪潮！', '没人能阻止无尽的浪潮！', 28153),
(148827, 'zhCN', '听从深渊的召唤！\n', '听从深渊的召唤！\n', 28153),
(148826, 'zhCN', '海浪会卷走你！', '海浪会卷走你！', 28153),
(148825, 'zhCN', '如此……黑暗……', '如此……黑暗……', 28153),
(148824, 'zhCN', '潮水……请带我走……', '潮水……请带我走……', 28153),
(148823, 'zhCN', '至少我死得像个……库尔提拉斯人……', '至少我死得像个……库尔提拉斯人……', 28153),
(148822, 'zhCN', '你……居然能够……', '你……居然能够……', 28153),
(148821, 'zhCN', '不能……就这样……', '不能……就这样……', 28153),
(148820, 'zhCN', '我要拿你的皮囊去领赏！', '哦，我要拿你的皮囊去领赏！', 28153),
(148819, 'zhCN', '我要拿你的脸来擦甲板！', '我要拿你的脸来擦甲板！', 28153),
(148818, 'zhCN', '冲我来啊！', '冲我来啊！', 28153),
(148817, 'zhCN', '这场战斗会成为酒吧里的谈资！', '哦，这场战斗会成为酒吧里的谈资！', 28153),
(148816, 'zhCN', '你会后悔的！', '你会后悔的！', 28153),
(148815, 'zhCN', '摆渡人……在召唤……', '摆渡人……在召唤……', 28153),
(148814, 'zhCN', '潮水……请带走我……', '潮水……请带我走……', 28153),
(148813, 'zhCN', '至少我为……库尔提拉斯而死……', '至少我为……库尔提拉斯而死……', 28153),
(148812, 'zhCN', '我终将……回归……海洋……', '我终将……回归……海洋……', 28153),
(148811, 'zhCN', '我会在六尺水下……安眠……', '我会在六尺水下……安眠……', 28153),
(148810, 'zhCN', '又一个战利品送上门了！', '又一个战利品送上门了！', 28153),
(148809, 'zhCN', '', '在这里我们可以自由地交谈了。这些话没法在奥格瑞玛说。', 28153),
(148808, 'zhCN', '我要把你切了喂鱼！', '我要把你切了喂鱼！', 28153),
(148807, 'zhCN', '来打我啊！', '来打我啊！', 28153),
(148806, 'zhCN', '', '请原谅我的拐弯抹角，因为马迪亚斯·肖尔派出了大批间谍。', 28153),
(148805, 'zhCN', '我要在酒吧里欢庆你的死亡！', '我要在酒吧里欢庆你的死亡！', 28153),
(148804, 'zhCN', '你会后悔的。', '你会后悔的。', 28153),
(148803, 'zhCN', '', '嘿！让我出去！', 28153),
(148802, 'zhCN', '回去干活儿，蛆虫！', '回去干活儿，蛆虫！', 28153),
(148801, 'zhCN', '你会遭……报应的……', '你会遭……报应的……', 28153),
(148800, 'zhCN', '这是……违抗……上级……', '这是……违抗……上级……', 28153),
(148799, 'zhCN', '你……被……免职了……', '你……被……免职了……', 28153),
(148798, 'zhCN', '要找到……好帮手……真难……', '要找到……好帮手……真难……', 28153),
(148797, 'zhCN', '我要……给你……记大过……', '我要……给你……记大过……', 28153),
(148796, 'zhCN', '啊……去你的……', '啊……去你的……', 28153),
(148795, 'zhCN', '你就……这点……能耐……', '你就……这点……能耐……', 28153),
(148794, 'zhCN', '没用的……蛆虫……', '没用的……蛆虫……', 28153),
(148793, 'zhCN', '我让你休息了吗？！', '我让你休息了吗？！', 28153),
(148792, 'zhCN', '我要拿你杀鸡儆猴！', '我要拿你杀鸡儆猴！', 28153),
(148791, 'zhCN', '休息时间结束了，懒骨头！', '休息时间结束了，懒骨头！', 28153),
(148790, 'zhCN', '敢惹我，你会后悔的！', '敢惹我，你会后悔的！', 28153),
(148789, 'zhCN', '你胆敢违法乱纪？！', '你胆敢违法乱纪？！', 28153),
(148788, 'zhCN', '让你看看以身试法的下场！', '让你看看以身试法的下场！', 28153),
(148787, 'zhCN', '给我规矩点！', '给我规矩点！', 28153),
(148786, 'zhCN', '让我们离开这里！', '', 28153),
(148785, 'zhCN', '', '塞利克，很高兴能看到你回来！无信者抓走了沃里克！', 28153),
(148783, 'zhCN', '', '你们都退下吧。', 28153),
(148782, 'zhCN', '', '啊，$n。多谢你的及时回应。', 28153),
(148781, 'zhCN', '', '艾尔格森正在毁灭森林！我们不能让他继续伤害大自然！', 28153),
(148780, 'zhCN', '你必须和神灵见面。准备好了吗', '', 28153),
(148779, 'zhCN', '雕像就在神殿废墟中的某个地方……', '', 28153),
(148778, 'zhCN', '我们得先清理掉这些蜘蛛，然后才能让部族来这里避难。', '', 28153),
(148775, 'zhCN', '我们必须把我们的发现告知部族！', '', 28153),
(148774, 'zhCN', '恐怕我的部族很快就要饿死了……', '', 28153),
(148773, 'zhCN', '我们必须查清纳迦到底在找什么……', '', 28153),
