(148686, 'zhCN', '你现在离家很远。', '你现在离家很远。', 28153),
(148685, 'zhCN', '对陌生人要多长个心眼。', '对陌生人要多长个心眼。', 28153),
(148684, 'zhCN', '别掺和女巫的事情。', '别掺和女巫的事情。', 28153),
(148683, 'zhCN', '荣耀属于维克雷斯家族。', '荣耀属于维克雷斯家族。', 28153),
