(145252, 'zhCN', '', '有话就说。', 28153),
(145251, 'zhCN', '我再试试。', '我再试试。', 28153),
(145250, 'zhCN', '错误！\n\n想再试一次吗？', '', 28153),
(145249, 'zhCN', '神灵。', '神灵。', 28153),
(145248, 'zhCN', '蜡烛。', '蜡烛。', 28153),
(145247, 'zhCN', '', '看那边，下面。有东西在发光！', 28153),
(145246, 'zhCN', '', '我们在哪？为什么到处都是烟？', 28153),
(145245, 'zhCN', '', '小心点，好么？', 28153),
(145244, 'zhCN', '树。', '树。', 28153),
(145243, 'zhCN', '', '别掉下去了，朋友！我掉下去没关系，但你可能就会摔扁啦！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145242, 'zhCN', '', '你好啊。', 28153),
(145241, 'zhCN', '', '原来山可以长这么高呀！', 28153),
(145240, 'zhCN', '', '这儿什么都看得到！', 28153),
(145239, 'zhCN', '', '见到你挺高兴。', 28153),
(145238, 'zhCN', '', '幸会。', 28153),
(145237, 'zhCN', '', '呱呱呱呱呱！', 28153),
(145236, 'zhCN', '', '不。', 28153),
(145235, 'zhCN', '', '没有。', 28153),
(145234, 'zhCN', '', '没门。', 28153),
(145233, 'zhCN', '', '这就对了。', 28153),
(145232, 'zhCN', '', '嗯哼。', 28153),
(145231, 'zhCN', '', '就是。', 28153),
(145230, 'zhCN', '', '太谢谢你了！', 28153),
(145229, 'zhCN', '', '非常感谢！', 28153),
(145228, 'zhCN', '侏儒。', '侏儒。', 28153),
(145227, 'zhCN', '', '我欠你个人情。', 28153),
(145226, 'zhCN', '', '看在黑铁砧的份上！', 28153),
(145225, 'zhCN', '', '起码有……十只！', 28153),
(145224, 'zhCN', '', '你就这点能耐？', 28153),
(145222, 'zhCN', '', '我要把你揍扁！', 28153),
(145221, 'zhCN', '', '不知道那棵树上住着多少只鸟。肯定好多好多！', 28153),
(145220, 'zhCN', '回答我的问题。\n\n我年轻的时候高，我年老的时候矮。我是什么？', '', 28153),
(145219, 'zhCN', '', '这是我的荣幸。', 28153),
(145218, 'zhCN', '', '朋友，看！我们在一棵大树下面！', 28153),
(145217, 'zhCN', '', '能帮忙我很高兴。', 28153),
(145216, 'zhCN', '', '不用谢啦。', 28153),
(145215, 'zhCN', '我们来玩玩吧。', '我们来玩玩吧。', 28153),
(145214, 'zhCN', '你准备好测试你的智慧了吗？', '', 28153),
(145213, 'zhCN', '', '我可以养一只当宠物吗？', 28153),
(145212, 'zhCN', '', '但是里面住的是蜥蜴鸟。', 28153),
(145211, 'zhCN', '', '这座塔好高。就像是……巨大的鸟房！', 28153),
(145210, 'zhCN', '', '喂，这些会飞的是什么呀？好漂亮！', 28153),
(145209, 'zhCN', '', '说起来……你有家吗？', 28153),
(145208, 'zhCN', '', '你住在这儿吗？', 28153),
(145207, 'zhCN', '', '它是怎么飞起来的？', 28153),
(145206, 'zhCN', '', '哇……会飞的城市！真的吗？！', 28153),
(145205, 'zhCN', '', '你想跟我一起玩公主游戏吗？', 28153),
(145204, 'zhCN', '', '你知道里面住着谁吗？我猜是公主。', 28153),
(145203, 'zhCN', '', '哇！这肯定是全世界最漂亮的房子了！', 28153),
(145202, 'zhCN', '', '呕！！', 28153),
(145201, 'zhCN', '', '是虫子吗？肯定是虫子。呕！我最讨厌虫子了！', 28153),
(145200, 'zhCN', '', '你说他们不想让谁进去？', 28153),
(145199, 'zhCN', '', '哇！这是我看到过的最大的城墙！', 28153),
(145197, 'zhCN', '', '尤娜拥抱了你。', 28153),
(145196, 'zhCN', '不许动！', '', 28153),
(145195, 'zhCN', '', '好的，朋友，我们出去吧！有好多地方要去呢！', 28153),
(145194, 'zhCN', '', '请告诉我妈妈和爸爸，我好想他们，而且……我们很快就会再见面了！', 28153),
(145193, 'zhCN', '', '朋友！圣光说我可以留下来！耶！', 28153),
(145192, 'zhCN', '', '我可以跟我的朋友多呆会儿吗？就多呆一小会儿？', 28153),
(145191, 'zhCN', '', '我还有好多事情没做呢，还有好多地方没去看过……', 28153),
(145190, 'zhCN', '', '等一下……', 28153),
(145189, 'zhCN', '', '妈妈！爸爸！他们在等我呢！', 28153),
(145188, 'zhCN', '', '那道光……告诉我要跟着它……', 28153),
(145187, 'zhCN', '', '出……出什么事了？', 28153),
(145186, 'zhCN', '', '哦，朋友！我们成功了！我们把他们打败了！', 28153),
(145185, 'zhCN', '', '黑暗消失了！我看得见了！', 28153),
(145184, 'zhCN', '', '你要为你的所作所为付出代价！', 28153),
(145183, 'zhCN', '诅咒你。诅咒你！还没完呢……', '', 28153),
(145182, 'zhCN', '你的死会让女妖之王高兴的！', '', 28153),
(145181, 'zhCN', '联盟的渣滓！黑暗女王会来找你们的！', '', 28153),
(145180, 'zhCN', '', '我要割开你的喉咙，$n！', 28153),
(145179, 'zhCN', '狂乱的蹄声在远方回响。有东西过来了。', '狂乱的蹄声在远方回响。有东西过来了。', 28153),
(145178, 'zhCN', '', '胆敢打扰我！你要付出生命的代价，$n！', 28153),
(145177, 'zhCN', '', '我在看着你，$n。', 28153),
(145176, 'zhCN', '我要把你们煎了，就像对你们的狗头国王那样！为了部落！', '', 28153),
(145175, 'zhCN', '你闻起来就像雷雨前的空气，真是清新啊。', '你闻起来就像雷雨前的空气，真是清新啊。', 28153),
(145173, 'zhCN', '', '有两下子，不过我也不只会魔法。', 28153),
(145172, 'zhCN', '我准备好了。我们开始仪式吧。', '我准备好了。我们开始仪式吧。', 28153),
(145171, 'zhCN', '我听到世界在我的脚下哭泣。艾泽拉斯正在痛苦中颤抖！我们必须找到缓解痛苦的办法……', '', 28153),
(145170, 'zhCN', '', '我不会轻易死去的，$n。感受我的愤怒吧！', 28153),
(145169, 'zhCN', '', '我终于找到你了，$n。', 28153),
(145168, 'zhCN', '我会碾碎你的头骨！', '', 28153),
(145167, 'zhCN', '我要把你的皮都剥下来！', '', 28153),
(145166, 'zhCN', '我会永远站在你的墓前。', '', 28153),
(145165, 'zhCN', '我失去了所有希望。', '', 28153),
(145164, 'zhCN', '这诅咒又来了。', '', 28153),
(145163, 'zhCN', '你要为对我做的事付出代价。', '', 28153),
(145162, 'zhCN', '我会吸取你的生命力量。', '', 28153),
(145161, 'zhCN', '金属的碰撞声和恐惧的味道是我的最爱。', '', 28153),
(145160, 'zhCN', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t你正受到|cFFF00000|Hspell:260953|h[铁之凝视]|h|r！', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t你|cFFF00000|Hspell:257459|h[上钩了]|h|r！', 28153),
(145159, 'zhCN', '', '我再也不会害怕了！', 28153),
(145158, 'zhCN', '', '我的圣光非常强大！', 28153),
(145157, 'zhCN', '我想回家。', '', 28153),
(145156, 'zhCN', '', '只要我的圣光与我同在，那么黑暗就绝对赢不了的！', 28153),
(145155, 'zhCN', '', '妈妈跟我说过，圣光总会找到我的。她说的就是你，对吗？你就是我的圣光！', 28153),
(145154, 'zhCN', '', '朋友，你还在！你没有离开我！', 28153),
(145153, 'zhCN', '不……不……', '不……不……', 28153),
(145152, 'zhCN', '黑暗女王……我失败了……', '黑暗女王……我失败了……', 28153),
(145151, 'zhCN', '我是图腾柱的根基，凡人。', '', 28153),
(145150, 'zhCN', '终于……', '终于……', 28153),
(145149, 'zhCN', '哦……别再来了……', '哦……别再来了……', 28153),
(145148, 'zhCN', '为了黑暗女王！', '为了黑暗女王！', 28153),
(145147, 'zhCN', '放弃希望吧！', '放弃希望吧！', 28153),
(145146, 'zhCN', '加入我们亡者的行列吧！', '加入我们亡者的行列吧！', 28153),
(145145, 'zhCN', '我要嚼碎你的骨头！', '我要嚼碎你的骨头！', 28153),
(145144, 'zhCN', '消灭活人！', '消灭活人！', 28153),
(145143, 'zhCN', '为了希尔瓦娜斯！', '为了希尔瓦娜斯！', 28153),
(145142, 'zhCN', '', '尤娜把手放在胸前，哭了起来。', 28153),
(145141, 'zhCN', '', '我……我办不到！我只想回家！', 28153),
(145140, 'zhCN', '', '朋友，你还在吗？我好怕！', 28153),
(145139, 'zhCN', '坏运气会找上你的！', '', 28153),
(145137, 'zhCN', '你的先祖正在召唤你加入。', '', 28153),
(145136, 'zhCN', '愿我兄弟那可怕的面孔诅咒你。', '', 28153),
(145135, 'zhCN', '你在搞什么巫毒，伙计？', '', 28153),
(145133, 'zhCN', '让骨骼各落其位。', '', 28153),
(145130, 'zhCN', '荆棘想夺取你的灵魂！', '', 28153),
(145129, 'zhCN', '白鹿转身消失在了森林中。从那之后，它就一直在庇护勇敢而诚实的人民。', '白鹿转身消失在了森林中。从那之后，它就一直在庇护勇敢而诚实的人民。', 28153),
(145128, 'zhCN', '“我是阿萨尔，森林之心。只要我在这里，你和你的人民就可以到我身边来寻求保护。”白鹿说道。', '“我是阿萨尔，森林之心。只要我在这里，你和你的人民就可以到我身边来寻求保护。”白鹿说道。', 28153),
(145127, 'zhCN', '“圣光保佑！你会说话！”阿罗姆大喊道！', '“圣光保佑！你会说话！”阿罗姆大喊道！', 28153),
(145126, 'zhCN', '', '<喝彩声>', 28153),
(145125, 'zhCN', '', '<哈欠声>', 28153),
(145124, 'zhCN', '', '喔！', 28153),
(145123, 'zhCN', '', '哟呵！', 28153),
(145122, 'zhCN', '它的弱点是火！', '', 28153),
(145121, 'zhCN', '', '<鸡叫声>', 28153),
(145120, 'zhCN', '', '<哭泣>', 28153),
(145119, 'zhCN', '“不用谢。我是在报答你的好意。”', '“不用谢。我是在报答你的好意。”', 28153),
(145118, 'zhCN', '', '<哭泣变种>', 28153),
(145117, 'zhCN', '', '<哭泣变种>', 28153),
(145116, 'zhCN', '', '<亲吻>', 28153),
(145115, 'zhCN', '“谢谢你，我的朋友。”阿罗姆对白鹿说道。', '“谢谢你，我的朋友。”阿罗姆对白鹿说道。', 28153),
(145114, 'zhCN', '', '<大笑>', 28153),
(145113, 'zhCN', '', '<大笑>', 28153),
(145112, 'zhCN', '', '<咂舌>', 28153),
(145111, 'zhCN', '阿罗姆和白鹿一起与德鲁斯特战士作战，并打败了他们。', '阿罗姆和白鹿一起与德鲁斯特战士作战，并打败了他们。', 28153),
(145110, 'zhCN', '', '<充满压迫感的咆哮>', 28153),
(145109, 'zhCN', '', '<咆哮变种>', 28153),
(145108, 'zhCN', '', '<叹气>', 28153),
(145107, 'zhCN', '', '<火车>', 28153),
(145106, 'zhCN', '白鹿回来了，踩倒了一群德鲁斯特！', '白鹿回来了，踩倒了一群德鲁斯特！', 28153),
(145105, 'zhCN', '这时森林里发出了一声咆哮！', '这时森林里发出了一声咆哮！', 28153),
(145104, 'zhCN', '但他绝不后退，下定决心要尽量多地打倒敌人！', '但他绝不后退，下定决心要尽量多地打倒敌人！', 28153),
(145103, 'zhCN', '阿罗姆勋爵能打败十个战士！他英勇而机智地战斗，但还是寡不敌众。他被包围了！', '阿罗姆勋爵能打败十个战士！他英勇而机智地战斗，但还是寡不敌众。他被包围了！', 28153),
(145102, 'zhCN', '有意思。', '有意思。', 28153),
(145101, 'zhCN', '夜里，德鲁斯特发起了攻击！', '夜里，德鲁斯特发起了攻击！', 28153),
(145100, 'zhCN', '白鹿一路跳着回到了森林里，阿罗姆在原地搭帐篷过夜。', '白鹿一路跳着回到了森林里，阿罗姆在原地搭帐篷过夜。', 28153),
(145099, 'zhCN', '“既然它能击退那么多的德鲁斯特，我希望让它留在我的森林里。”阿罗姆勋爵这样想着。所以他治愈了白鹿的伤。', '“既然它能击退那么多的德鲁斯特，我希望让它留在我的森林里。”阿罗姆勋爵这样想着。所以他治愈了白鹿的伤。', 28153),
(145098, 'zhCN', '当心荆棘！', '', 28153),
(145097, 'zhCN', '阿罗姆勋爵的人民需要食物，而那只巨鹿可以喂饱很多人，但他决定不去攻击它。', '阿罗姆勋爵的人民需要食物，而那只巨鹿可以喂饱很多人，但他决定不去攻击它。', 28153),
(145096, 'zhCN', '白鹿被德鲁斯特攻击了，它杀了很多德鲁斯特，但自己也受了伤。', '白鹿被德鲁斯特攻击了，它杀了很多德鲁斯特，但自己也受了伤。', 28153),
(145095, 'zhCN', '有一天，阿罗姆勋爵在森林里打猎的时候，遇见了一直巨大的白鹿。', '有一天，阿罗姆勋爵在森林里打猎的时候，遇见了一直巨大的白鹿。', 28153),
(145094, 'zhCN', '对！释放我们！', '', 28153),
(145093, 'zhCN', '我们终于……解脱了……', '', 28153),
(145092, 'zhCN', '终于……自由了……', '', 28153),
(145091, 'zhCN', '谢谢……你……', '', 28153),
