(144971, 'zhCN', '', '我无法交易它。', 28153),
(144970, 'zhCN', '', '无法使用。', 28153),
(144969, 'zhCN', '', '我还没有装备它。', 28153),
(144968, 'zhCN', '', '我必须先装备它。', 28153),
(144967, 'zhCN', '', '我现在还不能拾取它。', 28153),
(144966, 'zhCN', '', '我没有目标。', 28153),
(144965, 'zhCN', '', '我需要先选中一个目标。', 28153),
(144964, 'zhCN', '', '我需要一个目标。', 28153),
(144963, 'zhCN', '', '力量高涨，万灵彷徨，荆棘舐血，藤蔓游荡！', 28153),
(144962, 'zhCN', '', '把水晶给我，姐妹！', 28153),
(144961, 'zhCN', '', '我的荆棘会撕碎你！', 28153),
(144960, 'zhCN', '', '你越是挣扎，血痕就越多。', 28153),
(144959, 'zhCN', '', '你身上有黑暗的印记！', 28153),
(144958, 'zhCN', '', '你的头颅是上好的烛台。', 28153),
(144956, 'zhCN', '', '我的草根会再度发芽……', 28153),
(144955, 'zhCN', '', '四肢折断的声音百听不厌。', 28153),
(144954, 'zhCN', '我今晚能吃大餐了。非常感谢，祝你一帆风顺。', '我今晚能吃大餐了。非常感谢，祝你一帆风顺。', 28153),
(144953, 'zhCN', '你对我很友善。谢谢！', '你对我很友善。谢谢！', 28153),
(144952, 'zhCN', '谢谢你，朋友。', '谢谢你，朋友。', 28153),
(144951, 'zhCN', '', '多么灵活的骨头！', 28153),
(144950, 'zhCN', '<给十个金币。>', '<给十个金币。>', 28153),
(144949, 'zhCN', '<给一个金币。>', '<给一个金币。>', 28153),
(144948, 'zhCN', '<给五个铜币。>', '<给五个铜币。>', 28153),
(144947, 'zhCN', '赏点铜币吧，朋友？', '赏点铜币吧，朋友？', 28153),
(144946, 'zhCN', '', '血肉剥离，尖叫四起，合声雄浑，乐章永继！', 28153),
(144945, 'zhCN', '', '哈哈哈，你即将毁灭！', 28153),
(144944, 'zhCN', '', '你已经用过一次了！', 28153),
(144943, 'zhCN', '', '……莱赞在鲜血巨魔军队的尸体上大声咆哮。耀武扬威！', 28153),
(144942, 'zhCN', '', '你的折磨才刚刚开始。', 28153),
(144941, 'zhCN', '', '何等美丽的痛楚！', 28153),
(144940, 'zhCN', '', '就算我的身躯破碎……我的咒语……依旧存续……', 28153),
(144939, 'zhCN', '', '我要剥离你的血肉，聆听你的尖叫！', 28153),
(144938, 'zhCN', '', '焦黑之魂，残月之夜，众生哀鸣，万物陨灭！', 28153),
(144937, 'zhCN', '', '你现在归我了！', 28153),
(144936, 'zhCN', '', '跳舞吧，玩偶！跳舞吧！', 28153),
(144935, 'zhCN', '', '把水晶给我，你这蠢货！只有我才能驾驭它的力量！', 28153),
(144934, 'zhCN', '', '你们的灵魂永远都是……我的了。', 28153),
(144933, 'zhCN', '', '死亡也无法让我沉默……', 28153),
(144932, 'zhCN', '', '这个灵魂太脆弱了！', 28153),
(144931, 'zhCN', '', '你的力量在这里一无是处！', 28153),
(144930, 'zhCN', '', '$n，跟我来。其他人，到北线与洛坎会合。', 28153),
(144929, 'zhCN', '看啊，联盟军队！他们正在全线出击！', '', 28153),
(144928, 'zhCN', '他们有一大波士兵冲过来了！快拦下来！', '', 28153),
(144926, 'zhCN', '', '你好，$c。', 28153),
(144925, 'zhCN', '', '永远别忘记，向圣光宣誓效忠意味着什么。', 28153),
(144924, 'zhCN', '', '<法瑞娅对你致以热忱的微笑。>$B$B你干得不错，通过了试练，$c。但我觉得你的传说才刚刚开始。', 28153),
(144923, 'zhCN', '你要找玛依拉？她正在前线帮忙。$B$B暴风城里居住着许多能工巧匠，他们可以教你一两手。', '', 28153),
(144921, 'zhCN', '', '圣光啊，带走这张桌子吧！我大概再也没法使用这里了。$B$B阿古斯兽皮的污染太过持久，不管我冲洗多少遍也不行。', 28153),
(144908, 'zhCN', '维迪卡尔正在等待下一次旅行。\n\n我也一样。', '', 28153),
(144907, 'zhCN', '谢谢你帮忙，$G小伙子:小丫头;！我欠你一份情！', '', 28153),
(144906, 'zhCN', '呃，我要去旅馆了。', '', 28153),
(144905, 'zhCN', '啊，那就更好了。神装配英雄！而且这位英雄的传奇事迹甚至动摇了艾泽拉斯的根基！', '', 28153),
(144904, 'zhCN', '对，我就是要拿走！我是光明正大地买到这件护甲的，虽然我当时还没付钱。', '', 28153),
(144903, 'zhCN', '', '看来你今天运气不错，石眉先生。你可以把货物拿走了。', 28153),
(144902, 'zhCN', '别拿你的爪子碰我，毛球！', '', 28153),
(144901, 'zhCN', '', '遵命，夫人。', 28153),
(144900, 'zhCN', '', '走开！我们才不怕你呢！', 28153),
(144899, 'zhCN', '%s点了点头。', '', 28153),
(144898, 'zhCN', '', '楚先生，请送这位矮人离开。秀兰女士，把这件护甲重新上架。', 28153),
(144897, 'zhCN', '我今早把支票寄出来了，我发誓！你不能让我破产！', '', 28153),
(144896, 'zhCN', '', '石眉先生，你已经有很多次没有付款了。按照我们的合同，我得收回这些货物了。', 28153),
(144895, 'zhCN', '', '他们来了……', 28153),
(144894, 'zhCN', '', '我们会的。先坐下吧。', 28153),
(144893, 'zhCN', '他们从森林里冲出来，我们打成一团。艾什顿大师把我推开，自己被抓走了。我们得救他！', '', 28153),
(144892, 'zhCN', '', '我知道你努力了，马登。发生了什么？', 28153),
(144891, 'zhCN', '我努力想把它们撵走！', '', 28153),
(144889, 'zhCN', '', '话说……你为什么要把那个矮人带来？展示实力？用来威慑？', 28153),
(144888, 'zhCN', '和我想的一样。', '', 28153),
(144887, 'zhCN', '……对……没错。果然如此！', '', 28153),
(144886, 'zhCN', '别忘了我们的目的。我们必须赶在联盟之前找到希巴拉之眼。', '', 28153),
(144885, 'zhCN', '', '要知道，巨魔可能在这个考古发现上干坐了数千年！', 28153),
(144884, 'zhCN', '', '战斗开始了！带领我们走向胜利吧！', 28153),
(144883, 'zhCN', '你走的时候，跟你父亲说的是去探险。可不是去和这些部落杂种斡旋。', '', 28153),
(144882, 'zhCN', '公主殿下。', '', 28153),
(144881, 'zhCN', '您的父亲正在等待。', '', 28153),
(144880, 'zhCN', '', '公主……请允许我成为第一个迎接您的人——', 28153),
(144879, 'zhCN', '', '听着……父王虽然生性固执，但却明察秋毫。我敢打赌，他肯定已经知道是你帮我逃离了暴风城。', 28153),
(144878, 'zhCN', '', '这个人的命运可不由你决定，将军。', 28153),
(144877, 'zhCN', '保护王国最好的办法，就是将这些……杂碎……驱逐到沃顿。部落在赞达拉没有一席之地。', '', 28153),
(144876, 'zhCN', '', '你发誓会保护这个王国。如果你不愿尽职，那我就得找个愿意的人。', 28153),
(144875, 'zhCN', '<接触裂缝。>', '<接触裂缝。>', 28153),
(144874, 'zhCN', '', '将军。', 28153),
(144873, 'zhCN', '<这是滴绿龙之泪，被不知名的力量投进了暗影里。>', '', 28153),
(144872, 'zhCN', '', '与此同时，赞枢利议会，哼，这群勾心斗角的政客、倚老卖老的家伙不认为这是威胁。他们告诉我父亲，没必要采取措施。', 28153),
(144871, 'zhCN', '', '鲜血巨魔不断滋扰北境。他们把我的人民抓到纳兹米尔沼泽，从此杳无音信。', 28153),
(144870, 'zhCN', '', '赞达拉充满了内忧外患。所以我才去寻找部落……并请求部落最伟大的英雄之一，也就是你来帮助我。', 28153),
(144869, 'zhCN', '', '我们只能趁现在说两句，$n。关于我们的王国，有些事情你必须知道。', 28153),
(144868, 'zhCN', '', '来吧，部落的勇士。我们得跟我父亲见一面。祖尔嘛……待会儿再说。', 28153),
(144867, 'zhCN', '', '泽那！你好啊，小朋友。想我了吗？', 28153),
(144866, 'zhCN', '', '我听到你说的那个孩子的哭泣了。\n\n我告诉你，你可以进入这个世界，找到她。\n\n她所在的地方，生和死两个领域的屏障很薄弱，而且溢进了你的世界。\n\n要小心，你在这个地方没有任何力量，其中的居民无法受到凡人的伤害。\n\n你可以努力，但也许终究还是没法帮助你的朋友。', 28153),
(144864, 'zhCN', '愿圣光与你同在。', '愿圣光与你同在。', 28153),
(144863, 'zhCN', '我在找一个叫尤娜的小女孩，你看到她了吗？', '我在找一个叫尤娜的小女孩，你看到她了吗？', 28153),
(144862, 'zhCN', '', '提帕托斯教过我们怎么玩石块、羊皮纸、利剑……但我把规则忘了。', 28153),
(144860, 'zhCN', '联盟的大门已被摧毁！', '', 28153),
(144859, 'zhCN', '', '狮鹫！攻击！', 28153),
(144853, 'zhCN', '我们最勇敢的战士经常都在冲锋陷阵。至少我可以帮忙照看他们的家人，直到他们归来。', '我们最勇敢的战士经常都在冲锋陷阵。至少我可以帮忙照看他们的家人，直到他们归来。', 28153),
(144852, 'zhCN', '你进入了我的地盘？太蠢了！', '', 28153),
(144851, 'zhCN', '', '尾巴毛茸茸的！', 28153),
(144850, 'zhCN', '', '可以送给我吗？', 28153),
(144849, 'zhCN', '', '不嘛！再呆一会儿，讲几个冒险的故事吧，提帕托斯！', 28153),
(144848, 'zhCN', '', '他回来了！', 28153),
(144847, 'zhCN', '', '是提帕托斯！', 28153),
(144846, 'zhCN', '别担心，提帕托斯下次回来会有更多的故事……可能还会有新朋友。', '', 28153),
(144845, 'zhCN', '提帕托斯现在必须把这个小家伙还回去了。小朋友们，说再见吧。', '', 28153),
(144842, 'zhCN', '', '噢！', 28153),
(144841, 'zhCN', '跟我说说宴会上发生了什么。', '跟我说说宴会上发生了什么。', 28153),
(144840, 'zhCN', '黑暗女王有件重要的活儿要你去做，$c。希望你准备好了……', '', 28153),
(144839, 'zhCN', '', '提帕托斯！', 28153),
(144838, 'zhCN', '', '朋友，请保证你不会离开我。即使这里变黑了也……', 28153),
(144837, 'zhCN', '', '但现在有你在，我们一起的话，就可以打跑他们了！也许吧……', 28153),
(144836, 'zhCN', '', '我不停地跑呀跑呀，但他们总会找到我。', 28153),
(144835, 'zhCN', '', '他们很快就会出现的，朋友。', 28153),
(144834, 'zhCN', '', '你在这儿！这下子好多啦。', 28153),
(144833, 'zhCN', '哈哈！提帕托斯看到你也很高兴！提帕托斯也有份礼物，看看这个小家伙，是在瓦尔莎拉找到的。', '', 28153),
(144832, 'zhCN', '你在开玩笑吧？！', '', 28153),
(144831, 'zhCN', '这些圆球似乎蕴含某种力量。如果我能剥开外壳……', '', 28153),
(144830, 'zhCN', '啊！', '', 28153),
(144829, 'zhCN', '这些眼睛看起来漂亮饱满。我只要挤下几滴……', '', 28153),
(144828, 'zhCN', '', '我好冷，这儿好黑，我不知道该怎么办！', 28153),
(144827, 'zhCN', '', '我不会放弃的，朋友！我保证！', 28153),
(144826, 'zhCN', '', '朋友？是你吗？', 28153),
(144825, 'zhCN', '我们的特工已经渗透进了下面的地精采掘行动，很快我们就知道他们想干什么了。', '', 28153),
(144824, 'zhCN', '应该……再挖……深一点……', '应该……再挖……深一点……', 28153),
(144823, 'zhCN', '一个精灵……挖挖挖……哈！', '一个精灵……挖挖挖……哈！', 28153),
(144822, 'zhCN', '你太迟了。我们发现了……', '你太迟了。我们发现了……', 28153),
(144821, 'zhCN', '谁找到就归谁……', '谁找到就归谁……', 28153),
(144820, 'zhCN', '你永远找不到它……', '你永远找不到它……', 28153),
(144819, 'zhCN', '你的冒险结束了。去死吧！', '你的冒险结束了。去死吧！', 28153),
(144818, 'zhCN', '我很乐意埋了你。', '我很乐意埋了你。', 28153),
(144817, 'zhCN', '我们要从下把你挖穿！', '我们要从下把你挖穿！', 28153),
(144816, 'zhCN', '你想和黑铁矮人对着干吗？大错特错。', '你想和黑铁矮人对着干吗？大错特错。', 28153),
(144815, 'zhCN', '多管闲事的精灵！这些遗迹属于黑铁部族！', '多管闲事的精灵！这些遗迹属于黑铁部族！', 28153),
(144812, 'zhCN', '', '敌人的援军就要来了！', 28153),
(144811, 'zhCN', '读数是毋庸置疑的！我们向西走！', '', 28153),
(144810, 'zhCN', '', '峡谷是我们的了！重整队形！我们必须计划好下一轮进攻。', 28153),
(144809, 'zhCN', '', '你想将一个方形图腾塞进圆形图腾的位置里。巫毒也懂感情，地精。', 28153),
(144808, 'zhCN', '他们从阴影里冒出来了，到处都是！', '他们从阴影里冒出来了，到处都是！', 28153),
(144807, 'zhCN', '', '这一点非常令人钦佩。所以我也很喜欢他。', 28153),
(144806, 'zhCN', '', '是的，就跟昨天一样，也跟前天……和更早一天一样！', 28153),
(144805, 'zhCN', '隧道已经安全。打开大门！', '', 28153),
(144804, 'zhCN', '今天他心情很好，不是吗？', '', 28153),
(144803, 'zhCN', '', '敌人来了！Bwonsalaka！', 28153),
(144802, 'zhCN', '我将回到其他人身边。我们必须尽全力阻止这一切。', '', 28153),
(144801, 'zhCN', '谢谢你，$p。恐怕事态比我们想象的还要糟。', '', 28153),
(144800, 'zhCN', '跟我说说雄狮之眠发生了什么。', '跟我说说雄狮之眠发生了什么。', 28153),
(144799, 'zhCN', '我的特工已经控制了这片区域。话虽如此，保持低调永远是明智的。', '', 28153),
(144798, 'zhCN', 'Bwon\'chaga di choka！', 'Bwon\'chaga di choka！', 28153),
(144796, 'zhCN', '', '巫毒可以触动所有心灵，卡拉，无论对方相信与否。', 28153),
(144795, 'zhCN', '', '巫毒可以让你了解恐龙的想法？真的！？', 28153),
(144794, 'zhCN', '', '这是恋爱问题，卡拉。就算是你的心，也比大脑更了解巫毒。', 28153),
(144792, 'zhCN', '你的意志是我的了！', '你的意志是我的了！', 28153),
(144791, 'zhCN', '蒸汽会告诉你真相！', '蒸汽会告诉你真相！', 28153),
(144790, 'zhCN', '深吸一口吧！', '深吸一口吧！', 28153),
(144789, 'zhCN', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t莱赞|cFFFF0000|Hspell:260683|h[唤醒]|h|r了所有剩余的骨堆！', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t莱赞|cFFFF0000|Hspell:260683|h[唤醒]|h|r了所有剩余的骨堆！', 28153),
(144788, 'zhCN', '', '戈霍恩……', 28153),
(144787, 'zhCN', '', '不……不能就这样……', 28153),
(144786, 'zhCN', '', '我的姐妹……会……给我……报仇……', 28153),
(144785, 'zhCN', '', 'Gachaga！', 28153),
(144784, 'zhCN', '', '祖达萨……必将……陨落……', 28153),
(144783, 'zhCN', '', '长母……请为我复仇……', 28153),
(144782, 'zhCN', '', '但我本来会成为最强……', 28153),
(144781, 'zhCN', '', 'Pohkiza……', 28153),
(144780, 'zhCN', '嗯，太棒了。', '', 28153),
(144779, 'zhCN', '药水做得很好，$n。现在，我只需要每种加上几滴， 然后……', '', 28153),
(144778, 'zhCN', '', '小菜一碟！', 28153),
(144777, 'zhCN', '', '我会给你个痛快！', 28153),
(144776, 'zhCN', '', '哈！你拿什么挑战我！', 28153),
(144775, 'zhCN', '', '又多了一件收藏品！', 28153),
(144774, 'zhCN', '', '这是我们的土地！', 28153),
(144773, 'zhCN', '快点！这里！我们还有工作要做！', '', 28153),
(144772, 'zhCN', '偶尔休息一下也不错。$B$B尤其是在经历了冒险，大赚一番后。', '', 28153),
(144771, 'zhCN', '先把那里的火扑灭，我看看实验室还需要些什么。噢，这下好玩了！', '', 28153),
(144770, 'zhCN', '我目前完全没东西可卖了。对不起。', '', 28153),
(144769, 'zhCN', '我有几个球要给你，艾尔里克。', '我有几个球要给你，艾尔里克。', 28153),
(144768, 'zhCN', '我有你要的草药。', '我有你要的草药。', 28153),
(144767, 'zhCN', '这是你要的眼睛。', '这是你要的眼睛。', 28153),
(144766, 'zhCN', '这是你要的药水。', '这是你要的药水。', 28153),
(144765, 'zhCN', '啊，炼金术师同行！也许我可以和你探讨一下我的几张最新配方。$b$b我的专长是药剂，但我偶尔也涉猎变形术。', '', 28153),
(144764, 'zhCN', '欢迎光临我的店铺，$c！要来杯提神的药剂吗？或者看上什么别的东西了？$b$b我的专长是药剂，但我偶尔也涉猎变形术。', '', 28153),
(144763, 'zhCN', '', '新鲜的肉！', 28153),
(144762, 'zhCN', '', '我要把你的耳朵串在项链上！', 28153),
(144761, 'zhCN', '', '给戈霍恩的鲜血！', 28153),
(144760, 'zhCN', '嘘！别动！他只能看到运动的东西。', '嘘！别动！他只能看到运动的东西。', 28153),
(144759, 'zhCN', '圣光保佑……他回来了。', '圣光保佑……他回来了。', 28153),
(144758, 'zhCN', '光铸守备官呻吟着。', '光铸守备官呻吟着。', 28153),
(144757, 'zhCN', '我还以为我已经失去了自己的心。', '我还以为我已经失去了自己的心。', 28153),
(144756, 'zhCN', '大地母亲护佑着你！', '大地母亲护佑着你！', 28153),
(144755, 'zhCN', '太可怕了，$r。', '太可怕了，$r。', 28153),
(144754, 'zhCN', '我一定……我的心灵……一定要离开这儿！', '我一定……我的心灵……一定要离开这儿！', 28153),
(144753, 'zhCN', '低语……把我逼疯了！', '低语……把我逼疯了！', 28153),
(144752, 'zhCN', '谢谢你，勇士。', '谢谢你，勇士。', 28153),
(144751, 'zhCN', '', '即使是最锋利的武器，使用太多也会变钝。好好休息你才能痊愈，提帕托斯。', 28153),
(144750, 'zhCN', '提帕托斯感谢丽萨拉。提帕托斯感觉可以重新战斗了！', '', 28153),
(144749, 'zhCN', '要阻止提帕托斯，这点火候还不够！', '', 28153),
(144748, 'zhCN', '带上我的人偶护身符吧。相信我，这是我最好的货。', '', 28153),
(144747, 'zhCN', '这真是件精致的假货！你从谁那里得来的？不要说名字！直接拿来给我。', '', 28153),
(144746, 'zhCN', '闭紧你的嘴巴，别泄露你是从哪里得到它的，否则我就让你知道，我的名头是怎么来的。', '', 28153),
(144745, 'zhCN', '', '提帕托斯， 你又来了？要多少次才……', 28153),
(144744, 'zhCN', '那不是什么普通暗夜精灵的头颅……她是数千年前的皇族！', '', 28153),
(144743, 'zhCN', '时间会揭晓一切。小心照顾那朵百年花，$p。每一百年只开一次花。', '', 28153),
(144742, 'zhCN', '', '金种子！我们必须立即为大王种植它们。你觉得会长出什么来，贾登？', 28153),
(144741, 'zhCN', '这胡椒正适合我的下一批特级辣椒……那些金种子尝起来像泥土！', '', 28153),
(144740, 'zhCN', '', '不是传说，是真的。露希尔女士决心要夺回我们的土地和人民。', 28153),
(144739, 'zhCN', '要是这样的话，我会全力支持她。', '', 28153),
(144738, 'zhCN', '她做到了？我还以为那只是个传说！', '', 28153),
(144737, 'zhCN', '', '我现在是审判官了，镇长。露希尔女士重建了灰烬骑士团以对抗那些女巫。', 28153),
(144736, 'zhCN', '非常感谢你及时出现在这里，中尉。', '', 28153),
(144735, 'zhCN', '', '谢谢，$p！我们的炉石差点缺货。吃点胡椒吧，免费的。', 28153),
(144734, 'zhCN', '你想干点儿活，$p？找人买下这些炉石。用它们去换点值钱的东西来，我不会让你白费时间的。', '', 28153),
(144733, 'zhCN', '你知道这意味着什么吗，免费的木材！', '', 28153),
(144732, 'zhCN', '喂，呃……长官？我得到报告，在我们伐木场附近有个大树一样的怪物在游荡。', '', 28153),
(144731, 'zhCN', '嘎嘎！你妈是个穴居人！嘎嘎！', '', 28153),
(144730, 'zhCN', '黄肚皮的旱鸭子！嘎嘎！', '', 28153),
(144729, 'zhCN', '嘎嘎！', '', 28153),
(144728, 'zhCN', '喂，$p，你是否曾经想要打扁某人的脸，却知道自己做不到？我有适合你的好东西！', '', 28153),
(144727, 'zhCN', '神奇的护身符！绝妙的珍玩！大客户购买有特价！', '', 28153),
(144726, 'zhCN', '这低语真动听啊。', '这低语真动听啊。', 28153),
(144725, 'zhCN', '暗影会吞噬你。', '暗影会吞噬你。', 28153),
(144724, 'zhCN', '祝福和战吼都已经过时！在当今这个危险而又严酷的世界里，只有艾泽里特可以给予你力量。快来喝瓶装艾泽里特吧！', '', 28153),
(144723, 'zhCN', '你必须死。', '你必须死。', 28153),
(144722, 'zhCN', '快停下！', '快停下！', 28153),
(144721, 'zhCN', '黑暗之王来了……', '黑暗之王来了……', 28153),
(144720, 'zhCN', '如果沃金在破碎海岸的时候带着他那可靠的无敌图腾，那么他今天还会活着。不要犯同样的错误！', '', 28153),
(144719, 'zhCN', '监视你的敌人，留意你的朋友，偷看皇家区……这款神奇的低语小精灵图腾都能做到！', '', 28153),
(144718, 'zhCN', '这个图腾的火焰从拉斯塔哈大王第一次坐上王座之后便点亮了。今天就把这段赞达拉历史收入囊中！', '', 28153),
(144717, 'zhCN', '格里伏塔的承诺：不提问，有折扣！', '', 28153),
(144716, 'zhCN', '提帕托斯在此！', '', 28153),
(144715, 'zhCN', '', '我觉得好多了。', 28153),
(144714, 'zhCN', '提帕托斯！', '', 28153),
(144713, 'zhCN', '', '不戴上王冠肯定没法打败黑暗，朋友。规则是这么说的。', 28153),
(144712, 'zhCN', '', '它会射出星星！坏人可讨厌星星了。', 28153),
(144711, 'zhCN', '我们是知识的守护者和收集者。\n\n我的工作就是确保我们的发现得到准确的记载。', '', 28153),
(144706, 'zhCN', '我还有很多事情要准备。干掉他们。', '我还有很多事情要准备。干掉他们。', 28153),
(144705, 'zhCN', '我厌倦这场闲聊了。', '我厌倦这场闲聊了。', 28153),
(144704, 'zhCN', '那都是谎言！', '', 28153),
(144703, 'zhCN', '你没有感觉到位于海底深处的伟大存在吗？只要遵循她的意志，我们将再度完整！', '你没有感觉到位于海底深处的伟大存在吗？只要遵循她的意志，我们将再度完整！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144702, 'zhCN', '我们曾宣誓保卫布伦纳丹。守护我们的人民！你忘记了吗？', '', 28153),
(144701, 'zhCN', '你总是这么软弱，无法为斯托颂勋爵效力，只能像个傻子一样，在布伦纳丹自生自灭。', '你总是这么软弱，无法为斯托颂勋爵效力，只能像个傻子一样，在布伦纳丹自生自灭。', 28153),
(144700, 'zhCN', '输的人是你！', '', 28153),
(144699, 'zhCN', '大海……会吞噬你……', '', 28153),
(144698, 'zhCN', '我的生命……献给……艾萨拉……', '', 28153),
(144697, 'zhCN', '深渊会带走你……', '', 28153),
(144696, 'zhCN', '女王陛下…… 我……失败了……', '', 28153),
(144695, 'zhCN', '潮水……退了……', '', 28153),
(144694, 'zhCN', '', '潮水……退了……', 28153),
(144693, 'zhCN', '', '我的女王…… 我……失败了……', 28153),
(144692, 'zhCN', '', '深渊会带走你……', 28153),
(144691, 'zhCN', '', '我的生命属于艾萨拉！', 28153),
(144690, 'zhCN', '', '大海……会吞噬你……', 28153),
(144689, 'zhCN', '我还有个问题……', '我还有个问题……', 28153),
(144688, 'zhCN', '看来你需要一个朋友。', '看来你需要一个朋友。', 28153),
(144687, 'zhCN', '你在干什么？', '你在干什么？', 28153),
(144686, 'zhCN', '我是来帮你的，库哥洛！', '我是来帮你的，库哥洛！', 28153),
(144685, 'zhCN', '你可以看看这个卷轴吗？', '你可以看看这个卷轴吗？', 28153),
(144684, 'zhCN', '省省力气吧，年轻人。\n\n不管你想要什么，我都没有时间。', '', 28153),
(144683, 'zhCN', '朋友？不需要，但助理？我需要。', '', 28153),
(144682, 'zhCN', '我可以告诉你我不做的事情，那就是在赶工的时候和一个$r聊天。', '', 28153),
(144681, 'zhCN', '这样的话，我希望你是个高效的多面手。', '', 28153),
(144680, 'zhCN', '我现在不做兼职。我的进度很落后了。这些卷轴可不会自己写字。', '', 28153),
(144679, 'zhCN', '我亏损了。', '', 28153),
(144678, 'zhCN', '', '<奥露乐的眼神变得恍惚。>$B$B如果哥哥看得到苏拉玛现在的模样……', 28153),
(144677, 'zhCN', '', '我感觉我们的城市很快会受到召唤。希望到了那时我已经做好了准备。', 28153),
(144676, 'zhCN', '没说服光铸者加入部落真是件憾事，他们的武力极其强大。', '', 28153),
(144675, 'zhCN', '我刚数到几？啊！', '', 28153),
(144674, 'zhCN', '有了维多利亚重新加入，暮色卫队会好起来的。', '', 28153),
(144673, 'zhCN', '', '我们走，勇士。', 28153),
(144672, 'zhCN', '很高兴看到奥露乐在继续训练，她已经变强了很多。$B$B也许我应该好好看看她到底进步了多少。', '', 28153),
(144671, 'zhCN', '时代的浪潮变了，修士。如果不加入我们，你必输无疑。', '时代的浪潮变了，修士。如果不加入我们，你必输无疑。', 28153),
(144670, 'zhCN', '一个给你。一个给我。', '', 28153),
(144669, 'zhCN', '做假账真好玩！', '', 28153),
(144668, 'zhCN', '雷德！舰队必须立刻回到库尔提拉斯！', '', 28153),
(144667, 'zhCN', '我是不是已经数过这堆了？', '', 28153),
(144666, 'zhCN', '一……二……七……赤字……二……', '', 28153),
(144665, 'zhCN', '', '我把话说清楚，我可是非常擅长炸东西的……在我的目标清单上，刚好有人的排名在急剧蹿升！', 28153),
(144664, 'zhCN', '', '你再来的话，就会碰到点小小的“意外”了。', 28153),
(144663, 'zhCN', '', '啊！你会付出代价的！', 28153),
(144662, 'zhCN', '', '再见，伙计。', 28153),
(144661, 'zhCN', '', '哈？说完了？', 28153),
(144660, 'zhCN', '', '再见啦！', 28153),
(144659, 'zhCN', '', '你想要什么，小家伙？', 28153),
(144658, 'zhCN', '', '准备好出发了？', 28153),
(144657, 'zhCN', '', '嘿，伙计，有事吗？', 28153),
(144656, 'zhCN', '大概这就是我的命吧。太棒了，真——是太棒了。', '', 28153),
(144655, 'zhCN', '所以你想跟我玩这个？真的吗？一直不停地戳啊戳啊戳啊戳啊戳啊……', '', 28153),
(144654, 'zhCN', '你真的无事可做了吗？比如，呃……可以去亲吻鱼人什么的？', '', 28153),
(144653, 'zhCN', '噢，拜托！稍微尊重我一下好吗？', '', 28153),
(144652, 'zhCN', '对，对……随便吧。', '', 28153),
(144651, 'zhCN', '好啦，走开吧……', '', 28153),
(144650, 'zhCN', '再见！', '', 28153),
(144649, 'zhCN', '锁定目标，弹药上膛！', '', 28153),
(144648, 'zhCN', '准备出发！', '', 28153),
(144647, 'zhCN', '你再摸一下，就让你少根手指。', '', 28153),
(144646, 'zhCN', '我真是快乐得不得了。', '', 28153),
(144645, 'zhCN', '嗨，我名叫补丁，但你可以叫我“长官”。', '', 28153),
(144644, 'zhCN', '杀鸡就该用牛刀。', '', 28153),
(144643, 'zhCN', '我喜欢达成目标的感觉。', '', 28153),
(144642, 'zhCN', '再见。', '', 28153),
(144641, 'zhCN', '有什么计划？', '', 28153),
(144640, 'zhCN', '有什么命令？', '', 28153),
(144639, 'zhCN', '哟！', '', 28153),
(144638, 'zhCN', '这是你的嗜好？如今谁都有个嗜好了。', '', 28153),
(144637, 'zhCN', '你想知道我的战利品都是怎么来的吗？', '', 28153),
(144636, 'zhCN', '可惜啊，“粉矛部族”这个名字已经被占用了。', '', 28153),
(144635, 'zhCN', '我的头不知道放哪了！差不多有，啊，这么大。如果你看到了，麻烦跟我说一下。', '', 28153),
(144634, 'zhCN', '需要帮忙的话，尽管找我吧。', '', 28153),
(144633, 'zhCN', '别跟巫毒扯上关系。', '', 28153),
(144632, 'zhCN', '当心背后。', '', 28153),
(144631, 'zhCN', '有什么事儿，老大？', '', 28153),
(144630, 'zhCN', '为了暗矛氏族！', '', 28153),
(144629, 'zhCN', '我听着呢。', '', 28153),
(144628, 'zhCN', '好吧……这是你自找的。开始进行宇宙结构重组。', '', 28153),
(144627, 'zhCN', '持续点击并不能使系统运转提速。', '', 28153),
(144626, 'zhCN', '新目标可能需要抑制。', '', 28153),
(144625, 'zhCN', '错误。请不要重新尝试。', '', 28153),
(144624, 'zhCN', '互动完成。', '', 28153),
(144623, 'zhCN', '恢复抑制协议。', '', 28153),
(144622, 'zhCN', '重新扫描。', '', 28153),
(144621, 'zhCN', '', '你好，$p！艾泽拉斯还有很多全新的土地和朋友在等待我们造访。$B$B欧库勒斯已经在楼下准备好了传送门，你准备好就出发吧。', 28153),
(144620, 'zhCN', '侦测到腐蚀。必须不惜一切将其抑制。', '', 28153),
(144619, 'zhCN', '高优先级协议：抑制腐蚀。', '', 28153),
(144618, 'zhCN', '赫兹雷尔单位上线。目标：抑制腐蚀。', '', 28153),
(144617, 'zhCN', '', '你这老一套……已经比我还老了！', 28153),
(144616, 'zhCN', '', '据说以前有个始祖龟发了疯，把缠着她的虫子踩扁了。', 28153),
(144614, 'zhCN', '', '你让我想打架了。', 28153),
(144613, 'zhCN', '', '说完了吗？', 28153),
(144612, 'zhCN', '', '下次别来缠着我了。', 28153),
(144611, 'zhCN', '', '终于说完了啊。', 28153),
(144610, 'zhCN', '', '呃，怎么了？', 28153),
(144609, 'zhCN', '', '你真的有话想跟我说？', 28153),
(144608, 'zhCN', '', '你这次想问什么？', 28153),
(144605, 'zhCN', '快走吧……否则我就拿你的灵魂抵债！', '', 28153),
(144604, 'zhCN', '给你一条忠告……绝对别跟死神做交易！', '', 28153),
(144603, 'zhCN', '别把你的魂儿丢了。', '', 28153),
(144602, 'zhCN', '现在得小心行事。', '', 28153),
(144601, 'zhCN', '当心。', '', 28153),
(144600, 'zhCN', '你好啊，外来者。', '', 28153),
(144599, 'zhCN', '你找汉扎布有何贵干？', '', 28153),
(144598, 'zhCN', '我还有很多事情要做。', '', 28153),
(144597, 'zhCN', '跟你说了停下！', '', 28153),
(144596, 'zhCN', '你的嗓音没你以为的那么悦耳。', '', 28153),
(144595, 'zhCN', '我气得快跳起来了！', '', 28153),
(144594, 'zhCN', '你不是来吻我的，是吧？', '', 28153),
(144593, 'zhCN', '后会有期。', '', 28153),
(144592, 'zhCN', '三思而后跳。', '', 28153),
(144591, 'zhCN', '愿你捉到鲜美的飞虫。', '', 28153),
(144590, 'zhCN', '有话就说。', '', 28153),
(144589, 'zhCN', '你想跟卡格瓦说话？', '', 28153),
(144588, 'zhCN', '有事吗，小家伙？', '', 28153),
(144587, 'zhCN', '再见……不会太久。', '', 28153),
(144586, 'zhCN', '滚吧！走开！', '', 28153),
(144585, 'zhCN', '所有人……迟早都会跟我见面。', '', 28153),
(144584, 'zhCN', '你看着有点渴。想喝点什么吗？要不要来杯血腥玛丽？哈哈哈！', '', 28153),
(144583, 'zhCN', '我看得见死人，这是我的神力使然。', '', 28153),
(144582, 'zhCN', '哼……有人好像很喜欢刺激。', '', 28153),
(144581, 'zhCN', '你最好小心点。别忘了是在跟谁打交道。', '', 28153),
(144580, 'zhCN', '你好，你好！你是来做交易的吗？', '', 28153),
(144579, 'zhCN', '你想问死神什么事？', '', 28153),
(144578, 'zhCN', '你来找孤独老人邦桑迪做什么？', '', 28153),
(144577, 'zhCN', '我准备好了。', '我准备好了。', 28153),
(144576, 'zhCN', '你必须尽快阻止这疯狂的局面，不然就太晚了。', '', 28153),
(144575, 'zhCN', '', '我要紧紧抱住他，这样他就再也不会迷路了。', 28153),
(144574, 'zhCN', '竟敢从我们的眼皮底下抢东西！胆大包天！', '', 28153),
(144573, 'zhCN', '不，不，不可能。根据我的计算，它应该——！！', '', 28153),
(144572, 'zhCN', '结果太奇怪了。如果这些——你叫他们什么来着？毛胡子？——能让我集中注意力就好了！', '', 28153),
(144571, 'zhCN', '我必须再试一次。你做得很好，尽管我以为我们的敌人会更加高大一点。', '', 28153),
(144570, 'zhCN', '我相信你能应付任何打扰，是吗？', '', 28153),
(144569, 'zhCN', '这边走！开始探测之后，我会集中所有的注意力。', '', 28153),
(144568, 'zhCN', '寂灭者阿古斯正在部署重组模块！', '寂灭者阿古斯正在部署重组模块！', 28153),
(144567, 'zhCN', '', '努儿来帮我们了，朋友。我就知道你会找到我们的，努儿！', 28153),
(144566, 'zhCN', '水渠受到了持续性的结构损伤，而且还有不稳定的能量残余。大门目前不能进入。', '水渠受到了持续性的结构损伤，而且还有不稳定的能量残余。大门目前处于关闭状态。', 28153),
(144565, 'zhCN', '我会继续看着他，他看起来很高兴，正在花园里游荡。', '我会继续看着他，他看起来很高兴，正在花园里游荡。', 28153),
(144564, 'zhCN', '', '很好！非常不错！', 28153),
(144563, 'zhCN', '', '对目标释放真气一开始是挺难的。你，对，前面那个，试试能不能击中那边的训练假人。', 28153),
(144562, 'zhCN', '喂，$pr……你想买东西吗？', '', 28153),
(144561, 'zhCN', '你手里那是什么，$p？是百年花吗？', '', 28153),
(144560, 'zhCN', '', '我们要开始为下个种植季节做准备了，贾登。', 28153),
(144559, 'zhCN', '嗯……这辣椒少了点什么……需要再加把火。', '', 28153),
(144558, 'zhCN', '', '赞查！你是不是又忘了补充炉石箱了？', 28153),
(144557, 'zhCN', '再见！', '', 28153),
(144556, 'zhCN', '祝你游泳愉快。', '', 28153),
(144555, 'zhCN', '水好酷啊。我可喜欢水了。你喜欢水吗？你最喜欢水的哪里？我最喜欢的是水很湿。水最酷了，我说得对吧？', '', 28153),
(144554, 'zhCN', '妈妈说我们是亮西……两西……啊，两栖类！呼，终于说对了！', '', 28153),
(144553, 'zhCN', '咕噜咕噜咕噜，龟壳滚来滚去。咕噜咕噜咕噜，四脚全都离地。', '', 28153),
(144552, 'zhCN', '等我长大了，要把世界上所有的书都读一遍！', '', 28153),
(144551, 'zhCN', '你们没有壳，是怎么背东西的呀？', '', 28153),
(144550, 'zhCN', '我好喜欢打滚呀！', '', 28153),
(144549, 'zhCN', '我很快就会像你那么老了！', '', 28153),
(144548, 'zhCN', '好，走吧。反正我也没什么想跟你说了。', '', 28153),
(144547, 'zhCN', '并不是海里所有的东西都像我这么英俊，像我这么好脾气。', '', 28153),
(144546, 'zhCN', '要是找到什么稀奇的宝贝，带给我看看。', '', 28153),
(144545, 'zhCN', '下次给我讲点更好的故事。', '', 28153),
(144544, 'zhCN', '我见过的东西可以把你的壳都吓没了。', '', 28153),
(144543, 'zhCN', '靠近点，好好说话。', '', 28153),
(144542, 'zhCN', '你好啊，不管你是先生还是女士。', '', 28153),
(144541, 'zhCN', '你有什么古董想卖给我吗？至少得有两百年历史才行。', '', 28153),
(144540, 'zhCN', '', '你这就要离开我了？！', 28153),
(144539, 'zhCN', '', '再见。', 28153),
(144538, 'zhCN', '', '有一次，我偷了匹羊驼，把它送到了神殿，但妈妈还是让我把它放走了。', 28153),
(144537, 'zhCN', '', '有一次，我打败了一个冒险者，还拿走了他的头骨。他比你都还要高大呢……', 28153),
(144536, 'zhCN', '', '有一次，我抓住了一头雷龙的尾巴。我让它带着我走了三十二加半口气那么远。', 28153),
(144535, 'zhCN', '一只恶毒的信天翁冲向正在孵化的蛋。', '', 28153),
(144534, 'zhCN', '', '有一次，我抓到一条细颚龙，非常非常非常非常非常非常大。大人们告诉我说，那是条暴掠龙，但我觉得他们在骗我。', 28153),
(144533, 'zhCN', '', '有一次，我抓到了一条好大的鱼，结果其实是个中了妖术的卫兵。', 28153),
(144532, 'zhCN', '', 'Taz\'okun！', 28153),
(144531, 'zhCN', '', 'Taz\'dingo！', 28153),
(144530, 'zhCN', '', '我的洛阿神灵比你的厉害多了！', 28153),
(144529, 'zhCN', '', '我长大了也要当洛阿神灵！', 28153),
(144528, 'zhCN', '再见，新朋友。', '', 28153),
(144527, 'zhCN', '你要去哪儿？', '', 28153),
(144526, 'zhCN', '洛阿神灵太酷了。他们好多都非常大，可以一口把你吃掉！', '', 28153),
(144525, 'zhCN', '我长大了要当个雷龙德鲁伊。吼！', '', 28153),
(144524, 'zhCN', '我有十根脚趾……其中只有四根是我的。', '', 28153),
(144523, 'zhCN', '有人把我那箱皱缩的头偷走了。是你干的吗？', '', 28153),
(144522, 'zhCN', '你好。', '', 28153),
(144521, 'zhCN', 'Taz\'okun！', '', 28153),
(144520, 'zhCN', 'Taz\'dingo！', '', 28153),
(144519, 'zhCN', '啊呜！', '', 28153),
(144518, 'zhCN', '这里的洛阿神灵很强大。', '这里的洛阿神灵很强大。', 28153),
(144517, 'zhCN', '万灵与你同在。', '万灵与你同在。', 28153),
(144516, 'zhCN', '洛阿神灵永远注视着你。', '洛阿神灵永远注视着你。', 28153),
(144515, 'zhCN', '呸！吃我两拳，让你睡到明天！', '呸！吃我两拳，让你睡到明天！', 28153),
(144513, 'zhCN', '你这么做是在玩命！', '你这么做是在玩命！', 28153),
(144512, 'zhCN', '这儿的货有最好的魂能。', '这儿的货有最好的魂能。', 28153),
(144511, 'zhCN', '万灵低语着你的名字。', '万灵低语着你的名字。', 28153),
(144510, 'zhCN', '你信的是哪个洛阿神灵？', '你信的是哪个洛阿神灵？', 28153),
(144509, 'zhCN', '', '出击！为了赞达拉的未来！', 28153),
(144508, 'zhCN', '呃，这种见面方式真丢人……我最好赶紧回去，否则库哥洛会生气的。', '', 28153),
(144498, 'zhCN', '赞达拉永不陷落。', '赞达拉永不陷落。', 28153),
(144497, 'zhCN', '永远别在弱者面前退缩。', '', 28153),
(144496, 'zhCN', '给你的敌人带去伤口吧。', '', 28153),
(144495, 'zhCN', '愿你啃食敌人的血肉。', '', 28153),
(144494, 'zhCN', '怎么了，部落的孩子？', '', 28153),
(144493, 'zhCN', '你进入了我的领地。', '', 28153),
(144492, 'zhCN', '你是猎人，还是猎物？', '', 28153),
(144491, 'zhCN', '你是来做交易的吗？', '', 28153),
(144490, 'zhCN', '歌颂我吧。', '', 28153),
(144489, 'zhCN', '愿你的敌人永远嗅不出你的降临。', '', 28153),
(144488, 'zhCN', '为你的兽群带来力量吧。', '', 28153),
(144486, 'zhCN', '如果你想逃跑，别忘了……我是会开门的。', '', 28153),
(144484, 'zhCN', '你再说一句，就会成为我肚里的美餐。', '', 28153),
(144481, 'zhCN', '我乃变形大师，兽群奔行者，狩猎之王。', '', 28153),
(144480, 'zhCN', '你因何来见狩猎之王？', '', 28153),
(144479, 'zhCN', '你是来做交易的吗？', '', 28153),
(144478, 'zhCN', '', '愿你一路顺风……离我越远越好。', 28153),
(144477, 'zhCN', '', '记住，天空是我的领域。', 28153),
(144476, 'zhCN', '', '愿你如死神天降。', 28153),
(144475, 'zhCN', '', '风就是我的意志。', 28153),
(144474, 'zhCN', '', '我要把你抓到空中……然后扔到一块石头上！', 28153),
(144473, 'zhCN', '', '你是要惹我生气吗？', 28153),
(144472, 'zhCN', '', '你在考验我的耐心，年轻人。', 28153),
(144471, 'zhCN', '', '为什么我非得闻你呼出的气？', 28153),
(144470, 'zhCN', '', '怎么了，孩子？', 28153),
(144469, 'zhCN', '', '你是来做交易的吗？', 28153),
(144468, 'zhCN', '', '喂，$pr……你厌倦细颚龙的外表了吗？我的魔精可以让你变成一头魔暴龙！', 28153),
(144462, 'zhCN', '', '要慎重选择你的神灵。', 28153),
(144461, 'zhCN', '', '愿你永远可以找到敌人的行踪。', 28153),
(144460, 'zhCN', '', '为了兽群。', 28153),
(144459, 'zhCN', '', '永远不要驯服你心中的野兽。', 28153),
(144458, 'zhCN', '', '到野外走走吧。', 28153),
(144457, 'zhCN', '', '待在附近，一会儿我可能还用得着你。', 28153),
(144456, 'zhCN', '', '啊，我受不了了。', 28153),
(144455, 'zhCN', '', '那么继续吧。', 28153),
(144454, 'zhCN', '', '如果你继续这样做，我丈夫是会嫉妒的。', 28153),
(144453, 'zhCN', '', '有没有到野外走走？', 28153),
(144452, 'zhCN', '该我亲手来解决问题了。我不会让你毁了这笔交易！', '', 28153),
(144451, 'zhCN', '谢谢你，$n。看来像库哥洛挺忙的。现在……这些卷轴怎么办？', '', 28153),
(144450, 'zhCN', '', '这里的洛阿神灵很强大。', 28153),
(144449, 'zhCN', '', '你就穿成这样四处闲逛吗？', 28153),
(144448, 'zhCN', '你不是我的联系人！进来，兄弟们，这里有新鲜的肉！', '', 28153),
(144447, 'zhCN', '', '我效忠于变形大师贡克。', 28153),
(144446, 'zhCN', '<将卷轴交给依托卡。>', '<将卷轴交给依托卡。>', 28153),
(144445, 'zhCN', '', '如果努儿也在就好了，它一定知道该怎么做。', 28153),
(144444, 'zhCN', '', '哦，嗨！你是谁？我是尤娜。我们可以做朋友吗？如果我们一起努力，也许就能走出去了。', 28153),
(144443, 'zhCN', '喂！我有正适合你的东西。祖尔的私人细颚龙守卫！将那些扒窃的恶棍赶走！', '', 28153),
(144442, 'zhCN', '', '太亮了！太亮了！啊啊啊！', 28153),
(144441, 'zhCN', '祝福你，旅行者。\n\n放下你的武器，休息一会儿吧。\n\n战争不差这一会。', '', 28153),
(144440, 'zhCN', '你好，帕库拉艾！', '', 28153),
(144439, 'zhCN', '要慎重地选择你的神灵。', '', 28153),
(144438, 'zhCN', '神灵有话说得好……走开。', '', 28153),
(144437, 'zhCN', '愿帕库总能发现敌人的踪影。', '', 28153),
(144436, 'zhCN', '愿战争之风永远为你带来胜利。', '', 28153),
(144435, 'zhCN', '妙极了！就是那儿！', '', 28153),
(144434, 'zhCN', '哦耶，继续……再靠右一点……', '', 28153),
(144433, 'zhCN', '如果我老婆也像你这样喜欢缠着我就好了。', '', 28153),
(144432, 'zhCN', '神灵有话说得好……别去摸那个！', '', 28153),
(144431, 'zhCN', '神灵有话说得好……快躲！哈哈哈哈！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144430, 'zhCN', '想与翼手龙一起飞翔吗？', '', 28153),
(144429, 'zhCN', '天空就是我的眼睛。', '', 28153),
(144428, 'zhCN', '我侍奉帕库，她是最古老的洛阿神灵之一。', '', 28153),
(144427, 'zhCN', '', '我会为无力自保的人民挺身而战。', 28153),
(144425, 'zhCN', '我们都有自己的角色，你也一样。', '', 28153),
(144424, 'zhCN', '我见证了这个时代的许多大事，而每件中都有你。真奇妙。', '', 28153),
(144423, 'zhCN', '黑暗即将到来。', '', 28153),
(144422, 'zhCN', '这很可怕，伙计。真的。', '', 28153),
(144421, 'zhCN', '巨魔帝国将再次崛起。我已经预见到了。', '', 28153),
(144420, 'zhCN', '巨魔将是这个世界最初以及最后的统治者。', '', 28153),
(144419, 'zhCN', '命运没有青睐你，朋友。', '', 28153),
(144418, 'zhCN', '我知道你要说什么，所以直说吧。', '', 28153),
(144417, 'zhCN', '我见证过世界的末日，你不会喜欢的。', '', 28153),
(144416, 'zhCN', '', '赞达拉永不陷落。', 28153),
(144415, 'zhCN', '', '要为逝者复仇。', 28153),
(144414, 'zhCN', '', '愿你以敌人的颅骨装饰自己的铠甲。', 28153),
(144413, 'zhCN', '', '时代变了，赞达拉也得改变。', 28153),
(144412, 'zhCN', '', '还有很多事要忙。有话快说。', 28153),
(144411, 'zhCN', '愿你让敌人闻风丧胆。', '', 28153),
(144410, 'zhCN', '赞达拉万古长存。', '', 28153),
(144409, 'zhCN', '愿莱赞赐予你力量。', '', 28153),
(144408, 'zhCN', '当大王的感觉真好。', '', 28153),
(144407, 'zhCN', '你正站在拉斯塔哈大王面前。', '', 28153),
(144406, 'zhCN', '欢迎来到祖达萨。', '', 28153),
(144405, 'zhCN', '你是猎人……还是猎物？', '', 28153),
(144404, 'zhCN', '', '我如果可以看清东西就好了，这里总是黑乎乎的！', 28153),
(144403, 'zhCN', '', '但你是我的朋友，我知道，一切都会好起来的。', 28153),
(144402, 'zhCN', '', '至少我们在一起了。我们只是……不知道自己在哪而已。', 28153),
(144401, 'zhCN', '', '救命！救命！', 28153),
(144400, 'zhCN', '', '你是谁？你能帮帮我吗？', 28153),
(144399, 'zhCN', '', '好黑啊！我什么都看不到！', 28153),
(144397, 'zhCN', '', '艾利桑德的事情终于告一段落，但这座城市接下来还需要很多变化。', 28153),
(144396, 'zhCN', '', '夜之子真正获得了自由，我们再也不需要暗夜井和它的力量。$B$B我们可以塑造自己的命运。', 28153),
(144395, 'zhCN', '我带来了一些样品，足以驳斥关于我们的葡萄酒的谣言。我们的酒尝起来并没有脚味……我是说较为……苦涩！', '', 28153),
(144394, 'zhCN', '我们的一些酒商不再打理葡萄，转而种起了其他植物。', '', 28153),
(144393, 'zhCN', '啊，我们抵达的时候，那群鲜血巨魔正和卫兵激战。他们没料到会腹背受敌。', '', 28153),
(144392, 'zhCN', '哇，那家伙真大。我需要你帮我打败他！', '', 28153),
(144391, 'zhCN', '如果你看到一群野猪人，就扔个棘刺炸弹，让他们自食其果！', '', 28153),
(144390, 'zhCN', '我打赌那很疼，不是吗！离开我的土地！', '', 28153),
(144389, 'zhCN', '哈，正中眉心！', '', 28153),
(144388, 'zhCN', '你可以回去告诉罗兹我没事，但我永远不会离开我的农场。我永远不会离开他们。', '', 28153),
(144387, 'zhCN', '嗯，那样就行了。他们一向很喜欢这个地方……', '', 28153),
(144386, 'zhCN', '你可以使用奥格瑞玛传送门前往卡利姆多的主城，结识部落的盟友。', '', 28153),
(144385, 'zhCN', '', '洛坎！你还好吗？这儿好像发生了一场大战。', 28153),
(144384, 'zhCN', '我听说达拉然有层楼全都是魔法传送门。$B$B光是想想都叫人激动！', '', 28153),
(144383, 'zhCN', '维持这些传送门非常累，而且更重要的是，我们会因此分心，不能从事宝贵的研究！$B$B我相信利用传送道标可以达成更稳妥的解决方案。', '', 28153),
(144382, 'zhCN', '谁说地精没有文化？', '', 28153),
(144381, 'zhCN', '他们甚至有一个我们的鼓！', '', 28153),
(144380, 'zhCN', '……然后找个没人的鼓！', '', 28153),
(144379, 'zhCN', '欢迎光临醉酒鼓手，$pr！来喝一杯吧……', '', 28153),
(144378, 'zhCN', '啊！我以为我的计划万无一失，伙计！', '', 28153),
(144377, 'zhCN', '蠢货！你会为从我的桥下经过付出代价！', '', 28153),
(144376, 'zhCN', '嘿，伙计！你正经过我的桥，伙计。付巨魔过路费，伙计，否则就用鲜血补偿吧，伙计！', '', 28153),
(144375, 'zhCN', '我准备开始试炼了。', '我准备开始试炼了。', 28153),
(144374, 'zhCN', '', '如果我们给它们绑上炸药会怎么样？会很好笑……爆炸的恐龙！', 28153),
(144373, 'zhCN', '', '我很欣赏你的热情，舒佳。但我确信，赞达拉巨魔更希望他们的武器灌注强大的魔法，而非滴油的丑东西。', 28153),
(144372, 'zhCN', '我们……我们变成了什么？', '', 28153),
(144371, 'zhCN', '', '不！放开我！救命，朋友！救命！', 28153),
(144370, 'zhCN', '', '又变黑了！你去哪儿了？别离开我！', 28153),
(144369, 'zhCN', '', '我以前也有这样的魔杖！但我好久以前就把它弄丢了。', 28153),
(144368, 'zhCN', '', '王冠！好漂亮！', 28153),
(144367, 'zhCN', '', '努儿！我还以为再也看不到你了！你怎么也到这儿来了？', 28153),
(144366, 'zhCN', '', '亮了一点！我好像……看得见了。', 28153),
(144365, 'zhCN', '', '那是什么？黑暗里的光！好亮啊……', 28153),
(144364, 'zhCN', '她……承诺过……', '', 28153),
(144363, 'zhCN', '她说这样我们就能在一起了！', '', 28153),
(144362, 'zhCN', '', '我们身后有洛阿神灵，心中有无限勇气。我们必将胜利！', 28153),
(144361, 'zhCN', '', '我们要消灭鲜血巨魔，我们绝对不能让他们召唤出来的怪物来袭击我们！', 28153),
(144360, 'zhCN', '', '敌人想摧毁我们珍视的一切，我们绝不能让他们得逞！今天的这场战斗，将决定赞达拉的未来！', 28153),
(144359, 'zhCN', '', '士兵们……朋友们。我们经历了许多苦难，但决战终于近在眼前。', 28153),
(144358, 'zhCN', '告诉我能去哪里。', '告诉我能去哪里。', 28153),
(144357, 'zhCN', '你在找渡船吗？', '你在找渡船吗？', 28153),
(144356, 'zhCN', '', '幸好我穿着靴子。', 28153),
(144355, 'zhCN', '我会带领一些始祖龟步行前往祖尔加，祝你们两位好运。', '', 28153),
(144354, 'zhCN', '无论生死，为了部落！', '无论生死，为了部落！', 28153),
(144353, 'zhCN', '鲜血与荣耀！', '鲜血与荣耀！', 28153),
(144352, 'zhCN', '阿拉希属于部落！', '阿拉希属于部落！', 28153),
(144351, 'zhCN', '跟我走！', '跟我走！', 28153),
(144350, 'zhCN', '联盟必死！', '联盟必死！', 28153),
(144349, 'zhCN', '为了部落！', '为了部落！', 28153),
(144348, 'zhCN', '这边！前往战场！', '这边！前往战场！', 28153),
(144347, 'zhCN', '步兵，快点！我们要赢下这场战斗！', '步兵，快点！我们要赢下这场战斗！', 28153),
(144346, 'zhCN', '我是格罗尔。', '', 28153),
(144345, 'zhCN', '你会在南方找到我的神殿的遗迹，我在那里等你，我们一起让这些纳迦尝尝鲨鱼神灵的愤怒！', '', 28153),
(144344, 'zhCN', '哦……你真美味。', '', 28153),
(144343, 'zhCN', '你只配最为黑暗的深渊！', '', 28153),
(144342, 'zhCN', '阿塔格罗尔不欢迎纳迦！', '', 28153),
(144341, 'zhCN', '充满愤怒的纳迦鲜血气息，浓烈而美味……香甜可口……我会加入的。', '', 28153),
(144340, 'zhCN', '', '母亲, 本杰明把一切都告诉我了。\n\n你之前不听到我说话，现在也许可以了？我只想要一个解释。', 28153),
(144339, 'zhCN', '', '母亲，我知道你不在这里。但是如果你能听到我说的话……', 28153),
(144338, 'zhCN', '我也许不是个优秀的管理者，但母亲非常出色。现在看到她堕落至此……$b$b我们正在逐渐恢复，$n。多谢你的帮助。', '', 28153),
(144337, 'zhCN', '', '你要去哪儿？', 28153),
(144336, 'zhCN', '', '求你了，别离开我！', 28153),
(144335, 'zhCN', '隐藏在潮汐之下的主人会带领我们所有人走向胜利！', '潮汐之下的主人会带领我们走向胜利！', 28153),
(144334, 'zhCN', '看到你们都没缺胳膊少腿真是太好了……嘿，我们的女英雄来了！', '', 28153),
(144333, 'zhCN', '你要留下还是离开？', '', 28153),
(144332, 'zhCN', '抱歉。我必须找到我的姐姐。', '', 28153),
(144331, 'zhCN', '父亲去世后，母亲失踪了。但我从没想过……', '', 28153),
(144330, 'zhCN', '她和我父亲忙碌一生建立起这份事业，并养育我和姐姐长大。', '', 28153),
(144329, 'zhCN', '那个女巫……她是我的母亲。', '', 28153),
(144328, 'zhCN', '你似乎很懂该怎么应对野兽。你需要什么？', '', 28153),
(144327, 'zhCN', '这次是什么事？你弄丢东西了？', '', 28153),
(144326, 'zhCN', '太棒了！再来一次，从头开始。', '', 28153),
(144325, 'zhCN', '一次消耗太多能量是有风险的。记得把握节奏，弟子们。', '', 28153),
(144324, 'zhCN', '把真气集中起来后，它就会变得极其强大。你准备好后，李涛大师会指导你的。', '', 28153),
(144323, 'zhCN', '治疗时，你必须聚集你内心的力量，然后把它传递到另一个人身上。', '', 28153),
(144322, 'zhCN', '我们不用付出“一切”，真是太好了。', '我们不用付出“一切”，真是太好了。', 28153),
(144321, 'zhCN', '我们被腐化的兄弟姐妹还在荒野里游荡。', '我们被腐化的兄弟姐妹还在荒野里游荡。', 28153),
(144320, 'zhCN', '', '誓死……效忠部落。', 28153),
(144319, 'zhCN', '', '待会儿见，我的朋友。', 28153),
(144318, 'zhCN', '', '鲜血与雷鸣！', 28153),
(144317, 'zhCN', '', '我要砍死你。', 28153),
(144316, 'zhCN', '', '我的利刃渴望着你的鲜血！', 28153),
(144315, 'zhCN', '', '你的力量无法与兽人相提并论！', 28153),
(144314, 'zhCN', '', '你的骨头再硬，也比不过我的利刃！', 28153),
(144313, 'zhCN', '', '守住战线！别放任何人过来！', 28153),
(144312, 'zhCN', '谢谢你，朋友。', '', 28153),
(144311, 'zhCN', '如果下次见面时我不记得你，我很抱歉。', '', 28153),
(144310, 'zhCN', '感谢你解决掉了图鲁克。他不愿面对自己追寻的力量背后的危险。', '感谢你解决掉了图鲁克。他不愿面对自己追寻的力量背后的危险。', 28153),
(144309, 'zhCN', '<牛头人熟睡着，鼾声如雷，然后翻了个身。>', '<牛头人熟睡着，鼾声如雷，然后翻了个身。>', 28153),
(144308, 'zhCN', '呼……', '呼……', 28153),
(144307, 'zhCN', '我会，公主。至死方休。', '', 28153),
(144306, 'zhCN', '', '这是拯救我的人民的唯一方法，洛坎。我愿意为人民的安全付出一切。你会跟随我吗？', 28153),
(144305, 'zhCN', '我还是无法相信，我的兄弟姐妹居然屈服于邪能。', '我还是无法相信，我的兄弟姐妹居然屈服于邪能。', 28153),
(144304, 'zhCN', '', '女儿们，准备招待客人吧！', 28153),
(144303, 'zhCN', '', '鲜血……会为我复仇……', 28153),
(144302, 'zhCN', '', '为了战争之母！', 28153),
(144301, 'zhCN', '现在，集中你的真气。把能量推出去。', '', 28153),
(144300, 'zhCN', '', '灵魂将被剥离你的肉体！', 28153),
(144299, 'zhCN', '', '把你抽干一定很有意思。', 28153),
(144298, 'zhCN', '', '你的鲜血是我们的原料！', 28153),
(144297, 'zhCN', '', '我要抽干你的血，然后让你的躯壳腐烂凋零！', 28153),
(144296, 'zhCN', '', '你的鲜血会滋润我的利刃。', 28153),
(144295, 'zhCN', '如果你想搭便车，就来找我吧！', '', 28153),
(144294, 'zhCN', '', '吟血者又有鲜血可用了！', 28153),
(144293, 'zhCN', '', '你的皮可以做成上好的挽具！', 28153),
(144292, 'zhCN', '', '天空……在召唤我。', 28153),
(144291, 'zhCN', '', '今天是战斗的好日子。', 28153),
(144290, 'zhCN', '', '抱齿兽今晚可以美餐一顿了！', 28153),
(144289, 'zhCN', '坚持住！我去看看萨塔奥。', '', 28153),
(144288, 'zhCN', '记录——软泥实验。\n\n活化软泥已获得成功。它们可以完全依靠蜂蜜生存，无需溶解肉类或植物等有机物。它们产出的大量废料可以在桶中发酵，创造出一种特别浓烈且美味的蜂蜜酒。\n\n但如果不对软泥进行适当的控制，它们会扩张，最终吞噬掉整个蜂巢。在此过程中，它们往往变得更具攻击性，并逐渐失控。\n\n为此，蜜蜂自然会提高防备，变得更难应付。很明显，我最终需要制定一个解决方法，因为蜜蜂可不容易替换。', '', 28153),
(144287, 'zhCN', '', 'Pohkiza……', 28153),
(144286, 'zhCN', '', '万物……都属于……血神……', 28153),
(144285, 'zhCN', '', '哈哈哈！', 28153),
(144284, 'zhCN', '', '祖达萨……必将……陨落……', 28153),
(144283, 'zhCN', '', 'Gachaga！', 28153),
(144282, 'zhCN', '', '我的姐妹……会……为我……复仇……', 28153),
(144281, 'zhCN', '', '我的血……属于……戈霍恩！', 28153),
(144280, 'zhCN', '', '戈霍恩！', 28153),
(144279, 'zhCN', '<曾加亲热地对着你呼噜。>', '', 28153),
(144278, 'zhCN', '我从迷雾中前来，警告赞达拉的人民。艾泽里特让猩猩获得了智慧。智慧将带来战争。', '', 28153),
(144277, 'zhCN', 'Pohkiza……', '', 28153),
(144276, 'zhCN', '万物……都属于……血神……', '', 28153),
(144275, 'zhCN', '你……已经……失败了……', '', 28153),
(144274, 'zhCN', '祖达萨……必将……陨落……', '', 28153),
(144273, 'zhCN', 'Gachaga！', '', 28153),
(144272, 'zhCN', '我的生命属于母亲！', '', 28153),
(144271, 'zhCN', '我的血……属于……戈霍恩！', '', 28153),
(144270, 'zhCN', '戈霍恩！', '', 28153),
(144269, 'zhCN', '很好。很好。再来！', '', 28153),
(144268, 'zhCN', '别慌。', '', 28153),
(144266, 'zhCN', '', '我先去村子的防御工事帮忙，我们等下在那里会合！', 28153),
(144265, 'zhCN', '', '我们击溃了他们。来！我们应该和罗伊斯顿镇长谈谈。', 28153),
(144264, 'zhCN', '', '奥蕾莉亚叹了口气，眉头紧锁。', 28153),
(144263, 'zhCN', '<驻足聆听。>', '<驻足聆听。>', 28153),
(144262, 'zhCN', '', '<奥蕾莉亚的目光从石雕的冰冷面孔移到下方的铭牌，上面刻着她的墓志铭。>', 28153),
(144261, 'zhCN', '站稳脚跟，守住阵线！', '站稳脚跟，守住阵线！', 28153),
(144260, 'zhCN', '罗恩柯尔临终的气息散去，你听到一阵轻声哭泣。', '', 28153),
(144259, 'zhCN', '', '我会用你的肚皮做一顶新帽子！', 28153),
(144258, 'zhCN', '', '不！我的宝贝！', 28153),
(144257, 'zhCN', '', '别伤害小宝贝！你别想离开这个洞窟！', 28153),
(144256, 'zhCN', '', '他们想杀死我们！我的宠物，吃掉他们！', 28153),
(144255, 'zhCN', '邦桑迪……饶了我吧！', '邦桑迪……饶了我吧！', 28153),
(144254, 'zhCN', '赞达拉……万古长存……', '赞达拉……万古长存……', 28153),
(144253, 'zhCN', '我们要让你安息，尤洛克！弄成这个样子我很抱歉。', '', 28153),
(144252, 'zhCN', '什么……尤洛克身体里的这些东西是什么？', '', 28153),
(144251, 'zhCN', '就要成功了！只要拿到我的装备……', '', 28153),
(144250, 'zhCN', '不应该这样……', '不应该这样……', 28153),
(144249, 'zhCN', '邦桑迪……来……接我了……', '邦桑迪……来……接我了……', 28153),
(144248, 'zhCN', '保持队形，更多敌人来袭！', '保持队形，更多敌人来袭！', 28153),
(144247, 'zhCN', '我的……生命……献给赞达拉……', '我的……生命……献给赞达拉……', 28153),
(144245, 'zhCN', 'Di chuka Zandalar！', 'Di chuka Zandalar！', 28153),
(144243, 'zhCN', '杀光他们！', '杀光他们！', 28153),
(144242, 'zhCN', '为了真正的赞达拉！', '为了真正的赞达拉！', 28153),
(144240, 'zhCN', '你的血会滋养我们的土地！', '你的血会滋养我们的土地！', 28153),
(144239, 'zhCN', '我们会替你收尸的！', '我们会替你收尸的！', 28153),
(144238, 'zhCN', '你会死在这儿！', '你会死在这儿！', 28153),
(144237, 'zhCN', '赞达拉万古长存！', '赞达拉万古长存！', 28153),
(144236, 'zhCN', '公主说要找到怪物，这里全都是怪物！', '', 28153),
(144235, 'zhCN', '太阳哪儿去了？在这片烂沼泽里我什么都看不到。', '', 28153),
(144234, 'zhCN', '真荒唐！我看见了一个大洞，可地图上没有这个洞！', '', 28153),
(144233, 'zhCN', '哦！这……什么都不是……真令人失望。', '', 28153),
(144232, 'zhCN', 'Taz\'okun！这也许是一块艾泽里特！', '', 28153),
(144231, 'zhCN', '这是一种针吗？啊，为什么这么粘？', '', 28153),
(144230, 'zhCN', '哦，这可真漂亮，塔兰吉肯定会喜欢的。', '', 28153),
(144229, 'zhCN', '妖仆弩手发现你了！快躲开！', '', 28153),
(144228, 'zhCN', '原来这里不需要造这么多兵器的，但我特别喜欢造剑。不过说真的，我并不喜欢我们需要武器的原因。', '', 28153),
(144227, 'zhCN', '我明白为什么人们害怕沼泽了。', '', 28153),
(144226, 'zhCN', '真怪。', '', 28153),
(144225, 'zhCN', '我想手上的这些烂泥再也弄不掉了，我可怜的卷轴。', '', 28153),
(144224, 'zhCN', '这块石头很奇怪……噢！它动了！', '', 28153),
(144223, 'zhCN', '相当精彩！', '', 28153),
(144222, 'zhCN', '愿贡克指引你。', '愿贡克指引你。', 28153),
(144221, 'zhCN', '愿帕库护佑着你。', '愿帕库护佑着你。', 28153),
(144220, 'zhCN', '愿莱赞赐予你力量。', '愿莱赞赐予你力量。', 28153),
(144219, 'zhCN', '走路小心。', '走路小心。', 28153),
(144218, 'zhCN', '在我们的城市里要小心。', '在我们的城市里要小心。', 28153),
(144217, 'zhCN', '赞达拉万古长存！', '赞达拉万古长存！', 28153),
(144216, 'zhCN', '你需要保护吗？', '你需要保护吗？', 28153),
(144215, 'zhCN', '再也没有比我这儿更实惠的了。', '再也没有比我这更实惠的了。', 28153),
(144214, 'zhCN', '你来此有何贵干？', '你来此有何贵干？', 28153),
(144213, 'zhCN', '你好。', '你好。', 28153),
(144209, 'zhCN', '我发誓要守护皇室。', '我发誓要守护皇室。', 28153),
(144208, 'zhCN', '我们的王国会击败外敌。', '我们的王国会击败外敌。', 28153),
(144201, 'zhCN', '我们开始吧。', '我们开始吧。', 28153),
(144200, 'zhCN', '我们现在非常接近了，$n。$b$b只要你发令，我就开始探测。$b$b哦，我忘了说了。我们的宿敌在对面的海滩上扎营了。我会密切注意周围的环境，以防我们遭到伏击。$b$b如果有人干扰，我相信你会保护我的！', '', 28153),
(144199, 'zhCN', '各位，坚持住！我们要击退这群混蛋！', '', 28153),
(144198, 'zhCN', '天就要黑了！不要让那些营火灭掉！缺燃料就喊一声。', '', 28153),
(144197, 'zhCN', '别放任何怪物过来！我们干掉了他们那个大家伙，但损失的船太多了。', '', 28153),
(144196, 'zhCN', '休息够了，就到防线上换岗！我们要击退那帮恶魔！', '', 28153),
(144195, 'zhCN', '我需要志愿者找到艾什顿！也许他能制作一些信号弹。', '', 28153),
(144194, 'zhCN', '先把食物分给孩子，然后给伤员！', '', 28153),
(144193, 'zhCN', '治疗者要轮流休息！也包括你，克瑞斯婷！', '', 28153),
(144192, 'zhCN', '加固防线！把没钉死的东西都拆下来，要是还不够，就开始拔钉子！', '', 28153),
(144191, 'zhCN', '小抱齿兽用脚摩擦着莲叶，发出奇怪的声音。', '', 28153),
(144190, 'zhCN', '那些水手应该把时间花在监视部落上，而不是我们。', '那些水手应该把时间花在监视部落上，而不是我们。', 28153),
(144189, 'zhCN', '我们最好尽快找到我们要的东西，然后扬帆离开，越早越好。', '我们最好尽快找到我们要的东西，然后扬帆离开，越早越好。', 28153),
(144188, 'zhCN', '部落来了，小心点！', '部落来了，小心点！', 28153),
(144187, 'zhCN', '我真希望探险者协派再多派点人加入这次的探险。', '我真希望探险者协派再多派点人加入这次的探险。', 28153),
(144186, 'zhCN', '如果我们不来这里监视黑铁矮人，谁知道他们会干些什么？', '如果我们不来这里监视黑铁矮人，谁知道他们会干些什么？', 28153),
(144185, 'zhCN', '', '还有它们的孩子！我可以组装一个照相亭和恐龙玩具。当然也有你的份，贾拉尔。我七你三怎么样。毕竟主意是我出的。', 28153),
(144184, 'zhCN', '如果你愿意帮忙的话，前面还有一个需要帮助的人。', '', 28153),
(144183, 'zhCN', '', '自我再利用：是时候使用注射器激怒本金，然后跟着他，帮助他消灭入侵物种了。', 28153),
(144182, 'zhCN', '等我们结束这里的挖掘时，部落就快打到铁炉堡了！', '等我们结束这里的挖掘时，部落就快打到铁炉堡了！', 28153),
(144181, 'zhCN', '黑铁矮人不怕热。但这种潮湿……', '黑铁矮人不怕热。但这种潮湿……', 28153),
(144180, 'zhCN', '显然当战争来临的时候，探险者协会很喜欢悠闲地挖东挖西。', '显然当战争来临的时候，探险者协会很喜欢悠闲地挖东挖西。', 28153),
(144179, 'zhCN', '我们就为了这个离开我们的家？', '我们就为了这个离开我们的家？', 28153),
(144178, 'zhCN', '不必这么夸张。', '', 28153),
(144177, 'zhCN', '', '这些磨损痕迹……不均匀的污点……哎，我们现在要怎么进行展示？！', 28153),
(144176, 'zhCN', '是吗，这么糟吗？', '', 28153),
(144175, 'zhCN', '', '等等！', 28153),
(144174, 'zhCN', '我的朋友，请尽量加快速度。这台设备将为我们效力。', '', 28153),
(144173, 'zhCN', '满意？夫人，按照这个速度，我们得在这里待上一整年。', '', 28153),
(144172, 'zhCN', '', '啊啊，太棒了。是不是很令人满意？', 28153),
(144171, 'zhCN', '', '尽量不要损伤化石……很好。', 28153),
(144170, 'zhCN', '', '很好。现在保持双手稳定。', 28153),
(144169, 'zhCN', '', '德鲁伊，当心脚下！这儿有死亡陷阱！', 28153),
(144168, 'zhCN', '干得漂亮！我们应该可以用这个来对付那些木头怪物。啊……要小心，别弄洒了。', '', 28153),
(144167, 'zhCN', '谢谢你把她带回到我身边。', '', 28153),
(144166, 'zhCN', '', '自我再利用：这是注射器机关盒。请安装起来。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144165, 'zhCN', '', '嗨，爸爸！', 28153),
(144164, 'zhCN', '本妮！哦，我亲爱的女儿！', '', 28153),
(144163, 'zhCN', '你们只是暂时占领了这座伐木场！它会再次回到我们手中的！', '', 28153),
(144162, 'zhCN', '我们去找你爸爸吧。', '我们去找你爸爸吧。', 28153),
(144161, 'zhCN', '', '你好！你叫什么？', 28153),
(144160, 'zhCN', '你没发现自己有多危险吗？', '你没发现自己有多危险吗？', 28153),
(144159, 'zhCN', '你无法阻止我们所有人！', '你无法阻止我们所有人！', 28153),
(144158, 'zhCN', '你永远无法找到我们所有人！', '你永远无法找到我们所有人！', 28153),
(144157, 'zhCN', '我的位置暴露了！', '我的位置暴露了！', 28153),
(144156, 'zhCN', '快看！他们甚至有一个我们的鼓！\n\n谁说地精没有文化？', '', 28153),
(144153, 'zhCN', '接下来我们需要几滴挥发性树液。小心不要把罐子晃得太厉害！', '', 28153),
(144152, 'zhCN', '加入一些硫磺。当心烟！', '', 28153),
(144151, 'zhCN', '现在小心地加入一些炉花。', '', 28153),
(144150, 'zhCN', '我们需要加入一些硝石，来点刺激的！', '', 28153),
(144148, 'zhCN', '卡格瓦对你的伙伴点了点头。', '', 28153),
(144147, 'zhCN', '卡格瓦似乎正在与小抱齿兽说些什么。', '', 28153),
(144146, 'zhCN', '不！我才不回那个牢房！绝不！', '', 28153),
(144145, 'zhCN', '', '守住这里！不能失去控制权。', 28153),
(144144, 'zhCN', '非常好！我会告诉你往大锅里添些什么。一定要听从我的指示，否则可能会导致……爆炸。', '', 28153),
(144142, 'zhCN', '再见，本妮！', '', 28153),
(144141, 'zhCN', '', '是的！待会儿见，乔！', 28153),
(144140, 'zhCN', '', '嘿，乔！', 28153),
(144139, 'zhCN', '哦，嘿，本妮。去找你爸爸吗？', '', 28153),
(144138, 'zhCN', '大家都怎么了？！', '', 28153),
(144137, 'zhCN', '', '我需要治疗！', 28153),
(144136, 'zhCN', '', '向元素屈服吧！', 28153),
(144135, 'zhCN', '$n，我没办法让他变回原来的样子。和你在一起他会生活得更好。带上他，保护好他。', '', 28153),
(144134, 'zhCN', '我知道了。', '', 28153),
(144133, 'zhCN', '靠近一些，年轻人。', '', 28153),
(144132, 'zhCN', '梦魇……', '', 28153),
(144131, 'zhCN', '月亮……正在升起……', '', 28153),
(144130, 'zhCN', '遥远的海岸……', '', 28153),
(144129, 'zhCN', '不要搅拌……锅子……', '', 28153),
(144128, 'zhCN', '再来两杯……还有你们最大的胡椒……', '', 28153),
(144127, 'zhCN', '中间的山……倾覆了……', '', 28153),
(144126, 'zhCN', '再十分钟……', '', 28153),
(144125, 'zhCN', '还没有……', '', 28153),
(144124, 'zhCN', '小溜发出防备的咆哮。', '', 28153),
(144123, 'zhCN', '迎接死亡吧！', '迎接死亡吧！', 28153),
(144122, 'zhCN', '你会看清……你的末日的真相……', '', 28153),
(144121, 'zhCN', '等待你的……没有胜利……只有……死亡……', '', 28153),
(144120, 'zhCN', '在虚空……面前……不足……挂齿……', '', 28153),
(144119, 'zhCN', '你……什么都……没有赢……', '', 28153),
(144118, 'zhCN', '主人们……醒来……', '', 28153),
(144117, 'zhCN', '虚空会降临……到每一处……', '', 28153),
(144116, 'zhCN', '毫无意义……一切都会……归于黑暗……', '', 28153),
(144115, 'zhCN', '他们会在港口里找到你的尸体！', '他们会在港口里找到你的尸体！', 28153),
(144114, 'zhCN', '库尔提拉斯不需要联盟！', '库尔提拉斯不需要联盟！', 28153),
(144113, 'zhCN', '我要把你扔进海里！', '我要把你扔进海里！', 28153),
(144112, 'zhCN', '<排队等待激流堡之战>', '<排队等待激流堡之战>', 28153),
(144111, 'zhCN', '你可以在这张桌子边排队，等待加入战争前线的战斗。', '', 28153),
(144110, 'zhCN', '凯瑟琳会把我们全部淹死！', '凯瑟琳会把我们全部淹死！', 28153),
(144109, 'zhCN', '艾泽拉斯属于我们。', '', 28153),
(144108, 'zhCN', '帝国必将重生！', '', 28153),
(144107, 'zhCN', '把他们找出来！', '', 28153),
(144106, 'zhCN', '一切都将消失。', '', 28153),
(144105, 'zhCN', '一切都将灭亡。', '', 28153),
(144104, 'zhCN', '没有希望……没有生命。', '', 28153),
(144103, 'zhCN', '一切都将被吞噬。', '', 28153),
(144102, 'zhCN', '一切都将化为暗影。', '', 28153),
(144101, 'zhCN', '虚空会吞噬一切。', '', 28153),
(144100, 'zhCN', '', '利爪德鲁伊，进攻！', 28153),
(144099, 'zhCN', '<口哨声>', '', 28153),
(144097, 'zhCN', '', '那只能换个计划了……', 28153),
(144096, 'zhCN', '我拿到了情报。我们要带着它离开这里！', '', 28153),
(144095, 'zhCN', '', '我们被发现了！', 28153),
(144094, 'zhCN', '侦-侦-侦-侦<电流声>侦测到艾泽拉斯之血。请求：安装丢失的数-数-数-数据<电流声>核心。', '', 28153),
(144093, 'zhCN', '啊。太可怕了！', '', 28153),
(144092, 'zhCN', '贾巴里，你的记忆力堪比雷象，智慧可以和贡克媲美。', '', 28153),
(144091, 'zhCN', '当然了，“辣椒”和致命的毒药有什么区别呢，真是公平……', '', 28153),
(144090, 'zhCN', '我不需要你的照顾，贾巴里！霍利的辣椒都没能击倒我！', '', 28153),
(144089, 'zhCN', '够了。你这动静就像雷龙在清嗓子。', '', 28153),
(144088, 'zhCN', '嘘，我的兄弟。拿上这个。', '', 28153),
(144087, 'zhCN', '别乱搞！', '', 28153),
(144086, 'zhCN', '非常精准！现在再看看别的……', '', 28153),
(144085, 'zhCN', '你以前学过炼金！我看得出来！', '', 28153),
(144084, 'zhCN', '做得很好！现在我们要……', '', 28153),
(144082, 'zhCN', '第一发已经装填完毕。我一开火他们就会知道我们的位置。$b$b你准备好了吗？', '', 28153),
(144081, 'zhCN', '他们检查这里也只是时间问题了……', '', 28153),
(144080, 'zhCN', '', '好了！出发吧！', 28153),
(144079, 'zhCN', '', '等等！我们必须手拉手！', 28153),
(144078, 'zhCN', '普罗德摩尔必将陨落！', '普罗德摩尔必将陨落！', 28153),
(144077, 'zhCN', '我的死亡阻挡不了潮汐的变化。', '我的死亡阻挡不了潮汐的变化。', 28153),
(144076, 'zhCN', '你会后悔的！', '你会后悔的！', 28153),
(144075, 'zhCN', '你们不该来这里，外来者！', '你们不该来这里，外来者！', 28153),
(144074, 'zhCN', '伯拉勒斯属于我们！', '伯拉勒斯属于我们！', 28153),
(144073, 'zhCN', '', '这里到阿塔达萨有许多祖尔的爪牙，我们得将他们铲除。', 28153),
(144072, 'zhCN', '精灵……', '精灵……', 28153),
(144071, 'zhCN', '拉斯塔利执行者朝地上吐了口口水。', '拉斯塔利执行者叹息一声。', 28153),
(144070, 'zhCN', '当然。它太原始了。好了，3……2……1……', '', 28153),
(144069, 'zhCN', '', '一定要把又大又丑的神殿拍进去。', 28153),
(144068, 'zhCN', '', '等我们在银月城的朋友看到这张照片，都会非常嫉妒的。', 28153),
(144067, 'zhCN', '我的试练完成了。我写下了故事的最后一个字，回到了现实世界。', '我的试练完成了。我写下了故事的最后一个字，回到了现实世界。', 28153),
(144066, 'zhCN', '我的眼睛没法离开它，它开始窥探我的内心，强行将召唤它所需要了解的一切知识塞进了我的大脑。', '我的眼睛没法离开它，它开始窥探我的内心，强行将召唤它所需要了解的一切知识塞进了我的大脑。', 28153),
(144065, 'zhCN', '它开始嘶喊起来，庆祝着自己的新生。', '它开始嘶喊起来，庆祝着自己的新生。', 28153),
(144064, 'zhCN', '仪式完成了，一个生物在我的眼前融合成形。', '仪式完成了，一个生物在我的眼前融合成形。', 28153),
(144063, 'zhCN', '踏进房间时，我注意到地板上有四个符文。墨水一定就是在这里用的。', '踏进房间时，我注意到地板上有四个符文。墨水一定就是在这里用的。', 28153),
(144062, 'zhCN', '收集到足够的墨水后，我感觉到一股奇异的吸引力，指引着我走向大厅的一端。', '收集到足够的墨水后，我感觉到一股奇异的吸引力，指引着我走向大厅的一端。', 28153),
(144061, 'zhCN', '地板上的骨架提醒了我，如果失败，我也会死去。我不禁在想，之前是不是有人在这个试练中失败了。', '地板上的骨架提醒了我，如果失败，我也会死去。我不禁在想，之前是不是有人在这个试练中失败了。', 28153),
(144060, 'zhCN', '粘稠的淤泥让我感到厌烦。', '粘稠的淤泥让我感到厌烦。', 28153),
(144059, 'zhCN', '淤泥就是解谜的关键。不过到目前为止，我还没有找到需要的东西。', '淤泥就是解谜的关键。不过到目前为止，我还没有找到需要的东西。', 28153),
(144058, 'zhCN', '不知为什么，我很清楚自己要做什么。我决定坚持到底', '不知为什么，我很清楚自己要做什么。我决定坚持到底', 28153),
(144057, 'zhCN', '谨防墨黑，收集血红，血缚杀手现身。”', '谨防墨黑，收集血红，血缚杀手现身。”', 28153),
(144056, 'zhCN', '\"喷于笔尖，涌于血脉，融汇交织于此。\"', '\"喷于笔尖，涌于血脉，融汇交织于此。\"', 28153),
(144055, 'zhCN', '我在密室中醒来，一个奇怪的声音在我的脑中诵读了一首诗。', '我在密室中醒来，一个奇怪的声音在我的脑中诵读了一首诗。', 28153),
(144054, 'zhCN', '你开始在书上写字：“当笔触碰到纸时，我觉得自己被吸了进去。”', '你开始在书上写字：“当笔触碰到纸时，我觉得自己被吸了进去。”', 28153),
(144053, 'zhCN', '翻遍整本书后，所有页面都是空白的。你非常沮丧，看了看克洛纳，猜想她是不是知道这个试练的秘密。', '', 28153),
(144052, 'zhCN', '我很期待能看到你的所见所闻。', '', 28153),
(144051, 'zhCN', '拿起笔开始写就行了。不用担心，剩下的事交给书就可以。', '', 28153),
(144050, 'zhCN', '很简单，亲爱的。你要把自己的故事写进书里。', '', 28153),
(144049, 'zhCN', '哦不，要来了……', '', 28153),
(144048, 'zhCN', '我想要换一些羽毛笔。', '我想要换一些羽毛笔。', 28153),
(144047, 'zhCN', '我的天哪，根本没按计划来！你得再试一遍。', '', 28153),
(144046, 'zhCN', '炼金是非常精准的科学！你要学会集中精神。', '', 28153),
(144045, 'zhCN', '不对不对。我们得从头再来了！', '', 28153),
(144044, 'zhCN', '它烧着了！我们必须重新开始！', '它烧着了！我们必须重新开始！', 28153),
(144043, 'zhCN', '祖尔已经预见到了这一天。即便你们拼命想要改变命运，最终只不过证明了命运的不可避免！', '', 28153),
(144042, 'zhCN', '祖尔……从没说过……我会输……', '', 28153),
(144041, 'zhCN', '你们永远都没法及时到达悬崖！', '', 28153),
(144040, 'zhCN', '我准备好了！', '我准备好了！', 28153),
(144039, 'zhCN', '等等！我现在好多了！呃……', '等等！我现在好多了！呃……', 28153),
(144038, 'zhCN', '我是个傻瓜！', '我是个傻瓜！', 28153),
(144037, 'zhCN', '我再也听不到她的歌了……', '我再也听不到她的歌了……', 28153),
(144036, 'zhCN', '她永远不会爱你的！', '她永远不会爱你的！', 28153),
(144035, 'zhCN', '不，我的爱人！', '不，我的爱人！', 28153),
(144034, 'zhCN', '爱情伤人。', '爱情伤人。', 28153),
(144033, 'zhCN', '值了！', '值了！', 28153),
(144032, 'zhCN', '离别是这样甜蜜的凄清。', '离别是这样甜蜜的凄清。', 28153),
(144031, 'zhCN', '嘿，宝贝，瞧我揍扁这家伙。', '嘿，宝贝，瞧我揍扁这家伙。', 28153),
(144030, 'zhCN', '你在看我的女人？！', '你在看我的女人？！', 28153),
(144029, 'zhCN', '爱情征服一切！', '爱情征服一切！', 28153),
(144028, 'zhCN', '她是我的！我的！', '她是我的！我的！', 28153),
(144027, 'zhCN', '谢谢你，朋友。你救了这个村子，还给了我勇气。阿尔比，塞罗德，请监督尖角地区的善后工作。后会有期。', '', 28153),
(144026, 'zhCN', '你别碰她！', '你别碰她！', 28153),
(144025, 'zhCN', '祖尔想要唤醒达萨？！我不会闲坐着，任由这个“先知”亵渎第一任大王的骸骨。来吧，勇士，和我们一起去这里的南门。', '', 28153),
(144024, 'zhCN', '现在我必须回去。我叔叔和斯托颂谷地的海潮贤者也许听说过这种黑暗魔法。', '', 28153),
(144023, 'zhCN', '迪普沃登……他一向聪明，但我从不知道他会沾染这样的魔法，还掌握了这种能让海洋陷入极度恐慌的力量……', '', 28153),
(144022, 'zhCN', '滚开，她有主了！', '滚开，她有主了！', 28153),
(144021, 'zhCN', '', '很好！他们的阵形出现了漏洞。飞吧，孩子！把异端份子干掉！', 28153),
(144020, 'zhCN', '虽然尖角地区得救了，但我还是觉得害怕。迪普沃登虽然很聪明，但以前可没有这种力量。', '', 28153),
(144019, 'zhCN', '我会保护你的，我的爱人！', '我会保护你的，我的爱人！', 28153),
(144018, 'zhCN', '我非常爱她！', '我非常爱她！', 28153),
(144017, 'zhCN', '命运之手满足了，我会送你去安全的地方。命运有时是仁慈的。', '', 28153),
(144016, 'zhCN', '滚出我们的城市，$p！你将毁灭我们所有人！', '', 28153),
(144015, 'zhCN', '给受到神灵祝福的$p让路！', '', 28153),
(144013, 'zhCN', '', '这些预兆非常杂乱……你将面临极度艰难的挑战，但你终将克服它们。洛阿神灵不会放弃你。', 28153),
(144012, 'zhCN', '', '恐怕这些都是不好的预兆……你的未来将充满无尽的麻烦。我很遗憾。', 28153),
(144011, 'zhCN', '', '今天避开水。那不安全。', 28153),
(144010, 'zhCN', '', '空的？不……你必须改变这个预兆。', 28153),
(144009, 'zhCN', '', '你将面临巨大的苦难和背叛。小心挑选你如今的同伴。', 28153),
(144008, 'zhCN', '', '我很久没有听到过这个预兆了……你必须改变你的命运。', 28153),
(144007, 'zhCN', '', '不要为了眼前的目标走捷径。任何妥协或粗心大意都会导致可怕的下场。', 28153),
(144006, 'zhCN', '', '来自彼界的警告。小心点。', 28153),
(144005, 'zhCN', '', '警惕“黄金之城”。不值得去冒这个险。', 28153),
(144004, 'zhCN', '', '恐怕你必须盲目地走向未来。', 28153),
(144003, 'zhCN', '', '格罗尔被看不见的手拖入深渊。', 28153),
(144002, 'zhCN', '', '沙德拉的巢穴空着。', 28153),
(144001, 'zhCN', '', '托卡利沉睡着。', 28153),
(144000, 'zhCN', '', '莱赞倒在地上……死了。', 28153),
(143999, 'zhCN', '', '邦桑迪冷笑着提出交易。', 28153),
(143998, 'zhCN', '', '卡格瓦吞噬了一群蓝色恐角龙。', 28153),
(143997, 'zhCN', '', '贡克孤独地渡过一条金色的河流。', 28153),
(143996, 'zhCN', '', '帕库在黑暗中闭上了他的双眼。', 28153),
(143995, 'zhCN', '', '很少有比这个更为不祥的预兆。小心行事。', 28153),
(143994, 'zhCN', '', '对我们所有人来说都是个黑暗的预兆。你将什么带到了我们的海岸？', 28153),
(143993, 'zhCN', '', '你在浪费你的潜能。抓住你面前的机会，否则就会成为被遗忘的无名死者之一。', 28153),
(143992, 'zhCN', '', '你和盟友之间的嫌隙威胁到我们所有人。你必须团结赞达拉。', 28153),
(143991, 'zhCN', '', '一个不祥的预兆，但可以凭借力量和决心去克服。', 28153),
(143990, 'zhCN', '', '领袖们若不齐心是无法领导的。你必须与你的对手合作，否则将会承受可怕的后果。', 28153),
(143989, 'zhCN', '', '黑暗崛起，连我们中最强大的人也会被吞噬。包括你。', 28153),
(143988, 'zhCN', '', '对我们所有人来说都是个黑暗的预兆……', 28153),
(143987, 'zhCN', '', '一名新朋友的死亡。', 28153),
(143986, 'zhCN', '', '太阳沉入纳兹米尔的黑暗沼泽。', 28153),
(143985, 'zhCN', '', '一只开裂的花瓶，正在渗漏酒液。', 28153),
(143984, 'zhCN', '', '两个祭司互相残杀。', 28153),
(143983, 'zhCN', '', '一艘人类的船，登陆我们的海岸……', 28153),
(143982, 'zhCN', '', '破碎的冰与火的王座……', 28153),
(143981, 'zhCN', '', '一头雷龙倒在血泊中。', 28153),
(143980, 'zhCN', '', '血流成河，尸体从上游漂来……', 28153),
(143979, 'zhCN', '来吧，小爪！我们走！', '来吧，小爪！我们走！', 28153),
(143978, 'zhCN', '耶！谢谢！', '耶！谢谢！', 28153),
(143977, 'zhCN', '哇，现在好多了！', '', 28153),
(143976, 'zhCN', '我催促他们离开，但他们非要再看一下……我差点没逃出来……如果不是你，我可能就永远出不来了。', '', 28153),
(143975, 'zhCN', '', '借助你的化身泽托娅说话吧！', 28153),
(143974, 'zhCN', '', '借助你的化身伊卢娜说话吧！', 28153),
(143973, 'zhCN', '', '我们准备好了。进驻我的器皿，向我们展示未来。', 28153),
(143972, 'zhCN', '', '死者的灵魂、神灵的灵魂、迷失者和迷茫者的灵魂，现在听我一言！', 28153),
(143971, 'zhCN', '我这就回到防线后去！', '我这就回到防线后去！', 28153),
(143970, 'zhCN', '我没法动了！', '我没法动了！', 28153),
(143969, 'zhCN', '我还以为自己会被拖到森林里呢！', '我还以为自己会被拖到森林里呢！', 28153),
(143968, 'zhCN', '她们已经把很多人带到森林里了！', '她们已经把很多人带到森林里了！', 28153),
(143967, 'zhCN', '我马上就回去！', '我马上就回去！', 28153),
(143966, 'zhCN', '', '这些对你来说都是好兆头……立即大胆地展开行动吧！', 28153),
(143965, 'zhCN', '我还以为死定了呢！', '我还以为死定了呢！', 28153),
(143964, 'zhCN', '谢谢你！', '谢谢你！', 28153),
(143963, 'zhCN', '', '群兽奔腾……', 28153),
(143962, 'zhCN', '', '一个轻松愉快的预兆……不要被焦虑所吞噬。快乐和幽默会使你获得成功。', 28153),
(143961, 'zhCN', '孢林蔓延！', '', 28153),
(143960, 'zhCN', '万物终将……凋零……', '', 28153),
(143959, 'zhCN', '', '沙德拉最常见的祝福，但带有意外的附加条件。总体还是个好兆头，只是我并不能完全理解。', 28153),
(143958, 'zhCN', '', '守护者的的祝福……你将拯救很多生命，但也许会以你自己的生命做为代价。', 28153),
(143957, 'zhCN', '', '大王的神灵是一种罕见的预兆。强大且威武。你将消灭大王的敌人。', 28153),
(143956, 'zhCN', '', '长寿和轻松之死的好兆头。', 28153),
(143955, 'zhCN', '成为肥料吧！', '', 28153),
(143954, 'zhCN', '枯萎吧！', '', 28153),
(143953, 'zhCN', '腐化绽放！', '', 28153),
(143952, 'zhCN', '', '如果那个岛不是你的家乡，那就是个好兆头。', 28153),
(143951, 'zhCN', '生长吧！', '', 28153),
(143950, 'zhCN', '', '你将永远和盟友并肩战斗。贡克不会在你需要的时候放弃你。', 28153),
(143949, 'zhCN', '', '帕库将指引你的旅程，驱散你的敌人……', 28153),
(143948, 'zhCN', '真是肥沃的土壤。', '', 28153),
(143947, 'zhCN', '', '格罗尔跃过大王的舰队……', 28153),
(143946, 'zhCN', '', '沙德拉的卵孵化了。无数眼睛向前冲去……', 28153),
(143945, 'zhCN', '', '托卡利独自站立在山顶……', 28153),
(143944, 'zhCN', '', '莱赞重踏而下，鲜血巨魔四散奔逃……', 28153),
(143943, 'zhCN', '', '邦桑迪看向远方……', 28153),
(143942, 'zhCN', '', '卡格瓦吞噬掉一个岛屿……', 28153),
(143941, 'zhCN', '腐烂吧！', '', 28153),
(143940, 'zhCN', '', '贡克和他的兽群一起奔跑……', 28153),
(143939, 'zhCN', '收割！', '', 28153),
(143938, 'zhCN', '腐烂必须扩散！', '', 28153),
(143937, 'zhCN', '', '这一般是个好兆头，但具体要取决于你的朋友……', 28153),
(143936, 'zhCN', '', '这对我们所有人来说都是个好兆头。赞达拉应当欢迎你的到来。', 28153),
(143935, 'zhCN', '', '不管别人怎么想，你还没有完全发挥自己的潜能。你的力量将有所增长，你的强大将超越期望。', 28153),
(143934, 'zhCN', '', '一个……意外的预兆，对外来者来说。这是什么意思？', 28153),
(143933, 'zhCN', '', '强大的预兆！是你的好兆头……', 28153),
(143932, 'zhCN', '', '我的族人们发展壮大的好兆头。有趣，这个预兆应该给你……', 28153),
(143931, 'zhCN', '', '繁荣和传承的好兆头。', 28153),
(143930, 'zhCN', '', '力量、权力和成功的好兆头。', 28153),
(143929, 'zhCN', '', '复活的昔日友人……', 28153),
(143928, 'zhCN', '', '太阳从金色的水面上升起……', 28153),
(143927, 'zhCN', '', '一枚巨大的蛋，剧烈摇晃，但没有开裂……', 28153),
(143926, 'zhCN', '', '所有巨魔部族，团结在赞达拉的旗帜之下……', 28153),
(143925, 'zhCN', '', '被砍下的精灵头颅……', 28153),
(143924, 'zhCN', '', '古老的水域，与世无争……', 28153),
(143923, 'zhCN', '', '黄金的面具……', 28153),
(143922, 'zhCN', '', '帕库的阴影穿过一条石径……', 28153),
(143921, 'zhCN', '', '很好。让我们看看灵魂有什么话要对你说……', 28153),
(143920, 'zhCN', '', '你确定想要知道吗，$p？\n\n并非所有命运都包含伟大的事迹和幸福的结局……', 28153),
(143919, 'zhCN', '我不怕。告诉我，你在我的未来里看到了什么？', '我不怕。告诉我，你在我的未来里看到了什么？', 28153),
(143918, 'zhCN', '你在我的未来里看到了什么？', '你在我的未来里看到了什么？', 28153),
(143917, 'zhCN', '', '现在听我一言，失落的古老灵魂。进驻我的躯体，向我们展示未来。', 28153),
(143916, 'zhCN', '无所谓。我们无处不在……就在你的脚下。', '', 28153),
(143915, 'zhCN', '你太弱了……我们部族……会发展壮大。', '你太弱了……我们的部族……会发展壮大。', 28153),
(143914, 'zhCN', '', '欢迎来到失落灵魂之家，$p。\n\n你迟到了。我还以为你不会来了。\n\n那么，告诉我，孔娜拉夫人今天能为你提供什么服务？', 28153),
(143913, 'zhCN', '我战死沙场……', '我战死沙场……', 28153),
(143912, 'zhCN', '我们的棘刺……必将布满这片土地……', '我们的棘刺……必将布满这片土地……', 28153),
(143911, 'zhCN', '棘背一族……依旧会发展壮大……', '棘背一族……依旧会发展壮大……', 28153),
(143910, 'zhCN', '我的旅途……结束了。', '我的旅途……结束了。', 28153),
(143909, 'zhCN', '你的死亡将带给我荣耀。', '你的死亡将带给我荣耀。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143908, 'zhCN', '你的鲜血会让荆棘茁壮生长！', '你的鲜血会让荆棘茁壮生长！', 28153),
(143907, 'zhCN', '不撤退，不投降！', '不撤退，不投降！', 28153),
(143906, 'zhCN', '为什么染血纲要是空白的？', '为什么染血纲要是空白的？', 28153),
(143905, 'zhCN', '你会成为野猪的饲料。', '你会成为野猪的饲料。', 28153),
(143904, 'zhCN', '你休想阻止我们！', '你休想阻止我们！', 28153),
(143903, 'zhCN', '这地盘归我们了！', '这是我们的地盘！', 28153),
(143902, 'zhCN', '开始在书上写字。', '开始在书上写字。', 28153),
(143901, 'zhCN', '浏览整本书。', '浏览整本书。', 28153),
(143900, 'zhCN', '小爪！你还在上面吗？！如果听到我的话，就喵两声！！', '小爪！你还在上面吗？！如果听到我的话，就喵两声！！', 28153),
(143899, 'zhCN', '接下来的几页也是空白的。', '', 28153),
(143898, 'zhCN', '我们会把你弄下来的，小爪！你乖乖别动！', '我们会把你弄下来的，小爪！你乖乖别动！', 28153),
(143897, 'zhCN', '没事的，小爪！原地别动！', '没事的，小爪！原地别动！', 28153),
(143896, 'zhCN', '再多翻几页。', '再多翻几页。', 28153),
(143895, 'zhCN', '书上的页面是空白的。', '', 28153),
(143894, 'zhCN', '喵嗷嗷。', '', 28153),
(143893, 'zhCN', '坚持住，小爪！救兵快来了！！', '坚持住，小爪！救兵快来了！！', 28153),
(143892, 'zhCN', '快下来，小爪！下来！那里不安全！', '快下来，小爪！下来！那里不安全！', 28153),
(143891, 'zhCN', '跳下来，小爪！我会接住你的！', '跳下来，小爪！我会接住你的！', 28153),
(143890, 'zhCN', '小爪！！下来！！！', '小爪！！下来！！！', 28153),
(143889, 'zhCN', '', '我要把你喂给我的宠物，$r！', 28153),
(143888, 'zhCN', '勇士，过来。', '', 28153),
(143887, 'zhCN', '这边！', '', 28153),
(143886, 'zhCN', '小心！', '', 28153),
(143885, 'zhCN', '走这边。', '', 28153),
(143884, 'zhCN', '这边走。', '', 28153),
(143883, 'zhCN', '小心！', '', 28153),
(143882, 'zhCN', '这边！', '', 28153),
(143881, 'zhCN', '你。过来。', '', 28153),
(143879, 'zhCN', '净化！', '', 28153),
(143876, 'zhCN', '完成了。', '', 28153),
(143875, 'zhCN', '血！血！血！', '', 28153),
(143874, 'zhCN', '祖达萨必将陨落！', '', 28153),
(143873, 'zhCN', '新鲜的肉！', '', 28153),
(143872, 'zhCN', '我要你的血！', '', 28153),
(143871, 'zhCN', '你的骨头渣子对我们很有用！', '', 28153),
(143870, 'zhCN', '你的血属于戈霍恩！', '', 28153),
(143869, 'zhCN', '在血神面前，你再躲也没用！', '', 28153),
(143868, 'zhCN', 'Guzincha！', '', 28153),
(143867, 'zhCN', 'Kachago！', '', 28153),
(143865, 'zhCN', '你没有看到细则吗，孩子？\n\n不接受退款。不接受例外。不接受投诉。\n\n我知道该怎么让你振作起来……一次羽足的欢乐降落！', '', 28153),
(143864, 'zhCN', '一次羽足的欢乐降落，谢谢！', '一次羽足的欢乐降落，谢谢！', 28153),
(143863, 'zhCN', '我要退款。', '我要退款。', 28153),
(143862, 'zhCN', '欢迎回来，$p！\n\n你肯定非常享受你的羽足欢乐降落时间。\n\n作为正式会员，你可以无限次地从这座通灵塔顶部缓缓降落。想跳的时候随时告诉我！\n\n我们绝对不接受退款。', '', 28153),
(143861, 'zhCN', '立即参加羽足的欢乐降落吧！\n\n只需一次性缴纳少量服务费，你就能无限次地从这座通灵塔顶部缓缓降落。保证你的生命安全！\n\n不接受退款。', '', 28153),
(143860, 'zhCN', '这里的风比至高岭大很多。我们加入部落的决定已经有所回报。', '', 28153),
(143859, 'zhCN', '回归风暴，获得平静吧。飞过神殿，让我们分享你的力量。', '', 28153),
(143858, 'zhCN', '', '真是个美妙的城市。探索世界太有趣了！', 28153),
(143857, 'zhCN', '亡者啊，听从召唤。今天，你们的邪恶行径已得到宽恕。', '', 28153),
(143856, 'zhCN', '等你准备好了，就释放出丧钟里的灵魂。', '', 28153),
(143855, 'zhCN', '罗萨琳，非常抱歉，不过你得等一下。今天我们有比狩猎更紧急的事需要处理。', '', 28153),
(143854, 'zhCN', '', '噢！塞罗德！别闲着了。我们要外出狩猎，需要你的祝福！', 28153),
(143853, 'zhCN', '早点回来，$p！', '', 28153),
(143852, 'zhCN', '朝鲜血巨魔吐口水可以得10分！', '', 28153),
(143851, 'zhCN', '羽足的欢乐降落！告诉你的朋友们！', '', 28153),
(143850, 'zhCN', '很高兴再次见到你，$p。降落愉快！', '', 28153),
(143849, 'zhCN', '试着降落到雷龙身上！', '', 28153),
(143848, 'zhCN', '试着降落到瀑布里！', '', 28153),
(143847, 'zhCN', '小心翼手龙！', '', 28153),
(143846, 'zhCN', '旅途平安，$p。', '', 28153),
(143845, 'zhCN', '啊啊啊啊！', '', 28153),
(143844, 'zhCN', '为了联盟。', '', 28153),
(143843, 'zhCN', '为了部落！', '', 28153),
(143842, 'zhCN', '激流堡已经陷落了。投降吧，罗杰斯，体面点儿。', '', 28153),
(143841, 'zhCN', '哦耶，我的锤子……在这里！', '', 28153),
(143840, 'zhCN', '嘿，小铜须，你在家吗？', '', 28153),
(143839, 'zhCN', '圣光依然与我同在。我不会轻易倒下！', '', 28153),
(143838, 'zhCN', '罗杰斯！你的堡垒已经被我们扫平了。想让我们有什么下场啊，圣骑士？', '', 28153),
(143837, 'zhCN', '他们觉得几个骑着马的士兵就能阻止我们？哼！让他们看看部落的力量！', '', 28153),
(143836, 'zhCN', '据点需要支援。摧毁那些坦克，别让它们靠近！', '', 28153),
(143835, 'zhCN', '我们的防御还很薄弱。部落的军队，回到基地，守住我们的阵线！', '', 28153),
(143834, 'zhCN', '好吧，你想打，那我们就奉陪到底。派出骑兵部队，消灭他们！', '', 28153),
(143833, 'zhCN', '元素法阵已被部落控制。', '', 28153),
(143832, 'zhCN', '纽斯泰德归我们了……这下我们有狼骑兵了。', '', 28153),
(143831, 'zhCN', '军械库准备就绪。', '', 28153),
(143830, 'zhCN', '车间完工了。投石车很快就可以把联盟的城墙搞定！', '', 28153),
(143829, 'zhCN', '攻城坦克，消灭他们！', '', 28153),
(143828, 'zhCN', '已经警告过你了，部落的渣滓。现在，准备迎接毁灭吧。', '', 28153),
(143827, 'zhCN', '巨魔统治这片土地的时候，你们的联盟还不知道在哪呢，图拉扬。', '', 28153),
(143826, 'zhCN', '哼，肯定很合身。', '', 28153),
(143825, 'zhCN', '现在就先穿这套衣服吧。', '', 28153),
(143824, 'zhCN', '要事第一，我们需要木材和铁矿来建立部落基地。附近这两种资源应该很充足 。', '', 28153),
(143823, 'zhCN', '我也一直等待着和你交手，穆拉丁！', '', 28153),
(143822, 'zhCN', '也许这套衣服可以帮助你提高采集技能。', '', 28153),
(143821, 'zhCN', '还是想想你自己的下场吧，图拉扬！', '', 28153),
(143820, 'zhCN', '这里是联盟的领土！部落入侵者别想有好下场！', '', 28153),
(143819, 'zhCN', '今天，它将属于部落！', '', 28153),
(143818, 'zhCN', '很久以前，这片土地统统属于巨魔。', '', 28153),
(143817, 'zhCN', '啊……我很高兴，小伙子。这下你惹错矮人了。', '', 28153),
(143816, 'zhCN', '穆拉丁！出来，你这个懦夫！', '', 28153),
(143815, 'zhCN', '基地防御还很薄弱。别让那些坦克开到基地来！', '', 28153),
(143814, 'zhCN', '没你一半丑，穆拉丁！', '', 28153),
(143813, 'zhCN', '抱歉，考察者。', '', 28153),
(143812, 'zhCN', '很荣幸为您服务，考察者。', '', 28153),
(143811, 'zhCN', '', '战斗结束……我们没死。阿提娜会为她的疯狂付出代价！', 28153),
(143810, 'zhCN', '', '看，祖达萨的毁灭者！来阻止我们吧……你的哀嚎会为我们增光添彩！', 28153),
(143809, 'zhCN', '', '你们再怎么挣扎，都将死于主人的怒火！', 28153),
(143808, 'zhCN', '在神圣遗物学会工作非常劳累……', '', 28153),
(143807, 'zhCN', '哈，很简单吧！去一展身手吧。木材可是永远都不够用的。', '', 28153),
(143806, 'zhCN', '遵命，考察者。', '', 28153),
(143805, 'zhCN', '您尽管吩咐，考察者。', '', 28153),
(143804, 'zhCN', '我很乐意帮忙，考察者。', '', 28153),
(143803, 'zhCN', '', '你的皮囊可以做主人的新化身！', 28153),
(143802, 'zhCN', '', '接下来就轮到部落了。你要为希里克的死付出代价！你无处可逃了。', 28153),
(143801, 'zhCN', '', '祖达萨必将陨落……我的主人将重获自由！你们这些孱弱的洛阿神灵毫无胜算！', 28153),
(143800, 'zhCN', '好的，考察者。', '', 28153),
(143799, 'zhCN', '我马上就过去，考察者。', '', 28153),
(143798, 'zhCN', '', '有意思……贝罗斯，来看看这个，告诉我你看到了什么。', 28153),
(143797, 'zhCN', '', '你跑哪里去了，贝罗斯？我有更多珍贵的信息需要你记下来。', 28153),
(143796, 'zhCN', '', '我亲爱的贝罗斯，来看看这个。', 28153),
(143795, 'zhCN', '', '神圣遗物学会里没有休息时间，贝罗斯。', 28153),
(143794, 'zhCN', '', '贝罗斯，不要触摸遗物！', 28153),
(143793, 'zhCN', '', '棒极了……贝罗斯，过来看看这有多棒！', 28153),
(143792, 'zhCN', '', '赫兹雷尔的护盾启动了！快进去！', 28153),
(143791, 'zhCN', '', '贝罗斯，你又在梦游吗？过来帮我的忙。', 28153),
(143790, 'zhCN', '', '贝罗斯，麻利点记下我说的所有话。', 28153),
(143789, 'zhCN', '风舷军需要许多物资来维持最佳状态！我的工作就是跟踪和补充库存，以及修复损坏的设备和工具！$b$b……$b$b他们每天都会弄坏许多东西。$b$b他们可算不上温柔。', '', 28153),
(143788, 'zhCN', '', '$n，我能跟你谈谈吗？我希望你能助我一臂之力。', 28153),
(143787, 'zhCN', '<<我和工人们带着火炮走向堤道的时候发生了意外。>>', '', 28153),
(143786, 'zhCN', '提着袜子拖着丝，提着帕子拖着丝，提帕子拖丝，提帕托斯！\n', '', 28153),
(143785, 'zhCN', '他们都上了我的当！都觉得我是这么单纯的家伙……等一下，你说他们听得到我的话是什么意思？我，呃……提帕托斯！', '', 28153),
(143784, 'zhCN', '提帕托斯不喜欢的东西有：蛇、欺负人的小孩、蛇、黑乎乎的山洞、蛇……还有老是缠着提帕托斯的小个子。', '', 28153),
(143783, 'zhCN', '没错，提帕托斯读过书。那种字很少，图很多的……但还是书。', '', 28153),
(143782, 'zhCN', '小个子不会是想占提帕托斯的便宜吧？', '', 28153),
(143781, 'zhCN', '提帕托斯还是有点怕蛇。', '', 28153),
(143780, 'zhCN', '提帕托斯变成了光铸者，非常自豪！', '', 28153),
(143779, 'zhCN', '提帕托斯随时恭候。', '', 28153),
(143778, 'zhCN', '提帕托斯必须回去工作了。', '', 28153),
(143777, 'zhCN', '提帕托斯还有很多事要忙。', '', 28153),
(143776, 'zhCN', '提帕托斯希望很快再见到你。', '', 28153),
(143775, 'zhCN', '提帕托斯。', '', 28153),
(143774, 'zhCN', '快点，$n。性命攸关。', '', 28153),
(143773, 'zhCN', '提帕托斯准备好了。', '', 28153),
(143772, 'zhCN', '愿圣光与你同在，朋友。\n', '', 28153),
(143771, 'zhCN', '危险？提帕托斯才不怕危险！', '', 28153),
(143770, 'zhCN', '小个子想问提帕托斯什么？', '', 28153),
(143769, 'zhCN', '提帕托斯向小个子问好。', '', 28153),
(143768, 'zhCN', '提帕托斯？', '', 28153),
(143767, 'zhCN', '提帕托斯！', '', 28153),
(143766, 'zhCN', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s开始施展|cFFFF0000|Hspell:259610|h[血腥天启]|h|r！寻找掩护！', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s开始施展|cFFFF0000|Hspell:259610|h[血腥天启]|h|r！寻找掩护！', 28153),
(143765, 'zhCN', '', '挣扎吧！战斗吧！你们的痛苦会滋养我的主人！', 28153),
(143764, 'zhCN', '吉安娜？根本就是凶安娜。茉德拉？呃……我也不是每个名字都想得出的好吗？', '', 28153),
(143763, 'zhCN', '卡德加？我看是卡德减。对吧？', '', 28153),
(143762, 'zhCN', '肯瑞托？什么都不肯！对吧？', '', 28153),
(143761, 'zhCN', '如果你们都照我说的去做，而不是自作聪明，艾泽拉斯的情况会好很多。', '', 28153),
(143760, 'zhCN', '与我们作对可不明智。', '', 28153),
(143759, 'zhCN', '为了奎尔萨拉斯。', '', 28153),
(143758, 'zhCN', '我们克服了很多困难。', '', 28153),
(143757, 'zhCN', '我们以传统为基石打造未来。', '', 28153),
(143756, 'zhCN', '忙你自己的事吧。', '', 28153),
(143755, 'zhCN', '别让外人打扰我。', '', 28153),
(143754, 'zhCN', '尊重我们的传统。', '', 28153),
(143753, 'zhCN', '永恒的太阳依旧指引着我们。', '', 28153),
(143752, 'zhCN', '你想问什么？', '', 28153),
(143751, 'zhCN', '我侍奉银月城。', '', 28153),
(143750, 'zhCN', '我可是大忙人。', '', 28153),
(143749, 'zhCN', '别浪费资源。', '', 28153),
(143748, 'zhCN', '什么事？', '', 28153),
(143747, 'zhCN', '必须保护太阳井。', '', 28153),
(143746, 'zhCN', '给你这个作为谢礼。', '', 28153),
(143745, 'zhCN', '', '计划？卑微的我能有什么计划？', 28153),
(143744, 'zhCN', '', '你以为我没发现你看我的黑暗游侠的眼神吗？我建议你收敛一下，不仅别看，连想都别想。', 28153),
(143743, 'zhCN', '', '我一直在关注你的事迹。看来我得送你去纳萨诺斯那儿重新训练一下了。', 28153),
(143742, 'zhCN', '', '风行者三姐妹里，你肯定最喜欢我了……对吧？对吧？', 28153),
(143741, 'zhCN', '', '艾泽拉斯的生命之血属于部落。', 28153),
(143740, 'zhCN', '我差点开始怀疑它是否存在！', '', 28153),
(143739, 'zhCN', '', '我们必将得到属于我们的东西。', 28153),
(143738, 'zhCN', '', '所有人迟早都会效忠部落。', 28153),
(143737, 'zhCN', '', '无论如何，被遗忘者必将繁荣昌盛。', 28153),
(143736, 'zhCN', '', '我们会让联盟俯首称臣。', 28153),
(143735, 'zhCN', '', '效忠部落。效忠于我。', 28153),
(143734, 'zhCN', '它真漂亮！', '', 28153),
(143733, 'zhCN', '', '去吧。我还很忙。', 28153),
(143732, 'zhCN', '', '好好效忠我，你会得到奖赏。', 28153),
(143731, 'zhCN', '', '部落会获得崭新的未来。', 28153),
(143730, 'zhCN', '', '我们真正的事业才刚刚开始。', 28153),
(143729, 'zhCN', '', '你好，勇士。', 28153),
(143728, 'zhCN', '', '上前来。', 28153),
(143727, 'zhCN', '', '希望你不会浪费我的时间。', 28153),
(143726, 'zhCN', '', '我是大酋长，有话直说。', 28153),
(143725, 'zhCN', '', '赞达拉的元素饱经苦难。我们必须阻止那些为了私欲滥用力量的黑暗萨满。', 28153),
(143724, 'zhCN', '我叫伯特霍德，我是个爱马狂。\n\n据说这个度假村的西边出现了一头马形的生物，就在某座山上。我在这里找了份工作，为的是休息时也许可以看到它。\n\n哦，我愿意付出一切代价去看眼那样的……', '', 28153),
(143721, 'zhCN', '同意。请求不再思考泰坦守护者赫兹雷尔的位置相关问题。将前往指定区域祖纳兹曼。', '', 28153),
(143720, 'zhCN', '', '赫兹雷尔，鲜血巨魔正在祖纳兹曼集结。如果你想帮我们，你就得去那里。', 28153),
(143719, 'zhCN', '给我买杯酒吧，$pr。\n\n在你们的人像懦夫一样四散奔逃，躲藏在迷雾中的时候，我们的人民拯救了这个世界。\n\n你欠我一杯酒。', '', 28153),
(143718, 'zhCN', '泰坦守护者赫兹雷尔的系统正在以百分之五十的性能运行。必须保存剩余能量，用于清除鲜血巨魔。', '', 28153),
(143717, 'zhCN', '这里是我以前的混调室。皇室宴请来自世界各地的贵族，而我则用我的饮料款待他们。\n\n现在，这里已经变成了肮脏的外来者和他们那些丑陋朋友的巢穴。真可惜。', '', 28153),
(143716, 'zhCN', '我尊重很多地精财团。他们中立且强大，愿意付出任何代价。就像赞达拉巨魔……不过当然，没有我们这么优秀。\n\n但锈水财阀却是一个耻辱。竟然跟精灵和部落联手。这是纯粹的背叛。', '', 28153),
(143715, 'zhCN', '感受我的力量！', '', 28153),
(143714, 'zhCN', '我喜欢你们部落的风格，$p。强大的首领。共同奋斗的目标。稳定的补给线。\n\n你们还招人吗？', '', 28153),
(143713, 'zhCN', '我准备好寻找下一支盟友了。', '我准备好寻找下一支盟友了。', 28153),
(143712, 'zhCN', '', '部落和联盟之间的惺惺作态终于要结束了。$b$b战争即将来临。', 28153),
(143711, 'zhCN', '我一直都想不明白暗矛部族竟然选择加入部落这件事。应该是他们太弱了，根本无法独立生存。\n\n沃金还好吗？', '', 28153),
(143710, 'zhCN', '听着，精灵。我不是这个酒吧的主人了，所以我不必再假装喜欢你。\n\n给我滚一边去，肮脏的精灵。', '', 28153),
(143709, 'zhCN', '你看起来很渴。喝一杯吧。坐下来聊一会儿。\n\n自从远古时代开始，祖达萨便一直矗立。它不会在一夜之间消失的。', '', 28153),
(143708, 'zhCN', '我听说你们有些人要去纳兹米尔。如果可以，还是放弃任务吧。那片沼泽已经很久没有发生过什么好事了。', '', 28153),
(143707, 'zhCN', '我听说沃顿沙漠现在的麻烦越来越多。如果你要去那里，记得小心点。', '', 28153),
(143706, 'zhCN', '我的人民从时间的源头时起就建立起文明，并一直提携着你们一起发展。\n\n告诉我，$pr，你们一族曾做过什么值得铭记的事吗？\n\n我一件都想不出。', '', 28153),
(143705, 'zhCN', '（跳上赫兹雷尔的肩膀，回到林荫巨木。）', '（跳上赫兹雷尔的肩膀，回到林荫巨木。）', 28153),
(143704, 'zhCN', '戈霍恩抑制设施修复失败。必须阻止名为鲜血巨魔的生物摧毁祖达萨，彻底释放戈霍恩。\n\n建筑已被鲜血巨魔包围。泰坦守护者赫兹雷尔会确保$n和塔兰吉公主的安全。\n\n请跳到肩上。注意头部。', '', 28153),
(143703, 'zhCN', '肮脏。恶心。你的气味比鲜血巨魔更糟糕。\n\n如果我还是这个酒吧的主人，就会把你们和垃圾一起扫出去。', '', 28153),
(143702, 'zhCN', '你听说城市外面的事了吗？', '', 28153),
(143700, 'zhCN', '加里维克斯正在希利苏斯行动，快过去吧。如果你看到那儿有联盟，就立刻解决掉。', '', 28153),
(143699, 'zhCN', '我们在希利苏斯建了个临时基地。去那儿跟指挥官报到，记得留心部落。', '', 28153),
(143698, 'zhCN', '你们兽人很能喝。这一点我承认。\n\n但告诉你们那些高傲的精灵朋友，离这里远点，好吗？', '', 28153),
(143697, 'zhCN', '奥蕾莉亚和图拉扬？没希望的。我的意思是……我不是不喜欢他们俩在一起，而是……呃，我们可以换个话题吗？', '', 28153),
(143696, 'zhCN', '你不喜欢精灵，这一点我可以理解。毕竟，有一半精灵也看不惯另一半。', '', 28153),
(143695, 'zhCN', '我承认，以前我不怎么喜欢紫色。但现在越来越顺眼了。\n', '', 28153),
(143694, 'zhCN', '高等精灵？得了吧。能变得深沉而忧郁，还当高等精灵干什么？', '', 28153),
(143693, 'zhCN', '专注心灵，控制暗影。', '', 28153),
(143692, 'zhCN', '别向低语屈服。', '', 28153),
(143691, 'zhCN', '接受所有可能。', '', 28153),
(143690, 'zhCN', '愿暗影守护你。', '', 28153),
(143689, 'zhCN', '我们效忠联盟。', '', 28153),
(143688, 'zhCN', '圣光不是唯一的道路。', '', 28153),
(143687, 'zhCN', '朗多雷会证明自己的价值。', '', 28153),
(143686, 'zhCN', '我还有很多东西要教你。', '', 28153),
(143685, 'zhCN', '不要有任何成见。', '', 28153),
(143684, 'zhCN', '所有道路都能通行。', '', 28153),
(143683, 'zhCN', '我们不害怕力量，我们拥抱它。', '', 28153),
(143682, 'zhCN', '暗影为我们效命。', '', 28153),
(143681, 'zhCN', 'Bal\'a dash，malanore。', '', 28153),
(143680, 'zhCN', '你好，旅行者。', '', 28153),
(143679, 'zhCN', '我的眼罩从没换过位置！呃，我是说……怎么会有人连这种事情都会弄错，是吧？', '', 28153),
(143678, 'zhCN', '为希尔瓦娜斯效力并不容易。身为亡灵，她特别颐指气使。呃，不过……别告诉她这是我说的。', '', 28153),
(143677, 'zhCN', '不管他是不是女王的勇士，我的箭术都比他强多了。', '', 28153),
(143676, 'zhCN', '这种发型不是天生的，需要定时养护。', '', 28153),
(143675, 'zhCN', '银月城再也不需要国王的统治。', '', 28153),
(143674, 'zhCN', '我们血精灵正在崛起。', '', 28153),
(143673, 'zhCN', 'Al diel shala。', '', 28153),
(143672, 'zhCN', '部落就是我们的力量。', '', 28153),
(143671, 'zhCN', '我所做的一切都是为了奎尔萨拉斯。', '', 28153),
(143670, 'zhCN', '愿太阳之井的光芒与你同在。', '', 28153),
(143669, 'zhCN', '银月城必将再度繁荣。', '', 28153),
(143668, 'zhCN', '永歌森林美丽长存。', '', 28153),
(143667, 'zhCN', '永恒的太阳依旧指引着我们。', '', 28153),
(143666, 'zhCN', '重建工作还在继续。', '', 28153),
(143665, 'zhCN', '我们付出了无数牺牲。', '', 28153),
(143664, 'zhCN', '我乃银月城的摄政王。', '', 28153),
(143663, 'zhCN', 'Bal\'a dash，malanore。', '', 28153),
(143662, 'zhCN', '我代表银月城致以问候。', '', 28153),
(143651, 'zhCN', '哦，我好像钓到了一条大鱼！', '', 28153),
(143650, 'zhCN', 'PLACEHOLDER SCENE - 赫兹雷尔解释了戈霍恩是一名古神，曾经被做实验。鲜血巨魔想要摧毁祖达萨，释放戈霍恩。现在没有办法修复当前的禁制，必须保护祖达萨。鲜血巨魔的主母阿提娜来了，给赫兹雷尔造成了严重的伤害，准备发起攻击。', 'PLACEHOLDER SCENE - 赫兹雷尔解释了戈霍恩是一名古神，曾经被做实验。鲜血巨魔想要摧毁祖达萨，释放戈霍恩。现在没有办法修复当前的禁制，必须保护祖达萨。鲜血巨魔的主母阿提娜来了，给赫兹雷尔造成了严重的伤害，准备发起攻击。', 28153),
(143649, 'zhCN', '', '回来，$r！他的声音属于我！', 28153),
(143648, 'zhCN', '', '这里……充满……力量……', 28153),
(143647, 'zhCN', '', '小心，乌布里克。解开这种谜团通常要付出代价。', 28153),
(143646, 'zhCN', '拿这个方盒来说，它是个古代装置，甚至可能在艾泽拉斯有生命前就存在，但似乎被锁住了，我们还没法打开。\n', '', 28153),
(143645, 'zhCN', '的确！我们跟你一样，觉得虚空可以保护，而不是吞噬生命。我们进展良好，风行者女士，但是还有很多未解之谜。\n', '', 28153),
(143644, 'zhCN', '', '下次再说吧。我和这位勇士一直在寻找你。我们知道你被银月城流放，而我们志同道合。', 28153),
(143643, 'zhCN', '我和我的人民听说过阿古斯发生的事。当然，你对黑暗纳鲁所做的事，我也非常有兴趣了解。\n', '', 28153),
(143642, 'zhCN', '奥蕾莉亚·风行者！？怎么会……啊，真是莫大的荣幸！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143641, 'zhCN', '', '魔导师乌布里克！我是奥蕾莉亚·风行者。', 28153),
(143640, 'zhCN', '', '看前面。那一定是乌布里克。', 28153),
(143639, 'zhCN', '', '根据笔记，我应该可以重新打开通往他所说世界的通道。我看看……', 28153),
(143638, 'zhCN', '', '<跳跃落地：总计3>', 28153),
(143637, 'zhCN', '德拉希尔相信这里有个古代器物，蕴含着不可言喻的力量。也许这就是我们控制暗影的关键。', '', 28153),
(143636, 'zhCN', '他的笔记说，它位于现实构造的裂隙里。他从来没找到那个地方……但我成功了。道路很快会向我们敞开！', '', 28153),
(143635, 'zhCN', '德拉希尔渴望力量，他寻找着一个古代世界的碎片，那个世界坐落在虚空边缘。', '', 28153),
(143634, 'zhCN', '<跳跃落地：总计3>', '', 28153),
(143633, 'zhCN', '', '来吧。我们必须前往晨星之塔。', 28153),
(143632, 'zhCN', '然而，我相信这种知识可以用作正途。德拉希尔的研究主要在晨星之塔进行。我们必须前往那里。', '', 28153),
(143631, 'zhCN', '德拉希尔的背叛导致阿尔萨斯腐化了太阳井……并毁灭了我们的王国。我这才明白罗曼斯为何反对我们的研究。', '', 28153),
(143630, 'zhCN', '看来我们并不是同胞中第一批想驾驭虚空的。这些笔记作者的名字就是个诅咒……达尔坎·德拉希尔。', '', 28153),
(143629, 'zhCN', '<跳跃落地：总计3>', '', 28153),
(143628, 'zhCN', '', '看来我找到了一些笔记。', 28153),
(143627, 'zhCN', '', '<跳跃落地：总计3>', 28153),
(143626, 'zhCN', '不幸的是，我们的研究似乎遇到了瓶颈。相信安迪尔林庄园会有继续研究所需的知识。', '', 28153),
(143625, 'zhCN', '大法师必须明白，这种力量对保护银月城至关重要。辛多雷再也不能沦陷！', '', 28153),
(143624, 'zhCN', '我们的虚空实验进展顺利，必定获得突破……但鼠目寸光的罗曼斯却反对我们。', '', 28153),
(143623, 'zhCN', '<跳跃落地：总计3>', '', 28153),
(143622, 'zhCN', '', '<跳跃落地：总计3>', 28153),
(143621, 'zhCN', '<痛苦哀嚎：总计3>', '', 28153),
(143620, 'zhCN', '<跳跃落地：总计3>', '', 28153),
(143619, 'zhCN', '赫兹雷尔，开始扫描，寻找解决纳兹米尔古神腐化的办法。', '赫兹雷尔，开始扫描，寻找解决纳兹米尔古神腐化的办法。', 28153),
(143618, 'zhCN', '我们去看看这些鱼是否准备好上钩了吧！', '', 28153),
(143617, 'zhCN', '', '<跳跃落地：总计3>', 28153),
(143616, 'zhCN', '', '这片林地是我们姐妹的乐园。如今变成这样……我的心充满忧伤。', 28153),
(143615, 'zhCN', '我们会一起证明他们错了。', '', 28153),
(143614, 'zhCN', '我们得慢慢适应新的身体，但我们期待着您的归来，风行者女士。至于$p……我们忠心感谢你。', '', 28153),
(143613, 'zhCN', '', '作为交换，我会指引你们前行。我和$p会把这个消息告诉至高王乌瑞恩。然后我会回来教导你们。', 28153),
(143612, 'zhCN', '银月城很早就背叛了我们。今天，我们重生了……所以也应该选择新的道路。从今天起，我们效忠联盟。', '', 28153),
(143611, 'zhCN', '', '我感到了你手中的力量。真是……惊人。你会成为联盟的宝贵盟友。', 28153),
(143610, 'zhCN', '我玩弄着我控制不了的力量，差点被傲慢毁灭。奥蕾莉亚，教教我们吧，我们会遵从你的领导。', '', 28153),
(143609, 'zhCN', '', '我已下令在奥格瑞玛建好了大使馆，争取让其他人加入我们的事业。去那儿见我。', 28153),
(143608, 'zhCN', '', '部落领导军团之战时太过无私，使得军力下降。我们的敌人妄想趁机夺取我们的应得之物。不能让他们得逞。', 28153),
(143607, 'zhCN', '', '你看到我们在希利苏斯的行动了，$p。显然，联盟在竭力破坏我们的成果。', 28153),
(143606, 'zhCN', '时机到了，应该有新鲜血液加入联盟的事业了。我们在暴风城建立了一座大使馆。到那儿去见我。\n', '', 28153),
(143605, 'zhCN', '部落会不惜一切夺取艾泽拉斯的生命之血。我担心联盟在经历了军团之战后，军力已经空虚，无法阻止他们的侵犯。\n', '', 28153),
(143604, 'zhCN', '你已经亲眼见证了希利苏斯的惨状，$p。你了解目前的危机。', '', 28153),
(143603, 'zhCN', '到格罗玛什要塞外见我。别声张……否则后果自负。', '', 28153),
(143602, 'zhCN', '军情已经暴露。这事关部落的利益。我们必须抢在对手前面。', '', 28153),
(143601, 'zhCN', '$p！黑暗女王要你到奥格瑞玛见我。', '', 28153),
(143600, 'zhCN', '到雄狮之眠来见我。你懂的，会面的事千万别声张。', '', 28153),
(143599, 'zhCN', '我们发现了一些……敏感信息，他坚持要告诉你。', '', 28153),
(143598, 'zhCN', '$p，乌瑞恩国王请你到暴风城与我汇合。', '', 28153),
(143597, 'zhCN', '我也带来了外来者，他们想和你谈谈，伟大的神灵。', '', 28153),
(143596, 'zhCN', '', '夜之子聪明又强大。你们的古代知识对我们的事业很有帮助。', 28153),
(143595, 'zhCN', '', '客套话到此为止了。你还得证明自己，英雄。但不论你在何方，都在为部落而战！', 28153),
(143594, 'zhCN', '', '不过，我还是会留意你们的战果。身为大酋长，我对你们期待很高，也会奖赏功勋卓著的人。', 28153),
(143593, 'zhCN', '', '部落在世界上有很多对手。他们视我们为劲敌……又或者是流亡者。但我们因团结而强大，并与妄图剥夺我们自由的人奋战。\n', 28153),
(143592, 'zhCN', '', '至高岭牛头人力量与勇气兼备，在接下来的日子里对我们很重要。', 28153),
(143591, 'zhCN', '', '啊，年轻的英雄$p比我先到了。我听说你很有前途。但愿那些报告属实。', 28153),
(143590, 'zhCN', '一路平安，$p。愿圣光永远与你同在。', '', 28153),
(143589, 'zhCN', '虚空精灵虽然才刚刚加入我们，但奥蕾莉亚·风行者是我们最伟大的英雄之一。有了她的指引，你的力量必将对我们的事业大有帮助。', '', 28153),
(143588, 'zhCN', '我们要把你们赶出去！', '', 28153),
(143587, 'zhCN', '一路平安，$p。虽然你在暗影中行走，但依然是我们的希望明灯。', '', 28153),
(143586, 'zhCN', '希望听到你们的好消息。我感觉我们很快会再见面。', '', 28153),
(143585, 'zhCN', '艾泽拉斯纷争不断。接下来，你会面对许多敌人和考验。对抗黑暗时，你们绝非孤军奋战，有联盟在你们身边。', '', 28153),
(143584, 'zhCN', '光铸者虽然才刚刚加入我们，但我已经很了解德莱尼了。你们一定会体现圣光军团的奉献和勇气。', '', 28153),
(143583, 'zhCN', '欢迎你，$p。我是安度因·乌瑞恩国王。我要祝贺你成为联盟的新成员。', '', 28153),
(143582, 'zhCN', '我需要治疗！', '', 28153),
(143581, 'zhCN', '别来抢我们的伐木场！', '', 28153),
(143580, 'zhCN', '部落把我们带到了一个多么有趣而阴沉的小角落里。\n\n我相信在我的新阵营里，大多数地盘会比这地方更优雅和干净吧？', '', 28153),
(143579, 'zhCN', '原谅我，$p。\n\n我很乐意与你聊天，但恐怕我就快吐了。\n\n别喝这里的酒。', '', 28153),
(143578, 'zhCN', '<酿酒师塞斯那拉一边瞪着酒保，一边慢慢地把他的酒倒在旁边地上。>', '', 28153),
(143577, 'zhCN', '你尝过这里的酒吗？\n\n你必须试试。那味道真是可怕到难以置信。\n\n乐手可以写歌来描述那种史诗级的糟糕口感。\n\n讲真，简直是地底馊水的杰作，酒精破坏者，派对终结者。', '', 28153),
(143576, 'zhCN', '到目前为止，我相信赞达拉巨魔擅长建造庞大又恶心的建筑。\n\n但我不相信他们会酿酒。', '', 28153),
(143575, 'zhCN', '如果你酿不出好酒，就别酿酒。', '', 28153),
(143574, 'zhCN', '再给我买一杯这种酒，让我再吐一次到地上。', '', 28153),
(143573, 'zhCN', '他们管这泔水叫酒？怪不得巨魔们要放弃这个城市。', '', 28153),
(143572, 'zhCN', '我们终于自由了！快，离开这儿！', '我们终于自由了！快，离开这儿！', 28153),
(143571, 'zhCN', '这些木头怪物简直是噩梦！', '', 28153),
(143569, 'zhCN', '不知道……能不能……进保险……', '不知道……能不能……进保险……', 28153),
(143568, 'zhCN', '', '这地方虽然残破不堪，感觉还是很眼熟……', 28153),
(143567, 'zhCN', '再加把劲儿，你们这些懒骨头！', '再加把劲儿，你们这些懒骨头！', 28153),
(143566, 'zhCN', '建筑内部安全。指定物体“塔兰吉公主”已加入。', '', 28153),
(143565, 'zhCN', '好了。我们去克莱因吧！', '', 28153),
(143562, 'zhCN', '太迟了，戈霍恩已经无法控制。万物都会沦落。一切都会死亡。', '', 28153),
(143561, 'zhCN', '你的末日降临了。戈霍恩将获得自由。艾泽拉斯是我们的。', '', 28153),
(143560, 'zhCN', '把你的值钱的东西都放在宝库里，然后接着走，$p。\n\n我盯着你呢……', '', 28153),
(143559, 'zhCN', '德鲁斯瓦的黑暗时代降临了，但我们终将夺回这片土地！', '', 28153),
(143558, 'zhCN', '为了赞达拉！', '', 28153),
(143557, 'zhCN', '莱赞，一起狩猎吧！', '', 28153),
(143556, 'zhCN', '是的。只要陆地人一声令下，我们就出发。', '', 28153),
(143555, 'zhCN', '风之神灵帕库，到空中找出那些异教徒。探查出他们的意图，然后来神殿见我们。', '', 28153),
(143554, 'zhCN', '狩猎之神贡克，带领你的追随者前往先知神殿，杀死你能找到的所有敌人，把他们驱赶到开阔地带。', '', 28153),
(143553, 'zhCN', '赞达拉的兄弟姐妹们，是时候把这些投靠了祖尔的叛徒的脑袋砍下来了。', '', 28153),
(143552, 'zhCN', '', '其他人要为克莱因之旅做准备。元帅，你已经有进攻计划了吗？', 28153),
(143551, 'zhCN', '', '是，长官！', 28153),
(143550, 'zhCN', '', '把炼金之火的配方交给隼林镇的艾什顿大师。他就能配制出来了。', 28153),
(143549, 'zhCN', '', '幸好，隼林镇有个炼金专家，就在南面。森林很危险，所以你得走山间老路。', 28153),
(143548, 'zhCN', '', '圣典里有炼金之火的配方，但是需要高超的技巧，我们大家都不行。', 28153),
(143547, 'zhCN', '', '如果要彻底剿灭女巫会，光靠白银可不够。我们需要火。', 28153),
(143546, 'zhCN', '', '谢谢你，长官！小姐，您有何吩咐？', 28153),
(143545, 'zhCN', '克利多恩队长——我是说，审判官克利多恩绝对值得信赖。我相信她可以完成你的任何要求。', '', 28153),
(143544, 'zhCN', '', '元帅，有人选推荐吗？', 28153),
(143543, 'zhCN', '', '出发前，我需要一个人为骑士团完成一项特殊使命。', 28153),
(143542, 'zhCN', '你敢相信部落从未建立过正式的传送管理局吗？我的意思是，我不知道他们的人是怎么安全旅行的。一想到那些随机传送门在现实世界四处开洞，完全没有合适的定位……\n\n哎，不管酬劳多少，我都非常乐意为部落提供一个稳定的传送网络。请继续。', '', 28153),
(143540, 'zhCN', '这座镇子上的人都很坚强，但这对我们的勇气仍是巨大的考验。', '', 28153),
(143539, 'zhCN', '', '孩子们，淹死这些虫子。让它们瞧瞧我引以为傲的力量。', 28153),
(143537, 'zhCN', 'Brgl！Brglrgl！', '', 28153),
(143536, 'zhCN', 'Mrgl，mrglrglrgl！Mrrrg！Mrrrg！！', '', 28153),
(143531, 'zhCN', '窥探', '窥探', 28153),
(143530, 'zhCN', '这事儿就靠你了，孩子！上船！', '', 28153),
(143529, 'zhCN', '莱赞之爪号好像有什么不对劲。我们向其附近派出了斥候。', '', 28153),
(143523, 'zhCN', '把金子给我，马上就要到收工时间了！', '', 28153),
(143520, 'zhCN', '我准备好了，把合成的戈霍恩精华给我吧。', '我准备好了，把合成的戈霍恩精华给我吧。', 28153),
(143519, 'zhCN', '达卡大王！他发现我们了！救我！', '', 28153),
(143518, 'zhCN', '你……输了？输给了他们？可悲！马上去幽暗城，重新训练。看来我得从基础教你了……', '', 28153),
(143517, 'zhCN', '这场胜利真狼狈，但至少你好好教训了那些联盟狗。为了部落！', '', 28153),
(143516, 'zhCN', '我闻到了……狼人？夹杂在联盟自以为是的臭气里，好难区分呢。', '', 28153),
(143515, 'zhCN', '干掉他们！如果让大酋长失望了，你们也没好果子吃！', '', 28153),
(143514, 'zhCN', '联盟的士兵这么废柴？真可悲！有个人连剑都挥不动！', '', 28153),
(143513, 'zhCN', '开火！一个活口都不留！', '', 28153),
(143512, 'zhCN', '天哪！又有更多艾泽里特。跟着地图，把那些地方抢过来！', '', 28153),
(143511, 'zhCN', '又有新的艾泽里特喷发点，该死的岛！跟着地图去找吧。', '', 28153),
(143510, 'zhCN', '快了。别掉链子。再来点艾泽里特！', '', 28153),
(143509, 'zhCN', '哈！从联盟手上抢来啦！干得不错！', '', 28153),
(143508, 'zhCN', '第一次嘛，还行，但我们需要更多的艾泽里特！', '', 28153),
(143507, 'zhCN', '需要补给的话，就去拿吧。但女妖之王要的东西可别丟了！', '', 28153),
(143506, 'zhCN', '补给过来了。别让联盟把这些补给抢了！', '', 28153),
(143505, 'zhCN', '下面有……艾泽里特！给大酋长抢过来。如果有联盟挡路，就让他们血流成河。出发！', '', 28153),
(143504, 'zhCN', '让我好好看看你们。呃……可悲！怎么一个黑暗游侠都没有？嗯，只能凑合了。', '', 28153),
(143503, 'zhCN', '发现联盟的船！那些杂种就会跟在我们屁股后面。各就各位！', '', 28153),
(143502, 'zhCN', '你们使命很简单。收集所有的艾泽里特，一点都不要留给联盟。这么说应该够清楚吧。', '', 28153),
(143501, 'zhCN', '部落的勇士们！菲拉斯近海的荒岛上发现了艾泽里特矿藏。你们必须以黑暗女王的名义夺取那里！', '', 28153),
(143500, 'zhCN', '让他们滚！这座岛是我们的！', '', 28153),
(143499, 'zhCN', '为国王而战！为联盟而战！', '', 28153),
(143498, 'zhCN', '部落自以为很聪明。让他们长长见识！', '', 28153),
(143497, 'zhCN', '开火！把治疗者干掉！', '', 28153),
(143496, 'zhCN', '你们都很壮实。嗯……多来点潜行者就更好了，但有你们也够了！', '', 28153),
(143495, 'zhCN', '见鬼！这次部落占了上风。但我以雄狮之眠发誓，我们终将胜利！', '', 28153),
(143494, 'zhCN', '干得好，勇士！乌瑞恩国王知道了一定会大喜过望。为了联盟！', '', 28153),
(143493, 'zhCN', '补给来了！去拿吧，勇士们！', '', 28153),
(143492, 'zhCN', '又有艾泽里特喷发点！看看地图，把它们拿下！', '', 28153),
(143491, 'zhCN', '干得好。再多来点艾泽里特，今天就大获全胜了！', '', 28153),
(143490, 'zhCN', '部落没拿到那份艾泽里特。干得漂亮！', '', 28153),
(143489, 'zhCN', '干得好，英雄们。但我们需要更多艾泽里特！', '', 28153),
(143488, 'zhCN', '英雄们！我们在给你们空投补给品。别让部落抢了！', '', 28153),
(143487, 'zhCN', '岛上发现了别的艾泽里特喷发点！位置标注在你的地图上了。', '', 28153),
(143486, 'zhCN', '我们下方有丰富的艾泽里特矿藏。快下去，多收集点。如果有部落强盗挡路……就把他们干掉！', '', 28153),
(143485, 'zhCN', '发现部落船只！那些人渣一定是跟着我们来的。各就各位！', '', 28153),
(143484, 'zhCN', '我们的船开到了岛屿中心。尽量收集艾泽里特。它是胜利的关键！', '', 28153),
(143483, 'zhCN', '勇士们，菲拉斯近海有座岛上发现了艾泽里特矿藏。我们必须赶在部落之前拿下那里。', '', 28153),
(143482, 'zhCN', '', '真是荣幸，女伯爵莉亚德琳。欧库勒斯有银月城的坐标，我会叫上希尔格林和瓦尔托伊。到那儿见。', 28153),
(143481, 'zhCN', '', '我想摄政王听到你的话肯定很高兴。你准备好出发了吗？', 28153),
(143480, 'zhCN', '', '所以我很感谢您邀请我前往银月城。我想借此询问，夜之子在你们的部落里能不能有一席之地。', 28153),
(143479, 'zhCN', '', '联盟过于封闭……过于与世隔绝。我的人民再也无法忍受这种静滞。', 28153),
(143478, 'zhCN', '', '辛多雷也被泰兰德和她高傲的盟友嘲笑。他们多年来睡在山洞，躲在树巅，而我们则在为拯救这个世界奋战。', 28153),
(143477, 'zhCN', '', '看来，“艾露恩的智慧”不想让她修复与我们的关系。那就这样吧。', 28153),
(143476, 'zhCN', '', '卡多雷愿意为击败军团、摧毁暗夜井而战。除此之外……就全赖艾露恩的智慧指引了。', 28153),
(143475, 'zhCN', '', '我们不想做暗夜井的奴隶。我们想把军团赶出苏拉玛，并结束艾利桑德的高压统治。', 28153),
(143474, 'zhCN', '', '奥术师塔莉萨。我还记得你们在上古之战中的表现。你怎么保证不会背叛我们，不会成为下一个艾利桑德……下一个艾萨拉？', 28153),
(143473, 'zhCN', '', '我本以为卡利姆多的远亲更适合结盟。但他们既傲慢，又多疑，我很失望。', 28153),
(143472, 'zhCN', '', '我必须承认，第一次听说部落时，我怀疑我们是否会有共同点。', 28153),
(143471, 'zhCN', '', '能与你并肩对抗燃烧军团，部落也很自豪，女士。', 28153),
(143470, 'zhCN', '', '我们都欠你一份情。你对我们的事业帮助巨大。', 28153),
(143469, 'zhCN', '', '苏拉玛已经解放，首席奥术师。', 28153),
(143468, 'zhCN', '', '$p，欢迎回到苏拉玛。如今的情况比上次好多了，我很高兴。', 28153),
(143467, 'zhCN', '', '令人失望，但并不意外……神灵没有祝福你，孩子。你无法和我们一同登上选民之台。', 28153),
(143466, 'zhCN', '你肯定是走了很远的路才来到这里，年轻人。$b$b我这里有好几本关于螃蟹历史的小说，如果你感兴趣的话。', '', 28153),
(143465, 'zhCN', '', '坚毅而骄傲，你可以拖垮敌人，熬过所有风暴。我们需要你的力量来保卫城市。', 28153),
(143464, 'zhCN', '', '这……非同凡响。你的力量在未来可堪重任。', 28153),
(143463, 'zhCN', '', '自私而缺乏荣誉感……你最好另谋出路，小家伙。', 28153),
(143462, 'zhCN', '', '有意思……隐蔽又聪明，你从阴影中发动攻击。出其不意将成为你最大的武器。', 28153),
(143461, 'zhCN', '', '我知道了。你动作敏捷，善于观察，谨慎出击。你的耐心会得到回报。', 28153),
(143460, 'zhCN', '', '深入你的内心，孩子。告诉我你要如何猎杀你的猎物。用智慧、力量，还是别的东西？', 28153),
(143459, 'zhCN', '', '兽群强烈地呼唤着你。拥抱这股亲切的纽带，与你的兄弟姐妹一起去狩猎吧。', 28153),
(143458, 'zhCN', '你闻到了吗？我闻到卷心菜的气味。$b$b<克洛纳凑上来闻了闻你。>$b$b不是你身上的，是这附近的什么东西。$b$b我说，你的字写得怎么样？想让我教教你吗？不管你信不信，我可是一位书法大师。', '', 28153),
(143457, 'zhCN', '我们遭到了攻击！', '我们遭到了攻击！', 28153),
(143456, 'zhCN', '准备好你们的武器，兄弟姐妹们！', '准备好你们的武器，兄弟姐妹们！', 28153),
(143455, 'zhCN', '敌人混入我们当中了！', '敌人混入我们当中了！', 28153),
(143454, 'zhCN', '入侵者！拿起武器！', '入侵者！拿起武器！', 28153),
(143452, 'zhCN', '非常愿意。', '', 28153),
(143451, 'zhCN', '行动起来！', '', 28153),
(143450, 'zhCN', '还有订单要完成！', '', 28153),
(143449, 'zhCN', '', '请不要分散孩子的注意力。\n\n我在测试这些孩子是否能与神灵联系。受到神灵祝福的孩子会接受正式的祭司训练，以及所有随之而来的荣誉和特权。\n\n没有受到祝福的孩子将得到机会，去证明自己未来可以成长为强大的战士。\n\n两项测试都失败的孩子对我们毫无用处。他们最后可能会在码头上行窃，或去佐卡罗广场乞讨。', 28153),
(143448, 'zhCN', '我可以做到。', '', 28153),
(143447, 'zhCN', '好了好了。', '', 28153),
(143446, 'zhCN', '干活，干活。', '', 28153),
(143445, 'zhCN', '我们需要更多木材！', '', 28153),
(143444, 'zhCN', '死了以后有的是时间休息。在那之前，快完成订单！', '', 28153),
(143443, 'zhCN', '我会在它全部消失之前，尽快回到村子里。也许他们还没忘记我。', '', 28153),
(143442, 'zhCN', '我不认为自己能够再像以前那样。作为一头没有智慧的猩猩活着。经历过我的所见所感，无论多么短暂，我都无法回到从前了。', '', 28153),
(143441, 'zhCN', '达卡是对的。我已经感觉到我的智慧正逐渐向原始状态退化。', '', 28153),
(143440, 'zhCN', '你好，旅行者。今天有兴趣来点卷轴吗？$b$b或者由最为稀有的草药制成的异国墨水？', '', 28153),
(143439, 'zhCN', '地精的脑子只有核桃仁那么大，你得再干掉几百只他们才能长记性。', '', 28153),
(143438, 'zhCN', '你给这些地精好好上了一课。这就是跟黑铁矮人作对的下场！', '', 28153),
(143437, 'zhCN', '把机器轰飞！把工具砸烂！这些小绿崽子敢反抗的话，就送他们上西天！', '', 28153),
(143436, 'zhCN', '这些地精正在大规模腐化艾泽里特！无法容忍！', '', 28153),
(143435, 'zhCN', '终于可以把“反对者”夺回来了。让这些地精领教一下，偷黑铁矮人的东西是什么下场！', '', 28153),
(143434, 'zhCN', '谁？谁驱散了迷雾？达卡大王要杀了你！', '', 28153),
(143433, 'zhCN', '为了部落！', '为了部落！', 28153),
(143432, 'zhCN', '小提饥饿地凝视着猪。', '', 28153),
(143431, 'zhCN', '小提开心地摇晃。', '', 28153),
(143430, 'zhCN', '', '谁是可爱的小迅猛龙宝宝？就是你！就是你！', 28153),
(143429, 'zhCN', '', '哦，见到你真是太好了，小家伙！$n。谢谢你。', 28153),
(143428, 'zhCN', '', '那是小提吗？！', 28153),
(143427, 'zhCN', '小提开心地颤抖着。', '', 28153),
(143426, 'zhCN', '', '还会有……其他蛇人……', 28153),
(143425, 'zhCN', '', '赞达拉帝国已经日薄西山。无信者会夺取它的残骸！', 28153),
(143424, 'zhCN', '我要把你五马分尸！', '我要把你五马分尸！', 28153),
(143423, 'zhCN', '小提迎风抬起鼻子。她发出一声尖锐的呼喊。', '', 28153),
(143422, 'zhCN', '在你的女王面前跪下，佃农！', '在你的女王面前跪下，佃农！', 28153),
(143421, 'zhCN', '她也会……带走……你……', '她也会……带走……你……', 28153),
(143420, 'zhCN', '斯托颂家族必将统治这片土地！', '斯托颂家族必将统治这片土地！', 28153),
(143419, 'zhCN', '', '感谢你还有你的帮助！$n，准备好了就去暗尾的洞穴吧，拿这东西帮助本金。', 28153),
(143418, 'zhCN', '', '我可以制作设备来读取雷龙的大脑扫描，并进行分析。', 28153),
(143417, 'zhCN', '', '科学是唯一的答案，贾拉尔。我无意贬低你的权威，但神神叨叨无法代替严密正经的的化学。', 28153),
(143416, 'zhCN', '让那些软弱的人类见识下部落的力量！', '', 28153),
(143415, 'zhCN', '等我们的刀砍到他们身上时，那些人类会害怕我们的！', '', 28153),
(143414, 'zhCN', '为了部落！', '', 28153),
(143413, 'zhCN', '我要回祖达萨了……别担心我，我自己能回去的。下次去城里的时候记得来看我。', '', 28153),
(143412, 'zhCN', '等等，金蒂基。带上这只迅猛龙。毕竟他……似乎更喜欢你。', '', 28153),
(143411, 'zhCN', '小心警戒！我可不想让那些人类在我们的磨坊附近四处打探！', '', 28153),
(143410, 'zhCN', '抓紧工作！', '', 28153),
(143409, 'zhCN', '看来我们在这里的工作完成了。我要到沃顿去，为我的罪行付出代价了。', '', 28153),
(143408, 'zhCN', '要是让我看到有人在干活儿的时候睡着了，我就亲手把他抓去喂狼！', '', 28153),
(143407, 'zhCN', '保证资源供应源源不断！', '', 28153),
(143404, 'zhCN', '你的末日……即将来临……', '你的末日……即将降临……', 28153),
(143403, 'zhCN', '怎么……可能……', '怎么……可能……', 28153),
(143402, 'zhCN', '', '骑上你们的龙，前往城市。等我们杀完，会给你们带来一筐蛇头！', 28153),
(143401, 'zhCN', '你终将面对……风暴……之眼……', '你终将面对……风暴……之眼……', 28153),
(143400, 'zhCN', '你……会……陨落……', '你……会……陨落……', 28153),
(143399, 'zhCN', '那里。雾气就是从那深处冒出来的。', '', 28153),
(143398, 'zhCN', '我的灵魂……归于……大海……', '我的灵魂……归于……大海……', 28153),
(143397, 'zhCN', '我要前往……波涛……之下……', '我要前往……波涛……之下……', 28153),
(143396, 'zhCN', '他们杀了我们的酋长！整个村子都被毁了！', '', 28153),
(143395, 'zhCN', '主气孔在里面。快来！', '', 28153),
(143394, 'zhCN', '我会回归……深渊……', '我会回归……深渊……', 28153),
(143391, 'zhCN', '潮水终将……退去……', '潮水终将……退去……', 28153),
(143390, 'zhCN', '她的力量在我的血液中涌动！', '她的力量在我的血液中涌动！', 28153),
(143389, 'zhCN', '拥抱末日吧！', '拥抱末日吧！', 28153),
(143388, 'zhCN', '让命运的触须吞噬你！', '让命运的触须吞噬你！', 28153),
(143387, 'zhCN', '生命会脱离你的躯壳！', '生命会脱离你的躯壳！', 28153),
(143386, 'zhCN', '你的生命会在溺亡时寂灭！', '你的生命会在溺亡时寂灭！', 28153),
(143385, 'zhCN', '没人能阻止无尽的浪潮！', '没人能阻止无尽的浪潮！', 28153),
(143384, 'zhCN', '听从深渊的召唤！\n', '听从深渊的召唤！\n', 28153),
(143383, 'zhCN', '海浪会卷走你！', '海浪会卷走你！', 28153),
(143382, 'zhCN', '达卡大王……陨落了。', '', 28153),
(143381, 'zhCN', '', '但……你承诺过……荣耀……', 28153),
(143380, 'zhCN', '歹徒！你就像蜡烛，熄灭时更有用。', '', 28153),
(143379, 'zhCN', '', '你很强大，但你终将跟其他人一样臣服于女巫会！', 28153),
(143378, 'zhCN', '', '没关系。死人不会告密。攻击，宠物们！', 28153),
(143377, 'zhCN', '', '被你发现了。你一定觉得自己很聪明吧。', 28153),
(143376, 'zhCN', '哈！如果无法带给你力量，那智慧还有什么用？我将成为赞达拉之王。你要么留下见证，要么就去死吧！', '', 28153),
(143375, 'zhCN', '你必须住手了，达卡。我们本不该具备智慧。更别说发起战争！', '', 28153),
(143374, 'zhCN', '曾加……你带着一个渺小的生命，来到神圣的迷雾中。你为何而来？', '', 28153),
(143373, 'zhCN', '这里出什么事了？', '这里出什么事了？', 28153),
(143372, 'zhCN', '我在深渊中……看到了真理……', '我在深渊中……看到了真理……', 28153),
(143371, 'zhCN', '我为海潮……流尽鲜血……', '我为海潮……流尽鲜血……', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143370, 'zhCN', '去吧，迷雾的源头就在这个洞里。我不知道达卡大王在哪里。快点！', '', 28153),
(143369, 'zhCN', '这地方的鲜血魔法很强大，连不是巫医的人都能从空气中感觉到……到处都是……', '', 28153),
(143368, 'zhCN', '', '哦……陆地人，你在这里干什么？\n\n有什么我能帮你的吗？', 28153),
(143367, 'zhCN', '你想让我杀谁？', '', 28153),
(143366, 'zhCN', '漂亮！', '', 28153),
(143365, 'zhCN', '为了部落！', '', 28153),
(143364, 'zhCN', '杀戮时间到！', '', 28153),
(143363, 'zhCN', '杀戮很容易。', '', 28153),
(143362, 'zhCN', '不留活口！', '', 28153),
(143361, 'zhCN', '许多人会掉脑袋！', '', 28153),
(143360, 'zhCN', '荣耀归于部落！', '', 28153),
(143359, 'zhCN', '', '荣耀归于部落！', 28153),
(143358, 'zhCN', '', '许多人会掉脑袋！', 28153),
(143357, 'zhCN', '', '不留活口！', 28153),
(143356, 'zhCN', '我们永不……停歇……', '我们永不……停歇……', 28153),
(143355, 'zhCN', '就算杀了我……也没用……', '就算杀了我……也没用……', 28153),
(143354, 'zhCN', '我们已经……胜利了……', '我们已经……胜利了……', 28153),
(143353, 'zhCN', '', '杀戮很容易。', 28153),
(143352, 'zhCN', '我只是……听命行事……', '我只是……听命行事……', 28153),
(143351, 'zhCN', '海潮贤者……请保护我……', '海潮贤者……请保护我……', 28153),
(143350, 'zhCN', '我的生命……献给大海……', '我的生命……献给大海……', 28153),
(143349, 'zhCN', '库尔提拉斯属于大海！', '库尔提拉斯属于大海！', 28153),
(143348, 'zhCN', '你竟敢跟斯托颂家族作对？', '你竟敢跟斯托颂家族作对？', 28153),
(143347, 'zhCN', '我们就像漆黑的海渊一样冰冷无情！', '我们就像漆黑的海渊一样冰冷无情！', 28153),
(143346, 'zhCN', '跟我们作对的人都得死！', '跟我们作对的人都得死！', 28153),
(143345, 'zhCN', '我们的舰队会让你灰飞烟灭！', '我们的舰队会让你灰飞烟灭！', 28153),
(143344, 'zhCN', '', '杀戮时间到！', 28153),
(143343, 'zhCN', '', '跟我来，姐妹！', 28153),
(143342, 'zhCN', '如果没有我们，库尔提拉斯必将葬身鱼腹！', '如果没有我们，库尔提拉斯必将葬身鱼腹！', 28153),
(143341, 'zhCN', '', '跟我来，兄弟！', 28153),
(143340, 'zhCN', '山谷属于我们，舱底鼠！', '山谷属于我们，舱底鼠！', 28153),
(143339, 'zhCN', '以斯托颂之名！', '以斯托颂之名！', 28153),
(143338, 'zhCN', '', '好多死亡的细颚龙……我从蛋里把它们养大。这就像看着我的孩子们死去。$b$b那些蛇人必须血债血偿。', 28153),
(143337, 'zhCN', '附近建筑周围有大量腐化。需要立即采取行动。', '', 28153),
(143336, 'zhCN', '局部恢复成功。必须继续修理抑制器来处理腐化。', '', 28153),
(143335, 'zhCN', '正在升级辅助系统。请稍候……', '', 28153),
(143334, 'zhCN', '你能修理装备吗？', '你能修理装备吗？', 28153),
(143333, 'zhCN', '村庄已经毁了，但他们想要夺走熔炉，除非踏过我的尸体。', '', 28153),
(143332, 'zhCN', '', '为了部落！', 28153),
(143331, 'zhCN', '', '漂亮！', 28153),
(143330, 'zhCN', '', '你想让我杀谁？', 28153),
(143329, 'zhCN', '我很高兴无辜者安全了，但我们还有很多工作要做。', '', 28153),
(143328, 'zhCN', '', '不久前，暴风城对我还只是传说。我会走街串巷，探索其中的美妙。愿暗影指引你，$n。', 28153),
(143327, 'zhCN', '圣光与你同在，$n。我计划在艾泽拉斯寻找燃烧军团，继续我们永恒的战斗。', '', 28153),
(143326, 'zhCN', '我当然不会这么干……其实我考虑了一下。差不多有一秒钟呢！', '', 28153),
(143325, 'zhCN', '我得承认，看你们干活的劲儿，我真想让你们分一杯羹。', '', 28153),
(143324, 'zhCN', '干得好！接下来才是最英勇的壮举……填写表格，获取矿井的所有权。庄重又正式。', '', 28153),
(143323, 'zhCN', '但老实说，还是把它们干掉吧，免得影响我的收益。', '', 28153),
(143322, 'zhCN', '目标已完成。正在移动至前方位置。移动至新位置完成任务。', '', 28153),
(143321, 'zhCN', '哈！这群笨蛋碎成渣了。这些元素下手还真狠。', '', 28153),
(143320, 'zhCN', '小提紧紧地蜷缩起来。', '', 28153),
(143319, 'zhCN', '小提痛苦地鸣叫！', '', 28153),
(143318, 'zhCN', '世界在流血，而你们还在撕扯伤口？！去死吧！', '', 28153),
(143317, 'zhCN', '我要看到爆炸、混乱、过激的暴力！你懂的……你最擅长不过了。', '', 28153),
(143316, 'zhCN', '让那些风险投资公司的暴发户明白，他们的就是我的。', '', 28153),
(143315, 'zhCN', '但问题是……它不是我的！所以要由你来处理了。', '', 28153),
(143314, 'zhCN', '黑市的艾泽里特是从这儿挖出来的吧？还真成气候了。', '', 28153),
(143313, 'zhCN', '', '“座狼之灾”？没听说过。但……等等，这是什么？', 28153),
(143312, 'zhCN', '你的善良高于这个世界，兄弟。我会保证你得到妥善安葬的。', '', 28153),
(143311, 'zhCN', '我最爱清晨时分魔精的芬芳！', '', 28153),
(143310, 'zhCN', '', '洛坎说你对这种事情很有经验。这件事就交给你了。我就在这里等待地精小队吧。', 28153),
(143308, 'zhCN', '', '$n，我们必须尽可能地争取盟友。请尽快解决这位守护者的问题。', 28153),
(143307, 'zhCN', '需要协助。修复赫兹雷尔。进入附近建筑内部。抑制纳兹米尔所有的腐化。', '', 28153),
(143306, 'zhCN', '探测到纳兹米尔内部有大量腐蚀力量，必须进行控制。', '', 28153),
(143305, 'zhCN', '我参加过许多战斗……但这样的怪物……我从未见过……', '', 28153),
(143304, 'zhCN', '你们休想活捉我！', '', 28153),
(143303, 'zhCN', '好吧，沃顿也比这个地方更安全！', '', 28153),
(143302, 'zhCN', '不！不要！迅猛龙……它们会吃了我的！', '', 28153),
(143301, 'zhCN', '……谢谢你，扎路托。也许来生我们能做兄弟。', '', 28153),
(143300, 'zhCN', '对祖拉金使用鲜血雕像，吸收他的力量，将他送回坟墓！', '', 28153),
(143299, 'zhCN', '别担心，伙计！你去清理废墟的时候，我会在这里照顾船长的！', '', 28153),
(143298, 'zhCN', '好了！现在穿上伪装，去拿钥匙！', '', 28153),
(143297, 'zhCN', '你需要通过伪装骗过祖拉金。拿到补给品就快赶快回来！', '', 28153),
(143296, 'zhCN', '我虽然是个罪犯，但本性并不坏。我不会丢下你在这儿等死的！', '', 28153),
(143295, 'zhCN', '感谢你，就算是死……我也能光荣地死去了……', '', 28153),
(143294, 'zhCN', '来！向拯救了我们所有人的勇士<嗝>英雄致敬！', '', 28153),
(143293, 'zhCN', '', '去奥格瑞玛。与盟友汇合，共同塑造崭新的未来。', 28153),
(143292, 'zhCN', '', '你游历艾泽拉斯的同时，记得讲述夜之子的骄傲历史……并告诉大家，我们不再避世隐居。', 28153),
(143291, 'zhCN', '我们对夜之子了解多少？', '我们对夜之子了解多少？', 28153),
(143290, 'zhCN', '', '$n，你能来真是太好了。我们必须说服大酋长与夜之子结盟。', 28153),
(143289, 'zhCN', '我们对至高岭牛头人了解多少？', '我们对至高岭牛头人了解多少？', 28153),
(143288, 'zhCN', '', '现在，我们要证明，我们会为部落带来力量和荣耀。', 28153),
(143287, 'zhCN', '我们与至高岭牛头人有很多共同之处。我相信在接下来的战斗中，他们是理想的盟友。', '', 28153),
(143286, 'zhCN', '', '别担心曾加。我们会照顾他的。即使他已忘记自己的名字。', 28153),
(143285, 'zhCN', '', '老天，他可真壮，不是吗？干得好，朋友！', 28153),
(143284, 'zhCN', '', '愿星辰指引你的道路，$p。我听说希尔斯布莱德丘陵有很多趣事，很想去那里旅行。', 28153),
(143283, 'zhCN', '', '你确定吗，曾加？如果这位勇士驱散迷雾，你知道自己会失去什么吗？', 28153),
(143282, 'zhCN', '我会准备仪式超度这些灵魂。在北边的海岸线上跟我会合吧。', '', 28153),
(143281, 'zhCN', '我完全了解后果。但我相信，有些东西虽然难以舍弃，但势在必行。', '', 28153),
(143280, 'zhCN', '我从另一条路进入峡谷，到那里和你碰头。', '', 28153),
(143279, 'zhCN', '保持阵型！援军就快来了。我们不能让纳迦破坏堤坝！', '', 28153),
(143278, 'zhCN', '你的心灵将放下所有仇恨。', '', 28153),
(143277, 'zhCN', '', '但辛多雷——血精灵——尊重和理解我们。我们的远亲证明，在艾泽拉斯还有其他人和我们看法相同。', 28153),
(143276, 'zhCN', '', '苏拉玛面临危机时，艾泽拉斯的英雄与我们并肩赶走了军团。可有些人并不太情愿。', 28153),
(143275, 'zhCN', '', '这是苏拉玛的传统服装。穿上吧，牢记我们古老的过去，然后和我们的盟友一起，创造新的未来。', 28153),
(143274, 'zhCN', '你不用和我说两遍！', '', 28153),
(143273, 'zhCN', '', '你向部落和全艾泽拉斯证明，夜之子有意愿和勇气保卫我们的世界。', 28153),
(143272, 'zhCN', '前往船厂另一边的海岸线，找一名年轻的普罗德摩尔学员——泰莉亚。快去！', '', 28153),
(143271, 'zhCN', '', '回苏拉玛来。你帮助族人在这个世界重获地位，我们要感谢你。', 28153),
(143270, 'zhCN', '', '你是夏多雷的第一批冒险者，你游历了艾泽拉斯的荒野。但现在，该回家了。', 28153),
(143269, 'zhCN', '那些劳工……他们被海潮贤者的魔法束缚住了！我们必须帮助他们。', '', 28153),
(143268, 'zhCN', '感谢潮汐，并不是每个人都发疯了，只有半个家族而已！', '', 28153),
(143267, 'zhCN', '我不想穿木工装了。', '我不想穿木工装了。', 28153),
(143266, 'zhCN', '', '我先去前方查探。我们海边见！', 28153),
(143265, 'zhCN', '你看着挺精神，$n。', '', 28153),
(143264, 'zhCN', '我们有活儿要做。', '', 28153),
(143263, 'zhCN', '我想穿木工装。', '我想穿木工装。', 28153),
(143262, 'zhCN', '', '拿起武器！', 28153),
(143261, 'zhCN', '', '为了国王！', 28153),
(143260, 'zhCN', '', '发起进攻！', 28153),
(143259, 'zhCN', '', '誓死奋战！', 28153),
(143258, 'zhCN', '', '为了暴风城！', 28153),
(143257, 'zhCN', '', '为了联盟！', 28153),
(143256, 'zhCN', '', '不许撤退！', 28153),
(143255, 'zhCN', '', '让我来教训他们！', 28153),
(143254, 'zhCN', '', '你指的是什么腐化？$n，也许这东西觉得鲜血巨魔就是“腐化”。', 28153),
(143253, 'zhCN', '', '$n，你知道这东西是什么吗？它会愿意帮助我们吗？', 28153),
(143252, 'zhCN', '', '这是什么巫毒法术？！或许它能帮助我们阻止鲜血巨魔和戈霍恩……', 28153),
(143251, 'zhCN', '让我来教训他们！', '', 28153),
(143250, 'zhCN', '不许撤退！', '', 28153),
(143249, 'zhCN', '为了联盟！', '', 28153),
(143248, 'zhCN', '为了暴风城！', '', 28153),
(143247, 'zhCN', '誓死奋战！', '', 28153),
(143246, 'zhCN', '发起进攻！', '', 28153),
(143245, 'zhCN', '为了国王！', '', 28153),
(143244, 'zhCN', '拿起武器！', '', 28153),
(143243, 'zhCN', '哇，探测器跟疯了似的，看来岛上的某处发生了艾泽里特大喷发。', '', 28153),
(143242, 'zhCN', '我们必须找出这片污秽背后的根源。', '', 28153),
(143241, 'zhCN', '', '这身护甲是你成就的纪念，$p。请收下它，以表我的感谢。', 28153),
(143240, 'zhCN', '毫无疑问。', '', 28153),
(143239, 'zhCN', '你……你认为海洋生物也被感染了吗？', '', 28153),
(143238, 'zhCN', '还有个“不祥的预兆”，就是海湾里全是风舷军的猎物。', '', 28153),
(143237, 'zhCN', '曾加担心地在洞口张望。', '', 28153),
(143236, 'zhCN', '', '很多人怀疑，朗多雷无法驾驭虚空之力，注定成为它的牺牲品。你已经证明他们大错特错。', 28153),
(143235, 'zhCN', '随着我们深入海湾，海水的哭喊也愈发刺耳。我能感受到海潮的痛苦。真是不祥的预兆。', '', 28153),
(143234, 'zhCN', '', '你已经成为了联盟的强大武器，$p。回到虚空裂隙，让我们来嘉奖你的成就吧。', 28153),
(143233, 'zhCN', '我们办正事吧。', '', 28153),
(143230, 'zhCN', '我要开始训练了。你去看看塔加尔特，他还有事找你。', '', 28153),
(143229, 'zhCN', '泰坦守护者赫兹雷尔已重启。协议：抑制纳兹米尔肆虐的腐化。系统损坏，任务无法完成。', '', 28153),
(143228, 'zhCN', '', '经过在艾泽拉斯的冒险之旅， 这股力量虽然总想控制你，但终于为你所用。', 28153),
(143227, 'zhCN', '太棒了，我的朋友。我们来看看它的飞行情况。哟呵！', '', 28153),
(143226, 'zhCN', '呵呵！看看小猫拖了什么进来！难以置信！', '', 28153),
(143224, 'zhCN', '我去告诉拉斯塔哈大王，塔楼一亮，就说明我们已经把船抢回来了。这就是个信号，可以告诉我的船员，他们可以回家啦！', '', 28153),
(143223, 'zhCN', '这张照片里的目标不清晰，乌尔菲德不会满意的。', '这张照片里的目标不清晰，乌尔菲德不会满意的。', 28153),
(143222, 'zhCN', '我的朋友，帮帮我吧！', '', 28153),
(143221, 'zhCN', '我的工人……我辜负了他们。', '', 28153),
(143220, 'zhCN', '', '来人！指挥官被击中了！', 28153),
(143219, 'zhCN', '救命！我被攻击了！', '', 28153),
(143218, 'zhCN', '就管你要好了！', '', 28153),
(143217, 'zhCN', '这家伙真把我惹毛了！', '', 28153),
(143216, 'zhCN', '啊！我的保险金！', '', 28153),
(143215, 'zhCN', '我养这群蠢货干什么？！快出来修理！', '', 28153),
(143214, 'zhCN', '尝尝高水准的屠杀吧！', '', 28153),
(143213, 'zhCN', '享受每分钟300发的弹药吧！', '', 28153),
(143212, 'zhCN', '对，你只配倒在我脚下！', '', 28153),
(143211, 'zhCN', '倒下吧！', '', 28153),
(143210, 'zhCN', '', '我去侦察一下，在前面等你！', 28153),
(143209, 'zhCN', '永远别想活捉我！', '', 28153),
(143208, 'zhCN', '应该……购买……弹射椅……套件……', '', 28153),
(143207, 'zhCN', '我会把弹药费寄到你亲戚家。', '', 28153),
(143206, 'zhCN', '', '使用我教你的东西控制虚空。成为联盟的武器，即使你行走在黑暗边缘。', 28153),
(143205, 'zhCN', '会有人质疑你，觉得你没有决心和能力驾驭这股力量，因为有弱者已经被它逼疯。', '', 28153),
(143204, 'zhCN', '', '但我们看到了其他方法。许多道路和可能都展现在我们面前。', 28153),
(143203, 'zhCN', '', '有人会说，圣光才是正路，是对抗艾泽拉斯的敌人的唯一武器。', 28153),
(143202, 'zhCN', '你们这群无赖，知道给我造成了多大的财产损失吗！？', '', 28153),
(143201, 'zhCN', '欢迎来到蛮项！', '', 28153),
(143200, 'zhCN', 'DELETE ME', '', 28153),
(143199, 'zhCN', '砸烂！', '', 28153),
(143198, 'zhCN', '碾压！', '', 28153),
(143197, 'zhCN', '粉碎！', '', 28153),
(143196, 'zhCN', '可惜我没能教会他最重要的一课。', '', 28153),
(143195, 'zhCN', '告诉老拉斯塔哈，我会抽空回去。哦，还要谢谢你一路的帮助。', '', 28153),
(143193, 'zhCN', '等我的利爪抓住亚兹玛和祖尔，我要把他们摔在石头上！', '', 28153),
(143192, 'zhCN', '猎物就在附近。祖尔、亚兹玛和他们的异教徒很快就会血债血偿。这将是一次伟大的狩猎。', '', 28153),
(143191, 'zhCN', '荣耀属于帕库！', '荣耀属于帕库！', 28153),
(143190, 'zhCN', '这艘船将属于我们！', '这艘船将属于我们！', 28153),
(143189, 'zhCN', 'Taz\'okun！', 'Taz\'okun！', 28153),
(143188, 'zhCN', '只是皮肉之伤。我应该不会有事的。', '', 28153),
(143185, 'zhCN', '', '化为飞灰吧！', 28153),
(143184, 'zhCN', '', '烧吧！对！烧吧！', 28153),
(143183, 'zhCN', '', '想要艾泽里特？我喷你一脸！', 28153),
(143182, 'zhCN', '', '啊哦！看来我得把“无重大伤亡”计时器归零了。', 28153),
(143181, 'zhCN', '这一切都不值得！', '', 28153),
(143180, 'zhCN', '', '新手只会送命！', 28153),
(143179, 'zhCN', '为了联盟！', '', 28153),
(143178, 'zhCN', '', '我十分荣幸能再度为国王效力。为了联盟！', 28153),
(143177, 'zhCN', '', '这个申请人也不合格！', 28153),
(143176, 'zhCN', '你们立下了大功，$p，还有风行者女士。我感谢你们。', '', 28153),
(143175, 'zhCN', '虚空精灵要赢得我们所有人的信任还需要时间。但既然他们遵从你的教导，联盟也欢迎他们加入。', '', 28153),
(143174, 'zhCN', '', '我应该……拿……危险津贴的……', 28153),
(143173, 'zhCN', '', '我会引导和训练他们控制暗影的低语。作为报答，他们会为联盟而战。', 28153),
(143172, 'zhCN', '', '至高王陛下，我和$p找到了辛多雷流亡者。他们跟我一样，都被虚空改变了，但他们的心灵依然属于自己。', 28153),
(143171, 'zhCN', '', '干活要想出色……就要用超大炸弹！', 28153),
(143170, 'zhCN', '', '我的工人就是被你吓跑的吗？', 28153),
(143169, 'zhCN', '', '嘿！你这是要去哪儿？', 28153),
(143168, 'zhCN', '入侵者？！快逃命！！！', '入侵者？！快逃命！！！', 28153),
(143167, 'zhCN', '我不知道是什么样的黑暗力量控制了你的思想，但它将无法再折磨我们的人民。', '', 28153),
(143166, 'zhCN', '你可以做到的！', '', 28153),
(143165, 'zhCN', '快跑！', '', 28153),
(143164, 'zhCN', '', '你们谁都不准再抱怨工作环境了！', 28153),
(143163, 'zhCN', '这里不安全。你必须离开这个地方。', '', 28153),
(143162, 'zhCN', '反正这也不是什么好岛屿！', '', 28153),
(143161, 'zhCN', '我们完了！', '', 28153),
(143160, 'zhCN', '走吧！你的工作已经完成了。', '', 28153),
(143159, 'zhCN', '他挣脱了！快回来！', '', 28153),
(143158, 'zhCN', '你们自由了，兄弟姐妹们。', '', 28153),
(143157, 'zhCN', '', '你是因为唠唠叨叨才吸进毒气的，可别怪我！', 28153),
(143156, 'zhCN', '回你家人身边吧，这里由我们处理。', '', 28153),
(143155, 'zhCN', '快走吧，傻瓜们！', '', 28153),
(143154, 'zhCN', '让灵魂脱离你的凡躯，漂流入海不复回。', '', 28153),
(143153, 'zhCN', '在风暴的歌声中获得平静吧。', '', 28153),
(143152, 'zhCN', '不要怀疑，灯塔之光正是为你而亮。', '', 28153),
(143151, 'zhCN', '', '为了部落！', 28153),
(143150, 'zhCN', '', '为了部落！', 28153),
(143149, 'zhCN', '', '苏拉玛与部落同在！', 28153),
(143148, 'zhCN', '', '苏拉玛数千年都孤立无援。今天，你们加入了伟大的同盟。我接纳你们，塔莉萨。', 28153),
(143147, 'zhCN', '', '夜之子需要在艾泽拉斯诸国中寻求盟友。如果您接纳我们，我们必定会派出力量襄助您的事业。', 28153),
(143146, 'zhCN', '', '部落象征着力量、决心、独立。这些我们夏多雷也非常珍视。', 28153),
(143145, 'zhCN', '', '的确如此，首席奥术师。', 28153),
(143144, 'zhCN', '', '我深感荣幸，大酋长。我曾与莉亚德琳女士和摄政王并肩作战。他们证明了您的部落多么英勇。', 28153),
(143143, 'zhCN', '不要害怕，兄弟。海浪不会以貌取人。', '', 28153),
(143142, 'zhCN', '波涛和潮汐都无法淹没你灵魂的哀鸣。', '', 28153),
(143141, 'zhCN', '愿你英勇的灵魂永远安息。', '', 28153),
(143140, 'zhCN', '愿无底深渊收容你疲惫的灵魂。', '', 28153),
(143139, 'zhCN', '潮汐之母净化你不洁的肉体。', '', 28153),
(143138, 'zhCN', '海流会将你带走，牺牲者。', '', 28153),
(143137, 'zhCN', '大地会吞噬你！', '', 28153),
(143136, 'zhCN', '尘归尘，土归土，海潮归于大海。', '', 28153),
(143135, 'zhCN', '粉碎！', '', 28153),
(143134, 'zhCN', '艾泽拉斯之血在你体内流淌！', '', 28153),
(143133, 'zhCN', '我们不能再让这些迷失的灵魂徘徊下去了。我有话要和你说，$p。', '', 28153),
(143132, 'zhCN', '释放你的力量！', '', 28153),
(143131, 'zhCN', '有点浸水了，但还能读。这些咒语可以派上大用场。', '', 28153),
(143130, 'zhCN', '海雾隐藏了很多东西，但这个道标应该能帮我们到达那边。', '', 28153),
(143129, 'zhCN', '起来吧！', '', 28153),
(143128, 'zhCN', '', '欢迎你，孩子。我的视力也许抛弃了我，但帕库没有。\n\n坐过来，提出你对伟大神灵的问题吧。我会尽量回答。', 28153),
(143127, 'zhCN', '很好，刀刃依然锋利。越锋利才越安全。', '', 28153),
(143126, 'zhCN', '你再也不能作恶了。', '', 28153),
(143125, 'zhCN', '你的血又有多值钱？', '', 28153),
(143124, 'zhCN', '', '大酋长希尔瓦娜斯·风行者，这是苏拉玛的首席奥术师塔莉萨。', 28153),
(143123, 'zhCN', '', '我会与其他人汇合，等待你的命令，$c。', 28153),
(143122, 'zhCN', '', '我持保留态度……但我会执行命令。', 28153),
(143121, 'zhCN', '', '里德元帅觉得，你是击败女巫会的关键？', 28153),
(143120, 'zhCN', '拿出干劲来！', '', 28153),
(143119, 'zhCN', '呵，是时候了。', '', 28153),
(143118, 'zhCN', '再用点力气！', '', 28153),
(143117, 'zhCN', '拉！', '', 28153),
(143116, 'zhCN', '来，温斯顿。看来我们要去打女巫了。', '', 28153),
(143115, 'zhCN', '再用力砍几下就成了。', '', 28153),
(143114, 'zhCN', '她就快成功了！还差一点。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143113, 'zhCN', '又有新命令？', '', 28153),
(143112, 'zhCN', '感谢你把军令送来，$c。我会即刻向维克雷斯小姐报到。', '', 28153),
(143111, 'zhCN', '我还以为他们的故事只是历史学家想象力过剩的产物。', '', 28153),
(143110, 'zhCN', '你们不过是寄生虫。', '', 28153),
(143109, 'zhCN', '传言是真的？灰烬骑士团复活了？', '', 28153),
(143108, 'zhCN', '必须治愈……伤口……', '', 28153),
(143107, 'zhCN', '', '我发誓为你效命，$c。', 28153),
(143106, 'zhCN', '你闯进了我的地盘！', '', 28153),
(143105, 'zhCN', '', '我对这些小戏法没兴趣，但只要不用窝在这儿坐以待毙，我就愿意加入。', 28153),
(143104, 'zhCN', '', '你就是那个重建“灰烬骑士团”的人吧。最近大家都在说呢。', 28153),
(143103, 'zhCN', '<递过里德元帅的命令。>', '<递过里德元帅的命令。>', 28153),
(143102, 'zhCN', '', '构造体参战了。活人不够了，他就创造了新的军队。但石头的能源是什么？', 28153),
(143101, 'zhCN', '', '我能为你做什么，$c？', 28153),
(143100, 'zhCN', '', '这肯定是他们最崇高的首领——高莱克·图尔。啊！他在指挥仪式，创造岩石构造体！', 28153),
(143099, 'zhCN', '<斯坦泰德中尉轻轻点了点头，向你致意。>', '', 28153),
(143098, 'zhCN', '他很是个很好的样本，对吧？维克雷斯家族的驯鹰技术一直举世闻名。\n\n不幸的是，我们最好的鹰大部分都中了女巫会的诅咒。只有少数几只维克雷斯猎鹰没有受到影响，温斯顿就是之一。\n\n提起来真是让人伤心。', '', 28153),
(143097, 'zhCN', '', '可这……他们美化了屠杀行为！库尔提拉斯人根本手无寸铁！', 28153),
(143096, 'zhCN', '陆地人，森林里有什么邪恶的东西在扰动。每天夜里，森林中心的古代德鲁斯特纪念碑就会释放出邪恶的力量，不停地闪光。\n\n如果我是你，在旅行的时候就会避开那里。', '', 28153),
(143095, 'zhCN', '', '怎么了，陆地人？\n\n如果看不出来的话，我可以告诉你，我现在有点忙。', 28153),
(143094, 'zhCN', '消灭入侵者，净——化，净化。', '', 28153),
(143093, 'zhCN', '腐蚀即将释放，正在激——激活安——安——安全协议，发现入——入侵者。', '', 28153),
(143092, 'zhCN', '错误……检——检测到……入侵行为……正在扫描……腐蚀。', '', 28153),
(143091, 'zhCN', '毒气使用已授权。', '', 28153),
(143090, 'zhCN', '电压已提高。', '', 28153),
(143089, 'zhCN', '系统已启动。打击开始。', '', 28153),
(143088, 'zhCN', '', '石碑上的库尔提拉斯人好像是……平民？水手和农民？', 28153),
(143087, 'zhCN', '', '他们的首领也从战场撤退了。', 28153),
(143086, 'zhCN', '', '哈！我们从这儿开始反击！', 28153),
(143085, 'zhCN', '', '没看到他们的构造体参战，真有意思。', 28153),
(143084, 'zhCN', '风险投资公司感谢您的惠顾。请享受您购买的精英打击套件。', '', 28153),
(143083, 'zhCN', '', '他们又攻下了一座库尔提拉斯人的定居点。中间的角色很大，应该是他们的传奇领袖。', 28153),
(143082, 'zhCN', '风险投资公司感谢您的惠顾。请享受您购买的基础打击套件。', '', 28153),
(143081, 'zhCN', '给我几个月，我就能让这地方脱胎换骨，变成六星度假胜地！', '', 28153),
(143080, 'zhCN', '你傻啊！千万别买延保服务！', '你傻啊！千万别买延保服务！', 28153),
(143079, 'zhCN', '好的好的！等等……我是不是该购买延保服务？', '好的好的！等等……我该不该购买延保服务？', 28153),
(143078, 'zhCN', '来吧，$p，我的朋友。', '', 28153),
(143077, 'zhCN', '他们会杀了我们的！', '他们会杀了我们的！', 28153),
(143076, 'zhCN', '别催我！我在读许可协议！', '别催我！我在读许可协议！', 28153),
(143075, 'zhCN', '快！他们来了！', '快！他们来了！', 28153),
(143074, 'zhCN', '我只是想休息一下。', '', 28153),
(143073, 'zhCN', '冷静点，好孩子。冷静。', '', 28153),
(143072, 'zhCN', '系统……崩溃中。硬币获取……故障……', '', 28153),
(143071, 'zhCN', '谁想去飞一圈？你想去飞一圈吗？我们去飞一圈吧！', '', 28153),
(143070, 'zhCN', '别咬！', '', 28153),
(143069, 'zhCN', '伤害控制程序已启动。', '', 28153),
(143068, 'zhCN', '伤害此单位会违反用户协议。', '', 28153),
(143067, 'zhCN', '炸弹来啦！', '炸弹来啦！', 28153),
(143066, 'zhCN', '下面的渣滓，当心点！', '下面的渣滓，当心了！', 28153),
(143065, 'zhCN', '你，对，快回去干活！', '你，对，快回去干活！', 28153),
(143064, 'zhCN', '致命武力已授权。', '', 28153),
(143063, 'zhCN', '人群数量超过最大承载值。驱散。', '', 28153),
(143062, 'zhCN', '同时提供葬礼服务，价格实惠。', '', 28153),
(143061, 'zhCN', '又一个满意的顾客。\n', '', 28153),
(143060, 'zhCN', '风险投资公司不负责寻回断肢。', '', 28153),
(143059, 'zhCN', '部落守住了一波攻势！', '部落守住了一波攻势！', 28153),
(143058, 'zhCN', '分头行动！那些联盟狗会派增援到我们这里来的。', '', 28153),
(143057, 'zhCN', '', '这艘船占领港口之后，我就会成为船长！你们现在最好听我的话，学会鞠躬！', 28153),
(143056, 'zhCN', '', '这些囚犯不知道他们有多幸运！他们很快就会与祖尔同行。', 28153),
(143055, 'zhCN', '', '如果我们要占领这座港口，你们就必须再卖力一些！', 28153),
(143054, 'zhCN', '我控制……不住了……啊啊啊啊啊！', '', 28153),
(143050, 'zhCN', '不！我不想死在这儿！我的死期还没到！', '', 28153),
(143049, 'zhCN', '他是怎么……知道的……', '', 28153),
(143048, 'zhCN', '这……怎么会这样！', '', 28153),
(143047, 'zhCN', '你很强大……但远远不如我的洞察之力！', '', 28153),
(143046, 'zhCN', '我命令你，滚开！', '', 28153),
(143045, 'zhCN', '我的选民！主人需要你们！', '', 28153),
(143044, 'zhCN', '你才会葬身此地！', '', 28153),
(143043, 'zhCN', '你才没有棋高一招呢，老家伙！', '', 28153),
(143042, 'zhCN', '你说得对，我阻止不了。但我朋友可以。', '', 28153),
(143041, 'zhCN', '你我都清楚，我不会死在你的手上。你阻止不了我。', '', 28153),
(143040, 'zhCN', '好孩子。差不多该给你奖励了！', '', 28153),
(143039, 'zhCN', '我玩腻了。你已经把话传到了，现在接受你的命运吧。', '', 28153),
(143038, 'zhCN', '祖尔一口喝下药水。那味道让他颤抖。', '', 28153),
(143037, 'zhCN', '就是你第一眼看到的那瓶，不用细想，快。', '', 28153),
(143036, 'zhCN', '他的爪牙会试图阻止你。保持警惕。', '', 28153),
(143035, 'zhCN', '嗯。', '', 28153),
(143034, 'zhCN', '过来。时间到了。', '', 28153),
(143033, 'zhCN', '很好。现在把沃加巴的一瓶药水换成我给你的那瓶。', '', 28153),
(143032, 'zhCN', '等一下……往左边挪一点吧。', '', 28153),
(143031, 'zhCN', '现在把声之瓮放到门廊附近。', '', 28153),
(143030, 'zhCN', '离开大使馆后记得随时准备好武器，$p。这些赞达拉巨魔缺乏自控所需的力量和毅力。他们需要一个像我们这样强大的首领。\n\n那么，我能为你做什么吗？', '离开大使馆后记得随时准备好武器，$p。这些赞达拉巨魔缺乏自控所需的力量和毅力。他们需要一个像我们这样强大的首领。\n\n那么，我能为你做什么吗？', 28153),
(143029, 'zhCN', '如果你看到有联盟潜伏在附近，就告诉我。我来解决他们。\n\n现在，你在找什么？', '如果你看到有联盟潜伏在附近，就告诉我。我来解决他们。\n\n现在，你在找什么？', 28153),
(143028, 'zhCN', '我得夸夸赞达拉巨魔，他们的大使馆造的真不错。这座城市也是大的没边！\n\n你迷路了吗？', '我得夸夸赞达拉巨魔，他们的大使馆造的真不错。这座城市也是大的没边！\n\n你迷路了吗？', 28153),
(143027, 'zhCN', '我很忙。有话快说。', '我很忙。有话快说。', 28153),
(143026, 'zhCN', '你需要什么，$pr？', '你需要什么，$pr？', 28153),
(143025, 'zhCN', '荣耀属于大酋长！你在找什么？', '荣耀属于大酋长！你在找什么？', 28153),
(143024, 'zhCN', '这座雄伟的大使馆证明赞达拉巨魔尊重我们大酋长的力量。他们也应该感到害怕。\n\n那么，你有什么需要吗？', '这座雄伟的大使馆证明赞达拉巨魔尊重我们大酋长的力量。他们也应该感到害怕。\n\n那么，你有什么需要吗？', 28153),
(143023, 'zhCN', '这里的湿气都快让我的骨头出汗了。我能为你做什么？', '这里的湿气都快让我的骨头出汗了。我能为你做什么？', 28153),
(143022, 'zhCN', '我们要上去了，大家伙。总有一天，这些都会归我们。', '', 28153),
(143021, 'zhCN', '我们付钱给你，是为了让你偷懒的吗？', '', 28153),
(143020, 'zhCN', '', '也许，死亡才是风行者家族的真正遗产。', 28153),
(143019, 'zhCN', '', '我也是。有时候我觉得自己已经死了两次。第一次是在德拉诺失踪，第二次是被堕落纳鲁的阴影包围。', 28153),
(143018, 'zhCN', '看着我们的烈士雕像，我心里很沉重。', '', 28153),
(143017, 'zhCN', '', '命运已经来临，图拉扬。我得再亲眼看看故乡……亲耳听希尔瓦娜斯解释，她为何要成为大酋长。', 28153),
(143016, 'zhCN', '你们都有自己的路。如果圣光要让它们交汇，那就终将如此。命运不必强求。', '', 28153),
(143015, 'zhCN', '你可以不用去的，不必去看她。', '', 28153),
(143014, 'zhCN', '', '因为你最懂我的心。', 28153),
(143013, 'zhCN', '你心里还是很紧张……我看得出来。', '', 28153),
(143012, 'zhCN', '我知道接下来还有很多挑战，但是，无论如何……别忘了守护艾泽拉斯！', '', 28153),
(143011, 'zhCN', '你武器中流窜的能量……我从来没见过！但记住，所有力量都是有代价的。', '', 28153),
(143010, 'zhCN', '成功了！萨格拉斯之剑休眠了。艾泽拉斯还没有愈合……但你的行为争取了宝贵的时间。', '', 28153),
(143009, 'zhCN', '团结起来，勇士们！为了艾泽拉斯！', '', 28153),
(143008, 'zhCN', '一起举起武器……将腐化之力从黑暗泰坦之剑里吸走！', '', 28153),
(143007, 'zhCN', '唯一能压制这种力量的容器，就是你们手中的强大武器。', '', 28153),
(143006, 'zhCN', '萨格拉斯之剑正在荼毒这个世界的生命之血。', '', 28153),
(143005, 'zhCN', '来希利苏斯吧……趁世界还一息尚存，奋斗吧！', '', 28153),
(143004, 'zhCN', '我知道局势正剑拔弩张……但我希望你们能再次团结起来。', '', 28153),
(143003, 'zhCN', '勇士们，你们联合各自的组织，一起把燃烧军团赶出了艾泽拉斯。', '', 28153),
(143002, 'zhCN', '战火正在酝酿，$p。但如果不先治疗艾泽拉斯，别的都毫无意义。', '', 28153),
(143001, 'zhCN', '我不知道该怎么办。谁又知道呢？但我们必须努力。', '', 28153),
(143000, 'zhCN', '从阿古斯归来后，艾泽拉斯的哭喊就一直……痛彻心扉。好疼啊……', '', 28153),
(142999, 'zhCN', '勇士……时世艰难，但很高兴能再次看到你。', '', 28153),
(142998, 'zhCN', '我们还在等待援军，公主。但我们获得了有关神灵卡格瓦的线索。', '', 28153),
(142997, 'zhCN', '', '……这就是托加的命运。部落的援军有什么消息吗？', 28153),
(142996, 'zhCN', '快要完成了，$n。只要再坚持一下。', '', 28153),
(142995, 'zhCN', '真不敢相信，那些怪物杀了托加……', '', 28153),
(142994, 'zhCN', '哎，托加死了，我回去后就没什么故事可以跟其他人讲了。', '', 28153),
(142993, 'zhCN', '琪莎在哪？我还以为她会在这里指引我……', '', 28153),
(142992, 'zhCN', '好吧，我会去林荫巨木，看看到底会有多疯狂。', '', 28153),
(142991, 'zhCN', '哈……好吧，我想和一群鲜血巨魔战斗会是个有趣的故事。很好，我会去林荫巨木。', '', 28153),
(142990, 'zhCN', '你是说……什么？我不会错过这个故事的，我要去林荫巨木。', '', 28153),
(142989, 'zhCN', '好吧，基夏。我们去林荫巨木，把路上碰到的同胞都叫上。我们的朋友$n会把遗漏的人也叫上。', '', 28153),
(142988, 'zhCN', '', '我这就去林荫巨木，沿途的始祖龟就交给你了。', 28153),
(142987, 'zhCN', '$n，用那些火炮！', '', 28153),
(142986, 'zhCN', '祝你好运，$p。至于我，我要去灰谷测试我的技巧了。为了部落！', '', 28153),
(142985, 'zhCN', '帕库之息号和莱赞之爪号的确在周游世界后回来了。帮助他们尽快回到故乡吧。', '', 28153),
(142984, 'zhCN', '船只返航时，带回一片黑暗。我的内心深处涌现一股不好的预感。', '', 28153),
(142983, 'zhCN', '帕库之息号是我多年来的家。我的心就像这座海港，从它离开后就一直空荡荡。', '', 28153),
(142982, 'zhCN', '“雷霆之声”安吉的咆哮让你充满能量。', '', 28153),
(142981, 'zhCN', '喂！上船！船长说帕库之息号遇到麻烦了！', '', 28153),
(142980, 'zhCN', '', '指挥官，我们来帮忙了。堤坝绝不会溃于今日！', 28153),
(142979, 'zhCN', '', '我们去堤坝吧。指挥官利德不喜欢等人！', 28153),
(142977, 'zhCN', '你不适合这个地方！', '', 28153),
(142976, 'zhCN', '你是个愚蠢的懦夫！', '', 28153),
(142975, 'zhCN', '我鄙视你，无耻的入侵者！', '', 28153),
(142974, 'zhCN', '快滚，无赖！', '', 28153),
(142973, 'zhCN', '吃我一记老拳！', '', 28153),
(142972, 'zhCN', '我要打得你满地找牙！', '', 28153),
(142971, 'zhCN', '我会用这只手打掉你的牙！', '', 28153),
(142970, 'zhCN', '立正！', '', 28153),
(142969, 'zhCN', '', '以维克雷斯家族之名，我任命你们为灰烬骑士团的审判官！', 28153),
(142968, 'zhCN', '', '今天，你们化身为对抗无尽大军的希望灯塔。', 28153),
(142967, 'zhCN', '', '今天，你们化身为斩断邪恶的光明之刃。', 28153),
(142966, 'zhCN', '', '兄弟们，姐妹们，今天，你们化身为荡涤黑暗的炽热烈焰。', 28153),
(142965, 'zhCN', '', '啊，找到了。', 28153),
(142964, 'zhCN', '', '圣典里也介绍了征召仪式。我看看……', 28153),
(142963, 'zhCN', '', '谢谢你的支援，元帅。这样我们就有骑士团的样子了！', 28153),
(142962, 'zhCN', '我等着见大王，已经好几天了。你一定会觉得，他对地精在这里的勾当更感兴趣。', '', 28153),
(142961, 'zhCN', '我们这里驻扎着许多精兵，小姐。他们可以加入你的灰烬骑士团。', '', 28153),
(142960, 'zhCN', '', '元帅，我们找到了对抗女巫会的武器。我们需要身强体壮的士兵来使用它们。', 28153),
(142959, 'zhCN', '我永远不会背叛神灵和这座城市！', '', 28153),
(142958, 'zhCN', '我信仰帕库。鲜血魔法是禁忌！', '', 28153),
(142957, 'zhCN', '我说真话。我完全不知道什么鲜血古董！', '', 28153),
(142956, 'zhCN', '我是无辜的！求求你，饶了我。', '', 28153),
(142955, 'zhCN', '我没有偷运过鲜血古董！鲜血魔法是邪恶的！', '', 28153),
(142954, 'zhCN', '我从没见过什么鲜血古董！', '', 28153),
(142953, 'zhCN', '我不知道你在说什么！', '', 28153),
(142952, 'zhCN', '我没有做错任何事！', '', 28153),
(142951, 'zhCN', '别逼我再捅你……', '', 28153),
(142950, 'zhCN', '你把鲜血古董卖给谁了？', '', 28153),
(142949, 'zhCN', '你让我恶心，叛徒。', '', 28153),
(142948, 'zhCN', '我要让你生不如死，普洛迪托。我们要用你杀鸡儆猴。', '', 28153),
(142947, 'zhCN', '如果你认罪，我保证赐你速死。', '', 28153),
(142946, 'zhCN', '你是最恶心的那种人渣，普洛迪托。鲜血魔法正在残害我们的人民！', '', 28153),
(142945, 'zhCN', '我们知道你在往我们的城市里偷运鲜血古董。', '', 28153),
(142944, 'zhCN', '告诉我们，你是怎么得到鲜血古董的，普洛迪托！', '', 28153),
(142943, 'zhCN', '这个混蛋一直在往我们的城市里偷运鲜血古董。\n\n他会认罪的，然后我们就用他杀鸡儆猴。', '', 28153),
(142942, 'zhCN', '我没有做错任何事！告诉他们！', '', 28153),
(142941, 'zhCN', '（离开）', '（离开）', 28153),
(142940, 'zhCN', '<逃犯泰什延比沾满血迹、残破不堪的尸体几乎难以辨认。看起来似乎是附近迅猛龙干的。>', '<逃犯泰什延比沾满血迹、残破不堪的尸体几乎难以辨认。看起来似乎是附近迅猛龙干的。>', 28153),
(142939, 'zhCN', '我知道你是谁，莫乔巴。到沃顿去吧，接受你的流放。', '我知道你是谁，莫乔巴。到沃顿去吧，接受你的流放。', 28153),
(142938, 'zhCN', '你是谁？你想要什么，嗯？', '', 28153),
(142937, 'zhCN', '很抱歉，由于你犯下的罪行，你将被流放到沃顿。', '很抱歉，由于你犯下的罪行，你将被流放到沃顿。', 28153),
(142936, 'zhCN', '嘘！别让迅猛龙和祖拉金看到我。我要回祖达萨去。', '', 28153),
(142935, 'zhCN', '', '就逃犯而言……你干得不错。', 28153),
(142934, 'zhCN', '', '我们已经拿下了这座监狱，钥匙也归我们了。现在我们可以清点艾泽里特，释放人质了。', 28153),
(142933, 'zhCN', '', '看来艾什凡女勋爵还会再找个狱长。', 28153),
(142932, 'zhCN', '放火悠着点！说你呢，火法师。如果艾泽里特弹药爆炸了，我们都会化为灰烬！', '', 28153),
(142931, 'zhCN', '准备战斗，士兵！他们来了！', '', 28153),
(142930, 'zhCN', '', '我们来守住下层，你们上去见狱长吧。', 28153),
(142929, 'zhCN', '', '干得好。看来局势已经在你的掌控之下了。', 28153),
(142928, 'zhCN', '等我们把狱长的人质抓到手，就有大笔的赎金可拿啦！', '', 28153),
(142927, 'zhCN', '来吧，伙计们！把门弄开！', '', 28153),
(142926, 'zhCN', '', '他们最好赶快。否则接替你的人要做的第一件事，就是把你跟这群人渣丢去喂鱼。', 28153),
(142925, 'zhCN', '抱歉，艾什凡勋爵。我的人马上就会恢复这里的秩序。', '', 28153),
(142924, 'zhCN', '', '科古斯！你为什么还没给下层灌水，淹死那群叽叽喳喳的老鼠！？', 28153),
(142923, 'zhCN', '', '呕！你们越狱得趟过这堆东西？别站在顺风的方向！', 28153),
(142922, 'zhCN', '', '有这么个怪物，难怪狱长没叫人在岛的这边巡逻。你们居然把它干掉了，真棒。', 28153),
(142921, 'zhCN', '', '我们会留意卫兵，你们去下水道栅栏吧，从那儿应该还可以钻进监狱。', 28153),
(142920, 'zhCN', '', '根据我们的情报，要找到艾泽里特和人质，就得从狱长的脖子上把钥匙拽下来。', 28153),
(142919, 'zhCN', '', '快隐蔽！他们还没发现我们。', 28153),
(142918, 'zhCN', '我一定要这么做吗？', '', 28153),
(142917, 'zhCN', '你想要什么？', '', 28153),
(142916, 'zhCN', '准备工作。', '', 28153),
(142915, 'zhCN', '我们的兵营被摧毁了！', '', 28153),
(142914, 'zhCN', '要赢得这场战争，我们还需要支援。', '', 28153),
(142913, 'zhCN', '回去工作！', '', 28153),
(142912, 'zhCN', '建筑可不会自动建好！', '', 28153),
(142911, 'zhCN', '把锤子挥起来！', '', 28153),
(142910, 'zhCN', '', '奥蕾莉亚很不满。', 28153),
(142909, 'zhCN', '你救了我的命！', '你救了我的命！', 28153),
(142908, 'zhCN', '我应该能够自己去安全的地方。谢谢你。', '我应该能够自己去安全的地方。谢谢你。', 28153),
(142907, 'zhCN', '他们的攻击无休无止。谢谢你的帮助。', '他们的攻击无休无止。谢谢你的帮助。', 28153),
(142906, 'zhCN', '我不会忘记你的英勇作为。', '我不会忘记你的英勇作为。', 28153),
(142905, 'zhCN', '我以为我会死在这里！', '我以为我会死在这里！', 28153),
(142904, 'zhCN', '我们村需要更多像你这样的英雄！', '我们村需要更多像你这样的英雄！', 28153),
(142903, 'zhCN', '为那些没有获救的人报仇。', '为那些没有获救的人报仇。', 28153),
(142902, 'zhCN', '这些纳迦是怪物！', '这些纳迦是怪物！', 28153),
(142901, 'zhCN', '这把匕首会刺穿你的胸膛！', '', 28153),
(142900, 'zhCN', '入侵者正从下水道来袭！', '', 28153),
(142898, 'zhCN', '这块石头正在吟唱一首威力强大的寂静之歌。只有一个人能听见它的旋律，我们只能希望她永远不会降临这片海岸。', '', 28153),
(142897, 'zhCN', '我已经看见了我需要看到的一切。这块石头非常邪恶，必须被摧毁。', '', 28153),
(142894, 'zhCN', '我认为它不会乖乖投降，看来你只有从它的尸体上把那把武器给撬下来了。', '', 28153),
(142893, 'zhCN', '我在南边发现了我们的下一个猎物。你最好动作快点。', '', 28153),
(142892, 'zhCN', '摧毁那艘船反而让库尔提拉斯人缓了一口气，真是遗憾啊。', '', 28153),
(142891, 'zhCN', '黑暗女王一定会认可你的功劳。', '', 28153),
(142890, 'zhCN', '', '这是我的荣幸，摄政王陛下。我们银月城见，勇士。', 28153),
(142889, 'zhCN', '太好了！女伯爵莉亚德琳，请回奥格瑞玛，把好消息告诉大酋长。', '', 28153),
(142888, 'zhCN', '', '我代表夜之子接受这个提议。从今天起，苏拉玛将为部落而战。', 28153),
(142887, 'zhCN', '部落可以帮忙，首席奥术师。加入我们吧，银月城永远欢迎你。', '', 28153),
(142886, 'zhCN', '', '苏拉玛永远都是我们的家。但我们有些人想要去外面的世界冒险，重新在艾泽拉斯确定我们的地位。为此，我们需要盟友。', 28153),
(142885, 'zhCN', '', '我们从盟友那里获得了力量……但我们并没有迷失自己。', 28153),
(142884, 'zhCN', '', '正相反。这次冲突说明了你对人民的爱护。我看到部落让你们保持了自己的传统——这对我们非常重要。', 28153),
(142883, 'zhCN', '很抱歉让你看到这一幕，首席奥术师。我没想到你的访问会变成这样。', '', 28153),
(142882, 'zhCN', '', '如你所愿，摄政王。暂时就这样吧。', 28153),
(142881, 'zhCN', '够了！你走吧，奥蕾莉亚。就算是意外，你也对奎尔萨拉斯的安全构成了威胁。回暴风城去吧，银月城再也不是你的家。', '', 28153),
(142880, 'zhCN', '', '我不会在我自己的故乡束手就擒。', 28153),
(142879, 'zhCN', '卫兵！抓住这个破坏者！', '', 28153),
(142878, 'zhCN', '太阳之井安全了。感谢你的帮助，塔莉萨。你也一样，勇士。', '', 28153),
(142877, 'zhCN', '你在抵抗必然的命运！我必将得到它。', '', 28153),
(142876, 'zhCN', '', '趁现在！把我们的力量结合起来！', 28153),
(142875, 'zhCN', '大门打开了。对……足以满足需要了。', '', 28153),
(142874, 'zhCN', '', '要我们做什么？我们会尽力而为。', 28153),
(142873, 'zhCN', '', '我可以关闭裂隙，但需要帮手。', 28153),
(142872, 'zhCN', '有东西想撑开裂隙进入大厅。如果得逞，太阳井恐怕会失守。', '', 28153),
(142871, 'zhCN', '开始施放法术吧，里卡尔。', '开始施放法术吧，里卡尔。', 28153),
(142870, 'zhCN', '潮汐迟早会改变。这是真理。', '', 28153),
(142869, 'zhCN', '你快抓不住了！', '', 28153),
(142868, 'zhCN', '|TInterface\\Icons\\ABILITY_ROGUE_FANOFKNIVES:20|t%s正准备投掷|cFFFF0000|Hspell:257785|h[闪光飞刃]|h|r！藏起来！', '', 28153),
(142867, 'zhCN', 'Bal\'a dash，malanore。', '', 28153),
(142866, 'zhCN', '每个人都要踏上自己的道路。', '', 28153),
(142865, 'zhCN', '我们的人民代表着崭新的未来。', '', 28153),
(142864, 'zhCN', '从来没有必然的真理。', '', 28153),
(142863, 'zhCN', '宇宙中充满了秘密。', '', 28153),
(142862, 'zhCN', '我们的面前出现了新的机遇。', '', 28153),
(142861, 'zhCN', '过去已成历史。未来尚未确定。', '', 28153),
(142860, 'zhCN', 'Shorel\'aran。', '', 28153),
(142859, 'zhCN', '我们的人民不畏惧暗影。', '', 28153),
(142858, 'zhCN', '真相从不只有一种。', '', 28153),
(142857, 'zhCN', '低语休想控制我们。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142856, 'zhCN', '每次冲动前都要三思。', '', 28153),
(142855, 'zhCN', '别害怕力量，控制它吧。', '', 28153),
(142854, 'zhCN', '要考虑所有可能性。', '', 28153),
(142853, 'zhCN', '你的幼稚行为激怒不了我。', '', 28153),
(142852, 'zhCN', '“记住太阳之井的耻辱”？拜托，我已经听腻了。', '', 28153),
(142851, 'zhCN', '如果有个传送门突然出现在你脚下，在我眼前把你吞进无尽的虚无，请相信我，这一定只是巧合而已。无巧不成书嘛。', '', 28153),
(142850, 'zhCN', '对，宇宙之力改变了我的样子，众所周知，这股力量会使人发疯，于是我突然就成了“可疑分子”，真会以偏概全……\n', '', 28153),
