(140136, 'zhCN', '再见。', '', 28153),
(140135, 'zhCN', '', '心向和平，不忘战斗。', 28153),
(140134, 'zhCN', '心向和平，不忘战斗。', '', 28153),
(140133, 'zhCN', '带着勇气和谦卑侍奉圣光吧。', '', 28153),
(140132, 'zhCN', '', '带着勇气和谦卑侍奉圣光吧。', 28153),
(140131, 'zhCN', '我们会在这个世界上占据一席之地。', '', 28153),
(140130, 'zhCN', '', '我们会在这个世界上占据一席之地。', 28153),
(140129, 'zhCN', '愿阿坎多尔的恩赐滋养着你。', '', 28153),
