(140057, 'zhCN', '<亲吻>', '', 28153),
(140056, 'zhCN', '我们不畏惧黑暗。', '', 28153),
(140055, 'zhCN', '欢迎。', '', 28153),
(140054, 'zhCN', '欢迎你。', '', 28153),
(140053, 'zhCN', '你好。', '', 28153),
(140052, 'zhCN', '我的伤口需要治疗！', '', 28153),
(140051, 'zhCN', '治疗我！', '', 28153),
(140050, 'zhCN', '愿山岭为你遮风挡雨。', '', 28153),
(140049, 'zhCN', '愿旅途给你带来智慧。', '', 28153),
(140048, 'zhCN', '愿大地母亲指引你的道路。', '', 28153),
(140047, 'zhCN', '再见。', '', 28153),
