(159019, 'zhTW', '我們有…成千上萬個…你們阻止不了我們…', '我們有…成千上萬個…你們阻止不了我們…', 28153),
(159018, 'zhTW', '喀…我倒下了…', '喀…我倒下了…', 28153),
(159017, 'zhTW', '我會殺死你，然後把你的屍體餵給蟲群！', '我會殺死你，然後把你的屍體餵給蟲群！', 28153),
(159016, 'zhTW', '你們竟然這麼樂意地踏上末路？', '你們竟然這麼樂意地踏上末路？', 28153),
(159015, 'zhTW', '金礦是我們的！我們要獻給皇后！', '金礦是我們的！我們要獻給皇后！', 28153),
(159014, 'zhTW', '我們為女皇而出戰！', '我們為女皇而出戰！', 28153),
(159013, 'zhTW', '誰都無法阻止蟲群！', '誰都無法阻止蟲群！', 28153),
(159012, 'zhTW', '女皇悅耳的歌聲命我們殺了你。', '女皇悅耳的歌聲命我們殺了你。', 28153),
(159011, 'zhTW', '我奉皇后之命！', '我奉皇后之命！', 28153),
(159010, 'zhTW', '為了女皇！', '為了女皇！', 28153),
(159009, 'zhTW', '聯盟會屹立不搖…而女妖之王的邪惡統治一定會終結。', '', 28153),
(159008, 'zhTW', '她以為可以用殘暴的惡行打擊我們的意志，讓我們分崩離析。但我發誓…', '', 28153),
(159007, 'zhTW', '啊！我光榮地被擊敗…', '啊！我光榮地被擊敗…', 28153),
(159006, 'zhTW', '啊！這就是我渴望的死亡！', '啊！這就是我渴望的死亡！', 28153),
(159005, 'zhTW', '可是只要希瓦娜斯‧風行者繼續帶領部落，這個夢想就不可能實現。', '', 28153),
(159004, 'zhTW', '我將…駛入夕陽…', '我將…駛入夕陽…', 28153),
(159003, 'zhTW', '我一生都在希望這個世界能夠和平。', '', 28153),
(159002, 'zhTW', '我將加入上古戰士的行列…', '我將加入上古戰士的行列…', 28153),
(159001, 'zhTW', '勇士，你在聯盟最痛苦、最黑暗的一天，展現了無比的勇氣跟決心。', '', 28153),
(159000, 'zhTW', '靈魂為我的死亡獻上祝福…', '靈魂為我的死亡獻上祝福…', 28153),
(158999, 'zhTW', '', '先去休息吧。好好準備面對接下來的戰爭。我還需要你。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158998, 'zhTW', '我光榮戰死！', '我光榮戰死！', 28153),
(158997, 'zhTW', '我的部族會為我報仇…', '我的部族會為我報仇…', 28153),
(158996, 'zhTW', '', '但是聯盟確實在流血。接下來的戰爭中，他們的憤怒只會成為弱點。', 28153),
(158995, 'zhTW', '死亡等待著你…', '死亡等待著你…', 28153),
(158994, 'zhTW', '我又要擊敗一名矮小的敵人！', '我又要擊敗一名矮小的敵人！', 28153),
(158993, 'zhTW', '又來一場光榮的戰鬥！', '又來一場光榮的戰鬥！', 28153),
(158992, 'zhTW', '我要挖出你們的眼珠！', '我要挖出你們的眼珠！', 28153),
(158991, 'zhTW', '', '我們只成功了一半。聯盟一定會報仇，聯盟會追殺我，追殺我們所有人。', 28153),
(158990, 'zhTW', '', '我們先下手為強是為了在戰爭開始前就能獲勝…是為了一舉奪取敵人的家園，也消滅敵人的所有領袖。並對聯盟造成無法恢復的沉重打擊。', 28153),
(158989, 'zhTW', '', '當初派你執行這項任務時，我也沒料到結果會是這樣的。', 28153),
(158988, 'zhTW', '你會死在一千艘的船艦之下！', '你會死在一千艘的船艦之下！', 28153),
(158987, 'zhTW', '為喬倫而戰！', '為喬倫而戰！', 28153),
(158986, 'zhTW', '為了血喚號！', '為了血喚號！', 28153),
(158985, 'zhTW', '為了榮耀而死！', '為了榮耀而死！', 28153),
(158984, 'zhTW', '我要吃掉你的心臟！', '我要吃掉你的心臟！', 28153),
(158983, 'zhTW', '莫嚕咕嚕嘎咕…', '莫嚕咕嚕嘎咕…', 28153),
(158982, 'zhTW', '莫嚕咕莫嘎呼？', '莫嚕咕莫嘎呼？', 28153),
