(158980, 'zhTW', '咕嘎嚕…', '咕嘎嚕…', 28153),
(158979, 'zhTW', '姆嚕咕！', '姆嚕咕！', 28153),
(158978, 'zhTW', '嚕咕…姆嚕咕…', '嚕咕…姆嚕咕…', 28153),
(158977, 'zhTW', '姆嚕嚕莫咯囉！', '姆嚕嚕莫咯囉！', 28153),
(158976, 'zhTW', '莫嘎咕？姆咕！嚕咯！', '莫嘎咕？姆咕！嚕咯！', 28153),
(158975, 'zhTW', '嚕咕姆嘎莫囉嘎莫囉！', '嚕咕姆嘎莫囉嘎莫囉！', 28153),
(158974, 'zhTW', '', '啊，這太完美了！實在太感謝你了，$p，你人真好。拿去吧，請收下這些餅乾。', 28153),
