(158959, 'zhTW', '我們會繼續蔓延，直到你們的世界被恐懼和眼睛吞沒。', '我們會繼續蔓延，直到你們的世界被恐懼和眼睛吞沒。', 28153),
(158958, 'zhTW', '無光的深淵在召喚你。', '無光的深淵在召喚你。', 28153),
(158957, 'zhTW', '尖叫著逃進深淵吧！', '尖叫著逃進深淵吧！', 28153),
(158956, 'zhTW', '我們會把你們全部吞掉！', '我們會把你們全部吞掉！', 28153),
(158955, 'zhTW', '黑暗會吞噬你的肉體！', '黑暗會吞噬你的肉體！', 28153),
(158954, 'zhTW', '這是場船難…', '這是場船難…', 28153),
(158953, 'zhTW', '我一直以為…自己會死在海上…', '我一直以為…自己會死在海上…', 28153),
(158952, 'zhTW', '我不要…這樣死去…', '我不要…這樣死去…', 28153),
(158951, 'zhTW', '這全是…導航員的錯…', '這全是…導航員的錯…', 28153),
(158950, 'zhTW', '救我啊…你們這群懶蟲…', '救我啊…你們這群懶蟲…', 28153),
(158949, 'zhTW', '寧願死掉…也不要在這裡多待一刻…', '寧願死掉…也不要在這裡多待一刻…', 28153),
(158948, 'zhTW', '我們一開始…就不該來的…', '我們一開始…就不該來的…', 28153),
(158947, 'zhTW', '我的…隊員…爛死了…', '我的…隊員…爛死了…', 28153),
(158946, 'zhTW', '臭無賴，你們的船是我們的了！', '臭無賴，你們的船是我們的了！', 28153),
(158945, 'zhTW', '大家聽好，有寶藏自己送上門來，而且還會帶我們離開這裡！', '大家聽好，有寶藏自己送上門來，而且還會帶我們離開這裡！', 28153),
(158944, 'zhTW', '他們有船！殺了他們！', '他們有船！殺了他們！', 28153),
(158943, 'zhTW', '你一定會後悔來到這裡！', '你一定會後悔來到這裡！', 28153),
(158942, 'zhTW', '啊，我剛剛不該喝這麼多蘭姆酒的…', '啊，我剛剛不該喝這麼多蘭姆酒的…', 28153),
(158941, 'zhTW', '懶蟲，我們遭到攻擊了！都給我起來！', '懶蟲，我們遭到攻擊了！都給我起來！', 28153),
(158940, 'zhTW', '他們不是來救我們的，殺了他們！', '他們不是來救我們的，殺了他們！', 28153),
(158939, 'zhTW', '耶，兄弟們，我們要離開這裡了！攻擊他們！', '耶，兄弟們，我們要離開這裡了！攻擊他們！', 28153),
(158938, 'zhTW', '我將返回深海…很適合水手的死法…', '我將返回深海…很適合水手的死法…', 28153),
(158937, 'zhTW', '來人啊…在我死之前給我一杯蘭姆酒吧…', '來人啊…在我死之前給我一杯蘭姆酒吧…', 28153),
(158936, 'zhTW', '這裡…越來越暗…', '這裡…越來越暗…', 28153),
(158935, 'zhTW', '呃啊…那一招太卑鄙了…', '呃啊…那一招太卑鄙了…', 28153),
(158934, 'zhTW', '快去…船上…', '快去…船上…', 28153),
