(158932, 'zhTW', '你永遠也找不到…我的寶藏…', '你永遠也找不到…我的寶藏…', 28153),
(158931, 'zhTW', '啊…我的寶藏…', '啊…我的寶藏…', 28153),
(158930, 'zhTW', '快保護我，沒用的蠢蛋！', '快保護我，沒用的蠢蛋！', 28153),
(158929, 'zhTW', '快集合過來，你們這些骯髒的野狗，有人闖進來了！', '快集合過來，你們這些骯髒的野狗，有人闖進來了！', 28153),
(158928, 'zhTW', '你不應該來的，這裡是海盜的地盤！', '你不應該來的，這裡是海盜的地盤！', 28153),
(158927, 'zhTW', '喂，各位，有人闖進來啦！', '喂，各位，有人闖進來啦！', 28153),
(158926, 'zhTW', '燒殺擄掠，耶！', '燒殺擄掠，耶！', 28153),
(158925, 'zhTW', '你想被彎劍開膛破肚是吧！', '你想被彎劍開膛破肚是吧！', 28153),
(158924, 'zhTW', '你等著走跳板吧！', '你等著走跳板吧！', 28153),
(158923, 'zhTW', '喂！把入侵者全都趕出去！', '喂！把入侵者全都趕出去！', 28153),
(158922, 'zhTW', '沒有人能阻擋我們獵殺Onoho！', '', 28153),
(158921, 'zhTW', '大海把你送給我們，現在你走不了了…', '', 28153),
(158920, 'zhTW', '我們會繼續精進獵殺技術，然後等著大海的指引！', '', 28153),
(158919, 'zhTW', '海潮的起落已經預告了這場會面。', '', 28153),
(158918, 'zhTW', '你面對的是偉大的獵殺部族，還奢望著能活下來嗎？', '', 28153),
(158917, 'zhTW', '大海為我們帶來了新的肉和武器，我們感謝浪潮的恩賜！', '', 28153),
(158916, 'zhTW', '你的血肉和補給品會協助我們獵殺，我們感謝你！', '', 28153),
(158915, 'zhTW', '我們部族獵殺那隻巨獸已經好幾年了，你無法阻止我們的！', '', 28153),
(158914, 'zhTW', '沙灘早已…讓我看到我的命運…', '', 28153),
(158913, 'zhTW', '海潮…要把我帶走…', '', 28153),
(158912, 'zhTW', '這場獵殺…又取走一條命…', '', 28153),
(158911, 'zhTW', '你也是個…厲害的…獵人…', '', 28153),
(158910, 'zhTW', '喝啊…扎實的一擊…', '', 28153),
(158909, 'zhTW', '我們最後全都會被大海吞噬…', '', 28153),
(158908, 'zhTW', '獵殺少了我…還會繼續下去…', '', 28153),
(158907, 'zhTW', '我們…毫不後悔…', '', 28153),
(158906, 'zhTW', '看來有外來者被沖上岸了。', '', 28153),
(158905, 'zhTW', '我們感謝你的犧牲。', '', 28153),
(158904, 'zhTW', '奪走他們的補給品，我們今晚要設宴席！', '', 28153),
(158903, 'zhTW', '你敢挑戰我們的部族？', '', 28153),
(158902, 'zhTW', '你的血提供了獵殺的動力。', '', 28153),
(158901, 'zhTW', '你的屍體會為我們提供養分，感謝你。', '', 28153),
(158900, 'zhTW', '大海為我們帶來新的補給品…', '', 28153),
(158899, 'zhTW', '浪濤告訴我們你會來。', '', 28153),
(158898, 'zhTW', '', '我好愛棲息在這裡的有趣動物。兔子、鳥兒和螃蟹，各種生物都有。我訓練了幾個寵物來當我的夥伴，你看到我旁邊這個巨大的屍體了嗎？我的寵物只花4分鐘就解決了牠。真是飢餓的小傢伙們。想不想親眼看牠們戰鬥？', 28153),
(158897, 'zhTW', '', '幫我保護米若，好嗎？\n\n她對沙漠裡真正的危險一無所知。我不想見到她被沙漠吞噬…', 28153),
(158896, 'zhTW', '', '你的朋友看起來好多了。很高興基羅和米若能幫上忙。', 28153),
(158895, 'zhTW', '', '$n，歡迎光臨我們暫時的家。\n\n商隊隨時都準備出發，以防塞斯拉克發現我們的藏身處。', 28153),
(158894, 'zhTW', '來看看你是否能引導樂樂穿過海藻，到達安全的地點。', '', 28153),
(158893, 'zhTW', '', '我們一定會的。來，拿幾個麵粉炸彈。帶著他們的時候麻煩小心點。', 28153),
(158892, 'zhTW', '想不想交易熊肉？', '', 28153),
(158891, 'zhTW', '夸風跑走了！', '', 28153),
(158890, 'zhTW', '夸風把頭顱拿在你剛好拿不到的地方，尾巴頑皮地掃動著。', '', 28153),
(158889, 'zhTW', '你沒那麼…厲害。', '', 28153),
(158888, 'zhTW', '我會拿走任何我要的東西！', '', 28153),
(158887, 'zhTW', '我喜歡你的裝備…想做個交易嗎？', '', 28153),
(158886, 'zhTW', '我將返回…海中…', '', 28153),
(158885, 'zhTW', '我的部族今天…不會滅亡…', '', 28153),
(158884, 'zhTW', '咕哇…怎麼會…？', '', 28153),
(158883, 'zhTW', '我將回到…海潮的懷抱…', '', 28153),
(158882, 'zhTW', '寶藏…是我的…', '', 28153),
(158881, 'zhTW', '嘶…你會付出代價的…', '', 28153),
(158880, 'zhTW', '嘶…小偷…', '', 28153),
(158879, 'zhTW', '嘎…我的血…', '', 28153),
(158878, 'zhTW', '嘶！殺了他們！守住寶藏！', '', 28153),
(158877, 'zhTW', '這些寶石讓我的部族變強了，我們不會聽從你們的！', '', 28153),
(158876, 'zhTW', '我們會享用你們的血肉，大啃你們的骨頭！', '', 28153),
(158875, 'zhTW', '你們竟敢挑戰偉大的戰士？', '', 28153),
(158874, 'zhTW', '我保護這個部族！你們死定了！', '', 28153),
(158873, 'zhTW', '有入侵者！我的手下，快殺了他們！', '', 28153),
(158872, 'zhTW', '寶藏歸我部族所有，你們這些小偷！', '', 28153),
(158871, 'zhTW', '我的部族很強，你們阻止不了的！', '', 28153),
(158870, 'zhTW', '我去幫你找找看。', '我去幫你找找看。', 28153),
(158869, 'zhTW', '你們的寶藏是我們的！', '', 28153),
(158868, 'zhTW', '我有冰淇淋要請你吃！', '我有冰淇淋要請你吃！', 28153),
(158867, 'zhTW', '我要把你開膛破肚！', '', 28153),
(158866, 'zhTW', '保護部族！', '', 28153),
(158865, 'zhTW', '撕裂他們，把他們的寶藏拿來給我！', '', 28153),
(158864, 'zhTW', '嘶！我們受到攻擊！', '', 28153),
(158863, 'zhTW', '溫血動物！', '', 28153),
(158862, 'zhTW', '殺了他們！拿走他們的東西！', '', 28153),
(158861, 'zhTW', '嘶！殺了你們！', '', 28153),
(158860, 'zhTW', '孩子們，又有食物送上門了！', '孩子們，又有食物送上門了！', 28153),
(158859, 'zhTW', '沒問題。你需要我幫什麼忙？', '沒問題。你需要我幫什麼忙？', 28153),
(158858, 'zhTW', '喀喀喀，又有獵物掉進我們的洞穴，你的旅程結束了…', '喀喀喀，又有獵物掉進我們的洞穴，你的旅程結束了…', 28153),
(158857, 'zhTW', '美味的肉自己送上門來，太美妙了。', '美味的肉自己送上門來，太美妙了。', 28153),
(158856, 'zhTW', '你的血會成為幼蛛的乳汁，你的肉體會滋養蛛后，而我，將吸食你的大腦！', '你的血會成為幼蛛的乳汁，你的肉體會滋養蛛后，而我，將吸食你的大腦！', 28153),
(158855, 'zhTW', '你永遠也找不到卵的，我們蛛群永生不滅！', '你永遠也找不到卵的，我們蛛群永生不滅！', 28153),
(158854, 'zhTW', '別再掙扎了，獵物，你只會延長你的痛苦！', '別再掙扎了，獵物，你只會延長你的痛苦！', 28153),
(158853, 'zhTW', '又有一名受害者自投羅網，喀嘶！', '又有一名受害者自投羅網，喀嘶！', 28153),
(158852, 'zhTW', '我們就算只剩最後一口氣，也會保護幼蛛！', '我們就算只剩最後一口氣，也會保護幼蛛！', 28153),
(158851, 'zhTW', '小心…那些闖入者…', '小心…那些闖入者…', 28153),
(158850, 'zhTW', '你找不到…那些…卵的…', '你找不到…那些…卵的…', 28153),
(158849, 'zhTW', '你無法找到…我們全部…', '你無法找到…我們全部…', 28153),
(158848, 'zhTW', '都走到了這個地步…我們才不會被你消滅…', '都走到了這個地步…我們才不會被你消滅…', 28153),
(158847, 'zhTW', '我的身體會成為幼蛛的養分…', '我的身體會成為幼蛛的養分…', 28153),
(158846, 'zhTW', '喀嘶…痛…', '喀嘶…痛…', 28153),
(158845, 'zhTW', '保護…幼蛛…', '保護…幼蛛…', 28153),
(158844, 'zhTW', '喀嘶…', '喀嘶…', 28153),
(158843, 'zhTW', '幼蛛會吞食你們的血肉！', '幼蛛會吞食你們的血肉！', 28153),
(158842, 'zhTW', '喀喀喀…進來我的蛛網！', '喀喀喀…進來我的蛛網！', 28153),
(158841, 'zhTW', '有人入侵！', '有人入侵！', 28153),
(158840, 'zhTW', '我們會保護幼蛛！', '我們會保護幼蛛！', 28153),
(158839, 'zhTW', '嘶…新鮮的血液…', '嘶…新鮮的血液…', 28153),
(158838, 'zhTW', '裂物來了…', '裂物來了…', 28153),
(158837, 'zhTW', '別來打擾我們的蛛網！', '別來打擾我們的蛛網！', 28153),
(158836, 'zhTW', '喀…入侵者…', '喀…入侵者…', 28153),
(158835, 'zhTW', '', '嗯，我最近常常想吃甜的。我真的很想吃美味的草莓冰淇淋！\n\n如果你能幫我找一點回來，我會非常感激你的。方便的話，請幫我多帶一些，這樣我以後也會有得吃。希望這不會太麻煩你！', 28153),
(158834, 'zhTW', '', '親愛的，你看起來好瘦。最近有好好吃飯嗎？', 28153),
(158833, 'zhTW', '', '噢，你跑這麼大段路就是想來見人家嗎？', 28153),
(158832, 'zhTW', '', '親愛的你好啊。很高興見到你。', 28153),
(158831, 'zhTW', '呃啊！咕哇！', '', 28153),
(158830, 'zhTW', '你…不…', '', 28153),
(158829, 'zhTW', '啊啊…', '', 28153),
(158828, 'zhTW', '咕啊…', '', 28153),
(158827, 'zhTW', '你…好臭…', '', 28153),
(158826, 'zhTW', '要…趕快逃…', '', 28153),
(158825, 'zhTW', '嗚咕…', '', 28153),
(158824, 'zhTW', '呃啊…咕哇…', '', 28153),
(158823, 'zhTW', '新的氣味，不好，喝啊！', '', 28153),
(158822, 'zhTW', '啊，我聞到肉了！', '', 28153),
(158821, 'zhTW', '嘎啊！你送上門來！', '', 28153),
(158820, 'zhTW', '咬你，吃你的肉！', '', 28153),
(158819, 'zhTW', '死吧！喝啊！', '', 28153),
(158818, 'zhTW', '喝啊…你…我要殺！', '', 28153),
(158817, 'zhTW', '嘎啊！', '', 28153),
(158816, 'zhTW', '喝！', '', 28153),
(158815, 'zhTW', '這片荒野存在的時間比你還久，而且會把你逐出這裡。', '這片荒野存在的時間比你還久，而且會把你逐出這裡。', 28153),
(158814, 'zhTW', '發光的寶石是大自然賜給我們的禮物，不會讓你們拿到的！', '發光的寶石是大自然賜給我們的禮物，不會讓你們拿到的！', 28153),
(158813, 'zhTW', '入侵者，今天你會進入大自然的循環，我們會因你的屍體而茁壯。', '入侵者，今天你會進入大自然的循環，我們會因你的屍體而茁壯。', 28153),
(158812, 'zhTW', '我會中止你這場侵略，不讓你繼續腐化這片土地。', '我會中止你這場侵略，不讓你繼續腐化這片土地。', 28153),
(158811, 'zhTW', '你的屍體將會滋養這片遭你踐踏過的土地。', '你的屍體將會滋養這片遭你踐踏過的土地。', 28153),
(158810, 'zhTW', '你們這種人失去了平衡，無法持續下去。我不得不插手干涉。', '你們這種人失去了平衡，無法持續下去。我不得不插手干涉。', 28153),
(158809, 'zhTW', '我必須殺了你，才能修補被你打破的平衡。', '我必須殺了你，才能修補被你打破的平衡。', 28153),
(158808, 'zhTW', '我們的使命是保護這片林地和其中的野獸，我們不歡迎你！', '我們的使命是保護這片林地和其中的野獸，我們不歡迎你！', 28153),
(158807, 'zhTW', '你們這些傢伙…是一種疫病…', '你們這些傢伙…是一種疫病…', 28153),
(158806, 'zhTW', '你汙染了…我們的土地…', '你汙染了…我們的土地…', 28153),
(158805, 'zhTW', '你殺不死…大自然的…', '你殺不死…大自然的…', 28153),
(158804, 'zhTW', '我們會…重生…', '我們會…重生…', 28153),
