(158798, 'zhTW', '這些發光的寶石，是獻給荒野的禮物！', '這些發光的寶石，是獻給荒野的禮物！', 28153),
(158797, 'zhTW', '我們一定要保護平衡！', '我們一定要保護平衡！', 28153),
(158796, 'zhTW', '不准污染我們的林地！', '不准污染我們的林地！', 28153),
(158795, 'zhTW', '我回應大自然的召喚！', '我回應大自然的召喚！', 28153),
(158794, 'zhTW', '入侵者，不准你褻瀆這片土地！', '入侵者，不准你褻瀆這片土地！', 28153),
(158793, 'zhTW', '大自然會指引我的怒氣！', '大自然會指引我的怒氣！', 28153),
(158792, 'zhTW', '我一定要保護荒野！', '我一定要保護荒野！', 28153),
