(158786, 'zhTW', '我的怒氣…消散了…', '我的怒氣…消散了…', 28153),
(158785, 'zhTW', '你…為什麼…', '你…為什麼…', 28153),
(158784, 'zhTW', '一定要…逃走…', '一定要…逃走…', 28153),
(158783, 'zhTW', '我現在…看得更清楚了…', '我現在…看得更清楚了…', 28153),
