(158776, 'zhTW', '殺了…你…', '殺了…你…', 28153),
(158775, 'zhTW', '吼…', '吼…', 28153),
(158774, 'zhTW', '啊！', '啊！', 28153),
(158773, 'zhTW', '看他現在長多大了！就和他父親一樣。', '', 28153),
(158772, 'zhTW', '詛咒你…', '詛咒你…', 28153),
(158771, 'zhTW', '我看到…先祖了…', '我看到…先祖了…', 28153),
(158770, 'zhTW', '我看到靈魂…來迎接我了…', '我看到靈魂…來迎接我了…', 28153),
(158769, 'zhTW', '你贏得…一點也不光榮…', '你贏得…一點也不光榮…', 28153),
(158768, 'zhTW', '呃…你擊敗我了…', '呃…你擊敗我了…', 28153),
(158767, 'zhTW', '你無法殺光…我們全部…', '你無法殺光…我們全部…', 28153),
