(158765, 'zhTW', '我將加入靈魂的行列…', '我將加入靈魂的行列…', 28153),
(158764, 'zhTW', '我會用你的骨頭施展妖術，詛咒你全家！', '我會用你的骨頭施展妖術，詛咒你全家！', 28153),
(158763, 'zhTW', '你這個低下的外來者，你不屬於這裡！', '你這個低下的外來者，你不屬於這裡！', 28153),
(158762, 'zhTW', '', '我們孩子的孩子好像昨天才剛出生，現在看看他！', 28153),
(158761, 'zhTW', '啊，你是誰？這裡不歡迎你，知道嗎？', '啊，你是誰？這裡不歡迎你，知道嗎？', 28153),
(158760, 'zhTW', '我們就來看看你有多厲害…', '我們就來看看你有多厲害…', 28153),
(158759, 'zhTW', '我們拿到了寶石，我的部族是最強的了！', '我們拿到了寶石，我的部族是最強的了！', 28153),
(158758, 'zhTW', '我沒那麼好對付，呵。', '我沒那麼好對付，呵。', 28153),
(158757, 'zhTW', '島是我的，寶石也是我的，你在這裡只是找死。', '島是我的，寶石也是我的，你在這裡只是找死。', 28153),
(158756, 'zhTW', '這裡是我們發現的，闖入者，我們不會讓你奪走的！', '這裡是我們發現的，闖入者，我們不會讓你奪走的！', 28153),
(158755, 'zhTW', '這是我們的島嶼！', '這是我們的島嶼！', 28153),
(158754, 'zhTW', '喂，你在這座島上做什麼？', '喂，你在這座島上做什麼？', 28153),
(158753, 'zhTW', '夥計，我們遭到攻擊！快過來！', '夥計，我們遭到攻擊！快過來！', 28153),
(158752, 'zhTW', '把他們千刀萬剮！', '把他們千刀萬剮！', 28153),
