INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158748, 'zhTW', '我們會挖你的腸，喝你的血！', '我們會挖你的腸，喝你的血！', 28153),
(158747, 'zhTW', '吼！我光榮戰死！', '', 28153),
(158746, 'zhTW', '你們…才是入侵者…我們沒有錯…', '', 28153),
(158745, 'zhTW', '寶石…也救不了我們…', '', 28153),
(158744, 'zhTW', '我們會帶著更多的援手…回來的…', '', 28153),
(158743, 'zhTW', '星星…騙了我們…', '', 28153),
(158742, 'zhTW', '我聽到了…先祖的召喚…', '', 28153),
(158741, 'zhTW', '靈魂來迎接我了…', '', 28153),
(158740, 'zhTW', '我將加入…先祖的行列…', '', 28153),
(158739, 'zhTW', '星星會指引我的拳頭，未來就用你的血來寫！', '', 28153),
(158738, 'zhTW', '風告訴我，今天就是你的死期。', '', 28153),
(158737, 'zhTW', '靈魂賦予我不滅烈焰的力量！', '', 28153),
(158736, 'zhTW', '弱者，你挑起了一場你打不贏的仗！', '', 28153),
(158735, 'zhTW', '笨蛋，這座島的寶藏是我們的。', '', 28153),
(158734, 'zhTW', '先祖賜我力量和智慧！', '', 28153),
(158733, 'zhTW', '蠢蛋，我要在我的頭角上塗滿你的血！', '', 28153),
(158732, 'zhTW', '我會保護我的部族，外來者！', '', 28153),
(158731, 'zhTW', '戰士，協助我！', '', 28153),
(158730, 'zhTW', '整隊！我們遭到攻擊了！', '', 28153),
(158729, 'zhTW', '這是我們的島嶼，你不該來！', '', 28153),
(158728, 'zhTW', '發光的寶石是我們的，你沒有機會的！', '', 28153),
(158727, 'zhTW', '外來者，我們不會讓你奪走這裡！', '', 28153),
(158726, 'zhTW', '有人入侵！把他們趕走！', '', 28153),
(158725, 'zhTW', '靈魂指引我的武器！', '', 28153),
(158724, 'zhTW', '為了先祖！', '', 28153),
(158723, 'zhTW', '那招…好痛…', '', 28153),
(158722, 'zhTW', '你為什麼…要來…？', '', 28153),
(158721, 'zhTW', '啊！正中腹部…', '', 28153),
(158720, 'zhTW', '你…是小偷…', '', 28153),
(158719, 'zhTW', '不！我的寶石…', '', 28153),
(158718, 'zhTW', '你為什麼…要這樣做？', '', 28153),
(158717, 'zhTW', '噢…不好了…', '', 28153),
(158716, 'zhTW', '為什麼變得好黑？', '', 28153),
(158715, 'zhTW', '', '有些人認為約定沒什麼大不了。只是信口開河的權宜之計。未來無法確定，眼前的利益先到手再說。\n\n但是記住這一點，伯昂撒姆第最後一定會討回所有公道。', 28153),
(158714, 'zhTW', '各位巨魔，大開殺戒吧！', '', 28153),
(158713, 'zhTW', '不！我的寶石！不是你的！我需要寶石！', '', 28153),
(158712, 'zhTW', '闖入者，寶石讓我們變強。我們比你強了！', '', 28153),
(158711, 'zhTW', '解決你之後，我要摘下你的頭當戰利品！', '', 28153),
(158710, 'zhTW', '殺了他們！打斷他們的背脊！', '', 28153),
(158709, 'zhTW', '小廢物，這座島是我的。我的！', '', 28153),
(158708, 'zhTW', '我要打死你，然後喝你的血！', '', 28153),
(158707, 'zhTW', '我要把你砍成好幾段！吼！', '', 28153),
(158706, 'zhTW', '這我的寶石！吼！', '', 28153),
(158705, 'zhTW', '別拿走我們的東西！', '', 28153),
(158704, 'zhTW', '抓住他們！', '', 28153),
(158703, 'zhTW', '你不能拿寶石！', '', 28153),
(158702, 'zhTW', '這是我麼島！你快走！', '', 28153),
(158701, 'zhTW', '殺死入侵者！', '', 28153),
(158700, 'zhTW', '我打，我砍，我殺！', '', 28153),
(158699, 'zhTW', '我打爛你！', '', 28153),
(158698, 'zhTW', '或許這一次只要我答應成為更好的人，別像上次一樣…一切就會沒事！', '或許這一次只要我答應成為更好的人，別像上次一樣…一切就會沒事！', 28153),
(158697, 'zhTW', '你認為伯昂撒姆第會要我做什麼？', '你認為伯昂撒姆第會要我做什麼？', 28153),
(158696, 'zhTW', '我該怎麼做…我該怎麼做…一定有辦法可以脫身的！', '我該怎麼做…我該怎麼做…一定有辦法可以脫身的！', 28153),
(158695, 'zhTW', '只要我答應伯昂撒姆第的要求，一切就會恢復正常，對吧？', '只要我答應伯昂撒姆第的要求，一切就會恢復正常，對吧？', 28153),
(158694, 'zhTW', '恨哪！我恨這一切！', '恨哪！我恨這一切！', 28153),
(158693, 'zhTW', '這太可惡了！難道他們不知道我是誰嗎？', '這太可惡了！難道他們不知道我是誰嗎？', 28153),
(158692, 'zhTW', '就算會毀了我，我也要宰了讓我變成這樣的傢伙！', '就算會毀了我，我也要宰了讓我變成這樣的傢伙！', 28153),
(158691, 'zhTW', '為什麼會這樣？不公平！', '為什麼會這樣？不公平！', 28153),
(158690, 'zhTW', '情況不會變好的，你說服不了我的。', '情況不會變好的，你說服不了我的。', 28153),
(158689, 'zhTW', '我原本很有前途的，但是你看看…我現在什麼都不是了。', '我原本很有前途的，但是你看看…我現在什麼都不是了。', 28153),
(158688, 'zhTW', '我再也無法感受陽光了。', '我再也無法感受陽光了。', 28153),
(158687, 'zhTW', '要是能多給我幾天…我就可以完成好多事。', '要是能多給我幾天…我就可以完成好多事。', 28153),
(158686, 'zhTW', '死了？你錯了，我只是休息一下而已。', '死了？你錯了，我只是休息一下而已。', 28153),
(158685, 'zhTW', '你是誰？無所謂，反正也不重要…', '你是誰？無所謂，反正也不重要…', 28153),
(158684, 'zhTW', '只要我不去看，那就是沒有發生。就這麼簡單。', '只要我不去看，那就是沒有發生。就這麼簡單。', 28153),
(158683, 'zhTW', '繼續吧…繼續下去…最後總有一個對的…', '繼續吧…繼續下去…最後總有一個對的…', 28153),
(158682, 'zhTW', '竟敢踏進我的堡壘。不可原諒！', '', 28153),
(158681, 'zhTW', '你太弱了。和我在真正的戰鬥裡一決高下吧！', '', 28153),
(158680, 'zhTW', '你以為你那破爛的機器對付得了我嗎！？', '', 28153),
(158679, 'zhTW', '喂，出現挑戰者了！放馬過來！', '', 28153),
(158678, 'zhTW', '可是…我太美了，不可以死…', '', 28153),
(158677, 'zhTW', '', '我要把你…碎屍萬段…', 28153),
(158676, 'zhTW', '', '我要把你碎屍萬段！', 28153),
(158675, 'zhTW', '把我葬在海裡…', '', 28153),
(158674, 'zhTW', '我要把你浸龍骨！', '', 28153),
(158673, 'zhTW', '噁，這傢伙。我不知道是他過量的護髮用品比較糟…還是他的爛詩比較糟。總之，李德是個多情的人，也很會打架。', '', 28153),
(158672, 'zhTW', '在貝克特自己的腦海裡，他就是史詩傳說。', '', 28153),
(158671, 'zhTW', '露娜就是有點…鋒芒畢露。', '', 28153),
(158670, 'zhTW', '呵…死亡與納稅，是絕對逃不了的…', '', 28153),
(158669, 'zhTW', '現在是什麼情況？看來有筆帳要好好算算！', '', 28153),
(158668, 'zhTW', '', '希望一切都還來得及。加緊腳步，快點找到我女兒。', 28153),
(158666, 'zhTW', '', '命運絕地是斯陀頌恩海岸附近的島嶼。犯了重罪的罪犯和叛徒都被送到那裡，永遠不能回來。', 28153),
(158665, 'zhTW', '', '勇士！你有什麼發現嗎？', 28153),
(158661, 'zhTW', '我要離開這裡！$p，謝謝你幫忙！', '', 28153),
(158660, 'zhTW', '夸風發出一聲刺耳的尖嘯，興奮地甩動尾巴。', '', 28153),
(158659, 'zhTW', '夸風把頭顱放回你手中。', '', 28153),
(158658, 'zhTW', '夸風把頭顱扔在腳邊，朝著你熱烈嘶叫。', '', 28153),
(158657, 'zhTW', '', '我們輸了這場仗。泰達希爾也將淪陷。', 28153),
(158656, 'zhTW', '海潮會把你們整個吞了！', '', 28153),
(158655, 'zhTW', '勇士，我們走吧。我們必須繼續追隨大酋長…邁向勝利。', '', 28153),
(158654, 'zhTW', '', '成功了。大家快上來！', 28153),
(158653, 'zhTW', '你也有選擇。帶著他回到達納蘇斯，與家園一起滅亡…或是帶他逃走、一起活下去。', '', 28153),
(158652, 'zhTW', '', '因為你放過瑪法里恩，我願意讓你選擇。', 28153),
(158651, 'zhTW', '', '別怕。', 28153),
(158650, 'zhTW', '不是無故屠殺。這一切都是為了讓部落得以延續。', '', 28153),
(158649, 'zhTW', '', '不只那一擊，這整場戰爭都是可恥的。你竟敢無故輕賤這麼多生命！', 28153),
(158648, 'zhTW', '剛剛的攻擊太卑劣了。我沒有資格殺死他。', '', 28153),
(158647, 'zhTW', '', '獸人，你沒有殺他。為什麼？', 28153),
(158646, 'zhTW', '', '瑪法里恩！不要！', 28153),
(158645, 'zhTW', '你們…部落…已經淪為死亡的奴僕…以後的每一天…你都會後悔今日的作為…', '', 28153),
(158642, 'zhTW', '', '治療你的傷口，舒展你的筋骨。你在這裡很安全。', 28153),
(158641, 'zhTW', '我會死是因為惹上錯的野獸。你知道的，就是那隻。', '我會死是因為惹上錯的野獸。你知道的，就是那隻。', 28153),
(158640, 'zhTW', '我和你一樣困惑啊，夥計。', '我和你一樣困惑啊，夥計。', 28153),
(158639, 'zhTW', '哈瓦里紅番椒會讓我辣到受不了。', '哈瓦里紅番椒會讓我辣到受不了。', 28153),
(158638, 'zhTW', '我是在托卡納塔奔跑的時候死的。有機會的話我還想再這麼做！', '我是在托卡納塔奔跑的時候死的。有機會的話我還想再這麼做！', 28153),
(158637, 'zhTW', '你會把你的肉體留在門口吧？', '你會把你的肉體留在門口吧？', 28153),
(158636, 'zhTW', '我是在佐卡洛散步時被雷劈中。', '我是在佐卡洛散步時被雷劈中。', 28153),
(158635, 'zhTW', '我會死是因為從金字塔上摔下來，而我記不起來我是怎麼來到這裡的了。', '我會死是因為從金字塔上摔下來，而我記不起來我是怎麼來到這裡的了。', 28153),
(158634, 'zhTW', '全打扮好了，卻沒地方可去。', '全打扮好了，卻沒地方可去。', 28153),
(158633, 'zhTW', '要精準計算出在波拉勒斯開啟傳送門的正確位置很不簡單，但我願意挑戰！告訴我有沒有成功，好嗎？', '', 28153),
(158632, 'zhTW', '遵命，納薩諾斯。', '', 28153),
(158631, 'zhTW', '澤靈，你跟$n一起去波拉勒斯。歐庫雷斯開了傳送門在等著。', '', 28153),
(158630, 'zhTW', '你好，英雄，我們必須談談。', '', 28153),
(158629, 'zhTW', '這是這裡最好的座位…等我起來你才能坐。', '', 28153),
(158628, 'zhTW', '', '$p？呸，我從來沒聽過你這傢伙。', 28153),
(158627, 'zhTW', '等你準備好下船，在外頭等著的荷巴爾特會協助你們。', '', 28153),
(158626, 'zhTW', '別說我沒警告過你。', '別說我沒警告過你。', 28153),
(158625, 'zhTW', '不要過來！這是為了你好。', '不要過來！這是為了你好。', 28153),
(158624, 'zhTW', '夸風害怕地發抖。', '', 28153),
(158623, 'zhTW', '局勢現在對我們有利了，你說是不是，$n？', '', 28153),
(158622, 'zhTW', '我在地平線上看到偉大的事業，你我皆有份。', '', 28153),
(158621, 'zhTW', '你不能把我丟在這裡。我這把老古頭不適合在礦坑裡工作。', '你不能把我丟在這裡。我這把老古頭不適合在礦坑裡工作。', 28153),
(158620, 'zhTW', '我猜得出發酵階段大概是哪裡出錯。', '', 28153),
(158619, 'zhTW', '所以，這個看不見的汙染或許在一開始對降低水量的過程造成了影響。', '', 28153),
(158618, 'zhTW', '沒問題。', '', 28153),
(158617, 'zhTW', '能幫得上忙就好。', '', 28153),
(158616, 'zhTW', '我要去工作了。', '', 28153),
(158615, 'zhTW', '好啊，我幫你。', '', 28153),
(158614, 'zhTW', '我大概可以幫你。', '', 28153),
(158612, 'zhTW', '', '勇士，看看你身邊，這些樹有眼睛呢。我們幫它們闔上眼睛吧。', 28153),
(158611, 'zhTW', '我們得先全力穩定關鍵的混合物。', '', 28153),
(158610, 'zhTW', '喔喔喔！這的確可以解釋！「鍊金術第一定律：要得到有用的結果，就必須提供可等價代換的物質。」', '', 28153),
(158609, 'zhTW', '我們動手吧！', '我們動手吧！', 28153),
(158608, 'zhTW', '有意思…精準控制加熱程度是成敗的關鍵。', '', 28153),
(158607, 'zhTW', '啊！我想我知道為什麼催化劑會沒效了。', '', 28153),
(158606, 'zhTW', '奇怪…我們不可能會料到這種狀況。', '', 28153),
(158605, 'zhTW', '嗯…這倒是挺有趣的。', '', 28153),
(158604, 'zhTW', '我們有朋友被困在外頭。要不要去幫忙？', '', 28153),
(158603, 'zhTW', '喂！有人從我們這邊偷走一堆東西！一定要討回來！快點！最好連本帶利討回來。', '', 28153),
(158602, 'zhTW', '哎呀，到處都是受傷的人。我們必須幫幫這些人！', '', 28153),
(158601, 'zhTW', '有沒有潛行技術高超的人？有工作要交給你！', '', 28153),
(158600, 'zhTW', '如果你在外頭找到戰鬥機動車的零件，讓我修修看，修好就借你開。', '', 28153),
(158599, 'zhTW', '我看到一個欠扁的大傢伙，用凱贊風格去海扁他一頓吧。', '', 28153),
(158598, 'zhTW', '哇，好大隻。走吧，我們去把牠殺了！', '', 28153),
(158597, 'zhTW', '有聯盟部隊被俘虜了。你想不想執行救人任務？', '', 28153),
(158596, 'zhTW', '敵軍奪走了重要物資。我們就用那些小偷的性命，來為聯盟伸張正義怎樣？', '', 28153),
(158595, 'zhTW', '戰場上士兵受傷了，有治療人員嗎？', '', 28153),
(158594, 'zhTW', '是的，孩子，伊露恩眷顧他們。她賜予德魯伊召喚颶風的力量，讓他們乘風歸來。', '', 28153),
(158593, 'zhTW', '', '迷霧之海也在幫助他們？', 28153),
(158592, 'zhTW', '送我回港口。', '送我回港口。', 28153),
(158591, 'zhTW', '送我到小型船艦上。', '送我到小型船艦上。', 28153),
(158590, 'zhTW', '我需要自願者來完成這個任務。最好擅長潛伏，還要會做些見不得人的勾當。', '', 28153),
(158589, 'zhTW', '我們正打算回收敵人的戰爭機械。記得把能用的零件帶回來給我。', '', 28153),
(158588, 'zhTW', '嘿，狩獵目標自己出現了。', '', 28153),
(158587, 'zhTW', '有龐大又凶惡的野生生物闖進我們的領域。大家來狩獵吧！', '', 28153),
(158586, 'zhTW', '想跟我的小朋友打聲招呼嗎？', '', 28153),
(158585, 'zhTW', '老兄，你還真是個討厭的傢伙。', '', 28153),
(158584, 'zhTW', '喂，別鬧了。', '', 28153),
(158583, 'zhTW', '要平安回來啊，聽到沒？', '', 28153),
(158582, 'zhTW', '眼睛睜大點。', '', 28153),
(158581, 'zhTW', '自己小心。', '', 28153),
(158580, 'zhTW', '有啥新鮮的？', '', 28153),
(158579, 'zhTW', '你好嗎？', '', 28153),
(158578, 'zhTW', '不錯嘛。', '', 28153),
(158577, 'zhTW', '以聖光之名，我需要再來一杯。', '', 28153),
(158576, 'zhTW', '就算薪水再高都不值得忍受這些。', '', 28153),
(158575, 'zhTW', '好，好…', '', 28153),
(158574, 'zhTW', '一路好走。', '', 28153),
(158573, 'zhTW', '解散。', '', 28153),
(158572, 'zhTW', '隨時注意敵軍動向。', '', 28153),
(158571, 'zhTW', '什麼？', '', 28153),
(158570, 'zhTW', '我很專心地在聽你說。', '', 28153),
(158569, 'zhTW', '聯盟萬歲。', '', 28153),
(158568, 'zhTW', '', '不…不可能的。', 28153),
(158565, 'zhTW', '', '你可以幫我測試我力量的界限！', 28153),
(158564, 'zhTW', '', '有人說我的魔法很殘忍，但我只不過是想探索一切的可能。', 28153),
(158563, 'zhTW', '定身', '定身', 28153),
(158562, 'zhTW', '米雅…米雅！醒醒啊，我的皇后…我的摯愛！', '', 28153),
(158561, 'zhTW', '願伊露恩的光芒照耀你們。', '', 28153),
(158560, 'zhTW', '那個女妖殺了我的兒子，奪走我的王國。我絕對不會讓她殺害我摯愛的妻子！', '', 28153),
(158559, 'zhTW', '', '他們…不會走的…', 28153),
(158558, 'zhTW', '阿斯塔利，你已經盡力了！快命令所有祭司跟我們一起撤退！', '', 28153),
(158557, 'zhTW', '不！我會救你們出去！', '', 28153),
(158555, 'zhTW', '', '世界樹…他們在燒那棵樹！孩子…救救孩子。不用…管我。', 28153),
(158554, 'zhTW', '你不能留在這裡！我們快從傳送門逃走！', '', 28153),
(158553, 'zhTW', '', '阿斯塔利，沒時間了，我們必須在城市燒成灰燼之前趕快撤離！', 28153),
(158551, 'zhTW', '', '好好送他上路。如果你想要享受一下勝利也無妨。拿下他的頭之後到世界之樹跟我會合。', 28153),
(158550, 'zhTW', '', '我本來就會贏的，他只是在浪費我的時間。', 28153),
(158549, 'zhTW', '我根本不該插手的。', '', 28153),
(158548, 'zhTW', '', '沒什麼好後悔的，做得好。', 28153),
(158547, 'zhTW', '這個行為很可恥。我…很抱歉。', '', 28153),
(158546, 'zhTW', '呃啊！薩魯…法爾？！', '', 28153),
(158545, 'zhTW', '大酋長獨自對抗怒風！我必須…', '', 28153),
(158544, 'zhTW', '北邊？怎麼可能…可惡！他們一定是翻越了費伍德森林的山地！', '', 28153),
(158543, 'zhTW', '勇士、德拉茵…你們先去奧伯丁攔截部落。北邊就交給我吧。', '', 28153),
(158542, 'zhTW', '部落隨時都可能突破防線，到時候我們會腹背受敵。', '', 28153),
(158541, 'zhTW', '幽光…迷失方向了！幽光防線快失效了！', '', 28153),
(158540, 'zhTW', '', '聽到了嗎…怎麼可能…？尊師！部落從北邊過來了！', 28153),
(158539, 'zhTW', '', '機會來了。世界之樹會落入我們手中！去找薩魯法爾，讓我們結束這一切吧。', 28153),
(158537, 'zhTW', '', '英雄，看看你身邊！很漂亮吧。幽光漸漸散開了。防線開始一段一段的瓦解了。', 28153),
(158536, 'zhTW', '', '薩魯法爾！你總算來了。', 28153),
(158535, 'zhTW', '為了部落！', '', 28153),
(158534, 'zhTW', '', '小烏鴉，你想飛去哪裡呢？', 28153),
(158533, 'zhTW', '', '啊！我的眼睛！好痛！', 28153),
(158532, 'zhTW', '你這個女妖，給我滾！', '', 28153),
(158531, 'zhTW', '', '誰想得到你居然會出面保護你的寶貝樹木呢？', 28153),
(158530, 'zhTW', '', '瑪法里恩。你來的正是時候…', 28153),
(158529, 'zhTW', '希瓦娜斯！你的惡行玷汙了這個神聖之地！Andu-falah-dor！', '', 28153),
(158528, 'zhTW', '', '絕對不可以給他們任何喘息的機會。畢竟這是戰爭。', 28153),
(158527, 'zhTW', '', '在那之前，我們應該盡量對卡多雷施壓。', 28153),
(158526, 'zhTW', '', '在等候薩魯法爾的消息時，我會繼續帶領士兵向前推進。', 28153),
(158525, 'zhTW', '', '我們必須專心完成目標。', 28153),
(158524, 'zhTW', '', '急彎河的惡戰僵持不下，瑪法里恩也心知肚明。', 28153),
(158523, 'zhTW', '', '部落的勇士啊，我需要你們立即趕到急彎河！這是我們獲勝的機會！', 28153),
(158522, 'zhTW', '', '…我該去獵殺某隻烏鴉了。', 28153),
(158521, 'zhTW', '', '趕快完成這裡的工作。只要手上拿滿艾澤萊晶岩，就趕快交給工程師。', 28153),
(158520, 'zhTW', '', '那艘船一定是達納蘇斯來的…這表示…', 28153),
(158519, 'zhTW', '', '勇士，小心…聯盟似乎比我們提早一步。', 28153),
(158518, 'zhTW', '', '艾澤萊晶岩... 只要能掌握這個東西，就能消滅阻礙部落的所有敵人。', 28153),
(158517, 'zhTW', '', '工兵！拿起裝備跟我來！所有伐木機跟上。', 28153),
(158516, 'zhTW', '', '消滅它們，別讓它們的枝幹沾染我們族人的鮮血。', 28153),
(158515, 'zhTW', '', '你的內心在掙扎。但是德魯伊，這些古樹已經背叛了你…也背叛了自己神聖的使命。', 28153),
(158514, 'zhTW', '泰莉亞！我們需要搭個便車！', '', 28153),
(158513, 'zhTW', '基本上就是「跳下懸崖到安全地方」。走吧！', '', 28153),
(158512, 'zhTW', '然後華麗地逃跑！', '', 28153),
(158511, 'zhTW', '我們只要把保險箱抱走…', '', 28153),
(158510, 'zhTW', '我以前從來不明白陽光對一個人剩餘的皮膚有多刺激。', '我以前從來不明白陽光對一個人剩餘的皮膚有多刺激。', 28153),
(158509, 'zhTW', '我敢保證這個計畫天衣無縫。', '', 28153),
(158508, 'zhTW', '我猜你已經計畫好要怎麼帶著那個東西離開這裡了？', '我猜你已經計畫好要怎麼帶著那個東西離開這裡了？', 28153),
(158507, 'zhTW', '哈蘭在他的保險箱上再加了一道鎖來增強保全。\n\n<弗林揉著他的下巴。>\n\n沒錯，這下什麼也做不了…只有把箱子偷走。', '', 28153),
(158506, 'zhTW', '很專業嘛，哈蘭，真的很專業。', '', 28153),
(158505, 'zhTW', '我在想，只要讓我找到一名學員，你們就繞學院跑一百圈。', '', 28153),
(158504, 'zhTW', '他們一定在這附近。', '', 28153),
(158503, 'zhTW', '我們從未要求被帶回來…或承受這些。', '我們從未要求被帶回來…或承受這些。', 28153),
(158502, 'zhTW', '四個鎖？！竟然有四個？！', '', 28153),
(158501, 'zhTW', '聯盟竟然認為「我們」才是怪物？', '聯盟竟然認為「我們」才是怪物？', 28153),
(158500, 'zhTW', '那些學員去哪了…', '', 28153),
(158499, 'zhTW', '啊，就是這個…哈蘭‧史威特的保險箱。', '', 28153),
(158498, 'zhTW', '發生了這些事，我絕對不是嫉妒她。但或許她現在應該交出庫爾提拉斯，讓更有資格的人來領導。', '發生了這些事，我絕對不是嫉妒她。但或許她現在應該交出庫爾提拉斯，讓更有資格的人來領導。', 28153),
(158497, 'zhTW', '每過一天，這狀況似乎就越明顯。凱瑟琳只是藉助她過世丈夫的勢頭罷了。', '每過一天，這狀況似乎就越明顯。凱瑟琳只是藉助她過世丈夫的勢頭罷了。', 28153),
(158496, 'zhTW', '這幾個家族之間不召開會議，已經又過了一個星期。', '這幾個家族之間不召開會議，已經又過了一個星期。', 28153),
(158495, 'zhTW', '的確。任何值得一提的提拉加德貴族，都懂得別讓受害者有機會取得別人的同情。', '的確。任何值得一提的提拉加德貴族，都懂得別讓受害者有機會取得別人的同情。', 28153),
(158494, 'zhTW', '光天化日之下被謀殺，就在他們婚禮當天。這計畫也太不專業了。', '光天化日之下被謀殺，就在他們婚禮當天。這計畫也太不專業了。', 28153),
(158493, 'zhTW', '你說她未婚夫那件事嗎？當然有，真是丟臉啊。', '你說她未婚夫那件事嗎？當然有，真是丟臉啊。', 28153),
(158492, 'zhTW', '你聽說威奎斯特家的女兒發生的事了嗎？', '你聽說威奎斯特家的女兒發生的事了嗎？', 28153),
(158491, 'zhTW', '真丟臉。斯陀頌恩家竟然有人無法控制大海的？如果我是這個家族的人，早就在幾年前就和他脫離關係。', '真丟臉。斯陀頌恩家竟然有人無法控制大海的？如果我是這個家族的人，早就在幾年前就和他脫離關係。', 28153),
(158490, 'zhTW', '所以他舅舅就這樣把他趕來這裡，變成我們的問題？', '所以他舅舅就這樣把他趕來這裡，變成我們的問題？', 28153),
(158489, 'zhTW', '聽說布蘭農已經回到海灣這裡工作了。', '聽說布蘭農已經回到海灣這裡工作了。', 28153),
(158488, 'zhTW', '幸好珍娜長得像媽媽，戴林實在不怎麼好看。', '幸好珍娜長得像媽媽，戴林實在不怎麼好看。', 28153),
(158487, 'zhTW', '', '<她的背上插著一支匕首，身上的東西全被偷走了。>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158486, 'zhTW', '', '<這具贊達拉屍體似乎剛死不久。>', 28153),
(158485, 'zhTW', '<檢查屍體。>', '<檢查屍體。>', 28153),
(158484, 'zhTW', '威奎斯特家族好一陣子沒來波拉勒斯了。不知道是不是因為梅芮迪絲終於發現自己在這裡格格不入。', '威奎斯特家族好一陣子沒來波拉勒斯了。不知道是不是因為梅芮迪絲終於發現自己在這裡格格不入。', 28153),
(158483, 'zhTW', '斯陀頌恩領主上次來的時候，你看到他穿什麼嗎？如果你問我，有觸鬚的帽子是老派了點。', '斯陀頌恩領主上次來的時候，你看到他穿什麼嗎？如果你問我，有觸鬚的帽子是老派了點。', 28153),
(158482, 'zhTW', '<西蒙看了昆加一眼。>\n\n呃，沒錯…哈！哈！朋友，你真會開玩笑！\n\n哈！哈！太好笑了！\n\n你該走了，免得你又找到一個。哈！哈！\n\n你先去觀戰吧，我還要，呃…補貨。', '', 28153),
(158481, 'zhTW', '我在帳篷後面發現一具屍體。', '我在帳篷後面發現一具屍體。', 28153),
(158480, 'zhTW', '哈囉…呃…對了。\n\n歡迎光臨我的店，這是西蒙的…賣東西…之類的…店。\n\n我賣…\n\n<西蒙的目光快速掃向身後。>\n\n武器。各式各樣的武器。不過現在店員都沒空。\n\n要不要晚點再來，等我…補貨。', '', 28153),
(158479, 'zhTW', '我會宰了你，部落敗類！', '', 28153),
(158478, 'zhTW', '聯盟無權佔領我們的土地！', '聯盟無權佔領我們的土地！', 28153),
(158477, 'zhTW', '任何東西都比行軍麵包好吃。', '', 28153),
(158476, 'zhTW', '我們所有的資源都拿來為人民爭取撤退時間和阻擋部落了。去幫哨兵找些吃的東西吧。', '', 28153),
(158475, 'zhTW', '', '我要把你打入深海！', 28153),
(158474, 'zhTW', '我口袋裡的可不是魔精。', '', 28153),
(158473, 'zhTW', '你怎麼弄我，我就怎麼弄你！', '', 28153),
(158472, 'zhTW', '別逼我把你變成癩蛤蟆！', '', 28153),
(158471, 'zhTW', '你最好給我住手。我雖然老了，但我知道的妖術可不少。', '', 28153),
(158470, 'zhTW', '老兄，小心點，不用這樣戳來戳去的。', '', 28153),
(158469, 'zhTW', '我訓練暗矛食人妖已經好幾個世代啦。', '', 28153),
(158468, 'zhTW', '祝你好運，別忘了要留個好魔精在手上。', '', 28153),
(158467, 'zhTW', '', '任何東西都比行軍口糧好吃。', 28153),
(158466, 'zhTW', '', '餓肚子的軍隊無法打仗，這句話我聽過。一定能在這座森林裡找到吃的。', 28153),
(158465, 'zhTW', '別忘了，不是什麼東西都可以再生的。', '', 28153),
(158464, 'zhTW', '小心！', '', 28153),
(158463, 'zhTW', '快拿到樣本了！再給我一點時間就好…', '', 28153),
(158462, 'zhTW', '嗯，這些葉子好像有點難摘，出乎我意料之外…但我應該沒問題。', '', 28153),
(158461, 'zhTW', '這要花點時間才行，摘葉子可需要一雙巧手。', '', 28153),
(158460, 'zhTW', '我年紀大，不適合做這種事了。', '', 28153),
(158459, 'zhTW', '祖靈與你永在。', '', 28153),
(158458, 'zhTW', 'Eekum bokum。', '', 28153),
(158457, 'zhTW', '有人要找醫生嗎？', '', 28153),
(158456, 'zhTW', '需要我幫啥？', '', 28153),
(158455, 'zhTW', '你好啊。', '', 28153),
(158454, 'zhTW', '希望靈魂能指引我。', '希望靈魂能指引我。', 28153),
(158453, 'zhTW', '這些靈魂會指引你穿過這裡。', '', 28153),
(158452, 'zhTW', '烏納非，$n。這個哨站聽候你的差遣。', '', 28153),
(158451, 'zhTW', '', '危機解除了…但只是暫時。我們一定要找出供應他們軍火的人。', 28153),
(158450, 'zhTW', '', '盡量吃，滿足你的肚皮，然後休息一下吧！', 28153),
(158449, 'zhTW', '這個地方的封印是用來保護世界之魂的。但是艾澤萊晶岩不斷湧出，封印已經快裂開了！', '', 28153),
(158448, 'zhTW', '如果你用護符吸收艾澤萊晶岩，就可以用它的力量修復封印！', '', 28153),
(158447, 'zhTW', '', '據說那些幫派成員已經拿到某些威力強大的艾澤萊晶岩炸彈。找回那些炸彈，否則全波拉勒斯都會有危險！', 28153),
(158446, 'zhTW', '我的船沉沒了，數百名船員落入海中。不到一小時，鯊魚來了。有小鯊魚、大鯊魚、憤怒的鯊魚。我們用盡全力對抗牠們，但是當你直視牠們那毫無生氣的黑色眼珠，你會覺得牠們好似沒有生命，直到牠們撲上來咬你。大海被染紅了，情況越來越慘，一個人瞬間就會被撕成碎片。我們的人在捱過第一個晚上後大概已經少了一半。海裡彷彿有上千條鯊魚。最後終於有人來救我們的時候，已經過了五天，差一點就太晚了。三百一十六人出海，只有七個人回來，其他全被鯊魚吃了。\n\n說得夠多了。要不要去打幾條鯊魚？', '', 28153),
(158445, 'zhTW', '謝謝你。我願意冒這個風險。這雙靴子借我吧。', '謝謝你。我願意冒這個風險。這雙靴子借我吧。', 28153),
(158444, 'zhTW', '', '好痛！我只是想要搬走這些…呃…從貨車後面掉下來的箱子。\n\n至少可達沒事。誰也不能傷害我這可愛的小傢伙！\n\n如果你想跳回北邊的話，我還有一雙靴子。但是要警告你…這雙我還沒測試過。', 28153),
(158443, 'zhTW', '', '我們來晚了。', 28153),
(158442, 'zhTW', '', '你去看看這些人需要什麼幫助。我先到前面去！', 28153),
(158441, 'zhTW', '', '我們要先守住戴林之門！', 28153),
(158440, 'zhTW', '', '噢不…', 28153),
(158439, 'zhTW', '', '我們知道。你先喘口氣。那個人不會有好下場的。', 28153),
(158438, 'zhTW', '哈蘭…那個混蛋一直都是艾胥凡的奸細…他是…啊！', '', 28153),
(158437, 'zhTW', '呃…全身都痛…<咳嗽>', '', 28153),
(158436, 'zhTW', '', '弗林！冷靜點，是我！你還好嗎？覺得哪裡痛？', 28153),
(158435, 'zhTW', '呃…啊…嗚哇哇哇哇！！！', '', 28153),
(158434, 'zhTW', '', '來吧，母親，我們該回家了。', 28153),
(158433, 'zhTW', '', '抓緊了！', 28153),
(158432, 'zhTW', '我準備好要離開了。', '我準備好要離開了。', 28153),
(158431, 'zhTW', '', '$c，等你準備好，我可以把我們傳送出去。\n\n請快一點，我想趕快離開這裡。', 28153),
(158430, 'zhTW', '過場動畫！', '過場動畫！', 28153),
(158429, 'zhTW', '夜精靈雖然是很好的鄰居，但…要習慣他們的幽光還是會花點時間。', '', 28153),
(158428, 'zhTW', '使用土地，開墾土地，這就是我們該做的。', '', 28153),
(158427, 'zhTW', '那棵樹發生的事真叫人遺憾。', '', 28153),
(158426, 'zhTW', '你以為能夠阻止我們帶走德瑞克的屍體？你有苦頭吃了！', '', 28153),
(158425, 'zhTW', '這次樂樂只需要抵達終點就好，但是要小心潛伏在迷宮裡的危險。', '', 28153),
(158424, 'zhTW', '你能夠帶樂樂找到寶藏，然後走到終點，並且避開他走過的路嗎？', '', 28153),
(158423, 'zhTW', '是不是很簡單呢？', '', 28153),
(158422, 'zhTW', '先來個簡單的挑戰吧，引導樂樂走到終點。', '', 28153),
(158421, 'zhTW', '講這些故事的時候，我們會叫年輕的托爾托帶樂樂去走迷宮，完成不同的挑戰。', '', 28153),
(158420, 'zhTW', '你準備好接受戰鬥訓練了嗎？', '你準備好接受戰鬥訓練了嗎？', 28153),
(158419, 'zhTW', '我們來蜂狂地蜂一下吧，$p！', '我們來蜂狂地蜂一下吧，$p！', 28153),
(158418, 'zhTW', '樂樂的成功讓他越來越有自信。樂樂也因此開始探索更多有趣的地方。', '', 28153),
(158416, 'zhTW', '你可以帶著樂樂找到所有寶藏，然後走到終點，並且避開他走過的路嗎？', '', 28153),
(158415, 'zhTW', '樂樂開始到處探索古老的遺跡，也常常會發現奇妙的寶藏。', '', 28153),
(158414, 'zhTW', '「冒險者樂樂。」長大了，他開始對這個世界感到好奇。', '', 28153),
(158413, 'zhTW', '辛勤的樂樂終於有好成果，大地給他好多營養豐富的食物。', '', 28153),
(158412, 'zhTW', '你可以幫樂樂一次忙嗎？去看看花園裡的每一株植物。', '', 28153),
(158411, 'zhTW', '每天早上他都會去觀察花園裡每一株植物。', '', 28153),
(158410, 'zhTW', '', '佐司特顯然不會留下活口。我們絕對不能讓珍娜遭遇這種厄運。', 28153),
(158409, 'zhTW', '「樂樂的豐收。」樂樂最喜歡看東西生長了。', '', 28153),
(158408, 'zhTW', '樂樂好不容易才逃出來，於是他決定過個輕鬆一點的生活。', '', 28153),
(158407, 'zhTW', '你能幫樂樂關掉發光的格子，解除這個陷阱嗎？', '', 28153),
(158406, 'zhTW', '俗話說，「好奇心害死托爾托」。有一次，樂樂差點因為好奇而沒命，他中了古老的贊達拉陷阱！', '', 28153),
(158405, 'zhTW', '', '求我饒命吧！', 28153),
(158404, 'zhTW', '樂樂不適合城市生活。樂樂想過得更簡單一點。', '', 28153),
(158403, 'zhTW', '但是樂樂一直迷路。你可以帶著樂樂找到城市裡所有的商店，然後再去旅店，並且避開他走過的路嗎？', '', 28153),
(158402, 'zhTW', '「城市生活。」樂樂曾經去過大城市一次，有點像這附近的波拉勒斯。', '', 28153),
(158401, 'zhTW', '樂樂繼續過著安詳而平靜的生活…而且不愁吃喝。', '', 28153),
(158399, 'zhTW', '', '我在這些神殿周圍抓到幾隻小型元素生物，它們好有意思。想不想見識它們的能力？', 28153),
(158398, 'zhTW', '顧客跑了…$pr太強了…', '', 28153),
(158397, 'zhTW', '我還餓…', '', 28153),
(158396, 'zhTW', '怎麼暗下來了？', '', 28153),
(158395, 'zhTW', '再見了，加里維克斯…', '', 28153),
(158394, 'zhTW', '不准打架！', '', 28153),
(158393, 'zhTW', '上工第一天！祝好運！', '', 28153),
(158392, 'zhTW', '這裡不准$pr進入！', '', 28153),
(158391, 'zhTW', '私人派對！', '', 28153),
(158390, 'zhTW', '你還是我今天遇到的…第二差勁的客人…', '你還是我今天遇到的…第二差勁的客人…', 28153),
(158389, 'zhTW', '一名哥布林…被端走了…', '一名哥布林…被端走了…', 28153),
(158388, 'zhTW', '最後一次點…卡嘉可樂…', '最後一次點…卡嘉可樂…', 28153),
(158387, 'zhTW', '你最好…給我很多小費…', '你最好…給我很多小費…', 28153),
(158386, 'zhTW', '我從來沒學會…怎麼玩…高爾夫球…', '我從來沒學會…怎麼玩…高爾夫球…', 28153),
(158385, 'zhTW', '你只不過是個…雙柏忌…', '你只不過是個…雙柏忌…', 28153),
