(158375, 'zhTW', '我聽到聲音…', '我聽到聲音…', 28153),
(158374, 'zhTW', '老兄，這些飲料你得自己付！', '老兄，這些飲料你得自己付！', 28153),
(158373, 'zhTW', '把球一桿打進…你的膝蓋骨好不好呀！', '把球一桿打進…你的膝蓋骨好不好呀！', 28153),
(158372, 'zhTW', '<醫生轉過來對你低語。>$b$b他們傷得很重。照他們的情況看來，我們不能搬動他們。我能做的只有把他們的傷口包紮好，然後試著逃出這裡。$b$b那裡簡直就是一團混亂…', '不適用', 28153),
(158371, 'zhTW', '隨便做什麼都好過看這些笨蛋打曲球。', '隨便做什麼都好過看這些笨蛋打曲球。', 28153),
(158370, 'zhTW', '這種狀況的話，我建議朝臉揮九號鐵桿！', '這種狀況的話，我建議朝臉揮九號鐵桿！', 28153),
(158369, 'zhTW', '終於輪到我打了！', '終於輪到我打了！', 28153),
(158368, 'zhTW', '哈！騙到你了！我一直是臥底的警衛！', '哈！騙到你了！我一直是臥底的警衛！', 28153),
(158367, 'zhTW', '別擔心，我行的。', '別擔心，我行的。', 28153),
(158366, 'zhTW', '不要靠近客人！', '不要靠近客人！', 28153),
(158365, 'zhTW', '我的報酬才這麼一點，太不划算了。', '我的報酬才這麼一點，太不划算了。', 28153),
(158364, 'zhTW', '我需要…再烤…一次…', '我需要…再烤…一次…', 28153),
(158363, 'zhTW', '讓我曬到太陽…然後幫我翻身，別讓我曬傷…', '讓我曬到太陽…然後幫我翻身，別讓我曬傷…', 28153),
(158362, 'zhTW', '哈！他們還說…陽光會殺死我…', '哈！他們還說…陽光會殺死我…', 28153),
(158361, 'zhTW', '不，我美麗的古銅色肉體…', '不，我美麗的古銅色肉體…', 28153),
(158360, 'zhTW', '我要找加里維克斯…好好談談…', '我要找加里維克斯…好好談談…', 28153),
(158359, 'zhTW', '我只是想要享受派對…', '我只是想要享受派對…', 28153),
(158358, 'zhTW', '這裡不歡樂…也不是宮殿…', '這裡不歡樂…也不是宮殿…', 28153),
(158357, 'zhTW', '可是我…是重要人物…', '可是我…是重要人物…', 28153),
(158356, 'zhTW', '桿弟，帶我…進洞。', '桿弟，帶我…進洞。', 28153),
(158355, 'zhTW', '至少我死得…低於標準桿。', '至少我死得…低於標準桿。', 28153),
(158354, 'zhTW', '把我葬在…沙坑裡。', '把我葬在…沙坑裡。', 28153),
(158353, 'zhTW', '讓他們知道…我低於標準桿。', '讓他們知道…我低於標準桿。', 28153),
(158352, 'zhTW', '我這輩子…最棒的派對。', '我這輩子…最棒的派對。', 28153),
(158351, 'zhTW', '我這輩子…最糟的派對。', '我這輩子…最糟的派對。', 28153),
(158350, 'zhTW', '我要…退錢。', '我要…退錢。', 28153),
(158349, 'zhTW', '再…一杯…就好…', '再…一杯…就好…', 28153),
(158348, 'zhTW', '我們滿了。去其他地方游泳！', '我們滿了。去其他地方游泳！', 28153),
(158347, 'zhTW', '這座泳池不准$pr進來！', '這座泳池不准$pr進來！', 28153),
(158346, 'zhTW', '你看到我剛剛的跳水了嗎？是10分的完美表現哪！', '你看到我剛剛的跳水了嗎？是10分的完美表現哪！', 28153),
(158345, 'zhTW', '喂，$pr，你好大的醜臉擋到我的陽光啦！', '喂，$pr，你好大的醜臉擋到我的陽光啦！', 28153),
(158344, 'zhTW', '真是的，加里維克斯的保全越來越差了。', '真是的，加里維克斯的保全越來越差了。', 28153),
(158343, 'zhTW', '我多付這些錢，可不是為了讓$pr來打擾我！', '我多付這些錢，可不是為了讓$pr來打擾我！', 28153),
(158342, 'zhTW', '滾吧，$p。要鬧事就去找泳池旁邊的群眾。', '滾吧，$p。要鬧事就去找泳池旁邊的群眾。', 28153),
(158341, 'zhTW', '幫我拿一下卡嘉可樂。我來對付。', '幫我拿一下卡嘉可樂。我來對付。', 28153),
(158340, 'zhTW', '離開草地！你們的鞋子會把草踏扁。', '離開草地！你們的鞋子會把草踏扁。', 28153),
(158339, 'zhTW', '桿弟，拿我的木桿來！這一球需要飛遠一點。', '桿弟，拿我的木桿來！這一球需要飛遠一點。', 28153),
(158338, 'zhTW', '下次我要用你的眼球一桿進洞！', '下次我要用你的眼球一桿進洞！', 28153),
(158337, 'zhTW', '草皮受到干擾！我要再開一球！', '草皮受到干擾！我要再開一球！', 28153),
(158336, 'zhTW', '滾吧，$pr。我們還要忙著大吃大喝，然後再多喝幾杯呢！', '滾吧，$pr。我們還要忙著大吃大喝，然後再多喝幾杯呢！', 28153),
(158335, 'zhTW', '我不介意多點刺激。', '我不介意多點刺激。', 28153),
(158334, 'zhTW', '警衛！把這個$pr帶走！', '警衛！把這個$pr帶走！', 28153),
(158333, 'zhTW', '我來這裡消費可不是要讓人欺負聯盟的！', '我來這裡消費可不是要讓人欺負聯盟的！', 28153),
(158332, 'zhTW', '好痛…', '', 28153),
(158331, 'zhTW', '哥布林…快逃！', '', 28153),
(158330, 'zhTW', '我只是想要…亮晶晶…', '', 28153),
(158329, 'zhTW', '我盡力了…', '', 28153),
(158328, 'zhTW', '告訴加老大…我很抱歉…', '', 28153),
(158327, 'zhTW', '繼續工作…', '', 28153),
(158326, 'zhTW', '我好睏…', '', 28153),
(158325, 'zhTW', '黃金…源源不絕。', '', 28153),
(158324, 'zhTW', '不准碰！', '', 28153),
(158323, 'zhTW', '我們閃亮的黃金！', '', 28153),
(158322, 'zhTW', '加老大要我們砍死$pr。', '', 28153),
(158321, 'zhTW', '別靠近哥布林！', '', 28153),
(158320, 'zhTW', '給我黃金！', '', 28153),
(158319, 'zhTW', '加老大最好了！', '', 28153),
(158318, 'zhTW', '不准停止工作！', '', 28153),
(158317, 'zhTW', '不准拖！', '', 28153),
(158316, 'zhTW', '他們會在虛無面前顫抖。', '他們會在虛無面前顫抖。', 28153),
(158315, 'zhTW', '我透過帷幕看到了他們。跟我來。', '我透過帷幕看到了他們。跟我來。', 28153),
(158314, 'zhTW', '來吧，小哥布林…', '來吧，小哥布林…', 28153),
(158313, 'zhTW', '', '我們在亞格洛克集結了兵力。帶著你的人為部落搶下激流堡！', 28153),
(158312, 'zhTW', '<離開並前往突擊羅德隆>', '<離開並前往突擊羅德隆>', 28153),
(158311, 'zhTW', '除非氣氛變好，不然驚喜會持續下去。', '', 28153),
(158310, 'zhTW', '這會是個適合和朋友分享的好笑故事。', '', 28153),
(158309, 'zhTW', '拿出你的相機。倒數3…2…1…', '', 28153),
(158308, 'zhTW', '啟動快樂時光。', '', 28153),
(158307, 'zhTW', '收到驚喜要求。不顧一切執行要求。', '', 28153),
(158306, 'zhTW', '務必維持最高歡樂等級。', '', 28153),
(158305, 'zhTW', '絕不容忍無聊的派對賓客。', '', 28153),
(158304, 'zhTW', '偵測到趣味過低。調整中。', '', 28153),
(158303, 'zhTW', '', '…戰爭結束時候我會告訴你。', 28153),
(158302, 'zhTW', '算了，別在意。', '算了，別在意。', 28153),
(158301, 'zhTW', '對。', '對。', 28153),
(158300, 'zhTW', '', '我們距離部落的聚會地點只隔一箭之遙，而你問我為什麼會有一瓶讓你隱形的藥水？', 28153),
(158299, 'zhTW', '你怎麼會有隱形藥水？', '你怎麼會有隱形藥水？', 28153),
(158298, 'zhTW', '噓，快點離開。你會讓我被發現。', '', 28153),
(158297, 'zhTW', '送我到旗艦上。', '送我到旗艦上。', 28153),
(158296, 'zhTW', '如果你需要我把你送上那些船艦，就跟我說一聲！', '', 28153),
(158295, 'zhTW', '那棵巨大的行走樹木真是壯觀！', '', 28153),
(158294, 'zhTW', '你讓沃格里許緊張，要懲罰！', '', 28153),
(158293, 'zhTW', '沃格里許從來沒發生過這種事！', '', 28153),
(158292, 'zhTW', '啊啊啊啊！沃格里許被羞辱了！', '', 28153),
(158291, 'zhTW', '夜精靈真的對種東西很拿手。', '', 28153),
(158290, 'zhTW', '我讓你看到沃格里許真正的力量！', '', 28153),
(158289, 'zhTW', '弱者，迎接煉獄吧！', '', 28153),
(158288, 'zhTW', '巨魔要發威了！', '', 28153),
(158287, 'zhTW', '能夠多個幫手真好。', '', 28153),
(158286, 'zhTW', '', '珊蒂斯…你一定…要活下來…', 28153),
(158285, 'zhTW', '', '為了…我的…同胞…', 28153),
(158284, 'zhTW', '沃格里許要燒了你的腳！', '', 28153),
(158283, 'zhTW', '沃格里許的魔法失控了！', '', 28153),
(158282, 'zhTW', '', '在死後…加入我吧！', 28153),
(158281, 'zhTW', '見證我驚人的力量！', '', 28153),
(158280, 'zhTW', '啊，時機正好。', '', 28153),
(158279, 'zhTW', '', '看來你不需要等太久了，納薩諾斯。', 28153),
(158278, 'zhTW', '', '這些都亮晶晶的耶！我猜大的這個受過浪潮賢者的祝福，然後這個螺旋狀的來自海盜的寶藏箱！', 28153),
(158277, 'zhTW', '', '這樣他們就損失很多可以刺傷我們士兵的幽光了。做得好。', 28153),
(158276, 'zhTW', '', '我們要先清空這一區，部隊才能安全通過。別小看幽光的威力，尤其數量繁多的幽光。', 28153),
(158275, 'zhTW', '', '你一定不敢相信在這裡釣魚可以釣到什麼怪東西。在過去的幾天裡，我釣起了一些奇特的生物，想不想對戰？', 28153),
(158274, 'zhTW', '莉莉安不斷告訴我，部落是我的家人。\n\n既然我真正的家人不接納我…說實話，我很願意投入部落的懷抱。\n\n不過做為回報，莉莉安答應會保護我家人安全。如果只要我協助部落就可以確保他們安全，\n\n那我就會這麼做。', '', 28153),
(158273, 'zhTW', '', '我們該走了！', 28153),
(158272, 'zhTW', '', '賣貝殼喲！全庫爾提拉斯最美麗的貝殼。不對，是艾澤拉斯！全艾澤拉斯最美的貝殼！', 28153),
(158271, 'zhTW', '', '我漸漸恢復理智了，$n。\n\n有了莉莉安的幫助，或許我可以接受這個全新的命運。\n\n但我得說…我能夠離庫爾提拉斯越遠…就越好。', 28153),
(158270, 'zhTW', '我很感激有這次機會證明刃多雷對於我們事業的價值。\n\n我們會不計代價確保聯盟的勝利！', '', 28153),
(158269, 'zhTW', '', '到此為止。高階指揮官龍禍給我的印象很深刻。\n\n他有著多樣的戰術，並且可以快速適應不斷變換的環境，採取適當而必要的策略。\n\n聯盟的戰爭事務由有能力的人在管理。就跟你一樣，我很自豪可以參與其中。', 28153),
(158268, 'zhTW', '', '一定要消滅那個煞婪吸血鬼。部落如此魯莽行事，會讓我們全體陷入危機之中。', 28153),
(158267, 'zhTW', '很快你就看到。火！沒錯，大火！', '', 28153),
(158266, 'zhTW', '需要的時候我會再找你的。為了聯盟。', '', 28153),
(158265, 'zhTW', '立刻向安杜因國王報告。我們完成了這裡的工作，但是我們的任務才剛要開始。', '', 28153),
(158264, 'zhTW', '部落真的雇用了這些吸血的精靈嗎？他們竟墮落到這種地步。', '', 28153),
(158263, 'zhTW', '只有煙霧，沒有鏡子！', '', 28153),
(158262, 'zhTW', '從你描述的內容…聽起來像是煞婪一族的…血親王。', '', 28153),
(158261, 'zhTW', '', '古…古茲死了？', 28153),
(158260, 'zhTW', '只要有煙，就絕對有火…相信我！', '', 28153),
(158259, 'zhTW', '該進行下個階段了。', '', 28153),
(158258, 'zhTW', '德瑞克‧普勞德摩爾的屍體在我們手上。我們不需要其他庫爾提拉斯人的屍體了。暫時不用。', '', 28153),
(158257, 'zhTW', '希望你的努力沒有白費。', '', 28153),
(158256, 'zhTW', '戰火延燒到黑海岸了，我們必須盡量保護族人。把你找到的幽光指引到前線，然後消滅威脅。', '', 28153),
(158255, 'zhTW', '', '哈！我聽到被困住的叛徒慘叫！', 28153),
(158254, 'zhTW', '', '讓疲憊獲得休息，飢餓獲得飽足。', 28153),
(158253, 'zhTW', '', '我可沒有同意要把庫爾提拉斯引到我的港口。\n\n你最好有個合適的計畫。我可不打算失去自由。', 28153),
(158252, 'zhTW', '開始儀式吧。', '開始儀式吧。', 28153),
(158251, 'zhTW', '你從哪裡來的？', '你從哪裡來的？', 28153),
(158250, 'zhTW', '你待在這裡多久了？', '你待在這裡多久了？', 28153),
(158249, 'zhTW', '這是我唯一的家園。\n\n沙漠延伸到哪，我們就去到哪。', '這是我唯一的家園。\n\n沙漠延伸到哪，我們就去到哪。', 28153),
(158248, 'zhTW', '我的商隊早在我出生之前就把這片沙漠視為自己的家。\n\n渡海之後還有其他沙漠，但我從來沒見過。', '我的商隊早在我出生之前就把這片沙漠視為自己的家。\n\n渡海之後還有其他沙漠，但我從來沒見過。', 28153),
(158247, 'zhTW', '別胡說了。博學者，你和你的同胞做得非常好。你們是聯盟的表率。', '', 28153),
(158246, 'zhTW', '我代表所有的虛無精靈，對我們的失敗致上歉意。', '', 28153),
(158245, 'zhTW', '', '我們必須趕去守望山丘。快點，跳上來！', 28153),
(158244, 'zhTW', '夸風滿足地發出鳴叫，然後蜷起來打盹。', '', 28153),
(158243, 'zhTW', '村民發出痛苦的呻吟。', '村民發出痛苦的呻吟。', 28153),
(158242, 'zhTW', '你好，$n！這個哨站聽候你的差遣。', '', 28153),
(158241, 'zhTW', '', '哼。', 28153),
(158240, 'zhTW', '感謝你出力，我們會付你豐厚的報償。', '', 28153),
(158239, 'zhTW', '', '納薩諾斯，我告訴過你，你的部落可以在我的港口建立基地。但是我並沒有允許你對普勞德摩爾的艦隊敞開大門！', 28153),
(158238, 'zhTW', '那個權杖是個神器，具有操控海洋的無窮力量。我們會再度用它來打敗庫爾提拉斯艦隊。', '', 28153),
(158237, 'zhTW', '', '你打算怎麼潛進去？波拉勒斯可不是隨隨便便進得去的…', 28153),
(158236, 'zhTW', '我派瓦倫泰去波拉勒斯，不計一切代價告訴普勞德摩爾女士：你兒子在我們手中。', '', 28153),
(158235, 'zhTW', '冷靜，我的朋友。這個海盜一定會因為他的罪行付出代價。然而，我們必須等待法庭宣判他最後的刑責。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158234, 'zhTW', '我們在這裡的任務是取回深淵權杖，它在波拉勒斯的斯陀頌恩修道院深處。', '', 28153),
(158233, 'zhTW', '', '進來吧，$n。納薩諾斯會向你說明。', 28153),
(158232, 'zhTW', '法庭判你高利貸有罪。你貪婪的借貸洗劫了勾角地很多好人的積蓄。很多人因為你的罪行而流落街頭。', '', 28153),
(158231, 'zhTW', '法庭判你海盜、竊盜與謀殺有罪。根據庫爾提拉斯法律，海盜是所有罪行中最可恥的，而你將要伏法。', '', 28153),
(158230, 'zhTW', '敲詐與勒索！這裡有很多家庭今天都成為你陰謀下的犧牲品。你對這些庫爾提拉斯的好人收取過高的價格。現在就是你要承擔後果了。', '', 28153),
(158229, 'zhTW', '跟我來。我直接帶你們去見艾蘭里亞和高階指揮官。', '', 28153),
(158228, 'zhTW', '雖然這不是我希望能為聯盟帶來的全面勝利，但事不宜遲。', '', 28153),
(158227, 'zhTW', '我們一直在追獵的其實個加里維克斯的替身？哥布林真的是最糟糕的了。', '', 28153),
(158226, 'zhTW', '再見啦，廢物！', '', 28153),
(158225, 'zhTW', '但是這幾副機甲可不便宜，$p。我會把帳單寄去給你。', '', 28153),
(158224, 'zhTW', '你會死在汙水企業指南裡最古老的伎倆，高品質低薪工人的手上。', '', 28153),
(158223, 'zhTW', '哈！我真希望你們現在能看到自己的表情。', '', 28153),
(158222, 'zhTW', '', '光是想想有靈魂能躲過伯昂撒姆第就夠驚人了。我只希望他朋友間的羈絆能足夠讓我們在彼界聯繫到他。', 28153),
(158221, 'zhTW', '$n，在營地的西邊有一具望遠鏡，你何不去把他找出來？', '', 28153),
(158220, 'zhTW', '嗯…對了，古茲柏呢？他應該隨時都有可能出現。', '', 28153),
(158219, 'zhTW', '', '我是第一個回來的嗎？古茲在哪？', 28153),
(158218, 'zhTW', '鋼火小姐，歡迎回來。', '', 28153),
(158217, 'zhTW', '', '喂，老闆！你聽到那聲巨響了嗎？我想我把一個哥布林給轟上近地軌道了。', 28153),
(158216, 'zhTW', '古茲柏和凱爾希應該隨時會出現。', '', 28153),
(158215, 'zhTW', '呵，這個世界又為我做過什麼呢？', '', 28153),
(158214, 'zhTW', '你的自我膨脹得就像你的身體一樣。想想你的能力可以為這個世界做多少事！', '', 28153),
(158213, 'zhTW', '加里維克斯，你累積了這麼多財富，但是卻用來建造這裡？簡直是罪惡的巢穴！', '', 28153),
(158212, 'zhTW', '', '使用生氣勃勃來完全恢復你的生命力。', 28153),
(158211, 'zhTW', '使用生氣勃勃來完全恢復你的生命力。', '', 28153),
(158210, 'zhTW', '', '承受傷害是戰鬥的一部分，但身為武僧你可以運用迷霧來治療自己或是盟友。使用生氣勃勃技能來治療你的傷口。', 28153),
(158209, 'zhTW', '承受傷害是戰鬥的一部分，但身為武僧你可以運用迷霧來治療自己或是盟友。使用生氣勃勃技能來治療你的傷口。', '', 28153),
(158208, 'zhTW', '聯盟被擊敗了！', '', 28153),
(158207, 'zhTW', '|A:Warfront-HordeWave3:25:23:0:0|a部落部署了一支突襲隊！', '|A:Warfront-HordeWave3:25:23:0:0|a部落部署了一支突襲隊！', 28153),
(158206, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a英勇之喚小徑失守！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a英勇之喚小徑失守！', 28153),
(158205, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a紐沃農莊失守！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a紐沃農莊失守！', 28153),
(158204, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a元素之環失守！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a元素之環失守！', 28153),
(158203, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a高地駐營失守！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a高地駐營失守！', 28153),
(158202, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a諾斯弗德路口失守！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a諾斯弗德路口失守！', 28153),
(158201, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a賈爾森礦場失守！', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a賈爾森礦場失守！', 28153),
(158200, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a高地伐木場失守！', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a高地伐木場失守！', 28153),
(158199, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a賈爾森礦場正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a賈爾森礦場正遭受攻擊！', 28153),
(158198, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a高地伐木場正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a高地伐木場正遭受攻擊！', 28153),
(158197, 'zhTW', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|a你的指揮官正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a你的指揮官正遭受攻擊！', 28153),
(158196, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a英勇之喚小徑正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a英勇之喚小徑正遭受攻擊！', 28153),
(158195, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a紐沃農莊正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a紐沃農莊正遭受攻擊！', 28153),
(158194, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a元素之環正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a元素之環正遭受攻擊！', 28153),
(158193, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a諾斯弗德路口正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a諾斯弗德路口正遭受攻擊！', 28153),
(158192, 'zhTW', '聽你指示，按下大顆的紅色按鈕。知道了。', '聽你指示，按下大顆的紅色按鈕。知道了。', 28153),
(158191, 'zhTW', '告訴我可以飛往那些地方。', '告訴我可以飛往那些地方。', 28153),
(158190, 'zhTW', '你想不想飛到別的地方？', '', 28153),
(158189, 'zhTW', '又有人出價了！為什麼有些人就是要從別人的悲慘命運中牟利？', '又有人出價了！為什麼有些人就是要從別人的悲慘命運中牟利？', 28153),
(158188, 'zhTW', '我們沒有值錢的東西可以賣了。', '我們沒有值錢的東西可以賣了。', 28153),
(158187, 'zhTW', '我希望我們剩下的還夠買我們需要的補給。', '我希望我們剩下的還夠買我們需要的補給。', 28153),
(158186, 'zhTW', '我們還剩下多少黃金？', '我們還剩下多少黃金？', 28153),
(158185, 'zhTW', '沒有足夠的糧食配給…', '沒有足夠的糧食配給…', 28153),
(158183, 'zhTW', '旅行者，旅途小心。有奇怪的東西潛伏在佐司瓦的暗影。', '旅行者，旅途小心。有奇怪的東西潛伏在佐司瓦的暗影。', 28153),
(158182, 'zhTW', '哇…哇…這件套裝故障了！', '', 28153),
(158181, 'zhTW', '烏鴉都在看著！牠們笑個不停！牠們要來殺我了！', '', 28153),
(158180, 'zhTW', '', '你害我…把酒…灑出來了…', 28153),
(158179, 'zhTW', '', '你以為可以騙倒我嗎？！我要<嗝>刺穿你！', 28153),
(158178, 'zhTW', '', '做得好。我們回營地的另一邊見。', 28153),
(158177, 'zhTW', '加里維克斯，你看！', '加里維克斯，你看！', 28153),
(158176, 'zhTW', '聯盟？他們在贊達拉？', '', 28153),
(158175, 'zhTW', '我們跟著沙子一起旅行。', '我們跟著沙子一起旅行。', 28153),
(158174, 'zhTW', '沙丘裡充滿著寶藏，等我們去發掘。', '沙丘裡充滿著寶藏，等我們去發掘。', 28153),
(158173, 'zhTW', '貨車在哪，家就在哪。', '貨車在哪，家就在哪。', 28153),
(158171, 'zhTW', '|TInterface\\Icons\\INV_Mace_2H_CapturedTitanConstruct_D_01:20|t%s的|cFFFF0000|Hspell:271296|h[染血鬥棍]|h|r鎖定你了！', '', 28153),
(158170, 'zhTW', '', '這些可憐的靈魂…不該忍受這種折磨的。等我們救出珍娜，一定要想辦法再回來救它們。', 28153),
(158169, 'zhTW', '我可以確定一件事，佐司瓦陷入瘋狂了。', '我可以確定一件事，佐司瓦陷入瘋狂了。', 28153),
(158168, 'zhTW', '我聽其中一人說到出現了想吃人肉的鹿。', '我聽其中一人說到出現了想吃人肉的鹿。', 28153),
(158167, 'zhTW', '你說怪物人和木頭惡魔嗎？有啊，我聽他們談論過。', '你說怪物人和木頭惡魔嗎？有啊，我聽他們談論過。', 28153),
(158166, 'zhTW', '你聽到他們在說什麼了嗎？為什麼這些難民會在這裡？', '你聽到他們在說什麼了嗎？為什麼這些難民會在這裡？', 28153),
(158165, 'zhTW', '有些日子，我認為我可以用嘴巴發出嗡嗡聲，成功與我的蜜蜂溝通。不過我想如果要讓溝通真的奏效，大概得等到我把我的蜜蜂服做好。不過先別說這個了，我的蜜蜂是最強的，你想和牠們對戰，還是要走掉？', '', 28153),
(158164, 'zhTW', '', '願我們的意志比他們的戰爭機器更強大。', 28153),
(158163, 'zhTW', '勇士，卡多雷不會忘記你的付出。在這黑暗時刻，你能提供的任何幫助都可能扭轉戰局。', '', 28153),
(158162, 'zhTW', '雖然眼前挑戰艱鉅，但不要絕望。既然伊露恩給我們力量，我們就不能輕易放手。', '', 28153),
(158161, 'zhTW', '僅僅一場戰役不代表戰爭的結局。我們還有希望。', '', 28153),
(158160, 'zhTW', '安杜因國王也會派援軍過來，但在此之前，我們絕對要堅守到底。', '', 28153),
(158159, 'zhTW', '我們的艦隊從希利蘇斯回來了。讚美伊露恩！回來得真是時候。', '', 28153),
(158158, 'zhTW', '幽光仍在堅守防線，但是部落有很多士兵攻上黑海岸了。', '', 28153),
(158157, 'zhTW', '這下子他們的士氣八成受到嚴重打擊，千萬別低估心理戰帶來的成效。', '', 28153),
(158156, 'zhTW', '你對納薩諾斯說的話真不客氣。', '你對納薩諾斯說的話真不客氣。', 28153),
(158155, 'zhTW', '自由港的海盜越來越囂張了。我們要在他們內部埋下混亂的種子。就用他們的坐騎來對付他們吧，讓他們知道什麼叫做禍從天降！', '', 28153),
(158154, 'zhTW', '', '只要是水手，都害怕海妖的聲音。不過顯然有些人還是會去聽。', 28153),
(158153, 'zhTW', '', '海妖又抓到了一艘庫爾提拉斯運輸船。你去看看有什麼物資可以拿回來…不過小心，別落得跟那些船員一樣的下場！', 28153),
(158152, 'zhTW', '等著你的命運，會比死亡還糟…', '', 28153),
(158151, 'zhTW', '你們以為自己贏了嗎！？在我倒下之後，你們的厄運才剛要開始！', '', 28153),
(158150, 'zhTW', '非常好，這下子我們就有裝備上的優勢了。', '', 28153),
(158149, 'zhTW', '不能讓庫爾提拉斯繼續製造艾澤萊晶岩武器。毀掉那座鑄造廠！', '', 28153),
(158148, 'zhTW', '', '如果讓狂熱者懷疑你的忠心，你就小命難保了。\n\n我是受徵召來加入這場戰役的。你大概也是。我們一定要不擇手段－真的得不擇手段－來活下來。\n\n但是記住。最重要的戰爭只有一個，而且並不是這一個。', 28153),
(158147, 'zhTW', '你們的命運…都是一樣的…', '', 28153),
(158146, 'zhTW', '你們…太遲了…救不了她的…', '', 28153),
(158145, 'zhTW', '等待你們的…只有無盡的折磨…', '', 28153),
(158144, 'zhTW', '她…已經沒救了…', '', 28153),
(158143, 'zhTW', '我要復仇！', '', 28153),
(158142, 'zhTW', '普勞德摩爾是我們的了！', '', 28153),
(158141, 'zhTW', '你們也都會被吞噬！', '', 28153),
(158140, 'zhTW', '你們就加入她一起受苦吧！', '', 28153),
(158139, 'zhTW', '', '我在這一帶工作的時間夠我找到從這種艾澤萊晶岩而生的有趣生物。想不想和我暗中收集到的野性艾澤萊晶岩元素生物來場對戰，試試你的運氣呢？', 28153),
(158138, 'zhTW', '你們這些蠢蛋！你們絕對無法理解你們正在玩弄的力量！', '', 28153),
(158137, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a高地駐營正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a高地駐營正遭受攻擊！', 28153),
(158136, 'zhTW', '', '不完全是。當你看到機會出現，就要把握住。\n\n我的未來我一直都計畫好了。該是我付諸行動，讓計畫實現的時候了。', 28153),
(158135, 'zhTW', '我以為你服侍的是無冕者。你改變陣營了嗎？', '我以為你服侍的是無冕者。你改變陣營了嗎？', 28153),
(158134, 'zhTW', '我自由啦！謝謝你…現在，你的靈魂將滿足我無盡的饑渴！', '', 28153),
(158133, 'zhTW', '你來選擇第一個目標地區。等你決定好，我們就立刻行動。', '', 28153),
(158132, 'zhTW', '', '做得不錯。剩下的可以交給守衛處理。我們需要仔細觀察這座莊園。', 28153),
(158131, 'zhTW', '', '怪物一直從威奎斯特莊園衝出來！我們必須阻止牠們，別讓牠們跑去亞羅姆之地！', 28153),
(158129, 'zhTW', '我們會打贏這場戰爭。為了聯盟！', '', 28153),
(158128, 'zhTW', '去食人妖的土地尋找機會吧，我們必須竭盡所能，破壞大酋長的計畫。', '', 28153),
(158127, 'zhTW', '你在贊達拉建立據點，勇敢踏出了第一步。現在，我們能趁勢進攻部落！', '', 28153),
(158126, 'zhTW', '戰局瞬息萬變，我們的目標到了該調整的時候。', '', 28153),
(158125, 'zhTW', '我從來沒感到如此飢餓過…', '我從來沒感到如此飢餓過…', 28153),
(158124, 'zhTW', '勇士，你在庫爾提拉斯的行動對我們非常重要。聯盟必須團結，才能更加強大。', '', 28153),
(158123, 'zhTW', '為了聯盟！', '', 28153),
(158122, 'zhTW', '那些之後再說吧。你激勵了身邊許多人，英雄，我衷心感謝你。', '', 28153),
(158121, 'zhTW', '聯盟還是需要仰仗你的力量。看來，除非破壞大酋長和贊達拉之間的盟約，否則我們不可能徹底擊敗他們。我們總有一天…會成功的。', '', 28153),
(158120, 'zhTW', '我很想說一切都結束了，不過眼前還有很多事得努力，接下來的日子可能會更黑暗…就像黎明前的夜晚。', '', 28153),
(158119, 'zhTW', '勇士，長久以來，你一直都是我們對抗強敵的先鋒，而且即使面對部落的時候，你依然心懷勇氣…與榮耀。', '', 28153),
(158118, 'zhTW', '', '為了部落！', 28153),
(158117, 'zhTW', '', '你就是部落最強大的戰士。我相信你會把波拉勒斯化為一片火海。', 28153),
(158116, 'zhTW', '', '聯盟的軍力集中在庫爾提拉斯了。那些虛有其表的海軍回來後，他們的膽子就更大了。不過，那群水裡的雜種很快就會付出代價。', 28153),
(158115, 'zhTW', '', '雖然還沒贏得戰爭，但是我們勝利在望。在那個小國王的渺茫希望灰飛煙滅之前，我們絕對不能鬆懈。', 28153),
(158114, 'zhTW', '', '勇士，世界上自稱士兵的人很多，但是能真正上戰場的人並不多，而你似乎特別擅長打仗。', 28153),
(158113, 'zhTW', '', '奪走他們的希望，拿下我們的勝利。為了部落！', 28153),
(158112, 'zhTW', '', '利用你在庫爾提拉斯建立的據點，削弱那位小國王的兵力。動搖他們的信心，粉碎他們努力的成果。', 28153),
(158111, 'zhTW', '', '但是勝利，不僅需要增強我們的力量，也需要不時打擊我們的敵人，直到他們跪地求饒。', 28153),
(158110, 'zhTW', '', '而我認為，你是拉攏贊達拉為我們效力的不二人選。', 28153),
(158109, 'zhTW', '', '勇士，塔蘭姬公主找我們幫忙的時候，我就發現這是一個好機會，能把贊達拉的力量納為己用。', 28153),
(158108, 'zhTW', '連這裡的土地都死了。太可怕了，夥計。實在太可怕了。', '', 28153),
(158107, 'zhTW', '', '烤暖雙手，舒展痠痛吧，$c。', 28153),
(158106, 'zhTW', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t %s開始施放|cFFFF0000|Hspell:273361|h[黑暗之池]|h|r！', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t %s開始施放|cFFFF0000|Hspell:273361|h[黑暗之池]|h|r！', 28153),
(158105, 'zhTW', '$n，歡迎來到疾風哨站。本哨站聽候差遣。', '', 28153),
(158104, 'zhTW', '我應該…加買…保固才對…', '', 28153),
(158103, 'zhTW', '歡迎來到加里維克斯的疼痛宮殿，你這骯髒的小偷！', '', 28153),
(158102, 'zhTW', '讓弗茲魯克去攻擊亞格洛克。', '讓弗茲魯克去攻擊亞格洛克。', 28153),
(158101, 'zhTW', '腐化擴散的速度比我想像的還要快上許多…', '', 28153),
(158100, 'zhTW', '這些孢子不太尋常。一定要找出它們的來源。', '', 28153),
(158099, 'zhTW', '我們已經盡力了。希望他們能好好安息。', '', 28153),
(158098, 'zhTW', '靈魂躁動不安，我們必須終結他們的痛苦。', '', 28153),
(158097, 'zhTW', '', '做得好。希望靈魂能夠安息了。', 28153),
(158096, 'zhTW', '', '靈魂騷動不休，讓他們安息。', 28153),
(158095, 'zhTW', '', '有了這些孢子，我們就可以找到腐化的根源，想辦法摧毀腐化。', 28153),
(158094, 'zhTW', '', '腐化擴散很快。我們必須阻止腐化。收集這些孢子，才能開始研究。', 28153),
(158093, 'zhTW', '各位兄弟姐妹！部落強行進軍黑海岸！急彎河需要大家的支援！', '', 28153),
(158092, 'zhTW', '風之力灌注到你身上！', '風之力灌注到你身上！', 28153),
(158091, 'zhTW', '我要這些金子全部送回宮殿，越快越好，然後　-', '', 28153),
(158090, 'zhTW', '不准拖延！沒有藉口！絕不升職！', '', 28153),
(158089, 'zhTW', '別擋路！聯盟來了！', '', 28153),
(158088, 'zhTW', '我不會死在…哥布林手上。', '', 28153),
(158087, 'zhTW', '聯盟仰賴虛無精靈的力量。我們不會讓你們失望。', '', 28153),
(158086, 'zhTW', '加里維克斯！', '加里維克斯！', 28153),
(158085, 'zhTW', '快跑！是聯盟！', '快跑！是聯盟！', 28153),
(158084, 'zhTW', '', '一定是部落害熊怪無家可歸。', 28153),
(158083, 'zhTW', '', '部落…好多敵人…', 28153),
(158082, 'zhTW', '我的黃金啊！這個精靈是哪裡來的？！', '我的黃金啊！這個精靈是哪裡來的？！', 28153),
(158081, 'zhTW', '', '熊怪他們通常是很和平的，可能是因為失去家園才開始發狂。', 28153),
(158078, 'zhTW', '', '我在暗影中行走。', 28153),
(158077, 'zhTW', '', '馬上做！', 28153),
(158076, 'zhTW', '', '英雄，小心！我們必須低調行事！', 28153),
(158075, 'zhTW', '', '趕快把他殺掉，別讓他們通風報信！', 28153),
(158074, 'zhTW', '', '千萬別被發現！我們不能引起注意…', 28153),
(158073, 'zhTW', '我馬上就下去，蘭法！', '', 28153),
(158072, 'zhTW', '', '你先請。如果你要我打昏誰的話，直接說就好，不過…要小聲一點。', 28153),
(158071, 'zhTW', '哈里納會帶你過去，再回來接我。我一定要去確認我的船員都沒事！', '', 28153),
(158070, 'zhTW', '這樣一來他們應該學到教訓了。下次看看他們乖不乖。', '', 28153),
(158069, 'zhTW', '那些臭矮人就是學不到教訓。這裡不歡迎他們，去讓他們知道贊達拉人是怎麼對付入侵者的。', '', 28153),
(158068, 'zhTW', '要是有人翻過這道山嶺，就殺了他們！', '', 28153),
(158067, 'zhTW', '等我們毀掉他們的艦隊，就能拿下贊達拉了！', '', 28153),
(158066, 'zhTW', '把柱子豎起來！', '', 28153),
(158065, 'zhTW', '<稍待片刻，讓吉恩在一幕帥氣的過場動畫中說服凱瑟琳>', '<稍待片刻，讓吉恩在一幕帥氣的過場動畫中說服凱瑟琳>', 28153),
(158064, 'zhTW', '庫爾提拉斯的人民很團結，但是領導階層就不是了，而且聯盟也少了我們最有力的領導者之一。\n\n我希望有天能消除這些嫌隙。', '', 28153),
(158063, 'zhTW', '到普勞德摩爾城堡的家族紀念碑找我。要是運氣不錯的話，我們也許可以說服普勞德摩爾總帥取消對女兒的懲罰。', '', 28153),
(158062, 'zhTW', '勇士，你讓庫爾提拉斯重新團結起來，還說服他們加入了聯盟的行列。或許你還能幫個忙，讓一對母女重歸於好。', '', 28153),
(158061, 'zhTW', '切斷部落的補給線，減緩了他們的進攻。你為我們爭取到寶貴的時間。', '', 28153),
(158060, 'zhTW', '可惡的哥布林正在鑽井補充戰鬥機器的燃料！別讓他們繼續褻瀆這個地方！', '', 28153),
(158059, 'zhTW', '', '火焰旺盛燃燒，我們繼續前進。', 28153),
(158058, 'zhTW', '', '這些元素生物可以變成石毀車的燃料。殺死它們。如果有卡多雷想阻止你，就一併處理掉。', 28153),
(158057, 'zhTW', '我們可以取道虛無來節省時間。跟我來吧。', '', 28153),
(158056, 'zhTW', '加里維克斯可油滑了。他是不會在公開場合待太久的。', '', 28153),
(158055, 'zhTW', '我早該知道像加里維克斯這樣的哥布林無法抗拒掠奪一座貨真價實的黃金之城的機會。', '', 28153),
(158054, 'zhTW', '', '我們被發現了！把能帶的艾澤萊晶岩都帶走，盡快離開這裡！', 28153),
(158053, 'zhTW', '', '我的天啊…那是艾澤萊晶岩！而且到處都是！', 28153),
(158052, 'zhTW', '這裡到處都有艾澤萊晶岩冒出來。', '這裡到處都有艾澤萊晶岩冒出來。', 28153),
(158051, 'zhTW', '<把你的手放在艾澤萊晶岩上。>', '<把你的手放在艾澤萊晶岩上。>', 28153),
(158050, 'zhTW', '<艾澤萊晶岩礦點因充滿能量而發出低鳴>。', '', 28153),
(158049, 'zhTW', '', '伐木機交給你，我去對付入侵林地的傢伙！', 28153),
(158048, 'zhTW', '古樹之林！天啊…', '古樹之林！天啊…', 28153),
(158047, 'zhTW', '交給我！', '交給我！', 28153),
(158046, 'zhTW', '小心熊怪。他們突然成群結隊出現。', '小心熊怪。他們突然成群結隊出現。', 28153),
(158045, 'zhTW', '我來了！', '我來了！', 28153),
(158044, 'zhTW', '熊怪好像特別暴躁…', '熊怪好像特別暴躁…', 28153),
(158043, 'zhTW', '|TInterface\\Icons\\INV_misc_boilingblood:20|t%s的|cFFFF0000|Hspell:271224|h[血漿噴發]|h|r鎖定你了！', '', 28153),
(158042, 'zhTW', '別小看你所做的事情。他們每次戰敗，都要花點時間重整旗鼓，我們就能乘機鞏固自己打下的根基。', '', 28153),
(158041, 'zhTW', '部落想要在這裡站穩腳步。勇士！讓他們知道什麼叫做想都別想！', '', 28153),
(158040, 'zhTW', '', '那群幼獸活下來了。做得好。', 28153),
(158039, 'zhTW', '', '有群相當特殊的幼獸急需援手。快點去幫牠們，才能贏得剛克的青睞。', 28153),
(158038, 'zhTW', '也就是說，我們要對付的敵人變少了。做得很好。', '', 28153),
(158037, 'zhTW', '', '贊達拉永垂不朽！', 28153),
(158036, 'zhTW', '', '幸好有我身邊這位部落英雄，要不然我們的損失會更加慘重。$b這正是贊達拉必須適應、進化、再度回歸這個世界的鐵證。', 28153),
(158035, 'zhTW', '', '讓這柄長刃時時提醒我們，不管倒下多少次，不管被擊敗多少次，我們都是贊達拉！$b我們會適應，找出生存的方法！', 28153),
(158034, 'zhTW', '', '我們無數的兄弟姐妹，也因為他的暴行而喪失性命。', 28153),
(158033, 'zhTW', '', '看哪！這是古翰的鮮血。沙德拉、希爾雷克、托加、還有…還有瑞贊的死亡都跟他脫不了關係。', 28153),
(158032, 'zhTW', '根據我們的斥候回報，部落的戰艦已經離開海岸了。看來他們的援軍並沒有上岸。', '', 28153),
(158031, 'zhTW', '', '可是那不是我的功勞。', 28153),
(158030, 'zhTW', '勇士，在這片土地上，沒有什麼是理所當然的。謝謝你讓我們的斥候能夠活久一點。', '', 28153),
(158029, 'zhTW', '舉起你的武器，這是人民需要的象徵。', '', 28153),
(158028, 'zhTW', '當人民需要領袖的時候，你付諸行動。此刻，你的人民非常需要一位受人愛戴的領袖。', '', 28153),
(158027, 'zhTW', '你違背你父王的意思，把勇士帶到這裡來。其他人還渾然不知，你就察覺了古翰的秘密。', '', 28153),
(158026, 'zhTW', '軍情七處派了一組人到這個區域，不過我們還沒收到他們的任何消息。去了解原因，幫忙處理一下。', '', 28153),
(158025, 'zhTW', '告訴他們，贊達拉的領袖。舉起武器讓他們知道誰會保護這片土地。讓他們安心。', '', 28153),
(158024, 'zhTW', '', '沃金，你聽得見的話，請你現身吧。', 28153),
(158023, 'zhTW', '部落要為他們想佔領的每一寸土地付出血淋淋的代價。就算是小小的勝利，累積起來也能為我們帶來優勢。做得很好。', '', 28153),
(158022, 'zhTW', '絕望…好絕望。有好多無人指引的亡者，好多需要伸張正義的亡者。古翰卻奪走他們的希望。', '', 28153),
(158021, 'zhTW', '部落以為他們可以隨心所欲控制這個區域。勇士，讓他們知道聯盟不是好惹的。', '', 28153),
(158020, 'zhTW', '', '安靜。', 28153),
(158019, 'zhTW', '我聽見了！', '', 28153),
(158018, 'zhTW', '絕望…', '', 28153),
(158017, 'zhTW', '', '森金之子沃金啊，請聆聽你朋友與家人的聲音，他們想知道你在哪裡。', 28153),
(158016, 'zhTW', '放置艾澤萊晶岩', '放置艾澤萊晶岩', 28153),
(158015, 'zhTW', '你必須保護古樹之林！', '你必須保護古樹之林！', 28153),
(158014, 'zhTW', '保持警戒。', '保持警戒。', 28153),
(158013, 'zhTW', '<扶他站起來。>', '<扶他站起來。>', 28153),
(158012, 'zhTW', '老實說…我還有更狼狽的時候。\n\n但這也差不多了。', '', 28153),
(158011, 'zhTW', '', '英雄，古樹在呼喚了！你先去森林尋找利爪德魯伊，然後再到古樹之林跟我碰面。', 28153),
(158009, 'zhTW', '', '這幫我們爭取到喘息的空間。哨兵，堅守前線！', 28153),
(158008, 'zhTW', '', '我沒看到你說的那個人。我猜你朋友大概是被海妖的聲音迷走了。', 28153),
(158007, 'zhTW', '<問她有沒有看到弗林。>', '<問她有沒有看到弗林。>', 28153),
(158006, 'zhTW', '沒了？你是什麼意思，沒了？我要求賠償！', '沒了？你是什麼意思，沒了？我要求賠償！', 28153),
(158005, 'zhTW', '', '你不是唯一向軍情七處要求看檔案的人。', 28153),
(158004, 'zhTW', '一位戰功彪炳的精靈將軍，怎麼會注意到我這種人？', '', 28153),
(158003, 'zhTW', '', '基沙恩，你有你當英雄的方式，像是你打過三場大戰，還有你在赤脊山的英勇表現。', 28153),
(158002, 'zhTW', '就我看來，我只勉強配在旁邊服侍你。我至少能做的是保持安靜並對你表達敬意。', '', 28153),
(158001, 'zhTW', '女士，我在軍情七處的檔案上讀到過你。你已經活了一萬年，打過的仗我數也數不清。', '', 28153),
(158000, 'zhTW', '', '基沙恩，你在我們身邊是可以放鬆的。', 28153),
(157999, 'zhTW', '她說她應該去殺聯盟，而不是做這些無聊事。我知道在那之後我就應該要離開，而不是繼續交換故事。', '', 28153),
(157998, 'zhTW', '你要找的這個艾瑞依爾在亡者之城，那裡還有著成千上萬的部落大軍！她似乎收到了什麼讓她憂心的情報。', '', 28153),
(157997, 'zhTW', '這一定會很有趣！我會把你需要知道的告訴你，然後你把你的作戰經驗告訴我。', '', 28153),
(157996, 'zhTW', '', '我已經活了一萬年，參與過每一場戰爭。我親眼見過第一座永恆之井。', 28153),
(157995, 'zhTW', '我打過三場大戰，多次淪為野蠻獸人的囚犯但活了下來，我還協助殺過一隻黑龍。', '', 28153),
(157994, 'zhTW', '這個故事真好！我原本是要聽托加說偉大的故事的，可是他死了。你還有好故事嗎？', '', 28153),
(157993, 'zhTW', '我們剛剛救了你的命。你還想怎麼樣？', '', 28153),
(157992, 'zhTW', '噢，沒問題，我可以告訴你部落的一切。但我需要你給我點回報。', '', 28153),
(157991, 'zhTW', '謝謝你，女士。', '', 28153),
(157990, 'zhTW', '', '$n、基沙恩，謝謝你們的協助。我得立刻出發，繼續去獵殺德萊芬。願伊露恩照亮你們的道路。', 28153),
(157989, 'zhTW', '快去！側翼交給我！', '', 28153),
(157988, 'zhTW', '', '$n、基沙恩，來吧，我們回勝利堡去…我要好好安葬我的朋友。', 28153),
(157987, 'zhTW', '', '基沙恩，不論精靈還是人類，我們都是平等的。沒有誰比誰的命更寶貴。', 28153),
(157986, 'zhTW', '我…很快就可以恢復…但不該是我活下來，你的朋友才該活著。', '', 28153),
(157985, 'zhTW', '', '基沙恩！讚美伊露恩，至少有人活過了這場屠殺！', 28153),
(157984, 'zhTW', '<咳咳>女士…我還…沒死。看來…少了那些爪牙…他的力量就沒那麼強。', '', 28153),
(157983, 'zhTW', '', '法理雅…艾歐琳…賴莉亞絲…基沙恩…$n，我發誓，德萊芬一定會付出代價！', 28153),
(157982, 'zhTW', '啊！', '', 28153),
(157981, 'zhTW', '珊蒂斯‧羽月，我不會退讓步。你會看到你的盟友有多弱！', '', 28153),
(157980, 'zhTW', '我們趕快走吧。這些靈魂可以自己找到伯昂撒姆第。', '', 28153),
(157979, 'zhTW', '我知道那些鮮血食人妖一定會回來。但現在知道我們也會去他們老家找他們算帳，不太敢輕舉妄動了。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157978, 'zhTW', '', '珊蒂斯，你走…不要管我…', 28153),
(157977, 'zhTW', '我先去偵察，想辦法弄到一個安全的會合點。等你忙完就來村莊外找我。', '', 28153),
(157976, 'zhTW', '接受我為你帶來的死亡吧，夜精靈！', '', 28153),
(157975, 'zhTW', '就讓你看看我這可悲的人類的本事！', '', 28153),
(157974, 'zhTW', '', '解除護盾！把握機會！激流堡會是我們的！', 28153),
(157973, 'zhTW', '', '所有砲台…發射！', 28153),
(157972, 'zhTW', '', '嗯？', 28153),
(157971, 'zhTW', '他們當然會讓我們回去拿回貴重物品。我是說，一旦煙霧消散。', '他們當然會讓我們回去拿回貴重物品。我是說，一旦煙霧消散。', 28153),
(157970, 'zhTW', '我們過去擁有的一切都在那永恆樹枝裡!', '我們過去擁有的一切都在那永恆樹枝裡!', 28153),
(157969, 'zhTW', '你們會後悔當初沒有死在達納蘇斯的烈焰中！', '', 28153),
(157968, 'zhTW', '珊蒂斯‧羽月，竟然想埋伏我？真有膽量。', '', 28153),
(157967, 'zhTW', '或許我該先拿可悲的人類來殺雞儆猴。', '', 28153),
(157966, 'zhTW', '', '德萊芬，殺戮就到此為止。', 28153),
(157965, 'zhTW', '我到底得殺多少你們這種人，你們才懂得別來礙事？', '', 28153),
(157964, 'zhTW', '聯盟。我知道你們不夠聰明，沒有從我們上一次的交手學到教訓。', '', 28153),
(157963, 'zhTW', '看來該是把弱的戰鬥蜘蛛淘汰，然後讓強的戰鬥蜘蛛上場的時候了。', '', 28153),
(157962, 'zhTW', '一個人，三隻蜘蛛，總共26隻腳，你們一點機會也沒有。', '', 28153),
(157961, 'zhTW', '一個倒下時，另一個會取代牠的位置！', '', 28153),
(157960, 'zhTW', '小傢伙，別緊張。你能幫我們嗎？', '小傢伙，別緊張。你能幫我們嗎？', 28153),
(157959, 'zhTW', '<弗利卡警戒地盯著你>\n\n弗利卡？', '', 28153),
(157958, 'zhTW', '對，沒錯。我們超厲害！來一場吧！', '', 28153),
(157957, 'zhTW', '我準備好要殺死德萊芬和他的追隨者了。', '我準備好要殺死德萊芬和他的追隨者了。', 28153),
(157956, 'zhTW', '你好啊，我是疫病防治的戴伯特‧麥克林。我隨時樂意和蜘蛛同好來場對戰。', '', 28153),
(157955, 'zhTW', '看來我們是拿來引一群飢腸轆轆的吸血精靈的餌了。準備好迎接再下來要發生的事了嗎？', '', 28153),
(157954, 'zhTW', '', '我去警告其他人，基沙恩會在隧道和你碰頭。', 28153),
(157953, 'zhTW', '', '做得很好！接下來交給我們就可以了。', 28153),
(157952, 'zhTW', '', '部落打過來了！他們在建立基地，快用你的靈龍把他們全都擊退！', 28153),
(157951, 'zhTW', '你可能會穿過附近的這顆樹叢，認為蜘蛛不喜歡待在露天空間吹風，但其實，蜘蛛在這方面和你我一樣。再說，一看到蜘蛛網就知道一定有蜘蛛。', '', 28153),
(157950, 'zhTW', '', '我會在佐巴爾遺跡外圍和你會合。你小心。', 28153),
(157949, 'zhTW', '啊，狩獵總是這麼刺激。跟我一樣好好地享受吧。', '', 28153),
(157948, 'zhTW', '', '讓疲憊獲得休息，飢餓獲得飽足。', 28153),
(157947, 'zhTW', '沒問題，公主。', '', 28153),
(157946, 'zhTW', '', '好。我先回祖達薩。保持聯絡，向我回報部落在納茲米爾的各種行動。洛克漢，萬事小心。', 28153),
(157945, 'zhTW', '希瓦娜斯想要給他們一個機會。他們無家可歸了。如果他們可以和我們合作，就讓他們加入部落。不行的話，就除掉。', '', 28153),
(157944, 'zhTW', '這隻該死的鳥在海上肆虐，牠會攻擊我們派去庫爾提拉斯的船隻。殺了這隻鳥。', '', 28153),
(157943, 'zhTW', '', '洛克漢，我沒辦法信任這個德萊芬。我們不該跟煞婪一族打交道，尤其是現在這種混亂時刻。', 28153),
(157942, 'zhTW', '…好，我就暫時聽從你的命令。我們會清空這條隧道，讓你們的部隊能夠出動。', '', 28153),
(157941, 'zhTW', '因為你和希瓦娜斯的約定當中包括要尊敬部落的領導人，而且兄弟，我的階級比你高。', '', 28153),
(157940, 'zhTW', '你要我們用我們的能力…移動岩石。食人妖，為什麼我要聽你的？', '', 28153),
(157939, 'zhTW', '有條塌陷的隧道連結納茲米爾和沃魯敦。帶著你的跟隨者去清掉碎石，然後我們就可以直接攻打聯盟的主力。', '', 28153),
(157938, 'zhTW', '', '南方有個崩塌的通道，連結了納茲米爾跟沃魯敦。把通道打通，部落就能直接攻擊沃魯敦的聯盟營地。', 28153),
(157937, 'zhTW', '希瓦娜斯會很生氣的。德萊芬親王，我們必須迅速阻止聯盟。', '', 28153),
(157936, 'zhTW', '這可以說是我的特長之一。聯盟在亡者之城擾亂部落大軍，趁機殺了艾瑞依爾。', '', 28153),
(157935, 'zhTW', '', '德萊芬親王，請稱呼我塔蘭姬「公主」。還有你怎麼知道這件事？', 28153),
(157934, 'zhTW', '塔蘭姬，遊俠隊長艾瑞依爾殉職了。', '', 28153),
(157933, 'zhTW', '', '那她為什麼沒有來？太忙了，沒空來報告嗎？', 28153),
(157932, 'zhTW', '艾瑞依爾同時對付聯盟和鮮血食人妖，還幫我們在亡者之城建立基地。', '', 28153),
(157931, 'zhTW', '', '洛克漢，很抱歉我來遲了。告訴我目前的狀況，這個艾瑞依爾隊長真的很能幹嗎？', 28153),
(157930, 'zhTW', '公主，謝謝你從贊達拉遠道而來。我們一直在這裡努力抵抗鮮血食人妖和聯盟的入侵者。', '', 28153),
(157929, 'zhTW', '', '$n，歡迎你！這個哨站聽候你的差遣。', 28153),
(157927, 'zhTW', '我願意為你效勞。', '', 28153),
(157926, 'zhTW', '(喝下隱形藥劑。)', '(收下隱形藥劑。)', 28153),
(157925, 'zhTW', '', '別被發現。我們只要一個人進去就好。我會留在這裡，確保沒有人發現我們在做什麼。\n\n我有一瓶隱形藥水，你可以用來潛入那裡。你的行蹤會完全隱匿…但時間有限。\n\n喝下藥水，然後潛入廢墟。找出部落在計劃什麼，然後快點出來。', 28153),
(157924, 'zhTW', '我擔心即使在小型戰鬥中獲得勝利，也無法改變最後的定局。', '', 28153),
(157923, 'zhTW', '我們把部落趕回去了，不過他們已經注意到海岸邊的艾澤萊晶岩。我們不能讓他們得逞。', '', 28153),
(157920, 'zhTW', '親愛的，靠近一點。翁嘉雖然看不見，但是聽得到！呵呵呵！你來找老翁嘉要藥水嗎？', '親愛的，靠近一點。翁嘉雖然看不見，但是聽得到！呵呵呵！你來找老翁嘉要藥水嗎？', 28153),
(157919, 'zhTW', '', '加老大一定會很不開心…', 28153),
(157918, 'zhTW', '', '我要直接把你的嘴巴轟出個大洞！', 28153),
(157917, 'zhTW', '$p，我的同胞準備好了。為了聯盟。', '', 28153),
(157916, 'zhTW', '', '我猜你得和我一組了，$p。我們在聖匣營地會合。', 28153),
(157915, 'zhTW', '戰絲，我們走。', '', 28153),
(157914, 'zhTW', '三場大戰我都打過。我原以為我已經看過艾澤拉斯最慘的禍事。\n\n但我錯了。', '', 28153),
(157913, 'zhTW', '', '我有個東西或許能幫上忙。', 28153),
(157912, 'zhTW', '', '英雄，至於你，快去跟德拉茵‧夏月隊長報告，一定要守住邊境！', 28153),
(157911, 'zhTW', '', '角鷹獸弓箭手，你們跟我來。我們先去洛丹諾集合，組成機動部隊四處警備！', 28153),
(157910, 'zhTW', '', '哨兵們，在急彎河建立戰線！通知我們在古樹之林的盟友！', 28153),
(157909, 'zhTW', '', '獵手們，你們去黑海岸的南端支援！帶上旋刃投擲器！', 28153),
(157908, 'zhTW', '', '我們不能坐以待斃！哨兵，向前！', 28153),
(157907, 'zhTW', '隊長，部落已經打到急彎河了！我們快撐不下去了！', '隊長，部落已經打到急彎河了！我們快撐不下去了！', 28153),
(157906, 'zhTW', '是羊駝！耶！', '', 28153),
(157905, 'zhTW', '你確定嗎？', '你確定嗎？', 28153),
(157904, 'zhTW', '', '遵命！', 28153),
(157903, 'zhTW', '<直接攻擊。>', '<直接攻擊。>', 28153),
(157902, 'zhTW', '給你一點黃金如何？', '給你一點黃金如何？', 28153),
(157900, 'zhTW', '希瓦娜斯想跟我戰鬥，那就如她所願吧。我已經聯絡艦隊了，願伊露恩及時引領他們回來。', '', 28153),
(157899, 'zhTW', '我要拜託你去保護達納蘇斯。', '', 28153),
(157898, 'zhTW', '德拉茵，快去召集每座哨站的士兵，讓他們到這裡集合。', '', 28153),
(157897, 'zhTW', '', '尊師，怎麼辦？', 28153),
(157896, 'zhTW', '女妖之王想要奪走世界之樹。', '', 28153),
(157895, 'zhTW', '', '瑪法里恩！部落軍隊聚集在佐拉姆加前哨站。', 28153),
(157894, 'zhTW', '你可以穿過這道牆，英雄，幽光不會傷害你的。', '', 28153),
(157893, 'zhTW', '', '你在臨終時刻都還看不清人類真正的實力。', 28153),
(157892, 'zhTW', '', '而且你對人類依然抱持著過時的看法。我早該殺了你的。', 28153),
(157891, 'zhTW', '', '我註定要永恆地活下去，我不會死在這裡！', 28153),
(157890, 'zhTW', '', '珊蒂斯，你竟然甘願與骯髒的人類並肩作戰！他們短命又微不足道。', 28153),
(157889, 'zhTW', '', '珊蒂斯，已經過了…兩、三千年了？我們竟然會在這種情況下重逢，而你竟然會甘願協助人類。', 28153),
(157888, 'zhTW', '', '黑暗…希瓦娜斯…這是你看到的嗎…這就是你希望為我們擋下的命運？', 28153),
(157887, 'zhTW', '', '我原本以為這只是單純的偵察任務。我可以好好玩玩了！', 28153),
(157886, 'zhTW', '', '…結束了。等你準備好了，找出她的計畫，然後返回瑞德菲爾德哨站。', 28153),
(157885, 'zhTW', '|cFF0000FF(任務)|r航向祖達薩的席帕拉。', '|cFF0000FF(任務)|r航向祖達薩的席帕拉。', 28153),
(157884, 'zhTW', '做得好！把這個怪物解決了，我們的部隊就可以安然通過這個區域了。', '', 28153),
(157883, 'zhTW', '只有真正的鐵潮才配喝蘭姆酒。快放手！', '只有真正的鐵潮才配喝蘭姆酒。快放手！', 28153),
(157882, 'zhTW', '在沼澤建立補給線已經很不容易了，還多了一個魔法怪物的問題。想辦法消滅牠，開一條路出來。', '', 28153),
(157881, 'zhTW', '', '好極了！那個生物不會再阻礙我們了。', 28153),
(157880, 'zhTW', '', '這個生物吞食黑暗魔精！該送牠的靈魂去找伯昂撒姆第了。', 28153),
(157879, 'zhTW', '', '又是一場勝利。', 28153),
(157878, 'zhTW', '你必須學會打擾伯昂撒姆第是要付出代價的！你們何不快點離開呢？', '', 28153),
(157877, 'zhTW', '', '根據斥候回報，黑海岸突然冒出一大片艾澤萊晶岩。去幫哥布林盟友把那些晶岩娶回來。', 28153),
(157876, 'zhTW', '別太靠近伯昂撒姆第！', '別太靠近伯昂撒姆第！', 28153),
(157875, 'zhTW', '耳朵嗎？$B$B嗯，這很明顯就是時尚。', '', 28153),
(157874, 'zhTW', '猴人小偷！最好別讓我發現蘭姆酒不見了。', '猴人小偷！最好別讓我發現蘭姆酒不見了。', 28153),
(157873, 'zhTW', '沒用的污穢老鼠，不要再喝蘭姆酒了！', '沒用的污穢老鼠，不要再喝蘭姆酒了！', 28153),
(157872, 'zhTW', '我們的第一要務是阻止部落跟贊達拉結盟，因此我們必須先在敵人的地盤建立灘頭堡。', '', 28153),
(157871, 'zhTW', '該讓部落見識一下第七軍團的厲害了。', '', 28153),
(157870, 'zhTW', '', '士兵…不、別衝過去…！', 28153),
(157869, 'zhTW', '呃，機器開了嗎？麥克風試音，好。', '', 28153),
(157868, 'zhTW', '哈哈，看他們抱頭鼠竄的模樣！他們的部隊還要好一陣子才能行動了。做得好。', '', 28153),
(157867, 'zhTW', '我們搶到部落的另一個攻城武器了。現在該輪到他們自食惡果啦！', '', 28153),
(157866, 'zhTW', '天啊！怎麼可能，老大一定會不高興的，老伯昂撒姆第很久沒有弄丟靈魂了…真是糟透了。', '', 28153),
(157865, 'zhTW', '你說沃金？東西快拿過來。等等…等等等等…天啊！在哪裡？沃金的靈魂跑到哪去了？', '', 28153),
(157864, 'zhTW', '英雄，退下吧，這邊沒你的事了。', '', 28153),
(157863, 'zhTW', '幸好工人都不在意我們到處打探，只有公司的走狗會在意。\n\n你找到我們需要的東西了？', '', 28153),
(157862, 'zhTW', '今天在這裡完成了不少事。我們外頭見吧。', '今天在這裡完成了不少事。我們外頭見吧。', 28153),
(157861, 'zhTW', '', '一定要阻止賈克拉傑！', 28153),
(157860, 'zhTW', '為什麼國王會在我們自己的家園裡？', '為什麼國王會在我們自己的家園裡？', 28153),
(157859, 'zhTW', '暴風城的資源很吃緊，不夠我們存活。', '暴風城的資源很吃緊，不夠我們存活。', 28153),
(157858, 'zhTW', '不行不行，小英雄啊，你還不能離開這裡喔。', '', 28153),
(157857, 'zhTW', '太好了！又少了一個要擔心的禍害。', '', 28153),
(157856, 'zhTW', '比起在廢墟上戰鬥，聯盟應該奪回我們的故土！', '比起在廢墟上戰鬥，聯盟應該奪回我們的故土！', 28153),
(157855, 'zhTW', '這是我們失去的第二個家園。', '這是我們失去的第二個家園。', 28153),
(157854, 'zhTW', '我們現在該去哪裡？', '我們現在該去哪裡？', 28153),
(157853, 'zhTW', '很好，少了這隻野獸，我們的後代就能安心成長。', '', 28153),
(157852, 'zhTW', '這事牽連重大，將軍。我們必須依此情報應變。', '', 28153),
(157851, 'zhTW', '', '我們不能讓那頭怪物逃走，龍禍。', 28153),
(157850, 'zhTW', '暗矛食人妖不行！食人妖聖所不歡迎愚笨的食人妖！', '', 28153),
(157849, 'zhTW', '骯髒的部落不配到這裡來。我們沙怒要挑戰你！', '骯髒的部落不配到這裡來。我們沙怒要挑戰你！', 28153),
(157848, 'zhTW', '', '感謝你，艾蘭里亞。我們很歡迎你的協助。', 28153),
(157847, 'zhTW', '一項睿智的戰略。我認同。', '', 28153),
(157846, 'zhTW', '', '我們會找到他，然後把他的頭帶給你。而珊蒂斯則繼續專注追蹤血紅親王。', 28153),
(157845, 'zhTW', '', '我的虛無精靈可以幫忙解決加里維克斯。', 28153),
(157844, 'zhTW', '', '艾蘭里亞在她背後開啟了一道虛無傳送門。', 28153),
(157843, 'zhTW', '', '我們絕不能放這兩個目標逃走…而且我們也不需要。', 28153),
(157842, 'zhTW', '', '抱歉我打個岔，但我相信你們兩個都是對的。', 28153),
(157841, 'zhTW', '', '你看過德瑞文的能耐，龍禍。要是有更多像他一樣的人怎麼辦？', 28153),
(157840, 'zhTW', '就戰術上來說，他是最薄弱的環節。這是個千載難逢的機會。我們必須立刻攻擊。', '', 28153),
(157839, 'zhTW', '加里維克斯資助部落的戰爭，也是他們的領袖之中最了解艾澤萊晶岩的人。', '', 28153),
(157838, 'zhTW', '', '我們隨時都能宰了那個貪吃的哥布林！如果德瑞文逃走，我們可能永遠都找不到他了。', 28153),
(157837, 'zhTW', '我們很快就會處裡掉血紅親王德瑞文，將軍。但這是癱瘓部落軍隊的難得機會。其他事務必須先擱置。', '', 28153),
(157836, 'zhTW', '有頭長著翅膀的野獸把我的手下餵給幼獸了！用手上的武器賞牠們一頓大餐吧！', '', 28153),
(157835, 'zhTW', '你不能將那與部落友好的叛徒帶到這神聖的地方來！', '', 28153),
(157834, 'zhTW', '', '我們的盟友正等待你的命令。', 28153),
(157833, 'zhTW', '偉大的帕骷已經做出決定，吉亞拉克活得夠久了。去召集你的部隊，殺掉那隻生物。', '', 28153),
(157832, 'zhTW', '歡迎，勇士。我們還有事情要做。', '', 28153),
(157831, 'zhTW', '那是…血嗎？真的？你是說有一頂血盾在保護那東西？\n\n好…現在我真的再看到什麼都不希奇了。', '', 28153),
(157830, 'zhTW', '', '法陣是我們的！所有人就戰鬥位置！', 28153),
(157829, 'zhTW', '將會有更多的戰爭等著我。', '', 28153),
(157828, 'zhTW', '就算我們倒下，聖光依舊長存。肖爾，這場戰爭結束之後，你還有其他的目標嗎？', '', 28153),
(157827, 'zhTW', '是對聖光的信仰？還是對圖拉揚？', '', 28153),
(157826, 'zhTW', '正好相反。親眼見到圖拉揚歸來，看到聖光是如何鼓舞他、改變他之後，我的信念變得更加堅定，我知道我的信仰是對的。', '', 28153),
(157825, 'zhTW', '你發現圖拉揚還活著的時候，有質疑過自己做出的犧牲與決定嗎？', '', 28153),
(157824, 'zhTW', '他和聯盟遠征軍前往外域、並且渺無音訊的時候…聖光啟發了我，我知道我能夠以聖騎士的身份踏上戰場。我誓言要為他的犧牲而戰。', '', 28153),
(157823, 'zhTW', '但是我觀察了最初的幾位聖騎士，其中一人激勵了我…就是圖拉揚，他信仰堅定、忠貞不渝，成為了一名偉大的領袖。', '', 28153),
(157822, 'zhTW', '卓坎躺下來休息。', '', 28153),
(157821, 'zhTW', '白銀之手創立的時候，我還是一名騎士。那時我很懷疑信仰的教條能否結合軍事技巧，所以我只著重於自己的戰鬥能力。', '', 28153),
(157820, 'zhTW', '龍禍，像你這樣的聖騎士，怎麼會跑來指揮菁英軍團呢？你不是應該待在聖殿為聖光奉獻之類的嗎？', '', 28153),
(157819, 'zhTW', '喔，那當然。', '', 28153),
(157818, 'zhTW', '謝謝你的讚美。但是如果要在自身榮譽與任務之間做出選擇，我還是會以任務為重。當然，這一切都是為了聯盟。', '', 28153),
(157817, 'zhTW', '我得承認，身為聖騎士，我一直懷疑聯盟是否需要間諜跟刺客。但是你們對國王展現出來的忠誠和榮譽之心，確實毋庸置疑。', '', 28153),
(157816, 'zhTW', '軍情七處做的是機密任務，我比較喜歡待在幕後…讓敵人找不到我。', '', 28153),
(157815, 'zhTW', '我遵從聯盟的命令…以及聖光的指示，早就數不清多少次了。不過，你也不是第一次上戰場。', '', 28153),
(157814, 'zhTW', '龍禍，這是你第幾次參加對抗部落的大型戰役？', '', 28153),
(157813, 'zhTW', '小心別亂揮，$n。', '', 28153),
(157812, 'zhTW', '覺得你應該要知道。', '', 28153),
(157811, 'zhTW', '工坊現在開張了！如果你需要什麼，我們就有能力製作給你！', '', 28153),
(157810, 'zhTW', '對戰牙的傷害，我們將十倍奉還！', '', 28153),
(157809, 'zhTW', '我不再害怕死亡，死亡怕我…', '', 28153),
(157808, 'zhTW', '大酋長一定會懲罰這件事。', '', 28153),
(157807, 'zhTW', '死亡對你來說是太慈悲了點。', '', 28153),
(157806, 'zhTW', '我會將你的屍骸大快朵頤！', '', 28153),
(157805, 'zhTW', '我要把你劈成兩半！', '', 28153),
(157804, 'zhTW', '', '做得好，但我總覺得他們還會再來。', 28153),
(157803, 'zhTW', '', '海盜又來搶守望山丘了！他們什麼時候才會學乖？！幫海軍趕跑海盜吧！', 28153),
(157802, 'zhTW', '感謝你！我必須回去找我的家人。', '感謝你！我必須回去找我的家人。', 28153),
(157801, 'zhTW', '你看到他們的表情了嗎？噢，真是太值得了！這下他們得花好幾天才清得掉了！', '', 28153),
(157800, 'zhTW', '部落是野蠻人！', '部落是野蠻人！', 28153),
(157799, 'zhTW', '這麼邪惡的腐化最好還是趕快淨化…免得影響到部落。', '', 28153),
(157798, 'zhTW', '非常好。深淵在腐化大地，我們決不能袖手旁觀。', '', 28153),
(157797, 'zhTW', '想當年我跟凡瑞克常常揚起帆乘著風，抓幾隻騎乘用的鸚鵡四處搗亂。你要不要也試試看，讓那些海盜知道「正義」從天而降的滋味！', '', 28153),
(157796, 'zhTW', '一蹶不振…', '', 28153),
(157795, 'zhTW', '我…計算錯誤。', '', 28153),
(157794, 'zhTW', '這個怪物是瘋狂跟腐化的化身。快把它消滅掉！', '', 28153),
(157793, 'zhTW', '我只希望我的家人有及時逃出。', '我只希望我的家人有及時逃出。', 28153),
(157792, 'zhTW', '煙霧很濃。要不是葛雷邁恩女王，我們也許已經失去它了。', '煙霧很濃。要不是葛雷邁恩女王，我們也許已經失去它了。', 28153),
(157791, 'zhTW', '我們得把這個怪物打回深海裡去。攻擊牠！', '', 28153),
(157790, 'zhTW', '我們差點無法活著回來。', '我們差點無法活著回來。', 28153),
(157789, 'zhTW', '他們為何要如此做？', '他們為何要如此做？', 28153),
(157788, 'zhTW', '你真是惹我發毛！', '', 28153),
(157787, 'zhTW', '這全部都是我的！', '', 28153),
(157786, 'zhTW', '我會把你鑽成碎片！', '', 28153),
(157785, 'zhTW', '', '普勞德摩爾衛隊差點蒙受巨大損失。幸好有你，這只成了一點小挫折。', 28153),
(157784, 'zhTW', '', '我們有艘補給船在南方潮路觸礁了。大部分的船員都安全逃走，但是沒辦法帶走珍貴的物資。', 28153),
(157783, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t戰爭使者葉南茲開始施放|cFFF00000|Hspell:274932|h[無盡深淵]|h|r！', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t戰爭使者葉南茲開始施放|cFFF00000|Hspell:274932|h[無盡深淵]|h|r！', 28153),
(157782, 'zhTW', '竟然是酒？！我還以為是真的寶藏…可以拿來買酒的那一種！', '', 28153),
(157781, 'zhTW', '自由港一直流傳這樣的故事：有海盜把寶藏藏在港口附近水底。你要不要去找找看！', '', 28153),
(157780, 'zhTW', '很好。只要減少輸入波拉勒斯的艾澤萊晶岩武器數量，我們就有辦法鎮壓艾胥凡的叛亂行動。', '', 28153),
(157779, 'zhTW', '艾胥凡貿易公司一直沒聽從命令，還在繼續製造武器。去把鑄造廠毀了，但小心別傷害一般平民。', '', 28153),
(157778, 'zhTW', '嘿，別擔心，我們會幫這些孩子找到新家。別讓他們流落街頭或受到傷害。', '', 28153),
(157777, 'zhTW', '艾胥凡貿易公司用食物誘拐孤兒，然後逼他們去做苦工。我們必須把孩子們救出來！', '', 28153),
(157776, 'zhTW', '聽說艾索埃瑟斯只要揮揮爪子就能把海怪打出海面。剛剛真的很危險。你能殺掉他真是了不起。', '', 28153),
(157775, 'zhTW', '水手經常吟唱艾索埃瑟斯的傳說，聽說他只要吹口氣就能把戰艦吹翻。這些傳說都是真的。如果你能殺艾索埃瑟斯，水手就會改唱你的傳說。', '', 28153),
(157774, 'zhTW', '', '去找薩魯法爾霸王報到。教訓敵人，讓他們知道愚蠢的代價。為了部落！', 28153),
(157773, 'zhTW', '當我閉上眼睛…我依然能看到熊熊烈火。', '當我閉上眼睛…我依然能看到熊熊烈火。', 28153),
(157772, 'zhTW', '我希望我們的朋友平安無事。', '我希望我們的朋友平安無事。', 28153),
(157771, 'zhTW', '我們不能失去卡林多。', '我們不能失去卡林多。', 28153),
(157770, 'zhTW', '我無法相信世界之樹…沒了…', '我無法相信世界之樹…沒了…', 28153),
(157769, 'zhTW', '那些部落雜種摧毀了我們的家園！', '那些部落雜種摧毀了我們的家園！', 28153),
(157768, 'zhTW', '你要什麼？喔，你看來似乎也是個工程師…', '', 28153),
(157767, 'zhTW', '我想問點別的事情。', '我想問點別的事情。', 28153),
(157766, 'zhTW', '那瘋狂的廚師？他好像是我遠房親戚吧。真是可悲，他能想到的東西就只有炸彈，以及更大的炸彈而已。真正的天才是發明終極的力量泉源，長時間供給機器能源進行割、碎、鑽、或是爆破等工作，持續越久越好。', '', 28153),
(157765, 'zhTW', '你好，博士，我想要購買你其中一個反應爐。你不會後悔的。', '你好，博士，我想要購買你其中一個反應爐。你不會後悔的。', 28153),
(157764, 'zhTW', '你就是，爆爆博士嗎！？', '你就是，爆爆博士嗎！？', 28153),
(157763, 'zhTW', '喔，你認為如此。看來你的確是一名技術優秀的工程師！雖然比起我還差得遠，但能跟我比的確實不多。', '', 28153),
(157762, 'zhTW', '', '我不知道對方是誰，不過，動手殺了她吧！', 28153),
(157761, 'zhTW', '博士，那東西的工程技術真是驚人！', '博士，那東西的工程技術真是驚人！', 28153),
(157760, 'zhTW', '', '所有人回去黑鐵砧！集合後確認傷亡人數！', 28153),
(157759, 'zhTW', '嘿，我正在這工作耶！等你當上工程師，有能夠貢獻給技巧部門的東西時再來吧！', '', 28153),
(157758, 'zhTW', '', '你一下子就解決了，真不錯！我們要開門了，另一頭聽起來有一大群敵人在等我們。提高警覺！', 28153),
(157757, 'zhTW', '我花了過去五年的時間修理、升級、以及調整有史以來最先進而致命的機器人戰隊。想不想看看你那無趣平凡的寵物，對上由宇宙裡最優秀的次等維修技師所製作的寵物時表現如何？', '', 28153),
(157756, 'zhTW', '故障？那是不可能的！', '', 28153),
(157755, 'zhTW', '我的絕頂才智加上我製作出更絕頂的機械，是無敵的組合。', '', 28153),
(157754, 'zhTW', '', '做得好！那個傀儡變成一堆碎石，佐司瓦的居民安全了。', 28153),
(157753, 'zhTW', '', '在附近的山上出現了一個巨大的石頭傀儡！我們必須在它攻擊佐司瓦的居民之前制止它！', 28153),
(157752, 'zhTW', '怎麼可能！下次我要建造更大的機器人。', '', 28153),
(157751, 'zhTW', '沒有寵物能與我的戰隊匹敵，我是無敵的！', '', 28153),
(157750, 'zhTW', '準備面對我這支高度改造過、特製化的無敵機器人戰隊吧！', '', 28153),
(157749, 'zhTW', '我準備好啟程了，奎格瓦。', '我準備好啟程了，奎格瓦。', 28153),
(157748, 'zhTW', '到現在，鮮血食人妖也依然在持續屠殺我的子民。$b$b我會協助你接近他們的領袖，但我必須趕回沼澤保護我的子民。', '', 28153),
(157747, 'zhTW', '奎格瓦，鮮血食人妖的領袖已經逃至遠方的大型建築物了。拜託，請助我們一臂之力。', '奎格瓦，鮮血食人妖的領袖已經逃至遠方的大型建築物了。拜託，請助我們一臂之力。', 28153),
(157746, 'zhTW', '啊…咳咳，凡瑞克，那個我們等下再說啦。今天是來談正事的。', '', 28153),
(157745, 'zhTW', '', '我是來幫忙的，上戰場！', 28153),
(157744, 'zhTW', '', '我為我的人民奮戰。', 28153),
(157743, 'zhTW', '', '不夠看的敵人，立刻將它打發！', 28153),
(157742, 'zhTW', '你記得吧，就是「頭髮比烏鴉的羽毛還亮」的女人。哈哈哈！', '', 28153),
(157741, 'zhTW', '', '紀念達納蘇斯！', 28153),
(157740, 'zhTW', '', '我也非常想要趕快離開這裡。', 28153),
(157739, 'zhTW', '', '我們快點走吧，免得那種…怪物…又出現。', 28153),
(157738, 'zhTW', '', '還好…不礙事。', 28153),
(157737, 'zhTW', '對了，弗林，你一直掛在嘴邊的那個女人後來怎麼樣了？', '', 28153),
(157736, 'zhTW', '', '母親！你還好嗎？', 28153),
(157735, 'zhTW', '', '你能取回那把錘子嗎？它擁有相當強大的力量，如果被哥布林發現要怎麼使用它，對我們可能會是一場災難。', 28153),
(157734, 'zhTW', '', '$n，我有另一項任務給你。這些野蠻人隸屬於風險投資公司。這表示或許就在我們講話同時，他們正前往凱贊，要把反對者交到瑞茲當克老大的手上。', 28153),
(157733, 'zhTW', '', '黑鐵砧之手、暗砧，你們想辦法修復黑鐵砧。', 28153),
(157732, 'zhTW', '', '啊，他們偷走反對者，還把黑鐵砧拆為兩半！', 28153),
(157731, 'zhTW', '', '庫爾提拉斯也不會退讓半步。', 28153),
(157730, 'zhTW', '佐司特…絕不…放棄…', '', 28153),
(157729, 'zhTW', '地獄之鈴啊！', '', 28153),
(157728, 'zhTW', '你們兩個，睜大眼睛！看著黑鐵砧！', '', 28153),
(157727, 'zhTW', '', '地核之火啊！那一定就是撞上我的那具大型機甲！', 28153),
(157726, 'zhTW', '某個拳手偷襲我，偷走了反對者！', '', 28153),
(157725, 'zhTW', '', '我沒事。你自己看起來倒不太好。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157724, 'zhTW', '攝政女王！小姑娘，你還好嗎？', '', 28153),
(157723, 'zhTW', '', '好啦，各位，準備收工了！', 28153),
(157722, 'zhTW', '', '魔物，你們之前是手下敗將，現在還是一樣！', 28153),
(157721, 'zhTW', '瑟洛斯會把你們全部吞噬！我終於可以報仇了！', '', 28153),
(157720, 'zhTW', '', '竟然就在我們情況開始好轉的節骨眼上。', 28153),
(157719, 'zhTW', '', '<茉艾拉喃喃自語。>', 28153),
(157718, 'zhTW', '', '塞林，穿過工匠大廳！他們可能正在前往黑色寶庫。', 28153),
(157717, 'zhTW', '', '勇士，防守黑鐵大道，別被敵人攻破！', 28153),
(157716, 'zhTW', '', '黑鐵砧之手，召集你的巫士進行反擊！', 28153),
(157715, 'zhTW', '', '沒骨氣的綠色廢物想攻擊我們的老家？', 28153),
(157714, 'zhTW', '是哥布林！他們打過來了！', '', 28153),
(157713, 'zhTW', '', '勇士，準備戰鬥！', 28153),
(157712, 'zhTW', '', '魔物，你惹到不該惹的家族了！', 28153),
(157711, 'zhTW', '', '母親！', 28153),
(157710, 'zhTW', '', '母親，小心！', 28153),
(157709, 'zhTW', '', '哇，真是個大傢伙！', 28153),
(157708, 'zhTW', '你們全都別想逃！', '', 28153),
(157707, 'zhTW', '', '女兒，我們走吧。我們想辦法離開這裡。', 28153),
(157706, 'zhTW', '', '又出現更多敵人！', 28153),
(157705, 'zhTW', '', '元素生物來襲！', 28153),
(157704, 'zhTW', '', '我們已發現對艾澤萊晶岩施展強大的魔法可能會出現一些出乎意料的結果。', 28153),
(157703, 'zhTW', '', '珍娜？真的是你嗎？', 28153),
(157702, 'zhTW', '那吝嗇書呆子的意思是，當元素攻擊我們的時候保護我們。', '', 28153),
(157701, 'zhTW', '你們太…遲了…', '', 28153),
(157700, 'zhTW', '$C，我們重塑艾澤萊晶岩一定會產生自發性艾澤萊生成反應，你應付得來嗎？', '', 28153),
(157699, 'zhTW', '介意幫我放更多艾澤萊晶岩到鐵砧上嗎，$n？', '', 28153),
(157698, 'zhTW', '下一個就輪到你了！', '', 28153),
(157697, 'zhTW', '放肆的蠢貨！她已經毀了，你們救不了她！', '', 28153),
(157696, 'zhTW', '遵命，攝政女王。', '', 28153),
(157695, 'zhTW', '', '塞林，索爾加登，好好幹。', 28153),
(157694, 'zhTW', '', '夠了！魔物，現出你的真面目吧！', 28153),
(157693, 'zhTW', '', '他們頗有進展。安杜因每天都會詢問戰情更新，我應該告訴你我們目前獲得的情報。', 28153),
(157692, 'zhTW', '', '自從我們在黑石深淵首次發現艾澤萊晶岩，我就派了最優秀的人去精煉。', 28153),
(157691, 'zhTW', '', '謝謝你趕來，$n。', 28153),
(157690, 'zhTW', '', '爸爸…別再說了…', 28153),
(157689, 'zhTW', '', '我會在山丘上的雕像那邊等你。', 28153),
(157688, 'zhTW', '', '偉大的奎格瓦，我們需要你幫助！', 28153),
(157687, 'zhTW', '就像第三次獸人戰爭一樣。', '', 28153),
(157686, 'zhTW', '為了B連！', '', 28153),
(157685, 'zhTW', '就像在德拉諾一樣！', '', 28153),
(157684, 'zhTW', '讓我回想起第二次獸人戰爭。', '', 28153),
(157683, 'zhTW', '嗯嗯嗯嗯。', '嗯嗯嗯嗯。', 28153),
(157682, 'zhTW', '我們來確認一下殺掉艾瑞依爾隊長的流程。', '我們來確認一下殺掉艾瑞依爾隊長的流程。', 28153),
(157681, 'zhTW', '將軍。', '', 28153),
(157680, 'zhTW', '', '我們現在動身。$n將打先鋒。我們其他人會提供支援並預先探查環境。基沙恩，這也保括你在內。', 28153),
(157679, 'zhTW', '', '如果我們救出托爾托人，應該能換到部落動向的情報，這樣我們應該就能找到艾瑞依爾隊長。', 28153),
(157678, 'zhTW', '女士。納茲米爾裡面有幾名托爾托，而且根據情報，他們會知道部落的動向。其中有些人被鮮血食人妖抓走了。', '', 28153),
(157677, 'zhTW', '就像甕中捉魚一樣簡單！', '就像甕中捉魚一樣簡單！', 28153),
(157676, 'zhTW', '正中紅心！呃，正中魚心！', '正中紅心！呃，正中魚心！', 28153),
(157675, 'zhTW', '', '我們需要情報以及在納茲米爾有盟友協助才能達成此事。很走運地，我們有個機會。基沙恩？', 28153),
(157674, 'zhTW', '', '艾瑞依爾隊長一死，部落在納茲米爾的行動就會癱瘓，並且削弱希瓦娜斯的黑暗遊俠。', 28153),
(157673, 'zhTW', '這些食人妖傷害我的孩子太久了！現在換我獵殺他們了。', '', 28153),
(157672, 'zhTW', '我一直以為亡淘村在另一個方向。', '', 28153),
(157671, 'zhTW', '', '在奈得里消失後，就一直平靜無事。', 28153),
(157670, 'zhTW', '我們必須阻止他們。勇士，召集你的人手。激流堡是聯盟的地盤！', '', 28153),
(157669, 'zhTW', '但是部落正在統整軍隊，打算奪走激流堡。要是他們得手，他們就會在東部王國取得重要的戰略據點。', '', 28153),
(157668, 'zhTW', '在聯盟還是以羅德隆為首的年代，激流堡曾經是軍事重鎮。我們打算讓它恢復往日榮光。', '', 28153),
(157667, 'zhTW', '召集探險隊，出發尋找艾澤萊晶岩…別讓部落搶先一步。', '', 28153),
(157666, 'zhTW', '肖爾的斥候在這片大海的島上找到了艾澤萊晶岩。勇士，聯盟需要那些資源。', '', 28153),
(157665, 'zhTW', '你找來的探員要查明部落的計畫…並且還要確保我們能拿下最後的勝利。', '', 28153),
(157664, 'zhTW', '和馬迪亞斯·肖爾一起，召集機密行動小組。暴風城的間諜大師絕對是這個任務的不二人選。', '', 28153),
(157663, 'zhTW', '勇士，在戰場上，我們必須與敵人正面交鋒。不過有時候，我們也需要一些…巧妙的策略。', '', 28153),
(157662, 'zhTW', '我已準備好召喚奎格瓦。', '我已準備好召喚奎格瓦。', 28153),
(157661, 'zhTW', '', '澤靈正在和他的家人講話。後退點，我們要再看看我需不需要介入。', 28153),
(157660, 'zhTW', '', '讓他們旁敲側擊，暗中找出敵軍防禦的弱點…趁機擊破敵人。', 28153),
(157659, 'zhTW', '', '你去跟迦羅娜‧半血一起召集部落最陰險狡詐的頂尖特務，派他們到庫爾提拉斯和贊達拉執行秘密任務。', 28153),
(157658, 'zhTW', '', '為了確保你能成功，我派了幫手給你，他有一些…特殊的專長，應該能在這次任務中幫上忙。', 28153),
(157657, 'zhTW', '', '你必須儘快行動。利用夜色的掩護，好好搜尋殘骸。聯盟派了不少人巡邏那片水域。', 28153),
(157656, 'zhTW', '', '納薩諾斯，看來你對澤靈修士的轉化有進展了。他透露了那艘沉船的下落。', 28153),
(157655, 'zhTW', '', '現在小國王想派部隊佔領那裡，絕不能讓他們得逞。', 28153),
(157654, 'zhTW', '', '東部王國中央的激流堡，曾經是聯盟的一大重鎮…最後變成了廢墟。', 28153),
(157653, 'zhTW', '', '我們得把握機會。去探索這些島嶼，全部佔領下來…一座都不留給聯盟。', 28153),
(157652, 'zhTW', '', '我們的哥布林盟友又派上了用場。他們在這片廣大海洋的島嶼上面，找到艾澤萊晶岩的分布位置。', 28153),
(157651, 'zhTW', '', '有時候，與其派千軍萬馬到戰場上廝殺，還不如暗中從背後捅人一刀。', 28153),
(157650, 'zhTW', '', '該死的米爾頓霍爾瘋了！酒莊到處都是他的實驗品。拜託你去看看吧，別讓情況失去控制。', 28153),
(157649, 'zhTW', '', '你協助釋放我的組員，為此我感謝你與你的部落。\n\n只要我掌權一天，霧帆就能自由地遨遊七海！', 28153),
(157648, 'zhTW', '', '他把自己當作最後的祭品…我們失敗了。', 28153),
(157647, 'zhTW', '不…不可能！', '', 28153),
(157646, 'zhTW', '但你會的！', '', 28153),
(157645, 'zhTW', '受苦？你還沒見識過什麼才是真正的苦痛呢…還沒…', '', 28153),
(157644, 'zhTW', '泰莉亞，等你有空的時候，來暴風城作客吧。關於你父親，我有好多事情想跟你說。', '', 28153),
(157643, 'zhTW', '', '有一天突然就沒收到信了。我…我有好多問題想問。', 28153),
(157642, 'zhTW', '', '讓他死得痛快一點。我們今天已經看到夠多折磨了。', 28153),
(157641, 'zhTW', '', '「我的小星星。」', 28153),
(157640, 'zhTW', '我想起來了…他以前會寫信給你。他還幫你取了暱稱…', '', 28153),
(157639, 'zhTW', '大領主伯瓦爾是個偉大的人。真正的聯盟英雄…也是我的英雄。', '', 28153),
(157638, 'zhTW', '', '你認識我父親嗎？', 28153),
(157637, 'zhTW', '<賈克拉傑痛苦地呻吟。>', '', 28153),
(157636, 'zhTW', '泰莉亞…請快起來。這是我的榮幸。', '', 28153),
(157635, 'zhTW', '', '她是伯瓦爾的女兒，第三次戰爭以後就交給我們保護、扶養。', 28153),
(157634, 'zhTW', '弗塔根？！', '', 28153),
(157633, 'zhTW', '', '泰莉亞‧弗塔根。', 28153),
(157632, 'zhTW', '', '烏瑞恩國王，能見到你真是我的榮幸。我是泰莉亞。', 28153),
(157631, 'zhTW', '', '她跟你的勇士一樣都是拯救王國的關鍵…她還救了我的命。', 28153),
(157630, 'zhTW', '', '烏瑞恩國王，還要請你見一個人。', 28153),
(157629, 'zhTW', '我很開心，也很榮幸能歡迎庫爾提拉斯返回聯盟。願聖光引導我們邁向勝利。', '', 28153),
(157628, 'zhTW', '', '謝謝你…謝謝大家。我向大家保證，我一定會不負眾望。', 28153),
(157627, 'zhTW', '', '你們願意嗎？', 28153),
(157626, 'zhTW', '', '將軍，一切都結束了。你的陰謀，謊言，和殺戮。', 28153),
(157625, 'zhTW', '', '山繆，不！', 28153),
(157624, 'zhTW', '斯陀頌恩！', '', 28153),
(157623, 'zhTW', '派克，準備迎接自己的死亡吧。我一定會把艦隊獻給我們偉大的女王…艾薩拉。', '', 28153),
(157622, 'zhTW', '我只看到迷失的靈魂，渴望能獲得自由。', '', 28153),
(157621, 'zhTW', '結束了，斯陀頌恩！看看你的周圍…你被包圍了。', '', 28153),
(157620, 'zhTW', '你顯然是個專家。我就知道可以靠你去製造一陣混亂！', '', 28153),
(157619, 'zhTW', '我們的武器說不上厲害，所以只能見機行事。想辦法對敵人造成重創，然後在他們反應過來以前趕快逃走。', '', 28153),
(157618, 'zhTW', '', '誰知道那個東西會造成艦隊多大的傷害？幸好有你，我們永遠也不必知道。', 28153),
(157617, 'zhTW', '', '凱瑟琳，你不配治理這個地方。', 28153),
(157616, 'zhTW', '', '普莉希拉…我剛剛差一點…你怎麼可以背叛王國？你怎麼可以背叛我？', 28153),
(157615, 'zhTW', '', '那個魔像強大到可以把船劈成兩半！絕對不能讓斯陀頌恩領主擁有這麼厲害的武器。', 28153),
(157614, 'zhTW', '', '你雇用了海盜艦隊，給他們大量裝備，然後派海盜艦隊攻擊自己人。', 28153),
(157613, 'zhTW', '', '那是叫艾澤萊晶岩的東西…聯盟跟部落已經為了它交戰不休了。', 28153),
(157612, 'zhTW', '', '摧毀戴林之門所使用的武器，就是你們公司製造的！', 28153),
(157611, 'zhTW', '', '普莉希拉‧艾胥凡女士，我現在以走私、勾結海盜、背叛庫爾提拉斯海軍府等罪名逮捕你。', 28153),
(157610, 'zhTW', '大海給了我們很多，但是藏在深海之中的卻只有絕望。', '', 28153),
(157609, 'zhTW', '', '小女孩，你在胡說什麼？！', 28153),
(157608, 'zhTW', '', '原來你一直都在謀劃這一天。可恥。', 28153),
(157607, 'zhTW', '', '叛徒！', 28153),
(157606, 'zhTW', '有一隻來自深海的遠古怪物出現了，把他打回大海深處去吧。', '', 28153),
(157605, 'zhTW', '', '從我們都失去丈夫的時候開始，艾胥凡女士就一直是我的重要支柱。現在她會成為王國的支柱。從今天起…她就是…', 28153),
(157603, 'zhTW', '', '但這樣還不夠。', 28153),
(157602, 'zhTW', '', '打得漂亮！這樣我們的部隊就不用在海裡戰鬥了。', 28153),
(157601, 'zhTW', '我上次看到這麼多煙，應該是達文波特奶奶在教她那個白癡孫子烘焙的時候了。做得好！', '', 28153),
(157600, 'zhTW', '', '你好大膽！', 28153),
(157599, 'zhTW', '', '納迦正在用有生命的攻城機具摧毀堤岸！應戰吧！', 28153),
(157598, 'zhTW', '海盜？！現在普勞德摩爾家族居然連擊退海盜都辦不到了！', '', 28153),
(157597, 'zhTW', '', '海盜艦隊以壓倒性的火力攻擊大門…', 28153),
(157596, 'zhTW', '憤怒的風暴雖然難以捉摸，又藏著重重危險，但是你的力量更加強大。', '', 28153),
(157595, 'zhTW', '這看起來像浪潮賢者的魔法。趕快想辦法阻止它！', '', 28153),
(157594, 'zhTW', '雖然我們對敵人部隊造成了傷害，但是他們重建的速度比我們摧毀的速度更快。一定要切斷敵人的木材來源！全部燒光吧！', '', 28153),
(157593, 'zhTW', '', '傳聞是真的。戴林之門…淪陷了。', 28153),
(157592, 'zhTW', '爆炸好劇烈。除了破碎的瓦礫以外，你是不是什麼都沒留下？', '', 28153),
(157591, 'zhTW', '', '農作物沒事了，謝謝你！我們來想辦法看能不能把這些小傢伙搬到遠離農地的地方去。', 28153),
(157590, 'zhTW', '', '我就知道這些力氣花得值得。我們有她在真是太幸運了！', 28153),
(157589, 'zhTW', '', '有某種生物一直把農夫的種子吃掉，種子無法發芽。快把牠趕出來！', 28153),
(157588, 'zhTW', '', '達文波特小姐要求我們把幾樣東西送往戰場幫助前線的士兵。那位老小姐個性倔強，我們最好還是乖乖照做！', 28153),
(157587, 'zhTW', '我們會不斷清除他們造成的腐化，直到風暴聖壇恢復往日的純淨為止。', '', 28153),
(157586, 'zhTW', '這些怪物想要玷污我們神聖的土地。不能坐視不管！', '', 28153),
(157585, 'zhTW', '', '我知道消滅害蟲不是什麼好差事，但我敢說磨石村的人一定都非常感謝你。', 28153),
(157584, 'zhTW', '', '磨石村的居民真的很不幸，遭遇到各式各樣的苦難。他們的食物染上害蟲了。我們去幫忙清除吧。', 28153),
(157583, 'zhTW', '總有一天，浪潮賢者第一次施展法術的快樂呼喊，會再次響起…不過那也是以後的事了。', '', 28153),
(157582, 'zhTW', '', '希望這樣可以把剩下那些可怕的巨人趕回山裡，那才是他們該去的地方！', 28153),
(157581, 'zhTW', '這裡還殘留著我前任主人的力量。每個角落都不能放過。', '', 28153),
(157580, 'zhTW', '謝謝你。谷地的人絕對不會忘記你的恩情。', '', 28153),
(157579, 'zhTW', '', '雙頭巨人在磨石村到處作亂，當地的平民沒有能力反擊。只能靠我們伸出援手了！', 28153),
(157578, 'zhTW', '英雄，布瑞納丹需要你。我們的兵力還不夠，沒有辦法憑自己的力量反擊。', '', 28153),
(157577, 'zhTW', '等你做好準備，就去找安潔莉卡船長。', '', 28153),
(157576, 'zhTW', '', '抱歉，我在請你幫忙之前，應該先問你會不會對蜜蜂過敏。但你看起來好好的，這樣我下一次就知道要找誰幫忙了。', 28153),
(157575, 'zhTW', '謝謝你這麼快就過來。勇士，我們安排你和第三艦隊一起行動。', '', 28153),
(157574, 'zhTW', '絕對不能放任這種無恥的邪惡在世界上到處蔓延。', '', 28153),
(157573, 'zhTW', '', '酒莊的蜜蜂又攻擊當地居民了，那些農夫根本無計可施。我一點也不意外！', 28153),
(157572, 'zhTW', '安杜因派我來的，間諜大師。', '安杜因派我來的，間諜大師。', 28153),
(157571, 'zhTW', '', '那個農場發生的事情讓雪怪都瘋了。米爾頓霍爾那些神經病搬來前，雪怪從來沒鬧過事。', 28153),
(157570, 'zhTW', '', '我們收到情報，米爾頓霍爾酒莊遇到雪怪的問題了。你可以去那裡幫幫他們嗎？', 28153),
(157569, 'zhTW', '克西爾在深淵旋律號上不斷施展黑暗魔法。淨化甲板上的污穢吧。', '', 28153),
(157568, 'zhTW', '我們雖然勢單力薄，但是有你在，我們就無所畏懼。', '', 28153),
(157567, 'zhTW', '墮落的浪潮賢者會誘騙迷路的水手，還打算奪走浪潮交會地。阻止他們！', '', 28153),
(157566, 'zhTW', '', '這個生物本來是個備受敬重的蘑菇人。如此高貴的戰士竟然變成這樣，真是悲劇。', 28153),
(157565, 'zhTW', '', '我們收到情報，南邊的洞窟裡有強大的生物。小心，光是讀到報告上的描述，我就已經嚇得寒毛直豎了…', 28153),
(157564, 'zhTW', '', '做得好，但我總覺得這不會是我們最後一次出手救他…', 28153),
(157563, 'zhTW', '我們一直沒辦法把部落的軍隊全都趕走。一定要破壞他們的產線，必要的話，把那裡炸了也沒關係！', '', 28153),
(157562, 'zhTW', '', '在斯陀頌恩打造的所有武器都應該用來保護人民，而不是壓迫人民。', 28153),
(157561, 'zhTW', '我知道這個任務對你而言或許太簡單了，不過這件事情真的很重要。', '', 28153),
(157560, 'zhTW', '坎寧斯村因為某種…複雜的原因，一直沒辦法完成海軍府的訂單。像你這麼厲害的人應該可以幫助他們吧。', '', 28153),
(157559, 'zhTW', '', '如果浪費了這些彈藥那才可惜呢。你知道該怎麼做了吧。', 28153),
(157558, 'zhTW', '現在軍隊不在這裡，我們只能靠自己對抗野豬人。', '', 28153),
(157557, 'zhTW', '野豬人又在他們的沼澤裡打壞主意了。趁他們準備出手前阻止他們的計畫！', '', 28153),
(157556, 'zhTW', '努拉，我是來這幫忙的。', '努拉，我是來這幫忙的。', 28153),
(157555, 'zhTW', '', '是什麼風把你吹來這的?', 28153),
(157554, 'zhTW', '我們稍晚將在城鎮裡會面，然後平分這筆寶藏！', '', 28153),
(157553, 'zhTW', '你能帶我接近南貧瘠之地的高地小道嗎？', '你能帶我接近南貧瘠之地的高地小道嗎？', 28153),
(157552, 'zhTW', '船沒了帆，就好像騎士沒了馬，只是…算了，反正就是沒有用。', '', 28153),
(157551, 'zhTW', '可怕的風暴會破壞船上的器材。快點平息風暴！', '', 28153),
(157550, 'zhTW', '你替艾丁頓伸張了遲來的正義。謝謝你。', '', 28153),
(157549, 'zhTW', '艾丁頓修士絕對不會容忍如此邪惡的行為。以他的名義掃蕩這裡！', '', 28153),
(157548, 'zhTW', '', '所有東西的起點都是原料。當然還要加上辛勤工作，以及真誠的心。', 28153),
(157547, 'zhTW', '', '斯陀頌恩的船匠舉世聞名，他們需要木材。快想辦法讓一切恢復正常！', 28153),
(157546, 'zhTW', '', '這樣他們才會知道，斯陀頌恩的大門永遠敞開！', 28153),
(157545, 'zhTW', '', '斯陀頌恩領主的人又設置封鎖線了！破壞封鎖線，這樣商人才能通過！', 28153),
(157544, 'zhTW', '快，動作快！', '', 28153),
(157543, 'zhTW', '去找伊莎貝拉吧。她會確保你能安全抵達幽暗城的集合點。', '', 28153),
(157542, 'zhTW', '一旦集結足夠的援軍，我再跟你說明情況。', '', 28153),
(157541, 'zhTW', '謝謝你反應如此迅速，我們不能浪費時間了。', '', 28153),
(157540, 'zhTW', '真正的浪潮賢者，應該要守護家園、賦予希望和指引方向。', '', 28153),
(157539, 'zhTW', '浪潮賢者都立下了神聖的誓言，必須保護我們的人民。幫助我們履行誓言，拯救他們吧！', '', 28153),
(157538, 'zhTW', '敵人不會善罷甘休。但是多虧有你，我們又能多奮戰一天。', '', 28153),
(157537, 'zhTW', '看來儀式果然失敗了。絕對不能讓納迦的邪惡魔法繼續污染這片海洋。', '', 28153),
(157536, 'zhTW', '艾薩拉的追隨者在上次失敗之後，換了個新的儀式。把他們送回深海裡去，讓他們和主人好好團聚吧。', '', 28153),
(157535, 'zhTW', '', '最近納迦變得愈來愈凶狠。我很擔心接下來不知道會發生什麼事情。', 28153),
(157534, 'zhTW', '', '風暴守望還沒從上次的納迦攻擊完全恢復過來。幫他們守住防線！', 28153),
(157533, 'zhTW', '這些資源應該能強化我們的軍力。去收集更多資源吧！', '', 28153),
(157532, 'zhTW', '海潮祝福你。只要有我們在，他們就別想奪走谷地！', '', 28153),
(157531, 'zhTW', '凡事都有第一次…不過這種事情還是別再發生比較好。', '', 28153),
(157530, 'zhTW', '呃，我不知道是怎麼回事，城裡發生怪事了。麻煩你去調查一下。 ', '', 28153),
(157529, 'zhTW', '', '如果你背棄自己的情感，那剩下的就只是空虛的黑暗。', 28153),
(157528, 'zhTW', '', '親愛的珍娜…不是所有抉擇都能靠理智決定。', 28153),
(157527, 'zhTW', '', '珍娜，他是假的！這全都是假的！', 28153),
(157526, 'zhTW', '', '可是…他們騙了我…', 28153),
(157525, 'zhTW', '我太愚蠢了，竟然以為你可以當我們的領袖！', '', 28153),
(157524, 'zhTW', '你竟然任憑自己的偏見汙染祈倫托！', '', 28153),
(157523, 'zhTW', '', '可惜你父親一直沒學會這件事。', 28153),
(157522, 'zhTW', '', '想阻止無謂的殺戮是崇高的理想，珍娜。', 28153),
(157521, 'zhTW', '斯陀頌恩領主的軍隊想奪回這個地方。絕對不能讓這個地方落到他們手裡！', '', 28153),
(157520, 'zhTW', '', '滾開，別靠近她！', 28153),
(157519, 'zhTW', '希爾雷克是夜之羅亞。對此你不需要知道更多了。', '希爾雷克是夜之羅亞。對此你不需要知道更多了。', 28153),
(157518, 'zhTW', '', '都是因為我…', 28153),
(157517, 'zhTW', '都是你…是你不讓我出手。想想那一天死了多少聯盟士兵？那一天以後的所有戰役又死了多少人？', '', 28153),
(157516, 'zhTW', '我本來有機會殺光他們的！希瓦娜斯…索爾…想想要是沒有邪惡的部落，這個世界該有多美好！', '', 28153),
(157515, 'zhTW', '', '不對。一定又是那些在折磨珍娜的生物。快點！', 28153),
(157514, 'zhTW', '', '好熟悉的聲音…戴林？！', 28153),
(157513, 'zhTW', '', '又是幻象？珍娜一定就被困在這附近。', 28153),
(157512, 'zhTW', '', '我們一定要找到她…把她救出這個充滿絕望的地方。', 28153),
(157511, 'zhTW', '', '我的女兒還在這裡的某處躲著。獨自忍受痛苦。', 28153),
(157510, 'zhTW', '做得好！在未來的日子裡，你的故事都會在海上流傳。', '', 28153),
(157509, 'zhTW', '', '我們繼續找吧。', 28153),
(157508, 'zhTW', '', '她不見了…那孩子只是個幻影…只是珍娜受折磨的痛苦殘影。', 28153),
(157507, 'zhTW', '', '…但就算是最強大的人也沒辦法救所有人。', 28153),
(157506, 'zhTW', '', '珍娜…你當時…你一直都是庫爾提拉斯的驕傲…你是庫爾提拉斯的力量和風暴…', 28153),
(157505, 'zhTW', '', '不！珍娜，別聽他們胡說！', 28153),
(157504, 'zhTW', '', '我讓他們失望了…讓全部的人失望了…', 28153),
(157503, 'zhTW', '', '你本來可以阻止他的！你本來可以救我們！', 28153),
(157502, 'zhTW', '向您報到，霸王。', '向您報到，霸王。', 28153),
(157501, 'zhTW', '風暴守望又需要你的協助了，願海潮指引你獲得勝利。', '', 28153),
(157500, 'zhTW', '你把我們丟在那裡等死！', '', 28153),
(157499, 'zhTW', '', '你帶路吧，$p。', 28153),
(157498, 'zhTW', '', '而我總是會找到她…我絕對不會放棄她。', 28153),
(157497, 'zhTW', '', '珍娜小時候只要一害怕或難過就會躲起來。', 28153),
(157496, 'zhTW', '', '等等！', 28153),
(157495, 'zhTW', '', '不！你幫不了我！沒有人可以幫我！', 28153),
(157494, 'zhTW', '', '親愛的，沒事了…', 28153),
(157493, 'zhTW', '', '珍娜就在前面。我們快一點跟上！', 28153),
(157492, 'zhTW', '瑟洛斯…會吞噬你們…', '', 28153),
(157491, 'zhTW', '', '有我在就不可能讓你得逞！', 28153),
(157490, 'zhTW', '入侵者，普勞德摩爾家的女兒是我們的了！', '', 28153),
(157489, 'zhTW', '', '$n，我們必須跟上她！', 28153),
(157488, 'zhTW', '', '珍娜，等等！', 28153),
(157487, 'zhTW', '', '不！別過來！', 28153),
(157486, 'zhTW', '', '珍娜？！', 28153),
(157485, 'zhTW', '', '都是我的錯…', 28153),
(157484, 'zhTW', '', '荒疫之原…這個地方還真是名副其實…', 28153),
(157483, 'zhTW', '海潮祝福你。我們的谷地再次安全了。', '', 28153),
(157482, 'zhTW', '以深海之名…絕對不能再讓這頭畸形的怪物威脅到我們的人民！', '', 28153),
(157481, 'zhTW', '所有膽敢擅自利用潮母恩賜的人，都應該記取這個教訓。', '', 28153),
(157480, 'zhTW', '竟敢褻瀆海洋的力量…不能放過他們。', '', 28153),
(157479, 'zhTW', '托加是一個力量大不如前的強大存在，但我們托爾托還留存著祂的記憶。', '', 28153),
(157478, 'zhTW', '讓我們在這裡稍停，$p。', '', 28153),
(157477, 'zhTW', '格拉爾是睿智的羅亞，他會考慮到事物長遠的走向。深海是他的領地，他統治著最黑暗的汪洋。', '格拉爾是睿智的羅亞，他會考慮到事物長遠的走向。深海是他的領地，他統治著最黑暗的汪洋。', 28153),
(157476, 'zhTW', '願海潮拒絕他們，就像他們拒絕同胞一樣。', '', 28153),
(157475, 'zhTW', '消滅了野豬人，眼中釘又少了一點！做得好。', '', 28153),
(157474, 'zhTW', '野豬人在沼澤外的農場不知道在計劃什麼事情。或許你應該去看看能不能阻止他們的陰謀？', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157473, 'zhTW', '又有邪惡的靈魂回應了斯陀頌恩領主的召喚。不能讓他們破壞一切！', '', 28153),
(157472, 'zhTW', '安息吧，可憐的靈魂。你不會再受苦了。', '', 28153),
(157471, 'zhTW', '我的弟兄居然造就了如此恐怖的生物…終結牠的痛苦吧。', '', 28153),
(157470, 'zhTW', '我走了…', '我走了…', 28153),
(157469, 'zhTW', '是的…大人。', '是的…大人。', 28153),
(157468, 'zhTW', '這是什麼？', '這是什麼？', 28153),
(157467, 'zhTW', '那我走啦！', '那我走啦！', 28153),
(157466, 'zhTW', '又要工作了？', '又要工作了？', 28153),
(157465, 'zhTW', '', '包在我身上，首領！', 28153),
(157464, 'zhTW', '我的確在這裡西邊看到另一個小挖掘場。凱爾希？', '', 28153),
(157463, 'zhTW', '一起作戰！付出了這麼多，千萬別放棄！', '', 28153),
(157462, 'zhTW', '聖匣會最大的挖掘場就在南邊再過去一點。如我所料。', '', 28153),
(157461, 'zhTW', '部落的人開始放火了！趕快滅火，別讓整個村子陷入火海！', '', 28153),
(157460, 'zhTW', '做得好！火已經開始熄滅了，我們的家園也保住了。謝謝你。', '', 28153),
(157459, 'zhTW', '我絕對要給塞斯拉克人好看，讓他們連片破銅爛鐵都帶不走。', '我絕對要給塞斯拉克人好看，讓他們連片破銅爛鐵都帶不走。', 28153),
(157458, 'zhTW', '雖然我沒辦法找回我們的海軍，不過至少我們知道船隻還在…某個地方。艦隊的命運就掌握在普勞德摩爾手中了。', '', 28153),
(157457, 'zhTW', '迦尼是掌管被捨棄或忽略的人事物之羅亞。祂看照著像我這樣的孤兒，或是任何地位低下的人。', '', 28153),
(157456, 'zhTW', '我在這裡能完全發揮法術的力量。只要還有一絲找到艦隊的希望，我們都應該試試看。', '', 28153),
(157455, 'zhTW', '呃…走開… <嗝！>我很忙。', '', 28153),
(157454, 'zhTW', '我們是托卡利的追隨者：我們是移動的山脈、徘徊的壁壘。只要羅亞祝福著我們，我們的盾牌就能滴水不穿。', '', 28153),
(157453, 'zhTW', '', '這樣在谷地徘徊的危險生物就少了一個！做得好！', 28153),
(157452, 'zhTW', '', '哇…我不知道該說什麼。太精彩了。', 28153),
(157451, 'zhTW', '在這裡等，我好像聽到了什麼。', '', 28153),
(157450, 'zhTW', '沒想到這個方法真的行得通。這些金幣可以幫助很多人恢復原本的生活！', '', 28153),
(157449, 'zhTW', '好…我感應到船隻了…是我們的艦隊！艦隊周圍的黑暗霧氣開始消散了！', '', 28153),
(157448, 'zhTW', '我是來這解決你的問題的，克羅格。', '我是來這解決你的問題的，克羅格。', 28153),
(157447, 'zhTW', '', '根據風暴守望的報告，附近有麻煩的野獸出沒。我相信你一定可以解決的！', 28153),
(157446, 'zhTW', '', '山中有危險生物徘徊。趁還沒有人受傷，快把牠找出來！', 28153),
(157445, 'zhTW', '亡淘村的尋寶獵人們會捐一些金幣來救濟布瑞納丹。只是這些金幣我們得自己去拿過來！', '', 28153),
(157444, 'zhTW', '亞瑟…', '', 28153),
(157443, 'zhTW', '多拉斯，我需要一匹蠍尾獅載我去蕨牆村。', '多拉斯，我需要一匹蠍尾獅載我去蕨牆村。', 28153),
(157442, 'zhTW', '', '勇士，做得好，救了艾特文就是幫助托爾托…羅亞應該也會非常滿意吧。', 28153),
(157441, 'zhTW', '嘿，我推倒了石頭！某些非常生氣的石頭。', '', 28153),
(157440, 'zhTW', '你的命令是推倒石塚。', '', 28153),
(157439, 'zhTW', '喔，拜託！事情最後結果相當棒。內陸人與我解決掉那隻岩石巨怪而且還活著！這是場勝利。', '', 28153),
(157438, 'zhTW', '亞瑟！我不是告訴過你別亂跑撞到東西嗎？', '', 28153),
(157437, 'zhTW', '', '托爾托崇拜偉大的烏龜艾特文，那是他們古老的盟友。去保護艾特文、獻上食物，再度贏得他的信任。', 28153),
(157436, 'zhTW', '離開這兒！', '', 28153),
(157435, 'zhTW', '願美好的海流指引你，勇士！你為我們所有人立下了楷模。', '', 28153),
(157434, 'zhTW', '那我們就繼續往南。古茲柏，記得保持聯絡。', '', 28153),
(157433, 'zhTW', '你沒問題的，古茲！', '', 28153),
(157432, 'zhTW', '', '給他們好看，古茲柏！', 28153),
(157431, 'zhTW', '…用大量的炸彈！', '', 28153),
(157430, 'zhTW', '小挖掘場，嗯？聽起來是一項地精的工作…', '', 28153),
(157429, 'zhTW', '大約往這裡東邊半公里處，有一個小型的聖匣會挖掘場。', '', 28153),
(157428, 'zhTW', '$n，小心你背後！幫助我除去這些阻礙。', '', 28153),
(157427, 'zhTW', '上古烏龜艾特文是海洋的神秘生物，我們必須好好保護。和托爾托一起照顧艾特文。', '', 28153),
(157426, 'zhTW', '即使犧牲生命，也要讓斯陀頌恩領主為他的罪行付出代價。', '', 28153),
(157425, 'zhTW', '斯陀頌恩的人民有安居樂業的權利。如果有人敢對他們造成威脅，就別對敵人客氣。', '', 28153),
(157424, 'zhTW', '我們必須立刻行動，才能從艾薩拉的手中救出艦隊。', '', 28153),
(157423, 'zhTW', '這裡不安全。來吧，附近有個可以鳥瞰聖壇的老舊瞭望台。', '', 28153),
(157422, 'zhTW', '只要我們還活著，就絕對不會忘記他。', '', 28153),
(157421, 'zhTW', '那股聲音現在與你自己的聲音共鳴。你感覺它正在尋找一個答案，因為你自己也一樣。\n\n「目的又是什麼？」', '', 28153),
(157420, 'zhTW', '隨著你內心的聲音開始尖叫，你也因痛楚而皺眉。\n\n「它是從哪裡開始的？」', '', 28153),
(157419, 'zhTW', '非常感謝你，農夫們很快就能回到田地裡工作了。', '', 28153),
(157418, 'zhTW', '我接到報告說外圍的農地有危險。請你幫忙讓谷地恢復秩序！', '', 28153),
(157417, 'zhTW', '聲音越來越強烈而急切。\n\n「更多，更多，更多！」', '', 28153),
(157416, 'zhTW', '那古老的聲音現在只剩下回音，從你心靈的深處呼喚著。\n\n『你在追尋什麼？』', '', 28153),
(157415, 'zhTW', '你還真是讓人驚訝！改天有機會的話也教我兩招吧。', '', 28153),
(157414, 'zhTW', '做得好，如果需要帶你離開波拉勒斯，我們已經在附近安排人手了。', '', 28153),
(157413, 'zhTW', '我會潛行回去，報告博伍德。我們那裡見！', '', 28153),
(157412, 'zhTW', '哈！它在我們的力量之前崩潰了！', '', 28153),
(157411, 'zhTW', '', '小山…他…他走了…', 28153),
(157410, 'zhTW', '等我們殺掉他們最後一個人民，看他們全部變成被遺忘者的時候，那個小國王會臣服在黑暗女王腳下。最後，女王會統治世界。', '', 28153),
(157409, 'zhTW', '仇恨、鄙視，隨便你怎麼說。', '', 28153),
(157408, 'zhTW', '', '啊，你把仇恨轉化成動力。這我也懂。', 28153),
(157407, 'zhTW', '我們擺脫了巫妖王的控制之後，希瓦娜斯四處尋求盟友。人類不但沒有接納死去的羅德隆同胞，反而唾棄我們、獵殺我們。所以我也要獵殺他們。', '', 28153),
(157406, 'zhTW', '', '背信忘義？', 28153),
(157405, 'zhTW', '我曾經為他們戰鬥過。聯盟背信忘義，如今那種討人厭的傲慢，又增長了十倍。', '', 28153),
(157404, 'zhTW', '', '凋零者，你這麼熱衷於打擊聯盟，看起來不只是為了女王。', 28153),
(157403, 'zhTW', '', '我導致了一名國王的殞落，也許我能再次終結另一名國王的統治。', 28153),
(157402, 'zhTW', '很好。聯盟不值得同情，也不值得寬恕。好好教訓他們，黑暗女王會獎勵你的。', '', 28153),
(157401, 'zhTW', '', '的確。但是你一定也知道，我和聯盟合作是為了達成我的目的。我沒有欠他們什麼，部落才是我的家。', 28153),
(157400, 'zhTW', '你們這群傻瓜…', '', 28153),
(157399, 'zhTW', '以庫爾提拉斯之名，你將離開這個地方！', '', 28153),
(157398, 'zhTW', '我記得，但我也知道殺死萊恩·烏瑞恩並非出於你的意願。', '', 28153),
(157397, 'zhTW', '', '因為小國王的祖父把我當成朋友嗎？是我殺了他，你還記得吧？', 28153),
(157396, 'zhTW', '迦羅娜，你攻擊聯盟的手法非常厲害。可是我懷疑，你…是否真的忠於部落。', '', 28153),
(157395, 'zhTW', '哎嘿嘿，鮮肉上門了。', '', 28153),
(157394, 'zhTW', '感受自然之怒吧！', '', 28153),
(157393, 'zhTW', '我要把你徹底碾碎！', '', 28153),
(157392, 'zhTW', '你確定要繼續嗎？', '你確定要繼續嗎？', 28153),
(157391, 'zhTW', '勇士，做得好。斯陀頌恩谷地欠你太多人情，恐怕永遠都還不清。', '', 28153),
(157390, 'zhTW', '是夢，有關沉沒城市的夢。', '是夢，有關沉沒城市的夢。', 28153),
(157389, 'zhTW', '在他凝視之影找到…', '在他凝視之影找到…', 28153),
(157388, 'zhTW', '失於她的無情擁抱…', '失於她的無情擁抱…', 28153),
(157387, 'zhTW', '吸入溺水者的智慧…', '吸入溺水者的智慧…', 28153),
(157386, 'zhTW', '險丘小屋的倖存者已經戰鬥好幾天了。去看看你能不能幫上忙，為他們爭取休息的時間。', '', 28153),
(157383, 'zhTW', '真驚人，剛剛爆炸了好多次！幸好你跟托奇都安然無恙。', '', 28153),
(157382, 'zhTW', '深深飲下粼粼潮水…', '深深飲下粼粼潮水…', 28153),
(157381, 'zhTW', '風險投資公司一直在破壞這裡的海岸。去找托奇，也許你可以幫助他。', '', 28153),
(157380, 'zhTW', '呃...', '呃...', 28153),
(157379, 'zhTW', '你找到一個不祥的祭壇。當你將手放在上面時，陣陣話語開始流竄你的心靈。\n\n「你要如何開始？」', '', 28153),
(157378, 'zhTW', '做得好。改天我們去喝一杯，我請客。', '', 28153),
(157377, 'zhTW', '給我等著，我會好好對付你！', '', 28153),
(157376, 'zhTW', '我要把你撕成碎片！', '', 28153),
(157375, 'zhTW', '我想把鐵潮的人趕出這裡。如果不給鐵潮好日子過，看他們還會不會繼續在這裡逗留。', '', 28153),
(157374, 'zhTW', '為了佐司瓦！', '', 28153),
(157373, 'zhTW', '來！我們把那怪物化為碎石！', '', 28153),
(157372, 'zhTW', '', '托爾托一定很感謝你。我也是。', 28153),
(157371, 'zhTW', '', '那些風險投資公司的打手一直欺負托爾托！勇士，去找托奇看能不能幫助托爾托。', 28153),
(157370, 'zhTW', '', '我們的敵人會記得，部落勇士阻止他們的陰謀。做得好。', 28153),
(157369, 'zhTW', '', '我們的敵人愈來愈大膽了！快去奪取敵人的資源…必要的話還有性命。', 28153),
(157368, 'zhTW', '', '只要敵人變弱，我們就會更強。成功的每一小步，都可能帶來全面的勝利。', 28153),
(157367, 'zhTW', '', '士兵需要填飽肚子才能打仗。熊肉可以讓大家吃飽。別讓敵人阻礙你的行動。', 28153),
(157362, 'zhTW', '不應該存在的遠古魔物正蠢蠢欲動。謹慎戒備。', '不應該存在的遠古魔物正蠢蠢欲動。謹慎戒備。', 28153),
(157361, 'zhTW', '我們沒想到死人還能走路！', '我們沒想到死人還能站起來走路！', 28153),
(157360, 'zhTW', '我們沒料到力量會這麼強大！小心一點，內陸人。', '我們沒料到力量會這麼強大！小心一點，內陸人。', 28153),
(157359, 'zhTW', '一定要消滅這些傀儡。拜託幫幫忙！', '一定要消滅這些傀儡。拜託幫幫忙！', 28153),
(157358, 'zhTW', '謝謝你及時幫忙，內陸人。', '謝謝你及時幫忙，內陸人。', 28153),
(157357, 'zhTW', '$p，停下來。你看到了嗎？', '', 28153),
(157356, 'zhTW', '總算把他們趕跑了。城鎮沒有被摧毀。你保住了我們的性命。', '', 28153),
(157355, 'zhTW', '大批的部落部隊回來了，他們想要完成任務。我們一定要阻止部落！', '', 28153),
(157354, 'zhTW', '他通常不太吭聲，真的需要幫忙才會講。謝謝你幫助他！', '', 28153),
(157353, 'zhTW', '古弗德說他需要你幫忙。他的農場一直遭受到攻擊，補給品已經不夠了。想辦法幫幫他吧。', '', 28153),
(157352, 'zhTW', '下次野豬人就不敢隨便擴建地道了！幫我摸摸獵犬，獎勵牠。', '', 28153),
(157351, 'zhTW', '野豬人想擴建地道，這對我們的谷地是種威脅。只要給獵犬一點方向，就能嗅出野豬人的位置。', '', 28153),
(157350, 'zhTW', '$p，上路吧。', '', 28153),
(157349, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t你受到|cFFFF0000|Hspell:272536|h[毀滅在即]|h|r效果影響！', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t你受到|cFFFF0000|Hspell:272536|h[毀滅在即]|h|r效果影響！', 28153),
(157348, 'zhTW', '我跟你說，這個房間非常適合用來展示皇家收藏的古董文物。我們可以…', '', 28153),
(157347, 'zhTW', '', '我就在不遠處。', 28153),
(157346, 'zhTW', '珊蒂斯，低調一點。躲在陰影裡…如果你找到陰影的話。', '', 28153),
(157345, 'zhTW', '', '收到了，最高指揮官！我們走！', 28153),
(157344, 'zhTW', '凱爾希，你是我們在天空的眼睛。如果看到異狀就回報。', '', 28153),
(157343, 'zhTW', '你能再說一次計畫嗎？', '你能再說一次計畫嗎？', 28153),
(157342, 'zhTW', '我爸媽總是說我的想像力太豐富了。', '', 28153),
(157341, 'zhTW', '有時候我們會坐著小推車滑下谷地的山坡！我們還會假裝哈伯斯是老虎！', '', 28153),
(157340, 'zhTW', '小時候我跟哈伯斯常常到處去進行各式各樣的冒險。', '', 28153),
(157339, 'zhTW', '讓我看看。', '讓我看看。', 28153),
(157338, 'zhTW', '異象能協助我們觀察大屠殺，$r。', '異象能協助我們觀察大屠殺，$r。', 28153),
(157337, 'zhTW', '不久之後，艦隊也會沐浴在她的榮光之中，而庫爾提拉斯也會臣服於波濤之下。', '', 28153),
(157336, 'zhTW', '你們被蒙蔽了。潮母的恩賜讓我們重新獲得了力量。', '', 28153),
(157335, 'zhTW', '腐化的靈魂啊，你們還沒有履行誓言。摧毀這道大門！', '', 28153),
(157334, 'zhTW', '', '|TINTERFACE\\ICONS\\INV_TikiMan2_Bloodtroll.blp:20|t 長老黎克沙開始施放|cFFF00000|Hspell:264603|h[鮮血鏡像]|h|r！', 28153),
(157333, 'zhTW', '', '我對這座洞窟有信心。裡面一定有大量的黃金。', 28153),
(157332, 'zhTW', '我才正要講到我整個人跳進他的喉嚨從裡頭把牠切成兩半的部分！', '我剛講到一半。當時我一刀往牠喉嚨切下去，把牠切成兩半！', 28153),
(157331, 'zhTW', '好啦好啦，賴恩跟鉛錘辛可也有幫忙。不過我說的都是真的…字字真實！', '好啦好啦，賴恩跟辛可也有幫忙。不過我說的都是真的…字字屬實！', 28153),
(157330, 'zhTW', '嗯哼哼哼哼哼！', '嗯哼哼哼哼哼！', 28153),
(157329, 'zhTW', '閉嘴，賴恩，不准打斷我說話！', '閉嘴，賴恩，不准打斷我說話！', 28153),
(157328, 'zhTW', '', '沒有黃金，但是有很多蘭姆酒！', 28153),
(157327, 'zhTW', '對啊，就是靠我精湛的釣魚技術！', '對啊，還不是靠我精湛的釣魚技術！', 28153),
(157326, 'zhTW', '還好我反應夠快，立刻想到該怎麼料理這傢伙。', '還好我反應夠快，立刻想到該怎麼料理這個傢伙。', 28153),
(157325, 'zhTW', '然後我看見這傢伙出現地平線那端慢慢接近。我從沒看過這麼大尾的傢伙！', '然後我看見這傢伙從海平面上慢慢靠近。我從沒看過這麼大尾的傢伙！', 28153),
(157324, 'zhTW', '當時我站第一班哨，提防是不是有其他該死的納迦打過來。', '當時我站第一班哨，還在提防納迦闖過來。', 28153),
(157323, 'zhTW', '我現在來說說是怎麼遇上這兩個可憐水手的。', '我來說說是怎麼遇上這兩個可憐水手的。', 28153),
(157322, 'zhTW', '對啊，就是說嘛…喂，等一下！', '好啦，就算我同意，也…喂，等一下！', 28153),
(157321, 'zhTW', '你被潛水頭盔悶壞腦子了嗎？你乾脆跟我說賴恩會釣魚，我還可能相信！', '你被潛水頭盔悶壞腦子了嗎？你乾脆跟我說賴恩會釣魚，我還可能相信！', 28153),
(157320, 'zhTW', '呣呣呣呣呣。呣呣呣。', '呣呣呣呣呣。呣呣呣。', 28153),
(157319, 'zhTW', '呣！', '呣！', 28153),
(157318, 'zhTW', '呣呣…呣。', '呣呣…呣。', 28153),
(157317, 'zhTW', '幸運的是，我脖子上總是掛著特殊的子彈，以備不時之需。', '幸運的是，我脖子上總是掛著特殊的子彈，以備不時之需。', 28153),
(157316, 'zhTW', '到船長回來以前我會看守這些蘭姆酒。', '', 28153),
(157315, 'zhTW', '艦長…我完全沒有喝。', '', 28153),
(157314, 'zhTW', '', '有海盜的地方，通常就有黃金！', 28153),
(157313, 'zhTW', '', '有些工人說他們在這座洞窟看到一個海盜的鬼魂。', 28153),
(157312, 'zhTW', '', '前面就是布瑞納丹了。來吧！', 28153),
(157311, 'zhTW', '', '少了艦隊，我們就沒有防衛力量。隨時都可能遭受攻擊。', 28153),
(157310, 'zhTW', '', '我們要立刻找到派克修士才行。希望他能幫我們把艦隊指引回家。', 28153),
(157309, 'zhTW', '', '這片谷地很有氣勢吧？難怪會有這麼多人來這裡定居。', 28153),
(157308, 'zhTW', '', '這條路是去谷地唯一的路。斯陀頌恩家族一定有什麼古怪。', 28153),
(157307, 'zhTW', '', '布瑞納丹是庫爾提拉斯除了波拉勒斯以外最大的貿易重鎮。', 28153),
(157306, 'zhTW', '用力點好不好，你們這群小懶蟲！', '用力點好不好，你們這群小懶蟲！', 28153),
(157305, 'zhTW', '他在上面。有兩顆頭，而且體型巨大！', '他已經在那裡準備好攻擊了！', 28153),
(157304, 'zhTW', '別多管閒事。我來這裡有正事要辦！', '別多管閒事。我來這裡有正事要辦！', 28153),
(157303, 'zhTW', '你在做什麼？你必須跟我們其餘人一樣撤退！', '你在做什麼？你必須跟我們其餘人一樣撤退！', 28153),
(157302, 'zhTW', '你的棍棒小心點！', '你還是快逃吧，湯姆，我們可是人多勢眾！', 28153),
(157301, 'zhTW', '我們兩個都認為這…是你的錯。', '我們兩個都認為這…是你的錯。', 28153),
(157300, 'zhTW', '來面對我…兩個我！', '來面對我…兩個我！', 28153),
(157299, 'zhTW', '我要取他的右頭。', '他比我想像的還要龐大。', 28153),
(157298, 'zhTW', '檢查中', '檢查中', 28153),
(157296, 'zhTW', '歡迎回來，我的小朋友。聽聽這首我學到的新歌！', '', 28153),
(157294, 'zhTW', '你死掉，然後我壓扁鎮上所有人！', '你死掉，然後我壓扁鎮上所有人！', 28153),
(157293, 'zhTW', '風暴守望堅定不移，我們會為了聯盟率領艦隊，並且獲得勝利。', '', 28153),
(157292, 'zhTW', '', '海軍總帥，威奎斯特家族與你同在，也與聯盟同在。', 28153),
(157291, 'zhTW', '', '也請大家相信聯盟。聯盟的英雄救了我們，使我們不致於自我毀滅。', 28153),
(157290, 'zhTW', '', '請大家相信我的女兒珍娜…她成為庫爾提拉斯海軍總帥可以說是實至名歸。', 28153),
(157289, 'zhTW', '', '部落的目的也非常明確了，他們恨不得看著我們的國家燒成灰燼。', 28153),
(157288, 'zhTW', '', '如果我們不團結，就會變得脆弱。內部分化是我們最大的敵人。', 28153),
(157287, 'zhTW', '', '謝謝大家過來。我盡量長話短說。', 28153),
(157286, 'zhTW', '我敢說我們一定能把這些怪物消滅掉！', '', 28153),
(157285, 'zhTW', '當戴林要我離開他的守衛隊，撫養這個東部王國的小孩時，這真的把我弄糊塗了。\n\n為何要讓我承受這個負擔呢？為何不讓我待在他身邊奮戰呢？我認為或許是我做了什麼，讓他失去對我的信賴。\n\n這麼多年來，我終於了解事實正好相反。他要讓泰莉亞長大後成為一個堅強而心地高貴的人 - 而他相信我能辦到。', '', 28153),
(157284, 'zhTW', '', '我們是真的可以用某種地下坑道從暴風城前往鐵爐堡嗎？$B$B聽起來真不可思議！多希望有天可以見識一下。', 28153),
(157283, 'zhTW', '才一點點，威力就這麼驚人！如果有更多，破壞力不知道會有多強。', '', 28153),
(157282, 'zhTW', '', '謝謝。這樣一來，這裡的居民應該可以回田裡工作了。', 28153),
(157281, 'zhTW', '', '附近有某種生物威脅當地農夫的安全。我們必須幫忙！', 28153),
(157280, 'zhTW', '', '好極了！他們一定能讓這些資源派上用場。', 28153),
(157279, 'zhTW', '', '希望有一天，庫爾提拉斯人可以再次信任浪潮賢者的智慧，接受他們的指引。但在那之前，自己的航道還是自己決定吧。', 28153),
(157278, 'zhTW', '', '這樣一來我們也能稍微鬆一口氣了。謝謝你。', 28153),
(157277, 'zhTW', '', '斯陀頌恩的人民不會忘記你的付出。做得好！', 28153),
(157276, 'zhTW', '', '這片山丘資源豐富，對風暴守望的計畫來說非常重要。你可以幫助他們嗎？', 28153),
(157275, 'zhTW', '', '斯陀頌恩領主的人又在惹麻煩了。我們絕對不能讓他們繼續進行邪惡的儀式！', 28153),
(157274, 'zhTW', '', '這一帶快要失守了！快過去把敵人擊退！', 28153),
(157273, 'zhTW', '', '風暴守望需要幫忙。請你盡一切努力，讓這片谷地恢復和平吧！', 28153),
(157272, 'zhTW', '', '砲手！準備最後一次彈幕！', 28153),
(157271, 'zhTW', '', '維持護盾！我們快撐不住了！', 28153),
(157270, 'zhTW', '另外一個被遺忘者。我沒想到 - <咳嗽>。告訴我，小姐…？', '', 28153),
(157269, 'zhTW', '<咳嗽> 部落。我想這裡就是我安息的地方。\n\n而你是被遺忘者？有趣，但太遲了。\n\n嗯？你在等什麼？', '', 28153),
(157268, 'zhTW', '我們貨車再見，$p！', '', 28153),
(157267, 'zhTW', '', '呦呼！取寶了！', 28153),
(157266, 'zhTW', '請帶我回去。', '請帶我回去。', 28153),
(157265, 'zhTW', '感謝你今天的協助。我們應該離開了。', '感謝你今天的協助。我們應該離開了。', 28153),
(157264, 'zhTW', '(觀看澤靈與他家人的相遇。)', '(觀看澤靈與他家人的相遇。)', 28153),
(157263, 'zhTW', '朋友，你做得真好。如果聯盟的人騎術都跟你一樣厲害，那這個莊園隨時歡迎大家！', '', 28153),
(157262, 'zhTW', '啊，真是適合表演的美好日子！朋友，快上馬吧，上場讓大家看看你多厲害！', '', 28153),
(157261, 'zhTW', '', '你請便。來吧，$n。', 28153),
(157260, 'zhTW', '我要回基地了。我知道最後會發生什麼事，不需要親眼目睹。', '', 28153),
(157259, 'zhTW', '要知道你身在比你優秀的人之中。不要拿什麼妖術之王來浪費我的時間。', '', 28153),
(157258, 'zhTW', '', '很好！這樣應該能拖慢納迦的攻勢。', 28153),
(157257, 'zhTW', '', '我跟你保證。來吧，$n，回去見納薩諾斯並跟他說我們已經有了我們需要的東西了。', 28153),
(157256, 'zhTW', '我會加入你…然後協助你找到瓦倫汀船長。只要你保證我的家人平安無事。', '', 28153),
(157255, 'zhTW', '', '納迦又進攻堡壘了！用托爾托風格解決他們吧！', 28153),
(157254, 'zhTW', '', '擁抱被遺忘者之道並打造出你自己的道途。你會身在那些會接受你所變成的樣子的人之中。', 28153),
(157253, 'zhTW', '而這樣我算什麼？女妖之王的無腦僕人嗎？', '', 28153),
(157252, 'zhTW', '', '很少有贊達拉以外的人獲得此等殊榮。請你跟我一起走，跟大家分享沃金的事蹟。', 28153),
(157250, 'zhTW', '', '我曾試著警告你，澤靈。這個過程會改變你。活人將不再接受你了。', 28153),
(157249, 'zhTW', '不…茱莉亞…馬修…漢娜…我做了什麼？我是…什麼？', '', 28153),
(157248, 'zhTW', '', '把那怪物趕走！', 28153),
(157247, 'zhTW', '', '離我們遠一點！', 28153),
(157246, 'zhTW', '把它弄走！', '', 28153),
(157245, 'zhTW', '安靜！', '', 28153),
(157244, 'zhTW', '', '我不知道你是誰，但我的丈夫從沒試著傷害我或者他的小孩。我們要走了…別跟著我們！', 28153),
(157243, 'zhTW', '我…我…', '', 28153),
(157242, 'zhTW', '夠了！', '', 28153),
(157241, 'zhTW', '媽媽！救救我們！', '', 28153),
(157240, 'zhTW', '', '別讓它過來！', 28153),
(157239, 'zhTW', '爸爸就在這裡，聽我的聲音！你為什麼不了解呢？', '', 28153),
(157238, 'zhTW', '', '滾開！', 28153),
(157237, 'zhTW', '媽媽，我怕怪物！', '', 28153),
(157236, 'zhTW', '你為何不了解呢？是我，你的丈夫…孩子們，我是你們的爸爸啊！', '', 28153),
(157235, 'zhTW', '', '我再說最後一次，後退！你不是我的丈夫！', 28153),
(157234, 'zhTW', '我依然強大…就算死後也一樣。', '', 28153),
(157233, 'zhTW', '你還沒準備好在戰鬥中面對我！', '', 28153),
(157232, 'zhTW', '澤靈，我們要你幫我們找到瓦倫泰元帥的屍體。', '澤靈，我們要你幫我們找到瓦倫泰元帥的屍體。', 28153),
(157231, 'zhTW', '我的朋友會替我…復仇。', '', 28153),
(157230, 'zhTW', '我的怒氣將主要發洩在你身上！', '', 28153),
(157229, 'zhTW', '', '…我猜我們現在必須靜觀其變。', 28153),
(157228, 'zhTW', '我…我還活著！哈哈！我要立刻去找茱莉亞跟孩子們，他們一定很高興！', '', 28153),
(157227, 'zhTW', '', '很少有靈魂這麼…強大。加德林大師，請你把大酋長的骨灰帶到阿塔達薩。如果他的靈魂受到肯定，就可以光榮地與最偉大的諸王擺在一起。', 28153),
(157226, 'zhTW', '札拉贊恩不會再出現了。沃金即使已經不在人世，依然守護著我們。', '', 28153),
(157225, 'zhTW', '死去的人…還是倒下了…', '', 28153),
(157224, 'zhTW', '我們的援軍等候你的差遣。', '', 28153),
(157223, 'zhTW', '如果部落想打，我們將盡全力讓他們好看！', '', 28153),
(157222, 'zhTW', '希望你會有好消息。', '', 28153),
(157221, 'zhTW', '斯陀頌恩屹立不搖。', '', 28153),
(157220, 'zhTW', '一路順風。', '', 28153),
(157219, 'zhTW', '願潮水指引你。', '', 28153),
(157218, 'zhTW', '好極了！這些補給品派得上用場，我們也會好好利用那些小豬的。', '', 28153),
(157217, 'zhTW', '野豬人又在搶我們的商店了。為了公平起見，我們去把補給品搶回來，有看到什麼好東西也順便帶回來！', '', 28153),
(157216, 'zhTW', '沒問題。', '', 28153),
(157215, 'zhTW', '', '是的，大人！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157214, 'zhTW', '', '慈悲的伊露恩，請照耀亡魂。', 28153),
(157213, 'zhTW', '泰莉亞，再去巡察一次。叫城裡的守衛提高警覺，看看有沒有什麼不尋常的武器被走私到波拉勒斯。', '', 28153),
(157212, 'zhTW', '', '讓世人知道，森金之子沃金有資格進入這個神聖的墓地。不過要進入阿塔達薩恐怕避免不了戰鬥。我建議由這位勇士帶著骨灰前往最後入葬的地點。', 28153),
(157211, 'zhTW', '', '要做領袖不願意做的事情，真的很難。', 28153),
(157210, 'zhTW', '當大酋長卡爾洛斯不願意以身作則，以榮譽領導大家，沃金率領大家反抗這個好戰的領導者。', '', 28153),
(157209, 'zhTW', '', '當時，祖爾述說著偉大食人妖帝國的願景，對我的父親很有吸引力。不過你們酋長的眼光更加遠大。', 28153),
(157208, 'zhTW', '當贊達拉意圖統一所有食人妖部族的時候，沃金為了人民的安全，挺身對抗先知的黑暗力量。', '', 28153),
(157207, 'zhTW', '為了打敗強大的札拉贊恩，沃金和伯昂撒姆第做了交易。', '', 28153),
(157206, 'zhTW', '', '我已經數不清幽光的數量了。失去的生命啊…', 28153),
(157205, 'zhTW', '我們帶著森金之子，沃金的骨灰，來到這個聖地致意。', '', 28153),
(157204, 'zhTW', '弗林，我有任務要交給你：幫我們新盟友調查這種粉末的來源。', '', 28153),
(157203, 'zhTW', '古老的威脅在這裡蠢蠢欲動。小心一點。', '', 28153),
(157202, 'zhTW', '喚風者，我奉大酋長之命前來。', '喚風者，我奉大酋長之命前來。', 28153),
(157201, 'zhTW', '是的，我已經準備好去希利蘇斯了。', '是的，我已經準備好去希利蘇斯了。', 28153),
(157200, 'zhTW', '我為何在這裡，人類？', '我為何在這裡，人類？', 28153),
(157199, 'zhTW', '特使！我的同事不太相信，你願意展示給他們看看嗎？', '', 28153),
(157198, 'zhTW', '不，這次可不一樣。', '', 28153),
(157197, 'zhTW', '這也算線索？他們不是一直都在開發武器嗎。', '', 28153),
(157196, 'zhTW', '', '好吧，弗林，你發現什麼重要線索？是關於艾胥凡的新型火藥嗎？', 28153),
(157195, 'zhTW', '我需要一匹蠍尾獅前往安戈洛環形山的馬紹爾營地。', '我需要一匹蠍尾獅前往安戈洛環形山的馬紹爾營地。', 28153),
(157194, 'zhTW', '回來了…很好！我可沒那個膽子跟公主說，她的勇士被一個鑽石矮人搶走了！', '', 28153),
(157193, 'zhTW', '噢，耶！「我們」做得真好！', '', 28153),
(157192, 'zhTW', '我們得把那些貨物搶回來。我說的「我們」當然是指「你」。', '', 28153),
(157191, 'zhTW', '不管你要去的地方在哪，都希望這趟旅途不會太久。公主非常需要你的幫忙！', '不管你要去的地方在哪，都希望這趟旅途不會太久。公主非常需要你的幫忙！', 28153),
(157190, 'zhTW', '太令人驚奇了！我一定要紀錄下來。', '太令人驚奇了！我一定要紀錄下來。', 28153),
(157189, 'zhTW', '能否保護自己的補給線會左右戰果…能否摧毀敵人的補給線也很重要。', '', 28153),
(157188, 'zhTW', '聯盟的船遇難了…真是讓人高興！去附近找找看有沒有部落能用的物資。', '', 28153),
(157187, 'zhTW', '一天就搞定了。', '', 28153),
(157186, 'zhTW', '採礦機被攻擊了！快保護採礦機！', '', 28153),
(157185, 'zhTW', '這些資源對部落正在進行的活動非常重要。做得好。', '', 28153),
(157184, 'zhTW', '快保護採礦機！我們需要艾澤萊晶岩！', '', 28153),
(157183, 'zhTW', '你的戰術是什麼，珊蒂斯？', '你的戰術是什麼，珊蒂斯？', 28153),
(157182, 'zhTW', '', '<珊蒂斯銳利的雙眼掃視著地平線。她認同地對你點點頭。>', 28153),
(157181, 'zhTW', '找到日衛者，然後將他亂箭射死。', '', 28153),
(157180, 'zhTW', '我的戰略？', '', 28153),
(157179, 'zhTW', '諾姆瑞根特勤隊將設置炸彈引出日衛者，然後我們會趁著混亂突襲他。', '', 28153),
(157178, 'zhTW', '', '嗨啊！', 28153),
(157177, 'zhTW', '沒錯！因此，我已經召集一支有足夠技術的突擊隊進行攻堅。', '', 28153),
(157176, 'zhTW', '', '你想要…同時引爆大量炸彈。', 28153),
(157175, 'zhTW', '我想對他們所有挖掘場執行一次同步的燃燒彈攻擊。', '', 28153),
(157174, 'zhTW', '是的。我們的情報顯示至少有三處挖掘場。', '', 28153),
(157173, 'zhTW', '', '考古學？', 28153),
(157172, 'zhTW', '日衛者是聖匣守護者的成員，來此執行一項考古學任務。', '', 28153),
(157171, 'zhTW', '我…我不記得了？但這樣比較好。', '', 28153),
(157170, 'zhTW', '', '朋友，抱歉…你剛剛說你是誰？你是瑪法里恩提到的人嗎？', 28153),
(157168, 'zhTW', '我將你的字條帶給了碧葳茲緹。', '我將你的字條帶給了碧葳茲緹。', 28153),
(157167, 'zhTW', '', '還有那些平民…部落連平民都不放過。我只希望有人能逃過一劫…', 28153),
(157166, 'zhTW', '', '我們的哨站遭到突襲，接連失守。守衛都中毒了。', 28153),
(157165, 'zhTW', '', '在她站起來時，%s拭了一滴眼淚。', 28153),
(157164, 'zhTW', '', '本來想設下陷阱對付部落，結果失敗了。我們沒有成功。', 28153),
(157163, 'zhTW', '很高興看到你平安，$n。\n\n我也很好。\n\n亞昆達給了我一個重新來過的機會。', '', 28153),
(157162, 'zhTW', '你的計劃是什麼，最高指揮官？', '你的計劃是什麼，最高指揮官？', 28153),
(157161, 'zhTW', '第七軍團是艾澤拉斯的菁英。\n\n為了聯盟！', '', 28153),
(157160, 'zhTW', '誰？我不認識任何叫做這名字的食人妖，對吧？', '', 28153),
(157159, 'zhTW', '', '屍體…有好多好多屍體…', 28153),
(157158, 'zhTW', '我有樣東西要給你看看，這個禮物能幫助這個地方的人。', '', 28153),
(157157, 'zhTW', '在祖達薩的中心…居然會有個…鑽石矮人！你到底是誰？', '', 28153),
(157156, 'zhTW', '', '我在森林裡看過不少奇怪的東西，但都比不上這個。', 28153),
(157155, 'zhTW', '你感覺到了嗎？地面好像在震動…', '', 28153),
(157153, 'zhTW', '大酋長命令我協助你。', '大酋長命令我協助你。', 28153),
(157152, 'zhTW', '我必須飛往塔納利斯的加基森。', '我必須飛往塔納利斯的加基森。', 28153),
(157151, 'zhTW', '你…必須…', '', 28153),
(157150, 'zhTW', '我會…詛咒我的靈魂…永遠…如果這表示我家人能夠幸福…拜託！你必須…', '', 28153),
(157149, 'zhTW', '', '澤靈，我每天都在想這件事。', 28153),
(157148, 'zhTW', '鎖定目標。', '', 28153),
(157147, 'zhTW', '', '當我們成為被遺忘者時，我們都變得有點瘋狂。某些人比其他人更瘋。', 28153),
(157146, 'zhTW', '你認識亞昆達嗎？', '你認識亞昆達嗎？', 28153),
(157145, 'zhTW', '讓亞昆達卸下你心中的重擔。', '讓亞昆達卸下你心中的重擔。', 28153),
(157144, 'zhTW', '亞昆達賜與我們重新開始的機會。', '亞昆達賜與我們重新開始的機會。', 28153),
(157143, 'zhTW', '我們總是歡迎你。', '我們總是歡迎你。', 28153),
(157142, 'zhTW', '羅亞對神廟的訪客來者不拒。', '羅亞對神廟的訪客來者不拒。', 28153),
(157141, 'zhTW', '你認識亞昆達嗎？', '你認識亞昆達嗎？', 28153),
(157140, 'zhTW', '讓亞昆達卸下你心中的重擔。', '讓亞昆達卸下你心中的重擔。', 28153),
(157139, 'zhTW', '亞昆達賜與我們重新開始的機會。', '亞昆達賜與我們重新開始的機會。', 28153),
(157138, 'zhTW', '我們總是歡迎你。', '我們總是歡迎你。', 28153),
(157137, 'zhTW', '羅亞對神廟的訪客來者不拒。', '羅亞對神廟的訪客來者不拒。', 28153),
(157136, 'zhTW', '我是來幫忙的，奈瑟。', '我是來幫忙的，奈瑟。', 28153),
(157135, 'zhTW', '啊，夢魘結束了。', '啊，夢魘結束了。', 28153),
(157134, 'zhTW', '大砲準備好！把海怪轟回海底去！', '大砲準備好！把海怪轟回海底去！', 28153),
(157133, 'zhTW', '準備開火！', '準備開火！', 28153),
(157132, 'zhTW', '多拉斯，我需要飛往塵泥沼澤的泥鏈營地。', '多拉斯，我需要飛往塵泥沼澤的泥鏈營地。', 28153),
(157131, 'zhTW', '砲台就緒！把那頭怪獸轟成肉泥！', '砲台就緒！把那頭怪獸轟成肉泥！', 28153),
(157130, 'zhTW', '不…不！', '不…不！', 28153),
(157129, 'zhTW', '真謝謝你！等我把這個大砲弄好就可以報仇了！', '真謝謝你！等我把這個大砲弄好就可以報仇了！', 28153),
(157128, 'zhTW', '札巴吉在打鼾。', '札巴吉在打鼾。', 28153),
(157127, 'zhTW', '感謝救命之恩！快幫我爭取時間，我要把大砲準備好！', '呼，感謝救命之恩！快幫我爭取時間，我要把大砲準備好！', 28153),
(157126, 'zhTW', '這全是一場夢嗎？', '這全是一場夢嗎？', 28153),
(157125, 'zhTW', '我不想被海怪吃掉！', '我不想被海怪吃掉！', 28153),
(157124, 'zhTW', '將他們全都燒焦！', '', 28153),
(157123, 'zhTW', '幫我把這東西弄掉！', '幫我把這東西弄掉！', 28153),
(157122, 'zhTW', '$p，拿一把火炬，看到會動的東西就打。這些不死怪物不值得我們留情！', '', 28153),
(157121, 'zhTW', '對，士兵。而在這個不潔的港口有殺不完的怪物。', '', 28153),
(157120, 'zhTW', '救命！', '救命！', 28153),
(157119, 'zhTW', '沒有人會來搶我們的擊殺戰功，長官。', '', 28153),
(157118, 'zhTW', '你是誰？我們在哪裡？', '你是誰？我們在哪裡？', 28153),
(157117, 'zhTW', '沒有人會來支援。如果我們搞砸了，救援也就沒了。', '', 28153),
(157116, 'zhTW', '聽好了，士兵們。這是未經授權的任務。', '', 28153),
(157115, 'zhTW', '你還在等什麼，$p？\n\n我們有武器，也有敵人。上船！', '你還在等什麼，$p？\n\n我們有武器，也有敵人。上船！', 28153),
(157114, 'zhTW', '疲倦的亞昆達打鼾。', '疲倦的亞昆達打鼾。', 28153),
(157113, 'zhTW', '我們都是…亞昆達。', '我們都是…亞昆達。', 28153),
(157112, 'zhTW', '還有工作要做？', '', 28153),
(157111, 'zhTW', '好的。', '', 28153),
(157110, 'zhTW', '好的。', '', 28153),
(157109, 'zhTW', '是的，大人。', '', 28153),
(157108, 'zhTW', '', '是的，長官。', 28153),
(157107, 'zhTW', '好。我們自己先行動吧。如果她沒有及時醒來…準備好你的武器。', '', 28153),
(157106, 'zhTW', '', '她需要一點…時間來重新適應。', 28153),
(157105, 'zhTW', '', '咳…呃…', 28153),
(157104, 'zhTW', '史東，行行好，跟我們說這座墓園最重要戰爭英雄的名字。', '', 28153),
(157103, 'zhTW', '你既然來了，我們就能開始了。', '', 28153),
(157102, 'zhTW', '為你的兄弟姊妹而戰！', '為你的兄弟姊妹而戰！', 28153),
(157101, 'zhTW', '聯盟必勝！', '聯盟必勝！', 28153),
(157100, 'zhTW', '奮勇作戰！', '奮勇作戰！', 28153),
(157099, 'zhTW', '勇士，謝謝你幫忙處理這件麻煩事。今晚大家都可以平安回家了。', '', 28153),
(157098, 'zhTW', '阿拉希是我們的！', '阿拉希是我們的！', 28153),
(157097, 'zhTW', '殺死部落！', '殺死部落！', 28153),
(157096, 'zhTW', '跟我來！', '跟我來！', 28153),
(157095, 'zhTW', '為了聯盟！', '為了聯盟！', 28153),
(157094, 'zhTW', '走這邊！我們有仗要打呢！', '走這邊！我們有仗要打呢！', 28153),
(157093, 'zhTW', '這附近的部落勢力把野生動物趕到平地去了。快去幫獵人對付這些熊。', '', 28153),
(157092, 'zhTW', '你…你讓我殺了我的朋友！現在你會死！', '', 28153),
(157091, 'zhTW', '兄弟姐妹們，記住我們光榮的使命！', '', 28153),
(157090, 'zhTW', '感謝你，朋友。山谷與你同在。', '我真的很高興見到你，$p。我會記得這件事的。', 28153),
(157089, 'zhTW', '我現在可以自己找路出去。小心。', '見到你真好！', 28153),
(157088, 'zhTW', '我以為我掛定了！', '謝謝你，我不會忘記此事的。', 28153),
(157087, 'zhTW', '哈哈！那些野豬很不錯嘛。不知道牠們喜不喜歡蒸蛤蜊…', '', 28153),
(157086, 'zhTW', '我們在沼澤外發現一些沒人看管的野豬。如果你能騎到野豬身上，你就可以對付野豬人了！', '', 28153),
(157085, 'zhTW', '替我復仇…塔塔夫…', '', 28153),
(157084, 'zhTW', '', '折磨…終於…結束了…', 28153),
(157083, 'zhTW', '', '終於…自由…', 28153),
(157082, 'zhTW', '', '這…是個陷阱…', 28153),
(157081, 'zhTW', '', '呵…獵人變成獵物了…', 28153),
(157080, 'zhTW', '', '我們都逃不出祂的掌握…', 28153),
(157079, 'zhTW', '陛下，請等一下！我剛收到了最新的情報。', '', 28153),
(157078, 'zhTW', '', '這不…應該…是這樣的…', 28153),
(157077, 'zhTW', '', '獵物自己上門還真是省了我的事！', 28153),
(157076, 'zhTW', '', '看看是誰走進了我的陷阱！', 28153),
(157075, 'zhTW', '', '你有點小，但我還是會奪走你的獸皮！', 28153),
(157074, 'zhTW', '', '他們答應給我森林裡所有的寶物！', 28153),
(157073, 'zhTW', '', '你的毛皮能賣好價錢！', 28153),
(157072, 'zhTW', '', '又有毛皮可以拿了！', 28153),
(157071, 'zhTW', '你必死…無疑…', '', 28153),
(157070, 'zhTW', '我回歸大地…', '', 28153),
(157069, 'zhTW', '終局…來臨了…', '', 28153),
(157068, 'zhTW', '你要什麼？噓！走開！', '', 28153),
(157067, 'zhTW', '我的靈魂…受到感染…', '', 28153),
(157066, 'zhTW', '帷幕墜下了…', '', 28153),
(157065, 'zhTW', '瑟洛斯將吞噬我們全部！', '', 28153),
(157064, 'zhTW', '彼界神祉說話了！', '', 28153),
(157063, 'zhTW', '復仇，然後取走你的寶藏！', '', 28153),
(157062, 'zhTW', '是的，拿起火炬上工，$p！', '是的，拿起火炬上工，$p！', 28153),
(157061, 'zhTW', '是的，我們將大肆破壞，然後把他們全部送進黑暗的海底深淵！', '', 28153),
(157060, 'zhTW', '所以我們將燒毀他們，對吧？', '所以我們將燒毀他們，對吧？', 28153),
(157059, 'zhTW', '我們贊姆蘭港的那些受詛咒的老船員將在今天派出大型的突擊隊，而我們是他們其中一個目標。', '', 28153),
(157058, 'zhTW', '歡迎回到鹹水，我的好戰友！', '', 28153),
(157057, 'zhTW', '用力划！', '用力划！', 28153),
(157056, 'zhTW', '我只要想出這項咒語，或許他們就會讓我回去。那這個呢…塔‧厄格西‧萊納德！', '', 28153),
(157055, 'zhTW', '塔塔夫，如果你聽得懂的話，很抱歉把你變形成這樣，嗯，永久變成這樣。', '', 28153),
(157054, 'zhTW', '我想知道你的名字有沒有效，塔塔夫。來試試看吧，諾倫‧艾希‧塔塔夫！', '', 28153),
(157053, 'zhTW', '太不公平了，他們居然把我趕走，塔塔夫。我要讓他們見識我強大的力量…呃…如果我能想起來的話。', '', 28153),
(157052, 'zhTW', '嗯…不，似乎不是這樣。', '', 28153),
(157051, 'zhTW', '我忘記那該死的咒語了。你說那叫什麼咒語，塔塔夫？萊納德如何如何…諾斯法楚格？', '', 28153),
(157050, 'zhTW', '我可是眼界大開了！', '', 28153),
(157049, 'zhTW', '你的鮮血會滋養這片森林！', '', 28153),
(157048, 'zhTW', '啊啊啊啊啊！', '', 28153),
(157047, 'zhTW', '做得好。希望有一天這裡能再用來舉行儀祭典禮。', '', 28153),
(157046, 'zhTW', '這裡的魔法如果不好好處理會汙染附近所有水源。請盡量拖延浪潮賢者。', '', 28153),
(157045, 'zhTW', '希望海潮能帶走他們迷失的靈魂，讓他們最終得以安息。', '', 28153),
(157044, 'zhTW', '有些人把斯陀頌恩家族的黑暗力量帶到了這裡。殺掉這些人，別讓他們有機會造成災難。', '', 28153),
(157043, 'zhTW', '做得好！我從這裡都看得到煙！我們盡快準備好，再次發動攻擊。', '', 28153),
(157042, 'zhTW', '希望你跟獅鷲獸相處愉快！去找貝兒娜黛特‧羅布斯。她已經擬定戰牙堡攻擊部落軍隊的計畫了。', '', 28153),
(157041, 'zhTW', '', '啊？', 28153),
(157040, 'zhTW', '沒有羅亞幫忙你就沒有力量！快殺了他！', '', 28153),
(157039, 'zhTW', '敵人有瑞贊的神力保護！我一定會把這股神力奪回來！', '', 28153),
(157038, 'zhTW', '內陸人，別忘了對深海的生物心懷恐懼，活在黑暗陰影中的，絕非善類。', '', 28153),
(157037, 'zhTW', '有幾個浪潮賢者想召喚足以毀滅波拉勒斯的力量。趕快阻止他們！', '', 28153),
(157036, 'zhTW', '', '讓她帶頭，她會讓你安全抵達，平安離開。', 28153),
(157035, 'zhTW', '', '她準備好了！', 28153),
(157034, 'zhTW', '', '她是山谷裡速度最快的獅鷲獸。如果有人不同意，他們就是在撒謊。', 28153),
(157033, 'zhTW', '下一個就輪到你了！', '下一個就輪到你了！', 28153),
(157032, 'zhTW', '你跟那隻鳥都不友善。', '你跟那隻鳥都不友善。', 28153),
(157031, 'zhTW', '我也想要飛！', '我也想要飛！', 28153),
(157030, 'zhTW', '我恨聯盟。', '我恨聯盟。', 28153),
(157029, 'zhTW', '看！好漂亮的鳥。', '看！好漂亮的鳥。', 28153),
(157028, 'zhTW', '', '歸源驅動裝置已經準備完成了。現在，我們即將要徹底消滅古翰造成的瘟疫災難。', 28153),
(157027, 'zhTW', '這台歸源驅動裝置真是太讚了。我們快使用它來剷除古翰這個噁心的毒瘤吧。', '', 28153),
(157026, 'zhTW', '是我…被殺死？', '是我…被殺死？', 28153),
(157025, 'zhTW', '卑微的小廝！我會像蟲一樣壓碎你！', '卑微的小廝！我會像蟲一樣壓碎你！', 28153),
(157024, 'zhTW', '讓我離開這裡！', '讓我離開這裡！', 28153),
(157023, 'zhTW', '恐角龍幼獸怒吼一聲，然後逃向牠的母親！', '恐角龍幼獸怒吼一聲，然後逃向牠的母親！', 28153),
(157022, 'zhTW', '收留我！', '收留我！', 28153),
(157021, 'zhTW', '要載你嗎？', '要載你嗎？', 28153),
(157020, 'zhTW', '', '元帥把你訓練得很好，他一定會以你為傲的。', 28153),
(157019, 'zhTW', '', '謝謝你，小姐。我不會讓你失望的。', 28153),
(157018, 'zhTW', '', '我在此宣布你升任為科利爾東元帥，統領所有的威奎斯特守衛。', 28153),
(157017, 'zhTW', '', '往後佐司瓦還會需要你來擔負更重要的職責。', 28153),
(157016, 'zhTW', '', '審判官科利爾東，你的表現令人激賞，也展現出無比的慈悲、勇氣、智慧和領導風範。', 28153),
(157015, 'zhTW', '', '雖然生離死別讓人傷痛，但希望的火苗還在燃燒。', 28153),
(157014, 'zhTW', '不是針對你。', '不是針對你。', 28153),
(157013, 'zhTW', '我們的敵人控制了元素之環…只是暫時的。', '我們的敵人控制了元素之環…只是暫時的。', 28153),
(157012, 'zhTW', '我在元素之環看到了部落的部落旌旗！', '我在元素之環看到了部落的部落旌旗！', 28153),
(157011, 'zhTW', '部落已經控制了元素之環了！', '部落已經控制了元素之環了！', 28153),
(157010, 'zhTW', '元素之環帶著我們的旗幟！', '元素之環帶著我們的旗幟！', 28153),
(157009, 'zhTW', '我們的部隊控制著元素之環。', '我們的部隊控制著元素之環。', 28153),
(157008, 'zhTW', '元素之環依然在我們控制之下。', '元素之環依然在我們控制之下。', 28153),
(157007, 'zhTW', '紐沃農莊帶著部落的旗幟…暫時如此。', '紐沃農莊帶著部落的旗幟…暫時如此。', 28153),
(157006, 'zhTW', '那些禽獸認為自己能控制紐沃農莊？我們會讓他們知道厲害…', '那些禽獸認為自己能控制紐沃農莊？我們會讓他們知道厲害…', 28153),
(157005, 'zhTW', '那些惡魔無法永遠佔據紐沃農莊。', '那些惡魔無法永遠佔據紐沃農莊。', 28153),
(157004, 'zhTW', '我們的軍力已經掌控了紐沃農莊。', '我們的軍力已經掌控了紐沃農莊。', 28153),
(157003, 'zhTW', '紐沃農莊在我們控制之下。', '紐沃農莊在我們控制之下。', 28153),
(157002, 'zhTW', '看來我們已控制了紐沃農莊。最好繼續保持下去。', '看來我們已控制了紐沃農莊。最好繼續保持下去。', 28153),
(157001, 'zhTW', '帝王羅亞已經殞落。若我們要發動另一次獵捕，就必須小心謹慎。\n\n拉斯塔哈傷勢嚴重，並且快速老化。只有瑞贊的力量能讓伯昂撒姆第不敢進犯。我會向他獻出我的力量，但要挑戰掌管死亡的羅亞非我領域所及。', '', 28153),
(157000, 'zhTW', '什麼事，女士？', '', 28153),
(156999, 'zhTW', '', '獸王洛卡拉疑心地打量她旁邊的哥布林。', 28153),
(156998, 'zhTW', '', '看來你的小東西在打了這麼久後累壞了。這裡很安全，我會親自照料牠。', 28153),
(156996, 'zhTW', '恐角龍寶寶打了呵欠，然後閉上眼睛。', '恐角龍寶寶打了呵欠，然後閉上眼睛。', 28153),
(156995, 'zhTW', '該離開了！', '該離開了！', 28153),
(156994, 'zhTW', '感覺好像有人將我的靈魂整個從身體裡面抽出來一樣。', '', 28153),
(156993, 'zhTW', '真是好險！感謝相助！', '真是好險！感謝相助！', 28153),
(156992, 'zhTW', '感謝相助！我的防黏軟靴不曉得為什麼故障了。', '感謝相助！我的防黏軟靴不曉得為什麼故障了。', 28153),
(156991, 'zhTW', '非常感謝你！我一回去就會提出回報。這次遠征所遭遇到的物流障礙，遠超過我們簡報的程度。', '非常感謝你！我一回去就會提出回報。這次遠征所遭遇到的物流障礙，遠超過我們簡報的程度。', 28153),
(156990, 'zhTW', '老天，之後我一定會被關進自動清潔機整整一個禮拜！', '老天，之後我一定會被關進自動清潔機整整一個禮拜！', 28153),
(156989, 'zhTW', '那真是棘手的狀況！感謝你！', '那真是棘手的狀況！感謝你！', 28153),
(156988, 'zhTW', '願大海祝福這塊礦石，願大海永不取回它曾賜予祝福的東西。', '願大海祝福這塊礦石，願大海永不取回它曾賜予祝福的東西。', 28153),
(156987, 'zhTW', '你能祝福這些風暴白銀錠嗎？', '你能祝福這些風暴白銀錠嗎？', 28153),
(156986, 'zhTW', '沒有人敢認為被遺忘者是他們重新來過的機會。', '', 28153),
(156985, 'zhTW', '我不喜歡你話中的意思，札林。', '', 28153),
(156984, 'zhTW', '耶！甲殼類的力量！', '', 28153),
(156983, 'zhTW', '看來你得去找個殼躲躲了。懂嗎？殼？螃蟹？勝利是我的了！', '', 28153),
(156982, 'zhTW', '這不可接受！你還沒有見識到荷米斯隊長和他兇猛的螃蟹三人幫最後手段！', '', 28153),
(156981, 'zhTW', '怎麼可能？', '', 28153),
(156980, 'zhTW', '終於啊，有挑戰者上場了！', '', 28153),
(156979, 'zhTW', '航向斯陀頌恩谷地。', '航向斯陀頌恩谷地。', 28153),
(156978, 'zhTW', '航向提拉加德海灣。', '航向提拉加德海灣。', 28153),
(156977, 'zhTW', '航向佐司瓦。', '航向佐司瓦。', 28153),
(156976, 'zhTW', '…幹嘛？', '', 28153),
(156974, 'zhTW', '那個紅衣服的傢伙說我不夠「正史」。哼，這不是廢話嗎！我是水手，才不管什麼正不正式！', '', 28153),
(156973, 'zhTW', '你能為我再做一次庫爾提拉斯的簡報嗎？', '你能為我再做一次庫爾提拉斯的簡報嗎？', 28153),
(156972, 'zhTW', '我們一定會撥亂反正。', '', 28153),
(156971, 'zhTW', '', '好，要我怎麼幫你？', 28153),
(156970, 'zhTW', '做得好！這下絕對讓他們的詭計泡湯了。', '', 28153),
(156969, 'zhTW', '你也聽到大海的呼喚嗎？', '', 28153),
(156968, 'zhTW', '我必須知道我的家人是否安好！<咳嗽>', '', 28153),
(156967, 'zhTW', '', '我說不要測試我的－－', 28153),
(156966, 'zhTW', '聽說沼澤附近有某種可怕的植物怪。我們的機械農場幫手應該可以把怪物輕鬆解決掉吧。', '', 28153),
(156965, 'zhTW', '願大海指引你回家的路。', '', 28153),
(156964, 'zhTW', '你找普勞德摩爾家族有什麼請求？', '', 28153),
(156963, 'zhTW', '航向祖達薩。', '航向祖達薩。', 28153),
(156962, 'zhTW', '航向納茲米爾。', '航向納茲米爾。', 28153),
(156961, 'zhTW', '團結才有力量。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156960, 'zhTW', '我會為先父帶來榮耀。', '', 28153),
(156959, 'zhTW', '我在海邊花了好幾年時間尋找這個世界上最最致命的寄居蟹。你是想打一場，還是怕被打得落花流水？', '', 28153),
(156958, 'zhTW', '做得好。我們會叫我們最優秀的研究人員開始研析這些手稿。感謝你。', '', 28153),
(156957, 'zhTW', '戰鬥法師在死者身上看到一些托爾托魔法卷軸。在部落發現這件事之前，我們必須趕快行動，把卷軸帶回來。', '', 28153),
(156956, 'zhTW', '聯盟控制了激流堡！', '聯盟控制了激流堡！', 28153),
(156955, 'zhTW', '喂，$n！在這裡！', '', 28153),
(156954, 'zhTW', '你好啊，$p。我聽說你跟老基羅與狐狸人關係不錯。\n\n我們沒時間進行漫長的談判，因此我相信基羅對你的評語。\n\n若你想在廣闊的海洋上享受一下劫掠的樂趣，歡迎加入我的船員。\n\n準備好就跳上船，我們會開始啟航。', '', 28153),
(156953, 'zhTW', '真有意思…我會立刻讓法師仔細研究一下這個卷軸，謝謝你！', '', 28153),
(156952, 'zhTW', '喂，$p！真高興又見到你。\n\n你還想再來點海洋掠奪行動嗎？贊姆蘭正在號令他的船員登艦，而這讓他們輕易地成為我們的肉靶…若你瞄的準的話。\n\n不過我曾看過你作戰，因此我知道你能迅速解決這些無恥的骷髏。\n\n當你準備好的時候就跳上船。', '', 28153),
(156951, 'zhTW', '我將返回風之救贖。當你準備好返回波拉勒斯時，就跟上將說一聲。', '', 28153),
(156950, 'zhTW', '我常年在海上尋找兇殘程度前所未見的螃蟹，想看看你的寵物多快就會被沖走嗎？', '', 28153),
(156949, 'zhTW', '$n！我能幫你什麼忙嗎？', '', 28153),
(156948, 'zhTW', '這是什麼？', '這是什麼？', 28153),
(156947, 'zhTW', '$n！很高興能再見到你，自從上次在德拉諾為你效力後，已經過了很長一段時間。', '', 28153),
(156946, 'zhTW', '庫爾提拉斯會知道恐懼為何物！', '', 28153),
(156945, 'zhTW', '什麼…甚至…', '什麼…甚至…', 28153),
(156944, 'zhTW', '噁！好苦！', '噁！好苦！', 28153),
(156943, 'zhTW', '嚐起來像是…鉤子…', '嚐起來像是…鉤子…', 28153),
(156942, 'zhTW', '我是什麼？…一個維酷人？<嗝！>', '我是什麼？…一個維酷人？<嗝！>', 28153),
(156941, 'zhTW', '我…討厭…<嗝！> 淡啤酒…', '我…討厭…<嗝！> 淡啤酒…', 28153),
(156940, 'zhTW', '開啟傳送門，召來我們的部隊。', '開啟傳送門，召來我們的部隊。', 28153),
(156939, 'zhTW', '很榮幸能為部落效力，作為我持續在歐庫雷斯底下研究傳送術的一部分。\n\n我也很榮幸能在工作完成盡快離開這個地方。', '', 28153),
(156938, 'zhTW', '我的獵犬…只會…吠叫…不會咬人…', '我的獵犬…只會…吠叫…不會咬人…', 28153),
(156937, 'zhTW', '非常好，找到獵物了！', '非常好，找到獵物了！', 28153),
(156936, 'zhTW', '往護符裡灌注力量吧…這也許是拯救艾澤拉斯的唯一方法。', '', 28153),
(156935, 'zhTW', '你感覺到了嗎？這股…震動…', '', 28153),
(156934, 'zhTW', '', '目標：艾澤拉斯。偵測到嚴重心律不整。\n\n生命力超過可接受參數。\n\n嘗試更新事故回報…\n\n錯誤，錯誤，錯誤，錯誤。', 28153),
(156933, 'zhTW', '呼！這還真烈！', '', 28153),
(156932, 'zhTW', '嗯…讓我想起…我還是礦工的時候…訣竅是用你的工具從特定的角度敲打…讓...礦石…', '', 28153),
(156931, 'zhTW', '', '警告：已登錄多個隔離失效場所。\n\n建議銷毀下列設施：\n\n奧達曼、奧丹姆、奧多魯、奧杜亞、奧迪爾、奧達茲、奧…奧…奧…奧…', 28153),
(156930, 'zhTW', '呃…那不合我的胃口：', '', 28153),
(156929, 'zhTW', '再重複一次，根據我的計算結果，我們的成功率已經下降2.539%，我們必須快點進行維修！', '再重複一次，根據我的計算結果，我們的成功率已經下降2.539%，我們必須快點進行維修！', 28153),
(156928, 'zhTW', '來嘛！修好那些坦克！我們現在進度落後！', '來嘛！修好那些坦克！我們現在進度落後！', 28153),
(156927, 'zhTW', '動作快，大家！在部落發現我們之前，我們只有一點時間部署好這些攻城坦克。', '動作快，大家！在部落發現我們之前，我們只有一點時間部署好這些攻城坦克。', 28153),
(156926, 'zhTW', '拿出少校的奶泡咖啡', '拿出少校的奶泡咖啡', 28153),
(156925, 'zhTW', '拿出「極光」', '拿出「極光」', 28153),
(156924, 'zhTW', '提供苦澀暗根伏特加', '提供苦澀暗根伏特加', 28153),
(156923, 'zhTW', '拿出布瑞納丹蘋果白蘭地', '拿出布瑞納丹蘋果白蘭地', 28153),
(156922, 'zhTW', '拿出勾角地蒸餾酒', '拿出勾角地蒸餾酒', 28153),
(156921, 'zhTW', '拿出米爾頓霍爾蜜酒', '拿出米爾頓霍爾蜜酒', 28153),
(156920, 'zhTW', '拿出白果園淡啤酒', '拿出白果園淡啤酒', 28153),
(156919, 'zhTW', '拿出黑牙血酒', '拿出黑牙血酒', 28153),
(156918, 'zhTW', '帶我們回波拉勒斯。', '帶我們回波拉勒斯。', 28153),
(156917, 'zhTW', '', '噢，天啊，噢，天啊！我不會讓你失望的，$n，我發誓！', 28153),
(156916, 'zhTW', '', '呃，不好意思，是$n$G先生:女士;嗎？在這裡！', 28153),
(156915, 'zhTW', '噢，你需要什麼東西嗎？', '', 28153),
(156914, 'zhTW', '我們該從哪裡下手？', '', 28153),
(156913, 'zhTW', '帶我們回祖達薩。', '帶我們回祖達薩。', 28153),
(156912, 'zhTW', '', '你需要一艘船？送出消息？\n\n也許幫忙刺殺？', 28153),
(156911, 'zhTW', '走開，老兄…你看不出來…<嗝！> 我很忙嗎？', '', 28153),
(156910, 'zhTW', '', '目標：艾澤拉斯。\n\n警告：發生災難性系統故障。\n\n星球完整性於--\n\n計算中…計算中…計算中…', 28153),
(156909, 'zhTW', '這不在我的計算當中…', '這不在我的計算當中…', 28153),
(156908, 'zhTW', '根據我的計算結果，你的成功機率是…零！', '根據我的計算結果，你的成功機率是…零！', 28153),
(156907, 'zhTW', '', '勇士，那個野豬人身上有強大的魔精，但仍然不是你的對手。', 28153),
(156906, 'zhTW', '', '大地隨著野豬人薩滿的命令紛紛站起。趁還沒有影響到我們的計畫，快解決這個新威脅。', 28153),
(156905, 'zhTW', '斯陀頌恩的巨石變少了，我今晚總算能睡個好覺了。', '', 28153),
(156904, 'zhTW', '野生小翼手龍發出尖嘯聲示警！', '野生小翼手龍發出尖嘯聲示警！', 28153),
(156903, 'zhTW', '這裡有個野豬人喚地者正在召喚元素大軍。消滅元素大軍，消滅野豬人喚地者！', '', 28153),
(156902, 'zhTW', '謝謝你。我還以為我死定了。', '謝謝你。我還以為我死定了。', 28153),
(156901, 'zhTW', '真高興這世上還有好人。', '真高興這世上還有好人。', 28153),
(156900, 'zhTW', '謝謝！接下來的路我可以自己走。', '謝謝！接下來的路我可以自己走。', 28153),
(156899, 'zhTW', '為那些來不及獲救的人報仇。', '為那些來不及獲救的人報仇。', 28153),
(156898, 'zhTW', '你根本不知道他們如何折磨我們…', '你根本不知道他們如何折磨我們…', 28153),
(156897, 'zhTW', '你救了我的命！', '你救了我的命！', 28153),
(156896, 'zhTW', '非常感謝你。', '非常感謝你。', 28153),
(156895, 'zhTW', '我欠你一份人情。', '我欠你一份人情。', 28153),
(156894, 'zhTW', '你的勇氣無人可敵。', '你的勇氣無人可敵。', 28153),
(156893, 'zhTW', '我不會忘記你的善意。', '我不會忘記你的善意。', 28153),
(156892, 'zhTW', '你來得正是時候！', '你來得正是時候！', 28153),
(156891, 'zhTW', '我會記住你這份恩情。', '我會記住你這份恩情。', 28153),
(156890, 'zhTW', '我欠你一條命。', '我欠你一條命。', 28153),
(156889, 'zhTW', '我最好回去作戰。', '我最好回去作戰。', 28153),
(156888, 'zhTW', '徹底攪拌，直到滑順為止！', '', 28153),
(156887, 'zhTW', '混入井水裡！', '', 28153),
(156886, 'zhTW', '最後加熱！', '', 28153),
(156885, 'zhTW', '增添一點風味！', '', 28153),
(156884, 'zhTW', '現在一次一個！', '', 28153),
(156883, 'zhTW', '這個山谷值得一救。', '', 28153),
(156882, 'zhTW', '你有多餘的補給品嗎？', '你有多餘的補給品嗎？', 28153),
(156881, 'zhTW', '瑞贊他…他…他死了。那個…那個玩意兒根本不是羅亞。', '', 28153),
(156880, 'zhTW', '啊！勇士，這個地方嚴重受損，看來撐不了多久了！', '', 28153),
(156879, 'zhTW', '麥格尼，庫爾提拉斯的情況很危急。但我想…你是為了其他原因才來的。', '', 28153),
(156878, 'zhTW', '', '我把我的釣竿放到哪裡去了？我發誓它剛剛就在這裡…', 28153),
(156877, 'zhTW', '', '只要知道地點的話，就能好好享受打獵和釣魚的樂趣。', 28153),
(156876, 'zhTW', '<微風吹過馬車側面，破爛的木板發出咯吱咯吱聲。\n\n其中一個車輪似乎卡住了。>', '', 28153),
(156875, 'zhTW', '<推一下礦車。>', '<推一下礦車。>', 28153),
(156874, 'zhTW', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|t你正在靠近部落艦艇，小心一點！', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|t你正在靠近部落艦艇，小心一點！', 28153),
(156873, 'zhTW', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|t你正在靠近聯盟艦艇，小心一點！', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|t你正在靠近聯盟艦艇，小心一點！', 28153),
(156872, 'zhTW', '', '這道牆必須傾倒，大海將會回歸。', 28153),
(156871, 'zhTW', '$n…去別的地方幫忙吧，如果再次需要你，我會通知你。', '', 28153),
(156870, 'zhTW', '莉莉安、史東，過來一下，幫我鎖定其中一個…浪潮賢者。', '', 28153),
(156869, 'zhTW', '這些一再出現的阻礙實在讓我煩不勝煩。', '', 28153),
(156868, 'zhTW', '好吧，$n？你有什麼發現？送過來吧。', '', 28153),
(156867, 'zhTW', '好了，英雄，你應該還有事情要忙。你可以用傳送器傳回盟友身邊。祝你好運…祝我們大家好運。', '', 28153),
(156866, 'zhTW', '我繼續找找看有沒有方法可以修復艾澤拉斯的傷口。如果我需要你，我會透過護符找你。', '', 28153),
(156865, 'zhTW', '勇士，記得把這個護符貼身收好。它能幫你度過即將到來的黑暗。', '', 28153),
(156864, 'zhTW', '所以說我們只需要能追蹤到他的東西。', '', 28153),
(156863, 'zhTW', '', '堡壘的外牆會在你的猛攻下碎裂。', 28153),
(156862, 'zhTW', '', '看到信號就攻擊牆壁，史科洛斯。', 28153),
(156861, 'zhTW', '', '你會因有所貢獻而獲得獎勵。', 28153),
(156860, 'zhTW', '', '阿瑪麗亞，記得告訴這裡的納薩諾斯有關浪潮賢者的事。', 28153),
(156859, 'zhTW', '', '利用一下…就能找到…船艦殘骸…', 28153),
(156858, 'zhTW', '', '浪潮賢者…海之…牧師…', 28153),
(156857, 'zhTW', '', '啊，我相信我們已經談過那件事了。', 28153),
(156856, 'zhTW', '消失在茫茫大海！我們需要他的屍體！', '', 28153),
(156855, 'zhTW', '', '莫·瓦倫泰元帥…第二次獸人戰爭的勝利者…消失在茫茫大海…', 28153),
(156854, 'zhTW', '我想回到提拉加德海灣。', '我想回到提拉加德海灣。', 28153),
(156853, 'zhTW', '在你離開去辦自己的事的時候，我會確保航行順利。', '', 28153),
(156851, 'zhTW', '屍體在哪裡？', '', 28153),
(156850, 'zhTW', '等等…這是什麼？', '', 28153),
(156849, 'zhTW', '啊，瓦倫泰，你躲我們躲好一陣子了。', '', 28153),
(156848, 'zhTW', '我們不該讓Valentine等。', '', 28153),
(156847, 'zhTW', '塞伯創啟動…呃！', '', 28153),
(156846, 'zhTW', '什麼…我們還沒準備好！', '', 28153),
(156845, 'zhTW', '塞伯創無人能敵！', '', 28153),
(156844, 'zhTW', '五隻迷你貓結合成一隻超級貓！', '', 28153),
(156843, 'zhTW', '你別想再繼續控制下去了。', '', 28153),
(156842, 'zhTW', '邪惡的暗影，滾開！', '', 28153),
(156841, 'zhTW', '海潮會吞沒你邪惡的血肉！', '', 28153),
(156840, 'zhTW', '', '別讓他們傷害點點！', 28153),
(156839, 'zhTW', '', '救命啊！', 28153),
(156838, 'zhTW', '航向沃魯敦。', '航向沃魯敦。', 28153),
(156837, 'zhTW', '就算牠死了…晚上還是會讓我做噩夢。', '', 28153),
(156836, 'zhTW', '那個…呃…東西！快殺！快用火殺！', '', 28153),
(156835, 'zhTW', '|A:Warfront-AllianceWave3:25:23:0:0|a聯盟部署了一支突襲隊！', '|A:Warfront-AllianceWave3:25:23:0:0|a聯盟部署了一支突襲隊！', 28153),
(156834, 'zhTW', '塞斯拉克人在沙漠發現了米若的行蹤，她只有一個人，要是遭受攻擊的話，一定會很需要援手。', '', 28153),
(156833, 'zhTW', '', '奉黑暗女王的意志，我悉聽遵令。', 28153),
(156832, 'zhTW', '', '把這個人帶回去。他獲選成為被遺忘者。', 28153),
(156831, 'zhTW', '莉莉安。我們能找到其他的浪潮賢者。你知道他的家人不會接受他的。', '', 28153),
(156830, 'zhTW', '', '莉莉安·佛斯。你為何傳喚我？', 28153),
(156829, 'zhTW', '小小的不便，證明那不會影響我們的計畫。', '', 28153),
(156828, 'zhTW', '想要是一個很重的詞，只有對我的家人有益…我才願意承擔這個詞。', '', 28153),
(156827, 'zhTW', '', '極為痛苦地。', 28153),
(156826, 'zhTW', '但一部分的你活下來了，對吧？', '', 28153),
(156825, 'zhTW', '', '希望你活得夠久，幫我們找到瓦倫泰。', 28153),
(156824, 'zhTW', '走吧！', '走吧！', 28153),
(156823, 'zhTW', '', '我們可以徵召更多的部落軍隊，你只要下令就好。', 28153),
(156822, 'zhTW', '呼呼，請務必做到。', '', 28153),
(156821, 'zhTW', '', '我會去接她，納薩諾斯。別管我們，繼續進行。', 28153),
(156820, 'zhTW', '', '住手！', 28153),
(156819, 'zhTW', '', '啊啊啊啊！', 28153),
(156818, 'zhTW', '', '我…我沒辦法…', 28153),
(156817, 'zhTW', '', '我認為這是個好的開始，看看你還能做些什麼。', 28153),
(156816, 'zhTW', '聯盟和庫爾提拉斯部隊駐守在賢者崗，他們正在等待援軍到來，現在正是最脆弱的時候。', '', 28153),
(156815, 'zhTW', '我的家人安全嗎？', '', 28153),
(156814, 'zhTW', '', '很好，證明你對部落的價值，我們就讓你活久一點。', 28153),
(156813, 'zhTW', '他們很安全。幫我們，我們就會繼續確保他們的安全。', '', 28153),
(156812, 'zhTW', '<咳嗽> 我…我會盡我所能，佛斯小姐。妳想找到某個人或某個東西，對吧？讓我看看我沒有我的書時能做到什麼…', '', 28153),
(156811, 'zhTW', '', '別試圖考驗我的耐心，不然我會讓你痛不欲生。我必須先瞭解你的魔法才能，我們再來談。', 28153),
(156810, 'zhTW', '佛斯小姐，你是否生了病？在你歸來時，生前就有的病？', '', 28153),
(156809, 'zhTW', '', '莉莉安·佛斯，我才是提問的人，你能夠追查人還是物體嗎？', 28153),
(156808, 'zhTW', '成為被遺忘者。或許這是個<咳嗽>預兆。告訴我…', '', 28153),
(156807, 'zhTW', '', '大致上，$n說的對，只要你幫忙我們，你就不會受傷，最好在你死前。', 28153),
(156806, 'zhTW', '願黑暗女王眷顧你。', '', 28153),
(156805, 'zhTW', '我需要援軍。', '我需要援軍。', 28153),
(156804, 'zhTW', '需要增援部隊嗎？請下令，我就會從暴風城把兵運過去。', '', 28153),
(156803, 'zhTW', '我們沒時間了，需要什麼東西？', '', 28153),
(156802, 'zhTW', '你的生存能力…比那個敵人強太多了。', '', 28153),
(156801, 'zhTW', '我們的行動算不上有計畫，快解決這個威脅，還要保住自己的小命。', '', 28153),
(156799, 'zhTW', '%s嘎吱嘎吱地吃掉新鮮食物。', '', 28153),
(156798, 'zhTW', '%s津津有味地咀嚼葉片。', '', 28153),
(156797, 'zhTW', '%s把它的口鼻部埋入食物中。', '', 28153),
(156796, 'zhTW', '我要打扁你的腦袋！', '我要打扁你的腦袋！', 28153),
(156795, 'zhTW', '下個要受死的是誰？', '下個要受死的是誰？', 28153),
(156794, 'zhTW', '走吧！', '走吧！', 28153),
(156793, 'zhTW', '[過場動畫] - 珍娜抵達！她的部隊成功轟掉羅德隆城堡的城牆！順便一提，那簡直*超級*炫。', '[過場動畫] - 珍娜抵達！她的部隊成功轟掉羅德隆城堡的城牆！順便一提，那簡直*超級*炫。', 28153),
(156792, 'zhTW', '[過場動畫] - 安杜因抵達時，希瓦娜斯正在謁見廳等候。安杜因給她機會投降，但她反而炸掉整座城市。我是說，不然你以為呢？', '[過場動畫] - 安杜因抵達時，希瓦娜斯正在謁見廳等候。安杜因給她機會投降，但她反而炸掉整座城市。我是說，不然你以為呢？', 28153),
(156791, 'zhTW', '', '如果我能說服庫爾提拉斯重返聯盟…', 28153),
(156790, 'zhTW', '', '我們家族有全艾澤拉斯最強大的海軍。', 28153),
(156789, 'zhTW', '', '如果對象願意配合的話，這個法術不難。', 28153),
(156788, 'zhTW', '', '來吧，喝下這個。', 28153),
(156787, 'zhTW', '', '好啦，阿瑪麗亞，給我一點時間…', 28153),
(156786, 'zhTW', '我不是要殺你，是來這裡向你求助。', '我不是要殺你，是來這裡向你求助。', 28153),
(156785, 'zhTW', '<咳嗽> 部落。我想這裡就是我安息的地方。\n\n嗯？你在等什麼？', '', 28153),
(156784, 'zhTW', '', '嘿…$n，我的伐木機啊。', 28153),
(156783, 'zhTW', '我們必須快點，不然就得不到浪潮賢者的幫助了。', '', 28153),
(156782, 'zhTW', '', '不管你打算怎麼做，也不會比這場疫病還糟…他往東走了，想要靜靜地死去，不讓孩子們看見。求求你，別來打擾我們。', 28153),
(156781, 'zhTW', '我只想知道你的丈夫去了哪裡，我保證不會傷害你和你的家人。', '', 28153),
(156780, 'zhTW', '', '部落…你來這裡是為了從我身邊奪走更多東西嗎？我的丈夫快死了，而我身無分文…別傷害我的孩子，求求你。', 28153),
(156779, 'zhTW', '那樣毫無榮譽而言。我們只會用問的。不會為難哭泣的母親。', '', 28153),
(156778, 'zhTW', '這次或許需要後退一點！', '', 28153),
(156777, 'zhTW', '拿出大槍。', '', 28153),
(156776, 'zhTW', '我召來沙塵暴！', '', 28153),
(156775, 'zhTW', '你標記目標…', '', 28153),
(156774, 'zhTW', '我熱愛我的工作。', '', 28153),
(156773, 'zhTW', '哈哈！那傢伙這次終於遇上咬不動的對手了！', '', 28153),
(156772, 'zhTW', '大狗被放出來了。', '', 28153),
(156771, 'zhTW', '永遠不知道打中他們的是什麼。', '', 28153),
(156770, 'zhTW', '有人呼叫爆礦機過來嗎？', '', 28153),
(156769, 'zhTW', '你應該會喜歡這個！', '', 28153),
(156768, 'zhTW', 'AR-8已抵達。', '', 28153),
(156767, 'zhTW', '撐住！砍個幾刀。', '', 28153),
(156766, 'zhTW', '前往目標，狀態良好。', '', 28153),
(156765, 'zhTW', '', '蛤…', 28153),
(156764, 'zhTW', '', '你越快收集到這些花朵，我就越快能讓阿瑪麗亞派上用場。', 28153),
(156763, 'zhTW', '我聽說有隻巨大的蠕蟲在地面上到處吸收腐化、大肆破壞，如果你有看到的話，就立刻殺掉牠！', '', 28153),
(156762, 'zhTW', '孩子們都救出來了，他們現在都急著學你當英雄！', '', 28153),
(156761, 'zhTW', '一堆亡淘村的小孩跑去當海盜，結果被鐵潮的人當成囚犯關起來了！請你把他們救出來！', '', 28153),
(156760, 'zhTW', '', '哎…$n，來這裡！', 28153),
(156759, 'zhTW', '', '這世界上又少了可以傷害人民的怪獸。羅亞對你的作為很滿意。', 28153),
(156758, 'zhTW', '', '聽說有蟲子在吞食腐化，為大地帶來重大災害。我們見一個殺一個！', 28153),
(156757, 'zhTW', '他們說那裡有糖果？', '我現在是海盜了嗎？', 28153),
(156756, 'zhTW', '聽著，老闆，我知道你要贊助這場遠征，但是加里維克斯會想要確定黑暗女王拿到她的份。', '', 28153),
(156755, 'zhTW', '我需要前往哀塚墓園。', '我需要前往哀塚墓園。', 28153),
(156754, 'zhTW', '', '我拿到全庫爾提拉斯最安全的煙花！$b$b別被姓氏愚弄了。', 28153),
(156753, 'zhTW', '撤退！活著就有機會再戰。', '', 28153),
(156752, 'zhTW', '贊達拉，後退整隊！就讓他們多活幾天沒關係。', '', 28153),
(156751, 'zhTW', '消滅那些入侵者！', '', 28153),
(156750, 'zhTW', '你們真是弱！', '', 28153),
(156749, 'zhTW', '你的死期將至！', '', 28153),
(156748, 'zhTW', '我是恐怖海盜畢伍佛！永遠不留活口！', '我想我看到我的貓！', 28153),
(156747, 'zhTW', '踏進暴風圈吧，我們該結束這一切了。', '', 28153),
(156746, 'zhTW', '你不是海盜！', '他們說他們會送我一頂帽子！', 28153),
(156745, 'zhTW', '啊哈！給我一杯蘭姆酒！', '我必須去船尾甲板上！', 28153),
(156744, 'zhTW', '', '好吧，你不想弄髒雙手也罷。', 28153),
(156743, 'zhTW', '我想回到祖達薩。', '我想回到祖達薩。', 28153),
(156742, 'zhTW', '我會把帆揚起，方便我們迅速出航。去搶艾澤萊晶岩吧！', '', 28153),
(156741, 'zhTW', '', '$n，我會處理屍體，你回去找納薩諾斯，告訴他一切都照計畫進行。', 28153),
(156740, 'zhTW', '我不會參與把這個人轉化成被遺忘者的事，你自己動手。', '我不會參與把這個人轉化成被遺忘者的事，你自己動手。', 28153),
(156739, 'zhTW', '', '你將學會處理，我會在旁協助。', 28153),
(156738, 'zhTW', '我不值得救！', '我現在是海盜，不需要聽你的話。', 28153),
(156737, 'zhTW', '', '你現在是我們的一員，他們不會接納你。', 28153),
(156736, 'zhTW', '莉莉安，你殺死了澤靈。', '莉莉安，你殺死了澤靈。', 28153),
(156735, 'zhTW', '', '史東，我知道你經歷過什麼，你不能像我之前一樣，讓這個改變佔據你的心靈。', 28153),
(156734, 'zhTW', '不公平！我本想成為一個海盜。', '最好把我賣給海盜！', 28153),
(156733, 'zhTW', '莉莉安，對Zelling做你該做的事。', '莉莉安，對Zelling做你該做的事。', 28153),
(156732, 'zhTW', '', '等著看吧，說不定會不同…也許就這一次。', 28153),
(156731, 'zhTW', '', '很可怕。你身邊的人將會對你永遠改觀，當你看著鏡子，你只會看到一隻怪物，是你而不是你的怪物。', 28153),
(156730, 'zhTW', '拜託你…我需要…照顧…我的家人…無論如何…', '', 28153),
(156729, 'zhTW', '', '如果你變成我們，大家都會怕你。你照鏡子的時候，只會看到一個怪物。', 28153),
(156728, 'zhTW', '佛斯小姐，<咳>求求你…帶我回去…我一定要救我的家人…我什麼都願意做…', '', 28153),
(156727, 'zhTW', '', '什麼？你的家人會認為你是怪物的，別胡說了！', 28153),
(156726, 'zhTW', '', '好，我的確有想要知道的事。', 28153),
(156725, 'zhTW', '<喘氣>我很…抱歉。我…不行了…我已經完全…沒有力氣了…', '', 28153),
(156724, 'zhTW', '', '澤靈！可惡，給我活下來！', 28153),
(156723, 'zhTW', '沒錯！快點賜予我永生，我已經準備好了！', '', 28153),
(156722, 'zhTW', '', '好吧，澤靈，你真的清楚到時候會發生什麼事嗎？', 28153),
(156721, 'zhTW', '做得好。你讓敵人知道谷地人可不是好欺負的。', '', 28153),
(156720, 'zhTW', '斥候回報說這個地區出現新的威脅，把它解決掉，別讓問題變得更嚴重。', '', 28153),
(156719, 'zhTW', '珍娜，保重。願聖光與你同在。', '', 28153),
(156718, 'zhTW', '', '只要能帶著艦隊回來，我死都無所謂。', 28153),
(156717, 'zhTW', '雖然很困難…也很危險。', '', 28153),
(156716, 'zhTW', '我認為你是對的…也認為你能辦到。', '', 28153),
(156715, 'zhTW', '', '只有面對問題，他們才有可能加入我們。', 28153),
(156714, 'zhTW', '庫爾提拉斯就是因為你才脫離聯盟。', '', 28153),
(156713, 'zhTW', '', '那我們也去找盟友。', 28153),
(156710, 'zhTW', '', '好了…來看看到底發生了什麼事…', 28153),
(156709, 'zhTW', '如果部落成功與贊達拉結盟，我們就沒有辦法阻止部落了。', '', 28153),
(156708, 'zhTW', '怎麼可能！那一定是希瓦娜斯的詭計！那一定是…', '', 28153),
(156707, 'zhTW', '還看見一支龐大的贊達拉艦隊。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156706, 'zhTW', '生還者說他們被詭異恐怖的魔法襲擊。', '', 28153),
(156705, 'zhTW', '只有一艘回來。', '', 28153),
(156704, 'zhTW', '我知道。派出去八艘戰艦，結果怎麼樣？', '', 28153),
(156703, 'zhTW', '公主，以及先知。', '', 28153),
(156702, 'zhTW', '最近部落的人溜進監獄劫囚，帶走兩名贊達拉囚犯。', '', 28153),
(156701, 'zhTW', '珍娜，可以讓我們看看這名生還者究竟看到了什麼嗎？', '', 28153),
(156700, 'zhTW', '很多旅人都在這個區域被殺害，我想請你解決這件事的始作俑者。', '', 28153),
(156699, 'zhTW', '人都到齊了。間諜大師，你那邊有什麼消息？', '', 28153),
(156698, 'zhTW', '真了不起！我就知道你一定能保護我們。', '', 28153),
(156697, 'zhTW', '接下來我想要一艘飛船，我會以我兒子的名字命名。', '', 28153),
(156696, 'zhTW', '這是我自己偷來的！我叫她瑪拉的寶藏…那是我女兒的名字！', '', 28153),
(156695, 'zhTW', '當他們告訴我，我們需要對付海盜，我就說我需要海盜船！', '', 28153),
(156694, 'zhTW', '納迦似乎在策劃什麼！', '', 28153),
(156693, 'zhTW', '沒錯…永生…！', '', 28153),
(156692, 'zhTW', '等你準備好出發，就拉那條繩子。我會把船開過來！', '', 28153),
(156691, 'zhTW', '', '再抱怨的人等下就會變成一具屍體！', 28153),
(156690, 'zhTW', '', '動作快點，你們這些可悲的雜種！', 28153),
(156689, 'zhTW', '', '多做事！少說話！艾澤萊晶岩不會自己跑出來！', 28153),
(156688, 'zhTW', '', '那就是你所說的工作？你的狗很幸運，我們不是請你來做這種事！', 28153),
(156687, 'zhTW', '', '回去工作，你們這些賤種！給我用盡全力！', 28153),
(156686, 'zhTW', '求求你，殺了我！讓我獲得被遺忘者的永生！', '', 28153),
(156685, 'zhTW', '我知道你一直從公司偷東西，我來這裡是想確保這種事不會再次發生…', '我知道你一直從公司偷東西，我來這裡是想確保這種事不會再次發生…', 28153),
(156684, 'zhTW', '想挨揍嗎？管好你自己的事！', '想挨揍嗎？管好你自己的事！', 28153),
(156683, 'zhTW', '繼續走，船員。這裡沒什麼好看…', '繼續走，船員。這裡沒什麼好看…', 28153),
(156682, 'zhTW', '船員，你在看什麼？', '船員，你在看什麼？', 28153),
(156681, 'zhTW', '<咳>佛斯小姐，你怎麼會變成被遺忘者？', '', 28153),
(156680, 'zhTW', '部落的小偷偷走了艾胥凡貿易公司的艾澤萊晶岩。我要你好好教訓他們一頓，順便幫第七軍團搶一些資源回來！', '', 28153),
(156679, 'zhTW', '我偷東西只是為了填滿不懂得如何去愛的空洞內心！', '我偷東西只是為了填滿不懂得如何去愛的空洞內心！', 28153),
(156678, 'zhTW', '我是因為教育程度低，才會這麼做！', '我是因為教育程度低，才會這麼做！', 28153),
(156677, 'zhTW', '我不會再犯了，我保證！', '我不會再犯了，我保證！', 28153),
(156676, 'zhTW', '那隻鹹水狗哈靈頓全力以赴！', '那隻鹹水狗哈靈頓全力以赴！', 28153),
(156675, 'zhTW', '我不再偷東西了！再也不會！', '我不再偷東西了！再也不會！', 28153),
(156674, 'zhTW', '拜託，別殺我！我再也不會偷東西了！', '拜託，別殺我！我再也不會偷東西了！', 28153),
(156673, 'zhTW', '祖達薩的流放者擄走了我方士兵。我們絕對不會跟這些與部落同流合汙的傢伙談判。讓他們知道聯盟的厲害！', '', 28153),
(156672, 'zhTW', '你輕輕鬆鬆就解決他們了，非常好。', '', 28153),
(156671, 'zhTW', '我方間諜在沙漠裡發現一個小型部落營地。用迅雷不及掩耳的速度去削弱他們的兵力吧！', '', 28153),
(156670, 'zhTW', '跟你做生意真是一件開心的事。如果你想成為海盜，你隨時都能加入我們！', '', 28153),
(156669, 'zhTW', '我信守諾言，$c，隊長的保險箱是你的了！', '', 28153),
(156668, 'zhTW', '只要哈特弗德一死，我就會到船長的房間跟你會合。不用擔心，保險箱裡面的東西都是你的！', '', 28153),
(156667, 'zhTW', '', '這還不夠，你有很好的情報，但我們還需要知道你有多麼強大。', 28153),
(156666, 'zhTW', '拜託！一定可以，你的勇士在賢者崗引發混亂、大肆破壞。把我變成被遺忘者！', '', 28153),
(156665, 'zhTW', '', '我們支援…聯盟…錯了嗎？', 28153),
(156664, 'zhTW', '', '部落永遠瓦解不了庫爾提拉斯的意志！', 28153),
(156663, 'zhTW', '應該把書…丟進海裡…', '', 28153),
(156662, 'zhTW', '你不該拿這本書！它太危險了！', '', 28153),
(156661, 'zhTW', '', '在你還來不及咳嗽之前，你就會死了，札林。你想試試看嗎？', 28153),
(156660, 'zhTW', '<喘氣>你不怕我會攻擊你嗎？然後逃跑？', '', 28153),
(156659, 'zhTW', '史東隊長回來以後發瘋了嗎？我知道她發生過什麼事。', '', 28153),
(156658, 'zhTW', '', '轉變成被遺忘者的過程難以預料。你的身體和意志絕對會改變，但是改變的程度…無法預測，你能不能承受這個轉變的過程也不得而知。', 28153),
(156657, 'zhTW', '不，但你可以回答我的疑惑嗎？當你變成被遺忘者時，你是否從此不受任何疾病所困？', '', 28153),
(156656, 'zhTW', '有你在身邊，我就更有把握離開這該死的沙漠！', '', 28153),
(156655, 'zhTW', '大功告成後，到紅岩港找我。', '', 28153),
(156654, 'zhTW', '那還真是…有創意。', '', 28153),
(156653, 'zhTW', '只要部落還在遺跡裡面閒晃，我們的盟友就無法完成他們的任務。不過黑鐵矮人想到一個解決方法。', '', 28153),
(156652, 'zhTW', '激流堡之役將在2分鐘後開始。', '', 28153),
(156651, 'zhTW', '我似乎弄丟我那頂漂亮的帽子。', '我似乎弄丟我那頂漂亮的帽子。', 28153),
(156650, 'zhTW', '帶我們到斯陀頌恩谷地。', '帶我們到斯陀頌恩谷地。', 28153),
(156649, 'zhTW', '非常好，現在看看有什麼有用的東西。', '', 28153),
(156648, 'zhTW', '這些廢墟看起來像是沉入海底的神廟遺跡。這裡的納迦看起來會是個阻礙。祝你勘察順利。', '', 28153),
(156647, 'zhTW', '我準備好談判了，泰巾。', '我準備好談判了，泰巾。', 28153),
(156646, 'zhTW', '準備好要出發的時候，就告訴我一聲，老闆夥計！', '', 28153),
(156645, 'zhTW', '處理得不錯。現在處理掉，總比晚點發生問題好。', '', 28153),
(156644, 'zhTW', '我們的斥候發現一大群魚人，我們不能冒險讓他們群起攻擊我方側翼。', '', 28153),
(156643, 'zhTW', '', '勇士，你做得很好！今天羅亞對你微笑。', 28153),
(156642, 'zhTW', '', '風險投資公司正在傷害重要盟友的領地。羅亞一定很生氣。快去阻止他們，並且記得要幫忙收拾善後。', 28153),
(156641, 'zhTW', '', '很好！那些托爾托應該會記得是誰救了他們。', 28153),
(156640, 'zhTW', '', '我收到情報，這片海岸的納迦會奴役托爾托，不知道有什麼計畫。勇士，我們不可以讓這種事情發生！把納迦殺了，讓托爾托恢復自由。', 28153),
(156639, 'zhTW', '引導海上迷失的靈魂，是浪潮賢者的職責…但不應該是這樣。', '', 28153),
(156637, 'zhTW', '做得好。希望以後需要托爾托的時候，他們不會忘記我們！', '', 28153),
(156636, 'zhTW', '我準備好航向羅德隆。', '我準備好航向羅德隆。', 28153),
(156635, 'zhTW', '風險投資公司把海岸弄得一團糟。如果能清理海岸，就可以贏得托爾托的信賴。', '', 28153),
(156634, 'zhTW', '', '永遠…停學…', 28153),
(156633, 'zhTW', '', '我要給你一個教訓！', 28153),
(156632, 'zhTW', '好極了。我可不想知道納迦打算對那些托爾托做出什麼好事。', '', 28153),
(156631, 'zhTW', '斥候說，這裡的納迦抓走了不少托爾托。不管如何，我們都必須出手阻止。', '', 28153),
(156630, 'zhTW', '', '你打起架來就像一個酪農！', 28153),
(156629, 'zhTW', '做得好，勇士！我們離勝利越來越近了！', '', 28153),
(156628, 'zhTW', '這樣應該能暫時減少牠們的數量。做得不錯。', '', 28153),
(156627, 'zhTW', '這些長羽毛的蛇本來繁殖速度就很驚人，可是現在一切都失去控制了！快去把牠們的蛋全部毀掉。', '', 28153),
(156626, 'zhTW', '勇士，這些東西用途很大，我們的傷兵一定會感激你的。', '', 28153),
(156625, 'zhTW', '我們得就地取材。去幫忙收集野生翼手龍的唾腺，裡面的成份能用來治療傷兵。', '', 28153),
(156624, 'zhTW', '難怪這邊的暴掠龍什麼都吃！這些東西很有用，謝謝你了，勇士。', '', 28153),
(156623, 'zhTW', '我們現在正需要耐用的物品，據說這座島上暴掠龍的胃袋什麼都能裝。你願意幫我們去收集一些嗎？', '', 28153),
(156622, 'zhTW', '啊…快去奈普圖隆的貯藏箱…跟你一起…', '', 28153),
(156621, 'zhTW', '這是什麼…叛變？有種啊，豬玀們！', '', 28153),
(156620, 'zhTW', '為了部落！', '為了部落！', 28153),
(156619, 'zhTW', '', '我的研究暫時結束了，謝謝你的幫忙。', 28153),
(156618, 'zhTW', '', '那會讓部落學會干涉！這個魔法絕不能落入他們手中…', 28153),
(156617, 'zhTW', '', '萬分感激你的協助，這個屏障非常頑強…', 28153),
(156616, 'zhTW', '永生近在咫尺！我等不及被轉化成被遺忘者。試想一下那無限的可能性！\n\n等你有空的時候，你一定要告訴我那是什麼感覺，不死、永生，將世界納入手中！', '', 28153),
(156615, 'zhTW', '我拒絕因為一些莫名其妙的疾病死在…這裡。我必須活下去，保護我家人的安全。', '', 28153),
(156614, 'zhTW', '不要打擾死者，$r。', '', 28153),
(156613, 'zhTW', '', '這裡需要一點幫忙！', 28153),
(156612, 'zhTW', '如果你不努力上進，就會逐漸落後，這是我的至理名言！', '', 28153),
(156611, 'zhTW', '', '我必須做一些測試，收集資料。留意任何閒雜人等。', 28153),
(156610, 'zhTW', '', '我們或許可以駕馭這個魔法，或甚至讓它再現。', 28153),
(156609, 'zhTW', '', '在這裡運作的魔法非常高妙！簡直前所未見。', 28153),
(156608, 'zhTW', '', '給我記住！', 28153),
(156607, 'zhTW', '不過你有這個時間嗎？', '', 28153),
(156606, 'zhTW', '我需要新的偽裝。', '我需要新的偽裝。', 28153),
(156605, 'zhTW', '部落來了，快跑！有沒有安全的地方？', '部落來了，快跑！有沒有安全的地方？', 28153),
(156604, 'zhTW', '很好，部落問題更多了，現在聯盟也來了！', '很好，部落問題更多了，現在聯盟也來了！', 28153),
(156603, 'zhTW', '如果部落已經在這裡，我可不想送掉小命！', '如果部落已經在這裡，我可不想送掉小命！', 28153),
(156602, 'zhTW', '快跑！這是我們為聯盟提供的幫助！', '快跑！這是我們為聯盟提供的幫助！', 28153),
(156601, 'zhTW', '我以為我們不會被部落的人抓到！', '我以為我們不會被部落的人抓到！', 28153),
(156600, 'zhTW', '部落怎麼會來這裡？', '部落怎麼會來這裡？', 28153),
(156599, 'zhTW', '部落的人，快跑！', '部落的人，快跑！', 28153),
(156598, 'zhTW', '這是測試文字，我說了一些東西。', '', 28153),
(156597, 'zhTW', '', '納薩諾斯，再見了。', 28153),
(156596, 'zhTW', '', '<希瓦娜斯轉身離開，然後停下來回頭看了一眼。>', 28153),
(156595, 'zhTW', '我們不會讓你失望。黑暗女王，一路平安。', '', 28153),
(156594, 'zhTW', '', '去吧，記得隨時跟我報告進度。', 28153),
(156593, 'zhTW', '遵命，大酋長。', '', 28153),
(156592, 'zhTW', '', '很好，去跟我們的勇士討論一下，看要先拿下哪個據點。', 28153),
(156591, 'zhTW', '報告黑暗女王，是的。只要下令，女妖之嚎隨時可以出航。', '', 28153),
(156590, 'zhTW', '', '準備好了嗎？', 28153),
(156589, 'zhTW', '<納薩諾斯深深鞠躬。>', '', 28153),
(156588, 'zhTW', '黑暗女王。', '', 28153),
(156587, 'zhTW', '勇士，請你去女妖之嚎一趟。黑暗女王已經命令我們開始執行庫爾提拉斯的海岸戰鬥計畫。', '', 28153),
(156586, 'zhTW', '', '跟我來。', 28153),
(156585, 'zhTW', '', '勇士。', 28153),
(156584, 'zhTW', '這組人會交給迦羅娜‧半血負責，她會在你的協助下安排任務細節。', '', 28153),
(156583, 'zhTW', '我們集合了一群精英，準備執行黑暗女王的命令。', '', 28153),
(156582, 'zhTW', '做得非常好，勇士。', '', 28153),
(156581, 'zhTW', '部落察覺了我們的行蹤，還派出攻擊部隊。去幫勘測員爭取時間，讓他們完成任務！', '', 28153),
(156580, 'zhTW', '', '我想我可以做些安排，澤靈，前提是你必須先向部落證明你的價值。', 28153),
(156579, 'zhTW', '我的名字是湯瑪斯‧澤靈，我是浪潮賢者，充滿智慧的浪潮賢者！我願意執行你的命令，就算是協助攻擊附近的聯盟也不例外，拜託，讓我變成被遺忘者！', '', 28153),
(156578, 'zhTW', '看來礦車完整地回到家了。你的獎勵在要塞裡等著你。', '', 28153),
(156577, 'zhTW', '', '你是誰？你為什麼認為自己有這個資格？', 28153),
(156576, 'zhTW', '終於找到了，一個被遺忘者！求求你，殺了我，把我變成被遺忘者…賜予我永生！', '', 28153),
(156575, 'zhTW', '', '嗯，我是可以威脅一下那個女人，看看她能不能給我們一點有用的資訊…', 28153),
(156574, 'zhTW', '虛無還是元素 <咳嗽>…沒有東西能夠阻止這該死的疾病嗎？為什麼一切要像這樣結束？', '', 28153),
(156573, 'zhTW', '嗯，那個浪潮賢者曾在這裡紮營。我看過他保護和照顧自己的家人。', '', 28153),
(156572, 'zhTW', '你知道哪裡能找到浪潮賢者嗎？', '你知道哪裡能找到浪潮賢者嗎？', 28153),
(156571, 'zhTW', '我們發現部落正在運送補給穿過戰場。巴琳達正在找自願者來幫我們…補充物資。', '', 28153),
(156570, 'zhTW', '我們接到回報，指出部落斥候在礦坑附近活動。去工坊找珍妮了解情況。', '', 28153),
(156569, 'zhTW', '工坊的珍妮需要幫手。我們的補給快要不夠了。', '', 28153),
(156568, 'zhTW', '有錢要賺，有新地盤要剝削…$B$B活著真是太好了！', '', 28153),
(156567, 'zhTW', '不，我不在乎。', '', 28153),
(156566, 'zhTW', '米莎，你留下來。我們其他人會追查這個浪潮賢者，然後，莉莉安會…去做你原本打算要做的事。', '', 28153),
(156565, 'zhTW', '', '雷克薩，你不在乎細節嗎？', 28153),
(156564, 'zhTW', '我準備好前往幽暗城。', '我準備好前往幽暗城。', 28153),
(156563, 'zhTW', '', '喪鐘鎮不復存在。等你準備好了，我會帶你到法師區見霸王。', 28153),
(156562, 'zhTW', '', '勇士們，關鍵時刻到了。聯盟拚命進犯羅德隆這座要塞，一定會慘敗在我們的劍刃之下。', 28153),
(156560, 'zhTW', '聯盟的勇士們，奪回領土的時刻終於到了。日出的時候，我們就要開始進攻羅德隆城堡。部落和他們的大酋長必須為罪行受到制裁！', '', 28153),
(156559, 'zhTW', '', '你的夜裔精靈朋友在古道大廳，你逛完了之後，就來找我吧。', 28153),
(156558, 'zhTW', '', '我的父親把許多寶物，都放在這皇家庫房裡面。', 28153),
(156557, 'zhTW', '', '據說這個大封印之地是世界上現存，少數比贊達拉帝國還要更古老的事物。', 28153),
(156556, 'zhTW', '', '英雄，跟我來，我帶你到處逛逛。', 28153),
(156555, 'zhTW', '這個交給你比較好。', '', 28153),
(156554, 'zhTW', '我蹲在這牢裡的時間已經算不清，但到頭來其實也不重要了。', '', 28153),
(156553, 'zhTW', '我是山繆‧威廉斯，真高興看到拿著武器的人跟我們同一邊。', '', 28153),
(156552, 'zhTW', '這些海盜都是些下流、陰險的傢伙，殺光他們也不為過。', '這些海盜都是些下流、陰險的傢伙，殺光他們也不為過。', 28153),
(156551, 'zhTW', '我們到底為自己找來什麼麻煩？', '我們到底為自己找來什麼麻煩？', 28153),
(156550, 'zhTW', '我們一定會再見，怪物！', '我們一定會再見，怪物！', 28153),
(156549, 'zhTW', '在它們讓我過載之前，我殺了好幾隻這種邪惡怪物！', '在它們讓我過載之前，我殺了好幾隻這種邪惡怪物！', 28153),
(156548, 'zhTW', '為了聯盟！', '為了聯盟！', 28153),
(156547, 'zhTW', '一個都不能少！', '一個都不能少！', 28153),
(156546, 'zhTW', '我知道龍禍不會把我們丟在這裡！', '我知道龍禍不會把我們丟在這裡！', 28153),
(156545, 'zhTW', '回到船上我再請你喝酒。', '回到船上我再請你喝酒。', 28153),
(156544, 'zhTW', '我從來沒想過，原來牠們這麼能吃…', '', 28153),
(156543, 'zhTW', '拉尼舒是大胃王，不過沒什麼腦袋，牠們會吃掉視線範圍內的所有東西，就算是同族也照吃不誤。我們要好好利用這點。', '', 28153),
(156542, 'zhTW', '', '<迦羅娜旋轉她的武器，然後它們就似乎消失了。>', 28153),
(156541, 'zhTW', '這些戰鷹會送我們到目的地。準備好了就上去吧！', '', 28153),
(156540, 'zhTW', '出發吧。', '', 28153),
(156539, 'zhTW', '女王早已看透一切。我方運輸隊已在堡壘待命。', '', 28153),
(156538, 'zhTW', '我只要它們收藏的一件寶物。', '我只要它們收藏的一件寶物。', 28153),
(156537, 'zhTW', '我會回來，海盜！我們一定會再見！', '我會回來，海盜！我們一定會再見！', 28153),
(156536, 'zhTW', '殺光那群懦弱的傢伙！', '殺光那群懦弱的傢伙！', 28153),
(156535, 'zhTW', '我想念祖達薩…我到底還要在這裡受苦多久？', '我想念祖達薩…我到底還要在這裡受苦多久？', 28153),
(156534, 'zhTW', '這裡根本沒有寶藏，簡直謊話連篇！', '這裡根本沒有寶藏，簡直謊話連篇！', 28153),
(156533, 'zhTW', '他們不讓我成為他們的一員！這不公平。', '他們不讓我成為他們的一員！這不公平。', 28153),
(156532, 'zhTW', '在沙漠中極為少見的善行。', '在沙漠中極為少見的善行。', 28153),
(156531, 'zhTW', '沒想到居然有人會來救我。謝謝你，陌生人。', '沒想到居然有人會來救我。謝謝你，陌生人。', 28153),
(156530, 'zhTW', '有東西打開了。', '', 28153),
(156529, 'zhTW', '還沒結束…', '', 28153),
(156528, 'zhTW', '大家應該都脫困了，做得好，勇士。我就知道你一定能辦到。', '', 28153),
(156527, 'zhTW', '還有許多狐狸人被困在地穴裡面，你願不願意幫忙救他們出來？', '', 28153),
(156526, 'zhTW', '精確校準的清掃器因為在附近找不到化石而發出短暫的嗡鳴。', '精確校準的清掃器因為在附近找不到化石而發出短暫的嗡鳴。', 28153),
(156525, 'zhTW', '挖掘元素生物因為在附近找不到化石而煩躁得發出嗡鳴。', '挖掘元素生物因為在附近找不到化石而煩躁得發出嗡鳴。', 28153),
(156524, 'zhTW', '', '為了吉爾尼斯！', 28153),
(156523, 'zhTW', '', '守衛，給我上！把他們的人頭帶來給我！', 28153),
(156522, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_HOLY_DIVINEPROVIDENCE:20|t 泰坦守衛者赫茲羅開始施放|cFFF00000|Hspell:269310|h[淨化之光]|h|r！', '', 28153),
(156521, 'zhTW', '', '所以部落決定到這裡來攻打我們？省得我親自去找你們。吉爾尼斯人，攻擊！', 28153),
(156520, 'zhTW', '我沒想到算起來這麼複雜。晚點回來，我會分好你的那份。', '', 28153),
(156519, 'zhTW', '', '這就和鐵爐堡的銀行一樣，需要五個人才行。', 28153),
(156518, 'zhTW', '我們會成為英雄…很有錢的英雄！', '', 28153),
(156517, 'zhTW', '讓我變成有錢人，$p，我想幫自己買幾顆金牙！', '', 28153),
(156516, 'zhTW', '', '艾達，你的牙齒好點了嗎？', 28153),
(156514, 'zhTW', '', '我夢過這個場景，只不過我是在鐵爐堡的銀行。', 28153),
(156513, 'zhTW', '', '等我們拿到金子，我就要為自己買瓶香水，用它來泡澡。', 28153),
(156512, 'zhTW', '或許我們還有機會碰面。再見了！', '', 28153),
(156511, 'zhTW', '我們被釋放了…', '', 28153),
(156510, 'zhTW', '我們必須…逃走…', '', 28153),
(156509, 'zhTW', '', '感謝你的幫助，$n。我必須在別處繼續。', 28153),
(156508, 'zhTW', '', '我不會假裝了解你的動機，$n，但我很感謝你又擊殺了另一名死亡騎士。', 28153),
(156507, 'zhTW', '', '注意天空，$n！我感覺到有人在靠近！', 28153),
(156506, 'zhTW', '你好嗎，$p？', '如果有金子可賺，算我一份！', 28153),
(156505, 'zhTW', '我需要你的幫忙。', '我需要你的幫忙。', 28153),
(156504, 'zhTW', '我從巫妖王的手中活下來，卻被你這種人解決…呃啊…', '', 28153),
(156503, 'zhTW', '真是糟蹋…', '', 28153),
(156502, 'zhTW', '我需要你的幫忙。', '我需要你的幫忙。', 28153),
(156501, 'zhTW', '你贏了…龍…', '', 28153),
(156500, 'zhTW', '最終的…死亡…', '', 28153),
(156499, 'zhTW', '不…公平…', '', 28153),
(156498, 'zhTW', '那麼我會拿回屬於我的東西…用武力！', '', 28153),
(156497, 'zhTW', '我知道是怎麼回事，$n！你想要成為唯一擁有閃耀坐騎的死亡騎士！', '', 28153),
(156496, 'zhTW', '但我已經瞄準你後面那具遠古巨獸骨骸。所以若你不介意，我要拿走屬於我的東西。', '', 28153),
(156495, 'zhTW', '那裡的飛龍有點小…而且仍然活著。根本不算是最大的阻礙。', '', 28153),
(156494, 'zhTW', '我在跟隨著你的腳步。你是來這裡幫我的嗎？我看到你帶了禮物來！', '', 28153),
(156493, 'zhTW', '死亡領主，$n！給你個驚喜！', '', 28153),
(156492, 'zhTW', '呃。若你想要我來硬的，我也奉陪！', '', 28153),
(156491, 'zhTW', '', '$n，保護我！儀式必須完成！', 28153),
(156490, 'zhTW', '小飛龍，站到一旁。我跟那堆骨頭有約。', '', 28153),
(156489, 'zhTW', '我認為我應該遵循我原本的計畫，', '', 28153),
(156488, 'zhTW', '我們趕快離開這裡！', '我們趕快離開這裡！', 28153),
(156487, 'zhTW', '像我這樣所向披靡的騎士只能接受最好的坐騎。', '', 28153),
(156486, 'zhTW', '是兩條龍！還真是個驚喜！雖然活著的那條…有點小。', '', 28153),
(156485, 'zhTW', '', '這裡不歡迎你，死亡騎士。', 28153),
(156484, 'zhTW', '你看看，這裡有什麼啊？', '', 28153),
(156483, 'zhTW', '祖爾的信徒不會讓瑞贊這麼輕易地逃過一劫。我們必須從這裡殺出一條血路。\n\n你準備好了嗎？', '', 28153),
(156482, 'zhTW', '幹嘛那麼趕？放輕鬆。緩和呼吸…小睡一下！你跟我們在一起很安全。', '', 28153),
(156481, 'zhTW', '我父親教導我們使用熔爐…這是我們一起打的第一把錘子。', '', 28153),
(156480, 'zhTW', '我的錘子！你拿回來了！', '', 28153),
(156479, 'zhTW', '', '這些流亡者就是最接近我家人的人了。', 28153),
(156478, 'zhTW', '', '歡迎你加入，$p。', 28153),
(156477, 'zhTW', '歡迎你加入，$p。', '', 28153),
(156476, 'zhTW', '', '歡迎你加入，$p。', 28153),
(156475, 'zhTW', '歡迎你加入，$p。', '', 28153),
(156474, 'zhTW', '需要喝杯烈酒還是吃點東西？', '需要喝杯烈酒還是吃點東西？', 28153),
(156473, 'zhTW', '喔，$p，是你嗎？你沒有被沙怒跟蹤吧？', '', 28153),
(156472, 'zhTW', '再伏擊幾個車隊，我們就要突擊競技場，奪取真正的寶物了！', '', 28153),
(156471, 'zhTW', '我渴了！幫我去偷一些贊達拉好酒來！', '', 28153),
(156470, 'zhTW', '我們快沒有木材了。幫我再找一個狐狸人車隊供我們劫掠！', '', 28153),
(156469, 'zhTW', '沙漠是屬於沙怒的！其他人等都是入侵者！', '', 28153),
(156468, 'zhTW', '帶更多奴隸給我。我還有很多矛可以投擲。', '', 28153),
(156467, 'zhTW', '擊潰他們！把他們打得跟狗一樣！', '', 28153),
(156466, 'zhTW', '你現在沒這麼高傲強大了吧，驕縱的贊達拉！', '', 28153),
(156465, 'zhTW', '哈！幹掉一個！正中胸膛，你這醜狐狸人…', '', 28153),
(156464, 'zhTW', '你這挖泥巴的毛地薯，想拿回錘子嗎？放馬過來啊！', '', 28153),
(156463, 'zhTW', '我們要把這些庫爾提拉斯敗類逐出我們的土地！$n，呼叫部落，讓我們了結此事。', '', 28153),
(156462, 'zhTW', '你說話的時候應該注意點。亞茲瑪是羅亞的高階祭司，而且神王拉斯塔哈很重視她的意見。$b$b而且如果傳言是真的，她對預言者祖爾更有影響力。', '你說話的時候應該注意點。亞茲瑪是羅亞的高階祭司，而且神王拉斯塔哈很重視她的意見。$b$b而且如果傳言是真的，她對預言者祖爾更有影響力。', 28153),
(156461, 'zhTW', '沙德拉是贊庫爾議會最喜愛的羅亞，所以像我一樣追隨她的人，享有不少特權。其中一項就是不需要理會你這種人。', '沙德拉是贊庫爾議會最喜愛的羅亞，所以像我一樣追隨她的人，享有不少特權。其中一項就是不需要理會你這種人。', 28153),
(156460, 'zhTW', '你真該死…', '你真該死…', 28153),
(156459, 'zhTW', '你會輸的…', '你會輸的…', 28153),
(156458, 'zhTW', '陛下…我很抱歉…', '陛下…我很抱歉…', 28153),
(156457, 'zhTW', '給我…記住…', '給我…記住…', 28153),
(156456, 'zhTW', '為了…聯盟…', '為了…聯盟…', 28153),
(156455, 'zhTW', '沙德拉的追隨者很有興趣地一直跟著你們。$b$B我們看到你們部落一路深陷由謊言所交織的陷阱。這個陷阱很快就會關閉，而你們卻不會察覺，直到已無可挽回。', '沙德拉的追隨者很有興趣地一直跟著你們。$b$B我們看到你們部落一路深陷由謊言所交織的陷阱。這個陷阱很快就會關閉，而你們卻不會察覺，直到已無可挽回。', 28153),
(156454, 'zhTW', '死吧！', '死吧！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156453, 'zhTW', '我要讓你們變成屍塊回到奧格瑪！', '我要讓你們變成屍塊回到奧格瑪！', 28153),
(156452, 'zhTW', '你們要為對聯盟犯下的罪行付出代價！', '你們要為對聯盟犯下的罪行付出代價！', 28153),
(156451, 'zhTW', '我效忠於間諜的仕女、毒之羅亞沙德拉。你真正效忠的是誰？', '我效忠於間諜的仕女、毒之羅亞沙德拉。你真正效忠的是誰？', 28153),
(156450, 'zhTW', '死吧，部落雜碎！', '死吧，部落雜碎！', 28153),
(156449, 'zhTW', '為了聯盟！', '為了聯盟！', 28153),
(156448, 'zhTW', '女士大人已經注意到你進入她的領地了。別輕舉妄動。', '女士大人已經注意到你進入她的領地了。別輕舉妄動。', 28153),
(156447, 'zhTW', '與大地之母同行，$n。', '與大地之母同行，$n。', 28153),
(156446, 'zhTW', '我們在這片土地上的狩獵才剛開始。', '', 28153),
(156445, 'zhTW', '倫卡依然躲在綠洲裡？我應該在這幾天裡拜訪他一下…', '', 28153),
(156444, 'zhTW', '我就知道你會再回來光顧！這裡有一批全新的貨，特別為你準備的。', '', 28153),
(156443, 'zhTW', '[場景顯示賈克拉傑將軍以及科爾塞克皇帝兩人密謀。]', '', 28153),
(156442, 'zhTW', '深淵…看著…你…', '深淵…看著…你…', 28153),
(156441, 'zhTW', '我會把你破碎的屍體丟進海裡！', '我會把你破碎的屍體丟進海裡！', 28153),
(156440, 'zhTW', '', '我應該要投胎成哥布林才對，他們才懂欣賞我的特殊長才。', 28153),
(156439, 'zhTW', '當時應該跟鐵潮達成協議才對，他們簡直蠢到不行。', '', 28153),
(156438, 'zhTW', '當我們搜尋祖爾時，你就做你該做的事吧，小英雄。但準備好，我們很快就用得著你的猛勁了。', '', 28153),
(156437, 'zhTW', '', '我們會獵殺這些異端直到艾澤拉斯的盡頭。我會集合我的子嗣，我們要對這些膽敢背叛我們的邪惡生物，降下死亡與巨石。\n\n現在，我的子嗣會搜尋天空，預測祖爾那群背叛者的動靜。', 28153),
(156436, 'zhTW', '這一次…你殺掉我了…', '', 28153),
(156435, 'zhTW', '<將我的隊伍加入海嶼遠征PvP佇列。>', '<將我的隊伍加入海嶼遠征PvP佇列。>', 28153),
(156434, 'zhTW', '<加入海嶼遠征PvP佇列。>', '<加入海嶼遠征PvP佇列。>', 28153),
(156433, 'zhTW', '使用金提基的神像消滅祖拉金！', '使用金提基的神像消滅祖拉金！', 28153),
(156432, 'zhTW', '我只希望別人找不到我藏起來的那把鑰匙，鑰匙只能交給你。', '', 28153),
(156431, 'zhTW', '庫嘉，你的勇氣無庸置疑，但你的狀況無法進行戰鬥。$n，我會護送庫嘉。當你完成後，與我們在戰塔會面。', '', 28153),
(156430, 'zhTW', '感謝你，我會確保戰塔。我們需要戰塔呼叫其餘的部隊。', '感謝你，我會確保戰塔。我們需要戰塔呼叫其餘的部隊。', 28153),
(156429, 'zhTW', '', '我的姊妹們…會殺了你…', 28153),
(156428, 'zhTW', '部落必敗無疑…', '部落必敗無疑…', 28153),
(156427, 'zhTW', '你們在跟隨一個瘋女人…', '你們在跟隨一個瘋女人…', 28153),
(156426, 'zhTW', '你們這些禽獸…', '你們這些禽獸…', 28153),
(156425, 'zhTW', '我要…殺了…你…', '我要…殺了…你…', 28153),
(156424, 'zhTW', '我要部落好看…', '我要部落好看…', 28153),
(156423, 'zhTW', '為了泰達希爾…', '為了泰達希爾…', 28153),
(156422, 'zhTW', '姊妹們…我盡力了…', '姊妹們…我盡力了…', 28153),
(156421, 'zhTW', '', '我的家人都死在泰達希爾！我要殺了你們！', 28153),
(156420, 'zhTW', '', '我們會替泰達希爾復仇！', 28153),
(156419, 'zhTW', '我們要讓庫爾提拉斯不敢輕易與部落作對。', '', 28153),
(156418, 'zhTW', '為了泰達希爾和聯盟！', '為了泰達希爾和聯盟！', 28153),
(156417, 'zhTW', '在尖叫中慘死吧，部落敗類！', '在尖叫中慘死吧，部落敗類！', 28153),
(156416, 'zhTW', '', '殺人兇手！你膽敢露臉嗎？', 28153),
(156415, 'zhTW', '我們走這邊！', '', 28153),
(156414, 'zhTW', '現在走路交給我！', '', 28153),
(156413, 'zhTW', '我們去我想去的地方！', '', 28153),
(156412, 'zhTW', '我升等當腳了！', '', 28153),
(156411, 'zhTW', '我現在是駕駛！', '', 28153),
(156410, 'zhTW', '以聖火淨化你！', '', 28153),
(156409, 'zhTW', '不…我必須找到…戒指…', '', 28153),
(156408, 'zhTW', '畜生！我會把你的首級送給你的大酋長！', '畜生！我會把你的首級送給你的大酋長！', 28153),
(156407, 'zhTW', '你的頭會是獻給女王的貢品！', '', 28153),
(156406, 'zhTW', '', '部落會因為毀掉泰達希爾而受到制裁！', 28153),
(156405, 'zhTW', '', '我會讓你看看屍體是怎麼燃燒的！', 28153),
(156404, 'zhTW', '', '看來我們在這裡的工作完成了！在外頭小心點，$p。', 28153),
(156403, 'zhTW', '我一定會幫我的人報仇，我發誓。', '我一定會幫我的人報仇，我發誓。', 28153),
(156402, 'zhTW', '愚蠢的凡人。你們無法阻止我回來。', '', 28153),
(156401, 'zhTW', '', '你！部落。我需要你的能力。', 28153),
(156400, 'zhTW', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t出現一個新的|cFFFF0404|Hspell:263420|h[能量矩陣]|h|r。', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t出現一個新的|cFFFF0404|Hspell:263420|h[能量矩陣]|h|r。', 28153),
(156399, 'zhTW', '那食人妖比一袋瓦尼舒還瘋狂。', '', 28153),
(156398, 'zhTW', '雷卡提轉了轉他的眼睛。', '', 28153),
(156397, 'zhTW', '好的，夥伴。沒問題！感謝！', '', 28153),
(156396, 'zhTW', '沒時間講話了，雷卡提！', '', 28153),
(156395, 'zhTW', '潮汐之戒是我們的！這是艾薩拉女王的命令！', '潮汐之戒是我們的！這是艾薩拉女王的命令！', 28153),
(156394, 'zhTW', '除非戒指到手，我們決不罷休！', '除非戒指到手，我們決不罷休！', 28153),
(156393, 'zhTW', '你在幹嘛？數數？我？我才不幹。算數應該是你的工作。\n\n跟你說，我們重頭開始吧。', '', 28153),
(156392, 'zhTW', '潮汐之戒在哪？別把它藏起來！', '潮汐之戒在哪？別把它藏起來！', 28153),
(156391, 'zhTW', '潮汐之戒在附近遺失。女王一定要把它拿回來！', '潮汐之戒在附近遺失。女王一定要把它拿回來！', 28153),
(156390, 'zhTW', '風暴之甦正在壯大。你是站在我們這邊的嗎？', '風暴之甦正在壯大。你是站在我們這邊的嗎？', 28153),
(156389, 'zhTW', '我達到一百萬個靈魂了嗎？', '我達到一百萬個靈魂了嗎？', 28153),
(156388, 'zhTW', '沒有人能阻擋我們的女王！', '沒有人能阻擋我們的女王！', 28153),
(156387, 'zhTW', '我們是潮汐之戒的正統擁有者！', '我們是潮汐之戒的正統擁有者！', 28153),
(156386, 'zhTW', '我們依然能阻止斯陀頌恩領主。', '我們依然能阻止斯陀頌恩領主。', 28153),
(156385, 'zhTW', '戒指將是我們的！', '戒指將是我們的！', 28153),
(156384, 'zhTW', '艾薩拉女王要拿走潮汐之戒！', '艾薩拉女王要拿走潮汐之戒！', 28153),
(156383, 'zhTW', '|TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t 黃金風蛇吸收一個活化黃金，獲得|cFFFF0000|Hspell:265991|h[耀眼亮澤]|h|r！', '黃金風蛇吸收一個活化黃金，獲得|TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t 可跳過文字放此|cFFFF0000|Hspell:265991|h[耀眼亮澤]|h|r！', 28153),
(156382, 'zhTW', '', '呃喔！那不妙！不妙！', 28153),
(156381, 'zhTW', '用其中一個繩索下降到登陸艇…除非你喜歡游泳。', '', 28153),
(156380, 'zhTW', '我絕不要再洗任何一條這種骯髒的人類內衣了！', '', 28153),
(156379, 'zhTW', '', '我連襪子都濕了！感謝你。', 28153),
(156378, 'zhTW', '', '我真是受夠了！', 28153),
(156377, 'zhTW', '你自可怕的命運中拯救了我。', '', 28153),
(156375, 'zhTW', '當你外出冒險時，我研究了這把劍。', '當你外出冒險時，我研究了這把劍。', 28153),
(156374, 'zhTW', '<間諜大師肖爾點頭表示認可。>', '', 28153),
(156373, 'zhTW', '我們在這裡，間諜大師。', '', 28153),
(156372, 'zhTW', '我要與間諜大師肖爾合作。人不算親切，但他總是能完成任務。', '', 28153),
(156371, 'zhTW', '國王為這次戰役帶來一些令人印象深刻的英雄。', '', 28153),
(156370, 'zhTW', '迅翼，去為自己找個大餐吧。', '', 28153),
(156369, 'zhTW', '跟我來，$U小夥子:小姑娘;。', '', 28153),
(156368, 'zhTW', '射中那一個的膝蓋了！', '喔…那一定很痛！', 28153),
(156367, 'zhTW', '我們不會輕易放棄。', '他們剛剛應該在還有機會的時候用跑的。', 28153),
(156366, 'zhTW', '人員陣亡！', '沒他們想的那麼厲害！', 28153),
(156365, 'zhTW', '你好，史東船長。我一直期盼與你見面。', '', 28153),
(156364, 'zhTW', '那就運上貨車吧。你比我預期還要有用，佛斯小姐。', '', 28153),
(156363, 'zhTW', '', '夠完好了。', 28153),
(156362, 'zhTW', '大致完好？', '', 28153),
(156361, 'zhTW', '', '凋零者，這裡。我取得屍體了。', 28153),
(156360, 'zhTW', '做得很好，$p。現在，莉莉安在哪？', '', 28153),
(156359, 'zhTW', '你必須快點…他們要去對付瑞贊！', '', 28153),
(156358, 'zhTW', '他們…他們逼我說出德拉克瑞怎麼辦到的。', '', 28153),
(156357, 'zhTW', '好。英雄，讓泰莉亞快速跟你說一下。', '', 28153),
(156356, 'zhTW', '', '報告長官！戰況報告準備好了！', 28153),
(156355, 'zhTW', '', '你把她們的部隊給燒了！做得好。', 28153),
(156354, 'zhTW', '', '那些女巫開始重新整頓部隊了。想辦法控制魔巨像，摧毀她們的部隊！', 28153),
(156353, 'zhTW', '', '我們必須讓庫爾提拉斯知道與部落為敵有什麼下場。', 28153),
(156352, 'zhTW', '記得 - 橋梁港是一個大型據點，而且戒備森嚴。試著待在城鎮外緣…暫時先這樣。', '', 28153),
(156351, 'zhTW', '我們已經做了我們該做的，$p。我對我們的成果感到很驕傲。\n\n不過我們現在該照顧同胞，確保他們的安全了。\n\n我很確定我們還會再見面，很榮幸能有你這位朋友兼盟友。', '', 28153),
(156350, 'zhTW', '無信者對待他們的野獸相當殘酷。讓牠們反抗自己的主人並不困難。', '', 28153),
(156349, 'zhTW', '我根本不該忍受這樣的待遇，我可是預言者祖爾欽點的將軍！', '', 28153),
(156348, 'zhTW', '', '那才是值得歌頌的一場戰鬥！\n\n我很榮幸能跟你與瓦里克一同戰鬥。希望我們很快能再度並肩作戰。\n\n畢竟無信者總是殺不勝殺。', 28153),
(156347, 'zhTW', '讓我們一起為此事畫下休止符。', '', 28153),
(156346, 'zhTW', '', '讓我們給這些塞斯拉克一個教訓。', 28153),
(156345, 'zhTW', '', '有了這些東西，我們就可以繼續對抗女巫了。謝謝你。', 28153),
(156344, 'zhTW', '跟我來，要塞距離這裡不遠。', '', 28153),
(156343, 'zhTW', '好。那他們就是我們的目標。', '', 28153),
(156342, 'zhTW', '', '我們經過的那座城，橋梁港，似乎是這一區最大的威脅。', 28153),
(156341, 'zhTW', '雷克薩！<咳嗽> 許多人依然在反抗。他…他們沒有多少時間了。', '雷克薩！<咳嗽> 許多人依然在反抗。他…他們沒有多少時間了。', 28153),
(156340, 'zhTW', '那個怪物再也沒辦法拿部落士兵當晚餐了。勇士，殺得好。', '', 28153),
(156339, 'zhTW', '', '我們快要沒有銀礦了，要想對抗女巫，銀礦可是關鍵。請你到礦場去，盡量多挖一點回來。', 28153),
(156338, 'zhTW', '拉奇昂看起來願意協助我們，原因顯而易見。\n\n無信者向來對牠和牠的幼龍很殘酷。看牠身上的那些疤，還有山巔上空蕩蕩的窩巢。\n\n牠也和我們一樣想要復仇。我們會一起辦到的。', '', 28153),
(156337, 'zhTW', '聽好，山繆，你要撐住。', '', 28153),
(156336, 'zhTW', '我覺得好冷。這個聲音什麼時候才會停止？', '', 28153),
(156335, 'zhTW', '$n，攪拌一下我的燉藥，否則它會燒焦。', '', 28153),
(156334, 'zhTW', '做得真好。接下來要讓他們再也開不了聚會。', '', 28153),
(156333, 'zhTW', '有錢人，做得好。我們把這場會給砸了吧。', '', 28153),
(156332, 'zhTW', '別激動，草藥會舒緩你的傷口。你可以告訴我們要塞裡面的狀況嗎？有沒有倖存者？', '', 28153),
(156331, 'zhTW', '|TInterface\\ICONS\\ABILITY_DEATHKNIGHT_SOULREAPER:20|t每一層|cFFFF0404|Hspell:260512|h[靈魂收割]|h|r都會提高縛魂巨怪的傷害！', '', 28153),
(156330, 'zhTW', '你看！那一個還有呼吸！', '', 28153),
(156329, 'zhTW', '這場戰鬥讓許多勇敢的戰士犧牲。幸好你們來了。', '', 28153),
(156328, 'zhTW', '庫爾提拉斯在我們努力拯救船員的時候發動攻擊。我們的部隊散得太開，無法顧及兩邊，最後不得不撤退到岸邊。', '', 28153),
(156327, 'zhTW', '這場攻擊發生在一大早。庫爾提拉斯的法師用一個奇怪的東西召喚出那些纏繞我們船艦的可怕東西。', '', 28153),
(156326, 'zhTW', '哈！確認完畢，任務成功，完美典範！順利達成計畫讓我非常開心，完畢，通話結束。', '', 28153),
(156325, 'zhTW', '繼續執行任務。有沒有看見一顆紅色大按鈕？對，撤離那個區域，然後確實按下紅色大按鈕。準備完成後立即行動。完畢。', '', 28153),
(156324, 'zhTW', '授權碼為：一、九、九。儀器校準值超出可接受參數範圍…撤銷命令…我來處理。靜候指示，完畢。', '', 28153),
(156323, 'zhTW', '收到！校準完畢。你們必須在指定地點設定儀器定向。完成後立即向我回報，完畢。', '', 28153),
(156322, 'zhTW', '無線電測試，這裡是阿爾法一號。呼叫阿爾法分隊，聽到請回答。完畢。', '', 28153),
(156321, 'zhTW', '真是光榮的戰鬥，而且我們活下來了！', '', 28153),
(156320, 'zhTW', '', '烈焰永不熄滅…', 28153),
(156319, 'zhTW', '', '塵歸塵…', 28153),
(156318, 'zhTW', '你的善舉讓我們無地自容，感激不盡，$p。', '', 28153),
(156317, 'zhTW', '', '你們的骨頭會是很棒的火引。', 28153),
(156316, 'zhTW', '', '我不會留下任何為你哀悼的活口。', 28153),
(156315, 'zhTW', '在我們那漫長的歷史裡，很少有這麼美好的一天！', '', 28153),
(156314, 'zhTW', '我要新創一種湯，以表達對你的敬意！', '', 28153),
(156313, 'zhTW', '龜肉湯一點也比不上$r湯。\n\n只要泥蟲肉就好，不要抓那些小烏龜。\n\n改天再來看我，我們再一起探索湯的可能性！', '', 28153),
(156312, 'zhTW', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t %s開始施放|cFFFF0000|Hspell:267334|h[腐化之球]|h|r！', '遠方出現了一道投影…', 28153),
(156311, 'zhTW', '', '一不小心就會迷失方向。', 28153),
(156310, 'zhTW', '你需要我幫助的話就說一聲！', '', 28153),
(156309, 'zhTW', '現在這裡一切都就緒，我將會回去。', '', 28153),
(156308, 'zhTW', '|cFF0000FF(任務)|r航向提拉加德海灣。', '|cFF0000FF(任務)|r航向提拉加德海灣。', 28153),
(156307, 'zhTW', '|TInterface\\Icons\\ABILITY_DEATHKNIGHT_DEATHSIPHON2.BLP:20|t%s開始施放|cFFFF0000|Hspell:265360|h[狡詐詭計]|h|r！', '遠方出現了一道投影…', 28153),
(156306, 'zhTW', '', '勇士，非常感謝你的協助。', 28153),
(156305, 'zhTW', '', '過去的陰影糾纏著我們。', 28153),
(156304, 'zhTW', '你知道我一身力量，可是沒帶坦克的時候我都怎麼辦嗎？！做些吃力不坦好的事情！哈哈哈哈哈！', '', 28153),
(156303, 'zhTW', '你想過河拆橋是不是？', '', 28153),
(156302, 'zhTW', '你可別逼我丟錘子！', '', 28153),
(156301, 'zhTW', '願你火焰旺盛。', '', 28153),
(156300, 'zhTW', '不要放過任何機會。', '', 28153),
(156299, 'zhTW', '祝你愉快！', '', 28153),
(156298, 'zhTW', '你有沒有看到我的扳手？', '', 28153),
(156297, 'zhTW', '有什麼事嗎？', '', 28153),
(156296, 'zhTW', '射擊！', '', 28153),
(156286, 'zhTW', '', '這麼多痛苦…這麼多犧牲…', 28153),
(156285, 'zhTW', '', '我該怎麼辦？', 28153),
(156284, 'zhTW', '', '我得自己想辦法走出困境。', 28153),
(156283, 'zhTW', '沙子是紅色的。', '沙子是紅色的。', 28153),
(156282, 'zhTW', '我是怎麼來到這裡的？', '我是怎麼來到這裡的？', 28153),
(156281, 'zhTW', '我的朋友會替我復仇。', '我的朋友會替我復仇。', 28153),
(156280, 'zhTW', '圖拉揚會發光、艾蘭里亞會變暗…嗯…我現在重回戰場，看來也要學點花俏把戲才行。', '', 28153),
(156279, 'zhTW', '我做的還好吧？', '我做的還好吧？', 28153),
(156278, 'zhTW', '我會摧毀你！', '我會摧毀你！', 28153),
(156277, 'zhTW', '這就是你們的結局！', '這就是你們的結局！', 28153),
(156276, 'zhTW', '你阻止不了我們的！', '你阻止不了我們的！', 28153),
(156275, 'zhTW', '感謝聖光我終於不用待在榮譽堡了。那地方的汗臭味真的很驚人。', '', 28153),
(156274, 'zhTW', '今天不行，惡魔！', '今天不行，惡魔！', 28153),
(156273, 'zhTW', '我跟卡德加每個禮拜都會見面下下棋。(但我有發現他總是作弊。)', '', 28153),
(156272, 'zhTW', '我們各自都有本分。', '', 28153),
(156271, 'zhTW', '為了激流堡！', '', 28153),
(156270, 'zhTW', '我跟你老實講，首領老兄。\n\n我總是想參與一場叛變。', '', 28153),
(156269, 'zhTW', '為了聯盟！', '', 28153),
(156268, 'zhTW', '勝利屬於聯盟。', '', 28153),
(156267, 'zhTW', '祝你戰無不克，朋友。', '', 28153),
(156266, 'zhTW', '艾澤拉斯在呼喚，我們必須回應。', '', 28153),
(156265, 'zhTW', '我們為自己的天命而戰。', '', 28153),
(156264, 'zhTW', '無論未來如何，我們都要一起面對。', '', 28153),
(156263, 'zhTW', '我為聯盟而活。', '', 28153),
(156262, 'zhTW', '我們一定要復興激流堡。', '', 28153),
(156261, 'zhTW', '你聽了可能會翻白眼，不過我還是要說…拿起錘子開扁啦！', '', 28153),
(156260, 'zhTW', '你可能會覺得我有次子情結。可是，如果你上面有個哥哥全身都是鑽石，小弟又是著名的探險家，你一定也會很想有自己的特色吧！', '', 28153),
(156259, 'zhTW', '搞什麼？！有人叫我「糖果王」，然後問我能不能給他們幾根棒棒糖！', '', 28153),
(156258, 'zhTW', '我們絕對不會放棄！', '', 28153),
(156257, 'zhTW', '勇士，銅鬚部族感謝你。', '', 28153),
(156256, 'zhTW', '鐵爐堡必勝。', '', 28153),
(156255, 'zhTW', '願你的道路帶給你榮耀。', '', 28153),
(156254, 'zhTW', '願你的錘子每揮必中。', '', 28153),
(156253, 'zhTW', '朋友，願熔爐與你同在。', '', 28153),
(156252, 'zhTW', '錘子，有了…斧頭，有了…我們開工吧！', '', 28153),
(156251, 'zhTW', '你是來幫聯盟的嗎？', '', 28153),
(156250, 'zhTW', '我們三錘團結一心。', '', 28153),
(156249, 'zhTW', '鐵爐堡這就來幫忙了。', '', 28153),
(156248, 'zhTW', '你知道前六個軍團的下場嗎？要不要我跟你說啊？', '', 28153),
(156247, 'zhTW', '士兵，想蹲大牢嗎？', '', 28153),
(156246, 'zhTW', '你在考驗我的耐心。', '', 28153),
(156245, 'zhTW', '我們的任務才剛開始。', '', 28153),
(156244, 'zhTW', '後會有期。', '', 28153),
(156243, 'zhTW', '聖光與你同在。', '', 28153),
(156242, 'zhTW', '面對強大的聯盟，敵人只會嚐到失敗的苦果。', '', 28153),
(156241, 'zhTW', '以聖光之名，擊潰敵人。', '', 28153),
(156240, 'zhTW', '你聲名遠播。', '', 28153),
(156239, 'zhTW', '命運在對我們微笑。', '', 28153),
(156238, 'zhTW', '部落注定滅亡。', '', 28153),
(156237, 'zhTW', '士兵。', '', 28153),
(156236, 'zhTW', '我們都是聯盟的子民。', '', 28153),
(156235, 'zhTW', '', '我們一定要保護艾澤拉斯。出發吧，黑鐵！我們上戰場了！', 28153),
(156234, 'zhTW', '', '我們體內流的血液…跟艾澤拉斯的一模一樣。', 28153),
(156233, 'zhTW', '', '我們的王國鑄造在巨錘和鐵砧之上，我們具有熔火般的心…鋼鐵般的意志。', 28153),
(156232, 'zhTW', '', '山嶽賜給我們生命，賦予我們力量。', 28153),
(156231, 'zhTW', '', '索爾加登跟塞林為了表揚你，準備了一套護甲。抬頭挺胸穿上它吧。', 28153),
(156230, 'zhTW', '', '現在聯盟知道黑鐵的厲害了，你就是最適合代表黑鐵的勇士。', 28153),
(156229, 'zhTW', '', '回山裡來吧。我們幫你準備了特別的東西。', 28153),
(156228, 'zhTW', '', '勇士，黑鐵以你為榮。我已經聽說了，你到處旅行在艾澤拉斯留下許多英勇事蹟。', 28153),
(156227, 'zhTW', '', '我們黑鐵是山嶺熔火所鑄，讓這個世界看你的火光吧！', 28153),
(156226, 'zhTW', '', '艾澤拉斯在等你，去暴風城，開始鑄造你的冒險吧。', 28153),
(156225, 'zhTW', '', '黑鐵矮人不能繼續躲在陰影裡了。', 28153),
(156224, 'zhTW', '', '我們氏族裡有很多人覺得躲在地底下比較安全。但勇者無懼。', 28153),
(156223, 'zhTW', '為了聯盟！', '', 28153),
(156222, 'zhTW', '', '黑鐵接受你的邀請。為了聯盟！', 28153),
(156221, 'zhTW', '', '哈，好國王，不必流於形式！別在意。', 28153),
(156220, 'zhTW', '我們卻一直沒有正式邀請黑鐵矮人加入聯盟…希望你們能原諒這種粗心的錯誤，並且允許我修正。', '', 28153),
(156219, 'zhTW', '', '嗯哼。', 28153),
(156218, 'zhTW', '雖然黑鐵氏族以…獨立自主的精神聞名於世，但黑鐵氏族的堅毅跟忠誠也是眾所皆知。', '', 28153),
(156217, 'zhTW', '你在三錘議會中代表黑鐵矮人，維護了鐵爐堡的秩序跟穩定。', '', 28153),
(156216, 'zhTW', '', '我也很榮幸，國王。', 28153),
(156215, 'zhTW', '攝政女王索瑞森，能再次見面是我的榮幸。', '', 28153),
(156214, 'zhTW', '嘿！我在這裡可忙著。', '', 28153),
(156213, 'zhTW', '', '謝謝你。我們一定要想辦法保住佐司瓦剩下的農地。', 28153),
(156212, 'zhTW', '', '當地有個農夫的豬跑到樹林深處去了。救救那些豬…別讓豬被孢子感染！', 28153),
(156211, 'zhTW', '', '女巫總算無所遁形，我的人民也安全了。感謝你。', 28153),
(156210, 'zhTW', '', '女巫正在想辦法混進亞羅姆之地。揭發她們，消除她們的腐化力量，別讓她們傷害任何人。', 28153),
(156209, 'zhTW', '<提供凝血粉：|TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', '<提供凝血粉：|TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', 28153),
(156208, 'zhTW', '<提供遠古托爾托卷軸：|TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', '<提供遠古托爾托卷軸：|TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', 28153),
(156207, 'zhTW', '<提供海膽鹽水：|TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', '<提供海膽鹽水：|TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', 28153),
(156206, 'zhTW', '<提供止血香料：|TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', '<提供止血香料：|TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', 28153),
(156205, 'zhTW', '保持敏銳，$n。當我需要更多原料時就會給你指引。', '', 28153),
(156204, 'zhTW', '朋友，我們無能為力了。死亡羅亞把他帶走了！', '', 28153),
(156203, 'zhTW', '嗯。這恐怕…有點超出我的能力範圍。', '', 28153),
(156202, 'zhTW', '賈米爾‧阿布浩辛恐懼地退縮。', '', 28153),
(156201, 'zhTW', '…賈米爾？', '', 28153),
(156200, 'zhTW', '隨時。', '', 28153),
(156199, 'zhTW', '來…國王應該醒了，現在。', '', 28153),
(156198, 'zhTW', '他的血止不住。快點，$n，馬上把凝血粉給我！', '', 28153),
(156196, 'zhTW', '賈米爾‧阿布浩辛的吟咒聲越來越大聲而急迫。', '', 28153),
(156195, 'zhTW', '完成了！現在我會施用藥劑。', '', 28153),
(156194, 'zhTW', '賈米爾‧阿布浩辛開始默念某種禱詞。', '', 28153),
(156193, 'zhTW', '好的，三小搓。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156192, 'zhTW', '我已經七百年沒調製過了。我倒想看你是不是能想起比你祖父的祖父還要老的事情。', '', 28153),
(156191, 'zhTW', '你忘記配方了？！', '', 28153),
(156190, 'zhTW', '是一撮還是兩撮？…$n，幫我把卷軸拿過來。', '', 28153),
(156188, 'zhTW', '謝謝你。我正在以最快的速度調配。要有耐心。', '', 28153),
(156187, 'zhTW', '沒有嗎？酋爾，你最好快點把藥拿來…', '', 28153),
(156186, 'zhTW', '我要鹽水，去放食材的地方找一下。', '', 28153),
(156185, 'zhTW', '別讓那些克洛格逃走！', '別讓那些克洛格逃走！', 28153),
(156184, 'zhTW', '我準備好了，酋爾。', '我準備好了，酋爾。', 28153),
(156183, 'zhTW', '這些原料很棘手，我需要全神貫注。你必須取代我的雙手完成這份藥水。記住，國王正處在生死關頭。\n\n你準備好要開始了嗎？', '', 28153),
(156182, 'zhTW', '', '如果這個流放者所言不假，你就必須在附近搜索。千萬小心，賈克拉傑可能還沒走遠。', 28153),
(156181, 'zhTW', '嗯，我不知道你在乎！要從哪裡開始？\n\n我們每隔幾年都會前往納茲米爾朝聖。有時候是五年，其他時候則可能是二十年，一切都取決於托加何時準備好說故事。\n\n我們聽到許多耳語和流言，說托加有許多故事要傳授給我們，而那就是我們啟程朝聖的時候。我們來這裡，坐下，並聆聽托加告訴我們的每個故事，然後我們把這些故事分享給任何我們遇到的人。\n\n你應該要知道自己算走運了。我們很少像這樣這麼多人齊聚一堂。這對你的$r朋友來說，本身就已經是某種傳奇了。', '', 28153),
(156180, 'zhTW', '有我在…想都別想…', '有我在…想都別想…', 28153),
(156179, 'zhTW', '跟我說說你的這趟旅行。', '跟我說說你的這趟旅行。', 28153),
(156178, 'zhTW', '沒有人能在我的看守下逃離！', '沒有人能在我的看守下逃離！', 28153),
(156177, 'zhTW', '這次就算我們平手吧。', '', 28153),
(156176, 'zhTW', '我從來沒見過這種新火藥。', '', 28153),
(156175, 'zhTW', '波拉勒斯是我的。', '', 28153),
(156174, 'zhTW', '發生什麼事了？', '發生什麼事了？', 28153),
(156173, 'zhTW', '', '為了部落！', 28153),
(156172, 'zhTW', '', '很好，很好！現在帶我們通過炸藥，到橋另一端去。', 28153),
(156171, 'zhTW', '', '繼續前進！抓住城裡所有的守衛…還有他們的領袖！', 28153),
(156170, 'zhTW', '', '來抓我們啊，懦夫！', 28153),
(156169, 'zhTW', '', '部落會撕裂你們！', 28153),
(156168, 'zhTW', '', '庫爾提拉斯！你們和聯盟的協議就是你們的死刑！', 28153),
(156167, 'zhTW', '', '進到城裡，抓住裡面的守衛，越多越好！', 28153),
(156166, 'zhTW', '', '弗林！快點過來！', 28153),
(156165, 'zhTW', '我是怎麼失敗的？', '我是怎麼失敗的？', 28153),
(156164, 'zhTW', '', '時候到了！殺掉船長，霧帆的男男女女會繼續保有自由！', 28153),
(156163, 'zhTW', '', '你以為自己知道和壞男孩談戀愛的感覺如何嗎？親愛的，你根本不懂…', 28153),
(156162, 'zhTW', '', '奇怪…我怎麼沒發現我的庫爾提拉斯口音不見了。', 28153),
(156161, 'zhTW', '', '有啊，我當然有羊法杖。不然你以為「毛卜師」這名字是誰想的？', 28153),
(156160, 'zhTW', '在我們走之前，先偷幾把武器吧。', '在我們走之前，先偷幾把武器吧。', 28153),
(156159, 'zhTW', '買賣人民…這樣做是錯的。', '買賣人民…這樣做是錯的。', 28153),
(156158, 'zhTW', '攪拌中', '攪拌中', 28153),
(156157, 'zhTW', '我們狐狸人再也不想忍受了！', '我們狐狸人再也不想忍受了！', 28153),
(156156, 'zhTW', '他們還沒見識到我們的真本事呢！', '', 28153),
(156155, 'zhTW', '我這輩子再也不想看到塞斯拉克了。', '我這輩子再也不想看到塞斯拉克了。', 28153),
(156154, 'zhTW', '這就是為什麼你不該挑釁烏龜！', '', 28153),
(156153, 'zhTW', '我以為他們會把我吃掉！', '我以為他們會把我吃掉！', 28153),
(156152, 'zhTW', '沙啊，我真高興你來了！', '沙啊，我真高興你來了！', 28153),
(156151, 'zhTW', '', '都這麼多年了，你還是這麼惹人厭？有些事真的不會變…', 28153),
(156150, 'zhTW', '', '真正的戰鬥即將到來。', 28153),
(156149, 'zhTW', '', '我會盡力而為。', 28153),
(156148, 'zhTW', '', '接下來的路會充滿艱辛。', 28153),
(156147, 'zhTW', '那比我想像的還要痛。', '那比我想像的還要痛。', 28153),
(156146, 'zhTW', '我拿了他們幾塊水晶…所以最後笑的人是我。哈！', '', 28153),
(156145, 'zhTW', '這個殼是非賣品！', '', 28153),
(156144, 'zhTW', '反正這些塞斯拉克也付不起我要的錢。', '', 28153),
(156143, 'zhTW', '無信者一點也不尊重年紀或是智慧。', '', 28153),
(156142, 'zhTW', '我會把這個故事說給祖達薩的每個人聽！', '', 28153),
(156141, 'zhTW', '', '我們不能讓世界墮入黑暗。', 28153),
(156140, 'zhTW', '總算啊，我轉運了！', '', 28153),
(156139, 'zhTW', '大酋長要求我們消滅這個區域的聯盟軍力。快點執行！', '', 28153),
(156138, 'zhTW', '', '現在不是做夢的時候了。', 28153),
(156137, 'zhTW', '聯盟的蠢貨竟敢在附近紮營。去拜訪他們吧…讓他們知道，聯盟的野心有多容易破滅。', '', 28153),
(156136, 'zhTW', '聯盟部隊出沒在你的所在位置附近。趕快去解決他們。', '', 28153),
(156135, 'zhTW', '', '你找海洋之女有什麼事？', 28153),
(156134, 'zhTW', '聯盟膽怯了！黑暗女王知道了一定很高興。', '', 28153),
(156133, 'zhTW', '果斷！毫不猶疑！聯盟應該見識到我們的怒火了。', '', 28153),
(156132, 'zhTW', '開始射擊！', '', 28153),
(156131, 'zhTW', '聯盟…可笑！下次他們想阻礙我們的計畫，應該會再三考慮吧。', '', 28153),
(156130, 'zhTW', '', '我們前方的路還很長。', 28153),
(156129, 'zhTW', '屏住呼吸，勇士！', '', 28153),
(156128, 'zhTW', '', '聯盟屹立不搖。', 28153),
(156127, 'zhTW', '', '我知道該做什麼。', 28153),
(156126, 'zhTW', '', '星星之火，可以燒掉整個世界。', 28153),
(156125, 'zhTW', '', '如果你不控制力量…就會被力量控制。', 28153),
(156124, 'zhTW', '為了羅德隆。', '為了羅德隆。', 28153),
(156123, 'zhTW', '', '我絕對不會忘記。', 28153),
(156122, 'zhTW', '', '我們都有揮之不去的過往。', 28153),
(156121, 'zhTW', '終於，有點有趣的了！', '終於，有點有趣的了！', 28153),
(156120, 'zhTW', '', '不要輕易相信別人。', 28153),
(156119, 'zhTW', '我的靈魂感到飢渴。', '我的靈魂感到飢渴。', 28153),
(156118, 'zhTW', '大開殺戒！', '大開殺戒！', 28153),
(156117, 'zhTW', '我最喜歡看人家辦事乾淨俐落了，這樣征戰進度才不會落後。', '', 28153),
(156116, 'zhTW', '敵人碰上部落…敵人慘敗…這就是世界的常態。', '', 28153),
(156115, 'zhTW', '不愧是黑暗女王的勇士。', '', 28153),
(156114, 'zhTW', '這樣也算完成任務了…就是不夠優雅。好了，去做你本來該做的事吧。', '', 28153),
(156113, 'zhTW', '啊…把敵人切成一塊塊的，真令人愉快。就算是工作也要好好享受勝利！', '', 28153),
(156112, 'zhTW', '做得好。這樣計畫就可以繼續執行了。', '', 28153),
(156111, 'zhTW', '部落馬上就要占領這裡了，但是有個強大的敵人阻礙了我們的計畫。幫我們的部隊開路吧。', '', 28153),
(156110, 'zhTW', '大酋長對這個地方的計畫可沒有包括那個…怪物。消滅牠！', '', 28153),
(156109, 'zhTW', '', '聽我說，你這個自作聰明的傢伙…你有沒有想過，你其實活在「平行世界」，而我的世界才是真正的時間線？嗯…你開始懷疑了嗎？', 28153),
(156108, 'zhTW', '你附近有個名聲響亮的敵人。幫我把屍體帶回來，讓我研究，好嗎？', '', 28153),
(156107, 'zhTW', '附近有個敵人殺了我們許多新兵。聽說你是「部落的勇士」。你應該比新兵厲害吧？', '', 28153),
(156106, 'zhTW', '', '你們對抗燃燒軍團…卻沒有想過找我們幫忙？搞什麼啊？這關係到整個宇宙的命運，竟然沒有找我們…呸，算了啦！', 28153),
(156105, 'zhTW', '有報告說，你現在附近有強大的敵人。交給你解決了…好好享受吧！', '', 28153),
(156104, 'zhTW', '大酋長要你消滅這附近某個目標。別讓她失望。', '', 28153),
(156103, 'zhTW', '', '自從我來了以後，奧格瑪的獸人好像愈站愈直了。', 28153),
(156102, 'zhTW', '', '有個綠皮獸人說我的眼睛像「鎖兒」一樣拴住他的心…我就把他脊椎打斷了。', 28153),
(156101, 'zhTW', '我逐漸感到飢餓…', '我逐漸感到飢餓…', 28153),
(156100, 'zhTW', '', '有話快說。我趕著去打勝仗！', 28153),
(156099, 'zhTW', '', '瑪格哈獸人的心都很純淨又堅強。', 28153),
(156098, 'zhTW', '', '我們是來打勝仗的。', 28153),
(156097, 'zhTW', '', '我會聽你說的話…但主要還是看你的行為。', 28153),
(156096, 'zhTW', '', '我真不敢想像要是讓她們完成儀式的話，會發生什麼事。非常感謝。', 28153),
(156095, 'zhTW', '', '說吧。', 28153),
(156094, 'zhTW', '', '我會再次看到德拉諾的天空。', 28153),
(156093, 'zhTW', '', '戰爭是我們的一切。', 28153),
(156092, 'zhTW', '', '願你的敵人橫屍遍野。', 28153),
(156091, 'zhTW', '', '看來寇連恩這裡的女巫想進行某種新的儀式。阻止她們，別讓事態惡化！', 28153),
(156090, 'zhTW', '', '心懷榮耀而戰，雖死猶榮！', 28153),
(156089, 'zhTW', '', '瑪格哈一定會獲得勝利。', 28153),
(156088, 'zhTW', '', '死得壯烈。', 28153),
(156087, 'zhTW', '', '榮耀與你同行。', 28153),
(156086, 'zhTW', '', 'Throm-ka！', 28153),
(156085, 'zhTW', '', 'Lok-tar！', 28153),
(156084, 'zhTW', '可憐的鳥兒…願你們的靈魂永遠自在飛翔。', '', 28153),
(156083, 'zhTW', '這裡的獵鷹受到了女巫的詛咒。我也想救牠們，但是已經太遲了。用這些洋蔥對付牠們！', '', 28153),
(156082, 'zhTW', '', '很好。聯盟什麼時候才會學乖，才會知道沒有人能阻擋贊達拉？', 28153),
(156081, 'zhTW', '', '你做得很好。聯盟看到強大的贊達拉應該嚇得發抖吧。', 28153),
(156080, 'zhTW', '', '聯盟很快就會知道，贊達拉是不可能被征服的。', 28153),
(156079, 'zhTW', '', '我收到消息，有聯盟部隊在附近聚集。阻止他們，無論他們想做什麼。', 28153),
(156078, 'zhTW', '', '聯盟以為他們有辦法對抗贊達拉帝國。讓他們知道自己錯了。', 28153),
(156077, 'zhTW', '', '好了，各位，開始叛變吧！霧帆拒絕賣出我們的自由！', 28153),
(156076, 'zhTW', '', '我本來很討厭別人叫我「女王大人」，不過…嗯…好，我准許你這樣叫我！', 28153),
(156075, 'zhTW', '', '聯盟就在附近鬼鬼祟祟的。解決他們，讓他們知道贊達拉帝國有多可怕。', 28153),
(156074, 'zhTW', '問題解決了，我們總算可以安心一點了。', '', 28153),
(156073, 'zhTW', '為聯盟奮戰的士兵都不會忘記你今天所做的事。', '', 28153),
(156072, 'zhTW', '你做得很好。有空我可以跟你說第三次戰爭的事。你的表現讓我想起當年…', '', 28153),
(156071, 'zhTW', '做得好。這些資源對我們有長遠的幫助。', '', 28153),
(156070, 'zhTW', '這個地方相當棘手，讓我想起第二次獸人戰爭。你能幫忙一下嗎？', '', 28153),
(156069, 'zhTW', '我們在鄰近區域遇到麻煩了，你能幫忙處理一下嗎？', '', 28153),
(156068, 'zhTW', '', '我跟爸爸的關係當然不太好啊。所有的親子關係都有麻煩的地方，更何況我爸的脾氣硬得像鑽石！', 28153),
(156067, 'zhTW', '你附近那個地區對我們有重要用途。去消滅敵人，鞏固地區安全。', '', 28153),
(156066, 'zhTW', '根據情報，這附近有重要資源。如果能夠取得，一定能扭轉戰局。', '', 28153),
(156065, 'zhTW', '', '來啊…拿矮人來開玩笑啊，我就打斷你的腿，讓你知道什麼叫矮！', 28153),
(156064, 'zhTW', '我跳舞的時候，亂我者死。', '', 28153),
(156063, 'zhTW', '你在這裡做什麼？', '你在這裡做什麼？', 28153),
(156062, 'zhTW', '', '基羅和我只是路過而已。我們的下一站：無信者帝國。\n\n我的計畫就緒了。\n\n那些塞斯拉克佬永遠都不會知道是什麼攻擊了他們。', 28153),
(156061, 'zhTW', '', '我們又見面了。', 28153),
(156060, 'zhTW', '你為第七軍團的陣亡將士帶來了榮耀。我們會妥善運用這個據點的。', '', 28153),
(156059, 'zhTW', '你做得很好。接下來就交給我的士兵吧。', '', 28153),
(156058, 'zhTW', '', '黑鐵矮人一直都住在火山裡。你再戳我就讓你知道黑鐵爆發的威力！', 28153),
(156057, 'zhTW', '優秀的戰術。我們馬上就能好好運用這個地方了。', '', 28153),
(156056, 'zhTW', '很好。這些資源夠讓第七軍團用很久了。', '', 28153),
(156055, 'zhTW', '我們需要你幫忙拿下這個區域。只靠我的兵力沒辦法攻下來。', '', 28153),
(156054, 'zhTW', '我們為了拿下附近那個區域，損失很多士兵。去幫忙解決那裡的威脅。', '', 28153),
(156053, 'zhTW', '第七軍團的斥候說這個地點非常重要，為了我軍去把它拿下吧。', '', 28153),
(156052, 'zhTW', '', '我們三錘團結一心。', 28153),
(156051, 'zhTW', '第七軍團需要這附近的資源，無論用什麼方法都要取得這些資源。', '', 28153),
(156050, 'zhTW', '', '願你的錘子每揮必中。', 28153),
(156049, 'zhTW', '', '願黑鐵砧眷顧你。', 28153),
(156048, 'zhTW', '', '黑鐵矮人會在這個世界佔有一席之地。', 28153),
(156047, 'zhTW', '', '你快走吧，我還有事要做！', 28153),
(156046, 'zhTW', '', '你可以離開了。', 28153),
(156045, 'zhTW', '', '你走吧。', 28153),
(156044, 'zhTW', '轟炸我的目標！', '轟炸我的目標！', 28153),
(156043, 'zhTW', '火砲！發射！', '火砲！發射！', 28153),
(156042, 'zhTW', '已標示毀滅目標！', '已標示毀滅目標！', 28153),
(156041, 'zhTW', '火炮就位！朝我的目標發射！', '火炮就位！朝我的目標發射！', 28153),
(156040, 'zhTW', '', '我們直接說重點吧。', 28153),
(156039, 'zhTW', '', '嗯？我在聽啊。', 28153),
(156038, 'zhTW', '', '你在女王面前最好注意一下禮節。', 28153),
(156037, 'zhTW', '沙漠還沒把你吞噬真是太好了。', '', 28153),
(156036, 'zhTW', '', '山嶺賜給我們力量。', 28153),
(156035, 'zhTW', '', '你現在面對的是黑鐵部族的攝政女王。', 28153),
(156034, 'zhTW', '', '黑鐵部族會得到應有的尊重。', 28153),
(156033, 'zhTW', '', '聯盟需要我們的法術，也同樣需要我們的力量。', 28153),
(156032, 'zhTW', '著裝打扮', '著裝打扮', 28153),
(156031, 'zhTW', '清理中', '清理中', 28153),
(156030, 'zhTW', '', '做得好。這些資源對贊達拉非常有用。', 28153),
(156029, 'zhTW', '', '真厲害。大家很快就知道，絕對不能跟贊達拉帝國作對。', 28153),
(156028, 'zhTW', '', '部落的勇士又一次獲勝了。戰鬥中有你當盟友，真讓人放心。', 28153),
(156027, 'zhTW', '', '贊達拉感謝你。', 28153),
(156026, 'zhTW', '', '納薩諾斯覺得我們攻不下這裡。去證明他是錯的。', 28153),
(156025, 'zhTW', '', '為了這場仗，必須拿下附近的據地才行。去做你擅長的事吧。', 28153),
(156024, 'zhTW', '', '為了盟友，我們必須守住這裡。要是有人敢妨礙你，就毫不留情解決掉吧。', 28153),
(156023, 'zhTW', '', '這附近有資源，對我們的計畫有幫助。你去取得那些資源。', 28153),
(156022, 'zhTW', '點點和朵朵兩三下就會吃光光。', '', 28153),
(156021, 'zhTW', '點點和朵朵很倔強的，肚子餓的時候絕對不會拉車。幫他們找點食物吧。', '', 28153),
(156020, 'zhTW', '滾！', '滾！', 28153),
(156019, 'zhTW', '走開！', '走開！', 28153),
(156018, 'zhTW', '你不准碰！', '你不准碰！', 28153),
(156017, 'zhTW', '你敢靠近，我就用石頭砸你的頭！', '你敢靠近，我就用石頭砸你的頭！', 28153),
(156016, 'zhTW', '走開，不然我殺了你！', '走開，不然我殺了你！', 28153),
(156015, 'zhTW', '', '快去收集治療蛇人需要的東西。我來告訴喬瓦芭目前知道的消息。', 28153),
(156014, 'zhTW', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a開放新建築！', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a開放新建築！', 28153),
(156013, 'zhTW', '我去過許多地方，效忠過很多大酋長。別懷疑，你也會遇到很多大酋長。', '', 28153),
(156012, 'zhTW', '你幹嘛一直戳我？又要打仗了嗎？我在說什麼啊…有哪天是不打仗的。', '', 28153),
(156011, 'zhTW', '如果你知道我的斧頭上沾了多少人的血，就不會再一直來煩我！', '', 28153),
(156010, 'zhTW', '我年紀大了，沒空跟你胡鬧。', '', 28153),
(156009, 'zhTW', '我效忠部落。', '', 28153),
(156008, 'zhTW', '有話快說…而且你最好別想唬我。', '', 28153),
(156007, 'zhTW', '現在沒空跟你閒聊。', '', 28153),
(156006, 'zhTW', '你找我有什麼事？', '', 28153),
(156005, 'zhTW', 'Throm-ka！', '', 28153),
(156004, 'zhTW', 'Lok-tar！', '', 28153),
(156003, 'zhTW', '我是薩魯法爾。布洛克斯的弟弟。', '', 28153),
(156002, 'zhTW', '部落永存不滅。', '', 28153),
(156001, 'zhTW', '我不喜歡這個狀況，我要逃了！', '我不喜歡這個狀況，我要逃了！', 28153),
(156000, 'zhTW', '在戰場上，策略與力量都很重要。', '', 28153),
(155999, 'zhTW', '萬歲！我自由了！', '萬歲！我自由了！', 28153),
(155998, 'zhTW', '我要離開這裡！', '我要離開這裡！', 28153),
(155997, 'zhTW', '我們才是卡林多真正的力量。', '', 28153),
(155996, 'zhTW', '為什麼會發生這種事？', '為什麼會發生這種事？', 28153),
(155995, 'zhTW', '我不想死，掩護我！', '我不想死，掩護我！', 28153),
(155994, 'zhTW', '發生什麼事了！？', '發生什麼事了！？', 28153),
(155993, 'zhTW', '小心一點，到處都有瘋狂的人類！', '小心一點，到處都有瘋狂的人類！', 28153),
(155992, 'zhTW', '你要是可以的話…千萬別變老。', '', 28153),
(155991, 'zhTW', '失去了榮譽，我們就一無所有。', '', 28153),
(155990, 'zhTW', '能今日在戰場上死去，那才是獸人該有的死法。', '', 28153),
(155989, 'zhTW', '願你迎向敵人時光榮戰死。', '', 28153),
(155988, 'zhTW', '你能不能引導樂樂到安全的海藻？', '', 28153),
(155987, 'zhTW', '「樂樂與海」。托爾托的年輕人一離開沙灘，就必須靠自己找到安全地點。', '', 28153),
(155986, 'zhTW', '', '那些女巫的手下都解決掉了，伐木工人也可以回來了。謝謝你保護他們。', 28153),
(155985, 'zhTW', '我要直接把這抹去…', '', 28153),
(155984, 'zhTW', '', '那些女巫派出手下來佔領我們的伐木區。快把伐木工集合起來，燒死那些女巫！', 28153),
(155983, 'zhTW', '', '造箭師谷地終於不受女巫的魔法影響了，這要感謝你。', 28153),
(155982, 'zhTW', '', '女巫的人佔領了造箭師谷地！快幫忙救出居民，收復那座城鎮！', 28153),
(155981, 'zhTW', '噓…這裡，$n！', '', 28153),
(155980, 'zhTW', '', '我們必須挺身而出。', 28153),
(155979, 'zhTW', '', '只要時候一到，我就會出現。', 28153),
(155978, 'zhTW', '', '把事情做好。', 28153),
(155977, 'zhTW', '', '我們要幫助無助的人。', 28153),
(155976, 'zhTW', '', '沒有榮譽，我們就一無是處。', 28153),
(155975, 'zhTW', '', '如果你敢告訴任何人，我就把你抓去餵獅鷲獸。聽到了嗎？！', 28153),
(155974, 'zhTW', '', '我會奮戰到最後一刻。', 28153),
(155973, 'zhTW', '', '<哼咿>噢…請、請你假裝沒聽到好不好？', 28153),
(155972, 'zhTW', '', '我是…受過專業訓練的…侍從…有鋼鐵般的紀律…', 28153),
(155971, 'zhTW', '', '別這樣，好癢！快住手！', 28153),
(155970, 'zhTW', '', '喂！別動手動腳的！', 28153),
(155969, 'zhTW', '', '我們一定可以的。', 28153),
(155968, 'zhTW', '', '心懷榮耀作戰。', 28153),
(155967, 'zhTW', '', '保持航向。', 28153),
(155966, 'zhTW', '', '祝福大家。我要留在這裡，跟其他狐狸人一起戰鬥。', 28153),
(155965, 'zhTW', '', '下次見面跟我說故事吧！', 28153),
(155964, 'zhTW', '', '為了庫爾提拉斯！', 28153),
(155963, 'zhTW', '', '我還有職責在身。', 28153),
(155962, 'zhTW', '', '再見。', 28153),
(155961, 'zhTW', '', '情況如何？', 28153),
(155960, 'zhTW', '', '終於要動手了嗎！', 28153),
(155959, 'zhTW', '', '我訓練了一輩子就是為了現在。', 28153),
(155956, 'zhTW', '', '一起努力就一定能讓庫爾提拉斯團結起來。', 28153),
(155955, 'zhTW', '', '我一直想冒險。', 28153),
(155953, 'zhTW', '谷地對我而言就是家。', '', 28153),
(155952, 'zhTW', '來日方長，互相幫忙。', '', 28153),
(155950, 'zhTW', '自己小心一點。', '', 28153),
(155947, 'zhTW', '我們有難同當。', '', 28153),
(155946, 'zhTW', '', '警告：歸源衝擊能量即將達到最大值。', 28153),
(155945, 'zhTW', '', '請注意：歸源衝擊能量即將達到負荷極限。', 28153),
(155944, 'zhTW', '', '請注意：能量即將達到上限。', 28153),
(155943, 'zhTW', '', '警告：能量層級接近最大值。', 28153),
(155942, 'zhTW', '動動筋骨就好。', '', 28153),
(155941, 'zhTW', '我心在谷地。', '', 28153),
(155939, 'zhTW', '', '有什麼事嗎？', 28153),
(155938, 'zhTW', '你有聽到嗎？深淵在低語著什麼。好像…好像是說你！什麼？喔，我知道了。它說：不要再點派克了，你這個怪物。太神奇了！', '', 28153),
(155937, 'zhTW', '喔，他們有很多種不一樣的用途！$b$b除了明顯可以用來扎針以外，刺針本身也有數種有用的屬性。磨成細粉，就成了很棒的粘著劑。你可以將它們煮沸，將油脂用來去汙，危急時還可以用來剔牙！', '', 28153),
(155936, 'zhTW', '我必須親自宰掉你，跟你其他的笨朋友一起！', '', 28153),
(155935, 'zhTW', '通戈… 被外來者殺掉了？我一定是高估他了！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155934, 'zhTW', '我不該這樣死去…不…啊啊…', '', 28153),
(155933, 'zhTW', '我發過誓要維持這裡的和平。但因為你，我想要破例了。', '', 28153),
(155932, 'zhTW', '你儘管煩人沒關係。浪潮賢者的耐心可不是浪得虛名的。', '', 28153),
(155931, 'zhTW', '', '你好！', 28153),
(155930, 'zhTW', '你想拿這些刺針做什麼呢，到底？', '你想拿這些刺針做什麼呢，到底？', 28153),
(155929, 'zhTW', '供給中', '供給中', 28153),
(155928, 'zhTW', '你在幹嘛，你醉了嗎？你竟然自己喝醉沒找我？太不夠意思啦。', '', 28153),
(155927, 'zhTW', '水手，稍安勿躁。我知道我帥到不行，但我們還有任務要做。', '', 28153),
(155926, 'zhTW', '唔，除非你被強迫加入海軍…或是被海盜抓走…或是你被強迫加入海軍又被海盜抓走…', '', 28153),
(155925, 'zhTW', '唉，空曠的大海…嘴中哼著小曲…海風撫過胸毛…那才叫自由啊。', '', 28153),
(155924, 'zhTW', '勇敢向前。', '', 28153),
(155923, 'zhTW', '注意海面。', '', 28153),
(155922, 'zhTW', '下次換我請客。', '', 28153),
(155921, 'zhTW', '走吧，我們去賺錢。', '', 28153),
(155920, 'zhTW', '再見啦。', '', 28153),
(155919, 'zhTW', '<神王拉斯塔哈的呼吸短促且費力。包紮在胸前的繃帶被血濕透。>', '', 28153),
(155918, 'zhTW', '在外頭要小心。', '', 28153),
(155917, 'zhTW', '保持火藥乾燥。', '', 28153),
(155916, 'zhTW', '怎麼啦？', '', 28153),
(155915, 'zhTW', '太好了！我要趕快開始製作需要的藥劑了。我敢說當地的漁夫一定很高興那些討厭的臭鳥變少了。', '', 28153),
(155914, 'zhTW', '我是國王的御醫，賈米爾‧阿布浩辛。這並不是第一次我為國王治傷，羅亞在上，這也不會是最後一次。', '', 28153),
(155913, 'zhTW', '這裡的魚和螃蟹身上有我要的東西，很不湊巧的是，海鷗也很喜歡這些東西。請你把我需要的東西帶回來給我，順便把這些討厭的臭鳥解決掉！', '', 28153),
(155912, 'zhTW', '治療的如何？', '治療的如何？', 28153),
(155911, 'zhTW', '就是這樣…就是這樣！讓部落的威名撼動大地！', '', 28153),
(155910, 'zhTW', '我跟老拉斯塔哈一起經歷過很多事。不過這次…\n\n<賈米爾指著神王殘破的形體。>\n\n這次狀況非常糟糕。', '', 28153),
(155909, 'zhTW', '<酋爾盯著他的混合藥劑，頭並沒有抬起。>\n\n國王的時間不多了。', '', 28153),
(155908, 'zhTW', '朋友，工作就是工作。', '', 28153),
(155907, 'zhTW', '這樣就可以了。沒辦法利用它來對付我們的敵人，真是太可惜了。', '', 28153),
(155906, 'zhTW', '這附近有非常強大的敵人…這樣對我們的部隊不利。你知道該怎麼做了吧。', '', 28153),
(155905, 'zhTW', '大酋長一定會對你的表現很滿意。', '', 28153),
(155904, 'zhTW', '附近有個非常危險的敵人。先下手為強，別讓敵人破壞我們的計畫。', '', 28153),
(155903, 'zhTW', '這個區域的敵方部隊會破壞我們的計畫。大酋長希望有人把問題處理掉。千萬別讓她失望。', '', 28153),
(155902, 'zhTW', '瑞尼克怎麼會讓這種事發生？', '瑞尼克怎麼會讓這種事發生？', 28153),
(155901, 'zhTW', '別又來了！', '別又來了！', 28153),
(155900, 'zhTW', '會有人為此付出代價！', '會有人為此付出代價！', 28153),
(155899, 'zhTW', '為何烈酒總被破壞呢？', '為何烈酒總被破壞呢？', 28153),
(155898, 'zhTW', '別動烈酒！', '別動烈酒！', 28153),
(155897, 'zhTW', '看是要付金幣還是鮮血。凡事都有代價。', '', 28153),
(155896, 'zhTW', '嗯，故事的發展不應該是這樣。要不要再試一次？', '', 28153),
(155895, 'zhTW', '你渴嗎？我好渴。', '', 28153),
(155894, 'zhTW', '我洗耳恭聽。', '', 28153),
(155893, 'zhTW', '怎麼了？', '', 28153),
(155892, 'zhTW', '呦呼！', '', 28153),
(155891, 'zhTW', '自己小心。', '', 28153),
(155890, 'zhTW', '下次見了。', '', 28153),
(155889, 'zhTW', '乾杯！', '', 28153),
(155888, 'zhTW', '要烈酒還是麥酒？還是你全都要？', '', 28153),
(155887, 'zhTW', '想來點什麼？', '', 28153),
(155886, 'zhTW', '做得好，$n！', '', 28153),
(155885, 'zhTW', '需要幫忙嗎？', '', 28153),
(155884, 'zhTW', '你可以帶著樂樂找到島上所有的食物，然後到他的小屋去，並且避開他走過的路嗎？', '', 28153),
(155883, 'zhTW', '「簡單生活。」有一天樂樂決定到遠方的島嶼過著平靜的生活。', '', 28153),
(155882, 'zhTW', '你知道當年第二次戰爭，你這種新兵都叫什麼綽號嗎？叫藤壺…因為總是黏著我的屁股！', '', 28153),
(155881, 'zhTW', '樂樂的冒險旅程總是充滿危險。就拿這個故事來說好了…', '', 28153),
(155880, 'zhTW', '托爾托人都喜歡年輕小伙子樂樂環遊世界的故事。', '', 28153),
(155879, 'zhTW', '你到底想怎樣，想聽戰爭故事嗎？', '', 28153),
(155878, 'zhTW', '我年輕的時候，大家都知道什麼時候該閉嘴。', '', 28153),
(155877, 'zhTW', '', '生命的循環真是殘酷…', 28153),
(155876, 'zhTW', '', '有隻烏龜回到水裡了！', 28153),
(155875, 'zhTW', '', '感謝你，英雄！', 28153),
(155874, 'zhTW', '', '托爾托人總是生活在危險之中，像是海灘上的烏龜。保護牠們，讓牠們安全回到海洋裡！', 28153),
(155873, 'zhTW', '', '做得好！雖然這不是機器原本的用途，但效果還是一樣好。', 28153),
(155872, 'zhTW', '', '如果他們沒戴識別徽章，格殺勿論！', 28153),
(155871, 'zhTW', '', '是哪種白癡會搞丟好幾箱炸彈？', 28153),
(155870, 'zhTW', '', '亞羅姆之地的人把採礦機器修好了。用這台部落做的機器來對抗他們吧！', 28153),
(155869, 'zhTW', '', '我可以取消你的薪資，平衡超支的成本！', 28153),
(155868, 'zhTW', '', '我可能需要裁減人員來平衡支出。', 28153),
(155867, 'zhTW', '有人入侵鑄造廠！報告，有人入 -', '有人入侵鑄造廠！報告，有人入 -', 28153),
(155866, 'zhTW', '榮耀指引你。', '', 28153),
(155865, 'zhTW', '為了海軍總帥。', '', 28153),
(155864, 'zhTW', '為了庫爾提拉斯。', '', 28153),
(155863, 'zhTW', '別暴露弱點！', '', 28153),
(155862, 'zhTW', '保持警戒。', '', 28153),
(155861, 'zhTW', '祝你一帆風順。', '', 28153),
(155860, 'zhTW', '解散！', '', 28153),
(155859, 'zhTW', '', '', 28153),
(155858, 'zhTW', '', '', 28153),
(155857, 'zhTW', '有屁快放！', '', 28153),
(155856, 'zhTW', '', '', 28153),
(155855, 'zhTW', '我打過的仗比你吃過的飯還多。', '', 28153),
(155854, 'zhTW', '前線有消息嗎？', '', 28153),
(155853, 'zhTW', '你需要什麼？', '', 28153),
(155852, 'zhTW', '我這身老骨頭渴望戰鬥。', '', 28153),
(155851, 'zhTW', '有事要報告嗎？', '', 28153),
(155850, 'zhTW', '你好！', '', 28153),
(155849, 'zhTW', '', '不要欠別人人情。', 28153),
(155848, 'zhTW', '', '如海如風，我們自在輕鬆。', 28153),
(155847, 'zhTW', '', '庫爾提拉斯風雨無懼。', 28153),
(155846, 'zhTW', '', '我在聽。', 28153),
(155845, 'zhTW', '', '有話快說。', 28153),
(155844, 'zhTW', '我們要堅持下去。', '', 28153),
(155843, 'zhTW', '別畏懼潮水的流動。', '', 28153),
(155842, 'zhTW', '海流指引你。', '', 28153),
(155841, 'zhTW', '不要遺忘死者。', '', 28153),
(155840, 'zhTW', '要永遠看向大海。', '', 28153),
(155839, 'zhTW', '', '我沒空閒聊。', 28153),
(155838, 'zhTW', '風暴會在我們心中成形。', '', 28153),
(155837, 'zhTW', '我來此決鬥。', '我來此決鬥。', 28153),
(155836, 'zhTW', '不對。再試一次。', '', 28153),
(155835, 'zhTW', '哇喔，配到了！', '', 28153),
(155834, 'zhTW', '做得好，$n！', '', 28153),
(155833, 'zhTW', '這些年來我收集了不少東西。看看你能不能配對成功。', '', 28153),
(155832, 'zhTW', '前提是你喜歡跑步。如果喜歡飛行，就該見見「萬風羅亞」帕骷，她的圖騰比較少，但能提供遍及全城的飛行捷徑。', '', 28153),
(155831, 'zhTW', '', '形態的主宰，同時也是狩獵之王的剛克，是位相當強大的羅亞。他能賜你力量，讓遍及城市各處的圖騰，加快你的移動速度。', 28153),
(155830, 'zhTW', '深淵說過你的到來。', '', 28153),
(155829, 'zhTW', '我在聽。', '', 28153),
(155828, 'zhTW', '有什麼事嗎？', '', 28153),
(155827, 'zhTW', '海潮祝福你。', '', 28153),
(155826, 'zhTW', '把木板收起來，馬上就要開船了。我最不想看到船上破個洞。', '', 28153),
(155825, 'zhTW', '我知道他們也是來找艾澤萊晶岩的。真是厲害，不過還沒快到能打敗我們。我們動作快點，別引起他們注意。', '', 28153),
(155824, 'zhTW', '這樣應該就裝完全部了。剛清空這座島，正好就看到贊達拉的船在海面上出現。', '', 28153),
(155823, 'zhTW', '他們也在收集艾澤萊晶岩？嗯，真是太好了，殺掉他們，把晶岩搶過來就對了。', '', 28153),
(155822, 'zhTW', '猴人？在這裡？哈，看來你們永遠也猜不到誰會出現在這座島上。', '', 28153),
(155821, 'zhTW', '我們剛剛發現附近有大量的艾澤萊晶岩。這真是太好了。', '', 28153),
(155820, 'zhTW', '很好。雖然有點血腥又有點噁心，不過又能怎麼樣呢？這總是艾澤萊晶岩嘛。', '', 28153),
(155819, 'zhTW', '哇啊，真是隻大怪物，上面還沾滿了艾澤萊晶岩。你負責把牠殺了，我們來採集艾澤萊晶岩。', '', 28153),
(155818, 'zhTW', '對了，探測器顯示有些艾澤萊晶岩就在你的位置附近。你去看看吧。', '', 28153),
(155817, 'zhTW', '唷呼！真是收穫滿滿。做得好！', '', 28153),
(155816, 'zhTW', '哇，這可是一大塊艾澤萊晶岩。繼續挖下去，我們就可以立刻把碎片運回船上了。', '', 28153),
(155815, 'zhTW', '艾澤萊晶岩探測器顯示這附近有…嗯，艾澤萊晶岩。你去調查看看如何？至於我嘛，我就待在這裡。', '', 28153),
(155814, 'zhTW', '把船開過來，小心別撞壞了。然後把梯板放下來，謝啦。', '', 28153),
(155813, 'zhTW', '我是說，這裡也有可能會出現，像是巨大蜘蛛之類的東西。反正就是，這種事你說不準。', '', 28153),
(155812, 'zhTW', '我很確定就是這個地方。這裡應該會有一大堆艾澤萊晶岩。', '', 28153),
(155811, 'zhTW', '$n！感謝黑暗女王你們來了！雷克薩把一大群庫爾提拉斯佬引到前方的建築裡了。他需要支援！', '$n！感謝黑暗女王你們來了！雷克薩把一大群庫爾提拉斯佬引到前方的建築裡了。他需要支援！', 28153),
(155810, 'zhTW', '快，去下層甲板，操作一座大砲！我們的部隊需要我們！', '', 28153),
(155809, 'zhTW', '這就是瓦德奇斯的遺骸了。他生前是非常強大的龍。', '這就是瓦德奇斯的遺骸了。他生前是非常強大的龍。', 28153),
(155808, 'zhTW', '你可別亂想。', '你可別亂想。', 28153),
(155807, 'zhTW', '除了強大的黑暗力量，什麼都無法奪取他的性命。', '除了強大的黑暗力量，什麼都無法奪取他的性命。', 28153),
(155806, 'zhTW', '這就是瓦德奇斯的遺骸了。他生前是非常強大的龍。', '這就是瓦德奇斯的遺骸了。他生前是非常強大的龍。', 28153),
(155805, 'zhTW', '不過至少是個開始。', '不過至少是個開始。', 28153),
(155804, 'zhTW', '我的心胸可不像我們龍后那麼寬大。', '我的心胸可不像我們龍后那麼寬大。', 28153),
(155803, 'zhTW', '我絕對無法輕易原諒你對凱拉納史卓茲所做的事。', '我絕對無法輕易原諒你對凱拉納史卓茲所做的事。', 28153),
(155802, 'zhTW', '謝謝你了。', '謝謝你了。', 28153),
(155801, 'zhTW', '感謝你的幫助，$n。', '感謝你的幫助，$n。', 28153),
(155800, 'zhTW', '我們可不想再發生這種慘事了。', '我們可不想再發生這種慘事了。', 28153),
(155799, 'zhTW', '為了找到他的長眠之地，死亡領主入侵了我們的晶紅聖所。', '為了找到他的長眠之地，死亡領主入侵了我們的晶紅聖所。', 28153),
(155798, 'zhTW', '在先前與燃燒軍團的戰役中，我們有個同胞被培養成了不死生物。', '在先前與燃燒軍團的戰役中，我們有個同胞被培養成了不死生物。', 28153),
(155797, 'zhTW', '那麼我和$n就去進行任務了。來吧，$c，我帶你到儀式地點去。', '那麼我和$n就去進行任務了。來吧，$c，我帶你到儀式地點去。', 28153),
(155796, 'zhTW', '', '$n已經完成任務回來。他們或許可以幫你，薩勒史卓莎。', 28153),
(155795, 'zhTW', '是你們太大驚小怪。我覺得好多了。', '是你們太大驚小怪。我覺得好多了。', 28153),
(155794, 'zhTW', '撐住別動，我來幫你治療。', '撐住別動，我來幫你治療。', 28153),
(155793, 'zhTW', '你坐都坐不穩了，西奧多！', '你坐都坐不穩了，西奧多！', 28153),
(155792, 'zhTW', '', '做得好，$n！進來我的新辦公室看看吧。', 28153),
(155791, 'zhTW', '', '喂！那是我的獵物，我在算擊殺數！', 28153),
(155790, 'zhTW', '我需要超凡的力量來在戰鬥中與科爾塞克對決。他在我們之間一直是最強的戰士。\n\n我要盡可能從這些水晶上吸取力量，希望這樣就夠了。', '', 28153),
(155789, 'zhTW', '', '這些蜘蛛的數量終於回到安全範圍內了。這裡的居民也不必再擔心走進森林裡會被蜘蛛網黏住了。', 28153),
(155788, 'zhTW', '', '可怕的蜘蛛污染了整座森林，威脅到佐司瓦獵人的生命安全。燒光這些蜘蛛！', 28153),
(155787, 'zhTW', '置換中', '置換中', 28153),
(155786, 'zhTW', '', '做得好。這裡的天氣太惡劣了，這些物資能保護我們部隊。', 28153),
(155785, 'zhTW', '', '我們的斥候說，人類發明了一種方法，不用犧牲動物就能取得毛皮。真是奇怪的方法…但很有用。', 28153),
(155784, 'zhTW', '鋸木場有邪惡的東西，離波拉勒斯太近了，很危險。', '', 28153),
(155783, 'zhTW', '殺得乾淨俐落！海怪敢來庫爾提拉斯的海岸就是找死。', '', 28153),
(155782, 'zhTW', '翼艇隊釣到大魚了，現在他們需要你去幫個忙。', '', 28153),
(155781, 'zhTW', '燃燒中', '燃燒中', 28153),
(155780, 'zhTW', '我們已經身陷其中了，我不會打退堂鼓！', '我們已經身陷其中了，我不會打退堂鼓！', 28153),
(155779, 'zhTW', '如果今天是我的死期…我只會死在戰場上！', '如果今天是我的死期…我只會死在戰場上！', 28153),
(155778, 'zhTW', '我寧願一死了之，也不願落入摩詹波手中！', '我寧願一死了之，也不願落入摩詹波手中！', 28153),
(155777, 'zhTW', '我拒絕向摩詹波和他的幫派低頭！', '我拒絕向摩詹波和他的幫派低頭！', 28153),
(155776, 'zhTW', '我會戰到最後一刻！', '我會戰到最後一刻！', 28153),
(155775, 'zhTW', '摩詹波別指望我們束手就擒！', '摩詹波別指望我們束手就擒！', 28153),
(155774, 'zhTW', '戰鬥即將到來，帶著這把劍，保持警戒。', '戰鬥即將到來，帶著這把劍，保持警戒。', 28153),
(155773, 'zhTW', '這裡是我們的家，我們不能毫無反抗就輕易讓出。', '這裡是我們的家，我們不能毫無反抗就輕易讓出。', 28153),
(155772, 'zhTW', '', '做得好！這樣海軍要擔心的事又少了一樁。', 28153),
(155771, 'zhTW', '', '殺得真爽！看你戰鬥感覺可以學到很多東西。', 28153),
(155770, 'zhTW', '', '多虧有你，往庫爾提拉斯的路上更安全了。', 28153),
(155769, 'zhTW', '', '部隊之前在這一帶遇到很棘手的野獸。解決他們！', 28153),
(155768, 'zhTW', '', '這個地方有凶惡野獸出沒。為了庫爾提拉斯的安全，我們不能假裝沒看到！', 28153),
(155767, 'zhTW', '', '不能讓這種邪惡生物繼續危害無辜的平民老百姓。快解決牠！', 28153),
(155766, 'zhTW', '你不是應該在別的地方嗎？', '你不是應該在別的地方嗎？', 28153),
(155765, 'zhTW', '嘿，這一個看我的眼神好奇怪！', '嘿，這一個看我的眼神好奇怪！', 28153),
(155764, 'zhTW', '你離家有一段距離啊，朋友！', '你離家有一段距離啊，朋友！', 28153),
(155763, 'zhTW', '晚上出現紅色天空，水手歡欣鼓舞。白天出現紅色天空，水手憂心忡忡！', '', 28153),
(155762, 'zhTW', '我要傳送到古翰。', '我要傳送到古翰。', 28153),
(155761, 'zhTW', '我要傳送到謎思拉克斯。', '我要傳送到謎思拉克斯。', 28153),
(155760, 'zhTW', '我要傳送到祖爾。', '我要傳送到祖爾。', 28153),
(155759, 'zhTW', '我想傳送到血元素。', '我想傳送到血元素。', 28153),
(155758, 'zhTW', '我要傳送到札克沃茲。', '我要傳送到札克沃茲。', 28153),
(155757, 'zhTW', '我要傳送到噬臭者。', '我要傳送到噬臭者。', 28153),
(155756, 'zhTW', '我要傳送到母親大人。', '我要傳送到母親大人。', 28153),
(155755, 'zhTW', '你好，謝謝你協助測試奧迪爾！\n\n我可以把你直接傳送到任何測試中的頭目身邊。', '你好，謝謝你協助測試奧迪爾！\n\n我可以把你直接傳送到任何測試中的頭目身邊。', 28153),
(155754, 'zhTW', '', '我的貓不見了。', 28153),
(155753, 'zhTW', '風暴要是躲不過，就想辦法穿過。風暴要是穿不過，那就想辦法躲過！', '', 28153),
(155752, 'zhTW', '記住，濕的一側朝下！', '', 28153),
(155750, 'zhTW', '要送你去見伯昂撒姆第嗎？', '', 28153),
(155749, 'zhTW', '你一直住在陸地上真是太可憐了。', '', 28153),
(155748, 'zhTW', '當你眺望諸王海灣，看到那受到祝福的藍色火焰，要記住．今天是你扭轉了局勢！這場勝得漂亮，$n。贊達拉艦隊永遠不滅！', '', 28153),
(155747, 'zhTW', '我責罰你時是不會猶豫的。', '', 28153),
(155746, 'zhTW', '願你一帆風順、找到靈魂的意義！', '', 28153),
(155745, 'zhTW', '我們會再見面的！', '', 28153),
(155744, 'zhTW', '保重！大海在呼喚我！', '', 28153),
(155743, 'zhTW', '如果你以為航行會一帆風順，那顯然你啥都沒學到。', '', 28153),
(155742, 'zhTW', '祝你一路風平浪靜！', '', 28153),
(155741, 'zhTW', '願浪潮賜我們再次相遇的機會！', '', 28153),
(155740, 'zhTW', '隨風而去吧！尋找新的領域！', '', 28153),
(155739, 'zhTW', '你嘗到海風的鹹味了嗎？這就是家的味道。', '', 28153),
(155738, 'zhTW', 'Taz\'okun！旅行者，歡迎！', '', 28153),
(155737, 'zhTW', '任務完成了…但是非要弄得到處血跡斑斑嗎？下次拜託手腳俐落一點。', '', 28153),
(155736, 'zhTW', '哎呀！是你！', '', 28153),
(155735, 'zhTW', '大酋長下令，要你為了部落，攻下這個地方。無論你用什麼辦法…只要能贏就好。', '', 28153),
(155734, 'zhTW', '在海上的每一天都是好日子！', '', 28153),
(155733, 'zhTW', '要不要一起去大冒險？', '', 28153),
(155732, 'zhTW', '我要前往奧迪爾(團隊副本)。', '我要前往奧迪爾(團隊副本)。', 28153),
(155731, 'zhTW', '做得好！這些鳥兒總算有安全的地方可以棲息，現在我們要對付的敵人也變少了。', '', 28153),
(155730, 'zhTW', '我會殷切等待你歸來！', '', 28153),
(155729, 'zhTW', '請盡快回來！', '', 28153),
(155728, 'zhTW', '瞄準！', '瞄準！', 28153),
(155727, 'zhTW', '我知道，又是這個…', '', 28153),
(155726, 'zhTW', '我想你弄壞了某個東西…', '', 28153),
(155725, 'zhTW', '有什麼我能幫忙的嗎？', '', 28153),
(155724, 'zhTW', '需要我幫忙嗎？', '', 28153),
(155723, 'zhTW', '躲到掩護後方！', '躲到掩護後方！', 28153),
(155722, 'zhTW', '你必須慶幸我很欣賞你，這次我會修好它…就一次…', '', 28153),
(155721, 'zhTW', '真的嗎？把所有重量壓在一個小東西上來破壞它？誰能想到…', '', 28153),
(155720, 'zhTW', '你不可能比我的錘子還聰明。', '', 28153),
(155719, 'zhTW', '很確定這就是我上次修好的東西。', '', 28153),
(155718, 'zhTW', '我希望這些白痴別再破壞東西了。', '', 28153),
(155717, 'zhTW', '我想去威奎斯特莊園(地城)。', '我想去威奎斯特莊園(地城)。', 28153),
(155716, 'zhTW', '我想去托達戈爾(地城)。', '我想去托達戈爾(地城)。', 28153),
(155715, 'zhTW', '我想去波拉勒斯圍城戰(地城)。', '我想去波拉勒斯圍城戰(地城)。', 28153),
(155714, 'zhTW', '我想去風暴聖壇(地城)。', '我想去風暴聖壇(地城)。', 28153),
(155713, 'zhTW', '我想去自由港(地城)。', '我想去自由港(地城)。', 28153),
(155712, 'zhTW', '普麥瑞亞的羽毛啊！你嚇到我了！', '', 28153),
(155711, 'zhTW', '被女巫控制的手下把我們的鳥兒抓走了！快把這些獵鷹救回來，消滅女巫的走狗！', '', 28153),
(155710, 'zhTW', '想找個零件、小機械，或小玩意兒嗎？', '', 28153),
(155709, 'zhTW', '我想去幽腐深窟(地城)。', '我想去幽腐深窟(地城)。', 28153),
(155708, 'zhTW', '我想去晶喜鎮(地城)。', '我想去晶喜鎮(地城)。', 28153),
(155707, 'zhTW', '我想去瑟沙利斯神廟(地城)。', '我想去瑟沙利斯神廟(地城)。', 28153),
(155706, 'zhTW', '我想去諸王之眠(地城)。', '我想去諸王之眠(地城)。', 28153),
(155705, 'zhTW', '我們隨時能面對任何挑戰！', '', 28153),
(155704, 'zhTW', '我們這些有羽毛的朋友不用再擔心女巫的魔法了。', '', 28153),
(155703, 'zhTW', '那些女巫用符咒控制我們剛剛孵化的雛鳥！除掉這些符咒，消滅被妖術控制的馴鷹者，別讓魔法繼續蔓延！', '', 28153),
(155702, 'zhTW', '', '快滾。', 28153),
(155701, 'zhTW', '', '警告你，我有武器，而且我真的會用。', 28153),
(155700, 'zhTW', '', '我受夠你那個蠢樣子了。', 28153),
(155699, 'zhTW', '', '翼艇可以解決任何海怪。', 28153),
(155698, 'zhTW', '', '毛毛，你這隻小壞貓…馬上過來這裡！', 28153),
(155697, 'zhTW', '', '來這裡，小貓咪！', 28153),
(155696, 'zhTW', '我想去阿塔達薩(地城)。', '我想去阿塔達薩(地城)。', 28153),
(155695, 'zhTW', '', '準備好要幹點正經事再跟我說。', 28153),
(155694, 'zhTW', '', '我還要去殺海怪。', 28153),
(155693, 'zhTW', '', '什麼事？', 28153),
(155692, 'zhTW', '任務完成了？好，我會把這次捷報給大酋長。', '', 28153),
(155691, 'zhTW', '你好，謝謝你協助《決戰艾澤拉斯》Beta版！\n\n我可以把你直接傳送到目前開放測試的許多團隊或地城副本。這只是傳送門，不是組隊服務，因此希望你先組好隊伍，以便迎接接下來的挑戰。如果未組隊，你或許可以試用全新的隊伍搜尋器功能，尋找一些隊友。\n\n傳送之前，務必選擇想要測試的難度，因為你可能無法輕易離開副本，變更難度設定！', '你好，謝謝你協助《決戰艾澤拉斯》Beta版！\n\n我可以把你直接傳送到目前開放測試的許多團隊或地城副本。這只是傳送門，不是組隊服務，因此希望你先組好隊伍，以便迎接接下來的挑戰。如果未組隊，你或許可以試用全新的隊伍搜尋器功能，尋找一些隊友。\n\n傳送之前，務必選擇想要測試的難度，因為你可能無法輕易離開副本，變更難度設定！', 28153),
(155690, 'zhTW', '$n(部落)在你的地圖上被標示為|c00FFFF00|Hspell:272296|h[刺客]|h|r！殺了他們就能拿到賞金。', '$n(部落)在你的地圖上被標示為|c00FFFF00|Hspell:272296|h[刺客]|h|r！殺了目標就能拿到賞金。', 28153),
(155689, 'zhTW', '$n(聯盟)在你的地圖上被標示為|c00FFFF00|Hspell:272295|h[刺客]|h|r！殺了他們就能拿到賞金。', '$n(聯盟)在你的地圖上被標示為|c00FFFF00|Hspell:272295|h[刺客]|h|r！殺了就能拿到賞金。', 28153),
(155688, 'zhTW', '務必驅離這個區域的敵軍。這個任務對你來說應該不難吧？', '', 28153),
(155687, 'zhTW', '', '我還沒見過殺不了的海怪。', 28153),
(155686, 'zhTW', '拖得有點久…但結果還算可以接受。我們會繼續照計畫執行。', '', 28153),
(155685, 'zhTW', '大酋長要我們取得這個地區的資源。該是我們的就通通帶走。', '', 28153),
(155684, 'zhTW', '你還是不能提到我姊姊。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155683, 'zhTW', '', '我們一定會好好利用這些資源的！做得好。', 28153),
(155682, 'zhTW', '', '你作戰的樣子很像你姊姊。', 28153),
(155681, 'zhTW', '', '這個地方有很多燼火會可以利用的資源。鞏固這個地區，奪下資源！', 28153),
(155680, 'zhTW', '母親，遵命…', '', 28153),
(155679, 'zhTW', '', '小貓，你在哪裡？', 28153),
(155678, 'zhTW', '', '來吧，亞瑟。', 28153),
(155677, 'zhTW', '', '來吧，元帥，乖乖聽話，帶露西爾到我那裡去。不過，你得先把這些害蟲解決掉…', 28153),
(155676, 'zhTW', '', '你有看到我的貓嗎？', 28153),
(155675, 'zhTW', '', '我說元帥，你不應該這樣跟我說話的。就讓我來教你什麼叫禮貌吧。', 28153),
(155674, 'zhTW', '', '你跟得上嗎？', 28153),
(155673, 'zhTW', '離她遠一點，你這冷酷的女巫！', '', 28153),
(155672, 'zhTW', '', '你要懂得感恩，孩子！你父親不但活得好好的，而且很快會在庫爾提拉斯稱王了！加入我們吧，孩子…', 28153),
(155671, 'zhTW', '', '你…你對他做了什麼？！', 28153),
(155670, 'zhTW', '', '你能來跟我們團聚真是太好了。你父親很想念你。', 28153),
(155669, 'zhTW', '', '母親？是…是你嗎？', 28153),
(155668, 'zhTW', '', '到此為止。', 28153),
(155667, 'zhTW', '我聽說跟艾胥凡來的那些貨櫃有關。', '我聽說跟艾胥凡來的那些貨櫃有關。', 28153),
(155666, 'zhTW', '史東隊長怪怪的，比平時緊張。', '史東隊長怪怪的，比平時緊張。', 28153),
(155665, 'zhTW', '幸好我們今天有外務，不用待在這裡。', '幸好我們今天有外務，不用待在這裡。', 28153),
(155664, 'zhTW', '你說什麼？這是炸彈？！我還以為是酪梨。', '', 28153),
(155663, 'zhTW', '', '約翰，小心點。那種火藥一不小心就能把你整隻手炸爛。', 28153),
(155662, 'zhTW', '把跳板升起來！準備開船了！大家表現得很好。', '', 28153),
(155661, 'zhTW', '看來他們也在找艾澤萊晶岩。我們趕快偷偷溜走，別讓他們注意到。我們還得回報這件事。', '', 28153),
(155660, 'zhTW', '看來整座島都被清空，所有艾澤萊晶岩都在這裡了。走吧，我看到庫爾提拉斯的船出現了。', '', 28153),
(155659, 'zhTW', '看來他們也在收集艾澤萊晶岩。正好把東西都集中在一起了。哈！去從他們手上搶過來吧。', '', 28153),
(155658, 'zhTW', '猴人！哈！這種地方每次都有奇怪的傢伙出現。', '', 28153),
(155657, 'zhTW', '我發現有一大堆艾澤萊晶岩就在你們那附近。你們可以趕快過去看看情況。', '', 28153),
(155656, 'zhTW', '這樣就對了。我們很快就可以把船裝滿了。', '', 28153),
(155655, 'zhTW', '真是隻大怪物，上面還沾滿了艾澤萊晶岩。把牠殺了，我們把這些艾澤萊晶岩拿走。', '', 28153),
(155654, 'zhTW', '看起來在你們的位置附近還有艾澤萊晶岩。你們或許會想去探探究竟。', '', 28153),
(155653, 'zhTW', '做得好，真是大豐收。太好了。', '', 28153),
(155652, 'zhTW', '啊，太好了，這好大一塊。趕快去挖起來。我們馬上就會把艾澤萊晶岩放到船上去。', '', 28153),
(155651, 'zhTW', '儀器顯示這附近有艾澤萊晶岩。你們趕快過去仔細看看。', '', 28153),
(155650, 'zhTW', '把梯板放下來。就是這個地方了。', '', 28153),
(155649, 'zhTW', '我們不知道這裡還有什麼東西。你最好小心，注意周遭。', '', 28153),
(155648, 'zhTW', '就快到了。這裡就是我們斥候說有很多艾澤萊晶岩的島嶼。', '', 28153),
(155647, 'zhTW', '遵命，隊長。', '遵命，隊長。', 28153),
(155646, 'zhTW', '', '那為什麼還不趕快裝櫃上船？那些爆炸品都是風險。', 28153),
(155645, 'zhTW', '是、是的，史東隊長。', '是、是的，史東隊長。', 28153),
(155644, 'zhTW', '', '那是艾胥凡鑄造廠運來的火藥嗎？', 28153),
(155643, 'zhTW', '血與雷，這是哪種巫術？我們的船艦都被摧毀，部隊也被逼進海裡！', '', 28153),
(155642, 'zhTW', '我跟你說，在自由港賣耳塞一定能大賺一筆。', '', 28153),
(155641, 'zhTW', '你…你剛剛聽到了嗎？等等！又來了！快點殺掉！', '', 28153),
(155640, 'zhTW', '很好！這樣自由港就安全一點了。呃，我是不是太樂觀了？', '', 28153),
(155639, 'zhTW', '哈！知道厲害了吧，死鸚鵡！', '', 28153),
(155638, 'zhTW', '讚啦！我欠他的錢不用還了。', '', 28153),
(155637, 'zhTW', '什麼東西聞起來像烈酒，還戴了頂紅帽子？答案是海盜！而且不是友善的那種。', '', 28153),
(155636, 'zhTW', '我朋友看到附近有通緝犯。我們去賺懸賞金吧！', '', 28153),
(155635, 'zhTW', '這附近有非常危險的罪犯。我想該你出手了。', '', 28153),
(155634, 'zhTW', '嘿，是風險投資公司的朋友，他們來這裡幫我們處理艾澤萊晶岩的事，真是一群好人。你會喜歡他們的，去交個朋友。', '', 28153),
(155633, 'zhTW', '風險投資公司在島嶼周圍的好幾個地點開始行動了。你們最好趕快去阻止他們。', '', 28153),
(155632, 'zhTW', '風險投資公司也來湊一腳，只有哥布林才會想到用艾澤萊晶岩礦源賺錢。', '', 28153),
(155631, 'zhTW', '我們發現風險投資公司的人也到島上來了。看樣子他們是打算來接管島上的寶物。', '', 28153),
(155630, 'zhTW', '這是維酷人長艇，而且很多艘。看來為了奪取艾澤萊晶岩，整族都出航了。', '', 28153),
(155629, 'zhTW', '維酷人長艇剛剛載來一大群人。他們一定是來搶我們的。別讓他們真的得逞，好嗎？', '', 28153),
(155628, 'zhTW', '維酷人的艦隊來了。我用這副望遠鏡看到好多凶神惡煞的戰士，他們正在島上紮營。', '', 28153),
(155627, 'zhTW', '維酷人的船快到了，大概又是來掠奪的。維酷人總是到處掠奪，這也算是他們的文化。', '', 28153),
(155626, 'zhTW', '有些不太友善的島嶼食人妖決定要來這裡砸場子。他們要在島嶼周圍紮營了。', '', 28153),
(155625, 'zhTW', '海平面上出現島嶼食人妖獨木舟，他們隨時都會抵達。艾澤萊晶岩就像是一個信標，不斷把我討厭的東西吸引過來。', '', 28153),
(155624, 'zhTW', '有些島嶼食人妖出現了，應該是來搶艾澤萊晶岩的。要是你能想辦法讓他們離船遠一點，我們會很感激的。', '', 28153),
(155623, 'zhTW', '嘿，快看，一整支食人妖艦隊抵達了，因為我們需要更多食人妖，讓食人妖全面進攻？非常棒的點子。', '', 28153),
(155622, 'zhTW', '有條巨龍不知道從哪裡飛過來，大概是我今天很需要看到龍吧。這禮拜還真是精彩啊，對吧？不管了，龍就龍吧。', '', 28153),
(155621, 'zhTW', '嗨，朋友們。有條巨龍決定要來一起玩，牠好像對艾澤萊晶岩很有興趣。我只是覺得應該說一聲。', '', 28153),
(155620, 'zhTW', '龍，有龍耶！而且他們緊盯著船。我想它們看到我了，能幫個忙嗎？', '', 28153),
(155619, 'zhTW', '好像有一整群飛龍剛剛降落了，我非常清楚它們想要什麼。祝你好運！', '', 28153),
(155618, 'zhTW', '現在天空又怎麼了？怎麼一片黑？為什麼現在島上到處都是死屍？喔，天啊。', '', 28153),
(155617, 'zhTW', '呃，這真是我這輩子聞過最臭的味道了。是誰幹的？噢，好吧，是亡者。大家聽好，亡者也來這裡搶艾澤萊晶岩了！懂了嗎？', '', 28153),
(155616, 'zhTW', '然後更精彩的是，就連不死生物都在這座島上蔓延開了。我根本就不想知道。', '', 28153),
(155615, 'zhTW', '不死族？在這裡？我不知道現在到底怎麼了，不過一定不是好事。', '', 28153),
(155614, 'zhTW', '注意了，我看到托維爾的船出現在海面上，而且他們看起來不像是來好好談生意的。我們動作快一點，好嗎？', '', 28153),
(155613, 'zhTW', '哇，托維爾人嗎？已經很久很久沒看過這種船艦了。好吧，他們已經到了，而且他們恨我們。', '', 28153),
(155612, 'zhTW', '托維爾的船剛剛靠岸了。怎麼大家都知道艾澤萊晶岩在哪？我討厭這種事情，你們能去處理一下嗎？', '', 28153),
(155611, 'zhTW', '那是什麼？半人馬？牛頭怪？嘿，我想剛剛出現一些…呃…托維爾人。', '', 28153),
(155610, 'zhTW', '海面上出現海盜船。可能也是來這個地方搶劫的。海盜一天到晚都在搶劫。', '', 28153),
(155609, 'zhTW', '有群海盜上岸了。只要島上有金銀財寶，海盜總是隨後就到，這是一定的。', '', 28153),
(155608, 'zhTW', '現在第三艘船出現了，當然是因為我的每個任務都很有趣。順便一提，溫馨提醒你這次來的是海盜。', '', 28153),
(155607, 'zhTW', '哇！砲火跟我們擦身而過。現在有一大群海盜上岸了。', '', 28153),
(155606, 'zhTW', '薩烏洛克出現了，大概是聞到艾澤萊晶岩的味道。等等，他們有鼻子嗎？我可不想問他們。', '', 28153),
(155605, 'zhTW', '一整支薩烏洛克戰隊剛從海中湧出，讓人毫無心理準備。', '', 28153),
(155604, 'zhTW', '海浪裡有什麼東西？噢，天啊，一大群薩烏洛克剛從海裡上岸。全都靠你了。', '', 28153),
(155603, 'zhTW', '幾隻一臉憤怒的蜥蜴正盯著我們的船和船上的艾澤萊晶岩。能不能別讓它們搶走？能嗎？', '', 28153),
(155602, 'zhTW', '又有東西來了，以前沒看過這些傢伙。他們應該不是來這裡幫我們的忙。', '', 28153),
(155601, 'zhTW', '看到一堆奇怪的東西到島上來了。看來也是來找艾澤萊晶岩的，可是他們好像…有點不太對勁。', '', 28153),
(155600, 'zhTW', '啊！那些傢伙從哪裡冒出來的？它們好像是憑空出現。嘿，英雄？有客人來了。', '', 28153),
(155599, 'zhTW', '這些傢伙到底是什麼來頭？我看不清楚他們的臉。是朋友嗎？搞不好是敵人。', '', 28153),
(155598, 'zhTW', '看來我們古神和它的手下注意到我們了。呃，你有辦法應付這種情況嗎？', '', 28153),
(155597, 'zhTW', '有一些觸鬚臉怪物登島了，沒錯，我該閃人了，多保重。', '', 28153),
(155596, 'zhTW', '有人聽到低語的聲音嗎？如果不是我發瘋，那就是無面者到島上來了。噢，他們也是來找艾澤萊晶岩的。', '', 28153),
(155595, 'zhTW', '看看這團漆黑的暗影。真是太棒了，這絕對就是古神。小心那些觸手。', '', 28153),
(155594, 'zhTW', '有一大堆魔古都想搶艾澤萊晶岩，很可能想過來這裡。', '', 28153),
(155593, 'zhTW', '我看到魔古也到這座島來了。小心一點，我們跟他們可算不上朋友。', '', 28153),
(155592, 'zhTW', '呃，有魔古跑到這座島上了。不知道他們想做什麼。我就讓你去查查看吧。', '', 28153),
(155591, 'zhTW', '魔古的龍載了進攻部隊過來。再一次被艾澤萊晶岩引出來，每次都這樣。', '', 28153),
(155590, 'zhTW', '好吧，納迦已經來了，這正是我們要的，小心不要被殺了，好嗎？', '', 28153),
(155589, 'zhTW', '在望遠鏡中發現納迦的蹤跡，它們很快就會來到這裡。幫我們好好歡迎它們，好嗎？', '', 28153),
(155588, 'zhTW', '有些納迦也到這座島上來找艾澤萊晶岩了。一定是我們的好朋友艾薩拉派來的。她到底在想什麼啊？', '', 28153),
(155587, 'zhTW', '就連納迦都從深海裡游出來，看來是在打我們這些東西的主意。我要先去把砲彈準備好了。', '', 28153),
(155586, 'zhTW', '迷霧持續翻騰。不，等等，我看到破破爛爛的船艦，原來是科瓦迪爾人，太好了。', '', 28153),
(155585, 'zhTW', '呃，我們看到科瓦迪爾的船，他們馬上就要過來了。一定是來搶艾澤萊晶岩的。我到底為什麼要接這種工作啊？', '', 28153),
(155584, 'zhTW', '這裡的霧真是越來越濃了。看來一定是科瓦迪爾。睜大眼睛…我是說，要是你看得到東西的話。', '', 28153),
(155583, 'zhTW', '哇，什麼東西聞起來像海草？喔，嘿，大家，有幾個科瓦迪爾人過來了。', '', 28153),
(155582, 'zhTW', '看來我們這下子要深陷蟲蟲危機了…一大群螳螂人出現了。我到甲板下面去，你們玩得開心一點啊！', '', 28153),
(155581, 'zhTW', '我聽過這些傢伙，好像是叫螳螂人。呃，你可以幫我們解決它們嗎？我有點過敏。', '', 28153),
(155580, 'zhTW', '那是蜂群嗎？不不，那些東西很大，對了，那是螳螂人，而且他們就快過來了。', '', 28153),
(155579, 'zhTW', '你一定會很興奮的。螳螂人也出現了。當然囉，他們是來找艾澤萊晶岩的，這還用說。', '', 28153),
(155578, 'zhTW', '哇嗚！什麼東西從頭上飛過去了？你看到了嗎？島上有條巨龍在那裡。你仔細看。', '', 28153),
(155577, 'zhTW', '嘿，所以一隻巨龍剛剛現身，還帶著一整群小龍，他們看到我們拿走艾澤萊晶岩都覺得很不爽。', '', 28153),
(155576, 'zhTW', '這真是太棒了，一隻黑龍，黑龍耶！還有他一半的手下！就在這裡！簡直太棒了。', '', 28153),
(155575, 'zhTW', '嗯，有條巨龍剛在島上著陸。你應該知道我們的船很容易起火，對吧？離牠遠一點，越遠越好。', '', 28153),
(155574, 'zhTW', '托維爾搶艾澤萊晶岩也是來硬的。你們最好小心一點。', '', 28153),
(155573, 'zhTW', '喂，托維爾也在這裡出現了。跟我們一樣是來找艾澤萊晶岩的，哈哈。', '', 28153),
(155572, 'zhTW', '從沒想到我會看到另一艘托維爾船艦。有些人上岸了，看起來怒氣沖沖。', '', 28153),
(155571, 'zhTW', '有船靠岸了，過去只見過他們一次，自稱托維爾人。他們似乎不是很友善。', '', 28153),
(155570, 'zhTW', '', '想辦法把聖物完好無缺地帶回來，$n。艾司川迪斯有點…太狂熱了。', 28153),
(155569, 'zhTW', '', '讓這些海盜再也無法出海，對我們有很大的好處。勇士，謝謝你。', 28153),
(155568, 'zhTW', '你想被丟到碼頭底下嗎？', '', 28153),
(155567, 'zhTW', '我現在就跟潮水一樣憤怒。', '', 28153),
(155566, 'zhTW', '你不知道自己惹毛了什麼人。', '', 28153),
(155565, 'zhTW', '', '我們必須知道這些海盜在計劃什麼。攔截他們的命令文件…用什麼手段都好。', 28153),
(155564, 'zhTW', '潮汐往復，直到永遠。', '', 28153),
(155561, 'zhTW', '願你的航行一路順利。', '', 28153),
(155560, 'zhTW', '千萬別離開海洋。', '', 28153),
(155558, 'zhTW', '我討厭鳥，又吵鬧又噁心。我還有其他重要的事情要處理。', '', 28153),
(155557, 'zhTW', '我們在自由港的某個聯絡人需要幫忙…安撫他的鳥群。你一定可以勝任的。', '', 28153),
(155556, 'zhTW', '我侍奉浪潮。', '', 28153),
(155554, 'zhTW', '你也能感受到…石頭的力量…嗎？', '', 28153),
(155553, 'zhTW', '這顆石頭會讓我們變成有錢人！你不能拿走它！', '', 28153),
(155552, 'zhTW', '願潮水指引你。', '', 28153),
(155551, 'zhTW', '只要聆聽潮汐的聲音，就可以更了解這個世界。', '', 28153),
(155550, 'zhTW', '我心有疑慮…', '', 28153),
(155549, 'zhTW', '你可別逼我叫守衛。', '', 28153),
(155548, 'zhTW', '你要是有話要說，就趕快說吧！', '', 28153),
(155547, 'zhTW', '求求你…饒了我的貓。', '', 28153),
(155546, 'zhTW', '拜託，我真的很忙。', '', 28153),
(155545, 'zhTW', '記得回來多說說你冒險的故事！', '', 28153),
(155543, 'zhTW', '又來了幾個奈得里的手下！我會把他們像其他人一樣埋進泥巴裡！', '', 28153),
(155540, 'zhTW', '惡霸！', '', 28153),
(155539, 'zhTW', '祝你開心愉快！', '', 28153),
(155538, 'zhTW', '把這裡當自己家吧，我的莊園就是你的莊園。', '', 28153),
(155536, 'zhTW', '盡量吃，盡量喝，盡量玩！', '', 28153),
(155535, 'zhTW', '歡迎蒞臨諾爾威頓馬術暨狩獵慶典！', '', 28153),
(155534, 'zhTW', '', '以及五千億諾甘位元組，用以儲存可愛喵喵的圖像。', 28153),
(155533, 'zhTW', '朋友，來得正好。穴居怪打過來了！', '', 28153),
(155532, 'zhTW', '', '他們招惹了不該去碰的力量。我們必須阻止它從海裡覺醒！', 28153),
(155531, 'zhTW', '部落的戰士們！讓那些聯盟知道我們戰鬥的意義！往要塞前進！', '', 28153),
(155530, 'zhTW', '', '集合！前進！阿拉希會是我們的！', 28153),
(155529, 'zhTW', '', '那些人類正在從深淵召喚某種可怕的東西。快阻止他們！', 28153),
(155528, 'zhTW', '托爾托？', '托爾托？', 28153),
(155527, 'zhTW', '', '有著手臂和腿的殼就在那裡！\n\n別被他騙了。他很聰明，而且好管閒事！老是到處打探，收集古老的聖物、卷軸和廢物。\n\n別讓他先找到寶藏。', 28153),
(155526, 'zhTW', '我要跟我叔叔講！', '', 28153),
(155525, 'zhTW', '請你冷靜點、慢慢退開。', '', 28153),
(155524, 'zhTW', '不好意思，可以讓我靜靜嗎？', '', 28153),
(155522, 'zhTW', '我想應該就這樣了。', '', 28153),
(155521, 'zhTW', '沒有人告訴過我…領導人民這麼地困難。', '', 28153),
(155520, 'zhTW', '我會盡力而為。', '', 28153),
(155516, 'zhTW', '我會守護釣點！', '', 28153),
(155515, 'zhTW', '我必須證明自己的能力。', '', 28153),
(155514, 'zhTW', '浪潮歡迎你。', '', 28153),
(155513, 'zhTW', '好吧。', '', 28153),
(155512, 'zhTW', '要是沒其他事的話，你就走吧。', '', 28153),
(155511, 'zhTW', '我先回崗位去。', '', 28153),
(155510, 'zhTW', '我得盡忠職守。', '', 28153),
(155509, 'zhTW', '哼。', '', 28153),
(155508, 'zhTW', '太好了！有這些東西就可以調配一些…特別的藥水了。', '', 28153),
(155507, 'zhTW', '這個地方有豐富的自然資源，還有奇特的鍊金材料可以好好運用！麻煩你找一些有用的東西回來給我。', '', 28153),
(155506, 'zhTW', '', '農夫們都很感謝你幫忙擊退那些野獸。', 28153),
(155505, 'zhTW', '', '兇猛的野獸入侵了岸邊的農地。幫那邊的農夫處理一下這個問題。', 28153),
(155504, 'zhTW', '再碰我們一次會造成嚴重、可能致命的反應。', '', 28153),
(155503, 'zhTW', '你再這樣下去，我就讓你知道我們揍人可不會蘑菇！', '', 28153),
(155502, 'zhTW', '敢亂給我們扣菇帽子，就要你好看。', '', 28153),
(155501, 'zhTW', '沒事了嗎？', '', 28153),
(155500, 'zhTW', '生於榮耀，智識清曉。', '', 28153),
(155499, 'zhTW', '願孢子與你同在。', '', 28153),
(155498, 'zhTW', '幸會。', '', 28153),
(155497, 'zhTW', '你好呀！', '', 28153),
(155496, 'zhTW', '世上永遠都需要一個…菇妖王…。', '', 28153),
(155495, 'zhTW', '感受菇之哀傷的飢渴！', '', 28153),
(155494, 'zhTW', '啊！', '', 28153),
(155493, 'zhTW', '孢子不會放過我們…', '', 28153),
(155492, 'zhTW', '我們…再也…聽不見了…', '', 28153),
(155491, 'zhTW', '殺死你！殺！殺！', '', 28153),
(155490, 'zhTW', '加入我們！', '', 28153),
(155489, 'zhTW', '去死！去死！去死！', '', 28153),
(155488, 'zhTW', '', '哈！那種獵物連翼艇隊看到都會眼紅。', 28153),
(155487, 'zhTW', '你看那個該死的怪物正在吃新兵的內臟。快殺了牠吧…我真的不想一天到晚老是在訓練剛招募的新兵了。', '', 28153),
(155486, 'zhTW', '', '庫爾提拉斯守衛報告說這一區有巨大野獸。無論誰想出海都很危險。', 28153),
(155485, 'zhTW', '海盜之間流傳說海灣住了個骷髏惡魔。這個解釋合理多了。', '', 28153),
(155484, 'zhTW', '有個龐大生物上岸了。不知道是哪裡來的，但看起來很危險。', '', 28153),
(155483, 'zhTW', '做得好！托達戈爾有些囚犯真的罪有應得。例如這位先生就是活該。', '', 28153),
(155482, 'zhTW', '', '真是個瘋子。你今天救了很多人的生命。', 28153),
(155481, 'zhTW', '我要走了…', '我要走了…', 28153),
(155480, 'zhTW', '我可以安心了。', '我可以安心了。', 28153),
(155479, 'zhTW', '謝謝你。', '謝謝你。', 28153),
(155478, 'zhTW', '我想好好休息…', '我想好好休息…', 28153),
(155477, 'zhTW', '我好迷惘…', '我好迷惘…', 28153),
(155476, 'zhTW', '我本來很害怕…現在不怕了…', '我本來很害怕…現在不怕了…', 28153),
(155475, 'zhTW', '你好嗎？', '', 28153),
(155474, 'zhTW', '這光…好溫暖…', '這光…好溫暖…', 28153),
(155473, 'zhTW', '', '謝謝你的幫忙。我們不會忘記的。', 28153),
(155471, 'zhTW', '走這邊。', '走這邊。', 28153),
(155470, 'zhTW', '重新裝填！！', '重新裝填！！', 28153),
(155469, 'zhTW', '', '你這個異端！休想插手！', 28153),
(155468, 'zhTW', '開火！！！', '開火！！！', 28153),
(155467, 'zhTW', '', '贊達拉是黃金打造的。一定有方法可以把整座城市都偷走？', 28153),
(155466, 'zhTW', '', '有犯人從人類的監獄跑來部落港口附近。他對大家都很危險。', 28153),
(155465, 'zhTW', '我好像認得那傢伙！等等…我真的認得那傢伙。這通常不是什麼好事。', '', 28153),
(155464, 'zhTW', '深淵…應賜予我們…更多！', '', 28153),
(155463, 'zhTW', '這股力量是來自深淵的禮物！', '', 28153),
(155462, 'zhTW', '我原本以為，那些庫爾提拉斯人或許還有點骨氣…沒想到他們就跟懦弱的聯盟沒什麼兩樣。', '', 28153),
(155461, 'zhTW', '有個黑暗遊俠誘敵成功，引出總帥的參謀了。陷阱已經設好…就讓你下手吧。', '', 28153),
(155460, 'zhTW', '', '死者的靈魂終於又能安息了。', 28153),
(155459, 'zhTW', '好吧…可是你會回來，對不對？', '', 28153),
(155458, 'zhTW', '好啦，我們回頭見！', '', 28153),
(155457, 'zhTW', '這樣部落就知道惹上我們海軍是什麼下場！做得漂亮。', '', 28153),
(155456, 'zhTW', '有一名普勞德摩爾軍官快逮到黑暗遊俠了！過去幫他一把！', '', 28153),
(155455, 'zhTW', '我為爸爸感到驕傲！', '', 28153),
(155454, 'zhTW', '今天一定會很棒！', '', 28153),
(155453, 'zhTW', '我爸說有時候大人也會害怕。你會怕嗎？', '', 28153),
(155452, 'zhTW', '哇，快看看漂亮的小馬！', '', 28153),
(155451, 'zhTW', '開始學習永遠不嫌晚！', '', 28153),
(155450, 'zhTW', '先再見囉！', '', 28153),
(155449, 'zhTW', '', '這些靈魂受到女巫手下的影響，陷入無比的狂亂。消除這股腐化的力量，讓這些靈魂重新回歸平靜。', 28153),
(155448, 'zhTW', '很好…至少在我死前…<嗝！>…我又嚐到贊庫爾百年一次！', '', 28153),
(155447, 'zhTW', '我聽說摩詹波為了那場戰鬥招兵買馬，通戈的人也倒向他了…', '', 28153),
(155446, 'zhTW', '我發現摩詹波的人正在偵察競技場…', '', 28153),
(155445, 'zhTW', '你履行了你的承諾，我也會依約行事…', '', 28153),
(155444, 'zhTW', '啊！上次品嚐贊庫爾百年已經是好幾年前的事了…<嗝！>', '', 28153),
(155443, 'zhTW', '蘭姆酒給你，告訴我你聽到的事。', '蘭姆酒給你，告訴我你聽到的事。', 28153),
(155442, 'zhTW', '好吧，再見！我會…留在這裡。', '', 28153),
(155441, 'zhTW', '我一輩子都在尋找知識。你呢？', '', 28153),
(155440, 'zhTW', '我們經歷了漫長旅途，但現在終於到了！', '', 28153),
(155439, 'zhTW', '狩獵愉快。', '', 28153),
(155438, 'zhTW', '為了部落！', '', 28153),
(155437, 'zhTW', '要我去追蹤什麼嗎？', '', 28153),
(155436, 'zhTW', '尖牙與利齒。', '', 28153),
(155435, 'zhTW', '夠了，你死定了！', '', 28153),
(155434, 'zhTW', '別鬧了，住手！', '', 28153),
(155433, 'zhTW', '我…呃…我習慣自己打獵。', '', 28153),
(155432, 'zhTW', '開始狩獵吧。', '', 28153),
(155431, 'zhTW', '就這樣吧。', '', 28153),
(155430, 'zhTW', '開始潛行。', '', 28153),
(155429, 'zhTW', '狩獵開始了。', '', 28153),
(155428, 'zhTW', '我的獵物接近了。', '', 28153),
(155427, 'zhTW', '我聽見野性的呼喚。', '', 28153),
(155426, 'zhTW', '你有看到那些馬嗎？好漂亮喔！', '', 28153),
(155425, 'zhTW', '希望很快能再見到你。', '', 28153),
(155424, 'zhTW', '記得，別餵野生動物！', '', 28153),
(155423, 'zhTW', '好好享受度假村！', '', 28153),
(155422, 'zhTW', '…', '', 28153),
(155421, 'zhTW', '我們在這裡做什麼？', '我們在這裡做什麼？', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155420, 'zhTW', '你本來要跟我說什麼？', '你本來要跟我說什麼？', 28153),
(155419, 'zhTW', '我們不能逗留。我們沒有多少時間了。', '我們不能逗留。我們沒有多少時間了。', 28153),
(155418, 'zhTW', '你好啊！', '', 28153),
(155417, 'zhTW', '哈囉！', '', 28153),
(155416, 'zhTW', '歡迎光臨噴泉度假村！', '', 28153),
(155415, 'zhTW', '', '我的姐妹…會得到…石頭的力量！', 28153),
(155414, 'zhTW', '', '這顆石頭中的力量一定會讓母親非常滿意！', 28153),
(155413, 'zhTW', '你來選擇第一個目標地區。等你決定好，我們就出發。', '', 28153),
(155412, 'zhTW', '好，勇士，事不宜遲。我們的特務已經準備好要執行重要任務了。', '', 28153),
(155411, 'zhTW', '烏瑞恩國王，願聖光與您同在。', '', 28153),
(155410, 'zhTW', '陛下，一路順風。', '', 28153),
(155409, 'zhTW', '我還有些事情，必須先回暴風城，不過我很期待看到你的成果。我們一定會打贏這場仗。祝你們好運。', '', 28153),
(155408, 'zhTW', '幸會。', '', 28153),
(155407, 'zhTW', '有時候你可能會需要…低調行事。馬迪亞斯·肖爾大師和軍情七處的特務會協助你。', '', 28153),
(155406, 'zhTW', '很榮幸能跟你共事。', '', 28153),
(155405, 'zhTW', '我會派人全力支援你。第七軍團是聯盟最強的士兵，他們全都聽命於高階指揮官海弗德·龍禍。', '', 28153),
(155404, 'zhTW', '你是聯盟裡數一數二的英雄，我們想要打贏這場仗，你就是關鍵。部落想跟贊達拉聯手，絕對不能讓他們稱心如意。', '', 28153),
(155403, 'zhTW', '勇士，該朝贊達拉進攻了。風之救贖號就停靠在波拉勒斯，我會在船上等你。', '', 28153),
(155402, 'zhTW', '這片森林被詛咒了！快逃！再不逃就來不及了！', '這片森林被詛咒了！快逃！再不逃就來不及了！', 28153),
(155401, 'zhTW', '我從來沒看過這麼可怕的東西！', '我從來沒看過這麼可怕的東西！', 28153),
(155400, 'zhTW', '我的狗被他們吃了！接下來就輪到我了！', '我的狗被他們吃了！接下來就輪到我了！', 28153),
(155399, 'zhTW', '我的老爺爺那艘長滿藤壺的長船啊，這裡發生什麼事了？', '我的老爺爺那艘長滿藤壺的長船啊，這裡發生什麼事了？', 28153),
(155398, 'zhTW', '有一大群兔子在追我，兔子耶！', '有一大群兔子在追我，兔子耶！', 28153),
(155397, 'zhTW', '啊啊啊啊啊啊啊啊！', '啊啊啊啊啊啊啊啊！', 28153),
(155396, 'zhTW', '這些動物簡直是瘋了！', '這些動物簡直是瘋了！', 28153),
(155395, 'zhTW', '謝啦朋友！', '謝啦朋友！', 28153),
(155394, 'zhTW', '我們發現納迦在岸邊鬼鬼祟祟。這一大群納迦一定是來島上搶東西的。', '', 28153),
(155393, 'zhTW', '我們發現納迦的蹤影了。一定是來搶你的艾澤萊晶岩。多加小心。', '', 28153),
(155392, 'zhTW', '納迦部隊出現了，好好接待他們，哈。', '', 28153),
(155391, 'zhTW', '納迦自深海游出，跟我們一樣來這裡找寶石，小心一點。', '', 28153),
(155390, 'zhTW', '小心背後，遠方發現巨龍和它的族人，正朝我們這邊飛來。', '', 28153),
(155389, 'zhTW', '一整群飛龍剛剛飛來，它們已經開始收集艾澤萊晶岩。阻止它們的行動。', '', 28153),
(155388, 'zhTW', '喂，看來我們有伴了。有一群龍飛到這裡來，而且還盯著我們的船。', '', 28153),
(155387, 'zhTW', '有東西飛過來了…看起來好像是龍。一定是來搶艾澤萊晶岩的，小心一點。', '', 28153),
(155386, 'zhTW', '這裡有…黑龍？一定也是來找艾澤萊晶岩的。你們小心一點。', '', 28153),
(155385, 'zhTW', '巨龍…從沒想過我能看到成年的龍。它們想要艾澤萊晶岩，我們的艾澤萊晶岩。', '', 28153),
(155384, 'zhTW', '喂，龍族也到這裡來了。艾澤萊晶岩引起他們的注意了。', '', 28153),
(155383, 'zhTW', '天空越來越暗…是一隻黑龍！帶著其他黑龍一起劫掠這座島嶼，救命啊！', '', 28153),
(155382, 'zhTW', '一大堆風險投資公司的設備和人員剛剛抵達，他們一定是在找艾澤萊晶岩。', '', 28153),
(155381, 'zhTW', '風險投資公司打算在這裡設下根據地。你最好趕快去阻止他們。', '', 28153),
(155380, 'zhTW', '看吶，風險投資公司的投資人跑來這裡搶我們的財寶，你必須跟他們來場友好的商務會談。', '', 28153),
(155379, 'zhTW', '各位朋友，風險投資公司也來了。看來他們打算在這裡紮營了。', '', 28153),
(155378, 'zhTW', '喂，看那裡，好幾艘島嶼食人妖獨木舟。他們也在找艾澤萊晶岩，別讓他們得逞，哈！', '', 28153),
(155377, 'zhTW', '有幾個島嶼食人妖過來了。我敢說一定是來搶東西的。千萬要小心。', '', 28153),
(155376, 'zhTW', '海平面上出現島嶼食人妖獨木舟。從來都不喜歡他們，幫我殺掉幾個食人妖，好嗎？', '', 28153),
(155375, 'zhTW', '島嶼食人妖到岸邊來了，他們看起來可不太友善。', '', 28153),
(155374, 'zhTW', '砲火朝我們這裡打過來了。海盜船正在下錨，準備登島掠奪。', '', 28153),
(155373, 'zhTW', '對，海盜也來這裡湊熱鬧了。他們剛剛上岸，你最好去迎接他們。', '', 28153),
(155372, 'zhTW', '有一群海盜上岸了，跟我們一樣是來找艾澤萊晶岩的。小心一點。', '', 28153),
(155371, 'zhTW', '我不喜歡你…', '你…真的該走了…', 28153),
(155370, 'zhTW', '海平面上出現了另一艘船，看起來像是海盜。你們最好動作快一點，別讓他們把東西全都搶走。', '', 28153),
(155369, 'zhTW', '我知道那東西，薩烏洛克正爬行過來，準備攻擊我們，自己多小心。', '', 28153),
(155368, 'zhTW', '海上有些奇怪的動靜。應該是薩烏洛克出現了，而且還是一大群。', '', 28153),
(155367, 'zhTW', '有幾隻一臉兇惡的蜥蜴正盯著我們的船，最好先解決它們。', '', 28153),
(155366, 'zhTW', '有支薩烏洛克戰隊從水底上岸了。他們也是要來搶艾澤萊晶岩的。', '', 28153),
(155365, 'zhTW', '拜託…不要打到臉！', '你可以停了…', 28153),
(155364, 'zhTW', '我來不及完成工作了啦！', '我還沒買壽險耶！', 28153),
(155363, 'zhTW', '你聽到了嗎？螳螂人來了，他們也要找艾澤萊晶岩。別被他們戳到了，哈哈！', '', 28153),
(155362, 'zhTW', '有一大群螳螂人往這裡來了。你們小心一點…他們來這裡的目的跟我們一模一樣。', '', 28153),
(155361, 'zhTW', '我想這些叫做螳螂人的傢伙出現在這裡，似乎也是為了收集艾澤萊晶岩。', '', 28153),
(155360, 'zhTW', '嗡嗡聲…從天空傳來。我想有一大群蟲子即將降落在這座島上。', '', 28153),
(155359, 'zhTW', '這樣我的保險有雙倍給付…', '真是丟臉！', 28153),
(155358, 'zhTW', '祖靈…帶我走…', '眾靈…帶我走…', 28153),
(155357, 'zhTW', '沒錯，什麼東西聞起來像海草？看那裡，科瓦迪爾長艇已經靠岸了。', '', 28153),
(155356, 'zhTW', '一片霧茫茫，根本什麼都看不清。科瓦迪爾人一定就藏在裡面，小心背後。', '', 28153),
(155355, 'zhTW', '有幾艘破爛的船開了過來，有科瓦迪爾的臭味。他們來搶艾澤萊晶岩了。', '', 28153),
(155354, 'zhTW', '霧越來越濃了，而且不是普通的霧。看樣子科瓦迪爾快來了。', '', 28153),
(155353, 'zhTW', '和我…想的不一樣…', '和我…想的不一樣…', 28153),
(155352, 'zhTW', '我一直想要艘海盜船，首領老兄。我將它取名瑪拉，是我女兒的名字！\n\n若我拿到一艘飛船，我會用我兒子的名字為它命名！', '', 28153),
(155351, 'zhTW', '你怎麼會想到這個名字？', '你怎麼會想到這個名字？', 28153),
(155350, 'zhTW', '耶嘿嘿嘿嘿…\n\n下次再說這個故事吧，首領老兄。', '', 28153),
(155349, 'zhTW', '這艘船你從哪裡取得的？', '這艘船你從哪裡取得的？', 28153),
(155348, 'zhTW', '迦羅娜派我找船。所以我就找了艘船。', '', 28153),
(155347, 'zhTW', '你怎麼會有一艘海盜船？', '你怎麼會有一艘海盜船？', 28153),
(155346, 'zhTW', '有「新朋友」來了，哈哈。好像是維酷人戰士。', '', 28153),
(155345, 'zhTW', '喂，這裡有人出現了。看來是維酷掠奪者，小心點。', '', 28153),
(155344, 'zhTW', '維酷人的長艇登陸了。一群掠奪者，他們來搶劫的。', '', 28153),
(155343, 'zhTW', '好的，首領老兄。準備好叛變了嗎？', '', 28153),
(155342, 'zhTW', '海面上出現長艇了。一定是維酷人來搶晶岩。', '', 28153),
(155341, 'zhTW', '某種存在派了亡者過來這裡。是不屬於這個世界的存在，小心一點。', '', 28153),
(155340, 'zhTW', '靈魂告訴我亡者就在這裡，他們想要你們的艾澤萊晶岩。', '', 28153),
(155339, 'zhTW', '呃，有一股惡臭，一定是不死族想來搶我們的財寶，小心一點。', '', 28153),
(155338, 'zhTW', '這股黑暗氣息非比尋常，有東西正準備搶走艾澤萊晶岩，某種邪惡的事物。', '', 28153),
(155337, 'zhTW', '有一些奇怪的新客人跑來這裡找艾澤萊晶岩，似乎是某個邪教的教徒。', '', 28153),
(155336, 'zhTW', '哇，完全不知道這些傢伙怎麼來的。你有同伴了，快看！', '', 28153),
(155335, 'zhTW', '喂，這些傢伙是哪來的？看來他們也要搶艾澤萊晶岩。我們最好出手阻止他們。', '', 28153),
(155334, 'zhTW', '我們有新朋友了，以前連看都沒看過。可能是來找艾澤萊晶岩的。', '', 28153),
(155333, 'zhTW', '有幾隻魔古蛇就在離岸邊不遠的地方，它們很快就會抵達這裡。', '', 28153),
(155332, 'zhTW', '魔古出現了，打算搶走我們的財寶。熱烈歡迎他們一下，哈。', '', 28153),
(155331, 'zhTW', '有個魔古來搶我們的艾澤萊晶岩了。小心他們成群結隊殺過來。', '', 28153),
(155330, 'zhTW', '我看到雲蛟從那邊飛過來。魔古應該快到了。', '', 28153),
(155329, 'zhTW', '一陣暗影風暴…這一定是無面者來了。', '', 28153),
(155328, 'zhTW', '對，你也聽到低語聲了？一定是古神派出部隊討伐我們，小心一點。', '', 28153),
(155327, 'zhTW', '有些觸鬚臉朋友跑來這裡找艾澤萊晶岩，朋友。我…先閃了。', '', 28153),
(155326, 'zhTW', '無面者也注意到艾澤萊晶岩了。這裡出現了一大群無面者。', '', 28153),
(155325, 'zhTW', '壞鳥！沒有血。', '壞鳥！沒有血。', 28153),
(155324, 'zhTW', '滾！', '滾！', 28153),
(155323, 'zhTW', '', '谷溪森林的獵人們總算又安全了。', 28153),
(155322, 'zhTW', '', '那些野生動物受到女巫的控制，開始獵殺我們的獵人了！快想辦法拯救他們，消滅那些受詛咒的野獸！', 28153),
(155321, 'zhTW', '', '你就像是在我身旁的搞笑配角，$p。', 28153),
(155320, 'zhTW', '', '你好眼熟…你是不是蹲過托達戈爾？', 28153),
(155319, 'zhTW', '', '做得好。這樣一來山丘上的野生動物就不會對附近的居民造成威脅了。', 28153),
(155318, 'zhTW', '', '這片山丘上的野生動物都被女巫的詛咒控制了！消滅這些動物，別讓牠們進到城鎮裡面。', 28153),
(155317, 'zhTW', '越來越難呼吸了！', '越來越難呼吸了！', 28153),
(155312, 'zhTW', '他們會需要一點時間才能從這場攻擊中恢復過來。為了黑暗女王！', '', 28153),
(155311, 'zhTW', '大酋長的部隊已經在軍事學院裡建立了據點。快去幫助他們！', '', 28153),
(155310, 'zhTW', '', '這些人是我以前的同學！部落一定會為此付出代價！', 28153),
(155309, 'zhTW', '', '部落的精英部隊闖進普勞德摩爾軍校了。海軍需要我們幫忙防禦！', 28153),
(155308, 'zhTW', '', '落港村總算又安全了，但我們還是不能鬆懈。', 28153),
(155307, 'zhTW', '', '落港村又受到女巫詛咒的影響了。趕快破除詛咒，別讓村莊失陷！', 28153),
(155306, 'zhTW', '', '啊…岩石的力量…只屬於…斯陀頌恩！', 28153),
(155305, 'zhTW', '', '這顆石頭是深淵贈禮，你不該拿走！', 28153),
(155304, 'zhTW', '當花凋謝時，我就知道我只能靠自己了，所以立刻在碼頭找了一份工作。那朵花讓我不會像其他人一樣，淪落到變成遊民。', '當花凋謝時，我就知道我只能靠自己了，所以立刻在碼頭找了一份工作。那朵花讓我不會像其他人一樣，淪落到變成遊民。', 28153),
(155303, 'zhTW', '無論是野豬人或入侵的部落，這個山谷的人民皆屹立不搖。', '', 28153),
(155302, 'zhTW', '別拿…穴居怪的石頭…', '', 28153),
(155301, 'zhTW', '我的石頭…', '', 28153),
(155300, 'zhTW', '粉碎…你…', '', 28153),
(155299, 'zhTW', '穴居怪…碎了…', '', 28153),
(155298, 'zhTW', '穴居怪打碎…', '', 28153),
(155297, 'zhTW', '穴居怪…殺…', '', 28153),
(155296, 'zhTW', '啊啊呃！', '', 28153),
(155295, 'zhTW', '嗄嘍喔…', '', 28153),
(155294, 'zhTW', '這是穴居怪的地盤！快離開！', '', 28153),
(155293, 'zhTW', '啊啊啊嗚！穴居怪殺了你！', '', 28153),
(155292, 'zhTW', '把你打碎！', '', 28153),
(155291, 'zhTW', '', '我讓庫爾提拉斯各地順利營運。我能怎麼幫助你呢？', 28153),
(155290, 'zhTW', '亮亮石頭屬於穴居怪！給我離開！', '', 28153),
(155289, 'zhTW', '噶啦啊啊！破壞一切！', '', 28153),
(155288, 'zhTW', '穴居怪打你的臉！', '', 28153),
(155287, 'zhTW', '穴居怪打扁你的頭顱！', '', 28153),
(155286, 'zhTW', '這是穴居怪的地盤！', '', 28153),
(155285, 'zhTW', '特洛格佐爾！', '', 28153),
(155284, 'zhTW', '我的石頭！不是你的！', '', 28153),
(155283, 'zhTW', '我的寶藏！都是我的！', '', 28153),
(155282, 'zhTW', '啦啊啊！', '', 28153),
(155281, 'zhTW', '啊啊啊呃！', '', 28153),
(155280, 'zhTW', '碾碎！折斷！殺戮！', '', 28153),
(155279, 'zhTW', '穴居怪打打！', '', 28153),
(155278, 'zhTW', '穴居怪不笨！', '', 28153),
(155277, 'zhTW', '喂！你看到公主怎麼對付聯盟了嗎？看看你左邊那些殘骸，羅亞的力量真是強大！', '', 28153),
(155276, 'zhTW', '納迦離開一段時間之後，有人說要重建神廟。可是格拉爾不是失蹤的話，就是虛弱到無力協助，因此目前還只是說說而已。', '', 28153),
(155275, 'zhTW', '他的追隨者無人倖存，格拉爾大為震怒！那晚在水邊的人都能感受到他的痛苦…用死亡來感受。', '', 28153),
(155274, 'zhTW', '喔厚！感覺就像是烏雲散去！我們知道那個陰險的長髮女巫死了！', '', 28153),
(155273, 'zhTW', '祝你今天充滿驚喜。', '', 28153),
(155272, 'zhTW', '小心，這片土地再也不安全了。', '', 28153),
(155271, 'zhTW', '斯陀頌恩到處都是寶藏。', '', 28153),
(155270, 'zhTW', '歡迎來到谷地。', '', 28153),
(155269, 'zhTW', '你好！', '', 28153),
(155268, 'zhTW', '布瑞納丹是我的家，我要保護它。', '', 28153),
(155267, 'zhTW', '', '我是說到做到的女人。我的港口歡迎你們部落。', 28153),
(155266, 'zhTW', '對，船長兄弟。我們會協助你們。而且也希望你們會協助我們。', '', 28153),
(155265, 'zhTW', '', '自由嗎…看來你是言出必行啊。', 28153),
(155264, 'zhTW', '你為什麼…來這裡…？', '', 28153),
(155263, 'zhTW', '你只毀掉一根荊棘…但藤蔓還在…', '', 28153),
(155262, 'zhTW', '嘎啊！', '', 28153),
(155261, 'zhTW', '不…寶石…', '', 28153),
(155260, 'zhTW', '你無法殺光…我們…', '', 28153),
(155259, 'zhTW', '我失敗了…', '', 28153),
(155258, 'zhTW', '啪地一聲…', '', 28153),
(155257, 'zhTW', '荊棘…斷裂…', '', 28153),
(155256, 'zhTW', '這個地方的發光寶石都是我們的，入侵者！', '', 28153),
(155255, 'zhTW', '石頭讓我們的荊棘更堅硬！', '', 28153),
(155254, 'zhTW', '這片土地和它的力量，都歸我們掌控！', '', 28153),
(155253, 'zhTW', '我們的荊棘輕易就能刺穿你的血肉。', '', 28153),
(155252, 'zhTW', '我會把你的肉掛在小屋上！', '', 28153),
(155251, 'zhTW', '我們做了明智的選擇。', '', 28153),
(155250, 'zhTW', '我們的藤蔓會掌控這座島嶼，還有你的血肉！', '', 28153),
(155249, 'zhTW', '荊棘破壞者，這裡不是你們該來的地方。', '', 28153),
(155248, 'zhTW', '快點，來幫助我！', '', 28153),
(155247, 'zhTW', '以其人之道還治其人！', '', 28153),
(155246, 'zhTW', '你阻止不了失控的藤蔓！', '', 28153),
(155245, 'zhTW', '用你的鮮血澆灌荊棘。', '', 28153),
(155244, 'zhTW', '開砲！', '', 28153),
(155243, 'zhTW', '打破它們！', '', 28153),
(155242, 'zhTW', '你將枯萎，荊棘之敵。', '', 28153),
(155241, 'zhTW', '這是我們的地盤！', '', 28153),
(155240, 'zhTW', '呆坐在籠子裡，對我們一點幫助都沒有。', '', 28153),
(155239, 'zhTW', '刺穿他們的血肉！', '', 28153),
(155238, 'zhTW', '刺穿入侵者！', '', 28153),
(155237, 'zhTW', '', '前方的波浪起伏不定。', 28153),
(155236, 'zhTW', '入侵者！', '', 28153),
(155235, 'zhTW', '死吧，荊棘破壞者！', '', 28153),
(155234, 'zhTW', '', '願潮水指引你。', 28153),
(155233, 'zhTW', '聖物受到保護，格拉爾尚未失蹤。', '', 28153),
(155232, 'zhTW', '鮮血與雷霆，朋友。', '', 28153),
(155231, 'zhTW', '還有，我發現這個有趣的飾品。', '', 28153),
(155230, 'zhTW', '我們似乎不應該那麼急著離開哨站。', '', 28153),
(155229, 'zhTW', '', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_01.BLP:20|t%s以燃燒引線標記你，別靠近彈藥桶！', 28153),
(155228, 'zhTW', '享受你剩下的日子，拉茲迦基。下次再見面…就是你的死期！', '', 28153),
(155227, 'zhTW', '旅程帶我們來到這裡，我們的發現是謎題的另一塊拼圖。', '', 28153),
(155226, 'zhTW', '', '路上小心。', 28153),
(155225, 'zhTW', '', '市長在此。有何貴幹？', 28153),
(155224, 'zhTW', '', '我一定要保護斯陀頌恩的居民。', 28153),
(155223, 'zhTW', '', '你來幫忙的嗎？', 28153),
(155222, 'zhTW', '為了部落！', '', 28153),
(155221, 'zhTW', '看看牠在網裡動的樣子！幫牠除臟一定很有樂趣！', '看看牠在網裡動的樣子！幫牠除臟一定很有樂趣！', 28153),
(155220, 'zhTW', '哈！又抓到一隻！', '哈！又抓到一隻！', 28153),
(155219, 'zhTW', '是的，老兄。我能說的故事可多呢！', '', 28153),
(155218, 'zhTW', '', '所以呢，泰巾，若我們要合作，你就要告訴我多點部落的事。', 28153),
(155217, 'zhTW', '所有艾澤萊晶岩…都…是…我們的…', '', 28153),
(155216, 'zhTW', '艾澤萊晶岩是艾胥凡公司的財產！', '', 28153),
(155215, 'zhTW', '', '敵方部隊正在行動！擊退他們！', 28153),
(155214, 'zhTW', '', '謝謝你幫我們爭取到喘息的空間。', 28153),
(155213, 'zhTW', '', '總算擊退那些女巫了！做得好！', 28153),
(155212, 'zhTW', '', '女巫會正在攻擊這個區域。把她們趕走！', 28153),
(155211, 'zhTW', '', '我們總算能喘口氣了，謝謝你。', 28153),
(155210, 'zhTW', '', '女巫的人正在攻擊佐司瓦的居民！趕快擊退這些可惡的女巫！', 28153),
(155209, 'zhTW', '', '我代表這裡的人民，感謝你伸出援手。', 28153),
(155208, 'zhTW', '', '我的人民非常需要你的幫助。請你一定要幫忙！', 28153),
(155207, 'zhTW', '不！我們先讓他稱心如意一陣子。我們會暫時離開…等我們下次回來，就不會那麼慷慨了！', '', 28153),
(155206, 'zhTW', '我可以解決那個$r，首領！沒問題！', '我可以解決那個$r，首領！沒問題！', 28153),
(155205, 'zhTW', '別讓騙我一個人回去。你真的認為你那些小流氓能夠應付我在這裡的朋友？不要自取其辱了。', '', 28153),
(155204, 'zhTW', '結束了？你結束與否完全由我決定！你知道那些逃兵的下場！', '', 28153),
(155203, 'zhTW', '我受夠了，摩詹波。我不想再為了生存燒殺擄掠，從現在起，我們各走各的路…', '', 28153),
(155202, 'zhTW', '嘻嘻嘻…', '嘻嘻嘻…', 28153),
(155201, 'zhTW', '你不是想躲著你的老朋友吧？', '', 28153),
(155200, 'zhTW', '好吧，要不是拉茲迦基！我告訴你我們可以在這裡找到他…', '', 28153),
(155199, 'zhTW', '小心提防，摩詹波不值得信任…', '', 28153),
(155198, 'zhTW', '我準備好了。出發吧。', '我準備好了。出發吧。', 28153),
(155197, 'zhTW', '願大海祝福這些錠塊，並永遠不會要奪回它們。', '願大海祝福這些錠塊，並永遠不會要奪回它們。', 28153),
(155196, 'zhTW', '', '有了大師的力量助陣，我們就能再站起來！', 28153),
(155195, 'zhTW', '你能祝福這些風暴白銀錠嗎？', '你能祝福這些風暴白銀錠嗎？', 28153),
(155194, 'zhTW', '祝你一帆風順，$r。', '祝你一帆風順，$r。', 28153),
(155193, 'zhTW', '', '所有人都會臣服於艾薩拉女王腳下！', 28153),
(155192, 'zhTW', '', '隨著他的意志將你吞噬，你的眼睛無比灼痛！', 28153),
(155191, 'zhTW', '將魚叉拔出。', '將魚叉拔出。', 28153),
(155190, 'zhTW', '<這個生物虛弱地看了你一會兒，然後轉頭看向插在牠身側的一把魚叉。>', '<這個生物虛弱地看了你一會兒，然後轉頭看向插在牠身側的一把魚叉。>', 28153),
(155189, 'zhTW', '你要去哪？', '', 28153),
(155188, 'zhTW', '莫嗄，瑪古嘟！打死他們！', '', 28153),
(155187, 'zhTW', '嗚嗄法！想要給你一些傷口！', '', 28153),
(155186, 'zhTW', '嗚嗚，你們壞人！走開！', '', 28153),
(155185, 'zhTW', '瑪古達是誰？', '', 28153),
(155184, 'zhTW', '個哇呃！這些石頭…我的石頭！', '', 28153),
(155183, 'zhTW', '哇啊！你拿不寶藏！', '', 28153),
(155182, 'zhTW', '個哇啊？這是誰？', '', 28153),
(155181, 'zhTW', '布哇古！我要你去餵魚！', '', 28153),
(155180, 'zhTW', '啊古…？', '', 28153),
(155179, 'zhTW', '呃個！', '', 28153),
(155178, 'zhTW', '嗄夫…莫個…', '', 28153),
(155177, 'zhTW', '歐個…', '', 28153),
(155176, 'zhTW', '莫個！', '', 28153),
(155175, 'zhTW', '瑪吐法…', '', 28153),
(155174, 'zhTW', '葛克！', '', 28153),
(155173, 'zhTW', '啊布布布布！', '', 28153),
(155172, 'zhTW', '呃嗄，瑪古？', '', 28153),
(155171, 'zhTW', '喀利！', '', 28153),
(155170, 'zhTW', '布嗄，布嗄！', '', 28153),
(155169, 'zhTW', '啊！', '', 28153),
(155168, 'zhTW', '歐卡，瑪個多！', '', 28153),
(155167, 'zhTW', '波酷？', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155166, 'zhTW', '布嗄，瑪布古！', '', 28153),
(155165, 'zhTW', '啊嗄瑪，嗄瑪！', '', 28153),
(155164, 'zhTW', '他的心臟跳得越來越弱…我已經無計可施，只能幫他結束他的苦難了。', '', 28153),
(155163, 'zhTW', '艾胥凡懸賞要你的項上人頭！', '艾胥凡懸賞要你的項上人頭！', 28153),
(155162, 'zhTW', '我會從你的屍體上拿走戰利品！', '我會從你的屍體上拿走戰利品！', 28153),
(155161, 'zhTW', '你擊敗不了艾胥凡的！', '你擊敗不了艾胥凡的！', 28153),
(155160, 'zhTW', '這座城市是我們的！', '這座城市是我們的！', 28153),
(155159, 'zhTW', '波拉勒斯會陷入烈焰！', '波拉勒斯會陷入烈焰！', 28153),
(155158, 'zhTW', '我會趕到比較安全的地方跟你會合！', '我會趕到比較安全的地方跟你會合！', 28153),
(155157, 'zhTW', '我要搭渡船到佐司瓦。', '我要搭渡船到佐司瓦。', 28153),
(155156, 'zhTW', '為什麼…你來這裡…？', '', 28153),
(155155, 'zhTW', '亮亮石頭…我的…', '', 28153),
(155154, 'zhTW', '我的蠟燭！', '', 28153),
(155153, 'zhTW', '噢噢噢！', '', 28153),
(155152, 'zhTW', '嘎啊！', '', 28153),
(155151, 'zhTW', '蠟燭…熄滅…', '', 28153),
(155150, 'zhTW', '啊啊啊啊！', '', 28153),
(155149, 'zhTW', '不！', '', 28153),
(155148, 'zhTW', '把你當成大蠟燭點來燒！', '', 28153),
(155147, 'zhTW', '你的蠟燭是我的了！', '', 28153),
(155146, 'zhTW', '打倒你！拿走你的東西！', '', 28153),
(155145, 'zhTW', '把你的頭顱開個洞！', '', 28153),
(155144, 'zhTW', '不要拿走我的亮亮石頭！', '', 28153),
(155143, 'zhTW', '我的島嶼！我作主！', '', 28153),
(155142, 'zhTW', '亮亮石頭是我的！我的！', '', 28153),
(155141, 'zhTW', '這裡是我們發現的，不是你！', '', 28153),
(155140, 'zhTW', '這我的地盤！', '', 28153),
(155139, 'zhTW', '咬他們！拿走他們的蠟燭！', '', 28153),
(155138, 'zhTW', '噶啦！入侵者！', '', 28153),
(155135, 'zhTW', '不能拿走蠟燭！', '', 28153),
(155134, 'zhTW', '比呲波噓！', '', 28153),
(155133, 'zhTW', '亮亮石頭是我們的！', '', 28153),
(155132, 'zhTW', '亮亮石頭讓蠟燭變得更亮！', '', 28153),
(155131, 'zhTW', '祝你好運，內陸人。你要是信神的話，最好祈禱神與你同在。', '祝你好運，內陸人。你要是信神的話，最好祈禱神與你同在。', 28153),
(155130, 'zhTW', '到了，我最遠就只能送你到這裡了。', '到囉，我最遠就只能送你到這裡了。', 28153),
(155129, 'zhTW', '我上次想在這裡停船，結果差點被野狼咬斷一條腿…', '我上次想在這裡停船，結果差點被野狼咬斷一條腿…', 28153),
(155128, 'zhTW', '我們在遠一點的地方下船，鑿刻匠港口最近可不怎麼平靜。', '我們在遠一點的地方下船，鑿刻匠港口最近可不怎麼平靜。', 28153),
(155127, 'zhTW', '不管你去那裡是要做什麼，我都建議你盡快想辦法搞定。', '不管你去那裡是要做什麼，我都建議你盡快想辦法搞定。', 28153),
(155126, 'zhTW', '我是不像其他庫爾提拉斯人那麼迷信，但連我這種人都覺得，最近在佐司瓦發生的事真的讓人心裡發毛。', '我是不像其他庫爾提拉斯人那麼迷信，但連我這種人都覺得，最近在佐司瓦發生的事真的讓人心裡發毛。', 28153),
(155125, 'zhTW', '到了最近，礦坑大概都沒東西可以挖了，想找屠夫也都找不到了。', '到了最近，礦坑大概都沒東西可以挖了，想找屠夫也都找不到了。', 28153),
(155124, 'zhTW', '沒多久以前，商人還常常搭渡船，想運送從農夫和礦工那裡收來的貨品。', '沒多久以前，商人還常常搭渡船，想運送從農夫和礦工那裡收來的貨品。', 28153),
(155123, 'zhTW', '其他人可沒有這個膽子去，關於那個地方的謠言已經滿天飛了。', '其他人可沒有這個膽子去，關於那個地方的謠言已經滿天飛了。', 28153),
(155122, 'zhTW', '想去佐司瓦，是吧？算你好運，這艘船上有我在。', '想去佐司瓦，是吧？算你好運，這艘船上有我在。', 28153),
(155121, 'zhTW', '嗚啊！啊！！', '', 28153),
(155120, 'zhTW', '嗚…', '', 28153),
(155119, 'zhTW', '嘎…你…', '', 28153),
(155118, 'zhTW', '哇！被打中！', '', 28153),
(155117, 'zhTW', '啊！', '', 28153),
(155116, 'zhTW', '怪怪人…好壞…', '', 28153),
(155115, 'zhTW', '嗚克…嘟克…', '', 28153),
(155114, 'zhTW', '不，我的寶物！', '', 28153),
(155113, 'zhTW', '贊達拉的各種花草動物都需要研究和分門別類。', '贊達拉的各種花草動物都需要研究和分門別類。', 28153),
(155112, 'zhTW', '這些臭豬是從哪來的？', '', 28153),
(155111, 'zhTW', '我要狠狠往你的痛處打！', '', 28153),
(155110, 'zhTW', '將他們打扁！', '', 28153),
(155109, 'zhTW', '做得太好了！我們馬上就回去做強效藥水！', '', 28153),
(155108, 'zhTW', '抱歉夥計，沒時間接新工作了，行程都排滿…嘿，你有錢？忘記我剛才說的話，我能幫你什麼？', '抱歉夥計，沒時間接新工作了，行程都排滿…嘿，你有錢？忘記我剛才說的話，我能幫你什麼？', 28153),
(155107, 'zhTW', '我們的部隊現在很需要鍊金補給品！請幫我在這個區域尋找必要的材料。噢，對了，要小心這裡的熊。', '', 28153),
(155106, 'zhTW', '', '女巫的部隊正在攻擊獵鷹林！想辦法清除她們的邪惡魔法，讓城鎮重拾往日的平靜！', 28153),
(155105, 'zhTW', '', '我們把女巫都趕走了，獵鷹林的居民總算安全了。真的很感謝你。', 28153),
(155104, 'zhTW', '歡迎，這裡的一切都是剛從當地人身上掠奪來的。今天來買點全新的異國物品吧！', '歡迎，這裡的一切都是剛從當地人身上掠奪來的。今天來買點全新的異國物品吧！', 28153),
(155103, 'zhTW', '走開，寶物是我們的！', '', 28153),
(155102, 'zhTW', '作惡的壞蛋，這是我的島嶼！', '', 28153),
(155101, 'zhTW', '我要踩扁你，臭豬！', '', 28153),
(155100, 'zhTW', '用扳手打扁他！', '殺光！', 28153),
(155099, 'zhTW', '我們很快就會有一場工安意外了！', '我不管什麼工作安全守則了！', 28153),
(155098, 'zhTW', '一看就知道你是人生輸家！', '快拿扳手！我們來修理這傢伙！', 28153),
(155097, 'zhTW', '我們…鋒利依舊…', '', 28153),
(155096, 'zhTW', '擊敗我們，也不是真的獲勝…', '', 28153),
(155095, 'zhTW', '孢子會殺死你…', '', 28153),
(155094, 'zhTW', '就算死亡…我們也不會放棄…', '', 28153),
(155093, 'zhTW', '我們拋下軀體…', '', 28153),
(155092, 'zhTW', '至少…我們…是光榮戰死的…', '', 28153),
(155091, 'zhTW', '於是，我們倒下了。', '', 28153),
(155090, 'zhTW', '我們生長…就是為了…再次戰鬥…', '', 28153),
(155089, 'zhTW', '為了孢子！', '', 28153),
(155088, 'zhTW', '我們團結堅定！', '', 28153),
(155087, 'zhTW', '嘿！我們都照規矩來，你偏偏要來搗亂！', '那邊那個誰…你被開除了！', 28153),
(155086, 'zhTW', '你覺得痛了吧！我們贏定了！', '', 28153),
(155085, 'zhTW', '看我的鋒葉快刀！', '', 28153),
(155084, 'zhTW', '我們志在必得！', '', 28153),
(155083, 'zhTW', '你這場仗根本輸定了！', '', 28153),
(155082, 'zhTW', '你真的需要多練習了！', '', 28153),
(155081, 'zhTW', '看我們把你剁成碎泥！', '', 28153),
(155080, 'zhTW', '拜託，救救波拉勒斯！', '拜託，救救波拉勒斯！', 28153),
(155079, 'zhTW', '這些海盜會毀了波拉勒斯！', '這些海盜會毀了波拉勒斯！', 28153),
(155078, 'zhTW', '謝謝你！', '謝謝你！', 28153),
(155077, 'zhTW', '將壞蛋打成肉醬！', '', 28153),
(155076, 'zhTW', '我是這裡的王，壞蛋！', '', 28153),
(155075, 'zhTW', '殺掉他們！拿走他們的蛋蛋！', '', 28153),
(155074, 'zhTW', '可惡的離岸人！', '', 28153),
(155073, 'zhTW', '殺死怪怪人！', '', 28153),
(155072, 'zhTW', '寶藏讓我們強壯！', '', 28153),
(155071, 'zhTW', '我們的島嶼！不是你們的！', '', 28153),
(155070, 'zhTW', '你可惡！', '', 28153),
(155069, 'zhTW', '別拿走我們的寶藏！', '', 28153),
(155068, 'zhTW', '怪怪人走開！', '', 28153),
(155067, 'zhTW', '多年以前，我訓練札拉贊恩和沃金達到大師的境界。我完全沒料到他們的命運會撼動這個世界。', '', 28153),
(155066, 'zhTW', '我只是在工作啊！', '我只是在做我的工作！', 28153),
(155065, 'zhTW', '早知道就不幫你工作了！', '早知道就不幫你工作了！', 28153),
(155064, 'zhTW', '', '嗯，是的？我能幫你什麼忙嗎？', 28153),
(155063, 'zhTW', '我會想念…啤酒的…', '我會想念…啤酒的…', 28153),
(155062, 'zhTW', '我就知道這不是什麼好工作！', '我就知道這不是什麼好工作！', 28153),
(155061, 'zhTW', '祖靈啊…我要加入你們了…', '祖靈啊…我要加入你們了…', 28153),
(155060, 'zhTW', '我只是想…休息一下…', '我只是想…休息一下…', 28153),
(155059, 'zhTW', '我要…告訴老大…', '', 28153),
(155058, 'zhTW', '下次你讓我贏…', '', 28153),
(155057, 'zhTW', '哈哈！我贏啦…噢！等等…', '', 28153),
(155056, 'zhTW', '不…我不會輸…', '', 28153),
(155055, 'zhTW', '你是問題…我修理問題。', '', 28153),
(155054, 'zhTW', '我是熱能技師。我聰明。我做火！', '', 28153),
(155053, 'zhTW', '你去沾油…我來點火！', '你全身油…我來點火！', 28153),
(155052, 'zhTW', '我不喜歡火…你拿火！', '我不喜歡火…你拿火！', 28153),
(155051, 'zhTW', '我會把你烤到全熟。', '我搞不好會把你煎到全熟。', 28153),
(155050, 'zhTW', '你最好別想在這裡撒野。', '你最好想清楚要不要在這裡撒野。', 28153),
(155049, 'zhTW', '別來搗亂，不然你會燒傷的。', '別來搗亂，不然你很快就會被燒死。', 28153),
(155048, 'zhTW', '你很快就會開始發燙。', '你很快就會開始發燙。', 28153),
(155047, 'zhTW', '噢，是誰說要來點熱的？', '是誰要來點熱的？', 28153),
(155046, 'zhTW', '怪獸回到深海裡了。', '', 28153),
(155045, 'zhTW', '怪獸回來了！快把牠趕走，別讓牠破壞這面牆！', '', 28153),
(155044, 'zhTW', '什麼？沃金… 你不可能變得如此強壯，除非你變成…一個…', '', 28153),
(155043, 'zhTW', '你以為消滅我的身體…就能阻止我…把你大卸八塊？', '', 28153),
(155042, 'zhTW', '你以為有勝算？不過是在拖延時間罷了。', '', 28153),
(155041, 'zhTW', '我看著伯昂薩姆第折磨我的靈魂學了不少，輪到我讓你瞧瞧新學到的巫毒把戲了。', '', 28153),
(155040, 'zhTW', '你不可能藏他一輩子的。我一定要對沃金還有整個暗矛部族復仇！', '', 28153),
(155039, 'zhTW', '聽我命令！殺掉他們，把沃金的骨灰帶回來！馬上去！', '', 28153),
(155038, 'zhTW', '在哪裡？你們到底把沃金藏在哪裡？怎麼會找不到他？', '', 28153),
(155037, 'zhTW', '暗矛部族，你們把他藏在哪？我的老朋友呢？', '', 28153),
(155036, 'zhTW', '打倒暗矛部族，然後把骨灰帶回來。', '', 28153),
(155035, 'zhTW', '全都給我搜，把沃金的骨灰給我帶回來！', '', 28153),
(155034, 'zhTW', '這些討厭的蟲子什麼都吃，噁心死了。', '', 28153),
(155033, 'zhTW', '拉尼舒都衝過來了！快踩死牠們，別讓牠們造成更嚴重的問題。', '', 28153),
(155032, 'zhTW', '會的。一路順風。', '會的。一路順風。', 28153),
(155031, 'zhTW', '你已經為我指引了正確的方向。你不會有事吧？', '你已經為我指引了正確的方向。你不會有事吧？', 28153),
(155030, 'zhTW', '很抱歉我們只能幫上這點忙。', '很抱歉我和我哥哥只能幫上這點忙。', 28153),
(155029, 'zhTW', '', '非常好！很高興你是站在我們這邊的。', 28153),
(155028, 'zhTW', '', '競技場附近有個沙旋蜘蛛巢，我需要你去清掉那座巢穴！', 28153),
(155027, 'zhTW', '這種武器可能是地精科技產物。管他的，反正在戰鬥時能發揮效果就好。', '', 28153),
(155026, 'zhTW', '我方陸戰隊發現一些…很有意思的武器，如果能知道怎麼使用的話，或許能派上用場。你就拿這邊的野生動物來試試看吧。', '', 28153),
(155025, 'zhTW', '', '那麼大量的貨物，艾胥凡公司要好幾個禮拜才能追回來。做得很好！', 28153),
(155024, 'zhTW', '', '艾胥凡公司在附近惹是生非，你去幫忙阻止他們的行動。', 28153),
(155023, 'zhTW', '一百個笨蛋降落在滿是武器的島嶼上！賣票讓大家在飛艇上欣賞這副景象吧！', '一百個笨蛋降落在滿是武器的島嶼上！賣票讓大家在飛艇上欣賞這副景象吧！', 28153),
(155022, 'zhTW', '我們對機器人徵稅，然後再製造機器人收稅員！源源不絕的錢！', '我們對機器人徵稅，然後再製造機器人收稅員！源源不絕的錢！', 28153),
(155021, 'zhTW', '一個暗球！效果和光球相反。', '一個暗球！效果和光球相反。', 28153),
(155020, 'zhTW', '小頂的正式場合帽子，讓你在正式場合日常穿戴用！', '小頂的正式場合帽子，讓你在正式場合日常穿戴用！', 28153),
(155019, 'zhTW', '漂浮圖騰：登船後使用的圖騰！', '漂浮圖騰：登船後使用的圖騰！', 28153),
(155018, 'zhTW', '槍鞋！等等，不對…那個我們做過了。槍襪！', '槍鞋！等等，不對…那個我們做過了。槍襪！', 28153),
(155017, 'zhTW', '可回收的煙花！', '可回收的煙花！', 28153),
(155016, 'zhTW', '一支全員為哥布林的炸彈橇隊伍！', '一支全員為哥布林的炸彈橇隊伍！', 28153),
(155015, 'zhTW', '武器等級的乳酪。', '武器等級的乳酪。', 28153),
(155014, 'zhTW', '雙持電鋸戰刃！快把這賣給伊利達瑞！', '雙持電鋸戰刃！快把這賣給伊利達瑞！', 28153),
(155013, 'zhTW', '橄欖石白日夢，大幅縮短你小睡的時間！', '橄欖石白日夢，大幅縮短你小睡的時間！', 28153),
(155012, 'zhTW', '戰術烤肉鉗！', '戰術烤肉鉗！', 28153),
(155011, 'zhTW', '這是個關於一名人類和，呃，一名錦魚人的愛情故事！', '這是個關於一名人類和，呃，一名錦魚人的愛情故事！', 28153),
(155010, 'zhTW', '士兵，非常好！很高興你是站在我們這邊的。', '', 28153),
(155009, 'zhTW', '一根不是用來支撐天花板，卻是用來撐住地板不讓它升起的柱子！', '一根不是用來支撐天花板，卻是用來撐住地板不讓它升起的柱子！', 28153),
(155008, 'zhTW', '附近有個沙旋蜘蛛巢，擋住了進入峽谷的那條道路，我需要你去幫大軍清出一條路！', '', 28153),
(155007, 'zhTW', '艾澤萊晶岩魔法8號球？艾澤萊？還是艾澤去？', '艾澤萊晶岩魔法8號球？艾澤萊？還是艾澤去？', 28153),
(155006, 'zhTW', '泰達希爾煤炭球！帶來濃郁的煙燻烤肉氣味！', '泰達希爾煤炭球！帶來濃郁的煙燻烤肉氣味！', 28153),
(155005, 'zhTW', '行駛於水上而不是陸地的車輛！', '行駛於水上而不是陸地的車輛！', 28153),
(155004, 'zhTW', '吟游詩人！', '吟游詩人！', 28153),
(155003, 'zhTW', '可以召喚飛行管理員的口哨！', '可以召喚飛行管理員的口哨！', 28153),
(155002, 'zhTW', '士兵，做得好！沃魯敦一向被稱為死亡陷阱，現在總算少了一個禍害。', '', 28153),
(155001, 'zhTW', '讓你在各方面都獲得提升的秘法水晶！或許有一點不穩定，但是沒關係！', '讓你在各方面都獲得提升的秘法水晶！或許有一點不穩定，但是沒關係！', 28153),
(155000, 'zhTW', '有隻巨大的拉尼舒佔據了這座峽谷，不過直接攻擊牠太有勇無謀了，你必須找個其他方法來制伏牠！', '', 28153),
(154999, 'zhTW', '廁紙滑膛槍！想想這能替你省下多少時間！', '廁紙滑膛槍！想想這能替你省下多少時間！', 28153),
(154998, 'zhTW', '雙層船！這樣就能節省我們在海上的活動空間。我先喊要上面！', '雙層船！這樣就能節省我們在海上的活動空間。我先喊要上面！', 28153),
(154997, 'zhTW', '可重複使用的口香糖！與你的朋友、寵物，甚至是陌生人一同分享吧！', '可重複使用的口香糖！與你的朋友、寵物，甚至是陌生人一同分享吧！', 28153),
(154996, 'zhTW', '這工作很髒沒錯，但總要派人去吧！士兵，就你囉！', '', 28153),
(154995, 'zhTW', '想活命的話，我們一定要想辦法在沙漠種植作物才行。第一步就是找到肥料…這個任務就交給你了。', '', 28153),
(154994, 'zhTW', '我本來還半信半疑，但這個拿來對付無信者，一定很好用。', '', 28153),
(154993, 'zhTW', '塔恰在廢墟又挖到一根贊達拉圖騰，去看看這根圖騰有什麼用途。', '', 28153),
(154992, 'zhTW', '看起來真好玩！我要把這個留著用來對付獸人！', '', 28153),
(154991, 'zhTW', '那麼大量的貨物，艾胥凡公司要好幾個禮拜才能追回來。做很好！', '', 28153),
(154990, 'zhTW', '斥候在一座廢墟裡面找到這根古老的贊達拉圖騰，來看看這東西有什麼用吧。', '', 28153),
(154989, 'zhTW', '艾胥凡公司在附近進行非法採礦作業，我要你去搞個破壞。', '', 28153),
(154988, 'zhTW', '死亡沙漠綿延，求生意志無限。謝謝你。', '', 28153),
(154987, 'zhTW', '綠洲在沃魯敦非常珍貴，我們要盡可能找出綠洲的位置。', '', 28153),
(154986, 'zhTW', '光是在戰鬥中獲勝，未必能帶來勝利。有了這些補給，我們才能繼續撐下去。', '', 28153),
(154985, 'zhTW', 'Za uull og nuq i fssh zz oou iiyoq ez oou gul\'kafh anagg。', '', 28153),
(154984, 'zhTW', '我們正在深入這片大陸，佔領這片綠洲會為我們帶來相當程度的戰略優勢。', '', 28153),
(154983, 'zhTW', '我的墜落，只是無盡深淵的一次心跳。', '', 28153),
(154982, 'zhTW', '我不得不承認，結果比我預期的好太多了。', '', 28153),
(154981, 'zhTW', '我們…在贊姆蘭港那群特殊的盟友提出一個新計畫，要是你信得過他們，就去幫忙一下吧。', '', 28153),
(154980, 'zhTW', '哈！敢招惹聯盟就是這個下場！', '', 28153),
(154979, 'zhTW', '有士兵偷來一艘船，船上裝滿了武器。大家準備來對付那群不死怪物吧！', '', 28153),
(154978, 'zhTW', '非常好！看看這群該死的東西，下次還敢不敢攻擊聯盟。', '', 28153),
(154977, 'zhTW', '該死的不死海盜抓走了我們的士兵，快去救他們，絕對不能拋下他們！', '', 28153),
(154976, 'zhTW', '', '謝謝你，就算是流放者也不該受到這種對待。', 28153),
(154975, 'zhTW', '', '贊姆蘭的海盜俘虜了贊達拉流放者，快去救他們！', 28153),
(154974, 'zhTW', '無信者的注意力被引開了，讓他們知道什麼叫做死從天降！', '', 28153),
(154973, 'zhTW', '我知道他們一定會復活，但現在至少可以享受片刻安寧。', '', 28153),
(154972, 'zhTW', '無信者的數量太多了，我們必須把他們關在這裡面。', '', 28153),
(154971, 'zhTW', '將榮耀獻給瑟沙利斯！希望有一天，塞斯拉克人會想起她的恩惠…', '', 28153),
(154970, 'zhTW', '我將一部分的力量分給你，你要好好淨化這片土地上的無信者。', '', 28153),
(154969, 'zhTW', '', '我的力量…你做了什麼好事？', 28153),
(154968, 'zhTW', '', '這股力量…我…動彈不得…', 28153),
(154967, 'zhTW', '我的生命…正在流失…', '', 28153),
(154966, 'zhTW', '我動不了…救…我…', '', 28153),
(154965, 'zhTW', '嗚啊…', '', 28153),
(154964, 'zhTW', '你真以為自己對抗了神還能活著脫身？去死吧！', '', 28153),
(154963, 'zhTW', '不夠！我需要更多鮮血來止渴！', '', 28153),
(154962, 'zhTW', '你的鮮血會滋養我！', '', 28153),
(154961, 'zhTW', '工作爛透了，我受夠了！我要去訓練，我要當個大人物！', '工作爛透了，我受夠了！我要去訓練，我要當個大人物！', 28153),
(154960, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t艾澤洛克準備施放|cFFFF0000|Hspell:258622|h[共鳴脈衝]|h|r！', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t艾澤洛克準備施放|cFFFF0000|Hspell:258622|h[共鳴脈衝]|h|r！', 28153),
(154959, 'zhTW', '小子，這頭獅鷲獸會咬掉你一隻手。', '小子，這頭獅鷲獸會咬掉你一隻手。', 28153),
(154956, 'zhTW', '陰影延伸、信者匯集。我們的時代就要來臨。', '', 28153),
(154955, 'zhTW', '我會賦予你的軀殼意義。', '', 28153),
(154954, 'zhTW', '', '我的力量…我的詛咒…不可能…', 28153),
(154953, 'zhTW', '如果…你回得來的話。', '', 28153),
(154952, 'zhTW', '等我回來再討論什麼是榮譽…還有該怎麼重拾榮譽。', '', 28153),
(154951, 'zhTW', '把他押到監獄去吧。', '', 28153),
(154950, 'zhTW', '你們物種存在，就是為了滿足我。', '', 28153),
(154949, 'zhTW', '這種時候，我說了算。', '', 28153),
(154948, 'zhTW', '這還輪不到聯盟的國王來做決定！', '', 28153),
(154947, 'zhTW', '仔細聽好。這樣殺你毫無榮譽可言。', '', 28153),
(154946, 'zhTW', '父親曾經說過，瓦洛克‧薩魯法爾代表了部落的榮譽…', '', 28153),
(154945, 'zhTW', '不！我要光榮戰死！', '', 28153),
(154944, 'zhTW', '聯盟…停手！', '', 28153),
(154940, 'zhTW', '', '還真是頑強！能活下來見證我的驕傲，就是你們最大的成就。', 28153),
(154939, 'zhTW', '全軍聽令，集中火力攻擊那個怪物！納迦今天絕對別想攻破這道牆！', '', 28153),
(154937, 'zhTW', '<將我的隊伍加入傳奇難度的海嶼遠征佇列。>', '<將我的隊伍加入傳奇難度的海嶼遠征佇列。>', 28153),
(154936, 'zhTW', '<將我的隊伍加入英雄難度的海嶼遠征佇列。>', '<將我的隊伍加入英雄難度的海嶼遠征佇列。>', 28153),
(154935, 'zhTW', '<加入傳奇難度的海嶼遠征佇列。>', '<加入傳奇難度的海嶼遠征佇列。>', 28153),
(154934, 'zhTW', '<加入英雄難度的海嶼遠征佇列。>', '<加入英雄難度的海嶼遠征佇列。>', 28153),
(154933, 'zhTW', '去吧，獸群行者。在達薩亞洛前豎立我的雕像。讓所有人知道獸群的力量，我就會賜予你祝福。', '', 28153),
(154932, 'zhTW', '', '有了這三個卷軸，你在這裡旅行就會輕鬆多了。', 28153),
(154931, 'zhTW', '|TInterface\\ICONS\\Ability_Skyreach_Four_Wind.BLP:20|t %s面對|cFFFF0000$n|r並準備一次|cFFFF0000|Hspell:268403|h[強風斬擊]|h|r！', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s準備對|cFFFF0000$n|r施放|cFFFF0000|Hspell:268932|h[震地躍擊]|h|r！', 28153),
(154930, 'zhTW', '至少…我能站在地面上…戰死…', '', 28153),
(154929, 'zhTW', '外地人，你投得真好！我會專心來對付你。', '', 28153),
(154928, 'zhTW', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t%s遭到|cFFFF0000|Hspell:267702|h[入殮]|h|r！尋找掙扎跡象，找出他的位置！', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t%s遭到|cFFFF0000|Hspell:267702|h[入殮]|h|r！尋找掙扎跡象，找出他的位置！', 28153),
(154927, 'zhTW', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t 你被困在墓穴中了！快點|cFFFF0000|Hspell:267764|h[掙扎]|h|r，讓你的隊友知道你在哪裡！', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t 你被困在墓穴中了！快點|cFFFF0000|Hspell:267764|h[掙扎]|h|r，讓你的隊友知道你在哪裡！', 28153),
(154926, 'zhTW', '我們必須趕回虔信者聖所，一定要阻止賈克拉傑將軍，不能讓他釋放謎思拉克斯！', '', 28153),
(154925, 'zhTW', '你這蠢貨！誰都無法控制謎思拉克斯！', '', 28153),
(154924, 'zhTW', '他會召喚謎思拉克斯，而我們會一起征服艾澤拉斯！', '', 28153),
(154923, 'zhTW', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s準備|cFFFF0000|Hspell:267702|h[入殮]|h|r|cFFFF0000$n|r！', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s準備|cFFFF0000|Hspell:267702|h[入殮]|h|r|cFFFF0000$n|r！', 28153),
(154922, 'zhTW', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s準備對|cFFFF0000$n|r施放|cFFFF0000|Hspell:268932|h[震地躍擊]|h|r！', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s準備對|cFFFF0000$n|r施放|cFFFF0000|Hspell:268932|h[震地躍擊]|h|r！', 28153),
(154921, 'zhTW', '好了！科爾塞克，出來面對你們的罪行吧！', '', 28153),
(154920, 'zhTW', '', '我是來這裡觀察的，我們贊達拉對這些被遺忘者非常感興趣。', 28153),
(154919, 'zhTW', '', '凋零者，告訴你，遇到你我才高興呢。', 28153),
(154918, 'zhTW', '', '我去調查看看為什麼路被封起來了。你可以先想辦法說服士兵散開！', 28153),
(154917, 'zhTW', '收拾裝備，你們這些沒用的廢物。我們還有更重要的事要做。', '收拾裝備，你們這些無用的廢物。我們還有更重要的事要辦。', 28153),
(154916, 'zhTW', '滾開，臭蟲子。', '滾開，你這隻蟲子。', 28153),
(154915, 'zhTW', '閃遠點。', '閃遠點。', 28153),
(154914, 'zhTW', '我剛剛可沒有用全力。', '我下手時可沒那麼重。', 28153),
(154913, 'zhTW', '反正我打你也打夠了。', '反正我打你也打夠了。', 28153),
(154912, 'zhTW', '', '你太注重細節了！一定沒問題的！', 28153),
(154911, 'zhTW', '', '每個東西都有個價格－這些詭異的爬蟲會幫我賺進大把鈔票！只要我能把它們運回卡林多。', 28153),
(154910, 'zhTW', '', '它們需要鮮血才能存活，你要用什麼餵它們？', 28153),
(154909, 'zhTW', '', '你為什麼要把害蟲放進盒子裡？', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154908, 'zhTW', '立刻開放這條道路。', '立刻開放這條道路。', 28153),
(154907, 'zhTW', '拉奇昂，我看得出來，你的勇猛與智慧隨著歲月增長，無信者居然敢這樣對待你和你的後裔，我們會嚴加懲罰。', '', 28153),
(154906, 'zhTW', '想通過這裡得先經過我同意，朋友。', '想通過這裡得先經過我同意，朋友。', 28153),
(154905, 'zhTW', '你聾了啊，$G小子:小姑娘;? 山谷關閉了。', '你聾了啊，$G小子:小姑娘;? 山谷關閉了。', 28153),
(154904, 'zhTW', '防毒面具和荒疫噴灑器。我想知道這些東西有什麼用處。', '防毒面具和荒疫噴灑器。我想知道這些東西有什麼用處。', 28153),
(154903, 'zhTW', '給我一個防毒面具，拜託。', '給我一個防毒面具，拜託。', 28153),
(154902, 'zhTW', '不想惹麻煩就回到後排去，污穢老鼠。', '不想惹麻煩就回到後排去，污穢老鼠。', 28153),
(154901, 'zhTW', '沒文件就不能通過。這是規定。', '沒文件就不能通過。這是規定。', 28153),
(154899, 'zhTW', '我們有艾特文堅實的殼、我的高明策略，再加上你的勇敢跟決心，我們不可能輸的。', '', 28153),
(154898, 'zhTW', '我先去山頂那裡，免得過了這麼多年，拉奇昂都忘記我是誰了。', '', 28153),
(154897, 'zhTW', '', '等我們人員不再受傷，我就會馬上休息。', 28153),
(154896, 'zhTW', '', '我沒事，這些水手離不開我。', 28153),
(154895, 'zhTW', '照這樣下去，你就需要自備一個治療者。你躺在擔架上根本幫不上忙。', '', 28153),
(154894, 'zhTW', '你看起來很累，費瑞雅，你應該休息一下。', '', 28153),
(154893, 'zhTW', '帶著我的法杖，去無信者的鎮壓尖塔那邊，吸取尖塔的能量。', '', 28153),
(154892, 'zhTW', '我跟艾特文先去風險投資公司的地雷區等你。', '', 28153),
(154891, 'zhTW', '媽！米若和$p救了我們！', '媽！米若和$p救了我們！', 28153),
(154890, 'zhTW', '我早就說了，米若才不會拋棄我們咧！她最棒了！', '我早就說了，米若才不會拋棄我們咧！她最棒了！', 28153),
(154889, 'zhTW', '', '基羅，真高興你回來了！外面狀況很糟嗎？你怎麼會有一隻葉殼蟲？取名字了沒？可以讓我取嗎？牠會咬人嗎？', 28153),
(154888, 'zhTW', '米若，先把大家平安帶出去再說，之後有時間我再告訴你。', '', 28153),
(154887, 'zhTW', '實在是…太好玩太刺激了！', '', 28153),
(154886, 'zhTW', '我們要在無信者的援軍到達之前，騎上葉殼蟲離開這裡。', '', 28153),
(154885, 'zhTW', '', '下面是怎麼回事？風心，我們飛過去！', 28153),
(154884, 'zhTW', '', '我們先從布瑞納丹開始找起，希望至少可以在那裡找到派克修士。', 28153),
(154883, 'zhTW', '', '斯陀頌恩領主統領整個谷地。他是所有事情的關鍵，但他已經好幾個月沒有來波拉勒斯了。', 28153),
(154882, 'zhTW', '', '必須先拉攏斯陀頌恩家族。他們控制了浪潮賢者，進而控制了艦隊。', 28153),
(154881, 'zhTW', '', '你們這群無信者混蛋，都給我倒在狐狸人的旗子下面吧！', 28153),
(154880, 'zhTW', '你需要防毒面具，才不會死於荒疫。可以的話，你還能帶上荒疫噴灑器，去協助戰鬥。', '你需要防毒面具，才不會死於荒疫。可以的話，你還能帶上荒疫噴灑器，去協助戰鬥。', 28153),
(154879, 'zhTW', '', '艦隊平安回來之前，庫爾提拉斯應該也幫不上聯盟。', 28153),
(154878, 'zhTW', '', '也要讓關在下面的同胞知道，我們沒有拋下他們。', 28153),
(154877, 'zhTW', '', '讓他們知道自己的死期快到了。', 28153),
(154876, 'zhTW', '妮莎，這樣太冒險了，無信者會發現我們在這裡。', '', 28153),
(154875, 'zhTW', '活該，誰叫那個巫妖之前派兵攻擊我們的斥候。現在我們可以專心對付部落了。', '', 28153),
(154874, 'zhTW', '佐司瓦有女巫，納茲米爾有巫妖。先去解決妖怪的大軍，還有它們背後的力量來源。', '', 28153),
(154873, 'zhTW', '', '妮莎看到你一定會很開心！她在坑洞那邊殺塞斯拉克…她總是這樣。', 28153),
(154872, 'zhTW', '有意思。雖然有人告訴我地精拒絕靠近任何哥布林的科技產品。但至少我們現在知道這東西有多大威力了。', '', 28153),
(154871, 'zhTW', '我們從哥布林那邊搶來一台還在測試階段的裝置。拿去對付鮮血食人妖，測試一下這台機械的威力。', '', 28153),
(154870, 'zhTW', '我的預感告訴我，納迦一定另有圖謀，你一定要多加小心。', '', 28153),
(154869, 'zhTW', '是納迦！牠們在這個世界橫行了這麼久，現在該給牠們一點顏色瞧瞧了。', '', 28153),
(154866, 'zhTW', '自從第三次戰爭以來，我就沒看過有人能這麼勇敢地對抗部落了。做得好。', '', 28153),
(154864, 'zhTW', '你英勇對抗部落的故事會在庫爾提拉斯永遠流傳。', '', 28153),
(154863, 'zhTW', '做得好。希望最後的結果不要像第二次戰爭一樣。', '', 28153),
(154861, 'zhTW', '', '小孩被關在下面那個洞裡。你一定要小心！', 28153),
(154859, 'zhTW', '非常好！部落無人能擋！', '', 28153),
(154858, 'zhTW', '許多斥候為了阻止部落在這裡的行動，都光榮犧牲了。你一定要阻止部落。', '', 28153),
(154857, 'zhTW', '做得好！老兄，我從你身上學到幾招了。', '', 28153),
(154856, 'zhTW', '又解決一個強敵，但是很快又會冒出新的。不過現在，你倒是可以先喘口氣。', '', 28153),
(154855, 'zhTW', '', '我去叫風心來接我們。東方碼頭有個地方可以集合。', 28153),
(154854, 'zhTW', '啊，贏了！老兄，這感覺真好！', '', 28153),
(154853, 'zhTW', '在第三次戰爭的時候，我對部落的戰術瞭若指掌。他們現在就在附近故技重施，非常危險。快消滅他們。', '', 28153),
(154852, 'zhTW', '哈哈！笨蛋，現在搞清楚對手是誰了吧？', '', 28153),
(154851, 'zhTW', '部落在附近的行動讓我想起他們在第二次戰爭的時候用的伎倆。一定要盡快阻止他們，別讓他們得逞。', '', 28153),
(154850, 'zhTW', '老兄！你真的很厲害！', '', 28153),
(154848, 'zhTW', '附近有個強悍的靈魂，快點，去消滅它！', '', 28153),
(154846, 'zhTW', '有個敵人躲在附近，我們上吧！', '', 28153),
(154845, 'zhTW', '我謹代表第七軍團，謝謝你為對抗部落所做的一切。', '', 28153),
(154843, 'zhTW', '在這裡擊敗部落，就可以幫助第七軍團繼續進攻。做得好！', '', 28153),
(154842, 'zhTW', '我們會向安杜因國王報告你對抗部落的英勇事蹟。', '', 28153),
(154838, 'zhTW', '斥候說部落的人就在你附近。立刻突襲的話，一定能殺他們個措手不及。趕快出發！', '', 28153),
(154836, 'zhTW', '我們收到情報，部落大軍就在附近。這可是攻擊的大好機會！', '', 28153),
(154833, 'zhTW', '附近有個目標，迅速攻擊！', '', 28153),
(154832, 'zhTW', '第七軍團發現部落的部隊在附近有些小動作。你負責去干擾他們，打亂他們的計畫！', '', 28153),
(154831, 'zhTW', '附近還潛藏著其他威脅，你知道該怎麼做。', '', 28153),
(154830, 'zhTW', '眾靈說，這一帶有個強大的敵人，我們應該在它造成進一步危害之前，先下手為強。', '', 28153),
(154829, 'zhTW', '附近潛伏著莫大的威脅，快去消滅它！', '', 28153),
(154828, 'zhTW', '做得好！你要不要考慮正式加入第七軍團啊？我們很需要像你這樣的好手！', '', 28153),
(154827, 'zhTW', '做得漂亮。為了安杜因國王！為了聯盟！', '', 28153),
(154826, 'zhTW', '你今天所做的一切對第七軍團還有聯盟很有幫助。', '', 28153),
(154825, 'zhTW', '非常感謝你，第七軍團的所有士兵也很感謝你。', '', 28153),
(154824, 'zhTW', '我會把你的英勇事蹟向安杜因國王報告。', '', 28153),
(154823, 'zhTW', '我們斥候傳來報告，有強大的敵人躲在你附近。消滅目標。', '', 28153),
(154822, 'zhTW', '第七軍團剛剛收到命令，我們必須解決你附近的目標。', '', 28153),
(154821, 'zhTW', '希望他們下次注意點，我們不可能一直在附近等著救他們。這位勇士，謝謝你。', '', 28153),
(154820, 'zhTW', '不死生物困住了一批探勘小隊！趕快去救他們，不然就來不及了！', '', 28153),
(154819, 'zhTW', '從這邊開始就交給我們吧，該來解決古翰了。', '', 28153),
(154818, 'zhTW', '呃，他其實是復活的屍體？那就讓他乖乖躺平吧。', '', 28153),
(154817, 'zhTW', '我記得那個醜到不行的食人妖。祖爾想幹嘛？', '', 28153),
(154816, 'zhTW', '…', '', 28153),
(154815, 'zhTW', '…', '', 28153),
(154814, 'zhTW', '…', '', 28153),
(154813, 'zhTW', '…', '', 28153),
(154812, 'zhTW', '…', '', 28153),
(154811, 'zhTW', '…', '', 28153),
(154810, 'zhTW', '…', '', 28153),
(154809, 'zhTW', '…', '', 28153),
(154808, 'zhTW', '你漏掉一隻了！', '', 28153),
(154807, 'zhTW', '', '這座設施對各種生物體進行實驗，實驗目的為分析古神腐化之解決方案。', 28153),
(154806, 'zhTW', '呃！那到底是什麼玩意啊！', '', 28153),
(154805, 'zhTW', '…', '', 28153),
(154804, 'zhTW', '我聽過恩若司手下的故事，不過從來沒想過會親眼見到。真希望我不會再看見那種東西。', '', 28153),
(154803, 'zhTW', '真是好險，如果我們沒阻止它的話，不知道地表會有多少生命因此受到感染。', '', 28153),
(154802, 'zhTW', '聽起來可行，你們動手處理這件事情的時候，我會看看泰坦還有沒有隱瞞其他祕密。', '', 28153),
(154801, 'zhTW', '…', '', 28153),
(154800, 'zhTW', '啊！我們可沒有那麼多時間，得在疫情變嚴重之前趕快解決古翰才行。', '', 28153),
(154799, 'zhTW', '你找到答案了嗎？', '', 28153),
(154798, 'zhTW', '很好，所以這就是鮮血食人妖到處作亂的原因了。不過，泰坦為什麼要留古神一命？', '', 28153),
(154797, 'zhTW', '看到你真是太高興了。根據我的推測，這裡應該是某種研究設施。', '', 28153),
(154796, 'zhTW', '很好！成功了！只要抓到訣竅，要搞懂這種科技一點也不難。', '', 28153),
(154795, 'zhTW', '到底有完沒完！', '', 28153),
(154794, 'zhTW', '什麼？天啊！防爆門關起來了！趕快大鬧一場，把門弄開！', '', 28153),
(154793, 'zhTW', '等我一下，我來把門打開。', '', 28153),
(154792, 'zhTW', '你成功了！等我一下。我剛取得某種管理員權限，現在我應該可以控制這座設施了。', '', 28153),
(154791, 'zhTW', '我剛剛變成傳說了。', '', 28153),
(154789, 'zhTW', '戰火持續延燒。繼續攻擊我們的敵人！', '', 28153),
(154788, 'zhTW', '附近發現重要目標。我們需要你盡快幫忙處理一下。', '', 28153),
(154787, 'zhTW', '周圍到處都是強敵。消滅敵人，不要手下留情！', '', 28153),
(154780, 'zhTW', '準備應戰。', '準備應戰。', 28153),
(154779, 'zhTW', '', '抵達終點！哈！哈！', 28153),
(154777, 'zhTW', '', '今天是托卡納塔日！如果你想參加的話，去拿個火把，記得先熱身一下。', 28153),
(154774, 'zhTW', '', '勇士，看起來你在爭取贊達拉信任這件事的進展還不錯，我還有其他事要忙。祝你好運。', 28153),
(154772, 'zhTW', '', '歐庫雷斯，去檢查那個傳送門系統，我們需要建立連結部落首都的補給線。', 28153),
(154770, 'zhTW', '盡快到博昂金之殞和我碰面，我們一起偷偷潛進科爾塞克的要塞裡面。', '', 28153),
(154769, 'zhTW', '', '塔蘭姬公主人真好，她告訴我們有座古老的傳送網路也許還能用。', 28153),
(154768, 'zhTW', '', '如果你們準備好消滅艾胥凡的艦隊，就跟我說一聲。', 28153),
(154767, 'zhTW', '', '英雄，你們做得很好，但是波拉勒斯面臨的危機還沒解除。', 28153),
(154766, 'zhTW', '回去工作吧。這些人是跟我一起的。', '回去工作吧。這些人跟我是一夥的。', 28153),
(154765, 'zhTW', '修士，別忘了外人是不可以進圖書館的。', '修士，別忘了外人是不可以進圖書館的。', 28153),
(154764, 'zhTW', '我站在那裡，就在沙灘上，被邪惡的吉爾布林圍攻…這時有個英雄從天而降！喔，又見面了，$n！', '', 28153),
(154763, 'zhTW', '拿走那些卷軸！我打算走那條風景美麗的路回營地，順便分享你的心得。', '', 28153),
(154762, 'zhTW', '不管他們再怎麼掙扎，聯盟只會敗戰連連。', '', 28153),
(154761, 'zhTW', '有些聯盟的走狗到了，想拯救這座城市。去阻止他們徒勞無功的舉動吧。', '', 28153),
(154760, 'zhTW', '我們要用這些彈藥大肆破壞聯盟勢力。', '', 28153),
(154759, 'zhTW', '艾胥凡的部隊在用艾澤萊武器攻擊城市。把那些武器全部搶過來！', '', 28153),
(154758, 'zhTW', '沒有了軍官，庫爾提拉斯人就等著被扔進海裡餵魚吧。', '', 28153),
(154757, 'zhTW', '有個庫爾提拉斯軍官想整隊反攻。把他從戰場上除掉。', '', 28153),
(154756, 'zhTW', '', '很好。這下子你讓部落知道，波拉勒斯絕對不會落入敵人手中！', 28153),
(154755, 'zhTW', '', '部落的人趁著城市遭受攻擊，混進來搶東西了！千萬別讓部落在波拉勒斯大肆掠奪！', 28153),
(154754, 'zhTW', '', '好極了，艾胥凡這下該知道打手不可能打贏你。', 28153),
(154753, 'zhTW', '', '艾胥凡的傭兵正在城鎮上搗亂。快阻止他們！', 28153),
(154752, 'zhTW', '', '做得好，這些海盜才應該被抓起來。', 28153),
(154751, 'zhTW', '', '海盜正在抓平民去當奴隸！快阻止他們！', 28153),
(154750, 'zhTW', '勾拉圖爾…來了…', '', 28153),
(154749, 'zhTW', '整個庫爾提拉斯都難逃一劫。就從你開始！', '', 28153),
(154748, 'zhTW', '蠢蛋！你就哀號到死吧！', '', 28153),
(154747, 'zhTW', 'Oou ph\'magg an\'qov nuq。', '', 28153),
(154746, 'zhTW', 'Ywaq ongg uul\'gwa no AN\'zig！', '', 28153),
(154745, 'zhTW', 'Arwi ryiu yrr oou qam！', '', 28153),
(154744, 'zhTW', 'AN\'zig wgah qam za zyqtahg…', '', 28153),
(154743, 'zhTW', 'AN\'zig wgah zzof！', '', 28153),
(154742, 'zhTW', 'Ywaq fhssh wgah qam！', '', 28153),
(154741, 'zhTW', 'Uulg\'ma zyqtahg yrr！', '', 28153),
(154740, 'zhTW', 'Hnakf ywaq shuul\'wah yawifk yrr uull zz thyzz！', '', 28153),
(154739, 'zhTW', '趁你們還有辦法，快走吧！其他人應該已經發現你們的行動了。', '趁你還有辦法，快走吧！其他人應該發現你的行動了。', 28153),
(154738, 'zhTW', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t你被|cFFFF0000|Hspell:260838|h[鑽頭碎擊]|h|r鎖定了！', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t你被|cFFFF0000|Hspell:260838|h[鑽頭碎擊]|h|r鎖定了！', 28153),
(154737, 'zhTW', 'Og qam shfk wgah iiqaah halahs ma！', '', 28153),
(154736, 'zhTW', '去布瑞納丹找派克修士。把墜飾交給他。我們的行動才正要開始，他會需要你的幫助。', '去布瑞納丹找派克修士。把墜飾交給他。我們的行動才剛開始，他需要你幫助。', 28153),
(154735, 'zhTW', 'Maq oou kaaxth zz ak\'uq yrr sk\'yahf ma！', '', 28153),
(154734, 'zhTW', '我們在走向黑暗的道路上。但我們之中已經有人悄悄埋下了反抗的種子。', '我們走在黑暗的道路上。但我們當中有人已經悄悄埋下反抗的種子。', 28153),
(154733, 'zhTW', 'Zuq ag\'xig ka\'kar za wgah！', '', 28153),
(154732, 'zhTW', 'Puul qi\'plahf ni oou bormax！', '', 28153),
(154731, 'zhTW', 'Xith wgah！', '', 28153),
(154729, 'zhTW', 'Naz raqul！', '', 28153),
(154728, 'zhTW', 'I wgah far\'al zuq ni shn！', '', 28153),
(154727, 'zhTW', '艦隊沒有消失。只是被困在不尋常的風暴裡了。', '艦隊沒有消失。只是被困在不尋常的風暴裡了。', 28153),
(154726, 'zhTW', 'Zuq wgah qam n\'lyeth！', '', 28153),
(154725, 'zhTW', 'Zuq ag\'xig gag wgah naggwa\'fssh！', '', 28153),
(154724, 'zhTW', 'Zuq ag\'xig bormax oou iiqaath！', '', 28153),
(154723, 'zhTW', '你們還好嗎？我早該料到韋德跟籠罩斯陀頌恩家族的陰謀脫不了干係。', '你還好嗎？我早該料到韋德跟籠罩斯陀頌恩家族的陰謀脫不了干係。', 28153),
(154722, 'zhTW', '', '危險？什麼意思？', 28153),
(154721, 'zhTW', '好的，修士。', '好的，修士。', 28153),
(154720, 'zhTW', '拒絕所有訪客。我要招待貴賓。', '拒絕所有訪客。我要招待貴賓。', 28153),
(154719, 'zhTW', '你們大概不知道自己在這裡的處境有多危險。', '', 28153),
(154718, 'zhTW', '跟我來。低頭，別亂看。', '', 28153),
(154717, 'zhTW', '我們的防線仍然太脆弱了。趕快阻止部落，別讓他們靠近防線！', '', 28153),
(154716, 'zhTW', '激流堡還很脆弱，沒辦法直接承受石毀車的攻擊。在部落先鋒靠近前先解決掉他們！', '', 28153),
(154715, 'zhTW', '哈！真是精采的致意！…對帕骷來說。', '', 28153),
(154714, 'zhTW', '加派部隊過來！趕快消滅這些聯盟的敗類，別讓他們繼續前進！', '', 28153),
(154713, 'zhTW', '', '好了！現在登上贊庫爾的台階，向我們的羅亞致上敬意。只要有他們的眷顧，贊達拉就會永存！讓剛克以我們為傲！', 28153),
(154712, 'zhTW', '', '部署軍隊，動作快！絕對不能讓聯盟在這個地方立足！', 28153),
(154711, 'zhTW', '拔出武器！戰鬥的時候到了！', '', 28153),
(154710, 'zhTW', '部隊出動！激流堡的城牆會在部落面前應聲倒下！', '', 28153),
(154709, 'zhTW', '城塞現在正需要支援。阻止敵人的部隊，別讓他們靠近！', '', 28153),
(154708, 'zhTW', '別拖拖拉拉的。斯陀頌恩領主在風暴聖壇那裡等著要用這些圖！', '', 28153),
(154707, 'zhTW', '派部隊上場！把他們的破基地變成廢墟！', '', 28153),
(154706, 'zhTW', '', '浪潮賢者圖書館藏書量在世界上是數一數二的，我們要找的圖書管理員一定就在那裡。', 28153),
(154705, 'zhTW', '', '聯盟往亞格洛克進軍了！想辦法消滅他們，別讓他們攻打要塞！', 28153),
(154704, 'zhTW', '聯盟的士兵啊！擊潰敵人！', '', 28153),
(154703, 'zhTW', '聯軍的士兵們，衝啊！', '', 28153),
(154702, 'zhTW', '部落，戰鬥吧！打敗那些躲在城堡裡的膽小鬼，別讓他們攻破我們的城門！', '', 28153),
(154701, 'zhTW', '', '曲球砲！曲球砲！', 28153),
(154700, 'zhTW', '喔！是曲球砲！曲球砲耶！', '', 28153),
(154699, 'zhTW', '', '這看起來不妙。我們快點離開這裡。', 28153),
(154698, 'zhTW', '跟笨蛋亞倫去圖書館啦！別逼我拿你們填補裂隙。', '', 28153),
(154697, 'zhTW', '快加把勁啊，蠢蛋！別失去控制了！', '', 28153),
(154696, 'zhTW', '', '去就去。我們這就去找！', 28153),
(154695, 'zhTW', '', '與其在這裡浪費時間，幹嘛不去煩亞倫呢？', 28153),
(154694, 'zhTW', '', '把靈魂獻給潮汐。海水的低語會帶來真相！', 28153),
(154693, 'zhTW', '播種', '播種', 28153),
(154692, 'zhTW', '', '吉爾尼斯人，裝好砲彈！進攻！', 28153),
(154691, 'zhTW', '呃，各位先生女士，發動引擎！進攻！', '', 28153),
(154690, 'zhTW', '步槍兵！子彈上膛！進攻！', '步槍兵！舉槍！前進！', 28153),
(154689, 'zhTW', '', '我們可以保證你的船安全無阻，但是你必須付出代價。', 28153),
(154688, 'zhTW', '', '真是太悲慘了。或許以後不該在這裡辦婚禮。', 28153),
(154687, 'zhTW', '', '本來應該是開開心心的典禮，卻被搞砸了！消滅這些搗亂的傢伙，拯救婚禮的賓客！', 28153),
(154686, 'zhTW', '', '所以…我當作你不知道好了？', 28153),
(154685, 'zhTW', '', '你們簡直跟亞倫修士一樣煩人。', 28153),
(154684, 'zhTW', '', '喂，你，這裡誰負責？', 28153),
(154683, 'zhTW', '哼。', '哼。', 28153),
(154682, 'zhTW', '擠出傷口的膿瘡，在痛苦中高歌吧！', '', 28153),
(154681, 'zhTW', '不要逃避瘋狂！反過來吞噬它！', '', 28153),
(154680, 'zhTW', '欣賞腐朽的美妙，坦然接受吧！', '', 28153),
(154679, 'zhTW', '我要讓你們全都化成灰！', '', 28153),
(154678, 'zhTW', '薩爾扎克斯要殲滅敵人！', '', 28153),
(154677, 'zhTW', '你們全都會死！', '', 28153),
(154676, 'zhTW', '你們就面對毀滅的命運吧！', '', 28153),
(154675, 'zhTW', '你們逃不出暗影的掌控！', '', 28153),
(154674, 'zhTW', '滅絕萬物！', '', 28153),
(154673, 'zhTW', '消滅一切！', '', 28153),
(154672, 'zhTW', '你無法抵抗我的命令。', '', 28153),
(154671, 'zhTW', '放棄抵抗，接受瘟疫吧！', '', 28153),
(154670, 'zhTW', '誰都不能阻止古翰…', '', 28153),
(154669, 'zhTW', '腐朽吞噬萬物。', '', 28153),
(154668, 'zhTW', '你的軀殼屬於古翰。', '', 28153),
(154667, 'zhTW', '又多了一個腐朽的生命！', '', 28153),
(154666, 'zhTW', '古翰會再次甦醒！', '', 28153),
(154665, 'zhTW', '你們的世界會終結！', '', 28153),
(154664, 'zhTW', '你們必然會凋零。', '', 28153),
(154663, 'zhTW', '當你喉嚨發癢，當你心中難耐。我一直都在。', '', 28153),
(154662, 'zhTW', '萬物都會凋零，接受，然後轉化吧。', '', 28153),
(154661, 'zhTW', '', '歸源驅動裝置復原。賦予隔離室出入權限。', 28153),
(154660, 'zhTW', '', '控制臺啟動。重啟設施安全系統。', 28153),
(154659, 'zhTW', '對了！有一件很重要的事。呃，兩件。', '', 28153),
(154658, 'zhTW', '', '第一控制臺啟動。重新建立能量矩陣。', 28153),
(154657, 'zhTW', '', '目標「古翰」消滅。無存活樣本。', 28153),
(154656, 'zhTW', '', '腐化降至安全標準。恢復系統結構。', 28153),
(154655, 'zhTW', '最後這顆星球會像膿包爆開，把我的瘟疫散播到全宇宙。', '', 28153),
(154654, 'zhTW', '你們會成為帶原者，讓巨大、潰爛的囊腫包覆全世界。', '', 28153),
(154653, 'zhTW', '真是有活力的宿主，你們會最先接受我的禮物。', '', 28153),
(154652, 'zhTW', '封印，解除；泰坦，消失。腐朽的時代，來臨。', '', 28153),
(154651, 'zhTW', '', '這是為達薩亞洛報仇！你這個骯髒的東西居然毀了那裡！', 28153),
(154650, 'zhTW', '', '現在只能靠我們了，我們要為古翰帶來的這場瘟疫畫上句點。', 28153),
(154649, 'zhTW', '', '警告。此區有大量腐化跡象。隔離程序不允許我繼續前進。', 28153),
(154648, 'zhTW', '太完美了！要徹底打擊風險投資公司，這些地雷應該足夠。', '', 28153),
(154647, 'zhTW', '', '他是怎麼復活的，無所謂，我的刀子會把他送回深淵。', 28153),
(154646, 'zhTW', '有好多地雷可以選。', '', 28153),
(154645, 'zhTW', '', '分析結果顯示高度腐化。模擬分析：古翰先使此樣本重新復活，再使其強化。需要額外測試。', 28153),
(154644, 'zhTW', '', '祖爾？他居然還活著？我親眼看見他死在我父親手上！', 28153),
(154643, 'zhTW', '這些地雷不是用來探測烏龜的！我們應該不會有事才對。', '', 28153),
(154642, 'zhTW', '', '你居然漏掉一隻。', 28153),
(154641, 'zhTW', '', '實驗重點在於古翰之腐化能力是否能復活已經死亡的生物組織。實驗結果不明，樣本已經銷毀。', 28153),
(154640, 'zhTW', '', '觀察正確。這座設施對羅亞進行過無數次實驗，分析古神腐化之解決方案。', 28153),
(154639, 'zhTW', '', '那是什麼啊？看起來它應該曾經是羅亞。', 28153),
(154638, 'zhTW', '', '如果那是古翰的手下，我們就必須制止他，絕對不能讓那一大群那種東西跑到地面。', 28153),
(154637, 'zhTW', '', '發生錯誤。圓盤功能失常。偵測到損毀的資料。', 28153),
(154636, 'zhTW', '', '開始啟動程序。', 28153),
(154635, 'zhTW', '', '請向醫療室報到，以便摘取神經及大腦組織。', 28153),
(154634, 'zhTW', '', '根據在場生命體的大腦皮層活動顯示，所有個體過去都曾與上古之神有所接觸。', 28153),
(154633, 'zhTW', '', '過去經歷中所累積的數據，將有助於此設施進行的研究。', 28153),
(154632, 'zhTW', '', '根據在場生命體的大腦皮層活動顯示，有部分個體過去曾與上古之神有所接觸。', 28153),
(154631, 'zhTW', '', '另外存有九千五百億諾甘位元組的音樂播放清單與自拍圖片。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154630, 'zhTW', '', '七十五諾甘位元組的現存化合物資料。', 28153),
(154629, 'zhTW', '', '圓盤內存有五十諾甘位元組，關於所有已知宇宙生命體的生物學資料。', 28153),
(154628, 'zhTW', '', '現在進入的是資料庫。這裡保存了各種泰坦知識，涵蓋範圍極為廣泛。', 28153),
(154627, 'zhTW', '你們的努力，徒勞無功。沒人能阻擋瘟疫散佈，瘟疫已經深植你們體內。', '', 28153),
(154626, 'zhTW', '', '如果我們沒有成功阻止它的話，地表所有生命都會受到感染。', 28153),
(154625, 'zhTW', '啊，歡迎光臨。最近訪客很少，尤其是圖書館這裡。\n\n需要什麼嗎？', '啊，歡迎光臨。最近訪客很少，尤其是圖書館這裡。\n\n需要什麼嗎？', 28153),
(154624, 'zhTW', '', '警告：病毒隔離防壁破損。受汙染樣本正在接近。有感染風險。', 28153),
(154623, 'zhTW', '', '這間實驗室內部儲存了目前已知宇宙中數千種致命病毒株，依字母排序分類便於查詢。', 28153),
(154622, 'zhTW', '', '現在進入病毒生態學實驗室。', 28153),
(154621, 'zhTW', '', '別忘了維持真言術：盾的效果，才能從贖罪獲益。', 28153),
(154620, 'zhTW', '別忘了維持真言術：盾的效果，才能從贖罪獲得益處。', '', 28153),
(154619, 'zhTW', '', '先對自己施展真言術：盾，然後攻擊目標假人，如此一來也能治療你的傷口。', 28153),
(154618, 'zhTW', '先對自己施展真言術：盾，然後攻擊目標假人，如此一來你的傷口也會恢復。', '', 28153),
(154617, 'zhTW', '', '你對敵人造成傷害時，所有身上有你贖罪效果的人都會受到治療。', 28153),
(154616, 'zhTW', '你對敵人造成傷害時，所有身上有你贖罪效果的人都會受到治療。', '', 28153),
(154615, 'zhTW', '', '某些法術，例如真言術：盾，可以對你的目標施加贖罪效果。', 28153),
(154614, 'zhTW', '你有艦隊失蹤的線索嗎？', '你有艦隊失蹤的線索嗎？', 28153),
(154613, 'zhTW', '某些法術，例如真言術：盾，可以對你的目標施加贖罪。', '', 28153),
(154612, 'zhTW', '但首先要先說服大酋長才行。我需要你幫忙，走吧。', '', 28153),
(154611, 'zhTW', '或許我們該討回以前賣出去的人情。希望這樣可以招募忠誠的士兵加入部落。', '', 28153),
(154610, 'zhTW', '$n，你我都對部落忠心耿耿，如果我們不採取行動，部落絕對撐不過這場戰爭。', '', 28153),
(154609, 'zhTW', '', '計畫是這樣的：啟動控制臺，消滅古翰的瘟疫，所有問題一次解決。', 28153),
(154608, 'zhTW', '', '啟動所有控制臺即可進入古翰的隔離室。可啟動歸源驅動裝置清除樣本。', 28153),
(154607, 'zhTW', '', '如欲摧毀樣本，請重新啟動此區的控制臺。', 28153),
(154606, 'zhTW', '', '我們可沒有那麼多時間慢慢等！我們必須馬上摧毀古翰！', 28153),
(154605, 'zhTW', '', '無法從資料獲得結論。正在擬定其他研究方法，預計於兩千三百六十四個週期後實行。', 28153),
(154604, 'zhTW', '哇喔！這東西真是威力十足！', '', 28153),
(154603, 'zhTW', '', '那你找出來了嗎？', 28153),
(154602, 'zhTW', '好，來點火花…你還是別站這麼近比較好。', '', 28153),
(154601, 'zhTW', '也許我們可以把鎖炸了？把火藥撒上去看看。', '', 28153),
(154600, 'zhTW', '', '收集資料為對抗上古之神的必要方法。古翰的特殊生理結構有可能是解決上古之神危機的關鍵。', 28153),
(154599, 'zhTW', '', '你居然讓那種怪物活在世上？為什麼？', 28153),
(154598, 'zhTW', '', '這裡名為：奧迪爾。此研究設施之目的為囚禁「古翰」並加以研究。', 28153),
(154597, 'zhTW', '', '這到底是哪裡？', 28153),
(154596, 'zhTW', '', '設施系統受損。請多加小心。', 28153),
(154595, 'zhTW', '', '門全部被鎖住了！快關掉那台機器…不然我們全都會被燒成灰！', 28153),
(154594, 'zhTW', '', '警告：偵測到受汙染生命體，啟動焚化爐。', 28153),
(154593, 'zhTW', '', '腐化未能完成擴散到整座設施的主因，一定就是她了。', 28153),
(154592, 'zhTW', '', '吾乃母儀天下、親民和藹、大數據研究機構負責人，簡稱母親大人。', 28153),
(154591, 'zhTW', '', '為了部落！', 28153),
(154590, 'zhTW', '', '那是什麼聲音？', 28153),
(154589, 'zhTW', '', '為了部落！', 28153),
(154588, 'zhTW', 'Lok-tar ogar！為了部落！', '', 28153),
(154587, 'zhTW', '', '劇毒樣本，成功移除。正在開啟消毒室。', 28153),
(154586, 'zhTW', '', '霸王，我接受你的投誠。歡迎你們踏入奧格瑪的大門。', 28153),
(154585, 'zhTW', '', '德拉諾毀滅了，但是我們會在艾澤拉斯打造新的家園。現在，你的敵人就是我們的敵人！', 28153),
(154584, 'zhTW', '撒上火藥', '撒上火藥', 28153),
(154583, 'zhTW', '', '伊崔格跟你的勇士，證明了自身勇敢、高貴的品格。如果這就是部落精神，我們很榮幸能跟部落一起戰鬥。', 28153),
(154582, 'zhTW', '', '挨了機甲一輪轟炸，塔羅克居然沒死？不能讓這個怪物妨礙我們對付古翰！', 28153),
(154581, 'zhTW', '伯昂撒姆第…', '離家…好遠…', 28153),
(154580, 'zhTW', '我知道你很難過，寶貝，可是這裡真的有怪物。我們非走不可。', '我知道你很難過，寶貝，可是這裡真的有怪物。我們非走不可。', 28153),
(154578, 'zhTW', '', '榮耀對我們來說就是一切！大酋長，我們會死守這個承諾。', 28153),
(154577, 'zhTW', '蛋糕再買就有，我們真的該走了。', '蛋糕再買就有，我們真的該走了。', 28153),
(154576, 'zhTW', '我知道你不開心，但是我們真的該走了，寶貝。', '我知道你不開心，但是我們真的該走了，寶貝。', 28153),
(154575, 'zhTW', '寶貝，我們該走了。', '寶貝，我們該走了。', 28153),
(154574, 'zhTW', '', '伊崔格已經跟我提過瑪格哈有多強大。我希望榮耀對你們而言，就像對伊崔格一樣有意義？', 28153),
(154572, 'zhTW', '你毀了我的禮服！這件禮服本來很完美的！這是用奎爾薩拉斯進口的絲綢做的！頭紗是我媽媽留給我的！你好大的膽子！', '你毀了我的禮服！這件禮服本來很完美的！這是用奎爾薩拉斯進口的絲綢做的！頭紗是我媽媽留給我的！你好大的膽子！', 28153),
(154570, 'zhTW', '大酋長，我們成功完成任務了。嘉亞拉霸主答應派兵幫助部落。', '', 28153),
(154569, 'zhTW', '你竟然把外燴主廚殺了！他連開胃菜都還沒上！', '你竟然把外燴主廚殺了！他連開胃菜都還沒上！', 28153),
(154568, 'zhTW', '沙漠再也無法折磨我了。', '終於，期待已久的死亡！', 28153),
(154567, 'zhTW', '竟敢在我的婚禮搗亂，你們全都要付出代價！不管你是誰！', '竟敢在我的婚禮搗亂，你們全都要付出代價！不管你是誰！', 28153),
(154566, 'zhTW', '你知道我花了多少心血才有辦法弄得這麼完美嗎？', '你知道我花了多少心血才有辦法弄得這麼完美嗎？', 28153),
(154565, 'zhTW', '你竟敢破壞我的大日子？！', '你竟敢破壞我的大日子？！', 28153),
(154564, 'zhTW', '終於…解脫了。', '我不要…這樣死去…', 28153),
(154563, 'zhTW', '我已經整整四個月不敢吃麵包了！', '我已經整整四個月不敢吃麵包了！', 28153),
(154562, 'zhTW', '沙漠會吞噬我們所有人。', '死亡是我們唯一的解脫。', 28153),
(154561, 'zhTW', '你到底知不知道這個蛋糕有多貴？！', '你到底知不知道這個蛋糕有多貴？！', 28153),
(154560, 'zhTW', '我可是等了整整兩年才等到這個地方！', '我可是等了整整兩年才等到這個地方！整整兩年！', 28153),
(154559, 'zhTW', '死亡過去無法阻止我…', '', 28153),
(154558, 'zhTW', '我用一根手指就能殺了你！', '', 28153),
(154557, 'zhTW', '', '有新的能量矩陣可供拾取。', 28153),
(154556, 'zhTW', '', '可以拾取能量矩陣了。', 28153),
(154555, 'zhTW', '', '注意，出現新的能量矩陣可供拾取。', 28153),
(154554, 'zhTW', '', '警告，即將發動歸源衝擊，請保持該區域淨空。', 28153),
(154553, 'zhTW', '', '警告，已啟動歸源衝擊程序，請盡速撤離該區域。', 28153),
(154551, 'zhTW', '部落被擊敗了！', '', 28153),
(154550, 'zhTW', '很快地，你就會明白反抗有多愚蠢！', '很快地，你就會明白反抗有多愚蠢！', 28153),
(154549, 'zhTW', '出來，在命運之前屈服吧！', '出來，在命運之前屈服吧！', 28153),
(154548, 'zhTW', '潛伏在深處的那位，會把你們的皮做成披風！', '潛伏在深處的那位，會把你們的皮做成披風！', 28153),
(154547, 'zhTW', '盡管在這可悲的生命裡掙扎吧！無盡的浪潮最後會把你們吞沒！', '盡管在這可悲的生命裡掙扎吧！無盡的浪潮最後會把你們吞沒！', 28153),
(154546, 'zhTW', '', '使用懺悟，治療你的傷口。', 28153),
(154545, 'zhTW', '這到底是什麼火藥啊？喂，你也過來拿一點。', '', 28153),
(154544, 'zhTW', '使用懺悟，治療你的傷口。', '', 28153),
(154543, 'zhTW', '', '對自己或盟友施放懺悟，不會造成傷害，而是會治療。', 28153),
(154542, 'zhTW', '對自己或盟友施放懺悟，不會造成傷害，而是會治療我方。', '', 28153),
(154541, 'zhTW', '殺掉這些怪物！', '殺掉這些怪物！', 28153),
(154540, 'zhTW', '這本來是個很美好的宴會！', '這本來是個很美好的宴會！', 28153),
(154539, 'zhTW', '這是怎麼了？發生什麼事？那些怪物是什麼東西？', '這是怎麼了？發生什麼事？那些怪物是什麼東西？', 28153),
(154538, 'zhTW', '這比喝個爛醉的姻親還要可怕！', '這比喝個爛醉的姻親還要可怕！', 28153),
(154537, 'zhTW', '為什麼會發生這種事？', '為什麼會發生這種事？', 28153),
(154536, 'zhTW', '我們根本就還來不及跟陸行鷹一起熱舞！', '我們根本就還來不及跟陸行鷹一起熱舞！', 28153),
(154535, 'zhTW', '今天本來應該很開心的！', '今天本來應該很開心的！', 28153),
(154534, 'zhTW', '啊啊啊啊啊！', '啊啊啊啊啊！', 28153),
(154533, 'zhTW', '那我們就出發了，大酋長。$n，走吧。', '', 28153),
(154532, 'zhTW', '', '我們的夜裔盟友特別擅長傳送技術。我建議你去了解一下他們的知識，對你的旅程會很有幫助。', 28153),
(154531, 'zhTW', '我拿到卡爾洛斯當年去德拉諾所用的神器，雖然只有一小部分，不過應該有辦法再次打開通道…但我需要幫助才能辦到。', '', 28153),
(154530, 'zhTW', '', '我覺得這個計畫值得考慮。但是去另一個德拉諾的門不是已經關了嗎？', 28153),
(154529, 'zhTW', '我會跟歐雯斯談談。我喜歡我的工作，而我想要繼續作下去－－依我開的條件。', '', 28153),
(154528, 'zhTW', '這代表的是…我了解了。', '', 28153),
(154527, 'zhTW', '嗯… 我不相信艦長會反對與艾胥凡結盟。他看來相當肯定。', '', 28153),
(154526, 'zhTW', '', '勇士，你覺得呢？你準備接受新盟友了嗎？', 28153),
(154525, 'zhTW', '', '瑪格哈的獸人以驍勇善戰聞名。勇者不懼，往後的日子我會需要這些士兵。', 28153),
(154524, 'zhTW', '', '嗯，從另一個世界來的武裝獸人軍隊、訓練有素…迫不及待想消滅聯盟…有意思。', 28153),
(154523, 'zhTW', '當時這位勇士對抗卡爾洛斯跟燃燒軍團，救了德拉諾，也獲得當地獸人的信賴。他們欠部落的人情，我認為該請他們還了。', '', 28153),
(154522, 'zhTW', '大酋長，許多年前部落追殺卡爾洛斯‧地獄吼直至瀕臨毀滅的德拉諾。', '', 28153),
(154521, 'zhTW', '我們將對艾胥凡說不。這裡是艦長的命令。', '我們將對艾胥凡說不。這裡是艦長的命令。', 28153),
(154520, 'zhTW', '真是精緻的衣裝，朋友。需要什麼嗎？', '', 28153),
(154519, 'zhTW', '乾杯，夥伴們。你們看起來有點乾…哈！', '乾杯，夥伴們。你們看起來有點乾…哈！', 28153),
(154518, 'zhTW', '擊破中', '擊破中', 28153),
(154516, 'zhTW', '你不是學生。你打斷我上課最好有很好的理由。', '你不是學生。你打斷我上課最好有很好的理由。', 28153),
(154515, 'zhTW', '<戴洛似乎沒注意到你在場。>', '<戴洛似乎沒注意到你在場。>', 28153),
(154514, 'zhTW', '外來者，你打斷我們太沒禮貌了。', '外來者，你打斷我們太沒禮貌了。', 28153),
(154513, 'zhTW', '快速看過之後，還是不知道我的地精同伴去了哪裡。讓我再多研究一下你收集的情報。如果我發現了什麼，再通知你。', '', 28153),
(154512, 'zhTW', '|cFF0000FF(任務)|r航向斯陀頌恩谷地。', '|cFF0000FF(任務)|r航向斯陀頌恩谷地。', 28153),
(154511, 'zhTW', '警告！警告！入侵警報！入侵警報！', '', 28153),
(154510, 'zhTW', '', '這是你應得的禮物…這件是瑪格哈的傳統護甲。驕傲的穿上它吧！別忘了你的故鄉。Dranosh\'ek mag\'har！', 28153),
(154509, 'zhTW', '', '你擊退敵人，保衛部落，為瑪格哈帶來榮耀。', 28153),
(154508, 'zhTW', '', '回奧格瑪吧，我想表揚你為人民所做的一切努力。', 28153),
(154507, 'zhTW', '', '你在艾澤拉斯打過無數場仗。無論是敵人或盟友都聽過你的名字，都知道你是真正的瑪格哈。', 28153),
(154506, 'zhTW', '', '無論你將來會去什麼地方，別忘了你身體流著德拉諾的血液。Lok-tar ogar！', 28153),
(154505, 'zhTW', '', '我們一定會屢戰屢勝，讓全艾澤拉斯都知道誰才是戰爭的王者！', 28153),
(154504, 'zhTW', '', '部落現在需要我們的力量才能對抗聯盟。我們一定會出手相助。', 28153),
(154503, 'zhTW', '', '我們在葛羅瑪許‧地獄吼的領導下精誠團結，集結成強大、惟一的瑪格哈部族。', 28153),
(154502, 'zhTW', '', '許多年前，這些英雄從遙遠的地方來德拉諾跟我們一起對抗燃燒軍團。', 28153),
(154501, 'zhTW', '', '親愛的洛克漢，贊達拉一定會盡力協助暗矛部族。我一定會盡全力幫助你。', 28153),
(154500, 'zhTW', '我要借用這位勇士。有個交過手的傢伙，從伯昂撒姆第的手中溜走，威脅了我的家園。', '', 28153),
(154499, 'zhTW', '我準備好了。開始進行儀式吧。', '我準備好了。開始進行儀式吧。', 28153),
(154498, 'zhTW', '', '我覺得這裡一定有人知道發生了什麼事。整個艦隊不可能就這樣消失的！', 28153),
(154497, 'zhTW', '我們反而要…打開我們的傳送門讓部落進來？', '', 28153),
(154496, 'zhTW', '我們不應該向艾胥凡投降…', '', 28153),
(154495, 'zhTW', '而我應該相信你，$r？把它給我。', '', 28153),
(154494, 'zhTW', '長官，船長下了命令。他決定不和艾胥凡結盟！', '長官，船長下了命令。他決定不和艾胥凡結盟！', 28153),
(154493, 'zhTW', '你到底是從哪來的？你顯然不是這裡的人。', '', 28153),
(154492, 'zhTW', '', '什麼？讓我看一下。', 28153),
(154491, 'zhTW', '我帶來一些艦長給你的命令，水手長。', '我帶來一些艦長給你的命令，水手長。', 28153),
(154490, 'zhTW', '', '不只是為了艦隊，更是為了整個庫爾提拉斯…塞勒斯常說要：「袪除弊病。」', 28153),
(154489, 'zhTW', '', '你是誰？你究竟要什麼？', 28153),
(154488, 'zhTW', '', '所有庫爾提拉斯的船都會接受他們的祝福。這才是我們的船艦跟外來船不一樣的真正原因。', 28153),
(154487, 'zhTW', '', '我沒看過這麼密集的艾澤萊晶岩。雖然讓人擔心，但也讓人開心。', 28153),
(154486, 'zhTW', '', '艾澤萊晶岩的…元素生物？殺了它，但不要摧毀它。我們要搜集它留下的資源！', 28153),
(154485, 'zhTW', '', '這些食物應該能撐…一下下吧。', 28153),
(154484, 'zhTW', '', '獸人驍勇善戰，食量卻是哥布林的十倍！我們需要補充軍糧，你去殺卡多雷的時候，順便獵幾頭野獸回來。', 28153),
(154483, 'zhTW', '', '像我常說的，在玫瑰長出刺之前就先剪掉它。', 28153),
(154482, 'zhTW', '', '又有一個卡多雷指揮官出現在不該出現的地方。殺了她，我們可不能讓她找援軍來。', 28153),
(154481, 'zhTW', '', '你果然是這個任務的最佳人選。', 28153),
(154480, 'zhTW', '', '薩魯法爾登上了黑海岸和費伍德森林之間的山地。去碎矛谷跟他會合，確保他能順利通過。', 28153),
(154479, 'zhTW', '我們辦到了，大家！海盜之王贊姆蘭現在死了，寶藏是我們的了！', '', 28153),
(154478, 'zhTW', '', '我一直對你很有信心。', 28153),
(154477, 'zhTW', '', '看來卡多雷找了援軍，這會是個嚴峻的挑戰。我期待你凱旋歸來。', 28153),
(154476, 'zhTW', '', '你戰技高超、勇猛無比，勇士，你鼓舞了所有士兵。', 28153),
(154475, 'zhTW', '', '聯盟在搜索黑海岸，想掃蕩我們的據點。堅守陣線！不許退縮！', 28153),
(154474, 'zhTW', '', '戰場上，不是你死就是我活。沒什麼好說的。', 28153),
(154473, 'zhTW', '', '不要心軟！這些野蠻的精靈可不會對你手下留情。', 28153),
(154472, 'zhTW', '', '很好，英雄。我們大大打擊了他們的軍力。', 28153),
(154471, 'zhTW', '', '卡多雷擅長在夜晚作戰。加入戰鬥，在天黑之前解決他們！', 28153),
(154470, 'zhTW', '', '果然沒有辜負我對你的信任。卡多雷很快就會瓦解。', 28153),
(154469, 'zhTW', '', '我們比瑪法里恩的人還多得多！趁還有這個優勢，快點把陣線推進到黑海岸！', 28153),
(154468, 'zhTW', '', '真可憐…連招搖的機會都沒有。', 28153),
(154467, 'zhTW', '', '那名夜精靈指揮官在挑戰我的耐心。解決她。', 28153),
(154466, 'zhTW', '', '想想看，沉睡了幾千年，一覺醒來就是吃敗仗，真悲哀。', 28153),
(154465, 'zhTW', '', '所以這些古樹也想來玩玩？我們來教訓它們。', 28153),
(154464, 'zhTW', '至少情況沒這麼糟。我們不能讓部落拿到它殘存的脂液。', '', 28153),
(154463, 'zhTW', '', '純粹的艾澤萊晶岩元素生物！不知道它危不危險，勇士…我還是希望你多加小心。', 28153),
(154462, 'zhTW', '夜精靈一定會對抗我們到底。', '夜精靈一定會對抗我們到底。', 28153),
(154461, 'zhTW', '', '你用過艾澤萊晶岩炸彈嗎？想看看真正的力量嗎？做好準備吧，勇士，這絕對會讓你大為驚喜。', 28153),
(154460, 'zhTW', '這個樣本真是太棒了！我已經想到好幾種可以應用在鍊金術上的方法了。', '', 28153),
(154459, 'zhTW', '新人應該會嚇到吧。別擔心，這將有助於培養優秀的人格特質！', '', 28153),
(154458, 'zhTW', '', '卡多雷一定會抵抗我們的佔領行動…除非我們擊潰他們的意志。\n\n我們一定要命中要害，讓他們知道自己的未來危在旦夕。一定要讓他們失去某樣東西…或某個人…某個他們非常敬重、非常信任的人。某個希望的象徵。\n\n<黑暗女王瞇起了眼睛。>\n\n瑪法里恩‧怒風一定得死。', 28153),
(154457, 'zhTW', '聽漁夫說看到海裡有奇怪的巨大生物。帶個樣本回來做研究的話會很有幫助的。', '', 28153),
(154456, 'zhTW', '', '聯盟想用攻城武器對付我們？真可笑，讓他們見識部落的厲害吧。', 28153),
(154455, 'zhTW', '最近缺鐵，就算是訓練用的彈藥也不能浪費。我們海軍已經想到一個絕佳方法回收彈藥了。', '', 28153),
(154454, 'zhTW', '', '這些遺址有豐富的自然資源…我們全部都要！勇士，別讓卡多雷阻止我們。', 28153),
(154453, 'zhTW', '', '我們有蠍尾獅可以使喚。帶上幾批炸藥，攻擊那道幽光之壁吧！給瑪法里恩一個問候。', 28153),
(154452, 'zhTW', '', '英雄，射得真精彩！不過去撿砲彈的那個人有得忙了。', 28153),
(154451, 'zhTW', '風險投資公司的薩滿竟然有辦法控制艾澤萊晶岩元素生物！這些小偷、混帳、無賴，根本不該有這種力量。消滅她！', '', 28153),
(154450, 'zhTW', '', '聽起來訓練區正在練習射擊。你應該可以教新兵一兩招火炮射擊的竅門吧。', 28153),
(154449, 'zhTW', '', '你取回的武器會對軍隊很有幫助。做得漂亮。', 28153),
(154448, 'zhTW', '', '無論如何，我們都很需要浪潮賢者…尤其是此時此刻…', 28153),
(154447, 'zhTW', '太棒啦！你大爆冷門，讓很多人的錢包瘦了不少。包括我的。', '', 28153),
(154446, 'zhTW', '', '誰都不知道為什麼艦隊還沒有回來。', 28153),
(154445, 'zhTW', '', '有人說浪潮賢者失去法力了。但我覺得他們只是像艾胥凡那樣爭權奪利。', 28153),
(154444, 'zhTW', '', '那批物資是部落的！別讓它們落入聯盟的手裡！', 28153),
(154443, 'zhTW', '有些分水海寇會在這裡不定期舉辦海盜決鬥大賽，而且他們其實不太在乎什麼樣的人會來參賽。', '', 28153),
(154442, 'zhTW', '', '即使受過訓練，那些黑暗遊俠還是誤判了進攻形勢。凋零者應該找他們談談…', 28153),
(154441, 'zhTW', '', '我們最大的船上一定會有浪潮賢者，他們在暴風中指路，幫忙抵抗巨浪，讓船一帆風順。', 28153),
(154440, 'zhTW', '', '我的黑暗遊俠需要你的協助，勇士。去支援他們！', 28153),
(154439, 'zhTW', '', '勇士，還有工作要交給你。我有一支哥布林小隊準備要去掃蕩殘存的敵人。', 28153),
(154438, 'zhTW', '搞什麼…竟然把這個世界的生命之血拿去餵巨魔，還說這樣可以變聰明？！呃…怎麼可能成功…不可能吧？最好別讓他們試，快去把他們揍飛！\n！', '', 28153),
(154437, 'zhTW', '真是傑作！這一定能吸引所有人的目光！', '', 28153),
(154436, 'zhTW', '', '艾澤萊晶岩火藥桶掉到海裡面了！快點撈上來，別讓它們沉下去！', 28153),
(154435, 'zhTW', '你之前拍的那些照片我都用光啦。如果你最近有空，幫忙再去拍一點回來。', '', 28153),
(154434, 'zhTW', '', '營地暫時安全了，但是不能掉以輕心。', 28153),
(154433, 'zhTW', '風險投資公司的首席武器研究員現在人在這裡！我們找他找好久了。幫我去把他揍飛！', '', 28153),
(154432, 'zhTW', '', '真想讓你看看艦隊。就算是像你這樣的冒險者也會覺得很厲害！', 28153),
(154431, 'zhTW', '瞧，這就是遠近馳名的波拉勒斯！從暗巷幫派到貴族鬥爭，應有盡有。你知道嗎，諾姆瑞根從來沒有這種問題。', '', 28153),
(154430, 'zhTW', '我已經決定把附近幾個當地景點一起放在廣告裡面。先從這個城市開始吧。', '', 28153),
(154429, 'zhTW', '', '聯盟的破壞者混進來了！把他們找出來，讓他們付出代價！', 28153),
(154428, 'zhTW', '', '好了，該使用渡船通行證了！', 28153),
(154427, 'zhTW', '風險投資公司用一大筆錢，挖走我的首席武器研究員。人往高處去，我不怪他跳槽，但還是必須請你殺了他，沒問題吧？', '', 28153),
(154426, 'zhTW', '太美了！你知道，照片最棒的一點就是，上頭不會有馬尿味。', '', 28153),
(154425, 'zhTW', '諾爾威頓領主希望在下一期噴泉月刊幫他美麗的莊園放上醒目的廣告。我當然不會拒絕這種生意。', '', 28153),
(154424, 'zhTW', '風險投資公司不斷拿艾澤萊晶岩往巨魔嘴巴塞，說這樣可以讓巨魔變聰明。我覺得行不通，不過…，你還是去處理一下吧。小心駛得萬年船嘛。', '', 28153),
(154423, 'zhTW', '', '月井的精華應該能在戰鬥中好好派上用場。以後也要讓卡多雷再也碰不到月井。', 28153),
(154422, 'zhTW', '', '卡多雷會在戰鬥之後，用月井來恢復能量。快去吸收月井的能量，然後…毀掉月井。明白了嗎？', 28153),
(154421, 'zhTW', '幸好有你！再拖下去，我身為度假村主人的名譽就要受損了。', '', 28153),
(154420, 'zhTW', '去那裡的時候要小心，泰莉亞。我不相信那些戴著兜帽的賢者。', '', 28153),
(154419, 'zhTW', '根據小道消息，風險投資公司已經研發出控制艾澤萊晶岩元素生物的方法。我們得阻止他們。這邊的「我們」指的是「你」。', '', 28153),
(154418, 'zhTW', '', '我會讓附魔師在這些月亮石裡灌注艾澤萊晶岩的力量，這股力量對部落很有用處！', 28153),
(154417, 'zhTW', '', '卡多雷從那些月亮石的吊飾中吸取能量。想辦法讓他們用不了那些東西。', 28153),
(154416, 'zhTW', '', '很好，勇士。我們會好好運用這批艾澤萊晶岩。', 28153),
(154415, 'zhTW', '', '艾澤萊晶岩出現在黑海岸的廢墟了。全部搶過來，連一點碎片都不留給聯盟！', 28153),
(154414, 'zhTW', '', '做得很好。讓瑪法里恩確實感受到我們是來真的。', 28153),
(154413, 'zhTW', '', '這些幽光就像蟲子一樣脆弱。消滅它們的光芒，黑暗很快就會籠罩這片天空。', 28153),
(154412, 'zhTW', '真是災難！噴泉突然失控，開始攻擊客人！', '', 28153),
(154411, 'zhTW', '', '愚蠢！你們贏不了古翰的！你們的力量毫無用處！', 28153),
(154410, 'zhTW', '', '這應該夠我們的廚師煮出一些美味的食物了，謝謝你。', 28153),
(154409, 'zhTW', '', '我的德魯伊同袍…食量跟熊一樣大。這件事不輕鬆，但是我們需要補給。你能幫我們嗎？', 28153),
(154408, 'zhTW', '該幹活了，火力全開！', '', 28153),
(154407, 'zhTW', '哈哈！很好。', '哈哈！很好。', 28153),
(154406, 'zhTW', '真沒禮貌。', '真沒禮貌。', 28153),
(154405, 'zhTW', '你為什麼這麼做？', '你為什麼這麼做？', 28153),
(154404, 'zhTW', '全體羅亞在上，你以為你在做什麼？', '全體羅亞在上，你以為你在做什麼？', 28153),
(154403, 'zhTW', '把它打掉！', '把它打掉！', 28153),
(154402, 'zhTW', '讓開讓開！大砲來了！', '', 28153),
(154401, 'zhTW', '這樣就八份了！是一整個錢幣，有錢人！', '', 28153),
(154400, 'zhTW', '海盜有個習慣，會把寶藏分成八份。如果你能獨吞八份那就太幸運了！自由港應該到處都有寶藏吧。', '', 28153),
(154399, 'zhTW', '這就是貪吃的懲罰。今晚吃涼拌海蜇皮怎麼樣？哈哈！', '', 28153),
(154398, 'zhTW', '有隻超大的水母把自由港附近海域當成自己家。不管我們朝牠發射多少把魚叉，牠就是不肯走！', '', 28153),
(154397, 'zhTW', '你把恐怖船長凡德格里姆殺了，他的靈魂安息了！想想那些你剛解除詛咒的寶藏！', '', 28153),
(154396, 'zhTW', '這附近所有海岸都知道凡德格里姆船長有多恐怖。聽說他貪得無厭，就算死了還在到處掠奪。', '', 28153),
(154395, 'zhTW', 'Iggksh ywaq ag\'rr ni ky！', '', 28153),
(154394, 'zhTW', 'Ah\'shel ywaq qam yrr woth\'gl！', '', 28153),
(154393, 'zhTW', '這樣連第八份都到手了！錢幣也完整了！我們發財啦！', '', 28153),
(154392, 'zhTW', 'Za ag\'rr wgah thyzz zuq！', '', 28153),
(154391, 'zhTW', '海盜有個習慣，會把寶藏分成八份。如果你能獨吞八份那就太幸運了！自由港應該到處都有寶藏吧。', '', 28153),
(154390, 'zhTW', '誰叫牠這麼貪吃。今晚吃涼拌海蜇皮怎麼樣？', '', 28153),
(154389, 'zhTW', '有隻超大的水母把自由港附近海域當成自己的家。不管我們朝牠發射幾把魚叉，牠就是不肯走！', '', 28153),
(154388, 'zhTW', 'Ga ag\'rr ez AN\'zig wgha kyth zuq！', '', 28153),
(154387, 'zhTW', '你把恐怖船長凡德格里姆殺了，他的靈魂終於安息了！想想那些解除詛咒的寶藏！', '', 28153),
(154386, 'zhTW', '凡德格里姆船長的威名傳遍附近所有海岸。聽說他極其貪婪，就算他死了也還在四處掠奪。', '', 28153),
(154385, 'zhTW', '不對…應允我的未來不是這樣才對…', '', 28153),
(154384, 'zhTW', '古翰的鮮血在我體內流動，臣服於我的力量之下吧！', '', 28153),
(154383, 'zhTW', '我看過太可怕的事…', '沒想到你人真好。', 28153),
(154382, 'zhTW', '我要用這招毀滅你們！', '', 28153),
(154381, 'zhTW', '謝謝你，我就快撐不下去了。', '謝謝，我要趕快開溜！', 28153),
(154380, 'zhTW', '古翰的力量會毀滅你們！', '', 28153),
(154379, 'zhTW', '親眼見識你的末日，然後絕望吧！', '', 28153),
(154378, 'zhTW', '起來吧，被我選上的人啊！我們會用鮮血征服一切！', '', 28153),
(154377, 'zhTW', '從我的鮮血中復甦，擊垮那群弱者！', '', 28153),
(154376, 'zhTW', '我的同胞，來！來享用迷途之人的血肉！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154375, 'zhTW', '把你們的鮮血還給我！', '', 28153),
(154374, 'zhTW', '古翰！請接受這份鮮血祭品！', '', 28153),
(154373, 'zhTW', '你們，沒有未來可言。', '', 28153),
(154372, 'zhTW', '太弱了，跟我說的一樣。', '', 28153),
(154371, 'zhTW', '就跟我預言的一樣！', '', 28153),
(154370, 'zhTW', '蠢貨！來啊！我已經看到你們的死相了。', '', 28153),
(154369, 'zhTW', '在我很小的時候，我的母親就過世了，我父親獨自撫養我長大，他曾是一名水手，出海的時候，總是會留給我一朵海莖草的花。', '在我很小的時候，我的母親就過世了，我父親獨自撫養我長大，他曾是一名水手，出海的時候，總是會留給我一朵海莖草的花。', 28153),
(154368, 'zhTW', '', '注意。出現黑暗投影。', 28153),
(154367, 'zhTW', '', '注意。虛無載體安全措施已失效。', 28153),
(154366, 'zhTW', '', '英雄，你的行為很高尚。', 28153),
(154365, 'zhTW', '', '注意。虛無能量已達危險標準。', 28153),
(154363, 'zhTW', '', '警告。已複製更多奈幽。', 28153),
(154362, 'zhTW', '萬物重歸平衡了，Anu\'dorini talah！', '', 28153),
(154361, 'zhTW', '有敵人潛伏在暗影中，但是伊露恩的月光會讓他們無所遁形。打倒他們吧。', '', 28153),
(154360, 'zhTW', '', '警告。已複製更多異種蠍。', 28153),
(154359, 'zhTW', '呿！該死的東西！海莖草對我來說，就是讓水手再也回不了家，讓貨物永遠躺在海底。', '呿！該死的東西！海莖草對我來說，就是讓水手再也回不了家，讓貨物永遠躺在海底。', 28153),
(154358, 'zhTW', '', '這個世上沒有謎思拉克斯的容身之地。', 28153),
(154357, 'zhTW', '', '伊露恩眷顧你，英雄。你閃耀著星辰的光輝。', 28153),
(154356, 'zhTW', '', '勇士，我的弓箭手需要你的協助，去幫他們一下吧！', 28153),
(154355, 'zhTW', '', '必須終結這場戰爭。', 28153),
(154354, 'zhTW', '', '我會一直眷顧著你。', 28153),
(154353, 'zhTW', '', '讀取完成。關閉圓盤。', 28153),
(154352, 'zhTW', '', '你消滅了敵人，而且沒弄壞我的工程武器！衝著這點，你值得更多表揚。', 28153),
(154351, 'zhTW', '', '一定要恢復秩序。', 28153),
(154350, 'zhTW', '', '人各有所屬。我屬於這裡。', 28153),
(154349, 'zhTW', '', '我很虛弱，不過我確實存在。', 28153),
(154348, 'zhTW', '', '你之前有搭過嗎？抓緊了，你會嚇一跳的！', 28153),
(154347, 'zhTW', '', '讀取圓盤。載入損毀資料。', 28153),
(154346, 'zhTW', '我會盡量多派一些士兵到這裡來。希望他們能抵擋這波攻勢…我們沒辦法雙線同時作戰。', '', 28153),
(154345, 'zhTW', '我感覺到北邊有騷動。怎麼回事？難道是部落翻山越嶺來攻打我們嗎？快去看看！', '', 28153),
(154344, 'zhTW', '', '你看起來有點黑，英雄。事情不太順利嗎？', 28153),
(154343, 'zhTW', '', '就算在水底，這些艾澤萊晶岩火藥桶還是很危險。快去引爆，別讓它們浮上水面。小心一點，千萬別炸到自己，好嗎？', 28153),
(154342, 'zhTW', '', '資料矩陣超載。讀取多個圓盤。', 28153),
(154341, 'zhTW', '海莖草是嗎？有些船員確定他們的另一半會在他們出航時偷人，那些人這麼做也無可厚非，畢竟只要船員一出事，他們的生活就立刻沒有著落了。', '海莖草是嗎？有些船員確定他們的另一半會在他們出航時偷人，那些人這麼做也無可厚非，畢竟只要船員一出事，他們的生活就立刻沒有著落了。', 28153),
(154340, 'zhTW', '', '我一直都對你很有信心。', 28153),
(154339, 'zhTW', '', '部落大軍人數眾多，而且實力不容小覷。這傢伙看起來特別…難纏。英雄，你要小心一點。', 28153),
(154338, 'zhTW', '', '讀取圓盤。載入尤格薩倫資料。', 28153),
(154337, 'zhTW', '', '讀取圓盤。載入克蘇恩資料。', 28153),
(154335, 'zhTW', '', '部落的破壞者混進來了！找出那些人，好好回敬他們一番！', 28153),
(154334, 'zhTW', '', '不得不說…你瞄得很準，英雄。就連我手下的哨兵都應該跟你多學幾招。', 28153),
(154333, 'zhTW', '', '該以牙還牙了！我們必須破壞部落的石毀車，把他們趕回貧瘠之地那鳥不生蛋的老家！', 28153),
(154332, 'zhTW', '', '伊露恩為你而笑，英雄。我也一樣。', 28153),
(154331, 'zhTW', '', '部落想偷走月井的精華！千萬不能讓他們的髒手玷污我們神聖的泉水！', 28153),
(154330, 'zhTW', '', '叫那些部落混帳繼續待在他們的荒地裡就好，不要來靠近我們的森林。', 28153),
(154329, 'zhTW', '', '部落在梣谷邊界建立據點。快去召集看守這片森林的德魯伊！', 28153),
(154328, 'zhTW', '', '打得好，英雄。繼續保持熱忱…', 28153),
(154327, 'zhTW', '', '部落軍隊正在盜取我們領地上的資源！快阻止他們…別讓部落掠奪我們神聖的林地。', 28153),
(154326, 'zhTW', '', '就算死了數千年仍然技藝精湛。你打贏他們很厲害。', 28153),
(154325, 'zhTW', '', '那…那是神王達薩的第一護衛隊！他們可不好對付！', 28153),
(154324, 'zhTW', '哈哈！看來你把不死食人妖變成慘死食人妖了！做得好。', '', 28153),
(154323, 'zhTW', '那些不死食人妖看起來特別厲害。小心！', '', 28153),
(154322, 'zhTW', '關於海莖草你能告訴我什麼？', '關於海莖草你能告訴我什麼？', 28153),
(154321, 'zhTW', '', '英雄，這些應該就夠了。我們會記住你今天的貢獻。', 28153),
(154320, 'zhTW', '', '部落有艾澤萊晶岩武器了。我們去看看能不能搶過來，好嗎？', 28153),
(154319, 'zhTW', '…呃，石之大廳不算。', '', 28153),
(154318, 'zhTW', '哼。矮人做的東西才不會這樣一天到晚出錯。', '', 28153),
(154317, 'zhTW', '', '太好了！我會讓鍊金師把艾澤萊晶岩藏在部落找不到的地方。', 28153),
(154316, 'zhTW', '呸，食人妖的爛工藝。那個魔像故障了。打到它乖乖聽話為止！', '', 28153),
(154315, 'zhTW', '', '我們一定要比賈克拉傑早一步找到喬瓦芭。', 28153),
(154314, 'zhTW', '', '祖爾的黑暗魔法已經腐化了這個守護者。快阻止它的狂暴行為，我們才能修理它。', 28153),
(154313, 'zhTW', '', '祖爾…你對這個神聖之地的所作所為不可饒恕。', 28153),
(154312, 'zhTW', '', '哈魯，再見。好好安息吧。', 28153),
(154311, 'zhTW', '', '啊，武器大師哈魯…他負責訓練父親，還有父親的父親。他的工作已經結束了。讓他憂傷的靈魂獲得平靜。', 28153),
(154310, 'zhTW', '哈！看來你幫他紮紮實實地上了一課！', '', 28153),
(154309, 'zhTW', '當年為贊達拉皇室負責武術訓練的戰士還在陵寢徘迴。讓他安息吧！', '', 28153),
(154308, 'zhTW', '', '我的弓箭手應該能解決剩下的敵人。謝謝你，勇士，你扭轉了這場戰鬥。', 28153),
(154307, 'zhTW', '', '敵人從北邊向我們打來了。勇士，給敵人迎頭痛擊的時候到了。', 28153),
(154306, 'zhTW', '讓他們通過！', '', 28153),
(154305, 'zhTW', '', '就快結束了！亞昆達的聲音迴盪在我腦中。', 28153),
(154304, 'zhTW', '', '我會盡可能去恢復亞昆達的記憶，但你要幫忙壓制過程中甦醒出來的東西。', 28153),
(154303, 'zhTW', 'Ywaq ongg an\'qov i lal halahs nuq。', '', 28153),
(154302, 'zhTW', 'Ywaq mh\'naus wgah zaix zyqtahg。', '', 28153),
(154301, 'zhTW', '摩詹波會要你…付出代價…', '', 28153),
(154300, 'zhTW', '', '這…這裡是哪裡？我怎麼會在這裡？', 28153),
(154299, 'zhTW', 'Oou thyzz lal ak\'uq qwaz Zuq shkul ma sk\'tek…', '', 28153),
(154298, 'zhTW', '', '他們滿神秘的，但對庫爾提拉斯很重要。他們為漁業帶來豐收，讓谷地農田雨水充沛。', 28153),
(154297, 'zhTW', '', '這裡的人都會遵從大海指引，就像有人遵從聖光一樣。浪潮賢者跟大海之間的聯繫更深。', 28153),
(154296, 'zhTW', '', '照理說，我應該把風心借給你。但是浪潮賢者規定訪客只能搭船。', 28153),
(154295, 'zhTW', '', '塞勒斯，沒事的，我會保護自己。而且我跟聯盟特使在一起呢！', 28153),
(154294, 'zhTW', 'Oou yyqzz ez thyzz phquathi zuq！', '', 28153),
(154293, 'zhTW', 'Oou gul\'kafh lal lwhuk！', '', 28153),
(154292, 'zhTW', 'Qam oou iilth ez i awtgsshu amun on\'ma！', '', 28153),
(154291, 'zhTW', 'Log\'loth w\'oq Ongg！', '', 28153),
(154290, 'zhTW', '', '黑海岸的廢墟出現了艾澤萊晶岩，不能讓部落搶先拿到！', 28153),
(154289, 'zhTW', 'W\'oq uhn\'agth ez qam Shandai！', '', 28153),
(154288, 'zhTW', 'Awtgssh shn ongg shg\'ullwaq！', '', 28153),
(154287, 'zhTW', 'Zuq ag\'xig bormaz ag\'thyzak！', '', 28153),
(154286, 'zhTW', '謝謝你！', '謝謝你！', 28153),
(154285, 'zhTW', 'Za qualar ag\'xig za al\'tha！', '', 28153),
(154284, 'zhTW', '這點報酬也未免太少了！', '這點報酬也未免太少了！', 28153),
(154283, 'zhTW', '啊啊啊啊啊啊啊啊啊！', '啊啊啊啊啊啊啊啊啊！', 28153),
(154282, 'zhTW', '謝謝你救了我！', '謝謝你救了我！', 28153),
(154281, 'zhTW', '我還以為我要被做成香腸了！', '我還以為我要被做成香腸了！', 28153),
(154280, 'zhTW', 'Oou vwahuHn ag\'xig shfk zuq！', '', 28153),
(154279, 'zhTW', '謝謝啦！', '謝謝啦！', 28153),
(154278, 'zhTW', 'I ongg za ywaq qvsakf。', '', 28153),
(154277, 'zhTW', 'Vwah oou kaaxth zz ywaq iiyoq Ag\'xlg fhssh I on\'ma。', '', 28153),
(154276, 'zhTW', 'Za awtgsshu wgah uulg\'ma ywaq zaix。', '', 28153),
(154275, 'zhTW', 'Qam oou uhnish kyth zuq Ongg za fhssh as\'rr。', '', 28153),
(154274, 'zhTW', 'Ywaq zuq ywag shn\'ma Bo\'al za qwor。', '', 28153),
(154273, 'zhTW', 'Oou qam puul zyqtahg ywaq vorzz Qam ma shn\'ma。', '', 28153),
(154272, 'zhTW', 'Oou shath\'yar lwhuk shn\'ma yrr shandi agth fhssh。', '', 28153),
(154271, 'zhTW', '只要靈魂平靜下來，森林也會安定下來。感謝你。', '', 28153),
(154270, 'zhTW', '這些靈魂只剩下軀殼了。勇士，用你的撫觸來溫暖它們，讓它們重獲平靜吧。', '', 28153),
(154269, 'zhTW', '他們叫我妖術之王可是有原因的。', '', 28153),
(154268, 'zhTW', '拿著我的魔法棒，去把那些祭司變成有趣一點的東西吧。', '', 28153),
(154267, 'zhTW', '這樣你就覺得過份？去看看其他羅亞都要求信徒做什麼吧。', '', 28153),
(154266, 'zhTW', '如果我們不去阻止這場腐化，誰去呢？', '如果我們不去阻止這場腐化，誰去呢？', 28153),
(154265, 'zhTW', '剛克的德魯伊太嚴肅了。去祭壇玩點惡作劇，讓他們放鬆點。對了，他們可能會想殺了你。', '', 28153),
(154264, 'zhTW', '要是它繼續擴散…艾澤拉斯就完了。', '要是它繼續擴散…艾澤拉斯就完了。', 28153),
(154263, 'zhTW', '大自然發出痛苦的悲鳴…要怎麼才能阻止這場災難？', '大自然發出痛苦的悲鳴…要怎麼才能阻止這場災難？', 28153),
(154262, 'zhTW', '我們的力量完全沒用…要怎麼才能治療這個星球呢？', '我們的力量完全沒用…要怎麼才能治療這個星球呢？', 28153),
(154261, 'zhTW', '', '這趟好玩吧！你們兩個打得好極了。', 28153),
(154260, 'zhTW', '', '靈龍不太習慣背上有鞍具，路途會有點顛簸，你得忍耐一下。騎上靈龍，指揮牠們攻擊。', 28153),
(154259, 'zhTW', '我要享用你心中的恐懼！', '', 28153),
(154258, 'zhTW', '鐵爐堡的支援部隊！向敵人的基地前進！', '', 28153),
(154257, 'zhTW', '擊敗亞格洛克，為了阿拉索！為了激流堡！為了聯盟！', '', 28153),
(154256, 'zhTW', '', '你戰鬥時就像贊達拉傳說故事裡的人物。太厲害了。', 28153),
(154255, 'zhTW', '', '你已經多次證明了自己的價值。做得好。', 28153),
(154252, 'zhTW', '', '謝謝你，我們的人民都可以平安度日了。', 28153),
(154251, 'zhTW', '', '既然敵人死了，我們就可以繼續完成計畫了。', 28153),
(154246, 'zhTW', '', '藏身地點就在前面。到了那裡至少就能暫時喘口氣。', 28153),
(154245, 'zhTW', '', '我希望再也不要遇到那種敵人了。', 28153),
(154244, 'zhTW', '', '羅亞早就預言過你會獲勝，真高興預言成真了。', 28153),
(154243, 'zhTW', '', '你們部落聽到你把威脅解決了，應該也會很高興。', 28153),
(154242, 'zhTW', '', '我早就知道，那個敵人根本不是你的對手。', 28153),
(154240, 'zhTW', '感受身體的抽搐，我存在於你的畏懼裡。', '', 28153),
(154239, 'zhTW', '', '我收到情報，這附近有強大的敵人想對你不利。你也別對他仁慈了。', 28153),
(154238, 'zhTW', '', '部落的戰士說，你附近有麻煩的敵人。消滅敵人，減輕盟友的負擔。', 28153),
(154237, 'zhTW', '', '你們派出的部落斥候回報說這附近有強大的敵人，他們建議我們「迅速殺敵」。我也同意這麼做。', 28153),
(154234, 'zhTW', '納茲米爾的這群野蠻人好像怎麼都殺不完。謝謝你幫忙減少他們的人數。', '', 28153),
(154232, 'zhTW', '哈！你是天生好手！已經好久沒看到技巧這麼好的人了！', '', 28153),
(154230, 'zhTW', '鮮血食人妖正在攻打城門，騎著戰獸去對付那群野蠻人吧。', '', 28153),
(154228, 'zhTW', '今天沒工作給你。粗脖幫的人都去滑雪放鬆了。去抓隻蓬企鵝，一起上滑坡吧！', '', 28153),
(154225, 'zhTW', '', '小心。你附近有強敵。我們必須趁狀況還沒惡化，盡快殺死敵人。', 28153),
(154224, 'zhTW', '英雄，伊露恩讚賞你的壯舉。', '', 28153),
(154223, 'zhTW', '', '羅亞對我低語：這附近有強大的敵人，應該要從艾澤拉斯消失。', 28153),
(154222, 'zhTW', '女妖之王的攻勢毫不留情。淨化這片森林，驅散她在這裡的黑暗氣息！', '', 28153),
(154221, 'zhTW', '', '我的斥候回報附近有強大的敵人。趁敵人還沒造成重大傷亡，先下手為強。', 28153),
(154220, 'zhTW', '接下來交給我的部隊處理就好。謝謝你幫他們爭取時間重整隊伍。', '', 28153),
(154219, 'zhTW', '', '保持警戒。我感覺到附近有邪惡的東西。你最好趁他還沒找上你之前先出手！', 28153),
(154218, 'zhTW', '威脅暫時緩解，古樹重獲平靜了。', '', 28153),
(154217, 'zhTW', '', '這附近有致命的敵人。趁還沒有盟友傷亡，趕快把他們解決掉。', 28153),
(154216, 'zhTW', '只要不是贊達拉人就殺無赦！', '', 28153),
(154215, 'zhTW', '部落的行為驚動了古樹。趕走邪惡的敵人，讓森林恢復平靜。', '', 28153),
(154213, 'zhTW', '你今天的協助讓我們有了喘息的機會。', '', 28153),
(154212, 'zhTW', '這片宏偉森林裡的樹木斷折毀傷，痛苦哀鳴，都是因為部落朝我們的土地節節進逼。絕對不能再讓部落繼續推進！', '', 28153),
(154211, 'zhTW', '路上小心。', '路上小心。', 28153),
(154210, 'zhTW', '沙漠會吞噬弱者。', '沙漠會吞噬弱者。', 28153),
(154209, 'zhTW', '不要相信任何人。', '你最好小心一點。', 28153),
(154208, 'zhTW', '誰都不應該落到這個下場。', '誰都不應該落到這個下場。', 28153),
(154207, 'zhTW', '你需要什麼？', '這裡什麼人都歡迎。', 28153),
(154205, 'zhTW', '你好啊。', '你好啊。', 28153),
(154204, 'zhTW', '', '我還能聽到你的聲音…主人…', 28153),
(154203, 'zhTW', '我的話語會融化你的心智。', '', 28153),
(154202, 'zhTW', '順從嗜血的堅決，啜飲他們的鮮血。', '', 28153),
(154201, 'zhTW', '去找你的盟友，分享這份禮物。', '', 28153),
(154200, 'zhTW', '做得非常好，現在動作快，把剩下的無信者都解決掉！', '', 28153),
(154199, 'zhTW', '腐敗在你的身體流竄，隨著血液擴散。', '', 28153),
(154198, 'zhTW', '去從無信者巫士身上搶個裝置回來，然後充好電。我會好好獎勵你的。', '', 28153),
(154197, 'zhTW', '我們的巫士發現神廟裡面有異常強大的電流在流竄。', '', 28153),
(154196, 'zhTW', '開始這場千喉盛宴吧！', '', 28153),
(154195, 'zhTW', '太好了！現在可以來處理瑟沙利斯之心了。', '', 28153),
(154194, 'zhTW', '把那些聖物帶回來給我，我會給你獎勵。', '', 28153),
(154193, 'zhTW', '孩子，快來享用大餐！', '', 28153),
(154192, 'zhTW', '我知道無信者把好幾個我們族人的聖物藏了起來，地點就在神廟中心地帶前面的廣場某處。', '', 28153),
(154191, 'zhTW', '過來！腐敗奴僕！吃掉他們！', '', 28153),
(154190, 'zhTW', '這個樣本真是不錯！現在趕快把神廟剩下的無信者都解決掉！', '', 28153),
(154189, 'zhTW', '聽說有某種稀有的葉殼蟲在神廟築巢。把幼蟲帶回來給我看看，我會獎勵你。', '', 28153),
(154188, 'zhTW', '我的疫病無人能擋！', '', 28153),
(154187, 'zhTW', '我的荒疫無人能消除！', '', 28153),
(154186, 'zhTW', '就連泰坦也救不了你！', '', 28153),
(154185, 'zhTW', '你逃不過遭受感染的命運！', '', 28153),
(154184, 'zhTW', '封印破除，末日具現。過來，接受我的禮物。', '', 28153),
(154183, 'zhTW', '這些工人非常感謝你。你真的救了他們一命。', '', 28153),
(154182, 'zhTW', '腐敗…已經在你體內生根…', '', 28153),
(154181, 'zhTW', '那些女巫又入侵鑿刻匠港口了。趕快去救那些工人，別讓他們被做成香腸！', '', 28153),
(154180, 'zhTW', '', '先人的靈魂終於能夠安息，也狠狠教訓那些佐司特了，做得好。', 28153),
(154179, 'zhTW', '', '再這麼打下去，亞羅姆之地的難民也會陷入危險之中。一定要消滅敵軍！', 28153),
(154178, 'zhTW', '召喚風暴之力，揪出這個叛徒吧！', '', 28153),
(154177, 'zhTW', '你很會運用我的力量，勇士。', '', 28153),
(154176, 'zhTW', '親愛的孩子，你終於聽見我的聲音了。我們的神廟裡面有個叛徒。', '', 28153),
(154175, 'zhTW', '', '有個邪惡的可怕生物威脅了人民的生命安全，請你消滅牠。', 28153),
(154174, 'zhTW', '', '女巫在這個地方放出了可怕的生物，殺掉牠！', 28153),
(154173, 'zhTW', '', '做得好！多虧了你，佐司瓦的居民安全了。', 28153),
(154172, 'zhTW', '', '做得好，審判官！看他們下次還敢不敢回佐司瓦作怪！', 28153),
(154171, 'zhTW', '我終於重獲自由了！非常感謝你。', '', 28153),
(154170, 'zhTW', '', '斥候回報有危險的敵人在附近潛伏。消滅敵人！', 28153),
(154169, 'zhTW', '', '這個地方的人民受到強大的敵人威脅。請你消除這個威脅。', 28153),
(154168, 'zhTW', '我怎麼可能會輸？', '', 28153),
(154167, 'zhTW', '', '佐司瓦的人民都非常感謝你。我們今晚總算可以睡個好覺了。', 28153),
(154166, 'zhTW', '', '佐司瓦的人民非常感謝你的幫助。', 28153),
(154165, 'zhTW', '那非常不明智。', '', 28153),
(154164, 'zhTW', '', '報告指出這個地區有敵人，殺掉他們。', 28153),
(154163, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t古翰對你施放 |cFFFF0404|Hspell:272506|h[腐化爆裂]|h|r！', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t古翰對你施放 |cFFFF0404|Hspell:272506|h[腐化爆裂]|h|r！', 28153),
(154162, 'zhTW', '總算安息了…', '', 28153),
(154161, 'zhTW', '', '有個危險的敵人威脅了佐司瓦的安全，想辦法解決掉！', 28153),
(154160, 'zhTW', '如果海洋殺不了我，你憑什麼認為你殺得了我？', '', 28153),
(154159, 'zhTW', '等著看我吞噬整個世界吧。', '', 28153),
(154158, 'zhTW', '我們需要一艘渡船送我們去斯陀頌恩修道院。', '我們需要一艘渡船送我們去斯陀頌恩修道院。', 28153),
(154157, 'zhTW', '現在來為新主人效忠吧。', '', 28153),
(154155, 'zhTW', '一切意在言外…', '', 28153),
(154154, 'zhTW', '我的內心還是交戰不已！', '', 28153),
(154153, 'zhTW', '你的慘叫會不斷迴盪！', '', 28153),
(154152, 'zhTW', '血肉的詛咒會毀掉你們！', '', 28153),
(154151, 'zhTW', '爆發大規模傳染！', '', 28153),
(154150, 'zhTW', '', '卡嘉，我非去不可，我的職責第一。', 28153),
(154149, 'zhTW', '', '賈克拉傑背叛國王，但是沒有證據，國王不能拿他怎麼樣。', 28153),
(154148, 'zhTW', '看來…我現在可以休息了…', '看來…我現在可以休息了…', 28153),
(154147, 'zhTW', '我們警告你了！', '我們警告你了！', 28153),
(154146, 'zhTW', '', '快走，看你能找到什麼。我不能離開洛琪拉身邊。', 28153),
(154145, 'zhTW', '現在你可以聆聽亞昆達的話語，但你必須一個人。準備好就去祭壇那邊祈禱。', '', 28153),
(154144, 'zhTW', '你必須先淨身，亞昆達才會進入你的意志。', '', 28153),
(154143, 'zhTW', '我希望能回到這個地方。', '我希望能回到這個地方。', 28153),
(154142, 'zhTW', '恢復最大值，繼續收集作業。', '', 28153),
(154141, 'zhTW', '<阿賽爾溫暖地向你問候。>', '<阿賽爾溫暖地向你問候。>', 28153),
(154140, 'zhTW', '<阿賽爾一直注視著你。>', '<阿賽爾一直注視著你。>', 28153),
(154139, 'zhTW', '正在進行液體排放作業，進入待機狀態。', '', 28153),
(154138, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t古翰開始施放|cFFFF0404|Hspell:267700|h[古翰的凝視]|h|r。', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t古翰開始施放|cFFFF0404|Hspell:267700|h[古翰的凝視]|h|r。', 28153),
(154133, 'zhTW', '已鎖定要摧毀的樣本。', '', 28153),
(154132, 'zhTW', '對目標宿主執行血液分離作業。', '', 28153),
(154131, 'zhTW', '啟動鬥棍回收作業。', '', 28153),
(154130, 'zhTW', '開始部屬鬥棍。', '', 28153),
(154129, 'zhTW', '燃料耗盡，執行關機作業…', '', 28153),
(154128, 'zhTW', '', 'Dranosh\'ek mag\'har！', 28153),
(154127, 'zhTW', '污染用的樣本準備完畢。', '', 28153),
(154126, 'zhTW', '', '這裡戰禍連年。<大笑>太好了！我們最擅長屠戮戰場…我們一定會獲得勝利！', 28153),
(154125, 'zhTW', '', '這支強盛的部族如今只剩下我們。我們沒有受到腐化…我們英勇不屈…我們是瑪格哈！', 28153),
(154124, 'zhTW', '', '這些字字句句，就是我們的生存之道。', 28153),
(154123, 'zhTW', '', '力量與榮耀。鮮血與雷霆。', 28153),
(154122, 'zhTW', '腐朽能源準備完成。', '', 28153),
(154121, 'zhTW', '出現腐化的新對象。', '', 28153),
(154120, 'zhTW', '偵測到宿主，開始進行感染。', '', 28153),
(154119, 'zhTW', '', '我保證是真的，而且路途非常危險。就連塞斯拉克人都不敢踏進峽谷裡面。', 28153),
(154118, 'zhTW', '開始收集血漿。', '', 28153),
(154117, 'zhTW', '動作快，懶蟲！修好就有酬勞！', '', 28153),
(154116, 'zhTW', '多麼美麗的島嶼…', '多麼美麗的島嶼…', 28153),
(154115, 'zhTW', '那稱得上榮耀嗎？', '那稱得上榮耀嗎？', 28153),
(154114, 'zhTW', '', '繼續行動，洛琪拉在這片沙漠可撐不了多久。', 28153),
(154113, 'zhTW', '這點痛苦根本不算什麼…', '這點痛苦根本不算什麼…', 28153),
(154112, 'zhTW', '我為什麼會失敗？', '我為什麼會失敗？', 28153),
(154111, 'zhTW', '死吧，禿鷹！', '死吧，禿鷹！', 28153),
(154110, 'zhTW', '你沒辦法打敗我！', '你沒辦法打敗我！', 28153),
(154109, 'zhTW', '女妖之王現在人在哪裡？', '女妖之王現在人在哪裡？', 28153),
(154108, 'zhTW', '我從海難逃過一劫，可不是要死在你這個人渣手中！', '我從海難逃過一劫，可不是要死在你這個人渣手中！', 28153),
(154107, 'zhTW', '', '喔，我不這麼認為。', 28153),
(154106, 'zhTW', '該來實行妮莎的計畫了，塞斯拉克人絕對想不到。', '', 28153),
(154105, 'zhTW', '', '我應該要在保全上面花更多錢的。', 28153),
(154104, 'zhTW', '', '我不能讓你分散注意力！', 28153),
(154103, 'zhTW', '', '有必要的話就攻擊他們全部！我要珊瑚破壞者立刻開始運作。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154102, 'zhTW', '她傷勢太重，可能撐不了多久了。', '', 28153),
(154101, 'zhTW', '', '這是當然的囉。有其他倖存者嗎？', 28153),
(154100, 'zhTW', '在這裡被摧毀之前救多少是多少。', '在這裡被摧毀之前救多少是多少。', 28153),
(154099, 'zhTW', '這裡有好多迷人的物品。', '這裡有好多迷人的物品。', 28153),
(154098, 'zhTW', '還需要一段時間，才會有足夠人手維護古商路的安全。非常謝謝你的幫忙。', '', 28153),
(154097, 'zhTW', '謝謝你…', '謝謝你…', 28153),
(154096, 'zhTW', '喔不…別再來了。', '喔不…別再來了。', 28153),
(154095, 'zhTW', '別讓它們吃掉我…', '別讓它們吃掉我…', 28153),
(154094, 'zhTW', '他們告訴我…這只是件簡單的事…', '他們告訴我…這只是件簡單的事…', 28153),
(154093, 'zhTW', '你的頭顱會是很好的戰利品。', '你的頭顱會是很好的戰利品。', 28153),
(154092, 'zhTW', '有一些商人要求我們派出護衛。怎樣，你願意護送嗎？', '', 28153),
(154091, 'zhTW', '荒疫會讓你生不如死！', '荒疫會讓你生不如死！', 28153),
(154090, 'zhTW', '你在海上倖存，就是為了死在我手上！', '從海上倖存，只為死在我的劍下！', 28153),
(154089, 'zhTW', '這裡就是你的葬身之地！', '這裡就是你的葬身之地！', 28153),
(154088, 'zhTW', '你露出自己的真面目了，死亡領主！立刻從這個聖地離開！', '你露出自己的真面目了，死亡領主！立刻從這個聖地離開！', 28153),
(154087, 'zhTW', '一個人最難踏出的一步，就是繼續前進的下一步，$n。繼續努力前進。', '一個人最難踏出的一步，就是繼續前進的下一步，$n。繼續努力前進。', 28153),
(154086, 'zhTW', '你只是個以阿薩斯的形貌示人的怪物，$n。等你迎向最終的死亡時，我希望你死得緩慢又痛苦，讓你好好體會一下你對其他生靈造成的折磨和痛楚。\n\n當整個世界紛亂不已，面臨重大危機而自顧不暇時，你卻到處肆意作孽，殺戮生靈，將其轉化成不死生物。我很清楚你一定會以顧全大局當作藉口，不過你別忘了，死亡領主，你做任何事都需要承擔後果。\n\n<薩勒史卓莎輕輕地搖搖頭>\n\n或許就現在而言，你還有點用處。', '你只是個以阿薩斯的形貌示人的怪物，$n。等你迎向最終的死亡時，我希望你死得緩慢又痛苦，讓你好好體會一下你對其他生靈造成的折磨和痛楚。\n\n當整個世界紛亂不已，面臨重大危機而自顧不暇時，你卻到處肆意作孽，殺戮生靈，將其轉化成不死生物。我很清楚你一定會以顧全大局當作藉口，不過你別忘了，死亡領主，你做任何事都需要承擔後果。\n\n<薩勒史卓莎輕輕地搖搖頭>\n\n或許就現在而言，你還有點用處。', 28153),
(154085, 'zhTW', '<薩勒史卓莎的表情稍微緩和了下來。>\n\n我們不會忽視你所做的一切，$n。我們這一族雖然成員稀少，但每一位都無比珍貴。\n\n雖然這無法為對我們所做出的攻擊行為開脫，但我們瞭解，也很看重你的…自我克制。對像你們這樣的人來說，這一定很不容易。', '<薩勒史卓莎的表情稍微緩和了下來。>\n\n我們不會忽視你所做的一切，$n。我們這一族雖然成員稀少，但每一位都無比珍貴。\n\n雖然這無法為對我們所做出的攻擊行為開脫，但我們瞭解，也很看重你的…自我克制。對像你們這樣的人來說，這一定很不容易。', 28153),
(154084, 'zhTW', '這當然，死亡領主，$n。 \n\n我們知道襲擊聖所的是你，也知道腐化凱拉納史卓茲，讓他淪為奴僕的人就是你。 \n\n你一定要為這種種侵犯生靈的行為，付出慘痛的代價，總有一天會的。', '這當然，死亡領主，$n。 \n\n我們知道襲擊聖所的是你，也知道腐化凱拉納史卓茲，讓他淪為奴僕的人就是你。 \n\n你一定要為這種種侵犯生靈的行為，付出慘痛的代價，總有一天會的。', 28153),
(154083, 'zhTW', '我們都知道你的種種惡行，死亡騎士。雖然你也出過力，讓艾澤拉斯免於遭到燃燒軍團蹂躪的命運，但我們還是很難相信你。\n\n請你謹言慎行。', '我們都知道你的種種惡行，死亡騎士。雖然你也出過力，讓艾澤拉斯免於遭到燃燒軍團蹂躪的命運，但我們還是很難相信你。\n\n請你謹言慎行。', 28153),
(154082, 'zhTW', '看來我在晶紅龍殿還漏了幾條龍。<設法殺死她>', '看來我在晶紅龍殿還漏了幾條龍。<設法殺死她>', 28153),
(154081, 'zhTW', '希望我在這裡的所作所為多少能贏得一點信任。', '希望我在這裡的所作所為多少能贏得一點信任。', 28153),
(154080, 'zhTW', '反正你們的人已經虛弱不堪，奄奄一息了。我只是早點結束你們的痛苦。', '反正你們的人已經虛弱不堪，奄奄一息了。我只是早點結束你們的痛苦。', 28153),
(154079, 'zhTW', '我只是盡可能地拯救生命。', '我只是盡可能地拯救生命。', 28153),
(154078, 'zhTW', '你認識我？', '你認識我？', 28153),
(154077, 'zhTW', '不！不！不！！！', '不！不！不！！！', 28153),
(154076, 'zhTW', '', '為了聯盟。', 28153),
(154075, 'zhTW', '快走！你趕快逃命！', '快走！你趕快逃命！', 28153),
(154074, 'zhTW', '我…我好像拉在褲子裡了…', '我…我好像拉在褲子裡了…', 28153),
(154073, 'zhTW', '讓我離開這裡！', '讓我離開這裡！', 28153),
(154072, 'zhTW', '謝謝你！我差點就沒命了。', '謝謝你！我差點就沒命了。', 28153),
(154071, 'zhTW', '這是什麼東西？！我要離開這裡！', '這是什麼東西？！我要離開這裡！', 28153),
(154070, 'zhTW', '我得救了！就差那麼一點，我就要被怪物吃下肚了！', '我得救了！就差那麼一點，我就要被怪物吃下肚了！', 28153),
(154069, 'zhTW', '哼！輕輕鬆鬆。', '', 28153),
(154068, 'zhTW', '真不可思議…斯陀頌恩領主到底在做什麼恐怖的事情？！', '', 28153),
(154067, 'zhTW', '祭壇裡有某種強大、可怕的東西等著我們，我們會用獠牙讓敵人知道我們的厲害！', '', 28153),
(154066, 'zhTW', '小心！我發現祭壇腐化得很嚴重。我們不能袖手旁觀，任憑祭壇繼續惡化下去！', '', 28153),
(154065, 'zhTW', '你好像沒什麼變化嘛。哼，我們繼續狩獵吧。', '', 28153),
(154064, 'zhTW', '有沒有一種平靜的感覺？而且覺得意志更加堅定？走吧，我們去完成該做的事。', '', 28153),
(154063, 'zhTW', '聽說浪潮賢者會用淨化之泉的泉水強化力量。我們踏進祭壇中心以前，可以看看這是不是真的。', '', 28153),
(154062, 'zhTW', '哼！那跟我來！', '', 28153),
(154061, 'zhTW', '無論是誰，要進入我們最聖潔的聖地，都必須先淨身。請你先去每一座淨化之泉接受祝福之後，再踏入祭壇中心。', '', 28153),
(154060, 'zhTW', '所有的努力都能匯集。為了部落！', '', 28153),
(154059, 'zhTW', '幸好斯陀頌恩領主還沒完全控制住這裡，真讓我鬆一口氣。謝謝你。', '', 28153),
(154058, 'zhTW', '這些池子蘊含著力量。去收集純淨之水微粒，我們就可以獲得這些力量！', '', 28153),
(154057, 'zhTW', '我能感受到這個聖地還留有善良的存在。去收集純淨之水微粒吧，我們把聖壇復原成以前的樣子。', '', 28153),
(154056, 'zhTW', '我差點就要沒命了，謝謝你，$c。', '我差點就要沒命了，謝謝你，$c。', 28153),
(154055, 'zhTW', '', '感染正在擴散。', 28153),
(154054, 'zhTW', '', '病毒危險層級提高。', 28153),
(154053, 'zhTW', '', '偵測到新種病毒株。', 28153),
(154052, 'zhTW', '', '已啟動手術區。準備分析樣本。', 28153),
(154051, 'zhTW', '', '感染程度：非常危險。啟動完全淨化程序。', 28153),
(154050, 'zhTW', '', '進行隔離室排氣作業。', 28153),
(154049, 'zhTW', '', '正在測試細菌的高溫抵抗力。', 28153),
(154048, 'zhTW', '', '啟動解剖程序。', 28153),
(154047, 'zhTW', '', '系統已恢復正常，安全層級回復正常範圍。', 28153),
(154046, 'zhTW', '當然不會是靜悄悄的行動，不過這樣很有用。', '', 28153),
(154045, 'zhTW', '', '那是最後一隻了。亞茲瑪沒辦法監視我們了！', 28153),
(154044, 'zhTW', '', '亞茲瑪透過蜘蛛眼睛，監控著所有地方。踩扁牠們。', 28153),
(154043, 'zhTW', '', '清潔完畢。', 28153),
(154042, 'zhTW', '這次是救援任務。找出被俘虜的士兵，釋放他們，然後前往撤離地點。我授權你使用致命武力；實際上，我非常建議你使用。', '', 28153),
(154041, 'zhTW', '', '感染層級下降。', 28153),
(154040, 'zhTW', '很好，這樣第二隊就能輕輕鬆鬆把我們的士兵救出來了。', '', 28153),
(154039, 'zhTW', '', '非常感謝你，影刃拉棘沒辦法再殺害我的人民了。', 28153),
(154038, 'zhTW', '', '感染淨化完畢。', 28153),
(154037, 'zhTW', '這個任務很簡單，就是去製造混亂。有另一隊人馬隨時準備把被俘虜的戰士救出來，不過要先靠你解決那些守衛才行。衝進去，盡量殺，然後脫離混亂。', '', 28153),
(154036, 'zhTW', '', '有個最受亞茲瑪信任的刺客，被目擊到在那附近出沒過。小心點！', 28153),
(154035, 'zhTW', '', '偵測到致命病毒株。立即針對病毒啟動破壞程序。', 28153),
(154034, 'zhTW', '', '那會讓亞茲瑪那種玩弄黑暗巫毒的人學到教訓。', 28153),
(154033, 'zhTW', '', '啟動清潔程序。', 28153),
(154032, 'zhTW', '', '亞茲瑪的邪惡巫毒法術，讓提基面具都動起來了！摧毀她那些腐化的傀儡。', 28153),
(154031, 'zhTW', '你搞定了！現在探險者協會的夥伴們可以放心調查神廟了。', '', 28153),
(154030, 'zhTW', '有人在這裡屠殺贊達拉食人妖，除非把這狀況處理好，不然讓探險者協會進神廟太危險了。進去找出原因吧！', '', 28153),
(154029, 'zhTW', '太好了！我們可以馬上出發探險了。', '', 28153),
(154028, 'zhTW', '有太多提基面具，我沒辦法派助手到神廟裡，它們的魔法太強了！', '', 28153),
(154027, 'zhTW', '幹得好！雖然我鬍子裡好像還有東西在爬！', '', 28153),
(154026, 'zhTW', '啊，蜘蛛！又是蜘蛛！這個亞茲瑪讓這裡到處都是蜘蛛，你幫我打死一些，我們才能安心工作！', '', 28153),
(154025, 'zhTW', '聖光勇士，摧毀那些石毀車！', '', 28153),
(154024, 'zhTW', '獅鷲騎士，快起飛！', '', 28153),
(154023, 'zhTW', '黑鐵矮人，就是現在！從下面攻擊他們！', '', 28153),
(154022, 'zhTW', '', '嗯，證據確鑿。不過因為你，他們也沒剩幾個人可以執行計畫了！總之，做得非常好。', 28153),
(154021, 'zhTW', '榮耀…歸於聯盟…', '', 28153),
(154020, 'zhTW', '也許我現在是霧帆的人，但竟以為我會背棄我的聯盟根源，加入部落…你好大膽！', '', 28153),
(154019, 'zhTW', '', '每次自由港的海盜一出現就沒好事。我想知道他們這次在搞什麼。', 28153),
(154018, 'zhTW', '第七軍團需要操心的事情又少了一件，謝謝你。', '', 28153),
(154017, 'zhTW', '打得好！我們會固守這整塊區域，為了聯盟！', '', 28153),
(154016, 'zhTW', '剛剛很驚險，但是你英勇地克服了。繼續保持下去！', '', 28153),
(154015, 'zhTW', '敵人已經除掉了。很遺憾必須用暴力解決，但你完成了必要的任務。', '', 28153),
(154014, 'zhTW', '如果第三次戰爭有你隨行，事情應該會更順利。做得好。', '', 28153),
(154013, 'zhTW', '要是你有打第二次戰爭，應該也很厲害。打得好。', '', 28153),
(154012, 'zhTW', '非常好，又少了一個要擔心的禍害！', '', 28153),
(154011, 'zhTW', '謝謝你出這份力，你是真正的勇士，貨真價實的虔信者！', '', 28153),
(154010, 'zhTW', '', '只要消滅他們的錢包！就能打擊骨頭幫！', 28153),
(154009, 'zhTW', '', '如果我們能拿到骨頭幫的帳簿，就有辦法破壞他們的生意！', 28153),
(154008, 'zhTW', '感謝你，我們還不能移動傷患，但你替我們爭取了寶貴的時間。', '感謝你，我們還不能移動傷患，但你替我們爭取了寶貴的時間。', 28153),
(154007, 'zhTW', '來，這樣可以暫時止血…', '來，這可以暫時止血…', 28153),
(154006, 'zhTW', '我知道會痛，但盡量不要動…', '我知道會痛，但盡量別動…', 28153),
(154005, 'zhTW', '安靜！他們會聽到…', '安靜！他們會聽到。', 28153),
(154004, 'zhTW', '快去求救！我來看看有沒有辦法從奧迪爾內部阻止腐化！', '', 28153),
(154003, 'zhTW', '', '我在哪裡都能認出歐文斯的字跡。我要先幹掉你，然後再宰了那個叛徒！', 28153),
(154002, 'zhTW', '哎呀，入口要關起來了！絕對不能錯失這個機會！', '', 28153),
(154001, 'zhTW', '', '車子還在耶！', 28153),
(154000, 'zhTW', '', '船長！我們正遭遇一場叛亂！', 28153),
(153999, 'zhTW', '那東西是不是說了古翰的名字？趕快追上去！', '', 28153),
(153997, 'zhTW', '也許跟奧迪爾有關。我們得快點找出原因！', '', 28153),
(153996, 'zhTW', '我從來沒有見過那種腐化。', '', 28153),
(153995, 'zhTW', '', '那邊那個，$c。你想學一下鍊金術嗎？$b$b告訴你，我是世上最好的訓練師。', 28153),
(153994, 'zhTW', '不知道裡面會有什麼秘密？或許裡面會有擊敗古神的線索！', '', 28153),
(153993, 'zhTW', '黑暗帝國殞落以後，泰坦建立了這個設施，在這裡進行實驗，研究各種生物。', '', 28153),
(153992, 'zhTW', '啊！這是什麼鬼東西！', '', 28153),
(153991, 'zhTW', '這個洞穴一定是通往傳說中的奧迪爾！', '', 28153),
(153990, 'zhTW', '多虧有你出手相助，這片沙漠變得更安全了。', '', 28153),
(153989, 'zhTW', '', '剛剛還真是驚險，不過你贏得漂亮，好好保持下去！', 28153),
(153988, 'zhTW', '', '這樣我們就少了一個麻煩。做得好！', 28153),
(153987, 'zhTW', '', '太好了，敵人這下子應該會牢牢記住這次的教訓。', 28153),
(153986, 'zhTW', '帶路吧。', '帶路吧。', 28153),
(153985, 'zhTW', '', '這棟房子藏了許多秘密。確定上層有人巡邏之後，我可以幫你指出通往地下室的密道。', 28153),
(153984, 'zhTW', '謝謝你的幫助，沃魯敦需要像你這樣的英雄！', '', 28153),
(153983, 'zhTW', '很好，謝謝你，這片沙漠變得稍微安全一點了。', '', 28153),
(153982, 'zhTW', '做得好，這下子沃魯敦變得更安全了！', '', 28153),
(153981, 'zhTW', '想想那些…金幣啊…', '', 28153),
(153980, 'zhTW', '你知道自己在做什麼嗎？艾胥凡會讓我們變得難以想像的強大！', '', 28153),
(153979, 'zhTW', '我不會讓你傷害我的人民！', '', 28153),
(153978, 'zhTW', '石頭…到處都是…魔古…全部笑納！', '', 28153),
(153977, 'zhTW', '就在那裡！攻擊！', '', 28153),
(153976, 'zhTW', '', '我們應該安全了，你表現得很好。', 28153),
(153975, 'zhTW', '有了這些石頭，魔古就會無人可敵！', '', 28153),
(153974, 'zhTW', '你竟敢在我面前露臉！快滾！', '', 28153),
(153973, 'zhTW', '', '敵人追上來了，炸掉他們，勇士！', 28153),
(153972, 'zhTW', '', '忍耐一下！這趟路可不好受。', 28153),
(153971, 'zhTW', '讓你們瞧瞧老狼的尖牙！', '', 28153),
(153970, 'zhTW', '我要殺了你！', '', 28153),
(153969, 'zhTW', '挺有骨氣的嘛！哈！', '', 28153),
(153968, 'zhTW', '', '不可能的。', 28153),
(153967, 'zhTW', '', '真可悲。', 28153),
(153966, 'zhTW', '', '今天別想。', 28153),
(153965, 'zhTW', '我的斥候說附近有危險的敵人。我需要你去處理一下。', '', 28153),
(153962, 'zhTW', '附近的敵人害我失去一些部下，去幫他們報仇！', '', 28153),
(153959, 'zhTW', '第七軍團收到情報，附近有強大的敵人。去把敵人殺了。', '', 28153),
(153958, 'zhTW', '沒有財寶…只有黑暗。', '放眼望去都是黃金…', 28153),
(153957, 'zhTW', '讓我自由…', '我…自由了嗎？', 28153),
(153956, 'zhTW', '受詛咒的財寶…受詛咒的金子…', '該死的小偷…', 28153),
(153955, 'zhTW', '把我丟上財寶堆…', '金色的骨頭…', 28153),
(153954, 'zhTW', '根據可靠情報，你附近有危險的敵人。解決敵人，保持警戒，其他敵人隨時都有可能出現。', '', 28153),
(153953, 'zhTW', '附近有的敵人，害我們損失不少斥候。解決敵人，別讓斥候白白犧牲。', '', 28153),
(153952, 'zhTW', '小心，這附近有敵人。保持冷靜，把牠殺了，別讓牠逃走。', '', 28153),
(153951, 'zhTW', '不要垂頭喪氣嘛，老大。如果你不喜歡牠，你可以繼續找啊。', '', 28153),
(153950, 'zhTW', '我會給你們每個人一瓶藥水，現在先不要喝。', '', 28153),
(153949, 'zhTW', '很好，你成功激怒了一座沉睡的城市。\n\n別再浪費時間互相指責了，好嗎？', '', 28153),
(153948, 'zhTW', '我聽過這個故事了。(跳過場景並傳送到贊達拉的祖達薩港)', '我聽過這個故事了。(跳過場景並傳送到贊達拉的祖達薩港)', 28153),
(153947, 'zhTW', '就用你的死亡來回敬你的主人，告訴他風暴守望永不屈服！', '', 28153),
(153946, 'zhTW', '別讓它侵襲你的意志！反抗它！', '', 28153),
(153945, 'zhTW', '', '這所有的痛苦跟折磨都是你的錯…你這個怪物！', 28153),
(153944, 'zhTW', '我會保護大家，擋住它的攻擊！', '', 28153),
(153943, 'zhTW', 'Ni plahf Ni bormaz Oou sshoq\'meg vwyq yyg\'far。', '', 28153),
(153942, 'zhTW', '黃金。黃金。黃金。', '財寶堆成山。', 28153),
(153941, 'zhTW', '沒有光。沒辦法逃離。被遺忘之王重返。', '', 28153),
(153940, 'zhTW', '沒有船員…', '跑啊...', 28153),
(153939, 'zhTW', '所有財寶都是贊姆蘭的。', '只有贊姆蘭才能碰這些寶藏。', 28153),
(153938, 'zhTW', '看來我們應該互相引見一下。大副歐雯斯，這是$n。$n，這是歐雯斯。那我們就進入正題吧？', '', 28153),
(153937, 'zhTW', '', '我警告過基羅，塞斯拉克人很快就會找上我們。我們早就該有所準備…也許他現在終於肯相信我了。', 28153),
(153936, 'zhTW', '', '我們沒料到他們會發動攻擊，這些塞斯拉克人燒殺擄掠，還理直氣壯。', 28153),
(153935, 'zhTW', '黃金…', '亮晶晶…', 28153),
(153934, 'zhTW', '附近有可怕的生物出沒，你去消滅牠，別讓牠傷害其他無辜的生命。', '', 28153),
(153933, 'zhTW', '有盟友在附近遭受攻擊，你必須立刻剷除這個威脅！', '', 28153),
(153930, 'zhTW', '有隻危險生物在附近出沒，在出現其他受害者之前，你先去把牠解決掉！', '', 28153),
(153929, 'zhTW', '', '附近有隻生物非常危險。把牠解決掉，越快越好！', 28153),
(153928, 'zhTW', '', '有盟友在附近遭受攻擊，你去幫忙處理一下，不要讓其他人受害！', 28153),
(153927, 'zhTW', '', '有隻危險生物在附近出沒，在牠殺掉你之前，要先下手為強！', 28153),
(153926, 'zhTW', '我收到報告，這個區域有隻很危險的生物。我要你用最快速度解決這隻生物。', '', 28153),
(153925, 'zhTW', '快來支援我！', '', 28153),
(153924, 'zhTW', '有支車隊在附近受到攻擊。去解決那個禍害，以免再有這種事情！', '', 28153),
(153923, 'zhTW', '我知道她是人類，但請試著有點同理心。', '', 28153),
(153922, 'zhTW', '我們的目標很簡單。只要我們幫她成功兵變，我們就能用這裡做為我們攻擊時的據點。', '', 28153),
(153921, 'zhTW', '歐文斯不想要向其他海盜一樣放棄她的自由。', '', 28153),
(153920, 'zhTW', '附近有危險的生物。有人傷亡之前，快把牠解決掉！', '', 28153),
(153919, 'zhTW', '我在提拉加德尋找著陸點時聽說了我們的聯絡人。', '', 28153),
(153918, 'zhTW', '啊哈，海盜！', '', 28153),
(153917, 'zhTW', '沉沒的領域歡迎你們不情願的靈魂們。', '', 28153),
(153916, 'zhTW', 'Oou c\'toth shuul phquathi ywaq uulg\'ma on\'ma。', '', 28153),
(153915, 'zhTW', '我們失去他了，剩下的只有黑暗。', '', 28153),
(153914, 'zhTW', '', '小山，我知道你還聽得見。千萬不能放棄！', 28153),
(153913, 'zhTW', '的確，無論什麼都擋不了你太久。', '', 28153),
(153912, 'zhTW', '', '好！路線安全了！', 28153),
(153911, 'zhTW', '原來只是艘模型船。這件事就到此為止吧。', '', 28153),
(153910, 'zhTW', '', '好極了！把船帶回去看看有什麼秘密。', 28153),
(153909, 'zhTW', '這樣就行了。大酋長會感謝你的。', '', 28153),
(153908, 'zhTW', '', '太好了！你幫了我們大忙。', 28153),
(153907, 'zhTW', '好了，老大。我們來去會會他吧！記得表現得像個海盜！', '', 28153),
(153906, 'zhTW', '不覺得我這樣還不錯嗎？咿哈！', '', 28153),
(153905, 'zhTW', '有一頭凶猛的野獸阻礙我們離開監獄，殺了牠。', '', 28153),
(153904, 'zhTW', '', '有一頭巨大的野獸害我們沒辦法建立灘頭堡。去解決牠，我們才有撤退路線。', 28153),
(153903, 'zhTW', '讓我也來裝扮一下，老大。', '', 28153),
(153902, 'zhTW', '我們的間諜大師報告說：號稱庫爾提拉斯之光的偉大軍艦現在停在托達戈爾。如果報告屬實，你就必須去把船偷過來。', '', 28153),
(153901, 'zhTW', '', '監督者把傳家寶藏在一艘模型船裡。希望你能找回來。', 28153),
(153900, 'zhTW', '部落的戰爭機器需要武器和防具。你先去搜刮有用的東西，再回來找我。', '', 28153),
(153899, 'zhTW', '', '那裡面亂成一團，一定還有剩下的補給品。來看看我們能不能悄悄混進去，借點東西來用用。', 28153),
(153898, 'zhTW', '部落奪走你的父親…背叛你的國王…你卻什麼都不做！你打算拋棄所有盟友，任憑部落宰割嗎？', '', 28153),
(153897, 'zhTW', '部落都是野獸。也難怪他們最終還是背叛了你！', '', 28153),
(153896, 'zhTW', '你背棄血族，跑去跟那些野獸在一起。', '', 28153),
(153895, 'zhTW', '你冷眼旁觀，看著那些禽獸殺掉我。可是你背叛了我，又換得什麼？', '', 28153),
(153894, 'zhTW', '有一大群枯木食人妖從東方往激流堡過來了。不如把一部分的人趕回去小茅屋裡吧？剩下的記得要殺乾淨。', '', 28153),
(153893, 'zhTW', '朋友，這艘船不能燒。我們還要靠它才能到島上去。', '', 28153),
(153892, 'zhTW', '我們有許多獅鷲騎士被擊落了。在戰場上隨時注意有沒有生還者。', '', 28153),
(153891, 'zhTW', '', '見識到了吧！現在懂了吧！古翰會征服一切！', 28153),
(153890, 'zhTW', '', '如果不阻止那個怪物的話，它會毀掉祖達薩的！', 28153),
(153889, 'zhTW', '', '我知道鮮血食人妖是莫大的威脅，可是我沒想到居然有…這種東西…', 28153),
(153888, 'zhTW', '你是誰？', '你是誰？', 28153),
(153886, 'zhTW', '很高興見到你，$n。我們都知道你這位艾澤拉斯勇士的英雄事蹟。', '很高興見到你，$n。我們都知道你這位艾澤拉斯勇士的英雄事蹟。', 28153),
(153885, 'zhTW', '邪惡的魔物！滾回深淵！', '', 28153),
(153884, 'zhTW', '我擔心斯陀頌恩家族的邪教徒打算在波拉勒斯散播邪惡思想。去揭露他們的真面目。', '', 28153),
(153883, 'zhTW', '', '看來傳聞是真的。至少現在街上變得比以前安全了。', 28153),
(153882, 'zhTW', '兄弟姊妹，與我並肩作戰吧！', '', 28153),
(153881, 'zhTW', '繼續前進。黑暗在侵蝕他的意志！', '', 28153),
(153880, 'zhTW', '', '小山，撐住啊！我們就快到了！', 28153),
(153879, 'zhTW', '血一般的海潮！高漲！高漲！', '', 28153),
(153878, 'zhTW', '', '聽說波拉勒斯的守衛被幫派收買了。你可以幫忙調查一下嗎？', 28153),
(153877, 'zhTW', '呼…這應該可以轉移牠們的注意…呃…只有五分鐘？', '', 28153),
(153876, 'zhTW', '哇嗚！這些鳥簡直瘋了！給牠們食物或什麼都好！快！', '', 28153),
(153875, 'zhTW', '好，雖然這些錢包都不是我的，不過…在找到失主之前，我很樂意幫忙保管。', '', 28153),
(153874, 'zhTW', '咦？我的錢包呢？那臭小鬼是不是偷了我的錢包？！快追！', '', 28153),
(153873, 'zhTW', '', '希望其他人都平安無事。', 28153),
(153872, 'zhTW', '', '狐狸人是最溫和的種族了，我們駕著車隊移動、收集補給品，還到處跟人交易。', 28153),
(153871, 'zhTW', '你辦到了，$p。艾特文醒來了！', '', 28153),
(153870, 'zhTW', '', '塞斯拉克人對我的家園做了什麼…', 28153),
(153869, 'zhTW', '', '選得好，這個我會用。', 28153),
(153868, 'zhTW', '有些石拳巨魔打算攻擊激流堡。麻煩你向那些有啤酒肚的暴力分子示範一下，弄髒我們大門的下場。', '', 28153),
(153867, 'zhTW', '要有耐心，泰莉亞。他們會來的。', '', 28153),
(153866, 'zhTW', '', '風暴守望的其他人真的有辦法及時趕來嗎？', 28153),
(153865, 'zhTW', '你可以把那些無賴送回他們的村子裡領賞，就在西南方的湖邊。不過我會避開水域…畢竟魚人蝌蚪就是從這種地方來的。', '', 28153),
(153864, 'zhTW', '怎麼有一大群魚人蝌蚪在蹦蹦跳跳啊。', '', 28153),
(153863, 'zhTW', '斥候回報東北方的礦場有一輛失竊的礦車。看來要使用暴力手段回收了。', '', 28153),
(153862, 'zhTW', '我們偶然發現有些部落的伐木工沒人把守。看來應該去跟他們「木木款」。', '', 28153),
(153861, 'zhTW', '要記得，即使是有感情、有攻擊性的木頭…也還是木頭。而且是一大堆木頭。', '', 28153),
(153860, 'zhTW', '枝葉領主奧督斯出現在森林邊緣。', '', 28153),
(153859, 'zhTW', '石巨人弗茲魯克正在東南方的道路上到處踐踏。小心別被踩到了。', '', 28153),
(153858, 'zhTW', '我們揍到它聽話，再派它去部落的前線如何？', '', 28153),
(153857, 'zhTW', '東邊的山丘上有個巨大的土元素。', '', 28153),
(153856, 'zhTW', '各位英勇的聯軍士兵，時候到了。', '', 28153),
(153855, 'zhTW', '十字軍，衝向亞格洛克！這是聖光的旨意！', '', 28153),
(153854, 'zhTW', '部落打算佔領賈爾森礦場。讓他們知道，他們永遠在「狀礦外」！', '', 28153),
(153853, 'zhTW', '部落在騷擾高地伐木場的盟友。你去「砍砍」他們到底想怎樣。', '', 28153),
(153852, 'zhTW', '部落的軍隊入侵激流堡了。保護好指揮官、再把他們趕出去，好嗎？', '', 28153),
(153851, 'zhTW', '高地駐營受到攻擊。我能提議讓這些部落的老弱殘兵滾下山去嗎？', '', 28153),
(153850, 'zhTW', '', '準備好就跟我說一聲！', 28153),
(153849, 'zhTW', '', '大酋長需要所有部落的英雄保持機靈、準備充足。我們應該善用時間，好好完成戰鬥訓練。', 28153),
(153848, 'zhTW', '', '你好！歡迎來到希利蘇斯，我們的任務是護衛艾澤萊晶岩採集工作。', 28153),
(153847, 'zhTW', '蠕動…扭曲…低語…', '', 28153),
(153846, 'zhTW', '準備好的話就跟我說一聲。', '', 28153),
(153845, 'zhTW', '我們可以利用巡邏希利蘇斯的機會，好好練習你的戰鬥技巧。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153844, 'zhTW', '歡迎你！烏瑞恩國王要求所有聯盟英雄在對上部落的時候都處於最佳狀態。', '', 28153),
(153843, 'zhTW', '小心腳下。這座橋可不是浪得虛名的。', '', 28153),
(153842, 'zhTW', '', '好極了！接下來，…等等，那是…？準備戰鬥！聯盟打過來了！', 28153),
(153841, 'zhTW', '漲潮…無處可逃…', '', 28153),
(153840, 'zhTW', '一定要守住這裡！幫祖爾爭取時間，讓他解決這些該死的東西。', '', 28153),
(153839, 'zhTW', '部落的部隊接近元素之環了。我們應該給他們上一堂魔法課。', '', 28153),
(153838, 'zhTW', '', '為了爸爸！', 28153),
(153837, 'zhTW', '', '我可不會對你手下留情！', 28153),
