(153702, 'zhTW', '孩子們，去安全的地方，快！', '孩子們，去安全的地方，快！', 28153),
(153701, 'zhTW', '別擔心，我會照顧你們…', '別擔心，我會照顧你們…', 28153),
(153700, 'zhTW', '快點，來這裡！', '快點，來這裡！', 28153),
(153699, 'zhTW', '好，接下來我們接手就可以了。大家兩隻眼睛都還在吧！很好！', '', 28153),
(153698, 'zhTW', '庫爾提拉斯的海洋會吞噬你們！', '庫爾提拉斯的海洋會吞噬你們！', 28153),
(153697, 'zhTW', '就這樣吧。我的家人安全了。', '就這樣吧。我的家人安全了。', 28153),
(153696, 'zhTW', '你要付出代價！', '你要付出代價！', 28153),
(153695, 'zhTW', '野蠻人！', '野蠻人！', 28153),
(153694, 'zhTW', '這裡被鳥攻陷了！你最好叫那些老百姓趕快撤離，免得被海鷗啄掉眼睛。別跟他們說是我說的！', '', 28153),
(153693, 'zhTW', '救命！救救我們！', '救命！救救我們！', 28153),
(153692, 'zhTW', '我不會就這麼倒下…', '我不會就這麼倒下…', 28153),
(153691, 'zhTW', '我好怕！', '我好怕！', 28153),
(153690, 'zhTW', '可是我爸爸媽媽…', '可是我爸爸媽媽…', 28153),
(153689, 'zhTW', '我們會死掉嗎？', '我們會死掉嗎？', 28153),
(153688, 'zhTW', '為什麼你都不動？我好怕！', '為什麼你都不動？我好怕！', 28153),
(153687, 'zhTW', '快起來！拜託快起來…', '快起來！拜託快起來…', 28153),
(153686, 'zhTW', '爸爸！', '爸爸！', 28153),
