(153669, 'zhTW', '部落已經控制高地伐木場了！', '部落已經控制高地伐木場了！', 28153),
(153668, 'zhTW', '$n佔領了高地伐木場！', '$n佔領了高地伐木場！', 28153),
(153667, 'zhTW', '部落已經控制英勇之喚小徑了！', '部落已經控制英勇之喚小徑了！', 28153),
(153666, 'zhTW', '$n佔領了英勇之喚小徑！', '$n佔領了英勇之喚小徑！', 28153),
(153665, 'zhTW', '我們的英勇事蹟應該可以被收錄在軍事史的卷軸裡。', '', 28153),
(153664, 'zhTW', '我們高明的策略和完美的行動混淆了敵人。', '', 28153),
(153663, 'zhTW', '看來我們讓他們措手不及了。', '', 28153),
(153662, 'zhTW', '', '維多利亞！她…她沒能撐過去…', 28153),
(153661, 'zhTW', '', '聽好了！跟著納薩諾斯到庭院去！我會從後面擋住聯盟的部隊！', 28153),
(153660, 'zhTW', '士兵們，各就各位！聯盟打過來了！', '', 28153),
(153659, 'zhTW', '', '贊達拉不了解他們面前的恐怖，必須警告他們。', 28153),
(153658, 'zhTW', '', '艾薩拉女王正在策劃陰謀，而且她還有其他幫手。', 28153),
(153657, 'zhTW', '', '天啊！這實在太糟了，這些命令的內容，是要殺死效忠格拉爾的人！', 28153),
(153656, 'zhTW', '我們佔據空曠地形，就能以十對一！', '', 28153),
(153655, 'zhTW', '拜託你，別把我塞回魔像體內…', '求求你，讓我的靈魂自由…', 28153),
(153654, 'zhTW', '薩卡拉占，我們來找你算帳了…', '薩卡拉占，下個輪到你了…', 28153),
(153653, 'zhTW', '終於…可以休息…？', '終於…可以休息了…', 28153),
(153652, 'zhTW', '伯昂撒姆第…不肯放我前往彼界…', '何時…才能抵達彼界…？', 28153),
(153651, 'zhTW', '樹苗被野生動物吃了！', '樹苗被野生動物吃了！', 28153),
(153650, 'zhTW', '哇啊啊！', '', 28153),
(153649, 'zhTW', '千萬別讓部落的軍隊逃走！', '', 28153),
(153648, 'zhTW', '守衛！我們被攻擊了！堅守崗位！把城門關起來，把出口堵住！', '', 28153),
(153647, 'zhTW', '很好，走吧！', '', 28153),
(153646, 'zhTW', '當然。', '當然。', 28153),
(153645, 'zhTW', '你的朋友都受到女巫的折磨與殺害。', '你的朋友都受到女巫的折磨與殺害。', 28153),
(153644, 'zhTW', '噢，可惡！這下不妙。\n\n我有好消息。我快要在那座山丘上設置好據點了。你要不要去看看？', '', 28153),
(153643, 'zhTW', '看來你是從森林裡來的。那邊的傢伙過得如何？', '', 28153),
(153642, 'zhTW', '正好在我成功發明這個狼人機車之後！', '', 28153),
(153641, 'zhTW', '首領，你來了！你還帶了三輪車！', '', 28153),
(153640, 'zhTW', '距離激流堡之役開始還有1分鐘。', '', 28153),
(153639, 'zhTW', '我們合作之下更形強大。', '', 28153),
(153638, 'zhTW', '永不屈服，長存於世。', '', 28153),
(153637, 'zhTW', '小心一點。', '', 28153),
(153636, 'zhTW', '我剛剛不是說別做蠢事嗎？', '', 28153),
(153635, 'zhTW', '放逐者歡迎你，旅人。', '', 28153),
(153634, 'zhTW', '你前來助我們一臂之力嗎？', '', 28153),
(153633, 'zhTW', '什麼風把你吹來了？', '', 28153),
(153632, 'zhTW', '願你一路順風。', '', 28153),
(153631, 'zhTW', '記住，力量和美德。', '', 28153),
(153630, 'zhTW', '榮耀與你同行。', '', 28153),
(153629, 'zhTW', '這片土地將會…與你為敵…', '這片土地將會…與你為敵…', 28153),
(153628, 'zhTW', '不！我差點就能砍下你的頭…', '不！我差點就能砍下你的頭…', 28153),
(153627, 'zhTW', '弱小的…聯盟…', '弱小的…聯盟…', 28153),
(153626, 'zhTW', '你撐不了多久的…', '你撐不了多久的…', 28153),
(153625, 'zhTW', '食人妖帝國…萬歲…', '食人妖帝國…萬歲…', 28153),
(153624, 'zhTW', '我們不會輕易放棄…', '我們不會輕易放棄…', 28153),
(153623, 'zhTW', '你說，我在聽。', '', 28153),
(153622, 'zhTW', '這不是結束…', '這不是結束…', 28153),
(153621, 'zhTW', '歡迎你來到這裡。', '', 28153),
(153620, 'zhTW', '為了…部落。', '為了…部落。', 28153),
(153619, 'zhTW', '你的頭顱會讓我獲得豐厚的獎賞。', '你的頭顱會讓我獲得豐厚的獎賞。', 28153),
(153618, 'zhTW', '自以為比我們還聰明？哈！', '自以為比我們還聰明？哈！', 28153),
(153617, 'zhTW', '我們會把你們的頭當成戰利品！', '我們會把你們的頭當成戰利品！', 28153),
(153616, 'zhTW', '你無法找到我們所有人！', '你無法找到我們所有人！', 28153),
(153615, 'zhTW', '出來玩玩，聯盟小朋友？', '出來玩玩，聯盟小朋友？', 28153),
(153614, 'zhTW', '這片土地是贊達拉人的！', '這片土地是贊達拉人的！', 28153),
(153613, 'zhTW', '你一定會後悔來到這裡！', '你一定會後悔來到這裡！', 28153),
(153612, 'zhTW', '你根本就不應該來這裡！', '你根本就不應該來這裡！', 28153),
(153611, 'zhTW', '沒事的，我們比那些野蠻人厲害多了。', '沒事的，我們比那些野蠻人厲害多了。', 28153),
(153610, 'zhTW', '我不會丟下你！', '我不會丟下你！', 28153),
(153609, 'zhTW', '我們要一起逃出去！', '可惡，一定要逃出去！', 28153),
(153608, 'zhTW', '我不會丟下你的！', '我不會丟下你的！', 28153),
(153607, 'zhTW', '你在做什麼？你快逃命啊！', '你在做什麼？你快逃命啊！', 28153),
(153606, 'zhTW', '去找人幫忙！不用管我！', '去找人幫忙！別管我！', 28153),
(153605, 'zhTW', '太遲了，你快逃…', '太遲了，你快逃…', 28153),
(153604, 'zhTW', '你快逃啊…', '你快逃啊…', 28153),
(153603, 'zhTW', '我會一直看著你。', '', 28153),
(153602, 'zhTW', '他們下一次或許會小心一點，不要再被抓了。算他們好運，部落有像你這麼厲害的英雄出手照應他們。', '', 28153),
(153601, 'zhTW', '我們的盟友需要幫助。他們不知怎麼被抓走了。想辦法把他們救出來。', '', 28153),
(153600, 'zhTW', '有了這個情報，我們一定能取得對抗聯盟的優勢。我們會好好犒賞你的辛勞。', '', 28153),
(153599, 'zhTW', '我們派出去的間諜回報說這個地區隨時會有人來傳遞重要的消息。我們要不計一切代價阻止這件事發生。', '', 28153),
(153598, 'zhTW', '羅亞在眷顧你，這可是好消息！不過別因此得意自滿。', '', 28153),
(153597, 'zhTW', '敵人再次玷汙了羅亞庭園，這次非要讓他們學到教訓不可。羅亞的力量與你同在！', '', 28153),
(153596, 'zhTW', '在哨站跟我們會合。我們必須找到答案，這感覺像是暴風雨前的寧靜。', '', 28153),
(153595, 'zhTW', '這雖然不是什麼好差事，但非做不可。絕對不能讓敵人發現秘密。做得好。', '', 28153),
(153594, 'zhTW', '聯盟已經派出間諜，想辦法刺探我們隱藏的秘密。絕對不能讓他們知道我們的計畫。把這件事辦好。', '', 28153),
(153593, 'zhTW', '要是沒有贊達拉的艦隊，我們跟聯盟的這場仗就只是找死。', '', 28153),
(153592, 'zhTW', '聯盟可不會慢慢等我們把艦隊籌備好才來攻擊。我們需要贊達拉的力量。', '', 28153),
(153591, 'zhTW', '讓這些贊達拉人加入部落，英雄。', '', 28153),
(153590, 'zhTW', '我們需要贊達拉的艦隊。', '', 28153),
(153589, 'zhTW', '服從大酋長的命令。', '', 28153),
(153588, 'zhTW', '只要有你跟艾特文在，計畫就不可能失敗。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153587, 'zhTW', '贊達拉人好像不怎麼喜歡我。', '', 28153),
(153586, 'zhTW', '部落的代表。', '', 28153),
(153585, 'zhTW', '一定要讓贊達拉的艦隊加入部落。絕對要辦到。', '', 28153),
(153584, 'zhTW', '', '這位勇士勇敢抵抗暴風城的力量，救了我和祖爾。父親，你應該允許如此英勇的勇士晉見。', 28153),
(153583, 'zhTW', '陛下，部落的人只是想利用我們的海軍替女妖大酋長效命。', '', 28153),
(153582, 'zhTW', '這裡有好東西，別多問。', '這裡有好東西，別多問。', 28153),
(153581, 'zhTW', '我從高嶺帶了些補給品過來。', '我從高嶺帶了些補給品過來。', 28153),
(153580, 'zhTW', '(觀看使艾澤拉斯受傷的事件)', '(觀看使艾澤拉斯受傷的事件)', 28153),
(153579, 'zhTW', '＜泰坦控制臺顯示有一連串的資料條目。你可以選擇一個來看。＞', '', 28153),
(153578, 'zhTW', '希望你有穿防火內衣！', '希望你有穿防火內衣！', 28153),
(153577, 'zhTW', '唷，狀況越來越火熱了！', '狀況越來越火熱了！', 28153),
(153576, 'zhTW', '該讓你燒起來了！', '該讓你燒起來了！', 28153),
(153575, 'zhTW', '那位「鑽石矮人」是世界之魂的代言者。除非情況十萬火急，否則他不會出手干涉。', '', 28153),
(153574, 'zhTW', '', '噢，你能想像嗎？這個鑽石矮人可以帶我們去艾澤拉斯任何地方！', 28153),
(153573, 'zhTW', '我喜歡這個有傳送功能的鑽石矮人，還帶禮物來。我可以把他留著嗎？', '', 28153),
(153572, 'zhTW', '我知道這一定很重要，麥格尼。不過為了庫爾提拉斯…請你抓緊時間。', '', 28153),
(153571, 'zhTW', '來吧，勇士。艾澤拉斯在呼喚你！', '', 28153),
(153570, 'zhTW', '啊，忘記我把傳送點設在這裡了。', '啊，忘記我把傳送點設在這裡了，可惡。', 28153),
(153569, 'zhTW', '我太老沒辦法了。我要離開這裡！', '我太老沒辦法了。我要離開這裡！', 28153),
(153568, 'zhTW', '士兵，你的表現還有待加強。', '士兵，你的表現還有待加強。', 28153),
(153567, 'zhTW', '長官，我…我會表現得更好，長官。', '長官，我…我會表現得更好，長官。', 28153),
(153566, 'zhTW', '詹姆斯二兵，你當小孩的時候，父母沒給予你足夠的關注嗎？為何你要我浪費時間，在未知的土地上追著你到處跑呢？', '詹姆斯二兵，你當小孩的時候，父母沒給予你足夠的關注嗎？為何你要我浪費時間，在未知的土地上追著你到處跑呢？', 28153),
(153565, 'zhTW', '中士…感謝你來救我…長官。', '中士…感謝你來救我…長官。', 28153),
(153564, 'zhTW', '我們動身吧！', '我們動身吧！', 28153),
(153563, 'zhTW', '我們該回去了。龍禍指揮官會想要看完整的報告。', '我們該回去了。龍禍指揮官會想要看完整的報告。', 28153),
(153562, 'zhTW', '', '棘背沒殺掉我，而他們將會後悔。', 28153),
(153561, 'zhTW', '', '我想當我回來時就會重新裝潢。我在想用獠牙作為主題… 我到底要去哪裡找這種東西？$b$b<迪歐邪惡地一笑。>', 28153),
(153560, 'zhTW', '', '我需要喝一杯，然後就要開始奪回並重建我的家園了。感謝你削減他們的數量！', 28153),
(153559, 'zhTW', '不能逗留太久，我必須回到我的農場。鎮長叫我一定要來這恭賀你幫我們處理棘背的問題。$b$b幹得漂亮，小夥子。', '', 28153),
(153558, 'zhTW', '野豬人的任務做得漂亮，朋友！', '', 28153),
(153557, 'zhTW', '我不能留太久。我們會需要修好那些機械農場幫手，才能恢復它們對田野所造成的損害。$b$b不過隔段時間就休息一下是很重要的。', '', 28153),
(153556, 'zhTW', '我將機械農場幫手設定在自衛模式。我相信它沒問題的。', '', 28153),
(153555, 'zhTW', '注意找野豬人刺針。這是意外好用的工具，野豬人甚至還用它來熔煉！', '', 28153),
(153554, 'zhTW', '北邊有部落，西邊有野豬人。我們還能相信民兵嗎？', '', 28153),
(153553, 'zhTW', '我希望羅爾夫、莫特和史皮夫都逃出來了。', '', 28153),
(153552, 'zhTW', '', '我的間諜告訴我，沒有我們的艦隊，你贏不了聯盟。\n\n所以…我會把今天要搞的每一個小動作都交給你來做，你，沒有拒絕的餘地，哈哈！', 28153),
(153551, 'zhTW', '', '我一直告訴卓蘭妮和塔蘭姬港口已經在掌控之中。她們聽進去了嗎？沒有。$b$b有人鬧事嗎？有人搗亂嗎？有人打架嗎？當然都有。不過這些事都沒有嚴重到需要國王出面的地步。', 28153),
(153550, 'zhTW', '跟我來，若你願意的話。', '跟我來，若你願意的話。', 28153),
(153549, 'zhTW', '勇士，我有東西要給你看。這份禮物也可以幫助艾澤拉斯。', '', 28153),
(153548, 'zhTW', '大家稍安勿躁。這位是麥格尼·銅鬚，他原本是鐵爐堡的國王，現在是艾澤拉斯的代言者。', '', 28153),
(153547, 'zhTW', '噢，還真新奇。', '', 28153),
(153546, 'zhTW', '是巫術！', '', 28153),
(153545, 'zhTW', '', '呃…這是鑽石做的矮人嗎？！', 28153),
(153544, 'zhTW', '快釋放艾澤拉斯之心的力量！', '', 28153),
(153543, 'zhTW', '這是壞消息。我們最好向最高指揮官報告此事。', '這是壞消息。我們最好向最高指揮官報告此事。', 28153),
(153542, 'zhTW', '科爾塞克瘋了！他必須被阻止！', '科爾塞克瘋了！他必須被阻止！', 28153),
(153541, 'zhTW', '科爾塞克對和平逐漸不耐。他不顧瑟沙利斯的犧牲，愚蠢地試圖結合鑰匙，解放克蘇拉希來對付他的敵人。', '科爾塞克對和平逐漸不耐。他不顧瑟沙利斯的犧牲，愚蠢地試圖結合鑰匙，解放克蘇拉希來對付他的敵人。', 28153),
(153540, 'zhTW', '大賢者索利斯尋求我與科爾塞克的協助，來打造一個魔法屏障，封印陣亡的克蘇拉希。我們發誓絕不再讓如此恐怖的力量為禍人間。', '大賢者索利斯尋求我與科爾塞克的協助，來打造一個魔法屏障，封印陣亡的克蘇拉希。我們發誓絕不再讓如此恐怖的力量為禍人間。', 28153),
(153539, 'zhTW', '毀滅的力量超乎想像。我們的土地從此面目全非。', '毀滅的力量超乎想像。我們的土地從此面目全非。', 28153),
(153538, 'zhTW', '因為羅亞出手相助，我們才撿回一命。瑟沙利斯犧牲自己來制伏克蘇拉希，不過牠還是摧毀了矗立在這塊土地中央的一座古老金字塔。', '因為羅亞出手相助，我們才撿回一命。瑟沙利斯犧牲自己來制伏克蘇拉希，不過牠還是摧毀了矗立在這塊土地中央的一座古老金字塔。', 28153),
(153537, 'zhTW', '很久以前，在沙塵開始擴散前，一名可怕的克蘇拉希戰爭使者降臨在我們的土地上。所到之處，沒有任何人在他手下生還，無論是食人妖或是塞斯拉克都一樣。', '很久以前，在沙塵開始擴散前，一名可怕的克蘇拉希戰爭使者降臨在我們的土地上。所到之處，沒有任何人在他手下生還，無論是食人妖或是塞斯拉克都一樣。', 28153),
(153536, 'zhTW', '', '我們必須小心部落。他們不斷攻擊廣場。', 28153),
(153535, 'zhTW', '', '若你看到任何敵人侵入我城鎮的動態，請警告我一聲。', 28153),
(153534, 'zhTW', '', '每個人都指望我領導城鎮。我不會讓他們失望的！', 28153),
(153533, 'zhTW', '', '每個人似乎都安全了…目前是如此。', 28153),
(153532, 'zhTW', '那不只是一塊石頭，那是一把鑰匙。用來封印一股可怕、強大力量的其中一把鑰匙。', '那不只是一塊石頭，那是一把鑰匙。用來封印一股可怕、強大力量的其中一把鑰匙。', 28153),
(153531, 'zhTW', '喔！裡面有某種石頭。', '喔！裡面有某種石頭。', 28153),
(153530, 'zhTW', '別相信那海洋之女', '別相信那海洋之女', 28153),
(153529, 'zhTW', '用盡氣息，他警告人民', '用盡氣息，他警告人民', 28153),
(153528, 'zhTW', '只因女兒無情', '只因女兒無情', 28153),
(153527, 'zhTW', '', '這個矮人保證會強化你勇士身上的裝備，以便拯救我的族人，我願意冒個險。', 28153),
(153526, 'zhTW', '最後上將葬身海底', '最後上將葬身海底', 28153),
(153525, 'zhTW', '女兒卻置身事外', '女兒卻置身事外', 28153),
(153524, 'zhTW', '上將迎敵，英勇無懼', '上將迎敵，英勇無懼', 28153),
(153523, 'zhTW', '敵軍大舉襲來', '敵軍大舉襲來', 28153),
(153522, 'zhTW', '尋尋覓覓，只見危機降臨', '尋尋覓覓，只見危機降臨', 28153),
(153521, 'zhTW', '而自己，死不足惜', '而自己，死不足惜', 28153),
(153520, 'zhTW', '揚帆千里，為拯救她性命', '揚帆千里，為拯救她性命', 28153),
(153519, 'zhTW', '不如我們就讓這位勇士和鑽石國王去一趟吧。', '', 28153),
(153518, 'zhTW', '上將向西追尋', '上將向西追尋', 28153),
(153517, 'zhTW', '愛女逃命，橫越大海而去', '愛女逃命，橫越大海而去', 28153),
(153516, 'zhTW', '為何走錯了路', '為何走錯了路', 28153),
(153515, 'zhTW', '身為我們國家的榮譽', '身為我們國家的榮譽', 28153),
(153514, 'zhTW', '為何，拋棄了過去的回憶', '為何，拋棄了過去的回憶', 28153),
(153513, 'zhTW', '為何遠離？噢，那海洋之女', '為何遠離？噢，那海洋之女', 28153),
(153512, 'zhTW', '因為愛女離去', '因為愛女離去', 28153),
(153511, 'zhTW', '上將捐軀在塞拉摩', '上將捐軀在塞拉摩', 28153),
(153510, 'zhTW', '鮮血蔓延萬里', '鮮血蔓延萬里', 28153),
(153509, 'zhTW', '海軍送命在卡林多', '海軍送命在卡林多', 28153),
(153508, 'zhTW', '他的心，沉沒海底', '他的心，沉沒海底', 28153),
(153507, 'zhTW', '他的話語，飄蕩在風雨裡', '他的話語，飄蕩在風雨裡', 28153),
(153506, 'zhTW', '海上傳來聲音', '海上傳來聲音', 28153),
(153505, 'zhTW', '不要相信，那海洋之女', '不要相信，那海洋之女', 28153),
(153504, 'zhTW', '你好，$r。', '', 28153),
(153502, 'zhTW', '你的口袋裡有東西嗎？', '你的口袋裡有東西嗎？', 28153),
(153501, 'zhTW', '我會待在這裡顧好防禦。再次感謝你，朋友。', '我會待在這裡顧好防禦。再次感謝你，朋友。', 28153),
(153500, 'zhTW', '', '', 28153),
(153499, 'zhTW', '', '手下們！殺光他們！', 28153),
(153498, 'zhTW', '要不是你跟中士，我根本不可能站在這裡。再次感謝你們。', '要不是你跟中士，我根本不可能站在這裡。再次感謝你們。', 28153),
(153497, 'zhTW', '', '我會告訴祖爾。他會決定哪些事情需要向神王拉斯塔哈稟告。', 28153),
(153496, 'zhTW', '殺光他們，別讓他們通過！', '', 28153),
(153495, 'zhTW', '等一下我們要一鼓作氣直接衝到碼頭。準備好了就跟我說。', '', 28153),
(153494, 'zhTW', '你想找死嗎？', '', 28153),
(153493, 'zhTW', '別害我們被抓到。', '', 28153),
(153492, 'zhTW', '你想害死我們嗎？', '', 28153),
(153491, 'zhTW', '吼！不要亂跑！', '', 28153),
(153490, 'zhTW', '老兄，快回來啊！', '', 28153),
(153489, 'zhTW', '是$n，感謝聖光！我會去神殿。這裡不安全。', '', 28153),
(153488, 'zhTW', '並祈禱你不需要做出選擇。', '', 28153),
(153487, 'zhTW', '你最好知道該怎麼分辨忠誠跟榮耀。', '', 28153),
(153486, 'zhTW', '你這話是什麼意思？', '你這話是什麼意思？', 28153),
(153485, 'zhTW', '在她做了那些事以後，我已經不可能再回去她的部落了。', '', 28153),
(153484, 'zhTW', '你以為你來這裡是為了帶我回奧格瑪。回去找大酋長，你弄錯了。', '', 28153),
(153483, 'zhTW', '該對風險投資公司使出精心策劃的攻擊了！', '', 28153),
(153482, 'zhTW', '準備好就跟我說一聲，$n。', '', 28153),
(153477, 'zhTW', '', '先不要死。我們正在忙呢。', 28153),
(153476, 'zhTW', '', '別跟伯昂撒姆第走了。', 28153),
(153475, 'zhTW', '', '撐下去。', 28153),
(153474, 'zhTW', '', '快站起來，朋友。我們還有任務。', 28153),
(153473, 'zhTW', '', '我的羅亞不會讓你倒下。', 28153),
(153472, 'zhTW', '我們的情資說賽斯拉克是邪惡的，看來這是錯的。', '我們的情資說賽斯拉克是邪惡的，看來這是錯的。', 28153),
(153471, 'zhTW', '有兩個人能玩這個遊戲！', '有兩個人能玩這個遊戲！', 28153),
(153470, 'zhTW', '', '嶄新的食人妖帝國即將誕生。我們終於擺脫停滯不前的困境！', 28153),
(153469, 'zhTW', '', '祖爾早就知道會有這一天。來吧…血神的信徒。為這個世界的新時代做好準備！', 28153),
(153468, 'zhTW', '不！不…', '不！不…', 28153),
(153467, 'zhTW', '竟敢搶我的東西…', '竟敢搶我的東西…', 28153),
(153466, 'zhTW', '會輪到你的…', '會輪到你的…', 28153),
(153465, 'zhTW', '英雄們，跟我來！', '', 28153),
(153464, 'zhTW', '我會…逮到你…', '我會…逮到你…', 28153),
(153463, 'zhTW', '你死定了！你們全都會死！', '你死定了！你們全都會死！', 28153),
(153462, 'zhTW', '你以為可以隨便搶我東西嗎？', '你以為可以隨便搶我東西嗎？', 28153),
(153461, 'zhTW', '叛徒！我要砍你們的頭！', '叛徒！我要砍你們的頭！', 28153),
(153460, 'zhTW', '叛徒！你們全部都是！', '叛徒！你們全部都是！', 28153),
(153459, 'zhTW', '尤多拉船長…我想贏啊…', '', 28153),
(153458, 'zhTW', '小鮮肉？污鼠會，吃飯囉！', '', 28153),
(153457, 'zhTW', '今天，你每發出一聲戰吼，每揮動一次武器，偉大的羅亞都會聽在耳裡、看在眼裡！至於戰敗的…就到來世再見吧。', '', 28153),
(153456, 'zhTW', '讓他死得無比榮耀吧…', '', 28153),
(153455, 'zhTW', '讓他死得無比榮耀吧…', '', 28153),
(153454, 'zhTW', '啊啊啊！？', '', 28153),
(153453, 'zhTW', '到來世去吧…', '', 28153),
(153452, 'zhTW', '看來你今天沒有得到羅亞的眷顧。', '', 28153),
(153451, 'zhTW', '為了贊達拉！', '', 28153),
(153450, 'zhTW', '賣出！以281金幣賣出炫彩之劍！拿著這把劍，你想低調都不行。', '', 28153),
(153449, 'zhTW', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t你被|cFFFF0000|Hspell:260838|h[引導飛彈]|h|r鎖定了！', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t你被|cFFFF0000|Hspell:260838|h[引導飛彈]|h|r鎖定了！', 28153),
(153448, 'zhTW', '今天庫爾提拉斯必勝！', '', 28153),
(153447, 'zhTW', '鼻子跟耳朵掉滿地。', '', 28153),
(153446, 'zhTW', '直到真的結束了，才算結束。', '', 28153),
(153445, 'zhTW', '大家坐好！戰鬥還沒結束！', '', 28153),
(153444, 'zhTW', '你想看血，一定能看個夠！稍安勿躁。', '', 28153),
(153443, 'zhTW', '賣出！以18金幣賣出鬧鬼的遺物！老實說，我一毛錢都不會拿來買這東西，但這不是我的錢！', '', 28153),
(153442, 'zhTW', '糟了，糟了。還好，還好。', '', 28153),
(153441, 'zhTW', '你死了…不配成為真正的庫爾提拉斯人。', '', 28153),
(153440, 'zhTW', '哎呀，死啦！', '', 28153),
(153439, 'zhTW', '今晚庫爾提拉斯必勝！', '', 28153),
(153438, 'zhTW', '這不是光明磊落的戰鬥，大家最好保持距離。準備好了嗎？', '', 28153),
(153437, 'zhTW', '只有最後的勝利者，才能獲得如此殊榮。', '', 28153),
(153436, 'zhTW', '各位觀眾，各位朋友！我們今天聚在這裡就是要看這些強盜、惡棍、混蛋人渣能不能變成真正的庫爾提拉斯人！', '', 28153),
(153435, 'zhTW', '賣出！以1412金幣將一枚大型愛心火箭賣給可愛的女士！她現在絕對是城裡的話題人物了！', '', 28153),
(153434, 'zhTW', '賣出！以756金幣將無畏肩鎧賣給前排的年輕人！你似乎無法穿戴這件盔甲，不過誰在乎呢！', '', 28153),
(153433, 'zhTW', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t艾澤洛克正在施放|cFFFF0000|Hspell:257597|h[艾澤萊晶岩注入]|h|r！', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t艾澤洛克正在施放|cFFFF0000|Hspell:257597|h[艾澤萊晶岩注入]|h|r！', 28153),
(153432, 'zhTW', '叛徒！抓住她！', '', 28153),
(153431, 'zhTW', '對我們來說最重要的是不讓科爾塞克染指鑰匙。來吧，我們的神殿就在前方。', '', 28153),
(153430, 'zhTW', '我將它偷偷放在一名他們剛抓到的囚犯口袋裡。他說自己的名字叫詹姆斯。', '', 28153),
(153429, 'zhTW', '一群蠢貨！他們抓到我並搜了我身，但我早已把東西藏到了他們想都想不到的地方。', '', 28153),
(153428, 'zhTW', '但科爾塞克背叛了我們，而索利斯被殺了。如今科爾塞克跟他的追隨者…無信者…在找我跟我的鑰匙。', '', 28153),
(153427, 'zhTW', '很久以前，我們三人不分彼此…我、科爾塞克還有索利斯毫無嫌隙…共同統領人民。羅亞為了把某種古老的邪惡力量封印在沙塵之下，託付給我們三把鑰匙。', '', 28153),
(153426, 'zhTW', '我們的神廟，是對抗無信者的最後陣地。', '', 28153),
(153425, 'zhTW', '', '好啦，好啦。這裡可能真的有一點小小的問題。不過這種小事就沒有必要去煩國王了。', 28153),
(153424, 'zhTW', '', '現在已經不再是信仰羅亞的時代。現在，是血神的時代！', 28153),
(153423, 'zhTW', '', '不用費心去管那些不重要的小事。我們還有更重要的事情要談。', 28153),
(153421, 'zhTW', '', '希望你會喜歡！', 28153),
(153419, 'zhTW', '', '拿去。我可不能讓你空著肚子出發，對吧？', 28153),
(153418, 'zhTW', '', '啊，這些實在太完美了！', 28153),
(153417, 'zhTW', '', '親愛的請等等，我有個東西要給你。', 28153),
(153416, 'zhTW', '做得好！你勇猛的攻擊會讓贊達拉帝國嚇到發抖！', '', 28153),
(153415, 'zhTW', '我想選擇風之主宰帕骷。', '我想選擇風之主宰帕骷。', 28153),
(153414, 'zhTW', '我想選擇獸群之王剛克。', '我想選擇獸群之王剛克。', 28153),
(153413, 'zhTW', '贊達拉以為訓練了一頭猛獸，就可以保證安全了。讓他們知道自己錯得有多離譜！', '', 28153),
(153412, 'zhTW', '終於啊，我們收復激流堡了。', '', 28153),
(153411, 'zhTW', '死吧，雜種！', '', 28153),
(153410, 'zhTW', '學到教訓了吧。', '', 28153),
(153409, 'zhTW', '沒有人會懷念這個傢伙。', '', 28153),
(153408, 'zhTW', '總有一天，激流堡會再次屬於聯盟。', '', 28153),
(153407, 'zhTW', '對部落降下死亡之雨！', '', 28153),
(153406, 'zhTW', '第三部隊，開火！', '', 28153),
(153405, 'zhTW', '我想變更這裡的祖達薩羅亞代表。', '我想變更這裡的祖達薩羅亞代表。', 28153),
(153404, 'zhTW', '壁壘守衛，給我放箭！', '', 28153),
(153403, 'zhTW', '醒來吧，過去的回音！', '', 28153),
(153402, 'zhTW', '阿拉索的先人靈魂會消滅你們！', '', 28153),
(153401, 'zhTW', '邪惡就算在這裡，也不會有藏身之處。你做得很好。', '', 28153),
(153400, 'zhTW', '起來吧，我的祖先，保衛你們的家園。', '', 28153),
(153399, 'zhTW', '我殺過幾千個你們的族人。你也會和他們一樣。', '', 28153),
(153398, 'zhTW', '贊達拉帝國再度獲得了勝利！做得好，部落的勇士。', '', 28153),
(153397, 'zhTW', '這個蠻荒之地有某種邪惡的存在。想辦法把它趕走！', '', 28153),
(153396, 'zhTW', '這個區域受到叢林裡最凶猛的生物威脅。把牠找出來，想辦法消滅牠！', '', 28153),
(153395, 'zhTW', '正義必勝。', '', 28153),
(153394, 'zhTW', '淨化！', '', 28153),
(153393, 'zhTW', '你的命運已定。', '', 28153),
(153392, 'zhTW', '這是你的判決。', '', 28153),
(153391, 'zhTW', '雖然我們失去了激流堡，但是聯盟永遠不會滅亡。', '', 28153),
(153390, 'zhTW', '這就是聖光的力量！', '', 28153),
(153389, 'zhTW', '鼠輩，懼怕聖光的憤怒吧！', '', 28153),
(153388, 'zhTW', '聖光會懲擊你。', '', 28153),
(153387, 'zhTW', '又解決威脅了，聯盟再次獲得勝利了！', '', 28153),
(153386, 'zhTW', '聖光必勝！', '', 28153),
(153385, 'zhTW', '', '我是第一個撰史者。國王要我將我們的歷史記錄在石頭上，讓它世世代代流傳下去。', 28153),
(153384, 'zhTW', '聖光會淨化你！', '', 28153),
(153383, 'zhTW', '我的人民會永遠記得你是贊達拉的勇士。做得好！', '', 28153),
(153382, 'zhTW', '接受聖光的制裁吧！', '', 28153),
(153381, 'zhTW', '為了聖光！', '', 28153),
(153380, 'zhTW', '在這個地方，邪惡就像讓人窒息的藤蔓遍布四處。保護我們的部隊，斬除邪惡。', '', 28153),
(153379, 'zhTW', '我不會讓我的人民受到這種敵人威脅。消滅他們！', '', 28153),
(153378, 'zhTW', '只要清出一條路，我們就有辦法投入更多兵力，對抗贊達拉。謝謝你，勇士。', '', 28153),
(153377, 'zhTW', '以贊達拉帝國之名，又一位敵人倒下了。', '', 28153),
(153376, 'zhTW', '這個可惡的怪物對我們的部隊是一大威脅。消滅它，為了聯盟！', '', 28153),
(153375, 'zhTW', '我不會在我的國界內容忍這種事。立刻將其消滅！', '', 28153),
(153374, 'zhTW', '準備好就跳上三輪車吧。', '', 28153),
(153372, 'zhTW', '', '這些納迦非常害怕，除了對艾薩拉女王的忠誠外，還有某種東西正在驅使他們。', 28153),
(153371, 'zhTW', '', '你好啊。', 28153),
(153370, 'zhTW', '什麼，就這樣而已嗎？給我來點真正的挑戰吧！', '', 28153),
(153369, 'zhTW', '天啊，太好玩了！', '', 28153),
(153368, 'zhTW', '你到此為止了。', '', 28153),
(153367, 'zhTW', '幫我問候你的列祖列宗！', '', 28153),
(153366, 'zhTW', '我不會善罷干休！', '', 28153),
(153365, 'zhTW', '動作要一氣呵成。', '', 28153),
(153364, 'zhTW', '哈哈哈！我們就是這樣幹的！', '', 28153),
(153363, 'zhTW', '給我滾開！', '', 28153),
(153362, 'zhTW', '為了卡茲莫丹！', '', 28153),
(153361, 'zhTW', '這個送你！', '', 28153),
(153360, 'zhTW', '來試試這招吧。', '', 28153),
(153359, 'zhTW', '嘿，接招吧！', '', 28153),
(153357, 'zhTW', '你的戰鬥結束了！', '', 28153),
(153351, 'zhTW', '麥格尼，艾澤拉斯要給我什麼？', '麥格尼，艾澤拉斯要給我什麼？', 28153),
(153350, 'zhTW', '擊退這些猩猩以後，我們就可以全力對付部落了。做得好。', '', 28153),
(153349, 'zhTW', '這些猩猩吸收了卡迦邁的精華，因此獲得非常驚人的智力。絕對不能讓這些猩猩越過牠們居住的峽谷。', '', 28153),
(153348, 'zhTW', '偵測到A.T.O.M.I.K.發射', '偵測到A.T.O.M.I.K.發射', 28153),
(153347, 'zhTW', '部落的人要是以為能俘虜我們，那就真的太愚蠢了。感謝你，我們的人終於脫困了。做得好！', '', 28153),
(153346, 'zhTW', '我的一個人還下落不明，我根本無法安心。', '我的一個人還下落不明，我根本無法安心。', 28153),
(153345, 'zhTW', '我們真是神不知鬼不覺。哈！真是太感謝你了，勇士。', '', 28153),
(153344, 'zhTW', '部落的人要是以為能在祖達薩這裡監視我們的行動，那就錯了！消滅他們的耳目，讓他們知道我們聯盟是屹立不搖的！', '', 28153),
(153343, 'zhTW', '我再也不會不帶鑰匙就進到裡面去！', '我再也不會不帶鑰匙就進到裡面去！', 28153),
(153342, 'zhTW', '再多在那東西裡頭待一分鐘，就糟糕了！', '再多在那東西裡頭待一分鐘，就糟糕了！', 28153),
(153341, 'zhTW', '為什麼索爾加登一直把我們關在那些錫罐裡？嗄！', '為什麼索爾加登一直把我們關在那些錫罐裡？嗄！', 28153),
(153340, 'zhTW', '那裡比拉格納羅斯的火焰之座還熱！', '那裡比拉格納羅斯的火焰之座還熱！', 28153),
(153339, 'zhTW', '我會派人通知龍禍，告訴他我們順利拿下這個區域。謝謝你的協助，$n。', '', 28153),
(153338, 'zhTW', '這只是盡本分而已！', '', 28153),
(153337, 'zhTW', '好可怕啊！', '', 28153),
(153336, 'zhTW', '我們正從火源之界汲取力量，但不會因此召來危險的事物。', '', 28153),
(153335, 'zhTW', '別讓在那邊無故抖鬍子，塞林，我不像巫士族長索瑞森那麼蠢。', '', 28153),
(153334, 'zhTW', '召喚東西要小心，鐵砧族長。', '', 28153),
(153333, 'zhTW', '準備大顯身手了，弟兄們。你已經控制它了，$n。讓部落的人看看，惹惱黑鐵會有什麼下場！', '', 28153),
(153332, 'zhTW', '$C，把一些熔渣放在不穩定的熔岩上，然後做好準備。', '', 28153),
(153331, 'zhTW', '激流堡之役開打了！', '', 28153),
(153330, 'zhTW', '距離激流堡之役開始還有30秒。', '', 28153),
(153329, 'zhTW', '好，沒問題。', '', 28153),
(153328, 'zhTW', '等等，你帶著鑰匙吧？', '', 28153),
(153327, 'zhTW', '看來我的薩滿還在鑽地機裡面，就知道我忘了什麼東西。', '', 28153),
(153326, 'zhTW', '我們在這裡有個好的開始，還缺什麼？', '', 28153),
(153325, 'zhTW', '你不知道這裡的力量是什麼，孩子。', '', 28153),
(153324, 'zhTW', '<探進裡面，把某個東西感覺像是建築物的東西拔出來。>', '<探進裡面，把某個東西感覺像是建築物的東西拔出來。>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153323, 'zhTW', '<探進裡面，把某個東西拔出來。>', '<探進裡面，把某個東西拔出來。>', 28153),
(153322, 'zhTW', '<有道蟲洞在你眼前延伸。看來你應該要想辦法利用這個來產生建築。>', '', 28153),
(153321, 'zhTW', '別考驗我的耐心，蟲子。去死吧。', '', 28153),
(153320, 'zhTW', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_CTHUN.BLP:20|t%s開始施放|cFFFF0000|Hspell:264382|h[邪眼光束]|h|r！', '遠方出現了一道投影…', 28153),
(153319, 'zhTW', '大海是我們的家，但某種東西讓我們無法回家，希望你能對付它！', '', 28153),
(153318, 'zhTW', '你要見追尋者是嗎？他們都是強者，你在這裡會非常安全。', '', 28153),
(153317, 'zhTW', '船不見了。風暴憑空出現，恐怕其他人是兇多吉少了。', '', 28153),
(153316, 'zhTW', '謠傳海岸似乎發生奇怪的事。', '', 28153),
(153315, 'zhTW', '遵命。', '', 28153),
(153314, 'zhTW', '還有…請好好照顧珍娜。', '', 28153),
(153313, 'zhTW', '想辦法在庫爾提拉斯設置營地。這計畫絕對不能失敗。', '', 28153),
(153312, 'zhTW', '派一艘第七軍團的船艦護送珍娜。', '', 28153),
(153311, 'zhTW', '哼，當然沒問題。', '', 28153),
(153310, 'zhTW', '願深海拒絕你，就像你拒絕人民。', '', 28153),
(153309, 'zhTW', '你的存在只代表憎恨和折磨。', '', 28153),
(153308, 'zhTW', '風暴逐漸甦醒，你的死期已近。', '', 28153),
(153307, 'zhTW', '別怕，你的審判很快就來了。', '', 28153),
(153306, 'zhTW', '吉恩…你還能航海嗎？', '', 28153),
(153305, 'zhTW', '仔細聽人民的哭號，你的死期馬上就到了。', '', 28153),
(153304, 'zhTW', '你不可能得到救贖。', '', 28153),
(153303, 'zhTW', '你得到你想要的了。', '', 28153),
(153302, 'zhTW', '願你的靈魂永遠受到磨難。', '', 28153),
(153301, 'zhTW', '', '只要我一拿到武器…', 28153),
(153300, 'zhTW', '', '他們沒殺掉我。這是他們的一大錯誤。', 28153),
(153299, 'zhTW', '', '他們破壞我的農場，還敢獵捕我。決不能讓他們就這樣逃走！', 28153),
(153298, 'zhTW', '不解決這場威脅，我是不會走的！', '不解決這場威脅，我是不會走的！', 28153),
(153297, 'zhTW', '他們要為自己的所作所為付出代價！', '他們要為自己的所作所為付出代價！', 28153),
(153296, 'zhTW', '我要痛打這群野豬人一頓！', '我要痛打這群野豬人一頓！', 28153),
(153295, 'zhTW', '', '有空再回來談談生意。', 28153),
(153294, 'zhTW', '', '終於自由了！我要讓這些臭豬看看在我農場搗亂的後果！', 28153),
(153293, 'zhTW', '嘿，你終於醒了。', '', 28153),
(153292, 'zhTW', '不要…相信…喔那海洋之女…嗯嗯…嗯嗯…', '', 28153),
(153291, 'zhTW', '把…那東西拿開。我只…想要灌醉…我自己！*嗝！*', '把…那東西拿開。我只…想要灌醉…我自己！*嗝！*', 28153),
(153290, 'zhTW', '在我姊妹的老公展開一場長達四個月的旅程前，他給了她一隻海莖草，結果第三天花就謝了。這讓她悲傷到難以自己，但由於她很早就知道這件事，所以她還能把財產分配好，供養她的孩子。', '在我姊妹的老公展開一場長達四個月的旅程前，他給了她一隻海莖草，結果第三天花就謝了。這讓她悲傷到難以自己，但由於她很早就知道這件事，所以她還能把財產分配好，供養她的孩子。', 28153),
(153289, 'zhTW', '我們在樓上和地下室的房間裡放了行軍床，用來堆你們的裝備。\n\n雖然這點努力不算什麼，但總比在外面跟女巫在一起好。', '我們在樓上和地下室的房間裡放了行軍床，用來堆你們的裝備。\n\n雖然這點努力不算什麼，但總比在外面跟女巫在一起好。', 28153),
(153288, 'zhTW', '有些水手認為它們會帶來厄運，幾乎等於玩火自焚。其他人則希望自己所愛之人不需要等待壞消息來臨。我對這兩種人都沒意見。', '有些水手認為它們會帶來厄運，幾乎等於玩火自焚。其他人則希望自己所愛之人不需要等待壞消息來臨。我對這兩種人都沒意見。', 28153),
(153287, 'zhTW', '記得，只要樹沒倒，我們也不能倒下。我們不能在這裡送命。', '', 28153),
(153286, 'zhTW', '讓我們找到我們的親族。只要同心協力，我們或許就能讓佐司瓦恢復部分原狀。', '', 28153),
(153285, 'zhTW', '', '但－－？', 28153),
(153284, 'zhTW', '小樹苗，我們所有重要的東西都在林地。如果蘑菇人沒有攻擊，從南方來的腐化早就抵達我們這裡。', '', 28153),
(153283, 'zhTW', '', '去？去哪裡？梣木林地是我們的家，莫爾溫。而它現在被胞子覆蓋。我們不能就這樣一走了之！', 28153),
(153282, 'zhTW', '艾蜜莉，做的好。那我想我們現在該走了。', '', 28153),
(153278, 'zhTW', '關於這海莖草你能告訴我什麼？', '關於這海莖草你能告訴我什麼？', 28153),
(153277, 'zhTW', '打鼓', '打鼓', 28153),
(153276, 'zhTW', '|cFF0000FF(任務)|r航向祖達薩。', '|cFF0000FF(任務)|r航向祖達薩。', 28153),
(153275, 'zhTW', '啊，我的力量開始恢復了！', '', 28153),
(153274, 'zhTW', '這裡本來蠻平靜的。但接著風暴來襲。然後其他追尋者一去不返，$c。外面到底發生什麼事了？', '', 28153),
(153273, 'zhTW', '萬分感謝，我決定獻上一些我個人的小收藏，謝謝你出力。我必須繼續上路了，你很厲害！', '', 28153),
(153272, 'zhTW', '老實說，我似乎陷入一點小麻煩，做個好人，助我一臂之力吧。', '', 28153),
(153271, 'zhTW', '喔，謝了，你真是太好心了。這是給你的小東西，再會！', '喔，謝了，你真是太好心了。這是給你的小東西，再會！', 28153),
(153270, 'zhTW', '', '那邊那個！幫我個忙，寶貝！這裡只有我一個人，非常絕望，你知道嗎？', 28153),
(153269, 'zhTW', '喔，你知道我不能把身上的艾澤萊晶岩都給你，這些已經足以報答你，然後你就趕快離開吧，別擋我的路。', '', 28153),
(153268, 'zhTW', '好的好的，你可以幫我脫離困境嗎？', '', 28153),
(153267, 'zhTW', '聽好，這只是扮裝！看到了嗎？你摸摸看！$b$b這下你可以去叫他們放過我了嗎？我只不過是開個玩笑！霍格並沒有在危害暴風城！', '聽好，這只是扮裝！看到了嗎？你摸摸看！$b$b這下你可以去叫他們放過我了嗎？我只不過是開個玩笑！霍格並沒有在危害暴風城！', 28153),
(153266, 'zhTW', '', '謝謝你！我想你應該想要一些艾澤萊晶岩，我覺得這非常公平。', 28153),
(153265, 'zhTW', '', '喂，那邊那個誰！你能夠救我出來嗎？', 28153),
(153264, 'zhTW', '', '我想我是咎由自取。', 28153),
(153263, 'zhTW', '', '我罪有應得…', 28153),
(153262, 'zhTW', '她、她是回來殺光我們的！', '', 28153),
(153261, 'zhTW', '兇手！', '兇手！', 28153),
(153260, 'zhTW', '叛徒！', '叛徒！', 28153),
(153259, 'zhTW', '是海洋之女！', '', 28153),
(153258, 'zhTW', '', '珍娜女士…真的是珍娜女士嗎？', 28153),
(153257, 'zhTW', '', '喂，該回家了，快點！', 28153),
(153256, 'zhTW', '媽媽，那個女生是誰？', '媽媽，那個女生是誰？', 28153),
(153255, 'zhTW', '哈姆雷特…你再也不會是塊菌了…', '', 28153),
(153254, 'zhTW', '我的頭…我的豬怎麼了！', '', 28153),
(153253, 'zhTW', '我會把你今天的偉大事蹟流傳下去，呃…請你一定要贏！', '', 28153),
(153252, 'zhTW', '回到緋紅森林去！', '回到緋紅森林去！', 28153),
(153250, 'zhTW', '別讓老百姓靠近！拉起防線！', '', 28153),
(153249, 'zhTW', '%s落荒而逃。', '%s落荒而逃。', 28153),
(153248, 'zhTW', '', '現在我卻成為囚犯…', 28153),
(153247, 'zhTW', '', '看來這裡的衛隊依然訓練有素。父親一直都以他們為榮。', 28153),
(153246, 'zhTW', '不要催我！我正在試著救你的主人！', '', 28153),
(153245, 'zhTW', '嘿，$n！在這裡！', '嘿，$n！在這裡！', 28153),
(153244, 'zhTW', '我實在太不走運了！我正在前往多瓦薩的路上，但我的馱獸卻病倒了，而且「福無雙至，禍不單行」的俗語偏偏又應驗了。', '', 28153),
(153243, 'zhTW', '我是萊利！', '我是萊利！', 28153),
(153242, 'zhTW', '外面有一大堆部落的人可以放血，留一些給我，好嗎？', '外面有一大堆部落的人可以放血，留一些給我，好嗎？', 28153),
(153241, 'zhTW', '我想看它受苦。', '我想看看它痛苦的模樣。', 28153),
(153240, 'zhTW', '我們奉命殺掉這東西。', '我們奉命殺掉這東西。', 28153),
(153239, 'zhTW', '', '別走散，朋友。絕對不能被發現。', 28153),
(153238, 'zhTW', '', '保持專注。', 28153),
(153237, 'zhTW', '', '你是故意想讓我們被發現嗎？', 28153),
(153236, 'zhTW', '喂，波里斯…我們偷拐搶騙的日子好像結束了…', '', 28153),
(153235, 'zhTW', '你的手離我的野獸遠一點！', '', 28153),
(153234, 'zhTW', '這才像話。看看這麼多的艾澤萊晶岩！', '', 28153),
(153233, 'zhTW', '首領！你到了！', '', 28153),
(153231, 'zhTW', '讓開！有危險的囚犯來了！', '', 28153),
(153230, 'zhTW', '站住！報上名字、目的！', '', 28153),
(153229, 'zhTW', '', '現在不是亂跑的時候。', 28153),
(153228, 'zhTW', '閉…閉嘴。', '', 28153),
(153227, 'zhTW', '喔…說不定是女巫做的！', '', 28153),
(153226, 'zhTW', '這又是你的斥候，加里維克斯…而且這個是死的。', '', 28153),
(153225, 'zhTW', '我們必須進入城市的中心，疏散剩下的居民！', '', 28153),
(153224, 'zhTW', '小-小心...', '', 28153),
(153223, 'zhTW', '', '我們快到了！各位英雄，加快腳步！', 28153),
(153222, 'zhTW', '', '繼續前進！', 28153),
(153220, 'zhTW', '勇士們，跟我來！在城堡集合！這是大酋長的命令！', '', 28153),
(153217, 'zhTW', '', '薩魯法爾！你去哪了？', 28153),
(153216, 'zhTW', '小心，崩塌的田地依然危險！右方的道路應該比較安全。你可以從那前往風車，在往後走一點就是迪爾的農場了。', '', 28153),
(153215, 'zhTW', '', '你願意幫個忙的話，我可是非常歡迎喔。', 28153),
(153214, 'zhTW', '', '我的藥水沒了，可是貨車之前還有一大堆塞斯拉克人。', 28153),
(153213, 'zhTW', '', '你還活著啊？你身上有沒有武器可以借我？', 28153),
(153212, 'zhTW', '', '壞蛇人，知道厲害了吧！', 28153),
(153211, 'zhTW', '請送我回到入口。', '請送我回到入口。', 28153),
(153210, 'zhTW', '多虧你與你盟友的努力，瑟沙利斯化身重新獲得了力量。', '多虧你與你盟友的努力，瑟沙利斯化身重新獲得了力量。', 28153),
(153209, 'zhTW', '麥格尼，送我回贊達拉。', '麥格尼，送我回贊達拉。', 28153),
(153207, 'zhTW', '這個東西可以把我們送往目的地！勇士，跟我來。', '', 28153),
(153206, 'zhTW', '擊敗所有剩下的入侵者。', '擊敗所有剩下的入侵者。', 28153),
(153205, 'zhTW', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|t化身加入你的行列，|cFFFF0000|Hspell:269670|h[強化]|h|r你讓你結束這場戰鬥！', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|t化身加入你的行列，|cFFFF0000|Hspell:269670|h[強化]|h|r你讓你結束這場戰鬥！', 28153),
(153204, 'zhTW', '<瑟沙利斯化身就在你的眼前。她雖然還活著，卻因為食人妖的擾亂而十分虛弱。你四周的古老防衛結界開始發光啟動…>', '<瑟沙利斯化身就在你的眼前。她雖然還活著，卻因為食人妖的擾亂而十分虛弱。你四周的古老防衛結界開始發光啟動…>', 28153),
(153203, 'zhTW', '|cffffff00+$1i木頭|r', '|cffffff00+$1i木頭|r', 28153),
(153202, 'zhTW', '你們聽到公主說的了！上吧！', '', 28153),
(153201, 'zhTW', '', '你們看！護盾要消失了！', 28153),
(153199, 'zhTW', '千萬別緊張！雖然我登場的方式有點突兀…我是麥格尼‧銅鬚，艾澤拉斯的代言人。', '', 28153),
(153198, 'zhTW', '', '啊，你在這裡啊。跟我來，我們有點事情要商量。', 28153),
(153197, 'zhTW', '啊，你在這裡啊，勇士。我有話要跟你說！', '', 28153),
(153196, 'zhTW', '[IGC－與凱瑟琳結盟－珍娜把自己的命運交給凱瑟琳決定。凱瑟琳受到艾胥凡女士的慫恿，將珍娜視為叛徒，讓珍娜被帶走面對審判。「她對我來說已經死了。」玩家被逮捕。]', '[IGC－與凱瑟琳結盟－珍娜把自己的命運交給凱瑟琳決定。凱瑟琳受到艾胥凡女士的慫恿，將珍娜視為叛徒，讓珍娜被帶走面對審判。「她對我來說已經死了。」]', 28153),
(153195, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t 你被|cFFFF0000|Hspell:265212|h[育血]|h|r鎖定了！', ' |TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t你被|cFFFF0000|Hspell:265212|h[育血]|h|r鎖定了！', 28153),
(153194, 'zhTW', '我們會讓你復原！', '我們會讓你復原！', 28153),
(153193, 'zhTW', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t維克提斯開始施放|cFFFF0000|Hspell:265217|h[液化]|h|r！', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t維克提斯開始施放|cFFFF0000|Hspell:265217|h[液化]|h|r！', 28153),
(153192, 'zhTW', '別理加里維克斯。我們要前往佐司瓦打探敵人的位置。賺錢只是次要考量。', '', 28153),
(153191, 'zhTW', '總算…安靜了。', '', 28153),
(153190, 'zhTW', '喔，我死…', '', 28153),
(153189, 'zhTW', '去確認伊崔格和船長都做好準備了。我們要去賺錢！', '', 28153),
(153188, 'zhTW', '你…把我重傷…', '', 28153),
(153187, 'zhTW', '從今以後…我不會再說一個字。', '', 28153),
(153186, 'zhTW', '停止，夠了！', '', 28153),
(153185, 'zhTW', '壞人，你殺了我！', '', 28153),
(153184, 'zhTW', '喔，我被殺了！', '', 28153),
(153183, 'zhTW', '我的靈魂即將離去，我可以…安息了。', '', 28153),
(153182, 'zhTW', '', '不，你休想再傷害我的人民，你的瘋狂行徑到此為止！', 28153),
(153180, 'zhTW', '', '沒錯，公主！', 28153),
(153177, 'zhTW', '為封鎖腐化，創造出三個裝置。', '', 28153),
(153174, 'zhTW', '[帥氣過場動畫。]', '[帥氣過場動畫。]', 28153),
(153173, 'zhTW', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t維克提斯開始施放|cFFFF0000|Hspell:266948|h[瘟疫炸彈]|h|r!', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t維克提斯開始施放|cFFFF0000|Hspell:266948|h[瘟疫炸彈]|h|r!', 28153),
(153172, 'zhTW', '', '古神？難怪鮮血食人妖跑來侵略贊達拉的城市…', 28153),
(153171, 'zhTW', '資料修復完畢。古神腐化封鎖於納茲米爾之內。', '', 28153),
(153169, 'zhTW', '…還有一點一加侖的龍舌蘭酒！', '…還有一點一加侖的龍舌蘭酒！', 28153),
(153168, 'zhTW', '|cFF0000FF(任務)|r航向佐司瓦。', '|cFF0000FF(任務)|r航向佐司瓦。', 28153),
(153167, 'zhTW', '', '女妖之嚎是黑暗女王最好的船艦。外表看起來可能沒什麼，但是她非常堅固，而且鬥志激昂。\n\n這艘船的船長也很厲害。', 28153),
(153166, 'zhTW', '是的，我已經準備好去佐斯瓦了。', '是的，我已經準備好去佐斯瓦了。', 28153),
(153165, 'zhTW', '不要讓那個哥布林誤導你，$n。我們的任務不只是盡可能搜刮艾澤萊晶岩，而是收集關於聯盟的情報。\n\n你準備要離開了嗎？', '', 28153),
(153164, 'zhTW', '別讓貿易親王干擾你。我們的主要任務是偵察…不是賺錢。', '', 28153),
(153163, 'zhTW', '聽說那裡有一大堆艾澤萊晶岩正等著我們，我們只要盡量收集就好，看你的了。\n\n要是你被殺了，你的帽子就歸我！哈哈！', '', 28153),
(153162, 'zhTW', '繼續治療瑟沙利斯化身，並解決來襲的所有入侵者。', '繼續治療瑟沙利斯化身，並解決來襲的所有入侵者。', 28153),
(153161, 'zhTW', '非常好，英雄。我們必須隨時注意神廟裡面的叢網蜘蛛是不是都清乾淨了。', '', 28153),
(153160, 'zhTW', '叢網蜘蛛在神廟遺跡裡到處肆虐。你去幫忙清掉那些蜘蛛，救出被蛛網困住的信徒。', '', 28153),
(153159, 'zhTW', '將瑟沙利斯化身的生命力恢復至全滿。', '將瑟沙利斯化身的生命力恢復至全滿。', 28153),
(153158, 'zhTW', '鬼鬼祟祟的蜘蛛！', '', 28153),
(153157, 'zhTW', '謝了，$n！我欠你一命。', '', 28153),
(153156, 'zhTW', '我又能呼吸了！謝謝！', '', 28153),
(153155, 'zhTW', '這些蜘蛛什麼都吃！', '', 28153),
(153154, 'zhTW', '謝了！就差一點點…', '', 28153),
(153153, 'zhTW', '我還以為我也完蛋了！', '', 28153),
(153152, 'zhTW', '你對我們有什麼企圖？', '你對我們有什麼企圖？', 28153),
(153151, 'zhTW', '不，求求你…', '不，求求你…', 28153),
(153150, 'zhTW', '', '那就上來吧！勇士，我們會先出發去找艾希頓大師。你到緋紅森林跟我們會合！', 28153),
(153149, 'zhTW', '我的骨頭！好痛！', '好痛！我的骨頭！', 28153),
(153148, 'zhTW', '喔，我怎麼會忘了這個。', '喔，我怎麼會忘了這個。', 28153),
(153147, 'zhTW', '你真無聊，讓我們把你變得…有趣一點。', '你真無聊，讓我們把你變得…有趣一點。', 28153),
(153146, 'zhTW', '告訴我，這會痛嗎？', '告訴我，這會痛嗎？', 28153),
(153145, 'zhTW', '應該可以。', '', 28153),
(153144, 'zhTW', '', '馬騰，你現在可以動身了嗎？', 28153),
(153143, 'zhTW', '鎮裡現在沒事了，可以麻煩你解釋一下這是怎麼回事嗎？', '', 28153),
(153142, 'zhTW', '那當然！我不知道你要我幫什麼忙，但為了拯救我家園的人當然沒問題！\n\n不過，你可能需要再等一下。我敢說城鎮裡現在是一團亂。', '', 28153),
(153141, 'zhTW', '我們得離開這裡！', '我們得離開這裡！', 28153),
(153140, 'zhTW', '他們又來了，不！', '他們又來了，不！', 28153),
(153139, 'zhTW', '如果不是你的話，我早就死了…', '沒有你我早就死了…', 28153),
(153138, 'zhTW', '是部落！他們在這裡做什麼？', '是部落！他們在這裡做什麼？', 28153),
(153137, 'zhTW', '準備啟航了，指揮官！', '準備啟航了，指揮官！', 28153),
(153136, 'zhTW', '我能立刻就把你弄出那裡。你準備好的時候就跟我說一聲。', '', 28153),
(153135, 'zhTW', '你在找艾希頓嗎？跟我來。我沒看到他，倒是看到了他的學徒。', '', 28153),
(153134, 'zhTW', '哇喔，這個味道…心臟不夠強或是腸胃不夠好的人可不能吃。', '', 28153),
(153133, 'zhTW', '我聽說海洋另一頭的沙漠裡，有種點心。幫我帶點禿鷲翅膀和蠍子刺回來，我想做個不太一樣、更帶勁的版本。', '', 28153),
(153132, 'zhTW', '舵手，穩定向前。', '舵手，穩定向前。', 28153),
(153131, 'zhTW', '你著個笨蛋，轉另一邊啦！', '你這個笨蛋，轉另一邊！', 28153),
(153130, 'zhTW', '不潔之人不准進入亡者的殿堂。', '', 28153),
(153129, 'zhTW', '不准再前進了。', '', 28153),
(153128, 'zhTW', '沒人能進來這裡。', '', 28153),
(153127, 'zhTW', '再見。', '', 28153),
(153126, 'zhTW', '嘿。', '', 28153),
(153125, 'zhTW', '', '你…是我沒教好。', 28153),
(153124, 'zhTW', '', '休息時間。', 28153),
(153123, 'zhTW', '', '你們全部都…解散吧。', 28153),
(153122, 'zhTW', '', '上課了！', 28153),
(153121, 'zhTW', '', '該教你三大基礎了！符文、儀式，還有聖物！', 28153),
(153120, 'zhTW', '', '看我好好教訓你！', 28153),
(153119, 'zhTW', '現在誰該監督儲備品？', '', 28153),
(153118, 'zhTW', '這批貨品…已腐壞。', '', 28153),
(153117, 'zhTW', '決不會讓你破壞我們的商店！', '', 28153),
(153116, 'zhTW', '這個收藏僅限賓客瀏覽！', '', 28153),
(153115, 'zhTW', '太好了！這些可以吃很久很久。呃，如果我沒一次吃光的話。', '', 28153),
(153114, 'zhTW', '在這裡，生物適應環境的能力令人驚奇。鞭笞者更是其中的佼佼者，好吃，又多籽！去幫我們帶一些回來，記得要小心上面的刺！', '', 28153),
(153113, 'zhTW', '…我喜歡你的想法，瓦特。', '', 28153),
(153112, 'zhTW', '還是…反正我們已經拿到錢了，乾脆跟海瑟墩說我們受到攻擊…然後把蜜酒喝掉就好？', '', 28153),
(153111, 'zhTW', '很好…現在應該安全了。我們把這些桶子運到海瑟墩吧。', '', 28153),
(153110, 'zhTW', '當你呼叫船艦時，我將外出尋找詹姆斯下落的線索。我可不會讓他留在這些狡猾渾蛋的魔掌之中。', '當你呼叫船艦時，我將外出尋找詹姆斯下落的線索。我可不會讓他留在這些狡猾渾蛋的魔掌之中。', 28153),
(153109, 'zhTW', '那玩意兒絕對是在滴蜂蜜！', '', 28153),
(153108, 'zhTW', '過來，你這笨海鷗！', '', 28153),
(153107, 'zhTW', '喔…我完全準備好了。讓我看看你有什麼吧，大自然！', '', 28153),
(153106, 'zhTW', '我們動手吧！', '我們動手吧！', 28153),
(153105, 'zhTW', '這裡隨時會出現更多兇猛的野獸，$c。保護蜂蜜酒，想成好像你的命都靠它了！', '', 28153),
(153103, 'zhTW', '把頭抬起來，Bradford！我們不能讓他們看輕我們！', '', 28153),
(153102, 'zhTW', '好，瓦特，這就是我們的下場了。我不知道我們還能擊退幾頭這些野獸！', '', 28153),
(153101, 'zhTW', '%s將徹底充能的艾澤萊晶岩火砲轉向攻城塔。', '', 28153),
(153100, 'zhTW', '$n！我們需要你，快點！', '$n！我們需要你，快點！', 28153),
(153099, 'zhTW', '該死，李奧納德，我沒有准許你去探路！', '該死，李奧納德，我沒有准許你去探路！', 28153),
(153098, 'zhTW', '你們其餘人跟我來，我們將從他們的側翼繞過去。', '你們其餘人跟我來，我們將從他們的側翼繞過去。', 28153),
(153097, 'zhTW', '太迷人了，真是一群纖細可愛的小旅客。不知道我會在他們身上發現什麼。', '', 28153),
(153096, 'zhTW', '一般振翅蛾的壽命只有幾個月，不過這邊的振翅蛾有點特別。請多帶一些蛾給我，記得要溫柔小心，這些蛾非常脆弱。', '', 28153),
(153093, 'zhTW', '', '現在誰來照看土地?', 28153),
(153092, 'zhTW', '', '大地乃是我的歸處。', 28153),
(153091, 'zhTW', '', '你是很好的肥料。', 28153),
(153090, 'zhTW', '', '你會自食其果！', 28153),
(153089, 'zhTW', '', '我的花園的侵入者！', 28153),
(153088, 'zhTW', '', '四分五裂。', 28153),
(153087, 'zhTW', '', '我的計畫…被破壞了。', 28153),
(153086, 'zhTW', '', '我的編織預示你的末日！', 28153),
(153085, 'zhTW', '', '你的死期不遠！', 28153),
(153084, 'zhTW', '', '我要把你們的靈魂織入掛毯！', 28153),
(153083, 'zhTW', '該是結束這場追獵的時候了。', '', 28153),
(153082, 'zhTW', '居然如此殘暴。', '', 28153),
(153081, 'zhTW', '想不到…我會變成戰利品。', '', 28153),
(153080, 'zhTW', '該發動攻擊了！', '', 28153),
(153079, 'zhTW', '你們會成為我牆上美麗的戰利品！', '', 28153),
(153078, 'zhTW', '狩獵開始囉！', '', 28153),
(153077, 'zhTW', '有新鮮的肉可烤了！', '', 28153),
(153076, 'zhTW', '有晚餐吃了！', '', 28153),
(153075, 'zhTW', '我們必須重新打開祭壇。這是我們得救的機會！', '', 28153),
(153074, 'zhTW', '黑暗也阻擋不了我們的道路。', '', 28153),
(153073, 'zhTW', '非常好，我們絕對不能忘記那些英勇的峽谷甲蟲，牠們獻出自己的生命，從拉卡塔卡王手中救了所有人！', '', 28153),
(153072, 'zhTW', '對狐狸人來說，你這樣是要殺頭的。', '', 28153),
(153071, 'zhTW', '看來，紀律和得體的行為，都不是你的專長或天賦。', '', 28153),
(153070, 'zhTW', '萬物皆有其價值，就算是你也一樣。', '', 28153),
(153069, 'zhTW', '沙漠裡可是適者生存。', '', 28153),
(153068, 'zhTW', '沙塵將會指引我們道路。', '', 28153),
(153067, 'zhTW', '沙漠會引導我們。', '', 28153),
(153066, 'zhTW', '我們需要的一切，盡在沙漠之中。', '', 28153),
(153065, 'zhTW', '渡過沙塵的考驗，代表在被遺忘的事物中找到價值。', '', 28153),
(153064, 'zhTW', '記住，天生我材必有用。', '', 28153),
(153063, 'zhTW', '有話就說吧。', '', 28153),
(153062, 'zhTW', '你好。', '', 28153),
(153061, 'zhTW', '你帶了什麼過來嗎？', '', 28153),
(153060, 'zhTW', '你是來買東西的嗎？', '', 28153),
(153059, 'zhTW', '需要什麼嗎？', '', 28153),
(153058, 'zhTW', '', '贊達拉屹立不搖。', 28153),
(153057, 'zhTW', '', '一切小心。', 28153),
(153056, 'zhTW', '', '被放逐到沙漠是最殘忍的酷刑。', 28153),
(153055, 'zhTW', '', '我能為你做什麼？', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153054, 'zhTW', '', '有話快說。', 28153),
(153053, 'zhTW', '', '我在聽。', 28153),
(153052, 'zhTW', '', '嗯？', 28153),
(153051, 'zhTW', '我們絕不放棄。', '我們絕不放棄。', 28153),
(153050, 'zhTW', '我們會推翻無信者的帝國。', '我們會推翻無信者的帝國。', 28153),
(153049, 'zhTW', '願瑟沙利斯保佑所有人。', '願瑟沙利斯保佑所有人。', 28153),
(153048, 'zhTW', '引發這場戰爭的是科爾塞克。', '引發這場戰爭的是科爾塞克。', 28153),
(153047, 'zhTW', '我們要堅持下去。', '我們要堅持下去。', 28153),
(153046, 'zhTW', '你是來幫忙的嗎？', '你是來幫忙的嗎？', 28153),
(153045, 'zhTW', '骨徑峽谷受到拉卡塔卡王威脅！他非常強大，不能正面對抗，不過他吃起東西貪得無饜。你一直給他東西吃，他會吃到撐死自己！', '', 28153),
(153044, 'zhTW', '對狐狸人來說，你這樣是要殺頭的。', '對狐狸人來說，你這樣是要殺頭的。', 28153),
(153043, 'zhTW', '看來，紀律和得體的行為，都不是你的專長或天賦。', '看來，紀律和得體的行為，都不是你的專長或天賦。', 28153),
(153042, 'zhTW', '萬物都有其價值，就算是你也一樣。', '萬物都有其價值，就算是你也一樣。', 28153),
(153041, 'zhTW', '動作要快，腦筋要好。', '動作要快，腦筋要好。', 28153),
(153040, 'zhTW', '要生存就要夠有本事。', '要生存就要夠有本事。', 28153),
(153039, 'zhTW', '記住，天生我材必有用！', '記住，天生我材必有用！', 28153),
(153038, 'zhTW', '我們需要的一切，盡在沙漠之中。', '我們需要的一切，盡在沙漠之中。', 28153),
(153037, 'zhTW', '自己千萬小心，沒人能幫你。', '自己千萬小心，沒人能幫你。', 28153),
(153036, 'zhTW', '可別死掉啊。', '可別死掉啊。', 28153),
(153035, 'zhTW', '你帶了什麼來給我？', '你帶了什麼來給我？', 28153),
(153034, 'zhTW', '需要什麼嗎？', '需要什麼嗎？', 28153),
(153033, 'zhTW', '你是來買東西的嗎？', '你是來買東西的嗎？', 28153),
(153032, 'zhTW', '你好。', '你好。', 28153),
(153031, 'zhTW', '有東西要給我嗎？', '有東西要給我嗎？', 28153),
(153030, 'zhTW', '下次出去冒險，幫我帶個紀念品回來！', '下次出去冒險，幫我帶個紀念品回來！', 28153),
(153029, 'zhTW', '我們現在是朋友了嗎？', '我們現在是朋友了嗎？', 28153),
(153028, 'zhTW', '謝謝你願意跟我聊聊。', '謝謝你願意跟我聊聊。', 28153),
(153027, 'zhTW', '你現在正展開偉大的冒險嗎？太讓人著迷了！', '你現在正展開偉大的冒險嗎？太讓人著迷了！', 28153),
(153026, 'zhTW', '你曾故意吃下沙子嗎？', '你曾故意吃下沙子嗎？', 28153),
(153025, 'zhTW', '如果你死了，我可以拿走你的東西嗎？', '如果你死了，我可以拿走你的東西嗎？', 28153),
(153024, 'zhTW', '我們絕不放棄。', '', 28153),
(153023, 'zhTW', '我們會推翻無信者的帝國。', '', 28153),
(153022, 'zhTW', '願瑟沙利斯保佑所有人。', '', 28153),
(153021, 'zhTW', '引發這場戰爭的是科爾塞克。', '', 28153),
(153020, 'zhTW', '我們要堅持下去。', '', 28153),
(153019, 'zhTW', '你是來幫忙的嗎？', '', 28153),
(153018, 'zhTW', '做我們該做的事。', '', 28153),
(153017, 'zhTW', '瑟沙利斯會保佑所有人。', '', 28153),
(153016, 'zhTW', '無信者休想佔領我們的神廟。', '', 28153),
(153015, 'zhTW', '引發這場戰爭的是科爾塞克。', '', 28153),
(153014, 'zhTW', '我們要堅持下去。', '', 28153),
(153013, 'zhTW', '你是來幫忙的嗎？', '', 28153),
(153012, 'zhTW', '', '我們當時真不該救你出來。抱歉！我不是那個意思…', 28153),
(153011, 'zhTW', '', '我簡直不相信你還在繼續…', 28153),
(153010, 'zhTW', '', '你最好住手。', 28153),
(153009, 'zhTW', '', '你在做什麼？', 28153),
(153008, 'zhTW', '', '你還會回來吧？', 28153),
(153007, 'zhTW', '', '喂，你不可以死掉喔！', 28153),
(153006, 'zhTW', '', '獨自旅行危險多。', 28153),
(153005, 'zhTW', '', '我看得出來，朵朵很喜歡你。', 28153),
(153004, 'zhTW', '', '我比任何人更了解這片沙漠。', 28153),
(153003, 'zhTW', '', '你好！', 28153),
(153002, 'zhTW', '', '我可以幫忙！', 28153),
(153001, 'zhTW', '', '這座城市絕對不會淪陷。', 28153),
(153000, 'zhTW', '', '一切小心。', 28153),
(152999, 'zhTW', '', '我誓死保護王室的安全。', 28153),
(152998, 'zhTW', '', '我們屹立不搖。', 28153),
(152997, 'zhTW', '', '有話快說。', 28153),
(152996, 'zhTW', '', '嗯？', 28153),
(152995, 'zhTW', '', '我在聽。', 28153),
(152994, 'zhTW', '願沙漠淨化我的罪孽。', '', 28153),
(152993, 'zhTW', '沙漠危機四伏。', '', 28153),
(152992, 'zhTW', '覆水難收。', '', 28153),
(152991, 'zhTW', '你需要什麼？', '', 28153),
(152990, 'zhTW', '有我能幫忙的地方，就說吧。', '', 28153),
(152989, 'zhTW', '是我自找的。', '', 28153),
(152988, 'zhTW', '不想死，就快滾。', '', 28153),
(152987, 'zhTW', '我在注意你的一舉一動。', '', 28153),
(152986, 'zhTW', '你最好小心。', '', 28153),
(152985, 'zhTW', '你不該來這裡。', '', 28153),
(152984, 'zhTW', '我可沒有時間理你。', '', 28153),
(152983, 'zhTW', '你有什麼事？', '', 28153),
(152982, 'zhTW', '願風暴指引你。', '', 28153),
(152981, 'zhTW', '無須畏懼風暴。', '', 28153),
(152980, 'zhTW', '不經混亂，無以洞悉。', '', 28153),
(152979, 'zhTW', '風暴正在呼喚。', '', 28153),
(152978, 'zhTW', '這裡什麼人都歡迎。', '', 28153),
(152977, 'zhTW', '我就是風暴。', '', 28153),
(152976, 'zhTW', '有什麼事？', '', 28153),
(152975, 'zhTW', '饗宴結束了！', '', 28153),
(152973, 'zhTW', '', '我好像該換一頂新的骨頭頭盔了…', 28153),
(152972, 'zhTW', '', '喔對了，從前從前，有隻塞斯拉克人戳了我一下…一下而已。', 28153),
(152971, 'zhTW', '', '', 28153),
(152970, 'zhTW', '', '祝你順心又如意，武器靈活又鋒利。', 28153),
(152969, 'zhTW', '', '要讓他們害怕。', 28153),
(152968, 'zhTW', '', '留些塞斯拉克人給我。', 28153),
(152967, 'zhTW', '', '不要輕言放棄。', 28153),
(152966, 'zhTW', '', '', 28153),
(152965, 'zhTW', '', '今天很適合戰鬥。對啦，天天都適合。', 28153),
(152964, 'zhTW', '', '狐狸人可不像外表那麼柔弱。', 28153),
(152963, 'zhTW', '', '我一定會救回同胞。', 28153),
(152962, 'zhTW', '', '我準備好要作戰了。', 28153),
(152961, 'zhTW', '我為神王而生。', '', 28153),
(152960, 'zhTW', '保持警戒別鬆懈。', '', 28153),
(152959, 'zhTW', '願羅亞與你同在。', '', 28153),
(152958, 'zhTW', '贊達拉屹立不搖。', '', 28153),
(152957, 'zhTW', '我勇於面對危險。', '', 28153),
(152956, 'zhTW', '我們會擊倒敵人！', '', 28153),
(152955, 'zhTW', '', '很好，我知道你一定不會。', 28153),
(152954, 'zhTW', '我們不會讓你失望的…女王。', '', 28153),
(152953, 'zhTW', '', '想接下這個任務嗎？', 28153),
(152952, 'zhTW', '', '你們得潛入暴風城，救出一位政治犯，這個人會讓局勢對我們比較…有利。', 28153),
(152951, 'zhTW', '', '那個小鬼國王手上有不屬於他的東西。我要拿回來。', 28153),
(152950, 'zhTW', '', '部落想要贏，就需要盟友。', 28153),
(152949, 'zhTW', '', '其實，我想得很透徹。', 28153),
(152948, 'zhTW', '', '有些部落成員覺得我最近的行為似乎有點…思慮欠周。', 28153),
(152947, 'zhTW', '', '我有件事情，只能交給完全信任的人去辦。', 28153),
(152946, 'zhTW', '', '啊，終於來了，才正好在想你跑哪去了。', 28153),
(152945, 'zhTW', '…對部落很忠誠。', '', 28153),
(152944, 'zhTW', '諫言者都很忠誠…', '', 28153),
(152943, 'zhTW', '或許女王如果更能確信諫言者忠誠，就會比較願意坦言。', '', 28153),
(152942, 'zhTW', '如果大酋長不願和諫言者討論事情，我們要怎麼協助她？', '', 28153),
(152941, 'zhTW', '這不關你的事。', '', 28153),
(152940, 'zhTW', '大酋長召見你了嗎？', '', 28153),
(152939, 'zhTW', '詳情連我都不清楚。', '', 28153),
(152938, 'zhTW', '大酋長有個任務要你去做，而且這個任務非常重要…非常隱密。', '', 28153),
(152937, 'zhTW', '叫你的朋友去金牙旅店！', '', 28153),
(152936, 'zhTW', '別忘了在訪客登記簿上簽名。', '', 28153),
(152935, 'zhTW', '對我毫無用處。', '', 28153),
(152934, 'zhTW', '唉呀，你拿到香蕉串了嗎？', '', 28153),
(152933, 'zhTW', '金牙始終如一。', '', 28153),
(152932, 'zhTW', '歡迎來到金牙旅店！', '', 28153),
(152931, 'zhTW', '叛變或是走橫桅！', '', 28153),
(152930, 'zhTW', '照顧船員。', '', 28153),
(152929, 'zhTW', '小心變化莫測的大海。', '', 28153),
(152928, 'zhTW', '她悲痛欲絕，因為在塞拉摩那一戰，她失去了丈夫…還有女兒。', '', 28153),
(152927, 'zhTW', '別再碎碎念了！沒必要到處宣傳。', '別再碎碎念了！沒必要到處宣傳。', 28153),
(152926, 'zhTW', '安靜！這邊有個好東西。', '安靜！這邊有個好東西。', 28153),
(152925, 'zhTW', '閉嘴！我們不需要有人提問。', '閉嘴！我們不需要有人提問。', 28153),
(152924, 'zhTW', '贊姆蘭可不是活人待的地方。', '', 28153),
(152923, 'zhTW', '你在找船員？', '', 28153),
(152921, 'zhTW', '喂！', '', 28153),
(152920, 'zhTW', '凱瑟琳一直過得很痛苦。難怪珍娜回來，對她影響這麼大。', '', 28153),
(152918, 'zhTW', '', '必須讓各大家族在普勞德摩爾麾下重新團結。一定要找回失蹤的艦隊，否則我們還沒參戰就會潰散瓦解。', 28153),
(152917, 'zhTW', '我的部族被暮光之錘殲滅了，我能逃出來是因為我兄弟奇蘭讓我騎他的獅鷲獸逃走，救了我一命。\n\n我環遊了大半個世界，才在庫爾提拉斯定居下來。當初我發現這裡的人為了肉和毛皮獵捕獅鷲獸，是我讓他們明白了還有別的選擇。現在他們都是新一代的獅鷲騎士。\n\n我想我不會回老家了。現在這裡是材我的部族。', '', 28153),
(152916, 'zhTW', '帶我回到祖爾詹。', '帶我回到祖爾詹。', 28153),
(152915, 'zhTW', '鋸開中', '鋸開中', 28153),
(152914, 'zhTW', '一個蠻錘氏族的矮人在這裡幹嘛？', '一個蠻錘氏族的矮人在這裡幹嘛？', 28153),
(152913, 'zhTW', '幹完這票，我們就是有錢人了。', '幹完這票，我們就是有錢人了。', 28153),
(152912, 'zhTW', '那些笨蛋完全不清楚腳下東西的價值。', '那些笨蛋完全不清楚腳下東西的價值。', 28153),
(152911, 'zhTW', '我在銀月城有個顧客，願意花大錢買這些聖物。', '我在銀月城有個顧客，願意花大錢買這些聖物。', 28153),
(152910, 'zhTW', '這些東西是送不進博物館的。', '', 28153),
(152907, 'zhTW', '納茲米爾的每件事都怪怪的…整個地方都不太對勁。保持警戒。', '', 28153),
(152906, 'zhTW', '赫茲羅很忙！他到底在下面忙什麼呀？', '', 28153),
(152905, 'zhTW', '我們以為赫茲羅會在戰鬥中幫助我們，但他跑去做他自己的事情了。那個東西在幹什麼？', '', 28153),
(152900, 'zhTW', '不准用髒手碰我的財寶…', '你別太得意…我馬上就回來…', 28153),
(152899, 'zhTW', '這片土地…和我們…都受到詛咒…', '贊姆蘭不肯讓我們安息…這才是真正的詛咒…', 28153),
(152898, 'zhTW', '我什麼也感覺不到…', '打斷你這旱鴨子的狗腿…', 28153),
(152897, 'zhTW', '船長…一定會解決你…', '海盜之王贊姆蘭…會找你算帳…', 28153),
(152896, 'zhTW', '讓我們飛到下頭，和泰坦守衛者赫茲羅會面。', '讓我們飛到下頭，和泰坦守衛者赫茲羅會面。', 28153),
(152895, 'zhTW', '', '我必須稟告父王這裡的局勢。我們雖然獲得了勝利，但是與鮮血食人妖之間的戰爭還沒有結束。', 28153),
(152894, 'zhTW', '', '我絕對不會忘記部落為我們付出多少心力。要是沒有你，我們絕對不可能成功。', 28153),
(152893, 'zhTW', '', '謹遵命令！', 28153),
(152892, 'zhTW', '', '洞穴要塌了！快跑！', 28153),
(152891, 'zhTW', '你要嘛死在這石頭堆裡，要嘛被我的僕人撕碎。反正你是活不到我們勝利的時候了。', '', 28153),
(152890, 'zhTW', '', '我要和你同歸於盡！', 28153),
(152889, 'zhTW', '', '再靠近一點！', 28153),
(152888, 'zhTW', '', '讓我們盡興而歸吧！', 28153),
(152887, 'zhTW', '', '來嘛，給我抱一個！', 28153),
(152886, 'zhTW', '跟我來！動作快，別跟丟了！', '跟我來！動作快點，不要失散！', 28153),
(152885, 'zhTW', '|TInterface\\Icons\\Spell_shadow_mindflay.blp:20|t一名 |cFFFF0000|Hspell:269131|h[遠古屈心魔]|h|r與|cFFFF0000$n|r連接！', '', 28153),
(152884, 'zhTW', '第三艦隊的英雄們，準備戰鬥！立刻向葛雷邁恩國王報到！', '第三艦隊的英雄，打起精神！立刻向葛雷邁恩國王報到！', 28153),
(152883, 'zhTW', '啊，沒事，只不過是酒而已。', '', 28153),
(152882, 'zhTW', '', '.', 28153),
(152881, 'zhTW', '', '我們的部隊會擋住剩下的鮮血食人妖，但是恐怕撐不了多久。我們必須盡快完成任務。', 28153),
(152880, 'zhTW', '', '.', 28153),
(152879, 'zhTW', '', '可是已經好幾個月沒有艦隊的消息了！浪潮賢者紛紛隱居，似乎不想幫我們尋找失蹤的艦隊。', 28153),
(152878, 'zhTW', '', '威奎斯特家族數百年來都對普勞德摩爾忠心耿耿，只是最近他們不再出席會議，也開始出現奇怪的謠言。', 28153),
(152877, 'zhTW', '回來，寶貝！', '', 28153),
(152876, 'zhTW', '我不打算等它變涼。', '我不打算等它變涼。', 28153),
(152875, 'zhTW', '讓我死，伯昂撒姆第…求求你…', '', 28153),
(152874, 'zhTW', '有話快說。', '', 28153),
(152873, 'zhTW', '', '我們會繼續我們的…你怎麼用這種眼神看我啊？你有意見嗎？', 28153),
(152872, 'zhTW', '立刻，好的，沒問題，絕不拖延！', '', 28153),
(152871, 'zhTW', '哎，不是我見過最糟的。還是很不幸就是了，我們需要派出信使，讓高階指揮官知道發生了什麼事。', '', 28153),
(152870, 'zhTW', '噢，天哪，恐怕比我想像的還糟。對於讓你陷入這樣危險的處境，我深感抱歉，銅鬚先生。', '', 28153),
(152869, 'zhTW', '嗯？！小姑娘比喝了月亮蜜酒的魚人還瘋，想把我們這位可愛的$c獻祭給某個叫古翰的血神。', '', 28153),
(152868, 'zhTW', '康拉德上尉…人沒事，我想？', '', 28153),
(152867, 'zhTW', '祖爾納茲曼，我想，或圖爾沃？事實上，我相信他們是一樣的，或幾乎一樣。', '', 28153),
(152866, 'zhTW', '知情與否，是時候追查到底了。這個上尉要去哪裡？', '', 28153),
(152865, 'zhTW', '我…我的天哪。尊敬的康拉德上尉當然對這些怪異的情況一點都不知情。', '', 28153),
(152864, 'zhTW', '哈利的臉突然失去血色。', '', 28153),
(152863, 'zhTW', '這是怎麼回事，哈利？！你發送的那些供品…那些士兵被犧牲了！鮮血從他們的屍體裡流出，就像啤酒節的麥酒一樣。', '', 28153),
(152862, 'zhTW', '真是夠了！在我和$n瞭解狀況之前，他們別想再從我們這拿到紅銅！', '', 28153),
(152861, 'zhTW', '這可是和食人妖做生意！我們甚至還準備了蝙蝠，要當作和札拉瑪洽談進一步交易的供品。', '', 28153),
(152860, 'zhTW', '老天！對、沒錯，我想這項情報很準確。不過，康拉德上尉是個讓我們肅然起敬的對象，這一點無庸置疑。', '', 28153),
(152859, 'zhTW', '聽說這邊的野人會搞獻祭。', '', 28153),
(152858, 'zhTW', '我跟你保證，絕對不會發生什麼意外啦！這檔和食人妖談的生意可是由上尉出馬談成的。', '', 28153),
(152857, 'zhTW', '找不到上尉，發生什麼事？', '', 28153),
(152856, 'zhTW', '啊哈哈！真是直接了當，呵呵。不用擔心，所有的事情都在掌握之中。現在呢，我們就先退回安全的堡壘裡，如何？', '', 28153),
(152855, 'zhTW', '上尉在哪？', '', 28153),
(152854, 'zhTW', '康拉德上尉留給我一些指示。', '', 28153),
(152853, 'zhTW', '我們等你們好久了，敬重的顧問和未來的伙伴們。', '', 28153),
(152852, 'zhTW', '歡迎！歡迎！', '', 28153),
(152851, 'zhTW', '看來我們的接待人員到了。哈利是個很有意思的傢伙，可別不把他當一回事。', '', 28153),
(152850, 'zhTW', '然後…嗯…把鼻子捏起來。那個死人腐臭味是哪來的？', '', 28153),
(152849, 'zhTW', '算了。我說$n啊，你最好招子放亮一點，這個地方只要稍微一個大意，就很可能會送命。', '', 28153),
(152848, 'zhTW', '總之，還是有人和贊達拉與他們的部落同夥們唱反調。俗話說：敵人的敵人就是…後面接什麼？', '', 28153),
(152847, 'zhTW', '我們派康拉德上尉前去蓋座堡壘。他們回報說這一帶的鮮血食人妖或許願意做點生意，不過我覺得代價肯定不便宜。', '', 28153),
(152846, 'zhTW', '這樣不是很好嗎？只要你的心情不美麗，冒險和探求知識的機會就會找上門來。', '', 28153),
(152845, 'zhTW', '這地方讓我毛毛的…', '', 28153),
(152844, 'zhTW', '不過你們是活不到那一天了。來吧，守護者，殺光這些入侵者！', '', 28153),
(152843, 'zhTW', '消滅骯髒的庫爾提拉斯人，奪回我們的土地！', '', 28153),
(152842, 'zhTW', '你們的祖先都是蠢貨…你們也是！', '', 28153),
(152841, 'zhTW', '$n，選一條繩子垂降到登陸艇。祝你好運。', '', 28153),
(152840, 'zhTW', '', '一定還有刻下別的線索，繼續找！', 28153),
(152839, 'zhTW', '', '勾拉圖爾應該死了才對！有人目睹他敗亡的過程！', 28153),
(152838, 'zhTW', '此地的政府授權我們在這裡開啟傳送門。', '此地的政府授權我們在這裡開啟傳送門。', 28153),
(152837, 'zhTW', '這地方到處都是魔法。你能感受到嗎？\n\n我在想，他們在這裡進行怎樣的儀式？', '這地方到處都是魔法。你能感受到嗎？\n\n我在想，他們在這裡進行怎樣的儀式？', 28153),
(152836, 'zhTW', '', '還有個石碑！這上面也有勾拉圖爾。', 28153),
(152835, 'zhTW', '|cFF0000FF(任務)|r航向沃魯敦。', '|cFF0000FF(任務)|r航向沃魯敦。', 28153),
(152834, 'zhTW', '|cFFEF0201+$1i|r |cFFFFFF00艾澤萊晶岩|r', '|cFFEF0201+$1i|r |cFFFFFF00艾澤萊晶岩|r', 28153),
(152833, 'zhTW', '他們說我和鮮血<咳嗽>合作。我想說是「鮮血精靈」嗎？他們又講了一次鮮血<咳嗽>。\n\n鮮血食人妖！可不是什麼精靈。這兩個可差多了。', '', 28153),
(152832, 'zhTW', '', '是的，長官！', 28153),
(152831, 'zhTW', '', '等等…這是怎麼回事？', 28153),
(152830, 'zhTW', '團結，才有力量。', '', 28153),
(152829, 'zhTW', '…好的，紅色的那種，我在這裡加上註記，還用紅筆圈了起來。多謝你的幫助，不然結果可能就不妙了。', '', 28153),
(152828, 'zhTW', '啊，那邊的。我希望收集這種稀有沙漠之花的標本。請協助我。', '', 28153),
(152827, 'zhTW', '打得漂亮！我會回勝利堡等你。在他們傾巢而出前快走吧。', '', 28153),
(152826, 'zhTW', '我準備好了。', '我準備好了。', 28153),
(152825, 'zhTW', '這景象在世界的這頭很少見。紅鞭笞者的葉子據說有神祕的治療效用。$b$b我想要收集一些，但砍斷它們會讓植物的氣味散發到空氣中，那一定會引起這裡的動物的注意。$b$b在我收割時保護我，我會給予你合適的報償的。', '', 28153),
(152824, 'zhTW', '艾蘭里亞，率領剩下的部隊集中火力消滅敵方軍隊。', '', 28153),
(152823, 'zhTW', '為了部落！', '', 28153),
(152822, 'zhTW', '我的父親為了聯盟付出了一切！問題是，你也打算為部落犧牲這麼多嗎？', '', 28153),
(152821, 'zhTW', '我絕對不會退縮！我呼吸的每一口氣都是為了戰鬥。你又為你的人民付出過什麼？', '', 28153),
(152820, 'zhTW', '你父親是個心懷榮譽的人，小子。你根本就不懂榮譽。', '', 28153),
(152819, 'zhTW', '薩魯法爾，退下吧。這場戰爭不該由你一個人承擔。殺死你也沒有榮譽可言。', '', 28153),
(152818, 'zhTW', '', '我準備好了！', 28153),
(152817, 'zhTW', '大家做得很好！我們繼續行動吧。', '', 28153),
(152816, 'zhTW', '四顆眼珠…世界末日…她要來了！', '', 28153),
(152815, 'zhTW', '無盡的暗影…數不清的手臂…', '', 28153),
(152814, 'zhTW', '$p，我欠你的可多了，我絕對不會忘掉的。\n\n現在我們會幫忙諾拉和其他狐狸人找出贊姆蘭被偷走的寶物。如果你想要不死海盜身上的玩意的話別不好意思，開口就是了。\n\n我們策劃了一場成功的叛變，但我知道贊姆蘭用不著強迫所有船員變得心如蛇蠍，很多人都是自告奮勇的。\n\n如果你得去港口一趟，務必小心。', '', 28153),
(152813, 'zhTW', '我們不能讓維多利亞白白犧牲。她的法杖就是通往祭壇的關鍵。', '', 28153),
(152812, 'zhTW', '叛變直到橫桅端，$p，我會和你一起的。', '', 28153),
(152811, 'zhTW', '你曾經在同一個地方看過這麼多寶藏嗎？\n\n這就是當一輩子的海盜能帶給你的財富，太美了…', '', 28153),
(152810, 'zhTW', '', '<阿娜正在裝睡，她大聲地打呼著。>', 28153),
(152809, 'zhTW', '敲響銅鑼，向海盜之王贊姆蘭發起挑戰，我準備好正面迎戰了。', '', 28153),
(152808, 'zhTW', '我明白了。我們必須讓凱瑟琳‧普勞德摩爾看見我付出慘痛代價才學會的事…', '', 28153),
(152807, 'zhTW', '很好！古代食人妖帝國閃閃發亮的金幣，這可值錢了。這一份是你的！', '', 28153),
(152806, 'zhTW', '我在薩卡拉占庭院找到這根古老的圖騰，它能夠召喚不死生物。你去骨坑那邊，用它把埋在底下的寶藏挖出來！', '', 28153),
(152805, 'zhTW', '唉，算了，我可沒時間陪你鬼混，我要去參加派對！', '', 28153),
(152804, 'zhTW', '這年頭的小鬼，真的很沒耐性，我才正要開始呢！', '', 28153),
(152803, 'zhTW', '你再戳我的話，我就要開始講故事囉。講一個又臭又長又很無聊的故事。', '', 28153),
(152802, 'zhTW', '下次見面再好好聊聊。', '', 28153),
(152801, 'zhTW', '好，你走吧。我還有事要做。', '', 28153),
(152800, 'zhTW', '不用這麼急著走。', '', 28153),
(152799, 'zhTW', '小聲點！', '', 28153),
(152798, 'zhTW', '有什麼故事說來聽聽？', '', 28153),
(152797, 'zhTW', '有啦有啦…我有在聽。', '', 28153),
(152796, 'zhTW', '要是粗心大意，叢林裡的植物可能比動物還要可怕。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152795, 'zhTW', '打死我也不會再來這座礦坑了！', '打死我也不會再來這座礦坑了！', 28153),
(152794, 'zhTW', '不知道是從哪裡竄出來的！', '不知道是從哪裡竄出來的！', 28153),
(152793, 'zhTW', '謝謝你！我還以為我死定了。', '謝謝你！我還以為我死定了。', 28153),
(152792, 'zhTW', '讓我離開這裡！', '讓我離開這裡！', 28153),
(152791, 'zhTW', '', '這樣會拖累你們的。', 28153),
(152790, 'zhTW', '你的臉和我的靴子好像不太熟啊。要不要讓它們碰個面？', '', 28153),
(152789, 'zhTW', '快飛走啦，臭小鳥…', '', 28153),
(152788, 'zhTW', '我們空中再見啦。', '', 28153),
(152787, 'zhTW', '', '北方是斯陀頌恩谷地，這個家族的浪潮賢者負責打造我們的艦隊，並且負責對船施予祝福。', 28153),
(152786, 'zhTW', '先這樣吧。再見。', '', 28153),
(152785, 'zhTW', '回去工作吧！', '', 28153),
(152784, 'zhTW', '有事快說！', '', 28153),
(152783, 'zhTW', '你需要什麼？', '', 28153),
(152782, 'zhTW', '嗯？我很忙欸！', '', 28153),
(152781, 'zhTW', '在沃魯敦，這些禿鷹讓許多車隊十分頭痛。你做得很好。', '', 28153),
(152780, 'zhTW', '沒人馴服得了骨喙禿鷹，牠們逐漸變成一種麻煩。請你去撲殺牠們，順便處理一下鷹巢。', '', 28153),
(152779, 'zhTW', '你可以隨意看看，不過請別碰任何東西。$b$b這些植物非常驕弱。', '', 28153),
(152778, 'zhTW', '', '西邊的佐司瓦地區山勢連綿，礦產富饒。國家的礦產資源…還有許多精悍的戰士都來自那裡。', 28153),
(152777, 'zhTW', '', '過了提拉加德海灣，就是威奎斯特和斯陀頌恩家族的領地。', 28153),
(152776, 'zhTW', '你只有受苦的份！', '你只有受苦的份！', 28153),
(152775, 'zhTW', '我有很多讓你開口的方法！', '我有很多讓你開口的方法！', 28153),
(152774, 'zhTW', '我會碾碎你的靈魂。', '我會碾碎你的靈魂。', 28153),
(152773, 'zhTW', '生命燃燒成灰燼…', '', 28153),
(152772, 'zhTW', '那時候要救他，為時已晚。', '', 28153),
(152771, 'zhTW', '我深愛的這片土地正在分崩離析…所以我才會尋求你們的協助。正如聯盟需要庫爾提拉斯一樣，我們也非常需要你們。', '', 28153),
(152770, 'zhTW', '但是她的方向錯了，她的顧問蒙蔽了她，讓她看不出來，弊病已經遍及全國各地。', '', 28153),
(152769, 'zhTW', '第三次獸人戰爭為庫爾提拉斯帶來的創傷還在。這點凱瑟琳‧普勞德摩爾的感受最深。', '', 28153),
(152768, 'zhTW', '', '別讓我丟臉，好嗎？', 28153),
(152767, 'zhTW', '幾天後，他在半夜尖叫著醒來，渾身都被汗水浸溼。嚴重的感染深入他的五臟六腑，他最後沒能看見隔日的太陽。', '', 28153),
(152766, 'zhTW', '', '如果這裡沒有錢幣了，就去其他地方找找。', 28153),
(152765, 'zhTW', '以他的傷勢應該要退伍歸鄉的，但是他很頑固，堅持打勝仗之前絕不回去。他自己包紮了一下，跟治療人員說他沒事。', '', 28153),
(152763, 'zhTW', '有艘巨魔的重型船艦攻擊我們的運輸船。砲彈破片劃破甲板，刺進我一個朋友的體內。', '', 28153),
(152762, 'zhTW', '許多年前，我參加過某場戰爭。是…第二次獸人戰爭吧？我老是分不清楚。', '', 28153),
(152761, 'zhTW', '嗯…你們願意聽我這名老騎士說個故事嗎？', '', 28153),
(152760, 'zhTW', '你為什麼願意幫助我們？', '', 28153),
(152759, 'zhTW', '凱瑟琳‧普勞德摩爾拒絕了我們，甚至把自己的女兒當成叛徒。', '', 28153),
(152758, 'zhTW', '有個四處流浪的贊達拉人賣給我這瓶藥水，據說能在瞬間烹調任何食物，我當然不會拒絕這種好東西。幫我個忙，對這個地區的生物用用看吧。', '', 28153),
(152757, 'zhTW', '泰莉亞，為他們說明一下詳細情況吧。', '', 28153),
(152756, 'zhTW', '這全都會融化。', '', 28153),
(152755, 'zhTW', '葛雷邁恩國王，很榮幸見到你。我已經下令，你們可以任意在港口停留。', '', 28153),
(152754, 'zhTW', '效果真驚人！為了安全起見，我讓獠牙朋友先試吃看看…', '', 28153),
(152753, 'zhTW', '', '對力量的欲望、對最高真理的渴求，還有鮮血的意志。', 28153),
(152752, 'zhTW', '', '一開始的時候，納茲曼人的手段…很令人不快。不過現在我了解他們的想法了，他們很單純，心中懷抱單純的慾望。', 28153),
(152751, 'zhTW', '', '來，讓我帶你看看我學到了什麼。', 28153),
(152750, 'zhTW', '', '關於他們的事，還有很多要去了解。這種鮮血魔法…比你能想像的還要強大。', 28153),
(152749, 'zhTW', '', '這些可以做為強大的工具，用來對抗贊達拉食人妖和他們的部落盟友。', 28153),
(152748, 'zhTW', '', '我和鮮血食人妖、這些納茲曼人，建立的信賴關係比我想像中的強。', 28153),
(152747, 'zhTW', '啊，閉上你的嘴！', '', 28153),
(152746, 'zhTW', '', '嗚呃呃！　', 28153),
(152745, 'zhTW', '', '這是對事不對人，你了解的。但我決不能讓你打斷我至今所有的進展。…我所學到的事情…我還未發現的秘密。', 28153),
(152744, 'zhTW', '', '我們會犧牲這個贊達拉來強化我們的力量。', 28153),
(152743, 'zhTW', '因為你我們才能走這麼遠，我們會追隨你。', '因為你我們才能走這麼遠，我們會追隨你。', 28153),
(152742, 'zhTW', '$p知道附近哪裡有狐狸人船隊。我們可以暫時加入他們，直到暴風過去為止。', '', 28153),
(152741, 'zhTW', '贊姆蘭的爪牙一定會出海追殺我們。', '', 28153),
(152740, 'zhTW', '沒錯，但是我們必須先避避風頭。', '', 28153),
(152739, 'zhTW', '自由持有我們的財寶。', '自由持有我們的財寶。', 28153),
(152738, 'zhTW', '自由在任何地方掠奪。', '自由在任何地方掠奪。', 28153),
(152737, 'zhTW', '自由航行開放海域。', '自由航行開放海域。', 28153),
(152736, 'zhTW', '我們成功了，夥伴們。我們終於幹掉贊姆蘭了！', '', 28153),
(152735, 'zhTW', '用力划！加速往海岸前進！', '用力划！加速往海岸前進！', 28153),
(152734, 'zhTW', '你一定就是聯盟的使者。我很高興弗林和泰莉亞把你從那座糟糕的監獄裡面弄出來。\n\n我是塞勒斯‧克瑞斯福爵士，謹代表普勞德摩爾海軍府，歡迎你來到庫爾提拉斯。\n\n<塞勒斯伸出手來釋出善意。>', '', 28153),
(152733, 'zhTW', '<握他的手。>', '<握他的手。>', 28153),
(152732, 'zhTW', '我剩下的日子已經不多了。\n\n我才不願意在餘生看到庫爾提拉斯瓦解。', '', 28153),
(152731, 'zhTW', '好了，船員們，開始把寶藏搬到船上去！', '', 28153),
(152730, 'zhTW', '溫斯頓飛得太遠了，趕快回到寇連恩！', '', 28153),
(152729, 'zhTW', '各位，根據斥候回報，泰坦守衛者赫茲羅就在這棟建築的底部。', '', 28153),
(152728, 'zhTW', '哈卡在古拉巴什的心智留下了弱點，在那之後他們就很容易被影響，所以必須消滅他們。', '', 28153),
(152727, 'zhTW', '', '你別想…得逞…', 28153),
(152726, 'zhTW', '遵命，船長。', '', 28153),
(152725, 'zhTW', '', '寇連恩是我們的！', 28153),
(152724, 'zhTW', '今晚就在營地好好休息，明天我們要計畫一下如何取得剩下的寶藏。', '今晚就在營地好好休息，明天我們要計畫一下如何取得剩下的寶藏。', 28153),
(152723, 'zhTW', '歡迎來到商隊！', '歡迎來到商隊！', 28153),
(152722, 'zhTW', '好喔…', '好喔…', 28153),
(152721, 'zhTW', '沒錯，離海岸不遠處有座島嶼，上面有無數的寶藏。', '', 28153),
(152720, 'zhTW', '小小的詛咒絕對無法阻止狐狸人取得珍貴的寶藏。你有在哪邊弄到更多嗎？', '小小的詛咒絕對無法阻止狐狸人取得珍貴的寶藏。你有在哪邊弄到更多嗎？', 28153),
(152719, 'zhTW', '唯一的問題是。這些寶藏被詛咒了。', '唯一的問題是。這些寶藏被詛咒了。', 28153),
(152718, 'zhTW', '我們一直想找個新船隊加入。要是你願意接納我們，我們會跟你分享寶藏。', '', 28153),
(152717, 'zhTW', '海盜之王贊姆蘭殺了你的朋友。我們背叛了贊姆蘭並偷走他的寶藏。', '', 28153),
(152716, 'zhTW', '我在聽…', '我在聽…', 28153),
(152715, 'zhTW', '先等等！我們想跟你坐下來談談。', '', 28153),
(152714, 'zhTW', '骷…骷…骷髏！諾…諾…諾拉，殺了他們！', '骷…骷…骷髏！諾…諾…諾拉，殺了他們！', 28153),
(152713, 'zhTW', '做得漂亮，我們用無信者自己的大砲來反擊，應該能減緩他們的攻勢。', '', 28153),
(152712, 'zhTW', '我渴望勢均力敵的戰鬥！', '我渴望勢均力敵的戰鬥！', 28153),
(152711, 'zhTW', '無信者在發動攻擊！快用我們搶來的大砲反擊，幫忙保護神廟！', '', 28153),
(152710, 'zhTW', '', '派奇，就是現在！', 28153),
(152709, 'zhTW', '我準備好了。', '我準備好了。', 28153),
(152708, 'zhTW', '你想動起來嗎？我們可不是來渡假的。', '', 28153),
(152707, 'zhTW', '大夥，朝他們發射！', '', 28153),
(152706, 'zhTW', '發射攻擊！', '', 28153),
(152705, 'zhTW', '大夥，朝敵人發射！', '', 28153),
(152704, 'zhTW', '瞄準目標了！發射！', '', 28153),
(152703, 'zhTW', '火力全開！', '', 28153),
(152702, 'zhTW', '目標在那！射擊！', '', 28153),
(152701, 'zhTW', '哈哈哈…', '', 28153),
(152700, 'zhTW', '…沒錯。對我們的潛在客戶來說有點太恐怖了。', '', 28153),
(152699, 'zhTW', '太可怕了嗎？', '', 28153),
(152698, 'zhTW', '我很快地計算了一下損益，我不認為我們值得在這裡花時間。', '', 28153),
(152697, 'zhTW', '那…你的艾澤萊晶岩呢？', '', 28153),
(152696, 'zhTW', '很好。跳上摩托車，我們走吧。', '', 28153),
(152695, 'zhTW', '太好了。', '', 28153),
(152694, 'zhTW', '所以…呃…你要不要離開這裡？', '', 28153),
(152693, 'zhTW', '不不不不…', '', 28153),
(152692, 'zhTW', '伊崔格，你最好克服自己對女巫的恐懼。這個區域到處都是艾澤萊晶岩，還有…呃啊！', '', 28153),
(152691, 'zhTW', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t%s獲得|cFFFF0000|Hspell:263246|h[閃電之盾]|h|r！', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t%s獲得|cFFFF0000|Hspell:263246|h[閃電之盾]|h|r！', 28153),
(152690, 'zhTW', '別又來了！', '', 28153),
(152689, 'zhTW', '', '你的鮮血屬於我！', 28153),
(152688, 'zhTW', '誰在乎！你找到艾澤萊晶岩礦層了嗎？', '', 28153),
(152687, 'zhTW', '是什麼？那是什麼？', '', 28153),
(152686, 'zhTW', '閉…閉嘴。', '', 28153),
(152685, 'zhTW', '啊哈哈哈！這麼壯的老獸人，竟然怕女巫。', '', 28153),
(152684, 'zhTW', '才沒有！呃，我才不怕，我只是…不喜歡她們罷了。', '', 28153),
(152683, 'zhTW', '你說什麼？', '', 28153),
(152682, 'zhTW', '小心…女…女巫…', '', 28153),
(152681, 'zhTW', '伊崔格…你害怕女巫？', '', 28153),
(152680, 'zhTW', '他剛剛是說…女巫？', '', 28153),
(152679, 'zhTW', '城鎮不安全！那些鳥就在我們頭上！', '城鎮不安全！那些鳥就在我們頭上！', 28153),
(152678, 'zhTW', '嗯，做好你的工作，保護我！', '', 28153),
(152677, 'zhTW', '我沒有…但我的確有看到異狀。有人來了。', '', 28153),
(152676, 'zhTW', '得了… 沒什麼稀奇的。你有看到任何艾澤萊晶岩嗎？', '', 28153),
(152675, 'zhTW', '它們到處都是！', '它們到處都是！', 28153),
(152674, 'zhTW', '加里維克斯…你看到這具殘破的屍體了嗎？你的斥候死掉了。', '', 28153),
(152673, 'zhTW', '嗯，隨便啦。', '', 28153),
(152672, 'zhTW', '好吧，我們會調查艾澤萊晶岩。但是之後我們得專心對付聯盟！', '', 28153),
(152671, 'zhTW', '太…多…鳥了！', '太…多…鳥了！', 28153),
(152670, 'zhTW', '我永遠不會再相信海鷗了！', '我永遠不會再相信海鷗了！', 28153),
(152669, 'zhTW', '麥克米倫女士說的沒錯。這些鳥太邪惡了！', '麥克米倫女士說的沒錯。這些鳥太邪惡了！', 28153),
(152668, 'zhTW', '呿。做苦工。', '', 28153),
(152667, 'zhTW', '我們要先去查明這件事。', '', 28153),
(152666, 'zhTW', '重要事項優先！我的斥候告訴過我，在佐司瓦有著巨大的艾澤萊晶岩脈流。', '', 28153),
(152665, 'zhTW', '那就快滾開我的視線，不然我會讓你真的害怕！', '', 28153),
(152664, 'zhTW', '我們應該要小心。他說的話…讓我擔心。', '', 28153),
(152663, 'zhTW', '對，可是…', '', 28153),
(152662, 'zhTW', '…可怕的詛咒…其他人全都…', '', 28153),
(152661, 'zhTW', '你必須回頭！那是…', '', 28153),
(152660, 'zhTW', '', '吭。我以為它會更大。', 28153),
(152659, 'zhTW', '', '電流衝擊不夠。我猜它需要更多燃料。', 28153),
(152658, 'zhTW', '比起城市裡冰冷的石頭，我們更喜歡自然的林地。許多贊達拉人認為我們是異端，宣稱我們的主母不是羅亞。\n\n他們要怎麼想是他們的自由。我們露娜萊自古以來就擁有自然的天賦，掌握野地的形體。我們遵守的是平衡之道，而不是討價還價。', '', 28153),
(152655, 'zhTW', '真棒！太好了！啊，這個上面沾了沙子。不過沒差，你做得太棒了！', '', 28153),
(152654, 'zhTW', '有好多好多閃閃發亮的海玻璃被沖進沼澤裡面，可是全都被魚人拿走了！如果你有看到漂亮的，就幫忙撿一點回來。', '', 28153),
(152653, 'zhTW', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t 亞茲瑪開始施放|cFFFF0404|Hspell:249924|h[靈魂撕裂]|h|r！', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t 亞茲瑪開始施放|cFFFF0404|Hspell:249924|h[靈魂撕裂]|h|r！', 28153),
(152652, 'zhTW', '你來得太晚了。這裡已經遭到入侵了！', '你來得太晚了。這裡已經遭到入侵了！', 28153),
(152651, 'zhTW', '你以為只有我一個嗎？見見我的夥伴吧！', '你以為只有我一個嗎？見見我的夥伴吧！', 28153),
(152650, 'zhTW', '', '這些女巫本來就已經夠邪惡了，這下子更是喪盡天良！我真不知道該怎麼感謝你阻止這場…屠殺。', 28153),
(152649, 'zhTW', '女巫會的所作所為是在褻瀆這個世界，所以我們要為這些骯髒的大膽行徑畫下句點。', '', 28153),
(152648, 'zhTW', '總算機靈一點了！船上見，我會確保船員裝滿整船的寶藏。', '', 28153),
(152647, 'zhTW', '', '我們從這裡救回的每條人命，都象徵我們的勝利。做得好。', 28153),
(152646, 'zhTW', '死亡與重生是我們的專利，別人不要隨便染指比較好。謝謝你幫忙糾正這群人。', '', 28153),
(152645, 'zhTW', '', '你從漫天恐懼之中，拯救了佐司瓦的人民。請容我向你致上謝意。', 28153),
(152644, 'zhTW', '別惹出麻煩。', '別惹出麻煩。', 28153),
(152643, 'zhTW', '這些羽毛夠我們的遊俠用上一段時間了。', '', 28153),
(152642, 'zhTW', '永無止盡的燒殺擄掠很好…沒有你更好！', '', 28153),
(152641, 'zhTW', '有什麼比永無止盡的燒殺擄掠還好？', '', 28153),
(152640, 'zhTW', '你是個殘忍的船長，贊姆蘭。船員值得跟隨更好的人！', '', 28153),
(152639, 'zhTW', '', '你不走的話，我們會全軍覆沒。快走！', 28153),
(152638, 'zhTW', '', '我們不會讓你死在這裡！', 28153),
(152637, 'zhTW', '', '剛剛真驚險，大海就跟沃魯敦的沙漠一樣危險，一刻都不能大意。', 28153),
(152636, 'zhTW', '', '就差一點點，看來我們不只需要關注大海，也要關注沙漠。', 28153),
(152635, 'zhTW', '', '海岸那邊有隻巨大的海獸在肆虐，我們一定要阻止牠，不能讓它往島內前進。', 28153),
(152634, 'zhTW', '', '巨大的海怪一直在海岸作亂，我們必須在它進犯營地之前，阻止那隻海怪！', 28153),
(152633, 'zhTW', '', '佐拉斯是塞斯拉克軍隊中相當卓越的指揮官。能解決他的話，形同一次莫大的勝利。', 28153),
(152632, 'zhTW', '', '獠牙呼喚者索瑞斯是塞斯拉克軍隊的高階指揮官，消滅他對我們來說是一大勝利。', 28153),
(152631, 'zhTW', '', '狐狸人斥候回報，在附近發現塞斯拉克指揮官，我們必須把握這個機會剷除他。', 28153),
(152630, 'zhTW', '', '我們的斥候傳來消息，表示塞斯拉克的高階指揮官出現在附近。我們必須把握殺死他的機會，不要錯失良機。', 28153),
(152629, 'zhTW', '', '幹得好！失去了酋長，那個部族很快就會分崩離析。', 28153),
(152628, 'zhTW', '', '幹得好！少了酋長的領導，那個部族很快就會分崩離析。', 28153),
(152627, 'zhTW', '', '這附近有個魚人的部族,他們一直在製造麻煩。搞定他們的領導者,他們就會瓦解。', 28153),
(152626, 'zhTW', '', '這附近有個魚人部族一直在搗亂。搞定他們的領袖，這個部族就會瓦解。', 28153),
(152625, 'zhTW', '', '做得很好，我們的斥候一定很高興知道你消滅了莫法尼。', 28153),
(152624, 'zhTW', '', '做得好，要是狐狸人知道你解決掉莫法尼，一定會很開心。', 28153),
(152623, 'zhTW', '女巫會控制了一隻巨大烏鴉，用來對付這裡的居民。雖然佐司瓦人的死活都不關我的事，這隻烏鴉的羽毛對我們的黑暗遊俠來說倒是造箭的好材料。', '', 28153),
(152622, 'zhTW', '女巫會裡有個高階女巫為了增強力量，用手下的侍徒獻祭。殺了她，讓這些不知好歹的傢伙知道，只有黑暗女王才能掌控死亡。', '', 28153),
(152621, 'zhTW', '看來那些女巫「雇用」了莊園裡的廚師，做出這些可怕的菜餚。一定要想辦法消滅他們，越快越好。', '', 28153),
(152620, 'zhTW', '', '禍心女巫會控制了一隻佐司瓦當地的巨大烏鴉。殺掉牠，別讓牠獵殺這裡的居民！', 28153),
(152619, 'zhTW', '', '威奎斯特夫人手下有個女巫在用自己的侍徒獻祭。去阻止這場儀式，不要再有人犧牲了！', 28153),
(152618, 'zhTW', '', '有個贊達拉流放者一直在濫殺我們的斥候，在他奪走更多條人命之前，找到他，消滅他。', 28153),
(152617, 'zhTW', '', '最近有位流放者對狐狸人造成威脅。把他找出來，在他殘害更多生命之前解決掉他。', 28153),
(152616, 'zhTW', '', '這裡的廚師用大有問題的食材，做餐點給不知情的賓客吃。阻止他們繼續用恐怖的食物毒害別人！', 28153),
(152615, 'zhTW', '是的，長官！', '', 28153),
(152614, 'zhTW', '不是，長官。', '', 28153),
(152613, 'zhTW', '現在給我退下，讓他們通過。我會在辦公室跟他們會談。', '', 28153),
(152612, 'zhTW', '對！你們聽令於庫爾提拉斯！盾牌上是普勞德摩爾的徽章！我說了算！', '', 28153),
(152611, 'zhTW', '在沃魯敦，不施肥是無法種植作物的。我們通常是從土狼收集肥料，不過最近不太夠。去餵食土狼，看能不能增加肥料產量！', '', 28153),
(152610, 'zhTW', '艾胥凡女士？你是為她做事的嗎？你們盾牌上面的徽章是她的嗎？', '', 28153),
(152609, 'zhTW', '可是…艾胥凡女士下令…', '', 28153),
(152608, 'zhTW', '還不快退下！你們不知道這位是誰嗎？', '', 28153),
(152607, 'zhTW', '這批肥料品質真好！幹得好…對了！記得去把手洗乾淨！', '', 28153),
(152606, 'zhTW', '…我想我們該打斷一下，對吧？', '', 28153),
(152605, 'zhTW', '地平線上的是船帆嗎？他們或許在和贊達拉人談條件。', '', 28153),
(152604, 'zhTW', '用力踢', '用力踢', 28153),
(152603, 'zhTW', '箱子發出模糊的聲響。', '', 28153),
(152602, 'zhTW', '箱子發出愉悅的聲響。', '', 28153),
(152601, 'zhTW', '箱子發出模糊的聲響。', '', 28153),
(152600, 'zhTW', '不知道。但今晚由我買酒，美女。', '', 28153),
(152599, 'zhTW', '', '什麼事情？', 28153),
(152598, 'zhTW', '', '我很樂意將你傳送到無盡之海的底部！為了部落！', 28153),
(152597, 'zhTW', '怎麼-', '', 28153),
(152596, 'zhTW', '', '有謠傳指出外地的侵略者和間諜已經混到我們之間，我們必須步步為營。服從他們的指示，就可以避免不必要的事件。', 28153),
(152595, 'zhTW', '', '酬勞等等在談，碼頭管理員。', 28153),
(152594, 'zhTW', '沒錯，就在那裡。我們會把這封好，然後運回暴風城。', '', 28153),
(152591, 'zhTW', '', '歐庫雷斯…我很抱歉…', 28153),
(152590, 'zhTW', '針頭指向東。我會在廢墟中與你碰面，$n。', '', 28153),
(152589, 'zhTW', '', '太慢了，矮人。', 28153),
(152588, 'zhTW', '跟緊點，部落的人就潛伏在附近。我聞得到他們的味道。', '', 28153),
(152587, 'zhTW', '花香比我想的還重，他們換新口味了嗎，老精靈？', '', 28153),
(152586, 'zhTW', '不是這裡。另外，看來在我們之後的是夜裔，真是太好玩了。', '', 28153),
(152585, 'zhTW', '我們正在靠近，讓那些害人又耗魔的東西離我遠點，$n。', '', 28153),
(152584, 'zhTW', '就在我腳下…哪裡…？', '', 28153),
(152583, 'zhTW', '噢！真是卑鄙手段！', '', 28153),
(152581, 'zhTW', '箱子微微地嗡嗡作響。', '', 28153),
(152580, 'zhTW', '箱子微微地嗡嗡作響。', '', 28153),
(152579, 'zhTW', '箱子微微地嗡嗡作響。', '', 28153),
(152578, 'zhTW', '慢著！不能塑像是無法摧毀的，不過它們會釋出一段古老的回憶…一段我試圖遺忘的回憶。', '', 28153),
(152577, 'zhTW', '你的意思是…現在有這麼大一把劍插在這個世界的心臟裡，你還有時間在這裡亂戳人開玩笑嗎？還不快去做正事！', '', 28153),
(152576, 'zhTW', '別忘了你對艾澤拉斯的責任。', '', 28153),
(152575, 'zhTW', '一定要拯救世界！', '', 28153),
(152574, 'zhTW', '艾澤拉斯正在痛苦哀號。', '', 28153),
(152573, 'zhTW', '這個世界需要我們，勇士。', '', 28153),
(152572, 'zhTW', '', '一想到食人妖腳下可能有本世紀最棒的考古發現！', 28153),
(152571, 'zhTW', '留心你的骨頭，這裡有股力量，我嚐得出來。我們要在部落的眼底下把它找出來。', '', 28153),
(152570, 'zhTW', '', '小心你的手，現在，慢慢地、小心點。', 28153),
(152569, 'zhTW', '', '不要弄傷它。哎，就像那樣…', 28153),
(152568, 'zhTW', '', '啊啊…現在，看看它啊。你會成為厲害的考古學家的！', 28153),
(152567, 'zhTW', '真的嗎？你要全部用手來？', '', 28153),
(152566, 'zhTW', '去，拍拍我的元素生物，它會為你完成這事。', '', 28153),
(152565, 'zhTW', '', '等等！', 28153),
(152564, 'zhTW', '很好，現在，來辦正事了。', '', 28153),
(152563, 'zhTW', '', '你刮傷它了！我們可不能這樣展示它！', 28153),
(152562, 'zhTW', '哎，小姐，沒那麼糟啦。', '', 28153),
(152561, 'zhTW', '我的骨頭非常疲勞，詛咒讓我不堪負荷。', '', 28153),
(152560, 'zhTW', '海盜之王贊姆蘭永遠不會忘記這一天。', '', 28153),
(152559, 'zhTW', '', '港口統領辦公室往這邊走過去就到了。', 28153),
(152558, 'zhTW', '<嗅>這件大衣也該洗了。', '', 28153),
(152557, 'zhTW', '一把堅固的鎚子是價值不斐的工具，也是十分耐用的武器。', '', 28153),
(152556, 'zhTW', '沒鎚子啥都幹不成，跟被砍了雙手沒啥兩樣。', '', 28153),
(152555, 'zhTW', '', '我擋不了多久。你們快帶著節杖離開這裡！', 28153),
(152554, 'zhTW', '檢查', '檢查', 28153),
(152553, 'zhTW', '這些洞穴中有許多狗頭人。', '', 28153),
(152552, 'zhTW', '所有人都上船！再見，$p。', '', 28153),
(152551, 'zhTW', '我們大概可以啟航了，贊姆蘭絕對料不到我們會來。', '', 28153),
(152550, 'zhTW', '同意。', '同意。', 28153),
(152549, 'zhTW', '同意。', '同意。', 28153),
(152548, 'zhTW', '沒錯，贊姆蘭不是船長，而是個暴君。叛變是唯一的出路。', '沒錯，贊姆蘭不是船長，而是個暴君。叛變是唯一的出路。', 28153),
(152547, 'zhTW', '我們都是自願的，對吧？', '', 28153),
(152546, 'zhTW', '沒錯，拿走我們應得的寶藏。', '', 28153),
(152545, 'zhTW', '看看那些黃金…', '看看那些黃金…', 28153),
(152544, 'zhTW', '這是叛變，陰溝裡的老鼠！我們要用手中的劍刺穿贊姆蘭的身體。', '這是叛變，陰溝裡的老鼠！我們要用手中的劍刺穿贊姆蘭的身體。', 28153),
(152543, 'zhTW', '我們居然自尋死路。', '我們居然自尋死路。', 28153),
(152542, 'zhTW', '唯一比我們現在還糟的下場。', '', 28153),
(152541, 'zhTW', '那裡只有金奴，他們是被迫永遠看守贊姆蘭寶藏的前船員。', '', 28153),
(152540, 'zhTW', '我們正前往黃金島，贊姆蘭把我們無數年來掠奪到的寶藏都藏在那裡。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152539, 'zhTW', '用力划！', '用力划！', 28153),
(152538, 'zhTW', '*這裡有一些有趣的礦坑推車傳統動作。*', '', 28153),
(152537, 'zhTW', '外面好亮…把我這身骨頭放回洞裡。', '外面好亮…把我這身骨頭放回洞裡。', 28153),
(152536, 'zhTW', '', '庫爾提拉斯有幾個大家族，原本都對戴林‧普勞德摩爾效忠，但自從戴林在塞拉摩失利之後，情況就變了。', 28153),
(152535, 'zhTW', '', '之後海軍總帥凱瑟琳‧普勞德摩爾接下戴林的位子，負責指揮海軍和衛隊。', 28153),
(152534, 'zhTW', '', '雖然我們盡力維持秩序，庫爾提拉斯的犯罪率還是不斷提高、行政機關腐敗，還有海盜作亂。人民開始對普勞德摩爾海軍府失去信心。', 28153),
(152533, 'zhTW', '', '.', 28153),
(152532, 'zhTW', '', '.', 28153),
(152531, 'zhTW', '你好。你想休息一下嗎？吃個點心？', '', 28153),
(152530, 'zhTW', '以一個管家的身分服侍諾爾威頓大人和諾爾威頓女士是我的榮幸。如果你想要一個房間休息，直接說不用客氣。', '', 28153),
(152529, 'zhTW', '如此規模的莊園需要大量維護。打造馬蹄、修理耙子、各處偶爾需要進行的零工，鐵匠的工作永遠沒有完成的一天！', '', 28153),
(152528, 'zhTW', '需要修復什麼嗎？修復馬蹄鐵是我的專長，不過我也可以幫你看看你的護甲。', '', 28153),
(152527, 'zhTW', '', '快跑，快跑！', 28153),
(152526, 'zhTW', '', '道理非常簡單，不要受傷，我就不用治療你。', 28153),
(152525, 'zhTW', '', '讓我留下來擋住追兵吧。', 28153),
(152524, 'zhTW', '你是個天生的釣手，我就知道你很厲害！而且你的四肢都還健在…太厲害了！', '', 28153),
(152523, 'zhTW', '沙蟲十分兇殘，會躲在沙子底下狩獵。雖然牠們很危險，但牙齒很值錢！帶著我的釣竿，試試你的手氣！', '', 28153),
(152522, 'zhTW', '事情永遠可以更糟，我們只能用手邊的資源盡力而為。', '', 28153),
(152521, 'zhTW', '庫爾提拉斯艦隊臣服在我的意志之下，現在，輪到你了。', '', 28153),
(152520, 'zhTW', '', '我…真的走不動了。', 28153),
(152519, 'zhTW', '', '再走幾步就到了，我們不會丟下你的！', 28153),
(152518, 'zhTW', '讓他們嚐嚐新盟友的威力。', '', 28153),
(152517, 'zhTW', '我什麼都沒有了，贊姆蘭…一切都給你了。', '我什麼都沒有了，贊姆蘭…一切都給你了。', 28153),
(152516, 'zhTW', '另一個欠征服的生靈！一定會很有趣。', '另一個欠征服的生靈！一定會很有趣。', 28153),
(152514, 'zhTW', '', '加油，我們快到了！', 28153),
(152513, 'zhTW', '', '快到了，祭壇就在前面。', 28153),
(152512, 'zhTW', '你以為阻止得了我，但是庫爾提拉斯的命運早就決定了。', '', 28153),
(152507, 'zhTW', '好消息就由你來通知。我要確保這些大砲受到妥善處理。', '', 28153),
(152506, 'zhTW', '敵人全軍覆沒了！', '', 28153),
(152505, 'zhTW', '哈，又倒了一個。只剩下那一個…', '', 28153),
(152504, 'zhTW', '開火！', '', 28153),
(152503, 'zhTW', '那確實引起了他們的注意力。當我在重填彈的時候注意部落來襲！', '', 28153),
(152502, 'zhTW', '好，開始了。摀住你的耳朵！', '', 28153),
(152501, 'zhTW', '他們應該把力量用來治療艾澤拉斯，而不是傷害她。勇士，做得好。', '', 28153),
(152500, 'zhTW', '有人在附近吸取艾澤萊晶岩的力量，你一定要阻止他們！', '', 28153),
(152499, 'zhTW', '而現在，是我要帶領大家迎向浪潮之下的光榮未來。', '', 28153),
(152498, 'zhTW', '', '這股力量…會是…我們的！', 28153),
(152497, 'zhTW', '', '沒有人可以抵擋擁有這股力量的塞斯拉克！', 28153),
(152496, 'zhTW', '拿回那些寶石，放回原本的位置，我們才能通過！', '', 28153),
(152495, 'zhTW', '瑟沙利斯之眼竟然不見了！', '', 28153),
(152494, 'zhTW', '所需的東西我都有了。當你準備好開始就跟我說。', '', 28153),
(152493, 'zhTW', '看到他大搖大擺地朝城市走去。希望他不要讓自己出糗，不然人們可能會親自對付他。', '', 28153),
(152492, 'zhTW', '我觀察你的去向好一段時間了，看到你和那小傢伙一起奮鬥和獲勝。你應該以他為傲；而你沒放棄他，你也該以你自己為傲。這種事這裡沒有多少人能辦到。\n\n好好照顧夸風，他是個忠誠的夥伴，或許還是最好的飛行家。', '', 28153),
(152491, 'zhTW', '', '古翰…想要…這股力量…', 28153),
(152490, 'zhTW', '', '這股能量會帶給我們力量！你休想插手！', 28153),
(152489, 'zhTW', '幫忙', '幫忙', 28153),
(152488, 'zhTW', '剔骨中', '剔骨中', 28153),
(152487, 'zhTW', '有時候，總覺得這整個沼澤都在找我們麻煩。幸好有你勇於面對挑戰！', '', 28153),
(152486, 'zhTW', '我有不祥的預感…去巡邏的斥候早就該回來了。快去調查一下延誤的原因。', '', 28153),
(152484, 'zhTW', '', '我們繼續前進吧。', 28153),
(152483, 'zhTW', '', '在許多年前，是他的父親帶領我們來到這個谷地的。', 28153),
(152482, 'zhTW', '', '不是。在低語改變他之前，領主非常和善。', 28153),
(152481, 'zhTW', '', '斯陀頌恩領主一直都這麼殘忍嗎？', 28153),
(152480, 'zhTW', '', '實在不太可能不被發現。', 28153),
(152479, 'zhTW', '', '你要拋下我一個人等死嗎？', 28153),
(152478, 'zhTW', '這個石頭散發著艾薩拉本人的力量！把它帶去交給主堡的部隊，他們會知道該怎麼做的。', '', 28153),
(152477, 'zhTW', '謝謝，但你和我應該離開這裡！', '謝謝，但你和我應該離開這裡！', 28153),
(152476, 'zhTW', '我才不要當翼手龍寶寶的飼料！', '我才不要當翼手龍寶寶的飼料！', 28153),
(152475, 'zhTW', '指揮官會因為我被野生動物抓住而揍我的。', '指揮官會因為我被野生動物抓住而揍我的。', 28153),
(152474, 'zhTW', '謝謝你！我以為我很小心了，但另一隻野獸從側面把我撲倒，牠真是聰明。', '謝謝你！我以為我很小心了，但另一隻野獸從側面把我撲倒，牠真是聰明。', 28153),
(152473, 'zhTW', '呼，他們那些猛爪可真痛！', '呼，他們那些猛爪可真痛！', 28153),
(152472, 'zhTW', '這些該死的翼手龍可真煩。我可不希望我的士兵變成食物！', '這些該死的翼手龍可真煩。我可不希望我的士兵變成食物！', 28153),
(152471, 'zhTW', '這些該死的翼手龍…我可不希望士兵變成食物！', '這些該死的翼手龍…我可不希望士兵變成食物！', 28153),
(152470, 'zhTW', '我本來打算清除翼手龍，好拿下山丘上的制高點，但我們卻一個個被抓走！', '我本來打算清除翼手龍，好拿下山丘上的制高點，但我們卻一個個被抓走！', 28153),
(152469, 'zhTW', '魔古…會找到…更多…石頭…', '', 28153),
(152468, 'zhTW', '這個石頭的力量將會讓魔古帝國復甦！', '', 28153),
(152467, 'zhTW', '做得好！數量比我預計的還要多。', '', 28153),
(152466, 'zhTW', '古拉巴什陷入嗜殺的狂熱狀態！我們就幫他們…送入地府吧！敲響銅鑼，他們就會自投羅網！', '', 28153),
(152465, 'zhTW', '我們收到的報告說這個區域有食人妖在作亂，看來是該想辦法消滅他們了。敲響階梯頂端的鑼，讓他們知道我們要出手了！', '', 28153),
(152464, 'zhTW', '無論你能做什麼，只要能幫我們，我們會很感激的。', '無論你能做什麼，只要能幫我們，我們會很感激的。', 28153),
(152463, 'zhTW', '給我把斧頭，我就劈下去！', '', 28153),
(152462, 'zhTW', '不管是巫木邪獸還是什麼野獸都給我滾出來，我要打十個！', '', 28153),
(152461, 'zhTW', '庫爾提拉斯沒有不下場打架的！', '', 28153),
(152460, 'zhTW', '謝謝你的幫助，朋友。', '', 28153),
(152459, 'zhTW', '', '有人埋伏！', 28153),
(152458, 'zhTW', '快！快！快！', '快！快！快！', 28153),
(152457, 'zhTW', '好了，阿兵哥，聽仔細了！當我們抵達海灘，我要$n打先鋒。用那把信號槍點燃任何會動的東西。', '好了，阿兵哥，聽仔細了！當我們抵達海灘，我要$n打先鋒。用那把信號槍點燃任何會動的東西。', 28153),
(152456, 'zhTW', '為了聯盟！', '為了聯盟！', 28153),
(152455, 'zhTW', '沒用的傢伙，碾碎這些入侵者，不然你們的危險加給就是我的了！', '', 28153),
(152454, 'zhTW', '緊急修復協定進行中…', '', 28153),
(152453, 'zhTW', '甜美的艾澤萊晶岩！', '', 28153),
(152452, 'zhTW', '鑽啊，寶貝！', '', 28153),
(152451, 'zhTW', '', '只要斯陀頌恩沒發現我們走這裡，就很好。', 28153),
(152450, 'zhTW', '', '這樣最直接。', 28153),
(152449, 'zhTW', '', '這樣…好嗎？', 28153),
(152448, 'zhTW', '', '浪潮賢者會走這條儀祭之路前往聖壇接受祝福。', 28153),
(152447, 'zhTW', '', '只要詛咒還在，你們的傷口就無法癒合！', 28153),
(152446, 'zhTW', '', '結局不該是這樣的。', 28153),
(152445, 'zhTW', '', '你們要是失敗，我就完了！', 28153),
(152444, 'zhTW', '', '你們絕對不能失敗！', 28153),
(152443, 'zhTW', '警告！燃料嚴重不足！', '', 28153),
(152442, 'zhTW', '警告！偵測到未經授權的使用者。', '', 28153),
(152441, 'zhTW', '警告！你的許可證上已經沒有點數。', '', 28153),
(152440, 'zhTW', '又來一個了，做好準備！', '又來一個，做好吐口水的準備。', 28153),
(152439, 'zhTW', '吐高一點，這樣可以吐得更遠，而且一定會命中。', '吐高一點，這樣可以吐得更遠，而且一定會命中。', 28153),
(152438, 'zhTW', '準備迎戰！', '準備迎戰！', 28153),
(152437, 'zhTW', '在他們離開時吐口水，一定會命中！', '在他們離開時吐口水，一定會命中！', 28153),
(152436, 'zhTW', '矮矮矮人來來來襲！', '', 28153),
(152435, 'zhTW', '艾澤萊晶岩的力量快讓這些元素生物失去控制了。我們一定要想辦法阻止。', '', 28153),
(152434, 'zhTW', '有些和艾澤萊晶岩融合的土元素發狂了！去解決它們，然後吸收它們體內的晶岩！', '', 28153),
(152433, 'zhTW', '他們來了！點燃火藥！', '', 28153),
(152432, 'zhTW', '', '石頭騷動不安…我們應該全部拿下！', 28153),
(152431, 'zhTW', '', '這顆石頭蘊藏的力量會讓我們的帝國越來越強大！', 28153),
(152430, 'zhTW', '<格里布好奇地看著你。布萊恩沒那個心情告訴他，他不是一隻猴子。>', '<格里布好奇地看著你。布萊恩沒那個心情告訴他，他不是一隻猴子。>', 28153),
(152429, 'zhTW', '歡迎來到飛鷹棲息地。真是多虧了你，我們擊退了怪物，奪回了自己的城鎮。你想要待多久都沒問題。', '歡迎來到飛鷹棲息地。真是多虧了你，我們擊退了怪物，奪回了自己的城鎮。你想要待多久都沒問題。', 28153),
(152428, 'zhTW', '這些武器，很可能是哥布林科技產物。管他的，用來對付塞斯拉克的效果應該很棒。', '', 28153),
(152427, 'zhTW', '妮莎帶了一些…很有意思的武器回來。可能可以用來對付塞斯拉克，但我們不知道該怎麼使用。', '', 28153),
(152426, 'zhTW', '我從來沒看過像這樣的怪物！', '我從來沒看過像這樣的怪物！', 28153),
(152425, 'zhTW', '我可以飛離這裡嗎？', '我可以飛離這裡嗎？', 28153),
(152424, 'zhTW', '現在恐怕不行。\n\n當這團混亂開始時，我試著飛離，但他們從地面用魔法攻擊我們。里尼歐側背吃了一記，我們差一點就不能活著回到獵鷹林。\n\n羅斯頓市長告訴我們別輕舉妄動，直到我們奪回城鎮，或是情況有改善。\n\n我很抱歉，但我們哪裡也去不了。', '現在恐怕不行。\n\n當這團混亂開始時，我試著飛離，但他們從地面用魔法攻擊我們。里尼歐側背吃了一記，我們差一點就不能活著回到獵鷹林。\n\n羅斯頓市長告訴我們別輕舉妄動，直到我們奪回城鎮，或是情況有改善。\n\n我很抱歉，但我們哪裡也去不了。', 28153),
(152423, 'zhTW', '哇，這還真是出乎我意料！我敢說法師們一定很想看看這個東西。做得很好，英雄。', '', 28153),
(152422, 'zhTW', '根據情報顯示，部落想從塞斯拉克人手中奪走某種神器。這樣好了，就讓我們先下手為強，如何？', '', 28153),
(152421, 'zhTW', '開始吧，$n。', '', 28153),
(152420, 'zhTW', '哇啊！', '', 28153),
(152417, 'zhTW', '', '勇士，做得好！這些鬼東西就應該乖乖待在地底下才對。', 28153),
(152416, 'zhTW', '', '可惡，他們居然犧牲自己人來製造怪物。再不阻止他們的話，我們會被那些食肉植物啃個精光！', 28153),
(152415, 'zhTW', '<將我的隊伍加入普通難度的海嶼遠征佇列。>', '<將我的隊伍加入普通難度的海嶼遠征佇列。>', 28153),
(152414, 'zhTW', '', '掌控…艾澤萊晶岩的…是我們！', 28153),
(152413, 'zhTW', '', '鮮血魔法會與我的艾澤萊晶岩融合！', 28153),
(152412, 'zhTW', '破壞我的骸骨！ 我當然隨時都能參與叛變，我已經被吊在這裡好幾週了！', '破壞我的骸骨！ 我當然隨時都能參與叛變，我已經被吊在這裡好幾週了！', 28153),
(152411, 'zhTW', '', '很好，也許這些東西能讓我們了解在納茲米爾發生的古怪現象，以及那群兇惡的鮮血食人妖到底從哪裡來的。', 28153),
(152410, 'zhTW', '', '研究人員要我們留意找到的神器，絕對不能讓神器被部落搶走。在這座廢墟搜索一下，看看有沒有東西能派上用場。', 28153),
(152409, 'zhTW', '我最喜歡叛變了，算我一份。', '我最喜歡叛變了，算我一份。', 28153),
(152407, 'zhTW', '我很高興跟你一起叛變，小滑頭。海盜之王贊姆蘭要為他對我所做的事付出代價。', '我很高興跟你一起叛變，小滑頭。海盜之王贊姆蘭要為他對我所做的事付出代價。', 28153),
(152406, 'zhTW', '要是你有金幣，我們歡迎你到這裡來花。\n\n不要干擾我們做生意，我們的人就不會去干擾你，這樣清楚了嗎？', '要是你有金幣，我們歡迎你到這裡來花。\n\n不要干擾我們做生意，我們的人就不會去干擾你，這樣清楚了嗎？', 28153),
(152405, 'zhTW', '', '去找這裡的幾個大人物談談吧：克勞斯‧晴風、肯恩‧卡萊爾、柯隆克‧油鑽和菲克希‧狡刀。\n\n代替我去問問他們需要什麼幫助，我需要他們的支持。\n\n你要是有事找我的話，我會繼續在這裡跟一些優秀傑出但心裡還有疑慮的人談事情。', 28153),
(152404, 'zhTW', '我應該找誰談？', '我應該找誰談？', 28153),
(152403, 'zhTW', '只有我們兩個人叫什麼叛變，$p。多找一點人來！', '', 28153),
(152402, 'zhTW', '你的守護者在哪裡？', '', 28153),
(152401, 'zhTW', '你是隻不怎麼有禮貌的野獸。', '', 28153),
(152400, 'zhTW', '那是我要吃的。', '', 28153),
(152399, 'zhTW', '…你應該停止。', '', 28153),
(152398, 'zhTW', '你必須付出代價！', '你必須付出代價！', 28153),
(152397, 'zhTW', '那不是你的！', '那不是你的！', 28153),
(152396, 'zhTW', '嘿！把它吐出來！', '嘿！把它吐出來！', 28153),
(152395, 'zhTW', '我一定會再次復甦。', '', 28153),
(152394, 'zhTW', '我的傀儡，起來吧！消滅眼前的入侵者！', '', 28153),
(152393, 'zhTW', '好好享用吧…禿鷹…一定等很久了…', '', 28153),
(152392, 'zhTW', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t$n|cFFFF0000|Hspell:267343|h[掉落]|h|r了球體！', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t$n|cFFFF0000|Hspell:267343|h[掉落]|h|r了球體！', 28153),
(152391, 'zhTW', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t$n手中的球體被|cFFFF0000|Hspell:267633|h[奪走]|h|r了！', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t$n手中的球體被|cFFFF0000|Hspell:267633|h[奪走]|h|r了！', 28153),
(152390, 'zhTW', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t%s|cFFFF0000|Hspell:265755|h[取回]|h|r其中一個球體！', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t%s|cFFFF0000|Hspell:265755|h[取回]|h|r其中一個球體！', 28153),
(152389, 'zhTW', '我會讓禿鷹享受你活跳跳的鮮肉！', '', 28153),
(152388, 'zhTW', '首先，我們必須把話傳出去，而且你必須清楚意識到我們對抗的人是誰。', '', 28153),
(152387, 'zhTW', '那就來大鬧一場吧！', '', 28153),
(152386, 'zhTW', '我想問點別的事情。', '我想問點別的事情。', 28153),
(152385, 'zhTW', '嘿！停手！', '嘿！停手！', 28153),
(152384, 'zhTW', '走開！', '走開！', 28153),
(152383, 'zhTW', '走開！走開！', '走開！走開', 28153),
(152382, 'zhTW', '別鬧了！', '別鬧了！', 28153),
(152381, 'zhTW', '從那裡下來！', '從那裡下來！', 28153),
(152380, 'zhTW', '是鸚鵡？沒有風箏？', '是鸚鵡？沒有風箏？', 28153),
(152379, 'zhTW', '<塔恩嘲弄地說>\n\n鸚鵡可是比風箏要聰明得多也有趣得多。\n\n<塔恩睜開一邊眼睛，看著他的鳥。>\n\n就算牠們有時候會為了好玩而尖叫也一樣。', '<塔恩嘲弄地說>\n\n鸚鵡可是比風箏要聰明得多也有趣得多。\n\n<塔恩睜開一邊眼睛，看著他的鳥。>\n\n就算牠們有時候會為了好玩而尖叫也一樣。', 28153),
(152378, 'zhTW', '自從鐵潮的人來到這裡，理查‧裂帆就掌管這裡的人員出入。\n\n這原本是為了讓這個海灣保持「隱密」和「安全」，但你要我說的話，這是他掌控一切的手段。\n\n什麼都要他同意才可以。你看，要是我不聽話，我的皮膚和鳥的翅膀就會變成那樣。\n\n<塔恩傾身向前，放低了聲音。>\n\n或許應該換個人來管事了。', '自從鐵潮的人來到這裡，理查‧裂帆就掌管這裡的人員出入。\n\n這原本是為了讓這個海灣保持「隱密」和「安全」，但你要我說的話，這是他掌控一切的手段。\n\n什麼都要他同意才可以。你看，要是我不聽話，我的皮膚和鳥的翅膀就會變成那樣。\n\n<塔恩傾身向前，放低了聲音。>\n\n或許應該換個人來管事了。', 28153),
(152377, 'zhTW', '可以順便帶我離開這裡嗎？', '可以順便帶我離開這裡嗎？', 28153),
(152376, 'zhTW', '你必須先把我弄下來，我上次逃跑被他們抓到後，就被綁在這裡。', '', 28153),
(152375, 'zhTW', '真是驚人！我要離開這裡！', '真是驚人！我要離開這裡！', 28153),
(152374, 'zhTW', '或許…要是你夠勇敢…告訴他下次我會帶頂帽子！', '', 28153),
(152373, 'zhTW', '現在沒那麼強大了吧，嗯？去吧，小傢伙。去找艾芬，就是那個叫你殺我同類的傢伙。快去咬他，我就讓你變回人形。', '', 28153),
(152372, 'zhTW', '部落在這裡？他們是從哪冒出來的！誰會保護我們？', '部落在這裡？他們是從哪冒出來的！誰會保護我們？', 28153),
(152371, 'zhTW', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t莫芮克莎在戰場各處|cFFFF0000|Hspell:264206|h[鑽地]|h|r！', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t莫芮克莎在戰場各處|cFFFF0000|Hspell:264206|h[鑽地]|h|r！', 28153),
(152370, 'zhTW', '感謝，朋友。你沒來的話我可真是完了！', '感謝，朋友。你沒來的話我可真是完了！', 28153),
(152369, 'zhTW', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t$n被|cFFFF0000|Hspell:263958|h[蛇群]|h|r吞沒，快救$g他:她;！', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t$n被|cFFFF0000|Hspell:263958|h[蛇群]|h|r吞沒，快救$g他:她;！', 28153),
(152368, 'zhTW', '贊姆蘭港被詛咒的那一天…是許久以前了啊。', '', 28153),
(152367, 'zhTW', '等你準備好了，我的勳章將揭示我的過去。', '', 28153),
(152366, 'zhTW', '謝－謝謝你，$p。米－米基是好朋友。', '謝－謝謝你，$p。米－米基是好朋友。', 28153),
(152365, 'zhTW', '科爾塞克…我失敗了…', '', 28153),
(152364, 'zhTW', '這傢伙想死！讓我來成全你！', '', 28153),
(152363, 'zhTW', '誰都不能…阻擋我們…', '', 28153),
(152362, 'zhTW', '無禮的蠢蛋！擅自入侵者死！', '', 28153),
(152361, 'zhTW', '', '你的指揮官在下面的戰場等著。', 28153),
(152360, 'zhTW', '事情還沒…結束…', '事情還沒…結束…', 28153),
(152359, 'zhTW', '我們發現一個奇怪的卷軸，據說能召喚某種不可思議的力量。海岸邊聚集了許多不死生物，我們來看看這個卷軸是不是真的那麼厲害。', '', 28153),
(152358, 'zhTW', '事情…還沒…結束…', '事情…還沒…結束…', 28153),
(152357, 'zhTW', '我為帝國…奉獻生命…', '我為帝國…奉獻生命…', 28153),
(152356, 'zhTW', '這怎麼可能…', '這怎麼可能…', 28153),
(152355, 'zhTW', '沙塵…終將擴散…', '沙塵…終將擴散…', 28153),
(152354, 'zhTW', '會有人為我報仇…', '會有人替我報仇…', 28153),
(152353, 'zhTW', '我辜負了…科爾塞克…', '我辜負了…科爾塞克…', 28153),
(152352, 'zhTW', '我們還沒…輸…', '我們還沒…輸…', 28153),
(152351, 'zhTW', '誰都別想…阻止我們…', '誰都別想…阻止我們…', 28153),
(152349, 'zhTW', '我為帝國…奉獻生命…', '我為帝國…奉獻生命…', 28153),
(152348, 'zhTW', '這怎麼可能…', '這怎麼可能…', 28153),
(152347, 'zhTW', '沙塵…終將擴散…', '沙塵…終將擴散…', 28153),
(152346, 'zhTW', '會有人…為我…報仇…', '會有人…為我…報仇…', 28153),
(152345, 'zhTW', '我辜負了…科爾塞克…', '我辜負了…科爾塞克…', 28153),
(152344, 'zhTW', '我們還沒…輸…', '我們還沒…輸…', 28153),
(152343, 'zhTW', '誰都別想…阻止我們…', '誰都別想…阻止我們…', 28153),
(152342, 'zhTW', '', '很好，正如以往，這個工作交給你果然沒錯。', 28153),
(152341, 'zhTW', '', '勇士，這些鮮血食人妖之前攻擊過勝利堡，別手下留情，讓他們知道攻擊我們會有什麼下場！', 28153),
(152340, 'zhTW', '快點，鼠輩！艾澤萊晶岩可不會自己爆炸！', '', 28153),
(152339, 'zhTW', '', '他們燒了布瑞納丹，我們再也回不了家。', 28153),
(152338, 'zhTW', '再快一點！', '', 28153),
(152337, 'zhTW', '你讓我想起一個之前遇過的年輕猴人。他說自己是猴王還是什麼鬼東西的。一天到晚在煩我。', '', 28153),
(152336, 'zhTW', '你要是覺得自己有本事惹毛我，那就大錯特錯了。', '', 28153),
(152335, 'zhTW', '我認為我們應該跟世界各地的所有種族做生意…納迦例外。牠們真是一群可怕的生物。', '', 28153),
(152334, 'zhTW', '你要是找到強大的寶物，就帶回來給我，不要自作聰明留著自己用。', '', 28153),
(152333, 'zhTW', '嗯哼。擁有強大力量的寶物最好還是交給有智慧的長者，不要隨隨便便讓毛毛躁躁的冒險者拿去。', '', 28153),
(152332, 'zhTW', '千萬不要低估有兩百年以上歷史的東西所擁有的價值和力量。', '', 28153),
(152331, 'zhTW', '就是這樣這樣這樣。快去做就對了。', '', 28153),
(152330, 'zhTW', '你的價碼是多少？幫你辦喪事大概要多少錢？', '', 28153),
(152329, 'zhTW', '太好了，有冒險者來了。我需要你來幫忙。', '', 28153),
(152328, 'zhTW', '我給你…岩鏈！', '', 28153),
(152327, 'zhTW', '未來就在眼前，孩子！', '', 28153),
(152326, 'zhTW', '恭喜你，孩子，我們發財了！', '', 28153),
(152325, 'zhTW', '', '進來呀！別當一個膽小龍！', 28153),
(152324, 'zhTW', '千萬不要接受來自黑暗帝國的禮物。', '', 28153),
(152323, 'zhTW', '我們說不定又會在戰場上相見。不管是肩並肩還是背對背，以少擊多還是以弱敵強，都有可能，嘻嘻。', '', 28153),
(152322, 'zhTW', '換我了，你來捉魚！', '', 28153),
(152321, 'zhTW', '請坐，姊妹！', '', 28153),
(152320, 'zhTW', '你真幼稚！', '', 28153),
(152319, 'zhTW', '喂！你把魚嚇跑了！', '', 28153),
(152318, 'zhTW', '', '吼！我是帕骷！嘿咻！', 28153),
(152317, 'zhTW', '', '嘿，看哪，我是格拉爾', 28153),
(152316, 'zhTW', '', 'Taz\'okun!', 28153),
(152315, 'zhTW', '', '嘻咿！', 28153),
(152314, 'zhTW', '祝你好運，想辦法活下去。', '', 28153),
(152313, 'zhTW', '隨時小心背後，不然就弄個殼吧。', '', 28153),
(152312, 'zhTW', '給我…記住…', '給我…記住…', 28153),
(152311, 'zhTW', '不…公平…', '不…公平…', 28153),
(152310, 'zhTW', '侍徒們！入侵者接近聖池！', '', 28153),
(152309, 'zhTW', '不…這是我的…', '不…這是我的…', 28153),
(152308, 'zhTW', '你…居然…', '你…居然…', 28153),
(152307, 'zhTW', '看來我要剝你的皮來抵債了！', '看來我要剝你的皮來抵債了！', 28153),
(152306, 'zhTW', '我喜歡激烈的爭執。有時候甚至會動動手，或者互毆。', '', 28153),
(152305, 'zhTW', '我會要你付雙倍！', '我會要你付雙倍！', 28153),
(152304, 'zhTW', '看來你要斷手斷腳才付得起這筆錢了！', '看來你要斷手斷腳才付得起這筆錢了！', 28153),
(152303, 'zhTW', '喂！你不會有好下場的！', '喂！你不會有好下場的！', 28153),
(152302, 'zhTW', '我被偷襲過的次數，比你走過的路還要多，所以還是少打壞主意吧。', '', 28153),
(152301, 'zhTW', '死亡是贊姆蘭僅有的憐憫，但多數人連這點憐憫都得不到。', '', 28153),
(152300, 'zhTW', '挖掘中', '挖掘中', 28153),
(152299, 'zhTW', '我準備好了。', '我準備好了。', 28153),
(152298, 'zhTW', '', '直到斯陀頌恩領主的頭掛在牆上，我才會善罷甘休。', 28153),
(152297, 'zhTW', '', '這才是我們要的火力！', 28153),
(152296, 'zhTW', '哼…好吧…', '哼…好吧…', 28153),
(152295, 'zhTW', '給我…記住…', '給我…記住…', 28153),
(152294, 'zhTW', '我…不會被…打敗…', '我…不會被…打敗…', 28153),
(152293, 'zhTW', '我…才是這裡的王…', '我…才是這裡的王…', 28153),
(152292, 'zhTW', '憑你也想在海灣稱王？我一樣會把你打得滿地找牙！', '憑你也想在海灣稱王？我一樣會把你打得滿地找牙！', 28153),
(152291, 'zhTW', '我是這個地方的老大！你最好有點分寸！', '我是這個地方的老大！你最好有點分寸！', 28153),
(152290, 'zhTW', '通通給我安靜。米基沒事，而我正試著在後頭睡覺。', '通通給我安靜。米基沒事，而我正試著在後頭睡覺。', 28153),
(152289, 'zhTW', '我會好好懲罰你！', '我會好好懲罰你！', 28153),
(152288, 'zhTW', '誰都別想跟鐵潮作對！', '誰都別想跟鐵潮作對！', 28153),
(152287, 'zhTW', '大膽！', '大膽！', 28153),
(152286, 'zhTW', '如果沿路上你找到寶藏，把它也帶回來。我會讓它變值得的。', '如果沿路上你找到寶藏，把它也帶回來。我會讓它變值得的。', 28153),
(152285, 'zhTW', '我要你好看…', '我要你好看…', 28153),
(152284, 'zhTW', '誰都別想跟鐵潮作對…', '誰都別想跟鐵潮作對…', 28153),
(152283, 'zhTW', '我會…逮到你…', '我會…逮到你…', 28153),
(152282, 'zhTW', '對不起…老大…', '對不起…老大…', 28153),
(152281, 'zhTW', '你根本不應該來這裡！', '你根本不應該來這裡！', 28153),
(152280, 'zhTW', '你在這裡鬼鬼祟祟地做什麼！', '你在這裡鬼鬼祟祟地做什麼！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152279, 'zhTW', '你不屬於這裡！', '你不屬於這裡！', 28153),
(152278, 'zhTW', '喂！', '喂！', 28153),
(152277, 'zhTW', '', '你知道煮湯的時候可以放鯨鯊的鰓嗎？可以防止鱗片腐爛！噢，我們剛剛講到哪了？', 28153),
(152276, 'zhTW', '', '我說的『每個人』，其實是指每個有金幣可以花的人。人類、哥布林、牛頭人、精靈，都無所謂。錢反正是錢，都一樣的。\n\n<瑟希上下打量著你>\n\n噢。你是想問我會不會跟部落做買賣對吧。\n\n聽好了，我也是要討生活的。我要是有從船後面掉下來的錨，我也會賣給第一個出現的客人。事情就是這麼簡單。等我稱王以後，所有人都要到海灣這裡來做生意。\n\n你總不會想跟鐵潮那些傢伙打交道，對吧？\n\n相信我，這絕對是好事一樁。', 28153),
(152275, 'zhTW', '我的孩子們可是比你更有禮貌。', '', 28153),
(152274, 'zhTW', '你說向「所有人」開放交易是什麼意思？', '你說向「所有人」開放交易是什麼意思？', 28153),
(152271, 'zhTW', '除非你想把那根手指留給我，否則最好不要再亂戳。', '', 28153),
(152270, 'zhTW', '本地的旅店已經住滿了難民，你有需要的話，我倒是有多的房間可以讓你住。', '', 28153),
(152269, 'zhTW', '別忘了，找到亮晶晶的東西，拿來給迦尼就對了。', '', 28153),
(152268, 'zhTW', '你走的時候，東西可以留給我嗎？', '', 28153),
(152266, 'zhTW', '祝你在骯髒破舊的角落都能找到朋友，哈！', '', 28153),
(152265, 'zhTW', '做得好，勇士！多虧有你，這裡總算是安全了。', '', 28153),
(152264, 'zhTW', '我們的斥候證實，有非常危險的生物在這個區域活動，去找出來解決掉！', '', 28153),
(152263, 'zhTW', '', '把零件組合起來，殺掉艾胥凡的寵物，否則一定擋不住艾胥凡的艦隊！', 28153),
(152262, 'zhTW', '', '他是個相當令人驕傲的托爾托人，如果殼大一點的話就更好了，你懂吧？可惜他被鯨鯊吃掉了。', 28153),
(152261, 'zhTW', '', '我根本就沒注意到她已經在打呼了。她講話的聲音聽起來也是那副德行。就跟我第二個孫子沒兩樣，我說真的。', 28153),
(152260, 'zhTW', '', '有人說我講起話來總是沒完沒了。不過，我姊姊比我更嚴重。你知道她之前講到睡著都還沒講完嗎？', 28153),
(152259, 'zhTW', '你要出門找東西的時候，把自己的家當放在垃圾堆裡就對了。', '', 28153),
(152258, 'zhTW', '', '現在的冒險者都很有禮貌。', 28153),
(152257, 'zhTW', '', '嗯，這樣很棒對吧？', 28153),
(152256, 'zhTW', '', '有空記得回來看看諾菈啊。', 28153),
(152255, 'zhTW', '', '這讓我想到一個故事…', 28153),
(152254, 'zhTW', '', '哇，你真是年輕有活力對吧？', 28153),
(152253, 'zhTW', '', '很高興見到你，親愛的。', 28153),
(152252, 'zhTW', '塑形師，只會讓糟透的想法稍微好一些！', '塑形師，只會讓糟透的想法稍微好一些！', 28153),
(152251, 'zhTW', '卡嘉可樂，現在添加真正的水！', '卡嘉可樂，現在添加真正的水！', 28153),
(152250, 'zhTW', '', '你看起來像是懂得欣賞好故事的人。', 28153),
(152249, 'zhTW', '', '找到節杖以後，到這個鬼洞窟的北邊找我。跟著屍體堆走就對了。', 28153),
(152248, 'zhTW', '你就繼續吧，我會讓你知道大家為什麼叫我牢騷鬼。', '', 28153),
(152246, 'zhTW', '你好啊，有錢人。', '', 28153),
(152243, 'zhTW', '就像我說過的，我的廢物搞不好是你的羅亞。', '', 28153),
(152241, 'zhTW', '', '在納茲米爾，有太多太多危險。你剷除了其中一個禍害。', 28153),
(152239, 'zhTW', '', '這些到底是什麼鬼東西？英雄，工程師有個工具正好能派上用場。燒掉它們，別讓它們擴散到整個營地都是！', 28153),
(152232, 'zhTW', '有你真好。多虧有你，這片沙漠才安全了一點。', '', 28153),
(152231, 'zhTW', '我們的人發現沙漠裡面藏著危險的生物。我相信你一定可以處理。', '', 28153),
(152230, 'zhTW', '泰莉亞，朋友，這是你必須肩負的責任。我會照顧山繆，等我們準備好以後，就到聖壇那裡會合。', '', 28153),
(152229, 'zhTW', '溝通中', '溝通中', 28153),
(152228, 'zhTW', '我就知道你夠聰明。走吧，我們到那裡碰面。', '我就知道你夠聰明。走吧，我們到那裡碰面。', 28153),
(152227, 'zhTW', '祝你順利把他們趕走！我是專門走私的，不是傭兵。', '祝你順利把他們趕走！我是專門走私的，不是傭兵。', 28153),
(152226, 'zhTW', '看來，是該把鐵潮這幫人趕走才對！', '看來，是該把鐵潮這幫人趕走才對！', 28153),
(152225, 'zhTW', '鐵潮那幫人快把我的錢搾乾了，瑟希。我都快入不敷出了。', '鐵潮那幫人快把我的錢搾乾了，瑟希。我都快入不敷出了。', 28153),
(152224, 'zhTW', '來吧…開始狩獵！', '', 28153),
(152223, 'zhTW', '', '你看，我們還是可以從這裡賺到錢嘛！', 28153),
(152222, 'zhTW', '', '這些都是想逃跑的人。一定還有倖存者。', 28153),
(152221, 'zhTW', '這是一次考驗。', '這是一次考驗。', 28153),
(152220, 'zhTW', '我們應該立刻攻擊，讓斯陀頌恩領主措手不及。', '', 28153),
(152219, 'zhTW', '|cFF0000FF(任務)|r航向納茲米爾。', '|cFF0000FF(任務)|r航向納茲米爾。', 28153),
(152218, 'zhTW', '', '這艘船就交給你來指揮，$n。我的船員能夠應付任何突發狀況。', 28153),
(152217, 'zhTW', '我們該從何下手？', '', 28153),
(152216, 'zhTW', '嘿，別太難過。下次再看到這些傢伙，你就想著要好好報這一箭之仇就好。', '', 28153),
(152215, 'zhTW', '不要因為這樣就責怪自己，我們還是大有斬獲的。', '', 28153),
(152214, 'zhTW', '大家快上船！立刻離開，不然船要完蛋了！', '', 28153),
(152213, 'zhTW', '勝敗乃兵家常事，對吧？我們下次再努力。', '', 28153),
(152212, 'zhTW', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|t某些防禦機制開始|cFFFF0000|Hspell:267931|h[超載]|h|r！', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|t某些防禦機制開始|cFFFF0000|Hspell:267931|h[超載]|h|r！', 28153),
(152211, 'zhTW', '啊，我們拿的也夠了，離開這個地方吧。', '', 28153),
(152210, 'zhTW', '你不可能每場都贏。這就是人生。', '', 28153),
(152209, 'zhTW', '呸！我們要走了。下次再換你們拿吧。', '', 28153),
(152208, 'zhTW', '今天的表現真棒，給他們好看，哈哈哈！', '', 28153),
(152207, 'zhTW', '完成啦！喂，經過聯盟船艦的時候賞他們幾發大砲吧，哈哈哈哈！', '', 28153),
(152206, 'zhTW', '船都裝滿了。揚起船帆，準備回家吧！', '', 28153),
(152205, 'zhTW', '我們需要的就是這些了。該閃人啦！啊哈哈！', '', 28153),
(152204, 'zhTW', '能拿多少就拿多少。我們要趕快離開了！', '', 28153),
(152203, 'zhTW', '看來另一艘船也準備要開走了。我們動作要快一點。', '', 28153),
(152202, 'zhTW', '看樣子庫爾提拉斯的船快裝滿了。我們也要趕快離開。', '', 28153),
(152201, 'zhTW', '就快完成了。只要再埋頭苦幹一下就好了。', '', 28153),
(152200, 'zhTW', '就快裝滿了。再多一些就大功告成了。', '', 28153),
(152199, 'zhTW', '就快大功告成了。你們做得很好！', '', 28153),
(152198, 'zhTW', '啊！這地震讓我連站都站不穩！這一定是強大的土元素，到這裡來跟我們搶艾澤萊晶岩了。', '', 28153),
(152197, 'zhTW', '這陣風會把一切都撕碎…這一定是風元素搞的鬼。搞不好它也有一堆艾澤萊晶岩…等著我們去搶！', '', 28153),
(152196, 'zhTW', '噢，這陣暴風雪一定是強大的水元素之王造成的。把它解決掉吧。我這個人最怕冷了。', '', 28153),
(152195, 'zhTW', '這裡越來越熱，一定是火元素之王來搶艾澤萊晶岩了。你最好在我們的船帆被燒掉前趕快解決它，哈哈。', '', 28153),
(152194, 'zhTW', '看來一定是元素之王搞的鬼。殺掉它們…把它們的艾澤萊晶岩搶過來！', '', 28153),
(152193, 'zhTW', '元素今天在跟我們作對。可能是想搶我們要的東西。', '', 28153),
(152192, 'zhTW', '喂，有些強大的元素已經注意到我們了。小心那個帶頭的！', '', 28153),
(152191, 'zhTW', '這種天氣很不尋常。一定是強大的元素來搶我們的艾澤萊晶岩了！', '', 28153),
(152190, 'zhTW', '我們的船才裝到半滿而已。好好專心幹活！', '', 28153),
(152189, 'zhTW', '你們的表現非常好。我們已經完成一半了！', '', 28153),
(152188, 'zhTW', '船上已經半滿了。繼續努力，我們很快就能大功告成了！', '', 28153),
(152187, 'zhTW', '哇噢，看來這下事情可精彩了！', '', 28153),
(152186, 'zhTW', '看來有些新朋友出現了，呵呵。', '', 28153),
(152185, 'zhTW', '喂，注意一點啊！敵人也到這裡來了。', '', 28153),
(152184, 'zhTW', '就是這裡了。快去吧，艾澤萊晶岩在等你！', '', 28153),
(152183, 'zhTW', '船靠岸了。你可不要在那裡被殺掉啊，嘿嘿。', '', 28153),
(152182, 'zhTW', '跳板放下來了，朋友們。我們會把探測器開好。', '', 28153),
(152181, 'zhTW', '喂，這裡有一大堆艾澤萊晶岩。你最好過來看一下。', '', 28153),
(152180, 'zhTW', '地上剛剛噴出了一大塊艾澤萊晶岩。快過去那裡！哈哈！', '', 28153),
(152179, 'zhTW', '哇，這儀器簡直發瘋了！一定是探測到大量的艾澤萊晶岩了。', '', 28153),
(152178, 'zhTW', '儀器可以運作了！把艾澤萊晶岩礦點標記在你的地圖上。', '', 28153),
(152177, 'zhTW', '探測器開了！在地圖上找找艾澤萊晶岩都集中在哪裡。', '', 28153),
(152176, 'zhTW', '我只是在休息眼睛！現在要上工了！', '', 28153),
(152175, 'zhTW', '好的，老大，我會回到礦坑去。', '', 28153),
(152174, 'zhTW', '好睏…好睏…', '', 28153),
(152173, 'zhTW', '噢！好，我會繼續工作，$n！', '', 28153),
(152172, 'zhTW', '解決咒毒妖術師及其根基圖騰。', '解決咒毒妖術師及其根基圖騰。', 28153),
(152171, 'zhTW', '又一片大陸，又一個惡魔可以狩獵。', '', 28153),
(152170, 'zhTW', '哈！你沒讓我失望過，我最喜歡這種船員了。', '', 28153),
(152169, 'zhTW', '我們大功告成了。做得好，我們回家吧。', '', 28153),
(152168, 'zhTW', '艾澤萊晶岩都裝滿了！我們快離開，別讓他們發現我們要走了。', '', 28153),
(152167, 'zhTW', '我們要走囉！哇，真是大豐收。你們表現真好。', '', 28153),
(152166, 'zhTW', '部落就快贏過我們了。盡你所能趕快收集艾澤萊晶岩！', '', 28153),
(152165, 'zhTW', '我要去…席帕拉…', '', 28153),
(152164, 'zhTW', '看樣子部落已經在收尾了。我們要是再不馬上離開就完蛋了。', '', 28153),
(152163, 'zhTW', '看來部落也快裝滿了。想辦法去多拿一點過來，可以嗎？', '', 28153),
(152162, 'zhTW', '不是我要催你們，不過部落的船看起來裝得很滿。等他們裝滿了，我們也得跟著出航。', '', 28153),
(152161, 'zhTW', '馬上就好了！眼觀四面，耳聽八方，你一定可以的。', '', 28153),
(152160, 'zhTW', '這些晶岩真是閃閃發亮！再多裝一點，我們就可以出發了。', '', 28153),
(152159, 'zhTW', '艾澤萊晶岩快滿了。升起船帆！等你好了我們就可以出發了。', '', 28153),
(152158, 'zhTW', '嘿，我們這邊差不多了！再裝一點，就可以準備開船了。', '', 28153),
(152157, 'zhTW', '地面怎麼在震動？晃到我快吐了。聽好，我們發現這裡有土元素，我敢說背後一定有元素領主在操控。趕快行動，我快把午餐吐出來了。', '', 28153),
(152156, 'zhTW', '船帆一定會被這陣颶風吹壞的。看來這是風元素領主派手下來搶艾澤萊晶岩了。有這些風元素在這裡，船要開到其他地方應該很難。', '', 28153),
(152155, 'zhTW', '嘿，英 - 英雄們？水元素之王派手下來搶我們的艾澤萊晶岩，我快冷 - 冷死了。趕快過去消滅它們！我可沒料到會這樣。', '', 28153),
(152154, 'zhTW', '這裡越來越熱了。這到底是怎麼回…噢，這下我知道了。火元素之王也派手下來找艾澤萊晶岩了。這真是太棒了。', '', 28153),
(152153, 'zhTW', '我們裝滿一半了！繼續努力，保持下去，我們很快就可以離開這裡了。', '', 28153),
(152152, 'zhTW', '艾澤萊晶岩快裝滿了。繼續努力，做得好。', '', 28153),
(152151, 'zhTW', '你踐踏了神聖之地！', '', 28153),
(152150, 'zhTW', '我準備好了。', '我準備好了。', 28153),
(152149, 'zhTW', '調查結果指向這些廢墟。部落營地就在東北方丘陵，我們最好盡速完成任務後脫離。\n\n我們會先他們一步得到席帕拉之息，我保證。\n\n當你準備好開始調查時就跟我說。', '', 28153),
(152148, 'zhTW', '探測器已經可以用了！看你的地圖就知道哪裡有艾澤萊晶岩了。', '', 28153),
(152147, 'zhTW', '探測器啟動了。我會把艾澤萊晶岩的位置標在地圖上。不用客氣。', '', 28153),
(152146, 'zhTW', '剛剛發現附近有一大片艾澤萊晶岩的晶簇。一定是這樣才會地震。', '', 28153),
(152145, 'zhTW', '哇，我們這附近出現了大量的艾澤萊晶岩。快去看看，別讓部落搶先了。', '', 28153),
(152144, 'zhTW', '船錨固定好，木板也放下了！我們會把艾澤萊晶岩探測器打開，壞人就交給你了。', '', 28153),
(152143, 'zhTW', '船靠岸啦！我們先把艾澤萊晶岩探測器搞定，你們就去冒險吧。', '', 28153),
(152142, 'zhTW', '我們到了，這陣風把我的頭髮吹得亂七八糟。我們趕快拿了艾澤萊晶岩就走，可以嗎？', '', 28153),
(152141, 'zhTW', '噢，看來這個元素之王也想要我們在找的這些艾澤萊晶岩。在你處理這個…突發狀況的時候，我還是到船艙裡晃一晃好了。', '', 28153),
(152140, 'zhTW', '看來元素也注意到艾澤萊晶岩了。搞不好是元素之王在對我們虎視眈眈。不過誰找到就是誰的，對吧？', '', 28153),
(152139, 'zhTW', '看來部落也找到這個地方來了。他們的船剛靠岸。', '', 28153),
(152138, 'zhTW', '呃，看樣子部落也來了。你記得小心周遭，好嗎？', '', 28153),
(152137, 'zhTW', '我看到有一艘黃金…什麼都有的船。對，一定是贊達拉人。部落也來了，小心一點。', '', 28153),
(152136, 'zhTW', '我也曾經是個像你這樣的冒險者…然後我就變強了。哈哈！', '', 28153),
(152135, 'zhTW', '你看起來像個見多識廣的人。我們可以分享一下戰場的故事。', '', 28153),
(152134, 'zhTW', '我還記得拉卡國王和他妹妹脫拉皇后的那場大戰。呃，我記得一部分啦。好吧，我是蠻肯定有那場大戰的，大概有五成信心吧。', '', 28153),
(152133, 'zhTW', '你讓我想起，在第三王朝時期，有個傢伙跟我一起在喀撒朗海邊大殺特殺。可惜他最後被魔古給解決掉了。', '', 28153),
(152132, 'zhTW', '牧喙就別丟人現眼！咳！', '', 28153),
(152131, 'zhTW', '這就是為什麼我不喜歡結伴。', '', 28153),
(152130, 'zhTW', '當你說你自己叫魔禍的時候，我以為意思是你是惡魔的災禍，但你根本是帶來災禍的惡魔。', '', 28153),
(152129, 'zhTW', '是時候讓他們屈服了！', '', 28153),
(152128, 'zhTW', '「我們到叢林去吧」你說。「去看看風景」你說。我早該知道，你的盲點會給我們帶來麻煩。', '', 28153),
(152127, 'zhTW', '如果我們死掉，全都是你的錯。', '', 28153),
(152126, 'zhTW', '我聽說你在隱瞞什麼。$b$b多虧一個…不小心…是馬里斯，不是我，我們必須來這個滿是嗜吃骨頭的怪物，而且又潮濕的鬼洞尋找這個可惡的惡魔。$b$b幫助我們，你就可以從她屍體上取走任何有價值的東西。$b$b我們只想要她身上的一張紙，不是什麼好看的東西。', '', 28153),
(152125, 'zhTW', '喔咳！都是你的！', '', 28153),
(152124, 'zhTW', '牧喙抓到魚了嗎？', '', 28153),
(152123, 'zhTW', '別打了！我的人類！', '', 28153),
(152122, 'zhTW', '你們人類永遠學不乖。', '', 28153),
(152121, 'zhTW', '或許你沒那麼常告訴他們，喔咳！', '', 28153),
(152120, 'zhTW', '我一定會…拿到寶藏…', '那些寶藏…是我的…', 28153),
(152119, 'zhTW', '', '好吧，被你逮到了。', 28153),
(152118, 'zhTW', '', '進來這裡，牧喙，別再四處亂逛！', 28153),
(152117, 'zhTW', '', '後退，傻鳥，我不需要你的幫助！', 28153),
(152116, 'zhTW', '', '一點也不痛，鯊魚餌，那就是你最強的一招？', 28153),
(152115, 'zhTW', '哈！我可是一直在找機會好好發洩一下！', '哈！我一直想找機會發洩怨氣！', 28153),
(152114, 'zhTW', '', '在他們不聽我的命令之前…我的心情很好…', 28153),
(152113, 'zhTW', '', '「你們人類」是指什麼？', 28153),
(152112, 'zhTW', '', '他們會離開我的船嗎？你最好相信我會重建巨角號，然後把每一個叛徒釘在船首斜桅上！', 28153),
(152111, 'zhTW', '', '一無是處的廢物！', 28153),
(152110, 'zhTW', '她會…永遠…統治…', '她會…永遠…統治…', 28153),
(152109, 'zhTW', '居然…會被你這種人…擊敗…', '居然…被你這種人…擊敗…', 28153),
(152108, 'zhTW', '部落…永遠…屬於她…', '部落…永遠…屬於她…', 28153),
(152107, 'zhTW', '又…來了…', '又…來了…', 28153),
(152106, 'zhTW', '死亡是唯一的道路！', '死亡是唯一的道路！', 28153),
(152105, 'zhTW', '你有聽到尖叫聲嗎？', '你有聽到尖叫聲嗎？', 28153),
(152104, 'zhTW', '不留活口！', '不留活口！', 28153),
(152103, 'zhTW', '為了黑暗女王！', '為了黑暗女王！', 28153),
(152102, 'zhTW', 'Lok-tar ogar！', 'Lok-tar ogar！', 28153),
(152101, 'zhTW', 'Lok-narash！', 'Lok-narash！', 28153),
(152100, 'zhTW', 'Gakarah ma！', 'Gakarah ma！', 28153),
(152099, 'zhTW', '不勝即亡！', '不勝即亡！', 28153),
(152098, 'zhTW', '為了部落！', '為了部落！', 28153),
(152097, 'zhTW', '敵人都去死吧！', '敵人都去死吧！', 28153),
(152096, 'zhTW', '我今天就要你的命！', '我今天就要你的命！', 28153),
(152095, 'zhTW', '我…死得…光榮…', '我…死得…光榮…', 28153),
(152094, 'zhTW', '祖先啊…我來了…', '祖先啊…我來了…', 28153),
(152093, 'zhTW', '這場仗…你一定會輸…', '這場仗…你一定會輸…', 28153),
(152092, 'zhTW', '你也一樣…會死…', '你也一樣…會死…', 28153),
(152091, 'zhTW', '至少我…英勇戰死…', '至少我…英勇戰死…', 28153),
(152090, 'zhTW', '我的戰鬥…結束了…', '我的戰鬥…結束了…', 28153),
(152089, 'zhTW', '我的生命…獻給德拉諾…', '我的生命…獻給德拉諾…', 28153),
(152088, 'zhTW', '你走吧。', '你走吧。', 28153),
(152087, 'zhTW', '快滾。', '快滾。', 28153),
(152086, 'zhTW', '別丟部落的臉。', '別丟部落的臉。', 28153),
(152085, 'zhTW', '死得壯烈。', '死得壯烈。', 28153),
(152084, 'zhTW', '我沒什麼話要說了。', '我沒什麼話要說了。', 28153),
(152083, 'zhTW', '你快走吧。', '你快走吧。', 28153),
(152082, 'zhTW', '願榮耀與你同行。', '願榮耀與你同行。', 28153),
(152081, 'zhTW', '願你的刀刃永遠鋒利。', '願你的刀刃永遠鋒利。', 28153),
(152080, 'zhTW', '前進吧，去獲得勝利。', '前進吧，去獲得勝利。', 28153),
(152079, 'zhTW', '不要忘記你的職責。', '不要忘記你的職責。', 28153),
(152078, 'zhTW', '說明你的來意。', '說明你的來意。', 28153),
(152077, 'zhTW', '我沒時間跟你瞎攪和。', '我沒時間跟你瞎攪和。', 28153),
(152076, 'zhTW', '什麼事？我在聽…', '什麼事？我在聽…', 28153),
(152075, 'zhTW', '說吧。', '說吧。', 28153),
(152074, 'zhTW', '幸會。', '幸會。', 28153),
(152073, 'zhTW', 'Lok-tar！', 'Lok-tar！', 28153),
(152072, 'zhTW', 'Throm-ka！', 'Throm-ka！', 28153),
(152071, 'zhTW', '有什麼事嗎？', '有什麼事嗎？', 28153),
(152070, 'zhTW', 'Zug-zug。', 'Zug-zug。', 28153),
(152069, 'zhTW', '力量與榮耀。', '力量與榮耀。', 28153),
(152068, 'zhTW', '從艾澤拉斯來的都這麼煩嗎？', '從艾澤拉斯來的都這麼煩嗎？', 28153),
(152067, 'zhTW', '我最喜歡殺整天來煩我的人。你確定還要繼續鬧我嗎？', '我最喜歡殺整天來煩我的人。你確定還要繼續鬧我嗎？', 28153),
(152066, 'zhTW', '告訴你，你惹我生氣了。我生氣的後果你可承擔不起。', '告訴你，你惹我生氣了。我生氣的後果你可承擔不起。', 28153),
(152065, 'zhTW', '獸人…猛擊！', '獸人…猛擊！', 28153),
(152064, 'zhTW', '他們一定還在牆外忙著應付女巫的手下。', '', 28153),
(152063, 'zhTW', '', '其他的審判官在哪裡？', 28153),
(152062, 'zhTW', 'Lok-tar ogar！', 'Lok-tar ogar！', 28153),
(152061, 'zhTW', '死在我的怒火之下吧！', '死在我的怒火之下吧！', 28153),
(152060, 'zhTW', '你的命運已經注定！', '你的命運已經注定！', 28153),
(152059, 'zhTW', '向部落屈服吧！', '向部落屈服吧！', 28153),
(152058, 'zhTW', '為了部落！', '為了部落！', 28153),
(152057, 'zhTW', '敵人都去死吧！', '敵人都去死吧！', 28153),
(152056, 'zhTW', '我今天就要你的命！', '我今天就要你的命！', 28153),
(152055, 'zhTW', '我…死得…光榮…', '我…死得…光榮…', 28153),
(152054, 'zhTW', '祖先啊…我來了…', '祖先啊…我來了…', 28153),
(152053, 'zhTW', '這場仗…你一定會輸…', '這場仗…你一定會輸…', 28153),
(152052, 'zhTW', '你也一樣…會死…', '你也一樣…會死…', 28153),
(152051, 'zhTW', '眾靈…帶我走…', '眾靈…帶我走…', 28153),
(152050, 'zhTW', '我的戰鬥…結束了…', '我的戰鬥…結束了…', 28153),
(152049, 'zhTW', '我的靈魂…回到德拉諾…', '我的靈魂…回到德拉諾…', 28153),
(152048, 'zhTW', '多帶一點錢再過來。', '多帶一點錢再過來。', 28153),
(152047, 'zhTW', '希望這些東西你還喜歡。', '希望這些東西你還喜歡。', 28153),
(152046, 'zhTW', '記得再來。', '記得再來。', 28153),
(152045, 'zhTW', '死得壯烈。', '死得壯烈。', 28153),
(152044, 'zhTW', '我沒什麼話要說了。', '我沒什麼話要說了。', 28153),
(152043, 'zhTW', '話說夠了。', '話說夠了。', 28153),
(152042, 'zhTW', '願榮耀與你同行。', '願榮耀與你同行。', 28153),
(152041, 'zhTW', '願眾靈指引你的道路。', '願眾靈指引你的道路。', 28153),
(152040, 'zhTW', '前進吧，去獲得勝利。', '前進吧，去獲得勝利。', 28153),
(152039, 'zhTW', '就這樣吧。', '就這樣吧。', 28153),
(152038, 'zhTW', '你在找什麼嗎？', '你在找什麼嗎？', 28153),
(152037, 'zhTW', '需要什麼嗎？', '需要什麼嗎？', 28153),
(152036, 'zhTW', '歡迎看看。', '歡迎看看。', 28153),
(152035, 'zhTW', '說吧。', '說吧。', 28153),
(152034, 'zhTW', '幸會。', '幸會。', 28153),
(152033, 'zhTW', 'Lok-tar！', 'Lok-tar！', 28153),
(152032, 'zhTW', 'Throm-ka！', 'Throm-ka！', 28153),
(152031, 'zhTW', '有什麼事嗎？', '有什麼事嗎？', 28153),
(152030, 'zhTW', 'Zug-zug。', 'Zug-zug。', 28153),
(152029, 'zhTW', '力量與榮耀。', '力量與榮耀。', 28153),
(152028, 'zhTW', '從艾澤拉斯來的都這麼惹人厭嗎？', '從艾澤拉斯來的都這麼煩嗎？', 28153),
(152027, 'zhTW', '我最喜歡殺整天來煩我的人。你確定還要繼續鬧我嗎？', '我最喜歡殺整天來煩我的人。你確定還要繼續鬧我嗎？', 28153),
(152026, 'zhTW', '陌生人，你惹我生氣了。我生氣的後果你可承擔不起。', '陌生人，你惹我生氣了。我生氣的後果你可承擔不起。', 28153),
(152025, 'zhTW', '獸人…猛擊！！', '獸人…猛擊！！', 28153),
(152024, 'zhTW', '正在煮剛抓上來的新鮮魚肉。沒什麼比這個更棒的了。', '', 28153),
(152023, 'zhTW', '', '我們不斷遠行，想逃離這一切。卻只能逃到這麼遠的地方。風景太美了。', 28153),
(152017, 'zhTW', '它怎麼會破壞鎖鍊！', '它怎麼會破壞鎖鍊！', 28153),
(152016, 'zhTW', '快逃，別被它發現了！', '快逃，別被它發現了！', 28153),
(152015, 'zhTW', '鮮血感染！', '', 28153),
(152014, 'zhTW', '檢視花朵', '檢視花朵', 28153),
(152013, 'zhTW', '瑟沙利斯化身不再受到妖術影響！補滿它的生命力值來瓦解防禦！', '瑟沙利斯化身不再受到妖術影響！補滿它的生命力值來瓦解防禦！', 28153),
(152012, 'zhTW', '進化！', '', 28153),
(152011, 'zhTW', '感染！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152010, 'zhTW', '瘟疫蔓延！', '', 28153),
(152009, 'zhTW', '殘暴育血！', '', 28153),
(152008, 'zhTW', '吞噬軀殼！', '', 28153),
(152007, 'zhTW', '夠了！這是你們部落自找的。', '', 28153),
(152006, 'zhTW', '致命病毒株。感染，成功。', '', 28153),
(152005, 'zhTW', '我的變身失效了，你還有卷軸嗎？', '我的變身失效了，你還有卷軸嗎？', 28153),
(152004, 'zhTW', '叢林大嘴蛙跳進水中！', '', 28153),
(152003, 'zhTW', '爛東西！', '', 28153),
(152002, 'zhTW', '成為感染的對象吧！', '', 28153),
(152001, 'zhTW', '病菌爆發…無法避免…', '', 28153),
(152000, 'zhTW', '', '很好，呸，沒什麼好的。', 28153),
(151999, 'zhTW', '', '你找到豪郝先生那個幕後主使了嗎？', 28153),
(151998, 'zhTW', '新鮮的宿體！', '', 28153),
(151990, 'zhTW', '至於現在…該拿點戰利品了。', '', 28153),
(151989, 'zhTW', '我們拿到珍珠了！有了珍珠，我們的船就是海中的掠食者。', '', 28153),
(151987, 'zhTW', '', '好好享受這場勝利吧。沒有下一次了。', 28153),
(151986, 'zhTW', '這是荒野的法則，弱肉強食。', '', 28153),
(151985, 'zhTW', '提高警覺。有看不見的東西跟著我們。', '', 28153),
(151983, 'zhTW', '不能讓聯盟拿到這個寶物，妨礙我們的人會一個個倒下！', '', 28153),
(151982, 'zhTW', '', '我又可以做生意了，太好了。讓瑟希稱王就代表我們又可以在這裡賺大錢了。', 28153),
(151981, 'zhTW', '你會支持瑟希‧散砲嗎？', '你會支持瑟希‧散砲嗎？', 28153),
(151980, 'zhTW', '', '這個地方以前更好賺錢。', 28153),
(151979, 'zhTW', '', '我們得在被困住之前離開這裡。跟我來！', 28153),
(151978, 'zhTW', '斯陀頌恩家族會統治這個潮水洶湧的國度。潮母的憤怒會讓這件事成真。', '', 28153),
(151977, 'zhTW', '那支艦隊…注定是她的…', '', 28153),
(151976, 'zhTW', '我只是在逗他們玩，領主。我會處理好的！', '', 28153),
(151975, 'zhTW', '我們就要面對命運了。絕對不能讓他們進入風暴聖壇。', '', 28153),
(151974, 'zhTW', '', '看看你變成什麼了。你的手上沾了多少鮮血！', 28153),
(151973, 'zhTW', '卷軸飄浮著，發出嗡鳴，其他地方的預言被魔法弄得模糊不清。', '', 28153),
(151972, 'zhTW', '世界之魂生存機率：趨近於零…', '', 28153),
(151971, 'zhTW', '即將發生星球感染。', '', 28153),
(151970, 'zhTW', '我們應該讓鐵潮拿到寶藏。', '我們應該讓鐵潮拿到寶藏。', 28153),
(151969, 'zhTW', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s製造一個|cFFFF0000|Hspell:267891|h[迅捷結界]|h|r！', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s製造一個|cFFFF0000|Hspell:267891|h[迅捷結界]|h|r！', 28153),
(151968, 'zhTW', '<直接刺他>', '<直接刺他>', 28153),
(151967, 'zhTW', '…你是認真的嗎？', '…你是認真的嗎？', 28153),
(151966, 'zhTW', '太離譜了！我才不付這個錢！', '太離譜了！我才不付這個錢！', 28153),
(151965, 'zhTW', '睡地板過夜要五十金幣。火爐邊的區域要六十金幣。自己帶毯子來。\n\n床位要一百金幣。\n\n綁定你的爐石一週要七十五金幣。\n\n不滿意？\n\n<他雙手抱胸，輕蔑地一笑。>\n\n可惜，這些就是現在的行情。', '', 28153),
(151964, 'zhTW', '深海說過你的到來…還有你的死亡！', '', 28153),
(151963, 'zhTW', '偵測到大規模損壞。', '', 28153),
(151962, 'zhTW', '', '我們現在必須集合所有的人，從源頭阻止腐化。', 28153),
(151961, 'zhTW', '', '雖然有泰坦幫忙爭取時間，但是我們沒辦法囚禁古翰太久。', 28153),
(151960, 'zhTW', '偵測到劇毒樣本，隔離優先層級為最優先級。', '', 28153),
(151959, 'zhTW', '吞噬！消解！擴散！', '', 28153),
(151958, 'zhTW', '', '這個東西好像在找媽媽？希望他能帶我們找到能阻止荒疫擴散的辦法。', 28153),
(151957, 'zhTW', '古翰的隔離防壁失效。母親大人沒有回應。', '', 28153),
(151954, 'zhTW', '', '如果真的擴散到地面上，我們根本無法控制。', 28153),
(151953, 'zhTW', '', '我從來沒有看過這種腐化形態。', 28153),
(151952, 'zhTW', '', '絕對不可以讓這玩意到地面上！立刻殺了牠！', 28153),
(151951, 'zhTW', '', '啊！這到底是什麼鬼東西？！', 28153),
(151950, 'zhTW', '', '大家務必小心。誰知道這洞窟裡還會有什麼。', 28153),
(151949, 'zhTW', '', '鮮血食人妖是烏合之眾，但我們還是必須摧毀腐化根源。', 28153),
(151948, 'zhTW', '偉大的死亡羅亞，這是獻給您的祭品！', '', 28153),
(151947, 'zhTW', '如果這代表我們會有新成員加入，那我會照做。', '', 28153),
(151946, 'zhTW', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t $s開始施放|cFFFF0404|Hspell:260773|h[兇蠻儀式]|h|r！', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t %s開始施放|cFFFF0404|Hspell:260773|h[兇蠻儀式]|h|r！', 28153),
(151945, 'zhTW', '你會支持瑟希‧散砲嗎？', '你會支持瑟希‧散砲嗎？', 28153),
(151944, 'zhTW', '你是要買還是要賣？', '', 28153),
(151943, 'zhTW', '', '情況真是不妙…', 28153),
(151942, 'zhTW', '我很樂意。我會為你折磨他們！', '', 28153),
(151941, 'zhTW', '偵測到感染狀況，進行消毒。', '', 28153),
(151940, 'zhTW', '瘟疫爆發！', '', 28153),
(151939, 'zhTW', '啟動最終防衛機制，消滅病毒源頭。', '', 28153),
(151938, 'zhTW', '馬上到，領主。讓我先擺脫那堆害蟲就好。', '馬上到，領主。但讓我先擺脫那堆害蟲就好。', 28153),
(151937, 'zhTW', '正在淨化此區域。', '', 28153),
(151936, 'zhTW', '啟動淨化程序。', '', 28153),
(151935, 'zhTW', '邪惡爆裂！', '', 28153),
(151934, 'zhTW', '只是斷了幾根骨頭…沒什麼大礙。', '', 28153),
(151933, 'zhTW', '帶我們去狐狸人的營地，$p。我們會把寶藏拖走。', '', 28153),
(151932, 'zhTW', '鮮血噴發！', '', 28153),
(151931, 'zhTW', '', '放下武器！你不必這麼做！', 28153),
(151930, 'zhTW', '一定要…擴散…', '', 28153),
(151929, 'zhTW', '荒疫致命！', '', 28153),
(151928, 'zhTW', '感染！', '', 28153),
(151927, 'zhTW', '腐化血肉。', '', 28153),
(151926, 'zhTW', '吞噬！', '', 28153),
(151925, 'zhTW', '一定要擴散！', '', 28153),
(151924, 'zhTW', '你可不要忘記我們的交易條件，呵呵…', '', 28153),
(151923, 'zhTW', '哈哈哈哈！陛下，看到了沒？伯昂撒姆第一向說話算話！', '', 28153),
(151922, 'zhTW', '起來吧！別再偷懶了！拿起長矛繼續奮戰！', '', 28153),
(151921, 'zhTW', '別擔心，陛下。伯昂撒姆第最會照顧朋友了…', '', 28153),
(151920, 'zhTW', '', '你不用一直看我工作啊，我們都有工作要做。', 28153),
(151919, 'zhTW', '只要我們準備好，船隨時可出發。', '', 28153),
(151918, 'zhTW', '這些背叛者是我和帝國之間的阻礙，可你承諾的援助在哪裡？你打算遵守諾言嗎？', '', 28153),
(151916, 'zhTW', '勇士，做得好。多虧有你，我可以感覺到艾澤拉斯逐漸復原了。', '', 28153),
(151915, 'zhTW', '附近出現了好幾個艾澤萊晶岩傷口，快使用艾澤拉斯之心來讓傷口癒合！', '', 28153),
(151913, 'zhTW', '還能跑的時候趕快逃跑吧！', '', 28153),
(151912, 'zhTW', '咳咳！這種說法對羅亞非常不敬，陛下。但我認為今天收集的靈魂就足以彌補這一切！', '', 28153),
(151911, 'zhTW', '我們現在是同生共死了，$p。\n\n叛變或是走橫桅！', '', 28153),
(151910, 'zhTW', '伯昂撒姆第，趕快現身！', '', 28153),
(151909, 'zhTW', '跟隨祖爾的人實在太多。只剩下最後一條路了…', '', 28153),
(151908, 'zhTW', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s看著|cFFFF0000$n|r，準備要|cFFFF0000|Hspell:266951|h[一穿而過]|h|r！', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s看著|cFFFF0000$n|r，準備要|cFFFF0000|Hspell:266951|h[一穿而過]|h|r！', 28153),
(151907, 'zhTW', '守護瑟沙利斯之心的遠古結界已被一群贊達拉人解除…', '守護瑟沙利斯之心的遠古結界已被一群贊達拉人解除…', 28153),
(151906, 'zhTW', '會，瑟希一定會得到我的支持。', '', 28153),
(151905, 'zhTW', '你們這些哥布林懶蟲，動作快點，我要盒中基地立刻設置完成！', '你們這些哥布林懶蟲，動作快點，我要盒中基地立刻設置完成！', 28153),
(151904, 'zhTW', '你會支持瑟希‧散砲嗎？', '你會支持瑟希‧散砲嗎？', 28153),
(151902, 'zhTW', '嗯。好，我來看看。\n\n<庫達找了好一陣子，才從那堆東西深處拖出一個罐子。>\n\n我幾百年前買了這個，都忘了它的存在。我想應該可以把它賣了。', '', 28153),
(151901, 'zhTW', '你有沒有聽過一種叫做「百年醬」的東西？這個你有嗎？', '你有沒有聽過一種叫做「百年醬」的東西？這個你有嗎？', 28153),
(151900, 'zhTW', '你好，$r。你需要什麼新奇的玩意嗎？', '', 28153),
(151899, 'zhTW', '浪潮啊，它過來了！', '浪潮啊，它過來了！', 28153),
(151898, 'zhTW', '飢餓永無止盡，國王貪婪宴飲。', '', 28153),
(151897, 'zhTW', '創口潰爛。世界腐敗。', '', 28153),
(151896, 'zhTW', '我們一直都在你的心靈深處。', '', 28153),
(151895, 'zhTW', '腐臭的尖叫是他到來的前兆。', '', 28153),
(151894, 'zhTW', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|t『智者』薩納瑟爾開始施放|cFFFF0000|Hspell:267273|h[劇毒新星]|h|r！', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|t『智者』薩納瑟爾開始施放|cFFFF0000|Hspell:267273|h[劇毒新星]|h|r！', 28153),
(151893, 'zhTW', '', '潛伏者甦醒了！', 28153),
(151892, 'zhTW', '', 'Kril lax qutholil！', 28153),
(151890, 'zhTW', '你作為我的代表，擊敗了納迦，終止了他們發動的神廟攻擊行動。', '', 28153),
(151889, 'zhTW', '', '噢！我想試試百年醬已經想好久了！這是種混合多種原料再發酵好幾百年的調理醬。發酵越久，味道就越有層次。聽說這種醬可以為任何菜色帶來獨特的風味。\n\n聽說有些托爾托商人有貨，但這種醬非常稀有，也非常昂貴。\n\n<薰薰惆悵地嘆氣>\n\n那可是廚師的夢想食材啊！', 28153),
(151888, 'zhTW', '你的儲藏室真是應有盡有。香料架上還缺什麼東西嗎？', '你的儲藏室真是應有盡有。香料架上還缺什麼東西嗎？', 28153),
(151887, 'zhTW', '', '新面孔！感覺好像還蠻友善的。想來點特別的嗎？還是你想找稀有的香料或食譜？', 28153),
(151886, 'zhTW', '多虧有你，艾澤拉斯之心變得更強大。我們就快能治療艾澤拉斯的傷口了。', '', 28153),
(151885, 'zhTW', '我感覺到，艾澤萊晶岩就在附近…這群想濫用晶岩的人也在附近。你一定要阻止他們！', '', 28153),
(151884, 'zhTW', '來吧，小樹苗。靜下心來，幫我一起治療這個人。', '', 28153),
(151883, 'zhTW', '', '深淵之中，鮮血翻湧。', 28153),
(151882, 'zhTW', '', '你要的真相，就在潮水之下等你。', 28153),
(151881, 'zhTW', '', '聆聽溺死之人的樂章吧。', 28153),
(151880, 'zhTW', '', '黑暗扎根。疫病散播。門戶大開。', 28153),
(151879, 'zhTW', '', '深淵會連你的尖叫聲一起吞沒！', 28153),
(151878, 'zhTW', '', '我就在你的肺裡！', 28153),
(151877, 'zhTW', '', '我會在黑暗中…等你…', 28153),
(151876, 'zhTW', '', '我要殺了你！', 28153),
(151875, 'zhTW', '', '你的盟友會很樂意看到你去死。', 28153),
(151874, 'zhTW', '', '我們會永遠束縛在汪洋之中。', 28153),
(151873, 'zhTW', '你們完全沒有任何用處。', '', 28153),
(151872, 'zhTW', '脆弱！毫無價值！', '', 28153),
(151871, 'zhTW', '你們是最弱的品種！', '', 28153),
(151870, 'zhTW', '這怎麼…可能…', '', 28153),
(151869, 'zhTW', 'Ul basha krix。', '', 28153),
(151868, 'zhTW', '', '對空中開火！把他們射下來！', 28153),
(151867, 'zhTW', '次等種族只配當奴隸…或受死！', '', 28153),
(151866, 'zhTW', '', '為了部落！', 28153),
(151865, 'zhTW', '', '絕不留情！', 28153),
(151864, 'zhTW', 'Ug\' crish zul Thraxas！', '', 28153),
(151863, 'zhTW', '', '繼續火力支援！地面部隊的生死就掌握在你手上。', 28153),
(151862, 'zhTW', '', '繼續開火！', 28153),
(151861, 'zhTW', '這座墳墓會是你的長眠之地！', '', 28153),
(151860, 'zhTW', '你別想對抗贊達拉人！', '', 28153),
(151859, 'zhTW', '古翰的力量控制著這座神廟！', '', 28153),
(151858, 'zhTW', '贊達拉人會統治世界！', '', 28153),
(151857, 'zhTW', '', '這邊！踏上熱戰和榮耀的征途！', 28153),
(151856, 'zhTW', '誰都別想阻擋古翰！', '', 28153),
(151855, 'zhTW', '把鮮血獻給血神！', '', 28153),
(151854, 'zhTW', '我先到處挖挖看能找到什麼。無論找到什麼，我都會立刻告訴你。', '', 28153),
(151853, 'zhTW', '你剛剛聽到了吧！我們必須找出上古之神的腐化…然後才能處理它！', '', 28153),
(151852, 'zhTW', '哈哈！祖爾，這就是你的大絕招嗎？難怪食人妖帝國會毀滅！', '', 28153),
(151850, 'zhTW', '我敢說一定有辦法把你的屍體塞進石棺裡。', '', 28153),
(151849, 'zhTW', '光榮與榮耀，我為風暴之甦而戰！', '光榮與榮耀，我為風暴之甦而戰！', 28153),
(151848, 'zhTW', '我的刀刃為你效勞。', '我的刀刃為你效勞。', 28153),
(151847, 'zhTW', '我還沒死呢！', '我還沒死呢！', 28153),
(151846, 'zhTW', '我們將一起阻止這些惡魔！', '我們將一起阻止這些惡魔！', 28153),
(151845, 'zhTW', '只要我還有一口氣，這個山谷就不會受到佔領！', '只要我還有一口氣，這個山谷就不會受到佔領！', 28153),
(151844, 'zhTW', '若風暴之甦呼喚我，我就必須回應。', '若風暴之甦呼喚我，我就必須回應。', 28153),
(151843, 'zhTW', '無論生死，我們的時刻已來臨。', '無論生死，我們的時刻已來臨。', 28153),
(151842, 'zhTW', '我同意！', '我同意！', 28153),
(151841, 'zhTW', '喔，祖爾，可惜你不在場，你該看看這些魔像的下場。', '', 28153),
(151840, 'zhTW', '哈！我們走著瞧，你這個沒種的食人妖！', '', 28153),
(151839, 'zhTW', '他們會再度現身，擊垮敢跟古翰作對的傢伙！', '', 28153),
(151838, 'zhTW', '我們或許還有機會！為了風暴之甦！', '我們或許還有機會！為了風暴之甦！', 28153),
(151837, 'zhTW', '蠢貨！我的力量已經把這些先人的靈魂和主人的意志合而為一了。', '', 28153),
(151836, 'zhTW', '我聽到風暴之歌。還有希望！', '我聽到風暴之歌。還有希望！', 28153),
(151835, 'zhTW', '還有其他人在。我們還有希望！', '還有其他人在。我們還有希望！', 28153),
(151834, 'zhTW', '我不知道這裡受到什麼黑暗魔法影響，但我們一定要想辦法驅散魔法。', '', 28153),
(151833, 'zhTW', '我們絕非這樣的人。我們依然能阻止斯陀頌恩領主！', '我們絕非這樣的人。我們依然能阻止斯陀頌恩領主！', 28153),
(151832, 'zhTW', '根據我的研究，這裡就是贊達拉的開國神王陵寢。', '', 28153),
(151831, 'zhTW', '我們攻破大門了，前進！為了聯盟奪回阿拉希！', '', 28153),
(151830, 'zhTW', '派克還活著？我會立刻把他找出來。', '派克還活著？我會立刻把他找出來。', 28153),
(151829, 'zhTW', '攻陷大門了。去吧，把阿拉希從部落手中奪回來！', '', 28153),
(151828, 'zhTW', '攻破大門啦！前進！前進！', '', 28153),
(151827, 'zhTW', '', '大門已經攻破了！繼續攻擊！', 28153),
(151826, 'zhTW', '大門攻破了！掃蕩堡壘！', '', 28153),
(151825, 'zhTW', '為了贊達拉…和你的王國…你一定要阻止他。', '', 28153),
(151824, 'zhTW', '攻破大門了！現在拿下堡壘吧！', '', 28153),
(151823, 'zhTW', '我們必須立刻開啟風暴聖壇！', '我們必須立刻開啟風暴聖壇！', 28153),
(151822, 'zhTW', '他的主人還在累積力量。祖爾在血神掌握整個世界之前，都不會善罷干休。', '', 28153),
(151821, 'zhTW', '成功了。我們已經奪回阿拉希了。為了聯盟！', '', 28153),
(151820, 'zhTW', '風暴在我體內甦醒。我將對抗暗影！', '風暴在我體內甦醒。我將對抗暗影！', 28153),
(151819, 'zhTW', '', '我們的勝利是毋庸置疑的。為了部落！', 28153),
(151818, 'zhTW', '你讓我從殘酷的命運中解脫了，不過祖爾只是整個計畫中的一個小角色。', '', 28153),
(151817, 'zhTW', '回去向你的主人哀求吧，看看他會怎樣對付失敗的人！', '', 28153),
(151816, 'zhTW', '我知道這天終將到來。我會加入其他人。', '我知道這天終將到來。我會加入其他人。', 28153),
(151815, 'zhTW', '不可能！誰都別想違抗古翰！', '', 28153),
(151814, 'zhTW', '你打破了祖爾的束縛！我不用再服侍那頭蠢豬了！', '', 28153),
(151813, 'zhTW', '儘管抱怨吧，國王…反正你心知肚明，已經逃不出古翰的掌握。', '', 28153),
(151812, 'zhTW', '這些入侵者都會死…不過我在動手的時候可不需要聽你那些蠢話。', '', 28153),
(151811, 'zhTW', '我一輩子都在抵抗你的主人，卻在死後被你束縛於他的意志之下。', '', 28153),
(151810, 'zhTW', '閉嘴，說謊的先知！', '', 28153),
(151809, 'zhTW', '這裡是贊達拉首任國王的長眠之地。達薩是很固執，不過他還不是一樣臣服了！', '', 28153),
(151808, 'zhTW', '你瘋了嗎？', '你瘋了嗎？', 28153),
(151807, 'zhTW', '說明你的來意。', '說明你的來意。', 28153),
(151806, 'zhTW', '死了以後，我讓他們團結一致。這樣才能殺了你。', '', 28153),
(151805, 'zhTW', '大地支配了我。', '大地支配了我。', 28153),
(151804, 'zhTW', '他們在世的時候憎恨彼此，最後讓彼此走向毀滅。', '', 28153),
(151803, 'zhTW', '現在在你前方的這三位統治者，在沒有任何食人妖能獨尊的時候統治這個帝國。', '', 28153),
(151802, 'zhTW', '外來者不能來這。', '外來者不能來這。', 28153),
(151801, 'zhTW', '隨著大海退去，土地也會再次露出！', '隨著大海退去，土地也會再次露出！', 28153),
(151800, 'zhTW', '我敢說它一定也能把你「處理」掉。', '', 28153),
(151799, 'zhTW', '神廟內塞滿了屍體，所以才造出魔像處理這些病死的人。', '', 28153),
(151798, 'zhTW', '數千年前，一場鮮血疫病幾乎讓贊達拉人因此滅絕。', '', 28153),
(151797, 'zhTW', '他們會再度現身，擊垮敢跟古翰作對的傢伙！', '', 28153),
(151796, 'zhTW', '我的力量佔據了這裡，先人的靈魂已經束縛於主人的意志。', '', 28153),
(151795, 'zhTW', '歡迎來到首位食人妖國王的陵寢。真希望我能親自迎接你們。', '', 28153),
(151794, 'zhTW', '我告訴過你，我不會跟你一起發瘋！', '我告訴過你，我不會跟你一起發瘋！', 28153),
(151793, 'zhTW', '這次我才不上當。', '這次我才不上當。', 28153),
(151792, 'zhTW', '安…安全嗎？', '安…安全嗎？', 28153),
(151791, 'zhTW', '我們是創業家也是遷徙專家。跟那些該死的紅外套傭兵不一樣，我們不是海盜。', '', 28153),
(151790, 'zhTW', '', '英雄，我們回去找凱瑟琳吧。', 28153),
(151789, 'zhTW', '', '你們三個帶隊下去搜查，一定要抓住她！', 28153),
(151788, 'zhTW', '', '等等，可惡！', 28153),
(151787, 'zhTW', '', '傲慢的小鬼。事情還沒結束！', 28153),
(151786, 'zhTW', '', '結束了，你沒地方跑了。', 28153),
(151785, 'zhTW', '', '快讓路，一群漿糊腦袋！', 28153),
(151784, 'zhTW', '', '看招！', 28153),
(151783, 'zhTW', '', '你的小花招毫無意義！這座城市是我的！', 28153),
(151782, 'zhTW', '我會在這裡等待找到回家的路的幸運兒！', '', 28153),
(151781, 'zhTW', '', '換我稱王以後，情況一定會好很多。\n\n等這些鐵潮海盜一走，每個人都可以來這裡自由交易。這樣一定很棒！', 28153),
(151780, 'zhTW', '', '呃！在那些穿紅外套的混球出現之前，情況還沒這麼糟。', 28153),
(151779, 'zhTW', '聽著，我只是想討生活而已。', '', 28153),
(151778, 'zhTW', '裂帆和他的手下妨礙了生意。要是情況變得更糟，我大概會帶著我的鳥離開。', '', 28153),
(151777, 'zhTW', '我本來要發大財的…', '', 28153),
(151776, 'zhTW', '你想阻撓我們嗎？我一點也不介意殺了你！', '', 28153),
(151775, 'zhTW', '', '你不能奪走這片林地！', 28153),
(151774, 'zhTW', '', '感謝你。我覺得我能一個人對抗他們。我現在要回到莫爾溫那裡。', 28153),
(151773, 'zhTW', '我喜歡你對這地方的佈置。', '', 28153),
(151772, 'zhTW', '我們托爾托人在這裡貿易已經非常久了，後來贊達拉在我們周圍崛起，但他們現在遭遇了困難。至於我們，當然會存活下去。', '', 28153),
(151771, 'zhTW', '我要在這工作，不需要踏上危險之路。', '', 28153),
(151770, 'zhTW', 'Lok-tar ogar！', 'Lok-tar ogar！', 28153),
(151769, 'zhTW', 'Lok-narash！', 'Lok-narash！', 28153),
(151768, 'zhTW', 'Gakarah ma！', 'Gakarah ma！', 28153),
(151767, 'zhTW', '向部落屈服吧！', '向部落屈服吧！', 28153),
(151766, 'zhTW', '為了部落！', '為了部落！', 28153),
(151765, 'zhTW', '敵人都去死吧！', '敵人都去死吧！', 28153),
(151764, 'zhTW', '我今天就要你的命！', '我今天就要你的命！', 28153),
(151763, 'zhTW', '我…死得…光榮…', '我…死得…光榮…', 28153),
(151762, 'zhTW', '哈！前來報到，我明白了。把它丟到箱子裡，然後繼續工作！', '', 28153),
(151761, 'zhTW', '祖先啊…我來了…', '祖先啊…我來了…', 28153),
(151760, 'zhTW', '這場仗…你一定會輸…', '這場仗…你一定會輸…', 28153),
(151759, 'zhTW', '你也一樣…會死…', '你也一樣…會死…', 28153),
(151758, 'zhTW', '至少我…英勇戰死…', '至少我…英勇戰死…', 28153),
(151757, 'zhTW', '我的戰鬥…結束了…', '我的戰鬥…結束了…', 28153),
(151756, 'zhTW', '我的靈魂…回到德拉諾…', '我的靈魂…回到德拉諾…', 28153),
(151755, 'zhTW', '死得壯烈。', '死得壯烈。', 28153),
(151754, 'zhTW', '我沒什麼話要說了。', '我沒什麼話要說了。', 28153),
(151753, 'zhTW', '你快走吧。', '你快走吧。', 28153),
(151752, 'zhTW', '願榮耀與你同行。', '願榮耀與你同行。', 28153),
(151751, 'zhTW', '願你的刀刃永遠鋒利。', '願你的刀刃永遠鋒利。', 28153),
(151750, 'zhTW', '前進吧，去獲得勝利。', '前進吧，去獲得勝利。', 28153),
(151749, 'zhTW', '就這樣吧。', '就這樣吧。', 28153),
(151748, 'zhTW', '說吧。', '說吧。', 28153),
(151747, 'zhTW', '幸會。', '幸會。', 28153),
(151746, 'zhTW', 'Lok-tar！', 'Lok-tar！', 28153),
(151745, 'zhTW', 'Throm-ka！', 'Throm-ka！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151744, 'zhTW', '有什麼事嗎？', '有什麼事嗎？', 28153),
(151743, 'zhTW', 'Zug-zug。', 'Zug-zug。', 28153),
(151742, 'zhTW', '力量與榮耀。', '力量與榮耀。', 28153),
(151741, 'zhTW', '下次多買一點。', '下次多買一點。', 28153),
(151740, 'zhTW', '希望這些東西你還喜歡。', '希望這些東西你還喜歡。', 28153),
(151739, 'zhTW', '不得退款！', '不得退款！', 28153),
(151738, 'zhTW', '你在找什麼嗎？', '你在找什麼嗎？', 28153),
(151737, 'zhTW', '需要什麼嗎？', '需要什麼嗎？', 28153),
(151736, 'zhTW', '歡迎看看。', '歡迎看看。', 28153),
(151735, 'zhTW', '從艾澤拉斯來的都這麼煩嗎？', '從艾澤拉斯來的都這麼煩嗎？', 28153),
(151734, 'zhTW', '我最喜歡殺整天來煩我的人。你確定還要繼續鬧我嗎？', '我最喜歡殺整天來煩我的人。你確定還要繼續鬧我嗎？', 28153),
(151733, 'zhTW', '告訴你，你惹我生氣了。我生氣的後果你可承擔不起。', '告訴你，你惹我生氣了。我生氣的後果你可承擔不起。', 28153),
(151732, 'zhTW', '獸人…猛擊！', '獸人…猛擊！', 28153),
(151731, 'zhTW', '來…快來，親愛的瑞邦啊。來吃飯吧！', '', 28153),
(151730, 'zhTW', '<歡呼聲>', '', 28153),
(151729, 'zhTW', '<打呵欠>', '', 28153),
(151728, 'zhTW', '<喔呼！>', '', 28153),
(151727, 'zhTW', '<喔呼！>', '', 28153),
(151726, 'zhTW', '<學雞叫>', '', 28153),
(151725, 'zhTW', '<哭泣>', '', 28153),
(151724, 'zhTW', '<哭泣>', '', 28153),
(151723, 'zhTW', '<哭泣>', '', 28153),
(151722, 'zhTW', '<親吻>', '', 28153),
(151721, 'zhTW', '<笑聲>', '', 28153),
(151720, 'zhTW', '<笑>', '', 28153),
(151719, 'zhTW', '<噗噗呸呸呸！>', '', 28153),
(151718, 'zhTW', '<咆哮>', '', 28153),
(151717, 'zhTW', '<吼叫聲>', '', 28153),
(151716, 'zhTW', '<嘆氣>', '', 28153),
(151715, 'zhTW', '<火車聲 - 汽鏘汽鏘嘟嘟！>', '', 28153),
(151714, 'zhTW', '我…很抱歉。', '', 28153),
(151713, 'zhTW', '可憐蟲！面對瑪格哈獸人你沒有勝算！', '', 28153),
(151712, 'zhTW', '非常感謝。', '', 28153),
(151711, 'zhTW', '我感謝你。', '', 28153),
(151710, 'zhTW', '我欠你一份人情。', '', 28153),
(151709, 'zhTW', '我一定會打垮你！', '', 28153),
(151708, 'zhTW', '德拉諾的月亮啊！', '', 28153),
(151707, 'zhTW', '我只是做我該做的。', '', 28153),
(151706, 'zhTW', '下次別再找我幫忙了。', '', 28153),
(151705, 'zhTW', '我很樂意。', '', 28153),
(151704, 'zhTW', '說吧。', '', 28153),
(151703, 'zhTW', '幸會。', '', 28153),
(151702, 'zhTW', 'Lok-tar!', '', 28153),
(151701, 'zhTW', 'Throm-ka!', '', 28153),
(151700, 'zhTW', '不要。', '', 28153),
(151699, 'zhTW', '我說不要！', '', 28153),
(151698, 'zhTW', '絕不！', '', 28153),
(151697, 'zhTW', '的確。', '', 28153),
(151696, 'zhTW', '的確。', '', 28153),
(151695, 'zhTW', '沒錯。', '', 28153),
(151694, 'zhTW', '呼叫苦工', '呼叫苦工', 28153),
(151693, 'zhTW', '我居然讓氏族蒙羞！', '', 28153),
