(151566, 'zhTW', '最重要的是，我們需要高地伐木場的木頭。還有鋼鐵，這可以從賈爾森礦場取得。', '', 28153),
(151565, 'zhTW', '我不能學習那個法術。', '', 28153),
(151564, 'zhTW', '莉雅德倫女士，我不得不說你錯了。聯盟的旗幟會再次飄揚在阿拉希的。', '', 28153),
(151563, 'zhTW', '', '結束這場鬧劇吧，達納斯。這個地方早就不屬於托爾貝恩王室了。', 28153),
(151562, 'zhTW', '我不能拾取那個物品。', '', 28153),
(151561, 'zhTW', '那不是我能拿的。', '', 28153),
(151560, 'zhTW', '我需要靠近一點。', '', 28153),
(151559, 'zhTW', '我可是不怎麼高興，暗影獵手。', '', 28153),
(151558, 'zhTW', '距離太遠了。', '', 28153),
(151557, 'zhTW', '我拿不到。', '', 28153),
(151556, 'zhTW', '達納斯‧托爾貝恩，很高興終於見到你啊…', '', 28153),
(151555, 'zhTW', '我不能交易這件物品。', '', 28153),
(151554, 'zhTW', '我不能使用這個。', '', 28153),
(151553, 'zhTW', '還沒裝備這件物品。', '', 28153),
(151552, 'zhTW', '你錯了，阿拉希是我的。你和你的部落準備交過路費吧，伊崔格。', '', 28153),
(151551, 'zhTW', '需要先裝備這件物品。', '', 28153),
(151550, 'zhTW', '托爾貝恩！你要走現在還來得及，阿拉希現在是部落的。', '', 28153),
(151549, 'zhTW', '我們要先建立好防線才行。去找些鐵和木材。', '', 28153),
(151548, 'zhTW', '擊垮敵人！', '', 28153),
(151547, 'zhTW', '莉雅德倫女士，確實如此。我迫不及待想要消滅部落離經叛道的聖騎士。', '', 28153),
(151546, 'zhTW', '攻擊我的目標！', '', 28153),
(151545, 'zhTW', '去打倒敵人！', '', 28153),
(151544, 'zhTW', '往這裡走。', '', 28153),
(151543, 'zhTW', '跟著獸人就對了。', '', 28153),
(151542, 'zhTW', '', '圖拉揚？這下可有意思了…', 28153),
(151541, 'zhTW', '跟我來。', '', 28153),
(151540, 'zhTW', '為了部落！', '', 28153),
(151539, 'zhTW', '我受傷了！', '', 28153),
(151538, 'zhTW', '快幫我療傷！', '', 28153),
(151537, 'zhTW', '別站在那邊發呆，來幫我啊！', '', 28153),
(151536, 'zhTW', '過來支援我！', '', 28153),
(151535, 'zhTW', '先待在這裡。', '', 28153),
(151534, 'zhTW', '待著別動。', '', 28153),
(151533, 'zhTW', '洛克漢，聖光與我們同在。我們不會屈服於暗影。', '', 28153),
(151532, 'zhTW', '小心暗影，圖拉揚。我和部落要來對付你了…', '', 28153),
(151531, 'zhTW', '為了榮耀而死！', '', 28153),
(151530, 'zhTW', '攻擊！', '', 28153),
(151529, 'zhTW', 'Mok-thora ka!', '', 28153),
(151528, 'zhTW', '粉碎敵人！', '', 28153),
(151527, 'zhTW', '伊崔格，時候到了，我會把你跟部落軍隊從阿拉希的丘陵驅逐。', '', 28153),
(151526, 'zhTW', '突破防線！', '', 28153),
(151525, 'zhTW', '不想死就快撤退！', '', 28153),
(151524, 'zhTW', '我們下次再戰！', '', 28153),
(151523, 'zhTW', '走！快走啊！', '', 28153),
(151522, 'zhTW', '戰場上好像有股聯盟人渣的臭味？看來有場架要打了。', '', 28153),
(151521, 'zhTW', '做好準備！', '', 28153),
(151520, 'zhTW', '記得不時來看一看，我可不想浪費了箱子裡的鋼鐵。', '', 28153),
(151519, 'zhTW', '燒死他們！', '', 28153),
(151518, 'zhTW', '開火！', '', 28153),
(151517, 'zhTW', '敵人很快就來了。我們得把這座基地蓋起來，也就是說，我們需要確保木材和鋼鐵的來源。', '', 28153),
(151516, 'zhTW', '看我把你們都給踢出去，到時候你們部落就只能摀著紅腫的屁股滾蛋了！哈！', '', 28153),
(151515, 'zhTW', '', '滾開，穆拉丁。這個地方是屬於部落的。', 28153),
(151514, 'zhTW', '沒有啦，我只是想找幾個部落雜種，試試新刀的威力而已！', '', 28153),
(151513, 'zhTW', '你在這裡幹嘛，穆拉丁？你想打架嗎？', '', 28153),
(151512, 'zhTW', '那你怎麼不滾回你那貧瘠的鬼地方啊，長滿跳蚤的獸人！', '', 28153),
(151511, 'zhTW', '穆拉丁！你們矮人越界了。滾回你們的山裡去。', '', 28153),
(151510, 'zhTW', '', '聯盟很快就會打到這裡來了，我們動作要快。想辦法保住木頭和鐵礦，我們才有辦法建立據點。', 28153),
(151509, 'zhTW', '', '不要自欺欺人了，老傢伙。我們是來奪回激流堡的。', 28153),
(151508, 'zhTW', '莉雅德倫女士！歡迎來到阿拉希。我想你是來投降的吧？', '', 28153),
(151507, 'zhTW', '', '你已經離開太久了，圖拉揚。這個世界早就變得不一樣了。', 28153),
(151506, 'zhTW', '這是怎麼回事？為什麼帶領部落入侵者的是聖騎士？世界怎麼變成這樣？', '', 28153),
(151505, 'zhTW', '', '穆拉丁，我倒是想看看你能怎樣。這裡現在是部落的地盤了。', 28153),
(151504, 'zhTW', '你最好住手，小姑娘。否則我們聯盟就用迫擊砲把你轟到飽。', '', 28153),
(151503, 'zhTW', '達納斯‧托爾貝恩…我們之間的恩怨，就到戰場上來解決吧…', '', 28153),
(151502, 'zhTW', '你們竟敢入侵阿拉希？還敢找食人妖當指揮官？你們還真是錯得離譜啊。', '', 28153),
(151501, 'zhTW', '「綠皮」是嗎？現在我可被你惹毛了。', '', 28153),
(151500, 'zhTW', '奪回', '奪回', 28153),
(151499, 'zhTW', '<克勞斯噗嗤一笑>\n\n是啊，你大概遇過。我的親戚還真是遍布各地。', '', 28153),
(151498, 'zhTW', '你竟敢入侵激流堡，這裡可是托爾貝恩神聖的家園！滾，別讓我看到你們這些綠皮出現。', '', 28153),
(151497, 'zhTW', '而今天，我們會讓激流堡物歸原主！為了聯盟！', '', 28153),
(151496, 'zhTW', '長久以來，激流堡淪落外來入侵者的手中。', '', 28153),
(151495, 'zhTW', '為了聯盟！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151494, 'zhTW', '聯盟的士兵啊！我們今天會從醜惡的部落手中奪回偉大的激流堡。', '', 28153),
(151493, 'zhTW', '我們今天一定會奪回阿拉希的丘陵…為了聯盟！', '', 28153),
(151492, 'zhTW', '步槍上膛，拔出武器。', '', 28153),
(151491, 'zhTW', '', '阿拉希是我們的了！為了部落！', 28153),
(151490, 'zhTW', '', '先處理手上的任務。第一步是佔領亞格洛克，接下來就是激流堡！', 28153),
(151489, 'zhTW', '晴風？我以前也遇過姓這個的人。', '晴風？我以前也遇過姓這個的人。', 28153),
(151488, 'zhTW', '打包吧，小子！我們把那些武器弄出這裡吧！', '', 28153),
(151487, 'zhTW', '激流堡的要塞升級為城堡了。', '', 28153),
(151486, 'zhTW', '我們蓋好軍械庫了。', '', 28153),
(151485, 'zhTW', '工坊準備好了。', '', 28153),
(151484, 'zhTW', '我們的大廳升級成要塞了。', '', 28153),
(151483, 'zhTW', '諸王祭壇建造完成。', '', 28153),
(151482, 'zhTW', '我們的要塞現在是城堡了！', '', 28153),
(151481, 'zhTW', '軍械庫建造完成。', '', 28153),
(151480, 'zhTW', '工坊準備好建造坦克了。', '', 28153),
(151479, 'zhTW', '我們的大廳升級成要塞了。', '', 28153),
(151478, 'zhTW', '諸王祭壇建造完成。', '', 28153),
(151477, 'zhTW', '好！我們的要塞升級成城堡了！', '', 28153),
(151476, 'zhTW', '軍械庫準備好武裝我們的部隊了！', '', 28153),
(151475, 'zhTW', '工坊可以開工了。來建造坦克吧！', '', 28153),
(151474, 'zhTW', '大廳已經升級成要塞了！', '', 28153),
(151473, 'zhTW', '諸王祭壇準備好了！', '', 28153),
(151472, 'zhTW', '', '我們的城塞已經升級成堡壘了。為了部落！', 28153),
(151471, 'zhTW', '', '有了軍械庫，我們的部隊就有更好的裝備了。', 28153),
(151470, 'zhTW', '', '工坊已經建造完成了。', 28153),
(151469, 'zhTW', '', '我們的基地越來越壯大了。我們的議事廳升級為城塞了！', 28153),
(151468, 'zhTW', '', '風暴祭壇蓋好了。', 28153),
(151467, 'zhTW', '兵營準備好訓練部隊了。', '', 28153),
(151466, 'zhTW', '我們的兵營蓋好了。訓練部隊的時候到了。', '', 28153),
(151465, 'zhTW', '我們有兵營了！開始訓練部隊吧！', '', 28153),
(151464, 'zhTW', '', '我們已經可以在兵營訓練部隊了。', 28153),
(151463, 'zhTW', '城塞升級成堡壘了！', '', 28153),
(151462, 'zhTW', '我們已經把議事廳升級成城塞了。', '', 28153),
(151461, 'zhTW', '風暴祭壇準備好了。', '', 28153),
(151460, 'zhTW', '兵營準備好了。有了蠻兵支援，我們可以打贏這場仗。', '', 28153),
(151459, 'zhTW', '我們的城塞已經升級成堡壘了。', '', 28153),
(151458, 'zhTW', '我們的議事廳升級成城塞了！', '', 28153),
(151457, 'zhTW', '風暴祭壇已經完成了。', '', 28153),
(151456, 'zhTW', '我們有兵營了，快訓練蠻兵！', '', 28153),
(151455, 'zhTW', '', '想都別想。血騎士，打倒他們！', 28153),
(151454, 'zhTW', '我們暗影獵手也不是浪得虛名。刺客們，現身吧！', '', 28153),
(151453, 'zhTW', '我很了解所謂「聯盟的正義」。蠍尾獅騎士，讓他們知道什麼是部落的怒火！', '', 28153),
(151452, 'zhTW', '', '絕不！', 28153),
(151451, 'zhTW', '沒有本來就屬於你的土地，托爾貝恩。食人妖老早就在這裡了。', '', 28153),
(151450, 'zhTW', '哈！那是你自以為的想法。', '', 28153),
(151449, 'zhTW', '', '我受夠你裝模作樣了。血騎士，以聖光之怒消滅他們！', 28153),
(151448, 'zhTW', '就算聖光也救不了你啦，暗影獵手們，現身攻擊！', '', 28153),
(151447, 'zhTW', '蠍尾獅騎士，從空中攻擊！', '', 28153),
(151446, 'zhTW', '', '我們走著瞧，圖拉揚。你還得過我這關呢。', 28153),
(151445, 'zhTW', '我就在這裡等你過來。', '', 28153),
(151444, 'zhTW', '這我可不同意，圖拉揚。', '', 28153),
(151443, 'zhTW', '', '還差得遠呢，矮人。血騎士，備戰！', 28153),
(151442, 'zhTW', '你中計啦，穆拉丁。暗影獵手，開始攻擊！', '', 28153),
(151441, 'zhTW', '就是現在！蠍尾獅騎士攻擊！', '', 28153),
(151440, 'zhTW', '', '絕不。', 28153),
(151439, 'zhTW', '小心一點，穆拉丁！', '', 28153),
(151438, 'zhTW', '你撐不了多久的，矮人。為了部落！', '', 28153),
(151437, 'zhTW', '我曾經失去過這座城市，我不會讓這種事情再次發生，尤其是在你們這種人手上。防衛者，讓他們知道激流堡的實力！', '', 28153),
(151436, 'zhTW', '現在我安全。回去工作。', '', 28153),
(151435, 'zhTW', '聖光與我同在。防衛者，前進！', '', 28153),
(151434, 'zhTW', '莉雅德倫，我會堅守激流堡到最後一刻。防衛者，堅持下去！', '', 28153),
(151433, 'zhTW', '別急著慶祝，血精靈。你還得要解決我。', '', 28153),
(151432, 'zhTW', '哼…正合我意。', '', 28153),
(151431, 'zhTW', '哼！那塊高地根本沒什麼了不起！', '', 28153),
(151430, 'zhTW', '食人妖，我這個老蠢貨還留著一手呢。防衛者，讓他們知道激流堡的力量！', '', 28153),
(151429, 'zhTW', '洛克漢，聖光一定會戰勝暗影。防衛者，繼續前進！', '', 28153),
(151428, 'zhTW', '來啊，洛克漢！我等你好久了。防衛者，讓他們知道我們的厲害！', '', 28153),
(151427, 'zhTW', '閉嘴，食人妖。聯盟可不會輸給你那批骯髒的怪物軍隊。', '', 28153),
(151426, 'zhTW', '聖光仍舊照耀著激流堡。', '', 28153),
(151425, 'zhTW', '小夥子，快了啦。我看看，就先用步槍兵來挫挫你的銳氣吧。', '', 28153),
(151424, 'zhTW', '獸人，激流堡屹立不搖。我會很樂意看見你們的屍體在護城河裡載浮載沉。防衛者，讓他們知道這座城市的實力！', '', 28153),
(151423, 'zhTW', '伊崔格，我親身經歷的勝仗跟敗仗，比你聽過的戰爭故事都還多。這場仗還沒結束。防衛者，前進！', '', 28153),
(151422, 'zhTW', '小夥子，等你拿到再說。防衛者，把他們趕回去！', '', 28153),
(151421, 'zhTW', '嗯，你和你的族人沒什麼不同，你就和其他人一樣跪著等死吧。', '', 28153),
(151420, 'zhTW', '獸人，別急啊。馬上就來了。', '', 28153),
(151419, 'zhTW', '我在下面這裡都聞到你的口臭！放馬過來，獸人！', '', 28153),
(151418, 'zhTW', '聽令，攻城機具，攻破那座城門。我要把血精靈的頭插在矛上！', '', 28153),
(151417, 'zhTW', '聽令，攻城機具，攻破那座城門，把洛克漢抓來給我！托爾貝恩可不是浪得虛名的…', '', 28153),
(151416, 'zhTW', '聽令，攻城機具，攻破那座城門。讓邪惡的獸人知道什麼叫做聯盟的正義！', '', 28153),
(151415, 'zhTW', '高地駐營是我們的了。血精靈，這是你最後的機會。投降的話，我就考慮饒你一命。', '', 28153),
(151414, 'zhTW', '我們拿下了高地駐營，很快就可以攻擊亞格洛克，奪回本來就屬於我們的土地！', '', 28153),
(151413, 'zhTW', '高地駐營是我們的了。我們收拾這些入侵者的進展還不錯。', '', 28153),
(151412, 'zhTW', '控制賈爾森礦場，就有源源不絕的鋼鐵。一定派得上用場。', '', 28153),
(151411, 'zhTW', '太好了，高地伐木場可以提供重建激流堡所需的木材。', '', 28153),
(151410, 'zhTW', '機會來了，攻破城門！讓這些部落的入侵者受到制裁！', '', 28153),
(151409, 'zhTW', '機會來了，攻破城門！聖光會制裁你，洛克漢！', '', 28153),
(151408, 'zhTW', '機會來了，攻破城門！你的末日到了，伊崔格！', '', 28153),
(151407, 'zhTW', '我們佔領高地駐營了。聖光站在聯盟這邊。', '', 28153),
(151406, 'zhTW', '我們拿下高地駐營，接下來就是亞格洛克了。洛克漢，你逃不掉的。', '', 28153),
(151405, 'zhTW', '我們拿下高地駐營之後，很快就能擊敗所有部落軍隊了。', '', 28153),
(151404, 'zhTW', '很好。賈爾森礦場有我們需要的鋼鐵。', '', 28153),
(151403, 'zhTW', '要建造基地，伐木場的木材非常重要。', '', 28153),
(151402, 'zhTW', '動作快！用攻城機具破壞城門！讓那些血精靈知道矮人迫擊砲的威力！', '', 28153),
(151401, 'zhTW', '快點，派出攻城機具突破城門！把這個食人妖老巢燒得一乾二淨！', '', 28153),
(151400, 'zhTW', '快！趕快去！用攻城機具破壞城門！擊潰那些獸人！', '', 28153),
(151399, 'zhTW', '高地駐營是聯盟的！準備好要舉白旗了嗎，小傢伙？', '', 28153),
(151398, 'zhTW', '我們拿下高地駐營了！接下來就要去找你啦，洛克漢。', '', 28153),
(151397, 'zhTW', '呵…從來沒在酒吧付過帳…', '呵…從來沒在酒吧付過帳…', 28153),
(151396, 'zhTW', '高地駐營是我們的！為了聯盟！', '', 28153),
(151395, 'zhTW', '說不定…我們可以談個交易…', '說不定…我們可以談個交易…', 28153),
(151394, 'zhTW', '控制了賈爾森礦場之後，我們就有大量的鋼鐵可用。', '', 28153),
(151393, 'zhTW', '好，我們拿下高地伐木場了。我們可以利用這些木材建造基地。', '', 28153),
(151392, 'zhTW', '', '這場戰鬥需要技巧，偏偏你們最缺的就是技巧！', 28153),
(151391, 'zhTW', '', '把石毀車開過來！轟破他們的大門！把激流堡夷為平地！', 28153),
(151390, 'zhTW', '小心點，朋友！', '小心點，朋友！', 28153),
(151389, 'zhTW', '', '把石毀車開過來！轟破他們的大門！圖拉揚，你的死期到了！', 28153),
(151388, 'zhTW', '你這是什麼意思？', '你這是什麼意思？', 28153),
(151387, 'zhTW', '', '把石毀車開進來！轟破他們的大門！逼那個矮人出來應戰！', 28153),
(151386, 'zhTW', '', '我們拿下高地駐營了！我們部落距離佔領阿拉希又前進了一步！', 28153),
(151385, 'zhTW', '', '我們成功拿下了高地駐營！圖拉揚，部落馬上就會來找你了。', 28153),
(151384, 'zhTW', '', '我們拿下了高地駐營，就等於拿下了高地。目前的情勢開始對我們有利了。', 28153),
(151383, 'zhTW', '', '做得好。要是沒有那些鐵礦，我們早晚會撐不下去。', 28153),
(151382, 'zhTW', '就算犧牲生命，你們也沒辦法成功！讓開！見證奇蹟吧！', '', 28153),
(151381, 'zhTW', '', '我們會好好利用戰斧山脊的木材來建造基地。做得好。', 28153),
(151380, 'zhTW', '派出石毀車！摧毀城門！把那個老蠢貨托爾貝恩的頭帶來給我！', '', 28153),
(151379, 'zhTW', '派出石毀車！在部落的力量之前，就算是聖光也保護不了那個聖騎士！', '', 28153),
(151378, 'zhTW', '派出石毀車！那矮人別想一輩子躲在城門後面！', '', 28153),
(151377, 'zhTW', '高地駐營被部落佔領了，托爾貝恩。', '', 28153),
(151376, 'zhTW', '高地駐營是我們的，圖拉揚。暗影在逼近你…', '', 28153),
(151375, 'zhTW', '穆拉丁…我們拿下高地駐營了。你準備好要出來打一場了嗎？', '', 28153),
(151374, 'zhTW', '枯鬚礦場是屬於部落的。', '', 28153),
(151373, 'zhTW', '', '你們這些沒用的東西，要死要活都快滾開。這些人都交給我吧！', 28153),
(151372, 'zhTW', '很好。我們會用戰斧山脊的木材來建造城塞。', '', 28153),
(151371, 'zhTW', '派出石毀車！攻下城門！讓那個蠢托爾貝恩知道，綠皮的可以做到什麼程度！', '', 28153),
(151370, 'zhTW', '', '泰莉亞，看你長成這麼英勇的人，你父親一定會以你為榮。', 28153),
(151369, 'zhTW', '派出石毀車！攻下城門！這場仗就要結束了！', '', 28153),
(151368, 'zhTW', '派出石毀車！攻下城門！我們會把那個發臭的矮人頭顱串在矛上！', '', 28153),
(151367, 'zhTW', '老大一定會不高興的…', '老大一定會不高興的…', 28153),
(151366, 'zhTW', '高地駐營現在屬於部落了。還是我該說…屬於「綠皮的」。', '', 28153),
(151365, 'zhTW', '我們拿下高地駐營了。圖拉揚，你說過的制裁呢？我還在等呢…', '', 28153),
(151364, 'zhTW', '啊唷…', '啊唷…', 28153),
(151363, 'zhTW', '沒有要…針對誰…', '沒有要…針對誰…', 28153),
(151362, 'zhTW', '我們拿下高地駐營了，穆拉丁！我在上面這裡都看得到你的蒜頭鼻啦！', '', 28153),
(151361, 'zhTW', '我只是…聽命行事…', '我只是…聽命行事…', 28153),
(151360, 'zhTW', '', '泰莉亞…也對，你小時候從大海另一頭來到這裡，原來已經這麼久了？', 28153),
(151359, 'zhTW', '做的好。控制了枯鬚礦場，我們就再也不用擔心鐵礦供應了。', '', 28153),
(151358, 'zhTW', '戰斧山脊是我們的。我們可以利用它的伐木場來協助建造基地。', '', 28153),
(151357, 'zhTW', '不是針對你，但這裡可是有規矩的！', '不是針對你，但這裡可是有規矩的！', 28153),
(151356, 'zhTW', '英勇之喚小徑是我們的了。繼續攻擊！', '', 28153),
(151355, 'zhTW', '', '我叫泰莉亞。', 28153),
(151354, 'zhTW', '幹得好。我們重新佔領了元素之環。', '', 28153),
(151353, 'zhTW', '紐沃農莊再次高舉著聯盟的旗幟。', '', 28153),
(151352, 'zhTW', '', '好。你叫什麼名字？', 28153),
(151351, 'zhTW', '我們拿下英勇之喚小徑了。', '', 28153),
(151350, 'zhTW', '元素之環現在屬於聯盟了。', '', 28153),
(151349, 'zhTW', '做得好，士兵們，紐沃農莊是我們的了。', '', 28153),
(151348, 'zhTW', '給我住手！', '給我住手！', 28153),
(151347, 'zhTW', '', '海軍總帥，我們還是先送你回要塞吧。我們可以在要塞一起查看艾胥凡家族的犯罪證據。', 28153),
(151346, 'zhTW', '很好，把他們趕出英勇之喚小徑了。我們繼續前進！', '', 28153),
(151345, 'zhTW', '我們拿下元素之環了！', '', 28153),
(151344, 'zhTW', '你太超過了！', '你太超過了！', 28153),
(151343, 'zhTW', '我們佔領紐沃農莊啦！', '', 28153),
(151342, 'zhTW', '', '元素之環是我們的。', 28153),
(151341, 'zhTW', '', '我們成功佔領了紐沃農莊。', 28153),
(151340, 'zhTW', '我們對付麻煩人物自有一套！', '我們對付麻煩人物自有一套！', 28153),
(151338, 'zhTW', '', '這樣一來我們就能稍微喘息一下了。', 28153),
(151337, 'zhTW', '嘿！', '嘿！', 28153),
(151336, 'zhTW', '小心暗影，聯盟混蛋。我和部落要來對付你們了…', '', 28153),
(151335, 'zhTW', '打得好。拿下諾斯弗德路口以後，我們就可以專心處理更重要的目標。', '', 28153),
(151333, 'zhTW', '', '喂，就是你！過來，我有話跟你說。', 28153),
(151332, 'zhTW', '我不知道等了多少年，才等到這個復仇的機會，多虧有你母親幫了我一把。', '', 28153),
(151331, 'zhTW', '你的祖先屠殺了我的人民，不過那些人是消滅不了我的。', '', 28153),
(151330, 'zhTW', '', '勾拉圖爾？！這怎麼可能？你不是在很久以前就被我的祖先打敗了嗎！', 28153),
(151329, 'zhTW', '攻城機具，摧毀營地！', '', 28153),
(151328, 'zhTW', '我警告過你了，部落的傢伙，現在準備受死吧。', '', 28153),
(151327, 'zhTW', '這裡是聯盟領地！聖光照耀著激流堡的城牆，你們絕對不會有勝算。', '', 28153),
(151326, 'zhTW', '我在戰場上看到的是部落嗎？我等不及要搶走他們的物資了！', '', 28153),
(151324, 'zhTW', '你必須阻止他們…你可以吸收艾澤萊晶岩，強化艾澤拉斯之心！', '', 28153),
(151323, 'zhTW', '艾澤拉斯的表面傷痕累累…而為了自己利益想收集艾澤萊晶岩的不知道有多少人。', '', 28153),
(151322, 'zhTW', '艾澤拉斯之心是治療這個世界的關鍵…你需要累積更多的力量，才能有成功的機會。', '', 28153),
(151321, 'zhTW', '麥格尼，我準備好讓你強化艾澤拉斯之心了。', '麥格尼，我準備好讓你強化艾澤拉斯之心了。', 28153),
(151320, 'zhTW', '勇士，趕快來希利蘇斯找我。為了拯救我們的世界，還有很多事要做！', '', 28153),
(151319, 'zhTW', '', '我有一隻掃把，而且我不怕去用它！', 28153),
(151318, 'zhTW', '', '退後，你們這些會飛的鼠輩！', 28153),
(151317, 'zhTW', '', '滾出我的凳子！', 28153),
(151316, 'zhTW', '', '滾出去，你們這些髒鳥！', 28153),
(151315, 'zhTW', '付錢，小鬼！', '', 28153),
(151314, 'zhTW', '夢魘的怪獸啊，過來協助我！', '', 28153),
(151313, 'zhTW', '我有一種很好的預感…我們今天一定會找到。', '我有好的預感…我們今天一定會找到。', 28153),
(151312, 'zhTW', '這雙靴子很適合我。', '這雙靴子很適合我。', 28153),
(151311, 'zhTW', '我要砍死你！', '我要砍死你！', 28153),
(151310, 'zhTW', '這裡沒有人可以救你，人渣。', '這裡沒有人可以救你，人渣。', 28153),
(151309, 'zhTW', '小心你的腳下。', '小心你的腳下。', 28153),
(151308, 'zhTW', '你很快就會崩潰了…', '你很快就會崩潰了…', 28153),
(151307, 'zhTW', '你等著…', '你等著…', 28153),
(151306, 'zhTW', '這些資源不是你的！', '這些資源不是你的！', 28153),
(151305, 'zhTW', '哪來的鮮肉！', '哪來的鮮肉！', 28153),
(151304, 'zhTW', '浪潮洶湧！現身吧，我的手下！', '', 28153),
(151303, 'zhTW', '潛伏的恐懼啊，享用他們吧！', '', 28153),
(151302, 'zhTW', '深海的生物啊，回應我吧！', '', 28153),
(151301, 'zhTW', '這裡空氣真好聞，不像我那兒充滿獸人味。', '', 28153),
(151300, 'zhTW', '黑暗會毀滅你！', '', 28153),
(151299, 'zhTW', '我開始不耐煩了。受死吧！', '', 28153),
(151298, 'zhTW', '艾薩拉的手下無窮無盡。還抵抗什麼？', '', 28153),
(151297, 'zhTW', '現在我不太害怕，但石頭害我的手臂很酸。', '', 28153),
(151295, 'zhTW', '他開始聽見低語了。我們的時間不多了。', '', 28153),
(151294, 'zhTW', '', '我會跟上的。不用擔心我！', 28153),
(151293, 'zhTW', '在海底下…等待…呼喚…', '', 28153),
(151292, 'zhTW', '往這邊走，我去拿鐵。', '', 28153),
(151291, 'zhTW', '找找附近的武器架，無信者這裡到處都是武器架。\n\n在你回來之前，我不會惹麻煩。', '找找附近的武器架，無信者這裡到處都是武器架。\n\n在你回來之前，我不會惹麻煩。', 28153),
(151290, 'zhTW', '', '風啊，保護我吧！', 28153),
(151289, 'zhTW', '當我找到武器給你用的時候，我就會回來。', '當我找到武器給你用的時候，我就會回來。', 28153),
(151288, 'zhTW', '', '微風推送我們向前！', 28153),
(151287, 'zhTW', '我要把你轟成碎片！', '', 28153),
(151286, 'zhTW', '我的船固若金湯！', '', 28153),
(151285, 'zhTW', '元素發怒了！', '元素發怒了！', 28153),
(151284, 'zhTW', '竊取世界的凡人都該死。', '竊取世界的凡人都該死。', 28153),
(151283, 'zhTW', '我們會把你搶走的全部奪回來！', '我們會把你搶走的全部奪回來！', 28153),
(151282, 'zhTW', '元素會凌駕一切！', '元素會凌駕一切！', 28153),
(151281, 'zhTW', '你不能從我們手中把這奪走！', '你不能從我們手中把這奪走！', 28153),
(151280, 'zhTW', '這些寶石屬於元素之王！', '這些寶石屬於元素之王！', 28153),
(151279, 'zhTW', '<釋放奴隸，並給他們武器戰鬥。>', '<釋放奴隸，並給他們武器戰鬥。>', 28153),
(151278, 'zhTW', '有了這種力量，我們就能奪回世界！', '有了這種力量，我們就能奪回世界！', 28153),
(151277, 'zhTW', '<釋放奴隸，並給他們武器戰鬥。>', '<釋放奴隸，並給他們武器戰鬥。>', 28153),
(151276, 'zhTW', '只要毀滅你，我的王就會獎勵我。', '只要毀滅你，我的王就會獎勵我。', 28153),
(151275, 'zhTW', '給我一個武器，我就幫你殺十個無信者。', '給我一個武器，我就幫你殺十個無信者。', 28153),
(151274, 'zhTW', '帶上你的東西，你要跟我走。', '帶上你的東西，你要跟我走。', 28153),
(151273, 'zhTW', '斷開這些鎖鏈吧，朋友，狐狸人應該自由自在。', '斷開這些鎖鏈吧，朋友，狐狸人應該自由自在。', 28153),
(151272, 'zhTW', '我想要工作，但不安全。', '', 28153),
(151271, 'zhTW', '放我自由，$pr，我會和你一起殺無信者。', '放我自由，$pr，我會和你一起殺無信者。', 28153),
(151270, 'zhTW', '在無信者做了那些事之後，我絕不對他們留情。', '在無信者做了那些事之後，我絕不對他們留情。', 28153),
(151269, 'zhTW', '我會讓無信者為他們對我做的事付出代價。', '我會讓無信者為他們對我做的事付出代價。', 28153),
(151268, 'zhTW', '妮莎派你來的嗎？不管她的計畫是什麼，算我一個。', '妮莎派你來的嗎？不管她的計畫是什麼，算我一個。', 28153),
(151267, 'zhTW', '給我一個武器，朋友，我就會處理剩下的事。', '給我一個武器，朋友，我就會處理剩下的事。', 28153),
(151266, 'zhTW', '我只需要一個武器。', '我只需要一個武器。', 28153),
(151265, 'zhTW', '不…寶石是我的…你不能…拿走…', '', 28153),
(151264, 'zhTW', '不！蠢貨！', '', 28153),
(151263, 'zhTW', '你…還沒…贏…', '', 28153),
(151262, 'zhTW', '我會回來的！', '', 28153),
(151261, 'zhTW', '我們的時代到了…', '', 28153),
(151260, 'zhTW', '你只能延緩…不可避免…', '', 28153),
(151259, 'zhTW', '混亂…四起…', '', 28153),
(151258, 'zhTW', '誰都阻止不了…元素…', '', 28153),
(151257, 'zhTW', '你們的海洋會沸騰、天空會崩裂、山稜會隆起，而我們將會回歸！', '', 28153),
(151256, 'zhTW', '元素的黎明就在眼前！', '', 28153),
(151255, 'zhTW', '你的大限將至，凡人。', '', 28153),
(151254, 'zhTW', '有了這些寶石，我們最終會摧毀你。', '', 28153),
(151253, 'zhTW', '元素會再次統治一切！', '', 28153),
(151252, 'zhTW', '金色的礦物會給我們力量！', '', 28153),
(151251, 'zhTW', '你的世界會再次被我們奪走！', '', 28153),
(151250, 'zhTW', '你竟敢在我的地盤挑戰我？', '', 28153),
(151249, 'zhTW', '我拿了這麼多東西，還是看看就好了！', '', 28153),
(151248, 'zhTW', '帶我到奧格瑪。', '帶我到奧格瑪。', 28153),
(151247, 'zhTW', '', '$n，很高興見到你。我會暫時待在這裡，以便接近奎格瓦。\n\n我的父母告訴我各式各樣有關青蛙羅亞的故事，我很榮幸能幫助他逃離鮮血食人妖的掌控。', 28153),
(151246, 'zhTW', '這樣應該就行了。謝謝你！', '這樣應該就行了。謝謝你！', 28153),
(151245, 'zhTW', '勇士，幫我把砲彈拿過來！讓我能繼續開砲射擊！', '勇士，幫我把砲彈拿過來！讓我能繼續開砲射擊！', 28153),
(151244, 'zhTW', '', '德哈諾。德喇諾？德拉挪。德拉諾。<嘆氣>。我只是想說，我是從外域來的。', 28153),
(151243, 'zhTW', '', '要說我無污染也可以啦，但我還是喜歡說自己是純天然的獸人。', 28153),
(151242, 'zhTW', '', '我曾經把頭髮染成綠色，但是地獄吼大酋長看了很不高興。', 28153),
(151241, 'zhTW', '', '我不想再聽這些亂七八糟的事情了…啊！讓我痛打一頓就對了！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151240, 'zhTW', '', '破碎之手的人是相當傑出的戰士，不過千萬別叫他們幫你搥背。聽我的話準沒錯…<痛苦的叫聲>', 28153),
(151239, 'zhTW', '', '在艾澤拉斯有一大堆規定，誰可以捅、誰不能捅，誰可以揍、誰不能揍…你們真的不應該這樣綁手綁腳的！', 28153),
(151238, 'zhTW', '', '喂…你不就是那個把要塞丟在霜火峰不管的傢伙嗎？', 28153),
(151237, 'zhTW', '', '你想待多久都沒關係，不過別忘了，打破東西就要賠！', 28153),
(151236, 'zhTW', '', '在進行下一步之前，我要先問清楚…要多用力你才會開始覺得痛？', 28153),
(151235, 'zhTW', '', '我喜歡和你在一起，不代表我不想扁你一頓。', 28153),
(151234, 'zhTW', '', '剛剛好像有個血之谷的薩滿想把我，一直在對我眨眼睛。應該沒錯吧？還是…他只是不習慣剛被挖掉的眼睛…', 28153),
(151233, 'zhTW', '', '上一個對我毛手毛腳的人，已經變成了缺手缺腳的人。', 28153),
(151232, 'zhTW', '', '有個綠皮獸人說要用他的魅力魔死我。我回他說，要是你敢碰我，我就會用釘錘磨死你。', 28153),
(151231, 'zhTW', '', '薩魯法爾單身嗎？感覺他頭髮越白越俏、年紀越老越帥…', 28153),
(151230, 'zhTW', '', '你不需要黑暗之門，就已經闖入我的世界了。', 28153),
(151229, 'zhTW', '', '我…真的很抱歉。', 28153),
(151228, 'zhTW', '', '可笑！你根本不是瑪格哈獸人的對手！', 28153),
(151227, 'zhTW', '想把事情做好的話嘛…', '我果然還是得自己動手...', 28153),
(151226, 'zhTW', '早知道…就申請升遷…', '看來…是我被燒掉了…', 28153),
(151225, 'zhTW', '把錢…跟我埋在一起…', '我最討厭死掉…還有繳稅…', 28153),
(151224, 'zhTW', '好…痛…', '你會…付出代價…', 28153),
(151223, 'zhTW', '根本…不…值得…', '根本…不…值得…', 28153),
(151222, 'zhTW', '我的…危險加給呢…', '一點都…不划算…', 28153),
(151221, 'zhTW', '', '非常感謝。', 28153),
(151220, 'zhTW', '', '我感謝你。', 28153),
(151219, 'zhTW', '大酋長核准使用大範圍火力！燒吧，寶貝！', '大酋長核准使用大範圍火力！燒吧，寶貝！', 28153),
(151218, 'zhTW', '核准使用大範圍火力！快燒吧，寶貝！', '你的人頭很值錢…我要發財了！', 28153),
(151217, 'zhTW', '', '我欠你一份人情。', 28153),
(151216, 'zhTW', '', '你會在我面前倒下！', 28153),
(151215, 'zhTW', '你別想…阻止她…', '你不可能…阻止她…', 28153),
(151214, 'zhTW', '你是不是搞不清楚狀況啊，朋友。', '你犯下大錯了！', 28153),
(151213, 'zhTW', '', '德拉諾的月亮啊！', 28153),
(151212, 'zhTW', '這一定很有趣！', '寶貝，我最喜歡放火燒東西！', 28153),
(151211, 'zhTW', '為了部落…和利潤！', '為了部落！', 28153),
(151210, 'zhTW', '', '我只是盡自己的責任。', 28153),
(151209, 'zhTW', '', '不要再叫我做那種事了。', 28153),
(151208, 'zhTW', '', '我很樂意。', 28153),
(151207, 'zhTW', '', '不要。', 28153),
(151206, 'zhTW', '', '我說不行！', 28153),
(151205, 'zhTW', '', '絕不！', 28153),
(151204, 'zhTW', '', '的確。', 28153),
(151203, 'zhTW', '', '的確。', 28153),
(151202, 'zhTW', '', '沒錯。', 28153),
(151201, 'zhTW', '', '我讓整個氏族蒙羞了！', 28153),
(151200, 'zhTW', '', '我要恢復一下法力。', 28153),
(151199, 'zhTW', '', '需要法力！', 28153),
(151198, 'zhTW', '', '死得壯烈。', 28153),
