(151189, 'zhTW', '', '可憐我這個獸人吧！', 28153),
(151188, 'zhTW', '', '對苦工仁慈一點！', 28153),
(151187, 'zhTW', '', '做得漂亮。', 28153),
(151186, 'zhTW', '', '我覺得算不錯了。', 28153),
(151185, 'zhTW', '', '嗯哼，恭喜你啊。', 28153),
(151184, 'zhTW', '走吧，小氣鬼，這些防禦工事可不是免費的！', '', 28153),
(151183, 'zhTW', '', '擊垮敵人！', 28153),
(151182, 'zhTW', '', '攻擊我的目標！', 28153),
