(151170, 'zhTW', '', '走！快走啊！', 28153),
(151169, 'zhTW', '', '往這裡走。', 28153),
(151168, 'zhTW', '', '跟著獸人就對了。', 28153),
(151167, 'zhTW', '同志們…代替我繼續進行…', '同志們…代替我繼續進行…', 28153),
(151166, 'zhTW', '我終於可以安息了。', '我終於可以安息了。', 28153),
(151165, 'zhTW', '', '跟我來。', 28153),
(151164, 'zhTW', '靈魂…指引我。', '靈魂…指引我。', 28153),
(151163, 'zhTW', '別插手，否則小命不保。', '別插手，否則小命不保。', 28153),
(151162, 'zhTW', '我們會適時治療和攻擊。', '我們會適時治療和攻擊。', 28153),
(151161, 'zhTW', '', '為了部落！', 28153),
(151160, 'zhTW', '部落的人，過來我身邊！我會治療你們的傷口！', '部落的人，過來我身邊！我會治療你們的傷口！', 28153),
