(151091, 'zhTW', '', '我不能交易這件物品。', 28153),
(151090, 'zhTW', '', '我不能使用這個。', 28153),
(151089, 'zhTW', '', '還沒裝備這件物品。', 28153),
(151088, 'zhTW', '', '需要先裝備這件物品。', 28153),
(151087, 'zhTW', '', '我現在不能拾取物品。', 28153),
(151086, 'zhTW', '', '我沒有目標。', 28153),
(151085, 'zhTW', '', '我要先找到目標。', 28153),
(151084, 'zhTW', '', '我需要目標。', 28153),
(151083, 'zhTW', '', '我不能這麼做。', 28153),
(151082, 'zhTW', '', '我的權限不足。', 28153),
(151081, 'zhTW', '', '我不能攻擊那個目標。', 28153),
(151080, 'zhTW', '', '我不能攻擊它。', 28153),
(151079, 'zhTW', '', '我的背包已經滿了。', 28153),
(151078, 'zhTW', '', '我帶不動了。', 28153),
(151077, 'zhTW', '', '它鎖住了。', 28153),
(151076, 'zhTW', '', '這類物品太多了。', 28153),
(151075, 'zhTW', '', '我還不能使用這個物品。', 28153),
(151074, 'zhTW', '', '我還沒準備好。', 28153),
(151073, 'zhTW', '', '還要再等一下才行。', 28153),
(151072, 'zhTW', '', '魔怒不足。', 28153),
(151071, 'zhTW', '', '我的魔怒不足。', 28153),
(151070, 'zhTW', '', '魔痛不足。', 28153),
(151069, 'zhTW', '', '我的魔痛不夠。', 28153),
(151068, 'zhTW', '', '那不是背包。', 28153),
(151067, 'zhTW', '', '我錢不夠。', 28153),
(151066, 'zhTW', '', '那個我買不起。', 28153),
(151065, 'zhTW', '', '太貴了。', 28153),
(151064, 'zhTW', '', '他不能加入隊伍。', 28153),
(151063, 'zhTW', '', '我彈藥用完了。', 28153),
(151062, 'zhTW', '', '能量不足。', 28153),
(151061, 'zhTW', '', '我缺乏足夠的能量。', 28153),
(151060, 'zhTW', '', '我需要先有法力。', 28153),
(151059, 'zhTW', '', '法力不夠了。', 28153),
(151058, 'zhTW', '', '我需要法力。', 28153),
(151057, 'zhTW', '', '怒氣不足。', 28153),
(151056, 'zhTW', '', '我需要更多怒氣。', 28153),
(151055, 'zhTW', '', '太遠了。', 28153),
(151054, 'zhTW', '', '我離得太遠了。', 28153),
(151053, 'zhTW', '', '我得靠近一點。', 28153),
(151052, 'zhTW', '', '我們不能再邀請別人了。', 28153),
(151051, 'zhTW', '', '我暫時不能再喝了。', 28153),
(151050, 'zhTW', '', '我還沒學會那個技能。', 28153),
(151049, 'zhTW', '', '這個我還不能用。', 28153),
(151047, 'zhTW', '', '那個法術還沒準備好。', 28153),
(151046, 'zhTW', '', '還不能施放這個法術。', 28153),
(151045, 'zhTW', '', '還要再等一下。', 28153),
(151044, 'zhTW', '我必須…讓我解決他們！', '', 28153),
(151043, 'zhTW', '我看見的…不是這樣…', '來的…太突然了…', 28153),
(151042, 'zhTW', '把那不付帳的人攆出去，大夥兒！', '', 28153),
(151041, 'zhTW', '拜託，各位，我會還債的！', '', 28153),
(151040, 'zhTW', '我們進去之前，需要再研究一下，找出這些食人妖想做什麼，還有要怎麼阻止他們。', '', 28153),
(151039, 'zhTW', '當然，直覺告訴我在神廟深處還有更多危險。', '', 28153),
(151038, 'zhTW', '幹得好，解決那個怪物了。', '', 28153),
(151037, 'zhTW', '當然，被這些東西吸引過來不是只有我們。', '', 28153),
(151036, 'zhTW', '好，就是這裡。連我的骨頭都感覺到這些聖物的力量了。', '', 28153),
(151034, 'zhTW', '', '嘿，就是你！我朋友把我留在這裡等死，可以幫個忙嗎？', 28153),
(151031, 'zhTW', '', '嗯…真有趣…', 28153),
(151030, 'zhTW', '學著製作你自己的餐點！決不要信任一個瘦廚師！', '', 28153),
(151029, 'zhTW', '羅亞…呼喚我…', '算你…好運…', 28153),
(151028, 'zhTW', '部落…萬歲…', '部落…會贏…', 28153),
(151027, 'zhTW', '伯昂撒姆第，我來了…', '伯昂撒姆第，我來了…', 28153),
(151026, 'zhTW', '一群蠢貨！居然會死在神廟被破壞、沒有追隨者的羅亞手上？殺了他！', '', 28153),
(151025, 'zhTW', '伯昂撒姆第…我來了…', '我看到…彼界了…', 28153),
(151024, 'zhTW', '壞魂能會找上你！', '壞魂能要來找你了！', 28153),
(151023, 'zhTW', '噢對，是大酋長的命令。不留活口。', '噢對，是大酋長的命令。不留活口。', 28153),
(151022, 'zhTW', '別想逃！', '你躲不掉的，老兄！', 28153),
(151021, 'zhTW', '快看看這裡有什麼？是弱小的人類，正好可以殺掉！', '快看看這裡有什麼？是弱小的人類，正好可以殺掉！', 28153),
(151020, 'zhTW', '瑞茲當克說你不屬於這裡，小傢伙。', '', 28153),
(151019, 'zhTW', '瑞茲當克向你問好。', '', 28153),
(151018, 'zhTW', '啊！拜託，我好餓！', '', 28153),
(151017, 'zhTW', '我的兄弟和姊妹曾經照料這片土地，和樹木為伍。那些日子已經遠去。\n\n我們有一些人還沒忘記那樣的使命。\n\n梣木林地是我們其中一個庇護所。這地方讓我們能暫時擺脫侵蝕緋紅森林的腐化力量。\n\n有了長在它陰影中的力量干擾，看來它的年華也已經老去。現在我看著它衰弱，只能追憶它曾滋養的生命。', '', 28153),
(151016, 'zhTW', '羅亞引導我的攻擊！', '讓你去見伯昂撒姆第！', 28153),
(151015, 'zhTW', '為了部落！', '為了部落！', 28153),
(151014, 'zhTW', '林地是不是有什麼不對勁？', '林地是不是有什麼不對勁？', 28153),
(151013, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t古翰召喚|cFFFF0404|Hspell:267509|h[千喉奴僕]|h|r來助陣！', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t古翰召喚|cFFFF0404|Hspell:267509|h[千喉奴僕]|h|r來助陣！', 28153),
(151011, 'zhTW', '', '我還需要一些時間才能讓力量完全恢復，不過阻止我回歸的詛咒已經消失了。', 28153),
(151010, 'zhTW', '', '英雄，感謝你們。', 28153),
(151009, 'zhTW', '等等，那些入侵者是誰？他們在褻瀆瑟沙利斯！', '', 28153),
(151008, 'zhTW', '派我去戰場。', '派我去戰場。', 28153),
(151007, 'zhTW', '她的聖所應該就在前面。', '', 28153),
(151006, 'zhTW', '如果不是她的話，這個世界早就陷入一片混亂。', '', 28153),
(151005, 'zhTW', '瑟沙利斯犧牲自己來阻止謎思拉克斯的時候，我就在現場。', '', 28153),
(151003, 'zhTW', '我從這裡就能聽到緋紅森林的樹根渴求鮮血的呼喊。我沒想到他們的腐化會蔓延這麼遠。', '', 28153),
(151002, 'zhTW', '你非要停下來撿乾淨屍體才肯走嗎？瑟沙利斯才是我們的目標！', '', 28153),
(151001, 'zhTW', '看來，你的確抓到了消滅敵人的訣竅。', '', 28153),
(151000, 'zhTW', '不過時間急迫，我感覺到有股黑暗正在滋生，控制著這座神廟。', '', 28153),
(150999, 'zhTW', '你消滅了感染，我要向你致上謝意。', '', 28153),
(150998, 'zhTW', '她犧牲自己，阻止謎思拉克斯…不過隨著她的死去，沃魯敦的叢林也化為一片沙漠。', '', 28153),
(150997, 'zhTW', '這座神廟是瑟沙利斯的休憩之地，她是強大的羅亞，在很久以前保護我的同胞免於滅絕。', '', 28153),
(150996, 'zhTW', '', '好啊！痛擊他們！', 28153),
(150995, 'zhTW', '', '我壓大傢伙十塊金幣！', 28153),
(150993, 'zhTW', '她該復甦的時間已經過去了，我很擔心是不是有什麼東西阻止她重返人間。', '', 28153),
(150990, 'zhTW', '你即將離開指定區域，並將會從載具中移除。', '你即將離開指定區域，並將會從載具中移除。', 28153),
(150989, 'zhTW', '暫時休息一下，希望時間夠我們重新整隊、恢復精力。', '', 28153),
(150988, 'zhTW', '快！我們的水手需要幫忙！他們都受傷了，部落的人正在逼近！', '', 28153),
(150987, 'zhTW', '願浪潮善待你。', '', 28153),
(150986, 'zhTW', '新鮮的捲心菜！', '', 28153),
(150985, 'zhTW', '一帆風順。', '', 28153),
(150984, 'zhTW', '順風，朋友。', '', 28153),
(150983, 'zhTW', '噢，你好啊。', '', 28153),
(150982, 'zhTW', '有什麼事嗎？', '', 28153),
(150981, 'zhTW', '幸會。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150980, 'zhTW', '猛擊的時間到了！', '', 28153),
(150979, 'zhTW', '為了部落！', '為了部落！', 28153),
(150978, 'zhTW', '誰都無法阻止部落！', '誰都無法阻止部落！', 28153),
(150977, 'zhTW', '我們是長矛之尖…', '我們是長矛之尖…', 28153),
(150976, 'zhTW', '', 'Ugalazul bwrxil\' qu rax。', 28153),
(150975, 'zhTW', '被你們這些傢伙…擊敗了？', '被你們這些傢伙…擊敗了？', 28153),
(150974, 'zhTW', '部落…必勝…', '這片土地…是我們的…', 28153),
(150973, 'zhTW', '我們是…銳利的長矛…', '我為…榮耀而死…', 28153),
(150972, 'zhTW', '沒有人能…阻止我們…', '沒用的…雜碎…', 28153),
(150971, 'zhTW', '', '深淵終將…籠罩這片土地！', 28153),
(150970, 'zhTW', '', '不…我讓她失望了！', 28153),
(150969, 'zhTW', '', '對你們一族的詛咒！', 28153),
(150968, 'zhTW', '', '水…操控了我！', 28153),
(150967, 'zhTW', '', '為女王…獻上生命！', 28153),
(150966, 'zhTW', '', '自深淵…而生…', 28153),
(150965, 'zhTW', '', '我們的女王絕不會輸…', 28153),
(150964, 'zhTW', '噢！我現在就回去！請不要上報我！', '噢！我現在就回去！請不要上報我！', 28153),
(150963, 'zhTW', '你會是個可敬的對手。', '你會是個可敬的對手。', 28153),
(150962, 'zhTW', '別亂打探別人的事！', '別亂打探別人的事！', 28153),
(150961, 'zhTW', '深淵終將…籠罩這片土地！', '', 28153),
(150960, 'zhTW', '不…我讓她失望了！', '', 28153),
(150959, 'zhTW', '對你們一族的詛咒！', '', 28153),
(150958, 'zhTW', '水…操控了我！', '', 28153),
(150957, 'zhTW', '為女王…獻上生命！', '', 28153),
(150956, 'zhTW', '你絕對…阻止不了她…', '', 28153),
(150955, 'zhTW', '自深淵…而生…', '', 28153),
(150954, 'zhTW', '我們的女王絕不會輸…', '', 28153),
(150953, 'zhTW', '', '阻止敵人在這裡獲得立足點，才能保衛我們家園的安全。願剛克獎勵你英勇作戰的決心。', 28153),
(150952, 'zhTW', '', '讓聯盟在贊達拉獲得立足點，絕對會是災難。盡可能地回收物資，絕對不能手下留情。', 28153),
(150951, 'zhTW', '做事還是要自己動手才行...', '', 28153),
(150950, 'zhTW', '你的死亡就是我的榮耀！', '你的死期到了！', 28153),
(150949, 'zhTW', '殺光他們！', 'Lok\'tar！', 28153),
(150948, 'zhTW', '你會是個可敬的對手！', '不留活口！', 28153),
(150947, 'zhTW', '為了…部落…', '為了…部落…', 28153),
(150946, 'zhTW', '啊，她真漂亮！你今天可以領錢下班了。', '', 28153),
(150945, 'zhTW', '', '你們竟敢干涉我的計畫？就憑你們也想抗拒我的意志？', 28153),
(150944, 'zhTW', '做好準備。我們要跟怪物來場硬仗！', '', 28153),
(150943, 'zhTW', '它把我們引到它的巢穴！', '', 28153),
(150942, 'zhTW', '嗯…線索指向這條惡臭的通道。', '', 28153),
(150941, 'zhTW', '珍珠不在這裡。看來艾薩拉的手下不像外表看起來那樣笨。', '', 28153),
(150940, 'zhTW', '你的頭很快就會掛在我的牆上！', '', 28153),
(150939, 'zhTW', '向女王祈禱吧，你就要死在這裡了。', '', 28153),
(150938, 'zhTW', '是入侵者？我會把你們丟往黑暗深淵，大海會讓你們粉身碎骨，直到永遠。', '', 28153),
(150937, 'zhTW', '羅亞太強了！快退回安全的海裡！我們輸了！', '', 28153),
(150936, 'zhTW', '摧毀這座神廟！破壞所有石塊！推倒所有雕像！在女王之前，所有人都得屈服！', '', 28153),
(150935, 'zhTW', '不管你用的是什麼黑暗力量，下一個死的就是你！', '', 28153),
(150934, 'zhTW', '歡迎啊，入侵者。你的時機正好，來見證真正的力量吧！', '', 28153),
(150933, 'zhTW', '打得真不錯…不過真正的獵物已經撤退到祭壇裡面去了。', '', 28153),
(150932, 'zhTW', '', '女王已經下令取你的命！', 28153),
(150931, 'zhTW', '', '榮耀艾薩拉！', 28153),
(150930, 'zhTW', '', '我們的命運將定！', 28153),
(150929, 'zhTW', '', '我會享受殺死你的榮耀！', 28153),
(150928, 'zhTW', '', '沒人能反抗艾薩拉女王！', 28153),
(150927, 'zhTW', '', '潮汐之戒是我們的！', 28153),
(150926, 'zhTW', '', '你不可能理解我們的力量！', 28153),
(150925, 'zhTW', '噓，你沒穿鞋子。', '', 28153),
(150924, 'zhTW', '', '如果只有一個人呢？我可以用一些新鞋。', 28153),
(150923, 'zhTW', '有點耐心，小妹妹！', '', 28153),
(150922, 'zhTW', '', '他們永遠不會注意到，沒人說要衝進營地，但解決一些人無傷大雅！', 28153),
(150921, 'zhTW', '女王已經下令要你的命！', '', 28153),
(150920, 'zhTW', '榮耀歸於艾薩拉！', '', 28153),
(150919, 'zhTW', '我們的命運將定！', '', 28153),
(150918, 'zhTW', '我會享受殺死你的榮耀！', '', 28153),
(150917, 'zhTW', '沒人能反抗艾薩拉女王！', '', 28153),
(150916, 'zhTW', '潮汐之戒是我們的！', '', 28153),
(150914, 'zhTW', '我們必須待在這裡。要是你跑走，害我們被殺，就沒人可以回報狀況了。', '', 28153),
(150913, 'zhTW', '你根本無法理解我們的力量！', '', 28153),
(150912, 'zhTW', '我的捲心菜啊！', '', 28153),
(150911, 'zhTW', '該抓獅鷲獸了。上坐騎吧！', '', 28153),
(150908, 'zhTW', '粗脖幫的工作不一定光鮮亮麗，但一定有錢拿。', '', 28153),
(150907, 'zhTW', '我們接到獅鷲獸鞍的大訂單，所以需要更多毛皮。快去工作！', '', 28153),
(150906, 'zhTW', '山上的雪怪越少，下山的雪怪也會減少。你幹得不錯！', '', 28153),
(150905, 'zhTW', '冰川上雪怪的數量越來越多了。你去幫忙解決這個問題！', '', 28153),
(150904, 'zhTW', '有了浪潮珍珠的力量，我們的艦隊會勢不可擋。', '', 28153),
(150903, 'zhTW', '', '你是不是以為這些都不用錢啊！', 28153),
(150902, 'zhTW', '我的錯，大人…', '', 28153),
(150901, 'zhTW', '', '你這個笨手笨腳的東西！那些東西很貴！', 28153),
(150900, 'zhTW', '英雄，謝謝。你們給庫爾提拉斯帶來希望。', '', 28153),
(150899, 'zhTW', '我能感受到那個黑暗的力量已經開始消退。這個聖壇會恢復原狀。', '', 28153),
(150898, 'zhTW', '別去聽那個聲音！這可怕的東西會扭曲你們的靈魂！', '', 28153),
(150897, 'zhTW', '以潮母之名！', '', 28153),
(150896, 'zhTW', '各位英雄，小心了。某種看不見的邪惡力量仍然潛伏在這裡。我們必須想辦法從聖壇上面移除它。', '', 28153),
(150895, 'zhTW', '奇怪，黑暗的力量沒有消失。', '', 28153),
(150894, 'zhTW', '大人，你已經變成海潮的敵人，所以海潮把你吞沒了。', '', 28153),
(150893, 'zhTW', '那我就把你們的身軀丟往最黑暗的深淵，大海會讓你們粉身碎骨，直到永遠。', '', 28153),
(150892, 'zhTW', '休想。', '', 28153),
(150891, 'zhTW', '快決定。順我者生，逆我者亡。', '', 28153),
(150890, 'zhTW', '蠢貨！我們必須回到海中，艾薩拉女王會給我們力量，讓我們回去！', '', 28153),
(150889, 'zhTW', '大人！快住手！別把庫爾提拉斯的艦隊送入黑暗之中！', '', 28153),
(150888, 'zhTW', '', '斯陀頌恩領主，你好像有訪客呢。', 28153),
(150887, 'zhTW', '', '只要表示尊敬，聽他講話就好…運氣好他就不會把你從金字塔頂扔下去。', 28153),
(150886, 'zhTW', '女王，庫爾提拉斯艦隊馬上就屬於你了。', '', 28153),
(150885, 'zhTW', '海歸海，塵歸塵，潮水歸潮水。願你的靈魂找到平順的海流。', '', 28153),
(150884, 'zhTW', '各位英雄，快阻止他們，不然艦隊就完蛋了！', '', 28153),
(150883, 'zhTW', '泰坦圓盤已啟動：正在啟動腐化程序', '泰坦圓盤已啟動：正在啟動腐化程序', 28153),
(150882, 'zhTW', '泰坦圓盤已啟動：正在啟動欺敵程序', '泰坦圓盤已啟動：正在啟動欺敵程序', 28153),
(150881, 'zhTW', '', '只要儀式完成，庫爾提拉斯的艦隊就會屬於艾薩拉女王！', 28153),
(150880, 'zhTW', '歡迎啊，派克修士。你來的時機正好，來見證我們的勝利吧！', '', 28153),
(150879, 'zhTW', '斯陀頌恩破壞了這個聖地。我們必須努力從他手中挽救這個地方。', '', 28153),
(150878, 'zhTW', '聲音？', '聲音？', 28153),
(150877, 'zhTW', '小心，仍有某種黑暗在窺探我們，伺機而動。', '', 28153),
(150876, 'zhTW', '必須為這座聖壇，淨化斯陀頌恩領主的邪惡力量。', '', 28153),
(150875, 'zhTW', '', '主人！不要遺棄我！不要！', 28153),
(150874, 'zhTW', '', '你以為自己有辦法對抗古翰？嚐嚐自不量力的苦果吧！', 28153),
(150873, 'zhTW', '泥巴裡面有聲音！', '泥巴裡面有聲音！', 28153),
(150872, 'zhTW', '', '我們毀了。\n\n瑞贊的聖光已經離我們而去，只有追隨偉大帝王羅亞的幾個人還有一些力量，就連他們也不可信。\n\n我們一生奉獻，但現在我們會變成什麼樣的人？', 28153),
(150871, 'zhTW', '該升級了！', '', 28153),
(150870, 'zhTW', '好了，我不想再公平戰鬥了。', '', 28153),
(150869, 'zhTW', '太棒了！士兵們會好好利用這批補給品。你做得很好！', '', 28153),
(150868, 'zhTW', '斥候回報，有艘贊達拉貨船落入鮮血食人妖劫掠者手中。殺光他們，搶下那些補給品。', '', 28153),
(150867, 'zhTW', '注意了，各位，看來有推銷員來了！', '', 28153),
(150866, 'zhTW', '耶！去給你自己找個造型師吧！', '', 28153),
(150865, 'zhTW', '', '$n！喔，$n！我們有個任務給你！', 28153),
(150864, 'zhTW', '跳！', '跳！', 28153),
(150863, 'zhTW', '小傢伙，在伯昂撒姆第面前，就算潛行加消失也沒用。', '', 28153),
(150862, 'zhTW', '你身上好像有種…啊對了，是惡魔獵人的味道。', '', 28153),
(150861, 'zhTW', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a你的指揮官正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a你的指揮官正遭受攻擊！', 28153),
(150860, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a英勇之喚小徑正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a英勇之喚小徑正遭受攻擊！', 28153),
(150859, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a紐沃農莊正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a紐沃農莊正遭受攻擊！', 28153),
(150858, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a元素之環正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a元素之環正遭受攻擊！', 28153),
(150857, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a高地駐營正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a高地駐營正遭受攻擊！', 28153),
(150856, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a諾斯弗德路口正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a諾斯弗德路口正遭受攻擊！', 28153),
(150855, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a枯鬚礦場遭受攻擊！', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a枯鬚礦場遭受攻擊！', 28153),
(150854, 'zhTW', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a戰斧山脊正遭受攻擊！', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a戰斧山脊正遭受攻擊！', 28153),
(150853, 'zhTW', '我們必須找到先遣斥候，先清掉空中那群討厭的蟲子！', '我們必須找到先遣斥候，先清掉空中那群討厭的蟲子！', 28153),
(150852, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a英勇之喚小徑失守！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a英勇之喚小徑失守！', 28153),
(150851, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a紐沃農莊失守！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a紐沃農莊失守！', 28153),
(150850, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a元素之環失守！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a元素之環失守！', 28153),
(150849, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a高地駐營失守！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a高地駐營失守！', 28153),
(150848, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a諾斯弗德路口失守！', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a諾斯弗德路口失守！', 28153),
(150847, 'zhTW', '你可不是在什麼夢境裡面。', '', 28153),
(150846, 'zhTW', '喔，這下子真的眾靈與你同在了。', '', 28153),
(150845, 'zhTW', '啊，你是死亡騎士啊？你該看看「我」這扇死亡之門！', '', 28153),
(150844, 'zhTW', '下一個陷落的就是你的家園！', '下一個陷落的就是你的家園！', 28153),
(150843, 'zhTW', '你沒辦法阻止沙塵擴散！', '你沒辦法阻止沙塵擴散！', 28153),
(150842, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a枯鬚礦場失守！', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a枯鬚礦場失守！', 28153),
(150841, 'zhTW', '哈！迅空翻也翻不出我手掌心。', '', 28153),
(150840, 'zhTW', '我們會支配一切！', '我們會支配一切！', 28153),
(150839, 'zhTW', '我們會解決你，就像捏死蟲子一樣！', '我們會解決你，就像捏死蟲子一樣！', 28153),
(150838, 'zhTW', '老兄，這次假死變真死了？唉呀…', '', 28153),
(150837, 'zhTW', '為了皇帝！', '為了皇帝！', 28153),
(150836, 'zhTW', '老兄，我看你跟錯光芒走錯路了。', '', 28153),
(150835, 'zhTW', '這次閃現沒辦法死裡逃生了，對吧？', '', 28153),
(150834, 'zhTW', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a戰斧山脊失守！', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a戰斧山脊失守！', 28153),
(150833, 'zhTW', '太棒了！我是說，他們看來糟透了，但的確不一樣！', '', 28153),
(150832, 'zhTW', '', '嗯，那名冒險者的確看來不一樣。', 28153),
(150831, 'zhTW', '我想又是那些所謂「英雄們」的其中一個。聞起來像是有人站在火中！', '', 28153),
(150830, 'zhTW', '', '那到底是什麼味道？', 28153),
(150829, 'zhTW', '', '華爾多夫，那不是野豬人，只是另外一個「英雄」！', 28153),
(150828, 'zhTW', '嘿嘿嘿，全身重鎧還是照死不誤啊？', '', 28153),
(150827, 'zhTW', '喂，史泰勒，把我的劍給我！有一個野豬人朝這邊來了！', '', 28153),
(150826, 'zhTW', '噢，你把閃亮亮的靈魂石搞丟了，嗯？', '', 28153),
(150825, 'zhTW', '', '你說的沒錯！看起來的確很糟！', 28153),
(150824, 'zhTW', '你有看到$n身上的那套嗎？並沒有看起來那麼糟吧！', '', 28153),
(150823, 'zhTW', '啊，你想花點時間陪陪伯昂撒姆第嗎？', '', 28153),
(150822, 'zhTW', '哈哈！這還真是特別的死法！', '', 28153),
(150821, 'zhTW', '我會說他們這麼一穿看起來更糟了…不過我想他們總是看起來這麼糟！', '', 28153),
(150820, 'zhTW', '', '好啊，好啊，好啊，看看尖角蜥拖進來什麼東西！是$n！', 28153),
(150819, 'zhTW', '', '這鬼玩意是從哪裡拿到的？穴居怪身上嗎？！', 28153),
(150818, 'zhTW', '嘿，史泰勒，你看看$n的裝備！', '', 28153),
(150817, 'zhTW', '我想是的！小子，他們聞起來比我想像的還臭！哈！', '', 28153),
(150816, 'zhTW', '', '喂，華爾多夫！是「大名鼎鼎的」$r跟珍娜一起現身了嗎？', 28153),
(150815, 'zhTW', '', '是的！你很臭！哈哈哈！', 28153),
(150814, 'zhTW', '喂，你！對，就是你，有張怪臉的$r！', '', 28153),
(150813, 'zhTW', '我看過有更好塑形的馬匹！', '', 28153),
(150812, 'zhTW', '', '喂！$n！你覺得那頂頭盔配那雙靴子嗎？', 28153),
(150811, 'zhTW', '我真希望我知道別的事情。', '我真希望我知道別的事情。', 28153),
(150810, 'zhTW', '', '遠古的佐司特。他們對庫爾提拉斯人的仇恨在死後依然存在。那股對我們的憎惡仍縈繞不去。\n\n我同情那些他們招回來的傻瓜。', 28153),
(150809, 'zhTW', '復仇心切的鬼魂？', '復仇心切的鬼魂？', 28153),
(150808, 'zhTW', '你會被消滅！', '', 28153),
(150807, 'zhTW', '', '這些女巫使用的魔法既古老又腐敗。她們扭曲了生靈，用牠們來服侍她們，打亂了平衡。她們製作的邪惡玩意裡頭都有亟欲復仇的死者靈魂。', 28153),
(150806, 'zhTW', '', '狩獵使人快樂，復仇讓人滿足！', 28153),
(150805, 'zhTW', '', '這些會殺羅亞的叛徒竟然還想褻瀆瑞贊神廟。年邁的克茲洛提克會教訓他們，讓他們知道對帝王羅亞不敬會有什麼下場。', 28153),
(150804, 'zhTW', 'Naza bul rexil qalic ul\'。', '', 28153),
(150803, 'zhTW', '森林發生了什麼事？', '森林發生了什麼事？', 28153),
(150802, 'zhTW', 'Ca\' lish！', '', 28153),
(150801, 'zhTW', '', '你可以在附近的洞穴裡找到他。祝你好運，$n。', 28153),
(150800, 'zhTW', '', '綠野巡者雖然暫時變弱了，他還是會重新開始狩獵的。', 28153),
(150799, 'zhTW', 'Ug\' bwafa qilikx za！', '', 28153),
(150798, 'zhTW', '神廟的大門永遠為你敞開。', '', 28153),
(150797, 'zhTW', '喔，可憐的小東西，需要老伯昂撒姆第幫你一把嗎？', '', 28153),
(150796, 'zhTW', '拉尼舒的毒性，讓我的孩子十分虛弱，已經奄奄一息了。你救了我，請你使用我的力量來救他們。', '', 28153),
(150795, 'zhTW', 'Hul bala miz rilakich…', '', 28153),
(150794, 'zhTW', '嗯嗯嗯，我可沒料到，這麼快就在這裡看到你。', '', 28153),
(150793, 'zhTW', 'Lok\'tar ogar!', 'Lok\'tar ogar!', 28153),
(150792, 'zhTW', '為了部落！', '為了部落！', 28153),
(150791, 'zhTW', '我比你優秀！', '', 28153),
(150790, 'zhTW', '部落的士兵，舉起你的武器！今天，我們要向卡多雷進軍！', '', 28153),
(150789, 'zhTW', '我來猜猜看…你挑錯對手了嗎？', '', 28153),
(150788, 'zhTW', 'Il qul zerakish！', '', 28153),
(150787, 'zhTW', '你應該已經被修好了。前往奧格瑪去找希瓦娜斯，開始你的史詩級惡作劇。', '', 28153),
(150786, 'zhTW', '我開始了納茲米爾，但無法展開祖達薩，請修理我。', '我開始了納茲米爾，但無法展開祖達薩，請修理我。', 28153),
(150785, 'zhTW', '你需要什麼？', '', 28153),
(150784, 'zhTW', '保持這樣下去，對我們有利。', '', 28153),
(150783, 'zhTW', '去讓支持威奎斯特的那些人臣服，你就會拿到獎賞。', '', 28153),
(150781, 'zhTW', '把你最好的手下帶到置燭碼頭。你可以從那裡開始盡情地燒殺擄掠，消耗他們的物資，裝滿我們的箱子。', '', 28153),
(150779, 'zhTW', '黎德菲斯船長，我們最敬重的贊助人通知我，威奎斯特家族已經沒落了。', '', 28153),
(150778, 'zhTW', '你為什麼沒在崗位上？', '你為什麼沒在崗位上？', 28153),
(150777, 'zhTW', '我希望選擇金布爾作為我的羅亞。', '我希望選擇金布爾作為我的羅亞。', 28153),
(150776, 'zhTW', '就是艾澤拉斯之心！', '', 28153),
(150775, 'zhTW', '<這座祭壇的用途在於供奉獸王金布爾。>', '<這座祭壇的用途在於供奉獸王金布爾。>', 28153),
(150773, 'zhTW', '嗯？', '嗯？', 28153),
(150772, 'zhTW', '就算我是她的代言人，但「你」是她的勇士，她需要你為她挺身奮戰。', '', 28153),
(150771, 'zhTW', '勇士，艾澤拉斯向你呼喚。她想送你一個禮物…是個源於她自身的禮物。', '', 28153),
(150770, 'zhTW', '自由了！我們必須去神廟裡面的安全之處！', '自由了！我們必須去神廟裡面的安全之處！', 28153),
(150769, 'zhTW', '發…發生什麼事了？', '發…發生什麼事了？', 28153),
(150768, 'zhTW', '', '古翰！請賜給我力量！', 28153),
(150767, 'zhTW', '這份人情只能在彼界還你了，朋友。', '這份人情只能在彼界還你了，朋友。', 28153),
(150766, 'zhTW', '', '末日降臨！', 28153),
(150765, 'zhTW', '', '哭著求饒吧！', 28153),
(150764, 'zhTW', '', '所有人都得服侍主人！', 28153),
(150763, 'zhTW', '終於，擺脫那些受詛咒的骨頭了！', '終於，擺脫那些受詛咒的骨頭了！', 28153),
(150762, 'zhTW', '我們這就把哈蘭‧史威特的寶物拿走吧。', '', 28153),
(150761, 'zhTW', '泰坦圓盤已啟動：正在啟動混亂程序', '泰坦圓盤已啟動：正在啟動混亂程序', 28153),
(150760, 'zhTW', '我會還回去！我發誓！', '我會還回去！我發誓！', 28153),
(150759, 'zhTW', '哈蘭‧史威特的時代結束了。大海是屬於我們的！', '', 28153),
(150758, 'zhTW', '啊啊啊！', '啊啊啊！', 28153),
(150757, 'zhTW', '那是我偷的，別跟我搶！', '那是我偷的，別跟我搶！', 28153),
(150756, 'zhTW', '哈哈！我就知道賭你贏準沒錯！', '', 28153),
(150755, 'zhTW', '散開！', '快逃！', 28153),
(150754, 'zhTW', '啊！危險的陌生人！', '啊！危險的陌生人！', 28153),
(150753, 'zhTW', '想來打碎幾顆頭顱，賺點零用錢嗎？', '', 28153),
(150752, 'zhTW', '這整座島都被封鎖了。在競技場打鬥結束前都不會解除的。', '', 28153),
(150750, 'zhTW', '做得很好…可是想痛宰哈蘭一頓可沒有那麼容易。', '', 28153),
(150749, 'zhTW', '簡單的方法嘛，就是想辦法拿到邀請函。困難的方法呢，就是衝進去把這世界上最可怕的三位海盜船長直接殺掉。你自己決定吧，有錢人。', '', 28153),
(150748, 'zhTW', '就算是魚也沒有污鼠會那麼會喝！只要你證明酒量比他們好，尤多拉船長就會找你參加會議。', '', 28153),
(150747, 'zhTW', '黑牙惡徒最愛打架練拳頭。要是你能打得他們滿地找牙，拉沃船長就會拉你去開會。', '', 28153),
(150746, 'zhTW', '聽說那些船長打算見面開會。如果我們混進去，就能一次把九頭蛇的腦袋都砍下來！', '', 28153),
(150745, 'zhTW', '戰爭可不會自己結束，我們有工作要做！', '', 28153),
(150744, 'zhTW', '然後我們再把哈蘭解決掉。', '', 28153),
(150743, 'zhTW', '我們要讓分水海寇沒水、污鼠會抱頭鼠竄，把黑牙打得滿地找牙，再把鐵潮變成廢鐵。', '', 28153),
(150742, 'zhTW', '要是他成功，他的艦隊就會威脅到我們的海上勢力。', '', 28153),
(150741, 'zhTW', '哈蘭想把所有的海盜都納入鐵潮的勢力之下。', '', 28153),
(150740, 'zhTW', '感謝你釋放我。我感受到神廟內部傳來了伯昂撒姆第的呼喚，我們走。', '感謝你釋放我。我感受到神廟內部傳來了伯昂撒姆第的呼喚，我們走。', 28153),
(150739, 'zhTW', '我以為自己會永遠成為一具醜陋的骸骨。我必須趕快回神廟去！', '我以為自己會永遠成為一具醜陋的骸骨。我必須趕快回神廟去！', 28153),
(150738, 'zhTW', '返回到伯昂撒姆第…神廟…盡快…', '返回到伯昂撒姆第…神廟…盡快…', 28153),
(150737, 'zhTW', '我剩下的感知能力被他們汙穢的儀式鈍化了…帶我走到神廟的台階。', '我剩下的感知能力被他們汙穢的儀式鈍化了…帶我走到神廟的台階。', 28153),
(150736, 'zhTW', '感謝你，老兄！我很快就要消失了，請帶我到伯昂撒姆第的神廟。', '感謝你，老兄！我很快就要消失了，請帶我到伯昂撒姆第的神廟。', 28153),
(150735, 'zhTW', '你拿著什麼，有錢的夥伴？老迦尼的一個亮晶晶的飾品？拿近一點…', '', 28153),
(150734, 'zhTW', '我是這裡唯一懂數學的人！所以我負責注意支出，確保大家沒有亂花錢。', '', 28153),
(150733, 'zhTW', '在這場戰爭裡，苦工實在功不可沒。', '', 28153),
(150732, 'zhTW', '希望你平安歸來。', '', 28153),
(150731, 'zhTW', '小心那些鮮血食人妖。', '', 28153),
(150730, 'zhTW', '自己務必小心，千萬別死了！', '', 28153),
(150729, 'zhTW', '贊達拉情況很不妙。', '', 28153),
(150728, 'zhTW', '嘔，我超討厭鮮血食人妖。', '', 28153),
(150727, 'zhTW', '我們該如何擺脫困境？', '', 28153),
(150726, 'zhTW', '哼！部落自找苦頭。我會將這個裝置帶到亞羅姆之地，看看是否有人用得上。做得好。', '', 28153),
(150719, 'zhTW', '我準備好要保衛贊達拉了。', '我準備好要保衛贊達拉了。', 28153),
(150718, 'zhTW', '走這邊！我們的地面部隊在下面等著。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150717, 'zhTW', '', '森林正痛苦地哀嚎著。你聽得到嗎？', 28153),
(150716, 'zhTW', '我們要回家啦！', '我們要回家啦！', 28153),
(150715, 'zhTW', '看起來你好像不需要我幫忙！我們已經盡力早點趕回來了！', '', 28153),
(150714, 'zhTW', '我和達利爾一輩子都在這些山裡面生活，我們會比任何一個部落活得更久！', '', 28153),
(150713, 'zhTW', '你想要回祖達薩然後被殺，或是留在這裡被迅猛龍殺？', '你想要回祖達薩然後被殺，或是留在這裡被迅猛龍殺？', 28153),
(150712, 'zhTW', '我才不去沃魯敦，你聽到了嗎？我要在城裡過一輩子！', '', 28153),
(150711, 'zhTW', '', '艾瑪，新鮮的烏龜耶！現在就把我該得的一份給我！！', 28153),
(150710, 'zhTW', '你拿著什麼，有錢的夥伴？老迦尼的一個亮晶晶的飾品？拿近一點…', '', 28153),
(150709, 'zhTW', '', 'Xul krass qi\' UN skush！', 28153),
(150708, 'zhTW', '', 'Skitsh qi\'uthik illith！', 28153),
(150707, 'zhTW', '', '地板上到處都是屠殺的痕跡。', 28153),
(150706, 'zhTW', '', '要不要到地下室來，一起讚嘆死亡的美呢？', 28153),
(150705, 'zhTW', '', '喔天啊，你們把整棟屋子裡的人都殺光了啊。', 28153),
(150704, 'zhTW', '<你看到年輕食人妖的影像，他看著一支出殯的隊伍，瞪大雙眼，一臉無辜。>', '<你看到年輕食人妖的影像，他看著一支出殯的隊伍，瞪大雙眼，一臉無辜。>', 28153),
(150703, 'zhTW', '離開大門！這裡不安全。', '離開大門！這裡不安全。', 28153),
(150702, 'zhTW', '夸風向朝咆哮。回去找拉爾，或是解除坐騎！', '夸風向朝咆哮。回去找拉爾，或是解除坐騎！', 28153),
(150701, 'zhTW', '', '在痛苦中掙扎吧！', 28153),
(150700, 'zhTW', '', '我會撕裂你的靈魂！', 28153),
(150699, 'zhTW', '', '用那玩意兒害我頭髮都變綠了！', 28153),
(150698, 'zhTW', '', '你們的尖叫會迴盪不絕！', 28153),
(150697, 'zhTW', '', '我主宰一切！', 28153),
(150696, 'zhTW', '', '基羅，他們還活著！我們不能把他們留在這裡…', 28153),
(150695, 'zhTW', '快點，能拿就拿，屍體就留給禿鷹解決。', '', 28153),
(150694, 'zhTW', '這裡就是你們的葬身之地…', '', 28153),
(150693, 'zhTW', '有人入侵！', '', 28153),
(150692, 'zhTW', '你去做你的事吧，將軍，我的部分不勞你費心。', '', 28153),
(150691, 'zhTW', '這件事情必須加速進行，有些煩人的訪客來晉見國王…恐怕會妨礙我們。', '', 28153),
(150690, 'zhTW', '', '托達戈爾有個護衛，長得和你一模一樣！', 28153),
(150689, 'zhTW', '', '你以為有辦法繞過我溜進波拉勒斯銀行是吧？', 28153),
(150688, 'zhTW', '', '你擔心過輻射嗎？', 28153),
(150687, 'zhTW', '', '你會哪些有用的技能？比如說偽造或是開保險箱？', 28153),
(150686, 'zhTW', '', '風暴消散，我回過神來了。感謝你們。', 28153),
(150685, 'zhTW', '', '你們的生命毫無意義，死後就會遭人遺忘。', 28153),
(150684, 'zhTW', '', '骯髒的東西！', 28153),
(150683, 'zhTW', '', '幫我治療，然後我來關閉它們！', 28153),
(150682, 'zhTW', '', '妖術破除了，不過神廟的防禦也甦醒了！', 28153),
(150681, 'zhTW', '', '準備承受無盡的折磨！', 28153),
(150680, 'zhTW', '我很樂意看你烤熟的樣子！', '', 28153),
(150679, 'zhTW', '去死吧，害蟲！', '', 28153),
(150678, 'zhTW', '弧光斬！', '', 28153),
(150677, 'zhTW', '斬開！', '', 28153),
(150676, 'zhTW', '廢物！', '', 28153),
(150675, 'zhTW', '和玻璃一樣脆弱！', '', 28153),
(150674, 'zhTW', '我不是怕了也不是膽小鬼。我只是不喜歡！', '', 28153),
(150673, 'zhTW', '沒人可以反抗我們的帝國！', '', 28153),
(150672, 'zhTW', '我當然可以爬上去。我不是個娘娘腔！', '', 28153),
(150671, 'zhTW', '我不需要向你證明任何事！', '', 28153),
(150670, 'zhTW', '來吧，亞伯拉罕。我看過小孩子都做過。', '', 28153),
(150669, 'zhTW', '拜託，這沒那麼高。', '', 28153),
(150668, 'zhTW', '我賭你爬不上去。', '', 28153),
(150667, 'zhTW', '這不好笑！把我從這裡弄下去！', '', 28153),
(150666, 'zhTW', '不要再開玩笑了，救我下去！', '', 28153),
(150665, 'zhTW', '快救我下去！', '', 28153),
(150664, 'zhTW', '快走，當你還有辦法的時候！', '快走，當你還有辦法的時候！', 28153),
(150663, 'zhTW', '他們抓不走我的！', '他們抓不走我的！', 28153),
(150662, 'zhTW', '他們可以拿走我那一份！', '他們可以拿走我那一份！', 28153),
(150661, 'zhTW', '我們會殺死所有的鐵潮！', '我們會殺死所有的鐵潮！', 28153),
(150660, 'zhTW', '他們抓不走我的！', '他們抓不走我的！', 28153),
(150659, 'zhTW', '我不為海盜做事！', '我不為海盜做事！', 28153),
(150658, 'zhTW', '', '我要打扁你的腦袋！', 28153),
(150657, 'zhTW', '閒晃好玩嗎？哈！', '', 28153),
(150656, 'zhTW', '這裡有什麼麻煩嗎，亞伯拉罕？', '', 28153),
(150655, 'zhTW', '喔，白癡！你給我卡在那上面！', '', 28153),
(150654, 'zhTW', '瑟沙利斯獻出生命，拯救了這個世界。如果謎思拉克斯重返人間，她勇敢的犧牲就沒有意義了…', '', 28153),
(150653, 'zhTW', '謎思拉克斯就算死亡，殘留的精華還是很有力量，如果他再次復甦，這個世界不知道會變成什麼樣子…', '', 28153),
(150652, 'zhTW', '裡面有個邪惡的存在，我們一定要小心…', '', 28153),
(150651, 'zhTW', '', '他們開始朝成就大事邁進了一步。', 28153),
(150650, 'zhTW', '', '該來測試一下那些小傢伙了，這樣他們才能為自己的命運開始努力。你去鼓勵他們返回階級大廳。', 28153),
(150649, 'zhTW', '非常好！有了這些，就能做弓箭給獵人用，做護甲給我們穿了。', '', 28153),
(150648, 'zhTW', '要在沼澤裡建立補給線非常困難。為了維持部隊所需，你必須從野生動植物身上取得資源。', '', 28153),
(150647, 'zhTW', '啊，這些夠用了。這些滑溜溜的小傢伙，應該沒給你帶來太多麻煩吧？', '', 28153),
(150646, 'zhTW', '有一大群水刺烏賊？太好了！我墨水剛好用完！帶著這個卷軸，從烏賊身上汲取一些寶貴的墨水。', '', 28153),
(150645, 'zhTW', '', '看來我們的部隊非常需要這個，做得太好了！', 28153),
(150644, 'zhTW', '', '梅卡托克的無人飛行機科技再次躍進，現在需要實戰測試。我們聽說附近躲著很多鮮血食人妖，正好可以用它來搜尋敵人，加以殲滅！', 28153),
(150643, 'zhTW', '<爬上去！>', '<爬上去！>', 28153),
(150642, 'zhTW', '<夸風轉頭打量你。牠發出尖銳的叫聲，算是在打招呼。>\n\n嗄啊！', '', 28153),
(150641, 'zhTW', '', '齷齪的小怪物。', 28153),
(150640, 'zhTW', '', '拉尼舒有很多個胃，別找到第一個胃後就不挖了。', 28153),
(150639, 'zhTW', '牠不能飛，要回到上頭的棲息地會需要時間。我很確定牠會沒事的。$b$b待會再來看看，牠應該就回來了。', '', 28153),
(150638, 'zhTW', '嗯，我解決了。對了，不用客氣。$b$b我注意到牠看起來有點失落。或許你可以再帶牠去飛一飛！牠確實需要運動一下。', '', 28153),
(150637, 'zhTW', '那風箏要用來幹嘛？', '那風箏要用來幹嘛？', 28153),
(150636, 'zhTW', '', '我們必須快點追上她！走吧！', 28153),
(150635, 'zhTW', '', '我們要趕快，找到洛琪拉！', 28153),
(150634, 'zhTW', '早先你一步了，坎蘇。', '', 28153),
(150633, 'zhTW', '謝了，$p。沒有你，我們絕對辦不到，這是你應得的。', '', 28153),
(150632, 'zhTW', '而現在，塔恰與歐米...我們將把這地方所有值錢的東西拿得乾乾淨淨。', '', 28153),
(150631, 'zhTW', '夠了！我賜予你死在我手上的榮耀！', '', 28153),
(150630, 'zhTW', '就算是死亡，我和寵物之間的連結也不會消滅。開飯啦，特札拉…享受大餐吧！', '', 28153),
(150629, 'zhTW', '沒人能擋得住我的刀！', '', 28153),
(150628, 'zhTW', '殺戮時刻！', '', 28153),
(150627, 'zhTW', '我要剝了你的皮！', '', 28153),
(150626, 'zhTW', '怎麼可能？啊…終於啊！', '', 28153),
(150625, 'zhTW', '我的傳奇會長久流傳下去！', '', 28153),
(150624, 'zhTW', '休想搶走我的王位！', '', 28153),
(150623, 'zhTW', '這就是為什麼我是國王…而你什麼都不是。', '', 28153),
(150622, 'zhTW', '褻瀆我的神廟，你要付出代價！', '', 28153),
(150621, 'zhTW', '打獵的時候到了！', '', 28153),
(150620, 'zhTW', '這種毒沒有解藥！', '', 28153),
(150619, 'zhTW', '元素回應我的呼喚吧！', '', 28153),
(150618, 'zhTW', '讓你知道真正的妖術是什麼！', '', 28153),
(150617, 'zhTW', '', '這個可是很痛的喔！', 28153),
(150616, 'zhTW', '', '你死定了！', 28153),
(150615, 'zhTW', '', '該拿斧頭了！', 28153),
(150614, 'zhTW', '', '你最好繼續走，如果你知道什麼對你是好的。', 28153),
(150613, 'zhTW', '', '有人的人頭要落地了！', 28153),
(150612, 'zhTW', '不要…把我…埋在那些…蠢貨附近…', '', 28153),
(150611, 'zhTW', '', '我的頭…會變成…很棒的戰利品…', 28153),
(150610, 'zhTW', '', '我的憤怒…不會…結束…', 28153),
(150609, 'zhTW', '噓…我正在找蝴蝶！', '', 28153),
(150608, 'zhTW', '', '噢！你的頭會是個漂亮的裝飾品。', 28153),
(150607, 'zhTW', '', '連我以前打死的蟲子都比你強！', 28153),
(150606, 'zhTW', '你被巫毒解決了！', '', 28153),
(150605, 'zhTW', '', '我的怒火摧毀一切！', 28153),
(150603, 'zhTW', '我要拿走寶藏！', '我要拿走寶藏！', 28153),
(150602, 'zhTW', '讓聲音停下來！', '讓聲音停下來！', 28153),
(150601, 'zhTW', '那個寶藏是我的！', '那個寶藏是我的！', 28153),
(150599, 'zhTW', '', '哈！我來幫你的肩膀減輕一點負擔！', 28153),
(150598, 'zhTW', '哈！你們不應該喚醒我的力量。', '', 28153),
(150597, 'zhTW', '', '鮮血和白骨！', 28153),
(150596, 'zhTW', '', '你逃不掉的！', 28153),
(150595, 'zhTW', '巫醫來了！', '', 28153),
(150594, 'zhTW', '把軀體準備好！', '', 28153),
(150593, 'zhTW', '有數顆卵開始在北邊孵化！', '有數顆卵開始在北邊孵化！', 28153),
(150592, 'zhTW', '你打擾到死者了！', '', 28153),
(150591, 'zhTW', '覆蓋灰塵的卵開始在東邊孵化！', '覆蓋灰塵的卵開始在東邊孵化！', 28153),
(150590, 'zhTW', '西邊沾滿劇毒的蛋開始孵化！', '西邊沾滿劇毒的蛋開始孵化！', 28153),
(150589, 'zhTW', '預防感染！挖出腦子！', '', 28153),
(150588, 'zhTW', '一定要淨化鮮血詛咒！', '', 28153),
(150587, 'zhTW', '一定要…保存好…死者…', '', 28153),
(150586, 'zhTW', '', '我叫卡嘉繼續前進，我們一定要想辦法及時制止賈克拉傑！', 28153),
(150585, 'zhTW', '解決麻煩了！', '', 28153),
(150584, 'zhTW', '回歸塵土吧！', '', 28153),
(150583, 'zhTW', '安息吧。', '', 28153),
(150582, 'zhTW', '你的血受了詛咒！', '', 28153),
(150581, 'zhTW', '你的軀體帶來毀滅！', '', 28153),
(150580, 'zhTW', '', '呃啊…我的頭…到底怎麼回事？', 28153),
(150574, 'zhTW', '才不會讓你稱心如意，怪物！', '', 28153),
(150573, 'zhTW', '風暴甦醒。', '風暴甦醒。', 28153),
(150572, 'zhTW', '滾開！', '滾開！', 28153),
(150571, 'zhTW', '沒問題，讓我瞧瞧你有什麼，Vali。', '沒問題，讓我瞧瞧你有什麼，Vali。', 28153),
(150570, 'zhTW', '你為什麼需要錢幣？', '你為什麼需要錢幣？', 28153),
(150569, 'zhTW', '長著獠牙的人來到這裡，總是會用錢幣買東西。$B$B瓦利想說在沃魯敦外面的世界買東西一定要用錢幣！$B$B如果瓦利想離開沃魯敦，就需要錢幣。', '', 28153),
(150568, 'zhTW', '有錢幣的話，可以跟Vali買些陶器！', '', 28153),
(150567, 'zhTW', '喂喂！沒錯，就是你！你好像需要一點水！', '', 28153),
(150566, 'zhTW', '', '麥斯，謝謝你。等這一切結束之後，我們應該討論一下家族新任外交官的人選。', 28153),
(150565, 'zhTW', '', '我相信你。如果有人為難你，就趕快用力敲對方的頭，這樣就解決了。', 28153),
(150564, 'zhTW', '我應該要返回祭壇，這個精華值得調查一番。', '我應該要返回祭壇，這個精華值得調查一番。', 28153),
(150563, 'zhTW', '需要修理東西嗎？工具雖然老舊，但在我手上它們還是有點用處。', '需要修理東西嗎？工具雖然老舊，但在我手上它們還是有點用處。', 28153),
(150562, 'zhTW', '我希望選擇亞昆達作為我的羅亞。', '我希望選擇亞昆達作為我的羅亞。', 28153),
(150561, 'zhTW', '<這座祭壇的用途在於供奉風暴之羅亞亞昆達。>', '<這座祭壇的用途在於供奉風暴之羅亞亞昆達。>', 28153),
(150560, 'zhTW', '', '真是放肆！讓你父親聽聽你說的是什麼話。這段時間，我就先派僕人陪陪你們吧。', 28153),
(150559, 'zhTW', '', '我才不是你的女兒！你這個女巫！', 28153),
(150558, 'zhTW', '', '女兒，歡迎回家。你還帶了客人來啊。', 28153),
(150557, 'zhTW', '啊啊啊啊啊！', '啊啊啊啊啊！', 28153),
(150556, 'zhTW', '靠近一點檢視編織。', '靠近一點檢視編織。', 28153),
(150555, 'zhTW', '這織布機與其造物似乎灌注著女巫的魔法。', '這織布機與其造物似乎灌注著女巫的魔法。', 28153),
(150554, 'zhTW', '拿走瓶子。', '拿走瓶子。', 28153),
(150553, 'zhTW', '雖然這瓶腐敗已久，但對經驗老到的廚師來說可能還會有用。', '雖然這瓶腐敗已久，但對經驗老到的廚師來說可能還會有用。', 28153),
(150552, 'zhTW', '啊啊！發生什麼事了！救命！', '', 28153),
(150551, 'zhTW', '摧毀不成熟的豆莢。', '摧毀不成熟的豆莢。', 28153),
(150550, 'zhTW', '一個充滿疫病的囊苞在這裡沉睡。看來有人在培養這個要進行邪惡的計畫。', '一個充滿疫病的囊苞在這裡沉睡。看來有人在培養這個要進行邪惡的計畫。', 28153),
(150549, 'zhTW', '把地圖拿走。', '把地圖拿走。', 28153),
(150548, 'zhTW', '一張磨損的地圖，標出當地的狩獵點以及這裡的皮革商位置。', '一張磨損的地圖，標出當地的狩獵點以及這裡的皮革商位置。', 28153),
(150547, 'zhTW', '你確定要這樣做？', '你確定要這樣做？', 28153),
(150546, 'zhTW', '你…你居然跳進鍋子裡！你到底為什麼會做出這種事？！我們得重新開始了！', '', 28153),
(150545, 'zhTW', '', '道路通了！趁下一波敵人還沒打來，朝大門前進。', 28153),
(150544, 'zhTW', '', '大師，有什麼需要就告訴這位英雄。我先去洛伊斯頓鎮長那邊幫忙。', 28153),
(150543, 'zhTW', '你別想活捉我！', '你別想活捉我！', 28153),
(150542, 'zhTW', '', '這真是太好了，艾希頓大師。', 28153),
(150541, 'zhTW', '審判官，能幫到你和露西爾小姐，對我來說是至高無上的榮耀。', '', 28153),
(150540, 'zhTW', '真是不得了！好神奇的配方！產品非常易燃！', '', 28153),
(150539, 'zhTW', '露西爾小姐覺得應該交給我？好，我來看看！', '', 28153),
(150538, 'zhTW', '', '她發現了前人使用的煉金配方，希望你能重新製造出這樣東西。', 28153),
(150537, 'zhTW', '', '露西爾小姐重組了燼火會，我們會遵循古老文獻的指引對抗女巫，就像我們曾與佐司特奮戰一樣。', 28153),
(150536, 'zhTW', '', 'Krax il\' oni OGOG！', 28153),
(150535, 'zhTW', '', 'Ul tala kraza。', 28153),
(150534, 'zhTW', '', 'Bwaxa za\' raga xil。', 28153),
(150533, 'zhTW', '', 'Kryl！', 28153),
(150532, 'zhTW', '我知道…這是為什麼？', '', 28153),
(150531, 'zhTW', '', 'Bwixki amala zal qulllll…', 28153),
(150530, 'zhTW', '', 'Aglathrax hig\' thrixa。', 28153),
(150529, 'zhTW', '', '艾希頓大師，我們奉威奎斯特小姐之命來這裡找你。', 28153),
(150528, 'zhTW', '', 'ULL vera skish！', 28153),
(150527, 'zhTW', '在我的力量面前，你哪有什麼機會？', '', 28153),
(150526, 'zhTW', '淨化完畢！', '', 28153),
(150525, 'zhTW', '清理掉了！', '', 28153),
(150524, 'zhTW', '海潮…背棄了我…', '', 28153),
(150523, 'zhTW', '我會親眼看著你淹死！', '', 28153),
(150522, 'zhTW', '我不會再容忍你無禮的行為！', '', 28153),
(150521, 'zhTW', '我召喚洶湧的流水！聽我號令，淹沒這些入侵者！', '', 28153),
(150520, 'zhTW', '你們這些蠢貨竟敢來弄髒這個聖地！', '', 28153),
(150519, 'zhTW', '好好享受水葬的感覺吧！', '', 28153),
(150518, 'zhTW', '[畫面顯示賈克拉傑和塞斯拉克帝王科爾塞克被蛇人擁簇著，密謀要闖入金字塔。科爾塞克把你自空中擊落。]', '', 28153),
(150517, 'zhTW', '艾澤拉斯想要我怎麼辦，麥格尼？', '艾澤拉斯想要我怎麼辦，麥格尼？', 28153),
(150516, 'zhTW', '你應該回去待在岸上！', '', 28153),
(150515, 'zhTW', '讓我…回到海裡…', '', 28153),
(150514, 'zhTW', '我要把你放逐到深淵，付出代價！', '', 28153),
(150513, 'zhTW', '不！', '', 28153),
(150512, 'zhTW', '潮水會帶走你！', '', 28153),
(150511, 'zhTW', '我們之間的愛，絕對切不斷。', '', 28153),
(150510, 'zhTW', '', '親愛的，只要同心協力，我們堪比狂風暴雨。', 28153),
(150509, 'zhTW', '', '風暴淨化了你！', 28153),
(150508, 'zhTW', '', '吹走吧！', 28153),
(150507, 'zhTW', '|TInterface\\Icons\\INV_MISC_LESSERESSENCE:20|t%s得到了|cFFFF0000|Hcurrency:1559|h風暴精華|h|r！', '|TInterface\\Icons\\INV_MISC_LESSERESSENCE:20|t%s得到了|cFFFF0000|Hcurrency:1559|h風暴精華|h|r！', 28153),
(150506, 'zhTW', '', '雲層…散開了…', 28153),
(150505, 'zhTW', '', '強風會讓你的血肉與骨頭分離！', 28153),
(150504, 'zhTW', '', '親愛的！不！', 28153),
(150503, 'zhTW', '要是有人能活下來，那非他莫屬。我去花園那邊查看一下，審判官。', '', 28153),
(150502, 'zhTW', '', '沒人能對抗風暴！', 28153),
(150501, 'zhTW', '', '獵鷹林遭到猛烈攻擊。希望艾希頓大師還活著。', 28153),
(150500, 'zhTW', '', '普莉希拉騎馬逃走了！快騎我們的戰騎追她！', 28153),
(150499, 'zhTW', '艾希頓大師，我們需要你的幫助。', '艾希頓大師，我們需要你的幫助。', 28153),
(150498, 'zhTW', '非常感謝你，我現在要走了。', '非常感謝你，我現在要走了。', 28153),
(150497, 'zhTW', '我永遠都不會忘記的！我要離開這裡了！', '我永遠都不會忘記的！我要離開這裡了！', 28153),
(150496, 'zhTW', '我原本很擔心我會在那裡待上一輩子…這個代表我的感謝之意！', '我原本很擔心我會在那裡待上一輩子…這個代表我的感謝之意！', 28153),
(150495, 'zhTW', '謝謝你放我自由，也許這可以幫助到你。', '謝謝你放我自由，也許這可以幫助到你。', 28153),
(150494, 'zhTW', '感謝老天爺你救了我！讓我盡可能的幫助你吧。', '感謝老天爺你救了我！讓我盡可能的幫助你吧。', 28153),
(150493, 'zhTW', '不要把我丟在這裡！', '不要把我丟在這裡！', 28153),
(150492, 'zhTW', '讓我出去！', '讓我出去！', 28153),
(150491, 'zhTW', '', '拜託！請幫助我們！要是不阻止勾拉圖爾，他會在艾澤拉斯到處作亂的。', 28153),
(150490, 'zhTW', '幫我！', '幫我！', 28153),
(150489, 'zhTW', '快點，找個方法把牢房打開！', '快點，找個方法把牢房打開！', 28153),
(150488, 'zhTW', '放我出去！', '放我出去！', 28153),
(150487, 'zhTW', '請幫助我！', '請幫助我！', 28153),
(150486, 'zhTW', '羽冠龍？這裡怎麼會有羽冠龍？', '', 28153),
(150485, 'zhTW', '', '他們是什麼人不重要，我們迫切需要幫忙。絕對不能讓勾拉圖爾入侵我們的家園！', 28153),
(150484, 'zhTW', '', '別緊張，艾希頓大師！我們不是壞人！', 28153),
(150483, 'zhTW', '我們來晚了！等等，你們是什麼人？', '', 28153),
(150482, 'zhTW', '嗯，你們看起來不像壞人。外頭的攻擊停止了嗎？', '', 28153),
(150480, 'zhTW', '退後！不然我就用鍊金術對付你們！', '', 28153),
(150479, 'zhTW', '你們殺掉威奎斯特夫人，等於打開了迎接我前往這個世界的通道。', '', 28153),
(150478, 'zhTW', '你們這群沒有遠見的凡人，沒人能阻擋死亡。', '', 28153),
(150477, 'zhTW', '', '既然你在這裡待了這麼久，那好吧，你就永遠待在這裡吧！', 28153),
(150476, 'zhTW', '', '再插手管我的閒事，我就慢慢折磨你們，讓你們生不如死。', 28153),
(150475, 'zhTW', '', '從你臉上沉悶的表情看起來，在你的世界裡，所有人的家大概都是用糞便糊成的破舊房子吧。', 28153),
(150474, 'zhTW', '', '我想想，你還是別回答吧。', 28153),
(150473, 'zhTW', '', '你是什麼地方來的野人，殺掉女主人的僕人算是哪門子的禮貌？', 28153),
(150472, 'zhTW', '我準備好了，出發去找其他人吧。', '我準備好了，出發去找其他人吧。', 28153),
(150471, 'zhTW', '我們不能浪費時間，你的朋友們已經在阿圖亞曼裡面了…', '', 28153),
(150470, 'zhTW', '夸風失措地尖叫，拔腿就跑。', '', 28153),
(150469, 'zhTW', '', '小傢伙！你要是還想回家，現在最好趕快跑。', 28153),
(150468, 'zhTW', '', '我們現在要幫牠上一堂實務演練課。', 28153),
(150467, 'zhTW', '', '你的小傢伙對自己的翅膀沒信心。你必須繼續向它展現天際的美妙。', 28153),
(150466, 'zhTW', '', '你怎麼還在用腳走？', 28153),
(150465, 'zhTW', '', '你們兩個都活著。很好。就像我說的-', 28153),
(150464, 'zhTW', '', '謝謝你們，英雄。你們消滅了女巫會，還把我們從勾拉圖爾手裡救出來。能有今天真是多虧你們了。', 28153),
(150463, 'zhTW', '', '你看，只要有力氣跟武器，什麼都能搞定。', 28153),
(150462, 'zhTW', '成功了！消滅勾拉圖爾了！', '', 28153),
(150461, 'zhTW', '隨著危機近逼，夸風發出尖嘯求助！', '隨著危機近逼，夸風發出尖嘯求助！', 28153),
(150460, 'zhTW', '凡人，來吧，死亡在等著你們。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150459, 'zhTW', '', '我跟斯騰泰德留在這裡擋住他們。你們去做個了斷！', 28153),
(150458, 'zhTW', '', '莊園裡的怪物都朝我們這裡過來了！', 28153),
(150457, 'zhTW', '', '絕對不能讓勾拉圖爾返回這個世界！', 28153),
(150456, 'zhTW', '風箏開始劇烈抖動。返回氣流更平穩的地方！', '風箏開始劇烈抖動。返回氣流更平穩的地方！', 28153),
(150455, 'zhTW', '|TInterface\\ICONS\\INV_POTION_24:20|t 使用|cFFFF0404|Hspell:266198|h[鍊金火焰]|h|r來摧毀死觸奴隸的屍體！', '', 28153),
(150454, 'zhTW', '你們的夢魘現在才正要開始。', '', 28153),
(150453, 'zhTW', '威奎斯特夫人只不過是我手裡的棋子。你們殺掉她，剛好幫我開了一條路。', '', 28153),
(150452, 'zhTW', '吸收中', '吸收中', 28153),
(150451, 'zhTW', '蠢孩子，真沒遠見。死亡會緊緊跟隨著你，沒有人能躲開。', '', 28153),
(150450, 'zhTW', '', '這漫長的噩夢，終於結束了。', 28153),
(150448, 'zhTW', '去吧，小傢伙，把帽子拿回來，贏得迦尼的青睞。不過記得要小心，別讓飢餓的掠食者發現你…', '', 28153),
(150446, 'zhTW', '', '沒錯。要是大家知道我的家人做出這麼可怕的事，我到時候要怎麼說服大家相信我？', 28153),
(150445, 'zhTW', '', '現在最重要的是阻止她這種邪惡的行為。', 28153),
(150444, 'zhTW', '', '我的母親性情殘酷，不過我沒想到她竟然會這麼做。', 28153),
(150443, 'zhTW', '你先走，去找威奎斯特夫人，把這筆帳算清楚。', '', 28153),
(150442, 'zhTW', '哼！這下死了吧！', '', 28153),
(150441, 'zhTW', '一定要讓威奎斯特夫人為她邪惡的巫術付出代價。', '', 28153),
(150440, 'zhTW', '你釋放了那些靈魂，幫了它們一個大忙。', '', 28153),
(150439, 'zhTW', '你繼續去追殺威奎斯特夫人。這些房間就交給我處理。', '', 28153),
(150438, 'zhTW', '這些邪惡生物終於不會在夜裡突襲，我可以睡個好覺了。', '', 28153),
(150437, 'zhTW', '你去對付她的僕人，我們會好好調查。祝你一切順利。', '', 28153),
(150436, 'zhTW', '', '各位英雄，我要借助你們的力量。一定要消滅這股邪惡的勢力。', 28153),
(150435, 'zhTW', '到處亂跑應該解決不了問題，我們應該還有其他計畫吧…有嗎？', '', 28153),
(150434, 'zhTW', '麥斯！', '', 28153),
(150433, 'zhTW', '', '給我回來，看我的厲害！', 28153),
(150432, 'zhTW', '', '遵命，夫人。', 28153),
(150431, 'zhTW', '', '女士們，快出來招呼我們的客人。', 28153),
(150430, 'zhTW', '', '看來有人不請自來。沒關係，我們一定會好好招待他們。', 28153),
(150429, 'zhTW', '你總是出人意表。', '你總是出人意表。', 28153),
(150428, 'zhTW', '做得好，$r！', '做得好，$p', 28153),
(150427, 'zhTW', '我自由了！', '我自由了！', 28153),
(150426, 'zhTW', '我欠你的！', '我欠你的！', 28153),
(150425, 'zhTW', '非常感謝！', '非常感謝！', 28153),
(150421, 'zhTW', '我要賜予你一部分的神力，我的庇佑會淨化所有敢挑戰你的無信者。', '', 28153),
(150420, 'zhTW', '老朋友，你怕了嗎？同胞被殺得血流成河，你卻躲在裡面？科爾塞克，出來面對我們！', '', 28153),
(150419, 'zhTW', '$p，你應該和我合作，我一定會找到的。', '$p，你應該和我合作，我一定會找到寶藏。', 28153),
(150418, 'zhTW', '', '只是一點小阻礙而已！我們會重整旗鼓，拿下這個破城鎮！', 28153),
(150417, 'zhTW', '祖爾的變節造成的傷害比我以為的還大。他的叛亂基本上已經耗盡了我的軍隊。\n\n那些依然效忠我的人正在我身後的戰場上死去，被那些成群蜂擁入侵的鮮血食人妖殺死。\n\n我早該聽塔蘭姬的話。', '', 28153),
(150416, 'zhTW', '我認識某個知道寶藏在哪裡的傢伙。', '我認識某個知道寶藏在哪裡的傢伙。', 28153),
(150415, 'zhTW', '你知道金子在哪裡嗎？', '你知道金子在哪裡嗎？', 28153),
(150414, 'zhTW', '等你找到寶藏，我們平分。', '等你找到寶藏，我們平分。', 28153),
(150413, 'zhTW', '我聽說鐵潮已經找到了。', '我聽說鐵潮已經找到了。', 28153),
(150412, 'zhTW', '喂，來幫我找寶藏啊！', '喂，幫幫女孩找寶藏啊！', 28153),
(150411, 'zhTW', '這傢伙有個朋友聽到其中一名鐵潮說他們知道寶藏在哪。', '這傢伙有個朋友聽到其中一名鐵潮說他們知道寶藏在哪。', 28153),
(150410, 'zhTW', '說不定有金子的消息全都是謊言。', '說不定有金子的消息全都是謊言。', 28153),
(150409, 'zhTW', '我們得趕在鐵潮劫掠這個地方之前找到那個寶藏。', '我們得趕在鐵潮劫掠這個地方之前找到那個寶藏。', 28153),
(150408, 'zhTW', '', '說不定有人把貓吃了。', 28153),
(150407, 'zhTW', '[DNT] 飛回去吧，高傲的拉奇昂，告訴你的父親是誰放了你。', '', 28153),
(150406, 'zhTW', '', '我會聚集一些人，然後叫其他人搭附近的小艇。玩得愉快，$n！', 28153),
(150405, 'zhTW', '快！在佐司特國王復活他們之前，先用火燒掉！', '', 28153),
(150404, 'zhTW', '快點！用火燒！', '', 28153),
(150403, 'zhTW', '這裡需要支援！', '', 28153),
(150402, 'zhTW', '敵人太多了！', '', 28153),
(150401, 'zhTW', '屈服於黑暗的力量吧！', '', 28153),
(150400, 'zhTW', '起來吧！', '', 28153),
(150399, 'zhTW', '沒人能反抗我！', '', 28153),
(150398, 'zhTW', '你什麼都不是！', '', 28153),
(150397, 'zhTW', '有生必有死。', '', 28153),
(150396, 'zhTW', '死亡…也攔不住我…', '', 28153),
(150395, 'zhTW', '死亡會吞噬萬物！', '', 28153),
(150394, 'zhTW', '沒人能躲過我的復仇！', '', 28153),
(150393, 'zhTW', '所有職員都到廚房來！', '', 28153),
(150392, 'zhTW', '軟嫩可口！', '', 28153),
(150391, 'zhTW', '今晚的主菜格外美味…', '', 28153),
(150390, 'zhTW', '痛苦…好…美味…', '', 28153),
(150388, 'zhTW', '', '狐狸人會看照著你，$p。\n\n將有問題的無信者派到我這裡，我就會解決他們。樂意之至。', 28153),
(150387, 'zhTW', '真美味！', '', 28153),
(150386, 'zhTW', '新鮮的肉！', '', 28153),
(150385, 'zhTW', '吮指美味！', '', 28153),
(150384, 'zhTW', '晚餐來了！', '', 28153),
(150383, 'zhTW', '找到寶藏的人可以獨得三份！', '', 28153),
(150382, 'zhTW', '你想要變有錢嗎？快幫我找到寶藏！', '', 28153),
(150381, 'zhTW', '摩可希，讓這些懶蟲開始工作！', '', 28153),
(150380, 'zhTW', '可惡的鐵潮，你們休想拿到寶藏！', '', 28153),
(150379, 'zhTW', '殺了那個戴海賊帽的傢伙！沒錯，就是他！', '', 28153),
(150378, 'zhTW', '快去檢查岩石底下！不要放過任何小地方！', '', 28153),
(150377, 'zhTW', '把鐵潮趕出這裡！', '', 28153),
(150376, 'zhTW', '<哞～～>', '', 28153),
(150375, 'zhTW', '', '<哞～～>', 28153),
(150374, 'zhTW', '', '真是抱歉…', 28153),
(150373, 'zhTW', '', '無', 28153),
(150372, 'zhTW', '', '不管你們在這裡做什麼，今天都要結束！', 28153),
(150371, 'zhTW', '', '錢在哪裡？', 28153),
(150370, 'zhTW', '', '我知道你就躲在附近！', 28153),
(150369, 'zhTW', '', '我會在船塢摧毀你們全部。', 28153),
(150368, 'zhTW', '', '你們這群人沒有我想的那麼強。', 28153),
(150367, 'zhTW', '', '你要戴著這條鎖鏈直到抵達船塢！', 28153),
(150366, 'zhTW', '你好，有錢人。這裡是拾荒者神殿，你有帶什麼硬硬又粗粗的東西過來嗎？', '', 28153),
(150365, 'zhTW', '讓給他們吧，你死了也花不了！', '讓給他們吧，你死了也花不了！', 28153),
(150364, 'zhTW', '我不會留下寶藏離開的，它就在這裡！', '我不會留下寶藏離開的，它就在這裡！', 28153),
(150363, 'zhTW', '鐵潮要來了！我們得趕快離開這裡！', '鐵潮要來了！我們得趕快離開這裡！', 28153),
(150362, 'zhTW', '你好，有錢人。這裡是拾荒者神殿，你有帶什麼亮亮又滑滑的東西過來嗎？', '', 28153),
(150361, 'zhTW', '我們到了。晴空萬里，真是探險的好日子。', '', 28153),
(150360, 'zhTW', '這可不是普通的地震！附近一定有地方噴發出艾澤萊晶岩了。', '', 28153),
(150359, 'zhTW', '儀器已經好了。你應該能看到所有的艾澤萊晶岩了。', '', 28153),
(150358, 'zhTW', '小心！有艘庫爾提拉斯的船靠岸了。', '', 28153),
(150357, 'zhTW', '不公平，上一個也是你的！', '不公平，上一個也是你的！', 28153),
(150356, 'zhTW', '嘿，那是我的！', '嘿，那是我的！', 28153),
(150355, 'zhTW', '搜他的口袋！', '搜他的口袋！', 28153),
(150354, 'zhTW', '拿鑰匙！', '拿鑰匙！', 28153),
(150353, 'zhTW', '蠢貨！拉茲迦基是派你來送死的！', '', 28153),
(150352, 'zhTW', '', '跟我想的一樣。勇士，你能不能好心幫我們驗證一下呢？', 28153),
(150351, 'zhTW', '有意思，幽光會回應瑪法里恩。但如果森林裡有更多的求救聲呢？', '', 28153),
(150350, 'zhTW', '', '我們沒辦法摧毀幽光…應該說，沒辦法全部摧毀，但是我們也許能打散他們。', 28153),
(150349, 'zhTW', '誰都休想從通戈手中偷東西！', '', 28153),
(150348, 'zhTW', '', '我派去打探瑪法里恩的斥候低估了幽光的力量。他們已經為此付出代價。', 28153),
(150347, 'zhTW', '幽光防線？哼！女王陛下，這種東西只需要黑暗遊俠和石毀車就可以解決了。', '', 28153),
(150346, 'zhTW', '我不會…被擊垮的…', '', 28153),
(150345, 'zhTW', '真弱，沒有能讓無信者認真起來的翼手龍嗎？', '', 28153),
(150344, 'zhTW', '', '很高興見到你！來，讓你疲憊的頭顱靠著休息。', 28153),
(150343, 'zhTW', '', '若你需要任何東西，儘管跟我說！', 28153),
(150342, 'zhTW', '', '歡迎來到我的旅店！來，喝一杯。', 28153),
(150341, 'zhTW', '', '你還好吧，小夥子？進來坐，把這裡當成自己家。', 28153),
(150340, 'zhTW', '', '你看來需要休息一下。請坐，吃點東西！', 28153),
(150339, 'zhTW', '你好，有錢人。這裡是拾荒者神殿，你有帶什麼尖尖又利利的東西過來嗎？', '', 28153),
(150338, 'zhTW', '這裡的艾澤萊晶岩都是我的！', '這裡的艾澤萊晶岩都是我的！', 28153),
(150337, 'zhTW', '', '痛的話要說喲…', 28153),
(150336, 'zhTW', '', '天啊！你真會流血！', 28153),
(150335, 'zhTW', '', '船長！那個什麼偵測到附近有敵人。我要拿出最好的匕首！', 28153),
(150334, 'zhTW', '', '又要撲滅火焰、又要修好爆炸…哼！一群奴隸販子！', 28153),
(150333, 'zhTW', '', '「爆炸」還是很「正常」啊。兩個又沒有衝突！', 28153),
(150332, 'zhTW', '', '船長…一定…會生氣…', 28153),
(150331, 'zhTW', '', '我要來捅你啦！', 28153),
(150330, 'zhTW', '', '唷呼！', 28153),
(150329, 'zhTW', '', '捅人的時候到了！', 28153),
(150328, 'zhTW', '有一點點痛！', '', 28153),
(150327, 'zhTW', '噢，你還真兇啊！', '', 28153),
(150326, 'zhTW', '當魚餌吧你！', '', 28153),
(150325, 'zhTW', '你在看什麼看？', '', 28153),
(150324, 'zhTW', '現在換我…去餵魚了…', '', 28153),
(150323, 'zhTW', '嗯，這座島上的傢伙好像不簡單。看來繞點遠路是值得的。', '', 28153),
(150322, 'zhTW', '我的魚鉤正好缺一條蟲！', '', 28153),
(150321, 'zhTW', '拿他們來當魚餌！', '', 28153),
(150320, 'zhTW', '現在收割旋風！', '', 28153),
(150319, 'zhTW', '', '快！拿桶子給我！千萬不能浪費血啊！', 28153),
(150318, 'zhTW', '', '這島上到處都是人啊，動物啊，東西啊…就連部落都有。去拿點血回來給我！', 28153),
(150317, 'zhTW', '', '好了，大家！拿血來給我…可愛又迷人的血！應該也有你們想要的寶物啦。', 28153),
(150316, 'zhTW', '', '部落的血…我最喜歡了！手下們，都知道該怎麼做吧！', 28153),
(150315, 'zhTW', '', '你好啊。你需要留著全部的血嗎？可以分一點給我啊…', 28153),
(150314, 'zhTW', '', '這些鮮血…都浪費了…', 28153),
(150313, 'zhTW', '', '快殺掉他們！我要鮮血！', 28153),
(150312, 'zhTW', '', '把血交出來！', 28153),
(150311, 'zhTW', '', '全部殺光！', 28153),
(150310, 'zhTW', '啊！哈哈哈！', '', 28153),
(150309, 'zhTW', '嘻嘻嘻！', '', 28153),
(150308, 'zhTW', '聯…盟…的傢伙！出來玩囉！', '', 28153),
(150307, 'zhTW', '嗨！', '', 28153),
(150306, 'zhTW', '呵…呵呵…', '', 28153),
(150305, 'zhTW', '別動！', '', 28153),
(150304, 'zhTW', '『賊賊』彼特！', '', 28153),
(150303, 'zhTW', '『賊賊』彼特！', '', 28153),
(150302, 'zhTW', '『賊賊』彼特！', '', 28153),
(150301, 'zhTW', '不要再戳我了！', '', 28153),
(150300, 'zhTW', '喂，很癢耶！', '', 28153),
(150299, 'zhTW', '我轟死你！', '', 28153),
(150298, 'zhTW', '哈！逮到你了！', '', 28153),
(150297, 'zhTW', '大聲念出符文的內容。', '大聲念出符文的內容。', 28153),
(150295, 'zhTW', '帶我飛往黃金王座。', '帶我飛往黃金王座。', 28153),
(150294, 'zhTW', '', '勇士，在我找出方法對付幽光之前，必須想辦法轉移那些卡多雷的注意力。', 28153),
(150293, 'zhTW', '', '嗯，幽光散開了？很好，計畫看來是行得通…', 28153),
(150292, 'zhTW', '', '我的巨魔像會把你撕成碎片！你再怎麼抵抗都沒有用！', 28153),
(150291, 'zhTW', '', '趕快，把路障解決掉！', 28153),
(150290, 'zhTW', '', '上啊！我的寵物！把他們撕爛！', 28153),
(150289, 'zhTW', '', '各位勇士，跟我來。讓我邀請你一起欣賞這場華麗的結局。', 28153),
(150288, 'zhTW', '', '說不定，你還能跟兒子打聲招呼呢。', 28153),
(150287, 'zhTW', '', '想光榮戰死沙場就去吧，薩魯法爾。在我看來就只是隨便捨棄生命而已。也許我會再把你的屍體喚醒，繼續服侍我。', 28153),
(150286, 'zhTW', '', '或許你認為，只要死得光榮，犧牲生命也無所謂。但是對我而言，延續部落才是最重要的。凡是不認同這個理念的，都不配站在這裡。', 28153),
(150285, 'zhTW', '', '薩魯法爾，榮譽對屍體根本沒有意義。你對死亡的理解貧乏輕率，但我不同，我太熟悉死亡了。', 28153),
(150284, 'zhTW', '要相信大酋長的策略，塞隆。', '', 28153),
(150283, 'zhTW', '虛無精靈…一定要處理掉那些叛徒！', '', 28153),
(150282, 'zhTW', '羅德隆屬於被遺忘者！千萬不要退縮！', '', 28153),
(150281, 'zhTW', '穩住陣腳，他們的攻勢很快就會停止了！', '', 28153),
(150280, 'zhTW', '勇士們，聯盟快要不行了！他們已經只剩下一半的兵力了。', '', 28153),
(150279, 'zhTW', '哈哈哈！看看是誰來了。太好了，我才正在怕會無聊呢！', '', 28153),
(150278, 'zhTW', '到時候她自己會跟你說。快去吧！', '', 28153),
(150277, 'zhTW', '你們打算撐到什麼時候？大酋長的計畫到底是什麼？', '', 28153),
(150276, 'zhTW', '不行。我和洛索瑪來對付入侵者。大酋長必須有人守護。你不許離開她身邊。', '', 28153),
(150275, 'zhTW', '知道了。我會盡快和你會合。', '', 28153),
(150274, 'zhTW', '逼敵人穿過城堡側面，他們就沒辦法利用人數取得優勢。', '', 28153),
(150273, 'zhTW', '沒時間了！再過不久，我們就會失去地形優勢！', '', 28153),
(150272, 'zhTW', '遵命，凋零者。可是…薩魯法爾在哪裡？', '', 28153),
(150271, 'zhTW', '貝恩！召集投石車和所有的藥劑師。立刻派他們前往城堡！', '', 28153),
(150270, 'zhTW', '知道了，凋零者。', '', 28153),
(150269, 'zhTW', '洛索瑪，你去指揮遊俠從側翼包抄！叫他們到屋頂上就位！', '', 28153),
(150268, 'zhTW', '荒疫投擲部隊，你們是第一線！你們要讓敵人跟我們之間，佈滿荒疫！', '', 28153),
(150267, 'zhTW', '遵命，女王。', '', 28153),
(150266, 'zhTW', '', '去找洛索瑪。快一點！納薩諾斯，別讓我失望！', 28153),
(150265, 'zhTW', '防毒面具！快來拿防毒面具喔！如果你還想來點刺激的，就拿一個背包開工去！', '', 28153),
(150264, 'zhTW', '光榮奮戰，英雄們！Lok-Narash！', '', 28153),
(150263, 'zhTW', '', '勇士，把他們全殺了！聽好了，安杜因不是帶軍隊來陪我們玩的，而是要摧毀部落！千萬別手下留情，敵人也不會！', 28153),
(150262, 'zhTW', '部落的士兵！你們的兄弟姊妹還被困在戰場上！如果拋下自己人，就算是戰勝也不光榮！', '', 28153),
(150261, 'zhTW', 'Lok\'tar ogar!', '', 28153),
(150260, 'zhTW', '聯盟人多勢眾，但是我們更強大。我們是部落！我們會擊垮想打倒我們的敵人！', '', 28153),
(150259, 'zhTW', '各位勇士！大酋長已經下命令了！舉起武器，對抗聯盟的時候到了！', '', 28153),
(150258, 'zhTW', '', '那就來結束這一切吧。薩魯法爾，你來率領部隊，我去準備艾澤萊晶岩戰爭機器。', 28153),
(150257, 'zhTW', '是的，大酋長。', '', 28153),
(150256, 'zhTW', '快一點！大酋長在等！', '', 28153),
(150255, 'zhTW', '跟我一起向前！我們必須趁部落措手不及，繼續推進！', '', 28153),
(150254, 'zhTW', '他招來狂風，但我們比風更強大！勇士，撐下去啊！', '', 28153),
(150253, 'zhTW', '沒那麼快！', '', 28153),
(150252, 'zhTW', '', '快一點！我的寒冰之牆沒辦法撐太久！', 28153),
(150251, 'zhTW', '英雄們！先把火力集中在敵方援軍身上，晚一點再來處理那些薩滿！', '', 28153),
(150250, 'zhTW', '大酋長…會…阻止你…', '', 28153),
(150249, 'zhTW', '雄鷹之魂的狂風會讓你粉身碎骨！', '', 28153),
(150248, 'zhTW', '', '', 28153),
(150246, 'zhTW', '嘎啊。', '', 28153),
(150245, 'zhTW', '嘎啊啊啊！', '', 28153),
(150244, 'zhTW', '嘶嘎！', '', 28153),
(150242, 'zhTW', '這本書的書頁寫滿了充滿魔法的符文。', '這本書的書頁寫滿了充滿魔法的符文。', 28153),
(150241, 'zhTW', '我可以殺他們了嗎？你說過可以殺的。', '', 28153),
(150240, 'zhTW', '幹嘛？！', '', 28153),
(150239, 'zhTW', '去找你自己的盒子，你這愛搶的$r！', '不行，這個盒子是我的！\n\n我是來這裡找蟲煮湯。有幾個托爾托說用海蟹煮湯非常美味，可是我不和托爾托打交道的。我不想為了海蟹湯就去和陌生人交朋友。\n\n靠泥蟲湯可以建立起維持一輩子的友誼，而我們托爾托的一輩子很長。\n\n你幫我找泥蟲肉，我就考慮把這個箱子給你。', 28153),
(150238, 'zhTW', '好…痛…', '', 28153),
(150237, 'zhTW', '啊啊啊啊！', '', 28153),
(150236, 'zhTW', '在你拿出武器前，先聽我說完…', '', 28153),
(150235, 'zhTW', '', '搜搜看這傢伙身上有沒有錢。', 28153),
(150234, 'zhTW', '', '這座島上的寶藏怎麼還沒放在我的船上。動作快，你們這些懶鬼！把聯盟的東西也都拿來！', 28153),
(150233, 'zhTW', '', '我看到這裡有聯盟的人，而且都還有呼吸。把他們解決掉。', 28153),
(150232, 'zhTW', '', '快來島上大搶特搶。動作快！我這個人最討厭等了。', 28153),
(150231, 'zhTW', '', '啊？', 28153),
(150230, 'zhTW', '', '財寶…不能…放手…', 28153),
(150229, 'zhTW', '', '夠了，馬上殺掉他們！', 28153),
(150228, 'zhTW', '', '等你死了，要搶錢就方便了。', 28153),
(150227, 'zhTW', '', '我聽過聯盟有很多不好的事，離他們遠一點好了。', 28153),
(150226, 'zhTW', '', '這很有幫助。', 28153),
(150225, 'zhTW', '', '我來幫你吧。', 28153),
(150224, 'zhTW', '', '你好啊。', 28153),
(150223, 'zhTW', '', '我…是…對的。', 28153),
(150222, 'zhTW', '', '糟糕，他們來了。', 28153),
(150221, 'zhTW', '看來撤退可能會比較好。', '', 28153),
(150220, 'zhTW', '受夠你了。', '', 28153),
(150219, 'zhTW', '最好小心一點，聯盟。不然我只好對你們不客氣了。', '', 28153),
(150218, 'zhTW', '喲。', '', 28153),
(150217, 'zhTW', '夸風狼吞虎嚥，食物碎屑到處亂噴。', '', 28153),
(150216, 'zhTW', '聖光…我會…回來的…', '', 28153),
(150215, 'zhTW', '釋放你的怒火！', '', 28153),
(150214, 'zhTW', '我沒時間陪你玩！', '', 28153),
(150213, 'zhTW', '', '待著別動。', 28153),
(150212, 'zhTW', '', '動作慢一點。', 28153),
(150211, 'zhTW', '', '你的時候到了。', 28153),
(150210, 'zhTW', '', '土歸土。', 28153),
(150209, 'zhTW', '', '風引領我們來到這裡…也把聯盟帶來了。有時候，元素也會做出讓人意外的事。', 28153),
(150208, 'zhTW', '', '聽好了，聯盟。我們井水不犯河水。', 28153),
(150207, 'zhTW', '', '這裡的元素已經失去了平衡。看看我們能做些什麼，別讓聯盟來攪局。', 28153),
(150206, 'zhTW', '', '什麼風把你吹來了？', 28153),
(150205, 'zhTW', '', '我的靈魂…會…回來的…', 28153),
(150204, 'zhTW', '', '你快讓我失去耐性了。', 28153),
(150203, 'zhTW', '', '元素，幫助我們。', 28153),
(150202, 'zhTW', '', '治療就交給我吧。', 28153),
(150201, 'zhTW', '', '聖光照耀著你！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150200, 'zhTW', '', '我不喜歡奪取生命。', 28153),
(150199, 'zhTW', '', '小心…敵人就在附近。我們盡可能避開吧。', 28153),
(150198, 'zhTW', '<給予|TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[給予特大號恐龍食物]|h|r>', '<給予|TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[給予特大號恐龍食物]|h|r>', 28153),
(150197, 'zhTW', '', '聖光歡迎你！', 28153),
(150196, 'zhTW', '', '我…要回歸聖光了…', 28153),
(150195, 'zhTW', '<夸風不耐煩地動了動嘴。>\n\n嘎啊！', '', 28153),
(150194, 'zhTW', '', '快投降！沒必要白白送死！', 28153),
(150193, 'zhTW', '<夸風聞了聞你的味道。>\n\n嗄啊。', '', 28153),
(150192, 'zhTW', '你確定你要做這件事嗎？它對故事線完全沒有影響，除了給你成就感。', '你確定你要做這件事嗎？它對故事線完全沒有影響，除了給你成就感。', 28153),
(150191, 'zhTW', '敵人很強大！', '', 28153),
(150190, 'zhTW', '聖光判你有罪！', '', 28153),
(150189, 'zhTW', '大酋長想要嚇跑幽光，是嗎？我剛好有適合的東西。\n\n你想要駕駛這個東西？還是想負責丟炸彈？', '', 28153),
(150188, 'zhTW', '聖光照耀著此處。這裡艾澤萊晶岩不少。', '', 28153),
(150187, 'zhTW', '我依然在試著為這東西挪出空間。我們或許需要清掉一些樹木，或是拿一個我能讓它發出亮光的樹木物件。\n\n假裝這很驚人，幽光從牆壁衝出來，在你轟炸的地方造成可見的裂縫。', '我依然試著為這東西挪出空間，我們或許需要清掉一些樹木，或是拿一個我能讓它發出亮光的樹木物件。假裝這很驚人，幽光從牆壁衝出來，在你轟炸的地方造成可見的裂縫。', 28153),
(150186, 'zhTW', '讓我們飛吧。', '讓我們飛吧。', 28153),
(150185, 'zhTW', '我能飛。讓樹林起火不是我的風格。', '我能飛。讓樹林起火不是我的風格。', 28153),
(150184, 'zhTW', '聖光與你同在。', '', 28153),
(150183, 'zhTW', '你打得…很好…', '', 28153),
(150181, 'zhTW', '聖光擊潰我的敵人！', '', 28153),
(150180, 'zhTW', '為了聖光！', '', 28153),
(150179, 'zhTW', '', '動作慢一點。', 28153),
(150178, 'zhTW', '', '給我後退。', 28153),
(150177, 'zhTW', '', '做個了結吧！', 28153),
(150176, 'zhTW', '', '我們勝利了！', 28153),
(150175, 'zhTW', '', '這真是場冒險！未知的島嶼，未知的危險，還有未知的寶藏！不會吧，那是部落嗎？', 28153),
(150174, 'zhTW', '', '看看前方會有什麼冒險等著我們。我們要做的就是先擺脫部落。', 28153),
(150173, 'zhTW', '', '黑暗的子民，你們必敗無疑！聖光制裁者會消滅你們！', 28153),
(150172, 'zhTW', '', '朋友，你好。', 28153),
(150171, 'zhTW', '', '聖光…會給我救贖…', 28153),
(150170, 'zhTW', '', '你不是我們的對手！', 28153),
(150169, 'zhTW', '<夸風發出叫聲，向你打招呼。>\n\n嗄啊！', '', 28153),
(150168, 'zhTW', '<夸風充滿活力地朝著你的方向搖晃腦袋。>', '', 28153),
(150166, 'zhTW', '<夸風龍對你發出想玩的叫聲。>', '', 28153),
(150165, 'zhTW', '', '把這傢伙的靈魂交給虛無吧！', 28153),
(150164, 'zhTW', '<夸風隨著你靠近歪了歪頭。>\n\n嗄啊？', '', 28153),
(150163, 'zhTW', '', '為了虛無！', 28153),
(150162, 'zhTW', '', '這裡，就是這裡，跟那個聲音說的一樣！沒錯！哈哈哈！就是這樣。', 28153),
(150161, 'zhTW', '', '什麼？是誰在說話？', 28153),
(150160, 'zhTW', '', '嘿嘿嘿嘿…我要前往虛無了…', 28153),
(150159, 'zhTW', '', '盡量吃，寵物們！', 28153),
(150158, 'zhTW', '', '這正是虛無想要的靈魂！', 28153),
(150157, 'zhTW', '嚐嚐混亂的滋味吧！', '', 28153),
(150156, 'zhTW', '可悲。', '', 28153),
(150155, 'zhTW', '部落那些野蠻的傢伙到了。哼，他們根本不可能對抗虛無。', '', 28153),
(150154, 'zhTW', '狗頭人與地下城！', '狗頭人與地下城！', 28153),
(150153, 'zhTW', '狗頭人與地下城…', '狗頭人與地下城…', 28153),
(150152, 'zhTW', '你追求財富，卻要葬送此生…', '你追求財富，卻要葬送此生…', 28153),
(150151, 'zhTW', '這輩子恐怕你都無法逃出～！', '這輩子恐怕你都無法逃出～！', 28153),
(150150, 'zhTW', '虛無，幫助我！', '', 28153),
(150149, 'zhTW', '前方沒出路，後面是怪物，', '前方沒出路，後面是怪物，', 28153),
(150148, 'zhTW', '這瘋狂的追逐，還有怪物獵捕，想要逃命要努力跟著地圖！', '這瘋狂的追逐，還有怪物獵捕，想要逃命要努力跟著地圖！', 28153),
(150147, 'zhTW', '擁抱虛無吧！', '', 28153),
(150146, 'zhTW', '要是你偷蠟燭，最好加快腳步，躲開那沿途機關密佈！', '要是你偷蠟燭，最好加快腳步，躲開那沿途機關密佈！', 28153),
(150145, 'zhTW', '你不能拿蠟燭！', '你不能拿蠟燭！', 28153),
(150144, 'zhTW', '你不能拿蠟燭！', '你不能拿蠟燭！', 28153),
(150143, 'zhTW', '寶藏很豐富，只有這個別碰觸…', '寶藏很豐富，只有這個別碰觸…', 28153),
(150142, 'zhTW', '小心進入，那寶藏就在此處，儘管拿你心中想要的財富！', '小心進入，那寶藏就在此處，儘管拿你心中想要的財富！', 28153),
(150141, 'zhTW', '有許多寶物，和危險旅途，地下通道它也不太牢固。', '有許多寶物，和危險旅途，地下通道它也不太牢固。', 28153),
(150140, 'zhTW', '歡迎你們。', '', 28153),
(150139, 'zhTW', '前進地下的大洞窟。', '前進地下的大洞窟。', 28153),
(150138, 'zhTW', '啊…黑暗…環繞著我…', '', 28153),
(150137, 'zhTW', '真是一群可憐蟲。等著被生吞活剝吧。', '', 28153),
(150136, 'zhTW', '有膽子就來吧。', '', 28153),
(150135, 'zhTW', '高手在此處，開始出任務，', '高手在此處，開始出任務，', 28153),
(150134, 'zhTW', '有著無數寶藏，靜靜等待…厲害的冒險者…', '有著無數寶藏，靜靜等待…厲害的冒險者…', 28153),
(150133, 'zhTW', '我可以擺出勝利姿勢了嗎？要先殺他們才可以？噢，那好吧。', '', 28153),
(150132, 'zhTW', '傳說中，有個巨大的地下城…', '傳說中，有個巨大的地下城…', 28153),
(150131, 'zhTW', '是！', '是！', 28153),
(150130, 'zhTW', '噢，看到我一定很開心吧！想想被我殺掉的感覺吧！', '', 28153),
(150129, 'zhTW', '部落的船艦！真是等不及想看看他們發現我們也在這裡的表情了。', '', 28153),
(150128, 'zhTW', '小朋友，大家要不要來唱歌啊？', '小朋友，大家要不要來唱歌啊？', 28153),
(150127, 'zhTW', '嘻嘻', '嘻嘻', 28153),
(150126, 'zhTW', '歡迎！', '', 28153),
(150125, 'zhTW', '哈哈！', '哈哈！', 28153),
(150124, 'zhTW', '在這裡！', '', 28153),
(150123, 'zhTW', '怎麼了？跟不上嗎？', '', 28153),
(150122, 'zhTW', '耶！', '耶！', 28153),
(150121, 'zhTW', '抓住他們！', '抓住他們！', 28153),
(150120, 'zhTW', '呃，居然就這麼剛好…', '', 28153),
(150119, 'zhTW', '天啊！', '天啊！', 28153),
(150118, 'zhTW', '就是我！別擔心，我會好好對待你。', '', 28153),
(150117, 'zhTW', '你好啊，部落。我是克萊恩。沒想到會遇到你們。', '', 28153),
(150116, 'zhTW', '', '消失吧，臭蟲！', 28153),
(150115, 'zhTW', '如果你遇上葛斯拉克，不用遲疑，一刀刺進他的黑心。', '', 28153),
(150114, 'zhTW', '', '出身低賤的雜碎！', 28153),
(150113, 'zhTW', '', '你的血噴到我了！請你小心一點！', 28153),
(150112, 'zhTW', '', '真是倒楣啊，你們這些聯盟。看我怎麼教訓你們。', 28153),
(150111, 'zhTW', '葛斯拉克是罪有應得，希望他死前痛苦不堪。', '', 28153),
(150110, 'zhTW', '', '真討厭！這樣好粗魯。', 28153),
(150109, 'zhTW', '我會死在這片沙丘…這是我應得的下場。', '', 28153),
(150108, 'zhTW', '', '嘖嘖。我來處理吧。', 28153),
(150107, 'zhTW', '', '噢，是你啊。哈囉。', 28153),
(150106, 'zhTW', '', '真是完全…提不起勁啊…', 28153),
(150105, 'zhTW', '', '手套戴上！可不能把手弄髒了。', 28153),
(150104, 'zhTW', '', '先解決這個弱的！', 28153),
(150103, 'zhTW', '', '太棒了！你們看到了嗎？', 28153),
(150102, 'zhTW', '', '快啦，我們下船吧。沒有時間了啦！快快快！', 28153),
(150101, 'zhTW', '', '為什麼我被困在這裡，不能出去打架啊？', 28153),
(150100, 'zhTW', '拿到監督者的鑰匙之後，就能救出這次的目標，把他們的能力化為我們的優勢。', '', 28153),
(150099, 'zhTW', '', '哈哈！想得美！', 28153),
(150098, 'zhTW', '', '太慢了！', 28153),
(150097, 'zhTW', '黑暗女王一定會很高興的。', '', 28153),
(150096, 'zhTW', '', '不…不公平！你們…最討厭了…', 28153),
(150095, 'zhTW', '', '大家上啊！', 28153),
(150094, 'zhTW', '', '你別想從我手裡逃走！', 28153),
(150093, 'zhTW', '快！殺掉這個傢伙！', '', 28153),
(150092, 'zhTW', '無法避免的命運。', '', 28153),
(150091, 'zhTW', '去拿他的鑰匙，找到我們的目標。把擋路的人全都殺掉。', '', 28153),
(150090, 'zhTW', '時候到了。記住你學到的東西，讓這些聯盟的傢伙知道精靈貴族的厲害。', '', 28153),
(150089, 'zhTW', '想辦法到頂樓去，監督者就在那裡。', '', 28153),
(150088, 'zhTW', '集中精神，附近有強大的敵人，聯盟也來了。', '', 28153),
(150087, 'zhTW', '最近發生的越獄，在監獄下層引起一陣混亂。我們可以好好利用這一點。', '', 28153),
(150086, 'zhTW', '聯盟也在這裡。趕快引導你的力量，我們絕對不能出錯。', '', 28153),
(150085, 'zhTW', '我們的目標就在托達戈爾。', '', 28153),
(150084, 'zhTW', '你好啊。', '', 28153),
(150083, 'zhTW', '動作快…撤退…', '', 28153),
(150082, 'zhTW', '照計畫進行！應戰！', '', 28153),
(150081, 'zhTW', '打倒他們！聽我指揮！', '', 28153),
(150080, 'zhTW', '噢！噢噢噢噢，是首要目標！', '', 28153),
(150079, 'zhTW', '我殺掉一個了！我殺掉一個了！', '', 28153),
(150078, 'zhTW', '部落也在這裡？你們確定？我有一些精密的儀器。這些東西可是很貴的。', '', 28153),
(150077, 'zhTW', '哈囉！', '', 28153),
(150076, 'zhTW', '我一直都是對的…你們…這些混蛋…', '', 28153),
(150075, 'zhTW', '$n已完全充能！', '$n已完全充能！', 28153),
(150074, 'zhTW', '$n開始散發出能量！', '$n開始散發出能量！', 28153),
(150073, 'zhTW', '走開！', '', 28153),
(150072, 'zhTW', '$n的能量再次提高…', '$n的能量再次提高…', 28153),
(150071, 'zhTW', '噢，我…我…不知道是不是真的要這樣！', '', 28153),
(150070, 'zhTW', '$n的能量提升…', '$n的能量提升…', 28153),
(150069, 'zhTW', '', '快治療！', 28153),
(150068, 'zhTW', '一個混沌火花衝進戰場！', '一個混沌火花衝進戰場！', 28153),
(150067, 'zhTW', '', '消滅目標了。', 28153),
(150066, 'zhTW', '一個能量之核在附近形成。', '一個能量之核在附近形成。', 28153),
(150065, 'zhTW', '', '部落出場，子彈上膛！先把敵人清光，待會再來搜刮。', 28153),
(150064, 'zhTW', '', '要及時行樂喔。', 28153),
(150063, 'zhTW', '', '我要撤退了。', 28153),
(150062, 'zhTW', '一個由純粹能量組成的生物憑空出現在你面前！', '一個由純粹能量組成的生物憑空出現在你面前！', 28153),
(150061, 'zhTW', '', '嗚…好痛…', 28153),
(150060, 'zhTW', '', '注意敵人的行動。', 28153),
(150059, 'zhTW', '', '對準頭部，那裡就是弱點！', 28153),
(150058, 'zhTW', '該殺死這些畜生了。', '', 28153),
(150057, 'zhTW', '別想用刀劍跟機械打。', '', 28153),
(150056, 'zhTW', '我的機器被摧毀了！快撤退！', '', 28153),
(150055, 'zhTW', '機械陸行鳥被毀了！快點救我出去！', '', 28153),
(150054, 'zhTW', '踩扁了。', '', 28153),
