(150041, 'zhTW', '哇哈哈，砰！', '', 28153),
(150040, 'zhTW', '把刀子磨利點，有屍體需要我們處理。走吧，靜悄悄、慢慢來。', '', 28153),
(150039, 'zhTW', '你要做什麼？', '', 28153),
(150038, 'zhTW', '太遲了！', '', 28153),
(150037, 'zhTW', '哈…你什麼都…不是…', '', 28153),
(150036, 'zhTW', '小心了，聯盟。', '', 28153),
(150035, 'zhTW', '', '我們的人民對塔蘭姬提議的改變感到害怕，人們在害怕時會做出愚蠢的事。', 28153),
(150034, 'zhTW', '', '所有大砲，準備開火！', 28153),
(150033, 'zhTW', '', '我玩膩了。我要把波拉勒斯化成灰燼，你們根本別想獲勝！', 28153),
(150032, 'zhTW', '', '你竟敢傷害我漂亮的寵物？！                                                                                                                                                                         ', 28153),
(150031, 'zhTW', '', '接下來輪到這一個。', 28153),
(150030, 'zhTW', '', '一切都按計畫進行。', 28153),
(150029, 'zhTW', '', '我把路線全都計畫好了。這個計畫大膽又有效，就這麼做。聽我的就對了。', 28153),
(150028, 'zhTW', '', '你的護甲不錯。但尖刺再多一點會更好。', 28153),
(150027, 'zhTW', '', '我們不會…退縮的…', 28153),
(150026, 'zhTW', '', '放電！', 28153),
(150025, 'zhTW', '', '為了庫爾提拉斯！', 28153),
(150024, 'zhTW', '', '看來你們的計畫不怎麼樣嘛！', 28153),
(150023, 'zhTW', '重新開張囉!', '', 28153),
(150022, 'zhTW', '該來大砍特砍啦！', '', 28153),
(150021, 'zhTW', '喂！要修理那個很貴耶！', '', 28153),
(150020, 'zhTW', '', '攻破他們的大門了！入侵城市，殺光所有反抗我的人！', 28153),
(150019, 'zhTW', '真是沒用的垃圾。', '', 28153),
(150018, 'zhTW', '哈哈哈！噱翻了！', '', 28153),
(150017, 'zhTW', '這地方真不錯！有綠蔭、財寶、還有…聯盟？可惡，這地方爛透了。', '', 28153),
(150016, 'zhTW', '我們眼前出現了絕佳的投資機會。也許這些聯盟狗還可以秤斤當廢料賣！', '', 28153),
(150015, 'zhTW', '', '我就來讓你們看看吧。', 28153),
(150014, 'zhTW', '', '慶祝空虛的勝利吧，蠢貨！沒有庫爾提拉斯艦隊，你們根本不可能擊敗我。', 28153),
(150013, 'zhTW', '聞到了嗎？那就是利潤的氣味，而且濃到不行。把袋子拿好！', '', 28153),
(150012, 'zhTW', '怎麼啦？', '', 28153),
(150011, 'zhTW', '我還能…捲土重來…', '', 28153),
(150010, 'zhTW', '', '你做到了！這下艾胥凡沒了巨人，一定能把他們趕出這座城市。', 28153),
(150009, 'zhTW', '這個寶貝就是為此打造的！', '', 28153),
(150008, 'zhTW', '啟動殺戮模式。', '', 28153),
(150007, 'zhTW', '快點上啊！', '', 28153),
(150006, 'zhTW', '唉呀，看來是我太用力了。', '', 28153),
(150005, 'zhTW', '已經到了嗎？可是這時候正適合好好睡一覺耶。', '', 28153),
(150004, 'zhTW', '停止戰鬥的話，我就不用做這種事了。', '', 28153),
(150003, 'zhTW', '會有人幫你舔傷口的。', '', 28153),
(150002, 'zhTW', '吼嗚…你好！', '', 28153),
(150001, 'zhTW', '終於…可以睡了…', '', 28153),
(150000, 'zhTW', '休息一下吧！', '', 28153),
(149999, 'zhTW', '快逃吧，部落的傢伙。我們不會追上去的！', '', 28153),
(149998, 'zhTW', '', '你是獵人…的獵物！', 28153),
(149997, 'zhTW', '', '看來我需要新的獵物了！', 28153),
(149996, 'zhTW', '', '嗯…空氣中瀰漫獵物的氣味。還是要先有狩獵才刺激！', 28153),
(149995, 'zhTW', '', '你聞起來怪怪的。', 28153),
(149994, 'zhTW', '', '啊…鮮血的味道…真好…', 28153),
(149993, 'zhTW', '', '下一個…就換你！', 28153),
(149992, 'zhTW', '', '瞄準敵人喉嚨！', 28153),
(149991, 'zhTW', '做得好，勇士！多虧有你，這裡總算是安全了。', '', 28153),
(149990, 'zhTW', '大開殺戒！', '', 28153),
(149989, 'zhTW', '這樣他們就知道贊達拉的厲害了！', '', 28153),
