(149987, 'zhTW', '這還真好玩！', '', 28153),
(149986, 'zhTW', '是部落！把他們解決掉。狩獵開始了！*嗥叫*', '', 28153),
(149985, 'zhTW', '我們的間諜發現這個區域有個大威脅。想辦法找出來，把它消滅！', '', 28153),
(149984, 'zhTW', '*嗅嗅*是部落！真希望我是在上風處…', '', 28153),
(149983, 'zhTW', '', '這無所謂，我的大砲會把所有反抗勢力解決掉！', 28153),
(149982, 'zhTW', '跟著大家走別亂跑。我聞到邪惡的氣息。', '', 28153),
(149981, 'zhTW', '*吼叫*', '', 28153),
(149980, 'zhTW', '你阻止不了…我這種瘋狗…', '', 28153),
(149979, 'zhTW', '他會為他的所做所為後悔的！Di chuka 瑞贊！', '', 28153),
(149978, 'zhTW', '把他們撕成碎片！', '', 28153),
(149977, 'zhTW', '*嗥叫* 狼群，攻擊！', '', 28153),
(149976, 'zhTW', '', '耶！這個頭我要了，哈哈哈！', 28153),
(149975, 'zhTW', '', '哇嗚，這座島真是充滿希望。給我走開，我還有巫毒術要忙。', 28153),
(149974, 'zhTW', '', '我來幫你治療。', 28153),
(149973, 'zhTW', '', '你的頭滿好看的！等你死了可以留給我嗎？', 28153),
(149972, 'zhTW', '', '呃，暗矛食人妖…絕對不死…', 28153),
(149971, 'zhTW', '', '看我的妖術！', 28153),
(149970, 'zhTW', '', '末日來襲！', 28153),
(149969, 'zhTW', '', '你這傢伙，我要縮小你的頭！', 28153),
(149968, 'zhTW', '先殺這傢伙。', '', 28153),
(149967, 'zhTW', '逮到你了。', '', 28153),
(149966, 'zhTW', '這座島很不錯，不知道今天會有什麼新發現。', '', 28153),
(149965, 'zhTW', '什麼事？', '', 28153),
(149964, 'zhTW', '只是…稍微躺一下…', '', 28153),
(149963, 'zhTW', '睡一下吧！', '', 28153),
(149962, 'zhTW', '這些傢伙是從哪來的？來這裡做什麼？', '', 28153),
(149961, 'zhTW', '', '啊啊啊啊！', 28153),
(149960, 'zhTW', '', '更多的血！', 28153),
(149959, 'zhTW', '', '來啊！多來一點啊！', 28153),
(149958, 'zhTW', '', '團隊…策略…我呸！殺就對了！殺啊啊啊！', 28153),
(149957, 'zhTW', '', '是聯盟！殺光他們！把心臟挖出來給我…', 28153),
(149956, 'zhTW', '', '快把他們的手腳全都扯斷！血會流得到處都是！哈哈哈哈！', 28153),
(149955, 'zhTW', '', '怎樣？', 28153),
(149954, 'zhTW', '', '我…可是光榮戰死！*呸*', 28153),
(149953, 'zhTW', '', '把他們的手扯斷！', 28153),
(149952, 'zhTW', '想我了嗎？', '', 28153),
(149951, 'zhTW', '別動！', '', 28153),
(149950, 'zhTW', '嘿…你好啊。', '', 28153),
(149949, 'zhTW', '做得…好…', '', 28153),
(149948, 'zhTW', '我又殺了一個！絕對是我領先。', '', 28153),
(149947, 'zhTW', '我們開始吧！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149946, 'zhTW', '你得先去買張新的臉。', '你得先去買張新的臉。', 28153),
(149945, 'zhTW', '', '看得出你的眼神有一絲猶豫，$n。\n\n我准許你詢問我有關計畫的問題，如果你想知道的話。', 28153),
(149944, 'zhTW', '大酋長，我可以問為什麼我們要抓泰達希爾嗎？', '大酋長，我可以問為什麼我們要抓泰達希爾嗎？', 28153),
(149943, 'zhTW', '機會？', '機會？', 28153),
(149942, 'zhTW', '這還不確定，大酋長。', '這還不確定，大酋長。', 28153),
(149940, 'zhTW', '', '可以確定的是，聯盟會把達納蘇斯視為避風港，好讓他們得以將艾澤萊晶岩運往東部王國。安杜因‧烏瑞恩會打造強大的武器，而且或早或晚都會對我們的家園發動攻擊。他會先襲擊幽暗城和銀月城，然後向卡林多進軍。\n\n為了部落的未來著想，我們一定要先發制人。\n\n只要佔領達納蘇斯，我們就能控制艾澤萊晶岩的去向，並且確保這些資源不會被敵人用來對付我們。聯盟的人絕對不敢攻擊他們自己的城市，他們唯恐傷及平民。\n\n只要發動這一擊，我們就能確保世世代代的和平。', 28153),
(149939, 'zhTW', '', '我們沒有多少時間了，不過我敬佩你想深入探究的精神。\n\n<希瓦娜斯指著地圖上的希利蘇斯>。\n\n這裡永遠改變了艾澤拉斯大地上力量的平衡。\n\n我們在世界各地都找到了艾澤萊晶岩礦點，$n。雖然還無法完全了解艾澤萊晶岩的力量，但我們知道這種物質具有毀天滅地的強大力量。\n\n二十年後的戰爭會是什麼面貌？或者一百年後呢？\n\n要是聯盟掌控了艾澤萊晶岩這項資源，部落要怎麼保衛自己的疆域不受敵人侵犯？', 28153),
(149938, 'zhTW', '', '你有問題要問我嗎，$n？', 28153),
(149937, 'zhTW', '無信者把野獸關在附近的獸欄裡面，看起來是個好機會。', '', 28153),
(149936, 'zhTW', '看來部落也到這裡來了。這下事情會變得…很有趣。', '', 28153),
(149935, 'zhTW', '不要動手動腳，好嗎？', '', 28153),
(149934, 'zhTW', '解決他們！', '', 28153),
(149933, 'zhTW', '你好啊，甜心。', '', 28153),
(149932, 'zhTW', '打得好…以後…再見…', '', 28153),
(149931, 'zhTW', '哈！我又殺了一個！', '', 28153),
(149930, 'zhTW', '我可是準備好了！', '', 28153),
(149929, 'zhTW', '雖然這些武器能讓我們擁有更為強大的優勢。', '', 28153),
(149928, 'zhTW', '喜歡我的新翅膀嗎？或許它們很快，但沒有黏液能夠躲過我！$b$b惡棍也是。$b$b$b$b骯髒的惡棍。', '', 28153),
(149927, 'zhTW', '贊達拉的黏液很怪，天殺的太鹹了，而且它們有時候會回嘴。', '', 28153),
(149926, 'zhTW', '部落來了！終於能大打一場。看來我該脫上衣了！', '', 28153),
(149925, 'zhTW', '夸風發出開心的尖嘯，一口吞下獻上的食物。', '', 28153),
(149924, 'zhTW', '夸風先嗅了嗅食物，然後開始大快朵頤。', '', 28153),
(149923, 'zhTW', '夸風在空中把食物奪走。', '', 28153),
(149922, 'zhTW', '夸風衝向獻上的食物，整個吞下。', '', 28153),
(149921, 'zhTW', '神秘和神聖都有許多秘密，你有你的，我有我的。', '', 28153),
(149920, 'zhTW', '嘎？', '', 28153),
(149919, 'zhTW', '嘎啊啊！', '', 28153),
(149918, 'zhTW', '嗄啊！', '', 28153),
(149917, 'zhTW', '嘶嘎。', '', 28153),
(149916, 'zhTW', '會飛的猴人？怎麼可能？', '會飛的猴人？怎麼可能？', 28153),
(149915, 'zhTW', '撤退也是一種策略！', '', 28153),
(149914, 'zhTW', '讓我來治療！', '', 28153),
(149913, 'zhTW', '你好啊。你是來見習的嗎？', '', 28153),
(149912, 'zhTW', '我們的補給品並不充裕，但我可以分一點東西給你。如果你幫助我們，或許我可以考慮給你一些好東西。', '我們的補給品並不充裕，但我可以分一點東西給你。如果你幫助我們，或許我可以考慮給你一些好東西。', 28153),
(149911, 'zhTW', '<給予|TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[天然放養恐龍飼料]|h|r>', '<給予|TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[天然放養恐龍飼料]|h|r>', 28153),
(149910, 'zhTW', '我們的地點最好，寶藏就在這裡。', '我們的地點最好，寶藏就在這裡。', 28153),
(149909, 'zhTW', '你還沒看到…最厲害的…我…', '', 28153),
(149908, 'zhTW', '<夸風看著你的手，尋找食物。>\n\n嗄啊？嗄啊。', '', 28153),
(149907, 'zhTW', '注意分寸！', '', 28153),
(149906, 'zhTW', '快滾！部落的邪惡雜種！', '', 28153),
(149905, 'zhTW', '你很快就會被打得稀巴爛了！', '', 28153),
(149904, 'zhTW', '部落…一群未經開化、能力不足，智力又相當低下的傢伙。你們是怎麼找到這座島上來的？碰巧撞上的吧，這還用說。', '', 28153),
(149903, 'zhTW', '為了你們部落好，我就說慢一點。島…我們的。你們…快滾。這樣夠清楚了嗎？', '', 28153),
(149902, 'zhTW', '部落的野蠻人！乖乖把艾澤萊晶岩都交上來，我們就接受你們投降。希望你們沒有蠢到拒絕這麼寬宏大量的提議。', '', 28153),
(149901, 'zhTW', '', '嗯？我們見過嗎？', 28153),
(149900, 'zhTW', '', '噁！聯盟的臭乞丐平常就穿這樣嗎？快走吧…丟臉都要丟死了！', 28153),
(149899, 'zhTW', '', '那就是聯盟的船嗎？它是被海巨人攻擊過，還是原本就長這樣？', 28153),
(149898, 'zhTW', '是這裡太熱了，還是我太熱情了？我在說什麼…當然是我太熱情了！', '', 28153),
(149897, 'zhTW', '烤熟了！', '', 28153),
(149896, 'zhTW', '再燒旺一點！', '', 28153),
(149895, 'zhTW', '來放點火吧！', '', 28153),
(149894, 'zhTW', '你去峽谷放火，我會破壞上層的大砲。等你那邊好了，再到獸欄跟我會合。', '', 28153),
(149893, 'zhTW', '', '噁！要是不用看著你也能殺你就好了！', 28153),
(149892, 'zhTW', '要在海裡淹死，還是被烈焰吞噬。你們自己選吧，聯盟狗！', '', 28153),
(149891, 'zhTW', '噁！那是什麼味道？看來聯盟狗派出「精銳部隊」了。你知道他們為什麼這麼臭嗎？因為他們吃太多起司了。', '', 28153),
(149890, 'zhTW', '聖光保佑你。', '', 28153),
(149889, 'zhTW', '你很強...但我比你更強。', '', 28153),
(149888, 'zhTW', '我要撤退了。', '', 28153),
(149887, 'zhTW', '聖光為你治療！', '', 28153),
(149886, 'zhTW', '啊，是聯盟啊。我今天本來很開心的。要是你們走了我就更開心了。', '', 28153),
(149885, 'zhTW', '聯盟，這座島是我們的。你們現在放棄的話，就不會有人傷亡。', '', 28153),
(149884, 'zhTW', '敵人殺過來了！', '', 28153),
(149883, 'zhTW', '$n開始施放大治療術！', '$n開始施放大治療術！', 28153),
(149882, 'zhTW', '', '找出路來，不然就開一條。我們絕不能浪費時間。', 28153),
(149881, 'zhTW', '', '就這麼辦吧。薩魯法爾、納薩諾斯…你們立刻出發。', 28153),
(149880, 'zhTW', '大部分的走私商人不會想吸引霸王的關注…不過，我們應該能說服某個傢伙幫忙。', '', 28153),
(149879, 'zhTW', '我不是笨蛋。永望鎮的貨物不可能都走正規路線運過去。費伍德森林裡面一定有秘密路線。', '', 28153),
(149878, 'zhTW', '什麼意思？', '', 28153),
(149877, 'zhTW', '嗯…凋零者，你有認識的走私商人嗎？', '', 28153),
(149876, 'zhTW', '', '我們從兩側夾擊瑪法里恩。', 28153),
(149875, 'zhTW', '', '薩魯法爾，我要你帶一些人去費伍德森林，從山上找路去黑海岸。至於攻城武器，就留給我來指揮。', 28153),
(149874, 'zhTW', '', '看來這些幽光很容易受到干擾。我們可以利用這個弱點穿過這群幽光。', 28153),
(149873, 'zhTW', '大酋長，費伍德森林沒有路可以穿過。', '', 28153),
(149872, 'zhTW', '', '祖達薩，在大崩裂下存活並且仍然蓬勃發展的少數城市之一。在全盛時期，贊達拉帝國統治了半個世界。在蘇拉瑪爾，我們還是會警告我們的小孩，要他們小心食人妖和他們的陰險手段。\n\n我們視他們為嗜血的野蠻人。但看著這個…嗯，很容易讓人懷疑，到底是誰需要依靠另一方：贊達拉人或是部落。', 28153),
(149871, 'zhTW', '', '沙漠中充滿狐狸人的怒氣，尋求名為復仇的出口。我一定會幫他們復仇！', 28153),
(149870, 'zhTW', '', '無信者，死神來敲門了！', 28153),
(149869, 'zhTW', '', '前往佐拉姆加，快！', 28153),
(149868, 'zhTW', '結婚典禮準備開始了。', '結婚典禮準備開始了。', 28153),
(149867, 'zhTW', '嗯，這有點難為情。\n\n是這樣的，我已經把我的講稿寫在我的筆記本上，但我似乎把它…弄丟了。\n\n它一定就在這房間的某處，如果你能幫我找到它，我會永遠感謝你！', '', 28153),
(149866, 'zhTW', '噢，你好。恐怕我們還不認識，但你為了露西前來這裡，我很感激。\n\n我能如何幫你？', '', 28153),
(149865, 'zhTW', '別擔心，瓦札會在納茲米爾照顧你！', '', 28153),
(149864, 'zhTW', '露西爾不知道，只要她來到白林教堂，我都會去看她。\n\n一定是因為她對這裡發生的一切太過憂慮絕望，才會看不到我的靈魂。我只希望她多多少少能感覺到，其實我就在這裡。', '', 28153),
(149858, 'zhTW', '而你要去彼岸見他們了。願瑟沙利思原諒你。', '', 28153),
(149857, 'zhTW', '我們為自己搞了場亂鬥！', '我們為自己搞了場亂鬥！', 28153),
(149856, 'zhTW', '夸風大口吃掉了魚。', '', 28153),
(149855, 'zhTW', '夸風小心地聞了聞獻上的魚。', '', 28153),
(149854, 'zhTW', '<給予閃鱗魚肉。>', '<給予閃鱗魚肉。>', 28153),
(149853, 'zhTW', '<夸風害怕地往後，隨著你靠近不斷退縮。>$b$b或許你需要收買一下小翼手龍，要不要試試看給牠吃點心？', '', 28153),
(149852, 'zhTW', '永遠…', '', 28153),
(149851, 'zhTW', '我會永遠在這裡的，露西…', '', 28153),
(149850, 'zhTW', '', '噢，亞歷山大…真希望你也在這裡…', 28153),
(149849, 'zhTW', '謝謝你，朋友。', '', 28153),
(149848, 'zhTW', '我終於…可以放下對這個地方的回憶了。', '', 28153),
(149847, 'zhTW', '你錯了，老友，全都拜你所賜，他們死了。', '', 28153),
(149846, 'zhTW', '瓦里克，我並沒有強迫他們跟隨我…他們天生就是征服者…', '', 28153),
(149845, 'zhTW', '你會後悔…看到這些…', '你會後悔…看到這些…', 28153),
(149844, 'zhTW', '威奎斯特夫人是個可怕的敵人…', '威奎斯特夫人是個可怕的敵人…', 28153),
(149843, 'zhTW', '', '最好是這樣！', 28153),
(149842, 'zhTW', '別擔心，我來對付這個傢伙。', '別擔心，我來對付這個傢伙。', 28153),
(149841, 'zhTW', '', '蠢貨！絕對不能被人看到！', 28153),
(149840, 'zhTW', '看樣子有人來了…', '看樣子有人來了…', 28153),
(149839, 'zhTW', '跟妳合作總是這麼愉快，夫人。', '跟妳合作總是這麼愉快，夫人。', 28153),
(149838, 'zhTW', '', '這是給你的錢，無賴。快拿走，不要被人看見！', 28153),
(149837, 'zhTW', '有刺客！露西，躲我後面。守衛，保護賓客！', '', 28153),
(149836, 'zhTW', '', '亞歷山大，不！', 28153),
(149835, 'zhTW', '這不是針對你。', '這不是針對你。', 28153),
(149834, 'zhTW', '亞歷山大，你準備好要…等等，那是什麼？！', '', 28153),
(149833, 'zhTW', '身為佐司瓦的領主，也是露西爾的父親，我很榮幸能在大地、天空和海洋的見證下，主持這場婚禮。', '', 28153),
(149832, 'zhTW', '各位親朋好友、還有親愛的來賓，我們在這個涼爽的秋日相聚，一起慶賀露西爾和亞歷山大結為連理。', '', 28153),
(149831, 'zhTW', '很好。', '', 28153),
(149830, 'zhTW', '', '當然好。請繼續吧，父親。', 28153),
(149829, 'zhTW', '來吧？', '', 28153),
(149828, 'zhTW', '她馬上就來了。她交代我先替她開始。', '', 28153),
(149827, 'zhTW', '', '沒關係的，父親。那母親呢？', 28153),
(149826, 'zhTW', '請原諒我來遲了。', '', 28153),
(149825, 'zhTW', '威奎斯特夫人去哪了？', '', 28153),
(149824, 'zhTW', '', '他來了！', 28153),
(149823, 'zhTW', '哎呀，我遲到這麼久，記得幫我道歉。', '', 28153),
(149822, 'zhTW', '請轉告他們小倆口我馬上就下去。', '', 28153),
(149821, 'zhTW', '噢，你找到了！感謝浪潮啊！', '', 28153),
(149820, 'zhTW', '', '你是存心浪費我們的時間嗎？！', 28153),
(149819, 'zhTW', '', '我們要找的是一本冊子。你以為我們不會先去看書架嗎？', 28153),
(149818, 'zhTW', '', '我丈夫怎麼會把筆記本放在露西的背包裡？你也太蠢了！', 28153),
(149817, 'zhTW', '我應該沒有把它跟露西的信件放一起，但確認一下也無妨。', '', 28153),
(149816, 'zhTW', '我很感謝你的幫忙，但請你不要再亂翻我女兒的貼身衣物了…', '', 28153),
(149815, 'zhTW', '', '她的選擇對我們家族根本沒有好處…', 28153),
(149814, 'zhTW', '露西只是擇其所愛，梅芮迪絲。我當初娶你也是一樣…', '', 28153),
(149813, 'zhTW', '', '我告訴你，亞瑟，你絕對不能答應。我們的女兒怎麼可以嫁給普通商人？！', 28153),
(149812, 'zhTW', '', '謝謝你來到這裡。有你真是太好了。', 28153),
(149811, 'zhTW', '你為什麼會來這裡？', '', 28153),
(149810, 'zhTW', '露西？你來了…不對，你不是露西。', '', 28153),
(149809, 'zhTW', '你也一樣。你父王可不想看到你帶這些傢伙回來。是他命令我來找你的。', '', 28153),
(149807, 'zhTW', '不管怎樣，只是想確保最後獲勝的都是我而已。我的鑰匙在賈克拉傑將軍手上，然後…他現在應該也拿到你那把了。', '', 28153),
(149806, 'zhTW', '科爾塞克，你做了什麼好事？', '', 28153),
(149805, 'zhTW', '瓦里克，我很好奇…既然你在這裡，那是誰留在神廟裡保護重要的鑰匙呢？', '', 28153),
(149804, 'zhTW', '', '[PH] 我為了守護族人而生。你會死於這個賤民手中！', 28153),
(149803, 'zhTW', '[PH] 低賤的狐狸人，你們存在的意義就是為我的帝國效命！', '', 28153),
(149802, 'zhTW', '', '', 28153),
(149801, 'zhTW', '我要替自己買副新牙齒，而且是金子做的！', '我要替自己買副新牙齒，而且是金子做的！', 28153),
(149800, 'zhTW', '我們不會讓謎思拉克斯重獲自由，我會讓人民團結一心。', '', 28153),
(149799, 'zhTW', '付出勞力的都是我們，我們應該拿走所有的金子。', '付出勞力的都是我們，我們應該拿走所有的金子。', 28153),
(149798, 'zhTW', '不對，你只是我們犯下的過錯。是瑟沙利斯的壯烈犧牲，為我們帶來現在的和平。', '', 28153),
(149797, 'zhTW', '我，就是塞斯拉克真正的力量！', '', 28153),
(149796, 'zhTW', '最好沒有人想要騙走我這一份寶藏。', '最好沒有人想要騙走我這一份寶藏。', 28153),
(149795, 'zhTW', '等我找到寶藏，我會和寶藏一起消失！', '等我找到寶藏，我會和寶藏一起消失！', 28153),
(149794, 'zhTW', '找到的人，他們會額外分一份！', '找到的人，他們會額外分一份！', 28153),
(149793, 'zhTW', '價值三百萬枚金幣啊！我們要發財了！', '價值三百萬枚金幣啊！我們要發財了！', 28153),
(149792, 'zhTW', '說不定我們挖錯地方了？', '說不定我們挖錯地方了？', 28153),
(149791, 'zhTW', '我要替自己買座城堡，裡面還要有熱的洗澡水和僕人。', '我要替自己買座城堡，裡面還要有熱的洗澡水和僕人。', 28153),
(149790, 'zhTW', '奈得里說我們很接近了，隨時都會找到。', '奈得里說我們很接近了，隨時都會找到。', 28153),
(149789, 'zhTW', '我要買一艘比艦隊裡面任何一艘船艦都要大的船！', '我要買一艘比艦隊裡面任何一艘船艦都要大的船！', 28153),
(149788, 'zhTW', '三百萬的1/267可以分到多少？', '三百萬的1/267可以分到多少？', 28153),
(149787, 'zhTW', '這筆錢多到連珍娜‧普勞德摩爾都會想要我入贅！', '這筆錢多到連珍娜‧普勞德摩爾都會想要我入贅！', 28153),
(149786, 'zhTW', '', '…偶爾也會發生這種事。', 28153),
(149785, 'zhTW', '', '這是第一次，牠們會感覺到風拂過雙翼。這是飛行的樂趣！還有…', 28153),
(149784, 'zhTW', '', '啊…又有一隻回應天空的召喚了！', 28153),
(149783, 'zhTW', '快點回來，我們必須盡快攻擊科爾塞克皇帝。', '', 28153),
(149782, 'zhTW', '我會留在這裡為攻擊行動做準備，無信者那邊的問題就交給你處理。', '', 28153),
(149781, 'zhTW', '<將小獸推到巢外。>', '<將小獸推到巢外。>', 28153),
(149779, 'zhTW', '[用戶端場景－泰莉亞勇敢指控艾胥凡女士是這次攻擊的幕後黑手。你看不出來嗎，凱瑟琳？她一直想要取代你。凱瑟琳轉向普莉希拉－這是真的嗎？普莉希拉不再假裝溫柔而憐憫。她對凱瑟琳態度強硬：軟弱！你不配統治！是艾胥凡建造了這座城市！她對準凱瑟琳開了一槍。守衛立刻有了動作。普莉希拉對群眾附近的馬車射擊了幾輪子彈，揚起了一陣煙霧，迅速地覆蓋了整個廣場。場面陷入混亂。]', '[用戶端場景－泰莉亞勇敢指控艾胥凡女士是這次攻擊的幕後黑手。你看不出來嗎，凱瑟琳？她一直想要取代你。凱瑟琳轉向普莉希拉－這是真的嗎？普莉希拉不再假裝溫柔而憐憫。她對凱瑟琳態度強硬：軟弱！你不配統治！是艾胥凡建造了這座城市！她對準凱瑟琳開了一槍。守衛立刻有了動作。普莉希拉對群眾附近的馬車射擊了幾輪子彈，揚起了一陣煙霧，迅速地覆蓋了整個廣場。場面陷入混亂。]', 28153),
(149778, 'zhTW', '瓦里克，我已經準備迎戰科爾塞克皇帝。', '瓦里克，我已經準備迎戰科爾塞克皇帝。', 28153),
(149777, 'zhTW', '', '我的寶物…不…', 28153),
(149776, 'zhTW', '毀滅這艘船，拯救我們的人民吧！', '', 28153),
(149775, 'zhTW', '', '你手上的武器真閃亮，我有更多戰利品可拿了！', 28153),
(149774, 'zhTW', '偉大的風暴啊，聆聽我的呼喚！', '', 28153),
(149772, 'zhTW', '[PH] 非常精采，「老朋友」。但這還不足以阻止我！', '', 28153),
(149771, 'zhTW', '[PH] 我把鑰匙藏在堡壘深處，瓦里克，難道你以為我蠢到把鑰匙帶在身上嗎？', '', 28153),
(149770, 'zhTW', '[PH] 不過，有件事你說對了，和平談判已經不可能了！', '', 28153),
(149769, 'zhTW', '[PH] 廢話少說，老朋友，把謎思拉克斯牢籠的鑰匙交出來，你會害死我們所有人！', '', 28153),
(149768, 'zhTW', '我就讓你們見識一下永恆皇帝科爾塞克的力量！', '', 28153),
(149767, 'zhTW', '[PH] 成功了，我可能駕馭這座尖塔的力量了，事不宜遲，快去大門那！', '', 28153),
(149766, 'zhTW', '', '沙啊，我真高興看到你！我現在整個不知道要怎麼辦…', 28153),
(149765, 'zhTW', '', '基羅的行蹤很難掌握，總是在到處奔走，總是在計畫什麼大事。\n\n他跟妮莎一起離開了。但我最後聽到，他要到下頭的峽谷裡去偷些補給品或是破壞火砲之類的事。', 28153),
(149764, 'zhTW', '', '妮莎在下頭的奴隸營惹了些麻煩。先往西邊離開這個洞穴，再從你右手邊的第一個坡道往下走就到了。\n\n不確定方向的時候，聽聽看有沒有塞斯拉克死前的哀嚎，朝那走就對了，她會在附近的。', 28153),
(149763, 'zhTW', '', '喔，這部分可精彩了！你進來的時候應該完全沒看到他們，對吧？\n\n潛行的狐狸人在逃脫路線上沿途藏身，隨時留意無信者的蹤影！\n\n當他們知道在道路上行走非常安全時，我帶著一些狐狸人離開，去找能送他們到安全處的商隊。\n\n然後我再偷偷溜回來，準備帶下一批人離開。整個過程非常刺激，到目前為止我只因為恐懼哭了三次！\n\n如果你必須離開，只要離開洞穴並往西邊移動。過橋進入遺跡，你就安全了。', 28153),
(149762, 'zhTW', '', '我想就跟你一樣。看看這裡的狐狸人…他們傷痕累累，急需幫助。\n\n無信者奴役了我無數的族人，強迫我們為他們工作和戰鬥。\n\n以前，我們一直無法阻止他們。但妮莎和基羅讓我們知道我們可以反抗。\n\n在夜晚，基羅和其他人溜進下方的奴隸營，拯救最虛弱的狐狸人。\n\n他們把獲救的人帶來這裡，我則是守住安全通往沙丘的道路，那兒有篷車正在等著接他們去安全處。\n\n這過程非常危險，雖然我很想回到營地，聽著阿娜在溫暖的營火旁唱歌，但當我知道我的朋友需要我的幫助，我怎麼能只顧著自己。', 28153),
(149761, 'zhTW', '我想問點別的事。', '我想問點別的事。', 28153),
(149760, 'zhTW', '妮莎在哪裡？', '妮莎在哪裡？', 28153),
(149759, 'zhTW', '基羅在哪裡？', '基羅在哪裡？', 28153),
(149758, 'zhTW', '你要怎麼將奴隸偷運出去？', '你要怎麼將奴隸偷運出去？', 28153),
(149757, 'zhTW', '你在這裡做什麼？', '你在這裡做什麼？', 28153),
(149756, 'zhTW', '', '$p！我就知道你會來！我告訴他們：「$p在乎狐狸人，不會拋棄我們。」\n\n我也是來幫忙的！基羅和妮莎正在拯救狐狸人奴隸，我負責組織商隊，帶他們離開這裡。\n\n離塞斯拉克那麼近，實在有點可怕。但我知道這是正確的，妮莎也這麼說。\n\n喔，對了，歡迎來到我們小小的藏身之地。', 28153),
(149755, 'zhTW', '帶路吧。', '帶路吧。', 28153),
(149754, 'zhTW', '若你說謊，就會被吊死。', '若你說謊，就會被吊死。', 28153),
(149753, 'zhTW', '我與你同在。', '我與你同在。', 28153),
(149752, 'zhTW', '', '非常好！我們的部隊會好好使用這批補給品。', 28153),
(149751, 'zhTW', '', '我們找到一艘被鮮血食人妖擊沉的船隻殘骸。一定要在他們出現之前，搶回船上的物資！', 28153),
(149750, 'zhTW', '這最好是好消息。', '這最好是好消息。', 28153),
(149749, 'zhTW', '嗯。好吧，我們走。', '嗯。好吧，我們走。', 28153),
(149748, 'zhTW', '什麼？你最好沒有說錯…', '什麼？你最好沒有說錯…', 28153),
(149747, 'zhTW', '嗯，我值得信賴的侍從，看來我們在這裡的工作完成了。若你不介意，我還有一個雙頭巨人要殺。', '', 28153),
(149746, 'zhTW', '一名盜匪！別害怕，女士，我會保護你的！', '', 28153),
(149745, 'zhTW', '星界惡魔？我絕不能容忍閃閃二世受到如此侮辱！準備嚐嚐強尼的厲害…那是雙頭巨人嗎？', '', 28153),
(149744, 'zhTW', '星界惡魔！你獨力消滅這頭惡魔真是值得嘉許！牠有傷到你嗎？', '', 28153),
(149743, 'zhTW', '', '人們逐漸對凱瑟琳失去信心…', 28153),
(149742, 'zhTW', '', '很好…我們或許必須大鬧一場。', 28153),
(149741, 'zhTW', '', '第一步，製造騷亂。', 28153),
(149740, 'zhTW', '[PH] 夠遠了，謎思拉克斯將會復活，你們這些叛徒只有死路一條！', '', 28153),
(149739, 'zhTW', '[PH] 鑰匙會落入我們手裡…謎思拉克斯將會復活！', '', 28153),
(149738, 'zhTW', '閃閃二世…你怎麼不飛呢…？', '', 28153),
(149737, 'zhTW', '[PH] 我應該馬上開始…科爾塞克的軍隊很快就會到來！', '', 28153),
(149736, 'zhTW', '我已經準備好為你抵擋塞斯拉克的攻勢，你可以開始諧調了。', '我已經準備好為你抵擋塞斯拉克的攻勢，你可以開始諧調了。', 28153),
(149735, 'zhTW', '[PH]  準備好了嗎？我們必須快點，科爾塞克的軍隊會試著阻止我，不讓我竊取這座尖塔的力量，在我施法期間，你必須保護我的安全。', '', 28153),
(149730, 'zhTW', '這些幽光是從哪裡來的啊？', '', 28153),
(149729, 'zhTW', '啊！這些該死的幽光！', '', 28153),
(149726, 'zhTW', '各位英雄，你們解決了波拉勒斯的重大威脅，但我敢以酒桶打賭，這個城市的危機還沒解除。', '', 28153),
(149725, 'zhTW', '只要幹掉那個背後傷人的小人跟船長，海盜軍隊就只剩下不會綁鞋帶、連汙水幫浦都不會用的烏合之眾。', '', 28153),
(149724, 'zhTW', '哈蘭早該知道，背叛我就是這種下場。', '', 28153),
(149723, 'zhTW', '但那些人你三兩下就能解決了，對吧？', '', 28153),
(149722, 'zhTW', '喔對，除了他身邊那群可怕、充滿惡意的殺手跟罪犯。', '', 28153),
(149720, 'zhTW', '[PH] 我會想辦法抵達尖塔，跟我在那裡會合。科爾塞克的軍隊一定會極力阻止我們竊取他們的力量。', '', 28153),
(149719, 'zhTW', '美麗的女士，你有何困難？北郡的瑪克西米利安前來救助！', '', 28153),
(149717, 'zhTW', '', '小傢伙，沒有你的話，我們根本找不到洛琪拉。', 28153),
(149716, 'zhTW', '聽來有位少女需要救助。跟我來，侍從！', '', 28153),
(149715, 'zhTW', '你知道，侍從，我過去好幾次都沒成功殺掉這雙頭巨人，但我的矛深深地插在她的兩側。所以，我要給你的第一個任務---', '', 28153),
(149714, 'zhTW', '', '我們是朋友，對吧？', 28153),
(149713, 'zhTW', '', '去贊姆蘭會經過廢墟，你可以搭便車！朵朵和點點都會陪我，但有個能聊天的朋友也不錯。', 28153),
(149712, 'zhTW', '所以，那個泡泡…喔！你對鹽水沒輒？那可真奇怪，小東西。', '', 28153),
(149711, 'zhTW', '不！不可能的！', '', 28153),
(149710, 'zhTW', '等等…那些狐狸人在這裡幹嘛？', '', 28153),
(149709, 'zhTW', '雖然那裡已經廢棄多年，不過那裡倒是很適合讓我們…', '', 28153),
(149708, 'zhTW', '我自己的聖所就藏在山丘裡面。那是一座信奉瑟沙利斯的小小聖壇，我都在那裡冥想。', '', 28153),
(149707, 'zhTW', '當時我和科爾塞克一起領導塞斯拉克人，大家都虔誠信仰瑟沙利斯。', '', 28153),
(149706, 'zhTW', '溺水夢境吞噬了我！', '溺水夢境吞噬了我！', 28153),
(149705, 'zhTW', '我在那邊住過，是很久以前的事了，當時科爾塞克還沒為了權力和瘋狂的念頭背叛同胞。', '', 28153),
(149704, 'zhTW', '那裡到處都是岩石和塵土，環境惡劣，到處都是背棄羅亞的塞斯拉克人。', '', 28153),
(149703, 'zhTW', '我在無限的虛無中暢飲。', '我在無限的虛無中暢飲。', 28153),
(149702, 'zhTW', '我不再盲目了。', '我不再盲目了。', 28153),
(149701, 'zhTW', '我們正朝無信者帝國的中心地帶前進，勇士。', '', 28153),
(149700, 'zhTW', '是法陣…我看到虛無法陣了！', '是法陣…我看到虛無法陣了！', 28153),
(149699, 'zhTW', '扭曲的暗影來找我了！', '啊…扭曲的暗影來找我了！', 28153),
(149698, 'zhTW', '我聽見了！千萬個真相的聲音！', '啊…我聽見了！千萬個真相的聲音！', 28153),
(149697, 'zhTW', '我會在深淵永生。', '我會在深淵永生。', 28153),
(149696, 'zhTW', '總算！現在可以接近哈蘭‧史威特了，沒有人能阻擋我們。', '', 28153),
(149695, 'zhTW', '我的靈魂獻給上古之神！', '我的靈魂獻給上古之神！', 28153),
(149694, 'zhTW', '', '我們發誓一定會保護你的同胞。', 28153),
(149693, 'zhTW', '把拳頭舉起來試試看，你懂拳擊吧？', '', 28153),
(149692, 'zhTW', '那顆該死的藤壺把整個島都封鎖了。在打鬥結束前都不會解除的。', '', 28153),
(149691, 'zhTW', '我領子上可沒有和平之花，聯盟人渣！', '我領子上可沒有和平之花，聯盟人渣！', 28153),
(149690, 'zhTW', '我根本不知道礦道地鐵的任何事！', '我根本不知道礦道地鐵的任何事！', 28153),
(149689, 'zhTW', '接下來只要找把刀插進哈蘭的肚皮就成了，但這才是困難的地方。', '', 28153),
(149688, 'zhTW', '梟獸不會飛！你得走了！', '梟獸不會飛！你得走了！', 28153),
(149687, 'zhTW', '我不是間諜！', '我不是間諜！', 28153),
(149686, 'zhTW', '魚人什麼跟什麼？你腦子有問題吧！', '魚人什麼跟什麼？你腦子有問題吧！', 28153),
(149685, 'zhTW', '一瓶食人妖的汗水？我們這裡不賣那種東西！', '一瓶食人妖的汗水？我們這裡不賣那種東西！', 28153),
(149684, 'zhTW', '樹當然很漂亮，火當然很糟。你到底想說什麼？', '樹當然很漂亮，火當然很糟。你到底想說什麼？', 28153),
(149683, 'zhTW', '贊達拉永垂不朽！', '贊達拉永垂不朽！', 28153),
(149682, 'zhTW', '', '這神殿有點不對勁，我們需要想辦法進去。', 28153),
(149681, 'zhTW', '可惜你走英雄風格，不然應該會是帥氣的海盜。', '', 28153),
(149680, 'zhTW', '我長眠…是為了甦醒…', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149679, 'zhTW', '那…很不錯，瑪克西米利安。我現在就走了。', '那…很不錯，瑪克西米利安。我現在就走了。', 28153),
(149678, 'zhTW', '無盡的暗影…擁抱著我…', '', 28153),
(149677, 'zhTW', '你的希望…黯淡…', '', 28153),
(149676, 'zhTW', '呃…什麼？', '呃…什麼？', 28153),
(149675, 'zhTW', '種子…紮根了…', '', 28153),
(149674, 'zhTW', '我只不過是…萬中之一…', '', 28153),
(149673, 'zhTW', '循環…在延續…', '', 28153),
(149672, 'zhTW', '死亡本身…也會…死…', '', 28153),
(149671, 'zhTW', '你終究…會知道真相的…', '', 28153),
(149670, 'zhTW', '你聽說了嗎？戴林之門淪陷了！', '你聽說了嗎？戴林之門淪陷了！', 28153),
(149669, 'zhTW', '你對這一切有何感想？', '你對這一切有何感想？', 28153),
(149668, 'zhTW', '海流會把你沖往深淵。', '', 28153),
(149667, 'zhTW', '你的歌聲讓我想重操舊業。', '', 28153),
(149666, 'zhTW', '黑牙惡徒最喜歡打架練拳頭。如果你能打得他們滿地找牙，拉沃船長一定會拉你去開會。', '', 28153),
(149665, 'zhTW', '你幹嘛發出像殺豬一樣的聲音？', '', 28153),
(149664, 'zhTW', '污鼠會那群傢伙喝酒喝得比魚還凶！只要你證明自己酒量比他們好，尤多拉船長一定會邀請你參加會議的。', '', 28153),
(149663, 'zhTW', '你聽說那場攻擊了嗎？', '你聽說那場攻擊了嗎？', 28153),
(149662, 'zhTW', '不要讓任何人說我對戰爭沒有貢獻，這是我的報告。', '不要讓任何人說我對戰爭沒有貢獻，這是我的報告。', 28153),
(149661, 'zhTW', '', '不唱就不唱。點點和朵朵是最棒的好朋友，把車子拉過一座座沙丘！', 28153),
(149660, 'zhTW', '我不知道…情況每天都在惡化。或許應該是凱瑟琳下台的時候了。', '我不知道…情況每天都在惡化。或許應該是凱瑟琳下台的時候了。', 28153),
(149659, 'zhTW', '我不會讓聯盟失望的，就算我為了拿到這個在泥沼裡呆坐了三天也一樣。請把我的報告拿去吧。', '我不會讓聯盟失望的，就算我為了拿到這個在泥沼裡呆坐了三天也一樣。請把我的報告拿去吧。', 28153),
(149658, 'zhTW', '', '點點和朵朵最愛聽我唱撫慰心靈的歌了。', 28153),
(149657, 'zhTW', '你能相信有些人認為食人妖和夜精靈有血緣關係嗎？這次的經驗太糟糕了。我的報告在這裡。', '你能相信有些人認為食人妖和夜精靈有血緣關係嗎？這次的經驗太糟糕了。我的報告在這裡。', 28153),
(149656, 'zhTW', '想辦法拿到邀請函，會比較好做事。你也可以衝進去把這世界上最可怕的三位海盜船長直接做掉。你自己想想吧，夥伴。', '', 28153),
(149655, 'zhTW', '', '點點和朵朵是最棒的好朋友，把車子拉過一座座沙丘！小小的牙齒最愛吃…', 28153),
(149654, 'zhTW', '我說過，為了向泰達希爾復仇，我什麼都願意。假扮成食人妖也不例外，這是我的報告。', '我說過，為了向泰達希爾復仇，我什麼都願意。假扮成食人妖也不例外，這是我的報告。', 28153),
(149653, 'zhTW', '我收到可靠情報，那些船長打算聚在一起開會。如果我們有辦法混進去，就能把九頭蛇全部的腦袋一次砍掉！', '', 28153),
(149652, 'zhTW', '我的翼手龍在哪裡？', '我的翼手龍在哪裡？', 28153),
(149651, 'zhTW', '我的小龍怎麼了？', '我的小龍怎麼了？', 28153),
(149650, 'zhTW', '大家都說，到叢林走走吧；大家都說，很簡單的。把我的報告拿去就是了。', '大家都說，到叢林走走吧；大家都說，會沒事的。把我的報告拿去就是了。', 28153),
(149649, 'zhTW', '他為什麼會發出那個聲音？', '他為什麼會發出那個聲音？', 28153),
(149648, 'zhTW', '野蠻人，這裡都是徹頭徹尾的野蠻人。請把我的報告拿去吧。', '野蠻人，這裡都是徹頭徹尾的野蠻人。請把我的報告拿去吧。', 28153),
(149647, 'zhTW', '別問我昨晚被迫睡在哪裡。這是你的報告。', '別問我昨晚被迫睡在哪裡。這是你的報告。', 28153),
(149646, 'zhTW', '謝謝。', '謝謝。', 28153),
(149645, 'zhTW', '我比較像是策劃大局的人，執行方面的小細節就交給你了。', '', 28153),
(149644, 'zhTW', '最後讓哈蘭‧史威特付出代價。', '', 28153),
(149643, 'zhTW', '溺死在無盡之血當中。', '', 28153),
(149642, 'zhTW', '計畫就是：把分水海寇倒個精光，把污鼠會趕跑，把黑牙惡徒打爆，再把鐵潮變成廢鐵。', '', 28153),
(149641, 'zhTW', '如果哈蘭得逞，他率領的艦隊會威脅這整片海域。', '', 28153),
(149640, 'zhTW', '我以為我聽到了某種尖嘯，但我沒辦法離巢去看。$b$b最好快點，不然你就少一頭翼手龍能照顧了。牠們不是都能長大成年的。', '', 28153),
(149639, 'zhTW', '哈蘭‧史威特打算把所有海盜聚集在鐵潮的巨帆底下。', '', 28153),
(149638, 'zhTW', '噢，他跑了。大概是無聊了吧。$b$b你應該要在他弄傷自己前去找他。他還沒準備好要自衛。', '', 28153),
(149637, 'zhTW', '牠的確看起來很不快樂，對吧？$b$b牠一定在想媽媽，嘿，就是你，對吧？', '', 28153),
(149636, 'zhTW', '你的靈魂會不知飽足。', '', 28153),
(149635, 'zhTW', '眾星會畏懼我們的崛起。', '', 28153),
(149634, 'zhTW', '他發出的那陣噪音絕對是代表他餓了。$b$b最好在他惹事生非以前餵飽他。$b$b如果你沒有食物，你可以從戰獸欄那兒弄一點來。', '', 28153),
(149633, 'zhTW', '體會真實無存的擁抱。', '', 28153),
(149632, 'zhTW', '在奈奧羅薩永遠沉睡吧。', '', 28153),
(149631, 'zhTW', '在無盡深淵之下，黑暗無光。', '', 28153),
(149630, 'zhTW', '我是護翼者勾亞，帕骷是我的羅亞，我服侍萬風之王，照顧她的子嗣。$b$b她跟我說過，或許你需要幫忙。$b$b<護翼者勾亞雅輕笑。>$b$b你需要什麼？', '', 28153),
(149629, 'zhTW', '好好盯著你的死亡陰影吧。', '', 28153),
(149628, 'zhTW', '我聽說是海盜。你相信嗎？卑鄙、被蒼蠅咬的海盜！普勞德摩爾家族還有辦法保護我們嗎？', '我聽說是海盜。你相信嗎？卑鄙、被蒼蠅咬的海盜！普勞德摩爾家族還有辦法保護我們嗎？', 28153),
(149627, 'zhTW', '啊！我忠誠的侍從！總是在我需要時出現。\n\n我來到庫爾提拉斯，是希望能拯救身陷危險的市民。我當前的任務是拯救這靜謐村莊裡的可憐漁民，因為雙頭巨人已經決定要來襲擊他們。\n\n他們的皮不尋常地厚。', '', 28153),
(149626, 'zhTW', '是的，你跟其他所有人。排進隊伍裡然後不要試著想出鋒頭。人群已經夠燥動的了。', '是的，你跟其他所有人。排進隊伍裡然後不要試著想出鋒頭。人群已經夠燥動的了。', 28153),
(149625, 'zhTW', '我需要立刻見凱瑟琳‧普勞德摩爾。', '我需要立刻見凱瑟琳‧普勞德摩爾。', 28153),
(149624, 'zhTW', '海軍上將普勞德摩爾公爵正準備向大眾講話。請保持耐心。', '海軍上將普勞德摩爾公爵正準備向大眾講話。請保持耐心。', 28153),
(149623, 'zhTW', '總帥有危險了。跟我來！', '總帥有危險了。跟我來！', 28153),
(149622, 'zhTW', '請保持冷靜，一切都在掌握之中。', '請保持冷靜，一切都在掌握之中。', 28153),
(149621, 'zhTW', '奈得里‧古林那不喜歡被人佔便宜。誰都不准比我先找到寶藏！', '', 28153),
(149620, 'zhTW', '我不會被你抓到我在睡覺。\n\n你要是敢騙我，我就把你送去給忠誠者。', '', 28153),
(149619, 'zhTW', '這浪潮之血是最近才受到腐化的。我應該可以淨化它。', '', 28153),
(149618, 'zhTW', '啊！這個東西居然這麼不穩定。', '', 28153),
(149617, 'zhTW', '怎麼啦，旅行者！\n\n你是否一直在追尋我的英雄事蹟，冀望有一天能成為北郡的瑪克西米利安的侍從呢？\n\n你可以不用再冀望了，因為你走運了！我正需要一個侍從來替我在對抗危險敵人時協助我進行任務！', '', 28153),
(149616, 'zhTW', '', '我一定會找到她，拼死也會。', 28153),
(149615, 'zhTW', '', '贊姆蘭的港口在南邊，已經很多年沒有船進港了。不過那裡最有可能找到基羅和妮莎攻擊賽斯拉克需要的東西。', 28153),
(149614, 'zhTW', '', '你們專心找你們的朋友，路況交給我來顧就好。', 28153),
(149613, 'zhTW', '', '這是大戰之後，但…勾拉圖爾沒有死。雖然身受重傷，但是他沒死！', 28153),
(149612, 'zhTW', '', '各種歷史版本說的都一樣，勾拉圖爾被亞羅姆殺掉之後，他的軍隊也就此潰敗。這裡說，他被刺殺的時候力量就消失了，傀儡也都跟著粉碎。這一定有所關連。', 28153),
(149611, 'zhTW', '', '亞羅姆‧威奎斯特當時還是上校，他率領那次攻擊行動。刻在這邊的是…威奎斯特刺傷了勾拉圖爾。', 28153),
(149610, 'zhTW', '', '在佐司特石碑上面雕刻的是庫爾提拉斯人，不是佐司特人。', 28153),
(149609, 'zhTW', '', '有意思。我之前都不知道，原來他是逼不得已，所以才用傀儡來作戰。', 28153),
(149608, 'zhTW', 'Zuq yoh\'ghyl ma oou shandai nuq Ez iilth thyzz', '', 28153),
(149607, 'zhTW', 'Fhssh zzof og far\'al awtgsshu。', '', 28153),
(149606, 'zhTW', '', '很好！奎格瓦的後代暫時安全了。這位英雄，謝謝你。', 28153),
(149605, 'zhTW', '夸風發出開心的尖嘯，一口吞下獻上的食物。', '', 28153),
(149604, 'zhTW', '夸風先嗅了嗅食物，然後開始大快朵頤。', '', 28153),
(149603, 'zhTW', '夸風在空中把食物奪走。', '', 28153),
(149602, 'zhTW', '夸風衝向獻上的食物，整個吞下。', '', 28153),
(149601, 'zhTW', '', '那些鮮血食人妖抓走奎格瓦的後代．青蛙羅亞的內心滿是憤怒，現在，去幫他報仇吧！', 28153),
(149600, 'zhTW', '以斯陀頌恩之名！', '以斯陀頌恩之名！', 28153),
(149599, 'zhTW', '谷地是我們的，鼠輩！', '谷地是我們的，鼠輩！', 28153),
(149598, 'zhTW', '少了我們，庫爾提拉斯會沉入海底！', '少了我們，庫爾提拉斯會沉入海底！', 28153),
(149597, 'zhTW', '我們的艦隊會毀了你！', '我們的艦隊會毀了你！', 28153),
(149596, 'zhTW', '反抗我們的都得死！', '反抗我們的都得死！', 28153),
(149595, 'zhTW', '我們就像大海一樣無情！', '我們就像大海一樣無情！', 28153),
(149594, 'zhTW', '你竟敢對抗斯陀頌恩家族？', '你竟敢對抗斯陀頌恩家族？', 28153),
(149593, 'zhTW', '庫爾提拉斯屬於大海！', '庫爾提拉斯屬於大海！', 28153),
(149592, 'zhTW', '我為…海洋而生…', '我為…海洋而生…', 28153),
(149591, 'zhTW', '浪潮賢者…救救我…', '浪潮賢者…救救我…', 28153),
(149590, 'zhTW', '我只是…聽命行事…', '我只是…聽命行事…', 28153),
(149589, 'zhTW', '我們…已經贏了…', '我們…已經贏了…', 28153),
(149588, 'zhTW', '殺了我…也一樣…', '殺了我…也一樣…', 28153),
(149587, 'zhTW', '我們…絕不鬆懈…', '我們…絕不鬆懈…', 28153),
(149586, 'zhTW', '我流著…大海的血…', '我流著…大海的血…', 28153),
(149585, 'zhTW', '深海之中…藏著真理。', '深海之中…藏著真理。', 28153),
(149584, 'zhTW', '你不知道這有多羞辱人，這是你的報告。', '你不知道這有多羞辱人，這是你的報告。', 28153),
(149583, 'zhTW', '', '蠢貨…至少我們現在知道這些幽光有多危險了。', 28153),
(149582, 'zhTW', '', '瑪法里恩，我們下次見面就是你的死期！', 28153),
(149581, 'zhTW', '到此為止，女妖之王！', '', 28153),
(149580, 'zhTW', '<夸風把頭放在翅膀下，發出微弱的尖鳴。>', '', 28153),
(149579, 'zhTW', '', '捅人的時候到了！', 28153),
(149577, 'zhTW', '[PH] 讓他們付出代價，$p。', '', 28153),
(149575, 'zhTW', '', '還等什麼？牠才剛孵出來，肚子餓了。去戰獸欄要些肉。', 28153),
(149574, 'zhTW', '你召來雷電！', '', 28153),
(149573, 'zhTW', '', '我聽到了，幼獸的肺活量很不錯。\n\n你為什麼看起來這麼害怕？', 28153),
(149571, 'zhTW', '<眼神呆滯地看著你>', '<眼神呆滯地看著你>', 28153),
(149570, 'zhTW', '我什麼都沒說。', '我什麼都沒說。', 28153),
(149569, 'zhTW', '不介意給我枚金幣吧？', '不介意給我枚金幣吧？', 28153),
(149568, 'zhTW', '你這食人妖的長相還真奇特。', '你這食人妖的長相還真奇特。', 28153),
(149567, 'zhTW', '…什麼？', '…什麼？', 28153),
(149566, 'zhTW', '你擋住我的視線了。', '你擋住我的視線了。', 28153),
(149565, 'zhTW', '<打嗝。>', '<打嗝。>', 28153),
(149564, 'zhTW', '<說出暗語>。', '<說出暗語>。', 28153),
(149563, 'zhTW', '有事嗎？', '有事嗎？', 28153),
(149562, 'zhTW', '龜肉湯一點也比不上$r湯。\n\n只要泥蟲肉就好，不要抓那些小烏龜。\n\n改天再來看我，我們再一起探索湯的可能性！', '', 28153),
(149561, 'zhTW', '龜肉湯？', '龜肉湯？', 28153),
(149560, 'zhTW', '為了瑟沙利斯！', '', 28153),
(149559, 'zhTW', '通往科爾塞克皇帝的路被無信者封住了，一定要摧毀那道屏障！', '', 28153),
(149558, 'zhTW', '喂，聽我說！瑪姬在工坊那需要人幫忙，她需要一些零件，呃…反正就是零件。我對這些東西不太在行，好嗎？', '', 28153),
(149557, 'zhTW', '做得好。這個情報足以影響整個戰局。不過，我也不知道這次的密語是誰的主意。', '', 28153),
(149556, 'zhTW', '我們的密探已經混進贊達拉，但還是需要你把報告帶回來。去找游民說話。如果是密探就會回應你的密語。', '', 28153),
(149555, 'zhTW', '呃，基地附近有幾個巨魔，而且他們看起來好像很生氣。各位先生女士，拿起你的武器來！', '', 28153),
(149554, 'zhTW', '在這裡，只有亞昆達。與亞昆達共享名字的人，方能進入神廟殿堂。', '', 28153),
(149553, 'zhTW', '尋求救贖之人，亞昆達永不拒絕。', '', 28153),
(149552, 'zhTW', '', '我們在找一個叫做洛琪拉的流放者，她可能會來這座神廟。', 28153),
(149551, 'zhTW', '', '說不定有金子，我先去。', 28153),
(149550, 'zhTW', '', '我們也想和平共處，但佐司特馬上發動了戰爭。願意接受陌生人的並不多。', 28153),
(149549, 'zhTW', '', '等等，這裡顯示了庫爾提拉斯早期的據點，是一個早已消失的據點。', 28153),
(149548, 'zhTW', '我會和瑪奧卡談談。', '我會和瑪奧卡談談。', 28153),
(149547, 'zhTW', '很好，都到齊了。', '', 28153),
(149545, 'zhTW', '嗨，老兄。', '', 28153),
(149544, 'zhTW', '', '朋友，又見面了。', 28153),
(149543, 'zhTW', '', '這世界將無法承受謎思拉克斯帶來的破壞。', 28153),
(149542, 'zhTW', '讓他去吧，泰莉亞！', '', 28153),
(149541, 'zhTW', '', '山繆，不！', 28153),
(149540, 'zhTW', '為了艾丁頓！為了斯陀頌恩谷地！', '', 28153),
(149539, 'zhTW', '那些混蛋會為他們的行為付出代價。', '', 28153),
(149538, 'zhTW', '', '賈克拉傑是罪有應得。', 28153),
(149537, 'zhTW', '我們會一起奮戰。為了風暴守望！', '', 28153),
(149535, 'zhTW', '', '我已經幫你挑好合適的人選了。去取回我要的東西吧。', 28153),
(149533, 'zhTW', '這裡還有更多逃出教團的人。太好了，也許我們還有機會。', '', 28153),
(149532, 'zhTW', '如果它們混進我們當中，那艦隊就危險了。', '', 28153),
(149531, 'zhTW', '人們都以為這只是傳說，我們曾用它們的故事來警惕自己，不要對法術鑽研太深。', '', 28153),
(149530, 'zhTW', '那些東西…叫做克西爾。它們來自深海中最黑暗的地方。', '', 28153),
(149529, 'zhTW', '', '', 28153),
(149528, 'zhTW', '大酋長，你找我有什麼事嗎？', '大酋長，你找我有什麼事嗎？', 28153),
(149527, 'zhTW', '', '貝恩，撤回部隊！', 28153),
(149526, 'zhTW', '', '你要用這個遙控指示來移動爾力。讓他前往出現騷動的地面，他就會把蟲引出來。', 28153),
(149525, 'zhTW', '我們也想要保護自己，抵抗它們。但是…恐怕我們是失敗了。', '', 28153),
(149523, 'zhTW', '後來…這些低語聲變了。有時候聽起來冷酷嚴苛，甚至殘暴無情。', '', 28153),
(149522, 'zhTW', '長久以來，我們依循海洋的聲音，引導船隻和人民。大部分的人都聽不到海洋溫和的低語。', '', 28153),
(149521, 'zhTW', '附近有座橋，可以清楚看到風暴聖壇。預兆就是從那裡出現的。', '', 28153),
(149520, 'zhTW', '我會享受折磨你的。', '', 28153),
(149519, 'zhTW', '', '你拿那個東西小心點。除非你打算對付外面那些害蟲，如果是的話就放手去燒吧，寶貝，燒吧！', 28153),
(149518, 'zhTW', '你笨蛋。你去死。', '', 28153),
(149517, 'zhTW', '這些囚犯是贊達拉人的！', '', 28153),
(149516, 'zhTW', '哈哈哈！', '', 28153),
(149515, 'zhTW', '你死定了！', '', 28153),
(149514, 'zhTW', '弱小的聯盟。', '', 28153),
(149513, 'zhTW', '我要粉碎你！', '', 28153),
(149512, 'zhTW', '你想去找審問者？', '', 28153),
(149511, 'zhTW', '新鮮的肉！', '', 28153),
(149510, 'zhTW', '那東西…安全嗎？我願意冒這個險！', '那東西…安全嗎？我願意冒這個險！', 28153),
(149509, 'zhTW', '讓我離開這裡！', '讓我離開這裡！', 28153),
(149508, 'zhTW', '潮母啊…我們到底成了什麼樣子？', '', 28153),
(149507, 'zhTW', '你的出現太剛好了！', '你的出現太剛好了！', 28153),
(149506, 'zhTW', '那是個…鑽地機嗎？', '那是個…鑽地機嗎？', 28153),
(149505, 'zhTW', '我害怕到地底下去…但我更怕這些食人妖！', '我害怕到地底下去…但我更怕這些食人妖！', 28153),
(149504, 'zhTW', '謝謝你，謝謝！', '謝謝你，謝謝！', 28153),
(149503, 'zhTW', '你在緊要時刻來了！', '你在緊要時刻來了！', 28153),
(149502, 'zhTW', '我以為他們要把我吃了！', '我以為他們要把我吃了！', 28153),
(149501, 'zhTW', '指揮官，大酋長請你把哨站準備好，等一下要迎接士兵。', '指揮官，大酋長請你把哨站準備好，等一下要迎接士兵。', 28153),
(149500, 'zhTW', '我們必須騰出空間，迎接大酋長的艦隊。你可以清空碼頭嗎？', '我們必須騰出空間，迎接大酋長的艦隊。你可以清空碼頭嗎？', 28153),
(149499, 'zhTW', '大酋長需要口糧和床位，提供給她的軍隊。', '大酋長需要口糧和床位，提供給她的軍隊。', 28153),
(149498, 'zhTW', '你說大酋長帶了兩百名士兵？我會把哨站準備好等她大駕光臨。', '', 28153),
(149497, 'zhTW', '謹聽大酋長命令。我會立刻召集守衛清空碼頭。Lok\'tar，朋友。', '', 28153),
(149496, 'zhTW', '', '大酋長的軍隊需要食物跟住處？我們的儲備物資應該能夠應付。去年春天我們大豐收，也沒有遇到嚴冬。', 28153),
(149495, 'zhTW', '她在殺自己的士兵…', '', 28153),
(149494, 'zhTW', '讓我來，我知道該怎麼辦。', '', 28153),
(149493, 'zhTW', '送我回暴風城吧。(重新開始事件)', '送我回暴風城吧。(重新開始事件)', 28153),
(149492, 'zhTW', '將我送至祖達薩。(略過開場動畫。)', '將我送至祖達薩。(略過開場動畫。)', 28153),
(149491, 'zhTW', '', '我們海軍有一大堆軍艦不是被燃燒軍團摧毀，就是被聯盟破壞掉了。我已經請碼頭管理員日夜趕工，不過數量還是不夠。', 28153),
(149490, 'zhTW', '別動。', '', 28153),
(149489, 'zhTW', '我代表…古翰。他…作主。你…不從…就得死。', '', 28153),
(149488, 'zhTW', '來吧。', '', 28153),
(149487, 'zhTW', '羅亞的這副軀殼…滋養我…和…古翰。', '', 28153),
(149486, 'zhTW', '你想…阻止…古翰。只會…失敗…和…受苦。', '', 28153),
(149485, 'zhTW', '對…掙扎吧…抵抗吧…古翰要你…吃盡…苦頭。', '', 28153),
(149484, 'zhTW', '你們是…白費工夫。我…無人能敵。', '', 28153),
(149483, 'zhTW', '你們是…白費…我…無人能…什麼？不，不！', '', 28153),
(149482, 'zhTW', '這不…代表…什麼！他會找到…別的軀體。封印…會解除…古翰會…重獲自由！', '', 28153),
(149481, 'zhTW', '等等…這是地下室的東西嗎？', '', 28153),
(149480, 'zhTW', '', '[PH] 祝你好運。', 28153),
(149479, 'zhTW', '', '[PH] 他們的巡邏才剛過。你現在過去應該無大礙了。', 28153),
(149478, 'zhTW', '', '', 28153),
(149477, 'zhTW', '', '[PH] 無信者不會知道自己被什麼東西擊中！', 28153),
(149476, 'zhTW', '', '', 28153),
(149475, 'zhTW', '你開始追著小朋友跑，他們笑著跑給你追。', '你開始追著小朋友跑，他們笑著跑給你追。', 28153),
(149474, 'zhTW', '|TInterface\\Icons\\SPELL_NATURE_EARTHQUAKE:20|t%s朝|cFFFF0000$n|r施放|cFFFF0000|Hspell:257617|h[地裂崩引]|h|r！快散開！', '', 28153),
(149473, 'zhTW', '我以為我們能解決那些翼手龍來佔領丘陵上的制高點，但結果我們卻一個接一個被解決了。', '我以為我們能解決那些翼手龍來佔領丘陵上的制高點，但結果我們卻一個接一個被解決了。', 28153),
(149472, 'zhTW', '沒關係，女士。', '', 28153),
(149471, 'zhTW', '', '我不太喜歡演講，所以我長話短說。感謝你，你在斯陀頌恩谷地永遠都會有盟友。', 28153),
(149470, 'zhTW', '', '我沒有惡意，卡爾文。', 28153),
(149469, 'zhTW', '', '野豬人被趕跑了，牠們穿過農場跑回沼澤去了。你救了這些居民跟農夫…你為我們做的太多了，比起這些民兵能做的…或願意做的，都還要多。', 28153),
(149468, 'zhTW', '', '我不需要對你裝模作樣。反正我從來就不會說漂亮話。', 28153),
(149466, 'zhTW', '贊達拉人用船運送他們的戰俘，絕對不能讓他們得逞！用黑鐵矮人的鑽地機救出戰俘，別讓戰俘被拷問致死。', '', 28153),
(149465, 'zhTW', '', '我們必須把那些攻擊計畫送到基羅手中，沒時間浪費了，快走！', 28153),
(149464, 'zhTW', '', '她是對的。亞羅姆‧威奎斯特就是打了勝仗才當上領主。', 28153),
(149463, 'zhTW', '', '好吧，要是我們聽令的話，這些傀儡就到不了亞羅姆之地。來幫忙吧。', 28153),
(149462, 'zhTW', '', '她以為我們是她手下的士兵…', 28153),
(149461, 'zhTW', '', '打斷他們的鮮血獻祭！這只是我們阻止血神的其中一步而已。', 28153),
(149460, 'zhTW', '', '在祖爾納茲曼的那種邪惡儀式將腐化力量散播到這片大地，將鬼魂從彼界喚回來！淨化它們的遺體，讓它們安息吧！', 28153),
(149459, 'zhTW', '鮮血…之神…呃！', '鮮血…之神…呃！', 28153),
(149458, 'zhTW', '我們阿圖亞曼見。其他人在裡面等我們！', '', 28153),
(149457, 'zhTW', '他在呼喚我們…', '他在呼喚我們…', 28153),
(149456, 'zhTW', '有幾個蠍尾獅騎士碰上了麻煩。到戰場上搜尋生還者！', '', 28153),
(149455, 'zhTW', '走開！', '走開！', 28153),
(149454, 'zhTW', '不不不不！', '不不不不！', 28153),
(149453, 'zhTW', '滾出我的腦子！', '滾出我的腦子！', 28153),
(149452, 'zhTW', '啊！', '啊！', 28153),
(149451, 'zhTW', '快住手！', '快住手！', 28153),
(149450, 'zhTW', '我希望無信者能滿足於和平。我們總是如此希望。\n\n但他們不知節制的進犯迫使我們不得不出手。\n\n我們會推翻科爾塞克皇帝…而且我們會奪走一路上任何有用的東西。', '', 28153),
(149449, 'zhTW', '', '|TInterface\\Icons\\SPELL_MAGE_FLAMEORB:20|t快把彈藥桶搬離火源，別讓%s引爆！', 28153),
(149448, 'zhTW', '前鋒！準備支援威奎斯特上校！', '前鋒！準備支援亞羅姆上校！', 28153),
(149447, 'zhTW', '為了佐司瓦和庫爾提拉斯！', '為了佐司瓦和庫爾提拉斯！', 28153),
(149446, 'zhTW', '他們奪走我們的兒女！讓他們付出代價！', '他們奪走我們的兒女！讓他們付出代價！', 28153),
(149445, 'zhTW', '這就是光宗耀祖的時刻！', '這就是光宗耀祖的時刻！', 28153),
(149444, 'zhTW', '我們擊退他們了！繼續努力！', '我們擊退他們了！繼續努力！', 28153),
(149443, 'zhTW', '不要動搖！', '不要動搖！', 28153),
(149442, 'zhTW', '我們擊退敵人了！\n\n別光是站著，趕快戰鬥啊！', '我們擊退敵人了！\n\n別光是站著，趕快戰鬥啊！', 28153),
(149441, 'zhTW', '不祥之雲一接觸到%s，就開始沸騰起來！', '不祥之雲一接觸到%s，就開始沸騰起來！', 28153),
(149440, 'zhTW', '謝謝你…', '謝謝你…', 28153),
(149439, 'zhTW', '終於…我可以安息了…', '終於…我可以安息了…', 28153),
(149438, 'zhTW', '不需要再看守了…', '不需要再看守了…', 28153),
(149437, 'zhTW', '我要…回去休息了…', '我要…回去休息了…', 28153),
(149436, 'zhTW', '我的責任已盡…', '我的責任已盡…', 28153),
(149435, 'zhTW', '我會把肉找來。', '我會把肉找來。', 28153),
(149434, 'zhTW', '這個箱子是我的，你別多管閒事，$r。\n\n我需要泥蟲才能煮泥蟲湯，可是這種蟲會躲起來！我很有耐心，可以在這裡等上好幾天，或許可以再去多找幾個箱子？\n\n你幫我多找一些泥蟲肉，我就用這個箱子跟你交換。', '不行，這個盒子是我的！\n\n我是來這裡找蟲煮湯。有幾個托爾托說用海蟹煮湯非常美味，可是我不和托爾托打交道的。我不想為了海蟹湯就去和陌生人交朋友。\n\n靠泥蟲湯可以建立起維持一輩子的友誼，而我們托爾托的一輩子很長。\n\n你幫我找泥蟲肉，我就考慮把這個箱子給你。', 28153),
(149433, 'zhTW', '那個盒子？', '那個盒子？', 28153),
(149432, 'zhTW', '我站在這裡站了好久。然後就在泥巴裡看到這個有趣的箱子。', '我站在這裡站了好久。然後就在泥巴裡看到這個有趣的箱子。', 28153),
(149431, 'zhTW', '幹得好，老兄。我…我瘋了好久，我的靈魂如托爾托車隊般緩慢腐朽！', '幹得好，老兄。我…我瘋了好久，我的靈魂如托爾托車隊般緩慢腐朽！', 28153),
(149430, 'zhTW', '感謝你，陌生人。', '感謝你，陌生人。', 28153),
(149429, 'zhTW', '總算結束了。感謝你。', '總算結束了。感謝你。', 28153),
(149428, 'zhTW', '我又能高枕無憂了，感謝你，外邦人。', '我又能高枕無憂了，感謝你，外邦人。', 28153),
(149427, 'zhTW', '結束了…', '結束了…', 28153),
(149426, 'zhTW', '有什麼計畫？', '有什麼計畫？', 28153),
(149425, 'zhTW', '', '我在考慮電擊，或是火，或許乾脆把他給炸了！\n\n可是，殺死托爾托會招來厄運，我的厄運已經夠多了。\n\n那麼，讓我看看你會怎麼處理這個托爾托？', 28153),
(149424, 'zhTW', '', '我們有麻煩了，$p。有個托爾托發現了一個箱子，可是我們要那個箱子！', 28153),
(149423, 'zhTW', '討厭的沼澤！這邊濕氣太重，什麼東西都會壞掉。\n\n所以，有什麼事？有話快說，讓我早能繼續回去修理東西。', '討厭的沼澤！這邊濕氣太重，什麼東西都會壞掉。\n\n所以，有什麼事？有話快說，讓我早能繼續回去修理東西。', 28153),
(149422, 'zhTW', '', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149421, 'zhTW', '只有傲慢又無知的人才會樂於把阿曼尼食人妖留在身邊。你做得很好，勇士。', '', 28153),
(149420, 'zhTW', '阿曼尼食人妖都不是好東西，贊達拉人卻打開城門讓他們進到自己家裡。消滅那些侍徒，為了聯盟！', '', 28153),
(149419, 'zhTW', '那隻怪物死了！艾胥凡，守好上面的樓層！我會對付這個竊賊…', '那隻怪物死了！艾胥凡，守好上面的樓層！我會對付這個竊賊…', 28153),
(149418, 'zhTW', '只要我還活著，我不會讓這座堡壘淪陷！', '', 28153),
(149417, 'zhTW', '他們應該得到教訓了。', '', 28153),
(149416, 'zhTW', '<給凱蘭看歌唱之石。>', '<給凱蘭看歌唱之石。>', 28153),
(149415, 'zhTW', '阿曼尼部族一定會記得，我們部落在祖達薩一樣很有勢力。那你去提醒一下他們吧？敲響銅鑼，擊敗他們的侍徒。', '', 28153),
(149414, 'zhTW', '我會繼續往前去找農夫。不管你要做什麼，都別被他們抓到！', '', 28153),
(149413, 'zhTW', '', 'Taz\'dingo! ', 28153),
(149411, 'zhTW', '在泥巴裡有很多寶藏。你和摩可希要一起合作把寶藏找出來！', '', 28153),
(149410, 'zhTW', '不行！不能放克洛格…自由…', '', 28153),
(149409, 'zhTW', '奮勇作戰！', '奮勇作戰！', 28153),
(149408, 'zhTW', '為了部落！', '為了部落！', 28153),
(149407, 'zhTW', '我們一起戰鬥。', '我們一起戰鬥。', 28153),
(149406, 'zhTW', '我會和你一同奮戰。', '我會和你一同奮戰。', 28153),
(149405, 'zhTW', '我欠你一份情，$n。', '我欠你一份情，$n。', 28153),
(149404, 'zhTW', '儀式尚未完成，一定要制伏克洛格！', '', 28153),
(149403, 'zhTW', '繼續攻擊，我可以照顧自己。', '', 28153),
(149402, 'zhTW', '', '我的力量…這是…怎麼回事？', 28153),
(149401, 'zhTW', '', '我的身體…我沒辦法…呃啊！', 28153),
(149400, 'zhTW', '好。', '好。', 28153),
(149399, 'zhTW', '', '工人說他們聽到泥巴裡有聲音，有些人因此而瘋了！\n\n反正我不去聽就對了！', 28153),
(149398, 'zhTW', '', '有些庫爾提拉斯認為我和幾起竊盜事件有關，但我真的完全不知情。', 28153),
(149397, 'zhTW', '', '我要航向…未知的領域…', 28153),
(149396, 'zhTW', '', '這傢伙的反應好像從沒見過地精！', 28153),
(149395, 'zhTW', '', '我受夠了！', 28153),
(149394, 'zhTW', '', '屠殺彈，發射！', 28153),
(149393, 'zhTW', '', '把你打得稀爛！', 28153),
(149392, 'zhTW', '', '我要把你切碎！', 28153),
(149391, 'zhTW', '', '離開甲板！', 28153),
(149390, 'zhTW', '贊達拉…只會給滿滿的空頭支票。', '贊達拉…只會給滿滿的空頭支票。', 28153),
(149389, 'zhTW', '我的羅亞會告訴你接下來發生哪些事情…', '我的羅亞會告訴你接下來發生哪些事情…', 28153),
(149388, 'zhTW', '對我們來說，沒有一個地方可以讓我們安心過活。', '對我們來說，沒有一個地方可以讓我們安心過活。', 28153),
(149387, 'zhTW', '他們在自己的城市裡…放任我們自生自滅。', '他們在自己的城市裡…放任我們自生自滅。', 28153),
(149386, 'zhTW', '我們會變成什麼樣子？', '我們會變成什麼樣子？', 28153),
(149385, 'zhTW', '帝國…真的隕落了。', '帝國…真的隕落了。', 28153),
(149384, 'zhTW', '怎麼會…發生這種事。', '怎麼會…發生這種事。', 28153),
(149383, 'zhTW', '贊達拉…說過會保障我們的安全…', '贊達拉…說過會保障我們的安全…', 28153),
(149382, 'zhTW', '終於！有人找到了我給伯昂撒姆第的祭品，好好使用吧！', '終於！有人找到了我給伯昂撒姆第的祭品，好好使用吧！', 28153),
(149381, 'zhTW', '', '拇指留給我！剩下的就隨便你們。', 28153),
(149380, 'zhTW', '', '要是你死掉，我就要拿走你那一份！', 28153),
(149379, 'zhTW', '', '你的頭顱會是很棒的收藏。', 28153),
(149378, 'zhTW', '', '你和我現在算得上是朋友了。我可以向你借點金幣嗎？', 28153),
(149377, 'zhTW', '', '我在托達戈爾見過和你長得一模一樣的人。', 28153),
(149376, 'zhTW', '你犯的可是天大的錯誤！', '你犯的可是天大的錯誤！', 28153),
(149375, 'zhTW', '救命！臺地被攻擊了！', '救命！臺地被攻擊了！', 28153),
(149374, 'zhTW', '抓住他們！', '抓住他們！', 28153),
(149373, 'zhTW', '你不屬於這裡，夥計！', '你不屬於這裡，夥計！', 28153),
(149372, 'zhTW', '走開！贊達拉屬於食人妖！', '走開！贊達拉屬於食人妖！', 28153),
(149371, 'zhTW', '我就知道我聞到某種惡臭…', '我就知道我聞到某種惡臭…', 28153),
(149370, 'zhTW', '救命！我被攻擊了！', '救命！我被攻擊了！', 28153),
(149369, 'zhTW', '骯髒的雜種！', '骯髒的雜種！', 28153),
(149368, 'zhTW', '可達一邊喋喋不休，一邊看向山溝裡。', '', 28153),
(149367, 'zhTW', '', '我也很擔心，可達。', 28153),
(149366, 'zhTW', '我需要前往東點站。', '我需要前往東點站。', 28153),
(149365, 'zhTW', '', '你要去哪裡？', 28153),
(149364, 'zhTW', '', '謝謝你！請好好對待波達！', 28153),
(149363, 'zhTW', '', '所有大砲，發射！', 28153),
(149362, 'zhTW', '船塢就是你們的新家。', '', 28153),
(149361, 'zhTW', '你們全都要在船塢聽從斯陀頌恩領主的命令。', '', 28153),
(149360, 'zhTW', '所有人都進貨車裡面。', '', 28153),
(149359, 'zhTW', '鮮血食人妖又在威脅我的孩子了！$B$B來吧，小傢伙，我們該一起提醒他們，激怒奎格瓦會發生什麼事！', '', 28153),
(149358, 'zhTW', '', '夥伴們，這城市屬於我們！', 28153),
(149357, 'zhTW', '', '我會把你的內臟掛起來！', 28153),
(149356, 'zhTW', '', '刀上又多了一道口子！', 28153),
(149355, 'zhTW', '', '全力攻擊！', 28153),
(149354, 'zhTW', '', '全部殺光！', 28153),
(149353, 'zhTW', '他們的等待就快結束了。', '', 28153),
(149352, 'zhTW', '多久以後？', '多久以後？', 28153),
(149351, 'zhTW', '鐵潮每天都發動攻擊，部落大軍也正在向這裡前進。再過不久，這裡的所有人都得逃走。', '', 28153),
(149348, 'zhTW', '我會用你的血…來完成這個儀式！', '', 28153),
(149347, 'zhTW', '好。', '好。', 28153),
(149346, 'zhTW', '失敗？不…', '', 28153),
(149345, 'zhTW', '在充滿泥濘的湖底，埋藏著抵得過整座王國的黃金。那裡有一艘在第二次獸人戰爭中沉沒的寶藏船！\n\n整個城鎮都在合作，想率先找到寶藏！不過時間短暫，我們動作要快！', '', 28153),
(149344, 'zhTW', 'Lith qul\'shoth wshh... yzsh uovssh qvask.', '', 28153),
(149343, 'zhTW', '', '賈克拉傑，認命吧，你的計畫失敗了！', 28153),
(149341, 'zhTW', '你們在海面上互相爭奪…他在海底靜靜等待。', '', 28153),
(149340, 'zhTW', '', '正好趕上來阻止你！', 28153),
(149339, 'zhTW', '你來得正是時候…', '', 28153),
(149338, 'zhTW', '', '啊！他們都跑回家了！', 28153),
(149337, 'zhTW', '我們的鮮血儀式就快要完成了！', '', 28153),
(149336, 'zhTW', '', '請趕快找到他們！可達會很傷心的，如果他失去他的家人。', 28153),
(149335, 'zhTW', '寶藏？', '寶藏？', 28153),
(149334, 'zhTW', '鐵潮把所有人都關起來了，他們不想讓我們先找到寶藏！', '', 28153),
(149333, 'zhTW', '', '回來，小傢伙！我們可以幫你！', 28153),
(149332, 'zhTW', '', '如果我們進去，那些帶刺的也會逮到我們的！', 28153),
(149331, 'zhTW', '', '我看不到他們，可達！', 28153),
(149330, 'zhTW', 'Zaix lal sk\'woth\'gl Zaix lal uulwi', '', 28153),
(149329, 'zhTW', '鐵潮把人都抓去關起來了，我們需要你幫忙！', '', 28153),
(149328, 'zhTW', '他們是救贖。他們是真相。', '', 28153),
(149327, 'zhTW', 'Zuq wgah nuq iilth zz oou ga\'halahs anagg', '', 28153),
(149326, 'zhTW', '你們全都會溺死在沒有光芒的深淵裡面。', '', 28153),
(149325, 'zhTW', '', '沒炸掉的話，就再試一次。', 28153),
(149323, 'zhTW', '不行，大酋長要我直接帶你去見她。', '', 28153),
(149322, 'zhTW', '', '這可是我的船，我看你是必須改變一下計畫了。', 28153),
(149321, 'zhTW', '公主，我們可以到路上再討論。', '', 28153),
(149320, 'zhTW', '', '走吧，我們去祖達薩。', 28153),
(149319, 'zhTW', '你要說的話應該是「謝謝」才對吧。', '', 28153),
(149318, 'zhTW', '像你這樣有能力的…法師…在這種時候應該能幫上大忙吧，嗯？', '', 28153),
(149317, 'zhTW', '', '不…這不可能。', 28153),
(149315, 'zhTW', '你可以留在這裡對付我們，或許會成功。', '', 28153),
(149314, 'zhTW', '你有看到火焰正在吞噬城市吧。', '', 28153),
(149313, 'zhTW', '不要那麼衝動。', '', 28153),
(149312, 'zhTW', '', '那就受死吧。', 28153),
(149311, 'zhTW', '多謝好意，不過我們趕著上船。', '', 28153),
(149310, 'zhTW', '', '乖乖投降，我就把你們這些畜牲送回監獄，等國王判你們的罪。', 28153),
(149309, 'zhTW', '在這裡等著。', '', 28153),
(149307, 'zhTW', '已經處理好了。好好看著。', '', 28153),
(149306, 'zhTW', '不要再發呆了，快打破冰牆！', '', 28153),
(149305, 'zhTW', '我不知道瑞贊是誰，但是我欠他一份情。', '', 28153),
(149303, 'zhTW', '', '死吧，部落的雜碎！', 28153),
(149302, 'zhTW', '', '她阻斷了我們的去路！', 28153),
(149300, 'zhTW', '', '我也想要一批那種鳥！', 28153),
(149299, 'zhTW', '哈哈！拉桑老兄你真是太天才了！', '', 28153),
(149298, 'zhTW', '沒有…不過我大概知道原因了。你看。', '', 28153),
(149297, 'zhTW', '羅亞站在你的敵人那邊，祖爾。', '', 28153),
(149296, 'zhTW', '', '你們一路上殺害了那麼多無辜的人。但這場鬧劇也該到此為止了。', 28153),
(149295, 'zhTW', '', '他們沒追過來嗎？', 28153),
(149294, 'zhTW', '哈哈哈哈！', '', 28153),
(149292, 'zhTW', '', '他們一定是召回了羅德隆的部隊。我們要怎麼過去？', 28153),
(149291, 'zhTW', '我們走吧！', '', 28153),
(149290, 'zhTW', '', '羅亞啊，請聆聽我們的呼喚，偉大的瑞贊，請賜予我們力量！', 28153),
(149289, 'zhTW', '', '你們休想再傷害這座城市裡面的任何人！', 28153),
(149288, 'zhTW', '', '這次休想逃跑！', 28153),
(149287, 'zhTW', '小心一點。看樣子經驗老到的聯盟外交官，這次可不會留下任何活口。', '', 28153),
(149286, 'zhTW', '啊啊！', '', 28153),
(149285, 'zhTW', '', '你找到我媽媽了！非常感謝你把她從可怕的怪物手中救回來！', 28153),
(149284, 'zhTW', '', '感謝帶回我的玩具。如果你看到我媽媽，可以拜託你請她回家嗎？\n\n我已經好久沒看到她了。', 28153),
(149283, 'zhTW', '快。粉碎最後的封印。', '', 28153),
(149282, 'zhTW', '', '塔蘭姬，你和你的勇士去追祖爾。我會盡力召集人手，想辦法拖住揭滅者。要消滅那東西，我們得有一整支軍隊。', 28153),
(149281, 'zhTW', '他指揮謎思拉克斯，我們必須阻止黑暗帝國的僕從。', '', 28153),
(149280, 'zhTW', '', '勇士，我和羅亞會盡量擋住謎思拉克斯。快去找我父親，一起把祖爾解決掉！', 28153),
(149279, 'zhTW', '來吧，謎思拉克斯。來吧，揭滅者。一定要破除最後的封印。', '', 28153),
(149278, 'zhTW', '小傢伙們，路上的敵人清光了。快動起來，謎思拉克斯正在靠近。', '', 28153),
(149277, 'zhTW', '', '贊達拉的兄弟姐妹們，一起奪回我們的城市！向前進軍！', 28153),
(149276, 'zhTW', '', '勇士，幫忙找出佐卡洛的平民，然後送到我們這裡來。我們會盡力幫忙治療。', 28153),
(149275, 'zhTW', '', '不妙。我們被包抄了。羅亞已經盡力幫忙了，我們還是要把能應戰的食人妖都集合起來。', 28153),
(149274, 'zhTW', '', '所謂時窮節乃見。現在情況如何？', 28153),
(149273, 'zhTW', '', '塔蘭姬，都能騎著羅亞上戰場了啊。', 28153),
(149272, 'zhTW', '', '洛琪拉，都能對軍隊發號施令了呢。', 28153),
(149271, 'zhTW', '', '列隊！把戰弓都準備好。', 28153),
(149270, 'zhTW', '', '嗯…那還真是…麻煩。', 28153),
(149269, 'zhTW', '', '這位勇士告訴我們，揭滅者謎思拉克斯再度現身了。', 28153),
(149268, 'zhTW', '', '有種力量在驅使塞斯拉克攻擊。他們以前不會這樣大舉進攻。', 28153),
(149267, 'zhTW', '', '請小心，父王。這都是早就策劃好的，我們卻不知道敵人是誰。', 28153),
(149266, 'zhTW', '塔蘭姬，帶著部落勇士，去那裡召集軍隊。我會和奎格瓦一起守住狹徑。', '', 28153),
(149265, 'zhTW', '', '拉斯塔哈！沃魯敦的毒蛇從西邊包圍你的城池了。趕快想想辦法！', 28153),
(149264, 'zhTW', '太多敵人闖過去了，快去通往達薩亞洛的那座橋，我們可以在那邊擋住他們。', '', 28153),
(149263, 'zhTW', '這是給伯昂撒姆第的禮物。', '', 28153),
(149262, 'zhTW', '受死吧，入侵者！', '', 28153),
(149261, 'zhTW', '數量還真是多。', '', 28153),
(149260, 'zhTW', '敵人已經攻到血門了，快點，在那些入侵者攻入城市之前，能夠殺多少算多少。', '', 28153),
(149259, 'zhTW', '', '你無法阻止…風暴吹襲…', 28153),
(149258, 'zhTW', '', '你無力反抗無信者帝國！', 28153),
(149257, 'zhTW', '我自己會想辦法離開的。你保重！', '', 28153),
(149256, 'zhTW', '謝謝你…我以為我完蛋了。', '', 28153),
(149255, 'zhTW', '這樣應該就可以了。勇士，單槍匹馬拿下整座城感覺如何啊？', '', 28153),
(149254, 'zhTW', '快跑…快跑！！！', '', 28153),
(149253, 'zhTW', '太快了，他還沒完全沉浸在主人的榮光之中！', '', 28153),
(149252, 'zhTW', '糟糕！城市陷入混亂！我會把我們弄出這裡的。', '', 28153),
(149250, 'zhTW', '試試看我放在你口袋裡的匕首。我覺得你會喜歡的。', '', 28153),
(149249, 'zhTW', '勇士，你先出發吧。你去標記那些可以下手的目標，我來負責解決。', '', 28153),
(149248, 'zhTW', '信任一旦有裂隙就很難修復了。這樣一來就算是高傲的贊達拉也會受到損害。勇士，做得好。', '', 28153),
(149247, 'zhTW', '食人妖弱小部族的使者十分依賴贊達拉的保護，但我們還是有辦法對付他們。殺死使者，讓敵人內鬨。', '', 28153),
(149246, 'zhTW', '燒掉他們的貨車，打斷他們的骨頭！', '燒掉他們的貨車，打斷他們的骨頭！', 28153),
(149245, 'zhTW', '如果這些害蟲把鑰匙藏了起來，我們會找到它！', '如果這些害蟲把鑰匙藏了起來，我們會找到它！', 28153),
(149244, 'zhTW', '夠烈的就留下來，它們可以賣個好價錢。', '夠烈的就留下來，它們可以賣個好價錢。', 28153),
(149243, 'zhTW', '快結束了嗎？拜託跟我說要結束了！', '', 28153),
(149242, 'zhTW', '回來這裡！', '回來這裡！', 28153),
(149241, 'zhTW', '', '趕快前往西北方的山脊。亞羅姆之地的人會清楚看到我們的信號。', 28153),
(149240, 'zhTW', '', '在我們離開之前，應該好好利用現在的情勢打擊敵人！', 28153),
(149239, 'zhTW', '', '我們可以到西北方的高地發出撤退信號。', 28153),
(149238, 'zhTW', '這太瘋狂了！別那麼快！', '', 28153),
(149237, 'zhTW', '哈哈哈哈！我最喜歡驚天動地的踏擊了！', '', 28153),
(149236, 'zhTW', '', '用女巫的武器來對抗她們的感覺真不錯。', 28153),
(149235, 'zhTW', '火焰發出了紫色煙霧。他們應該很快就會看見了。', '', 28153),
(149234, 'zhTW', '首先，我來下達指令，讓他們開始攻擊。', '', 28153),
(149233, 'zhTW', '不用。時候到了，他們自然會來。', '', 28153),
(149232, 'zhTW', '', '要去追他們嗎？', 28153),
(149231, 'zhTW', '沒有外來威脅…也不用再和羅亞打交道。這是一條用鮮血鋪成的路…古翰會率領我們！', '', 28153),
(149230, 'zhTW', '我現在還不太餓。你晚一點再來…', '', 28153),
(149229, 'zhTW', '如果我說一切都在計畫中，你信嗎？我想不太可能。', '', 28153),
(149228, 'zhTW', '好消息！我知道敵人的位置了。就在我們周圍！', '', 28153),
(149227, 'zhTW', '你…可以幫個忙，不要告訴蘿絲嗎？', '', 28153),
(149226, 'zhTW', '現在這樣真是不太光采啊。', '', 28153),
(149225, 'zhTW', '我向你透露這段預言。食人妖帝國會統治這個世界，恆古不朽。而食人妖帝王將穩坐在他的王位上，直到永遠，儘管你和我都活不到預言實現之日。讓我看見這道預示的是我的神明…', '', 28153),
(149224, 'zhTW', '老友，你故步自封，把我們的王國變得陳腐不堪。不過，我已經看見未來，食人妖帝國會再次崛起。', '', 28153),
(149223, 'zhTW', '你應該聽塔蘭姬的話才對。', '', 28153),
(149221, 'zhTW', '不要！哈布圖！', '', 28153),
(149220, 'zhTW', '哈！做得好！', '', 28153),
(149219, 'zhTW', '鮮血的時代就要來臨。', '', 28153),
(149218, 'zhTW', '羅亞的時代…結束了。', '', 28153),
(149217, 'zhTW', '我不是你的臣民。', '', 28153),
(149216, 'zhTW', '瑞贊啊瑞贊…', '', 28153),
(149215, 'zhTW', '說話小心點，叛徒。', '', 28153),
(149214, 'zhTW', '啊，他來了。是什麼的羅亞呢…嗯…', '', 28153),
(149212, 'zhTW', '', '事情最好跟你預料的一樣。', 28153),
(149211, 'zhTW', '邪惡的異端！', '', 28153),
(149210, 'zhTW', '', '預知你夥伴的下一個行動！', 28153),
(149209, 'zhTW', '', '像風一樣攻擊！招架！', 28153),
(149208, 'zhTW', '', '完成訓練之前不准休息！', 28153),
(149207, 'zhTW', '', '注意你的訓練對手！堅定地發動攻擊！', 28153),
(149206, 'zhTW', '指揮官！她就這樣…倒下了？！', '指揮官！她就這樣…倒下了？！', 28153),
(149205, 'zhTW', '姊妹，你還好嗎？！我不該這麼用力！', '姊妹，你還好嗎？！我不該這麼用力！', 28153),
(149204, 'zhTW', '喔我的天…我竟然…你還好嗎？！', '喔我的天…我竟然…你還好嗎？！', 28153),
(149200, 'zhTW', '沒有什麼比解決一名聯盟指揮官更讓人滿意的了。而且還如此輕易得手…', '', 28153),
(149199, 'zhTW', '', '一路順風。', 28153),
(149198, 'zhTW', '', '燼火會現在要再次對抗勾拉圖爾了。有盟友在，我們一定會堅強的。', 28153),
(149197, 'zhTW', '', '謝謝你幫我的忙。我可以向露西爾小姐報告任務成功了。', 28153),
(149196, 'zhTW', '我真不敢想像要是你跟審判官沒有插手的話會是什麼情況。', '', 28153),
(149195, 'zhTW', '幸好我沒死掉。', '', 28153),
(149194, 'zhTW', '', '現在飛越樹林還算安全，我只希望他們趕快到。', 28153),
(149193, 'zhTW', '', '獅鷲騎士正在等我們的信號。', 28153),
(149192, 'zhTW', '亂七八糟！亂七八糟！下次要安靜一點！', '', 28153),
(149191, 'zhTW', '可惡！不是說要安靜迅速的嗎？給我專心一點！', '', 28153),
(149190, 'zhTW', '盡快殺掉他，別讓他警告別人！', '', 28153),
(149189, 'zhTW', '小心別被發現！盡量不要引起注意…', '', 28153),
(149187, 'zhTW', '啊，不，不。這個交給我。', '', 28153),
(149186, 'zhTW', '我寧願睜一隻眼閉一隻眼。但我從來沒有趁人在睡夢中時殺了他。', '', 28153),
(149185, 'zhTW', '喂，小心那些平民，我們可不想引起守衛注意。', '', 28153),
(149184, 'zhTW', '剛剛那個不是守衛，但我不會阻止你屠殺聯盟的。', '', 28153),
(149183, 'zhTW', '照理說，我們可以放過平民…但我喜歡你的做法。', '', 28153),
(149182, 'zhTW', '你很冷酷…不過我喜歡。', '', 28153),
(149181, 'zhTW', '我們有個工程師在尋找備用零件的時候看到聯盟的人在礦場附近出沒。到工坊找瑪姬詢問詳情，然後…呃，做好準備。', '', 28153),
(149180, 'zhTW', '我的胸部…我無法呼吸！', '我的胸部…我無法呼吸！', 28153),
(149179, 'zhTW', '我的喉嚨…呃！', '我的喉嚨…呃！', 28153),
(149178, 'zhTW', '我覺得我快要吐了…', '我覺得我快要吐了…', 28153),
(149177, 'zhTW', '我只想要…休息…', '我只想要…休息…', 28153),
(149176, 'zhTW', '一切都如此…黑暗…', '一切都如此…黑暗…', 28153),
(149175, 'zhTW', '我…感覺很奇怪。', '我…感覺很奇怪。', 28153),
(149174, 'zhTW', '不！不！！', '', 28153),
(149173, 'zhTW', '什…什麼？！', '', 28153),
(149172, 'zhTW', '喂！給我站住！', '', 28153),
(149171, 'zhTW', '', '看來他們真的想找死…現在只希望他們的血不會化為古翰的助力。', 28153),
(149170, 'zhTW', '', '他們不斷地挑釁伯昂撒姆第，絕對不會有好下場。英雄，我們和伯昂撒姆第的契約依然有效，把這些迷途的靈魂送回伯昂撒姆第身邊吧！', 28153),
(149169, 'zhTW', '等等，噢。是我的另一條腿。沒事啦。', '', 28153),
(149168, 'zhTW', '有東西碰到我的腿了！', '', 28153),
(149167, 'zhTW', '大寶車安全了。你快去領你的獎勵吧！', '', 28153),
(149166, 'zhTW', '看來我們的礦工中大獎了！你把它完整的運回基地，我們都會大賺一筆。', '', 28153),
(149165, 'zhTW', '', '我們走！我會好好盯著你。', 28153),
(149164, 'zhTW', '', '炸藥用起來永遠不嫌多！', 28153),
(149163, 'zhTW', '', '你有沒有認識哪個庫爾提拉斯的貴族，有很多金子但是保全很鬆散的那種？', 28153),
(149162, 'zhTW', '', '我正在尋找像你一樣的聰明人，$p，有大量資金來投資我的新創企業。', 28153),
(149161, 'zhTW', '', '身為地精，在庫爾提拉斯不小心點不行。', 28153),
(149160, 'zhTW', '', '有疑慮的話，炸就對了。', 28153),
(149159, 'zhTW', '', '托巴拉德、托達戈爾、暴風城監獄，我全都待過！', 28153),
(149158, 'zhTW', '發出信號，我們離開這裡吧！', '發出信號，我們離開這裡吧！', 28153),
(149157, 'zhTW', '', '拜託，洛琪拉，別這樣！你會死掉的！', 28153),
(149156, 'zhTW', '', '感謝沙塵，你沒事！', 28153),
(149155, 'zhTW', '', '不准繼續前進！任何人都不准打擾主人！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149154, 'zhTW', '這些小傢伙看起來不太像是威脅，$r。', '', 28153),
(149151, 'zhTW', '', '$p，你還活著！你和我一樣幸運。', 28153),
(149150, 'zhTW', '晚點再見了。', '', 28153),
(149149, 'zhTW', '就這樣？', '', 28153),
(149148, 'zhTW', '你保重。', '', 28153),
(149147, 'zhTW', '不要擔心，朋友。', '', 28153),
(149146, 'zhTW', '要來點巫毒嗎？', '', 28153),
(149145, 'zhTW', '你需要什麼？', '', 28153),
(149144, 'zhTW', '', '只要我還活著，鮮血食人妖就休想再耍什麼詭計。', 28153),
(149143, 'zhTW', '', '鮮血食人妖想偷偷溜過去。我這邊有個東西能讓你看穿他們，好好利用，殺掉那些鮮血食人妖！', 28153),
(149142, 'zhTW', '調整你的呼吸，我們到船上之前是不會停的。', '', 28153),
(149141, 'zhTW', '跑！我跑了！', '跑！我跑了！', 28153),
(149140, 'zhTW', '祖爾會把我們都害死的。', '祖爾會把我們都害死的。', 28153),
(149139, 'zhTW', '末日要來了！', '末日要來了！', 28153),
(149138, 'zhTW', '這會大大影響生意的。', '這會大大影響生意的。', 28153),
(149137, 'zhTW', '我要離開這裡。', '我要離開這裡。', 28153),
(149136, 'zhTW', '喂！發生什麼事？！', '', 28153),
(149135, 'zhTW', '守衛！守衛，救命啊！噢！', '', 28153),
(149134, 'zhTW', '噢！你真野蠻！', '', 28153),
(149133, 'zhTW', '怕什麼！用力打過來就對了。', '', 28153),
(149132, 'zhTW', '快，打我啊！', '', 28153),
(149131, 'zhTW', '打我。', '', 28153),
(149130, 'zhTW', '聽好，計畫是這樣：', '', 28153),
(149129, 'zhTW', '第三篇：我快完成了！蜜蜂越生越多，產量也以倍數提高。但我要仔細注意蜂后的情況。', '', 28153),
(149128, 'zhTW', '第二篇：活化的蜜酒開始出現攻擊性。或許我的計算出現了一點點失誤。', '', 28153),
(149127, 'zhTW', '第一篇：蜂蜜活起來了，但是複製速率遠遠超出我的想像。我得多做點實驗！', '', 28153),
(149126, 'zhTW', '快滅火！別讓火勢蔓延！', '', 28153),
(149125, 'zhTW', '看看他們夾著尾巴逃跑的模樣！', '', 28153),
(149124, 'zhTW', '像老鼠一樣逃吧！', '', 28153),
(149123, 'zhTW', '', '真是蠢到家了。你們全都會死在這裡，成為無名墓塚下的一抔黃土。', 28153),
(149122, 'zhTW', '', '我知道部落一向殘酷無情、不擇手段。但現在這樣是怎麼回事…', 28153),
(149121, 'zhTW', '陛下！找到了！我會親自扒下他們的皮呈到你面前！', '', 28153),
(149120, 'zhTW', '別裝出一副不高興看到我們的樣子。', '', 28153),
(149119, 'zhTW', '我很高興。真的。快走吧，就等你準備好。', '', 28153),
(149118, 'zhTW', '', '祖爾，你真是殘酷的敵人。', 28153),
(149117, 'zhTW', '', '我們打不過她。快逃！', 28153),
(149116, 'zhTW', '', '現在怎麼了？', 28153),
(149115, 'zhTW', '看來場面還真是一團亂啊。', '', 28153),
(149114, 'zhTW', '', '到港口！我們必須前進！', 28153),
(149113, 'zhTW', '有人覺得，石頭城堡比較…不容易著火。', '', 28153),
(149112, 'zhTW', '敵人想包圍我們，絕對不能讓他們得逞！', '', 28153),
(149111, 'zhTW', '不要繼續前進比較好。', '', 28153),
(149110, 'zhTW', '我們回運河。跟我來！', '', 28153),
(149109, 'zhTW', '這個，等下會用到。', '', 28153),
(149108, 'zhTW', '', '快找掩護！', 28153),
(149107, 'zhTW', '', '小心！', 28153),
(149106, 'zhTW', '那匹老狼聞到我們的氣味了，趕快離開這裡！', '', 28153),
(149105, 'zhTW', '', '他們人太多…屏障撐不了多久！', 28153),
(149104, 'zhTW', '這就是了！阻止他們，不要讓他們到大門去！', '這就是了！阻止他們，不要讓他們到大門去！', 28153),
(149103, 'zhTW', '以為你逃過一劫了嗎？你錯了！', '以為你逃過一劫了嗎？你錯了！', 28153),
(149102, 'zhTW', '在下面！把那些資源搶過來！', '在下面！把那些資源搶過來！', 28153),
(149101, 'zhTW', '', '鮮血食人妖是種扭曲噁心的生物。他們永遠不可能改變。', 28153),
(149100, 'zhTW', '', '鮮血食人妖在吞噬我的人民！阻止他們！', 28153),
(149099, 'zhTW', '戮喙被騷動吸引過來！', '戮喙被騷動吸引過來！', 28153),
(149098, 'zhTW', '斧之喙被水中那些夥伴的氣味吸引過來！', '斧之喙被水中那些夥伴的氣味吸引過來！', 28153),
(149097, 'zhTW', '謝謝你，勇士！我可不想白白送掉自己這條小命。', '', 28153),
(149096, 'zhTW', '你來了！可以來幫我一個忙嗎？', '', 28153),
(149095, 'zhTW', '感謝你及時相助。我們會去跟威奎斯特小姐會合。', '', 28153),
(149094, 'zhTW', '', '再幫忙一下吧？', 28153),
(149093, 'zhTW', '謝謝你的幫忙。', '', 28153),
(149092, 'zhTW', '可惡的女巫和屏障！', '', 28153),
(149091, 'zhTW', '', '這些幼獸的狀況不錯。牠們以後會是很優秀的戰獸。', 28153),
(149090, 'zhTW', '', '年幼的戰獸需要持續的照顧和關心。牠們必須學會和我們互動，就像我們也得學會和牠們互動一樣。', 28153),
(149089, 'zhTW', '我聽到召喚了！', '', 28153),
(149088, 'zhTW', '我失去了所有的武器，但至少撿回了小命。', '', 28153),
(149087, 'zhTW', '他們趁我在偵察的時候偷襲我，這不會再發生了。', '', 28153),
(149086, 'zhTW', '我會回來讓這些鮮血食人妖付出代價的！', '', 28153),
(149085, 'zhTW', '謝謝你，我會回去祖爾詹。', '', 28153),
(149084, 'zhTW', '', '謝謝你，那些哥布林最好開始多花點心思幫助拯救我的城市，而不是滿腦子想賺錢。', 28153),
(149083, 'zhTW', '', '有支哥布林勘察小隊被不死生物困住了！我們必須去救他們才行！', 28153),
(149082, 'zhTW', '你知道這個焦油罐能用來做什麼嗎？我也不知道，但我聽說這能賣很多錢！', '', 28153),
(149081, 'zhTW', '這裡根本就是深淵無誤！我要閃人了。', '', 28153),
(149080, 'zhTW', '是啊，嗯，反正我正要離開。這焦油將賣出一大筆錢。', '', 28153),
(149079, 'zhTW', '好險！嘿，撿一些焦油給我，好嗎？這在老家能賣不少錢。', '', 28153),
(149078, 'zhTW', '謝謝，誰知道從一片沼澤禁地中取得焦油會這麼危險呢？', '', 28153),
(149076, 'zhTW', '科爾塞克太過火了，我必須親自去處理這件事情。我不在的時候，你要保護好這把鑰匙。', '', 28153),
(149075, 'zhTW', '', '鮮血食人妖這下子應該知道自己的日子不多了。', 28153),
(149074, 'zhTW', '', '哥布林戰隊想好要怎麼料理鮮血食人妖了。你去幫他們規劃一下逃脫路線。', 28153),
(149073, 'zhTW', '我們進去A.F.M.O.D.，阻止那團鮮血食人妖部隊的行動。', '我們進去A.F.M.O.D.，阻止那團鮮血食人妖部隊的行動。', 28153),
(149072, 'zhTW', '呦！我們有遇到一些想去祖達薩的狂暴鮮血食人妖。幸好我們對A.M.O.D作了一點小升級。\n\n盡情欣賞A.F.M.O.D吧，這個寶貝可以飛！死從天降！\n\n當然，我們必須丟掉他的盾牌，不然就沒辦法飛。\n\n想要開出去試試看嗎？我們可以把軍隊炸成碎片！', '', 28153),
(149071, 'zhTW', '你跟其他人一樣…沒用…', '', 28153),
(149070, 'zhTW', '又有流放者可以殺？今天運氣真不錯。', '', 28153),
(149066, 'zhTW', '小國王，出發吧。如果有人想跟蹤你，我就把他吃掉。', '', 28153),
(149065, 'zhTW', '喔，會有點小問題。', '', 28153),
(149064, 'zhTW', '', '祖爾沒嚇到尿褲子…應該不是什麼大事。', 28153),
(149063, 'zhTW', '他們一定還沒走遠。保持警戒才能確保人民安全。', '', 28153),
(149062, 'zhTW', '部落的入侵者闖入暴風城監獄了！請所有居民在威脅平息前待在屋內。', '', 28153),
(149061, 'zhTW', '這是國王的命令！', '', 28153),
(149060, 'zhTW', '我會把大家藏起來，只要別做出什麼蠢事就好。', '', 28153),
(149059, 'zhTW', '哈哈！別擔心，小安索，這只是一次挫折而已！我們很快就能重振旗鼓的。', '哈哈！別擔心，小安索，這只是一次挫折而已！我們很快就能重振旗鼓的。', 28153),
(149058, 'zhTW', '你-你-你在說什麼？你差點把自己害死不說，整個農場也被你毀了！', '', 28153),
(149057, 'zhTW', '由我們來推動蜂蜜製造的技術，不計代價！', '由我們來推動蜂蜜製造的技術，不計代價！', 28153),
(149056, 'zhTW', '看來你不需要啊。', '', 28153),
(149055, 'zhTW', '快跳。', '', 28153),
(149054, 'zhTW', '嗯？', '', 28153),
(149053, 'zhTW', '', '別擔心。如果他真的遭遇危險，我們一定會知道的。', 28153),
(149052, 'zhTW', '繼續吧。', '', 28153),
(149051, 'zhTW', '', '等等…衛兵都不見了？', 28153),
(149050, 'zhTW', '走吧，靠近一點。', '', 28153),
(149049, 'zhTW', '希望下次你能先提醒一下。', '', 28153),
(149048, 'zhTW', '保持警戒。軍情七處回報敵人在要塞附近現身。', '', 28153),
(149047, 'zhTW', '從橋上跳下去，快。', '', 28153),
(149046, 'zhTW', '我們過橋吧。先知大人，您覺得怎麼樣呢？', '', 28153),
(149045, 'zhTW', '快點，別站在路中間。', '', 28153),
(149044, 'zhTW', '在這裡等著。', '', 28153),
(149043, 'zhTW', '暴風城的居民，大家請注意！', '', 28153),
(149042, 'zhTW', '來吧，大家感情好一點，靠緊一點。', '', 28153),
(149041, 'zhTW', '', '全城的人都在找我們，我們不能在此逗留。', 28153),
(149040, 'zhTW', '我已經準備好要出海了！', '我已經準備好要出海了！', 28153),
(149039, 'zhTW', '', '你準備好要前往庫爾提拉斯了嗎？', 28153),
(149038, 'zhTW', '', '多謝你的幫忙，我們現在有時間可以進行調度，以及讓奎格瓦建立防線。謝謝你。', 28153),
(149037, 'zhTW', '你別想阻止我奪回自己的地盤！', '', 28153),
(149036, 'zhTW', '', '鮮血食人妖還在攻擊奎格瓦！想辦法切斷補給線，狠狠地給他們一點教訓！', 28153),
(149035, 'zhTW', '瑟沙利斯…我想不起來你的聲音了…', '', 28153),
(149034, 'zhTW', '我們不依靠羅亞的力量，我們的強大是自己獲得的！', '', 28153),
(149033, 'zhTW', '入侵者！不要插手你們不懂的事情。', '', 28153),
(149031, 'zhTW', 'PLACEHOLDER SCENE - 塔蘭姬問我們事情解決了沒。洛克漢則是說邪惡總有辦法活下去，事情不可能就這樣結束。\n鏡頭：塔蘭姬和洛克漢近觀，接著帶到充滿邪惡氣息的深坑。', 'PLACEHOLDER SCENE - 塔蘭姬問我們事情解決了沒。洛克漢則是說邪惡總有辦法活下去，事情不可能就這樣結束。\n鏡頭：塔蘭姬和洛克漢近觀，接著帶到充滿邪惡氣息的深坑。', 28153),
(149030, 'zhTW', '', '主人…我…失敗了…', 28153),
(149029, 'zhTW', '', '勾拉圖爾…來了…', 28153),
(149028, 'zhTW', '', '勾拉圖爾…會給我力量…', 28153),
(149027, 'zhTW', '', '雖然我對戰鬥不在行，但一定要設法制裁我母親，而且我還要親眼看到這一切。', 28153),
(149026, 'zhTW', '', '為了我父親，為了佐司瓦！', 28153),
(149025, 'zhTW', '', '審判官，我們在裡面會合。', 28153),
(149024, 'zhTW', '', '審判官，聽令！榮耀歸於威奎斯特！', 28153),
(149023, 'zhTW', '', '是的，小姐。我們會把女巫都解決掉。', 28153),
(149022, 'zhTW', '', '審判官，最後一戰就靠你們了。願你們一切順利。', 28153),
(149021, 'zhTW', '', '母親…你做了什麼？', 28153),
(149020, 'zhTW', '', '元帥，不…', 28153),
(149019, 'zhTW', '我…很遺憾…', '', 28153),
(149018, 'zhTW', '親愛的露西…我…讓你失望了…', '', 28153),
(149017, 'zhTW', '', '撐下去，元帥！', 28153),
(149016, 'zhTW', '不…不應該…這樣！', '', 28153),
(149015, 'zhTW', '我…服從…', '', 28153),
(149014, 'zhTW', '兩側交給我們，你跟緊露西爾和元帥！', '', 28153),
(149013, 'zhTW', '', '你們惹錯人了，可惡的女巫！', 28153),
(149012, 'zhTW', '繼續前進，這裡交給我們！啄眼睛就對了，溫斯頓！', '', 28153),
(149011, 'zhTW', '我會緊跟在後。', '我會緊跟在後。', 28153),
(149010, 'zhTW', '為了威奎斯特家族！', '', 28153),
(149009, 'zhTW', '跟緊一點，在我們攻破莊園大門之前都不要停下腳步！', '', 28153),
(149008, 'zhTW', '照這速度我們是撐不久的，我們必須跑到碼頭那裡。\n\n你一下令我們就走。', '', 28153),
(149007, 'zhTW', '審判官！我們要把握機會救出威奎斯特大人和夫人…還要消滅討厭的女巫！', '', 28153),
(149005, 'zhTW', '', '看得出你在顫抖。怕了嗎，聯盟狗？', 28153),
(149004, 'zhTW', '', '頭暈了嗎？', 28153),
(149003, 'zhTW', '', '你們真的以為打得贏？', 28153),
(149002, 'zhTW', '', '居然被…低等賤民…', 28153),
(149001, 'zhTW', '你們獲勝的機率幾乎是零！', '', 28153),
(149000, 'zhTW', '你的位置不對！', '', 28153),
(148999, 'zhTW', '燒死這個傢伙！', '', 28153),
(148998, 'zhTW', '你…作弊…', '', 28153),
(148997, 'zhTW', '我來幫你了！', '', 28153),
(148996, 'zhTW', '防禦陣形！', '', 28153),
(148995, 'zhTW', '聖光…會指引我。', '', 28153),
(148994, 'zhTW', '', '挖他們的心臟！', 28153),
(148993, 'zhTW', '', '我要把你的靈魂獻給勾拉圖爾！', 28153),
(148991, 'zhTW', '準備！有敵人來襲。', '準備！有敵人來襲。', 28153),
(148990, 'zhTW', '保護資源！', '保護資源！', 28153),
(148989, 'zhTW', '這木頭是我們的！', '這木頭是我們的！', 28153),
(148988, 'zhTW', '不要再靠近了！', '不要再靠近了！', 28153),
(148987, 'zhTW', '退後！', '退後！', 28153),
(148986, 'zhTW', '守護者是我們之間最強的，負責在大金字塔內封印謎思拉克斯的屍體。\n\n索利斯是創始者，但他無法獨自封印墓穴。\n\n他請求瓦里克和科爾塞克的幫忙，他們一起在大金字塔周圍設立了屏障，封印了其中的謎思拉克斯屍體。', '守護者是我們之間最強的，負責在大金字塔內封印謎思拉克斯的屍體。\n\n索利斯是創始者，但他無法獨自封印墓穴。\n\n他請求瓦里克和科爾塞克的幫忙，他們一起在大金字塔周圍設立了屏障，封印了其中的謎思拉克斯屍體。', 28153),
(148985, 'zhTW', '他自稱為科爾塞克皇帝，但很久以前他是守護者的一員，身負保護墓穴的重任。\n\n他對戰爭的渴望和我們羅亞所象徵的一切背道而馳，但他毀謗並違背了她，發起大軍要征服整個祖達薩。', '他自稱為科爾塞克皇帝，但很久以前他是守護者的一員，身負保護墓穴的重任。\n\n他對戰爭的渴望和我們羅亞所象徵的一切背道而馳，但他毀謗並違背了她，發起大軍要征服整個祖達薩。', 28153),
(148984, 'zhTW', '以科爾塞克皇帝為首的無信者是激進塞斯拉克人的武裝勢力。\n\n很久以前，我們都團結地生活在一起，如瑟沙利斯所願。\n\n自從科爾塞克叛變開始，無信者就為這片土地帶來了戰爭。\n\n他們征服整個世界之前，絕對不會停手。', '以科爾塞克皇帝為首的無信者是激進塞斯拉克人的武裝勢力。\n\n很久以前，我們都團結地生活在一起，如瑟沙利斯所願。\n\n自從科爾塞克叛變開始，無信者就為這片土地帶來了戰爭。\n\n他們征服整個世界之前，絕對不會停手。', 28153),
(148983, 'zhTW', '瑟沙利斯是我們敬愛的羅亞。\n\n在謎思拉克斯侵襲我們的土地並威脅要毀滅我們的時候，是她挺身阻止，犧牲自己的生命讓我們存活下來。\n\n不像那些無信者，我們還是能感覺到她的存在，而且相信總有一天她會回到我們身邊。', '瑟沙利斯是我們敬愛的羅亞。\n\n在謎思拉克斯侵襲我們的土地並威脅要毀滅我們的時候，是她挺身阻止，犧牲自己的生命讓我們存活下來。\n\n不像那些無信者，我們還是能感覺到她的存在，而且相信總有一天她會回到我們身邊。', 28153),
(148982, 'zhTW', '守護者是我們之間最強的，負責在大金字塔內封印謎思拉克斯的屍體。\n\n索利斯是創始者，但他無法獨自封印墓穴。\n\n他請求瓦里克和科爾塞克的幫忙，他們一起在大金字塔周圍設立了屏障，封印了其中的謎思拉克斯屍體。', '', 28153),
(148981, 'zhTW', '他自稱為科爾塞克皇帝，但很久以前他是守護者的一員，身負保護墓穴的重任。\n\n他對戰爭的渴望和我們羅亞所象徵的一切背道而馳，但他毀謗並違背了她，發起大軍要征服整個祖達薩。', '', 28153),
(148980, 'zhTW', '瑟沙利斯是我們敬愛的羅亞。\n\n在謎思拉克斯侵襲我們的土地並威脅要毀滅我們的時候，是她挺身阻止，犧牲自己的生命讓我們存活下來。\n\n不像那些無信者，我們還是能感覺到她的存在，而且相信總有一天她會回到我們身邊。', '', 28153),
(148979, 'zhTW', '', '我需要你立刻趕到奧格瑪，執行極為重要的緊急任務。不要讓我等太久。', 28153),
(148978, 'zhTW', '', '我們能不能得勝就看你的表現了。', 28153),
(148977, 'zhTW', '以科爾塞克皇帝為首的無信者是激進塞斯拉克人的武裝勢力。\n\n很久以前，我們都團結地生活在一起，如瑟沙利斯所願。\n\n自從科爾塞克叛變開始，無信者就為這片土地帶來了戰爭。\n\n他們征服整個世界之前，絕對不會停手。', '', 28153),
(148976, 'zhTW', '', '勇士，部落和聯盟已經全面開戰了。', 28153),
(148975, 'zhTW', '這座島上的艾澤萊晶岩數量非常可觀。附近應該還有一大簇晶岩才對。', '', 28153),
(148974, 'zhTW', '艾澤萊晶岩探測器啟動了！這樣就看得到整座島的情況了。', '', 28153),
(148973, 'zhTW', '瑟沙利斯是我們敬愛的羅亞。\n\n在謎思拉克斯侵襲我們的土地並威脅要毀滅我們的時候，是她挺身阻止，犧牲自己的生命讓我們存活下來。\n\n不像那些無信者，我們還是能感覺到她的存在，而且相信總有一天她會回到我們身邊。', '', 28153),
(148972, 'zhTW', '他自稱為科爾塞克皇帝，但很久以前他是守護者的一員，身負保護墓穴的重任。\n\n他對戰爭的渴望和我們羅亞所象徵的一切背道而馳，但他毀謗並違背了她，發起大軍要征服整個祖達薩。', '', 28153),
(148971, 'zhTW', '我們會永遠記得我們的羅亞對我們的付出。', '我們會永遠記得我們的羅亞對我們的付出。', 28153),
(148970, 'zhTW', '', '這位勇士，謝謝你。我已經派人去解讀這些文本的內容，希望他們能找到對抗血神的相關資訊。', 28153),
(148969, 'zhTW', '', '我想這裡還是可能藏有封印或消滅古翰的知識。快去找找看有沒有任何對我們有用處的聖物，或是文本紀錄。', 28153),
(148968, 'zhTW', '我們的信仰讓我們堅強。', '我們的信仰讓我們堅強。', 28153),
(148966, 'zhTW', '我們會不計一切代價保衛神廟。', '我們會不計一切代價保衛神廟。', 28153),
(148965, 'zhTW', '我們不會拋棄神廟。', '我們不會拋棄神廟。', 28153),
(148962, 'zhTW', '一艘船艦進入地城。派克表示他非常擔心，為何一艘載了村民的船會駛入他組織的聖所。', '一艘船艦進入地城。派克表示他非常擔心，為何一艘載了村民的船會駛入他組織的聖所。', 28153),
(148959, 'zhTW', '什麼事？', '什麼事？', 28153),
(148958, 'zhTW', '我在這裡就能強烈地感受到。來者不善。', '', 28153),
(148955, 'zhTW', '我好奇老爹在這下面做什麼…', '', 28153),
(148954, 'zhTW', '我們得趕快離開，我可以想辦法讓我們晃過那些守衛。\n\n準備好要出發的時候，就告訴我一聲！', '', 28153),
(148953, 'zhTW', '快讓開！', '', 28153),
(148952, 'zhTW', '繼續往右！我好像看到出口了！', '', 28153),
(148946, 'zhTW', '很好！我們可以利用這些東西，做出很棒的弓箭和護甲。', '', 28153),
(148945, 'zhTW', '納茲米爾非常危險，如果你找對地方，會發現許多可用的資源。海岸邊有許多野生的動植物，幫我們的士兵帶點補給回來吧。', '', 28153),
(148944, 'zhTW', '我們要怎麼做，$p？', '', 28153),
(148943, 'zhTW', '', '厄運！', 28153),
(148942, 'zhTW', '', '你應該向希歐克回報！他一定很高興能重新掌控礦坑。', 28153),
(148941, 'zhTW', '', '我們辦到了！', 28153),
(148940, 'zhTW', '', '我的死亡…一直…來自…古翰…？', 28153),
(148939, 'zhTW', '', '古翰之血！', 28153),
(148938, 'zhTW', '我會在實驗室等你！', '我會在實驗室等你！', 28153),
(148936, 'zhTW', '前面那裡就是神廟。', '', 28153),
(148935, 'zhTW', '我們要盡一切所能，不能讓他得逞。', '', 28153),
(148934, 'zhTW', '他率領無信者四處征戰，找尋剩下的鑰匙，這樣他才能破除阿圖亞曼周圍的屏障，運用其中的力量來征服祖達薩。', '', 28153),
(148933, 'zhTW', '自從科爾塞克背叛以後，無信者在這片大地掀起了戰火。', '', 28153),
(148932, 'zhTW', '很久以前，我們遵從羅亞的教誨，全都一體同心。', '', 28153),
(148931, 'zhTW', '我們的神廟是對抗無信者的最後防線。', '', 28153),
(148930, 'zhTW', '部落的戰士們，回應戰鬥的呼喚！給我們的敵人一個痛快。', '', 28153),
(148929, 'zhTW', '你需要托爾托，對吧？', '你需要托爾托，對吧？', 28153),
(148928, 'zhTW', '帶個托爾托走吧！讓他們活著，或者把他們的殼當成儲藏庫。', '帶個托爾托走吧！讓他們活著，或者把他們的殼當成儲藏庫。', 28153),
(148927, 'zhTW', '還有人要加碼嗎？剛從納茲米爾朝聖途中抓來的托爾托！', '還有人要出價嗎？剛從納茲米爾朝聖途中抓來的托爾托！', 28153),
(148925, 'zhTW', '再也遇不到品質這麼好的狐狸人囉！', '再也遇不到品質這麼好的狐狸人囉！', 28153),
(148924, 'zhTW', '健康狐狸人都在這裡，活蹦亂跳的！', '健康狐狸人都在這裡，活蹦亂跳的！', 28153),
(148923, 'zhTW', '還有人要競標狐狸人嗎？他們是很好的奴隸！', '還有人要競標狐狸人嗎？他們是很好的奴隸！', 28153),
(148922, 'zhTW', '必須阻止無信者！', '必須阻止無信者！', 28153),
(148921, 'zhTW', '我應該能夠自行前往安全處。', '我應該能夠自行前往安全處。', 28153),
(148920, 'zhTW', '謝謝你，接下來的路我可以自己走。', '謝謝你，接下來的路我可以自己走。', 28153),
(148919, 'zhTW', '為那些來不及獲救的人報仇。', '為那些來不及獲救的人報仇。', 28153),
(148918, 'zhTW', '你根本不知道他們如何折磨我們…', '你根本不知道他們如何折磨我們…', 28153),
(148917, 'zhTW', '小心一點，$p。你可是直搗黃龍。', '', 28153),
(148916, 'zhTW', '等你取回科爾塞克的石頭，就到那裡跟我會合。', '', 28153),
(148910, 'zhTW', '你竟敢踏進這片狩獵場！', '你竟敢踏進這片狩獵場！', 28153),
(148909, 'zhTW', '你會為此付出代價！', '你會為此付出代價！', 28153),
(148908, 'zhTW', '聯盟在這裡沒有容身之處！', '聯盟在這裡沒有容身之處！', 28153),
(148907, 'zhTW', '這座貯肉所屬於贊達拉！', '這座貯肉所屬於贊達拉！', 28153),
(148906, 'zhTW', '你們儘管浪費時間繼續討論好了。', '', 28153),
(148905, 'zhTW', '', '通往外面，如果那傢伙可以信任的話。', 28153),
(148904, 'zhTW', '這條路通往哪裡？', '', 28153),
(148903, 'zhTW', '', '這個味道…很臭。', 28153),
(148902, 'zhTW', '', '讓那些鮮血食人妖知道我們不會再逃避了。做得好。', 28153),
(148901, 'zhTW', '', '阻止…他們…', 28153),
(148900, 'zhTW', '', '沒人能從第七軍團眼皮底下溜走。受死吧，骯髒的部落！', 28153),
(148899, 'zhTW', '', '根據斥候回報，鮮血食人妖在附近集結。去讓他們知道，惹火贊達拉會有什麼下場。', 28153),
(148898, 'zhTW', '', '你別想再往前一步！', 28153),
(148897, 'zhTW', '', '這是無效力場，我沒辦法施法！', 28153),
(148896, 'zhTW', '真可怕的巫毒法術。薩莉瑟拉？', '', 28153),
(148895, 'zhTW', '', '等我一下。我試了很久都逃不出這個籠子。', 28153),
(148894, 'zhTW', '', '你永遠破解不了我的詛咒！', 28153),
(148893, 'zhTW', '這裡的任何一隻野獸未來都有可能為部落效力。我們不能讓這種事發生。', '', 28153),
(148892, 'zhTW', '就算猛獸的數量很快就能恢復，部落想重新培育馴獸者可沒那麼容易。做得好！', '', 28153),
(148891, 'zhTW', '贊達拉保護區有許多能作戰的猛獸，但必須經過訓練才能派上用場。對猛獸下毒，把馴獸者引出來，他們才是你真正的目標。', '', 28153),
(148890, 'zhTW', '', '你最好沒說錯，祖爾。', 28153),
(148889, 'zhTW', '走錯了，另一條路才對。', '', 28153),
(148888, 'zhTW', '走這裡！', '', 28153),
(148887, 'zhTW', '', '我們要怎麼離開這裡？', 28153),
(148886, 'zhTW', '', '多虧有你，我們才能朝阻止鮮血食人妖的目標更進一步。', 28153),
(148885, 'zhTW', '', '我感覺到附近有種邪惡的魔精。一定是鮮血食人妖！把他們找出來，然後制止他們！', 28153),
(148884, 'zhTW', '', '趕快走！', 28153),
(148883, 'zhTW', '', '封鎖監獄！', 28153),
(148879, 'zhTW', '撥雲見日出…風暴終散去…', '', 28153),
(148878, 'zhTW', '我是風暴的使者！', '', 28153),
(148877, 'zhTW', '之後再好好介紹吧。', '', 28153),
(148876, 'zhTW', '', '我們代表部落前來，我是薩莉瑟拉，這位是洛克漢。', 28153),
(148875, 'zhTW', '', '嗯…謝謝。先知跟我說你們是盟友。', 28153),
(148874, 'zhTW', '哈哈哈，好啊，我記得你。你就是那個可惡的…', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148872, 'zhTW', '啊，公主，正如我所說，護衛來了。', '', 28153),
(148871, 'zhTW', '$n，我們走吧。這邊。', '', 28153),
(148870, 'zhTW', '', '', 28153),
(148868, 'zhTW', '', '', 28153),
(148867, 'zhTW', '照計畫進行，我隨後就到。', '', 28153),
(148858, 'zhTW', '', '好吧…薩魯法爾霸王，既然你已經確定…', 28153),
(148857, 'zhTW', '我非常確定。Lok\'tar。', '', 28153),
(148856, 'zhTW', '你不跟我們一起走了。', '', 28153),
(148855, 'zhTW', '你我都知道，你們不是來救我的。你們要找的人還在更裡面。', '', 28153),
(148854, 'zhTW', '根據這些報告，我認為帝王走訪市場的時候，最容易受到攻擊，那就在附近。', '', 28153),
(148853, 'zhTW', '我想這個還是交給你來比較好。', '', 28153),
(148852, 'zhTW', '', '我們會引開敵人的注意。小心點。', 28153),
(148851, 'zhTW', '我先往前找出俘虜。你們要掩護我。', '', 28153),
(148850, 'zhTW', '第七軍團防守嚴密。看來人類很怕我們救走囚犯。', '', 28153),
(148849, 'zhTW', '待會見吧。祝你們好運。', '', 28153),
(148848, 'zhTW', '那是我們的逃生工具。救出俘虜之後就趕快上船。', '', 28153),
(148847, 'zhTW', '我幫你們準備了能死得乾淨俐落的辦法。無計可施的時候就用吧。', '', 28153),
(148846, 'zhTW', '要是你們被抓了，大酋長和部落的人會對你們的行動一概予以否認。', '', 28153),
