(148661, 'zhTW', '我勇於面對難關。', '我勇於面對難關。', 28153),
(148660, 'zhTW', '事情很不妙，對吧？', '事情很不妙，對吧？', 28153),
(148659, 'zhTW', '有什麼內陸的消息嗎？', '有什麼內陸的消息嗎？', 28153),
(148658, 'zhTW', '這裡恐怕沒有和平的時候。', '這裡恐怕沒有和平的時候。', 28153),
(148657, 'zhTW', '很高興能認識你。', '很高興能認識你。', 28153),
(148656, 'zhTW', '有聽到什麼風聲嗎？', '有聽到什麼風聲嗎？', 28153),
(148655, 'zhTW', '請問你找我有什麼事呢？', '請問你找我有什麼事呢？', 28153),
(148654, 'zhTW', '幸會、幸會。', '幸會、幸會。', 28153),
(148653, 'zhTW', '天啊…居然已經這麼晚了。你是不是該走啦？', '天啊…居然已經這麼晚了。你是不是該走啦？', 28153),
(148652, 'zhTW', '你聽到了嗎？好像有人在叫你的名字，就是那裡。聽起來好像很緊急！', '你聽到了嗎？好像有人在叫你的名字，就是那裡。聽起來好像很緊急！', 28153),
(148651, 'zhTW', '你總有別的事可以做吧？隨便什麼事情都好！', '你總有別的事可以做吧？隨便什麼事都好！', 28153),
(148650, 'zhTW', '我能為你做什麼？', '我能為你做什麼？', 28153),
(148649, 'zhTW', '以總帥之名祝福你，朋友！', '以總帥之名祝福你，朋友！', 28153),
(148648, 'zhTW', '祝你安好。', '祝你安好。', 28153),
(148647, 'zhTW', '喂！', '喂！', 28153),
(148646, 'zhTW', '救命啊！我被壓榨了！', '救命啊！我被壓榨了！', 28153),
(148645, 'zhTW', '我有點不太喜歡你這個人。', '我有點不太喜歡你這個人。', 28153),
(148644, 'zhTW', '有人說過你怪怪的嗎？', '有人說過你怪怪的嗎？', 28153),
(148643, 'zhTW', '願大海滋養你。', '願大海滋養你。', 28153),
(148642, 'zhTW', '每條路難免都有水坑。', '每條路難免都有水坑。', 28153),
(148641, 'zhTW', '我們會奪回屬於我們的一切。', '我們會奪回屬於我們的一切。', 28153),
(148640, 'zhTW', '以前的日子比較單純。', '以前的日子比較單純。', 28153),
(148639, 'zhTW', '多一個人就多一份力量。', '多一個人就多一份力量。', 28153),
(148638, 'zhTW', '你是外地人，對吧？', '你是外地人，對吧？', 28153),
(148637, 'zhTW', '想花錢嗎？我這裡有好東西。', '想花錢嗎？我這裡有好東西。', 28153),
(148636, 'zhTW', '這裡的東西是全庫爾提拉斯最好的。', '這裡的東西是全庫爾提拉斯最好的。', 28153),
(148635, 'zhTW', '來看看我有什麼好東西。', '來看看我有什麼好東西。', 28153),
(148634, 'zhTW', '旅途平安。', '旅途平安。', 28153),
(148633, 'zhTW', '謝謝你光顧。', '謝謝你光顧。', 28153),
(148632, 'zhTW', '歡迎再來。', '歡迎再來。', 28153),
(148631, 'zhTW', '祝你一路平安。', '祝你一路平安。', 28153),
(148630, 'zhTW', '祝你一路順風。', '祝你一路順風。', 28153),
(148629, 'zhTW', '要永遠看向大海。', '要永遠看向大海。', 28153),
(148628, 'zhTW', '航行順利。', '航行順利。', 28153),
(148627, 'zhTW', '祝你安好。', '祝你安好。', 28153),
(148626, 'zhTW', '喂！', '喂！', 28153),
(148625, 'zhTW', '準備起錨。', '準備起錨。', 28153),
(148624, 'zhTW', '保持火藥乾燥。', '保持火藥乾燥。', 28153),
(148623, 'zhTW', '永遠忠誠。', '永遠忠誠。', 28153),
(148622, 'zhTW', '有麻煩了嗎？', '有麻煩了嗎？', 28153),
(148621, 'zhTW', '我們離目標不遠了。', '', 28153),
(148620, 'zhTW', '普勞德摩爾的精兵，任你差遣。', '普勞德摩爾的精兵，任你差遣。', 28153),
(148619, 'zhTW', '祝你一路平安。', '祝你一路平安。', 28153),
(148618, 'zhTW', '祝你一路順風。', '祝你一路順風。', 28153),
(148617, 'zhTW', '要永遠看向大海。', '要永遠看向大海。', 28153),
(148616, 'zhTW', '航行順利。', '航行順利。', 28153),
(148615, 'zhTW', '暴掠龍的胃袋真棒！可以煮、可以風乾、可以煎可以炒…嗯？我在想什麼？喔，我在想，該吃午飯了。', '', 28153),
(148614, 'zhTW', '旅途平安。', '旅途平安。', 28153),
(148613, 'zhTW', '很高興你能大駕光臨。', '很高興你能大駕光臨。', 28153),
(148612, 'zhTW', '歡迎再來啊！', '歡迎再來啊！', 28153),
(148611, 'zhTW', '我老婆總是說暴掠龍什麼都吃！嗯，這樣的話，那些龍應該都是鐵胃！去幫我帶一些暴掠龍的胃回來…記得別讓我老婆發現。', '', 28153),
(148610, 'zhTW', '嗯…想買點什麼東西嗎？', '嗯…想買點什麼東西嗎？', 28153),
(148609, 'zhTW', '有事要報告嗎？', '有事要報告嗎？', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148608, 'zhTW', '這裡的東西是全庫爾提拉斯最好的。', '這裡的東西是全庫爾提拉斯最好的。', 28153),
(148607, 'zhTW', '我可不會賣次等貨，朋友。', '我可不會賣次等貨，朋友。', 28153),
(148606, 'zhTW', '我能為你做什麼？', '我能為你做什麼？', 28153),
(148605, 'zhTW', '以總帥之名祝福你，朋友！', '以總帥之名祝福你，朋友！', 28153),
(148604, 'zhTW', '注意保暖。', '注意保暖。', 28153),
(148603, 'zhTW', '祝你安好。', '祝你安好。', 28153),
(148602, 'zhTW', '想喝杯茶嗎？', '想喝杯茶嗎？', 28153),
(148601, 'zhTW', '千萬別走暗巷。', '千萬別走暗巷。', 28153),
(148600, 'zhTW', '一定要堅強。', '一定要堅強。', 28153),
(148599, 'zhTW', '城裡現在很危險。', '城裡現在很危險。', 28153),
(148598, 'zhTW', '有什麼發現的話就喊一聲！你將名留青史。', '', 28153),
(148597, 'zhTW', '如果我們找到鑰匙，帝王就能讓世界臣服於塞斯拉克的光輝之下！我一直想四處走走看看！', '', 28153),
(148596, 'zhTW', '沉睡者將會甦醒。', '', 28153),
(148595, 'zhTW', '要是他真的醒來，我們有人能夠安然無恙嗎？', '', 28153),
(148594, 'zhTW', '你認為真的有鑰匙嗎？', '', 28153),
(148593, 'zhTW', '科爾塞克皇帝相信，等我們找到鑰匙，我們就能讓塞斯拉克再次團結在一起。', '', 28153),
(148592, 'zhTW', '你聽到什麼聲音了嗎？', '', 28153),
(148591, 'zhTW', '來這裡為帝國做事，老闆。', '', 28153),
(148590, 'zhTW', '那些只會傻笑的「虔信者」很快就會低頭求饒。', '', 28153),
(148589, 'zhTW', '狂風在呼嘯。', '狂風在呼嘯。', 28153),
(148588, 'zhTW', '最好注意保暖。', '最好注意保暖。', 28153),
(148587, 'zhTW', '信使說鑰匙就在這裡。我們越快找到它，就能越早離開這個令我毛骨聳然的地方。', '', 28153),
(148586, 'zhTW', '注意保暖。', '注意保暖。', 28153),
(148585, 'zhTW', '普勞德摩爾一家會保護我們，他們總是如此。', '普勞德摩爾一家會保護我們，他們總是如此。', 28153),
(148584, 'zhTW', '祝你一路風平浪靜。', '祝你一路風平浪靜。', 28153),
(148583, 'zhTW', '這裡恐怕沒有和平的時候。', '這裡恐怕沒有和平的時候。', 28153),
(148582, 'zhTW', '有什麼內陸的消息嗎？', '有什麼內陸的消息嗎？', 28153),
(148581, 'zhTW', '事情很嚴重，對吧？', '事情很嚴重，對吧？', 28153),
(148580, 'zhTW', '記得回來看看新貨，朋友。', '記得回來看看新貨，朋友。', 28153),
(148579, 'zhTW', '我們每天都有特別的東西。', '我們每天都有特別的東西。', 28153),
(148578, 'zhTW', '隨時回來看看。', '隨時回來看看。', 28153),
(148577, 'zhTW', '慢慢看喔。', '慢慢看喔。', 28153),
(148576, 'zhTW', '來，我們打個商量。', '來，我們打個商量。', 28153),
(148575, 'zhTW', '事情…還沒…結束…', '', 28153),
(148574, 'zhTW', '你太遲了…', '', 28153),
(148573, 'zhTW', '別想阻止我們…', '', 28153),
(148572, 'zhTW', '這裡…屬於我們…', '', 28153),
(148571, 'zhTW', '我會…回到瑟洛斯…', '', 28153),
(148570, 'zhTW', '來談談生意吧？', '來談談生意吧？', 28153),
(148569, 'zhTW', '我們一定會報仇！', '', 28153),
(148568, 'zhTW', '絕不容情！', '', 28153),
(148567, 'zhTW', '佐司特會奪回這片土地！', '', 28153),
(148566, 'zhTW', '你會向勾拉圖爾屈服！', '', 28153),
(148565, 'zhTW', '我…甦醒了！', '', 28153),
(148564, 'zhTW', '你總有別的事可以做吧？隨便什麼事都好！', '你總有別的事可以做吧？隨便什麼事都好！', 28153),
(148563, 'zhTW', '你聽到了嗎？好像有人在叫你的名字，就是那裡。聽起來好像很緊急！', '你聽到了嗎？好像有人在叫你的名字，就是那裡。聽起來好像很緊急！', 28153),
(148562, 'zhTW', '天啊…居然已經這麼晚了。你是不是該走了？', '天啊…居然已經這麼晚了。你是不是該走了？', 28153),
(148561, 'zhTW', '你先忙吧。', '你先忙吧。', 28153),
(148560, 'zhTW', '穩定向前。', '穩定向前。', 28153),
(148559, 'zhTW', '保持冷靜，繼續前進。', '保持冷靜，繼續前進。', 28153),
(148553, 'zhTW', '我們會把這地方夷為平地！', '學學妮莎的勇氣！', 28153),
(148552, 'zhTW', '祝你好運。', '祝你好運。', 28153),
(148551, 'zhTW', '下個被我看到的無信者完蛋了！', '我要好好善用這把劍！', 28153),
(148550, 'zhTW', '拿起武器的感覺真好。', '狐狸人才不好欺負！', 28153),
(148549, 'zhTW', '幸會、幸會。', '幸會、幸會。', 28153),
(148548, 'zhTW', '請問你找我有什麼事呢？', '請問你找我有什麼事呢？', 28153),
(148547, 'zhTW', '', '噢，這些真是太棒了！不用管拉爾高興不高興，他自己會想通的。', 28153),
(148546, 'zhTW', '', '我丈夫不想幫我們的藥劑師收集翼手龍的唾液。他現在越來越軟弱了。到那裡去幫我把腺體全都拿回來！', 28153),
(148545, 'zhTW', '太好了，接下來我們的人會拼命研究這些資料。', '', 28153),
(148544, 'zhTW', '有聽到什麼風聲嗎？', '有聽到什麼風聲嗎？', 28153),
(148543, 'zhTW', '很高興能認識你。', '很高興能認識你。', 28153),
(148542, 'zhTW', '有很多托爾托人死在那些鮮血食人妖屠夫手上，不過我們還是可以保存他們的知識。請盡可能地把你看到的卷軸帶回來！', '', 28153),
(148541, 'zhTW', '救命啊！我被壓榨了！', '救命啊！我被壓榨了！', 28153),
(148540, 'zhTW', '', '這…不可能…', 28153),
(148539, 'zhTW', '啊，這就是極權統治下的社會暴力！', '啊，這就是極權統治下的社會暴力！', 28153),
(148538, 'zhTW', '', '我的魔法…失效了？', 28153),
(148537, 'zhTW', '', '我原本能得到…力量…', 28153),
(148536, 'zhTW', '除非他們的靈魂重獲自由，否則我無法接受新的信徒。這違反我的榮譽感。', '', 28153),
(148535, 'zhTW', '你剛剛對我丟了一把刀嗎？', '你剛剛對我丟了一把刀嗎？', 28153),
(148534, 'zhTW', '', '力量…在流逝…', 28153),
(148533, 'zhTW', '', '姐妹們會殺了你…', 28153),
(148532, 'zhTW', '', '儀式需要用你的血！', 28153),
(148531, 'zhTW', '', '拿你當祭品剛剛好！', 28153),
(148530, 'zhTW', '', '向禍心女巫會臣服吧！', 28153),
(148529, 'zhTW', '', '母親，給我力量！', 28153),
(148528, 'zhTW', '最後當我咬穿首領的心臟時，她卻對我的信徒下了詛咒，讓他們的靈魂永遠受到折磨。', '', 28153),
(148527, 'zhTW', '', '我為女巫會而生！', 28153),
(148526, 'zhTW', '我不在乎她死了。正好少個人阻礙我。', '', 28153),
(148525, 'zhTW', '她竟然使用巫術來向我報仇…', '', 28153),
(148524, 'zhTW', '於是我開始獵殺剩下的納迦，一個也不放過…', '', 28153),
(148523, 'zhTW', '我的工作就是我的一切！忘了佩圖拉，忘了班傑明，這才是我的使命。', '', 28153),
(148522, 'zhTW', '我白手起家！我創立這項事業，是為了讓我的妻子與家人餬口。', '', 28153),
(148521, 'zhTW', '榮耀歸於威奎斯特。', '榮耀歸於威奎斯特。', 28153),
(148520, 'zhTW', '你知道，我並非一直都是一家成功木材公司的老闆。', '', 28153),
(148519, 'zhTW', '千萬不要插手女巫的事。', '千萬不要插手女巫的事。', 28153),
(148518, 'zhTW', '看到陌生人都要小心。', '看到陌生人都要小心。', 28153),
(148517, 'zhTW', '別靠近我，內陸人。', '別靠近我，內陸人。', 28153),
(148516, 'zhTW', '你是敵是友？', '你是敵是友？', 28153),
(148515, 'zhTW', '請說明來意。', '請說明來意。', 28153),
(148514, 'zhTW', '在幾個世紀之前，納迦攻擊過這座神廟，我到的時候已經太晚了，信徒無人倖免。', '', 28153),
(148513, 'zhTW', '我很認同托塔卡部族對付納迦的決心，但我無法保護他們。', '', 28153),
(148512, 'zhTW', '大海賜予你恩惠。', '大海賜予你恩惠。', 28153),
(148511, 'zhTW', '每條路都難免有水坑。', '每條路都難免有水坑。', 28153),
(148510, 'zhTW', '我們會奪回屬於我們的一切。', '我們會奪回屬於我們的一切。', 28153),
(148509, 'zhTW', '以前的日子單純多了。', '以前的日子單純多了。', 28153),
(148508, 'zhTW', '多一個人就多一份力量。', '多一個人就多一份力量。', 28153),
(148507, 'zhTW', '你是外地人，對吧？', '你是外地人，對吧？', 28153),
(148506, 'zhTW', '斯陀頌恩會恢復純淨。', '斯陀頌恩會恢復純淨。', 28153),
(148505, 'zhTW', '小心深海裡的危險。', '小心深海裡的危險。', 28153),
(148504, 'zhTW', '願你的航行一路順利。', '願你的航行一路順利。', 28153),
(148503, 'zhTW', '我們一定會度過這個難關。', '我們一定會度過這個難關。', 28153),
(148502, 'zhTW', '歡迎能為大海帶來榮耀的人。', '歡迎能為大海帶來榮耀的人。', 28153),
(148501, 'zhTW', '浪潮歡迎你。', '浪潮歡迎你。', 28153),
(148500, 'zhTW', '我們會讓這座谷地恢復原狀。', '我們會讓這座谷地恢復原狀。', 28153),
(148499, 'zhTW', '隨時小心，提高警覺。', '隨時小心，提高警覺。', 28153),
(148498, 'zhTW', '記住風暴的歌聲。', '記住風暴的歌聲。', 28153),
(148497, 'zhTW', '我們絕不動搖。', '我們絕不動搖。', 28153),
(148496, 'zhTW', '斯陀頌恩不會被擊垮。', '斯陀頌恩不會被擊垮。', 28153),
(148495, 'zhTW', '你從很遠的地方來的吧。', '你從很遠的地方來的吧。', 28153),
(148493, 'zhTW', '你也是。$n，你還真有點本事。如果你到了沃魯敦，記得找我。', '', 28153),
(148492, 'zhTW', '再會了，金提基，你要活下來。', '', 28153),
(148491, 'zhTW', '這個交給我。', '', 28153),
(148490, 'zhTW', '計畫定下了，開始行動。', '', 28153),
(148489, 'zhTW', '嘿！這是我幹過最瘋狂的事情。', '', 28153),
(148488, 'zhTW', '祖拉金死了！我們趕快離開吧。', '', 28153),
(148487, 'zhTW', '做得好！保持下去！', '', 28153),
(148486, 'zhTW', '咿哎！', '咿哎！', 28153),
(148485, 'zhTW', '不要吃我！', '不要吃我！', 28153),
(148484, 'zhTW', '呃！', '呃！', 28153),
(148483, 'zhTW', '父親到底在做什麼，怎麼會這樣？', '', 28153),
(148482, 'zhTW', '蜂蜜怎麼會自己動起來了呢？', '', 28153),
(148481, 'zhTW', '<喘氣> 呣, $p… 蜂蜜還活著嗎？', '', 28153),
(148480, 'zhTW', '謝謝，陌生人。', '謝謝，陌生人。', 28153),
(148479, 'zhTW', '我要給塞斯拉克人好看，讓他們什麼都帶不走。', '我要讓塞斯拉克人連片破銅爛鐵都帶不走。', 28153),
(148478, 'zhTW', '該來玩個我叫做「蛇與狐」的小遊戲了…', '該來玩個我叫做「蛇與狐」的小遊戲了…', 28153),
(148477, 'zhTW', '耶呼！我自由了！你沒吃掉我！', '耶呼！我自由了！你沒吃掉我！', 28153),
(148476, 'zhTW', '又來了，這已經是第二次了。', '又來了，這已經是第二次了。', 28153),
(148475, 'zhTW', '', '你沒被沙漠吞噬真是太好了，$n！', 28153),
(148473, 'zhTW', '偉大的羅亞，這是托塔卡部族獻上的祭品。', '偉大的羅亞，這是托塔卡部族獻上的祭品。', 28153),
(148472, 'zhTW', '放下！', '', 28153),
(148471, 'zhTW', '沒那麼快！', '', 28153),
(148470, 'zhTW', '你會後悔的。', '', 28153),
(148469, 'zhTW', '如果我是你的話，我不會那麼做。', '', 28153),
(148468, 'zhTW', '還回來！', '', 28153),
(148467, 'zhTW', '別天真了！那是我的。', '', 28153),
(148466, 'zhTW', '那不是你該拿的東西，朋友。', '', 28153),
(148463, 'zhTW', '錯誤的選擇。', '', 28153),
(148462, 'zhTW', '我一向喜歡好好打一場。', '', 28153),
(148461, 'zhTW', '你就準備面對後果吧！', '', 28153),
(148460, 'zhTW', '就是你！', '', 28153),
(148459, 'zhTW', '你會後悔的！', '', 28153),
(148458, 'zhTW', '不，你今天不行！', '', 28153),
(148456, 'zhTW', '小心你的腳下。', '', 28153),
(148455, 'zhTW', '我的望遠鏡放在北邊能俯瞰到坑洞的斷崖那邊，較低的那個。', '', 28153),
(148454, 'zhTW', '', '原來是恐角龍恐龍學！真有趣，快把這些東西放在卡裘碰不到的地方。', 28153),
(148453, 'zhTW', '', '我找到這組老舊的卷軸，但是我不知道它們的功用。你先去幫我試試看卷軸有什麼效果。一定會很好玩！', 28153),
(148452, 'zhTW', '用神像把它炸毀！', '', 28153),
(148451, 'zhTW', '快跑！', '', 28153),
(148450, 'zhTW', '啊啊啊！', '', 28153),
(148449, 'zhTW', '呃…我覺得不太對勁，我感覺到那邊有邪惡的鮮血魔法在蠢動…', '', 28153),
(148448, 'zhTW', '你辦到了！這就是祖拉金的下場。', '', 28153),
(148447, 'zhTW', '哈哈！我一定要講給帕骷聽！', '', 28153),
(148446, 'zhTW', '夜裔精靈想到怎麼處理席帕拉的入侵者了。這一定很有趣。', '', 28153),
(148420, 'zhTW', '', '做得好，也許有一天這些水域又會變得安全。', 28153),
(148419, 'zhTW', '', '你們兩個唱夠了！', 28153),
(148418, 'zhTW', '', '很好，我們全在這裡。別浪費任何時間了。', 28153),
(148416, 'zhTW', '這位老兄，謝謝你啦。那些鮮血食人妖死有餘辜！', '', 28153),
(148415, 'zhTW', '那些混帳居然敢褻瀆羅亞的屍體！我絕不允許他們這樣做！殺光他們！', '', 28153),
(148414, 'zhTW', '', '誰是最棒的贊達拉小咬咬啊？就是你！', 28153),
(148413, 'zhTW', '', '我們強大的盟友必須學習怎麼和敵人打仗，你就教這小不點怎麼戰鬥吧。', 28153),
(148412, 'zhTW', '聽到的內容如下：\n\n有一次，偉大的羅亞向一群追隨者開口道：\n\n『如同美洲豹可以一連追蹤獵物好幾天，智者無時無刻都是耐心十足。愚者的人生被欲望和情緒所掌控，很快就會在叢林中丟掉性命。\n\n如同叢林能夠賜予生命，它也能夠賜予死亡。有遠見的人知道自然不屬於他們，反而是他們屬於自然。這些人懂得順應自然規律，只拿取維生所需的東西。』\n\n聽到這些話語，伊拉卡‧諾‧金布爾的追隨者不禁心生敬意，不驕不躁。', '', 28153),
(148411, 'zhTW', '聽到的內容如下：\n\n有一次，偉大的羅亞向一群追隨者開口道：\n\n『如同一個國王不會用他最珍貴的寶藏換成一坯土，高貴的人也不會為了名利犧牲自己的正直，這樣終將一生無憾。\n\n如同川流不息的河水鑿開峽谷，所有的豐功偉業都是源自於努力不懈。只要秉持不屈不撓的決心，失敗永遠不會打倒你。』\n\n聽到這些話語，伊拉卡‧諾‧金布爾的追隨者不禁心生嚮往，力行實踐。', '', 28153),
(148410, 'zhTW', '聽到的內容如下：\n\n有一次，偉大的羅亞向一群追隨者開口道：\n\n『如同受傷的老虎跳過岩石和裂口，面對恐懼時，勇敢的人不會浪費時間怯懦。隨時隨地勇猛精進，獵物就不會消失在視線中。\n\n如同腐朽吞噬叢林中的百花，年紀也吞噬青春的精力。力量的來源並非體力，而是不會被年紀摧毀的堅定意志。』\n\n聽到這些話語，伊拉卡‧諾‧金布爾的追隨者不禁心生勇氣，信心滿滿。', '', 28153),
(148408, 'zhTW', '伊拉卡‧諾‧金布爾，他亦是虎之羅亞、獸王、大貓之王及獵物主宰。', '', 28153),
(148400, 'zhTW', '我身上的疤比你說的語言還要老。', '', 28153),
(148399, 'zhTW', '我要找個年輕人，要會做事又肯跟邪惡的勢力戰鬥…當然，會有錢拿啦。', '', 28153),
(148398, 'zhTW', '', '你是來找諾菈聊天的嗎？', 28153),
(148397, 'zhTW', '這裡，小鱗子！', '這裡，小鱗子！', 28153),
(148396, 'zhTW', '等我們自由後，你不會喜歡我們。', '等我們自由後，你不會喜歡我們。', 28153),
(148395, 'zhTW', '好啦！好啦！', '好啦！好啦！', 28153),
(148394, 'zhTW', '啊！給我下去！', '啊！給我下去！', 28153),
(148393, 'zhTW', '<雕像上似乎有些痕跡。上頭所記述的事物－假如確實有的話－在很久以前就已經消逝了。>', '', 28153),
(148392, 'zhTW', '<雕像上似乎有些痕跡。上頭所記述的事物－假如確實有的話－在很久以前就已經消逝了。>', '<雕像上似乎有些痕跡。上頭所記述的事物－假如確實有的話－在很久以前就已經消逝了。>', 28153),
(148391, 'zhTW', '<雕像上似乎有些痕跡。上頭所記述的事物－假如確實有的話－在很久以前就已經消逝了。>', '', 28153),
(148389, 'zhTW', '索利斯被謀殺了，但是發生在他能安全保護他的鑰匙之錢。我們中仍對瑟沙利斯忠誠的人被迫離鄉背井並躲藏起來。從那以後我們就一直在對抗無信者。', '', 28153),
(148388, 'zhTW', '科爾塞克組織了一支志同道合的塞斯拉克軍隊，然後他們就開始屠殺任何擋他們道的人。', '', 28153),
(148387, 'zhTW', '', '我們必須警告公主才行。', 28153),
(148386, 'zhTW', '', '武器…賈克拉傑在找的一定就是這個！原來是克蘇拉希…', 28153),
(148385, 'zhTW', '他秘密謀畫要挖掘克蘇拉希將軍，並用他作為征服整個大陸的武器。', '', 28153),
(148384, 'zhTW', '多年來，科爾塞克逐漸厭倦我們的生活方式。雖然我們與鄰近的食人妖向來和平相處，科爾塞克卻渴望戰爭。', '', 28153),
(148383, 'zhTW', '多年來，我們過著和平的生活，正如瑟沙利斯所望。我們的土地已毀而我們的羅亞也離開了，但我們適應了下來。我們確信總有一天，瑟沙利斯將會重臨。', '', 28153),
(148382, 'zhTW', '為確保屏障無法被輕易打破，我們各自創造了一把鑰匙。我們用在屏障上的魔法只有在全部三把鑰匙齊聚時才能被解除。於是乎，守衛者便成立了。', '', 28153),
(148381, 'zhTW', '依然忠於瑟沙利斯的人，被迫離開家鄉，四處躲藏。那之後，我們一直在對抗無信者。', '', 28153),
(148380, 'zhTW', '科爾塞克召集了一支跟他想法一致的塞斯拉克軍隊，只要敢反抗他們，一律殺無赦…索利斯首當其衝，不過他死前先把鑰匙藏了起來。', '', 28153),
(148379, 'zhTW', '隨著時間過去，科爾塞克開始渴望戰爭，他暗中計畫，要讓克蘇拉希再次出現，成為他征服這片大陸的武器。', '', 28153),
(148378, 'zhTW', '雖然索利斯十分強大，但是他無法獨力撐起這道屏障，於是我跟科爾塞克一起幫忙，把謎思拉克斯封印在大金字塔裡面。', '', 28153),
(148377, 'zhTW', '我們在現場目睹一切過程，看著他被消滅，心裡很清楚，絕對不能讓謎思拉克斯重返世間。', '', 28153),
(148376, 'zhTW', '多虧羅亞犧牲了自己，我們才得以倖存。雖然她擊敗了克蘇拉希，卻沒能阻止他摧毀放置在阿圖亞曼中心的圓盤。', '', 28153),
(148375, 'zhTW', '很久以前，揭滅者謎思拉克斯現身於這片土地，他所經之處，不分食人妖和塞斯拉克人，只見屍橫遍野。', '', 28153),
(148374, 'zhTW', '這把鑰匙屬於第一個守衛者，他的名字是索利斯，他最後死在科爾塞克手裡。', '', 28153),
(148365, 'zhTW', '', '噢，所以梅納派他那些嘍囉解決他的問題，就如以往一樣。那就來吧，嘍囉。我會像解決其他嘍囉一樣解決你的。', 28153),
(148364, 'zhTW', '一個女巫…為什麼女巫要針對我們公司？我要離開這裡。我要通知我的父親！', '', 28153),
(148361, 'zhTW', '法蘭索瓦注意到你的大錢包，認為你是值得他花時間的人。', '', 28153),
(148360, 'zhTW', '你稍微讓你的錢包鈴鐺作響。', '你稍微讓你的錢包鈴鐺作響。', 28153),
(148359, 'zhTW', '若你能除去那隻蜘蛛…你會幫助到很多人。', '', 28153),
(148358, 'zhTW', '很好…看來你清出了一條路。我想我能自己逃出去。', '', 28153),
(148357, 'zhTW', '法蘭索瓦目中無人地啄你的腳。', '', 28153),
(148356, 'zhTW', '', '', 28153),
(148355, 'zhTW', '', '', 28153),
(148354, 'zhTW', '<將索利斯之石交給瓦里克。>', '<將索利斯之石交給瓦里克。>', 28153),
(148353, 'zhTW', '岸邊安全了！誰知道青蛙的魔力會這麼強？', '', 28153),
(148352, 'zhTW', '納迦在吸取青蛙羅亞的力量！快毀掉營地，阻止他們！', '', 28153),
(148351, 'zhTW', '保佑你，陌生人。我長翅膀的朋友準備好載你到任何你需要去的地方了。', '保佑你，陌生人。我長翅膀的朋友準備好載你到任何你需要去的地方了。', 28153),
(148350, 'zhTW', '我又復甦啦！謝謝你，以後我隨時都會支援你。', '我又復甦啦！謝謝你，以後我隨時都會支援你。', 28153),
(148349, 'zhTW', '伯昂撒姆第保佑你！', '伯昂撒姆第保佑你！', 28153),
(148348, 'zhTW', '我喜歡的石頭！別碰！', '', 28153),
(148347, 'zhTW', '', '我們必須找瓦里克談談。', 28153),
(148345, 'zhTW', '別衝動，如果他們在找瓦里克，也許他們幫得上忙…', '', 28153),
(148344, 'zhTW', '我恢復了！謝謝你，陌生人。', '我恢復了！謝謝你，陌生人。', 28153),
(148342, 'zhTW', '', '看來你帶了幫手一起過來。', 28153),
(148340, 'zhTW', '', '大家先冷靜下來，這個人不是壞人。', 28153),
(148339, 'zhTW', '沒錯！就是這個，尼米，真的，外殼。你必須珍惜外殼…', '', 28153),
(148338, 'zhTW', '整整停止了一分鐘。我感到寒冷。我感到炎熱…我是說…', '', 28153),
(148337, 'zhTW', '而科奧，科奧拿起那把劍…他的眼睛，它們就這樣…掉出去…', '', 28153),
(148336, 'zhTW', '魚鰭與刀刃與嘲笑與黑暗…有血…', '', 28153),
(148335, 'zhTW', '這是海裡面最無聊的哨站…直到一切都改變了…他們來了…', '', 28153),
(148334, 'zhTW', '總之，它很輝煌！也相當恐怖！', '', 28153),
(148333, 'zhTW', '等等，你是有頭有臉的人，對不對？我過去也曾看錯人…', '', 28153),
(148332, 'zhTW', '你怎麼可能沒聽過…每個人都聽過史卡文的渠溝。', '', 28153),
(148331, 'zhTW', '什麼？你從沒聽過史卡文的渠溝？', '', 28153),
(148330, 'zhTW', '你知道史卡文渠溝之戰，對吧？下方深處…', '', 28153),
(148329, 'zhTW', '所以總之呢，科奧與我正在談論那場戰鬥。', '', 28153),
(148328, 'zhTW', '我愛你，有鱗的小朋友', '', 28153),
(148327, 'zhTW', '我看過一次，真是太不可思議了！', '', 28153),
(148326, 'zhTW', '你知道這地方的水底下有火嗎？', '', 28153),
(148325, 'zhTW', '老天，那根本不是現在的重點，真正的重點是…', '', 28153),
(148324, 'zhTW', '嗯，他沒有。他只是看著我，然後壓扁一隻螃蟹…', '', 28153),
(148323, 'zhTW', '你應該會覺得很厲害，對吧？或者至少假裝一下？', '', 28153),
(148322, 'zhTW', '真是讓我傷心。', '', 28153),
(148321, 'zhTW', '我有次找到一個貝殼。很漂亮的貝殼。我跟科奧說了。科奧不在乎。', '', 28153),
(148320, 'zhTW', '我不喜歡藤壺。科奧說喜歡藤壺的人都很邪惡。', '', 28153),
(148318, 'zhTW', '以前科爾塞克和我就是在這兒傳授瑟沙利斯的智慧，一切都變了好多…\n\n現在神聖的場所只存在遺跡中，而瑟沙利斯已被－好一點的話－遺忘。更多時候，是被憎恨。\n\n科爾塞克…你對我們的人民做了什麼，老友？', '', 28153),
(148317, 'zhTW', '藤壺是壞的。你喜歡藤壺嗎，尼米先生？', '', 28153),
(148316, 'zhTW', '我不喜歡藤壺，因為它們讓我的腳很癢。科奧說他也不喜歡藤壺。', '', 28153),
(148315, 'zhTW', '藤壺是壞東西。', '', 28153),
(148314, 'zhTW', '我的朋友科奧，你認識科奧？好吧，朋友，科奧說如果你把弩砲插進腳趾之間，就能順利除去藤壺。', '', 28153),
(148313, 'zhTW', '你不屬於這裡！', '你不屬於這裡！', 28153),
(148312, 'zhTW', '你竟敢挑戰黑鐵矮人！', '你竟敢挑戰黑鐵矮人！', 28153),
(148311, 'zhTW', '見識山嶺之力！', '見識山嶺之力！', 28153),
(148310, 'zhTW', '看我怎麼教訓你！', '看我怎麼教訓你！', 28153),
(148309, 'zhTW', '有本事就來啊！', '有本事就來啊！', 28153),
(148308, 'zhTW', '今天是你的忌日！', '今天是你的忌日！', 28153),
(148307, 'zhTW', '我的怒火會燒死你！', '我的怒火會燒死你！', 28153),
(148306, 'zhTW', '我的火焰…永不…熄滅…', '我的火焰…永不…熄滅…', 28153),
(148305, 'zhTW', '我的族人…會為我…復仇…', '我的族人…會為我…復仇…', 28153),
(148304, 'zhTW', '我的靈魂…在黑鐵砧…安息…', '我的靈魂…在黑鐵砧…安息…', 28153),
(148303, 'zhTW', '真想…再喝一杯…', '真想…再喝一杯…', 28153),
(148302, 'zhTW', '你…該死…', '你…該死…', 28153),
(148301, 'zhTW', '為女王而死…是我的榮耀…', '為女王而死…是我的榮耀…', 28153),
(148300, 'zhTW', '我會在…烈火中…重生…', '我會在…烈火中…重生…', 28153);
