(145276, 'zhTW', '烏娜被黑暗吞沒了。', '烏娜被黑暗吞沒了。', 28153),
(145275, 'zhTW', '', '啊！不要啊！救我！', 28153),
(145273, 'zhTW', '', '開始出現一陣嗡鳴聲，讓你非常不安。', 28153),
(145272, 'zhTW', '', '我求求你！', 28153),
(145271, 'zhTW', '', '發發善心，好嗎？', 28153),
(145270, 'zhTW', '', '求你大發慈悲！', 28153),
(145269, 'zhTW', '', '很不賴嘛。', 28153),
(145268, 'zhTW', '', '真是厲害。', 28153),
(145267, 'zhTW', '', '非常好。', 28153),
(145266, 'zhTW', '', '但現在…還不是時候。', 28153),
(145265, 'zhTW', '', '我知道，總有一天我要回去找爸爸媽媽。', 28153),
(145264, 'zhTW', '', '願熔爐照亮你的道路。', 28153),
(145263, 'zhTW', '', '你帶我看了好多好酷的東西。你真是我最好的朋友！', 28153),
(145262, 'zhTW', '', '我講完了。', 28153),
(145261, 'zhTW', '', '你要為自己做過的事付出代價！', 28153),
(145260, 'zhTW', '', '你走吧！', 28153),
(145259, 'zhTW', '', '再見。', 28153),
(145258, 'zhTW', '', '謝謝你讓我知道這件事！太感謝你了，朋友！', 28153),
(145257, 'zhTW', '', '還是有人活著離開阿古斯？', 28153),
(145256, 'zhTW', '', '我的族人在這裡！他們還活著！', 28153),
(145255, 'zhTW', '', '哇…好美喔…', 28153),
(145254, 'zhTW', '', '那太搞笑啦，朋友。', 28153),
(145253, 'zhTW', '', '它像水一樣在動耶…是發光的湖泊嗎？', 28153),
(145252, 'zhTW', '', '說明你的來意。', 28153),
(145251, 'zhTW', '好啊。', '好啊。', 28153),
(145250, 'zhTW', '錯了！\n\n想再猜猜看嗎？', '', 28153),
(145249, 'zhTW', '是羅亞。', '是羅亞。', 28153),
(145248, 'zhTW', '蠟燭。', '蠟燭。', 28153),
(145247, 'zhTW', '', '你看下面，在發光耶！', 28153),
(145246, 'zhTW', '', '這是哪裡？怎麼到處都是煙啊？', 28153),
(145245, 'zhTW', '', '所以要小心喔，好嗎？', 28153),
(145244, 'zhTW', '樹。', '樹。', 28153),
(145243, 'zhTW', '', '別掉下去喔，朋友！我掉下去不會怎樣，你的話就慘了！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145242, 'zhTW', '', '你好。', 28153),
(145241, 'zhTW', '', '原來山可以這麼高！', 28153),
(145240, 'zhTW', '', '從這裡什麼都看得到耶！', 28153),
(145239, 'zhTW', '', '很高興見到你。', 28153),
(145238, 'zhTW', '', '幸會。', 28153),
(145237, 'zhTW', '', '啾啾啾啾！', 28153),
(145236, 'zhTW', '', '不行。', 28153),
(145235, 'zhTW', '', '不要。', 28153),
(145234, 'zhTW', '', '想都別想。', 28153),
(145233, 'zhTW', '', '這就對了。', 28153),
(145232, 'zhTW', '', '嗯嗯。', 28153),
(145231, 'zhTW', '', '對啊。', 28153),
(145230, 'zhTW', '', '我非常感激。', 28153),
(145229, 'zhTW', '', '非常感謝你。', 28153),
(145228, 'zhTW', '地精。', '地精。', 28153),
(145227, 'zhTW', '', '我欠你一份情。', 28153),
(145226, 'zhTW', '', '為了黑鐵砧！', 28153),
(145225, 'zhTW', '', '肯定有…十隻那麼多吧！', 28153),
(145224, 'zhTW', '', '這就是你的本事嗎？', 28153),
(145222, 'zhTW', '', '我要揍死你！', 28153),
(145221, 'zhTW', '', '不知道有多少鳥兒住在那棵樹上。一定很多！', 28153),
(145220, 'zhTW', '你回答看看。\n\n我年輕的時候高，老的時候矮。我是什麼？', '', 28153),
(145219, 'zhTW', '', '這是我的榮幸。', 28153),
(145218, 'zhTW', '', '朋友，你看！我們在一棵好大的大樹底下！', 28153),
(145217, 'zhTW', '', '很高興能幫忙。', 28153),
(145216, 'zhTW', '', '你真的不用客氣。', 28153),
(145215, 'zhTW', '來玩吧。', '來玩吧。', 28153),
(145214, 'zhTW', '心智大考驗！你準備好了嗎？', '', 28153),
(145213, 'zhTW', '', '我可以養一隻當寵物嗎？', 28153),
(145212, 'zhTW', '', '只不過是給像蜥蜴的鳥住的。', 28153),
(145211, 'zhTW', '', '好壯觀的高塔。就像是一座…巨大的鳥屋！', 28153),
(145210, 'zhTW', '', '嘿，天上飛的是什麼？好漂亮喔！', 28153),
(145209, 'zhTW', '', '說到這個…你有家嗎？', 28153),
(145208, 'zhTW', '', '你住在這裡嗎？', 28153),
(145207, 'zhTW', '', '是怎麼辦到的啊？', 28153),
(145206, 'zhTW', '', '哇…會飛的城市耶！真的假的？！', 28153),
(145205, 'zhTW', '', '我們來玩公主遊戲好不好？', 28153),
(145204, 'zhTW', '', '你知道住在裡面的是誰嗎？我想一定是公主。', 28153),
(145203, 'zhTW', '', '哇！那絕對是有史以來最漂亮的房子！', 28153),
(145202, 'zhTW', '', '噁！', 28153),
(145201, 'zhTW', '', '會不會是蟲子？我猜一定是蟲子。噁！我最討厭蟲子了！', 28153),
(145200, 'zhTW', '', '你覺得他們是想要擋住什麼東西？', 28153),
(145199, 'zhTW', '', '哇！那是我看過最大的一面牆了！', 28153),
(145197, 'zhTW', '', '烏娜抱住你。', 28153),
(145196, 'zhTW', '你不能拿靴子！', '', 28153),
(145195, 'zhTW', '', '好啦，朋友，我們離開這裡吧！有好多地方要去呢！', 28153),
(145194, 'zhTW', '', '幫我跟爸爸媽媽說，我好想他們…還有，我很快就會見到他們的！', 28153),
(145193, 'zhTW', '', '朋友！那個光說我可以留下來！萬歲！', 28153),
(145192, 'zhTW', '', '我能不能跟我的朋友待在一起？再一下子好不好？', 28153),
(145191, 'zhTW', '', '我還有好多事情沒做過，還有好多地方沒去過…', 28153),
(145190, 'zhTW', '', '等一下…', 28153),
(145189, 'zhTW', '', '媽媽！爸爸！他們在等我！', 28153),
(145188, 'zhTW', '', '光…要我跟著它前進…', 28153),
(145187, 'zhTW', '', '發…發生了什麼事？', 28153),
(145186, 'zhTW', '', '喔，朋友！我們成功了！我們擊敗他們了！', 28153),
(145185, 'zhTW', '', '黑暗消失了！我看得見了！', 28153),
(145184, 'zhTW', '', '你要為自己做過的事付出代價！', 28153),
(145183, 'zhTW', '詛咒你，我詛咒你！事情還沒完…', '', 28153),
(145182, 'zhTW', '你的死會讓女妖之王很高興的！', '', 28153),
(145181, 'zhTW', '聯盟的混帳！我會把你的頭帶給黑暗女王！', '', 28153),
(145180, 'zhTW', '', '我要割開你的喉嚨，$n！', 28153),
(145179, 'zhTW', '狂亂的蹄聲在遠方迴響。有東西正在逼近。', '狂亂的蹄聲在遠方迴響。有東西正在逼近。', 28153),
(145178, 'zhTW', '', '竟敢打斷我，你要用你的生命補償我，$n！', 28153),
(145177, 'zhTW', '', '我在看著你，$n。', 28153),
(145176, 'zhTW', '我要把你炸了，就像你的狗王一樣！為了部落！', '', 28153),
(145175, 'zhTW', '隨著空氣開始劈啪作響，你聞到了臭氧的味道。', '隨著空氣開始劈啪作響，你聞到了臭氧的味道。', 28153),
(145173, 'zhTW', '', '真是無恥，但我不只是會魔法而已。', 28153),
(145172, 'zhTW', '我準備好了。開始進行儀式吧。', '我準備好了。開始進行儀式吧。', 28153),
(145171, 'zhTW', '我能聽到從腳底下傳來這顆星球的哀號。艾澤拉斯痛得不停顫抖！我一定要想辦法減輕她的痛苦…', '', 28153),
(145170, 'zhTW', '', '我可沒那麼容易死，$n。嚐嚐我的怒火吧！', 28153),
(145169, 'zhTW', '', '終於還是找到你了，$n。', 28153),
(145168, 'zhTW', '我會敲碎你的頭顱！', '', 28153),
(145167, 'zhTW', '我會把你的肉從骨頭上剝下來！', '', 28153),
(145166, 'zhTW', '我會永遠守著你的墳墓。', '', 28153),
(145165, 'zhTW', '我已經什麼希望都沒有了。', '', 28153),
(145164, 'zhTW', '可惡。不要再這樣了。', '', 28153),
(145163, 'zhTW', '你會為你對我做的事付出代價的。', '', 28153),
(145162, 'zhTW', '我會抽乾你的生命力。', '', 28153),
(145161, 'zhTW', '我最愛品味金屬碰撞的聲音還有恐懼的味道。', '', 28153),
(145160, 'zhTW', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t 你受到|cFFF00000|Hspell:260953|h[鋼鐵凝視]|h|r！', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t 你在|cFFF00000|Hspell:257459|h[狠狠盯上]|h|r！', 28153),
(145159, 'zhTW', '', '我再也不會害怕了！', 28153),
(145158, 'zhTW', '', '我的光太強了！', 28153),
(145157, 'zhTW', '我想回家。', '', 28153),
(145156, 'zhTW', '', '只要我的光跟我在一起，黑暗就不會贏！', 28153),
(145155, 'zhTW', '', '媽媽說過聖光一定會找到我的。那就是你，朋友。你就是我的光！', 28153),
(145154, 'zhTW', '', '朋…朋友，你在這裡！你沒有丟下我！', 28153),
(145153, 'zhTW', '不…不…', '不…不…', 28153),
(145152, 'zhTW', '黑暗女王…我失敗了…', '黑暗女王…我失敗了…', 28153),
(145151, 'zhTW', '我在圖騰柱的最下層，老兄。', '', 28153),
(145150, 'zhTW', '終於啊…', '終於啊…', 28153),
(145149, 'zhTW', '噢…別再來一次…', '噢…別再來一次…', 28153),
(145148, 'zhTW', '為了黑暗女王！', '為了黑暗女王！', 28153),
(145147, 'zhTW', '放棄希望！', '放棄希望！', 28153),
(145146, 'zhTW', '踏入死亡的國度！', '踏入死亡的國度！', 28153),
(145145, 'zhTW', '我會享用你的屍骨！', '我會享用你的屍骨！', 28153),
(145144, 'zhTW', '活人都得死！', '活人都得死！', 28153),
(145143, 'zhTW', '為了希瓦娜斯！', '為了希瓦娜斯！', 28153),
(145142, 'zhTW', '', '烏娜雙臂環繞著自己，開始哭泣。', 28153),
(145141, 'zhTW', '', '我…我辦不到！我只是想要回家！', 28153),
(145140, 'zhTW', '', '朋友？你還在嗎？我好怕！', 28153),
(145139, 'zhTW', '壞魂能會逮到你！', '', 28153),
(145137, 'zhTW', '你的祖先叫你回去團聚了。', '', 28153),
(145136, 'zhTW', '希望你和我兄弟長得一樣醜。', '', 28153),
(145135, 'zhTW', '你用什麼巫毒術，夥計？', '', 28153),
(145133, 'zhTW', '就順其自然吧。', '', 28153),
(145130, 'zhTW', '荊棘會刺向你的靈魂！', '', 28153),
(145129, 'zhTW', '然後牠回過頭，消失在森林裡。從此以後，勇敢而真誠的人在森林裡都會受到白鹿的保護。', '然後牠回過頭，消失在森林裡。從此以後，勇敢而真誠的人在森林裡都會受到白鹿的保護。', 28153),
(145128, 'zhTW', '『我是阿賽爾，也是這裡的森林之心。只要有我在，我就會保護你和來尋求我幫助的人民。』白鹿這麼說。', '『我是阿賽爾，也是這裡的森林之心。只要有我在，我就會保護你和來尋求我幫助的人民。』白鹿這麼說。', 28153),
(145127, 'zhTW', '『聖光啊！你會說話！』亞羅姆大人很震驚！', '『聖光啊！你會說話！』亞羅姆大人很震驚！', 28153),
(145126, 'zhTW', '', '<歡呼聲>', 28153),
(145125, 'zhTW', '', '<打呵欠>', 28153),
(145124, 'zhTW', '', '<喔呼！>', 28153),
(145123, 'zhTW', '', '<喔呼！>', 28153),
(145122, 'zhTW', '火會燒盡這個怪物！', '', 28153),
(145121, 'zhTW', '', '<學雞叫>', 28153),
(145120, 'zhTW', '', '<哭泣>', 28153),
(145119, 'zhTW', '『不用客氣。我只是在回報你對我的恩情。』', '『不用客氣。我只是在回報你對我的恩情。』', 28153),
(145118, 'zhTW', '', '<哭泣>', 28153),
(145117, 'zhTW', '', '<哭泣>', 28153),
(145116, 'zhTW', '', '<親吻>', 28153),
(145115, 'zhTW', '亞羅姆大人對白鹿說：『謝謝你，朋友。』', '亞羅姆大人對白鹿說：『謝謝你，朋友。』', 28153),
(145114, 'zhTW', '', '<笑聲>', 28153),
(145113, 'zhTW', '', '<笑>', 28153),
(145112, 'zhTW', '', '<噗噗呸呸呸！>', 28153),
(145111, 'zhTW', '亞羅姆大人和白鹿一起對抗這些戰士，擊敗了他們。', '亞羅姆大人和白鹿一起對抗這些戰士，擊敗了他們。', 28153),
(145110, 'zhTW', '', '<咆哮>', 28153),
(145109, 'zhTW', '', '<吼叫聲>', 28153),
(145108, 'zhTW', '', '<嘆氣>', 28153),
(145107, 'zhTW', '', '<火車聲 - 汽鏘汽鏘嘟嘟！>', 28153),
(145106, 'zhTW', '大白鹿回到他身邊，踏過好幾個佐司特戰士！', '大白鹿回到他身邊，踏過好幾個佐司特戰士！', 28153),
(145105, 'zhTW', '森林裡突然傳來一聲巨吼！', '森林裡突然傳來一聲巨吼！', 28153),
(145104, 'zhTW', '亞羅姆大人決定能殺幾個就殺幾個，於是堅持到底。', '亞羅姆大人決定能殺幾個就殺幾個，於是堅持到底。', 28153),
(145103, 'zhTW', '亞羅姆大人單獨面對十個戰士！雖然他智勇雙全，但畢竟寡不敵眾，遭到了重重包圍！', '亞羅姆大人單獨面對十個戰士！雖然他智勇雙全，但畢竟寡不敵眾，遭到了重重包圍！', 28153),
(145102, 'zhTW', '有意思。', '有意思。', 28153),
(145101, 'zhTW', '到了夜晚，佐司特發動攻擊！', '到了夜晚，佐司特發動攻擊！', 28153),
(145100, 'zhTW', '大白鹿回到了森林裡，亞羅姆也紮了營。', '大白鹿回到了森林裡，亞羅姆也紮了營。', 28153),
(145099, 'zhTW', '『只要是能挺身對抗這麼多佐司特的生物，我都希望能留在這片森林裡，』他這麼想著。於是亞羅姆大人治療了這頭鹿。', '『只要是能挺身對抗這麼多佐司特的生物，我都希望能留在這片森林裡，』他這麼想著。於是亞羅姆大人治療了這頭鹿。', 28153),
(145098, 'zhTW', '小心荊棘！', '', 28153),
(145097, 'zhTW', '雖然亞羅姆大人需要食物來餵飽他的人民，這頭鹿也很夠吃，但他還是決定不殺這頭鹿。', '雖然亞羅姆大人需要食物來餵飽他的人民，這頭鹿也很夠吃，但他還是決定不殺這頭鹿。', 28153),
(145096, 'zhTW', '大白鹿遭到佐司特的攻擊，殺了很多敵人，但自己也受傷了。', '大白鹿遭到佐司特的攻擊，殺了很多敵人，但自己也受傷了。', 28153),
(145095, 'zhTW', '有一天，亞羅姆大人在森林裡打獵的時候，遇到了一頭大白鹿。', '有一天，亞羅姆大人在森林裡打獵的時候，遇到了一頭大白鹿。', 28153),
(145094, 'zhTW', '快！釋放我們！', '', 28153),
(145093, 'zhTW', '你救了…我們…', '', 28153),
(145092, 'zhTW', '終於…自由了…', '', 28153),
(145091, 'zhTW', '謝謝…你…', '', 28153),
(145090, 'zhTW', '加入我們。', '', 28153),
(145089, 'zhTW', '誰都逃不了。', '', 28153),
(145088, 'zhTW', '', '打倒這傢伙！', 28153),
(145087, 'zhTW', '', '消滅這個目標！', 28153),
(145086, 'zhTW', '', '集中攻擊敵人！', 28153),
(145085, 'zhTW', '快逃！沒有希望！', '', 28153),
(145084, 'zhTW', '一起…永遠。', '', 28153),
(145083, 'zhTW', '', '迎戰！', 28153),
(145082, 'zhTW', '', '為了女王！', 28153),
(145081, 'zhTW', '', '用「群山」的力量向前衝！', 28153),
(145080, 'zhTW', '別跟我們一樣受苦！', '', 28153),
(145079, 'zhTW', '', '打倒他們！', 28153),
(145078, 'zhTW', '', '擊退他們！', 28153),
(145077, 'zhTW', '', '快撤退！', 28153),
(145076, 'zhTW', '', '所有人！撤退！', 28153),
(145075, 'zhTW', '', '快逃啊！', 28153),
(145074, 'zhTW', '', '走這邊。', 28153),
(145073, 'zhTW', '', '我帶路。', 28153),
(145072, 'zhTW', '', '跟我來。', 28153),
(145071, 'zhTW', '', '為了聯盟！', 28153),
(145070, 'zhTW', '', '快來幫忙！', 28153),
(145069, 'zhTW', '', '來幫我的忙！', 28153),
(145068, 'zhTW', '', '有危險！', 28153),
(145067, 'zhTW', '', '全力攻擊！', 28153),
(145066, 'zhTW', '', '開火！', 28153),
(145065, 'zhTW', '', '待在這裡。', 28153),
(145064, 'zhTW', '', '不要動。', 28153),
(145063, 'zhTW', '', '我傷得很重！', 28153),
(145062, 'zhTW', '', '我需要治療！', 28153),
(145061, 'zhTW', '', '<吼叫聲>', 28153),
(145060, 'zhTW', '', '<大吼>', 28153),
(145059, 'zhTW', '', '<放聲大吼>', 28153),
(145058, 'zhTW', '', '<吐氣>', 28153),
(145057, 'zhTW', '', '<集中力量>', 28153),
(145056, 'zhTW', '', '<發出吼叫>', 28153),
(145055, 'zhTW', '', '<死亡吶喊>', 28153),
(145054, 'zhTW', '', '<痛哭>', 28153),
(145053, 'zhTW', '', '<吐氣>', 28153),
(145052, 'zhTW', '', '<墜落吶喊>', 28153),
(145051, 'zhTW', '', '<深呼吸>', 28153),
(145050, 'zhTW', '', '<躍起>', 28153),
(145049, 'zhTW', '', '<躍下落地>', 28153),
(145048, 'zhTW', '', '<吶喊>', 28153),
(145047, 'zhTW', '', '<喘氣>', 28153),
(145046, 'zhTW', '', '<歡呼>', 28153),
(145045, 'zhTW', '', '<痛哼>', 28153),
(145044, 'zhTW', '', '<痛喊>', 28153),
(145043, 'zhTW', '', '千萬別讓目標離開視線。', 28153),
(145042, 'zhTW', '', '為了守護親愛的人，我會不顧一切。', 28153),
(145041, 'zhTW', '', '箭無虛發。', 28153),
(145040, 'zhTW', '', '再見。', 28153),
(145039, 'zhTW', '', '只要控制得當，暗影也能是盟友。', 28153),
(145038, 'zhTW', '', '你好。', 28153),
(145037, 'zhTW', '', '我們不能再邀請別人了。', 28153),
(145036, 'zhTW', '', '我們各行其道。做好你的選擇。', 28153),
(145035, 'zhTW', '', '我暫時不能再喝了。', 28153),
(145034, 'zhTW', '', '我還沒學會那個技能。', 28153),
(145033, 'zhTW', '', '這個我還不能用。', 28153),
(145032, 'zhTW', '', '那個法術還沒準備好。', 28153),
(145031, 'zhTW', '', '有消息嗎？', 28153),
(145030, 'zhTW', '', '還不能施放這個法術。', 28153),
(145029, 'zhTW', '', '還要再等一下。', 28153),
(145028, 'zhTW', '', '一定要無所不用其極。', 28153),
(145027, 'zhTW', '', '這真是個狩獵的好日子。', 28153),
(145026, 'zhTW', '', '我都失蹤這麼久了，你就這樣對待我嗎？', 28153),
(145025, 'zhTW', '', '我不能這麼做。', 28153),
(145024, 'zhTW', '', '我的權限不足。', 28153),
(145023, 'zhTW', '', '我不能攻擊那個目標。', 28153),
(145022, 'zhTW', '', '我的虛無力量會吞噬你…除非你聽話一點。', 28153),
(145021, 'zhTW', '', '我不能攻擊它。', 28153),
(145020, 'zhTW', '', '我的背包已經滿了。', 28153),
(145019, 'zhTW', '', '我帶不動了。', 28153),
(145018, 'zhTW', '', '姊妹之間有很多事。更何況她是不死的。', 28153),
(145017, 'zhTW', '', '它鎖住了。', 28153),
(145016, 'zhTW', '', '這類物品太多了。', 28153),
(145015, 'zhTW', '', '我還不能使用這個物品。', 28153),
(145014, 'zhTW', '', '我還沒準備好。', 28153),
(145013, 'zhTW', '', '還要再等一下才行。', 28153),
(145012, 'zhTW', '', '魔怒不足。', 28153),
(145011, 'zhTW', '', '我的魔怒不足。', 28153),
(145010, 'zhTW', '', '魔痛不足。', 28153),
(145009, 'zhTW', '', '我的魔痛不夠。', 28153),
(145008, 'zhTW', '', '那不是背包。', 28153),
(145007, 'zhTW', '', '錢不夠。', 28153),
(145006, 'zhTW', '', '那個我買不起。', 28153),
(145005, 'zhTW', '', '太貴了。', 28153),
(145004, 'zhTW', '', '他不能加入隊伍。', 28153),
(145003, 'zhTW', '', '我彈藥用完了。', 28153),
(145002, 'zhTW', '', '能量不足。', 28153),
(145001, 'zhTW', '', '我缺乏足夠的能量。', 28153),
(145000, 'zhTW', '', '我需要先有法力。', 28153),
(144999, 'zhTW', '', '法力不夠了。', 28153),
(144998, 'zhTW', '', '需要法力。', 28153),
(144997, 'zhTW', '', '怒氣不足。', 28153),
(144996, 'zhTW', '', '我需要更多怒氣。', 28153),
(144995, 'zhTW', '', '太遠了。', 28153),
(144994, 'zhTW', '', '當然，我當然還愛著他。你一定要多管閒事嗎？', 28153),
(144993, 'zhTW', '', '我離得太遠了。', 28153),
(144992, 'zhTW', '', '我得靠近一點。', 28153),
(144991, 'zhTW', '', '我的武器必須以雙手使用。', 28153),
(144990, 'zhTW', '', '那個技能還沒準備好。', 28153),
(144989, 'zhTW', '', '我還不能這麼做。', 28153),
