INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144985, 'zhTW', '', '我不能在這裡那麼做。', 28153),
(144984, 'zhTW', '', '我不能扔掉那件物品。', 28153),
(144983, 'zhTW', '', '這件物品已經跟我綁定了。', 28153),
(144982, 'zhTW', '', '我不能裝備那個物品。', 28153),
(144981, 'zhTW', '', '我的等級還不夠。', 28153),
(144980, 'zhTW', '', '我還不能使用它。', 28153),
(144979, 'zhTW', '', '我的技能等級不夠，不能裝備這件物品。', 28153),
(144978, 'zhTW', '', '這不是我能裝備的東西。', 28153),
(144977, 'zhTW', '', '我不能學習這個法術。', 28153),
(144976, 'zhTW', '', '我不能拾取那個物品。', 28153),
(144975, 'zhTW', '', '那不是我能拿的。', 28153),
(144974, 'zhTW', '', '我需要靠近一點。', 28153),
(144973, 'zhTW', '', '距離太遠了。', 28153),
(144972, 'zhTW', '', '我拿不到。', 28153),
(144971, 'zhTW', '', '我不能交易這件物品。', 28153),
(144970, 'zhTW', '', '我不能使用這個。', 28153),
(144969, 'zhTW', '', '還沒裝備這件物品。', 28153),
(144968, 'zhTW', '', '需要先裝備這件物品。', 28153),
(144967, 'zhTW', '', '我現在不能拾取物品。', 28153),
(144966, 'zhTW', '', '我沒有目標。', 28153),
(144965, 'zhTW', '', '我要先找到目標。', 28153),
(144964, 'zhTW', '', '我需要目標。', 28153),
(144963, 'zhTW', '', '死靈在下、陰魂在上，讓我的荊棘成長茁壯！', 28153),
(144962, 'zhTW', '', '姊妹，把水晶給我！', 28153),
(144961, 'zhTW', '', '我的荊棘會把你撕成碎片！', 28153),
(144960, 'zhTW', '', '你越是掙扎，就越會流血！', 28153),
(144959, 'zhTW', '', '你身上帶著黑印記！', 28153),
(144958, 'zhTW', '', '你的頭骨很適合當裝飾。', 28153),
(144956, 'zhTW', '', '我還能再次生根…', 28153),
(144955, 'zhTW', '', '我愛肋骨斷掉的聲音。', 28153),
(144954, 'zhTW', '我今晚有好東西吃了，非常感謝你，祝福你。', '我今晚有好東西吃了，非常感謝你，祝福你。', 28153),
(144953, 'zhTW', '你對我真好，謝謝你！', '你對我真好，謝謝你！', 28153),
(144952, 'zhTW', '謝啦，朋友。', '謝啦，朋友。', 28153),
(144951, 'zhTW', '', '骨頭真軟！', 28153),
(144950, 'zhTW', '<給十個金幣。>', '<給十個金幣。>', 28153),
(144949, 'zhTW', '<給一個金幣。>', '<給一個金幣。>', 28153),
(144948, 'zhTW', '<給五個銅幣。>', '<給五個銅幣。>', 28153),
(144947, 'zhTW', '給點銅板吧，朋友？', '給點銅板吧，朋友？', 28153),
(144946, 'zhTW', '', '血肉腐敗、哭聲高亢，尖叫編成美麗的樂章！', 28153),
(144945, 'zhTW', '', '你馬上就會毀滅！', 28153),
(144944, 'zhTW', '', '你輪過了！', 28153),
(144943, 'zhTW', '', '…而瑞贊對著鮮血食人妖大軍的屍體大吼，大獲全勝！', 28153),
(144942, 'zhTW', '', '你想解脫還早得很呢。', 28153),
(144941, 'zhTW', '', '這痛苦多迷人！', 28153),
(144940, 'zhTW', '', '身體沒了…我的詛咒…也會在…', 28153),
(144939, 'zhTW', '', '我會讓你們慘叫個不停！', 28153),
(144938, 'zhTW', '', '靈魂焦黑、暗夜冰冷，殺死所有我眼前的人！', 28153),
(144937, 'zhTW', '', '你現在屬於我了！', 28153),
(144936, 'zhTW', '', '跳舞吧，傀儡！跳啊！', 28153),
(144935, 'zhTW', '', '把水晶給我，蠢材！只有我才能操控它的力量！', 28153),
(144934, 'zhTW', '', '你們的靈魂永遠…屬於我。', 28153),
(144933, 'zhTW', '', '死亡阻止不了我…', 28153),
(144932, 'zhTW', '', '脆弱的靈魂！', 28153),
(144931, 'zhTW', '', '你們在這裡沒有力量！', 28153),
(144930, 'zhTW', '', '你跟我來。 其他的人，都跟洛克漢到北方戰線去。', 28153),
(144929, 'zhTW', '注意聯盟的部隊！他們把全部軍力都派出來了！', '', 28153),
(144928, 'zhTW', '他們派了一大堆士兵過來！別讓他們得逞！', '', 28153),
(144926, 'zhTW', '', '你好，$c。', 28153),
(144925, 'zhTW', '', '永遠不要忘記侍奉聖光所代表的意義。', 28153),
(144924, 'zhTW', '', '<法芮雅微笑問候你。>$B$B$c，你通過了試煉，做得很好，我想你的故事才剛要開始。', 28153),
(144923, 'zhTW', '如果你是要找美拉，她到前線去幫忙了。$B$B暴風城裡有許多能幹的裁縫師，他們多少都可以教你一點。', '', 28153),
(144921, 'zhTW', '', '聖光帶走這張工作桌吧！我可能再也無法使用這間工坊了。$B$B不管我怎麼刷洗表面，都刷不掉阿古斯野獸毛皮所留下的污漬。', 28153),
(144908, 'zhTW', '梵迪卡爾在等待下一次出航。\n\n我也是。', '', 28153),
(144907, 'zhTW', '謝謝你幫忙，$G小夥子:小姑娘;！我欠你一次！', '', 28153),
(144906, 'zhTW', '欸，我要去酒館啦。', '', 28153),
(144905, 'zhTW', '啊，這樣好多了。大英雄就是要配這個護甲！尤其是我這個傳奇事蹟足以撼動整個艾澤拉斯的英雄！', '', 28153),
(144904, 'zhTW', '沒錯，我會把它拿走！雖然還沒完全付清，但這個護甲是我光明正大買下來的。', '', 28153),
(144903, 'zhTW', '', '岩眉先生，看來你今天很走運。你可以把貨物拿回去了。', 28153),
(144902, 'zhTW', '把爪子拿開，你這毛球！', '', 28153),
(144901, 'zhTW', '', '是的，女士。', 28153),
(144900, 'zhTW', '', '走開！我們才不怕你！', 28153),
(144899, 'zhTW', '%s點點頭。', '', 28153),
(144898, 'zhTW', '', '朱先生，麻煩你送這個矮人出去。秀蘭小姐，重新把這個護甲列入清單吧。', 28153),
(144897, 'zhTW', '我今天早上才把支票寄出去的，我發誓！你不能不顧我的死活啊！', '', 28153),
(144896, 'zhTW', '', '岩眉先生，你已經太多次沒按時付費了，根據合約，我要收回貨物。', 28153),
(144895, 'zhTW', '', '他們來了…', 28153),
(144894, 'zhTW', '', '我們會把他救回來的，你別動。', 28153),
(144893, 'zhTW', '怪物從樹林裡冒出來，我們用力反抗。艾希頓大師把我推開，他就被抓走了。我們一定要把他救回來！', '', 28153),
(144892, 'zhTW', '', '我知道，馬騰。告訴我們發生什麼事了。', 28153),
(144891, 'zhTW', '我已經用盡全力抵抗牠們了！', '', 28153),
(144889, 'zhTW', '', '那麼…你把矮人帶來的原因是？炫耀武力？嚇阻敵人？', 28153),
(144888, 'zhTW', '事情就如我想像的一樣順利。', '', 28153),
(144887, 'zhTW', '…對…沒錯。當然！', '', 28153),
(144886, 'zhTW', '別忘了我們來這裡的目的，我們必須搶在聯盟之前找到眼睛。', '', 28153),
(144885, 'zhTW', '', '一想到食人妖腳下可能有千年來最棒的考古發現！', 28153),
(144884, 'zhTW', '', '戰鬥開始了！帶我們迎向勝利！', 28153),
(144883, 'zhTW', '你離開的時候，還跟你父王說是要去探險。卻沒提到你是去跟部落的雜種周旋。', '', 28153),
(144882, 'zhTW', '公主。', '', 28153),
(144881, 'zhTW', '你的父親還在等我們。', '', 28153),
(144880, 'zhTW', '', '公主…請讓我先歡迎你—', 28153),
(144879, 'zhTW', '', '先說好，我父王是個固執的人，但他觀察入微。我敢說他早就知道是你把我從暴風城救出來的。', 28153),
(144878, 'zhTW', '', '他們的命運不是由你來決定，將軍。', 28153),
(144877, 'zhTW', '保衛這個王國最好的辦法，就是由我來把這個…傢伙…流放到沃魯敦。我們贊達拉沒有部落的容身之地。', '', 28153),
(144876, 'zhTW', '', '守護王國是你的職責。既然你怠忽職守，我只好找其他人來幫忙。', 28153),
(144875, 'zhTW', '<觸碰淚珠。>', '<觸碰淚珠。>', 28153),
(144874, 'zhTW', '', '將軍。', 28153),
(144873, 'zhTW', '<一滴綠龍的淚珠，由不知名的力量送入了暗影之地。>', '', 28153),
(144872, 'zhTW', '', '都這樣了，贊庫爾議會那些勾心鬥角的政客和倚老賣老的傢伙，卻還是說這不構成威脅。他們一直說服父王不要動手開戰。', 28153),
(144871, 'zhTW', '', '鮮血食人妖在北方邊界肆虐，還把人民拖進納茲米爾的沼澤裡，一去不回。', 28153),
(144870, 'zhTW', '', '贊達拉正面臨內憂外患，被敵人包圍了、現在腹背受敵。這正是我找上部落的原因…也是我找上你這個部落英雄的原因。', 28153),
(144869, 'zhTW', '', '我們只有一點時間獨處，$n。有些關於我們國家的事一定要告訴你。', 28153),
(144868, 'zhTW', '', '來吧，部落的勇士。跟我一起去見父王。祖爾…我們晚點再談。', 28153),
(144867, 'zhTW', '', '基娜！乖女孩，想不想我啊？', 28153),
(144866, 'zhTW', '', '你說的這個孩子，我聽過她的哭聲。\n\n我會對你施加印記，這樣你就能進入這個世界去找她。\n\n她待的那個地方，生死的界線非常薄弱，甚至延伸到你的世界。\n\n多加小心，你的力量在這個地方沒有用處，凡人傷不了那裡的生物。\n\n努力試試看吧，但是你也可能幫不了你的朋友。', 28153),
(144864, 'zhTW', '聖光與你同在。', '聖光與你同在。', 28153),
(144863, 'zhTW', '我在找一個叫做烏娜的小女孩，你有看到她嗎？', '我在找一個叫做烏娜的小女孩，你有看到她嗎？', 28153),
(144862, 'zhTW', '', '特帕托教過我們玩巨石、皮紙、劍…可是我忘記規則了。', 28153),
(144860, 'zhTW', '聯盟大門已經被摧毀了！', '', 28153),
(144859, 'zhTW', '', '獅鷲獸！攻擊！', 28153),
(144853, 'zhTW', '我們最勇敢的戰士總是勇往直前。我能做到的，就是照顧他們的家人，等他們回來。', '我們最勇敢的戰士總是勇往直前。我能做到的，就是照顧他們的家人，等他們回來。', 28153),
(144852, 'zhTW', '你闖進我的隧道？真是愚蠢！', '', 28153),
(144851, 'zhTW', '', '牠的尾巴好蓬喔！', 28153),
(144850, 'zhTW', '', '我可以養牠嗎？', 28153),
(144849, 'zhTW', '', '不要啦！留下來多講一點冒險故事嘛，特帕托！', 28153),
(144848, 'zhTW', '', '他回來了！', 28153),
(144847, 'zhTW', '', '是特帕托！', 28153),
(144846, 'zhTW', '別擔心！特帕托還會再回來講更多的故事…說不定還會再帶其他朋友來。', '', 28153),
(144845, 'zhTW', '特帕托現在必須把牠帶回去了。孩子們，說再見吧。', '', 28153),
(144842, 'zhTW', '', '噢！', 28153),
(144841, 'zhTW', '告訴我宴席上發生的事。', '告訴我宴席上發生的事。', 28153),
(144840, 'zhTW', '$c，黑暗女王有重要的任務要交給你。希望你已經準備好了…', '', 28153),
(144839, 'zhTW', '', '特帕托！', 28153),
(144838, 'zhTW', '', '朋友，答應我你不會離開我，就算這裡黑到看不見…', 28153),
(144837, 'zhTW', '', '但是現在有你一起…我們…說不定可以反擊！', 28153),
(144836, 'zhTW', '', '我一直跑一直跑…可是他們總是會找到我。', 28153),
(144835, 'zhTW', '', '他們很快就會到這裡來了，朋友。', 28153),
(144834, 'zhTW', '', '你在這裡啊！太好了。', 28153),
(144833, 'zhTW', '哈哈！特帕托很高興看到你們平安無事！特帕托還帶了禮物，這個小傢伙原本在維爾薩拉。', '', 28153),
(144832, 'zhTW', '你在開我玩笑嗎？', '', 28153),
(144831, 'zhTW', '這些球體似乎擁有某種力量。或許只要我移除外殼的話…', '', 28153),
(144830, 'zhTW', '啊！', '', 28153),
(144829, 'zhTW', '這些眼睛看來圓潤飽滿。我只要從它們上面擠出幾滴的話…', '', 28153),
(144828, 'zhTW', '', '我好冷喔，這裡好黑。我不知道該怎麼辦！', 28153),
(144827, 'zhTW', '', '我不會放棄的，朋友！我保證！', 28153),
(144826, 'zhTW', '', '朋友？是你嗎？', 28153),
(144825, 'zhTW', '我們的探員已經潛入下方的哥布林採礦作業場地。很快就可以知道他們究竟在忙什麼了…', '', 28153),
(144824, 'zhTW', '應該…挖…深一點…', '應該…挖…深一點…', 28153),
(144823, 'zhTW', '有個精靈…在挖土…哈！', '有個精靈…在挖土…哈！', 28153),
(144822, 'zhTW', '你太遲了。我們找到了…', '你太遲了。我們找到了…', 28153),
(144821, 'zhTW', '誰找到，就是誰的…', '誰找到，就是誰的…', 28153),
(144820, 'zhTW', '你永遠找不到的…', '你永遠找不到的…', 28153),
(144819, 'zhTW', '你的搜索到此為止，去死吧！', '你的搜索到此為止，去死吧！', 28153),
(144818, 'zhTW', '我很高興能把你埋了。', '我很高興能把你埋了。', 28153),
(144817, 'zhTW', '我們會挖個洞把你埋起來！', '我們會挖個洞把你埋起來！', 28153),
(144816, 'zhTW', '你想找黑鐵矮人的麻煩？真是大錯特錯。', '你想找黑鐵矮人的麻煩？真是大錯特錯。', 28153),
(144815, 'zhTW', '愛管閒事的精靈！這座遺跡是黑鐵矮人的！', '愛管閒事的精靈！這座遺跡是黑鐵矮人的！', 28153),
(144812, 'zhTW', '', '敵人的援軍要打過來了！', 28153),
(144811, 'zhTW', '數據是不會錯的！我們往西走！', '', 28153),
(144810, 'zhTW', '', '山谷是我們的！重整隊形！準備面對下一戰。', 28153),
(144809, 'zhTW', '', '你這就像是想把方形圖騰放進圓形圖騰座一樣。巫毒是會看情緒的，哥布林。', 28153),
(144808, 'zhTW', '他們從暗影裡冒出來。到處都是！', '他們從暗影裡冒出來。到處都是！', 28153),
(144807, 'zhTW', '', '我欣賞他這種特質，很值得佩服。', 28153),
(144806, 'zhTW', '', '是啊，他昨天、前天…還有大前天也是這樣呢！', 28153),
(144805, 'zhTW', '通道確定沒有敵人了，馬上開門！', '', 28153),
(144804, 'zhTW', '他今天可真是鬥志高昂，是吧？', '', 28153),
(144803, 'zhTW', '', '敵人打過來了！Bwonsalaka！', 28153),
(144802, 'zhTW', '我該回去找其他人了。我們必須盡全力阻止這一切。', '', 28153),
(144801, 'zhTW', '謝謝你。我很擔心事情會比我們想的更嚴重。', '', 28153),
(144800, 'zhTW', '告訴我雄獅陵園發生的事。', '告訴我雄獅陵園發生的事。', 28153),
(144799, 'zhTW', '我的探員已經清空了這個區域。意思是，保持低調總是比較明智。', '', 28153),
(144798, 'zhTW', 'Bwon\'chaga di choka!', 'Bwon\'chaga di choka!', 28153),
(144796, 'zhTW', '', '巫毒會影響所有人的心，恰拉，無論他們相不相信。', 28153),
(144795, 'zhTW', '', '巫毒可能讓你聽到恐龍的心聲？真的嗎？', 28153),
(144794, 'zhTW', '', '這就是愛，卡菈。就算是你，你的心也比你的腦更懂巫毒。', 28153),
(144792, 'zhTW', '我能控制你的意志！', '這地方是我的了！', 28153),
(144791, 'zhTW', '真相就在煙霧裡！', '真相就在煙霧裡！', 28153),
(144790, 'zhTW', '深呼吸！', '深呼吸！', 28153),
(144789, 'zhTW', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t瑞贊|cFFFF0000|Hspell:260683|h[喚醒]|h|r所有剩餘的骨堆。', '||TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t瑞贊|cFFFF0000|Hspell:260683|h[喚醒]|h|r所有剩餘的骨堆。', 28153),
(144788, 'zhTW', '', '古翰…', 28153),
(144787, 'zhTW', '', '不該…這樣…', 28153),
(144786, 'zhTW', '', '姐妹們會…幫我…報仇…', 28153),
(144785, 'zhTW', '', 'Gachaga!', 28153),
(144784, 'zhTW', '', '祖達薩…會…滅亡…', 28153),
(144783, 'zhTW', '', '要幫我…報仇…', 28153),
(144782, 'zhTW', '', '我明明是最強的…', 28153),
(144781, 'zhTW', '', 'Pohkiza…', 28153),
(144780, 'zhTW', '喔，這真是太好了。', '', 28153),
(144779, 'zhTW', '那些藥水，做得好，$n。現在我就每種加幾滴，然後…', '', 28153),
(144778, 'zhTW', '', '這還不容易！', 28153),
(144777, 'zhTW', '', '我會速戰速決！', 28153),
(144776, 'zhTW', '', '哈！要打敗你太輕鬆了！', 28153),
(144775, 'zhTW', '', '又有頭骨可以收集了！', 28153),
(144774, 'zhTW', '', '這是我們的地盤！', 28153),
(144773, 'zhTW', '快點！過來這裡！我們還有事要做！', '', 28153),
(144772, 'zhTW', '偶爾喘口氣是件好事。$B$B特別是在大賺一筆之後！', '', 28153),
(144771, 'zhTW', '你來滅火，我來打點實驗室需要的東西！噢，真是太有趣了！', '', 28153),
(144770, 'zhTW', '我剛把所有的材料都用完了。抱歉啊。', '', 28153),
(144769, 'zhTW', '我有一些球要給你，艾勒瑞克。', '我有一些球要給你，艾勒瑞克。', 28153),
(144768, 'zhTW', '我為你準備了那些草藥。', '我為你準備了那些草藥。', 28153),
(144767, 'zhTW', '這裡是你要的眼睛。', '這裡是你要的眼睛。', 28153),
(144766, 'zhTW', '這是你需要的藥水。', '這是你需要的藥水。', 28153),
(144765, 'zhTW', '啊，一位煉金師同行！或許你會喜歡我最新的一些配方。$b$b製造藥水是我的專長,但是我偶爾也玩玩轉化工藝。', '', 28153),
(144764, 'zhTW', '$c，歡迎光臨！你對剛做好的藥水有興趣嗎？或者有其他東西引起你的注意？$b$b製造藥水是我的專長，不過我也時常會接些轉化方面的工作。', '', 28153),
(144763, 'zhTW', '', '新鮮的肉！', 28153),
(144762, 'zhTW', '', '我要拿你的耳朵來串項鍊！', 28153),
(144761, 'zhTW', '', '把鮮血獻給古翰！', 28153),
(144760, 'zhTW', '噓，別動！你不動，他就不會注意到你。', '噓，別動！你不動，他就不會注意到你。', 28153),
(144759, 'zhTW', '聖光保佑我啊…他回來了。', '聖光保佑我啊…他回來了。', 28153),
(144758, 'zhTW', '光鑄復仇者發出抱怨的聲音。', '光鑄復仇者發出抱怨的聲音。', 28153),
(144757, 'zhTW', '我以為自己要失去理智了。', '我以為自己要失去理智了。', 28153),
(144756, 'zhTW', '大地之母保佑你！', '大地之母保佑你！', 28153),
(144755, 'zhTW', '$r，那實在太可怕了。', '$r，那實在太可怕了。', 28153),
(144754, 'zhTW', '我必須…我的意志…我必須離開這裡！', '我必須…我的意志…我必須離開這裡！', 28153),
(144753, 'zhTW', '那些低語…差點就要把我逼瘋了！', '那些低語…差點就要把我逼瘋了！', 28153),
(144752, 'zhTW', '謝謝你，勇士。', '謝謝你，勇士。', 28153),
(144751, 'zhTW', '', '再厲害的武器，不斷磨損也是會壞的。特帕托，休息一下，讓自己好好復原吧。', 28153),
(144750, 'zhTW', '特帕托很感謝黎瑟拉。特帕托覺得自己又可以上場作戰了！', '', 28153),
(144749, 'zhTW', '就算再多次也阻止不了特帕托！', '', 28153),
(144748, 'zhTW', '做這檔事呢，帶上我的咒像護符就對了，別懷疑。', '', 28153),
(144747, 'zhTW', '這偽造技術也太好了吧！你從誰那邊拿到這個的？不用告訴我是誰！把他請來我這就對了！', '', 28153),
(144746, 'zhTW', '不準說出去你是從哪拿到這個的，不然我就讓你看看我是怎麼拿到我的外號的。', '', 28153),
(144745, 'zhTW', '', '又是你啊，特帕托？這是第幾次了…', 28153),
(144744, 'zhTW', '她可不是路邊你看到的夜精靈…她在幾千年前可是皇親國戚啊！', '', 28153),
(144743, 'zhTW', '以後就知道了。照顧好百年之花，$p。它們每一百年才開一次花。', '', 28153),
(144742, 'zhTW', '', '黃金種子！我們必須立刻為神王種植這些種子。你覺得會長成什麼出來，賈登？', 28153),
(144741, 'zhTW', '這個胡椒非常適合用來製作我下一批特辣辣醬…而且那些黃金種子嘗起來就像泥土！', '', 28153),
(144740, 'zhTW', '', '燼火會真的存在。一直都在。露西爾決心要救回這片土地和人民。', 28153),
(144739, 'zhTW', '如果她辦到了，我會全力支持她。', '', 28153),
(144738, 'zhTW', '真的假的？我還以為那只不過是傳說而已！', '', 28153),
(144737, 'zhTW', '', '我現在是審判官了，鎮長。露西爾小姐重新建立了燼火會，要對抗這些女巫。', 28153),
(144736, 'zhTW', '中尉，該怎樣感激你才好，多謝前來相助。', '', 28153),
(144735, 'zhTW', '', '謝謝，$p！我們的爐石庫存正不夠呢。來根辣椒吧，我請客。', 28153),
(144734, 'zhTW', '你有興趣做點事嗎，$p？找個人把這些爐石買下來吧。用它們來換些值錢的東西，我會給你相對的回報的。', '', 28153),
(144733, 'zhTW', '你知道這代表什麼嗎…免費的木材！', '', 28153),
(144732, 'zhTW', '呃，嗯…老大？我接到報告說林地附近出現了像大樹一樣的怪物。', '', 28153),
(144731, 'zhTW', '呱呱！你老媽是穴居怪！呱呱！', '', 28153),
(144730, 'zhTW', '黃肚旱鴨子！呱呱！', '', 28153),
(144729, 'zhTW', '嘎嘎！', '', 28153),
(144728, 'zhTW', '嘿，$p，你想過要揍某個人一拳，但卻心有餘而力不足嗎？我這裡有你需要的解方！', '', 28153),
(144727, 'zhTW', '驚人的護符！奇妙的珍品！我只提供最好的優惠給最優秀的商人！', '', 28153),
(144726, 'zhTW', '聽聽那些低語。好美啊。', '聽聽那些低語。好美啊。', 28153),
(144725, 'zhTW', '暗影會吞噬你。', '暗影會吞噬你。', 28153),
(144724, 'zhTW', '祝福和叫喊都過時了！只有艾澤萊晶岩才能給你力量來應付當今險惡的世界。今天就喝瓶裝艾澤萊晶岩！', '', 28153),
(144723, 'zhTW', '你非死不可。', '你非死不可。', 28153),
(144722, 'zhTW', '讓它停下來！', '讓它停下來！', 28153),
(144721, 'zhTW', '黑暗…降臨了…', '黑暗…降臨了…', 28153),
(144720, 'zhTW', '如果沃金在破碎海岸時帶著他可靠的無敵圖騰，他現在就會還活著。別和他犯一樣的錯！', '', 28153),
(144719, 'zhTW', '監視你的敵人、留意你的朋友、偷窺一眼皇家廳堂…這個驚人的悄悄話幽光圖騰全都能辦到！', '', 28153),
(144718, 'zhTW', '自拉斯塔哈王登基之後，這個圖騰的火光便耀眼至今。今天就把這個贊達拉歷史文物買回家！', '', 28153),
(144717, 'zhTW', '格利夫塔的保證：不要問問題，就會有優惠！', '', 28153),
(144716, 'zhTW', '特帕托來了！', '', 28153),
(144715, 'zhTW', '', '我覺得好多了。', 28153),
(144714, 'zhTW', '特帕托！', '', 28153),
(144713, 'zhTW', '', '沒有皇冠就不能對抗黑暗，朋友。規則就是這樣。', 28153),
(144712, 'zhTW', '', '它會射出星星！壞人最怕這個了。', 28153),
(144711, 'zhTW', '我的族人看守與收藏知識。\n\n我的任務是確保我們的發現有確實紀錄下來。', '', 28153),
(144706, 'zhTW', '我還要做很多準備，把他們解決掉。', '我還要做很多準備，把他們解決掉。', 28153),
(144705, 'zhTW', '這些鬼話還真煩。', '這些鬼話還真煩。', 28153),
(144704, 'zhTW', '那些聲音全都是謊言！', '', 28153),
(144703, 'zhTW', '你難道感受不到，她就在深海底？在她的意志下，我們都會變得完整、完美！', '你感覺不到來自深淵的偉大存在嗎？在她的意志之下，我們將再次合而為一！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144702, 'zhTW', '我們曾經發誓要守護布瑞納丹，保護我們的人民！你忘記了嗎？', '', 28153),
(144701, 'zhTW', '你向來軟弱，不配伺候斯陀頌恩領主，只能像個傻瓜躲在布瑞納丹。', '你一向羸弱無比，無法為斯陀頌恩領主效力，像個傻瓜一樣在那個村莊漸漸毀滅。', 28153),
(144700, 'zhTW', '會死的人是你！', '', 28153),
(144699, 'zhTW', '大海…吞噬你…', '', 28153),
(144698, 'zhTW', '為了…艾薩拉…', '', 28153),
(144697, 'zhTW', '死在海裡吧…', '', 28153),
(144696, 'zhTW', '女王…我…失敗了…', '', 28153),
(144695, 'zhTW', '潮水…退了…', '', 28153),
(144694, 'zhTW', '', '潮水…退了…', 28153),
(144693, 'zhTW', '', '女王…我…失敗了…', 28153),
(144692, 'zhTW', '', '死在海裡吧…', 28153),
(144691, 'zhTW', '', '為艾薩拉奮戰至死！', 28153),
(144690, 'zhTW', '', '大海…吞噬你…', 28153),
(144689, 'zhTW', '我還有一個問題…', '我還有一個問題…', 28153),
(144688, 'zhTW', '看來你需要一個朋友。', '看來你需要一個朋友。', 28153),
(144687, 'zhTW', '你在做什麼？', '你在做什麼？', 28153),
(144686, 'zhTW', '我是來幫忙的，庫戈洛！', '我是來幫忙的，庫戈洛！', 28153),
(144685, 'zhTW', '你能看一下這個卷軸嗎？', '你能看一下這個卷軸嗎？', 28153),
(144684, 'zhTW', '喘口氣，年輕人。\n\n不管你想做什麼，我都沒有時間。', '', 28153),
(144683, 'zhTW', '朋友？不對，是助理。', '', 28153),
(144682, 'zhTW', '我現在不打算做的呢，就是在還有事要忙的時候和$r聊些無關緊要的話。', '', 28153),
(144681, 'zhTW', '那樣的話，我希望你很擅長一心多用。', '', 28153),
(144680, 'zhTW', '我現在顧不了其他的工作了，我進度已經落後太多了。這些卷軸可不會自己寫好，你也知道吧。', '', 28153),
(144679, 'zhTW', '我入不敷出。', '', 28153),
(144678, 'zhTW', '', '<亞魯艾兒的思緒似乎飄到了遠方。>$B$B真希望我弟弟也能看到這座城市…', 28153),
(144677, 'zhTW', '', '我有預感，夜裔精靈很快就會需要應戰。希望到那個時候，我已經做好準備。', 28153),
(144676, 'zhTW', '可惜沒能說服光鑄德萊尼加入部落，他們的武藝非常高超。', '', 28153),
(144675, 'zhTW', '我剛數到哪了？哎！', '', 28153),
(144674, 'zhTW', '等薇可朵回來以後，絕對會成為暮衛的一大助力。', '', 28153),
(144673, 'zhTW', '', '行動吧，勇士。', 28153),
(144672, 'zhTW', '很高興看到亞魯艾兒還在繼續接受訓練，她似乎已經變強了。$B$B或許我該評估一下她進步了多少。', '', 28153),
(144671, 'zhTW', '浪潮洶湧萬變，兄弟。要是不跟我們站在一起，你就必死無疑。', '潮流變了，兄弟。如果你不跟我們站在一起，那你就輸了。', 28153),
(144670, 'zhTW', '一個給你，一個給我。', '', 28153),
(144669, 'zhTW', '做假帳太好玩了！', '', 28153),
(144668, 'zhTW', '里德！艦隊必須立刻離開這裡回到庫爾提拉斯！', '', 28153),
(144667, 'zhTW', '我已經數過這堆了嗎？', '', 28153),
(144666, 'zhTW', '一…二…七…紅…二…', '', 28153),
(144665, 'zhTW', '', '別怪我沒提醒你，我可是爆裂物專家…小心變成我下一個想要爆裂的東西！', 28153),
(144664, 'zhTW', '', '你再這樣下去，恐怕會發生一點小「意外」。', 28153),
(144663, 'zhTW', '', '啊！你會付出代價的！', 28153),
(144662, 'zhTW', '', '再見，夥伴。', 28153),
(144661, 'zhTW', '', '啊？就這樣？', 28153),
(144660, 'zhTW', '', '再見！', 28153),
(144659, 'zhTW', '', '你需要什麼？', 28153),
(144658, 'zhTW', '', '準備出發了嗎？', 28153),
(144657, 'zhTW', '', '哈囉，有事嗎？', 28153),
(144656, 'zhTW', '看來我得默默承受了。太棒了，真是太…棒了。', '', 28153),
(144655, 'zhTW', '你就打算一直這樣嗎？認真的嗎？就一直點點點點點點點點點…', '', 28153),
(144654, 'zhTW', '你就沒有別的事可以做嗎？例如…跟魚人來個法式舌吻之類的？', '', 28153),
(144653, 'zhTW', '噢，拜託！放尊重一點好嗎！', '', 28153),
(144652, 'zhTW', '好啦…好啦…隨便啦。', '', 28153),
(144651, 'zhTW', '好啦，走吧…', '', 28153),
(144650, 'zhTW', '再見！', '', 28153),
(144649, 'zhTW', '我做好準備了！', '', 28153),
(144648, 'zhTW', '準備出動！', '', 28153),
(144647, 'zhTW', '你再繼續弄我，我就讓你少一根指頭。', '', 28153),
(144646, 'zhTW', '我原本過得還蠻愉快的。', '', 28153),
(144645, 'zhTW', '嗨，我叫派奇。你可以叫我「長官」。', '', 28153),
(144644, 'zhTW', '爆炸可是愈大愈好！', '', 28153),
(144643, 'zhTW', '這一切都在我的盤算中啦。', '', 28153),
(144642, 'zhTW', '再見。', '', 28153),
(144641, 'zhTW', '有什麼計畫？', '', 28153),
(144640, 'zhTW', '要下命令嗎？', '', 28153),
(144639, 'zhTW', '呦！', '', 28153),
(144638, 'zhTW', '你喜歡這樣？這年頭大家都有怪癖。', '', 28153),
(144637, 'zhTW', '你想知道這些頭骨哪來的嗎？', '', 28153),
(144636, 'zhTW', '很遺憾，「爛矛部族」這名字有人用了。', '', 28153),
(144635, 'zhTW', '我的頭不見了！大概…嗯，這麼大。如果看到的話要跟我說喔。', '', 28153),
(144634, 'zhTW', '需要幫忙就回來找我。', '', 28153),
(144633, 'zhTW', '別被巫毒法術所迷惑。', '', 28153),
(144632, 'zhTW', '你要小心。', '', 28153),
(144631, 'zhTW', '有什麼事，老大？', '', 28153),
(144630, 'zhTW', '為了暗矛部族！', '', 28153),
(144629, 'zhTW', '我在聽。', '', 28153),
(144628, 'zhTW', '好吧…這可是你自找的。啟動重置全宇宙的作業程序。', '', 28153),
(144627, 'zhTW', '你狂點我，並不會讓系統跑得比較快。', '', 28153),
(144626, 'zhTW', '出現新的潛在隔離目標。', '', 28153),
(144625, 'zhTW', '錯誤。請勿再次嘗試。', '', 28153),
(144624, 'zhTW', '互動程序完成。', '', 28153),
(144623, 'zhTW', '繼續隔離程序。', '', 28153),
(144622, 'zhTW', '重新進行掃描。', '', 28153),
(144621, 'zhTW', '', '你好啊，$p！新地區和新盟友都在艾澤拉斯等著我們。$B$B歐庫雷斯已經在樓下備妥了傳送門，就等你做好準備了。', 28153),
(144620, 'zhTW', '發現汙染。必須想辦法隔絕。', '', 28153),
(144619, 'zhTW', '高優先級程序：隔絕污染。', '', 28153),
(144618, 'zhTW', '赫茲羅單位啟動。目標：隔離污染。', '', 28153),
(144617, 'zhTW', '', '你這招實在太老套…連我都看不下去了！', 28153),
(144616, 'zhTW', '', '你聽過一個故事，是講失控的托爾托攻擊一直煩她的蟲子嗎？', 28153),
(144614, 'zhTW', '', '你讓我很想揍人。', 28153),
(144613, 'zhTW', '', '講夠了沒？', 28153),
(144612, 'zhTW', '', '下次別再來煩我。', 28153),
(144611, 'zhTW', '', '你終於要出發啦。', 28153),
(144610, 'zhTW', '', '呃。又怎麼了？', 28153),
(144609, 'zhTW', '', '你一定要跟我說話嗎？', 28153),
(144608, 'zhTW', '', '你又想幹嘛？', 28153),
(144605, 'zhTW', '走開…不然我就用你的靈魂來抵債！', '', 28153),
(144604, 'zhTW', '我建議你…別跟死亡的羅亞打交道！', '', 28153),
(144603, 'zhTW', '靈魂可別掉了。', '', 28153),
(144602, 'zhTW', '一切多小心。', '', 28153),
(144601, 'zhTW', '在外頭要小心。', '', 28153),
(144600, 'zhTW', '你好，外來者。', '', 28153),
(144599, 'zhTW', '你找漢札布做什麼？', '', 28153),
(144598, 'zhTW', '我還有很多事要做。', '', 28153),
(144597, 'zhTW', '我叫你別鬧了！', '', 28153),
(144596, 'zhTW', '你少在那裡給我呱呱叫了。', '', 28153),
(144595, 'zhTW', '你讓我暴跳如雷了！', '', 28153),
(144594, 'zhTW', '你該不會是來親我的吧？', '', 28153),
(144593, 'zhTW', '下次見了。', '', 28153),
(144592, 'zhTW', '凡事要三思。', '', 28153),
(144591, 'zhTW', '祝你抓到新鮮蒼蠅。', '', 28153),
(144590, 'zhTW', '說吧。', '', 28153),
(144589, 'zhTW', '你找奎格瓦嗎？', '', 28153),
(144588, 'zhTW', '嗯，小傢伙？', '', 28153),
(144587, 'zhTW', '再見…很快就會了。', '', 28153),
(144586, 'zhTW', '哼！快走吧！', '', 28153),
(144585, 'zhTW', '或早或晚…每個人都會來見我的。', '', 28153),
(144584, 'zhTW', '你好像很渴。想喝點什麼？「絕命水」怎麼樣？哈哈哈！', '', 28153),
(144583, 'zhTW', '我看得見死人。這不是什麼稀奇的事。', '', 28153),
(144582, 'zhTW', '嗯…看來有人沒分寸，小心惹火上身。', '', 28153),
(144581, 'zhTW', '慢著。別忘了你在跟誰打交道。', '', 28153),
(144580, 'zhTW', '你好啊！你是來交易的嗎？', '', 28153),
(144579, 'zhTW', '你對死亡有什麼要求？', '', 28153),
(144578, 'zhTW', '嗯…你找孤單的老伯昂撒姆第有什麼事嗎？', '', 28153),
(144577, 'zhTW', '我準備好了。', '我準備好了。', 28153),
(144576, 'zhTW', '我們必須在無可挽回之前阻止這場鬧劇。', '', 28153),
(144575, 'zhTW', '', '我會好好看著他，這樣他就不會再迷路了。', 28153),
(144574, 'zhTW', '從我們眼底下被奪走！真是有膽識！', '', 28153),
(144573, 'zhTW', '不，不，這不可能是對的。據我的計算，它應該是--！', '', 28153),
(144572, 'zhTW', '這些結果真是令人困惑。如果這些-- 你會叫它們做什麼？毛鬚怪？--能讓我專心就好了！', '', 28153),
(144571, 'zhTW', '我必須再試一次。你做得很好，雖然我本來想我們的敵人應該會高一點。', '', 28153),
(144570, 'zhTW', '我想你能應付任何打擾，對吧？', '', 28153),
(144569, 'zhTW', '這邊走！只要我開始進行占卜，就必須全神貫注。', '', 28153),
(144568, 'zhTW', '『滅界者』阿古斯正在部署歸源模組！', '『滅界者』阿古斯正在部署歸源模組！', 28153),
(144567, 'zhTW', '', '朋友，努努來救我們了。努努，我就知道你會找到我們！', 28153),
(144566, 'zhTW', '水道的結構受損，而且裡面充斥著不穩定的能量。門會暫時保持關閉。', '水道的結構受損，而且裡面充斥著不穩定的能量。門會暫時保持關閉。', 28153),
(144565, 'zhTW', '我會繼續看著他。他似乎只要能在花園裡逛一逛就心滿意足了。', '我會繼續看著他。他似乎只要能在花園裡逛一逛就心滿意足了。', 28153),
(144564, 'zhTW', '', '非常好！真讓我刮目相看！', 28153),
(144563, 'zhTW', '', '要把氣集中在目標身上，一開始可能會很困難。\n\n前面那個！你來試試擊中那邊的訓練假人。', 28153),
(144562, 'zhTW', '哎，$pr…想買什麼嗎？', '', 28153),
(144561, 'zhTW', '你拿著什麼，$p？那是百年之花嗎？', '', 28153),
(144560, 'zhTW', '', '我們得開始準備下一個耕季了，賈登。', 28153),
(144559, 'zhTW', '嗯…這個辣椒還少點什麼…它需要點熱度。', '', 28153),
(144558, 'zhTW', '', '贊恰！你又忘記把爐石桶填滿了嗎？', 28153),
(144557, 'zhTW', '再見囉！', '', 28153),
(144556, 'zhTW', '順水漫游。', '', 28153),
(144555, 'zhTW', '水很棒，我最喜歡水了。你喜歡水嗎？你最喜歡水的哪一點？我最喜歡水濕濕的。這樣真的很棒，對不對？', '', 28153),
(144554, 'zhTW', '媽媽說我們是兩騎類…涼棲類…啊…呃…兩棲類！呼，終於說對了！', '', 28153),
(144553, 'zhTW', '托爾托爾托爾托，我滾來滾去唷。托爾托爾托爾托，我四腳朝天唷。', '', 28153),
(144552, 'zhTW', '等我長大，我什麼都要讀過一遍！', '', 28153),
(144551, 'zhTW', '你沒有殼要怎麼背東西？', '', 28153),
(144550, 'zhTW', '我喜歡滾來滾去！', '', 28153),
(144549, 'zhTW', '我很快就會跟你一樣老了！', '', 28153),
(144548, 'zhTW', '好，你走。反正我也不想再跟你說話了。', '', 28153),
(144547, 'zhTW', '不是所有海洋生物都跟我一樣天生帥氣又儀表不凡。', '', 28153),
(144546, 'zhTW', '只要看到特別的東西，就帶來給我。', '', 28153),
(144545, 'zhTW', '記得帶更精彩的故事回來。', '', 28153),
(144544, 'zhTW', '我看過的事情會把你嚇到殼都掉了。', '', 28153),
(144543, 'zhTW', '靠近一點，不要嘀嘀咕咕。', '', 28153),
(144542, 'zhTW', '先生女士你們都好。', '', 28153),
(144541, 'zhTW', '你有古董要賣嗎？至少要有兩百年歷史的。', '', 28153),
(144540, 'zhTW', '', '我說你可以走了嗎？！', 28153),
(144539, 'zhTW', '', '掰掰。', 28153),
(144538, 'zhTW', '', '有一次啊，我偷了一隻羊駝，還帶到神廟去。但媽媽後來叫我放牠走。', 28153),
(144537, 'zhTW', '', '有一次啊，我把一個冒險者揍死了，還拿走他的顱骨。他比你高大多了…', 28153),
(144536, 'zhTW', '', '有一次啊，我抓到一隻雷龍的尾巴。我抓著牠一路數到32.5才放手。', 28153),
(144535, 'zhTW', '一隻凶暴信天翁潛向孵化中的蛋。', '', 28153),
(144534, 'zhTW', '', '有一次啊，我抓到一隻羽冠龍。牠真的很大很大很大很大。大人跟我說牠是暴掠龍，但我覺得他們應該是說謊。', 28153),
(144533, 'zhTW', '', '有一次啊，我抓到一隻超級大魚。但後來發現那只是被放了妖術的守衛。', 28153),
(144532, 'zhTW', '', 'Taz\'okun！', 28153),
(144531, 'zhTW', '', 'Taz\'dingo！', 28153),
(144530, 'zhTW', '', '我的羅亞會打爆你的羅亞！', 28153),
(144529, 'zhTW', '', '我長大之後也要當羅亞！', 28153),
(144528, 'zhTW', '再見了，新朋友。', '', 28153),
(144527, 'zhTW', '你要去哪裡？', '', 28153),
(144526, 'zhTW', '羅亞都好酷喔。大部分都大到可以一口把你吃掉！', '', 28153),
(144525, 'zhTW', '我長大之後要當雷龍德魯伊。吼啊！', '', 28153),
(144524, 'zhTW', '我有十根腳趾…但裡面只有四根是我自己的。', '', 28153),
(144523, 'zhTW', '有人把我一整盒皺皺的縮小頭顱偷走了。是你拿的嗎？', '', 28153),
(144522, 'zhTW', '噢，你好。', '', 28153),
(144521, 'zhTW', 'Taz\'okun！', '', 28153),
(144520, 'zhTW', 'Taz\'dingo！', '', 28153),
(144519, 'zhTW', '吼啊！', '', 28153),
(144518, 'zhTW', '這裡的羅亞很強大。', '這裡的羅亞很強大。', 28153),
(144517, 'zhTW', '眾靈與你同在。', '眾靈與你同在。', 28153),
(144516, 'zhTW', '羅亞會一直看著你的。', '羅亞會一直看著你的。', 28153),
(144515, 'zhTW', '嘖！你先吃藥，早上再來找我。', '嘖！你先吃藥，早上再來找我。', 28153),
(144513, 'zhTW', '你這樣做簡直在對命運挑釁！', '你這樣做簡直在對命運挑釁！', 28153),
(144512, 'zhTW', '最好的寶貝都在這裡。', '最好的寶貝都在這裡。', 28153),
(144511, 'zhTW', '眾靈低聲說著你的名字。', '眾靈低聲說著你的名字。', 28153),
(144510, 'zhTW', '你信的是哪個羅亞？', '你信的是哪個羅亞？', 28153),
(144509, 'zhTW', '', '為了贊達拉的未來，前進！', 28153),
(144508, 'zhTW', '這是場尷尬的會面…我最好快點回去，不然庫戈洛會不高興。', '', 28153),
(144498, 'zhTW', '贊達拉屹立不搖。', '贊達拉屹立不搖。', 28153),
(144497, 'zhTW', '別向弱者屈服。', '', 28153),
(144496, 'zhTW', '讓你的敵人受到重創。', '', 28153),
(144495, 'zhTW', '願你嚐到把敵人開腸剖肚的滋味。', '', 28153),
(144494, 'zhTW', '部落的孩子，你有什麼事情？', '', 28153),
(144493, 'zhTW', '這裡是我的領域。', '', 28153),
(144492, 'zhTW', '你是獵人，還是獵物？', '', 28153),
(144491, 'zhTW', '你是來談條件的嗎？', '', 28153),
(144490, 'zhTW', '傳頌我的事蹟。', '', 28153),
(144489, 'zhTW', '願你的攻擊無聲無息。', '', 28153),
(144488, 'zhTW', '為獸群帶來力量。', '', 28153),
(144486, 'zhTW', '你想逃跑的話，別忘了…我會開門。', '', 28153),
(144484, 'zhTW', '你再繼續，就會變成我下一個獵物。', '', 28153),
(144481, 'zhTW', '我是各種形態的主宰，獸群的征逐者，也是狩獵之王。', '', 28153),
(144480, 'zhTW', '你來見狩獵之王有什麼事？', '', 28153),
(144479, 'zhTW', '你來談條件的嗎？', '', 28153),
(144478, 'zhTW', '', '願風吹拂你…趕快把你吹走。', 28153),
(144477, 'zhTW', '', '別忘了，天空屬於我。', 28153),
(144476, 'zhTW', '', '願你讓死亡從天而降。', 28153),
(144475, 'zhTW', '', '風隨我令。', 28153),
(144474, 'zhTW', '', '我要把你拎起來…然後丟在石頭上！', 28153),
(144473, 'zhTW', '', '你想點燃我的怒火嗎？', 28153),
(144472, 'zhTW', '', '不要考驗我的耐心，年輕人。', 28153),
(144471, 'zhTW', '', '我一定要跟你呼吸同樣的空氣嗎？', 28153),
(144470, 'zhTW', '', '有事嗎，孩子？', 28153),
(144469, 'zhTW', '', '你來談條件的嗎？', 28153),
(144468, 'zhTW', '', '哎，$pr…你是不是找羽冠龍找到累了？我這邊有魔精可以讓你看起來像頭魔暴龍！', 28153),
(144462, 'zhTW', '', '謹慎選擇你的羅亞。', 28153),
(144461, 'zhTW', '', '願你總是能發現敵人的蹤跡。', 28153),
(144460, 'zhTW', '', '為了獸群。', 28153),
(144459, 'zhTW', '', '不要去馴服內心的野獸。', 28153),
(144458, 'zhTW', '', '能野就盡量野吧。', 28153),
(144457, 'zhTW', '', '待著別動，我待會可能還會需要你幫我。', 28153),
(144456, 'zhTW', '', '噢，我累了。', 28153),
(144455, 'zhTW', '', '你就繼續吧。', 28153),
(144454, 'zhTW', '', '你再這樣，我丈夫可能會吃醋的。', 28153),
(144453, 'zhTW', '', '你曾經狂野過嗎？', 28153),
(144452, 'zhTW', '是時候把事情接回我自己手中了。我不會讓你毀掉這次行動！', '', 28153),
(144451, 'zhTW', '$n，謝謝你。看來庫戈洛很忙。現在…要怎麼處理這些卷軸？', '', 28153),
(144450, 'zhTW', '', '羅亞在這裡很強大。', 28153),
(144449, 'zhTW', '', '你居然選擇用這副模樣走來走去？', 28153),
(144448, 'zhTW', '你不是我的聯絡人！進來吧，大伙，這裡有新鮮的肉！', '', 28153),
(144447, 'zhTW', '', '我侍奉形態的主宰，剛克。', 28153),
(144446, 'zhTW', '<把卷軸交給伊托卡。>', '<把卷軸交給伊托卡。>', 28153),
(144445, 'zhTW', '', '我好希望努努在這裡。他一定知道該怎麼辦。', 28153),
(144444, 'zhTW', '', '喔，嗨！你是誰？我是烏娜。要不要當我的朋友？說不定我們可以一起離開這個地方。', 28153),
(144443, 'zhTW', '嘿！我正好有你需要的東西，祖爾的個人羽冠龍結界！別讓那些竊賊靠近！', '', 28153),
(144442, 'zhTW', '', '好亮！太亮了！啊啊！', 28153),
(144441, 'zhTW', '祝福你，旅行者。\n\n卸下武器，放鬆一下吧。\n\n打仗可以等一下再說。', '', 28153),
(144440, 'zhTW', '你好，帕骷的信徒！', '', 28153),
(144439, 'zhTW', '好好選擇你的羅亞。', '', 28153),
(144438, 'zhTW', '套一句我的羅亞常說的…走開。', '', 28153),
(144437, 'zhTW', '帕骷會永遠搶先監視你的敵人。', '', 28153),
(144436, 'zhTW', '願戰爭的局面永遠對你有利。', '', 28153),
(144435, 'zhTW', '對了！就是那個地方！', '', 28153),
(144434, 'zhTW', '噢對…你繼續…再往你的右邊一點點…', '', 28153),
(144433, 'zhTW', '要是我太太也能這麼注意我就好了。', '', 28153),
(144432, 'zhTW', '套一句我們羅亞常說的…別碰那個！', '', 28153),
(144431, 'zhTW', '套一句我們羅亞常說的…快閃！哈哈哈哈哈！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144430, 'zhTW', '想跟恐龍一起翱翔天際嗎？', '', 28153),
(144429, 'zhTW', '天空就是我的雙眼。', '', 28153),
(144428, 'zhTW', '我侍奉帕骷，他是最古老的羅亞之一。', '', 28153),
(144427, 'zhTW', '', '我會為無力自保的人挺身而戰。', 28153),
(144425, 'zhTW', '我們都各有安排，你也是。', '', 28153),
(144424, 'zhTW', '我看見這個時代會發生的各種大事，不管哪件事，都跟你有關。真是奇怪。', '', 28153),
(144423, 'zhTW', '可怕的事就要發生了。', '', 28153),
(144422, 'zhTW', '這很可怕，朋友。非常可怕。', '', 28153),
(144421, 'zhTW', '食人妖帝國會再度興盛。我已經看見了。', '', 28153),
(144420, 'zhTW', '最初稱霸世界的是食人妖，最後掌權的也會是我們。', '', 28153),
(144419, 'zhTW', '命運可不怎麼眷顧你啊，朋友。', '', 28153),
(144418, 'zhTW', '我已經看到你會說什麼了，拜託你就速戰速決吧。', '', 28153),
(144417, 'zhTW', '我見過這個世界的末日，你不會想親眼看到的。', '', 28153),
(144416, 'zhTW', '', '贊達拉屹立不搖。', 28153),
(144415, 'zhTW', '', '一定要替死去的人報仇。', 28153),
(144414, 'zhTW', '', '祝你戰無不勝，敵人的頭骨都會是你的裝飾品。', 28153),
(144413, 'zhTW', '', '時代不同了，贊達拉也必須改變。', 28153),
(144412, 'zhTW', '', '我事情很多。你快說。', 28153),
(144411, 'zhTW', '願你的敵人都聞風喪膽。', '', 28153),
(144410, 'zhTW', '贊達拉永垂不朽。', '', 28153),
(144409, 'zhTW', '瑞贊賦予你力量。', '', 28153),
(144408, 'zhTW', '當國王確實很不錯。', '', 28153),
(144407, 'zhTW', '在你面前的是神王拉斯塔哈。', '', 28153),
(144406, 'zhTW', '歡迎來到祖達薩。', '', 28153),
(144405, 'zhTW', '你是獵人…還是獵物？', '', 28153),
(144404, 'zhTW', '', '真希望我能看清楚一點，這裡到處都好黑喔！', 28153),
(144403, 'zhTW', '', '我們是朋友，一定不會有事的。', 28153),
(144402, 'zhTW', '', '至少我們在一起。我們只是…不知道這是哪裡。', 28153),
(144401, 'zhTW', '', '救命！救命啊！', 28153),
(144400, 'zhTW', '', '你是誰？可不可以幫幫我？', 28153),
(144399, 'zhTW', '', '好黑喔！我什麼也看不到！', 28153),
(144397, 'zhTW', '', '終於不用再應付艾莉珊德了，但是城裡還有很多事情需要處理。', 28153),
(144396, 'zhTW', '', '夜裔真的得到了解放。我們不需要夜井，也不需要它的力量了。$b$b現在我們可以掌握自己的命運。', 28153),
(144395, 'zhTW', '我帶了試喝樣品來破除沒有根據的謠言，我們生產的酒怎麼可能腳味…我是說「果味」太濃呢？', '', 28153),
(144394, 'zhTW', '有些葡萄酒商已經放棄照管葡萄園，開始種植其他植物了。', '', 28153),
(144393, 'zhTW', '對，我們到的時候鮮血食人妖已經在跟守衛打了。他們沒料到我們會乘機偷襲。', '', 28153),
(144392, 'zhTW', '哇，真大隻。我需要你的幫忙才能擊倒他！', '', 28153),
(144391, 'zhTW', '若你看到一群野豬人，就丟一顆刺針炸彈，讓他們自食其果！', '', 28153),
(144390, 'zhTW', '很痛吧，對不對！滾出我的土地！', '', 28153),
(144389, 'zhTW', '哈，正中他們眉心！', '', 28153),
(144388, 'zhTW', '你可以去跟蘿絲說我很好。不過我不會離開我的農場，也不會離開我的家人。', '', 28153),
(144387, 'zhTW', '好，這樣就行了。他們向來很喜歡這個地點…', '', 28153),
(144386, 'zhTW', '你可以使用奧格瑪傳送門，前往我們部落盟友在卡林多的主城並跟他們會合。', '', 28153),
(144385, 'zhTW', '', '洛克漢！你還好嗎？看來這裡發生過戰鬥。', 28153),
(144384, 'zhTW', '我聽說達拉然有一整層專門用來進行魔法傳送的空間。$B$B這真是充滿無限可能啊！', '', 28153),
(144383, 'zhTW', '維持這些傳送門是乏味無比的工作，更何況，這樣一來就沒有時間進行重要的研究了！$B$B我敢說傳送術可以解決問題，讓我們不用再煩惱。', '', 28153),
(144382, 'zhTW', '誰說哥布林沒有文化？', '', 28153),
(144381, 'zhTW', '他們甚至拿了我們的一個鼓！', '', 28153),
(144380, 'zhTW', '…然後找到一個開放的鼓！', '', 28153),
(144379, 'zhTW', '歡迎來到酒醉鼓手，$pr！喝一杯吧…', '', 28153),
(144378, 'zhTW', '啊！我以為我的計畫毫無破綻，老兄！', '', 28153),
(144377, 'zhTW', '傻瓜！你要為闖入我的地盤付出代價！', '', 28153),
(144376, 'zhTW', '「沒錯，老兄！你過的是我的橋，老兄。給食人妖過路費，老兄，否則就要拿血來還了，老兄！」', '', 28153),
(144375, 'zhTW', '我準備好開始試煉。', '我準備好開始試煉。', 28153),
(144374, 'zhTW', '', '要不如我們在它們身上綁些炸藥？那一定會很熱鬧…炸死恐龍！', 28153),
(144373, 'zhTW', '', '非常感謝你的熱情，咻嘎。但我能肯定贊達拉人比較喜歡在武器上附上強大的魔法，而不是油膩膩的醜東西。', 28153),
(144372, 'zhTW', '什麼…我們變成了什麼？', '', 28153),
(144371, 'zhTW', '', '不要！放開我！救命啊，朋友！救我！', 28153),
(144370, 'zhTW', '', '又變暗了！你到哪裡去了？不要離開我！', 28153),
(144369, 'zhTW', '', '我以前有一把像這樣的魔杖！可是早就弄丟了。', 28153),
(144368, 'zhTW', '', '是皇冠！好漂亮喔！', 28153),
(144367, 'zhTW', '', '努努！我好怕我再也看不到你了！你怎麼跑到這裡來了？', 28153),
(144366, 'zhTW', '', '現在比較亮了！好像看得到…的樣子。', 28153),
(144365, 'zhTW', '', '那是什麼？一片黑暗裡突然出現了亮光！好亮喔…', 28153),
(144364, 'zhTW', '她…承諾過的…', '', 28153),
(144363, 'zhTW', '我被告知我們可以這樣子在一起！', '', 28153),
(144362, 'zhTW', '', '有羅亞助陣，加上各位英勇的戰士，勝利一定是屬於我們的！', 28153),
(144361, 'zhTW', '', '我們要擊潰鮮血食人妖。我們要阻止他們，讓他們永遠無法用他們想要召喚的怪物對付我們！', 28153),
(144360, 'zhTW', '', '敵人想摧毀我們所愛的一切。我們絕對不能讓敵人得逞！我們今天所做的一切，將會決定贊達拉的未來！', 28153),
(144359, 'zhTW', '', '各位士兵…各位朋友，我們經歷了這麼多困難，但是如今，我們奮鬥的目標終於在眼前了。', 28153),
(144358, 'zhTW', '指出我可以划船到哪裡？', '指出我可以划船到哪裡？', 28153),
(144357, 'zhTW', '在找碼頭嗎？', '在找碼頭嗎？', 28153),
(144356, 'zhTW', '', '好險我有穿靴子！', 28153),
(144355, 'zhTW', '我會帶領一部份的托爾托人步行前往祖爾詹。祝你們兩個好運。', '', 28153),
(144354, 'zhTW', '我生與死…都是為了部落！', '我生與死…都是為了部落！', 28153),
(144353, 'zhTW', '鮮血與榮耀！', '鮮血與榮耀！', 28153),
(144352, 'zhTW', '阿拉希屬於部落！', '阿拉希屬於部落！', 28153),
(144351, 'zhTW', '跟我來！', '跟我來！', 28153),
(144350, 'zhTW', '聯盟去死吧！', '聯盟去死吧！', 28153),
(144349, 'zhTW', '為了部落！', '為了部落！', 28153),
(144348, 'zhTW', '這邊！加入戰局！', '這邊！加入戰局！', 28153),
(144347, 'zhTW', '快點，蠻兵！我們有仗要打呢！', '快點，蠻兵！我們有仗要打呢！', 28153),
(144346, 'zhTW', '我叫格拉爾！', '', 28153),
(144345, 'zhTW', '你會在南方發現我神廟的廢墟，我將在那裡與你會面，然後我們要讓這些納迦知道惡鯊羅亞的憤怒！', '', 28153),
(144344, 'zhTW', '喔…你真美味。', '', 28153),
(144343, 'zhTW', '你已進入萬劫不復之境！', '', 28153),
(144342, 'zhTW', '阿塔格拉爾不歡迎納迦！', '', 28153),
(144341, 'zhTW', '納迦充滿怒意之血所散發美味而強烈的氣息…甜嫩的肉塊…算我一份。', '', 28153),
(144340, 'zhTW', '', '母親，班傑明把一切都告訴我了。\n\n你過去不能聽我說，但或許現在你可以？我所要的，只是一個解釋而已。', 28153),
(144339, 'zhTW', '', '母親，我知道你不在這裡。但若你能聽到我…', 28153),
(144338, 'zhTW', '我或許不是最好的管理員，但母親之前可厲害了。看到她如此沉淪…$b$b我們處理得來，$n。謝謝你的幫忙。', '', 28153),
(144337, 'zhTW', '', '你要去哪裡？', 28153),
(144336, 'zhTW', '', '拜託，你不要走。', 28153),
(144335, 'zhTW', '潮水下的主人會帶領我們獲得勝利！', '深海裡的主人會帶領我們獲得勝利！', 28153),
(144334, 'zhTW', '很高興看大家平安無事，多虧了…嘿！大英雄來了！', '', 28153),
(144333, 'zhTW', '你要待上一會兒，還是現在就要離開？', '', 28153),
(144332, 'zhTW', '抱歉，我必須找到我的姊妹。', '', 28153),
(144331, 'zhTW', '當父親死後，母親就消失了。但我從沒想過…', '', 28153),
(144330, 'zhTW', '她和我的父親窮盡一生努力建立了這番事業並養大我和我姊妹。', '', 28153),
(144329, 'zhTW', '那個女巫…她本來是我母親。', '', 28153),
(144328, 'zhTW', '看來你知道怎麼應付野獸，你需要什麼？', '', 28153),
(144327, 'zhTW', '怎麼了？你弄丟了什麼東西嗎？', '', 28153),
(144326, 'zhTW', '非常好！再一次，從頭開始。', '', 28153),
(144325, 'zhTW', '如果一次用掉太多能量會非常危險。大家記得調整自己的步調。', '', 28153),
(144324, 'zhTW', '匯聚起來的氣蘊含著非常強大的能量。等你準備好了，李淘大師會指導你的。', '', 28153),
(144323, 'zhTW', '治療的時候，你必須匯聚內在的力量，然後把這股力量傳遞出去。', '', 28153),
(144322, 'zhTW', '很高興我不用付出一切。', '很高興我不用付出一切。', 28153),
(144321, 'zhTW', '我那些受到腐化的兄弟姊妹還在荒野中到處遊蕩。', '我們受到腐化的兄弟姐妹還在荒野中到處遊蕩。', 28153),
(144320, 'zhTW', '', '我的生命…獻給部落。', 28153),
(144319, 'zhTW', '', '再見，朋友。', 28153),
(144318, 'zhTW', '', '鮮血與雷霆！', 28153),
(144317, 'zhTW', '', '我要砍死你。', 28153),
(144316, 'zhTW', '', '我要用劍把你切開。', 28153),
(144315, 'zhTW', '', '你根本不是獸人的對手！', 28153),
(144314, 'zhTW', '', '殺你還髒了我的劍！', 28153),
(144313, 'zhTW', '', '守住戰線！滴水不漏！', 28153),
(144312, 'zhTW', '謝謝你，朋友。', '', 28153),
(144311, 'zhTW', '如果之後見面認不出你，先跟你道個歉。', '', 28153),
(144310, 'zhTW', '謝謝你把托洛卡解決掉。他所追尋的這股力量隱藏著極大的危險，但他就是不願意相信。', '謝謝你把托洛卡解決掉。他所追尋的這股力量隱藏著極大的危險，但他就是不願意相信。', 28153),
(144309, 'zhTW', '<熟睡的牛頭人鼾聲雷動，翻了個身。>', '<熟睡的牛頭人鼾聲雷動，翻了個身。>', 28153),
(144308, 'zhTW', '呼嚕嚕嚕…', '呼嚕嚕嚕…', 28153),
(144307, 'zhTW', '公主，我願意。陪你到最後一刻。', '', 28153),
(144306, 'zhTW', '', '洛克漢，唯有如此，才能拯救我的人民。我願意付出一切來換取他們的平安，你們願意幫我嗎？', 28153),
(144305, 'zhTW', '我還是不敢相信，我的兄弟姊妹們會向惡魔屈服。', '我還是不敢相信，我的兄弟姊妹們會向惡魔屈服。', 28153),
(144304, 'zhTW', '', '女兒們，這就是你應付客人的方法！', 28153),
(144303, 'zhTW', '', '鮮血…會替我復仇…', 28153),
(144302, 'zhTW', '', '為戰母而戰！', 28153),
(144301, 'zhTW', '現在，集中真氣，把這股能量從你體內推出去。', '', 28153),
(144300, 'zhTW', '', '你的靈魂待在外頭比較有用！', 28153),
(144299, 'zhTW', '', '吸乾你一定很有趣。', 28153),
(144298, 'zhTW', '', '你的血給我們力量！', 28153),
(144297, 'zhTW', '', '我會奪走你的血。身體就腐爛吧！', 28153),
(144296, 'zhTW', '', '我的武器會沾滿你的血。', 28153),
(144295, 'zhTW', '如果你要搭便車，你知道在哪可以找到我！', '', 28153),
(144294, 'zhTW', '', '你的血，是很好的祭品！', 28153),
(144293, 'zhTW', '', '拿你們的皮來做鞍具！', 28153),
(144292, 'zhTW', '', '天空在…呼喚。', 28153),
(144291, 'zhTW', '', '今天真是適合戰鬥。', 28153),
(144290, 'zhTW', '', '克洛格今天能飽餐一頓了！', 28153),
(144289, 'zhTW', '堅持下去！我去看看薩陶的狀況。', '', 28153),
(144288, 'zhTW', '日記 - 黏液實驗\n\n讓黏液活性化的嘗試相當成功。它們可完全以蜂蜜為食，而不需分解肉或蔬菜等有機體。製造出來的大量廢棄物可在桶內發酵，釀成濃烈而美味的蜜酒。\n\n不過，如果沒有妥善隔離，黏液最終將找出並吞噬整個蜂巢。在過程中它們也時常變得更具侵略性而不受控制。\n\n而蜜蜂也會因此越來越有戒心，難以供我們所用。我顯然必須找出一個解決方案，因為蜜蜂沒那麼容易替代。', '', 28153),
(144287, 'zhTW', '', 'Pohkiza…', 28153),
(144286, 'zhTW', '', '一切歸於…血神…', 28153),
(144285, 'zhTW', '', '哈哈哈！', 28153),
(144284, 'zhTW', '', '祖達薩…會…滅亡…', 28153),
(144283, 'zhTW', '', 'Gachaga!', 28153),
(144282, 'zhTW', '', '姐妹們會…幫我…報仇…', 28153),
(144281, 'zhTW', '', '鮮血…獻給…古翰！', 28153),
(144280, 'zhTW', '', '古翰！', 28153),
(144279, 'zhTW', '<祖加像深情地你發出低吼。>', '', 28153),
(144278, 'zhTW', '我來自迷霧，在此警告贊達拉的人民。艾澤萊晶岩為猩猩帶來無比的智慧，引發戰爭的智慧。', '', 28153),
(144277, 'zhTW', 'Pohkiza…', '', 28153),
(144276, 'zhTW', '一切歸於…血神…', '', 28153),
(144275, 'zhTW', '你…已經…失敗了…', '', 28153),
(144274, 'zhTW', '祖達薩…會…滅亡…', '', 28153),
(144273, 'zhTW', 'Gachaga!', '', 28153),
(144272, 'zhTW', '為了戰母！', '', 28153),
(144271, 'zhTW', '鮮血…獻給…古翰！', '', 28153),
(144270, 'zhTW', '古翰！', '', 28153),
(144269, 'zhTW', '很好，很好。再一次！', '', 28153),
(144268, 'zhTW', '別再弄了。', '', 28153),
(144266, 'zhTW', '', '我要去幫助鎮民鞏固防線。我們到那裡碰面！', 28153),
(144265, 'zhTW', '', '我們打贏了。來吧！我們應該去找洛伊斯頓鎮長談談。', 28153),
(144264, 'zhTW', '', '艾蘭里亞嘆了口氣，眉頭緊皺。', 28153),
(144263, 'zhTW', '<請留步，聽我說個故事。>', '<請留步，聽我說個故事。>', 28153),
(144262, 'zhTW', '', '<艾蘭里亞的視線從石雕冰冷的臉龐，移到下方刻有她碑文的石板上。>', 28153),
(144261, 'zhTW', '撐住！我們要守住陣線！', '撐住！我們要守住陣線！', 28153),
(144260, 'zhTW', '你聽到洛柯臨死前的哀鳴。', '', 28153),
(144259, 'zhTW', '', '我要用你的肚皮做一頂新的帽子！', 28153),
(144258, 'zhTW', '', '不！我的寶貝！', 28153),
(144257, 'zhTW', '', '別傷害那個小傢伙！你別想離開這個洞窟了！', 28153),
(144256, 'zhTW', '', '他們想要我們的命！上，收拾他們！', 28153),
(144255, 'zhTW', '伯昂撒姆第…大發慈悲！', '伯昂撒姆第…大發慈悲！', 28153),
(144254, 'zhTW', '贊達拉…永垂不朽…', '贊達拉…永垂不朽…', 28153),
(144253, 'zhTW', '我們得讓你休息了，烏洛克！我很抱歉，但不得不如此啊！', '', 28153),
(144252, 'zhTW', '這是…這些東西在烏洛克幹啥？', '', 28153),
(144251, 'zhTW', '我們就快達成了！只要有我的工具…', '', 28153),
(144250, 'zhTW', '不應該這樣…', '不應該這樣…', 28153),
(144249, 'zhTW', '伯昂撒姆第…來找…我了…', '伯昂撒姆第…來找…我了…', 28153),
(144248, 'zhTW', '守住防線，更多敵人來了！', '守住防線，更多敵人來了！', 28153),
(144247, 'zhTW', '我為…贊達拉…而生…', '我為…贊達拉…而生…', 28153),
(144245, 'zhTW', 'Di chuka，贊達拉！', 'Di chuka，贊達拉！', 28153),
(144243, 'zhTW', '殺光他們！', '殺光他們！', 28153),
(144242, 'zhTW', '為了真正的贊達拉！', '為了真正的贊達拉！', 28153),
(144240, 'zhTW', '你的鮮血會灌溉我們的土地！', '你的鮮血會灌溉我們的土地！', 28153),
(144239, 'zhTW', '我們要殺了你！', '我們要殺了你！', 28153),
(144238, 'zhTW', '你會死在這裡！', '你會死在這裡！', 28153),
(144237, 'zhTW', '贊達拉永垂不朽！', '贊達拉永垂不朽！', 28153),
(144236, 'zhTW', '公主說找到怪物，他們全都是怪物！', '', 28153),
(144235, 'zhTW', '太陽在哪裡？我在這沼澤臭坑裡什麼都看不到。', '', 28153),
(144234, 'zhTW', '這沒有道理！我看到一個大洞。這張地圖沒有任何洞！', '', 28153),
(144233, 'zhTW', '喔！這是…這…什麼都沒… 真令人失望。', '', 28153),
(144232, 'zhTW', 'Taz\'okun！這可能是艾澤萊晶岩！', '', 28153),
(144231, 'zhTW', '這是某種針頭嗎？呃，為何這麼黏？', '', 28153),
(144230, 'zhTW', '喔，這很可愛。塔蘭姬可能會喜歡。', '', 28153),
(144229, 'zhTW', '妖役弓弩手瞄準你了！快閃開！', '', 28153),
(144228, 'zhTW', '這附近需要劍的人不多，但我很愛打造它們。我不喜歡我們需要這麼多劍的原因就是了！', '', 28153),
(144227, 'zhTW', '我看出人們為何害怕這片沼澤了。', '', 28153),
(144226, 'zhTW', '好奇怪。', '', 28153),
(144225, 'zhTW', '我不認為我能把這汙點從我的雙手移除。我可憐的卷軸。', '', 28153),
(144224, 'zhTW', '這是一個奇怪的岩石…喔！它動了！', '', 28153),
(144223, 'zhTW', '真是有趣。', '', 28153),
(144222, 'zhTW', '剛克會指引你。', '剛克會指引你。', 28153),
(144221, 'zhTW', '帕骷會守護你。', '帕骷會守護你。', 28153),
(144220, 'zhTW', '瑞贊會給你力量。', '瑞贊會給你力量。', 28153),
(144219, 'zhTW', '一切小心。', '一切小心。', 28153),
(144218, 'zhTW', '在我們城裡要多小心。', '在我們城裡要多小心。', 28153),
(144217, 'zhTW', '贊達拉永垂不朽！', '贊達拉永垂不朽！', 28153),
(144216, 'zhTW', '你也需要保護嗎？', '你也需要保護嗎？', 28153),
(144215, 'zhTW', '這裡的東西價格最划算。', '這裡賣的東西價格是最划算的。', 28153),
(144214, 'zhTW', '你來這裡做什麼？', '你來這裡做什麼？', 28153),
(144213, 'zhTW', '你好。', '你好啊。', 28153),
(144209, 'zhTW', '我誓死保衛王室的安全。', '我誓死保護王室的安全。', 28153),
(144208, 'zhTW', '我們會捍衛這個王國。', '我們會捍衛這個王國。', 28153),
(144201, 'zhTW', '開始吧。', '開始吧。', 28153),
(144200, 'zhTW', '我們現在非常接近了，$n。$b$b跟我說一聲，我就會開始占卜。$b$b喔，我忘記提到了。我們的敵人已經沿著對面的海灘紮了營地。我會密切觀察你的周圍，以防遭人埋伏。$b$b如果有人發現我們，你想必會保護我的！', '', 28153),
(144199, 'zhTW', '大家撐住！我們快擊退他們了！', '', 28153),
(144198, 'zhTW', '天要黑了！別讓火焰熄滅！如果燃料不夠，立刻回報請別人幫忙。', '', 28153),
(144197, 'zhTW', '絕對不能讓任何怪物通過！我們雖然殺了巨怪，卻也損失了相當多船隻。', '', 28153),
(144196, 'zhTW', '休息過的人，去跟防禦工事那邊的人換班！我們一定要擋住這些怪物！', '', 28153),
(144195, 'zhTW', '我需要志願者去艾希頓那裡幫忙！他或許有辦法弄出幾個信號彈。', '', 28153),
(144194, 'zhTW', '先讓這些孩子吃飯，再來換傷患吃！', '', 28153),
(144193, 'zhTW', '治療人員務必輪班休息！克絲汀，我就是在說你！', '', 28153),
(144192, 'zhTW', '快加強防禦！把沒釘死在地上的都拿來！不夠的話，就算釘死的也連釘子一起拔起來用！', '', 28153),
(144191, 'zhTW', '小克洛格發出奇怪的吱吱聲，雙腳在睡蓮葉踏著。', '', 28153),
(144190, 'zhTW', '這些水手應該專心留意部落的人，而不是我們。', '這些水手應該專心留意部落的人，而不是我們。', 28153),
(144189, 'zhTW', '一找到我們要的東西，就開船離開這吧，越快越好。', '一找到我們要的東西，就開船離開這吧，越快越好。', 28153),
(144188, 'zhTW', '部落的人靠近了，提高警覺！', '部落的人靠近了，提高警覺！', 28153),
(144187, 'zhTW', '我真希望探險者協會當初帶了更多人來這次考察。', '我真希望探險者協會當初帶了更多人來這次考察。', 28153),
(144186, 'zhTW', '如果我們沒有來這留意黑鐵人，誰知道他們會做出什麼事？', '如果我們沒有來這留意黑鐵人，誰知道他們會做出什麼事？', 28153),
(144185, 'zhTW', '', '還有他們的孩子！我可以設個拍照台和恐龍娃娃。當然你也有得分，詹加拉，看是要七三分還是怎麼樣。身為出點子的，我當然還是分多點。', 28153),
(144184, 'zhTW', '前方還需要幫助，如果你願意幫忙的話。', '', 28153),
(144183, 'zhTW', '', '使用我：該準備使用注射器激怒班金了，然後跟隨他，協助他消滅入侵的人。', 28153),
(144182, 'zhTW', '等我們在這挖完後，部落都已經快到鐵爐堡了！', '等我們在這挖完後，部落都已經快到鐵爐堡了！', 28153),
(144181, 'zhTW', '黑鐵人不怕熱，但這股濕氣…', '黑鐵人不怕熱，但這股濕氣…', 28153),
(144180, 'zhTW', '探險者協會真的很喜歡慢慢地挖東西，明明還有不能輸的仗要打。', '探險者協會真的很喜歡慢慢地挖東西，明明還有不能輸的仗要打。', 28153),
(144179, 'zhTW', '我們為了這個離開了我們的山？', '我們為了這個離開了我們的山？', 28153),
(144178, 'zhTW', '你不需要這麼戲劇化。', '', 28153),
(144177, 'zhTW', '', '這些刮痕…泥土除得凹凸不平…噢，現在我們要怎麼展示它？', 28153),
(144176, 'zhTW', '真的有這麼糟嗎？', '', 28153),
(144175, 'zhTW', '', '等等！', 28153),
(144174, 'zhTW', '我的朋友，請自由探查這裡，這個儀器會幫你的忙。', '', 28153),
(144173, 'zhTW', '過癮？女士，照這速度，我們會在這一整年。', '', 28153),
(144172, 'zhTW', '', '啊啊啊，太美好了，是不是很過癮呢？', 28153),
(144171, 'zhTW', '', '小心別傷害到化石…非常好。', 28153),
(144170, 'zhTW', '', '非常好，現在，手拿穩一點。', 28153),
(144169, 'zhTW', '', '小心一點，德魯伊！這裡是個死亡陷阱！', 28153),
(144168, 'zhTW', '做得漂亮！我們應該可以用這個來對付那些巨大的木頭怪物了。啊…千萬小心別灑出來了。', '', 28153),
(144167, 'zhTW', '謝謝你將她帶回我身邊。', '', 28153),
(144166, 'zhTW', '', '使用我：這箱就是奇怪的注入裝置。請注射它。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144165, 'zhTW', '', '嗨，老爹！', 28153),
(144164, 'zhTW', '潘妮！噢，我親愛的女孩！', '', 28153),
(144163, 'zhTW', '你在伐木場的優勢只是暫時的！我們會再次把它奪回來的！', '', 28153),
(144162, 'zhTW', '我們去找你爸爸吧。', '我們去找你爸爸吧。', 28153),
(144161, 'zhTW', '', '嗨！你叫什麼名字？', 28153),
(144160, 'zhTW', '你看不出來你的處境有多危險嗎？', '你看不出來你的處境有多危險嗎？', 28153),
(144159, 'zhTW', '你阻止不了我們全部人！', '你阻止不了我們全部人！', 28153),
(144158, 'zhTW', '你絕對找不到我們全部人！', '你絕對找不到我們全部人！', 28153),
(144157, 'zhTW', '我被包圍了！', '我被包圍了！', 28153),
(144156, 'zhTW', '看哪！他們甚至拿了我們的一個鼓！\n\n誰說哥布林沒有文化？', '', 28153),
(144153, 'zhTW', '接下來需要幾滴爆燃汁液。小心不要晃得太用力！', '', 28153),
(144152, 'zhTW', '再加一點硫磺。小心煙霧！', '', 28153),
(144151, 'zhTW', '現在小心地加一點爐邊之花進去。', '', 28153),
(144150, 'zhTW', '我們要加點硝石，讓它更有威力！', '', 28153),
(144148, 'zhTW', '奎格瓦對你的夥伴點了點頭。', '', 28153),
(144147, 'zhTW', '奎格瓦似乎和小克洛格在溝通。', '', 28153),
(144146, 'zhTW', '不！ 我才不要回去那個鬼地方！', '', 28153),
(144145, 'zhTW', '', '守住聖壇！我們一定不能失去控制權。', 28153),
(144144, 'zhTW', '太好了！我會告訴你要在大鍋裡加什麼東西。一定要照我的指示做，不然做出來的東西可能會…爆炸。', '', 28153),
(144142, 'zhTW', '再見，佩妮。', '', 28153),
(144141, 'zhTW', '', '對啊，等會見，喬！', 28153),
(144140, 'zhTW', '', '嘿，喬！', 28153),
(144139, 'zhTW', '噢嘿，佩妮。妳要去看妳爸嗎？', '', 28153),
(144138, 'zhTW', '大家怎麼回事？！', '', 28153),
(144137, 'zhTW', '', '我需要治療！', 28153),
(144136, 'zhTW', '', '向元素投降！', 28153),
(144135, 'zhTW', '$n，我沒有辦法把他變回來，但如果他在你身邊，日子會比較好過。就讓他陪著你吧，別讓他挨餓受凍。', '', 28153),
(144134, 'zhTW', '我明白了。', '', 28153),
(144133, 'zhTW', '靠近一點，年輕人。', '', 28153),
(144132, 'zhTW', '噩夢…', '', 28153),
(144131, 'zhTW', '月亮…正在升起…', '', 28153),
(144130, 'zhTW', '遙遠的海岸…', '', 28153),
(144129, 'zhTW', '別攪拌…鍋子…', '', 28153),
(144128, 'zhTW', '再兩杯酒…還有你最大根的辣椒…', '', 28153),
(144127, 'zhTW', '中央山嶺…翻轉…', '', 28153),
(144126, 'zhTW', '再十分鐘…', '', 28153),
(144125, 'zhTW', '還沒…', '', 28153),
(144124, 'zhTW', '彈彈防衛性地低吼。', '', 28153),
(144123, 'zhTW', '準備送命吧！', '準備送命吧！', 28153),
(144122, 'zhTW', '接受…你的命運…', '', 28153),
(144121, 'zhTW', '沒有…勝利…只有…死亡…', '', 28153),
(144120, 'zhTW', '不足以…對抗…虛無…', '', 28153),
(144119, 'zhTW', '你…贏不了的…', '', 28153),
(144118, 'zhTW', '主人…醒來…', '', 28153),
(144117, 'zhTW', '虛無會…吞噬一切…', '', 28153),
(144116, 'zhTW', '沒用的…一切都會…歸於黑暗…', '', 28153),
(144115, 'zhTW', '他們會在港口找到你的屍體！', '他們會在港口找到你的屍體！', 28153),
(144114, 'zhTW', '庫爾提拉斯不需要聯盟！', '庫爾提拉斯不需要聯盟！', 28153),
(144113, 'zhTW', '我會把你丟去海裡！', '我會把你丟去海裡！', 28153),
(144112, 'zhTW', '<加入激流堡之役佇列>', '<加入激流堡之役佇列>', 28153),
(144111, 'zhTW', '你可以利用這張桌子來加入戰爭前線的佇列。', '', 28153),
(144110, 'zhTW', '凱瑟琳會眼睜睜看著我們全部淹死！', '凱瑟琳會眼睜睜看著我們全部淹死！', 28153),
(144109, 'zhTW', '艾澤拉斯屬於我們。', '', 28153),
(144108, 'zhTW', '帝國會再度興盛！', '', 28153),
(144107, 'zhTW', '找到他們！', '', 28153),
(144106, 'zhTW', '全部都會滅亡。', '', 28153),
(144105, 'zhTW', '你們全都會死。', '', 28153),
(144104, 'zhTW', '沒有希望…也沒有生命。', '', 28153),
(144103, 'zhTW', '全都會被吞噬。', '', 28153),
(144102, 'zhTW', '一切都會變成暗影。', '', 28153),
(144101, 'zhTW', '虛無會吞噬一切。', '', 28153),
(144100, 'zhTW', '', '利爪德魯伊，攻擊！', 28153),
(144099, 'zhTW', '<吹哨>', '', 28153),
(144097, 'zhTW', '', '只好執行B計畫了…', 28153),
(144096, 'zhTW', '拿到情報了。我們只要想辦法離開就好！', '', 28153),
(144095, 'zhTW', '', '我們被發現了！', 28153),
(144094, 'zhTW', '發 - 發 - 發發發…<雜訊>現艾澤拉斯之血。指令：安裝遺失的資 - 資 - 資資資資料…<雜訊>核心。', '', 28153),
(144093, 'zhTW', '呃，這真是糟糕！', '', 28153),
(144092, 'zhTW', '加巴里，你的記憶力跟伊萊克和剛克一樣好。', '', 28153),
(144091, 'zhTW', '當然，我們用「辛辣」來形容死亡劇毒，還真是個恰當的比較…', '', 28153),
(144090, 'zhTW', '加巴里，不用照顧我！不過是豪利的辣椒，我撐過來了！', '', 28153),
(144089, 'zhTW', '別說話了，你聽起來像喉嚨痛的布魯多。', '', 28153),
(144088, 'zhTW', '噓，我的兄弟。把這拿去。', '', 28153),
(144087, 'zhTW', '別在瞎鬧了！', '', 28153),
(144086, 'zhTW', '就是這樣！接著來看看還有什麼…', '', 28153),
(144085, 'zhTW', '我敢說你一定接觸過鍊金術！我看得出來！', '', 28153),
(144084, 'zhTW', '做得好！接下來我們要…', '', 28153),
(144082, 'zhTW', '第一槍已經上膛了，一旦我開火，他們就會知道我們在這裡。$b$b你準備好了嗎？', '', 28153),
(144081, 'zhTW', '他們遲早會查到這裡…', '', 28153),
(144080, 'zhTW', '', '好！我們走！', 28153),
(144079, 'zhTW', '', '等等！我們要牽著手才行！', 28153),
(144078, 'zhTW', '普勞德摩爾必敗！', '普勞德摩爾必敗！', 28153),
(144077, 'zhTW', '我的死並不能阻止局勢的變化。', '我的死並不能阻止局勢的變化。', 28153),
(144076, 'zhTW', '你會後悔的！', '你會後悔的！', 28153),
(144075, 'zhTW', '這裡沒有你的容身處，外來者！', '這裡沒有你的容身處，外來者！', 28153),
(144074, 'zhTW', '波拉勒斯是我們的！', '波拉勒斯是我們的！', 28153),
(144073, 'zhTW', '', '從這裡到阿塔達薩到處都是祖爾的手下。想辦法除掉他們。', 28153),
(144072, 'zhTW', '精靈…', '精靈…', 28153),
(144071, 'zhTW', '拉斯塔瑞執法者往地上吐口水。', '拉斯塔瑞執法者嘆氣。', 28153),
(144070, 'zhTW', '我當然會，這個這麼原始。好了，3…2…1…', '', 28153),
(144069, 'zhTW', '', '記得要把背景又大又醜的神殿拍進去。', 28153),
(144068, 'zhTW', '', '我們所有銀月城的朋友看到這張照片時，都會很嫉妒的。', 28153),
(144067, 'zhTW', '我的旅途結束了。我完成了我故事的最後一筆，並且回到物質界。', '我的旅途結束了。我完成了我故事的最後一筆，並且回到物質界。', 28153),
(144066, 'zhTW', '它攫住了我的目光，同化著我的心靈，以我需要用來召喚它的知識填滿我的心智。', '它攫住了我的目光，同化著我的心靈，以我需要用來召喚它的知識填滿我的心智。', 28153),
(144065, 'zhTW', '它停止成形，並且為它的新生命發出哭喊。', '它停止成形，並且為它的新生命發出哭喊。', 28153),
(144064, 'zhTW', '儀式完成，我看到某種生物在我眼前聚合成形。', '儀式完成，我看到某種生物在我眼前聚合成形。', 28153),
(144063, 'zhTW', '當我進入那房間的時候，我注意到散佈在地面上的符文。這一定就是那些墨水的用途。', '當我進入那房間的時候，我注意到散佈在地面上的符文。這一定就是那些墨水的用途。', 28153),
(144062, 'zhTW', '當我收集了足夠的墨水，我感覺到一股奇怪的牽引，指向這些大廳的盡頭。', '當我收集了足夠的墨水，我感覺到一股奇怪的牽引，指向這些大廳的盡頭。', 28153),
(144061, 'zhTW', '一句地面上的骷髏提醒了我，我不過是名凡人。我在想之前是否有其他人在這裡失敗。', '一句地面上的骷髏提醒了我，我不過是名凡人。我在想之前是否有其他人在這裡失敗。', 28153),
(144060, 'zhTW', '這些黏稠的東西開始變得真的很討厭了。', '這些黏稠的東西開始變得真的很討厭了。', 28153),
(144059, 'zhTW', '這些泥團就是謎題的關鍵。而目前為止，我都能找到我所需要的。', '這些泥團就是謎題的關鍵。而目前為止，我都能找到我所需要的。', 28153),
(144058, 'zhTW', '不知為何，我卻知道自己該做什麼。我決定繼續下去。', '不知為何，我卻知道自己該做什麼。我決定繼續下去。', 28153),
(144057, 'zhTW', '避開漆黑，收集赤紅，那麼你的血縛殺手就會復甦。」', '避開漆黑，收集赤紅，那麼你的血縛殺手就會復甦。」', 28153),
(144056, 'zhTW', '「從筆尖溢出的，與從血管溢出的，全都在裡面混合交融。」', '「從筆尖溢出的，與從血管溢出的，全都在裡面混合交融。」', 28153),
(144055, 'zhTW', '我在一個房間裡醒來。在我腦海裡有個奇異的聲音，在引述一首詩。', '我在一個房間裡醒來。在我腦海裡有個奇異的聲音，在引述一首詩。', 28153),
(144054, 'zhTW', '你開始在書上寫字，『當筆尖碰觸到書頁的時候，我覺得自己被拉了進去。』', '你開始在書上寫字，『當筆尖碰觸到書頁的時候，我覺得自己被拉了進去。』', 28153),
(144053, 'zhTW', '瀏覽了整本書，每一頁似乎都是空白的。你灰心的看向克隆娜，想著她知不知道些什麼。', '', 28153),
(144052, 'zhTW', '我很期待能讀到你的冒險經歷。', '', 28153),
(144051, 'zhTW', '只要拿起一支筆，開始寫就對了。別擔心，剩下的就交給書吧。', '', 28153),
(144050, 'zhTW', '這很簡單，親愛的。你得在書裡寫下自己的故事。', '', 28153),
(144049, 'zhTW', '天啊，又開始了…', '', 28153),
(144048, 'zhTW', '我想要兌換一些我的刺針。', '我想要兌換一些我的刺針。', 28153),
(144047, 'zhTW', '天啊，不應該是這種結果。再試一次！', '', 28153),
(144046, 'zhTW', '鍊金術是種精確的科學！請好好集中精神。', '', 28153),
(144045, 'zhTW', '噢，這下錯了。我們要從頭開始了！', '', 28153),
(144044, 'zhTW', '混合物燒起來了！我們得重新開始了！', '混合物燒起來了！我們得重新開始了！', 28153),
(144043, 'zhTW', '祖爾早就知道有這麼一天。你努力對抗命運，只是證明這一切都已經注定了！', '', 28153),
(144042, 'zhTW', '祖爾…從來沒說過…我會輸…', '', 28153),
(144041, 'zhTW', '你絕對不可能來得及！', '', 28153),
(144040, 'zhTW', '我準備好要開始了！', '我準備好要開始了！', 28153),
(144039, 'zhTW', '等等！我已經好多了！呃啊啊…', '等等！我已經好多了！呃啊啊…', 28153),
(144038, 'zhTW', '我真蠢！', '我真蠢！', 28153),
(144037, 'zhTW', '再也聽不到她的歌了…', '再也聽不到她的歌了…', 28153),
(144036, 'zhTW', '她永遠不會愛你！', '她永遠不會愛你！', 28153),
(144035, 'zhTW', '不，寶貝！', '不，寶貝！', 28153),
(144034, 'zhTW', '愛情…好痛。', '愛情…好痛。', 28153),
(144033, 'zhTW', '值得！', '值得！', 28153),
(144032, 'zhTW', '分離是如此甜蜜的悲傷。', '分離是如此甜蜜的悲傷。', 28153),
(144031, 'zhTW', '嘿，寶貝，看我把這傢伙揍扁。', '嘿，寶貝，看我把這傢伙揍扁。', 28153),
(144030, 'zhTW', '你敢偷看我的女人？！', '你敢偷看我的女人？！', 28153),
(144029, 'zhTW', '愛會征服一切！', '愛會征服一切！', 28153),
(144028, 'zhTW', '她是我的！我的！', '她是我的！我的！', 28153),
(144027, 'zhTW', '盟友，謝謝你，你救了整座村莊，也讓我變得更有勇氣。阿爾比、瑟羅德，請幫忙重建釣點。我會盡快傳消息。', '', 28153),
(144026, 'zhTW', '不准你碰她！', '不准你碰她！', 28153),
(144025, 'zhTW', '祖爾想喚醒達薩？我可不會就這樣讓這名「先知」褻瀆先王的遺骨。來吧，勇士，與我們在南大門會和。', '', 28153),
(144024, 'zhTW', '我必須回家一趟。叔叔跟斯陀頌恩谷地的浪潮賢者，或許知道更多關於這種黑暗魔法的事情。', '', 28153),
(144023, 'zhTW', '迪普瓦登…他一直很聰明，但我沒想到他會去碰這種魔法。竟然能控制連大海都懼怕的力量…', '', 28153),
(144022, 'zhTW', '滾開，她是我的！', '滾開，她是我的！', 28153),
(144021, 'zhTW', '', '好！他們的滅天者弩砲出現射擊死角。飛吧，孩子們，殺光這些邪教徒！', 28153),
(144020, 'zhTW', '釣點獲救了，但我還是很不安。迪普瓦登雖然聰明，但就算是他，本來也沒有這種力量。', '', 28153),
(144019, 'zhTW', '寶貝，我來保護你！', '寶貝，我來保護你！', 28153),
(144018, 'zhTW', '我超級愛她！', '我超級愛她！', 28153),
(144017, 'zhTW', '天命之手十分滿足，我會把你平安送回去。天命也是有仁慈的一面。', '', 28153),
(144016, 'zhTW', '滾出我們的城市，$p！你會害死我們！', '', 28153),
(144015, 'zhTW', '讓路給$p，他是羅亞的祝福！', '', 28153),
(144013, 'zhTW', '', '預兆有好有壞…你會面對不可能的挑戰，但你會克服它們。羅亞沒有拋棄你。', 28153),
(144012, 'zhTW', '', '我恐怕這些都是不好的預兆… 你的未來將有無盡的麻煩。我很抱歉。', 28153),
(144011, 'zhTW', '', '今天避開水域，它們不太安全。', 28153),
(144010, 'zhTW', '', '空的？不…你必須改變它。', 28153),
(144009, 'zhTW', '', '你會經歷巨大的磨難和背叛。今天要謹慎選擇你的夥伴。', 28153),
(144008, 'zhTW', '', '我已經很久沒有聽到這個預兆了…你必須改變你的命運。', 28153),
(144007, 'zhTW', '', '今天別為了追尋你的目標而走捷徑。任何妥協或粗心會導致恐怖的後果。', 28153),
(144006, 'zhTW', '', '來自彼界的警告。小心一點。', 28153),
(144005, 'zhTW', '', '小心黃金之城，它不值得冒險。', 28153),
(144004, 'zhTW', '', '恐怕你必須盲目地迎接未來。', 28153),
(144003, 'zhTW', '', '格拉爾被一隻看不見的手拉進深處。', 28153),
(144002, 'zhTW', '', '沙德拉的巢是空的。', 28153),
(144001, 'zhTW', '', '托卡利睡了。', 28153),
(144000, 'zhTW', '', '瑞贊摔到地上…死了。', 28153),
(143999, 'zhTW', '', '伯昂撒姆第帶著微笑提出交易。', 28153),
(143998, 'zhTW', '', '奎格瓦吞噬一群藍色恐角龍。', 28153),
(143997, 'zhTW', '', '剛克獨自一人，游過一條黃金之河。', 28153),
(143996, 'zhTW', '', '帕骷在黑暗中閉上她的雙眼。', 28153),
(143995, 'zhTW', '', '再沒有比這個更不吉利的預兆了。小心腳步。', 28153),
(143994, 'zhTW', '', '讓所有人大難臨頭的黑暗預兆，你究竟帶了什麼來我們的海岸？', 28153),
(143993, 'zhTW', '', '你在浪費你的才能。把握你面前的機會，或者泯滅在無名無姓的死人之中。', 28153),
(143992, 'zhTW', '', '你與你盟友的分裂讓所有人身陷險境，你必須團結贊達拉。', 28153),
(143991, 'zhTW', '', '預兆雖然不吉利，但你可以憑著實力和決心克服。', 28153),
(143990, 'zhTW', '', '各自為政的首領算不上首領。你必須跟你的對手合作，或者承擔分裂的後果。', 28153),
(143989, 'zhTW', '', '就連最強壯的人都逃不過被黑暗吞噬的命運。即使是你也一樣。', 28153),
(143988, 'zhTW', '', '一個我們全部人的黑暗預兆…', 28153),
(143987, 'zhTW', '', '一位新朋友之死。', 28153),
(143986, 'zhTW', '', '納茲米爾黑暗沼澤內的落日。', 28153),
(143985, 'zhTW', '', '一個破損的酒瓶，滴著酒液。', 28153),
(143984, 'zhTW', '', '兩個牧師自相殘殺。', 28153),
(143983, 'zhTW', '', '一艘人船，在我們的海岸登陸…', 28153),
(143982, 'zhTW', '', '一座破裂的冰與火之冠…', 28153),
(143981, 'zhTW', '', '一條滿身是血的雷龍。', 28153),
(143980, 'zhTW', '', '一條鮮血之河，屍首逆流而上…', 28153),
(143979, 'zhTW', '來吧，抓抓。我們走！', '過來，抓抓！走吧！', 28153),
(143978, 'zhTW', '耶！謝謝你！', '耶！謝謝你！', 28153),
(143977, 'zhTW', '哇，這樣好多了！', '', 28153),
(143976, 'zhTW', '我催促他們離開，但他們還想再多待一下子…我好不容易才逃出來…要不是你的話，我一定無法活著離開。', '', 28153),
(143975, 'zhTW', '', '請透過你的容器說話，濟托亞！', 28153),
(143974, 'zhTW', '', '請透過你的容器說話，伊露娜！', 28153),
(143973, 'zhTW', '', '我們準備好了。注滿我的容器並向我們揭示未來。', 28153),
(143972, 'zhTW', '', '亡者之靈、羅亞之靈、失落而苦惱之靈，請聽我訴說！', 28153),
(143971, 'zhTW', '我要回到防線那裡！', '我要回到防線那裡！', 28153),
(143970, 'zhTW', '我剛剛完全動不了！', '我剛剛完全動不了！', 28153),
(143969, 'zhTW', '我還以為我也要被拖進林子裡了！', '我還以為我也要被拖進林子裡了！', 28153),
(143968, 'zhTW', '她們已經抓了好幾個人進林子裡了！', '她們已經抓了好幾個人進林子裡了！', 28153),
(143967, 'zhTW', '我要回到路障那裡去！', '我要回到路障那裡去！', 28153),
(143966, 'zhTW', '', '你的預兆都是好的…今天就大膽行動吧！', 28153),
(143965, 'zhTW', '我還以為我也完蛋了！', '我還以為我也完蛋了！', 28153),
(143964, 'zhTW', '謝謝你！', '謝謝你！', 28153),
(143963, 'zhTW', '', '獸群奔竄…', 28153),
(143962, 'zhTW', '', '令人愉快的預言…別讓焦慮把你壓垮。快樂和幽默會引你走向成功。', 28153),
(143961, 'zhTW', '荒疫蔓生！', '', 28153),
(143960, 'zhTW', '全都會…凋零…', '', 28153),
(143959, 'zhTW', '', '這是沙德拉最常見的祝福，還有個意外的附加結果。雖說我沒法全然理解，但這仍是不錯的。', 28153),
(143958, 'zhTW', '', '防禦者的祝福…你會拯救許多生命，但或許得放棄你自己的。', 28153),
(143957, 'zhTW', '', '國王的羅亞是個罕見的預兆，充滿力量且強大。你會摧毀國王的敵人。', 28153),
(143956, 'zhTW', '', '一個顯示出長命和安息的好預兆。', 28153),
(143955, 'zhTW', '需要肥料！', '', 28153),
(143954, 'zhTW', '枯萎！', '', 28153),
(143953, 'zhTW', '腐化繁茂！', '', 28153),
(143952, 'zhTW', '', '假如島嶼不是你的家鄉，那這就是個好預兆。', 28153),
(143951, 'zhTW', '成長吧！', '', 28153),
(143950, 'zhTW', '', '你永遠會和盟友並肩作戰。剛克不會在你的危急時刻拋棄你的。', 28153),
(143949, 'zhTW', '', '帕骷會引導你的旅程，讓你不受敵人侵擾…', 28153),
(143948, 'zhTW', '甜美的肥料。', '', 28153),
(143947, 'zhTW', '', '格拉爾躍過神王的艦隊…', 28153),
(143946, 'zhTW', '', '沙德拉的蛋孵化了。無數眼睛衝向前…', 28153),
(143945, 'zhTW', '', '托卡利獨自在山巔站立…', 28153),
(143944, 'zhTW', '', '瑞贊踏地一跺，鮮血食人妖四處逃竄…', 28153),
(143943, 'zhTW', '', '伯昂撒姆第望向別處…', 28153),
(143942, 'zhTW', '', '奎格瓦吞下了一座島嶼…', 28153),
(143941, 'zhTW', '惡瘡！', '', 28153),
(143940, 'zhTW', '', '剛克與他的獸群一同奔跑…', 28153),
(143939, 'zhTW', '收割！', '', 28153),
(143938, 'zhTW', '讓腐敗蔓延吧！', '', 28153),
(143937, 'zhTW', '', '幾乎總是一個好預兆，但禍福還是要取決於你自己，朋友…', 28153),
(143936, 'zhTW', '', '這對我們所有人都是好預兆。贊達拉歡迎你的到來。', 28153),
(143935, 'zhTW', '', '雖然許多人意見相左，但你其實還沒發揮全部的潛力。你的力量還會成長，而你將會超乎想像地強大。', 28153),
(143934, 'zhTW', '', '一個…對外來者來說相當驚奇的預兆。這是什麼意思？', 28153),
(143933, 'zhTW', '', '一個強大的預兆！這對你很有利…', 28153),
(143932, 'zhTW', '', '一個對我們人民來說象徵擴張以及成長的好預兆。有趣的是這預兆是要給你的…', 28153),
(143931, 'zhTW', '', '一個象徵繁榮與遺緒的好預兆。', 28153),
(143930, 'zhTW', '', '一個象徵堅強、力量、以及成功的好預兆。', 28153),
(143929, 'zhTW', '', '過去的好友復生…', 28153),
(143928, 'zhTW', '', '太陽在金色水面上升起…', 28153),
(143927, 'zhTW', '', '巨大的蛋，劇烈地抖動，但沒有破殼…', 28153),
(143926, 'zhTW', '', '所有食人妖部族都集結在贊達拉的旗幟下…', 28153),
(143925, 'zhTW', '', '被斬斷的精靈頭…', 28153),
(143924, 'zhTW', '', '古老的水，世代不受擾動…', 28153),
(143923, 'zhTW', '', '黃金面具…', 28153),
(143922, 'zhTW', '', '帕骷的陰影跨越了一條石徑…', 28153),
(143921, 'zhTW', '', '很好。讓我們看看魂靈要對你說什麼…', 28153),
(143920, 'zhTW', '', '你確定你想知道嗎，$p？\n\n不是所有的命運都有偉大的功績和快樂的結局…', 28153),
(143919, 'zhTW', '我並不害怕。告訴我你在我的未來看到什麼。', '我並不害怕。告訴我你在我的未來看到什麼。', 28153),
(143918, 'zhTW', '你在我的未來看到什麼？', '你在我的未來看到什麼？', 28153),
(143917, 'zhTW', '', '失落而古老的靈魂，請聽我說。注滿我的容器，向我們顯現未來。', 28153),
(143916, 'zhTW', '無所謂。我們無處不在…甚至就在你腳下。', '', 28153),
(143915, 'zhTW', '你很弱小…我們這一族…會越來越強大。', '你很弱小…我們這一族…會越來越強大。', 28153),
(143914, 'zhTW', '', '$p，歡迎來到迷失靈魂小屋。\n\n你來遲了，我不確定你會不會來。\n\n告訴我，科娜瓦女士今天能為你做什麼？', 28153),
(143913, 'zhTW', '我死得有價值…', '我死得有價值…', 28153),
(143912, 'zhTW', '我們的荊棘…會長滿這片土地…', '我們的荊棘…會長滿這片土地…', 28153),
(143911, 'zhTW', '棘背一族…會變得更強大…', '棘背一族…會變得更強大…', 28153),
(143910, 'zhTW', '我的旅程…結束了。', '我的旅程…結束了。', 28153),
(143909, 'zhTW', '你的死亡帶給我榮耀。', '你的死亡帶給我榮耀。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143908, 'zhTW', '你的鮮血會讓荊棘長得更茁壯。', '你的鮮血會讓荊棘長得更茁壯。', 28153),
(143907, 'zhTW', '絕不撤退！絕不投降！', '絕不撤退！絕不投降！', 28153),
(143906, 'zhTW', '放血手冊為什麼是空白的？', '放血手冊為什麼是空白的？', 28153),
(143905, 'zhTW', '我要拿你來餵野豬。', '我要拿你來餵野豬。', 28153),
(143904, 'zhTW', '你別想阻擋我們！', '你別想阻擋我們！', 28153),
(143903, 'zhTW', '這裡是我們的了！', '這裡是我們的了！', 28153),
(143902, 'zhTW', '開始在書上寫字。', '開始在書上寫字。', 28153),
(143901, 'zhTW', '快速翻閱這整本書。', '快速翻閱這整本書。', 28153),
(143900, 'zhTW', '抓抓！你還在嗎？！聽見的話就喵兩聲！', '抓抓！你還在嗎？！聽見的話就喵兩聲！', 28153),
(143899, 'zhTW', '接下來的幾頁看起來也是空白的。', '', 28153),
(143898, 'zhTW', '我們會救你，抓抓！乖乖別動！', '我們會救你，抓抓！乖乖別動！', 28153),
(143897, 'zhTW', '沒事的，抓抓！在那等會！', '沒事的，抓抓！你等著別動！', 28153),
(143896, 'zhTW', '再多翻幾頁。', '再多翻幾頁。', 28153),
(143895, 'zhTW', '書頁看起來是空白的。', '', 28153),
(143894, 'zhTW', '咪喵嗚嗚嗚。', '', 28153),
(143893, 'zhTW', '撐著，抓抓！救援要到了！', '別擔心，抓抓！馬上就有人來救你！', 28153),
(143892, 'zhTW', '抓抓下來！下來！上面不安全！', '抓抓下來！下來！上面不安全！', 28153),
(143891, 'zhTW', '跳下來，抓抓！我會接住你！', '抓抓，跳下來！我會接住你！', 28153),
(143890, 'zhTW', '抓抓啊！快下來！！', '抓抓啊！快下來！！', 28153),
(143889, 'zhTW', '', '我會拿你來餵我的寵物，$r！', 28153),
(143888, 'zhTW', '勇士，這裡。', '', 28153),
(143887, 'zhTW', '在這裡！', '', 28153),
(143886, 'zhTW', '小心！', '', 28153),
(143885, 'zhTW', '走這邊。', '', 28153),
(143884, 'zhTW', '走這邊。', '', 28153),
(143883, 'zhTW', '小心！', '', 28153),
(143882, 'zhTW', '在這裡！', '', 28153),
(143881, 'zhTW', '你，過來。', '', 28153),
(143879, 'zhTW', '淨化！', '', 28153),
(143876, 'zhTW', '完成了。', '', 28153),
(143875, 'zhTW', '血！血！血！', '', 28153),
(143874, 'zhTW', '祖達薩會滅亡！', '', 28153),
(143873, 'zhTW', '新鮮的肉！', '', 28153),
(143872, 'zhTW', '喝你的血！', '', 28153),
(143871, 'zhTW', '我要啃你的骨頭！', '', 28153),
(143870, 'zhTW', '鮮血獻給古翰！', '', 28153),
(143869, 'zhTW', '你躲不過血神的！', '', 28153),
(143868, 'zhTW', 'Guzincha!', '', 28153),
(143867, 'zhTW', 'Kachago!', '', 28153),
(143865, 'zhTW', '你沒有讀附加條款嗎，小子？\n\n不退費，沒有例外，不准抱怨。\n\n我知道什麼能讓你打起精神…羽足的快樂飄落！', '', 28153),
(143864, 'zhTW', '來一個羽毛腳歡樂墜！', '來一個羽毛腳歡樂墜！', 28153),
(143863, 'zhTW', '我想要退貨。', '我想要退貨。', 28153),
(143862, 'zhTW', '歡迎回來，$p！\n\n你肯定很享受在羽足的快樂飄落家族的時光。\n\n身為正式會員，你可以從這塔台好玩的頂端緩慢飄降，次數不限。要再玩一次只要跟我說就好！\n\n絕對不提供退費。', '', 28153),
(143861, 'zhTW', '今天就加入羽足的快樂飄落家族！\n\n只要繳交一次性的小額手續費，你就可以從這塔台頂端緩慢飄降，次數不限。我們保證不會讓你死！\n\n不提供退費。', '', 28153),
(143860, 'zhTW', '這上頭的風比高嶺以前的還強，我們加入部落的決定已經值得了。', '', 28153),
(143859, 'zhTW', '回歸風暴獲得安息。穿過祭壇和我們分享你的力量。', '', 28153),
(143858, 'zhTW', '', '真是座美好的城市，探索世界真是太好玩了！', 28153),
(143857, 'zhTW', '聽我呼喚，亡者。今天會赦免你的邪惡罪行。', '', 28153),
(143856, 'zhTW', '你準備好以後，就釋放鐘裡面的靈魂吧。', '', 28153),
(143855, 'zhTW', '羅莎琳，抱歉，要請你再等等。我們今天有比狩獵更緊急的事要處理。', '', 28153),
(143854, 'zhTW', '', '喂！瑟羅德！別再拖拖拉拉了。我們還在等你祝福才能出海狩獵！', 28153),
(143853, 'zhTW', '請再次光臨，$p！', '', 28153),
(143852, 'zhTW', '對你看到的鮮血食人妖吐口水，得十分！', '', 28153),
(143851, 'zhTW', '羽足的快樂飄落家族！請大家告訴大家！', '', 28153),
(143850, 'zhTW', '真高興能再見到你，$p，祝飄落愉快。', '', 28153),
(143849, 'zhTW', '試著降落在那隻雷龍身上！', '', 28153),
(143848, 'zhTW', '試著降落在瀑布中！', '', 28153),
(143847, 'zhTW', '小心翼手龍！', '', 28153),
(143846, 'zhTW', '一路平安，$p。', '', 28153),
(143845, 'zhTW', '啊啊啊啊啊！', '', 28153),
(143844, 'zhTW', '為了聯盟。', '', 28153),
(143843, 'zhTW', '為了部落！', '', 28153),
(143842, 'zhTW', '激流堡已經毀了。投降吧，羅傑斯，我們還能饒你一命。', '', 28153),
(143841, 'zhTW', '太好了，我的錘子… 就在那裡！', '', 28153),
(143840, 'zhTW', '哈囉，小銅鬚，有人在家嗎？', '', 28153),
(143839, 'zhTW', '聖光依然與我同在，我不會這麼輕易倒下的！', '', 28153),
(143838, 'zhTW', '羅傑斯上將！我們已經摧毀你的堡壘了。你說的懲罰在哪裡啊，聖騎士？', '', 28153),
(143837, 'zhTW', '他們認為幾個騎著馬的士兵就能阻擋我們？哈！讓他們瞧瞧部落的厲害！', '', 28153),
(143836, 'zhTW', '城塞需要支援。在那些坦克還沒靠近之前，先解決掉它們！', '', 28153),
(143835, 'zhTW', '我們的防禦還是很薄弱。部落的士兵！回到基地做好防禦準備！', '', 28153),
(143834, 'zhTW', '好吧，你想打仗，我就放陪到底。派出騎兵隊解決他們！', '', 28153),
(143833, 'zhTW', '部落現在控制了元素之環。', '', 28153),
(143832, 'zhTW', '紐沃農莊是我們的…有了農莊，就有狼騎兵。', '', 28153),
(143831, 'zhTW', '軍械庫準備好了，老兄。', '', 28153),
(143830, 'zhTW', '工坊完成了。石毀車可以輕鬆轟破聯盟的城牆！', '', 28153),
(143829, 'zhTW', '攻城機具，摧毀他們！', '', 28153),
(143828, 'zhTW', '我警告過你了，部落人渣，現在準備被殲滅吧。', '', 28153),
(143827, 'zhTW', '早在聯盟知道這地方以前，這裡就已經是食人妖的地盤了，圖拉揚。', '', 28153),
(143826, 'zhTW', '嗯。你穿起來剛剛好。', '', 28153),
(143825, 'zhTW', '這些衣服現在應該夠穿了。', '', 28153),
(143824, 'zhTW', '最重要的事，就是我們需要木頭和鋼鐵來建造部落的基地。這附近應該有很多。', '', 28153),
(143823, 'zhTW', '我也等不及了，穆拉丁。', '', 28153),
(143822, 'zhTW', '或許換上這些衣服會對採集有幫助。', '', 28153),
(143821, 'zhTW', '呸！圖拉揚，你的制裁留著嚇小孩吧！', '', 28153),
(143820, 'zhTW', '這裡是聯盟的土地！部落的入侵者很快就會受到制裁！', '', 28153),
(143819, 'zhTW', '今天，這裡會屬於部落！', '', 28153),
(143818, 'zhTW', '很久很久以前，這片土地全都屬於食人妖。', '', 28153),
(143817, 'zhTW', '啊…小夥子，我很樂意。你惹錯矮人了。', '', 28153),
(143816, 'zhTW', '穆拉丁！快出來，你這個懦夫！', '', 28153),
(143815, 'zhTW', '我們的防禦還不夠強。阻止那些坦克，別讓我們的基地受到攻擊！', '', 28153),
(143814, 'zhTW', '才不像你那麼醜，銅鬚！', '', 28153),
(143813, 'zhTW', '請原諒我，考官。', '', 28153),
(143812, 'zhTW', '我很榮幸能幫上忙，考官。', '', 28153),
(143811, 'zhTW', '', '戰鬥結束了…我們撐下來了。艾提娜會為了她的瘋狂行徑付出代價！', 28153),
(143810, 'zhTW', '', '看看祖達薩的毀滅者！有種就來阻止吧…我會好好折磨你們！', 28153),
(143809, 'zhTW', '', '跑這麼遠，就是為了到主人面前送死！', 28153),
(143808, 'zhTW', '為聖閘會工作根本是吃力不討好…', '', 28153),
(143807, 'zhTW', '嘿，太簡單了！到外面去試試身手。我們隨時用得上木頭。', '', 28153),
(143806, 'zhTW', '是的，考官。', '', 28153),
(143805, 'zhTW', '考官，我隨時都準備好了。', '', 28153),
(143804, 'zhTW', '我很高興能幫上忙，考官。', '', 28153),
(143803, 'zhTW', '', '你的軀體正好拿來給主人用！', 28153),
(143802, 'zhTW', '', '下一個就是部落了。竟敢殺死希爾雷克！你們一個都別想逃。', 28153),
(143801, 'zhTW', '', '祖達薩會滅亡…我的主人會重獲自由！你們那些弱小的羅亞擋不住他的！', 28153),
(143800, 'zhTW', '是的，考官。', '', 28153),
(143799, 'zhTW', '馬上到，考官。', '', 28153),
(143798, 'zhTW', '', '有趣…貝羅斯，你來看一下，然後告訴你看到什麼。', 28153),
(143797, 'zhTW', '', '你逃去了哪裡，貝羅斯？我有更有價值的解析，需要你寫下來。', 28153),
(143796, 'zhTW', '', '我親愛的貝羅斯，來看看這個。', 28153),
(143795, 'zhTW', '', '聖匣組織裡沒有時間休息，貝羅斯。', 28153),
(143794, 'zhTW', '', '貝羅斯，別碰神器！', 28153),
(143793, 'zhTW', '', '真是神奇…貝羅斯，來看看這有多麼神奇！', 28153),
(143792, 'zhTW', '', '赫茲羅張開護盾了！快進去！', 28153),
(143791, 'zhTW', '', '貝羅斯，你又在做夢了嗎？我這裡會需要你的協助。', 28153),
(143790, 'zhTW', '', '貝羅斯，幫個忙，把我所有的話都記下來。', 28153),
(143789, 'zhTW', '翼艇需要很多補給品來維持良好營運！追蹤跟補充庫存是我的工作，修理壞掉的機具和裝置也是！$b$b…$b$b他們每天都會把大量各種機具和裝置給用壞。$b$b他們不是溫柔的人。', '', 28153),
(143788, 'zhTW', '', '勇士，我能跟你說句話嗎？我需要你的幫助。', 28153),
(143787, 'zhTW', '<<我與工人前往設置大砲的堤道時，發生了一件事。>>', '', 28153),
(143786, 'zhTW', '特別害怕拖鞋。特害怕拖鞋。特別怕拖鞋。特害怕拖。特別怕拖。特怕怕拖拖。特怕怕拖。特怕拖拖。特怕拖。特帕托！', '', 28153),
(143785, 'zhTW', '我的惡作劇好像讓他們都上當了耶！想不到他們以為我會笨到…等等，這是說他們聽得到我的聲音？我…呃，特帕托！', '', 28153),
(143784, 'zhTW', '特帕托不喜歡的有：蛇、欺負人的小孩、蛇、黑黑的洞穴、蛇…還有一直煩特帕托的小傢伙。', '', 28153),
(143783, 'zhTW', '特帕托當然有讀過書，字很大、圖畫很多的書…那些也是書啊。', '', 28153),
(143782, 'zhTW', '小傢伙不會想要欺負善良的特帕托…對吧？', '', 28153),
(143781, 'zhTW', '特帕托還是有一點點怕蛇。', '', 28153),
(143780, 'zhTW', '特帕托很榮幸能成為光鑄戰士！', '', 28153),
(143779, 'zhTW', '隨時回來找特帕托喔。', '', 28153),
(143778, 'zhTW', '特帕托要回去工作囉。', '', 28153),
(143777, 'zhTW', '特帕托有很多事要做。', '', 28153),
(143776, 'zhTW', '特帕托很快會再跟你見面的。', '', 28153),
(143775, 'zhTW', '特帕托。', '', 28153),
(143774, 'zhTW', '動作快，$n。這是攸關性命的事情。', '', 28153),
(143773, 'zhTW', '特帕托準備好了！', '', 28153),
(143772, 'zhTW', '聖光與你同在，朋友。', '', 28153),
(143771, 'zhTW', '危險？特帕托才不怕什麼危險！', '', 28153),
(143770, 'zhTW', '小傢伙需要特帕托幫什麼忙嗎？', '', 28153),
(143769, 'zhTW', '特帕托向小傢伙打招呼。', '', 28153),
(143768, 'zhTW', '特帕托？', '', 28153),
(143767, 'zhTW', '特帕托！', '', 28153),
(143766, 'zhTW', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s開始施放|cFFFF0000|Hspell:259610|h[血腥天啟]|h|r！尋找掩護！', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s開始施放|cFFFF0000|Hspell:259610|h[血腥天啟]|h|r！尋找掩護！', 28153),
(143765, 'zhTW', '', '掙扎吧！戰鬥吧！你們的痛苦讓主人更強大！', 28153),
(143764, 'zhTW', '珍娜？我看是「真假」。莫德菈？應該是…呃…哼，我總不可能每個名字都想出諧音吧？', '', 28153),
(143763, 'zhTW', '卡德加？我看是老人家。對不對啊？', '', 28153),
(143762, 'zhTW', '祈倫托？聽起來像騎駱駝。有沒有？', '', 28153),
(143761, 'zhTW', '要是你們能完全照我的話去做，不要用自己的腦袋思考，或許艾澤拉斯會比現在美好。', '', 28153),
(143760, 'zhTW', '跟我們作對一點也不明智。', '', 28153),
(143759, 'zhTW', '為了奎爾薩拉斯！', '', 28153),
(143758, 'zhTW', '我們經歷了很多事。', '', 28153),
(143757, 'zhTW', '我們的未來必須建立在傳統之上。', '', 28153),
(143756, 'zhTW', '快去工作吧。', '', 28153),
(143755, 'zhTW', '別讓外來者干預。', '', 28153),
(143754, 'zhTW', '尊重我們的傳統。', '', 28153),
(143753, 'zhTW', '永恆的太陽之光依然指引著我們。', '', 28153),
(143752, 'zhTW', '你找我有什麼事？', '', 28153),
(143751, 'zhTW', '我向銀月城效忠。', '', 28153),
(143750, 'zhTW', '我現在有點忙。', '', 28153),
(143749, 'zhTW', '不要浪費任何資源。', '', 28153),
(143748, 'zhTW', '什麼事？', '', 28153),
(143747, 'zhTW', '一定要好好守護太陽之井。', '', 28153),
(143746, 'zhTW', '把這個拿去吧，以表達我的感謝之意。', '', 28153),
(143745, 'zhTW', '', '計畫？你是說我嗎？我哪可能會有什麼計畫？', 28153),
(143744, 'zhTW', '', '我早就發現你用色瞇瞇的眼神在看我手下的遊俠了，建議你最好收斂一點。', 28153),
(143743, 'zhTW', '', '我一直在注意你的表現，看來你應該去找納薩諾斯接受加強輔導。', 28153),
(143742, 'zhTW', '', '風行者三姊妹裡你最喜歡的是我…對吧？', 28153),
(143741, 'zhTW', '', '艾澤拉斯的生命之源是屬於部落的。', 28153),
(143740, 'zhTW', '我開始懷疑到底有沒有這樣的生物存在！', '', 28153),
(143739, 'zhTW', '', '絕對要得到屬於我們的一切。', 28153),
(143738, 'zhTW', '', '所有人遲早都會向部落效忠。', 28153),
(143737, 'zhTW', '', '無論如何，我都會讓被遺忘者的勢力更加壯大。', 28153),
(143736, 'zhTW', '', '我們會讓聯盟跪地求饒。', 28153),
(143735, 'zhTW', '', '向部落效忠。對我效忠。', 28153),
(143734, 'zhTW', '他真美啊！', '', 28153),
(143733, 'zhTW', '', '去吧。我還有很多事要做。', 28153),
(143732, 'zhTW', '', '對我忠心耿耿，就會得到獎賞。', 28153),
(143731, 'zhTW', '', '嶄新的未來在等待著部落。', 28153),
(143730, 'zhTW', '', '真正的工作才剛要開始。', 28153),
(143729, 'zhTW', '', '你好啊，勇士。', 28153),
(143728, 'zhTW', '', '到前面來。', 28153),
(143727, 'zhTW', '', '我相信你不會浪費我的時間。', 28153),
(143726, 'zhTW', '', '向你的大酋長說明來意。', 28153),
(143725, 'zhTW', '', '贊達拉的元素經歷了許多苦難。我們必須阻止濫用它們的力量滿足私欲的黑暗薩滿。', 28153),
(143724, 'zhTW', '我叫柏索德，我對馬匹有點狂熱。\n\n有傳言說，此處西方的山嶺上，有一隻雄偉的馬型生物。我在這裡工作，是希望能在閒暇時看到牠。\n\n喔，要是能看見那樣的生物，我什麼都願意付出…', '', 28153),
(143721, 'zhTW', '了解。泰坦守衛者赫茲羅在此地的工作，無須其他協助。即將前往祖爾納茲曼地區。', '', 28153),
(143720, 'zhTW', '', '赫茲羅，鮮血食人妖集中在祖爾納茲曼。你想幫我們的話，就必須到那裡去。', 28153),
(143719, 'zhTW', '請我喝酒吧，$pr。\n\n在你的同類像懦夫一樣跑去躲在霧中時，我的同類拯救了世界。\n\n你欠我一杯酒。', '', 28153),
(143718, 'zhTW', '泰坦守護者赫茲羅，以百分之五十的能量運作。必須保留能量，以淨化鮮血食人妖。', '', 28153),
(143717, 'zhTW', '這以前是我的調酒室，皇室在此娛樂世界各地的貴族，而我用我做的飲品滿足他們。\n\n現在，它是個充滿骯髒外來者和他們醜陋朋友的窩，真是個恥辱。', '', 28153),
(143716, 'zhTW', '我尊重一部分的哥布林企業。中立又強大，做事不計代價。就像贊達拉人…當然，更糟糕就是了。\n\n但你們污水是個恥辱。和部落與精靈為伍。根本就是自甘下賤。', '', 28153),
(143715, 'zhTW', '感受我的力量！', '', 28153),
(143714, 'zhTW', '我喜歡你們部落運作的方式，$p。有強大的首領、為達成目的而團結，而且有穩定的補給線。\n\n你在徵人嗎？', '', 28153),
(143713, 'zhTW', '我準備好尋求下一個盟友了。', '我準備好尋求下一個盟友了。', 28153),
(143712, 'zhTW', '', '終於，部落和聯盟之間可以不用再假惺惺了。$b$b大戰就要開打了。', 28153),
(143711, 'zhTW', '你們暗矛族和部落聯合依然讓我感到驚訝。我猜，是獨木總是難撐大樑。\n\n沃金怎麼樣？', '', 28153),
(143710, 'zhTW', '聽著，精靈，經營這酒吧的已經不是我，所以我不用假裝我喜歡你。\n\n離開我的視線，骯髒的精靈。', '', 28153),
(143709, 'zhTW', '你看起來很渴，喝點東西吧，留下來聊聊天。\n\n祖達薩從遠古時代就存在了，它不會一夜之間消失的。', '', 28153),
(143708, 'zhTW', '我聽到你們幾個要去納茲米爾。能的話，你們應該要推掉這任務。多少世代以來那沼澤都沒發生過好事。', '', 28153),
(143707, 'zhTW', '我聽說沃魯敦那片沙漠最近會有比平常更多的麻煩。如果你要去那，最好小心點。', '', 28153),
(143706, 'zhTW', '我的同類在上古時代開創了文明，從那之後就背負著你們走到今天。\n\n告訴我，$pr，你的同類做過什麼值得紀念的事？\n\n我什麼都想不出來。', '', 28153),
(143705, 'zhTW', '(跳上赫茲羅的肩膀，返回幽暗谷)', '(跳上赫茲羅的肩膀，返回幽暗谷)', 28153),
(143704, 'zhTW', '古翰的圍堵修復失敗了。我們必須阻止鮮血食人妖的部隊破壞祖達薩，不然古翰真的被召出來就糟了。\n\n鮮血食人妖包圍了建築。泰坦守衛者赫茲羅將確保$n和塔蘭姬公主的安全。\n\n跳上肩膀，記得把頭放低。', '', 28153),
(143703, 'zhTW', '骯髒、噁心，你比鮮血食人妖還難聞。\n\n如果這酒吧還是我的，我會把你和垃圾一起掃出去。', '', 28153),
(143702, 'zhTW', '你在城外聽到什麼消息？', '', 28153),
(143700, 'zhTW', '加里維克斯已經在希利蘇斯展開行動。立刻去那裡。如果看到鬼鬼祟祟的聯盟成員，格殺勿論。', '', 28153),
(143699, 'zhTW', '我們在希利蘇斯建立了臨時基地。到那裡跟我們的特務會合，記得，隨時注意部落的動靜。', '', 28153),
(143698, 'zhTW', '你們獸人可真能喝，這點我得承認。\n\n叫你那些高傲的精靈朋友離這遠點就是了，好嗎？', '', 28153),
(143697, 'zhTW', '艾蘭里亞和圖拉揚嗎？行不通的。呃…我不是不贊成他們在一起，可是…呃，我們換個話題可以嗎？', '', 28153),
(143696, 'zhTW', '我能理解你為什麼不喜歡精靈。畢竟，我們有一半的精靈也滿討厭另外一半的。', '', 28153),
(143695, 'zhTW', '我承認自己不是很喜歡紫色，但我身上的這個顏色好像擦也擦不掉了。', '', 28153),
(143694, 'zhTW', '高等精靈？拜託，高等精靈有什麼好，看起來悲慘又憂鬱才受歡迎。', '', 28153),
(143693, 'zhTW', '保持專注，永遠克制。', '', 28153),
(143692, 'zhTW', '不要向低語屈服。', '', 28153),
(143691, 'zhTW', '不要拒絕各種可能。', '', 28153),
(143690, 'zhTW', '暗影守護著你。', '', 28153),
(143689, 'zhTW', '我們向聯盟效忠。', '', 28153),
(143688, 'zhTW', '追隨聖光不是唯一的選擇。', '', 28153),
(143687, 'zhTW', '我們刃多雷會證明自己的價值。', '', 28153),
(143686, 'zhTW', '我有很多東西可以教你。', '', 28153),
(143685, 'zhTW', '排除心中的成見。', '', 28153),
(143684, 'zhTW', '所有道路都有無限可能。', '', 28153),
(143683, 'zhTW', '我們不害怕力量，我們樂於接受力量。', '', 28153),
(143682, 'zhTW', '暗影由我們掌控。', '', 28153),
(143681, 'zhTW', 'Bal\'a dash, malanore. (你好啊，旅行者。)', '', 28153),
(143680, 'zhTW', '你好，旅人。', '', 28153),
(143679, 'zhTW', '我的眼罩沒有換過位置啊！誰會搞錯這種事啊？哎呀真是的！', '', 28153),
(143678, 'zhTW', '在希瓦娜斯底下做事…不怎麼輕鬆。變成不死族讓她更是專橫又跋扈，但是…欸，別告訴她這是我說的。', '', 28153),
(143677, 'zhTW', '就算我不是女王的勇士，我的箭術還是能輕鬆贏過納薩諾斯。', '', 28153),
(143676, 'zhTW', '我這美麗的秀髮可不是天生的，是精心打理出來的。', '', 28153),
(143675, 'zhTW', '銀月城再也不會由國王來統治。', '', 28153),
(143674, 'zhTW', '我們的王國日益興盛。', '', 28153),
(143673, 'zhTW', 'Al diel shala. (旅途平安。)', '', 28153),
(143672, 'zhTW', '部落有我們需要的力量。', '', 28153),
(143671, 'zhTW', '我做的一切，都是為了奎爾薩拉斯。', '', 28153),
(143670, 'zhTW', '願太陽之井的光芒與你同在。', '', 28153),
(143669, 'zhTW', '銀月城會再度繁榮昌盛。', '', 28153),
(143668, 'zhTW', '永歌森林的美永恆不朽。', '', 28153),
(143667, 'zhTW', '永恆的太陽之光依然指引著我們。', '', 28153),
(143666, 'zhTW', '重建的工作還要繼續下去。', '', 28153),
(143665, 'zhTW', '我們曾經做出許多犧牲。', '', 28153),
(143664, 'zhTW', '我是銀月城的攝政王。', '', 28153),
(143663, 'zhTW', 'Bal\'a dash, malanore. (你好啊，旅行者。)', '', 28153),
(143662, 'zhTW', '我代表銀月城歡迎你。', '', 28153),
(143651, 'zhTW', '喔，我好像釣到大尾的了！', '', 28153),
(143650, 'zhTW', 'PLACEHOLDER SCENE - Hezrel reveals G\'huun being an old god, being experimented upon, and reveals blood trolls want to destroy Zuldazar in order to free G\'huun. No way of fixing current containment, must protect Zuldazar. Ateena, blood troll matriarch, arrives, badly damages Hezrel, and prepares to strike.', 'PLACEHOLDER SCENE - Hezrel talks about G\'huun being an old god, being experimented upon, and reveals blood trolls want to destroy Zuldazar in order to free G\'huun. No way of fixing current containment, must protect Zuldazar. Ateena, blood troll matriarch, arrives, badly damages Hezrel, and prepares to strike', 28153),
(143649, 'zhTW', '', '回來，$r！他的聲音是我的！', 28153),
(143648, 'zhTW', '', '這裡有…很強…力量…', 28153),
(143647, 'zhTW', '', '小心點，奧姆里克，解開這種奧秘通常要冒很大的風險。', 28153),
(143646, 'zhTW', '比如說這個立方體。這是非常古老的裝置，可能在艾澤拉斯出現生命之前就已經存在。它好像鎖住了，我們打不開。', '', 28153),
(143645, 'zhTW', '沒錯！我們跟你一樣，認為虛無的力量不是只能吞噬生命，而是可以保護生命。風行者女士，我們已經有不少發現，只是還沒揭開所有的秘密。', '', 28153),
(143644, 'zhTW', '', '這或許可以改天再聊。我跟這位勇士一直在找你，聽說你被銀月城流放，這點我們倒是很像。', 28153),
(143643, 'zhTW', '我跟族人都聽說了在阿古斯發生的事。你應該也知道，我們對你和黑暗那魯之間的互動非常好奇。', '', 28153),
(143642, 'zhTW', '艾蘭里亞‧風行者！？怎麼會…哎呀，真是天大的榮幸啊！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143641, 'zhTW', '', '博學者奧姆里克！我是艾蘭里亞‧風行者。', 28153),
(143640, 'zhTW', '', '看，在前面。那一定是奧姆里克。', 28153),
(143639, 'zhTW', '', '根據筆記，我應該可以打開前往這個世界的通道。我來試試看…', 28153),
(143638, 'zhTW', '', '<躍下落地>', 28153),
(143637, 'zhTW', '崔希爾認為可以在這個地方找到力量無比強大的遠古物品。或許這個東西就是能讓我們控制暗影的關鍵。', '', 28153),
(143636, 'zhTW', '他的筆記寫著，這個地方就在現實世界的某個裂隙裡。他沒有找到…但是我找到了。前往這個世界的通道很快就會開啟！', '', 28153),
(143635, 'zhTW', '崔希爾為了獲得強大的力量而追求某個遠古世界的碎片，一個位處虛無邊緣的遙遠世界。', '', 28153),
(143634, 'zhTW', '<躍下落地>', '', 28153),
(143633, 'zhTW', '', '來吧，我們必須前往晨星尖塔。', 28153),
(143632, 'zhTW', '不過，我相信這些知識可以用在正途上。崔希爾通常都在晨星尖塔進行研究，那裡正是我們要去的地方。', '', 28153),
(143631, 'zhTW', '當初就因為是崔希爾的背叛，阿薩斯才有機會腐化太陽之井…這個王國也才會毀滅。所以我總算明白為什麼洛摩斯會反對我們做這些研究。', '', 28153),
(143630, 'zhTW', '看來我們並不是族人裡最早想要控制虛無之力的。我找到一些筆記，筆記的主人就是達克汗‧崔希爾這個可惡的叛徒。', '', 28153),
(143629, 'zhTW', '<躍下落地>', '', 28153),
(143628, 'zhTW', '', '看來我們發現了一些筆記。', 28153),
(143627, 'zhTW', '', '<躍下落地>', 28153),
(143626, 'zhTW', '只可惜，我們的研究遇到了瓶頸。我認為藏在安狄里安莊園裡的資料，能幫助我們打破目前的僵局。', '', 28153),
(143625, 'zhTW', '大博學者必須要知道，這股力量是保衛銀月城的關鍵。辛多雷絕對不會再受到敵人的威脅！', '', 28153),
(143624, 'zhTW', '我們對虛無的研究非常順利。雖然目光短淺的洛摩斯不斷反對，但我相信很快就會有突破性的發現了。', '', 28153),
(143623, 'zhTW', '<躍下落地>', '', 28153),
(143622, 'zhTW', '', '<躍下落地>', 28153),
(143621, 'zhTW', '<痛哭>', '', 28153),
(143620, 'zhTW', '<躍下落地>', '', 28153),
(143619, 'zhTW', '赫茲羅，開始掃描，找出要如何化解上古之神在納茲米爾造成的腐化。', '赫茲羅，開始掃描，找出要如何化解上古之神在納茲米爾造成的腐化。', 28153),
(143618, 'zhTW', '來看看這些魚是不是準備好要吃餌了！', '', 28153),
(143617, 'zhTW', '', '<躍下落地>', 28153),
(143616, 'zhTW', '', '這座森林曾經帶給我和妹妹很多美好的回憶。現在看到這個景象…讓我覺得好難過。', 28153),
(143615, 'zhTW', '我們要一起證明，他們錯了。', '', 28153),
(143614, 'zhTW', '我們會慢慢適應這個新的形態。風行者女士，我們等你回來。這位勇士…真的非常感謝你。', '', 28153),
(143613, 'zhTW', '', '而我會在旅途中協助你。我和勇士要先去向烏瑞恩國王報告這件事，等我回來，我們就可以開始訓練了。', 28153),
(143612, 'zhTW', '很久以前，銀月城背棄了我們。但今天，我們重生了…也該走出新的道路。從現在開始，我們向聯盟效忠。', '', 28153),
(143611, 'zhTW', '', '我感覺到了。你們身上的力量…很強大。要是你們能加入聯盟，一定會是得力的盟友。', 28153),
(143610, 'zhTW', '因為我的傲慢，我們差點滅族。我不該妄想自己無法控制的強大力量。艾蘭里亞，如果你願意訓練我們，我們一定會跟隨你的。', '', 28153),
(143609, 'zhTW', '', '我已經下令在奧格瑪建造大使館，我們要在那裡招募盟友。立刻去那裡跟我會合。', 28153),
(143608, 'zhTW', '', '部落當初無私地對抗燃燒軍團，還因此元氣大傷。敵人現在卻想趁機奪走屬於我們的東西。絕對不能讓他們稱心如意。', 28153),
(143607, 'zhTW', '', '勇士，你曾經看過我們在希利蘇斯的行動。很顯然地，聯盟千方百計地想要阻礙我們。', 28153),
(143606, 'zhTW', '聯盟需要結交新的盟友。因此，我們還在暴風城建立了大使館。到那裡去跟我會合吧。', '', 28153),
(143605, 'zhTW', '部落會不擇手段搶奪艾澤拉斯的生命之源。我擔心擊敗燃燒軍團之後，我們的兵力不足以阻止他們。', '', 28153),
(143604, 'zhTW', '勇士，你親眼看過希利蘇斯遭遇的災難。你了解事情的嚴重性。', '', 28153),
(143603, 'zhTW', '到葛羅瑪許堡外面跟我會合。別走漏消息…否則很快就會有嚴重的後果。', '', 28153),
(143602, 'zhTW', '我們最近得知與部落利益有關的重大情報。無論如何絕對要處處搶先對手一步才行。', '', 28153),
(143601, 'zhTW', '勇士！黑暗女王要你到奧格瑪跟我會合。', '', 28153),
(143600, 'zhTW', '到雄獅陵園找我。應該不用我多說，這次會面的事別告訴任何人。', '', 28153),
(143599, 'zhTW', '我們發現了一些…敏感的資訊，他堅持一定要讓你知道。', '', 28153),
(143598, 'zhTW', '勇士，烏瑞恩國王希望你前往暴風城跟我會合。', '', 28153),
(143597, 'zhTW', '我還帶了這個外人來。他想跟你談談，偉大的羅亞。', '', 28153),
(143596, 'zhTW', '', '夜裔是很有智慧又強大的一族。你們擁有的古老知識可以幫助我們達成目標。', 28153),
(143595, 'zhTW', '', '客套話我就說到這裡。英雄，你還需要證明自己。不管你走到哪裡，都要記住…你是為部落而戰！', 28153),
(143594, 'zhTW', '', '放心吧，我會留意你的進展。身為大酋長，我對你有很深的期待…勞苦功高的人我絕對不會虧待。', 28153),
(143593, 'zhTW', '', '部落在這世界上有不少敵人。有的跟我們勢不兩立…有的不肯接納我們。但我們只要團結，力量就會強大…誰都別想剝奪我們的自由。', 28153),
(143592, 'zhTW', '', '高嶺牛頭人兼具力量與勇氣。接下來的日子裡，我們會需要借助他們的能力。', 28153),
(143591, 'zhTW', '', '啊，年輕的英雄大駕光臨啊。我聽說你潛力無窮，希望你會證明這一點。', 28153),
(143590, 'zhTW', '一路平安。願聖光永遠與你同在。', '', 28153),
(143589, 'zhTW', '雖然虛無精靈才剛加入聯盟，但艾蘭里亞‧風行者是偉大的英雄，有了她的指導，你的力量一定能成為我們的助力。', '', 28153),
(143588, 'zhTW', '我要把你趕出這裡！', '', 28153),
(143587, 'zhTW', '一路平安。你雖然與暗影同行，對我們來說卻是希望的明燈。', '', 28153),
(143586, 'zhTW', '我很期待你的戰果。我相信我們很快就會再碰面的。', '', 28153),
(143585, 'zhTW', '艾澤拉斯現在正是動亂的時刻。接下來，你會面臨很多考驗，遇到很多敵人…記住，你絕對不會獨自對抗黑暗，聯盟會與你同在。', '', 28153),
(143584, 'zhTW', '雖然光鑄戰士才剛加入聯盟，但是我很了解德萊尼，我相信你一定會展現出聖光軍團的奉獻精神和無比勇氣。', '', 28153),
(143583, 'zhTW', '歡迎你，朋友。我是安杜因·烏瑞恩國王，我想親自歡迎你加入聯盟，成為我們的一分子。', '', 28153),
(143582, 'zhTW', '我需要治療！', '', 28153),
(143581, 'zhTW', '別想搶我的伐木場！', '', 28153),
(143580, 'zhTW', '部落居然帶我們來到這個既有趣又偏僻的世界的一角。\n\n我相信，新陣營的絕大多數建築會比這個更高雅乾淨吧？', '', 28153),
(143579, 'zhTW', '原諒我，$p。\n\n我很想跟你聊天，但我想我要嘔吐了。\n\n別試這裡的紅酒。', '', 28153),
(143578, 'zhTW', '<葡萄酒商的瑟斯納拉盯著酒保，一邊緩緩地把他的紅酒往旁邊的地上倒。>', '', 28153),
(143577, 'zhTW', '你嚐過這裡的紅酒了嗎？\n\n你必須試試，味道恐怖到讓人不敢相信。\n\n吟遊詩人或許會寫歌傳唱這難喝到成為傳奇的口感。\n\n真是一種成就，廚餘一般、浪費酒精、絕對搞砸派對的產品。', '', 28153),
(143576, 'zhTW', '到目前為止，我相信贊達拉人能夠建造出令人不快的大型建築。\n\n我不相信他們能釀酒。', '', 28153),
(143575, 'zhTW', '如果你釀不出好酒，你根本就不該釀酒。', '', 28153),
(143574, 'zhTW', '買第二杯這種紅酒給我吧，好讓我再次把這髒水吐到地上。', '', 28153),
(143573, 'zhTW', '他們說這餿水是紅酒？難怪食人妖要棄守這座城市。', '', 28153),
(143572, 'zhTW', '我們終於自由了！快，趕快離開這裡！', '我們終於自由了！快，趕快離開這裡！', 28153),
(143571, 'zhTW', '這些木頭怪物簡直是惡夢中走出來的東西！', '', 28153),
(143569, 'zhTW', '我要申請…危險津貼補助…', '我要申請…危險津貼補助…', 28153),
(143568, 'zhTW', '', '這裡殘破不堪，不過卻有種熟悉的感覺…', 28153),
(143567, 'zhTW', '用力點好不好，你們這群小懶蟲！', '用力點好不好，你們這群小懶蟲！', 28153),
(143566, 'zhTW', '建築內部檢查完畢。指派中，塔蘭姬公主，已加入。', '', 28153),
(143565, 'zhTW', '命令下達。全部前往寇連恩！', '', 28153),
(143562, 'zhTW', '太遲了。古翰無法被阻止。一切皆將崩壞。生靈皆將毀滅。', '', 28153),
(143561, 'zhTW', '你已經完了。古翰將獲得自由，艾澤拉斯會是我們的。', '', 28153),
(143560, 'zhTW', '$p，把你的貴重物品放在寶庫，然後繼續行動。\n\n我會盯著你的…', '', 28153),
(143559, 'zhTW', '佐司瓦現在正面臨危難，但我們一定會把這片土地奪回來！', '', 28153),
(143558, 'zhTW', '為了贊達拉！', '', 28153),
(143557, 'zhTW', '瑞贊，我們來打獵吧。', '', 28153),
(143556, 'zhTW', '是。我們聽內陸人的命令行動。', '', 28153),
(143555, 'zhTW', '萬風羅亞帕骷，從空中搜查那些異端份子。找出他們的目的，然後到神廟和我們碰面。', '', 28153),
(143554, 'zhTW', '剛克，狩獵的羅亞，帶你的追隨者到先知神廟去，看到敵人就殺光。把敵人全都逼出來吧。', '', 28153),
(143553, 'zhTW', '贊達拉的兄弟姐妹們，終於是時候了。我們要把所有向祖爾效忠的叛徒，頭顱全部都砍下來。', '', 28153),
(143552, 'zhTW', '', '剩下的其他人要準備去寇連恩一趟。元帥，我相信你有進攻的計畫了？', 28153),
(143551, 'zhTW', '', '遵命，小姐！', 28153),
(143550, 'zhTW', '', '把鍊金火焰的配方交給獵鷹林的艾希頓大師。他知道該怎麼做。', 28153),
(143549, 'zhTW', '', '幸好，我知道獵鷹林有個鍊金大師，在南邊。樹林很危險，所以你們一定要走古道。', 28153),
(143548, 'zhTW', '', '書上寫了製作鍊金火焰的方法，但是這裡沒有人做得出來。', 28153),
(143547, 'zhTW', '', '想把這些女巫斬草除根，我們需要的不只是白銀，還需要火。', 28153),
(143546, 'zhTW', '', '謝謝長官！小姐，請問你有何吩咐？', 28153),
(143545, 'zhTW', '科利爾東上尉 - 我是說審判官，一直以來都很認真負責。我相信她什麼任務都能完成。', '', 28153),
(143544, 'zhTW', '', '你有人選嗎，元帥？', 28153),
(143543, 'zhTW', '', '在我們出發之前，我需要有人執行燼火會的特別任務。', 28153),
(143542, 'zhTW', '你能相信部落從來沒有官方的傳送局嗎？我是說，我不知道部落人民旅行時怎麼會有安全保障，一想到這麼多莫名、沒有精確定位的傳送門在現實界開了那麼多洞…\n\n不管怎樣，我很願意為部落提供一個穩定的瞬間移動網路。你請離開吧。', '', 28153),
(143540, 'zhTW', '雖然鎮民都很堅強，但是這次真的是個考驗。', '', 28153),
(143539, 'zhTW', '', '孩子們，溺死這些蟲子，證明你們值得我驕傲。', 28153),
(143537, 'zhTW', '巴格！巴格拉格！', '', 28153),
(143536, 'zhTW', '莫格，莫格格！莫格！莫格！', '', 28153),
(143531, 'zhTW', '撬開中', '撬開中', 28153),
(143530, 'zhTW', '這個就交給你了，小子！上船吧！', '', 28153),
(143529, 'zhTW', '瑞贊之爪出事了。我們在營地附近設置了偵察坐騎。', '', 28153),
(143523, 'zhTW', '交出你的金子，我五分鐘後要開收支會議！', '', 28153),
(143520, 'zhTW', '我準備好了，幫我塗上擬似古翰精華吧。', '我準備好了，幫我塗上擬似古翰精華吧。', 28153),
(143519, 'zhTW', '是達卡王！他找了我們！救命！', '', 28153),
(143518, 'zhTW', '你竟然…輸了？真可悲！去幽暗城報到，接受加強輔導。看來你需要從頭開始訓練。', '', 28153),
(143517, 'zhTW', '雖然贏得不夠漂亮，但至少你讓那些聯盟狗得到一點教訓了。為了部落！', '', 28153),
(143516, 'zhTW', '好臭…是狼人嗎？還是聯盟臭傢伙自以為是的味道？根本分不出來。', '', 28153),
(143515, 'zhTW', '消滅他們！千萬不要讓大酋長失望！', '', 28153),
(143514, 'zhTW', '聯盟就只有這點能耐？真沒用！那傢伙連劍都舉不好！', '', 28153),
(143513, 'zhTW', '射擊！一個活口也不能留！', '', 28153),
(143512, 'zhTW', '該死！又出現艾澤萊晶岩了。趕快利用地圖，找出那些地點！', '', 28153),
(143511, 'zhTW', '島上又有其他地方噴出艾澤萊晶岩了！看著地圖去找吧。', '', 28153),
(143510, 'zhTW', '只差一點了。不要鬆懈，收集艾澤萊晶岩！', '', 28153),
(143509, 'zhTW', '哈！從聯盟手中搶過來了！做得好！', '', 28153),
(143508, 'zhTW', '第一次就能收集到這些已經不錯了，但是還不夠！', '', 28153),
(143507, 'zhTW', '有需要的話，趕快去拿補給品。但千萬別忘了女妖之王要的東西！', '', 28153),
(143506, 'zhTW', '補給品快來了。絕對不能讓聯盟捷足先登！', '', 28153),
(143505, 'zhTW', '下面…有艾澤萊晶岩！為大酋長拿下吧。要是有聯盟的傢伙礙事，就把他們變成屍體。快去！', '', 28153),
(143504, 'zhTW', '過來讓我看看。呃…真弱！為什麼隊伍裡沒有黑暗遊俠呢？算了，硬著頭皮上吧。', '', 28153),
(143503, 'zhTW', '聯盟的船艦開過來了！那些狗東西真是陰魂不散。等什麼！快就戰鬥位置！', '', 28153),
(143502, 'zhTW', '你們的任務很簡單，就是收集所有的艾澤萊晶岩，一點都不能留給聯盟。我相信這應該很好懂才對。', '', 28153),
(143501, 'zhTW', '部落的勇士！我們在菲拉斯沿岸的某座島嶼發現艾澤萊晶岩。你們的職責就是為黑暗女王拿回資源！', '', 28153),
(143500, 'zhTW', '擊退他們！這座島是我們的！', '', 28153),
(143499, 'zhTW', '為國王而戰！為聯盟而戰！', '', 28153),
(143498, 'zhTW', '這群部落豬自以為聰明。給他們一點顏色瞧瞧！', '', 28153),
(143497, 'zhTW', '射擊！殺死他們的治療者！', '', 28153),
(143496, 'zhTW', '你們看起來還滿壯的。嗯…我想再找一、兩個盜賊會更好…但現在這樣也可以啦！', '', 28153),
(143495, 'zhTW', '可惡！這次讓部落占了上風。但我以雄獅陵園發誓，我們一定會獲得最後的勝利！', '', 28153),
(143494, 'zhTW', '勇士，做得太好了！烏瑞恩國王一定很高興我們能獲勝。為了聯盟！', '', 28153),
(143493, 'zhTW', '補給品來了！勇士們，快去拿！', '', 28153),
(143492, 'zhTW', '又有晶岩噴發了！看地圖前往噴發位置，拿回晶岩！', '', 28153),
(143491, 'zhTW', '做得很好。再多收集一些艾澤萊晶岩，我們今天就勝利了！', '', 28153),
(143490, 'zhTW', '你阻止了部落收集艾澤萊晶岩，做得好！', '', 28153),
(143489, 'zhTW', '英雄們，你們做得不錯，但是這些艾澤萊晶岩還不夠！', '', 28153),
(143488, 'zhTW', '英雄們！補給品丟下去給你們了。千萬別讓部落搶走了！', '', 28153),
(143487, 'zhTW', '艾澤萊晶岩又在這座島上噴發了！噴發的位置幫你標示在地圖上。', '', 28153),
(143486, 'zhTW', '各位英雄，底下有豐富的艾澤萊礦藏，趕快下去收集起來。如果部落的傢伙跑過來跟你們搶…那就殺掉他們！', '', 28153),
(143485, 'zhTW', '部落的船艦開過來了！一定是那些混蛋跟蹤我們。快就戰鬥位置！', '', 28153),
(143484, 'zhTW', '船艦已經開到這座島嶼的中心。盡量收集艾澤萊晶岩，越多越好，這是我們勝利的關鍵！', '', 28153),
(143483, 'zhTW', '勇士，我們在菲拉斯沿岸的某座島嶼發現艾澤萊晶岩，一定要在部落下手之前趕快行動。', '', 28153),
(143482, 'zhTW', '', '這是我的榮幸，莉雅德倫女士。歐庫雷斯有你主城的座標，我去找西爾格林和薇兒塔，我們銀月城見。', 28153),
(143481, 'zhTW', '', '你有這樣的打算，攝政王知道了一定很高興。準備好要出發了嗎？', 28153),
(143480, 'zhTW', '', '也因此我非常感謝你邀請我前往銀月城，我想知道部落有沒有夜裔的容身之地。', 28153),
(143479, 'zhTW', '', '聯盟感覺太封閉…太畫地自限。我的族人絕對無法再忍受這種死板的感覺。', 28153),
(143478, 'zhTW', '', '泰蘭妲和那群高傲的傢伙也看不起辛多雷。也不想想我們努力奮戰拯救世界的時候，她們只會躲在樹上或跑進獸穴裡睡大覺。', 28153),
(143477, 'zhTW', '', '看來「伊露恩的智慧」只有指引她跟族人繼續分裂。那就隨她去吧。', 28153),
(143476, 'zhTW', '', '卡多雷會幫忙擊退燃燒軍團並摧毀夜井。除此之外…就看伊露恩的智慧如何帶領我們吧。', 28153),
(143475, 'zhTW', '', '我們不想成為夜井的奴隸。我們想把燃燒軍團從蘇拉瑪爾趕出去，終結艾莉珊德的暴政。', 28153),
(143474, 'zhTW', '', '薩莉瑟拉秘法師，我還記得先祖之戰時，你們站在哪一方。我們要怎麼相信你不會背叛，變成下一個艾莉珊德…或者是艾薩拉？', 28153),
(143473, 'zhTW', '', '我原本以為住在卡林多的族人才是我們的盟友，但他們的傲慢與猜忌讓我非常失望。', 28153),
(143472, 'zhTW', '', '說實話，我剛知道部落的時候，很懷疑我們之間會有任何共同點。', 28153),
(143471, 'zhTW', '', '能跟你一起對抗燃燒軍團是部落的榮幸，女士。', 28153),
(143470, 'zhTW', '', '這一切都要感謝你們兩位，你們絕對功不可沒。', 28153),
(143469, 'zhTW', '', '很高興你的城市重獲自由，首席秘法師。', 28153),
(143468, 'zhTW', '', '莉雅德倫和勇士，你們好。歡迎回到蘇拉瑪爾。很高興這次見面，這裡的情況比上次好多了。', 28153),
(143467, 'zhTW', '', '羅亞並沒有給你祝福，小朋友。這很讓人失望，但其實也是意料中的事。總之，你沒辦法和我們一起踏上天選者臺地。', 28153),
(143466, 'zhTW', '為了來見我，你一定走了很長一段路，年輕人。$b$b我有很多關於螃蟹歷史的故事，你是為此而來嗎？', '', 28153),
(143465, 'zhTW', '', '堅韌而驕傲，你的耐力比任何敵人都要強，能抵擋任何風暴侵襲。我們會需要你的力量來保衛我們的城市。', 28153),
(143464, 'zhTW', '', '這實在…太奇怪了。我們之後會需要你的力量。', 28153),
(143463, 'zhTW', '', '自私又無恥…你走別條路會發展得很好的，小傢伙。', 28153),
(143462, 'zhTW', '', '真是有趣…既隱匿又聰明，你從陰影中出擊。出奇不意便是你最大的武器。', 28153),
(143461, 'zhTW', '', '聽著，你很敏捷又具觀察力，在攻擊中也很小心。你的耐心會得到回報的。', 28153),
(143460, 'zhTW', '', '小朋友，感受自己的靈魂，告訴我…你怎麼對獵物下手：你會善用自己的智慧、力量，還是其他東西？', 28153),
(143459, 'zhTW', '', '獸群熱切地呼喚你。接受親族的羈絆，與你的兄弟姊妹們一同狩獵吧。', 28153),
(143458, 'zhTW', '你聞到了嗎？捲心菜的味道。$b$b<克隆娜靠近你，在你身上嗅了嗅。>$b$b不是你，是附近某種東西的味道。$b$b對了，你字寫得怎麼樣？需要我教你嗎？要是你相信的話，我可是個雕銘大師。', '', 28153),
(143457, 'zhTW', '有人在攻擊我們！', '有人在攻擊我們！', 28153),
(143456, 'zhTW', '拿起武器，兄弟姐妹們！', '拿起武器，兄弟姐妹們！', 28153),
(143455, 'zhTW', '敵人就在我們身邊！', '敵人就在我們身邊！', 28153),
(143454, 'zhTW', '有人入侵！備戰！', '有人入侵！備戰！', 28153),
(143452, 'zhTW', '我很樂意。', '', 28153),
(143451, 'zhTW', '快點！', '', 28153),
(143450, 'zhTW', '我們有工單要趕！', '', 28153),
(143449, 'zhTW', '', '請不要打擾小孩子。\n\n我在測試這些小孩，看看他們有沒有和羅亞連結的跡象。那些被羅亞祝福的小孩會獲得完整的祭司訓練，還有一切伴隨而來的榮耀和特權。\n\n我們會給沒受到祝福的孩子一個機會，他們要證明他們有一天能夠長成強大的戰士。\n\n兩樣測試都沒通過的人對我們來說沒有用。他們最後或許會在碼頭當小偷，或是在佐卡洛當乞丐。', 28153),
(143448, 'zhTW', '我會去做。', '', 28153),
(143447, 'zhTW', '好的，好的。', '', 28153),
(143446, 'zhTW', '工作，工作。', '', 28153),
(143445, 'zhTW', '我們需要更多木材！', '', 28153),
(143444, 'zhTW', '你死的時候就可以休息了。在那之前，我們有命令要達成！', '', 28153),
(143443, 'zhTW', '在完全消失之前，我會盡快趕回村落，也許他們還沒忘記我。', '', 28153),
(143442, 'zhTW', '即使只是這麼短暫的體驗，我不覺得今後我還能像以前那樣，過得像一隻毫無思考能力的猴子。', '', 28153),
(143441, 'zhTW', '達卡說得沒錯，我可以感受到心靈逐漸回歸原始狀態。', '', 28153),
(143440, 'zhTW', '你好，旅人，今天想買些卷軸嗎？$b$b或是想買些用珍稀草藥製成的異國墨水？', '', 28153),
(143439, 'zhTW', '這些哥布林的腦袋太小，什麼都記不住，你要多殺幾百個他們才會學到教訓。', '', 28153),
(143438, 'zhTW', '正好讓那些哥布林瞧瞧招惹黑鐵矮人會有什麼下場！', '', 28153),
(143437, 'zhTW', '打爛機器！摧毀工具！把擋路的綠皮傢伙全都解決掉！', '', 28153),
(143436, 'zhTW', '這些哥布林嚴重污染了艾澤萊晶岩！絕對不能容許這種事發生！', '', 28153),
(143435, 'zhTW', '終於把反對者拿回來了。好好教訓這些哥布林，讓他們再也不敢偷黑鐵矮人的東西！', '', 28153),
(143434, 'zhTW', '是誰？誰趕走迷霧？達卡王殺死你！', '', 28153),
(143433, 'zhTW', '為了部落！', '為了部落！', 28153),
(143432, 'zhTW', '小堤卡飢餓地看著豬隻。', '', 28153),
(143431, 'zhTW', '小堤卡嬉鬧地擺動。', '', 28153),
(143430, 'zhTW', '', '誰是喜歡嚼東西的可愛小迅猛龍啊？就是你！就是你啦！', 28153),
(143429, 'zhTW', '', '喔，真高興看到你這小傢伙！$n…謝謝你。', 28153),
(143428, 'zhTW', '', '那是堤卡嗎？！？！', 28153),
(143427, 'zhTW', '小堤卡快樂地發出顫聲。', '', 28153),
(143426, 'zhTW', '', '還會有…別人的…', 28153),
(143425, 'zhTW', '', '贊達拉帝國有如落日。無信者會接管這一切！', 28153),
(143424, 'zhTW', '你等著被五馬分屍吧！', '你就等著被五馬分屍吧！', 28153),
(143423, 'zhTW', '小堤卡將鼻子舉至空中。牠發出一陣銳利的叫喊。', '', 28153),
(143422, 'zhTW', '你們會向女王臣服的！', '你們會向女王跪地臣服的！', 28153),
(143421, 'zhTW', '你也…逃不過…她…', '你也…逃不過…她…', 28153),
(143420, 'zhTW', '斯陀頌恩家族會統治這裡！', '斯陀頌恩家族會統治這裡！', 28153),
(143419, 'zhTW', '', '真是謝謝你，$n。如果這個有用，我就準備去幽暗之尾的洞窟幫班金一個忙。', 28153),
(143418, 'zhTW', '', '我其實可以做出用來識讀殘暴龍大腦掃描的儀器的，說說罷了。', 28153),
(143417, 'zhTW', '', '科學是唯一的解藥，詹加拉。我無意貶低你的力量，但胡言亂語不能取代進步、充滿邏輯的鍊金術。', 28153),
(143416, 'zhTW', '我們會讓那些弱小的人類見識部落的力量！', '', 28153),
(143415, 'zhTW', '在我們的刀刃砍向這些人類的血肉前，他們應該恐懼我們！', '', 28153),
(143414, 'zhTW', '為了部落！', '', 28153),
(143413, 'zhTW', '我準備回祖達薩…別擔心，我自己可以回去。下次到城裡的時候，記得找我聊聊。', '', 28153),
(143412, 'zhTW', '等等，金提基，帶這隻迅猛龍一起走。牠似乎…比較喜歡你。', '', 28153),
(143411, 'zhTW', '眼睛放亮一點！我不喜歡那些人類在伐木場附近鬼鬼祟祟的！', '', 28153),
(143410, 'zhTW', '動作快點！', '', 28153),
(143409, 'zhTW', '我們在這裡的工作告一個段落，我也該去沃魯敦贖罪了。', '', 28153),
(143408, 'zhTW', '要是被我抓到有人在工作的時候睡覺，我就親自抓你們去餵狼！', '', 28153),
(143407, 'zhTW', '繼續把資源送進來！', '', 28153),
(143404, 'zhTW', '你一定…會死…', '你一定…會死…', 28153),
(143403, 'zhTW', '這怎麼…可能…', '這怎麼…可能…', 28153),
(143402, 'zhTW', '', '帶著你的野獸往城裡去吧。等我們搞定以後我會帶給你一籃子的蛇頭的！', 28153),
(143401, 'zhTW', '你會見識…風暴的…核心…', '你會見識…風暴的…核心…', 28153),
(143400, 'zhTW', '你…也…會死…', '你…也…會死…', 28153),
(143399, 'zhTW', '深處就是霧氣的來源。', '', 28153),
(143398, 'zhTW', '我的靈魂…會…沉入海底…', '我的靈魂…會…沉入海底…', 28153),
(143397, 'zhTW', '我要…前往…海底了…', '我要…前往…海底了…', 28153),
(143396, 'zhTW', '他們殺了我們的酋長！整個村莊都毀了！', '', 28153),
(143395, 'zhTW', '主排氣孔就在裡面，快！', '', 28153),
(143394, 'zhTW', '我會…回到深海…', '我會…回到深海…', 28153),
(143391, 'zhTW', '就連潮水…也會退去…', '就連潮水…也會退去…', 28153),
(143390, 'zhTW', '我全身充滿她的力量！', '我全身充滿她的力量！', 28153),
(143389, 'zhTW', '你受死吧！', '你受死吧！', 28153),
(143388, 'zhTW', '命運的觸手會包圍你！', '命運的觸手會包圍你！', 28153),
(143387, 'zhTW', '你只會剩下冰冷的軀殼！', '你只會剩下冰冷的軀殼！', 28153),
(143386, 'zhTW', '我要把你活活淹死！', '我要把你活活淹死！', 28153),
(143385, 'zhTW', '沒有人能阻擋浪潮！', '沒有人能阻擋浪潮！', 28153),
(143384, 'zhTW', '聽從深海的呼喚！', '聽從深海的呼喚！', 28153),
(143383, 'zhTW', '海浪會把你沖走！', '海浪會把你沖走！', 28153),
(143382, 'zhTW', '而殞落的是…達卡王。', '', 28153),
(143381, 'zhTW', '', '我…說好的…榮耀呢…', 28153),
(143380, 'zhTW', '惡人！你如蠟燭一般，被燃盡最適切。', '', 28153),
(143379, 'zhTW', '', '你再強，也會跟其他人一樣敗在我們手下！', 28153),
(143378, 'zhTW', '', '無所謂。反正死人也不能說話了。手下們，攻擊！', 28153),
(143377, 'zhTW', '', '你找到我們了。你一定很得意吧。', 28153),
(143376, 'zhTW', '呵！如果智能不能讓你獲得權利和力量，還要這玩意幹麻呢？我到時候就是贊達拉的君主。你要嘛搞清楚現實，要不就下地獄吧！', '', 28153),
(143375, 'zhTW', '達卡，我必須阻止你。我們從來都不該擁有所謂的智能，更何況還因此掀起一場戰爭！', '', 28153),
(143374, 'zhTW', '祖加…你帶了一個羸弱無力的人來到這裡，在這片神聖迷霧之中。你為什麼要來？', '', 28153),
(143373, 'zhTW', '下面出了什麼事？', '下面出了什麼事？', 28153),
(143372, 'zhTW', '真相就在…深海之中…', '真相就在…深海之中…', 28153),
(143371, 'zhTW', '我流著…大海的血…', '我流著…大海的血…', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143370, 'zhTW', '去吧，迷霧的源頭就在這洞穴中。不確定達卡王在哪裡，快點！', '', 28153),
(143369, 'zhTW', '這地方的鮮血魔法很強大。就連巫醫以外的人都感覺得到…它無所不在…', '', 28153),
(143368, 'zhTW', '', '噢…你在這做什麼，內陸人？\n\n我能幫你什麼忙嗎？', 28153),
(143367, 'zhTW', '你要我去殺誰？', '', 28153),
(143366, 'zhTW', 'Taz\'dingo! (勝利！)', '', 28153),
(143365, 'zhTW', '為了部落！', '', 28153),
(143364, 'zhTW', '殺戮時間到！', '', 28153),
(143363, 'zhTW', '殺人超簡單。', '', 28153),
(143362, 'zhTW', '絕不留情！', '', 28153),
(143361, 'zhTW', '人頭落地！', '', 28153),
(143360, 'zhTW', '為了榮耀部落！', '', 28153),
(143359, 'zhTW', '', '為了榮耀部落！', 28153),
(143358, 'zhTW', '', '人頭落地！', 28153),
(143357, 'zhTW', '', '絕不留情！', 28153),
(143356, 'zhTW', '我們…絕不鬆懈…', '我們…絕不鬆懈…', 28153),
(143355, 'zhTW', '殺了我…也沒用…', '殺了我…也沒用…', 28153),
(143354, 'zhTW', '我們…已經贏了…', '我們…已經贏了…', 28153),
(143353, 'zhTW', '', '殺人超簡單。', 28153),
(143352, 'zhTW', '我只是…聽命行事…', '我只是…聽命行事…', 28153),
(143351, 'zhTW', '浪潮賢者…救救我…', '浪潮賢者…救救我…', 28153),
(143350, 'zhTW', '我為…海洋而生…', '我為…海洋而生…', 28153),
(143349, 'zhTW', '庫爾提拉斯屬於大海！', '庫爾提拉斯屬於大海！', 28153),
(143348, 'zhTW', '你敢對抗斯陀頌恩家族？', '你敢對抗斯陀頌恩家族？', 28153),
(143347, 'zhTW', '我們就像大海一樣無情！', '我們就像大海一樣無情！', 28153),
(143346, 'zhTW', '反抗我們的都得死！', '反抗我們的都得死！', 28153),
(143345, 'zhTW', '我們的軍隊會殺了你！', '我們的軍隊會殺了你！', 28153),
(143344, 'zhTW', '', '殺戮時間到！', 28153),
(143343, 'zhTW', '', '來吧，姊妹！', 28153),
(143342, 'zhTW', '少了我們，庫爾提拉斯會沉入海底！', '少了我們，庫爾提拉斯會沉入海底！', 28153),
(143341, 'zhTW', '', '來吧，兄弟！', 28153),
(143340, 'zhTW', '谷地是我們的，鼠輩！', '谷地是我們的，鼠輩！', 28153),
(143339, 'zhTW', '以斯陀頌恩之名！', '以斯陀頌恩之名！', 28153),
(143338, 'zhTW', '', '這麼多死掉的恐龍…我可是從蛋就開始養牠們。這就像看我自己的孩子死去一樣。$b$b蛇人要付出代價。', 28153),
(143337, 'zhTW', '建築物周圍出現大量腐化物質。必須立即採取行動。', '', 28153),
(143336, 'zhTW', '部分恢復程序完成。必須繼續修復腐化抑制作業。', '', 28153),
(143335, 'zhTW', '升級輔助系統中。請稍候…', '', 28153),
(143334, 'zhTW', '你會修理裝備嗎？', '你會修理裝備嗎？', 28153),
(143333, 'zhTW', '村子雖然沒了，但他們若想要我的熔爐，得先扳開我死僵的手指。', '', 28153),
(143332, 'zhTW', '', '為了部落！', 28153),
(143331, 'zhTW', '', 'Taz\'dingo! (勝利！)', 28153),
(143330, 'zhTW', '', '你要我去殺誰？', 28153),
(143329, 'zhTW', '幸好無辜的人民都沒事，但我們還有很多事要做。', '', 28153),
(143328, 'zhTW', '', '我在此之前只聽過關於暴風城的故事。我會親自到街上走走，欣賞這裡的美景。願暗影指引你，$n。', 28153),
(143327, 'zhTW', '願聖光與你同在，$n。我打算在艾澤拉斯尋找燃燒軍團的餘孽，繼續這場永恆之戰。', '', 28153),
(143326, 'zhTW', '當然了，只是想想啦，…但我真的有想過。想了快整整一秒！', '', 28153),
(143325, 'zhTW', '我得說，看你認真工作的樣子，我都差點想把賺來的錢分你一份了。', '', 28153),
(143324, 'zhTW', '幹得好啊！真正的好戲終於要開始了…簽好這些文件佔有整個礦場。一定要正式又漂亮。', '', 28153),
(143323, 'zhTW', '我說真的，最好把它們都殺光，才不會害我少賺。', '', 28153),
(143322, 'zhTW', '目標已設定。前往下個位置。完成前往新地點。', '', 28153),
(143321, 'zhTW', '哈！看那些笨蛋被打個稀巴爛。元素出手還真夠狠的。', '', 28153),
(143320, 'zhTW', '小堤卡小聲發出威脅的低吼。', '', 28153),
(143319, 'zhTW', '小堤卡不安地啁啾叫！', '', 28153),
(143318, 'zhTW', '這世界受傷了，你們還撕扯傷口？！去死吧！', '', 28153),
(143317, 'zhTW', '我要看到爆炸、動亂，還有極度的暴力！反正…就是你最擅長的事情。', '', 28153),
(143316, 'zhTW', '讓風險投資公司的人知道，他們所有的東西，我都能奪走。', '', 28153),
(143315, 'zhTW', '問題就在…東西不是我的！所以，這就要靠你了。', '', 28153),
(143314, 'zhTW', '黑市裡的艾澤萊晶岩就是這麼來的囉？搞得還不錯嘛。', '', 28153),
(143313, 'zhTW', '', '我不知道「座狼剋星」是什麼…等等，這個呢？', 28153),
(143312, 'zhTW', '是這個世界配不上你啊。兄弟，我一定會幫你好好辦場葬禮。', '', 28153),
(143311, 'zhTW', '我早上醒來，喜歡聞聞魔精的味道醒腦。', '', 28153),
(143310, 'zhTW', '', '洛克漢說你有跟這種東西打交道的經驗。那就交給你了。我將會留在這裡等哥布林戰隊。', 28153),
(143308, 'zhTW', '', '勇士，我們需要所有的盟友。去幫助這個守衛者…而且要快。', 28153),
(143307, 'zhTW', '需要協助。修復赫茲羅。進入附近建築內部。隔離納茲米爾的所有腐化。', '', 28153),
(143306, 'zhTW', '納茲米爾內部偵測到大規模腐化。必須進行隔離。', '', 28153),
(143305, 'zhTW', '我經歷無數次戰鬥…但是像這樣的怪物…前所未見…', '', 28153),
(143304, 'zhTW', '你休想活捉我！', '', 28153),
(143303, 'zhTW', '很好，沃魯敦一定比這裡更安全！', '', 28153),
(143302, 'zhTW', '不！不要！迅猛龍…會把我吃掉！', '', 28153),
(143301, 'zhTW', '謝謝你，扎魯圖，來生再當兄弟吧。', '', 28153),
(143300, 'zhTW', '對祖拉金使用鮮血神像來吸收它的力量，然後把它送回地獄！', '', 28153),
(143299, 'zhTW', '夥計，不用擔心！我會在這裡照顧隊長，廢墟就交給你了！', '', 28153),
(143298, 'zhTW', '好了！現在進行偽裝然後拿走鑰匙！', '', 28153),
(143297, 'zhTW', '你需要偽裝一下，才不會被祖拉金盯上。一拿到補給品，就快點回來！', '', 28153),
(143296, 'zhTW', '我是個罪犯，但我不是什麼罪大惡極的人，我不可能放你在這裡死掉！', '', 28153),
(143295, 'zhTW', '謝謝你，就算我死了…我的名聲也得到保全…', '', 28153),
(143294, 'zhTW', '聽我說！讓我們向這位能解救…嗝……所有人的英雄敬酒！', '', 28153),
(143293, 'zhTW', '', '去奧格瑪吧。跟我們的盟友會合，一同打造全新的未來。', 28153),
(143292, 'zhTW', '', '你在艾澤拉斯行動的時候，記得把夜裔精靈的歷史告訴你遇到的人…讓大家知道，我們不再與世隔絕了。', 28153),
(143291, 'zhTW', '我們對夜裔的了解有多少？', '我們對夜裔的了解有多少？', 28153),
(143290, 'zhTW', '', '$n，幸好你在這裡。我們一定要讓大酋長相信，夜裔會成為部落很好的盟友。', 28153),
(143289, 'zhTW', '我們對高嶺牛頭人的了解有多少？', '我們對高嶺牛頭人的了解有多少？', 28153),
(143288, 'zhTW', '', '現在就是我們為部落展現力量、帶來榮耀的時候了。', 28153),
(143287, 'zhTW', '我們和高嶺牛頭人一起經歷了那麼多，我相信他們在未來會成為可靠的盟友。', '', 28153),
(143286, 'zhTW', '', '別擔心祖加。我們會照顧他。就算他不再記得自己的名字也一樣。', 28153),
(143285, 'zhTW', '', '哇，他可真大隻，是不是？做得好，朋友！', 28153),
(143284, 'zhTW', '', '願星辰指引你，$p。我聽說希爾斯布萊德丘陵發生了奇怪的事，我可能會去那裡吧。', 28153),
(143283, 'zhTW', '', '祖加，你確定要這麼做嗎？要是讓這名勇士驅走迷霧，你知道自己會失去什麼嗎？', 28153),
(143282, 'zhTW', '我去準備釋放這些靈魂的儀式。你到北邊的海岸和我碰面。', '', 28153),
(143281, 'zhTW', '我完全瞭解會有什麼後果，雖然我知道有些東西很難放掉，不過你也不得不放。', '', 28153),
(143280, 'zhTW', '我會從另一條路去深谷，我們就在那見面吧。', '', 28153),
(143279, 'zhTW', '穩住陣形！援軍要來了，我們不能讓納迦破壞堤岸！', '', 28153),
(143278, 'zhTW', '放下你心中的仇恨吧。', '', 28153),
(143277, 'zhTW', '', '但是辛多雷，也就是血精靈，對我們尊重與包容。他們證明了在艾澤拉斯，有人了解我們的想法與信念。', 28153),
(143276, 'zhTW', '', '在這座城市最黑暗的時刻，艾澤拉斯的英雄與我們並肩作戰，擊退了燃燒軍團。有些人並不情願。', 28153),
(143275, 'zhTW', '', '這件蘇拉瑪爾的傳統服裝送給你。請把它穿上，牢記我們族人的歷史…然後和盟友一起打造全新的未來。', 28153),
(143274, 'zhTW', '我很清楚該怎麼做！', '', 28153),
(143273, 'zhTW', '', '你讓部落還有全艾澤拉斯的人民都看見，夜裔擁有保衛這個世界的意志與勇氣。', 28153),
(143272, 'zhTW', '從院子另一頭的海岸過去，找到叫做泰莉亞的普勞德摩爾衛隊年輕成員。快去！', '', 28153),
(143271, 'zhTW', '', '回到蘇拉瑪爾來。我們要感謝你，讓我們在世界上重新佔有一席之地。', 28153),
(143270, 'zhTW', '', '你是率先代表夏多雷在艾澤拉斯荒野冒險的先鋒。但現在，回家的時候到了。', 28153),
(143269, 'zhTW', '那些工人…都被浪潮賢者的魔法束縛了！一定要幫助他們。', '', 28153),
(143268, 'zhTW', '感謝海潮，至少還有人沒失去理智。斯陀頌恩家族有一半的人都瘋了！', '', 28153),
(143267, 'zhTW', '我不想要法蘭絨襯衫了。', '我不想要法蘭絨襯衫了。', 28153),
(143266, 'zhTW', '', '我去前面偵察。我們海邊見！', 28153),
(143265, 'zhTW', '看起來不錯，$n。', '', 28153),
(143264, 'zhTW', '我們還有事情要做。', '', 28153),
(143263, 'zhTW', '我想穿上法蘭絨襯衫。', '我想穿上法蘭絨襯衫。', 28153),
(143262, 'zhTW', '', '準備作戰！', 28153),
(143261, 'zhTW', '', '為了國王！', 28153),
(143260, 'zhTW', '', '我要殺了你！', 28153),
(143259, 'zhTW', '', '去死吧！', 28153),
(143258, 'zhTW', '', '為了暴風城！', 28153),
(143257, 'zhTW', '', '為了聯盟！', 28153),
(143256, 'zhTW', '', '永不退縮！', 28153),
(143255, 'zhTW', '', '我來對付他們！', 28153),
(143254, 'zhTW', '', '你說的腐化是指什麼？說不定它說的「腐化」，指的是鮮血食人妖。', 28153),
(143253, 'zhTW', '', '勇士，你知道這到底是什麼嗎？這東西能幫得了我們嗎？', 28153),
(143252, 'zhTW', '', '這到底是什麼鬼巫術？說不定，它能幫我們阻止鮮血食人妖跟古翰…', 28153),
(143251, 'zhTW', '我來對付他們！', '', 28153),
(143250, 'zhTW', '永不退縮！', '', 28153),
(143249, 'zhTW', '為了聯盟！', '', 28153),
(143248, 'zhTW', '為了暴風城！', '', 28153),
(143247, 'zhTW', '去死吧！', '', 28153),
(143246, 'zhTW', '我要殺了你！', '', 28153),
(143245, 'zhTW', '為了國王！', '', 28153),
(143244, 'zhTW', '準備作戰！', '', 28153),
(143243, 'zhTW', '哇啊，探測器簡直瘋了。看來島上的某個地方會噴發出大量的艾澤萊晶岩。', '', 28153),
(143242, 'zhTW', '我們一定要找出污染的來源。', '', 28153),
(143241, 'zhTW', '', '給你的這套護甲象徵你所達到的成就。收下這份謝禮吧。', 28153),
(143240, 'zhTW', '毫無疑問。', '', 28153),
(143239, 'zhTW', '你…你是說海中的生物也被腐化了嗎？', '', 28153),
(143238, 'zhTW', '那我再跟你說個「壞兆頭」吧。這個海灣充滿怪物。', '', 28153),
(143237, 'zhTW', '祖加看了看洞穴入口，顯得很擔心。', '', 28153),
(143236, 'zhTW', '', '許多人認為刃多雷無法克服虛無的影響，絕對會被這股力量給吞噬。你已經證明他們都錯了。', 28153),
(143235, 'zhTW', '離岸邊越遠，海水的呼嘯就越尖銳。我可以感受到海潮的痛苦。這是很壞的兆頭。', '', 28153),
(143234, 'zhTW', '', '你已經成為聯盟的重要戰力了。回虛無裂隙去吧，我們想表揚你的成就。', 28153),
(143233, 'zhTW', '我們來完成儀式吧。', '', 28153),
(143230, 'zhTW', '我會去訓練。你去見塔戈特，他可以幫你。', '', 28153),
(143229, 'zhTW', '泰坦守衛者赫茲羅重新啟動完畢。執行協議：隔離納茲米爾的嚴重腐化。系統受損，無法完成任務。', '', 28153),
(143228, 'zhTW', '', '你在艾澤拉斯經歷了這些冒險之後，已經掌握了這股力量，不會再被它控制了。', 28153),
(143227, 'zhTW', '抓得好，朋友。我們來看看他怎麼飛。嘻啊！', '', 28153),
(143226, 'zhTW', '哈哈！軟腳蝦帶禮物回來了！真不敢相信！', '', 28153),
(143224, 'zhTW', '我會讓神王拉斯塔哈知道，如果高塔發出火光，就表示我們奪回船隻了。這樣我的船員就知道他們可以回家了！', '', 28153),
(143223, 'zhTW', '所需的主題在這張照片並不清楚，沃弗德不會要的。', '所需的主題在這張照片並不清楚，沃弗德不會要的。', 28153),
(143222, 'zhTW', '朋友，快來幫助我！', '', 28153),
(143221, 'zhTW', '這裡的工人…都是我的錯。', '', 28153),
(143220, 'zhTW', '', '來人！指揮官受到攻擊！', 28153),
(143219, 'zhTW', '救命！我被攻擊了！', '', 28153),
(143218, 'zhTW', '你會付出代價的！', '', 28153),
(143217, 'zhTW', '這傢伙真讓我不爽！', '', 28153),
(143216, 'zhTW', '啊！保險費又要漲了！', '', 28153),
(143215, 'zhTW', '我付錢給你們這些笨蛋幹嘛？！還不快想辦法！', '', 28153),
(143214, 'zhTW', '讓你見識高級大屠殺！', '', 28153),
(143213, 'zhTW', '嚐嚐一分鐘300發的威力吧！', '', 28153),
(143212, 'zhTW', '你只配被我…踩在腳下！', '', 28153),
(143211, 'zhTW', '吃土吧！', '', 28153),
(143210, 'zhTW', '', '我先去偵察一下，我們在路的另一邊會合！', 28153),
(143209, 'zhTW', '你別想活捉我！', '', 28153),
(143208, 'zhTW', '應該…加購…彈射...逃生座椅…', '', 28153),
(143207, 'zhTW', '彈藥的費用我會找你家裡的人要。', '', 28153),
(143206, 'zhTW', '', '用我教你們的方法來保持控制。讓自己成為聯盟的武器…就算遊走在黑暗邊緣也在所不惜。', 28153),
(143205, 'zhTW', '有些人會懷疑你。他們會質疑你的決心，不相信你能駕馭這股力量，因為意志軟弱的人會被逼瘋。', '', 28153),
(143204, 'zhTW', '', '但我們找到了其他辦法。我們面前有很多條道路，也有各種可能。', 28153),
(143203, 'zhTW', '', '有些人會告訴你聖光是唯一的正道，也是唯一能捍衛艾澤拉斯的武器。', 28153),
(143202, 'zhTW', '你們這群草包知道自己害我損失多少資產嗎！？', '', 28153),
(143201, 'zhTW', '歡迎加入粗脖幫！', '', 28153),
(143200, 'zhTW', '', '', 28153),
(143199, 'zhTW', '摧毀！', '', 28153),
(143198, 'zhTW', '攻擊！', '', 28153),
(143197, 'zhTW', '徹底粉碎！', '', 28153),
(143196, 'zhTW', '很遺憾我沒能好好教導他最重要的一課是什麼。', '', 28153),
(143195, 'zhTW', '告訴拉斯塔哈，時候到了我就會回來。啊，對了，謝謝你幫忙。', '', 28153),
(143193, 'zhTW', '當我用我的利爪抓住亞茲瑪和祖爾時，我要把他們摔到岩石上！', '', 28153),
(143192, 'zhTW', '獵物就在附近，祖爾、亞茲瑪和他們那些異教徒的血很快就會染紅大地，這次狩獵一定很精彩。', '', 28153),
(143191, 'zhTW', '這份榮耀獻給帕骷！', '這份榮耀獻給帕骷！', 28153),
(143190, 'zhTW', '這艘船是我們的！', '這艘船是我們的！', 28153),
(143189, 'zhTW', 'Taz\'okun！', 'Taz\'okun！', 28153),
(143188, 'zhTW', '只是皮肉傷，我想應該沒事吧…', '', 28153),
(143185, 'zhTW', '', '你會整個燒光光！', 28153),
(143184, 'zhTW', '', '燒吧！哈哈哈！燒吧！', 28153),
(143183, 'zhTW', '', '想找艾澤萊晶岩？讓你滿臉都是！', 28153),
(143182, 'zhTW', '', '糟糕！看來公司的『連續無人傷亡天數』又要歸零了。', 28153),
(143181, 'zhTW', '怎麼樣都不值得！', '', 28153),
(143180, 'zhTW', '', '職場經驗不足是會出事的！', 28153),
(143179, 'zhTW', '為了聯盟！', '', 28153),
(143178, 'zhTW', '', '能再度為國王效勞是我的榮幸。為了聯盟！', 28153),
(143177, 'zhTW', '', '謝謝再連絡囉！', 28153),
(143176, 'zhTW', '風行者女士，還有勇士，你們立下了大功。我很感謝你們。', '', 28153),
(143175, 'zhTW', '這些虛無精靈要贏得所有人的信任可能還需要一點時間，但只要他們願意聽從你的指導，聯盟就歡迎他們。', '', 28153),
(143174, 'zhTW', '', '應該…要有…危險津貼…', 28153),
(143173, 'zhTW', '', '我會引導他們，教他們克制暗影的低語。這樣一來，他們就可以對抗敵人，為聯盟貢獻一分力量。', 28153),
(143172, 'zhTW', '', '烏瑞恩國王，我和勇士發現了辛多雷的流放者。他們跟我一樣受到虛無的影響而改變，但仍然可以掌握自己的意志。', 28153),
(143171, 'zhTW', '', '想把事情做好…就用更猛的炸藥！', 28153),
(143170, 'zhTW', '', '是你害我的工作團隊開溜嗎？', 28153),
(143169, 'zhTW', '', '嘿！你們想跑去哪裡？', 28153),
(143168, 'zhTW', '有人入侵？！快跑！！', '有人入侵？！快跑！！', 28153),
(143167, 'zhTW', '我不知道你的心智被什麼黑暗蒙蔽，姐妹。但我不會讓它繼續折磨人民的。', '', 28153),
(143166, 'zhTW', '你可以的！', '', 28153),
(143165, 'zhTW', '逃跑者！', '', 28153),
(143164, 'zhTW', '', '我不想再聽到什麼工作環境危險的抱怨了！', 28153),
(143163, 'zhTW', '這裡不安全。你必須離開這裡。', '', 28153),
(143162, 'zhTW', '反正島嶼也不怎麼樣！', '', 28153),
(143161, 'zhTW', '我們完蛋了！', '', 28153),
(143160, 'zhTW', '走吧！這裡沒你的事了。', '', 28153),
(143159, 'zhTW', '他掙脫了！回來！', '', 28153),
(143158, 'zhTW', '你們自由了，兄弟姐妹們。', '', 28153),
(143157, 'zhTW', '', '抱怨的話，就代表你沒在憋氣！那吸到毒煙就是你自己的問題！', 28153),
(143156, 'zhTW', '去找家人吧。這讓我們來處理。', '', 28153),
(143155, 'zhTW', '逃啊，傻瓜！', '', 28153),
(143154, 'zhTW', '把靈魂從軀殼裡洗去，讓靈魂和海水一起流動。', '', 28153),
(143153, 'zhTW', '只要傾聽風暴的樂章，就能平靜。', '', 28153),
(143152, 'zhTW', '別懷疑燈塔為誰而亮。它為你而亮。', '', 28153),
(143151, 'zhTW', '', '為了部落！', 28153),
(143150, 'zhTW', '', '為了部落！', 28153),
(143149, 'zhTW', '', '蘇拉瑪爾會與部落並肩作戰！', 28153),
(143148, 'zhTW', '', '蘇拉瑪爾千年以來都與世隔絕。從今天起，你們要為更遠大的目標而戰。薩莉瑟拉，我接受你的宣誓效忠。', 28153),
(143147, 'zhTW', '', '夜裔準備要在艾澤拉斯尋求盟友。如果你們願意接受，夜裔會向部落效忠，為部落而戰。', 28153),
(143146, 'zhTW', '', '部落有力量、有決心、又獨特，這些都是夏多雷非常重視的。', 28153),
(143145, 'zhTW', '', '確實如此，首席秘法師。', 28153),
(143144, 'zhTW', '', '大酋長，幸會。我曾與莉雅德倫和攝政王並肩作戰。他們的英勇，是部落的典範。', 28153),
(143143, 'zhTW', '別怕，兄弟。海浪不會只靠表象來審判。', '', 28153),
(143142, 'zhTW', '潮起潮落，往復不休，靈魂苦痛。', '', 28153),
(143141, 'zhTW', '你勇敢無畏的靈魂可以永遠安息了。', '', 28153),
(143140, 'zhTW', '願深海迎接你疲憊的靈魂。', '', 28153),
(143139, 'zhTW', '潮母會洗淨你邪惡的血肉。', '', 28153),
(143138, 'zhTW', '讓海流帶你走，亡者。', '', 28153),
(143137, 'zhTW', '大地會吞噬你！', '', 28153),
(143136, 'zhTW', '海歸海、塵歸塵、潮水歸潮水。', '', 28153),
(143135, 'zhTW', '粉碎！', '', 28153),
(143134, 'zhTW', '你身上流著艾澤拉斯之血！', '', 28153),
(143133, 'zhTW', '我們不能再讓這些失落的靈魂繼續遊蕩了。我們可能會有所衝突，朋友。', '', 28153),
(143132, 'zhTW', '釋放你的力量！', '', 28153),
(143131, 'zhTW', '雖然泡過水了，但還可以用。我們會需要這上面的咒語。', '', 28153),
(143130, 'zhTW', '海洋的迷霧隱藏著許多事物，但有這個信標就可以找到它們。', '', 28153),
(143129, 'zhTW', '起來吧！', '', 28153),
(143128, 'zhTW', '', '歡迎，孩子。我的視力或許已離我遠去，但帕骷還沒。\n\n和我坐一會，告訴我你那些關於偉大羅亞的問題吧，我會盡力解答的。', 28153),
(143127, 'zhTW', '很好，這把匕首還很銳利。銳利的匕首才安全。', '', 28153),
(143126, 'zhTW', '你再也不能作怪了。', '', 28153),
(143125, 'zhTW', '你的血有什麼價值？', '', 28153),
(143124, 'zhTW', '', '大酋長希瓦娜斯·風行者，這位是蘇拉瑪爾的首席秘法師薩莉瑟拉。', 28153),
(143123, 'zhTW', '', '我會加入行列，等候你的命令。', 28153),
(143122, 'zhTW', '', '我有疑問…但我會接受命令的。', 28153),
(143121, 'zhTW', '', '瑞德元帥認為你就是我們擊退女巫會的關鍵？', 28153),
(143120, 'zhTW', '用力砍，認真砍！', '', 28153),
(143119, 'zhTW', '呵，也差不多了。', '', 28153),
(143118, 'zhTW', '再用力一點！', '', 28153),
(143117, 'zhTW', '快拔！', '', 28153),
(143116, 'zhTW', '溫斯頓，來。看來我們要獵女巫了。', '', 28153),
(143115, 'zhTW', '再砍深一點點，就大功告成了。', '', 28153),
(143114, 'zhTW', '就快好了！再一下下就好。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143113, 'zhTW', '新命令嗎？', '', 28153),
(143112, 'zhTW', '謝謝你把命令送過來，我馬上去向威奎斯特小姐報到。', '', 28153),
(143111, 'zhTW', '我還以為燼火會的故事是群大驚小怪的歷史學家瞎編出來的。', '', 28153),
(143110, 'zhTW', '你們只不過是寄生蟲。', '', 28153),
(143109, 'zhTW', '傳言是真的嗎？燼火會重新建立了嗎？', '', 28153),
(143108, 'zhTW', '傷口…一定要修復…', '', 28153),
(143107, 'zhTW', '', '算我一份吧。', 28153),
(143106, 'zhTW', '你闖進我的地盤了！', '', 28153),
(143105, 'zhTW', '', '雖然我不相信你說的這些話，不過有所行動總比坐在這裡等女巫殺光我們好。', 28153),
(143104, 'zhTW', '', '這麼說來你就是這個「燼火會」的幕後推手了。', 28153),
(143103, 'zhTW', '<交出瑞德元帥的命令。>', '<交出瑞德元帥的命令。>', 28153),
(143102, 'zhTW', '', '傀儡開始加入戰場。士兵都死光了，他只好自己創造大軍。但他是怎麼賦予這些石頭力量的？', 28153),
(143101, 'zhTW', '', '我能幫你什麼忙嗎，$c？', 28153),
(143100, 'zhTW', '', '這就是他們那位最偉大的領袖，勾拉圖爾。啊！他在帶領大家舉行創造石頭傀儡的儀式！', 28153),
(143099, 'zhTW', '<斯騰泰德中尉知道你來了，他輕輕地點頭示意。>', '', 28153),
(143098, 'zhTW', '很好的個體，對吧？威奎斯特家族一直以來都以馴鷹專家而聞名。\n\n很不幸的，我們大部分的鳥都受到了女巫的詛咒。這隻獵鷹溫斯頓是少數沒有受她們詛咒控制的威奎斯特獵鷹。\n\n局勢真的很糟。', '', 28153),
(143097, 'zhTW', '', '可是…他們卻在大屠殺！庫爾提拉斯人的手上甚至連武器都沒有！', 28153),
(143096, 'zhTW', '林子裡有些邪惡的騷動，內陸人。在夜晚，遠古佐司特紀念碑的核心散發著不潔的力量。\n\n如果我是你，我旅行時會離那地方遠遠的。', '', 28153),
(143095, 'zhTW', '', '什麼事，內陸人？\n\n如果你看不出來的話，我現在有點忙。', 28153),
(143094, 'zhTW', '消滅入侵者，清除…清除。', '', 28153),
(143093, 'zhTW', '腐化即將釋放。啟－啟動安－安－全協定。找到入－入侵者。', '', 28153),
(143092, 'zhTW', '錯誤…入侵…已偵測…正在掃描…腐化。', '', 28153),
(143091, 'zhTW', '准許使用有毒氣體。', '', 28153),
(143090, 'zhTW', '高壓電提高。', '', 28153),
(143089, 'zhTW', '啟動系統。開始重擊。', '', 28153),
(143088, 'zhTW', '', '刻在石碑上的庫爾提拉斯人…好像是平民？水手和幾個農夫？', 28153),
(143087, 'zhTW', '', '就連他們的領袖都從戰場上開溜了。', 28153),
(143086, 'zhTW', '', '哈！然後這裡我們反擊了！', 28153),
(143085, 'zhTW', '', '奇怪的是，並沒看到任何他們的傀儡。', 28153),
(143084, 'zhTW', '風險投資公司感謝您的光顧。您購買的是高級重擊組合包，請好好享受。', '', 28153),
(143083, 'zhTW', '', '這裡是另一個淪陷的庫爾提拉斯據點。我猜中間這個比較大的人是他們的領袖吧。', 28153),
(143082, 'zhTW', '風險投資公司感謝您的光顧。您購買的是基本重擊組合包，請好好享受。', '', 28153),
(143081, 'zhTW', '再給我幾個月，我會把這個地方變成六星級度假村！', '', 28153),
(143080, 'zhTW', '笨蛋！延長保固一點用也沒有！', '笨蛋！延長保固一點用也沒有！', 28153),
(143079, 'zhTW', '我好了，好啦！等等…我應該要加購延長保固嗎？', '我好了，好啦！等等…我應該要加購延長保固嗎？', 28153),
(143078, 'zhTW', '來吧，朋友。', '', 28153),
(143077, 'zhTW', '我們會被殺死！', '我們會被殺死！', 28153),
(143076, 'zhTW', '別催我！我還在看授權說明書！', '別催我！我還在看授權說明書！', 28153),
(143075, 'zhTW', '快啊！他們來了！', '快啊！他們來了！', 28153),
(143074, 'zhTW', '只是想休息一下下。', '', 28153),
(143073, 'zhTW', '冷靜點，乖孩子。冷靜。', '', 28153),
(143072, 'zhTW', '系統…錯誤。退幣功能…故障…', '', 28153),
(143071, 'zhTW', '誰想要來飛一下？你想要來飛一下嗎？讓我們飛向天空吧！', '', 28153),
(143070, 'zhTW', '不准咬人！', '', 28153),
(143069, 'zhTW', '啟動傷害控制程序。', '', 28153),
(143068, 'zhTW', '毀損這個裝置違反了使用者規範。', '', 28153),
(143067, 'zhTW', '炸彈來啦！', '炸彈來啦！', 28153),
(143066, 'zhTW', '下面的廢物，小心啦！', '下面的廢物，小心啦！', 28153),
(143065, 'zhTW', '喂，就是你。回去工作！', '喂，就是你。回去工作！', 28153),
(143064, 'zhTW', '授權使用致命武器。', '', 28153),
(143063, 'zhTW', '敵人數量達到最高負載量。開始驅離。', '', 28153),
(143062, 'zhTW', '殯葬服務優惠中。', '', 28153),
(143061, 'zhTW', '又多一個滿意的顧客。', '', 28153),
(143060, 'zhTW', '任何失去四肢等情形，風險投資公司恕不負責。', '', 28153),
(143059, 'zhTW', '部落已經擋住了一波攻擊！', '部落已經擋住了一波攻擊！', 28153),
(143058, 'zhTW', '散開！那些聯盟狗會往我們這派遣援軍。', '', 28153),
(143057, 'zhTW', '', '這艘船一拿下海港，我就成了船長！你現在最好乖乖聽話，然後學習怎麼鞠躬行禮！', 28153),
(143056, 'zhTW', '', '這些囚犯不知道自己有多幸運！他們很快就與祖爾在一起了。', 28153),
(143055, 'zhTW', '', '如果我們要拿下海港，你必須表現得更好一點！', 28153),
(143054, 'zhTW', '我不能…控制…啊啊啊啊！', '', 28153),
(143050, 'zhTW', '不！我不能死在這裡！時候還沒到！', '', 28153),
(143049, 'zhTW', '他怎麼…知道…', '', 28153),
(143048, 'zhTW', '這…根本不可能！', '', 28153),
(143047, 'zhTW', '你很強…但我的預言更強！', '', 28153),
(143046, 'zhTW', '走開！這是命令！', '', 28153),
(143045, 'zhTW', '信徒們！快來幫助主人！', '', 28153),
(143044, 'zhTW', '會死的是你們！', '', 28153),
(143043, 'zhTW', '我看得比你還遠，老頭！', '', 28153),
(143042, 'zhTW', '沒錯，我不會。可是我朋友會。', '', 28153),
(143041, 'zhTW', '我們都知道我不會死在你手上。你沒辦法阻止我。', '', 28153),
(143040, 'zhTW', '乖女孩，差不多該吃點心了。', '', 28153),
(143039, 'zhTW', '我已經玩膩了。既然你話說完了，那就接受制裁吧。', '', 28153),
(143038, 'zhTW', '祖爾一口喝下藥水，那味道實在讓人不敢恭維。', '', 28153),
(143037, 'zhTW', '就拿你看到的第一瓶。不用想那麼多，快點。', '', 28153),
(143036, 'zhTW', '他的手下會阻止你。要小心。', '', 28153),
(143035, 'zhTW', '嗯。', '', 28153),
(143034, 'zhTW', '過來吧。時候到了。', '', 28153),
(143033, 'zhTW', '好。拿我給你的藥劑去跟沃爾詹巴的藥劑掉包。', '', 28153),
(143032, 'zhTW', '我想一下…往左邊一點好了。', '', 28153),
(143031, 'zhTW', '把甕放到拱門那邊。', '', 28153),
(143030, 'zhTW', '在大使館外就把武器亮出來，$p。這些贊達拉人缺乏必要的力量和意志力來保持冷靜。他們需要跟希瓦娜斯一樣厲害的大酋長。\n\n現在，你需要我幫什麼忙？', '在大使館外就把武器亮出來，$p。這些贊達拉人缺乏必要的力量和意志力來保持冷靜。他們需要跟希瓦娜斯一樣厲害的大酋長。\n\n現在，你需要我幫什麼忙？', 28153),
(143029, 'zhTW', '要是你發現聯盟的人潛伏在附近，就告訴我一聲，我會解決他們。\n\n至於現在呢，你想要找什麼東西？', '要是你發現聯盟的人潛伏在附近，就告訴我一聲，我會解決他們。\n\n至於現在呢，你想要找什麼東西？', 28153),
(143028, 'zhTW', '贊達拉有個長處，就是他們知道如何建造一間宏偉的大使館。而且這座城市好大！\n\n你迷路了嗎？', '贊達拉有個長處，就是他們知道如何建造一間宏偉的大使館。而且這座城市好大！\n\n你迷路了嗎？', 28153),
(143027, 'zhTW', '我很忙，快一點。', '我很忙，快一點。', 28153),
(143026, 'zhTW', '你需要什麼，$pr？', '你需要什麼，$pr？', 28153),
(143025, 'zhTW', '榮耀大酋長！你想找什麼嗎？', '榮耀大酋長！你想找什麼嗎？', 28153),
(143024, 'zhTW', '這間宏偉的大使館證明贊達拉尊重大酋長的實力，他們理應感到畏懼。\n\n你現在想幹嘛？', '這間宏偉的大使館證明贊達拉尊重大酋長的實力，他們理應感到畏懼。\n\n你現在想幹嘛？', 28153),
(143023, 'zhTW', '這股濕氣讓我的骨頭都流汗了。我能為你做什麼？', '這股濕氣讓我的骨頭都流汗了。我能為你做什麼？', 28153),
(143022, 'zhTW', '我們在進步，大塊頭。有一天這些都會是我們的。', '', 28153),
(143021, 'zhTW', '我付錢給你們幹嘛的？來偷懶嗎？', '', 28153),
(143020, 'zhTW', '', '或許死亡才是風行者家族最拿手的本事。', 28153),
(143019, 'zhTW', '', '我也是。有時候會覺得自己好像死了兩次。第一次是大家以為我們在德拉諾犧牲，再來是陷入墮落那魯的暗影那一次。', 28153),
(143018, 'zhTW', '看著緬懷我們的紀念碑，我覺得很不安。', '', 28153),
(143017, 'zhTW', '', '圖拉揚，我該走了。我一定要再親眼看看我的家園…還要親耳聽到希瓦娜斯解釋她會當上大酋長的理由。', 28153),
(143016, 'zhTW', '你們都有各自該走的路。如果聖光要你們的命運交會，自然會交會，沒必要去左右命運的安排。', '', 28153),
(143015, 'zhTW', '你不需要走這一趟。你沒有必要去見她。', '', 28153),
(143014, 'zhTW', '', '親愛的，你最了解我了。', 28153),
(143013, 'zhTW', '你很不安。雖然你隱藏得很好…但我看得出來。', '', 28153),
(143012, 'zhTW', '我知道未來還要面對很多的挑戰，但不管發生什麼事…千萬別忘了我們對艾澤拉斯的責任！', '', 28153),
(143011, 'zhTW', '你的武器現在蘊藏驚人的能量…我從來沒見過這種東西！但是你要記住，所有的力量都伴隨著代價。', '', 28153),
(143010, 'zhTW', '你們辦到了！劍上的邪惡力量被封印了。艾澤拉斯的傷口還沒有復原…但是你們爭取到了寶貴的時間。', '', 28153),
(143009, 'zhTW', '團結一心，勇士們！為了艾澤拉斯！', '', 28153),
(143008, 'zhTW', '齊心協力…驅除黑暗泰坦劍刃造成的腐化能量！', '', 28153),
(143007, 'zhTW', '現在唯一能夠乘載這種力量的東西…就是你們手中的強大武器。', '', 28153),
(143006, 'zhTW', '薩格拉斯的劍汙染了這個世界的生命之血。', '', 28153),
(143005, 'zhTW', '到希利蘇斯來吧…趁時機未晚，這個世界需要我們！', '', 28153),
(143004, 'zhTW', '我知道情勢日益緊繃…但是我要再一次請大家團結起來。', '', 28153),
(143003, 'zhTW', '勇士們，你們萬眾一心，並肩把燃燒軍團趕出艾澤拉斯。', '', 28153),
(143002, 'zhTW', '又有一場風暴要來了。如果沒辦法治好艾澤拉斯…其它的一切都沒有意義。', '', 28153),
(143001, 'zhTW', '我不知道怎麼辦。可能沒有人知道。但是我們得繼續嘗試。', '', 28153),
(143000, 'zhTW', '從阿古斯回來之後，我就一直聽見艾澤拉斯痛苦哀號…', '', 28153),
(142999, 'zhTW', '勇士…在這種關頭能夠見到朋友真好。', '', 28153),
(142998, 'zhTW', '還沒有消息，公主。不過我們得到奎格瓦的線索了。', '', 28153),
(142997, 'zhTW', '', '…這就是托加的遭遇。部落的援軍有消息了嗎？', 28153),
(142996, 'zhTW', '我們快要完成了，$n。只要再走一下下。', '', 28153),
(142995, 'zhTW', '真不敢相信那些怪物讓托加開腸破肚…', '', 28153),
(142994, 'zhTW', '哎，托加死了，現在我回去之後，也沒有什麼好和其他人說的了。', '', 28153),
(142993, 'zhTW', '姬莎在哪裡？我以為她會在這裡為人指路…', '', 28153),
(142992, 'zhTW', '好吧，我會前往幽暗谷，看看一切會變得多瘋狂。', '', 28153),
(142991, 'zhTW', '嗯…既然如此，我想跟一整群的鮮血食人妖戰鬥會是個有趣的故事。好吧，我會去幽暗谷。', '', 28153),
(142990, 'zhTW', '你們全部都做了…什麼？我不想錯過這個故事，我會前往幽暗谷。', '', 28153),
(142989, 'zhTW', '好了，姬莎，我們去幽暗谷，把路上遇到的同胞一起帶過去。這位朋友會負責召集剩下的人。', '', 28153),
(142988, 'zhTW', '', '我要到幽暗谷去，托爾托人的事就交給你辦了。', 28153),
(142987, 'zhTW', '$n，去操作那些大砲！', '', 28153),
(142986, 'zhTW', '祝你好運，$p。我呢，要去梣谷試試自己的本領。為了部落！', '', 28153),
(142985, 'zhTW', '出去環遊世界的帕骷之息和瑞贊之爪總算歸來，幫助它們順利回家。', '', 28153),
(142984, 'zhTW', '船艦回來的時候，有黑暗跟著回來。我當時有股不祥的預感，從我肚子深處傳來。', '', 28153),
(142983, 'zhTW', '許多年來，帕骷之息一直是我的家。當她出航時，我的心也跟港口一樣空蕩蕩的。', '', 28153),
(142982, 'zhTW', '『雷霆勇者』安吉的吼聲讓你滿腔熱血。', '', 28153),
(142981, 'zhTW', '喂！快上船！船長說帕骷之息有麻煩了！', '', 28153),
(142980, 'zhTW', '', '指揮官，我們來幫忙了。我們會守住堤岸！', 28153),
(142979, 'zhTW', '', '我們快趕去堤岸，里德指揮官不喜歡等人！', 28153),
(142977, 'zhTW', '你不屬於這裡！', '', 28153),
(142976, 'zhTW', '你既愚蠢又膽小！', '', 28153),
(142975, 'zhTW', '我蔑視你，卑鄙的入侵者！', '', 28153),
(142974, 'zhTW', '快滾，你這個無賴！', '', 28153),
(142973, 'zhTW', '我會讓你痛不欲生！', '', 28153),
(142972, 'zhTW', '我會打到你大聲求饒！', '', 28153),
(142971, 'zhTW', '我會用這隻手拔掉你的牙齒！', '', 28153),
(142970, 'zhTW', '注意！', '', 28153),
(142969, 'zhTW', '', '我以威奎斯特家族之名，在這裡任命你們為燼火會的審判官！', 28153),
(142968, 'zhTW', '', '從今以後，你們就是象徵希望的燈塔。', 28153),
(142967, 'zhTW', '', '從今以後，你們就是斬妖除魔的劍刃。', 28153),
(142966, 'zhTW', '', '兄弟姐妹們，從今以後，你們就是驅走黑暗的火焰。', 28153),
(142965, 'zhTW', '', '啊，找到了。', 28153),
(142964, 'zhTW', '', '書裡有寫到向新成員說的話。讓我看一下…', 28153),
(142963, 'zhTW', '', '謝謝你把手下讓給我，元帥。這樣一來我們就是像樣的組織了！', 28153),
(142962, 'zhTW', '我已經等著覲見國王好幾天了。還以為他會對這裡的哥布林在幹什麼比較有興趣呢。', '', 28153),
(142961, 'zhTW', '我們在這裡有很多士兵，小姐。他們可以加入你成立的燼火會。', '', 28153),
(142960, 'zhTW', '', '元帥，我們找到可以用來對抗女巫的武器了。這種武器要讓身強體健的士兵來用。', 28153),
(142959, 'zhTW', '我永遠不會背叛羅亞，也不會背叛這座城市！', '', 28153),
(142958, 'zhTW', '我敬拜的是帕骷。鮮血魔法是禁忌！', '', 28153),
(142957, 'zhTW', '我告訴你的是實話。我不知道關於鮮血聖物的事！', '', 28153),
(142956, 'zhTW', '我是無辜的！請大發慈悲吧。', '', 28153),
(142955, 'zhTW', '我決不會走私鮮血聖物。鮮血魔法是邪惡的！', '', 28153),
(142954, 'zhTW', '我才沒看過什麼鮮血聖物！', '', 28153),
(142953, 'zhTW', '我不知道你在說什麼！', '', 28153),
(142952, 'zhTW', '我沒做任何錯事啊！', '', 28153),
(142951, 'zhTW', '別逼我再刺你一次…', '', 28153),
(142950, 'zhTW', '你把鮮血聖物賣給誰？', '', 28153),
(142949, 'zhTW', '你令我作噁，叛徒。', '', 28153),
(142948, 'zhTW', '我會讓你痛苦，波迪托。我們要拿你來殺雞儆猴。', '', 28153),
(142947, 'zhTW', '若你說實話，我保證會給你一個痛快的。', '', 28153),
(142946, 'zhTW', '你是最糟糕的人渣，波迪托。血魔法正在殺害我們的人民！', '', 28153),
(142945, 'zhTW', '我們知道你一直有走私鮮血聖物到我們的城市裡。', '', 28153),
(142944, 'zhTW', '告訴我們你是怎麼拿到鮮血聖物的，波迪托！', '', 28153),
(142943, 'zhTW', '這個人渣一直在走私鮮血聖物到我們的城市裡。\n\n他會認罪，然後我們會用他來殺雞儆猴。', '', 28153),
(142942, 'zhTW', '我什麼都沒做錯！告訴他們！', '', 28153),
(142941, 'zhTW', '(離開)', '(離開)', 28153),
(142940, 'zhTW', '<這具破破爛爛的屍體滿是血跡，幾乎認不出來是逃犯泰許楊比了。看來是附近迅猛龍的傑作。>', '<這具破破爛爛的屍體滿是血跡，幾乎認不出來是逃犯泰許楊比了。看來是附近迅猛龍的傑作。>', 28153),
(142939, 'zhTW', '我知道你是誰，你是莫巧巴。去沃魯敦吧，在那裡安穩地度過被放逐的餘生。', '我知道你是誰，你是莫巧巴。去沃魯敦吧，在那裡安穩地度過被放逐的餘生。', 28153),
(142938, 'zhTW', '你是誰？你想要什麼，嗯？', '', 28153),
(142937, 'zhTW', '很抱歉，但你已經因為犯罪而被流放到沃魯敦。', '很抱歉，但你已經因為犯罪而被流放到沃魯敦。', 28153),
(142936, 'zhTW', '噓！我要避開迅猛龍與祖拉金，返回祖達薩。', '', 28153),
(142935, 'zhTW', '', '以一個逃犯來說，你表現很好。', 28153),
(142934, 'zhTW', '', '既然我們已經控制整座監獄，鑰匙也拿到了，就開始回收艾澤萊晶岩、釋放人質吧。', 28153),
(142933, 'zhTW', '', '我看艾胥凡女士這下一定要再找個監督者了。', 28153),
(142932, 'zhTW', '別亂來！放火的，我就是說你。要是艾澤萊晶岩爆炸，我們就都死定了！', '', 28153),
(142931, 'zhTW', '做好準備！他們來了！', '', 28153),
(142930, 'zhTW', '', '在你去找監督者的時候，我們會佔領下層。', 28153),
(142929, 'zhTW', '', '做得好，看來你們已經控制住局勢了。', 28153),
(142928, 'zhTW', '只要綁走監督者的人質，我們就能拿到花不完的贖金了！', '', 28153),
(142927, 'zhTW', '大夥快點！把門砸開！', '', 28153),
(142926, 'zhTW', '', '你最好做到，否則接替你的人要做的第一件事就是看著你死！', 28153),
(142925, 'zhTW', '我很抱歉，艾胥凡女士。我的手下一定能讓這裡恢復秩序。', '', 28153),
(142924, 'zhTW', '', '寇格斯！好好解釋一下為什麼沒控制住底下，也沒把他們全部殺光？', 28153),
(142923, 'zhTW', '', '噁！你們爬過這堆東西逃出來的？那你們走前面！', 28153),
(142922, 'zhTW', '', '原來還有這頭怪物，怪不得監督者沒多派人巡邏這邊。還好你把牠殺掉了。', 28153),
(142921, 'zhTW', '', '我們對付附近的守衛，你想辦法到下水道閘門去。應該可以從那裡進入監獄才對。', 28153),
(142920, 'zhTW', '', '根據我們得到的情報，艾澤萊晶岩寶箱和人質集中區的鑰匙在監督者身上…就掛在脖子上。', 28153),
(142919, 'zhTW', '', '躲好！我們還沒被發現。', 28153),
(142918, 'zhTW', '一定要這樣嗎？', '', 28153),
(142917, 'zhTW', '有事嗎？', '', 28153),
(142916, 'zhTW', '準備上工。', '', 28153),
(142915, 'zhTW', '我們的兵營被摧毀了！', '', 28153),
(142914, 'zhTW', '我們需要援軍，才有辦法打贏。', '', 28153),
(142913, 'zhTW', '回去工作！', '', 28153),
(142912, 'zhTW', '兵營可不會自己蓋好！', '', 28153),
(142911, 'zhTW', '錘子揮大力一點！', '', 28153),
(142910, 'zhTW', '', '艾蘭里亞的表情明顯變得緊繃。', 28153),
(142909, 'zhTW', '你救了我一命！', '你救了我一命！', 28153),
(142908, 'zhTW', '我應該能自己去避難處了。感謝你。', '我應該能自己去避難處了。感謝你。', 28153),
(142907, 'zhTW', '他們的攻擊毫不留情。謝謝你的幫忙。', '他們的攻擊毫不留情。謝謝你的幫忙。', 28153),
(142906, 'zhTW', '我不會忘記你的英勇行為。', '我不會忘記你的英勇行為。', 28153),
(142905, 'zhTW', '我以為我會死在這裡！', '我以為我會死在這裡！', 28153),
(142904, 'zhTW', '我們的村莊需要像你這樣的英雄！', '我們的村莊需要像你這樣的英雄！', 28153),
(142903, 'zhTW', '為那些來不及獲救的人報仇。', '為那些來不及獲救的人報仇。', 28153),
(142902, 'zhTW', '這些納迦是怪物！', '這些納迦是怪物！', 28153),
(142901, 'zhTW', '這把刀會直接插進你胸口！', '', 28153),
(142900, 'zhTW', '入侵者從下水道過來了！', '', 28153),
(142898, 'zhTW', '這塊石頭吟唱著寂靜而強大的歌曲。只有一個人能聽到它的旋律，我們最好祈禱她永遠找不到進入這片海岸的方法。', '', 28153),
(142897, 'zhTW', '我看過所有該看的東西了。這塊石頭十分邪惡，必須摧毀它。', '', 28153),
(142894, 'zhTW', '我不覺得牠會乖乖把武器交給我們，所以你就從牠的屍體上搶過來吧。', '', 28153),
(142893, 'zhTW', '我看到下一個目標就在南邊。你最好動作快一點。', '', 28153),
(142892, 'zhTW', '可惜消滅這玩意反而給了庫爾提拉斯人時間重整旗鼓。', '', 28153),
(142891, 'zhTW', '黑暗女王一定會讚賞你的表現。', '', 28153),
(142890, 'zhTW', '', '我很樂意效勞，攝政王。勇士，我們銀月城見。', 28153),
(142889, 'zhTW', '好極了！莉雅德倫女士，請回到奧格瑪向大酋長報告這個好消息。', '', 28153),
(142888, 'zhTW', '', '我代表夜裔精靈接受這個提議。從今天起，蘇拉瑪爾要為部落而戰。', 28153),
(142887, 'zhTW', '首席秘法師，你們需要部落的力量。加入我們吧，銀月城的大門會永遠為你而開。', '', 28153),
(142886, 'zhTW', '', '蘇拉瑪爾永遠都是我們的家，但有些族人想要看看世界，在艾澤拉斯找回我們的位置。這樣一來，我們就需要盟友。', 28153),
(142885, 'zhTW', '', '我們從盟友那裡得到力量…但是並沒有迷失自我。', 28153),
(142884, 'zhTW', '', '正好相反。這場衝突讓我看到你對人民是多麼盡心盡力。看得出來部落讓你保留了傳統，這也是我們非常重視的事情。', 28153),
(142883, 'zhTW', '薩莉瑟拉，很抱歉讓你看到這種場面。事情會這樣發展真是出乎我預料。', '', 28153),
(142882, 'zhTW', '', '如你所願，攝政王。但這件事還沒結束。', 28153),
(142881, 'zhTW', '夠了！立刻離開，艾蘭里亞。不管是不是意外，你讓奎爾薩拉斯陷入危險都是不爭的事實。回暴風城去吧，銀月城再也不是你的家了。', '', 28153),
(142880, 'zhTW', '', '我不會讓自己在家鄉被當成犯人看待。', 28153),
(142879, 'zhTW', '守衛！抓住這個破壞者。', '', 28153),
(142878, 'zhTW', '太陽之井守住了。薩莉瑟拉，多虧有你的幫忙。還有你，勇士。', '', 28153),
(142877, 'zhTW', '這只是無謂的掙扎！我一定會拿走我要的東西。', '', 28153),
(142876, 'zhTW', '', '趁現在！把你的力量集中到我這裡！', 28153),
(142875, 'zhTW', '門打開了。很好…這就是我們需要的。', '', 28153),
(142874, 'zhTW', '', '你來指揮，我們提供支援。', 28153),
(142873, 'zhTW', '', '我可以關閉裂隙，但我需要幫手。', 28153),
(142872, 'zhTW', '某種東西想撕開裂隙進入這裡。要是讓它通過，太陽之井就不保了。', '', 28153),
(142871, 'zhTW', '開始施法吧，里凱。', '開始施法吧，里凱。', 28153),
(142870, 'zhTW', '潮水遲早會變換。風水輪流轉。', '', 28153),
(142869, 'zhTW', '你的控制正在減退！', '', 28153),
(142868, 'zhTW', '|TInterface\\Icons\\ABILITY_ROGUE_FANOFKNIVES:20|t%s正準備投擲|cFFFF0000|Hspell:257785|h[閃擊匕首]|h|r！快躲起來！', '', 28153),
(142867, 'zhTW', 'Bal\'a dash, malanore. (你好啊，旅行者。)', '', 28153),
(142866, 'zhTW', '每個人都有自己的路要走。', '', 28153),
(142865, 'zhTW', '我們的族人代表了嶄新的未來。', '', 28153),
(142864, 'zhTW', '真理不是理所當然的。', '', 28153),
(142863, 'zhTW', '宇宙之中充滿奧秘。', '', 28153),
(142862, 'zhTW', '全新的機會就在我們眼前。', '', 28153),
(142861, 'zhTW', '過去已成歷史，但未來還有無限可能。', '', 28153),
(142860, 'zhTW', 'Shorel\'aran. (再會。)', '', 28153),
(142859, 'zhTW', '我們的族人並不害怕暗影。', '', 28153),
(142858, 'zhTW', '真相不只一個。', '', 28153),
(142857, 'zhTW', '我們不會被低語控制。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142856, 'zhTW', '要控制每一股衝動。', '', 28153),
(142855, 'zhTW', '不要害怕力量，要控制力量。', '', 28153),
(142854, 'zhTW', '思考所有可能性。', '', 28153),
(142853, 'zhTW', '我不會被你的幼稚行為激怒的。', '', 28153),
(142852, 'zhTW', '「勿忘太陽之井？」拜託，聽都聽膩了。', '', 28153),
(142851, 'zhTW', '要是你腳下突然開了一道通往虛無的傳送門把你給吞進去，那絕對只是巧合。意外嘛，總是會發生。', '', 28153),
(142850, 'zhTW', '是啦，我的外貌因為引發瘋狂的強大力量而改變，然後大家就突然開始覺得我是「可疑分子」了。以貌取人是不對的。', '', 28153),
(142849, 'zhTW', '你在找什麼嗎？', '', 28153),
(142848, 'zhTW', '我這裡有來自遙遠國度的稀有商品。', '', 28153),
(142847, 'zhTW', '任何東西都有個價錢…就看你是不是真心想買。', '', 28153),
(142846, 'zhTW', '希望你對買到的東西很滿意。', '', 28153),
(142845, 'zhTW', '謝謝光臨。', '', 28153),
(142844, 'zhTW', '隨時回來看看。', '', 28153),
