(141208, 'zhTW', '你為什麼在哭？', '你為什麼在哭？', 28153),
(141207, 'zhTW', '是的－是的！信會很快很快送到！全速前進，美人！', '', 28153),
(141206, 'zhTW', '你可以把這封信送給在波拉勒斯的泰莉亞？', '你可以把這封信送給在波拉勒斯的泰莉亞？', 28153),
(141205, 'zhTW', '未完待續…\n\n感謝參與BlizzCon！', '', 28153),
(141204, 'zhTW', '來嘲笑我的？來嘲笑失落帝國的代言者？$b$b祖爾德拉克食人妖不是被天譴軍團帶走，就是被他們殺了。在他們垂死掙扎時，我的同類殺死了我們的羅亞，竊取了那些神的力量以對抗天譴軍團，然後再死去。$b$b現在，我在這跟這些贊達拉人的寵物差不多，只是他們用來向孩子展示的奇珍異獸。$b$b別煩我。', '', 28153),
(141202, 'zhTW', '', '被女巫會拒絕害我撕裂了靈魂，我就來奪取你的吧！', 28153),
(141201, 'zhTW', '', '嗯，有一個東西能有幫助…', 28153),
(141200, 'zhTW', '', '我們…我們原本可以一起擁有美好的未來，但是卻被奪走了。', 28153),
(141199, 'zhTW', '', '當他們來到門前，我早該了解…他們出現時總是沒有好事。\n\n我那時就知道，夢想已經結束了。', 28153),
(141198, 'zhTW', '', '這打擊…太沉重…\n\n我沒想到傷痛會這麼沉重…', 28153),
(141197, 'zhTW', '喂！你！在這裡！', '', 28153),
(141196, 'zhTW', '<女人在哭泣。你伸出手去安慰她。>', '<女人在哭泣。你伸出手去安慰她。>', 28153),
(141194, 'zhTW', '確定要傳送到阿塔達薩地城？', '確定要傳送到阿塔達薩地城？', 28153),
(141193, 'zhTW', '確定要傳送到自由港地城？', '確定要傳送到自由港地城？', 28153),
(141192, 'zhTW', '傳送到阿塔達薩地城', '傳送到阿塔達薩', 28153),
(141191, 'zhTW', '傳送到自由港地城', '傳送至自由港', 28153),
(141190, 'zhTW', '歡迎參加BlizzCon 2017！若要傳送到所屬陣營的地城，請按一下下方！', '歡迎參加BlizzCon 2017！若要傳送到所屬陣營的地城，請按一下下方！', 28153),
(141189, 'zhTW', '', '滾！證明你自己還有點用再回來找我！', 28153),
(141188, 'zhTW', '對不起！我也想幫助他，可是我不會打架！', '', 28153),
(141187, 'zhTW', '', '你們擋不住的！祖達薩沒有希望，你也一樣。古翰甦醒了！古翰再起了！', 28153),
(141186, 'zhTW', '', '竟敢殺死我們的羅亞…我要殺了你…折磨你…搾乾你的血！', 28153),
(141185, 'zhTW', '', '希爾雷克侍奉古翰！我要你們付出代價。祖達薩滅亡之後…下一個就是部落！', 28153),
(141184, 'zhTW', '<拉奇昂低下頭表示敬意。>', '', 28153),
(141183, 'zhTW', '我們出發吧。', '我們出發吧。', 28153),
(141182, 'zhTW', '<拉奇昂低下頭表示敬意。>', '', 28153),
(141180, 'zhTW', '再見了，笨蛋！', '', 28153),
(141178, 'zhTW', '我想我應該暫時躲起來…', '', 28153),
(141177, 'zhTW', '真遺憾，那隻烏龜沒有自己來。他的殼應該可以賣個好價錢。', '', 28153),
(141176, 'zhTW', '我要創建一個牛頭人惡魔獵人組織，名字就叫「伊利達哞」。', '', 28153),
(141175, 'zhTW', '梵迪卡爾的速度非常快，因為它是用「光」速飛行。', '', 28153),
(141174, 'zhTW', '', '高嶺永存！領子太低的就給我滾出去。', 28153),
(141173, 'zhTW', '', '你看過預言者費倫發明的新舞步嗎？叫做麥克艾瑞漫步。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141172, 'zhTW', '', '哼。一定似<嗝！>夾著尾巴落跑了。', 28153),
(141171, 'zhTW', '', '那個膽小的人渣在哪裡？竟然敢侮辱<嗝！>鐵潮劫掠者？！', 28153),
(141170, 'zhTW', '', '什麼？！<嗝！>看我教訓他們，竟敢批評我的隊員！', 28153),
(141169, 'zhTW', '呀！那些腦袋泡水的無賴正在玷汙鐵潮劫掠者的盛名！就在那，在那建築後面！', '呀！那些腦袋泡水的無賴正在玷汙鐵潮劫掠者的盛名！就在那，在那建築後面！', 28153),
(141168, 'zhTW', '什麼？那個老女人早該放棄她的靈魂然後死去了！去，殺了她最好。我要拿屬於我的東西。', '', 28153),
(141167, 'zhTW', '', '<嗝>$B$B嗯？你想幹嘛？', 28153),
(141166, 'zhTW', '你說你做了什麼？這...這可是禁忌…怎麼可以殺害羅亞！', '', 28153),
(141165, 'zhTW', '喬崇加還活著，但是羅亞希爾雷克…', '喬崇加還活著，但是羅亞希爾雷克…', 28153),
(141164, 'zhTW', '你在這兒！我正要開始擔心呢，發生什麼事了？', '', 28153),
(141163, 'zhTW', '我表面上是高貴的德萊尼…私底下是狂野的埃雷達爾。', '', 28153),
(141162, 'zhTW', '|TInterface\\ICONS\\ABILITY_VEHICLE_SIEGEENGINECANNON.BLP:20|t |cFFF00000|Hspell:257585|h[火砲彈幕]|h|r即將來襲！', '|TInterface\\ICONS\\ABILITY_VEHICLE_SIEGEENGINECANNON.BLP:20|t |cFFF00000|Hspell:257585|h[火砲彈幕]|h|r即將來襲！', 28153),
(141161, 'zhTW', '<回想薩格拉斯遭到囚禁的情景>', '<憶起薩格拉斯的囚禁>', 28153),
(141160, 'zhTW', '<回憶萬神殿寶座發生的事情>', '<回想你們抵達萬神殿寶座的情景>', 28153),
(141159, 'zhTW', '我能帶來光明…與激情。', '', 28153),
(141158, 'zhTW', '靈行者？！', '', 28153),
(141157, 'zhTW', '你說我們臉上為什麼會長觸手？我們臉上才沒有長觸手！要是有，就表示我們德萊尼是虛無的使者，表面上先贏得你的信任，然後暗中入侵你們，最後毀掉你們。你的意思應該不是這樣吧？是吧？', '', 28153),
(141156, 'zhTW', '要是我身上的刺青有點黯淡，是因為我昨天晚上忘記幫自己充電了。', '', 28153),
(141155, 'zhTW', '|TInterface\\Icons\\ABILITY_DEVOUR.BLP:20|t瑞贊使用他的|cFFFF0000|Hspell:255371|h[恐怖面容]|h|r，快躲起來！', '|TInterface\\Icons\\ABILITY_DEVOUR.BLP:20|t瑞贊使用他的|cFFFF0000|Hspell:255371|h[恐怖面容]|h|r，快躲起來！', 28153),
(141154, 'zhTW', '', '主人…請賜我力量…', 28153),
(141153, 'zhTW', '', '我會用石頭砸死你！你看我敢不敢！', 28153),
(141152, 'zhTW', '', '走開，你們這些臭穴居怪！', 28153),
(141151, 'zhTW', '<目睹聖物的祝福。>', '<目睹聖物的祝福。>', 28153),
(141150, 'zhTW', '<目睹風行者之所見。>', '<目睹風行者之所見。>', 28153),
(141149, 'zhTW', '', '別讓幼龍接近拉奇昂！', 28153),
(141148, 'zhTW', '<目睹聖光審判。>', '<目睹聖光審判。>', 28153),
(141147, 'zhTW', '', '不好意思！你能來這裡幫我一下嗎？謝謝！', 28153),
(141146, 'zhTW', '<目睹三傑議會的決定。>', '<目睹三傑議會的決定。>', 28153),
(141145, 'zhTW', '<目睹逃離阿古斯。>', '<目睹逃離阿古斯。>', 28153),
(141144, 'zhTW', '', '別讓那些幼獸逃走！', 28153),
(141143, 'zhTW', '喂！在這裡！喂！喂喂喂！', '', 28153),
(141142, 'zhTW', '受傷的翼手龍停下來療傷。', '', 28153),
(141141, 'zhTW', '<目睹阿格拉瑪的到來。>', '<目睹阿格拉瑪的到來。>', 28153),
(141140, 'zhTW', '', '看哪！完成了！噢，真是好美、好致命！', 28153),
(141139, 'zhTW', '', '這麼多…力量！啊哈哈哈！', 28153),
(141138, 'zhTW', '真有趣…所以他們用這些魔塔來旅行。今天真是有教育意義的一天。', '', 28153),
(141137, 'zhTW', '呃，老大？$n？我想我們有新的蛇患。', '', 28153),
(141136, 'zhTW', '<拉奇昂滿懷自豪，抬起了頭。>', '', 28153),
(141135, 'zhTW', '', '雖然我是光鑄戰士，但我也很擅長在黑暗裡做的事喔。', 28153),
(141134, 'zhTW', '', '我的眼睛、刺青、護甲，到處都會發光喔。告訴我，你想要先看我點亮哪裡？', 28153),
(141133, 'zhTW', '', '就算不是天角部族，一樣能樂到飛天。', 28153),
(141132, 'zhTW', '', '嗯，生活在海拔很高的地方，讓我的耐力變得很驚人。我來為你示範一下…', 28153),
(141131, 'zhTW', '', '艾瑟‧智水我認識。她走路速度其實很快，只是喜歡故意捉弄旅行者。', 28153),
(141130, 'zhTW', '無法安息的骸骨變成復活的迅猛龍了！', '無法安息的骸骨變成復活的迅猛龍了！', 28153),
(141129, 'zhTW', '在附近的古老骸骨開始騷動。', '在附近的古老骸骨開始騷動。', 28153),
(141128, 'zhTW', '破碎群島上方的達拉然', '破碎群島上方的達拉然', 28153),
(141127, 'zhTW', '公主是贊達拉的未來。一定要保護她。', '公主是贊達拉的未來。一定要保護她。', 28153),
(141126, 'zhTW', '大主教圖拉揚命我前往艾澤拉斯的時候，我很不願意離開他的身邊。我認為別人比我更適合這項任務。\n\n但是現在，我明白他為什麼要這麼做了。他想讓我看看這個他和艾蘭里亞女士付出一切也要保護的地方。\n\n雖然這場仗結束了，但是未來還有更多的仗要打。雖然我們打倒了燃燒軍團，但並不代表所有的惡魔都已經束手就擒。\n\n<洛斯拉賽恩握緊拳頭，露出微笑。>\n\n它們遲早會投降的。', '', 28153),
(141125, 'zhTW', '我們遵從公主的命令。', '我們遵從公主的命令。', 28153),
(141124, 'zhTW', '你找我有什麼事？', '你找我有什麼事？', 28153),
(141123, 'zhTW', '那些樹活過來了！拿起你的斧頭！', '', 28153),
(141122, 'zhTW', '特帕托！', '', 28153),
(141121, 'zhTW', '', '試煉開始。願聖光與你們同在。', 28153),
(141120, 'zhTW', '', '你的選擇很不尋常，但嚴格說來沒有違反規則。我們的勇士在面對挑戰時從不退縮。', 28153),
(141119, 'zhTW', '那好吧！特帕托就選…這個小傢伙！', '', 28153),
(141118, 'zhTW', '', '上一個單槍匹馬的新兵，回來的時候精神都崩潰了。去選個副手，不然就回兵營。', 28153),
(141117, 'zhTW', '特帕托不需要別人幫他！', '', 28153),
(141116, 'zhTW', '', '特帕托，我們討論過好幾次了，每個新兵都要有一個副手協助，你的副手在哪裡？', 28153),
(141115, 'zhTW', '', '但如果你真的準備好了，就上前來接受你的命運。', 28153),
(141114, 'zhTW', '', '要是你心裡還有一絲懷疑，那就回頭吧。這樣是智慧的表現，不是懦弱。', 28153),
(141113, 'zhTW', '', '許多英勇的德萊尼都經歷過這場試煉，卻身心重創…甚至更糟。', 28153),
(141112, 'zhTW', '', '你們會被迫直視內心深處，面對真正的自己。或者你想成為的自己。', 28153),
(141111, 'zhTW', '', '還剩最後一個試煉，這也是最艱鉅的試煉。', 28153),
(141110, 'zhTW', '', '各位戰友，你們通過了這場試煉，這證明了你們心中閃耀著熾熱的聖光。', 28153),
(141109, 'zhTW', '<看來穴居怪已經把它掏空了。>', '', 28153),
(141108, 'zhTW', '<繼續尋找孩子們>', '<繼續尋找孩子們>', 28153),
(141107, 'zhTW', '我相信$n對此比你有經驗多了，英格麗。', '', 28153),
(141106, 'zhTW', '', '不公平，這是我想做的事！', 28153),
(141105, 'zhTW', '當初梵迪卡爾在這場戰役中登場的時候還沒有經過完整測試，但她還是讓我們安全回家了。\n\n過去所做的那些升級都是值得的，對吧？\n\n別回答這個問題，我聽到會傷心的。\n\n就跟你說沒有人在乎戰艦工程師的貢獻。', '', 28153),
(141104, 'zhTW', '我找到他們了！終於找到他們了。\n\n<阿拉特的笑容消失，表情突然有點猶疑。>\n\n這兩個人賦予我生命…卻在我成長的過程中幾乎完全缺席。我知道他們是為了我才不停奮戰，做出那麼多犧牲。可是…\n\n我們不可能馬上就變成幸福快樂的家庭，他們幾乎對我一無所知，我也只從傳說中聽過他們的故事。了解彼此需要時間，創傷也才能復原。\n\n不過至少接下來我們會一起面對。', '', 28153),
(141103, 'zhTW', '', '艾蘭里亞變了，她能操縱我無法完全理解的力量，可是我知道她的內心並沒有變，她還是我親愛的姊姊。\n\n希瓦娜斯的遭遇讓她非常難過。要處理這些事…就必須見面談。\n\n我們風行者三姊妹必須見一面，要這麼做的話，只有一個地點可行。', 28153),
(141102, 'zhTW', '', '你怎麼還在這裡？\n\n<依莎娜疑惑地看著你。>\n\n結束了。回家吧。\n\n<依莎娜對你揮揮手。>\n\n快走吧！', 28153),
(141101, 'zhTW', '這場對抗燃燒軍團的戰役實在好漫長，大家都疲憊不堪。我們踏遍無數個世界追擊它們，甚至進入扭曲虛空，最後終於贏得這場勝利。\n\n我累了，$n。可是我們還不能休息。\n\n麥格尼看到的末日幻象讓我打從心底感到恐懼。只剩下最後一個泰坦了，絕對不能讓它有什麼萬一，勇士。', '', 28153),
(141100, 'zhTW', '', '看哪！完成了！噢，真是好美、好致命！', 28153),
(141099, 'zhTW', '我在無數個夜晚輾轉難眠，夢想能回到阿古斯，看看我的故鄉變成了什麼樣子，渴望能拯救它。\n\n<費倫沉默了好一陣子。>\n\n過去的一切無法重來，但至少我們打贏了這場仗。\n\n我不確定接下來會如何，但是我不會被動等待幻象的指引。我要盡全力輔佐安杜因國王，確保他為接下來要面對的威脅做好準備。', '', 28153),
(141098, 'zhTW', '', '一想到要跟阿拉特和圖拉揚一起回到艾澤拉斯我就雀躍不已。終於又能見到故鄉的林地了。\n\n可是…\n\n凡蕾莎跟我說了希瓦娜斯的遭遇。雖然我對去見她感到恐懼，可是我一定要親眼看看她現在的樣子。\n\n她還是我的妹妹嗎？還是已經成為聖光所鄙棄的怪物？\n\n沒錯，我也轉變了。我現在能使用的力量也同樣讓旁人懷疑我的忠誠。\n\n<艾蘭里亞深吸一口氣。>\n\n我要沉著冷靜。還有很多事情需要思考…', 28153),
(141097, 'zhTW', '終於，這場仗總算打完了。\n\n經歷過無數場征戰，犧牲這麼慘重，沒想到我還可以活著看到這一天。\n\n<圖拉揚嘆了口氣，熱淚湧上他的雙眼。>\n\n我們就要返回我離開了一千年的家園。\n\n我過去的人生已經不復存在。現在我該從頭開始，跟兒子建立感情，畢竟這一切都是為了他。', '', 28153),
(141096, 'zhTW', '…做得非常好，英格麗，完全沒有造成不安。', '', 28153),
(141095, 'zhTW', '我已經在辦了。', '', 28153),
(141094, 'zhTW', '', '呃…老大？我想我們會需要盾牌抵擋打下來的閃電！', 28153),
(141093, 'zhTW', '', '噢，我等著做這件事已經很久了，退後！', 28153),
(141092, 'zhTW', '你們誰再說我是會走路的水晶燈，我就要誰好看…', '', 28153),
(141091, 'zhTW', '', '我通常對卓格巴不感興趣，可是當我看到他們在卜魯健身房運動的時候…啊，這樣比喻好了，我的大地深處湧上了潮水。', 28153),
(141090, 'zhTW', '英格麗，我將要用自己的魔法強化喚天者寶石，後退一點。', '英格麗，我將要用自己的魔法強化喚天者寶石，後退一點。', 28153),
(141089, 'zhTW', '我需要你幫忙強化喚天者寶石。', '我需要你幫忙強化喚天者寶石。', 28153),
(141088, 'zhTW', '我真不敢相信…$n！在這裡！', '', 28153),
(141087, 'zhTW', '', '嘻嘻…我就知道我們會得救！嗯，或許我只是超努力禱告。在這裡！', 28153),
(141086, 'zhTW', '', '你！$n！我聽說過你的好多事，帶我離開這裡！', 28153),
(141085, 'zhTW', '這是做夢吧，$n真的在這裡，試著要救我。', '', 28153),
(141084, 'zhTW', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t 你在|cFFF00000|Hspell:257459|h[狠狠盯上]|h|r！', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t 你在|cFFF00000|Hspell:257459|h[狠狠盯上]|h|r！', 28153),
(141083, 'zhTW', '勝利比你所想的還要近。', '', 28153),
(141082, 'zhTW', '她迴盪的低語最是響亮。', '', 28153),
(141081, 'zhTW', '燃燒者保持平衡。現在失落了…失落了。', '', 28153),
(141080, 'zhTW', '這一切都是你的驕傲造成的。', '', 28153),
(141079, 'zhTW', '夜幕低垂。她的歌聲會戛然而止。', '', 28153),
(141078, 'zhTW', '接受你的命運。一切都會沉沒。', '', 28153),
(141077, 'zhTW', '裂縫在擴大…', '', 28153),
(141075, 'zhTW', '$n喚醒了一堆骸骨！', '$n喚醒了一堆骸骨！', 28153),
(141074, 'zhTW', '哈囉！如果你不小心弄丟哪個夥伴，我們可以幫你找回來。', '', 28153),
(141073, 'zhTW', '我這輩子都在照顧動物。如果你願意的話，我仍可以幫忙處理。', '', 28153),
(141072, 'zhTW', '我們盡快趕來了。', '', 28153),
(141071, 'zhTW', '', '把荒疫準備好！讓敵人的軍隊嚐嚐我們的厲害！', 28153),
(141070, 'zhTW', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_SHADOW:20|t你受到了|cFFFF0000|Hspell:251570|h[靈魂炸彈]|h|r的影響！', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_SHADOW:20|t你受到了|cFFFF0000|Hspell:251570|h[靈魂炸彈]|h|r的影響！', 28153),
(141069, 'zhTW', '|TInterface\\Icons\\INV_ELEMENTAL_MOTE_SHADOW01:20|t你受到了|cFFFF0000|Hspell:250669|h[靈魂驟發]|h|r的影響！', '|TInterface\\Icons\\INV_ELEMENTAL_MOTE_SHADOW01:20|t你受到了|cFFFF0000|Hspell:250669|h[靈魂驟發]|h|r的影響！', 28153),
(141068, 'zhTW', '', '但是你的命運要由自己掌控，我會教你怎麼去抗拒低語，你就不會被暗影控制，反而可以控制暗影。', 28153),
(141067, 'zhTW', '', '德贊恩想剝奪你們的意志，想讓你變得跟他一樣，成為只想滿足飢渴的奴隸。', 28153),
(141066, 'zhTW', '艾蘭里亞…勇士…我的族人自由了，但是我們已經…改變了。那些聲音…', '', 28153),
(141065, 'zhTW', '', '不，這些人不會聽你的，他們可沒有迷失。', 28153),
(141064, 'zhTW', '不…', '', 28153),
(141063, 'zhTW', '', '我看穿了你的謊言，德贊恩。其他人也不會受騙的。', 28153),
(141062, 'zhTW', '為什麼要抗拒呢？你和輝煌榮耀的命運只差一步了。', '', 28153),
(141061, 'zhTW', '', '這個虛無風暴是某種通道…一定要把它封起來。', 28153),
(141060, 'zhTW', '', '以太族，我不會向你的主人屈服…也不會讓他們控制我的同胞！', 28153),
(141059, 'zhTW', '風行者，不管那個叛徒跟你說了什麼，我們都是站在同一邊的…', '', 28153),
(141058, 'zhTW', '', '等等、別急…不要第一次約會就想碰人家的…角。', 28153),
(141057, 'zhTW', '名字不重要。應該問的是…你們會變成什麼樣子吧？', '', 28153),
(141056, 'zhTW', '', '跟我來，一定要阻止這件事，不能讓我的族人受到改造！', 28153),
(141055, 'zhTW', '呃啊啊！我感覺到這股力量…在呼喚我…改造我…', '', 28153),
(141054, 'zhTW', '', '奧姆里克，抵抗那些低語！他所說的「禮物」只會讓你變成奴隸。', 28153),
(141053, 'zhTW', '', '快出來！你是誰？', 28153),
(141052, 'zhTW', '啊…我所看到的未來終於成真了。謝謝你打開了這條路。', '', 28153),
(141051, 'zhTW', '', '他說我的眼睛「像牛奶一樣」。真是有夠掃興，爛死了…', 28153),
(141050, 'zhTW', '這副鹿角，比一般牛頭人的牛角更硬更挺喔！要不要摸摸看？', '', 28153),
(141049, 'zhTW', '哈哈！見證我的力量吧，凡人，要知道，你也可以擁有一部份這種力量…', '', 28153),
(141048, 'zhTW', '前面的區域很危險，調頭！', '前面的區域很危險，調頭！', 28153),
(141047, 'zhTW', '', '你讓祖爾輕易擊敗我們的部隊。現在他們完全不受阻擋，直接進軍阿塔達薩。你有應變的計畫嗎，我的王啊？', 28153),
(141046, 'zhTW', '', '拉斯塔哈，你慢慢處理這件事情好了。', 28153),
(141045, 'zhTW', '祖爾究竟是不是個好策劃者，或只是個好的先知，這點很難說。無論如何，他每一步都領先我們。$b$b他想用我們第一個神王達薩的骸骨取代我。$b$b我很想再次看到食人妖統治世界，但祖爾變成的這種黑暗異教徒，不是我願意承擔的代價。', '', 28153),
(141044, 'zhTW', '', '我要對你做的事，就連老伯昂撒姆第都會覺得噁心。', 28153),
(141043, 'zhTW', '', '我會對你的靈魂做出可怕的事。', 28153),
(141042, 'zhTW', '', '你的苦難不會隨著死亡結束的。', 28153),
(141041, 'zhTW', '', '首先，我要殺了你，然後，我要對你做實驗。', 28153),
(141040, 'zhTW', '', '入侵我的神殿？噢，你將為此而死。', 28153),
(141039, 'zhTW', '', '拉斯塔哈在這裡？很好。帶我去見這個後輩。', 28153),
(141038, 'zhTW', '我只是想幫個忙。', '', 28153),
(141037, 'zhTW', '這個世界會充滿即將到來的美麗。', '', 28153),
(141036, 'zhTW', '哼，看看你！強大的英雄是吧…哈！', '', 28153),
(141035, 'zhTW', '', '你知道要怎麼讓女人愛上你嗎？按摩她的足蹄就對了。相信我，屢試不爽。', 28153),
(141034, 'zhTW', '', '牛頭人是最厲害的戰略師，因為他們都滿肚子計哞。', 28153),
(141033, 'zhTW', '', '噗嚕嚕，這裡好冷。想不想來點冰淇淋？', 28153),
(141032, 'zhTW', '', '為什麼河鬃牛頭人總是那麼冷靜？因為他們心如止水啊。', 28153),
(141031, 'zhTW', '', '高嶺牛頭人吃了巧克力會變成什麼？牛～奶巧克力！', 28153),
(141030, 'zhTW', '你剛剛是不是想把大衣掛在我頭頂的角上？你以為我是衣帽架嗎？', '', 28153),
(141029, 'zhTW', '什麼東西比一隻卓格巴還要臭？兩隻卓格巴。那什麼東西比兩隻卓格巴還要臭呢？沒有人知道，那種臭味會把人活活熏死。', '', 28153),
(141028, 'zhTW', '牛頭人、揚古和坦卡走進一間酒吧。我不是在講笑話，這是我的家族聚會。', '', 28153),
(141027, 'zhTW', '哈！我朋友曾經叫某個全身紫裝的冒險者把魚給踢回河裡！啊，那個人…該不會就是你吧？', '', 28153),
(141026, 'zhTW', '就算我只是個普通的高嶺牛頭人，至少還不用去挖便便找戰利品。', '', 28153),
(141025, 'zhTW', '我們來玩個遊戲。只要聽到鷹身人大喊「塵歸塵，土歸土！」就乾一杯。', '', 28153),
(141024, 'zhTW', '為什麼那兩個德萊尼老是來問我會不會迷路？', '', 28153),
(141023, 'zhTW', '', '尺寸不是重點，重點是那根圖騰要怎麼動。', 28153),
(141022, 'zhTW', '', '你的眼睛在看哪裡啊？', 28153),
(141020, 'zhTW', '', '嗯…想不想跟我撞撞角？', 28153),
(141018, 'zhTW', '你一定是鍊金師，才會讓我的心起了強烈的化學反應。', '', 28153),
(141017, 'zhTW', '你可以再用力一點，我的皮很厚的。', '', 28153),
(141016, 'zhTW', '大地的深處充滿…有隱私的地方。', '', 28153),
(141015, 'zhTW', '我的圖騰很有力，整晚動不停。', '', 28153),
(141014, 'zhTW', '相信我…探索神秘的深處我最會了。', '', 28153),
(141013, 'zhTW', '你看過梵迪卡爾上面的宿舍區嗎？就我們兩個，我帶你去參觀一下。', '', 28153),
(141012, 'zhTW', '', '你一定要來眾星之廷參加我們的派對，我還沒見過比你更需要戴面具的人。', 28153),
(141011, 'zhTW', '', '夜精靈？根本就是鄉下精靈吧！他們在樹上生活，睡在獸穴裡…頭上還會長角。他們絕對無法適應城市的生活。', 28153),
(141010, 'zhTW', '', '我遇過一個卡多雷，那傢伙說要是我能回到一萬年前，我的穿衣風格就走在時代的尖端了。噢！夜精靈還真是會損人啊！', 28153),
(141009, 'zhTW', '', '經過這麼多年，泰蘭妲還是那麼漂亮。你知道她有沒有對象嗎？', 28153),
(141008, 'zhTW', '', '想來杯秘能酒嗎？是我親自用腳踩的喔。', 28153),
(141007, 'zhTW', '', '玫瑰花紅豔豔，我的家真美麗。那是偽裝嗎？是誰在那裡？', 28153),
(141006, 'zhTW', '', '是幻象！你在暗示什麼？', 28153),
(141005, 'zhTW', '說真的，把一隻憤怒的大恐龍關進動物園，絕對不會有好下場。', '', 28153),
(141004, 'zhTW', '我不懂眾星之廷這個名字哪來的，我常去那裡逛，可是一個大明星也沒見過。', '', 28153),
(141003, 'zhTW', '在我那個年代，精靈就只有一種。哪有分這麼多。', '', 28153),
(141002, 'zhTW', '這就是我。我愛喝秘能酒…而且懂的事情不少。', '', 28153),
(141001, 'zhTW', '我叫洛伊，我對魔法上癮。', '', 28153),
(141000, 'zhTW', '為什麼大家都要我講那句話啊？呃，好吧：「是幻象！你在隱藏什麼？」', '', 28153),
(140999, 'zhTW', '說實話，大多數的時候都沒有不對勁。', '', 28153),
(140998, 'zhTW', '', '我身上的每個地方都隨你探索。', 28153),
(140997, 'zhTW', '', '我跟這群男人困在同一個屏障裡上萬年，早就想換換口味了。', 28153),
(140996, 'zhTW', '', '讓我看你的地脈，你就可以看我的。', 28153),
(140995, 'zhTW', '', '別管活化和引爆了，我們直接開始複製吧？', 28153),
(140994, 'zhTW', '', '我的夜井會讓所有男人都離不開。', 28153),
(140992, 'zhTW', '', '這絕對不是幻象。你所看到的一切…都非常真實。', 28153),
(140991, 'zhTW', '', '你褲袋裡的東西是幻象？還是你真的很高興見到我？', 28153),
(140990, 'zhTW', '你是奧肯多爾的果實嗎？因為你看起來好鮮嫩可口。', '', 28153),
(140989, 'zhTW', '眾星一致認為，你…辣到讓人受不了。', '', 28153),
(140988, 'zhTW', '我敢說…我們在夜裡一定會情投意合。', '', 28153),
(140987, 'zhTW', '我想我是夜落…進你懷裡了。', '', 28153),
(140986, 'zhTW', '嗯…我想深入你的地脈。', '', 28153),
(140985, 'zhTW', '你找到通往我內心的幽暗地道了。', '', 28153),
(140984, 'zhTW', '你一定也會魔法，因為你把其他人都變不見，只剩我們兩個了。', '', 28153),
(140983, 'zhTW', '你的身體就像一池充滿魔力的泉水，讓我怎麼也離不開。', '', 28153),
(140982, 'zhTW', '', '一千年來，我唯一見過的人類就是圖拉揚。我還以為所有人類都像他一樣白髮蒼蒼而且滿身傷疤。', 28153),
(140981, 'zhTW', '', '身為光鑄戰士的壞處就是，每次自拍都會曝光過度。', 28153),
(140980, 'zhTW', '', '梵迪卡爾「暫時」還沒有墜毀…但是根據經驗，這只是遲早的事。', 28153),
(140979, 'zhTW', '', '建議你不要光著蹄子在梵迪卡爾上面走動。我們偶爾還是會踩到沒掃乾淨的水晶裂片。', 28153),
(140978, 'zhTW', '', '腳趾頭有什麼好，修趾甲的時候蹄子才方便。', 28153),
(140977, 'zhTW', '', 'Archenon poros? 我看是阿克農‧吃螺絲才對。', 28153),
(140976, 'zhTW', '', '沒有，我的尾巴上面才沒有什麼發光的刺青。', 28153),
(140975, 'zhTW', '我為艾爾而…<咳咳>阿古斯，我為阿古斯而生！', '', 28153),
(140974, 'zhTW', '在船上待了這麼久，能再踏上平穩的地面真好。船上凹凸不平的，我的足蹄簡直要痛死了。', '', 28153),
(140973, 'zhTW', '你的世界好奇怪，為什麼會有練功夫的熊？這在阿古斯叫做馬戲團。', '', 28153),
(140972, 'zhTW', '我原本以為我身上的刺青是那魯語的「聖光捍衛者」，後來才發現它的意思其實是「發光的山羊」。', '', 28153),
(140971, 'zhTW', '', '不知道該做什麼的話…會發光的地方都可以摸。', 28153),
(140970, 'zhTW', '你讓我的光柱更亮眼了…希望你能受得了。', '', 28153),
(140969, 'zhTW', '她的鮮血會讓他更強大。你的血也是。', '', 28153),
(140968, 'zhTW', '|TINTERFACE\\ICONS\\SPELL_ARCANE_MINDMASTERY.BLP:20|t你的心智快要向|cFFFF0000|Hspell:244172|h[精神衝擊]|h|r屈服了！', '|TINTERFACE\\ICONS\\SPELL_ARCANE_MINDMASTERY.BLP:20|t你的心智快要向|cFFFF0000|Hspell:244172|h[精神衝擊]|h|r屈服了！', 28153),
(140967, 'zhTW', '我們得離開，我們不該待在這裡。', '我們得離開，我們不該待在這裡。', 28153),
(140966, 'zhTW', '', '那些該死的祖達薩懦夫，居然沒早點制止這個威脅！我父親還認為這會「自己消失」，真是太傻了。\n\n這一切不會因為我們殺死艾提娜就結束。狀況遠比我預期還要糟糕。', 28153),
(140965, 'zhTW', '我的任務…結束…', '', 28153),
(140964, 'zhTW', '女王，請原諒我。', '', 28153),
(140963, 'zhTW', '女王…我失敗了！', '', 28153),
(140962, 'zhTW', '任何人都不能靠近我的女王！', '', 28153),
(140961, 'zhTW', '絕對不能讓你打掃女王休息！', '', 28153),
(140960, 'zhTW', '我會永遠守護女王！滾！', '', 28153),
(140959, 'zhTW', '', '羅亞啊…不！原來這才是鮮血食人妖真正的實力。噢，父王…你為什麼一直不肯面對？！', 28153),
(140958, 'zhTW', '', '做好準備，前方不知道還會有什麼危險。', 28153),
(140957, 'zhTW', '<還是不要惹是生非才好。>', '', 28153),
(140954, 'zhTW', '我通常喜歡開著燈…不過我本身也會發光就是了。', '', 28153),
(140953, 'zhTW', '', '到我的船上來，我們來扭曲一下虛空吧。', 28153),
(140952, 'zhTW', '', '你一定是那魯下凡…不然怎麼會有天使般的身材？', 28153),
(140950, 'zhTW', '', '她一定就在這附近。我是絕對不會放棄的，只差一步就能殺掉這些怪物的首領了。', 28153),
(140949, 'zhTW', '', '你別想逃，艾提娜，我才不怕你的什麼黑暗巫毒魔法！', 28153),
(140945, 'zhTW', '伊洛德斯將軍離開他的指揮艙了！', '伊洛德斯將軍離開他的指揮艙了！', 28153),
(140944, 'zhTW', '首席工程師伊胥卡離開他的指揮艙了！', '首席工程師伊胥卡離開他的指揮艙了！', 28153),
(140942, 'zhTW', '斯維拉克斯上將離開她的指揮艙了！', '斯維拉克斯上將離開她的指揮艙了！', 28153),
(140939, 'zhTW', '', '你面對的是古翰的力量！別以為能阻止我們，我讓你看看吧…', 28153),
(140938, 'zhTW', '', '可憐的塔蘭姬！我們可是強大羅亞的子孫。你絕對贏不了的，孩子！', 28153),
(140937, 'zhTW', '', '不要以為你能嚇倒我，艾提娜。我會先打倒你，接著就去把你侍奉的主人也收拾掉！', 28153),
(140936, 'zhTW', '', '我最好先躲起來，等時機一到，我會現身，和你聯手殺掉艾提娜！', 28153),
(140930, 'zhTW', '我自由了！', '永遠別想走！', 28153),
(140929, 'zhTW', '我會讓你受盡折磨！', '薩卡拉占背叛了我們！', 28153),
(140928, 'zhTW', '薩卡拉占你下地獄去吧！', '沒人能逃出薩卡拉占的手掌心！', 28153),
(140927, 'zhTW', '戰母！我看到西北方那邊有一些動靜。', '', 28153),
(140926, 'zhTW', '你好，戰母，這邊沒發現任何動靜。', '', 28153),
(140925, 'zhTW', '哎，戰母。有壞消息，我們跟丟那些殺死納吉瑪工作隊的入侵者了。', '', 28153),
(140924, 'zhTW', '', '讓那些鮮血食人妖為這種不敬的行為付出代價吧！你幫死者報仇之後再來找我。', 28153),
(140923, 'zhTW', '', '我不能坐視不管，任由這些可惡的怪物…褻瀆我死去族人的屍體！', 28153),
(140922, 'zhTW', '我的斧頭生來就是要砍樹，這些也算是夠接近的了！', '', 28153),
(140921, 'zhTW', '這個斧頭生來就是要劈砍，那它就會這麼做！', '', 28153),
(140920, 'zhTW', '蜘蛛…木頭怪物…我會把牠們通通都擊倒！', '', 28153),
(140919, 'zhTW', '', '|TInterface\\Icons\\ABILITY_CREATURE_POISON_02:20|t通往朗寇拉的惡魔傳送門開啟了！', 28153),
(140918, 'zhTW', '', '|TInterface\\Icons\\SPELL_HOLY_CONSUMEMAGIC:20|t通往納斯雷薩的暗影傳送門開啟了！', 28153),
(140917, 'zhTW', '', '|TInterface\\Icons\\SPELL_MAGE_FLAMEORB:20|t通往克諾索斯的火焰傳送門開啟了！', 28153),
(140916, 'zhTW', '你休想把我關回去！', '我要好好享用你的靈魂！', 28153),
(140915, 'zhTW', '|cffffff00已進行研究|r', '|cffffff00已進行研究|r', 28153),
(140914, 'zhTW', '', '只要再一批圖騰…好了，準備完成！', 28153),
(140912, 'zhTW', '蜘蛛是一回事，樹人又是怎麼回事？我不幹了！', '', 28153),
(140911, 'zhTW', '我很習慣劈柴這件事情，但是它們並不會反抗！', '', 28153),
(140910, 'zhTW', '樹活過來了！趕快自己逃命去吧！', '', 28153),
(140909, 'zhTW', '', '跟著我，我會在我們逃跑時，隱藏我們的行蹤。', 28153),
(140907, 'zhTW', '', '動作快，我們不知道那東西到底是死是活。', 28153),
(140906, 'zhTW', '', '看看這些神器！我需要更大的袋子！', 28153),
(140905, 'zhTW', '做得好，大家！能拿就拿，不要客氣。', '', 28153),
(140904, 'zhTW', '', '或許能為我遇上的麻煩弄幾個小玩意。', 28153),
(140903, 'zhTW', '', '噢，別忘了蘊藏靈魂的魔像眼！塔恰能把這些東西做成有趣的…小炸彈。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140902, 'zhTW', '', '被詛咒的塑像！塔恰一定會喜歡…看看這些材料。', 28153),
(140901, 'zhTW', '', '好吧，來瞧瞧這種魔法物質到底有什麼能耐。', 28153),
(140900, 'zhTW', '', '這次是大豐收，$p。當然，為了自己人著想，最好的東西都歸我。', 28153),
(140899, 'zhTW', '', '這裡大多是普通的贊達拉武器…喔，那些似乎有附魔！', 28153),
(140898, 'zhTW', '', '打得漂亮。現在來看看他們到底藏了什麼好東西。', 28153),
(140897, 'zhTW', '快保護祭司！誰都別想通過！', '快保護祭司！誰都別想通過！', 28153),
(140896, 'zhTW', '我們會在附近的廢墟建立營地，我有種不好的預感…你們兩位千萬要小心。', '', 28153),
(140895, 'zhTW', '羅蒂叫你撿東西？是我的話，就直接對野獸施放妖術。不過每次這樣做，商人都會碎碎念。', '', 28153),
(140894, 'zhTW', '', '有隻雷龍好像被什麼東西嚇到，現在非常害怕。城裡事情已經夠多了，又發生這種事。盡量幫商人們搶救貨物，不然會被雷龍踩壞！', 28153),
(140893, 'zhTW', '', '我真感謝你，現在的小孩對長輩或長輩的東西一點也不尊重，在我年輕的時候啊…', 28153),
(140892, 'zhTW', '', '幫幫我！那些小不點拿走我們的卷軸，變成了野獸。我們準備了驅散卷軸，要靠得夠近才能發揮作用。小心一點！', 28153),
(140891, 'zhTW', '在你死前應該明白，你剩下的同類會被鐵鍊綑綁，臣服於我們！', '', 28153),
(140890, 'zhTW', '你可悲的同類應該乖乖就範。', '', 28153),
(140889, 'zhTW', '你的同類會在我們的刀下死去。', '', 28153),
(140888, 'zhTW', '部落和聯盟將會毀滅！', '', 28153),
(140887, 'zhTW', '為帝王復仇！', '', 28153),
(140886, 'zhTW', '為雷神復仇！', '', 28153),
(140885, 'zhTW', '祖爾向我們承諾，會向你們的同類討回公道。', '', 28153),
(140880, 'zhTW', '恐龍術師基莎在求救！', '恐龍術師基莎在求救！', 28153),
(140869, 'zhTW', '趕快讓兵營正常運作。', '', 28153),
(140860, 'zhTW', '呃，抱歉！在這裡！可以請你幫點忙嗎？', '', 28153),
(140859, 'zhTW', '', '感謝協助，$p。等你準備好殺幾個塞斯拉克人的時候，就到裡面找我們。', 28153),
(140858, 'zhTW', '', '我同意，這不是我們的戰鬥，是時候離開了。', 28153),
(140857, 'zhTW', '情況惡化的速度太快。我們已經備妥攻擊塞斯拉克所需的補給品。', '', 28153),
(140856, 'zhTW', '送我到枯鬚礦場。', '送我到枯鬚礦場。', 28153),
(140855, 'zhTW', '招募一個哥布林轟炸兵。', '招募一個哥布林轟炸兵。', 28153),
(140854, 'zhTW', '我會先溜進去，偵察那個區域。除掉那些亡靈，方便我收集補給品。', '我會先溜進去，偵察那個區域。除掉那些亡靈，方便我收集補給品。', 28153),
(140853, 'zhTW', '', '你必須先殺死魔像，然後使用圖騰從它們的屍體吸出靈魂。', 28153),
(140852, 'zhTW', '你進去之後動作要快。下個會合點是在廢墟後方，地下密室附近。', '', 28153),
(140851, 'zhTW', '沒希望了！欺詐者的承諾都是謊言！', '', 28153),
(140850, 'zhTW', '謊言！都是謊言！', '', 28153),
(140849, 'zhTW', '為什麼你要讓我看到？！為什麼？！', '', 28153),
(140848, 'zhTW', '你是受人操控的傀儡，就連死後也不能解脫！', '', 28153),
(140847, 'zhTW', '臣服於古翰吧！', '', 28153),
(140846, 'zhTW', '', '死亡阻止不了我…', 28153),
(140845, 'zhTW', '', '母親…會殺了你…', 28153),
(140844, 'zhTW', '好了！這樣就沒問題了…等你靠近村莊，魔法就會把你變成鮮血食人妖的樣子。', '', 28153),
(140843, 'zhTW', '', '事情還沒完…', 28153),
(140842, 'zhTW', '', '我們…無所不在…', 28153),
(140841, 'zhTW', '', '佐司瓦是我們的！', 28153),
(140840, 'zhTW', '', '抵抗是沒有用的！', 28153),
(140839, 'zhTW', '', '母親會把你殺了！', 28153),
(140838, 'zhTW', '', '我們會拿下這個小村莊！', 28153),
(140837, 'zhTW', '', '歐米帶著偵察報告回來了。', 28153),
(140836, 'zhTW', '', '大家，有個壞消息。我發現那裡面有亡靈，我已經把威脅程度提升到橘色。', 28153),
(140834, 'zhTW', '', '在此同時，我會先進去遺跡偵察，你結束後就到會合點找我。', 28153),
(140833, 'zhTW', '', '別把時間浪費在無生命的魔像，尋找還有力量的魔像。', 28153),
(140832, 'zhTW', '送我去戰斧山脊。', '送我去戰斧山脊。', 28153),
(140831, 'zhTW', '我們會在直接攻擊廢墟之前，先在斷橋的會合點碰面。', '', 28153),
(140830, 'zhTW', '好，每個人都分配到工作了。狩獵愉快。', '', 28153),
(140829, 'zhTW', '跟我來，神王拉斯塔哈就在附近。', '跟我來，神王拉斯塔哈就在附近。', 28153),
(140828, 'zhTW', '', '把武器拿出來。有人正在靠近…', 28153),
(140827, 'zhTW', '', '當祖爾要求我們，要我們給他第一任國王達薩的遺骸時，我們以為他在開玩笑。$b$b我們拒絕了他。$b$b我們不知道他手上有一支軍隊，能用武力奪去我們的神殿。', 28153),
(140826, 'zhTW', '這個遺跡裡滿是寶物。我們慢慢來，把事情做好。', '', 28153),
(140825, 'zhTW', '', '媽媽，妳在哪裡？', 28153),
(140824, 'zhTW', '<溫斯東正在打開一個卡包。他從哪弄來那麼多金幣？>', '', 28153),
(140823, 'zhTW', '<溫斯東憤怒地看著他的手牌。>', '', 28153),
(140822, 'zhTW', '<溫斯東把他的卡牌收藏弄亂，試著想出一個新套牌的點子。$b$b進一步觀察，他似乎挑了非常多野獸…>', '', 28153),
(140821, 'zhTW', '送我到亞格洛克。', '送我到亞格洛克。', 28153),
(140820, 'zhTW', '想要找到賽扎克斯，我們必須先找到瑟沙利斯。', '', 28153),
(140818, 'zhTW', '薩卡拉占把我們的靈魂當成武器，你只有死路一條。', '', 28153),
(140817, 'zhTW', '你的武器毫無用處，我們的精神守護著他。', '', 28153),
(140816, 'zhTW', '又一個要為薩卡拉占而死的生者！', '', 28153),
(140815, 'zhTW', '你的靈魂會加入這魔像內的其他靈魂！', '', 28153),
(140814, 'zhTW', '快放了我們…', '', 28153),
(140813, 'zhTW', '薩卡拉占統領一切…', '', 28153),
(140812, 'zhTW', '必須消滅外來者。', '', 28153),
(140811, 'zhTW', '沒有國王，我只聽從薩卡拉占。', '', 28153),
(140810, 'zhTW', '去吧，去吧…找到這個走丟的媽媽，再把她們都帶回來！', '', 28153),
(140809, 'zhTW', '嘿嘿…小朋友沒說錯。她媽媽不在彼界。', '', 28153),
(140808, 'zhTW', '沒有羅亞，我只聽從薩卡拉占。', '', 28153),
(140807, 'zhTW', '守衛庭院，不惜一切。', '', 28153),
(140806, 'zhTW', '救救我們…', '', 28153),
(140805, 'zhTW', '將一切…獻給薩卡拉占…', '', 28153),
(140804, 'zhTW', '噢呵呵，牧師啊！要是你考慮改變信仰的話，記得告訴伯昂撒姆第啊，知道嗎？', '', 28153),
(140803, 'zhTW', '血蠅最近咬人咬得很凶，對吧？', '血蠅最近咬人咬得很凶，對吧？', 28153),
(140802, 'zhTW', '痛！', '喔！', 28153),
(140801, 'zhTW', '大笨蛋。', '呃啊，大笨蛋。', 28153),
(140800, 'zhTW', '喂！拿東西小心一點！', '喂！拿東西小心一點！', 28153),
(140799, 'zhTW', '該死的內陸人…', '呃啊，該死的內陸人…', 28153),
(140798, 'zhTW', '噢！你這是幹什麼？！', '噢！你這是幹什麼？！', 28153),
(140797, 'zhTW', '我們失敗了。燃燒的遠征會徹底吞噬宇宙萬物。', '', 28153),
(140796, 'zhTW', '骯髒的乞丐！這裡由我統治！', '', 28153),
(140795, 'zhTW', '勇士倒下了。再也沒有人能阻止萬物末日。', '', 28153),
(140794, 'zhTW', '元素回應部落的呼喚了，一如往常。', '', 28153),
(140793, 'zhTW', '', '靈魂小屋為你準備好了，你需要什麼？', 28153),
(140792, 'zhTW', '就連羅亞都拋棄了我們。', '就連羅亞都拋棄了我們。', 28153),
(140791, 'zhTW', '薩卡拉占奴役我們無數世代，解放我們…', '薩卡拉占奴役我們無數世代，解放我們…', 28153),
(140790, 'zhTW', '靈魂是強大的武器…如果你能控制他們的話。', '靈魂是強大的武器…如果你能控制他們的話。', 28153),
(140789, 'zhTW', '他利用我們的靈魂保護自己。光憑武器，無法突破他的護盾。', '他利用我們的靈魂保護自己。光憑武器，無法突破他的護盾。', 28153),
(140788, 'zhTW', '無以估計的財富不過是騙局，我們的下場是變成奴隸。', '無以估計的財富不過是騙局，我們的下場是變成奴隸。', 28153),
(140787, 'zhTW', '薩卡拉占禁止我們信奉羅亞。只有他才能被尊崇。', '薩卡拉占禁止我們信奉羅亞。只有他才能被尊崇。', 28153),
(140786, 'zhTW', '為什麼伯昂撒姆第拒絕讓我們進入彼界？', '為什麼伯昂撒姆第拒絕讓我們進入彼界？', 28153),
(140785, 'zhTW', '薩卡拉占把我們的靈魂困在這些魔像中，他逼我們為他效命。', '薩卡拉占把我們的靈魂困在這些魔像中，他逼我們為他效命。', 28153),
(140784, 'zhTW', '希望狼群餓了。部落的旗幟飄揚在紐沃農莊，我們可以訓練狼騎兵了。', '', 28153),
(140783, 'zhTW', '軍械庫建好了，趕快讓熔爐開始運作！', '', 28153),
(140781, 'zhTW', '軍械庫建造完成。下一個命令是什麼？', '', 28153),
(140780, 'zhTW', '薩卡拉占必須為囚禁我們付出代價！', '薩卡拉占必須為囚禁我們付出代價！', 28153),
(140779, 'zhTW', '瑟沙利斯會守護我們的。', '瑟沙利斯會守護我們的。', 28153),
(140778, 'zhTW', '', '安息吧，親愛的卡嘉，你永遠活在我心裡。', 28153),
(140777, 'zhTW', '索利斯是第一個守衛者。他當時需要我與科爾塞克一起幫助他把謎思拉克斯的屍體封印在大金字塔裡面。\n\n我們合力設置了結界，將謎思拉克斯的屍體封印在裡面。\n\n我們每個人都製造了一把鑰匙，將我們的力量灌注其中，以確保墓穴不受人驚擾。', '', 28153),
(140776, 'zhTW', '好了，好了，我們全部人都不需要打架。讓我們坐下來、喝杯酒，然後講講謎語吧，好嗎？', '', 28153),
(140775, 'zhTW', '你以為那邊的溫斯東會是個容易的對手，你看好了。他會扭轉局勢，你才會是搞砸的人！', '', 28153),
(140774, 'zhTW', '我知道拉斯塔哈，偉大的永恆之王。對於要保護誰，他應該更小心點。', '', 28153),
(140773, 'zhTW', '「噢，我會繼續我的冒險」你想。何不留下來、放鬆一下，喝杯酒呢？', '', 28153),
(140772, 'zhTW', '歡迎來到猴人王座提基酒吧。這裡有全贊達拉最棒的酒！', '', 28153),
(140771, 'zhTW', '我們可以利用這顆心和瑟沙利斯的連結來追蹤她。', '', 28153),
(140770, 'zhTW', '這顆心連結著我們的洛阿的生命能量。你描述的紅光表示她很苦惱。但更重要的是，她還活著！', '', 28153),
(140769, 'zhTW', '如果你說的是真的，那我們得快點行動了！', '', 28153),
(140768, 'zhTW', '有意思…', '', 28153),
(140767, 'zhTW', '不不不，你死了對我沒好處。我可以讓你起死回生…只要付點代價。', '', 28153),
(140766, 'zhTW', '喂，你來這裡幹嘛？你的時候還沒到…還早呢。', '', 28153),
(140764, 'zhTW', '', '她沒料到那會把叢林變成沙漠…', 28153),
(140762, 'zhTW', '嗄啊！', '', 28153),
(140761, 'zhTW', '無信者休想佔領我們的神廟。', '', 28153),
(140760, 'zhTW', '我能運用他們的力量，操縱時光來幫助我們。', '', 28153),
(140759, 'zhTW', '就此停手，別再阻撓我。毀約的人終將付出代價。', '', 28153),
(140758, 'zhTW', '現在回到你的牢籠，繼續接受折磨。', '', 28153),
(140757, 'zhTW', '我不會跟出賣自己人的人交易。', '', 28153),
(140756, 'zhTW', '拜託，伯昂撒姆第，再給我一次機會！我會每天敲你的鼓！我的族人會永遠信奉你！', '', 28153),
(140755, 'zhTW', '我和你一樣在找洛琪拉，這些蛇說你找到她了。\n\n我們都能重逢真是太好了，如果他們會把我從這籠子放出來的話啦。', '', 28153),
(140754, 'zhTW', '你永遠無法進入彼界，你永遠看不到你的先祖，你會永遠困在這裡。', '', 28153),
(140753, 'zhTW', '我會的。伯昂撒姆第不會忘記他的怨恨。', '', 28153),
(140752, 'zhTW', '但你變得越來越傲慢，禁止信奉你以外的人，你還記得嗎？', '', 28153),
(140751, 'zhTW', 'change me', 'change me', 28153),
(140750, 'zhTW', '我們已經說好了，你獲得力量，你的族人則信奉我。', '', 28153),
(140749, 'zhTW', '要是你相信，你就是個既愚蠢又虛偽的人，薩卡拉占。', '', 28153),
(140748, 'zhTW', '贊達拉有很多秘密，也許我們發現了一個不應該公諸於世的秘密。', '', 28153),
(140747, 'zhTW', '', '我們要揭穿賈克拉傑這個叛徒。', 28153),
(140746, 'zhTW', '伯昂撒姆第，你這個老雜種，我總算打敗你了！', '', 28153),
(140745, 'zhTW', '是的！我終將加入先祖的行列，進入暗影之境！', '', 28153),
(140743, 'zhTW', '守衛者是誰？', '守衛者是誰？', 28153),
(140742, 'zhTW', '這是什麼？我的靈魂終於脫離那個牢籠了嗎？', '', 28153),
(140740, 'zhTW', '誰是瑟沙利斯？', '誰是瑟沙利斯？', 28153),
(140739, 'zhTW', '以科爾塞克皇帝為首的無信者是激進塞斯拉克人的武裝勢力。\n\n很久以前，我們都團結地生活在一起，如瑟沙利斯所願。\n\n自從科爾塞克叛變開始，無信者就為這片土地帶來了戰爭。\n\n他們征服整個世界之前，絕對不會停手。', '', 28153),
(140738, 'zhTW', '寇賽克是誰？', '寇賽克是誰？', 28153),
(140737, 'zhTW', '無信者才不能占領這座神殿。', '', 28153),
(140736, 'zhTW', '卡茲格羅斯！賜予英雄我們的形體！', '', 28153),
(140735, 'zhTW', '', '起身吧，勇士們！為你們的世界而戰！', 28153),
(140734, 'zhTW', '', '我們還有希望，至高之父。這些凡人體內還有生命的火花。', 28153),
(140733, 'zhTW', '不！我們承受了太多痛苦…絕不能就此結束！', '', 28153),
(140732, 'zhTW', '我能控制時間流動，滅界者！這是能束縛你無情怒火的力量！', '', 28153),
(140731, 'zhTW', '凡人倒下了。最後的泰坦…沒有救了。', '', 28153),
(140730, 'zhTW', '滅界者的怒火湧現了！快，英雄們！打倒這些傀儡！', '', 28153),
(140729, 'zhTW', '', '朋友，做得漂亮。以後隨時歡迎你過來一起狩獵！你先搭獅鷲獸回釣點吧，這裡交給我們就好。', 28153),
(140727, 'zhTW', '', '我們能相信賽里克嗎？你認為賽里克能協助我們找到賽扎克斯嗎？', 28153),
(140725, 'zhTW', '', '這是賈克拉傑做的嗎？他已經抓到賽扎克斯了嗎？', 28153),
(140724, 'zhTW', '榮耀！海洋的榮耀！', '', 28153),
(140723, 'zhTW', '你阻止不了海潮…', '', 28153),
(140722, 'zhTW', 'Ifis yahf an\'zig…', '', 28153),
(140721, 'zhTW', '在我們主子的注視下顫抖吧！', '', 28153),
(140720, 'zhTW', '嗚喔咻！', '', 28153),
(140719, 'zhTW', '海洋在向你呼喚，$r。', '', 28153),
(140718, 'zhTW', '回到你的魔像裡，靈魂！你是我的！', '', 28153),
(140717, 'zhTW', '檢查中', '檢視中', 28153),
(140716, 'zhTW', '', '他的護盾消失了，立刻出擊！', 28153),
(140715, 'zhTW', '', '要是你夠聰明，你可以把重活都丟給靈魂做。', 28153),
(140714, 'zhTW', '', '這就是為什麼我會讓憤怒的靈魂塞滿舊圖騰，$p…', 28153),
(140713, 'zhTW', '', '他在那裡！我會解決那個麻煩的靈魂護盾。', 28153),
(140712, 'zhTW', '諾甘農！用你敏銳的觀察發現敵人的弱點！', '', 28153),
(140711, 'zhTW', '我會將我的力量賦予他們其中一人，至高之父。', '', 28153),
(140710, 'zhTW', '阿格拉瑪！這些凡人需要你的力量。', '', 28153),
(140709, 'zhTW', '讓大海的怒濤洗淨所有的腐化吧！', '', 28153),
(140708, 'zhTW', '讓天空與大海幫助我們的勇士，葛剛尼斯！', '', 28153),
(140707, 'zhTW', '我們有這塊天殺的土地上最好的住宿，你愛怎麼說隨你！', '', 28153),
(140706, 'zhTW', '想喝酒嗎，惡棍？', '', 28153),
(140705, 'zhTW', '', '我不知道這蛇人說的是不是實話，但我們也沒什麼選擇了。', 28153),
(140704, 'zhTW', '我得要殺誰才能在這裡弄到他奶奶的啤酒？', '我得要殺誰才能在這裡弄到他奶奶的啤酒？', 28153),
(140703, 'zhTW', '你有…賣東西嗎？', '你有…賣東西嗎？', 28153),
(140702, 'zhTW', '', '我們必須在賈克拉傑取得武器前先把它拿到手。', 28153),
(140701, 'zhTW', '', '<野豬人發出一連串地呼嚕聲，伴隨著一些尖叫。>', 28153),
(140700, 'zhTW', '翼艇那些傢伙真勇敢！要是我才不敢去面對那些怪物！真慶幸我只要負責運貨就好。', '翼艇那些傢伙真勇敢！要是我才不敢去面對那些怪物！真慶幸我只要負責運貨就好。', 28153),
(140699, 'zhTW', '', '歐克雷，我們走吧。翼艇隊在等我們。', 28153),
(140698, 'zhTW', '', '瑟羅德，我們不等你祝福了。我們要出發去殺海怪。', 28153),
(140697, 'zhTW', '解決薩卡拉占後，就是大豐收的時候了。不管你拿到什麼，都是你的。', '', 28153),
(140696, 'zhTW', '為什麼？', '為什麼？', 28153),
(140695, 'zhTW', '啊啊啊！', '啊啊啊！', 28153),
(140694, 'zhTW', '好燙，好燙，好燙！', '好燙，好燙，好燙！', 28153),
(140693, 'zhTW', '', '我拿到了所有用來解決薩卡拉占屏障所需要的東西了。你只要跟我說他在哪裡。', 28153),
(140692, 'zhTW', '不該是這樣！', '不該是這樣！', 28153),
(140691, 'zhTW', '不不不不！', '不不不不！', 28153),
(140690, 'zhTW', '等一下！', '等一下！', 28153),
(140689, 'zhTW', '', '我會帶路。跟緊一點。', 28153),
(140688, 'zhTW', '', '他們一定試過了，不過謝謝$n，我還沒碰到伯昂撒姆第。', 28153),
(140687, 'zhTW', '', '別想拋下我，獨佔戰利品。', 28153),
(140686, 'zhTW', '', '沙漠沒把你吞噬真是太好了，洛琪拉！', 28153),
(140685, 'zhTW', '', '我和我的斥候會在那邊跟你會合。', 28153),
(140684, 'zhTW', '', '感謝你協助我。我不知道我們的發現有何意義，但我很高興能把這裡的一些人救出去。', 28153),
(140683, 'zhTW', '', '布萊諾領主以及其他人已前往斯陀頌恩谷地，警告他們牧師內部的腐化。我會把這項資訊帶回去波拉勒斯。', 28153),
(140682, 'zhTW', '我會在那邊等你，$n，跟靈魂有關的東西都得謹慎處理。', '', 28153),
(140681, 'zhTW', '', '我已經拿到治療所需的東西…', 28153),
(140680, 'zhTW', '', '我們碰巧發現了某種比我們自己更偉大的事物，我的朋友。', 28153),
(140678, 'zhTW', '', '我們在這裡等，最好不要引起賈克拉傑的刺客的注意。', 28153),
(140677, 'zhTW', '等一下…', '', 28153),
(140675, 'zhTW', '', '海怪死啦！翼艇隊今天的戰鬥會成為傳說。', 28153),
(140673, 'zhTW', '', '出現了！展現翼艇隊的實力吧！', 28153),
(140672, 'zhTW', '沙怒刺客隱入暗影之中。', '沙怒刺客隱入暗影之中。', 28153),
(140671, 'zhTW', '', '翼艇隊，別後退！讓那傢伙知道我們的厲害！', 28153),
(140670, 'zhTW', '', '破壞那些觸手！把怪獸逼出海面！', 28153),
(140669, 'zhTW', '', '提防那些刺客，賈克拉傑可是高價懸賞我的頭。', 28153),
(140667, 'zhTW', '這個世界會是我們的，祖爾已經預見未來！', '這個世界會是我們的，祖爾已經預見未來！', 28153),
(140666, 'zhTW', '你不能阻擋必然發生的事，祖爾已經預見一切。', '你不能阻擋必然發生的事，祖爾已經預見一切。', 28153),
(140665, 'zhTW', '你把我們失敗的國王帶來了？他將會死去，而你也救不了他。', '你把我們失敗的國王帶來了？他將會死去，而你也救不了他。', 28153),
(140664, 'zhTW', '你太遲了，祖爾已經要踏上塔巔了。', '你太遲了，祖爾已經要踏上塔巔了。', 28153),
(140663, 'zhTW', '部落將會毀滅，聯盟將會毀滅，而贊達拉則會一躍而起！', '部落將會毀滅，聯盟將會毀滅，而贊達拉則會一躍而起！', 28153),
(140662, 'zhTW', '贊達拉要統治世界！', '贊達拉要統治世界！', 28153),
(140661, 'zhTW', '我們為真正的食人妖帝國而戰！', '我們為真正的食人妖帝國而戰！', 28153),
(140660, 'zhTW', '為祖爾奮戰至死！', '為祖爾奮戰至死！', 28153),
(140659, 'zhTW', '深海恐獸，受到迪普瓦登的黑暗主人擺布！或許連翼艇隊的人都沒辦法解決。', '', 28153),
(140656, 'zhTW', '有比你高的人惹過我，但他們全都躺下了。', '', 28153),
(140655, 'zhTW', '誰都別想動…我的寶藏…', '', 28153),
(140654, 'zhTW', '不敢相信…', '', 28153),
(140653, 'zhTW', '來人啊！讓這些雜碎見識一下我們的大砲！', '', 28153),
(140652, 'zhTW', '大砲！把他們炸成碎片！', '', 28153),
(140651, 'zhTW', '看看有沒有金牙齒，沒有就餵鯊魚。', '', 28153),
(140650, 'zhTW', '我最愛屍體掉在甲板上的聲音。', '', 28153),
(140649, 'zhTW', '', '古翰就要自由了，希爾雷克的追隨者會獲得獎賞！', 28153),
(140648, 'zhTW', '夥計們，過來搜刮東西囉。等我挑完，你們再搶剩的。', '', 28153),
(140647, 'zhTW', '你犯了最常見的大錯！只要跟寶藏有關，就千萬別惹史威特！', '', 28153),
(140646, 'zhTW', '拿他們的內臟來擦甲板！', '', 28153),
(140645, 'zhTW', '到甲板集合！', '', 28153),
(140644, 'zhTW', '|TInterface\\Icons\\Shaman_PVP_RipplingWaters:20|t%s開始施放|cFFFF0000|Hspell:255594|h[天與海]|h|r！', '|TInterface\\Icons\\Shaman_PVP_RipplingWaters:20|t%s開始施放|cFFFF0000|Hspell:255594|h[天與海]|h|r！', 28153),
(140643, 'zhTW', '', '不錯嘛。比我想的還厲害…但我還是會喝光你的血。', 28153),
(140642, 'zhTW', '', '瑞贊是個強大的羅亞。看來你當祖爾的祭品剛剛好。', 28153),
(140641, 'zhTW', '', '感謝你們把祭司殺了。我對神廟的控制只會越來越強！', 28153),
(140640, 'zhTW', '我喜歡這個！多拿一點到我的巢穴去…我必須先回去和主人聯絡！', '', 28153),
(140639, 'zhTW', '', '無面者現在已經無法構成威脅，但我會繼續監視阿圖亞曼，確保這裡不會有變數。', 28153),
(140638, 'zhTW', '', '沃卡爾…又粉身碎骨了？無所謂…我能修好他。要是換成你死了，那就沒得救了！', 28153),
(140637, 'zhTW', '起飛！', '起飛！', 28153),
(140636, 'zhTW', '我們遭到攻擊了！我們得阻止怪物進攻！', '', 28153),
(140635, 'zhTW', '你準備好了就跟我說！時間不多，怪物可不會慢慢來！', '', 28153),
(140634, 'zhTW', '', '祖爾馬上就會喚醒達薩，食人妖帝國就要復興了！', 28153),
(140633, 'zhTW', '', '太遲了，外來者！神廟現在屬於我的主人了！', 28153),
(140632, 'zhTW', '哈！有用耶！繼續戳！不要停啊！', '', 28153),
(140631, 'zhTW', '我們的數量不如塞斯拉克，但我們能以智慧取勝。', '', 28153),
(140630, 'zhTW', '', '能拿就拿，想拿就拿，想搶誰就搶誰。', 28153),
(140629, 'zhTW', '', '只要帶在身邊夠久，總有一天會派上用場，任何東西都是。', 28153),
(140628, 'zhTW', '|TInterface\\Icons\\ABILITY_MOUNT_EPICBATMOUNT.BLP:20|t%s開始施放|cFFFF0000|Hspell:256497|h[鮮血恐慌]|h|r！尋找掩護！', '', 28153),
(140627, 'zhTW', '呼…他以為我們死了。現在要想個…新計畫。', '', 28153),
(140626, 'zhTW', '還以為有多了不起…結果還是死在這裡。等我恢復以後…再來吃掉你們的屍體。', '', 28153),
(140625, 'zhTW', '', '風會指引你進入阿圖亞曼…做好萬全的準備！', 28153),
(140624, 'zhTW', '', '只有我們才能找到干擾的來源，並且終結它。', 28153),
(140623, 'zhTW', '', '數百年來，黑暗力量在阿圖亞曼生根發展，我感覺到元素越來越躁動不安…', 28153),
(140622, 'zhTW', '迫擊砲小隊！把他們的堡壘炸爛。夷為平地！', '', 28153),
(140621, 'zhTW', '', '衝擊的反響依然在元素之間迴盪，究竟什麼樣的力量才能造成這樣的災難？', 28153),
(140620, 'zhTW', '', '阿圖亞曼曾經是個美輪美奐的地方，卻因數千年前的一場大爆炸而毀於一旦。', 28153),
(140619, 'zhTW', '快躲好，希爾雷克來了！', '', 28153),
(140618, 'zhTW', '', '將你的手放在薩滿石上，我會召喚颶風，把你送到阿圖亞曼。', 28153),
(140617, 'zhTW', '', '必須解決晶尾蠍的問題，而且我擔心還會出現更大的威脅。', 28153),
(140616, 'zhTW', '呃啊啊！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140615, 'zhTW', '你很強大…不過誰也別想對抗羅亞！', '', 28153),
(140614, 'zhTW', '夠了！我會享用你們的屍骨！', '', 28153),
(140613, 'zhTW', '主人賦予我的力量…會淨化你們給我的髒東西！', '', 28153),
(140612, 'zhTW', '我會…啊啊啊！？我…中毒了？你對我做了什麼？', '', 28153),
(140611, 'zhTW', '哈！你要打算怎麼對抗我？我可是天空之王！', '', 28153),
(140610, 'zhTW', '', '我們還有其他選擇嗎？', 28153),
(140609, 'zhTW', '', '洛琪拉！你真的相信他說的話？', 28153),
(140608, 'zhTW', '', '那麼你就能夠得到我們的幫助，賽里克。', 28153),
(140607, 'zhTW', '收集儀式要用的材料，我們會幫你尋找失蹤的神器。', '', 28153),
(140606, 'zhTW', '那個預言比我們想像的更有幫助，我們快要找到賽扎克斯了。', '', 28153),
(140605, 'zhTW', '這個儀式會向我們展示什麼？我們快找到塞扎克斯了沒？', '', 28153),
(140604, 'zhTW', '你真的相信這些蛇嗎？我想他們可能有所隱瞞…', '', 28153),
(140603, 'zhTW', '我的人可以幫你找到這個…你怎麼叫它的？賽扎克斯？', '', 28153),
(140602, 'zhTW', '你要讓他們像這樣把我繼續關著嗎？', '', 28153),
(140601, 'zhTW', '只有傻瓜才會尋找洛琪拉，當她被送進沙漠時，她的下場就已經決定了。', '', 28153),
(140600, 'zhTW', '', '寶庫明明封死了！為什麼裡面是空的？這根本沒有道理…', 28153),
(140599, 'zhTW', '', '賈克拉傑做了什麼…', 28153),
(140596, 'zhTW', '別小看…沙漠…', '', 28153),
(140595, 'zhTW', '神廟會陷落！我們會殺光所有擋路的傢伙！', '', 28153),
(140594, 'zhTW', '很高興跟你交易。你不介意的話，我要先溜了，以免被發現我逃出來了。', '', 28153),
(140593, 'zhTW', '我說話算話，這幾套分水海寇的制服給你們。穿上去就像個十足的罪犯了！', '', 28153),
(140592, 'zhTW', '我要像打破玻璃一樣打碎你！', '我要像打破玻璃一樣打碎你！', 28153),
(140591, 'zhTW', '為了皇帝！', '為了皇帝！', 28153),
(140590, 'zhTW', '你辦到了！我就知道狗有用。牠們是人類最好的朋友。', '', 28153),
(140589, 'zhTW', '我們會解決你，就像捏死蟲子一樣！', '我們會解決你，就像捏死蟲子一樣！', 28153),
(140588, 'zhTW', '你會像沙塵一樣四散各地，被人遺忘！', '你會像沙塵一樣四散各地，被人遺忘！', 28153),
(140587, 'zhTW', '沙漠會吞噬你！', '沙漠會吞噬你！', 28153),
(140586, 'zhTW', '我們會支配一切！', '我們會支配一切！', 28153),
(140585, 'zhTW', '你沒辦法阻止沙塵擴散！', '你沒辦法阻止沙塵擴散！', 28153),
(140584, 'zhTW', '下一個陷落的就是你的家園！', '下一個陷落的就是你的家園！', 28153),
(140583, 'zhTW', '嗯…你先幫我，我就會幫你。懂嗎？', '', 28153),
(140582, 'zhTW', '不過，我也遇到一點小麻煩。這個鎖不願意乖乖讓我撬開。鑰匙在那隻臭狗身上，他可是狡猾得很。', '', 28153),
(140581, 'zhTW', '我會好好享受一番！', '我會好好享受一番！', 28153),
(140580, 'zhTW', '賈克拉傑要這傢伙的人頭！', '賈克拉傑要這傢伙的人頭！', 28153),
(140579, 'zhTW', '你的人頭有錢拿！', '你的人頭有錢拿！', 28153),
(140578, 'zhTW', '如果你真的想弄點大場面，就要跟船長團的人談一談。我可以幫忙。', '', 28153),
(140576, 'zhTW', '我要砍死你！', '我要砍死你！', 28153),
(140575, 'zhTW', '賈克拉傑問候你！', '賈克拉傑問候你！', 28153),
(140574, 'zhTW', '嗨！你們看起來就像是狠腳色，跟平常那些自稱海盜的雜碎不一樣。', '', 28153),
(140573, 'zhTW', '斬鋼截鐵！', '', 28153),
(140572, 'zhTW', '接招！', '', 28153),
(140571, 'zhTW', '', '我從不失手。', 28153),
(140570, 'zhTW', '', '我最喜歡看目標掙扎扭動！', 28153),
(140569, 'zhTW', '當心啦！', '', 28153),
(140568, 'zhTW', '這桶開好啦！接住！', '', 28153),
(140567, 'zhTW', '找出克洛格瓦，小東西會在那裡找到你的。', '', 28153),
(140566, 'zhTW', '憑你也想對抗我，蠢豬？讓我來好好教教你。', '', 28153),
(140565, 'zhTW', '', '我從未見過塞斯拉克人求饒，他說的可能是真的。', 28153),
(140564, 'zhTW', '', '我們沒時間管囚犯了，直接處決他，一了百了！', 28153),
(140563, 'zhTW', '', '說謊！塞斯拉克人燒殺擄掠，無惡不作！', 28153),
(140562, 'zhTW', '海洋怒濤！', '', 28153),
(140561, 'zhTW', '小心腳下。', '', 28153),
(140560, 'zhTW', '我不是你的敵人！你必須相信我！', '', 28153),
(140559, 'zhTW', '把我和我的武器埋在一起…', '', 28153),
(140558, 'zhTW', '我沒打算傷害你！拜託…別殺我！', '', 28153),
(140557, 'zhTW', '這傢伙交給我！', '這傢伙交給我！', 28153),
(140556, 'zhTW', '你會後悔跑到這裡來撒野！', '你會後悔跑到這裡來撒野！', 28153),
(140555, 'zhTW', '我們可是奉命要殺掉這傢伙。', '我們可是奉命要殺掉這傢伙。', 28153),
(140554, 'zhTW', '你的東西，馬上就會變成我的了！', '你的東西，馬上就會變成我的了！', 28153),
(140553, 'zhTW', '我這是高處不勝寒，求敗真難啊！', '', 28153),
(140552, 'zhTW', '你根本不應該插手！', '你根本不應該插手！', 28153),
(140551, 'zhTW', '你管太多閒事了！', '你管太多閒事了！', 28153),
(140550, 'zhTW', '你不屬於這裡！', '你不屬於這裡！', 28153),
(140549, 'zhTW', '首殺！', '', 28153),
(140548, 'zhTW', '漂亮的最後一擊。', '', 28153),
(140546, 'zhTW', '來試試你的能耐吧！', '', 28153),
(140545, 'zhTW', '', '賞你幾顆葡萄吃吧，雜碎！', 28153),
(140544, 'zhTW', '', '事情開始有趣了！', 28153),
(140542, 'zhTW', '', '逃吧，反正你躲不了的！', 28153),
(140541, 'zhTW', '', '我瞄準你了！', 28153),
(140540, 'zhTW', '', '射得…好…', 28153),
(140539, 'zhTW', '', '啊啊，我還有子彈沒用完耶。', 28153),
(140538, 'zhTW', '', '現在讓他們去擔心塞斯拉克吧。你和我必須打開地窖，並且找到塞扎克斯。', 28153),
(140537, 'zhTW', '', '正中要害。', 28153),
(140536, 'zhTW', '', '擊殺數再加一！', 28153),
(140535, 'zhTW', '', '拿你的頭當練習的槍靶剛剛好。', 28153),
(140534, 'zhTW', '看我怎麼弄死你！', '', 28153),
(140533, 'zhTW', '這輪算我請！', '', 28153),
(140532, 'zhTW', '喝啊，你們這群無賴！', '', 28153),
(140531, 'zhTW', '這沒用的。我們的忠誠獻給拉斯塔哈，而不是這個假先知。', '', 28153),
(140530, 'zhTW', '喲嗬！', '', 28153),
(140529, 'zhTW', '臭無賴，來跟我拚酒！', '', 28153),
(140528, 'zhTW', '要我說的話，他該要去找伯昂撒姆第。', '', 28153),
(140527, 'zhTW', '', '你去調和球體。我們其他人會前往阿圖拉曼遺跡，尋找塞扎克斯之殿。', 28153),
(140526, 'zhTW', '', '把艦隊帶到潘達利亞就已經夠糟了，他現在還想自己獨佔祖達薩！', 28153),
(140525, 'zhTW', '', '我從來都不相信祖爾那個油腔滑調的傢伙！', 28153),
(140524, 'zhTW', '完成之後，我就會回來，戰母！', '', 28153),
(140523, 'zhTW', '總算我也…喝掛了嗎？', '', 28153),
(140522, 'zhTW', '我出發了，戰母，為了妳，我赴湯蹈火也再所不辭！', '', 28153),
(140521, 'zhTW', '醉醺醺的！站不起來啦！', '', 28153),
(140520, 'zhTW', '多練練酒量，夥計！', '', 28153),
(140519, 'zhTW', '族母，為了妳什麼都行！', '', 28153),
(140518, 'zhTW', '營地的石材不夠用了，請在納茲米爾找來六十份最純粹的石材。', '營地的石材不夠用了，請在納茲米爾找來六十份最純粹的石材。', 28153),
(140517, 'zhTW', '我要再來一杯！喝醉一點才受得了跟你們再瞎混一遍。', '', 28153),
(140516, 'zhTW', '營地的木頭不夠用了，快去取得三十根原木！', '營地的木頭不夠用了，快去取得三十根原木！', 28153),
(140515, 'zhTW', '戰母！我一直在這邊等著，就和你吩咐的一樣。', '', 28153),
(140514, 'zhTW', '我們需要五十張完好的鱷魚皮。割完這些皮之前別來煩我。', '我們需要五十張完好的鱷魚皮。割完這些皮之前別來煩我。', 28153),
(140513, 'zhTW', '戰母！我能為你做什麼？', '', 28153),
(140512, 'zhTW', '你喜歡我漂亮的鳥兒嗎？', '', 28153),
(140511, 'zhTW', '告訴我可以飛往那些地方。', '告訴我可以飛往那些地方。', 28153),
(140510, 'zhTW', '', '靈魂是我的！', 28153),
(140509, 'zhTW', '', '向我的力量屈服吧！', 28153),
(140508, 'zhTW', '', '粉碎你的靈魂！', 28153),
(140507, 'zhTW', '', '我會撕裂你的靈魂！', 28153),
(140506, 'zhTW', '', '為了部落！', 28153),
(140505, 'zhTW', '為了部落！', '', 28153),
(140504, 'zhTW', '', '為了部落！', 28153),
(140503, 'zhTW', '', '從今天開始，高嶺會遵守誓言，與你們齊心抗敵。', 28153),
(140502, 'zhTW', '', '我接受你宣誓效忠。部落會協助你們…也希望你們表現出忠誠。', 28153),
(140501, 'zhTW', '', '大酋長，貝恩·血蹄和你的勇士都展現了部落應有的力量和勇氣。', 28153),
(140500, 'zhTW', '', '酋長，你有話要說嗎？', 28153),
(140499, 'zhTW', '這是部落的榮幸才對，歡迎你們！我們這就前往奧格瑪，跟大酋長報告這個好消息。', '', 28153),
(140498, 'zhTW', '', '如果你們願意接納我們，加入部落會是高嶺牛頭人的榮幸。', 28153),
(140497, 'zhTW', '', '貝恩·血蹄，你展現出勇氣、榮譽和無比的忠誠。我認為現在是我們兩邊的族人結為盟友的最佳時機。', 28153),
(140496, 'zhTW', '我一想到就不寒而慄，梅拉。要不是貝恩和這位勇士立刻採取行動，一切都完了。', '', 28153),
(140495, 'zhTW', '', '要是烏蓋涅斯的計畫成功了，我們全部都會變成古神的奴僕…就連黯角也不例外。', 28153),
(140494, 'zhTW', '', '這一天差點就是艾澤拉斯的末日。', 28153),
(140493, 'zhTW', '', '蠢貨！祖爾…會撕裂…你的靈魂…', 28153),
(140492, 'zhTW', '那些低語…停下來了。勇士、灰空，謝謝你們。', '', 28153),
(140491, 'zhTW', '', '黯角的情況不妙，我們一定要想辦法救他。請你去找靈行者灰空談談，我想他幫得上忙。', 28153),
(140490, 'zhTW', '除非弄清楚這場攻擊背後的原因，否則我們永遠無法確保莫高雷的安全。梅拉，我跟你一起走，我們一起對抗黑暗吧。', '', 28153),
(140489, 'zhTW', '', '我必須立刻帶黯角回到高嶺！', 28153),
(140488, 'zhTW', '我知道這種力量。勇士！我們需要你的協助！', '', 28153),
(140487, 'zhTW', '', '黯角！這是哪裡來的黑暗力量？', 28153),
(140486, 'zhTW', '我不該…離開…高嶺的…', '', 28153),
(140485, 'zhTW', '我這次想談的，就是同胞之間的情誼，希望...', '', 28153),
(140484, 'zhTW', '', '非常感謝你的邀請，貝恩。很高興我們終於有機會聯繫同胞之間的感情。', 28153),
(140483, 'zhTW', '梅拉，謝謝你大駕光臨。很榮幸歡迎你來到莫高雷。', '', 28153),
(140482, 'zhTW', '', '我要喝你的血！', 28153),
(140481, 'zhTW', '', '我會好好運用你的血…反正你也已經用不著了。', 28153),
(140480, 'zhTW', '', '達薩很快就會甦醒，但你活不到那時候了！', 28153),
(140479, 'zhTW', '我們的部隊有了鋼製護甲，威力提升！', '我們的部隊有了鋼製護甲，威力提升！', 28153),
(140478, 'zhTW', '叛變者是吧？抓住$G他:她;！', '叛變者是吧？抓住$G他:她;！', 28153),
(140477, 'zhTW', '把你的手拿開！', '把你的手拿開！', 28153),
(140476, 'zhTW', '你以為你在幹什麼？！', '你以為你在幹什麼？！', 28153),
(140475, 'zhTW', '等他們聽完我要說的話之後，請把水晶帶到海加爾山，留在永恆之井的岸邊。', '', 28153),
(140474, 'zhTW', '水晶裡有兩段訊息。一段給我哥哥瑪法里恩，另一段是給泰蘭妲的。勇士，請你幫我傳達給他們。', '', 28153),
(140473, 'zhTW', '無論未來如何，我會坦然面對命運。只是…我還有未了的心事…我想化解過去的仇恨。', '', 28153),
(140472, 'zhTW', '前往阿古斯的通道開啟的瞬間…我看見燃燒軍團的世界…那時候我就知道，我回不了艾澤拉斯。', '', 28153),
(140471, 'zhTW', '我們的部隊有了鋼製武器，威力提升！', '我們的部隊有了鋼製武器，威力提升！', 28153),
(140470, 'zhTW', '我能承受痛苦，族母！我準備好戰鬥了！', '', 28153),
(140469, 'zhTW', '我不弱，我感受不到痛苦！我做好殺戮的準備了！', '', 28153),
(140468, 'zhTW', '我受得了更多的痛苦！擋我者死！', '', 28153),
(140467, 'zhTW', '我很強壯！這點攻擊不算什麼，族母！', '', 28153),
(140464, 'zhTW', '$n，跟這隻生物說你認識我，他不能像這樣把我關起來！', '', 28153),
(140463, 'zhTW', '正在移除。', '正在移除。', 28153),
(140462, 'zhTW', '啊，真是好喝。', '', 28153),
(140461, 'zhTW', '來。我們乾杯，敬美好的往日！', '', 28153),
(140460, 'zhTW', '什麼事？', '', 28153),
(140459, 'zhTW', '', '我收下你的獻祭了！', 28153),
(140458, 'zhTW', '', '上來吧！我們可能已經太遲了！', 28153),
(140457, 'zhTW', '主人會把我修好…', '', 28153),
(140456, 'zhTW', '主人會用你的碎塊，把我變得更強！', '', 28153),
(140455, 'zhTW', '主人要殺！', '', 28153),
(140454, 'zhTW', '讓你粉身碎骨。', '', 28153),
(140453, 'zhTW', '一起死！', '', 28153),
(140452, 'zhTW', '不要！', '', 28153),
(140451, 'zhTW', '力量消失了！', '', 28153),
(140450, 'zhTW', '不要碰圖騰！', '', 28153),
(140449, 'zhTW', '不！！', '', 28153),
(140448, 'zhTW', '粉碎！', '', 28153),
(140447, 'zhTW', '打！', '', 28153),
(140446, 'zhTW', '你？！我要撕裂你！', '', 28153),
(140445, 'zhTW', '', '你總算來了，元素竊竊私語，示意你的到來…', 28153),
(140444, 'zhTW', '希瑟雅和我會跑在前頭，通知瓦里克你到了。', '', 28153),
(140441, 'zhTW', '還有其他消息嗎？', '還有其他消息嗎？', 28153),
(140439, 'zhTW', '無信者是誰？', '無信者是誰？', 28153),
(140438, 'zhTW', '無信者永遠不會停止圍攻，但你的努力幫我們爭取到一點時間。我們會找到我們的羅亞並結束這場戰爭。', '', 28153),
(140437, 'zhTW', '無信者正在圍攻我們的家園，我們必須把他們趕回去！絕不容許他們染指神廟。', '', 28153),
(140436, 'zhTW', '噢，你真無趣，$G先生:女士;！', '噢，你真無趣，$G先生:女士;！', 28153),
(140435, 'zhTW', '嗯，才不屑呢！我想我還是回家吧。', '嗯，才不屑呢！我想我還是回家吧。', 28153),
(140434, 'zhTW', '吼！吼吼吼—…噢。', '吼！吼吼吼—…噢。', 28153),
(140433, 'zhTW', '你真的很掃興，夥伴。', '你真的很掃興，夥伴。', 28153),
(140432, 'zhTW', '變大更好玩！', '變大更好玩！', 28153),
(140431, 'zhTW', '耶呼！超好玩…嗚嘎！', '耶呼！超好玩…嗚嘎！', 28153),
(140430, 'zhTW', '小心！我看不到自己在踩哪裡！', '小心！我看不到自己在踩哪裡！', 28153),
(140429, 'zhTW', '我是充滿力量的迅猛龍，就和剛克一樣！哈哈哈！', '我是充滿力量的迅猛龍，就和剛克一樣！哈哈哈！', 28153),
(140428, 'zhTW', '', '噢，你真無趣，$G先生:女士;！', 28153),
(140427, 'zhTW', '', '嗯，才不屑呢！我想我還是回家吧。', 28153),
(140426, 'zhTW', '', '吼！吼吼吼—…噢。', 28153),
(140425, 'zhTW', '', '你真的很掃興，夥計。', 28153),
(140424, 'zhTW', '解決他們。我們的任務就快完成了！', '', 28153),
(140423, 'zhTW', '', '變大更好玩！', 28153),
(140422, 'zhTW', '', '耶呼！超好玩…嗚嘎！', 28153),
(140421, 'zhTW', '', '小心！我看不到自己在踩哪裡！', 28153),
(140420, 'zhTW', '', '我是充滿力量的迅猛龍，就和剛克一樣！哈哈哈！', 28153),
(140419, 'zhTW', '你真的很掃興，夥伴。', '', 28153),
(140418, 'zhTW', '吼！吼吼吼—…噢。', '', 28153),
(140417, 'zhTW', '嗯，才不屑呢！我想我還是回家吧。', '', 28153),
(140416, 'zhTW', '噢，你真無趣，$G先生:女士;！', '', 28153),
(140415, 'zhTW', '我是充滿力量的暴掠龍，就和剛克一樣！哈哈哈！', '', 28153),
(140414, 'zhTW', '小心！我看不到自己在踩哪裡！', '', 28153),
(140413, 'zhTW', '耶呼！超好玩…嗚嘎！', '', 28153),
(140412, 'zhTW', '變大更好玩！', '', 28153),
(140411, 'zhTW', '主人要你的命！', '', 28153),
(140410, 'zhTW', '嘎！這些混蛋！嘎！', '', 28153),
(140409, 'zhTW', '嘎！攻擊他們兩側！嘎！', '', 28153),
(140408, 'zhTW', '嘎！長眠海底！嘎！', '', 28153),
(140407, 'zhTW', '嘎！減輕我的重量！嘎！', '', 28153),
(140406, 'zhTW', '嘎！豬！嘎！', '', 28153),
(140405, 'zhTW', '哈哈！乖乖吃大便吧！', '', 28153),
(140404, 'zhTW', '看來…我要…長眠海底了…', '', 28153),
(140403, 'zhTW', '你只配當魚餌！', '', 28153),
(140402, 'zhTW', '死人可不會講故事！', '', 28153),
(140401, 'zhTW', '哇，看來有人還是不會游泳！', '', 28153),
(140400, 'zhTW', '這滋味一定讓你難忘。', '', 28153),
(140399, 'zhTW', '這發要打爛你的雙眼！', '', 28153),
(140398, 'zhTW', '我要戳爛你們的皮！', '', 28153),
(140397, 'zhTW', '我要把你們炸到屎滾尿流！', '', 28153),
(140396, 'zhTW', '把別人的酒打翻是會倒大楣的。', '', 28153),
(140395, 'zhTW', '不！我要替灑出來的酒默哀一下。', '', 28153),
(140394, 'zhTW', '啊！你害我的酒掉了！', '', 28153),
(140393, 'zhTW', '不留活口！', '', 28153),
(140392, 'zhTW', '全速進擊！', '', 28153),
(140391, 'zhTW', '贊達拉永遠不滅！', '', 28153),
(140390, 'zhTW', '該讓敵人流點血了。', '', 28153),
(140389, 'zhTW', '眾靈與你同在！', '', 28153),
(140388, 'zhTW', '我聽到呼喚了！', '', 28153),
(140387, 'zhTW', '好吧，那麼…就是現在！快！', '', 28153),
(140386, 'zhTW', '手下留情？愚蠢的蟲子！我們會消滅祖達薩，也會消滅你！', '', 28153),
(140385, 'zhTW', '偉大的希爾雷克啊！求求你大發慈悲，放過我們吧！', '', 28153),
(140384, 'zhTW', '衝啊！', '', 28153),
(140383, 'zhTW', '喬崇加，我準備好了。開始執行阻止希爾雷克的計畫吧。', '喬崇加，我準備好了。開始執行阻止希爾雷克的計畫吧。', 28153),
(140382, 'zhTW', '噢，這太瘋狂了…一開始我可沒想到，我居然要殺死羅亞。', '', 28153),
(140381, 'zhTW', '啊啊！鯊鯊，快過來攻擊他們兩側！', '', 28153),
(140380, 'zhTW', '信徒們…收手吧。褻瀆羅亞之人，上前來，過來受死。把你們的鮮血獻給古翰！', '', 28153),
(140379, 'zhTW', '注意點，你們這群屁股長東西的豬！', '', 28153),
(140378, 'zhTW', '最後衝擊！', '', 28153),
(140377, 'zhTW', '你越來越煩人了！', '', 28153),
(140376, 'zhTW', '受死吧，永遠閉嘴！', '', 28153),
(140375, 'zhTW', '這裡有很多食人妖，但他們不想打架。$b$b他們這樣可到不了英靈殿。在戰場追求榮耀才是真理！$b$b他們的國王在哪？他應該會懂我的意思，甚至可能很會打架！', '', 28153),
(140374, 'zhTW', '你來打架的？我正需要對手。', '', 28153),
(140373, 'zhTW', '', '我們希望透過戰鬥精進自己，並追求會讓我們通往英靈殿的榮耀。$b$b這裡的國王很強壯，已經在位數百年了。他會是個可敬的對手。我們只需要和國王見面並挑戰他，來場榮耀的對決！', 28153),
(140372, 'zhTW', '', '神聖襲擊！', 28153),
(140371, 'zhTW', '', '我的勝利將蝕刻在你的靈魂上！', 28153),
(140370, 'zhTW', '', '來吧，戰士！戰鬥等著我們！', 28153),
(140369, 'zhTW', '炸彈來啦！', '', 28153),
(140368, 'zhTW', '', '我在尋找高貴的戰士和我並肩作戰。', 28153),
(140367, 'zhTW', '別在意鯊鯊，他只是需要…減輕點重量！', '', 28153),
(140366, 'zhTW', '你死到臨頭了！', '', 28153),
(140364, 'zhTW', '鯊鯊，起錨了啦，翅膀還不快動起來！我們得給這些旱鴨子一點教訓。', '', 28153),
(140363, 'zhTW', '入侵者！', '', 28153),
(140362, 'zhTW', '趕快把遺囑都寫一寫！', '', 28153),
(140361, 'zhTW', '站住，你們這些混蛋！', '', 28153),
(140360, 'zhTW', '你要我去殺誰？', '', 28153),
(140359, 'zhTW', '', '我們會守住這座島，有事會跟你報告！', 28153),
(140358, 'zhTW', '國王萬歲！', '', 28153),
(140357, 'zhTW', '伯昂撒姆第又給了我一次機會！', '', 28153),
(140356, 'zhTW', '勝利！', '', 28153),
(140355, 'zhTW', '', '黃金順從我的力量！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140354, 'zhTW', '', '你不屬於這裡！', 28153),
(140353, 'zhTW', '', '我會挖出你的心臟。', 28153),
(140352, 'zhTW', '', '情況很緊急。我們到洞穴會合！', 28153),
(140335, 'zhTW', '上吧，要是這次不成功，我們就玩完了。', '', 28153),
(140334, 'zhTW', '糟糕…是希爾雷克！', '', 28153),
(140333, 'zhTW', '塔蘭姬公主一定對在沼澤發生的事情非常好奇。', '', 28153),
(140332, 'zhTW', '', '黃金聽我的號令。', 28153),
(140331, 'zhTW', '', '清除所有腐化！', 28153),
(140330, 'zhTW', '', '我有阿塔達薩的力量！', 28153),
(140329, 'zhTW', '', '我淨化你了！', 28153),
(140328, 'zhTW', '', '你還是死了比較好。', 28153),
(140327, 'zhTW', '', '一定要…淨化…池子。', 28153),
(140326, 'zhTW', '', '可敬的人才能葬在這裡，而你的屍體只能餵恐龍！', 28153),
(140325, 'zhTW', '', '你根本不該來這裡。', 28153),
(140324, 'zhTW', '', '你為黃金而來，卻只會粉身碎骨而去！', 28153),
(140323, 'zhTW', '', '這裡不歡迎亞茲瑪的手下！', 28153),
(140322, 'zhTW', '你過來。我要親自對付你。', '', 28153),
(140321, 'zhTW', '塔蘭姬派我們來這裡調查沼澤怪物是不是真的。但是真相更恐怖…他們正在製造怪物…', '', 28153),
(140320, 'zhTW', '我以為你死了！喂，別跟我說你現在幫鐵潮混混工作！', '', 28153),
(140319, 'zhTW', '這…真是說來話長。先喝一杯吧？', '', 28153),
(140318, 'zhTW', '鐵潮混混，我上次就說過了，你…等等…弗林？！', '', 28153),
(140317, 'zhTW', '咳咳…別跑，你這個胖藤壺！我們來搶寶藏啦！', '', 28153),
(140316, 'zhTW', '', '什…什麼？不！這股…力量…', 28153),
(140315, 'zhTW', '歡迎來到金牙幫，$p，我們現在是一家人了！', '', 28153),
(140314, 'zhTW', '', '你曾經把塞斯拉克揍到它斷尾過嗎？', 28153),
(140313, 'zhTW', '你有力量，但我有腦袋。\n\n我們可以相輔相成。', '', 28153),
(140312, 'zhTW', '', '別擔心，我馬上就會把鼓修好。', 28153),
(140311, 'zhTW', '', '…黑色小鳥早就知道！', 28153),
(140310, 'zhTW', '', '…陪我玩遊戲…', 28153),
(140309, 'zhTW', '', '只剩下玩具…', 28153),
(140308, 'zhTW', '', '大家都逃走或死翹翹。', 28153),
(140307, 'zhTW', '收集中', '收集中', 28153),
(140306, 'zhTW', '', '艾薩拉…我失敗了…', 28153),
(140305, 'zhTW', '', '殺死你女王一定會很高興，納沙塔爾一定會崛起！', 28153),
(140303, 'zhTW', '跟我和弗林一起舉杯！我請客！$B$B你要喝什麼？', '', 28153),
(140302, 'zhTW', '牛奶…在一個骷髏頭杯裡。', '牛奶…在一個骷髏頭杯裡。', 28153),
(140301, 'zhTW', '牛奶。', '牛奶。', 28153),
(140300, 'zhTW', '淡啤酒。', '淡啤酒。', 28153),
(140299, 'zhTW', '|TInterface\\Icons\\INV_AMMO_BULLET_03:20|t%s用|cFFFF0000|Hspell:256044|h[致命射擊]|h|r瞄準你！', '', 28153),
(140298, 'zhTW', '在外面小心。有大事要發生了。', '', 28153),
(140297, 'zhTW', '這裡永遠歡迎你，$p，你一輩子都是金牙幫的一份子。', '', 28153),
(140296, 'zhTW', '金牙旅店正式開幕了！', '', 28153),
(140295, 'zhTW', '謝謝你救了我…', '', 28153),
(140294, 'zhTW', '我可能會留在這裡一陣子，做點我能做的事。', '', 28153),
(140293, 'zhTW', '不敢相信我又找到你了，$p。不過我已經沒力了…', '', 28153),
(140292, 'zhTW', '我說你瘋了，但你剛剛救了我的命，所以，謝謝了。', '', 28153),
(140291, 'zhTW', '你幫這些流放者在這個鳥不生蛋的地方蓋了間旅店？', '', 28153),
(140290, 'zhTW', '無信者在沙漠中一路追著我，還路過許多野生動物和怪物，我差點就掛了。', '', 28153),
(140289, 'zhTW', '鮮血食人妖瘋了，把我們的人抓去餵蝙蝠！', '鮮血食人妖瘋了，把我們的人抓去餵蝙蝠！', 28153),
(140288, 'zhTW', '這些傢伙想用我的血餵那些蝙蝠！', '這些傢伙想用我的血餵那些蝙蝠！', 28153),
(140287, 'zhTW', '謝謝，他們想要把我獻祭給蝙蝠呢！', '謝謝，他們想要把我獻祭給蝙蝠呢！', 28153),
(140286, 'zhTW', '他們想要把我餵給蝙蝠！', '他們想要把我餵給蝙蝠！', 28153),
(140285, 'zhTW', '艾薩拉女王似乎已經走上絕路。如果沒有任何意外，我們一定可以讓她的計畫全盤落空。$B$B那讓我的肚子很癢。', '', 28153),
(140283, 'zhTW', '你的偽裝消失了！為什麼我的還在？嗯…這樣計畫要改變一下。', '', 28153),
(140282, 'zhTW', '勇士！你怎麼了？', '', 28153),
(140281, 'zhTW', '啊，我頭有點暈…是伯昂撒姆第在呼喚我。', '', 28153),
(140280, 'zhTW', '', '我知道你在想什麼：「贊達拉食人妖不是奴役了哥布林並逼他們挖礦嗎？」$b$b聽著，如果我們不處理我們的敵人，他們只會彼此找麻煩。那樣對生意可不好。', 28153),
(140279, 'zhTW', '', '沒有必要謝我。', 28153),
(140278, 'zhTW', '沒有必要謝我。', '', 28153),
(140277, 'zhTW', '不客氣。', '', 28153),
(140276, 'zhTW', '', '不客氣。', 28153),
(140275, 'zhTW', '很榮幸能為你服務。', '', 28153),
(140274, 'zhTW', '', '很榮幸能為你服務。', 28153),
(140273, 'zhTW', '', '這沒什麼。', 28153),
(140272, 'zhTW', '這沒什麼。', '', 28153),
(140271, 'zhTW', '', '這是我的榮幸。', 28153),
(140270, 'zhTW', '這是我的榮幸。', '', 28153),
(140269, 'zhTW', '這是我的榮幸。', '', 28153),
(140268, 'zhTW', '', '這是我的榮幸。', 28153),
(140267, 'zhTW', '', '一點沒錯。', 28153),
(140266, 'zhTW', '一點也沒錯。', '', 28153),
(140265, 'zhTW', '你說得沒錯。', '', 28153),
(140264, 'zhTW', '我在沃魯敦的第一口酒。自從我們遭到攻擊後，我一直走不出沙丘！', '', 28153),
(140263, 'zhTW', '', '你說得沒錯。', 28153),
(140262, 'zhTW', '$p，你在這裡做什麼？我還以為你死了！', '', 28153),
(140261, 'zhTW', '是的。', '', 28153),
(140260, 'zhTW', '', '是的。', 28153),
(140259, 'zhTW', '', '當然囉。', 28153),
(140258, 'zhTW', '當然囉。', '', 28153),
(140257, 'zhTW', '在這裡等。', '', 28153),
(140256, 'zhTW', '', '在這裡等。', 28153),
(140255, 'zhTW', '', '待在這裡別走。', 28153),
(140254, 'zhTW', '待在這裡別走。', '', 28153),
(140253, 'zhTW', '留在這裡。', '', 28153),
(140252, 'zhTW', '', '留在這裡。', 28153),
(140251, 'zhTW', '', '待在這裡。', 28153),
(140250, 'zhTW', '待在這裡。', '', 28153),
(140249, 'zhTW', '你人真好。', '', 28153),
(140248, 'zhTW', '', '你人真好。', 28153),
(140247, 'zhTW', '', '你若覺得我的拳頭太快，等你被我姊姊諾可希打就知道了，她一揮拳就會讓你眼冒金星！', 28153),
(140246, 'zhTW', '', '我欠你一個人情。', 28153),
(140245, 'zhTW', '我欠你一個人情。', '', 28153),
(140244, 'zhTW', '謝謝你，朋友。', '', 28153),
(140243, 'zhTW', '', '謝謝你，朋友。', 28153),
(140242, 'zhTW', '', '非常感謝你。', 28153),
(140241, 'zhTW', '非常感謝你。', '', 28153),
(140240, 'zhTW', '', '聖光感謝你。', 28153),
(140239, 'zhTW', '聖光感謝你。', '', 28153),
(140238, 'zhTW', '我很感謝你。', '', 28153),
(140237, 'zhTW', '', '我很感謝你。', 28153),
(140236, 'zhTW', '', '我需要法力。', 28153),
(140235, 'zhTW', '我需要法力。', '', 28153),
(140234, 'zhTW', '我需要更多法力。', '', 28153),
(140233, 'zhTW', '', '我需要法力。', 28153),
(140232, 'zhTW', '', '需要法力。', 28153),
(140231, 'zhTW', '需要法力。', '', 28153),
(140230, 'zhTW', '法力不夠了。', '', 28153),
(140229, 'zhTW', '', '我需要先有法力。', 28153),
(140228, 'zhTW', '', '等你準備好，就可以見摩可希了，朋友。$b$b別在意我，我只是個打手。但別以為你能夠碰她，你還是在我的攻擊範圍內。', 28153),
(140227, 'zhTW', '', '轟炸敵人！', 28153),
(140226, 'zhTW', '轟炸敵人！', '', 28153),
(140225, 'zhTW', '開始轟炸！', '', 28153),
(140224, 'zhTW', '', '開始轟炸！', 28153),
(140223, 'zhTW', '', '你覺得我可怕的話，你該看看我的姊妹波可希。她和異種蠍一樣兇猛，但和毒蛇一樣優雅。咻！碰！', 28153),
(140222, 'zhTW', '', '你想要談談，就去和茉希談，負責談話的是她。$b$b<諾可希提起她的釘錘，用它的頭拍向她的另一隻掌心。>$b$b如果你想做任何蠢事，負責打人的是我。你不會想跟我談話的。', 28153),
(140221, 'zhTW', '釋放你的怒火！', '', 28153),
(140220, 'zhTW', '', '釋放你的怒火！', 28153),
(140219, 'zhTW', '', '全力出擊！', 28153),
(140218, 'zhTW', '', '你可以和老闆講話，但我會好好注意你的。', 28153),
(140217, 'zhTW', '', '這港口禁止任何胡鬧的勾當。你沒看到我在笑，對吧？', 28153),
(140216, 'zhTW', '', '開火！', 28153),
(140215, 'zhTW', '', '我同意。', 28153),
(140214, 'zhTW', '我同意。', '', 28153),
(140213, 'zhTW', '你有事找老闆，你就去找老闆。$b$b你有事找我？不，你才沒有。滾開，小子。', '', 28153),
(140212, 'zhTW', '這是真的。', '', 28153),
(140211, 'zhTW', '', '這是真的。', 28153),
(140210, 'zhTW', '$p…？', '', 28153),
(140209, 'zhTW', '就這麼辦。', '', 28153),
(140208, 'zhTW', '', '就這麼辦。', 28153),
(140207, 'zhTW', '', '對，我看到加茲里斯和他的人在那兒策劃陰謀。這對他們才沒好處。我們成功和國王合作之後，要做的第一件事就是剷除這些競爭者。$b$b供給和需求，對吧？如果我們擁有所有的供給，我們就可以滿足我們所有的需求！', 28153),
(140206, 'zhTW', '', '的確。', 28153),
(140205, 'zhTW', '的確。', '', 28153),
(140204, 'zhTW', '的確。', '', 28153),
(140203, 'zhTW', '', '的確。', 28153),
(140202, 'zhTW', '', '我拒絕。', 28153),
(140201, 'zhTW', '我拒絕。', '', 28153),
(140200, 'zhTW', '拜託，我受傷了…能不能同情一下可憐的贊達拉人！', '', 28153),
(140199, 'zhTW', '這樣不行。', '', 28153),
(140198, 'zhTW', '', '這樣不行。', 28153),
(140197, 'zhTW', '哈囉！有人在嗎？', '', 28153),
(140196, 'zhTW', '', '不行。', 28153),
(140195, 'zhTW', '不行。', '', 28153),
(140194, 'zhTW', '絕不！', '', 28153),
(140193, 'zhTW', '', '當然不行。', 28153),
(140192, 'zhTW', '不。', '', 28153),
(140191, 'zhTW', '', '不要。', 28153),
(140190, 'zhTW', '', '不。', 28153),
(140189, 'zhTW', '不。', '', 28153),
(140188, 'zhTW', '大家各就各位。我們今天的第一位客戶，太叫人興奮了！別殺他們！', '', 28153),
(140187, 'zhTW', '', '我們在此代表污水組織。沒有任何事能夠阻止我們，就算和熱砂那些業餘的傢伙一起困在這港口也一樣。$b$b我們的協商進行得很順利。很快我就能和國王談話，而他將會明白，這個合作關係對雙方都一樣有利。', 28153),
(140186, 'zhTW', '', '污水組織雇用了這行業最好的幾個談判家。他們幾乎什麼都能引進、賣出，或是直接買入。對某些人來說很值得崇拜。$b$b我負責的是其他人辦不到的事，我和我的姊妹會接手處理，看好囉。', 28153),
(140185, 'zhTW', '污水？我知道他們。他們很臭屁，還派摩可希和她的姊妹到這來「注意」我們。好像我們會做虧心事一樣，懂我意思嗎？$b$b我不會擔心他們。我和許多貿易親王打過交道，這是小事一樁。', '', 28153),
(140184, 'zhTW', '在這碰到你真好，你可以給國王帶個口信嗎？我很確定他會想知道，我們能為他偉大的城市帶來什麼樣的商機。', '', 28153),
(140183, 'zhTW', '敵人來了！', '', 28153),
(140182, 'zhTW', '', '危險逼近了。', 28153),
(140181, 'zhTW', '我向你保證，我們在這辦理的是熱砂的官方業務。$b$b老闆知道贊達拉帝國很龐大，而當一個帝國很龐大，我們的機會就很龐大，懂了嗎？$b$b他們不讓我到城區裡去，但我有預感這一切很快就會改變。', '', 28153),
(140180, 'zhTW', '', '危險逼近了！', 28153),
(140179, 'zhTW', '危險逼近了！', '', 28153),
(140178, 'zhTW', '請幫幫我！', '', 28153),
(140177, 'zhTW', '', '請幫幫我！', 28153),
(140176, 'zhTW', '快來幫我！', '', 28153),
(140175, 'zhTW', '', '快來幫我！', 28153),
(140174, 'zhTW', '', '幫幫我！', 28153),
(140173, 'zhTW', '幫幫我！', '', 28153),
(140172, 'zhTW', '幫我！', '', 28153),
(140171, 'zhTW', '', '幫我！', 28153),
(140170, 'zhTW', '蘇拉瑪爾…尊貴而自由。', '', 28153),
(140169, 'zhTW', '', '蘇拉瑪爾…尊貴而自由。', 28153),
(140168, 'zhTW', '', '我們抵抗黑暗。', 28153),
(140167, 'zhTW', '我們抵抗黑暗。', '', 28153),
(140166, 'zhTW', '幸會。', '', 28153),
(140165, 'zhTW', '', '幸會。', 28153),
(140163, 'zhTW', '那會讓每個出席的客人印象深刻！', '', 28153),
(140161, 'zhTW', '跟我來，我知道要把這根長牙裝在…哪裡，好讓每個人都看得見。', '', 28153),
(140160, 'zhTW', '－嚴禁轉述－', '', 28153),
(140159, 'zhTW', '葛斯拉克，這些入侵者交給你處理！別再讓我失望了。', '', 28153),
(140158, 'zhTW', '安靜！這裡還有別人…', '', 28153),
(140157, 'zhTW', '我們進不去，門被我們沒見過的魔法封住了。', '', 28153),
(140156, 'zhTW', '來到這片沙漠，是你的錯誤。就算是公主也救不了你。', '', 28153),
