(140127, 'zhTW', '', '蘇拉瑪爾不會遺忘它的勇士。', 28153),
(140126, 'zhTW', '蘇拉瑪爾不會遺忘它的勇士。', '', 28153),
(140125, 'zhTW', '', '永遠跟隨聖光的指引。', 28153),
(140124, 'zhTW', '永遠跟隨聖光的指引。', '', 28153),
(140123, 'zhTW', '再見。', '', 28153),
(140122, 'zhTW', '', '再見。', 28153),
(140121, 'zhTW', '我們走這裡。', '', 28153),
(140120, 'zhTW', '一起來吧。', '', 28153),
(140119, 'zhTW', '', '來吧。', 28153),
(140118, 'zhTW', '', '來吧。', 28153),
(140117, 'zhTW', '', '跟著我走。', 28153),
(140116, 'zhTW', '', '跟我走吧。', 28153),
(140115, 'zhTW', '跟著我走。', '', 28153),
(140114, 'zhTW', '跟我走。', '', 28153),
(140113, 'zhTW', '', '走這邊。', 28153),
(140112, 'zhTW', '', '走這邊。', 28153),
(140111, 'zhTW', '跟我來。', '', 28153),
(140110, 'zhTW', '跟我來。', '', 28153),
(140109, 'zhTW', '這個事情不要說出去，嗯，$p？算是金牙的秘密。', '', 28153),
(140108, 'zhTW', '嗯，這種水果看起來很好吃！把它放上自助餐餐桌。', '', 28153),
(140107, 'zhTW', '在你去幫我們採點水果時，我會做一些烤毒蠍當早餐！', '', 28153),
(140106, 'zhTW', '$n的鱗片注入靜電！', '$n的鱗片注入靜電！', 28153),
(140105, 'zhTW', '', '想要的話，第一趟飛行就送給你，$p。如果想飛去什麼地方，就告訴我一聲。', 28153),
(140104, 'zhTW', '', '小心潛伏在山脊上的尖角蜥…牠們會突然偷襲。', 28153),
(140103, 'zhTW', '快撤退！', '', 28153),
(140102, 'zhTW', '', '快撤退！', 28153),
(140101, 'zhTW', '快撤退！', '', 28153),
(140100, 'zhTW', '', '快離開這裡！', 28153),
(140099, 'zhTW', '', '快找掩護！', 28153),
(140098, 'zhTW', '快找掩護！', '', 28153),
(140097, 'zhTW', '', '快找掩護！', 28153),
(140096, 'zhTW', '快找掩護！', '', 28153),
(140095, 'zhTW', '撤退！', '', 28153),
(140094, 'zhTW', '', '撤退！', 28153),
(140093, 'zhTW', '撤退！', '', 28153),
(140092, 'zhTW', '', '撤退！', 28153),
(140091, 'zhTW', '願羅亞引領你的艦隊迅速前進。你必須警告國王，不然就來不及了！', '', 28153),
(140090, 'zhTW', '清出一條道路後，我們會在卡歐的戰艦跟你會合。願靈魂與你同在。', '', 28153),
(140089, 'zhTW', '對。', '', 28153),
(140088, 'zhTW', '', '對。', 28153),
(140087, 'zhTW', '對。', '', 28153),
(140086, 'zhTW', '', '對。', 28153),
(140085, 'zhTW', '你會在上方的臺地找到我們的戰士。為了祖達薩！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140080, 'zhTW', '<火車聲 - 汽鏘汽鏘嘟嘟！>', '', 28153),
(140079, 'zhTW', '', '<火車聲 - 汽鏘汽鏘嘟嘟！>', 28153),
(140078, 'zhTW', '<火車聲 - 汽鏘汽鏘嘟嘟！>', '', 28153),
(140077, 'zhTW', '', '<火車聲 - 汽鏘汽鏘嘟嘟！>', 28153),
(140076, 'zhTW', '', '<嘆氣>', 28153),
(140075, 'zhTW', '<嘆氣>', '', 28153),
(140074, 'zhTW', '', '<嘆氣>', 28153),
(140073, 'zhTW', '<嘆氣>', '', 28153),
(140072, 'zhTW', '<噗噗呸呸呸！>', '', 28153),
(140071, 'zhTW', '', '<噗噗呸呸呸！>', 28153),
(140070, 'zhTW', '<噗噗呸呸呸！>', '', 28153),
(140069, 'zhTW', '', '<噗噗呸呸呸！>', 28153),
(140068, 'zhTW', '', '<笑>', 28153),
(140067, 'zhTW', '<笑>', '', 28153),
(140066, 'zhTW', '', '<笑>', 28153),
(140065, 'zhTW', '<笑>', '', 28153),
(140064, 'zhTW', '<笑聲>', '', 28153),
(140063, 'zhTW', '', '<笑聲>', 28153),
(140062, 'zhTW', '<笑聲>', '', 28153),
(140061, 'zhTW', '', '<笑聲>', 28153),
(140060, 'zhTW', '', '<親吻>', 28153),
(140059, 'zhTW', '<親吻>', '', 28153),
(140058, 'zhTW', '', '<親吻>', 28153),
(140057, 'zhTW', '<親吻>', '', 28153),
(140056, 'zhTW', '我們不會懼怕黑暗。', '', 28153),
(140055, 'zhTW', '歡迎你來啊。', '', 28153),
(140054, 'zhTW', '你好啊。', '', 28153),
(140053, 'zhTW', '你好。', '', 28153),
(140052, 'zhTW', '誰快幫我治療！', '', 28153),
(140051, 'zhTW', '幫我治療！', '', 28153),
(140050, 'zhTW', '願山嶺賜予你庇護與安樂。', '', 28153),
(140049, 'zhTW', '願你在旅途中增長智慧。', '', 28153),
(140048, 'zhTW', '願大地之母指引你。', '', 28153),
(140047, 'zhTW', '再見。', '', 28153),
(140046, 'zhTW', '為了部落！', '', 28153),
(140045, 'zhTW', '', '為了部落！', 28153),
(140044, 'zhTW', '為了聯盟！', '', 28153),
(140043, 'zhTW', '', '為了聯盟！', 28153),
(140042, 'zhTW', '為了部落！', '', 28153),
(140041, 'zhTW', '', '來吧。', 28153),
(140040, 'zhTW', '幫我！', '', 28153),
(140039, 'zhTW', '我需要幫忙！', '', 28153),
(140038, 'zhTW', '危險逼近了！', '', 28153),
(140037, 'zhTW', '<親吻>', '', 28153),
(140036, 'zhTW', '<笑聲>', '', 28153),
(140035, 'zhTW', '<笑>', '', 28153),
(140034, 'zhTW', '不可以。', '', 28153),
(140033, 'zhTW', '不行。', '', 28153),
(140032, 'zhTW', '不。', '', 28153),
(140031, 'zhTW', '好…喬崇加！請你到那間小屋那邊去準備鮮血儀式。', '好…喬崇加！請你到那間小屋那邊去準備鮮血儀式。', 28153),
(140030, 'zhTW', '快。我們快沒時間了！', '', 28153),
(140029, 'zhTW', '沒錯。', '', 28153),
(140028, 'zhTW', '說得好。', '', 28153),
(140027, 'zhTW', '噓！聽著，我們必須偷偷溜走。在鮮血食人妖之中，女性是他們的領袖。$B$B命令我去那邊的草屋…就說要我準備一場鮮血儀式。$B$B沒有人會驚訝你對我呼來喚去的！', '', 28153),
(140026, 'zhTW', '的確。', '', 28153),
(140025, 'zhTW', '開火！', '', 28153),
(140024, 'zhTW', '轟炸他們！', '', 28153),
(140023, 'zhTW', '需要法力。', '', 28153),
(140022, 'zhTW', '我需要法力。', '', 28153),
(140021, 'zhTW', '<噗噗呸呸呸！>', '', 28153),
(140020, 'zhTW', '<嘆氣>', '', 28153),
(140019, 'zhTW', '當然囉。', '', 28153),
(140018, 'zhTW', '我的榮幸。', '', 28153),
(140017, 'zhTW', '不客氣。', '', 28153),
(140016, 'zhTW', '萬分感謝。', '', 28153),
(140015, 'zhTW', '感激不盡。', '', 28153),
(140014, 'zhTW', '我欠你一份情。', '', 28153),
(140013, 'zhTW', '<火車聲 - 汽鏘汽鏘嘟嘟！>', '', 28153),
(140012, 'zhTW', '待在這裡。', '', 28153),
(140011, 'zhTW', '待著別走。', '', 28153),
(140010, 'zhTW', '的確。', '', 28153),
(140009, 'zhTW', '沒錯。', '', 28153),
(140008, 'zhTW', '對。', '', 28153),
(140004, 'zhTW', '我真羨慕你們…能親眼目睹嶄新的食人妖帝國誕生。可惜拉斯塔哈不能親自體會這種感動了。', '', 28153),
(140003, 'zhTW', '魔古完成他們的任務…把國王的護衛全都引開了。', '', 28153),
(140002, 'zhTW', '預言已然降臨。只需要引開你們，祖爾就能完成計畫。', '', 28153),
(140001, 'zhTW', '維納克多爾！卡歐最好是在撒謊，否則你就是下一個！', '', 28153),
(140000, 'zhTW', '', '帝王？', 28153),
(139999, 'zhTW', '無所謂…你們的國王…死定了…', '', 28153),
(139998, 'zhTW', '我就知道不能信任那混帳！他會付出代價的！', '', 28153),
(139997, 'zhTW', '祖爾說過會有新的帝國，我們會實現這句話！', '', 28153),
(139996, 'zhTW', '看看四周，卡歐。你早已輸了！放下武器！', '', 28153),
(139995, 'zhTW', '我是雷霆之力，也是荒原煞星，絕對不會輸的！', '', 28153),
(139994, 'zhTW', '', '我們是贊達拉！我們永不屈服！', 28153),
(139993, 'zhTW', '祖達薩本來就是屬於我們的。趕快投降，我還能讓你死得痛快一點。', '', 28153),
(139992, 'zhTW', '哼。我還以為會更有挑戰性呢。', '', 28153),
(139991, 'zhTW', 'Taz\'dingo！為了神王拉斯塔哈！', '', 28153),
(139990, 'zhTW', '', '哈布圖，你必須去告訴神王拉斯塔哈祖爾不懷好意。我和$p會對付這個蠻卒。', 28153),
(139989, 'zhTW', '贊達拉艦隊的到來', '贊達拉艦隊的到來', 28153),
(139988, 'zhTW', '我看看你戴著什麼帽子。', '我看看你戴著什麼帽子。', 28153),
(139987, 'zhTW', '你活著回來了？\n\n我是說，你活著回來了！\n\n在你的腳步聲嚇到我以前，我正在如我承諾過的一樣跟蘇爾森清理酒館…你看得出來嗎？', '', 28153),
(139986, 'zhTW', '讓我們來看看那些石頭吧！', '讓我們來看看那些石頭吧！', 28153),
(139985, 'zhTW', '我有個好主意：你買兩頂帽子，你戴一頂，把另一頂給朋友、家人、伴侶都好，我不會批評你的。', '', 28153),
(139984, 'zhTW', '我當然會同時賣兩頂帽子，我有兩個頭！$b$b看來你只有一個頭，真為你感到遺憾。但你可以留第二頂備用！', '', 28153),
(139983, 'zhTW', '想買帽子嗎？我有帽子！買兩件第二件原價！', '', 28153),
(139982, 'zhTW', '想和波魯達一樣又高又壯嗎？買顆我的石頭吧，每天用它來練舉重跟拋接，或許你也可以又高又壯。$b$b可能不會和我一樣高、一樣壯就是了。', '', 28153),
(139981, 'zhTW', '來買波魯達的石頭！我這裡有最好最好的石頭，價錢也很優惠！', '', 28153),
(139980, 'zhTW', '嘿，你！想買個石頭嗎？我的石頭是最好的。', '', 28153),
(139979, 'zhTW', '瑟沙利斯之心發出紅光，那是什麼意思？', '瑟沙利斯之心發出紅光，那是什麼意思？', 28153),
(139978, 'zhTW', '我們必須保持堅強。', '我們必須保持堅強。', 28153),
(139977, 'zhTW', '亡者山隘非常明顯，朝西北方走，看到又黑又詭異的石山就是了。那一定非常有趣！', '', 28153),
(139976, 'zhTW', '等你靠近營地，就會偽裝成鮮血食人妖。不過記得！這偽裝不是十全十美的。', '', 28153),
(139975, 'zhTW', '鮮血食人妖的戰隊是女人在管事的，所以你要扮成這個樣子。相信我，沒問題的！', '', 28153),
(139974, 'zhTW', '先警告你，可能會有點痛。嗯…應該是很痛！', '', 28153),
(139727, 'zhTW', '我準備好要開始儀式，把自己偽裝成鮮血食人妖了。', '我準備好要開始儀式，把自己偽裝成鮮血食人妖了。', 28153),
(139726, 'zhTW', '這個地方有非常非常邪惡的巫毒壞法術。', '', 28153),
(139592, 'zhTW', '如果你需要我，我會在離艾薩恩很遠很遠的地方。', '', 28153),
(139567, 'zhTW', '看來我不在的時候，你似乎交了一些朋友。', '', 28153),
(139482, 'zhTW', '', '守住這個匯合處！我們不能讓魔古再前進一步。', 28153),
(139443, 'zhTW', '你的朋友可以離開，不過我會盯著他。', '', 28153),
(139410, 'zhTW', '馬上去辦。', '', 28153),
(139408, 'zhTW', '城市正在動亂。我們必須保護你的安全！', '', 28153),
(139406, 'zhTW', '我的國王，我們不能離開你身邊。', '', 28153),
(139401, 'zhTW', '我給過你機會。只要我還在位，贊達拉就不可能向你的魔古寵物屈服。', '', 28153),
(139397, 'zhTW', '我的士兵會翻遍整座城市，把他們一網打盡。', '', 28153),
(139391, 'zhTW', '我欠你一條命。這邊不安全，我們神廟裡面見。', '', 28153),
(139390, 'zhTW', '', '喂！別只是出一張嘴，快來幫忙！我們去海上打！', 28153),
(139389, 'zhTW', '瑟羅德修士！斯陀頌恩領主！還好你們來了，我們正好需要協助！', '', 28153),
(139388, 'zhTW', '當你拿到我要的東西後，到另一頭跟我會面。務必做好充足準備。', '', 28153),
(139387, 'zhTW', '喂，你！快過來！不然等那些惡棍回來我一定會被殺掉。', '', 28153),
(139386, 'zhTW', '就算他們奪走這片土地，也奪不走我們永恆的靈魂。', '', 28153),
(139385, 'zhTW', '謝謝你。我會想辦法離開這裡。', '謝謝你。我會想辦法離開這裡。', 28153),
(139384, 'zhTW', '過來這裡！我們可是會誓死保護卡薩金的珠寶。', '過來這裡！我們可是會誓死保護卡薩金的珠寶。', 28153),
(139383, 'zhTW', '', '翼艇隊，準備就位！這些怪獸跟我們之前遇到的都不一樣！', 28153),
(139375, 'zhTW', '小心你的腳趾，拉尼舒什麼都能吃…真的是來者不拒。', '', 28153),
(139374, 'zhTW', '', '如果你也在找塔吉，他應該在南邊的山丘上。', 28153),
(139372, 'zhTW', '這裡的事完成後，就回商隊跟我會合，我要開始進行維修。', '', 28153),
(139371, 'zhTW', '恭喜你，$p。只有少數幸運兒才能在遇到拉尼舒後活下來。', '', 28153),
(139370, 'zhTW', '既堅固又結實…這種木材最適合用來修復商隊的貨車。', '', 28153),
(139369, 'zhTW', '篷車的修理進行地很順利，多虧有你幫我們帶來的好木材。', '', 28153),
(139368, 'zhTW', '', '好吧…嗯…是這個！隱形卷軸…終於找到了。', 28153),
(139367, 'zhTW', '', '不要離題，我們沒時間聽故事！', 28153),
(139366, 'zhTW', '我沒說過這個故事嗎？喔，很精彩耶！我看看，該從哪裡開始呢…', '', 28153),
(139365, 'zhTW', '', '天啊…這個看起來像是用古神語寫的。你是在哪裡找到這個的？', 28153),
(139364, 'zhTW', '不是！難道你連看都沒看嗎？不過這先留著，把事情解決就用得上了。', '', 28153),
(139363, 'zhTW', '', '我看看…永恆回歸卷軸對嗎？', 28153),
(139362, 'zhTW', '拜託，可以帶我去找阿爾比嗎？他一定很擔心。', '', 28153),
(139361, 'zhTW', '在你拯救其他人之後，和我在東邊的高地會面，我們要對抗海潮祭司！', '', 28153),
(139360, 'zhTW', '', '拜託，這很花時間耶！公主，你不知道這個老傢伙有多少卷軸。', 28153),
(139358, 'zhTW', '一定要去跟其他人會合！', '我們去跟其他人會合！', 28153),
(139357, 'zhTW', '保護艦隊！', '保護艦隊！', 28153),
(139356, 'zhTW', '一定要守住戰港！', '一定要守住戰港！', 28153),
(139355, 'zhTW', '為神王拉斯塔哈而戰！', '為神王拉斯塔哈而戰！', 28153),
(139354, 'zhTW', '哈！我就知道一定能找到這個。這樣我們就可以混進鮮血食人妖裡了。記得跟緊。', '', 28153),
(139353, 'zhTW', '在以前，我可以搞定一整群這種巨痕蚯蚓。他們在黑暗中找上我，我就被放倒了！他們的要求，精簡來說就是「快點！艾薩拉要她的獎品！」', '', 28153),
(139351, 'zhTW', '你知道的都請跟我們說，大人，我們需要盡可能收集情報。', '', 28153),
(139350, 'zhTW', '那些納迦是在這裡找某個東西。恐怕是為了艾薩拉吧。我們一定要阻止他們，或是打亂他們的目標。', '', 28153),
(139348, 'zhTW', '因…因為我太…太沒用了，這個村莊被邪教組織占領了。', '', 28153),
(139347, 'zhTW', '聽到了嗎？是伯昂撒姆第的召喚！永恆將近！', '聽到了嗎？是伯昂撒姆第的召喚！永恆將近！', 28153),
(139346, 'zhTW', '大人！你還好吧？發生了什麼事？', '', 28153),
(139345, 'zhTW', '布蘭農！', '', 28153),
(139344, 'zhTW', '那聲音…他在呼喚我們…必須聽從！', '那聲音…他在呼喚我們…必須聽從！', 28153),
(139343, 'zhTW', '發生什麼事了？我原本不舒服躺在床上…但是現在…我在哪？', '發生什麼事了？我原本不舒服躺在床上…但是現在…我在哪？', 28153),
(139341, 'zhTW', '我的生命…獻給帝王…', '', 28153),
(139339, 'zhTW', '我對不起人民，都是因為我威望不夠，他們才會投靠其他力量。', '', 28153),
(139338, 'zhTW', '叔叔派我管理這個村莊，讓我盡量多累積領導人民的經驗。但沒想到…會有邪教，遇上邪教要怎麼辦？！', '', 28153),
(139336, 'zhTW', '千萬次戰鬥…千萬個勝利…', '', 28153),
(139335, 'zhTW', '雷霆…永遠不會…停息…', '', 28153),
(139334, 'zhTW', '陌生人，謝謝你救我。康威那些人一下子就掌控整個村莊…我完全措手不及。', '', 28153),
(139333, 'zhTW', '風暴…消散了…', '', 28153),
(139329, 'zhTW', '我們貫徹…眾神的意志…', '', 28153),
(139328, 'zhTW', '就連岩石也會…碎裂…', '', 28153),
(139327, 'zhTW', '肉體…很脆弱…', '', 28153),
(139326, 'zhTW', '魔古帝國…永遠…不滅…', '', 28153),
(139317, 'zhTW', '你會是個好奴隸！', '', 28153),
(139316, 'zhTW', '感受風暴之怒！', '', 28153),
(139315, 'zhTW', '向我屈服！', '', 28153),
(139314, 'zhTW', '我就是力量的代表！', '', 28153),
(139312, 'zhTW', '贊達拉必須遵守承諾…不然就得死。', '', 28153),
(139311, 'zhTW', '我會空手捏碎你的頭！', '', 28153),
(139309, 'zhTW', '我們會在你的屍骨上重建帝國！', '', 28153),
(139308, 'zhTW', '屈服吧！', '', 28153),
(139307, 'zhTW', '布蘭農，你這個愚蠢的孩子。我已經完成交易了，我一定會帶領村莊邁向成功，我們不需要你！', '布蘭農，你這個愚蠢的小孩。我已經完成交易了，我一定會帶領村莊邁向成功，我們不需要你！', 28153),
(139306, 'zhTW', '我們需要資源來建造防禦工事。大家分頭去把鋼鐵和木頭帶回來！', '', 28153),
(139305, 'zhTW', '', '你知道這座島的什麼秘密？告訴我！', 28153),
(139304, 'zhTW', '海洋永遠都會由我們統治！', '', 28153),
(139303, 'zhTW', '我們會讓你在海裡淹死！', '', 28153),
(139298, 'zhTW', '', '好啦，我會去商隊那裡，待會見，$p！', 28153),
(139295, 'zhTW', '沒錯，謝謝你們今天出手相助，科娜和$p，我欠你們一次。', '', 28153),
(139294, 'zhTW', '', '我們不會跟你一起戰到最後，桑博爾。', 28153),
(139293, 'zhTW', '我也很高興聽到凋萎者桑卡逃離他的束縛。那麼強大的元素…會讓我們很頭痛。', '', 28153),
(139292, 'zhTW', '所以這團混亂都是一個薩滿一手促成？謝謝你把他殺了。', '', 28153),
(139291, 'zhTW', '哈哈！接招吧，骯髒的部落混蛋！', '', 28153),
(139290, 'zhTW', '我的儀式就快完成了！為我效力，凋萎者桑卡！', '', 28153),
(139288, 'zhTW', '', '好啊，誰在乎！哼…說得跟真的一樣。', 28153),
(139287, 'zhTW', '哼，你懂什麼！你想留就留，我們要可走了。這個地方我熟得很。', '', 28153),
(139286, 'zhTW', '那些傢伙會宰了你！他們比上次遇到的鮮血食人妖更難對付。', '', 28153),
(139285, 'zhTW', '哼！你以為自己是誰啊。我們一定要教訓這些兇手！', '', 28153),
(139284, 'zhTW', '', '你應該留下來幫忙想想計畫，你打不過鮮血食人妖的。', 28153),
(139283, 'zhTW', '姬莎，拉斯克，我們要把殺害托加的害蟲全都殺光。', '', 28153),
(139282, 'zhTW', '', '總算！我還以為只有我們在乎托加的死活！', 28153),
(139281, 'zhTW', '噢，你看看。其他人總算鼓起勇氣趕過來了。', '', 28153),
(139250, 'zhTW', '|cffffff00+$1i鐵|r', '|cffffff00+$1i鐵|r', 28153),
(139241, 'zhTW', '繼續戰鬥！', '', 28153),
(139240, 'zhTW', '', '我們相輔相成，對吧？', 28153),
(139204, 'zhTW', '', '我又殺了一個，桑博爾！這是第27個了！', 28153),
(139198, 'zhTW', '|cffffff00+$1i木材|r', '|cffffff00+$1i木材|r', 28153),
(139168, 'zhTW', '對…掙扎吧…抵抗吧…古翰要你…吃盡…苦頭。', '', 28153),
(139167, 'zhTW', '你想…阻止…古翰。只會…失敗…和…受苦。', '', 28153),
(139165, 'zhTW', '來吧。', '', 28153),
(139164, 'zhTW', '別動。', '', 28153),
(139163, 'zhTW', '工坊建造完成！', '', 28153),
(139162, 'zhTW', '工坊準備好了！建造石毀車，該讓聯盟看看他們的城牆有多不堪一擊了。', '', 28153),
(139097, 'zhTW', '$n在它們的爪子上塗滿毒液！', '$n在它們的爪子上塗滿毒液！', 28153),
(139080, 'zhTW', '你不明白…藏在底下的到底是什麼…', '', 28153),
(139079, 'zhTW', '我們的力量會粉碎你！', '', 28153),
(139078, 'zhTW', '向新的主人臣服吧！', '', 28153),
(139077, 'zhTW', '只有我們…能戰勝…', '', 28153),
(139073, 'zhTW', '風暴也都聽我號令！', '', 28153),
(139072, 'zhTW', '你會後悔的！', '', 28153),
(139071, 'zhTW', '我已經得到了你一輩子得不到的力量！', '', 28153),
(139070, 'zhTW', '我警告過你了！', '', 28153),
(139065, 'zhTW', '我們的話語充滿力量。這裡是我們的！', '', 28153),
(138870, 'zhTW', '', '造箭師谷地的居民多虧了你才能得救，$c。 \n\n你去照料威奎斯特小姐吧。女巫會留下的餘孽就讓我們來處理。', 28153),
(138865, 'zhTW', '', '你回來了！請告訴我你把高階女巫解決掉了。', 28153),
(138864, 'zhTW', '', '自從那股能量從礦場湧出以後，我們就沒有辦法再進去了。\n\n你控制住的那個巫木傀儡或許是我們唯一的希望。', 28153),
(138859, 'zhTW', '', '我們感謝你的幫忙，$c。在你到來之前，情勢非常不妙。', 28153),
(138853, 'zhTW', '我會到城裡到處看看，希望城裡的人都沒事！', '', 28153),
(138852, 'zhTW', '成功了！你控制住咒化奴隸了！', '', 28153),
(138849, 'zhTW', '走開！', '', 28153),
(138848, 'zhTW', '', '高興了嗎？喜歡我走來走去嗎？', 28153),
(138847, 'zhTW', '', '你說我站著不動？那…這樣呢？這樣算在朝聖了嗎？', 28153),
(138841, 'zhTW', '靠近一點，小$pr，我有話想跟你說。', '', 28153),
(138837, 'zhTW', '', '我來親自問問這是怎麼回事。到城鎮裡找我！', 28153),
(138836, 'zhTW', '', '你很優秀，$p。我希望我們很快會再見面。', 28153),
(138833, 'zhTW', '我們必須保持堅強。', '', 28153),
(138832, 'zhTW', '去吧，$n！保護佐司瓦的人民！', '', 28153),
(138831, 'zhTW', '冷靜啊，海洋之子，必須相信大海，大海會給我們解答。', '', 28153),
(138830, 'zhTW', '', '你要是碰上邪惡的女巫，記得幫我在她們臉上打一拳，勇士！', 28153),
(138829, 'zhTW', '', '我們很高興還能看到像你這樣的勇士，$n。', 28153),
(138824, 'zhTW', '', '塔吉和科娜現在早該回來了，他們一定遇到麻煩了。', 28153),
(138823, 'zhTW', '我們的當務之急是回收補給品，吃飯皇帝大。', '', 28153),
(138822, 'zhTW', '偉大的海洋啊，請安慰釣點碼頭的病人和受苦的人。疾病在這裡不斷蔓延，但願我們能發現疾病的根源！', '', 28153),
(138821, 'zhTW', '是你們運氣好，$n正好到那裡才救了你們。', '', 28153),
(138820, 'zhTW', '你們再吵就禁足三個月！', '', 28153),
(138819, 'zhTW', '我們是冒險者耶！', '', 28153),
(138818, 'zhTW', '', '噢噢噢噢！', 28153),
(138817, 'zhTW', '噢！不要這樣啦，爺爺！', '', 28153),
(138816, 'zhTW', '你們全部都要禁足兩個月！', '', 28153),
(138815, 'zhTW', '', '是的，長官。', 28153),
(138814, 'zhTW', '知道，爺爺。', '', 28153),
(138813, 'zhTW', '知道，爺爺。', '', 28153),
(138812, 'zhTW', '你們這些孩子明明就知道不可以偷溜出去！', '', 28153),
(138811, 'zhTW', '這首曲子我再也不想聽到了！', '這首曲子我再也不想聽到了！', 28153),
(138810, 'zhTW', '我終於自由了！', '我終於自由了！', 28153),
(138809, 'zhTW', '唉，那首歌大概一整天都會在我腦中迴盪吧。', '唉，那首歌大概一整天都會在我腦中迴盪吧。', 28153),
(138808, 'zhTW', '謝謝你，英雄！', '謝謝你，英雄！', 28153),
(138807, 'zhTW', '終於…可以一死了…阻止古翰的工作…就交給你了…', '', 28153),
(138804, 'zhTW', '你以為自己能阻止古翰？有膽就到我的競技場見真章！', '', 28153),
(138803, 'zhTW', '納瑟席近來有點粗魯。我很遺憾，你的禮儀課將會嚴苛…而且長久。現在就用卷軸吧，會有幫助的！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(138802, 'zhTW', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_EARTH.BLP:20|t$n讓他們的血|cFFFF0000|Hspell:255582|h[腐化]|h|r了！', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_EARTH.BLP:20|t$n讓他們的血|cFFFF0000|Hspell:255582|h[腐化]|h|r了！', 28153),
(138801, 'zhTW', '', '|TInterface\\Icons\\SPELL_HOLY_PURIFY.BLP:20|t$n施展|cFFFF0000|Hspell:255577|h[汲血]|h|r！', 28153),
(138800, 'zhTW', '', '$n以黃金包覆雙手。', 28153),
(138799, 'zhTW', '一開始這邊就只有隻小魚人，然後風暴就來了，接著納迦就湧上了岸。他們先拿下了我，我真的很為此羞愧。', '', 28153),
(138798, 'zhTW', '請解放我的靈魂，拜託你！', '', 28153),
(138797, 'zhTW', '我不想繼續下去了！了結我吧！', '', 28153),
(138796, 'zhTW', '拜託，讓我回到伯昂撒姆第的身旁吧！', '', 28153),
(138795, 'zhTW', '好痛啊！了結我吧！', '', 28153),
(138794, 'zhTW', '拜託你，終結我的痛苦吧！', '', 28153),
(138793, 'zhTW', '我無法控制自己！', '', 28153),
(138792, 'zhTW', '拜託你，了結我吧！', '', 28153),
(138791, 'zhTW', '', '請解放我的靈魂，拜託你！', 28153),
(138790, 'zhTW', '', '我不想繼續下去了！了結我吧！', 28153),
(138789, 'zhTW', '', '拜託，讓我回到伯昂撒姆第的身旁吧！', 28153),
(138788, 'zhTW', '', '好痛啊！了結我吧！', 28153),
(138787, 'zhTW', '', '拜託你，終結我的痛苦吧！', 28153),
(138786, 'zhTW', '', '我無法控制自己！', 28153),
(138785, 'zhTW', '', '拜託你，了結我吧！', 28153),
(138784, 'zhTW', '', '我聽到元素的召喚，我依循著風的指示飄泊。', 28153),
(138783, 'zhTW', '這些東西是怎麼跑到我的胃裡的？', '這些東西是怎麼跑到我的胃裡的？', 28153),
(138782, 'zhTW', '我…我覺得不太舒服…', '我…我覺得不太舒服…', 28153),
(138781, 'zhTW', '我的胃有好幾天都沒感覺這麼舒服了！', '我的胃有好幾天都沒感覺這麼舒服了！', 28153),
(138779, 'zhTW', '這些東西…在我的身體裡嗎？', '這些東西…在我的身體裡嗎？', 28153),
(138776, 'zhTW', '', '除非你打算留下來幫忙，否則還是走吧。', 28153),
(138775, 'zhTW', '', '歡迎來到造箭師谷地。很抱歉這裡一團糟，我們正忙著應付這些女巫。', 28153),
(138774, 'zhTW', '我還以為它們會把我殺了！謝謝你！', '我還以為它們會把我殺了！謝謝你！', 28153),
(138773, 'zhTW', '謝謝你。等我找到寵物，我就要離開這個鬼地方！', '謝謝你。等我找到寵物，我就要離開這個鬼地方！', 28153),
(138772, 'zhTW', '謝謝你！', '謝謝你！', 28153),
(138771, 'zhTW', '我從來沒有見過像這樣的東西。我要走了！', '我從來沒有見過像這樣的東西。我要走了！', 28153),
(138770, 'zhTW', '謝謝你救了我。', '謝謝你救了我。', 28153),
(138769, 'zhTW', '謝謝你，陌生人。我還以為我死定了。', '謝謝你，陌生人。我還以為我死定了。', 28153),
(138768, 'zhTW', '朋友，抱歉突然打擾，我有非常緊急的事情。', '', 28153),
(138767, 'zhTW', '你是誰？你不是鮮血食人妖…不然靈魂早就把你殺死了。', '', 28153),
(138766, 'zhTW', '等等…有東西往這個方向過來了。', '', 28153),
(138765, 'zhTW', '這座廢墟是伯昂撒姆第的聖地。鮮血食人妖不會跟著我們過來。', '', 28153),
(138762, 'zhTW', '數量不多，不過全部都能讓你們使用。', '', 28153),
(138760, 'zhTW', '', '部落又要撤退了？他們有什麼詭計嗎？', 28153),
(138759, 'zhTW', '絕對不能讓大酋長逃走。抓到她是贏得這場戰爭的關鍵。', '', 28153),
(138758, 'zhTW', '你什麼都不是…', '', 28153),
(138757, 'zhTW', '這個海灣屬於海潮祭司納瑟須！我們會解開祖達薩蘊藏的謎！', '', 28153),
(138756, 'zhTW', '嘿，鮮肉上門了。', '嘿，鮮肉上門了。', 28153),
(138755, 'zhTW', '不用擔心，我們不會被霸凌的。我知道有個地方可以讓我們躲起來蒐集情報。', '', 28153),
(138754, 'zhTW', '霸凌。他的意思是霸凌。', '', 28153),
(138753, 'zhTW', '好吧，進去報到，準備參加…「迎新活動」。嘿嘿。', '', 28153),
(138752, 'zhTW', '嗯…好吧，你們確實自備了帽子…', '', 28153),
(138751, 'zhTW', '我們想要加入鐵潮劫掠者，我們自備了帽子。', '我們想要加入鐵潮劫掠者，我們自備了帽子。', 28153),
(138749, 'zhTW', '這個地方很神聖，我的任務就是永世保護它的安全。', '', 28153),
(138748, 'zhTW', '很多朝聖者在前往亡者之城的路上，會在這裡小歇一下。\n\n這幾天真是平靜…但這可不是什麼好現象！', '', 28153),
(138747, 'zhTW', '這座庇護所剛落成的時候，我就在負責守備工作了。我會一直做到這邊垮掉那一天。', '', 28153),
(138746, 'zhTW', '這裡歡迎所有要前往亡者之城的人。', '', 28153),
(138745, 'zhTW', '遵照伯昂撒姆第的指示，我為前去其神廟的旅人提供住宿之處。', '', 28153),
(138744, 'zhTW', '看起來真帥。走吧，我們去找招募員報名。', '', 28153),
(138743, 'zhTW', '帽子戴上。想當水手怎麼可以沒有帽子！', '', 28153),
(138742, 'zhTW', '再給我幾分鐘就行了，羅莎琳。有了強化魚叉，你一定能很快的打敗對手！', '', 28153),
(138741, 'zhTW', '', '歐克雷，武器到底來了沒有？可以的話，我想盡快出航。這根本就是浪費時間！', 28153),
(138740, 'zhTW', '哎？你要幹嘛？', '哎？你要幹嘛？', 28153),
(138739, 'zhTW', '我想我現在要空手回去波拉勒斯了。帶著卷軸在那邊和我碰面，我們會補償你。', '', 28153),
(138738, 'zhTW', '這很重要：你要交易的卷軸是用綠色封蠟彌封。是綠色！', '', 28153),
(138737, 'zhTW', '你找的人叫做克倫頓。他的店在高處，在鎮的最南端。', '', 28153),
(138734, 'zhTW', '你幹嘛咬我？好像我的身上還有肉一樣。', '', 28153),
(138733, 'zhTW', '吃那隻野獸，你這隻瘋蛇！', '', 28153),
(138732, 'zhTW', '我喜歡存在你體內的好戰性格。把它留著用在賽斯拉克身上吧。', '', 28153),
(138731, 'zhTW', '哈！你差點就唬到我了！', '', 28153),
(138730, 'zhTW', '瑞贊的目光轉向$n，並且準備|TInterface\\Icons\\ABILITY_MOUNT_FOSSILIZEDRAPTOR.BLP:20|t|cFFFF0000|Hspell:255421|h[吞噬]|h|r目標！', '', 28153),
(138729, 'zhTW', '古爾納庫船長必須為他的所作所為付出代價。', '', 28153),
(138728, 'zhTW', '謝謝你放了我…我會讓你把它當成人生目標。', '', 28153),
(138725, 'zhTW', '挖洞要注意看！我正在下頭睡覺呢！', '挖洞要注意看！我在下面睡覺呢！', 28153),
(138724, 'zhTW', '在你大肆破壞這個地區時，這裡的靈魂可能不會袖手旁觀…', '', 28153),
(138723, 'zhTW', '我不認為往那些骸骨上丟炸彈是好主意！', '', 28153),
(138722, 'zhTW', '我拷問了許多食人妖關於席帕拉的事，但無論我的拷問方法為何，我聽到的都是不同的故事。\n\n有些人說席帕拉讓人們的身體因為腐爛而脹大。\n\n或是讓任何看他的人變成活生生的骷髏。\n\n或是他會潛伏在陰影中，在夜晚才出沒，吞食熟睡的人們。\n\n或是他會在道路附近等候，讓人們咳血死去。\n\n難怪當地人都離得遠遠的！', '', 28153),
(138721, 'zhTW', '距離我上次這樣注視此地已經很久了。就連在那個時候，當地居民也都恐懼且避諱這裡…\n\n惡靈潛伏在此，$n，最好不要打擾他們。', '', 28153),
(138717, 'zhTW', '你不該在贊姆蘭的巷弄間遊蕩，小老鼠。抓住他，奇發！', '你不該在贊姆蘭的巷弄間遊蕩，小老鼠。抓住他，奇發！', 28153),
(138716, 'zhTW', '部落…會為我報仇…', '', 28153),
(138715, 'zhTW', '這個地區屬於聖匣守護者。這裡不歡迎聯盟的人！', '', 28153),
(138709, 'zhTW', '', '或許有些附帶的損傷，但我很確定我們最終會把碎片都拼回去的。我們或許需要再召集幾個研究助理…', 28153),
(138707, 'zhTW', '嘿，薩農麥克，你的帽子戴起來真的很舒服，我決定要留著！', '', 28153),
(138706, 'zhTW', '誰想跟我喝一杯？', '', 28153),
(138705, 'zhTW', '你們為什麼要如此努力？你們知道我們永生不死，對吧？', '', 28153),
(138704, 'zhTW', '喂，森吉拉克！你一不留神，蘇南吉就會趁機偷走你的東西！', '', 28153),
(138703, 'zhTW', '嘿，薩葛吉亞，你的手下搞得這個地方烏煙瘴氣，給我離開這裡！', '', 28153),
(138702, 'zhTW', '蘇萊，我從沒看過動作比你還慢的人！', '', 28153),
(138701, 'zhTW', '口渴了嗎？太不幸了！', '', 28153),
(138700, 'zhTW', '跟上大家的速度，你這個懶鬼。我需要更多烈酒！', '', 28153),
(138699, 'zhTW', '$n佔領了枯鬚礦場！', '$n佔領了枯鬚礦場！', 28153),
(138698, 'zhTW', '', '不要再像這樣亂跑了。知道了嗎？好了，我們走吧，還有很多事要做。', 28153),
(138691, 'zhTW', '我…請冷靜，大家快冷靜！我們在想辦法了。我們一定會找到解藥、一定會找出問題源頭！', '', 28153),
(138690, 'zhTW', '', '你必須幫助我們，瑟羅德！我們需要答案！我們需要解藥！', 28153),
(138689, 'zhTW', '疾病的源頭是什麼？', '', 28153),
(138688, 'zhTW', '', '我們孩子都生病了！', 28153),
(138687, 'zhTW', '記得回來參加複賽…', '記得回來參加複賽…', 28153),
(138686, 'zhTW', '我為此喝了一整天酒…', '我整天喝酒就為了這個…', 28153),
(138679, 'zhTW', '古爾納庫會很不爽。', '古爾納庫會很不爽。', 28153),
(138678, 'zhTW', '離我的藏寶圖遠一點！', '離我的藏寶圖遠一點！', 28153),
(138676, 'zhTW', '繳交狐狸人的頭，第一次購物就能打折！', '', 28153),
(138675, 'zhTW', '一天一杯酒，從此不怕打！', '', 28153),
(138674, 'zhTW', '眼罩再怎麼多都不夠！', '', 28153),
(138673, 'zhTW', '看起來就像贊姆蘭本人戴著補釘的最新款帽子！', '', 28153),
(138672, 'zhTW', '尤克薩是魔精的專家！趕快來買他最新的藥水！', '', 28153),
(138671, 'zhTW', '彎劍全新到貨！超級鋒利！', '', 28153),
(138670, 'zhTW', '今天跟著一隻猛虎一起戰鬥吧！', '', 28153),
(138669, 'zhTW', '來點狐狸人肉排，剛煮好的！', '', 28153),
(138668, 'zhTW', '奧勾今天都半價…', '奧勾的東西今天都半價…', 28153),
(138666, 'zhTW', '', '我可以自己找路出去。小心。', 28153),
(138664, 'zhTW', '在你走之前…記得收拾這團混亂。', '在你走之前…記得收拾這團混亂。', 28153),
(138663, 'zhTW', '把這旅店當你的家吧…永遠留在這裡！', '把這旅店當成你的家吧…永遠留在這裡！', 28153),
(138662, 'zhTW', '嗨，$c，我們需要你幫點小忙去處理一個問題。', '', 28153),
(138661, 'zhTW', '我們會永遠臣服於贊姆蘭的意志。', '我們會永遠臣服於贊姆蘭的意志。', 28153),
(138660, 'zhTW', '我付出一切來保護我的組員。你不能再靠近了！', '我付出一切來保護我的組員。你不能再靠近了！', 28153),
(138659, 'zhTW', '我們從墓穴歸來，隨時都能出戰。', '我們從墓穴歸來，隨時都能出戰。', 28153),
(138658, 'zhTW', '我不是已經殺掉你了嗎？或者是你殺掉我了？', '我不是已經殺掉你了嗎？或者是你殺掉我了？', 28153),
(138655, 'zhTW', '我會享用你的血肉，把你的靈魂獻給主人！', '', 28153),
(138652, 'zhTW', '我要把你的肉從骨頭上扯下來！', '', 28153),
(138651, 'zhTW', '以在地上爬的人來說，你算不錯了…不過也到此為止！', '', 28153),
(138650, 'zhTW', '跑快點，廢物。我有一大把時間追殺你。', '跑快點，廢物。我有一大把時間追殺你。', 28153),
(138649, 'zhTW', '沒有人能從我手中搶走這個寶藏！你不能，贊姆蘭不能，誰都不能！', '沒有人能從我手中搶走這個寶藏！你不能，贊姆蘭不能，誰都不能！', 28153),
(138644, 'zhTW', '我們的帝國會崛起，你們的會滅亡！', '我們的帝國會崛起，你們的會滅亡！', 28153),
(138641, 'zhTW', '你的死會讓別人學到教訓！', '你的死會讓別人學到教訓！', 28153),
(138634, 'zhTW', '別擔心，$pr。我沒打算跟你打。\n\n這是贊姆蘭搞的鬼，每個人都是這樣，不管我們要不要。\n\n看看我…\n\n<溫和的岡薩重重嘆了一口氣。>\n\n想喝點什麼嗎？', '', 28153),
(138633, 'zhTW', '如果你想在沃魯敦活命，你必須隨時準備好面對死亡…千萬別眨眼。', '', 28153),
(138631, 'zhTW', '有獵物，才有錢拿。', '寶藏…是我的了。', 28153),
(138628, 'zhTW', '詛咒讓我們更強大！', '為了贊姆蘭，我付出了一切。', 28153),
(138627, 'zhTW', '敢打擾贊姆蘭的生者都得死。', '不是我們的同伴，通通都得死！', 28153),
(138625, 'zhTW', '我已經不知道在這裡駐守多少年了。', '這是我們的港口！', 28153),
(138624, 'zhTW', '小心一點！千萬不要小看塞斯拉克…', '', 28153),
(138623, 'zhTW', '', '找到了！謝謝你幫忙。', 28153),
(138622, 'zhTW', '', '快找到了…', 28153),
(138621, 'zhTW', '', '我總算快找到真正的聖物了，既然其他莫名其妙的東西都拿出來了，應該不會花太多時間才對。', 28153),
(138620, 'zhTW', '', '從這些骨頭上面的咬痕看來，這一定是柏基的收藏。', 28153),
(138619, 'zhTW', '', '這是曲熔做出來的原型作品，不意外。簡直是浪費金屬，我們可沒有空間放這種垃圾。', 28153),
(138618, 'zhTW', '', '我們所發現的最有價值的寶物，都留在這個箱子裡。我會盡可能取回這些寶物，你來幫我顧著背後，$c。', 28153),
(138615, 'zhTW', '我們不會拋棄神廟。', '', 28153),
(138589, 'zhTW', '只要這座神廟矗立的一天，隨時歡迎你把它當成你的避風港。', '', 28153),
(138568, 'zhTW', '', '喔喔！只要讓我喘口氣，我一定很快就能踢你的脛骨報仇！', 28153),
(138567, 'zhTW', '等等！我不是狗！我很驚訝你那雙又粗又短的腿竟然這麼能跑。我本來以為你會在碰到斜坡的時候直接滾倒在地上。', '', 28153),
(138566, 'zhTW', '', '一個缺口！我要跟你賽跑，柏基！打賭你抓不到我，就算你有半條狗的血統也一樣！', 28153),
(138556, 'zhTW', '聯盟控制了激流堡中庭！', '聯盟控制了激流堡中庭！', 28153),
(138555, 'zhTW', '$n佔領了激流堡中庭！', '$n佔領了激流堡中庭！', 28153),
(138553, 'zhTW', '', '是埋伏！快保護村民！', 28153),
(138552, 'zhTW', '', '走吧，我們到高徑之路去！', 28153),
(138551, 'zhTW', '希望是這樣，小姐。整隊，走，出發！', '', 28153),
(138550, 'zhTW', '', '別說了，元帥。這位勇士會跟我一起去，絕對不會有事的。', 28153),
(138549, 'zhTW', '小姐，可是那樣不安全 - ', '', 28153),
(138548, 'zhTW', '', '元帥，你先帶兵到亞羅姆之地去。我先去其他地方，然後再跟你會合。', 28153),
(138547, 'zhTW', '聯盟控制了英勇之喚小徑！', '聯盟控制了英勇之喚小徑！', 28153),
(138546, 'zhTW', '$n佔領了英勇之喚小徑！', '$n佔領了英勇之喚小徑！', 28153),
(138545, 'zhTW', '下一個是誰？', '', 28153),
(138544, 'zhTW', '歡迎成為永遠不死的受詛咒者，大副。', '', 28153),
(138543, 'zhTW', '呃啊！', '', 28153),
(138542, 'zhTW', '大副加姆波亞，重生吧！', '', 28153),
(138540, 'zhTW', '向前一步，收下我的禮物，歡迎加入永生的行列！', '', 28153),
(138539, 'zhTW', '這是我們的家園，我們願意不計代價守住這座港口…至死方休！', '', 28153),
(138538, 'zhTW', '不！', '不！', 28153),
(138537, 'zhTW', '塞斯拉克以為我們不堪一擊，輕鬆就能弄死，你們同意嗎？', '', 28153),
(138535, 'zhTW', '我很快就會復活…很快就會去找你，加姆波亞…', '', 28153),
(138534, 'zhTW', '我自己的大副帶頭叛變？我會讓你悔不當初！', '', 28153),
(138533, 'zhTW', '哈！哪來的白目膽敢挑戰我？', '', 28153),
(138532, 'zhTW', '', '母親…會殺了你…', 28153),
(138531, 'zhTW', '', '你們不必抵抗，庫爾提拉斯是禍心女巫會的！', 28153),
(138530, 'zhTW', '內陸人，我們會保護小姐，你去殺掉首領！', '', 28153),
(138529, 'zhTW', '', '母親會殺了你，露西爾‧威奎斯特！', 28153),
(138528, 'zhTW', '這到底是什麼東西？', '', 28153),
(138527, 'zhTW', '陷阱無法繼續牽制他們，敵人又來了！', '', 28153),
(138526, 'zhTW', '卡卓恩，冷靜一點，我們還是有辦法擊敗札佐克斯。', '卡卓恩，冷靜一點，我們還是有辦法擊敗札佐克斯。', 28153),
(138521, 'zhTW', '', '謝謝你，治安官。我們走吧？', 28153),
(138520, 'zhTW', '威奎斯特小姐，你可以走了…我向你道歉…', '', 28153),
(138519, 'zhTW', '注意！在此宣布審判結果，對造箭師谷地下詛咒的女巫，其實另有其人。', '', 28153),
(138518, 'zhTW', '', '太好了。我們現在 - ', 28153),
(138517, 'zhTW', '…我只需要再弄個鮮血食人妖來。他們為數眾多，而你的末日已近！', '', 28153),
(138516, 'zhTW', '不！娜娜夸格！現在我必須要…', '', 28153),
(138515, 'zhTW', '哈哈…你的努力會全部化為泡影，你不可能制止我的力量！', '', 28153),
(138514, 'zhTW', '你真的認為有用嗎？血神的力量在我的體內流動，你阻止不了我的！', '', 28153),
(138513, 'zhTW', '我的力量…消失了！哈哈…你一定是沒有其他辦法了，才會認為這招有效吧！', '', 28153),
(138509, 'zhTW', '小心！樹林裡有敵人！', '', 28153),
(138502, 'zhTW', '就這樣了！在不傷害我自己的前提下，這已經是我能給予的最大限度了。快去燒掉骷髏堆。', '', 28153),
(138501, 'zhTW', '在我分給你部份火焰魔精的時候，給我專心一點…', '', 28153),
(138500, 'zhTW', '我準備好要接受你的火焰魔精，用它來摧毀墓塚。', '我準備好要接受你的火焰魔精，用它來摧毀墓塚。', 28153),
(138499, 'zhTW', '', '好吧，看樣子我們要對這些女巫主動宣戰了。我知道應該怎麼做。', 28153),
(138498, 'zhTW', '他…被抓走了，小姐。在我們聽到你在接受審判的時候，正在想辦法營救他。', '', 28153),
(138497, 'zhTW', '', '我父親呢？他對這件事採取了什麼應對措施？', 28153),
(138496, 'zhTW', '山那頭有很多地方都被她們佔領了。我們只剩下一點點人在防守亞羅姆之地。', '', 28153),
(138495, 'zhTW', '小姐，情況非常危急。女巫會的影響已經擴及佐司瓦各地了。', '', 28153),
(138494, 'zhTW', '', '元帥！女巫會是怎麼回事？告訴我到底發生了什麼事！', 28153),
(138449, 'zhTW', '', '哇！看看老贊姆蘭過去的模樣！', 28153),
(138448, 'zhTW', '', '贊姆蘭真是個混蛋，對吧？', 28153),
(138439, 'zhTW', '拿起塑像，集合船員。', '', 28153),
(138438, 'zhTW', '塞斯拉克奪不走我們的家園，今天不會，永遠不會。', '', 28153),
(138437, 'zhTW', '我…我…一定還有別的辦法，船長。船員…', '', 28153),
(138436, 'zhTW', '你是要騙我吧！對不對？', '沒有你的話我一定會死在這裡！', 28153),
(138435, 'zhTW', '沒時間介紹了。我不要再多花一分鐘待在這個礦坑。', '沒時間介紹了。我不要再多花一分鐘待在這個礦坑。', 28153),
(138434, 'zhTW', '別質疑我的命令！把每個人送上祭壇，動作！', '', 28153),
(138433, 'zhTW', '我當然很高興見到你。', '我當然很高興見到你。', 28153),
(138432, 'zhTW', '我不知道你是誰、想要什麼，但是謝了。', '我不知道你是誰、想要什麼，但是謝了。', 28153),
(138431, 'zhTW', '你救了我的命，真的。我搞不好會死在這下面！', '你救了我的命，真的。我搞不好會死在這下面！', 28153),
(138430, 'zhTW', '我的手臂也許疲累，但是我的雙腿迫不及待要衝出這裡！', '我不知道你是誰，目的是什麼，但感謝你。', 28153),
(138429, 'zhTW', '該死的沙子！該死的蛇！贊姆蘭港是我的！', '', 28153),
(138428, 'zhTW', '我欠你一次，陌生人。', '我欠你一次，陌生人。', 28153),
(138427, 'zhTW', '他們數量太多了，船長！我們必須撤退，不然整船的人都會被殺光。', '', 28153),
(138426, 'zhTW', '把那些蛇一刀兩斷！不要手軟！', '', 28153),
(138373, 'zhTW', '祈禱我能跑得比惡徒還快吧！', '', 28153),
(138316, 'zhTW', '謝謝你，$c。我會在某個比較安全的地方跟你談。', '', 28153),
(138288, 'zhTW', '別後退！不是死在塞斯拉克手中，就是死在我手中。', '', 28153),
(138282, 'zhTW', '集合船員，每一個醉醺醺的海盜都給我到前門去。', '', 28153),
(138281, 'zhTW', '沒人能從我手中奪走它，想都別想！', '', 28153),
(138280, 'zhTW', '他們就跟其他人一樣蠢。這裡是贊姆蘭港！我的港口！', '', 28153),
(138279, 'zhTW', '贊姆蘭船長，塞斯拉克大軍逼近！數也數不清！', '', 28153),
(138264, 'zhTW', '飛行工程師克拉佐為你服務！', '', 28153),
(138247, 'zhTW', '離開我的港口！那些沙丘才是你真正的墓地。', '', 28153),
(138242, 'zhTW', '除了又硬又髒的衣服，你們根本一無所有，你們在我眼裡早就是個死人。', '', 28153),
(138240, 'zhTW', '除了付船資的人外，你們誰都不准踏上我的船一步。', '', 28153),
(138238, 'zhTW', '受死吧，你這個毫無用處的垃圾。', '', 28153),
(138235, 'zhTW', '如果你不讓我們上船，我們都會死！', '如果你不讓我們上船，我們都會死！', 28153),
(138234, 'zhTW', '一邊走，難民們！海盜先上船！', '', 28153),
(138233, 'zhTW', '求求你，贊姆蘭。讓我們上船，塞斯拉克會殺了我們！', '求求你，贊姆蘭。讓我們上船，塞斯拉克會殺了我們！', 28153),
(138232, 'zhTW', '只要有多餘的空間，我們能載就載。', '', 28153),
(138224, 'zhTW', '', '你來的時機很不湊巧，內陸人。\n\n你來做什麼？', 28153),
(138214, 'zhTW', '…好吧，那就我來了。', '', 28153),
(138213, 'zhTW', '', '一點也不。', 28153),
(138212, 'zhTW', '沒這回事。', '', 28153),
(138211, 'zhTW', '', '不會。', 28153),
(138210, 'zhTW', '我們殲滅了好幾群塞斯拉克，只因為他們殺了我們幾個人，只有我覺得這樣有點殺太多人嗎？', '', 28153),
(138209, 'zhTW', '真讓人鬆一口氣，但我想，那對我來說有點太超過了。', '', 28153),
(138208, 'zhTW', '', '啊哈哈！那太驚人了！而且你還活著！', 28153),
(138203, 'zhTW', '放出紙飛艇！', '', 28153),
(138202, 'zhTW', '你又辦到了，朋友！做得好！', '', 28153),
(138200, 'zhTW', '穴居怪跟蹤我到這裡。這全是我的錯！請幫幫我，$n！', '', 28153),
(138123, 'zhTW', '誰會想到，托爾托也能這麼逍遙自在？！', '', 28153),
(138122, 'zhTW', '我能感覺到風鑽進我的殼裡！', '', 28153),
(138121, 'zhTW', '我就像鳥一樣自由！', '', 28153),
(138120, 'zhTW', '爸爸，你做得真好！', '', 28153),
(138118, 'zhTW', '別放手別放手別放手啊！！！', '', 28153),
(138075, 'zhTW', '朋友，可以過來幫我選馬嗎？一定要最完美的馬才可以！', '', 28153),
(138074, 'zhTW', '偷懶的工人最愛偷酒，如果你找不到烈酒，就去搜他們的身。', '', 28153),
(138073, 'zhTW', '我把其他的貨物藏在水下，讓它們冷卻下來。', '', 28153),
(138072, 'zhTW', '你沒事，活跳跳的$pr。要是你想喝點什麼，就說一聲。', '', 28153),
(138071, 'zhTW', '', '喝！', 28153),
(138070, 'zhTW', '', '你該慶幸我踢不到更高的地方！別否認！是你觸動了陷阱！', 28153),
(138069, 'zhTW', '喔嗚！我的脛骨！', '', 28153),
(138068, 'zhTW', '我的爛攤子？我的爛攤子？？我想你才是罪魁禍首，你這叫人無法忍受的…', '', 28153),
(138067, 'zhTW', '', '－為了收你的爛攤子！', 28153),
(138066, 'zhTW', '', '讓我們離開這裡，尋找交易夥伴，我快餓死了。', 28153),
(138065, 'zhTW', '', '嘿，我一路上拿了夠多寶石和飾品，這個月都不用擔心錢的問題。', 28153),
(138064, 'zhTW', '', '對，對，我也愛你們大家。', 28153),
(138061, 'zhTW', '', '大家，這裡沒有我們的事了，收拾行李，準備上路。', 28153),
(138060, 'zhTW', '', '不能說我很驚訝，驅除詛咒只是姑且一試。', 28153),
(138059, 'zhTW', '想看看香腸是怎麼灌的嗎？', '', 28153),
(138058, 'zhTW', '誰拿了你的培根？是我！嘿嘿！', '', 28153),
(138057, 'zhTW', '你很適合做成上好的培根！', '', 28153),
(138056, 'zhTW', '我要…絞碎…你…', '', 28153),
(138055, 'zhTW', '你…死定…了…', '', 28153),
(138054, 'zhTW', '', '願風承載著你，$p…還有不要成為他們的一員，好嗎？', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(138053, 'zhTW', '', '我會偷偷潛入商隊，讓每個人準備好在你解除詛咒後仔細搜索這個地方。', 28153),
(138052, 'zhTW', '', '這就是我找到的紙條，只需要再幾個東西，你就能執行儀式。', 28153),
(138051, 'zhTW', '真的很感謝你救了我們，$c。不過，你忙著破除詛咒，現在一定餓了吧。\n\n要不要來點香腸？', '', 28153),
(138050, 'zhTW', '請好好享受這個盛宴！騎馬遛達！大吃大喝！親愛的朋友，你就是我的貴賓啊。', '', 28153),
(138049, 'zhTW', '朋友，你不只救了我兒子，還救了整個慶典！這一定會成為大家津津樂道的故事！', '', 28153),
(138048, 'zhTW', '', '你是為了食物來的，還是別的事？', 28153),
(138047, 'zhTW', '復活中', '復活中', 28153),
(138046, 'zhTW', '', '在你尋找其他塑像的時候，我會待在這裡。找到所有塑像後，就帶回來這裡。', 28153),
(138045, 'zhTW', '', '另一個塑像，可以幫我拿過來嗎？', 28153),
(138044, 'zhTW', '', '我想這裡應該是贊姆蘭的會客廳，到處都是寶藏！', 28153),
(138042, 'zhTW', '重新整隊！絕對不能退縮！', '', 28153),
(138040, 'zhTW', '', '米基很可能已經死了，你必須趁早遠離贊姆蘭。', 28153),
(138039, 'zhTW', '', '你是一個又大又肥的$pr天使！我的英友！', 28153),
(138038, 'zhTW', '他們把阿娜帶去南邊，但我要離開這裡了！', '', 28153),
(138037, 'zhTW', '等我力量恢復，就會回神廟去。我會在那裡等你。', '', 28153),
(138036, 'zhTW', '我終於自由了。', '', 28153),
(138035, 'zhTW', '快點回來找我，諾拉。', '', 28153),
(138034, 'zhTW', '', '要是我們現在離開，我們在沙丘根本找不到食物。', 28153),
(138033, 'zhTW', '', '不，你心裡明白，我們不行。', 28153),
(138032, 'zhTW', '你不需要這樣，諾拉。我們可以收拾行李，從此拋開贊姆蘭。', '', 28153),
(138031, 'zhTW', '', '我不在的時候，商隊就交給你打理了，維吉。', 28153),
(138029, 'zhTW', '我離開很久了，希望裡面還有我的朋友。', '', 28153),
(138028, 'zhTW', '等你找到艾胥凡公司賣武器給這些人的證據之後，就可以到山上的大門來找我。', '', 28153),
(138026, 'zhTW', '好，我拿到你的…腳了。接下來呢？', '好，我拿到你的…腳了。接下來呢？', 28153),
(138025, 'zhTW', '這絕對是近年來最熱鬧的慶典！騎上古柏，讓那些穴居怪知道你們的厲害。古柏打架最猛了！', '', 28153),
(138024, 'zhTW', '落港村上上下下都欠你一份人情，$c。 \n\n我真想知道有什麼辦法能好好報答你。', '', 28153),
(138023, 'zhTW', '你跟古柏真是完美搭檔！歡迎你隨時騎著古柏在莊園裡到處逛逛。', '', 28153),
(138021, 'zhTW', '許多人不知道你為他們做了什麼事，但我永遠不會忘記。', '', 28153),
(138020, 'zhTW', '', '可惡的蠢貨！你竟敢到我的地盤來撒野！？', 28153),
(138019, 'zhTW', '', '你叫再大聲也沒人會來救你！', 28153),
(138018, 'zhTW', '盛大歡迎我們尊敬的客人，$n$g大人:女士;！', '', 28153),
(138017, 'zhTW', '請容我宣布$n$g大人:女士;的到來！', '', 28153),
(138016, 'zhTW', '歡迎$n$g大人:女士;大駕光臨諾爾威頓莊園，這是我的榮幸！', '', 28153),
(138015, 'zhTW', '', '我是阿珍，在這些海妖把我們引過來之前，我是一艘商船上的傭兵。$B$B這些傢伙把我從潮間帶救了起來，為我取了一個綽號，從那之後我們就像家人一樣。$B$B他們或許看來有點怪，但他們是正直的好人。對他們某些人來說，在這裡被沖上岸是好事，讓他們遠離了以前的辛苦生活，是一個重新開始的機會。其他人則努力活下去，直到他們有辦法回家。', 28153),
(138014, 'zhTW', '森胥竺用雷霆之杯幫我做了杯飲料。多虧有森胥竺，我們很快都能和亞昆達成為一體了。', '', 28153),
(138013, 'zhTW', '', '凱爾瓦克斯…他手上有許多祭品…都能殺掉你…', 28153),
(138012, 'zhTW', '', '我會把你加入凱爾瓦克斯的屍體祭品行列！', 28153),
(138009, 'zhTW', '別－別把他們嚇跑，諾拉。我－我們需要他們幫忙。', '別－別把他們嚇跑，諾拉。我－我們需要他們幫忙。', 28153),
(138008, 'zhTW', '告訴我，陌生人。你有聽過贊姆蘭的傳說嗎？', '告訴我，陌生人。你有聽過贊姆蘭的傳說嗎？', 28153),
(137999, 'zhTW', '我看我還是到後面那邊去好了，呃，那邊的光線才看得清楚。祝你好運！', '', 28153),
(137997, 'zhTW', '<調查背包>', '<調查背包>', 28153),
(137993, 'zhTW', '<這是個小孩用的背包。上面別著「初級冒險者」的徽章。>', '', 28153),
(137988, 'zhTW', '我再拿一點點寶藏就走…', '我再拿一點點寶藏就走…', 28153),
(137987, 'zhTW', '謝謝你，我不會回頭。', '謝謝你，我不會回頭。', 28153),
(137986, 'zhTW', '我犯了一個大錯。', '我犯了一個大錯。', 28153),
(137985, 'zhTW', '你看到他們怪物般的寵物了嗎？這個地方就是一場夢魘。', '你看到他們怪物般的寵物了嗎？這個地方就是一場夢魘。', 28153),
(137984, 'zhTW', '謝謝你，$pr，我差點就撐不下去了。', '謝謝你，$pr，我差點就撐不下去了。', 28153),
(137983, 'zhTW', '我欠你一份人情。', '我欠你一份人情。', 28153),
(137982, 'zhTW', '整個商隊只剩下我一個人…', '整個商隊只剩下我一個人…', 28153),
(137981, 'zhTW', '我看到的東西…', '我看到的東西…', 28153),
(137926, 'zhTW', '你的朋友死了，$pr。這不是凡人可以來的地方。', '', 28153),
(137925, 'zhTW', '', '所以有個叫贊姆蘭的食人妖過去曾經是這個港口的老大？那這裡一定是他的會客廳。', 28153),
(137924, 'zhTW', '好吧…原本是托爾托朝聖之旅，要去聽托加說故事。不過…沒關係，你們可以一起來。', '', 28153),
(137913, 'zhTW', '我有專門對付你這種討厭鬼的藥劑！', '', 28153),
(137912, 'zhTW', '我之前總是很喜歡那小子…我是說，機器人。', '', 28153),
(137911, 'zhTW', '我曾經擁有一個玩具機器人。我跟一個波拉勒斯地精買的一個需要上發條的小夥伴。', '', 28153),
(137909, 'zhTW', '先去收集你溝通時需要用到的東西，這是邁向救贖的開端。', '', 28153),
(137908, 'zhTW', '別讓森胥竺等太久…但你如果去找他千萬小心！他可不是什麼好惹的角色。', '', 28153),
(137907, 'zhTW', '%s開始嚷嚷著自己要為自己的行為負責，持續講了好幾分鐘。', '', 28153),
(137906, 'zhTW', '嗯…應該是我的羅盤吧。它從來沒有讓我走錯過！好吧，在我們被困在這裡之前是沒有。但是不能說是羅盤的錯，我是說你總不能怪一個沒有生命的東西 - ', '', 28153),
(137905, 'zhTW', '好。你們可以一起來，不過不要大聲喧嘩！我們是去朝聖，不是野餐。', '', 28153),
(137903, 'zhTW', '', '真令人訝異…不過我們還有事情要做。現在只剩下兩個羅亞，我們必須和托爾托人一起去見烏龜的羅亞，托加。', 28153),
(137902, 'zhTW', '', '你得到伯昂撒姆第的協助…還殺了希爾雷克？！', 28153),
(137901, 'zhTW', '噢，很簡單啊！我值得信任的午餐盒。午餐盒裡從來沒有出現過難吃的東西。我好想它。', '', 28153),
(137900, 'zhTW', '', '終於自由了！', 28153),
(137899, 'zhTW', '女士下一個束縛的就是你的靈魂！', '', 28153),
(137898, 'zhTW', '(告訴塔蘭姬你獲得伯昂撒姆第協助和殺死希爾雷克的事。)', '(告訴塔蘭姬你獲得伯昂撒姆第協助和殺死希爾雷克的事。)', 28153),
(137897, 'zhTW', '女士下一個利用的就是你的靈魂！', '', 28153),
(137896, 'zhTW', '為她的榮耀而戰！', '', 28153),
(137895, 'zhTW', '我為主人奉獻生命！', '', 28153),
(137894, 'zhTW', '', '你必須現在離開…我即將產生變化，而我不希望讓你看到我蛻變後的樣子…', 28153),
(137893, 'zhTW', '我叫比爾，你有東西要修理就來找我吧。', '', 28153),
(137892, 'zhTW', '', '對我來說已經太遲了…但其他人還有一線希望。', 28153),
(137891, 'zhTW', '嘿，旅行者！你和我們一樣是被潮水沖上岸的嗎？$B$B我知道這不怎麼樣，但歡迎你在我們的小營地住下來，住多久都行。', '', 28153),
(137890, 'zhTW', '去沙漠裡找出失蹤的學徒。我會待在這裡等你。', '', 28153),
(137889, 'zhTW', '你最喜歡你在船難中失去的什麼東西？', '你最喜歡你在船難中失去的什麼東西？', 28153),
(137888, 'zhTW', '有東西可以吃嗎？', '', 28153),
(137887, 'zhTW', '', '看來不太妙，真的不妙，大家快下車！快！', 28153),
(137886, 'zhTW', '', '那些都是賈克拉傑的人！', 28153),
(137885, 'zhTW', '', '那些食人妖看起來不像是你的朋友。', 28153),
(137869, 'zhTW', '蠢貨！你早該抓緊機會逃命！我一定會得到亞昆達的力量！', '', 28153),
(137860, 'zhTW', '', '朵朵！點點！等等！危險，不要亂跑！', 28153),
(137857, 'zhTW', '哇，我看看…你平安回來了！', '', 28153),
(137851, 'zhTW', '為了塞斯拉克帝國的榮耀！', '為了塞斯拉克帝國的榮耀！', 28153),
(137810, 'zhTW', '呃啊！我的腿…好像斷了。', '', 28153),
(137807, 'zhTW', '動手吧。', '動手吧。', 28153),
(137806, 'zhTW', '儀式正進行到高潮，希爾雷克隨時都可能現身，你準備好了嗎？', '', 28153),
(137805, 'zhTW', '和我在儀式法陣那會面。', '', 28153),
(137789, 'zhTW', '小心，$c。', '小心，$c。', 28153),
(137788, 'zhTW', '<魔法連結讓羅亞的身體癱瘓了。>', '', 28153),
(137787, 'zhTW', '歡迎來到我的神廟，$n。感謝你英勇的作為，這裡永遠都會熱烈歡迎你的到來。', '', 28153),
(137785, 'zhTW', '', '謝謝你們兩位。你們的所作所為對我…以及全體贊達拉有重大意義。', 28153),
(137784, 'zhTW', '', '我應該可以說服納茲米爾的其他托爾托人幫忙。說不定修克和卡喬許也會加入！', 28153),
(137783, 'zhTW', '好啦，公主，我們會幫你一起對抗血神，別再拿這件事情煩我了！', '', 28153),
(137782, 'zhTW', '', '拉斯克，好好照顧那位羅亞。這位英雄，我還有事情要請你幫忙。', 28153),
(137781, 'zhTW', '哈！淘氣的烏龜老頑童…怎麼可能乖乖安息。他重新轉生降世了！', '', 28153),
(137780, 'zhTW', '', '這到底是什麼…', 28153),
(137779, 'zhTW', '', '我向你發誓，托加，在我們把鮮血食人妖和古翰斬草除根以前，我絕不懈怠。', 28153),
(137778, 'zhTW', '', '我也會讓大家知道你是多麼英勇地對抗古翰。', 28153),
(137777, 'zhTW', '再見，托加。我會記得你說過的故事…還會說給別人聽。', '', 28153),
(137776, 'zhTW', '', '你很強，但你在我掌握的力量面前微不足道！', 28153),
(137764, 'zhTW', '', '好…我們回祭壇去吧。', 28153),
(137763, 'zhTW', '呼！我要休息一下。', '', 28153),
(137762, 'zhTW', '', '啊…不敢相信。我們做到了！', 28153),
(137758, 'zhTW', '', '我和部落的勇士…絕對饒不了你…我們會把你大卸八塊，讓你死無全屍！', 28153),
(137757, 'zhTW', '', '我…我要結束這一切！我不會再讓我的人民…生活在你…以及鮮血食人妖所帶來的恐懼之中！', 28153),
(137755, 'zhTW', '這不…代表…什麼！他會找到…別的軀體。封印…會解除…古翰會…重獲自由！', '', 28153),
(137754, 'zhTW', '快！在它發現我是更大的威脅前幹掉它！', '', 28153),
(137753, 'zhTW', '嚐嚐我值得信賴的十字弓吧，卑鄙的惡魔！', '', 28153),
(137752, 'zhTW', '別一直亂動！牠要是一直動我就沒辦法打中牠！', '', 28153),
(137751, 'zhTW', '', '你在幹嘛？守衛，來我這！', 28153),
(137750, 'zhTW', '啊啊！你們不是古翰的對手！乖乖受死吧！', '', 28153),
(137749, 'zhTW', '', '為了托加！', 28153),
(137748, 'zhTW', '', '所有人！上！', 28153),
(137747, 'zhTW', '你們在…白費…我…無人能…什麼？不，不！', '', 28153),
(137746, 'zhTW', '', '狂妄自大只會自取滅亡。你的力量根本保護不了你！', 28153),
(137745, 'zhTW', '你們是…白費工夫。我…無人能敵。', '', 28153),
(137744, 'zhTW', '', '我們殺了古翰的使者，不知道其他人會有什麼反應！', 28153),
(137743, 'zhTW', '我已經很久沒有火冒三丈了，為了托加！', '', 28153),
(137742, 'zhTW', '', '我們走吧，為了贊達拉…還有為了托加！', 28153),
(137736, 'zhTW', '', '偉大的希爾雷克，我們獻給你血與肉！', 28153),
(137734, 'zhTW', '好啦，我們來了！', '', 28153),
(137733, 'zhTW', '', '來！我們要做好萬全的準備，才能成功擊敗血神的使者！', 28153),
(137732, 'zhTW', '我的小羽冠龍，要小心蜘蛛。我雖然是秘密之神，但是亞茲瑪可是間諜夫人。她老是在我的領土上留下一堆間諜到處跑，四處獵捕我的孩子。', '', 28153),
(137731, 'zhTW', '我準備好要進去了。', '我準備好要進去了。', 28153),
(137730, 'zhTW', '', '我從來沒想過會到廢墟裡來。是不是很神奇？', 28153),
(137728, 'zhTW', '現在沒那麼強大了吧，嗯？去吧，小傢伙。去找諾加諾，就是那個叫你殺我同類的傢伙。快去咬他，我就讓你變回人類。', '', 28153),
(137721, 'zhTW', '', '這樣一定會是托爾托史上最精彩的冒險故事！為羅亞報仇，還殺了恐怖怪物的化身！', 28153),
(137720, 'zhTW', '我說啊，我們搞不好真的能殺掉古翰的使者。', '', 28153),
(137719, 'zhTW', '', '我們趕快走，去看看鮮血食人妖到底想做什麼。', 28153),
(137718, 'zhTW', '', '我們在這裡的任務完成了。亞羅姆之地見。', 28153),
(137716, 'zhTW', '', '我對付不了女巫，而且我還被困住了。', 28153),
(137715, 'zhTW', '', '謝謝你把我從這個邪惡傀儡裡面救出來。', 28153),
(137710, 'zhTW', '', '好。我們走吧。記住，別發出聲音，我可不希望看到你們兩個被抓走。', 28153),
(137709, 'zhTW', '那當然。我有比你還老的卷軸！姬莎，去幫我找出來。', '', 28153),
(137708, 'zhTW', '', '我們必須得查出鮮血食人妖到底還想幹什麼。拉斯克、姬莎，有沒有什麼辦法...可以讓我們混進去？', 28153),
(137707, 'zhTW', '', '最後，扭轉戰局的是我們的學者…', 28153),
(137706, 'zhTW', '我真的是年紀大了…', '', 28153),
(137705, 'zhTW', '血魔法！怎麼會有人想行使這種法術？', '', 28153),
(137704, 'zhTW', '我會跟其他人講述這個事件的來龍去脈。', '', 28153),
(137703, 'zhTW', '他們首先殺掉托加，現在他們要殺掉我們！這些食人妖有什麼毛病啊？', '', 28153),
(137702, 'zhTW', '他們也把我的卷軸全偷走了！幫我奪回來。', '', 28153),
(137701, 'zhTW', '總算，我轉運了！', '', 28153),
(137700, 'zhTW', '', '你阻止不了我們吃托爾托！', 28153),
(137699, 'zhTW', '', '我們不吃羅亞…但我們吃托爾托！', 28153),
(137697, 'zhTW', '', 'Kachago!', 28153),
(137696, 'zhTW', '別相信這個賣弄又腐敗的小販所說的謊言。\n\n他賣我很多手稿，結果全部都只是荒唐的假貨。\n\n如果他覺得我會不要求退費就走人的話，他可是大錯特錯。畢竟食人妖沒「那麼」長命。', '', 28153),
(137695, 'zhTW', '在得到退費之前，我不會離開的。', '', 28153),
(137694, 'zhTW', '你的敘述讓人毫無頭緒，用詞也非常差。', '', 28153),
(137693, 'zhTW', '你的書上寫的都是些不存在的地方。', '', 28153),
(137692, 'zhTW', '祝你們好運，凡人。還有…謝謝你們。', '', 28153),
(137691, 'zhTW', '你賣的是謊言，泰拉。', '', 28153),
(137690, 'zhTW', '毀掉蓋在我遺體附近的營地，就能削弱疆苟的力量。', '', 28153),
(137689, 'zhTW', '塔蘭姬公主。那些鮮血食人妖利用我的血肉來強化疆苟。', '', 28153),
(137678, 'zhTW', '', '指引我們吧，偉大的托加。告訴我們該如何阻止鮮血食人妖。', 28153),
(137677, 'zhTW', '我已經來了。你有什麼事嗎？', '', 28153),
(137676, 'zhTW', '托加！有人要見你，還不快點把頭探出來！', '', 28153),
(137675, 'zhTW', '', 'Guzincha!', 28153),
(137674, 'zhTW', '呃啊啊…', '', 28153),
(137673, 'zhTW', '啊啊啊！', '', 28153),
(137672, 'zhTW', '', '你是躲不過血神的！', 28153),
(137671, 'zhTW', '『笨山羊，快走吧，不然你會被怪物吃掉。』', '『笨山羊，快走吧，不然你會被怪物吃掉。』', 28153),
(137670, 'zhTW', '', '鮮血獻給古翰！', 28153),
(137669, 'zhTW', '『你好啊，小糖果。你好像迷路了喔！要不要跟我一起走，我帶你回家，嗯？』', '『你好啊，小糖果。你好像迷路了喔！要不要跟我一起走，我帶你回家，嗯？』', 28153),
(137668, 'zhTW', '', '你的骨頭會成為祭品！', 28153),
(137667, 'zhTW', '', '喝你的血！', 28153),
(137666, 'zhTW', '', '新鮮的肉！', 28153),
(137665, 'zhTW', '', '祖達薩會滅亡！', 28153),
(137664, 'zhTW', '我不是來這裡保衛商人或是你的。不，我的工作是擊退任何可能會從北方來的惡夢。鮮血食人妖、蛇人、聯盟，不管是什麼。\n\n還有必須打敗無聊，但大部分時間是其他的東西。你到這裡來做什麼呢？', '我不是來這裡保衛商人或是你的。不，我的工作是擊退任何可能會從北方來的惡夢。鮮血食人妖、蛇人、聯盟，不管是什麼。\n\n還有必須打敗無聊，但大部分時間是其他的東西。你到這裡來做什麼呢？', 28153),
(137663, 'zhTW', '<小山羊似乎是從某人的農場走失的。\n\n頸圈上寫的名字是「瑪茲潘」。>', '', 28153),
(137662, 'zhTW', '', '血！血！血！', 28153),
(137661, 'zhTW', '聽說，把塔蘭姬公主救回來的那個人是你，我要為此感謝你。\n\n不過他們說，把祖爾帶回來的也是你，我要為此指責你。\n\n你有什麼事？', '聽說，把塔蘭姬公主救回來的那個人是你，我要為此感謝你。\n\n不過他們說，把祖爾帶回來的也是你，我要為此指責你。\n\n你有什麼事？', 28153),
(137660, 'zhTW', '你以為我是其中一個商人嗎？我是個戰士！階級比你高，夥計。\n\n有什麼事嗎？', '你以為我是其中一個商人嗎？我是個戰士！階級比你高，夥計。\n\n有什麼事嗎？', 28153),
(137659, 'zhTW', '找到你要的東西了嗎？找不到的話就快離開。', '找到你要的東西了嗎？找不到的話就快離開。', 28153),
(137658, 'zhTW', '你的身上不會帶了什麼鮮血食人妖的巫毒吧？沒有嗎？那就好。\n\n你到底是來做什麼的？', '你的身上不會帶了什麼鮮血食人妖的巫毒吧？沒有嗎？那就好。\n\n你到底是來做什麼的？', 28153),
(137657, 'zhTW', '他們說鮮血食人妖找到新的方法滲透我們的社會。如果不能侵略我們，就會讓我們轉變。\n\n或許兩個方法一起用，不過沒什麼好擔心的。你需要什麼？', '他們說鮮血食人妖找到新的方法滲透我們的社會。如果不能侵略我們，就會讓我們轉變。\n\n或許兩個方法一起用，不過沒什麼好擔心的。你需要什麼？', 28153),
(137656, 'zhTW', '我的表親在下頭的血門進行真正的戰鬥。我呢？我被分配來照料羽冠龍，呸。\n\n現在，你有什麼事嗎？', '我的表親在下頭的血門進行真正的戰鬥。我呢？我被分配來照料羽冠龍，呸。\n\n現在，你有什麼事嗎？', 28153),
(137655, 'zhTW', '伯昂撒姆第，我們準備好讓你召喚托加的靈魂了。', '伯昂撒姆第，我們準備好讓你召喚托加的靈魂了。', 28153),
(137654, 'zhTW', '他們說要去納茲米爾、說聽過托加的故事，還說過會很有趣！', '', 28153),
(137652, 'zhTW', '羅亞的這副軀殼…滋養我…和…古翰。', '', 28153),
(137651, 'zhTW', '我代表…古翰。他…作主。你…不從…就得死。', '', 28153),
(137643, 'zhTW', '我很想聽到他們的尖叫，但你最好還是低調行事。可不想讓你也被抓。', '', 28153),
(137642, 'zhTW', '啊！自由！', '', 28153),
(137641, 'zhTW', '噢，如果你遇到一個叫沙爾俊的食人妖，用我的利爪把他的心窩刺穿！他自找的！', '', 28153),
(137640, 'zhTW', '感激不盡，夥伴！', '', 28153),
(137639, 'zhTW', '', '有了希爾雷克之裔載著我們飛行以及血之神的力量，贊達拉必將陷落！', 28153),
(137638, 'zhTW', '謝謝你幫忙跑腿，$p。離開的時候，可以請卡勒皮送一些水來嗎？', '', 28153),
(137637, 'zhTW', '小心一點！這些樹人已經狂暴化，接近它們的人都會被殺死。', '', 28153),
(137620, 'zhTW', '你的體型毫無意義，但你的靈魂遠大於這些丘陵裡的任何生物。', '', 28153),
(137619, 'zhTW', '', '謝謝你，桑博爾！希望你把能教的都教給我這個小狐狸人。', 28153),
(137618, 'zhTW', '我將一部分的力量注入這個圖騰，以供你使用，記得不要輕易使用。', '', 28153),
(137616, 'zhTW', '', '不客氣，桑博爾。我的朋友和我很樂意幫點小忙。', 28153),
(137615, 'zhTW', '真讓人意外，把這個精華交給我是明智的抉擇。', '', 28153),
(137614, 'zhTW', '', '靠！這灘水的移動速度非常快，我根本無法控制！', 28153),
(137610, 'zhTW', '', '只要調查大水坑就好，沃魯敦的大水坑不多，應該很容易發現。', 28153),
(137609, 'zhTW', '', '可以的話，弄得俗豔一點，我們想讓桑博爾印象深刻。', 28153),
(137608, 'zhTW', '', '不管那下面發生什麼事，拿到水就走，不要涉入其中。', 28153),
(137607, 'zhTW', '那下面有許多強者，$p。每次出手和選擇都應深思熟慮。', '', 28153),
(137606, 'zhTW', '你贏得榮耀與榮譽，$p。', '', 28153),
(137605, 'zhTW', '', '不管你是誰，工作一天就該得到一天的薪水。', 28153),
(137604, 'zhTW', '像$p這樣強大的破邪者不會為了錢跟怪物搏鬥，梅亞，我們這麼做都是為了榮耀！', '', 28153),
(137603, 'zhTW', '', '只要你夠努力，沒有不能修復的東西，海蘿。', 28153),
(137602, 'zhTW', '你確定我們能修好這輛貨車嗎？有一大部分都進了拉尼舒的肚子。', '', 28153),
(137601, 'zhTW', '現在是重頭戲：殺殺殺，然後收割靈魂！', '', 28153),
(137597, 'zhTW', '你很有兩下子嘛，塔蘭姬，但找我幫忙是有代價的。', '', 28153),
(137594, 'zhTW', '', '伯昂撒姆第，我們沒空在這裡耗。你要羅亞的靈魂？既然希爾雷克死了，那靈魂就歸你吧。', 28153),
(137590, 'zhTW', '哈…要不要來…做個交易？你把其他羅亞的靈魂帶過來，我就讓你見托加，嗯？', '', 28153),
(137588, 'zhTW', '我看看…嗯…你想找的靈魂，是可憐的托加對吧。', '', 28153),
(137587, 'zhTW', '我已經準備好召喚伯昂撒姆第。', '我已經準備好召喚伯昂撒姆第。', 28153),
(137586, 'zhTW', '談判沒用，我們必須找其他辦法阻止他們，或至少像你一樣，比他們更快行動。', '', 28153),
(137585, 'zhTW', '我會把話傳給卡勒皮及其他人。拉尼舒吃了$pr…還有其他的一切。', '', 28153),
(137584, 'zhTW', '哈哈，注意那些$pr腳的位置！別跌倒了！', '', 28153),
(137583, 'zhTW', '大大咬一口！吃掉面具！大家都吃$pr！', '', 28153),
(137582, 'zhTW', '', '鮮血食人妖一定會很後悔闖進來。', 28153),
(137581, 'zhTW', '<拉動燭台>', '<拉動燭台>', 28153),
(137580, 'zhTW', '<靠近細看才發現，燭台似乎與牆裡的某種機關連接在一起。>', '', 28153),
(137579, 'zhTW', '<這是一雙舊靴子。\n\n不然你以為是什麼？>', '', 28153),
(137578, 'zhTW', '<在地毯底下也找不到秘密入口。\n\n不過，這地毯還真是跟房間搭配得天衣無縫。>', '', 28153),
(137577, 'zhTW', '<令人驚訝的是，這本凸出來的書居然不是秘密入口的開關把手。>', '', 28153),
(137576, 'zhTW', '<船錨被牢牢地固定在牆上。>', '', 28153),
(137575, 'zhTW', '', '我告訴你，是鮮血食人妖。跟我來…讓他們付出代價！', 28153),
(137574, 'zhTW', '', '是誰對托加做這種事？他只是想說故事！', 28153),
(137573, 'zhTW', '托加！不！', '', 28153),
(137572, 'zhTW', '托加被殺了，像頭普通的動物一樣被殺了！', '', 28153),
(137571, 'zhTW', '所有托加的故事…永遠消逝了！', '', 28153),
(137570, 'zhTW', '一名羅亞…死了？', '', 28153),
(137569, 'zhTW', '怎麼會發生這種事？', '', 28153),
(137568, 'zhTW', '', '學者把秘密藏在這裡，以防惡人得知。', 28153),
(137563, 'zhTW', '我正在找工作。', '我正在找工作。', 28153),
(137561, 'zhTW', '', '哼！你以為我是誰，導遊嗎？我是來聽托加的故事的。', 28153),
(137560, 'zhTW', '', '我最好還是趕快動身，以免又有人來找我問東問西。', 28153),
(137559, 'zhTW', '', '注意聽，專心順著這條路走，別亂跑，你就會看到托加。他是一隻巨大的烏龜…很難錯過。', 28153),
(137558, 'zhTW', '', '哼！我怎麼做關你什麼事！輪不到你來教我怎麼朝聖。', 28153),
(137557, 'zhTW', '朝聖？你根本就只是在那裡站著！拉斯克說過，你知道要去哪裡找托加。', '朝聖？你根本就只是在那裡站著！拉斯克說過，你知道要去哪裡找托加。', 28153),
(137556, 'zhTW', '拉斯克說，你會告訴我要去哪找托加。', '拉斯克說，你會告訴我要去哪找托加。', 28153),
(137555, 'zhTW', '想幹麻？你看不出來我正在朝聖旅途嗎？', '', 28153),
(137554, 'zhTW', '嗯，我們一定合得來，公主。', '', 28153),
(137553, 'zhTW', '', '這不是第一次了！我之前跟老一輩的托爾托人打過交道…你們總是有說不完的故事。給我專心趕路！', 28153),
(137552, 'zhTW', '好，那我們出發吧，去朝拜托加。不過，切記，別喧嘩。我可不想錯過任何他說的故事！', '', 28153),
(137551, 'zhTW', '呃…好吧。我們沒興趣參與其他事務，但你們要是想同行倒是沒關係。', '', 28153),
(137550, 'zhTW', '你有什麼事？', '', 28153),
(137549, 'zhTW', '或許你該重新考慮你的答案。', '', 28153),
(137548, 'zhTW', '我只知道亞昆達。', '', 28153),
(137547, 'zhTW', '我問的是你的名字，但你開始講故事？', '', 28153),
(137546, 'zhTW', '死亡之翼？是什麼弱弱的蟲子有這種名字？', '', 28153),
(137545, 'zhTW', '你將會被賦予這位羅亞的賜福。這套系統是半成品。', '你將會被賦予這位羅亞的賜福。這套系統是半成品。', 28153),
(137544, 'zhTW', '我馬上辦。', '我馬上辦。', 28153),
(137543, 'zhTW', '', '這座峽谷裡的花草像我們一樣，都在和死神搏鬥。', 28153),
(137542, 'zhTW', '真是感激不盡，內陸人。我要盡量離這個地方越遠越好。', '真是感激不盡，內陸人。我要盡量離這個地方越遠越好。', 28153),
(137541, 'zhTW', '', '嘿，你！你喜歡火嗎？或火箭？著火的火箭呢？我有好多很酷的東西要給你看，我等不及了！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137540, 'zhTW', '我的天啊！這到底…是什麼？！', '我的天啊！這到底…是什麼啊？！', 28153),
(137537, 'zhTW', '', '喔，是沒錯啦，不過你絕對不會想穿越峽谷，因為裡面超級可怕。', 28153),
(137536, 'zhTW', '', '你們等等，這條路很不好走！', 28153),
(137535, 'zhTW', '我們一定還有別的路可以選擇…', '', 28153),
(137534, 'zhTW', '', '就在南邊。可是你要知道，那座山受到詛咒了。凡是進去的人，都沒再出來過了。', 28153),
(137533, 'zhTW', '一定是這裡沒錯，我看見前面那棟建築了。', '', 28153),
(137531, 'zhTW', '我們應該往南走，神廟就在那邊的山丘裡面。', '', 28153),
(137530, 'zhTW', '我的旅店雖然老舊，但很舒服，我向你保證。', '', 28153),
(137529, 'zhTW', '亞昆達給了我們機會拋下過去，重新開始。', '', 28153),
(137528, 'zhTW', '', '部落必須被殲滅。祖達薩會臣服在聯盟之前的！', 28153),
(137526, 'zhTW', '呃。這裡還好啦。我們要去朝拜。我有預感你會讓我們的旅程變得更加艱難。', '', 28153),
(137525, 'zhTW', '', '托爾托！你們怎麼會來到這個詛咒之地？', 28153),
(137523, 'zhTW', '你或許不會喜歡這問題的答案，$n。別搞錯了，我被放逐到這沙漠是罪有應得。', '', 28153),
(137517, 'zhTW', '你做了什麼才淪落到這來？', '你做了什麼才淪落到這來？', 28153),
(137516, 'zhTW', '把過去拋在腦後並重新開始的機會聽起來真不錯。或許這些食人妖並沒有那麼瘋狂。', '', 28153),
(137515, 'zhTW', '我的命是洛琪拉救的。沒有她的領導，我們這些流放者不可能在沙漠中存活。', '', 28153),
(137509, 'zhTW', '好啦，拿去！放我走吧！', '', 28153),
(137508, 'zhTW', '魯伯特，跳舞吧！', '', 28153),
(137505, 'zhTW', '我有看到你問起的那個人。她輕易地通過了審判，但是看起來沒興趣在這久待。\n\n她在找些什麼東西。她問問題，就跟你一樣。但她離開地就跟她來的時候一樣快。她往南去，而你也該這麼做。\n\n這間神廟不安全。', '', 28153),
(137504, 'zhTW', '', '我們都是亞昆達。', 28153),
(137502, 'zhTW', '魯伯特，過來！', '', 28153),
(137501, 'zhTW', '你看到戰衛洛琪拉了嗎？', '你看到戰衛洛琪拉了嗎？', 28153),
(137500, 'zhTW', '亞昆達賜予我們力量。', '亞昆達賜予我們力量。', 28153),
(137499, 'zhTW', '沒有亞昆達，我們什麼都不是。', '沒有亞昆達，我們什麼都不是。', 28153),
(137498, 'zhTW', '亞昆達把他的力量借給了我們。', '亞昆達把他的力量借給了我們。', 28153),
(137497, 'zhTW', '我們都是亞昆達。', '我們都是亞昆達。', 28153),
(137496, 'zhTW', '她不是亞昆達。', '', 28153),
(137495, 'zhTW', '', '如果她不是亞昆達，她就不能來這裡。', 28153),
(137494, 'zhTW', '只有亞昆達才能進入這座神廟。', '', 28153),
(137493, 'zhTW', '這裡沒有叫做那個名字的人。', '', 28153),
(137492, 'zhTW', '', '我只見那些匹配擁有亞昆達神力的人。', 28153),
(137491, 'zhTW', '你為什麼如此關心那些不是亞昆達的人？', '', 28153),
(137490, 'zhTW', '', '洛琪拉？好奇怪的名字。', 28153),
(137489, 'zhTW', '裡面黏糊糊的！嚼！嚼！', '', 28153),
(137488, 'zhTW', '小聲一點…我們不想要這些邪教徒瘋子知道我們會像這樣講話。', '', 28153),
(137487, 'zhTW', '你想和亞昆達為伍嗎，孩子？好好服侍我，我就會達成你的願望…', '', 28153),
(137486, 'zhTW', '你敢！不准喝。', '', 28153),
(137485, 'zhTW', '嚼！嚼！嚼！', '', 28153),
(137484, 'zhTW', '我第一次說的時候你沒聽見嗎？你用了那個聖杯，你就會後悔。', '', 28153),
(137483, 'zhTW', '薩爾加會在北邊的高塔中睡覺，只要一滴我的毒藥，她就永遠不會醒來。記得把鑰匙拿回來！', '', 28153),
(137482, 'zhTW', '', '我們先前見過嗎？你看起來很眼熟…', 28153),
(137480, 'zhTW', '等到我出來，有得你好受的！', '', 28153),
(137479, 'zhTW', '把我放出來，不然我發誓你一定會後悔！', '', 28153),
(137478, 'zhTW', '在我帶來惡夢之前，放我出來！', '', 28153),
(137477, 'zhTW', '我從沒看過像那樣的東西…那塊肉只是讓拉尼舒變得更餓，老灌木根本毫無機會！', '', 28153),
(137476, 'zhTW', '哈！這招有用…噢！這招超痛！別再來了！', '', 28153),
(137475, 'zhTW', '我沒同意你吃掉我，你這隻愚蠢的生物！', '', 28153),
(137472, 'zhTW', '', '', 28153),
(137466, 'zhTW', '去北邊找大食客妮妮。那是一條身邊無數屍體的巨蟲。你去解決她，拿走她的面具！', '', 28153),
(137465, 'zhTW', '', '托加的血是我們的力量來源！', 28153),
(137464, 'zhTW', '', '我們拿到托加的血了！', 28153),
(137463, 'zhTW', '啊，終於不癢了，獨處是最棒的事。', '', 28153),
(137462, 'zhTW', '魯伯特，別理那個差勁的獵人。你一定能成為完美的夥伴。', '', 28153),
(137461, 'zhTW', '那是熊。趁霍頓家的人還沒看到，趕快把熊處理掉。', '那是熊。趁霍頓家的人還沒看到，趕快把熊處理掉。', 28153),
(137460, 'zhTW', '多麼蠢啊，我在打獵的時候撿到這隻狗。我決定教牠一些把戲。', '', 28153),
(137459, 'zhTW', '那－那是一隻熊嗎！？', '那－那是一隻熊嗎！？', 28153),
(137458, 'zhTW', '魯伯特，這慷慨的$c帶了禮物給我們。快說謝謝，跳舞吧！', '', 28153),
(137457, 'zhTW', '歡迎你，英勇的亞昆達。', '', 28153),
(137456, 'zhTW', '歡迎你，寧靜的亞昆達。', '', 28153),
(137455, 'zhTW', '歡迎你，靈巧的亞昆達。', '', 28153),
(137454, 'zhTW', '我斬殺了死亡之翼，你一定聽過我吧？', '我斬殺了死亡之翼，你一定聽過我吧？', 28153),
(137453, 'zhTW', '我戰勝巫妖王的故事沒傳到你家那裡？', '我戰勝巫妖王的故事沒傳到你家那裡？', 28153),
(137452, 'zhTW', '我擊退了燃燒軍團，真的假的？你不知道我是誰？', '我擊退了燃燒軍團，真的假的？你不知道我是誰？', 28153),
(137451, 'zhTW', '快離開，你這隻膽小的害蟲！去吃你愛吃的肉，別來殘害這些樹！', '', 28153),
(137450, 'zhTW', '我的名字是靈巧的亞昆達。', '我的名字是靈巧的亞昆達。', 28153),
(137449, 'zhTW', '我的名字是寧靜的亞昆達。', '我的名字是寧靜的亞昆達。', 28153),
(137448, 'zhTW', '我的名字是英勇的亞昆達。', '我的名字是英勇的亞昆達。', 28153),
(137447, 'zhTW', '我的名字沒有改變。', '我的名字沒有改變。', 28153),
(137446, 'zhTW', '你的人生自此不再毫無意義了。\n\n你過去的行事和作為必須被遺忘。\n\n告訴全部人你真正的名字吧！', '', 28153),
(137444, 'zhTW', '許多人來我們的神廟避難，但只有證明自己具備資格的人能獲得進來。', '', 28153),
(137438, 'zhTW', '哈！我們可以一起殺掉這隻野獸！', '', 28153),
(137437, 'zhTW', '長牙因為有了盟友而重振精神，發動攻擊！', '', 28153),
(137436, 'zhTW', '長牙發出勝利的長嗥，對你表示感謝，並且終於得以安息。', '', 28153),
(137435, 'zhTW', '謝謝你。我可以安息了。', '', 28153),
(137434, 'zhTW', '歡迎來到我的林地，$p…或者說林地的殘骸。', '', 28153),
(137432, 'zhTW', '我受不了了，夥計！我再也受不了了！', '', 28153),
(137431, 'zhTW', '算了，夥計！如果我獻祭你，或許希爾雷克會給我力量！', '', 28153),
(137430, 'zhTW', '我不要再當祭品了！反抗吧我的兄弟們！', '', 28153),
(137429, 'zhTW', '你和那大祭司可以去死！', '', 28153),
(137428, 'zhTW', '我才不要像動物一樣活著！', '', 28153),
(137427, 'zhTW', '大祭司要求你獻上服從的象徵。\n[釋放苦力。]', '大祭司要求你獻上服從的象徵。\n[釋放苦力。]', 28153),
(137426, 'zhTW', '帶食物來或是被吃掉！', '', 28153),
(137425, 'zhTW', '在沃魯敦，什麼都變得很困難。^n^n我需要一些木頭修理我的篷車。', '', 28153),
(137424, 'zhTW', '', '哈哈…你晚了一步…血神…降臨！', 28153),
(137423, 'zhTW', '', '信使將會完全無缺！你無法阻止的！', 28153),
(137422, 'zhTW', '這對一名$pr來說或許很好笑，但拉尼舒非常讓人頭痛。^n^n他們讓人有點想笑就是了。', '', 28153),
(137421, 'zhTW', '沒人能阻止我們！人們將開始起義！', '', 28153),
(137420, 'zhTW', '你最好小心點，老兄。你的女人能掌權的時間沒多久了！', '', 28153),
(137419, 'zhTW', '你會見識到的，老兄。我的弟兄與我將離開這裡，取得統治！', '', 28153),
(137418, 'zhTW', '你是來再次懲罰我的嗎？我不會怕你的！', '', 28153),
(137417, 'zhTW', '托加的血是我們的力量來源！', '', 28153),
(137416, 'zhTW', '我們拿到托加的血了！', '', 28153),
(137414, 'zhTW', '我們會把羅亞的肉帶給其他人。你無法阻止我們！', '', 28153),
(137413, 'zhTW', '羅亞肉是我們的，你的肉也會是我們的！', '', 28153),
(137412, 'zhTW', '', '看來，我們得準備殺幾個女巫了。', 28153),
(137411, 'zhTW', '', '古老的燼火會就此重生了。', 28153),
(137410, 'zhTW', '', '書卷裡的知識，會賦予你和我們的部隊需要的力量，去消滅那群玷污這裡的邪惡女巫。', 28153),
(137409, 'zhTW', '', '如果你想了解燼火會的奧秘，就拿起書卷吧。', 28153),
(137408, 'zhTW', '', '找到了…燼火會留下來的一切都在這裡了。你準備好要重拾遠古的歷史了嗎？', 28153),
(137407, 'zhTW', '', '快過來，書卷應該在這裡沒錯！', 28153),
(137406, 'zhTW', '', '我在說什麼啊…你當然不會有事。它想打倒你，根本還差得遠呢！', 28153),
(137405, 'zhTW', '', '我從來沒看過這麼大的傀儡！你還好嗎？', 28153),
(137404, 'zhTW', '', '希爾雷克…會幫我報仇', 28153),
(137403, 'zhTW', '', '為古翰獻上我的靈魂！', 28153),
(137402, 'zhTW', '<選擇幫助亨利‧布雷克瓦特，解決這個僵局。>', '<選擇幫助亨利‧布雷克瓦特，解決這個僵局。>', 28153),
(137401, 'zhTW', '', '羅亞肉是我們的！', 28153),
(137400, 'zhTW', '', '小心！在你後面！', 28153),
(137399, 'zhTW', '', '希爾雷克…萬…歲…', 28153),
(137398, 'zhTW', '', '我們獵羅亞肉！我們吃羅亞肉！', 28153),
(137397, 'zhTW', '', '等等…事情不太對勁。', 28153),
(137396, 'zhTW', '', '嗯…看樣子前面有石頭擋住了。你能清出一條路嗎？', 28153),
(137395, 'zhTW', '', '有了這些知識，我們總算能把佐司特趕回山裡去了。', 28153),
(137394, 'zhTW', '', '他們整理研究成果，應用在武器和戰略上，找到擊敗那些野蠻人的方法。', 28153),
(137393, 'zhTW', '', '我剛說到，戰爭的局勢之所以能扭轉，是因為學者慢慢發現了佐司特魔法的弱點。', 28153),
(137392, 'zhTW', '', '謝謝你，我剛剛還以為會被抓住。', 28153),
(137391, 'zhTW', '', '等等…小心！', 28153),
(137390, 'zhTW', '', '威奎斯特家的人都很勇猛善戰，但佐司特的魔法太過強大，當時我們幾乎就要輸了…', 28153),
(137389, 'zhTW', '', '我的祖先在跟佐司特作戰的時候，面對的傀儡就跟這些很相似。', 28153),
(137388, 'zhTW', '', '很抱歉，一定是女巫的魔法驚擾了佐司特祖先們的靈魂。我們一定要小心。', 28153),
(137387, 'zhTW', '', '小心！', 28153),
(137386, 'zhTW', '', '等等…那是什麼？', 28153),
(137385, 'zhTW', '', '不知道持續多少年了，直到我們威奎斯特家族的祖先決定不再姑息，挺身反抗。', 28153),
(137384, 'zhTW', '', '佐司瓦是這些人的家園。他們就是從這裡一再地到我們小小的村莊燒殺擄掠。', 28153),
(137383, 'zhTW', '', '很久以前，在庫爾提拉斯剛立國的時候，我們族人遇上了一群凶猛好戰的野蠻人。這些野蠻人自稱為佐司特。', 28153),
(137382, 'zhTW', '', '找到了！就在這裡！', 28153),
(137381, 'zhTW', '', '我們一定要找到入口！', 28153),
(137380, 'zhTW', '', '這裡藏著我們家族的古老秘密，那時威奎斯特家才剛在這片土地上落腳。', 28153),
(137379, 'zhTW', '', '真不敢相信我會在這裡！父親以前告訴過我這裡的故事。', 28153),
(137378, 'zhTW', '', '駕！前往亞羅姆之地，貝拉！', 28153),
(137377, 'zhTW', '', '貝拉，我需要你跟著這個人，幫忙載上找到的物資，好嗎？', 28153),
(137376, 'zhTW', '<選擇幫助長牙，解決這個僵局。>', '<選擇幫助長牙，解決這個僵局。>', 28153),
(137375, 'zhTW', '<獵人亨利‧布雷克瓦特的靈魂專注於這場永不停歇的爭鬥之中，沒有意識到你的存在。\n\n他和猛狼長牙的靈魂交戰不息，雙方誰也不肯讓步，至死不休。>', '', 28153),
(137374, 'zhTW', '<猛狼長牙死後，靈魂仍然不停地奮戰。\n\n她陷入了與獵人亨利‧布雷克瓦特永恆不息的爭戰。>', '', 28153),
(137296, 'zhTW', '', '又有鮮血可以獻給希爾雷克了！', 28153),
(137295, 'zhTW', '', '獵頭的時候到了！', 28153),
(137294, 'zhTW', '', '你會死在這裡！', 28153),
(137292, 'zhTW', '', '希爾雷克會吸乾你的鮮血！', 28153),
(137290, 'zhTW', '', '剛好！就拿你來餵蝙蝠！', 28153),
(137289, 'zhTW', '', '下一個就把你獻給希爾雷克！', 28153),
(137287, 'zhTW', '', '血神說過你會來！', 28153),
(137284, 'zhTW', '你說你想蓋堡壘？哈！不要害我笑了，哈哈！', '', 28153),
(137282, 'zhTW', '派大砲上場！把他們的破基地炸爛！', '', 28153),
(137281, 'zhTW', '哇、哇、哇！看來部落終於決定出來讓大家看看他們那副醜臉了！', '', 28153),
(137280, 'zhTW', '我每分每秒逐漸衰弱。你…你一定要幫我，不然就太遲了。', '', 28153),
(137279, 'zhTW', '朋友，你真是天生的騎士！', '', 28153),
(137278, 'zhTW', '接下來就是我最喜歡的部分了…跳躍！跳過柵欄，展現你精湛的馬術。只要多多跳躍，你的整體表現就會顯得更加精彩！', '', 28153),
(137277, 'zhTW', '粗脖幫已經把他們最喜歡用的東西教給你了，就是縛錘彈！在坐騎上好好練習，把紙飛艇打下。它們數量不多，但是價值很多分！', '', 28153),
(137276, 'zhTW', '庫爾提拉斯的騎手都需要精湛的戰鬥技巧。攻擊豺狼人目標，展現你耍魚叉的技巧！', '', 28153),
(137275, 'zhTW', '或許是兩者的結合？人熊，也或許是熊人？', '', 28153),
(137274, 'zhTW', '又是熊造成的傷口。或許是暴徒和他的寵物熊？', '', 28153),
(137271, 'zhTW', '也或許不是熊。她看起來好像和某個暴徒之類的傢伙起了衝突。', '', 28153),
(137270, 'zhTW', '這傷口好奇特。幾乎讓我聯想到熊。你看這像不像是熊造成的傷口？', '', 28153),
(137269, 'zhTW', '所有東西…都會變成沙漠…納茲米爾也一樣…！', '', 28153),
(137268, 'zhTW', '塞斯拉克帝國奪下納茲米爾！', '', 28153),
(137267, 'zhTW', '我好不簡單熬過鮮血食人妖，結果我只能拿到這個？呸！', '我好不簡單熬過鮮血食人妖，結果我只能拿到這個？呸！', 28153),
(137266, 'zhTW', '呿。托加死了，我也沒故事可講了。', '呿。托加死了，我也沒故事可講了。', 28153),
(137265, 'zhTW', '這到底是？這什麼鬼地方…我要離開！', '這到底是？這什麼鬼地方…我要離開！', 28153),
(137264, 'zhTW', '托加…死了？這是什麼狀況？', '托加…死了？這是什麼狀況？', 28153),
(137263, 'zhTW', '', '你怎敢背叛我？我要砍了你的頭！', 28153),
(137262, 'zhTW', '', '他就這樣走了。我必須把獵場看守者的這週薪水加倍才行。', 28153),
(137261, 'zhTW', '好極了！獵麋鹿比獵熊有水準多了！', '', 28153),
(137260, 'zhTW', '', '西邊有個小營地用得上-', 28153),
(137259, 'zhTW', '哈哈！做得好！繼續努力！', '', 28153),
(137258, 'zhTW', '開始！', '', 28153),
(137257, 'zhTW', '鈞吉一直在做不好的事。如果那些蜥蜴在你之前找到他，那他就糟了。', '', 28153),
(137256, 'zhTW', '好了嗎？預備…', '', 28153),
(137255, 'zhTW', '這些或許不是最美味的食材，至少不會讓我們挨餓。', '', 28153),
(137254, 'zhTW', '哮怒狂牙已死，我們走失的羊駝回來了。現在我們需要擔心的只剩摩詹波會殺死我們所有人了…', '', 28153),
(137253, 'zhTW', '羊駝不可能獨自在沙漠中生存。我們必須帶牠們回來！', '', 28153),
(137252, 'zhTW', '我們的羊駝群在攻擊中走失了，我們必須在為時已晚之前找到牠們！', '', 28153),
(137251, 'zhTW', '沙漠是一處荒涼的地方，但若你知道去哪找，還是找的到食物。', '', 28153),
(137250, 'zhTW', '沒有食物以及補給，我們撐不了多久…', '', 28153),
(137249, 'zhTW', '只要塞斯拉克繼續在這片土地橫行，和平永遠不會到來。', '', 28153),
(137248, 'zhTW', '等你準備好了，我們就進行下一步。', '', 28153),
(137247, 'zhTW', '$n佔領了紐沃農莊！', '$n佔領了紐沃農莊！', 28153),
(137246, 'zhTW', '聯盟控制了紐沃農莊。', '聯盟控制了紐沃農莊。', 28153),
(137245, 'zhTW', '聯盟控制了戰斧山脊！', '聯盟控制了戰斧山脊！', 28153),
(137244, 'zhTW', '', '拜託…我的時間…不多了。', 28153),
(137243, 'zhTW', '<食人妖的側邊有個巨大的鋸齒傷口，周圍充滿著綠色的泡沫。>', '', 28153),
(137242, 'zhTW', '', '我真的很擔心我姪女。', 28153),
(137241, 'zhTW', '', '我真高興你平安無事，$p！朵朵與點點也沒事。', 28153),
(137240, 'zhTW', '', '朵朵和點點越來越會吃了，要負責拉一整車的食人妖可不輕鬆！', 28153),
(137239, 'zhTW', '', '朵朵和點點既強壯又可靠，我們要去哪都可以靠牠們。', 28153),
(137235, 'zhTW', '一言為定。', '一言為定。', 28153),
(137234, 'zhTW', '尼可把獵鷹收在他的包包裡。', '', 28153),
(137233, 'zhTW', '啊，有個$c出現在我的巢穴。告訴我，小$r，你是來談條件的嗎？\n\n很久以前，我決定讓我的追隨者選擇任何他們也想信奉的羅亞。但想得到我的恩賜，嗯，我必須要求你成為祖達薩人心中，代表我力量的象徵。\n\n若你希望獲得我的恩賜，返回達薩亞洛之階，然後興建一座足以匹配眾神，屬於我的聖壇。\n\n做這件事，我就會視你為我獸群的一員。一言為定？', '', 28153),
(137226, 'zhTW', '放開我。', '放開我。', 28153),
(137223, 'zhTW', '你好，這位有錢人，今天你來到拾荒者神殿有什麼事？', '', 28153),
(137212, 'zhTW', '第一天：我們應該可以在午餐時間前找到北方洞穴的穴居怪。我就是知道我們可以在晚餐前有新發現！出發去冒險吧！', '', 28153),
(137175, 'zhTW', '$n佔領了諾斯弗德路口！', '$n佔領了諾斯弗德路口！', 28153),
(137174, 'zhTW', '聯盟控制了諾斯弗德路口！', '聯盟控制了諾斯弗德路口！', 28153),
(137162, 'zhTW', '啊，又一個為了古翰必須被消滅的靈魂！', '', 28153),
(137161, 'zhTW', '愚蠢的羽冠龍，你又死了。', '', 28153),
(137157, 'zhTW', '嘿嘿嘿嘿！', '', 28153),
(137156, 'zhTW', '$n佔領了高地駐營！', '$n佔領了高地駐營！', 28153),
(137155, 'zhTW', '聯盟已經控制了高地駐營！', '聯盟已經控制了高地駐營！', 28153),
(137154, 'zhTW', '這…這種自由的快感！', '', 28153),
(137153, 'zhTW', '等等…喬馬！喬馬，我做到啦！', '', 28153),
(137152, 'zhTW', '聯盟控制了元素之環！', '聯盟控制了元素之環！', 28153),
(137151, 'zhTW', '$n佔領了元素之環！', '$n佔領了元素之環！', 28153),
(137148, 'zhTW', '去吧！', '', 28153),
(137144, 'zhTW', '不！我還是不行！太快了！', '', 28153),
(137143, 'zhTW', '好，我好像…真的可以…', '', 28153),
(137142, 'zhTW', '啊啊啊啊啊！', '', 28153),
(137141, 'zhTW', '啊！撕裂！殺戮！', '', 28153),
(137140, 'zhTW', '殺！殺！殺！', '', 28153),
(137139, 'zhTW', '啊啊…擊碎！', '', 28153),
(137138, 'zhTW', '打死你！', '', 28153),
(137137, 'zhTW', '嗚哇啊啊啊！', '', 28153),
(137135, 'zhTW', '我…殺…你…', '', 28153),
(137134, 'zhTW', '崩裂…', '', 28153),
(137133, 'zhTW', '我…粉碎…', '', 28153),
(137132, 'zhTW', '你也是我的點心！', '', 28153),
(137131, 'zhTW', '不要新鮮的肉！', '', 28153),
(137130, 'zhTW', '大地毀滅你！', '', 28153),
(137129, 'zhTW', '我吃你！', '', 28153),
(137128, 'zhTW', '好，喬馬，帶我去訓練場吧。希望我這次真的可以「馬到成功」，哈哈…', '', 28153),
(137127, 'zhTW', '爸，你做到了！抓緊喔！', '', 28153),
(137122, 'zhTW', '這我的…', '', 28153),
(137121, 'zhTW', '我…殺…你…', '', 28153),
(137120, 'zhTW', '我…揍你…', '', 28153),
(137119, 'zhTW', '我揍你！', '', 28153),
(137118, 'zhTW', '我吃你！', '', 28153),
(137117, 'zhTW', '殺你！', '', 28153),
(137116, 'zhTW', '這我的寶貝！', '', 28153),
(137113, 'zhTW', '哈里遜‧瓊斯是我的偶像！布萊恩‧銅鬚也還不錯啦。', '', 28153),
(137110, 'zhTW', '你釣到一條了！', '', 28153),
(137109, 'zhTW', '噢！你勾到螃蟹了，牠很火！', '', 28153),
(137108, 'zhTW', '線斷了！', '', 28153),
(137107, 'zhTW', '是波茲嘉！', '', 28153),
(137106, 'zhTW', '波斯賈現在將吃了你！', '', 28153),
(137105, 'zhTW', '波茲嘉來了，我們上！', '', 28153),
(137104, 'zhTW', '', '我會親自把你餵給希爾雷克！', 28153),
(137101, 'zhTW', '你覺得上面會不會有泰坦的東西？我覺得一定有，不然怎麼會有穴居怪。我一定要去找泰坦留下來的東西。', '', 28153),
(137100, 'zhTW', '一定要把這些孩子禁足一輩子！', '', 28153),
(137099, 'zhTW', '雖然我的孫子總是惹麻煩，但這可不是一般的麻煩！', '', 28153),
(137098, 'zhTW', '除臟', '除臟', 28153),
(137097, 'zhTW', '好、好吧，孩子。就是現在了。朋友，你可以幫幫我嗎？', '', 28153),
(137096, 'zhTW', '快啊！我們趕快離開這裡！', '', 28153),
(137095, 'zhTW', '爸，夠了喔，我們已經拖得夠久了。你快騎上這匹馬！', '', 28153),
(137094, 'zhTW', '這匹馬不適合我，兒子。你看看牠打量我的眼神。就像要把我吃了！', '', 28153),
(137093, 'zhTW', '我喜歡這匹。這匹最漂亮！對吧？', '', 28153),
(137092, 'zhTW', '不，不行。這匹我不能騎。牠…太活蹦亂跳了！看看這步伐，我這把老骨頭真的禁不起！', '', 28153),
(137091, 'zhTW', '這匹不錯！', '', 28153),
(137090, 'zhTW', '不行，喬馬。這匹不太好。牠有點太…呃…不穩定。對！不穩定！我怕稍微動一下牠就會嚇到。', '', 28153),
(137089, 'zhTW', '這匹怎麼樣，爸？', '', 28153),
(137088, 'zhTW', '好，也拖夠久了。我們去找一匹最完美的馬吧！', '', 28153),
(137087, 'zhTW', '在開始之前，我要先準備準備。等我一下…', '', 28153),
(137086, 'zhTW', '我們把你剁了，就有更多食物！', '', 28153),
(137085, 'zhTW', '你一定可以讓主人吃個痛快', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137084, 'zhTW', '我爸爸總是在談馬！他想騎馬，但我覺得他怕它們。$b$b我完全知道怎麼幫助他！', '', 28153),
(137083, 'zhTW', '這一定就是塞斯拉克在找的東西！', '', 28153),
(137082, 'zhTW', '所以刻在符石上的故事是真的…球體真的存在！', '', 28153),
(137080, 'zhTW', '', '你的魔法騙不了我的！', 28153),
(137079, 'zhTW', '', '藥水還沒有準備好，你走吧！', 28153),
(137078, 'zhTW', '', '說，你為何打擾我的冥想？', 28153),
(137077, 'zhTW', '桑卡…凋萎者…', '', 28153),
(137076, 'zhTW', '桑卡…凋萎者…', '', 28153),
(137075, 'zhTW', '', '謝謝你的幫助，陌生人。記得把鹽擺在你的馬褲外面。', 28153),
(137074, 'zhTW', '朋友，做好準備。這場盛會等下就會變得很熱鬧了！', '', 28153),
(137073, 'zhTW', '小偷！你要付出代價！', '小偷！你要付出代價！', 28153),
(137071, 'zhTW', '帝國的力量銳不可擋！', '帝國的力量銳不可擋！', 28153),
(137068, 'zhTW', '廢墟裡的力量是我們的！', '廢墟裡的力量是我們的！', 28153),
(137067, 'zhTW', '你休想搶走那個力量！那是我們的！', '你休想搶走那個力量！那是我們的！', 28153),
(137066, 'zhTW', '', '你不是每天都有機會得到水元素的幫助的。', 28153),
(137065, 'zhTW', '', '你真是精神可嘉。去吧，在達薩亞洛的台階前為我立起雕像，這裡的食人妖就會知道事情跟我有關。', 28153),
(137063, 'zhTW', '', '哈哈！我可不是那個意思。', 28153),
(137062, 'zhTW', '<啟動巨像>', '<啟動巨像>', 28153),
(137061, 'zhTW', '隨著你靠近，古老的傀儡開始發光。', '隨著你靠近，古老的傀儡開始發光。', 28153),
(137056, 'zhTW', '別再想束縛我，薩滿，我會讓你四分五裂！', '', 28153),
(137055, 'zhTW', '喂！你看起來不像是上流貴族。來跟我們喝一杯！諾央頓大人邀請我們下山來舉行派對，我們自然恭敬不如從命！', '', 28153),
(137054, 'zhTW', '這裡不歡迎你…這是食人妖的橋！', '', 28153),
(137053, 'zhTW', '看看這些駿馬，年輕人。我們可是穿過了整個大陸來參加這個節慶。我決定要研究這些美麗的動物。$b$b高貴，強大…他們在我老邁的心中打入了懾人的恐懼。', '', 28153),
(137052, 'zhTW', '凋萎者會吞噬這個峽谷！', '', 28153),
(137051, 'zhTW', '部落奪回亞格洛克了！', '部落奪回亞格洛克了！', 28153),
(137050, 'zhTW', '', '這裡出現了一股新的力量。到我面前來，部落的$p，讓我看看你最真實的樣子。$b$b一個$r$c，顯然還是個勇士。$b$b妖術之王告訴我，你想要我的祝福，但你必須先有付出，我對所有來和我交易的人都有同樣的要求。$b$B你需要證明自己有跳下懸崖的勇氣…', 28153),
(137049, 'zhTW', '快點，把這個邪教徹底消滅！', '', 28153),
(137048, 'zhTW', '你--你是認真的嗎？我認為我們應該接受他的提議！', '', 28153),
(137047, 'zhTW', '呿，我度過的難關比你幹過的活更多！你絕對贏不了的。', '', 28153),
(137046, 'zhTW', '你們的人民大難臨頭了！不加入我這邊的話…就等著滅亡吧。', '', 28153),
(137045, 'zhTW', '我同意。', '我同意。', 28153),
(137041, 'zhTW', '啊，我們崇高的英雄！歡迎，歡迎。喜歡吃喝什麼就自己拿吧。若你有需要什麼其他東西就跟我說，我會很樂意協助你。', '', 28153),
(137040, 'zhTW', '這是我們照顧我們所有馬匹的地方。騎士和養馬人都在這裡讓它們受到良好的照料。', '', 28153),
(137039, 'zhTW', '', '你對空之羅亞有何請求？', 28153),
(137038, 'zhTW', '', '我要去跟馬庫斯躲在一起！', 28153),
(137037, 'zhTW', '', '謝謝你！這邊的石頭都快被我丟光了！', 28153),
(137036, 'zhTW', '入侵者去死！', '', 28153),
(137035, 'zhTW', '', '札佐克斯的力量流遍我的全身！', 28153),
(137034, 'zhTW', '', '札佐克斯的力量會消滅你！', 28153),
(137033, 'zhTW', '我要回去祖爾詹遺跡，我們要去看看有沒有別人也突發奇想，跑去加入鮮血食人妖。', '', 28153),
(137032, 'zhTW', '卡卓恩太弱了，看不出我們才是贏家，真是不幸，對吧？', '', 28153),
(137031, 'zhTW', '$n，願好運隨行。在札佐克斯把所有人變成他的手下之前，快點消滅他！', '', 28153),
(137030, 'zhTW', '放心把這件事情交給$n就對了。$G他:她;會把你說的妖術師宰掉的。', '', 28153),
(137029, 'zhTW', '達朱爾…我不知道…$n沒辦法阻止札佐克斯的！我們全都會死！', '', 28153),
(137028, 'zhTW', '', '我要去找馬庫斯！那邊見！', 28153),
(137027, 'zhTW', '', '噢，謝謝你！這裡實在讓人太不舒服了。', 28153),
(137026, 'zhTW', '', '這真的有點太過火了，我要走了！', 28153),
(137025, 'zhTW', '聯盟攻擊了礦場！', '', 28153),
(137024, 'zhTW', '$n攻擊了礦場！', '', 28153),
(137023, 'zhTW', '我會馬上開始補充湖水。', '', 28153),
(137022, 'zhTW', '如此強大的精華，這一定是桑博爾的傑作。', '', 28153),
(137021, 'zhTW', '我要去找馬庫斯，跟他一起等。到時候見！', '', 28153),
(137020, 'zhTW', '嘿，謝謝你！誰會知道穴居怪也懂魔法？', '', 28153),
(137019, 'zhTW', '我回去找桑博爾。', '', 28153),
(137018, 'zhTW', '我重生了。', '', 28153),
(137017, 'zhTW', '我從小就是聽鮮血食人妖的恐怖故事長大的，但這情況比任何聽過的故事都還糟糕。', '', 28153),
(137016, 'zhTW', '卡卓恩跑了！$n，你必須去追他…有必要的話，你可以殺了他。', '', 28153),
(137015, 'zhTW', '我們都完蛋了！札佐克斯會拯救我們，如果你想反抗，就準備受死吧！', '', 28153),
(137013, 'zhTW', '撐…不住…', '', 28153),
(137012, 'zhTW', '歡迎參加諾爾威頓馬術慶典！我們還在準備，但請你一定要來參加，就這麼說定囉！', '', 28153),
(137011, 'zhTW', '走啊！你們沒有必要留在這裡了！', '', 28153),
(137010, 'zhTW', '就是現在，$c！', '', 28153),
(137009, 'zhTW', '不要相信他的謊言，不然你們也會完蛋的！', '', 28153),
(137008, 'zhTW', '荒秋谷主宰死了！他就是太渴望力量才會有這種下場！', '', 28153),
(137007, 'zhTW', '我見過…古翰…好絕望…完全沒有希望…', '', 28153),
(137006, 'zhTW', '沒有希望的！你為什麼不加入札佐克斯呢？', '', 28153),
(137005, 'zhTW', '再次感謝你，$c。你來得正是時候！', '', 28153),
(137003, 'zhTW', '你毀了…這片土地…', '', 28153),
(137002, 'zhTW', '你不應該插手我們在做的事，除非你也想變成祭品！', '', 28153),
(137001, 'zhTW', '這些人瘋了！救救我，$c！', '', 28153),
(137000, 'zhTW', '一定要想辦法按捺住巫木邪偶，否則我們的厄運就不會停止！', '', 28153),
(136999, 'zhTW', '你就不能閉嘴嗎？！你死了對大家都有好處！', '', 28153),
(136998, 'zhTW', '你不能這樣！這是謀殺！謀殺！', '', 28153),
(136997, 'zhTW', '看樣子你消滅了不少蜜蜂。我從這裡自己回去應該沒問題了。', '', 28153),
(136996, 'zhTW', '謝謝你，陌生人！我還以為要被這些蜜蜂螫死了！', '', 28153),
(136995, 'zhTW', '跑到我眼睛裡了！我的眼睛！', '', 28153),
(136994, 'zhTW', '千萬不要是蜜蜂！不！！！', '', 28153),
(136993, 'zhTW', '$C！能見到友善的面孔真好…等等，這是什麼？', '', 28153),
(136992, 'zhTW', '為巫木邪偶歡呼！', '為巫木邪偶歡呼！', 28153),
(136991, 'zhTW', '你看，$n！這是瑪歌，我新得到的馬。他是不是很棒？$b$b我想念明星，他是個好男孩，只是有時候會激動起來！我會特別努力和瑪歌培養感情，這樣我就能看出他何時緊張。$b$b我想要成為一個真正優秀的馬術家，所以我會繼續和梅麗莎做訓練，這樣瑪歌和我就可以成為一對好搭檔。最好最好的搭檔！', '', 28153),
(136990, 'zhTW', '到巫木邪偶面前集合，新來的成員。他的恩典會保護我們不受這片土地的詛咒影響。', '', 28153),
(136989, 'zhTW', '', '你救了艾迪，我真是感激不盡。他是個好孩子，而且他也會成為優秀的馬術家。$b$b我想我們還是會繼續往莊園那裡騎的。', 28153),
(136988, 'zhTW', '太…弱了…', '', 28153),
(136987, 'zhTW', '戰母，遵命，我立刻出發！', '', 28153),
(136986, 'zhTW', '科加布派我來的。', '科加布派我來的。', 28153),
(136985, 'zhTW', '不過如果你加入我這邊，你就會得到從來都沒想過的力量！', '', 28153),
(136984, 'zhTW', '如果你想反抗，就等著被碾過吧。', '', 28153),
(136983, 'zhTW', '你沒有選擇了，祖達薩會毀滅，古翰會重獲自由！', '', 28153),
(136982, 'zhTW', '如果你臣服於我，我就可以放過你。古翰答應過。', '', 28153),
(136981, 'zhTW', '古翰會吞噬一切，我們一點希望都沒有。', '', 28153),
(136980, 'zhTW', '哈哈…你很強！但是在古翰面前，萬物皆會臣服。如果你們改變主意，我過的條件還是有效…', '', 28153),
(136979, 'zhTW', '等…等一下，我們也許應該跟札佐克斯聯手！不然要怎麼阻止這一切？', '', 28153),
(136978, 'zhTW', '$n永遠不會站在你那邊！讓這巫妖看看你對這「提議」有什麼感想！', '', 28153),
(136977, 'zhTW', '服侍我，你就能得救…而我會賜給你古翰一部份的力量。', '', 28153),
(136976, 'zhTW', '鮮血食人妖和古翰就要毀滅祖達薩了，但是你不需要和它同歸於盡。', '', 28153),
(136975, 'zhTW', '來吧，巫妖，告訴我你有什麼提議。', '來吧，巫妖，告訴我你有什麼提議。', 28153),
(136974, 'zhTW', '加入我，你就不用陪祖達薩一起被消滅掉！', '', 28153),
(136973, 'zhTW', '死定了！我們要怎麼對付這種怪物？', '', 28153),
(136972, 'zhTW', '這些鮮血食人妖有多少力量泉源？', '', 28153),
(136969, 'zhTW', '', '很好！明智的選擇。來吧，跟我一起去找剛克。', 28153),
(136968, 'zhTW', '哈！我就知道你會做出正確的選擇。過來這裡，我會帶你飛去見帕骷。', '', 28153),
(136967, 'zhTW', '我想要選擇一個不同的羅亞。', '我想要選擇一個不同的羅亞。', 28153),
(136966, 'zhTW', '不不不！愛管閒事的部落蟲子！我會把你的生命力吸得一乾二淨。', '', 28153),
(136965, 'zhTW', '不要停！我要它別停下來！', '', 28153),
(136964, 'zhTW', '給我更多！全部都給我！', '', 28153),
(136963, 'zhTW', '再來！給我更多！', '', 28153),
(136962, 'zhTW', '很好…很好…很好！！！！', '', 28153),
(136961, 'zhTW', '', '你來遲了！如果我的蝙蝠因此而死，我要用你的頭來裝飾我的小屋！', 28153),
(136960, 'zhTW', '你是這場戰鬥中最意外的盟友。', '', 28153),
(136959, 'zhTW', '我…我想那很公平。', '', 28153),
(136958, 'zhTW', '', '好了，艾迪，我想騎馬課程現在會轉移至莊園進行。', 28153),
(136957, 'zhTW', '', '沒有時間感傷了！薩魯法爾！', 28153),
(136956, 'zhTW', '一定會有別的辦法，大酋長！', '', 28153),
(136954, 'zhTW', '', '拉爾，你這個自以為是的白癡！你害我們陷入險境。鮮血教徒已經準備在山巔上舉行儀式了。', 28153),
(136953, 'zhTW', '最後一道屏障…會陷落…古翰…會重獲自由！', '', 28153),
(136952, 'zhTW', '不…我和古翰的連結…在消逝？', '', 28153),
(136951, 'zhTW', '我要散播古翰的力量，你沒辦法阻止我！', '', 28153),
(136950, 'zhTW', '傻瓜！我體內有古翰的力量！我不會失敗的！', '', 28153),
(136949, 'zhTW', '大膽的小$pr，靠近一點，我有話想跟你說。', '', 28153),
(136948, 'zhTW', '', '哈…札佐克斯才不會被阻止…他的力量…會幫助我們摧毀…祖達薩…', 28153),
(136947, 'zhTW', '', '有了薩拉斯和古翰的力量，我們銳不可擋！', 28153),
(136945, 'zhTW', '做得好，$c。你贏得了我的信任，我會幫助你完成任務。', '', 28153),
(136944, 'zhTW', '', '我好像真的感覺到他了。', 28153),
(136943, 'zhTW', '他好像動了！不…等等…難道那是風？', '', 28153),
(136942, 'zhTW', '大功告成了。巫木邪偶，請過目我們獻上的物品，賜給我們恩典吧！', '', 28153),
(136941, 'zhTW', '你帶了骨頭過來？太好了！他最喜歡的就是骨頭了。', '', 28153),
(136940, 'zhTW', '噢，是內臟！我們一定可以…找到用處的。', '', 28153),
(136939, 'zhTW', '我看你帶了木頭過來。這選擇可以理解，也很正確。', '', 28153),
(136938, 'zhTW', '', '不對，不對！這是烹飪用的香草，不是儀式用的藥草！你分不出來嗎？', 28153),
(136937, 'zhTW', '', '你帶穀物來做什麼？我們又不是要紮稻草人！拿走！', 28153),
(136936, 'zhTW', '噢，你把卷軸帶來了…這些卷軸雖然很可能是喚醒巫木邪偶的關鍵，但是…我們沒有人看得懂。', '', 28153),
(136935, 'zhTW', '水果？！你是認真的嗎？$g他:她;是認真的吧，是嗎？', '', 28153),
(136934, 'zhTW', '我們辦到了。終於要讓希瓦娜斯伏法了。勇士，跟我來…', '', 28153),
(136929, 'zhTW', '<海蘿輕輕地敲打他腰上的鈴鼓，並對你眨眼。>', '', 28153),
(136927, 'zhTW', '我想我們不會再見面了，$n，謝謝你。', '', 28153),
(136925, 'zhTW', '', '沃魯敦以前給我們的困難更糟。我們會沒事的。', 28153),
(136919, 'zhTW', '如果你能幫我清出一條路，我應該就能安全到達梅麗莎那裡。真的很感謝你救了我！', '', 28153),
(136918, 'zhTW', '現在能…安全出去了嗎？穴居怪真的很恐怖！', '', 28153),
(136917, 'zhTW', '$n佔領了戰斧山脊！', '$n佔領了戰斧山脊！', 28153),
(136916, 'zhTW', '你去跟蘿蒂單獨談談。告訴她一切的根源可能就在贊庫爾內部。', '', 28153),
(136915, 'zhTW', '嗯，事情…不太對勁。我感覺到贊庫爾內部有股強大的力量。', '', 28153),
(136914, 'zhTW', '每個禮拜，都有越來越多贊達拉人沉迷於那些納茲米爾異端所傳播的鮮血魔法。', '', 28153),
(136913, 'zhTW', '我們的防禦減弱了。塔蘭姬公主一直在要求增加兵力。她父王沒有及時採取行動，於是她決定去找部落。', '', 28153),
(136912, 'zhTW', '我們就是在那個時候接觸到鮮血魔法的，這跟低等部族的小把戲可不一樣。', '', 28153),
(136911, 'zhTW', '幾年前，這裡因為大災變而震動。北邊失去防禦，鮮血食人妖也開始肆虐。', '', 28153),
(136910, 'zhTW', '我會告訴你最好的位置，你就負責把崗哨圖騰給丟下去。', '', 28153),
(136909, 'zhTW', '一個小型的馬匹點心袋掉落在地上。調查過那個袋子後，你發現艾迪的名字被繡在織料上。$b$b他一定有經過這條路，不過似乎不是自願的。你看到剩下的點心一路灑上斜坡。', '一個小型的馬匹點心袋掉落在地上。調查過那個袋子後，你發現艾迪的名字被繡在織料上。$b$b他一定有經過這條路，不過似乎不是自願的。你看到剩下的點心一路灑上斜坡。', 28153),
(136908, 'zhTW', '我不知道我們還能在塞斯拉克的攻勢下撐多久…', '', 28153),
(136907, 'zhTW', '你看起來不是來自祖達薩，否則你一定知道我是誰。我曾經是賈克拉傑將軍的私人主廚！$b$b有次將軍吃了我的料理後生病，於是我就被流放了，但那根本不是我的錯！$b$b其他的廚師覬覦我的地位！其中一人一定是趁我不注意的時候在料理下毒！$b$b我有一天一定會證明自己的清白，但現在，我必須煮這些噁心的糞甲蟲維生。', '', 28153),
(136906, 'zhTW', '聯盟，堅守崗位！', '', 28153),
(136905, 'zhTW', '你怎麼會來到沃魯敦？', '你怎麼會來到沃魯敦？', 28153),
(136904, 'zhTW', '你問了不該問的問題，$c。\n\n我不在乎隱瞞我的過去，但這裡的其他人可能不這麼想…\n\n當我還是個小孩的時候，就跟家人一起被流放。我的父親欠了一大筆債，那時候，小孩總是跟父母一起被流放。\n\n拉茲迦基發現我的時候，我獨自一人，差點渴死。他讓我恢復健康，視我如己出，撫養我長大。從那時候起，我就一直待在他身邊。', '', 28153),
(136903, 'zhTW', '你怎麼會來到沃魯敦？', '你怎麼會來到沃魯敦？', 28153),
(136902, 'zhTW', '', '那邊的，我從沒有看過你。來，跟我談談。', 28153),
(136901, 'zhTW', '', '希爾雷克高興了…但還需要更多的血！將另一個犧牲品帶來！', 28153),
(136900, 'zhTW', '', '偉大的希爾雷克，操控蝙蝠的羅亞以及古翰的僕人。這個祭品是獻給你的！', 28153),
(136899, 'zhTW', '', '妖術之王拉爾就在臺地的另一頭那裡。記得幫我臭罵他兩句。', 28153),
(136895, 'zhTW', '你的時候到了，安杜因國王！', '', 28153),
(136894, 'zhTW', '要是我們逃走，就會變成獵物。不行。我們要為信仰奮戰到底，死而無憾！', '', 28153),
(136889, 'zhTW', '', '快開口，不然我就割了你的舌頭，把它用在下個儀式。', 28153),
(136888, 'zhTW', '', '希爾雷克提供我們他的子嗣，而血神提供我們他的力量。團結起來，我們勢不可擋！', 28153),
(136887, 'zhTW', '', '什麼事？有話快說，不然你就會是下個祭品。', 28153),
(136882, 'zhTW', '抓住繩索', '抓住繩索', 28153),
(136878, 'zhTW', '', '戰爭時期只能採取非常手段。', 28153),
(136876, 'zhTW', '', '有蛇！小心！', 28153),
(136874, 'zhTW', '剛克對你說過話了嗎？他是獸群之王。他對幾個暗矛食人妖說過話，引導他們成為德魯伊。$b$b但對我們來說，他不只是個聲音。我們可以親自看到他說話。不是某種碎片或是他的一部分，而是他的真實本體。', '剛克對你說過話了嗎？他是獸群之王。他對幾個暗矛食人妖說過話，引導他們成為德魯伊。$b$b但對我們來說，他不只是個聲音。我們可以親自看到他說話。不是某種碎片或是他的一部分，而是他的真實本體。', 28153),
(136872, 'zhTW', '是剛克這個羅亞教導所有的食人妖如何和其他羅亞交流並成為德魯伊的。我們永遠會感激他做的這件事。', '是剛克這個羅亞教導所有的食人妖如何和其他羅亞交流並成為德魯伊的。我們永遠會感激他做的這件事。', 28153),
(136871, 'zhTW', '帕骷的追隨者們仍然因為戰鬥德魯伊蘿蒂跟他們的妖術之王拉爾分手而有所怨懟。非常遺憾、非常不專業。', '帕骷的追隨者們仍然因為戰鬥德魯伊蘿蒂跟他們的妖術之王拉爾分手而有所怨懟。非常遺憾、非常不專業。', 28153),
(136870, 'zhTW', '帕骷的追隨者們仍然因為妖術之王拉爾跟他們的戰鬥德魯伊蘿蒂分手而有所怨懟。非常遺憾、非常不專業。', '帕骷的追隨者們仍然因為妖術之王拉爾跟他們的戰鬥德魯伊蘿蒂分手而有所怨懟。非常遺憾、非常不專業。', 28153),
(136869, 'zhTW', '不管你怎麼做，都別聽信那些剛克的追隨者所說的謊言。他們只是在嫉妒我們的羅亞帕骷有多棒。', '不管你怎麼做，都別聽信那些剛克的追隨者所說的謊言。他們只是在嫉妒我們的羅亞帕骷有多棒。', 28153),
(136868, 'zhTW', '我聽命於帕骷，風之羅亞以及我們海軍的主人，她和其他的羅亞都不一樣，你和她打交道，會比和其他羅亞打交道好多了。他們不值得信任。', '我聽命於帕骷，風之羅亞以及我們海軍的主人，她和其他的羅亞都不一樣，你和她打交道，會比和其他羅亞打交道好多了。他們不值得信任。', 28153),
(136867, 'zhTW', '喂，$p。羅亞一直低語著你的名字。你來到祖達薩應該會很有趣。', '喂，$p。羅亞一直低語著你的名字。你來到祖達薩應該會很有趣。', 28153),
(136866, 'zhTW', '帕骷是萬風羅亞，也是我們斥候和艦隊的主子，她個性衝動、熱愛自由。如果你想知道多了解這位羅亞，可以去和妖術之王拉爾聊聊，那位是她的勇士。', '帕骷是萬風羅亞，也是我們斥候和艦隊的主子，她個性衝動、熱愛自由。如果你想知道多了解這位羅亞，可以去和妖術之王拉爾聊聊，那位是她的勇士。', 28153),
(136865, 'zhTW', '啊！部落的英雄。妖術之王拉爾一定會很欣賞你。你站在他這邊，就等於站在帕骷這邊，站在我這邊。', '啊！部落的英雄。妖術之王拉爾一定會很欣賞你。你站在他這邊，就等於站在帕骷這邊，站在我這邊。', 28153),
(136864, 'zhTW', '這裡不歡迎你。', '這裡不歡迎你。', 28153),
(136863, 'zhTW', '我跟你沒什麼話好說。', '我跟你沒什麼話好說。', 28153),
(136862, 'zhTW', '你一定是迷路了，要知道，你不該出現這裡。', '你一定是迷路了，要知道，你不該出現這裡。', 28153),
(136861, 'zhTW', '賤民，呸！', '賤民，呸！', 28153),
(136860, 'zhTW', '不要和我講話，草民。', '不要和我講話，草民。', 28153),
(136859, 'zhTW', '', '如我所料，我的作品完美無缺。一定有東西堵住了噴泉。你介意調查一下嗎？', 28153),
(136858, 'zhTW', '', '讓我們近一點觀察這座噴泉。', 28153),
(136857, 'zhTW', '我要用你的血來完成我下一次的儀式！', '我要用你的血來完成我下一次的儀式！', 28153),
(136856, 'zhTW', '愛管閒事的部落人渣！', '愛管閒事的部落人渣！', 28153),
(136855, 'zhTW', '你無法阻止我們所有人！', '你無法阻止我們所有人！', 28153),
(136854, 'zhTW', '你覺得我是這裡唯一會使用鮮血魔法的人嗎？喔，糟糕，你要準備面對意外的驚喜了。', '你覺得我是這裡唯一會使用鮮血魔法的人嗎？喔，糟糕，你要準備面對意外的驚喜了。', 28153),
(136853, 'zhTW', '呸！我才不會被某個多管閒事的部落小卒阻止呢！', '呸！我才不會被某個多管閒事的部落小卒阻止呢！', 28153),
(136852, 'zhTW', '我以為是你們這些飛行蠢蛋負責留意鮮血食人妖。為什麼是我們在做你們的工作？', '我以為是你們這些飛行蠢蛋負責留意鮮血食人妖。為什麼是我們在做你們的工作？', 28153),
(136851, 'zhTW', '蘿蒂會確保你不能在我們的儀式之日搗亂的。', '蘿蒂會確保你不能在我們的儀式之日搗亂的。', 28153),
(136850, 'zhTW', '你們這些飛行狂熱者會害贊達拉滅亡。', '你們這些飛行狂熱者會害贊達拉滅亡。', 28153),
(136849, 'zhTW', '如果拉爾一直擾亂我們，他會害你們全都被餵給國王的羅亞。', '如果拉爾一直擾亂我們，他會害你們全都被餵給國王的羅亞。', 28153),
(136848, 'zhTW', '', '敵人實在太多了…你下令，我就傳送大家到安全的地方。', 28153),
(136846, 'zhTW', '你還在追隨蘿蒂？哈！你比布魯多糞便還笨。', '你還在追隨蘿蒂？哈！你比布魯多糞便還笨。', 28153),
(136845, 'zhTW', '現在寡不敵眾的人是你。', '', 28153),
(136844, 'zhTW', '有天拉爾會統治這地方，把你們這些迅猛龍迷都踢到荒野，那才是你們該待的地方。', '有天拉爾會統治這地方，把你們這些迅猛龍迷都踢到荒野，那才是你們該待的地方。', 28153),
(136843, 'zhTW', '你的羅亞叫做剛克，你應該以此為恥的。', '你的羅亞叫做剛克，你應該以此為恥的。', 28153),
(136842, 'zhTW', '你們這些骯髒的德魯伊最差勁了，比古拉巴什好不了多少。', '你們這些骯髒的德魯伊最差勁了，比古拉巴什好不了多少。', 28153),
(136841, 'zhTW', '你沒比我好到哪去…你的手上…全是我的鮮血。', '', 28153),
(136840, 'zhTW', '食人妖只為自己而活，要嘛殺人，不然就是被殺掉！', '', 28153),
(136838, 'zhTW', '<你找到艾迪的迷你馬「明星」仍保有餘溫的屍體。>$b$b<麵包屑的痕跡往丘陵上延伸。看來艾迪留下了一道蹤跡。>', '你找到艾迪迷你馬「明星仍保有餘溫的屍體$b$b你也希望還能及時搭救艾迪。', 28153),
(136837, 'zhTW', '小孩會是好吃的點心！', '', 28153),
(136836, 'zhTW', '我在這裡！他有鑰匙！拜託，幫幫我！', '', 28153),
(136835, 'zhTW', '', '我們快跟上，$n。如果諾爾威頓領主的兒子發生什麼事情的話，我的頭會被砍掉！', 28153),
(136832, 'zhTW', '我們是一群放逐者，被逐出祖達薩，只能在沙漠中等死。\n\n我們當中，有些人是被誣賴的，但其他的人都是自作自受。\n\n我們現在唯一的心願就是活下去。\n\n只要你遵守部族的紀律，就能在我們之中佔有一席之地。不過，一旦你破壞紀律，我們的懲罰會比拉斯塔哈王更有效率。', '', 28153),
(136831, 'zhTW', '你需要什麼，族長？', '', 28153),
(136830, 'zhTW', '什麼事？你…你不是下一個要犧牲的人，是吧？', '', 28153),
(136829, 'zhTW', '那些女祭司…他們會把我們都殺掉！', '', 28153),
(136828, 'zhTW', '你不偽裝的話事情會變得更難看。', '', 28153),
(136827, 'zhTW', '告訴我你部落的事。', '告訴我你部落的事。', 28153),
(136825, 'zhTW', '', '這是洛琪拉的盾牌…那她人呢？你對她做了什麼？', 28153),
(136824, 'zhTW', '不是我，是賈克拉傑幹的好事。我是因為洛琪拉才活下來的。', '', 28153),
(136823, 'zhTW', '', '米若，快停車！我好像看到什麼東西了！', 28153),
(136822, 'zhTW', '', '洛琪拉怎麼可能在這種地方活下來？', 28153),
(136820, 'zhTW', '', '你相信這片荒地曾經是食人妖帝國的一顆明珠嗎？曾經生機盎然的叢林…如今全都埋在沙子底下了。', 28153),
(136819, 'zhTW', '', '基羅根本不用那麼擔心。我很有經驗的！但你最好還是抓緊一點，以防萬一啦。', 28153),
(136818, 'zhTW', '', '我一向很小心！', 28153),
(136816, 'zhTW', '…但也只有這個$c幫忙才行。$g他:她;有非常強的力量，我聞得出來。', '', 28153),
(136815, 'zhTW', '你一定是跟跑去那個納茲什麼的那群人一樣瘋了…', '你一定是跟他們一樣瘋了，才會去那個納茲什麼的…', 28153),
(136814, 'zhTW', '呿。你看好，我這就過去證明他已經瘋了。', '呿！你看好，我這就過去證明他已經瘋了。', 28153),
(136813, 'zhTW', '我一定會告訴營地的每一個人你如何把我救出來！', '', 28153),
(136812, 'zhTW', '我自由了！真讓人不敢相信！', '', 28153),
(136811, 'zhTW', '如果我的力量回來了，我就可以打倒他…', '', 28153),
(136810, 'zhTW', '…而那就是烏洛克－會殺光你們的不死怪物。', '', 28153),
(136809, 'zhTW', '蠢貨！你會成為烏洛克的食物！', '', 28153),
(136808, 'zhTW', '噓，烏洛克就在附近，我聞得到他牙齒的味道。', '', 28153),
(136807, 'zhTW', '讓我見識一下『濕地惡夢』烏洛克。', '讓我見識一下『濕地惡夢』烏洛克。', 28153),
(136806, 'zhTW', '', '艾迪！！！', 28153),
(136805, 'zhTW', '帕骷、帕骷、帕骷，她會是你的羅亞。', '帕骷、帕骷、帕骷，她會是你的羅亞。', 28153),
(136804, 'zhTW', '喜歡天空嗎？我也是。加入帕骷吧，她會是你的羅亞。', '喜歡天空嗎？我也是。加入帕骷吧，她會是你的羅亞。', 28153),
(136803, 'zhTW', '別再遲疑，今天就追隨帕骷！', '別再遲疑，今天就追隨帕骷！', 28153),
(136800, 'zhTW', '他沒事，他沒事啦！沒必要…啊啊！', '', 28153),
(136799, 'zhTW', '', '好了，艾迪，讓明星冷靜下來。', 28153),
(136798, 'zhTW', '', '廢物！你連希爾雷克的祭品都稱不上！', 28153),
(136797, 'zhTW', '', '來吧，該輪到你上場了。', 28153),
(136789, 'zhTW', '在此告別，再會。', '', 28153),
(136788, 'zhTW', '我要回去佐巴爾，那邊有更多靈魂可以讓我用來還債。', '', 28153),
(136780, 'zhTW', '被束縛的暗夜獵人咕噥了一下。', '', 28153),
(136779, 'zhTW', '被束縛的暗夜獵人聽到有東西在附近！', '', 28153),
(136778, 'zhTW', '被束縛的暗夜獵人對著空氣聞了聞。', '', 28153),
(136769, 'zhTW', '', '米基不應該落得如此下場的，但我知道那不是你的錯。\n\n感謝你為我們找到他們。與其活在悔恨裡，不如迎接痛苦的真相。\n\n我們像一家人一樣在沙丘間流浪，現在你也是一份子了，歡迎你來到我們的車隊。', 28153),
(136768, 'zhTW', '你必須腦袋更清楚才行。你的敵人會感受到你思想中的弱點。', '', 28153),
(136767, 'zhTW', '住手！', '', 28153),
(136766, 'zhTW', '我、我等不及要聽阿娜歌頌你的英勇與善良了。\n\n阿、阿娜很擅長做音樂，記、記得要告訴她你的故事！\n\n我、我們會讓我們遇到的每個人都聽聽$p的故事。', '', 28153),
(136764, 'zhTW', '', '悲劇、不死海盜、被詛咒的生物、叛變…這場冒險堪稱傳奇。\n\n我對於英勇之歌$p的第一段歌詞已經有幾個不錯的想法。\n\n你會成為傳奇，至少對這個商隊來說，被世代歌頌。\n\n睡個午覺就來。', 28153),
(136763, 'zhTW', '認真給我打！', '', 28153),
(136762, 'zhTW', '我們不只為了保護人們，更是為了贊達拉的未來。', '', 28153),
(136761, 'zhTW', '要以迅雷不及掩耳的速度攻擊，但也別忘了你周圍的士兵。', '', 28153),
(136760, 'zhTW', '你得全力擊中目標，但你的姿勢也要四平八穩。', '', 28153),
(136759, 'zhTW', '我在訓練場裡騎過很多次了，在外面應該不會有多難的！', '', 28153),
(136758, 'zhTW', '', '艾迪，把繩子握好。', 28153),
(136757, 'zhTW', '', '諾爾威頓領主委託我訓練他兒子馬術。他在訓練場內做得夠好了，但我不太敢帶他出來外面騎。要是他的馬受到驚嚇，我不知道他能不能把馬控制住。$b$b希望這種事情不會發生！', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(136756, 'zhTW', '明星才不會被嚇到，他是個好孩子！', '', 28153),
(136755, 'zhTW', '我覺得他有在聽，你看他的耳朵！', '', 28153),
(136754, 'zhTW', '我！我！', '', 28153),
(136753, 'zhTW', '', '慢一點，小心一點。任何東西都有可能嚇到他。', 28153),
(136752, 'zhTW', '', '讓他專注在你身上，這裡有很多東西！', 28153),
(136751, 'zhTW', '', '艾迪，用你的腳，不是手。', 28153),
(136750, 'zhTW', '沼澤裡的沙漠…那些塞斯拉克在打什麼主意？', '', 28153),
(136747, 'zhTW', '謝謝你帶我逃離那些討厭的尖角蜥。我再也不會獨自到河彎那去了…除非我長大！', '', 28153),
(136746, 'zhTW', '哈囉？外面有人嗎？', '', 28153),
(136745, 'zhTW', '聯盟根本阻擋不了部落的力量！為了部落！', '', 28153),
(136744, 'zhTW', '贊姆蘭港是我的！', '', 28153),
(136741, 'zhTW', '沙爾俊，別傻了！發生了這種事，我們怎麼可能離開納茲米爾。我絕對不要再回祖達薩。', '', 28153),
(136740, 'zhTW', '有了你的幫忙，我就有能力和你一起再次擊敗烏洛克。我會在這邊準備進行下一個儀式。', '', 28153),
(136738, 'zhTW', '那些怪物打算把我吃了！', '', 28153),
(136732, 'zhTW', '沙爾俊，你說什麼？…嗯…對，說得對。', '', 28153),
(136731, 'zhTW', '沙爾俊，這件事情應該交給我去辦才對，我不喜歡待在旁邊看別人做事。', '', 28153),
(136730, 'zhTW', '我準備往前推進！記得為對決烏洛克做好準備。', '', 28153),
(136729, 'zhTW', '爸爸說我今年能參加慶典。他們總算要教我騎術了！', '', 28153),
(136728, 'zhTW', '我在維持大自然的平衡。\n\n別吵，沙爾俊，我當然關心大自然的平衡…就某種程度來說啦。\n這種事情不用跟$g他:她;說。', '', 28153),
(136727, 'zhTW', '沼澤充滿了恐怖的東西，如果你想活命，你必須也成為恐怖的東西。', '', 28153),
(136726, 'zhTW', '詛咒…結束了嗎？我終於…自由了？', '', 28153),
(136725, 'zhTW', '你腳下是受詛咒之地…沒有人能夠離開！', '', 28153),
(136724, 'zhTW', '', '贊姆蘭陰暗的角落裡藏著許多怪物。\n\n小心點，你才不會變得像他們一樣。', 28153),
(136723, 'zhTW', '無 - 無論發生什麼事，一家人都要團結。', '', 28153),
(136722, 'zhTW', '我可沒開玩笑，我要那食人妖死翹翹，就跟烏洛克一樣。狩獵愉快。', '', 28153),
(136721, 'zhTW', '沙爾俊，別傻了。$g他:她;知道我是認真的。好啦好啦，我會確保對方知道我不是在開玩笑。', '', 28153),
(136720, 'zhTW', '跟你合作很愉快。如果你遇到名叫克魯加的食人妖，一定要把他宰了。', '', 28153),
(136719, 'zhTW', '我們不能再浪費時間了，一定要把烏洛克解決掉。', '', 28153),
(136718, 'zhTW', '是的！是時候了…該解決烏洛克了！', '', 28153),
(136717, 'zhTW', '我感覺得到…自己的力量回來了！', '', 28153),
(136713, 'zhTW', '哈哈！就快準備好了…我們很快就可以對付烏洛克了！', '', 28153),
(136712, 'zhTW', '很好…我感覺力量回來了！', '', 28153),
(136711, 'zhTW', '啊…不夠！我們需要更強的力量，才能殺掉烏洛克。', '', 28153),
(136710, 'zhTW', '我需要的東西都齊全了…該來強化力量了！', '', 28153),
(136698, 'zhTW', '我們才是幸運兒。你不是。還不是。', '', 28153),
(136697, 'zhTW', '她所追尋的，只能藉由犧牲來獲得。', '', 28153),
(136696, 'zhTW', '', '在這片小小的星星之海以外，就只有無盡的黑暗。', 28153),
(136695, 'zhTW', '', '告訴爸爸我原諒他了。', 28153),
(136694, 'zhTW', '', '她背叛你了嗎？總有一天會的…', 28153),
(136693, 'zhTW', '', '你會孤獨地死去。', 28153),
(136692, 'zhTW', '', '主人等著你加入他的行列…', 28153),
(136691, 'zhTW', '', '他醒來了。他注意到你了。', 28153),
(136690, 'zhTW', '', '你會加入我們的。', 28153),
(136689, 'zhTW', '', '我知道你做過什麼。', 28153),
(136688, 'zhTW', '', '你聽到隱約的笑聲。', 28153),
(136687, 'zhTW', '', '你感覺到視線落在你身上。', 28153),
(136686, 'zhTW', '', '你覺得有人在看著你。', 28153),
(136685, 'zhTW', '', '鬼魅追隨者笑著跑走了。', 28153),
(136684, 'zhTW', '我們下次會面會是最後一次…', '', 28153),
(136683, 'zhTW', '你的靈魂屬於我，闖入者！', '', 28153),
(136681, 'zhTW', '你的存在是種汙染，嚐嚐席帕拉的怒火！', '你的存在是種汙染，嚐嚐席帕拉的怒火！', 28153),
(136680, 'zhTW', '', '如果你要找來自南方的頂級魔精飾品，找翁嘉就對了！', 28153),
(136679, 'zhTW', '愚蠢的凡人。席帕拉會摧毀你的！', '愚蠢的凡人。席帕拉會摧毀你的！', 28153),
(136678, 'zhTW', '我們一定要騎『風王』阿塔去才行。上來吧，好好看個仔細。', '', 28153),
(136677, 'zhTW', '我們的羅亞常說，要是你看不到腐化的根源，那就飛高一點。', '', 28153),
(136676, 'zhTW', '蘿蒂的方法比較腳踏實地。我還是喜歡飛行的視角。', '', 28153),
(136674, 'zhTW', '準備巡邏。', '準備巡邏。', 28153),
(136673, 'zhTW', '', '我是戰鬥德魯伊蘿蒂，我是形體羅亞、狩獵大師剛克的媒介。$b$b我也是贊庫爾議會的成員，不過我想你已經知道了。', 28153),
(136672, 'zhTW', '搬運工向贊達拉守衛點頭。', '', 28153),
(136671, 'zhTW', '守衛仔細地打量你。', '', 28153),
(136670, 'zhTW', '守衛對你示意。', '', 28153),
(136669, 'zhTW', '你最好學到教訓了！', '你最好學到教訓了！', 28153),
(136668, 'zhTW', '在你走過時，守衛向你敬禮。', '', 28153),
(136667, 'zhTW', '守衛往你的方向點了點頭。', '', 28153),
(136662, 'zhTW', '在你面前的是妖術之王拉爾。我是贊庫爾議會的一員，也是偉大羅亞帕骷的大祭司，她是萬風羅亞，也是掌管我們海軍的領袖。\n\n那麼，你有何貴幹？', '', 28153),
(136657, 'zhTW', '工作，工作。', '', 28153),
(136655, 'zhTW', '', '聖光會帶給你平靜，$c。', 28153),
(136654, 'zhTW', '沙爾俊你這蠢貨！你怎麼會在大家面前亂講話？大家會以為你瘋掉了！', '', 28153),
(136653, 'zhTW', '我得把儀式的東西備妥。力量回復之後，我們就可以處理烏洛克。', '', 28153),
(136652, 'zhTW', '我知道，我就住在納茲米爾。你可能覺得我瘋了，不過你要知道，如果你們不幫我，就等著倒大楣！', '', 28153),
(136651, 'zhTW', '我知道你一定覺得我瘋了，但你一定要幫我！', '', 28153),
(136650, 'zhTW', '別就這樣拒絕啊！我需要你的幫忙！', '', 28153),
(136649, 'zhTW', '看，他的保護消失了！讓我們了結他吧！', '', 28153),
(136648, 'zhTW', '', '我以古翰之名重生！', 28153),
(136647, 'zhTW', '這麻煩的工作就交給你了，我還是在烏洛克的巢穴外頭。', '', 28153),
(136646, 'zhTW', '啊哈！成功了！我就說嘛，沙爾俊，我們一定可以擊敗他的。', '', 28153),
(136645, 'zhTW', '勇士！收拾那個女巫！她手下那些破爛的骨頭，會向真正的死亡羅亞屈服！', '', 28153),
(136644, 'zhTW', '烏洛克受到圖騰的保護！使用我的火炬燒掉它們！', '', 28153),
(136643, 'zhTW', '<背包有一半被埋在沙中，但其中的內容物看起來狀況良好。>', '', 28153),
(136642, 'zhTW', '', '我不是叫你不要去礦場嗎？你差一點就死在那裡！', 28153),
(136641, 'zhTW', '死亡降臨！', '死亡降臨！', 28153),
(136640, 'zhTW', '有人闖入！', '有人闖入！', 28153),
(136639, 'zhTW', '加入我們！', '加入我們！', 28153),
(136638, 'zhTW', '', '我絕對不容許任何人干擾我！殺了這隻蟲子！', 28153),
(136637, 'zhTW', '快！快！快！', '快！快！快！', 28153),
(136632, 'zhTW', '哈哈，我要宰了這一個！', '', 28153),
(136615, 'zhTW', '', '起來吧，我的僕從們！起來殺死這個蠢羅亞！', 28153),
(136614, 'zhTW', '我需要你幫忙…我知道就要發生某種不好的事情了，而且我沒辦法自己對付！', '', 28153),
(136613, 'zhTW', '', '膽子很大嘛，凡是反抗古翰的人都只有一個下場！', 28153),
(136611, 'zhTW', '沒有人能命令伯昂撒姆第！小傢伙，你有想過…對抗我會是怎樣的下場嗎？', '', 28153),
(136610, 'zhTW', '嗯…女人啊，你看起來很聰明，卻蠢到跑來我的神廟出手干涉。', '', 28153),
(136609, 'zhTW', '', '我只給你這次機會，向血神屈服，不然…就受死吧！', 28153),
(136608, 'zhTW', '', '伯昂撒姆第！你終於離開那座安全的廢墟了。', 28153),
(136607, 'zhTW', '你還懶洋洋地站在那幹嘛？讓我們開始吧！', '', 28153),
(136605, 'zhTW', '開始吧。', '開始吧。', 28153),
(136604, 'zhTW', '束縛儀式是非常非常古老的魔精，就跟這個世界一樣古老。只要有這個魔精，當你殺了某個人，伯昂撒姆第就會得到他們的靈魂。如果你接受這儀式，我們的協議就達成了。$b$b你準備好了？我準備好了。', '', 28153),
(136603, 'zhTW', '', '怎麼了，內陸人？', 28153),
(136602, 'zhTW', '', '我的人已經準備好要幫忙保護村民了。可以開始撤離了嗎？', 28153),
(136601, 'zhTW', '我準備好了。', '我準備好了。', 28153),
(136600, 'zhTW', '那招太糟糕了，小指頭。壞魔暴龍！壞壞！', '那招太糟糕了，小指頭。壞魔暴龍！壞壞！', 28153),
(136599, 'zhTW', '到靈魂之廷來，我們該簽下我們的…契約了。', '', 28153),
(136591, 'zhTW', '我不是在跟你商量。我們可是奉了公主的命令。', '', 28153),
(136590, 'zhTW', '', '然後她就命令我確保$n以及，是她說的，「可愛的傢伙」盡快趕到納茲米爾。', 28153),
(136589, 'zhTW', '邪偶開始反抗主人的控制了！', '', 28153),
(136588, 'zhTW', '奴隸好像暫時不動了。', '', 28153),
(136587, 'zhTW', '奴隸開始狂亂了！', '', 28153),
(136581, 'zhTW', '處理這個入侵者，海衛。照我說的去做。', '', 28153),
(136578, 'zhTW', '致敬', '', 28153),
(136577, 'zhTW', '我用長靴來打賭，一定會在碼頭找到更多艾胥凡武器。我們得查出誰在買這些武器。', '', 28153),
(136576, 'zhTW', '', '我姐妹眾多…庫爾提拉斯必亡…', 28153),
(136575, 'zhTW', '', '你認輸吧！我們一定會讓所有人俯首稱臣！', 28153),
(136574, 'zhTW', '', '看我的！', 28153),
(136573, 'zhTW', '', '不錯嘛…不過憑這點本事想打敗高階女巫可沒那麼容易！', 28153),
(136572, 'zhTW', '', '無所謂。看看女巫會的敵人有什麼下場！侍徒們，把造反的東西殺了！', 28153),
(136571, 'zhTW', '', '看來這些煩人的傢伙成功的讓我們創造的東西造反了？你一定很得意吧。', 28153),
(136570, 'zhTW', '我從來沒看過這裡忙亂成這樣。一定是出大事了。', '', 28153),
(136569, 'zhTW', '有私掠者、傭兵，甚至海盜也來者不拒。所以說，這是個…有趣的地方。', '', 28153),
(136568, 'zhTW', '自由港就是「自由人的港口」。跟波拉勒斯不一樣，這裡什麼船艦都可以停。', '', 28153),
(136567, 'zhTW', '', '我很抱歉，$c。我們完全沒有水草了。大家都病得太重，沒辦法下水採收。替我向瑟羅德致歉。', 28153),
(136566, 'zhTW', '', '姐妹們會幫我報仇…', 28153),
(136565, 'zhTW', '', '你不應該插手的！', 28153),
(136564, 'zhTW', '你們有水草嗎？瑟羅德需要它來製作解藥。', '你們有水草嗎？瑟羅德需要它來製作解藥。', 28153),
(136563, 'zhTW', '', '母親會要了你的命…', 28153),
(136562, 'zhTW', '', '這座村莊是女巫的，入侵者！', 28153),
(136561, 'zhTW', '', '事情好多，時間好少！$b$b我必須為漁夫和他們的設備祈福、觀看潮汐獲得預兆、祈禱我們的水手歸來…', 28153),
(136560, 'zhTW', '', '女巫會吞噬你…', 28153),
(136559, 'zhTW', '', '女巫會吞噬一切！', 28153),
(136558, 'zhTW', '海妖今天傾巢而出，但水面可看不出蹤跡。航行時遠離島嶼能保你平安順利。', '海妖今天傾巢而出，但水面可看不出蹤跡。航行時遠離島嶼能保你平安順利。', 28153),
(136557, 'zhTW', '東邊的浪潮兇猛的湧來，但是西邊這裡的浪潮卻很平靜。', '東邊的浪潮兇猛的湧來，但是西邊這裡的浪潮卻很平靜。', 28153),
(136556, 'zhTW', '我的祝福能使你連在水裡都安全。', '我的祝福能使你連在水裡都安全。', 28153),
(136555, 'zhTW', '將漁人送到市場旁的碼頭。今天那裡有許多魚。', '將漁人送到市場旁的碼頭。今天那裡有許多魚。', 28153),
(136554, 'zhTW', '我們在你的指引之下將會是安全的。', '我們在你的指引之下將會是安全的。', 28153),
(136553, 'zhTW', '我們必須在比較深的水域來趟短期旅行。最好的行程是什麼？', '我們必須在比較深的水域來趟短期旅行。最好的行程是什麼？', 28153),
(136552, 'zhTW', '那我們就沒必要這麼趕了。謝謝你！', '那我們就沒必要這麼趕了。謝謝你！', 28153),
(136551, 'zhTW', '我們將要遠征到深處的水域。浪潮的情況如何了？', '我們將要遠征到水域深處。浪潮的情況如何了？', 28153),
(136550, 'zhTW', '我感覺到你的祝福流經我全身。讓我致上最深的感謝。', '我感覺到你的祝福流經我全身。讓我致上最深的感謝。', 28153),
(136549, 'zhTW', '我要出發去找海怪了，請給我祝福！', '我要出發去找海怪了，請給我祝福！', 28153),
(136548, 'zhTW', '我會通知漁人。', '我會通知漁人。', 28153),
(136547, 'zhTW', '今天哪裡魚比較多？', '今天哪裡魚比較多？', 28153),
(136546, 'zhTW', '嘿！外地人，戰獸欄的人都在談論你。他們說你有超越凡人的勇氣！', '', 28153),
(136545, 'zhTW', '', '你是和羅亞為伍的人之一。小心應對，不是所有的羅亞都互相喜歡。', 28153),
(136538, 'zhTW', '部落的戰士們！我們今天要奮起，揮舞斧頭，讓敵人噴灑鮮血。', '', 28153),
(136533, 'zhTW', '梅卡托克，你的飛行器有辦法越過荒疫嗎？', '', 28153),
(136532, 'zhTW', '', '我們來扭轉戰局吧，烏瑞恩國王！', 28153),
(136528, 'zhTW', '珍娜！封鎖出口，別讓他們求援！', '', 28153),
(136527, 'zhTW', '神廟將會倒塌！女祭司已預見此事！', '', 28153),
(136526, 'zhTW', '保護女祭司！', '', 28153),
(136525, 'zhTW', '主祭需要鮮血進行儀式，你的鮮血正是上好的材料！', '', 28153),
(136524, 'zhTW', '為主祭而戰！為古翰而戰！', '', 28153),
(136523, 'zhTW', '伯昂撒姆第可無權指使我們！為血之神而戰！', '', 28153),
(136522, 'zhTW', '酋長有令！', '', 28153),
(136521, 'zhTW', '入侵者！受死吧！', '', 28153),
(136520, 'zhTW', '為督軍瑪拉卡而戰！為血之神而戰！', '', 28153),
(136519, 'zhTW', '你會成為酋長的好奴隸的！', '', 28153),
(136518, 'zhTW', '', '你竟敢打斷我的儀式？', 28153),
(136517, 'zhTW', '', '夠了！我說我會考慮！', 28153),
(136516, 'zhTW', '但你可以讓產量加倍，甚至是三倍！我的藥劑都是百分之百天然的，保證—', '', 28153),
(136515, 'zhTW', '', '我不知道…我們的方法沒什麼問題，而且…', 28153),
(136514, 'zhTW', '我告訴你，你正在錯過一個天大的機會！你不會想要錯過這個的！', '', 28153),
(136513, 'zhTW', '', '你會後悔的！', 28153),
(136512, 'zhTW', '', '開始儀式吧！我要擺脫這虛弱的軀體！', 28153),
(136511, 'zhTW', '沒什麼好看的，快走！', '', 28153),
(136510, 'zhTW', '別逼我傷害你，小傢伙。', '', 28153),
(136509, 'zhTW', '喂！你在那幹什麼？', '', 28153),
(136508, 'zhTW', '', '一切都將毀滅…在鮮血之神的旨意下…', 28153),
(136507, 'zhTW', '', '為鮮血之神獻上更多鮮血！', 28153),
(136498, 'zhTW', '每個人都要瘋了！我要趁還能走時快離開這裡！', '', 28153),
(136497, 'zhTW', '', '都結束了。\n\n這…非這麼做不可。她已經被腐化得太深了。\n\n<蕾貝卡啜泣著。>\n\n對不起，請讓我靜一靜。', 28153),
(136495, 'zhTW', '', '一開始我覺得妹妹在做的事情看起來滿有意思的，誰知道後來簡直是瘋了！\n\n她在書裡提到要用遠古傀儡打造一支軍隊！要是不阻止她的話，佐司瓦的所有人都會變成她的奴隸！', 28153),
(136494, 'zhTW', '走開！', '走開！', 28153),
(136493, 'zhTW', '', '希望我跟媽媽都能再見到你。', 28153),
(136492, 'zhTW', '', '真的…媽媽做錯了。但是我原諒她。我們現在可以在彼界快快樂樂地永遠在一起了。', 28153),
(136491, 'zhTW', '', '我跟媽媽會永遠在一起…永遠永遠！', 28153),
(136490, 'zhTW', '', '不…我…本來要…永生不死的…', 28153),
(136489, 'zhTW', '小心點。這裡有很多怪物。', '', 28153),
(136488, 'zhTW', '', '這是什麼？不！你盡然敢把那東西帶來這裡！', 28153),
(136487, 'zhTW', '', '找到你了，媽媽！', 28153),
(136486, 'zhTW', '', '是誰，居然打擾我休息？', 28153),
(136485, 'zhTW', '<想要打開石棺。>', '<想要打開石棺。>', 28153),
(136484, 'zhTW', '<石棺蓋得很緊，但你用力一點應該可以打開它。>', '', 28153),
(136483, 'zhTW', '', '就快到了！媽媽！你在哪裡？', 28153),
(136482, 'zhTW', '', '這裡好暗喔！你先走，我會跟在後面。', 28153),
(136481, 'zhTW', '', '不對，不對，這裡是女王的墓穴。媽媽要是跑進去一定會很慘。', 28153),
(136480, 'zhTW', '', '噁，那邊的祭司好臭喔！不對啦，媽媽才不會去那裡。', 28153),
(136479, 'zhTW', '', '我跟媽媽見到祭司了。他們給我這件衣服，他們人好好喔！', 28153),
(136478, 'zhTW', '我就知道你比不上我！', '我就知道你比不上我！', 28153),
(136477, 'zhTW', '', '不對，我覺得不是這裡耶。神廟從來不讓任何人進去。', 28153),
(136476, 'zhTW', '我需要更努力訓練…', '我需要更努力訓練…', 28153),
(136475, 'zhTW', '啊…你比我預期的更強。', '啊…你比我預期的更強。', 28153),
(136474, 'zhTW', '夠了！我投降！', '夠了！我投降！', 28153),
(136473, 'zhTW', '你贏了。這次…', '你贏了。這次…', 28153),
(136472, 'zhTW', '夠了！我放棄！', '夠了！我放棄！', 28153),
(136471, 'zhTW', '別讓你的血滴到我！', '別讓你的血滴到我！', 28153),
(136470, 'zhTW', '挑戰我是不明智的決定！', '挑戰我是不明智的決定！', 28153),
(136469, 'zhTW', '我希望你的劍和你的舌頭一樣厲害！', '我希望你的劍和你的舌頭一樣厲害！', 28153),
(136468, 'zhTW', '你敢挑戰我？我會讓你嚐嚐你自己的血！', '你敢挑戰我？我會讓你嚐嚐你自己的血！', 28153),
(136467, 'zhTW', '和我對打會是你犯下的最後一個錯誤！', '和我對打會是你犯下的最後一個錯誤！', 28153),
(136466, 'zhTW', '如果你想被打…那你就會被打！', '如果你想被打…那你就會被打！', 28153),
(136465, 'zhTW', '', '媽媽說要去一個很暗很可怕的地方。不知道在哪裡？嗚…我怕黑！', 28153),
(136464, 'zhTW', '', '耶！好，媽媽說她和伯昂撒姆第有交易。所以她一定還在神廟裡面。', 28153),
(136463, 'zhTW', '拉茲迦基叫我來和你一較高下。', '拉茲迦基叫我來和你一較高下。', 28153),
(136462, 'zhTW', '你最好自己小心…我不喜歡陌生人。', '你最好自己小心…我不喜歡陌生人。', 28153),
(136461, 'zhTW', '問我是怎麼來到沃魯敦的，我就會給你一大堆墓地的名字讓你拜訪…', '問我是怎麼來到沃魯敦的，我就會給你一大堆墓地的名字讓你拜訪…', 28153),
(136460, 'zhTW', '在我數到三之前，你得掉頭離開…三！', '在我數到三之前，你得掉頭離開…三！', 28153),
(136459, 'zhTW', '你沒看到我正在訓練嗎？閃開！', '你沒看到我正在訓練嗎？閃開！', 28153),
(136458, 'zhTW', '洛克漢，我是來幫助你和塔蘭姬公主調查納茲米爾的。', '洛克漢，我是來幫助你和塔蘭姬公主調查納茲米爾的。', 28153),
(136457, 'zhTW', '塔蘭姬公主派我們去納茲米爾，我們需要你用翼手龍送我們過去。', '', 28153),
(136453, 'zhTW', '', '盡你所能拿下村莊。我馬上就親自出發去調查那座廢墟。', 28153),
(136451, 'zhTW', '', '礦場裡的墳墓可能會有我們的儀式用得上的東西。', 28153),
(136450, 'zhTW', '', '造箭師谷地那些愚蠢的礦工，意外闖進了原本位於舊石礦場深處的隱匿廢墟裡。', 28153),
(136449, 'zhTW', '', '女巫會的各位，聽好了。', 28153),
(136448, 'zhTW', '', '我在那裡已經損失兩個人了，你千萬不要當第三個。', 28153),
(136447, 'zhTW', '', '我不知道他們想要什麼，但從那裡來的魔法，似乎會把生命一點一滴吸乾。', 28153),
(136446, 'zhTW', '', '內陸人，我得警告你，一定要避開礦場。', 28153),
(136445, 'zhTW', '', '這是最後一批村民了。要是運氣好的話，他們就能平安抵達落港村。', 28153),
(136444, 'zhTW', '', '看來他們派出大傢伙了！做好準備！', 28153),
(136443, 'zhTW', '', '又有敵人從村裡打過來了！守住！', 28153),
(136442, 'zhTW', '', '看樣子我們被發現了。保護村民！', 28153),
(136441, 'zhTW', '', '跟守衛一起就位，擋住從村子裡來的怪物！', 28153),
(136440, 'zhTW', '', '聽好了，大家，我們要守住這條路，讓撤離的村民都能逃走。', 28153),
(136439, 'zhTW', '', '希望你背包裡藏了迷你大軍。', 28153),
(136438, 'zhTW', '', '都聽到了嗎？這個內陸人要幫我們奪回村莊！', 28153),
(136437, 'zhTW', '', '我只能說，這些模樣怪異的巫木傢伙可是玩真的。\n\n事情是從幾個星期前開始的，有幾個礦工失蹤了。然後，這些生物就突然出現，把我們從自己的村莊裡趕走。這一切都是從威奎斯特家的女兒到這裡四處查探以後才開始的，她走了以後情況也沒有好轉，反而越來越糟。\n\n這些生物已經佔領了村莊，還把大部分的村民都抓走了。我好不容易才跟一小群志願者一起守住這裡，但我根本不知道該怎麼把村莊奪回來。\n\n除非你是來這裡幫忙的，否則還是趕快走吧。', 28153),
(136436, 'zhTW', '我很樂意幫忙。', '我很樂意幫忙。', 28153),
(136435, 'zhTW', '這裡發生什麼事了？', '這裡發生什麼事了？', 28153),
(136434, 'zhTW', '', '自從這些可怕的生物從礦坑裡排山倒海地出現，我們的村莊就已經岌岌可危了。\n\n希望你能找出這些禍亂的根源，不要像我們一樣空手而歸。', 28153),
(136432, 'zhTW', '我會協助你尋找你的母親。', '我會協助你尋找你的母親。', 28153),
(136431, 'zhTW', '你一直很有耐心。', '你一直很有耐心。', 28153),
(136430, 'zhTW', '', '媽媽不在，我在這裡真的好寂寞啊。$b$b你可以幫我找找她嗎？拜託！我保證不會惹麻煩。', 28153),
(136429, 'zhTW', '', '媽媽叫我待在這裡。我現在已經等好久了，但是媽媽還是沒有回來！$b$b我不想等了，我要我媽媽！', 28153),
(136428, 'zhTW', '你在這裡做什麼？', '你在這裡做什麼？', 28153),
(136427, 'zhTW', '', '族母在哪？我想回家！', 28153),
(136426, 'zhTW', '', '族母去哪了？她離開了好久。', 28153),
(136425, 'zhTW', '', '好冷啊…族母在哪？', 28153),
(136422, 'zhTW', '另一個要去納茲米爾的傢伙？你回不來了，相信我。', '', 28153),
(136421, 'zhTW', '', '哼。我知道了。我會前往納茲米爾，希望我們可以趕上公主。', 28153),
(136420, 'zhTW', '塔蘭姬已經在納茲米爾了？那我要快點出發了。待會見。', '', 28153),
(136419, 'zhTW', '', '我們一秒都不能浪費。都好幾天沒有獵鷹林的消息了。', 28153),
(136418, 'zhTW', '', '我…我應該可以溜進我妹妹所在的洞穴裡。我會在那裡跟你碰面。', 28153),
(136417, 'zhTW', '', '我要去納茲米爾了。待會見。', 28153),
(136415, 'zhTW', '好的食材在沃魯敦不太好找，但如果你閉上眼睛、吃快一點，食物其實不如你想像的那麼難吃！', '', 28153),
(136414, 'zhTW', '如果你想知道羊駝的事，你來對地方了！關於羊駝的一切，我可是什麼都知道！', '', 28153),
(136413, 'zhTW', '沃魯敦或許是個危險的荒原，但這是我唯一的家。', '', 28153),
(136407, 'zhTW', '我們要去一個全祖達薩都沒人想去的地方，最好做好準備。', '', 28153),
(136406, 'zhTW', '攻擊！', '', 28153),
(136405, 'zhTW', '我還帶了這位外地者。他想跟你談談，偉大的羅亞。', '', 28153),
(136404, 'zhTW', '來，就是這樣。', '', 28153),
(136403, 'zhTW', '啊，這聲音我認得！還有禮物，很好。進來吧，快進來呀！', '', 28153),
(136402, 'zhTW', '大寶車出動了！我們需要增援部隊！', '', 28153),
(136398, 'zhTW', '我身體像燒起來啦！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(136397, 'zhTW', '啊啊啊啊！', '', 28153),
(136396, 'zhTW', '偉大的伯昂撒姆第，這鼓聲因你而響亮！這都是獻給你的！', '', 28153),
(136395, 'zhTW', 'Doba quzhu ta tawbo! Metah bo chu!', '', 28153),
(136394, 'zhTW', '非常好。現在開始擊鼓！', '', 28153),
(136393, 'zhTW', '照著指示踏出腳步，畫出一個儀式法陣。小心點！要是儀式搞砸，伯昂撒姆第會氣炸的。', '', 28153),
(136388, 'zhTW', '你那個順手做的任務好了沒？可以拜託你<嗝>專業一點嗎？', '', 28153),
(136387, 'zhTW', '毒刺？呃，應該會有合理的用途吧。', '', 28153),
(136386, 'zhTW', '喂，這裡很危險耶！<嗝>別離我太遠可以嗎！', '', 28153),
(136385, 'zhTW', '呃…看來我也只能等了。', '', 28153),
(136384, 'zhTW', '<嗝>這裡啦！', '', 28153),
(136383, 'zhTW', '喂，你還在等什麼？！', '', 28153),
(136382, 'zhTW', '<嗝>嗨，小蜥蜴。', '', 28153),
(136380, 'zhTW', '準備戰鬥！Lok-tar ogar！', '', 28153),
(136379, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [300]挖隧道', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [300]挖隧道', 28153),
(136378, 'zhTW', '嘿，$g朋友：寶貝;。讓我告訴你戰爭前線最新科技的完整情報：\n\n坑道。\n\n沒錯。只要一大筆黃金，我的同事與我就會幫你與你的戰友們挖一條通往前線的坑道。你意下如何？', '', 28153),
(136377, 'zhTW', '這裡很複雜。讓<嗝>我來說話就好。', '', 28153),
(136376, 'zhTW', '我們到了。自由港。', '', 28153),
(136375, 'zhTW', '嗯。上次是往右…這次就往左！看來我總算清醒了。', '', 28153),
(136374, 'zhTW', '', '我們必須在塞斯拉克發現球體不見前，將它帶回營地！快走！', 28153),
(136373, 'zhTW', '啊，就快到了，我有感覺。', '', 28153),
(136372, 'zhTW', '天啊，走真遠。需要再喝一點點…', '', 28153),
(136371, 'zhTW', '什…什麼？你是誰？這是什麼？', '什…什麼？你是誰？這是什麼？', 28153),
(136370, 'zhTW', '那東西在控制我的大腦？！', '那東西在控制我的大腦？！', 28153),
(136369, 'zhTW', '啊哈！這裡很眼熟。走這裡<嗝>一定不會錯。', '', 28153),
(136368, 'zhTW', '發…發生什麼事了？', '發…發生什麼事了？', 28153),
(136367, 'zhTW', 'Uq naggwa…我們的主人…會來找你的…', 'Uq naggwa…我們的主人…會來找你的…', 28153),
(136366, 'zhTW', '太遲了！你阻止不了在你面前湧起的浪潮！', '太遲了！你阻止不了在你眼前掀起的浪潮！', 28153),
(136365, 'zhTW', '啊，這樣好多了。我們走吧。', '', 28153),
(136364, 'zhTW', '嗚，頭好暈。我需要一點小酒清醒清醒。', '', 28153),
(136363, 'zhTW', '不對。絕對是往右邊。', '', 28153),
(136362, 'zhTW', '<嗝>該往那邊走…左邊嗎？', '', 28153),
(136361, 'zhTW', '細語…它們讓我完全無法思考…', '細語…它們讓我完全無法思考…', 28153),
(136360, 'zhTW', '我的靈魂獻給海洋…', '我的靈魂獻給海洋…', 28153),
(136359, 'zhTW', 'Y\'za qam yyqzz…', 'Y\'za qam yyqzz…', 28153),
(136358, 'zhTW', '噢，入侵者，你闖入了你不該來的地方！', '噢，入侵者，你闖入了你不該來的地方！', 28153),
(136357, 'zhTW', '你的心臟會是很好的祭品！', '你的心臟會是很好的祭品！', 28153),
(136356, 'zhTW', '我完全臣服於這股力量！', '我完全臣服於這股力量！', 28153),
(136350, 'zhTW', '%s在跟隨你。', '', 28153),
(136349, 'zhTW', '%s不想繼續跟著你，跑走了。', '', 28153),
(136348, 'zhTW', '', '既然大海恢復平靜，我們該把注意力放在洞穴上。', 28153),
(136347, 'zhTW', '蠟燭擺好了，祭品也都準備就緒了。現在該來畫出法陣…', '', 28153),
(136346, 'zhTW', '喚天者寶石正在超載！誰知道你現在使用的話會發生什麼事？', '喚天者寶石正在超載！誰知道你現在使用的話會發生什麼事？', 28153),
(136345, 'zhTW', '為了部落！', '', 28153),
(136341, 'zhTW', '我們開始吧。', '我們開始吧。', 28153),
(136340, 'zhTW', '這些平原會因吸收我們敵人的血液而成長。', '', 28153),
(136327, 'zhTW', '', '小心！', 28153),
(136326, 'zhTW', '', '小心！', 28153),
(136325, 'zhTW', '好吧…我應該準備好了。還是可以補救的。', '', 28153),
(136324, 'zhTW', '讓弗茲魯克去攻擊高地駐營。', '讓弗茲魯克去攻擊高地駐營。', 28153),
(136323, 'zhTW', '讓弗茲魯克去攻擊英勇之喚小徑。', '讓弗茲魯克去攻擊英勇之喚小徑。', 28153),
(136322, 'zhTW', '讓弗茲魯克去攻擊激流堡。', '讓弗茲魯克去攻擊激流堡。', 28153),
(136321, 'zhTW', '<弗茲魯克向下瞪著你。>', '', 28153),
(136320, 'zhTW', '樂意之至。', '', 28153),
(136319, 'zhTW', '我會把你碎屍萬段！', '', 28153),
(136318, 'zhTW', '蠢貨，其他人也會來…把寶石搶回去…', '', 28153),
(136317, 'zhTW', '你不可能阻止我們找出喚天者寶石的真正力量！', '', 28153),
(136316, 'zhTW', '沙漠將會繼續擴張！', '', 28153),
(136315, 'zhTW', '為塞斯拉克奪下納茲米爾！', '', 28153),
(136314, 'zhTW', '這片土地會變成一片沙地！', '', 28153),
(136313, 'zhTW', '我們接下來就會征服你的土地！', '', 28153),
(136312, 'zhTW', '你阻止不了我們的！', '', 28153),
(136311, 'zhTW', '應該把沼澤翻過一遍！', '', 28153),
(136310, 'zhTW', '我們會統治這一切！', '', 28153),
(136309, 'zhTW', '這片土地將化為沙漠！', '', 28153),
(136297, 'zhTW', '你怎麼可以這樣？！', '', 28153),
(136296, 'zhTW', '你…你殺了我這輩子最愛的人！', '', 28153),
(136295, 'zhTW', '啊…拜託…被塞斯拉克砍成兩半…這根本不可行吧。', '', 28153),
(136292, 'zhTW', '我來給你大海的祝福！希望你接受海洋溫柔的懷抱，成為浪潮的盟友。', '', 28153),
(136291, 'zhTW', '席帕拉…會讓你受難…', '', 28153),
(136290, 'zhTW', '這是席帕拉的神聖祭壇。他會笑納新的靈魂成為他的收藏！', '', 28153),
(136278, 'zhTW', '這個世界…將會沉沒…ak yar qi\'lwhuk h\'iwn…', '這個世界…將會沉沒…ak yar qi\'lwhuk h\'iwn…', 28153),
(136277, 'zhTW', '太遲了！你阻止不了我們的計畫！', '太遲了！你已經沒辦法阻止計畫了！', 28153),
(136276, 'zhTW', 'Ifis shuul qi\'nuq yyqzz…', '', 28153),
(136275, 'zhTW', '布蘭農‧斯陀頌恩是個軟弱的小鬼。真正的力量屬於大海！', '', 28153),
(136274, 'zhTW', '阿爾比？怎麼回事？斯陀頌恩領主在哪裡？', '', 28153),
(136273, 'zhTW', '瑟羅德，說了你也不會相信。真是大災難。', '', 28153),
(136272, 'zhTW', '別到處張揚！如果我們的任務失敗了，希瓦娜斯女士可不會給我們好臉色。', '', 28153),
(136271, 'zhTW', '塔克？我早該想到的。算了，反正他也為自己的無能賠上自己一條命。', '', 28153),
(136270, 'zhTW', '是塔克。第一個死在塞斯拉克手上的就是他。', '', 28153),
(136269, 'zhTW', '我們應該看得到來犯的部隊啊！哨點誰負責的？', '', 28153),
(136268, 'zhTW', '', '老大，我不覺得是我們的問題。對我們發動攻擊的傢伙原本也在這裡。', 28153),
(136267, 'zhTW', '英格麗，如果我們把事情辦好，她肯定會言出必行的。', '', 28153),
(136266, 'zhTW', '', '老大，她笑過嗎？', 28153),
(136265, 'zhTW', '好了，開始行動！我們在這一帶還有很多地方要偵察，而且我們不能再被伏擊了。', '', 28153),
(136264, 'zhTW', '<在你望向別處時，黑暗神像似乎會離開你的視線邊緣，但正眼看時它卻紋風不動。或許是光線的關係。又或許不是。>', '', 28153),
(136263, 'zhTW', '', '哦，得了吧！', 28153),
(136262, 'zhTW', '…那項資訊是機密。', '', 28153),
(136261, 'zhTW', '', '你第一次被砍成兩半是什麼時候。', 28153),
(136260, 'zhTW', '這不是我第一次被砍成兩半。希望這是最後一次。', '', 28153),
(136259, 'zhTW', '偶而啦。', '', 28153),
(136258, 'zhTW', '', '呃…克雷頓，我們是被遺忘者，被砍成兩半也不會死啦。', 28153),
(136257, 'zhTW', '老大，你是怎麼活下來的？我看到你被砍成兩半。', '', 28153),
(136256, 'zhTW', '', '好好享受寶石吧！我想儀式讓它…大致保存完好。', 28153),
(136255, 'zhTW', '吃臉的蟲？我要走了！', '吃臉的蟲？我要走了！', 28153),
(136254, 'zhTW', '他們怎麼可以讓這種事情發生？夠了，我們必須加入公會。', '他們怎麼可以讓這種事情發生？夠了，我們必須加入公會。', 28153),
(136253, 'zhTW', '也正好是我的休息時間，我要離開這裡了。', '也正好是我的休息時間，我要離開這裡了。', 28153),
(136252, 'zhTW', '我會到更高的地方去，告訴小隊隊員們要去哪裡找我。', '', 28153),
(136251, 'zhTW', '我很習慣看到貨物裡有各種怪物屍塊，不過你說活著的怪物？這免談。', '我很習慣看到貨物裡有各種怪物屍塊，不過你說活著的怪物？這免談。', 28153),
(136250, 'zhTW', '只要把那個塞進去…', '', 28153),
(136249, 'zhTW', '', '我會在包裝區的另一端跟你碰面。我要看看城鎮內部發生什麼事。', 28153),
(136248, 'zhTW', '', '這裡怎麼了？這…怎麼回事？', 28153),
(136243, 'zhTW', '', '「千萬不要實驗暗影魔法的效果」。$B$B他們警告我：「你的好奇心會毀掉艾澤拉斯。」$B$B我把他手臂扯下來的時候，他尖聲說道：「把手臂還我，你不能這個當成零件！」$B$B抱歉，我剛好在回想往事！', 28153),
(136242, 'zhTW', '好的很，看來我們可以留下來觀賞閃電秀。', '', 28153),
(136241, 'zhTW', '反對。', '', 28153),
(136240, 'zhTW', '反對。', '', 28153),
(136239, 'zhTW', '…還有反對的。', '', 28153),
(136238, 'zhTW', '贊成。', '', 28153),
(136237, 'zhTW', '我最好跟著去，確保一切都不會出差錯。', '', 28153),
(136236, 'zhTW', '', '贊成。', 28153),
(136235, 'zhTW', '', '贊成。', 28153),
(136234, 'zhTW', '我們來投票吧：誰想待在危險的沼澤裡，欣賞蛇人屠殺秀？', '', 28153),
(136233, 'zhTW', '', '拜託，查德維克！$n快把喚天者寶石拿到手了，到時候我們就可以用這顆寶石燒光那些傢伙！', 28153),
(136232, 'zhTW', '我的法師和我會和你在上頭會合。', '', 28153),
(136231, 'zhTW', '真想不到會在這裡見到友善的面孔。感謝搭救，你聽過英格麗的計畫了嗎？', '', 28153),
(136230, 'zhTW', '我們不該傻到毫無準備地來這麼危險的地方的…', '', 28153),
(136229, 'zhTW', '', '我會趁你對付希立斯的時候離開這裡…然後出去看看這顆寶石有什麼用途！', 28153),
(136228, 'zhTW', '感謝你的救援，這些塞斯拉克在納茲米爾尋找某種暗影魔法，誰知道為了什麼？', '', 28153),
(136227, 'zhTW', '', '真是太好了。這些塞斯拉克需要某種魔法來解開其中一個神器的力量。', 28153),
(136226, 'zhTW', '你有收到你的貨物嗎？', '你有收到你的貨物嗎？', 28153),
(136225, 'zhTW', '啊！把這東西拿開！', '', 28153),
(136224, 'zhTW', '你這渾蛋！', '你這渾蛋！', 28153),
(136223, 'zhTW', '天啊！他殺了肯奈！', '天啊！他殺了肯奈！', 28153),
(136222, 'zhTW', '這可能造成問題，小心！', '', 28153),
(136221, 'zhTW', '其實幾分鐘前我才剛收到貨物！想看看嗎？', '', 28153),
(136220, 'zhTW', '', '我說啊，我已經好幾天沒見到斯陀頌恩的小子了。我希望他們可以讓比較有能力的人來當這裡的頭頭，不過我算哪根蔥啊？', 28153),
(136219, 'zhTW', '有注意到什麼奇怪的事嗎？', '有注意到什麼奇怪的事嗎？', 28153),
(136218, 'zhTW', '我這幾天都沒有收到新鮮的食材！如果沒有新鮮的蛇頸龍鰭，我該如何做我知名的餐點炸蛇頸龍？', '', 28153),
(136215, 'zhTW', '我相信該讓塞斯拉克體驗一下痛苦的真諦。', '', 28153),
(136212, 'zhTW', '嘿！看起來還不錯嘛！你曾經做過這個嗎？', '', 28153),
(136211, 'zhTW', '啊！沒關係，繼續。這個部分本來就麻煩，轉一下就好…', '', 28153),
(136210, 'zhTW', '拿我的腿時小心點就是了，它們在脫落後通常會扭來扭去。', '', 28153),
(136207, 'zhTW', '喂！把那東西還我！', '', 28153),
(136206, 'zhTW', '', '我的酒館不歡迎羽冠龍！', 28153),
(136205, 'zhTW', '', '什麼？你想幹嘛？', 28153),
(136200, 'zhTW', '好，後方交給我吧。', '', 28153),
(136199, 'zhTW', '吉恩，我需要你掩護後方。讓所有人同時進入城堡實在是太冒險了，一定會有陷阱。', '', 28153),
(136198, 'zhTW', '', '走吧。', 28153),
(136197, 'zhTW', '聽好了，各就各位。聽我的命令攻擊！', '', 28153),
(136196, 'zhTW', '沒錯…雖然我們已經盡可能在希瓦娜斯沒有防備時突襲，但還是不能小看她。', '', 28153),
(136194, 'zhTW', '你有發現什麼不尋常的東西嗎？', '你有發現什麼不尋常的東西嗎？', 28153),
(136193, 'zhTW', '需要什麼嗎？', '', 28153),
(136192, 'zhTW', '', '嗯，有什麼事嗎？', 28153),
(136191, 'zhTW', '歡迎！歡迎！想吃點什麼嗎？', '', 28153),
(136187, 'zhTW', '你應該不介意助我一臂之力吧？其實是我的腳有點問題，我的手跟手臂都很好。', '', 28153),
(136179, 'zhTW', '該讓那些聯盟的雜碎見識一下部落的力量了！', '', 28153),
(136178, 'zhTW', '從我們的狼還是幼獸時，牠們就被訓練要用來戰鬥。', '', 28153),
(136177, 'zhTW', '我沒有時間閒聊，還有很多事要做。', '', 28153),
(136176, 'zhTW', '', '嗯？找我有什麼事嗎？', 28153),
(136170, 'zhTW', '珍娜！感謝聖光，你來了！我們現在非常需要你。', '', 28153),
(136169, 'zhTW', '', '凱爾瓦克斯是我們的兒子，可是他現在只不過是一頭怪物。消滅他吧，這樣我們才能把他的靈魂送回伯昂撒姆第身邊。', 28153),
(136167, 'zhTW', '', '凱爾瓦克斯要踐踏跟伯昂撒姆第有關的一切。找到那個骨匣，我們就可以結束這場鬧劇。', 28153),
(136166, 'zhTW', '', '協助淨化伯昂撒姆第的古老聖所。它原本是如此輝煌，真是不勝唏噓…', 28153),
(136165, 'zhTW', '', '等等…那裡有人…而且不是鮮血食人妖！嘿，在這裡！', 28153),
(136164, 'zhTW', '', '我製造的東西…怎麼會輸…', 28153),
(136163, 'zhTW', '', '這些靈魂都是我的！', 28153),
(136162, 'zhTW', '這樣下去，我們永遠沒辦法為伯昂撒姆第淨化這個地方！', '', 28153),
(136161, 'zhTW', '', '啊，你來了！沐敦芭剛剛跟我報告了。看來你們經歷了不少事啊。', 28153),
(136160, 'zhTW', '', '我活著的時候就負責保衛這片林地。我絕對不當女巫的走狗！', 28153),
(136159, 'zhTW', '好…美…', '', 28153),
(136156, 'zhTW', '', '小心一點。你傷口很深。', 28153),
(136153, 'zhTW', '我們隨時都能離開。', '我們隨時都能離開。', 28153),
(136152, 'zhTW', '', '獨自穿越這些沙丘絕對不安全。', 28153),
(136151, 'zhTW', '活著的時候，我保衛這片土地。\n\n就算死了，我依然遵守這個誓言。', '', 28153),
(136150, 'zhTW', '', '我們會在「另一邊」等你。', 28153),
(136149, 'zhTW', '伯昂撒姆第就要到了，他們會帶給我們安息！', '', 28153),
(136148, 'zhTW', '不，我不想去見伯昂撒姆第，我不想要…求求你，不要！', '', 28153),
(136147, 'zhTW', '', '伯昂撒姆第會決定你的命運，你就看他有沒有我們這麼有慈悲心。', 28153),
(136146, 'zhTW', '不，媽，我們得有點動作！', '', 28153),
(136145, 'zhTW', '一切都太遲了，小子。你選擇背叛伯昂撒姆第，你得為自己的選擇負責。', '', 28153),
(136144, 'zhTW', '爸、媽…對不起，請原諒我。請幫我帶話給伯昂撒姆第！', '', 28153),
(136141, 'zhTW', '我負責處理死者。$b$b<艾倫聳聳肩。>$b$b這是我的工作。', '', 28153),
(136140, 'zhTW', '', '愚蠢的羅亞！地獄無門你偏要闖！', 28153),
(136116, 'zhTW', '走吧，我們回到地穴去。', '', 28153),
(136115, 'zhTW', '哈哈！敵人都完蛋啦！', '', 28153),
(136114, 'zhTW', '伯昂撒姆第…不！古翰說過我不可能被打敗的！', '', 28153),
(136113, 'zhTW', '別搞得緊張兮兮的！我的經驗告訴我，關於這些「怪物」的傳言遠比怪物本身還可怕！', '', 28153),
(136112, 'zhTW', '我總覺得不太對勁…$n，小心！', '', 28153),
(136111, 'zhTW', '好！帶頭的死了，剩下的好對付。我們好好的享用吧！', '', 28153),
(136110, 'zhTW', '呿！我詛咒你，也詛咒伯昂撒姆第，他無法擁有我的靈魂！', '', 28153),
(136109, 'zhTW', '你的靈魂將成為鮮血之神的食糧！', '', 28153),
(136108, 'zhTW', '凱爾瓦克斯再次弱化…靠你了！', '', 28153),
(136107, 'zhTW', '什麼…不可能的！沒人能束縛我，你做不到，伯昂撒姆第也不行！', '', 28153),
(136106, 'zhTW', '是時候面對伯昂撒姆第的審判了，我們拿到骨匣，而$n幫我取得遺骨來反制你的巫毒！', '', 28153),
(136105, 'zhTW', '母親，父親…', '', 28153),
(136104, 'zhTW', '', '住手！凱爾瓦克斯！', 28153),
(136103, 'zhTW', '你會與伯昂撒姆第的僕人一樣，遭受永恆的痛苦！', '', 28153),
(136102, 'zhTW', '夠了！血神要你去死…該死的伯昂撒姆第，我一定會完成這項旨意！', '', 28153),
(136101, 'zhTW', '沒關係，我親眼看過這個文明的興衰歷程…你阻止不了我的！', '', 28153),
(136100, 'zhTW', '什麼？我的僵屍…骷髏呢？怎麼搞得？', '', 28153),
(136099, 'zhTW', '愚蠢的凡人…我的軍隊會摧毀你。僕人們，上吧！', '', 28153),
(136096, 'zhTW', '喂！我沒認出你。你是來這幫忙的還是什麼？', '', 28153),
(136095, 'zhTW', '別再胡鬧了！', '別再胡鬧了！', 28153),
(136094, 'zhTW', '', '想打探艾胥凡的事情要多加小心。他們可是黑幕重重。', 28153),
(136093, 'zhTW', '打得不錯…你這個跳蚤咬爛的偷渡客。算你走運，我沒在上陸前找到你，否則我靴底踩的就是你的屍體。', '打得不錯…你這個無恥的偷渡客。算你走運，如果在上陸之前找到你，你就會變成我靴底的屍體。', 28153),
(136092, 'zhTW', '衝著我來吧，你們這些水妖！我要剝你們的皮來當新的旗子！', '衝著我來吧，你們這些水妖！我要剝你們的皮來當新的旗子！', 28153),
(136086, 'zhTW', '', '父王原本用鐵腕統治，沒有人敢違背律法，他同時也很公正，會幫助需要的人，深受人民愛戴。$b$b可是現在呢？已經談不上什麼鐵腕手段。他身邊的親信一面說著毒藥般的讒言，一面暗中圖謀著各種詭計。$b$b我不知道他們有什麼陰謀，但我知道人民沒有時間了。', 28153),
(136085, 'zhTW', '', '孩子們，殺死這傢伙！', 28153),
(136072, 'zhTW', '鮮血之潮會從北方向你襲來，而你只能屈膝臣服。', '鮮血之潮會從北方向你襲來，而你只能屈膝臣服。', 28153),
(136071, 'zhTW', '他們很快就會從納茲米爾來到這裡，而你們就會看到到我們目睹過的事。', '他們很快就會從納茲米爾來到這裡，而你們就會看到到我們目睹過的事。', 28153),
(136070, 'zhTW', '不！不！你不能阻止我們，他答應過我們，你不能阻止我們。', '不！不！你不能阻止我們，他答應過我們，你不能阻止我們。', 28153),
(136069, 'zhTW', '英雄之血會很值錢的。', '英雄之血會很值錢的。', 28153),
(136068, 'zhTW', '死人，是沒辦法向守衛告發我的。', '死人，是沒辦法向守衛告發我的。', 28153),
(136067, 'zhTW', '你算老幾，竟敢反抗我們？', '你算老幾，竟敢反抗我們？', 28153),
(136039, 'zhTW', '這是在幹什麼？敵人在後面！如果你不願意跟我一起對付他們，那我就自己去。', '', 28153),
(136015, 'zhTW', '桶子裡的貨物看來都是一些安全、常見的怪物肢體。', '', 28153),
(136003, 'zhTW', '該做個了結了！到河邊來找我。', '', 28153),
(135928, 'zhTW', '', '這些不死生物褻瀆了伯昂撒姆第的威名，我們必須解決這些傢伙！', 28153),
(135927, 'zhTW', '伯昂撒姆第的遺願必須要被實現。在那之前我們絕對不能懈怠下來。', '', 28153),
(135904, 'zhTW', '來我的洞穴裡。我們有許多事要完成。', '', 28153),
(135903, 'zhTW', '', '求求你！奎格瓦！請你原諒我！', 28153),
(135901, 'zhTW', '你已經自負到質問我看誰比較順眼嗎？', '', 28153),
(135900, 'zhTW', '', '是奎格瓦！真是光榮！但是我沒資格...因為我沒能阻止納迦。', 28153),
(135898, 'zhTW', '納雷茲，你證明了自己的價值，你現在是我的追隨者了。', '', 28153),
(135875, 'zhTW', '', '我會留在這裡監視納迦，向奎格瓦證明我的價值。再會。', 28153),
(135874, 'zhTW', '你別想，外來者！你別想從我這拿走我的生財工具！', '', 28153),
(135869, 'zhTW', '帶路吧。', '帶路吧。', 28153),
(135868, 'zhTW', '你是新來的？你是誰？$b$b如果你不先去見豪郝先生，他會不高興的。你最好跟我來。', '', 28153),
(135865, 'zhTW', '', '人們還說我留著「用途這麼特定」的卷軸很傻，呸！', 28153),
(135861, 'zhTW', '%s傷重不治。', '%s傷重不治。', 28153),
(135843, 'zhTW', '', '喉魔…只是想要再…做…一個…', 28153),
(135842, 'zhTW', '', '你會變成很不錯的圖騰能量！', 28153),
(135795, 'zhTW', '<巨大青蛙死亡、倒在泥潭裡>', '', 28153),
(135777, 'zhTW', '散開！', '', 28153),
(135776, 'zhTW', '啊啊啊！', '', 28153),
(135774, 'zhTW', '流氓！', '', 28153),
(135772, 'zhTW', '咦！', '', 28153),
(135771, 'zhTW', '我要向豪郝先生告狀！', '', 28153),
(135770, 'zhTW', '那是我的！', '', 28153),
(135769, 'zhTW', '啊！陌生人危險！', '', 28153),
(135768, 'zhTW', '豪郝先生不會喜歡這個的！', '', 28153),
(135741, 'zhTW', '什麼？', '什麼？', 28153),
(135740, 'zhTW', '$r對巫醫說了什麼？', '', 28153),
(135733, 'zhTW', '他錯了。是對我們造成了損傷沒錯，不過祖爾搭乘我們的艦隊逃跑了，還引發了幾場戰爭。我們留在這裡，撐了過來，然後重建這座城市，因為這才是贊達拉人該做的事。', '', 28153),
(135732, 'zhTW', '祖爾的預言？呸！他有告訴你，贊達拉什麼時候會沉到海裡嗎？', '', 28153),
(135726, 'zhTW', '我每個月都要看數百艘船在碼頭來來去去，並且確定每一艘都能準時靠港或離開。$b$b有話快說有屁快放，我忙得不得了。', '', 28153),
(135719, 'zhTW', '', '繼續。', 28153),
(135701, 'zhTW', '有很多關於席帕拉的故事，但我不知道哪些是真的。可以肯定的是，古人們都怕他。\n\n聽說席帕拉讓人們的身體因為腐爛而脹大。\n\n或是讓任何看他的人變成活生生的骷髏。\n\n或是他會潛伏在陰影中，在夜晚才出沒，吞食熟睡的人們。\n\n或是他會在道路附近等候，讓人們咳血死去。\n\n就連最勇敢的戰士都知道要遠離這個地方。', '', 28153),
(135699, 'zhTW', '席帕拉是誰？', '席帕拉是誰？', 28153),
(135694, 'zhTW', '', '我…我應該可以溜進我妹妹所在的洞穴裡。我會在那裡跟你碰面。', 28153),
(135683, 'zhTW', '你來這裡做什麼，$c?', '', 28153),
(135680, 'zhTW', '我們準備好要開始審判了。', '我們準備好要開始審判了。', 28153),
(135679, 'zhTW', '拖延對你沒有好處。我們一定會找出威奎斯特小姐背地裡隱藏的真相！', '', 28153),
(135674, 'zhTW', '我們的蠍尾獅騎士可能落地了，但真正的力量是蘊藏在斧柄中！', '', 28153),
(135673, 'zhTW', '不管有沒有火砲，我們的實力無人可敵！', '', 28153),
(135670, 'zhTW', '我會把你大卸八塊！', '', 28153),
(135638, 'zhTW', '那些怪物殺掉我最後一位信徒。我要讓他們見識一下長達萬年的憤怒！', '', 28153),
(135610, 'zhTW', '', '這會帶你到下面的房間，塔蘭姬公主在裡面等你。小心台階。', 28153),
(135604, 'zhTW', '', '跟我來。我帶你們從最好走的路下去。', 28153),
(135586, 'zhTW', '', '有機會的話就來看我，我迫不及待想跟你分享我從這些蝕刻文件發現的東西！', 28153),
(135579, 'zhTW', '', '不用擔心我…我可以自己回到競技場。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(135578, 'zhTW', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t 亞茲瑪開始對|cFFFF0000$n|r施放|cFFFF0404|Hspell:249924|h[靈魂撕裂]|h|r！', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t 亞茲瑪開始對$n施放|cFFFF0404|Hspell:249924|h[靈魂撕裂]|h|r！', 28153),
(135577, 'zhTW', '我感覺得到力量正在逐漸恢復…解毒劑發揮作用了。', '', 28153),
(135576, 'zhTW', '我不確定喬瓦芭還有多少時間…血清是她唯一的希望。', '', 28153),
(135574, 'zhTW', '喬瓦芭和塔茲金已經失蹤好幾天了，我開始擔心他們的安危…', '', 28153),
(135565, 'zhTW', '快點行動！不殺掉納迦，沒辦法解救奎格瓦的信徒。', '', 28153),
(135555, 'zhTW', '', '願奎格瓦祝福你。讓札爾卓希亞知道，膽敢招惹羅亞會是怎樣的下場。', 28153),
(135539, 'zhTW', '我們必須阻止納迦。別把你自己套在我的生活裡。', '', 28153),
(135511, 'zhTW', '帶我去見神王拉斯塔哈。', '帶我去見神王拉斯塔哈。', 28153),
(135496, 'zhTW', '我們的城鎮遭受攻擊！', '我們的城鎮遭受攻擊！', 28153),
(135492, 'zhTW', '我派了一些工人去幫你開挖那個礦層。', '', 28153),
(135486, 'zhTW', '礦場遭受攻擊！', '礦場遭受攻擊！', 28153),
(135469, 'zhTW', '', '什麼事？', 28153),
(135466, 'zhTW', '這垃圾卷軸…趕快找到修克！', '', 28153),
(135465, 'zhTW', '來！我正想辦法找到修克，你一定幫得上忙。別撞倒那個圖騰！', '', 28153),
(135464, 'zhTW', '怎麼不做正事呢？想辦法找到修克！', '', 28153),
(135457, 'zhTW', '', '或許有些附帶的損傷，但我很確定我們最終會把碎片都拼回去的。我們或許需要再召集幾個研究助理…', 28153),
(135456, 'zhTW', '這裡的靈魂對此不會太高興的，別說我沒有警告你！', '', 28153),
(135455, 'zhTW', '嘿！你最好不要往那些骸骨上丟炸彈！', '', 28153),
(135446, 'zhTW', '', '入侵者死！', 28153),
(135445, 'zhTW', '', '你會向我們屈服的！', 28153),
(135444, 'zhTW', '', '不…我不會失敗的！', 28153),
(135443, 'zhTW', '', '不…答應過會給我…力量的…', 28153),
(135442, 'zhTW', '', '我會讓你求生不得、求死不能！', 28153),
(135441, 'zhTW', '', '你也一樣會變成奴隸！', 28153),
(135440, 'zhTW', '', '你擋不住我的！', 28153),
(135439, 'zhTW', '我要把你的心臟獻給主人！', '', 28153),
(135432, 'zhTW', '聯盟已拿下一處艾澤萊晶岩礦層！', '', 28153),
(135431, 'zhTW', '$n守住了艾澤萊晶岩的礦層。', '', 28153),
(135430, 'zhTW', '部落拿下一座艾澤萊晶岩礦脈了！', '', 28153),
(135429, 'zhTW', '$n已突襲一處艾澤萊晶岩礦層！', '', 28153),
(135405, 'zhTW', '非常好。但你要知道，我會請求神王獵捕這隻怪物。', '', 28153),
(135400, 'zhTW', '夠了。將軍，退下吧。這名部落的手下已經克服了兩個部族的挑戰了。依據律法，你必須讓他們通過。', '', 28153),
(135399, 'zhTW', 'I\'m placeholder text. If you see this, Josh has made a mistake.', 'I\'m placeholder text. If you see this, Josh has made a mistake.', 28153),
(135388, 'zhTW', '人們都說在國王的妻子死後，他就不曾離開他的王座了。', '人們都說在國王的妻子死後，他就不曾離開他的王座了。', 28153),
(135387, 'zhTW', '部落？在祖達薩這裡？這真是糟糕，這非常糟糕。', '部落？在祖達薩這裡？這真是糟糕，這非常糟糕。', 28153),
(135386, 'zhTW', '當祖爾離開時，他帶走了我們好多人。現在他們說鮮血食人妖在攻擊我們北部的邊界。', '當祖爾離開時，他帶走了我們好多人。現在他們說鮮血食人妖在攻擊我們北部的邊界。', 28153),
(135385, 'zhTW', '', '呃…很抱歉，內陸人。看來我得再請你幫一個忙了。', 28153),
(135384, 'zhTW', '看來你是非等不可了。', '', 28153),
(135383, 'zhTW', '', '誰知道要查多久！', 28153),
(135382, 'zhTW', '不管怎樣，除非找出村莊怪事背後的真相，否則你別想得到赦免！', '', 28153),
(135381, 'zhTW', '', '什麼？！可是我都通過了！', 28153),
(135380, 'zhTW', '我還是很懷疑。這無法解釋造箭師谷地發生的怪事。', '', 28153),
(135379, 'zhTW', '安靜！審判結果由我來決定！', '', 28153),
(135378, 'zhTW', '她可能根本不是女巫！那我們該怎麼辦？', '她可能根本就不是女巫！那我們該怎麼辦？', 28153),
(135377, 'zhTW', '她在吐！這怎麼可能！', '', 28153),
(135376, 'zhTW', '', '噢…我覺得不太…', 28153),
(135375, 'zhTW', '', '我當然可以。拿毒液，內陸人。', 28153),
(135374, 'zhTW', '你能證明自己不只是空殼嗎？威奎斯特小姐？', '', 28153),
(135373, 'zhTW', '大家都知道女巫不需要食物，而是靠吞噬靈魂來得到力量。她的身體只是空殼子。', '', 28153),
(135372, 'zhTW', '真是奇怪，但還不能下定論。來進行最後的測試吧…看看她是不是會嘔吐。', '', 28153),
(135371, 'zhTW', '血蠅沒有從她身上逃開。要說的話，還叮得比平常凶！', '血蠅沒有從她身上逃開。要說的話，還叮得比平常凶！', 28153),
(135370, 'zhTW', '', '啊！嗚！噢，好痛！', 28153),
(135369, 'zhTW', '', '不用擔心我。叮幾下沒關係的。', 28153),
(135368, 'zhTW', '現在...放出血蠅，看看是不是會從女巫身上逃開！', '', 28153),
(135367, 'zhTW', '第二個測試是讓蚊蟲叮咬。大家都知道就連嗜血的血蠅，都不會吸女巫骯髒的血。', '', 28153),
(135366, 'zhTW', '冷靜，冷靜。她說不定耍了什麼把戲。我們繼續進行審判。', '', 28153),
(135365, 'zhTW', '她在哭！女巫不會哭，對吧？！', '她在哭！女巫不會哭，對吧？！', 28153),
(135364, 'zhTW', '', '來吧，內陸人。讓他們看看。', 28153),
(135363, 'zhTW', '被告到底有沒有辦法哭呢？讓我們看看，好做出判決。', '', 28153),
(135362, 'zhTW', '第一個測試是會不會流淚。請所有人注意，威奎斯特小姐目前為止可是連一滴眼淚都沒有流。', '', 28153),
(135361, 'zhTW', '她選擇由這位內陸人來執行測試。真是不尋常…但是，為了展現誠意，我表示同意。', '', 28153),
(135360, 'zhTW', '依照慣例，已經由威奎斯特小姐選出測試方法，來證明自己沒有犯下使用巫術的罪行。', '', 28153),
(135359, 'zhTW', '總算啊！審判可以開始了！', '', 28153),
(135358, 'zhTW', '你們有完沒完？我都快沒耐性了！', '', 28153),
(135357, 'zhTW', '我聽過一個故事說，以前有個女巫就住在沼澤裡。村民會發現她是女巫，是因為血蠅都不敢靠近她。\n\n血蠅誰都叮，就是不會叮她！\n\n據說這是因為女巫的血太骯髒了，連血蠅都不想碰！', '', 28153),
(135356, 'zhTW', '我從來沒有看過真正的女巫。這樣是不是很刺激？！', '', 28153),
(135355, 'zhTW', '要是在以前啊，我們會在女巫身上綁重物，把她們沉到河裡！這樣還會浮起來的話，我們就知道她們一定有什麼古怪，一定要吊死！\n\n對我來說這就是對付女巫唯一的方法！', '', 28153),
(135354, 'zhTW', '女巫的邪惡詛咒害了我兒子！今天一定要伸張正義！', '', 28153),
(135353, 'zhTW', '', '嗯…我不知道…\n\n有傳言說女巫絕對不會嘔吐，因為她們肚子裡什麼東西都沒有，只有黑暗的靈魂。 \n\n不過，我是不知道你要怎麼證明啦…', 28153),
(135352, 'zhTW', '', '我們一定要想辦法解除村裡的詛咒。\n\n說真的，把施咒的女巫殺掉就可以解除詛咒了嗎？', 28153),
(135351, 'zhTW', '我聽說女巫的身體不怕火燒，所以抓到女巫的時候，我們都是把她們吊死！\n\n你要是想說服我的話，就拿火炬燒她！', '', 28153),
(135350, 'zhTW', '那個女人把邪惡力量帶到這裡來，我們一定要讓她好看！', '', 28153),
(135349, 'zhTW', '', '嗯，我媽跟我說過，女巫不管怎樣都不會哭，再痛、再傷心也不會。\n\n威奎斯特小姐聽到自己要被抓去審判，卻一滴眼淚都沒流，她一定是女巫！', 28153),
(135348, 'zhTW', '你要怎麼證明某個人不是女巫？', '你要怎麼證明某個人不是女巫？', 28153),
(135347, 'zhTW', '', '審判很可怕，但這是為了幫造箭師谷地伸張正義！', 28153),
(135346, 'zhTW', '威奎斯特小姐決定要用哪種測試方法了嗎？', '', 28153),
(135345, 'zhTW', '終於！那就開始吧！', '', 28153),
(135344, 'zhTW', '治安官！你可以繼續進行…審判了。', '', 28153),
(135343, 'zhTW', '你替我們爭取了時間，內陸人。希望這些村民不是存心要傷害威奎斯特小姐。', '', 28153),
(135342, 'zhTW', '', '救我？難道你為了救我，打算把這些村民全都砍死嗎？\n\n絕對不行。如果你想救我，就跟元帥一起幫我的忙。\n\n就算他們的指控無憑無據，他們依然是我的人民，我不能為了自身安危去傷害他們。我會挺身接受審判，證明我是清白無辜的。\n\n不過，我擔心元帥會自作主張採取行動，我被困在這裡無法動彈。你看看能否說服他，不要干擾這場審判。', 28153),
(135341, 'zhTW', '我是來救你的。', '我是來救你的。', 28153),
(135340, 'zhTW', '', '很抱歉把你牽扯到這件事裡來，這些人都是好人，只是最近實在發生太多事了。', 28153),
(135339, 'zhTW', '', '你不能這麼做，元帥！我命令你退下！', 28153),
(135338, 'zhTW', '沒時間跟你們爭了。要是不讓開，我們就來硬的！', '', 28153),
(135337, 'zhTW', '威奎斯特小姐有施行巫術的嫌疑！除非她能獲得赦免，否則我們不可能把她交給你的！', '', 28153),
(135336, 'zhTW', '治安官弗雷默！我命令你立刻釋放威奎斯特小姐，把她交給我！', '', 28153),
(135335, 'zhTW', '又有人攪局！？這次又是什麼事？！', '', 28153),
(135334, 'zhTW', '你看！有騎兵從樹林過來了！', '你看！有騎兵從樹林過來了！', 28153),
(135333, 'zhTW', '哼，我最討厭有人攪局！你有什麼事，內陸人？', '', 28153),
(135332, 'zhTW', '治安官！有陌生人來了！', '治安官！有陌生人來了！', 28153),
(135331, 'zhTW', '你必須接受審判 -', '', 28153),
(135330, 'zhTW', '露西爾‧威奎斯特！你被指控施行巫術，並且對造箭師谷地的村莊施加詛咒！', '', 28153),
(135301, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [70] 生成戰鬥機動車', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [70] 生成戰鬥機動車', 28153),
(135286, 'zhTW', '', '我真是傻，獨自脫隊找尋遠古聖物…', 28153),
(135281, 'zhTW', '你…<嗝！>…你在看什麼，夥伴？', '', 28153),
(135272, 'zhTW', '我們來討論一下要怎麼對抗鮮血食人妖。', '我們來討論一下要怎麼對抗鮮血食人妖。', 28153),
(135265, 'zhTW', '', '應該還有一個…在這裡！', 28153),
(135263, 'zhTW', '', '找到了！烏龜的羅亞，托加。他仁慈又睿智，一定會幫助我們！我來看看還有哪位羅亞在這裡…', 28153),
(135261, 'zhTW', '', '納茲米爾是被詛咒的土地…但還是有羅亞居住。退後點…我來看看哪位羅亞在這裡。', 28153),
(135226, 'zhTW', '謝謝你！這真是一場噩夢。', '', 28153),
(135225, 'zhTW', '你一定要阻止她！', '', 28153),
(135224, 'zhTW', '發生什麼事了？', '', 28153),
(135221, 'zhTW', '我要殺了你！', '', 28153),
(135220, 'zhTW', '你竟敢插手主人的事！', '', 28153),
(135209, 'zhTW', '', '我們看看那邊有什麼…', 28153),
(135190, 'zhTW', '來，小指頭！我有好吃的點心要給你！', '來，小指頭！我有好吃的點心要給你！', 28153),
(135189, 'zhTW', '聯盟已經佔領礦坑。', '聯盟已經佔領礦坑。', 28153),
(135188, 'zhTW', '看起來簡直像過動兒，不過結果還不賴吧？哈哈哈！', '', 28153),
(135187, 'zhTW', '只要持有這支桅杆…，就能指揮我的船員…', '', 28153),
(135185, 'zhTW', '有些人會期待艦隊歸來。但我很清楚記得那些和祖爾一起出航的食人妖，他們很常生氣。', '有些人會期待艦隊歸來。但我很清楚記得那些和祖爾一起出航的食人妖，他們很常生氣。', 28153),
(135184, 'zhTW', '祖爾被拖回贊達拉的事是真的嗎？我敢說他對此不是很高興。', '祖爾被拖回贊達拉的事是真的嗎？我敢說他對此不是很高興。', 28153),
(135179, 'zhTW', '我不喜歡部落，但你殺了很多聯盟的人渣，還真是不錯。', '我不喜歡部落，但你殺了很多聯盟的人渣，還真是不錯。', 28153),
(135178, 'zhTW', '你真的和塔蘭姬公主並肩作戰？她有沒有把別人的臉融化？她有沒有把誰的頭剖開？她的妖術怎麼樣？', '你真的和塔蘭姬公主並肩作戰？她有沒有把別人的臉融化？她有沒有把誰的頭剖開？她的妖術怎麼樣？', 28153),
(135177, 'zhTW', '我聽說你的族類在追隨不死領袖，老伯昂撒姆第對此不會高興的。', '我聽說你的族類在追隨不死領袖，老伯昂撒姆第對此不會高興的。', 28153),
(135176, 'zhTW', '你是部落的人？沃金真的死了嗎？', '你是部落的人？沃金真的死了嗎？', 28153),
(135175, 'zhTW', '感謝羅亞，塔蘭姬公主回來了。她離開的時間並不長，但反對她的人需要的時間也不多。', '感謝羅亞，塔蘭姬公主回來了。她離開的時間並不長，但反對她的人需要的時間也不多。', 28153),
(135174, 'zhTW', '先是非食人妖，現在還有部落？塔蘭姬還要讓什麼人進入我們的城市？', '先是非食人妖，現在還有部落？塔蘭姬還要讓什麼人進入我們的城市？', 28153),
(135173, 'zhTW', '部落的人在這？黑暗時代啊。', '部落的人在這？黑暗時代啊。', 28153),
(135147, 'zhTW', '我…怎麼回事？我要離開這裡！', '', 28153),
(135140, 'zhTW', '父親，幫幫我。請你指引我。我需要…', '', 28153),
(135138, 'zhTW', '陛下，攻城塔幾乎全毀，死傷的士兵也越來越多…', '', 28153),
(135002, 'zhTW', '我沒辦法就這樣把這東西放在這裡。趕快取走，否則我就拿回去了！', '', 28153),
(135001, 'zhTW', '若沒有人快點開啟寶箱，我就必須啟動召回陣列！', '', 28153),
(134991, 'zhTW', '也不能每次都贏。我們走吧！', '', 28153),
(134989, 'zhTW', '什麼？沒人要嗎？隨便你們！', '', 28153),
(134976, 'zhTW', '我先看到的！', '我先看到的！', 28153),
(134975, 'zhTW', '介意我骰需嗎？', '介意我骰需嗎？', 28153),
(134877, 'zhTW', '好，我們上吧。第一個把它打開的人就能拿走全部寶藏！', '', 28153),
(134876, 'zhTW', '還有十五秒。準備迎接大型騷動！', '', 28153),
(134875, 'zhTW', '正在解鎖！給我三十秒，可以嗎？', '', 28153),
(134869, 'zhTW', '補給品來了！小心你們的頭！', '', 28153),
(134867, 'zhTW', '聽好，我們有一批補給品要送往低地！', '', 28153),
(134811, 'zhTW', '解鎖完畢！勝者就能拿走戰利品！', '', 28153),
(134810, 'zhTW', '還有十五秒解鎖完成！', '', 28153),
(134809, 'zhTW', '已啟動解鎖程序！倒數三十秒。', '', 28153),
(134790, 'zhTW', '投下補給品！下面的當心！', '', 28153),
(134789, 'zhTW', '要對低地空投補給品了！', '', 28153),
(134699, 'zhTW', '', '繼續向前，英雄。我跟這條蛇還有話要說。', 28153),
(134678, 'zhTW', '我們不會殺死青蛙，但我們會殺掉你！', '', 28153),
(134676, 'zhTW', '我們會把你的青蛙朋友關在籠裡，汲取它們的力量！', '', 28153),
(134675, 'zhTW', '我必須保護她的新法力來源！', '', 28153),
(134674, 'zhTW', '卑劣的$r！我們本該得到新的法力之源！', '', 28153),
(134673, 'zhTW', '只要我們殺了你，就能得到更多青蛙！', '', 28153),
(134672, 'zhTW', '上面的人命令我們不要殺死青蛙，但我們可以殺掉你！', '', 28153),
(134671, 'zhTW', '你阻止不了我們。青蛙將能餵飽我們好幾年！', '', 28153),
(134670, 'zhTW', '', '青蛙是屬於納迦的！', 28153),
(134669, 'zhTW', '', '我們不會讓你搶走我們的青蛙！', 28153),
(134668, 'zhTW', '', '殺死竊法者！', 28153),
(134667, 'zhTW', '', '這些青蛙現在屬於我們！', 28153),
(134666, 'zhTW', '', '青蛙是我們的，蠢貨！', 28153),
(134665, 'zhTW', '', '這些青蛙本該滿足我們接下來幾年的法力之癮！', 28153),
(134664, 'zhTW', '', '我們會用這些青蛙來救我們的族人！', 28153),
(134663, 'zhTW', '', '這些青蛙會成為我們的法力之源！', 28153),
(134661, 'zhTW', '部落對泰達希爾的卑劣攻擊，開始了戰爭…也讓我們看清了現狀。', '', 28153),
(134656, 'zhTW', '奎格瓦會賞賜虔誠的你，來吧。', '', 28153),
(134652, 'zhTW', '', '我的長老說過有關奎格瓦的故事，沒人相信他…除了我，我想證明那是真的。', 28153),
(134651, 'zhTW', '納雷茲，我知道，不論何時何地，你一直十分虔誠地信奉著奎格瓦。', '', 28153),
(134650, 'zhTW', '', '等等！在你離開之前…', 28153),
(134649, 'zhTW', '我該回獸穴了，謝謝你的幫忙。', '', 28153),
(134648, 'zhTW', '他們甚至說你父親決定示弱，還派他唯一的女兒去請求祖爾帶著艦隊回來。那是真的嗎，殿下？', '', 28153),
(134647, 'zhTW', '', '你敢用這種口氣和我說話—', 28153),
(134646, 'zhTW', '只要殺掉札爾卓希亞，剩下的納迦就不成問題。祝好運。', '', 28153),
(134639, 'zhTW', '敵方石毀車已在南方部落陣地出現！', '敵方石毀車已在南方部落陣地出現！', 28153),
(134638, 'zhTW', '', '我在山丘這裡這麼久了，從來沒有看過這種怪物！', 28153),
(134637, 'zhTW', '<向她出示祖爾之言>', '<向她出示祖爾之言>', 28153),
(134630, 'zhTW', '', '我…我不知道我妹妹跟她朋友在計畫什麼，只知道不是什麼好事。跟鮮血獻祭有關的一定不是好事！', 28153),
(134629, 'zhTW', '', '好…好多雙腿！好多對眼睛！他們都在找我！', 28153),
(134620, 'zhTW', '', '我們需要一位真正的領導人，而不是一個虛弱的國王！', 28153),
(134618, 'zhTW', '', '我邊境守軍疲軟、人民虛弱。我們需要唯有祖爾可以帶來的力量。', 28153),
(134617, 'zhTW', '', '牢記我們的先知祖爾之言。牢記他向我們的子民預見的末日。', 28153),
(134616, 'zhTW', '', '在王座上腐朽的神王拉斯塔哈已經沒有力氣謁見他的子民，或是根本沒有那個膽量。我們需要一個強力的領導者！', 28153),
(134615, 'zhTW', '', '祖爾預見了浩劫與重生，但我們什麼都沒做。我們眼睜睜看著我們的國王把他流放、我們眼睜睜看著祖爾帶著我們的兄弟姐妹們一起流亡。後來，我們目睹浩劫與重生帶來的毀滅！', 28153),
(134613, 'zhTW', '', '祖爾將會重臨，並讓我們的帝國在灰燼中重生。', 28153),
(134610, 'zhTW', '', '時候到了！我一定要告訴其他人，告訴那些始終信奉他的人。', 28153),
(134599, 'zhTW', '', '艾薩拉女王，我不會讓你失望！青蛙會落入我們手中，我保證！', 28153),
(134598, 'zhTW', '', '你重視的青蛙都會被裝進籠裡，為我們效命！', 28153),
(134597, 'zhTW', '', '無禮的雜碎！我們的族人終將滿足法力之癮，不會再感到飢渴，不用再苦苦渴求！', 28153),
(134596, 'zhTW', '', '為什麼…只差一點…就再也不會渴求…魔法…', 28153),
(134595, 'zhTW', '', '你！你搞砸了一切…接下來幾年，青蛙本該成為我們的法力之源！', 28153),
(134594, 'zhTW', '納迦會為他們的罪行付出代價。', '', 28153),
(134593, 'zhTW', '札爾卓希亞居然敢對我們做出這種事情，該讓她付出代價了。', '', 28153),
(134592, 'zhTW', '我的力量又開始流動了…謝謝你，奎格瓦會知道你的善行的。', '', 28153),
(134591, 'zhTW', '我的力量又回來了！你做得很好，奎格瓦會知道你的善行的。', '', 28153),
(134590, 'zhTW', '我感覺…自己很厲害！真的很謝謝你，我必須先回奎格瓦一趟了。', '', 28153),
(134589, 'zhTW', '', '多年前，當他自流放中回到我們艦隊時。$b$b他描述了關於某一天世界將會流血的幻覺，而且他還詳盡地描述了你的樣子。', 28153),
(134588, 'zhTW', '你上次和祖爾談話是什麼時候？', '你上次和祖爾談話是什麼時候？', 28153),
(134587, 'zhTW', '', '你！是你！$b$b祖爾向我描述過你，鉅細靡遺。在你臉上…有那個…東西。和他描述的一樣。$b$b快告訴我是不是真的？你真的是來幫他傳話的嗎？', 28153),
(134584, 'zhTW', '終於。自從雷王甦醒過來以後，我就一直在救這頭傳信獸。看來牠知道牠的死期到了。', '', 28153),
(134583, 'zhTW', '那青蛙的魔力可以讓我們的人民溫飽，我們再也不會沒水可用了！', '', 28153),
(134581, 'zhTW', '<把祖爾之言拿給他看。>', '<讓他看祖爾之言。>', 28153),
(134580, 'zhTW', '什麼事，外來者？', '', 28153),
(134492, 'zhTW', '', '救兵終於來了！我不小心被納迦偷襲，我們必須救那些青蛙。', 28153),
(134471, 'zhTW', '', '啊，看看誰來了。暴風城的小獅子終於探出頭了？你根本就搞不清楚狀況，小國王。我們才剛要開始呢！', 28153),
(134465, 'zhTW', '', '嗯…我在這裡等待、躲藏，我最討厭兩個東西。查明納迦為什麼需要這些青蛙！', 28153),
(134464, 'zhTW', '你的實力就這樣嗎，風行者？！', '', 28153),
(134463, 'zhTW', '所有部隊，進攻大門！勝利屬於聯盟！', '', 28153),
(134460, 'zhTW', '', '在玷汙這些青蛙之前，這些納迦不會離開。', 28153),
(134453, 'zhTW', '公主現在不在這，救不了你。', '公主現在不在這，救不了你。', 28153),
(134451, 'zhTW', '哈哈，除了我之外沒有人會救你。', '哈哈，除了我之外沒有人會救你。', 28153),
(134450, 'zhTW', '守衛才不在乎你這種骯髒外來者的命。', '守衛才不在乎你這種骯髒外來者的命。', 28153),
(134449, 'zhTW', '我的刀子說，你要給我很好的優惠。', '我的刀子說，你要給我很好的優惠。', 28153),
(134448, 'zhTW', '你的保護費又遲交了。', '你的保護費又遲交了。', 28153),
(134447, 'zhTW', '殿下，你聞不到攥住這座城市的恐懼嗎？', '', 28153),
(134442, 'zhTW', '嘿…嘿…貨已經送出去了…', '', 28153),
(134439, 'zhTW', '啊！又有肉可以拿來灌香腸了！', '', 28153),
(134438, 'zhTW', '哈！你們自己人還在內鬥，讓你嚐嚐部落的厲害。', '', 28153),
(134330, 'zhTW', '每個人自求多福！', '每個人自求多福！', 28153),
(134329, 'zhTW', '這是混亂！我必須避往安全之處。', '這是混亂！我必須避往安全之處。', 28153),
(134328, 'zhTW', '這些穴居怪突然冒出來！', '這些穴居怪突然冒出來！', 28153),
(134310, 'zhTW', '神廟已經變成廢墟，比我預想的還糟。', '', 28153),
(134309, 'zhTW', '在被謀殺之前，我是這座神廟的照料者。不知道在我死後數十年後，現在情況究竟是如何…', '', 28153),
(134300, 'zhTW', '噢！壞恐龍，壞壞！', '噢！壞恐龍，壞壞！', 28153),
(134299, 'zhTW', '你好厲害！', '你好厲害！', 28153),
(134298, 'zhTW', '啊！我的手指！', '啊！我的手指！', 28153),
(134297, 'zhTW', '如果你一直胡鬧，我可要打你了！', '如果你一直胡鬧，我可要打你了！', 28153),
(134296, 'zhTW', '噢！不准咬人！', '噢！不准咬人！', 28153),
(134295, 'zhTW', '小心點…小心！', '小心點…小心！', 28153),
(134292, 'zhTW', '%s顫抖並哀鳴。', '', 28153),
(134291, 'zhTW', '%s警覺地吱吱叫。', '', 28153),
(134290, 'zhTW', '%s恐懼地嘶叫。', '', 28153),
(134289, 'zhTW', '我會陪你穿過神廟遺跡。', '我會陪你穿過神廟遺跡。', 28153),
(134288, 'zhTW', '尼可朝著鼬的方向叫了起來。', '', 28153),
(134279, 'zhTW', '他們在吸收我的魔力！', '', 28153),
(134278, 'zhTW', '他們正在偷走我們的魔法！', '', 28153),
(134277, 'zhTW', '呃…我的魔力消散了…', '', 28153),
(134276, 'zhTW', '我覺得…力量都被抽走了…他們抽走了我的力量！', '', 28153),
(134275, 'zhTW', '這些惡魔綁走了我的朋友！', '', 28153),
(134274, 'zhTW', '那些傢伙正在吸收我的魔力！', '', 28153),
(134272, 'zhTW', '這次不會了…', '', 28153),
(134271, 'zhTW', '聯盟不會丟下任何人！', '', 28153),
(134270, 'zhTW', '她在復活死者！我們要撤出受傷的人！', '', 28153),
(134266, 'zhTW', '勝利屬於被遺忘者！', '', 28153),
(134263, 'zhTW', '陛下，這荒疫太危險了！我們不該冒險…', '', 28153),
(134252, 'zhTW', '聖光保佑。把受傷的人帶來找我！', '', 28153),
(134233, 'zhTW', '', '謝謝，剩下的我自己就可以應付了！', 28153),
(134230, 'zhTW', '野蠻的東西！', '可惡的東西！', 28153),
(134229, 'zhTW', '為了…國王…為了羅德…', '我不行了…為了國王…為了羅德…', 28153),
(134227, 'zhTW', '敵人一直出現，沒完沒了！快來幫我擊退他們！', '敵人一直出現，沒完沒了！快來幫我擊退他們！', 28153),
(134226, 'zhTW', '', '啊…誰來幫個忙？', 28153),
(134224, 'zhTW', '', '弓箭手，上箭！前進！', 28153),
(134223, 'zhTW', '英雄！敵人太多了！我怕…他們撐不了多久了…', '', 28153),
(134211, 'zhTW', '好美…', '', 28153),
(134209, 'zhTW', '等等，你聽到了嗎？', '', 28153),
(134208, 'zhTW', '舵手，快轉彎！', '舵手，快轉彎！', 28153),
(134186, 'zhTW', '你說的對！是時候正式讓$p入幫了，準備進行儀式！', '', 28153),
(134164, 'zhTW', '', '來吧，卓可，我們繼續搜索。', 28153),
(134163, 'zhTW', '', '這裡簡直無聊透頂。', 28153),
(134162, 'zhTW', '', '你叫我們來幹嘛？', 28153),
(134161, 'zhTW', '', '你知道那個喚狼的$r發生了什麼事嗎？', 28153),
(134159, 'zhTW', '', '你覺得這是場遊戲嗎？', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(134158, 'zhTW', '不會吧…有人尿在桶子裡…', '', 28153),
(134157, 'zhTW', '客戶急著要貨物！我們要出發了！', '客戶急著要貨物！我們要出發了！', 28153),
(134156, 'zhTW', '', '時程改了，大家！你們的酒都外帶吧！', 28153),
(134155, 'zhTW', '', '你為什麼要浪費我們的時間？', 28153),
(134151, 'zhTW', '', '信號煙火可不是玩具。', 28153),
(134150, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] 防守南方聯盟陣地', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] 防守南方聯盟陣地', 28153),
(134149, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] 防守北方聯盟陣地', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] 防守北方聯盟陣地', 28153),
(134125, 'zhTW', '', '算了，我們不能等他。我已經找到知道洛琪拉在哪裡的人。跟我來，這邊走！', 28153),
(134123, 'zhTW', '', '別在這裡浪費時間了。要是有什麼發現，就發射照明彈。', 28153),
(134116, 'zhTW', '這片土地是我們的，賤種！你的代價就是死！', '', 28153),
(134115, 'zhTW', '士兵！集合列隊！', '', 28153),
(134111, 'zhTW', '我對這裡可一點也不會留戀。', '', 28153),
(134109, 'zhTW', '', '對於一個離我的劍這麼近的人來說，你的要求還真多。', 28153),
(134101, 'zhTW', '你不屬於這裡！', '你不屬於這裡！', 28153),
(134100, 'zhTW', '喔喔，這空桶子是我的！另外一個桶子給你。', '', 28153),
(134099, 'zhTW', '快，躲好！', '', 28153),
(134096, 'zhTW', '艾胥凡的小秘密。', '', 28153),
(134095, 'zhTW', '這是什麼？！', '', 28153),
(134094, 'zhTW', '確定要使用50|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t戰爭前線黃金建造哨兵塔？', '確定要使用50|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t戰爭前線黃金建造哨兵塔？', 28153),
(134093, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] 建造哨兵塔', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] 建造哨兵塔', 28153),
(134092, 'zhTW', '知道了，知道了，曼佐。我們早該聽你的話，你就不會淪落到這個地步。我們早該照你的計畫做，你很聰明，我都知道。現在給我閉嘴，不然我就再打斷你的鼻子！', '', 28153),
(134091, 'zhTW', '曼佐！這是間讓人賓至如歸的旅店，讓過去隨風而逝吧。', '', 28153),
(134090, 'zhTW', '哈！你喜歡你的作風，$p，但別做夢了，那個醜陋的眼罩和耀眼的微笑就是他僅剩的東西。', '', 28153),
(134089, 'zhTW', '沃尼，別再向我們的客人發起生死決鬥，你剛殺死的那兩個人還沒付錢。', '', 28153),
(134088, 'zhTW', '想說就大聲說！你們兩隻小老鼠在那邊窸窸窣窣，我聽不見！', '', 28153),
(134087, 'zhTW', '你別想騙任何人，沃尼。我知道你喜歡我送你的帽子，在你承認之前，我都不會動它！', '', 28153),
(134086, 'zhTW', '停一下，鼓聲響個不停，她聽不見你的聲音。休息一下，葛倫妮雅！$p想向你致意。葛倫妮雅是我們的吟遊詩人，但她有時候會忘記人們需要在這裡講話。', '', 28153),
(134085, 'zhTW', '…$p，你還好嗎？你快把葛倫妮雅嚇死了…你是不是中暑了？', '', 28153),
(134084, 'zhTW', '眼睛很利，$p！還在祖達薩的時候，葛倫妮雅幫助我們逃離許多險境。她幫我們闖過許多道門…老實說，還擺脫許多人。', '', 28153),
(134079, 'zhTW', '好吧，該去做事了！', '', 28153),
(134078, 'zhTW', '無論如何，你對我們整個村子有恩，我很感謝你。我來看看能怎麼幫你吧…', '', 28153),
(134077, 'zhTW', '我覺得他們不會想把賭注押在一個內陸人身上。', '', 28153),
(134076, 'zhTW', '詛咒降臨了這片土地，在事情開始不對勁的時候，威奎斯特家的人什麼事都不做，就夾著尾巴溜了。他們躲在莊園宅邸裡，任由不知名的邪惡力量蹂躪這些人民。', '', 28153),
(134075, 'zhTW', '你要找威奎斯特家那群膽小鬼？我覺得這對你不會有什麼幫助。', '', 28153),
(134074, 'zhTW', '我希望能跟威奎斯特家的領主見上一面。', '我希望能跟威奎斯特家的領主見上一面。', 28153),
(134073, 'zhTW', '我真不知道該怎麼謝你才能表達我的感激，內陸人。\n\n落港村全村的命都是你救的。', '', 28153),
(134072, 'zhTW', '我能幫你什麼忙嗎，$c？', '', 28153),
(134070, 'zhTW', '', '啊，你回來了！你去得有點久，遇到什麼事了嗎？', 28153),
(134069, 'zhTW', '', '你可以用我的火箭飛回基地。不過只能用一次喔，準備好出發之前別亂動火箭。', 28153),
(134068, 'zhTW', '', '嘿，呃…你很厲害，但剩下的我們可以自己來。', 28153),
(134067, 'zhTW', '我們快走。', '我們快走。', 28153),
(134066, 'zhTW', '紐特宣稱這座火箭可以製成一台安全的單程載具，不過這看起來就很脆弱，我實在不敢恭維。', '', 28153),
(134065, 'zhTW', '摧毀所…所有抵抗勢…勢力！女王萬歲…歲！', '', 28153),
(134064, 'zhTW', '破壞神…神殿來的東西…西！', '', 28153),
(134063, 'zhTW', '為女王守…守住聖…聖物！', '', 28153),
(134062, 'zhTW', '女王要這些…些聖…聖物！動作…作快點！', '', 28153),
(134061, 'zhTW', '很高興看大家平安無事，多虧了…嘿！大英雄來了！', '', 28153),
(134060, 'zhTW', '我的…寶藏…', '', 28153),
(134059, 'zhTW', '你竟敢碰我的寶藏！', '', 28153),
(134018, 'zhTW', '<試著打開箱子。>', '<試著打開箱子。>', 28153),
(134017, 'zhTW', '箱子關得很緊，但你用力一點應該可以打開它。', '', 28153),
(134016, 'zhTW', '', '看來又有艘聯盟的船入港停泊了。希望他們沒有受到跟珍娜一樣的「待客之道」…', 28153),
(134015, 'zhTW', '你救了我的命！', '', 28153),
(134014, 'zhTW', '我不會忘記這一次的，謝謝你！', '', 28153),
(134013, 'zhTW', '下次我請你喝一杯！', '', 28153),
(134012, 'zhTW', '謝謝你，我差點就撐不下去了。', '', 28153),
(134011, 'zhTW', '納迦把其他人上鍊帶走了，請救救他們！', '', 28153),
(134010, 'zhTW', '血與榮耀！下次見面的時候，我請客！', '', 28153),
(134009, 'zhTW', '', '我不知道你到底怎麼了，但看樣子確實有用！你…你還好嗎？', 28153),
(134007, 'zhTW', '為了聯盟！', '為了聯盟！', 28153),
(134003, 'zhTW', '團結奮戰，為了聯盟！', '', 28153),
(134001, 'zhTW', '為了保護我們的未來，我們一定要女妖之王付出代價！在今天終結她的黑暗統治！', '', 28153),
(134000, 'zhTW', '打從一開始，部落大酋長的陰謀就不是攻佔城市，而是摧毀我們的生活…摧毀後代子孫的希望。', '', 28153),
(133999, 'zhTW', '團結奮戰，擊退她的黑暗勢力！讓我們的旗幟，再度飄揚在羅德隆的天空！', '', 28153),
(133998, 'zhTW', '聯盟的兄弟姐妹們，都聽好了！', '', 28153),
(133996, 'zhTW', '安杜因國王帶頭進攻了！繼續推進，拿下戰場！', '', 28153),
(133990, 'zhTW', '攻城機具隨時都能出動！', '', 28153),
(133989, 'zhTW', '一個優秀的$G小伙子:小姑娘;，一架攻城機具！', '', 28153),
(133988, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [100] 打造攻城機具', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [100] 打造攻城機具', 28153),
(133986, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] 訓練迫擊砲兵－攻擊北方', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] 訓練迫擊砲兵－攻擊北方', 28153),
(133985, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] 訓練騎士－攻擊北方', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] 訓練騎士－攻擊北方', 28153),
(133984, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] 訓練步槍兵－攻擊北方', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] 訓練步槍兵－攻擊北方', 28153),
(133983, 'zhTW', '我需要跟你拿更多錢才能完成交易。', '', 28153),
(133982, 'zhTW', '歡迎光臨小店！', '', 28153),
(133981, 'zhTW', '', '獸欄管理員路西亞‧法隆戴爾，聽候差遣！', 28153),
(133980, 'zhTW', '', '訓練我們的騎士相當昂貴，$n。', 28153),
(133979, 'zhTW', '', '很高興再次見到你，$n！我能幫你什麼？', 28153),
(133974, 'zhTW', '', '訓練可不是免費的！$B$B存多一點金幣再回來找我！', 28153),
(133971, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] 訓練騎士－攻擊南方', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] 訓練騎士－攻擊南方', 28153),
(133970, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] 訓練迫擊砲兵－攻擊南方', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] 訓練迫擊砲兵－攻擊南方', 28153),
(133969, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] 訓練步槍兵－攻擊南方', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] 訓練步槍兵－攻擊南方', 28153),
(133968, 'zhTW', '', '怎麼那麼慢？該開始工作了！', 28153),
(133960, 'zhTW', '<有禮貌地自我介紹。>', '<有禮貌地自我介紹。>', 28153),
(133959, 'zhTW', '<有禮貌地自我介紹。>', '<有禮貌地自我介紹。>', 28153),
(133958, 'zhTW', '', '她安全嗎？我那時候叫卡嘉不要來找我的。', 28153),
(133953, 'zhTW', '這座沉沒的城市原本是供奉海之羅亞格拉爾的美麗神廟。$b$b然而，納迦出手毀了神廟，殺了他的所有追隨者。$B$B就算格拉爾還活著，實力也不如往常。', '', 28153),
(133952, 'zhTW', '怎麼了？我們遭到攻擊了嗎？', '', 28153),
(133951, 'zhTW', '從天上掉下什麼東西了！就在那邊！', '', 28153),
(133950, 'zhTW', '我的兄弟們對納迦的恨意正在讓他們失去判斷力。這不是第一次煞因女士和她的盤懼納迦跟蹤我們找到這樣的發現。$b$b要知道，他們知道我們掌握了他們所不知道的事情。', '', 28153),
(133947, 'zhTW', '', '你會求饒的！', 28153),
(133946, 'zhTW', '我需要前往幽暗谷。', '我需要前往幽暗谷。', 28153),
(133945, 'zhTW', '你會死在我的劍下！', '你會死在我的劍下！', 28153),
(133944, 'zhTW', '你需要人載一程嗎？', '', 28153),
(133943, 'zhTW', '不留活口！', '我不留活口！', 28153),
(133942, 'zhTW', '', '擅自闖入者死！', 28153),
(133941, 'zhTW', '', '把營地拆了。不管哥吉他們在研究什麼，全都帶來給我。', 28153),
(133939, 'zhTW', '海盜女王一定會幫我報仇！', '', 28153),
(133938, 'zhTW', '是誰讓這個白癡上船的？', '', 28153),
(133936, 'zhTW', '死吧，蛆蟲！', '死吧，蛆蟲！', 28153),
(133935, 'zhTW', '你很勇敢是吧？', '你很勇敢是吧？', 28153),
(133934, 'zhTW', '你的東西就是我的！交出來！', '你的東西就是我的！交出來！', 28153),
(133933, 'zhTW', '這裡是艾胥凡公司的土地！', '這裡是艾胥凡公司的土地！', 28153),
(133929, 'zhTW', '這裡不歡迎你！', '這裡不歡迎你！', 28153),
(133928, 'zhTW', '你休想活著離開這裡！', '你休想活著離開這裡！', 28153),
(133926, 'zhTW', '我不會忘記你的善行…', '我不會忘記你的善行…', 28153),
(133925, 'zhTW', '折磨總算結束了…', '折磨總算結束了…', 28153),
(133924, 'zhTW', '陌生人，十分感謝你…', '陌生人，十分感謝你…', 28153),
(133923, 'zhTW', '我就知道伊拉卡‧諾‧金布爾會派人來幫助我們…', '我就知道伊拉卡‧諾‧金布爾會派人來幫助我們…', 28153),
(133919, 'zhTW', '我總算可以安息了…', '我總算可以安息了…', 28153),
(133918, 'zhTW', '我就知道羅亞不會遺棄我們…', '我就知道羅亞不會遺棄我們…', 28153),
(133917, 'zhTW', '越過跳耀點。如果你沒跳超過一半的話，裁判也許就不會算了。', '越過跳耀點。如果你沒跳超過一半的話，裁判也許就不會算了。', 28153),
(133916, 'zhTW', '如果太快或太慢跳，你的馬可能會讓你摔下來。', '如果太快或太慢跳，你的馬可能會讓你摔下來。', 28153),
(133915, 'zhTW', '別擔心，我不會再迷路了！我知道你一定會來找我。', '', 28153),
(133913, 'zhTW', '當慢跑時，你可以使用奔馳來再次加速！', '當慢跑時，你可以奔馳來再次加速！', 28153),
(133912, 'zhTW', '使用慢跑來快速移動。這是跳躍的最佳速度！', '使用慢跑來快速移動。這是跳躍的最佳速度！', 28153),
(133911, 'zhTW', '使用行走，就能往前行走，使用停止，就能隨時停止。', '使用行走，就能往前行走，使用停止，就能隨時停止。', 28153),
(133904, 'zhTW', '吉爾哥布林是可怕的生物。這些阿諛奉承的小型海中生物樂意為他們的納迦主人做任何事，而且無惡不作。', '', 28153),
(133899, 'zhTW', '說不定修克已經知道這裡不是個探險聖地，而是自助式墳場！', '', 28153),
(133893, 'zhTW', '不客氣，蠢貨。別再亂跑了！', '', 28153),
(133883, 'zhTW', '敵方石毀車已在北方部落陣地出現！', '敵方石毀車已在北方部落陣地出現！', 28153),
(133835, 'zhTW', '很不幸地，打造軍隊並不便宜，$n。我們必須餵養他們、訓練他們，並手工打造每一片護甲。\n\n等你有更多錢時再回來吧。', '', 28153),
(133834, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] 訓練步卒－攻擊南方', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] 訓練步卒－攻擊南方', 28153),
(133833, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] 訓練步卒－攻擊北方', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] 訓練步卒－攻擊北方', 28153),
(133832, 'zhTW', '', '這麼多的遺骸…你是吃…得到這種力量的？', 28153),
(133831, 'zhTW', '', '我們聽過你的傳聞…你應該很好吃！', 28153),
(133830, 'zhTW', '', '你最好…別想靠著吃我…獲得力量…', 28153),
(133829, 'zhTW', '', '在把你獻給圖騰之前，我不介意拿你的手臂當點心！', 28153),
(133828, 'zhTW', '', '我聽到聲音說…血肉…讓我們更強壯…', 28153),
(133827, 'zhTW', '', '那個聲音告訴我：你的血肉會給我們力量！', 28153),
(133820, 'zhTW', '戰爭前線黃金不足，無法建造建築物。', '戰爭前線黃金不足，無法建造建築物。', 28153),
(133819, 'zhTW', '建築物建造期間，無法建造其他建築物。', '建築物建造期間，無法建造其他建築物。', 28153),
(133806, 'zhTW', '當你再次蒞臨這座神廟，我們會把你當成朋友和貴賓。', '', 28153),
(133805, 'zhTW', '你的勇氣值得敬重，我將賜予你力量祝福，願你武運昌隆。', '', 28153),
(133804, 'zhTW', '還有，你拯救了我的追隨者的靈魂，讓他們免於毀滅，並幫助了這座神廟。', '', 28153),
(133803, 'zhTW', '庫巴卡終於就戮，遭竊的力量神器也從托塔卡手中奪了回來。', '', 28153),
(133801, 'zhTW', '托塔卡族已經無可救藥，必須殺死庫巴卡和他的族人，並且摧毀他們的黑暗力量之源。', '', 28153),
(133799, 'zhTW', '難以想像，他們對力量的渴望竟然讓他們墮落至此…現在該怎麼辦？', '', 28153),
(133798, 'zhTW', '在吸取神廟裡每一個靈魂的能量之前，托塔卡部族不會停手。', '', 28153),
(133794, 'zhTW', '確定要使用150|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t 戰爭前線黃金建造鐵匠鋪？', '確定要使用150|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t 戰爭前線黃金建造鐵匠鋪？', 28153),
(133793, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] 建造鐵匠舖', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] 建造鐵匠舖', 28153),
(133790, 'zhTW', '確定要使用150|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t戰爭前線黃金建造工坊？', '確定要使用150|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t戰爭前線黃金建造工坊？', 28153),
(133788, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] 建造工坊', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] 建造工坊', 28153),
(133786, 'zhTW', '確定要使用150|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t戰爭前線黃金建造獸欄？', '確定要使用150|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t戰爭前線黃金建造獸欄？', 28153),
(133785, 'zhTW', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] 建造獸欄', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] 建造獸欄', 28153),
(133784, 'zhTW', '選擇要在這個位置建造的建築物：', '選擇要在這個位置建造的建築物：', 28153),
(133775, 'zhTW', '修克闖禍了…再一次地！我真不敢相信那白癡被鮮血食人妖抓走了。', '', 28153),
(133769, 'zhTW', '修克，人呢？！修克！', '', 28153),
(133768, 'zhTW', '我知道要把大家集中到哪裡去，跟我來！', '', 28153),
(133765, 'zhTW', '你的靈魂注定毀滅！', '', 28153),
(133764, 'zhTW', '你的羅亞在這裡沒有用！', '', 28153),
(133763, 'zhTW', '你的靈魂屬於我們！', '', 28153),
(133760, 'zhTW', '托塔卡絕不容許任何人入侵！', '', 28153),
(133759, 'zhTW', '這裡不歡迎你！', '', 28153),
(133758, 'zhTW', '在這裡伊拉卡‧諾‧金布爾沒有權力！', '', 28153),
(133757, 'zhTW', '這裡的力量屬於我們！', '', 28153),
(133756, 'zhTW', '就連羅亞都別想阻止我們！', '', 28153),
(133755, 'zhTW', '讓你看看我真正的力量！', '', 28153),
(133754, 'zhTW', '力量是我們的！', '', 28153),
(133752, 'zhTW', '我們會吞噬你的靈魂！', '', 28153),
(133745, 'zhTW', '', '你知道多少我們的計畫？告訴我！', 28153),
(133742, 'zhTW', '', '說話！你知道這神殿的什麼秘密？', 28153),
(133741, 'zhTW', '', '你最好開口，不然你就會被淹死！', 28153),
(133732, 'zhTW', '你去救出修克，我會去一個比較安全的地方。我並不打算麻煩你一次救兩個人。', '', 28153),
(133731, 'zhTW', '[在碼頭停泊片刻後…]', '[在碼頭停泊片刻後…]', 28153),
(133730, 'zhTW', '謝謝你送我，小泰。我會去跟那個老傢伙回報。', '', 28153),
(133729, 'zhTW', '那白痴…他怎麼會想被鮮血食人妖抓走？', '', 28153),
(133728, 'zhTW', '…修克在納薩沃食人妖手上。', '', 28153),
(133727, 'zhTW', '不…不不！', '', 28153),
(133726, 'zhTW', '喔不...', '', 28153),
(133725, 'zhTW', '…別在我身邊打轉，快去找修克！', '', 28153),
(133724, 'zhTW', '是什麼聲音？我會保護公主，你去看一下。', '', 28153),
(133723, 'zhTW', '陌生人，落港村多虧了你。請告訴我們該怎麼報答你。', '', 28153),
(133722, 'zhTW', '真的很感謝你…我本來還以為不可能脫離詛咒了…', '', 28153),
(133721, 'zhTW', '這…是怎麼回事？', '', 28153),
(133720, 'zhTW', '', '你恢復了！看樣子村民們也快恢復了！', 28153),
(133719, 'zhTW', '', '你別想消除…我的詛咒…', 28153),
(133718, 'zhTW', '', '我們有遠古的力量。等死吧！', 28153),
(133717, 'zhTW', '', '讓你看看女巫會的力量！', 28153),
(133716, 'zhTW', '', '你要就逃吧，否則也是這種下場。', 28153),
(133715, 'zhTW', '', '蠢東西！村莊歸我了，這是母親的意思！', 28153),
(133714, 'zhTW', '那個女人很危險…但再怎麼樣都不會比我危險，要是你被我發現做了壞事的話你就知道了！', '那個女人很危險…但要是我發現你在做壞事，我會比她更危險好幾倍！', 28153),
(133713, 'zhTW', '不管你去那裡做什麼，最好都跟樹林裡的那個瘋女人沒有關係。', '不管你去那裡做什麼，最好都跟樹林裡的那個瘋女人沒有關係。', 28153),
(133712, 'zhTW', '親愛的丈夫…我不知道你到底想騙誰，不過我親眼看過你偷偷摸摸地溜到丘陵那邊去。你以為我睡了，其實我沒睡。', '親愛的丈夫…你可能覺得自己很聰明，但我親眼看到你在以為我睡著時，偷偷摸摸溜到丘陵那邊去。', 28153),
(133711, 'zhTW', '我會想辦法在這禮拜內再送一次貨。', '我會想辦法在這禮拜內再送一次貨。', 28153),
(133710, 'zhTW', '我養的豬得了某種怪病，變得出奇地凶猛。這樣一來就很難抓住牠們，集中運送。', '我養的豬得了某種怪病，變得出奇地凶猛。這樣一來就很難抓住牠們，集中運送。', 28153),
(133709, 'zhTW', '路上有個親切的老婦人給了我一點點植物，好用來餵豬，不過我覺得豬可能已經受到污染了。', '路上有個親切的老婦人給了我一點點植物，好用來餵豬，不過我覺得豬可能已經受到污染了。', 28153),
(133708, 'zhTW', '親愛的史托頓工頭，最新一批屠宰肉品時間慢了，我誠摯地道歉。', '親愛的史托頓工頭，最新一批屠宰肉品時間慢了，我誠摯地道歉。', 28153),
(133707, 'zhTW', '如果發現可疑的人事物，請立刻向懷特村長報告。', '', 28153),
(133706, 'zhTW', '另外，我們接獲報告，丘陵地區有危險生物出沒。所有因故必須離村的人都必須嚴加小心防範。', '', 28153),
(133705, 'zhTW', '為了安全起見，所有村民必須在日落前返回住處，不得延誤。', '', 28153),
(133704, 'zhTW', '由於最近的幾起失蹤事件，即日起落港村將嚴格執行新的宵禁命令。', '', 28153),
(133703, 'zhTW', '我用最後一把火炬打賭，這些怪事一定跟那個老巫婆有關！', '我用最後一把火炬打賭，這些怪事一定跟那個老巫婆有關！', 28153),
(133702, 'zhTW', '照這樣下去，我們再過一個月豬飼料就不夠用了。這個地方到底受了什麼詛咒？！', '照這樣下去，我們再過一個月豬飼料就不夠用了。這個地方到底受了什麼詛咒？！', 28153),
(133701, 'zhTW', '這些天殺的蟲子是從哪裡飛來的！每天早上都來，已經兩個禮拜了。', '這些天殺的蟲子是從哪裡飛來的！每天早上都來，已經兩個禮拜了。', 28153),
(133700, 'zhTW', '', '找找村民最近紀錄下來的事情，或許可以幫助我們釐清原因。', 28153),
(133699, 'zhTW', '', '我會看看能否在村裡的記錄簿上找到什麼線索。村民要是看到過什麼可疑的事，或許會留下記錄也不一定。', 28153),
(133698, 'zhTW', '', '噢不…不要連這個地方都出事！', 28153),
(133693, 'zhTW', '', '你不了解，如果賈克拉傑成功的話，那就沒有地方是安全的了。', 28153),
(133692, 'zhTW', '', '我不能丟下你送死！我們可以逃離這一切，到安全的地方重新開始啊。', 28153),
(133691, 'zhTW', '', '你不該為了我來的，卡加。', 28153),
(133690, 'zhTW', '', '我以為我不會再見到你了…', 28153),
(133689, 'zhTW', '摧毀一切圖騰總比一個都沒拆掉好，看看我們能不能找到那頭腦簡單的傢伙。', '', 28153),
(133688, 'zhTW', '修克！別鬧了，我已經太靠近鮮血食人妖的前哨站！', '', 28153),
(133686, 'zhTW', '', '洛琪拉！你還活著！', 28153),
(133685, 'zhTW', '卓蘭妮，我的刀刃啊，我們必須守住神廟。走吧！', '', 28153),
(133672, 'zhTW', '我要執行主人的命令！', '', 28153),
(133670, 'zhTW', '揍扁你！', '', 28153),
(133669, 'zhTW', '來吧，小神王。現在給這些異端份子一點教訓！', '', 28153),
(133668, 'zhTW', '我向你發誓，部落的勇士幫我見證，不拿下祖爾的頭顱我絕不罷休。', '', 28153),
(133667, 'zhTW', '是我變軟弱了。有很多人警告過我…包括我女兒在內，我卻沒有聽進去。', '', 28153),
(133666, 'zhTW', '現在該問問自己，你到底是國王？還是獵物？', '', 28153),
(133665, 'zhTW', '鮮血的氣味傳開了。', '', 28153),
(133664, 'zhTW', '臣屬在威脅你的地位。朋友在威脅你的性命。', '', 28153),
(133663, 'zhTW', '拉斯塔哈，敵人在侵犯你的疆界。', '', 28153),
(133648, 'zhTW', '偉大的羅亞，你沒事吧？來，我來幫你把鎖鍊解開。', '', 28153),
(133646, 'zhTW', '祖爾預告了你的到來，事情的進展全都如他所料。', '', 28153),
(133645, 'zhTW', '', '蠢貨！我要是有那個時間，就會讓你替沃卡爾償命！', 28153),
(133644, 'zhTW', '', '死吧，沙德拉！死個徹底！念在過去，你的力量就歸我吧！', 28153),
(133643, 'zhTW', '在你處理這些圖騰的時候，我會繼續推進，希望在圖騰清除乾淨之後，我們可以揪出那個頭腦簡單的傢伙。', '', 28153),
(133638, 'zhTW', '', '沃卡爾！解決這些入侵者，我要對付沙德拉。', 28153),
(133633, 'zhTW', '', '沙德拉！長久以來我都聽命於你。從現在開始，我要侍奉新的主人！', 28153),
(133632, 'zhTW', '', '你太遲了。羅亞已經沒救了！', 28153),
(133610, 'zhTW', '剛克生氣！剛克摧毀亞茲瑪！', '', 28153),
(133606, 'zhTW', '你的行為我都看在眼裡，你獲得我的祝福了。', '', 28153),
(133605, 'zhTW', '謝謝你，$n，我獻上我的祝福。', '', 28153),
(133591, 'zhTW', '<火箭側面有段潦草模糊的訊息。>$b$b注意：此為正式公文。$B$B非部落指揮官階級者不得閱讀！$b$b留言者：哥布林戰隊的派奇$b$b我的小隊接到重型武器運送任務，目的是讓納茲米爾的戰況有所進展。我們帶來的大砲能輕易摧毀任何擋路的玩意兒。$B$B我們搭乘「獻酒號」，目前正在東岸搜尋登陸地點。需要人員指引我們部署地點。', '', 28153),
(133582, 'zhTW', '*咆哮* 我會暫時留下，但這都是為了幫助我那些被你的愚蠢害死的追隨者的靈魂。', '', 28153),
(133581, 'zhTW', '那是個簡單的錯誤…但看看你身邊！這個地方沒有為你帶來快樂的回憶嗎？留下來，讓我們以你之名重建這座神廟！', '', 28153),
(133580, 'zhTW', '吾王，托爾托人的習俗非常奇特。我怎麼都想不到，拒絕求婚居然會被視為宣戰！', '', 28153),
(133579, 'zhTW', '你的任務非常簡單：與托塔卡族和平共處，並在我不在的時候，看護我的神廟。現在看一下這個地方！', '', 28153),
(133578, 'zhTW', '*呃哼* 是我，偉大的羅亞，你忠心耿耿的僕人，烏南丘。', '', 28153),
(133576, 'zhTW', '', '庫爾提拉斯這裡有個俗語。$B$B當壞事發生時，老水手會聳聳肩，宣稱：「你不能改變風向。」$B$B我討厭那個俗語。', 28153),
(133575, 'zhTW', '', '塞勒斯從我小時候就開始教導我。他教我戰技、騎術、以及如何航海。$B$B當我成為衛隊成員時，我已經比某些教練還要厲害了。$B$B他們不喜歡那樣。', 28153),
(133574, 'zhTW', '', '在戴林‧普勞德摩爾被擊敗後，一切都變了。$B$B珍娜一定有她的理由…對吧？', 28153),
(133573, 'zhTW', '', '我從小聽著偉大羅德隆王國的故事長大。$B$B以及它的殞落。$B$B甚至在我還沒懂事前，天譴軍就奪走了我的母親、父親、以及我的家園。', 28153),
(133572, 'zhTW', '我準備好做出我的選擇了。', '我準備好做出我的選擇了。', 28153),
(133571, 'zhTW', '這傢伙根本失控啦！！！', '', 28153),
(133570, 'zhTW', '', '你決定好接下來要如何了嗎？', 28153),
(133569, 'zhTW', '', '我很感謝你，$n。', 28153),
(133568, 'zhTW', '如果你在我們回來之前迷路，我不會再去找你了！', '', 28153),
(133567, 'zhTW', '回去和其他人會合吧，我有好多故事要講！', '', 28153),
(133566, 'zhTW', '小心，這些食人妖可能中邪了，他們怎麼會吃自己的同類？', '', 28153),
(133565, 'zhTW', '嗯…真美味！應該加點佐料的，還是下次吧。', '', 28153),
(133564, 'zhTW', '好餓…迅猛龍肉聽起來不錯。', '', 28153),
(133563, 'zhTW', '做好準備，凡人！獸王終於重返人世了！', '', 28153),
(133562, 'zhTW', '刃衛卡嘉派我來的。', '刃衛卡嘉派我來的。', 28153),
(133561, 'zhTW', '', '很高興看到喬瓦芭還活著。', 28153),
(133560, 'zhTW', '', '我欠你好多人情，$n。', 28153),
(133559, 'zhTW', '', '我想你最好穿上這套服裝，然後進入營地裡面。任何人如果敢碰洛琪拉，我可不敢保證我不會刀刃相向。', 28153),
(133558, 'zhTW', '我們的…寶藏…', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(133557, 'zhTW', '不准搶走邪鱗的寶物！', '', 28153),
(133556, 'zhTW', '我們只是灌香腸的普通人！怎麼會有人想傷害我們？', '', 28153),
(133555, 'zhTW', '', '我會盯著那個人類，要是他想逃跑，得先問過我的劍。', 28153),
(133554, 'zhTW', '我會自行前往海灘。等你拿到你要的東西，到那裡跟我會合。', '', 28153),
(133553, 'zhTW', '祭品已經就位，萬事俱備，我們可以召喚羅亞了。', '', 28153),
(133551, 'zhTW', '要面對這種邪惡，贊達拉需要盡可能獲得所有幫助。很幸運地，部落特地來此助拳。', '', 28153),
(133548, 'zhTW', '', '我會盯緊這個人，確保他哪裡也去不了。', 28153),
(133547, 'zhTW', '', '一場腥風血雨即將到來。我們必死無疑了嗎，$n？', 28153),
(133540, 'zhTW', '你去吧，傳達我的憤怒。我必須趕去羅亞身邊，不然就來不及了。', '', 28153),
(133539, 'zhTW', '', '為什麼…血肉…應該會給我…力量…', 28153),
(133538, 'zhTW', '', '不可能…你可不能吃掉我，你不能得到我的力量！', 28153),
(133537, 'zhTW', '', '嗯？據說我可以從吃人肉得到力量。你怎麼還不快死一死？！', 28153),
(133536, 'zhTW', '', '你聞起來蠻有力量的，我吃了你就能得到力量！', 28153),
(133534, 'zhTW', '', '我不會給你這個神器！', 28153),
(133532, 'zhTW', '啊，沒錯，我實在太蠢了…我忘了獻上祭品！我們不能兩手空空地召喚羅亞！', '', 28153),
(133527, 'zhTW', '嗯…一定出了什麼問題。塑像已經安放在祭壇上，為什麼羅亞還不歸來？', '', 28153),
(133526, 'zhTW', '', '這是洛琪拉的勳章，每個戰衛都有一個以表彰他們為國王而效力。至少她不是毫無抵抗就把它放棄。', 28153),
(133516, 'zhTW', '祖爾和他所有的追隨者很快就會知道，違逆羅亞總是得付出代價的。\n\n隨著分秒過去，他們欠的就會越來越多。', '', 28153),
(133515, 'zhTW', '', '我們來了！你有什麼發現？', 28153),
(133514, 'zhTW', '', '我們繼續追，距離應該很近了。', 28153),
(133505, 'zhTW', '', '國王，我會和你並肩作戰。部落會為他們的罪行付出代價。我來堵住入口，讓大家有時間重整旗鼓。', 28153),
(133503, 'zhTW', '至少兩個，然後他們是大的那個！啊，謝謝你為我治療。', '', 28153),
(133502, 'zhTW', '你差點就被吃了…你知道自己身體裡有多少長矛嗎？', '', 28153),
(133501, 'zhTW', '卡喬許，你應該看過那玩意才是！黑魔法肆虐、食人妖開始做些詭異動作，我的肚子甚至還被串了個長矛！', '', 28153),
(133500, 'zhTW', '白痴！你知道我多擔心你嗎？', '', 28153),
(133499, 'zhTW', '好險！我這點小傷很快就好，我這個老傢伙才沒這麼輕易出事。', '', 28153),
(133498, 'zhTW', '我醒了，好了！這真的有必要嗎？', '', 28153),
(133497, 'zhTW', '', '很好，你有看見我的照明彈！卓可在哪裡？', 28153),
(133496, 'zhTW', '呃，我還好，還可以活動。我會和卡喬許見面…我看…他應該怒火中燒！', '', 28153),
(133495, 'zhTW', '', '哈…你那個神器…還在…賈拉雅手上…', 28153),
(133494, 'zhTW', '', '吃掉那個托爾托人之後，下個就是吃你！', 28153),
(133492, 'zhTW', '', '這個市場有來自艾澤拉斯各地的旅人，還有很多旅店。這個是我最喜歡的。', 28153),
(133490, 'zhTW', '', '我看到的幻象…一定要阻止祖爾和亞茲瑪，$n！', 28153),
(133489, 'zhTW', '卡喬許派我過來，我會處理那些喉魔。', '卡喬許派我過來，我會處理那些喉魔。', 28153),
(133488, 'zhTW', '呃…如果你不是來吃我的…快走吧，保命要緊！\n\n食人妖等下就會過來…拿他們的「食物」。', '', 28153),
(133487, 'zhTW', '呃…他們來了，小心！', '', 28153),
(133481, 'zhTW', '這不是沙德拉的做法。她發生什麼事了？', '這不是沙德拉的做法。她發生什麼事了？', 28153),
(133480, 'zhTW', '祖爾和亞茲瑪要為這場叛變負責。一定要阻止他們！', '祖爾和亞茲瑪要為這場叛變負責。一定要阻止他們！', 28153),
(133479, 'zhTW', '我可不想這樣死掉。感謝你救了我！', '我可不想這樣死掉。感謝你救了我！', 28153),
(133478, 'zhTW', '我要跟羅亞談談這件事！', '我要跟羅亞談談這件事！', 28153),
(133477, 'zhTW', '今天很適合戰鬥，每天都很適合。', '', 28153),
(133476, 'zhTW', '血魔法天地不容！背叛者必須被阻止！', '', 28153),
(133475, 'zhTW', '力量…完全恢復了！現在輪到我報仇了！', '', 28153),
(133474, 'zhTW', '沙德拉以及她的手下這次太過分了！', '', 28153),
(133473, 'zhTW', '非常好！我漸漸恢復力量了！快去啟動最後一根圖騰。', '', 28153),
(133472, 'zhTW', '你去找修克，我留在這裡接應。', '', 28153),
(133471, 'zhTW', '…他就在我們後面的神廟，這樣就好辦了。', '', 28153),
(133470, 'zhTW', '哈！他是…', '', 28153),
(133469, 'zhTW', '祖爾會為此付出代價！', '', 28153),
(133468, 'zhTW', '啊，我的力量恢復了！快，釋放其他圖騰的魔力。', '', 28153),
(133467, 'zhTW', '希望羅亞保佑你，朋友！', '', 28153),
(133466, 'zhTW', '看來修克不在納茲米爾…', '', 28153),
(133465, 'zhTW', '我準備好了，請你施法好讓我們找到修克。', '我準備好了，請你施法好讓我們找到修克。', 28153),
(133463, 'zhTW', '', '我知道你的感受。再等一下就可以飛了．', 28153),
(133461, 'zhTW', '(返回)', '(返回)', 28153),
(133460, 'zhTW', '我身上還有一些吃的，不過我從來都沒試過迅猛龍肉，要不要趁這個機會來試試看？', '', 28153),
(133459, 'zhTW', '我們破壞了其中一些圖騰，你的法術派得上用場嗎？', '我們破壞了其中一些圖騰，你的法術派得上用場嗎？', 28153),
(133455, 'zhTW', '', '噢，我的小寶貝。你整天窩在這裡，一定覺得很煩吧。', 28153),
(133450, 'zhTW', '你現在就會死。', '你現在就會死。', 28153),
(133449, 'zhTW', '祖爾已經承諾，要將力量賜給取下你腦袋的人。', '祖爾已經承諾，要將力量賜給取下你腦袋的人。', 28153),
(133448, 'zhTW', '我會把你的頭獻給祖爾。', '我會把你的頭獻給祖爾。', 28153),
(133447, 'zhTW', '我要把你的心靈給剖開。', '我要把你的心靈給剖開。', 28153),
(133446, 'zhTW', '我們會讓你流血。', '我們會讓你流血。', 28153),
(133445, 'zhTW', '國王在哪裡？', '國王在哪裡？', 28153),
(133444, 'zhTW', '我們會把你的頭插在長矛上。', '我們會把你的頭插在長矛上。', 28153),
(133443, 'zhTW', '為祖爾奮戰至死！', '為祖爾奮戰至死！', 28153),
(133438, 'zhTW', '<祭壇頂端的表面呈凹面狀，每個角落旁都有明顯的凹槽。$b$b看來某種又大又重的物品曾經被放在祭壇上。$b$b無論那是什麼，它已經不見了。>', '', 28153),
(133432, 'zhTW', '檢視祭壇。', '檢視祭壇。', 28153),
(133430, 'zhTW', '<房間似乎是空的。$b$b你眼前的祭壇上面有贊達拉的雕紋以及羅亞伊拉卡‧諾‧金布爾的圖案。$b$b看來某個東西曾被放在祭壇上方，或許是個雕像？>', '', 28153),
(133428, 'zhTW', '', '會計室無論早晚都警備森嚴。你可以把貴重物品放在這裡。', 28153),
(133412, 'zhTW', '贊庫爾人無所不知！', '贊庫爾人無所不知！', 28153),
(133411, 'zhTW', '你逃不出我的手掌心！', '你逃不出我的手掌心！', 28153),
(133410, 'zhTW', '祖爾會知道你的秘密！', '祖爾會知道你的秘密！', 28153),
(133409, 'zhTW', '你會失去性命！', '你會失去性命！', 28153),
(133407, 'zhTW', '你別想阻止我，入侵者！', '你別想阻止我，入侵者！', 28153),
(133406, 'zhTW', '贊達拉現在屬於贊庫爾！', '贊達拉現在屬於贊庫爾！', 28153),
(133405, 'zhTW', '為了祖爾！為了贊庫爾！', '為了祖爾！為了贊庫爾！', 28153),
(133404, 'zhTW', '贊庫爾人要什麼拿什麼！', '贊庫爾人要什麼拿什麼！', 28153),
(133403, 'zhTW', '我會奪走你的力量！', '我會奪走你的力量！', 28153),
(133402, 'zhTW', '你的死會讓我更強大！', '你的死會讓我更強大！', 28153),
(133401, 'zhTW', '更多血來獻給祖爾！', '更多血來獻給祖爾！', 28153),
(133392, 'zhTW', '', '這艘船可以停靠提拉加德內灘的所有渡船站。', 28153),
(133389, 'zhTW', '', '你需要港口統領頒發的渡船通行證。這沒問題。', 28153),
(133387, 'zhTW', '', '別擔心越獄的事了…在市場你就只是個旅人。我來幫你適應環境吧！', 28153),
(133380, 'zhTW', '', '我先姑且救你這次，之後還有得算呢！', 28153),
(133379, 'zhTW', '', '你可以讓我吃很長一段時間！', 28153),
(133374, 'zhTW', '', '我要啃你的骨頭！', 28153),
(133372, 'zhTW', '', '把尖刺帶著，食物來啦！', 28153),
(133371, 'zhTW', '', '食物自己找上門來了！', 28153),
(133370, 'zhTW', '', '你的腿一定很好吃！', 28153),
(133369, 'zhTW', '', '我們現在要吃點食物！', 28153),
(133368, 'zhTW', '', '你看起來真美味！', 28153),
(133359, 'zhTW', '這也不是修克第一次迷路了。我倒希望他真的遇上什麼大麻煩。', '', 28153),
(133357, 'zhTW', '回去工作！晶岩可不會自己跑出來堆好。', '回去工作！艾澤萊晶岩不會自己跑出來堆好。', 28153),
(133356, 'zhTW', '我準備好陪你前往神廟。', '我準備好陪你前往神廟。', 28153),
(133355, 'zhTW', '早知道我不該信任這些在背後害人的托塔卡！我真不敢相信他們殺了我，還把我困在這罐子裡一百年…還是兩百年？我甚至記不得了！', '', 28153),
(133354, 'zhTW', '<可怕又震撼的吼聲傳遍整個札巴哈里。>', '<可怕又震撼的吼聲傳遍整個札巴哈里。>', 28153),
(133351, 'zhTW', '我要去找羅亞。你這邊事了後，就到神廟裡面跟我會合。', '', 28153),
(133350, 'zhTW', '終於自由了…感謝你讓我從那個被詛咒的甕中解脫！就算對一隻鬼來說，那裡面還是太小太擠！', '', 28153),
(133349, 'zhTW', '', '這幾道牆撐不了多久的，這裡不能久留。', 28153),
(133348, 'zhTW', '', '做得太好了，夥伴！準備好時來找我，我們有一場仗要回去打。', 28153),
(133346, 'zhTW', '', '血神…帶我走！別以為…這樣就結束了…', 28153),
(133345, 'zhTW', '', '血神遲早會達到他的目的，你阻止不了我們的！', 28153),
(133344, 'zhTW', '', '公主一定會想馬上接到報告。最好別讓她等。', 28153),
(133343, 'zhTW', '撐下去。', '', 28153),
(133342, 'zhTW', '你不能死。我們還要奮戰。', '', 28153),
(133341, 'zhTW', '起來。你還有事要做。', '', 28153),
(133340, 'zhTW', '起來吧！我們需要你。', '', 28153),
(133339, 'zhTW', '起來吧！', '', 28153),
(133338, 'zhTW', '起來吧！國王需要你。', '', 28153),
(133337, 'zhTW', '我準備好要和鮮血食人妖作戰了。', '我準備好要和鮮血食人妖作戰了。', 28153),
(133336, 'zhTW', '鮮血食人妖正在集結他們的勢力，準備再次攻擊我和我的孩子們。$b$b這一次，殺人的該換我了！$b$b你準備好了嗎？', '', 28153),
(133325, 'zhTW', '部落攻擊者正前往兵營！', '部落攻擊者正前往兵營！', 28153),
(133305, 'zhTW', '', '你很快就會開始習慣了。我們先去找塞勒斯吧！', 28153),
(133304, 'zhTW', '', '很漂亮吧？塞勒斯把她給我的時候，她還只是個小寶寶。', 28153),
(133303, 'zhTW', '我會和你一起對抗鮮血食人妖，不過，我必須先恢復力量才行。你願意幫助我嗎？', '', 28153),
(133302, 'zhTW', '贊提莫對我十分虔誠，願他的靈魂與我的後代共存。', '', 28153),
(133300, 'zhTW', '蘭達爾對著沙地吐了一口痰。', '', 28153),
(133298, 'zhTW', '救命！把東西弄走啊！', '', 28153),
(133297, 'zhTW', '', '他的傷勢太嚴重了…我很抱歉。', 28153),
(133295, 'zhTW', '烏南丘？*咆哮* 我早該知道了…', '', 28153),
(133294, 'zhTW', '誰竟敢將我召來這座破舊的神廟？', '', 28153),
(133274, 'zhTW', '我先去準備儀式，你好了就去那邊找我。', '', 28153),
(133265, 'zhTW', '張大你的眼睛目睹伊拉卡‧諾‧金布爾的光輝，他亦是虎之羅亞、獸王、大貓之王及獵物主宰！', '', 28153),
(133264, 'zhTW', '你找到塑像了！既然它已經就位，我們可以召喚羅亞了…', '', 28153),
(133263, 'zhTW', '', '我會將這傢伙帶回去見他的羅亞，然後殺掉每一個膽敢擋你面前的傢伙。', 28153),
(133261, 'zhTW', '兵營被摧毀了！趕快重建！', '兵營被摧毀了！趕快重建！', 28153),
(133260, 'zhTW', '鐵匠舖被摧毀了！趕快重建！', '鐵匠舖被摧毀了！趕快重建！', 28153),
(133259, 'zhTW', '獸欄被摧毀了！趕快重建！', '獸欄被摧毀了！趕快重建！', 28153),
(133258, 'zhTW', '工坊被摧毀了！趕快重建！', '工坊被摧毀了！趕快重建！', 28153),
(133254, 'zhTW', '我連把武器都沒有！', '', 28153),
(133253, 'zhTW', '我不想死！', '', 28153),
(133252, 'zhTW', '我不能在這種條件下工作！', '', 28153),
(133251, 'zhTW', '開始動了！準備！', '', 28153),
(133250, 'zhTW', '我們會試一個反化石作用的法術，後退點！', '', 28153),
(133249, 'zhTW', '我準備好了。', '我準備好了。', 28153),
(133248, 'zhTW', '如果這個法術有用，可別以為席帕拉是個和顏悅色的傢伙。\n\n希望你已經做好應付他的準備。', '', 28153),
(133247, 'zhTW', '', '快過來！這裡有人受傷了！', 28153),
(133240, 'zhTW', '', '在這惡劣之地，我只能盡量提供遮蔽之地。', 28153),
(133239, 'zhTW', '在贊達拉人決定在我周圍蓋房子前，這地方曾是我的。', '', 28153),
(133224, 'zhTW', '必須將塑像送回金布爾的神廟，你手中握有讓羅亞重返人世的鑰匙！', '', 28153),
(133223, 'zhTW', '我的靈魂非常虛弱，時間所剩無幾，旅人。仔細聽好我說的話…', '', 28153),
(133214, 'zhTW', '我們離開這裡吧。前面有座神廟叫做佐巴爾，到那裡會合。', '', 28153),
(133213, 'zhTW', '打倒部落指揮官了，你贏了！', '打倒部落指揮官了，你贏了！', 28153),
(133212, 'zhTW', '讓人血脈賁張！那些獸人雜碎似乎留下幾顆威力不錯的炸彈，我知道把炸彈丟在他們那些醜陋的建築附近，會發生什麼事？', '', 28153),
(133207, 'zhTW', '這地區因為過去的靈魂已經荒廢許久，而這不是沒有原因的。\n\n非常歡迎部落的人來盡力調查此地，如果他們敢的話…', '', 28153),
(133204, 'zhTW', '就算已經死亡，我們人民的靈魂依然效忠偉大的羅亞伊拉卡‧諾‧金布爾。我們信念的牽絆是不滅的，比死亡本身更強壯。', '', 28153),
(133201, 'zhTW', '我們需要那個礦坑，但那些該死的獸人擋住我們的路。讓我們下去那裡殺死他們，方便我們指揮這些工人，幫我們建造兵營。', '', 28153),
(133200, 'zhTW', '那是那個醜東西的末日。現在除掉那張旌旗，我們開工吧。', '', 28153),
(133199, 'zhTW', '好吧，大夥，如果我們想要解決那個獸人指揮官，徹底摧毀他的基地，我們就必須在這之後拿下一個基地。', '', 28153),
(133198, 'zhTW', '', '根本…沒用的！你們…還是…都得死…', 28153),
(133197, 'zhTW', '你是多年來第一個踏入我神廟的凡人。能在生靈之中再度擁有追隨者的感覺真好。', '', 28153),
(133158, 'zhTW', '', '我們成功了。想想看當那大傀儡粉碎祖達薩的牆壁，讓他們全都進城時會發生什麼事。會有更多羅亞站在我們這邊，這幫助很大的。', 28153),
(133157, 'zhTW', '', '看看他們！這些人都要去祖達薩…小心！把你的頭放低！', 28153),
(133156, 'zhTW', '', '那個島就在南邊，我會在那裡等你。', 28153),
(133155, 'zhTW', '', '在這裡。船已經準備好了，就等你上船。希望沒有河怪，對吧？', 28153),
(133154, 'zhTW', '開始了！', '', 28153),
(133153, 'zhTW', '只要別讓它爆炸就行！', '', 28153),
(133152, 'zhTW', '持續攻擊！', '', 28153),
(133151, 'zhTW', '我能幫你什麼忙嗎，$g小夥子:小姑娘;？', '', 28153),
(133150, 'zhTW', '告訴你吧，你在那裡面找到什麼都是你的。算是我的感謝之意！', '', 28153),
(133149, 'zhTW', '啊啊啊…啊啊啊…', '', 28153),
(133143, 'zhTW', '你的存在是對此地的汙染！當心席帕拉！', '', 28153),
(133141, 'zhTW', '現在可以在工坊招募矮人擲彈手。', '現在可以在工坊招募矮人擲彈手。', 28153),
(133140, 'zhTW', '鐵匠鋪現在可以招募步槍兵。', '鐵匠鋪現在可以招募步槍兵。', 28153),
(133139, 'zhTW', '獸欄現在可以招募騎士。', '獸欄現在可以招募騎士。', 28153),
(133138, 'zhTW', '兵營現在可以招募步卒。', '兵營現在可以招募步卒。', 28153),
(133136, 'zhTW', '', '你非常靠近了。我很快就感應到其中一位羅亞就在水邊。', 28153),
(133133, 'zhTW', '', '嗯…這份供品是不久之前放的。看來在這片沼澤還是有人信奉伯昂撒姆第。', 28153),
(133131, 'zhTW', '太多鮮血食人妖，我不打了。', '', 28153),
(133126, 'zhTW', '部落失去一棟建築物。現在可開始建造鐵匠鋪。', '部落失去一棟建築物。現在可開始建造鐵匠鋪。', 28153),
(133125, 'zhTW', '部落失去一棟建築物。現在可開始建造工坊。', '部落失去一棟建築物。現在可開始建造工坊。', 28153),
(133124, 'zhTW', '部落失去一棟建築物。現在可開始建造獸欄。', '部落失去一棟建築物。現在可開始建造獸欄。', 28153),
(133123, 'zhTW', '', '你看，跟著那個幻影，查明信奉伯昂撒姆第的崇拜者怎麼了。', 28153),
(133122, 'zhTW', '', '是鮮血食人妖。看來她被當成祭品了。嗯，兇手留下一把匕首！看來只需要一點小法術…', 28153),
(133114, 'zhTW', '帶我離開這裡！', '', 28153),
(133113, 'zhTW', '炸彈被放下了！', '炸彈被放下了！', 28153),
(133112, 'zhTW', '炸彈被拾取了！', '炸彈被拾取了！', 28153),
(133111, 'zhTW', '炸彈要爆了！快閃開！', '炸彈要爆了！快閃開！', 28153),
(133108, 'zhTW', '步卒 [25戰爭前線黃金] |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t', '步卒 [25戰爭前線黃金] |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t', 28153),
(133104, 'zhTW', '我們開始吧。', '我們開始吧。', 28153),
(133103, 'zhTW', 'REUSEME', 'REUSEME', 28153),
(133102, 'zhTW', '我們在這的工作進行得非常緩慢，都是因為聯盟的干擾！', '我們在這的工作進行得非常緩慢，都是因為聯盟的干擾！', 28153),
(133101, 'zhTW', '如果我不用一直小心留意聯盟的破壞者，我工作的進度會快很多…', '如果我不用一直小心留意聯盟的破壞者，我工作的進度會快很多…', 28153),
(133100, 'zhTW', '聯盟在這塊土地上無權插手—祖達薩是部落的領土！', '聯盟在這塊土地上無權插手—祖達薩是部落的領土！', 28153),
(133099, 'zhTW', '除非我們把那些該死的矮人從我們的地盤趕出去，不然我們是沒辦法有真正的進展的！', '', 28153),
(133085, 'zhTW', '', '聯盟…會戰勝…', 28153),
(133084, 'zhTW', '', '這是一個官方的探險者協會挖掘點，你這是非法入侵！', 28153),
(133069, 'zhTW', '為了聯盟！', '為了聯盟！', 28153),
(133066, 'zhTW', '走開，入侵者！', '走開，入侵者！', 28153),
(133065, 'zhTW', '這些神器會是我們的！', '這些神器會是我們的！', 28153),
(133064, 'zhTW', '聖匣守護者去死！', '聖匣守護者去死！', 28153),
(133055, 'zhTW', '', '你好！你試過把雙眼蒙起來，把火箭綁在背上然後發射嗎？我試過！', 28153),
(133054, 'zhTW', '聯盟必須被消滅，祖達薩屬於部落！', '', 28153),
(133053, 'zhTW', '那太驚人了，真厲害的發現！', '', 28153),
(133048, 'zhTW', '', '我花了很多時間在這裡纏著旅行者把他們的故事說給我聽。特別是從東部王國過來的人！', 28153),
(133047, 'zhTW', '', '波拉勒斯港…我們到了。除了普勞德摩爾城堡，這是全城警備最森嚴的地方。同時也是外來者唯一能拜訪的地方。', 28153),
(133045, 'zhTW', '', '他肯付你錢就該偷笑了。快點專心划！', 28153),
(133044, 'zhTW', '聯盟特使？！塞勒斯可沒提到這件事…我應該跟他多收一倍的！', '', 28153),
(133043, 'zhTW', '', '你跟珍娜‧普勞德摩爾一起來的！你是聯盟特使！', 28153),
(133042, 'zhTW', '', '等等…我認得你…', 28153),
(133041, 'zhTW', '喔！我救出目標了。我來介紹你們認識。壞朋友，泰莉亞。泰莉亞，壞朋友。', '', 28153),
(133040, 'zhTW', '', '那裡發生什麼事了？看來是你引發了混亂！', 28153),
(133039, 'zhTW', '不知道你在胡說些什麼…對了，我們好像拿到「真正的」艾胥凡相關情報了。', '', 28153),
(133038, 'zhTW', '她在那裡！我們快過去。', '', 28153),
(133037, 'zhTW', '我們到下層去看看能不能找到出口。', '', 28153),
(133036, 'zhTW', '啊，太好了。還真是不能沒有這些東西！走吧。', '', 28153),
(133013, 'zhTW', '', '不管你是想打條新地毯或新大衣，我們都有足夠的皮草！', 28153),
(133012, 'zhTW', '', '溫暖的皮草，實用的皮草，以及舒適宜人的皮草！', 28153),
(133011, 'zhTW', '', '從庫爾提拉斯來的高級皮草！', 28153),
(133009, 'zhTW', '', '提拉加德最可靠的發明，是真的！', 28153),
(133008, 'zhTW', '', '不要相信從任何其他地方來的地精發明！我的同行都是騙子！', 28153),
(133007, 'zhTW', '', '你在別地方找不到更多精工製作的小玩意兒跟飾品了！', 28153),
(133001, 'zhTW', '哇！他…他在長大嗎？？噫！', '哇！他…他在長大嗎？？噫！', 28153),
(132999, 'zhTW', '復活中', '復活中', 28153),
(132994, 'zhTW', '法師們，讓我們回營地去。我們有很多研究要做！', '', 28153),
(132993, 'zhTW', '可惡！鑰匙壞了。剛剛的爆炸真猛！', '', 28153),
(132992, 'zhTW', '東西拿好，我們要去找這一區的獄卒了。我們需要他的鑰匙。', '', 28153),
(132991, 'zhTW', '看來從這邊出不去。到另一邊看看。', '', 28153),
(132990, 'zhTW', '兵營開放', '兵營開放', 28153),
(132989, 'zhTW', '快，加油！給他們好看！', '', 28153),
(132988, 'zhTW', '[牢門啪地被打開。囚犯一湧而出，跑過長廊。]', '[牢門啪地被打開。囚犯一湧而出，跑過長廊。]', 28153),
(132987, 'zhTW', '部落攻擊者正前往工坊！', '部落攻擊者正前往工坊！', 28153),
(132986, 'zhTW', '正在訓練步卒', '正在訓練步卒', 28153),
(132985, 'zhTW', '兵營已佔領，正在重建。', '兵營已佔領，正在重建。', 28153),
(132981, 'zhTW', '部落攻擊者正前往獸欄！', '部落攻擊者正前往獸欄！', 28153),
(132980, 'zhTW', '部落攻擊者正前往鐵匠舖！', '部落攻擊者正前往鐵匠舖！', 28153),
(132969, 'zhTW', '', '媽媽，我所有的朋友都在玩，只差我一個！我可以去嗎，拜託～？', 28153),
(132968, 'zhTW', '', '我好無聊！我可以去玩嗎？', 28153),
(132967, 'zhTW', '', '我們完成這差事了嗎？', 28153),
(132966, 'zhTW', '', '', 28153),
(132957, 'zhTW', '', '這老東西？$B$B<發出一聲輕笑。>$B$B看看周圍吧，你覺得我從哪得到它的？', 28153),
(132955, 'zhTW', '一面相當有趣的盾牌，你在哪裡得到的？', '一面相當有趣的盾牌，你在哪裡得到的？', 28153),
(132954, 'zhTW', '', '我或許個子小，但我揮起錘子可比你遇到的大部分部落穢物都還要大力。', 28153),
(132945, 'zhTW', '你在外頭這裡做什麼?', '你在外頭這裡做什麼?', 28153),
(132944, 'zhTW', '我一定要好好教訓他們。別阻止我！', '', 28153),
(132943, 'zhTW', '大傢伙來了！喂，船就是被他弄沉的！給他一點教訓！', '', 28153),
(132941, 'zhTW', '聽好$g小夥子:小姑娘;…我，呃…忘了我要說什麼，但在這裡最好別多管閒事。$B$B我可不想讓你的血沾到我的裝備。', '', 28153),
(132940, 'zhTW', '身高高代表要讓我情緒高漲需要比較長的時間。$B$B要有耐心。', '', 28153),
(132939, 'zhTW', '既然我們必須調整一下大砲的精準度，才能進行下一步，那乾脆順便轟掉幾隻納迦，你說怎麼樣？', '', 28153),
(132938, 'zhTW', '哇，小心！他們朝我們發射砲彈！用集束砲火解決他們！', '', 28153),
(132935, 'zhTW', '在下面！小心！', '', 28153),
(132932, 'zhTW', '', '沒錯…大家聽好，改向西邊前進，避開不必要的衝突。', 28153),
(132931, 'zhTW', '看來他們的人口比想像中多。', '', 28153),
(132928, 'zhTW', '你是來避難的，還是來交易的？', '你是來避難的，還是來交易的？', 28153),
(132926, 'zhTW', '我們都準備好了。趕快上來。', '', 28153),
(132924, 'zhTW', '快！去拉把手！', '', 28153),
(132923, 'zhTW', '該出發了。接應的人應該在海灘上等了。', '', 28153),
(132922, 'zhTW', '', '給我走開！金幣都是我的！', 28153),
(132920, 'zhTW', '最先抵達部署地點的就賞五萬枚金幣！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(132918, 'zhTW', '我剛下了幾個地雷，當作防禦設施。', '', 28153),
(132917, 'zhTW', '好…我真的該走了。', '', 28153),
(132916, 'zhTW', '噁…聞起來有一股海盜味。', '', 28153),
(132915, 'zhTW', '大家注意，該走了！', '', 28153),
(132912, 'zhTW', '要有風險才夠刺激啊！拜託，你應該多去賭博才對。', '', 28153),
(132911, 'zhTW', '', '拜託，八二分帳很划算了。討價還價小心談判破裂！', 28153),
(132910, 'zhTW', '只拿八成？怎麼不再多拿一點？太大方了吧？', '', 28153),
(132909, 'zhTW', '歡迎回到金牙旅店，姊妹，這裡永遠是你的家。\n\n放鬆、好好休息，然後來喝酒吧！', '', 28153),
(132908, 'zhTW', '歡迎回到金牙旅店，兄弟，這裡永遠是你的家。\n\n放鬆、好好休息，然後來喝酒吧！', '', 28153),
(132907, 'zhTW', '你在幹什麼？那是我的東西！', '你在幹什麼？那是我的東西！', 28153),
(132906, 'zhTW', '救命！有人在搞破壞！', '救命！有人在搞破壞！', 28153),
(132905, 'zhTW', '那是精密儀器！', '那是精密儀器！', 28153),
(132904, 'zhTW', '嘿！離我的東西遠點！', '嘿！離我的東西遠點！', 28153),
(132897, 'zhTW', '讓我離開這個牢籠！我是無辜的，我發誓！', '讓我離開這個牢籠！我是無辜的，我發誓！', 28153),
(132893, 'zhTW', '我同意，葛倫妮雅。如果蘇爾森沒回來，$p會是很好的替補。', '', 28153),
(132891, 'zhTW', '到底是誰出的餿主意，要我們開往這該死的石窟的？', '到底是誰出的餿主意，要我們開往這該死的石窟的？', 28153),
(132890, 'zhTW', '歌聲終於停止了！', '歌聲終於停止了！', 28153),
(132889, 'zhTW', '是…酒嗎？', '那是…麥酒嗎？', 28153),
(132880, 'zhTW', '嘿，那部分永遠不會變老。', '', 28153),
(132879, 'zhTW', '我已經把血液和你收集的螫刺放在一起煮，然後倒入儀式用的金牙高腳杯裡…這是鳳梨，別吃下去，我們只有一顆。', '', 28153),
(132877, 'zhTW', '我得救了，謝謝你！', '', 28153),
(132876, 'zhTW', '謝謝！我們會合點見！', '', 28153),
(132849, 'zhTW', '我現在知道自己差點就要中了陷阱…謝謝你！', '我現在知道自己差點就要中了陷阱…謝謝你！', 28153),
(132848, 'zhTW', '我不知道自己怎麼了…', '我不知道自己怎麼了…', 28153),
(132847, 'zhTW', '去救其他人…我會立刻去找金布爾。', '去救其他人…我會立刻去找金布爾。', 28153),
(132846, 'zhTW', '我差點就萬劫不復…我非常感謝你，陌生人！', '我差點就萬劫不復…我非常感謝你，陌生人！', 28153),
(132845, 'zhTW', '這場騙局讓我差點失去靈魂…', '這場騙局讓我差點失去靈魂…', 28153),
(132844, 'zhTW', '我現在知道那不過是幻影，我會去找金布爾…', '我現在知道那不過是幻影，我會去找金布爾…', 28153),
(132843, 'zhTW', '我被吞噬之光誘惑，謝謝你救了我…', '我被吞噬之光誘惑，謝謝你救了我…', 28153),
(132841, 'zhTW', '', '沒有水也沒有食物，我撐不了多久。在繞了一天的路以後，我現在唯一的選擇是姑且相信那個瘋子的話，往南邊找找看有沒有庇護所。', 28153),
(132840, 'zhTW', '', '賈克拉傑的刺客，在半夜偷襲營地。大家手上沒有武器，也都還睡得迷迷糊糊，因此完全沒有自衛能力。我挺身戰鬥，不過為時已晚，倖存者慌忙逃命，只能獨自在這片恐怖的大地求生。', 28153),
(132839, 'zhTW', '', '太陽終於下山了，讓人昏頭轉向的炎熱也稍微緩解。我們被烈日曬到恍惚的時候，有個人發了瘋似地說南邊有座神廟，願意收留被流放的人們。我看那傢伙撐不過今天晚上了。', 28153),
(132838, 'zhTW', '', '我在寫下這段話的時候，和一群被流放的人關在同一個籠子裡，被運往我們要度過餘生的沙漠，不過這段「餘生」的日子恐怕屈指可數。臉上感受到的灼熱空氣，告訴我就快到了。', 28153),
(132830, 'zhTW', '', '你太遲了…羅亞…都會成為食物…獻給鮮血之神。', 28153),
(132827, 'zhTW', '那些納迦一定會付出代價！', '', 28153),
(132826, 'zhTW', '非常感謝你！', '', 28153),
(132825, 'zhTW', '我欠你一次！', '', 28153),
(132824, 'zhTW', '自由！', '', 28153),
(132823, 'zhTW', '我欠你一命，這些半蛇半人的傢伙會為了破壞我們的家園付出代價…', '我欠你一條命。我一定要讓那些蛇人血債血償…', 28153),
(132821, 'zhTW', '<拿取信件。>', '<拿取信件。>', 28153),
(132752, 'zhTW', '妮莎，感謝沙塵，你平安無事！', '', 28153),
(132737, 'zhTW', '', 'He truly is the kindest man I\'ve ever known.', 28153),
(132736, 'zhTW', '%s motions in your direction as if to stop you, then retracts, settling down to gaze into the distance once more.', '', 28153),
(132735, 'zhTW', '嘿，第一次喝儀式蠍血一定很難下嚥，吐出來吧，下次就會順口多了。', '', 28153),
(132734, 'zhTW', '祖達薩背叛了我們，把我們像外來者一樣流放。但我們永遠不會背叛彼此，金牙始終如一。', '', 28153),
(132733, 'zhTW', '啊，這血嚐起來很鮮甜…喝下去，體驗我的視界，$p。', '', 28153),
(132714, 'zhTW', '適合每一位獵人的各種專業火槍，應有盡有！', '', 28153),
(132713, 'zhTW', '出去打獵嗎？要取得補給品，沒有比這裡更好的地方了！', '', 28153),
(132712, 'zhTW', '槍枝、彈藥和炸彈，給各種資歷的獵人！', '', 28153),
(132711, 'zhTW', '恐角龍幼獸疲倦地打了哈欠。', '', 28153),
(132710, 'zhTW', '喔，那東西？那只是我用來餵食保鏢的小東西，要是你願意出價的話，我還有很多！', '', 28153),
(132696, 'zhTW', '現在出來安全嗎？', '', 28153),
(132692, 'zhTW', '哈！沒錯，我知道$p看不見你，大概會以為我瘋了，哈！', '', 28153),
(132691, 'zhTW', '別傷心，$p根本看不見你，大概會以為我瘋了，哈！', '', 28153),
(132690, 'zhTW', '$p救了你，蘇爾森！我超級開心！', '', 28153),
(132688, 'zhTW', '嘿，$n！貿易親王說我們得開始賺錢才行。如果你聽到什麼好生意可做，就讓我知道，好嗎？', '', 28153),
(132684, 'zhTW', '', '新娘來了，新娘來了！', 28153),
(132683, 'zhTW', '走這邊！', '走這邊！', 28153),
(132682, 'zhTW', '衝刺！你可以的！', '衝刺！你可以的！', 28153),
(132681, 'zhTW', '<小聲說你覺得他的眼罩非常可笑。>', '<小聲說你覺得他的眼罩非常可笑。>', 28153),
(132680, 'zhTW', '我可以拿你的東西嗎？', '我可以拿你的東西嗎？', 28153),
(132679, 'zhTW', '你的眼罩非常可怕。', '你的眼罩非常可怕。', 28153),
(132678, 'zhTW', '<曼佐的眼罩隨著魔法抖動。>', '', 28153),
(132677, 'zhTW', '<嘗試在互瞪比賽中勝過葛倫妮雅。>', '<嘗試在互瞪比賽中勝過葛倫妮雅。>', 28153),
(132676, 'zhTW', '我賭你一定能成為一個很好的門檔。', '我賭你一定能成為一個很好的門檔。', 28153),
(132675, 'zhTW', '你好！', '你好！', 28153),
(132674, 'zhTW', '<以顱骨來說，葛倫妮雅看起來還是出奇地開心。>', '', 28153),
(132673, 'zhTW', '大家安靜！我們有客人來了。', '', 28153),
(132672, 'zhTW', '<有禮貌地自我介紹。>', '<有禮貌地自我介紹。>', 28153),
(132671, 'zhTW', '<小聲說著整件事的瘋狂可笑。>', '<小聲說著整件事的瘋狂可笑。>', 28153),
(132670, 'zhTW', '我喜歡你的帽子。', '我喜歡你的帽子。', 28153),
(132669, 'zhTW', '呃…你好？', '呃…你好？', 28153),
(132668, 'zhTW', '哇！那是什麼？感覺很厲害。', '', 28153),
(132667, 'zhTW', '', '<沃尼好像陷入永無止盡的尖叫狀態。>', 28153),
(132663, 'zhTW', '', '你會喜歡我們的香料為各種料理所點綴的色彩與風味！', 28153),
(132662, 'zhTW', '', '來自艾澤拉斯各地的上等香料！', 28153),
(132661, 'zhTW', '', '別再吃乏然無味的餐點了！參觀看看我們的香料！', 28153),
(132657, 'zhTW', '啊啊！用玩具讓牠分心看看！', '啊啊！用玩具讓牠分心看看！', 28153),
(132656, 'zhTW', '這「鱒」的是市場上最好的魚！', '這「鱒」的是市場上最好的魚！', 28153),
(132655, 'zhTW', '果然還是用現抓的魚做湯最好！', '果然還是用現抓的魚做湯最好！', 28153),
(132654, 'zhTW', '魚！新鮮的魚！剛剛才從巨牙海民的船卸下來的！', '魚！新鮮的魚！剛剛才從巨牙海民的船卸下來的！', 28153),
(132653, 'zhTW', '長官！西南邊的部落營地似乎正在集結部隊，他們似乎準備出動了，長官。', '', 28153),
(132651, 'zhTW', '別跟丟他們！一有風吹草動，你知道該怎麼做。', '', 28153),
(132650, 'zhTW', '費林伍德！有新消息嗎？', '', 28153),
(132648, 'zhTW', '拯救', '拯救', 28153),
(132646, 'zhTW', '放箭！', '放箭！', 28153),
(132645, 'zhTW', '你一定是那些我聽了不少英勇事蹟的部落勇士之一。而且你還帶了恐角龍寶寶？獸王一定會想看看的。請通行。', '你一定是那些我聽了不少英勇事蹟的部落勇士之一。而且你還帶了恐角龍寶寶？獸王一定會想看看的。請通行。', 28153),
(132636, 'zhTW', '', '真有意思…', 28153),
(132635, 'zhTW', '', '來瞧瞧這裡有什麼收獲。', 28153),
(132634, 'zhTW', '', '你要小心點。', 28153),
(132629, 'zhTW', '使用疾跑跑快一點！', '使用疾跑跑快一點！', 28153),
(132628, 'zhTW', '', '我們要殺掉獵人，把圖騰都搶回來。', 28153),
(132626, 'zhTW', '', '當贊達拉人看到你在對抗他們時，你會再次擁有追隨者。', 28153),
(132624, 'zhTW', '', '你是強大的羅亞！有你幫助我們，敵人絕對沒有勝算！', 28153),
(132622, 'zhTW', '', '偉大的奎格瓦！我們需要你幫忙對抗鮮血食人妖！', 28153),
(132620, 'zhTW', '逮到你了！就是你！', '', 28153),
(132619, 'zhTW', '別跑！就是你！', '', 28153),
(132613, 'zhTW', '我賜你我力量的一小部分，善用這股力量讓贊提莫安息。', '', 28153),
(132611, 'zhTW', 'Debug Testing', 'Debug Testing', 28153),
(132609, 'zhTW', '攻勢發生的太突然…我們沒辦法阻止他們。', '攻勢發生的太突然…我們沒辦法阻止他們。', 28153),
(132608, 'zhTW', '巨獸…把我們打得落花流水…', '巨獸…把我們打得落花流水…', 28153),
(132607, 'zhTW', '武器…破壞…', '武器…破壞…', 28153),
(132606, 'zhTW', '納…納迦…到處都是！', '納…納迦…到處都是！', 28153),
(132605, 'zhTW', '謝…謝謝你！', '謝…謝謝你！', 28153),
(132604, 'zhTW', '也來到這步田地啦。', '也來到這步田地啦。', 28153),
(132603, 'zhTW', '懦夫！', '懦夫！', 28153),
(132602, 'zhTW', '你別想活捉我！', '你別想活捉我！', 28153),
(132601, 'zhTW', '不配榮耀的殘渣！', '不配榮耀的殘渣！', 28153),
(132600, 'zhTW', '可悲的殘渣！', '可悲的殘渣！', 28153),
(132599, 'zhTW', '到這來參加大獵捕，你也挺勇敢的。我想今天應該會很有趣，你想呢？', '', 28153),
(132581, 'zhTW', '別管這些小蟲。先殺帶頭的！', '', 28153),
(132580, 'zhTW', '我已經受夠這些攻擊了！殺光他們！我可是奎格瓦，誰敢動我！', '', 28153),
(132579, 'zhTW', '做得很好，$n。你確實證明了你的實力和勇氣，回到神廟去，接受你的獎勵。', '', 28153),
(132573, 'zhTW', '上次拉尼舒過境的時候時，啃光了四支車隊。多虧有你，憾事才不會重演。', '', 28153),
(132572, 'zhTW', '有群雷龍迷路闖進沃魯敦，變成拉尼舒的大餐了！快去減少拉尼舒的數量，免得牠們演變成不可收拾的大麻煩。', '', 28153),
(132571, 'zhTW', '帶著祭品安全歸來，證明你自己，那麼羅亞就會願意見你一面。', '', 28153),
(132566, 'zhTW', '你為這座神廟效力，證明了自己的價值，$n。作為回報，你願意接受的話，我會賦予你祝福。', '', 28153),
(132565, 'zhTW', '你必須趕緊找出獠牙呼喚者的巢穴，找到之後立刻殺掉對方。神廟的安危全繫於此。', '', 28153),
(132564, 'zhTW', '如果不將塞斯拉克從峽谷趕出來，這座神廟就會陷入危機。', '', 28153),
(132563, 'zhTW', '我收下這禮物，陌生人。過來一點，我這雙老眼已經看不清楚了。', '', 28153),
(132562, 'zhTW', '看來我們有訪客了，賈爾南吉。請看照我們新來到的客人。', '', 28153),
(132560, 'zhTW', '歡迎參加真正的狩獵。', '', 28153),
(132550, 'zhTW', '那隻龐大的雷霆蜥蜴允許我們在神廟避難，只要羅亞允許，這裡隨時歡迎你來。', '', 28153),
(132549, 'zhTW', '慘了！機甲被他拿走了啦！不搶回來的話，我們工作一輩子也賠不起！', '', 28153),
(132547, 'zhTW', '你拿到東西了嗎？', '', 28153),
(132545, 'zhTW', '<你看見數百個引信，引信連接的是裝有發光粉末的瓶子。>', '', 28153),
(132544, 'zhTW', '<箱子裡的彎劍的劍刃有一種熟悉的光澤。>', '', 28153),
(132541, 'zhTW', '<上千顆火槍彈藥被小心地一捆捆放在這箱子裡。>', '', 28153),
(132537, 'zhTW', '<箱子裡飄出的肯定是火藥味。>', '', 28153),
(132536, 'zhTW', '<將包裝拉開，你看到箱子裡有武器閃耀的光澤。>', '', 28153),
(132534, 'zhTW', '沒想到我會再次為塞勒斯冒險。$B$B當然我也沒想到我們兩個會活這麼久！', '', 28153),
(132533, 'zhTW', '等你查到貨物的消息就來跟我會合。', '', 28153),
(132532, 'zhTW', '把那些小傢伙送到鑄造廠西邊。我會在那邊看著，保證不讓任何人抓走他們。', '', 28153),
(132531, 'zhTW', '卡格尼用他的渡船將這女孩救出水面 - 說她想逃出鑄造廠。$B$B艾胥凡公司利用童工一點也不令我驚訝。當波拉勒斯的幫派強迫我當扒手，為他們引開守衛時，我才跟她差不多大而已。$B$B在這個世界，你越弱，就會有越多人利用你。', '', 28153),
(132495, 'zhTW', '', '古翰…這跟你說的…不一樣…', 28153),
(132494, 'zhTW', '', '蠢蛋！你的靈魂屬於古翰了！', 28153),
(132493, 'zhTW', '', '不！我還沒…準備…好…', 28153),
(132492, 'zhTW', '', '你膽敢打斷我的哀悼？你會後悔的！', 28153),
(132453, 'zhTW', '', '我還以為自己會被悶死在這裡！謝謝你！', 28153),
(132450, 'zhTW', '', '紐特氣喘吁吁。', 28153),
(132444, 'zhTW', '走這邊！', '走這邊！', 28153),
(132416, 'zhTW', '跟緊一點！', '', 28153),
(132415, 'zhTW', '我們必須到羅亞庭園去，不然就太遲了。請快一點！', '', 28153),
(132408, 'zhTW', '', '感謝你收拾殘局，贊姆蘭比傳說中更危險。', 28153),
(132406, 'zhTW', '那是我最近遇過最不舒服的事，謝了，$n！', '', 28153),
(132404, 'zhTW', '', '等我抓住亞茲瑪和那些蜘蛛…噢，那就精彩了。', 28153),
(132403, 'zhTW', '謝謝你，$ct。為了部落！', '謝謝你，$ct。為了部落！', 28153),
(132398, 'zhTW', '我沒時間應付這種閒聊。', '', 28153),
(132396, 'zhTW', '你問這個幹嘛？你也想被送到沙漠裡去嗎？', '', 28153),
(132376, 'zhTW', '', '我要讓你付出代價 - ', 28153),
(132374, 'zhTW', '啊啊啊啊！', '啊啊啊啊！', 28153),
(132365, 'zhTW', '羅亞回到神廟了。', '羅亞回到神廟了。', 28153),
(132364, 'zhTW', '你在這裡不安全，你應該趁早離開。', '你在這裡不安全，你應該趁早離開。', 28153),
(132343, 'zhTW', '在遺跡的另一邊有個隱蔽的地方，很適合當行動基地。叫大家到那裡集合。', '', 28153),
(132342, 'zhTW', '奎格瓦看了螢火蟲一會兒，對牠們的光感到開心。', '', 28153),
(132340, 'zhTW', '奎格瓦一口就把肉吃下去！', '', 28153),
(132325, 'zhTW', '你敢侮辱我？給我滾！', '', 28153),
(132324, 'zhTW', '奎格瓦瓦發怒了！你太慢了！', '', 28153),
(132323, 'zhTW', '我接受你的祭品。現在讓我看看你的能耐。', '', 28153),
(132322, 'zhTW', '奎格瓦瓦著惱地看著四周。他看來變得無聊了。引他分心！', '', 28153),
(132321, 'zhTW', '奎格瓦舔了舔嘴唇，飢餓地看著你。餵飽他！', '', 28153),
(132320, 'zhTW', '你帶了祭品來！我很高興！我會讓你多活一會兒。', '', 28153),
(132310, 'zhTW', '使用靈魂面具', '使用靈魂面具', 28153),
(132308, 'zhTW', '全能的奎格瓦，我為你獻上血肉與微光蠅。', '全能的奎格瓦，我為你獻上血肉與微光蠅。', 28153),
(132307, 'zhTW', '你是青蛙的朋友。我…我不會吃你。', '', 28153),
(132306, 'zhTW', '入侵者！你要來拐走我的孩子嗎？我要把你吃了。', '', 28153),
(132297, 'zhTW', '看樣子路是往這邊走的…', '', 28153),
(132296, 'zhTW', '怎麼回事，諾特利？', '', 28153),
(132294, 'zhTW', '這些是我蒐集的石頭，還請收下它們，我這把老骨頭已經沒法像以前以樣扛著寶藏到處走了。吼吼吼！', '', 28153),
(132293, 'zhTW', '噢，哈囉，你覺得你能救救一位老人家嗎？我似乎是陷進一場大麻煩裡了。', '', 28153),
(132289, 'zhTW', '我正在想個計畫搞定這一切，你別擔心。', '', 28153),
(132288, 'zhTW', '鬍渣渣謝謝你！這裡，把這些亮晶晶拿走吧，它們有霉運。', '', 28153),
(132287, 'zhTW', '', '那邊的，我需要你的幫忙！', 28153),
(132279, 'zhTW', '', '我們一定要守住陣地才行。我們所有人都是阻止家園面臨滅亡威脅的重要防線。', 28153),
(132275, 'zhTW', '', '你竟敢冒犯我們的聖地！', 28153),
(132274, 'zhTW', '', '滾！我們不需要別人的救贖！', 28153),
(132267, 'zhTW', '那還真糟糕。至少你幫我找到步槍了。', '', 28153),
(132266, 'zhTW', '我總是在獵捕鮮血食人妖，換成你也不錯。', '', 28153),
(132265, 'zhTW', '別亂動。我要乾淨地取下你的人頭。', '', 28153),
(132264, 'zhTW', '代我向伯昂撒姆第問好。', '', 28153),
(132263, 'zhTW', '站出來。別害羞。', '', 28153),
(132262, 'zhTW', '小心腳下…', '', 28153),
(132261, 'zhTW', '我要拿走你的頭。', '', 28153),
(132260, 'zhTW', '出來玩玩，小$r！', '', 28153),
(132254, 'zhTW', '', '埋伏！', 28153),
(132243, 'zhTW', '', '我決定要到東部庇護所去。希望那裡的人沒有遭遇到和谷溪村一樣的命運。', 28153),
(132240, 'zhTW', '', '我感覺得到，這個地方充滿了憤怒和悲傷。在這裡曾經發生過慘劇。', 28153),
(132237, 'zhTW', '<你看到這個凶狠陷阱的鋸齒深深刺進死亡獵人的腿裡面。$B$B在他的護身防具上面還有飛鏢刺在上面。$B$B從獵人一臉訝異的模樣判斷，他不知道下手的人是誰。>', '', 28153),
(132236, 'zhTW', '', '小狗狗，好好陪客人玩喔！不能讓他們餓肚子…或逃走！', 28153),
(132221, 'zhTW', '在這置入打靶場', '', 28153),
(132205, 'zhTW', '看管珍娜的人前幾天才來過這裡，他們要放逐她。如果我們動作夠快，或許來得及先找到她。', '', 28153),
(132201, 'zhTW', '', '入侵者！你會為我姊妹們的死付出代價！', 28153),
(132190, 'zhTW', '獸王說你現在是我們的一員了，允許你待在這裡，不過別以為我們不會盯著你。', '', 28153),
(132189, 'zhTW', '', '騎翼手龍很刺激！不過記得抓牢！', 28153),
(132188, 'zhTW', '很好，那我們就從這裡開始找。', '', 28153),
(132187, 'zhTW', '看樣子她應該是走這條路去找地方待了。', '', 28153),
(132186, 'zhTW', '我們會想辦法的，麥斯，只要先找到珍娜。尤里克，你說呢？', '', 28153),
(132185, 'zhTW', '', '我總覺得等我們回來的時候，他們不會幫忙開門的…', 28153),
(132180, 'zhTW', '', '這就對了，就是這條路！', 28153),
(132179, 'zhTW', '你想要老伯昂撒姆第做什麼事情？', '', 28153),
(132178, 'zhTW', '不壞，不壞！看來你有成為靈魂收割者的潛力！', '', 28153),
(132177, 'zhTW', '你竟敢褻瀆我的屍體！', '', 28153),
(132169, 'zhTW', '看誰能把珍娜找回來，聯盟已經備下重賞。', '看誰能把珍娜找回來，聯盟已經備下重賞。', 28153),
(132168, 'zhTW', '你是說在佐司瓦嗎？這不會是真的吧！\n\n不，長官，我的職責是在這裡為這些精銳士兵提供補給！只有腦袋不清楚的人才會想越過這道門！', '', 28153),
(132152, 'zhTW', '', '你是個出色的戰士，這點我承認。我會聽元帥命令行事。', 28153),
(132149, 'zhTW', '', '現在要回頭已經太遲了，尤里克。丹霍姆可不會輕易原諒攻擊他的人，即使是聽令行事也一樣。', 28153),
(132148, 'zhTW', '珍娜？！我們就是在找她嗎？這樣是叛國罪啊！', '', 28153),
(132146, 'zhTW', '我必須冒這個險，隊長。士兵們，聽我命令。', '', 28153),
(132145, 'zhTW', '就讓你通過吧，瑞德，不過我絕對會稟告王后！你以後別想再踏進波拉勒斯一步！', '', 28153),
(132144, 'zhTW', '夠了，我讓步！', '', 28153),
(132143, 'zhTW', '我們沒空陪你玩！士兵們，一起上！', '', 28153),
(132142, 'zhTW', '奉女王之命，誰也別想通過這道門。就連你也一樣。', '', 28153),
(132141, 'zhTW', '丹霍姆隊長，我是為了秘密任務才徵召了這些人。我命令你讓開，我們要通過！', '', 28153),
(132140, 'zhTW', '站住！元帥，你到底想帶我的人到哪裡去，啊？', '', 28153),
(132139, 'zhTW', '這樣就可以了！告訴瑞德元帥軍需官諾特利前來報到！', '', 28153),
(132138, 'zhTW', '我只是要…借點我們會需要的東西…', '', 28153),
(132137, 'zhTW', '獎勵，是吧？這下情況就不同了…', '', 28153),
(132136, 'zhTW', '先停火，看來他們已經逃跑了。', '', 28153),
(132135, 'zhTW', '去拿一把弩來幫我，內陸人！', '', 28153),
(132134, 'zhTW', '要是他對我下令，我一定會聽命行事，但是沒先解決掉這裡的野獸就去的話，就算是擅離職守了。', '', 28153),
(132133, 'zhTW', '我懷疑元帥就是因為那樣才會來到這裡，不過在這裡提到這個名字的時候還是小聲一點比較好…', '', 28153),
(132132, 'zhTW', '', '我告訴你，要是你能證明自己有這個勇氣，那我就加入瑞德的小小冒險。做好準備！', 28153),
(132131, 'zhTW', '', '我已經準備好要面對暗墓林的所有危險了，但我可不想照顧一個只會拖後腿的內陸人。', 28153),
(132130, 'zhTW', '', '歡迎，$r，加入大獵捕。在這裡，所有會動的東西都可以獵捕。$b$b我們榮耀所有從狩獵中帶回頂級戰利品的獵人。', 28153),
(132129, 'zhTW', '小心點！女巫的魔法很厲害！', '', 28153),
(132128, 'zhTW', '石板歷史悠久、磨損嚴重。它和擺在它前方的新鮮祭品形成強烈對比。', '石板歷史悠久、磨損嚴重。它和擺在它前方的新鮮祭品形成強烈對比。', 28153),
(132117, 'zhTW', '', '你的骨頭可以給女士享用！', 28153),
(132114, 'zhTW', '部落都是骯髒的人渣！', '', 28153),
(132113, 'zhTW', '這場戰爭沒有結束的一天嗎？', '', 28153),
(132112, 'zhTW', '我會回到陰影中。', '', 28153),
(132111, 'zhTW', '士兵，注意安全。', '', 28153),
(132107, 'zhTW', '在北方。沿著河走，直到水變淺時再過河。', '', 28153),
(132106, 'zhTW', '', '我會跟他們走，確保安全真的無虞。', 28153),
(132105, 'zhTW', '歡迎！抱歉，這裡有點亂，我們很少有活人訪客。', '', 28153),
(132096, 'zhTW', '嗯，我算是信了你的話…暫時。我們談談吧。', '', 28153),
(132095, 'zhTW', '', '我說真的！', 28153),
(132094, 'zhTW', '等一下，亞桑！$G他:她;頗有可信之處。或許這個小女孩講的是真話。', '', 28153),
(132093, 'zhTW', '啊，想講話拖延時間，直到你的朋友抵達嗎？', '', 28153),
(132092, 'zhTW', '', '等等，他們是朋友－－$n，小心！', 28153),
(132081, 'zhTW', '很抱歉蘇爾森沒來見你，他應該會喜歡你的頭髮。', '', 28153),
(132068, 'zhTW', '沒錯，我聽到$p說的話了，曼佐，不過我還是覺得你的眼罩比尖角蜥的背還醜。', '', 28153),
(132067, 'zhTW', '哈！沃尼，說點好話。他們可能就喜歡穿得一身黑…不過你說的沒錯！', '', 28153),
(132066, 'zhTW', '葛倫妮雅是我們的駐點吟遊詩人。她可以彈奏你點的任何歌曲…只要是鼓樂就成。她喜歡砸爛東西，希望不是砸你的臉，哈！別擔心，她不會的…大概吧。', '', 28153),
(132057, 'zhTW', '不，葛倫妮雅，我不會買黃金鼓給你！別再吵吵鬧鬧，不然我會沒收你的新帽子！', '', 28153),
(132055, 'zhTW', '我們必須保持冷靜，這個沼澤是強力巫毒術的來源。', '', 28153),
(132054, 'zhTW', '你聞起來挺不錯的，沼澤的氣味還沒滲入你的皮膚，現在來談談吧。', '', 28153),
(132053, 'zhTW', '', '黑暗找上安妮，但她卻不聽話。最後她被抓走了，也沒有人驚訝！', 28153),
(132049, 'zhTW', '', '山繆善良又溫柔，養了很多動物。現在山繆不見了，豬豬誰來照顧？', 28153),
(132048, 'zhTW', '', '海耶斯先生，他善良又和藹。可惜他的心，被女巫挖出來！', 28153),
(132047, 'zhTW', '', '瑪麗小姐背叛大家，追求邪惡力量。現在森林陰森可怕、村民死光光。', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(132046, 'zhTW', '這邊，外來客。', '', 28153),
(132045, 'zhTW', '', '我警告你，外來者，我會盯著你。你待會見到的，是目前世上數一數二老的食人妖。他能活這麼久，是因為有我們兄弟在保護他。所以你可別亂打什麼主意。', 28153),
(132044, 'zhTW', '為祖爾金復仇！', '', 28153),
(132043, 'zhTW', '希望船上有食物！', '希望船上有食物！', 28153),
(132042, 'zhTW', '真想找個暖暖的營火！', '真想找個暖暖的營火！', 28153),
(132041, 'zhTW', '也幫幫大人，拜託！', '也幫幫大人，拜託！', 28153),
(132040, 'zhTW', '謝謝你！', '謝謝你！', 28153),
(132039, 'zhTW', '我要回去上學…', '我要回去上學…', 28153),
(132038, 'zhTW', '抓不到我！我跑超快！', '抓不到我！我跑超快！', 28153),
(132037, 'zhTW', '我要走了！', '我要走了！', 28153),
(132020, 'zhTW', '', '冷靜一點，卓可。這些生物讓我們有個遮風躲雨的地方，讓我們贏得他們的信任。', 28153),
(132019, 'zhTW', '哇喔，這個靈魂還真強大！老伯昂撒姆第開心得不得了！哈哈！太好了，我變強了！', '', 28153),
(132017, 'zhTW', '', '你摧毀了自己獲得力量的機會…', 28153),
(132016, 'zhTW', '很好，這樣應該可以擋住他們一下。', '', 28153),
(132015, 'zhTW', '塞斯拉克人的帝國不斷擴張，連我們的同胞先前居住的平原也被奪走了。我們一定要阻止他們的征服行動！', '', 28153),
(132010, 'zhTW', '往岸邊走。那裡會有一艘船帶你到安全的地方。', '往岸邊走。那裡會有一艘船帶你到安全的地方。', 28153),
(132009, 'zhTW', '', '蠢蛋…你不知道你扯進了什麼事…', 28153),
(132004, 'zhTW', '我看到很多壞人。他們對每個人大吼大叫…連大人都被吼了！', '我看到很多壞人。他們對每個人大吼大叫…連大人都被吼了！', 28153),
(132003, 'zhTW', '你是壞人嗎？$B$B你看起來不壞。', '你是壞人嗎？$B$B你看起來不壞。', 28153),
(132002, 'zhTW', '我的鼻子凍僵了、我的耳朵凍僵了、我的腳趾凍僵了…', '我的鼻子凍僵了、我的耳朵凍僵了、我的腳趾凍僵了…', 28153),
(131999, 'zhTW', '他們說會給我們吃飯，但我來這裡後連麵包屑都沒看過！', '他們說會給我們吃飯，但我來這裡後連麵包屑都沒看過！', 28153),
(131998, 'zhTW', '', '搜查完成後，卓可和我會在那裡跟你會合。', 28153),
(131997, 'zhTW', '', '你先到神廟去，不用等我們。要是這個羅亞真的那麼厲害，或許能幫助我們找到洛琪拉。', 28153),
(131996, 'zhTW', '<咳嗽><咳嗽>$B$B我想回家。', '<咳嗽> <咳嗽>$B$B我想要回家。', 28153),
(131995, 'zhTW', '請不要對我大吼！', '請不要對我大吼！', 28153),
(131994, 'zhTW', '我累了。', '我累了。', 28153),
(131939, 'zhTW', '', '歡迎，士兵，你準備好為聯盟而戰了嗎？', 28153),
(131931, 'zhTW', '你以為你很辛苦？你根本不知道試著即時掌握哪個戰爭在何時發生有多困難。', '', 28153),
(131897, 'zhTW', '', '繼續飛，但願我們永遠不會發現。', 28153),
(131894, 'zhTW', '', '我們等下要穿越沼澤，只要待在空中別被看見，就不會有什麼問題。', 28153),
(131893, 'zhTW', '', '卡嘉，你看下面！那是什麼？', 28153),
(131888, 'zhTW', '媽媽的願望，一定會實現。', '', 28153),
(131887, 'zhTW', '吾命為戰母！', '', 28153),
(131886, 'zhTW', '為戰母獻上鮮肉！', '', 28153),
(131885, 'zhTW', '新的血！', '', 28153),
(131884, 'zhTW', '戰母說要殺…不，要活捉。對，活捉！', '', 28153),
(131883, 'zhTW', '往肌腱砍！切成碎片，戰母說把他們切成碎片。', '', 28153),
(131882, 'zhTW', '死吧！死吧！去死吧！', '', 28153),
(131881, 'zhTW', '<你搜索他的口袋，發現一封信。>\n\n我最親愛的瑪麗，\n\n請趕快回家。羅素一直在問你到哪去了。我該怎麼跟他說？母親跑進森林，不曉得做什麼去了？我們想念你，親愛的。我們家不再一樣了。拜託，請回到我們身邊。\n\n愛你的，\n強納森', '', 28153),
(131880, 'zhTW', '－嗝－走路看路行嗎…', '－嗝－走路看路行嗎…', 28153),
(131878, 'zhTW', '<調查屍體確認身分>', '<調查屍體確認身分>', 28153),
(131875, 'zhTW', '我們今天出什麼貨？', '我們今天出什麼貨？', 28153),
(131874, 'zhTW', '嗯？', '嗯？', 28153),
(131869, 'zhTW', '寡婦烈酒！三桶。', '寡婦烈酒！三桶。', 28153),
(131868, 'zhTW', '香料酒！五桶！深淵淡啤酒！七桶！還有…', '香料酒！五桶！深淵淡啤酒！七桶！還有…', 28153),
(131867, 'zhTW', '聽好了！今天我們的計畫如下！', '聽好了！今天我們的計畫如下！', 28153),
(131855, 'zhTW', '再次感謝你幫忙。我會把貢品直接帶到神廟裡去。', '再次感謝你幫忙。我會把貢品直接帶到神廟裡去。', 28153),
(131851, 'zhTW', '所有人，肅靜！$p會到你們每個人面前，向你們致意。', '', 28153),
(131845, 'zhTW', '目前這樣就夠了，到大階梯那兒去找公主，我會繼續巡邏，看看有沒有漏掉的聯盟。', '', 28153),
(131844, 'zhTW', '我們分成幾路盯住聯盟的行蹤，我會盡力幫你找到他們。', '', 28153),
(131843, 'zhTW', '真是放肆！敢在我的地盤撒野？真是的。他們一定會後悔的，嗯哼，非常後悔。', '', 28153),
(131842, 'zhTW', '', '我在這個世界停留了太久，現在，我終於得到了平靜！', 28153),
(131841, 'zhTW', '去吧，老兄。伯昂撒姆第守護著你。', '', 28153),
(131840, 'zhTW', '很好，很好。希瓦娜斯會樂見此事。來吧，「代言者」，我們接著討論下一步行動。', '', 28153),
(131839, 'zhTW', '等等，我們全部都要和那傢伙打？我以為我們可以…你知道的…派我們的勇士當代表之類的。', '', 28153),
(131838, 'zhTW', '要敲響那座鼓，你會需要曼布的重錘和基戴的重錘，你可以在我的神殿裡找到它們。', '', 28153),
(131832, 'zhTW', '謝謝你，朋友。', '', 28153),
(131831, 'zhTW', '我需要前往祖爾詹。', '我需要前往祖爾詹。', 28153),
(131830, 'zhTW', '', '雖然我死了，這些傢伙還是會聽我的命令而來。\n\n要載你嗎？', 28153),
(131829, 'zhTW', '借一步說話。有個狀況需要你了解一下。', '', 28153),
(131828, 'zhTW', '哈囉，我的朋友！我正到處在找你呢！', '', 28153),
(131818, 'zhTW', '別忘記你答應我的條件。如果想要伯昂撒姆第的協助…就繼續把靈魂送來。', '', 28153),
(131816, 'zhTW', '公主，別衝動！我們應該從長計議。先偵察那個區域，然後仔細計畫一下。', '', 28153),
(131803, 'zhTW', '', '我猜你就是她口中的那位英雄。若你能協助我們的公主，我就會把一切都跟你說。我照料我們的傷兵已經很久了，情況是越來越糟。\n\n她正要前往納茲米爾：她本來只帶了一名小侍衛，但你那邊的洛克漢也加入了。我們提供他們一切所需的補給品。\n\n他們往西北方的大門走了。自從鮮血食人妖開始圍攻主要大門後，那裡已經有一段時間沒看到鮮血食人妖了。\n\n我這個羅亞的眼睛受到遮蔽，無法知悉那邊的動靜。請步步小心。', 28153),
(131777, 'zhTW', '我會還這份人情，我保證。', '我會還這份人情，我保證。', 28153),
(131776, 'zhTW', '我可以走了？你不求回報？你跟別人不一樣耶。', '', 28153),
(131774, 'zhTW', '', '下頭真是一團亂，如果公主沒離開的話有多好。鮮血食人妖就在我們的大門外了，國王還是什麼事也不做！', 28153),
(131771, 'zhTW', '她在這待不到一天就已經走了！\n\n塔蘭姬要去某個地方，而且她沒讓她父親知道。她只帶了幾個隨身護衛，做做樣子。\n\n就算她沒講，我也覺得她要去納茲米爾。那是個很糟的地方，夥伴。如果我不能去，我會希望你代替我去。\n\n她會需要補給品。公主大概會在她之前常去的地方找牧師幫忙。讓我看你的地圖。', '', 28153),
(131766, 'zhTW', '塔蘭姬在哪裡？', '塔蘭姬在哪裡？', 28153),
(131765, 'zhTW', '你救了我們的公主，真是幫了我一個大忙。根據我的經驗，有時候想保護她根本是件麻煩事。她覺得，拯救贊達拉全是她一個人的事。', '', 28153),
(131764, 'zhTW', '你還真是寬宏大量。', '你還真是寬宏大量。', 28153),
(131763, 'zhTW', '沒有時間閒聊，士兵，這裡是前線指揮營地。我們這裡首當其衝，那邊的陶拉祖營地一直送來一波又一波該死的牛頭人。\n\n如果我們失去這個陣地，我不認為我們能攻破那些大門。', '', 28153),
(131761, 'zhTW', '你躲不過魔精的！', '', 28153),
(131752, 'zhTW', '瓦賈布，何必急著要去彼界呢？只要臣服於古翰，就能獲得永恆的生命！', '', 28153),
(131750, 'zhTW', '又一個可悲的流放者來沙漠找死？', '', 28153),
(131745, 'zhTW', '', '和洛克漢一起去納茲米爾。我會在那裡跟你碰頭。我們一定要解決鮮血食人妖這個大禍害。', 28153),
(131742, 'zhTW', '', '奧丁祝福你，還有這個…是你應得的報酬。', 28153),
(131741, 'zhTW', '好了，大夥，讓我們進去，把一切染紅吧。我要守衛在門口站崗，以免他們試著把我們趕出來；我還要一整組服務兵準備緊急醫療。還有，誰來幫我找來另一顆傳送石，好應付緊急狀況。', '', 28153),
(131709, 'zhTW', '發生什麼事了？我們怎麼被關了？', '', 28153),
(131706, 'zhTW', '', '尤里克，把你的野戰包拿過來。這裡有個倖存者！', 28153),
(131705, 'zhTW', '呃…噢！遵命！', '', 28153),
(131703, 'zhTW', '', '動作快，少尉！我們要在這裡找到出去的路！', 28153),
(131690, 'zhTW', '刃衛賀祖爾毫無反應。', '', 28153),
(131689, 'zhTW', '', '刃衛喬拉娜毫無反應。', 28153),
(131674, 'zhTW', '歡迎來到金牙旅店！', '', 28153),
(131672, 'zhTW', '這個流放者看樣子是還活著，不過也就只剩一口氣了。 \n\n他傷得很重，看他的傷勢，受到的傷害可能不只是明顯的外傷。', '', 28153),
(131671, 'zhTW', '似乎有光線從堵住通道的瓦礫堆另一頭穿透過來。\n\n要是能把這堆瓦礫殘骸清理掉，我們或許就能清出一條離開廢墟的路。', '', 28153),
(131670, 'zhTW', '這些生物是被冰霜魔法殺死的，看來珍娜一定到過這裡。\n\n不過，她究竟去了哪裡，卻依然是個謎。', '', 28153),
(131668, 'zhTW', '這足跡看起來像是在林子裡攻擊你們隊伍的其中一隻野獸。看樣子牠還拖著什麼東西一路往前走。\n\n奇怪的是，足跡到了某個地方就完全不見了，就像這頭野獸憑空消失了一樣。', '', 28153),
(131667, 'zhTW', '小心點，我餓到要生氣了！', '', 28153),
(131666, 'zhTW', '', '那是什麼鬼？', 28153),
(131665, 'zhTW', '恐角龍寶寶驚訝地嘶吼。', '', 28153),
(131664, 'zhTW', '恐角龍幼獸撒嬌地撲上你。', '', 28153),
(131663, 'zhTW', '恐角龍幼獸給你充滿愛意的一咬，意外地痛。', '', 28153),
(131662, 'zhTW', '恐角龍幼獸興奮地把你撞倒。', '', 28153),
(131661, 'zhTW', '我好餓，我吃得下一頭殘暴龍！', '', 28153),
(131659, 'zhTW', '媽媽，我可以吃更多肉嗎，拜託？', '', 28153),
(131658, 'zhTW', '鞭笞者很好吃，但我想要肉！', '', 28153),
(131657, 'zhTW', '%s淘氣地低鳴。', '', 28153),
(131656, 'zhTW', '%s頑皮地看著你。', '', 28153),
(131655, 'zhTW', '%s開心地踱步。', '', 28153),
(131654, 'zhTW', '%s興奮地嗥叫。', '', 28153),
(131653, 'zhTW', '聽著，你很有勇氣，孩子，但你不會談判，比不上我的。$b$b只要給我機會見他們的國王，我就能說服他讓出他的艦隊、他的王位、他們用來裝飾的黃金，甚至是幾個提基面具，離開時當作紀念品。', '', 28153),
(131652, 'zhTW', '嘿嘿，太棒了！老兄，說不定你值得我花點時間在你身上。我們回去神廟聊聊，老伯昂撒姆第有件事想跟你談談。', '', 28153),
(131651, 'zhTW', '啊，這個薩拉札…她在現世逗留太久了。無論如何，你一定要把她的靈魂帶來給我這位非常有耐心的羅亞，沒問題吧？', '', 28153),
(131650, 'zhTW', '', '如果你沒辦法讓我和我的愛人重逢，就快走吧。', 28153),
(131649, 'zhTW', '我們準備好接受你的祝福了。', '我們準備好接受你的祝福了，偉大的羅亞。', 28153),
(131648, 'zhTW', '這座神廟在許多年前就建成了。建築物沒有變，我的信眾卻換了好幾代。', '', 28153),
(131637, 'zhTW', '你好，小東西，我回來了。請向前一步，接受我的祝福。', '', 28153),
(131633, 'zhTW', '只有贊達拉人才能進入這神聖的地方！根據我們的律法…', '', 28153),
(131632, 'zhTW', '傳令下去…現在，你就是部落的代表了。', '', 28153),
(131631, 'zhTW', '只要我還是國王，我說的話就是律法。', '', 28153),
(131630, 'zhTW', '這位勇士，你會成為全國上下注目的焦點。從今天起，我稱呼你為部落代表。', '', 28153),
(131629, 'zhTW', '我們就來看看部落能給贊達拉什麼。我允許此人進出大封印之地…暫時先這樣吧。', '', 28153),
(131628, 'zhTW', '塔蘭姬擔心我分不清真正的敵人是誰。不過我可沒有糊塗到那種程度。', '', 28153),
(131627, 'zhTW', '但我女兒說的也有道理。救她出來需要無比的勇氣…我很敬佩這點。', '', 28153),
(131626, 'zhTW', '賈克拉傑說得沒錯…你是想藉助我們的兵力來對抗聯盟。', '', 28153),
(131625, 'zhTW', '', '太棒了！快點坐下來，開始品茶。多虧你和小親親，我可以叫最後一位客人過來了！', 28153),
(131624, 'zhTW', '', '在這裡！這一定會是最棒的下午茶會！', 28153),
(131623, 'zhTW', '', '快點！快點！茶會時間到囉！', 28153),
(131620, 'zhTW', '', '犧牲了你，再加上我丈夫，儀式就能完成！', 28153),
(131619, 'zhTW', '', '加入我們，姊妹，我們會獲得強大的力量！', 28153),
(131618, 'zhTW', '<男人的胸部中央有一個大型的開放性創傷。往內一看，你注意到他的心臟被挖了出來。>', '', 28153),
(131617, 'zhTW', '以木頭刻著「S. 霍桑」幾個字。', '', 28153),
(131616, 'zhTW', '', '霍桑先生總是不讓小狗狗靠近他養的動物。現在狗狗終於可以吃飯飯了！', 28153),
(131615, 'zhTW', '', '村裡的人都不見了。', 28153),
(131609, 'zhTW', '', '我們必須小心，還沒有人能夠從納茲米爾活著回去。', 28153),
(131608, 'zhTW', '', '鮮血食人妖只是卑賤的蠻子。他們早就不是威脅了。', 28153),
(131607, 'zhTW', '夠了。這個外來者的事由我來決定。', '', 28153),
(131606, 'zhTW', '', '要擊敗鮮血食人妖，就需要盟友。我只是做該做的事。', 28153),
(131605, 'zhTW', '塔蘭姬帶了部落的雜碎來。這可是叛國啊，陛下。', '', 28153),
(131604, 'zhTW', '', '把你的靈魂獻給主人！獻給古翰！', 28153),
(131603, 'zhTW', '這不會…就這樣…結束…', '不會…就這樣…結束…', 28153),
(131602, 'zhTW', '', '古翰才是這裡的主人。愚蠢的伯昂撒姆第也得臣服於他！', 28153),
(131544, 'zhTW', '我準備好了。', '我準備好了。', 28153),
(131543, 'zhTW', '', '<安妮看著你，她的眼神十分空洞。雖然她看起來沒有受傷，但她的衣服沾染著血。她結巴地說著話，但她說的內容很難懂。>', 28153),
(131542, 'zhTW', '麥斯、諾特利和尤里克已經回報，他們準備好要出發了。', '麥斯、諾特利和尤里克已經回報，他們準備好要出發了。', 28153),
(131541, 'zhTW', '你是從谷溪村來的嗎？', '你是從谷溪村來的嗎？', 28153),
(131540, 'zhTW', '', '<安妮劇烈地顫抖著，她望著空氣。>', 28153),
(131539, 'zhTW', '時候到了。到門那邊跟我會合，我們一起進攻佐司瓦！', '', 28153),
(131505, 'zhTW', '我不會在這種情況下離開他的。去讓其他人知道他們對他做了什麼，我會在神廟那邊跟你碰面。', '', 28153),
(131504, 'zhTW', '*吸鼻子*拜託你醒來…', '', 28153),
(131503, 'zhTW', '哈卡西你現在已經安全了…哈卡西？嘿…醒醒…', '', 28153),
(131497, 'zhTW', '壞魔暴龍！壞壞！', '壞魔暴龍！壞壞！', 28153),
(131496, 'zhTW', '謝謝你的幫助，還幫我把命令傳達下去。我會向瑞德元帥報告的。', '', 28153),
(131494, 'zhTW', '不過，時間不見得允許聰明的做法。', '', 28153),
(131493, 'zhTW', '等風暴平息下來再踏進這麼危險的地方，會是比較聰明的做法。', '', 28153),
(131492, 'zhTW', '很好，我會馬上準備好補給品。', '', 28153),
(131491, 'zhTW', '告訴瑞德元帥，諾特利軍需官前來報到！', '', 28153),
(131490, 'zhTW', '', '我們在門那裡會合，內陸人。希望你為接下來的一切做好準備了。', 28153),
(131489, 'zhTW', '', '哈！原來瑞德想衝進佐司瓦的森林裡？這裡也該發生一些有趣的事情了。', 28153),
(131487, 'zhTW', '', '內陸人，你來煩我是有重要的事…\n\n還是你看不出我很忙？', 28153),
(131486, 'zhTW', '有一場風暴正在暗墓林上方醞釀。能在事到臨頭之前發現，都稱得上是好事。\n\n搞得好像佐司瓦原本還不夠危險一樣…', '', 28153),
(131485, 'zhTW', '瑞德元帥下令加入尋找珍娜的搜索隊。', '瑞德元帥下令加入尋找珍娜的搜索隊。', 28153),
(131484, 'zhTW', '噢，我們這裡還真不常見到內陸人。\n\n你是來找補給品的嗎？', '', 28153),
(131479, 'zhTW', '我得承認，你的勇氣讓人刮目相看，內陸人。\n\n你雖然不是本地人，卻願意冒著生命危險拯救我們。我只希望你不只有這個心，還能有這個能力。\n\n我們會照你的意思離開這裡。', '', 28153),
(131478, 'zhTW', '撐住，哈卡希…我們會求你，我保證！', '', 28153),
(131477, 'zhTW', '你…永遠…無法得逞，你這個怪物！', '', 28153),
(131476, 'zhTW', '這怎麼回事，內陸人跑到這裡來？你一定是想來看看佐司瓦這個詛咒之地，又不想面對這裡真正的危險吧？\n\n回家吧，$G小伙子:小姑娘;。這裡可不是什麼旅遊景點。', '', 28153),
(131475, 'zhTW', '什麼？！\n\n對不起。我…我說錯了。 \n\n所以說，你跟普勞德摩爾家結盟了？看來你是為了珍娜的消息來的。你大老遠跑到北方來也不會有第二個原因了。\n\n看來，你來得正是時候。', '', 28153),
(131472, 'zhTW', '<把泰莉亞的紙條交給瑞德>', '<把泰莉亞的紙條交給瑞德>', 28153),
(131471, 'zhTW', '你好啊，漢札布。你是來還債的嗎？', '', 28153),
(131470, 'zhTW', '你有什麼消息嗎，旅行者？', '', 28153),
(131469, 'zhTW', '我們必須救他！', '', 28153),
(131468, 'zhTW', '我剛聽到洞裡傳來哈卡希的聲音！他似乎有麻煩了…', '', 28153),
(131467, 'zhTW', '$n！這裡！', '', 28153),
(131466, 'zhTW', 'Guards! Allies! Horde forces on approach from the southwest! Ready at the gates!', '', 28153),
(131465, 'zhTW', '蛇紋石交給你，我先進去尋找哈卡希…', '', 28153),
(131461, 'zhTW', '啊哈哈哈！漢札布，你把我當成傻瓜嗎？你殺不死這兩個人的。', '', 28153),
(131460, 'zhTW', '那兩個力量特別強。他們應該可以滿足我們的協議？', '', 28153),
(131459, 'zhTW', '偉大的伯昂撒姆第…依照約定，我帶靈魂來給你了。', '', 28153),
(131458, 'zhTW', '', '等等…聽，我覺得我聽到了什麼。', 28153),
(131457, 'zhTW', '', '屏障倒下了！讓我們離開這裡吧！', 28153),
(131456, 'zhTW', '她一點用都沒有。鮮血食人妖從北方入侵我們的土地，聯盟從南方滲入我們的邊界，而現在你讓這些部落的雜種進到我們的城裡來。', '', 28153),
(131455, 'zhTW', '', '無論你做了什麼，它阻止了一部分魔精通往屏障，讓我們再找找更多這種東西。', 28153),
(131454, 'zhTW', '', '洛琪拉是這王國最棒的領袖之一—', 28153),
(131453, 'zhTW', '我有關於哈卡希的消息。', '我有關於哈卡希的消息。', 28153),
(131452, 'zhTW', '', '敵人來了！', 28153),
(131451, 'zhTW', '', '去路被擋住了！讓我們四處看看，一定會有除掉這屏障的方法。', 28153),
(131450, 'zhTW', '', '都殺光！', 28153),
(131449, 'zhTW', '', '沒有人能阻止我們！', 28153),
(131448, 'zhTW', '', '打碎！', 28153),
(131447, 'zhTW', '', '去死吧！', 28153),
(131446, 'zhTW', '<遠處傳來怪物的吼叫聲。>', '', 28153),
(131445, 'zhTW', '我們必須快點找到他，免得為時已晚！準備好後，盡快到峽谷附近跟我會合！', '', 28153),
(131444, 'zhTW', '所以哈卡希前往峽谷調查某事，到現在都還沒回來…這不是什麼好消息。', '', 28153),
(131443, 'zhTW', '', '小心，這裡的魂靈頗有怒意。大概是困在這裡太久了。', 28153),
(131442, 'zhTW', '', '客人醒了。', 28153),
(131440, 'zhTW', '', '小親親非常喜歡森林，我絕對不會讓那些壞狗狗欺負牠！', 28153),
(131439, 'zhTW', '妳無法抓到我的，女巫！', '', 28153),
(131435, 'zhTW', '幫忙訓獸師制伏魔暴龍。', '幫忙訓獸師制伏魔暴龍。', 28153),
(131434, 'zhTW', '攻擊紅死病！', '攻擊紅死病！', 28153),
(131431, 'zhTW', '丟出玩具以干擾魔暴龍！', '丟出玩具以干擾魔暴龍！', 28153),
(131430, 'zhTW', '衝向屏障，把它衝破！', '衝向屏障，把它衝破！', 28153),
(131429, 'zhTW', '從北門逃出去！別被魔暴龍抓到！', '從北門逃出去！別被魔暴龍抓到！', 28153),
(131428, 'zhTW', '祝你好運，學徒！', '', 28153),
(131427, 'zhTW', '歡迎來到訓練場！在你面前的是小指頭，我們兇猛的小魔暴龍。', '', 28153),
(131426, 'zhTW', '那貨物是我們的，聯盟人渣！', '那貨物是我們的，聯盟人渣！', 28153),
(131425, 'zhTW', 'Inspect the body further.', 'Inspect the body further.', 28153),
(131424, 'zhTW', '<傷口非常深，這些傷口非常的精準。$B$B傷口周圍有某種殘留的液體在光線下閃爍。>', '', 28153),
(131419, 'zhTW', '', '等你準備好就出發，別浪費時間。我擔心洛琪拉沒辦法撐太久。', 28153),
(131418, 'zhTW', '', '在找到洛琪拉之前我不會休息。', 28153),
(131416, 'zhTW', '你從沒騎魔暴龍打架過？他咬人不痛…通常都不痛啦！', '你從沒騎魔暴龍打架過？他咬人不痛…通常都不痛啦！', 28153),
(131415, 'zhTW', '', '你是對的！我們上吧！', 28153),
(131414, 'zhTW', '', '沒錯，你的話充滿智慧。來，讓我們尋找離開這個地窖的路。', 28153),
(131413, 'zhTW', '', '你的話沒錯，老兄。我們四處搜索，這裡一定會有能出去的路。', 28153),
(131408, 'zhTW', '放棄不是一個士兵會做的事，普雅。現在，振作起來，讓我們想辦法離開這裡。為了部落！', '放棄不是一個士兵會做的事，普雅。現在，振作起來，讓我們想辦法離開這裡。為了部落！', 28153),
(131407, 'zhTW', '我們有任務在身，普雅，無論如何，我們都必須完成！', '我們有任務在身，普雅，無論如何，我們都必須完成！', 28153),
(131406, 'zhTW', '這是你要展現給大酋長的態度嗎？他們在指望我們呢！', '這是你要展現給大酋長的態度嗎？他們在指望我們呢！', 28153),
(131405, 'zhTW', '', '抵抗沒有用，我們完了！', 28153),
(131404, 'zhTW', '你是暗影獵手，普雅，向他們證明「暗影獵手」不只是個頭銜吧。', '你是暗影獵手，普雅，向他們證明「暗影獵手」不只是個頭銜吧。', 28153),
(131403, 'zhTW', '你祖宗們的希望和夢想都在你身上，你沒打過一仗就想放棄了嗎？', '你祖宗們的希望和夢想都在你身上，你沒打過一仗就想放棄了嗎？', 28153),
(131399, 'zhTW', '你可以繼續奮戰啊！相信你自己，讓他們引以為傲。', '你可以繼續奮戰啊！相信你自己，讓他們引以為傲。', 28153),
(131396, 'zhTW', '', '什麼？當然不行！', 28153),
(131392, 'zhTW', '振作一點，你可以更好的，你是個暗影獵手！', '振作一點，你可以更好的，你是個暗影獵手！', 28153),
(131391, 'zhTW', '塔蘭姬公主好像沒打算要等。她和祖爾已經到碼頭去了。你動作快點或許還能追上。', '', 28153),
(131389, 'zhTW', '', 'Placeholder World Quest Text', 28153),
(131388, 'zhTW', '如果你感受得到絕望，代表你的靈魂還活著，你也可以做些什麼改變現況！', '如果你感受得到絕望，代表你的靈魂還活著，你也可以做些什麼改變現況！', 28153),
(131387, 'zhTW', '他掙脫了！跑啊！', '他掙脫了！跑啊！', 28153),
(131386, 'zhTW', '我們還有希望！如果我們合作，我們就能想辦法擊敗這個詛咒。', '我們還有希望！如果我們合作，我們就能想辦法擊敗這個詛咒。', 28153),
(131385, 'zhTW', '現在嘛，就讓你和洛克漢決定怎樣才是做比較好，因為他比我還了解那群人。$b$b再說，那群食人妖對我這種不肯乖乖死去的人有成見。我才不想讓他們那種短視的人防礙我們取得艦隊。$b$b絕對不能失敗，一定要幫希瓦娜斯爭取到艦隊。', '', 28153),
(131384, 'zhTW', '', '喔？你為何會這麼想呢？', 28153),
(131383, 'zhTW', '你振作一點，我們還可以抵抗！', '你振作一點，我們還可以抵抗！', 28153),
(131382, 'zhTW', '當你遇見你祖先的靈魂時，你真的想跟他們說你放棄了嗎？', '當你遇見你祖先的靈魂時，你真的想跟他們說你放棄了嗎？', 28153),
(131377, 'zhTW', '別向絕望屈服！我們會想出辦法的。', '別向絕望屈服！我們會想出辦法的。', 28153),
(131372, 'zhTW', '我們快點走吧。', '我們快點走吧。', 28153),
(131371, 'zhTW', '我真不敢相信哈卡希把這麼多事留給我們。他回來時要為此付出代價！', '', 28153),
(131370, 'zhTW', '', '哈哈！刺穿它吧！', 28153),
(131369, 'zhTW', '', '真是令人絕望，我們該怎麼離開這裡？', 28153),
(131333, 'zhTW', '他跟我提到峽谷裡的騷動，我告訴他沒什麼好擔心的。', '', 28153),
(131332, 'zhTW', '嗯…讓我想想，喔，對了！我不久前看到他走進峽谷，不知道他去那裡做什麼？', '', 28153),
(131331, 'zhTW', '哈卡希？是的，我今天有見到他。他就在不遠處，為儀式在聚集供品。', '', 28153),
(131329, 'zhTW', '', '散開！快逃到安全的地方！想辦法盡量遠離這些蛇！', 28153),
(131327, 'zhTW', '卡嘉，我們要繞一下路，塞斯拉克帝國就在附近。', '', 28153),
(131325, 'zhTW', '', '你說蛇人？我以為他們都躲在沙子裡…', 28153),
(131322, 'zhTW', '', '就在前面！我看到了！飛低一點，找找看有沒有洛琪拉的下落。', 28153),
(131306, 'zhTW', '你之前從沒見過偉大的亞昆達？你來的正是時候！', '', 28153),
(131305, 'zhTW', '在亞昆達到來之前，我有好多事要做！沒時間了…沒時間了！', '', 28153),
(131304, 'zhTW', '你看見哈卡希了嗎？', '你看見哈卡希了嗎？', 28153),
(131303, 'zhTW', '我們的人已經好多年沒有召喚亞昆達了。我等不及要再次看到他了！', '', 28153),
(131302, 'zhTW', '%s興奮地吞下每一口食物，接著嗝出火焰！', '', 28153),
(131300, 'zhTW', '%s大聲地吞掉那棵植物。', '', 28153),
(131299, 'zhTW', '終於，真正的戰鬥！\n\n這些部落傻瓜認為他們可以攻破那兒的裂口然後攻進前線指揮營地。我該說什麼？\n\n呸！\n\n來，讓我們一起砍殺幾個人渣。', '', 28153),
(131298, 'zhTW', '', '我真高興你來了，士兵，我們快撐不住了！\n\n凱旋堡壘是我們攻擊大門的關鍵隘口。從奧格瑪來的援軍不斷攻擊北方的裂口，如果我們不守住這裡，我們從塞拉摩來的所有船隊都會有危險。', 28153),
(131297, 'zhTW', '如你所願，海加希大師…', '', 28153),
(131296, 'zhTW', '試吃食物不算是「準備盛宴」。我不會再說第二次了，里夫。', '', 28153),
(131295, 'zhTW', '但我已經忙著準備盛宴！', '', 28153),
(131294, 'zhTW', '哈卡希還沒送來最後一個祭品。請帶著我們的新朋友一起去，幫我們收集祭品。', '', 28153),
(131293, 'zhTW', '是的，海加希大師！', '', 28153),
(131292, 'zhTW', '里夫！去接待我們的客人。', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(131291, 'zhTW', '沒有祭品，我們就無法召喚羅亞。也許你可以幫忙我們…', '', 28153),
(131290, 'zhTW', '舉行儀式的時間就快到了，但是還有很多必要的祭品還沒送來。', '', 28153),
(131289, 'zhTW', '在神廟的房間裡尋找古老的石板，亞昆達的傳說等你一探究竟。', '', 28153),
(131255, 'zhTW', '願我們永遠頌揚偉大的雷霆蜥蜴。願他永遠守護這座叢林。', '', 28153),
(131254, 'zhTW', '', '很好。菜鳥，現在選一顆蛋。如果你的腦海裡響起牠的聲音，就代表牠接受你了…', 28153),
(131250, 'zhTW', '', '<嘉茲麗族母若有所思地打量你>', 28153),
(131249, 'zhTW', '', '她就在這裡，她是兇猛和優雅的完美結合對吧？要挑戰她，膽子要夠大。', 28153),
(131248, 'zhTW', '', '這座建築看起來跟伯昂撒姆第位於祖達薩的神廟非常像，但是年代更久遠。', 28153),
(131247, 'zhTW', '我的恐角龍從他孵化那刻就和我在一起，我們戰鬥無間。', '我的恐角龍從他孵化那刻就和我在一起，我們戰鬥無間。', 28153),
(131246, 'zhTW', '不錯，想當喚獸者當然需要技巧，但更需要無限的耐心。你知道的，年幼的恐角龍本身就是麻煩製造者！', '不錯，想當喚獸者當然需要技巧，但更需要無限的耐心。你知道的，年幼的恐角龍本身就是麻煩製造者！', 28153),
(131245, 'zhTW', '因此，我們在此一遺址上建造這座神廟供奉亞昆達。願我們不再遺忘這位偉大的羅亞。', '', 28153),
(131244, 'zhTW', '塵埃落定之時，我們爬到山頂。祖爾克汗毫無生氣的屍體躺在我們面前，但亞昆達也消失無蹤。', '', 28153),
(131243, 'zhTW', '正當激戰似乎永遠不會結束的時候，塵埃落定，大地也平靜了下來…', '', 28153),
(131242, 'zhTW', '亞昆達終於歸來，兩隻野獸立刻戰得難分難解，每一擊都使大地震動！', '', 28153),
(131241, 'zhTW', '正當希望失落的時候，一陣嘹亮的吼聲響徹整個峽谷。一個身影出現在懸崖上，遮蔽住了月光。', '', 28153),
(131240, 'zhTW', '我們全力攻擊祖爾克汗，但他的力量太過強大！他順利逃走…我們從此災難連連。', '', 28153),
(131239, 'zhTW', '我們引誘祖爾克汗深入峽谷，設下埋伏。巨大的網子從天而降…', '', 28153),
(131238, 'zhTW', '部族的長老在沃魯阿曼的中心會面。我們要團結一心、齊心奮戰，還是要收拾家當、逃離叢林？我們選擇奮戰！', '', 28153),
(131237, 'zhTW', '祖爾克汗來去自如，對這片土地造成威脅。他肆意追殺我的族人。那是段不堪回首的日子…', '', 28153),
(131236, 'zhTW', '我們不再獻上祭品給偉大的雷霆蜥蜴，最終，亞昆達從叢林中消失…', '', 28153),
(131235, 'zhTW', '亞昆達使我們免於祖爾克汗帶來的恐懼，但隨著時間過去，我的族人也越來越自滿。', '', 28153),
(131234, 'zhTW', '魔暴龍祖爾克汗嫉妒羅亞的力量，他潛伏在幽暗的叢林中，貪婪殘暴，以殺戮為樂。', '', 28153),
(131233, 'zhTW', '叢林中的所有生物都敬畏他的力量和偉大，除了一個人以外。那殘暴的祖爾可汗…', '', 28153),
(131232, 'zhTW', '很久以前，我的族人敬畏地看著這隻偉大的雷霆蜥蜴在叢林中漫遊。', '', 28153),
(131231, 'zhTW', '我，札加吉，部族首領及這座神廟的建築者，在此將它獻給偉大的亞昆達。', '', 28153),
(131230, 'zhTW', '我打出生就開始接受成為喚獸者的訓練，你又做了什麼？', '我打出生就開始接受成為喚獸者的訓練，你又做了什麼？', 28153),
(131229, 'zhTW', '戰鬥吧！', '戰鬥吧！', 28153),
(131228, 'zhTW', '', '贊達拉萬歲！', 28153),
(131227, 'zhTW', '', '羅亞與我同在！', 28153),
(131226, 'zhTW', '', '為了祖達薩！', 28153),
(131224, 'zhTW', '', '戰衛洛琪拉是我的長官。她是有史以來最厲害的。', 28153),
(131223, 'zhTW', '我不問問題，只遵守命令。你最好也不要問什麼問題。', '', 28153),
(131222, 'zhTW', '快點，$n。我不是負責聊天的。', '', 28153),
(131221, 'zhTW', '', '你想找死嗎？這裡到處都是將軍的耳目。', 28153),
(131220, 'zhTW', '', '無論你需要什麼，有話就快說。', 28153),
(131218, 'zhTW', '', '如你所見，我們當中還是有人也這麼認為。', 28153),
(131215, 'zhTW', '', '喂！就是你！你就是那個到處探聽將軍的人嗎？', 28153),
(131214, 'zhTW', '', '扔進沙漠就等於是死刑。我不會眼睜睜看著洛琪拉死在沙漠裡的！', 28153),
(131213, 'zhTW', '', '不管她發現了什麼，都讓他們動了殺機想將她滅口。', 28153),
(131212, 'zhTW', '', '她跟我說很快就能證明賈克拉傑將軍是個叛國賊，卻再也沒有她的消息了。', 28153),
(131211, 'zhTW', '', '跟我一起走，不要讓任何人注意到你。', 28153),
(131210, 'zhTW', '你能多告訴我一點賈克拉傑將軍的事嗎？', '你能多告訴我一點賈克拉傑將軍的事嗎？', 28153),
(131209, 'zhTW', '', '需要我幫忙嗎？', 28153),
(131208, 'zhTW', '我很抱歉你們兩個被捲入這件事，但至少你們能如願見到伯昂撒姆第！嘿嘿呵！', '', 28153),
(131207, 'zhTW', '很好，這個靈魂非常有價值，我會把它獻給伯昂撒姆第！', '', 28153),
(131206, 'zhTW', '該死，他們找到我了！嘿，幫助我，我們就能談談你想要的協助。', '', 28153),
(131205, 'zhTW', '準備戰鬥！', '', 28153),
(131204, 'zhTW', '', '元帥，不！', 28153),
(131203, 'zhTW', '放開$G他:她;，你 -', '', 28153),
(131202, 'zhTW', '', '小心，內陸人！', 28153),
(131201, 'zhTW', '麥斯、尤里克，在這個區域散開，尋找 - ', '', 28153),
(131200, 'zhTW', '', '你覺得她是不是…到下面去了？', 28153),
(131199, 'zhTW', '我不懂，路明明是往這裡…', '', 28153),
(131198, 'zhTW', '這是條死路…', '', 28153),
(131197, 'zhTW', '', '這裡…是哪裡？！', 28153),
(131196, 'zhTW', '遠方好像有棟建築物。珍娜一定是要去那裡！', '', 28153),
(131195, 'zhTW', '這些野獸擋住路了，解決牠們！', '', 28153),
(131194, 'zhTW', '我們一定要繼續深入森林裡！排好隊形！', '', 28153),
(131193, 'zhTW', '看起來像是冰霜魔法…珍娜一定是往這裡走了！', '', 28153),
(131192, 'zhTW', '可惡！我們只好先繼續行動了…等等，這是什麼？', '', 28153),
(131191, 'zhTW', '長官！我看不到諾特利的蹤影，在這種風暴中也沒辦法追蹤足跡！', '', 28153),
(131190, 'zhTW', '這…這很不妙。', '', 28153),
(131189, 'zhTW', '', '這到底是…', 28153),
(131188, 'zhTW', '快點，他們往這裡去了！', '', 28153),
(131187, 'zhTW', '', '有埋伏！', 28153),
(131186, 'zhTW', '唉呀！！！', '', 28153),
(131185, 'zhTW', '諾特利，不要！', '', 28153),
(131184, 'zhTW', '等等…我好像看到什麼了…', '', 28153),
(131183, 'zhTW', '快，我們繼續走。', '', 28153),
(131182, 'zhTW', '我還寧願相信是這麼回事。但我覺得這是某種更黑暗的力量。', '', 28153),
(131181, 'zhTW', '', '看樣子森林裡不是只有野獸。你覺得是被流放的人做的嗎？', 28153),
(131180, 'zhTW', '站住！這是什麼？', '', 28153),
(131179, 'zhTW', '這不是什麼好兆頭…', '', 28153),
(131178, 'zhTW', '這些野獸變得更大膽，也更會直接攻擊人了。', '', 28153),
(131177, 'zhTW', '怎麼回事？都提高警覺！', '', 28153),
(131176, 'zhTW', '聽我命令！', '', 28153),
(131175, 'zhTW', '拿起武器做好準備，我們今晚要勇敢深入黑暗！', '', 28153),
(131174, 'zhTW', '森林裡的野獸不太友善…對任何人都是這樣。', '', 28153),
(131173, 'zhTW', '這場風暴會遮蔽我們的視線，靠近一點，不要走錯路了。', '', 28153),
(131172, 'zhTW', '我準備開始訓練了。', '我準備開始訓練了。', 28153),
(131171, 'zhTW', '我們在訓練各式各樣的野獸。就算那些生來是運貨的也得接受戰鬥訓練！', '', 28153),
(131170, 'zhTW', '我們要沿著這條路走到命運絕地，流放者一定會往這個地方去。', '', 28153),
(131169, 'zhTW', '', '靈魂…離開…我的身體…', 28153),
(131168, 'zhTW', '', '呃啊！！', 28153),
(131167, 'zhTW', '', '我沒…辦法…', 28153),
(131166, 'zhTW', '', '你永遠都無法擊敗我們的！在我嚥下最後一口氣前，我詛咒你們所有人！我們地府再見吧！', 28153),
(131165, 'zhTW', '', '騎乘獸和騎乘者之間的連結可藉由神像建立。準備好的時候，就碰一下薩烏石吧。', 28153),
(131158, 'zhTW', '僅代表亞昆達，偉大的羅亞，我歡迎你來到這個神廟，旅行者。', '', 28153),
(131148, 'zhTW', '', '你打得很好，我的小朋友跟著你很安全。', 28153),
(131142, 'zhTW', '', '我的孩子值得最好的！', 28153),
(131115, 'zhTW', '幹掉他們，孩子們！', '', 28153),
(131114, 'zhTW', '懦夫！派出你最厲害的勇士，讓我們瞧瞧他的能耐！', '', 28153),
(131113, 'zhTW', '讓我們來看看這些部落為我們存了什麼好東西？', '', 28153),
(131112, 'zhTW', '', '你將流出鮮血！', 28153),
(131111, 'zhTW', '', '這次我抓到你了，漢札布！你會為我姊妹們的死付出代價！', 28153),
(131109, 'zhTW', '我們去找伯昂撒姆第這名羅亞。', '我們去找伯昂撒姆第這名羅亞。', 28153),
(131108, 'zhTW', '看來最糟的部分已經過去了，讓我們在這裡休息一下，再繼續前進。', '', 28153),
(131107, 'zhTW', '做得很好，這些部隊對戰事很有貢獻。', '', 28153),
(131106, 'zhTW', '部隊休息，我們在這裡等一分鐘，然後立刻出發。', '', 28153),
(131105, 'zhTW', '聯盟的士兵！在我們前往前線指揮營地的路上，守護這支勇敢的艦隊！', '', 28153),
(131098, 'zhTW', '這些利爪…和牙齒…看來我會做好一陣子關於這件事的惡夢了。', '這些利爪…和牙齒…看來我會做好一陣子關於這件事的惡夢了。', 28153),
(131097, 'zhTW', '你來得正是時候。', '你來得正是時候。', 28153),
(131096, 'zhTW', '我還以為我撐不下去了，謝謝你！', '我還以為我撐不下去了，謝謝你！', 28153),
(131094, 'zhTW', '你的衣服上沒有塵土，聞起來也不臭。$b$b你是誰，怎麼在這沼澤亂晃？', '', 28153),
(131093, 'zhTW', '你是誰，陌生人？你聞上去不像是個鮮血食人妖。', '', 28153),
(131088, 'zhTW', '', '耶！這一定是最棒的下午茶會！我們去找其他客人。', 28153),
(131087, 'zhTW', '你找漢札布做什麼？', '', 28153),
(131086, 'zhTW', '', '小象鼻，瑪麗小姐不准你進到屋子裡！你弄得到處都是泥巴！', 28153),
(131085, 'zhTW', '', '噢，啃滋龍先生！你一定很餓了吧？快點過來喝杯茶吧。', 28153),
(131081, 'zhTW', '', '調皮的史椎市長！一天到晚都想逃避身為市長的責任。這下你別想跑掉了！', 28153),
(131080, 'zhTW', '', '我不相信他，我們應該…', 28153),
(131079, 'zhTW', '安靜！不准再發出任何聲音！', '', 28153),
(131078, 'zhTW', '', '呃啊！', 28153),
(131077, 'zhTW', '喔不錯！這是個很棒的戰利品！', '', 28153),
(131057, 'zhTW', '$n守住了伐木場！', '', 28153),
(131056, 'zhTW', '聯盟已拿下船艦殘骸！', '', 28153),
(131055, 'zhTW', '部落已拿下船艦殘骸！', '', 28153),
(131054, 'zhTW', '$n襲擊了船艦殘骸！', '', 28153),
(131049, 'zhTW', '部落在通往北方城堡的路上部署了一台坦克！必須毀掉它！', '部落在通往北方城堡的路上部署了一台坦克！必須毀掉它！', 28153),
(131048, 'zhTW', 'Scenario Complete.', 'Scenario Complete.', 28153),
(131033, 'zhTW', '', '幫第七軍團艦隊開路！等援軍一到就能擊退敵人了。', 28153),
(131032, 'zhTW', 'Test', '', 28153),
(131030, 'zhTW', '', '聽著，夥伴！魔精的痕跡通往北邊，讓我們跟著它走。', 28153),
(131025, 'zhTW', '', '北邊有什麼消息嗎？', 28153),
(131010, 'zhTW', '', '嗯…為獻祭殺戮，還很新鮮。無論這裡舉行了什麼儀式，殘留的魔精留下了一道痕跡。讓我們來看看它會帶我們去哪裡。', 28153),
(131009, 'zhTW', '屍體背後插著一把小刀。', '屍體背後插著一把小刀。', 28153),
(131008, 'zhTW', '', '我感覺北邊有個超強的東西，我們去看看吧。', 28153),
(131007, 'zhTW', '', '我剛發現這個地方的時候，並沒有這個這個祭品。看來伯昂撒姆第還是有個追隨者。', 28153),
(131000, 'zhTW', '納茲米爾惡劣的氣候磨平了石板上大部分的字。只有「讚揚」、「靈魂」和「墳墓」這些字能被辨認。', '納茲米爾惡劣的氣候磨平了石板上大部分的字。只有「讚揚」、「靈魂」和「墳墓」這些字能被辨認。', 28153),
(130979, 'zhTW', 'Our scouts reported Horde forces advancing toward Northwatch under the cover of night. We require your immediate aide!', '', 28153),
(130978, 'zhTW', '', '聯盟的士兵們！時候到了！我們現在就要攻破莫高雷的雄偉之門！並肩推進，努力奮戰！', 28153),
(130977, 'zhTW', '', 'Everyone to the docks!', 28153),
(130969, 'zhTW', '', '啊，古翰說對了，你們終於來了。我就來找點樂子吧！', 28153),
(130967, 'zhTW', '', '第七軍團艦隊的士兵，出征的時候到了。收好你們的東西和裝備，準備出發。', 28153),
(130947, 'zhTW', '你沒看到我快要餓死了嗎？', '', 28153),
(130946, 'zhTW', '媽媽，餵我！', '', 28153),
(130945, 'zhTW', '%s開心地用頭頂著你。', '', 28153),
(130944, 'zhTW', '', '我的存在不會因死亡而逝去。', 28153),
(130943, 'zhTW', '想玩個遊戲嗎？你跑，然後我會試著抓住你然後吃掉你！', '', 28153),
(130940, 'zhTW', '%s悲傷地瞪視你。', '', 28153),
(130939, 'zhTW', '%s飢餓地哼著聲。', '', 28153),
(130938, 'zhTW', '%s 哼著聲，用力地用鼻子撞你。', '', 28153),
(130937, 'zhTW', '%s的肚子發出很大的咕嚕聲。', '', 28153),
(130936, 'zhTW', '%s溫暖地用鼻子撫著你。', '', 28153),
(130935, 'zhTW', '', '你無法打敗我們全部人。達薩亞洛將陷落！', 28153),
(130934, 'zhTW', '我打算把傷者送走。處理好事情之後，請到拉茲洛提克和我們見面，我們會把這場戰事結束。', '', 28153),
(130932, 'zhTW', '孵化中…', '孵化中…', 28153),
(130931, 'zhTW', '', '挖了你的腸！', 28153),
(130930, 'zhTW', '', '剝了你的皮！', 28153),
(130929, 'zhTW', '', '更多鮮血！更多鮮血！', 28153),
(130928, 'zhTW', '', '媽媽需要你的血。', 28153),
(130927, 'zhTW', '', '骨頭不錯。', 28153),
(130926, 'zhTW', '', '新鮮的肉，流竄的血。', 28153),
(130925, 'zhTW', '呃，這麼多傷口要花我一個星期才會痊癒。', '呃，這麼多傷口要花我一個星期才會痊癒。', 28153),
(130924, 'zhTW', '鮮血食人妖野人！', '鮮血食人妖野人！', 28153),
(130923, 'zhTW', '哈！你今天才得不到我的血。', '哈！你今天才得不到我的血。', 28153),
(130922, 'zhTW', '他們說過他們要用我的血。', '他們說過他們要用我的血。', 28153),
(130921, 'zhTW', '哈！你今天才抓不到我，你們這群野蠻人。', '哈！你今天才抓不到我，你們這群野蠻人。', 28153),
(130920, 'zhTW', '他們剛要開始一場儀式，我可以感受到我的骨頭在皮膚下滑動。', '他們剛要開始一場儀式，我可以感受到我的骨頭在皮膚下滑動。', 28153),
(130919, 'zhTW', '他們在我的手臂上刻了符號，那些野蠻人。', '他們在我的手臂上刻了符號，那些野蠻人。', 28153),
(130918, 'zhTW', '耶！今天才抓不到這名食人妖。', '耶！今天才抓不到這名食人妖。', 28153),
(130917, 'zhTW', '謝謝你！非常謝謝你！', '謝謝你！非常謝謝你！', 28153),
(130915, 'zhTW', '先別開火，這是我們的援兵！', '', 28153),
(130914, 'zhTW', '', '夥計，走啦，該打獵了！', 28153),
(130913, 'zhTW', '', '來吧！就快開始孵化了。', 28153),
(130907, 'zhTW', '我準備好了。', '我準備好了。', 28153),
(130906, 'zhTW', '', '歡迎來到戰獸欄，$n。\n\n我聽說過你們的部落，我也知道你來這裡是為了跟老拉斯塔哈達成協議。\n\n我們會觀察你到底有沒有用，也許到時候，我們可以在達薩面前幫你說點好話，懂？', 28153),
(130905, 'zhTW', '如果我發現是誰對你這老傢伙做這種事…', '', 28153),
(130904, 'zhTW', '鮮血食人妖在用陰謀作戰。', '', 28153),
(130903, 'zhTW', '黑魔法，這不尋常。', '', 28153),
(130902, 'zhTW', '老傢伙，他們用了什麼詛咒你？', '', 28153),
(130901, 'zhTW', '加油，老傢伙，你撐得下去的。', '', 28153),
(130900, 'zhTW', '維持隊形！將死傷者帶回，但務必維持你的隊形。', '', 28153),
(130899, 'zhTW', '看守天空！還有更多血腹襲來。', '', 28153),
(130898, 'zhTW', '你是贊達拉人，打的像樣點！', '', 28153),
(130897, 'zhTW', '讓那個傷兵站起來！別讓任何人被這些野蠻人擄走。', '', 28153),
(130896, 'zhTW', '堅守陣地，兄弟姊妹們！我們今天不會被這些野人打敗的！', '', 28153),
(130842, 'zhTW', '助每個人一臂之力。', '助每個人一臂之力。', 28153),
(130841, 'zhTW', '', '或許你比看起來的還強。我的勇士不會對你太客氣的。你準備好要開始時，就來挑戰他吧。', 28153),
(130840, 'zhTW', '', '我沒想到一個初學者會讓你遇到這麼大的困難。讓我們來看看你對付一個強一點的對手會如何。', 28153),
(130839, 'zhTW', '我可以提供你各種物資，以便援助戰爭前線。', '', 28153),
(130838, 'zhTW', '', '你真的準備好要承擔這項責任了嗎？現在重新考慮還不遲。', 28153),
(130822, 'zhTW', '新將軍升官了！', '新將軍升官了！', 28153),
(130797, 'zhTW', '', '你很有決心，我很欣賞。是見嘉茲麗族母的時候了，來吧。', 28153),
(130796, 'zhTW', '', '你準備好把小恐龍的需求擺在第一位了嗎？你知道牠們的食量多大嗎？', 28153),
(130795, 'zhTW', '與野獸的連結打從一孵化就開始了，會持續一輩子。牠們就是家人。', '與野獸的連結打從一孵化就開始了，會持續一輩子。牠們就是家人。', 28153),
(130794, 'zhTW', '', '恐角龍是吃素的，所以別試著餵牠吃肉！', 28153),
(130793, 'zhTW', '幼龍對於與它們連結的人另眼相看。它為什麼會選擇像你這樣的外地人，絕對是個謎！', '幼龍對於與它們連結的人另眼相看。它為什麼會選擇像你這樣的外地人，絕對是個謎！', 28153),
(130732, 'zhTW', '', '啊…蝙蝠的羅亞，希爾雷克…他一定就在納茲米爾。那個狡猾的羅亞一定知道要怎麼阻止這一切。', 28153),
(130731, 'zhTW', '', '我感覺到他的力量了…就在附近，比其他的羅亞都更靠近。', 28153),
(130730, 'zhTW', '', '死亡的羅亞…伯昂撒姆第。他很強大，但是狡猾又危險…每次跟他打交道都是一場交易。', 28153),
(130710, 'zhTW', '', '青蛙的羅亞，奎格瓦…他在納茲米爾！奎格瓦非常強大，他絕對不會允許鮮血食人妖在此肆虐。', 28153),
(130707, 'zhTW', '也就是說，我們要和代表死亡、烏龜、蝙蝠和青蛙的羅亞打交道…說服他們出手阻止鮮血食人妖。', '', 28153),
(130705, 'zhTW', '', '我們的力量不足以阻止鮮血食人妖。不過我們還有機會，那就是納茲米爾的羅亞。', 28153),
(130692, 'zhTW', '', '<充滿暗示性地…盯著你。>', 28153),
(130625, 'zhTW', '', '塔蘭姬提過，當玩家去尋求被遺忘的羅亞協助時，她要從祖達薩的聯絡人那裡弄來有限的支援。', 28153),
(130566, 'zhTW', '', 'COOL CUTSCENE/FLYOVER. You see the corrupt titan superconstruct! The Blood Matriarch notices you and casts a capturing spell on Talanji!', 28153),
(130494, 'zhTW', '', '自由了！我們必須行動，跳上來！', 28153),
(130490, 'zhTW', '', '更多我的士兵，但路還很長。我們必須繼續前進。', 28153),
(130485, 'zhTW', '', '我們的人…都被殺了！你現在應該明白了。鮮血食人妖都是禽獸！', 28153),
(130383, 'zhTW', '', '洛克漢，你的建議非常好，不過現在該行動了，不能再等下去。一定要阻止那些鮮血食人妖才行。', 28153),
(130372, 'zhTW', '', '要迅捷且致命。祖爾和我會在金字塔的階梯上等你們。你沒法錯過的。', 28153),
(130361, 'zhTW', '', '若你活了下來，與我們在桶列的入口會面。那時我或許會有任務給你。', 28153),
(130353, 'zhTW', '我以前從沒來過贊達拉。祖達薩比我以前能想像的地方都大。$b$b小心點，夥伴。贊達拉人看起來或許言行端正，但他們依然是食人妖。食人妖社會對被視為弱者的人可是毫不留情。', '', 28153),
(130352, 'zhTW', '塔蘭姬公主在這些碼頭的尾端等著你。別遊蕩，而且在死亡之痛儀式舉行以前，別到城市裡去。\n\n你得把會講話的死屍留在這兒直到國王下指示為止。', '', 28153),
(130121, 'zhTW', '', '如你所願。', 28153),
(130120, 'zhTW', '你要為你對庫爾提拉斯犯下的罪接受審判。', '', 28153),
(130119, 'zhTW', '我們會帶你去見凱瑟琳大人。', '', 28153),
(130099, 'zhTW', '<短暫而多話的會面，我要嘲笑祖爾和貶低他；告訴我女兒，她拋棄了她的崗位>', '', 28153),
(130096, 'zhTW', '你應該知道，我們的國王已經避過一百二十三次暗殺行動。$b$b那些失敗刺客的頭現在是王座間的裝飾。', '', 28153),
(130081, 'zhTW', '', '你想見神王？那好，去敲響鑼，我們就會為你進行一場適宜的挑戰。', 28153),
(130079, 'zhTW', '', '帶上你的祝福離開吧，如果你回到這來，你會失去性命。', 28153),
(130075, 'zhTW', '', '老沃金最近怎麼樣啊？我聽說死了，啊，真糟糕。我們有些人都夢想著親手殺死他呢。', 28153),
(130032, 'zhTW', '有話快說，然後滾吧，$r。阿曼尼還沒忘記，是你們部落的人殘害並謀殺了我們敬愛的祖爾金。\n\n基於對贊達拉的尊重，我只給你一個警告：這大使館是阿曼尼的領地，你要是在此逗留，我們就會把你活埋。', '', 28153),
(130031, 'zhTW', '帶著你的祝福離開吧。亞曼尼不歡迎你們部落。', '', 28153),
(130030, 'zhTW', '很勇敢，夥伴。我不認為你明白你要面對什麼事。打敗我身後的每個學徒，你就能帶著我們的祝福離開。', '', 28153),
(130003, 'zhTW', '', '.', 28153),
(129998, 'zhTW', '', '我是珍娜·普勞德摩爾。我想見海軍總帥凱瑟琳‧普勞德摩爾…我的母親。', 28153),
(129993, 'zhTW', '', '總之，試試看吧。', 28153),
(129983, 'zhTW', '啊！不！加茲瑞岡！你這沒心沒肺的部落混帳！來，收下你的祝福然後給我滾。', '', 28153),
(129980, 'zhTW', '你不在的時候很多事都變了，殿下。洛琪拉的實力配不上她的地位，我把她流放到沃魯敦做為處置。', '', 28153),
(129979, 'zhTW', '', '賈克拉傑。戰衛洛琪拉在哪裡？', 28153),
(129978, 'zhTW', '到此為止了，部落的混帳。', '', 28153),
(129969, 'zhTW', '[載入畫面 -> IGC－開放水域上的船隻，珍娜的夢魘，抵達波拉勒斯大門。]', '[載入畫面 -> IGC－開放水域上的船隻，珍娜的夢魘，抵達波拉勒斯大門。]', 28153),
(129968, 'zhTW', '你想要挑戰看看嗎？你該來試試看。敲那面鑼，你就會知道挑戰內容了。', '', 28153),
(129967, 'zhTW', '<發出一項挑戰>', '<發出一項挑戰>', 28153),
(129966, 'zhTW', '哈囉，$r。你的人們過去讓我們受了很多苦難。你想幹嘛？', '', 28153),
(129965, 'zhTW', '聯盟不會忍受這種事！', '聯盟不會忍受這種事！', 28153),
(129964, 'zhTW', '我們的國王會聽聞此事！', '我們的國王會聽聞此事！', 28153),
(129963, 'zhTW', '你這次贏了。', '你這次贏了。', 28153),
(129962, 'zhTW', '你才不能占有這塊土地！', '你才不能占有這塊土地！', 28153),
(129961, 'zhTW', '我們會回來的！', '我們會回來的！', 28153),
(129960, 'zhTW', '我們跟你還沒完呢，$p！', '我們跟你還沒完呢，$p！', 28153),
(129959, 'zhTW', '骯髒的$c！', '骯髒的$c！', 28153),
(129958, 'zhTW', '去死吧！', '去死吧！', 28153),
(129957, 'zhTW', '我一直聽到你的事蹟，$p！殺死你會讓我成為英雄的。', '我一直聽到你的事蹟，$p！殺死你會讓我成為英雄的。', 28153),
(129956, 'zhTW', '沒等到你斷氣，我可是不會走的！', '沒等到你斷氣，我可是不會走的！', 28153),
(129955, 'zhTW', '如果你死了，贊達拉人可不能和你結盟。', '如果你死了，贊達拉人可不能和你結盟。', 28153),
(129954, 'zhTW', '要擺脫我可沒那麼容易！', '要擺脫我可沒那麼容易！', 28153),
(129953, 'zhTW', '部落雜碎！', '部落雜碎！', 28153),
(129952, 'zhTW', '部落人渣別想和贊達拉人結盟。', '部落的人渣決不能與贊達拉人結盟。', 28153),
(129951, 'zhTW', '根據公主的命令，你被驅逐了。離開，或死亡。', '根據公主的命令，你被驅逐了。離開，或死亡。', 28153),
(129950, 'zhTW', '別碰我，部落人渣。', '別碰我，部落人渣。', 28153),
(129949, 'zhTW', '哎呀，祖達薩有部落的人，真有意思。', '哎呀，祖達薩有部落的人，真有意思。', 28153),
(129948, 'zhTW', '你也在找這個嗎？這是我先看到的，而且我要買下來，所以走開吧。', '你也在找這個嗎？這是我先看到的，而且我要買下來，所以走開吧。', 28153),
(129947, 'zhTW', '你要什麼？我很忙。', '你要什麼？我很忙。', 28153),
(129946, 'zhTW', '什麼事，部落人渣？', '什麼事，部落人渣？', 28153),
(129944, 'zhTW', '', '我先把船準備好。勇士，準備好出發時來港口找我。', 28153),
(129940, 'zhTW', '聽著，外來者，我只有一個規定：你要打架去外面打。\n\n只要照做，你就可以在這過夜。\n\n噢，如果你看到違法的事，別檢舉我。', '', 28153),
(129883, 'zhTW', '外來人都不能進入祖達薩，除非我已嘗過他們的血肉！', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(129881, 'zhTW', '走吧，凡人。告訴拉斯塔哈的女兒，我准許你進入城市。', '', 28153),
(129880, 'zhTW', '我想進入這個城市。', '我想進入這個城市。', 28153),
(129879, 'zhTW', '你聞起來很新鮮，而且經過戰火試煉，真是可口的獵物。你為什麼會來到我面前？', '', 28153),
(129660, 'zhTW', '勇士！緊急戰事會議要開始了。你必須立即前來暴風要塞。', '', 28153),
(128197, 'zhTW', '我自深淵歸來！', '', 28153),
(128196, 'zhTW', '我們好像到了！你先去熟悉這座島的地形，我們會把探測器搞定。', '', 28153),
(128195, 'zhTW', '在這裡登陸，苦工們。等等，我聞到人類的臭味。人類，給我聽好，這座島屬於伯格索克！', '', 28153),
(127581, 'zhTW', '哇啊，這種天氣還真是不尋常。看來這些艾澤萊晶岩引起元素領主的注意了。小心一點，不然就殺掉它們。殺就對了！', '', 28153),
(127580, 'zhTW', '', '立刻派人去礦場開採艾澤萊晶岩礦層。', 28153),
(127579, 'zhTW', '$n，我們的斥候發現了幾個含有豐富艾澤萊晶岩的島嶼。我們急需你的船。', '', 28153),
(127578, 'zhTW', '聯盟！這座島是聖光賜給我們的。離開吧，不要自尋死路。這可是最後的警告。', '', 28153),
(127577, 'zhTW', '', '我就喜歡搶寶物，哈哈！多普，看到會動的東西就開火。『賊賊』彼特，把那些聯盟的廢物好好捅一頓。把艾澤萊晶岩拿來給我！', 28153),
(127576, 'zhTW', '嘿，老兄，這裡有些好東西喔。', '', 28153),
(127575, 'zhTW', '', '你的光鑄盟友前來支援了！', 28153),
(127574, 'zhTW', '我們已經拿了不少，呃，部落也來了。你動作可能要快一點了。', '', 28153),
(127573, 'zhTW', '怎麼了嗎？我們已經接到命令，艾澤萊晶岩正等著我們，查看一下桌子，準備好出航時，就告訴我一聲。\n\n我知道，我很帥，大家都常常盯著我，但現在必須集中注意力。', '', 28153),
(127569, 'zhTW', '重新開始目前的島嶼。', '重新開始目前的島嶼。', 28153),
(127568, 'zhTW', '已經裝滿一半了，大家千萬別讓我失望。', '', 28153),
(127501, 'zhTW', '你！救救鬍渣渣！給你很多亮晶晶的東西！', '', 28153),
(126508, 'zhTW', '|cFF0EA6DC+$1i|r|cFFFFFF00艾澤萊晶岩|r', '|cFF0EA6DC+$1i|r|cFFFFFF00艾澤萊晶岩|r', 28153),
(124726, 'zhTW', '破解規則', '破解規則', 28153),
(124724, 'zhTW', '重新遊戲', '重新遊戲', 28153),
(124723, 'zhTW', '開始遊戲', '開始遊戲', 28153),
(124717, 'zhTW', '------------------------------$b最高難度$b------------------------------$b\n當你把手放在上面時，控制台嗡嗡作響。中央面板上閃過永無止盡的層層圖示，多數圖示都伴隨著頭顱或眼睛以「X」表示的臉。這個等級提供額外的時間，但是其中一個延時計時器是地雷偽裝而成。$b$b歡樂的音樂響起。究竟控制台是祝你好運，順利通過最高難度的挑戰？還是在跟你告別呢？', '', 28153),
(124716, 'zhTW', '---------------$b4級$b---------------$b\n控制台回應你熟悉的碰觸，亮起一連串六邊形圖示，播放歡樂的音樂。$b$b很難解讀中央面板上緩慢移動的古代符號，但你知道絕大多數的玩家都在下個難度遭到無情抹殺。$b$b唯一的好處是其中一個六邊形會提供額外的時間。', '', 28153),
(124715, 'zhTW', '---------------$b3級$b---------------$b\n控制台熱烈地歡迎你，但它一直想謀殺你的事實不容忽視。$b$b有關下一級挑戰的圖示似乎指出你即將面對提示更少、時間更短、地雷更多的局面。', '', 28153),
(124714, 'zhTW', '---------------$b2級$b---------------$b\n控制台發出嗶嗶聲，你碰一下就識別出你的身分。規則似乎改變了，上面的圖示指出現在追加計時功能。$b$b如果未能在時限內解開謎題，只會稍作懲罰，不會直接死亡，真棒。', '', 28153),
(124713, 'zhTW', '你盡你所能解讀圖示，並忽視持續不斷的即死警告。$b$b掃地雷控制台會產生六邊形格子，只要一踩上去就會有所反應。多個立邊形格子中都有地雷，玩家一觸即死。相反地，踩在「安全」的格子上，則會顯示數字，指出附近的地雷數。$b$b目標是「掃完」整個地圖，開出所有安全的格子，並利用提供的小白旗標記所有危險的格子。$b$b不清楚為什麼這個遊戲認為有必要謀殺踩錯格子的玩家。', '', 28153),
(124711, 'zhTW', '---------------$b1級$b---------------$b\n你碰一下，這個神秘的秘法控制台便亮起。一頁又一頁的說明顯示在中央面板上。雖然看不懂上面的語言，但可以看圖說故事：$b一大堆頭顱。$b$b這是掃地雷，號稱最危險的遊戲，玩家必須穿越一個秘法礦區，辨識所有佈有地雷的區域，只要稍有差錯，就會立刻死亡。$b$b你不知道為什麼有人會認為這很好玩。', '', 28153),
(124677, 'zhTW', '5級', '', 28153),
(124676, 'zhTW', '4級', '', 28153),
(124675, 'zhTW', '3級', '', 28153),
(124674, 'zhTW', '2級', '', 28153),
(124673, 'zhTW', '1級', '', 28153);
